INSERT INTO `jobs` (`job_id`, `company_id`, `posted_by`, `title`, `description`, `requirements`, `salary_min`, `salary_max`, `location`, `job_type`, `created_at`) VALUES
	(1, 2, 3, 'Senior Java Developer', 'We are looking for a Senior Java Developer to join our dynamic team...', '- 3+ years of Java development experience\n- Strong knowledge of Spring Framework\n- Experience with microservices architecture', 20000000.00, 35000000.00, 'Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2, 3, 4, 'Frontend React Developer', 'Join our frontend team to build amazing user interfaces...', '- 2+ years of React experience\n- Proficient in JavaScript, HTML, CSS\n- Experience with Redux or similar state management', 15000000.00, 25000000.00, 'Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3, 2, 3, 'DevOps Engineer', 'We need a DevOps Engineer to help streamline our deployment processes...', '- Experience with Docker and Kubernetes\n- Knowledge of AWS or Azure\n- CI/CD pipeline experience', 25000000.00, 40000000.00, 'Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(4, 4, 7, 'Nhân Viên Triển Khai Phần Mềm (Thu Nhập 10-15 Triệu)', 'DaMi hiện đang kinh doanh các sản phẩm phần mềm kế toán, hóa đơn điện tử, chữ ký số, kê khai thuế, dịch vụ quản lý hóa đơn, …\nCài đặt, hướng dẫn khách hàng sử dụng phần mềm kế toán SimSoft và các sản phẩm khác của DaMi.\nTriển khai, hỗ trợ khách hàng vận hành, sử dụng tốt các sản phẩm đã mua.', 'Ứng viên tốt nghiệp Đại học chuyên ngành Tài chính – Kế toán hoặc Công nghệ phần mềm.\nCó kinh nghiệm làm việc tối thiểu là 02 năm.\nHiểu biết sâu về nghiệp vụ kế toán và/hoặc lĩnh vực phần mềm ứng dụng.\nLà người cầu tiến, có tinh thần trách nhiệm cao.\nƯu tiên ứng viên đã làm qua công việc tương tự.', 8000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(5, 5, 8, 'Giảng Viên Đào Tạo Ai (Mức Lương Từ 18 - 40 Triệu)', 'Trực tiếp giảng dạy Online và Offline các khóa học về AI theo giáo trình của Learning Chain dành cho học viên;\nThực hiện đào tạo nội bộ định kỳ nhằm nâng cao hiểu biết và hỗ trợ nhân sự áp dụng hiệu quả vào công việc;\nCập nhật và biên soạn nội dung bài giảng, tài liệu học tập phù hợp với trình độ và nhu cầu học viên, xu hướng công nghệ, định hướng chuyển đổi của công ty trong các nhóm cộng đồng và trên các nền tảng để thu hút và phát triển cộng đồng của công ty. \nTạo những nội dung giảng dạy, chia sẻ với nhiều định dạng khác nhau trên các nền tảng Mạng xã hội như Facebook, Zalo, Youtube, X ...\nHỗ trợ giải đáp thắc mắc, theo dõi tiến độ học tập và đánh giá kết quả học viên;\nTham gia tổ chức workshop, event, hội thảo chuyên đề về công nghệ;\nHợp tác với các bộ phận khác để nâng cao chất lượng đào tạo và trải nghiệm học viên.', 'Ít nhất 2 năm kinh nghiệm làm việc (hoặc tìm hiểu) về ngành AI\nCó kiến thức nền tảng vững về lĩnh vực AI.\nCó kinh nghiệm giảng dạy hoặc truyền đạt kiến thức rõ ràng, dễ hiểu cho cộng đồng;\nKỹ năng sư phạm, giao tiếp tốt; sử dụng thành thạo các công cụ giảng dạy online/offline;\nNgoại hình ưa nhìn, hoạt ngôn là một lợi thế;\nƯu tiên ứng viên biết tiếng Anh hoặc tiếng Trung.', 18000000.00, 40000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(6, 5, 8, 'Giảng Viên Đào Tạo Blockchain (Mức Lương Từ 18 - 40 Triệu)', 'Trực tiếp giảng dạy Online và Offline các khóa học về Blockchain, Web3 theo giáo trình của Learning Chain dành cho học viên;\nThực hiện đào tạo nội bộ định kỳ nhằm nâng cao hiểu biết và hỗ trợ nhân sự áp dụng hiệu quả vào công việc;\nCập nhật và biên soạn nội dung bài giảng, tài liệu học tập phù hợp với trình độ và nhu cầu học viên, xu hướng công nghệ, định hướng chuyển đổi của công ty trong các nhóm cộng đồng và trên các nền tảng để thu hút và phát triển cộng đồng của công ty. \nTạo những nội dung giảng dạy, chia sẻ với nhiều định dạng khác nhau trên các nền tảng Mạng xã hội như Facebook, Zalo, Youtube, X ...\nHỗ trợ giải đáp thắc mắc, theo dõi tiến độ học tập và đánh giá kết quả học viên;\nTham gia tổ chức workshop, event, hội thảo chuyên đề về công nghệ;\nHợp tác với các bộ phận khác để nâng cao chất lượng đào tạo và trải nghiệm học viên.', 'Ít nhất 2 năm kinh nghiệm làm việc (hoặc tìm hiểu) về ngành Blockchain \nCó kiến thức nền tảng vững về lĩnh vực Blockchain, Web3 \nCó kinh nghiệm giảng dạy hoặc truyền đạt kiến thức rõ ràng, dễ hiểu cho cộng đồng;\nKỹ năng sư phạm, giao tiếp tốt; sử dụng thành thạo các công cụ giảng dạy online/offline;\nNgoại hình ưa nhìn, hoạt ngôn là một lợi thế;\nƯu tiên ứng viên biết tiếng Anh hoặc tiếng Trung.', 18000000.00, 40000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(7, 6, 9, 'Kỹ Sư Công Nghệ Thông Tin', 'Giám sát lắp đặt, nghiệm thu hệ thống tại công trình.\nKhắc phục sự cố kỹ thuật.', 'Tốt nghiệp Đại học chuyên ngành Điện, Tự động hóa, Công nghệ thông tin.\nKinh nghiệm từ 02 năm trở lên.\nTuổi từ 22–35 tuổi.\nThành thạo PLC Siemens, Mitsubishi, Omron, HMI, SCADA, biến tần.\nCó kinh nghiệm về hệ thống IoT, Smart Home.\nKhả năng đọc bản vẽ điện, nắm vững tiêu chuẩn kỹ thuật (TCVN, PCCC…).\nKỹ năng làm việc độc lập, theo nhóm, chịu áp lực tốt.\nTrung thực, chủ động, trách nhiệm trong công việc.', 15000000.00, 35000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(8, 7, 10, 'Nhân Viên Trực Vận Hành Hệ Thống', 'Trực vận hành hệ thống phần mềm Trung tâm dịch vụ khách hàng 24/7. Kiểm tra xử lý tin báo cháy, kiểm tra xử lý trường hợp mất kết nối thiết bị, gửi báo cáo cho các cơ sở về tình trạng báo cháy của các cơ sở định kỳ tháng/quý/năm.\nTrực tổng đài chăm sóc khách hàng, tổ chức và triển khai xây dựng các kênh thông tin để khách hàng có thể tiếp cận dễ dàng các thông tin về công ty, chủng loại sản phẩm, tính năng, thông số kỹ thuật của sản phẩm, giá bán,... Nhanh chóng, kịp thời tiếp nhận và xử lý thông tin, ý kiến khiếu nại của khách hàng; đồng thời, tổ chức phân tích nguyên nhân, hành động khắc phục phòng ngừa sự cố cho khách hàng.\nĐịnh kỳ hàng tháng báo cáo và gửi các đơn vị liên quan trong Công ty báo cáo tổng hợp, hệ thống hóa các thông tin khiếu nại nhận được từ khách hàng nhằm nâng cao chất lượng sản phẩm, dịch vụ của Công ty.\nCác nhiệm vụ khác liên quan đến công tác chăm sóc khách hàng và các quy định quản trị của Công ty.', 'Trình độ học vấn: Cao đẳng/ Đại học\nChuyên ngành: Các ngành kỹ thuật, công nghệ hoặc các chuyên ngành có liên quan tới mô tả công việc\nKiến thức chuyên môn: Kiến thức về sản phẩm thiết bị công nghiệp; dịch vụ công nghệ thông tin, viễn thông; hệ thống phần mềm; các kiến thức cơ bản về kinh doanh\nTin học: Sử dụng thành thạo các phần mềm Office\nKỹ năng: Kỹ năng làm việc nhóm; đàm phán, thuyết phục; kiểm tra, giám sát; lập kế hoạch; phân tích, tổng hợp, báo cáo\nThái độ/tố chất: Trung thực, thẳng thắn; Khả năng học hỏi; Linh hoạt và thích nghi\nƯu tiên ứng viên có ít nhất 01 năm kinh nghiệm trong lĩnh vực chăm sóc khách hàng', 0.00, 1000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(9, 7, 10, 'Nhân Viên Kinh Doanh (Hồ Chí Minh Và Hà Nội)', 'Tìm kiếm, khai thác và phát triển các mối quan hệ với khách hàng tiềm năng (doanh nghiệp, tổ chức, cá nhân có nhu cầu về hệ thống PCCC và giám sát an ninh).\nTư vấn, giới thiệu các sản phẩm và giải pháp về thiết bị truyền tin báo cháy, hệ thống báo cháy (đầu báo khói, nhiệt, chuông, còi, tủ trung tâm,...) và các loại camera giám sát (IP, Analog, PTZ, Dome, Bullet,...).\nTrực tiếp đàm phán, thương lượng hợp đồng và chốt sales với khách hàng.\nChăm sóc khách hàng hiện có, duy trì và phát triển mối quan hệ tốt đẹp.\nThực hiện các báo cáo kinh doanh định kỳ theo yêu cầu của quản lý.\nCập nhật thông tin thị trường, đối thủ cạnh tranh và xu hướng công nghệ liên quan đến ngành.\nPhối hợp với bộ phận kỹ thuật để hỗ trợ khách hàng trong quá trình triển khai và hậu mãi.\nHoàn thành các chỉ tiêu doanh số được giao.', 'Trình độ học vấn: Tốt nghiệp Cao đẳng/Đại học chuyên ngành Quản trị Kinh doanh, Kinh tế, Kỹ thuật hoặc các ngành liên quan.\nKinh nghiệm: từ 2 năm trở lên\nKỹ năng chuyên môn: đàm phán, báo cáo\nKỹ năng mềm: làm việc theo nhóm, làm việc độc lập\nPhẩm chất: Trung thực, năng động, nhiệt tình, có đạo đức nghề nghiệp.', 0.00, 1000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(10, 8, 11, 'Nhân Viên Kỹ Thuật Sửa Máy Tính - Máy In', '- Biết nhận biết các lỗi cơ bản về phần cứng của máy tính.\n- Thành thạo công việc lắp ráp máy tính, nâng cấp linh kiện. lắp đặt và cài đặt máy in, máy fax.\n- Cài đặt HĐH Windows, macbook, phần mềm ứng dụng, phần mềm đồ họa : photoshop, autocad,corel,3dmax…\n- Sửa chữa thay thế linh kiện máy in, đổ mực máy in: canon, hp, samsung, brother.…', '- Thông thạo đường phố Hà nội.\n- Có phương tiện đi lại (xe máy)\n- Trong công việc cần trung thực , nhanh nhẹn, chịu áp lực công việc cao,Chăm chỉ, sức khỏe tốt.\n- Thành thạo tay nghề, Am hiểu kỹ thuật, năng động, nhiệt tình, ham học hỏi', 10000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(11, 9, 12, 'Devops Engineer', 'Thiết kế, triển khai và quản lý các pipeline CI/CD bằng Azure DevOps.\nTự động hóa việc cung cấp hạ tầng và triển khai hệ thống bằng các công cụ Infrastructure as Code (IaC) như Terraform, ARM templates hoặc Azure CLI.\nGiám sát và tối ưu hóa môi trường Azure để đảm bảo tính sẵn sàng cao, hiệu suất tốt và an toàn bảo mật.\nHợp tác với các nhóm phát triển, QA và IT để tinh gọn quy trình phát triển phần mềm (SDLC).\nKhắc phục và xử lý các sự cố liên quan đến quá trình build, triển khai và hạ tầng hệ thống.\nTriển khai và quản lý hệ thống quản lý phiên bản, chủ yếu sử dụng Git.\nĐảm bảo tuân thủ các tiêu chuẩn ngành và các thông lệ tốt nhất về bảo mật, khả năng mở rộng và độ tin cậy.\nTạo và duy trì tài liệu chi tiết về quy trình, cấu hình và thủ tục.', 'Tốt nghiệp đại học chuyên ngành Khoa học Máy tính, Công nghệ Thông tin hoặc lĩnh vực liên quan (hoặc có kinh nghiệm làm việc tương đương).\nCó kinh nghiệm làm việc ở vị trí Kỹ sư DevOps, tập trung vào dịch vụ đám mây Azure.\nHiểu rõ các nguyên tắc CI/CD và có kinh nghiệm thực tiễn với Azure DevOps pipelines.\nThành thạo các ngôn ngữ lập trình/script như PowerShell, Bash hoặc Python.\nCó kinh nghiệm thực hành với các công cụ IaC như Terraform, ARM templates hoặc Azure Resource Manager.\nCó kinh nghiệm làm việc với công nghệ container hóa và các công cụ điều phối như Docker và Kubernetes.\nQuen thuộc với các hệ thống quản lý mã nguồn, đặc biệt là Git.\nKỹ năng giải quyết vấn đề tốt và có khả năng làm việc nhóm hiệu quả.', 35000000.00, 50000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(12, 10, 13, 'Nhân Viên SEO Website (Thu Nhập Trên 10 Triệu)', '- Lập kế hoạch dự án, triển khai, giám sát, đánh giá hiệu quả SEO theo từng giai đoạn \n- Thực hiện các chiến dịch offpage và onpage\n- Xử lý lỗi xảy ra trong quá trình SEO \n- Phối hợp với bộ phận Content để có các content chất lượng và đảm bảo chiến lược SEO theo từng giai đoạn\n- Nâng hạng từ khóa lên TOP và duy trì thứ hạng của từ khóa trên TOP ổn định\n- Công việc chuyên môn khác theo yêu cầu của Quản lý', '- Bắt buộc Có 2 năm kinh nghiệm quản lý nhóm, kinh nghiệm xây dựng và thực hiện chiến lược SEO tổng thể và chi tiết\n- Ngành học: Các ngành học liên quan tới marketing, công nghệ thông tin, truyền thông… \n- Am hiểu và có kinh nghiệm về SEO website, SEO web thương mại điện tử…\n- Hiểu sâu các kiến thức về onpage - offpage \n- Sử dụng thành thạo các công cụ hỗ trợ SEO như: Google webmaster tool, Analytics,…\n- Đã từng SEO lên top các từ khóa trước đó\n- Có máy tính cá nhân\n- Hiểu biết về HTML, CSS và Javascript…', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(13, 11, 14, 'Nhân Viên Kỹ Thuật - IT', '- Cài đặt/sửa chữa/xử lý các sự cố kỹ thuật phát sinh liên quan lĩnh vực: server, phần mềm, phần cứng, mạng/wifi, hệ thống camera, tổng đài, thiết bị văn phòng (máy tính, máy in….) \n- Thực hiện các công việc liên quan đến CNTT bao gồm các thiết bị âm thanh, nghe nhìn trong các sự kiện, hội họp. \n- Cài đặt, bảo trì các thiết bị và hệ thống CNTT của công ty. \n- Thực hiện các công việc liên quan đến IT khác khi có yêu cầu. \n- Các công việc về kỹ thuật phù hợp khác của bộ phận Kỹ thuật', '- Tốt nghiệp Cao đẳng trở lên các chuyên ngành công nghệ thông tin, công nghệ phần mềm. \n- Có ít nhất 2 năm kinh nghiệm (ưu tiên có kinh nghiệm ở lĩnh vực khách sạn). \n- Có hiểu biết về phần mềm kế toán (misa…), phần mềm khách sạn (là lợi thế) \n- Có khả năng giải quyết vấn đề và ra quyết định tốt. \n- Có khả năng học hỏi và nghiên cứu các công nghệ mới.', 95000000.00, 105000000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(14, 12, 15, 'Digital & Performance Marketing Executive', 'Trực tiếp xây dựng và thực hiện các chiến dịch digital marketing, góp phần thúc đẩy sự phát triển của thương hiệu Kärcher Việt Nam và mang lại doanh số bán hàng bền vững\n1. Quản lý và Tối ưu quảng cáo (Paid Ads) (30%):\nLên kế hoạch, thiết lập, triển khai và tối ưu hóa các chiến dịch quảng cáo trên các nền tảng Facebook (Meta Ads) và Google (Google Ads), bao gồm Search, Display, Shopping, YouTube và Performance Max\nTheo dõi và phân tích hiệu suất các chiến dịch quảng cáo, thực hiện các thử nghiệm A/B testing để cải thiện các chỉ số như CTR, CPC, CVR và ROS.\nKiểm soát và phân bổ ngân sách quảng cáo hiệu quả, đảm bảo đạt được các mục tiêu đã đề ra.\n2. Phối hợp và quản lý SEO Agency (15%):\nPhối hợp với đội ngũ sales/Customer Service để làm việc, theo dõi kết quả leadcard\nTheo dõi, đánh giá và kiểm tra chất lượng công việc của Agency để đảm bảo các chiến dịch SEO được triển khai đúng tiến độ và đạt hiệu quả.\nKiểm tra các báo cáo định kỳ từ Agency và đề xuất các giải pháp cải thiện khi cần.\nNắm vững kiến thức SEO để có thể đưa ra các yêu cầu và phản hồi phù hợp với Agency.\n 3. Hỗ trợ team Sales Online cho các chiến dịch campaign Webshop & các sàn TMĐT (30%):\nPhối hợp chặt chẽ với team Sales Online để xây dựng, triển khai và tối ưu các chiến dịch marketing cho Webshop và các sàn Thương mại điện tử (Tiki, Shopee, Lazada).\nPhân tích dữ liệu và đề xuất các giải pháp nhằm tăng hiệu quả kinh doanh, lượt truy cập và chuyển đổi trên các kênh online.\nCập nhật các chương trình khuyến mãi, các chiến dịch lớn (Mega Campaign) trên sàn và đề xuất các chiến lược truyền thông phù hợp.\n 4. Phân tích và Báo cáo (15%):\nSử dụng các công cụ phân tích như Google Analytics (GA4) để theo dõi hiệu suất website, hành vi người dùng và hiệu quả của các kênh marketing.\nThực hiện các báo cáo định kỳ về hiệu quả hoạt động marketing kỹ thuật số và đề xuất kế hoạch hành động trong tương lai.\n 5. Hỗ trợ các hoạt động Digital khác (10%):\nPhối hợp với team Content và Designer để lên ý tưởng, xây dựng nội dung sáng tạo cho các chiến dịch marketing.\nCập nhật các xu hướng, thuật toán mới nhất trên các nền tảng digital để áp dụng vào công việc\nCác công việc khác theo yêu cầu của Quản lý.', 'Có ít nhất 2 năm kinh nghiệm thực chiến trong lĩnh vực Digital Marketing, đặc biệt là tối ưu quảng cáo trên các kênh Facebook và Google.\nHiểu biết sâu sắc về các công cụ và nền tảng như Google Ads, Meta Business Suite, Google Analytics (GA4).\nCó kiến thức vững chắc về SEO và các công cụ hỗ trợ như Ahrefs, SEMrush, Google Search Console.\nTư duy phân tích dữ liệu tốt, nhạy bén với các con số và có khả năng đưa ra quyết định cải thiện performance chiến dịch dựa trên dữ liệu.\nTinh thần chủ động, trách nhiệm cao và khả năng làm việc độc lập cũng như làm việc nhóm.\nCó khả năng chịu áp lực công việc và mong muốn học hỏi, phát triển bản thân.\nTốt nghiệp Đại học chuyên ngành Marketing, Kinh tế, Truyền thông hoặc các ngành liên quan.', 15000000.00, 16000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(15, 13, 16, 'Nhân Viên IT Full Stack Developer', 'Xây dựng phần mềm theo yêu cầu của khách hàng (Backend, Frontend)\nKiểm tra phần mềm đảm bảo khả năng phản hồi và hiệu quả\nKhắc phục sự cố, gỡ lỗi và nâng cấp phần mềm\nViết tài liệu kỹ thuật (tài liệu thiết kế, hướng dẫn sử dụng…)', 'Có kinh nghiệm tối thiểu 1 năm với vai trò Full Stack Developer hoặc tương tự\nCó kinh nghiệm về một trong các Backend: C#, NodeJS, Python\nCó kinh nghiệm về một trong các Frontend: React, VueJS, HTML, CSS\nCó kinh nghiệm với một trong các Cloud: AWS, Google, Azure Cloud\nCó kinh nghiệm với một trong các databases: MySQL, MongoDB, MSSQL, PostgreSQL\nCó kinh nghiệm xây dựng phần mềm tích hợp AI là một lợi thế\nCó khả năng học hỏi công nghệ mới nhanh chóng, thích nghi với đa dạng yêu cầu khách hàng\nCó kinh nghiệm thực hiện dự án từ đầu là một lợi thế', 10000000.00, 28000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(16, 14, 17, 'Giáo Viên Tin Học', '- Thực hiện công tác giảng dạy theo thời khóa biểu được phân công;\n- Chuẩn bị vật dụng và dụng cụ dạy học theo đúng nguyên tắc của giáo trình, giáo án;\n- Theo dõi tiến độ học tập của học sinh qua hệ thống đào tạo;\n- Cập nhật báo giảng, cập nhật sổ nhật ký phòng máy, ghi điểm học sinh trên hệ thống;\n- Liên hệ và trao đổi chuyên môn và kỹ thuật với chuyên viên quản lý của Trung tâm theo khu vực;\n- Thực hiện công tác kiểm tra, thi học kỳ, điểm số cho học sinh;\n- Báo cáo tình hình thi cử, báo cáo tình hình đăng ký thi của học sinh;\n- Báo cáo định kỳ kế hoạch, tiến độ và kết quả hoạt động giảng dạy môn Tin học tại các trường;\n- Quan sát và quản lý lớp chặt chẽ theo qui định của Trung tâm và Nhà trường;\n- Xây dựng mối quan hệ chặt chẽ, chia sẻ kết nối thông tin cho giáo viên chủ nhiệm và phụ huynh, đồng hành cùng giáo viên chủ nhiệm và phụ huynh trong việc giáo dục học sinh;\n- Thực hiện các công việc khác theo phân công của quản lý trực tiếp.', '- Tốt nghiệp Đại học trở lên chuyên ngành Sư phạm Tin học hoặc các chuyên ngành có liên quan (Công nghệ thông tin, Khoa học máy tính, Kĩ thuật phần mềm, An toàn thông tin...), có Chứng chỉ nghiệp vụ sư phạm (nếu chuyên ngành tốt nghiệp không thuộc khối ngành Sư phạm);\n- Có chứng chỉ IC3/ICDL/MOS;\n- Có kinh nghiệm giảng dạy Tin học quốc tế từ 1 năm trở lên;\n- Tâm huyết với nghề nghiệp và có phẩm chất đạo đức tốt; \n- Lập kế hoạch bài học và tổ chức nội dung giảng dạy một cách khoa học;\n- Phối hợp và hòa đồng, thân thiện cởi mở với đồng nghiệp;\n- Lắng nghe và phản hồi tích cực đến học sinh;\n- Tuổi: Từ 24 trở lên.', 12000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(17, 15, 18, 'Trưởng Nhóm Tự Động Hóa (Plc / Robot)', 'Weldcom tuyển 02 trưởng nhóm tự động hóa (PLC/ Robot), làm việc tại Trụ sở chính: Số 285A Ngô Gia Tự, Long Biên:\n\n- Tiếp nhận và thiết kế giải pháp kỹ thuật cho các dự án mới\n- Hỗ trợ & quản lý dự án về giải pháp robot, chế tạo máy, điều khiển tự động, PLC\n- Kết hợp với các bộ phận khác trong công ty để làm Giải pháp và đảm bảo dự án đúng tiến độ khi triển khai\n- Lập thời gian biểu cho các công việc cụ thể\n- Quản lý tiến độ dự án, điều phối và giám sát nhà thầu phụ\n- Kiểm tra đánh giá và xử lý các sự cố kỹ thuật liên quan đến hệ thống tự động hóa.', '- Số năm kinh nghiệm: Tối thiểu 3 năm ở công việc tương đương\n- Kỹ sư tốt nghiệp từ cao đẳng trở lên các chuyên ngành liên quan đến cơ khí,Tự Động Hóa, Cơ Điện Tử, Điện tử công nghiệp\n- Có kinh nghiệm hoặc hiểu biết về Robot, PLC, HMI, Cảm biến, Machine Vision, Hệ thống SCADA\n- Yêu cầu khác : Hiểu biết về việc sử dụng khí nén và thủy lực, có khả năng làm việc theo nhóm.', 25000000.00, 35000000.00, 'Hà Nội,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(18, 16, 19, 'Quản Lý Dự Án Triển Khai Phần Mềm Erp – CRM – Scm – Mes', 'Bạn sẽ là người chịu trách nhiệm toàn diện trong việc triển khai các dự án phần mềm quản trị doanh nghiệp (ERP/CRM/SCM/MES), đảm bảo đúng tiến độ – đúng ngân sách – đúng chất lượng và đạt sự hài lòng cao nhất từ phía khách hàng.\nNhiệm vụ chính:\nLập kế hoạch, quản lý tiến độ và giám sát toàn bộ vòng đời dự án.\nLà đầu mối liên hệ với khách hàng, quản lý kỳ vọng và giải quyết vấn đề phát sinh\nĐiều phối đội ngũ tư vấn nghiệp vụ, kỹ thuật viên, lập trình viên, kiểm thử.\nQuản lý rủi ro và đảm bảo chất lượng triển khai.\nLập báo cáo tiến độ, tài liệu dự án và phối hợp chặt chẽ với Ban Giám đốc.', 'Tốt nghiệp ĐH chuyên ngành: Hệ thống thông tin, Quản trị kinh doanh, Kế toán – Tài chính…\n3–5 năm kinh nghiệm triển khai phần mềm ERP/CRM/SCM/MES, trong đó có vai trò Quản lý Dự án.\nCó hiểu biết tổng quan về nghiệp vụ doanh nghiệp: tài chính, sản xuất, mua bán hàng, kho, nhân sự...\nThành thạo các phương pháp quản lý dự án: PMBOK, Agile/Scrum. Có chứng chỉ PMP/Prince2/CSM là lợi thế.\nKỹ năng lãnh đạo, phân tích, thuyết trình và giao tiếp với khách hàng xuất sắc.\nThành thạo công cụ: Jira, Microsoft Project, Asana, v.v.\nƯu tiên ứng viên từng làm với các hệ thống như SAP, Oracle, Dynamics, Bravo, Odoo, Misa Amis...', 20000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(19, 17, 20, 'Giảng Viên Cơ Hữu Khoa Công Nghệ Thông Tin', 'Tham gia giảng dạy đại học các học phần thuộc ngành Công nghệ thông tin (công      nghệ phần mềm, an ninh mạng, thiết kế đồ hoạ,…).\nTham gia nghiên cứu khoa học, hoạt động phát triển chuyên môn, phát triển và tham gia chương trình đào tạo và hợp tác quốc tế.\nTham gia tổ chức các hoạt động ngoại khoá cho sinh viên và hoạt động phục vụ cộng đồng.\nTham gia công tác tuyển sinh và các hoạt động khác theo yêu cầu của Nhà trường.\nThực hiện các công việc khác theo phân công của Lãnh đạo.', 'Tốt nghiệp Thạc sĩ/Tiến sĩ đúng chuyên ngành từ các trường ĐH uy tín trong và ngoài nước.\nCó ít nhất 02 năm kinh nghiệm làm việc tại các doanh nghiệp uy tín.\nCó kỹ năng sư phạm, kiến thức chuyên môn tốt, có khả năng giảng dạy lý thuyết và thực hành.\nKhả năng giao tiếp tốt, yêu thích việc giảng dạy, tinh thần trách nhiệm và nhiệt huyết với nghề.\nTiếng Anh giao tiếp tốt (TOEIC 600 trở lên hoặc chứng chỉ quốc tế tương đương).', 0.00, 1000.00, 'Đắk Lắk,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(20, 16, 19, 'Trưởng Nhóm Tư Vấn Triển Khai Phần Mềm Erp – Tài Chính Kế Toán', 'Bạn sẽ là người dẫn dắt đội ngũ tư vấn nghiệp vụ ERP phân hệ Tài chính – Kế toán, tham gia trực tiếp vào các dự án triển khai phần mềm ERP tại các doanh nghiệp vừa và lớn\nCông việc chính:\nPhân tích yêu cầu nghiệp vụ tài chính – kế toán từ khách hàng.\nThiết kế và cấu hình hệ thống ERP theo chuẩn mực kế toán Việt Nam (VAS), luật thuế.\nĐiều phối nhóm tư vấn triển khai, kiểm soát chất lượng, tiến độ dự án.\nĐào tạo, chuyển giao hệ thống và hỗ trợ sau triển khai.\nTư vấn cải tiến quy trình kế toán – tài chính cho doanh nghiệp.', 'Tốt nghiệp Đại học các ngành: Kế toán, Tài chính, Kiểm toán, Hệ thống thông tin quản lý...\nTừ 5–7 năm kinh nghiệm triển khai ERP, trong đó có ít nhất 2 năm quản lý nhóm tư vấn ERP.\nAm hiểu sâu về chuẩn mực kế toán Việt Nam, quy định thuế (GTGT, TNDN, TNCN…).\nTừng triển khai SAP, Oracle, Microsoft Dynamics, hoặc các hệ thống ERP lớn tại Việt Nam là lợi thế lớn.\nKỹ năng lãnh đạo, giao tiếp – tư vấn tốt, làm việc độc lập và đội nhóm hiệu quả\nƯu tiên ứng viên có chứng chỉ Kế toán trưởng, CPA, ACCA.', 20000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(21, 18, 21, 'Chuyên Viên Triển Khai Dự Án', 'Kiểm thử & Đảm bảo chất lượng:\nXây dựng kịch bản và thực hiện kiểm thử toàn diện các hệ thống, ứng dụng.\nLàm việc trực tiếp với người dùng cuối để hỗ trợ, phát hiện và tìm nguyên nhân phát sinh lỗi.\nGhi nhận lỗi (bug report), phối hợp chặt chẽ với đội ngũ phát triển để theo dõi và xác nhận việc sửa lỗi.\nQuản lý Triển khai:\nTheo dõi tiến độ, xác định các rủi ro tiềm ẩn và báo cáo tình hình triển khai định kỳ cho quản lý.\nPhối hợp với các phòng ban, đối tác để đảm bảo các nguồn lực và yêu cầu được đáp ứng đúng thời hạn.\nThực hiện cài đặt, cấu hình các hệ thống trên hệ thống nội bộ hoặc phần mềm của bên thứ 3.\nLàm việc với các đối tác thứ ba (Bokun, Trip, Google...) để tích hợp và kết nối hệ thống.\nĐào tạo & Hỗ trợ Chuyển giao:\nSoạn thảo tài liệu hướng dẫn, quy trình vận hành hệ thống.\nTổ chức và thực hiện đào tạo cho người dùng cuối (tài xế, nhân viên nội bộ, đối tác, khách hàng).\nCung cấp hỗ trợ kỹ thuật ban đầu cho người dùng sau khi hệ thống đi vào hoạt động.\nTối ưu hóa & Cải tiến:\nPhân tích các quy trình vận hành, vẽ lại luồng thao tác để đề xuất các giải pháp cải tiến.\nThu thập phản hồi từ người dùng để cải tiến sản phẩm và quy trình triển khai.\nTrích xuất dữ liệu và tạo các báo cáo phân tích hiệu quả vận hành theo yêu cầu.\nThực hiện các nhiệm vụ được phân công từ Quản lý trực tiếp hoặc BoD.', 'Kinh nghiệm: Có ít nhất 02 năm kinh nghiệm ở các vị trí tương đương như Triển khai phần mềm, Kiểm thử phần mềm (Tester/QA), Hỗ trợ kỹ thuật (IT Support).\nChuyên môn: Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ Thông tin, Hệ thống Thông tin hoặc các ngành liên quan.\nKiến thức & Kỹ năng:\nCó hiểu biết về quy trình triển khai và kiểm thử phần mềm (SDLC).\nKỹ năng giải quyết vấn đề kỹ thuật tốt, tư duy logic.\nKỹ năng giao tiếp, trình bày và đào tạo rõ ràng, hiệu quả.\nGiao tiếp tốt bằng tiếng Anh\nCó kiến thức về lập trình, làm việc với CSDL là một lợi thế.\nCó kinh nghiệm sử dụng các công cụ quản lý công việc như Trello, Jira là một lợi thế.\nChủ động, cẩn thận, có tinh thần trách nhiệm cao.', 15000000.00, 20000000.00, 'Đà Nẵng,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(22, 19, 22, 'Chuyên Viên Nghiên Cứu Ứng Dụng Ai / Ai Application Specialist', 'Quản trị viên Website (30%)\n- Quản trị viên vận hành hệ thống website của công ty \n- Kiểm tra, tối ưu tốc độ tải trang, cấu trúc website, và đảm bảo website hoạt động ổn định.\n- Cập nhật nội dung trang web: banner, sản phẩm, tin tức, thông tin khuyến mãi...\n- Phối hợp với bộ phận thiết kế và marketing để tối ưu trải nghiệm người dùng, giao diện thân thiện và phù hợp hành vi khách hàng mục tiêu.\nNghiên cứu, ứng dụng công nghệ AI/chuyển đổi số (70%)\n- Phân tích, nghiên cứu, đánh giá và phối hợp với các bộ phận liên quan xây dựng và phát triển các dự án chuyển đổi số cho các bộ phận.\n- Nghiên cứu các xu hướng công nghệ, chủ động tư vấn, cung cấp hoặc đề xuất các sáng kiến, cải tiến, đổi mới số, công nghệ/giải pháp mới áp dụng cho nghiệp vụ của các bộ phận - trong công ty.\n- Đào tạo và hướng dẫn lại cho nhân viên các phòng ban.\n- Đề xuất các công cụ AI mới phù hợp công ty (trợ lý email, tóm tắt họp, chatbot, tự động báo cáo...).\n- Tham gia phát triển các sản phẩm AI phục vụ nội bộ hoặc tích hợp AI cho các hệ thống.', 'Kinh nghiệm thực tế Đã từng sử dụng Chat GPT hoặc công cụ AI (Notion AI, Claude, Gemini, Copilot...) để xử lý công việc hành chính, kế toán, marketing, nhân sự, v.v.\nTư duy ứng dụng: Có khả năng nhìn thấy các bài toán thực tế trong từng phòng ban và đề xuất cách áp dụng AI để cải tiến.\nKỹ năng viết prompt: Biết cách viết prompt tối ưu theo nghiệp vụ, có thư viện prompt mẫu là một lợi thế.\nKỹ năng công cụ văn phòng & AI: Thành thạo Google Workspace hoặc Microsoft 365, biết cách kết hợp AI với Excel, Word, PowerPoint, Notion, Canva…\nCó kinh nghiệm làm việc ở phòng R&D, chuyển đổi số, hoặc từng làm training nội bộ.\nCó hiểu biết cơ bản về quản trị doanh nghiệp và quy trình các phòng ban.\nƯu tiên ứng viên từng làm việc tại các công ty startup, công ty quy mô nhỏ-vừa.\nỨng viên có laptop cá nhân.', 10000000.00, 14000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(23, 20, 23, 'Nhân Viên Kinh Doanh Phần Mềm (Pos)', '- Thời gian làm việc: 8h - 17h. Thứ 2 - Thứ 7 (hàng tuần)\n- Lương cơ bản + phụ cấp: 7.300.000. Thu nhập 14M ++\n Tìm kiếm, tiếp cận và tư vấn giải pháp phần mềm quản lý bán hàng LitePOS đến các hộ kinh doanh, cửa hàng bán lẻ, nhà hàng – quán ăn – café, cửa hàng thời trang, mini mart, hiệu thuốc,…\nHỗ trợ cài đặt, hướng dẫn sử dụng phần mềm và chăm sóc khách hàng sau bán.\nTư vấn trực tiếp, đi thị trường hoặc online tùy mô hình\nBáo cáo tiến độ và kết quả kinh doanh hàng ngày/tuần/tháng.\nWebsite: https://vinshop.VN/', 'Ưu tiên ứng viên có kinh nghiệm Sales Fintech, phần mềm bán hàng (KiotViet, Eco, VNPay, iPOS, Sapo,..)\nCó khả năng giao tiếp, thương lượng & xử lý vấn đề tốt.\nHiểu biết về các quy trình tư vấn, cài đặt, hỗ trợ khách hàng.\nCó khả năng làm việc độc lập và làm việc nhóm hiệu quả.\nKhả năng giải quyết vấn đề nhanh chóng và hiệu quả, chăm sóc khách hàng tốt.', 8000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(24, 15, 18, 'Kỹ Sư Plc / Robot', 'Weldcom tuyển 05 Kỹ sư tự động hóa - PLC - Robot , làm việc tại Trụ sở chính: Số 285A Ngô Gia Tự, Long Biên \n\n- Tiếp nhận và thiết kế giải pháp kỹ thuật cho các dự án mới\n- Hỗ trợ & quản lý dự án về giải pháp robot, chế tạo máy, điều khiển tự động, PLC\n- Kết hợp với các bộ phận khác trong công ty để làm Giải pháp và đảm bảo dự án đúng tiến độ khi triển khai\n- Lập thời gian biểu cho các công việc cụ thể\n- Quản lý tiến độ dự án, điều phối và giám sát nhà thầu phụ\n- Kiểm tra đánh giá và xử lý các sự cố kỹ thuật liên quan đến hệ thống tự động hóa.', '- Số năm kinh nghiệm: Tối thiểu 2 năm ở công việc tương đương\n- Kỹ sư tốt nghiệp từ cao đẳng trở lên các chuyên ngành liên quan đến cơ khí,Tự Động Hóa, Cơ Điện Tử, Điện tử công nghiệp\n- Có kinh nghiệm hoặc hiểu biết về Robot, PLC, HMI, Cảm biến, Machine Vision, Hệ thống SCADA\n- Yêu cầu khác : Hiểu biết về việc sử dụng khí nén và thủy lực, có khả năng làm việc theo nhóm.', 15000000.00, 25000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(25, 21, 24, 'Nhân Viên IT Quản Trị Mạng', '- IT Support đảm bảo hoạt động cho máy tính, máy in, các thiết bị IT. \n- Quản lý, kiểm soát, cài đặt các phần mềm kỹ thuật, máy móc của công ty. \n- Quản lý Website, Domain , WebHosting, Email Hosting. \n- Phụ trách an toàn bảo mật thông tin. \n- Lên kế hoạch bảo trì, nâng cấp hệ thống, thiết bị định kỳ. \n- Khôi phục dữ liệu cho người dùng khi có sự cố.', '- Tốt nghiệp cao đẳng, chuyên ngành Công nghệ thông tin \n- Ưu tiên ứng viên có kinh nghiệm \n- Có trách nhiệm trong công việc, năng động và nhanh nhẹn.', 5000000.00, 7000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(26, 22, 25, 'Chuyên Viên Digital Marketing (Performance)', 'Quản lý và tối ưu chiến dịch quảng cáo số\nVận hành quảng cáo: Trực tiếp lên kế hoạch, triển khai và quản lý các chiến dịch quảng cáo trên các nền tảng:\nTối ưu hiệu suất: Liên tục theo dõi, phân tích và tối ưu các chỉ số quảng cáo (CPM, CPC, CTR, CPA, ROAS,...) để tối đa hóa hiệu quả và giảm thiểu chi phí.\nNghiên cứu và phát triển: Cập nhật các thuật toán, xu hướng và công cụ quảng cáo mới, đề xuất và thử nghiệm các chiến thuật (tactics) để nâng cao hiệu suất.\nVận hành và báo cáo E-commerce\nQuản lý sàn thương mại điện tử: Vận hành và tối ưu gian hàng trên cả các sàn thương mại điện tử nội địa (Shopee, Lazada, TikTok Shop) và quốc tế (Amazon, Alibaba).\nBáo cáo và phân tích: Theo dõi và báo cáo định kỳ về hiệu suất hoạt động của gian hàng, đề xuất các phương án tối ưu để tăng trưởng doanh số. Cụ thể, phân tích hiệu quả các chiến dịch quảng cáo trên sàn, quản lý kho hàng và các chương trình khuyến mãi.\nBáo cáo và phân tích dữ liệu\nĐo lường và báo cáo: Thu thập, phân tích dữ liệu và lập báo cáo chi tiết về hiệu quả các chiến dịch marketing theo tháng/quý.\nPhân tích chiến lược: Dựa trên dữ liệu, đưa ra các nhận định và đề xuất các chiến lược để cải thiện hiệu quả kinh doanh trong các kỳ tiếp theo.', 'Có ít nhất 1-2 năm kinh nghiệm thực chiến trong lĩnh vực Digital Marketing Performance.\nNắm vững các công cụ và nền tảng quảng cáo: Facebook Ads, Google Ads, TikTok Ads,...\nƯu tiên đã có kinh nghiệm vận hành và tối ưu gian hàng trên các sàn thương mại điện tử nội địa (Shopee, Lazada, TikTok Shop) và/hoặc quốc tế (Amazon, Alibaba) là một lợi thế lớn.\nKhả năng phân tích dữ liệu tốt, thành thạo các công cụ như Google Analytics, Google Tag Manager và các công cụ báo cáo khác.\nCó tư duy phân tích, logic và khả năng giải quyết vấn đề hiệu quả.\nTinh thần chủ động, trách nhiệm cao và khả năng làm việc độc lập cũng như làm việc nhóm.\nTiếng Anh tốt là một lợi thế, đặc biệt trong việc vận hành các sàn quốc tế và nghiên cứu tài liệu.', 1000000.00, 7000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(27, 23, 26, 'Nhân Viên Kỹ Thuật Nạp Mực Máy In', 'Nạp mực máy in\nSửa chữa và khắc phục sự cố các thiết bị văn phòng\nChi tiết công việc sẽ trao đổi khi phỏng vấn.', 'Siêng năng ,trung thực,có trách nhiệm với công việc….\nBiết cấp mực là được\nXử lý thành thạo các sự cố máy tính\nCó trách nhiệm với công việc, làm việc nghiêm túc, nhanh nhẹn, nhiệt tình, gắn bó lâu dài', 10000000.00, 13000000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(28, 24, 27, 'Nhân Viên IT', '- Quản trị hệ thống mạng nội bộ của công ty.\n- Xử lý các sự cố liên quan đến máy tính, phần mềm, thiết bị mạng, đường truyền trong công ty\n- Cài đặt hệ điều hành, các phần mềm ứng dụng và thiết bị công nghệ thông tin\n- Hỗ trợ xử lý các vấn đề về mạng, hệ thống camera, máy chấm công, máy in, fax, điện thoại, wifi…\n- Tham gia xây dựng và đề xuất các giải pháp, phối hợp triển khai các dự án CNTT đang vận hành\n- Thực hiện các nhiệm vụ khác theo yêu cầu của người phụ trách', '- Tốt nghiệp Đại Học chuyên ngành Công nghệ thông tin, mạng máy tính & an ninh mạng hoặc có liên quan\n- Có kiến thức và kinh nghiệm về công nghệ thông tin, hệ thống mạng, phần mềm, phần cứng máy tính, cơ sở dữ liệu và các công nghệ mới nhất\n- Từ 02 năm kinh nghiệm về hỗ trợ người dùng Support/Helpdesk\n- Có kiến thức và kinh nghiệm về Window Server, Microsoft SQL, phần cứng máy tính\n- Nắm vững kiến thức TCP/IP , đọc hiểu tài liệu.\n- Có chứng chỉ MCSA, CCNA là lợi thế.', 12000000.00, 175000000.00, 'Long An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(29, 25, 28, '[Hà Nam] Chuyên Viên Công Nghệ Thông Tin', '- Kiểm tra sự hoạt động của các thiết bị IT tại nhà máy (Máy chủ vật lý, cửa từ, loa thông báo, giám sát môi, hệ thống báo cháy, máy lạnh). Nếu có hiện tượng bất thường báo ngay cho những người phụ trách chuyên môn của IT để tiến hành xử lý.\n - Phối hợp với các bên liên quan thực hiện triển khai bảo trì, xử lý các lỗi Camera bị mất tín hiệu, lỗi cáp quang, lỗi phần mềm view Camera và thực hiện việc di chuyển & thay đổi vị trí camera theo yêu cầu của ban quản lý nhà máy \n- Phối hợp thực hiện khắc phục sự cố liên quan đến mạng, máy móc thiết bị IT tại khu vực Trạm cân \n- Triển khai, thực hiện các chính sách quy trình, quy định và giải pháp về phòng ngừa các rủi ro CNTT, đảm bảo ngăn ngừa các rủi ro và các sự cố an toàn CNTT. Tham gia các bước diễn tập khôi phục hệ thống IT quan trọng trong nội bộ khối ICS hàng quý \n- Triển khai các chương trình nhằm nâng cao chất lượng hỗ trợ người dùng theo tiêu chuẩn dịch vụ của công ty: Tiếp nhận, kiểm tra sự hợp lệ và mức độ ưu tiên các yêu cầu dịch vụ ICS nhằm đảm bảo yêu cầu theo quy định và đầy đủ thông tin \n- Xử lý và đào tạo khắc phục các sự cố liên quan đến hệ thống CNTT trong công ty cho người dùng nhằm đảm bảo các sự cố được xử lý kịp thời và ngăn ngừa tái diễn', 'Đại học/Cao đẳng chuyên ngành công nghệ thông tin', 18000000.00, 21000000.00, 'Hà Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(30, 26, 29, 'Golang Developer', 'Key Responsibilities\n- Design, implement, and maintain robust RESTful and gRPC APIs using Golang\n- Architect modular, extensible microservices using design patterns and clean architecture principles\n- Optimize backend logic and services using efficient data structures and algorithms\n- Integrate with MongoDB and PostgreSQL databases for transactional and analytical workloads\n- Containerize and orchestrate services with Docker and Kubernetes\n- Leverage AWS cloud services (e.g., EKS, RDS, S3, Lambda, SQS) for building distributed systems\n- Participate in performance tuning, profiling, and production troubleshooting\n- Use AI developer agents/tools (e.g., GitHub Copilot, ChatGPT) to enhance productivity and automation\n- Collaborate across teams to ensure CI/CD pipelines, observability, and quality standards are met', 'Required Skills\n- 3+ years of experience in backend development with Golang\n- Proficiency in building and consuming RESTful and gRPC APIs\n- Strong grasp of data structures, algorithms, and design patterns\n- Hands-on experience with MongoDB and PostgreSQL\n- Proficient in containerization using Docker and orchestration with Kubernetes\n- Working knowledge of AWS services and best practices for scalable infrastructure\n- Experience with code quality practices (testing, linting, reviews, version control)\n- Familiarity with API security practices (OAuth2, JWT)\nPreferred / ADD-on Skills (Nice to Have)\n- Experience with Apache Airflow, Kubeflow, or similar MLOps tools\n- Working knowledge of Python for scripting or pipeline components\n- Familiarity with event-driven architecture (Kafka, NATS, RabbitMQ)\n- Exposure to AI-powered developer tools/agents (Copilot, Cody, ChatGPT workflows)\n- Understanding of service mesh/API gateway concepts (Istio, Envoy, Kong)\n- Experience with Infrastructure-as-Code tools (Terraform, Helm)\nEducation & Experience\n- Bachelor’s degree in Computer Science, Software Engineering\n- Strong engineering background with a proven track record of designing and shipping production-grade backend systems', 15000000.00, 30000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(31, 27, 30, 'Giáo Viên Ngành Vẽ, Thiết Kế Kỹ Thuật Số - Digital Painting', 'Phụ trách giảng dạy các môn thuộc chuyên ngành Vẽ kỹ thuật số (Digital Painting) như Vẽ cơ bản, Vẽ kỹ thuật số, Vẽ nhân vật, Vẽ minh họa, Màu Sắc, Semi-real Art, Workshop màu, Concept Art ...  của lớp Họa sĩ kể chuyện tại CMA.\nXây dựng lộ trình giảng dạy phù hợp với mục tiêu và luôn cập nhật xu hướng mới của ngành. \nBiên soạn giáo án theo giáo trình cũng như tài liệu của CMA.\nTheo dõi, cập nhật và đánh kết quả học tập của học viên đồng thời hướng dẫn học viên trong các kỳ sáng tác hoặc đồ án cuối khóa.\nTham gia các hoạt động học thuật, cuộc họp chuyên môn và các sự kiện khác liên quan.\n*** Chi tiết liên hệ: 0902738806 để trao đổi thêm', 'Tốt nghiệp đại học trở lên các chuyên ngành liên quan đến Mỹ thuật, Digital Art, Illustration hoặc có kỹ năng chuyên môn vẽ Digital Painting.\nCó ít nhất 2 năm kinh nghiệm giảng dạy hoặc kinh nghiệm thực tiễn trong ngành như Game Art, Concept Art, Illustration, v.v. \nThành thạo phần mềm \nCó kỹ năng truyền đạt, nghiên cứu giảng dạy là một lợi thế.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(32, 28, 31, 'Technical Sales', 'Thực hiện kế hoạch kinh doanh được giao theo quy trình của Công ty hàng tháng, quý, năm;\nTư vấn và đề xuất các giải pháp/sản phẩm/dịch vụ cho khách hàng doanh nghiệp không giới hạn trong phạm vi sản phẩm, dịch vụ sau đây:\nThường xuyên tiếp cận và tạo mối quan hệ với khách hàng;\nTìm kiếm khách hàng tiềm năng và mở rộng danh sách khách hàng;\nTrao đổi, đám phán, ký kết hợp đồng;\nGiám sát chất lượng dịch vụ, giải quyết khiếu nại, và đánh giá sự hài lòng của khách hàng sử dụng sản phẩm/dịch vụ của Công ty;\nThực hiện các chương trình chăm sóc khách hàng theo quy định của Công ty;\nThực hiện các thủ tục giấy tờ liên quan đến khách hàng phụ trách;\nThực hiện các công việc khác theo phân công của cấp trên.', 'Nam/Nữ, dưới 30 tuổi\nTốt nghiệp Đại Học/Cao Đẳng, ưu tiên chuyên ngành Công nghệ thông tin, Quản trị kinh doanh hoặc Ngôn ngữ Anh\nNgoại ngữ: tiếng Anh (ưu tiên nhưng không bắt buộc)\nTin học: MS Office cấp độ cao, CRM\nTối thiểu 01 năm kinh doanh dịch vụ tương đương\nChăm chỉ, ý thức kỷ luật cao, cầu tiến', 7000000.00, 20000000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(33, 29, 32, 'IT System Leader', '1. Mục tiêu công việc \nQuản trị hệ thống chịu trách nhiệm duy trì và quản lý các hệ thống công nghệ thông tin của công ty, đảm bảo hoạt động liên tục và an toàn. Điều này bao gồm việc cài đặt, cấu hình, nâng cấp và duy trì phần cứng và phần mềm, cũng như giám sát hiệu suất và giải quyết các sự cố kỹ thuật. \n2. Mô tả công việc \nQuản lý Hệ thống:  \nCài đặt, cấu hình và duy trì các hệ thống máy chủ và mạng.  \nĐảm bảo các hệ thống luôn hoạt động ổn định, an toàn và hiệu suất cao.  \nBảo mật:  \nThực hiện các biện pháp bảo mật để bảo vệ hệ thống và dữ liệu của công ty.  \nĐánh giá và phát hiện lỗ hổng bảo mật, đề xuất các giải pháp khắc phục.  \nHỗ trợ Kỹ thuật:  \nCung cấp hỗ trợ kỹ thuật cho nhân viên trong công ty.  \nGiải quyết nhanh chóng các vấn đề phát sinh liên quan đến hệ thống.  \nQuản lý Dữ liệu:  \nQuản lý sao lưu dữ liệu và khôi phục dữ liệu khi cần thiết.  \nĐảm bảo tính toàn vẹn và bảo mật của dữ liệu.', 'Tuổi từ 32 đổ lên\nTốt nghiệp Đại học chuyên ngành Công nghệ Thông tin hoặc liên quan.  \nÍt nhất 5 năm kinh nghiệm làm việc trong lĩnh vực quản trị hệ thống.  \nKinh nghiệm dùng Microsoft Office 365\nHiểu biết sâu về hệ điều hành Windows/Linux và các công nghệ mạng.  \nHiểu biết sâu về công nghệ triển khai các máy chủ ảo hoá VMWARE/HYPERV và các công nghệ ảo hoá khác.  \nKỹ năng giải quyết vấn đề và tư duy logic tốt.  \nKỹ năng giao tiếp tốt, khả năng làm việc nhóm và độc lập', 20000000.00, 22000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(34, 30, 33, 'Nhân Viên Marketing Và Truyền Thông', '• Lên kế hoạch và triển khai các chiến dịch marketing theo tháng/quý phù hợp với lịch chạy tour và chương trình khuyến mãi.\n• Quản lý, sáng tạo nội dung và đăng bài trên các kênh Facebook, Instagram, TikTok, Zalo OA, Website.\n• Chụp ảnh, quay và biên tập video về tour, trải nghiệm khách hàng, cảnh đẹp Hạ Long – Lan Hạ.\n• Thiết kế cơ bản các ấn phẩm truyền thông: banner, poster, brochure, infographics.\n• Viết bài PR, thông cáo báo chí khi có sự kiện hoặc sản phẩm mới.\n• Triển khai và theo dõi quảng cáo Facebook Ads, Google Ads (nếu có).\n• Kết nối và làm việc với KOLs, Travel Blogger, đơn vị báo chí, đại lý du lịch để quảng bá thương hiệu.\n• Hỗ trợ truyền thông cho các sự kiện trên tàu: tiệc, hội nghị, sinh nhật, chụp ảnh khách.\n• Theo dõi, thống kê hiệu quả marketing và báo cáo định kỳ cho quản lý.', '• Tốt nghiệp chuyên ngành Marketing, Truyền thông\n• Có khả năng viết nội dung sáng tạo, chụp ảnh và quay dựng video cơ bản.\n• Sử dụng được các phần mềm thiết kế cơ bản (Canva, Photoshop cơ bản).\n• Biết chạy quảng cáo Facebook/Google.\n• Năng động, giao tiếp tốt, yêu thích du lịch và dịch vụ khách hàng.\n• Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực du lịch, lữ hành hoặc du thuyền.', 15000000.00, 22000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(35, 31, 34, 'Kỹ Sư Ứng Dụng CNTT', 'Kỹ sư ứng dụng CNTT chịu trách nhiệm chính trong việc phát triển, triển khai và quản trị các hệ thống ứng dụng theo phân công của trưởng phòng CNTT.\nHỗ trợ và đào tạo người dùng cuối sử dụng hệ thống ứng dụng.\nLàm việc chặt chẽ với khách hàng, nhà cung cấp để xử lý các sự cố và yêu cầu phát sinh trong quá trình vận hành.\nTham gia phát triển và triển khai các ứng dụng kinh doanh của công ty. Triển khai cho khách hàng.\nHỗ trợ giám sát, vận hành hệ thống theo thực tế khai thác của đơn vị.\nThực hiện các công việc khác theo yêu cầu của Trưởng phòng CNTT.\nBáo cáo công việc cho Trưởng phòng CNTT.', 'Có kiến thức về các ngôn ngữ như PHP, .NET, Java, ASP, JavaScript, v.v.\nCó kiến thức và kinh nghiệm với các hệ điều hành Windows, Linux, UNIX, Centos, và các máy chủ web như IIS, Apache, Tomcat.\nCó kiến thức và kinh nghiệm trong việc cài đặt, quản lý và xử lý sự cố các hệ quản trị cơ sở dữ liệu như: My SQL, Microsoft SQL Server, Oracle, IBM DB2, PostgreSQL.\nCó kinh nghiệm phát triển ứng dụng web trên nền tảng Laravel, VueJS là một lợi thế.\nCó kinh nghiệm với các hệ thống của Microsoft như SharePoint, SQL, Email Exchange.\nCó ý thức cao về bảo mật thông tin doanh nghiệp.\nChăm chỉ, thái độ làm việc tốt, tự giác, có tinh thần trách nhiệm, đáng tin cậy, tác phong làm việc chuyên nghiệp.\nCó khả năng tiếp thu kiến thức kỹ thuật và sản phẩm mới, tài liệu học tập bằng tiếng Anh.\nCó khả năng làm việc theo nhóm và làm việc độc lập.\nKỹ năng giao tiếp tốt.\nCó kiến thức trong lĩnh vực khai thác cảng, logistic là một lợi thế.', 10000000.00, 15000000.00, 'Quảng Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(36, 32, 35, 'Nhân Viên Lập Trình Website Fullstack', 'Tham gia phát triển và vận hành các dự án thực tế liên quan đến nền tảng Elearning.\nXây dựng, tối ưu hóa hệ thống web, đảm bảo hiệu suất và trải nghiệm người dùng.\nPhối hợp chặt chẽ với các thành viên trong team (BA, UI/UX, Tester, DevOps…) để phát triển các tính năng mới.\nNghiên cứu, áp dụng các công nghệ mới để nâng cao chất lượng sản phẩm.', 'Tốt nghiệp chuyên ngành Công nghệ Thông tin hoặc có kinh nghiệm tương đương.\nCó kinh nghiệm 1 năm làm việc trở lên với các công nghệ Web.\nTư duy logic tốt, chủ động học hỏi, làm việc nhóm tốt và có trách nhiệm với công việc.\nCó máy tính cá nhân để làm việc.\nThành thạo:\nFront-End: HTML, CSS, JavaScript, Typescript, Git, Figma.\nBack-End: PHP, NodeJs\nCSDL: MySQL, Redis\nCó kiến thức tốt về:\nRESTful API, HTTP request\nKỹ thuật cache dữ liệu\nKỹ thuật tối ưu hoá hệ thống web\nƯU TIÊN:\nƯu tiên ứng viên có kinh nghiệm với hệ thống Elearning hoặc các hệ thống quản lý nội dung.\nHiểu biết hoặc đã làm việc với kiến trúc Microservices, biết cách xây dựng API Gateway.\nThành thạo làm việc với các framework:\nVue.js (Frontend)\nLaravel, Yii2 (Backend – PHP)', 8000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(37, 33, 36, 'IT Support', 'Position Objectives:\nServe as a vital bridge between the Headquarters’ IT team and the local IT team in Vietnam to ensure the seamless deployment, operation, and alignment of IT systems, processes, and standards.\nDrive system performance optimization, streamline operational processes, and ensure consistent, high-quality IT service delivery across the organization.\nProvide timely technical support to maintain business continuity and enhance day-to-day operational efficiency.\nKey Responsibilities:\nCollaborate closely with the IT team at the Headquarters to develop, standardize, improve, and implement IT infrastructure strategies, system processes, and operational procedures.\nCommunicate directly and effectively in English (speaking, listening, and writing) with the Headquarters’ teams to ensure alignment, accurate task execution, and efficient project delivery.\nDeploy, develop, and supervise IT infrastructure and systems in Vietnam to accelerate business processes and enhance operational performance.\nManage, operate, and monitor IT infrastructure, including servers, network systems, storage devices, security systems, and backup solutions, ensuring stable and secure operations.\nPerform IT Helpdesk duties: install, configure, maintain, and troubleshoot hardware, software, networks, email systems, and other IT-related issues for end-users at the main office and satellite hubs.\nEnsure timely technical support and stable operation of IT systems and equipment across all locations.\nSupport the rollout and execution of IT projects to align with the company’s business development and expansion plans.', 'Bachelor\'s Degree or higher in Information Technology or related fields.\nMinimum 3 years of experience in a similar role: IT System, IT Helpdesk, System Administrator.\nSolid knowledge of networking, servers, virtualization, Windows operating systems, hardware, and software.\nStrong teamwork, problem-solving, and communication skills to collaborate with multiple departments and international teams.\nGood English proficiency (speaking, listening, writing) to work directly with foreign teams.\nAbility to analyze and resolve technical issues promptly and effectively.', 15000000.00, 17000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(38, 34, 37, 'Game QA Tester', 'Proceed the QA for published games (live games);\nWrite/manage a QA Plan, Test Cases and Test Data from Testing requirements;\nConduct and schedule tests, including Compatibility Test, Functionality Test, Policy Test, Balance Test.', 'Have at least 6 months of experience;\nHave experience in mobile game play (character collection RPG, sports, casual game, ETC);\nMobile game mid/hardcore/RPG genre service experience;\nExcellent Excel and computer skills;\nTechnical insight on a wide range of physical devices from different manufacturers (Apple, Samsung, ETC.) and operating systems (iOS, Android, ETC…);', 1000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(39, 35, 38, 'Nhân Viên Kinh Doanh (Gia Công & Phát Triển Phần Mềm)', 'NHIỆM VỤ CHÍNH / KEY RESPONSIBILITIES\nPhát triển kinh doanh / Business Development\nTìm kiếm & mở rộng khách hàng tiềm năng trong và ngoài nước (Nhật Bản, Mỹ, Châu Âu, Việt Nam...).\nIdentify and expand potential clients in both domestic and international markets (Japan, US, Europe, Vietnam...).\nGiới thiệu dịch vụ gia công phần mềm (outsourcing/offshore), phát triển phần mềm theo yêu cầu, cung cấp đội ngũ phát triển (dedicated team).\nPromote software outsourcing, offshore development, custom software solutions, and dedicated development team services.\nPhân tích nhu cầu khách hàng, tư vấn giải pháp công nghệ & mô hình hợp tác phù hợp.\nAnalyze client needs, propose suitable technology solutions and cooperation models.\nTư vấn & bán hàng / Sales & Consulting\nChuẩn bị proposal, báo giá, thuyết trình và thương thảo hợp đồng.\nPrepare proposals, quotations, presentations, and negotiate contracts.\nPhối hợp cùng đội ngũ kỹ thuật/PM để đảm bảo giải pháp đáp ứng yêu cầu và khả thi.\nWork with technical/PM teams to ensure proposed solutions are feasible and aligned with client needs.\nĐạt và vượt chỉ tiêu doanh số theo kế hoạch kinh doanh.\nAchieve and exceed sales targets as per business plan.\nChăm sóc khách hàng / Account Management\nQuản lý, duy trì và phát triển mối quan hệ với khách hàng hiện hữu.\nManage, maintain, and strengthen long-term relationships with existing clients.\nTheo dõi mức độ hài lòng & xử lý các vấn đề phát sinh.\nMonitor customer satisfaction and resolve issues during collaboration.\nBáo cáo & chiến lược / Reporting & Strategy\nPhân tích thị trường, đối thủ cạnh tranh và xu hướng công nghệ để đề xuất chiến lược kinh doanh.\nAnalyze market trends, competitors, and technologies to recommend business strategies.\nBáo cáo định kỳ về doanh số, cơ hội kinh doanh và tiến độ hợp đồng.\nProvide regular reports on sales performance, business opportunities, and contract status.', 'YÊU CẦU CÔNG VIỆC / REQUIREMENTS\nTốt nghiệp Đại học chuyên ngành Kinh tế, Quản trị kinh doanh, CNTT hoặc liên quan.\nBachelor’s degree in Business, Economics, IT, or related fields.\nTối thiểu 3 năm kinh nghiệm trong Sales IT / Business Development / Outsourcing Sales.\nAt least 3 years of experience in IT Sales, Business Development, or Outsourcing Sales.\nKiến thức cơ bản về quy trình phát triển phần mềm (Agile, Scrum, Waterfall...), mô hình offshore & outsourcing.\nBasic understanding of software development processes (Agile, Scrum, Waterfall) and offshore/outsourcing models.\nKỹ năng giao tiếp, đàm phán, thuyết trình tốt; chủ động, sáng tạo, định hướng kết quả.\nStrong communication, negotiation, and presentation skills; proactive, creative, and result-oriented.\nGiao tiếp tốt tiếng Anh hoặc tiếng Nhật (ưu tiên biết cả hai).\nGood communication in English or Japanese (both is a plus).\nChịu được áp lực doanh số, tinh thần trách nhiệm cao.\nAbility to work under sales pressure with strong accountability.', 10000000.00, 60000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(40, 36, 39, 'Chuyên Viên Tuyển Dụng Mảng IT', 'Phối hợp cùng quản lý dự án xây dựng chiến lược tuyển dụng theo từng giai đoạn (sàng lọc, truyền thông, phỏng vấn)\nSourcing ứng viên qua các kênh: LinkedIn, TopCV, cộng đồng, referral…\nPhụ trách liên hệ ứng viên, sắp xếp phỏng vấn, theo sát quy trình tuyển chọn\nHỗ trợ thiết lập tài liệu, dashboard tracking số lượng và chất lượng ứng viên\nLàm việc trực tiếp với khách hàng, team kỹ thuật và các bên liên quan', 'Giới tính: Nữ\nĐộ tuổi: 25 – 35\nNgoại hình &  giao tiếp tốt, nhanh nhẹn và có tư duy hệ thống\nTối thiểu 1 năm kinh nghiệm tuyển dụng, ưu tiên đã tham gia các dự án mass hiring, IT headhunting hoặc tuyển số lượng lớn\nCó khả năng làm việc độc lập và teamwork, chịu được áp lực deadline cao\nTiếng Anh tốt (đọc hiểu JD, CV, giao tiếp với ứng viên/khách hàng quốc tế)\nCó tinh thần trách nhiệm cao, chủ động, linh hoạt trong xử lý công việc', 10000000.00, 17000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(41, 5, 8, 'Ai Researcher - Mức Lương 12 - 25 Triệu', 'Đảm nhận vai trò nghiên cứu và phát triển nội dung về lĩnh vực AI. Hỗ trợ các hoạt động đào tạo, phối hợp với các bộ phận để triển khai chiến dịch hiệu quả.\nTìm kiếm, chọn lọc và tổng hợp thông tin chuyên sâu từ các nguồn quốc tế và nội bộ về các chủ đề: AI và các công nghệ, ứng dụng liên quan v.v.\nBiên soạn nội dung slide đào tạo phù hợp với mục tiêu từng chương trình (livestream, workshop, khóa học).\nHỗ trợ giảng viên/streamer trong việc chuẩn bị tài liệu đào tạo, kịch bản trình bày, các case study minh họa.\nNghiên cứu các tính năng, sản phẩm, điểm mạnh và lợi thế cạnh tranh của các đối tác.\nViết nội dung giới thiệu, hướng dẫn sử dụng, phân tích sản phẩm và đăng lên các group cộng đồng người dùng trên các nền tảng: Facebook, Telegram, Zalo, Twitter/X, v.v.\nĐề xuất chủ đề, ý tưởng nội dung theo trend thị trường và chiến lược phát triển sản phẩm.\nLàm việc cùng team thiết kế để sản xuất ấn phẩm hình ảnh, infographic, banner... bám sát nội dung và dễ hiểu với người dùng.\nHỗ trợ team truyền thông, livestream triển khai các chiến dịch nội dung liên quan đến đào tạo và sản phẩm.', 'Có kiến thức nền tảng và kinh nghiệm trong lĩnh vực AI (trên 2 năm)\nCó khả năng thuyết trình lưu loát, ngoại hình sáng, phong thái chuyên nghiệp cùng kiến thức chuyên môn vững vàng.\nKỹ năng research, tổng hợp và xử lý thông tin nhanh, hiệu quả từ nhiều nguồn quốc tế.\nKỹ năng viết tốt, văn phong rõ ràng, dễ hiểu, phù hợp với từng nhóm đối tượng (ưu tiên có portfolio nội dung từng thực hiện).\nCó khả năng sử dụng các công cụ làm slide như Canva hoặc PowerPoint.\nChủ động, có tư duy logic, làm việc nhóm tốt và tinh thần học hỏi cao.', 12000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(42, 5, 8, 'Crypto Researcher - Mức Lương 12 - 25 Triệu', 'Đảm nhận vai trò nghiên cứu và phát triển nội dung về thị trường Crypto, Blockchain và Web3. Hỗ trợ các hoạt động đào tạo, phối hợp với các bộ phận để triển khai chiến dịch hiệu quả.\nTìm kiếm, chọn lọc và tổng hợp thông tin chuyên sâu từ các nguồn quốc tế và nội bộ về các chủ đề: Blockchain, Crypto, Web3, DeFi, NFT, v.v.\nBiên soạn nội dung slide đào tạo phù hợp với mục tiêu từng chương trình (livestream, workshop, khóa học).\nHỗ trợ giảng viên/streamer trong việc chuẩn bị tài liệu đào tạo, kịch bản trình bày, các case study minh họa.\nNghiên cứu các tính năng, sản phẩm, điểm mạnh và lợi thế cạnh tranh của các đối tác.\nViết nội dung giới thiệu, hướng dẫn sử dụng, phân tích sản phẩm và đăng lên các group cộng đồng người dùng trên các nền tảng: Facebook, Telegram, Zalo, Twitter/X, v.v.\nĐề xuất chủ đề, ý tưởng nội dung theo trend thị trường và chiến lược phát triển sản phẩm.\nLàm việc cùng team thiết kế để sản xuất ấn phẩm hình ảnh, infographic, banner... bám sát nội dung và dễ hiểu với người dùng.\nHỗ trợ team truyền thông, livestream triển khai các chiến dịch nội dung liên quan đến đào tạo và sản phẩm.', 'Có kiến thức nền tảng và kinh nghiệm tốt về thị trường Crypto, Blockchain, Web3 và các sản phẩm DeFi (trên 2 năm)\nCó khả năng thuyết trình lưu loát, ngoại hình sáng, phong thái chuyên nghiệp cùng kiến thức chuyên môn vững vàng.\nKỹ năng research, tổng hợp và xử lý thông tin nhanh, hiệu quả từ nhiều nguồn quốc tế.\nKỹ năng viết tốt, văn phong rõ ràng, dễ hiểu, phù hợp với từng nhóm đối tượng (ưu tiên có portfolio nội dung từng thực hiện).\nCó khả năng sử dụng các công cụ làm slide như Canva hoặc PowerPoint.\nChủ động, có tư duy logic, làm việc nhóm tốt và tinh thần học hỏi cao.', 12000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(43, 37, 40, 'Full-Stack Developer (PHP / Nodejs / MySQL)', 'Trực tiếp phát triển các sản phẩm, hệ thống vận hành nội bộ (CRM, ERP,...) phục vụ các lĩnh vực như: bán lẻ, giáo dục.\nTham gia xây dựng backend (PHP/Laravel, NodeJS), hệ thống API kết nối app/web.\nThực hiện xây dựng giao diện website theo thiết kế, đảm bảo tương thích trên các thiết bị khác nhau.\nPhối hợp chặt chẽ với Dev Lead để tổ chức codebase, viết mã rõ ràng, tuân thủ tiêu chuẩn kỹ thuật của team.\nPhối hợp với BA/QC để đảm bảo chất lượng sản phẩm trước khi đưa vào vận hành.\nThiết kế và lập trình giao diện web (admin portal), đảm bảo responsive, thân thiện trên nhiều thiết bị.', 'Từ 2 - 3 năm kinh nghiệm trong vai trò phát triển phần mềm Full-stack. \nThành thạo Fontend: HTML, CSS, JavaScript, và các framework như Vue.js, React, responsive layout, tối ưu UX.\nThành thạo Backend: PHP/Laravel, NodeJS, thiết kế RESTful API, viết tài liệu API với Swagger.\nHiểu biết về design patterns và kiến trúc phần mềm. \nThành thạo với Database SQL (MySQL); các công cụ quản lý mã nguồn (Git/Github). \nTư duy hệ thống, trách nhiệm cao với chất lượng và độ ổn định của sản phẩm.  \nƯu tiên ứng viên từng làm việc với hệ thống CMS hoặc hệ thống trong lĩnh vực bản lẻ và giáo dục.', 20000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(44, 38, 41, '[Hà Nội] Ui / Ux Designer', 'Nghiên cứu và phối hợp với Business Analyst để xây dựng các thiết kế trải nghiệm & giao diện người dùng cho các sản phẩm phần mềm của công ty với tiêu chí chuẩn mực và tiện dụng.\nThiết kế luồng sử dụng cũng như nghiên cứu để tối ưu trải nghiệm của người dùng sản phẩm trên từng tính năng của hệ thống. Có kỹ năng xây dựng design system và áp dụng vào sản phẩm\nThiết kế giao diện UI/UX trên nhiều thiết bị và nền tảng khác nhau, đặc biệt là các sản phẩm Web-based.\nPhối hợp chặt chẽ với các bộ phận Support, Marketing, các nhóm Development, QA, … để xây dựng bản thiết kế tối ưu và sạch gọn, nâng cao trải nghiệm người dùng\nThực hiện các nghiên cứu/đánh giá về hành vi người dùng (thị hiếu) trong quá trình thiết kế sản phẩm/tính năng. Tối ưu trải nghiệm để có phản biện tốt cho đầu ra sản phẩm\nNghiên cứu, cập nhật xu hướng thiết kế mới để giúp nâng cao chất lượng thiết kế sản phẩm', 'Tốt nghiệp đại học chuyên ngành thiết kế\nCó ít nhất 2 năm kinh nghiệm trong thiết kế sản phẩm phần mềm, đặc biệt là các sản phẩm phần mềm liên quan đến nghiệp vụ vận hành. Có kinh nghiệm thiết kế cho các sản phẩm SaaS là lợi thế.\nSử dụng thành thạo các phần mềm thiết kế như: Figma, AI, PS\nCó kinh nghiệm làm việc với các phương pháp thiết kế mới như Flat Design, Material Design, User-Centric Design… Có hiểu biết sâu về Component, autolayout, …\nCó tư duy tốt về thẩm mỹ, có tư duy logic tốt về flow feature, có khả năng làm interaction design\nChịu khó tham khảo, tìm tòi giải pháp và kiên nhẫn trong công việc, tỉ mỉ trong cách tạo ra sản phẩm. Kỹ tính tới từng chi tiết, luôn hướng tới cái hoàn thiện hơn (cầu toàn).\nCó khả năng chịu được áp lực và có trách nhiệm với công việc được giao\nKỹ năng ra quyết định và giải quyết vấn đề chiến lược trong lĩnh vực thiết kế và trải nghiệm người dùng\nTiếng Anh chuyên ngành đọc hiểu', 13000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(45, 39, 42, 'Vận Hành Cộng Đồng Game', 'Hỗ trợ khách hàng trên các cộng đồng (Fanpage, Group,...)\nLivestream, khuấy động cộng đồng, thực hiện các sự kiện cộng đồng.\nPhối hợp với các phòng ban nội bộ trong công việc\nThực hiện bài viết, cập nhật thông tin sản phẩm trên cộng đồng, fanpage theo yêu cầu của nhóm sản phẩm.\nPhối hợp với các phòng ban trong công việc', 'Tính tình hòa đồng, sôi nổi, nói chuyện thân thiện.\nCó khả năng bình tĩnh và giải quyết áp lực theo xu hướng tích cực\nYêu cầu bắt buộc: Thích chơi Game, chơi nhiều game thể loại MMORPG, Card Battle, Kiếm hiệp,…\nƯu tiên ứng viên là nữ, có khả năng livestream\nƯu tiên ứng viên có khả năng PTS, căt ghép Video', 8000000.00, 10000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(46, 40, 43, 'Cộng Tác Viên IT (Theo Dự Án)', '“HMH tuyển CỘNG TÁC VIÊN IT SENIOR – TƯ VẤN VÀ TRIỂN KHAI GIẢI PHÁP DOANH NGHIỆP”\nVề HMH\nHMH là đối tác của Microsoft, Google, Bitdefender, ManageEngine, chuyên cung cấp giải pháp và dịch vụ CNTT cho doanh nghiệp vừa và nhỏ, tập đoàn trong nước và tập đoàn nước ngoài (FDI, MNC).\nChúng tôi tìm kiếm chuyên gia IT (5–10 năm kinh nghiệm), đã từng trực tiếp tư vấn và triển khai DỰ ÁN thực tế, để đồng hành triển khai các giải pháp công nghệ cho khách hàng đa dạng quy mô.\nNhiệm vụ chính\nTư vấn giải pháp và thiết kế hệ thống phù hợp cho SMB, tập đoàn trong nước và FDI/MNC.\nTriển khai dự án thực tế:\nMicrosoft 365 (Azure AD, Exchange, Teams, SharePoint)\nGoogle Workspace và Google Cloud\nBitdefender Security (Endpoint, Email, Threat Protection)\nManageEngine (ITSM, Endpoint, AD Manager)\nMigration và bảo mật: Email/Data Migration, Backup và Disaster Recovery.\nĐào tạo và chuyển giao cho IT nội bộ và người dùng cuối.\nOn-call hỗ trợ khi có phát sinh từ khách hàng/dự án.', 'Yêu cầu bắt buộc\n5–10 năm kinh nghiệm trong mảng IT Infrastructure/Cloud/Security.\nĐã từng tư vấn và triển khai thành công dự án thực tế cho doanh nghiệp (SMB, tập đoàn trong nước hoặc FDI).\nThành thạo ít nhất 2 mảng: Microsoft / Google / Bitdefender / ManageEngine.\nƯu tiên có chứng chỉ quốc tế (Microsoft, Google, Bitdefender, ManageEngine).\nTư duy giải pháp – định hướng business, kỹ năng giao tiếp khách hàng xuất sắc.\nCam kết bảo mật và hợp tác lâu dài.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(47, 41, 44, 'Senior Software Developer', 'POSITION PURPOSE: \nAs an Automation Developer, you will have the opportunity to join our Operations Excellence team, you will play a key role in designing, developing, and optimizing digital solutions to tackle challenges in Logistics and Planning — including transportation management, warehouse management, and route optimization. You\'ll work as part of an agile, cross-functional team, leveraging your programming expertise to deliver impactful solutions that drive efficiency and innovation in the fast-paced retail industry.\n YOUR RESPONSIBILITIES WILL INCLUDE:\n- Collaborating closely with the Technical Lead and Business Analyst to understand key business challenges in the logistics domain, with a focus on Transportation Management and Warehouse Management.\n- Utilizing your expertise in C# and ASP.NET to develop applications for warehouse management and delivery services, integrating features such as inventory tracking, order processing, and route optimization.\n- Designing and implementing effective data management and processing solutions to enhance the performance and functionality of warehouse and delivery systems.\n- Contributing to comprehensive documentation of system features, architecture, and user flows to ensure maintainability and knowledge sharing.', 'WHAT WE WILL BE LOOKING FOR IN YOU:\nProgramming Proficiency:\n- Proficient in C# and  ASP.NET Core, with solid experience in MVC, Web API, Clean Architecture, and Domain-Driven Design (DDD).\n- Solid understanding of Object-Oriented Programming (OOP) principles, SOLID, design patterns, and clean code practices.\n- Hands-on experience in designing and developing microservices, and event-driven architectures using message brokers such as Kafka, RabbitMQ.\n- Strong experience in database design in SQL, with a focus on query optimization and high-performance data handling.\n- Working experience with modern front-end frameworks like React, Vue, or Angular.\n- Proficient in HTML/CSS/JavaScript, including responsive design.\n- Strong experience in communication protocols, especially RESTful API design and implementation.\n- Strong understanding of security standards including OAuth2, JWT, and OWASP Top 10.\n- Solid understanding of Artificial Intelligence (AI) and Machine Learning (ML) concepts, especially in Natural Language Processing (NLP) is advantageous.\n- Experience with GCP ML services (Vertex AI,  Vision API, NLP API, ETC.).\n- Experience with CI/CD pipelines, containerization (Docker, Kubernetes), and cloud platforms such as GCP is a plus.\n- Knowledge of Git, Jira for version control.\n Qualifications:\n- Bachelor\'s degree in Computer Science, Information Technology, or Software Engineering\n- From 2 to 3 years of professional experience in software development.\n- Experienced in Manufacturing and Logistics domains, preferably within a Manufacturing or Logistics company.\n- Problem-solving: Ability to identify and solve technical data analysis and modeling challenges.\n- Learning Agility: Eagerness to learn new concepts and technologies quickly.\n- Attention to Detail: Ability to work meticulously and ensure the accuracy of results.\n- Versatility in Work Environment: Ability to work effectively both independently and as part of a team, with strong communication skills and adept problem-solving abilities.\n- Willing to research new technologies: Ability to research new technology to meet and improve projects with specific requirements.', 20000000.00, 30000000.00, 'Long An,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(48, 42, 45, 'Automation Developer / Coder', 'Phát triển và triển khai các giải pháp tự động hoá quy trình (RPA) nhằm tối ưu hiệu quả vận hành của doanh nghiệp.\nLập trình, xây dựng script tự động hoá trên trình duyệt, ứng dụng web, desktop và điện thoại.\nPhối hợp với các bộ phận nghiệp vụ để phân tích quy trình, xác định nhu cầu tự động hoá.\nBảo trì, nâng cấp, tối ưu hoá các bot/automation scripts hiện có.\nĐảm bảo chất lượng, tính bảo mật và khả năng mở rộng của hệ thống automation.', 'Độ tuổi: 23 – 32 tuổi, Nam.\nTốt nghiệp đại học chuyên ngành Công nghệ Thông tin, Điện tử Viễn thông hoặc các lĩnh vực có liên quan.\nCó ít nhất 2 năm kinh nghiệm trong phát triển phần mềm hoặc lập trình automation..\nThành thạo ít nhất một ngôn ngữ lập trình: Java, Python, JavaScript, C#...\nCó kinh nghiệm với các công cụ automation/RPA như: UiPath, Automation Anywhere, Blue Prism, hoặc Selenium, Puppeteer.\nTư duy logic tốt, nhiệt tình, cẩn thận, tỉ mỉ, trách nhiệm cao; linh hoạt, sáng tạo, hướng đến hiệu quả công việc. \nKỹ năng làm việc độc lập và làm việc nhóm tốt.', 18000000.00, 25000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(49, 43, 46, 'IT Manager', 'Provide plan, solution and management (30%):\n● Analyze the requirements which are requested by internal related departments such as RnD, Growth, CDX and Operations.\n● Produce development plans and solution design based on the requirements.\n● Review and the solution produced by other team members.\n● Manage cloud infrastructure and supporting tools.\n● Manage IT team to deliver software on-time and on-budget.\nDevelopment (30%):\n● Follow assignment/commitment to develop the application based on requirements.\n● Perform self-review and Unit Test to quality the outcome yourself.\nQuality Control (30%):\n● Conduct cross-review the outcome of team members to provide independent and transparent quality point of view as well as assure trustable quality on the outcome of the team.\n● Conduct automation test to avoid side effect issues on the deployment process.\nImprovement (10%):\n● Conduct demonstrations for the stakeholders to satisfy the expectations of stakeholders as well as gathering new opportunities for improvement.\n● Conduct retrospective to produce lesson learnt as well as improvement actions plan.\n● Self-learning plan to improve yourself in relevant skills and technical.', '● Gender: Male.\n● Age: 26 – 35.\n● Education: Bachelor of Computer Science or Programming or similar certification.\n● Knowledge of ReactJs, React Native, NodeJS, ExpressJS, NestJS, PostgreSQL, MongoDB, Tyscript, Python.\n● Knowledge in Agile Scrum working model.\n● At least 1-year experience in managing an IT team.\n● Knowledge of Cloud infrastructure such as IaaS, PaaS and SaaS.\n● Knowledge of Devops, CI/CD and Automation Test.\n● Confident, energetic, hardworking.\n● Open and ready to change mindset.\n● Good communication and presentation skills.\n● Ability to communicate in English. TOEIC 650 or higher.', 10000000.00, 12000000.00, 'Cần Thơ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(50, 44, 47, 'Kỹ Sư Phần Mềm Hệ Thống Công Nghệ Thông Tin', 'Phát triển và bảo trì hệ thống phần mềm quản lý chuỗi cung ứng và vận chuyển.\nThiết kế và tối ưu hóa các giải pháp CNTT phục vụ hoạt động logistics.\nTích hợp hệ thống CNTT với các đối tác bên ngoài: hãng vận chuyển, kho bãi, đối tác thương mại điện tử...\nXử lý dữ liệu và hỗ trợ kiểm tra thông tin script, source, database\nPhối hợp với các phòng để đưa ra giải pháp công nghệ phù hợp.\nHỗ trợ vận hành, xử lý lỗi phần mềm liên quan đến nghiệp vụ logistics.\nTriển khai bộ source code, database của các sản phẩm cho hệ thống ứng dụng', 'Tốt nghiệp Đại học chuyên ngành CNTT, Kỹ thuật phần mềm, Hệ thống thông tin hoặc tương đương.\nCó hiểu biết hoặc kinh nghiệm làm việc trong lĩnh vực logistics, vận chuyển, chuỗi cung ứng.\nThành thạo ít nhất một ngôn ngữ lập trình: Java, Python, C#, hoặc PHP.\nCó kinh nghiệm với cơ sở dữ liệu: MySQL, PostgreSQL, SQL Server...\nƯu tiên ứng viên có kinh nghiệm với hệ thống ERP, TMS, WMS.\nKỹ năng phân tích và giải quyết vấn đề tốt.\nChủ động, trách nhiệm và có khả năng làm việc nhóm.', 14000000.00, 17000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(51, 33, 36, 'Giáo Viên Dạy Lập Trình / IT / Coding (Remote / Freelance / Part-Time)', '- Dạy viết mã, lập trình cho trẻ em từ nhóm 6 đến 16 tuổi (lớp học trực tuyến sử dụng Zoom)\n- Mỗi lớp sẽ diễn ra trong 1 giờ.\n- Thời gian (có thể thay đổi tùy theo nhu cầu của phụ huynh và sự sẵn sàng của giáo viên):\n○ Thứ Hai - Thứ Sáu (5:30 chiều - 9:30 tối)\n○ Thứ 7 - Chủ nhật (Thời gian linh hoạt)\n- Chuyên môn về mã hóa (logic, trình tự và cấu trúc) để tạo ra các kết quả sáng tạo như Trò chơi, Ảnh động, ứng dụng và trang web.\n *Địa điểm làm việc :Toàn Quốc', '- Là công dân Việt Nam.\n- B. Tech, M. Tech, BCA, MCA, BE, ME. (Sinh viên mới tốt nghiệp 2022, 2021,2020,2019,2018 đã có kinh nghiệm) CSE, ISE, EEE, IT - CHỈ NỀN TẢNG MÁY TÍNH\n- Có kinh nghiệm ở vị trí giảng dạy sẽ là một lợi thế\n- Có thể giảng dạy nhiều ca trong một tuần.\n- Bạn là người có khả năng xây dựng mối quan hệ và kết nối mạnh mẽ.\n- Kiến thức tốt về Scratch, Python.', 10000000.00, 15000000.00, 'TP.HCM', 'Part-time', '2025-10-07 20:59:18.149534'),
	(52, 45, 48, 'Nhân Viên Vận Hành Máy In Barcode', 'Phụ trách các đơn hàng Barcode\nXử lý file, hình ảnh, tạo lập file in  kiểm tra chất lượng thành phẩm (trầy xướt, sai nội dung, màu sắc, đậm nhạt).\nKiểm soát NVL trước in và sau in ( xuất và trả NVL về kho )\nBàn giao thành phẩm cho QC\nPhụ trách kỹ thuật các máy in barcode (bảo dưỡng đầu in, máy in định kỳ, xử lý các lỗi máy móc phát sinh)\nCác công việc được cấp trên điều động.', 'Ưu tiên ứng viên sử dụng PM corel, Bartender Vi tính văn phòng.\nChịu khó, cẩn thận\nTrung thực , làm việc nhóm\nTăng ca khi hàng gấp, hàng nhiều', 8000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(53, 46, 49, 'IT Developer (Frontend / Backend / Ai)', 'Coding Challenge #3: IT Developer (Frontend / Backend / AI)\nLocation: Online (for Developers based in Da Nang)\nChallenge Date: 6:30PM Thursday, August 28, 2025\nApplication Deadline: 12:00 PM, Thursday, August 28, 2025\nApplication Form: https://forms.cloud.microsoft/r/LpFTSnbpv7\n\n About the Opportunity\nTalentGetGo is excited to launch the 3rd Coding Challenge - a unique opportunity for passionate developers to showcase their skills and connect with top Korean tech companies hiring global talent.\nWhether you\'re a Frontend, Backend, or AI Developer, this is your chance to prove your talent, receive recognition, and open doors to a global IT career - all from Vietnam.\n\n What You’ll Get\nInternship & job opportunities with Korean tech companies\nAccess to TalentGetGo’s exclusive network of verified IT developers\n\nWho Should Apply\nWe’re looking for:\nDevelopers currently based only in Da Nang\nOpen to Frontend / Backend / AI specializations\nRecent graduates or final-year students are welcome\nComfortable taking an English coding test\nCommitted to attending the challenge in person\n\n Event Details\nFormat: Online coding test via Talent Get Go platform\nTest Language: English\nDuration: 3 Hours (06:30 PM - 09:30 PM)\n\n Note\nParticipants are required to take the test online via Talent Get Go platform. Only confirmed participants will recieve the test guidelines\nNo-shows after confirmation will be disqualified from future programs. Please confirm only if you can attend.\nPrevious Coding Challenge participants are welcome to reapply.\nOnly shortlisted candidates will be contacted via email.\n\n TalentGetGo - a joint venture between CARROT Global, a leading HR consulting company, and Codepresso, a South Korea-based AI-powered HR SaaS provider - a Korean-based global recruitment and HR platform, the challenge brings together top young IT talents to showcase their skills through real-world coding scenarios.', 'Who Should Apply\nWe’re looking for:\nDevelopers currently based only in Da Nang\nOpen to Frontend / Backend / AI specializations\nRecent graduates or final-year students are welcome\nComfortable taking an English coding test\nCommitted to attending the challenge in person', 5000000.00, 8000000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(54, 47, 50, 'Back-End Developer', 'Phát triển, tối ưu và bảo trì các hệ thống backend đang triển khai.\nTham gia xây dựng, phát triển các sản phẩm trong lĩnh vực Crypto/Blockchain theo định hướng của công ty. \nĐề xuất ý tưởng, cùng đội ngũ kỹ thuật triển khai các giải pháp thành sản phẩm thực tế.', 'Yêu cầu bắt buộc:\n- Tốt nghiệp đại học chính quy các ngành: CNTT, Khoa học máy tính, Toán – Tin hoặc tương đương.\n- Tối thiểu 1 năm kinh nghiệm phát triển backend với Golang hoặc Rust.\n- Sử dụng tốt Linux và công nghệ container như Docker.\n- Thành thạo ít nhất một trong các hệ quản trị cơ sở dữ liệu: Postgres, MySQL/MariaDB, Redis, ...\n- Khả năng tư duy logic và giải quyết vấn đề tốt.\n- Tinh thần học hỏi và sẵn sàng làm việc với công nghệ/ ngôn ngữ mới.\nƯu tiên (không bắt buộc):\n- Hiểu biết hoặc đã từng tham gia các dự án Blockchain.\n- Đam mê học hỏi và khả năng tự nghiên cứu công nghệ mới.', 14000000.00, 25000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(55, 48, 51, 'Nhân Viên Vận Hành Game', '·   Tham gia phát hành và vận hành các sản phẩm Game Online của Công ty\n·   Tham gia trải nghiệm và đánh giá để tìm kiếm các sản phẩm tiềm năng mới cho Công Ty.\n·   Lên kế hoạch vận hành và tương tác với đối tác thiết kế sự kiện ingame/outgame nâng cao doanh thu cho sản phẩm mỗi tháng.\n·   Phân tích các số liệu của sản phẩm để định hướng phát triển cho sản phẩm.\n·   Playtest và tìm lỗi, đảm bảo sản phẩm vận hành ổn định.\n·   Report sản phẩm vận hành theo định kỳ theo yêu cầu.\n·   Phân tích hành vi người dùng và nhu cầu sử dụng sản phẩm.\n·   Hỗ trợ khách hàng cho sản phẩm trên các công cụ cộng đồng/vận hành.\n·   Phối hợp với các phòng ban khác trong công việc', '·   Đã tốt nghiệp các trường Đại học/ Cao đẳng\n·   Có kinh nghiệm làm việc từ 6 tháng ở các vị trí tương đương trong các đơn vị phát hành game tại Việt Nam \n·   Trung thực, chủ động, nhiệt tình, sáng tạo trong công việc và chịu được áp lực cao\n·   Có khả năng tư duy logic tốt với các dữ liệu/ chỉ số.\n·   Có khả năng diễn đạt ý tưởng và giao tiếp hiệu quả.\n·   Khung thời gian linh động theo công việc.\n·   Có đam mê và sử dụng thành thạo với các dịch vụ trực tuyến (Mạng xã hội, Forum, Social Game, Game online)\n·   Ưu tiên ứng viên đam mê chơi Game thể loại MMORPG, Card Battle, Thẻ tướng, Tiên hiệp, Kiếm hiệp…(Ưu tiên game Mobile)\n·   Ưu tiên ứng viên có kiến thức về các IP phim/ truyện/ manga/ anime xu hướng.\n·   Ưu tiên ứng viên có kinh nghiệm về đánh giá game,cập nhật xu hướng thị trường game, phân tích số liệu liên quan tới người dùng với những sở thích và thị hiếu quốc tế khác nhau.', 8000000.00, 10000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(56, 49, 52, 'Full-Stack Developer', '-  Trưởng nhóm lập trình (quản lý công việc của nhóm)\n- Trực tiếp tham gia phát triển các dự án phần mềm trọng điểm của công ty trong lĩnh vực y tế, các phần mềm ứng dụng cho y tế số \n- Tham gia phân tích, thiết kế hệ thống theo yêu cầu của khách hàng.\n- Phân tích, đánh giá, nâng cấp và tối ưu mã nguồn trong quá trình phát triển.\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai.\n- Tham gia đưa ra những ý tưởng, giải pháp mới cải thiện công việc', '- Tốt nghiệp đại học hệ chính quy các chuyên ngành CNTT\n- Thành thạo sử dụng Git để quản lý mã nguồn là một lợi thế\n- Kỹ năng chuyên môn (bắt buộc):\n+ Frontend: Có kiến thức về Angular, HTML, TypeScript, CSS, JQuery.\n+ Backend: Lập trình thành thạo với ngôn ngữ C#.\n+ DataBase: Có kiến thức về SQL Server.\n- Kinh nghiệm làm việc: tối thiểu 3 năm kinh nghiệm\n- Có khả năng làm việc nhóm, có ý chí cầu tiến khi đảm nhiệm vai trò tearm leader và chịu được áp lực trong công việc.\n- Yêu cầu khác: Nhiệt tình, năng động, chăm chỉ, có tinh thần cầu tiến, kỹ năng mềm trong giao tiếp.', 15000000.00, 25000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(57, 50, 53, 'Project Management Fresher', '• Study requirements and plan resources\n• Implement project goal\n• Work on task and/or assign to appropriate team members (if needed)\n• Review influencer’s profile • Send outreach (Email/DM) to potential influencers tool or manually\n• Report to Project Lead daily/routinely\n• Monitor workflow in order to ensure project running smoothly\n• Review requested data from Data Engineer and feedback bug within campaign requirement\n• Investigate & report issue, including performance & campaign issue, solutions and improvements\n• Contribute to internal tools build requirements & improvement', '• Bachelor’s degree in economics, Marketing or related field\n• Fresher or ideally, 1 years’ experience in marketing field or related position\n• Any other experience to prove that you can do the job well\n• Strong knowledge of sourcing tools and techniques\n• Good English communication skills\n• Proficient in Microsoft Excel & Power point and Google sheet \n• Project Management Skill:\n      • Communication skill\n      • Quality control data skill\n      • Organizational skill\n      • Task & result-oriented', 85000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(58, 51, 54, 'PHP Backend Developer', '• Design, develop, and maintain backend systems using GraphQL with Hasura and PHP.\n• Build and manage GraphQL schemas on Hasura, integrating with PostgreSQL database.\n• Integrate Hasura with system written in PHP to handle requests from Forntend\n• Set up and manage CI/CD pipelines using GitHub Actions for testing and FluxCD to deploy on Kubernetes environment.\n• Manage security configuration, authentication, and authorization of Hasura (JWT, roles).\n• Optimize GraphQL queries, monitor performance, and handle errors.\n• Work with frontend team to develop API that meet user needs.\n• Ensure backend systems meet security, performance, and scalability standards.\n• Write technical documentation and participate in internal training on GraphQL, Hasura, and CI/CD tools.', '• At least 2 years of experience working with backend development.\n• Experience working with Hasura and GraphQL.\n• Proficiency in PHP and experience building API or handling custom logic requests with Hasura.\n• Understanding of PostgreSQL database, including schema design, query optimization and data management.\n• Experience deploying applications on Kubernetes, using FluxCD to manage CD.\n• Skills in setting up CI pipelines with GitHub Actions, including running tests and checking automatic source code.\n• Understanding of API security (JWT, OAuth) and authorization methods on Hasura.\n• Skills in debugging and optimizing system performance.\n• English: Reading and understanding specialized documents\nOther requirements:\n• Experience working in a microservices environment.\n• Ability to work in team, communicate well and coordinate with other departments.\n• Logical thinking and ability to solve problems quickly.\n• Creative thinking, progressive and proactive in learning new technology, able to withstand high pressure.', 12000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(59, 52, 55, 'Senior Java Developer', 'Xây dựng và phát triển SDLC, bao gồm phân tích yêu cầu, thiết kế, mã hóa, test và vận hành.\nThiết kế và phát triển hiệu quả các ứng dụng Java, đảm bảo tuân thủ các tiêu chuẩn mã hóa và vận hành tốt nhất.\nTiến hành đánh giá code để xác định và giải quyết các vấn đề về hiệu suất như code xấu và lỗ hổng bảo mật.\nPhối hợp với các nhóm đa chức năng để thu thập các yêu cầu và chuyển chúng thành các thiết kế kỹ thuật.\nKhắc phục sự cố và sửa lỗi các vấn đề phức tạp trong quá trình vận hành, đảm bảo giải quyết kịp thời.\nLuôn cập nhật các xu hướng và những tiến bộ mới nhất trong quy trình phát triển Java và sử dụng chúng để cải thiện quy trình phát triển.\nPhối hợp với các bên liên quan để xác định phạm vi, mục tiêu và sản phẩm bàn giao của dự án, đảm bảo sự phù hợp với các mục tiêu kinh doanh.\nKết hợp với các team khác để hợp lý hóa các quy trình.', 'Có từ 5 năm kinh nghiệm phát triển Java\nHiểu rõ khái niệm cơ bản về hệ phân tán và Microservices, ưu tiên có kinh nghiệm phát triển Springboot, Spring Cloud;\nHiểu rõ công nghệ phát triển về database như MySQL, MongoDB, ưu tiên ứng viên có khả năng tối ưu câu lệnh SQL;\nƯu tiên ứng viên biết về Distributed Cache Redis, Middleware như Kafka;\nƯu tiên ứng viên nắm vững về Maven, Mit;\nTích cực chủ động, chịu được áp lực công việc, tinh thần đoàn kết, giao tiếp tốt, làm việc tỉ mỉ, có trách nhiệm.', 40000000.00, 50000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(60, 53, 56, 'Thực Tập Sinh Graphic Design (Ui Và Ux)', 'Được tham gia trực tiếp vào quá trình phát triển sản phẩm, thiết kế UI/UX cho Phần mềm CRM, ERP, Apmobile Hoặc Website/App/CMS/Themes và các sản phẩm khác theo tiêu chí thân thiện với người dùng.\nĐược tham gia với các bộ phận liên quan (Technology, Marketing, Development, Design...) để lựa chọn phương án thiết kế UI/UX xuyên suốt dự án sản phẩm/dịch vụ.\nTrao đổi ý tưởng, xây dựng quy trình thiết kế nhằm đảm bảo tính thẩm mỹ và logic. Trình bày ý tưởng, sản phẩm một cách trực quan thông qua các công cụ hỗ trợ.\nXây dựng các bộ UI/UX Design Guidelines để trợ giúp đội ngũ phát triển đúng yêu cầu về thiết kế.\nThường xuyên cập nhật công nghệ, tiêu chuẩn và các xu hướng thiết kế giao diện người dùng mới.\nThực hiện các công việc khác theo sự phân công của quản lý trực tiếp.', 'Về kinh nghiệm: Tối thiểu 3 tháng\nVề trình độ: Ưu tiên sinh viên năm cuối sắp ra trường các trường Đại học, Cao đẳng, Trung tâm chuyên ngành thiết kế đồ họa hoặc các chuyên ngành liên quan.\nVề kĩ năng: Có hiểu biết chính về Tool và Figma và các phần mềm hỗ trợ khác.\nPhẩm chất, thái độ: Chăm chỉ, tư duy độc lập, tôn trọng, cởi mở, vui tính.\nCó Máy tính cá nhân\nCV gửi kèm link các sản phẩm đã từng triển khai (nếu có) để đánh giá năng lực.', 3000000.00, 5000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(61, 54, 57, 'Lập Trình Viên No-Code Tại Bmt', '- Phát triển website, app, miniapp dựa trên yêu cầu của khách hàng hoặc yêu cầu của công ty\n- Sử công cụ no-code thiết kế, ráp dữ liệu, logic dựa theo API basic đã build sẵn.\n- Hỗ trợ, fix lỗi theo yêu cầu của khách hàng hoặc quản lý trực thuộc.', '- Không yêu cầu về bằng cấp\n- Nắm vững các kiến thức về CSS, Bootstrap, Reacjs, Vuejs (Quan trọng)\n- Có kiến thức về Backend: MongoDB, Nodejs, GraphQL\n- Có khả năng làm việc độc lập\n- Có tư duy nhanh nhạy, siêng năng, chịu khó tự tìm tòi học hỏi\n- Ưu tiên đã từng làm dự án cá nhân', 7000000.00, 15000000.00, 'Đắk Lắk', 'Full-time', '2025-10-07 20:59:18.149534'),
	(62, 55, 58, 'React Navtive Developer', 'Tham gia phát triển, duy trì và tối ưu ứng dụng mobile sử dụng React Native phục vụ quy trình nghiệp vụ bảo hiểm.\nPhối hợp cùng các thành viên trong nhóm triển khai tính năng mới và xử lý lỗi dự án.\nTham gia đóng góp ý tưởng cải thiện UI/UX và logic nghiệp vụ phù hợp với yêu cầu thực tế.\nHỗ trợ tích hợp ứng dụng với hệ thống backend (API, SDK…).\nĐược đào tạo và chuyển giao công nghệ mới khi cần thiết.', 'Có kiến thức hoặc kinh nghiệm 6 tháng – 1 năm với React Native (hoặc từng thực hiện ít nhất 1 dự án thực tế).\nNắm vững kiến thức cơ bản: component, state, props, navigation, lifecycle, Redux/Context API, call API (fetch/axios).\nBiết làm việc với RESTful API, có tư duy xử lý lỗi và validation phía client.\nCó kinh nghiệm sử dụng Git và quy trình quản lý source code cơ bản.\nCó khả năng làm việc nhóm, chủ động học hỏi, cẩn thận trong công việc.\nKhông yêu cầu tiếng Anh.', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(63, 56, 59, 'Kỹ Sư Tư Vấn Giải Pháp Mạng Và Bảo Mật - Thu Nhập Upto 30M', 'Nghiên cứu và tư vấn các giải pháp mạng và bảo mật theo nhu cầu khách hàng.\nXây dựng hồ sơ kỹ thuật, hồ sơ dự thầu.\nPhân tích yêu cầu khách hàng, đề xuất giải pháp tối ưu dựa trên các công nghệ của Cisco, Fortinet, Palo Alto, Check Point, Juniper, v.v.\nThiết kế sơ đồ mạng, kiến trúc bảo mật, lựa chọn thiết bị phù hợp với yêu cầu dự án.\nLàm việc với các nhà cung cấp, hãng công nghệ để cập nhật thông tin sản phẩm, giải pháp mới.\nHỗ trợ đội ngũ kinh doanh trong việc thuyết trình, demo giải pháp và sản phẩm cho khách hàng.\nTham gia xây dựng tài liệu đào tạo nội bộ về công nghệ mạng & bảo mật.\nHỗ trợ triển khai thử nghiệm (PoC) và đánh giá hiệu suất giải pháp.\nHỗ trợ giải đáp thắc mắc kỹ thuật của khách hàng trong quá trình đấu thầu và triển khai dự án', 'Tốt nghiệp Đại học / Cao đẳng chuyên ngành Công nghệ thông tin, Điện tử Viễn thông hoặc liên quan.\nHiểu biết về các công nghệ mạng và bảo mật: Routing, Switching, Firewall, IPS, VPN, NAC, DDoS Protection, v.v.\nCó kinh nghiệm làm việc với các giải pháp và thiết bị của Cisco, Fortinet, Palo Alto, Check Point, Juniper…\nCó kinh nghiệm thực hiện hồ sơ kỹ thuật, đấu thầu các dự án CNTT.\nKhả năng đọc hiểu tài liệu kỹ thuật bằng tiếng Anh.\nƯu tiên ứng viên có các chứng chỉ như CCNP, CCIE, NSE4+, PCNSE, JNCIP, hoặc tương đương.\nTiếng Anh tốt để có thể làm việc trực tiếp với đối tác, chuyên gia hãng\nKỹ năng tư vấn, thuyết trình và làm tài liệu kỹ thuật tốt.\nKỹ năng phân tích, đánh giá nhu cầu và thiết kế giải pháp phù hợp.\nKỹ năng làm việc nhóm và phối hợp với các bộ phận liên quan.\nSẵn sàng học hỏi và cập nhật công nghệ mới', 25000000.00, 30000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(64, 57, 60, 'Senior Full-Stack Developer (Nodejs, Typescript)', 'Thiết kế, phát triển & tối ưu hệ thống backend sử dụng Node.js (Express.js, Nest.js, Sails.js).\nTích hợp mô hình AI (LLM, RAG) vào hệ thống backend.\nXây dựng API chuẩn RESTful và WebSocket cho ứng dụng real-time.\nThiết kế & quản lý cơ sở dữ liệu (MongoDB, Redis, ElasticSearch, Clickhouse).\nTham gia xây dựng kiến trúc hệ thống, đảm bảo hiệu năng & khả năng mở rộng.\nTriển khai trên Docker và nền tảng Cloud (AWS, GCP, Azure).\nPhối hợp chặt chẽ với team AI, Frontend, Product để phát triển tính năng.\nNghiên cứu, nâng cấp & tối ưu hệ thống.\nThực hiện các nhiệm vụ khác theo phân công.', 'Tốt nghiệp ĐH ngành CNTT hoặc liên quan.\n≥ 4 năm kinh nghiệm Back-End với Node.js.\nThành thạo Express.js + 1 framework khác (Nest.js hoặc Sails.js).\nƯu tiên:\nKinh nghiệm trong FMCG.\nHiểu & từng làm việc với AI tools, Lite LLM, Anything LLM.\nCó kinh nghiệm LLM/RAG.\nThành thạo Docker, Microservices, DevOps, Rest-API, WebSocket.\nHiểu biết Unix/Linux, IIS.\nKỹ năng làm việc độc lập & nhóm, chủ động và học hỏi nhanh.', 20000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(65, 58, 61, 'Chuyên Viên Kinh Doanh Dự Án', 'Bán hàng Hệ thống, Thiết bị và phần mềm công nghệ hiện đại.\nTìm kiếm khách hàng dự án (chủ đầu tư, nhà thầu, công ty thiết kế…).\nTìm kiếm thông tin các dự án xây dựng dân dụng, chung cư, resort, khách sạn… sẽ khởi công hoặc đang xây dựng.\nTư vấn, giới thiệu sản phẩm, lên giải pháp phù hợp, báo giá, trình mẫu và chốt hợp đồng.\nBáo cáo tiến độ và kết quả công việc theo tuần cho Quản lý và BGĐ.\nChủ động lên kế hoạch triển khai các công việc hoặc mục tiêu được giao.\nGiữ mối quan hệ mật thiết với khách hàng bằng cách thường xuyên thăm hỏi, nhanh chóng phản hồi những yêu cầu của khách hàng.\nChủ động theo dõi giám sát các dự án được phân công bằng cách phối hợp với Bộ phận Tư Vấn Thiết Kế (Spec), Project Sales, Sales Admin và nhà phân phối để đạt tỷ lệ trúng thầu cao.\nThực hiện các công việc khác theo phân công của cấp quản lý.', 'Tốt nghiệp Cao Đẳng , ĐH trở lên, ưu tiên các khối ngành Điện tử Viễn Thông , CNTT, Kinh tế Công nghệ , Kỹ thuật , Xây dựng…\nKinh nghiệm KD : 01 năm. Ưu tiên đã có kinh nghiệm sale trong ngành thiết bị điện tử truyền thông, lĩnh vực điện nhẹ ELV (CCTV, Access control, Video Intercom, PA,Carparking …)\nPhần mềm tích hợp An Ninh ,Hệ thống Mạng \nPhân phối các sản Phẩm Điện nhẹ : Suprema , CMITECH , HiKvision , Optex, Klocker, AI - VMS\nTiếng Anh -Tốt là lợi thế\nThành thạo tin học văn phòng: Outlook, Word, Excel, Power point.', 10000000.00, 40000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(66, 59, 62, 'Nhân Viên Kinh Doanh - Tư Vấn Căn Hộ Tại Nam Từ Liêm - Hà Nội', 'Sản phẩm: Các dự án Vinhomes Ocean Park 1,2,3, Masteries Homes, Vinhomes Smart City, các dự án ven biển, Phú Quốc,…\n· Tìm kiếm, tiếp cận khách hàng tiềm năng, và giới thiệu cho khách hàng về các sản phẩm mà công ty đang phân phối.\n· Đào tạo, hỗ trợ đội nhóm bán hàng theo chủ chương chính sách của CĐT, Đại lý\n· Thực hiện các hoạt động khác của Chủ đầu tư liên quan đến hoạt động kinh doanh BĐS\n· Hỗ trợ KH hoàn thiện thủ tục mua bán BDS và tiến hành chăm sóc KH sau bán.\nThời gian làm việc giờ hành chính: Thứ 2 - Thứ 7 (Sáng 09:00-12:00, Chiều 14:00-17:00)', '· KHÔNG yêu cầu kinh nghiệm, có hỗ trợ đào tạo\n· Tinh thần trách nhiệm cao với công việc\n· Năng động, chịu khó học hỏi\n· Ưu tiên có kinh nghiệm từ 1 năm trở lên.', 10000000.00, 60000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(67, 60, 63, 'Sales Digital', '1. Nghiên cứu và phát triển sản phẩm \nNghiên cứu và nắm rõ các sản phẩm hiện có và xu hướng tương lai của thị trường.\nTìm hiểu, phân tích thị trường, đối thủ cạnh tranh và xu hướng người dùng sản phẩm số, để từ đó đưa ra các đề xuất, kế hoạch để cải tiến các sản phẩm hiện có và phát triển các sản phẩm mới phù hợp với nhu cầu thực tế của thị trường và người dùng\n2. Tư vấn sản phẩm \nĐối với khách hàng tiềm năng: Cần tìm hiểu và nắm rõ nhu cầu, khó khăn và mong muốn của khách hàng để từ đó tư vấn khách hàng sử dụng hoặc chuyển sang sử dụng những sản phẩm ưu việt của Công ty mình.\nĐối với khách hàng đang sử dụng sản phẩm của công ty: Cần sát sao hỗ trợ khách hàng (tập huấn giáo viên, tập huấn nhân viên, hướng dẫn cách sử dụng, chuyển giao các tài liệu bổ trợ cần thiết theo sự cho phép của BGĐ Công ty)\nTiếp nhận và xử lý các feedback của khách hàng về sản phẩm.\n3. Hội thảo, tập huấn và giới thiệu sản phẩm\n Chuẩn bị hội thảo và thực hiện hội thảo (Kế hoạch, campaign, vật phẩm marketing, sách trưng bày, hội trường, công tác tổ chức, điều phối nhân sự, trang thiết bị, giảng viên tập huấn, nội dung hội thảo, nội dung trainer trình bày, banner, backdrop, âm thanh, ánh sáng, biểu mẫu feedback).\nChuẩn bị slide tập huấn chuyên môn hoặc giới thiệu về sản phẩm theo nhu cầu thực tế.\nGiới thiệu công ty và sản phẩm digital của công ty một cách khoa học, chỉn chu và ấn tượng tại hội thảo.\nTạo lập hình ảnh DTP chuyên nghiệp trong hội thảo đối với khách hàng.\n4. Thúc đẩy bán hàng\n Nghiên cứu thị trường và đối thủ cạnh tranh để xây dựng kế hoạch kinh doanh hiệu quả và đề xuất các chiến lược nhằm đạt được mục tiêu doanh số đã đề ra.\nTìm kiếm và xây dựng mối quan hệ với khách hàng tiềm năng qua nhiều kênh khác nhau như dữ liệu nội bộ, mạng xã hội, sự kiện, giúp mở rộng mạng lưới khách hàng.\nGiới thiệu, tư vấn sản phẩm/dịch vụ và giải đáp thắc mắc cho khách hàng nhằm thuyết phục họ sử dụng sản phẩm, dịch vụ của doanh nghiệp.\nĐàm phán và ký kết hợp đồng với khách hàng, bao gồm các điều khoản về giá cả, thanh toán và thời gian giao hàng.\nLên ý tưởng và triển khai các chương trình khuyến mãi, hậu mãi nhằm thúc đẩy doanh số và duy trì mối quan hệ lâu dài với khách hàng\n5. Hoạt động chung của bộ phận và tổ chức \nTham gia các buổi tập huấn/ chia sẻ SẢN PHẨM, kinh nghiệm của BP/đơn vị.\nTham gia nghiên cứu đánh giá SẢN PHẨM mới.\nTham gia xây dựng kế hoạch phát triển BP.\nXây dựng kế hoạch Kinh doanh của KV.\nTập huấn cho nhân viên mới của đơn vị.\nTập huấn cho nhân viên mới của bộ phận.\nBáo cáo tình hình của khách hàng mình quản lý khi có yêu cầu.\nTham gia các công việc khác của đơn vị, bộ phận theo sự điều động của quản lý bộ phận.\n6. Chịu trách nhiệm hỗ trợ IT Văn phòng', '- Tốt nghiệp Cao Đẳng, Đại Học chuyên ngành Quản Trị Kinh Doanh, Marketing, Kinh tế, Sư phạm hoặc các chuyên ngành có liên quan\n- Tin học văn phòng\n- Tiếng Anh giao tiếp\n- Có kỹ năng bán hàng, giao tiếp, xử lý tình huống, tổ chức, phối hợp.\n- Có kinh nghiệm từ 3 năm trở lên, ưu tiên có kinh nghiệm trong các ngành Bảo hiểm, FMCG, các ngành có liên quan...\n- Đạo đức tốt, trung thực, linh hoạt, nhanh nhẹn, chịu khó, chịu được áp lực cao, nhiệt tình, có đam mê hoài bão, có trách nhiệm cao với công việc.', 9000000.00, 11000000.00, 'Phú Thọ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(68, 61, 64, 'Nhân Viên Editor', 'Chỉnh sửa và tạo video ngắn, trailer game từ các cảnh quay có sẵn trên các nền tảng social: TikTok, Facebook, Instagram,… (Chủ yếu là Tiktok)\nThêm hiệu ứng âm thanh, hình ảnh để nâng cao chất lượng video.\nPhối hợp với đội ngũ để lên ý tưởng và triển khai các dự án video.\nĐảm bảo các video tuân thủ các tiêu chuẩn về chất lượng và thương hiệu của công ty.\nCập nhật và duy trì các xu hướng mới nhất.', 'Kinh nghiệm từ 06 tháng trong lĩnh vực chỉnh sửa video, ưu tiên có kinh nghiệm trong ngành game. (Nếu bạn chưa có kinh nghiệm nhiều nhưng tự tin với skills của mình thì cứ mạnh dạn gửi portfolio nhé)\nSử dụng thành thạo các phần mềm chỉnh sửa video như Capcut, Adobe Premiere hoặc các công cụ tương đương. (Biết sử dụng các phần mềm như: Ae, Ps,…  Là một lợi thế)\nGửi CV kèm Portfolio/sản phẩm cá nhân.\nCó kỹ năng sáng tạo và tư duy tốt.\nHiểu biết về các xu hướng video ngắn.\nKỹ năng tổ chức và quản lý thời gian tốt để hoàn thành dự án đúng hạn.\nCó khả năng làm việc độc lập và làm việc nhóm hiệu quả.\nCẩn thận, chỉn chu, nhiệt huyết và chủ động trách nhiệm trong công việc, đảm bảo công việc đúng deadline.\nCó tinh thần học hỏi, cầu tiến.', 7000000.00, 13000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(69, 62, 65, 'Ai Engineer / Kỹ Sư Ai', 'Nghiên cứu và xây dựng các mô hình AI/ML và triển khai mô hình AI vào môi trường văn phòng\nĐảm bảo an toàn, bảo mật dữ liệu và hệ thống.\nTriển khai các công cụ AI hỗ trợ sản xuất nội dung\nCác công việc khác theo chuyên môn do quản lý yêu cầu', 'Tốt nghiệp Đại học các chuyên ngành: Công nghệ thông tin, Lập trình ,Khoa học máy tính, Công nghệ phần mềm, Hệ thống thông tin, Toán ứng dụng....\nCó kiến thức lập trình cơ bản, ưu tiên các bạn thành thạo C/C++ hoặc Python\nSử dụng thành thạo các ứng dụng sử dụng AI\nCó khả năng độc hiểu tài liệu bằng tiếng anh\nTư duy logic, kỹ năng phân tích và giải quyết vấn đề.\nChủ động, sáng tạo, ham học hỏi công nghệ mới.', 8000000.00, 20000000.00, 'Hải Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(70, 63, 66, 'Nhân Viên Tester', '- Thực hiện kiểm thử phần mềm theo yêu cầu của dự án Game/Web/App\n- Viết test case, test plan dựa trên tài liệu yêu cầu hoặc hướng dẫn của team BA/PM.\n- Thực hiện test manual, báo cáo bug và theo dõi quá trình fix bug.\n- Phối hợp với đội phát triển để đảm bảo chất lượng sản phẩm.\n- Thực hiện kiểm thử hồi quy khi có phiên bản cập nhật.\n- Viết tài liệu hướng dẫn sử dụng phần mềm khi cần.\n- Trao đổi với đối tác telco trong và ngoài nước.', '- Tối thiểu 2 năm Kinh nghiệm ở vị trí Tester\n- Tốt nghiệp chuyên ngành CNTT, Khoa học máy tính hoặc các ngành liên quan.\n- Có kiến thức kinh nghiệm về kiểm thử phần mềm, quy trình phát triển phần mềm (SDLC, STLC).\n- Biết cách viết test case, test scenario và báo cáo bug.\n- Kỹ năng giao tiếp, làm việc nhóm tốt.\n- Có trách nhiệm, tỉ mỉ, cẩn thận trong công việc.\n- Ứng viên có thể làm việc full-time, sẵn sàng hỗ trợ đối tác nước ngoài.', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(71, 64, 67, 'Nhân Viên Kiểm Thử Tester', '- Thực hiện kiểm thử phần mềm theo yêu cầu của dự án Game/Web/App\n- Viết test case, test plan dựa trên tài liệu yêu cầu hoặc hướng dẫn của team BA/PM.\n- Thực hiện test manual, báo cáo bug và theo dõi quá trình fix bug.\n- Phối hợp với đội phát triển để đảm bảo chất lượng sản phẩm.\n- Thực hiện kiểm thử hồi quy khi có phiên bản cập nhật.\n- Viết tài liệu hướng dẫn sử dụng phần mềm khi cần.\n- Trao đổi với đối tác telco trong và ngoài nước.', '- Tối thiểu 2 năm Kinh nghiệm ở vị trí Tester\n- Tốt nghiệp chuyên ngành CNTT, Khoa học máy tính hoặc các ngành liên quan.\n- Có kiến thức kinh nghiệm về kiểm thử phần mềm, quy trình phát triển phần mềm (SDLC, STLC).\n- Biết cách viết test case, test scenario và báo cáo bug.\n- Kỹ năng giao tiếp, làm việc nhóm tốt.\n- Có trách nhiệm, tỉ mỉ, cẩn thận trong công việc.\n- Ứng viên có thể làm việc full-time, sẵn sàng hỗ trợ đối tác nước ngoài.', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(72, 65, 68, 'Nhân Viên Kinh Doanh Công Nghệ Thông Tin', 'Tìm kiếm và phát triển khách hàng mới, duy trì mối quan hệ với khách hàng hiện tại để tăng doanh số bán hàng.\nThực hiện các cuộc gọi điện thoại, gặp gỡ trực tiếp và gửi email để giới thiệu và tư vấn sản phẩm/dịch vụ của công ty đến khách hàng. Ưu tiên người có kiến thức về Công nghệ thông tin.\nTiếp nhận thông tin, nhu cầu của khách hàng và thực hiện các công việc liên quan: Báo giá, lên đơn đặt hàng, xác nhận đơn hàng, xử lí vấn đề phát sinh. Kí hợp đồng, chốt hợp đồng, thanh lý hợp đồng với khách hàng.\nLập kế hoạch và báo cáo doanh số bán hàng hàng tháng, theo dõi tiến độ và điều chỉnh kế hoạch khi cần thiết.\nTuyệt đối giữ bí mật về nguồn dữ liệu Khách hàng.\nTham gia vào các sự kiện, hội thảo và triển lãm để quảng bá thương hiệu và mở rộng mạng lưới khách hàng.\nThực hiện những nhiệm vụ khác do Trưởng / Phó Bộ phận hoặc Ban Giám Đốc trực tiếp giao phó. (Thông tin chi tiết sẽ trao đổi tại buổi phỏng vấn)', 'Tốt nghiệp Đại học/Cao đẳng/Trung cấp chuyên ngành Kinh tế/ QTKD/ Điện tử Viễn Thông/ CNTT hoặc các ngành liên quan.\nƯu tiên độ tuổi 23-40\nNgoại hình ưa nhìn, sạch sẽ, gọn gàng.\nCó kinh nghiệm trong lĩnh vực Công nghệ thông tin là một lợi thế.\nSử dụng thành thạo các công cụ văn phòng, đặc biệt là Word và Excel.\nKỹ năng giao tiếp và thuyết phục tốt, có khả năng xây dựng mối quan hệ với khách hàng.\nCó khả năng làm việc độc lập và theo nhóm, chịu áp lực cao trong công việc.\nTrung thực, nhiệt tình, đam mê kinh doanh, có tinh thần cầu tiến, sẵn sàng học hỏi và phát triển bản thân trong lĩnh vực kinh doanh.', 10000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(73, 66, 69, 'Nhân Viên Kiểm Thử Phần Mềm (Tester)', '- Hiểu nghiệp vụ và yêu cầu dự án.\n- Lập kế hoạch Test, thiết kế Test Case, thực hiện Test.\n- Theo dõi, tổng hợp, đánh giá và báo cáo kết quả Test cho các bên liên quan.\n- Là cầu nối giữa các thành viên trong team.', '- Bắt buộc: Có tiếng Nhật từ N3 trở lên\n- Có hiểu biết về sử dụng phần mềm\n- Yêu thích công việc, ham học hỏi, có tinh thần trách nhiệm cao, tỷ mỷ, cẩn thận.\n- Có kinh nghiệm từ 1 năm trở lên', 8000000.00, 81000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(74, 67, 70, 'Nhân Viên IT Helpdesk', 'Công việc chính:\nHỗ trợ các Phòng ban tại công ty xử lý các yêu cầu công việc về hạ tầng công nghệ thông tin, gồm: Email, Network, Windows, Printers, Firewall, Điện thoại và các thiết bị ngoại viPhối hợp với các Phòng ban tại công ty quản lý, bàn giao và thu hồi các thiết bị, máy tính, công cụ dụng cụ tại sàn.\nGiám sát và quản trị hệ thống mạng LAN và máy tính văn phòng tại Công ty.\nQuản lý các thiết bị ngoại vi phục vụ công việc liên quan đến IT: Máy in, máy tính bảng, laptop,… Hỗ trợ các tác vụ người dùng: Email, Internet,…\nHướng dẫn các phòng ban sử dụng phần mềm, phần cứng IT phục vụ cho công việc.\nSao lưu, phục hồi dữ liệu quan trọng của Công ty.\nCác công việc khác được phân bởi quản lý trực tiếp.\nCông việc khác:\nThu thập, nhập liệu, thống kê, gửi/ lưu trữ hồ sơ nhân viên về HO theo yêu cầu.\nThu thập và tổng hợp hồ sơ nhân sự tại chi nhánh gửi về công ty.\nCác công việc hỗ trợ khác.', 'Tốt nghiệp Đại học/ Cao đẳng, chuyên ngành liên quan tới IT.\nTối thiểu 01 năm kinh nghiệm làm công việc ở các vị trí tương tự.\nCó kinh nghiệm quản lý Windows Servers, Domain Controllers, Windows Mail Servers, cài đặt phần mềm ứng dụng.\nAm hiểu vè biết cài đặt, quản trị mạng LAN, kết nối internet.\nCó kiến thức, kinh nghiệm về Linux là lợi thế.\nKhả năng làm việc nhóm tốt.', 8000000.00, 10000000.00, 'Quảng Ngãi', 'Internship', '2025-10-07 20:59:18.149534'),
	(75, 68, 71, 'Fullstack Developer Middle Level (Salary: 23M)', 'Use best practices and technologies to develop large SPAs for various users and platforms.\nEnsure high-quality, performant, and reusable code.\nDeveloping, testing, and debugging responsive web applications.\nDesign web application solutions, ensuring scalability, performance, and maintainability.\nIdentify and mitigate technical risks and bottlenecks, proposing alternative solutions when necessary.\nWrite documents, code reviewing and support technical for junior members.\nStay up-to-date with the latest web development trends and technologies and assess their suitability for the project', 'Must have:\n3 years of experience programming with ReactJS, NodeJS.\nHaving proficiency in both frontend and backend.\nExperience designing and developing RESTful web services.\nExperience with delivering and maintaining applications.\nBe able to write clean, performance-centric, reusable, and understandable code with unit tests.\nHands-on experience with Git.\nExperience working on databases, specifically MongoDB.\nWorking with both client and server-side experimentation/personalization and able to provide optimized solutions for each problem respectively.\nGood knowledge about data structures and algorithms.\nBe structured, solution-oriented, own quality mindset, good problem-solving skills,  eagerness to learn, and curiosity.\nHave good communication skills, have experience with technical coaching and mentoring work.\nGood command of English (Listening, Reading, Writing).\nNice to have:\nPrevious product company experience.\nExpertise in web optimization, security, and user behavior tracking.\nFamiliar with Agile development methods, especially Scrum.\nHaving knowledge of Clean Code, popular software development principles.\nHave experience in improving performance by using caching, indexing, maintenance, and optimizing query.\nExperienced in developing distributed systems on top of microservices architecture, event-driven architecture using NodeJs, Kafka, RabbitMQ, ETC. is highly welcome.\nFamiliarity with cloud platforms such as AWS or GCP.\nHaving knowledge of CI/CD, container orchestration platforms (ECS, Kubernetes, Docker) is a big plus.\nExperienced in automated testing frameworks is a plus.', 23000000.00, 30000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(76, 69, 72, 'Thực Tập Sinh IT', '•    WMS\n•    Hạ tầng Wifi kho và văn phòng\n•    Face ID \n•    Hệ thống chống trộm BIM\n•    Triển khai thử nghiệm AI để kiểm soát các khâu sản xuất, QLCL, HR\n•    Triển khai hệ thống ghi nhận số liệu chất lượng, dây chuyền sản xuất, và định hướng phát triển automation scada trong dây chuyền sản xuất, hệ thống MES\n*Thời gian làm việc: Giờ hành chính: 8h – 17h (T2 – T6), làm việc 2 ngày thứ 7 / tháng\n* Địa điểm làm việc: Nhà máy VIFON – Chi nhánh Hải Dương, KCN Tân Trường, Mao Điền, TP. Hải Phòng. ( Địa chỉ cũ: Tân Trường,Cẩm Giàng, Hải Dương)', '•    Sinh viên năm cuối hoặc mới tốt nghiệp các ngành: CNTT, Khoa học máy tính, Mạng máy tính, Hệ thống thông tin...\n•    Có kiến thức cơ bản về phần cứng máy tính, mạng LAN/WAN, hệ điều hành Windows.\n•    Nhanh nhẹn, ham học hỏi, chịu khó và có tinh thần trách nhiệm.\n•    Có thể thực tập tối thiểu 3 tháng.', 1000000.00, 3000000.00, 'Hải Dương,', 'Internship', '2025-10-07 20:59:18.149534'),
	(77, 70, 73, 'Kỹ Sư Presale', '- Tư vấn, khảo sát, thiết kế giải pháp hạ tầng CNTT cho khách hàng doanh nghiệp (Server, Storage, Network, Ảo hóa, Cloud, Data Center...).\n- Phối hợp với đội ngũ kinh doanh để làm rõ yêu cầu khách hàng, đề xuất giải pháp kỹ thuật phù hợp với nhu cầu thực tế.\n- Viết tài liệu giải pháp, tài liệu thuyết minh, demo PoC, lên cấu hình thiết bị và lập BoM.\n- Tham gia trình bày, bảo vệ giải pháp trước khách hàng (trực tiếp/online), trả lời các câu hỏi chuyên sâu về kỹ thuật.\n- Cập nhật kiến thức sản phẩm mới từ các hãng, thường xuyên tham gia đào tạo, sự kiện, workshop về công nghệ.\n- Hỗ trợ các bộ phận kỹ thuật trong quá trình triển khai dự án khi cần thiết.\n- Làm hồ sơ kỹ thuật, đáp ứng yêu cầu đấu thầu, so sánh thiết bị và báo giá.', '- Tốt nghiệp Đại học chuyên ngành CNTT, Điện tử Viễn thông hoặc tương đương.\n- Có 2 - 3 năm kinh nghiệm thực tế ở vị trí Presale/System Engineer trong lĩnh vực SI (System Integrator).\n- Hiểu biết vững về hệ thống Server, Storage, Network, Ảo hóa (VMware/Hyper-V), giải pháp Backup, HA, DR, Microsoft, Linux...\n- Ưu tiên có chứng chỉ kỹ thuật (MCSE, VCP, CCNA, HPE, Dell, Lenovo, NetApp, Huawei...).\n- Kỹ năng giao tiếp tốt, trình bày giải pháp rõ ràng, biết lắng nghe và khai thác nhu cầu khách hàng.\n- Khả năng viết tài liệu, thuyết trình tốt (có demo hoặc dẫn chứng dự án thực tế là lợi thế).\n- Tinh thần trách nhiệm, chủ động cập nhật kiến thức, làm việc teamwork tốt.\n- Đọc hiểu tài liệu tiếng Anh chuyên ngành.', 15000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(78, 71, 74, 'Business Analytics Executive (Hn / HCM)', 'Gather business and system requirements from partner (Singapore, Japan, Thailand, Hongkong, Indonesia, India...) in finance field.\nUnderstand and analyze the requirements from partner in business view and end-user view.\nWrite Basic Design based on analyzed requirements.\nWork with development team to go over the specification, Q&A, consult the solutions or figure out the problems.\nSupport the project manager in assigning tasks and managing the team to make sure that the project runs smoothly.\nSupport in testing, verifying bugs/issue before handover to Client.', 'Graduated from University in Information Technology, Business, Finance or a related discipline.\nAt least 2-3 year of experience in BA position.\nHave good logical and flexible thinking.\nExperience in developing projects related to finance, blockchains is an advantage.\nGood at English (Proficient all 4 skills).', 15000000.00, 45000000.00, 'Hà Nội,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(79, 72, 75, 'System Engineer', 'Chịu trách nhiệm chính trong việc xây dựng, tối ưu và đảm bảo sự vận hành ổn định của các hệ thống hạ tầng trọng yếu.\nQuản trị và Tối ưu hóa Hạ tầng Cloud Native:\nChịu trách nhiệm chính trong việc thiết kế, triển khai và vận hành các cluster Kubernetes quy mô lớn trên môi trường on-premise và Private Cloud (OpenStack).\nChủ động đề xuất và triển khai các giải pháp nhằm tối ưu hiệu năng, chi phí và tăng cường bảo mật cho hệ thống Kubernetes.\nTự động hóa toàn diện (Automation & IaC):\nDẫn dắt việc áp dụng Infrastructure as Code (IaC) một cách sâu rộng, sử dụng Terraform và Ansible để quản lý và tự động hóa toàn bộ vòng đời của hạ tầng.\nThiết kế, xây dựng và tối ưu hóa các pipeline CI/CD phức tạp (GitLab CI, Jenkins, ArgoCD), giúp rút ngắn thời gian triển khai và giảm thiểu rủi ro.\nXây dựng Hệ thống giám sát và Đảm bảo độ tin cậy (SRE):\nSở hữu (own) và phát triển hệ thống giám sát, logging, tracing tập trung (Prometheus, Grafana, ELK Stack) để đảm bảo khả năng quan sát (observability) toàn diện cho hệ thống.\nThiết kế và thực thi các giải pháp High Availability (HA) và Disaster Recovery (DR), đảm bảo hệ thống đáp ứng các cam kết SLA nghiêm ngặt.\nChia sẻ kiến thức & Cải tiến liên tục:\nChia sẻ kiến thức, kinh nghiệm và hỗ trợ các thành viên khác trong nhóm để cùng phát triển.\nNghiên cứu, đánh giá và thử nghiệm các công nghệ mới để đưa vào áp dụng thực tế.', 'Kinh nghiệm: Có ít nhất 03 năm kinh nghiệm làm việc ở vị trí DevOps Engineer/ System Engineer hoặc các vai trò tương đương.\nChuyên môn sâu (Core Skills):\nLinux: Quản trị thành thạo hệ điều hành Linux (CentOS, Ubuntu,...).\nContainerization: Kinh nghiệm sâu trong việc quản trị, vận hành và xử lý sự cố các cluster Kubernetes ở môi trường production.\nInfrastructure as Code (IaC): Thành thạo sử dụng Terraform và Ansible để tự động hóa hạ tầng.\nCI/CD: Có kinh nghiệm xây dựng và tối ưu hóa các pipeline CI/CD phức tạp với các công cụ như GitLab CI, Jenkins, ArgoCD.\nMonitoring: Kinh nghiệm dày dặn trong việc xây dựng và vận hành hệ thống giám sát với Prometheus, Grafana, ELK Stack.\nKiến thức nền tảng vững chắc:\nHiểu biết sâu sắc về mạng máy tính (TCP/IP, DNS, HTTP/HTTPS, Load Balancing).\nHiểu rõ về kiến trúc microservices và các thách thức khi vận hành chúng.', 25000000.00, 45000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(80, 73, 76, 'Intern Security - SE', 'Position Summary \n• The System Engineer role of this project will be responsible for all tasks related to operation and monitoring within SIEM and SOAR. This role will serve as an important cornerstone in achieving reinforcement of security threat detection operations over the next few years. \nResponsibilities\n• Real-time security threats monitoring for SAP services located in SCP\n• Issuing an alert ticket depending on the analysis results and checking the personnel’s countermeasures, when detecting anomalies\n• Response to inquiries from SAP service manager', 'Requirements for Intern/Fresher:\n• Last-year students or graduates major in technology and able to join full-time training courses.\n• GPA at least ~ 2.5/4.0\n• Able to communicate in English and have English comprehension (~ from B1 level and above).\n• Able to work flexibly and meet deadlines, willing to acquire updated technology as customers require.\n[Minimum Qualifications]\n• Basic IT knowledge with NW protocols, OS (Linux, Windows), Cloud, ETC.\n• Majored/experienced in computer science or IT security\n• Work on weekends and holidays\n• Active attitude to be willing to learn security monitoring with responsibility\n• Communicate simply in English\n[Preferred Qualifications]\n• Basic knowledge of Cloud environment especially SCP\n• Basic IT Security knowledge\n• Malware, EDR, internal anomalies, ETC.\n• Related experiences in internal anomalies inspection and malicious code analysis\n• Experience with using SIEM and SOAR', 49000000.00, 10000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(81, 74, 77, 'Business Analyst (Ba) - Up To 35M', 'Thực hiện phân tích quy trình kinh doanh toàn diện để xác định nhu cầu, mục tiêu và thách thức của khách hàng đối với các dự án quy mô nhỏ.\nPhân tích các yêu cầu và thông số kỹ thuật hệ thống chi tiết dựa trên nhu cầu của khách hàng.\nCung cấp hướng dẫn chuyên môn về các phương pháp hay nhất của ERP, cấu hình hệ thống và tối ưu hóa quy trình.\nTham gia các dự án phân tích và triển khai quy mô nhỏ, bao gồm thu thập yêu cầu, thiết lập hệ thống, cấu hình và tùy chỉnh hệ thống để phù hợp với quy trình kinh doanh của khách hàng.\nTạo và duy trì các kế hoạch, lịch trình và báo cáo trạng thái dự án chi tiết.\nHoàn thành dự án đúng thời hạn, trong phạm vi ngân sách và đáp ứng các tiêu chuẩn chất lượng và kỳ vọng của khách hàng.\nTham gia phát triển và triển khai các chiến lược quản lý thay đổi để thúc đẩy người dùng áp dụng hệ thống ERP.\nCung cấp hỗ trợ liên tục và khắc phục sự cố của khách hàng sau khi triển khai một cách kịp thời.\nĐóng góp vào các hoạt động chia SẺ kiến thức và đảm bảo các sản phẩm chất lượng cao trong các dự án.', 'Bằng cử nhân Khoa học máy tính, Công nghệ thông tin hoặc lĩnh vực liên quan.\nCó tối thiểu 3 năm kinh nghiệm, thành thạo Tiếng Anh.\nCó kiến thức tốt về các hệ thống ERP hàng đầu (ví dụ: Odoo, SAP, Oracle, Microsoft Dynamics, NetSuite) và các công nghệ liên quan. Ưu tiên kiến thức triển khai Odoo.\nKỹ năng giao tiếp, thuyết trình và quan hệ giữa các cá nhân bằng tiếng Anh.\nKhả năng làm việc độc lập và hợp tác trong môi trường làm việc nhanh, tập trung vào khách hàng.\nƯu tiên có kinh nghiệm trước đây trong tư vấn ERP, với thành tích đã được chứng minh về việc triển khai dự án thành công.\nƯu tiên hiểu biết tốt về các quy trình kinh doanh trong nhiều ngành khác nhau.\nƯu tiên có kinh nghiệm triển khai ERP, lý tưởng nhất là với phần mềm nổi bật và được sử dụng rộng rãi nhất trong ngành như Odoo (ưu tiên).', 25000000.00, 35000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(82, 75, 78, 'Kỹ Thuật Viên Máy Tính, Máy In', '- Cài đặt hệ điều hành và các phần mềm văn phòng, lắp đặt, tháo lắp máy tính bàn và laptop…\n- Sửa chữa các lỗi cơ bản của máy in', '- Học về ngành công nghệ thông tin từ trung cấp trở lên, biết cài đặt hệ điều hành và các phần mềm văn phòng, biết lắp đặt, tháo lắp máy tính bàn và laptop… \n- Ưu tiên: các bạn đã thực tập và làm việc tại công ty máy tính\n- Hỗ trợ đào tạo và hướng dẫn các bạn sinh viên mới ra trường nếu có nhiệt huyết và xác định công việc lâu dài.', 10000000.00, 15000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(83, 9, 12, 'Data Engineer', 'Thiết kế và triển khai các pipeline xử lý dữ liệu có khả năng mở rộng và bảo mật, sử dụng Azure Data Factory, Azure Databricks và các dịch vụ khác của Azure.\nQuản lý và tối ưu hóa lưu trữ dữ liệu bằng Azure Data Lake Storage, Azure SQL Data Warehouse và Azure Cosmos DB.\nPhát triển mô hình dữ liệu và duy trì kiến trúc dữ liệu nhằm hỗ trợ phân tích dữ liệu và báo cáo thông minh doanh nghiệp (BI).\nĐảm bảo chất lượng và tính nhất quán của dữ liệu thông qua các quy trình làm sạch, chuyển đổi và tích hợp dữ liệu.\nGiám sát và xử lý sự cố liên quan đến dữ liệu trong môi trường Azure để đảm bảo hiệu suất và tính sẵn sàng cao.\nHợp tác với các nhà khoa học dữ liệu, chuyên viên phân tích kinh doanh và các bên liên quan để hiểu rõ yêu cầu và triển khai giải pháp dữ liệu phù hợp.\nTriển khai các biện pháp bảo mật dữ liệu như mã hóa, kiểm soát truy cập và ghi nhật ký để bảo vệ thông tin.\nTự động hóa các pipeline và quy trình xử lý dữ liệu để tối ưu hóa việc thu thập, xử lý và phân phối dữ liệu.\nSử dụng các dịch vụ phân tích của Azure, như Azure Synapse Analytics, để cung cấp thông tin và hỗ trợ ra quyết định dựa trên dữ liệu.\nLuôn cập nhật các tính năng và công nghệ mới của Azure để cải tiến quy trình kỹ thuật dữ liệu.\nTài liệu hóa quy trình, hệ thống và kiến trúc dữ liệu để đảm bảo rõ ràng và tuân thủ các quy định.\nHỗ trợ và hướng dẫn trong quản trị dữ liệu, bao gồm quản lý metadata, truy xuất nguồn gốc dữ liệu (data lineage) và xây dựng danh mục dữ liệu (data catalog).', 'Tốt nghiệp đại học chuyên ngành Khoa học Máy tính, Công nghệ Thông tin hoặc lĩnh vực liên quan (hoặc có kinh nghiệm tương đương).\nCó kinh nghiệm làm việc ở vị trí Kỹ sư Dữ liệu (Data Engineer), tập trung vào dịch vụ đám mây Azure.\nHiểu rõ các nguyên tắc CI/CD và có kinh nghiệm với các pipeline của Azure Data Engineer.\nThành thạo các ngôn ngữ scripting như PowerShell, Bash hoặc Python.\nCó kinh nghiệm làm việc với các công cụ container hóa và điều phối như Docker và Kubernetes.\nQuen thuộc với các hệ thống quản lý mã nguồn, đặc biệt là Git.\nKỹ năng giải quyết vấn đề tốt và có khả năng làm việc hiệu quả trong môi trường nhóm.', 35000000.00, 45000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(84, 76, 79, 'Thiết Kế 3D', '- Triển khai bản vẻ thi công\n- Thiết kế 3D nội, ngoại thất\n- Sử dụng phần mềm sketchup, autocad 2D\n- Các công việc khác sẽ trao đổi thêm trong buổi phỏng vấn', '- Kinh nghiệm 1 năm\n- Biết sử dụng các công cụ xử lý hình ảnh (sketchup)\n- Có ý tưởng sáng tạo trong thiết kế, am hiểu về các mẫu thiết kế, cập nhật các xu hướng hiện tại.', 9000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(85, 77, 80, 'Nhân Viên Tư Vấn Giải Pháp Erp', 'Thu thập phân tích các yêu cầu nghiệp vụ tại đơn vị khách hàng để xây dựng và xác nhận tài liệu khảo sát, tài liệu chỉnh sửa…\nTạo yêu cầu lập trình và phối hợp với bộ phận Lập trình đảm bảo phần mềm đáp ứng đúng yêu cầu đã xác nhận với khách hàng.\nThực hiện test nghiệp vụ để kiểm tra tính chính xác của sản phẩm chỉnh sửa so với tài liệu yêu cầu.\nĐề xuất các giải pháp tối ưu hóa quy trình nghiệp vụ.\nTheo dõi và quản lý tiến độ thực hiện dự án.\nBáo cáo tiến độ công việc cho quản lý.', 'Giới tính: Nam, từ 24 - 28 tuổi.\nTốt nghiệp đại học chuyên ngành Kế toán Kiểm toán, Hệ thống thông tin, Tin học tài chính kế toán.\nVững nghiệp vụ kế toán (có thể sử dụng được truy vấn SQL là một lợi thế)\nCó khả năng phân tích, tổng hợp thông tin tốt.\nChăm chỉ, nhiệt tình, nhanh nhẹn, giao tiếp tốt, làm việc nhóm hiệu quả và chịu được áp lực công việc cao.\nSử dụng các công cụ hỗ trợ phân tích nghiệp vụ là một lợi thế.\nƯu tiên ứng viên có kinh nghiệm làm việc trong lĩnh vực tài chính, kế toán hoặc triển khai phần mềm kế toán, ERP.', 8000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(86, 78, 81, 'Technical Lead Fullstack', 'Solicit requirements from clients through workshops, site surveys, and solution design. This may include integration with the systems of clients.\nLead a team of 2–5 engineers in design, development, testing, and deployment, coordinating tasks between the Middle East and Vietnam teams.\nCollaborate with internal and external suppliers for system integration.\nDefine work breakdown for the team, for project tracking and reporting\nWork with the Middle East project team for project management reporting\nFamiliar and experienced with IoT platform\nHandle change requests and error management while maintaining high-quality deliverables.\nRelease management including version control for integration coordination, Test, and Site Installation', 'Have a good working knowledge and/or experience in workflow/business processes definitions, as well as API, messaging, OPC, SCADA integrations\nAt least 7 years in system integration, technical design\nExperience leading IT/OT system integration projects.\nUnderstand the concept of layered architectures, components, interfaces, messaging, and patterns\nFamiliar with software design and development, including DevSecOps processes and configuration/change processes in a large-scale system environment.\nA good communicator, planner, documentation writer, and able to motivate the team\nPrimary programming language is JavaScript, utilizing technologies such as Node.js and ReactJS\nFluent English', 50000000.00, 70000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(87, 79, 82, 'Cộng Tác Viên Sales - Mức Hoa Hồng Cố Định 30% Mỗi Tháng', 'Chủ động tìm kiếm và xây dựng mối quan hệ với các khách hàng tiềm năng.\nGiới thiệu, tư vấn chi tiết về các sản phẩm/dịch vụ của công ty, đảm bảo khách hàng hiểu rõ giá trị và lợi ích.\nThuyết phục khách hàng và hoàn tất thủ tục ký kết hợp đồng.', 'Có khả năng giao tiếp, thuyết phục và xây dựng mối quan hệ tốt.\nĐảm bảo làm việc ít nhất 3-4 giờ mỗi ngày để đạt được hiệu quả công việc.\nCó bằng Trung cấp trở lên.', 5000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(88, 80, 83, 'System Engineer', '- Thiết kế, kiểm thử, triển khai và giám sát các biện pháp bảo mật cho hệ thống của công ty;\n- Xây dựng quy trình làm việc để duy trì hệ thống mạng trong bộ phận IT;\n- Quản lý hoạt động an ninh nhằm bảo vệ máy tính, mạng và dữ liệu của tổ chức khỏi virus, các vi phạm bảo mật và các cuộc tấn công từ hacker độc hại;\n- Quản lý hệ thống sao lưu và bảo mật, đảm bảo khả năng khôi phục dữ liệu trong trường hợp xảy ra sự cố, đồng thời giám sát và xử lý các vi phạm bảo mật;\n- Hỗ trợ đội phát triển trong việc triển khai ứng dụng trên hệ thống Unix/Linux;\n- Đề xuất và triển khai các công cụ để quản lý tuân thủ, kiểm toán và chức năng quản lý lỗ hổng bảo mật;\n- Phối hợp với các bộ phận liên quan để xây dựng và duy trì kế hoạch, quy trình, hướng dẫn và chế độ kiểm thử cho việc quản lý sự cố an ninh mạng của tổ chức;\n- Nghiên cứu và đề xuất nâng cấp bảo mật & cung cấp tư vấn kỹ thuật cho các bộ phận liên quan;\n- Phản ứng ngay lập tức khi có sự cố an ninh và thực hiện phân tích sau sự cố.', '- Tối thiểu 2 năm kinh nghiệm ở vị trí Kỹ sư Hệ thống/Mạng;\n- Tốt nghiệp Đại học chuyên ngành Khoa học máy tính, Công nghệ thông tin hoặc lĩnh vực kỹ thuật liên quan;\n- Hiểu biết các khái niệm bảo mật liên quan đến DNS, định tuyến, xác thực, VPN, proxy và công nghệ giảm thiểu tấn công DDOS;\n- Có kinh nghiệm thiết kế/triển khai hệ thống mạng (ưu tiên có kinh nghiệm với mô hình HA – High Availability);\n- Có kiến thức và kinh nghiệm về các dịch vụ đám mây như AWS, Google Cloud, Azure, Linode;\n- Có kinh nghiệm sử dụng EKS, GKS, K8s và khả năng viết helm charts;\n- Có kinh nghiệm sử dụng các ngôn ngữ script như Bash/Python;\n- Có kinh nghiệm với công cụ CI/CD như Jenkins, GitLab;\n- Có kinh nghiệm sử dụng Ansible/Terraform;\n- Kinh nghiệm với các công cụ giám sát, logging và cảnh báo;\n- Có kinh nghiệm với cơ sở dữ liệu MySQL, Postgres;\n- Có kinh nghiệm hardening (tăng cường bảo mật) hệ điều hành và xử lý sự cố;\n- Có kinh nghiệm với các hệ điều hành Linux như CentOS, Ubuntu;\n- Thành thạo cấu hình và vận hành Nginx/Apache;\n- Có kinh nghiệm làm việc với ActiveMQ, Redis và Memcache.\n+ ƯU TIÊN (PLUS):\nCó kinh nghiệm với Kong Gateway, Istio là một lợi thế;\nCó kinh nghiệm với Terraform/Terragrunt và Ansible là một lợi thế;\nCó kiến thức và kinh nghiệm với Elasticsearch, Kafka là một lợi thế;\nCó kiến thức về postfix, máy chủ FTP và các dịch vụ khác là một lợi thế;\nCó kiến thức về bảo mật, kiểm tra lỗ hổng và cập nhật hệ điều hành & ứng dụng là một lợi thế;\nSiêng năng, có tinh thần trách nhiệm và kỹ năng giao tiếp, làm việc nhóm tốt;\nCó khả năng làm việc độc lập, chịu được áp lực cao.', 40000000.00, 64000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(89, 7, 10, 'Nhân Viên Kinh Doanh', 'Tìm kiếm, khai thác và phát triển các mối quan hệ với khách hàng tiềm năng (doanh nghiệp, tổ chức, cá nhân có nhu cầu về hệ thống PCCC và giám sát an ninh).\nTư vấn, giới thiệu các sản phẩm và giải pháp về thiết bị truyền tin báo cháy, hệ thống báo cháy (đầu báo khói, nhiệt, chuông, còi, tủ trung tâm,...) và các loại camera giám sát (IP, Analog, PTZ, Dome, Bullet,...).\nTrực tiếp đàm phán, thương lượng hợp đồng và chốt sales với khách hàng.\nChăm sóc khách hàng hiện có, duy trì và phát triển mối quan hệ tốt đẹp.\nThực hiện các báo cáo kinh doanh định kỳ theo yêu cầu của quản lý.\nCập nhật thông tin thị trường, đối thủ cạnh tranh và xu hướng công nghệ liên quan đến ngành.\nPhối hợp với bộ phận kỹ thuật để hỗ trợ khách hàng trong quá trình triển khai và hậu mãi.\nHoàn thành các chỉ tiêu doanh số được giao.', 'Trình độ học vấn: Tốt nghiệp Cao đẳng/Đại học chuyên ngành Quản trị Kinh doanh, Kinh tế, Kỹ thuật hoặc các ngành liên quan.\nKinh nghiệm: từ 2 năm trở lên\nKỹ năng chuyên môn: đàm phán, báo cáo\nKỹ năng mềm: làm việc theo nhóm, làm việc độc lập\nPhẩm chất: Trung thực, năng động, nhiệt tình, có đạo đức nghề nghiệp.', 12000000.00, 18000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(90, 81, 84, 'Japanese Tester', '• Develop test cases based on specifications\n• Executes tasks related to the production of the test plans, test cases, and test data.\n• Report bug with detailed information\n• Qualify bug’s severity and priority rating', '● General knowledge about testing: terms, software development process, testing process\n● From 2+ years of experience in software testing web/testing apps on mobile\n● Ability to Reading / Writing skills in Japanese N3++ (must have)\n● Ability to make suggestions and feedback when encountering problems\n● Good teamwork skills, professional and ethnic behaviors', 12000000.00, 18000000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(91, 82, 85, 'Giáo Viên - Trợ Giảng Dạy Lập Trình Cho Trẻ', 'Giảng dạy các bộ môn Scratch, Robotics và Python cho học sinh từ cấp 1 đến cấp 3 theo giáo trình của trung tâm.\nChuẩn bị bài giảng, giáo án trước mỗi buổi học để đảm bảo chất lượng giảng dạy.\nTheo dõi và điểm danh học viên, ghi nhận tình hình lớp học sau mỗi buổi.\nĐánh giá kết quả học tập của học viên thông qua bài kiểm tra giữa khóa, cuối khóa.\nHướng dẫn, hỗ trợ học viên trong quá trình học tập và thực hành.', 'Sinh viên đại học có khả năng giảng dạy Scratch (cơ bản & nâng cao), Python, Robotics (được đào tạo)..\nKỹ sư đã đi làm, đam mê giảng dạy và muốn kiếm thêm thu nhập.\nƯu tiên ứng viên theo học các chuyên ngành: Tin học, Khoa học máy tính, Lập trình hoặc Sư phạm Toán - Tin.\nYêu thích làm việc với trẻ em, không yêu cầu kinh nghiệm giảng dạy (được đào tạo).\nCó máy tính cá nhân để phục vụ công việc giảng dạy.', 1000000.00, 5000000.00, 'Khánh Hòa', 'Full-time', '2025-10-07 20:59:18.149534'),
	(92, 83, 86, 'Nhân Viên Kỹ Thuật Vận Hành', 'Cài đặt phần mềm bãi xe thông minh, camera, barie, máy chấm công, cửa kiểm soát ra vào, phân tầng thang máy, báo vị trí đỗ xe ô tô,...\nCấu hình switch, máy chủ windows server, database, SQL server, API,…\nThi công cáp quang, dây mạng lan, dây điện, lắp đặt thiết bị hệ thống kiểm soát xe thông minh.\nBảo trì, xử lý lỗi và lên kế hoạch sửa chữa, nâng cấp thiết bị (máy tính, camera, barie, thiết bị mạng, UPS,...) để đảm bảo vận hành.\nTham gia kiểm thử, nghiệm thu, hướng dẫn vận hành các hệ thống mới để bàn giao cho đối tác.', 'Giới tính: Nam. Độ tuổi từ 20-35.\nTrình độ: tốt nghiệp Cao Đẳng trở lên về ngành công nghệ thông tin hoặc nghành liên quan đến máy tính.\nƯu tiên ứng viên có kinh nghiệm trong việc triển khai hệ thống kiểm soát an ninh - BMS, không có kinh nghiệm sẽ được đào tạo.\nChăm chỉ, trung thực, nhiệt huyết, chủ động, sáng tạo trong công việc, có khả năng chịu áp lực công việc.\nCó khả năng nắm bắt, tự học hỏi và nghiên cứu, cẩn thận trong công việc.\nTư duy logic, xử lý vấn đề tốt.\nTinh thần cầu thị, trách nhiệm với công việc, định hướng ổn định gắn bó lâu dài.', 7000000.00, 12000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(93, 84, 87, 'Tax Accountant', '■ Monitor and implement activities to collect, analyze, verify, and report accounting and tax in accordance with the company\'s plan. Through corporate policy, ensure that all accounting, payroll, and tax activities are in compliance with the law and regulations.\n■ Support internal and external audits, prepare necessary financial documents and reports.\n■ Coordinate with relevant departments to gather and validate financial data.\n■ Stay updated with changes in tax laws and accounting standards to ensure compliance.\n■ Assist in improving internal processes to enhance accuracy and efficiency in accounting tasks.', 'DUTIES AND RESPONSIBILITIES\n■ Export invoices, import software data \n■ Monthly payment of tax report vouchers \n■ Check and compare records of payment and receipt of goods to adjust tax revenue in a timely manner when arising \n■ Maintain good communication and coordination with tax authorities, related partners \n■ Organize document storage \n■ Prepare Internal report and tax reports (VAT, PIT, ..) \n■ Other tasks assigned by line manager\n QUALIFICATIONS AND SKILLS \n■ At least 1 -2 experiences in Tax Accounting \n■ Experienced in using MISA, FAST, Excel \n■ Expertise in tax and accountancy \n■ Having extensive accounting knowledge, understanding accounting laws, regulations and standards \n■ Interpersonal and communication skills \n■ English (or Korean) communication skills \n■ International or start-up company experience will be an advantage.', 10000000.00, 15000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(94, 85, 88, 'Intern Sales', '- Xây dựng phễu bán hàng, khai thác danh sách khách hàng hiện có của công ty và tìm kiếm\nkhách hàng mới.\n- Hỗ trợ hướng dẫn thủ tục mua bán và phối hợp với Customer Service chăm sóc khách hàng sau\nbán\n- Hỗ trợ các công việc giấy tờ Sales admin\n- Thực hiện các công việc khác được giao', '- Ưu tiên các bạn sinh viên năm 2, năm 3 ở các khoa, ngành ngôn ngữ, am hiểu và học các ngành công nghệ thông tin là một lợi thế\n- Kỹ năng giao tiếp tốt, Tiếng Anh thành thạo (IELTS từ 6.5 trở lên hoặc tương đương)\n- Khả năng giải quyết vấn đề, sẵn sàng học hỏi kiến thức mới\n- Có kinh nghiệm kinh doanh dự án các sản phẩm CNTT là một lợi thế\n- Chăm chỉ, kiên trì', 5000000.00, 2000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(95, 86, 89, 'Kỹ Sư Dịch Vụ IT (Service Engineer) - Tiếng Anh', '▸ Giải quyết sự cố hệ thống hội nghị.\n▸ Quản lý phần mềm diệt virus.\n▸ Giải quyết sự cố phần cứng và phần mềm máy tính khách hàng.\n▸ Giám sát và nhận các công trình dây điện.', '▸ Tốt nghiệp Cao đẳng hoặc Đại học các chuyên ngành liên quan đến CNTT\n▸ Có 1-3 năm kinh nghiệm làm việc liên quan đến CNTT, chấp nhận ứng viên mới tốt nghiệp\n▸ Có thể giao tiếp tiếng Anh hoặc tiếng Trung tốt\n▸ Kỹ năng giao tiếp và làm việc nhóm tốt\n▸ Có thể đào tạo tại Biên Hòa, làm việc chính thức tại Châu Đức\n▸Có thể phối hợp đi ca (7:30-16:00 6:00-14:00, 14:00-22:00, 22:00-6:00)', 0.00, 1000.00, 'Bà Rịa - Vũng Tàu,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(96, 87, 90, 'Nhân Viên Kinh Doanh Website', 'Tìm kiếm, liên hệ với khách hàng đối tác\nTiếp nhận nguồn data từ Marketing chủ động liên hệ tư vấn theo kịch bản\nXây dựng danh sách đối tác tiềm năng, tiếp cận và giới thiệu các cơ hội hợp tác\nTheo dõi và báo cáo hiệu quả các chiến dịch\nPhối hợp với team marketing để đưa ra các ý tưởng phát triển kinh doanh', 'Tốt nghiệp cao đẳng, đại học trở lên, ưu tiên các chuyên ngành liên quan đến kinh tế\nCó kinh nghiệm trong lĩnh vực kinh doanh website tối thiểu 6 tháng\nAm hiểu về website: responsive, domain, hosting, SSL,...\nCó kinh nghiệm bán các sản phẩm SAAS\nƯu tiên ứng viên có kinh nghiệm làm trong các công ty công nghệ bán sản phẩm B2B, B2C\nKhả năng giao tiếp, đàm phán tốt, linh hoạt trong xử lý tình huống\nKỹ năng tìm kiếm, khai thác và tiếp cận đối tác mới\nAm hiểu về SEO, Digital Marketing là một lợi thế\nThu nhập\nThu nhập khi đạt 100% KPI: 12 - 30 triệu VND\nThu nhập tính theo tỷ lệ đạt KPI\nLương cứng: 8 triệu VND\nLương cứng không phụ thuộc doanh số', 8000000.00, 30000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(97, 88, 91, 'Nhân Viên Quản Trị Hệ Thống', 'Vận hành & giám sát hệ thống\nQuản lý Cloud & Kubernetes\nBảo mật & sao lưu\nHỗ trợ kỹ thuật', 'Tối thiểu 1 năm kinh nghiệm ở vị trí System Admin hoặc DevOps.\nTốt nghiệp Đại học trở lên\nKinh nghiệm thực tế với:\nHiểu biết cơ bản về mạng và bảo mật hệ thống.\nƯu tiên:\nKinh nghiệm với Terraform / Ansible / Helm.\nChứng chỉ CKA, AWS/GCP Associate hoặc tương đương.\nKinh nghiệm làm việc với Cloud Việt Nam (VNG Cloud, Viettel Cloud...).', 20000000.00, 27000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(98, 89, 92, 'Chuyên Viên Tư Vấn CNTT - Phòng Dịch Vụ Tư Vấn - Hà Nội', '- Tư vấn các dự án đầu tư ứng dụng CNTT:\n- Tư vấn khảo sát, tư vấn lập dự án đầu tư;\n- Tư vấn lập thiết kế kỹ thuật và dự toán chi tiết;\n- Tư vấn phân tích thiết kế, đề xuất giải pháp kỹ thuật;\n- Tư vấn lập HSMT, đánh giá HSDT;\n- Tư vấn thẩm định HSMT và KQLCNT;\n- Tư vấn thẩm tra/thẩm định các dự án đầu tư ứng dụng CNTT;\n- Tư vấn giám sát thi công, tư vấn quản lý dự án;\n- Các hoạt động tư vấn khác có liên quan theo quy định pháp luật;\n- Thực hiện các dịch vụ khảo sát phục vụ xây dựng kiến trúc, quy hoạch phục vụ phát triển chính quyền điện tử/ chính phủ điện tử/thành phố thông minh; - Thực hiện các dịch vụ xây dựng kiến trúc, quy hoạch phục vụ phát triển chính quyền điện tử/ chính phủ điện tử/thành phố thông minh.', '- Tốt nghiệp đại học chính quy chuyên ngành Công nghệ thông tin (hoặc gần CNTT).\n- Ưu tiên các ứng viên tốt nghiệp Đại học Bách khoa Hà nội và Học Viện bưu chính viễn thông, Giao thông … có kinh nghiệp làm việc liên quan đến vị trí cần tuyển dụng', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(99, 90, 93, 'Giáo Viên Dạy Lập Trình', 'Giảng dạy lập trình cơ bản (Scratch, Python, Web...) cho học sinh tiểu học và THCS.\nSoạn bài, hướng dẫn học sinh thực hành trên máy tính theo giáo trình có sẵn.\nĐánh giá tiến độ học tập và hỗ trợ học sinh phát triển tư duy công nghệ.', 'Có kỹ năng sư phạm, yêu trẻ, giao tiếp tốt.\nThành thạo sử dụng máy tính: soạn thảo văn bản, trình chiếu, sử dụng phần mềm, internet...\nKhông yêu cầu kiến thức lập trình chuyên sâu – sẽ được đào tạo miễn phí nếu phù hợp.\nƯu tiên sinh viên/kỹ sư ngành Sư phạm, CNTT hoặc người đã có kinh nghiệm giảng dạy.', 5000000.00, 20000000.00, 'Khánh Hòa', 'Internship', '2025-10-07 20:59:18.149534'),
	(100, 91, 94, 'Customer Success Intern', '• Learn about products features and update functionalities knowledge continuously\n• Respond to customer queries in a timely and accurate way, via phone, email or chat\n• Identify customer needs and helping customers use specific features\n• Collect and report the problems that customers often encounter to give suggestions to improve the product.', '• Willing to take night shifts and weekend shifts\n• Interested in solving problems with digital/SaaS products\n• Good communication English skills (TOEIC > 600 or equivalent)\n• Effective and positive communication with customers, team members, and managers\n• Ability to adapt and respond to different characters, and maintain calmness when dealing with stressed or upset customers\n• Good problem-solving, logical thinking, and decision-making skills\n• Basic knowledge of HTML, CSS, and JS is a plus', 16000000.00, 7000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(101, 92, 95, 'Kỹ Sư Công Nghệ Ai', 'Nghiên cứu, thiết kế và triển khai các mô hình trí tuệ nhân tạo trong lĩnh vực phần mềm đặc biệt là ChatBot hoặc Giáo dục: machine learning, deep learning, NLP (Natural Language Processing),…\nThu thập, xử lý và phân tích dữ liệu để huấn luyện và tối ưu mô hình AI.\nHợp tác với các bộ phận khác (Product Owner, Software Engineer) để tích hợp mô hình AI vào hệ thống, sản phẩm thực tế\nGiám sát hiệu suất và cải tiến liên tục các thuật toán và mô hình AI trong quá trình vận hành.\nTối ưu hóa chi phí tính toán và tốc độ xử lý cho các giải pháp AI\nCập nhật và ứng dụng các công nghệ AI mới nhất trong ngành để nâng cao hiệu quả sản phẩm/dịch vụ trong lĩnh vực giáo dục\nĐề xuất các phương án phát triển và cải tiến AI', 'Tốt nghiệp Đại học chuyên ngành CNTT, Khoa học máy tính, Toán tin, hoặc các ngành liên quan.\nCó 3 năm kinh nghiệm trong các sản phẩm AI. (Ưu tiên sản phẩm ChatBot AI)\nThành thạo ít nhất một trong các ngôn ngữ lập trình: Python, Java, C++, R (ưu tiên Python)\nCó kiến thức và kinh nghiệm thực tế về các thư viện/framework AI: TensorFlow, PyTorch, Scikit-learn, Hugging Face,…\nHiểu và triển khai được pipeline RAG, làm việc với vector DB (FAISS, Qdrant, Pinecone,…)\nKinh nghiệm xây dựng AI Agent đa nhiệm bằng Langchain, LlamaIndex…\nThành thạo kỹ thuật: Prompt engineering, function calling, chain-of-thought, tool usage\nNắm vững kiến thức: thống kê, xác suất, machine learning, tối ưu hóa\nTư duy logic, khả năng giải quyết vấn đề tốt, tinh thần học hỏi và cập nhật công nghệ mới.\nCó khả năng nghiên cứu và cải tiến liên tục chatbot AI\nƯu tiên: Kinh nghiệm triển khai mô hình AI vào môi trường sản phẩm thực tế; triển khai mô hình AI trên nền tảng đám mây (AWS, GCP, Azure); sử dụng Docker, Kubernetes hoặc các công cụ MLOps.', 20000000.00, 30000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(102, 72, 75, 'Thực Tập Sinh Backend (Python, Django - HCM)', 'Làm việc với các bộ dữ liệu lớn: thu thập, lưu trữ và phân tích thống kê dữ liệu.\nPhát triển và duy trì API sử dụng các framework như Django hoặc FastAPI.\nHợp tác với nhóm để thiết kế và tối ưu hóa cơ sở dữ liệu SQL và NoSQL.\nTham gia review code, kiểm thử và debug để đảm bảo chất lượng sản phẩm.\nChủ động trao đổi với nhóm, đặc biệt khi gặp khó khăn hoặc nguy cơ trễ deadline.\nChịu trách nhiệm với công việc được giao và chủ động báo cáo nếu không thể hoàn thành đúng hạn.\nTham gia giải quyết vấn đề và đề xuất các giải pháp sáng tạo.', 'Có thể lập trình với Python.\nHiểu biết về dữ liệu lớn (big data) và phân tích thống kê.\nQuen thuộc với các framework backend như Django, FastAPI hoặc tương đương.\nCó kinh nghiệm làm việc với cả cơ sở dữ liệu SQL và NoSQL.\nKỹ năng giải quyết vấn đề tốt, ham học hỏi.\nKỹ năng làm việc nhóm và giao tiếp tốt.\nCó tinh thần trách nhiệm, chủ động trong công việc.\nĐam mê phát triển backend và mong muốn làm việc trong môi trường hợp tác.\nSử dụng các công cụ AI để hỗ trợ và nâng cao hiệu suất công việc backend.\nCó kinh nghiệm làm việc với các công cụ tìm kiếm như OpenSearch.', 0.00, 1000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(103, 93, 96, 'Nhân Viên Kỹ Thuật Máy Photocopy (Không Cần Kinh Nghiệm) - Khu Vực Cần Thơ', '- Lắp đặt mới và hướng dẫn sử dụng cho khách hàng, các dòng máy máy photocopy\n- Hỗ trợ cài đặt và xử lý lỗi trong quá trình sử dụng\n- Đến tận nơi xử lỗi cho khách hàng nếu không xử lý được từ điện thoại hay ultraview, teamviewer\n- Cài đặt driver cho máy photocopy\n- Biết sửa chữa máy photocopy.', '- Nam. Tuổi từ 22 đến 25\n- Thành thạo tin học văn phòng, mạng internet, chia sẻ thiết bị qua mạng Lan nội bộ\n- CHƯA CÓ KINH NGHIỆM SẼ ĐƯỢC ĐÀO TẠO: Tốt nghiệp Trung Cấp chuyên ngành công nghệ thông tin , điện – điện tử hoặc chuyên ngành liên quan. \n- Đam mê lĩnh vực công nghệ\n- Thành thạo tin học văn phòng, mạng internet, chia sẻ thiết bị qua mạng Lan nội bộ\n- Ưu tiên có kinh nghiệm về sửa chữa máy in, máy tính, máy photocopy', 5000000.00, 10000000.00, 'Cần Thơ', 'Internship', '2025-10-07 20:59:18.149534'),
	(104, 94, 97, 'Chuyên Viên Marketing', '- Thiết kế vỏ hộp sản phẩm, hình ảnh, các hạn mục theo yêu cầu BGD ( biết design cơ bản) \n- Up web thông tin và hình ảnh sp. Chụp ảnh đẹp. \n- Chăm sóc fanpage \n- Chịu trách nhiệm các mảng cv liên quan mkt, hình ảnh ảnh công ty. Quảng bá đưa hình ảnh công ty, văn hoá doanh nghiệp, thương hiệu phân phối gần hơn với đối tác. Tăng độ nhận diện.', '- Kinh nghiệm từ 1 năm trở lên\n- Tốt nghiệp Cao đẳng trở lên chuyên ngành Marketing \n- Có thể làm việc team, có tính tự giác , chủ động trong công việc', 9000000.00, 11000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(105, 95, 98, 'Software Consultant (Business Analyst ,erp)', 'Phân tích rõ yêu cầu nghiệp vụ của khách hàng\nPhối hợp với công ty tư vấn thực hiện khảo sát nghiệp vụ, đề xuất các giải pháp, tham gia thực hiện giải pháp, kiểm thử giải pháp trên hệ thống ERP.\nHướng dẫn cán bộ nghiệp vụ tại các đơn vị sử dụng hệ thống ERP phục vụ công việc.\nThực hiện công việc theo yêu cầu trưởng nhóm.', 'Giới tính: Nam\nCó thể đi công tác các tỉnh theo yêu cầu\nKhả năng đọc hiểu tài liệu tiếng Anh\nGiao tiếp tốt, có khả năng chịu được áp lực cao trong công việc\nTinh thần làm việc theo nhóm tốt\nÝ thức cao và có trách nhiệm trong công việc\nTốt nghiệp ĐH chuyên ngành Tài Chính / Kế toán hoặc các ngành liên quan\nƯU TIÊN có kinh nghiệm về kế toán (mua hàng, bán hàng, sản xuất, kho, tài chính)\nƯU TIÊN ứng viên thường trú tại Ba Tri / Mỏ Cày Bắc – Bến Tre\nPhỏng vấn tại Ba Tri-Bến Tre', 9000000.00, 20000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(106, 96, 99, 'Chuyên Viên Quản Trị Hệ Thống Youtube', 'Lập kế hoạch phát triển nội dung và kiếm tiền từ nền tảng Youtube\nBiên tập các video đăng tải lên nền tảng Youtube\nQuản trị kênh và vận hành hệ thống, đảm bảo đúng theo chính sách của Youtube. Có khả năng liên hệ với các bên đối tác và Youtbe để xử lý các kháng nghị liên quan đến bản quyền nội dung hoặc chính sách nền tảng.\nChăm sóc khách hàng, liên hệ với đối tác để xử lý các vấn đề liên quan đến CMS Youtube\nĐối soát hợp đồng và phối hợp với Kế toán để làm thanh toán cho các bên liên quan.', 'Tốt nghiệp Cao đẳng trở lên chuyên ngành : Tin học, Kỹ thuật, Khoa học máy tính, Công nghệ thông tin….\nƯu tiên những bạn đã từng làm SEO  website, Youtube, TikTok, Fanpage hiểu biết về thuật toán, chính sách của Youtube, TikTok, Fanpage…\nCó hiểu biết sâu rộng về Youtube (thuật toán, chính sách) và các công cụ, tiện ích hỗ trợ phát triển kênh.\nBiết sử dụng các phần mềm Adobe Premiere, Photoshop, Ai, canva...\nCó ít nhất 1 năm kinh nghiệm ở vị trí tương đương\nNhanh nhẹn, chăm chỉ, ham học hỏi, có tinh thần trách nhiệm cao\nThành thạo các kỹ năng văn phòng\nƯu tiên ứng viên có kinh nghiệm tại nhiều loại hình doanh nghiệp tương đồng với SCTV và nộp hồ sơ sớm', 7000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(107, 97, 100, 'Nhân Viên Data Analyst', '1.Tiếp nhận và thu thập dữ liệu: phối hợp các phòng ban để thu thập, truy xuất, rà soát và làm sạch dữ liệu theo yêu cầu.\n2.Phân tích và báo cáo dữ liệu nhằm tham mưu cho cấp trên về thực trạng của vấn đề và đề xuất các chiến lược giải quyết tối ưu, hỗ trợ việc ra quyết định.\n3.Đóng góp vào việc cải tiến các quy trình làm việc các phòng ban, nâng cao năng suất làm việc của đội ngũ.\n4.Hỗ trợ xây dựng quy trình đánh giá và đo lường hiệu suất của từng bộ phận theo yêu cầu.\n5.Hỗ trợ việc tự động hóa báo cáo các phòng ban.\n6.Triển khai và đào tạo sử dụng phần mềm nội bộ cho các bộ phận chức năng.\n7.Các nhiệm vụ khác theo sự phân công của Ban Giám đốc.', '1.Độ tuổi từ 23-35\n2.Tốt nghiệp đại học, cao đẳng chuyên ngành kinh tế, thống kê, toán học, khoa học máy tính hoặc các lĩnh vực liên quan.\n3. Ít nhất 1 năm kinh nghiệm trong vai trò phân tích dữ liệu.\n4.Thành thạo Excel (pivot table, VLOOKUP/XLOOKUP....), biết sử dụng các công cụ và kỹ thuật tiên tiến để tối ưu hóa quá trình phân tích dữ liệu.\n5.Tư duy phân tích logic, khả năng trình bày và giải thích số liệu tốt.\n6.Khả năng giao tiếp kết nối nội bộ, tư duy là một nhà quản trị của tổ chức.\n7.Khả năng làm việc độc lập\n8.Cẩn thận, tỉ mĩ, có tinh thần làm việc nhóm và chủ động trong công việc\n9. Đóng góp giá trị, cùng xây dựng và hoàn thành theo mục tiêu chung của phòng ban, mục tiêu chung của công ty.', 14000000.00, 17000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(108, 98, 101, 'Nhân Viên Quản Trị Website', 'Nắm vững cách sử dụng và làm chủ các tính năng trong trang quản trị (Magento, Headless CMS) của website thương mại điện tử và dịch vụ\nChuyển nội dung từ website sang các sàn du lịch\nCập nhật, sao lưu dữ liệu website\nXuất báo cáo dữ liệu từ website và các sàn\nTạo mới, chỉnh sửa nội dung WYSIWYG, HTML khi có yêu cầu  \nĐược hướng dẫn sử dụng các công cụ AI, Photoshop, Illustrator và các phần mềm xây dựng/chỉnh sửa dữ liệu\nTương tác với các bộ phận khác để vận hành, phát triển và khác phục các sự cố hoặc sai sót thông tin trên website và sàn.\nCác công việc khác theo yêu cầu của cấp trên', 'Kinh nghiệm: tối thiểu 1-2 năm tại vị trí tương đương. \nTốt nghiệp Đại học/cao đẳng...các ngành học liên quan\nƯu tiên kinh nghiệm quản trị website\nCó hiểu biết về PHP, HTML, CSS, JS, ReactJS, CSV, JSON, RegEx..\nĐã từng làm quen với các CMS như Magento 2, WordPress, Headles CMS..\nBiết sử dụng các phần mềm Editors, IDEs, Photoshop, Illustrator cơ bản.', 10000000.00, 14000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(109, 99, 102, 'Nhân Viên Hỗ Trợ Và Chăm Sóc Khách Hàng', '- Hỗ trợ khách hàng sử dụng phần mềm : Phầm mềm y tế cung cấp cho bệnh viện , phòng khám,…\n- Làm việc theo ca (8 tiếng/ ngày).\n- Chi tiết trao đổi khi phỏng vấn', '- Nam, tuổi từ 20-30 (2002 - 1995)\n- Tốt nghiệp từ Trung cấp trở lên, ưu tiên chuyên ngành công nghệ thông tin, kế toán,…\n- Giao tiếp vui vẻ, khéo léo, thân thiện, nhiệt tình.\n- Có tinh thần trách nhiệm cao và đam mê công nghệ.\n- Chịu đi công tác xa (khi đi triển khai + bồi dưỡng).\n- Chịu được áp lực công việc.', 8000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(110, 13, 16, 'Nhân Viên Phần Mềm IT Full Stack Developer', 'Xây dựng phần mềm theo yêu cầu của khách hàng (Backend, Frontend)\nKiểm tra phần mềm đảm bảo khả năng phản hồi và hiệu quả\nKhắc phục sự cố, gỡ lỗi và nâng cấp phần mềm\nViết tài liệu kỹ thuật (tài liệu thiết kế, hướng dẫn sử dụng…)', 'Có kinh nghiệm tối thiểu 1 năm với vai trò Full Stack Developer hoặc tương tự\nCó kinh nghiệm về một trong các Backend: C#, NodeJS, Python\nCó kinh nghiệm về một trong các Frontend: React, VueJS, HTML, CSS\nCó kinh nghiệm với một trong các Cloud: AWS, Google, Azure Cloud\nCó kinh nghiệm với một trong các databases: MySQL, MongoDB, MSSQL, PostgreSQL\nCó kinh nghiệm xây dựng phần mềm tích hợp AI là một lợi thế\nCó khả năng học hỏi công nghệ mới nhanh chóng, thích nghi với đa dạng yêu cầu khách hàng\nCó kinh nghiệm thực hiện dự án từ đầu là một lợi thế', 10000000.00, 28000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(111, 100, 103, 'Nhân Viên IT Phần Cứng / Mạng Cho Siêu Thị Bách Hoá (TP.HCM)', '- Lắp ráp và cài đặt phần mềm máy tính PC, camera, cài đặt và cấu hình máy in, máy scan. Giải quyết các vấn đề về mật khẩu, các lỗi phần cứng và phần mềm máy tính, hỗ trợ vấn đề người dùng gặp phải, xử lý các sự cố phát sinh. \n- Quản lý mạng và cảnh báo sự cố đường truyền, thường xuyên kiểm tra thiết bị máy tính nhằm đảm bảo hoạt động ổn định.\n- Hỗ trợ các thiết bị lắp đặt siêu thị (lắp đặt thiết bị mạng, thiết bị giám sát, cân điện tử, máy POS cho cửa hàng) \n- Cấp quyền, phân quyền, quản lý phần mềm bán hàng siêu thị \n- Các công việc khác liên quan đến thiết bị điện tử theo yêu cầu của lãnh đạo', '- Tuổi từ 28 - 40 tuổi\n- Trình độ Cao đẳng/Đại học\n- Có kinh nghiệm trong triển khai và khắc phục sự cố hệ thống mạng máy tính \n- Thành thạo tin học văn phòng: Word, Excel,...\n- Có tư duy làm việc logic, làm việc theo nhóm. \n- Chăm chỉ, tinh thần trách nhiệm cao trong công việc. \n- Khả năng sắp xếp công việc tốt', 13000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(112, 101, 104, 'Nhân Viên Triển Khai Và Hỗ Trợ Phần Mềm HCM', 'Triển khai phần mềm, hướng dẫn sử dụng\nTiếp nhận yêu cầu chỉnh sửa phần mềm\nBảo trì phần mềm định kỳ\nHỗ trợ kỹ thuật, xử lý sự cố trong quá trình khách hàng sử dụng\nThỉnh thoảng đi công tác tỉnh (chủ yếu triển khai mới)', 'Biết cài đặt hệ điều hành Window và các phần mềm thông dụng\nCó hiểu biết cơ bản về phần cứng máy tính, mạng LAN\nCó phương tiện cá nhân đi lại\nSiêng năng, ham học hỏi\nCó hiểu biết về SQL server/lập trình là một lợi thế\nCó kinh nghiệm ở vị trí tương tự là một lợi thế\nKhông hút thuốc lá (bao gồm thuốc lá điện tử)', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(113, 102, 105, 'Nhân Viên Thiết Kế - Graphic Design', '- Thiết kế các sản phẩm đồ họa: lịch xuân, catalog, banner, bao lì xì, số tay, các mẫu quảng cáo POSM.\n- Thiết kế các ấn phẩm in (tờ rơi, brochure, poster, bandroll,...), thiết kế các vật phẩm sử dụng trong ngày lễ, sự kiện của công ty (backdrop, giấy mời, standee, bảng biển,...).\n- Giám sát & quản lý chất lượng in ấn của các biểu mẫu, vật phẩm quảng cáo, đảm bảo thực hiện đúng với mẫu thiết kế đã được phê duyệt.\n- Thiết kế logo, banner, hình ảnh thumbnail quảng cáo tối ưu cho website, và các nền tảng social media (Facebook, Instagram, Tiktok) và E-commerce (Shopee, Lazada, Tiktokshop).\n- Phối hợp với Bộ phận Marketing để phát triển nội dung hình ảnh cho các chiến dịch truyền thông.\n- Chỉnh sửa & tối ưu hình ảnh sản phẩm (retouch, cân chỉnh màu sắc, crop).\n- Nghiên cứu & ứng dụng các xu hướng thiết kế digital mới nhất (bao gồm 2D & 3D).', 'Trình độ: Tốt nghiệp Cao đẳng, đại học và các ngành liên quan đến \n- Kinh nghiệm từ 3 năm.\n- Tiếng Anh ( đọc & hiểu)\n- Có khả năng phân tích thống kê, giải trình và báo cáo.\n- Thành thạo các phần mềm office, premier, AI,After Effect,…\n- Có kỹ năng giải quyết vấn đề\n-Tư duy logic và đổi mới', 10000000.00, 16000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(114, 103, 106, 'Tester Cum Ba (Yêu Cầu Có Kinh Nghiệm)', '1. Kiểm thử phần mềm (60%)\nViết test case, test scenario chi tiết dựa trên tài liệu đặc tả.\nThực hiện test thủ công (manual) để đảm bảo chất lượng sản phẩm. \nThiết kế, phát triển và thực hiện test script tự động cho các module quan trọng. \nQuản lý và tối ưu bộ test automation (framework, script, báo cáo…). \nPhối hợp với Dev để tái kiểm tra lỗi, theo dõi tiến độ fix bug. \nTham gia UAT, hỗ trợ kiểm thử & xử lý lỗi phát sinh. \n 2. Phân tích nghiệp vụ (40%)\nThu thập, làm rõ yêu cầu nghiệp vụ. \nViết và quản lý tài liệu đặc tả nghiệp vụ (BRD, SRS, Use Case, User Story, Wireframe, Flowchart...).\nTruyền đạt yêu cầu tới team Dev & đảm bảo các bên hiểu đúng và đầy đủ. \nTham gia demo, training sản phẩm cho khách hàng và nội bộ. \n Bộ phận: Phát triển sản phẩm / Dự án \nBáo cáo: BA Leader/ PM', 'Tốt nghiệp Đại học các ngành CNTT, Hệ thống thông tin, Kinh tế hoặc liên quan. \nCó kinh nghiệm ở vị trí tester và willing kiêm nhiệm vai trò BA \nHiểu biết quy trình phát triển phần mềm và các mô hình (Waterfall, Agile/Scrum). \nKỹ năng phân tích, viết tài liệu nghiệp vụ tốt. \nKỹ năng kiểm thử: viết test case, test report, thực hiện kiểm thử thủ công và tự động. \nCó kiến thức về test automation: biết sử dụng các công cụ như Selenium, Katalon, Cypress hoặc các framework automation khác. \nCó khả năng viết script automation bằng ngôn ngữ phù hợp (Java, Python, JavaScript…). \nHiểu biết về API testing là một lợi thế. \nKỹ năng giao tiếp, teamwork và quản lý công việc. \nƯu tiên có kiến thức về SQL, công cụ quản lý dự án (Jira, Redmine, Trello…).', 12000000.00, 14000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(115, 104, 107, 'Nhân Viên IT Phần Mềm (10-15 Triệu / Tháng)', 'Hỗ trợ, tư vấn các Phòng ban công tác nhập liệu, xử lý số liệu trên phần mềm ERP.\nQuản lý hệ thống phần mềm, mạng,…trong công ty\nCác công việc khác do cấp trên giao phó', 'Ưu tiên từng làm ở công ty sản xuất,có kinh nghiệm thực tế về phần mềm ERP\nTốt nghiệp Trung cấp trở lên ngành CNTT, phần mềm,…\nKinh nghiệm từ 1 năm trở lên\nSiêng năng, chịu khó\nƯu tiên ứng viên sinh sống gần khu vực KCN Tam Phước', 10000000.00, 15000000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(116, 105, 108, 'Nhân Viên Tư Vấn Marketing Web Làm Việc Tại Tân Bình- Đi Làm Ngay', 'Chủ động tìm kiếm, kết nối với khách hàng tiềm năng, mở rộng thị trường (data sẽ được công ty hướng dẫn tìm)\nTư vấn, giới thiệu về các dịch vụ thiết kế website, hosting, tên miền, dịch vụ chăm sóc, quản trị, quảng cáo website,... của công ty\nBáo giá, đàm phán, ký kết hợp đồng, quản lý, hỗ trợ khách hàng và bàn giao dự án\nChăm sóc khách hàng', 'Ưu tiên có kinh nghiệm sale từ 6 tháng trở lên – không có kinh nghiệm sẽ được đào tạo chi tiết\nTốt nghiệp Trung cấp nghề trở lên, ưu tiên ngành quản trị kinh doanh, kinh tế, tài chính – ngân hàng, marketing,...\nĐam mê với tư vấn, sales, giao tiếp ổn, thích marketing thực chiến\nCó laptop cá nhân và phương tiện di chuyển\nCơ hội làm việc cho các ứng viên có chuyên ngành liên quan đến Marketing và đam mê Sales', 9000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(117, 106, 109, 'Nhân Viên Kỹ Thuật Điện - Điện Tử (Sửa Bo Mạch) - Không Y / C Kinh Nghiệm', 'Kiểm tra, phân tích và sửa chữa các lỗi bo mạch điện tử của máy photocopy, máy in.\nThực hiện các công việc hàn, khò các linh kiện điện tử trên bo mạch.\nĐọc và tra cứu thông số kỹ thuật của các linh kiện (tụ, chip, datasheet...).\nPhối hợp với các bộ phận khác để đảm bảo chất lượng công việc', 'Tốt nghiệp Trung cấp trở lên các chuyên ngành Điện, Điện tử, Cơ điện tử hoặc các ngành liên quan.\nKhông yêu cầu kinh nghiệm, sẽ được đào tạo thêm về sản phẩm của công ty.\nCó kiến thức cơ bản về điện, điện tử.\nCó kỹ năng sử dụng thành thạo các thiết bị hàn, khò, đồng hồ đo.\nCó khả năng đọc và hiểu các thông số linh kiện điện tử (tụ, chip).\nThái độ làm việc nghiêm túc, cẩn thận, trung thực và có tinh thần trách nhiệm cao.\nChịu khó, cẩn thận ham học hỏi, Chủ động trong công việc. Thực sự nhiệt huyết và mong muốn gắn bó lâu dài.', 7000000.00, 9000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(118, 107, 110, 'Lập Trình Viên (Next.Js, Node.Js, Javascript...) - Thu Nhập Lên Đến 40Tr', '• Thiết kế, phát triển và duy trì ứng dụng phần mềm và hệ thống.\n• Tham gia vào toàn bộ quy trình phát triển phần mềm (SDLC).\n• Sử dụng các công nghệ Next.JS, Node.JS, JavaScript, SQL Server hoặc ASP.NET, .NET Core.\n• Thực hiện các thử nghiệm và sửa lỗi để đảm bảo chất lượng sản phẩm.\n• Hợp tác với đội ngũ đa chức năng để xác định yêu cầu và cung cấp giải pháp kỹ thuật.\n• Cập nhật và nâng cấp các hệ thống hiện có theo yêu cầu của công ty.\n• Đảm bảo tuân thủ các tiêu chuẩn mã nguồn và thực hành lập trình tốt nhất.', '• Tối thiểu 2 năm kinh nghiệm lập trình với Next.JS, Node.JS, JavaScript.\n• Kinh nghiệm làm việc với SQL Server , ASP.NET, .NET Core là một lợi thế.\n• Khả năng làm việc độc lập và trong môi trường nhóm .\n• Ưu tiên ứng viên có khả năng phát triển lên trưởng nhóm, trưởng bộ phận .\n• Kĩ năng giải quyết vấn đề tốt và tư duy phản biện.\n• Có đam mê học hỏi và phát triển bản thân.', 20000000.00, 40000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(119, 108, 111, 'Nhân Viên Kinh Doanh Thiết Bị - Phần Mềm Quản Lý - Tài Chính', 'Tiếp cận các cửa hàng tạp hoá, F&B, bán lẻ, nhà thuốc… để giới thiệu và phát triển khai:\n Máy quẹt thẻ & máy quét mã QR\n Phần mềm quản lý bán hàng Posapp\n Xuất hóa đơn điện tử từ máy tính tiền theo đúng quy định Nhà nước', 'Siêng năng, thích công việc đi thị trường, có sức bền\n Kỹ năng giao tiếp tốt, tự tin thuyết phục\n Có tinh thần trách nhiệm, tư duy tích cực, làm việc nhóm tốt', 8000000.00, 12000000.00, 'Tiền Giang,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(120, 109, 112, 'Giáo Viên Tin Học (Tốt Nghiệp Ngành CNTT) - Đi Làm Ngay', 'Tham gia trợ giảng hoặc giảng dạy, biên soạn tài liệu, giáo trình, đề thi…các lớp Tin Học Văn Phòng:CNTT Cơ Bản (CCA), CNTT Nâng Cao (CCB), IC3 & MOS. Tại các Chi Nhánh của Tin Học Đại Dương\nLàm việc tại các chi nhánh của Tin Học Đại Dương hoặc tại các Trường THCS, THPT là đơn vị đối tác của Tin Học Đại Dương', 'Giới tính: Nam – Nữ\nNgoại hình dễ nhìn, giọng nói dễ nghe\nĐã hoặc sắp tốt nghiệp chuyên ngành CNTT hệ Đại học và Cao đẳng. \nƯu tiên có chứng chỉ nghiệp vụ sư phạm\nCó năng khiếu và yêu thích việc đào tạo, giảng dạy, nghiên cứu CNTT…\nTrung thực, năng động và có trách nhiệm cao trong công việc\nCó tính chủ động nghiên cứu cập nhật kiến thức để nâng cao giá trị bản thân', 9000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(121, 110, 113, 'Junior Product Marketer (Product Marketing)', 'Selfomy One chính là giải pháp dạy và học ứng dụng trí tuệ nhân tạo toàn diện nhất cho các trung tâm giảng dạy về IELTS, TOEIC và SAT. Giải pháp của chúng tôi giúp trung tâm giao bài tập, chấm bài bằng A.I và tổ chức các kỳ thi mô phỏng giống với kỳ thi thật. Sản phẩm đã được nhiều trung tâm, trường học lớn trên cả nước sử dụng.\nSelfomy đang phát triển nhanh chóng nhưng bền vững, đạt mức tăng trưởng doanh thu 15% mỗi tháng.\nLà Product Marketer (Product Marketing) đầu tiên tại Selfomy, công việc của bạn là giúp công ty đạt mục tiêu chung là tăng trưởng về doanh số. Để làm được điều đó, bạn sẽ là người dành thời gian lên kế hoạch và dành phần lớn thời gian để thực hiện các kênh Marketing để sản phẩm được nhiều khách hàng tiềm năng biết đến và quan tâm đến sản phẩm. Khách hàng của Selfomy là khách hàng doanh nghiệp (B2B), thường kỹ tính, cần nhiều thời gian nghiên cứu và đánh giá.\nProduct Marketer tại Selfomy là nhân sự chữ T, nơi bạn có kiến thức chuyên ngành về Marketing nhưng hiểu rộng về các mảng liên quan (ví dụ công nghệ giáo dục, website, bán hàng) và nếu không biết thì sẵn sàng học hỏi và thử sức. Từ đó có thể đảm nhiệm nhiều vai trò khác nhau để hỗ trợ các nhóm Kỹ thuật và Kinh doanh.  \nChúng tôi cũng có mục tiêu đưa giải pháp ra Đông Nam Á trong quý 4/2025. Vì vậy đây là một vai trò rất thú vị và bạn sẽ có cơ hội phát triển không ngừng cùng công ty (và trở nên tự do và đủ đầy hơn).\nTrách nhiệm\nLên kế hoạch cho chiến lược tiếp cận thị trường của sản phẩm.\nTriển khai chiến lược đó trên các kênh, cách thức khác nhau để đạt mục tiêu về marketing (ví dụ Marketing Qualified Lead): \nSEO: Tối ưu hóa nội dung và website để cải thiện thứ hạng tìm kiếm\nEmail Marketing: Xây dựng và thực hiện các chiến dịch email marketing hiệu quả\nSocial Ads: Quản lý và tối ưu các chiến dịch quảng cáo trên Facebook, LinkedIn, và các nền tảng social khác\nOrganic Social: Xây dựng cộng đồng người theo dõi, thương hiệu cá nhân của bạn về lĩnh vực EdTech.\nSearch Ads: Triển khai và tối ưu chiến dịch Google Ads, Bing Ads\nWebsite: Cập nhật nội dung, tối ưu trải nghiệm người dùng và conversion rate\nGrowth Hacking: Thử nghiệm các phương pháp tăng trưởng sáng tạo, từ viral marketing đến hợp tác', 'Yêu thích môi trường startup, mong muốn đột phá, tạo dấu ấn riêng trong sự nghiệp.\nKỹ năng viết, giao tiếp và nghiên cứu tốt.\nCó kinh nghiệm liên quan về Marketing.\nKhả năng làm việc độc lập và tự quản lý công việc.\nCó kinh nghiệm làm việc từ xa là một điểm cộng.', 7000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(122, 111, 114, 'Nhân Viên Triển Khai Phần Mềm (Định Hướng Ba)', 'Làm quen, tìm hiểu và nắm vững nghiệp vụ quản lý sân thể thao và tính năng của phần mềm ALOBO\nTích lũy kiến thức, kỹ năng để đảm nhận vị trí Business Analyst (BA) sau giai đoạn 3 – 6 tháng\nTạo tài khoản và hướng dẫn khách hàng cài đặt, training sử dụng phần mềm.\nChăm sóc hệ thống khách hàng đã ký hợp đồng sử dụng phần mềm ALOBO: Theo dõi hoạt động, hỗ trợ sử dụng phần mềm, tư vấn giải pháp tối ưu.\nDuy trì mối quan hệ tích cực, xây dựng lòng tin và sự gắn bó với khách hàng hiện tại.\nLàm việc theo phân công của cấp trên, phối hợp với bộ phận kỹ thuật trực ngoài giờ xoay ca theo tuần (có phụ cấp) để giải quyết các vấn đề lỗi phần mềm phát sinh.\nTiếp nhận và triển khai các tính năng mới của phần mềm từ đội phát triển.\nGhi nhận phản hồi khách hàng, đề xuất cải tiến sản phẩm hoặc quy trình nội bộ.\nĐề xuất gói nâng cấp, tính năng mới phù hợp với từng mô hình kinh doanh để upsell.\nXây dựng tài liệu, quy trình tối ưu để đẩy nhanh quá trình triển khai.\nBáo cáo cấp trên các các vấn đề của khách hàng trong tuần theo lịch trình', 'Tốt nghiệp Đại học chuyên ngành Công Nghệ Thông Tin, Hệ Thống Thông tin hoặc các ngành liên quan.\nƯu tiên sinh viên tốt nghiệp các trường UIT, Kinh Tế Luật, Bưu chính viễn thông ...\nYêu thích công nghệ .\nKỹ năng làm việc độc lập và làm việc nhóm.\nChủ động trong việc chăm sóc khách hàng, xử lý tình huống linh hoạt.\nCó kỹ năng trao đổi, thương lượng, truyền đạt & thuyết phục khéo léo.\nCó trách nhiệm với deadline\nThái độ ân cần, tôn trọng khách hàng, tôn trọng cấp trên và đồng nghiệp\nƯu tiên ứng viên có kiến thức về các môn thể thao, tiếp thu nhanh\nCó kỹ năng tư vấn giải pháp là một lợi thế lớn\nBiết chơi Cầu lông, Tennis, Pickleball... là một điểm cộng', 7000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(123, 112, 115, 'Kỹ Sư Phần Mềm', 'Thiết kế, phát triển và triển khai các ứng dụng web hiệu quả và có khả năng mở rộng. \nPhối hợp chặt chẽ với các thành viên trong nhóm để đưa ra giải pháp kỹ thuật, triển khai tính năng và cải thiện hệ thống hiện có. \nViết mã sạch, dễ bảo trì và có kiểm thử. \nTối ưu hóa hiệu suất ứng dụng, đảm bảo tính ổn định và bảo mật. \nNghiên cứu và áp dụng các công nghệ mới để nâng cao chất lượng sản phẩm.', 'Ngôn ngữ lập trình: TypeScript thành thạo. \nHosting: Có kinh nghiệm với Heroku, Vercel hoặc AWS. \nDatabase: Có kinh nghiệm làm việc với Postgres. \nMemory storage, Event broker: Kinh nghiệm sử dụng Redis. \nORM: Hiểu biết sâu về ít nhất một trong các ORM như Prisma, Supabase hoặc Drizzle. \nFrontend Framework: Thành thạo Next.js, đặc biệt là phiên bản Next.js 13+. \nBackend Framework: Kinh nghiệm làm việc với NestJS hoặc ExpressJS. \nForm: Sử dụng thành thạo React Hook Form. \nSchema validation: Có kinh nghiệm sử dụng Zod để xác thực dữ liệu. \nƯu tiên: \nCó kinh nghiệm phát triển Smart Contract. \nKỹ năng lập trình Solidity. \nCó kinh nghiệm làm việc với môi trường phát triển Hardhat.', 10000000.00, 25000000.00, 'TP.HCM', 'Contract', '2025-10-07 20:59:18.149534'),
	(124, 113, 116, 'Nhân Viên Tư Vấn Website - Không Yêu Cầu Kinh Nghiệm', 'Gọi điện thoại giới thiệu đến khách hàng về dịch vụ và chương trình khuyến mãi hiện có của công ty.\nTư vấn các sản phẩm của công ty như: Thiết kế website, tên miền, hosting,...\nĐặt lịch hẹn gặp trực tiếp với khách hàng để trao đổi chi tiết và demo sản phẩm cho khách tham khảo.\nLập bảng báo giá, thương lượng và tiến hành kí kết hợp đồng với khách hàng.', '● KHÔNG YÊU CẦU KINH NGHIỆM \n● Từ 18 - 28 tuổi\n● Chào đón các bạn sinh viên mới ra trường, học trái ngành\n● Có kinh nghiệm về sales, tư vấn là một lợi thế\n● Có khả năng giao tiếp tốt, không nói ngọng, nói lắp\n● Chăm chỉ, có tinh thần cầu tiến, ham học hỏi\n● Có kỹ năng làm việc theo nhóm', 8000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(125, 114, 117, 'Nhân Viên IT', 'Tùy theo tình hình vấn đề xảy ra tại các cơ sở trong hệ thống, nhân viên sắp xếp thứ tự quan trọng – ưu tiên – khoảng cách để xử lý.\nĐảm bảo, duy trì hệ thống công nghệ thông tin khối Văn phòng và hệ thống các trung tâm.\nXác định, chuẩn đoán và hỗ trợ người dùng các sự cố về máy tính, tư vấn nâng cấp hệ thống hoặc thiết bị thay thế.\nThiết lập hệ thống mạng nội bộ cho công ty: Cấu hình modem, hệ thống wifi, switch, các thiết bị mạng.\nSửa chữa các thiết bị phần cứng, thiết bị văn phòng: máy in, fax, điện thoại, wifi, camera,…\nLàm việc với các nhà cung cấp về vấn đề bảo hành, bảo trì các thiết bị công nghệ thông tin.\nPhối hợp với các phòng ban khác khi có yêu cầu.\nGhi chép nhật ký sữa chữa và bảo dưỡng thiết bị theo quy định.\nTheo dõi số lượng máy tính và thiết bị mạng và đặt hàng khi thiếu.\nCó kinh nghiệm thi công, bảo trì, bảo dưỡng camera.', 'Tốt nghiệp Cao đẳng trở lên chuyên ngành Công nghệ thông tin, Quản trị mạng, Điện tử viễn thông,…\nCó ít nhất 1 năm kinh nghiệm ở vị trí tương đương \nCó thể di chuyển giữa các cơ sở (Bình Tân – Bình Chánh – Quận 12 – Hóc Môn cũ)\nNắm vững về hệ thống phần cứng máy vi tính \nƯu tiên ứng viên có chứng chỉ quốc tế như CCNA, Microsoft role-based,...\nƯu tiên ứng viên có kinh nghiệm làm việc với Office 365\nKỹ năng làm việc nhóm tốt', 75000000.00, 9000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(126, 115, 118, 'Nhân Viên IT - Tại Tân Bình Ưu Tiên Biếng Tiếng Anh', 'Vận hành hệ thống CNTT\n- Tổ chức quản trị vận hành, giải quyết sự cố kỹ thuật liên quan đến hạ tầng vật lý,Network,Wi-Fi,internet,Firewall Server,Storage / backup,telephony trên toàn hệ thống\n- Vận hành máy chủ và quản trị tài khoản người dùng và hệ quản trị dữ liệu của tất cả phần mềm ứng dụng và website đã triển khai tại công ty chẳng hạn: kế toán,Nhân sự, website công ty,….Bao gồm cả những phần mềm và phần cứng hệ thống mà công ty đang thuê ngoài.\n- Nâng cấp/update hệ điều hành, firmware, service patch trên máy chủ và thiết bị Mạng.\n Tiếp nhận, xử lý và phản hồi các yêu cầu hỗ trợ từ người dùng (giáo viên, nhân viên, học sinh) qua các kênh liên lạc (email, điện thoại, ticket system).\nHỗ trợ cài đặt, cấu hình, khắc phục sự cố phần mềm và phần cứng cho máy tính, laptop, máy in, thiết bị ngoại vi.\nHướng dẫn người dùng sử dụng các ứng dụng và dịch vụ CNTT của trường.\nBảo trì, sửa chữa và thay thế linh kiện phần cứng máy tính, laptop, máy in.\nHỗ trợ quản lý, giám sát và xử lý sự cố mạng LAN, WAN, Wi-Fi.\nHỗ trợ quản lý và bảo trì hệ thống CCTV, máy chấm công, Access control, thiết bị mạng (switch, router, firewall), FreePbx.\nKiểm tra, bảo dưỡng các thiết bị và hạ tầng trong phòng server.\nTừng sử dụng và hỗ trợ người dung trong môi trường AD, O365.\nGiám sát và đảm bảo an toàn thông tin, backup dữ liệu định kỳ.\nQuản lý và hỗ trợ các phần mềm học thuật của trường (ví dụ: ManageBac).\nCài đặt, cấu hình và xử lý sự cố phần mềm chuyên dụng theo yêu cầu của bộ phận học thuật, ban Giám đốc.\nĐảm bảo kết nối và tích hợp giữa các hệ thống phần mềm và dịch vụ CNTT.\nQuản lý thiết bị và tài sản IT.\nLập báo cáo định kỳ về tình trạng thiết bị và hệ thống CNTT.\nĐề xuất nâng cấp, mua sắm và cải thiện hạ tầng CNTT.\nHỗ trợ các sự kiện, hoạt động của trường yêu cầu thiết bị và hạ tầng công nghệ.', 'Tốt nghiệp ngành CNTT.\nCó chứng chỉ CCNA, AZ-800 hoặc AZ-104.\nCó tinh thần chăm chỉ, sáng tạo, chịu được áp lực công việc.\nTiếng Anh giao tiếp trôi chảy.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(127, 116, 119, 'Lập Trình Viên Backend', 'Develop and maintain serverless backend services and microservices for a multi-tenant POS platform.\n\nDesign, build, and maintain highly scalable, reliable, and performant backend systems.\n\nLeverage AWS services (e.g., Lambda, API Gateway, SQS, SNS, DynamoDB, OpenSearch, S3) to architect robust and event-driven infrastructure.\n\nBuild real-time communication layers using WebSocket (via AWS API Gateway + Lambda).\n\nDefine infrastructure using AWS CDK with best practices for IaC.\n\nIntegrate with external services such as payment gateways (Clover, TYSYS,...), SMS gateways (Twilio), and FCM push notifications.\n\nIdentify and resolve bottlenecks, bugs, and production incidents quickly and efficiently.\n\nWrite clean, maintainable, and well-documented code following modern software engineering practices.\n\nCollaborate closely with frontend/mobile engineers, QA, product managers, and designers.\n\nParticipate in code reviews and contribute to knowledge sharing across the team.\n Maintain high test coverage through unit and integration tests (Jest or equivalent).', 'Bachelor’s degree in Computer Science, Information Technology, or related field.\nAt least 2–5 years of experience building backend services using JavaScript/TypeScript with Node.js.\nProven hands-on experience with AWS serverless ecosystem: Lambda, API Gateway, DynamoDB, S3, SQS, SNS, EventBridge, OpenSearch.\nStrong understanding of WebSocket protocols and handling real-time data pipelines.\nExperience with CDK for infrastructure management.\nFamiliarity with designing NoSQL schemas for high-performance querying in a multi-tenant environment.\nSolid foundation in system design, data structures, and algorithms.\nExperience working in agile development teams, using tools like GitHub, JIRA, Notion.\nUnderstanding of security best practices in authentication (JWT), data protection, and API gateway policies.\nFamiliarity with observability tools like AWS CloudWatch, X-Ray, and Sentry.', 20000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(128, 117, 120, 'Nhân Viên IT', 'Nghiên cứu, xây dựng và phát triển một số phần mềm nội bộ\nHỗ trợ nhanh các phòng ban khi xảy ra vấn đề, sự cố liên quan đến mạng, máy tính, điện thoại, email .. \nThực hiện kiểm tra, theo dõi, sửa chữa và nạp mực máy in \nKiểm tra tình trạng bảo mật và quét virus định kỳ tất cả máy tính trong công ty \nQuản lý các thiết bị, linh kiện, vật tư máy tính và máy in \n Đề xuất mua trang thiết bị vật tư kịp thời\nXử lý các vấn đề liên quan đến website như gia hạn tên miền, hosting và cập nhật thông tin\nNghiên cứu, xây dựng và phát triển một số phần mềm nội bộ\nCác công việc khác theo yêu cầu của cấp trên', 'Tốt nghiệp trung cấp trở lên chuyên ngành công nghệ thông tin, có kiến thức về phần mềm\nNam từ 22T-35T\nKinh nghiệm 1-2 năm về phần mềm\nKhông yêu cầu kinh nghiệm phần cứng, sẽ được đào tạo', 9000000.00, 15000000.00, 'Long An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(129, 118, 121, 'IT System', 'Tham mưu về công tác quản lý và phát triển ứng dụng CNTT trong mọi lĩnh hoạt động của công ty. Quản lý, đảm bảo hoạt động và phát triển ứng dụng CNTT trong quản lý, hỗ trợ cho hoạt động sản xuất kinh doanh.\nQuản lý và giám sát hệ thống mạng nội bộ (LAN, WAN, Wifi, VPN)\nCấu hình và vận hành các thiết bị mạng: switch, router, firewall (Fortinet/Cisco/Sophos)\nGiám sát hệ thống mạng bằng các công cụ như Zabbix, PRTG, TheDude,…\nQuản trị hệ thống máy chủ (Windows/Linux), domain controller, DNS, DHCP, File Server, Mail Server\nTriển khai và duy trì hệ thống backup, antivirus, firewall, bảo mật endpoint\nXử lý sự cố kỹ thuật liên quan đến kết nối mạng, truy cập dữ liệu, máy chủ\nTham gia triển khai các dự án nâng cấp mạng, mở rộng hệ thống hạ tầng CNTT\nViết tài liệu kỹ thuật, SOP, sơ đồ mạng, hướng dẫn sử dụng thiết bị\nĐề xuất cải tiến, tối ưu hóa hiệu năng hệ thống mạng – hệ thống máy chủ\nQuản trị Microsoft 365, Exchange Online, Azure AD, cấu hình anti-spam, mail flow rules, phân phối hợp lý.\nThiết lập tổng đài ảo (voicebot) trên nền tảng Asterisk/FreePBX tích hợp AI speech-to-text\nHỗ trợ người dùng trong việc tiếp nhận và xử lý các vấn đề liên quan đến kỹ thuật như cài đặt máy tính, mạng internet, phần mềm, camera, các thiết bị văn phòng (máy in, máy photo, hệ thống chấm công,…) của khối Văn phòng.', 'Có kinh nghiệm tối thiểu 3 năm ở vị trí tương đương.\nTốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Quản trị mạng hoặc các chuyên ngành liên quan\nAm hiểu về hệ thống mạng (LAN, WAN, WIFI), hệ thống máy tính, server (Windows và Linux).\nƯu tiên ứng viên có chứng chỉ: CCNA/CCNP, MCSA/MCSE, Fortinet NSE\nAm hiểu về Nội quy, quy trình, qui định Công ty và các lĩnh vực nghiệp vụ phụ trách..', 0.00, 1000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(130, 119, 122, 'Nhân Viên Kiểm Thử Phần Mềm (Manual Tester)', '- Test các tính năng trên web & mobile app do nhân viên lập trình phát triển\n- Báo lỗi trên tool quản lý bug\n- Theo dõi tình trạng, confirm bug sau khi bug được fix\n- Trao đổi chặt chẽ với nhân viên lập trình, BA về các tính năng và lỗi phát sinh', '- Trung thực, cẩn thận, tinh thần trách nhiệm cao.\n- Ưu tiên ứng viên đã có kinh nghiệm từ 1.5 năm trở lên\n- Nhiệt tình, chủ động, ham học hỏi.\n- Kỹ năng giao tiếp tốt, có khả năng thuyết trình, trình bày rõ ràng các vấn đề là 1 lợi thế.', 7000000.00, 12000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(131, 120, 123, 'Nhân Viên Lập Trình Ứng Dụng (Không Cần Kinh Nghiệm)', 'Phân tích, thiết kế, phát triển phần mềm bằng Python.\nXây dựng & tích hợp API cho backend và ứng dụng mobile.\nLàm việc với SQL Server, xử lý dữ liệu hiệu quả.\nPhân tích & xử lý dữ liệu JSON, hỗ trợ tích hợp hệ thống.\nTham gia nghiên cứu & ứng dụng AI / Machine Learning vào dự án.', 'Không cần kinh nghiệm, sẽ được đào tạo\nHiểu ngôn ngữ lập trình Python.\nBiết SQL Server, JSON, API.\nKiến thức về mobile app là lợi thế.\nĐam mê công nghệ mới, đặc biệt là AI.\nĐọc hiểu tài liệu kỹ thuật tiếng Anh là một điểm cộng.', 7000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(132, 121, 124, 'Chuyên Viên Kỹ Thuật - Phần Cứng - Mạng', '- Xử lý được các sự cố PC, laptop, mạng \n- Nạp mực các dòng máy in thông dụng\n- Sửa được các lỗi máy in trắng đen, máy in màu ( yêu cầu kinh nghiệm trên 1 năm)', '- Bằng cấp: Trung cấp trở lên\n- Kinh nghiệm: 1 năm vị trí tương đương\n- Làm việc lâu dài\n- Có khả năng làm việc theo nhóm\n- Trung thực, vui vẻ, hoà đồng\n- Ưu tiên có kinh nghiệm về: sửa máy in màu', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(133, 122, 125, 'Fresher Flutter Developer', '- Phát triển & duy trì ứng dụng Flutter/Dart đa nền tảng.\n- Thiết kế UI/UX tối ưu (custom widget, animation, state management).\n- Áp dụng OOP, SOLID, design pattern.\n- Thiết kế kiến trúc (MVC, MVVM, Clean Architecture).\n- Tích hợp API (REST, WebSocket, gRPC, GraphQL…).\n- Tối ưu hiệu năng, bảo mật, khả năng mở rộng.', 'Yêu cầu bắt buộc\n- ≥ 1 năm kinh nghiệm làm việc với Flutter/Dart.\n- Thành thạo Flutter UI, state management (Provider, Bloc, Riverpod…).\n- Hiểu rõ OOP, SOLID, design pattern.\n- Kinh nghiệm làm việc với nhiều loại API/protocol.\n- Từng tham gia dự án nhiều người dùng đồng thời (high concurrent users).\nƯu tiên\n- Kinh nghiệm thiết kế kiến trúc ứng dụng và áp dụng Clean Architecture.\n- Kiến thức về tối ưu chi phí tính toán và hiệu suất trên mobile. \n- Kinh nghiệm triển khai ứng dụng trên App Store và Google Play.', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(134, 60, 63, 'Nhân Viên Đào Tạo Phần Mềm', 'Lên kế hoạch, tổ chức các buổi đào tạo (trực tiếp hoặc online) về cách sử dụng phần mềm cho khách hàng mua sản phẩm (đầy đủ phân quyền trong sản phẩm: admin, teacher, student, parents...).\nSoạn và cập nhật các tài liệu như: HDSD, video demo, quy trình thao tác, câu hỏi thường gặp (FAQ)…\nTiếp nhận, giải đáp, hướng dẫn khách hàng khi gặp lỗi hoặc khó khăn trong quá trình sử dụng phần mềm.11assf\nThu thập ý kiến, khó khăn hoặc đề xuất từ khách hàng, sau đó phối hợp với bộ phận kỹ thuật/sản phẩm để xử lý.\nTheo dõi tiến độ và mức độ áp dụng phần mềm, hỗ trợ giải quyết các vấn đề phát sinh trong triển khai.\nPhổ biến những thay đổi, nâng cấp của phần mềm đến khách hàng, tổ chức đào tạo lại (nếu cần).\nKhảo sát khách hàng, phân tích mức độ thành thạo khi sử dụng phần mềm để cải thiện chất lượng đào tạo.', 'Hiểu biết về phần mềm doanh nghiệp: LMS, e-Commerce, Quản lý đề thi, LMS… và cách vận hành cơ bản.\nKiến thức triển khai phần mềm (cơ bản): Phối hợp với các bên liên quan để triển khai nội bộ/hỗ trợ triển khai đến đối tác/khách hàng của công ty. Hiểu biết cơ bản về quy trình phát triển phần mềm: Agile/Scrum.\nTư duy hệ thống, logic và định hướng khách hàng.\nSử dụng thành thạo các phần mềm chuyên ngành liên quan\nThích nghi tốt với môi trường công việc có áp lực cao.\nCó kinh nghiệm tối thiểu 1 năm ở vị trí tương tự hoặc các vai trò như CSKH, triển khai phần mềm, đào tạo nội bộ.\nCó kỹ năng viết tài liệu và đào tạo người dùng.\nCó kinh nghiệm và yêu thích làm các sản phẩm về giáo dục.', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(135, 60, 63, 'Nhân Viên Đào Tạo - Triển Khai Phần Mềm', 'Lên kế hoạch, tổ chức các buổi đào tạo (trực tiếp hoặc online) về cách sử dụng phần mềm cho khách hàng mua sản phẩm (đầy đủ phân quyền trong sản phẩm: admin, teacher, student, parents...).\nSoạn và cập nhật các tài liệu như: HDSD, video demo, quy trình thao tác, câu hỏi thường gặp (FAQ)…\nTiếp nhận, giải đáp, hướng dẫn khách hàng khi gặp lỗi hoặc khó khăn trong quá trình sử dụng phần mềm.11assf\nThu thập ý kiến, khó khăn hoặc đề xuất từ khách hàng, sau đó phối hợp với bộ phận kỹ thuật/sản phẩm để xử lý.\nTheo dõi tiến độ và mức độ áp dụng phần mềm, hỗ trợ giải quyết các vấn đề phát sinh trong triển khai.\nPhổ biến những thay đổi, nâng cấp của phần mềm đến khách hàng, tổ chức đào tạo lại (nếu cần).\nKhảo sát khách hàng, phân tích mức độ thành thạo khi sử dụng phần mềm để cải thiện chất lượng đào tạo.', 'Hiểu biết về phần mềm doanh nghiệp: LMS, e-Commerce, Quản lý đề thi, LMS… và cách vận hành cơ bản.\nKiến thức triển khai phần mềm (cơ bản): Phối hợp với các bên liên quan để triển khai nội bộ/hỗ trợ triển khai đến đối tác/khách hàng của công ty. Hiểu biết cơ bản về quy trình phát triển phần mềm: Agile/Scrum.\nTư duy hệ thống, logic và định hướng khách hàng.\nSử dụng thành thạo các phần mềm chuyên ngành liên quan\nThích nghi tốt với môi trường công việc có áp lực cao.\nCó kinh nghiệm tối thiểu 1 năm ở vị trí tương tự hoặc các vai trò như CSKH, triển khai phần mềm, đào tạo nội bộ.\nCó kỹ năng viết tài liệu và đào tạo người dùng.\nCó kinh nghiệm và yêu thích làm các sản phẩm về giáo dục.', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(136, 123, 126, 'Quản Trị Hệ Thống (System Administrator)', 'Quản lý, bảo trì và nâng cấp hệ thống máy chủ, mạng nội bộ, phần mềm và thiết bị CNTT;\nGiám sát an ninh mạng, sao lưu dữ liệu định kỳ và khôi phục hệ thống khi cần thiết;\nHỗ trợ người dùng nội bộ xử lý sự cố kỹ thuật;\nĐảm bảo tuân thủ nghiêm ngặt các chính sách bảo mật và quy trình CNTT của công ty.', 'Tốt nghiệp Đại học chuyên ngành CNTT, Hệ thống thông tin hoặc các ngành liên quan;\nTối thiểu 3 năm kinh nghiệm trong quản trị hệ thống và quản lý dự án CNTT;\nAm hiểu sâu về Windows Server, Linux, VMware, hệ thống mạng, bảo mật thông tin;\nKỹ năng giao tiếp, quản lý thời gian và giải quyết vấn đề tốt.', 25000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(137, 124, 127, 'Nhân Viên Kỹ Thuật Sửa Chữa, Lắp Ráp Máy Tính, Máy In Có Kinh Nghiệm', '- Cần nhân viên có kinh nghiệm 1 năm trở lên lắp ráp, sữa chữa , máy in, máy tính, latop\n- Biết cài phần mềm office , server, mail outlook,......\n- Biết lắp ráp, máy tính , latop chuyên nghiệp\n- Biết bom mực, sửa máy in các dòng máy', '- Trung thực , kinh nghiệm như nào khai rõ\n- Chăm chỉ , siêng năng, yêu nghề\n- Có tâm trong công việc\n- Làm theo sự chỉ đạo của quản lý', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(138, 125, 128, 'Nhân Viên Marketing', '- Lên chiến lược, kế hoạch SEO website trong lĩnh vực bao bì nhựa\n- Tối ưu hóa website với các công cụ tìm kiếm, tối ưu Onpage.\n- Nghiên cứu từ khóa cho SEO, lên kế hoạch đẩy từ khóa\n- Theo dõi và báo cáo các chỉ số Google Analytics\n- Social Media: Quản lý nội dung trên các trang mạng xã hội như: Facebook, Linkedin, Website, Email Marketing, ...\n- Thiết kế ấn phẩm truyền thông\n-  Phối hợp NVKD xây dựng ý tưởng, chiến lược PR-Marketing cho sản phẩm, dịch vụ của Công ty. \n- Theo dõi và cập nhật tiến độ công việc, báo cáo hiệu quả các chiến dịch cho cấp trên theo tuần/tháng/quý.\n- Đánh giá hiệu suất công việc sau mỗi chiến dịch (KPIs, tương tác, doanh thu tăng trưởng...).\n- Thực hiện các nhiệm vụ khác theo yêu cầu của cấp quản lý.', '- Nam/ Nữ - Tuổi từ 27 tuổi đến 40 tuổi.\n- Tốt nghiệp Cao đẳng/ Đại học chuyên ngành Marketing, trruyền thông, Kinh doanh hoặc các ngành liên quan;\n- Từng làm Marketing cho các Công ty sản xuất.', 12000000.00, 15000000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(139, 126, 129, 'Lập Trình Viên Full- Stack (Full-Stack Developer) - Đi Làm Ngay', '•    Phát triển và bảo trì tính năng trên frontend (Next.js) và backend (Go)\n•    Sử dụng Protocol Buffers và Connect RPC để xây dựng API\n•    Thực hiện các thao tác với cơ sở dữ liệu PostgreSQL thông qua GORM\n•    Tuân thủ các mẫu kiến trúc đã định, bao gồm repository pattern và clean architecture\n•    Viết và duy trì migration để cập nhật cấu trúc database\n•    Phối hợp từ khâu định nghĩa proto đến triển khai giao diện người dùng\n•    Tham gia review code, đảm bảo chất lượng và tính nhất quán.\nThời gian làm việc 9h-17h thứ 2 đến thứ 6', '•    Frontend: Hiểu biết cơ bản về React, TypeScript và JavaScript hiện đại\n•    Backend: Nắm vững kiến thức nền tảng về ngôn ngữ Go\n•    Database: Khả năng đọc/viết SQL và hiểu quan hệ giữa các bảng\n•    Version Control: Sử dụng thành thạo Git và các workflow liên quan\n•    Giải quyết vấn đề: Kỹ năng phân tích, gỡ lỗi tốt\n•    Tư duy học hỏi: Ham học công nghệ mới và các mẫu kiến trúc\nKinh nghiệm ưu tiên\n•    Đã từng làm việc với Next.js App Router và React 19\n•    Hiểu biết về gRPC/Connect RPC hoặc các framework API tương tự\n•    Quen với Docker và các khái niệm containerization\n•    Am hiểu nguyên tắc thiết kế microservices\n•    Kinh nghiệm viết migration và sử dụng ORM\n•    Biết về hệ thống xác thực (ưu tiên NextAuth)', 15000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(140, 33, 36, 'Giáo Viên IT / Coding - Online / Remote', '- Dạy viết mã, lập trình cho trẻ em từ nhóm 6 đến 16 tuổi (lớp học trực tuyến sử dụng Zoom)\n- Mỗi lớp sẽ diễn ra trong 1 giờ.\n- Thời gian (có thể thay đổi tùy theo nhu cầu của phụ huynh và sự sẵn sàng của giáo viên):\n○ Thứ Hai - Thứ Sáu (5:30 chiều - 9:30 tối)\n○ Thứ 7 - Chủ nhật (Thời gian linh hoạt)\n- Chuyên môn về mã hóa (logic, trình tự và cấu trúc) để tạo ra các kết quả sáng tạo như Trò chơi, Ảnh động, ứng dụng và trang web.\n *Địa điểm làm việc :Toàn Quốc', '- Là công dân Việt Nam.\n- B. Tech, M. Tech, BCA, MCA, BE, ME. (Sinh viên mới tốt nghiệp 2022, 2021,2020,2019,2018 đã có kinh nghiệm) CSE, ISE, EEE, IT - CHỈ NỀN TẢNG MÁY TÍNH\n- Có kinh nghiệm ở vị trí giảng dạy sẽ là một lợi thế\n- Có thể giảng dạy nhiều ca trong một tuần.\n- Bạn là người có khả năng xây dựng mối quan hệ và kết nối mạnh mẽ.\n- Kiến thức tốt về Scratch, Python.', 10000000.00, 15000000.00, 'TP.HCM', 'Freelance', '2025-10-07 20:59:18.149534'),
	(141, 127, 130, 'Lập Trình Viên .Net Phát Triển Hệ Thống Quản Lý Kho', 'Tham gia phát triển và mở rộng hệ thống WMS (nền tảng ASP.NET Core + Vue 3). \nViết API backend bằng .NET 8, Entity Framework Core. \nTham gia tích hợp các module mới như: barcode, RFID, báo cáo, đa kho... \nPhối hợp với team để phát triển frontend (Vue3) nếu cần. \nTham gia bảo trì, tối ưu hiệu năng hệ thống. \nViết tài liệu kỹ thuật, ghi chú code rõ ràng.', 'Tốt nghiệp chuyên ngành CNTT hoặc mới ra trường có kiến thức cơ bản vững.\nCó kinh nghiệm thực hành / làm đồ án với .NET Core, C#, EF Core.\nBiết sử dụng Git, hiểu mô hình MVC / REST API\nHiểu kiến trúc client-server, HTTP request/response.\nTư duy logic tốt, ham học hỏi, chủ động trong công việc.\nƯu tiên:\n•    Từng làm việc với VueJS / TypeScript.\n•    Biết Docker, có kinh nghiệm triển khai web app.\n•    Biết về hệ thống WMS hoặc quản lý kho là lợi thế.', 10000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(142, 128, 131, 'Backend Developer', 'Tổng quan: Bạn sẽ là một phần của đội ngũ phát triển sản phẩm, chịu trách nhiệm chính trong việc xây dựng và bảo trì các API, khắc phục lỗi các sản phẩm AI của Easy AI, và phối hợp với các bên liên quan để đảm bảo trải nghiệm tốt nhất cho người dùng cuối.\nPhạm vi công việc: \nXây dựng API cho Frontend\nXử lý các công việc sửa lỗi (fix bugs) trên hệ thống.\nBáo cáo và thực hiện các công việc khác theo sự phân công của Quản lý.', 'Kinh nghiệm từ 3 năm trở lên ở vị trí tương đương.\nKinh nghiệm làm việc với cơ sở dữ liệu (MySQL, PostgreSQL, MongDB ...).\nKinh nghiệm làm việc Laravel Framework. Kinh nghiệm với Vue.js là lợi thế.\nCó kinh nghiệm làm việc với các hệ thống chatbot thương mại và từng sử dụng các công cụ AI là lợi thế.\nĐam mê & có trách nhiệm với công việc. \nCó khả năng làm việc độc lập & tinh thần học hỏi cao.\nCó máy tính cá nhân.', 15000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(143, 129, 132, 'Thực Tập Sinh Ai', 'Hỗ trợ thu thập, phân tích và làm rõ yêu cầu nghiệp vụ từ khách hàng hoặc các phòng ban liên quan.\nHỗ trợ viết tài liệu đặc tả yêu cầu (Business Requirement Document - BRD, SRS, Use Case, User Story...).\nHỗ trợ làm việc với các bộ phận phát triển, kiểm thử và thiết kế để đảm bảo yêu cầu được hiểu đúng và triển khai chính xác.\nTham gia vào quá trình kiểm thử (UAT) và nghiệm thu sản phẩm.\nTham gia các cuộc họp nội bộ và với khách hàng (nếu có), ghi chú và tổng hợp nội dung cuộc họp.\nNghiên cứu và cập nhật các kiến thức về sản phẩm, nghiệp vụ và quy trình phân tích.', 'Sinh viên năm cuối hoặc vừa tốt nghiệp các ngành: Hệ thống thông tin, CNTT, Kinh tế, Quản trị Kinh doanh, hoặc các ngành liên quan.\nCó tư duy logic, kỹ năng phân tích và giải quyết vấn đề tốt.\nGiao tiếp tốt, có khả năng trình bày và viết tài liệu rõ ràng.\nCó kiến thức cơ bản về quy trình phát triển phần mềm (Agile/Scrum là một lợi thế).\nSử dụng được các công cụ hỗ trợ phân tích như: MS Office, Excel, PowerPoint, Draw.io, Figma, Jira, Confluence… là một lợi thế.\nChủ động, cầu tiến và sẵn sàng học hỏi.', 1000000.00, 25000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(144, 130, 133, 'Lập Trình Viên Web Remote PHP Laravel, React, Vue Fullstack', 'Tham gia phát triển, bảo trì và tối ưu hóa các ứng dụng Laravel.\nHỗ trợ xây dựng và triển khai các API cho các ứng dụng frontend.\nLàm việc cùng với các thành viên trong nhóm để thiết kế kiến trúc hệ thống hiệu quả.\nTham gia vào việc kiểm thử và khắc phục sự cố ứng dụng.\nCập nhật tài liệu kỹ thuật và quy trình phát triển.', 'Kiến thức cơ bản về PHP và các framework phổ biến như Laravel.\nHiểu biết về cơ sở dữ liệu (MySQL, PostgreSQL) và SQL.\nKhả năng làm việc nhóm và giao tiếp tốt.\nTinh thần cầu tiến, ham học hỏi và tìm hiểu công nghệ mới.\nKinh nghiệm với HTML, CSS, JavaScript, là một lợi thế.', 7000000.00, 12000000.00, 'TP.HCM', 'Freelance', '2025-10-07 20:59:18.149534'),
	(145, 131, 134, 'Nhân Viên Marketing', 'Viết nội dung giới thiệu sản phẩm, bài PR, bài đăng mạng xã hội\nLên ý tưởng, triển khai các chiến dịch quảng cáo (Facebook, Zalo, Google Ads,...)\nCập nhật và quản lý nội dung website công ty\nTham gia xây dựng hình ảnh thương hiệu\nHỗ trợ bộ phận kinh doanh khi cần thiết\nChi tiết công việc sẽ được trao đổi cụ thể trong buổi phỏng vấn', 'Có Kinh nghiệm marketing, chạy ads đa nền tảng: tiktok, gg ads, fb ads,... \nCó tư duy sáng tạo, chủ động học hỏi, trách nhiệm cao\nBiết edit video, ảnh cơ bản, có thiết bị làm việc cá nhân\nYêu thích công nghệ, nhanh nhạy với các xu hướng marketing online\nCó thể làm việc độc lập và theo nhóm\nChấp nhận sinh viên mới ra trường / thực tập sinh', 7000000.00, 10000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(146, 132, 135, 'Nhân Viên IT Phần Cứng', 'Chịu trách nhiệm bảo trì, sửa chữa các thiết bị máy tính, máy in, server.\nVận hành và duy trì hệ thống server, mạng LAN, WAN, CAM.\nTriển khai hệ thống phần mềm, quản lý website.\nHỗ trợ người dùng sử dụng hệ thống thông tin trong trường học.\nBáo cáo, sửa chữa định kì các hệ thống.\nCác công việc được giao khác.', 'Tốt nghiệp Trung Cấp, Cao Đẳng hoặc Đại Học chuyên ngành Công nghệ thông tin, mạng máy tính & an ninh mạng hoặc có liên quan\nCó kiến thức và kinh nghiệm về công nghệ thông tin, hệ thống mạng, phần mềm, phần cứng máy tính, cơ sở dữ liệu và các công nghệ mới nhất\nTừ 01 năm kinh nghiệm về hỗ trợ người dùng Support/Helpdesk\nCó kiến thức và kinh nghiệm về Window Server, Microsoft SQL, phần cứng máy tính\nNắm vững kiến thức TCP/IP , đọc hiểu tài liệu.\nCó chứng chỉ MCSA, CCNA là lợi thế.', 8000000.00, 10000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(147, 60, 63, 'Nhân Viên Triển Khai - Đào Tạo Phần Mềm', 'Lên kế hoạch, tổ chức các buổi đào tạo (trực tiếp hoặc online) về cách sử dụng phần mềm cho khách hàng mua sản phẩm (đầy đủ phân quyền trong sản phẩm: admin, teacher, student, parents...).\nSoạn và cập nhật các tài liệu như: HDSD, video demo, quy trình thao tác, câu hỏi thường gặp (FAQ)…\nTiếp nhận, giải đáp, hướng dẫn khách hàng khi gặp lỗi hoặc khó khăn trong quá trình sử dụng phần mềm.\nThu thập ý kiến, khó khăn hoặc đề xuất từ khách hàng, sau đó phối hợp với bộ phận kỹ thuật/sản phẩm để xử lý.\nTheo dõi tiến độ và mức độ áp dụng phần mềm, hỗ trợ giải quyết các vấn đề phát sinh trong triển khai.\nPhổ biến những thay đổi, nâng cấp của phần mềm đến khách hàng, tổ chức đào tạo lại (nếu cần).\nKhảo sát khách hàng, phân tích mức độ thành thạo khi sử dụng phần mềm để cải thiện chất lượng đào tạo.', '-    Hiểu biết về phần mềm doanh nghiệp: LMS, e-Commerce, Quản lý đề thi, CMS… và cách vận hành cơ bản.\n-    Kiến thức triển khai phần mềm (cơ bản): Phối hợp với các bên liên quan để triển khai nội bộ/hỗ trợ triển khai đến đối tác/khách hàng của công ty.\n-    Hiểu biết cơ bản về quy trình phát triển phần mềm: Agile/Scrum.\n-    Tư duy hệ thống, logic và định hướng khách hàng.\n-    Có kinh nghiệm tối thiểu 1 năm ở vị trí tương tự hoặc các vai trò như CSKH, triển khai phần mềm, đào tạo nội bộ.\n-    Có kỹ năng viết tài liệu và đào tạo người dùng.', 8000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(148, 133, 136, 'Nhân Viên IT Kv Quận 11', '- Hỗ trợ triển khai và vận hành phần mềm quản lý doanh nghiệp (ERP/CRM/Kế toán/Nhân sự,...).\n- Thiết kế, chỉnh sửa, quản lý website công ty trên nền tảng phần mềm Odoo.\n- Cùng team tham gia phân tích, tìm hiểu rõ các yêu cầu/mong muốn từ công ty.\n- Xử lý các lỗi phát sinh, hỗ trợ người dùng trong quá trình sử dụng hệ thống.\n- Chịu tránh nhiệm về hệ thống mạng nội bộ, Camera và các hệ thống khác tại các tòa nhà.\n- Nâng cấp, bảo trì máy tính và trang thiết bị văn phòng\n- Công việc khác do cấp trên giao.- Địa điểm làm việc: 70 Hòa Bình, Phường 5, Quận 11, Thành phố Hồ Chí Minh\n- Thời gian làm việc: \n+ Giờ làm việc   : 7h30 – 17h15\n+ Nghỉ trưa          : 11h30 – 13h\n+ Ngày nghỉ         : Chủ nhật hàng tuần', '- Tốt nghiệp Cao đẳng/Đại học chuyên ngành CNTT, Khoa học máy tính hoặc các ngành liên quan.\n- Có kinh nghiệm làm việc với phần mềm quản lý doanh nghiệp như ERP, CRM, HRM, phần mềm kế toán,...\n- Có kinh nghiệm làm việc với phần mềm Odoo (ưu tiên biết tùy biến giao diện, xây dựng website trên Odoo).\n- Kỹ năng phân tích, giải quyết vấn đề và làm việc nhóm tốt.\n- Ưu tiên ứng viên đã từng triển khai hệ thống ERP cho doanh nghiệp.', 8000000.00, 13000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(149, 134, 137, 'Nhân Viên Chăm Sóc Khách Hàng - Dịch Vụ Website', 'Tiếp nhận, giải đáp các thắc mắc, phàn nàn của khách hàng và đưa ra hướng giải quyết.\nTiếp nhận các dự án website đã hoàn thành để cung cấp các dịch vụ, sản phẩm tiếp theo liên quan: Domain, Email, Hosting, Quảng cáo web\nChăm sóc khách hàng mới về dịch vụ sản phẩm của công ty.\nTiếp nhận và xúc tiến yêu cầu chỉnh sửa web, nâng cấp web.\nHỗ trợ hướng dẫn sử dụng web cho khách hàng.\nTiếp nhận và xúc tiến yêu cầu chăm sóc web: Cập nhật nội dung, hình ảnh bài viết cho khách hàng,...', 'Khả năng giao tiếp tốt, hòa đồng, hội nhập nhanh.\nCó tinh thần trách nhiệm và chịu được áp lực công việc.\nCó hiểu biết về website.\nGiỏi vi tính văn phòng (word, excel).\nKinh nghiệm: Ít nhất 1 năm kinh nghiệm ở vị trí chăm sóc khách hàng.\nPhẩm chất cá nhân: Nhanh nhẹn, Trung thực, nhiệt tình công tác.', 7000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(150, 135, 138, 'Lập Trình Viên', '- Tham gia phân tích, thiết kế và phát triển phần mềm cho nhiều dự án khác nhau.\n- Nâng cấp hệ thống, phát triển các yêu cầu bổ sung tính năng phần mềm.\n- Tham gia nghiên cứu và phát triển các dự án, sản phẩm thực tế đã có của Công ty như Cổng thông tin điện tử, Toà soạn điện tử, Phần mềm Quản lý văn bản và điều hành, Phần mềm Quản lý công việc, Phần mềm CSDL Ngành Giáo dục……\n- Phối hợp cùng đội ngũ BA/Test phân tích, thiết kế, đưa ra giải pháp để phát triển phần mềm đáp ứng yêu cầu của người dùng cuối.\n- Nghiên cứu, phát triển các giải pháp mới', '- Tốt nghiệp ngành CNTT, công nghệ phần mềm, toán tin hoặc tương đương\n- Có kiến thức về lập trình hướng đối tượng (OOP), SOLID, DDD (Domain Driven Design)\n- Lập trình và phát triển nền tảng .NET Framework hoặc .Net Core (C-Sharp, Web MVC và Web API)\n- Có kinh nghiệm làm việc với: SQL Server, MongoDB, Oracle\n- Có kinh nghiệm làm việc với: Angular, Angularjs, VueJS, Reactjs, …\n- Có khả năng xây dựng các Web Services, WCF, API và kết nối khác.\n- Có kinh nghiệm triển khai phần mềm theo kiến trúc micro-services (là một lợi thế)\n- Hiểu biết về JavaScript, HTML, CSS\n- Có kỹ năng lập trình App là một lợi thế: Flutter hoặc Native App\n- Có trách nhiệm cao trong công việc, sẵn sàng thu xếp thời gian để hoàn thành công việc theo yêu cầu dự án.', 8000000.00, 30000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(151, 136, 139, 'Trợ Lý Giám Đốc', 'Tham mưu cho Ban Giám Đốc về các quyết định tài chính, kế toán, đầu tư, kinh doanh.\nTham gia vào quá trình xây dựng kế hoạch kinh doanh, kế hoạch chi phí, lương thưởng hàng năm.\nKiểm tra và rà soát các báo cáo tài chính trong Công ty, báo cáo kết quả hoạt động kinh doanh, dòng tiền, bảng cân đối kế toán; tổng hợp về tình hình kinh doanh, tình hình tài chính chung của Công ty.\nĐánh giá cấu trúc chi phí, các yếu tố rủi ro tài chính tiềm ẩn trong công ty và đề xuất các giải pháp kiểm soát, tối ưu.\nHỗ trợ phòng Tài Chính Kế toán trong công việc tổ chức, vận hành bộ máy kế toán và hệ thống tài chính kế toán Công ty; Kiểm soát dòng tiền ra vào Công ty, đề xuất phương án giải quyết khi có vấn đề phát sinh.\nCập nhật các quy định về thuế, tài chính có ảnh hưởng đến hoạt động của công ty và dự án, đưa ra tư vấn sơ bộ cho Giám Đốc\nTheo dõi việc lập và thực hiện kế hoạch của các phòng ban rồi có báo cáo hàng tuần với giám đốc theo tuần/tháng/năm\nThực hiện một số công việc khác do Giám Đốc trực tiếp giao.', 'Kiến thức \nTốt nghiệp Đại học trở lên các chuyên ngành: Tài chính Doanh nghiệp, Đầu tư, Kế toán, Kiểm toán, Kinh tế hoặc các ngành liên quan.\nTối thiểu 3-5 năm kinh nghiệm làm việc trong lĩnh vực tài chính. Ưu tiên ứng viên có kinh nghiệm tại các vị trí Kế toán tổng hợp, kế toán trưởng, kiểm toán viên.\nỨng viên có kinh nghiệm làm ở các đơn vị tư vấn kế toán, tư vấn thuế là một lợi thế.\nKiến thức sâu rộng về luật liên quan tài chính kế toán, luật thuế, luật kế toán.\nKiến thức quản lý, phân bổ ngân sách, chi phí doanh nghiệp\nKỹ năng:\nKỹ năng giao tiếp, đàm phán\nKỹ năng tổng hợp và phân tích báo cáo\nKỹ năng lập kế hoạch\nKỹ năng quản trị rủi ro\nKỹ năng quản lý, tổ chức công việc, giám sát thực hiện công việc\nSử dụng Word, Excel thành thạo (có khả năng làm báo cáo độc lập trên Excel)\nPhẩm chất cá nhân\nĐạo đức tốt, nhiệt tình với công việc.\nCẩn thận, chịu khó học hỏi\nTrung thực, Khách quan;\nTrách nhiệm trong công việc\nChịu được áp lực cao trong công việc.', 15000000.00, 25000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(152, 137, 140, 'Nhân Viên Kỹ Thuật Máy Tính – Máy In', '- Lắp ráp, cài đặt, sửa chữa máy tính, máy in, máy photocopy\n- Nạp mực máy in, máy photocopy\n- Thi công, lắp đặt hệ thống mạng LAN, Internet, Camera\n- Thời gian làm việc: Thứ 2 – Thứ 7: Sáng 7h30 – 11h30 | Chiều 13h00 – 17h00\n- Nghỉ chiều Thứ 7 & Chủ Nhật', '- Ưu tiên người có kinh nghiệm\n- Tốt nghiệp Trung cấp kỹ thuật trở lên hoặc tương đương\n- Nhanh nhẹn, nhiệt tình, trung thực, ham học hỏi', 8000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(153, 138, 141, 'Giáo Viên Tin Học Part-Time', 'Trực tiếp giảng dạy chương trình Tin học quốc tế tại các trường Tiểu học, THCS, THPT.\nỨng viên trúng tuyển sẽ được AQV đào tạo bổ sung thêm chuyên môn giảng dạy chuyên nghiệp.\nNghiên cứu các chương trình học, phương pháp giảng dạy, phát triển tư duy cho học sinh.\nQuản lý lớp học: quản lý các thiết bị và phần mềm máy tính trong lớp học. \nHình thức làm việc: cộng tác giảng dạy, hay làm toàn thời gian.', 'Tốt nghiệp Đại học chuyên ngành: CNTT, Tin học, Khoa học máy tính, Mạng máy tính, Tin học quản lý (ưu tiên Sư phạm Tin học). \nNếu GV tốt nghiệp đại học không phải ngành Sư phạm, thì cần bổ sung thêm chứng chỉ NVSP, có thể bổ sung sau.\nCó kiến thức và kỹ năng chuyên môn tốt (ưu tiên các ứng viên đã có các chứng chỉ IC3 Spark/ IC3/ MOS).\nỨng viên yêu thích công việc giảng dạy, nhiệt tình, vui vẻ, tác phong làm việc chuyên nghiệp.\nGiáo viên Tin học chuyên lập trình: Có khả năng dạy tốt: Scratch, Python, VBA macro trong Excel.\nGiáo viên Tin học ứng dụng: Có khả năng dạy tốt: IC3 GS6, MOS, CCUD CNTT. (Ứng viên phù hợp sẽ được trung tâm hỗ trợ tập huấn thêm chuyên môn).', 10000000.00, 18000000.00, 'TP.HCM', 'Part-time', '2025-10-07 20:59:18.149534'),
	(154, 139, 142, 'Thực Tập Sinh Lập Trình Game Unity', 'Tham gia phát triển game mobile trên nền tảng Unity.\nCùng team xây dựng các tính năng gameplay, UI/UX, animation và logic game.\nTích hợp tài nguyên game: âm thanh, hình ảnh, prefab, v.v.\nHỗ trợ kiểm tra, sửa lỗi và tối ưu hiệu suất game.\nTham gia brainstorm cùng đội ngũ phát triển game.', 'Là sinh viên năm 3 trở lên các trường Đại học thuộc khối ngành CNTT, Kỹ thuật phần mềm, Khoa học máy tính, hoặc tương đương.\nBiết lập trình C# và sử dụng Unity Editor cơ bản.\nYêu thích làm game, chủ động học hỏi và có trách nhiệm với công việc.\nCó sản phẩm cá nhân hoặc từng làm đồ án Unity là lợi thế.\nƯu tiên ứng viên có thể thực tập full-time (hoặc ít nhất 4 buổi/tuần).', 3000000.00, 6000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(155, 140, 143, 'Marketing Intern', 'Hỗ trợ lên ý tưởng và thực hiện các chiến dịch Marketing.\nViết bài content cho fanpage, website và các nền tảng mạng xã hội khác.\nHỗ trợ quản lý và phát triển kênh social media.\nTheo dõi, phân tích insight khách hàng và đánh giá các chỉ số đo lường hiệu quả của content marketing.\nPhối hợp với các bộ phận khác để đảm bảo tiến độ công việc.\nHỗ trợ công việc hành chính liên quan đến phòng Marketing.', 'Sinh viên năm 4 hoặc mới tốt nghiệp chuyên ngành Marketing, Truyền thông, Quản trị kinh doanh hoặc các ngành liên quan.\nCó hiểu biết cơ bản về Marketing.\nKỹ năng viết lách tốt, sáng tạo, chủ động trong công việc.\nBiết sử dụng các công cụ thiết kế cơ bản như Canva, Capcut,…\nTinh thần học hỏi, cầu tiến, ham tìm hiểu.', 1000000.00, 15000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(156, 141, 144, 'Hà Nội - Nhân Viên IT (IT Support / IT Helpdesk)', 'Quản lý, bảo trì PC, laptop, máy in, thiết bị IT tại văn phòng, kho, cửa hàng khu vực miền Bắc\n Hỗ trợ kỹ thuật (Level 1) các sự cố mạng LAN, camera, máy chấm công, họp trực tuyến… theo SLA\n Cập nhật và quản lý danh sách tài sản CNTT, phối hợp nhà cung cấp bảo trì/sửa chữa\n Hỗ trợ IT khi khai trương/đóng cửa hàng, thực hiện kế hoạch bảo dưỡng thiết bị định kỳ', 'Tốt nghiệp Cao đẳng/Đại học CNTT, Điện tử viễn thông hoặc liên quan\n Thành thạo thiết bị, phần mềm, mạng máy tính và xử lý sự cố IT\n Kỹ năng quản lý thời gian, giải quyết vấn đề, làm việc nhóm tốt', 10000000.00, 12000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(157, 142, 145, 'Nhân Viên IT - Bình Chánh', '- Cài đặt hệ điều hành, hỗ trợ người dùng về các vấn đề kỹ thuật.\n- Quản trị hệ thống mạng máy tính nội bộ của công ty.\n- Quản trị hệ thống phần mềm chấm công, camera của công ty.\n- Cài đặt, quản trị phần mềm kế toán, hệ thống email và website của công ty.\n- Hướng dẫn, giúp đỡ người dùng máy tính tại các hệ thống của công ty qua teamviewer hoặc đến trực tiếp.\n- Kiểm tra, chẩn đoán và khắc phục sự cố (sửa chữa hoặc thay thế linh kiện, gỡ lỗi...).\n- Ghi chép nhật ký sữa chữa và bảo dưỡng thiết bị theo quy định.\n- Theo dõi số lượng máy tính và thiết bị mạng và đặt hàng khi thiếu.\n- Có ký năng quản lý, giám sát nhân viên qua điện thoại, camera, teamview…\n- Thực hiện các công việc khác theo yêu cầu của quản lý.', '- Học vấn: Tốt nghiệp Cao Đẳng, Đại Học chuyên ngành Công nghệ thông tin, Kỹ thuật máy tính,...\n- Kinh nghiệm:\nCao Đẳng: kinh nghiệm làm việc từ 4-6 năm.\nĐại Học trở lên: kinh nghiệm làm việc từ 1-3 năm\n- Những kỹ năng, năng lực và ngoại ngữ yêu cầu:\nCó kinh nghiệm tại vị trí IT hoặc vị trí liên quan.\nCó khả năng nắm bắt nguyên lý và vận hành thiết bị.\nNắm vững và áp dụng tiêu chuẩn an toàn của thiết bị.\nCó thể thiết kế và thi công những mạch điện điểu khiển máy đơn giản không quá phức tạp.\nCó khả năng học hỏi nhanh, thường xuyên cập nhật các kiến thức mới đáp ứng công việc.\nCó khả năng phân tích, tìm kiếm, xử lý thông tin tốt.\nCẩn thận, có trách nhiệm, sáng tạo.\nCó tinh thần teamwork, có trách nhiệm với công việc.\nKhả năng giao tiếp lưu loát, lịch sự, khéo léo, ứng xử linh hoạt và xử lý các tình huống tốt, có khả năng làm việc dưới môi trường chịu áp lực cao.\nCó định hướng xác định gắn bó lâu dài với công ty.', 11000000.00, 13000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(158, 142, 145, 'Nhân Viên Công Nghệ Thông Tin - Củ Chi', '- Cài đặt hệ điều hành, hỗ trợ người dùng về các vấn đề kỹ thuật.\n- Quản trị hệ thống mạng máy tính nội bộ của công ty.\n- Quản trị hệ thống phần mềm chấm công, camera của công ty.\n- Cài đặt, quản trị phần mềm kế toán, hệ thống email và website của công ty.\n- Hướng dẫn, giúp đỡ người dùng máy tính tại các hệ thống của công ty qua teamviewer hoặc đến trực tiếp.\n- Kiểm tra, chẩn đoán và khắc phục sự cố (sửa chữa hoặc thay thế linh kiện, gỡ lỗi...).\n- Ghi chép nhật ký sữa chữa và bảo dưỡng thiết bị theo quy định.\n- Theo dõi số lượng máy tính và thiết bị mạng và đặt hàng khi thiếu.\n- Có ký năng quản lý, giám sát nhân viên qua điện thoại, camera, teamview…\n- Thực hiện các công việc khác theo yêu cầu của quản lý.', '- Học vấn: Tốt nghiệp Cao Đẳng, Đại Học chuyên ngành Công nghệ thông tin, Kỹ thuật máy tính,...\n- Kinh nghiệm:\nCao Đẳng: kinh nghiệm làm việc từ 4-6 năm.\nĐại Học trở lên: kinh nghiệm làm việc từ 1-3 năm\n- Những kỹ năng, năng lực và ngoại ngữ yêu cầu:\nCó kinh nghiệm tại vị trí IT hoặc vị trí liên quan.\nCó khả năng nắm bắt nguyên lý và vận hành thiết bị.\nNắm vững và áp dụng tiêu chuẩn an toàn của thiết bị.\nCó thể thiết kế và thi công những mạch điện điểu khiển máy đơn giản không quá phức tạp.\nCó khả năng học hỏi nhanh, thường xuyên cập nhật các kiến thức mới đáp ứng công việc.\nCó khả năng phân tích, tìm kiếm, xử lý thông tin tốt.\nCẩn thận, có trách nhiệm, sáng tạo.\nCó tinh thần teamwork, có trách nhiệm với công việc.\nKhả năng giao tiếp lưu loát, lịch sự, khéo léo, ứng xử linh hoạt và xử lý các tình huống tốt, có khả năng làm việc dưới môi trường chịu áp lực cao.\nCó định hướng xác định gắn bó lâu dài với công ty.', 11000000.00, 13000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(159, 142, 145, 'Nhân Viên Công Nghệ Thông Tin - IT', '- Cài đặt hệ điều hành, hỗ trợ người dùng về các vấn đề kỹ thuật.\n- Quản trị hệ thống mạng máy tính nội bộ của công ty.\n- Quản trị hệ thống phần mềm chấm công, camera của công ty.\n- Cài đặt, quản trị phần mềm kế toán, hệ thống email và website của công ty.\n- Hướng dẫn, giúp đỡ người dùng máy tính tại các hệ thống của công ty qua teamviewer hoặc đến trực tiếp.\n- Kiểm tra, chẩn đoán và khắc phục sự cố (sửa chữa hoặc thay thế linh kiện, gỡ lỗi...).\n- Ghi chép nhật ký sữa chữa và bảo dưỡng thiết bị theo quy định.\n- Theo dõi số lượng máy tính và thiết bị mạng và đặt hàng khi thiếu.\n- Có ký năng quản lý, giám sát nhân viên qua điện thoại, camera, teamview…\n- Thực hiện các công việc khác theo yêu cầu của quản lý.', '- Học vấn: Tốt nghiệp Cao Đẳng, Đại Học chuyên ngành Công nghệ thông tin, Kỹ thuật máy tính,...\n- Kinh nghiệm:\nCao Đẳng: kinh nghiệm làm việc từ 4-6 năm.\nĐại Học trở lên: kinh nghiệm làm việc từ 1-3 năm\n- Những kỹ năng, năng lực và ngoại ngữ yêu cầu:\nCó kinh nghiệm tại vị trí IT hoặc vị trí liên quan.\nCó khả năng nắm bắt nguyên lý và vận hành thiết bị.\nNắm vững và áp dụng tiêu chuẩn an toàn của thiết bị.\nCó thể thiết kế và thi công những mạch điện điểu khiển máy đơn giản không quá phức tạp.\nCó khả năng học hỏi nhanh, thường xuyên cập nhật các kiến thức mới đáp ứng công việc.\nCó khả năng phân tích, tìm kiếm, xử lý thông tin tốt.\nCẩn thận, có trách nhiệm, sáng tạo.\nCó tinh thần teamwork, có trách nhiệm với công việc.\nKhả năng giao tiếp lưu loát, lịch sự, khéo léo, ứng xử linh hoạt và xử lý các tình huống tốt, có khả năng làm việc dưới môi trường chịu áp lực cao.\nCó định hướng xác định gắn bó lâu dài với công ty.', 11000000.00, 13000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(160, 60, 63, 'Nhân Viên Triển Khai Phần Mềm', '- Tham gia khảo sát yêu cầu, phân tích các quy trình nghiệp vụ mô tả của khách hàng.\n- Xây dựng tài liệu nghiệp vụ dựa trên kết quả khảo sát.\n- Thực hiện vận hành, chạy thử, đánh giá mức độ phù hợp của phần mềm đối với các yêu cầu của khách hàng.\n- Tham gia đào tạo và chuyển giao phần mềm cho khách hàng.\n- Hướng dẫn, hỗ trợ người dùng vận hành hệ thống, kiểm tra kết quả vận hành.\n- Hỗ trợ khách hàng trong quá trình vận hành và sử dụng hệ thống.\n- Kiểm thử hệ thống và tìm các lỗi hệ thống, phối hợp với lập trình viên hoàn chỉnh hệ thống.\n- Phối hợp với Kinh doanh demo hệ thống cho khách hàng.', '- Học vấn: Tốt nghiệp Cao đẳng trở lên.\n- Kiến thức: Ưu tiên có kiến thức về phần mềm e-learning, triển khai phần mềm LMS.\n- Kỹ năng chuyên môn: Ưu tiên có hiểu biết về hệ thống quản lý cơ sở dữ liệu Microsoft SQL.\n- Khả năng: Giao tiếp tốt, tự tin.\n- Yêu cầu chung: Có tinh thần học hỏi, siêng năng, nhanh nhẹn, năng động, trung thực và tinh thần cầu tiến.\n- Tính cách: Chính xác, cần mẫn, chịu khó.', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(161, 143, 146, 'Nhân Viên IT Helpdesk', 'Xây dựng, triển khai, vận hành và quản trị hệ thống CNTT (máy tính, máy in, mạng, máy chủ, lưu trữ...) và các thiết bị bổ trợ.\nQuản trị hệ thống sever, cơ sở dữ liệu, bảo mật hệ thống, website, thư điện tử… thay đổi tài khoản người dùng và mật khẩu, backup…\nQuản lý hệ thống email công ty (Google Zimbra)\nTham gia xử lý sự cố liên quan tới máy chủ, lưu trữ, user, các dịch vụ mạng và các thiết bị bổ trợ.\nQuản trị phần mềm CRM cho khối bán hàng (thêm tài khoản, phân quyền tài khoản)\nQuản trị phần mềm nhân sự (1office)\nĐề xuất, chuẩn bị máy tính và các thiêt bị phụ trợ\nNghiên cứu, nắm vững các sản phẩm, công nghệ, giải pháp hệ thống, ứng dụng công nghệ mới\nPhát triển và tiêu chuẩn hóa hệ thống tài liệu kỹ thuật mạng bảo mật, máy chủ, lưu trữ, backup.Nghiên cứu, nắm vững các sản phẩm, công nghệ, giải pháp hệ thống, ứng dụng công nghệ mới\nPhát triển và tiêu chuẩn hóa hệ thống tài liệu kỹ thuật mạng bảo mật, máy chủ, lưu trữ, backup.\nQuản lý máy chấm công công ty\nHỗ trợ các bộ phận khác giải quyết các vấn đề liên quan đến công nghệ, mạng máy tính.\nHỗ trợ khối nhà máy các vấn đề liên quan tới chuyên môn', '1. Trình độ học vấn tối thiểu:\nCao đẳng chuyên ngành CNTT, ĐTVT.\nƯu tiên các trường Đại học Bách Khoa Hà Nội; Đại học Quốc Gia Hà Nội;Học viện công nghệ bưu chính viễn thông\n2. Kinh nghiệm tối thiểu: ít nhất 2 năm trở lên về các lĩnh vực\nQuản trị hệ thống server Window\nQuản trị các thiết bị văn phòng\n3. Yêu cầu chuyên môn:\nCó kiến thức chuyên môn về quản trị máy chủ và dịch vụ hệ thống, hệ thống mạng LAN, WAN, am hiểu về các dòng máy chủ\nCó kiến thức chuyên môn về bảo mật, am hiểu thiết bị lưu trữ dữ liệu, công nghệ ảo hóa, công nghệ điện toán đám mây…\nƯu tiên sử dụng tốt các hệ điều hành: MS Windows Server, Linux, Centos\nCó kinh nghiệm cấu hình và quản trị hệ thống lớn cluster (OS-DB) và cân bằng tải web server.\nCó kinh nghiệm trong việc cải thiện hiệu năng của cơ sở dữ liệu là một lợi thế', 13000000.00, 16000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(162, 144, 147, 'Cộng Tác Viên Nhân Sự Admin', 'Hỗ trợ tạo nội dung và đăng bài tuyển dụng theo từng vị trí công ty yêu cầu trên website, SNS.\nQuản lý dữ liệu thông tin ứng viên trên hệ thống quản lý của công ty.\nTiếp nhận, sàng lọc hồ sơ ứng viên phù hợp với yêu cầu công ty đưa ra.\nBáo cáo hiệu quả của các kế hoạch thu thập khảo sát cho phòng nhân sự.\nPhối hợp với phòng nhân sự để lên kế hoạch tổ chức tiệc, sự kiện cho công ty.\nHỗ trợ công việc hành chính, bổ sung vật tư, văn phòng phẩm, snacks.\nHỗ trợ công việc kế toán: scan tài liệu, lưu hồ sơ, chứng từ, rà soát hồ sơ.\nCác công việc khác theo yêu cầu của phòng nhân sự, kế toán.', 'Có Laptop cá nhân.\nBiết sử dụng các website tạo poster như Canva, Figma,...\nCó kỹ năng viết nội dung và đăng tuyển trên mạng xã hội.\nCó kỹ năng quản lý thời gian và tối ưu hiệu suất làm việc.\nCẩn thận, chi tiết, có tinh thần học hỏi, có trách nhiệm cao và trung thực.\nỨng viên có kinh nghiệm trong lĩnh vực IT là 1 lợi thế.', 1000000.00, 3000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(163, 145, 148, 'Nhân Viên Tuyển Sinh', '● Trực fanpage, tư vấn và hỗ trợ khách hàng quan tâm đến khóa học.\n● Tìm kiếm, phát triển dữ liệu khách hàng từ các nguồn khác để đảm bảo chỉ tiêu tuyển sinh.\n● Khai thác tuyển sinh các nguồn từ các trung tâm, trường học, các kênh social \n● Theo dõi và chăm sóc khách hàng cũ - lắng nghe feedback – upsale.\n● Thực hiện các công việc khác theo yêu cầu của quản lý.', '● Tốt Nghiệp Cao Đẳng, Đại học trở lên yêu thích công việc Tư vấn, tuyển sinh\n● Có ít nhất 06 tháng kinh nghiệm tại vị trí tương đương \n● Có thái độ tận tâm, chuyên nghiệp trong công việc\n● Có Laptop cá nhân', 11000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(164, 146, 149, 'Nhân Viên Thiết Kế Website', 'Thiết kế giao diện website trên CMS Wordpress\nThiết kế các yếu tố đồ họa (banner, icon, hình ảnh, landing page, slider, email template…) phục vụ website và các nền tảng số khác.\nTham gia xây dựng ý tưởng hình ảnh cho các chiến dịch thương hiệu\nĐảm bảo tính thân thiện trên thiết bị di động (Responsive Design).\nNghiên cứu xu hướng thiết kế mới và đề xuất cải tiến cho giao diện website.\nTham gia bảo trì, chỉnh sửa giao diện, cập nhật nội dung khi cần.\nThực hiện các nhiệm vụ khác theo yêu cầu của trưởng bộ phận hoặc quản lý dự án.', 'Tốt nghiệp Trung học/Cao đẳng chuyên ngành Thiết kế Đồ họa, Thiết kế Web, CNTT hoặc liên quan.\nSử dụng thành thạo một trong các các phần mềm thiết kế liên quan: Adobe Photoshop, v.v.\nKiến thức cơ bản về HTML, CSS, JavaScript là một lợi thế.\nCó tư duy sáng tạo, thẩm mỹ tốt, am hiểu UX/UI.\nKỹ năng làm việc nhóm, quản lý thời gian và giao tiếp tốt.\nCẩn thận, tỉ mỉ, có trách nhiệm cao với công việc.', 6000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(165, 29, 32, 'Senior PHP Developer', '1. Mục tiêu công việc \nĐảm bảo việc phát triển hệ thống ứng dụng Website/ Website Ecommerce/ các tích hợp có liên quan đến website khác. \n 2. Mô tả công việc \nThiết kế, phát triển và duy trì phần backend của website thương mại điện tử, sử dụng framework Symfony. \nTích hợp các API bên thứ ba, bao gồm cổng thanh toán, sàn thương mại điện tử (Shopee, Lazada, TikTok Shop), và hệ thống vận chuyển. \nĐảm bảo hiệu suất, bảo mật và khả năng mở rộng của hệ thống backend. \nXây dựng các chức năng quản lý đơn hàng, quản lý kho, và theo dõi tình trạng giao hàng. \nLàm việc chặt chẽ với đội frontend để triển khai các tính năng mới, đảm bảo tích hợp mượt mà giữa frontend và backend. \nTối ưu hóa cơ sở dữ liệu và truy vấn để đảm bảo tốc độ và hiệu quả xử lý. \nQuản lý và cải tiến các quy trình CI/CD (Continuous Integration/Continuous Deployment) để tự động hóa việc triển khai. \nGiải quyết các lỗi phát sinh và đảm bảo uptime cao cho website thương mại điện tử. \nTham gia phân tích yêu cầu, đề xuất giải pháp kỹ thuật và lập tài liệu chi tiết về hệ thống. \nĐào tạo và hỗ trợ các thành viên trong đội phát triển.', '1. Trình độ và kinh nghiệm \nTốt nghiệp đại học chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc lĩnh vực liên quan. \nTối thiểu 5 năm kinh nghiệm phát triển website backend, trong đó ít nhất 3 năm kinh nghiệm trên các framework phổ biến. \nƯu tiên ứng viên đã từng tham gia dự án triển khai mới website Thương Mại Điện Tử cho doanh nghiệp sản xuất hoặc thương mại, bán lẻ. \n 2. Kiến thức và kỹ năng chuyên môn \nTối thiểu 5 năm kinh nghiệm phát triển website backend, trong đó ít nhất 3 năm kinh nghiệm trên làm việc với framework Symfony hoặc Laravel \nƯu tiên trên 5 năm kinh nghiệm về PHP. \nThành thạo làm việc với cơ sở dữ liệu phổ biến My SQL. \nCó kinh nghiệm với các API. \nHiểu biết về các công nghệ bảo mật và mã hóa trong thương mại điện tử. \nƯu tiên: Có kinh nghiệm phát triển hệ thống đa kênh tích hợp (omnichannel).', 25000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(166, 147, 150, 'Quản Lý Triển Khai Dự Án CNTT', 'Quản lý và triển khai dự án công nghệ thông tin, tích hợp hệ thống liên quan như: Hệ thống máy chủ; lưu trữ; hệ thống backup; thiết bị mạng và bảo mật; thi công cabling và di dời phòng máy chủ\nTiếp nhận yêu cầu triển khai theo hợp đồng từ phòng kinh doanh hoặc quản lý bộ phận.\nPhối hợp với các bộ phận liên quan, các đối tác và khách hàng lập kế hoạch triển khai khi nhận được yêu cầu.\nKiểm soát hiệu quả tiến độ triển khai, báo cáo các vấn đề bất thường, các rủi ro liên quan ảnh hưởng đến việc thực hiện hợp đồng.\nTham gia xử lý các thủ tục hồ sơ cần thiết của dự án thuộc phạm vi kỹ thuật (nếu có)\nPhối hợp với Bộ phận kinh doanh cho ý kiến tư vấn triển khai phù hợp khi được yêu cầu\nXử lý các khiếu nại khách hàng và đưa ra hành động khắc phục/phòng ngừa (liên quan đến chuyên môn)\nThực hiện các nhiệm vụ khác theo phân công của cấp trên\nBáo cáo công việc cho Trưởng bộ phận kỹ thuật/Trưởng phòng kinh doanh dự án liên quan', 'Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Điện tử viễn thông.\nĐã từng tham gia triển khai tích hợp hệ thống đối với các dòng máy chủ/lưu trữ/giải pháp backup của các hãng như: HPE; DELL; IBM; NetApp; Fujitsu; ...\nĐã từng làm việc trên các nền tảng công nghệ ảo hóa như: Vmware; HyperV; ...\nCó kiến thức về: môi trường Microsoft Windows Server; Linux (Ubuntu; CentOS; ...)\nHiểu biết quy trình làm việc trong môi trường Datacenter\nCó kiến thức về networking phục vụ cho công việc triển khai tích hợp hệ thống\nHiểu biết quy trình triển khai dự án Công nghệ thông tin\nCác kỹ năng văn phòng khác phục vụ công việc\nChấp nhận đi công tác tại các địa phương ngoài Tp. Hồ Chí Minh\nĐam mê công việc kỹ thuật\nCó khả năng làm việc nhóm và làm việc độc lập\nChịu được áp lức cao trong công việc\nNghiêm túc, gắn bó với công việc\nNhạy bén, linh hoạt, cầu tiến, trung thực', 15000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(167, 148, 151, 'Kỹ Thuật Máy Tính', '- Nhận biết các lỗi cơ bản về phần cứng của máy tính .\n- Thành thạo công việc lắp ráp máy tính, nâng cấp linh kiện. Thi công mạng, lắp đặt thiết bị mạng, cài đặt wifi, modem, lắp đặt và cài đặt máy in, máy fax. \n- Cài đặt HĐH, phần mềm ứng dụng, phần mềm đồ họa : photoshop, autocad,corel,...\n- Kiểm tra và sửa lỗi phần mềm máy tính, máy văn phòng. \n- Kiểm tra và sửa lỗi hệ thống mạng Lan, mạng Internet. \n- Bảo dưỡng hệ thống máy tính, máy văn phòng.', '- Kinh nghiệm: 2 Năm\n- Thành thạo tay nghề, am hiểu kỹ thuật, năng động, nhiệt tình, ham học hỏi.Nam\n- Ưu tiên những ứng viên biết đổ mực và thay linh kiện máy in\n- Trong công việc cần trung thực , nhanh nhẹn, chịu áp lực công việc cao, chăm chỉ, sức khỏe tốt.', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(168, 149, 152, 'Nhân Viên IT (Network & Cctv Specialist / Senior IT Engineer)', 'Thiết kế, triển khai, và quản lý hệ thống mạng nội bộ (LAN/WAN) cho nhà máy hoặc văn phòng sản xuất.\nCài đặt, cấu hình, và bảo trì hệ thống camera giám sát (CCTV, camera IP) để đảm bảo an ninh và giám sát sản xuất.\nXử lý sự cố liên quan đến mạng và camera (mất kết nối, lỗi hình ảnh, hoặc cấu hình sai).\nGiám sát hiệu suất hệ thống mạng và camera, đề xuất nâng cấp hoặc tối ưu hóa khi cần.\nPhối hợp với các bộ phận khác để tích hợp hệ thống mạng và camera với các giải pháp sản xuất (như ERP, IoT).\nLàm việc với nhà cung cấp để triển khai hoặc sửa chữa thiết bị mạng và camera.\nĐào tạo và hỗ trợ nhân viên nội bộ về cách sử dụng hệ thống CNTT liên quan.\nLập báo cáo định kỳ về tình trạng hệ thống mạng và camera.', 'Tốt nghiệp Cao đẳng/ Đại học chuyên ngành Công nghệ thông tin, Điện tử viễn thông, hoặc lĩnh vực liên quan.\nCó ít nhất 5 năm kinh nghiệm trong quản trị mạng và hệ thống camera giám sát (CCTV, camera IP) tại các công ty sản xuất hoặc khu công nghiệp.\nThành thạo cấu hình và quản lý hệ thống mạng (LAN, WAN, VPN, firewall) sử dụng thiết bị của Cisco, Fortinet, Mikrotik, hoặc tương tự.\nKinh nghiệm lắp đặt, vận hành, và bảo trì hệ thống camera giám sát (Hikvision, Dahua, Axis, hoặc các thương hiệu tương tự), bao gồm cả hệ thống camera IP và tích hợp với phần mềm quản lý (VMS).\nHiểu biết về các giao thức mạng (TCP/IP, DNS, DHCP, VLAN) và hệ thống an ninh mạng cơ bản.\nƯu tiên có chứng chỉ chuyên môn như CCNA, CCNP, MTCNA, hoặc chứng chỉ liên quan đến hệ thống camera giám sát.\nKỹ năng phân tích, xử lý sự cố nhanh chóng, và làm việc độc lập hoặc theo nhóm.', 15000000.00, 25000000.00, 'Long An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(169, 150, 153, 'Graphic Designer', 'Thiết kế hình ảnh phục vụ chạy quảng cáo Facebook, Zalo, TikTok… theo brief có sẵn\nThiết kế banner, social post, hình ảnh landing page đơn giản\nHỗ trợ chỉnh sửa hình ảnh theo feedback từ Content, Account\nTìm hiểu và cập nhật các xu hướng thiết kế online mới\nBiết sử dụng Canva\nBiết chụp hình, quay phim cơ bản', 'Sinh viên mới tốt nghiệp hoặc có kinh nghiệm 6 tháng ngành thiết kế đồ họa, mỹ thuật, truyền thông...\nBiết sử dụng cơ bản Photoshop, Illustrator (có thể đào tạo thêm)\nCó tinh thần học hỏi, chịu được deadline, teamwork tốt\nCó gu thẩm mỹ, yêu thích quảng cáo & truyền thông\nƯu tiên có portfolio cá nhân nhỏ hoặc sản phẩm làm trong trường/làm thêm\nBiết sử dụng Công Nghệ AI\nBiết sử dụng Canva\nBiết chụp hình, quay phim cơ bản', 5000000.00, 7000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(170, 109, 112, 'Thực Tập Sinh IT Support / IT Helpdesk (Phần Cứng)', 'Set up các phòng học vi tính, hệ thống mạng,... \nXử lý sự cố máy tính về phần cứng \nCài đặt các chương trình học cho Trung Tâm và học viên \nHỗ trợ các công việc kỹ thuật chung của Công Ty \nLàm việc tại các khu vực: ưu tiên sắp xếp cho sinh viên làm việc gần nhà \nKhu vực 1: Thủ Đức, Bình Thạnh, Phú Nhuận, Quận 1, Quận 3 \nKhu vực 2: Nhà Bè, Quận 4, Quận 5, Quận 7, Quận 10, Quận 11 \nKhu vực 3: Bình Chánh, Bình Tân, Tân Phú, Quận 6, Quận 8 \nKhu vực 4: Hóc Môn, Quận 12, Gò Vấp, Tân Bình', 'Nhận thực tập sinh, sinh viên mới ra trường học chuyên ngành Kỹ thuật máy tính, CNTT, Tin học, Quản trị mạng hay các ngành liên quan \nCó xe máy, lý lịch, hồ sơ rõ ràng \nTrung thực, năng động và có trách nhiệm cao trong công việc', 5000000.00, 2000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(171, 151, 154, 'Nhân Viên Lập Trình', 'Tham gia phát triển và xây dựng các sản phẩm\nTìm hiểu công nghệ, xây dựng mới và phát triển tính năng hiện tại của các dự án\nTham gia vào thiết kế và review source code\nĐảm bảo tiến độ, chất lượng công việc và báo cáo thường xuyên tới quản lý\nTrao đổi chi tiết khi phỏng vấn', 'Có tối thiểu 1 - 3 năm kinh nghiệm trong lĩnh vực phát triển web\nCó kinh nghiệm làm việc với Angular (preferable), HTML, CSS, JavaScript\nCó kinh nghiệm làm việc với Nodejs (Nestjs)\nCó kinh nghiệm làm việc với RDBMS như MySQL, SQL, PostgreSql\nCó kinh nghiệm làm việc với API\nKỹ năng phân tích, tư duy logic tốt, chuyên nghiệp\nCẩn thận, chi tiết, chủ động, có trách nhiệm cao, sẵn sàng học hỏi, chia sẻ và cải thiện', 7000000.00, 13000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(172, 152, 155, 'Backend Developer', 'Phát triển và duy trì API: Thiết kế, phát triển và triển khai các API RESTful và sử dụng NestJS để phục vụ các ứng dụng web và mobile.\nQuản lý cơ sở dữ liệu: Làm việc với PostgreSQL để thiết kế schema cơ sở dữ liệu, viết các truy vấn hiệu quả và tối ưu hóa hiệu suất cơ sở dữ liệu.\nXây dựng logic nghiệp vụ: Triển khai các logic nghiệp vụ phức tạp, đảm bảo tính đúng đắn, bảo mật và hiệu suất của hệ thống.\nTối ưu hóa hiệu suất: Xác định và khắc phục các vấn đề về hiệu suất trong các ứng dụng backend và cơ sở dữ liệu.\nViết unit/integration test: Đảm bảo chất lượng mã thông qua việc viết và duy trì các bài kiểm tra tự động.\nTích hợp hệ thống bên ngoài: Tích hợp với các dịch vụ và API của bên thứ ba khi cần thiết.', 'Học vấn: Tốt nghiệp Đại học chuyên ngành phát triển phần mềm hoặc các ngành liên quan\nKinh nghiệm và kỹ năng: \nCó ít nhất 2 năm kinh nghiệm thực tế trong việc phát triển backend.\nThành thạo TypeScript, Git\nCó kinh nghiệm vững chắc với cơ sở dữ liệu PostgreSQL, bao gồm thiết kế cơ sở dữ liệu, tối ưu hóa truy vấn, và quản lý dữ liệu.\nKinh nghiệm làm việc với các ORM/ODM như TypeORM\nCó kinh nghiệm viết unit tests và integration tests\nNắm vững kiến thức và kinh nghiệm phát triển ứng dụng backend với framework NestJS (bao gồm Modules, Controllers, Providers, Guards, Interceptors, Pipes, v.v.).\nHiểu biết sâu sắc về thiết kế API RESTful và các nguyên tắc thiết kế API tốt \nCó kiến thức về các kiến trúc hệ thống phân tán và microservices là một lợi thế.\nKhả năng phân tích và giải quyết vấn đề một cách logic và hiệu quả.\nTinh thần trách nhiệm cao, chủ động trong công việc và khả năng làm việc độc lập cũng như làm việc nhóm.\nKhả năng đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.', 18000000.00, 23000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(173, 153, 156, 'Nhân Viên Vận Hành Kho', 'Sắp xêp kho bãi, soạn hàng \nNhập dữ liệu sản phẩm.\nThời gian làm việc : \n  Sáng 8h -12h\n  Chiều : 1h30-5h30 \nThời gian từ thứ 2 đến Thứ sáu + Sáng thứ 7\nNghỉ chiều thứ 7 và Chủ Nhật', 'Biết sử dụng máy vi tính\nKhông vướng bận gia đình\nLàm việc toàn thời gian giờ hành chính.', 7000000.00, 8000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(174, 29, 32, 'Junior Front-End Developer', '• Develop the application(Front-End)/ functions/ modules/ reports by using programming languages, such: Javascript/HTML/CSS, SQL Database, Web server and HTTP.\n• Understand the architect of business application, such ERP, POS, DMS, Web Ecommerce,…\n• Support and train End-Users using business applications or business functions.\n• Monitor, tuning the performance & update the document of source-code.\n• Join in deployment for new IT projects.\n• Perform other tasks requested by Line Manager or Company’s management.', '• Bachelor degree (University/College) in Information Technology, major: Software development or MIS.\n• Must have:\no Proven working experience at least 1 years in software development with language:HTML, \nCSS, PHP and Nuxtjs .\no Using source control Git, IDE Visual Code.\no Problem solving skill.\no Result-oriented.\no Open-mined with positive thinking & can-do attitude.\n• Nice-to have:\no Have experience with Vue,SQL Database, Web server and HTTP.\no Have experience in building a web application.\no Have experienced to work at or implement the project at the production and trading companies\nis a plus.\no Good communication.\no Good presentation skill\n Working time: Monday - Friday (8AM - 5.30PM)', 10000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(175, 154, 157, 'Nhân Viên Hành Chánh- IT', 'Quản lý hệ thống máy tính và mạng máy tính\nBảo trì sửa chữa phần cứng lẫn phần mềm cho các đơn vị và nghiên cứu ứng dụng công nghệ thông tin cho trong việc quản lý sản xuất kinh doanh. \nQuản lý việc sử dụng Internet của toàn Công ty theo quy định.\nThực hiện công tác quản trị cơ sở hạ tầng văn phòng Công ty như nhà cửa, trang thiết bị văn phòng, điện nước, hoa kiểng, bảng quảng cáo.', 'Tốt nghiệp Đại Học công nghệ thông tin', 12000000.00, 15000000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(176, 155, 158, 'Thực Tập Sinh Công Nghệ Thông Tin (Full_Time)', 'Tiếp nhận thông tin khách hàng\nLên ý tưởng trang Website cho khách hàng\nTư vấn về bố cục, màu sắc, chức năng của trang Website\nCùng bộ phận kỹ thuật hỗ trợ giúp khách hàng có trang Website phù hợp nhất\nKiểm tra và bàn giao cho khách hàng\nQuản lý trang Website khách hàng\nChăm sóc khách hàng\nCác công việc khác theo sự sắp xếp của công ty', 'Không ngại giao tiếp\nSiêng năng, chịu khó học hỏi\nLàm việc giờ hành chính (8h-17h)', 7000000.00, 15000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(177, 156, 159, 'Lập Trình Viên Tích Hợp Dữ Liệu', 'Tham gia triển khai các dự án của công ty\nĐưa các giải pháp tích hợp dữ liệu theo yêu cầu khách hàng\nLàm việc trên các phần mềm giải pháp ETL (Extract, Transform, Load) chuyên dụng như: Oracle Data Integrator (ODI), SAP Data Services,….\nLàm việc trên các công cụ BI (Business Intelligence) chuyên dụng như: Oracle Business Intelligence, Oracle Analytics Server, Tableau,..\nTham gia thiết kế xây dựng mô hình dữ liệu\nXây dựng các ETL Jobs,procedure\nTối ưu hóa các ETL Jobs, các câu lệnh truy vấn dữ liệu\nThực hiện các công việc khác theo yêu cầu của Quản trị dự án', 'Trình độ học vấn/ bằng cấp: \nTốt nghiệp Đại Học ngànhCông Nghệ ThôngTin, Toán Tin, Hệ Thống Thông Tin hoặc các ngành tương đương khác\nKiến thức chuyên môn\nBiết lập trình ngôn ngữ SQL, PL/SQL.Viết procedure, package,….\nHiểu biết các công cụ tích hợp ETL, OracleData Integrator (ODI) là lợi thế\nBiết về hệ quản trị CSDL  \nKinh nghiệm làm việc \nTối thiểu 2 năm kinh nghiệmvề xử lý tích hợp dữ liệu\nCó kinh nghiệmphát triển báo cáo BI\nKỹ năng: Hoạch định, Phân tích ra quyết định, Tổ chức, Giao tiếp, Đàm phán, Phân công\nỦy quyền, Kiểm tra\nGiám sát, Đánh giá, Thuyết trình, Giải quyết vấn đề\nNgoại ngữ: Tiếng Anh đọc hiểu tài liệu', 12000000.00, 25000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(178, 157, 160, 'Thực Tập Lập Trình Embedded / Iot', 'Thực tập (giai đoạn trước khi tham gia dự án thực tế) về phát triển các hệ thống Embedded, AIoT như: thiết bị quan trắc - điều khiển, hệ thống truyền thông, camera thông minh, thiết bị y tế ...\nLập trình cho các thiết bị edge devices (như Raspberry Pi, ESP32, Jetson Nano) và tính toán tại cloud (như AWS)\nTham gia vào các quá trình từ thiết kế, phát triển, kiểm thử đến triển khai hệ thống phần cứng và phần mềm\nTiếp cận, nghiên cứu, ứng dụng các công nghệ mới về AI, Edge Computing, IoT\nThực tập xây dựng tài liệu báo cáo, quản lý dự án', 'Có kinh nghiệm lập trình ngôn ngữ C/C++/C#, Python tối thiểu 06 tháng và khả năng học hỏi nhanh\nTốt nghiệp đại học các chuyên ngành Điện - Điện tử, Cơ – Điện tử, CNTT, Kỹ thuật máy tính với tư duy lập trình tốt\nCó kinh nghiệm lập trình với ít nhất một loại thuộc MCU, SoC hay SoM như: Rasp Pi, ESP32, Jetson Nano, Zynq, ...\nCó khả năng hàn, lắp mạch điện tử\nƯu tiên ứng viên biết tiếng Nhật\nLợi thế: \nCó hiểu biết về Embedded Linux, Android, ESP-IDF, ...\nCó khả năng sử dụng tiếng Anh trong công việc\nCó tinh thần làm việc nhóm, năng động, có khả năng làm việc dưới áp lực cao\nBiết sử dụng Altium trong thiết kế mạch điện tử', 1000000.00, 2000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(179, 158, 161, 'Thực Tập Sinh Lập Trình Vi Điều Khiển - Ai', 'Lập trình điều khiển thiết bị nhúng (Raspberry/Arduino/AI/v.v.v) và các module liên quan.\nHỗ trợ thiết kế và thử nghiệm hệ thống điều khiển.\nCác hoạt động chuyên môn khác được phân công.', 'Sinh viên năm 3, năm 4 chuyên ngành Điện tử, Tự động hóa hoặc Công nghệ thông tin \nTư duy logic, cẩn thận, ham học hỏi.\nĐối với các ứng viên chuyên ngành Điện tử, Tự động hóa: \n                 + Đã từng tham gia đồ án môn học có lập trình điều khiển liên quan Raspberry (hoặc Arduino).\n                 + Ưu tiên các bạn đã biết cơ bản lập trình python/MicroPython.\nĐối với các ứng viên chuyên ngành Công nghệ thông tin : \n                 + Có kiến thức và kỹ năng thực hành đạt tối thiểu ở mức cơ bản về Python.\n                 + Ưu tiên các bạn đã từng có đồ án môn học liên quan xử lý ảnh hoặc âm thanh bằng python.\nThời gian thực tập tối thiểu 12 tuần.', 5000000.00, 5000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(180, 72, 75, 'Nhân Viên IT Helpdesk (Uob)', 'Kiểm tra đầu ngày hệ thống (camera, tổng đài...) nội bộ ở hội sở, chi nhánh.\nKiểm tra khắc phục các lỗi hư hỏng vật lý thiết bị tin học.\nThay thế/ nâng cấp thiết bị phần cứng thiết bị tin học.\nDi chuyển vị trí thiết bị tin học trong cùng trụ sở; hoặc di chuyển thiết bị tin học phòng ban Hội sở/ Chi nhánh sang vị trí mới theo kế hoạch phát triển mạng lưới.\nXử lý các yêu cầu về hệ điều hành/ phần mềm cơ bản trên máy trạm.\nXử lý các lỗi liên quan mạng WAN, LAN, wifi/ internet.\nKhắc phục hỗ trợ lỗi phần mềm từ xa\nHỗ trợ xử lý lỗi máy in/scan\nHỗ trợ phòng họp\nBáo cáo công việc ngày, tuần, tháng.\nThực hiện các công việc khác theo yêu cầu của trưởng bộ phận.', 'Ứng viên có từ 2 năm kinh nghiệm ở vị trí tương đương\nTốt nghiệp Cao đẳng trở lên chuyên ngành Công nghệ thông tin, Quản trị mạng, Điện tử viễn thông,...\nNắm vững về hệ thống phần cứng máy vi tính\nCó kiến thức tốt về các loại Hệ điều hành như Windows, MS Office365 và các lỗi thường gặp với máy tính văn phòng.\nCó kinh nghiệm về phần mềm virus Trellix\nƯu tiên ứng viên có chứng chỉ MCSA(không yêu cầu chứng chỉ quốc tế).\nCó tư duy luôn lấy khách hàng làm trọng tâm.\nCó thể giao tiếp tiếng anh (mức cơ bản)', 13000000.00, 16000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(181, 159, 162, 'Ai Engineer Intern', 'Tìm hiểu và thực nghiệm các mô hình ngôn ngữ lớn (LLM) như ChatGPT, LLaMA, Mistral,…\nTham gia xử lý hình ảnh: nhận diện, phân loại, segmentation,…\nThu thập, làm sạch và xử lý dữ liệu huấn luyện cho mô hình AI.\nTham gia vào các dự án xử lý ngôn ngữ tự nhiên (NLP): phân tích, chuẩn hóa, gán nhãn dữ liệu văn bản.\nViết các script Python cơ bản phục vụ tiền xử lý, huấn luyện và đánh giá mô hình.\nLàm việc với dữ liệu từ cơ sở dữ liệu (SQL, SQLite) hoặc file CSV.\nThử nghiệm tích hợp mô hình AI vào các ứng dụng mẫu: chatbot, hệ thống phân loại văn bản, nhận diện hình ảnh,…\nTheo dõi và cập nhật các xu hướng AI mới qua tài liệu, báo cáo, diễn đàn công nghệ.\nĐề xuất ý tưởng và công nghệ mới cùng nhóm phát triển.', 'Sinh viên năm cuối hoặc mới tốt nghiệp chuyên ngành: Khoa học máy tính, AI, Kỹ thuật phần mềm, hoặc liên quan.\nCó kiến thức cơ bản về Machine Learning, Deep Learning hoặc Xử lý ngôn ngữ tự nhiên (NLP) là một lợi thế.\nThành thạo lập trình Python.\nHiểu và sử dụng tốt các thư viện phổ biến như: NumPy, Pandas, Scikit-learn, OpenCV.\nTừng sử dụng hoặc có trải nghiệm với các thư viện AI như: PyTorch, TensorFlow, Hugging Face,\nCó kỹ năng phân tích dữ liệu, xử lý file CSV, và kiến thức cơ bản về SQL.\nTư duy logic tốt, chủ động học hỏi công nghệ mới.\nKỹ năng làm việc nhóm, cởi mở trong việc chia sẻ và đóng góp ý tưởng.\nĐã từng tham gia các khóa học, dự án nghiên cứu hoặc đồ án liên quan đến AI là điểm cộng', 4000000.00, 5000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(182, 160, 163, 'Nhân Viên Thiết Kế In Ấn, Qùa Tặng, Quảng cáo', 'Tiếp nhận thông tin thiết kế từ bộ phận bán hàng\nLên thiết kế 2D-3d và Mockup sản phẩm theo yêu cầu của khách hàng\nBiết dàn trang – bình bài –xuất file in offset\nĐảm bảo các ấn phẩm thiết kế đạt yêu cầu về tính thẩm mỹ, đúng màu sắc Branding thương hiệu của khách hàng \nChụp và chỉnh sửa hình ảnh sản phẩm mà công ty đã sản xuất phục vụ cho mục đích lưu trữ và marketing\nHỗ trợ bộ phận marketing thiết kế banner cho website, Facebook, Zalo…\nQuản lý, lưu trữ các file tài liệu thiết kế mà mình đảm nhận', 'Tốt nghiệp Cao đẳng/Đại học chuyên ngành Thiết kế đồ họa\nSử dụng thành thạo các phần mềm thiết kế: Photoshop, AI,..\nCó tính sáng tạo cao trong công việc \nCẩn thận, tỉ mỉ, trung thực và làm việc có trách nhiệm.\nCó kinh nghiệm tối thiểu từ 6 tháng đến 1 năm.\nKỹ năng làm việc chính xác, tổ chức công việc tốt và có khả năng làm việc độc lập.\nSẵn sàng học hỏi, cập nhật kiến thức mới và làm việc chăm chỉ trong môi trường đòi hỏi sự chính xác và trách nhiệm cao.', 8000000.00, 14000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(183, 161, 164, 'Nhân Viên SEO Web', '- Tối ưu website với các công cụ tìm kiếm Google \n- SEO từ khóa website trên các công cụ tìm kiếm…. \n- Biết cách triển Entity (Khai thác các nguồn backlink chất lượng)\n- Quảng bá dịch vụ sản phẩm của công ty trên các diễn đàn, blog, mạng xã hội,... \n- Lập kế hoạch phân tích đánh giá từ khóa, đánh giá thị trường thông qua mức độ tìm kiếm từ khóa \n- Thực hiện chiến dịch xây dựng link liên kết, hệ thống website của công ty \n- Sử dụng các công cụ hỗ trợ để đẩy mạnh kết quả SEO \n- Theo dõi thứ hạng từ khóa, lập báo cáo thứ hạng từ khóa', '- Cầu thị, ham học hỏi\n- Hiểu biết cơ bản về Photoshop (Xử lý hình ảnh trước khi đăng website)\n- Có kiến thức cơ bản về kỹ năng (onpage, offpage) \n- Có khả năng xây dựng backlink, guest posting, và các phương pháp SEO Off-page khác.\n- Sử dụng thành thạo các công cụ, mạng xã hội bloger, facebook, \n- Có kỹ năng làm việc với wordpress, blogsport,..\n- Kinh nghiệm làm trong lĩnh vực SEO từ 1-2 năm trở lên\n- Đã từng SEO lên top các từ khóa trước đó(Trình bày trong CV) \n- Trung thực, nhiệt tình, năng động và có trách nhiệm với công việc\n - Khả năng làm việc độc lập, theo nhóm', 10000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(184, 162, 165, 'Thực Tập Sinh Lập Trình - Software Intern', 'Tham gia vào quá trình phân tích yêu cầu (BA), lập trình (coding) và kiểm thử (testing) trong các dự án nội bộ hoặc dự án với đối tác.\nHỗ trợ nhóm phát triển trong việc nghiên cứu và xây dựng các sản phẩm phần mềm mới.\nThực hiện các công việc khác theo sự phân công và hướng dẫn của quản lý trực tiếp hoặc trưởng nhóm kỹ thuật.', 'Có tinh thần chăm chỉ, chủ động học hỏi và mong muốn phát triển trong lĩnh vực công nghệ.\nCó kiến thức nền tảng về lập trình ở một hoặc nhiều mảng sau:\n- Back-end / Front-end / Mobile / Kiểm thử phần mềm\n- Ưu tiên ứng viên có kinh nghiệm với C#, .NET, WPF, SQL Server\nCó hiểu biết cơ bản về hệ điều hành Linux là một lợi thế.\nLà sinh viên năm 4 trở lên hoặc có kỹ năng lập trình tốt tương đương.\nƯu tiên ứng viên có thể thực tập toàn thời gian (full-time).\nThời gian thực tập tối thiểu 3 tháng.\nCó laptop cá nhân để phục vụ công việc trong thời gian thực tập.', 1000000.00, 2000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(185, 163, 166, 'Backend Developer (Chuyên Node.Js)', 'Phát triển và tối ưu các tính năng mới nhằm đáp ứng nhu cầu của người dùng.\nViết và duy trì API kết nối giữa các hệ thống, phục vụ trao đổi dữ liệu với front-end và mobile app.\nTham gia phân tích, thiết kế kiến trúc hệ thống, đảm bảo khả năng mở rộng và hiệu suất.\nNhận yêu cầu từ cấp trên, phân tích và triển khai nhanh chóng, đảm bảo đúng tiến độ và chất lượng.\nPhối hợp chặt chẽ với các team front-end, mobile và QA để đảm bảo tính ổn định và đồng bộ của sản phẩm.', 'Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ Thông tin hoặc tương đương.\nCó ít nhất 3 năm kinh nghiệm làm Backend Developer với Node.js.\nỨng viên từng làm việc với .NET là điểm cộng.\nCó kinh nghiệm làm việc với các cơ sở dữ liệu: PostgreSQL, MySQL, MongoDB.\nHiểu rõ kiến trúc và triển khai RESTful API.\nVững kiến thức lập trình: OOP, Design Patterns.\nCó kinh nghiệm với Git, SVN.\nCó khả năng viết unit test, hiểu các nguyên tắc kiểm thử cơ bản.\nƯu tiên có kinh nghiệm với: Elasticsearch, Kibana, Jenkins, docker, cấu hình server, CI/CD pipelines.\nTư duy logic tốt, chủ động trong công việc.\nKỹ năng làm việc nhóm và giao tiếp kỹ thuật hiệu quả.\nCó khả năng đọc hiểu tài liệu tiếng Anh chuyên ngành.', 25000000.00, 35000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(186, 164, 167, 'Business Analyst', 'PHÂN TÍCH NGHIỆP VỤ\nTìm hiểu, nghiên cứu giải pháp Salesforce\nTư vấn các phương án hiệu quả cho khách hàng về xây dựng hệ thống CRM.\nTrình bày giải pháp cho khách hàng.\nHỗ trợ trong việc tổ chức triển khai giải pháp cho khách hàng.\nTRIỂN KHAI\nLập kế hoạch khảo sát và phân tích yêu cầu của khách hàng.\nKhảo sát và thu thập yêu cầu người dùng.\nLập tài liệu phân tích yêu cầu người dùng, phân tích yêu cầu phần mềm.\nXác định công nghệ, giải pháp nghiệp vụ giải quyết các vấn đề liên quan đến yêu cầu người dùng.\nLập tài liệu thiết kế tổng thể, thiết kế chi tiết.\nCấu hình hệ thống Salesforce hoặc công nghệ mà công ty cung cấp phù hợp với đặc thù yêu cầu nghiệp vụ\nViết tài liệu mô tả yêu cầu người dùng, mô tả tổng quan chức năng kèm với wireframe, flow.\nPhối hợp bộ phận kiểm thử, QC để đảm bảo giải pháp đáp ứng yêu cầu nghiệp vụ, sản phẩm đáp ứng nhu cầu người dùng.\nXây dựng tài liệu đào tạo, tiến hành đào tạo và thực hiện hỗ trợ kỹ thuật sản phẩm và giải pháp cho khách hàng cuối sau khi bàn giao hệ thống.', 'Có từ 1.5 năm kinh nghiệm ở vị trí phân tích nghiệp vụ để chuyển thành quy trình hệ thống ở domain Marketing, CRM..\nCó am hiểu về hệ thống Automation Marketing, CRM, Loyalty.\nCó kinh nghiệm xây dựng giải pháp marketing ở các dự án khác nhau.\nCó kinh nghiệm làm việc với SQL và HTML, CSS, scripting cơ bản.\nCó kinh nghiệm làm việc với dữ liệu và sử dụng Excel để xử lý dữ liệu phục vụ cho các use case marketing đơn giản.\nCó am hiểu về hệ thống Salesforce Marketing Cloud (và các module liên quan) là một lợi thế.\nCó kinh nghiệm viết tài liệu nghiệp vụ, phân tích nghiệp vụ với các dự án cỡ vừa\nCó tư duy tốt về phân tích hệ thống.\nCó khả năng giao tiếp, trao đổi yêu cầu, tư vấn và thuyết phục khách hàng, giao tiếp với đối tác và các team liên quan phục vụ công việc.\nCó tinh thần tự học, tìm hiểu về kiến thức, ngành nghề, công nghệ ứng dụng phù hợp\nCó kỹ năng prompt AI để hoàn thành công việc hiệu quả.\nCó khả năng sử dụng thành thạo tiếng Anh để nghiên cứu, đọc viết các tài liệu (Có thể giao tiếp bằng tiếng Anh là một lợi thế).', 12000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(187, 165, 168, 'Nhân Viên Dịch Vụ Khách Hàng (Offline) - Thu Nhập Từ 10Tr - Lâm Đồng', '- Liên hệ danh sách khách hàng được giao qua cuộc gọi, tin nhắn, tìm hiểu nhu cầu, vấn đề của khách hàng trong quá trình sử dụng phần mềm và vận dụng kĩ năng nghiệp vụ đã được đào tạo để đưa ra tư vấn, hỗ trợ cho khách hàng trực tiếp\n\n- Đào tạo, hướng dẫn sử dụng phần mềm cho khách hàng mới;\n\n- Xây dựng và quản lý mối quan hệ tốt đẹp với khách hàng;\n\n- Ghi nhận các khiếu nại từ khách hàng và phối hợp với các bộ phận liên quan để xử lý theo đúng quy trình;\n\n- Thực hiện các chương trình khảo sát tới khách hàng, tổng hợp và báo cáo cho cấp trên theo kế hoạch;\n\n- Lắng nghe góp ý, phản hồi của khách hàng, tổng hợp và đề xuất giải pháp cho khối phát triển sản phẩm để cải tiến phần mềm;\n\n- Quản lý và báo cáo công việc đến cấp trên theo đúng quy trình.', '- Tốt nghiệp Trung cấp trở lên;\n\n- Có kinh nghiệm Chăm sóc khách hàng ít nhất 6 tháng;\n\n- Nhiệt tình, có tinh thần dịch vụ khách hàng, lấy khách hàng là trọng tâm;\n\n- Ưu tiên ứng viên có kinh nghiệm làm ở các Công ty liên quan đến công nghệ, viễn thông,..', 10000000.00, 15000000.00, 'Lâm Đồng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(188, 166, 169, 'Fschcm_Cán Bộ Quản Trị Hệ Thống Mạng (IT Outsource)', 'Nghiên cứu và khảo sát tình trạng hệ thống mạng hiện tại. • Tính toán các đề xuất thay đổi cho phù hợp với yêu cầu/thực tế sử dụng.\nTheo dõi, giám sát vận hành hệ thống mạng tuân thủ theo các quy trình/quy định vận hành. • Xử lý sự cố khi hệ thống có lỗi xảy ra thuộc phạm vi được phân công\nĐề xuất và sắp lịch sửa chữa, nâng cấp, bảo trì hệ thống mạng.Kết hợp với hãng/NCU xử lý sự cố nếu có liên quan đến hãng/NCU\nCài đặt các ứng dụng mà user sử dụng\nXử lý khi thiết bị của User có lỗi xảy ra\nKết hợp với hãng/NCU xử lý sự cố nếu có liên quan đến hãng/NCU \nNhận thông tin yêu cầu hỗ trợ/xử lý sự cố từ Khách hàng\nĐiều phối, chuyển thông tin xử lý sự cố cho các bên liên quan xử lý sự cố\nNhập hệ thống, theo dõi TAT, xử lý các cases phát sinh', 'Phẩm chất cá nhân: Personal Qualities:\nCẩn thận, tỉ mỉ\nCó tinh thần trách nhiệm Học vấn: Education:\nTốt nghiệp Cao Đẳng trở lên Kinh nghiệm liên quan tới vị trí: Job Related Experience:\nÍt nhất 01 năm kinh nghiệm trong lĩnh vực tương đương Kiến thức liên quan: Business Understanding:\nCó kiến thức chung về CNTT', 13000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(189, 167, 170, '[HCM] Nhân Viên Hành Chính Tổng Hợp', '1. Hành chính văn phòng:\nTiếp nhận và lưu trữ các hồ sơ liên quan đến hợp đồng, các công văn, thông báo, quyết định trong Công ty.  \nSoạn thảo các văn bản, tài liệu, công văn liên quan đến Hợp đồng, báo giá. \nTheo dõi và quản lý cơ sở hạ tầng và môi trường làm việc (chi phí văn phòng: thuê văn phòng, điện, nước, gửi xe,...; dịch vụ, vệ sinh văn phòng; quản lý phòng họp) \nTheo dõi, quản lý và mua sắm, sửa chữa, bảo dưỡng các tài sản, trang thiết bị, vật tư văn phòng (máy móc, thiết bị, đồ dùng, văn phòng phẩm) \nTheo dõi và quản lý các chi phí liên quan đến dự án, công tác, hội thảo, hội nghị, sự kiện nội bộ.  \nHỗ trợ các thủ tục pháp lý, chuẩn bị cho các kế hoạch công tác của BGĐ và các phòng ban: vé tàu xe, vé máy bay, khách sạn, nhà hàng.  \nHỗ trợ lập kế hoạch và tổ chức các sự kiện nội bộ, Teambuilding của phòng ban & Công ty;\n2. Quản lý nhân sự:\nTham gia xây dựng và hoàn thiện các quy trình, quy chế, nội quy trong Công ty. \nLập hồ sơ nhân sự: lưu trữ hồ sơ cá nhân, trình độ học vấn, kinh nghiệm làm việc của nhân viên. \nQuản lý lương thưởng: Tính toán lương thưởng theo quy định của công ty, đảm bảo tính minh bạch công bằng. \nCung cấp các chế độ phúc lợi như BHXH, BHYT, nghỉ phép cho nhân viên. \nĐánh giá hiệu suất công việc: Đánh giá định kỳ hiệu quả công việc, đề xuất khen thưởng hoặc kỷ luật. \nQuản lý kỷ luật nhân viên: Xử lý các vi phạm nội quy theo quy định của công ty.\n3. Quan hệ lao động:\nGiải quyết tranh chấp lao động: Giải quyết mâu thuẫn giữa người lao động và người sử dụng lao động theo quy định của pháp luật \nTư vấn cho nhân viên về các vấn đề liên quan đến lao động\n4. Định kỳ báo cáo: Báo cáo hàng tuần và đột xuất theo yêu cầu của cấp trên (các thông tin liên quan đến tuyển dụng, quản lý nhân sự, hồ sơ và các chi phí văn phòng)\n5. Các công việc khác theo yêu cầu của cấp trên.', '1. Trình độ học vấn\nTốt nghiệp Đại học chuyên ngành Quản trị nhân sự, Quản trị kinh doanh, Ngoại thương.\n2. Ngoại ngữ\nTiếng Anh có khả năng giao tiếp và đọc hiểu\n3. Kiến thức chuyên môn\nKiến thức chuyên môn về công việc hành chính, quản trị\nThành thạo các phần mềm văn phòng như Word, Excel, PowerPoint, Outlook\n4. Kỹ năng chuyên môn\nKỹ năng làm việc độc lập và làm việc nhóm.  \nKỹ năng giao tiếp trực tiếp hoặc qua điện thoại tốt.  \nKỹ tổ chức, sắp xếp công việc và quản lý thời gian  \nKỹ năng lắng nghe, giải quyết vấn đề  \n5. Kinh nghiệm\nCó ít nhất 1 năm kinh nghiệm ở vị trí Hành chính văn phòng hoặc vị trí tương đương', 7000000.00, 11000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(190, 168, 171, 'Lập Trình Web & App', 'Xây dựng website thương mại điện tử và Mobile app phục vụ cho hoạt động của công ty.\nTích hợp các hệ thống thanh toán như ngân hàng, ví thanh toán và hệ thống POS\nSẵn sàng hỗ trợ ngoài giờ kể cả các ngày nghỉ lễ, cuối tuần nếu có sự cố hoặc yêu cầu từ cấp trên\nSẵn sàng hỗ trợ các bộ phận khác hoặc phòng ban IT các công việc khác khi cần', 'Đọc hiểu tiếng anh - trung cấp\nSử dụng lập trình tốt các ngôn ngữ Flutter, React Native, node.js, React/Next.js, Javescript, ….\nLập trình viên fullstack, có kinh nghiệm từ 5 năm làm việc fullstack trong lịch vực Website và Mobile app.\nƯu tiên ứng viên có kinh nghiệm làm việc Vendure\nLàm việc độc lập', 40000000.00, 45000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(191, 169, 172, 'Nhân Viên Thiết Kế Giao Diện Người Dùng', '• Thực hiện nghiên cứu, đánh giá nhằm cải tiến chất lượng sản phẩm và đáp ứng nhu cầu người dùng;\n• Chuyển ý tưởng thiết kế thành bản phác thảo, Wireframe, Prototype bằng các phần mềm chuyên dụng (Figma, Figjam, Adobe XD);\n• Xây dựng, sáng tạo thiết kế mới và điều chỉnh các sản phẩm đã có;\n• Xây dựng, quản lý và sử dụng Design System;\n• Làm việc nhóm, phối hợp với các thành viên khác trong nhóm để nghiên cứu, testing, tạo ra sản phẩm thiết kế theo yêu cầu được giao;\n• Đưa ra ý kiến phản hồi, đóng góp hữu dụng cho sản phẩm, quy trình làm việc chung của nhóm;\n• Mô tả, viết tài liệu hand-off và làm việc trực tiếp với đội ngũ kỹ thuật (DEV);\n• Hỗ trợ testing, kiểm thử, đảm bảo chất lượng đầu ra về mặt UIUX;\n• Đảm nghiệm các công việc khác theo sự phân công của cấp trên.\n• Thiết kế ấn phẩm Online (banner, hình ảnh cho các bài viết trên MXH, website…), các ấn phẩm Offline(Catalog, Backdrop, Brochure…).\n• Tìm kiếm và nghiên cứu phong cách thiết kế hình ảnh phù hợp với các sản phẩm của công ty.', '• Có năng khiếu về thẩm mỹ, nhận diện và biết sắp xếp bố cục hợp lý;\n• Thành thạo công cụ:\n• Thiết kế UI/UX: Figma, Adobe XD.\n• Thiết kế đồ hoạ: Adobe Photoshop, Adobe Illustrator, Adobe Premiere, Adobe After Effects.\n• Có kinh nghiệm làm việc ở tất cả các giai đoạn của quy trình thiết kế sản phẩm, bao gồm: Nghiên cứu người dùng, Lên ý tưởng, Wireframe, Prototype, Copywriting, Hand-off, Testing.', 4000000.00, 5000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(192, 170, 173, 'Nhân Viên Công Nghệ Thông Tin', 'Xây dựng và phát triển chiến lược công nghệ thông tin phù hợp cho doanh nghiệp\nQuản lý hệ thống server chủ, mạng Quản trị hệ thống, bảo mật dữ liệu, PCS và chịu trách nhiệm khắc phục, giải quyết nhanh khi phát sinh sự cố.\nQuản lý, phát triển các hệ thống CNTT về quản trị doanh nghiệp\nQuản lý hệ thống dữ liệu thông tin như email công ty, số điện thoại nhân viên, thông tin khách hàng,...\nXây dựng, quản lý hệ thống cơ sở vật chất như mạng CNTT cho công ty và các đơn vị thành viên.\nĐề xuất, tham gia các dự án phát triển các phần mềm, CNTT cho các đơn vị, bộ phận.\nNghiên cứu, tìm hiểu và thay thế các công cụ, ứng dụng công nghệ mới để tăng năng suất lao động.\nQuản lý, bảo quản các thiết bị, quản trị rủi ro.\nCài đặt các hệ thống phần mềm (hệ điều hành, phần mềm ứng dụng...)\nQuản trị và phát triển website', 'Tối thiểu 01 năm kinh nghiệm ở vị trí tương đương\nTốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành liên quan\nTrình độ Tiếng Anh: Tối thiểu B1', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(193, 171, 174, 'Lập Trình Viên PHP / Laravel', '- Làm việc về website PHP / Laravel\n- Tham gia nghiên cứu, xây dựng phát triển website, phần mềm của công ty\n- Xây dựng, chỉnh sửa các website trên nền tảng Laravel / PHP...\n- Xử lý lỗi và tối ưu hóa vận hành cho các tính năng hiện có.\n- Công việc cụ thể trao đổi khi phỏng vấn', '- Thành thạo PHP, MySQL, Laravel\n- Thành tạo HTML / CSS, Javascript\n- Biết Wordpress là một lợi thế\n- Biết Photoshop\n- Thái độ làm việc chuyên nghiệp và có trách nhiệm.\n- Tiếng anh giao tiếp tốt', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(194, 172, 175, 'Nhân Viên Thiết Kế Đồ Họa Website (Ui / Ux)', 'Lên ý tưởng, sáng tạo và trực tiếp thiết kế giao diện UI/UX cho Website, Mobile App.\nPhối hợp chặt chẽ với các bộ phận liên quan như Product, Maketing, Developer trong suốt quá trình làm sản phẩm.\nThiết kế: Logo, Screenshot, Banner.', 'Có ít nhất 01 năm kinh nghiệm trong việc thiết kế Website.\nSử dụng thành thạo một trong các công cụ thiết kế như Figma, Photoshop, Sketch.\nCó sản phẩm demo là một lợi thế.\nƯu tiên những bạn đã có kinh nghiệm thiết kế và nắm vững các kiến thức về UI/UX Design pattern, Design System, Responsive Web Design, CSS, HTML.\nKhả năng giao tiếp và làm việc nhóm tốt.\nỨng viên gửi CV có kèm link porfolio (sản phẩm).', 8000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(195, 173, 176, 'Nhân Viên Admin (Làm Việc Từ Thứ 2 Tới Thứ 6 Hàng Tuần)', '- Gọi Khách hàng cần tư vấn để lại thông tin trên hệ thống\n- Hỗ trợ Sale Demo hệ thống hoặc Meeting khách hàng\n- Quản lý hệ thống nội bộ của công ty\n- Test tính năng nâng cấp hệ thống\n- Đăng thông tin sản phẩm và các bài viết về sự kiện của dự án khi có phát sinh lên hệ thống\n- Trực hotline hệ thống\n- Xây dựng tài liệu hệ thống', '- Đang chờ bằng hoặc đã tốt nghiệp đại học/ cao đẳng.\n- Kinh nghiệm: không yêu cầu (Có kinh nghiệm telesales hoặc chăm sóc khách hàng là một lợi thế)\n- Kỹ năng giao tiếp và thuyết phục tốt.\n- Kiên nhẫn, chịu được áp lực công việc.', 7000000.00, 10000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(196, 142, 145, 'Nhân Viên IT - Cần Giuộc', '- Cài đặt hệ điều hành, hỗ trợ người dùng về các vấn đề kỹ thuật.\n- Quản trị hệ thống mạng máy tính nội bộ của công ty.\n- Quản trị hệ thống phần mềm chấm công, camera của công ty.\n- Cài đặt, quản trị phần mềm kế toán, hệ thống email và website của công ty.\n- Hướng dẫn, giúp đỡ người dùng máy tính tại các hệ thống của công ty qua teamviewer hoặc đến trực tiếp.\n- Kiểm tra, chẩn đoán và khắc phục sự cố (sửa chữa hoặc thay thế linh kiện, gỡ lỗi...).\n- Ghi chép nhật ký sữa chữa và bảo dưỡng thiết bị theo quy định.\n- Theo dõi số lượng máy tính và thiết bị mạng và đặt hàng khi thiếu.\n- Có ký năng quản lý, giám sát nhân viên qua điện thoại, camera, teamview…\n- Thực hiện các công việc khác theo yêu cầu của quản lý.', '- Học vấn: Tốt nghiệp Cao Đẳng, Đại Học chuyên ngành Công nghệ thông tin, Kỹ thuật máy tính,...\n- Kinh nghiệm:\nCao Đẳng: kinh nghiệm làm việc từ 4-6 năm.\nĐại Học trở lên: kinh nghiệm làm việc từ 1-3 năm\n- Những kỹ năng, năng lực và ngoại ngữ yêu cầu:\nCó kinh nghiệm tại vị trí IT hoặc vị trí liên quan.\nCó khả năng nắm bắt nguyên lý và vận hành thiết bị.\nNắm vững và áp dụng tiêu chuẩn an toàn của thiết bị.\nCó thể thiết kế và thi công những mạch điện điểu khiển máy đơn giản không quá phức tạp.\nCó khả năng học hỏi nhanh, thường xuyên cập nhật các kiến thức mới đáp ứng công việc.\nCó khả năng phân tích, tìm kiếm, xử lý thông tin tốt.\nCẩn thận, có trách nhiệm, sáng tạo.\nCó tinh thần teamwork, có trách nhiệm với công việc.\nKhả năng giao tiếp lưu loát, lịch sự, khéo léo, ứng xử linh hoạt và xử lý các tình huống tốt, có khả năng làm việc dưới môi trường chịu áp lực cao.\nCó định hướng xác định gắn bó lâu dài với công ty.', 11000000.00, 13000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(197, 174, 177, 'Nhân Viên Phòng Bảo Hành', 'Nhận và trả hàng bảo hành, gọi điện thoại cho khách hàng khi cần thiết\nLàm việc trực tiếp với khách hàng và đại lý\nKiểm soát kho và hàng hóa bảo hành\nHỗ trợ kĩ thuật test hàng khi cần \nTrao đổi thêm khi phỏng vấn', 'Tốt nghiệp trung cấp, cao đẳng, địa học\nTiếng Anh cơ bản vi tính văn phòng\nSiêng năng, trung thực, năng động\nKhông cần kinh nghiệm, ưu tiên sinh viên mới ra trường\nHiểu biết về phần cứng máy tính là một lợi thế', 75000000.00, 9000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(198, 175, 178, 'Nhân Viên Kinh Doanh Phần Mềm / Sales B2B', 'Tìm kiếm khách hàng qua các hoạt động: tổ chức/tham gia hội thảo, email marketing, khai thác thông tin khách hàng từ nhiều nguồn.\nThuyết trình /Demo online/trực tiếp và tư vấn giải pháp phù hợp cho khách hàng\nBáo giá, đàm phán và thống nhất phương án triển khai với khách hàng\nĐồng hành giúp Khách hàng chuyển đổi số thành công và duy trì mối quan hệ sau bán hàng\n Đối tượng khách hàng: Giám đốc, Trưởng phòng,... tại các doanh nghiệp forwarder\nSản phẩm kinh doanh: phần mềm quản lý cho doanh nghiệp forwarder – ForwardX (chuyên lĩnh vực logistics forwarder)\nPhối hợp bộ phận triển khai, hỗ trợ, giải quyết vấn đề giữa khách và bộ phận triển khai.\nQuảng bá hình ảnh công ty\nCác công việc liên quan truyền thông và kinh doanh theo phân công của công ty.', 'Kinh nghiệm sales B2B trên 1 năm\nChuyên ngành học: công nghệ thông tin, hệ thống thông tin, xuất nhập khẩu, logistics, quản trị kinh doanh, marketing.\nĐam mê kinh doanh: mong muốn đột phá về thu nhập\nKiên trì, bền bỉ: có quyết tâm vượt qua giới hạn của bản thân, chinh phục những thử thách, cơ hội mới với tệp khách hàng doanh nghiệp \nCó hiểu biết về lĩnh vực logistics, kế toán là một lợi thế\nKỹ năng giao tiếp, thuyết trình: rõ ràng, thuyết phục người nghe\nCó kỹ năng giao tiếp tốt, có khả năng tạo mối quan hệ thân thiết với đối tác, khách hàng.\nTư duy logic: phân tích được vấn đề của khách hàng để đề xuất giải pháp tối ưu nhất\nPhản xạ tình huống: linh hoạt, chuyên nghiệp, tạo được thiện cảm với khách hàng', 9000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(199, 176, 179, 'Chuyên Viên Tư Vấn Triển Khai Erp (Đi Làm Ngay)', '- Tham gia vào các dự án triển khai ERP\n- Khảo sát, tiếp nhận và phân tích các yêu cầu từ các phòng ban liên quan (kinh doanh, marketing, kế toán, quản lý dự án, v.v.) để hiểu rõ các quy trình nghiệp vụ hiện tại, xác định các vấn đề tồn đọng và cơ hội cải tiến. Từ đó thiết kế giải pháp tối ưu các vấn đề trong công tác quản trị doanh nghiệp.\n- Ghi nhận và tài liệu hóa các yêu cầu một cách chi tiết, rõ ràng và có cấu trúc, bao gồm cả yêu cầu nghiệp vụ (functional requirements) và yêu cầu phi nghiệp vụ (non-functional requirements).\n- Phân tích tính khả thi và đánh giá tác động của các yêu cầu đối với hệ thống và quy trình hiện có.\n- Phối hợp chặt chẽ với đội ngũ kỹ thuật (Developer/Consultant) để chuyển giao các yêu cầu và thiết kế giải pháp thành các đặc tả kỹ thuật (technical specifications) chi tiết.\n- Xác định các điểm cần phát triển tùy chỉnh (customization) hoặc tích hợp (integration) nếu các chức năng tiêu chuẩn không đáp ứng được yêu cầu.\n- Thực hiện việc triển khai và customize phần mềm (giao diện, báo cáo, workflow, form mẫu…) theo sự chỉ đạo của quản lý.\n- Hoàn thành các công việc được phân công, hướng dẫn.\n- Quản lý các thay đổi (change management) trong quá trình triển khai, đảm bảo mọi sự thay đổi đều được ghi nhận, đánh giá và phê duyệt.\n- Kiểm thử và chịu trách nhiệm về tiến độ, đảm bảo chất lượng công việc được giao.\n- Hỗ trợ kỹ thuật sau khi triển khai.\n- Đào tạo và hướng dẫn cho khách hàng sử dụng phần mềm theo yêu cầu.\n- Cung cấp hỗ trợ sau triển khai để giải đáp thắc mắc, xử lý các vấn đề phát sinh trong quá trình vận hành hệ thống.', '- Tốt nghiệp Đại học chuyên ngành Kế toán kiểm toán, Tài chính ngân hàng, CNTT hoặc Chuyên ngành Hệ thống thông tin quản lý.\n- Nắm vững kiến thức về một mảng chuyên môn quản trị doanh nghiệp (Tài chính, kế toán, mua hàng, bán hàng, quản lý kho, nhân sự tiền lương, sản xuất, quản lý dự án…).\n- Có khả năng trình bày để hướng dẫn đào tạo khách hàng.\n- Có khả năng làm việc độc lập, nhóm, có tính nghiên cứu tìm tòi.\n- Có kỹ năng giải quyết vấn đề và chịu áp lực tốt.\n- Có khả năng giao tiếp và làm dịch vụ khách hàng.\n- Nhiệt tình và có tinh thần trách nhiệm cao.\n- Công việc triển khai dự án yêu cầu linh hoạt về thời gian.\n- Có khả năng đi công tác trong và ngoài nước.\n- Đã tham gia triển khai ERP của phần mềm Oracle, SAP là một lợi thế.', 10000000.00, 40000000.00, 'Hà Nội,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(200, 177, 180, 'Lập Trình Viên Mobile', 'Chịu trách nhiệm phát triển ứng dụng di động, trải nghiệm người dùng\nPhát triển và tối ưu các tính năng mobile trên nền tảng React Native (sử dụng Expo).\nThiết kế giao diện người dùng tương tác tốt, đẹp mắt và dễ sử dụng.\nTối ưu hiệu suất ứng dụng, đảm bảo khả năng mở rộng và bảo trì dễ dàng.\nTích hợp API (Rest), quản lý dữ liệu bất đồng bộ và trạng thái ứng dụng hiệu quả.\nTriển khai các tính năng như xác thực, thông báo đẩy, Camera, xử lý File, Media, biểu đồ, hiển thị Animation, Zustand, Redux…\nHỗ trợ xử lý Realtime và kết nối Socket nếu cần thiết.\nTham gia phân tích yêu cầu, Review Code và cải tiến quy trình phát triển.', 'Tốt nghiệp Đại học chuyên ngành phát triển phần mềm hoặc các ngành liên quan\nTừ 3 kinh nghiệm trong lĩnh vực thiết kế hoặc ở các vị trí tương đương\nCó kinh nghiệm triển khai OTA Update, Dev Client hoặc quản lý nhiều môi trường Build.\nCó kiến thức về bảo mật, performance, CI/CD trên Mobile.\nBiết sử dụng AI để tối ưu công việc\nCó kinh nghiệm về lạp trình web bằng React, Next js\nHiểu rõ về kiến trúc ứng dụng mobile và các mô hình quản lý trạng thái hiện đại.\nKinh nghiệm làm việc với hệ thống điều hướng, xử lý Gesture, Animation nâng cao.\nNắm vững cách xử lý Form, Validate dữ liệu, quản lý lỗi.\nBiết cách tối ưu hiệu suất render, quản lý bộ nhớ và xử lý danh sách lớn hiệu quả.', 16000000.00, 19000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(201, 178, 181, 'Nhân Viên Tester', '- Thực hiện kiểm thử phần mềm theo yêu cầu của dự án Game/ Web/ App\n- Viết Test Case, Test Plan dựa trên tài liệu yêu cầu hoặc hướng dẫn của team BA/ PM.\n- Thực hiện Test Manual, báo cáo Bug và theo dõi quá trình Fix Bug.\n- Phối hợp với đội phát triển để đảm bảo chất lượng sản phẩm.\n- Thực hiện kiểm thử hồi quy khi có phiên bản cập nhật.\n- Viết tài liệu hướng dẫn sử dụng phần mềm khi cần.\n- Trao đổi với đối tác Telco trong và ngoài Nước.', '-Tối thiểu 2 năm Kinh nghiệm ở vị trí Tester\n- Tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan.\n- Có kiến thức kinh nghiệm về kiểm thử phần mềm, quy trình phát triển phần mềm (SDLC, STLC).\n- Biết cách viết Test Case, Test Scenario và báo cáo Bug.\n- Kỹ năng giao tiếp, làm việc nhóm tốt.\n- Có trách nhiệm, tỉ mỉ, cẩn thận trong công việc.\n- Ứng viên có thể làm việc full-time, sẵn sàng hỗ trợ đối tác Nước Ngoài.', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(202, 179, 2, 'iOS Developer (Swift)', 'Top 3 reasons to join us\n- Lương và chế độ hấp dẫn, linh hoạt, cạnh tranh\n- Cơ hội thăng tiến, phát triển trong công việc\n- Môi trường thân thiện, trẻ trung, sáng tạo\n\nJob description\n- Xây dựng các ứng dụng Mobile Banking liên quan đến các mảng tài chính, Ngân hàng, Viễn thông trên nền tảng IOS\n- Xây dựng các ứng dụng liên quan đến các phần tiện ích Ecommerce\n- Nghiên cứu, tìm kiếm giải pháp về việc áp dụng các tính năng của thiết bị di động vào mảng tài chính, Ngân hàng, Viễn thông.\n- Duy trì, hỗ trợ, nâng cấp các ứng dụng dịch vụ đã phát triển của Công ty\n- Phát triển mới, nâng cấp ứng dụng cho các ngân hàng trong giai đoạn sắp tới.\n\nYour skills and experience\n- Tốt nghiệp Đại học/ Cao đẳng các chuyên ngành Công nghệ thông tin, Công nghệ phần mềm,..... hoặc Trường đào tạo lập trình viên Quốc Tế (NIIT, Aptech) trở lên\n- Có từ 6 tháng kinh nghiệm trở lên\n- Hiểu biết về xCode, Swift, có kinh nghiệm lập trình ứng dụng trên IOS\n- Có hiểu biết về Realm, giao tiếp client – server thông qua REST và JSON\n- Có kiến thức về Objective – C là 1 lợi thế, chịu khó học hỏi, tìm hiểu kiến thức mới\n- Ưu tiên ứng viên có kinh nghiệm làm về lĩnh vực tài chính, ngân hàng\n\nWhy you\'ll love working here\n1. Chế độ lương & thưởng hấp dẫn:\n- Mức lương thỏa thuận theo năng lực, đánh giá năng lực hàng năm\n- Chế độ thưởng phong phú và hấp dẫn (Theo quy định và chính sách công ty)\n- Hỗ trợ ăn sáng miễn phí\n- Hỗ trợ ăn trưa: 50.000đ/ngày\n- Hỗ trợ gửi xe, xăng xe, điện thoại (tùy vị trí)\n- Hỗ trợ trang điểm cho CBNV nữ\n- Quà tặng các ngày lễ trong năm\n2. Bảo hiểm & chăm sóc sức khỏe toàn diện:\n- BHXH, BHYT, BHTN theo pháp luật hiện hành\n- Gói bảo hiểm sức khỏe cao cấp 24/7 mua cho nhân viên & người thân nhân viên\n- Khám sức khỏe định kỳ hàng năm\n3. Môi trường làm việc hiện đại:\n- Cung cấp máy tính & thiết bị làm việc hiện đại\n- Văn phòng làm việc hiện đại, thiết bị làm việc Hi- tech\n- Không gian ăn nhẹ miễn phí (nước uống, trà cafe, hoa quả, sữa chua)\n4. Phát triển nghề nghiệp:\n- Cơ hội tiếp cận với những công nghệ mới, những dự án quy mô lớn\n- Làm việc cùng đội ngũ hơn 2000 nhân sự tài năng, có chuyên môn giỏi, dày dặn kinh nghiệm, tư duy chia sẻ\n- Được tài trợ kinh phí tham gia các chương trình đào tạo nâng cao năng lực\n- Công ty thành lập gần 20 năm với các sản phẩm & dịch vụ đã được khẳng định vị thế trên thị trường\n5. Hoạt động ngoại khóa phong phú:\n- Văn hóa công ty đặc sắc với nhiều hoạt động đoàn thể được quan tâm đầu tư: Team building, Nghỉ mát (trong nước và nước ngoài), 20/10, Year End Party, hoạt động thiện nguyện,…\n- Các câu lạc bộ: CLB Cầu lông, CLB Bóng đá, CLB Yoga, CLB Điền kinh, CLB Bơi\n\nChúng tôi sẽ liên hệ qua điện thoại với những CV phù hợp trong vòng 7 ngày làm việc kể từ ngày ứng tuyển.\nLưu ý: Công ty đang tuyển tại 2 văn phòng Hà Nội và Tp. Hồ Chí Minh, ứng viên vui lòng ghi rõ địa chỉ trên CV.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '22  Láng Hạ, Dong Da, Ha Noi; Tầng 12, tòa nhà Minh Long, số 17 Bà Huyện Thanh Quan, P. Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(203, 180, 2, '5 Fullstack Dev (Java, Spring, Angular)', 'Top 3 reasons to join us\n- 18+ days of annual leave\n- Premium health insurance\n- 13th month salary\n\nJob description\nPrefer immediate employment / ƯU TIÊN ĐI LÀM NGAY\nYour main activities:\n- Develop back-end API using Java, Spring Framework, JHipster\n- Develop user interfaces in JavaScript / HTML5 / CSS3 using state-of-the-art Front-end frameworks like AngularJS or ReactJS\n- Test, commit and integrate your code with our online products\n\nAs an employee in LEAP, you will:\n- Be involved in all the activities of Agile method (all activities from business specification, details design to development, testing and deployment)\n- Have opportunities to contribute your talents to real products, watch it go live and even use it\n- Have chances to work with all parts of our applications, not only front-end but also back-end and even deeper to database\n- Join a family where people are willing to help each other\n- Receive a very attractive remuneration for your dedication\n\nYour skills and experience\nWe expected from you:\n- Experienced with or willing to learn Java development (using Spring Boot)\n- Experienced with or willing to learn Front-end development (AngularJS or ReactJS)\n- Strong interest in software design, programming and testing\n- Prefer immediate employment\n\nNice to have:\n- Experienced with Linux\n- Experienced with DevOps activities is remarkable plus\n- Graduated in Vietnam National University, Ho Chi Minh City is a big plus\n\nWhy you\'ll love working here\nAs an employee in LEAP, you will:\n- Be involved in all the activities of Agile method (all activities from business specification, details design to development, testing and deployment)\n- Have opportunities to contribute your talents to real products, watch it go live and even use it\n- Have chances to work with all parts of our applications, not only front-end but also back-end and even deeper to database\n- Join a family where people are willing to help each other\n- Receive a very attractive remuneration for your dedication\n- 18+ days of annual leave\n- 13th month salary\n- Premium health insurance\n- Support work from home in urgent cases\n- Chance to travel to European countries (France, Switzerland ...)\n- Yearly company trip (internal or external Vietnam)\n- Receive a very attractive remuneration for your dedication\n- Dynamic working environment\n- Flexible working hours\n- Being willing to improve skills and to learn new technologies continuously\n- Equip new and state-of-the-art PCs with 32 GB Ram, 500 GB SSD plus dual 24” screens\n- Free snacks in the office\n- English training in each afternoon.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '199 Dien Bien Phu, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(204, 181, 2, 'Mid/Senior Frontend Developer (Next.js, Tailwind, CSS)', 'LocalLife.Asia là nền tảng kết nối du khách với trải nghiệm cộng đồng thực thụ tại các vùng nông thôn, miền núi, dân tộc thiểu số khắp châu Á. Đây không chỉ là du lịch, mà là hành trình sống cùng, học cùng, làm cùng người dân địa phương.\n\nChúng tôi không dẫn bạn đi du lịch, chúng tôi dẫn bạn vào lòng người dân.\n\nLà Mid/Senior Frontend Developer, bạn sẽ :\n\n📌 Nhiệm vụ:\n- Xây dựng giao diện người dùng cho các trang: tìm kiếm, chi tiết địa điểm, form đặt chỗ, quản lý tài khoản.\n- Tối ưu hóa SEO (bằng SSR, ISR) và tốc độ tải trang.\n- Kết nối API từ backend để hiển thị dữ liệu động.\n- Phối hợp chặt chẽ với UI/UX Designer và AI Engineer để xử lý dữ liệu context gợi ý.\n\nYour skills and experience:\n- Thành thạo Next.js (App Router), Tailwind CSS, TypeScript.\n- Kinh nghiệm tối ưu hóa SEO và hiệu suất trang web.\n- Ưu tiên ứng viên đã từng làm việc trong lĩnh vực du lịch, thương mại điện tử hoặc SaaS frontend.\n\nWhy you\'ll love working here:\n- Mức lương hấp dẫn\n- Lương tháng thứ 13\n- Khám sức khoẻ hàng năm\n- Thi thoảng - Code mọi nơi, test luôn sản phẩm du lịch cộng đồng\n- Chuyển sang chế độ làm việc Hybrid nếu đáp ứng thời gian làm việc đủ lâu.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '63 Nguyễn Hiến Lê, phường Hoà Xuân, Cam Le, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(205, 182, 2, 'Atlassian ITSM Development Engineer (ITSM, Python)', 'TymeX is an innovative digital banking development company that drives business growth by leveraging advanced technology solutions to multi banks internationally. We are dedicated to offering exceptional customer service and seamless product delivery through state-of-the-art tools and infrastructure. We are seeking an experienced ITSM Development Engineer to join our dynamic team, ensuring that ITSM developments are processed simply and efficiently through automations and integrations of modern techniques in alignment with business growth framework.\n\nRole Overview:\nThe Atlassian ITSM Development Engineer will be responsible for designing, implementing, and optimizing IT Service Management solutions within the Atlassian ecosystem. You will collaborate with ITSM, DevOps, and Development teams to streamline processes, enhance user experiences, and support continuous improvement initiatives across the organization.\n\nKey Responsibilities:\n- Design and develop Atlassian ITSM solutions, including JIRA Service Management, Confluence, Opsgenie, and related tools.\n- Customize workflows, automation, and configurations within the Atlassian suite to meet organizational requirements.\n- Collaborate with cross-functional teams to understand business needs and implement solutions that support ITSM best practices.\n- Monitor and maintain the stability, performance, and scalability of Atlassian systems.\n- Develop custom scripts and integrations to enhance functionality and improve productivity.\n- Perform regular system maintenance, upgrades, and troubleshooting as needed.\n- Support users with training, documentation, and issue resolution.\n\nYour skills and experience\nRequired Qualifications:\n- Bachelor’s degree in computer science, Information Technology, or related field, or equivalent experience.\n- Proven hands-on experience in architecting, configuring, and managing JIRA Service Management, Confluence, and Opsgenie in complex enterprise environments.\n- Solid understanding of ITSM concepts such as Incident, Problem, Change, and Configuration Management.\n- Proficiency in scripting languages (e.g., Python, Groovy) for automation and customization within the Atlassian suite.\n- Familiarity with REST APIs and integrations with other ITSM/ITOM tools.\n- Excellent problem-solving skills and a proactive approach to identifying improvements.\n\nPreferred Qualifications:\n- Atlassian certifications (e.g., Atlassian Certified Jira Project Administrator).\n- Experience with CI/CD and DevOps tools and practices.\n- Knowledge of ITIL framework and relevant certifications.\n\nWhy you\'ll love working here\nWhat We Offer:\n- Competitive salary and benefits package.\n- Opportunity to work in a fast-paced, innovative fintech company.\n- A collaborative and inclusive work environment.\n- Growth opportunities within the company.\n- Exposure to cutting-edge technologies and processes.\n\nThis role is an excellent opportunity for someone with expertise in the Atlassian ecosystem and ITSM to contribute to our team’s success and make a meaningful impact. We look forward to reviewing your application.\n- Meal and parking allowance are covered by the company\n- Full benefits and salary rank during probation\n- Insurances as Vietnamese labor law and premium health care for you and your family without seniority compulsory\n- Performance bonus up to 2 months\n- 13th month salary pro-rata\n- 15-day annual leave+ 3-day sick leave + 1 birthday leave + 1 Christmas leave\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) – we focus on your development\n- Values-driven, international working environment, and agile culture\n- Overseas travel opportunities for training and working related\n- Internal Hackathons and company’s events (team building, coffee run, blue card…)\n- Work-life balance 40-hr per week from Mon to Fri', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower, Lumiere Riverside, 277 Vo Nguyen Giap, An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(206, 183, 2, 'Junior QC Engineer (Tester/QA QC)', 'We are building an environment where personal development is a focus. We want all members to grow with the company through hands-on projects and industry best practices. Our clients have extremely high expectations and that sets a bar for our quality of work.\n\nWe’re looking for a QC Engineer (Tester) for our organization. For this role, we need people who are eager to take ownership and love learning new things.\n\nWe are growing at a brisk pace and we want you to be part of our success.\n\nWhat you\'ll be doing:\n- Evaluate and clarify product requirements. Participate in reviewing product design and work with the development team to incorporate test ability requirements.\n- Design test plans, test cases, and test procedures to ensure accuracy, stability, and security of the product.\n- Work with developers to analyze and find the root cause of bugs.\n- Web and mobile application validation.\n- Quality-driven and proactive to do what is necessary to achieve deadlines in a dynamic environment with frequent priority and changes.\n- Support on building and maintaining frameworks to help performance tests, automate tests and expand test coverage in an Agile development environment (plus).\n\nYour skills and experience:\nWhat You Are Good at\n- Strong in functional/non-functional testing:\n  - Test technique: Equivalence partitioning, Boundary value, Decision table, generate test cases from use cases.\n  - Have adhoc-testing skills\n  - Experience in Performance and Security testing is a plus\n- Experience in web, mobile testing and api testing.\n- Experience in technical problem solving; root cause analysis; and data gathering, analysis, and reporting within a system/software quality assurance discipline.\n- Process strong analytical skills, with excellent problem-solving abilities\n- Learn new techniques and technologies quickly.\n\nHaving any of the below experience/knowledge is a plus:\n- Familiarity with automated testing tools and frameworks for client-server applications.\n- Experience in writing code to test UIs, APIs, and frontend systems.\n- Experience in API testing, performance testing, security testing, usability testing.\n\nWhy you\'ll love working here:\n- Above industry standard salaries.\n- Friendly working environment and flexible working hours.\n- 13th salary, insurance and team building activities.\n- We work hand-in-hand with our clients to fully invest in their product development and build solutions together for their target market.\n- We fully invest in our team, we will help you build yourself up in any area you feel you need development, be it in English, learning a new design tool, developing your design thinking and more. We want to make sure that you’re always learning and developing yourself whilst a part of our team.\n- We respect both Product and Technology equally, ensuring all of the Products we work on have features with true market potential and ensuring all of the team contribute to, understand and believe in what they are developing.\n- We respect you and your personal hours, we keep sustainable pace by working standard 8 hour days from Monday to Friday, ensuring we only plan for what we can achieve.\n- We are fully agile, working with set sprint goals and working at our rate of velocity.\n- You will have ownership over your role, giving you the opportunity to experiment and try new processes to better improve your day-to-day responsibilities. We are always open to improving our processes.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '56A Le Khoi, Phu Thanh, Tan Phu, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(207, 184, 2, 'Senior Officer, User Experience Research', 'Top 3 reasons to join us\n- Top-tier banking environment in Vietnam\n- Challenging opportunities for the “Greater” You\n- Attractive career path and benefits\n\nJob description\n- The senior UX Researcher’s role is to provide answers to the most challenging questions in the product’s design, and to reveal the underlying needs of customers. \n- The senior UX Researcher reveals what the consumers need by conducting primary research, observing consumer behaviour and motivation, and working with Product Designers, Product Management, and Product Developers to developing new products and services.\nKey Accountabilities (1)\nResearch:\n- Conduct various studies with the assistance of the UX Researcher, by applying methods such as usability testing, field research, surveys, diary studies, and any other methods that she deems impactful in the formulation of product approaches that improve consumer experience.\n- Analyse qualitative and quantitative data in order to generate strategic and tactical insights along with actionable recommendations that drive product design improvements and innovation that will in turn improve the consumer experience.\n- Lead the product design and product development departments in a hands-on manner through both small scale and large scale user experience research. The UX Researcher assists these departments in the analysis and interpretation of cognitive, behavioural, and physiological data.\nKey Accountabilities (2)\nCollaboration:\n- Facilitates the collection of experience metrics in the course of collaboration with different product departments; collaborate with Product and Experience Design as well as the Development (engineering), Marketing, Sales, and Product Management.\n- Contributes to design expertise by actively participating in various product discussion sessions with the product designers, developers, managers and other collaborative personnel.\n- In interaction with consumers, using approaches method such as interviews, diary studies, surveys, competitive analysis, and A/B testing, among many others.\nKey Relationships - Direct Manager Director, Customer Experience Design\nKey Relationships - Direct Reports\nKey Relationships - Internal Stakeholders\nTeams within the Digital Office and relevant departments in the Bank.\nKey Relationships - External Stakeholders Customers, Partners providing professional services\n\nYour skills and experience\n- 5+ years of relevant experience in a research role\n- Deep experience in working with clients researching customer needs and behaviours\n- Deep experience in product management or customer segment management\n\nAgile / Digital Experience\n- Strong understanding of Agile principles, practices and Scrum methodologies.\n- Experience working in Agile teams to support digital transformation projects.\n- Experience in process improvement and LEAN thinking methodologies\nQualifications\n- Bachelor degree in Social Science, Cognitive Science, Statistics, Psychology, or any other related field. A working experience of the equivalent is also acceptable for the position.\n\nWhy you\'ll love working here\nWHY BECOME IT/DATA EXPERTS AT TECHCOMBANK?\n- Investing over 500 million USD to develop large-scale IT projects, Techcombank is one of the leading bank in Technology trends in Vietnam\n- You will grow with Techcombank by having the opportunity to learn from top experts from across the world\n- Techcombank provides a rewarding remuneration structure that commensurate with your achievement and contribution\n- Techcombank is the Top 2 Best place to work in the banking industry where you can experience various exciting activities throughout the year: Company anniversary, Team building, Active Saturday, Year End Party, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 6 Quang Trung, phường Trần Hưng Đạo, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(208, 185, 2, 'Senior/Lead Software Engineer(.NET WPF) with English', 'Top 3 reasons to join us\n• Hybrid working model and good work-life balance\n• 15+ days of paid leave per year\n• Premium health insurance for employee\n\nJob description\n• As a Software Developer, you will play a key role in designing, building, and maintaining software solutions using the Microsoft Stack of Technologies. Your daily tasks will involve end-to-end software development, where you will use your proficiency in C#, .NET, WPF/XAML, Web APIs, LINQ, and Entity Framework. You will also utilise your skills to write and optimise SQL queries, ensuring performance and scalability.\n• You will be part of a team that builds service-oriented or microservices-based applications, following industry best practices for object-oriented programming and design. Your work will require you to ensure high quality code, write unit-tested code, and apply effective debugging skills to resolve any issues across different environments.\n• In this role, you will have the opportunity to contribute to a team that values collaboration and continuous improvement. While working in an Agile environment, you will participate in Scrum or Kanban methodologies to deliver solutions efficiently. You may also be involved in test-driven or acceptance test-driven development to ensure that the software meets business requirements. Your work could extend to creating applications on Microsoft Azure and using tools such as FitNesse or Postman.\n\nYour skills and experience\n• To be successful in this role, you should have a degree in Computer Science, such as B.E./B.Tech. or MCA, or equivalent experience.\n• Proficiency in English is a must.\n• You need to bring 3-5 years of professional experience for Engineer position and minimum 6 years of experience for Senior Engineer position in software development and a strong understanding of object-oriented programming principles, UML, and software development practices. Your ability to ensure performance management and troubleshoot C# or SQL-related performance issues is essential.\n• It would be beneficial if you have experience in WPF development, working in Agile team environments, and using methodologies such as Scrum or Kanban.\n• Familiarity with test-driven development and cloud platforms like Microsoft Azure would also be advantageous.\n• In addition to your technical expertise, you should have excellent analytical and problem-solving skills and strong communication abilities, both written and verbal. Being self-motivated, detail-oriented, and able to work effectively both independently and as part of a team will be key to your success in this position.\n\nWhy you\'ll love working here\n• Join a dynamic and fast-growing global network, tackle great challenges with large-scale products, and work with modern technologies\n• We support your development and are committed to advancing your career\n• Hybrid and flexible working environment with attractive benefits\n• We embrace diversity! As an Equal Opportunity Employer, we value strength in diversity and prohibit discrimination in any form\n• English-speaking environment where you will have opportunities to work on global projects and connect with experienced colleagues from around the world\n• Hybrid working model and good work-life balance\n• 13th-month salary bonus and annual performance bonus\n• 100% offered salary and mandatory social insurances in 2-month probation\n• 15+ days of paid leave per year\n• Premium health insurance\n• Annual company trip and various team building activities and appreciation gifts', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(209, 186, 2, 'Backend Server Developer (.NET, C#, SQL)', 'Mô tả công việc\n- Tham gia vào việc xây dựng và phát triển ứng dụng Backend dựa trên các yêu cầu của công ty.\n- Tham gia vào việc thiết kế hệ thống và triển khai Phát triển hệ thống máy chủ game.\n- Kết nối với cơ sở dữ liệu SQL (Thiết kế và tối ưu CSDL quan hệ (Microsoft SQL Server, MySQL, PostgreSQL..., Viết store procedure, query phức tạp cho các chức năng như: lọc lịch sử trận đấu, thống kê người chơi, chống gian lận,..., Quản lý đồng bộ hóa dữ liệu giữa client – server).\n- Tối ưu hiệu năng các ứng dụng trong hệ thống.\n- Phát triển và triển khai API cho các sản phẩm Core.\n- Phối hợp với đội ngũ phát triển Frontend và quản trị dự án để đảm bảo sự liên kết và hiệu suất công việc cao nhất.\n\nYour skills and experience\n- Thành thạo .NET (C#), SQL.\n- Sử dụng thành thạo công cụ làm việc nhóm Git.\n- Có hiểu biết về CI/CD.\n- Kinh nghiệm từ 5 năm trở lên.\n- Nhận cv song ngữ tiếng anh - tiếng Việt.\n\nWhy you\'ll love working here\n✨ CHẾ ĐỘ PHÚC LỢI HẤP DẪN TẠI CÔNG TY ✨\n- Thu nhập cạnh tranh: Mức lương hấp dẫn, thưởng tháng 13 và thưởng thâm niên.\n- Thưởng theo hiệu quả công việc, xét thưởng vào các dịp Lễ – Tết.\n- Đánh giá tăng lương 1 lần/năm, trường hợp nổi bật sẽ được xét tăng lương ngay tại thời điểm.\n- Chế độ nghỉ phép: 12 ngày nghỉ phép có lương mỗi năm theo quy định – nghỉ thoải mái, vẫn nhận lương đầy đủ.\n- Sự kiện nội bộ ấm áp: Hàng năm tổ chức “Ngày hội gia đình” vào tháng 5, có quà tặng bằng tiền mặt dành tặng ông bà, cha mẹ, vợ/chồng và con cái của nhân viên – thể hiện sự trân trọng với cả gia đình bạn.\n- Chế độ quà tặng nhân dịp đặc biệt: Tặng quà các ngày lễ: Tết Dương lịch, Tết Âm lịch, 30/4, Trung thu, 8/3, 20/10. Cả nhân viên nam và nữ đều có quà.\n- Nhân viên chính thức trên 6 tháng được tặng quà sinh nhật trị giá 5 triệu đồng/người.\n- Thưởng hiệu suất riêng: Ngoài lương chính còn có các khoản thưởng, bonus hàng tháng tùy theo đóng góp.\n- Hỗ trợ nơi ở: Nhân viên ở xa được sắp xếp chỗ ở miễn phí, thuận tiện cho công việc.\n- Cơ hội học hỏi và phát triển: Làm việc cùng các chuyên gia hàng đầu trong nước và quốc tế.\n- Giao lưu, học hỏi với đồng nghiệp quốc tế giúp cải thiện tiếng Anh và mở rộng tư duy toàn cầu.\n- Chăm sóc sức khỏe toàn diện: Khám sức khỏe định kỳ tại các bệnh viện quốc tế như BV Phương Đông.\n- Miễn phí tiêm phòng HPV, cúm cho nhân viên.\n- Trải nghiệm công tác và du lịch: Các chuyến công tác nước ngoài kết hợp du lịch, khám phá đặc sản và địa danh nổi tiếng.\n- Được tài trợ các hoạt động gắn kết team, học hỏi kiến thức lập trình qua các buổi giao lưu, workshop.\n- Văn phòng hiện đại, tiện nghi: Không gian làm việc rộng rãi, thoáng mát. Có bánh, trà, café phục vụ mỗi ngày.\n- Bữa trưa đầy đủ dinh dưỡng, ngon miệng dành riêng cho nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'B4-12 Vinhomes Gardenia Hàm Nghi, Đường Hàm Nghi, Phường Cầu Diễn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(210, 187, 2, 'Data Engineer', 'Top 3 reasons to join us\n- Attractive salary package\n- Onsite opportunity in Europe, Australia, US, Japan\n- Firm’s Certified Qualifications Sponsorship\n\nJob description\n- Design and develop data pipelines to support enterprise data solutions, ensuring seamless integration across systems.\n- Work with a variety of data sources, optimizing ETL/ELT processes for efficient data processing and storage.\n- Architect data solutions that meet the analytics and business intelligence needs of the organization.\n- Implement best practices for data governance, quality, and security, including data privacy and compliance regulations.\n- Collaborate with internal and external teams to understand business requirements and deliver actionable data solutions.\n- Ensure efficient data retrieval, optimizing performance for real-time and batch data processing environments.\n- Partner with business stakeholders, data analysts, and data scientists to provide insights and drive data-driven decisions.\n\nYour skills and experience\n- 4+ years of experience as a Data Engineer, particularly with a focus on building and maintaining data solutions.\n- Expertise in SQL and data modeling (Kimball, Inmon, Data Vault).\n- Hands-on experience with Cloud Data Warehousing solutions (preferably Azure).\n- Proficiency in Python, Scala, or Java for data processing and pipeline development.\n- Experience with data orchestration tools like Apache Airflow or dbt.\n- Strong knowledge of relational and NoSQL databases (e.g., PostgreSQL, MySQL, MongoDB).\n- Familiarity with working on AI-related projects is preferred.\n- Excellent English communication skills, both written and verbal, for effective client collaboration.\n- Experience with Azure Databricks is a plus.\n- Experience working on AI or machine learning projects.\n\nWhy you\'ll love working here\n- Attractive salary package\n- Salary review twice a year\n- Flexible working hour\n- Premium health care\n- Working in One of the largest digital transformation agencies – A professional English environment\n- Free English, Japanese, and professional training packages\n- Firm’s Certified Qualifications Sponsorship for career development\n- Annual company trip inside or outside Vietnam\n- Other fun activities: happy hour, quarterly team building, football club, yoga club, swimming club, charity activities, etc.\n- Free entertainment parties: Birthday party, Anniversary party, Sum-up Party, Year-End.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Handico Tower, Pham Hung, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(211, 188, 2, 'Senior Full-stack Developer (Java, Reactjs)', 'Top 3 reasons to join us\n- Very attractive salary package and Bonus\n- Overseas: Technical trainings and certifications\n- Global career opportunity\n\nJob description\nPerform development activities to build new and maintain existing WEB-based software systems using Java Frameworks, Front-end frameworks and databases.\nResponsibilities\n- Participate in developing web applications, new modules, features from beginning till end in the functional system (It can be Full-Stack from Frontend to Backend services and databases depends on skills and experiences).\n- Participate in analyzing requirements, design architecture, perform coding, unit tests, testing and technical documentation in line with user & system requirements to deliver source code, documents and test scripts that meet client’s needs and meet the release milestone.\n- Perform bugs fixing, maintaining, enhancement existing WEB application modules.\n- Assist Team Leads, Managers in reporting project status and deliverable estimations.\n- Perform code review and supports colleagues.\n- Conduct training & coaching team members in software engineering development if required.\n- Supports team leads on maintaining development environments if required to make sure smooth development.\n- Perform 3rd level support in and after office hours if needed to ensure fastest possible recovery to service.\n\nYour skills and experience\nSkills & Qualifications:\n- Software development skills using Java, ReactJS are required.\n- Good problem-solving skills.\n- Communication skills: Intermediate-level English (especially reading and writing).\n- Ability to work independently, proactive problem solver.\nKnowledge & Experience:\n- Have at least 5-years experience in Full-stack development using Java 17 and Spring Boot/ Spring Framework and web development using ReactJS and related libraries e.g. Redux, Webpack, Babel, Gulp, Sass, Axios\n- Experience with RESTful Web Service with Spring/Spring Boot\n- Experience coding multi-threaded Java applications\n- Experience in MySQL with stored procedures, SQL and index\n- Experience in application performance troubleshooting\n- Understand OOP concepts and design patterns\n- Able to perform code review and give suggestions on solutions and designs\n- Experience in Junit and Jet\n\nPLUS points:\n- Well design and develop web application with a large number of concurrent users and with high performance requirement is a BIG PLUS.\n- Experience with Java 21 is a PLUS\n- Experience/Knowledge on any of Redis, Elasticsearch is a PLUS.\n\nWhy you\'ll love working here\n(*) BONUSES & REWARDS\n- Competitive Salary\n- 13th Month Salary & Performance Bonus\n- Employee of the Year Award\n(*) TRAINING & DEVELOPMENT\n- In-house & Overseas Training\n- Full reimbursement for international Technical Certification\n- Global career opportunity\n(*) ANNUAL PAID LEAVES\n- Vacation Leave: 12 days per year\n- Medical Leave: 8 days per year\n- 1 extra seniority day for every 3 years of service\n(*) HEALTHCARE\n- Annual Routine Check-up\n- Premium Healthcare Insurance\n- Comprehensive Insurance\n(*) WELLNESS AND LEISURE ACTIVITIES\n- Annual Team Building\n- Soccer & Badminton Club and Sports activities\n- Entertainment activities: Music band, Karaoke & Play-station time\n- Celebrations special events: Birthdays, Christmas, New Year/Year-end Party.\n(*) PERKS\n- Fruits Days Twice a Month\n- Unlimited snacks & beverages', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor, Menas Mall Saigon Airport, 60A Truong Son, Ward 2,, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(212, 189, 2, 'iOS Developer', 'Top 3 reasons to join us\n- Attractive Salary & Benefit\n- Yearly Performance Bonus (2 Times/Year)\n- Premium Health Insurance\n\nJob description\nJOB RESPONSIBILITIES:\nIncluding but not limited to jobs as below:\n- Measure and maximize product quality while keeping the milestone timelines intact.\n- Should be able to narrow down the problem based on the analysis of the logs and code.\n- Ability to define a problem with well-defined scope.\n- Requirement gathering and analysis.\n- Work closely with R&D team W/W for timely completion of feature development and ensure smooth delivery to market on time.\n- Handling Market Support queries and drive critical market issues along with technical and support teams.\n- National and abroad traveling involved time to time.\n\nFOR iOS DEVELOPER\n- Development of App on iOS\n- Development and Maintenance of Application for iOS platform\n\nYour skills and experience\nYour Skills and Experience\nKNOWLEDGE, QUALIFICATION AND EXPERIENCE\n(Specific knowledge, skills, qualifications and (or) experience required to competently performing the job).\nGeneral requirement:\n- Bachelor’s degree in Computer Science, S/W Engineering or IT related field.\n- At least 3 years of experience in software development.\n- Good in English communication for working.\n- Mastery in problem analysis, problem resolution.\n- Fast learning skills and mindset required to quickly understand new technologies and new modules in product.\n- Ability to multi-task and manage tasks with varying priorities.\n- Tech-savvy and passionate about building products.\n- Proactive at work.\n\nFOR iOS DEVELOPER\nTechnical requirement:\n(Mandatory)\n- Knowledge in Native Application on iOS, open to work with Kotlin Multiple Platform\n- Familiar with Xcode\n- Understand in Canvas on iOS, ability to make custom UI base on Canvas.\n- Knowledge in App on Samsung Galaxy Framework(One UI) or Material UI\n- Knowledge in Socket connection and BLE.\n- Knowledge & Experience of software design, development, software architect.\n(Optional)\n- Knowledge in Design Patterns.\n- Understand mobile lifecycle.\n- Familiar with Dependency Injection, Image loader libraries.\n- Ability to write unit test case, ui test case.\n- Ability to work with Canvas to create custom Image editor is a big plus.\n- Familiar with Algorithm or have high level on Coding challenge platform like Leetcode, HackerRank is a big plus.\n\nWhy you\'ll love working here\n- Yearly Performance Bonus 2 times/year (up to 3-month salary) + 13th Salary. (At least 15 months).\n- Flexible working week policy.\n- Intensive Training Program.\n- Oversea Biz-trip\n- Linkedin E-Learning & Udemy unlimited access.\n- Premium Health Insurance.\n- 100% salary and mandatory social insurances in 2-month probation.\n- Daily shuttle bus from city center to company\n- Team Building Gifts quarterly.\n- Free luncheon.\n- Birthday Gifts.\n- Training Opportunities in Korea.\n- Take part in various significant activities such as SEHC Festival, SEHC Cup, Town Hall Meeting, Liên Quân Mobile Champion, SEHC Marathon, SEHC Hackathon, SEHC Home Town,....', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lot I-11, D2 Road, Saigon Hi-tech Park, Tang Nhon Phu B Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(213, 190, 2, 'Remote - Games Developer (Unity 3D, Android, iOS)', 'Goodia VN cần tuyển dev có kinh nghiệm làm Hyper Casual game\n\nĐảm bảo sản xuất đủ số lượng 2 games/tháng\n\nSau khi code xong gameplay thì tiến hành quay video quảng cáo cho game ,dựa trên kịch bản được cung cấp (phần này có thể edit, chỉnh sửa code để phù hợp với kịch bản). Nếu game pass CPI thì sẽ tiến hành update thêm từ từ để thu hút player.\n\nYour skills and experience\n\n- Trên 3 năm kinh nghiệm làm game Unity 3D trên mobile\n- Có kinh nghiệm 1 mình làm 1 game (yêu cầu bắt buộc)\n- Yêu cầu làm 2 games/tháng,tùy thỏa thuận\n- Có thể trao đổi công việc /nhận task trong giờ hành chính khi cần\n- Chat bằng tiếng Anh qua ứng dụng slack để trao đổi công việc\n- Nhận lương vào ngày 10 hàng tháng\n- CV tiếng Anh\n- Note: CV ghi rõ Những game đã làm+link game + mức lương mong đợi\n\nWhy you\'ll love working here\n\n- Lương Up to 30M, đóng full BHXH\n- Đóng Bảo hiểm xã hội và thuế Thu nhập cá nhân theo Luật lao động.\n- Thời gian làm việc tự do.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote, Ho Chi Minh, Da Nang, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(214, 191, 2, 'Web Developer (Angular 8+/HTML5, Javascript, CSS3)', 'Top 3 reasons to join us\n1. Môi trường trẻ trung, năng động\n2. Không làm thứ 7, chủ nhật\n3. Lộ trình thăng tiến rõ ràng\n\nJob description\n- Phát triển các sản phẩm học tập trên nền tảng Web.\n- Thiết kế, xây dựng và phát triển ý tưởng mới cho các ứng dụng Web.\n- Tham gia vào toàn bộ quy trình phát triển một sản phẩm ứng dụng hoàn chỉnh để đưa sản phẩm tới người sử dụng.\n- Nghiên cứu các tài liệu, công nghệ để phát triển dự án.\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công của quản lý dự án.\n- Phối hợp với team UI/UX, BA, Backend,... triển khai dự án đảm bảo các yêu cầu về chất lượng, tiến độ.\n- Xây dựng tài liệu kỹ thuật, tài liệu hướng dẫn triển khai hệ thống.\n\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin\n- Tối thiểu 1 năm kinh nghiệm làm việc với Angular 8 trở lên (Ưu tiên Angular 15 trở lên)\n- Thành thạo HTML5, CSS3, Javascript, Typescript, ES6....\n- Hiểu biết về trình duyệt, các vùng lưu trữ dữ liệu trên trình duyệt (LocalStorage, SessionStorage, Cookie...).\n- Biết các kiến thức về SEO trang web, tối ưu trang web là một lợi thế.\n- Ưu tiên từng tham gia dự án Product và có kèm thông tin link sản phẩm\n- Sử dụng thành thạo git và các công cụ hỗ trợ khác.\n- Có kỹ năng giao tiếp và thuyết trình tốt, có khả năng làm việc nhóm tốt\n- Có kỹ năng giải quyết vấn đề, xử lý tình huống tốt\n- Có kỹ năng quản lý thời gian, sắp xếp công việc tốt\n- Có khả năng làm việc độc lập và làm việc nhóm tốt\n- Tận tâm, cầu thị có trách nhiệm, chủ động và tích cực trong công việc\n- Thái độ tốt,lắng nghe, phản hồi tích cực, đổi mới và phát triển.\n\nWhy you\'ll love working here\n1.  Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án\n- Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm\n\n2.  Chế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn\n\n3.  Cơ hội phát triển bản thân\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Toà nhà Toyota Thanh Xuân - 315 Trường Chinh, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(215, 192, 2, 'Flutter Developer (React Native/ OOP)', 'Job description\n- Ứng viên sẽ có cơ hội tham gia và trải nghiệm quy trình phát triển cũng như góp phần lên ý tưởng cho những sản phẩm Product mà công ty đang phát triển.\n- Tham gia vào thiết kế và phát triển các module, chức năng của ứng dụng, tối ưu chất lượng sản phẩm và hỗ trợ cho các thành viên trong team.\n- Cơ hội nâng cao trình độ bằng việc bằng việc tham gia phát triển các sản phẩm có độ phức tạp và hoàn thiện cao, đòi hỏi tối ưu về performance.\n\nYour skills and experience\nYêu cầu chính:\n- Có từ 2-3 năm kinh nghiệm với Flutter, ưu tiên có thêm kinh nghiệm với react native\n- Kiến thức về về OOP, thiết kế hệ thống, cấu trúc giải thuật.\n- Kiến thức về về Firebase.\n- Có hiểu biết về CI/CD.\n- Có khả năng đóng góp, xây dựng cải thiện UI/UX\n- Có kinh nghiệm làm việc theo nhóm theo mô hình Agile | Scrum\n\nKỹ năng:\n- Kỹ năng làm việc độc lập và làm việc nhóm.\n- Tinh thần cầu tiến, cởi mở và thích học hỏi. Tư duy sáng tạo và giải quyết vấn đề. Có tinh thần start up và tư duy sản phẩm.\n- Đề cao trách nhiệm trong công việc, ý thức chất lượng sản phẩm.\n- Kỹ năng xử lý tình huống tốt, cẩn thận, trách nhiệm cao trong công việc.\n\nYêu cầu khác:\n- Ưu tiên ứng viên có kinh nghiệm phát triển product.\n\nWhy you\'ll love working here\nMỨC LƯƠNG:\n- Lương cứng: Upto 20tr (Hoặc deal theo năng lực) + Thưởng tháng lương thứ 13+ Thưởng cổ phần\n- Thời gian làm việc: 8:45 – 18:00 từ Thứ Hai đến Thứ Sáu.\n\nCƠ HỘI VÀ THỬ THÁCH\n- Cơ hội được làm việc trong môi trường chuyên nghiệp, hiện đại và năng động. Thử sứ với các Product hấp dẫn, thử thách đủ lớn với các ý tưởng đột phá.\n- Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng, trao quyền, cho phép bạn làm việc, sáng tạo theo cách riêng. Tài năng và thành tích của từng nhân viên được trân trọng, nhân viên xuất sắc được khen thưởng hàng năm.\n- Cơ hội phát triển năng lực, được hỗ trợ kèm cặp chuyên môn.\n\nCHÍNH SÁCH ĐÃI NGỘ\n- Review lương từ 1-2 lần/năm.\n- Có thưởng kinh doanh theo tình hình kinh doanh của công ty hằng năm.\n- Cung cấp máy móc công cụ làm việc.\n- Có cơ hội trở thành nhân sự Key của công ty và nhận được Cổ phần thưởng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 13 Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(216, 193, 2, 'Senior QC Executive (Automation Test, Tester, QA QC)', 'Top 3 reasons to join us\n- Positive work environment, support & determination\n- Very attractive salary & benefits \n- Development opportunities & improve a quality life\n\nJob description\nPrimary Objectives\nThe Senior Automation Tester position will participate in implementing and executing all aspects of Testing to ensure that quality standards of software products are met. The role requires hands-on QC expertise, ability to take initiative and evolve our QC processes. Besides, the role also requires ability to analyze the systems to determine what to test, the priority of those tests and the best way to test for new features, enhancements, and defect fixes.\nMain responsibilities\n- Apply industry best practices and develop new tools and processes to ensure quality goals are met.\n- Develop and execute test cases, scripts, plans, and procedures (manual and automated).\n- Diagnose defects and track them from discovery to resolution.\n- Partner with engineering teams to stay informed of new technologies being introduced and to ensure that system components are designed for testability.\n- Respond to all requests from team members in a timely professional manner.\n- Any assignments from Line Manager if needed\n\nYour skills and experience\n1. Education level\n- Bachelor’s degree in computer science/ IT\n- Bachelor‘s Degree in Non-Computer Sciences/Non-IT can be considered if earning excellent knowledge/ hands-on experience in software testing.\n\n2. Knowledge & Experience\n- 5+ years of experience in software testing (both manual and automation), with at least 3 years focused on automation for Web and API testing.\n- Strong written English communication skills.\n- Solid understanding of software testing methodologies, including test levels, test types, static testing, and dynamic testing.\n- Proven ability to manage and execute testing activities across different phases of the software development life cycle.\n- Hands-on experience with one or more automation frameworks/tools, such as:  \n+ Selenium WebDriver (Java)  \n+ Cypress/ Playwright  \n+ Other custom or open-source automation frameworks\n- Capable of implementing and maintaining automated test scripts.\n- Experience in developing and enhancing automation frameworks for improved scalability and maintainability.\n- Able to work independently in cross-functional Agile teams.\n- Adaptable to dynamic and fast-changing environments.\n- Ability to collaborate with and coach developers to ensure high testability of features.\n- Experience in the Banking or Financial Services domain.\n- Knowledge of Performance Testing using tools like JMeter or k6.\n- Experience working with Microservice-based architectures, including:  \n+ RESTful APIs  \n+ Event/message-driven systems  \n+ Logging/monitoring tools.\n- Familiarity with CI/CD tools and processes, such as: Jenkins, Docker, AWS, Azure.\n\n3. Technical skills\nWe don’t expect you to know all of them, but experience with multiple is a strong advantage:\n+ Programming: Java, JavaScript/TypeScript (or similar object-oriented languages)\n+ Cloud & Collaboration: Azure, Confluence\n+ API Testing Tools: Postman, SoapUI\n+ Frameworks & Tools: REST API testing, TestNG, Selenium, Cypress, Appium\n- Software Testing Certification is desired but not mandatory.\n- Detailed and effective written communication skills for documenting the features tested and bugs found.\n- Good command of written English is a big plus.\n\n4. Soft skills\n- Highly organized, detail oriented, extremely responsive, and able to prioritize many tasks.\n- Self-motivated, works well independently and with others.\n- Able to perform effectively & independently and mentor others in software testing.\n- Ability to meet deadlines and deliver within our high demand environment.\n- Required to be team-player who is highly motivated, focused on customer satisfaction and solution/ results driven.\n\nWhy you\'ll love working here\nUnderstanding candidates\' expectations of the ideal workplace, we always put the people element at the top of our priorities. \nPrimary benefits:\n- Attractive KPI Bonus annual\n- Review Salary and performance annual\n- 16+ Annual Leaves​, 5 sick leaves, 1 day off birthday\n- Full Social Insurance, Annual Medical Check- up​, Health insurance\n- Team Building and company activities: Year- end Party, New-year Party, Company trip, Charity activities\n- Learning workshops: e-learning, English courses, career development training programs​\n- Sports clubs: gym, yoga, running, football, tennis, badminton.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'AB Tower, 76A Le Lai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(217, 194, 2, 'Senior Backend (C#, ASP.NET, .NET Core)', 'While we are continuing to thrive, our Joblogic team in Vietnam is looking for Senior Backend Developers (C#, ASP.NET, .NET core) to join our dynamic, innovative development team.\n\nJob Responsibilities - Backend side (main focus):\n- The technology stacks you\'ll be working with: C#, ASP.NET MVC, .NET Core, SQL Server, Entity framework, Microservice, SignalR, Azure Cloud, Azure DevOps, MongoDB\n- Assessing and understanding user stories and coding tasks\n- Developing and coding new features, applications, upgrade and fix bugs to high- quality standards and customer expectations\n- Supporting on existing applications\n- Progressing tasks and coding deliverable to completion\n- Coding high-quality, readable and maintainable Unit Tests to ensure maintainability, confidence and testability of changes\n- Taking part in code reviews and collaborate with other developers\n- Proactively growing your professional capabilities and those of the team\n\nYour skills and experience\n- Bachelor of Information Technology, or relevant field\n- Ideally, 6+ years of experience with a strong focus on Backend development using .NET technologies\n- In-depth knowledge of C#, .NET 4.x, MVC, .NET Core, Web API, SQL, Entity Framework\n- Having knowledge and experience with Microservices architecture\n- Hands-on practices with Unit Testing and Integration Testing; and ability to write and run unit tests\n- Having knowledge of web application development\n- Familiarity with database technologies such as SQL Server, MySQL, or MongoDB\n- Proficient in using version control systems, such as Jira, Git\n- Strong understanding of software development principles\n- Good knowledge of OOP and some design patterns\n- Good teamwork, problem-solving, communication skills\n- Understanding and hands-on experience with Agile methodologies\n- Intermediate English communication (both spoken and written)\n\nNice to have:\n- Having knowledge and experience with Azure cloud (Azure DevOps, CI/CD pipelines...); or AWS/GCP services\n- Experience in SaaS, AI-driven products, or mobile applications\n\nHiring process: 01 ROUND – Technical interview (English) with our VN Backend team\n\nWhy you\'ll love working here\n- The office is right in the center, so it\'s easy to commute\n- Well-deserved remuneration package including competitive salary, loyalty bonus, 13th-month bonus\n- Numerous opportunities for growth and development within a leading UK-based product company and a fast-growing international team.\n- Well-equipped working devices\n- 100% gross salary in probation\n- Full social insurance, Premium health care benefits and annual medical checkup\n- Annual paid leaves: 15+ days per year\n- Performance & Salary review per year\n- Enjoy in a nice office with fun, friendly and talented colleagues and plenty of activities: Happy Hours, Company Trip, Sport Activities, International Women\'s Day, Vietnamese Women\'s Day, Men\'s Day, Children\'s Party, Christmas, Year-end Party, etc.\n- Other perks: sponsored certificates (Azure, ISTQB, PSM…), occasional gifts (welcome kit, newborn, marriage, birthday, 8/3, new-year gift...)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '246 Cong Quynh, Pham Ngu Lao Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(218, 195, 2, 'Principal Engineer (Java, Spring Boot)', 'ABOUT TIMO\nEverybody dreams of being rich(er) and fears being poor. Timo supports you in achieving this dream. Financially, we support across the 5 functions of money: moving, managing, accessing, growing, and protecting your money.\nBeing rich however means more than just having a lot of money. Enjoying a rich life includes making money more fun and emotional by embedding banking services into your lifestyle and within your social circle to unlock a truly rich life.\n\nA day in your life might include (what you will be doing/ key responsibilities)\n- Shape product strategy and translate it into high-quality, simple, and impactful features.\n- Propose scalable technical solutions that align with current and future business goals, with clear understanding of trade-offs.\n- Independently identify system weaknesses, propose practical improvements, and effectively communicate them to leadership.\n- Conduct proof-of-concept for new technologies, architectures, and design patterns.\n- Design and document solutions clearly to support accurate estimation and smooth execution.\n- Partner with engineers to provide hands-on technical leadership throughout implementation.\n\nYour skills and experience\n- 10+ years of professional software development experience, including 4+ years with Java and 2+ years in a Principal Engineer or Software Architect role.\n- Strong expertise in designing RESTful APIs using Java Spring Boot.\n- Hands-on experience with messaging systems such as Kafka, RabbitMQ.\n- Solid understanding of caching strategies and tools like Redis.\n- A desire to work on high-performance, highly scalable Financial transactions systems with billions of transactions per month.\n- Strong communication and collaboration abilities; team-oriented mindset.\n- Proven experience with Agile practices, Unit Testing, CI/CD, and cloud-native development (12-Factor App principles).\n- Bachelor’s degree in Computer Science, Engineering, or a related field.\n- Deep understanding of software design patterns, microservices architecture, secure development, and cloud-based systems.\n- Familiarity with Spring ecosystem, Jersey, jOOQ, Java 8+ features (Streams, Lambdas, Reactive), scripting, and basic OS administration.\n\nWhy you\'ll love working here\nOur deliverable is a leading software that is changing the way people do banking. You will be proud of your work and you will share with everybody that you helped to build Timo.\n\nYou’ll be joining a team of experts who are technically savvy, creative, and who share the intention of reinventing banking in Vietnam. You work closely with international architects and front-end consultants, product managers, and designers to develop the system. You will learn a lot from them.\n\nCompany Benefits:\n- Full benefits and salary during probation\n- Premium health care insurance\n- Competitive salary and learning culture\n- Other benefits as per stated in Vietnamese Labor Law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '412 Nguyen Thi Minh Khai, Ward 5, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(219, 196, 2, 'Senior/Lead Backend Engineer (Golang)', 'About GHN\n\n"Giao Hàng Nhanh (GHN) is one of Vietnam’s leading logistics companies, proudly delivering exceptional services with the commitment: “Smarter, Faster, More Cost-Effective.” GHN empowers millions of businesses to optimize their operations while creating thousands of jobs for the Vietnamese workforce.\n\nFounded with the mission to revolutionize the logistics industry and guided by a technology-driven vision, GHN continuously integrates advanced technological solutions into every delivery. This enables streamlined operations, enhanced delivery performance, and a fast, safe, and efficient customer experience - serving a wide range of clients including E-commerce platforms, retailers, and individual consumers.\n\nWith a nationwide network spanning all 63 provinces and cities, a forward-thinking innovation strategy, and robust logistics infrastructure, GHN continues to affirm its position as a pioneer in Vietnam’s rapidly growing E-commerce and logistics sector."\n\nAs a Senior/Lead Backend Engineer at GHN, you will play a critical role in designing and developing scalable backend systems that power Vietnam\'s leading logistics platform. You’ll work on high-impact projects that optimize core operations—from pickup to delivery—while driving technical excellence, system reliability, and innovation across teams.\n\nResponsibilities\n\nDesign & Develop Logistics Solutions: Build and enhance scalable backend systems that power core logistics operations, including first-mile pickup, last-mile delivery, warehousing, sorting, and freight transportation.\n\nAPI Development: Design and implement robust, secure, and well-documented open APIs to support seamless integration with internal systems and external partners, enabling a more connected logistics ecosystem.\n\nPerformance & Reliability: Continuously monitor and improve system performance. Proactively troubleshoot and resolve production issues, conduct root cause analysis, and contribute to system refactoring efforts to enhance reliability, maintainability, and scalability.\n\nCode Quality & Best Practices: Write clean, modular, and testable code that adheres to engineering best practices. Actively participate in code reviews, knowledge sharing, and documentation to maintain high standards across the codebase.\n\nAgile Collaboration: Work in a fast-paced Agile environment, collaborating closely with product managers, frontend developers, QA engineers, DevOps, and other stakeholders to deliver high-impact features and improvements.\n\nYour skills and experience\n\nRequirement:\n\nBachelor’s Degree in Information Technology, Computer Science, or equivalent.\nAt least 4+ years of experience in full lifecycle project development using Golang.\nExtensive experience in software design, architecture, development integration.\nSolid knowledge of event processing models, parallel programming, multi-threading, enterprise integration pattern, Socket, Web Service, and REST.\nProficient in relational databases, and familiar with at least one NoSQL DB.\nDistributed Caching such as Redis.\nFamiliar with Microservices, event-driven architecture.\nGood cross-team communication skills.\n\nThe following skills would be nice to have:\n\nExperience creating React-based UIs.\nExperience with big-data technologies such as Apache Kafka, and OLAP.\nKnowing how to work with Docker, K8S or cloud services, e.g GCP, AWS... is a big plus.\n\nBackend Developer:\n\nRequirement:\n\nBachelor’s Degree in Information Technology, Computer Science, or equivalent.\n2+ years of experience with full lifecycle of project development using Golang.\nGood knowledge of event processing models, parallel programming, multi-threading, enterprise integration pattern, Socket, Web Service, and REST.\nFamiliar with at least one SQL DB such as MySQL, PostgreSQL.\nExperience with distributed caching technologies such as Redis.\nFamiliar with Microservices, event-driven architecture.\nGood cross-team communication skill.\n\nThe following skills would be nice to have:\n\nExperience with big-data technologies such as Spark, Airflow.\nKnowing how to work with Docker, K8S or cloud services, e.g GCP, AWS... is a big plus.\n\nWhy you\'ll love working here\n\n13th-month salary, performance bonuses, and KPI bonuses.\nHealth insurance, Social insurance, and Unemployment insurance.\nMedical insurance.\nAnnual health checkup.\nAnnual salary reviews.\nAnnual team building/company trip.\nOngoing internal and external training opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3rd Floor, Rivera Park Building, 7/28 Thanh Thai, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(220, 182, 2, 'Backend Technical Lead (Java)', 'Top 3 reasons to join us\nExcellent environment and team to help you grow.\nCompetitive salary and learning culture.\nPremium health care for you and your family.\n\nJob description\nDescription:\nThe Technical Leader will drive the efficient delivery of change through analysis, definition, and documentation of requirements whilst identifying potential solutions using agile delivery frameworks.\nWhat you’ll be doing\nWork in small, highly collaborative agile teams. You and the team will have a clear mission and ownership of an important outcome that support Tyme and our customers.\nAlign with stakeholders across Tyme on best practices around APIs, security, compliance, roadmap, and reliability.\nHelp drive the technical direction of software features.\nBuild highly scalable, reliable, and maintainable APIs to handle high-volume transactions.\nWe aim for teams that are inclusive, helpful, and have a strong sense of ownership for the things they build.\nAt Tyme, we optimize for quality, flow, and fast feedback, focusing on end-to-end ownership, continuous improvement, testing, monitoring, and experimentation. We’re looking for positive and passionate people who will put teamwork and collaboration above all else.\n\nYour skills and experience\nYou should have:\nA pragmatic mindset.\nKnowledge of professional software engineering practices for the full development life cycle (coding standards, code reviews, source control management, build processes, testing, operation, monitoring, etc.).\nWith at least 8+ years of experience working in software development, we also welcome strong candidates having fewer years of experience.\nPreferably with 3+ years of experience in Java. We also welcome other general-purpose programming languages but are not limited to Java.\nUnderstanding of system design and tuning for high performance, scalability, and reliability.\nStrong database and schema design for large-scale and finance systems.\nGreat problem-solving abilities.\nExperience with microservices architecture.\nExperience with event-driven architecture or message queue system\nProfessional experience working with cloud (either AWS, Azure, or GCP).\nExperience in enterprise architecture.\nWorking proficiency in English.\nQualifications:\nThe ability to work and live in Ho Chi Minh City\nB.Sc or M.Sc in Computer Science or a related discipline with proven "hands-on" development experience.\n\nWhy you\'ll love working here\nYou’ll love working with us if you are:\nPassionate about technology.\nIndependent but also a good team player.\nComfortable with a high degree of ambiguity.\nFocused on usability and speed.\nKeen on presenting your ideas to your peers and management.\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\nSome of our benefits:\nMeal and parking allowances are covered by the company.\nFull benefits and salary rank during probation.\nInsurances such as Vietnamese labor law and premium health care for you and your family.\nSMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\nValues-driven, international working environment, and agile culture.\nOverseas travel opportunities for training and work-related.\nInternal Hackathons and company events (team building, coffee run, etc.).\nPro-Rate and performance bonus.\n15-day annual + 3-day sick leave per year from the company.\nWork-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(221, 197, 2, 'Backend Engineer (Python) - AGI', 'Top 3 reasons to join us\n1. Top Salary, Awesome Benefits\n2. Premium healthcare for 3 members in family\n3. Grab to work, Lunch allowance for all employee\n\nJob description\n- Collaborate with engineering teams to design, develop, and deploy business critical solutions.\n- Stay continuously informed about the latest advancements and trends in the AGI field.\n- Write clean, maintainable, and efficient code to implement new features and functionalities.\n- Research and adopt new techniques and methodologies to solve complex problems, utilizing critical thinking and analytical skills.\n- Proactively identify and address complex issues related to task management, load balancing, and system scalability.\n- Share knowledge through peer-to-peer collaboration, conduct code reviews, provide technical guidance, and mentor junior team members as needed.\n\nYour skills and experience\n- Bachelor’s degree or higher in Computer Science, Engineering, or a related field.\n- Over 3 years of experience in software engineering.\n- Proficiency in backend development in an object oriented language. Proficiency in either Python, Golang, Node.js or C# and the willingness to learn another.\n- Familiarity with distributed task management systems and job queues like Celery, Faktory, BullMQ or others.\n- Experience in full-stack engineering is highly desirable and willingness to work with tools like HTMX, jQuery or React.\n- Good understanding of relational databases, locks, indexes and transactions. Strong SQL skills.\n- Demonstrated ability to quickly learn and adapt to new technologies and programming languages.\n- Excellent problem-solving skills, with a strong understanding of algorithms and data structures.\n- Familiarity with best practices in the software development life cycle, including version control, code reviews, and testing frameworks.\n- Ability to work effectively both independently and collaboratively within a team environment.\n- Familiarity with writing unit tests.\n\nWhy you\'ll love working here\n- Competitive compensation package, including 13th-month salary and performance bonuses\n- Comprehensive health care coverage for you and your dependents\n- Generous leave policies, including annual leave, sick leave, and flexible work hours\n- Convenient central district 1 office location, next to a future metro station\n- Onsite lunch with multiple options, including vegetarian\n- Grab for work allowance and fully equipped workstations\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Havana Tower - 132 Ham Nghi, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(222, 198, 2, 'Senior AI Engineer', 'If you have a strong passion for creating robust and scalable AI-based software products and thrive in a collaborative, dynamic, and technologically advanced environment, our exclusive opportunity at Renn Labs might be the perfect fit for you. We are on the lookout for a highly passionate AI Engineer to become a vital part of our globally innovative team.\n\nIn the role of a Senior AI Engineer, your primary focus will be to design, develop, and integrate AI models using diverse frameworks, ensuring they align with our project requirements and enhance our software infrastructure. You will engage in rigorous testing and validation to guarantee model reliability and performance and work closely with the technical team to embed AI functionalities into our products.\n\nAre you ready to elevate your value to new heights and redefine the future? Start your AI Engineering journey with Renn Labs today.\n\nTHE IMPACT YOU’LL MAKE IN THIS ROLE\n\n• Collaborating with key stakeholders to understand project requirements, contribute to technical feasibility assessments, and actively engage in project planning and execution;\n• Innovatively designing and developing advanced AI/ML models and algorithms that cater to the specific needs of our applications, utilizing industry-standard frameworks such as TensorFlow or PyTorch;\n• Integrating seamlessly AI/ML models into our existing software infrastructure, ensuring they function harmoniously within the broader system architecture;\n• Seamlessly developing standardized and automated processes, including data collection, model training, inference, and incorporating user feedback into the training pipeline for continuous model improvement and upgrades;\n• Successfully define methods to evaluate and benchmark results, ensuring we can clearly determine whether changes or refactoring efforts are improvements or setbacks;\n• Rigorously testing and validating AI/ML models to guarantee their accuracy, reliability, and efficiency in real-world applications;\n• Working proactively with software engineers to incorporate AI/ML functionalities into user interfaces and backend services;\n• Experiment with various AI approaches, such as multi-modal methods like Colpali or leveraging tools like Swirl AI Connect for context search and retrieval-augmented generation (RAG).\n• Constantly staying informed about the latest advancements in AI/ML technologies and industry best practices, and actively suggesting ways to incorporate emerging trends into our development processes such as enhancing inference speed, scaling AI systems to serve multiple customers simultaneously, and minimizing training costs.\n• Ensuring that data security, privacy, and ethical considerations are central to our AI/ML solutions, in collaboration with cross-functional teams;\n• Comprehensively providing technical documentation and facilitating knowledge transfer to internal teams for the effective understanding and application of AI/ML components.\n\nWHAT YOU’LL NEED TO MAXIMIZE IMPACT IN THIS ROLE\n• 5 years of practical experience in developing AI-powered software. The designated title will be assigned based on your strengths, experience, and potential for growth.\n• Proficiency in AI/ML frameworks, such as TensorFlow or PyTorch.\n• Experience with OpenAI API with hands-on experience in developing and deploying machine learning models.\n• Practical experience in building AI models using open-source LLMs like LLaMA.\n• Strong proficiency in Python and familiarity with key libraries and tools for AI/ML development.\n• Skilled in data preprocessing, feature engineering, and model evaluation techniques.\n• Familiar with cloud platforms like AWS, Azure, or Google Cloud for AI/ML solutions deployment and management.\n• Solid understanding of software development principles, version control systems (e.g., Git), and collaborative coding practices.\n• Strong problem-solving skills and a keen interest in addressing complex challenges in AI/ML development.\n• Good communication, with the ability to understand business requirements and comfortably discuss ideas.\n• Excellent collaboration skills, with the ability to work effectively in a global environment and agile project setting.\n• Demonstrated ability in mentoring and managing multiple projects simultaneously will set your application apart and give you a distinct advantage.\n• Last but not least, an eagerness to learn and a startup spirit at heart. This role provides extensive exposure to AI-driven product development, offering a pathway to global ways of work and highly advancements in the future of technology.\n\nWhy you\'ll love working here\nAI-FIRST VENTURE STUDIO with decades of experience in entrepreneurship and innovative technology. Renn Labs is an exclusive innovation studio committed to incubating cutting-edge experiments and developing transformative solutions in AI, finance, and e-commerce. Our mission is to create exponential impact, empowering select partners to accelerate their growth and revolutionize their industries. Spearheaded by a top-tier venture capitalist and investor based in the United States and bolstered by a team of diverse experts, our expanding team in Vietnam is at the forefront of groundbreaking innovation.\n\nAt Renn Labs, we leverage a variety of AI techniques across our projects in the realms of investment and e-commerce. Our products are powered by advanced technologies, including OpenAI, Perplexity, Claude, and Gemini. We employ a range of approaches such as RAG, Roleplay, Replay, ReAct, Few-shot Learning, Chain of Thought etc.\n\nHere are some of our fascinating projects:\n• An AI-powered fundraising platform that is transforming the alternative investment industry. It provides access to 150K+ firms in the industry and includes an AI memo tool for writing sophisticated documents. Additionally, the platform features a due diligence tool that allows users to interact with financial documents. It also includes an AI-powered news curator tailored to the industry.\n• An AI-powered newsletter digest that helps individuals and companies navigate the ocean of information in the new AI age. It personalizes the newsletter experience by allowing users to choose from a curated list of the top 20 newsletters or connect Gmail to receive summaries of other newsletters.\n• An AI concierge for gift shopping that makes finding the perfect gift easier, faster, and more enjoyable.\n• An AI content platform for next-generation e-commerce that establishes a strong data foundation and connectivity to enable hyper-scalable generative content. It features product intelligence, generative AI content, enrichment and standardization, and microsite development.\n• An AI powered automated SEO content generator with best practices. It offers keyword analysis, competitor analysis, content generation, internal and external linking, and platform deployment.\n• And more projects that could originate from your ideas.\n\nOur AI-First Culture\nRenn is embarking on an exciting “AI First” journey, harnessing cutting-edge technologies and methodologies adopted by top tech and digital innovators across the globe. Our transformation goes beyond just technology. We are deeply committed to investing in our people with AI tools.\n\nWe are a collective of innovators, thinkers, and creators. Our culture is built on the foundation of experimentation, continuous learning, and a relentless pursuit of excellence. We believe in empowering our small team to make big contributions, ensuring that every voice is heard and every idea is valued.\n\nIf you are eager to learn, grow, and inspire those around you, then Renn team is the ideal place for you!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '200 Street 3/2, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(223, 199, 2, 'Backend Developer (Java)', 'Job description\n- Design and develop high-quality, high-performance web services and applications in collaboration with architects and team members.\n- Review, clarify, and contribute to business/product requirements, and transform ideas into functional solutions.\n- Develop Middleware, APIs, and Workers to support business-critical systems.\n- Research, evaluate, and adopt new technologies as needed to enhance system performance.\n- Monitor and track product metrics to gather feedback from end-users for continuous improvement.\n- Create and develop business and market reports to support decision-making.\n\n2 round process:\n- Round 1: Technical & Logic Test.\n- Round 2: Interview with Hiring manager\n\nYour skills and experience\n- Education & Experience: Bachelor’s degree in Computer Science, IT, or related field (or equivalent experience).\n- Programming & Development: Proficiency in Java, Node.js, or Python, with the ability to quickly adapt to new technologies.\n- Architecture & Web Services: Strong knowledge of microservices, event-driven architectures, and RESTful web services (gRPC or Thrift is a plus).\n- Database Management: Familiarity with RDBMS (MySQL, PostgreSQL) and/or NoSQL databases (MongoDB).\n- Tools & Platforms\n  - Experience with Elasticsearch and the ELK stack (highly advantageous).\n  - Knowledge of Google Data Studio, Power BI, or Machine Learning is a plus.\n\nWhy you\'ll love working here\n- Location: District 1 (Nguyen Binh Khiem Street)\n- Competitive Salary – Based on skills and experience, with performance-based adjustments.\n- Bonuses & Incentives – 13th-month salary, performance bonuses, and annual salary reviews.\n- Provide a laptop (Macbook)\n- Work Schedule – Monday to Friday\n- Comprehensive Insurance – Full coverage as per labor law, plus additional private healthcare.\n- Learning & Development – Access to training programs, mentorship, and career growth opportunities.\n- Team Bonding Activities – Company trips, team outings, and engagement events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nguyễn Bỉnh Khiêm, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(224, 200, 2, 'Cybersecurity Engineer  (Security/Cloud/AWS)', 'Protect. Innovate. Lead the Future of Secure Tech.\nAt DIGI-TEXX, we’re not just building smart solutions — we’re securing the future of digital innovation. As a trusted tech partner delivering cutting-edge AI/ML-powered services, we believe cybersecurity is the foundation of everything we build.\nWe’re on the lookout for a passionate, hands-on Cybersecurity Engineer who’s excited by challenges, thrives in a fast-paced environment, and wants to make a real impact.\nWhat You’ll Own & Drive\n- Develop and maintain systems that reliably monitor and respond to security incidents and threats in real-time\n- Implement and maintain firewalls, Intrusion Detection/Prevention Systems (IDS/IPS), endpoint protection, and other key tools\n- Run vulnerability scans, penetration tests, and security audits\n- Design and enforce security policies, standards, and best practices\n- Collaborate with DevOps and IT teams to build secure infrastructure from the ground up\nStay one step ahead with the latest security trends, risks, and mitigation techniques\n\nYour skills and experience\n- 3-5 years of experience in cybersecurity roles\n- Solid knowledge of network security, threat detection, and incident response\n- Hands-on with Security Information and Event Management (SIEM), firewalls, IDS/IPS, endpoint protection tools\n- Familiar with ISO 27001, National Institute of Standards and Technology (NIST), Open Web Application Security Project (OWASP) best practices and cloud security across AWS (Amazon Web Services), Azure, or GCP (Google Cloud Platform)\n- Bonus points for scripting skills: Python, Bash, or PowerShell\n- Team player with great problem-solving skills\n- Confident, clear communicator in English (Certificate or not - if you are at a level at which you can thoroughly describe your technical innovations and strategies to a foreign expert through an online call, we’d like to hear from you.)\n\nWhy you\'ll love working here\n- 13th-month salary and annual performance bonuses\n- Full coverage of social insurance\n- Premium healthcare insurance \n- Company trip and team building activities\n- Professional and transparent working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Anna Building, Quang Trung Software City, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(225, 201, 2, 'Senior Manual QC Engineer', 'About One Mount:\nOne Mount is Vietnam’s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam’s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nJob Description:\n- Elicit and analyze business requirements from key stakeholders and assess relevant solutions and their potential impact\n- Define the testing objectives and criteria for success and oversee the testing and follow up processes for software products\n- Determine requirements and develop test plans.\n- Execute writing test design, test cases based on the system specification documents\n- Develop automation test scripts based on available frameworks\n- Perform the following test: Manual UI test, API test, Mobile/Web test, Performance test, automation test\n- Review failure analysis results and implement changes that limit and/or eliminate the causes of failure\n- Performs log bugs, evaluates bug severity and keeps track bug status via JIRA as workflow actions\n- Self-management of personal work and report progress to the team and the leader.\n- Assisting other team members and associated with IT and Business team\n- Ensure agile software development methodologies to develop, improve and deploy software applications\n\nYour skills and experience\nKey Skills:\n- Over 5 years of experience in software testing (required)\n- Strong experience in creating, maintaining test artifacts (test plan, test cases, test scenarios, test report...)\n- Experienced in testing API using Postman, Soap UI …\n- Experience in using SQL statements\n- Experience in using the Java language\n- Understanding of all phases of a test cycle, including but not limited to functional, regression, integration, performance, acceptance, load, black box, white box, and automation testing\n- Understand the software product development processes.\n- Ability to work independently, excellent in communication and solve problems\n- Ability to work on different projects concurrently.\n\nDomain Expertise:\n- Graduated from university majoring in IT (required)\n- Having knowledge and experience in an automation test framework (Robot framework…) is an advantage.\n- Ability to learn new knowledge and skills if guided\n- Having experience working under the Agile model (Scrum).\n- Having experience in finance service projects and proptech are an advantage.\n\nIndividual Skills:\n- Agility, active, proactive, sense of responsibility\n- Details oriented, hard-working\n- Good communication\n\nWhy you\'ll love working here\nBenefit and Perks\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000 VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Premium Social insurance, yearly health check\n- Laptop, screen and other needed facilities/accounts/tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'relly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n\nWorking Environment\n- Open & collaborative working space foster both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms, sleep corner.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tower 2 (T26) Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(226, 202, 2, 'Cloud Engineer Microsoft 365 (System Engineer, M365)', 'Are you passionate about modern cloud technologies and want to help shape innovative IT environments? As a Cloud Engineer for Microsoft 365 at Dinotronic, you will:\nMaintain, improve, and support customer environments using Microsoft 365 and Azure technologies\nWork on M365 Intune (configuration, software packaging & deployment), Entra ID and other Cloud technologies\nOnboard customers to standardized M365 & Azure environments, manage migrations, conduct proof of concepts (PoC), and suggest solutions together with our international team\nHandle support incidents, daily operational tasks, maintain the security of our services and work on modern cloud technologies depending on your skills and preferences\nOptional, if interested: Work on automating our onboarding-tasks and enforcing our standards by using PowerShell scripts and Azure DevOps as well as Power Platform, supporting our vision of a fully-automated managed service provider\n\nWe’re looking for someone who combines technical expertise with a passion for learning. Here’s what we’d love to see:\nA degree in IT (e.g. computer science, information technology)\nSolid knowledge of Microsoft 365 backend like Intune, Entra ID, and Exchange Online\nFamiliar with Azure cloud services (IaaS, PaaS, SaaS)\nA good level of English, a self-driven and innovative mindset, reliable, and a passion for IT\nBonus points if you have (optional):\nExperience in cloud automation (PowerShell, DevOps, or Power Automate)\nKnowledge of network/firewall administration\nKnowledge of Windows Server OS and Microsoft technologies for patch management, device management, backup, security\nInterest or experience in security, information & identity protection, AVD/W365, ARM, infrastructure-as-code, Azure Automation, Power Automate, or related fields\nMicrosoft certifications (not a must, but always a plus)\n\nAt Dinotronic, IT isn’t just a job—it’s our passion. We’re a cloud-only managed service provider with a dynamic, international team spanning our Vietnam office and Swiss headquarters. Between both teams we work together on interesting technologies, follow processes according to ITIL and we love what we do.\n\nHere’s why you’ll love being part of our team:\nWork with cutting-edge cloud technologies\nReceive training for the job and enough time for learning—plus support to earn Microsoft certifications\nEnjoy a positive, respectful working environment in an inspiring team, with flexible conditions, an attractive salary & benefits package\nGrow your career in exciting fields like M365, security, cloud infrastructure, scripting, or related fields\n\nLooking forward to welcoming you onboard our team soon!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '147-149 Vo Van Tan, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(227, 189, 2, 'System Engineer (Embedded, Linux)', 'Top 3 reasons to join us\n- Attractive Salary & Benefit\n- Yearly Performance Bonus (2 Times/Year)\n- Premium Health Insurance\n\nJob description\n- Design and implement System Framework to verify device driver\n- Creating control features to ensure systems effectively meet the organization’s quality standards\n- Design and implement window application for automation test system (error detection, error analysis, log collection), which external controls multiple devices and graphic driver (PDM/HDPC, MSPG, EIDEN) / NVidia card.\n- Log analysis to define & resolve market issue, ensure product reliability.\n- Ensures completion of all documentation required for production introduction.\n- Use GitHub for source code repository and Jira for task tracking.\n\nYour skills and experience\nGeneral Requirement:\n- Bachelor\'s or Master\'s Degree in Computer Science, Computer Engineering, relevant technical field, or equivalent practical experience.\n- At least 3+ years of experience with C, C++, C#, Linux, Docker\n- Good in English communication for working.\n- Ability to work on multiple tasks concurrently.\n- Self-motivated with a strong desire to learn.\n- Solid decision-making skills and judgment – can be depended upon to meet goals, foresee and avert problems.\n\nTechnical Requirement:\n- C, C++, C# programming experience.\n- Proven working experience in installing, configuring and troubleshooting UNIX/Linux based environments.\n- Solid scripting skills (i.e., shell scripts, Python).\n- Experience in window application and device protocol (PDM/HDPC, MSPG, EIDEN).\n- Strong understanding CI/CD system.\n\nWhy you\'ll love working here\n- Yearly Performance Bonus 2 times/year (up to 3-month salary) + 13th Salary. (At least 15 months).\n- Flexible working week policy.\n- Intensive Training Program.\n- Oversea Biz-trip\n- Linkedin E-Learning & Udemy unlimited access.\n- Premium Health Insurance.\n- 100% salary and mandatory social insurances in 2-month probation.\n- Daily shuttle bus from city center to company\n- Team Building Gifts quarterly.\n- Free luncheon.\n- Birthday Gifts.\n- Training Opportunities in Korea.\n- Take part in various significant activities such as SEHC Festival, SEHC Cup, Town Hall Meeting, Liên Quân Mobile Champion, SEHC Marathon, SEHC Hackathon, SEHC Home Town,....', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lot I-11, D2 Road, Saigon Hi-tech Park, Tang Nhon Phu B Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(228, 203, 2, 'Technical Project Manager (Agile Coach/L, Scrum Master)', 'If you’re looking to be a part of a dynamic, highly-analytical team who enjoys project management, look no further. As a Technical Project Manager, you will be handed the reins in project management for the company. Along with managing IT projects independently according to IT project life-cycle standards, you’ll also be in charge of mentoring and coaching other members. Collaborating with various other teams within the company, you’ll ensure the nature, maintenance, and standards for every project under your watch run seamlessly and on time. Collectively, your efforts will help align the stakeholder’s business targets with the right projects’ objectives and outcomes.\nManage the execution of multiple complexities, technically oriented projects in parallel\nEnsure products (mobile app, web app, and back-end systems) are shipped against aggressive deadlines and exacting standards\nProvide status reports regarding project milestones, deliverables, dependencies, risks, and issues, communicating across leadership\nBe the operational heart of a cross-functional team of developers, designers, QA,s and product managers, to allocate tasks, prioritize features, manage releases.\n\nYour skills and experience\nBackground in Computer Science, Engineering. Master’s degree is a plus\nExperience in IT/Internet/Software field with experience working with both Developers and Non-Dev colleagues\nHave the technical knowledge to understand the requirement, architecture, and to work with multiple teams\nExperience working as an Agile Coach, Scrum Master or Agile delivery lead\nSolid organization, leadership, team-building, and mentorship experience\nGood at English and are a confident communicator.\n\nWhy you\'ll love working here\nWhy should you work in this position?\nAhamove is the number 1 on-demand logistics company in Vietnam, the place to give you access to current and first-class technologies, as well as connect e-commerce and payment platforms of millions of users.\nAt Ahamove, the sense of ownership is put on the top and the team is supported to complete your works, as well as supported and made favorable conditions for learning and self-improvement.\nOpen and honest culture where people are valued, treated fairly, trusted and empowered.\nDisruptive innovations\nPeople-oriented philosophy of doing business\nYour footprint on regional on-demand market\nSharp, motivated colleagues in a fun office environment\n\nBenefits and Allowances\nGrab/Be for work: 1M/month\nLaptop & PVI insurance\nWorking 5 days/week\nCompetitive salaries and benefits according to experience and education level\nComfortable Private working Area for the TECH team\nTeambuilding + Outing trip\nAnd more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Rivera Park 7/28 Thành Thái, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(229, 204, 2, 'UI-UX Designer (Figma, Adobe Creative Suite, English)', 'UI and UX design will be one of our key differentiators. Designveloper wants to keep improving on this so that our user experience continues to be the best in design.\nWe are looking for someone who likes to keep researching the latest trends, designs and implement them in his/her work. Experiment with colors, effects, patterns, typography, icons etc.\nAre you passionate about design web, mobile applications and solving complex problems? Do you enjoy working in a dynamic, fast-paced and fun environment? We want to meet you!\n\nResponsibilities\nDesign System Management: Consume and maintain our existing design systems (individually in each team) to ensure consistency and scalability across all products.\nUI Design: Create visually compelling and user-friendly interfaces that align with our brand guidelines for our commercial purposes on website.\nUX Research: Participate in user research and usability testing sessions to gather insights and inform design decisions. Having experience with analytics tools: Google analytics, Hotjar, Crazy Egg, … is a plus.\nCollaboration: Work closely with cross-functional teams including product managers, developers, and other designers to bring concepts to life.\n\nYour skills and experience\nAt least over 3 year working years in UI/UX design experience in web and mobile applications. Mobile applications portfolio is a plus\nStrong UX design portfolio showcasing past projects and design skills.\nProficiency in design tools: Figma, Adobe Creative Suite or similar.\nGood communication skills and ability to collaborate with cross-functional teams.\nSelf-motivated and ability to work independently with minimal supervision.\nProficiency in English is a must as you would collaborate closely with our foreign clients on daily basis.\n\nWhy you\'ll love working here\nWhy You\'ll Love Working Here?\nSalary Up to $1800\nWorking & growing with Passionate & Talented Team.\nDiverse careers opportunities with Software Outsourcing, Software Product.\nEnglish environment with projects from US, UK, …\nProjects in various domains (pdf, logistic, online contract, medical …)\nVarious training on hot-trend technologies, best practices and soft skills.\nHave 2 - 3 remote days / week (Flexible).\nWorking time 35 hours/week (Monday – Friday).\nMaximum 16 days annual leave per year.\nRefund annual leave days at the end of year.\nProfessional training process (support Udemy training course, >5000 courses).\nTraining course refund (AWS…)\nAttractive Salary and Benefits.\nPerformance review.\nAlmost all customers from the US, UK ….\nMacBook Pro provided.\nPersonal laptop allowance: $250 per year.\nEmployee referral bonus: $100 - $500.\nProject referral bonus: 5% project value contract.\nSocial insurance, PVI Premium health care for you and your loved ones.\n13th month salary and Bonus based on team performance.\nFree in-house entertainment facilities (bilak, ping pong,…), coffee, snacks, instant noodles,…\nSport activities: football, table-tennis, table football…\nCompany trips, team building, office parties, …..\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No. 53-55-57, Pho Duc Chinh street, Nguyen Thai Binh ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(230, 205, 2, 'Senior Product Manager/Senior Technical Product Manager', 'At LeapXpert, we\'re revolutionizing business communication by seamlessly integrating the familiarity of consumer messaging apps with enterprise-grade security and compliance. As pioneers in responsible business communications, we empower employees and clients to connect through their preferred messaging platforms while upholding the highest standards of governance and security. Our mission is to transform workplace communication globally. We\'ve been recognized as a Visionary in Gartner\'s Magic Quadrant for Digital Communications Governance and Archiving Solutions, raised a $20 million Series B funding round—bringing our total funding to $60 million, and earned the trust of top-tier institutions worldwide, who rely on our platform daily to streamline client communications. This is just the beginning—we\'re growing rapidly and we\'re seeking passionate, talented individuals to join our team. This is your opportunity to work on impactful projects using cutting-edge technologies alongside driven innovators from around the world. Apply now to be part of something revolutionary! Responsibilities: Develop technical specifications for the LeapXpert FMOP platform Collaborate with Engineering Leaders to drive the technical direction of the product roadmap, addressing complex topics such as performance, scalability, and reliability Own key product areas, including API architecture and third-party integrations Works with business stakeholders to define the product vision, strategy & roadmap for assigned product areas Leads initiatives across some product areas or features that directly contribute to the company’s long-term vision Owns customer feedback initiatives of assigned product areas, ensuring that feedback is systematically incorporated into decision-making processes Drives and Co-owns UX improvements of assigned product areas, ensure that designs meet user needs and are intuitive Uses data, market research and industry best practices to inform product decisions and prioritization, ensuring that metrics are tied to key business outcomes Owns the development of feature specifications for complex and strategic initiatives. Engages stakeholders early to align on scope and execution while ensuring even edge cases are addressed Drives the end-to-end product delivery process for key features or initiatives at Epic-level, ensuring that all stakeholders are aligned, and dependencies are addressed Work with front-line stakeholders (business owners, customer success teams) in (some) client projects to drive expectations and get requirements Owns development backlogs of 1 or 2 scrum teams Your skills and experience: Solid background in software engineering, preferably ~3 years working as software engineers is a big plus Proven experience in product management (5+ years), experience as Technical PM is a mandatory requirement Strong business acumen, strategic thinking, and focus on execution and outcomes. Experience in driving cross-functional programs or processes Excellent interpersonal skills, excellent English communication skills, both oral and written In-depth understanding of Agile principles, with the ability to apply them effectively to projects Collaborative team player with strong organizational, analytical, and problem-solving skills Why you\'ll love working here: You are looking for: An awesome job opportunity with an attractive remuneration package Working on site in a stylish and comfortable environment. Friendly coworkers who support each other to win together as a team Working in a team that encourages AI adoption, experimenting with and learning new AI tools to enhance the developer experience. A flat, product-focused organization and Agile teams that allow you to bring value and ideas to the product and the company Opportunities to learn and be trained in new technologies and methodologies Facing new and innovative challenges to deliver a commercial-grade, world-class product Career growth in multiple directions, based on your preferences and abilities Benefits: 13th Salary, paid pro-rata, every month to allow more flexible financial plans 18 annual leaves and 1 birthday leave Full salary on probation Full social insurance according to Vietnam Labor Law Premium Health Care Insurance Annual health check Lunch and parking allowances Team building, fun monthly, quarterly activities, and so much more fun are waiting for you! Relax with Tabletop foosball, PlayStation, massage chair in the office Annual Performance Review Attractive career path Advanced technical solutions, Agile culture and the opportunity to work with the latest technologies Sounds like a good fit? Come and join the team at LeapXpert!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '195/10E Dien Bien Phu, Ward 15, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(231, 186, 2, 'Fx Artist (2D/3D, Unity, After Effects)', 'Job description\n- Thiết lập hiệu ứng cho TV series animation, cũng như các sản phẩm 3D cần thiết cho game\n- Tạo VFX và shader chất lượng cao dựa trên chỉ đạo nghệ thuật, hạn chế kỹ thuật và thời hạn.\n- Đảm bảo hiệu ứng phù hợp với phong cách hình ảnh của game.\n- Phát triển các công cụ và kỹ thuật mới để tối ưu hóa, cải thiện quy trình sản xuất\n\nYour skills and experience\n- Bắt buộc sử dụng thành thạo: Unity và After Effects\n- Bắt buộc có khả năng tạo hiệu ứng cả 2D và 3D\n- Ưu tiên ứng viên có hiểu biết sâu về hệ thống hạt (Particle System)\n- Kinh nghiệm: từ 3 năm trở lên\n- Yêu cầu: Có portfolio (hồ sơ năng lực cá nhân)\n- Nhận CV song ngữ Tiếng Anh- Tiếng Việt\n\nWhy you\'ll love working here\n✨ CHẾ ĐỘ PHÚC LỢI HẤP DẪN TẠI CÔNG TY ✨\n\n- Thu nhập cạnh tranh: Mức lương hấp dẫn, thưởng tháng 13 và thưởng thâm niên.\n- Thưởng theo hiệu quả công việc, xét thưởng vào các dịp Lễ – Tết.\n- Đánh giá tăng lương 1 lần/năm, trường hợp nổi bật sẽ được xét tăng lương ngay tại thời điểm.\n\n- Chế độ nghỉ phép: 12 ngày nghỉ phép có lương mỗi năm theo quy định – nghỉ thoải mái, vẫn nhận lương đầy đủ.\n- Sự kiện nội bộ ấm áp: Hàng năm tổ chức “Ngày hội gia đình” vào tháng 5, có quà tặng bằng tiền mặt dành tặng ông bà, cha mẹ, vợ/chồng và con cái của nhân viên – thể hiện sự trân trọng với cả gia đình bạn.\n- Chế độ quà tặng nhân dịp đặc biệt: Tặng quà các ngày lễ: Tết Dương lịch, Tết Âm lịch, 30/4, Trung thu, 8/3, 20/10.\n- Cả nhân viên nam và nữ đều có quà.\n- Nhân viên chính thức trên 6 tháng được tặng quà sinh nhật trị giá 5 triệu đồng/người.\n- Thưởng hiệu suất riêng: Ngoài lương chính còn có các khoản thưởng, bonus hàng tháng tùy theo đóng góp.\n- Hỗ trợ nơi ở: Nhân viên ở xa được sắp xếp chỗ ở miễn phí, thuận tiện cho công việc.\n- Cơ hội học hỏi và phát triển: Làm việc cùng các chuyên gia hàng đầu trong nước và quốc tế.\n- Giao lưu, học hỏi với đồng nghiệp quốc tế giúp cải thiện tiếng Anh và mở rộng tư duy toàn cầu.\n- Chăm sóc sức khỏe toàn diện: Khám sức khỏe định kỳ tại các bệnh viện quốc tế như BV Phương Đông.\n- Miễn phí tiêm phòng HPV, cúm cho nhân viên.\n- Trải nghiệm công tác và du lịch: Các chuyến công tác nước ngoài kết hợp du lịch, khám phá đặc sản và địa danh nổi tiếng.\n- Được tài trợ các hoạt động gắn kết team, học hỏi kiến thức lập trình qua các buổi giao lưu, workshop.\n- Văn phòng hiện đại, tiện nghi: Không gian làm việc rộng rãi, thoáng mát.\n- Có bánh, trà, café phục vụ mỗi ngày.\n- Bữa trưa đầy đủ dinh dưỡng, ngon miệng dành riêng cho nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'B4-12 Vinhomes Gardenia Hàm Nghi, Đường Hàm Nghi, Phường Cầu Diễn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(232, 206, 2, 'Senior QA Engineer', 'Top 3 reasons to join us\n1. Attractive remuneration package with 18 days off\n2. Smart people, interesting project & swiss quality\n3. Travel opportunities to Switzerland\n\nJob description\n- Key role in releasing the best deliverables to the customers\n- Review and clarify software requirement specification \n- Execute manual test cases\n- Design and maintain manual test plan, test cases and test strategies\n- Regularly review, and improve quality of the test plan, and test cases\n- Identify and propose areas where test coverage can be improved\n- Develop, implement and maintain automation tests for streamlining the testing process using Selenium or other tools.\n- Design, build code base, refactor and extend automation code framework when necessary\n- Regular review and improve automation code quality\n- Identify and propose areas where automation can improve quality\n- Analyze and report defects, support reproducing and analyzing root causes of defects.\n- Report, track, and monitor defects in the defect tracking system\n- Address issues relating to testing quality\n- Communicate progress, test results to Test Lead\n- Implement of extensive practical experience, and coach other testers.\n\nYour skills and experience\n- At least 4 years experienced in QC role\n- Strong experience of testing methodology and testing tools\n- Experience in designing test cases based on requirements.\n- Experience in designing automation test code based on requirements and software code\n- Ability to effectively manage time, and individually prioritize multiple tasks of competing priority\n- Good oral and written communication skills\n- Strong passion for IT software and testing\n- Experience with Agile based testing approaches\n- Research/ experience with automation testing is a strong plus\n- Research/ experience with manual testing\n\nWhy you\'ll love working here\n- Professional European-based company\n- Attractive salary\n- Performance bonus of up to 4 months‘ salary\n- Opportunities for travel to Europe\n- Hybrid home/office working model\n- Flexible working time\n- Structured training & development roadmap\n- Good work-life balance\n- Premium healthcare insurance\n- Loyalty programs\n- Well-being activities\n- Annual company trips and team-building events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CII Building, 152 Điên Biên Phủ, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(233, 207, 2, 'Automation QA Engineer', 'Top 3 reasons to join us\n\n1. Lộ trình phát triển sự nghiệp đa chiều\n2. Cơ hội đào tạo, công tác tại Nhật, Singapore, Mỹ..\n3. Mức lương hấp dẫn, chế độ thưởng dựa trên năng lực\n\nJob description\nEnsure quality of products\n• Analyze manual test cases to clarify which parts can be automated.\n• Develop/verify test cases using framework Selenium or UI Path or Playwright\n• Execute test cases and analyze results to summary about quality of system\n• Communicate with other project stakeholders to ensure the quality of the functions/modules which you are assigned to\n• Manage an automation test team including planning, estimation, reviewing source code, reviewing test results, reports\n\nYour skills and experience\n[General requirements]\n• At least 2 years experienced in automation test development\n• Experienced develop automation script for desktop app, know UI Path is plus.\n• Experienced in programming languages like C#, Javascript, typesript is plus.\n• Experience in testing framework: JUnit5, TestNG…\n• Experience in CI/CD tools such as Jenkins or similar.\n• Experience in Docker or VM is a plus\n• Experience in leading an automation team is a plus.\n• Experienced in management tools such as JIRA, Redmine.\n• Logical thinking, Self-learning and Self-motivated & proactive.\n• English skills: Good at speaking, reading, writing.\n[Preferred requirements]\n• Have testing in Web/Factory/IoT domain\n• Have automation testing skill/experience\n• Have software development skill/experience\n• Have Japanese skill\n• Good understanding of software development life cycle & common using software development process: CMMI, Agile …\n• Have ISTQB certificate\n\nWhy you\'ll love working here\nPanasonic R&D Center Vietnam was established in April 2007, is a company specializing in R&D of Panasonic Group in Vietnam with the aim of enhancing R&D activities in the field of digital home appliances, automation, mobility in Vietnam, providing R&D services for software solutions in today\'s hottest fields such as AI, Cloud, IoT in a chain of R&D centers of worldwide corporations\n1. Career Path Development\n• Long-term multi-career roadmap;\n• Learning & development (Language Training, Technical Training, Soft-skill Training, On-job Training, etc.)\n• Oversea business trips (Japan, China, Singapore, US, Mexico, EU, etc.)\n2. Work-life Balance\n• Flexible working time that supports work-life balance (Core time: 9:00-16:00; 5 days from Monday - Friday/ week)\n• Additional special holiday\n3. Compensation package\n• Attractive salary \n• Competitive bonus package depend on abilities, performance and competencies\n• Diversified allowance scheme\n4. Wellness\n• Well-protected with 24/7 personal accident and medical care insurance;\n• Well-designed Annual Health Check-up program;\n5. Activities\n• Team-building activities; Birthday Party; Year-end party; Sport Day/ Family Day\n• Summer Vacation (Trip to famous tourist spots domestic/ overseas,…)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lotte Tower, 54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(234, 208, 2, 'QA - Middle / Senior', 'Droppii are seeking an experienced Medior/Senior Quality Assurance professional to take ownership of testing on our products. As a Quality Assurance Specialist, you will design test plans, test suites, and test cases, ensuring the delivery of comprehensive test coverage for each sprint and regression. Additionally, you will be responsible for generating test summary reports with valuable statistical insights.\n\nResponsibilities\nTake ownership of testing activities on the our products.\nDesign effective test plans, test suites, and detailed test cases.\nEnsure timely delivery of test cases for every sprint and regression cycle.\nGenerate comprehensive test summary reports, highlighting key statistics.\nCollaborate closely with the application team to adapt test cases for changes in the application.\nFacilitate integration testing and regression testing using test scripts.\nEffectively communicate and collaborate with the global team, resolving issues that impact timelines.\n\nYour skills and experience\nMinimum of 3 years of experience in software testing.\nProficiency in testing Web, Mobile and Restful API applications.\nStrong skills in creating test plans and test cases using various testing techniques.\nExcellent understanding of Software Development Life Cycle (SDLC) and quality processes.\nFamiliarity with industry-standard test and defect management tools.\nKnowledge of programming languages is desirable.\nExperience with a Playwright is a plus.\nExperience with Continuous Integration (CI) tools is a plus.\n\nWhy you\'ll love working here\nEngaging and challenging work environment, focusing on the exciting domain of eCommerce.\nHybrid working model with flexible hours.\nEmployee Stock Ownership Program (ESOP): Enjoy the opportunity to be a company stakeholder through our ESOP, fostering a sense of shared success and ownership.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '39A Ta Hien street, Quarter 1, Thanh My Loi Ward, District 2, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(235, 209, 2, 'Senior Android Software Engineer (Kotlin) - Up to $3000', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\n\nJOB OVERVIEW\nDevelop Automotive In-Vehicle Infotainment system for the next generation luxury vehicles based on latest version of Google Android Automotive. Joining the project, you will have chance to facing with cutting-edge technology such as connected-car, hypervisor.\n\nRESPONSIBILITIES\nParticipate in the design, coding and testing of software for MHU equipment (Infotainment system)\nCoding and fixing issues of Android application on MHU\nCoding and fixing issues for information, entertainment, intelligence and connectivity features on MHU\n\nYour skills and experience\nBasic Qualifications\nMinimum 3 years of experience developing Kotlin on Android.\nGood knowledge in Kotlin and Android development environment: Activity, Fragment, Service, Customize View UI Layout, Animation (Property, View, Drawable), Jetpack Architecture component.\nHave experience with design patterns like MVC, MVP, MVVM.\nExperience with designing layouts to support multiple screen sizes and densities and handling localization support.\nExperience with version control tools like SVN and GIT.\nAndroid application development tools and environments (Android Studio).\n\nNice to have\nHaving knowledge of Android AOSP and Android Automotive\nHaving knowledge of SOLID, Design patterns\nHaving knowledge and experience with Agile Software Development frameworks.\nExperience with performance and memory optimization.\nFamiliarity with Inter Process Communication (IPC) to connect between processes in Android.\n\nWhy you\'ll love working here\nCompetitive salary. Bonus based on performance.\nFPT Care insurance plan tailored for FPT employees\nAttractive annual summer vacation allowance\nSponsored training courses for personal growth and up to 100% coverage for certification costs\nGlobal and inclusive workplace with monthly cross-cultural events\nInternational exposure and career growth across global locations\nWork-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Building, 17 Duy Tân Str., Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(236, 210, 2, 'Database Operations Engineer (DataOps)', 'Shinhan DS, a company that allows developer to realize their own dream by lavishing on provide work environment for development and stable employment.\n\nShinhan DS is responsible for the ICT related business for the Shinhan Financial Group.\nFounded in 1991, Shinhan DS provided a systematic IT service including System Management(SM), System Integration(SI), IT consulting and e-biz within the financial group, such as the bank, card and securities, accelerated the Digital Transformation to maximize customer satisfaction and achieve continuous development through the trust and support of customers.\n\nBased on its experience and capability through the best IT service, Shinhan DS is concentrating on the Southeast Asia market, the core of the global network.\nIts local subsidiary \'Shinhan DS Vietnam\' was founded in May 2018, promising a new leap to grow as a global ICT corporation.\n\nWe are looking for Database Operations Engineer\n\nKey Responsibilities:\n- Install and configure various database systems on client sites.\n- Provide on-site technical support and maintenance for deployed database environments.\n- Assist in initial system setup, basic troubleshooting, and issue resolution.\n- Communicate effectively with clients and internal teams for service delivery.\n\nYour skills and experience\nRequired Qualifications:\n- Bachelor’s degree in Computer Science, Information Technology, or a related field.\n- Basic understanding and hands-on experience with database installation, configuration, and issue handling.\n- Minimum of 5-14 years of relevant experience.\n- Intermediate English proficiency or above for effective communication.\n\nPreferred Qualifications:\n- Oracle certification holders preferred (especially OCP).\n- Experience in operating middleware systems (WEB/WAS) is a plus.\n- Familiarity with database systems across different OS environments (Linux/Windows, etc.).\n- Strong communication skills and a proactive, service-oriented mindset.\n\nWhy you\'ll love working here\nOur company provides an opportunity to grow as an expert-Banking IT in Vietnam.\nYou can learn about Banking concepts and know-how from Korea specialized developers.\nIn addition, We have plans to expand our company to Indonesia, Myanmar, Philippines.\nWe plan to offer training for outstanding employees in Korea.\n\nBenefits:\n- Salary: you will be happy.\n- Performance review: twice a year.\n- Incentive Programs to congratulate members\' development.\n- Company Trip, monthly/weekly activities and events.\n- Health check once a year and advanced healthcare program.\n- Free snack, coffee, sponsored pizza or chicken & beer parties.\n- Work onsite with foreign teams for short or long term.\n- Your solutions and opinions are heard.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 3, The Mett Tower, 15 Tran Bach Dang Street, Thu Thiem Ward,, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(237, 211, 2, 'Chuyên viên Hỗ trợ ứng dụng', '1. Vận hành ứng dụng Công nghệ Thông tin:\n- Thực hiện vận hành, giám sát hàng ngày và bảo trì các ứng dụng để đảm bảo vận hành hệ thống ổn định và hiệu quả\n- Xây dựng tài liệu hướng dẫn vận hành hệ thống\n\n2. Hỗ trợ ứng dụng Công nghệ Thông tin:\n- Hỗ trợ các bộ phận nghiệp vụ trong việc xử lý lỗi/sự cố hàng ngày ở cấp độ 2\n- Phân tích các lỗi xảy ra ở môi trường Product, theo dõi các giải pháp xử lý lỗi từ đội dự án hoặc đối tác để phản hồi kịp lúc cũng như đảm bảo xử lý đúng tiến độ\n- Thu thập, đánh giá nhu cầu sử dụng của người dùng và theo dõi, cung cấp thông tin năng lực của các ứng dụng tương ứng để lập kế hoạch bổ sung và quy hoạch năng lực xử lý cho các ứng dụng\n- Xác định mức độ sẵn sàng của ứng dụng/giải pháp khi tiếp nhận vận hành để đảm bảo hệ thống đủ điều kiện hoạt động\n\n3. Giám sát ứng dụng Công nghệ Thông tin:\n- Kiểm tra, giám sát vận hành và phát hiện các cảnh báo phát sinh của các hệ thống\n- Thực hiện xử lý khi có cảnh báo phát sinh của các hệ thống\n- Rà soát, cập nhật tiêu chí cho các loại cảnh báo để đảm bảo hệ thống giảm sát hoạt động đúng với hiện trạng thực tế\n\n4. Hỗ trợ các công việc khác trong bộ phận theo phân công\n- Thực hiện các công việc hỗ trợ dự án:\n+ Tiếp nhận vận hành hệ thống từ giai đoạn kiểm thử (UAT)\n+ Hỗ trợ dự án xây dựng bộ tài liệu bàn giao vận hành hoàn chỉnh\n+ Tham gia nghiên cứu, vận hành các dự án liên quan đến công nghệ mới (Cloud, DevOps…)\n- Thực hiện các công việc hỗ trợ khác trong bộ phận:\n+ Hỗ trợ lập kế hoạch năm cho nhóm\n+ Hỗ trợ xây dựng, cập nhật danh mục dịch vụ hỗ trợ tiêu chuẩn, tài liệu cho người sử dụng\n+ Đề xuất và hỗ trợ xây dựng các công cụ, quy trình, giải pháp nâng cao hiệu quả hoạt động\n+ Hỗ trợ hướng dẫn, kèm cặp vị trí chuyên viên xử lý các vấn đề phức tạp\n+ Thực hiện một số công việc khác theo phân công của Trưởng bộ phận.\n\nYour skills and experience\n- Tốt nghiệp đại học chính quy chuyên ngành Công nghệ thông tin;\n- Có 1 năm kinh nghiệm trở lên ở vị trí tương đương;\n- Có kinh nghiệm về Splunk, Solarwinds, K8S;\n- Có khả năng suy luận, tư duy logic về phân tích log, phân tích hệ thống, kỹ năng giải quyết vấn đề;\n- Có khả năng giao tiếp hiệu quả, làm cầu nối giữa đối tác triển khai, nhà cung cấp giải pháp, các nhóm nội bộ và các bộ phận người dùng khác;\n- Có khả năng làm việc độc lập, định hướng công việc chuyên môn cho nhóm;\n- Đọc hiểu tốt các tài liệu kỹ thuật bằng tiếng Anh, giao tiếp cơ bản;\n- Ưu tiên ứng viên:\nCó kinh nghiệm về lập trình;\nCó kinh nghiệm về Application Performance Monitoring hoặc Digital Experience Monitoring;\nCó kinh nghiệm về Cloud Monitoring;\nCó kiến thức về ITIL, ITSM;\nCó kinh nghiệm làm việc trong lĩnh vực tài chính, chứng khoán.\n\nWhy you\'ll love working here\nChứng khoán SSI nhận 3 giải thưởng nơi làm việc tốt nhất:\nHighly competitive remuneration package: Attractive monthly salary, 13th month salary, KPIs cash bonus, Public holiday cash bonus, Birthday gift, Lunar new year gift,...\nPremium AON healthcare insurance and full labor insurance\n12 days Annual leave + 2 days sick leave with full paid\nLuxury team-building trip and varied engagement activities\nJoining the leisure clubs: Football, E-Sport, Running, Gym, Yoga....\nFully sponsored training to build your career\nProfessional, open minded and supportive working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Dali Tower - 24c Phan Dang Luu, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(238, 212, 2, 'Software Developer', 'We are looking for a bilingual (Vietnamese / English) highly motivated and detail-oriented Software Developer to join our dynamic engineering team. In this role, you will be responsible for the end-to-end development of robust, scalable, and efficient software applications that directly contribute to our company’s success and customer satisfaction.\n\nAs a Software Developer, you will play a key role in designing system architecture, writing clean and maintainable quality code, and collaborating with cross-functional teams to implement innovative solutions. You will have the opportunity to work on a variety of projects—from enhancing existing systems to building new platforms and services from the ground up.\n\nThis position is ideal for someone who thrives in a fast-paced, agile environment and enjoys solving complex technical challenges. You should be comfortable working across the full software development lifecycle, from gathering requirements and designing features to testing, deployment, and maintenance. Strong problem-solving skills, a passion for technology, and a commitment to continuous learning are essential to thrive in this role.\n\nWhether you\'re developing backend APIs, creating intuitive front-end interfaces, or integrating with cloud services, your contributions will help shape the future of our technology stack and deliver value to our organization.\n\nKey Responsibilities:\n• Design, build, test, and deploy software applications and services.\n• Write clean, scalable, and maintainable code using frameworks such as JS, jQuery, Angular, Xamarin, SQL, SOQL, VB, XML Python, Java, JavaScript, C#, .NET, React.\n• Participate in code reviews, debugging, and troubleshooting to ensure high performance and reliability.\n• Collaborate with designers, product managers, QA, and other developers to define and deliver solutions that meet business goals.\n• Continuously learn and apply best practices in software development, security, and performance optimization.\n• Document software functionality and assist with user or system documentation when necessary.\n\nYour skills and experience\n• Bachelor\'s degree in Computer Science, Software Engineering, or a related field (or equivalent experience).\n• Familiarity with AI tool sets and LLM’s.\n• 3 to 5 years of hands-on experience in software development.\n• Strong understanding of algorithms, data structures, and software design principles.\n• Familiarity with source control tools like Git and CI/CD practices.\n• Experience working in agile/scrum development environments.\n\nPreferred Qualifications:\n• Experience with cloud platforms such as AWS, Azure, or Google Cloud.\n• Familiarity with containerization (e.g., Docker, Kubernetes).\n• Knowledge of relational or NoSQL databases (e.g., MySQL, PostgreSQL, MongoDB).\n• Exposure to unit testing and test-driven development (TDD).\n• Understanding of RESTful APIs and microservices architecture.\n\nWhy you\'ll love working here\n• Performance bonuses End Year Bonus.\n• Health insurance.\n• Professional development budget.\n• Provide laptops and necessary equipment for work.\n• May require some local and international travel.\n• Collaborative, inclusive team culture.\n• Yearly team building.\n• Flexible hours and remote work options.\n• Salary Adjustment 2 time/ year.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '196A Nguyen Van Huong, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(239, 213, 2, '[Fresher] AI/Machine Learning Engineer (Grit, Python)', 'At EATLAB, we\'re a team that is hardworking, smart, and fast to take action. We don’t care what your degree is. If you’re logical (no bullshit) and hardworking (almost a workaholic), this is the place for you. We do not accept anything mediocre. Quality of work is important. Even if you cannot achieve perfection at the beginning, we value efforts to strive toward it. Our product is an AI system that catches fraud and rewards efforts. We especially welcome candidates from Math, Physics, Nuclear Engineering, and related fields.\n\nYou Should Apply If\n- You loveeeeee working, not (only) for money, but because you love to make something incredible\n- You always learn new things every day\n- You hate corruption & fraud to the bone\n- Know how to ask a question\n\nWhat You’ll Be Doing\n- Build, test, and improve AI/ML models with a focus on real-world applications\n- Evaluate model performance and identify opportunities to improve accuracy, speed, and reliability\n- Work with data — from preprocessing to fine-tuning, including images for computer vision tasks\n- Collaborate with a small, focused team — we value clear thinking, not loud talking\n- Deploy AI models to production, optimize inference, and contribute to system scalability\n- Contribute to monthly release cycles and iterate fast based on real user feedback\n\nYour skills and experience\nMust-Haves\n- Knowledgable in your applied field and always updating your knowledge\n- If you have a direct experience, it\'s a plus (but if not, it\'s ok)\n- If you love technology, you will have a lot of fun\n- Learning is what you do everyday\n- We build fraud detection systems (so cool!!)\n- The CEO got a PhD from MIT (with GPA 4.0 all her life).\n- Happy and good attitude\n- Understand life – happiness and sufferings are a part of life\n- We got free snacks all day\n- Easy going, not too picky. Can enjoy colleagues at work\n- If you continue to develop yourself, your salary is subjected to increase twice a year (only if you improve)\n- We are building a team of avengers – small team of incredibly capable people. The more revenue we generate, the more it will come back to you. But it will be no easy work!\n- If you accept all of the above, click apply.\n- PS. We want someone with a fighting attitude. If you give up easily, DO NOT apply.\n\nKnowledgable In\n- Computer vision — classification, detection, segmentation\n- API development (e.g. Flask, FastAPI)\n- Math-heavy disciplines — linear algebra, statistics, optimization\n\nWhy you\'ll love working here\n- Be part of a mission-driven team fighting fraud and rewarding real contribution\n- Grow fast with biannual performance reviews and lots of ownership\n- Get annual health checkups and an international trip with the team\n- Learn from world-class mentors — including an MIT founder with multiple exits\n- Work with teammates who value depth, honesty, and grit.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vinhomes Central Park, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(240, 214, 2, 'Software Security Engineer (Linux, Embedded)', 'Top 3 reasons to join us\n- Competitive salary & up-to 16-month income / year\n- Attractive allowances & benefits\n- Hybrid Working & Flexible working time\n\nJob description\n- Guide Secure SW Development Methologies to Developers (Threat Modeling, TARA, CVSS, etc)\n- Security Design & Review for the Embedded SW (To ensure the security of the SW modules, design together with the dev teams and review team\'s outputs.)\n- Design and Implement for System Hardening (incl. OS Hardening, Memory Hardening)\n- Implement Test Cases to Verify System Security Requirements\n- Manage CVEs in used Open Source SW\n\nYour skills and experience\n- Bachelor\'s degree in computer science / engineering or equivalent practical experience\n- 3+ years of experience in SW Security \n- Understanding for Cybersecurity Engineering (NIST CSF/RMF, threat modeling, TARA, and etc)\n- Understanding for the embedded Linux environment and system hardening\n- Good communication skill in English, mostly for the technical communication with the collaborating scrum teams\n\nWhy you\'ll love working here\n- 13th month salary + Incentive bonus (Total remuneration package / year: up to 16-month salary) + Annual salary review; 100% salary in probation\n- HYBRID WORKING, flexible working time (Mon - Fri)\n- Support for lunch, transportation and other allowances (Coding Expert, Technical leader, phone...);\n- Premium health care & accident insurance;\n- Total 20 days off (12 days of annual leave & additional 8 days of company holidays: Summer holiday, Mid-Autumn, Christmas, LG and VS DCV Foundation Days);\n- Support fee to get TOEIC & technical certifications (ISTQB, Agile Scrum...);\n- On-site & training opportunities abroad;\n- Company trip, sport clubs (zumba, football, pingpong, badminton,...);\n- Monthly budget for team activities, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 17 đến tầng 21, Tòa văn phòng, Lotte Mall Hà Nội, Số 272 Võ Chí Công, Phường Phú Thượng, Quận Tây Hồ, Thành phố Hà Nội, Tay Ho, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(241, 215, 2, 'Frontend Developer (JavaScript/  HTML/  CSS)', 'Phát triển giao diện người dùng từ thiết kế (HTML, CSS, JavaScript).\nTối ưu hóa hiệu suất và đảm bảo giao diện đáp ứng (responsive).\nĐảm bảo tương thích trên các trình duyệt.\nPhối hợp với đội ngũ backend để tích hợp API và đảm bảo trải nghiệm người dùng mượt mà..\nNghiên cứu và áp dụng công nghệ front-end mới.\n\nTối thiểu 2 năm kinh nghiệm làm việc ở vị trí Front-End Developer.\nThành thạo HTML5, CSS3 (bao gồm CSS preprocessors như Sass, Less) và JavaScript (ES6+).\nKinh nghiệm với React, Angular hoặc Vue.js.\nQuen thuộc với Git và có kỹ năng làm việc nhóm và độc lập tốt.\nCó kiến thức cơ bản về UI/UX principles và best practices.\nCó tư duy logic tốt và khả năng giải quyết vấn đề hiệu quả.\nƯu tiên ứng viên có kinh nghiệm làm việc trong lĩnh vực công nghệ, giải trí hoặc truyền thông.\nƯu tiên ứng viên có kinh nghiệm với các công cụ build và quản lý dự án frontend\nƯu tiên ứng viên có kinh nghiệm viết unit test và integration test cho front-end.\n\nLương Net 20M - 35M + Phụ Cấp + Thưởng (Thỏa thuận theo năng lực)\nLương tháng 13. Xét tăng lương hàng năm dựa trên năng lực và kết quả làm việc\nCác chế độ khác:\n- Nghỉ phép 12 ngày, nghỉ bệnh, bảo hiểm y tế và bảo hiểm xã hội…theo Luật Lao động Việt Nam, du lịch hàng năm.\n- Được cấp thiết bị theo yêu cầu công việc.\nThời gian làm việc:\n- Từ Thứ 2 đến Thứ 6: từ 8:30 đến 17:30, (nghỉ trưa 12:00-13:30)\n- Thứ 7 làm việc từ 8:00 đến 12:00.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Sun Avenue, 28 Mai Chí Thọ, P.An Phú, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(242, 216, 2, '15 [Middle/Senior] Fullstack (Java, Python, ReactJS)', 'Top 3 reasons to join us\n• Môi trường làm việc đa quốc gia\n• Cơ hội thăng tiến, phát triển bản thân\n• Trải nghiệm làm việc tại Nhật Bản/ Âu Mỹ\n\nJob description\n• Phát triển và duy trì các ứng dụng web với kiến trúc fullstack, sử dụng Java hoặc Python cho backend và các framework hiện đại cho frontend.\n• Thiết kế và xây dựng các RESTful API để giao tiếp giữa các dịch vụ.\n• Xây dựng giao diện người dùng động và phản hồi tốt bằng các framework như ReactJS, Angular hoặc VueJS.\n• Quản lý cơ sở dữ liệu quan hệ và/hoặc NoSQL (MySQL, PostgreSQL, MongoDB, Redis).\n• Đóng gói ứng dụng bằng Docker để đảm bảo môi trường phát triển và triển khai nhất quán.\n• Thiết lập và giám sát tình trạng hệ thống bằng các công cụ logging và alerting hiện đại.\n• Làm việc trong môi trường Agile/Scrum với các công cụ quản lý dự án như JIRA.\n• Phối hợp chặt chẽ với các team khác (BA, QA, DevOps, khách hàng...) để đảm bảo chất lượng và tiến độ sản phẩm.\n\nYour skills and experience\n• Tốt nghiệp Đại học, cao đẳng chuyên nghành Công nghệ thông tin, hoặc các chuyên ngành liên quan\n• Có từ 3–6 năm kinh nghiệm phát triển phần mềm, trong đó ít nhất 2 năm kinh nghiệm với Java hoặc Python.\n• Thành thạo một trong các kết hợp công nghệ sau:\n  • Java (Spring Boot, v.v) + Frontend (ReactJS / Angular / Vue)\n  • Java + Python (Flask / FastAPI / Django)\n  • Python + Frontend (ReactJS / Angular / Vue)\n• Hiểu rõ về RESTful API, kiến trúc microservices, authentication/authorization.\n• Có kinh nghiệm làm việc với cơ sở dữ liệu quan hệ (MySQL, PostgreSQL) và/hoặc NoSQL (MongoDB, Redis).\n• Có kỹ năng viết unit test, sử dụng Git, CI/CD. ◦ Kỹ năng giao tiếp và làm việc nhóm tốt.\n\nƯu tiên:\n• Có kinh nghiệm làm việc trong các dự án outsource hoặc khách hàng Hàn Quốc.\n• Có kinh nghiệm với DevOps (Docker, Kubernetes) là một lợi thế.\n• Kỹ năng làm việc nhóm tốt, chủ động và tinh thần trách nhiệm cao.\n• Ưu tiên ứng viên có khả năng giao tiếp tiếng Anh cơ bản trở lên.\n\nWhy you\'ll love working here\n• Mức lương: Thỏa thuận theo năng lực khi phỏng vấn.\n• Chế độ phúc lợi:\n  • Lương tháng 13+ và xét tăng lương 2 lần/năm. Thưởng theo dự án, thưởng lễ/tết, thưởng giới thiệu nhân sự, thưởng hiệu quả công việc...\n  • Phụ cấp thâm niên từ 2 năm làm việc.\n  • Tham gia các hoạt động đào tạo nội bộ và bên ngoài, phát triển lộ trình nghề nghiệp rõ ràng.\n  • Nghỉ thứ 7, Chủ nhật và 12 ngày phép/năm.\n  • Tham gia các câu lạc bộ thể thao – văn hóa – nghệ thuật do công ty tài trợ (bóng đá, cầu lông, bơi lội, âm nhạc, game, tiếng Anh…).\n  • Chăm sóc sức khỏe: Khám sức khỏe định kỳ, bảo hiểm sức khỏe chất lượng cao Rikkei Care.\n  • Văn hoá thoải mái: Âm nhạc hàng ngày, trái cây tươi, team building thường xuyên, du lịch trong và ngoài nước.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 18, tòa nhà Vinacomin, 3 Dương Đình Nghệ, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(243, 217, 2, 'Senior Engineering Manager(Golang, Python, Next.js, ML)', 'About Us\nReforged Labs is a YC-backed, Sandhill Road funded AI startup revolutionizing how the world\'s top mobile gaming studios market themselves to hundreds of millions of players. We\'re building cutting-edge AI technology that powers sophisticated ad analysis and generation pipelines for elite global gaming companies. \nWe don\'t follow trend; we set them. Our engineering team builds solutions that rival the best Silicon Valley has to offer, creating technology that generates millions of dollars in value for our customers.\n\nThe Role \nWe\'re seeking an exceptional Engineering Manager to lead our growing technical team in Ho Chi Minh City. This is not a role for the average manager; we\'re looking exclusively for extraordinary talent who can drive high-performing engineering teams to deliver world-class technology. You\'ll lead a talented team of engineers across frontend, backend, and ML specialties, establishing engineering excellence while maintaining our rapid pace of innovation. Your leadership will directly impact how hundreds of millions of players discover and experience games through our AI-powered platforms.\n\nCore Responsibilities\n● Lead, mentor, and develop a high-performing engineering team of 6-9 engineers working on cutting-edge AI technologies \n● Drive sprint planning, execution, and delivery of our product roadmap with exceptional velocity \n● Establish and refine engineering processes that maintain quality while enabling rapid iteration \n● Oversee technical standards and architectural decisions across our AI-driven platforms \n● Collaborate with the CTO and CPO to translate business requirements into technical implementations \n● Identify and eliminate blockers to progress, keeping delivery timelines on track \n● Foster a culture of engineering excellence, continuous learning, and knowledge sharing \n● Conduct effective 1:1s and performance reviews to develop and retain top talent \n● Participate in technical decisions for our agentic workflows and AI systems\n\nYour skills and experience\nRequired Experience \n● 5+ years of software engineering experience with at least 2-3 years in a leadership role \n● Strong experience with modern technology stacks, ideally including Golang or similar backend technologies \n● Track record of managing engineering teams that consistently deliver high-quality software on time \n● Experience implementing engineering processes in a fast-paced environment \n● Demonstrated ability to balance technical excellence with business priorities \n● Experience managing senior engineers and fostering their growth \n● Understanding of AI/ML integration and workflow systems \n● Experience with agile development methodologies and sprint management \n● Professional English communication skills (Vietnamese language skills welcome) \n\nEssential Qualities \n● Leadership presence that inspires confidence and commitment from technical teams \n● Strategic thinking balanced with operational excellence and attention to detail \n● Strong communicator who can translate between technical and business stakeholders \n● Data-driven approach to measuring team performance and productivity \n● Ability to make difficult decisions and trade-offs to maintain delivery momentum \n● Problem-solver who thrives in a fast-paced startup environment \n● Passion for building and developing high-performing engineering teams \n● Comfort with ambiguity and rapid change in a growing company\n\nInterview Process \nOur thorough 3-week interview process is designed to evaluate both your leadership abilities and technical acumen: \n1. Technical Founder Assessment \n○ Leadership philosophy and approach \n○ Technical background discussion \n○ Real-world engineering challenges \n\n2. Leadership & Delivery Excellence \n○ Panel with senior engineers on technical leadership \n○ Solution presentation to a real engineering challenge \n○ Team scaling and management scenarios \n\n3. Executive Assessment \n○ Vision alignment with CEO \n○ Technical strategy discussion with CTO \n○ Culture fit and mutual expectations\nWe focus on evaluating your leadership capabilities, technical credibility, delivery excellence, cultural fit, and growth potential throughout this process. Our goal is to create a two-way dialogue that helps both of us determine if this critical role is the right fit.\nWe aim to complete the entire process within 3 weeks and provide timely updates at each stage.\nNote: This role is designed for elite engineering managers. If you\'re not consistently recognized as a leader who can build and drive high-performing technical teams, this position is likely not a good fit. We\'re looking for candidates who can demonstrate outstanding leadership abilities and deliver outsized impact.\n\nWhy you\'ll love working here\nWhy You\'ll Love Working Here\n• Industry-leading compensation package\n• Work on technology that is genuinely world-class and cutting-edge, not just by local standards\n• Build products that compete globally and set new industry standards\n• Compensation package targeting top-tier engineers (significantly above local market rates)\n• Opportunity to be an early engineer at a rapidly growing, well-funded AI startup\n• Direct impact on products used by major gaming studios reaching hundreds of millions of users\n• Potential for international recognition and career advancement opportunities\n• Challenging, fast-paced environment that will accelerate your professional growth\n• Collaborative culture where your ideas matter and technical excellence is valued\nOur Engineering Culture\n• We operate in agile sprint cycles with a focus on rapid iteration and continuous delivery. Our\nteam values independence and ownership, with each engineer taking full responsibility for their features from architecture to production deployment.\n• We maintain high standards for code quality while moving quickly to meet market demands. We are building a culture that combines Silicon Valley engineering practices with exceptional local talent.\n• Located in Ho Chi Minh City, we\'ve created a work environment that combines Silicon Valley engineering practices with local talent, offering the unique opportunity to work on global-scale problems while being part of Vietnam\'s growing tech ecosystem.\n• We are an equal opportunity employer and value diversity at our company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 , 2 Thi Sách, Phường Bến Nghé, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(244, 218, 2, 'Hybrid QA Engineer (Automation Test/QA QC/JavaScript)', 'We are looking for a Senior Automation QA Engineer with strong programming and testing skills to join our dynamic team. You will be responsible for developing and maintaining automated test scripts, analyzing results, identifying issues, and continuously enhancing our automation frameworks and processes. This is a great opportunity to grow your career in a friendly and professional environment.\n\nKey Responsibilities\n- Develop and execute automated test scripts for web, mobile, and API testing.\n- Analyze test results, report defects, and collaborate with the team to resolve issues.\n- Improve and maintain automation test frameworks and infrastructure.\n- Collaborate with cross-functional teams to enhance testing strategies in Agile environments.\n- Document and report test execution results in a clear and timely manner.\n- Maintain test data to ensure consistent and reliable test runs.\n\nYour skills and experience\n- 3+ years of experience in automation testing\n- Proficient in one of these language JavaScript/TypeScript/Java/Python…with solid experience writing automation scripts.\n- Experience with automation tools like Selenium, Playwright, Cypress, or Testcafe.\n- Hands-on experience with test frameworks like Mocha or TestNG.\n- Understanding of software testing principles and best practices.\n- Experience working in Agile development environments.\n- Strong analytical and problem-solving skills.\n- Familiarity with Git, CI/CD tools like Jenkins.\n- Intermediate or higher English skills (spoken and written) preferred.\n- Daily communication with international customers in English is a plus.\n\nWhy you\'ll love working here\n- We\'re always looking for candidates with talent and we know choosing a place is also so difficult for you. Therefore, let us give you some extra reasons to join us:\n- Numerous opportunities for personal and professional growth.\n- Competitive salary, bonuses, and allowances.\n- 13th-month salary.\n- Performance reviews once per year.\n- Social & health insurance, annual leave, and working conditions are compliant with Vietnamese labor laws.\n- Flexible working hours and modern working processes.\n- Free in-house coffee and English courses.\n- Annual health check-up.\n- Friendly, young, and dynamic team with regular fun activities: Football club, birthday parties, happy hours, team building events, company trips, year-end party, and more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Elinext Building, 37A Phan Xich Long, Ward 3, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(245, 182, 2, 'Data Engineer - Digital Banking (Python, SQL Database)', 'TymeX is building some of world\'s fastest growing digital banks and the data team plays a key role in driving the bank’s vision of creating a platform that stimulates economic participation and facilitates broader financial inclusion by implementing creative best in class data and analytic solutions to achieve success in providing quality services and products to our customers and optimising the business.\n\nAs a Data Engineer you will contribute to the mission by creating solutions that will directly support informed decision-making and innovation by providing clean, protected, quality and auditable data from various sources into fit for purpose data products.\n\nIn this role, you can expect to:\n- Design, develop, test, deploy and monitor data pipelines in Databricks on AWS from a wide variety of data sources.\n- Design, develop, test, deploy and monitor scalable code with PySpark and SQL in Databricks.\n- Identify opportunities to improve internal process through code optimisation and automation.\n- Build data quality dashboards, lineage flows / and or monitoring tools to utilize the data pipeline, providing active monitoring and actionable insight into overall data quality and data governance.\n- Assist in migrating data from legacy systems onto newly developed solutions.\n- Follow and lead best practices on all data security, retention, and privacy policies.\n\nYour skills and experience:\n- Bachelor’s degree.\n- 5+ years’ experience of building ETL/ELT pipelines.\n- Proven competency in solution design, development, implementation, reporting and analysis.\n- Proficiency in Apache-Spark, Python and SQL languages.\n- Proficiency in working with Text, Delta, Parquet, JSON, CSV, and XML data formats.\n- Working knowledge of Spark structured streaming.\n- AWS infrastructure experience, specifically working with S3.\n- Solid understanding of git-based version control, DevOps, and CI/CD. Experience of working on Atlassian stack a plus.\n- Knowledge of common web API frameworks and web services.\n- Fluent in English speaking.\n- Strong teamwork, relationship, and client management skills, and the ability to influence peers and senior management to accomplish team goals.\n- Willingness to embrace modern technology, best practice, and ways of work.\n\nWhy you\'ll love working here:\n- Performance bonus up to 2 months\n- 13th month salary pro-rata\n- 15-day annual leave+ 3-day sick leave + 1 birthday leave + 1 Christmas leave\n- Meal and parking allowance are covered by the company.\n- Full benefits and salary rank during probation.\n- Insurances as Vietnamese labor law and premium health care for you and your family without seniority compulsory\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\n- Values-driven, international working environment, and agile culture.\n- Overseas travel opportunities for training and working related.\n- Internal Hackathons and company\'s events (team building, coffee run, blue card...)\n- Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(246, 219, 2, 'Business Analyst', 'Authentic education Hub là nền tảng giáo dục số tiên phong trong việc phát triển các giải pháp học tập trực tuyến, và hệ sinh thái học liệu số. Với sứ mệnh “đưa giáo dục chất lượng cao đến với mọi học sinh”, chúng tôi đang tìm kiếm một BA tài năng để cùng xây dựng và tối ưu sản phẩm giáo dục phục vụ hàng triệu người dùng.\n\nNỘI DUNG CÔNG VIỆC  \n- Khảo sát, thu thập và thống nhất yêu cầu của khách hàng.  \n- Phân tích và định nghĩa phạm vi yêu cầu nghiệp vụ, yêu cầu người dùng, yêu cầu chức năng các sản phẩm, dịch vụ với Khách hàng hoặc đối tác hoặc các bộ phận yêu cầu. Xây dựng, mô tả/đặc tả chức năng, nghiệp vụ cho các sản phẩm/dịch vụ: URD, SRS.  \n- Thực hiện báo cáo, các công việc liên quan theo sự phân công của QL trực tiếp.  \n- Phối hợp cùng team QC xây dựng và lên kế hoạch kiểm thử hệ thống.  \n- Đóng vai trò cầu nối giữa các team phát triển, làm rõ và tư vấn cho các thành viên trong team phát triển về nội dung yêu cầu.\n\nYour skills and experience  \n- Kinh nghiệm khoảng 2-3 năm kinh nghiệm làm việc ở vị trí tương đương.  \n- Khả năng thu thập và đánh giá tốt, có tư duy phân tích và hệ thống hóa tài liệu.  \n- Có kinh nghiệm làm việc với các domain về edtech hoặc F&B.  \n- Có khả năng sử dụng các công cụ phân tích và thiết kế yêu cầu như: draw.io, figma, ...  \n- Có khả năng làm việc và giao tiếp với databasse.  \n- Có khả năng đọc hiểu tiếng Anh là 1 lợi thế.  \n- Chủ động, có trách nhiệm, có tinh thần cầu tiến trong công việc.\n\nWhy you\'ll love working here  \n- Mức lương thỏa thuận, cạnh tranh theo năng lực.  \n- Tăng lương, xét thưởng dựa trên năng lực, hiệu quả công việc (đánh giá hiệu suất công việc 2 lần/năm).  \n- Chế độ tham gia BHXH, BHYT, BHTN theo quy định của Nhà nước.  \n- Tham gia các hoạt động Sinh nhật, liên hoan hàng tháng, Year End Party, ...  \n- Quà tặng, thưởng trong các dịp lễ lớn: Tết thiếu nhi, 2/9, Tết Dương Lịch, ...  \n- Chính sách ưu đãi khi sử dụng các sản phẩm trong hệ sinh thái của tập đoàn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '5BT2, khu đô thị Mễ Trì Hạ, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(247, 220, 2, 'Software Developer (SQL, Angular)', 'Tham gia phân tích, thiết kế, phát triển và bảo trì các hệ thống phần mềm phục vụ lĩnh vực y tế như: HIS, LIS, RIS, EMR/EHR, Quản lý bệnh viện,…;\nTích hợp với các hệ thống phụ trợ và các bên thứ 3;\nTối ưu hiệu năng, bảo mật và độ tin cậy của hệ thống phần mềm;\nVá lỗi, xây dựng và nâng cấp các module theo yêu cầu nghiệp vụ;\nCập nhật các công nghệ mới phục vụ cho việc cải tiến phần mềm và đáp ứng các yêu cầu quản lý Y tế số;\nThực hiện các công việc khác theo phân công của Quản lý trực tiếp.\nTốt nghiệp Đại học, cao đẳng chuyên ngành công nghệ thông tin;\nYêu cầu có 06 tháng kinh nghiệm trở lên;\nCó kinh nghiệm làm việc với cơ sở dữ liệu PostgreSQL, SQL Server, MySQL, C#, HTML, CSS, Angular...;\nCó khả năng tự học, nghiên cứu, kỹ năng làm việc nhóm và giải quyết vấn đề tốt;\nChủ động trong công việc, giải quyết vấn đề nhanh, chịu được áp lực công việc.\nLương net: Thỏa thuận theo năng lực;\nCông ty đóng Bảo hiểm xã hội theo quy định;\nMôi trường làm việc thân thiện, chuyên nghiệp, cơ hội thăng tiến cao;\nChế độ bảo hiểm, phúc lợi đầy đủ theo quy định của công ty;\nĐược tham gia vào các dự án, cập nhật công nghệ mới nhất;\nĐược hỗ trợ đào tạo nghiệp vụ và hướng dẫn quy trình vận hành thực tế cùng đội ngũ chuyên gia trong các lĩnh vực: Y tế...;\nCác chế độ theo Luật Lao động hiện hành và các phúc lợi theo quy định của Công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sàn Văn phòng số VP5 tầng 2 tòa nhà Pan Horizon, Xuân Thủy, Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(248, 221, 2, 'Bridge Software Engineer (N2+, Tech background)', 'We are looking for a BrSE candidate to join the project from offshore, receiving the requirements from clients, then communicating and cooperating with the Software Development/ Offshore team to develop the system and managing the development process of the software projects for clients.\n\nUnderstand business processes, discussing and making clear with the customer on business requirements and translating them into system specifications.\n\nWork under the client\'s side.\n\nUnderstand the requirements and deploy them to the Offshore/ Software Development Team.\n\nCommunicate requests and inquiries between offshore and the client.\n\nParticipate in the meeting with clients and support communication.\n\nSupport understanding of the team of provided materials.\n\nChange requirements management.\n\nResponsible for reviewing the Offshore review report, reviewing the deliverables, and taking charge of the deliverables\' quality and deliverables.\n\nProject work scope management (including variable work scope depending on the original work scope).\n\nQualifications and Education Requirements:\n\n01+ year of experience working with software development, experience of working as BrSE.\n\nEnthusiastic, responsible, willing to learn new technologies, and able to work under pressure.\n\nGood at English and Fluent in Japanese (N2) in both verbal and writing skills.\n\n2+ years of hands-on system development experience, including web services or native application development.\n\n1+ year of experience with AWS. (including one of the following certificates: AWS Solution Architect Associate, or AWS Developer Associate or above.)\n\n1+ year of experience with GitHub, Backlog, Slack (or other project management or communication tools).\n\nEssential Soft Skills:\n\nExperience in creating and reviewing requirements definitions.\n\nExperience in planning and executing system tests.\n\nProactive communication and collaboration with clients and partners to clarify requirements.\n\nExperience in leading system development projects in collaboration with overseas teams.\n\nAbility to understand business priorities and apply appropriate engineering solutions.\n\nDesire to contribute to global business and organizational growth beyond engineering tasks.\n\nProactive self-starter who is driven to achieve product goals.\n\nDedicated and willing to go the extra mile.\n\nPassionate about new technologies and stays up-to-date on industry trends.\n\nEnjoys automating tasks.\n\nProject management skill.\n\nDevelopment experience as a developer (need technical knowledge).\n\nHave good skills in Teamwork, Analysis, Design, Communication, and Presentation.\n\nStrong interpersonal skills and able to work independently. \n\nProactive can-do attitude and high sense of organization and responsibility.\n\nUnderstand Japanese working cultures and styles (people who have experience of working in Japan tend to have it).\n\nPreferred Qualifications:\n\n1+ year of experience in system maintenance and operations.\n\n1+ year of experience in project management (PM or PL) or PMP certification.\n\n1+ year of experience with Datadog or NewRelic.\n\nExperience in proposal writing and negotiation.\n\nExperience in developing high-traffic applications.\n\nHands-on experience with servers, containers, and networks.\n\nExperience with configuration management tools for system deployment.\n\nIT certifications.\n\nAzure Associate or above certification.\n\nWhy you\'ll love working here:\n\nFully paid insurance coverage, premium health care, and annual health checkup.\n\n20 days of annual leave plus 1 more day for the Anniversary Establishment Day in Oct.\n\nAll benefits followed Vietnamese labor law, including a 13th-month salary. \n\nTraining allowance.\n\nAnnual company trip. \n\nAnnual performance review.\n\nFree parking card.\n\nA laptop that fits your needs. \n\nSport Clubs (Football and badminton).\n\nEnglish Speaking Club.\n\nFree beverages.\n\nWorking from Monday to Friday (9am -6pm).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '2nd Floor, Central Park, 117-119-121 Nguyen Du, Ben Thanh, District 1, HCMC, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(249, 222, 2, '06 Java Developers (Spring, Oracle)', '- Tham gia thiết kế, phát triển, triển khai và bảo trì các sản phẩm phần mềm của Công ty\n- Lập trình và tối ưu hóa để đảm bảo hiệu suất, chất lượng và khả năng đáp ứng tốt nhất của các ứng dụng;\n- Xây dựng kế hoạch và quản lý tiến độ lập trình theo kế hoạch\n- Thực hiện các công việc khác do Cán bộ quản lý yêu cầu.\n*** Chi tiết công việc sẽ trao đổi thêm trong quá trình phỏng vấn ***\n\n- Có kinh nghiệm lập trình Java tại các dự án thực tế từ 1 năm trở lên.\n- Có kinh nghiệm phát triển ứng dụng web\n- Có kinh nghiệm tốt với Spring framework (Spring-core, Spring-boot, Spring Security,...)\n- Có kinh nghiệm về Web Framework (Spring MVC, Struts,…), JavaScript framework (Angular, Jquery, VueJS,…);\n- Có kinh nghiệm làm việc và hiểu biết với API (Resful, SOAP), SCM (Git, SVN), IDE (Eclipse...)\n- Sử dụng thành thạo ngôn ngữ Oracle\n- Ưu tiên ứng viên có kinh nghiệm mảng Banking và Fintech\n- Có tinh thần trách nhiệm, ham học hỏi và chủ động trong công việc\n\n- Thu nhập cao tương xứng với năng lực.\n- Thưởng nóng khi thi đỗ chứng chỉ chuyên môn, thưởng hoàn thành dự án, thưởng cuối năm v.v.. và nhiều khoản thưởng hấp dẫn khác.\n- Môi trường thân thiện, năng động\n- Team Building, Tiệc sinh nhật công ty, Tiệc tổng kết năm, tiệc sinh nhật hàng tháng, dã ngoại, nhiều hoạt động ngoại khóa v.v... được tổ chức thường xuyên quanh năm\n- Được tham gia nhiều khóa đào tạo nâng cao chuyên môn, công ty hỗ trợ kinh phí thi chứng chỉ chuyên ngành phục vụ cho công việc.\n- Cơ hội thăng tiến cho các bạn trẻ có năng lực.\n- Hưởng đầy đủ các chế độ theo luật lao động hiện hành và các chính sách đãi ngộ tốt. Công ty tài trợ gói bảo hiểm sức khỏe với mức bảo lãnh viện phí nội và ngoại trú lên đến 180 triệu/năm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '98  Nguy Nhu Kon Tum, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(250, 214, 2, 'DevOps Engineer (CI CD, Python, C++, English)', 'Top 3 reasons to join us\n- Competitive salary & up-to 16-month income / year\n- Attractive allowances & benefits\n- Flexible working time with many company holidays\n\nJob description\nAs member of Software Engineering Team, your main responsibilities will depend on the job position for which you qualify:\n \n(1) Software Engineer - Integration Build (OpenSource system, C, C++, Python):\nOperation and maintenance of (CI/CD/)CT pipeline based on Jenkins, BlackDuck Hub, Scancode and In-house system(VOSC)\n(Yocto, Android, etc) Extending application and optimization of build-based Open Source Scan\nOSS package verification and optimization\n \n(2) Software Engineer - Integration Build (C, C++, Python):\nDesign & set up an initial build environment for a new project and provide/maintain an environment for developers to build.\nImprovements to the Build System and developer development environment.\nEstablish a configuration management policy(Code quality and Code Review System) in close collaboration with other department, and set up and operate various tools that can help improvements Code quality and SW stabilize.\n\nYour skills and experience\nJob requirements will depend on the position you apply for:\n \n(1) Software Engineer - Integration Build (OpenSource system, C, C++, Python):\n- Understanding of open source licenses (e.g., GPL, MIT, Apache)\n- Experience in Yocto Build System, Android Build System\n- Experience in Git, Jenkins, BlackDuck Hub, Fosslight scanner\n- Excellent skills in Python, Shell scripts and Linux System\n- Git & Gerrit experience (comfortable using code review and source code repository management)\n- Knowledge in containerization technologies such as Docker\n\n(2) Software Engineer - Integration Build (C, C++, Python):\n- Experience in Embedded Linux system\n- Fluency in C, C++, Java, Kotlin, Python, Shell scripting, Make. CMake.\n- Having hands-on experiences in using version control tool such as Git, gerrit(comfortable using code review and source code repository management);\n- Knowledge in containerization technologies such as Docker, VM\n\nWhy you\'ll love working here\n- 13th month salary + Incentive bonus (Total remuneration package / year: up to 16-month salary) + Annual salary review;\n- HYBRID WORKING, flexible working time (Mon - Fri)\n- Support for lunch, transportation and other allowances (Coding Expert, Technical leader, phone...);\n- Premium health care & accident insurance;\n- Total 20 days off (12 days of annual leave & additional 8 days of company holidays: Summer holiday, Mid-Autumn, Christmas, LG and VS DCV Foundation Days);\n- Support fee to get TOEIC & technical certifications (ISTQB, Agile Scrum...);\n- On-site & training opportunities abroad;\n- Company trip, sport clubs (zumba, football, pingpong, badminton,...);\n- Monthly budget for team activities, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 17 đến tầng 21, Tòa văn phòng, Lotte Mall Hà Nội, Số 272 Võ Chí Công, Phường Phú Thượng, Quận Tây Hồ, Thành phố Hà Nội, Tay Ho, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(251, 156, 2, 'Senior Business Analyst (Databse)', 'Job description\n- Kiểm tra, giám sát các công việc của team trực tiếp với vai trò Senior/Lead Business Analyst trong dự án.\n- Báo cáo công việc hàng tuần cho quản lý trực tiếp.\n- Giao tiếp với khách hàng để nắm bắt nhu cầu của khách hàng trong việc thực hiện các nghiệp vụ liên quan đến phần hành được giao.\n- Phân tích các yêu cầu của khách hàng, phân tích nghiệp vụ DWH, mô hình dữ liệu dành cho ngân hàng và doanh nghiệp. Xem xét khả năng đáp ứng của hệ thống đối với các yêu cầu của khách hàng và làm việc với khách hàng để chốt yêu cầu.\n- Chuyển hóa các yêu cầu của khách hàng thành các đầu mục thiết kế hệ thống, báo cáo.\n- Thực hiện việc kiểm tra hệ thống.\n- Chuẩn hóa các quy trình, workflow, tài liệu vận hành. Biên soạn, chỉnh sửa và phát hành các tài liệu.\n- Thực hiện các công việc khác theo yêu cầu của Ban Giám đốc hoặc Quản lý trực tiếp.\n\nYour skills and experience\nTrình độ học vấn/ bằng cấp\n- Bằng cử nhân, tốt nghiệp các ngành Kế toán – Kiểm toán, Hệ thống thông tin quản lý, Công nghệ thông tin, Ngân hàng hoặc các ngành có liên quan khác;\n\nKinh nghiệm làm việc\n- Tối thiểu 4 năm kinh nghiệm tại vị trí Business Analyst hoặc tương đương.\n- Tối thiểu 2 năm kinh nghiệm tại vị trí Senior/Lead hoặc tương đương tại công ty tài chính ngân hàng.\n- Có kinh nghiệm làm trung tâm MIS của bank.\n- Đã tham gia tối thiểu 1 dự án ETL, DWH của ngân hàng với vai trò Business Analyst dữ liệu.\n\nKiến thức chuyên môn\n- Có kinh nghiệm về triển khai các hệ thống công nghệ thông tin, các hệ thống Operational Data Store (ODS), Data warehouse (DWH), Business Intelligence (BI) dành cho ngân hàng và công ty tài chính.\n- Có kiến thức về các báo cáo tài chính của ngân hàng, công ty tài chính.\n- Có kiến thức về các hệ thống Core (Flexcube, T24).\n- Có kiến thức về SQL và code.\n- Có hoặc đang học các bằng cấp nghiệp vụ (ACCA, CFA, CMA, v.v) hoặc tương đương.\n\nKỹ năng\n- Kỹ năng tổ chức và sắp xếp thông tin;\n- Kỹ năng đối mặt với áp lực;\n- Kỹ năng giao tiếp;\n- Kỹ năng quản lý công việc;\n- Kỹ năng giải quyết vấn đề;\n- Kỹ năng lãnh đạo.\n\nYêu cầu khác\n- Thành thạo tin học văn phòng, biết sử dụng các công cụ phục vụ nghiệp vụ.\n- Tiếng Anh đọc hiểu tài liệu.\n\nWhy you\'ll love working here\n- Chế độ nghỉ (nghỉ hàng tuần, phép năm, lễ tết…)\n- Được hưởng đầy đủ các chế độ BHXH, BHYT, BHTN và các chế độ khác theo quy định Nhà nước.\n- Được đánh giá hiệu quả công việc 06 tháng/lần để làm căn cứ nâng lương, thăng tiến, khen thưởng.\n- Được định hướng và có cơ hội thăng tiến, phát triển sự nghiệp theo nguyện vọng.\n- Được hưởng các chế độ phúc lợi khác như: Company trip, Team building, các hoạt động tập thể… của Công ty.\n- Khám sức khỏe định kỳ hàng năm & tham gia bảo hiểm sức khỏe bên ngoài (PVI, Bảo Việt, Bảo Minh,...).\n- Được tạo điều kiện đào tạo nâng cao kiến thức, kỹ năng về CNTT, kỹ năng mềm,… bằng các hội nghị chuyên đề tại công ty, các khóa học tại các đơn vị đào tạo chuyên nghiệp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phòng 401, tòa Savina, số 1 Đinh Lễ, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(252, 223, 2, 'Senior QA Engineer', 'Akila is looking for a Senior QA with ambition, creativity and a passion for sustainability and technology. Our team is involved in a wide variety of technologies, like digital twin, 3D engine development and cross platform development. This role will be critical for Akila’s development, as it represents on both Mobile and Web platform. Candidate should be comfortable working in a fast-moving startup environment where speed, hard work and fresh thinking are critical to success. Provide timely and valuable feedback after Product Requirement Detail and technical design document review. Create detailed, comprehensive, and well-structured test plan and test cases. Execute test cases and report test results. Design and implement automation test script to ensure testing efficiency. Write and execute test scripts to cover the most needs. Work with team to improve product quality continuously.\n\nYour skills and experience\nBachelor’s degree in Computer Science or equivalent is required. Master’s degree is preferred. 4+ years software whitebox/blackbox testing experience is preferred. Strong knowledge of Software QA methodologies and testing process. Experience with performance testing tools (Jmeter is preferred). Experience with automation testing framework, Selenium/Robot/Nose experience is preferred. Familiar with one or more programming language, Python is preferred. Familiar with API testing and any experience with Yapi is preferred. Excellent trouble shooting skill. Proactive & Plan-Do-Check-Act attitude with good capabilities of problem solving. Excellent attention to details, follow through design and be able to work independently. Adaptable, resilient, and positive attitude. AI/ML knowledge background is a plus. Excellent English communication skill. Experience with performance testing.\n\nWhy you\'ll love working here\nThe opportunity to work on groundbreaking digital-twin technology that directly contributes to decarbonization and sustainable building practices. Collaborate with industry leaders in AI, 3D visualization, and simulation. Be part of a fast-growing, innovative team shaping the future of digital twins. Competitive salary and benefits package, with flexible work arrangements.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Peakview Tower, 36 Hoang Cau, O Cho Dua, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(253, 224, 2, 'Senior QA/QC Engineer (Hybrids or Automation)', 'We are looking for a QA/QC Engineer with solid testing and interpersonal skills. Candidates joining in Money Forward Vietnam will participate in a joyful, high competent and English speaking team to enhance quality for the company\'s products which are serving millions of users.\n\nThis position is hiring in both Hanoi & HCM.\n\nResponsibilities\n- Analyze product requirement and clarify if any questions\n- Design test cases with in-depth understanding of requirements and testing techniques\n- Perform testing activities from start to delivery of tasks and tracking status of found defects\n- Participate in agile team to develop our high quality products\n- Enhance working process and share best practices to others\n- Initialize new ideas and contribute to develop QA/QC department\n- Support, review and provide necessary trainings to teammates\n\nYour skills and experience\n- 5+ years of experience in web testing\n- Good English communication and documentation skills\n- Solid skills and knowledge of testing processes and techniques\n- Experience in test automation with any frameworks, any programming languages\n- Experience in API testing with Postman or other tools\n- Experience in working in cross functional or agile teams\n- Familiar with issue and test management tools like Jira, TestRail…\n- Great interest in testing, open minded and able to self-motivated\n- Experience in performance testing or security testing is a plus\n- ISTQB or equivalent testing certificate is a plus\n\nWhy you\'ll love working here\nCaring Mental & Physical Recreation:\n- Hybrid working\n- Full salary in probation & 13th month salary\n- Social insurance on full salary from probation\n- Premium Health insurance from probation\n- Flexible start 8AM-9AM from Mon-Fri\n- 16 days off annually + 1 Birthday Leave\n- Paternity leave extra 5 days\n- Annual company trip; Quarterly team building activities\n- Club activities\n- Annual health check\n\nCaring Career & Development:\n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- Well-equipped facility: Macbook pro, additional monitor,..  \n- Soft skill workshops\n- Tech seminars\n- Monthly and biannually Recognition Awards\n- Performance review twice/year', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(254, 216, 2, '[Global Market] 02 DevOps Engineer & Infra', 'Top 3 reasons to join us\n• Môi trường làm việc đa quốc gia\n• Cơ hội thăng tiến, phát triển bản thân\n• Trải nghiệm làm việc tại Nhật Bản/ Âu Mỹ\n\nJob description\n• Design and implement Azure DevOps Pipelines using YAML to support CI/CD processes for software projects.\n• Build and manage containerized environments using Docker for development, testing, and production.\n• Apply Azure DevOps CI/CD best practices to ensure fast, secure, and stable deployments.\n• Set up monitoring, logging, and application performance tracking using Application Insights, Azure Monitor, and related tools.\n• Operate and optimize infrastructure services on Azure Cloud (e.g., Web Apps, Azure Functions, App Gateway, Storage, Key Vault, etc.).\n• Collaborate with development teams to automate deployments and improve system operations.\n\nYour skills and experience\nMust have:\n• Proven experience with Azure DevOps Pipelines (YAML).\n• Proficiency in Docker and container orchestration for software deployment.\n• Solid understanding and application of CI/CD best practices on Azure.\n• Hands-on experience with monitoring/logging tools: Application Insights, Azure Monitor, Log Analytics, etc.\n• Working knowledge of Azure Cloud Services.\nNice to have:\n• Relevant certifications such as AZ-400, AZ-104.\n• Experience with Infrastructure as Code (IaC) tools like Terraform or Bicep.\n• Strong scripting skills in PowerShell or Bash.\n• Good English communication skills to collaborate with international teams or clients.\n\nWhy you\'ll love working here\n• Package: At least 13 months/ year. Review periodically following company policy.\n• Bonus: Tet bonus, project bonus, holiday bonus, HR referral bonus...\n• Seniority allowance (working time from 2 years or more).\n• Participate in learning and training activities inside and outside the company, accumulate learning points, develop G-Points on the company\'s management system.\n• 2 days of leave per week and 12 leave days per year.\n• Clubs and many cultural, sports, and art activities sponsored or supported by the company (For example: Football, table tennis, badminton, swimming, music, English, games...).\n• Ensure health: Periodic health check, support to buy high-quality health insurance...\n• Join the Rikkei Care Health Insurance Plan.\n• Mental comfort: Playing music on demand every day, happy hour, team building activities...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 18, tòa nhà Vinacomin, 3 Dương Đình Nghệ, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(255, 225, 2, 'Engineering Manager', 'By applying for the above position, you accept and agree that your personal data and any information stated in the attached curriculum vitae (CV) will be used and processed by ITViec and NAB Vietnam for recruitment purposes. The storage and processing of such information will comply with the applicable laws of Vietnam, and the policies and procedures of ITViec and NAB Vietnam regarding personal data, as amended from time to time.\n\nABOUT THE JOB\nAs an Engineer Manager, you will be accountable for the leadership of one or more engineering scrum teams to plan, deliver and support service features that deliver customer value and/or mature service capability. The position is also accountable for executing the people leader fundamentals in line with NAB Policies, driving a learning-based culture with an ability to set and gain agreement for realistic and stretching objectives for the team.\n\nYOUR JOB RESPONSIBILITIES\nManage multi-Agile teams to deliver on engineering standards, sprint backlogs, and plans, engineers’ responsibilities and performance management, code quality, adherence to development, and testing guardrails.\nManage milestones, deliverables, risks, and dependencies of the engineering teams.\nEducate the engineering teams and ensure the release of features to production comply with NAB risk management frameworks.\nAbility to create and maintain relationships with a wide range of stakeholders.\nBe the voice of reason between speed and quality.\nEvangelist of the T-shaped working model; coach engineers to be T-shaped, versatile, and take responsibility outside their core disciplines.\nLine management (1:1 meeting, personal development & training plan, career path, probation reviews, and performance reviews);\nCoach teams in applying Scrum and DevOps.\nBe responsible for continuous improvement of the teams.\nLead initiatives for implementing efficient development and delivery processes.\nDrive a learning-based culture with an ability to set and gain agreement for realistic and stretching objectives for the team.\n\nTechnical environment:\nMicroservices architecture system\nProgramming - Java, JavaScript, MV* patterns, Nodejs, ReactJS (including Redux)\nDatabases – Postgres, MongoDB\nDevOps – Jenkins, Artifactory, SonarQube, GitHub, CloudFormation\nCloud: Multi-Cloud, AWS (Lambda, Postgres, S3, API Gateway, CLI, SNS/SQS), Azure\n\nYOUR SKILL AND EXPERIENCE\nMust have:\n10+ years working experience in Software Development; 5+ years’ experience in leading cross-functional Agile teams.\nSolid understanding of Software Quality, DevOps environments\nExcellent experience in SDLC methodologies – Scrum, Kanban, Waterfall\nProven ability to manage and deliver complex technology projects involving multiple engineering teams both onshore and offshore.\nReal-world experience with large-scale Agile adoption, not just theoretical knowledge.\nStrong stakeholder management experience.\nProven people leadership, team building, motivation, and coaching skills\nExperience in managing code and change management processes.\nExperience with IT Service Management (e.g., Release Management) and experience with using Service Now or similar.\nStrong ability to communicate at both strategic and operational level internally and externally, making effective decisions balancing business and stakeholder needs.\nFluent English skills\n\nNice to have:\nAgile – Certified Scrum Master (preferred)\nExperience in the Banking or Financial Services industry; (preferred)\n\nWhy you\'ll love working here\n1. Generous compensation and benefit package\nAttractive salary and benefits  \n20-day annual leave and 7-day sick leave, etc.  \n13th month salary and Annual Performance Bonus  \nPremium healthcare for yourself and family members  \n\n2. Exciting career and development opportunities  \nLarge scale products with modern technologies in banking domain  \nClear roadmap for career advancement in both technical and leadership pathways  \nSponsored certificates in both IT and banking/finance  \nPremium account on Udemy\nEnglish learning with native teachers  \n\n3. Professional and engaging working environment \nHybrid working model and excellent work-life balance    \nWell-equipped & modern Agile office with fully-stocked pantry    \nAnnual company trip and events   ', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(256, 226, 2, 'Deputy head of Data Services development', 'LynkiD is a pioneering fintech company specializing in customer loyalty services and data integration, under a leading financial group. We are seeking an experienced and passionate Deputy Head of Data Service to help build, operate, and scale modern data products and services for both internal and external stakeholders (banks, retail, insurance, and more). You will support the Head of Department in managing a team responsible for designing, developing, and maintaining robust data services (data APIs, streaming pipelines, data marts, etc.). You will also work closely with business units, product teams, partners, and IT to ensure timely delivery of high-quality data solutions.\n\nKey Responsibilities:\n\nData Service Development: Assist in building and executing the strategy for data service development at LynkiD. Design and develop data services such as APIs, batch/real-time pipelines, and data marts that power internal applications and external partner integrations. Ensure high performance, availability, and scalability of data platforms and services.\n\nTeam Management & Operations: Support team leadership, mentoring junior engineers and coordinating task allocation within the team. Collaborate with engineering, QA, and DevOps to maintain CI/CD pipelines, monitor system health, and ensure service reliability. Propose improvements in operational processes, development standards, and monitoring practices.\n\nCross-functional Collaboration: Act as a liaison between the data engineering team and business/product stakeholders to collect, analyze, and translate requirements into technical solutions. Evaluate new data integration requests and external API services, ensuring alignment with business needs and architectural standards.\n\nData Governance & Compliance: Ensure data services are developed in compliance with internal data governance frameworks and external data privacy regulations. Support implementation of logging, alerting, and data quality monitoring mechanisms across services.\n\nYour skills and experience\n\nEducation & Experience: Bachelor’s or Master’s degree in Computer Science, Information Systems, Data Engineering, or related fields. Minimum of 3–5 years of experience in data engineering, data platform development, or API services, preferably in fintech, banking, or loyalty eco-systems. Proven experience in designing and operating scalable, hybrid data systems.\n\nTechnical Skills: Proficiency in Python, Java, and SQL for data processing and backend services. Familiarity with modern data architecture principles (Data Lake, Data Warehouse, Streaming, Data Mesh). Experience with cloud platforms such as AWS, Azure, or GCP, particularly with services like Redshift, S3, Glue, BigQuery, etc. Knowledge of tools like Git, Docker, Airflow, and CI/CD practices.\n\nSoft Skills & Leadership: Strong system thinking and product mindset with a business-oriented approach to solving problems. Excellent communication skills and the ability to translate complex technical ideas to non-technical audiences. Experience managing small teams (3–6 people), allocating tasks, mentoring juniors, and coordinating cross-team work.\n\nPreferred (Nice to Have): Experience delivering Data-as-a-Service or external-facing data products. Understanding of modern data operating models such as Data Mesh or Data Product Thinking. Relevant certifications (AWS Certified Data Analytics, Google Cloud Data Engineer, etc.).\n\nWhy you\'ll love working here\n\nA dynamic fintech startup environment with a strong data-first vision. Competitive compensation package (salary). Clear career progression toward team lead or department head within 6–12 months based on performance. Direct exposure to senior management and strategic projects from day one.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '20th Floor, 89 Lang Ha, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(257, 227, 2, 'Junior IT Support', 'Top 3 reasons to join us:\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description:\n- Support Operations: Ensure efficient handling of first-level support requests via communication channels such as Slack and phone, escalating complex issues to the technical team.\n- System Monitoring: Oversee active monitoring of system dashboards, alerts, and infrastructure boards on platforms like Grafana and AWS to proactively identify and address issues.\n- After-Hours Coordination: Organize and participate in rotation schedules for after-hours system monitoring to guarantee continuous platform operation.\n- Documentation: Maintain comprehensive documentation of support activities, resolutions, and preventive measures to build a robust knowledge base.\n- Software Support: Oversee support for office software and applications, manage user access, and ensure optimal usage practices.\n- Infrastructure Management: Maintain the reliability and security of office network infrastructure, including Wi-Fi, routers, switches, and hardware like printers, laptops, and TVs.\n\nYour skills and experience:\n- Education: Bachelor\'s degree in Information Technology, Computer Science, or a related field.\n- Experience: Minimum of 1 years in IT support roles.\n- Technical Skills: Knowledge with system monitoring tools (e.g., Grafana, AWS CloudWatch) and network infrastructure management.\n- Communication: Good verbal and written communication skills in English, capable of conveying technical information to non-technical stakeholders.\n- Flexibility: Willingness to work flexible hours, including nights, weekends, and holidays, to support 24/7 operations.\n\nPreferred (but not required):\n- Cloud Experience: Knowledge with AWS, Azure, or Google Cloud services.\n- DevOps Knowledge: Knowledge of DevOps principles and tools.\n\nThis role is a fantastic opportunity for individuals looking to deepen their experience in tech support within a vibrant and fast-growing tech startup environment. Join us at Crossian LLC and be a part of our mission to redefine cross-border eCommerce.\n\nWhy you\'ll love working here:\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain: \nExceptional Compensation:\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total Annual compensation up to $14,000, reflecting your expertise and contribution.\nGrowth Opportunities:\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(258, 183, 2, 'Senior/Lead PHP Engineer', 'We are building an environment where personal development is a focus. We want all members to grow with the company through hands-on projects and industry best practices. Our clients have extremely high expectations and that sets a bar for our quality of work. We’re looking for a Senior/Lead PHP Engineer for our organization.\n\nWhat you\'ll be doing:\n\n- Working on Web and Mobile products.\n- Provide technical leadership and mentorship to engineering teams.\n- Set and enforce coding standards and best practices.\n- Design scalable and maintainable software architecture aligning with business objectives.\n- Communicate complex technical concepts to both technical and non-technical audiences.\n- Champion continuous integration and continuous deployment (CI/CD) practices.\n- Drive the resolution of critical production issues in a timely manner.\n\nYour skills and experience\n\nWhat You Are Good at\n\n- Professional software development experience.\n- Software design and architecture experience.\n- Experience with building services and Restful APIs.\n- Strong experience with PHP, PSR, we expect you to coach others.\n- Excellent communication skills, capable of simplifying complex technical information for a diverse audience.\n\nHaving the following skills is a plus\n\n- Experience with GraphQL.\n- AWS knowledge (Docker, Kubernetes, databases, storage, streams, etc).\n\nWhy you\'ll love working here\n\n- Above industry standard salaries.\n- Friendly working environment and flexible working hours.\n- 13th salary, insurance, and team-building activities.\n- We work hand-in-hand with our clients to fully invest in their product development and build solutions together for their target market.\n- We fully invest in our team, we will help you build yourself up in any area you feel you need development, be it in English, learning a new design tool, developing your design thinking, and more. We want to make sure that you’re always learning and developing yourself whilst a part of our team.\n- We respect both Products and Technology equally, ensuring all of the Products we work on have features with true market potential and ensuring all of the team contribute to, understand, and believe in what they are developing.\n- We respect you and your personal hours, we keep a sustainable pace by working standard 8 hours days from Monday to Friday, ensuring we only plan for what we can achieve.\n- We are fully agile, working with set sprint goals and working at our rate of velocity.\n- You will have ownership over your role, giving you the opportunity to experiment and try new processes to better improve your day-to-day responsibilities. We are always open to improving our processes.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '56A Le Khoi, Phu Thanh, Tan Phu, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(259, 228, 2, 'CVCC Phát triển Ứng dụng kênh ngân hàng số (Java, .NET)', '• Tham gia việc phân tích, đánh giá các yêu cầu nghiệp vụ ngân hàng trên các kênh ngân hàng điện tử, ngân hàng số dành cho KHCN và KHDN, Branch Teller.\n• Tham gia phát triển, cải tiến và duy trì các ứng dụng kênh ngân hàng điện tử, ngân hàng số dành cho KHCN và KHDN, Branch Teller.\n• Đảm bảo tích hợp liền mạch giữa các ứng dụng kênh ngân hàng điện tử, ngân hàng số và các hệ thống công nghệ hiện có của ngân hàng.\n• Tham gia phối hợp hỗ trợ các đơn vị vận hành giám sát hoạt động và khắc phục các vấn đề phát sinh của các hệ thống trên kênh số khi có yêu cầu bao gồm: Internet Banking, Mobile Banking.\n• Tham gia hỗ trợ level 2 cho các sản phẩm, dịch vụ trên kênh số nhằm phục vụ khách hàng nội bộ (CallCenter, Card Center, Chi nhánh/Phòng giao dịch) và khách hàng bên ngoài thông qua các kênh như Service Desk, email, điện thoại,…\n• Tham gia các dự án số hóa của Ngân hàng và khối CNTT.\n• Theo dõi xu hướng và phát triển trong lĩnh vực ngân hàng điện tử, ngân hàng số, đề xuất các phương án cải tiến và áp dụng các giải pháp sáng tạo để nâng cao trải nghiệm khách hàng.\n• Thực hiện các nhiệm vụ khác theo phân công của cấp quản lý.\n\nYour skills and experience\n\n- Tốt nghiệp đại học trở lên các chuyên ngành phù hợp như CNTT/Điện tử viễn thông hoặc các chuyên ngành có liên quan đến CNTT.\n- Tối thiểu 3 năm kinh nghiệm trong lĩnh vực phát triển ứng dụng ngân hàng số, tài chính số hoặc các lĩnh vực liên quan (lập trình Java/ .NET, J2EE/Web service/JMS, Oracle Database, My SQL, Postgre SQL).\n- Có kinh nghiệm về tích hợp hệ thống qua ESB (Enterprise Service Bus) sử dụng EIP (Enterprise Integration Patterns).\n- Có kinh nghiệm về microservices, CI/CD\n- Có kinh nghiệm về các công cụ giám sát như ELK, Splunk, Prometheus, Grafana\n- Sử dụng thành thạo các IDE phát triển và các tool quản lý source code, quản lý công việc. (CI/CD: Jenkin, GIT, ANT);\n- Nắm vững các design pattern thông dụng, các kiến thức về cấu trúc dữ liệu và giải thuật, lập trình hướng đối tượng,...\n- Đã từng làm việc trong lĩnh vực ngân hàng, có kiến thức về nghiệp vụ và hệ thống thông tin ngân hàng là lợi thế.\n- Kỹ năng Tiếng Anh đọc hiểu tài liệu kỹ thuật.\n\nƯu tiên các ứng viên\n\n- Ham học hỏi tìm tòi sáng tạo cái mới\n- Có hiểu biết về nghiệp vụ tài chính ngân hàng\n- Đã từng triển khai sản phẩm lên AWS, Azuse\n- Có kinh nghiệm làm việc theo mô hình Agile/ Scrum/ Waterfall.\n\nWhy you\'ll love working here\n\nChế độ phúc lợi\n\n- Lương và phụ cấp\n- Lương nhân viên PG Bank được áp dụng từ việc khảo sát mức lương thực tế của ngành và thị trường. Khung lương được xây dựng cho 9 cấp/ bậc của công việc, dải lương rộng cho phép thu hút được những ứng viên tiềm năng và đảm bảo trả mức lương cạnh tranh cao cho mọi vị trí. Ngoài chế độ lương cạnh tranh, nhân viên PG Bank còn được hưởng rất nhiều chế độ phụ cấp khác theo đặc thù công việc như phụ cấp điện thoại, phụ cấp ăn trưa, phụ cấp đi lại ... , chế độ tham quan nghỉ mát hàng năm, tặng quà cho CBNV nhân dịp sinh nhật, thăm hỏi ốm đau, kết hôn, hỗ trợ thai sản.\n\n- Chế độ khen thưởng:\n- PG Bank có chế độ đãi ngộ nhân viên xứng đáng với năng lực và đóng góp của từng cá nhân. Về cơ bản, PG Bank có chế độ thưởng như sau:\n\n+ Thưởng theo kết quả kinh doanh\n+ Thưởng hoàn thành công việc\n+ Thưởng cho tập thể, cá nhân tiêu biểu trong năm\n+ Thưởng đột xuất cho tập thể, cá nhân hoàn thành xuất sắc nhiệm vụ, có sáng kiến, đóng góp có giá trị cho Ngân hàng, thưởng do hoàn thành vượt mức kế hoạch được giao.\n+ Thưởng cho toàn bộ CBNV ngân hàng trong các dịp lễ tết.\n\n- Chế độ bảo hiểm:\n- Tất cả nhân viên chính thức của PG Bank đều được tham gia Bảo hiểm xã hội, Bảo hiểm y tế và bảo hiểm thất nghiệp theo đúng quy định của Luật lao động hiện hành. Ngoài ra, tất cả nhân viên chính thức của PG Bank đều được mua thêm bảo hiểm Pijico, một gói bảo hiểm rất ưu việt giúp thanh toán các chi phí y tế như tiền thuốc, tiền viện phí… khi khám chữa bệnh tại các bệnh viện tốt nhất tại địa phương.\n\nĐào tạo và phát triển nguồn nhân lực\n- Công tác đào tạo và phát triển nguồn nhân lực luôn được chú trọng và phát triển tại PG Bank. Với mục tiêu xây dựng nguồn nhân lực có năng lực và tính chuyên nghiệp cao đáp ứng chiến lược phát triển nhanh và bền vững của Ngân hàng, chuẩn bị nhân sự kế nhiệm cấp điều hành cho Ngân hàng, PG Bank thường xuyên tổ chức cho nhân viên tham dự các khóa đào tạo trong và ngoài nước, các khóa đào tạo của NHNN, Hiệp hội ngân hàng, các tổ chức đào tạo có uy tín khác nhằm nâng cao trình độ chuyên môn, nâng cao kỹ năng làm việc hiệu quả và các kỹ năng quản lý, lãnh đạo trong từng giai đoạn, vị trí công tác.\n\nCơ hội thăng tiến\n\n- Tại PG Bank, nhân viên được làm việc trong môi trường cạnh tranh lành mạnh, rất nhiều cơ hội phát triển, thăng tiến đang chờ đón các bạn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thanh Cong Tower, 79 Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(260, 229, 2, 'Mobile Developer (JavaScript/ React Native)', 'Headquarter: Daoukiwoom Group - Find more at:Industry: Finance & Trading\n\nTop 3 reasons to join us\n- Full SHUI as Vietnamese Law\n- 15-day annual leave, Christmas leave\n- Premium Private Medical Insurance PVI\n\nJob description\n- Develop Mobile Stock Trading app using JavaScript under the Kiwoom platform\n- Work directly with remote team to clarify tasks and requirements\n- Develop new features based on the user requirements (analyzing requirements and system design)\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance\n- Managing time and resources based on the WBS\n- Compile a weekly-report about the progress of tasks\n- Perform self-learning about a domain knowledge, write a report and conduct a seminar about it\n- Write high-quality, clean, elegant, maintainable, and testable code\n- Maintaining technical documents up-to-date\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the Kiwoom Framework for Kiwoom Indonesia, Finansia (in Thailand), and so on.\n\nYour skills and experience\nEducation & Experience\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Minimum 2-3 years of professional experience in mobile app development using JavaScript or iOS/Android native.\n- Experience and knowledge in markup language, including HTML, CSS is a must.\n- Ability to write clean, easy to understand code.\n- Familiarity with version control systems, such as Git or SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n- Solid understanding of the full mobile development life cycle.\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nSoft Skills & Communication\n- Strong problem-solving and analytical skills.\n- Able to communicate in English, written and spoken.\n- Strong communication skills and teamwork, international experience is preferred.\n\nNice to have:\n- Over 1 year of experience in developing securities solutions, including a smartphone-based trading platform utilizing the Mobile Trading System (MTS)\n- Proficient in utilizing the Mobile development Framework (Ionic, PhoneGap, React, Vue, Nexacro)\n- Experience on working with oversea team.\n\nWhy you\'ll love working here\nBENEFITS\nIncome & Achievement\n- Competitive salary, salary review once a year\n- 13th month salary and Annual Performance Bonus\n- MVP and Shining star awards at the end of year\n- Global and professional working environment\n\nWorkplace Happiness\n- Full SHUI as Vietnamese Law\n- Premium Private Medical Insurance PVI and annual health check\n- 15-day annual leave, Christmas leave and 30-min menstrual leave for women\n- Company trip, YEP and monthly gathering time\n- Gifts on special occasion and fully stocked snack corner\n- Sponsored training courses and book purchase quarterly\n- Be well-equipped with new working equipment\n\nSPECIAL OFFER\n- Providing training and education experience in Korea with Korean Finance/IT expert.\n- Providing opportunities to work and support in IT/Finance fields overseas.\n\nHIRING PROCESS: The interview will be conducted at our office in Ho Chi Minh city.\nRound 1:\n- Step 1: Live coding test\n- Step 2: Interview with part team leader (upon passing coding test)\n- Step 3: Interview with Director\nRound 2: Final interview with Head Office in Korea', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '14F, AP Tower, 518B Dien Bien Phu Street, Ward 21, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(261, 230, 2, 'Product Owner (B2B Product)', 'We are looking for a hands-on Product Owner to help drive the delivery of B2B software solutions that generate meaningful business outcomes. You will play a key part in aligning priorities, managing the product backlog by working closely with cross-functional teams, and ensuring that every product release is executed smoothly and delivers measurable business impact. While some product areas incorporate AI technologies to enhance efficiency and value, the focus of this role is on delivering practical, effective solutions that address real-world challenges.\n\nEnsure that our B2B product roadmap is defined and managed in a way that aligns with client demands and company strategy. Own up to the business outcomes, rather than focusing on completing tasks or delivering features.\nDefine and manage the product backlog, ensuring it is well-prioritized, clearly documented, and aligned with business goals.\nWork closely with engineering, design, and other teams to translate business and client requirements into actionable user stories, specifications, and acceptance criteria.\nManage stakeholder expectations, keeping all relevant teams informed of progress, timelines, and trade-offs (between scope, speed, and quality).\nConduct market and competitor research to identify trends, gaps, and opportunities for differentiation.\nSupport and assist commercial teams by providing product insights, roadmaps, and feature updates that help drive client engagement and satisfaction.\nMonitor product performance and gather user feedback post-release to identify opportunities for continuous improvement.\n\nYour skills and experience\n\nAt least 2+ years of experience working in product-related roles, preferably within B2B software solutions.\nA strong product mindset — you prioritize solving the right problems, focus on achieving outcomes, and balance business goals with user needs rather than just delivering tickets.\nOwnership attitude — you take responsibility for results, follow through on commitments, and help push things forward when obstacles arise.\nProven ability to break down complex business requirements into clear deliverables, manage the product backlog, set priorities, and balance trade-offs.\nComfortable working directly with engineers, designers, commercial teams, and non-technical stakeholders — you know how to adjust your communication style to keep everyone aligned and informed.\nFlexible and adaptable, able to adjust quickly to shifting priorities without losing focus on outcomes.\n\nWhy you\'ll love working here\n\nAt Got It, we invest in people who grow with us — and foster a culture that values both personal and professional development.\nOpportunities to learn and grow through internal training, rotation, and career advancement.\nESOP program – grow together and share in the company’s achievements.\nComprehensive healthcare with Bao Viet and full statutory benefits.\nFull gross salary during probation.\nAnnual salary review based on performance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '102 Nguyễn Đình Chính, Phường 15, Quận Phú Nhuận, TP. HCM, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(262, 231, 2, 'Senior IT Executive (Salary from Usd1.000 to 1.500)', 'Top 3 reasons to join us\n• Performance Bonus\n• Personal Accident and Health Care Program\n• ParkCity Hanoi Club Staff Membership\n\nJob description\nIT MANAGEMENT\n1. Administer network workstations: Anticipate communication and networking problems and implement preventive measures. Investigate, recommend and install enhancements and operating procedures that optimize network availability. Troubleshoot networks, systems, and applications to identify and correct malfunctions and other operational difficulties.\n2. Plan and implement network security, including building firewalls, applying cryptography to network applications, managing host security, file permissions, backup and disaster recovery plans, file system integrity, and adding and deleting users. Maintain confidentiality with regard to the information being processed, stored or accessed by the network.\n3. Maintain licenses for department/organization. Document network problems and resolutions for future reference. Perform and/or oversee software and application development, installation, and upgrades.\n4. Investigate user problems, identify their source, determine possible solutions, test and implement solutions. Ensure timely user notification of maintenance requirements and effects on system availability.\n5. Install, configure, add or upgrade and maintain personal computers, file servers, ethernet networks, network cabling, and other related equipment, devices, and systems.\n6. Assist users in maximizing use of networks and computing systems.\n7. Plan periodic maintenance, repair, upgrade and recommend purchases of computers, peripheral equipment, network hardware and software.\n8. Update new IT products, system solutions, and applications of new technology regarding Enterprise IT Management System.\n\nOFFICE EQUIPMENT\n9. Maintain and troubleshoot the office equipments/machines electrical devices (telephone system, facsimile, photocopiers, printer, etc.) to make sure those are in good condition and operation\n10. Recommend and supervise the office equipment’s supplier and maintenance service providers\n11. Perform other duties as assigned by superior from time to time.\n\nYour skills and experience\n• Bachelor degree in Informatics Technology\n• Obtaining CCNA/ MSCA Certificate is preferable\n• Minimum of 5 year working experience at the same position\n• Comprehensive Technical Expertise\n• Software Knowledge & Integration\n• Leadership & Independence\n• Excellent Communication & Soft Skills\n• Loyalty & Stability\n• English Proficiency\n\nWhy you\'ll love working here\n• Office hours: Monday- Friday, off on Saturday and Sunday.\n• Annual holidays leave will be following Vietnam law and as company regulations.\n• Social insurance, health insurance and unemployment insurance will be under Labor Law.\n• Healthcare insurance package\n• Dynamic and youthful working environment\n• Professional development opportunities.\n• ParkCity Hanoi Club Membership', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khu đô thị ParkCity Hanoi, đường Lê Trọng Tấn, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(263, 232, 2, 'UI/UX Designer (Mid/Senior, English Required)', 'Fullerton Healthcare Group is looking to expand its technical capabilities to enhance our service offerings and improve internal processes. There is ample opportunity to grow and learn with the deeply motivated team at Fullerton Healthcare Group. We are looking for candidates with deep expertise in User Experience and User Interface design work for both web and mobile applications. UI/UX Designers responsibilities include gathering user requirements, designing graphic elements and building navigation components. To be successful in this role, you should have experience with design software and wireframe tools. We believe that you also have a portfolio of professional design projects that includes work with mobile applications that is ready to be discussed on the interview.\n\nResponsibilities \n\n- Gather and evaluate user requirements in collaboration with product managers, and engineers\n- Develop wireframes, prototypes, and interactive mockups to illustrate how the app function and look like.\n- Design system-wise components (interface elements, like menus, tabs…)\n- Prepare and present rough drafts to internal teams and key stakeholders\n- Plan and conduct cross-functional (BA, PM, Engineering…) product strategy and implement to facilitate UX creation and ensure design output\n- Ensure consistent and intuitive user experiences across multiple devices and platforms.\n- Identify and troubleshoot UX problems and conduct adjustments based on user feedback\n- Create original graphic designs (e.g images, sketches and tables)\n- Design videos to introduce upcoming mobile products\n- Collaborate with developers to ensure accurate implementation of design specifications.\n- Stay updated with the latest design trends, tools, and technologies to continuously improve design processes. \n\nYour skills and experience\n\n- Bachelor’s degree in Design, Human-Computer Interaction, or a related field (or equivalent practical experience).\n- At least 2 years of experience in UX/UI Design \n- Proven work experience as a Designer with a strong portfolio showcasing your design expertise. \n- Demonstrated ability to create visually appealing and intuitive user interfaces for web and mobile applications.\n- Knowledge of Figma (Adobe Suite is a plus) \n- Basic knowledge of video\n- Team spirit and strong communication skills to collaborate with various stakeholders\n- Good multi-tasking and time-management skills\n- Good English written and oral proficiency\n- [Bonus] Experienced in the Healthcare industry is preferable \n\nWhy you\'ll love working here\n\n- A young and dynamic team where you can develop your career path and improve your English skills\n- An exciting project which uses cutting-edge technology\n- 14 days annual leave per year\n- 13th-month salary\n- Social insurance, Health insurance, Unemployment insurance are contributed based on full salary package \n- Private insurance for employees. After 1 year, company will cover the insurance for family members (spouse, children)\n- Providing Laptop to work\n- Company trip \n- Annual health check \n- Monthly teambuilding activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1st Floor, L’Mak Plaza (Nam A Plaza), 127 Hong Ha, Ward 09, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(264, 233, 2, 'Software Engineer – Mining Machine & Mass Production', 'We are looking for a skilled Software Engineer to join our mining machine development team. The ideal candidate will have solid experience in embedded Linux firmware, ASIC-based mining software, and mass production environments. You will play a key role in building reliable, high-performance firmware that powers cutting-edge cryptocurrency mining machines.\n\nKey Responsibilities\n- Develop and maintain firmware for embedded Linux platforms (e.g., CGMiner or similar mining frameworks)\n- Design and implement firmware for MCU-based power supply control systems\n- Collaborate with the hardware engineering team to ensure seamless system integration\n- Perform software quality assurance (QA) and stress testing prior to mass deployment\n- Conduct diagnostics and failure analysis during production and post-deployment\n- Perform thermal simulation and analysis to optimize heat dissipation and cooling systems\n- Ensure firmware stability, scalability, and performance in mass production environments\n- Contribute to the automation of software testing and deployment pipelines.\n\nYour skills and experience\nJob Requirements\n- Bachelor’s or Master’s degree in Computer Science, Electrical Engineering, or a related field.\n- Direct experience with ASIC-based mining software development or optimization.\n- Proven experience in mass production of mining machines or embedded systems.\n- Solid understanding of blockchain protocols and cryptocurrency mining mechanisms.\n- Experience with embedded Linux and mining tools such as CGMiner, BFGMiner, or equivalents.\n- Familiarity with power management ICs, thermal control, and cooling system optimization.\n- Proficiency in MCU firmware development (e.g., STM32, ESP32, or similar).\n- Ability to conduct and interpret thermal simulations using relevant tools.\n- Experience in automated software testing frameworks for embedded systems is a plus.\n- Strong analytical and problem-solving skills; ability to work in fast-paced environments.\n\nPreferred Qualifications\n- Experience in hardware-software co-design.\n- Knowledge of production-line testing and debugging tools.\n- Understanding of reliability engineering for high-uptime systems.\n\nWhy you\'ll love working here\n- Competitive salary based on experience and skills.\n- Professional working environment with a clear promotion roadmap.\n- Salary review and performance bonus every year.\n- Full social insurance, health insurance, and travel allowances.\n- Opportunities to work on advanced semiconductor projects with cutting-edge 5nm and 2nm technologies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3 Nguyen Luong Bang, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(265, 234, 2, 'Solution Architect (JavaScript, English)', 'Top 3 reasons to join us\n- Strong Management Team and Talents\n- Attractive salary and benefits\n- Full social insurance and PVI Healthcare Insurance\n\nJob description\n- System Architecture Design: Develop and maintain the infrastructure architecture of software systems, ensuring scalability, efficiency, and long-term sustainability.\n- Requirements Analysis & Solution Design: Analyze technical requirements from project teams and clients, proposing solutions that align with business goals.\n- Database Architecture: Design and optimize database systems, ensuring scalability and high performance in production environments.\n- Security & Performance Assurance: Build solutions with high security standards and optimize system performance for large-scale systems.\n- Collaboration with Development Teams: Work closely with software development, DevOps teams, and stakeholders to ensure alignment in system design and implementation.\n- Monitor and Improve Solutions: Continuously monitor and improve technical solutions to ensure ongoing development and success of software systems.\n- Scalability & Maintainability: Create architecture designs that are scalable and easy to maintain over time.\n- Introduce and Implement New Technologies: Propose and implement new technologies to keep the company at the forefront of technical advancements.\n\nYour skills and experience\n- At least 8 years of experience in software development, with at least 3+ years as a Solution Architect.\n- Deeply understand JavaScript and had experience in Front-end (ReactJS) & Back-end (NodeJS) frameworks.\n- Strong understanding and experience of:\n  - Knowledge well in design patterns;\n  - Clean code, coding standards, and code reviews & code refactoring;\n  - Unit tests, mocking libraries, code coverage;\n  - Can lead technical support and training;\n  - Detail-oriented and goal-driven person.\n- Having any of the below experience/knowledge is a plus:\n  - SSO & Microservice architecture\n  - GraphQL, PostgreSQL, MongoDB, ElasticSearch\n  - K8s, Docker\n  - System monitoring, TimeSeries Database (e.g. StatsD, InfluxDB, Graphite…)\n  - CI/CD with Gitlab, Azure DevOps, Bamboo, Bitbucket or similar tools\n  - Cloud services (GCP, AWS, or Microsoft Azure…)\n- Good command of English (written and spoken).\n\nWhy you\'ll love working here\n- Attracted salary based on the ability of the candidate and the general salary framework set by the company.\n- Salary review annually based on the work performance.\n- 13th-month salary and bonus for holidays.\n- Team building once a month.\n- Company trip once a year.\n- PVI healthcare insurance.\n- Full social benefits in accordance with the company and the law of Vietnam.\n- Professional environment and clear procedures.\n- Great opportunity to improve English.\n- Opportunity to learn Logistics and professional management system of project development process.\n\n(Please be noted that only selected candidates will be contacted via phone)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Scetpa Building, 19A Cong Hoa, Ward 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(266, 235, 2, 'Chuyên Viên Phát Triển Ứng Dụng', 'Top 3 reasons to join us\n- Trải nghiệm công nghệ tài chính hiện đại  \n- Nhận gói thu nhập cao  với nhiều chế độ phúc lợi\n- Làm việc tại văn phòng chuẩn Top A \n\nJob description\n- Nghiên cứu, đề xuất các giải pháp cung cấp kênh giao dịch trực tuyến cho người sử dụng đảm bảo tính thuận tiện, an toàn bảo mật và nhanh chóng cho các giao dịch điện tử.\n- Nghiên cứu, đề xuất, xây dựng mới/ nâng cấp các giao diện người sử dụng trên các kênh giao dịch trực tuyến.\n- Phát triển mới các phương thức/ tính năng giao dịch điện tử và thanh toán điện tử trên các kênh giao dịch trực tuyến.\n- Xây dựng hệ thống tra soát đối soát phục vụ cho các giao dịch điện tử.\n- Tiến hành phối hợp với các Phòng/ Ban trong Khối CNTT và Khối/ Phòng/ Ban có liên quan trực tiếp đến yêu cầu để kiểm thử hệ thống\n- Lập tài liệu kỹ thuật, chuyển giao các ứng dụng, dịch vụ cho các đơn vị hỗ trợ nghiệp vụ, vận hành và khai thác.\n- Hỗ trợ các đơn vị, vận hành hệ thống đã xây dựng và triển khai.\n- Khắc phục lỗi khi có yêu cầu từ phía nghiệp vụ và các đơn vị kinh doanh.\n- Quản lý mã nguồn của các ứng dụng liên quan.\n- Thực hiện các nhiệm vụ khác do Ban Giám đốc Khối và Trưởng phòng giao.\n\nYour skills and experience\n- Tốt nghiệp Đại học trở lên, chuyên ngành Công nghệ thông tin, Toán tin, Công nghệ phần mềm\n- Có kinh nghiệm ít nhất 3 năm lập trình Java/Mobile (Adroid, IOS)\n- Có kinh nghiệm làm việc với CSDL Oracle, lập trình ngôn ngữ PL/SQL\n- Có kinh nghiệm về các sản phẩm dịch vụ giao dịch và thanh toán điện tử của Ngân hàng.\n- Có kinh nghiệm về xây dựng các ứng dụng nội bộ trong Ngân hàng\n- Có khả năng đọc hiểu tài liệu Tiếng Anh chuyên ngành\n- Có kiến thức về giao dịch và thanh toán điện tử\n- Có kỹ năng nghiên cứu, nắm bắt công nghệ mới\n\nWhy you\'ll love working here\nQuyền lợi :  \n- Cơ hội tạo ra dấu ấn trong hành trình sự nghiệp số của bản thân khi tham gia xây dựng các dự án ĐANG phát triển và là TRỌNG ĐIỂM của Ngân hàng (thay vì xây dựng từ giai đoạn đầu).\n- Cơ hội trải nghiệm các kiến trúc, công nghệ mới nhất trên thị trường Tài chính - Ngân hàng.\n- Cơ hội nhận gói thu nhập hấp dẫn cùng với rất nhiều chế độ phúc lợi toàn diện chỉ dành cho các CBNV.\n- Cơ hội đào tạo chuyên môn, học hỏi từ những chuyên gia đầu ngành, luân chuyển công việc sang các phòng ban khác phù hợp với lộ trình thăng tiến nghề nghiệp.\n- Cơ hội làm việc tại văn phòng làm việc đạt chuẩn Top A với các trang thiết bị máy móc hiện đại nhất, tiên tiến nhất, tham gia những hoạt động thường niên của Ngân hàng nhằm nâng cao đời sống CBNV.\n\nPhúc Lợi :\n- Máy tính xách tay  \n- Bảo hiểm  \n- Phụ cấp (Thâm niên, Ăn trưa,...)  \n- Du lịch nước ngoài  \n- Đồng phục  \n- Thưởng  \n- Chăm sóc sức khỏe  \n- Đào tạo  \n- Tăng lương  \n- Chế độ nghỉ phép\n- Chế độ tập thể dục', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'LPBank Tower, 210 Tran Quang Khai, Trang Tien, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(267, 236, 2, 'Frontend Developer (JavaScript, HTML5, CSS, ReactJS)', 'NỘI DUNG CÔNG VIỆC:\n- Xây dựng hệ thống chiến lược nhằm tăng hiệu quả trên các nền tảng marketing online\n- Xây dựng hệ thống hỗ trợ nghiệp vụ có khả năng vận hành với quy mô lớn\n- Tham gia vào phát triển các dự án từ giai đoạn Basic Design, Detail Design, Development, Release\n\nYêu cầu chung:\n- Tốt nghiệp đại học trở lên.\n- Kinh nghiệm phát triển hệ thống Web > 2 năm\n- Kinh nghiệm sử dụng Git, GitHub hoặc GitLab > 2 năm\n- Sẵn sàng học hỏi và phát triển những ngôn ngữ mới\n\n2 năm kinh nghiệm:\n- Sử dụng HTML, CSS và BootStrap\n- Sử dụng JavaScript\n- Sử dụng NextJS, ReactJS và Redux\n- Sử dụng RestfulAPI\n\n1 năm kinh nghiệm\n- Phát triển dựa trên đám mây công cộng (AWS/Azure/GCP)\n- Phát triển theo phương pháp Agile\n- Kinh nghiệm phát triển dự án nhóm\n\nƯu tiên nếu có thêm kỹ năng sau:\n- Có hơn 1 năm kinh nghiệm phát triển hệ thông liên quan đến quảng cáo trực tuyến\n- Có kiến thức nền tảng về 00P, phát triển web, DBMS, ORM và mẫu thiết kế.\n- Có hơn 1 năm kinh nghiệm làm quản lý\n- Có hơn 1 năm kinh nghiệm làm ký sư cầu nối\n\nTHỜI GIAN LÀM VIỆC: \n- Từ Thứ 2 đến Thứ 6\n- Làm việc theo lịch của Nhật Bản\n- Khung giờ: 7h→16h\n- Lịch nghỉ: Thứ 7,CN và những ngày lễ Nhật (không nghỉ Lễ Tết Việt Nam)\n\nQuy trình phỏng vấn:\n- Xét duyệt CV\n- Phỏng vấn 1: trực tiếp (60 phút)\n- Làm bài test EQ online\n- Phỏng vấn 2: trực tiếp (60 phút)\n\n🌼 CHẾ ĐỘ:\n- Trang bị các thiết bị hiện đại hỗ trợ cho nghiệp vụ (Macbook Pro,....)\n- Cơ hội thăng tiến nhanh cho những bạn có tiềm năng\n- Cơ hội đi công tác onsite\n- Hỗ trợ tham gia các khóa học nâng cao kỹ năng, hỗ trợ chi phí thi chứng chỉ\n- Tiền mừng kết hôn, tiền mừng sanh con cho nhân viên của công ty\n- Du lịch hằng năm\n- Tiệc thân mật nhóm hàng tháng, phí taxi đi lại\n- Hỗ trợ phí gửi xe, phí xăng xe đi lại\n- Tham gia full lương đầu đủ các loại bảo hiểm\n- Xét duyệt tăng lương 2 lần/năm\n- Hỗ trợ chi phí hoạt động câu lạc bộ trong công ty\n- Lương tháng 13, và trả lương ngoài giờ theo lụa chọn Việt Nam\n- Làm việc ngày lễ Việt Nam lương +300%.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '72 Nguyen Thi Minh Khai, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(268, 237, 2, 'Business Analyst (BA)', 'Job description\n• Tham gia các dự án phần mềm, tiếp nhận, phân tích và chủ động tư vấn các yêu cầu về nghiệp vụ lĩnh vực liên quan Quy trình quản lý dự án.\n• Lập và chuẩn bị các tài liệu, hồ sơ cho yêu cầu phát triển và chuyển cho bộ phận lập trình thực hiện.\n• Tìm hiểu, nắm bắt các quy trình, quy định nghiệp vụ phải tuân thủ.\n• Kiểm soát việc đáp ứng yêu cầu nghiệp vụ của các bộ phận khác khi phát triển ứng dụng, đào tạo cho các thành viên dự án và những bên liên quan đều hiểu nghiệp vụ.\n• Tham gia phối hợp với tester kiểm tra kết quả phát triển, đảm bảo phù hợp với nội dung yêu cầu đã thống nhất.\n• Soạn thảo và ban hành tài liệu hướng dẫn sử dụng sản phẩm công nghệ cho người dùng cuối.\n• Thực hiện các công việc khác theo sự phân công của Quản lý trực tiếp.\n\nYour skills and experience\n• Tốt nghiệp Đại học chuyên ngành CNTT hoặc có liên quan\n• Có ít nhất 02 năm kinh nghiệm trở lên ở vị trí tương đương\n• Hiểu biết về quy trình nghiệp vụ, sản phẩm, dịch vụ, ứng dụng công nghệ là một lợi thế.\n• Nắm vững các kỹ năng thu thập, phân tích nghiệp vụ\n• Khả năng phân tích, xử lý vấn đề, diễn đạt vấn đề từ tổng quát đến cụ thể chi tiết mạch lạc, rõ ràng.\n• Tư duy logic tốt, nhanh nhạy, tinh thần trách nhiệm cao với công việc, thái độ làm việc tích cực.\n• Tiếng Anh tốt là một lợi thế.\n\nWhy you\'ll love working here\n• Thu nhập: thỏa thuận theo năng lực, deal trong phỏng vấn.\n• Thời gian làm việc: Thứ Hai – hết Sáng thứ 7\n+ Ca sáng: 8h30 – 12h00\n+ Ca chiều: 13h30 – 18h00\n• Được học hỏi, đào tạo và tham gia vào các dự án lớn theo xu hướng công nghệ 4.0 trong lĩnh vực: Chính phủ, Y tế 4.0, Doanh nghiệp.\n• Môi trường làm việc thân thiện, năng động;\n• Được tham gia bảo hiểm đầy đủ theo quy định của pháp, Du lịch/nghỉ mát cùng công ty hàng năm;\n• Lương tháng 13, thưởng cuối năm, xem xét tăng lương hàng năm;\n• Tham gia các hoạt động văn hoá, sự kiện hấp dẫn của Công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, tòa nhà SanNam, 78 Duy Tân,, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(269, 238, 2, 'Security Engineer - (Red Team)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Thực hiện việc rà soát, đánh giá/kiểm thử an ninh thông tin hệ thống\n- Tiến hành các cuộc thử nghiệm thâm nhập của Red Team, mô phỏng những cuộc tấn công trong thế giới thực, chỉ ra những điểm yếu của nội bộ và hệ thống SOC.\n- Thực hiện đào tạo chia sẻ với các thành viên trong đội nhóm.\n- Thực hiện các công việc khác theo yêu cầu của Manager đề ra.\n\nYour skills and experience\n- Tốt nghiệp Đại học (chính quy, công lập, dân lập trong nước hoặc Đại học tại nước ngoài) trở lên thuộc các chuyên ngành: An ninh mạng (Cybersecurity), An toàn thông tin (Information Security), Bảo mật thông tin và mật mã (Cryptography & Information Security), Công nghệ Thông tin, Hệ thống thông tin, Kỹ thuật phần mềm, Kỹ thuật mạng, Quản trị hệ thống và Mạng, Điện tử - Viễn thông...\n- Hiểu rõ root-cause các lỗ hổng bảo mật (theo OWASP, CWE), cách exploit (manual – không sử dụng các công cụ tự động).\n- Hiểu biết về các phase trong Redteam. Có kinh nghiệm sử dụng các công cụ hỗ trợ trong quá trình Pentest cũng như các công cụ trong từng Redteam phase.\n- Có khả năng code một trong những ngôn ngữ scripting để viết mã exploit (Bash, Powershell, Python, Perl, Java, .Net, ...), có khả năng sửa, tạo các exploit cho web, OS...\n- Có khả năng nghiên cứu chuyên sâu, cách debug trên các ngôn ngữ nhằm xây dựng lại exploit liên quan tới các lỗ hổng bảo mật 1-day (Nếu có phát hiện các lỗ hổng 0-day là một lợi thế)\n- Có hiểu biết về các cơ chế phòng thủ/giám sát của blue-team nhằm tìm cách bypass/ẩn mình trước các cơ chế này là một lợi thế.\n\nWhy you\'ll love working here\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n\nCơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n\nMôi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng\n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(270, 238, 2, 'Business Analyst (Project Manager, Agile)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Tiếp nhận các yêu cầu về sản phẩm, dịch vụ đối với CNTT\n- Thực hiện nghiệp vụ phân tích, làm rõ yêu cầu và thống nhất với các bên liên quan\n- Xây dựng các tài liệu phân tích, đặc tả yêu cầu, mô hình hóa quy trình nghiệp vụ\n- Tham gia giám sát quá trình kiểm thử nhằm đảm bảo chất lượng của hệ thống CNTT đáp ứng đúng và đủ yêu cầu đã đặt ra\n\nYour skills and experience\n- Tốt nghiệp hệ chính quy các Trường Đại học trong nước hoặc nước ngoài\n- Chuyên ngành đào tạo: Công nghệ thông tin, Toán tin, Điện tử Viễn thông, kế toán, Tài chính Ngân hàng\n- Có ít nhất 01 năm kinh nghiệm trong công tác phân tích nghiệp vụ tại các Ngân hàng, Tổ chức Tài chính, Tập đoàn & Công ty về CNTT\n- Ưu tiên ứng viên có kinh nghiệm quản lý dự án\n- Có kiến thức tổng quan về ngân hàng và am hiểu sâu nghiệp vụ ngân hàng\n- Có hiểu biết/kinh nghiệm thực tế về các nghiệp vụ ngân hàng. Đã từng làm việc với các hệ thống T24, Kondor, Way4 là một lợi thế\n- Ưu thế khi ứng viên có kinh nghiệm làm việc theo các phương pháp Agile  \n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…  \n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương  \n- Cơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng  \n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng  \n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.  \n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)  \n- Môi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng  \n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(271, 239, 2, 'Women Leadership in Tech', '*** Ignite your Impact – Women Leadership in Tech ***\nWe’re empowering and promoting women in leadership roles in Engineering and Software Development. This is an incredible opportunity to connect with like-minded professionals, share insights, and unlock new growth opportunities.\n\nKey Responsibilities\n\nLeadership & Team Development: Lead, mentor, and develop a high-performing team of engineers, fostering a collaborative, inclusive, and supportive environment.\nBusiness Development: Leverage technical expertise to identify and drive new business opportunities, defining strategies for regional business growth.\nProject Management: Oversee the planning, execution, and delivery of software projects, ensuring timely and high-quality completion.\nTechnical Expertise: Provide hands-on guidance in product life cycle. Stay updated with emerging technologies to drive innovation.\nStakeholder Collaboration: Work closely with cross-functional teams to align business goals.\nProcess Improvement: Enhance engineering processes to boost efficiency, quality, and team performance. Encourage best practices in software development and testing.\n\nYour skills and experience\n\nWho is this for?\nAmbitious Women in Tech and aspiring to move into leadership positions.\nEstablished female leaders looking to expand their influence and mentor others.\nAllies and organizations committed to fostering diversity and inclusion in leadership.\n\nWhy join?\nAccess to exclusive leadership development resources\nOpportunities for mentorship and coaching from seasoned women leaders.\nNetworking with a community of dynamic, forward-thinking professionals\nInsights on overcoming challenges unique to female leaders in today’s workplace\nInvitations to webinars, workshops, and networking events focused on leadership growth.\n\nJoin us now to break barriers, share knowledge, and elevate the voices of women in leadership. Together, we’ll build a diverse, inclusive, and transformative future.\n\nWhy you\'ll love working here\n\nWHY BOSCH?\nBecause we don\'t just follow trends, we create them. Because together we turn ideas into reality, working every day to make the world of tomorrow a better place. Do you have high standards when it comes to your job? So do we. At Bosch, you will discover more than just work.\n\nBenefits and Career Opportunities\nWorking in one of the Best Places to Work in Vietnam and Top 30 of the Most Innovative Companies all over the world\nJoin a dynamic and fast-growing global company (English-speaking environment)\n13th-month salary bonus + attractive performance bonus (you\'ll love it!) + annual performance appraisal\n100% monthly salary and mandatory social insurance in 2-month probation\nOnsite opportunities: short-term and long-term assignments\n15++ days of annual leave + 1 day of birthday leave\nPremium health insurance for employee and 02 family members\nFlexible working time\nLunch and parking allowance\nVarious training on hot-trend technologies/ foreign language (English/Chinese/Japanese) and soft skills\nFitness & sports activities: football, badminton, yoga, Aerobic\nFree in-house entertainment facilities and snack\nJoin in various team building, company trips, year-end party, tech talks, and lots of charity events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa street, ward 13, Tan Binh, Ho Chi Minh; Capital Place, 29 Lieu Giai Street, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(272, 240, 2, 'Sr/Mid Fullstack Developer (NodeJS, Golang, PostgreSQL)', 'Be a part of our Development Team developing high quality B2B e-Commerce eco-system. Responsibilities Design and develop user-friendly, responsive, and visually appealing frontend interfaces using ReactJS. Design and develop services which can handle a massive amount of data. Design and implement API endpoints for the API backend in Nodejs/Golang. Write clean, maintainable, and efficient code. Give solutions to improve business & operation performance. Reporting to the Manager Write Unit test/Document. Your skills and experience Required Job Skills 2 + year experience in FrontEnd/Full Stack position. Good knowledge of client language: JavaScript and TypeScript. Experience with modern backend technologies using Golang/Nodejs. Good knowledge of SQL Good knowledge of ReactJS, HTML, CSS. Experience with database system: Postgres/Mysql/Cassandra. Experience with responsive design and making websites work in different browsers. Familiarity with front-end tools (SSR, State Management, UI Kit…). Willingness to research, learn new programming languages and frameworks. Strong ability to solve problems and think critically. Nice to have: Excellent communication skills both in writing and in person. Experience with state management libraries such as Zustand or Jotai. Understanding of server-side rendering. Good knowledge of eCommerce, Saas, etc. Knowledge of Integrations with various Third-party Library/Service. Experience with Kafka, Redis, Elasticsearch and knowledge of Caching is a plus. Familiarity with design tools such as Sketch, Figma. Experience in developing a Chat system is a big plus. Experience in developing a CRM system is a big plus. Why you\'ll love working here Competitive salary and regular performance reviews. Flexible working hours, hybrid or remote-friendly environment. Fast-growing company with clear career development opportunities. Young, talented, and passionate team. Annual bonus, 13th-month salary, team building, and full labor benefits.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Roman Plaza, Tố Hữu, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(273, 203, 2, 'Senior/Team Lead Product Designer', 'The Role\nAs a Senior/Team Lead Product Designer, you’ll work with a cross-functional, highly capable team of designers, researchers, product owners, and engineers inventing and iterating end-to-end product experiences. We are looking for designers who are passionate yet capable of analyst customer behaviors and identifying opportunities while being able to articulate human-centered approaches in a fast-paced environment. We’re a young and passionate team committed to creating a convenient, delightful, and intelligent user experience.\nJob Description\n• Experience working with qualitative and quantitative data that helps ground your decisions in real data, the marketplace needs & norms, and business OKRs.\n• Experience building for a consumer audience\n• Ability to work collaboratively across cross-functional teams.\n• Examples of developing and conveying ideas clearly in a written and visual format—clearly demonstrate how your designs tackle customers’ problems or add value to their lives\n• Highly proficient with design tools (Figma, Photoshop, Illustrator, etc.)\n• Ability to facilitate team discussions and help drive decisions\n• Experience building products for Android or iOS and web\n• Knowledge of mobile and web design patterns\n\nYour skills and experience\n• 4+ years of Product Designer (or UIUX Designer) design experience, expert-level responsive web design.\n• Min 1-2 years of experience in team management\n• Experience designing and conducting user research, including contextual inquiry and usability testing\n• Strong understanding and application of user-centered design methods and principles\n• Excellent deliverables, including prototypes, detailed page schematics, sketches, interaction flows, site maps, navigation systems, and web-appropriate writing\n• Ability to work well with the engineering team and the product team to articulate issues and communicate persuasively\n• Experience working in small collaborative teams.\n• A portfolio showing thoughtful problem-solving and high-quality visual design.\n• Fluency with current product design patterns and tools.\n\nWhy you\'ll love working here\n• Ahamove has 7+ products and 20+ services. If you love to be challenged with significant problems, we have a place for you.\n• Our culture is bottom-up innovation, so your imagination is the only limit.\n• You will be your boss, and of course, fighting with other bosses. Those who have the most insight will be the decision-maker.\n• Play an important role in the product development of AHA, both internally and externally\n• A chance to practice managing complex products that can offer a high-value proposition to the customer\n• Gauge your technical skill in massive projects and a fast-pacing environment\n• Sharp, motivated colleagues in a fun office environment\n• Competitive salaries and benefits according to experience and education level\n\nBenefit and Allowances\n• Grab/Be for work: 1M/month\n• Laptop & PVI insurance\n• Competitive salaries and benefits according to experience and education level\n• And more', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Rivera Park 7/28 Thành Thái, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(274, 209, 2, 'Senior C++ Software Engineer - Salary up to $3000', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n- Participate in the design, coding and testing of software for IVI (In-Vehicle Infotainment) system in Automotive domain\n- Developing and maintaining core system components\n- Optimizing system performance\n- Collaborating on platform architecture\n- Ensuring compatibility across devices\n- Profiling and optimizing system performance\n- Implementing security features\n- Working with cross-functional teams\n\nYour skills and experience\n- Graduated from a university specialized in Electronics Engineering, Automatic Control, Automation, Computer Science, or related fields.\n- At least 3-5 years of experience working with Android framework/platform\n- Have participated in successful projects related to embedded software\n- Demonstrated proficiency in C/C++ programming language\n- Experience in OOP, Design Patterns, SOLID principles, UML\n- Deep understanding about Android HAL (Hardware Abstraction Layer)\n- Deep understanding about VTS (Vendor Test Suite)\n- Demonstrated proficiency in AOSP build system\n- Deep understanding about Android partition, Android boot process, Android Security model, Android GKI\n- Demonstrated proficiency in Kernel Driver development (Interrupt, Spinlock, multi-threading, …), Bootloader development, Device tree.\n- Demonstrated proficiency in Android SELinux\n- Experience in Communication Protocols (I2C, SPI, UART, …) and Linux Kernel concept: Interrupt, Spinlock, multi-threading…\n- Experience in working with AOSP project, native HAL service, Android Frameworks (service, provider, activity, windows)\n- Proficiency in using tools and software related to embedded software design\n- Effective use of Git, Gerrit code review, CI/CD tools (Jenkins, QuickBuild, …)\n- English: TOEIC 600+\n- Soft skill: Strong Organizational, Analytical, Problem solving, Proactive, Teamwork, Independent work\n\nWhy you\'ll love working here\n- FPT Care insurance plan tailored for FPT employees\n- Attractive annual summer vacation allowance\n- Sponsored training courses for personal growth and up to 100% coverage for certification costs\n- Global and inclusive workplace with monthly cross-cultural events\n- International exposure and career growth across global locations\n- Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Building, 17 Duy Tân Str., Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(275, 241, 2, 'Senior AI Engineer (Python) -Up to 50M', '1. Phát triển và triển khai mô hình AI:\n- Thiết kế, xây dựng và tối ưu hóa các mô hình machine learning và deep learning.\n- Triển khai các mô hình AI vào môi trường sản xuất.\n- Giám sát và đánh giá hiệu suất của mô hình AI, thực hiện các điều chỉnh cần thiết.\n\n2. Nghiên cứu và phát triển:\n- Nghiên cứu các xu hướng và công nghệ AI mới nhất.\n- Đề xuất và triển khai các ý tưởng sáng tạo nhằm cải thiện các giải pháp AI hiện có.\n- Thử nghiệm và đánh giá các thuật toán và mô hình AI mới.\n\n3. Xử lý và phân tích dữ liệu:\n- Thu thập, xử lý và phân tích các tập dữ liệu lớn để huấn luyện và đánh giá mô hình AI.\n- Phát triển các quy trình xử lý dữ liệu hiệu quả.\n- Trực quan hóa dữ liệu và trình bày kết quả phân tích.\n\n4. Hợp tác và giao tiếp:\n- Làm việc chặt chẽ với các thành viên nhóm AI, kỹ sư phần mềm và các bên liên quan.\n- Truyền đạt rõ ràng và hiệu quả các khái niệm AI và kết quả nghiên cứu.\n- Hỗ trợ và hướng dẫn các kỹ sư AI cấp dưới.\n\n5. Tham gia xây dựng chiến lược:\n- Đưa ra các phân tích và đề xuất liên quan đến việc ứng dụng AI một cách hiệu quả trong hoạt động kinh doanh.\n\nYour skills and experience:\n- Bằng cử nhân hoặc thạc sĩ chuyên ngành Khoa học Máy tính, Trí tuệ Nhân tạo, Thống kê hoặc các ngành liên quan.\n- 3 - 5 năm kinh nghiệm làm việc trong lĩnh vực AI, đặc biệt là các dự án về machine learning và deep learning.\n- Am hiểu sâu sắc các thuật toán và mô hình machine learning, bao gồm các mô hình deep learning.\n- Thành thạo các ngôn ngữ lập trình (Python, TensorFlow, PyTorch, v.v.).\n- Có kinh nghiệm sử dụng các công cụ và nền tảng AI (AWS, Google Cloud, Azure).\n- Kỹ năng xử lý và phân tích dữ liệu mạnh mẽ.\n- Khả năng giải quyết vấn đề và tư duy phản biện tốt.\n- Kỹ năng giao tiếp và làm việc nhóm hiệu quả.\n\nWhy you\'ll love working here:\n- Mức lương: upto 50M (thoả thuận khi phỏng vấn)\n- Tham gia đầy đủ BHXH theo quy định\n- Công ty cung cấp thiết bị làm việc\n- Tăng lương, xét thưởng dựa trên năng lực, hiệu quả công việc\n- Đánh giá lương 6 tháng 1 lần và theo các chiến dịch\n- Thưởng nhân viên xuất sắc, Chính sách thưởng tháng lương 13, thưởng 2/9, thưởng Tết dương lịch và các ngày lễ khác trong năm.\n- Chính sách thăm hỏi toàn diện cho nhân sự: sinh nhật, kết hôn, sinh con, ốm đau,...\n- Các hoạt động thể thao, văn hóa đa dạng và phong phú: CLB đá bóng, đạp xe, cầu lông,...\n- Các hoạt động nội bộ khác: Year End Party, Team Building, Party,...\n- Thời gian làm việc: thứ 2 - thứ 6', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa MD Complex, 68 Nguyễn Cơ Thạch, Mỹ Đình 1, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(276, 242, 2, 'Remote -Sr. React Native Engineer (ReactJS, Javascript)', 'Working time: 9AM - 6PM Vietnam Time\nWork location: Remote in Vietnam\nDomain: Insurance, Finance, E-commerce\n\nWe are looking for Senior React Native Developers to work on our projects. You will be delivering complex, fully bespoke mobile software solutions and helping this large, expanding global financial organization to expand their front-end team. In this role, you can expect exciting projects, inclusive forward-thinking culture, and some great learning opportunities.\n\nOn a day-to-day basis, the software engineer will put their experience to good use working closely in a multi-disciplinary scrum team to deliver responsive, high-quality web applications alongside gaining experience in modern cloud deployment best practices.\n\nThe Senior React Native Developer must have the following key skills:\n- 5+ years of experience in React & React Native\n- Strong fundamental CSS, JS, Typescript, ECMA\n- Backend experience with Node.js/GraphQL is preferable\n- Experience with MongoDB\n- Professional understanding of RESTful and SOAP APIs\n- Worked within an Agile team\n- Good English communication skills\n- Problem-solving- should be able to explain ideas, analyze solutions’ complexity and implement them perfectly.\n\nIt would be a bonus if you had some or all the following:\n- Experience in the finance sector\n- Java Spring boot\n\nWhy you\'ll love working here:\nWorking with us:\n- Working time: 9am - 6pm (Vietnam Time)\n- 12 days of annual leaves\n- Extra pay for Overtime\n- Salary package received in NET amount (USD)\n\nPerks:\n- Work from home: our entire company has worked virtually since inception. We have well-developed systems and processes to support remote work.\n- Rapid Growth Business: our company is growing rapidly and there is opportunity to grow with our team.\n- Excellent Team Culture and a positive, supportive environment. Relaxed, friendly vibe with a regional HQ.\n- Events: Company Trips, Team building, Year End Party\n- Devices support after probation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote in Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(277, 243, 2, 'Developer Experience Engineer (English, DevOps)', 'This position is responsible for designing, building, and maintaining platforms, tools, and processes to enhance the developer experience and improve engineering productivity. You will work closely with development teams to understand their needs, automate processes, and promote best practices in software development.\n  Responsibilities\n- Collaborate with development teams to analyze requirements, design solutions, and create technical documentation.\n- Design, build, and maintain tools and platforms to improve the developer experience.\n- Automate development processes using tools like GitHub Actions.\n- Provide and maintain standardized development environments using Docker and DevContainers.\n- Collect and visualize key development metrics using tools like Apache DevLake.\n- Promote best practices in software development, testing, and deployment.\n- Support and train team members to enhance their overall skills.\n- Act as a "servant leader," helping development teams achieve their goals.\n- Contribute to the continuous improvement of development environments and processes.\nWe expect to join as senior level in our team and becoming leader/manager in the future.\nYour skills and experience\nMust have:\n- Experience with GitHub Actions or similar automation platforms.\n- Experience in software development or DevOps.\n- Ability to work independently, take responsibility, and stay self-motivated.\n- Passion for helping others and improving the developer experience.\n- Intermediate level in English communication.\nNice to have:\n- Experience with using AI solution for improve development experience for example experience with AI-powered code review tools.\n- Solid understanding of the Software Development Lifecycle (SDLC).\n- Hands-on experience with build automation tools like Maven.\n- Experience working with CI/CD pipelines and related tools.\n- Proficiency in containerization technologies like Docker.\n- Strong interest in the latest trends in CI/CD and development efficiency tools, with a proactive attitude toward trying them out.\n- Experience with development environment tools like DevContainers.\n- Experience with metrics collection and visualization tools like DevLake.\n- Experience working with cloud platforms such as AWS, Azure, or GCP.\n- Experience designing and implementing microservices architectures.\n- Experience working on large-scale, mission-critical systems.\n- Passion for helping others and improving the developer experience.\n- Excellent communication and teamwork skills.\n- Intermediate level in English communication.\n- Intermediate level in Japanese communication.\nWhy you\'ll love working here\n- Attractive Salary and Benefits\n- Working & growing with Passionate & Talented Team\n- Bonus: Annual Bonus, Performance Bonus.\n- Award: MVP for excellent Department/members\n- Annual health check-up\n- Social Insurance, Health Insurance, Unemployment Insurance (company will pay for full salary); Voluntary health insurance & accident insurance (PTI care 24/7)\n- Company trip, Big annual year-end party every year, Team building, etc.\n- Working hour: Monday to Friday (working hour from 08:00 to 17:00)\n- Training: Tech E-Learning & various training on hot-trend technologies, best practices and soft skills\n- Tech SHIMEKAI (Quarterly Technology Sharing)\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24th-25th Floor, A&B Tower, 76A Le Lai Street, Ben Thanh Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(278, 244, 2, 'E-commerce Business Developer (Digital Content)', 'Job description\n1. Phát triển nội dung số (Digital Content Creation)\n- Thiết kế hình ảnh sản phẩm, banner, poster, video ngắn,... phù hợp với từng nền tảng TMĐT (Shopee, Lazada, TikTok Shop, Facebook,...).\n- Sử dụng các công cụ AI hỗ trợ như Canva AI, CapCut AI, ChatGPT,... để tạo ra nội dung bắt trend, đúng thông điệp thương hiệu.\n- Viết mô tả sản phẩm, nội dung tương tác, câu chuyện thương hiệu trên nền tảng TMĐT & mạng xã hội.\n\n2. Quản trị và vận hành gian hàng TMĐT\n- Cập nhật thông tin sản phẩm: hình ảnh, giá, mô tả, tồn kho,...\n- Tối ưu hiển thị và trải nghiệm gian hàng để tăng chuyển đổi và tỷ lệ giữ chân người mua.\n- Phối hợp triển khai các chương trình flash sale, campaign theo mùa, sự kiện khuyến mãi.\n\n3. Cập nhật xu hướng và chiến lược triển khai\n- Theo dõi các xu hướng viral, âm nhạc, hashtag trên TikTok, Shopee, Meta để điều chỉnh nội dung phù hợp.\n- Đề xuất các chiến dịch truyền thông nội dung ngắn hạn và dài hạn nhằm tăng lượt xem, tương tác và doanh thu.\n\n4. Chăm sóc khách hàng và đối tác TMĐT\n- Duy trì mối quan hệ với khách hàng hiện tại, hỗ trợ trả lời thông tin sản phẩm, xử lý đơn hàng (nếu cần).\n- Giao tiếp cơ bản với các đối tác/nhà phân phối nếu có liên kết TMĐT ngoài.\n\nYour skills and experience\n- Có laptop cá nhân, tinh thần chủ động và trách nhiệm cao trong công việc.\n- Tốt nghiệp Trung cấp trở lên hoặc đang là ứng viên các ngành: Công nghệ thông tin, Marketing, Thương mại, QTKD, Truyền thông, Thiết kế,…\n- Không yêu cầu kinh nghiệm – sẽ được đào tạo từ đầu nếu bạn có thái độ tốt và tinh thần học hỏi.\n\nWhy you\'ll love working here\nThu nhập:\n- Lương chính thức: 12.000.000 VNĐ/tháng (tùy năng lực).\n- Lương đào tạo: thỏa thuận theo năng lực đầu vào.\n- Thưởng: theo hiệu quả công việc mỗi tháng.\n\nĐào tạo & hỗ trợ:\n- Được training các công cụ AI và kỹ năng vận hành thương mại điện tử từ A–Z\n- Làm việc trực tiếp với team nhiều kinh nghiệm, sẵn sàng hỗ trợ 1:1\n- Lộ trình phát triển rõ ràng:\n- Cơ hội thăng tiến lên Team Leader, Trưởng nhóm Content/TMĐT sau 6–12 tháng nếu thể hiện tốt\n\nMôi trường làm việc:\n- Trẻ trung, cởi mở, năng động – khuyến khích thử nghiệm & sáng tạo\n- Có team building, thưởng nóng, sinh nhật, du lịch, chế độ nghỉ phép đầy đủ...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '213 Điện Biên Phủ, Phường Võ Thị Sáu, Quận 3, TP. Hồ Chí Minh, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(279, 245, 2, 'Full Stack Developer (Java, Springboot, React)', 'LG CNS is looking for full stack developers for cloud domain project.\n\nYour skills and experience\n[Required]\n- Bachelor\'s degree of Information Technology or higher \n- Have working experiment and excellent knowledge at software developing using Java, Spring boot\n- Have working experiment and excellent knowledge at software developing using React, HTML, JavaScript\n- Good knowledge about AI (Azure OpenAI and GenAI)\n- Good knowledge about public cloud (Azure, AWS,)\n- Database: MariaDB (or MySQL).\n\n[Preferred]\n- Having experiment with Python and Google cloud\n\nWhy you\'ll love working here\n- Best remuneration: Periodically review and adjust salary once a year, PI bonus twice a. Allowances for lunch, transportation, and phone charges. Party with the team once a. Workshop travel for the whole company once a year. Bonuses/Gifts for holidays, International Labor Day, International Women\'s Day, etc.\n- High-class, modern office: 5-star standard office with modern equipment, large rest and entertainment areas (game area, karaoke room, reading room, cafe counter, snack bar, etc.) Meet all members\' needs, especially the office has an airy and beautiful view that is among the most beautiful in Hanoi.\n- Top equipment: Each employee is equipped with the latest generation LG Gram laptop and modern large LG screen.\n- Best working time: Work 8 hours/day (8:00 ~ 17:00), from Monday to Friday. No pressure to work overtime/weekends!\n- Flexible, youthful working style: LG CNS Vietnam members are mostly from the 9-10x generation, with a youthful, modern, and fair working style!\n- Creative environment, valuing individual opinions: With a young and talented team, we always appreciate the creativity and suggestions that members make.\n- Opportunities to work/study in Korea and abroad: With customers and projects mostly from abroad, your opportunities for training and onsite abroad will always be open!\n- Other: Happy hours every Friday, Team outing monthly, join clubs like football, badminton, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(280, 246, 2, 'Flutter Developer (IOS, Android, MVC, OOP)', 'Chúng tôi đang tìm kiếm Developer Flutter có ít nhất 2 năm kinh nghiệm để gia nhập đội ngũ phát triển sản phẩm lâu dài tại PickoNow. Nhân sự mới sẽ làm việc chặt chẽ với Product Owner, UI/UX Designer và các thành viên khác trong dự án để xây dựng và phát triển ứng dụng PickoNow, mang đến trải nghiệm tuyệt vời cho cộng đồng pickleball.\n\nPhát triển và bảo trì ứng dụng mobile trên nền tảng Flutter (Android/iOS).\nLàm việc với Product Owner và UI/UX Designer để hiện thực hóa giao diện người dùng.\nTích hợp API, Firebase hoặc các hệ thống backend khác.\nCải thiện hiệu suất ứng dụng, xử lý vấn đề về state management.\nKiểm tra, sửa lỗi và tối ưu ứng dụng trên nhiều thiết bị.\n\nCó tối thiểu 2 năm kinh nghiệm ở vị trí tương ứng (.NET hoặc Flutter).\nThành thạo lập trình hướng đối tượng (OOP), có hiểu biết về mô hình MVC hoặc MVVM.\nCó kinh nghiệm làm việc với các hệ thống API (RESTful API, GraphQL).\nKinh nghiệm với Git (GitHub, GitLab, hoặc Bitbucket).\nCó trách nhiệm với công việc, sẵn sàng học hỏi công nghệ mới.\nNếu biết cả .NET và Flutter là một lợi thế nhưng không bắt buộc.\nƯu tiên ứng viên có kinh nghiệm làm việc với CI/CD, Docker, Kubernetes.\n\nMức lương cạnh tranh theo năng lực.\nMôi trường làm việc năng động, chuyên nghiệp, có cơ hội thăng tiến.\nĐược làm việc với đội ngũ giàu kinh nghiệm, học hỏi và phát triển kỹ năng.\nHỗ trợ đào tạo, tham gia các khóa học nâng cao chuyên môn.\nĐược tham gia bảo hiểm và các phúc lợi theo quy định của công ty.\nChế độ thưởng theo dự án, hiệu suất làm việc.\nCơ hội làm việc trong ngành công nghệ thể thao và startup sáng tạo.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '188 A6 Nguyễn Văn Hưởng, phường Thảo Điền, Quận 2, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(281, 219, 2, 'Backend Java Developer (Spring, MySQL)', 'Authentic education Hub là nền tảng giáo dục số tiên phong trong việc phát triển các giải pháp học tập trực tuyến, và hệ sinh thái học liệu số. Với sứ mệnh “đưa giáo dục chất lượng cao đến với mọi học sinh”, chúng tôi đang tìm kiếm một BA tài năng để cùng xây dựng và tối ưu sản phẩm giáo dục phục vụ hàng triệu người dùng.\nNỘI DUNG CÔNG VIỆC\n- Phối hợp với các thành viên trong team tham gia vào toàn bộ vòng đời phát triển sản phẩm, chú trọng vào lập trình hệ thống. Giải quyết các vấn đề liên quan đến thiết kế và triển khai kỹ thuật cũng như thiết lập các giải pháp kỹ thuật.\n- Tư duy logic và đưa ra các giải pháp xử lý vấn đề trong quá trình phát triển sản phẩm cùng với các thành viên khác.\n- Sửa lỗi phát sinh và cải thiện hiệu suất hoạt động của sản phẩm, hệ thống.\n- Chịu trách nhiệm end-to-end về các tính năng mà mình phát triển.\n- Quyết định phương pháp lập trình và cách thức xử lý trong quá trình phát triển, vận hành sản phẩm.\n- Hỗ trợ trưởng nhóm về phân tích kỹ thuật để đưa ra giải pháp kỹ thuật tốt nhất cũng như hỗ trợ đồng nghiệp giải quyết các vấn đề kỹ thuật để hoàn thành dự án/nhiệm vụ được giao đúng thời hạn.\nYour skills and experience\n- Có ít nhất 3 năm kinh nghiệm làm các sản phẩm sử dụng công nghệ Java Developer.\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc lĩnh vực liên quan.\n- Am hiểu về công nghệ Java Backend (Spring framework, MySQL, Redis, ...). Hiểu rõ về lập trình hướng đối tượng.\n- Có tư duy logic, hệ thống; ưu tiên các ứng viên có giải thưởng liên quan đến cấu trúc dữ liệu và giải thuật.\n- Có kiến thức về quy trình, phương pháp phát triển phần mềm, methodologies, test-driven process, application architecture, và design pattern.\n- Am hiểu về GIT source control, Agile process, CI/CD\n- Có kỹ năng giao tiếp hiệu quả, làm việc nhóm tốt.\n- Có khả năng đóng góp và xây dựng sản phẩm.\n- Có khả năng hỗ trợ vận hành hệ thống.\nWhy you\'ll love working here\n- Mức lương thỏa thuận, cạnh tranh theo năng lực.\n- Thưởng thành tích xuất sắc theo năm.\n- Đánh giá hiệu suất công việc 2 lần/năm.\n- Chế độ tham gia BHXH, BHYT, BHTN theo quy định của Nhà nước.\n- Khám sức khỏe định kỳ hàng năm theo lịch của công ty.\n- Tham gia các hoạt động Sinh nhật, liên hoan hàng tháng, Year End Party, ...\n- Quà tặng, thưởng trong các dịp lễ lớn: Tết thiếu nhi, 2/9, Tết Dương Lịch, ...\n- Môi trường startup năng động, chuyên nghiệp, tư duy mở.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '5BT2, khu đô thị Mễ Trì Hạ, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(282, 247, 2, 'Technical Support Engineer - Java & C++', 'The Operate team provides Murex customers 24/7 technical support to restore normal operations with minimal impact on clients’ business. Along with incident management, Operate provides problem management and operability feedback to evolve the application, enhance user experience and reduce total cost of ownership for both clients and Murex. In order to support efficiently all types of critical incidents, the team has become highly skilled in collaborating cross functionally and working under pressure while continuously learning new skills/technologies and obtaining transversal application knowledge in a rapid evolving environment.\n\nRole Overview:\nThe Operate engineer will provide technical support with incident management practices on the Murex platform and Murex production chain while maintaining a high level of quality for both internal and external clients.\n\nRole Responsibilities:\n- Provide on-premises and cloud-based technical support while maintaining effective working relationships with internal and external clients.\n- Analyze and manage incidents and propose solutions according to the Service Level Agreements (SLAs).\n- Analyze Mx.3 application code and troubleshoot application errors, crashes, and performance issues.\n- Identify underlying root causes for recurring problems to improve the overall service of the team.\n- Identify potential technology enhancements to improve the technical support where possible.\n- Contribute to the knowledge database build and update.\n- Write and update documentation covering technical aspects of the Murex platform delivered to the clients.\n- Write troubleshooting procedures “How to’s” and other in depth technical documentation for internal utilization.\n- Share knowledge and expertise with team members and coach newcomers to leverage on technical skills.\n- Provide technical support to Murex offices as internal clients relying on other technical experts in Murex (System team, development team, architecture…) in order to enable them to focus on their own core business.\n\nTo be successful in the role, you should have:\n- Communication Skills: Good written and verbal communication skills in English are mandatory.\n- Flexibility to adjust working hours, including modified shifts (e.g., starting and finishing earlier, weekend, and holiday shifts.)\n- Bachelor or Master’s degree in engineering or computer science from a reputable university\n- 0-2 years relevant experience in troubleshooting technical issues\n- Good Programming Skills: Java, C/C++ (Python is a plus) - Ability to read and understand code is necessary\n- DB Skills: SQL (query building and performance analysis), DBA skills for Sybase and Oracle a plus\n- Advanced problem solving and decision making skills\n- Learning agility and ability to work under pressure in a continuously evolving environment\n- Client orientation\n- Cross group collaboration and team work\n- Drive for excellence', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Friendship Tower, 31 Le Duan, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(283, 248, 2, 'Tester (QA/QC)', 'Top 3 reasons to join us\n- Product 100K+ Global Users\n- Flexible time & 12 remote days\n- ~ 16 Month Salary and more\n\nJob description\nWhy we’re looking for you\nWe are looking for 1 Tester to assess software quality through Manual Testing for Ecommerce Domain. You will be responsible for ensuring that our products, applications and systems work well. You should have a keen eye for details, are organized and systematic, and highly passionate about quality.\nThis is a high visibility team where you will make a direct positive impact on customer experience and the business. If you enjoy broadening your technical skills, building a new product, and working in an environment that thrives on creativity, experimentation, and innovation, then you can be part of a warm and fun Scrum team engaging in web and mobile tests. Come value add us with your experience and expertise!\n\nYou’ll do\n- Study and analyze requirements and system specifications and technical design documents to provide timely and meaningful feedback\n- Work with internal teams (e.g developers and team leaders) to identify system requirements/the customer needs.\n- Create test design and test cases\n- Estimate, prioritize testing activities\n- Perform thorough regression testing/exploratory testing when bugs are resolved\n- Troubleshoot and report bugs and errors to development teams\n\nYour skills and experience\nYou have…\n- From 3 years of working experience in software Testing (API, Web, Mobile Testing, …), preferably in the ecommerce domain\n- Basic knowledge about UI/UX\n- Cross browser, cross platform, and responsive web/mobile testing experience\n- Familiarity with Agile frameworks\n- Analytical mind and good problem-solving skills\n- Proactive, responsible, organized, able to work independently, and gives attention to detail\n- Reading/writing in English at intermediate level. (TOEIC 500point)\n- ISTQB Foundation certification is plus\n\nWhy you\'ll love working here\nWe offer\n- Salary range: Negotiate\n- Performance review: 2 times per year\n- Yearly Salary Package: 13th-month salary bonus + Performance bonus: up to 3 months.\n- Lunch meal + Parking fees provided.\n- 12 remote working days/ year.\n- 12 annual leaves/ year.\n- Bonus on birthday, 30/4&1/5, 2/9.\n- Social insurance & Health insurance for team members.\n- Annual Health Checkup at the top clinic in Vietnam.\n- Weekly shoulder massage treatment.\n- Annual team building: summer trip, many indoor and outdoor activities such as soccer club, swimming club, cycling club…\n\nWhy you’ll love working here\n- Learn product-thinking and customer-centric mindset.\n- Collaborative and supportive environment\n- Young and passionate colleague\n- Professional and creative office view\n- Clear & Scientific Agile Framework on the whole company workflow & culture.\n- You are able to work as a member of a full process of product development. Even working with the CEO on new ideas. We want to develop and grow a strong product development team with expertise and skills we can be proud of through different products and battles.\n- Flexible working time:\n    - Morning: 8:00 am -12:00 pm (check in from 8:00 am to 8:45 am)\n    - Afternoon: 1:00 pm - 5:45 pm (check out from 5:00 pm to 5:45 pm)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '5th floor, Artemis Tower No. 3 Le Trong Tan, Khuong Mai, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(284, 249, 2, 'Business Analyst', 'About AILOGY\nAILOGY is part of a fast-growing tech group, building AI-powered SaaS platforms that help businesses optimize operations in finance, education, and customer engagement. Founded in 2025, we’re passionate about solving real-world problems with data and intelligent systems.\nOur teams move quickly, think big, and collaborate closely. We foster a culture of innovation where everyone feels empowered to share ideas, experiment, and grow. As we scale, we’re shaping strong development practices and making space for meaningful work.\nJoin us to build the future—smarter, faster, and with purpose.\n\nLife at AILOGY\nAt AILOGY, we nurture a supportive, inclusive environment where creativity and innovation thrive. We value transparency, open communication, and a positive, inclusive work culture.\nOur team is diverse and driven by a shared passion for AI, customer success, and making a real impact. We encourage idea-sharing, continuous learning, and personal growth—building a culture where professional development and career advancement are part of everyday life.\nWhether you\'re just starting out or growing into a leadership role, there\'s room here for you to thrive and help shape the future of AI.\n\nOverview\nWe are looking for a Business Analyst to join our fast-growing AI team. As a BA, you’ll turn complex ideas into clear, actionable deliverables—ensuring we deliver real value to clients and hit key milestones.\nAs we expand, we’re seeking someone eager to grow into a key role over time—such as a Product Manager or BA Manager. You’ll collaborate across teams, influence stakeholders, and help shape our BA practices from the ground up.\n\nResponsibilities\n1. Stakeholder & Team Communication\nGather and analyze business requirements; translate them into user stories, use cases and functional requirements.\nCollaborate with the Product Owner to manage the product vision, backlog, roadmap, and priorities.\nWork closely with Devs, QA, and Designers to define system design, and validate test cases.\nTrack project status, identify blockers, and ensure timely delivery.\n\n2. Business & Technical Analysis\nPrepare and maintain documentation such as BRD, FRDs, and process diagrams.\nCreate wireframes and diagrams using any tools like Figma, Visily, Miro, Draw.io, or others as preferred.\nConduct post-release analysis to evaluate feature adoption and user engagement.\n\n3. Process Improvement:\nIdentify and implement process improvements to optimize development workflows.\n\nYour skills and experience\nSkill and Qualifications\nAt least 4 years of experience as a Business Analyst (preferably fintech, Agile teams).\nStrong communication, presentation, and writing skills; able to speak both “tech” and “business” fluently.\nProficiency in process/data modeling (BPMN, UML) and wireframing tools (e.g., Figma, Visily).\nProven experience in creating BRDs, FRDs, and process documentation.\nStrong logical thinking and ability to evaluate dependencies, and edge cases.\nFamiliarity with data tools like BI, Excel, or similar platforms.\nGood English skills (write and read).\n\nNice to have:\nKnowledge of compliance frameworks (PCI-DSS, GDPR).\nExperience working with external partners (banks, regulators).\nExperience as a Scrum Master or BA template builder.\nCertifications of PSPO, PSM,... are advantageous.\n\nWhy you\'ll love working here\nAt AILOGY, growth is a shared journey. If our values align with yours, we offer meaningful opportunities for growth — through new challenges, expanded roles, and leadership paths — so you can leave your mark\nSome of our Perks and Benefits:\nWorking hours: 9:00 AM - 6:00 PM, Monday - Friday (Flexitime from 8:00 AM - 9:30 AM)\nMacBook M4 provided \n13th-month salary and annual performance bonus\n15 days of annual leave \nPerformance review: twice a year\nExtra Premium Healthcare & Annual Health Check.\nTeam activities: Annual company trip, monthly team parties, team-building events, and regular sports sessions (e.g., badminton)\nOthers: Benefits related to public holidays, insurance, etc., in accordance with Vietnamese labor laws.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '113 - 115 Ung Van Khiem Street, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(285, 250, 2, '[Da Nang & Ho Chi Minh] QA Engineer', 'Top 3 reasons to join us\n- 13th month salary & Performance\n- Premium insurance for family\n- Well-being program\n\nJob description\nJOB PURPOSE\n- The quality gatekeeper is responsible for ensuring that software is being delivered with the highest quality standards. The main mission is to reach quality excellence by having no issues in production as a continuous target.\n- The QA Engineer should know and understand the business details, being able to check whether the final result matches all the business expectations.\n- The QA Engineer should create and execute manual and automated test scenarios, provide root cause analyses of defects based on metrics, and proactively raise improvements that will enhance the quality of the product.\n\nPRIMARY JOB RESPONSIBILITIES\n- As a member of an Agile team: The main responsibility for the quality of the product. Ensure that the product is delivered with the highest quality by leveraging QA activities along with the scrum phases. Some of the daily basis activities are:\n- Design test processes and procedures used to ensure that software operates within defined requirements.\n- Create detailed, comprehensive, and well-structured test plans and test cases.\n- Implement test plans, automation, and validation strategies.\n- Creating and executing test automation scripts (UI testing, API testing, etc).\n- In-depth functional testing – Must be able to evaluate functional stability to ensure business requirements are being met and are “fit-for-purpose” through end-to-end functional and automation testing.\n- Work closely with developers and product owners/business analysts to resolve issues.\n- Communicate any obstacles to raise awareness and avoid project impediments and overall project timeline disruption.\n- Collaborate with Product Owner, and Developers on tasks related to the planning, testing, and coordination of release activities.\n- Participate in user story creation process through dissection of high-level requirements during team review sessions.\n\nYour skills and experience\nSKILLS AND QUALIFICATIONS\n- 3+ years of work experience in Quality Assurance roles\n- Good communication skills in English.\n- Experience in writing clear, concise, and comprehensive test plans and test cases.\n- Knowledge of testing integrations, testing best practices, and end-to-end system processes.\n- Excellent analytical and problem-solving abilities.\n- Demonstrated ability to think outside the box.\n- Understanding of Agile/Scrum methodology and how QA functions within it.\n\nPREFERRED QUALIFICATIONS\n- Experience with test automation tools, such as Selenium, Gherkin, Specflow, Postman, SoapUI, etc.\n- Familiarity with git and version control tools.\n- Having Salesforce experience/knowledge is a big plus.\n\nWhy you\'ll love working here\nAt OTSV, work is a self-fulfillment, we encourage staff to leave their comfort zone, think out of the box, and share their ideas without hesitation. As a team, we analyze and evaluate issues objectively to learn quickly from mistakes.\nWe believe in ‘fail quick, success quick’ and strive to keep pace with the forefront of technology to digitize ONE’s business.\nThe designs of our offices embrace our culture of being flexible and open. Unlike a conventional office, we have an open concept with different work areas which encourages collaboration, open-mindedness, and spontaneity.\nEach work area has its charm and aims to make our staff feel as comfortable in the office as they would feel at home. Have a meet-up at the Café amidst the aroma of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3-4 tòa nhà Phi Long, 52 Nguyễn Văn Linh, Hai Chau, Da Nang; Tòa nhà ETOWN 6 - 364 Cộng Hòa, Phường 13, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(286, 251, 2, 'Trưởng phòng tư vấn triển khai ERP (SAP, Oracle, RPA)', 'Top 3 reasons to join us\n• Thưởng tháng 13 và thưởng hiệu quả làm việc\n• Thời gian làm việc từ thứ 2 - thứ 6\n• Đào tạo theo khung năng lực\n\nJob description\n• Phụ trách chính tổ chức triển khai SAP ERP: Thiết kế, triển khai, tích hợp hệ thống, điều phối và giám sát toàn bộ quy trình triển khai ERP để đảm bảo sự thành công của dự án từ khảo sát, tư vấn đến vận hành; và\n• Tối ưu hóa việc áp dụng ERP cho tập đoàn: Đảm bảo giải pháp ERP đáp ứng được các yêu cầu nghiệp vụ thực tế và mang lại hiệu quả vận hành cao nhất cho tập đoàn; và\n• Nghiên cứu và phát triển các mô hình phân tích nâng cao: phân tích xu hướng, dự báo; và\n• Định hướng và triển khai các giải pháp báo cáo thông minh BI nhằm phục vụ nhu cầu phân tích dữ liệu cho các đơn vị và cấp lãnh đạo tập đoàn Bolt Holdings cho việc ra quyết định chiến lược và vận hành của doanh nghiệp dựa trên dữ liệu; và\n• Chuẩn hóa, tự động hóa hệ thống báo cáo điều hành, tài chính, kinh doanh, nhân sự...Đảm bảo chất lượng và hiệu quả của hệ thống báo cáo BI: Kiểm soát chặt chẽ về mặt dữ liệu, trực quan hóa, tính dễ sử dụng và độ tin cậy của các báo cáo và dashboard; và\n• Phụ trách triển khai các ứng dụng RPA cho toàn tập đoàn: Lập kế hoạch và dẫn dắt lộ trình triển khai các giải pháp RPA phù hợp với mục tiêu chuyển đổi số của tập đoàn; và\n• Chuẩn hóa và số hóa quy trình vận hành giữa các phòng ban các công ty thành viên & tập đoàn. Giảm sai sót thủ công, tăng độ chính xác và kiểm soát quy trình. Tiết kiệm thời gian phê duyệt, tổng hợp, báo cáo nhằm Tối ưu hóa hoạt động vận hành thông qua tự động hóa; và\n• Quản lý và phát triển đội ngũ chuyên nghiệp: Xây dựng một đội ngũ tư vấn triển khai SAP ERP, BI và RPA vững chuyên môn và kỹ thuật, có khả năng làm việc hiệu quả, chủ động, sáng tạo; và\n• Thúc đẩy văn hóa ra quyết định dựa trên dữ liệu (data-driven): Góp phần hình thành tư duy phân tích trong tập đoàn, giúp ban lãnh đạo và CBNV tập đoàn ra quyết định dựa trên thông tin đáng tin cậy.\n• Hỗ trợ và tham mưu cho Tổng giám đốc trong việc xây dựng mục tiêu, kế hoạch, chiến lược triển khai các nền tảng quản trị nội bộ, phát triển hệ thống các mô hình dự báo, tối ưu hóa các quy trình vận hành; và\n• Tham gia triển khai các giải pháp phần mềm: Nghiên cứu, triển khai các dự án phần mềm mới theo yêu cầu của Tổng giám đốc\n\nYour skills and experience\n• Tốt nghiệp Đại học/ Cao học trở lên chuyên ngành Công nghệ thông tin/ Kế toán – kiểm toán/Tài chính – Kinh tế.\n• Có chứng chỉ ERP chuyên sâu: SAP, Oracle; chứng chỉ chuyên môn về BI và dữ liệu ( Microsoft Certified, Tableau Desktop Specialist) là lợi thế\n• Tối thiểu 5–7 năm kinh nghiệm triển khai hệ thống ERP (SAP, Oracle, hoặc tương đương).\n• Có ít nhất 3–5 năm kinh nghiệm ở vị trí quản lý dự án hoặc trưởng nhóm triển khai ERP.\n• Tối thiểu 3 năm kinh nghiệm quản lý nhóm hoặc dự án BI.\n• Tối thiểu 2–3  năm kinh nghiệm trong lĩnh vực tự động hóa hoặc phát triển phần mềm.\n• Đã trực tiếp tham gia hoặc điều phối thành công nhiều dự án ERP cho các doanh nghiệp vừa và lớn.\n\nWhy you\'ll love working here\n• Lương thỏa thuận\n• Thưởng tháng 13 và thưởng hiệu quả làm việc\n• Thời gian làm việc từ thứ 2 - thứ 6\n• Nghỉ phép theo quy định của nhà nước\n• Đào tạo theo khung năng lực', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1 - Tòa nhà 4A, Tạ Quang Bửu, P. Bách Khoa, Q. Hai Bà Trưng, Thành phố Hà Nội, Việt Nam, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(287, 252, 2, 'Senior Native Mobile Developer (Swift & Kotlin – BLE)', 'We are looking for a Senior Native Mobile Developer with deep expertise in Swift and Kotlin, and a strong understanding of BLE (Bluetooth Low Energy) communications to join our team. This role will play a key part in building and integrating our MPC (Multi-Party Computation) Crypto Wallet solution with a secure hardware device that communicates with the mobile application via BLE.\n\nYou will work closely with cryptography engineers, firmware teams, and backend developers to embed MPC protocols into the mobile app, define and test mobile-side communication protocols, and ensure a secure and seamless user experience between the wallet and the embedded hardware.\n\nKey Responsibilities\n- Implement and maintain native iOS (Swift) and Android (Kotlin) components of our MPC wallet solution.\n- Integrate cryptographic SDKs and MPC libraries to support MPC core functions such as secure key share generation, signing, and transaction flows.\n- Develop and optimize BLE communication between the mobile app and the secure hardware component, including pairing, GATT services, and encrypted data transmission.\n- Collaborate with firmware teams to define packet structures, command sets, and device-side state machines.\n- Ensure mobile security best practices, including biometric authentication, secure local storage, sandboxing, and encrypted communication channels.\n- Build clean, well-tested, and maintainable code that aligns with our cross-platform architecture and performance goals.\n- Work closely with QA to implement robust test coverage, particularly around BLE and MPC integration.\n- Participate in design reviews, code reviews, and contribute to cross-functional discussions and continuous improvement.\n\nYour skills and experience\nMust-have Requirements\n- 5+ years of hands-on mobile development experience with both Swift (iOS) and Kotlin (Android).\n- Strong understanding of BLE: scanning, GATT profiles, pairing, encrypted communication, and performance optimization.\n- Proven experience building mobile apps that interface with external hardware over BLE or NFC.\n- Familiarity with integrating SDKs into Swift and Kotlin-based mobile environments.\n- Solid grasp of mobile security: keychain, keystore, biometric auth, secure enclave, encrypted storage.\n- Strong problem-solving, debugging, and communication skills.\n- Ability to work independently and collaboratively with distributed teams in a fast-paced startup environment.\n\nNice-to-have Requirements\n- Experience working with MPC-based systems, threshold signing, or cryptographic key orchestration.\n- Exposure to crypto wallet development or blockchain transaction signing.\n- Familiarity with BLE emulators/simulators for development and automated testing.\n- Experience setting up CI/CD for mobile, release workflows, and crash/error monitoring.\n- Contributions to open-source mobile, cryptography, or Web3 projects.\n- Experience with multi platforms (e.g. Flutter).\n\nWhy you\'ll love working here\n- Work on Cutting-Edge Crypto Tech: Be part of a team building secure, MPC-powered wallet technology that’s reshaping the future of digital asset protection.\n- Collaborate with Top Talent: Work alongside a world-class team of engineers and crypto experts who value quality, innovation, and continuous learning.\n- Flexible & Remote-Friendly Environment: Enjoy the freedom to work from anywhere or join us in Ho Chi Minh City - your impact matters more than your location.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote / Ho Chi Minh District 1, Ho Chi Minh / Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(288, 253, 2, 'AI Talents (Ph.D. Holders)', 'PROJECT OVERVIEW To resolve challenges in Nexon games and uncover new opportunities, we are seeking an AI expert to lead research and services in generative AI technology. This role will serve as the AI hub within the Nexon Group, enhancing overall development productivity and fostering the accumulation and activation of AI technologies.\n\nJOB SUMMARY Conduct research and development on Nexon’s AI technologies to support the organization’s business objectives and technical needs. Responsibilities include AI model design, optimization, large-scale data processing, and analysis, as well as planning and implementing AI solutions for real-world services, all while leading collaboration with internal teams and external partners.\n\nJOB DESCRIPTION\n\nAI Model Development and Optimization \n- Research and design state-of-the-art machine learning, deep learning, and generative AI algorithms \n- Develop customized AI models for specific problem-solving and optimize their performance \n- Maintain and continuously update existing models \n\nData Processing and Analysis \n- Collect, preprocess, and analyze large-scale datasets \n- Extract data-driven insights and build decision-support systems \n\nAI Solution Planning and Implementation \n- Plan and develop AI products and services that meet business needs \n- Develop, test, and provide customized AI solutions for practical applications \n\nResearch and Trend Analysis \n- Investigate and analyze the latest AI technologies, academic papers, and industry trends \n- Experiment with and validate innovative technologies for potential business applications \n\nCollaboration and Technical Support \n- Collaborate with team members while providing technical support to both internal development teams and external partners \n- Conduct AI-related training and workshops to disseminate knowledge \n\nSystem Integration and Maintenance \n- Integrate and deploy developed AI solutions \n- Ensure system stability through performance monitoring and ongoing maintenance.\n\nYOUR SKILLS AND EXPERIENCE\n\nESSENTIAL REQUIREMENTS\n\nEducation & Major \n- Bachelor’s degree or higher in Computer Science, Data Science, AI, Mathematics, Statistics, or related fields \n- Must hold a Ph.D.\n\nExperience \n- Proven experience in AI model development and data analysis projects \n- Experience with large-scale data processing and cloud-based AI solution development \n\nTechnical Skills \n- Proficiency with machine learning/deep learning frameworks (e.g., TensorFlow, PyTorch) \n- Expertise in programming languages such as Python or R \n- Experience with databases and distributed computing (e.g., Hadoop, Spark) \n\nManagement and Leadership \n- Experience managing R&D teams and mentoring \n- Strong project planning, scheduling, and execution skills \n- Excellent communication skills for effective engagement with diverse stakeholders \n\nStrategic Thinking \n- Understanding of the latest technological trends and their business applications \n- Ability to set and execute the organization’s technical direction \n\nPREFERRED QUALIFICATIONS \n- Publication of AI-related academic papers or registration of patents (especially SCI-indexed publications) \n- Experience with MLOps or DevOps \n- Relevant certifications (e.g., AWS Certified Machine Learning, Google Professional Data Engineer) \n- Proficiency in English \n\nWHY YOU\'LL LOVE WORKING HERE\n- Chance to work on global projects with multicultural teams, world-class games.\n- Attractive salary and benefits.\n- Professional work environment.\n- Open culture where every employee is valued, treated fairly and trusted.\n- 13th salary every year at least 1-month salary.\n- From 12 days Annual Leave\n- Government social, health, and unemployment insurance.\n- Lunch Allowance\n- Annual salary review based on employee performance and company success\n- Annual Company Trip, Year End Party\n- Events during Birthday, Full Moon Festival, other important holidays.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UOA Tower, 11th Floor, 06 Tan Trao Street, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(289, 254, 2, 'Full Stack Developer - Java, Spring', 'Are you a passionate full stack developer looking to contribute to the development of enterprise-class applications that drive planning and revenue growth. Our ideal candidate will be demonstrably skilled, have strong, hands-on experience with Java and Spring to develop enterprise applications. The candidate will play a critical role in application design and development and support junior developers.\n\nResponsibilities\n- Develop and maintain scalable Java-based applications.\n- Collaborate with team and stakeholders to analyze requirements.\n- Implement efficient algorithms, optimize applications, and seamlessly integrate.\n- Write clean, testable, and efficient code adhering to best practices.\n- Develop RESTful APIs and integrate third-party APIs.\n- Integrate with SQL databases, ensuring data integrity and efficiency.\n- Write unit and integration tests to ensure functionality and reliability of API endpoints.\n- Troubleshoot and debug applications to resolve technical issues.\n- Conduct code reviews and provide constructive feedback to team members.\n- Create clear and concise documentation (docs-as-code) for code and APIs.\n- Ensure application security and compliance with industry and regional standards.\n- Stay updated with the latest technologies and tools in Java development and apply them to improve existing solutions.\n\nYour skills and experience\nExcellent development skills required. Excellent communication skills required. Solid mathematics skills required. Intermediate English skills required.\n\nQualifications\n- Bachelor’s degree in computer science, software engineering, or related field.\n- Five or more years of experience in Java development, with 2 years of full stack development experience.\n- Solid experience with design patterns, developing from architecture and design documents.\n- Knowledge of Java and J2EE/Java EE (including servlets, JSP, JSF, JDBC).\n- Proficiency in Spring frameworks including Spring, Spring MVC, and Spring Boot.\n- Strong knowledge of object-oriented programming (OOP) including inheritance, interfaces, exception handling, and design patterns.\n- Strong understanding of Java threading, concurrency, concurrency patterns, experience building thread safe code.\n- Solid experience with RESTful APIs, Microservices, and Web Services and best practices.\n- Solid Experience with SQL, ORM, databases including MySQL, PostgreSQL, and SQL Server.\n- Experience with analytics engines such as Cube and Spark.\n- Experience with message queuing systems such as Kafka and RabbitMQ.\n- Experience with front-end development and technologies from JavaFX to React and Redux.\n- Experience with Spring components and ecosystem (e.g. Spring Boot LogBack, Spring Data, Spring Security, etc.).\n- Good understanding of containerization tools Docker and Kubernetes.\n- Experience with IntelliJ and GIT or similar source code versioning tools and coding standards.\n- Solid skills in statistics, probability, and linear algebra.\n- Excellent attention to detail.\n- Strong analytical and problem-solving skills.\n- Excellent communication and teamwork abilities.\n- Experience collaborating with business, engineering, operational, and product stakeholders, spanning business requirements, functional specifications, and test plans.\n- Maintaining a constant focus on the applications delivering client value.\n\nPreferred\n- Good understanding NoSQL databases, like MongoDB, Redis, OLAP and data warehouses.\n- Knowledge of Linux and common tech stacks.\n- Knowledge of cloud services like AWS or Azure.\n- Previous experience working in a Startup environment.\n- Previous experience working in an Agile/Scrum environment.\n\nWhy you\'ll love working here\n- Income negotiated according to experience and ability, with 13th month salary and bonus up to 15th month salary based on excellent performance and business results.\n- Loyalty program after second year, bonus up to 1 month salary based on product launches.\n- Social insurance, health insurance and salary insurance after signing labor contract.\n- Startup culture, young, dynamic English-speaking work environment. You are a stakeholder.\n- Software engineering, building real product. Attention and commitment to real engineering.\n- Challenged to master with mentoring and coaching, from engineering to project and presentation skills.\n- Sponsoring over achievers for technical certifications.\n- New equipment, professional development environments, in-house servers and hybrid cloud.\n- Empowered to experiment with opensource and Linux lab environments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '26 Thao Dien Street, Thao Dien, Thu Duc, HCMC, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(290, 255, 2, 'QA Engineer (JMeter)', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nJob Description: At Aperia Solutions, our success is driven by the innovation and dedication of our talented engineering team. We are seeking a QA Engineer with a strong background in automation—particularly with JMeter—to help us ensure the highest level of quality across our product suite. This role will focus on developing robust testing strategies, automating functional tests, and collaborating closely with cross-functional teams to uphold our commitment to secure and scalable solutions.\n\nKey Responsibilities:\n- Design, implement, and maintain comprehensive test strategies, test plans, and test cases across functional and integration testing.\n- Develop and optimize automated scripts, primarily using JMeter, to support a CI/CD pipeline.\n- Execute manual and automated testing, including regression, functional, UI, and API testing.\n- Utilize and help refine Aperia’s test frameworks for Functional Automation, Security, and Penetration Testing.\n- Analyze and translate user stories and business requirements into detailed test scenarios and scripts.\n- Ensure thorough test coverage while balancing time constraints and business priorities.\n- Select, recommend, and support tools such as Postman, database testing, and log analysis tools (e.g., Splunk) for end-to-end validation.\n- Lead the testing effort within agile teams; collaborate on design and code reviews to ensure testability.\n- Collaborate with cross-functional teams including Product, DevOps, and Security to embed quality into our development lifecycle.\n- Mentor junior QA engineers and foster a culture of continuous improvement.\n\nFunctional Responsibilities:\n- Actively engage with Scrum teams to resolve product issues quickly and effectively.\n- Conduct and lead regression testing based on impact analysis.\n- Communicate findings clearly and proactively to relevant stakeholders.\n- Manage priorities and multitask across multiple projects while maintaining high attention to detail.\n- Promote adherence to Agile, Scrum, TDD, BDD, and other best practices in software development and testing.\n- Communicate effectively through Teams, SharePoint, GitHub, and other collaborative platforms.\n- Contribute to an inclusive and high-performance team culture that values transparency, ownership, and accountability.\n\nYour skills and experience:\nTechnical Skills:\n- 3-4 years of hands-on QA experience with increasing levels of responsibility.\n- At least 1-2 years JMeter automation experience with for functional testing and/or Performance testing.\n- Experience with Postman, SQL/DB testing, Splunk, and writing/maintaining test plans and strategies.\n- Proven expertise in API and UI automation.\n- Deep understanding of QA frameworks and SDLC methodologies.\n- Experience working within CI/CD pipelines and test code integration.\n- Proficient in REST/SOAP, JSON, XML, and web technologies such as ReactJS.\n- Familiarity with Secure Software Development Framework (SSDF) and Secure Development Lifecycle (SDL) practices.\n- Experience testing high-performance, high-throughput web applications.\n- Strong analytical, troubleshooting, and root cause analysis skills.\n- Experience with or ability to learn Aperia’s internal tools like Prova and ViewTrx.\n\nThings that will separate you from the rest:\n- Knowledge in security testing, performance testing, performance tuning is a definite plus.\n- Passion for achieving excellence in technical, process, product quality and reliability.\n- Must be extremely detail and technology-oriented and have excellent communications skills.\n- Experience in collaborating with global teams to lead QA initiatives is a definite plus.\n\nEducation:\n- B.Tech/M.Tech/MCA/ MS Degree\n\nJob Type:\n- Full-time\n\nSchedule:\n- Monday to Friday\n\nWork Location:\n- The Six8 Building: 24-26 Phan Dinh Giot, Tan Binh District, HCMC\n- VDB Tower: 74 Quang Trung, Hai Chau, Danang\n\nWhy you\'ll love working here:\n- Highly competitive salary\n- Full salary for probation & full coverage of social insurance.\n- Premium healthcare for you and your beloved one.\n- Monthly childcare support\n- 13th-month salary.\n- Annual Leave: 15 days; Paternity Leave: 6 weeks, Bereavement leave: 10 days.\n- Flexible working time, focus on output (no checking time attendance)\n- Various active sporty clubs: Football, Billiards, Badminton, E-sport clubs\n- Frequent opportunities to travel to US headquarter from 3-6 months.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Six8 Building: 24-26 Phan Dinh Giot, Tan Binh District, HCMC; VDB Tower: 74 Quang Trung, Hai Chau, Danang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(291, 256, 2, 'React Native developer', 'Top 3 reasons to join us\nCompelling rewards, 13th-month salary\nWorking 5 weekdays and Flexible working time\nInternational Teamwork opportunities \n\nJob description\nAbout Us\nLitmers is a No-code & Code Outsourcing Agency leading innovation in the outsourced development space. We specialize in fast, cost-efficient software delivery without compromising on quality.\nSince our launch in January 2023 with just four team members, we’ve expanded to 50 people by May 2025, completed over 110 projects, and achieved 78% year-over-year revenue growth.\nRecognized as one of the top no-code Bubble development teams in Asia, we are currently ranked 13th out of 368 global Bubble agencies (as of April 2025). We also earned Gold Partner status within just 2.5 years, placing us in the top 5 globally by growth rate.\nLearn more:\n \nPosition Overview\nWe’re looking for a skilled React Native Frontend Developer to join our growing engineering team.\nIn this role, you’ll collaborate with designers, Bubble developers, and backend engineers to build scalable, high-performance cross-platform applications using React-based frameworks (React, React Native). This is a hands-on development position with no managerial responsibilities, focused on delivering clean, reliable code and great user experiences.\n\nResponsibilities\n- Develop and maintain high-quality mobile applications using React Native\n- Convert design mockups into responsive, pixel-perfect interfaces\n- Integrate frontend components with backend services and APIs\n- Optimize performance across iOS and Android platforms\n- Write clean, reusable, and testable code to support consistent UX\n- Collaborate with cross-functional teams to ensure seamless feature delivery\n- Troubleshoot and resolve technical issues effectively\n- Participate in code reviews and contribute to frontend best practices\n\nYour skills and experience\nRequirements\n- 3–5 years of experience in mobile app development using React Native\n- Strong proficiency in JavaScript and TypeScript\n- Experience with Expo, Firebase or native modules\n- Hands-on experience with building and deploying iOS and Android apps\n- Familiarity with React.js, especially for building cross-platform, shareable components\n- Solid understanding of API integration, mobile app lifecycle, and performance tuning\n- Proficient with version control tools (e.g., Git, GitHub)\n- Awareness of Agile methodologies and frontend development workflows\n- Comfortable communicating in English in a global team setting\n\nNice to Haves\n- Experience with automated testing tools for React Native (e.g., Jest, Detox)\n- Familiarity with App Store / Play Store deployment processes\n- Interest or prior experience with no-code/low-code platforms like Bubble\n\nWhy you\'ll love working here\n- 13th-month salary: calculated as one month\'s actual basic salary if the employee works for 12 months of the calendar year.\n- Annual Leaves : employee who has been working for 12 months or more is entitled to fully-paid annual leave with 12 days.\n- Social Insurance, Medical Insurance, Unemployment Insurance: Yes\n- Convenient shared office in Thao Dien, HCM\n- Flexibility in commuting time (8:30~9:30 AM)\n- Flexible working time with notice (ex. Visiting hospital, bank etc)\n- Latest device support in any type (Mac, monitors etc)\n- Working 5 weekdays (Mon-Fri)\n- Work-related books and lectures supported\n- External activities (Clubs)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thao Dien, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(292, 257, 2, 'Senior .NET Developer (C#, .NET, SQL)', 'WE ARE LOOKING FOR TALENTED DEVELOPERS !\n\nResponsibilities: \n- Analyze requirements, design new features for WinForms application.\n- Code, test, document and implement new applications or enhancements to existing systems\n- Assess the impact of change requests, and develop solutions and mitigation strategies\n- Apply project design, system developments and maintenance methodologies\n- Design and develop API platform to connect to various disparate backend systems\n- Develop documentation throughout development process\n- Implement common APIs based on architecture guidelines and framework related to logging, authentication, security, error recovery etc.\n- Interpret business requirements and provide systems/technical documentation\n- Share knowledge and information with the team and assist others in priorities team meeting\n- Work as team player to provide ongoing production support to our customers. This involves investigate production issues, locate root cause, and apply the appropriate fixes or change requests and documentation etc.\n- Attention to detail; an analytical and conceptual thinker\n\nYour skills and experience\n\nTechnical attributes: \n- Have 3+ experience working with .NET development in C# \n- Strong technical skills in .NET frameworks and .NET development tools. \n- Experience in WinForms\n- Working experience with Microsoft SQL Server\n- Familiarity with ASP.NET (for API development)\n- Strong interpersonal and communication skills using English\n\nAdditional attributes (preferred not required):\n- Experience in other technology languages (e.g.: JavaScript, HTML5, CSS3 etc.)\n- Working knowledge or experience in ERP type systems\n- Working knowledge or experience in Accounting or Retail POS systems\n- Experience with workflow based systems\n- Experience with Agile Development methodologies\n\nWhy you\'ll love working here\n\nWe are our people, and whilst as a business we make software, as an organization, we make some of the industry’s best! Joining the team you will work with the engineers around the world from BMW, Mercedes, Honda, Porches, Hyundai …\n\n1 WORKING HOURS\n- Working hours is flexible and the standard guideline is between 8:00 AM to 5:00 PM with 1 hour break for lunch.\n- Staff can start early and finish early to keep in sync with Australia working hours\n\n2 LEAVES\n- 12 days Annual Leave per annum. Annually leave is accumulated up to 2 years.\n- Additional one annual leave day for every five years of service\n- Sick Leave: 5 days paid per annum.\n- Compassionate Leave: 3 days per annum\n\n3 HEALTHCARE\n- Premium Personal Health Insurance package for full-time and permanent staff.\n- Annual health check\n\n4 BONUSES\n- 13th month bonus\n- Loyalty reward Program (Bonus for every 3 years, 5 years of service)\n- Project/ Performance Bonus\n\n5 OTHER BENEFITS, ALLOWANCES AND INCENTIVES\n- 100% salary during Probation Period\n- Fully sponsored onsite trip to Titan international offices (AU, Thailand, UAE, EU etc.)\n- Gifts on special occasions + holidays (Tet, Full-moon festival, Birthday, Christmas etc.)\n- Employee Referral Program\n- Internal events every month (Happy lunch, Milk tea Friday, etc.)\n- Sport Activity Funding (Football every Tuesday & Thursday)\n- Education Funding\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '182 Lê Đại Hành, District 11, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(293, 243, 2, 'Mid/Sr Java Developer (English Required) - Up to 3200$', 'Rakuten FinTech Vietnam Co., Ltd. is the company, which was established in 2021, and the subsidiary of Rakuten Card, which is one of the biggest credit card company in Japan. Our mission is to develop internal system and mission-critical system for Rakuten Card and FinTech group companies to contribute to FinTech business growth, also to provide attractive environment for talented engineers in both Vietnam and Japan.\nWe are looking for a new member of our company, who will be working as Expert of this position. In this position, you will need to collaborate with stakeholders to support the business’ vision and strategy and be required to accelerate business activities to streamline daily operations through industry experience and your best practices.\nEspecially we are in the early stage right now, so that we would like to have the experienced administrative specialist who has flexibility and quickness, also is able to consider organization support by themselves.\nThis position will have responsibility to develop Web application, Web API and more for our Fintech services such as “Rakuten Card”, “Rakuten Pay”, "Rakuten Bank” etc.\nResponsibilities\n- Perform requirement analysis, design and technical documentation\n- Design, build, and maintain efficient, reusable, and reliable Java code\n- Work to improve and enhance quality in automated testing, etc\n- Work with leader and teammates to estimate and plan for projects\nBecause of start-up phase, we expect to join as tech leader level in our team and becoming leader/manager in the future.\nYour skills and experience\nMust have:\n- At least 4+ years working in Java API/Web development\n- Intermediate-level in English communication\n- Strong experience in SQL, especially Oracle\n- Strong knowledge in Java Web & Enterprise (EE) technologies\n- Good knowledge with source control and defect tracking tool\n- Good experience with unit testing: JUnit, mock\n- Must be independent, responsible, and self-motivated with the ability to learn and achieve superior results\n- Strong communication skills with proven ability to present complex ideas and document in a clear and concise way.\nNice to have:\n- Experience in developing large-scale mission-critical systems\n- Experience in design and implement event-driven architectures using messaging systems, especially with Kafka\n- Experience in utilizing NoSQL distributed databases to manage large volumes of data, especially with Cassandra\n- Working experience as a Tech Lead and Team Leader\n- Experience in microservice, cloud computing\nWhy you\'ll love working here\n- Commuting Allowances\n- Meal Allowances\n- Performance Bonus\n- Tet Bonus (Annual Bonus)\n- Salary review\n- Health checkup\n- Premium Health care\n- Company Trip\n- Annual Leave\n*Benefits might be updated to add on, please let us know if you want to know more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24th-25th Floor, A&B Tower, 76A Le Lai Street, Ben Thanh Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(294, 258, 2, 'VIC - Process Quality Assurance (QA QC)', 'Trung tâm Công nghệ thông tin (VIC) là đơn vị xây dựng, triển khai, duy trì các hệ thống phần mềm, số hóa các quy trình thuộc lĩnh vực quản trị doanh nghiệp (tài chính, tài sản, kho, mua sắm, nhân sự...) trong Tập đoàn, triển khai các công cụ phần mềm hỗ trợ nghiệp vụ cho các đơn vị trực thuộc. Đồng thời, trung tâm cũng nghiên cứu và triển khai các giải pháp ERP nhằm nâng cao năng lực quản trị, nâng cao hiệu quả sử dụng tài nguyên (bao gồm cả tài nguyên con người), nhất quán về cách thức quản lý và đảm bảo tính tuân thủ của Viettel trên toàn cầu.\n\n1.1. Kiểm tra, đánh giá\n- Hướng dẫn, hỗ trợ giải quyết các vấn đề, rủi ro về quy trình ở mức tổ chức.\n- Chủ động đề xuất, tổ chức kiểm tra, đánh giá (audit) mức độ tuân thủ quy trình, quy định đã ban hành định kỳ hoặc đột xuất.\n- Tư vấn dự án áp dụng các hướng dẫn, tiêu chuẩn chất lượng, phát hiện vấn đề có nguy cơ ảnh hưởng tới toàn bộ tổ chức.\n\n1.2 Xây dựng, tối ưu quy trình, quy định, KPI\n- Theo dõi, đo đạc, đánh giá, phân tích các số liệu quy trình, chất lượng; từ đó đưa ra các nguy cơ, xu hướng, vấn đề và đề xuất quy trình, chất lượng cho lãnh đạo.\n- Chủ trì xây dựng, cải tiến quy trình, quy định, hướng dẫn, SLA, KPI ... trong phạm vi toàn tổ chức.\n- Nghiên cứu và áp dụng các tiêu chuẩn, mô hình thế giới để xây dựng quy trình, quy định từ đó tối ưu luồng sản xuất, nâng cao chất lượng sản phẩm/dịch vụ.\n\n2.3 Hoạt động chuyên môn\n- Đưa ra các mục tiêu, chương trình hành động về việc nâng cao chất lượng sản phẩm, dịch vụ CNTT, nâng cao chất lượng nhân sự đảm bảo chất lượng.\n- Đào tạo chuyên sâu về về quy trình của tổ chức và các quy trình liên quan.\n- Huấn luyện các đội dự án về cách thức thực thi dự án trong toàn tổ chức nhằm tăng hiệu quả.\n\nYour skills and experience\n- Tốt nghiệp các trường đại học chuyên ngành CNTT hoặc liên quan \n- Tiếng Anh: Toeic 550 trở lên hoặc tương đương \n- Kiến thức về các mô hình phát triển phần mềm Agile, Scrum, XP, Waterfall...: chuyên sâu được quan điểm, các định nghĩa, khái niệm, luồng quy trình thực hiện, cách thức vận dụng vào thực tế hoặc nếu có chứng chỉ quốc tế trong lĩnh vực liên quan, ... \n- Kiến thức về công cụ quản lý sản xuất: chuyên sâu.\n- Kiến thức tổng quan về các mô hình và các tiêu chuẩn quản lý chất lượng (như ISO 9001, ISO 27001, CMMI, ITIL, ...). Có khả năng tư duy nhậy bén, nắm bắt và phân tích vấn đề từ nhiều góc độ khác nhau.\n- Có khả năng tư vấn lại các vấn đề liên quan đến sản phẩm cho đội dự án.\n- Khả năng giao tiếp và trình bầy vấn đề tốt, phối hợp nhóm tốt.\n- Khả năng chịu áp lực cao.\n\nWhy you\'ll love working here\n- Lương thỏa thuận theo năng lực, kinh ngiệm.\n- Chế độ thu nhập hấp dẫn tăng theo năng lực, kinh nghiệm.\n- Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo theo cách riêng.\n- Được khơi gợi cảm hứng làm việc với văn phòng xanh, không gian mở, hiện đại tiêu chuẩn quốc tế.\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày.\n- Thưởng thức bữa trưa tại Tập đoàn, được chọn lọc bởi các chuyên gia dinh dưỡng.\n- Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building.\n- Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, Trụ sở chính của Tập đoàn Viettel, Lô D26, Khu đô thị mới Cầu Giấy, phường Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(295, 259, 2, 'Cloud Security Engineer (Remote)', 'Resola Inc, a pioneering force in AI solutions for marketing and advertising, is seeking an experienced Cloud Security Engineer to join our innovative team remotely from Vietnam. As a crucial member of Resola\'s engineering division, you\'ll be responsible for designing and implementing comprehensive security measures that protect our cloud infrastructure while enabling innovation and growth.\n\nAbout Us\nWe are dedicated to empowering organizations to harness the full potential of artificial intelligence responsibly and efficiently. Our diverse team of 75 employees representing 9 nationalities works in a collaborative environment where innovation meets practical business applications.\n\nResponsibilities\n- Design and implement comprehensive security architectures for cloud infrastructure and applications\n- Lead security incident response efforts and conduct thorough post-incident analysis\n- Develop and maintain security policies ensuring regulatory compliance\n- Collaborate with development teams to implement security best practices\n- Conduct regular security assessments and penetration testing\n- Manage identity and access control systems\n- Research and evaluate new security technologies and solutions\n\nYour skills and experience\nRequirements\n- Strong experience in cloud security architecture and implementation\n- Deep knowledge of security frameworks and compliance standards\n- Expertise in cloud platforms (AWS, Azure, or GCP)\n- Strong incident response and threat management skills\n- Proficiency in English (for team communication)\n\nWhat We Value\n- Commitment to security-first design principles\n- Ethical and responsible approach to AI security\n- Continuous learning and knowledge sharing\n- Collaborative spirit and excellent communication skills\n\nWhy you\'ll love working here\nWe Offer\n- A competitive salary with a transparent progression pathway.\n- A flexible and supportive work environment that values work-life balance.\n- Opportunities for personal and professional development.\n- A dynamic, multicultural team with a passion for building great software.\n- Up to 10 days of paid day off.\n- Up to 16 days of public holidays per year.\n- Performance and salary review every 6 months.\n- Opportunity for a bonus every 6 months based on results and outcomes.\n\nOur products and services\nDECA is an all-in-one digital marketing platform that helps businesses of all sizes to plan, execute and optimize their online marketing campaigns. With a user-friendly interface and advanced features, Deca simplifies the complex process of digital marketing and enables businesses to achieve their marketing goals with ease.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remotely, Other, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(296, 238, 2, '[Middle, Senior] Mobile Developer (Flutter)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Lead các dự án và trực tiếp tham gia lập trình các ứng dụng di động (iOS và Android) của MBBank, gồm hệ thống nội bộ và ứng dụng dành cho khách hàng với quy mô 30 triệu khách hàng cá nhân và 300.000 khách hàng doanh nghiệp - đứng đầu Việt Nam về quy mô phục vụ.\n- Lên timeline công việc, quản lý tasks cho các thành viên trong team phát triển (3 - 6 thành viên/dự án), giám sát và hỗ trợ các thành viên hoàn thành công việc đúng cam kết.\n- Tham gia phân tích nghiệp vụ, đề xuất các giải pháp công nghệ.\n- Làm việc chặt chẽ với các team Sản phẩm, UX/UI và Backend để thiết kế, xây dựng các sản phẩm, nền tảng và tính năng mới.\n- Phối hợp cùng các nhà cung cấp trong và ngoài nước triển khai các giải pháp Công nghệ mới nhất về phát triển ứng dụng di động.\n\nYour skills and experience\n- Có từ 03 năm kinh nghiệm làm việc tại các công ty hoặc dự án về lập trình di động, ưu tiên ứng viên có kinh nghiệm với Flutter.\n- Có ít nhất 01 năm kinh nghiệm làm việc với từng nền tảng iOS và Android.\n- Có kinh nghiệm trong việc xây dựng CI/CD cho nền tảng di động.\n- Nắm vững cách thức viết và tích hợp Native Module, Native View để giao tiếp với Flutter và React Native, cũng như giao tiếp giữa JavascriptEngine và native.\n- Có kiến thức về state management và local storage như SQLite, Shared Preferences...\n- Thành thạo sử dụng XCode, Android Studio và các công cụ phân tích như Flipper hoặc Dart DevTools.\n- Đã từng tham gia phát hành ít nhất 02 ứng dụng trên App Store hoặc Google Play.\n- Ưu tiên ứng viên có kinh nghiệm làm việc với Backend (Spring Boot, Java) và web frontend (ReactJS, AngularJS, VueJS).\n\nWhy you\'ll love working here\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể… \n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\nCơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng \n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng \n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\nMôi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng \n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(297, 188, 2, 'Java Web Developer (Java/ReactJS)', 'Top 3 reasons to join us\n- Very attractive salary package and Bonus\n- Overseas: Technical trainings and certifications\n- Global career opportunity\n\nJob description\nPerform development activities to build new and maintain existing WEB-based software systems using Java Frameworks, Front-end frameworks and databases.\nResponsibilities\n- Participate in developing web applications, new modules, features from beginning till end in the functional system (It can be Full-Stack from Frontend to Backend services and databases depends on skills and experiences).\n- Participate in analyzing requirements, design architecture, perform coding, unit tests, testing and technical documentation in line with user & system requirements to deliver source code, documents and test scripts that meet client’s needs and meet the release milestone.\n- Perform bugs fixing, maintaining, enhancement existing WEB application modules.\n- Assist Team Leads, Managers in reporting project status and deliverable estimations.\n- Perform code review and supports colleagues.\n- Conduct training & coaching team members in software engineering development if required.\n- Supports team leads on maintaining development environments if required to make sure smooth development.\n- Perform 3rd level support in and after office hours if needed to ensure fastest possible recovery to service.\n\nYour skills and experience\nSkills & Qualifications:\n- Software development skills using Java and ReactJS are required.\n- Good problem-solving skills.\n- Communication skills: Intermediate-level English (especially reading and writing).\n- Ability to work independently, proactive problem solver.\n\nKnowledge & Experience:\n- Have at least 3-years working experience in web development using Java 17 or Spring Boot/ Spring Framework\n- Experience with RESTful Web Service with Spring/Spring Boot \n- Have at least 3-years working experience in web development using ReactJS and related libraries e.g. Redux, Webpack, Babel, Gulp, Sass, Axios\n- Experience coding multi-threaded Java applications\n- Experience in MySQL with stored procedures, SQL and index\n- Experience in application performance troubleshooting\n- Understand OOP concepts and design patterns\n- Able to perform code review and give suggestions on solutions and designs\n- Experience in Junit and Jet\n\nPLUS points:\n- Well design and develop web application with a large number of concurrent users and with high performance requirement is a BIG PLUS.\n- Experience with Java 21 is a PLUS\n- Experience/Knowledge on any of Redis, Elasticsearch is a PLUS\n\nWhy you\'ll love working here\n(*) BONUSES & REWARDS\n- Competitive Salary\n- 13th Month Salary & Performance Bonus \n- Employee of the Year Award\n(*) TRAINING & DEVELOPMENT\n- In-house & Overseas Training\n- Full reimbursement for international Technical Certification \n- Global career opportunity\n(*) ANNUAL PAID LEAVES\n- Vacation Leave: 12 days per year\n- Medical Leave: 8 days per year\n- 1 extra seniority day for every 3 years of service\n(*) HEALTHCARE\n- Annual Routine Check-up\n- Premium Healthcare Insurance \n- Comprehensive Insurance\n(*) WELLNESS AND LEISURE ACTIVITIES\n- Annual Team Building\n- Soccer & Badminton Club and Sports activities\n- Entertainment activities: Music band, Karaoke & Play-station time\n- Celebrations special events: Birthdays, Christmas, New Year/Year-end Party.\n(*) PERKS\n- Fruits Days Twice a Month\n- Unlimited snacks & beverages', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor, Menas Mall Saigon Airport, 60A Truong Son, Ward 2,, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(298, 260, 2, 'Devops Engineer (Cloud, AWS, Azure, CI/CD, English)', 'WHO ARE WE? \nDigital Unicorn is a French digital agency with a passionate and ambitious team. We specialize in:\n- Mobile Application Development\n- Website Development\n- AI/Deep Learning\n- UX/UI Design\nWe’re more than just a company — we’re a small hub for those who want to step into an international working environment. Here, you’ll train, work, and build your career foundation, all while growing friendships that last.\nAt Digital Unicorn:\n- We share and support each other\n- We build meaningful products for startups\n- We create a space where you can enjoy working and growing.\n\nWE ARE HIRING: DevOps Engineer\nLevel: Senior\nType: Full-time In-house, On-site\n\nAbout the Role\nWe are looking for a DevOps Engineer with strong experience in AWS and Azure to join our in-house team at Digital Unicorn. The ideal candidate will be responsible for building, maintaining, and optimizing infrastructure and CI/CD pipelines to ensure system reliability, scalability, and performance. You will play a critical role in supporting development teams and improving our deployment workflows in a high-growth environment.\n\nResponsibilities:\n- Design, implement, and manage CI/CD pipelines\n- Automate infrastructure using Infrastructure as Code (IaC) tools\n- Monitor system health, ensure high availability, and respond to incidents\n- Work closely with developers to streamline deployments and system integration\n- Optimize cloud infrastructure (AWS, Azure) for performance and cost\n- Ensure system security, backup, and disaster recovery readiness\n- Document systems and processes clearly\n- Contribute to continuous improvement initiatives in DevOps practices.\n\nYour skills and experience\n- 5+ years of hands-on experience in DevOps/Cloud Engineering\n- Proficiency with AWS and Azure cloud platforms\n- Experience with CI/CD tools (Jenkins, GitLab CI/CD, etc.)\n- Knowledge of containerization (Docker, Kubernetes)\n- Familiarity with monitoring tools (Prometheus, Grafana, etc.)\n- Strong scripting skills (Bash, Python, etc.)\n- Fluent English speaking ability is required\n- Excellent problem-solving skills and ability to work independently.\n\nWhy you\'ll love working here\n- Training policy, salary, and bonus that match your skills and experience\n- Provision of full of devices for work\n- 100% salary during the probation period\n- Full insurance policies\n- Dynamic, comfortable, and creative working environment\n- Team Building events/ company trips every year\n- Snacks and fruits for breaks\n- Sports activities to recharge positive energies\n- Immerse in an English-speaking environment for professional foreign communication.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3F, 94 Ho Nghinh, Son Tra, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(299, 206, 2, 'Senior .NET Enginer', 'Top 3 reasons to join us\n• Attractive remuneration package with 18 days off\n• Smart people, interesting project & swiss quality\n• Travel opportunities to Switzerland\n\nJob description\nYour responsibilities\n• Participate in innovative software development life cycle using agile methodologies\n• Adhere to the coding standards, best practices, common design patterns & principles\n• Delivery of high-quality software together with the team, including design, code, troubleshooting, tests, documentation\n• Write the technical design and detailed design for the tasks\n• Self-manage tasks as per the timelines and quality  \n• Coach, supervise or lead when necessary other developers and team members  \n\nYour skills and experience\nYour qualifications\n• Bachelor’s degree in computer science or equivalent\n• At least 5 years’ experience in software development of this applied stack\n• Good knowledge of OOP, SOLID principles, Design pattern, data modeling\n• Able to read and write technical documents in the English language\n• Good technical, analytical, and problem-solving skills\n• Passionate, pro-active and keen to learn new technologies (or moving to mission part)\n• Experience in the .NET technology and ecosystem\n• Proven experience of coaching and supervising other developers and team members\n• Proven experience: .NET Core, NHibernate or Entity Framework, ...  \n\nNice to have\n• Knowledge of the Agile methodology (Scrum)\n• Knowledge of CI/CD (Jenkins, Docker)\n• Experience and/or certifications on Amazon, Azure and Oracle clouds.\n• Experience in Web development (Angular, ReactJS) or Windows App development\n• Experience in leading a project or a team\n• Oral communication skills in English\n\nWhy you\'ll love working here\n• Professional European-based company\n• Attractive salary\n• Performance bonus of up to 4 months‘ salary\n• Opportunities for travel to Europe\n• Hybrid home/office working model\n• Flexible working time\n• Structured training & development roadmap\n• Good work-life balance\n• Premium healthcare insurance\n• Loyalty programs\n• Well-being activities\n• Annual company trips and team-building events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CII Building, 152 Điên Biên Phủ, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(300, 261, 2, 'Backend Developer (NodeJS, Java, PHP)', '1. Tham gia phát triển và duy trì hệ thống back-end cho các dự án phần mềm hỗ trợ đầu tư chứng khoán, đào tạo trực tuyến và các lĩnh vực khác mà công ty đang mở rộng.\n2. Thiết kế, xây dựng và tối ưu hóa các API bảo đảm tính ổn định, hiệu suất và bảo mật.\n3. Thu thập dữ liệu tự động từ các nguồn, chuẩn hóa và lưu trữ dữ liệu.\n4. Phối hợp với nhóm front-end, QA, PM… trong quá trình phát triển và triển khai dự án.\n5. Tham gia nghiên cứu, cập nhật các xu hướng công nghệ mới và ứng dụng vào sản phẩm.\n\nYour skills and experience\n1. Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các ngành liên quan; hoặc tốt nghiệp đại học ngành khác nhưng có tối thiểu 2 năm kinh nghiệm lập trình back-end.\n2. Thành thạo ít nhất một ngôn ngữ/lộ trình back-end (Java, Node.js, Python, .NET, PHP, v.v.).\n3. Có kinh nghiệm làm việc với cơ sở dữ liệu (SQL hoặc NoSQL).\n4. Biết sử dụng các công cụ lập trình AI, biết sử dụng các cơ sởi dữ liệu phi truyền thống như Neo4j là lợi thế.\n5. Ưu tiên ứng viên đã có kinh nghiệm tham gia dự án thực tế, đặc biệt là các dự án có yếu tố AI.\n6. Tinh thần cầu tiến, có khả năng học hỏi nhanh và làm việc nhóm tốt.\n\nWhy you\'ll love working here\n1. Được làm việc trong các dự án sáng tạo, có hàm lượng công nghệ cao, tiếp cận nhiều thách thức thú vị.\n2. Có cơ hội nâng cao chuyên môn, kỹ năng nghiệp vụ và thăng tiến trong công việc.\n3. Mức lương cạnh tranh, thưởng theo hiệu quả công việc và đóng góp.\n4. Môi trường làm việc thân thiện, khuyến khích sự chủ động và sáng tạo.\n5. Tham gia đầy đủ các chế độ bảo hiểm và các phúc lợi khác theo quy định công ty.\nTHÔNG TIN KHÁC\n• Thời gian làm việc: Thứ 2 - Thứ 6, Thứ 7 ngày lẻ.\n• Ưu tiên: Ứng viên có khả năng Full-stack (làm được cả front-end và back-end), ứng viên sử dụng thành thạo các công cụ hỗ trợ AI\n• Liên hệ ứng tuyển: Gửi CV kèm Portfolio/Dự án nổi bật (nếu có) đến Bộ phận Nhân sự của Công ty Cổ phần Truyền thông và Dịch vụ số Kiến Lửa.\nRất mong được hợp tác và chào đón các ứng viên tài năng cùng đồng hành trong hành trình mở rộng và phát triển sản phẩm công nghệ sáng tạo của Kiến Lửa!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, tòa nhà ADG, số 37 Lê Văn Thiêm, phường Nhân Chính, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(301, 184, 2, 'Expert/Senior Java Developer (Life Insurance Project)', 'Top 3 reasons to join us\n- Top-tier banking environment in Vietnam\n- Challenging opportunities for the “Greater” You\n- Attractive career path and benefits\n\nJob description\nA. Software Development\n• Responsible for ensuring that the bank\'s digital platforms work well by managing back end site databases, performance issues, security and that the server, application and database communicate with each other.\n• Responsible for collaborating with business tribes to understand the needs and technical requirements before building a web application.\n• Responsible for the server-side web application logic and integration with front-end codes\n• Collaborate with Front End Developers to design more functional and cohesive codes to enhance user experience.\n• Responsible for driving the application lifecycle with a key focus in coding and debugging of web applications based on feedback from testers and users.\n• Compile and analyze data, process and codes to troubleshoot problems and identify areas for improvement.\n\nB. Software Documentation\n• Work closely with tribe and squad members to translate business requirements into technical design documents.\n• Review and implement technical requirement documents by coding flowcharts, layouts, diagrams, charts, code comments and guides for the program.\n\nYour skills and experience\nA. Domain Expertise\n• 8-10 years of relevant experience in Java and experience in Life Insurance or Financial product is preferable\n• Experience in working with SQL, microservices and AWS is a big plus\n• Database: Experience with Oracle, Microsoft SQL Server, PostgreSQL preferred\n• Operating system: Priority to have experience in Linux, Redhat environment\n• Priority is given to having experience in CI/CD, logging platforms, monitoring platforms\n• Priority is given to those who are willing to do a variety of jobs in both programming languages and different platforms and frameworks (Spring, Backbase, Jira, JiraSM, Power Platform, Power BI...)\n\nB. Agile/Digital Experience\n• Understands Agile principles, practices and Scrum methodologies.\n• Experience working in Agile teams to support digital transformation projects.\n\nC. Qualifications\n• Bachelor\'s degree in computer science, software engineering or information technology\n• Good at English is a big plus\n\nD. Personal Attributes\n• Passionate about technology and excited about the impact of emerging / disruptive technologies\n• Ownership mindset with a focus on getting things fixed, not simply discovered\n• A self-starter who thrives in an environment that fosters entrepreneurial thinking and innovation\n• Believes in the non-hierarchical culture of collaboration, transparency and trust across the team.\n\nWhy you\'ll love working here\nWHY BECOME IT/DATA EXPERTS AT TECHCOMBANK?\n- Investing over 500 million USD to develop large-scale IT projects, Techcombank is one of the leading banks in Technology trends in Vietnam\n- You will grow with Techcombank by having the opportunity to learn from top experts from across the world\n- Techcombank provides a rewarding remuneration structure that commensurate with your achievement and contribution\n- Techcombank is the Top 2 Best place to work in the banking industry where you can experience various exciting activities throughout the year: Company anniversary, Team building, Active Saturday, Year End Party, etc.\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'C5 Building Tower, D’Capitale Tower, 119 Tran Duy Hung, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(302, 262, 2, 'Cloud Business Development Manager', 'Huawei is a leading global provider of information and communications technology (ICT) infrastructure and smart devices. We have 208,000+ employees and operate in over 170 countries and regions, serving more than three billion people around the world. We are committed to bringing digital to every person, home and organization for a fully connected, intelligent world. Total R&D investment over the last decade now exceeds CNY977.3 billion.\n\nKEY RESPONSIBILITIES OF THIS ROLE\n\n1. Explore and identify key account in the defined industry/segment. Perform account insight about the market position, business portfolio, investment structure and organization structure.  \n2. Define commercial model. Develops and drive the engagement with business partners; Works towards nurturing the existing accounts.  \n3. Develop and maintain key account plans that identify opportunities for CLOUD to deliver values to customer  \n4. Keeping abreast and insight of competition, competitive issues and products.  \n5. Meet assigned sales and revenue targets and strategic objectives.\n\nYour skills and experience\n\nPROFESSIONAL EXPERIENCE/QUALIFICATION  \n• Knowledgeable about the Vietnam Cloud Market, Industry/industry segments features, quick locator to target segments arising with opportunities.  \n• Knowledgeable about the unique capabilities of CLOUD\'s services/products, and mastery of horizontal and vertical cloud solution. Capabilities to translate customer requirement into CLOUD service/products/solutions.  \n \nBusiness Skills  \n• Good at English, skills in business sense, problem solving, project management and analytical  \n• Great communication skills, team spirit, and a can-do attitude  \n• Knowledge of identifying, developing, negotiating, and closing large-scale IT technology deals.  \n• Operates as Cloud expert and sales lead in the areas of IAAS, PAAS, SAAS cloud Integration and cloud native technology  \n• Bachelor & above, Preferred Major in IT Related or MBA  \n\nWhy you\'ll love working here\n\n* Working time and benefits:  \n• Monday to Friday (08:30-18:00).  \n• Competitive Salary and performance bonus. Full salary in 2 months of probation.  \n• Comprehensive online training platform and overseas training opportunities.\n• Participating in full insurance benefits (health insurance, social insurance, unemployment insurance), the company supports 24/24 accident insurance and health care insurance for employees.\n• Professional working environment, multinational company, good career development opportunities. Cultural and sports activities, taking care of employees\' health and life are organized periodically...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '33rd Floor, Keangnam Landmark, E6, Pham Hung Street, Me Tri Ward, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(303, 263, 2, 'Game LivOps Manager', 'Neopets is a vibrant and beloved online virtual pet game where users can adopt, care for, and interact with their own Neopets. With a rich history and a dedicated 150 M+ fan base, Neopets continuously evolves to provide engaging experiences through games, activities, and a vast virtual world. Our target audience primarily includes Millennials and Generation Z, who are passionate about digital experiences and community engagement. We aim to create nostalgic yet innovative content that resonates with these demographics.\n\nResponsibilities:\n- Plan, execute, and optimize LiveOps strategies for free-to-play mobile games, focusing on casual or Match-3 genres.\n- Analyze key performance indicators(KPIs) to drive performance improvements and enhance player retention.\n- Design and manage in-game events, special offers, and content calendars to maximize engagement and revenue.\n- Collaborate with cross-functional teams to ensure seamless execution of LiveOps initiatives.\n- Thrive in a fast-paced, reactive environment with rapid iteration cycles to adapt to player feedback and market trends.\n\nYour skills and experience\nRequirements:\n- Approximately 10 years of experience in LiveOps for free-to-play mobile games, ideally in casual or Match-3 genres.\n- Strong data-driven mindset with expertise in interpreting KPIs and optimizing game performance.\n- Proven skills in designing and managing in-game events, offers, and content calendars.\n- Comfortable working in a fast-paced environment with quick iteration cycles.\n- Fluent in English (written and spoken).\n\nWhy you\'ll love working here\nWe offer competitive compensation, a dynamic work environment, and professional growth and development opportunities. Join our team of talented developers and contribute to the success of our cutting-edge projects.\n\nTo apply, please submit your resume, portfolio, and any relevant code samples demonstrating your expertise in Node.js and PHP. Only shortlisted candidates will be contacted for further technical evaluation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote, Other, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(304, 264, 2, 'Senior Process Quality Assurance (PQA, Auditing)', 'Top 3 reasons to join us\n- International working environment\n- Competitive compensation package and benefits\n- Interacting with leading-edge technologies\n\nJob description\n- Support for IoT system Integration Services, which is provide comprehensive expertise in both industry domains and IT+OT data convergence:\n- Collaborate and report Global QA Team about project status and process compliance periodically.\n- Define, customize the software development process in the projects based on the company process.\n- Monitor process compliance\n- Periodically perform process audit and product audit.\n- Prepare QA reports and send to Managers or clients as needed.\n- Consult client, Project managers, other members for process, templates, checklists.\n- Maintain QMS satisfying ISO 9001 requirement, CMMi.\n- Provide Senior Leadership Team project status report and process compliance periodically.\n- Train employees for the process, related tools and techniques.\n\nYour skills and experience\n• Bachelor’s degree in computer science, Information Technology or relevant major.\n• More than 4 years experiences of software development process, quality assurance (QA) or similar role.\n*Knowledge, Skills and Abilities:\n• Knowledge of QA process audit, product audit, statistic, quality report and analysis.\n• Knowledge of QA system development and implementation.\n• Knowledge of ISO 9001, CMMi… \n• Excellent cooperation and communication skills.\n• Responsible and proactive.\n• Ability to work independently.\n• Proficiency in English.\n\nWhy you\'ll love working here\nAt Hitachi Digital Services, we enjoy:\n- Unique opportunity to work with multinational team of Hitachi in over 130 countries.\n- Incomparable chance to participate in full Software Development Life Cycle (SDLCs) and comprehensive soft skills training.\n- Competitive remuneration with attractive allowances & bonuses.\n\nHitachi Digital Services offers a competitive benefit packages. Come join us to enjoy:\n- Opportunities for advanced career development overseas, including the US, UK, Japan...\n- Competitive & attractive compensation and benefits packages:\n- Allowance for English, Japanese language certifications.\n- Subsidy for transportation and meals.\n- 13th salary & Bonus\n- Additional Premium Health Insurance Package for employees.\n- Annual checking of health and company trip for employees.\n- Flexible working hours.\n- Being an integral part of a dynamic and fast-growing global enterprise.\n- An open, professional, and nourishing environment with out-side of work activities, such as football, tennis, badminton, dancing, music, and charity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Helios Bldg + QTSC9, Quang Trung Software City, Tan Chanh Hiep Ward, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(305, 265, 2, 'Senior Frontend Engineer (ReactJS)', 'Here at Skedulo we’re on a mission to support the 2.7 billion people in the world—and the companies that employ them—who do not work at a desk every day. Our global teams are collaborative, ambitious, innovative, and passionate about helping our customers realize their fullest potential by enabling their mobile workforces.  \n\nThe Skedulo team is a tight-knit group of builders who are passionate about shaping . We are looking for motivated, self-starters who share our , challenge the status quo, and push the pace of innovation in order to accelerate growth. If you’re drawn to solving hard problems and want to help design software that will make a difference in people’s lives, Skedulo is for you. Visit our  to learn more about what Skedulo does and to learn more about our people and team.\n\nThe Senior Frontend Engineer will be a key member of the Solution Engineering team in VN. Engineers display a solid understanding of core engineering concepts. They are focused on growing as an engineer, learning the team’s tools and current processes, as well as a strong background in Engineering best-practices like automated testing, source control, and agile planning.\n\nThey communicate well and are capable of delivering feedback to peers and their manager. When given a task with unclear requirements they know how to ask for clarification, and ensure that all assumptions are vetted before work starts to reduce the need for re-work. They understand how their work fits into the larger picture for their team, and use this to identify conflicting requirements to their team lead and project manager. Senior Frontend Engineer also works with the FE team to share best practices and provide support/guidance to junior members.\n\nDay to Day  \n- Work on projects with high complexity, large or strategic projects.  \n- Writing and reviewing code from the sprint backlog inline with front-end team best practices.  \n- Assisting in driving team sprint execution to ensure timelines are met without compromising on quality.  \n- Anticipates and communicates blockers or delays for their work (or their squads) before they require escalation.  \n\nTechnical Duties  \n- Consistently writes production-ready code that is easily testable, easily understood by other engineers, and accounts for edge cases and errors.  \n- Provides technical advice and weighs in on technical discussions / decisions that impact their team.  \n- Ensures their commitments are realistic, understands their priority and urgency, and delivers upon them accordingly.\n\nCommunication & Leadership Duties  \n- Communicate within your team in an effective, clear, concise manner in both written and verbal form on technical and non technical subjects.  \n- Helps their fellow team members overcome obstacles, resolve blockers, and complete work tasks.  \n- Mentors more junior teammates in an open, respectful, flexible, and empathetic manner.  \n- Resolving code-based defects discovering either through project work or through our technical support team.  \n- Contributing to continual improvement of coding standards and methods used by our technical development team.  \n- Contributing to technical documentation such as technical design and as built documents.\n\nYour skills and experience  \n- MINIMUM QUALIFICATIONS  \n- Must have at least 5+ years of commercial experience in Front-end web development.  \n- Experienced in Front end unit testing frameworks (ideally Mocha or Jest).  \n- Experienced in CSS Preprocessors (ideally Sass).  \n- Must have strong written and oral English language communication skills.  \n\n- DESIRED SKILLS & EXPERIENCE  \n- Will have at least 3+ years’ experience developing web applications with ReactJS.  \n- Ideally experienced with one or more of the following: Vuejs, AngularJs.  \n- Strong experience in modern front-end build tools (e.g. Git, Webpack, Yarn, NPM).  \n- Familiar with RESTful API, GraphQL.  \n- Knowledgeable in modern authorization mechanisms, such as JSON Web Token.  \n- Beneficial to have prior experience working with offshore and distributed teams.  \n- Exposure to Agile development methodologies such as Scrum and Kanban.  \n- Prior experience with common cross functional tools in JIRA, Confluence, GitHub.  \n- Understands the importance of contributing to the CI/CD pipeline and automation.\n\n- ADDITIONAL REQUIREMENTS  \n- Must be authorized to work without visa sponsorship in Vietnam to be considered for this position.  \n- Must be willing to work in the Ho Chi Minh office at least 3 days per week (Hybrid); and reside within 35 miles of HCM.\n\nWhy you\'ll love working here  \n- Competitive Salary Package including 13th month bonus  \n- New Hire Stock Options  \n- Employee Referral Bonus Program  \n- 3 volunteer days per year  \n- 100% employer paid subscription to Modern Health (includes 6 coaching & 6 therapy session per year)  \n- A generous budget to spend on setting up your home office or WFH station  \n- 100% employer paid access to Udemy (Learning & Development)  \n- Paid Parental Leave for both carers (12 weeks)  \n- Hybrid Work Model (3 days in the office & 2 days work from home)  \n- Private Medical Benefits (PTI Health Insurance) for employee + family  \n- 100% employer paid annual health check  \n- 7 paid sick leave days per year  \n- 20 paid personal leave days per year  \n- 12 paid public holiday days per year  \n- Company & Team Offsite Events provided  \n- Our office offers open and creative workspaces with room to play, reflect, and relax  \n- Our team works hard but also plays hard; we will challenge your best table tennis and PS4 skills  \n- Kitchen stocked with snacks & drinks  \n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'An Phú Plaza, 117-119 Ly Chinh Thang street, Vo Thi Sau ward, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(306, 227, 2, 'Quality Engineer Lead', 'Top 3 reasons to join us\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description\n**Testing and Quality Assurance:**\n- Design, develop, and execute test plans and test cases to ensure comprehensive coverage of product requirements.\n- Perform functional, integration, regression, and system testing for both frontend and backend systems.\n- Create and maintain detailed reports on testing progress, defects, and outcomes.\n- Review and refine test strategies to optimize quality and efficiency.\n- Ensure cross-browser, cross-platform, and device compatibility for applications.\n\n**Automation Testing:**\n- Develop, implement, and maintain automated test scripts using tools like Cucumber, Serenity BDD, and Playwright.\n- API testing is conducted using tools such as Postman and performance testing with JMeter.\n- Collaborate with the DevOps team to integrate automated tests into CI/CD pipelines using Jenkins and Git.\n- Leverage programming skills in Java or JavaScript to enhance testing frameworks.\n\n**Collaboration and Delivery:**\n- Collaborate with BAs, developers, and product managers to understand requirements, provide input, and ensure alignment.\n- Act as a quality advocate, focusing on delivering features that meet user needs and maintain high standards.\n- Evaluate product readiness and release timelines based on test results and team discussions.\n\n**Leadership and Influence:**\n- Share quality-focused practices and promote a quality-first mindset within the team.\n- Mentor team members on testing techniques and workflows to enhance overall quality.\n- Ensure workflows and processes are followed consistently and improve them when necessary.\n\n**Continuous Monitoring and Improvement:**\n- Monitor product performance and user feedback in production environments to identify improvement areas.\n- Stay updated with industry trends, tools, and best practices to continually improve testing processes.\n- Drive initiatives to improve product quality, user satisfaction, and team productivity.\n\nYour skills and experience\n**Education:** Bachelor\'s Degree in Information Technology, Computer Science, or a related field from a reputable university.\n**Experience:** Minimum of **4 years of experience** as a Software Tester or QC Engineer, with significant exposure to both **manual** and **automated** testing.\n**Technical Skills:**\n- Proficient in **coding** with the ability to learn and apply **automation** testing tools.\n- Deep understanding of **APIs/Web-services** and familiarity with testing tools such as Postman, BrowserStack, and curl.\n- Knowledge of **Agile/Scrum** methodologies and practices like TDD/BDD.\n\n**Tools and Documentation:**\n- Proficient with **Atlassian** tools (Jira, Confluence) and mock-up tools (e.g., Figma, draw.io,..).\n- Ability to write Software Development Requirement Documents and Functional Specifications.\n- Experience with test **automation** frameworks (e.g., Playwright, Cucumber, cypress.io,..) is a plus.\n\n**Soft Skills:**\n- Excellent **Problem-Solving** skills and **Critical Thinking**.\n- Outstanding **Communication** and **Documentation** skills.\n- Ability to work collaboratively in a **fast-paced**, **Agile** environment.\n- Proactive and **self-motivated** with a strong sense of **ownership**.\n\n**Preferred (but not required)**\n- **ISTQB** certification or equivalent.\n- Experience in the **eCommerce** industry.\n- Familiarity with **CI/CD** pipelines.\n- Proficiency in **English**.\n\nWhy you\'ll love working here\n**Exceptional Total Compensation Package**\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Full salary during probation & Guaranteed 13th month salary.\n- 12 days work-from-home & 12 days of paid annual leave, plus seniority paid leave.\n- Global health insurance package for yourself and direct family members, plus annual health checkup.\n\n**Growth Opportunities**\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\n\n**Global Vision**\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi, New setup, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(307, 239, 2, 'Technical Expert (Semiconductor)', 'Top 3 reasons to join us\n1. Committed 13th-mth bonus + attractive yearly bonus\n2. Premium Healthcare for you and 2 family members\n3. 16++ days of paid leave per year\n\nJob description\nProducts: Semiconductor-based sensors (Bosch Sensor Tech)\nPosition Overview:\nWe are seeking a highly qualified and experienced Technical Expert in the Semiconductor industry to join our dynamic team at Bosch Sensor Tech in Vietnam. The ideal candidate will possess extensive technical expertise in semiconductors and relevant sensor technologies, with a proven track record of delivering innovative solutions in complex environments. This role requires a strategic thinker capable of navigating interdisciplinary challenges, influencing both software and hardware development methodologies, and ensuring alignment with our business objectives as we expand our regional and local operations.\n\nKey Responsibilities:\nArchitectural Design & Leadership:\n- Lead the design and evolution of robust software or ASIC architectures that not only meet but exceed software and hardware requirements, ensuring scalability, performance, and maintainability.\n- Derive architectural drivers, refine quality goals, and identify technical and project constraints to inform and guide architectural decisions.\n\nArchitecture Evaluation:\n- Conduct comprehensive evaluations and verifications of architectural designs to ensure compliance with established quality standards and project requirements, fostering a culture of excellence.\n\nTechnical Guidance:\n- Provide expert support to development teams throughout the software and hardware lifecycle, including requirement development, detailed design, implementation, integration, and testing.\n- Mentor and guide team members in best practices for software and ASIC architecture, promoting professional growth and technical excellence.\n\nStrategic Contributions:\n- Contribute to the definition, implementation, and evaluation of business strategies, including decisions related to software reuse, third-party integrations, licensing, and make-or-buy analyses.\n- Identify and analyze interdisciplinary problems at the system level, proposing innovative solutions that align with organizational objectives and drive business success.\n\nProcess Development:\n- Drive the development and tailoring of software and hardware processes to meet project-specific needs, ensuring adherence to industry standards and best practices.\n- Create and enhance guidelines for design principles, patterns, and coding/modeling standards to cultivate a culture of excellence in both software and hardware development.\n\nMethodology Influence:\n- Influence or define software and hardware development methodologies and tools, ensuring alignment with the latest industry trends and organizational needs.\n\nYour skills and experience\n- Bachelor’s or Master’s degree in Electronics, Mechatronics, Computer Science, or a related field; a PhD in a relevant field is a plus.\n- Minimum of 6 years of experience in the semiconductor industry, with a strong focus on software or ASIC architecture.\n- Proficiency in both embedded software and hardware, facilitating effective discussions with technical experts across Bosch groups, customers, and suppliers.\n- Strong ability to read and interpret schematics and datasheets for electronic components, demonstrating a solid understanding of hardware design.\n- Proven self-discipline, self-motivation, and a collaborative team spirit, with a commitment to driving team success.\n- Excellent communication skills in English, both oral and written, with the ability to convey complex technical concepts to diverse audiences.\n- Relevant certifications in semiconductor design, embedded systems, or software architecture (e.g., IEEE, IPC, or specific vendor certifications).\n- Familiarity with cutting-edge semiconductor technologies such as FinFET, SOI, or GaN.\n- Experience with MEMS (Micro-Electro-Mechanical Systems) design and fabrication.\n- Understanding of industry standards and regulations such as ISO 9001, ISO 26262 (functional safety), and other relevant quality management systems.\n- Knowledge of supply chain and manufacturing processes, with an understanding of semiconductor manufacturing processes and the ability to collaborate closely with manufacturing teams.\n\nWhy you\'ll love working here\nWhy BOSCH?\n- Because we don\'t just follow trends, we create them.\n- Because we do not just follow trends, we create them. Together we turn ideas into reality, working every day to make the world of tomorrow a better place.\nDo you have high standards when it comes to your job? So do we. At Bosch, you will discover more than just work.\n\nBenefits and Career Opportunities\n- Working in one of the Best Places to Work in Vietnam and Top 30 of the Most Innovative Companies all over the world\n- English-speaking environment, with opportunity to be part of innovation team and work in global projects\n- Onsite opportunities\n- Engage in our diverse training programs which surely help strengthen both your personal and professionalism\n- Flexible working time and working model\n- 13th-month salary bonus + attractive performance bonus (you\'ll love it!) + annual performance appraisal\n- 100% offered salary and mandatory social insurances in 2-month probation\n- 15++ days of annual leave + 1-day of birthday leave\n- Premium health insurance for employee and 02 family members\n- Lunch and parking allowance\n- Good benefits of company activities such as: football, badminton, yoga, Aerobic, team building…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Capital Place, 29 Lieu Giai Street, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(308, 266, 2, 'Data Engineer (Python, SQL, Databricks)', 'We’re looking for a Data Engineer to support our clients Microsoft Fabric platform. This is a hands-on role focused on building reliable, production-grade data pipelines and curated datasets. While there may be some ad hoc work, the core of the role is structured, scalable data engineering not data science.\n\nYou’ll work with Dataflows, Pipelines, Notebooks (for ETL, not ML), and Lakehouses to deliver trusted data to analysts and business users.\n\nWe also welcome programmers with strong SQL and Python skills who are looking to transition into data-focused roles, especially considering the growing demand for data infrastructure alongside AI. Experience with data integration, API ingestion, or working with Apache Spark or Pandas is highly valued.\n\nBuild and maintain data pipelines using Microsoft Fabric (Pipelines, Dataflows, Lakehouse)\nWrite efficient SQL for transformations, aggregation, and data quality checks\nUse Python in notebooks for ETL workflows using Pandas or Spark\nDesign datasets across Bronze, Silver, and Gold layers following medallion architecture\nImplement data lineage, monitoring, and validation\nHandle some ad hoc data requests while focusing on reusable, maintainable solutions\nApply basic governance practices (e.g. RLS, access controls, metadata tagging)\n\nCandidates must be able to perform the responsibilities outlined in this role. The following is a guide to the type of experience we’re looking for — real-world, hands-on experience matters more than formal credentials alone.\n\nYou should meet one of the following:\nA Bachelor’s degree in Computer Science, IT, or Software Engineering with at least 2 years of relevant experience OR\n3+ years of professional experience in data engineering, backend development, or SQL-heavy roles OR\n2+ years of hands-on work with Microsoft Fabric, Azure Synapse, Azure Data Factory, or Databricks\n\nTechnical Requirements\nStrong in SQL and/or Python for building scalable data pipelines\nExperience with Microsoft Fabric, Synapse, ADF, or Databricks \nKnowledge of Delta Lake, parquet formats, and other standard formats.\nUnderstanding of star schema, fact/dimension modelling, and medallion architecture\nComfortable using Git and CI/CD tools for data workflows\nBonus: Familiar with Power BI, DAX, Purview, or Dynamics 365\n\nWe want our staff to grow, we encourage that they investigate new technology and spend time doing R&D.\n\nAs a company it is our responsibility to provide all the tools and training needed to help our developers become the best they can be.\n\nWe invest in our employees by paying for certifications that are within our companies focus.\n\nIt is important that you enjoy your work that you are motivated and excited every day.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Dao Tan Street, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(309, 267, 2, 'Senior Fullstack Developer ( .Net Core + VueJS, SQL)', 'Chúng tôi đang tìm kiếm một Full Stack Developer giàu kinh nghiệm để tham gia phát triển và duy trì các hệ thống quản lý bán hàng, bảo hành, quản lý kho hàng, tài chính và chăm sóc khách hàng. Ứng viên sẽ chịu trách nhiệm xây dựng các giải pháp công nghệ toàn diện từ giao diện người dùng đến backend và cơ sở dữ liệu.  Trách nhiệm chính:\n\nFrontend (VueJS)\n- Xây dựng giao diện người dùng responsive và thân thiện sử dụng VueJS\n- Tối ưu hóa trải nghiệm người dùng (UX/UI) cho các module mua bán hàng \n- Tích hợp API và xử lý dữ liệu real-time \n\nBackend (.NET Core)\n- Thiết kế và phát triển RESTful API sử dụng .NET Core \n- Phát triển các module quản lý kho hàng (nhập/xuất/tồn kho) \n- Xây dựng hệ thống quản lý quy trình chăm sóc khách hàng \n- Đảm bảo bảo mật và hiệu suất của ứng dụng \n- Quản lý Cơ sở dữ liệu \n\nDatabase (SQL Server)\n- Viết stored procedures, functions và triggers \n- Đảm bảo tính toàn vẹn và bảo mật dữ liệu Thực hiện backup và recovery dữ liệu \n\nPhân tích và Thiết kế \n- Phân tích yêu cầu từ các bộ phận và stakeholders \n- Thiết kế kiến trúc hệ thống và database schema \n- Tạo tài liệu kỹ thuật và user manual \n- Đề xuất giải pháp công nghệ phù hợp\n\nYêu cầu Kỹ thuật:\n- 4-5 năm kinh nghiệm  phát triển full stack web application \n- Có kinh nghiệm xây dựng hệ thống thương mại điện tử, quản lý bán hàng, quản lý kho, CRM \n- Thành thạo VueJS (Vue 2/3, Vuex/Pinia, Vue Router) \n- Thành thạo .NET Core (ASP.NET Core Web API, Entity Framework Core) \n- Có kinh nghiệm làm việc với cơ sở dữ liệu SQL Server (T-SQL, stored procedures, indexing) \n- Hiểu biết về HTML5, CSS3, JavaScript ES6+ \n- Kinh nghiệm với Git version control \n\nKỹ năng Mềm:\n- Khả năng làm việc nhóm tốt, có tinh thần hợp tác\n- Khả năng làm việc độc lập, tự quản lý công việc hiệu quả \n- Kỹ năng phân tích và hiểu yêu cầu từ khách hàng \n- Kỹ năng giao tiếp và trình bày ý tưởng rõ ràng \n- Tư duy logic, khả năng giải quyết vấn đề \n- Chủ động học hỏi và cập nhật công nghệ mới\n\nWhy you\'ll love working here\n- Lương cạnh tranh theo năng lực (thỏa thuận)\n- Thưởng tháng 13, thưởng tết \n- Bảo hiểm sức khỏe + các chế độ phúc lợi đầy đủ \n- Review tăng lương định kỳ hằng năm \n- Làm việc trong môi trường thân thiện, chuyên nghiệp \n- Đầy đủ các trang thiết bị làm việc \n- Cơ hội thăng tiến, phát triển kỹ năng và nghề nghiệp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '436a/73 Đường 3/2 Phường 12 , District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(310, 255, 2, 'Senior Full-Stack Developer (.NET, ReactJS, NodeJS)', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nJob Description\nWe are seeking a highly skilled and experienced Senior Full Stack Developer to join our in-office team in Ho Chi Minh City, Vietnam. The ideal candidate will possess advanced knowledge and experience in .NET, React, Node.js, and SQL Server. Additionally, we are looking for an individual who is proficient in both modern event-driven architecture and legacy 3-tier architecture and has experience with AI plugins in their Integrated Development Environments (IDEs). Proficiency in writing micro frontends and microservices, transforming legacy applications into modern patterns, and experience with Azure DevOps is essential. The candidate should also have experience with the SAFe Agile Methodology and acting as a technical team lead over a scrum team.\n\nCore Responsibilities\n- Design, develop, and maintain scalable, reliable, and efficient full-stack applications using .NET, React, Node.js, and SQL Server.\n- Ensure performance, quality, and responsiveness of applications.\n- Identify and correct bottlenecks and fix bugs in a timely manner.\n- Help maintain code quality, organization, and automation.\n- Implement and manage both modern event-driven and legacy 3-tier architectures.\n- Integrate and utilize AI plugins to enhance development processes and outcomes.\n- Develop and maintain micro frontends and microservices to ensure modularity and scalability.\n- Transform and modernize legacy applications to conform to new architectural patterns.\n\nFunctional Responsibilities\n- Collaborate with cross-functional teams to define, design, and ship new features.\n- Mentor junior developers and provide technical guidance to the team.\n- Lead a scrum team as a technical team lead, ensuring effective collaboration and project delivery.\n\nYour skills and experience\n- Technical Skills\n- Minimum of 5 years of professional experience as a .NET Full Stack Engineer.\n- Expertise in React, Node.js, and SQL Server.\n- Strong experience with both modern event-driven architecture and legacy 3-tier architecture.\n- Proficient in using AI plugins with IDEs to improve development efficiency.\n- Solid understanding of software development principles, design patterns, and best practices.\n- Excellent problem-solving skills and attention to detail.\n- Strong communication and teamwork abilities.\n- Ability to work in an agile environment and adapt to changing requirements.\n- Proficiency in developing micro frontends and microservices.\n- Experience in transforming legacy applications to modern architectural patterns.\n- Experience with Azure DevOps.\n- Experience with SAFe Agile Methodology.\n- Excellent English communication skills are required.\n\nThings that will separate you from the rest\n- Experience as a technical team lead, particularly over a scrum team.\n- Experience with cloud platforms such as AWS, Azure, or Google Cloud.\n- Familiarity with containerization technologies like Docker and Kubernetes.\n- Knowledge of CI/CD pipelines and DevOps practices.\n- Experience with microservices architecture.\n\nEducation or Certifications\n- Bachelor’s degree in Computer Science, Information Technology, or related field.\n\nWhy you\'ll love working here\n- Highly competitive salary\n- Full salary for probation & full coverage of social insurance.\n- Premium healthcare for you and your beloved one.\n- Monthly childcare support\n- 13th-month salary.\n- Annual Leave: 15 days; Paternity Leave: 6 weeks, Bereavement leave: 10 days.\n- Flexible working time, focus on output (no checking time attendance)\n- Various active sporty clubs: Football, Billiards, Badminton, E-sport clubs\n- Frequent opportunities to travel to US headquarter from 3-6 months.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Six8 Building: 24-26 Phan Dinh Giot Street, Tan Binh District, HCMC., Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(311, 268, 2, 'Automation Specialist (Fullstack)', 'Top 3 reasons to join us\n- Friendly International environment\n- Passionate colleagues\n- Competitive salary \n\nJob description\nAre you an automation enthusiast with a strong fullstack development background, eager to make a significant impact in a dynamic, international environment? We are seeking a highly motivated and technically adept Automation Specialist to join our team in HCMC. You will play a pivotal role in optimizing our large customer\'s diverse processes through cutting-edge automation solutions, working closely with an international team.\n\nThis is a unique opportunity to leverage your coding prowess and passion for automation to drive efficiency, reduce costs, and enhance operational excellence across a wide range of sales and marketing business processes.\n\nWhat You\'ll Do:\n- Build, manage, and optimize automations across a variety of tools, including N8N, Zapier, Pipedream, HubSpot, and through custom scripting using NodeJS and Python.\n- Integrate internal and client-facing platforms seamlessly using APIs, webhooks, and middleware.\n- Provide insightful feedback to management regarding current automation projects, system performance, and future needs.\n- Test alternate designs and processing methods to assess feasibility, performance, and necessary modifications for implementation.\n- Modify system components or products to ensure strict conformance with engineering design and performance specifications.\n- Diagnose and repair equipment failures of existing automation systems, collaborating closely with maintenance teams.\n- Proactively identify process inefficiencies and independently create scalable automated solutions.\n- Document all workflows and automation logic in a clear, maintainable, and supportable format.\n- Continuously monitor and maintain automation stability and performance, ensuring high availability.\n\nYour skills and experience\nWhat We\'re Looking For:\n- 2+ years of professional experience as a Fullstack Developer, with strong proficiency in NodeJS, PostgreSQL, MongoDB and Redis.\n- A genuine "Automation Lover" – someone passionate about finding inefficiencies and solving problems through automation.\n- 1+ year of hands-on experience with process automation tools such as N8N, Zapier, Pipedream, and/or HubSpot.\n- DevOps skills, including experience with server management and configuration, Docker, and continuous integration/delivery practices.\n- Experience with API integrations, webhooks, and middleware development.\n- Excellent problem-solving skills and a proactive approach to identifying and resolving technical challenges.\n- Strong English communication and interpersonal skills, with the ability to collaborate effectively with international teams, management, integrators, and production staff.\n\nWhy you\'ll love working here\nRegular team-building events\nPlay counter-strike at breaktime\nInternational, dynamic, friendly working environment.\nLearn a lot of new stuff\nProvide snacks, sweets, fruits,.... for free :)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6 Đ. Nguyễn Siêu, Bến Nghé, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(312, 269, 2, 'Junior Front-End Developer(VueJS 3/NuxtJS 3)', 'Top 3 reasons to join us\n- Môi trường khởi nghiệp đầy thử thách\n- Sẽ là thành viên nòng cốt của công ty lớn Nhật Bản\n- Chế độ đãi ngộ hàng đầu\n\nJob description\n- Develop and maintain web applications using Nuxt.js 3.\n- Collaborate with designers to implement user interfaces.\n- Ensure the technical feasibility of UI/UX designs.\n- Optimize applications for maximum speed and scalability.\n- Participate in code reviews and contribute to team knowledge sharing.\n\nYour skills and experience\n- 1-2 years of experience in front-end development.\n- Proficiency in JavaScript, including ES6+ features.\n- Experience with Nuxt.js 3 and Vue.js 3.\n- Strong understanding of HTML5 and CSS3.\n- Knowledge of responsive design principles.\n- Familiarity with version control systems (e.g., Git).\n- Strong problem-solving skills.\n- Excellent communication and teamwork abilities.\n\nBonus Points:\n- Some level of Japanese language proficiency.\n- Familiarity with backend technologies such as Node.js, Express, or databases (e.g., MongoDB, MySQL).\n\nWhy you\'ll love working here\n- Chúng tôi cung cấp mức lương tốt, đãi ngộ, môi trường phát triển cho nhân viên. Chúng tôi đặc biệt coi trọng văn hóa công ty, vậy nên nếu nhận thấy môi trường này phù hợp với chính bạn thì hãy nhanh tay ứng tuyển.\n\nVăn hóa công ty\n- YARUTOKI wα YARU\n- Trong tiếng Nhật, cụm từ "Yarutoki wa Yaru" có nghĩa là làm việc một cách nghiêm túc khi đến lúc phải nghiêm túc, trong khi vẫn duy trì một không khí vui vẻ. Văn hóa của công ty chính là chúng ta vui vẻ khi làm việc nhưng đến lúc cần nghiêm túc thì chúng ta sẽ nghiêm túc và tạo ra những kết quả tuyệt vời.\n\n- Tập trung vào giao tiếp\n- Chúng tôi thường xuyên tổ chức họp 1-1 với cấp lãnh đạo. Chúng tôi coi trọng giao tiếp không chỉ với đồng nghiệp mà còn với ban quản lý. \n- Công ty là nơi mà chúng ta dành hầu hết thời gian, không chỉ để làm việc mà còn để tận hưởng cuộc sống. Do đó, để xây dựng những mối quan hệ tốt đẹp ở công ty cho một cuộc sống tốt đẹp, chúng tôi luôn coi trọng việc “lắng nghe” trong giao tiếp.\n\n- Kỉ luật và linh hoạt\n- Chúng tôi coi kỷ luật là sự chuyên nghiệp. Tuy nhiên, chúng tôi cũng rất coi trọng tính linh hoạt để ứng phó với những thay đổi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '7th Floor TTC Tower, 19 Duy Tan St., Dich Vong Hau Ward, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(313, 270, 2, 'Cloud DevOps Lead (English, AWS/Azure, Kubernetes)', 'As a Cloud DevOps Lead/Manager, you will be responsible for the following tasks:\n\n- Lead cloud migration and operations across 10 BUs, managing 5+ contractors and 30+ IT colleagues per BU.\n- Architect and implement secure, automated cloud infrastructure and operations.\n- Define and enforce cloud security policies, standards, and best practices.\n- Collaborate with Group Security and Infra teams to ensure compliance and resilience\n- Drive DevOps and infrastructure automation initiatives across all BUs.\n- Educate and support local IT teams on cloud-native technologies and cyber risk management.\n- Lead the Cloud BAU team to support ongoing operations and migrations.\n- Manage and develop container platforms and orchestration tools (e.g., Docker, Kubernetes).\n- Manage vendor relationships and cross-functional teams to deliver cloud-first strategies.\n- Communicating and discussing directly with cross-countries technical team and Manager in English\n\nYour skills and experience\n\n- 7+ years or more or relevant experience, and 2+ years in managing contractors and small team\n- Bachelor degree in computer science, Cyber Security, Information Security, Software Development, or a related field.\n- Experience with containers platforms (Docker EE or Openshift) and orchestration (Swarm, Kubernetes, Azure Kubernetes or AWS Elastic Kubernetes)\n- Solid knowledge in security technologies such as firewalls, intrusion detection/prevention, vulnerability scanning, WAF, CASB, cloud security gateways, etc.\n- Previous experience in cloud platform in security or infrastructure implementation and operations, also networking and infrastructure automation implementation or operation\n- Proficiency in programming languages such as Python, NodeJS, Java, etc\n- Proficiency in English, with excellent written and verbal communication skills, essential for daily meetings and direct interactions with cross-country Managers.\n\nWhy you\'ll love working here\n\n- Attractive salary and benefits\n- Extensive leave up to 21 days per year\n- Health insurance for employee + spouse & children\n- Professional and multi-culture working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Long Tower, 101-103 Nguyen Cuu Van, Binh Thanh Dist., HCMC, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(314, 271, 2, 'IT Business Analyst (Senior BA cum Project Manager)', 'JOB PURPOSE:\nBusiness Analyst (BA) is responsible for contributing to meeting user commitments according to plan. The Business Analyst is responsible for:\n- Assisting users in defining business requirements to meet their business goals\n- Preparing business specification documents\n- Conducting system tests & user acceptance tests\n- Carrying our day-to-day applications and operations support \n- Double hat as a Business Analyst (BA) and Project Manager (PM) in planning/managing resources to implement the software enhancements and/or special projects as assigned\n\nPRINCIPAL ACCOUNTABILITIES:\n- Utilizes knowledge of both the life insurance industry and current company life system functionality by writing business specifications and performs various validity testing.\n- Consults with users to define needs or problem areas and determine scope of investigation required to recommend possible solutions.\n- Develop test plans and test cases.\n- Executes test plans independently or in conjunction with the user.\n- Contributes to the resolution of common system problems.\n- Assists with user on-the-job training/team members on basic functional components.\n- Participates and contributes during studies and/or gap analysis to identify functional gaps between the user’s current processes and current company systems’ functionality.\n- Provide day-to-day applications and operations supervision.\n- Implement special projects as assigned\n\nYour skills and experience\n- A university degree in Business/Computing, or equivalent business experience\n- Experiences in life insurance/financial business/business analysis\n- At least 7-10 years of experience\n- Basic knowledge of data base: MSSQL or MySQL or DB2\n- Computer literate in office suite of products (word, spreadsheet, flowchart, presentation etc.)\n- Demonstrates basic knowledge of Data Architecture of system and basic SQL.\n- Understanding of applications interfaces between life system and other corporate systems\n\nSoft skills:\n- Customer service mindset\n- Good analytical skills and attentive to details\n- Analytical thinking and a fast learner\n- Able to work under pressure and meet tight deadlines\n- Excellent interpersonal and communication skills\n- Good command of spoken and written, reading English (required)\n- Good resource planning/management skills\n\nPersonal attributes\n- Good team player, independent and result-oriented\n- Flexible and open to changes\n\nWhy you\'ll love working here\n- Salary for 13th month, Bonus & Special Bonus\n- Full of social welfare under Vietnamese Labor Law (Insurance, annual leave, ...)\n- Healthcare for yourself & Your Family\n- Annual travel and team building activities\n- 16 annual leave days\n- Company will buy Life Insurance Contract for yourself after 1 year working\n- Training: Trained in soft and technical skills\n- International, challenging, and friendly working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '149-151 Nguyen Van Troi, Ward 11, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(315, 272, 2, 'Quality Control TeamLead (Tester, QA QC, Agile, Scrum)', 'Top 3 reasons to join us\n- Môi trường năng động và sáng tạo\n- Cơ hội phát triển sự nghiệp\n- Chế độ đãi ngộ canh tranh\n\nJob description\n1. Xây dựng chiến lược kiểm thử:\n- Thiết lập chiến lược kiểm thử phần mềm phù hợp với mục tiêu kinh doanh của tập đoàn.\n- Đề xuất và triển khai các công cụ, phương pháp kiểm thử tiên tiến.\n\n2. Quản lý quy trình kiểm thử và Kiểm soát chất lượng:\n- Xây dựng, triển khai và duy trì quy trình kiểm thử phần mềm (bao gồm kiểm thử chức năng, hiệu suất, bảo mật, tự động hóa).\n- Theo dõi và đảm bảo tiến độ kiểm thử theo kế hoạch.\n- Đảm bảo các sản phẩm phần mềm tuân thủ tiêu chuẩn chất lượng và các yêu cầu đặc thù của ngành bảo hiểm, tài chính, sức khỏe.\n- Phân tích và đánh giá rủi ro liên quan đến chất lượng phần mềm.\n\n3. Quản lý đội nhóm:\n- Tuyển dụng, đào tạo và phát triển đội ngũ kiểm thử phần mềm.\n- Quản lý và phân công công việc, đánh giá hiệu suất của đội ngũ.\n\n4. Phối hợp liên phòng ban:\n- Làm việc chặt chẽ với các phòng ban khác như phát triển phần mềm, sản phẩm, kinh doanh để đảm bảo hiểu rõ yêu cầu sản phẩm.\n- Tham gia vào quá trình phân tích yêu cầu và thiết kế giải pháp để đảm bảo tính khả thi và chất lượng.\n\n5. Báo cáo:\n- Lập báo cáo định kỳ về kết quả kiểm thử, các vấn đề phát sinh và đề xuất giải pháp cải thiện.\n\nYour skills and experience\n1. Trình độ học vấn/Chứng chỉ\n- Tốt nghiệp Đại học trở lên chuyên ngành Công nghệ thông tin, Khoa học máy tính, Hệ thống thông tin hoặc các ngành liên quan.\n\n2. Kinh nghiệm làm việc\n- Tối thiểu 5 năm kinh nghiệm trong lĩnh vực kiểm thử phần mềm, trong đó ít nhất 2 năm ở vị trí quản lý hoặc trưởng nhóm.\n- Có kinh nghiệm làm việc trong các dự án phần mềm liên quan đến bảo hiểm, tài chính, sức khỏe là một lợi thế.\n\n3. Kiến thức/Kỹ năng/Năng lực chuyên môn\n3.1. Kỹ năng chuyên môn\n- Am hiểu về các phương pháp kiểm thử phần mềm: manual, automation, performance testing, security testing.\n- Thành thạo các công cụ kiểm thử tự động như Selenium, JMeter, Appium, hoặc tương tự.\n- Hiểu biết về các quy trình phát triển phần mềm (Agile, Scrum, Waterfall).\n- Có kiến thức về bảo mật phần mềm và tiêu chuẩn chất lượng (ISO, CMMI, ISTQB).\n\n3.2. Năng lực lãnh đạo\n- Lãnh đạo đội nhóm thực hiện mục tiêu dài hạn. Phát triển năng lực cá nhân trong đội. Đánh giá và cải thiện hiệu suất làm việc của đội nhóm.\n- Thực hiện phân tích sâu các xu hướng thị trường, rủi ro, và cơ hội. Hỗ trợ lãnh đạo cấp cao trong việc ra quyết định chiến lược.\n- Xử lý các tình huống đa chiều, đưa ra quyết định dựa trên phân tích dữ liệu và nhận định từ nhiều góc độ. Đảm bảo quyết định tối ưu hóa lợi ích và giảm thiểu rủi ro cho tổ chức.\n\n3.3. Yêu cầu khác\n- Tư duy phân tích và giải quyết vấn đề tốt.\n- Kỹ năng giao tiếp và thuyết trình hiệu quả.\n- Khả năng làm việc dưới áp lực cao với nhiều dự án song song.\n- Kỹ năng tổ chức và lập kế hoạch.\n- Tiếng Anh giao tiếp tốt, đặc biệt trong môi trường làm việc quốc tế.\n\n4. Năng lực cốt lõi\n- Có tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty.\n\nWhy you\'ll love working here\n1. Cộng đồng những người làm nghề chính trực và dấn thân phụng sự\n- Môi trường làm nghề tài chính chuyên nghiệp.\n- Làm việc với tinh thần làm chủ, sáng tạo và thách thức.\n\n2. Tổng thu nhập theo năng lực\n- Thu nhập xứng đáng theo năng lực và giá trị đóng góp.\n- Xem xét thay đổi thu nhập hàng năm.\n\n3. Chế độ đãi ngộ\n- Tham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động.\n- Được tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24.\n\n4. Tổ chức học tập và văn hóa sôi nổi\n- Không gian làm việc mở với trang thiết bị hiện đại.\n- Các hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '43 Lê Văn Lương, Nhân Chính, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(316, 203, 2, 'Senior QC Engineer (QA QC, Tester, iOS, Android)', 'Top 3 reasons to join us\n- Disruptive innovations\n- People-oriented philosophy of doing business\n- Your footprint on regional on-demand market\n\nJob description\n- Work closely with multiple stakeholders such as the business team, product managers, and engineers to sync up product features and troubleshoot issues.\n- Work with project developers, business analysts, and customer support teams to ensure software solutions meet our user expectations.\n- Develop software test cases, based on consumer specifications and requirements.\n- Perform root cause analysis on defects found to identify and mitigate project risks.\n- Conduct exploratory and usability testing to locate bugs before the software is introduced into production.\n- Execute comprehensive testing against the software, ensuring all features function as designed and intended.\n- Contribute to the continuous improvement of software testing methodologies and develop standard operating procedures (SOPs), if necessary.\n- Perform functional and user scenario tests on iOS/Android mobile and Web platforms.\n- Communicate with the technical and reproduce issues for the debug plan.\n- Work closely with the project team to understand user requirements and review issues.\n- Coordinate testing activities with other members.\n- Ensure UAT is delivered with approved quality and timeline.\n\nYour skills and experience\n- 3+ years of experience with software testing.\n- Experience in developing test cases, test plans, and execution tests (functional testing, non-functional testing).\n- Knowledge of computer architecture and tools for manual & auto testing, unit testing, integration testing, functional testing, and bug-tracking systems.\n- Good communication skills, who can convert business feedback into technical requirements and vice versa.\n- Experience in web, and mobile applications.\n- Ability to multitask in a dynamic, fast-paced environment.\n- Having enthusiasm and passion at work, having a responsibility to ensure product quality.\n- Good at research, problem-solving, and troubleshooting ability.\n- Experience in APIs(Postman), database, and backend testing.\n- Experience in automation test and performance testing is a plus.\n- Having ISTQB certification is a plus.\n\nWhy you\'ll love working here\n- Annual health check-ups.\n- Sports club: Running, football, badminton.\n- Challenging working environment with attractive domain as Logistics.\n- Fair team.\n- Comfortable Private working Area for TECH team.\n- Teambuilding + Outing trip.\n- Join Training Courses and Tech Sharing.\n- Mid-Autumn Party, Christmas party, Year-end Party.\n- Monthly allowance for taxi.\n- Competitive salary, 13th-month pay & Performance Bonus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Rivera Park 7/28 Thành Thái, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(317, 273, 2, 'Senior Backend Developer (with Frontend and English)', 'Top 3 reasons to join us\n- Premium Healthcare package insurance\n- 13th month salary, Performance bonus\n- Language Certificate allowance (TOIEC & Japanese)\n\nJob description\n- Lead the design, development, and implementation of robust and scalable Web applications.\n- Drive DevOps initiatives, including CI/CD pipelines, infrastructure as code (IaC), and automated deployments.\n- Implement and maintain cloud-based solutions using AWS and/or Azure.\n- Develop and maintain frontend components using modern JavaScript frameworks.\n- Collaborate with cross-functional teams to define and implement project requirements.\n- Provide technical leadership and mentorship to junior developers.\n- Conduct code reviews and ensure adherence to coding standards and best practices.\n- Troubleshoot and resolve complex technical issues.\n- Stay up-to-date with the latest Backend technologies, DevOps practices, and cloud computing trends\n\nYour skills and experience\n- Bachelor\'s or Associate\'s degree in Information Technology or a related field.\n- Extensive experience (3+ years) in Backend development (Java, PHP, Python or .Net)\n- Experience in DevOps practices, including CI/CD and IaC is a plus\n- Experience with cloud platforms (AWS and/or Azure) is a plus\n- Experience with modern JavaScript frameworks for frontend development (e.g., React, Angular, Vue.js).\n- Strong understanding of software development principles and best practices.\n- Excellent problem-solving and analytical skills.\n- Strong communication and interpersonal skills.\n- Proficiency in English (written and, at least TOEIC 700).\n\nPreferred Qualifications:\n- AWS and/or Azure certifications.\n- Experience with containerization and orchestration technologies (Docker, Kubernetes).\n- Experience with database administration and optimization.\n- Japanese language proficiency (JLPT certification).\n\nWhy you\'ll love working here\n- Competitive salary and benefits including Premium Healthcare package insurance\n- 13th month salary, Performance bonus\n- 16 days annual leave\n- Comprehensive Training Courses (Languages, Technical and Soft-skill)\n- Language Certificate allowance (TOIEC and Japanese)\n- Birthday and Lunar New Year gifts\n- Lunch and bus/ parking allowance\n- Fun team activities and outings\n- Sponsored happy hour and sport clubs\n- Comfortable work space and friendly colleagues', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Etown 2, 364 Cong Hoa, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(318, 274, 2, 'Project Manager/Scrum Master', 'Key Contributions\nWe are seeking an experienced Project Manager to oversee software development initiatives and ensure the successful delivery of projects. In this role, you will collaborate closely with development teams and cross-functional stakeholders to manage projects throughout their entire lifecycle.\nLead and deliver software projects using Agile/Scrum and other relevant project management methodologies\nCollaborate with internal teams and clients to establish clear objectives, timelines, and deliverables\nMonitor project progress, quality standards, and potential risks to ensure timely and cost-effective delivery\nManage scope changes, resource allocation, and project priorities\nContribute to project estimation and planning during the pre-sales phase as needed\nFoster effective communication and collaboration across cross-functional teams and stakeholders\nDrive team performance and support the personal development of team members\n\nYour skills and experience\nKey Ingredients for Success\nBachelor’s Degree in Computer Science / Information Technology / Software Development or related fields\nMust have:\nA solid background in IT, with 4+ consecutive years of experience in Project Management/Scrum Master\nProven experience in managing resources and leading cross-functional teams\nProficiency in using project management tools (e.g., Jira, Asana, MS Project, Trello)\nStrong leadership, communication, and stakeholder management skills\nFluent English communication is mandatory, with good presentation and reporting skills\n\nNice to have:\nPrior experience in E-commerce, CRM systems, or the Payment domain is an advantage\n\nWhy you\'ll love working here\nWe are a multinational, product-driven company specializing in proprietary POS solutions — developing in-house and delivering directly to our worldwide customers.\n\nBenefits\nRecognition & Rewards:\n13th-month salary\nLoyalty Bonus programs\nBiannual Performance and Salary review\nComprehensive Insurance Coverage:\nFull government public insurance contributions based on gross salary\nPremium health insurance\nAnnual health check\nClear career development and growth structure; Training sessions and Learning workshops\n14 days of annual leave and one additional day of leave for every year of service\nLaptop/MacBook and top-notch facilities are provided based on each role\nAgile/Scrum-based internal workflows for efficient and collaborative development\nCompany trips, parties and regular team-building activities; Weekly happy hour, coffee, snacks, and board games\nOverseas travel opportunities based on the individual performance and policies for each evaluation period\n\nWorking Environment & Culture\nInternational Workplace: English-speaking environment\nPositive and Open-Minded Culture: Engineers are encouraged to propose innovative solutions that enhance productivity and code quality\n1-on-1 Mentorship: Monthly coffee sessions with managers offer personalized feedback, goal setting, and career development opportunities\nFlexible Working Hours: Promote work-life balance and individual productivity', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '42/37-38 Hoàng Diệu, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(319, 275, 2, 'Senior Fullstack Developer (.NET + React)', 'Development is the largest discipline at Endava. Our developers design, build, and release software products in multiple programming languages, frameworks, and libraries. Always collaborating with cross-functional project teams, our developers are adaptable problem-solvers with a client-oriented mindset.  As a Full-stack Developer at Endava, you are responsible for implementing and delivering high-quality software products using Agile Scrum methodology. As a part of a global project, you can contribute your technical expertise and experience in order to the project succeed.\n\nResponsibilities:\n- Collaborate with passionate team members and contribute to continuous improvement and high-quality deliverables. \n- Work closely with clients and global teams in an agile environment to understand product goals and key features. \n- Support both development and validation to ensure the product delivers real value and functions as expected. \n- Implement requirements using modern front-end technologies and stay up to date with industry trends. \n- Tackle complex technical challenges and actively contribute to Scrum ceremonies and team success. \n- Participate in code reviews and continuously learn new tools, technologies, and best practices.\n\nYour skills and experience\nMandatory skills\n- 5+ years of experience in fullstack development with strong React, .Net C#, and Entity Framework.\n- Experience with Unit/integration testing.\n- Follow design patterns (SOLID, DI, Atomic) and quality standards.\n- Strong communication and problem-solving skills.\n- Learns and retains domain knowledge to drive project success.\n- Upper-intermediate English proficiency.\n\nDesired skills\n- Familiar with Redux, TanStack Query, Styled Components.\n- Knowledge of .NET Core Minimal APIs, Microsoft SQL Server.\n- Familiarity with Python is a plus.\n- Agile processes knowledge and experience.\n- Able to coach and support teammates.\n\nWhy you\'ll love working here\nAt Endava, we are offering opportunities and exciting development for our people to build an engaging technical community.\n\n- Career coaching, learning and development: Certifications, soft skills, training licenses. Endava Digital Library and tech conferences.\n- Culture and work environment: Company-sponsored team-based sports, hobby clubs, tech & social communities.\nSome of our benefits\n- Finance: Competitive salary package, annual leave encashment, 13th month salary, referral bonus; \n- Career Development: Career coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership;\n- Learning Opportunities: Complex projects, rotations, internal tech communities, training, coaching, online learning platforms subscriptions, English programme, certifications, pass-it-on sessions, workshops, conferences;\n- Work-Life Balance: Hybrid work and flexible working hours, employee assistance programme;\n- Health: Global internal wellbeing programme, access to wellbeing apps, premium health check, extra insurance;\n- Community: Global internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations;\n- Other: Trade Union benefits, Welcome package and gift-giving frequency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '9-11 Dong Da street, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(320, 276, 2, 'Software Engineer (C#, VB.NET, F# )', 'Top 3 reasons to join us\n- 20 annual leaves per year\n- Checkpoint: Twice per year, Year End Bonus \n- Professional training and soft skills development\n\nJob description\n- Work as part of a Software Development Team under Agile Scrum model.\n- Understand user requirements and provide technical solutions.\n- Contribute to improve Team and Organization’s process and infrastructure.\n- Create the reusable, testable, and efficient codes.\n- Design and implement performant applications with low latency and high availability.\n- Integrate the data storage solutions and create database schemas that represent and support business processes.\n- Implement the security and data protection.\n- Troubleshoot, test and maintain the core product software and databases to ensure strong optimization and functionality.\n\nYour skills and experience\n- +5 years Experience in .NET (C#, ).\n- +1 year Experience in .NET (F#).\n- Experience in , MVC, , Entity framework.\n- Knowledge about HTML, CSS, Javascript, jQuery.\n- Experience with the following tech stack is required: NoSQL (Azure CosmosDB), Azure Search, Azure Storage, Azure Functions, Azure Event Hub, Azure Application Insights, Snowflake, and Excel (SpreadsheetGear).\n- Write high quality and testable code following clean code and SOLID design principles.\n- Experience in Unit and API testing.\n- Experience in Azure, AWS.\n- Strong experience in relational database design.\n- Relational database (mySQL, SQL server), nonRelational database (NoSQL, MongoDB, CosmosDB)\n- Good knowledge about Design patterns\n- Good knowledge in Restful API development.\n- Experience in requirement analysis, system design, Web Application Development architect.\n- Proficient understanding of code versioning tools (Git) and git flow process.\n- Experience in tuning performance, making things faster.\n- Basic English.\n- Experience in project leader of about 3 members, sharing knowledge.\n\nNICE TO HAVE:\n- Experience with other frameworks is a plus (.NET core, JS framework).\n- Have knowledge in Microservice, K8S, Data Warehouse.\n- Good knowledge working with system or working CI/CD tools such as Jenkins, Docker.\n- Experience working with common third-party APIs (LINE, Stripe ... ) is a plus.\n- Experience with some service of aws, gcp, azure,…\n- Having an Cloud Service, AWS certificate is a plus.\n\nWhy you\'ll love working here\n- Competitive Salary – Deserved Rewards\n- Attractive salary, aligned with your skills and contributions.\n- Salary review twice a year to recognize your dedication.\n- Generous year-end bonus, based on individual performance.\n- Comprehensive Healthcare – We Care About You\n- Premium health insurance package for extra protection.\n- Annual health check-ups at top-tier hospitals.\n- Ergonomic chairs to protect your health.\n- Access to mindfulness courses for your mental well-being.\n- Modern & Innovative Work Environment\n- Equipped with MacBook/Laptop & the latest technology to enhance productivity.\n- Dedicated office floors with 6 levels for various projects.\n- Personal Development – Unlimited Growth Opportunities\n- Sponsored international certification exams, supporting professional advancement.\n- Specialized training courses & soft skills development to enhance expertise.\n- Flat organizational structure, enabling direct collaboration with leaders and fostering creativity and innovation.\n- Transparent and well-defined career advancement opportunities.\n- Agile Mindset – People-Centric Growth\n- Open, flexible, and supportive work culture, driving collective success.\n- Stronger team connections, creating a dynamic and efficient workplace.\n- Work Hard – Play Hard\n- Exciting activities: Open Talks, IT Seminars, Team Building, Project Trips, Sports Day, Year-End Parties…\n- Diverse entertainment: PlayStation, Friday Happy Hours, Mindfulness-related activities…\n- Flexible Working Hours\n- Monday - Friday: 8:00 AM - 11:30 AM | 1:00 PM - 5:30 PM.\n- Join TechTus, where we work HAPPILY to achieve our DREAMS together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 8, tòa nhà HMC Tower, 193 Đinh Tiên Hoàng, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(321, 277, 2, 'Back-end Developer (Java Springboot)', 'Tham gia phát triển hệ thống dựa trên dựa trên yêu cẩu của bộ phận quản lý sản phẩm.\nSẽ nghiên cứu những nền tảng công nghệ mới bắt kịp xu thế công nghệ hiện tại nếu yêu cầu về mặt sản phẩm cần.\nĐóng góp/đề xuất những ý tưởng hay/sáng tạo cả về mặt sản phẩm/công nghệ (nếu có)\nCác tiếu chí trên là đơn vị đo lường cụ thể đóng góp của công việc/chức danh này.\nChịu trách nhiệm đảm bảo việc thành công trong hoạt động, công việc cụ thể với các chức năng, trách nhiệm mà cấp Quản lý trực tiếp giao phó/kỳ vọng.\nHướng dẫn đồng nghiệp trong đơn vị và ngoài đơn vị về cách thức sử dụng phương pháp Agile để thực thi công việc.\nĐịnh kỳ báo cáo và cập nhật tình hình các công việc được giao\nNghiên cứu, đánh giá công nghệ mới. Đóng góp ý tưởng, giải pháp không chỉ về mặt công nghệ còn khuyến khích về mặt sản phẩm.\n\nYour skills and experience\nTốt nghiệp Đại học trở lên hoặc có bằng cấp tương đương của các đơn vị đào tạo công nghệ thông tin có tiếng.\nTối thiểu 1 năm kinh nghiệm lập trình vị trí Java\nSử dụng thành thạo một trong các hệ quản trị cơ sở dữ liệu Mysql, Oracle, Sql server\nThành thạo, hiểu biết sâu rộng Java Core.\nCó kinh nghiệm sử dụng framework Springboot\nHiểu biết về webservice SOAP/Restful, chuẩn message JSON, OOP, XML, Design partern, web server..\nCó kiến thức cơ bản về hệ thống, Network, OS (Window, Linux ..)\nSử dụng thành thạo các IDE phát triển.\nSử dụng thành thạo các tool quản lý source code, quản lý công việc.\nHiểu biết về cache (redis, memcache,..), MessageQueue (Rabbit, ActiveMQ..) là một lợi thế\nTiếng anh đọc hiểu tài liệu tiếng anh chuyên ngành tốt, giao tiếp tốt là một lợi thế.\nKiến thức triển khai dự án với các phương pháp khác nhau như agile, water-fall, Kanban\n\nKỹ năng:\nLàm việc độc lập/theo nhóm. Có kĩ năng giao tiếp làm việc trong nhóm, các bộ phận liên quan.\nLập kế hoạch, thực thi, quản lý công việc được giao\nCó khả năng tổng hợp phân tích đánh giá vấn đề/yêu cầu.\nChịu được áp lực công việc.\nTính chủ động và thái độ tiếp nhận công việc qua tinh thần “can-do”!\n\nWhy you\'ll love working here\nThu nhập hấp dẫn, lương thưởng theo performance\nThưởng các ngày Lễ /Tết (theo chính sách công ty từng thời kì)\nChế độ ngày phép hấp dẫn theo từng cấp bậc\nBảo hiểm bắt buộc theo quy định, BH sức khỏe cao cấp cho CBNV\nĐược tham gia các khóa đào tạo tùy thuộc vào khung đào tạo cho từng vị trí.\nThời gian làm việc: từ thứ 2 – thứ 6 \nMôi trường làm việc năng động, thân thiện, có nhiều cơ hội học đào tạo, học hỏi và phát triển; được tham gia nhiều hoạt động văn hóa thú vị (cuộc thi về thể thao, tài năng, hoạt động team building,…)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 25, Toà nhà Văn phòng Thương mại, số 89 Láng Hạ, Phường Láng Hạ, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(322, 238, 2, '[Middle, Senior] Java Backend Developer (Spring)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Phát triển, trực tiếp lập trình các hệ thống, ứng dụng của Ngân hàng, gồm các hệ thống nội bộ và ứng dụng dành cho khách hàng với quy mô 30 triệu khách hàng cá nhân và 300.000 khách hàng doanh nghiệp.\n- Phát triển hoặc phối hợp triển khai cùng các nhà cung cấp cho các giải pháp Công nghệ.\n- Quản lý, phát triển dịch vụ tích hợp với các hệ thống core như: T24, WAY4, BPM, CRM, CIC ...\n- Quản lý, phát triển API trên API Gateway phục vụ tích hợp với các đối tác trong nước và quốc tế.\n- Nghiên cứu, thử nghiệm, triển khai áp dụng các xu hướng công nghệ mới vào việc phát triển: GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL ...\n- Tham gia phân tích nghiệp vụ, đề xuất giải pháp, phương án triển khai nhằm cải tiến, nâng cao hiệu quả của các dự án trong quá trình làm việc.\n- Lên timeline công việc, quản lý tasks cho các thành viên trong nhóm, giám sát và hỗ trợ các thành viên hoàn thành đúng cam kết.\n- Dẫn dắt nhóm 3-6 thành viên, đồng hành cùng các thành viên phát triển chuyên môn và hoàn thành công việc\n\nYour skills and experience\n- Tốt nghiệp Đại học các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin ...\n- Tối thiểu 02 năm làm việc thực tế tại các công ty, dự án về lập trình Backend\n- Tối thiểu 1 - 2 năm kinh nghiệm làm việc với Microservice.\n- Thành thạo ngôn ngữ Java.\n- Thành thạo Spring framework: spring core, spring security, spring boots.\n- Thành thạo một trong trong các loại database: Oracle, Sqlserver, PostgreSQL, Mongodb.\n- Có kiến thức tốt về kiến trúc hệ thống. Thông thạo đa dạng thiết kế phần mềm.\n- Có khả năng tuning performance của ứng dụng, hệ thống.\n- Có hiểu biết sâu về các kỹ thuật/công nghệ: MySQL, Redis, MongoDB, PostgreSQL, Kafka,…\n- Có kinh nghiệm phát triển, sử dụng Cloud, AI, Front-end là 1 lợi thế.\n- Có kinh nghiệm hướng dẫn, quản lý đội nhóm là lợi thế\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n  - Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n  - Du lịch nghỉ dưỡng hàng năm\n  - Khám sức khỏe định kì\n  - Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n  - Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n- Cơ hội nghề nghiệp và phát triển bản thân:\n  - Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n  - Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n  - Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n  - Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n- Môi trường làm việc lý tưởng với:\n  - Những người cộng sự thân thiện và tài năng\n  - Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(323, 278, 2, 'AI Engineer', 'Job description\n\n1.1. Nghiên cứu và đề xuất công cụ AI: \n- Tìm hiểu và đánh giá các công cụ AI tiềm năng, phù hợp với từng phòng ban trong công ty. \n- Đề xuất các công cụ AI tốt nhất dựa trên hiệu quả, chi phí, và tính ứng dụng. \n\n1.2. Thử nghiệm và đóng gói giải pháp AI: \n- Thiết kế quy trình thử nghiệm các công cụ AI trên các quy trình cụ thể của từng phòng ban. \n- Phối hợp với các team liên quan để thử nghiệm, thu thập phản hồi và điều chỉnh các giải pháp AI trước khi đóng gói. \n\n1.3. Theo dõi và đảm bảo tiến độ ứng dụng AI: \n- Phối hợp với các leader của các phòng ban để theo dõi và đôn đốc tiến độ triển khai AI theo kế hoạch. \n- Cập nhật tình hình hàng tuần, đánh giá kết quả và đưa ra đề xuất cải thiện khi cần thiết. \n\n1.4. Đóng gói và triển khai sản phẩm AI cho khách hàng:\n- Hoàn thiện quy trình ứng dụng AI nội bộ trước khi đóng gói sản phẩm. \n- Phối hợp với đội ngũ kinh doanh giới thiệu và triển khai sản phẩm AI cho khách hàng bên ngoài. \n- Hỗ trợ khách hàng cài đặt, sử dụng sản phẩm AI, thu thập phản hồi để cải tiến sản phẩm. \n\n1.5. Báo cáo và đánh giá: \n- Lập báo cáo tiến độ nghiên cứu, thử nghiệm và ứng dụng AI hàng tuần. \n- Đánh giá hiệu quả triển khai và lên kế hoạch tiếp theo để đẩy mạnh bán sản phẩm ra thị trường.\n\nThời gian làm việc từ 8h30-17h30 từ thứ 2 - thứ 6 (và làm 2 thứ 7 cách tuần).\n\nYour skills and experience\n\n- Tốt nghiệp đại học ngành Công nghệ thông tin, Khoa học máy tính, hoặc các ngành liên quan. \n- Có kinh nghiệm làm việc với các công cụ và giải pháp AI.\n- Kỹ năng nghiên cứu và phân tích tốt, khả năng đề xuất giải pháp công nghệ sáng tạo. \n- Kỹ năng giao tiếp tốt, có khả năng làm việc nhóm và phối hợp với nhiều phòng ban. \n- Kỹ năng lập kế hoạch & bám đuổi mục tiêu. \n- Kỹ năng xây dựng và duy trì mối quan hệ với đối tác cao cấp. \n- Kỹ năng làm việc với con người, phối hợp các phòng ban. \n- Ưu tiên có kinh nghiệm làm việc trong các dự án triển khai AI là một lợi thế.\n\nWhy you\'ll love working here\n\n3.1. Lương - thưởng  \n- Mức lương: 15 - 25 triệu tùy năng lực.\n- Được đánh giá tăng lương hằng tháng theo PP tích điểm.\n- Các khoản thưởng KQKD hàng tháng.\n- Nhận thưởng nóng cá nhân, đội nhóm xuất sắc ngay theo từng tuần, từng tháng, từng sản phẩm.\n- Thưởng ý tưởng, thưởng cải tiến sáng tạo.\n- Thưởng tháng lương 13.\n- Thưởng Tết âm lịch.\n- Đảm bảo tín nhiệm đồng hành; tham gia vào Ban Lãnh Đạo công ty có Cổ phần xây dựng và đóng góp hằng năm.\n\n3.2. Phúc lợi\n- Phụ cấp & Trợ cấp: Ăn trưa ~ 840,000 VNĐ/tháng; PC gửi xe.\n- PC nhiệm 500,000 – 5,000,000 VNĐ/tháng.\n- Phụ cấp trang phục 4,000,000VND/năm.\n- Các khoản phúc lợi khác: Thưởng các ngày lễ Tết theo Quy định của nhà nước, Sinh nhật, các chế độ ốm đau hiếu hỷ đầy đủ; Người lao động sinh con; Người lao động kết hôn; Thưởng thêm các ngày sinh nhật Công ty, Tết thiếu nhi, Trung thu, Noel;  \n- Ngày phép giữ nguyên lương: 12 ngày/năm.\n- Các hoạt động Teamwork, Teambuilding, Du lịch định kỳ.\n- Hỗ trợ chi phí tập Gym hàng tháng, khám sức khỏe định kỳ hàng năm.\n\n3.3. Đào tạo phát triển & Lộ trình thăng tiến\n- Đào tạo nội bộ: kỹ năng mềm, kỹ năng chuyên môn hàng tuần; văn hoá đọc 15P hàng ngày;  \n- Teamwork 2h mỗi tuần trong hoặc ngoài văn phòng.\n- Được cử đi đào tạo nâng cao chuyên môn nghiệp vụ, kỹ năng mềm.\n- Hỗ trợ 50% - 100% chi phí tự học (chứng chỉ, kỹ năng bổ trợ,...).\n- Cơ hội thăng tiến, phát triển nghề nghiệp lâu dài.\n- Lộ trình thăng tiến: Không hạn chế tuổi tác, bạn có thể ở vị trí cao ngay khi còn rất trẻ.\n\nTheo hướng chuyên gia: Nhân viên -> Chuyên viên -> Chuyên viên cao cấp -> Chuyên gia -> Chuyên gia cao cấp.\n\nTheo hướng Quản lý: Nhân viên -> Chuyên viên -> Trưởng dự án/Trưởng nhóm -> Trưởng bộ phận -> Giám đốc Business Unit.\n\n3.4. Môi trường làm việc - Văn hóa Công ty \n- Lấy nhân sự làm trung tâm/ cốt lõi.\n- Làm việc trách nhiệm cao, coi mình là nguyên nhân của mọi vấn đề.\n- Chủ động và sáng tạo khi làm việc. \n- Học tập và cải tiến công việc mỗi ngày.\n- Mục tiêu rõ ràng gắn mục tiêu cá nhân vào mục tiêu tổ chức.\n- Chính trực, thân thiện, cởi mở.\n- Hợp tác cao cùng hành động hướng tới Kết quả chung.\n- Bạn là chuyên gia trong lĩnh vực của bạn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2 tòa GTC, số 3 đường Galaxy 6, Vạn Phúc, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(324, 245, 2, 'Front End Developer ( Javascript, ReactJS, VueJS )', 'LG CNS Việt Nam đang tìm kiếm các lập trình viên Front-end đủ tiêu chuẩn tham gia vào các dự án của công ty. Bạn sẽ phát triển trong việc phát triển ứng dụng web trong các lĩnh vực khác nhau, chẳng hạn như các dự án về Data, Machine learning / Data Learning, AI, và các solution hiện có của công ty\nNhiệm vụ:\n- Đảm bảo hiệu suất, chất lượng và khả năng đáp ứng tốt nhất có thể của các ứng dụng ở phía Front-end\n- Tham gia lập trình các ứng dụng web \n- Phối hợp cùng team dự án Việt Nam và Hàn Quốc để đảm bảo tiến độ\n- Trao đổi chi tiết khi phỏng vấn\n\nYour skills and experience\n- Có ít nhất 3 năm kinh nghiệm \n- Có kinh nghiệm phát triển ứng dụng web/mobile\n- Có thể phát triển HTML, CSS, Javascript, jQuery\n- Có kinh nghiệm Figma\n- Có thể phát triển dựa trên SPA (Vue.js, Vuex)\n- Có kinh nghiệm với các công cụ cộng tác như Git, Jira và Confluence\n- Hiểu và sử dụng CI/CD\n- Giao tiếp Tiếng anh ở mức trung bình (TOEIC trên 550 và các chứng chỉ tương tự hoặc tự tin giao tiếp tiếng anh)\n\nƯu tiên\n- Hiểu về Back-end\n- Sử dụng được Typescript\n- Có kinh nghiệm UI/UX\n- Có kinh nghiệm với biểu đồ javascript (Echarts, Chart.js, d3js, v.v.)\n- Kinh nghiệm sử dụng Tailwind, MUI\n- Kinh nghiệm phát triển OAuth\n- Giao tiếp tiếng Hàn\n\nWhy you\'ll love working here\n- Lương, thưởng sẽ được thảo luận sau khi thông qua CV & Phỏng vấn\n- Review đánh giá năng lực hàng năm và điều chỉnh tăng lương theo hiệu quả công việc\n- Phụ cấp chứng chỉ ngoại ngữ tiếng hàn (TOPIK)\n- Chăm sóc sức khỏe: Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp\n- Điều kiện làm việc thoải mái và thời gian làm việc linh hoạt\n- Cơ hội phát triển nghề nghiệp tốt với các dự án thú vị và đầy thử thách;\n- Các khóa đào tạo tiếng Anh, tiếng Hàn, kỹ thuật, kỹ năng mềm;\n- Cơ hội học các khóa học đặc biệt của LG CNS, công nghệ mới và bảo mật\n- Quà tặng, thưởng vào các dịp lễ, tết (30/4-1/5, 2/9, tết v.v)\n- Các hoạt động ngoài trời với sự hỗ trợ của công ty: câu lạc bộ thể thao, team building, tiệc happy hour, sinh nhật, du lịch, sự kiện nhân viên và gia đình, v.v.\n- Thời gian làm việc: 8 tiếng từ T2 - T6 (8:00- 12:/ 13:00 - 17:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(325, 279, 2, 'Odoo Developer (Python, JavaScript)', 'Chúng tôi đang tìm kiếm một Odoo Developer tài năng vằn nhiệt huyết để dẫn dắt việc triển khai hệ thống Odoo ERP cho doanh nghiệp vận hành công viên giải trí là khu Đô thị Du lịch hàng đầu Đông Nam Á. Với hệ thống chuỗi cung ứng du lịch, dịch vụ, nghĩ dưỡng, giáo dục, khoa học công nghệ và đô thị thông minh hàng đầu, rộng gần 400ha, vốn đầu tư lên đến 3,5 tỷ đô. Bạn sẽ là nhân tố cốt lõi trong việc thiết lập, tùy chỉnh, và tối ưu hóa các module Odoo (ERP, CRM, HRM, POS, v.v.) để đáp ứng nhu cầu quản lý phức tạp của công viên, từ bán vé, quản lý khách hàng, đến chuỗi cung ứng và nhân sự. Đây là cơ hội để bạn đặt nền móng cho một hệ thống ERP hiện đại, góp phần nâng cao trải nghiệm khách hàng và hiệu quả vận hành.\n\nTrách nhiệm chính:\n- Phân tích yêu cầu nghiệp vụ từ các phòng ban (bán vé, dịch vụ khách hàng, nhân sự, kho, tài chính) và chuyển đổi thành các giải pháp kỹ thuật trên Odoo.\n- Cấu hình và tùy chỉnh các module Odoo (ví dụ: CRM, Bán hàng, HRM, POS) để phù hợp với quy trình kinh doanh của công viên giải trí.\n- Phát triển các tính năng mới hoặc module tùy chỉnh bằng Python, XML, và JavaScript.\n- Quản lý và tối ưu hóa cơ sở dữ liệu PostgreSQL để đảm bảo hiệu suất hệ thống.\n- Tích hợp Odoo với các hệ thống bên ngoài (ví dụ: hệ thống bán vé, ứng dụng di động, hoặc thiết bị IoT trong công viên).\n- Hỗ trợ triển khai Odoo trên hạ tầng on-premise học cloud (Odoo.sh, AWS, v.v.).\n- Kiểm tra, sửa lỗi, và đảm bảo hệ thống hoạt động ổn định trước khi đưa vào vận hành.\n- Tài liệu hóa mã nguồn, quy trình, và hướng dẫn sử dụng cho đội ngũ nội bộ.\n- Hỗ trợ đào tạo Key Users và End Users về cách sử dụng hệ thống Odoo.\n- Cộng tác với CTO để lập kế hoạch triển khai từng giai đoạn và mở rộng đội ngũ IT.\n\nYour skills and experience:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính, hoặc lĩnh vực liên quan.\n- Có ít nhất 2-3 năm kinh nghiệm phát triển hoặc triển khai Odoo (phiên bản Community hoặc Enterprise).\n- Thành thạo Python, XML, và JavaScript để phát triển và tùy chỉnh module Odoo.\n- Hiểu biết sâu về cơ sở dữ liệu PostgreSQL và khả năng tối ưu hóa hiệu suất.\n- Kinh nghiệm cấu hình và quản trị hệ thống trên Linux (Ubuntu khuyến khích) học môi trường đám mây (AWS, Google Cloud, Odoo.sh).\n- Hiểu biết về các quy trình kinh doanh trong ERP (ví dụ: CRM, HRM, quản lý kho, kế toán).\n- Kỹ năng phân tích nghiệp vụ và làm việc với các phòng ban không thuộc IT.\n- Kỹ năng giao tiếp tốt, có khả năng làm việc độc lập và theo nhóm.\n- Tiếng Anh khá (đọc hiểu tài liệu kỹ thuật và giao tiếp cơ bản với cộng đồng Odoo toàn cầu).\n\nƯu tiên:\n- Kinh nghiệm triển khai Odoo cho các doanh nghiệp trong ngành dịch vụ, giải trí, học bán lẻ.\n- Đã từng tích hợp Odoo với các hệ thống bên thứ ba (API, ứng dụng di động, học thiết bị IoT).\n- Có chứng chỉ Odoo học tham gia các khóa học chính thức từ Odoo.\n- Hiểu biết về quy trình vận hành công viên giải trí (bán vé, quản lý xếp hàng, trải nghiệm khách hàng).\n\nWhy you\'ll love working here:\n- Làm việc trong một dự án đầy thách thức, xây dựng hệ thống ERP cho công viên giải trí hàng đầu.\n- Cơ hội học hỏi và phát triển cùng các công nghệ hiện đại.\n- Môi trường làm việc năng động, sáng tạo, và hỗ trợ phát triển nghề nghiệp.\n- Xe ca đưa rước ở Hồ Kỳ Hòa học hỗ trợ nhà ở cộng đồng nếu ở lại công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '120 Xa lộ Hà Nội, Phường Tân Phú, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(326, 280, 2, 'Triển khai phần mềm (Linux/ SQL/ Database)', 'Job description\n- Tham gia khảo sát nghiệp vụ, quy trình thực tế tại khách hàng.\n- Tư vấn giải pháp với các yêu cầu của khách hàng.\n- Xây dựng và trình bày các tài liệu dự án/phần mềm.\n- Xây dựng kịch bản, chuẩn bị và demo phần mềm với khách hàng\n- Phối hợp các bộ phận liên quan, truyền tải thông tin đặc thù khách hàng đến bộ phận kỹ thuật khi có phát sinh yêu cầu.\n- Cài đặt, đào tạo và hỗ trợ khách hàng sử dụng phần mềm và thiết bị y tế cá nhân\n- Kiểm tra phần mềm, đảm bảo chất lượng hệ thống khi triển khai.\n- Khảo sát đánh giá và nhận phản hồi từ khách hàng\n- Các công việc khác theo phân công của cấp quản lý (nếu có).\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành Hệ thống thông tin.\n- Giới tính: Nam\n- Có kinh nghiệm cài đặt và xử lý vấn đề với hạ tầng mạng, internet, PC\n- Có kinh nghiệm cài đặt Linux, Ubuntu, VM, Docker\n- Có kinh nghiệm làm việc với SQL , Database PostgreSQL\n- Có tư duy hệ thống và phân tích thiết kế\n- Có kinh nghiệm triển khai và tư vấn giải pháp hệ thống phần mềm từ 03 năm trở lên (có kinh nghiệm triển khai phần mềm y tế là điểm cộng).\n- Có khả năng tự đưa ra giải pháp và kết nối công việc với các bộ phận liên quan.\n- Có kỹ năng trình bày và viết tài liệu dự án/phần mềm một cách chuyên nghiệp\n- Có kỹ năng giải quyết vấn đề\n- Có kỹ năng tổ chức sắp xếp và quản lý thời gian hiệu quả\n- Giao tiếp hiệu quả với khách hàng, đồng nghiệp.\nWhy you\'ll love working here\n- Thu nhập: 20tr / tháng gross.\n- Lộ trình tăng lương hàng năm rõ ràng theo chính sách công ty\n- Thưởng Tháng 13, Thưởng tết, Phụ cấp công tác, Phụ cấp điện thoại, Phụ cấp cơm trưa, Phụ cấp xăng….\n- Được hưởng các chế độ BHXH, Bảo hiểm sức khỏe, thưởng lễ, Tết theo quy định.\n- Được hưởng các chế độ phúc lợi của công ty như: sinh nhật, ốm đau, thai sản, hiếu, hỉ, du lịch hàng năm...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '618 Đường 3 tháng 2, phường 14, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(327, 281, 2, 'Fullstack Developer', 'Job description\n- Join a professional training program focused on Node.js, React, and Ruby on Rails (RoR)\n- Collaborate with the team to develop new features and maintain our web and app products\n- Participate in both frontend and backend development for improved user experiences\n\nYour skills and experience\n- Currently majoring in IT/Computer Science (recent graduates also welcome)\n- Familiarity with both frontend and backend development (React, Node.js, or Ruby on Rails is a plus)\n- Basic understanding of SQL and relational databases (Postgres is a plus)\n- Knowledge of version control systems (Git, GitHub)\n- Eagerness to learn new technologies and programming languages\n- Solid foundation in object-oriented programming is a plus\n\nWhy you\'ll love working here\n- Opportunity to learn and work with the newest technologies in real projects\n- Supportive and dynamic team environment\n- 13th-month salary bonus\n- Full social, health, and insurance benefits', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'S4, The Sun Avenue, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(328, 282, 2, 'Mobile Developer (Flutter)', 'Top 3 reasons to join us\n• Lĩnh vực trung gian thanh toán nhiều tiềm năng\n• Lương cạnh tranh + thưởng quý theo KQ công việc\n• Đãi ngộ hấp dẫn: ăn trưa, bảo hiểm theo lương\n\nJob description\n• Thiết kế kiến trúc và lập trình phát triển module/sản phẩm mới hoạt động ổn định\n• Tham gia phát triển, đề xuất giải pháp kỹ thuật các dự án lập trình ứng dụng App trên nền tảng mobile\n• Nghiên cứu và ứng dụng các công nghệ mới và ứng dụng vào quá trình phát triển sản phẩm, viết tài liệu mô tả\n• Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của cấp trên\n• Góp phần xây dựng công ty, tham gia định hướng chiến lược và phát triển sản phẩm\n• Đánh giá các chức năng khi nhận được yêu cầu từ các nhóm\n• Báo cáo kết quả làm việc với Ban lãnh đạo và Quản lý trực tiếp.\n\nYour skills and experience\n• Có từ 2 năm kinh nghiệm Flutter (Ưu tiên biết Native Android hoặc IOS)\n• Có kinh nhiệm submit/publish app trên store (PlayStore và AppStore).\n• Có kinh nghiệm tạo plugin, package, module.\n• Có kinh nhiệm tích hợp SDK vào các app khác.\n• Có kinh nghiệm về UI/UX và xử lý các animation.\n• Có kinh nghiệm về Flutter generate assets, text, color…\n• Có kỹ năng làm việc với các dự án sử dụng quản lý mã nguồn Git.\n• Có kinh nghiệm về tối ưu performance cho ứng dụng.\n• Có khả năng phân tích yêu cầu và làm việc nhóm.\n• Ưu tiên ứng viên có:\n• Có hiểu biết về CI/CD là một lợi thế.\n• Có kinh nghiệm về Chopper, Dio, Retrofit, Go Route là một lợi thế.\n• Đã từng làm trong lĩnh vực tài chính/ngân hàng là một lợi thế.\n\nWhy you\'ll love working here\n• Lương thỏa thuận theo năng lực\n• Trợ cấp ăn trưa bằng coupon (giá trị 40k/ngày) tại canteen vé gửi xe máy miễn phí.\n• Thường xuyên tổ chức các giải thưởng cho cá nhân/team xuất sắc.\n• Thưởng định kỳ theo hiệu quả kinh doanh, thưởng nóng, thưởng cuối năm (theo tình hình kinh doanh của công ty và kết quả công việc)\n• Review lương 1-2 lần/năm\n• Chế độ khác: BHXH, BHYT, BHTN theo luật lao động. Bảo hiểm sức khỏe PVI (cấp Lead trở lên, hỗ trợ mua kèm người nhà)\n• Teambuilding gắn kết đội ngũ 2 lần/năm cùng toàn thể CBNV công ty\n• Khám sức khỏe định kỳ, Đào tạo và các chương trình văn hóa nội bộ v.v…\n• Nghỉ phép 12 ngày/năm\n• Thời gian làm việc: Thứ 2 – thứ 6 (9h – 18h00) và 2-3 sáng thứ 7 cách tuần (remote)\n• Ngoài ra công ty còn có các CLB chăm lo sức khỏe thể chất tinh thần cho CBNV: bóng đá, bơi, cầu lông, bi-a, đạp xe,…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '19 To Huu, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(329, 283, 2, 'Business Analyst (Nghiệp vụ ERP)', 'Nhiệm vụ chính:\n- Khảo sát, phân tích và định nghĩa yêu cầu nghiệp vụ từ khách hàng\n- Viết tài liệu mô tả yêu cầu (Business Requirement, Basic Design, User Flow, Use Case, etc.)\n- Tư vấn quy trình, nghiệp vụ phù hợp với hệ thống ERP đang triển khai\n- Là cầu nối giữa team phát triển và khách hàng (vai trò BrSE khi làm với thị trường Nhật hoặc nước ngoài)\n- Đảm bảo chất lượng đầu ra phù hợp với kỳ vọng của khách hàng\n- Tham gia test/ xác nhận UAT khi cần thiết\n- Hỗ trợ hoạt động presale, demo, đề xuất giải pháp nếu có\n- Tham gia phát triển giải pháp ERP trên nền tảng no-code / low-code (được đào tạo nếu chưa có kinh nghiệm)\n\nHọc vấn:\n- Tốt nghiệp đại học (ưu tiên chuyên ngành CNTT, Kinh tế, Kế toán, Hệ thống thông tin...)\n\nNgoại ngữ:\n- Tiếng Anh giao tiếp business hoặc Tiếng Nhật (~N2)\n\nChuyên môn & Kinh nghiệm:\n- Có hiểu biết và kinh nghiệm tham gia dự án ERP\n- Am hiểu các nghiệp vụ doanh nghiệp, đặc biệt là nghiệp vụ kế toán\n- Ưu tiên ứng viên đã từng làm việc với các hệ thống như Odoo, Microsoft Dynamics (AX/365), hoặc ERP tương tự\n- Có kinh nghiệm viết tài liệu nghiệp vụ, thiết kế cơ bản, use case, wireframe…\n- Có tư duy hệ thống tốt, khả năng tổng hợp thông tin và truyền đạt rõ ràng\n\nKỹ năng mềm:\n- Giao tiếp và làm việc nhóm tốt\n- Chủ động, ham học hỏi và sẵn sàng tìm hiểu các domain nghiệp vụ mới\n- Có trách nhiệm, cầu tiến, tư duy tích cực trong công việc\n\nTop 3 reasons to join us:\n- Lương và chế độ đãi ngộ hấp dẫn.\n- Môi trường làm việc cởi mở, năng động.\n- Có cơ hội phát triển, thăng tiến.\n\nWhy you\'ll love working here:\n- Môi trường làm việc cởi mở, năng động:\n  - Làm việc với những đồng nghiệp thân thiện, vui vẻ, hòa đồng luôn giúp đỡ nhau\n  - Tôn trọng ý kiến cá nhân, đề cao sự sáng tạo.\n  - Văn phòng làm việc rộng rãi, trang phục tự do.\n- Có cơ hội phát triển, thăng tiến:\n  - Được đào tạo thêm nghiệp vụ, công nghệ mới và ngoại ngữ giao tiếp.\n  - Có nhiều hoạt động nâng cao chuyên môn (Seminar, Workshop, Techtalk...)\n  - Hỗ trợ thi chứng chỉ năng lực chuyên môn.\n- Chế độ đãi ngộ hấp dẫn:\n  - Review lương: 2 lần/ năm; Thưởng: 2 lần/ năm; Thưởng doanh thu dự án theo quý.\n  - 12 ngày nghỉ phép, 3 ngày nghỉ hè và 4 ~ 5 ngày nghỉ có lương của riêng công ty/ năm.\n  - Tham gia hoạt động câu lạc bộ: Bóng bàn, bơi, bóng đá, đọc sách, E-sports (PES, AOE, CS, LOL)...\n  - Được tôn vinh nhân viên xuất sắc hàng tháng/ quý/ năm.\n  - Mỗi tháng sẽ có ít nhất một sự kiện dành cho nhân viên (Du lịch công ty, Sport Day, Family Day...).\n  - Được tham gia 6 lần teambuilding trong 1 năm (theo dự án và theo section).\n  - Chế độ thâm niên.\n  - Chế độ chăm sóc phụ nữ: nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 31, tòa Keangnam Hanoi Landmark 72, Lô E6,  Đường Phạm Hùng, Phường Mễ Trì, Quận Nam Từ Liêm, Hà Nội, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(330, 284, 2, 'IS Specialist (ERP, SQL, C#)', 'The IS Specialist is responsible for ensuring the accuracy and timeliness of data input into the ERP system and other integrated applications. This role requires strong expertise in ERP systems, particularly Epicor, or a demonstrated ability to quickly learn and adapt to new ERP solutions.\n\nResponsibilities\n➢ ERP System Managements\n• Ensure the integrity, accuracy, and timely input of data into Epicor ERP and integrated systems. • Analyze business processes and align ERP functionalities with operational needs. • Configure, customize, and enhance ERP applications through programming and scripting. • Design user-friendly functionalities, interfaces, and reports.\n• Monitor system performance, conduct diagnostic tests, and resolve technical issues. • Stay up to date with the latest ERP upgrades and functionalities.\n➢ User Support & Training\n• Provide technical support to end-users and resolve system-related issues.\n• Develop training materials and conduct ERP training sessions for employees.\n• Assist users in optimizing ERP functionalities for their specific roles.\n➢ Master Data & Database Management\n• Maintain and manage company master data, ensuring consistency and accuracy across systems. • Collaborate with departments and Group IT to collect, update, and deploy master data efficiently.\n\nYour skills and experience\nDiploma – Experience\n• Bachelor’s degree in Management Information Systems or Information Technology.\n• Minimum 2 years of experience working with ERP systems, preferably Epicor.\nCompetences\n• Strong understanding of business processes and ERP development tools.\n• Proficiency in SQL and C#.\n• Proficiency in Microsoft 365 suite, with knowledge of Java and full-stack development being a plus.\n• Excellent analytical and problem-solving abilities.\n• Strong organizational and time-management skills.\n• Effective communication, collaboration, and interpersonal skills.\n• Detail-oriented, proactive, and capable of working independently.\n• Fluent in English; French is a plus.\n\nWhy you\'ll love working here\nWe offer attractive salaries and are very dedicated to investing in the development of our talents. Dedicated and loyal staff will get chances for training and personal development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 9, Tòa nhà Phụ nữ, 20 Nguyễn Đăng Giai, Thảo Điền, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(331, 285, 2, 'IT Administrator (Chinese Speaking)', 'About Faraday: Faraday Technology Corporation is a leading fabless ASIC design and silicon IP (Intellectual property) provider established in 1993 as the first Asian ASIC vendor. Faraday is listed on the Taiwan Stock Exchange (TWSE) under ticket number 3035.\nFaraday Technology Vietnam (FTV) is established in Ho Chi Minh in 2019. We aim to be a full-fledged R&D centre, spanning from RTL design to post-sillicon verification.\n \nAbout the Role\nWe\'re looking for a detail-oriented and proactive IT Administrator to support our Information Technology Services (ITS) operations at Faraday Vietnam. This role bridges communication between our Vietnam team and HQ, helps drive IT process coordination, and ensures seamless communication, documentation, and support across the organization.\n \nKey Responsibilities\n- Manage and monitor the IT support ticketing system: receive user requests, forward them to the appropriate ITS personnel, and follow up to ensure timely resolution.\n- Act as a liaison between Faraday HQ/ES and Vietnam ITS team regarding IT security, procedures, and compliance requests.\n- Prepare reports, internal guidelines, and training documents to support IT operations and knowledge sharing.\n- Communicate ITS updates, policies, and announcements to internal staff in an engaging and timely manner.\n- Handle administrative and documentation tasks related to IT processes and compliance.\n- Coordinate with cross-border teams (HQ/ES and VN) on project-related matters involving IT systems and services.\n\nYour skills and experience\n- Bachelor\'s degree in IT or related field.\n- 1–2 years of experience in IT support, system administration, or IT coordination role (fresh graduates with strong potential are welcome)\n- Strong communication and coordination skills, especially in cross-functional or cross-border environments\n- Basic understanding of IT infrastructure, networks, and security practices\n- Proficiency in Microsoft Office tools and familiarity with ticketing systems\n- Basic English communication.\n- Good Mandarin speaking is a must\n- Organized, detail-oriented, and proactive in following up on tasks\n\nWhy you\'ll love working here\nOur benefits:\n- Attractive and Competitive Compensation Package\n- Lunch and Transport Allowance\n- Healthcare insurance program\n- Advanced career and development opportunities\n- Professional and Engaging working environment\n- Various Employee Engagement Activities throughout the year (Year End Party, Birthday celebration, Company Trip, ….)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phòng 602, 1003, 1004, 1401 Tháp Royal Tower B, Tòa Nhà Royal Centre, 235 Nguyễn Văn Cừ, Phường Nguyễn Cư Trinh, Q.1, TP.HCM, Việt Nam, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(332, 286, 2, 'Java Web Developer (Spring/ SQL) – up to 1600$', 'Top 3 reasons to join us\n- Lương thưởng, phúc lợi tốt\n- Môi trường làm việc thoải mái\n- Đánh giá tăng lương 1 lần/năm\n\nJob description\n- Phát triển các chức năng trên web admin và giao diện trang thanh toán của Cổng thanh toán;\n- Lập kế hoạch công việc và đóng góp ý tưởng sáng tạo để nâng cao chất lượng công việc;\n- Xây dựng tài liệu phân tích, thiết kế, testcase, thực hiện test các chức năng được giao;\n- Thực hiện báo cáo công việc hàng ngày;\n- Tham gia các hoạt động chung của công ty;\n\nYour skills and experience\n- Có ít nhất 2 năm kinh nghiệm làm việc về Java (Web, Core);\n- Có kinh nghiệm làm việc với sản phẩm về trung gian thanh toán, ngân hàng, tài chính, thương mại điện tử là một lợi thế;\n- Thành thạo HTML/CSS, Javascript, jQuery, Bootstrap;\n- Thành thạo Framework Spring;\n- Có kinh nghiệm làm việc với linux;\n- Có kinh nghiệm làm việc với Jasper Report là một lợi thế;\n- Thành thạo SQL, tối ưu DB, có kinh nghiệm làm việc với Oracle;\n- Thành thạo công cụ quản lý source code Git;\n- Có khả năng nắm bắt nhanh quy trình vận hành dịch vụ, quy trình hoạt động của công ty;\n- Đam mê với lập trình và ham học hỏi.\n\nWhy you\'ll love working here\nỨng viên có cơ hội làm việc trong công ty hàng đầu về lĩnh vực thanh toán điện tử với thị trường đang phát triển mạnh mẽ theo xu thế, môi trường làm việc chuyên nghiệp và các chế độ đãi ngộ xứng đáng được đánh giá bằng kết quả công việc và đóng góp của bản thân. Quyền lợi cụ thể như sau:\n- Thu nhập lên từ 20-30 triệu/tháng;\n- Lương tháng 13 và các khoản thưởng Lễ Tết;\n- Đánh giá tăng lương 1 lần/năm;\n- Được hưởng các khoản phụ cấp ăn trưa, điện thoại, đi lại, công tác… theo yêu cầu công việc;\n- Được hưởng chế độ bảo hiểm theo quy định nhà nước;\n- Được mua bảo hiểm sức khỏe và chế độ khám sức khỏe chuyên sâu định kỳ 1 lần/năm;\n- Được tham gia các hoạt động của công ty: Xem phim, team building, company trip với chất lượng 4 sao trở lên và các hoạt động thể thao văn nghệ gắn kết khác của công ty;\n- Được làm việc cùng với các chuyên gia công nghệ hàng đầu trong mảng Fintech tại Việt Nam và Hàn Quốc;\n- Được làm việc trong môi trường chuyên nghiệp, trẻ trung, năng động và cởi mở đồng thời các thành viên gắn kết như một gia đình.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 14, Tòa Handico Phạm Hùng,, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(333, 258, 2, 'VTS - Tư Vấn Giải Pháp - Presales Engineer', 'Gia nhập “vũ trụ” công nghệ Viettel, nơi bạn không chỉ được “đắm chìm” trong hàng loạt công nghệ xịn xò như Big Data, AI, IoT, AR/VR, Cloud, Blockchain… mà còn được trao cơ hội thực hiện sứ mệnh quan trọng: “Chung tay cùng Chính phủ kiến tạo – Chính phủ số”, đồng hành với doanh nghiệp và người dân giải quyết các vấn đề cấp bách của xã hội, hướng tới một cuộc sống tốt đẹp hơn cho mọi người.\n\nTại VTS (Tổng Công ty Giải pháp Doanh nghiệp Viettel), bạn sẽ được hiện thực hóa những ý tưởng táo bạo, tham gia vào các dự án công nghệ hàng đầu và phát triển giải pháp đột phá cho tương lai số. Đây chính là nơi khơi dậy đam mê, thúc đẩy sáng tạo và chắp cánh cho mọi ước mơ công nghệ của bạn. Sẵn sàng trở thành “ngôi sao sáng” trên hành trình chuyển đổi số và cùng Viettel tạo nên dấu ấn trong cuộc cách mạng công nghiệp 4.0? Let’s go!\n\nBạn sẽ làm gì?\nXây dựng, trình bày các giải pháp CNTT dựa trên nhu cầu của khách hàng\nHiểu rõ các sản phẩm dịch vụ đang kinh doanh phục vụ tư vấn khách hàng\nTiếp xúc, khảo sát, tổng hợp và phân tích sơ bộ yêu cầu khách hàng để xây dựng, tư vấn và trình bày giải pháp;\nPhối hợp cùng AM xúc tiến để giới thiệu, trình bày sản phẩm/dịch vụ cho khách hàng;\nLập, tư vấn cho khách hàng về chi phí dự án theo định mức quy định pháp luật;\nXây dựng tài liệu tư vấn dưới sự hướng dẫn của người có kình nghiệm\n\nXây dựng hồ sơ kỹ thuật tham dự thầu dự án (đối với các dự án có quy mô nhỏ)\nPhối hợp với các đơn vị chuyên môn về sản phẩm, công nghệ, triển khai để cập nhật, đồng bộ các thông tin thay đổi trong văn bản quy định của nhà nước ảnh hưởng tới sản phẩm, giải pháp do Viettel cung cấp cho khách hàng hàng.\n\nKỹ năng và kinh nghiệm của bạn\nBằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng, Khoa học dữ liệu hoặc tương đương.\nNgoại ngữ: Đọc hiểu tài liệu tiếng Anh ngon lành. Ưu tiên có chứng chỉ TOEIC 550+ (hoặc IELTS, TOEFL tương đương).\nKiến thức, kinh nghiệm:\nCó tối thiểu 06 tháng kinh nghiệm tại vị trí ứng tuyển.\nKỹ năng giao tiếp, thuyết trình, thuyết phục tốt, duy trì phát triển các mối quan hệ\nKỹ năng lập bảng biểu, kế hoạch, đề xuất quy trình, checklist\nKỹ năng tìm hiểu, nghiên cứu, phân tích so sánh, đánh giá giải pháp công nghệ kỹ thuật, quản lý thông tin sản phẩm CNTT\nKỹ năng tư vấn giải pháp, lựa chọn giải pháp kỹ thuật phù hợp với nhu cầu của khách hàng.\n\nTinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội.\n\nTại sao bạn sẽ yêu thích công việc này\nLương cạnh tranh: Thu nhập “ổn áp”, xứng đáng với năng lực và kinh nghiệm.\nĐầy đủ các khoản thưởng: Thưởng lễ Tết, quà tặng, du lịch nghỉ mát, hỗ trợ ăn trưa, cước điện thoại…\nNghỉ phép linh hoạt: 12 ngày phép + 3 ngày nghỉ mát + 1 ngày sáng tạo mỗi năm.\nBảo hiểm toàn diện: Hưởng đầy đủ BHXH, BHYT, BHTN theo quy định, cộng thêm gói bảo hiểm riêng từ Viettel.\nMôi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo “bung nóc”.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Tran Huu Duc, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(334, 287, 2, 'Senior Backend Developer (PHP, Laravel, MySQL, Kafka)', 'Introduction:\nWe are looking for a highly skilled Senior Software Developer to join our talented engineering team. In this role, you will have the opportunity to work on complex systems that support large-scale applications. You will be responsible for backend development, architecture, system performance optimization, and driving the integration of tools such as Laravel, Kafka, MySQL, Graylog, and AWS.\n\nResponsibilities:\n•	Backend Development:\n•	Lead the design and implementation of scalable, efficient, and secure applications using Laravel.\n•	Architect and build RESTful APIs and services with a focus on scalability and maintainability.\n•	Work on system components with high traffic and large data volumes, ensuring that they are optimized for performance and reliability.\n\n•	Database Management:\n•	Build, optimize, and maintain high-performance MySQL databases.\n•	Ensure data integrity and high availability with a focus on query optimization, schema design, and indexing strategies.\n•	Implement data migrations and transformations as required by the application.\n\n•	Graylog for Monitoring & Logging:\n•	Set up and manage Graylog to aggregate logs and monitor application health.\n•	Work on log processing and ensure log data is being captured correctly for debugging, analytics, and alerting purposes.\n\n•	Performance Optimization:\n•	Continuously analyze system performance and implement improvements to enhance speed, scalability, and reliability.\n•	Optimize code and database queries to ensure high efficiency and low latency.\n•	Address bottlenecks in both the backend code and infrastructure.\n\n•	Mentorship & Leadership:\n•	Provide mentorship and technical guidance to junior and mid-level developers, helping to develop their skills.\n•	Lead by example, contributing to coding standards, code reviews, and best practices.\n•	Foster a culture of learning and growth within the engineering team.\n\n•	Collaboration & Communication:\n•	Collaborate closely with cross-functional teams, including product, design, and operations, to deliver features on time and in scope.\n•	Communicate technical concepts to both technical and non-technical stakeholders effectively.\n•	Lead or participate in architecture reviews, sprint planning, and other agile ceremonies.\n\nYour skills and experience:\nRequirements:\n•	Technical Skills:\n•	Expert-level experience with Laravel framework and modern PHP development practices.\n•	Strong experience working with Kafka for message brokering and real-time data streaming.\n•	Solid understanding of MySQL, including performance tuning, indexing, and query optimization.\n•	Proficiency in AWS cloud services (EC2, S3, RDS, CloudWatch, Lambda, etc.).\n•	Experience with Graylog or similar log management/monitoring tools.\n•	Expertise in performance optimization techniques for both backend and database systems.\n\n•	Experience:\n•	5+ years of professional experience in software development, with a focus on backend systems.\n•	Proven track record in designing, building, and maintaining scalable web applications.\n•	Experience in building and maintaining production-level applications with high traffic and low latency requirements.\n•	Experience in architecting and developing microservices or distributed systems.\n\n•	Soft Skills:\n•	Strong leadership and mentoring skills, with the ability to guide a team through complex technical challenges.\n•	Excellent problem-solving skills and the ability to debug complex issues under pressure.\n•	Strong communication skills, with the ability to effectively communicate complex technical ideas to both technical and non-technical stakeholders.\n•	Self-motivated, proactive, and able to work independently or as part of a team in a fast-paced environment.\n\nWhy you\'ll love working here:\n•	Getting 100% salary paid for work trial.\n•	Attractive salary schemes including 13th month salary.\n•	Equipment provided includes Macbook Pro and widescreen monitor.\n•	Premium healthcare package.\n•	Monthly team dinners and annual company trips.\n•	Opportunity to greatly improve English skills with CubicStack’s international client.\n•	Embracing multiple, new technical stacks to accelerate business development.\n•	Allowed flexible working hours with annual leaves package.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Charmington La Pointe Officetel Apartments, 181 Cao Thang St, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(335, 288, 2, 'AI Analyst (Python, SQL, LLM)', 'Parcel Perform is looking for an amazing team member to support us in data analyzing! Are you interested in e-commerce and like to take on new challenges? Help us drive Parcel Perform’s growth and join our team! We are looking for you!\n\nWE NEED YOU ON OUR TEAM!\n\n- Collaborate with business stakeholders across products, sales, marketing, and technology to identify opportunities for leveraging AI and LLM-powered solutions.\n- Utilize generative AI to uncover actionable insights, predict trends, and design AI-powered solutions that address business challenges, enhance decision-making, and boost productivity.\n- Conduct internal investigations and use LLM applications to analyze unstructured data, generate summaries, or extract key insights.\n- Combine proprietary and external data to perform advanced analyses, explaining the “what”, “why”, and “how” to stakeholders, as well as internal investigation.\n- Effectively communicate insights, model outcomes, and recommendations to business executives in an understandable and actionable manner.\n- Extracting data to report to customers. Investigate and suggest improvements based on customer feedback. Ensure that analytics solutions being developed align with business objectives.\n- Driving initiatives to optimize the operational excellence of the data and AI team. Taking proactive steps to enhance the efficiency, effectiveness, and overall performance of the team in handling data-related tasks and processes.\n\nWHAT YOU SHOULD BRING ALONG!\n\n- 3+ years of experience working as a Data Analyst, Research Engineer, AI Engineer… or related fields.\n- Strong business acumen – the most important ability is to relate the data to our and our clients’ business needs. The ability to technically excel when handling data is welcome, but not mandatory.\n- Familiarity with applying Large Language Models (LLMs) in work is preferred. In addition, experience with tools and frameworks such as Hugging Face Transformers, LangChain, LlamaIndex, or cloud-based AI services like Azure OpenAI, Amazon Bedrock, and Google Vertex AI is A STRONG PLUS.\n- Proven ability to design, fine-tune, and integrate LLMs into workflows, ensuring scalability, reliability, and alignment with business needs. Capable of communicating the impact of AI applications to non-technical stakeholders, bridging technical expertise with the business side.\n- Strong analytical and reporting skills (statistics, story telling).\n- Good proficiency in SQL and intermediate proficiency in Python. Experience with data visualization libraries or platforms such as Jaspersoft, Tableau, Dashboards, is considered a plus.\n- Ability to collect, organize, analyze, and disseminate significant amounts of information with attention to detail and accuracy.\n- Good communication skills, and the ability to translate findings for a non-technical audience.\n- Good written and spoken English.\n- Open-minded, friendly, and strong willingness to keep learning and pushing yourself to higher and higher levels.\n- Work experience with logistics or supply chain data is a plus.\n\nWHAT YOU WILL RECEIVE IN RETURN!\n\nWe at Parcel Perform are dedicated to being a platform for growth for all our team members, regardless of function and location.\n- The opportunity to work in a fast-growing, super exciting, and innovative business that will revolutionize the e-commerce logistics industry. You will be the needle of success on the growth of a global product that will become a key platform behind successful e-commerce logistics worldwide.\n- The ability to continuously learn and develop in an international setting with you being a critical driver behind the success of us achieving our mission.\n- An environment where everybody never stops growing and focuses on succeeding – we continuously work with you on your strengths and weaknesses across many important dimensions and look at ways for you to address them and further your development.\n- Your entry ticket into being part of the Parcel Perform journey, where you will work with and alongside people from around the world that share the same passion and dedication.\n\nBuilt on the industry\'s most comprehensive e-commerce logistics data, Parcel Perform is the leading AI-powered Delivery Experience Platform, centered around AI Decision Intelligence. The company provides businesses with essential AI tools—including Proactive Data Monitoring, Daily AI Insight Summaries, Targeted Recommendations, Performance Alerts, Out-of-the-box Business Intelligence, and the AI Navigator—to optimize operations, personalize the customer journey, and transform e-commerce logistics into a key driver of customer satisfaction and loyalty. With its AI-first approach, Parcel Perform enables businesses worldwide to ensure their delivery experience meets the highest standards, master proactive control, and lead by becoming the preferred choice for consumers in an AI-driven world. Get started at www.parcelperform.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Grace Tower, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(336, 200, 2, 'IT Infrastructure Manager (Linux/Docker/English)', 'We\'re Hiring Innovative IT Manager to Drive Innovation, Lead Transformation, Secure the Future!\n\nJoin DIGI-TEXX - Where Full Stack Meets Future-Ready Infrastructure\n\nWe\'re seeking an innovative, hands-on Tech-Leader to scale resilient next-generation IT Systems and empower our DevOps and engineering teams, driving AI/ML-powered solutions. Let’s build what’s next-together.\n\nWhat You’ll Own & Drive\n- Own our infrastructure & network operations (24/7 uptime)\n- Design, build and optimize scalable full stack environments \n- Ensure strong cybersecurity across threat detection, incident response, and data protection\n- Collaborate with DevOps & ML teams to enable scalable systems, seamless deployments\n- Drive automation, self-healing infra & observability\n\nBuild and lead dynamic IT teams & directly manage client and vendor relations\n\nYour skills and experience\n- 5–10+ years in infrastructure & network management\n- Experience with full stack environments & Continuous Integration/Delivery (CI/CD) pipelines\n- Pro in Linux, Docker, Kubernetes, Git\n- Strong grasp of network security, firewalls, Intrusion Detection/Prevention Systems (IDS/IPS)\n- Automation-first mindset with strong leadership skills\n- Confident, clear English (Certificate or not - if you are at a level at which you can thoroughly describe your technical innovations and strategies to a foreign expert through an online call, we’d like to hear from you.)\n\nWhy you\'ll love working here\n- Lead full stack infrastructure innovation\n- No bureaucracy, full autonomy\n- Competitive compensation + clear growth pathways\n- Collaborative, high-energy, future-focused tech culture\n\nWork Location: 2nd floor, Anna Building, Quang Trung Software City, District 12, HCMC\nWorking time: 8:00 am - 5:50 pm, Mon-Fri', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Anna Building, Quang Trung Software City, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(337, 289, 2, 'Chuyên viên Quản trị hệ thống Corebanking', 'Top 3 reasons to join us\n- Môi trường làm việc năng động\n- Chế độ phúc lợi đầy đủ của Ngân hàng\n- Thu nhập xứng đáng, thưởng tối thiểu 2 tháng,dự án\n\nJob description\n- Tham gia quản trị, phát triển sản phẩm, dịch vụ, tham số hóa và vận hành ứng dụng Core Banking tại VRB.\n- Hỗ trợ người dùng trong quá trình vận hành, sử dụng ứng dụng Core Banking. Tiếp nhận, phân tích và xử lý các yêu cầu hỗ trợ liên quan đến nghiệp vụ trên hệ thống Core\n- Tham gia công tác EOD ứng dụng Core Banking.\n- Phối hợp rà soát, xây dựng các chính sách, quy trình, quy định ứng dụng Core Banking.\n-Tham gia triển khai các dự án CNTT.\n\nYour skills and experience\nTrình độ đào tạo: \n- Tốt nghiệp Đại học trở lên các trường trong nước/ nước ngoài\n- Chuyên ngành: Công nghệ thông tin, Tin học ứng dụng, Khoa học máy tính, Kỹ thuật phần mềm, Điện tử viễn thông, Kỹ thuật thông tin\nYêu cầu kinh nghiệm: \n- Có kiến thức và/hoặc kinh nghiệm trực tiếp vận hành, hỗ trợ hoặc triển khai hệ thống Oracle Flexcube (Core Banking). \n- Có kiến thức và hiểu luồng giao dịch của các phân hệ chính của Flexcube như: CASA, TD, LN, FX, Customer,…\n- Am hiểu cơ chế xử lý batch, end-of-day, và quản trị lỗi trong hệ thống Core.\n- Có kiến thức cơ bản về một ngôn ngữ lập trình, về cơ sở dữ liệu, ngôn ngữ SQL (Là lợi thế tuyển dụng).\nNgoại ngữ: Có khả năng nói, viết bằng tiếng Anh. Chứng chỉ tiếng Anh yêu cầu: tối thiểu tương đương trình độ B1 trở lên theo khung tham chiếu trình độ ngoại ngữ chung Châu Âu.\nTuổi: Không quá 40 tuổi.\nYêu cầu khác:\n- Chịu được áp lực công việc, sẵn sàng làm ngoài giờ khi có sự cố cần xử lý.\n- Tinh thần trách nhiệm cao, bảo mật tuyệt đối, có khả năng làm việc độc lập và xử lý sự cố trong tình huống áp lực.\n- Nghiêm túc, cầu tiến, chịu khó, nhiệt tình trong công việc.\n\n- Ưu tiên ứng viên nộp hồ sơ ứng tuyển bằng Tiếng Anh.\n\nWhy you\'ll love working here\n- Hưởng lương hấp dẫn, phù hợp với năng lực và kinh nghiệm.\n- Làm việc và phát triển trong môi trường trẻ trung, năng động và luôn giàu nhiệt huyết\n- Có cơ hội thăng tiến cao, được làm việc trong môi trường thân thiện, sáng tạo và phát triển.\n- Được tham gia các chương trình đào tạo nghiệp vụ của Ngân hàng.\n- Được chi bổ sung thu nhập theo kết quả làm việc, vị trí công việc và hưởng các cơ chế khuyến khích theo quy định của VRB.\n- Du lịch - Nghỉ dưỡng - Team building hằng năm.\n- Khám sức khỏe định kỳ và chế độ bảo hiểm sức khỏe do VRB tài trợ.\n- Các phúc lợi hiếu, hỷ, tiền mừng sinh nhật, thai sản, …\n- Ưu tiên ứng viên nộp hồ sơ ứng tuyển bằng Tiếng Anh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '75 Trần Hưng Đạo, Hoàn Kiếm, Hà Nội, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(338, 290, 2, 'Leader Tester Engineer (QA QC/ SQL/ ERP)', '1. Lập kế hoạch kiểm thử\n• Xây dựng Test Plan phù hợp với từng giai đoạn dự án ERP (SIT, UAT, Regression...).\n• Xác định phạm vi, nguồn lực và timeline kiểm thử cho từng đợt release hoặc go-live.\n2. Quản lý & giám sát kiểm thử\n• Phân công nhiệm vụ cho đội ngũ tester nội bộ \n• Quản lý và theo dõi tiến độ thực hiện kiểm thử, đảm bảo đúng kế hoạch.\n• Thực hiện các loại test: chức năng (Functional), tích hợp (Integration), hồi quy (Regression), hiệu năng (Performance – nếu có).\n• Đào tạo, hỗ trợ, hướng dẫn nhằm xây dựng đội ngũ có đủ năng lực thực hiện công việc\n3. Phối hợp các bên liên quan\n• Phối hợp với Business Analyst để hiểu yêu cầu nghiệp vụ, từ đó xây dựng test case phù hợp.\n• Phối hợp với Dev để tuỳ chỉnh chức năng theo đúng yêu cầu nghiệp vụ\n• Hướng dẫn người dùng kiểm thử UAT, ghi nhận lỗi và hỗ trợ xác minh kết quả.\n4. Quản lý lỗi \n• Ghi nhận lỗi, phân loại mức độ nghiêm trọng, theo dõi vòng đời lỗi đến khi được xử lý.\n• Sử dụng các công cụ như JIRA, Git hoặc Excel (tùy quy mô dự án).\nXây dựng và duy trì tài liệu kiểm thử\n• Thiết kế test case, checklist kiểm thử.\n• Xây dựng bộ tài liệu UAT cho người dùng và checklist go-live.\n5. Đào tạo\n• Xây dựng tài liệu hướng dẫn sử dụng\n• Tham gia đào tạo, hỗ trợ người dùng cuối\nThực hiện các nhiệm vụ khác theo sự phân công của cấp trên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, tòa nhà Hoàng Ngọc, Số 4 ngõ 82 Dịch Vọng Hậu Cầu Giấy, Phường Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(339, 291, 2, 'Manual QC (Junior - Middle)', 'Top 3 reasons to join us\nThử việc 2 tháng 100% lương\nCơ hội được tham gia vào các dự án CNTT lớn\nTổng thu nhập một năm lên đến 14-15 tháng lương\n\nJob description\n- Đọc hiểu các tài liệu và phân tích yêu cầu của sản phẩm và thiết kế của dự án;\n- Lập kế hoạch kiểm thử và kịch bản kiểm thử, chuẩn bị dữ liệu kiểm thử;\n- Kiểm thử các dự án phần mềm, phối hợp với các bộ phận khác của công ty để đảm bảo chất lượng dự án;\n- Quản lý, phân tích và theo dõi kết quả kiểm thử, báo cáo kết quả kiểm thử…;\n- Phân tích kết quả kiểm tra và phát hiện lỗi;\n- Phát triển các chiến lược Kiểm thử và quy trình làm việc trong dự án;\n- Phối hợp với BA để hiểu các mục tiêu của dự án, nắm được các luồng nghiệp vụ hệ thống để từ đó đánh giá và đưa ra được phạm vi cần;\n- Xây dựng các tài liệu cần thiết bộ phận kiểm thử;\n- Có khả năng đưa ra các giải pháp nhằm cải tiến, nâng cao hiệu quả;\n- Có thể ứng dụng kiểm thử tự động trong quá trình làm việc là một lợi thế;\n- Thực hiện các công việc khác theo sự phân công của Quản lý trực tiếp.\n- Thời gian làm việc VPHN: T2 - sáng T7 8:00AM-17:30PM. Nghỉ 2 sáng thứ 7/tháng\n\nYour skills and experience\n- Tốt nghiệp Cao đẳng trở lên các ngành Công nghệ thông tin, Điện tử viễn thông hoặc tương đương. Có kiến thức về lĩnh vực CNTT;\n- Có ít nhất 1 năm kinh nghiệm ở vị trí ứng tuyển;\n- Nhanh nhẹn, không ngại việc khó, có khả năng làm việc độc lập và làm việc nhóm;\n- Trung thực, có ý thức học hỏi, trách nhiệm với công việc;\n- Có kỹ năng phân tích logic kỹ thuật, dự đoán tình huống có khả năng gây lỗi;\n- Ưu tiên ứng viên có kinh nghiệm kiểm thử các dự án phần mềm CNTT: Dịch vụ công, cổng thông tin, nghiệp vụ doanh nghiệp từ 06 tháng trở lên;\n- Có khả năng làm việc với các tài liệu chuyên ngành bằng tiếng Anh là một lợi thế;\n- Có thể đi công tác tỉnh, onsite bên khách hàng khi có yêu cầu.\n\nWhy you\'ll love working here\n- Tham gia vào các dự án quy mô Bộ ngành, quốc gia, được làm việc cùng nhiều chuyên gia có nhiều kinh nghiệm.\n- Lương: theo thoả thuận theo năng lực.\n- Thưởng tháng lương thứ 13, thưởng KPI (6 tháng một lần, tức 1 năm 2 lần), thưởng theo kết quả kinh doanh, thưởng nóng theo hiệu quả công việc, thưởng ngày lễ (tổng thu nhập một năm lên đến 14-15 tháng lương).\n- Các chế độ phúc lợi khác dành cho nhân viên: sinh nhật, kết hôn, sinh con, ăn trưa, YEP, du lịch, happy hour, team building tháng, tea break, quà lễ/tết,…\n- Hoạt động thể dục thể thao năng động: bóng đá, cầu lông, tennis,…\n- Cung cấp thiết bị làm việc.\n- Tham gia đầy đủ các chế độ bảo hiểm (BHXH, BHYT, BHTN…), khám sức khoẻ định kỳ theo quy định của Nhà nước;\n- Chính sách hỗ trợ đào tạo nâng cao năng lực nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '103 Nguyễn Tuân, Phường Thanh Xuân Trung, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(340, 292, 2, 'HO - CVCC Vận hành và giám sát hệ thống CNTT', 'A. MÔ TẢ CÔNG VIỆC\n1. Giám sát và xử lý sự cố hệ thống:\n- Kiểm tra, giám sát hạ tầng CNTT theo đúng quy trình vận hành.\n- Theo dõi màn hình/cảnh báo để kịp thời phát hiện và xử lý sự cố.\n- Ghi nhận, thông báo và phối hợp xử lý sự cố thông qua hệ thống ticket system.\n- Chẩn đoán nhanh chóng các sự cố phát sinh nhằm đảm bảo dịch vụ hoạt động liên tục.\n- Phối hợp chặt chẽ với các đơn vị liên quan và đối tác để xử lý sự cố.\n\n2. Vận hành hệ thống và công cụ giám sát:\n- Giám sát hoạt động máy chủ, ứng dụng và dịch vụ CNTT bằng các công cụ chuyên biệt của ngân hàng.\n- Triển khai, cải tiến công cụ giám sát và phân tích báo cáo vận hành định kỳ.\n- Ghi nhận đầy đủ nhật ký ca trực, các sự kiện, sự cố trong quá trình vận hành.\n\n3. Hỗ trợ và phối hợp vận hành:\n- Hỗ trợ tra cứu, phản hồi giao dịch từ các kênh: Internet Banking, Open API, và các hệ thống liên quan.\n- Phối hợp triển khai các yêu cầu thay đổi/đề xuất từ khách hàng hoặc bộ phận nghiệp vụ.\n- Đảm bảo tuân thủ các chính sách, quy trình và tiêu chuẩn chất lượng dịch vụ (SLA).\n\n4. Phát triển và triển khai hệ thống:\n- Triển khai ứng dụng, cập nhật bản vá lỗi vào môi trường vận hành.\n- Thiết lập môi trường kiểm thử và vận hành hệ thống CNTT.\n- Cải tiến quy trình vận hành và tài liệu hóa hệ thống.\n- Tham gia các dự án CNTT: tiếp nhận bàn giao, xây dựng và vận hành hệ thống sau triển khai.\n\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Tối thiểu 02 năm kinh nghiệm trong lĩnh vực Ngân hàng hoặc ngành liên quan.\n- Ưu tiên ứng viên có kinh nghiệm trong công tác vận hành/giám sát hạ tầng IT.\n- Thành thạo hệ điều hành Linux/Unix, hệ thống Middleware.\n- Thành thạo các thao tác trên nền tảng Container Docker, Kubeneties.\n- Có kinh nghiệm vận hành Cloud AWS (EKS, MSK, EC2,…)\n- Ưu tiên có kiến thức lập trình hoặc nền tảng kỹ thuật tốt.\n- Ưu tiên có kinh nghiệm sử dụng các công cụ giám sát như: SolarWinds, Zabbix, Grafana, AWS CloudWatch.\n- Hiểu biết các hệ quản trị cơ sở dữ liệu: MSSQL, Oracle, MySQL, PostgreSQL, MongoDB, ELK, Splunk.\n- Tư duy logic, khả năng học hỏi và ứng dụng công nghệ mới.\n- Có kỹ năng quan sát, phân tích và xử lý sự cố nhanh nhạy.\n- Quản lý công việc hiệu quả, làm việc nhóm tốt và chịu được áp lực cao.\n- Có khả năng nghiên cứu, phân tích luồng giao dịch và nguyên nhân lỗi.\n- Giao tiếp rõ ràng, kiên nhẫn với đối tác/khách hàng và hòa nhã với đồng nghiệp.\n- Trung thực, chủ động và có tinh thần trách nhiệm cao trong công việc.\n\nWhy you\'ll love working here\n- TẠI SAO BẠN NÊN CHỌN OCB?\n1. Tại OCB, văn hóa được chú trọng phát triển:\n- Văn hóa làm việc cởi mở, tôn trọng sự khác biệt, khuyến khích đưa ra những ý tưởng mới, sáng tạo và được tạo điều kiện để hiện thực hóa.\n- Đội ngũ đồng nghiệp trẻ trung, nhiệt huyết, luôn sẵn sàng hỗ trợ nhau.\n2. Tại OCB, cơ hội phát triển không giới hạn:\n- Chương trình đào tạo đa dạng và chuyên biệt theo từng chức danh kèm theo lộ trình thăng tiến rõ ràng.\n- Đánh giá hiệu quả công việc hằng quý hoặc 6 tháng với cơ chế minh bạch, công bằng, tạo động lực để bạn phát triển.\nĐẶC QUYỀN OCBERS\n- Muôn vàn lương thưởng: Lương tháng 13, Thưởng KPI, Thưởng theo chương trình thi đua, Thưởng thâm niên, Thưởng sinh nhật, Phụ cấp tùy chức danh…\n- Bảo vệ toàn diện: BHYT, BHXH, Bảo hiểm sức khỏe, Bảo hiểm tai nạn.\n- Trọn vẹn gắn kết: Nghỉ mát hàng năm, Hội thao, Hội diễn văn nghệ\n- Ưu đãi đặc biệt: lãi suất cho vay CBNV, thấu chi tài khoản lương, ưu đãi thẻ tín dụng,…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark Building, 15 Tran Bach Dang Str, Thu Thiem Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(341, 293, 2, 'Lead Engineer (US Product/Golang/Javascript)', 'Top 3 reasons to join us\n\n1. Profitable startup from Year 1!\n2. High pay, MacBook Pro, $1000 annual development \n3. Work with top talent on product changing industry\n\nJob description\n\nAbout the Opportunity\nAs our Lead Engineer, you’ll be leading one of our product engineering squads composed of backend, frontend, and QA engineers. In this role, you will play a critical part in building and enhancing core products & services within our platform, while maintaining strong alignment with technical strategy and operational priorities of the organization.\n\nYou\'ll split your time between hands-on activities such as coding, code reviewing, designing solutions and technical leadership responsibilities, including project delivery, team mentorship and maintaining collaborative environments:\n\n- Squad leadership: lead a cross-functional engineering squad and follow through on a daily basis to drive project execution, from planning to production release.\n- Technical execution: as an individual contributor, participate in product building by contributing directly to the codebases; as a tech lead, set a high bar for engineering excellence by promoting and applying best practices, from code reviewing to architecture decisions.\n- Team leadership: coach and develop team members, find some common grounds between their desired career goals with the company\'s ladder to define an appropriate development plan and provide support to help them grow along their career paths.\n- Cross-functional collaboration: partner and establish working relationships with product managers, marketers, customer support and other stakeholders to align on delivery goals and effective communication channels. Communicate technical decisions & trade-offs clearly to both technical and non-technical stakeholders by using appropriate languages for different audiences.\n- Technical strategy: work closely with CTO, Engineering Manager and other leaders to shape and execute technical strategies, making sure team directions are heading the right path.\n\nYour skills and experience\n\nWhat you need to be successful\n- 5+ years working as a software engineer, with at least 3 years in a lead role\n- Expertise in at least one major tech stack and willing to make the switch to Go and Javascript\n- Experience in building and maintaining high-traffic backend services, preferably running on AWS\n- Experience in building SaaS webapps, preferably using React or similar frameworks\n- Experience working with MongoDB and PostgreSQL or similar databases\n- Proven experience leading engineering teams using approaches that encourage innovation and grow mindset\n- Excellent English communication and interpersonal skills\n- Passion for mentoring and growing engineering talents\n- Experience in async communication with product, marketing, and operations teams in different timezones\n- Comfortable working in fast-paced, agile environments where things are changing & moving moderately fast\n\nNice to haves:\n- Experience in a SaaS/ Product development or email marketing industry\n- Experience with API & automation testing\n- Experience with SaaS problems like fair usage, noisy neighbor\n- Experience working with large databases like sharding, partitioning, no downtime migration\n- Experience working with Martech (email deliverability, tracking, embed analytics)\n- Experience working with Fintech (handling transactions, money flow, fraud prevention)\n\nWhy you\'ll love working here\nWe are a profitable, fast-growing startup with a product that is transforming the industry. We value creativity, hard work, human connection, diversity, and being a great place to work!\n\n- Competitive salary and a 13th-month bonus\n- Stock options for high contributors\n- Personal development allowance of up to $1000/year\n- Premium healthcare coverage\n- Flexible work hours with standard five-day workweek\n- Modern office with top-notch equipment like a Macbook Pro\n- Opportunities for career growth, including overseas options\n\nIf you\'re passionate about making a difference and thriving in a dynamic, collaborative environment, we want to hear from you! Apply now and join us in shaping the future.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Indochina Riverside, 74 Bach Dang, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(342, 255, 2, 'Senior Full-Stack Developer (.NET, ReactJS, NodeJS)', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nWe are seeking a highly skilled and experienced Senior Full Stack Developer to join our in-office team in Ho Chi Minh City, Vietnam. The ideal candidate will possess advanced knowledge and experience in .NET, React, Node.js, and SQL Server. Additionally, we are looking for an individual who is proficient in both modern event-driven architecture and legacy 3-tier architecture and has experience with AI plugins in their Integrated Development Environments (IDEs). Proficiency in writing micro frontends and microservices, transforming legacy applications into modern patterns, and experience with Azure DevOps is essential. The candidate should also have experience with the SAFe Agile Methodology and acting as a technical team lead over a scrum team.\n\nCore Responsibilities\n- Design, develop, and maintain scalable, reliable, and efficient full-stack applications using .NET, React, Node.js, and SQL Server.\n- Ensure performance, quality, and responsiveness of applications.\n- Identify and correct bottlenecks and fix bugs in a timely manner.\n- Help maintain code quality, organization, and automatization.\n- Implement and manage both modern event-driven and legacy 3-tier architectures.\n- Integrate and utilize AI plugins to enhance development processes and outcomes.\n- Develop and maintain micro frontends and microservices to ensure modularity and scalability.\n- Transform and modernize legacy applications to conform to new architectural patterns.\n\nFunctional Responsibilities\n- Collaborate with cross-functional teams to define, design, and ship new features.\n- Mentor junior developers and provide technical guidance to the team.\n- Lead a scrum team as a technical team lead, ensuring effective collaboration and project delivery.\n\nYour skills and experience\nTechnical Skills\n- Minimum of 5 years of professional experience as a .NET Full Stack Engineer.\n- Expertise in React, Node.js, and SQL Server.\n- Strong experience with both modern event-driven architecture and legacy 3-tier architecture.\n- Proficient in using AI plugins with IDEs to improve development efficiency.\n- Solid understanding of software development principles, design patterns, and best practices.\n- Excellent problem-solving skills and attention to detail.\n- Strong communication and teamwork abilities.\n- Ability to work in an agile environment and adapt to changing requirements.\n- Proficiency in developing micro frontends and microservices.\n- Experience in transforming legacy applications to modern architectural patterns.\n- Experience with Azure DevOps.\n- Experience with SAFe Agile Methodology.\n- Strong communication skills in English, both written and verbal.\n\nThings that will separate you from the rest\n- Experience as a technical team lead, particularly over a scrum team.\n- Experience with cloud platforms such as AWS, Azure, or Google Cloud.\n- Familiarity with containerization technologies like Docker and Kubernetes.\n- Knowledge of CI/CD pipelines and DevOps practices.\n- Experience with microservices architecture.\n\nEducation or Certifications\n- Bachelor’s degree in Computer Science, Information Technology, or related field.\n\nWhy you\'ll love working here\n- Highly competitive salary\n- Full salary for probation & full coverage of social insurance.\n- Premium healthcare for you and your beloved one.\n- Monthly childcare support\n- 13th-month salary.\n- Annual Leave: 15 days; Paternity Leave: 6 weeks, Bereavement leave: 10 days.\n- Flexible working time, focus on output (no checking time attendance)\n- Various active sporty clubs: Football, Billiards, Badminton, E-sport clubs\n- Frequent opportunities to travel to US headquarter from 3-6 months.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Six8 Building: 24-26 Phan Dinh Giot Street, Tan Binh District, HCMC., Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(343, 294, 2, 'Google Cloud Platform Cloud Engineer - Hà Nội', 'Role Overview:\nAs a Google Cloud Platform (GCP) Cloud Engineer specializing in consulting and deployment, you will be a key technical resource, guiding our customers in their journey to and within the Google Cloud. You will leverage your deep understanding of GCP services and best practices to consult with clients on their cloud strategies, design robust and scalable solutions, and lead the successful deployment of their systems on the platform.\n\nResponsibilities:\n- Provides expert GCP consultation to understand client needs, design optimal cloud strategies and architectures, and clearly communicate technical solutions.\n- Designs and develops scalable, secure GCP cloud systems tailored to customer needs.\n- Leads and executes GCP system and application deployments, configures and manages GCP services, and ensures efficient and secure operations following best practices and security policies.\n- Identifies and resolves GCP infrastructure and application issues, and proactively recommends system improvements for performance, cost, and security.\n- Serves as the main technical contact for clients, providing ongoing support, addressing inquiries, and offering recommendations based on their needs and GCP advancements.\n- Utilize automation and scripting languages (Python, Bash, or PowerShell) proficiently to automate infrastructure deployment, configuration management, application deployments, and routine operational tasks.\n\nYour skills and experience:\n- Proven work experience as a Senior Cloud Engineer or similar role.\n- Strong communication, presentation, and interpersonal skills.\n- Strong understanding of cloud architecture and design principles, including scalability, high availability, fault tolerance, and disaster recovery.\n- In-depth knowledge of at least one cloud platform, such as AWS, Azure, or Google Cloud Platform (GCP).\n- Troubleshooting and analytical skills.\n- Client management skills to discuss systems as needed.\n- Relevant training and/or certifications as a Cloud Engineer.\n- Terraform to automate infrastructure deployment.\n- Support or construction experience Continuous Integration/Continuous Deployment (CI/CD) pipelines for cloud infrastructure and applications.\n- Good English communication skills.\n- Another certification for AWS, Azure, Kubernetes is plus.\n\nWhy you\'ll love working here:\n- Professional Growth: Thrive in an environment that promotes continuous learning and professional development, with access to a wealth of training and certification programs.\n- Attractive Compensation: Enjoy a competitive salary (negotiable) and a comprehensive benefits package designed to recognize and reward your contributions.\n- Cutting-Edge Technology: Work directly with Google Cloud and its extensive ecosystem, pushing the boundaries of what‘s possible in the cloud domain.\n- Knowledge Expansion: Take your expertise to new heights, delving into the latest trends and innovations in public cloud and digital transformation.\n- Salary: up to 1,800 USD\n- Professional working environment\n- Promotion once/year\n- 13th month salary\n- Insurance based on the Vietnam labor law\n- Yearly vacation\n- 12 full-paid days off\n- Laptop\n- Company party, teambuilding.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 2, Toong Hoang Dao Thuy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(344, 295, 2, 'Software QA Project Manager (Agile, Scrum)', 'Job description\n- Quản lý dự án: Lãnh đạo và quản lý các dự án kiểm thử phần mềm, đảm bảo các phần mềm đạt chất lượng cao, đúng tiến độ và ngân sách.\n- Lập kế hoạch và thực thi kiểm thử: Xây dựng kế hoạch kiểm thử chi tiết cho các hệ thống phần mềm, thực hiện và giám sát quy trình kiểm thử thủ công và tự động.\n- Lãnh đạo nhóm: Quản lý đội ngũ kiểm thử phần mềm, hỗ trợ đội ngũ và đảm bảo tuân thủ các thực hành quy trình kiểm thử tốt nhất.\n- Hợp tác với đội ngũ phát triển phần mềm: Làm việc chặt chẽ với đội ngũ phát triển phần mềm và các bên, đảm bảo yêu cầu dự án và tính tương thích.\n- Quản lý rủi ro dự án.\n- Cải tiến quy trình kiểm thử: Liên tục tối ưu hóa quy trình kiểm thử phần mềm để nâng cao hiệu quả và độ chính xác.\n- Báo cáo và quản lý chất lượng: Đảm bảo chất lượng phần mềm thông qua việc cung cấp các báo cáo kiểm thử chi tiết, bao gồm việc theo dõi lỗi, và đảm bảo các tiêu chuẩn chất lượng cao cho sản phẩm.\n\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành CNTT, điện tử viễn thông, Trí tuệ nhân tạo, hoặc các ngành liên quan.\n- Tối thiểu 5 năm kinh nghiệm trong kiểm thử phần mềm, quản lý dự án.\n- Có kinh nghiệm sử dụng các công cụ kiểm thủ và tự động hóa kiểm thử là một lợi thế.\n- Kỹ năng quản lý dự án: Kinh nghiệm sử dụng các phương pháp quản lý dự án (Agile, Scrum, Waterfall) để quản lý dự án.\n- Khả năng lãnh đạo: Kỹ năng lãnh đạo và quản lý đội kiểm thử phần mềm, với khả năng làm việc nhóm tốt và giải quyết vấn đề hiệu quả.\n- Khả năng giao tiếp xuất sắc, trong việc phối hợp với đội ngũ phát triển phần mềm và các bên liên quan không có chuyên môn về phần mềm.\n- Khả năng giải quyết vấn đề: khả năng phân tích và giải quyết vấn đề trong môi trường phát triển phần mềm phức tạp.\n- Có chứng chỉ ISTQB, PMP hoặc các chứng chỉ liên quan là một lợi thế.\n- Hiểu biết về vòng đời phát triển sản phẩm phần mềm chất lượng quốc tế là một lợi thế.\n- Sử dụng tiếng Anh thành thạo.\n- Ham học hỏi, tư duy logic tốt.\n- Trung thực, có tinh thần trách nhiệm, chịu được áp lực cao, khả năng tự học tốt.\n- Tác phong làm việc chuyên nghiệp, có khả năng làm việc độc lập và theo nhóm.\n\nWhy you\'ll love working here\n- Thu nhập hấp dẫn, cạnh tranh, lên đến 2000$/ tháng.\n- Tăng lương theo kinh nghiệm và thâm niên công tác.\n- Cơ hội học hỏi nhiều công nghệ mới.\n- Môi trường làm việc sáng tạo, năng động, hỗ trợ nhau trong công việc.\n- Tham gia các hoạt động teambuilding cùng công ty.\n- Có BHXH, BHYT, chế độ nghỉ phép đầy đủ theo quy định.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phòng 605, Tầng 6, tháp B, tòa nhà Hongkong Tower, 243A la thành, láng thượng, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(345, 296, 2, 'Remote Java Developer - Spring/JQuery/J2EE', 'We are looking for Java Developer to join us in building high-performing, scalable, Enterprise-Grade website for both public and private sector.\n\nYou will be responsible for backend web development while providing expertise in the projects.\n\nThe Role\n- Design and develop applications for mission-critical systems, delivering in high-availability and performance\n- Participate throughout the full development lifecycle\n- Write well designed, testable, efficient code\n- Support continuous improvement by exploring new alternatives and technologies\n\nYour skills and experience\n- Degree in Computer Science, Engineering or equivalent\n- Passion in coding\n- Experience in JAVA\n- Proficient in Object Oriented programming, SQL and software design pattern\n- Knowledge of ORM (i.e. Hibernate), Spring framework will be advantage\n- 1 to 3 years working experience in web application development\n- Good communication skills, analytical & problem solving skills\n\nWhy you\'ll love working here\n- Fully remote work\n- Attractive remuneration package\n- Flexibility and work-life balance\n- Positive company culture and values\n- Supportive and encouraging team members\n- Excellent career development opportunity\n- Comprehensive on-job training\n\nHere is our VMV - Come to join us\nVISION\nTo solve tomorrow’s challenge.\nMISSION\nWe enable clients to enrich their customer understanding, create impactful business decisions, and take clients’ business to next level through ideas and solutions.\nVALUE\nWhen we make our earth, clients, and team members happy, the rest will come.\n\nOur company is planning to establish a new team in Vietnam and we would like ‘YOU’ to be a part of our team.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote, Other, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(346, 297, 2, 'Mobile App Developer (React Native)', 'We are seeking a Mobile App Developer to join our expanding team. If you have a strong foundation in software development and the ability to thrive in our fast-paced industry, we would love to talk to you!\n\nLocations: Ho Chi Minh, Da Nang, Hanoi\n\nWhat You’ll Be Doing\n- Working on Mobile Apps for a diverse range of clients and industries.\n- Collaborating and pair programming with other developers to build mobile applications using React Native.\n- Working with the product owner to convert business requirements into technical designs.\n- Cooperating with UI designers to implement modern minimalist designs into production.\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n\nYour skills and experience\nRequirements\n\nMust have\n- A minimum of 4 years of experience in web or mobile development using React Native.\n- Good web front-end knowledge: Javascript, HTML/CSS, responsive layouts.\n- Prior experience with REST API.\n- Excellent written and verbal communication skills in English.\n\nNice to have\n- Familiar with mobile app performance monitoring and optimization.\n- Familiar with Agile Process and Scrum Methodologies.\n- Familiar with Extreme Programming practices: TDD (Test Driven Development), Refactoring, and Continuous Integration.\n\nWhy you\'ll love working here\nWho We Are\nCodeLink is an innovative and design-focused development agency. We focus on user-centric design and agile development to bring the product vision of our clients to life. We handle the end-to-end development of products, developing the product vision through product understanding, designing experiences through UX design, refining these flows with modern UI design, and developing products through iterative agile development.\n\nWe work with both early-stage product teams and teams with existing products from a wide range of countries and industries. We focus on modern technologies and work directly with our clients. We design using design-thinking principles on tools such as Sketch, Figma, Zeplin, and more, and develop products leveraging our tech stack of React, React Native, Rails, Python, and Node.JS.\n\nOur Core Values\n1. Take full ownership of delivery\nWe take ownership of our client projects and ensure that we deliver what we are in charge of to the best possible outcome.\n\n2. Deliver our highest level of quality\nWe take pride in the high quality that we deliver and work at a sustainable pace to ensure we can always deliver on that quality.\n\n3. Stay consistent in plans and processes\nWe keep open and transparent communication with our teammates and our client whilst following agile development practices.\n\n4. Have empathy for all those we work with\nWe show empathy and respect to all those we work with to gain a deeper understanding without any judgment or assumption.\n\n5. Continuously improve and grow\nWe aim high with a growth mindset and see every day as an opportunity to develop ourselves, our processes, and our products.\n\nTop 3 Reasons To Join Us\n- Use cutting-edge & proven technologies\n- Work directly with international clients\n- Open environment with a focus on learning\n\nWhy You’ll Love Working With Us\nWe work hand-in-hand with our clients to fully invest in their product development and build solutions together for their target market.\n\nWe fully invest in our team, we will help you build yourself up in any area you feel you need development, be it in English, learning a new design tool, developing your design thinking, and more. We want to make sure that you’re always learning and developing yourself whilst a part of our team.\n\nWe respect both Product and Technology equally, ensuring all of the Products we work on have features with true market potential and ensuring all of the team contribute to, understand, and believe in what they are developing.\n\nWe are very selective with our clients, we only work on awesome products we believe in and that show strong market potential.\n\nWe respect you and your personal hours, we keep a sustainable pace by working standard 8 hour days from Monday to Friday, ensuring we only plan for what we can achieve.\n\nWe are fully agile and only work with Clients who work the same, working with set sprint goals and working at our rate of velocity.\n\nYou will have ownership over your role, giving you the opportunity to experiment and try new processes to better improve your day-to-day responsibilities. We are always open to improving our processes.\n\nCompany Benefits\n- Three days remote every week and four full remote weeks per year.\n- Gold level Health Insurance coverage from Bao Viet Insurance, a yearly complete Health Check and social insurance\n- All office benefits and full salary during probation.\n- Flexible working time starting anytime up to 10 AM, working Monday-Friday with no overtime and a long lunch break.\n- Allowance for everything: meals, parking, petrol, along with unlimited snacks and nice coffee every day.\n- Choose from a brand-new Mac or PC device.\n- Salary review twice a year with opportunities for promotions and spot awards.\n- 12 days annual leave per year, with all days not taken paid out in cash, plus 2 sick leave days.\n- Yearly Training Budget up to 5 million VND per staff. On top of that, Professional coaching program, buddy system, tech talks, agile sessions, and 1on1 private English classes are available\n- Yearly company trip, monthly activities, , and other Celebrations for special days in the year, such as Women’s Day, YEP, and Christmas.\n- Employee-led clubs within the company; games teams, sports teams, etc.\n- Modern open-space office with comfortable workspace, a PS5 games room, and chill-out areas.\n\nWhere We Work\nHCMC Head Office: Level 8, Vina Building, 131 Xo Viet Nghe Tinh, Ward 17, Binh Thanh District, HCMC\nHanoi Office: Ba Dinh District, Ha Noi City\nDa Nang Office: Hai Chau District, Da Nang City', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ha Noi, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(347, 238, 2, 'CV Kiến trúc An toàn TT- Information Security Architect', 'Top 3 reasons to join us\n1. Mức lương cạnh tranh, hấp dẫn\n2. Môi trường làm việc chuyên nghiệp, thân thiện\n3. Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Thiết kế kiến trúc ATTT: tham gia vào dự án, quá trình phát triển sản phẩm đưa ra các thiết kế giải pháp đảm bảo kiến trúc ATTT cho hệ thống, ứng dụng, cơ sở dữ liệu, …\n- Đánh giá rủi ro\n- Xây dựng tiêu chuẩn, quy trình bảo mật (ISO27001, NIST, PCIDSS)\n- Hỗ trợ triển khai giải pháp ATTT\n\nYour skills and experience\n- Tốt nghiệp Đại học các chuyên ngành: Công nghệ thông tin, Toán tin, Điện tử Viễn thông, ....và tương đương\n- Có ít nhất 01 năm làm việc tại các vị trí liên quan đến bảo mật, rủi ro an ninh\n- Hiểu biết về ISO27001, PCIDSS, NIST, Nghị định 13, Thông tư 09, ...\n- Hiểu biết về các giải pháp bảo mật trong môi trường Cloud-Native\n- Ưu tiên:\n  + Ứng viên có hiểu biết rộng về các giải pháp bảo mật FW/ IPS/ WAF/ EDR; giải pháp giám sát an ninh SIEM/ SOAR; IAM\n  + Có chứng chỉ CISSP, CISM, CEH\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n  + Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm; Thưởng các dịp lễ tết trong năm; Thưởng theo danh hiệu cá nhân và tập thể…\n  + Du lịch nghỉ dưỡng hàng năm\n  + Khám sức khỏe định kì\n  + Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n  + Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n\n- Cơ hội nghề nghiệp và phát triển bản thân:\n  + Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n  + Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n  + Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n  + Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n\n- Môi trường làm việc lý tưởng với:\n  + Những người cộng sự thân thiện và tài năng\n  + Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(348, 298, 2, 'Senior Frontend Developer (ReactJS/VueJS)', 'ANDPAD Vietnam is seeking a Senior Frontend Developer (ReactJS/VueJS) who can join to our team and develop the application in cooperation with the product manager, working in the form of Squad, a small team can quickly and consistently engage in everything from design to development, testing and operation.\n\nAlso, there are a lot of opportunities to work with new languages ​​and FWs other than the main language in an international environment.\n\n■ Job Scope\n• Design and implementation function of the product in charge using ReactJS/VueJS\n• Implement UI and improve UX close to the customer\'s business to realize DX promotion\n• Requirements definition and specification formulation in collaboration with product managers and designers\n• Review the design, programming of other engineers\n\n■ Development environment\n• Programing: TypeScript/HTML/CSS\n• Framework: VueJS, NuxtJS, ReactJS, NextJS\n• Infrastructure: AWS/GCP\n• CI/CD: Circle CI/Bitrise/GitHub Actions\n• Knowledge Tool: Confluence/esa\n• VCS: GitHub\n• Others: Slack/Jira/Trello\n\nYour skills and experience\nMust have:\n• Empathy for Andpad\'s mission and values\n• 7+ years of experience in a software development role: Frontend Developer\n• Experience with TypeScript language\n• Experience with frontend frameworks (VueJS, ReactJS etc.)\n• Knowledge and ability to explain principles of web operation and differences of browsers\n• Experience as a technical lead throughout the full project development lifecycle\n• Basic knowledge of Web application security\n• Skills of development and operation using various frameworks\n• Experience Test code implementation (Unit Test)\n• Good at English communication\n\nNice to have:\n• Knowledge of backend development (Golang/ Ruby on rails/ Others)\n• Experienced developing Front-end microservices.\n• Experience of discovering problems from logs and solving problems \n• Experience of deciding and progressing the technical policy of the team as a tech lead.\n• Experience of using and understanding of  Library and Framework.\n• Experience of publishing and contributing to OSS.\n\nWhy you\'ll love working here\n• Competitive salary package, including full insurance coverage.\n• Annual performance review: twice/ year.\n• 13th-month salary Bonus.\n• Remote/ Hybrid working model.\n• 18 days of leave: 12 days of annual leave, 6 days of New Year Leave.\n• Premium Healthcare Insurance Package starting from day one.\n• Annual Health Check-up.\n• Excellent career development opportunities, with exposure to and experience in the latest technologies.\n• Patents and Inventions bonus.\n• Company trip, Year-End Party, Gifts for Tet/ Holidays.\n• MacBook Pro/laptop is provided.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3rd Floor, Dong Nhan Building, 90 Nguyen Dinh Chieu, Da Kao Ward, District 1, Ho Chi Minh / 2F, Building C, Office Area, Udic Complex, Hoang Dao Thuy Street, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(349, 250, 2, '[Ho Chi Minh & Da Nang] Product Owner', 'Top 3 reasons to join us\n- Performance Bonus\n- Well-being allowance\n- Medical insurance for the staff\'s family\n\nJob description\n- Owning a product/product line, developing and maintaining product vision and strategies to achieve it\n- Run discovery workshops (Service Design, Product Design, Personas, MVP scoping, Inception Deck).\n- Create Inception Deck to align all stakeholders and development team’s members\n- Explain to the development team about the product’s market & users\n- Creates the User Story Map and define the minimum viable product (MVP)\n- Manage Product Backlog (create & list requirements)\n- Make the plan for release and each time-box (iteration)\n- Perform user acceptance testing, validate that delivered features meet agreed functional & technical acceptance criteria.\n- Work closely with the development team to make sure that product backlogs are understood correctly, and make adjustments in time if needed\n- Translate business needs into well-structured epics, user stories, and acceptance criteria that consider data flow, edge cases, and non-functional needs.\n- Clarify requirements with engineers, review proposed solutions, and ensure feasibility without over-engineering.\n- Translate requirements into wireframes, user flows\n- Collaborate with UIUX designers on visual polish, ensuring consistency with the Design System.\n- Drive the product evolution through data analysis and user feedback\n- Define and validate product KPI and monitor it\n- Communicate with business stakeholders\n\nYour skills and experience\n- Advantageous to have 3-5 years of experience in product/service planning/UX\n- Have at least 2-year experiences related to software development\n- Fluency in English is a MUST\n- Communication & negotiation skill\n- Organizational & analytical skill\n- Continuous improvement mindset\n- Data-driven focus\n- Be a savvy application user or have experience in website design\n- Familiarity with Agile Software Development\n- Having experience in the shipping industry is a plus\n\nWhy you\'ll love working here\nAt OTSV, work is a self-fulfillment, we encourage staff to leave their comfort zone, think out of the box, and share their ideas without hesitation. As a team, we analyze and evaluate issues objectively to learn quickly from mistakes.\nWe believe in ‘fail quick, success quick’ and strive to keep pace with the forefront of technology to digitize ONE’s business.\nThe designs of our offices embrace our culture of being flexible and open. Unlike a conventional office, we have an open concept with different work areas which encourages collaboration, open-mindedness, and spontaneity.\nEach work area has its charm and aims to make our staff feel as comfortable in the office as they would feel at home. Have a meet-up at the Café amidst the aroma of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà ETOWN 6 - 364 Cộng Hòa, Phường 13, Tan Binh, Ho Chi Minh; Tầng 3-4 tòa nhà Phi Long, 52 Nguyễn Văn Linh, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(350, 224, 2, 'Engineering Manager (Ruby/Golang/Java - Open for Expat)', 'Top 3 reasons to join us\n- Hybrid working; Flexible time; Macbook Pro\n- L&D programs; 17 days off \n- 13.7 million B2C users; 140,000+ business customer\n\nJob description\n- Manage multi-product teams to build and deliver products on engineering standards and ensure code quality.\n- Evaluate multiple technical solutions, balancing performance, scalability, maintainability, and cost.\n- Ability to create and maintain relationships with a wide range of stakeholders.\n- Be the voice of reason between speed and quality.\n- People management(1:1 meeting, personal development & training plan, career path, probation reviews, and performance reviews).\n- Coach teams in applying Scrum and DevOps and be responsible for continuous improvement of the teams.\n- Lead initiatives for implementing efficient development and delivery processes.\n\nYour skills and experience\nMust-have:\n- Background in Information Technology, Software Engineering, or Information System \n- 10+ years of experience in software development\n- 8+ years of experience in managing web projects or product development \n- Have worked as a senior Ruby/Golang/Java software engineer or higher\n- Experience in handling/building an engineering team (direct or indirect) of 10-20+ members, organizational agility\n- Excellent problem-solving skills, especially in dealing with escalated or critical issues \n- Good experience in people management: employee satisfaction, career growth, performance review, coaching, mentoring, 1:1 meeting\n- Good experience in Agile: Methodologies (Scrum, Kanban, LeSS) and practices\n- Strong knowledge of security and robust high-performance system\n- Good experience in microservices, micro-frontend, and multi-tenant architecture design/implementation\n- Experience in solving complex requirements/problems both business and technology such as: Finance System, Accounting System, Banking System, Distributed System, Scalable web applications\n- English skills (professional working proficiency)\n\nNice-to-have:\n- Japanese\n\nWhy you\'ll love working here\nCaring Mental & Physical Recreation:\n- Hybrid working: 2 days at the office and 3 days WFH\n- Working hour: Flexible start 8AM-9AM from Mon-Fri\n- Full salary in probation\n- Insurance: Applied from Probation period: - Social Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\n- Private health insurance & accident insurance. From Managing level: extra for family members\n- Bonus: 13th month salary\n- 17 - 24 paid days off and more\n- Paternity leave: Extra 5 days\n- Annual company trip; Quarterly team building\n- Billiards & Running club\n- Annual health check\n- Well-equipped facility: Macbook pro, additional monitor,.. \n\nCaring Career & Development:\n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- External & internal training courses\n- Soft-skill workshops\n- Tech seminars\n- Monthly and biannual Recognition Awards\n- Performance & salary review: twice/year (Jun & Dec)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ETown Central Building, 11 Doan Van Bo, Ward 13, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(351, 238, 2, '[Middle, Junior] Java Backend Developer (Spring)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Phát triển, trực tiếp lập trình các hệ thống, ứng dụng của Ngân hàng, gồm các hệ thống nội bộ và ứng dụng dành cho khách hàng với quy mô 30 triệu khách hàng cá nhân và 300.000 khách hàng doanh nghiệp.\n- Phát triển hoặc phối hợp triển khai cùng các nhà cung cấp cho các giải pháp Công nghệ.\n- Quản lý, phát triển dịch vụ tích hợp với các hệ thống core như: T24, WAY4, BPM, CRM, CIC ...\n- Quản lý, phát triển API trên API Gateway phục vụ tích hợp với các đối tác trong nước và quốc tế.\n- Nghiên cứu, thử nghiệm, triển khai áp dụng các xu hướng công nghệ mới vào việc phát triển: GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL ...\n\nYour skills and experience\n- Tốt nghiệp Đại học các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Khoa học máy tính, Hệ thống thông tin...\n- Có kinh nghiệm làm việc thực tế tại các công ty hoặc dự án về lập trình Backend\n- Thành thạo 1 trong các ngôn ngữ BackEnd, ưu tiên Java.\n- Thành thạo Spring framework: spring core, spring sercuity, spring boots.\n- Thành thạo một trong trong các loại database: Oracle, Sqlserver, PostgreSQL, Mongodb.\n- Có kinh nghiệm trong domain tài chính, ngân hàng là lợi thế\n\nWhy you\'ll love working here\n**Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:**\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm; Thưởng các dịp lễ tết trong năm; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n\n**Cơ hội nghề nghiệp và phát triển bản thân:**\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n\n**Môi trường làm việc lý tưởng với:**\n- Những người cộng sự thân thiện và tài năng\n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(352, 224, 2, 'Information Security & IT Helpdesk Manager/ Specialist', 'ABOUT US: Money Forward was established in 2012, we have grown significantly during the last 12 years and become the leading fintech and SaaS platform in Japan. We are serving 140,000 commercial clients and 14 million individual users in Japan.\nMoney Forward Vietnam puts Forwardians at the core of every decision by creating an environment where they can seize opportunities to grow sufficiently, and by providing a workplace where they can contribute with joy, and endeavor. MFV is aiming to not only move your career forward, but also move your life forward.\nLocation:\n21st Floor, Etown Central Building, 11 Doan Van Bo Street, Ward 13, District 4, Ho Chi Minh City\n11th Floor, ROX Tower, No. 54A Nguyen Chi Thanh, Lang Thuong Ward, Dong Da District, Hanoi City.\nOVERVIEW:\nWe are looking for an Information Security & IT HelpDesk Manager to strengthen our security and IT operations. In this role, you will work proactively to improve our company\'s security and IT systems. You will create and carry out plans based on company situations, working closely with teams with a global organization. This position requires someone who can take initiative, set high standards, and bring the entire company on board to achieve objectives.\nKEY RESPONSIBILITIES:\nIT Governance:\n- Lead risk assessment processes and implement mitigation strategies\n- Develop and conduct security awareness training programs tailored to the local context\n- Manage security incident response procedures\n- Evaluate compliance with the group information security standards and implement improvements in the company operation.\n- Understand and implement control requirements and regulations from the information security department and the legal department in the headquarters.\nCorporate Security:\n- Oversee network, endpoint and device security \n- Collaborate with teams in Japan to optimize operational efficiency while maintaining security\n- Aligning with the group direction to develop and implement security-conscious productivity solutions.\nIT Operations (IT Helpdesk) (only ~20% job tasks)\n- Improve and maintain Corporate IT operations for a 100+ employee organization, such as device and account management processes.\n- Hands-on management of devices, office facilities, software accounts, office network, IT help desk.\n- Manage local Corporate IT team members.\nYour skills and experience\nEssential (IT Governance skill): \n- 8+ years of experience in IT/Security roles, with 2+ years in management positions\n- Advanced/ Strong experience in IT Governance with ability to build and implement security strategy and process for the whole company\n- Experience in risk management and security operations\n- Proven track record in implementing security programs and policies\n- Understanding of information security frameworks (ISO 27001, NIST, etc.)\n- Strong logical thinking, leadership, and stakeholder management skills\n- Good communication skills in English.\nNice to have (Corp Security & IT Helpdesk skill): \n- Intermediate experience in network security\n- Intermediate experience in device security\n- Intermediate experience in IAM, Entra ID, Active Directory\n- Experience managing corporate IT infrastructure and operations.\nPersonal Qualities:\n- Strategic thinker with strong problem-solving abilities\n- Self-motivated and able to work independently\n- Excellence in stakeholder management and communication\n- Strong leadership and team management skills\n- Ability to balance security requirements with business needs.\nNote: We\'re open for Principal/ Senior level for this role. Candidate with less of years of experience can apply.\nWhy you\'ll love working here\nFinancial Benefits:\n- Attractive Salary Package comparing with market standard\n- Insurance based on full salary (Social Insurance, Health Insurance, Unemployment Insurance)\n- Private health insurance and accident insurance\n- Full salary during probation period\n- 16-24 paid leaves per year\nWorking environment:\n- Very well-equipped facility: Macbook Pro, Additional monitor\n- Hybrid working model with 2 working days in office per week\n- Annual Company trip and Quarterly Team building\n- Working in an international environment with nice and supportive colleagues\n- Work life balance environment\n- Sport clubs in the company for engagement activities: billiard club, running club\nCareer Development:\n- Clear Career path\n- Strong sponsoring from companies for various technology courses and certifications\n- External & internal training courses\n- Tech seminars\n- Monthly and biannual Recognition Awards\n- Performance & salary review: twice/year (Jun & Dec).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '11th Floor, ROX Tower, No 54A Nguyen Chi Thanh, Lang Thuong Ward, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(353, 299, 2, 'Techlead Fullstack Java (Good English)', 'Top 3 reasons to join us\n- Attractive salary package + signin bonus\n- Professional working environment \n- Opportunity to become core manager\n\nJob description\n- Application Development and Maintenance: Use Java and Spring Boot to develop and maintain high-performance web applications and microservices, ensuring high availability and responsiveness.\n- Performance Optimization: Analyze and optimize application performance to minimize latency and maximize resource efficiency.\n- Software Quality Assurance: Write and maintain test suites, conduct code reviews, and ensure adherence to software development standards.\n- Team Collaboration and Technical Leadership: Work with team members, mentor junior developers, and coordinate with other departments such as DevOps, QA, and Product Management.\n- Knowing how to design System Architecture is a plus.\n\nYour skills and experience\n- Experience: At least 8 years of software development experience, with substantial expertise in Java and Spring Framework (Spring Boot, Spring Cloud, Spring Security, etc.) and FE: VueJS/ ReactJs\n- Programming Skills: Strong object-oriented programming skills, understanding of software design patterns, and ability to solve complex problems.\n- Related Technologies: Experience with related technologies such as Hibernate, JPA, RESTful APIs, Microservices, Docker/Kubernetes, JUnit, and databases like MySQL, PostgreSQL, MongoDB.\n- Teamwork Skills: Excellent communication and teamwork abilities, capable of leading and mentoring within a team.\n- Educational Background: Diploma in Information Technology, Computer Science, or a related field.\n\nSoft Skills: Leadership (Team size 5-10 mem)\n- Problem-Solving: Ability to identify creative solutions to technical challenges.\n- Communication: Strong communication skills, able to clearly and persuasively convey ideas.\n- Time Management: Effective time management skills and ability to prioritize tasks appropriately.\n\nWhy you\'ll love working here\n- Working time: 8.30 am – 5.30 pm from Monday to Friday.\n\nOPPORTUNITIES AND CHALLENGES:\n- Opportunity to work in a professional, modern and energizing setting.\n- Challenging projects, possibilities, cutting-edge technology, and problems.\n- An open and dynamic working atmosphere that promotes the interchange of ideas, while also empowering you to work and create in your own style. Each employee\'s talent and accomplishments are valued, and outstanding employees are recognized and rewarded on a yearly basis.\n- Opportunities for capacity development, as well as assistance with professional certification expenses, are available to those who work in the field (1 million - 5 million).\n- Some advanced certifications will cover the full cost of studying and taking the exam.\n\nATTRACTIVE REWARDING POLICY AND WORK-LIFE BALANCE:\n- Review salary 1-2 times/year, with the possibility of an unexpected salary rise based on capacity an infinite number of times per year\n- Policy for 13th-Month Salary Bonus and Holiday Bonuses According to Company Regulations.\n- Holiday travel mode (package 5-7 million/person), team building,...\n- Full participation in social insurance, as well as a yearly health checkup at a reputable hospital.\n- Comprehensive visit policy for personnel and relatives: birthday, marriage, childbirth, illness, etc.\n- The football club, cycling car, badminton, ... are just a few of the sports and cultural activities available.\n- Allowance for classes and training awards: Learning Star of the Month,\n- A chance to be the face of the year\'s study, the royalties...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '19 Duy Tân, P. Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(354, 300, 2, 'Fullstack Developer (NodeJS/ReactJS,Javascript)', 'Top 3 reasons to join us\n- Attractive salary + KPI bonus based on performance\n- Opportunity to be led by top architects & leaders\n- High teamwork spirit and flexible working time\n\nJob description\n- Design, code, and review scalable, maintainable software solutions that align with business and system architecture.\n- Identify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\n- Collaborate across squads (frontend, backend, QC…) to share knowledge, align on best practices, and mentor junior team members\n- Take ownership of features or systems; lead projects or squads when needed, ensuring delivery quality and guiding technical direction.\n\nYour skills and experience\nMust-Have:\n- Proactive problem-solver with a bias toward action and ownership.\n- Quick to pick up new frameworks, libraries, and tooling as the stack evolves.\n- From 1 to 5+ years of hands-on experience in software development — we’re hiring across levels (Junior to Senior), and responsibilities will be matched accordingly\n- Familiarity with macOS or Linux for development and deployment tasks.\n- Hands-on experience or working knowledge in our core stack is required; full expertise in one side (FE or BE) is acceptable:\n- Backend: Node.js, Express.js, PostgreSQL, Redis, Elasticsearch.\n- Frontend: React.js, Next.js, Redux, Redux-Saga, Reselect, React Hooks.\n- Commitment to code quality:\n- Strong experience in code reviews.\n- Familiarity with unit testing best practices.\n- Growth mindset: Ready to grow rapidly as the company scales several times a year.\n\nNice-to-Have (Plus):\n- Deep understanding of Webpack, including code splitting, asset optimization, and custom configurations.\n- Strong foundation in computer science: Data structures, algorithms, design patterns.\n- Experience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\n- Familiarity with microservices architecture.\n\nWhy you\'ll love working here\nBenefits:\n- Competitive Compensation & Bonuses\n- Attractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n- 100% salary during the probation period.\n- 13th-month salary to ensure financial stability.\n- Performance reviews twice a year with opportunities for salary adjustments.\n\nFlexible Work & Growth Opportunities:\n- Hybrid working model: Work from home or at the office as needed.\n- Work alongside top CTOs, architects, and tech leaders at Vexere.\n- Build your public profile through:\n- Publishing articles on Medium & Vexere Techblog under your name.\n- Contributing to Open Source projects managed by Vexere.\n- Speaking at tech talks and industry events.\n- Attractive stock options for dedicated developers and team leads.\n\nExclusive Employee Perks:\n- Up to 30% discount on bus tickets for Vexere employees and their families.\n- 12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\n- Vibrant and dynamic work environment with a friendly, supportive team.\n- Training sessions on negotiation, communication, work management, interpersonal skills, and software technology.\n- Exciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nOur mission and vision:\n- Vision: Everything you need for travel & transportation\nOver thousands of years, human history has made great leaps, mainly due to the application of technology. Believing in this, VeXeRe strongly desires to improve and upgrade people\'s lives through the ability to innovate and apply technology, meeting all needs in travel and transportation sectors.\n- Mission: Bring more happiness to your journey\nEveryone has trips that can be the beginning of excited and happy journeys, changing each person\'s life. Therefore, the mission that VeXeRe strives for is not only limited to regular trips, but also the journey of life of each person. VeXeRe wishes to accompany and bring more happiness to each journey.\nHappiness can be enhanced: It can be a cheaper trip that enables more people to travel, more access to better services, with more happy and more meaningful experiences.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '384 Hoàng Diệu, phường 6, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(355, 301, 2, 'Senior PHP Developer (salary up to $1,500)', 'Top 3 reasons to join us\n- Allowances on holidays and quarterly bonus\n- PTI insurance package\n- Open working environment with young people\n\nJob description\n- Participate in the development of projects with customers in the field of e-commerce, manufactory and property management in Japan.\n- Develop software applications using VueJS and Laravel framework.\n- Maintain and enhance the existing applications if needed.\n- Join in full cycle of design, develop, test and deploy a software application.\n- Perform assigned tasks independently.\n- Ability to work independently and team work.\n- Ensure the assigned tasks to be performed on-time and with high quality.\n- Comply with established coding quality standard of the company.\n\nYour skills and experience\nMUST HAVE\n- At least 3 years experience of PHP7, PHP8 and latest Laravel frameworks.\n- Experience with writing unit test for projects using PHP, VueJS, Javascript, Typescript.\n- Familiar with software life cycle and project management.\n- Familiar with front-end such as VueJS, JavaScript, JQuery, Bootstrap, HTML5, CSS3, SCSS.\n- Familiar with unit test, code review, source control (Git), and issue tracking (Jira/ClickUp).\n- Good knowledge of RDBMS (MySQL) and understanding how to optimise SQL queries for better performance.\n- Good experience in problem solving and trouble shooting.\n- Good communication and team work.\n- Good mindset in helping client as yourself.\n- Willing to support the other members.\n- Can proactively learn and gain necessary skills for existing or future projects.\nNICE TO HAVE\n- Fair communication in English (speaking, listening).\n- Experience in using other languages such as NodeJS, NestJS is a plus.\n- Have experience in using AWS (Docker, EC2, S3, RDS) is advance.\n\nWhy you\'ll love working here\nBENEFITS WE HAVE:\n- Salary review 2 times/year\n- Attractive salary\n- 13rd month salary and Quarterly bonus\n- PTI insurance package\n- Allowance for parking/birthday/holidays\n- Periodically teambuilding activities\n- Open working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '7th floor, Loyal building, 151 Võ Thị Sáu, phường Võ Thị Sáu, quận 3, TPHCM, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(356, 302, 2, 'Developer Manager (Java Technical Lead, English)', 'Top 3 reasons to join us\n- Flexible working hour\n- Private health care insurance \n- Premium annual health care check\n\nJob description\n- Directly communicate with Product, Developer, QA and Executive teams.\n- Control project plan execution for the team\'s feature.\n- Collaborate with team members to investigate, analyze, design and estimate features based on specification.\n- Participate in required meetings.\n- Handle internal processes for team members (hiring, training, performance review, etc.).\n- Conduct code review for team members.\n- Support revolving business logic and technical problems for team members.\n- Process issue from Support/QA team and/or assigned to team members.\n\nYour skills and experience\n- Management experience of a 6+ team.\n- Management experience of 6+ years.\n- Be able to manage international teams \n- Be able to work flexible working hours\n- Experience with team collaboration frameworks like Agile.\n- Fluency in Java and the related ecosystem.\n- Strong experience with object-oriented development.\n- Strong experience with design patterns, programming principles.\n- Strong experience with Spring framework, Hibernate.\n- Strong experience with multi-threaded, network programming.\n- Experience with modern Web programming.\n- Experience with modern APIs, SDKs.\n- Experience with Linux bash, Powershell.\n- Experience with analyzing and designing system architectures.\n- Knowledge with virtualization and cloud computing.\n- Able to write component, module, cleaned and well tested code.\n- Able to follow existing code standards and set new.\n- Able to use SVN and Git.\n- At least 5 years of experience in a relevant position.\n- Upper-intermediate in English (or higher level)\n\nGiven the high volume of CVs applied, we can only manage to respond to candidates whose profiles aligns with the position within 5 working days. We appreciate your understanding and enthusiasm towards our company.\n\nWhy you\'ll love working here\nThe Nakivo team in Vietnam has been changing very fast in the recent years, we have grown from a group of 6 engineers to the current team size of 80 and we are expecting to grow even more in the next following years.\nWe welcome and embrace people, regardless of their background, religion, nationality or gender, but focus on diversity, contribution, determination and work ethic. At Nakivo, we are trying to improve every day, to become a competitive choice for talented people, by offering\n- Flexible working hours: Office opens from 6.00 AM to 10.00 PM\n- 13-month bonus & performance bonus\n- 100% salary on probationary period\n- Private health care package\n- Healthcare package for family members\n- Premium health care check\n- Gift (cash/voucher) for every special occasion: New Year\'s Eve, Tet holidays, International Women\'s Day, International Children\'s Day, Mid-Autumn Festival and Birthday\n- 15-18 annual leaves/year, 5 sick leaves and additional leaves (up to 3 days)\n- Team building\n- Free and un-limited snack, tea, coffee and by-choice request.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '16 Le Quy Don, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(357, 275, 2, 'Automation Tester (QA QC/ Tester)', 'Our Testers work with project teams to ensure software quality through systematic test planning, execution, and defect tracking, ensuring functionality, performance, and reliability of applications before deployment. With deep knowledge of various types of applications, databases, and operating systems, they maintain high standards of product excellence and user satisfaction. \n\nAs a Tester (Automation) at Endava, you will be in charge of building, developing, and implementing automated tests to assure the quality of our software applications. You will take part in specific projects and work directly with our global stakeholders. \n\nResponsibilities:\n- Analyzing users stories, use cases and requirements.\n- Collaborate closely with other team members and departments to define the test cases.\n- Execute all levels of testing.\n- Design, develop, maintain and extend automation scripts using various frameworks and programming languages.\n- Detect and track software defects and inconsistencies.\n- Apply quality engineering principles throughout the Agile product life cycle.\n- Provide support and documentation.\n\nYour skills and experience:\n- 3+ years of experience working in automation testing in overall 4+ working in testing experience.\n- Experience in building automation testing frameworks from scratch.\n- Automation testing experience in both front-end and back-end.\n- Deeply understanding about testing concept and having coding experience with one of languages (Java, Javascript, Python, C#).\n- Experience in Web Services/API automated testing.\n- Experience with REST testing tools.\n\nWould be a plus with:\n- Good knowledge of BDD.\n- Good knowledge in SQL.\n- Knowledge with Azure/AWS DevOps pipelines to set up automated builds and enable CI/CD.\n\nWhy you\'ll love working here:\nAt Endava, we are offering opportunities and exciting development for our people to build an engaging technical community. \nCareer coaching, learning and development: \n- Certifications, soft skills, training licenses.\n- Endava Digital Library and tech conferences. \nCulture and work environment: \n- Company-sponsored team-based sports, hobby clubs, tech & social communities. \n\nSome of our benefits:\n- Finance: Competitive salary package, annual leave encashment, 13th month salary, referral bonus; \n- Career Development: Career coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership;\n- Learning Opportunities: Complex projects, rotations, internal tech communities, training, coaching, online learning platforms subscriptions, English programme, certifications, pass-it-on sessions, workshops, conferences;\n- Work-Life Balance: Hybrid work and flexible working hours, employee assistance programme;\n- Health: Global internal wellbeing programme, access to wellbeing apps, premium health check, extra insurance;\n- Community: Global internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations;\n- Other: Trade Union benefits, Welcome package and gift-giving frequency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '9-11 Dong Da street, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(358, 237, 2, 'NodeJS Developer (JavaScript, CSS, React JS)', 'Job description\n- Tham gia lập trình, vận hành, tối ưu các sản phẩm của công ty.\n- Tối ưu hóa hiệu suất và bảo mật của các ứng dụng Web.\n- Xác định và giải quyết các vấn đề liên quan đến ứng dụng Web.\n- Tham gia vào các quá trình kiểm soát chất lượng cho sản phẩm.\n- Các công việc khác theo sự phân công của Quản lý trực tiếp.\n- Chi tiết trao đổi qua cuộc phỏng vấn.\n\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin, hoặc tương đương\n- Kinh nghiệm: từ 2 năm ở vị trí tương đương.\n- Thành thạo quy trình phát triển phần mềm, từ tiếp nhận yêu cầu, lựa chọn công cụ, ngôn ngữ, thiết kế CSDL, xây dựng frontend, backend, triển khai lên hệ thống server thật.\n- Thành thạo ngôn ngữ lập trình Javascript, CSS, HTML và một framework xây dựng frontend như ReactJS hoặc Angular, biết cách xây dựng website responsive chạy trên mobile.\n- Thành thạo một framework xây dựng backend như NodeJS Express, ngôn ngữ SQL, biết cách sử dụng ORM và vận hành hệ quản trị CSDL như MySQL hoặc Postgres.\n- Biết sử dụng các API và thiết kế API để tương tác với các dịch vụ của khách hàng.\n- Biết đọc tài liệu bằng tiếng anh.\n- Biết phát triển ứng dụng mobile (ReactNative) là một lợi thế.\n- Kỹ năng làm việc độc lập và làm việc nhóm tốt để giải quyết các vấn đề liên quan đến sản phẩm.\n\nWhy you\'ll love working here\n- Mức lương: thỏa thuận\n- Phụ cấp ăn trưa.\n- Được hưởng các chế độ BHXH, BHYT, BHTN và các phúc lợi khác theo quy định của Luật lao động và của Công ty.\n- Được đi du lịch và tham gia các hoạt động vui chơi, giải trí khác do công ty tổ chức hàng hàng năm.\n- Được đào tạo bài bản, chuyên sâu nâng cao nghiệp vụ chuyên môn và kỹ năng mềm.\n- Được làm việc trong môi trường chuyên nghiệp, năng động, sáng tạo.\n- Thời gian làm việc: Từ thứ 2 đến hết sáng thứ 7, nghỉ chiều thứ Bảy và các ngày Chủ nhật.\n  + Sáng: từ 8h30 – 12h00.\n  + Chiều: từ 13h30 – 18h00.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, tòa nhà SanNam, 78 Duy Tân,, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(359, 303, 2, 'Senior Automation Quality Engineer', 'We are looking for a detail-oriented and proactive Automation Quality Engineer to join our team. You will play a key role in building and maintaining automated test frameworks, identifying issues early in the development lifecycle, and ensuring the delivery of high-quality software. This role is ideal for someone passionate about test automation, continuous improvement, and collaborating with cross-functional teams. This is a great opportunity to work on Web and Mobile applications.\n\nResponsibilities:\n1. Design, develop, and maintain a robust automation framework for web and mobile applications.\n2. Analyze test results and provide feedback for improving software quality.\n3. Collaborate with stakeholders and engineers to understand requirements and participate in Agile/Scrum (sprint planning, stand-ups, retrospectives).\n4. Integrate automated tests into CI/CD pipelines to ensure fast and reliable feedback.\n5. Identify, report, and track bugs in a clear and organized manner using test management and issue tracking tools.\n\nYour skills and experience:\n- 4+ years of experience in automation testing for mobile and web applications.\n- Proven experience in developing and maintaining an automation framework from scratch.\n- Experience with CI/CD pipelines and version control (e.g., Git, Jenkins).\n- Familiarity with native and Flutter mobile apps and web frontend/backend systems.\n- Experience with bug tracking and test case management tools (e.g., Jira, TestRail).\n- Solid problem-solving skills and attention to detail.\n- Exposure to embedded systems testing is a plus.\n- Good written and verbal English communication skills.\n- Bachelor’s degree in Computer Engineering, or related fields.\n\nWhy you\'ll love working here:\nWe’ve worked hard to build the workplace culture we’ve always dreamed of - one where we celebrate each other\'s successes, work hard together, and know when it’s time to relax. We know that we can’t reach our goals alone, and think that our culture makes it a little easier to come to work and makes our biggest goals achievable. At FuelCloud, you’ll be using cutting-edge technology and taking on interesting challenges every day with a team that is genuinely happy to have you!\n\nBenefits:\n- Attractive salary (Full salary during probationary period)\n- 13th month - salary\n- Provide Laptop & Screens for working\n- Ability to travel to US\n- Working with expat team\n- Premium health care insurance for you and your family\n- Free annual health check\n- 15 days of PTO and no working OT\n- Company trip & team dinners\n- Many team activities: Birthday party, Mid-Autumn Festival, Christmas, Year End party,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No 22, B2 Street, Sala Urban Residence, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(360, 304, 2, 'Mobile Developer (Android, Kotlin, React Native)', 'Job description\n- Lập trình viên android lập trình bằng Kotlin.\n- Tham gia xây dựng, nâng cấp và sửa lỗi cho các ứng dụng đã có.\n- Phối hợp với team thiết kế, backend và tester để hoàn thiện sản phẩm.\n\nYour skills and experience\n- Tối thiểu 1 năm phát triển Android với Kotlin.\n- Năm sinh: từ 20Bắt buộc: Có sản phẩm mẫu thực tế đã được xuất bản trên Google Play (vui lòng đính kèm link).\n- Học đúng chuyên ngành Công nghệ thông tin của các trường đại học: Bách Khoa, Bưu chính viễn thông, Học viện Kỹ thuật mật mã, Học viện Kỹ thuật quân sự, Đại học Công nghiệp Hà Nội,...\n- Ưu tiên :Có kinh nghiệm tích hợp Google AdMob, làm việc với đa nền tảng hoặc có thêm kỹ năng React Native.\n- Tư duy code sạch, tối ưu hiệu năng, có kiến thức cơ bản về UX/UI.\n- Nhanh nhẹn, chịu khó, có trách nhiệm với sản phẩm và cam kết hoàn thành deadline.\n- Biết làm việc nhóm, chủ động học hỏi và cập nhật công nghệ.\n\nWhy you\'ll love working here\n- Lương cứng: 10 – 25 triệu/tháng tùy theo năng lực thực tế.\n- Thử việc 2 tháng 85% lương (có thể nhanh hơn nếu thể hiện tốt)!\n- Thưởng theo % doanh thu sản phẩm. - Thưởng lễ, Tết, du lịch hằng năm.\n- Thưởng lương tháng thứ 13.\n- Review lương định kì 2 lần /1 năm hoặc theo đóng góp!\n- Đóng BHXH theo quy định nhà nước sau khi lên chính thức .\n- Môi trường làm việc: Được tiếp cận và thực chiến với nhiều dự án thật, giúp tăng cường khả năng xử lý tình huống và phát triển chuyên môn.\n- Cơ hội học hỏi và phát triển kiến thức kĩ năng thông qua các buổi đào tạo nội bộ.\n- Môi trường Startup trẻ năng động, phẳng về cấp bậc, khuyến khích sáng tạo và phát triển ý tưởng.\n- Thời gian làm việc: Sáng 9h-12h, chiều 14h-18h (Từ thứ 2 - thứ 6; nghỉ T7, CN và các ngày lễ Tết).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'So A6, Khu nha 252 duong Luong The Vinh, Phuong Trung Van, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(361, 184, 2, 'Senior/Junior, Application Operator', '1. Mô tả công việc:\nChịu trách nhiệm quản lý vận hành các ứng dụng and dịch vụ tổng thể bao gồm nhưng không giới hạn Corebanking, FMB, Thẻ, các kênh thanh toán, Contact Center… đáp ứng nhu cầu và yêu cầu kinh doanh của Ngân hàng.\nĐảm bảo liên tục thông qua quy trình vận hành ứng dụng\n- Tham gia trực tiếp vào việc thực hiện các thay đổi và báo cáo cho các bên liên quan tại các mốc quan trọng\n- Triển khai các công cụ, thay đổi nhằm đơn giản hóa, tự động hóa, tập trung hóa hoạt động của hệ thống.\n- Làm việc với các bên liên quan để tăng cường quy trình và chất lượng phân phối đồng thời giảm thiểu các nguồn lực cần thiết.\nVận hành ứng dụng\n- Trực tiếp thực hiện các hạng mục liên quan trong lộ trình đã đề ra và đảm bảo tuân thủ các mốc thời gian và điểm kiểm tra thích hợp.\n- Dự án hỗ trợ và tiếp quản\n- Triển khai và quản lý các yêu cầu Thay đổi để giảm thiểu tác động đến hoạt động của hệ thống\n2. Mục tiêu hoạt động ứng dụng\n- Chịu trách nhiệm vận hành ứng dụng và hỗ trợ kỹ thuật, bao gồm triển khai và bảo trì ứng dụng hàng ngày, quản lý vấn đề và sự cố\n- Kiểm tra hệ thống thường xuyên (Kiểm tra nhanh, kiểm tra sức khỏe)\n- Hỗ trợ các vấn đề kỹ thuật L2\n- Giám sát các hệ thống chính về sự bất thường\n- Hỗ trợ giải quyết các khoảng trống và rủi ro PCI DSS\n- Thực hiện xử lý hàng loạt EOD nếu dịch vụ cụ thể yêu cầu\n- Các nhiệm vụ bảo trì hiệu suất cho hệ thống CNTT (lưu trữ, sao lưu, gia hạn hợp đồng hỗ trợ / bảo trì ...)\nYour skills and experience\n- Tối thiểu 5 năm kinh nghiệm liên quan trong phát triển phần mềm và tối thiểu 2 đến 3 năm kinh nghiệm trong việc vận hành ứng dụng\n- Ưu tiên ứng viên có Kiến thức làm việc về DevOps, Kubernetes và Container\n- Kiến thức làm việc về Tự động hóa trong vận hành, playbook (ví dụ: Ansible, jenkins ...)\n- Cần có kinh nghiệm làm việc với môi trường cloud\n- Kinh nghiệm thực hành về vận hành Ứng dụng và hỗ trợ kỹ thuật\n- Có kinh nghiệm làm việc với các công cụ vận hành ứng dụng là (AM, Grafana, Dynatrace, AppDynamics, Datadog, EFK ...).\n- Hiểu các nguyên tắc, thực hành Agile và các phương pháp luận Scrum để vận hành ứng dụng\n- Có kinh nghiệm làm việc trong các nhóm Agile để hỗ trợ các dự án đưa vào hoạt động trong JIRA và Confluence\nWhy you\'ll love working here\nWHY BECOME IT/DATA EXPERTS AT TECHCOMBANK?\nInvesting over 500 million USD to develop large-scale IT projects, Techcombank is one of the leading bank in Technology trends in Vietnam\nYou will grow with Techcombank by having the opportunity to learn from top experts from across the world\nTechcombank provides a rewarding remuneration structure that commensurate with your achievement and contribution\nTechcombank is the Top 2 Best place to work in the banking industry where you can experience various exciting activities throughout the year: Company anniversary, Team building, Active Saturday , Year End Party, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'C5 Building Tower, D’Capitale Tower, 119 Tran Duy Hung, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(362, 305, 2, 'Technical Art Lead', 'Summary: Technical Artist will develop and maintain robust art pipelines, custom tools, shaders, and visual effects for ultra-realistic Next-Gen and premium cartoon AAA game projects for our clients, fully optimized for Unreal/Unity. They’ll ensure service excellence through proactive client communication, rigorous version control, and AI-enhanced automation, guaranteeing on-time, on-budget delivery at AAA standards.\n\nJob Description:\n\nEngine Integration:\n- Involved in early project set-up with stakeholders such as kick-off, testing and documentation.\n- Collaborate with client, IT team, Tech Dept, Production teams during projects’ timeline to tackle any tech related issues.\n- Be the bridge and main point of contact between art production and clients on any technical concerns.\n- Exploring new technologies and doing necessary training for the team. (AI etc..)\n- Contribute ideas, tools, workflow for Tech Dept and Production teams.\n- Create clear and accurate technical documentation, training sessions or tools for production teams to increase production efficiency.\n\nVFX Optimization:\n- Optimize VFX for mobile/console/PC with GPU budget, LODs, shader variants.\n- Lead VFX pipeline, create modular systems, mentor team, and collaborate with TechArt and Design.\n- Apply AI upscalers, remeshing, or auto UV tools to support workflow, integrate AI into modeling/texturing, and customize AI tools Level 34. Design and maintain AI enhanced pipelines and collaborate with ML/TechArt for tool development.\n\nOther:\n- Develop and maintain art pipelines and workflows.\n- Create custom tools and scripts to automate art tasks.\n- Optimize game performance by reducing draw calls, memory usage, and other bottlenecks.\n- Mentor and train other artists on technical art skills.\n- Troubleshoot technical issues related to art assets.\n\nYour skills and experience:\n- A minimum of 5 years of experience in 3D art or video game industry.\n- Familiarity with digital content creation software like Maya, Blender, Substance Painter, ...\n- Familiarity with at least 1 programming language or shader language or visual programming.\n- Understanding of physically based rendering (PBR), lighting and shading.\n- Good verbal and written communication skills in English, able to clearly communicate ideas and technical knowledge.\n- Independent, pro-active, showing initiative.\n- Game engine experience, e.g., Unreal, Unity.\n- Scripting APIs of 3D software like Maya, Mari, ZBrush, Substance Painter.\n\nWhy you\'ll love working here:\n- Working with top talents/Artist from top game developers in Vietnam.\n- Opportunity to collaborate and contribute to 2A-3A Game titles.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Z06 Đường số 13, Phường Tân Thuận Đông, Quận 7, Thành phố Hồ Chí Minh, Việt Nam, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(363, 306, 2, 'Technical Business Analyst (Technical Product Owner)', 'GKIM is looking for smart and tech-savvy English speakers to work with us and our clients, turning business requirements and user insights into delightful user experiences and digital money-making machines for our clients.\n\nIn this role, you need to demonstrate experience and creativity in system development and application design. You\'ll work with our CEO, our clients, our UI/UX designers, our product managers and our development team.\n\nIf you are interested in and can prove your experience in technical business analysis or related roles and exceptional communication skills, do get in touch.\n\nResponsible:\n- Act as the bridge between the product owner, clients and offshore to clarify requirements and develop the technical documents for the development team (developers, testers, UI designer) and facilitate communication among internal team members\n- Develop data models base on the business requirements\n- Performing system analyzes on software programs, applications, and web services.\n- Efficiently integrating new systems, programs, and applications with business operations and services.\n- Monitoring product licenses and ensuring compliance with IT industry regulations.\n\nYour skills and experience:\nSkills required:\n- A bachelor\'s degree in computer science or information technology, and an accredited qualification in management consultancy, or similar.\n- 3+ years of experience with extensive experience in technical business analysis in a related industry.\n- Advanced knowledge of programming languages like SQL and system integration solutions. With a preference for backend experience to analyze data models for product design and task documentation.\n- Ability to design and maintain efficient customer portal support and feedback channels.\n- Ensuring optimal system functionality via integrated diagnostics.\n- Exceptional communication skills toward facilitating the user of new software systems.\n- Knowledge of relevant licensing and industry compliance regulations.\n- Excellent in English\n- Technical writing skills and process modeling: proficient in writing/drawing diagrams, creating technical documents.\n- Experience in data analysis to leverage insights for feature suggestions, improvements, and product ideation debates.\n- Experience in business domains such as healthcare preferred.\n- Strong negotiation skills for roadmap planning, conflict resolution, decision-making, presentations, and persuasion.\n- Ability to work on estimates and propose budgets with development team for a development requirement.\n\nWhy you\'ll love working here:\nEMPLOYEES BENEFITS \n● Competitive salary based on skills and ability \n● Semi-annual reviews, annual salary increases, and salary increments upon achieving team/company KPIs \n● Year-end bonus, 13th and 14th month salary, and additional bonuses \n● Social insurance, health insurance, unemployment insurance, and Bao Viet Insurance \n● Company trips, regular team-building and dining events \n● We have a beautiful office with a lounge serving  juice & coffee all day.\n● Weekly workshops for learning and sharing \n● Numerous celebrations: Happy Hour, March 8th, company birthday, June 1st, Mid-Autumn Festival, October 20th, Christmas, Year-end party, and New Year party \n● Personal development programs and well-planned career paths', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sarina 1C Apartment , An Loi Dong Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(364, 225, 2, 'QA Engineer (QA QC, Tester)', 'By applying for the above position, you accept and agree that your personal data and any information stated in the attached curriculum vitae (CV) will be used and processed by ITViec and NAB Vietnam for recruitment purposes. The storage and processing of such information will comply with the applicable laws of Vietnam, and the policies and procedures of ITViec and NAB Vietnam regarding personal data, as amended from time to time.\n\nABOUT THE JOB\nWe\'re seeking experienced and talented automation testing engineers to work on our flagship platform that serves millions of customers daily. You will join our Agile Engineering team and manage the automation testing for the team while coaching them to have a quality mindset. You will be part of our committed Quality community, passionate about delivering a high-quality experience for our customers. To be successful, you will need to demonstrate expertise in test automation and have a solid understanding of the testing methodology.\n\nLocation: Ho Chi Minh & Hanoi (hybrid working, 2 day office/week)\n\nLevel: Junior, Medior, Senior & Lead\n\nWhat will you be responsible for?\n- Implement shift-left testing, automation first to test early and often\n- Code automated tests during build and regression test phases and integrate into the CI/CD pipeline\n- Create test plans, execute test cases, and prepare test summary reports for features built-in your team\n- Review solution documentation, and assist with the analysis, testing, and resolution of issues\n- Support defining the user story acceptance criteria and ensuring stories meet the high level of quality\n- Influence your team to think of Quality first, conduct training to empower developers to a level of sufficient testing skills\n\nYour skills and experience\nMust-have skills:\n- Typically have 3+ years in a software testing (both in manual and automation testing) role with at least 1.5 years of automation experience in Web and API testing.\n- Good English communication skills (both verbal & written)\n- Solid knowledge of testing methodologies covering test levels, static test, and dynamic testing.\n- Manage/ deliver test execution for the new features in different testing life cycles.\n- Strong at using testing frameworks and tools, at least one or more from this list: Selenium Webdriver automation framework (Java), Cypress (Javascript/ Typescript), Automation framework.\n- Experienced in implementing/ maintaining automation test scripts. Develop/ improve existing automation framework.\n- The technologies we use in our Quality practices are below. We don’t expect you to know all of them, but having experience with a large number of technologies is ideal:\n   - Experience with Java or Javascript/Typescript programming (or similar languages)\n   - QTest, JIRA, Confluence\n   - PACT, Postman, SoapUI, REST, TestNG, Selenium, Cypress, Appium, Espresso,…\n- Be able to carry testing independently in a cross-functional team following Agile process.\n- Ability to work in a dynamic and continuously changing environment.\n- Ability to coach and motivate developers to ensure their features are of high test-ability.\n\nNice-to-have\n- ISTQB – Certified\n- Experience in the Banking or Financial Services industry\n- Exposure to AWS and cloud-native architecture\n- Performance: JMeter, LoadRunner, Gatling\n- Experienced testing on a Microservice-based system (Restful API, Event/ Message driven, Logging)\n- Familiar with CI/CD process and tools: Jenkins, Docker, AWS, Azure,…\n\nWhy you\'ll love working here\n1. Generous compensation and benefit package\n   - Attractive salary and benefits\n   - 20-day annual leave and 7-day sick leave, etc.\n   - 13th month salary and Annual Performance Bonus\n   - Premium healthcare for yourself and family members\n\n2. Exciting career and development opportunities\n   - Large scale products with modern technologies in banking domain\n   - Clear roadmap for career advancement in both technical and leadership pathways\n   - Sponsored certificates in both IT and banking/finance\n   - Premium accounts on Udemy/A Cloud Guru/Coursera/LinkedIn, etc.\n   - English learning with native teachers\n\n3. Professional and engaging working environment\n   - Hybrid working model and excellent work-life balance\n   - Well-equipped & modern Agile office with fully-stocked pantry\n   - Annual company trip and events\n\nA DIVERSE AND INCLUSIVE WORKPLACE WORKS BETTER FOR EVERYONE\nNAB is a place where colleagues of all genders, sexualities and ages, carers and colleagues with disability, and colleagues from all cultures, races and religions have the opportunity to thrive, connect and grow.\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh & Hanoi (hybrid working, 2 day office/week)', 'Full-time', '2025-10-07 20:59:18.149534'),
	(365, 307, 2, 'Embedded AI Engineer (C Language/C++/Linux/Embedded C)', 'Job description\n- Design and implement sophisticated scalable multi-threaded Object Oriented Software in C++ for solving challenging problems involving high speed data processing and networking.\n- Design advanced software modules that follow modern C++ design patterns.\n- Apply C programming skills for Linux device driver development and debugging.\n- Apply problem solving skills and experience to identify and improve low-level system performance issues.\n- Apply engineering principles to design algorithms for controlling image acquisition parameters, as well as environmental conditions (Temperature, Power, Fog, Frost, etc.).\n- Create design documents on software architecture and algorithms.\n- Collaborate with Hardware designers on board bring-up and debug.\n- Maintain and improve Firmware build system using Make and Python.\n- Collaborate with Quality Assurance team on identifying test cases for new features and areas for regression tests.\n- Follow the established development process for all design and implementation tasks.\n\nYour skills and experience\n- Bachelor / Master degree in Computer Engineering, Software Engineering. Having a EE background is a plus.\n- Experience in writing quality C or Modern C++ on Linux OS based embedded systems. Experience in Rust is a plus.\n- Experience in the Linux build system. Familiarity with Yocto is a plus.\n- Knowledge in writing low-level programming for HW peripherals and drivers.\n- Knowledge on networking protocols / connectivity, such as Wifi, Bluetooth, used with embedded systems.\n- Knowledge in camera linux embedded systems is a plus.\n- Good written English and oral communication skills.\n- Desire to learn.\n- A team player.\n\nWhy you\'ll love working here\n- Compensation & bonus: 13th & 14th salary, AIP bonus, Holidays, Tet, and Long year service …\n- Social insurance, Health insurance, Unemployment insurance: by Social Insurance and Labor Law.\n- The regime of annual leave, company trip, and checkup examination.\n- Award for marriage, newborn.\n- We have AON insurance package for employee, spouse, and children every year.\n- You will be trained, learned & work with the best technical managers who help you improve various dev skills & career path.\n- You’ll love working in our dynamic environment employees, young & active.\n- We love sport activities, as marathon, football, swimming....\n- Working time: From Monday to Friday | 08:30-12:00 & 13:00-17.30.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'L07.01, Tầng 07, Tháp A, Khu thương mại dịch vụ kết hợp nhà ở cao tầng tại lô đất 1-13, thuộc khu chức năng số 1 – Số 15, đường Trần Bạch Đằng, Phường Thủ Thiêm, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(366, 308, 2, 'Sr Fullstack Developer (TypeScript + ReactJS, NodeJS)', 'Job Description We are looking for a Senior Fullstack Developer (with strong expertise in BackEnd Java) to take a leading role in building scalable, high-performance web applications and REST API services. You will work across the full development lifecycle, mentor junior developers, and contribute to architectural decisions and product strategy.  Key Responsibilities We\'re looking for an experienced senior Java to join us. You will have opportunities to improve your skills and contribute to develop new and exciting solutions to our products. The applicant must show ability to work productively both independently and in a team environment. Automate ETL pipelines and ML workflow Your skills and experience Requirements – Must Have At least 4 years experience in Java Good knowledge of key Open source technologies, such as: Spring-boot, Spring, Hibernate, Jetty, Jackson, JUnit, Apache Commons and SLF4J Experience in the development of larger Java solutions Be an efficient and quality-oriented person with experience from project based on agile methods like Kanban and Scrum Experience with ORM technologies like JPA and Hibernate, are comfortable with the JDBC / SQL and database systems such as POSTGRESQL, MYSQL Experience with NoSQL (Redis, Cassandra, Hbase, MongoDB, ...). Experience with application servers like Jetty and Tomcat, and know to Web services and integrations based on SOAP and REST Good knowledge of solutions related to construction and integration Maven, Team City, and Jenkins/Hudson Requirements – Nice to Have Plus: experience in BigData Architect (Hadoop, Kafka, Spark). Why you\'ll love working here Inside our engineering team: We iterate constantly. There\'s no such thing as the best version of anything, just a constant streams of improvements and tests. We move fast, really fast. Major changes can be executed in a few days, many times just a few hours. We have a data-informed mindset. We try to use data to inform our decision as much as possible. We are independent. Most of the time, your team will not need technical assistance from other teams. We take risks. We\'re not afraid to challenge "best practices". Our attractive offers include: Open communication with passionate and experienced members. Challenging working environment. Social insurance, unemployment insurance under the Insurance Law Internal events to bond our mutual understanding & spirit such as team building, team outing, Citic\'s birthday, Year-end party... Generous special Employee Stock Ownership Plan (ESOP), which is approved by the Board of Director. 40 flexible working hours per week from Monday to Friday. Young, dynamic working environment with strong startup culture. Training and career development opportunities. Company team building, annual Birthday party and other events: New Year, X-mas, Mid Autum Festival,… Support fee for parking, marriages, child births, hospitalization. Sport clubs (Running, Badminton, Soccer).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lakeview 1, An Khanh Ward, District 2, HCMC, District 2, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(367, 309, 2, 'Senior Solution Architect & Tech Director (Web, AI)', 'Verticurl, a division of , was established in 2006 with the mission to be the world’s leading marketing technology services agency for multinational organizations. We enable our clients to assess, deploy and integrate MarTech platforms, activate customer experience technologies, implement lead management processes that accelerate revenue conversion and leverage marketing technology to achieve operational excellence. For more information, please visit the website:\n\nWe are seeking a talented and experienced Senior Solution Architect to join our Creative Technology Hub, with a focus on modern web and mobile technologies, enhanced by creative tech and emerging innovations such as AR, VR, Web3, AI, and Machine Learning.\n\nIn this role, you will play a pivotal part in designing and delivering innovative, future-ready solutions that leverage these technologies to meet our clients’ evolving needs. You will work closely with cross-functional teams to define scalable, robust, and flexible architectures.\n\nYour deep expertise in architectural principles, cloud solutions, DevOps practices, and cutting-edge technologies will be instrumental in shaping the technical direction of our projects and providing strong leadership across our development teams.\n\nResponsibilities\n\nArchitectural Design: Collaborate with cross-functional teams to design and develop scalable and efficient Web, Mobile solutions with AR, VR, AI, Web3, and Machine Learning. Apply your deep understanding of these technologies to create architectures that align with project requirements and business objectives.\n\nTechnical Leadership: Provide technical guidance and leadership to the development team, ensuring best practices and architectural standards are followed. Serve as a subject matter expert, staying up-to-date with the latest trends, tools, and frameworks in the creative technology space.\n\nSolution Development: Work closely with clients and internal stakeholders to identify business needs and translate them into technical requirements. Lead the development of prototypes, proof of concepts, and production-ready Web, Mobile solutions using emerging technology.\n\nCollaboration: Collaborate with other Solution Architects, Software Engineers, Designers, and Project Managers to ensure seamless integration of creative technology solutions within larger projects. Foster a collaborative and innovative environment, promoting knowledge sharing and continuous learning.\n\nEvaluation and Optimization: Evaluate existing systems and technologies, identifying areas for improvement and optimization. Provide recommendations for enhancements, architectural changes, or technology adoption to enhance overall solution quality and performance.\n\nPeople Management: Lead and mentor a team of developers and technologists. Support their professional growth through coaching, performance feedback, and career development planning. Create an inclusive and motivating environment that drives high performance and team cohesion.\n\nYour skills and experience\n\nQualification:\n\nBachelor\'s or Master\'s degree in Computer Science, Engineering, or a related field.\nProven experience as a Solution Architect, Technical Architect, Cloud Architect or similar role, with a focus on Web, Mobile with creative technologies such as AR, VR, AI, and Machine Learning.\nStrong understanding of architectural principles, design patterns, and best practices in software development. Can provide solutions for high performance and scalability architecture.\nIn-depth knowledge of AR/VR platforms (e.g., Unity, Unreal Engine), AI frameworks (e.g., TensorFlow, PyTorch), and machine learning algorithms.\nExperience in designing and implementing end-to-end solutions, from requirements gathering to deployment and maintenance.\nExcellent problem-solving skills and the ability to translate business requirements into technical solutions.\nStrong communication and interpersonal skills to effectively collaborate with multidisciplinary teams and communicate technical concepts to non-technical stakeholders.\nHave experience with any Tech stack/language/framework (JavaScript, TypeScript, ReactJS, Angular, VueJS, HTML5 / CSS 3, SASS/LESS), Mobile (iOS, Android, React Native, Flutter), Backend (NodeJS, Java, Go, PHP, Python, .Net Core), Database (MySQL, MSSQL, PostgreSQL, MongoDB, Cassandra), Web Server (Nginx, Apache).\nHave Strong solutioning experience with any of Cloud solutions: Azure, GCP or AWS.\nExcellent understanding of DevOps/CloudOps and building high-availability infrastructure.\nLeadership that combines persuasiveness, decisiveness, and competitiveness is necessary to motivate a team.\nExcellent communication skills in English.\n\nWhy you\'ll love working here\n\nOpportunities to join a fast-growing global organization that specializes in MarTech.\nFlexibility to show off your MarTech muscle and sharpen your digital marketing technology skills.\nRecognition and appreciation for hard work, smart thinking, and expertise.\nAttractive salary and benefits.\nPremium health and accidental insurance package; health check-up every year.\n20 Annual Leaves per year and birthday leave is applied.\nCompany trip, team building and exciting annual year-end party.\nHigh-tech laptop and other facilities will be provided by company.\nFlexible working hours and place. Hybrid working is applied.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '72 Nguyen Thi Minh Khai, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(368, 214, 2, 'Software Engineer (C++, Embedded Linux)', 'Top 3 reasons to join us\n1. Competitive salary & up-to 16-month income / year\n2. Attractive allowances & benefits\n3. Flexible working time with many company holidays\n\nJob description\nFollowing research centers in Korea, USA, Russia, India, etc. LG CTO Vietnam Software Lab (LG CTO VSL) officially operated in Vietnam from July 2022 with the mission of developing next generations of technology and incubating new LG business in the future. You will have the opportunity to work, share and learn with talented engineers at CTO centers in countries around the world and launch strategic-oriented technology products of LG Corporation.\n\nRoles & responsibilities:\nAs a Software Engineer in LG CTO VSL, your roles & responsibilities will be one of team as follows:\n\n1.System Core Engineer:\n- Develop and maintain the native daemons / services\n- Code review using Gerrit & GitHub\n- Regularly discuss with remote teams on task planning and feedbacks exchange\n\n2.Graphic Engineer:\n- Work in Scrum teams for developing Graphic Framework including Qt compositor for webOS\n- Triage problems, prioritize accordingly and propose a solution\n- Defect review and track with other team members\n- Communicate with developers and stakeholders in headquarter (Korea) regularly\n\nYour skills and experience\nQualifications:\n- Bachelor\'s degree in computer science / engineering or equivalent practical experience\n- 5+ years of working experience in embedded linux environment\n- 3+ years of working experience with the C++ programming language\n- Preferred Experiences: Graphics, EGL, Wayland, webOS, unit test\n- Good communication skill in English, mostly for the technical communication with the collaborating scrum teams\n\nPreferred Qualifications:\n- Embedded Linux Developers on the Yocto Build System\n- DBus knowledge\n- Linux (native) daemon development experience using C++, CMake\n- Glib experience, especially functions related to g_main_loop (event loop)\n\nWhy you\'ll love working here\n1. 13th month salary + Incentive bonus (Total remuneration package / year: up to 16-month salary) + Annual salary review; 100% probation salary\n2. HYBRID WORKING, flexible working time (Mon - Fri)\n3. Support for lunch, transportation and other allowances (Coding Expert, Technical leader, phone...);\n4. Premium health care & accident insurance;\n5. Total 20 paid leaves/year;\n6. Support fee to get TOEIC & technical certifications (ISTQB, Agile Scrum...);\n7. On-site & training opportunities abroad;\n8. Company trip, sport clubs (zumba, football, pingpong, badminton,...);\n9. Monthly budget for team activities, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 17 đến tầng 21, Tòa văn phòng, Lotte Mall Hà Nội, Số 272 Võ Chí Công, Phường Phú Thượng, Quận Tây Hồ, Thành phố Hà Nội, Tay Ho, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(369, 310, 2, 'Outsystems Solution Architect', 'We are currently hiring an Outsystems Systems Architect to join the Product Development team. If you love building high-impact products that touch the lives and stomachs of millions of users, working alongside a talented, world-class team, we want to hear from you.\nThe Outsystems Systems Architect is responsible for analyzing and understanding high-level requirements, solutioning, developing, simulation and integration. This role focuses on bridging the gap between business goals and technical implementation, ensuring that all components of a system work together seamlessly. The Systems Architect works closely with product managers, developers, and other stakeholders to define and implement the strategy for our products.\n\nResponsibilities\nLead the design and architecture of Enterprise Outsystems Applications, implementing a comprehensive solution, focusing on scalability, security, and performance.\nDevelop high-quality Outsystems applications and maintaining detailed technical documentation, including configuration, deployment and maintenance strategies.\nManage integration points between OutSystems and existing systems, ensuring smooth data flow and operational efficiency.\nProvide technical guidance and mentorship to development teams, performing code reviews and ensuring adherence to OutSystems best practices and architectural patterns.\nWork with stakeholders to convert business requirements to technical specifications and present solutions clearly.\nImplement robust security measures to safeguard data and ensure compliance with industry standards.\n\nYour skills and experience\nA degree in IT / Computer Science with 5+ years of hands-on Outsystems experience.\nStrong architectural and design skills.\nStrong in Outsystems Platform knowledge.\nExperience in code reviews and adherence to coding standards.\nExperience in integrating with other cloud solutions.\nExcellent communication in English with strong leadership abilities.\n\nWe accept working from Ho Chi Minh City and Hanoi[Work from home]\n\nWhy you\'ll love working here\nWe provide our staff with:\n- Very attractive salaries that commensurate with work experience.\n- Have a chance to develop your career and access new IT technologies\n- Be able to have business trips in Singapore and meet strategic partnerships\n- Be supported and work with experienced and friendly members.\n- Professional and nice work environment.\n- Work from home.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(370, 214, 2, 'Automation Test Engineer (Tester, Python, English)', 'LG Electronics Development Vietnam (LGEDV) produces high-quality in-car infotainment systems that deliver both information and entertainment on-the-go for many of the world‘s biggest automobile brands. LGEDV conducts core R&D activities, and various product reliability tests in support of our vehicle component business.\n\nWith the key missions of offering an environment that enables colleagues to demonstrate their capabilities, focus on their work and create value & delivering the “invaluable” office operation services & solutions that contributes to a company’s business success.\n\nAs member of Automation Test Team, you will be responsible for testing software for Automotive domain as below:\n- Analyze software project requirements in Automotive (Telematics, AVN, Cluster);\n- Create/update test scripts for testing.\n- Setup test environment; execute automation test scripts and ensure about automation test result reliability.\n- Log, verify & manage defects on defect tracking system\n- Follow test leader’s assignments.\n- Escalate testing risks and issues\n\nYour skills and experience:\n- Ability to read and understand English documents specialized in IT field.\n- Has good logical thinking.\n- Good at software programming, Python language is preferred. (Had experience in development position is a plus)\n- Good knowledge about Linux\n- Had knowledge about RegEx is a plus.\n- Automotive (especially IVI: In Vehicle Infotainment) and ASPICE experience is a plus.\n- Good at team working.\n\nWhy you\'ll love working here:\n- 13th month salary + Incentive bonus (Total remuneration package / year: up to 16-month salary) + Annual salary review;\n- HYBRID WORKING, flexible working time (Mon - Fri)\n- Support for lunch, transportation and other allowances (Coding Expert, Technical leader, phone...);\n- Premium health care & accident insurance;\n- Total 20 days off (12 days of annual leave & additional 8 days of company holidays: Summer holiday, Mid-Autumn, Christmas, LG and VS DCV Foundation Days);\n- Support fee to get TOEIC & technical certifications (ISTQB, Agile Scrum...);\n- On-site & training opportunities abroad;\n- Company trip, sport clubs (zumba, football, pingpong, badminton,...);\n- Monthly budget for team activities, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 17 đến tầng 21, Tòa văn phòng, Lotte Mall Hà Nội, Số 272 Võ Chí Công, Phường Phú Thượng, Quận Tây Hồ, Thành phố Hà Nội, Tay Ho, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(371, 311, 2, 'Business Analyst (Agile/Figma)', '- Làm việc với các bên liên quan để thu thập, phân tích và xác định yêu cầu nghiệp vụ, đảm bảo tính nhất quán, đúng và đầy đủ của các yêu cầu\n- Phân tích và đưa ra mô hình, giải pháp dựa trên yêu cầu đã thu thập được\n- Mô hình hóa quy trình nghiệp vụ thành các sơ đồ UML: Use Case Diagram, Activity diagram, State diagram, Flow Diagram,…\n- Phối hợp với các thành viên khác viết các tài liệu đặc tả yêu cầu nghiệp vụ, tài liệu mô tả trường hợp sử dụng (usecase); tài liệu thiết kế chi tiết\n- Truyền đạt nội dung đến các thành viên dự án, quản lý dự án để làm rõ yêu cầu của khách hàng\n- Hỗ trợ team phát triển trong quá trình phát triển sản phẩm\n- Thực hiện kiểm thử UAT. Hỗ trợ quá trình kiểm thử nghiệm thu và xác minh tính chính xác tính năng của phần mềm\n- Quản lý thay đổi yêu cầu trong suốt vòng đời dự án và cập nhật các tài liệu liên quan\n- Thực hiện một số công việc khác khi có yêu cầu của cấp trên\n\n- Tối thiểu 6 tháng kinh nghiệm, Tốt nghiệp chuyên ngành CNTT hoặc tương đương hoặc tự học và đã tham gia dự án liên quan đến phát triển phần mềm\n- Hiểu biết về quy trình phát triển phần mềm (SDLC), Waterfall, Agile\n- Biết sử dụng các công cụ như: Figma, Axure, Balsamiq, Visio, Remind, Jira\n- Sử dụng tốt các công cụ văn phòng (MS Office, Google Workspace)\n\n- Lương từ 10 - 20 triệu, thỏa thuận theo năng lực làm việc, phụ cấp ăn trưa/xăng xe…\n- Hưởng đầy đủ các chế độ về BHXH và cơ chế đãi ngộ theo Quy định của Công ty\n- Môi trường làm việc, đồng nghiệp trẻ trung, thân thiện, luôn có sự hỗ trợ cùng nhau trong công việc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 19 tòa nhà HH2 Bắc Hà, 15 Tố Hữu, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(372, 312, 2, 'Quản lý rủi ro an toàn thông tin (Infomation Security)', 'Top 3 reasons to join us\n1. Thu nhập từ 24 - 26 tháng lương/năm\n2. Được đào tạo trend công nghệ mới\n3. Team building, year-end party...\n\nJob description\n- Phân tích và nhận diện rủi ro an toàn thông tin:\n  - Phân tích các quy trình quản trị, vận hành để nhận diện các rủi ro an toàn thông tin\n  - Phân tích dữ liệu trên hệ thống như security log, các sự kiện rủi ro, các bug lỗi,. để nhận diện các rủi ro an toàn thông tin\n  - Phân tích các bản thiết kế triển khai hệ thống thông tin để nhận diện các rủi ro an toàn thông tin\n  - Phân tích ảnh hưởng của các hệ thống CNTT của ngân hàng đối với CVE mới trên thế giới \n- Phân tích và đánh giá rủi ro an toàn thông tin\n  - Thực hiện phân tích mức độ ảnh hưởng, khả nặng xảy ra, mức độ rủi ro và đề xuất mức độ ưu tiên triển khai biện pháp khắc phục của mỗi rủi ro đã được nhận diện\n  - Thực hiện các công việc khác liên quan đến quản lý rủi ro, chính sách an toàn thông tin\n\nYour skills and experience\n- Trình độ\n  - Đại học hệ chính quy, chuyên ngành CNTT/điện tử viễn thông. \n- Kỹ năng chuyên môn\n  - Có ít nhất 01 năm kinh nghiệm trong lĩnh vực CNTT, đã từng quản trị các hệ thống máy chủ hoặc cơ sở dữ liệu hoặc hệ thống bảo mật hoặc phát triển phần mềm hoặc quản lý rủi ro an toàn thông tin hoặc duy trì hệ thống an ninh thông tin (ISMS) hoặc kiểm toán hệ thống thông tin.\n  - Ưu tiên ứng viên đã từng làm việc trong vị trí quản lý rủi ro an toàn thông tin hoặc kinh nghiệm phát triển phần mềm\n  - Có khả năng phân tích tổng hợp và kỹ năng làm việc nhóm tốt\n  - Ưu tiên: Chứng chỉ ISO27K, CEH, CHFI, CISA, CRISK, CISM, CISSP, CIPP\n\nWhy you\'ll love working here\n- Dẫn đầu thị trường\n  - Cơ hội được làm việc tại một trong ngân hàng Big4.\n  - Cơ hội được thử sức trong những lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n  - Được tham gia vào các dự án lớn: Kho dữ liệu thô – VietinBank Data Lake, Hệ thống khách hàng VietinBank 360, VietinBank Cloud Data Lake…\n- Môi trường năng động sáng tạo\n  - Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo.\n  - Nơi hội tụ của các Machine Learning Engineer, Data Engineer, Software Engineer hàng đầu với nhiều năm kinh nghiệm trong các lĩnh vực tài chính ngân hàng.\n- Chế ngộ đãi ngộ hấp dẫn, cạnh tranh: \n  - Thu nhập từ 24 - 30 tháng lương/năm \n  - Được thư giãn, khơi nguồn sáng tạo mỗi ngày.\n  - Được đào tạo, định hướng chuyên môn thường xuyên;\n  - Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building thú vị\n  - Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '183 Nguyễn Lương Bằng, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(373, 182, 2, 'API Integration Engineer (Java/Python/Golang)', 'We are seeking an experienced API Integration Engineer to join our team and play a crucial role in supporting our engineering and business operations.  Your mission is to embrace continuous integration/deployment in a delivery pipeline that will perform automated quality checks, deploy cloud infrastructure and applications quickly, and provide operational tooling and metrics that can be consumed by development teams. To be successful, you will have a blend of development experience and operational experience that provides a good understanding of the developers you are working with, while also balancing critical systems uptime.\n\nMain responsibilities:\n- Primary job is to do integration work using Java/Python/Golang, REST, SOAP APIs and Identity service.\n- Solving complex technical and business problems and learn new technology and frameworks\n- Be part of a team that will take full responsibility for the features you own\n- Design, develop, test, deploy, monitor and improve, you are responsible for the full life-cycle of your product – build it, own it.\n\nYour skills and experience\nMust have:\n- A pragmatic mindset.\n- Outstanding problem-solving ability, eagerness to learn, and curiosity.\n- A few years of software development experience with one or more general-purpose programming languages.\n- Adaptable attitude and personality that is ready for continuous change.\n- Collaboration and culture fit in Agile experience will be an advantage.\n- The ability to communicate effectively with business and technical teams.\n\nNice to have:\n- Experience working with API Management platforms like: WSO2 / MuleSoft / Kong – design and development of APIs, guidance on design and development best practices, define strategy for operational procedures such as version control, deployments, monitoring - is a big plus\n- Experience in OAuth2 implementations using any Identity/SSO tools\n- API’s designing and modeling using Swagger and API Developer toolkit\n- Experience in Installation and configuration of various API product features and capabilities\n- Good to have knowledge on Middleware and ESB tools\n- Experience working with Amazon Web Service\n- Experience working with Observability platform like DataDog / NewRelic\n- Good skills in English.\n\nWhy you\'ll love working here\nYou’ll love working with us if you are:\n- Passionate about technology.\n- Independent but also a good team player.\n- Comfortable with a high degree of ambiguity.\n- Focused on usability and speed.\n- Keen on presenting your ideas to your peers and management.\n\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\n\nSome of our benefits:\n- Meal and parking allowances are covered by the company.\n- Full benefits and salary rank during probation.\n- Insurances such as Vietnamese labor law and premium health care for you and your family.\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\n- Values-driven, international working environment, and agile culture.\n- Overseas travel opportunities for training and work-related.\n- Internal Hackathons and company events (team building, coffee run, etc.).\n- Pro-Rate and performance bonus.\n- 15-day annual + 3-day sick leave per year from the company.\n- Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(374, 313, 2, 'Backend Developer - Software Engineer', '1. Backend Development & Microservices\n- Design, develop, and optimize high-performance REST/GraphQL APIs and microservices.\n- Build backend services using NodeJS (MERN Stack) and Golang.\n- Enhance system performance and scalability.\n\n2. Technology & Architecture\n- Work with distributed systems and microservices architecture.\n- Deploy applications on cloud platforms.\n- Integrate AI/ML solutions into the system.\n- Proficient in containerization using Docker and Kubernetes.\n\n3. DevOps & CI/CD\n- Develop and maintain CI/CD pipelines using GitLab.\n- Apply best practices in DevOps.\n- Monitor and optimize the development workflow.\n\nYour skills and experience\n\n1. Technical Experience\n- At least 5+ years of experience in backend development with NodeJS (MERN Stack) and Golang.\n- Strong experience in designing RESTful APIs and microservices.\n- Proficiency in working with PostgreSQL, MongoDB, and Redis.\n- Experience in database design for large-scale systems.\n\n2. Technical Skills\n- In-depth understanding of distributed systems and microservices architecture.\n- Proficiency in Docker, Kubernetes, and cloud platforms (AWS, GCP).\n- Strong knowledge of data structures and algorithms.\n- Proficient in Git and source code management tools.\n- Ability to apply AI in enhancing development speed and quality.\n\n3. Soft Skills\n- Strong analytical and problem-solving skills.\n- Effective teamwork and collaboration.\n- Proactive in learning new technologies.\n- High sense of responsibility and passion for software development.\n\nWhy you\'ll love working here\n- Competitive salary commensurate with experience.\n- Flexible working hours to support work-life balance and productivity.\n- Opportunity to work in a dynamic startup environment with a passionate and talented team.\n- Chance to make a significant impact on the growth and success of innovative products in the D2C industry.\n- Collaborative culture that values creativity, diversity, and continuous learning.\n- Career growth and skill development opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24 Huỳnh Khương Ninh, Phường Đa Kao, Quận 1, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(375, 211, 2, 'Automation Tester Engineer', 'Top 3 reasons to join us\n\n- Attractive salary and bonus package\n- Premium AON healthcare insurance\n- Fully sponsored training to build your career\n\nJob description\n\n- You will join the QA team and implement the automation testing to improve quality and reduce IT product and service development time:\n- What will you be responsible for?\n  - Implement shift-left, automated testing first to test early and often\n  - Analyze the project and come up with a suitable, optimal and effective automated testing strategy\n  - Collaborate with the project team, build a test environment and automate test cases according to the proposed strategy\n  - Integrate automated testing suite into CICD process\n  - Always think and improve automated testing suites to improve performance and automation speed\n\nYour skills and experience\n\n- Must-have skills:\n  - At least 2 years of automation testing experience in WEB UI or API testing or Mobile testing.\n  - Experience with Java and any other programming languages (C#, Python, Javascript)\n  - Expert in one or more automation testing frameworks (Selenium, Cucumber, Appium, Protractor, Cypress, Robot etc.)\n  - Working within agile development teams with a BDD approach and supporting the developers to quality assure developments early.\n  - Good experience in API testing ( Postman, RestAssured ) and contract-based testing (e.g. PACT)\n  - Solid knowledge of testing methodologies covering test levels, static test, dynamic test\n  - Strong English communication skills (both verbal & written), especially in the global software development environment\n  - Good ability in troubleshooting and consult the development team to fix the issues\n\n- Nice to have:\n  - Exposure to AWS or any other cloud services (Azure, GCP)\n  - DevOps: Able to operate in a Cloud, CI/CD environment\n\nWhy you\'ll love working here\n\n- Chứng khoán SSI nhận 3 giải thưởng nơi làm việc tốt nhất:\n- Highly competitive remuneration package: Attractive monthly salary, 13th month salary, KPIs cash  bonus, Public holiday cash bonus, Birthday gift, Lunar new year gift....\n- Premium AON healthcare insurance\n- 12 days Annual leave + 2 days sick leave with full paid\n- Luxury team-building trip and varied engagement activities\n- Joining the leisure clubs: Football, E-Sport, Running, Gym, Yoga....\n- Fully sponsored training to build your career\n- Professional, open minded and supportive working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Luong Yen, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(376, 314, 2, '(Đống Đa HN) Lập trình Game Front-end (Unity, Cocos2d)', 'Top 3 reasons to join us\n- Không có Over Time, Cân bằng cuộc sống\n- Cơ hội tiếp cận công nghệ mới, AI\n- Đóng bảo hiểm full lương, chế độ linh hoạt\n\nJob description\n- Phát triển và tối ưu game sử dụng một trong các framework, engine sau : Cocos2d-JS, Cocos2d-x, Unity, PhaserJS chạy đa nền tảng: Android, iOS, WebView, Browser.\n- Tích hợp các tính năng giao tiếp giữa WebView và native code (Android/iOS) thông qua bridge (Javascript ↔ Java/Swift).\n- Tối ưu hóa hiệu suất và kích thước game để đảm bảo trải nghiệm mượt mà trên thiết bị di động.\n- Xử lý tương tác người dùng, hiệu ứng animation, âm thanh, và các logic gameplay.\n- Tham gia bảo trì, sửa lỗi, nâng cấp và thêm tính năng mới cho các sản phẩm game hiện có.\n\nYour skills and experience\n- Có kinh nghiệm tối thiểu 1 năm với Cocos2d-JS, Cocos2d-x, PhaserJS hoặc tối thiểu 2 năm đối với Unity\n- Thành thạo JavaScript, HTML5 hoặc C#.\n- Hiểu biết về Optimization.\n- Hiểu biết về cơ chế hoạt động của WebView trên Android (Java/Kotlin) và iOS (Objective-C/Swift).\n- Có kinh nghiệm làm việc với bridge JS ↔ Native là một lợi thế.\n- Biết debug đa nền tảng (Android WebView, Safari iOS).\n- Khả năng làm việc độc lập và teamwork tốt.\n- Source control với Git.\n\n▼Kĩ năng mong muốn khác\n- Có sản phẩm game demo thực tế.\n- Biết ứng dụng AI để tăng hiệu suất.\n- Biết tiếng Nhật.\n- Ham học hỏi.\n- Biết thêm Cocos Creator.\n- Biết các kiến thức tối ưu bundle JS, nén texture, lazy load, ...\n\nWhy you\'ll love working here\n- Mức lương hấp dẫn từ 800 USD đến 1500 USD\n- Review lương hàng năm\n- Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp đóng full lương.\n- Được thêm 1 ngày nghỉ có phép vào ngày sinh nhật\n- Tham gia lớp học tiếng Nhật, đào tạo chuyên môn do công ty tổ chức\n- Tham gia hoạt động Teambuilding và du lịch hàng năm\n- Trợ cấp chứng chỉ IT, chứng chỉ tiếng Nhật, trợ cấp tham gia hội thảo\n- Tự do ăn mặc thoải mái, không gò bó\n- Happy time ăn uống 1 lần 1 tuần\n- Trợ cấp câu lạc bộ thể thao: bóng đá, cầu lông, gym, ….\n- Nghỉ sau sinh 6 tháng\n- Kho truyện tranh và sách tiếng Nhật free\n- Đồng nghiệp trẻ trung, năng động, thân thiện, hoà đồng\n- Phục vụ đồ uống miễn phí\n- Giờ làm việc : từ thứ 2 đến thứ 6 hàng tuần (8:00 ~ 12:00 và 13:30 ~ 17:30)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, tòa nhà Ocean Park, số 1 Đào Duy Anh, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(377, 307, 2, 'CyberSecurity Solution Engineer (Cloud, English)', 'As a part of the cybersecurity team, you will be asked to :\n- Monitor the latest attack trends and market security threats to ensure we\'re ahead of any emerging risks; along with performing the occasional code reviews, you will look at both the overall roadmap and specifically focus on the security implications of the code.\n- This could involve collaborating with developers to address any vulnerabilities.\n- To help the overall business plan, KPIs and a technical "gap list" will be maintained for the products you will focus on.\n- Participating in security audits and creating necessary reports are regular occurrences, helping us maintain compliance and identify potential weaknesses.\n- Oversee penetration testing activities, working with other internal Red teams to identify and address system vulnerabilities.\n- Training and knowledge sharing, either learning about new security technologies or educating colleagues on best practices.\n\nExpanded Responsibilities:\n- Secure cloud systems, addressing concerns with container and monolithic deployments in public clouds.\n- Implementing US government standards, data impact assessments, and security controls (CJIS, SOC-2, ISO 27001, FedRamp, WCAG, and NIST 800-53).\n- Support secure and efficient web applications, ensuring seamless REST-based interactions and an optimal user experience.\n- Innovate with hybrid cloud-AI applications, leveraging AI and machine learning services.\n- Software testing, bug tracking, and management of software deployment using Agile-related software tracking tools (Jira, Confluence, Testrails, OTRS, ServiceNow)\n- Create and track metrics using Neculus, Google Sheets, and other related tools\n- Work with incident response and security teams to implement processes and procedures in the event of an incident.\n\nYour skills and experience:\n- Bachelor Degree in Science, Computer Science or related applied technology field.\n- Fluent in verbal and written in English language\n- 3 to 5 years of experience in cloud security or cloud infrastructure engineering\n- Hands-on experience with Microsoft Azure, Google Cloud Platform (GCP), and Amazon Web Services (AWS).\n- Strong understanding of cloud security concepts, such as identity and access management (IAM), network security, data encryption, and vulnerability management.\n- Strong understanding of network protocols (TCP/IP, SSH, UDP, IPv4, IPv6, DNS, SMTP, SFTP, DHCP, VPN, IPSec).\n- Experience with Infrastructure as Code (IaC), as a concept\n- Ability to solve problems independently and collaboratively in a dynamic, fast-paced environment.\n- Strong communication skills, capable of conveying technical concepts to a diverse audience.\n- Understanding of and the differences between static and dynamic analysis tools\n\nPreferred Qualifications:\n- Additional experience with Azure, GCP, and AWS is beneficial.\n- Experience with OWASP ZAP, Mend, GitHub CodeQL, Nucleus, SonarQube\n- Understanding of cloud architecture, microservices, and serverless computing.\n- Proficiency in database design and management for both SQL and NoSQL databases.\n- In-depth knowledge of modern authentication protocols like OAuth, OpenID Connect, SAML 2.0, FIDO2, and JWT.\n- Experience with GitHub Workflows to deploy IaC\n- Knowledge of security best practices related to ciphers, key management, and security protocols, and experience working with Red/Blue security teams to improve security posture.\n- Experience with observability and metrics, including Prometheus, New Relic, Kirbana, SIEM’s, and Grafana.\n- Knowledge of compliance frameworks, CJIS, FedRAMP, NIST 800-53\n- Any relevant certifications is a plus\n\nWhy you\'ll love working here:\n- Compensation & bonus: 13th & 14th salary, AIP bonus, Holidays, Tet, and Long year service …\n- Social insurance, Health insurance, Unemployment insurance: by Social Insurance and Labor Law\n- The regime of annual leave, company trip, and checkup examination\n- Award for marriage, newborn\n- We have AON insurance package for employee, spouse, and children every year\n- You will be trained, learned & work with the best technical managers who help you improve various dev skills & career path\n- You’ll love working in our dynamic environment employees, young & active\n- We love sport activities, as marathon, football, swimming,...\n- Working time: From Monday to Friday | 08:30-12:00 & 13:00-17.30', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'L07.01, Tầng 07, Tháp A, Khu thương mại dịch vụ kết hợp nhà ở cao tầng tại lô đất 1-13, thuộc khu chức năng số 1 – Số 15, đường Trần Bạch Đằng, Phường Thủ Thiêm, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(378, 315, 2, 'Platform Engineering (Golang)', 'Job description\n\nCDN Optimization & Routing Logic\n\nBuild services to dynamically route traffic across in-house and third-party CDNs (e.g., BytePlus, Gcore) based on real-time conditions (ISP, bandwidth, cost, QoS).\nImplement feedback loops using QoE metrics to adjust CDN selection automatically.\n\nExperience Platform\n\nDevelop APIs and services that support real-time A/B testing, feature flagging, and config-based behavior without code redeployments.\nWork with data engineers to design pipelines and stores for experimentation data and variant analysis.\n\nEngagement Platform\n\nDesign backend systems to orchestrate omnichannel messaging (push, in-app, email) using real-time user segmentation and behavioral triggers.\nIntegrate with messaging providers and build routing/logging systems to ensure reliability.\n\nTranscode System Integration\n\nBuild UI control panels for configuring backend services, transcoding profiles, routing rules, and more.\nEnsure role-based access, audit logging, and fail-safe designs for sensitive operations.\n\nCore Engineering Principles\n\nDesign clean APIs, asynchronous workers, and scalable microservices with observability (metrics/logs/traces).\nWrite automated tests (unit/integration/load), CI pipelines, and infrastructure-as-code if needed.\n\nYour skills and experience\n\nGraduated from college or higher in IT, Software Engineering, Computer Science, or a related field\n3+ years of experience in backend engineering, preferably in platform, infrastructure, or media-heavy domains.\nStrong understanding of distributed systems, microservices, and event-driven architecture.\nExperience with real-time data processing and building APIs that drive dynamic behaviors.\nFamiliarity with CDN technologies, transcoding pipelines, or A/B testing platforms is a plus.\nBonus: Experience with internal platform or developer tools.\nLanguages: Golang, Python, Node.js\nFrameworks: gRPC, REST, FastAPI, Express\nInfra: Kubernetes, Docker, Redis, Kafka, Postgres, MongoDB\nCloud/CDN: GCP, BytePlus, Gcore, Cloudflare, in-house CDN\nTooling: GitHub Actions, Prometheus, Grafana, Datadog, Airflow.\n\nWhy you\'ll love working here\n\n💰 Competitive Compensation\n13th-month salary, sign-on bonus, performance-based reviews, and attractive bonuses.\n\n🚀 Growth Opportunities\nAccess to training and advanced technologies.\n\n📱 Exciting Projects\nWork on leading entertainment apps and OTT platforms.\n\n🌟 Open Culture\nWe value ideas, creativity, and innovation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '222 Pasteur, Phường Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(379, 225, 2, 'Medior/ Senior Backend Engineer - IDG', 'ABOUT THE JOB\nWe are seeking passionate and results-driven Medior/ Senior Engineer to join our Integration Design and Governance team. This role is perfect for individuals who thrive on building scalable, maintainable, and innovative solutions in a fast-paced environment. You will have the opportunity to understand the intricacies of our business domains and design microservices and APIs that align with business capabilities while ensuring flexibility and scalability.\n\nYou will play a key role in designing resource-oriented APIs and promoting interoperability across microservices by leveraging modern integration patterns like REST APIs, event-driven architecture, and queueing patterns. Additionally, you will contribute to advanced initiatives such as microservice consolidation, GraphQL platforms (Supergraph and Subgraph), and guide teams on building cohesive microservice ecosystems that support specific business capabilities.\n\nAs part of the team, you will oversee the development lifecycle, ensuring technical excellence from design to deployment, while also mentoring and empowering engineers to tackle complex technical challenges and grow within the organization.\n\nYOUR JOB RESPONSIBILITIES\n1. Master the intricacies of business domains and design microservices that align with business capabilities.\n2. Design, develop, review, and implement APIs and integration solutions using modern patterns and resource-oriented architecture principles.\n3. Tackle cutting-edge projects, including microservice consolidation and building GraphQL platforms leveraging Supergraph and Subgraph approaches.\n4. Implement integration patterns (e.g., REST APIs, event-driven architecture, and queueing) to enable seamless communication between services.\n5. Drive success using Agile development practices, CI/CD pipelines, and DevOps processes.\n6. Mentor and guide engineers by sharing expertise, facilitating knowledge sessions, and providing solutions to architectural challenges.\n7. Fully understand customer/business requirements and ensure applications are developed consistently with those needs.\n8. Deliver robust, maintainable, and well-documented solutions with solid test coverage.\n9. Good at English communication.\n\nYOUR SKILLS & EXPERIENCE\nMust-have:\n1. Experience as a Senior/Lead Engineer in a complex, enterprise-level development environment (minimum of 5+ years).\n2. Proficiency in Java or other programming languages (e.g., Python, Groovy, NodeJS, etc.).\n3. Strong foundation in Computer Science, particularly with scalable, maintainable systems.\n4. Expertise in designing RESTful APIs and complex microservices-based systems, with experience debugging and troubleshooting in microservices architectures.\n5. Hands-on experience with cloud computing (AWS or Azure).\n6. Proficiency working in containerized environments with FaaS technologies.\n7. Knowledge of CI/CD pipelines and automation in software delivery.\n8. Experience with unit testing, integration testing, and debugging.\n9. Strong English communication skills (verbal and written) in a global development environment.\n10. Familiarity with Agile methodologies and environments.\n11. Ability to write structured, maintainable, and clean code.\n12. Strong problem-solving and analytical skills.\n\nTHE BENEFITS AND PERKS\n1. Generous compensation and benefit package.\n   - Attractive salary and benefits.\n   - 20-day annual leave and 7-day sick leave, etc.\n   - 13th month salary and Annual Performance Bonus.\n   - Premium healthcare for yourself and family members.\n   - Monthly allowance for team activities.\n   - Premium welcome kit and frequent appreciation gifts.\n   - Extra benefits for long-term employees.\n2. Exciting career and development opportunities.\n   - Large scale products with modern technologies in banking domain.\n   - Clear roadmap for career advancement in both technical and leadership pathways.\n   - Well-structured learning and development programs (technical and soft skills).\n   - Sponsored certificates in both IT and banking/finance.\n   - Premium account on Udemy.\n   - English learning with native teachers.\n   - Opportunity for traveling & training in Australia.\n3. Professional and engaging working environment.\n   - Hybrid working model and good work-life balance.\n   - Well-equipped & modern Agile office with fully stocked pantry.\n   - Special programs to improve your physical and mental health.\n   - Annual company trip and events.\n   - A solid talented team behind you – great people who love what they do.\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(380, 316, 2, 'Senior .NET Developer (English)', 'Top 3 reasons to join us\n• Attractive salary package and valuable benefits\n• Get the opportunity to access global L&D programs\n• Hybrid and flexible working environment\n\nJob description\n• Take an active role in shaping requirements: Partner with stakeholders to understand their needs and translate them into effective technical solutions.\n• Craft clean, scalable, and maintainable code: Build robust and high-performance applications using .NET languages, adhering to best practices and design patterns.\n• Ensure quality through rigorous testing: Write comprehensive unit and integration tests, and participate in testing and debugging efforts to maintain high quality standards.\n• Contribute to continuous improvement: Review, refactor, and maintain existing code to optimize performance and ensure long-term code health.\n• Document your work effectively: Create clear and concise technical documentation to support ongoing development and maintenance.\n• Collaborate effectively within a cross-functional team: Work closely with developers, designers, and testers to achieve shared goals.\n\nYour skills and experience\n• Relevant experience: 5+ year of experience in .NET development, preferably with exposure to various .NET frameworks and technologies.\n• Front-end expertise (nice to have): Knowledge of React, HTML, and CSS to work seamlessly across the full stack.\n• Strong foundation in OOP, SOLID principles, design patterns, and microservices architecture: Demonstrate a deep understanding of these concepts in your code and design decisions.\n• Understanding of domain-driven design: Experience in applying DDD principles to model complex business domains effectively.\n• Agile proficiency: Experience working in Agile environments and adapting to iterative development processes.\n• Excellent problem-solving and communication skills: Ability to troubleshoot complex issues, communicate technical concepts clearly, and collaborate effectively with team members.\n• Educational background: A BSc/BA in Computer Science, Engineering, or a related field.\n• Communication skills: Proficiency in English to communicate efficiently with team members and stakeholders.\n\nWhy you\'ll love working here\n• Full salary and benefits as an official employee on probation.\n• Hybrid working model.\n• Open and flat environment, highly appreciate your idea and constantly supporting your skill development.\n• Innovative and international learning and development program, we dedicate to supporting employees’ growth and development of skills.\n• Challenging products with onsite opportunities in Europe (Germany, Australia, Poland, etc.).\n• 13th-month salary & short-term incentives: we offer incentives as defined by the company’s success in the previous year.\n• 15+ annual leaves per year.\n• Full healthcare compliance.\n• Premium healthcare for employees.\n• Gifts for every special occasion.\n• Supportive working conditions: Laptop, MS Surface Hub.\n• Free and unlimited snacks, tea, coffee, and by-choice request.\n• Premium company trip & business traveling programs and other exciting activities.\n\nNote: Only shortlisted candidates will be contacted. Thanks for your interest!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Anna building, Quang Trung software city, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(381, 317, 2, 'Android Engineer', 'The Software Engineer collaborates with colleagues to define requirements for software solutions and tools aimed at device’ configuration and management, analyzes such requirements, develops the software that realize them and the automatic tests that verify such functionalities.\n\nHe / she participates in design reviews, evaluates new application components and upgrades, writes recommendations on risk mitigation, understands, and recognizes quality software architecture and contributes to its definition, manages Android application’s maintenance, evaluates possible improvement of the software designs.\n\nThere may be also a collaboration with application engineers, field service engineers, technical support engineers and commercial teams to solve technical issues or to address new business needs.\n\nMain Responsibilities:\nTo discuss with team requests for new features or software modules to be developed \nTo define and document functional requirements of needed developments \nTo develop and debug software applications, mainly using Kotlin, Android development tools \nTo apply software engineering and programming best practices \nTo analyze, understand and refactor existing source code \nTo have experience in SW optimization and event-based programming \nTo be familiar with Agile SW development  \n\nYour skills and experience\nTechnical Skills:\nGood knowledge of the Android ecosystem\nProficiency in Kotlin, Android development tools and best practices (e.g. MVVM, JetPack, Android Studio, Gradle, …)\nGood knowledge of Kotlin/Java SE for Linux and Windows is plus\nDevelopment experience with Web UI / web applications / cloud services is plus\nGood knowledge of the testing best practices in Android (unit testing, mocking, …)\nFamiliarity with RESTful APIs and JSON\nBasic knowledge about database\nUnderstanding of patterns and concepts\nFamiliarity with different designs and architectural patterns \nIn-depth knowledge of code versioning tools such as Git\nUnderstanding of CI/CD process\n\nRequirements:\nEducation: Bachelor’s degree relating to Software Engineering or Computer Science\nYoE: 3+ years in application developement\nNice to have: experienes of Kotlin/Java SE for Linux and Windows, Web UI / web applications / cloud services \n\nWhy you\'ll love working here\nCAREER OPPORTUNITIES:\nLive in a high-end technology R&D environment\nBe proud to see your own developed products sold all over the world\nStrong knowledge and skills improvement through practical training and technical experience\nCareer promotion with proven capabilities\nOpportunity for overseas training (US, Europe, etc.)\n\nBENEFITS:\nWorking day: from Monday to Friday (08:00 AM- 4:30 PM), One Smart working day per week\nSalary and Allowance: Competitive\nIncentive, Reward and Bonus: Outstanding employee award with attractive bonus, semi-annual KPI reward, Long term incentive for key positions and Annual bonus\nCompany’s labor policy completely pursuant to Vietnam labor legislation: working conditions, social & health insurance paid based on gross salary.\nMobility: Global mobility program in US and/or Italy\nBenefits: Free meals, transportation allowances, accident insurance 24x24, premium health care insurance including dependents; gifts for Vietnam national days, scholarship for children of employees\nExciting leisure: Sport activities, corporate parties, company trip once a year, monthly teambuilding\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Datalogic Vietnam LLC. F04, Lot I-4A, Saigon High Tech Park, Long Thanh My Ward, Thu Duc, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(382, 318, 2, '[Remote/Hybrid] Backend Engineer (Scala, Golang, Java)', 'Hi there!\n\nWe are Semrush, a global IT company developing our own product - a platform for digital marketers. New stars are born here, so don’t miss your chance.\nThis is our Scala / Java Developer role for those who want to turn ideas into reality using code, algorithms, and maybe a bit of magic.\n\nFind out more and apply here please:\n\nTasks in the role:\n- Collaborating with other developers, engineers, and product team members\n- Write beautiful and fast code that improves our code base in meaningful ways\n- Using test-driven development to write well-tested code\n- Fixing bugs fast and taking your time to solve hard problems well\n- Taking ownership of your tasks and mentoring, supporting the team in solution design, best practices, and driving new projects\n\nYour skills and experience:\n\nWho we are looking for:\n- At least 2 years of work experience in Scala or a similar functional programming language on JVM / Java like Kotlin or functional language like Golang\n- Experience working with Scala-related technologies such as Akka, Akka HTTP, Spark, etc.\n- Understand the basics of Container (Docker Environments), modern CI/CD Pipelines\n- Proficiency in English (written and spoken)\n- Strong problem-solving skills\n\nNot required, but a plus:\n- Google Cloud, AWS, or Kubernetes knowledge would be a big plus\n- You share our common values: Trust, as we prefer to speak up and be our true selves; Sense of Ownership, as it’s not worth wasting time on something you don’t believe in; and enthusiasm for Constant Change, as we are always looking to make things better\n\nWhy you\'ll love working here:\n\nA bit about the team:\nYou can get to know the team better at one of the interviews, but some brief information about future colleagues will be useful now.\nThe Ryte Crawler Team is responsible for the operation and development of the Semrush Enterprise website crawler, leveraging the Chrome/Lighthouse engine to analyze the technical aspects of our customers\' websites. Their primary goal is to ensure comprehensive and accurate data collection that supports Ryte’s customers in optimizing their web presence.\n\nA little more about our company:\nSemrush is a leading online visibility management SaaS platform that enables businesses globally to run search engine optimization, pay-per-click, content, social media, and competitive research campaigns and get measurable results from online marketing.\nWe’ve been developing our product for 16 years and have been awarded G2s Top 100 Software Products, Global and US Search Awards 2021, Great Place to Work Certification, Deloitte Technology Fast 500, and many more. In March 2021, Semrush went public and started trading on the NYSE with the SEMR ticker.\n10,000,000+ users in America, Europe, Asia, and Australia have already tried Semrush, and over 1,000 people around the world are working on its development. The Semrush team is constantly growing.\n\nOur Diversity, Equity, and Inclusion commitments:\nSemrush is an equal opportunity employer. Building a better future for marketers around the world unites people from all backgrounds. Even if you feel that you don’t 100% match all requirements, don’t be discouraged from applying! We are committed to ensuring that everyone feels a sense of belonging in the workplace.\nWe do not discriminate based on race, religion, creed, color, national origin, sex, pregnancy, sexual orientation, gender identity, gender expression, age, ancestry, physical or mental disability, or medical condition, including medical characteristics, genetic identity, marital status, military service, or any other classification protected by applicable local, state or federal laws.\n\nOur new colleague, we are waiting for you!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '15/8 Lê Thánh Tôn, Sonatus Building, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(383, 319, 2, 'DevOps Engineer (Da Nang, HCMC)', 'Top 3 reasons to join us\n- Attractive Package\n- Europe onsite opportunities\n- Private health care for family\n\nJob description\n- Close cooperation in the international teams from Germany, France, the Czech Republic, and the US, and spreading the DevOps culture (You build it, you run it!)\n- Accompanying the complete software delivery process from concept to production\n- Setting up and further developing CI/CD pipelines\n- Setting up and operating modern logging and monitoring solutions \n- Analysis and resolution of problems in staging and production\n- Ensuring application development follows cloud-based architectures\n- Migration of existing applications to cloud-based architectures\n- Work closely together with the development teams \n\nThis job is open to both Vietnamese citizens and foreigners living in Vietnam.\nPlease send us your application in English.\n\nYour skills and experience\n- General qualifications\n  - Strong English communication skills (both verbal & written)\n  - 2+ years of professional experience in international software projects (flexible depending on how fast your learning and technical developing capabilities are)\n  - Degree in engineering or natural sciences (university or technical college)\n\n- Technical skills\n  - Must have\n    - Basic programming knowledge and experience in software development\n    - Experience with Linux and scripting languages\n    - Understanding and experience of DevOps principles\n    - Experience in packaging, developing, and deploying applications (Java or JavaScript)\n    - Comprehensive experience in CI/CD tools such as Jenkins, Git version control...\n    - Comprehensive experience and knowledge of containerization technologies such as Docker, Kubernetes...\n  - Nice to have\n    - Experience with build tools (Gradle, Maven, npm, Webpack...)\n    - Experience with managing database systems (PostgreSQL, Oracle...)\n    - Experience in working with cloud environments (AWS, Azure...)\n    - Experience with configuration management tools (Ansible, Puppet...)\n    - Experience with modern logging and monitoring solutions (ELK/Loki, Grafana/Prometheus...)\n\n- Soft skills \n  - Sense of responsibility, communication skills, and team spirit\n  - Willingness to learn and build a deep understanding\n  - Be able to work independently and under pressure\n  - A passion for software development, new trends, and technologies in IT\n\nWhy you\'ll love working here\n- Good salary and a bonus if things work well \n- Working & growing with an international team\n- Onsite opportunities: short-term and long-term assignments in Europe\n- 18 days off allowance per year \n- Premium insurance for you and your spouse (husband or wife) & yearly check-up\n- Loyalty program after three years and five years\n- Flexible working time (40h/week) with hybrid working policy\n- Highly professional equipment (Mac/Thinkpad, 2 screens, adjustable desks)\n- Intense English course for the first 3 months by our native English teachers and optional English seminars during the work time\n- Training sponsored by mgm\n- An amazing company trip once a year, team-building with the project team and month-end with the whole company, covered by mgm\n- Free in-house drinks (coffee, beer, soft drinks,…) and food (cookies, fruit,…) and out-house company-funded sport clubs (football, swimming, badminton...)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '195A Hai Bà Trưng, Võ Thị Sáu Ward, District 3, Ho Chi Minh; 7 Phan Chau Trinh, Hải Châu 1, Hai Chau, Da Nang; 71 Quang Trung, Hải Châu 1, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(384, 320, 2, 'Backend Developer (NodeJS, Python, Java)', 'Top 3 reasons to join us\n- Highly competitive salary\n- Training and development\n- Opportunity to work in a professional environment\n\nJob description\n- Develop software solutions for international markets.\n- Integrate AI or Blockchain Services.\n- Communicate with clients to understand requirements and report progress.\n- Take responsibility for assigned tasks, including accurate estimation of work.\n- Participate in bidding and estimation processes.\n- Collaborate with other teams within the company to ensure a clear understanding and successful completion of tasks.\n\nYour skills and experience\n- Bachelor\'s degree in Information Technology, Computer Science, or related fields.\n- Strong communication skills in English, both verbal and written.\n- 1-3 years of experience in software development.\n- BE technologies: Node.js (ExpressJS, NestJS), Python (fastAPI, Django, Langchain), Java or PHP, etc.\n- Familiarity with DB such as PostgreSQL, MongoDB, and MySQL.\n- Knowledge of FE technologies (React.js or Vue.js) is a plus.\n- Knowledge of cloud platforms like AWS, Azure, or GCP is a plus.\n- Understanding AI or Blockchain technologies is an advantage.\n- Preference for candidates with experience in Agile/Scrum environments.\n\nWhy you\'ll love working here\n- Competitive salary with performance-based bonuses\n- Dynamic, global, and professional working environment that values innovation and teamwork\n- Holiday and year-end bonuses\n- Health and social insurance in accordance with labor laws\n- Direct training to enhance and expand industry-relevant knowledge\n- Performance evaluation with salary and bonus reviews per company policy\n- Monthly allowance for employees holding IELTS certification.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'HUD3 Tower - 123 To Hieu Street, Nguyen Trai Ward, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(385, 245, 2, 'Crawling Engineer (Java, Python)', 'We are seeking a skilled Software Engineer with a strong background in Spring Boot and Java to join our dynamic team. The ideal candidate will be responsible for designing and developing scalable applications and managing cloud resources effectively.\n\nResponsibilities:\n- Design and develop applications using Spring Boot and Java.\n- Work with databases, SQL, and Python ORM for data management.\n- Design and develop infrastructure using Terraform.\n- Implement serverless applications with AWS Lambda, SQS, EventBridge, and SES.\n- Develop and manage applications on GCP CloudRun.\n- Utilize Git, Jira, and Confluence for version control and project management.\n- Understand and implement CI/CD pipelines using GitHub Actions.\n\nYour skills and experience:\n[Required]\n- Graduated from University major in information technology or related\n- At least one year of experience in same position\n- Experience with Git, Jira, and Confluence.\n- Understanding and utilization of CI/CD.\n- Experience in Python programming.\n- Familiarity with Spring Boot and Java code.\n- Knowledge of GCP Cloud Run.\n- Experience working with Amazon SQS and AWS Lambda.\n- Proficiency in Spring Boot and Java design/development.\n- Strong knowledge of DB/SQL and Python ORM.\n- Experience in Terraform design and development.\n- Familiarity with AWS services: Lambda, SQS, EventBridge, SES.\n- Experience with GCP CloudRun design and development.\n\n[Preferred]\n- Experience in Agile and application lifecycle management.\n- Experience with CI/CD and Git applications.\n- Experience with Amazon Athena.\n- Experience in design and development using Amazon SQS/AWS Lambda.\n- Experience in handling parallel processes, threading, and computing resources.\n- Knowledge of resource optimization techniques.\n- Ability to resolve complex application and cloud resource issues.\n- Experience in analyzing and handling open-source library issues.\n- Familiarity with Apache Flow.\n\nOpportunity:\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Topik allowance\n- Review capacity annually and adjust salary increases according to work performance.\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8 hours/day).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(386, 321, 2, '2 .NET Developer (ASP.NET, C#) Up to $1300', 'Top 3 reasons to join us\n• Môi trường làm việc thoải mái, nghỉ T7, CN. Ko OT\n• Tham gia bảo hiểm sức khỏe PTI \n• Review lương 2 lần/năm, phụ cấp thâm niên \n\nJob description\n•  Tham gia vào quá trình phát triển hệ thống thanh toán trung gian và quản trị tài khoản người dùng cuối.\n• Tham gia thiết kế, xây dựng, phát triển và tối ưu cho hệ thống;\n• Thực hiện các công việc khác theo sự chỉ đạo của quản lý;\n• Các công việc chi tiết khác sẽ được trao đổi cụ thể trong quá trình phỏng vấn.\n\nYour skills and experience\n• Biết lập trình thành thạo  , C#\n• Sử dụng thành thạo các công nghệ: CSS, HTML, JavaScript, Ajax, Jquery, Json, XML, Bootstrap\n• Có ít nhất 02 năm kinh nghiệm làm về MVC Framework, Entity Framework, ADO.Net\n• Có ít nhất 02 năm kinh nghiệm làm về hệ quản trị CSDL: MSSQL,MYSQL\n• Lập trình thành thạo với web-service: SOAP, RESFUL, MVC API\n• Có kinh nghiệm trong việc lập trình với cache-server:Runtime Cache, memcached, redis cache là một lợi thế\n• Có hiểu biết cơ bản về các hệ điều hành Win;\n• Sử dụng thành thạo công cụ Visual Studio (2010,2012,2013,…)\n\nWhy you\'ll love working here\n\n• Nghỉ thứ 7, Chủ nhật\n• Thưởng các ngày nghỉ lễ, sinh nhật Công ty, tết âm lịch, tết dương lịch.\n• Đóng Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm;\n• Được tham gia bảo hiểm sức khỏe PVI care;\n• Ngày phép: 12 ngày/năm được hưởng nguyên lương (Ngoài các ngày nghỉ lễ theo lịch nhà nước, nghỉ hiếu hỉ, ma chay);\n• Du lịch hàng năm, Teambuilding cuối năm do công ty tổ chức;\n• Khám sức khỏe định kỳ hàng năm tại bệnh viên uy tín;\n• Đối với nhân viên nữ có con dưới 1 tuổi: được linh động đi muộn hoặc về sớm 1h/ngày;\n• Được ăn nhẹ vào thứ 6 hàng tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 8, Tòa nhà V.E.T, 98 Hoàng Quốc Việt, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(387, 207, 2, 'Backend/ Cloud Engineer', 'Top 3 reasons to join us\n• Lộ trình phát triển sự nghiệp đa chiều\n• Cơ hội đào tạo, công tác tại Nhật, Singapore, Mỹ..\n• Mức lương hấp dẫn, chế độ thưởng dựa trên năng lực\n\nJob description\n• Collaborating with engineering and development teams to evaluate and identify optimal cloud solutions.\n• Modifying and improving existing systems.\n• Designing, developing, and deploying modular cloud-based systems.\n• Developing and maintaining cloud solutions in accordance with best practices.\n\nYour skills and experience\n• Vietnamese nationality.\n• English communication skills.\n• Degree in computer science or a similar field.\n• Knowledge of Clouds: AWS, Azure or Linux (EC2, ECS, Lambda, SQS, etc.)\n• Experience in programming at least one of JavaScript (Node.js), Java (Spring)\n• Experience working with RESTful web services\n• Knowledge or experience of RDBMS, SQL/NoSQL (PostgreSQL, MSSQL, Amazon DynamoDB)\n• Azure, AWS certifications preferred.\n• Experience with version Control (GIT/ SVN/et.)\n• Troubleshooting and analytical skills.\n• Good communication and collaboration skills.\n\nWhy you\'ll love working here\nPanasonic R&D Center Vietnam was established in April 2007, is a company specializing in R&D of Panasonic Group in Vietnam with the aim of enhancing R&D activities in the field of digital home appliances, automation, mobility in Vietnam, providing R&D services for software solutions in today\'s hottest fields such as AI, Cloud, IoT in a chain of R&D centers of worldwide corporations \n1. Career Path Development\n• Long-term multi-career roadmap;\n• Learning & development (Language Training, Technical Training, Soft-skill Training, On-job Training, etc.)\n• Oversea business trips (Japan, China, Singapore, US, Mexico, EU, etc.)\n2. Work-life Balance\n• Flexible working time that supports work-life balance (Core time: 9:00-16:00; 5 days from Monday - Friday/ week)\n• Additional special holiday\n3. Compensation package\n• Attractive salary \n• Competitive bonus package depend on abilities, performance and competencies\n• Diversified allowance scheme\n4. Wellness\n• Well-protected with 24/7 personal accident and medical care insurance;\n• Well-designed Annual Health Check-up program;\n5. Activities\n• Team-building activities; Birthday Party; Year-end party; Sport Day/ Family Day\n• Summer Vacation (Trip to famous tourist spots domestic/ overseas,…)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lotte Tower, 54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(388, 322, 2, 'Business System Analyst', 'About the Role:\nWe are looking for a detail-oriented and proactive Technical Business Analyst (BA) to work closely with our Java development squads and the Delivery Lead to drive successful project outcomes. This role is pivotal in bridging the gap between business requirements and technical implementation, ensuring clarity, alignment, and quality throughout the delivery lifecycle.\n\nKey Responsibilities:\n- Collaborate with the Delivery Lead and development squads to gather, analyze, and document business and technical requirements.\n- Translate business needs into clear, concise, and structured documentation, including user stories, process flows, and functional specifications.\n- Support the creation and maintenance of technical documentation, such as API specs, data models, and system architecture overviews.\n- Facilitate workshops, sprint planning, and backlog grooming sessions with stakeholders and development teams.\n- Act as a liaison between offshore teams and Australian stakeholders, ensuring consistent communication and alignment.\n- Assist in UAT planning and coordination, ensuring that delivered features meet business expectations.\n- Continuously improve documentation standards and delivery processes.\n\nYour skills and experience:\n- From 5 - 8 years of experience as a Business Analyst in a technology-driven environment.\n- Strong understanding of software development lifecycles, particularly Agile/Scrum.\n- Proven ability to create high-quality documentation for both business and technical audiences.\n- Experience working with technical teams, especially in Java-based environments.\n- Excellent communication and stakeholder management skills.\n- Strong analytical and problem-solving abilities.\n- Proficient in tools such as Jira, Confluence, Lucidchart, or similar.\n\nPreferred Qualifications:\n- Experience working with distributed or offshore teams.\n- Familiarity with REST APIs, data structures, and system integration concepts.\n- Prior experience engaging with Australian clients or similar markets.\n\nWhy you\'ll love working here:\nLife at Capgemini is dynamic and fun, a place where people love to work. A career with freedom, full of learning and development opportunities and the support to help you achieve your best.\n\nA career at Capgemini is rewarding and constantly transforming. Here are the top ten reasons why people love working at Capgemini:\n1. Your values are our values: We’re guided by seven core values: honesty, boldness, trust, freedom, team spirit, modesty, and fun. If you share those values, then you’ll find your place with us.\n2. People come first: Through our People Charter, we encourage free exchange of ideas, respect for differences, and wellbeing in the workplace for everyone.\n3. Never stop learning: At the Capgemini Group University, you’ll learn via classroom-based and virtual courses, e-learning modules and rich-media online resources.\n4. Feel free to grow: Over the course of your career, your goals may shift. Want to change your focus? Switch tracks? We’re here to help.\n5. Get inspired by your colleagues: Our cultural diversity means you’ll always have something to learn from those around you.\n6. Forget the notion of the “typical day”: Challenge and variety are constants here. From the work you do to the people you meet to the places you travel, we’ll keep you on your toes.\n7. Strike a balance that works for you: You’re human—and so are we! We strive to make sure our employees achieve a healthy, happy work-life balance.\n8. Count on us for career growth: We’re always growing and so should you. We prioritize the personal development of our team members with our Capgemini Group University.\n9. Your Love for Travel: We have 300 offices in 40 countries around the world. You’ll have opportunities to travel or work in different locations.\n10. Dig in your first day: Whether you join us as a recent graduate or a seasoned professional, you’ll start to work directly on challenging projects from day one.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '106 Nguyen Van Troi, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(389, 323, 2, 'Fulltime Remote Fullstack Javascript/Typescript/NodeJS', 'We are a fast-growing, remote-first technology company transforming back-office operations for micro SMEs through innovative software, AI, and a commitment to outstanding customer experiences.\n\nAs a Fullstack Javascript Engineer, you’ll drive the creation of scalable, AI-powered solutions to revolutionize our tech landscape, enhancing efficiency, innovation, and user satisfaction. Collaborating with data scientists, product managers, designers, and DevOps teams, you’ll build robust systems with seamless AI integration, setting new standards for reliability and excellence.\n\nWe are looking for a high-quality, architecture-minded engineer who combines strong technical fundamentals with the smart use of AI tools, a focus on system reliability, and a deeply collaborative mindset. They take ownership of code quality and system stability, always striving to level up both their own work and their team’s performance.\n\nYour skills and experience\nKey outcomes\nDeliver High-Quality Code: Consistently submit well-documented, maintainable code with high test coverage (>80%) through PRs, following team standards and best practices.\nApply Strong Fundamentals: Design and build features applying solid software architecture (e.g., SOLID, clean architecture), efficient database design, and API best practices.\nLeverage AI Tools Effectively: Use AI coding assistants to speed up development (e.g., boilerplate, test writing, debugging) without sacrificing code quality. Share effective prompts and techniques\nContribute to System Stability: Maintain production rollback rates below 2% by enforcing thorough testing, leveraging CI/CD, and following DevOps best practices.\nEngage in Collaborative Development: Actively join code reviews, provide constructive feedback, and respond positively to feedback to boost team velocity and knowledge sharing.\nRequirements\nExperience: 5+ years as a Fullstack Engineer, AI Specialist, or similar, with a strong track record of deploying scalable, AI-integrated applications.\nFrontend & Backend Skills: Proficient in VueJS/React and NodeJS (TypeScript), with experience building modular, reusable, and resilient microservices.\nDatabase & Architecture: Skilled in MongoDB/Supabase, REST/RPC, and designing systems aligned with Clean/Hexagonal architecture, SOLID principles, ACID compliance, and idempotency.\nAI Expertise: Experienced in AI ecosystems like LangChain and LlamaIndex, with hands-on skills in prompt engineering, RAG, and curiosity about specialized hardware like Groq.\nQuality Commitment: Dedicated to high testing standards, secure coding, and detailed documentation for AI pipelines to ensure reliable performance.\nCommunication: Strong communicator, adept at collaborating with Agile teams and connecting product, UX, data science, and engineering to drive AI initiatives.\nCloud & DevOps: Knowledgeable in AWS/GCP, serverless/PaaS solutions, and Kubernetes deployments, with a focus on MLOps and AI model lifecycle best practices.\nVersatility: Comfortable working independently or collaboratively, pushing projects from concept to production while inspiring your team.\n\nWhy you\'ll love working here\nAs a full-time employee, you will be eligible for the benefits that CoderPush offers according to our policies:\nA remote working environment that allows you to work from anywhere in the world\nFull-time insurance follow VN Labor laws\nWork equipment support.\nAnnual bonus, performance-based bonus.\nMonthly compensation package to help you work and live better, remotely!\nFully support for exams to get Certification and skills improvement training.\nReceive 22 paid leaves on your 5th years. We encourage you to take one month off work.\nA competitive salary and benefits package\nOpportunities for professional development and career advancement with monthly coaching.\nA dynamic and innovative team that values creativity and collaboration.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(390, 310, 2, 'Senior Full-Stack Developer (Node.js, ReactJS, BIM)', 'We are currently hiring a Senior Full-Stack Developer to join the Product Development team. If you love building high-impact products that touch the lives and stomachs of millions of users, working alongside a talented, world-class team, we want to hear from you.\nResponsibilities\n- Develop, optimize, and maintain web applications - Build high-performance, cross-platform UI/UX - Write tests (unit tests, integration tests) to ensure code quality\n- Optimize performance, improve page load speed and rendering\n- Proficiency in Node.js, React and Construction/BIM.\n- Ability to optimize queries and assist in database design.\n- Experience in setting up and managing CI/CD pipelines. - Service broker and gRPC\n\nWe accept working from Ho Chi Minh City, Hanoi and Danang[Work from home]\n\nYour skills and experience\nMain requirements:\n- At least 5 years of experience in full stack development is preferred.\n- ReactJS, TypeScript, TailwindCSS, HTML, CSS.\n- NodeJS.\n- Construction/BIM.\n- SQL postgres, Redis andMongoDB.\n- Strong understanding of OOP (Object-Oriented Programming) and its application in projects.\n- Ability to write technical documentation and follow coding standards.\n- Strong knowledge git.\n\nNice to have:\n- Familiarity with Web Worker, WebAssembly, Web Push Notification.\n- Knowledge of openBIM/BIM is a plus.\n- Knowledge of threeJS is a plus.\n- Familiarity with Bitbucket is a plus.\n- Knowledge of Kubernetes and microservices architecture is a plus.\n- Understanding of Service Broker for managing service communications.\n\nMindset and skill:\n- Strong logical thinking and problem-solving skills.\n- Passion for learning and staying updated with new technologies.\n\nWhy you\'ll love working here\nWe provide our staff with:\n- Very attractive salaries that commensurate with work experience.\n- Have a chance to develop your career and access new IT technologies\n- Be able to have business trip in Singapore and meeting strategic partnership\n- Be supported and work with experienced and friendly member.\n- Professional and nice work environment.\n- Work from home.\n- Bonus based on your proficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(391, 324, 2, 'Front End Developer ( Nodejs, Flutter, C/C++, MFC )', 'Top 3 reasons to join us\n- Profession\n- Opportunity to develop skills\n- Have the opportunity to advance\n\nJob description\nCandidates selected will participate in the following projects:\n- Research and develop additional features in the VIMES hospital management solution.\n- Develop software systems to manage connections with testing machines.\n- Develop software to manage DICOM image storage and processing.\n- Develop software for managing finance, accounting, salary, and asset management.\n- Participate in the entire system construction process (research, survey, analysis, design, coding).\n- Develop electronic medical record subsystems running on smart devices.\n\nYour skills and experience\n- University graduate in IT.\n- At least 1 year of experience in a similar position.\n- Proficient in programming using technologies: C/C++, MFC, or Node.js, Flutter.\n- Prefer candidates with Flutter programming experience.\n- Experience in programming with one of the databases: Oracle, PostgreSQL, etc.\n- Write backends for applications, system functions using JavaScript, TypeScript, Flutter/NodeJS.\n- Participate in building, upgrading APIs and optimizing system features for users.\n- Learn and apply new technologies to enhance system load-bearing capacity.\n- Participate in research and development of new products as requested by customers.\n- Have the ability to analyze and design software.\n- Have a creative mindset, quick to learn and absorb new technologies, able to work under pressure.\n- Non-smoker.\n\nWhy you\'ll love working here\n- Competitive salary, negotiable based on competence.\n- Bonuses on holidays, Tet, 13th month salary, and attractive year-end bonuses based on revenue.\n- Regular annual salary review.\n- Improve software development skills by participating in large-scale, practical projects of VIMES.\n- A modern, professional working environment with opportunities for advancement and long-term stability.\n- Social insurance, health insurance, unemployment insurance as prescribed by law.\n- Full benefits for employees according to current labor laws (Tet gifts, Mid-Autumn Festival gifts, Children\'s Day, company birthday, etc.).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '73 Lý Nam Đế, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(392, 325, 2, 'Staff Fullstack AI Engineer', 'Top 3 reasons to join us\n- Cutting-edge technology in semiconductor design\n- Competitive compensation and benefit package\n- Young, dynamic, team-oriented working environment\n\nJob description\nAbout this role\nAs a Full Stack AI Engineer, you will develop the user interfaces for and manage the full lifecycles of AI/ML application experiences.\n\nAbout our team\nOur global AI, Data & Analytics Division at Renesas is experiencing an increasing demand for AI and Generative AI (LLM) based solutions. Working closely with our business partners, we deliver AI solutions to help drive value for Renesas at a global enterprise scale. We are seeking passionate candidates that will thrive as part of a global team of technologists that love empowering customers, collaborating with teammates, and using the latest AI and Data technologies.\n\nResponsibilities\n- Build and enhance user interfaces and experiences for AI solutions, including front-end and back-end systems and deploying complete applications.\n- Develop and maintain full stack AI/ML applications using Databricks tools and frameworks.\n- Collaborate with data scientists and AI/ML engineers, and domain experts on cross-functional projects using Databricks Workspaces.\n- Keep up to date with the latest developments and trends in AI/ML applications and Databricks technologies.\n\nYour skills and experience\nMust Have\n- Bachelor\'s degree or higher in computer science, engineering, or a related field.\n- 10+ years of professional experience in the tech industry.\n- Strong management skills, including team leadership and cross-functional coordination.\n- Proficiency in JIRA, Confluence, and related project management tools.\n- Expertise in system/solution architecture design, with solid knowledge of cloud platforms (e.g., AWS, Azure, GCP).\n- Ability to create and communicate technical designs using tools like Draw.io.\n- Fluent English communication skills, both written and verbal.\n- Experience working with AI team members, or a strong motivation to learn and collaborate in AI-related projects.\n\nNice-to-Have Skills:\n- Knowledge of DevOps practices and tools.\n- Experience with frontend development using React.\n- Familiarity with backend technologies, including Python, MongoDB, and PostgreSQL.\n\nWhy you\'ll love working here\nRenesas Design Vietnam Company Limited aims to provide our employees with comprehensive compensation and benefit plans, and a professional working environment. Some featured benefits are: \n- Competitive salary/bonus based on working performance. \n- Excellent training program. \n- Opportunity for promotion.\n- Fair assessment. \n- 24/24 hour insurance package including social and medical and unemployed insurance \n- Dynamic people. \n- Team-oriented environment. \n- Sport activities and Annual company trip.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '31 Tan Thuan, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(393, 326, 2, 'QA Engineer (Automation)', 'Top 3 reasons to join us\n- Boost your international career at CODE LEAP\n- Work on challenging German B2B products \n- Flexible work policy with Grab sponsorship\n\nJob description\n- Perform E2E tests via the UI, simulating various user actions to ensure comprehensive functionality and stability\n- Test individual front-end components, ensuring they behave as expected within the overall UI\n- Develop and maintain automated UI tests using Playwright, ensuring the tests stay effective and aligned with the evolving platform\n- Work closely with developers to integrate test coverage into the development cycle and ensure defects are tracked and resolved efficiently\n- Log and track defects using tools like Jira, analyzing root causes and ensuring quick resolutions\n- Maintain and update test documentation and test data sets to ensure consistency and repeatability\n- Contribute to the improvement of testing processes, such as optimizing test scripts and suggesting new tools for better testing efficiency\n\nYour skills and experience\n- At least 2 years of experience in software testing\n- Hands-on experience with React (for understanding UI behavior and components in the context of testing)\n- Strong expertise in Playwright for UI test automation\n- Solid experience in front-end testing and validating that UI components work as expected\n- Knowledge of UI testing frameworks (e.g., Playwright, Cypress) and best practices for automation\n- Experience with manual testing of the UI for real-world usability and user experience validation\n- Familiarity with defect tracking tools like Jira\n- You understand and know how to prioritize your tasks with a problem-solving mindset\n- You don\'t take things personally and are comfortable with ambiguity and rapid changes common in early-stage product development\n- You don\'t wait for others to tell you what you need to do but proactively reach out to people, communicate, ask for help, and get things done\n- You feel comfortable communicating in the English language\n\nNice to have\n- Experience transitioning from development to QA\n- Experience with eCommerce/ERP platforms (e.g., Shopify, Magento, JTL, etc.)\n- Have a development background is a plus\n\nWhy you\'ll love working here\n- Competitive salary and beneﬁts\n- Year-end bonus (13th-month salary)\n- Generous annual leave of up to 18 days\n- Enjoy a stress-free and comfortable commute to and from work with our Grab Services sponsor\n- Enjoy an endless selection of delicious refreshments, including gourmet coffee, beverages, snacks, and fresh fruits, all complimentary\n- Focused on individual development:\n  - Unlimited access to Udemy and other recommended courses\n  - Sponsored Professional certificates such as ISTQB, ASQ, CSTE, CAST, etc\n  - Sharing session every Friday, come along with lunch provided by CODE LEAP\n  - 1-on-1 coaching with experienced professionals\n- Flexible work policy, which provides flexible hours to accommodate personal schedules and commitments\n- Premium AI Assistant tools are provided to support your work\n- Dynamic, fun, and agile environment, perfect for sharing and creativity\n- Open-minded, kind & humble colleagues', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '101 Nguyen Cuu Van, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(394, 209, 2, '[Healthcare] Data Engineer', 'A subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n- In charge of the design, development, and optimization of scalable data pipelines and ETL processes.\n- Architect and manage data storage solutions, including databases and data warehouses.\n- Collaborate with cross-functional teams to understand data requirements and deliver robust data solutions.\n- Implement and enforce data quality and validation processes to ensure data accuracy and integrity.\n- Monitor and troubleshoot data systems to ensure optimal performance and reliability.\n- Stay abreast of the latest industry trends and technologies in data engineering.\n- Provide technical leadership and mentorship to junior and senior data engineers.\n- Drive the adoption of best practices in data engineering and data governance.\n- Lead and participate in strategic planning and decision-making processes related to data infrastructure.\n\nYour skills and experience\n- Bachelor’s or Master’s degree in Computer Science, Engineering, or a related field.\n- 5+ years of experience in data engineering or a related role.\n- Proven experience in leading and mentoring engineering teams (for Lead position).\n- Strong proficiency in SQL and experience with relational databases (e.g., MySQL, PostgreSQL).\n- Extensive experience with big data technologies (e.g., Hadoop, Spark, Kafka).\n- Proficiency in programming languages such as Python, Java, or Scala.\n- Experience with cloud platforms (e.g., AWS, Azure, Google Cloud) and their data services.\n- Strong problem-solving skills and attention to detail.\n- Excellent communication, collaboration, and leadership skills.\n\nPreferred Qualifications:\n- Experience with data modeling and data architecture design.\n- Knowledge of data governance and security best practices.\n- Familiarity with machine learning and data science concepts.\n- Experience in strategic planning and project management.\n\nWhy you\'ll love working here\n- Performance-based bonuses up.\n- FPT Care insurance plan tailored for FPT employees.\n- Attractive annual summer vacation allowance.\n- Sponsored training courses for personal growth and up to 100% coverage for certification costs.\n- Global and inclusive workplace with monthly cross-cultural events.\n- International exposure and career growth across global locations.\n- Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Building, 17 Duy Tân Str., Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(395, 327, 2, 'Software Architect', 'We are seeking a highly skilled and experienced Software Architect to provide technical leadership and guidance for our development teams. The ideal candidate will be responsible for designing and overseeing the implementation of robust, scalable, and maintainable software systems. You will play a crucial role in defining the architectural vision, ensuring alignment with business objectives, and fostering innovation within the engineering department. Collaboration with cross-functional teams, including product managers and stakeholders, will be essential.\n\nKey Responsibilities\n\nDesign and guide the implementation of scalable, reliable, and secure software solutions.\nCollaborate with stakeholders to understand business requirements and translate them into technical designs.\nEvaluate and recommend technologies, tools, and frameworks to support the architectural vision.\nProvide technical leadership and mentorship to development teams.\nEnsure adherence to architectural principles, coding standards, and best practices.\nIdentify and mitigate technical risks and challenges.\nParticipate in code reviews and ensure the quality of deliverables.\nStay up-to-date with emerging technologies and industry trends.\n\nYour skills and experience\n\nProven 7-10 years of experience as a Software Architect or in a similar leadership role within software development.\nStrong understanding of software development methodologies, principles, and best practices.\nExperience designing and implementing complex, scalable, and distributed software systems.\nProficiency in programming languages and technologies relevant to modern application development.\nSolid knowledge of architectural patterns (e.g., microservices, event-driven architecture).\nExperience with cloud platforms (e.g., AWS, Azure, GCP) and their services.\nFamiliarity with DevOps practices and CI/CD pipelines.\nExcellent communication, collaboration, and leadership skills.\nAbility to translate business requirements into technical specifications and architectural blueprints.\nStrong problem-solving and analytical abilities.\nExperience mentoring and guiding development teams.\nUnderstanding of security principles and best practices in software design.\nBachelor\'s or Master\'s degree.\n\nWhy you\'ll love working here\n\n13th-month salary, annual performance review\nLaptop upon joining.\nYearly company trip.\nModern facility, flexible and open environment.\nOpportunity for business trips to other countries.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cong Hoa, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(396, 328, 2, 'Software Development Manager(JavaScript/NodeJS/English)', 'Chúng tôi là một công ty chuyên phát triển Mini Game và nhận dự án outsourcing từ nước ngoài. Hiện tại, chúng tôi đang tìm kiếm một Software Development Manager có năng lực kỹ thuật vững chắc và nhiều kinh nghiệm để dẫn dắt đội ngũ kỹ thuật, định hướng và thực hiện các mục tiêu phát triển game của công ty.\n\nMô tả công việc:\n- Xây dựng và triển khai chiến lược công nghệ dài hạn, đảm bảo sự phát triển phù hợp với mục tiêu kinh doanh.\n- Quản lý và dẫn dắt đội ngũ kỹ thuật, đảm bảo tiến độ và chất lượng sản phẩm.\n- Đánh giá và áp dụng các công nghệ mới nhằm tối ưu hóa hiệu suất, bảo mật và vận hành.\n- Thiết lập quy trình phát triển phần mềm hiện đại, bao gồm CI/CD và các mô hình bảo mật.\n- Có kinh nghiệm phát triển hệ thống và nội dung Game.\n- Chịu trách nhiệm phát triển, đào tạo xây dựng đội ngũ nhân viên kĩ thuật.\n- Tham gia cùng đội ngũ Quản lý để định hướng và phát triển kinh doanh.\n\nYour skills and experience:\n- Tối thiểu 5 năm kinh nghiệm Software Development Manager hoặc các vị trí tương đương trong lĩnh vực phát triển Game và Web.\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các lĩnh vực liên quan.\n- Có kinh nghiệm phát triển game hoặc từng tham gia vào các dự án game lớn, sở hữu portfolio mạnh.\n- Thành thạo các công nghệ phát triển Mini Game và cập nhật xu hướng thị trường.\n- Kinh nghiệm phát triển game, hệ thống website (frontend & backend), API development.\n- Hiểu biết về quản lý phiên bản, quy trình phát triển phần mềm và triển khai CI/CD.\n- Thành thạo Jira để quản lý dự án và kiểm soát phần mềm khác.\n- Tiếng Anh thành thạo (4 kỹ năng), có thể làm việc với đối tác và đội ngũ quốc tế.\n- Kỹ năng lãnh đạo, quản lý nhóm và giải quyết vấn đề xuất sắc.\n- Khả năng tư duy chiến lược, đổi mới sáng tạo và ra quyết định nhanh chóng.\n- Có kỹ năng giao tiếp và phối hợp giữa các phòng ban trong tổ chức.\n\nWhy you\'ll love working here:\n- Mức lương Thỏa thuận theo năng lực\n- Chế độ lương - thưởng: Lương tháng 13, thưởng doanh thu.\n- Trợ cấp ăn trưa\n- Chăm sóc sức khỏe: Bảo hiểm y tế\n- Nghỉ phép: 12 ngày/năm (tăng theo kinh nghiệm), nghỉ lễ theo lịch nhà nước\n- Chế độ đãi ngộ tốt nhất cùng đội ngũ nhân viên luôn hỗ trợ nhau hết mình, trọng dụng nhân tài\n- Khu vực pantry fill đồ ăn cà phê trà bánh free cho mọi người\n- Có cơ hội tiếp xúc với chuyên gia trong lĩnh vực công nghệ và kinh tế.\n- Có cơ hội phát triển bản thân và thăng tiến\n- Môi trường năng động, thân thiện, tự do, thoải mái\n- Thường xuyên được tham gia team building, hoạt động nội bộ.\n- Thời gian làm việc: Từ 9h - 18h, từ Thứ 2 - Thứ 6.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '99 Nguyễn Thị Nhung, Hiệp Bình Phước, Thủ Đức, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(397, 329, 2, 'Tech Lead – IP Telephony/VoIP Systems (NodeJS, Golang)', 'Proposition:\n• JOB OFFER after 1 ROUND INTERVIEW\n• Clear career path & ESOP opportunities upon product launch\n• While NOT mandatory, strong English reading/listening skills are highly recommended for ongoing course learning & documentation review\nAbout us: K&M Holdings is a dynamic startup in Hanoi specializing in SaaS/AaaS solutions. Our flagship products include an IP Telephony platform built on Asterisk, a coalition loyalty app, and AI-powered customer care agents.\n\nAbout the role:\nWe are seeking a passionate and experienced Tech Lead to drive the technical vision for our IP Telephony platform. In this role, you will be at the forefront of designing and developing robust telecommunication solutions using the Asterisk framework. You will lead a team of developers and collaborate closely with product managers and external telecom providers to deliver a high-quality, scalable, and secure VoIP system. Your expertise will be key in defining architecture, ensuring system performance, and integrating cutting-edge telephony technologies that meet both current and future business needs.\n\nResponsibilities: \n• Architectural Leadership: Design and oversee the overall system architecture for the IP telephony platform, ensuring scalability, security, and high availability.\n• Core Development: Serve as the principal coder; write and review critical code components, modules, and integrations with Asterisk and VoIP protocols (SIP, RTP, etc.).\n• Team Leadership: Mentor and guide a small team of backend and frontend developers, establishing coding standards, best practices, and agile methodologies.\n• Integration & Collaboration: Work closely with product management and external telecom providers to align technical solutions with business needs.\n• Performance Optimization: Analyze system performance and implement improvements for call quality, reliability, and security.\n• Innovation: Stay updated on emerging telecommunication trends and integrate new features or protocols as needed.\n\nYour skills and experience\nCandidate requirements:\n• Bachelor’s or Master’s degree in Computer Science, Electrical Engineering, or a related field.\n• 3+ years of hands-on experience in telecommunication systems, VoIP technologies, or related domains.\n• Proven expertise with the Asterisk framework and associated protocols (SIP, RTP).\n• Strong programming skills (preferably in C/C++, Node.js and Python) and a deep understanding of network and telecommunication infrastructure.\n• Familiarity with cloud-based telephony integrations and containerization technologies.\n• Experience in agile project management and modern CI/CD practices.\n• Demonstrated leadership experience with a track record of delivering complex technical projects.\n• Excellent problem-solving, communication, and mentoring skills.\n\nWhy you\'ll love working here\n• JOB OFFER after 1 online interview round\n• Clear career path & ESOP opportunities upon product launch\n• Mentorship by seasoned Tech Leads & free access to modern learning courses\n• While NOT mandatory, strong English reading/listening skills are highly recommended for ongoing course learning & documentation review\n• Social, Health, and Unemployment Insurance provided after probation period\n• Annual leave in accordance with regulations\n• Public holidays off as per labor laws\n• Holiday bonuses: 13th-month salary bonus\n• Team building activities, monthly birthday celebrations, etc.\n• Support for parking fees, lunch, beverages, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '66 Trương Công Giai, Dịch Vọng, Hà Nội, Vietnam, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(398, 330, 2, 'Senior Data Analyst (SQL,Python)', 'Top 3 reasons to join us\n- Competitive packages Parking fee & Lunch allowance\n- Flexible working hour. Annual leave 15 days/ year\n- Room to grow professionally. Sponsorship for L&D\n\nJob description\n- Identifying and gathering department requirements and then designing and implementing solutions that meet those needs with appropriate products or services.\n- Conduct in-depth data analysis using SQL, Python, and other relevant tools to extract, clean, transform, and visualize data.\n- Own the end-to-end data flow, and data analysis and provide insights into the effectiveness of the business and key performance indicators (KPIs) for the senior management team.\n- Create compelling data visualizations (e.g., dashboards, reports) to communicate insights effectively to both technical and non-technical audiences.\n- Preparing reports and Providing data support for various departments for predictions using relevant data;\n- Monitor partner operations and guide their action plans based on data-driven insights.\n- Document data analysis processes for future reference and knowledge sharing.\n- Propose new automated data acquisition or analysis processes.\n- Provide data support for various departments.\n- Other tasks as assigned by management.\n\nYour skills and experience\n- At least 5 years of experience in the data field, with experience in tech companies being advantageous. BA degree from a university in Statistics, Business, Data Analytics, or related fields.\n- Strong analytical skills with the ability to identify patterns and trends in large datasets.\n- Master in SQL, data analysis, and data visualization skills using BI tools such as Data studio and Tableau. Familiarity with R and Python is a plus.\n- Excellent communication skills and the ability to work with business, product, and technical stakeholders.\n- Proactive problem-solving skills with a keen attention to detail. \n- Proficiency in data processing, analytical skills, as well as negotiation and presentation skills.\n- Experience with cloud platforms (e.g., AWS, Azure, GCP).\n- Experience with data warehousing and data modeling concepts.\n- Experience with machine learning or artificial intelligence is a plus.\n\nWhy you\'ll love working here\n- 100% salary on your probation period.\n- 15 full-paid days off per year.\n- 13th-month bonus salary.\n- Room to grow with support from the team and sponsorship for L&D.\n- Performance review 2 times/year.\n- Competitive packages.\n- Room to grow professionally, sponsorship for learning & development of related skills.\n- Opportunity to work on a mission that can transform the lives of millions of Vietnamese.\n- Annual Performance Bonuses (up to 2 salary months per year).\n- Parking fee & Lunch allowance.\n- Annual Health Checkup, Premium Health Care (Manager level), Accident Insurance for all members.\n- Enjoy a variety of corporate events, from sports competitions, monthly birthday parties, and team building to Year-End Party, etc.\n- Flat, open, and fast-paced environment where every idea is welcomed.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '402 Nguyễn Thị Minh Khai, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(399, 331, 2, 'Back-end Engineer ( Golang, Python)', 'At Teko, with nearly 200 talented engineers in many fields, we work and share knowledge in the application of advanced technology platforms such as Cloud, Big Data, Al, … In addition, Teko Ventures is investing strongly in the fields of Fintech, New Retail, Logistics, Warehouse, Digital Entertainment, B2B Management Solution.\n\nYour responsibilities:\n- You will be part of an agile team, working closely with product managers, designers and technical leads to ideate, prototype, build and test new products or features. In short, you take ownership of your work and leads the effort from architecture, implementation, deployment and testing.\n- Writing clean and reusable code with unit / functional tests and continually increase your code quality.\n- Having lots of discussions, brainstorming with your team to make technical decisions.\n- Spending lots of time to review other people’s code so you will learn and understand every piece of the system and making sure we have the best code quality as a team.\n- Constantly raise your standard, learning new things and sharing knowledge with the rest of the team. We believe it’s more meaningful when we grow as a team.\n- Taking ownership of the product and constantly find ways to make it better by improving the design, system maintainability, performance and reliability. You will also monitor and troubleshoot application or system issues by deep diving into technical problems. This requires you to understand the whole application and infrastructure stack.\n\nRequirements:\n- BS in Computer Science or similar field of study.\n- Very solid experience of software development (Golang, Python, Java, .NET, JavaScript,..)\n- Have good knowledge about computer science, data structures, algorithms.\n- It’s good to have years of experience but as long as you love to code and learn new things, then you are good.\n- Good to have: Experience with designing and building high traffic applications to serve millions of users.\n- Good to have: Experience with devops automation tools, CI/CD.\n- Good to have: Experience with containerization technologies such as Docker, Kubernetes.\n\nOur current tech stacks:\n- Infrastructure: Linux, Network, Storage (Ceph), Kubernetes.\n- CI/CD: Ansible, Docker, GitOps.\n- Application layers: Python, Golang, Java, .NET, JavaScript.\n- Distributed systems: Elasticsearch, Apache Spark.\n- Databases: MongoDB, Redis, MySQL.\n\nWhy you\'ll love working here:\n- Negotiable salary according to qualification (13th-month salary + performance bonus);\n- 02 months probation with 100% of Gross salary;\n- The working environment is open, energetic and professional. More opportunities for career promotion;\n- Free Food & Drink: lunch, fresh fruit/cake, coffee & tea;\n- Annual health check and attractive Premium healthcare coverage under the company’s own policy;\n- Employee Relationship: company trip, team bonding & clubs;\n- Leave Paid: 12 days for annual leave & 6 days for sick leave (max 18 days);\n- Working time: Monday to Friday (Flexible from 8:30 - 9:00 AM to 5:30 - 6:00 PM).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Gems Empire Tower, 201 Truong Chinh, Thanh Xuan, Ha Noi; Minh Long Tower, 17 Bà Huyện Thanh Quan, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(400, 238, 2, 'DevSecOps Engineer', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Xây dựng và tối ưu hóa quy trình DevOps/DevSecOps, áp dụng nguyên tắc tự động hóa nhằm nâng cao hiệu quả triển khai ứng dụng công nghệ thông tin.\n- Triển khai, vận hành và quản lý các giải pháp/công cụ CICD/IaC, công nghệ Containerization/Kubernetes như GitLab, Jenkins, Nexus, Docker, ISTIO, Ansible, Rancher, v.v.\n- Đảm nhiệm các công việc triển khai (deploy), tối ưu hóa (optimizing), giám sát (monitoring), phân tích (analysis) sản phẩm.\n- Tham gia ngay từ giai đoạn phát triển sản phẩm, thiết kế các thành phần phi chức năng nhằm đảm bảo an ninh hệ thống và hỗ trợ trong quá trình vận hành, bao gồm:\n  + Thiết kế hệ thống tuân thủ các chính sách và quy định bảo mật.\n  + Chuẩn hóa logging, tracing và thông tin monitoring, sử dụng các công cụ như ELK, Prometheus, Grafana.\n\nYour skills and experience\n- Tốt nghiệp đại học các chuyên ngành Công nghệ thông tin, Toán tin, Điện tử Viễn thông, hoặc lĩnh vực liên quan.\n- Vị trí mở với ứng viên mới tốt nghiệp có đam mê với lĩnh vực DevOps, DevSecOps\n- Ưu tiên ứng viên có kinh nghiệm thực tế về DevOps/DevSecOps tại công ty công nghệ hoặc tổ chức tài chính.\n- Hiểu biết về quy trình phát triển phần mềm, quen thuộc với tư duy làm việc Agile.\n- Có kiến thức về các hệ quản trị cơ sở dữ liệu, bao gồm Oracle, SQL Server, PostgreSQL, MongoDB…\n- Kinh nghiệm xây dựng CI/CD Pipeline, sử dụng một trong số các công cụ sau: Jenkins, GitLab, Nexus, Harbor, Docker, Helm, Kubernetes, Prometheus, Grafana.\n- Tiếng Anh tốt, có khả năng làm việc trực tiếp với đối tác nước ngoài.\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n  - Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n  - Du lịch nghỉ dưỡng hàng năm\n  - Khám sức khỏe định kì\n  - Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n  - Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n- Cơ hội nghề nghiệp và phát triển bản thân:\n  - Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n  - Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n  - Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n  - Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n- Môi trường làm việc lý tưởng với:\n  - Những người cộng sự thân thiện và tài năng\n  - Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(401, 332, 2, 'Senior Technology Manager (AI/DevOps/Cloud)', 'The Senior Manager will lead and oversee the Software Engineering, Quality Control, and DevOps teams, ensuring highquality, scalable, and efficient delivery of technological products and platforms. This role requires a strong technical foundation, strategic thinking, leadership capability, and close cross-functional collaboration, particularly with Business Units, to understand their needs and design solutions that drive growth and scalability. The ideal candidate will possess an AI mindset, actively seeking opportunities to leverage AI/ML technologies within the SDLC and business applications.\n\nKey Responsibilities:\nLead, mentor, and develop the Engineering, QC, and DevOps teams to deliver best-in-class software products and services.\nCollaborate closely with Business Units (BUs): Understand BU pain points, strategic goals, and operational needs to identify opportunities and translate them into effective technical solutions.\nDesign and Architect Scalable Solutions: Lead the design of applications and platforms that support business growth, scalability, and efficiency, aligning technical architecture with business strategy.\nChampion AI Integration: Identify and evaluate opportunities to apply AI/ML technologies to improve the SDLC (e.g., AI-assisted coding, automated testing, predictive monitoring) and develop AI-powered features or applications.\nDefine and enforce technical architecture, development standards, and QA processes.\nOversee end-to-end delivery of projects, ensuring code quality, system reliability, and performance.\nImplement and optimize CI/CD pipelines, automated testing frameworks, and infrastructure as code practices.\nEnsure effective coordination between product, engineering, QC, infrastructure, and business teams.\nMonitor and improve software delivery KPIs such as cycle time, deployment frequency, system uptime, and bug rates.\nManage team structure, capacity planning, hiring, and performance reviews.\nStay up-to-date with technological trends, particularly in AI/ML and cloud-native architectures, proposing improvements to enhance productivity, security, and scalability.\n\nYour skills and experience:\n1. Education background requirements:\nBachelor’s or Master’s degree in Computer Science, Engineering, or a related field.\n8+ years of experience in software development, with significant experience in engineering leadership roles.\nProven experience managing cross-functional tech teams (Engineering, QA, DevOps).\nDemonstrated experience working directly with business stakeholders: Proven ability to understand business requirements, translate them into technical specifications, and design impactful solutions.\nStrong AI Mindset: Understanding of AI/ML concepts and practical applications. Experience or demonstrable interest in leveraging AI tools and techniques within the software development lifecycle (SDLC).\nStrong technical skills in backend/frontend development, testing frameworks, and cloud infrastructure (AWS/Azure/GCP).\nDeep understanding of Agile/Scrum methodologies and modern DevOps practices.\nExcellent communication, stakeholder management, and leadership skills.\n\n2. Bonus Points For:\nExperience implementing AI/ML solutions or integrating AI tools into development workflows.\nExperience designing and building applications specifically to address business process optimization or growth challenges.\nStrong time management skills.\nExcellent English communication (written and verbal).\nTeam player with a collaborative mindset.\nCreative problem-solver who focuses on priorities.\nAdaptable to new technologies and ideas.\nExperience with microservices architecture.\n\nWhy you\'ll love working here:\nHone your creativity, invent and innovate, and set your own highest standards within a nurturing, equal opportunity environment. With our tremendous growth, we seek dynamic, entrepreneurial and broad-minded individuals to join us.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'AB Building, 27B Nguyen Dinh Chieu, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(402, 333, 2, 'Security Solutions (Presale)', 'Job description\n1. Kỹ sư tư vấn (Pre-Sales) giải pháp ATTT\n- Có kiến thức về các giải pháp mảng ATTT (SAST, DAST, IAST, Threat Modeling…)\n- Hỗ trợ khách hàng tư vấn, thử nghiệm các giải pháp ATTT mà công ty phân phối (SAST, DAST, IAST, Threat Modeling…)\n\n2. Kỹ Năng Thuyết Trình và Giao Tiếp:\n- Chuẩn bị nội dung và thực hiện các buổi trình bày giải pháp bảo mật hoặc các buổi cập nhật công nghệ.\n- Giao tiếp hiệu quả để giải thích các vấn đề kỹ thuật phức tạp một cách dễ hiểu với khách hàng.\n- Phối hợp với các đội ngũ nội bộ để phản hồi và xử lý các yêu cầu của khách hàng.\n\n3. Quan Hệ Khách Hàng:\n- Duy trì mối quan hệ tốt với khách hàng, hỗ trợ các yêu cầu hậu mãi và nâng cao mức độ hài lòng.\n- Đề xuất nâng cấp, bảo trì hoặc mở rộng giải pháp để đáp ứng nhu cầu phát sinh của khách hàng.\n\n4. Cập Nhật Công Nghệ:\n- Nghiên cứu, học hỏi và cập nhật các công nghệ bảo mật mới nhất để hỗ trợ khách hàng tốt hơn.\n- Tham gia các chương trình đào tạo nội bộ hoặc bên ngoài để nâng cao kỹ năng chuyên môn.\n\nYour skills and experience\n1. Kiến Thức và Kinh Nghiệm:\n- Tốt nghiệp đại học chuyên ngành Công nghệ Thông tin, An ninh mạng, hoặc các ngành liên quan.\n- Có từ 2-3 năm kinh nghiệm trong triển khai hoặc tư vấn các giải pháp an toàn thông tin.\n\n2. Kỹ Năng:\n- Kỹ năng phân tích và xử lý vấn đề tốt.\n- Kỹ năng thuyết trình và giao tiếp tốt, đặc biệt là với khách hàng.\n- Có khả năng làm việc độc lập và phối hợp nhóm hiệu quả.\n\n3. Chứng Chỉ Ưu Tiên (không bắt buộc):\n- Các chứng chỉ bảo mật cơ bản như AWS, CompTIA Security+, hoặc tương đương là lợi thế.\n\n4. Ngôn Ngữ:\n- Tiếng Anh cơ bản: có khả năng đọc hiểu tài liệu kỹ thuật và giao tiếp.\n\nWhy you\'ll love working here\n- Lương tháng 13, Chế độ thưởng hấp dẫn\n- 12-15 ngày nghỉ phép hàng năm\n- BHXH, BHYT; Du lịch hàng năm; Trợ cấp taxi; điện thoại\n- Được cấp máy tính xách tay để làm việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phòng 1701 Toà G3 khu đô thị Vinhomes Greenbay, số 7 Đại Lộ Thăng Long, phường Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(403, 334, 2, 'ReactJS Developer - Level Middle', 'Voyager is looking for a Middle-Level ReactJS Developer to join our product development team. This role requires building and optimizing high-quality user interfaces (UI), integrating with backend systems, and ensuring a smooth user experience. The ideal candidate has hands-on experience with ReactJS, strong logical thinking, and a continuous learning mindset.\n\nJob Responsibilities\n\n- Develop features based on customer and project requirements, ensuring high quality, testability, and maintainability.\n- Conduct code reviews as per guidelines, propose solutions, and contribute to team/project direction.\n- Work closely with the IT Comtor (Japanese translator/interpreter) and other team members to clearly understand and effectively implement project requirements.\n- Estimate task completion time and commit to meeting deadlines.\n- Regularly report progress and work status.\n- Support and mentor new team members (with a growth path toward a Senior Leader position).\n- Further details will be discussed during the interview.\n\nYour skills and experience\n\nRequirements\n\n- Graduated from a university/college majoring in Information Technology or an equivalent field.\n- 2–4 years of experience in ReactJS development.\n- Proficient in JavaScript (ES6+), HTML5, and CSS3.\n- Experience with state management libraries such as Redux, Zustand, or Context API.\n- Knowledge of Responsive Design and Cross-browser Compatibility.\n- Experience working in Agile processes.\n- Strong logical thinking, a proactive attitude, and a high sense of responsibility.\n\nPreferred Qualifications\n\n- Experience with Figma and Docker.\n- Familiarity with CI/CD and Unit Testing (Jest, React Testing Library).\n- Previous experience in UI/UX design.\n- Full-stack development experience with PHP (Laravel) backend.\n\nWhy you\'ll love working here\n\nSalary & Benefits\n\n- Salary up to 30 million VND/month or higher, negotiable based on capability.\n- Performance review 1–2 times per year with performance-based bonuses.\n- Full benefits package: 13th-month salary, Social Insurance, Health Insurance, and extended PVI health insurance.\n- 100% support for professional development courses (e.g., advanced React, Japanese language).\n- Working equipment provided: MacBook Pro or other devices as required.\n- Company culture & events: Birthday parties, team-building activities, and regular internal events.\n- Office amenities: Foosball, ping-pong table, free coffee and snacks.\n\nCareer Path\n\n- Opportunities to be promoted to Senior Developer, Tech Lead, or Fullstack Developer.\n- Career development guidance and check-ins every 6 months.\n- Clear personal and team goal-setting.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 02, SBI Building, Street 03, Quang Trung Software City, Tan Chanh Hiep Ward, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(404, 292, 2, 'HO - CVCC Phát triển ứng dụng thẻ (Backend, Golang)', 'Job description\n- Design and develop features for Card Development team.\n- Design database schema.\n- Write clean and maintainable code.\n- Work directly with other teams to discuss and build the high quality product.\n\nYour skills and experience\n- At least 1+ years of Golang.\n- Experience in working with Database both relational and non-relational.\n- Experience in writing good unit tests.\n- Experience with API, Restful, GRPC.\n- Knowledge about HTTPS, TLS.\n- Proficient in source version control like git, gitlab.\n- Familiarity with container like docker, kubernetes.\n- We welcome the engineers who want to learn Golang.\n\nWhy you\'ll love working here\n- 100% salary in probation\n- 13th month salary, year-end bonus from 2-6 months salary base\n- Competitive salary, commensurate with ability\n- Working environment with deep specialization\n- Evaluation for annual salary increase\n- Bonus and welfare regime\n- Regular internal training in professional knowledge and soft skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark Building, 15 Tran Bach Dang Str, Thu Thiem Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(405, 335, 2, 'QA/QC/Tester', 'Forix is looking for an experienced QA/QC/Tester to join our award-winning team that specializes in providing ongoing ecommerce support and development services using Magento, Shopify, BigCommerce to clients around the world.\nIn this position you will be responsible for testing complex web applications to ensure proper functionality. Candidates with a strong performance in this position typically have an opportunity to advance into Project Manager Assistant or Project Management roles within the company.\n\nJob Description\n- Create and execute test cases based on project specifications (functional, application, and regression).\n- Troubleshoot and assess test issues to determine failure points.\n- Provide estimates for testing task times and meeting durations.\n- Manage testing schedule\n- Report and document bugs/issues in a clear, timely, and concise manner.\n- Work closely with our development team to ensure delivery of quality implementations.\n- Escalate project issues to management when appropriate.\n- Identify potential project risks and provide recommendations to mitigate risks.\n\nYour skills and experience\n- A minimum of 1 year of experience in a web testing position is required.\n- Excellent attention to detail, communication, and organizational skills are a must.\n- Experience testing on eCommerce websites and CMS systems.\n- Experience with Magento/Shopify/BigCommerce is a big plus.\n- Solid understanding of various testing types and techniques are needed.\n- Comprehensive verbal and written communication skills are needed.\n- Advanced English proficiency is needed.\n\nWhy you\'ll love working here\n- High, competitive base salary\n- 13th month salary\n- Monday-Friday work week (9AM-6PM)\n- Ongoing education and training opportunities\n- Monthly team building events\n- Annual company retreat\n- Personal Healthcare Insurance\n- Annual Healthcare Checkup\n- 15 days leave per year\n- Christmas Holiday\n- Daily tea, snack, and fruit breaks\n\nFor more information about us, please visit our website at www.forixcommerce.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '82 Tran Huy Lieu, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(406, 336, 2, 'Project Manager Tiếng nhật  N2 (Java/Agile/Team Leader)', 'Top 3 reasons to join us\n- 13th Salary + Yearly Performance Bonus\n- Amazing training and development opportunities\n- Health Insurance Package\n\nJob description\n- Tham gia quản lý dự án với teamsize tối thiểu từ 3 người trở lên\n- Tiếp nhận phân công dự án từ trưởng phòng và lập kế hoạch thực hiện\n- Trao đổi trực tiếp với khách hàng và các bên liên quan trong quá trình thực hiện\n- Quản lý tiến độ, chất lượng, quản lý các thành viên trong nhóm dự án, sử dụng hiệu quả tài nguyên được cấp\n- Trực tiếp chỉ đạo và thực hiện các công việc dự án để đảm bảo thành công của dự án trên 3 yếu tốt cốt lõi (Chất lượng, Chi phí và Tiến độ)\n- Báo cáo và đề xuất cách giải quyết vấn đề, các rủi ro cho trưởng phòng\n\nYour skills and experience\n- Tốt nghiệp ĐH (hoặc tương đương) ngành CNTT- Phần mềm\n- Tiếng Nhật từ N2 trở lên (Kĩ năng hội thoại tốt)\n- Có kinh nghiệm từ 1 năm trở lên về quản lý dự án với team size ít nhất 5 người\n\nƯu tiên (nếu có)\n- Có kinh nghiệm trong ngành outsourcing phần mềm cho thị trường Nhật\n- Có chứng chỉ PMP/ACP và sẵn sàng đi công tác nước ngoài\n- Có kiến thức về các best practices trong phát triển và triển khai dự án phần mềm web bằng Java & Spring Framework về các lĩnh vực ERP, CRM, Finance solutions etc..\n- Có kinh nghiệm quản lý các dự án theo nhiều mô hình khác nhau như Agile, Waterfall\n- Có khả năng thực hiện estimation\n\nWhy you\'ll love working here\nChế độ đãi ngộ:\n- Lương thỏa thuận theo năng lực thực tế của ứng viên lên tới 2500$. Review lương: 1 lần/năm.\n- Trợ cấp đi lại, trợ cấp ăn trưa, trợ cấp tiếng Nhật, trợ cấp onsite khi tham gia dự án bên khách hàng…\n- Thưởng lễ tết, thưởng tháng lương thứ 13, thưởng nhân viên xuất sắc quý, năm, nhân viên tiêu biểu đi du lịch Nhật Bản.\n- Nghỉ theo lịch công ty, nghỉ theo lịch khách hàng Nhật, ngoài các ngày nghỉ theo quy định, 1 năm có thêm 2 đợt nghỉ dài.\n- Nghỉ tham gia Ngày hội khai giảng cùng con\n- Chế độ chăm sóc phụ nữ: Nghỉ sinh lý phụ nữ: 8h/ tháng; Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày\n- Chế độ làm việc từ xa chăm con ốm, và các bệnh khác theo quy định\n- Chương trình đào tạo gắn liền lộ trình thăng tiến\n\nChế độ chăm sóc sức khỏe cho nhân viên:\n- Bảo hiểm y tế, bảo hiểm xã hội, bảo hiểm thất nghiệp theo quy định của Luật lao động.\n- Bảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên.\n- Khám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín (Bệnh viện Thu Cúc, bệnh viện Medlatec…)\n\nVăn phòng làm việc tiện ích:\n- Miễn phí trà, coffee tại khu vực ăn uống của công ty.\n- Máy pha coffee, máy bán hàng tự động tiện ích ngay tại công ty.\n- Mượn sách và tạp chí tại thư viện\n\nCác hoạt động sôi nổi:\n- Hoạt động team building kết nối đội nhóm hàng quý.\n- Các CLB thể thao: bóng đá, bi lắc, bóng bàn, văn nghệ…\n- Hoạt động du lịch thường niên và các sự kiện lớn trong công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '266 Doi Can, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(407, 259, 2, 'Cloud Platform Engineer (Remote)', 'Resola Inc, a pioneering force in AI solutions for marketing and advertising, is seeking an experienced Cloud Platform Engineer to join our innovative team. As a key member of Resola\'s engineering division, you\'ll be responsible for designing, implementing, and maintaining our cloud infrastructure while adhering to best practices in security, scalability, and efficiency.\n\nWe are dedicated to empowering organizations to harness the full potential of artificial intelligence responsibly and efficiently. Our diverse team of 75 employees representing 9 nationalities works in a collaborative environment where innovation meets practical business applications.\n\nResponsibilities\n- Design and implement scalable, secure cloud infrastructure using Infrastructure as Code principles\n- Manage and optimize AWS resources and services across multiple environments\n- Implement and maintain comprehensive monitoring, alerting, and logging systems\n- Configure and manage CI/CD pipelines for automated deployments\n- Optimize infrastructure costs and resource utilization\n- Implement security best practices and ensure compliance requirements\n- Collaborate with development teams to improve deployment processes\n\nRequirements\n- 5+ years of experience in cloud infrastructure engineering\n- Strong expertise in AWS services, security, and infrastructure best practices\n- Expertise in cloud platforms (Azure, GCP and others)\n- Proficiency in Infrastructure as Code tools (e.g., Terraform, CDK, CloudFormation)\n- Experience with CI/CD tools and DevOps practices\n- Strong background in cloud security architecture and implementation\n- Proficiency in English (for internal communication)\n\nWhat We Value\n- Security-first approach to infrastructure design\n- Commitment to continuous learning and knowledge sharing\n- Data-driven decision making\n- Collaborative spirit and excellent communication skills\n\nWhy you\'ll love working here\nWe Offer\n- A position open to all levels – whether you’re just starting or you’ve been coding for years, we encourage you to apply.\n- A competitive salary with a transparent progression pathway.\n- A flexible and supportive work environment that values work-life balance.\n- Opportunities for personal and professional development.\n- A dynamic, multicultural team with a passion for building great software.\n- Up to 10 days of paid day off.\n- Up to 16 days of public holidays per year.\n- Performance and salary review every 6 months.\n- Opportunity for a bonus every 6 months based on results and outcomes.\n\nOur products and services\nDECA is an all-in-one digital marketing platform that helps businesses of all sizes to plan, execute and optimize their online marketing campaigns. With a user-friendly interface and advanced features, Deca simplifies the complex process of digital marketing and enables businesses to achieve their marketing goals with ease.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remotely, Other, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(408, 337, 2, 'Senior Fullstack TypeScript Developer (ReactJS/API/LLM)', 'We\'re looking for an exceptional Fullstack TypeScript Developer with strong front-end expertise and a passion for integrating cutting-edge AI and LLM technologies. In this senior position, you\'ll lead technical efforts, motivate your team, and make key contributions to architectural decisions. You’ll also design, develop, and deploy sophisticated backend APIs, ensuring seamless integration with AI-powered solutions. This role blends advanced front-end engineering with backend development and strategic involvement in cloud infrastructure decisions.\n\nWhat you’ll do: \n- Build sophisticated, high-performance user interfaces integrating TypeScript and modern front end frameworks. \n- Design and implement robust backend APIs to support advanced application functionality, including AI integrations. \n- Lead technical discussions, motivate your team, and align efforts towards strategic product goals. \n- Translate complex business and user requirements into seamless digital experiences. \n- Collaborate closely with UX/UI designers and backend engineers to ensure cohesive application experiences. \n- Actively participate in architectural decision-making, guiding the adoption of emerging technologies and best practices. \n- Bring good vibes to the team — whether it’s sharing memes, spontaneous coffee debates, or just making the daily standup a bit less boring.\n\nYour skills and experience\n\nEssential Skills \n- Fullstack TypeScript Expertise: Exceptional proficiency across frontend and backend TypeScript development. \n- Modern Front-End Frameworks: Deep experience with React, Next.js, Node, Vercel, Deno, or Bun. \n- Web Fundamentals: Strong grasp of responsive design, performance optimisation, and emerging web standards.\n- Backend APIs: Proven confidence and experience creating secure, scalable backend APIs. \n- Design & UX/UI: Clear understanding of design principles, UI & UX best practices.\n- LLM & AI Integration: Strong interest in integrating Large Language Models and AI-driven solutions into web applications. \n- Cloud Infrastructure: Practical experience deploying solutions within cloud environments (AWS, GCP). \n\nDesirable Skills \n- Experience with DevOps practices, Docker, and CI/CD pipelines.\n- Familiarity with testing frameworks such as Jest, Cypress, or Playwright. \n- Practical knowledge of accessibility (WCAG) and cross-browser compatibility. \n\nSoft Skills\n- Architectural Decision-Making: Contribute strategically to architectural decisions, providing clear insights into best practices. \n- Attention to Detail: Commitment to delivering highly polished, performant, and user-friendly solutions.\n- Fluent in English communication and reported directly to an Australian manager.\n\nWhy you\'ll love working here\n- Full social and health insurance in accordance with regulations\n- Annual company trip \n- Flexible working hours and remote work options\n- Opportunity to work on cutting-edge AI applications \n- Collaborative, growth-focused team environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '62 Võ Văn Tần, P. Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(409, 209, 2, 'Leader for Platform Team (onsite China)', 'A subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nPROJECT OVERVIEW\n\nYou will take part in multi-million project for high-profile customer, which are automotive industry leaders Japan (Onsite China).\nYou will work on a full life cycle for automotive software used in a car such as Autosar software.\nYou have a great career advance to expand your horizon not only in the automotive industry but also the international working experience.\n\nRESPONSIBILITIES\n\nManage Development full life cycle of automotive software for various microcontrollers\nWork with various kinds of microcontroller from Renesas, NXP, …\nPerform Requirement Analysis, (high and low) Design, Coding, Unit Testing, Integration Testing and Quality Testing\n\nYour skills and experience\n\nMust have:\n\nWorking experience in programming in C/C++, Embedded system development, Platform Development.\nWorking experience in development of full life cycle for automotive software (Requirement Analysis, (High-Low) Design, Coding, Unit Testing, Integration Testing and Quality Testing).\nDevelopment experience in RTE, OS, BSW, MCAL module layer and CDD.\nDevelopment experience on Automotive microcontroller families like Renesas, NXP, …\nDevelopment experience in COM Stack, Mem Stack…\nKnowledge of Compilers, Debuggers for different micro-controllers\nExperience with configuration tools and testing devices (e.g. Davinci, EB Tresos, CANoe, CANalyzer, VFlash, etc.)\nGood knowledge of hardware, software embedded system concepts and architecture.\nGood understanding of the embedded software build process (compiling, linking, programming, etc.).\nAbility to troubleshoot issues to resolution. Strong problem solving and root cause analysis skills.\nExperience with configuration management software (SVN, GIT)\nAbility to analyze / study new technical, new hardware\nTeamwork and communication skills.\nGood in Japanese level: Can communicate/explain with customers about output/input (N3+).\nGood in English communication is a strong plus point.\n\nNice to have:\n\nWork experience in post-build is plus point.\nWork experience on AUTOSAR compliant BSW software, MCAL driver development is a strong plus.\nOverall understanding of automotive systems.\n\nWhy you\'ll love working here\n\nFPT Care insurance plan tailored for FPT employees\nAttractive annual summer vacation allowance\nSponsored training courses for personal growth and up to 100% coverage for certification costs\nGlobal and inclusive workplace with monthly cross-cultural events\nInternational exposure and career growth across global locations\nWork-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Software Đường D1 Phường Tân Phú , District 9, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(410, 207, 2, 'Mobile Android App Dev (Java/Kotlin/OOP/Swift/Web API)', '• Responsible for developing Android application using Kotlin: Analyze requirement, Design app structure, implement, unit test.\n• Responsible for common mobile app development: Cross-platform app, iOS app\n\nYour skills and experience\n\n1. Must have\n• 2+ years of Android application experience. (Kotlin, Java)\n• Strong knowledge of OOP, data structure and algorithm.\n• Strong experience on database, caching, lazy loading, background threads, networking, camera...\n• Experience with connect and transfer data via HTTP/HTTPS, BLE, NFC…\n• Familiarity with RESTful APIs to connect to back-end services.\n• Familiarity with MVVM, MVP, Android Architecture components\n• Able to develop cross-platform app is big plus: Flutter, React Native, or iOS app Swift/Objective C\n• Experience working in an environment using Agile/Scrum\n• Passionate in mobile software engineering and mobile products\n• A graduate from Computer science/Informatics, Information System or Computer Engineering or equivalent from reputable university.\n• Personal Qualifications: Creative thinking, hard work, enthusiasm, high responsibility in the work and willing to learn new things, English is fluent.\n\n2. Nice to have\n• C++, Swift/Objective C are preferred.\n• Experience in backend-cloud development is big plus.\n• Experience with application security, AI algorithm.\n\nWhy you\'ll love working here\n\nPanasonic R&D Center Vietnam was established in April 2007, is a company specializing in R&D of Panasonic Group in Vietnam with the aim of enhancing R&D activities in the field of digital home appliances, automation, mobility in Vietnam, providing R&D services for software solutions in today\'s hottest fields such as AI, Cloud, IoT in a chain of R&D centers of worldwide corporations.\n\n1. Career Path Development\n• Long-term multi-career roadmap;\n• Learning & development (Language Training, Technical Training, Soft-skill Training, On-job Training, etc.)\n• Oversea business trips (Japan, China, Singapore, US, Mexico, EU, etc.)\n2. Work-life Balance\n• Flexible working time that supports work-life balance (Core time: 9:00-16:00; 5 days from Monday - Friday/ week)\n• Additional special holiday\n3. Compensation package\n• Attractive salary\n• Competitive bonus package depend on abilities, performance and competencies\n• Diversified allowance scheme\n4. Wellness\n• Well-protected with 24/7 personal accident and medical care insurance;\n• Well-designed Annual Health Check-up program;\n5. Activities\n• Team-building activities; Birthday Party; Year-end party; Sport Day/ Family Day\n• Summer Vacation (Trip to famous tourist spots domestic/ overseas,…)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lotte Tower, 54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(411, 338, 2, 'Trưởng Phòng Phát Triển Sản Phẩm (Product Manager)', '1. XÂY DỰNG SẢN PHẨM\n- Là người đồng kiến tạo triết lý và linh hồn sản phẩm – từ tầm nhìn, mục tiêu đến hành vi sản phẩm.\n- Hiểu và dẫn dắt sản phẩm như một cơ thể sống: có hồn, có tính cách, có trải nghiệm đầy cảm xúc.\n- Chịu trách nhiệm định hướng dài hạn sản phẩm: tính nhất quán, bản sắc và giá trị cốt lõi.\n\n2. THỰC CHIẾN – KẾT NỐI – ĐO LƯỜNG – TỐI ƯU\n- Dẫn dắt toàn bộ vòng đời sản phẩm: nghiên cứu – thiết kế – phát triển – triển khai – đánh giá – tối ưu.\n- Làm việc chặt chẽ với đội ngũ phát triển, UX/UI, QA, vận hành và marketing để đảm bảo tính khả thi và hiệu quả.\n- Sử dụng dữ liệu để ra quyết định sản phẩm, theo dõi các chỉ số: retention, conversion, NPS, CLV, churn rate, v.v.\n- Chăm chút trải nghiệm người dùng đến từng chi tiết – từ giao diện đến hành vi tương tác.\n\n3. XÂY ĐỘI NGŨ – XÂY VĂN HÓA – XÂY HỆ THỐNG\n- Tuyển chọn, huấn luyện và phát triển đội ngũ sản phẩm phù hợp với giá trị cốt lõi của PayTech.\n- Thiết lập quy trình quản lý sản phẩm tinh gọn, minh bạch, hướng đến hiệu quả.\n- Truyền cảm hứng, tạo môi trường học tập liên tục và phản biện tích cực.\n- Là cầu nối giữa chiến lược công ty và đội sản phẩm, cùng ban lãnh đạo đồng hành xây tầm nhìn chung.\n\nKiến thức & Kinh nghiệm:\n- Tối thiểu 3–5 năm kinh nghiệm làm Product Manager hoặc tương đương.\n- Từng xây dựng, quản lý hoặc ra mắt sản phẩm thực tế có người dùng.\n- Hiểu sâu mô hình vận hành sản phẩm SaaS / fintech / loyalty là lợi thế.\n- Có khả năng tổ chức, đánh giá và cải tiến quy trình sản phẩm.\n\nKỹ năng & Phẩm chất:\n- Kỹ năng phân tích, phản biện, ra quyết định dựa trên dữ liệu.\n- Giao tiếp rõ ràng, kể chuyện tốt, truyền cảm hứng.\n- Tư duy hệ thống, tư duy người dùng và tư duy chiến lược.\n- Chính trực, dấn thân, cam kết và có lòng tự trọng nghề nghiệp cao.\n\nWhy you\'ll love working here\n1. Lương: Lương thoả thuận theo năng lực và kinh nghiệm\n2. Thưởng: Theo quy định của Công ty.\n- Thưởng năm: định mức 01 tháng lương 13 theo thâm niên và thưởng thêm theo kết quả công việc\n- Thưởng lễ Tết (08/03, 20/10, 30/04 và 01/05, 02/09, 1/1, ...)\n3. Phúc lợi:\n- Du lịch hàng năm\n- Bảo hiểm xã hội, y tế theo luật định.\n- Khám sức khỏe định kỳ 06 tháng/1 lần\n- Nghỉ thứ Bảy và Chủ nhật.\n- Môi trường làm việc chuyên nghiệp, năng động, sáng tạo và luôn được khuyến khích cải tiến.\n- Được đào tạo Nghiệp vụ và Kỹ Năng liên tục, có cơ hội thăng tiến lên các vị trí cao hơn.\n- Cơ sở vật chất, công cụ làm việc hiện đại, tiện nghi, ứng dụng công nghệ, chuyển đổi số\n- Cơ hội làm việc và phát triển tại Công ty công nghệ sáng tạo trong lĩnh vực thương mại điện tử, loyalty, ví điện tử, truyền thông, dịch vụ giá trị gia tăng, truyền thông.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ICOM Building, số 17/93 Trần Thái Tông, Dịch Vọng, Cầu Giấy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(412, 339, 2, 'Junior/Middle Automation Tester (Python)', 'Top 3 reasons to join us\n\n- Very attractive salary package & performance bonus\n- 20 days annual leaves\n- Full legal package and 100% salary on probation\n\nJob description\n\nPosition Summary:\n- Design, maintain an automation framework and develop automation test cases using Behave Python.\n\nResponsibilities:\n- Complete assigned tasks from your direct superior(s) on time.\n- Determine test objectives through detailed analysis in order to automate features comprehensively.\n- Develop, plan and implement automated test cases based on software requirements and technical understanding.\n- Develop and extend the current test automation infrastructure to be more efficient, both in execution and in reporting.\n- Run tests (including manual tests, automation tests, or both) against UAT builds/releases during the development lifecycle.\n- Perform manual testing upon request for simple features.\n- Take responsibility for certifying the quality of the product.\n- Create bug reports in Bug Tracking systems and follow Bug life cycle.\n- Report testing status and test results (daily or weekly) to superior(s) accurately and promptly.\n- Support, mentor, or coach members when needed.\n\nYour skills and experience\n\n- Degree in IT/Computer Science/Computer Engineering or related discipline.\n- Programming skill is a MUST (Python)\n- 1+ years’ experience in Web automation testing using BDD framework (Behave is preferred)\n- 1+ years’ experience in API automation testing (Python, JMeter, Postman, etc.)\n- Have good knowledge of testing methodologies & techniques and the defect reporting process.\n- Experience with Version Control (SVN, GIT), CI/CD system (Jenkins).\n- Experience in testing web-based applications is required.\n- Experience with defect tracking systems and quality assurance tools (Jira, Confluence, TestRail).\n- Problem Solving skill, Issue escalation skill, Time management skill.\n- Interpersonal and communication skills, both oral and written.\n- Able to work in a dynamic and ever-changing industry.\n- Good English written and verbal communication skills are preferred.\n- Logical thinking, detail-oriented, willing to take challenges.\n- Be able to work in a fast-paced environment.\n\nWhy you\'ll love working here\n\n- Attractive compensation, regular assessments, and salary reviews;\n- 13th-month salary and annual bonus;\n- 20 days annual leave;\n- 100% salary during the probation period;\n- 100% social insurance, premium healthcare insurance, and annual routine check-up;\n- Unlimited access to a selection of food and beverages;\n- Special celebrations on 8/3, Father\'s day, 20/10, Christmas, Tet holiday, etc.;\n- Company activities: annual teambuilding, New Year party, quarterly company party, weekly fruits day, monthly birthday, etc.;\n- Sports activities: badminton, football, bowling, cycling, etc.;\n- In-house acoustic music band;\n- Cinema days with blockbuster movies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 12, Hai Au Building, 39B Truong Son Street, Ward 4, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(413, 340, 2, 'Smart Contract Engineer (Blockchain, Solidity)', 'Top 3 reasons to join us\n- Saturday & Sunday off.\n- Blockchain Technology training.\n- Free lunch, free parking, Company trip.\n\nJob description\nWhat you\'ll be doing:\n- Participate in the entire blockchain development lifecycle, from design and architecture to implementation using smart contracts.\n- Write unit tests to ensure the reliability and performance of applications.\n- Work closely with the project team to deliver new features on schedule.\n- Stay updated on new blockchain technologies and improve workflows for better system performance.\n\nYour skills and experience\nRequirements:\n- Mid/Senior: Minimum 2 years of hands-on experience with smart contracts and 3 years of general programming experience.\n- Proficiency in Solidity, Typescript.\n- Experience with development tools like Foundry, Viem, Hardhat, and Ether.\n- Solid understanding of common smart contract attack vectors.\n- Strong foundation in algorithms, data structures, and cryptography.\n- Ability to write clean, well-documented, and maintainable code.\n\nNice to Have:\n- Familiarity with popular DeFi protocols like Uniswap, Aave, MakerDao.\n- Experience with chain development toolkits such as Arbitrum Orbit.\n\nWhy you\'ll love working here\n- Saturday & Sunday OFF\n- Blockchain Technology training.\n- Social & Health insurance according to Vietnam Labour Law.\n- 13th salary.\n- Free lunch.\n- Free parking.\n- Company trip.\n- Regular team building activities.\n- Exciting work environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '133 Dương Bá Trạc (ngay cầu Nguyễn Văn Cừ Q1), District 8, Ho Chi Minh', 'Contract', '2025-10-07 20:59:18.149534'),
	(414, 341, 2, 'AI Engineer (Min 3y exp, Upto 40M, BH Full lương, BHSK)', 'Top 3 reasons to join us\n• Mức lương cạnh tranh, Thử việc 2 tháng 120% lương \n• Bảo hiểm full lương\n• Bảo hiểm sức khỏe\n\nJob description\n• Nghiên cứu, xác minh và báo cáo các công nghệ mới như đảm bảo chất lượng AI\n• Phát triển các công nghệ mới liên quan đến chất lượng phần mềm, triển khai trong các tool, v.v.\n• Triển khai và cải tiến các thuật toán và mô hình theo yêu cầu ứng dụng trong thực tế\n• Cộng tác với các kỹ sư phần mềm để tích hợp các mô hình máy học vào hệ thống sản xuất, đảm bảo khả năng mở rộng, độ tin cậy và hiệu suất\n• Sử dụng/tối ưu hóa các mô hình ngôn ngữ lớn như GPT (Generative Pre-training Transformer) cho các trường hợp sử dụng cụ thể trong Kiểm thử phần mềm\n• Nghiệp vụ phát triển nghiên cứu liên quan đến test, phát triển và thiết kế hệ thống cùng với sự hợp tác của bộ phận R&D của khách hàng phía Nhật Bản (nghiên cứu ứng dụng)\n• Giải quyết các bài toán về Machine Learning, Deep Learning, Big Data khác\n• Các công việc liên quan khác theo yêu cầu của trưởng bộ phận\n\nYour skills and experience\n• Trên 3 năm kinh nghiệm trong lĩnh vực AI, Machine Learning, Deep Learning, từng tham gia phát triển các mô hình học sâu phục vụ các bài toán trong AI\n• Đã làm việc trên nhiều nền tảng học sâu phổ biến như TensorFlow, Keras, Caffe, PyTorch, v.v.\n• Từng tham gia ít nhất 01 dự án hoặc đề tài R&D liên quan đến AI hoặc các ứng dụng học máy chuyên sâu\n• Thành thạo các ngôn ngữ lập trình như Python, C/C++, có khả năng xử lý các bài toán phức tạp, tối ưu hóa hiệu năng hệ thống.\n• Có kinh nghiệm xây dựng, huấn luyện và triển khai các mô hình LLM (Large Language Models) cho các ứng dụng xử lý ngôn ngữ tự nhiên (NLP), đặc biệt là các hệ thống sinh văn bản, truy vấn ngữ nghĩa, và trợ chuyện thông minh\n• Thành thạo trong việc phát triển và tối ưu hóa các mô hình RAG (Retrieval-Augmented Generation), phục vụ cho các hệ thống AI đàm thoại, chatbot nội bộ, và tìm kiếm ngữ nghĩa tăng cường.\n• Có hiểu biết sâu về các kỹ thuật OCR (Optical Character Recognition), từng triển khai các pipeline trích xuất văn bản từ hình ảnh tài liệu đa ngôn ngữ, tích hợp với các mô hình NLP để phân tích và xử lý văn bản\n• Tuân thủ nghiêm ngặt các tiêu chuẩn lập trình như PEP8 đối với Python, đảm bảo mã nguồn rõ ràng, dễ bảo trì và có khả năng mở rộng\n• Có khả năng đóng gói, triển khai, tích hợp AI model vào các sản phẩm thực tế\n• Thành thạo các công cụ quản lý mã nguồn như Git, SVN, có kinh nghiệm làm việc nhóm theo mô hình Agile/Scrum, đồng thời có khả năng làm việc độc lập và chủ động giải quyết vấn đề\n\nWhy you\'ll love working here\n1. Lương và Phúc Lợi\n• Rank lương theo năng lực\n• Thời gian làm việc 5 ngày/tuần, checkin linh hoạt từ 7h30 đến 8h30 (Nghỉ Thứ 7, Chủ Nhật). Nghỉ trưa 1 tiếng, từ 12h00 đến 13h00\n• Thử việc 120% lương\n• Tham gia đầy đủ Bảo hiểm tuân thủ theo Luật Lao động hiện hành (Đóng full lương)\n• Bảo hiểm sức khỏe\n• Hỗ trợ ăn trưa\n• Khám sức khỏe định kỳ hàng năm\n• Tối thiểu 13 tháng lương 1 năm, và các khoản thưởng vào các ngày lễ khác\n• Thưởng giới thiệu ứng viên 20M – 40M/1 người tùy từng thời điểm\n• Thưởng bằng cấp 5-20M/1 lần\n• Thưởng lễ tết 1M/1 lần\n• Tiền ma chay, hiếu hỉ 2M/1 người\n• Đánh giá tăng lương 2 lần/năm\n• Tham gia các sự kiện ngoại khóa, hoạt động Team Building, Workshop, tiệc sinh nhật hàng tháng,...Duy lịch 1 lần/năm trong nước hoặc nước ngoài\n\n2. Cơ hội nghề nghiệp\n• Làm việc, học hỏi và phát triển cùng đồng nghiệp là những kỹ sư trẻ tài năng, đam mê và có lý tưởng lớn\n• Được tham gia các chương trình training về kỹ năng công nghệ và kỹ năng mềm, phương pháp làm việc\n• Được tư vấn và chia sẻ về phát triển năng lực và nghề nghiệp bản thân\n• Có nhiều cơ hội đi onsite làm việc tại Nhật\n\n3. Môi trường làm việc\n• Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, công bằng\n• Có cơ hội thăng tiến lên các vị trí Leader, quản lý\n• Tinh thần làm việc nhóm tốt, hỗ trợ nhiệt tình từ đồng nghiệp\n• Tham gia các khóa học training tiếng Nhật, kỹ năng mềm, kiến thức kỹ thuật\n• Tham gia các Club Game, Bóng đá, Tiếng Nhật\n• Có cơ hội làm việc và đào tạo tại Nhật Bản', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 23+26, Tòa nhà Handico Tower, Khu đô thị mới Mễ Trì Hạ, đường Phạm Hùng - Phường Mễ Trì - Quận Nam Từ Liêm - Hà Nội, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(415, 341, 2, 'Business Analyst/BrSE (Japanese N1/N2), Upto 2500$', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, Thử việc 2 tháng 120% lương\n- Bảo hiểm full lương\n- Bảo hiểm sức khỏe\n\nJob description\n- Là cầu nối với các tập đoàn Nhật Bản bao gồm Khách hàng và công ty mẹ ... (Sử dụng tiếng Nhật)\n- Thu thập và phân tích yêu cầu của khách hàng sau đó cùng với đội phát triển phân tích các thông số kỹ thuật của dự án để thống nhất với khách hàng\n- Triển khai yêu cầu tới đội phát triển và quản lý yêu cầu trong suốt dự án\n- Chịu trách nhiệm thực hiện UAT đảm bảo nghiệp vụ của dự án được thực hiện đúng theo yêu cầu của khách hàng trước khi bàn bàn giao\n- Thực hiện các công việc theo yêu cầu của Manager\n\nYour skills and experience\n- Có từ 3 năm kinh nghiệm làm việc tại các vị trí BrSE/BA/Tester/Comtor/PO...\n- Tốt nghiệp đại học các ngành CNTT, HTTT, KHMT hoặc ngành ngôn ngữ Nhật\n- Có khả năng phân tích yêu cầu, truyền đạt thông tin tốt\n- Tiếng Nhật từ JLPT N2 trở lên, tốt cả 4 kỹ năng\n- Ưu tiên ứng viên nếu có:\n- Có kinh nghiệm phát triển\n- Có khả năng giao tiếp Tiếng Anh\n- Có kinh nghiệm làm việc liên quan đến AI\n\nWhy you\'ll love working here\n1. Lương và Phúc Lợi\n- Rank lương theo năng lực\n- Thời gian làm việc 5 ngày/ tuần, checkin linh hoạt từ 7h30 đến 8h30 (Nghỉ Thứ 7, Chủ Nhật). Nghỉ trưa 1 tiếng, từ 12h00 đến 13h00\n- Thử việc 120% lương\n- Tham gia đầy đủ Bảo hiểm tuân thủ theo Luật Lao động hiện hành (Đóng full lương)\n- Bảo hiểm sức khỏe\n- Hỗ trợ ăn trưa\n- Khám sức khỏe định kỳ hàng năm\n- Tối thiểu 13 tháng lương 1 năm, và các khoản thưởng vào các ngày lễ khác\n- Thưởng giới thiệu ứng viên 20M – 40M/1 người tùy từng thời điểm\n- Thưởng bằng cấp 5-20M/1 lần\n- Thưởng lễ tết 1M/1 lần\n- Tiền ma chay, hiếu hỉ 2M/1 người\n- Đánh giá tăng lương 2 lần/năm\n- Tham gia các sự kiện ngoại khóa, hoạt động Team Building, Workshop, tiệc sinh nhật hàng tháng,...Du lịch 1 lần/năm trong nước hoặc nước ngoài\n2. Cơ hội nghề nghiệp\n- Làm việc, học hỏi và phát triển cùng đồng nghiệp là những kỹ sư trẻ tài năng, đam mê và có lý tưởng lớn\n- Được tham gia các chương trình training về kỹ năng công nghệ và kỹ năng mềm, phương pháp làm việc\n- Được tư vấn và chia sẻ về phát triển năng lực và nghề nghiệp bản thân\n- Có nhiều cơ hội đi onsite làm việc tại Nhật\n3. Môi trường làm việc\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, công bằng\n- Có cơ hội thăng tiến lên các vị trí Leader, quản lý\n- Tinh thần làm việc nhóm tốt, hỗ trợ nhiệt tình từ đồng nghiệp\n- Tham gia các khóa học training tiếng Nhật, kỹ năng mềm, kiến thức kỹ thuật\n- Tham gia các Club Game, Bóng đá, Tiếng Nhật\n- Có cơ hội làm việc và đào tạo tại Nhật Bản', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 23+26, Tòa nhà Handico Tower, Khu đô thị mới Mễ Trì Hạ, đường Phạm Hùng - Phường Mễ Trì - Quận Nam Từ Liêm - Hà Nội, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(416, 342, 2, 'Software Engineer C++', 'MiTek’s Component Manufacturing division is seeking a dynamic and passionate Software Engineer to help pioneer industry changing solutions for the residential construction industry. This position will be part of a team working on a 3D BIM solution for single or multi-family modeling, design, and estimating. Be part of a high-performing and collaborative team that is focused on innovation and engaging MiTek customers, while creating powerful software.\n\nRole, Responsibilities & Typical Activities\n• Code, enhance, test, and debug 3D CAD/Engineering desktop software using C++, C, and C#.\n• Contribute to large, breakthrough enhancements in our CAD/BIM platform. Efforts require refactoring existing logic, feasibility analysis, and creating new enhancements.\n• Collaborate with business analysts, testing, and other development teams to ensure solutions are efficient, consistent, and fulfill business needs.  \n• Perform design and analysis on efforts before starting development.\n• Author technical documents for software architecture or design as required.\n• Participate in design reviews, code reviews, and collaborative requirements reviews.\n• Apply generally accepted programming standards and techniques to ensure efficient performance and data manipulation.\n• Attendance during regular work hours and overtime as required.\n• Collaborate with multiple global teams to contribute to a large-scale project.  \n\nYour skills and experience\n• Bachelor of Science degree in Computer Science or related field. Additionally, equivalent work experience may be substituted for the degree requirement.\n• 3+ years of experience designing, developing, and deploying enterprise applications in global environments.\n• 2+ years of hands-on experience with C++ application development.\n• Experienced with desktop application development.\n• Knowledge of data structures and strong understanding of object-oriented principles.\n• Comfortable digging into large, unfamiliar codebases to diagnose, debug, and resolve critical issues\n• Familiarity with Azure DevOps for project management and source control.\n• Must possess excellent verbal and written communication skills in English and the ability to communicate in both technical and business terms. (English level B2 - CEFR or equivalent)\n\nPreferred Qualifications:\n• Understanding of mathematical concepts involving algebra and geometry\n• Understanding of SCRUM and Agile principles to collaborate effectively in a team environment.\n\nWhy you\'ll love working here\n• Extremely competitive salary.\n• 13th month & productivity Bonus.\n• Yearly salary review.\n• Healthcare insurance package.\n• 24/24 Personal accident insurance.\n• State-of-the-art office environment.\n• Yearly outing.\n• Detailed induction, training and on-going career development.\n• Opportunity for overseas training and travel.\n• English training programs.\n• 5-day week.\n• Flexible start-times.\n• Free lunch.\n• Free parking.\n• Full Social Club including gym, yoga, football, badminton, swimming.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'A5 Building, E- Office Park, Road, Tân Thuận, Đ. Sáng Tạo, Tân Thuận Đông, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(417, 343, 2, 'Sr Robotics Simulation Engineer (Machine Learning, 3D)', 'Title: Senior Robotics Simulation Engineer (Machine Learning, 3D)\nSkill Tag: Python, 3D Game, System Engineer\nBecome a crucial part of the Vietnam Software Development department at Symbotic, a pioneering US robotics warehouse automation company based in Wilmington, Massachusetts. We are seeking a passionate and experienced Simulation Engineer to drive the development of cutting-edge simulation systems and tools that are fundamental to the design, development, qualification, and successful deployment of our large-scale integrated robotic systems for warehouse automation.\n\nAs a Senior Robotics Engineer - Simulation, you will:\n- Being part of the VN Software Development department of Symbotic, an US robotics warehouse automation company based in Wilmington, Massachusetts.\n- Drive the development of simulation systems and tools responsible for supporting the design, development, qualification, and deployment of large scale integrated robotic systems for our warehouse automation system\n- Develop faster than real-time and optimized simulation environments for driving key design decisions for new systems and products\n- Take responsibility for all aspects of the simulation tools used throughout the organization including individual robots, perception, controls, fleet-level operations, routing, and system-wide simulations\n- And perform similar duties as he deems fit for the proper execution of his duties and duties as delegated by the direct manager or the Employer.\n\nYour skills and experience\nMust Have:\n- Bachelor\'s or Master\'s degree in Computer Science, Computer Engineering, Robotics, or a closely related discipline.\n- 5+ years of hands-on experience in building and simulating robots, including the development of sophisticated simulation environments and optimization solutions.\n- Hands on experience with developing 3D simulations, 3D Game (Unreal, Unity3D...), digital-twins, and faster than real-time virtual environments for real-world applications.\n- Able to apply advanced mathematical concepts.\n- Strong teamwork, communication, time management, and problem-solving skills.\n- Excellent working proficiency and clear communication skills in both spoken and written English.\n\nPreferred:\n- Solid foundation in programming (e.g., Python), firmware development, and/or system-level design. Knowledge of control theory, localization, path planning and navigation, and computer vision is a significant plus.\n- Experience with Machine Learning (ML) and cloud computing models and tools for training within simulation environments.\n- Familiarity with industry-standard rendering engines such as Nvidia Omniverse, Unity, Blender, or similar.\n\nWhy you\'ll love working here\n- (Gross) Salary $1800-$3500, Yearly adjustment \n- Social insurance, health/life/disability insurance, annual health check\n- 13th month salary \n- Yearly bonus up to 2 month pay depending on performance review\n- Hybrid working option: 1 work-from-home day per week\n- 14 days of paid vacation \n- Work laptop\n- Company trip and other team benefits', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phòng 8.04, Tầng 8, Tòa nhà IPC, 1489 Nguyễn Văn Linh, Phường Tân Phong, Quận 7, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(418, 299, 2, 'Techlead Backend (Onsite long time Japan)', 'Top 3 reasons to join us\n- Attractive salary package + signin bonus\n- Professional working environment \n- Opportunity to become core manager\n\nJob description\n- Participate in outsourcing projects for Japanese clients\n- Analyze requirements, design, and develop features based on client needs\n- Collaborate with the project team to ensure product quality\n- Report daily progress to the Team Leader/Project Manager\n\nYour skills and experience\n- Experience: At least 5 years of software development experience, with substantial expertise in Java and Spring Framework (Spring Boot, Spring Cloud, Spring Security, etc.) and FE: VueJS/ ReactJs\n- Programming Skills: Strong object-oriented programming skills, understanding of software design patterns, and ability to solve complex problems.\n- Related Technologies: Experience with related technologies such as Hibernate, JPA, RESTful APIs, Microservices, Docker/Kubernetes, JUnit, and databases like MySQL, PostgreSQL, MongoDB.\n- Teamwork Skills: Excellent communication and teamwork abilities, capable of leading and mentoring within a team.\n- Educational Background: Diploma in Information Technology, Computer Science, or a related field.\n- Soft Skills: Leadership (Team size 3 -10 members)\n- Problem-Solving: Ability to identify creative solutions to technical challenges.\n- Communication: Strong communication skills, able to clearly and persuasively convey ideas.\n- Time Management: Effective time management skills and ability to prioritize tasks appropriately.\n- Japanese N2 or higher required, fluent communication\n\nWhy you\'ll love working here\n- Working time: 10.00 am – 18.00 pm from Monday to Friday.\n  OPPORTUNITIES AND CHALLENGES:\n- Opportunity to work in a professional, modern and energizing setting.\n- Challenging projects, possibilities, cutting-edge technology, and problems.\n- An open and dynamic working atmosphere that promotes the interchange of ideas, while also empowering you to work and create in your own style. Each employee\'s talent and accomplishments are valued, and outstanding employees are recognized and rewarded on a yearly basis.\n- Opportunities for capacity development, as well as assistance with professional certification expenses, are available to those who work in the field (1 million - 5 million).\n- Some advanced certifications will cover the full cost of studying and taking the exam.\n  ATTRACTIVE REWARDING POLICY AND WORK-LIFE BALANCE:\n- Review salary 1-2 times/year, with the possibility of an unexpected salary rise based on capacity an infinite number of times per year\n- Policy for 14th-Month Salary Bonus and Holiday Bonuses According to Company Regulations.\n- Holiday travel mode (package 30.000 yen/person), team building,...\n- Full participation in social insurance, as well as a yearly health checkup at a reputable hospital.\n- Comprehensive visit policy for personnel and relatives: birthday, marriage, childbirth, illness, etc.\n- The football club, cycling car, badminton, ... are just a few of the sports and cultural activities available.\n- Allowance for classes and training awards: Learning Star of the Month,\n- A chance to be the face of the year\'s study, the royalties...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tokyo/ Fukousa/ Osaka', 'Full-time', '2025-10-07 20:59:18.149534'),
	(419, 344, 2, 'Senior Golang Developer', 'About Us\nAt our company, we\'re a team that is hardworking, logical, and fast to execute. We don\'t care what your degree is. If you\'re logical (no bullshit) and love building things that work, this is the place for you.\nWe do not accept anything mediocre. Quality of work is everything. Even if you cannot achieve perfection at the beginning, we value the relentless effort to strive toward it.\nOur product is built with Go the way it was meant to be — simple, powerful, and production-ready. We especially welcome candidates who understand that good code doesn\'t need to be complicated.\n\nYou Should Apply If\nYou loveeeeee building things — not (only) for money, but because you love creating something incredible\nYou learn new things every day — and get excited about diving deep into Go fundamentals\nYou hate over-engineered solutions to the bone — you\'ve seen too many frameworks ruin simple problems\nYou know how to ask smart questions — not just "how?" but "why?" and "is this the right approach?"\nYou believe simple code beats complex code every single time.\n\nWhat You\'ll Be Doing\nLead a team of Go developers who share your passion for clean, working code\nBuild, test, and improve production systems with a focus on real-world applications that actually work\nDesign architectures that scale — not just in theory, but in practice with real traffic\nWork with real databases — from design to optimization, including complex queries and performance tuning\nCollaborate with a small, focused team — we value clear thinking, not loud talking\nDeploy Go applications to production and optimize for performance, reliability, and maintainability\nMentor team members and help them grow their Go skills the right way\nContribute to our engineering culture — we iterate fast based on real user feedback\nMake technical decisions that affect the entire product and team.\n\nYour skills and experience\nMust-Haves\nDeep knowledge of Go and always updating your understanding of best practices.\nProduction experience with Go — you\'ve seen real systems under real load.\nLeadership experience — you can guide a team and make tough technical decisions.\nDatabase skills — comfortable with SQL, database design, and performance optimization.\nLearning mindset — this is what you do every day, naturally.\nTesting philosophy — you write tests that actually test business logic, not just coverage.\nHappy and positive attitude — because building great software should be fun.\nUnderstand life — challenges and victories are both part of the journey.\n\nNice-to-Haves\nExperience with PostgreSQL, CockroachDB, Redis, ClickHouse.\nKnowledge of Google Cloud Platform or similar.\nUnderstanding of microservices and distributed systems.\nDocker/Kubernetes experience.\nPerformance optimization and profiling skills.\n\nKey Principles & Our "Real Go" Philosophy\nWhat Makes Us Different\nNo Repository/Service layers unless necessary — we prefer simple functions over complex abstractions.\nFeature-based organization — code is organized by what it does, not by architectural layers.\nContext for dependency injection — we use Go\'s context package instead of DI frameworks.\nReal database testing — we test against actual databases, not mocks.\nHTTP 200 for business errors — clear separation between technical and business failures.\nInternal packages for shared code — proper encapsulation within modules.\n\nIdiomatic Go Practices We Follow\nError handling the Go way — explicit error returns, no exceptions or try-catch.\nInterfaces are discovered, not declared — small, focused interfaces defined by consumers.\nComposition over inheritance — embed structs and interfaces, avoid deep hierarchies.\nZero values are useful — design types so their zero value is ready to use.\nAccept interfaces, return structs — flexible input, concrete output.\nDon\'t panic in libraries — return errors instead, let callers decide.\nUse Go modules properly — semantic versioning, minimal dependencies.\nFollow Go naming conventions — MixedCaps for exported, camelCase for unexported.\nPrefer clarity over cleverness — readable code beats "smart" code every time.\nUse gofmt and go vet — consistent formatting and static analysis.\n\n"Real Go" Testing Approach\nUse Real Database instead of Mocks — create separate test databases for each test case.\nComplete Isolation — each test case has its own database, no interference between tests.\nAutomatic Setup/Teardown — databases are created and cleaned up automatically.\nReal Test Data Preparation — create actual test data instead of mocking.\nTest Real Business Logic — test validation, business rules, and database interactions together.\nDon\'t mock HTTP requests to make tests look fancy.\nDon\'t use httptest for testing business logic.\nDon\'t test routing — test business logic directly.\nWrite focused tests — test actual working functions, not wrappers.\nNo Complex Mock Objects — reduce time and errors from writing mock objects.\nUnderstand that good architecture = testable code without mocks.\n\nUnderstanding of Example Project Required\nRead and understand "This is real Go."\nDeep dive into every file in the example project, understand the structure and rationale behind each package/module.\nUnderstand the separation of business logic from transport layer.\nUnderstand using context for dependency injection.\nUnderstand database migration with embedded SQL files.\n\nAnti-patterns We Reject\nJava-style OOP in Go (We Don\'t Want This).\nRepository/Service layers everywhere — Don\'t create interfaces just because "it\'s good practice."\nDependency Injection frameworks — Use context instead of wire, dig, or fx.\nDeep inheritance hierarchies — Go doesn\'t have classes for a reason.\nGetters/Setters for everything — Use public fields when appropriate.\nFactory patterns everywhere — Don\'t create factories of factories.\nManager/Controller/Service naming — If you need a "Manager", rethink your design.\nInterface for every struct — Interfaces should be discovered, not declared upfront.\nMocking everything — Test with real databases, not mock objects.\n\n🎯 Key Principles We Follow\nFunctions over methods — Use functions unless you need state.\nComposition over inheritance — Embed structs, don\'t create hierarchies.\nExplicit over implicit — Clear dependencies, no magic.\nSimple over clever — Readable code beats "smart" code.\nDirect over abstracted — Don\'t abstract until you need to.\nReal over mocked — Test against real systems when possible.\n\n🔍 Red Flags in Code Reviews\nIf we see these patterns, we\'ll ask you to refactor:\n-Multiple layers of abstraction for simple operations.\n-Interfaces created "just in case."\n-Complex dependency injection setup.\n-Testing HTTP handlers instead of business logic.\n-Mocking databases for unit tests.\n-Manager/Service/Controller naming everywhere.\n-Deep struct embedding hierarchies.\n\nTech Stack We Actually Use (No Bloat)\nCore:\n-Go (standard library focused).\n-PostgreSQL / CockroachDB / Redis / ClickHouse.\n-Docker / Kubernetes.\nInfrastructure & DevOps:\n-Google Cloud Platform.\n-GitHub Actions.\n-NATS / Google Cloud Pub/Sub.\n-Docker / Kubernetes.\n\nWhy you\'ll love working here\nBe Part of Something Real\nFight against over-engineered solutions and build systems that actually work.\nGrow fast with biannual performance reviews and real ownership of your work.\nSalary increases based on your growth — not years of experience or politics.\n\nLearn from World-Class People\nWork with people who\'ve built production systems at scale.\nLearn from mentors who understand both the theory and practice of Go.\nNo toxic people, no politics — just passionate developers who want to build great things.\n\nWork Environment That Actually Works\nFlexible working hours — we measure output, not hours.\nNo micromanagement — we trust you to deliver results.\nConstructive code reviews — we help each other write better code.\nFast iteration cycles — see your code in production quickly.\n\nWhat We Value in People\nCan read documentation independently — no hand-holding needed.\nAsk thoughtful questions — you think before you ask.\nTake feedback without getting emotional — you understand code can always improve.\nLove learning and growing — you want to become better every day.\nHave fighting spirit — you don\'t give up when things get challenging.\nDeliver more than expected — you surprise us in good ways.\n\nIf you accept all of the above, apply now.\nPS. We want someone with a fighting attitude. If you give up easily, DO NOT apply.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vinhomes Central Park, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(420, 238, 2, '[Middle, Senior] Java FullStack Developer (Spring)', 'Top 3 reasons to join us\n  - Mức lương cạnh tranh, hấp dẫn\n  - Môi trường làm việc chuyên nghiệp, thân thiện\n  - Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n  - Phát triển, trực tiếp lập trình các hệ thống, ứng dụng của Ngân hàng, gồm các hệ thống nội bộ và ứng dụng dành cho khách hàng với quy mô 30 triệu khách hàng cá nhân và 300.000 khách hàng doanh nghiệp.\n  - Phát triển hoặc phối hợp triển khai cùng các nhà cung cấp cho các giải pháp Công nghệ.\n  - Quản lý, phát triển dịch vụ tích hợp với các hệ thống core như: T24, WAY4, BPM, CRM, CIC ...\n  - Quản lý, phát triển API trên API Gateway phục vụ tích hợp với các đối tác trong nước và quốc tế.\n  - Nghiên cứu, thử nghiệm, triển khai áp dụng các xu hướng công nghệ mới vào việc phát triển: GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL ...\n  - Tham gia phân tích nghiệp vụ, đề xuất giải pháp, phương án triển khai nhằm cải tiến, nâng cao hiệu quả của các dự án trong quá trình làm việc.\n  - Lên timeline công việc, quản lý tasks cho các thành viên trong nhóm, giám sát và hỗ trợ các thành viên hoàn thành đúng cam kết.\n  - Dẫn dắt nhóm 3-6 thành viên, đồng hành cùng các thành viên phát triển chuyên môn và hoàn thành công việc\n\nYour skills and experience\n  - Tốt nghiệp Đại học các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin ...\n  - Tối thiểu 02 năm làm việc thực tế tại các công ty, dự án về lập trình Backend\n  - Tối thiểu 1 - 2 năm kinh nghiệm làm việc với Microservice.\n  - Thành thạo ngôn ngữ Java.\n  - Thành thạo Spring framework: spring core, spring sercuity, spring boots.\n  - Thành thạo một trong trong các loại database: Oracle, Sqlserver, PostgreSQL, Mongodb.\n  - Có kiến thức tốt về kiến trúc hệ thống. Thông thạo đa dạng thiết kế phần mềm.\n  - Có khả năng tuning performance của ứng dụng, hệ thống.\n  - Có hiểu biết sâu về các kỹ thuật/công nghệ: MySQL, Redis, MongoDB, PostgreSQL, Kafka,…\n  - Có kinh nghiệm phát triển, sử dụng Cloud, AI, Front-end là 1 lợi thế.\n  - Có kinh nghiệm hướng dẫn, quản lý đội nhóm là lợi thế\n\nWhy you\'ll love working here\n  - Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n    - Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n    - Du lịch nghỉ dưỡng hàng năm\n    - Khám sức khỏe định kì\n    - Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n    - Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n  - Cơ hội nghề nghiệp và phát triển bản thân:\n    - Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n    - Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n    - Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n    - Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n  - Môi trường làm việc lý tưởng với:\n    - Những người cộng sự thân thiện và tài năng\n    - Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(421, 211, 2, 'Business Analyst (Core chứng khoán)', '1. Business Analysis\n- Provide consultation to user departments on how to utilize technology to automate jobs and/or drive revenue.\n- Handle requests related to existing business operations, technology setup, business enhancement proposals, and potential product developments.\n- Offer advice and alternative solutions when applicable.\n- Work closely with stakeholders/key end-users to gather and define detailed business requirements.\n- Prepare corresponding documentation to reflect the results of business analysis.\n\n2. Documentation & Communication\n- Prepare comprehensive documentation including user requirements, workflows, business process flows, and data requirements for system developments or business process enhancements.\n- Draft proposals for business enhancement initiatives and potential product developments.\n- Communicate and align requirements with key users and stakeholders to ensure clarity and mutual understanding.\n\n3. Data Analysis\n- Identify data analysis needs to provide factual, evidence-based business insights.\n- Perform data analysis and deliver justifiable, actionable conclusions to support business decisions.\n\n4. Program Rollout\n- Support Program Managers/Project Managers in the rollout of new products or services, including:\n    + Project operations.\n    + User training and coaching on new application systems.\n    + Participation in User Acceptance Testing (UAT).\n- Participate in profit & loss analysis, cost control, and other related rollout support tasks as needed.\n\nYour skills and experience\n- University degree in IT, Computer Mathematics, or related disciplines.\n- Minimum 2 years of business analysis experience.\n- Experience with UML and knowledge of operational workflows is an advantage.\n- Strong experience in identifying and managing project risks for large, complex projects.\n- Solid skills in project documentation, workflow definition, business process development, alternatives analysis, risk assessment, and recommendations.\n- Experience in leading/managing PMO services and functions supporting IT projects.\n- Experience in using Jira.\n- Prior experience working with Equity Core System and Derivative Core System is a strong plus.\n- General understanding of system architecture.\n- Ability to read technical documents in English well and communicate at a basic level.\n\nWhy you\'ll love working here\nChứng khoán SSI nhận 3 giải thưởng nơi làm việc tốt nhất: \n- Highly competitive remuneration package: Attractive monthly salary, 13th month salary, KPIs cash bonus, Public holiday cash bonus, Birthday gift, Lunar new year gift,...\n- Premium AON healthcare insurance and full labor insurance\n- 12 days Annual leave + 2 days sick leave with full paid\n- Luxury team-building trip and varied engagement activities\n- Joining the leisure clubs: Football, E-Sport, Running, Gym, Yoga....\n- Fully sponsored training to build your career\n- Professional, open minded and supportive working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Luong Yen, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(422, 345, 2, '[English] Scrum Coordinator/ Agile Project Coordinator', 'As a Scrum Coordinator, you will play a pivotal role in ensuring the smooth and efficient execution of Scrum projects within our organization. You will be responsible for coordinating Scrum events, managing project backlogs, and facilitating effective communication between team members and stakeholders.\n\nResponsibilities:\n- Scrum Event Coordination: Facilitate and manage all Scrum events, including Sprint Planning, Daily Scrums, Sprint Reviews, and Retrospectives.\n- Backlog Management: Maintain and prioritize product backlogs, ensuring they align with business objectives and are well-defined.\n- Team Facilitation: Foster a collaborative and productive team environment by facilitating effective communication, conflict resolution, and decision-making.\n- Stakeholder Management: Liaise with stakeholders to gather requirements, manage expectations, and ensure their satisfaction with project outcomes.\n- Metrics and Reporting: Track project progress, analyze key metrics, and provide regular reports to stakeholders.\n- Continuous Improvement: Identify opportunities for process improvement and implement best practices to enhance team efficiency and effectiveness.\n\nYour skills and experience:\n- Strong fluency in English is a must\n- Minimum 2+ years of experience as a Scrum Coordinator or Agile Project Coordinator.\n- Proven experience as a Scrum Coordinator or similar role.\n- Strong understanding of Agile methodologies in product management, particularly Scrum and Kanban.\n- Excellent communication and interpersonal skills.\n- Open-mindedness and willingness to learn: Ability to accept feedback, adapt to new approaches, and continuously develop your skills.\n- Ability to work effectively in a fast-paced and dynamic environment.\n- Strong organizational and time management skills.\n- Proficiency in project management tools and software.\n\nWhy you\'ll love working here:\n- 15 days of annual leaves\n- Competitive salary (+13-month salary included)\n- Health insurance, social insurance according to the government regulations\n- PVI Healthcare Insurance\n- Have a chance to work in an international, friendly, open environment\n- Annual Travel opportunity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '324 Le Van Sy, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(423, 217, 2, 'Senior Frontend Engineer (Next.JS, ReactJS, JavaScript)', 'About Us\nReforged Labs is a YC-backed, Sandhill Road funded AI startup revolutionizing how the world\'s top mobile gaming studios market themselves to hundreds of millions of players. We\'re building cutting-edge AI technology that powers sophisticated ad analysis and generation pipelines for elite global gaming companies.\n\nWe don\'t follow trend; we set them. Our engineering team builds solutions that rival the best Silicon Valley has to offer, creating technology that generates millions of dollars in value for our customers.\n\nThe Role \nWe\'re seeking an exceptional Senior Frontend Engineer to join our fast-growing team in Ho Chi Minh City. This is not a role for the average developer; we\'re looking exclusively for extraordinary talent who can compete with the best engineers globally.\n\nYou\'ll work on sophisticated technology that impacts how the world\'s top mobile games market themselves to hundreds of millions of players. This is a rare opportunity to join an early-stage, venture-backed AI startup with global ambitions.\n\nCore Responsibilities\n- Architect and implement beautiful, intuitive chat interfaces that seamlessly display real-time data streams\n- Build dynamic, responsive UIs that handle multiple concurrent data streams with flawless performance\n- Create elegant visualizations for complex AI-generated content and analytics\n- Implement sophisticated state management for real-time applications\n- Collaborate closely with backend engineers to integrate AI-powered services\n- Drive technical decisions that will shape our platform\'s frontend architecture\n- Set the standard for frontend excellence and best practices\n\nYour skills and experience\nRequired Experience \n- 5+ years of professional frontend development experience \n- Expert-level knowledge of Next.js and React ecosystem \n- Proven experience building real-time interfaces with websockets/SSE \n- Deep understanding of state management patterns and solutions (Redux, Context API, Zustand, etc.) \n- Strong experience with modern JavaScript (ES6+) and TypeScript \n- Track record of delivering complex UIs with meticulous attention to detail \n- Experience with responsive design and cross-browser compatibility \n- Professional English communication skills (verbal and written) \n\nEssential Qualities \n- Self-starter mentality with strong ownership of deliverables \n- Excellence in time management and ability to meet ambitious deadlines \n- Clear communication skills, especially around technical constraints and trade-offs \n- Proactive in identifying and resolving potential blockers \n- Passion for clean, maintainable, and performant code \n- Comfort working in a fast-paced startup environment \n\nInterview Process \n1. Initial Technical Screen (45-60 mins)\n- Technical background discussion\n- Live coding exercise focused on React fundamentals\n- High-level experience overview\n\n2. Project Review (45-60 mins)\n- Present your take-home project implementation\n- Technical deep-dive with Senior Engineers\n- Architecture and scalability discussion\n\n3. Final Leadership Conversation (60 mins)\n- Vision alignment with CEO and CTO\n- Culture and team fit discussion\n- Two-way Q&A about growth opportunities\n\nWe aim to complete the entire process within 2 weeks of your first response.\n\nWhy you\'ll love working here\nWhy You\'ll Love Working Here\n- Industry-leading compensation package\n- Work on technology that is genuinely world-class and cutting-edge, not just by local standards\n- Build products that compete globally and set new industry standards\n- Compensation package targeting top-tier engineers (significantly above local market rates)\n- Opportunity to be an early engineer at a rapidly growing, well-funded AI startup\n- Direct impact on products used by major gaming studios reaching hundreds of millions of users\n- Potential for international recognition and career advancement opportunities\n- Challenging, fast-paced environment that will accelerate your professional growth\n- Collaborative culture where your ideas matter and technical excellence is valued\n\nOur Engineering Culture\n- We operate in agile sprint cycles with a focus on rapid iteration and continuous delivery. Our team values independence and ownership, with each engineer taking full responsibility for their features from architecture to production deployment.\n- We maintain high standards for code quality while moving quickly to meet market demands. We are building a culture that combines Silicon Valley engineering practices with exceptional local talent.\n- Located in Ho Chi Minh City, we\'ve created a work environment that combines Silicon Valley engineering practices with local talent, offering the unique opportunity to work on global-scale problems while being part of Vietnam\'s growing tech ecosystem.\n- We are an equal opportunity employer and value diversity at our company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 , 2 Thi Sách, Phường Bến Nghé, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(424, 346, 2, 'Senior Backend Developer NodeJS', 'Top 3 reasons to join us:\n- Đãi ngộ hấp dẫn, thu nhập phù hợp năng lực\n- Môi trường TRẺ chuyên nghiệp, sáng tạo,cạnh tranh\n- Được đào tạo nâng cao năng lực\n\nJob description:\n- Xây dựng Backend quản lý (server-side) cho các hệ thống vận hành tại Kingfood: hệ thống bán hàng, quản lý nhập xuất kho, giám sát, báo cáo, tích hợp dữ liệu...\n- Viết code các tính năng theo nhu cầu vận hành; làm docker, message queue, database (MySQL, Mongo…), API, CI...\n- Tham gia thiết kế kiến trúc phần mềm và cấu trúc dữ liệu.\n- Nghiên cứu áp dụng những kỹ thuật đảm bảo yêu cầu người dùng.\n- Tối ưu hóa hệ thống để xử lý dữ liệu lớn.\n- Deploy code trên server test và production.\n- Giám sát và đảm bảo hệ thống vận hành ổn định, tối ưu.\n- Review code, hỗ trợ các thành viên khác trong team hoàn tất công việc.\n- Làm việc và hỗ trợ các bộ phận khác như: Product, BA, QC\n\nYour skills and experience:\n- Ít nhất 4 năm kinh nghiệm Backend Developer\n- Kiến thức tốt và toàn diện về NodeJS \n- Kinh nghiệm làm việc với kiến trúc Microservice, hiểu và ứng dụng được các khái niệm trong kiến trúc microservice như: service discovery, service registry, distributed tracing, asynchronous processing.\n- Có kiến thức docker, docker-compose, k8s.\n- Kinh nghiệm làm việc với các tool CI/CD như gitlab, jenkin.\n- Kinh nghiệm viết unit-test, performance-test, e2e-test.\n- Kinh nghiệm làm việc với cơ sở dữ liệu MongoDB, Redis, Elasticsearch và các cơ sở dữ liệu quan hệ khác như: Clickhouse, Mysql, Postgree v..v\n- Kinh nghiệm làm việc với hệ thống message queue như: RabbitMq, Kafka.\n\nNice to have:\n- Có tư logic tốt trong việc xử lý các yêu cầu liên quan đến quy trình và số liệu\n- Có ý thức viết code sạch, tỉ mẩn, chi tiết\n- Sử dụng thành tạo công cụ quản lý version source code: git, gitlab.\n- Ham học hỏi, sẵn sàng và có khả năng tự học ngôn ngữ công nghệ mới (nếu cần)\n- Có tinh thần làm việc của startup và sẵn sàng chia sẻ đào tạo cho đồng nghiệp.\n\nWhy you\'ll love working here:\n- Môi trường trẻ chuyên nghiệp, năng động, sáng tạo, phát triển, có nhiều cơ hội thăng tiến\n- Được đào tạo nâng cao năng lực, thoải mái đề xuất ý tưởng để nâng cao hiệu suất làm việc.\n- Được hưởng đầy đủ các chính sách về lao động theo luật lao động về lương, thưởng, nghỉ Lễ, Tết\n- Phòng làm việc rộng rãi đầy đủ tiện nghi, được cấp màn hình làm việc\n- Sử dụng laptop cá nhân', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '571 Huynh Tan Phat, Tan Thuan Dong Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(425, 347, 2, 'Fullstack Developer (CS-Cart / PHP)', 'Top 3 reasons to join us\n\n- Có thể làm việc từ xa\n- Văn phòng mới! Trong công ty có góc cafe\n- Lớp học tiếng Nhật và tiếng Anh miễn phí\n\nJob description\n- Tham gia phát triển, bảo trì và tối ưu hóa các website thương mại điện tử, đặc biệt là trên nền tảng CS-Cart.\n- Thiết kế và xây dựng giao diện người dùng thân thiện, chuẩn UI/UX.\n- Phát triển các tính năng mới cả về frontend và backend, đảm bảo hiệu suất và tính bảo mật.\n- Phối hợp với team thiết kế, quản lý dự án và QA để triển khai sản phẩm chất lượng cao.\n- Tham gia phân tích yêu cầu, đưa ra giải pháp kỹ thuật hợp lý cho các tính năng của hệ thống.\n- Có kinh nghiệm custom addon, theme hoặc core trên CS-Cart.\n- Làm việc theo mô hình labo, kỹ sư sẽ trở thành nhà phát triển chuyên trách của khách hàng, nhận chỉ thị và báo cáo trực tiếp với khách hàng Nhật Bản.\n\nYour skills and experience\nBẮT BUỘC:\n- Có ít nhất 1–2 năm kinh nghiệm phát triển web fullstack (PHP, JavaScript).\n- Có kinh nghiệm làm việc với một trong các framework: Laravel, Symfony, hoặc tương đương. Thành thạo HTML, CSS, JavaScript (ưu tiên biết jQuery, và có kinh nghiệm xử lý responsive UI)\n- Có khả năng tạo tài liệu thiết kế tổng quát và chi tiết để trình bày cho khách hàng.\n- Có khả năng phân tích, tự học, và giải quyết vấn đề độc lập.\n- Có kinh nghiệm thực tế với CS-Cart\n\nƯU TIÊN:\n- Ưu tiên ứng viên có sản phẩm thực tế hoặc đã từng tham gia phát triển hệ thống TMĐT.\n- Ưu tiên ứng viên có kinh nghiệm làm việc trực tiếp với khách hàng Nhật hoặc từng làm việc trong mô hình labo.\n\nWhy you\'ll love working here\n• Thử việc FULL lương.\n• Thưởng lương tháng lương thứ 13.\n• Mức lương xứng đáng với năng lực của mình.\n• Xét tăng lương 2 lần/ năm.\n• Có cơ hội được TĂNG LƯƠNG NGAY LẬP TỨC nếu làm việc đạt hiệu quả cao.\n• Hỗ trợ tiền trợ cấp giữ xe.\n• Được đào tạo các kỹ năng cần thiết theo yêu cầu công việc.\n• Môi trường tốt để cải thiện tốt tiếng Anh và tiếng Nhật.\n• Snack, nước uống FREE trong thời gian làm việc.\n• Tham gia tiệc sinh nhật của công ty 1 tháng / lần, tiệc buffet theo định kỳ.\n• Kiểm tra sức khỏe định kỳ hàng năm.\n• Được đóng các khoản BHXH, BHYT, BHTN, KPCĐ theo quy định của pháp luật.\n• Được làm việc trong môi trường chuyên nghiệp, năng động, cơ hội thăng tiến cao.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'An Phu Plaza Building, 117-119 Ly Chinh Thang Street, Ward Vo Thi Sau, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(426, 348, 2, 'Mid - Senior Quality Engineer', 'Founded in 2016, Katalon is the leading provider of a modern, comprehensive quality management platform. Katalon Platform enables quality assurance, DevOps, and software teams of any size to deliver world-class customer experiences faster, easier, and more efficiently.\n\nSince its first launch, Katalon has experienced tremendous growth, serving more than 100,000 users across 30,000 teams of all shapes & sizes, many of which are in the Fortune Global 500, such as PwC, KMPG, Abbott, etc. Katalon is recognized as a top automation tool by prestigious review sites, such as Gartner, Capterra, and IT Central Station.  \n\nWe’re looking for a Senior Quality Engineer to help deliver high-quality software while contributing to the development and enhancement of our Quality Platform. You will play an essential role within the quality engineering team, collaborating with fellow engineers and product teams to ensure the platform meets the highest standards of software quality.\n\nYou will be part of a dedicated, distributed team working with advanced testing techniques to assess and improve the quality of our platform. As a Senior Quality Engineer, you will work closely with Agile teams, providing expertise on quality engineering while supporting the overall success of the product.\n\nContribute to the automation-first quality strategy and improve testing practices for our evolving platform;\nCollaborate with Product Managers and Software Engineers to provide input and guidance on testing for new features and designs;\nParticipate in Agile ceremonies and provide input on quality engineering tasks within the team;\nSupport and mentor junior quality engineers, providing guidance on test techniques and best practices;\nWork closely with Customer Support to reproduce defects, address escalations, and support issue resolution;\nAssist with maintaining and improving testing processes, tools, and automation frameworks.\n\nYour skills and experience\nKey Qualifications  \nStrong understanding of Test methodologies and principles;  \n2+ years of hands-on experience with automation tools such as Katalon, Cypress, or Playwright;  \nExperience with object-oriented programming (OOP) and proficiency in programming languages (Groovy, Java);  \nPractical experience with mobile testing and API testing;  \nFamiliarity with automated build/deployment pipelines (e.g., Jenkins, Circle CI, GitHub Action, Azure Pipelines);  \nExperience in Agile Teams (Scrum, SAFe framework);  \nStrong multitasking abilities and adaptability to fast-paced environments;  \nExperience supporting testability, defining acceptance criteria, and collaborating on non-functional requirements;  \nProficient in English communication and presentation skills.  \n\nBonus Points:  \nBachelor’s degree in Computer Science/Software Engineering or equivalent;  \nExperience with WinApp testing;  \nExperience with Performance Testing using tools like K6;  \nFamiliarity with cloud providers like LambdaTest, Kobiton, BrowserStack, and Saucelabs;  \nUnderstanding of Data Engineering applications, data platforms, machine learning, and AI;  \nKnowledge of cloud providers such as LamdaTest, Kobiton, BrowserStack and Saucelabs;  \nPSM I certified.\n\nWhy you\'ll love working here  \nAt Katalon, we bring together self-starting, open-minded, and talented people while actively promoting a transparent and growth-enabling working environment. But don’t just take our word for it. Take a better look below!\nTotal Remuneration: Satisfying your financial goals through competitive compensation and periodic performance bonuses.\nWell-being & Work-life Balance: Staying healthy through comprehensive health plans and generous paid leaves.\nStatutory Compliance: Labor compliance with local regulations that ensure employee security.\nWork Facilities & Accommodation: Top-notch equipment, supportive allowances, and A-class facilities.\nDiversity, Equity, Engagement, & Inclusion: Becoming part of a global team that celebrates differences, equal opportunity, and meaningful employee recognition.\nGrowth & Rewards: Thriving professionally through employee enablement, a culture of trust, and rewarding performance.\n\nKatalon is proud to be an equal-opportunity employer. We care about our people and celebrate our differences. We want to work with talented, collaborative, and innovative people. We do not discriminate in hiring or any employment decision based on race, color, religion, national origin, age, sex (including pregnancy, childbirth, or related medical conditions), marital status, ancestry, physical or mental disability, genetic information, veteran status, gender identity or expression, sexual orientation, or other characteristics protected by law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Complex Building, 285 Cach Mang Thang 8 Street, District 10, HCMC, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(427, 349, 2, 'Remote - Backend Developer, Golang', 'We are in search of an experienced Golang developer with either an interest in or experience in backend systems and microservices as well as platform integrations.   Must be able to innovate solutions to problems, as well as optimise functions database interactions (such as Postgres, Kafka, Docker, Kubernates).   Ultimately the two most important strengths would be mastery of Golang, and an ability to solve problems.  Golang experience required Golang blockchain or crypto experience considered an asset Database experience considered an asset (Postgres or similar) Softly is a rapidly growing platform of experts solving unique hi-tech problems.   Excellent opportunity for career advancement and professional growth, while providing a balanced work environment with flexible hours, remote work and Vietnamese language.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(428, 307, 2, 'Data Scientist (Image & Generative AI)', 'Job description\n- Analyze and understand new data requirements related to image processing.\n- Assist in designing and building data pipelines for collecting, storing, and processing image datasets.\n- Propose strategies for collecting and labeling image datasets.\n- Work on cloud-based architectures (GCP) for storage and computation.\n- Collaborate with senior engineers to implement Generative AI models for image augmentation, processing, generating.\n- Ensure data governance and compliance, with guidance, addressing issues like bias in AI-generated images.\n\nYour skills and experience\n- Bachelor’s degree in Computer Science, Data Science, or related field.\n- 3-5 years of experience in data engineering, data science with exposure to image data processing.\n- Familiar with Python and image processing libraries (OpenCV, Pillow).Knowledge of Generative AI concepts.\n- Experience with database: SQL, PostgreSQL\n- Strong teamwork, problem-solving skills, and willingness to learn.\n- Good at English languages\n\nWhy you\'ll love working here\n- Compensation & bonus: 13th & 14th salary, AIP bonus, Holidays, Tet, and Long year service …\n- Social insurance, Health insurance, Unemployment insurance: by Social Insurance and Labor Law\n- The regime of annual leave, company trip, and checkup examination\n- Award for marriage, newborn\n- We have AON insurance package for employee, spouse, and children every year\n- You will be trained, learned & work with the best technical managers who help you improve various dev skills & career path\n- You’ll love working in our dynamic environment employees, young & active\n- We love sport activities, as marathon, football, swimming,...\n- Working time: From Monday to Friday | 08:30-12:00 & 13:00-17.30', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'L07.01, Tầng 07, Tháp A, Khu thương mại dịch vụ kết hợp nhà ở cao tầng tại lô đất 1-13, thuộc khu chức năng số 1 – Số 15, đường Trần Bạch Đằng, Phường Thủ Thiêm, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(429, 350, 2, 'Backend Developer (Golang/ Java)', 'ABOUT US\nAt Neyu, we are building platforms that empower businesses and individuals to share their values with billions worldwide through products and services. We believe that serving others unlocks happiness, health, and more meaningful lives. As a rapidly expanding MarTech company, we operate across Asia—including Thailand, Vietnam, Malaysia, the Philippines, Indonesia, and India—and are extending our reach into Latin America.\nRecognizing opportunities to unlock untapped potential, Neyu Corporation drives growth through innovation, digital platforms, and advanced marketing technology. Our group, a top-ranked direct sales company in Southeast Asia, has over 1,400 team members with a strong presence in these regions.\nThrough our e-commerce platforms, we create and sell healthcare and pharmaceutical products, particularly within the Nutra niche. Combining core marketing principles with advanced IT, we see limitless opportunities ahead. If you are eager to participate in international projects, gain unique skills, and learn from top leaders, Neyu is the right place for you.\n\nKEY RESPONSIBILITIES\n● Design, develop, and maintain backend services and APIs.\n● Improve system performance and scalability.\n● Contribute to new projects such as:\n  ❖ Marketing platform\n  ❖ Omnichannel solutions\n  ❖ CRM and ERP systems\n\nYour skills and experience\nTECHNICAL SKILLS & EXPERIENCE:\nLanguages: Proficient in Golang (preferred) or Java (minimum 1 year of experience). Experience with Node.js or PHP is a plus.\nFrameworks: Experience with Gin (Golang) or Spring Boot (Java).\nDatabases: Strong knowledge of relational databases (PostgreSQL, MySQL) and familiarity with NoSQL databases (MongoDB, Elasticsearch).\nCaching: Experience with Redis for performance optimization.\nDevOps & Tools: Familiar with Linux, Docker, Kubernetes, Nginx, Git, Jenkins.\nTelephony: Knowledge of Asterisk PABX or similar systems is a plus.\nDevelopment Practices: Comfortable with Agile methodologies and tools.\n\nSOFT SKILLS:\nStrong problem-solving and critical thinking abilities.\nExcellent communication and collaboration skills.\nPassion for learning and exploring new technologies.\nProven track record of delivering large-scale applications with a user-centric mindset.\n\nQUALIFICATIONS\nBachelor’s degree in Computer Science, Software Engineering, or a related field.\nMinimum 1 year of experience in backend development.\nComfortable working and communicating in English. \n\nWhy you\'ll love working here\nA multinational, dynamic working environment that offers various development opportunities where work transcends all traditional boundaries.\nOpportunities to work with a vast global talent pool, bringing together diverse, specialized teams that collaborate seamlessly.\nA delegation culture where you are empowered to take full ownership and responsibilities in projects, tasks, and innovations.\nSalary: Competitive remuneration package and fully paid in the probation period.\nPay-for-performance policy: Attractive year-end bonus and salary review twice per year based on the employee’s performance.\nPremium health care package.\nA work-life harmony working schedule from 9 AM – 6 PM from Monday to Friday.\nTeam building and other various cash and non-cash benefits (holiday bonuses, birthday…).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '17-19 Ton That Tung Street, Pham Ngu Lao Ward, District 1, Ho Chi Minh City, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(430, 225, 2, 'StarCamp Security Engineer (Fresher)', 'By applying for the above position, you accept and agree that your personal data and any information stated in the attached curriculum vitae (CV) will be used and processed by ITViec and NAB Vietnam for recruitment purposes. The storage and processing of such information will comply with the applicable laws of Vietnam, and the policies and procedures of ITViec and NAB Vietnam regarding personal data, as amended from time to time.\n\nSecurity is one of the fastest growing segment in the IT Industry, covering a wide range of roles that work together to protect users from theft, damage, loss, and unauthorized access to their computers, network, and data.\n\nNAB Vietnam is now opening a Security-focus StarCamp program for freshers in the IT industry. Whether you are a final-year student, a recent graduate, or switching to a new career in tech, our bootcamp will provide you with core competencies, the skills, and the mindset required to be part of an elite team that provide CyberSecurity to more than 10 million customers globally.\n\nLearning how NAB build processes, features, and infrastructure to protect our 10-million customers.\nPaid training allowance\nDeveloping soft skills and English skills required for international software development workplace\nIncluding:\n- Cyber Security Engineer (i.e Engineering, DevOps, Mainframe Identity Services (MIS) Engineer, etc.)\n- Cyber Security Analyst (i.e Application Security, Penetration Testing, etc.)\n- Cyber Security Assurance/ Advisory\n- Business Analyst\n\nNote:\nThe program will start in Aug 2025 and last 3 months. Please review your schedule to ensure you can commit to working full-time during and after the training if you qualify for a full-time position.\n\nWhy Security\nCybercrime and financial crime are on the rise, with it a strong demand for security professionals (32% increase globally between 2022 and 2023). NAB in particular has invested heavily in security, both in terms of infrastructure and our workforce, to protect our customers. We also aim to invest in the tech ecosystem in Vietnam, leveraging our expertise to grow a sustainable generation of talents in cybersecurity here.\n\nAlso, join us if you want to:\n- Help protect millions of users from theft, damage, and loss\n- Work in an international software development environment\n\nWe are looking for some great new talent to join us who can say yes to being:\n- Analytical Problem Solvers\n- Collaborative Team Players\n- Outside the box Innovators\n- Accountable deliverers\n- Proactive and Eager Learners\n\nSimply register via the following link to submit your CV: \n\nTHE BENEFITS AND PERKS\n1. Generous compensation and benefit package\n- Attractive salary and benefits\n- 20-day annual leave and 7-day sick leave, etc.\n- 13th month salary and Annual Performance Bonus\n- Premium healthcare for yourself and family members\n- Monthly allowance for team activities\n- Premium welcome kit and frequent appreciation gifts \n- Extra benefits for long-term employees\n2. Exciting career and development opportunities \n- Large scale products with modern technologies in banking domain\n- Clear roadmap for career advancement in both technical and leadership pathways\n- Well-structured learning and development programs (technical and soft skills)\n- Sponsored certificates in both IT and banking/finance\n- Premium account on Udemy \n- English learning with native teachers\n- Opportunity for traveling & training in Australia\n3. Professional and engaging working environment\n- Hybrid working model and good work-life balance \n- Well-equipped & modern Agile office with fully stocked pantry\n- Special programs to improve your physical and mental health\n- Annual company trip and events \n- A solid talented team behind you – great people who love what they do\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh / ROX Tower, 54A Nguyen Chi Thanh, Lang Thuong, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(431, 216, 2, 'US/UK Market- QA Automation Manager (Leadership, QA QC)', 'Top 3 reasons to join us\n- Môi trường làm việc đa quốc gia\n- Cơ hội thăng tiến, phát triển bản thân\n- Trải nghiệm làm việc tại Nhật Bản/ Âu Mỹ\n\nJob description\n- Develop and implement a comprehensive testing strategy to ensure the quality of our software applications.\n- Ensure that all testing is carried out in accordance with industry best practices and standards.\n- Develop and maintain automated testing frameworks and scripts to improve testing efficiency and accuracy.\n- Coordinate all applications testing teams to ensure that testing is carried out in a timely and efficient manner.\n- Work closely with the development team to ensure that testing is integrated into the development process.\n- Develop and maintain testing metrics to measure the effectiveness of the testing process.\n- Identify and report on any risks or problems found during testing as soon as possible.\n- Provide regular reports to onshore managers on the status of testing and any issues or concerns.\n- Promotes a constructive, positive team environment and maintains a spirit of openness, information sharing, inquisitiveness, problem-solving, and support for our common goals.\n\nYour skills and experience\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- Excellent English communication, previous experience working directly with European and American customers.\n- Minimum of 7 years experience in software testing, with 3+ years in the leading and mentoring position for the team of 10 members.\n- Strong test management, strategy build up, execution monitoring and reporting is required.\n- Strong background in automation testing for large systems, using Ranorex is an advantage.\n- Strong knowledge of continuous integration/continuous delivery (CI/CD) tools and practices.\n- Knowledge of Azure, MS SQL, capable of building queries to process large data.\n- Experience with ControlM, JIRA, SharePoint and ServiceNow a plus.\n- Understanding of Finance Industry is a plus.\n\nWhy you\'ll love working here\n- Là một thành viên của Rikkeisoft, những điều thú vị này sẽ dành cho bạn: - 5 ngày làm việc chính thức/ tuần, nghỉ phép 1 ngày/tháng. Tham gia hoạt động Thứ 7 Truyền Nghề hàng tuần, có phụ cấp và hỗ trợ ăn trưa.\n- LƯƠNG xét TĂNG 2 lần/năm. THƯỞNG nhiều: tháng 13, thưởng Tết, thưởng dự án, thường ngày lễ, thưởng giới thiệu nhân sự...\n- Tham gia lớp học tiếng Nhật do giáo viên bản địa giảng dạy.\n- Câu lạc bộ và nhiều hoạt động văn hóa - thể thao - nghệ thuật được công ty tài trợ hoặc hỗ trợ (Ví dụ: Bóng đá, bóng bàn, cầu lông, bơi lội, âm nhạc, tiếng anh, game...)\n- Cấu hình máy móc khủng: Main B360M-D3H, CPU Core i5 8400, Ram 8G/2666, SSD Samsung 250GB.\n- Đảm bảo sức khỏe: Khám sức khỏe định kỳ, hỗ trợ mua bảo hiểm sức khỏe chất lượng cao...\n- Thoải mái tinh thần: Phát nhạc theo yêu cầu mỗi ngày, hoa quả tươi, các hoạt động teambuilding gắn kết... Đi chơi gần xa khắp nơi.\n- Cơ hội đi Nhật Bản làm việc và du lịch khắp nơi.\n- Học hỏi kinh nghiệm từ những nhân vật trẻ nổi tiếng và có nhiều ảnh hưởng (Top 30 Under 30 fo Forbes bình chọn)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 18, tòa nhà Vinacomin, 3 Dương Đình Nghệ, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(432, 351, 2, 'Quality Control Lead', 'Top 3 reasons to join us\n- The world of passion, challenge, innovation\n- We\'re a family of young souls united by talents\n- Passions and Trust\n\nJob description\n- Strategic Oversight and Evaluation: Evaluates production operations from a strategic level, utilizing automated testing and CI/CD pipelines to ensure products meet quality, integrity, functionality, and other specifications and requirements.\n- Testing Process Management: Develops, implements, and oversees quality standard testing and evaluation processes, including their integration into CI/CD pipelines and compatibility with containerized environments, leveraging testing frameworks and automation tools.\n- Continuous Improvement and Issue Resolution: Assesses test results and monitoring data to approve changes, ensure continuous improvement of testing processes, and proactively address quality issues using appropriate tools and strategies.\n- Team Leadership and Development: Leads, mentors, and manages the QC team, ensuring they have the necessary skills, resources, and support to perform their duties effectively, including training on new technologies and ensuring the capability to test database systems.\n- Innovation and Industry Awareness: Stays up to date with industry trends, testing technologies, and best practices, including advancements in AI/ML applications, and evaluates and integrates new tools and techniques to enhance QC processes.\n\nYour skills and experience\nAutomation Testing\n- Strong knowledge of software testing methodologies and best practices.\n- Ability to design and implement comprehensive test plans.\n- Familiarity with monitoring and observability tools such as Sentry, Grafana, or similar.\n- Experience with automated testing frameworks like Playwright, Selenium, or Cypress.\n- A general understanding of how AI/ML can be applied to quality control, such as anomaly detection or log analysis is a plus.\n\nCI/CD:\n- Solid understanding of CI/CD pipelines and principles.\n- Experience with CI/CD tools like GitHub Actions, Jenkins, or similar.\n- Familiarity with containerization using Docker or Kubernetes.\n- Basic understanding of database systems (SQL or NoSQL).\n\nSoft Skills:\n- Passion for staying updated on design trends, emerging technologies, and AI advancements.\n- Excellent leadership, communication, and interpersonal skills.\n- Strong analytical and problem-solving abilities.\n- Ability to work in a fast-paced, dynamic environment and manage multiple priorities.\n\nPreferred Qualifications:\n- Certification in Quality Control or related areas (e.g., ISTQB,...)\n- Experience with Agile/Scrum methodologies.\n\nWhy you\'ll love working here\nWe believe that motivation & personality of the employees are the only shortcut to the promotion of the corporate and contributions to the society. We will try our best to create a corporate environment where all employees can realize their dreams and goals.\nFeatured benefits include:\n- Monday - Friday/ 9am - 6pm\n- Have opportunity to work with global merchants and join the dynamic, young and friendly project team; stable career path;\n- Attractive salary based on skills and experience; 13th month salary & seniority bonus; Employee’s marriage, maternity bonus; Birthday voucher gift;\n- Annual salary review;\n- PTI Healthcare, annual health check;\n- Regular technical seminar & external/ internal training courses;\n- Providing free coffee, tea & snack;\n- Internal engagement events: Teambuilding; Town-hall, birthday gift voucher, mid-autumn, new year and kick-off parties, yearly company trip;\n- FireGroup Sports Clubs: Running, Football, Badminton, etc;\n- Laptop/ PC/ Monitor \'re provided.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Flemington Tower, 182 Le Dai Hanh Street, District 11, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(433, 352, 2, '02 Senior Full-Stack Engineer (ReactJS/ HTML5/ CSS)', 'Xây dựng Frontend và Backend cho hệ thống web và CMS \nThiết kế và quản lý Database \nThiết kế và phát triển RESTful API \nPhát triển Server-side logic \nImplement và bảo trì các hệ thống backend có thể mở rộng \nThiết kế và xây dựng giao diện người dùng chất lượng cao \nĐảm bảo thiết kế đáp ứng và trải nghiệm người dùng tối ưu \nTạo các tài liệu cần thiết để thiết kế và phát triển\n\nLƯU Ý: Ứng viên vui lòng gửi CV tiếng Anh.\n\nYêu cầu bắt buộc: Có từ 2-4 năm kinh nghiệm làm việc với những thứ dưới đây.  \n- ReactJS(Next.js)/HTML5/CSS  \n- Hono  \n- TypeScript  \n- Coding for CSS frameworks and CSS preprocessors such as Tailwind CSS, CSS in JS, Sass  \n- Responsive design  \n- RDBMS table design  \n- SQL querying  \n- API building  \n- Git, Github  \n- Docker\n\nYêu cầu ưu tiên: Có kinh nghiệm với những thứ dưới đây.  \n- Test code implementation  \n- ESLint and other linters, Prettier  \n- Nest.js  \n- Prisma  \n- SQL performance tuning  \n- GraphQL  \n- CI/CD pipeline construction  \n- Amazon Web Services (AWS)  \n- Terraform  \n- Scalability-aware development  \n- BFF (Backend For Frontend) construction  \n- Team development  \n- Next.js Ver.13 AppRouter  \n- Understand rendering strategy (CSR, SSR, SSG, ISR)  \n- StoryBook  \n- Figma (or XD)  \n- UI/UX design\n\nWhy you\'ll love working here  \n- Số lượng cần tuyển: 2 người\n- Mức lương cạnh tranh lên đến 2000$\n- 12 ngày nghỉ một năm và sau 3 năm thì tăng thêm 1 ngày mỗi năm \n- Bảo hiểm xã hội đầy đủ (Sức khỏe, thất nghiệp, y tế ) \n- Làm việc từ thứ 2 đến 6, từ 8h30 đến 17:30, được nghỉ trọn vẹn 2 ngày cuối tuần bên gia đình \n- Tận hưởng thoải mái đồ ăn vặt, nước uống: Cafe, bánh kẹo, bim bim, hỗ trợ đỗ xe miễn phí \n- Có cơ hội đi làm tại Nhật Bản \n- Có cơ hội được làm việc với các đối các công ty game lớn tại Nhật Bản như Square Enix, DeNa \n- Có cơ hội học hỏi, đào tạo và tham gia vào các dự án lớn theo xu hướng công nghệ 4.0', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'số 11 Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(434, 353, 2, 'Business Analyst (Agile, Scrum)', 'Top 3 reasons to join us\n- Môi trường làm việc thân thiện, chuyên nghiệp\n- Lương thưởng tương xứng năng lực làm việc\n- Có cơ hội phát triển bản thân\n\nJob description\n- Khảo sát, thu thập, phân tích yêu cầu nghiệp vụ, kỹ thuật và giải pháp trên các ứng dụng mobile, web.\n- Xây dựng và mô hình hóa quy trình nghiệp vụ\n- Tài liệu hóa yêu cầu nghiệp vụ và yêu cầu chức năng\n- Tiến hành phân tích đánh giá tính khả thi của giải pháp.\n- Phối hợp với đội ngũ thiết kế, kĩ thuật để xây dựng hàng trình khách hàng và thiết kế giao diện ứng dụng\n- Phối hợp các bên liên quan để lập kế hoạch triển khai dự án.\n- Phối hợp với đội ngũ kỹ thuật, kiểm thử trong suốt quá trình phát triển và kiểm thử.\n- Giám sát và báo cáo tiến độ dự án\n- Tuân thủ các quy trình và quy định của HDBank\n\nYour skills and experience\n- Có kinh nghiệm về việc xây dựng quy trình: BPMN, UML\n- Có kinh nghiệm về tiếp nhận và quản lý yêu cầu nghiệp vụ\n- Có kinh nghiệm về phân tích yêu cầu, phân tích ảnh hưởng và phân tích khác biệt (Gap analysis)\n- Có kinh nghiệm xây dựng wireframe, mockup cho các chức năng hệ thống\n- Có kinh nghiệm về sử dụng và đặc tả use cases/user story\n- Có kiến thức về Agile/Waterfall và các mô hình phổ biến như Scrum, Kanban...\n- Có kỹ năng phỏng vấn người dùng, giao tiếp với các nhóm khác nhau (nghiệp vụ, developer, tester...)\n- Thành thạo viết tài liệu hóa các yêu cầu nghiệp vụ và yêu cầu chức năng (Business requirement document và functional specification\n- Chịu được áp lực cao từ mức độ ưu tiên và timeline của dự án\n- Tài liệu bàn giao có chất lượng tốt, hạn chế các sai sót\n- Chủ động báo cáo kết quả công việc định kỳ cho quản lý\n- Cần cụ, kiên nhẫn, ham học hỏi và chủ động trong công việc\n- Đáp ứng deadline công việc đã đặt ra\n\nWhy you\'ll love working here\n- Đánh giá và xét thưởng tương xứng với năng lực.\n- Được quy hoạch, huấn luyện và đào tạo bài bản, tiếp cận với những công nghệ mới nhất và hiện đại nhất trong lĩnh vực tài chính.\n- Được hỗ trợ phát triển bản thân tối đa.\n- Du lịch, teambuilding hằng năm.\n- Lương tháng 13, lễ, Tết.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(435, 354, 2, 'Java Fullstack Developer', 'Top 3 reasons to join us\n• Đãi ngộ đi cực kỳ hấp dẫn\n• Du lịch, teambuilding hàng quý cùng người thân\n• Cơ hội trao quyền để lead dự án\n\nJob description\n• Phát triển, tối ưu các chức năng hệ thống backend theo sự phân công và định hướng từ PM hoặc Leader.\n• Tham gia phân tích nghiệp vụ, phân rã chức năng, phân tích hệ thống, kiểm thử logic và trải nghiệm, sửa lỗi, triển khai hệ thống\n• Chịu trách nhiệm về chất lượng và hiệu quả code của các module được giao. Đảm bảo sản phẩm backend ổn định, hiệu suất tốt và dễ bảo trì.\n• Hợp tác chặt chẽ với các team liên quan (FE, QA, BA, DevOps…) để đảm bảo tiến độ và chất lượng sản phẩm.\n• Tham gia vào quy trình kiểm thử, fix bugs, triển khai và bảo trì hệ thống.\n• Chủ động tìm hiểu nghiệp vụ và tham gia đề xuất cải tiến sản phẩm.\n• Hỗ trợ các thành viên junior khi cần và có thể review code nếu được giao.\n• Báo cáo tiến độ, vấn đề, kết quả công việc đến quản lý trực tiếp.\n• Trải nghiệm sản phẩm định kỳ để hiểu hành vi người dùng, từ đó đưa ra các đề xuất cải tiến.\n\nYour skills and experience\n1. Kiến thức bắt buộc:\n• Có tối thiểu 02 năm kinh nghiệm tương đương\n• Có kinh nghiệm làm việc với hệ quản trị cơ sở dữ liệu RDBMS, NoSQL, có khả năng viết, tối ưu truy vấn, phân tích dữ liệu.\n• Có hiểu biết về các Framework Spring Boot, Vert.x, Microservice.\n• Hiểu rõ mô hình backend MVC và các khái niệm RESTful API.\n• Có kinh nghiệm triển khai hệ thống trên môi trường production, biết cách vận hành và giám sát hệ thống.\n• Có khả năng sử dụng AI trong lập trình.\n\nKiến thức nâng cao (lợi thế):\n• Biết sử dụng các ngôn ngữ lập trình khác: PHP, Python, Shell-script, Jenkin, HAProxy\n• Kỹ năng làm việc theo quy trình JIRA, Agile, SCRUM\n• Có hiểu biết về UI/UX, hành vi người dùng là một điểm cộng.\n\n2. Kỹ năng\n• Problem solving: Có khả năng phân tích vấn đề, tìm giải pháp kỹ thuật phù hợp.\n• Design thinking: Có tư duy xây dựng giải pháp tối ưu, hướng đến trải nghiệm người dùng.\n• Giao tiếp, làm việc nhóm, lắng nghe và truyền đạt thông tin\n• Học hỏi và tự học tốt; Tổ chức và quản lý thời gian\n\n3. Tố chất\n• Tư duy logic\n• Tư duy hệ thống\n• Tỉ mỉ, cẩn thận\n\nWhy you\'ll love working here\n• Thử việc 2 tháng hưởng 100% lương chính thức.\n• Thu nhập không giới hạn: Lương cứng + thưởng KPI, thưởng dự án, lương tháng 13, thưởng Tết,…\n• Khám sức khỏe định kỳ hàng năm.\n• Trợ cấp tiền ăn trưa khi là nhân viên thử việc.\n• Du lịch hàng năm, dã ngoại hàng quý 4 lần/năm, được hỗ trợ du lịch cùng người thân.\n• Hưởng đầy đủ các chế độ bảo hiểm theo quy định của nhà nước khi là nhân viên chính thức.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2 tháp A, tòa Rivera Park, 69 Vũ Trọng Phụng, Thanh Xuân, Hanoi, Vietnam, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(436, 355, 2, 'Backend Team Leader (Java, Spring)', 'Nghiên cứu, phát triển và triển khai, tư vấn các giải pháp công nghệ dựa trên nền tảng Java, tạo ra các sản phẩm phần mềm tối ưu, phù hợp với nhu cầu của khách hàng.\nHỗ trợ các thành viên trong nhóm với các chức năng phức tạp, tham gia nhận xét, đánh giá source code của các thành viên trong nhóm.\nCải tiến và nâng cao chất lượng dự án: Nghiên cứu và áp dụng công nghệ, kiến trúc service mới tại các dự án lớn phù hợp với định hướng và chiến lược phát triển của Công ty.\nTạo ra những sản phẩm mới, bảo trì cũng như cải thiện các giải pháp hiện có.\nĐảm bảo về chất lượng các dự án triển khai.\nQuản lý team: Điều phối công việc, xử lý tình huống, sự vụ, đánh giá nhân sự. Lên kế hoạch hoạt động, đào tạo, hướng dẫn, nâng cao năng lực các bạn thành viên khác.\nSố năm kinh nghiệm từ 5-7 năm trở lên và tối thiểu 1-2 năm ở vị trí Leader.\nNắm vững về Java Core: String, StringBuilder, String Buffer, Box - Unbox.\nSử dụng thành thạo Collection trong Java.\nHiểu được các design pattern Spring Framework đang dùng, khái niệm về IoC, DI, hiểu về Spring Data JPA.\nCó kiến thức lập trình cơ bản (OOP, Creational, Structural, Behavioral).\nDatabase: Thành thạo SQL, có kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu như MySQL, PostgreSQL, Oracle.\nNắm được các giải thuật và cấu trúc dữ liệu cơ bản.\nNắm được syntax, cách hoạt động của 1 ngôn ngữ bất kỳ.\nCó kiến thức về quy trình phát triển dự án.\nNắm bắt, thực hành nhuần nhuyễn trên 1 code base / framework.\nGit nâng cao và có thể đưa ra các flow sử dụng git phù hợp từng giai đoạn dự án cũng như hỗ trợ các member khác khi có sự cố về GIT.\nKiến thức chuyên môn: Là lợi thế khi hiểu sâu kiến thức về Software Architect, Design Pattern, SOLID , Clean Code.\nPhân tích yêu cầu: Hiểu rõ về yêu cầu của công việc phụ trách, có khả năng phân tích và đưa ra Q&A trước khi phát triển chức năng.\nThiết kế hệ thống: Tạo được detail design, API document, thiết kế DB ... cho chức năng phụ trách.\nThiết kế được các chức năng lớn, quan trọng của dự án.\nTham gia review thiết kế chức năng của members khác làm, đưa ra các đánh giá mang tính định hướng kỹ thuật, hỗ trợ khi cần thiết.\nKhả năng Code: Có thể code các module từ cơ bản đến phức tạp.\nCó thể phân tích bug và đề xuất giải pháp cho các module phần mềm từ cơ bản đến phức tạp.\nCó thể xây dựng codebase, xây dựng convention về luồng làm việc và giao tiếp trong hệ thống.\nCó kinh nghiệm làm việc với các bên thứ 3 là một lợi thế như payment gateway, apple store, google play, hệ thống kyc, banking.\nTesting/Debug: Self-test tốt, hạn chế số lượng bug QC phát hiện ra.\nXử lý nhanh các bugs phát sinh.\nKỹ năng cá nhân: Kỹ năng teamwork, giao tiếp, giải quyết vấn đề.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '5BT2, khu đô thị Mễ Trì Hạ, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(437, 356, 2, '[Remote] Senior/Team Lead PHP Developer (Zend, Laravel)', 'Top 3 reasons to join us\n\n- Attractive salary, benefits, hybrid working\n- Technical training sessions (internal – external)\n- PVI Healthcare insurance\n\nJob description\n\n- Lead the design, development, and maintenance of robust APIs, services, and backend systems using PHP and related technologies.\n- Guide and support your development team, ensuring efficient workflows, code quality, and timely delivery.\n- Collaborate effectively across teams, including frontend, QA, and DevOps, to deliver seamless features and solutions.\n- Communicate clearly with clients to manage expectations, provide technical insights, and maintain long-term partnerships.\n- Troubleshoot complex programming issues and provide technical direction for scalable, maintainable architecture.\n- Drive feature development that integrates with various system components and enhances user experience.\n\nYour skills and experience\n\nMUST HAVE SKILLS:\n\n- 6+ years of hands-on experience in software development with a strong focus on backend systems.\n- Proven expertise in PHP 7/8, with solid experience in modern frameworks such as Zend and Laravel (our current stack uses Zend).\n- Good understanding of SOLID principles, software design patterns, and clean coding practices.\n- Excellent understanding of relational databases, including database design and optimization.\n- Solid experience with Test-Driven Development (TDD) and writing unit/integration tests using tools like PHPUnit or Pest.\n- Background in architecture and system design for scalable, maintainable applications.\n- Skilled in refactoring legacy codebases to improve maintainability, performance, and readability.\n- Fluent in English – strong verbal and written communication skills are essential.\n\nNICE TO HAVE\n\n- Experience with front-end frameworks such as ReactJS, Angular, or Vue.js, along with proficiency in HTML/CSS.\n- Experience working with distributed systems, and message brokers such as Kafka or RabbitMQ.\n- Demonstrated ability to lead or contribute to system migration projects, particularly in migrating legacy Zend Framework applications to Laravel.\n\nACCEPT REMOTE WORKING\n\nWhy you\'ll love working here\n\nCompetitive Salary and Brilliant Health Benefits\n\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan\n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program\n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support.\n- Surrounded with friendly, open-minded, young and supportive colleagues\n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '17th Floor, 36 Tran Quoc Toan, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(438, 302, 2, 'IT Manager (VMware/Cloud/AWS/English)', 'Top 3 reasons to join us\n- Flexible working hour\n- Private health care insurance \n- 13-month salary\n\nJob description\nTeam Leadership & KPI Management\n- Lead and manage the IT team, track and achieve KPIs\n- Foster a culture of accountability, collaboration, and continuous improvement\n- within the IT team.\n\nIT Operations & Service Reliability\n- Ensure uptime, availability, and performance of critical services across distributed datacenters.\n- Oversee backup operations, periodic data restoration tests, and planned failover drills.\n- Maintain documentation of IT infrastructure, services, and processes.\n\nIT Projects: Planning & Execution\n- Plan, drive, and execute IT infrastructure and operations projects\n- Lead cross-functional initiatives involving Dev, QA, Security, and Product teams.\n- Ensure project delivery on time, within scope and budget.\n\nSupport for Dev & QA Teams\n- Investigate and evaluate new platforms, tools, and systems to support development and testing efforts.\n- Install, configure, and troubleshoot development and QA environments\n- Provide timely technical support for Dev and QA teams\n\nSystem Management & Troubleshooting\n- Manage installation, configuration, and maintenance of hardware, software, and network infrastructure.\n- Proactively identify and resolve system issues\n- Automate repetitive tasks using scripting and configuration management tools\n\nSecurity & Compliance\n- Collaborate with the security team to implement and maintain IT security policies.\n- Enforce access controls, patch management, and endpoint protection.\n- Support compliance audits by maintaining logs, reports, and documentation.\n\nYour skills and experience\nYou properly are a potential candidate for this position, if you have:\n- 7+ years of experience in IT management\n- 2+ years of experience working in mid-sized private sector companies\n- Experience leading and managing large IT projects\n- Expertise with managing physical, virtual, and cloud infrastructures\n- Excellent written and verbal communication skills\n- English level: Fluent or Advanced\n- Higher education\n\nYou would be a strong candidate, if you have one of these following:\n- Professional certifications\n\nGiven the high volume of CVs applied, we can only manage to respond to candidates whose profiles aligns with the position within 5 working days. We appreciate your understanding and enthusiastic towards our company.\n\nWhy you\'ll love working here\nThe Nakivo team in Vietnam has been changing very fast in the recent years, we have grown from a group of 6 engineers to the current team size of 80 and we are expecting to grow even more in the next following years. \nWe welcome and embrace people, regardless of their background, religion, nationality or gender, but focus on diversity, contribution, determination and work ethic. At Nakivo, we are trying to improve every day, to become a competitive choice for talented people, by offering\n- Flexible working hours: Office opens from 6.00 AM to 10.00 PM\n- 13-month bonus & performance bonus\n- 100% salary on probationary period\n- Private health care package\n- Healthcare package for family members\n- Premium health care check\n- Gift (cash/voucher) for every special occasion: New Year\'s Eve, Tet holidays, International Women\'s Day, International Children\'s Day, Mid-Autumn Festival and Birthday\n- 15-18 annual leaves/year, 5 sick leaves and additional leaves (up to 3 days)\n- Team building\n- Free and un-limited snack, tea, coffee and by-choice request.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '16 Le Quy Don, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(439, 348, 2, 'Mid - Lead Software Engineer (Java, Full-stack)', 'ABOUT US\nFounded in 2016, Katalon is the leading provider of a modern, comprehensive quality management platform. Katalon Platform enables quality assurance, DevOps, and software teams of any size to deliver world-class customer experiences faster, easier, and more efficiently. Since its first launch, Katalon has experienced tremendous growth, serving more than 100,000 users across 30,000 teams of all shapes & sizes, many of which are in the Fortune Global 500, such as PwC, KPMG, Abbott, etc. Katalon is recognized as a top automation tool by prestigious review sites, such as Gartner, Capterra, and IT Central Station.\n\nABOUT POSITION\nWe are looking for talented Full-stack Engineers (Mid & Lead levels) to join our growing team behind Katalon - an AI-augmented test automation solution that automatically discovers, models, generates, and maintains user-journey test cases. TrueTest provides a streamlined test generation process, saving time and improving testing efficiency. You’ll work on cutting-edge features using modern tech stacks such as Java, Spring Boot, Quarkus, PostgreSQL, Kafka, React, and Generative AI, contributing directly to systems that scale globally.\n\nWhat You’ll Do\nAs a Mid-Level Engineer:\n- Develop and maintain scalable backend services and user interfaces.\n- Implement microservices using Java (Spring Boot/Quarkus) and PostgreSQL.\n- Build responsive UIs with React and integrate event-driven workflows via Kafka.\n- Collaborate with cross-functional teams to deliver high-impact product features.\n- Write unit tests and participate in code reviews to ensure code quality.\n- Apply AI tools to improve development efficiency and reduce repetitive work.\nAs a Lead Engineer, you’ll also:\n- Drive architecture design for distributed, secure, and high-performance systems.\n- Lead by example through mentoring and enforcing engineering best practices (SOLID, CI/CD, etc.).\n- Identify areas for system-wide improvement and influence technical direction.\n- Ensure cross-team collaboration with product, infra, and data teams.\n- Contribute to building internal tools, frameworks, and reusable components.\nYour skills and experience\nMust-Haves (All Levels):\n- Strong software engineering foundation and product-oriented mindset.\n- Proficient in Java and frameworks (Spring Boot/Quarkus).\n- Experience with PostgreSQL, React, Kafka, Docker, and Kubernetes.\n- Familiar with CI/CD tools like GitHub Actions or similar.\n- Exposure to AI technologies or willingness to adopt them into workflows.\n- Good communication and collaborative skills in a fast-paced environment.\nFor Lead Level:\n- Proven experience designing system architecture for large-scale applications.\n- Strong leadership in mentoring, design reviews, and team enablement.\n- Comfortable owning codebases and delivering end-to-end technical solutions.\nWhy you\'ll love working here\nAt Katalon, we bring together self-starting, open-minded, and talented people while actively promoting a transparent and growth-enabling working environment. But don’t just take our word for it. Take a better look below!\n- Competitive Pay & Bonuses: We believe in rewarding great work! You\'ll receive an attractive salary package plus performance bonuses to help you meet your financial goals.\n- Your Health & Happiness Matter: Take care of yourself with our comprehensive health coverage, flexible work options, and generous time off. We understand that life happens outside of work too!\n- Location-Tailored Benefits: Enjoy a complete benefits package designed specifically for your country, giving you the best coverage where you live.\n- Everything You Need to Succeed: Work with top-of-the-line equipment and enjoy modern facilities, plus helpful allowances to support your work setup.\n- A Place Where You Belong: Join our worldwide family where we celebrate what makes each of us unique. Here, everyone has a voice and equal opportunities to shine.\n- Room to Grow & Thrive: Your success is our success! We foster a trust-based culture where you can develop your skills, take on new challenges, and be recognized for your achievements.\n\nKatalon is proud to be an equal-opportunity employer. We care about our people and celebrate our differences. We want to work with talented, collaborative, and innovative people. We do not discriminate in hiring or any employment decision based on race, color, religion, national origin, age, sex (including pregnancy, childbirth, or related medical conditions), marital status, ancestry, physical or mental disability, genetic information, veteran status, gender identity or expression, sexual orientation, or other characteristics protected by law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Complex Building, 285 Cach Mang Thang 8 Street, District 10, HCMC, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(440, 357, 2, 'Middle Frontend Developer (JavaScript)', 'Top 3 reasons to join us\n- Start up company\n- Hybrid working\n- Work-Life Balance\n\nJob description\n- Build and maintain micro-frontend applications for individual games \n- Ensure the platform’s performance, scalability, and cross-platform compatibility (desktop, mobile) \n- Work closely with backend developers to integrate with APIs, WebSockets, and real-time services.\n- Collaborate with UX/UI designers to ensure seamless and engaging user experiences. \n- Write clean, maintainable, and scalable code.\n\nYour skills and experience\n- 3+ years of experience in frontend development, with a strong focus on web applications\n- Proficiency in HTML/CSS, JavaScript, TypeScript including working with complex data models\n- Understanding of WebSockets, real-time communication\n- Experience with front-end framework (e.g. React with Redux, Saga) \n- Experience with backend development with .NET or NodeJs and Microservice is a plus\n\nWhy you\'ll love working here\n- Competitive salary\n- Hybrid work style with 6 - 8 remote days per month—balance work and life your way.\n- 12 paid leave days per year, plus national holidays.\n- Flexible hours, Monday to Friday—your weekends are all yours.\n- Work with a young, passionate, and supportive team that loves what they do.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Co-working, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(441, 358, 2, 'Senior Data Engineer', 'Top 3 reasons to join us\n- Attractive benefits regime, leading the market\n- No.1 Dairy Company in Vietnam \n- A culture that inspires work and creativity\n\nJob description\n- Possess an understanding of the data structures and governance.\n- Build the infrastructure required for optimal extraction, transformation, and loading of data from a wide variety of data sources.\n- Design and maintain optimal data and machine learning pipeline architecture.\n- Assemble large, complex data sets to build data marts that meet functional/non-functional business requirements.\n- Communicate effectively with Developers and Business users to understand and clarify requirements.\n- Support internal training and proper documentation ensuring the successful onboarding of new team members\n- Implement internal process improvements: automating manual processes, optimizing data delivery, re-designing infrastructure for greater scalability, etc.\n- Develop efficient software code for multiple use cases leveraging big data technologies for various use cases built on the platform\n\nYour skills and experience\n- Bachelor’s degree in computer science, engineering, management information system or a related technical discipline.\n- 3+ years’ experience working as a Data Engineer role, ETL with large amounts of data.\n- Experience with software engineering best practice in version control and CI/CD\n- Experience with data warehousing architecture and data modeling, ETL data pipeline in both batch and real-time applications\n- Obsessed with Data Quality and Data Observability. Experience in data lineage and data testing processes\n- Experience with using the following software/tool in the big data field.\n  - Workflow management tools: Airflow, Prefect, Dagster, etc.\n  - ETL/Reverse tools: Talend, CDAP, Azure Data Factory, Airbyte/ Matillion, Census, dbt, etc.\n  - Big data technology: Apache Spark, Apache Beam, Presto, Kafka, Redis, etc.\n  - NoSQL and OLAP database: MongoDB, Elastic search, Clickhouse/Druid, Prometheus, InfluxDB, etc.\n  - Monitoring tools: Grafana, Kibana, etc.\n  - Linux and command line interfaces\n- Good at programming languages: Python, Java, etc.\n- Experience in performing root cause analysis, identify problems and propose recommendations for improvement.\n- Strong organizational and multitasking skills with the ability to balance competing priorities\n- Experience modern cloud computing platforms and concepts is a plus (Azure/GCP)\nWho we are looking for\n"Attitude eats skills for breakfast": we greatly value people who possess the 3 personal traits:\n- Growth mindset\n- Curiosity\n- Automation\n\nWhy you\'ll love working here\n- Competitive salary and benefits on Top in VietNam.\n- Attractive 13th-month salary and high performance bonus in the year.\n- Annual performance review for salary raise and promotion.\n- Premium private insurance with a discount for family members.\n- Annual health check.\n- Company trips and team buildings.\n- Gifts on special accession: individual /company birthday, Tet, and Holidays.\n- Internal activities, sport, and social clubs, gym, yoga, swimming…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vinamilk Tower, 10 Tan Trao St., Tan Phu Ward., District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(442, 359, 2, 'Remote Golang / Go Engineer - Up to 100M/month', 'We are looking for a highly skilled Senior Go / Golang Developer to join our team, a fast-growing SaaS solution in the online advertising space. You can work either in a flexible Office space, but we also offer 100% home office and remote work options.\n\nYou work for a profitable, operating SaaS solution designed for online advertising. The platform allows advertisers to monitor and optimize their ad spending and revenues across multiple channels. We love working with cutting-edge technologies and massive datasets, always focusing on performance optimization.\n\nWhy Join Us?\n\n1. Work with a efficient European Top-Notch Teams: Collaborate directly with the top engineers in Europe.\n2. 100% Home Office & Remote Work: Enjoy flexibility to work from anywhere, with no need to relocate.\n3. Outstanding Benefits: 20 days of paid annual leave, and no worries about overtime – we believe in work-life balance.\n4. Top Salary & Perks: We offer competitive compensation and state-of-the-art hardware to support your work.\n5. Growth Opportunities: You’ll have a real impact, shaping the product with your ideas and insights.\n6. Continuous Learning: We support your career development through training and learning opportunities.\n\nYour skills and experience\n\n1. Fluent English\n2. Extensive experience in Web / SaaS development\n3. Expertise in Golang / Go and complementary technologies\n4. Experience with ClickHouse or column-oriented databases is a big plus\n5. Familiarity with web technologies like HTTP, Cookies, and Local Storage\n6. Ideally, some exposure to online advertising/marketing\n7. Strong independent work style\n\nWhy you\'ll love working here\n\n- 100% Home Office & Remote possible\n- 20 Days paid annual leave\n- Top Salary\n- No Overtime issues\n- Top Work Environment\n- State-of-the-Art Hardware', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote', 'Full-time', '2025-10-07 20:59:18.149534'),
	(443, 360, 2, 'Intermediate Tester (QA QC, English)', 'Are you an Intermediate Tester seeking an exciting opportunity to be part of an international team? Look no further! We are thrilled to offer a unique position in Ho Chi Minh City for an Intermediate Tester.\n\nResponsibilities:\n- Be a founding member of a new development team focused on software solutions.\n- Collaborate closely with developers, Business Analysts, and other team members.\n- Independently design, develop, and execute comprehensive test plans and strategies.\n- Perform functional and regression tests manually to validate software functionality.\n- Work with tools such as Katalon, Postman, Cypress, etc., to test components and APIs.\n- Collaborate with cross-functional teams in Vietnam and the Netherlands to deliver exceptional products.\n\nYour skills and experience:\n- Bachelor’s degree in Computer Science, Engineering, Mathematics, or a related analytical field.\n- 3+ years of experience in software testing.\n- Excellent written and verbal English communication skills.\n- Solid understanding of the software development life cycle and quality assurance practices.\n- Ability to work independently and take full ownership of testing efforts.\n- Strong attention to detail and commitment to delivering high-quality results.\n- Hands-on experience with testing tools such as Katalon, SoapUI, and Postman.\n- Strong analytical and problem-solving skills.\n- Experience in applying various testing methodologies effectively.\n\nWhy you\'ll love working here:\n- Attractive salary with annual performance review.\n- Fixed 13th-month salary and performance bonus.\n- Full salary during probation and full social insurance coverage.\n- Hybrid working model with a good work-life balance.\n- Premium healthcare (including annual health check-up).\n- 16 days of annual leave per year.\n- 5 paid sick leave days.\n- Dynamic and international English-speaking working environment.\n- Regular gatherings (happy hours, bimonthly dinners, social events, etc.).\n- Annual company trip.\n- Fully stocked pantry with coffee and snacks.\n- Budget for team activities.\n- Supportive and diverse work environment that promotes continuous learning.\n- Opportunity for traveling and training in the Netherlands.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '106 Nguyen Van Troi Street, Ward 17, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(444, 361, 2, 'Bridge Software Engineer (BrSE, N2, Technical)', 'We are looking for a Bridge System Engineer (BrSE) to support our projects by facilitating communication between our development team and Japanese clients.\n\nResponsibilities:\n- Assist the Project Manager (PM) and other BrSEs in direct client interactions, including requirement negotiations with Japanese clients.\n- Act as a bridge between the development team and Japanese clients, ensuring smooth communication and understanding of project requirements.\n- Translate project documents and specifications between Japanese and the development team.\n- Support the development team in preparing reports and tracking project progress.\n- Assist the Project Manager or Team Leader with management tasks.\n\nYour skills and experience\nGeneral Requirements:\n- Japanese proficiency at N2 level or higher.\n- Strong understanding of IT workflows with the ability to adapt flexibly.\n- Creative, proactive, and willing to take on challenges. Able to work under high pressure.\n- Willingness to travel for business trips when required.\n\nTechnical & Communication Skills:\n- Experience in real-world communication using Japanese.\n- Basic knowledge of IT software development.\n- Prior experience working in Japanese IT companies is preferred.\n- Background as a software engineer (in any role) is a plus.\n- Strong logical thinking, problem summarization, and communication skills.\n\nWhy you\'ll love working here\nCompensation and benefits:\n- Attractive salary and benefits (Salary review - 2 times/year)\n- Insurance contribution equal to 100% of salary. Year-end bonus.\n- Annual health check for all employees.\n- MacBook or personal laptop provided.\n\nSpiritual life:\n- Monthly party with food and drink.\n- Team Building, Company Trip,... and other project activities.\n- Free foreign language training: English and Japanese.\n- Opportunity to work in Japan.\n- Gifts and allowances for Weddings, Childbirths, Women\'s Day, and Children\'s Day\n- Professional, friendly, and open working environment\n- The company organizes birthday parties for employees monthly, organizes bonuses and celebrations. celebrate the holidays of the year.\n\nWorking time and place of working time:\n- Working from Monday - Friday and the last Saturday of the month, working hours 8:30 - 17:30 (8 hours/day), public holidays according to state regulations;\n- Floors 3 -5 , Waseco Building, No. 10 Pho Quang, Ward 02, Tan Binh District, Ho Chi Minh City.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '301, Block B, Waseco Plaza, 10 Pho Quang, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(445, 362, 2, 'Wordpress Developer (AI, Python)', '1. Chiến lược SEO dẫn dắt bởi AI\n- Nghiên cứu từ khóa bằng các công cụ AI (Bard, Gemini, Google Keyword Planner AI), phân tích ngữ nghĩa và ý định người dùng.\n- Tạo khung nội dung chuẩn SEO bằng AI, kiểm tra nguyên bản >98% (Originality.ai) và tuân thủ EEAT.\n- Phân tích SERP tự động (Frase, Clearscope), tối ưu thẻ H/meta, xây dựng liên kết nội bộ động.\n\n2. SEO kỹ thuật và xây dựng liên kết\n- Chẩn đoán lỗi kỹ thuật bằng Search Console AI, tối ưu tốc độ trang và Core Web Vitals.\n- Dùng AI để tìm nguồn backlink chất lượng (BuzzStream, Ahrefs AI) và triển khai guest post.\n- Phân phối nội dung đa nền tảng (Synthesia video, Google News AI).\n\n3. Phân tích dữ liệu & thử nghiệm AI\n- Cấu hình Google Analytics 4 + Looker Studio để theo dõi KPI, tạo báo cáo tự động.\n- A/B testing bằng AI (Google Optimize, Mutiny) để tối ưu chuyển đổi trang đích.\n- Quản lý plugin AI và đồng bộ nội dung đa trang với WP All Import + ChatGPT.\n\n4. Tối ưu WordPress bằng AI\n- Quản lý cấu trúc WordPress, nén ảnh tự động (ShortPixel AI), tối ưu AMP và giao diện mobile-first.\n- Cài đặt, giám sát và sửa lỗi tự động qua Screaming Frog + AI (ChatGPT prompt).\n- Dự báo và tối ưu tài nguyên server dựa trên mô hình lưu lượng truy cập AI (GA4 + Cloud).\n\n5. Khai thác từ khóa và ý định chuyên sâu\n- Dùng Google Natural Language API để phân tích nội dung đối thủ, trích xuất từ khóa LSI/entity.\n- Kết hợp Ahrefs + Bard để khai thác câu hỏi đuôi dài, mở rộng thư viện từ khóa mạng xã hội (Brand24).\n- Theo dõi và phân tích SERP đối thủ bằng SurferSEO, SEMrush, tạo báo cáo chiến lược bằng ChatGPT.\n\nYour skills and experience\nKỹ năng bắt buộc:\n- Tối thiểu 2 năm kinh nghiệm SEO/WordPress, từng triển khai thành công các dự án lên Top với AI hỗ trợ.\n- Thành thạo các plugin SEO AI (AIOSEO, RankMath AI), hiểu cách tối ưu nội dung GPT-4/Gemini.\n- Có kỹ năng sử dụng công cụ Google AI (GA4, Search Console AI, Bard Prompt, Natural Language API).\n- Có thể viết script cơ bản (Python) để tích hợp API AI vào hệ thống WordPress.\n\nKỹ năng bổ sung:\n- Thành thạo công cụ tối ưu ảnh AI (Canva Magic, Adobe Firefly).\n- Có tư duy phân tích dữ liệu và kinh nghiệm xây dựng hệ thống báo cáo Looker Studio.\n\nPhẩm chất & thái độ:\n- Theo kịp xu hướng AI trong tìm kiếm (SGE, đa mô thức).\n- Biết khai thác AI để tăng năng suất nhưng vẫn kiểm soát chất lượng thủ công.\n- Có tinh thần học hỏi, thích đổi mới, phối hợp làm việc nhóm hiệu quả (Notion AI, Slack,...).\n\nƯu tiên:\n- Có chứng chỉ Google Generative AI Engineer Certification học hoặc tương đương.\n- Đã từng triển khai hệ thống SEO tự động hóa hoặc vận hành nhiều site WordPress tích hợp AI.\n\nWhy you\'ll love working here\n- Được làm việc trong môi trường tiên phong ứng dụng AI vào SEO – Web – Tăng trưởng.\n- Cơ hội phát triển kỹ năng Prompt Engineering và làm việc với các công cụ mới nhất từ Google.\n- Được trao quyền đề xuất chiến lược, tối ưu công cụ và trực tiếp ảnh hưởng tới doanh thu.\n- Văn hóa minh bạch, linh hoạt, ưu tiên hiệu quả và học tập không ngừng.\n- Lương thoả thuận theo năng lực, các chính sách thưởng và phúc lợi theo lục quy định.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 6, đường 9A, An Lạc, Binh Tan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(446, 363, 2, 'IT System & Solution Leader', 'Job description\n• Tiếp nhận và quản trị hệ thống giải pháp/phần mềm Công ty đã phát triển\n• Cập nhật, đánh giá và đề xuất cải tiến giải pháp/phần mềm\n• Tham gia thiết kế, phát triển module/sản phẩm mới \n• Theo dõi, giám sát hoạt động hệ thống, phần mềm, phát hiện và xử lý sự cố kịp thời\n• Xử lý các sự cố liên quan đến hệ thống mạng LAN/WAN, database, server\n• Đánh giá, tối ưu hiệu năng ứng dụng và hệ thống backend\n• Hỗ trợ team dev trong việc troubleshoot, debug và tối ưu code\n• Nghiên cứu công nghệ mới và đề xuất cải tiến hệ thống\n• Phân tích luồng nghiệp vụ, đề xuất giải pháp kỹ thuật phù hợp\n• Thực hiện demo, triển khai setup hệ thống cho đối tác, khách hàng khi có yêu cầu\n• Tư vấn, triển khai các giải pháp công nghệ, sản phẩm phục vụ chiến lược chuyển đổi số, số hóa quy trình hoạt động của công ty\n• Nghiên cứu, đề xuất các sáng kiến cải tiến hạ tầng, hệ thống CNTT nhằm nâng cao năng suất, hiệu quả.\n\nYour skills and experience\n• Tốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT, Kỹ thuật phần mềm hoặc lĩnh vực liên quan.\n• Có ít nhất 03 năm kinh nghiệm ở vị trí quản trị hệ thống, hạ tầng, hỗ trợ người dùng.\n• Có ít nhất 01 năm kinh nghiệm team leader ngành CNTT.\n• Kinh nghiệm quản trị Windows Server, Active Directory, email server, cloud service cơ bản (Google Workspace, Office 365, AWS/Azure cơ bản).\n\nWhy you\'ll love working here\n• Mức lương cạnh tranh (tùy theo năng lực).\n• Tham gia đầy đủ chế độ BHXH, BHYT, BHTN theo quy định.\n• Môi trường làm việc chuyên nghiệp, năng động, nhiều cơ hội phát triển nghề nghiệp.\n• Cơ hội tham gia các dự án công nghệ mới, giải pháp chuyển đổi số tiên tiến.\n• Được đào tạo, nâng cao kiến thức về hệ thống, giải pháp, kỹ năng mềm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '120 Nguyễn Minh Hoàng, Phường 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(447, 364, 2, 'Data Engineer', 'Key Responsibilities\n\n1. Design, develop, and maintain robust ETL pipelines to process and transform data from various sources into structured formats.\n\n2. Collaborate with stakeholders to understand data requirements and implement solutions that meet business needs.\n\n3. Ensure data integrity, security, and availability across all stages of the data lifecycle.\n\n4. Optimize data storage and retrieval processes for performance and scalability.\n\n5. Develop and maintain data models, schemas, and metadata documentation.\n\n6. Monitor and troubleshoot data systems to ensure smooth operation and timely resolution of issues.\n\n7. Implement best practices for data governance, including compliance with privacy and regulatory standards.\n\n8. Stay updated on emerging data technologies and trends to recommend innovative solutions.\n\nYour skills and experience\n\nQualifications\n\nRequired Skills and Experience\n\n1. Bachelor’s degree in Computer Science, Data Science, Information Technology, or a related field.\n\n2. 3+ years of experience in data engineering, with expertise in building and managing ETL workflows.\n\n3. Proficiency with ETL tools commonly used in data engineering (e.g., SSIS).\n\n4. 3+ years of experience of programming languages such as Python.\n\n5. 3+ years of experience in SQL and database management systems (e.g., MySQL, SQL Server).\n\n6. Understanding of data warehousing concepts.\n\n7. Excellent problem-solving skills and ability to work collaboratively within a team.\n\nPreferred Skills\n\n1. Familiar with cloud platforms like AWS and Azure.\n\n2. Hands-on experience with ETL environments using Azure Data Factory, Azure Data Lake, Databricks, Synapse.\n\n3. Experience with big data technologies such as Hadoop, Spark.\n\n4. Experience with data visualization tools and techniques.\n\nWhy you\'ll love working here\n\n1. Innovative Work Culture: Join a team where creativity and innovation are at the heart of everything we do. Our IT company thrives on new ideas, and we encourage a collaborative environment where every voice is heard. You\'ll have the opportunity to work on cutting-edge projects that push the boundaries of technology.\n\n2. Career Growth & Learning Opportunities: We believe in the power of continuous learning. Whether it’s through mentorship, online courses, or access to industry conferences, we provide the tools you need to grow professionally. You’ll have opportunities to learn and advance in your career, all while working with some of the best minds in the industry.\n\n3. Collaborative Team Spirit: We know that great things happen when people come together. Our teams are diverse, inclusive, and driven to succeed. From brainstorming sessions to cross-departmental collaboration, you’ll work with talented individuals who are passionate about what they do.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '32 Pham Ngoc Thach, Ward Vo Thi Sau, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(448, 365, 2, 'Fullstack Software Engineer (LLMxData Platform/US Co.)', 'Join us in revolutionizing how businesses interact with data! We\'re the Vietnam-based AI team of a $400M/year US healthcare company building a cutting-edge platform that augments Business Intelligence with Agentic AI. Imagine a chat interface that doesn\'t just fetch data, but allows users to interact with structured information intuitively, receive deep-dive analyses, and get actionable business suggestions – all powered by intelligent agents. Our ultimate vision is to replace traditional Data Analysis and BI with a smarter, more proactive AI-driven solution. If you\'re passionate about using LLMs to build the future of data analytics, this is your opportunity.\n\nBonus: We provide a bonus to compensate candidates giving up a 13th month bonus leaving a job mid-year.\n\nKey Responsibilities\n- Architect and Scale Core Systems: Lead the design, implementation, and optimization of highly scalable, fault-tolerant backend services and non-blocking APIs using Python (FastAPI) or Java (Vert.x, Quarkus). Ensure services handle high throughput with minimal latency.\n- End-to-End Product Delivery: Drive the full lifecycle of product features—from requirements gathering and prototyping through testing, deployment, and iteration—working closely with product managers, UX designers, and DevOps.\n- Champion Asynchronous Patterns: Build and maintain event-driven, asynchronous processing pipelines (e.g., message queues, pub/sub) to support real-time data ingestion, processing, and integrations.\n- Performance & Reliability: Establish and enforce best practices for monitoring, observability, and automated testing. Identify bottlenecks and implement caching, connection pooling, backpressure, and rate-limiting strategies to sustain 99.9%+ uptime.\n- Comprehensive Service Monitoring: Design, deploy, and maintain end-to-end observability solutions using Prometheus for metrics collection and Grafana for visualization and alerting.\n- AI & RAG Applications: Architect Retrieval-Augmented Generation (RAG) solutions and intelligent agents that solve real-world problems—integrating vector stores, LLM APIs (e.g., OpenAI), and custom prompting frameworks.\n- Mentorship & Collaboration: Provide technical leadership and mentorship to mid-level engineers, foster a culture of code quality, and collaborate across cross-functional teams to drive continuous improvement.\n\nYour skills and experience\nRequired Qualifications\n- 5+ years of software engineering experience, with a proven track record of building and operating production-grade, scalable applications.\n- Expertise in Python & FastAPI or Java (Vert.x, Quarkus): Deep familiarity with asynchronous programming (async/await in Python or non-blocking event loops in Java), concurrency models, and profiling/tuning of services.\n- API Design Mastery: Hands-on experience building RESTful, GraphQL, or gRPC APIs that support high request volumes; strong understanding of HTTP/2, WebSockets, and protocol optimizations.\n- Cloud & Infrastructure: Proficient with AWS, GCP, or Azure; containerization with Docker; orchestration using Kubernetes/Helm; Infrastructure-as-Code (Terraform, CloudFormation).\n- Data Storage & Caching: Solid background in relational (PostgreSQL, MySQL) and NoSQL (MongoDB, Redis, DynamoDB) databases; designing data schemas for performance and scalability.\n- Asynchronous Ecosystems: Experience with message brokers (Kafka, RabbitMQ, AWS SQS), task queues (Celery, AWS Lambda) or Java equivalents, and stream-processing frameworks.\nPreferred Qualifications\n- RAG & Agent Development: Practical experience implementing Retrieval-Augmented Generation pipelines, vector search (e.g., Pinecone, Weaviate), and building autonomous agents with LangChain or similar frameworks.\n- AI/ML Collaboration: Familiarity with embedding-based search, prompt engineering, chaining, and orchestration of multi-LLM workflows.\n- Observability & Security: Strong grasp of logging, tracing (OpenTelemetry), metrics (Prometheus/Grafana), and security best practices (OAuth2, JWT, encryption).\n- Leadership & Communication: Excellent verbal and written English skills; demonstrated ability to influence technical direction and collaborate effectively across teams.\n\nWhy you\'ll love working here\n- Great compensation + 13th month bonus\n- Mission-driven startup culture (less politics) in a growing company ($400M in annual revenues!)\n- Build with a great team at the frontiers of AI with strong focus on learning\n- Opportunities to rotate to our US office (if desired)\n- Leaving bonus: We provide a bonus to compensate candidates giving up a 13th month bonus leaving a job mid-year.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '92A Nguyen Huu Canh St., Ward 22, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(449, 366, 2, 'Backend Engineer (Java/Kotlin/Spring) - NAVER CLIP', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea’s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia’s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us:\n\nWe are looking for Backend Engineers (Java/Kotlin/Spring).\n\nYour daily task:\nDeveloping and improving NAVER Clip(short-form video) Service backend system:\n- NAVER Clip event/promotion service page\'s backend API\n- Management system of general Clip business for administrator\n- Supporting system of Clip influencer\'s profile home\n- Additional development tasks related to the NAVER Clip domain\n- Collaborate with a Global team (Korean)\n\nYour background:\n- Over 2 years of experience in backend system development with Java\n- In-depth understanding of HTTP-based web services and video playback on web pages\n- Experience in development using Spring and Kotlin frameworks\n- Proficient in at least one RDBMS\n- JavaScript development experience in building dynamic web applications\n- Basic backend design skills based on an understanding of MSA, RESTful, etc\n- Positive mindset and a considerate attitude towards colleagues\n- Strong communication skills in English\n\nIt\'s a big plus if you:\n- Full-stack web developer\n- Maintenance of backend systems for handling massive-traffic volumes\n- Experience with NoSQL solutions\n- Experience in data analysis based on Big Data\n- Familiar with and able to use React as a front-end library\n- Strong communication skills in Korean\n\n*Due to the volume of interest and applications we receive, our response time may be slower than usual. We appreciate your patience and understanding as we carefully review each application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '4th and 9th Floor, Block B, Viettel Building, 285 CMT8, Ward 12, District 10, Ho Chi Minh city, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(450, 367, 2, 'Data Engineer (Python, SQL, Azure)', 'Job description\n- Create efficient ETL processes for data extraction, transformation, and loading.\n- Ensure high-quality data by implementing validation checks and monitoring.\n- Collaborate with data analysts to deploy semantic models into production.\n- Optimize data pipelines for scalability and performance.\n- Build solutions to monitor performance of the data pipelines deployed and take corrective measures when necessary.\n- Work closely with software engineers, product managers, data analysts and data scientists.\n- Communicate findings to technical and non-technical stakeholders through clear and compelling presentations and reports.\n- Take part in innovation projects and collaborate closely with academic institutions.\n\nYour skills and experience\n- Experience: Minimum of 3 years in a data engineering role.\n- Technical Skills:\n  - Proficiency in designing data pipelines and ETL tools (e.g., Azure Databricks or MS Fabric).\n  - Proficiency in Python or strong SQL knowledge for data manipulation and querying.\n  - Experience with Microsoft Azure cloud platform.\n  - Experience with CI/CD pipelines and good software development practices, including version control, code organization and testing.\n  - Knowledge in DataOps and MLOps.\n  - Experience working in an agile (Scrum or Kanban) framework.\n  - Ability to share knowledge and mentoring junior team members.\n  - Good analytical skills.\n  - Very good understanding of data models and experience with medallion architect.\n  - Eager to learn work with the newest technologies.\n  - High initiative and ability to work independently.\n  - Solution-oriented, pragmatic, with an eye for detail and capable of explaining decisions and results.\n  - Good communication skills.\n\nWhy you\'ll love working here\n- Your Career\n  There is one overriding reason for our success – and that is you. If you are not growing, then neither are we.\n- Your Leave\n  Enjoy your time off, you’ve earned it! Work life balance is essential, we offer generous holiday allowances, as well as loyalty leave and charity leave.\n- Your Lifestyle\n  Work. Life. Balance. We want to support good health and wellbeing and know that your lifestyle is key to this. The way we work and how we relax are recognised through our lifestyle benefits.\n- Your Community\n  Giving something back. Community is at the heart of how we operate and our ethos. To recognise this we offer charity matching, charity leave and the opportunity to get involved in corporate fundraising events and activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Savills Vietnam – 18th floor, Doji Tower, 81 - 85 Ham Nghi Street, Nguyen Thai Binh Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(451, 297, 2, 'Fullstack Developer Python/ReactJS/AI', 'We are looking for a Fullstack Web Developer with a strong emphasis on backend development using Python and hands-on experience in AI/LLM integration. This role is ideal for someone passionate about building scalable, high-performance web systems, with deep expertise in API design, cloud infrastructure, database architecture, and modern security practices. While frontend experience with ReactJS (or similar frameworks) is required, the focus of this role is on backend engineering and delivering solutions powered by AI technologies.\n\nLocation: Ho Chi Minh, Da Nang, Hanoi\n\nWhat You’ll Be Doing\n\nWorking on Web and Mobile products for a diverse range of clients and industries.\nWorking and pair programming with other developers to build applications with Python and ReactJS.\nDesigning & implementing back-end API using Python\nWorking with the Product Owner to convert business requirements into technical designs.\nCooperating with the UI Designer to implement modern minimalist designs into production.\nApplying proven technologies and best practices to level up your technical skills: NestJS, Redux\nLearning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n\nYour skills and experience\n\nRequirements\n\nMust have\n\n5+ years of experience in backend development using Python\n3+ years of experience in frontend development using ReactJS or similar frameworks (Vue, Svelte, Angular)\nProven expertise in designing and implementing RESTful APIs, scalable web architecture, and deploying to cloud platforms (AWS, GCP, or Azure)\nHands-on experience with Python for backend development; experience integrating AI/ML solutions into web applications is a strong plus.\nStrong working knowledge of relational databases and NoSQL (e.g., MySQL, PostgreSQL, SQL Server, MongoDB ...)\nFamiliarity with Extreme Programming (XP) practices such as Test-Driven Development (TDD), Continuous Integration (CI), and code refactoring\nFamiliar with event-driven tech and message brokers (Kafka, RabbitMQ...)\nExperienced with micro services and data-intensive applications\nExperience working within Agile/Scrum teams\nExcellent English communication skills, both written and verbal\n\nNice to have\n\nExperience with NodeJS and Golang\nExperience with serverless architecture, e.g., AWS Lambda, GCP Cloud Function, etc.\nExperience with data security, performance, and scalability.\nExperience integrating LLMs (e.g., OpenAI, Hugging Face) into production applications.\n\nWhy you\'ll love working here\n\nWho We Are\n\nCodeLink is an innovative and design-focused development agency. We focus on user-centric design and agile development to bring the product vision of our clients to life. We handle the end-to-end development of products, developing the product vision through product understanding, designing experiences through UX design, refining these flows with modern UI design, and developing products through iterative agile development.\n\nWe work with both early-stage product teams and teams with existing products from a wide range of countries and industries. We focus on modern technologies and work directly with our clients. We design using design-thinking principles on tools such as Sketch, Figma, Zeplin, and more, and develop products leveraging our tech stack of React, React Native, Rails, Python, and Node.JS.\n\nOur Core Values\n\n1. Take full ownership of delivery\nWe take ownership of our client projects and ensure that we deliver what we are in charge of to the best possible outcome.\n\n2. Deliver our highest level of quality\nWe take pride in the high quality that we deliver and work at a sustainable pace to ensure we can always deliver on that quality.\n\n3. Stay consistent in plans and processes\nWe keep open and transparent communication with our teammates and our client whilst following agile development practices.\n\n4. Have empathy for all those we work with\nWe show empathy and respect to all those we work with to gain a deeper understanding without any judgment or assumption.\n\n5. Continuously improve and grow\nWe aim high with a growth mindset and see every day as an opportunity to develop ourselves, our processes, and our products.\n\nTop 3 Reasons To Join Us\n\nUse cutting-edge & proven technologies\nWork directly with international clients\nOpen environment with a focus on learning\n\nWhy You’ll Love Working With Us\n\nWe work hand-in-hand with our clients to fully invest in their product development and build solutions together for their target market.\n\nWe fully invest in our team, we will help you build yourself up in any area you feel you need development, be it in English, learning a new design tool, developing your design thinking, and more. We want to make sure that you’re always learning and developing yourself whilst a part of our team.\n\nWe respect both Product and Technology equally, ensuring all of the Products we work on have features with true market potential and ensuring all of the team contribute to, understand, and believe in what they are developing.\n\nWe are very selective with our clients, we only work on awesome products we believe in and that show strong market potential.\n\nWe respect you and your personal hours, we keep a sustainable pace by working standard 8 hour days from Monday to Friday, ensuring we only plan for what we can achieve.\n\nWe are fully agile and only work with Clients who work the same, working with set sprint goals and working at our rate of velocity.\n\nYou will have ownership over your role, giving you the opportunity to experiment and try new processes to better improve your day-to-day responsibilities. We are always open to improving our processes.\n\nBenefits\n\nThree days remote every week and four full remote weeks per year.\nGold level Health Insurance coverage from Bao Viet Insurance, a yearly complete Health Check and social insurance\nAll office benefits and full salary during probation.\nFlexible working time starting anytime up to 10 AM working Monday - Friday with no overtime and a long lunch break.\nAllowance for everything: meals, parking, petrol, along with unlimited snacks and nice coffee every day.\nChoose from a brand-new Mac or PC device.\nSalary review twice a year with opportunities for promotions and spot awards.\n12 days annual leave per year, with all days not taken paid out in cash, plus 2 sick leave days..\nYearly Training Budget up to 5 million VND per staff. On top of that, Professional coaching program, buddy system, tech talks, agile sessions, and 1on1 private English classes are available\nYearly company trip, monthly activities, and other Celebrations for special days in the year, such as Women’s Day, YEP, and Christmas.\nEmployee-led clubs within the company; games teams, sports teams, etc.\nModern open-space office with comfortable workspace, a PS4 games room, and chill-out areas.\n\nWhere We Work\n\nHCMC Head Office: Level 8, Vina Building, 131 Xo Viet Nghe Tinh, Ward 17, Binh Thanh District, HCMC\nHanoi Office: Ba Dinh District, Ha Noi City\nDa Nang Office: Hai Chau District, Da Nang City.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Da Nang, Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(452, 368, 2, 'Senior Fullstack Engineer (TypeScript/ReactJS/NextJS)', 'About BeWao\nBeWao is a pioneering health and wellness platform tailored to the Vietnamese market. We empower users to achieve their nutrition and fitness goals through personalized solutions driven by cutting-edge technology and localized expertise. As part of our mission to redefine health in Vietnam, we are seeking a talented Senior Fullstack Software Engineer to join our dynamic team.\nAbout the Role\nAs a Senior Fullstack Software Engineer, you’ll play a pivotal role in building and maintaining our health and wellness applications. Collaborating closely with our Product and Design teams, you’ll focus on creating seamless, user-centric experiences while ensuring robust, scalable, and efficient codebases.\nWhat You’ll Do\n- Design, develop, and maintain new features for BeWao\'s health and wellness platform.\n- Work across the full technology stack—frontend, API, and backend—to deliver high-quality solutions.\n- Architect and implement multi-service systems that ensure consistent, efficient, and reliable data flow.\n- Quickly identify and resolve issues to maintain product reliability and enhance the user experience.\n- Collaborate with cross-functional teams to optimize developer workflows, deployment strategies, and testing processes.\nYour skills and experience\nWe’re looking for a passionate, growth-oriented engineer who thrives in a startup environment. You should be:\n- Experienced: 4+ years of professional experience in building and maintaining consumer-grade web or mobile applications.\n- Knowledgeable: Proficient in modern full-stack development, with expertise in frontend frameworks, APIs, and backend services.\n- Skilled: Strong programming and Computer Science fundamentals, with a focus on building reliable, scalable software.\n- Collaborative: A team player who values feedback and actively contributes to the growth of peers.\n- Growth-Focused: Committed to continuous learning and improvement in both technical and non-technical domains.\nTechnologies We Use\n- Core Stack: TypeScript, GraphQL, ReactJS, React Native, NextJS, NestJS, PostgreSQL, MongoDB\n- Styling: Tailwind CSS, Headless UI\n- Infrastructure: GCP, Serverless, Redis, Elasticsearch, Cloudflare Workers, HL7, FHIR (optional)\nWhy you\'ll love working here\n- Competitive salary and benefits: Up to 50M\n- Generous leave policy:  \n  - Public holidays  \n  - 12 days annual leave  \n  - 3 additional Company Holidays (Christmas, Vietnamese Family Day, Birthday leave)\n- Comprehensive insurance coverage and allowances (parking, transportation).\n- Performance-based annual 13th-month salary (may apply).\n- Recreational facilities (billiards, table tennis) for a balanced work-life experience.\nApply Now\nJoin BeWao and be part of a team shaping the future of health and wellness in Vietnam. Let’s build something amazing together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '95-97 Nguyễn Cơ Thạch, Phường An Lợi Đông, Thành phố Thủ Đức, TP Hồ Chí Minh, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(453, 369, 2, 'Full Stack Developer (.NET Core, DevExtreme, ReactJS)', 'Experience: 3+ years\nLocation: Full-time, On-site\nDatabase: Oracle\n\nYour skills and experience\nFrontend Development:\n- Proficient in React.js and DevExtreme for building dynamic user interfaces\n- Skilled in API integration and session management on the frontend\n- Experience with DevExpress components for .NET-based UI development\n- Familiarity with internationalization (i18n) and localization support\n\nBackend Development:\n- Strong command of .NET Core for developing scalable backend services\n- Expertise in REST API development and integration\n- Ability to interact with Oracle databases, including calling stored procedures and handling responses\n- Implementation of JWT and claims-based authentication for secure access\n- Backend session handling and caching strategies for performance optimization\n\nTesting & Documentation:\n- Proficient in using Postman and Swagger for API testing and documentation\n- Experience writing unit tests for both frontend and backend components\n\nAdditional Skills:\n- Solid understanding of error handling and centralized logging across the stack\n- Version control using Git/GitHub for collaborative development\n- Core knowledge of General Insurance is an added advantage.\n\nWhy you\'ll love working here\nAll the benefits according to Vietnam Labour Law', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(454, 353, 2, 'Giám đốc Công Nghệ - HD Financial Group', 'HD Financial Group là Tập đoàn tài chính bao gồm hơn 10 định chế: HDBank, Vikki Bank, Công ty tài chính HDSaison, Bảo hiểm HDI, Chứng khoán HDS, Công ty Quản lý quỹ HD Capital...\nHD Financial Group đang tìm kiếm những nhà quản lý tiên phong, những chuyên gia xuất sắc trong từng lĩnh vực, những người có khát vọng định hình tương lai cùng mở ra kỷ nguyên tăng trưởng mới. Công việc cụ thể:\n- Đồng hành cùng chủ tịch và các lãnh đạo cấp cao trong việc xây dựng chiến lược kinh doanh của Tập đoàn.\n- Dẫn dắt chiến lược công nghệ ngân hàng số với tư duy kinh doanh - bảo đảm hệ thống linh hoạt, an toàn và sáng tạo để phục vụ tăng trưởng, tối ưu vận hành và nâng cao trải nghiệm người dùng, thúc đẩy mô hình kinh doanh số, khai thác dữ liệu và mở rộng hệ sinh thái thông qua công nghệ.\n\nYour skills and experience:\n- Tốt nghiệp đại học trở lên chuyên ngành Công nghệ Thông tin, Khoa học máy tính, Hệ thống thông tin hoặc các ngành liên quan. Ưu tiên ứng viên có bằng Thạc sĩ và/hoặc chứng chỉ quốc tế: TOGAF, AWS/Azure Certified Architect, PMP, CISO, v.v.\n- Tối thiểu 10 năm kinh nghiệm trong lĩnh vực công nghệ, trong đó có ít nhất 5 năm ở vị trí lãnh đạo cấp cao tại tổ chức tài chính, fintech, hoặc ngân hàng số.\n- Ưu tiên ứng viên có kinh nghiệm triển khai core banking, API platform, cloud computing, data lake/warehouse, CI/CD, DevSecOps.\n\nWhy you\'ll love working here:\n- Thu nhập và chế độ hấp dẫn, cơ hội thăng tiến không giới hạn\n- Được làm việc trực tiếp cùng Chủ tịch Tập đoàn và các Cán bộ Lãnh đạo cao cấp của Ngân hàng, Định chế tài chính để phát triển tài năng và tỏa sáng\n- Được thử thách, phát triển trong môi trường lý tưởng: sức sống đổi mới, văn hóa hiệu quả, nhân văn, tôn vinh tính chính trực và sự tử tế\nCơ hội dẫn đần xu thế Kinh doanh - Công nghệ.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(455, 238, 2, 'CV Chất lượng Dữ liệu- Data Governance Specialist', 'Top 3 reasons to join us\n• Mức lương cạnh tranh, hấp dẫn\n• Môi trường làm việc chuyên nghiệp, thân thiện\n• Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n• Sử dụng các kỹ thuật (như SQL, Data Profiling, Python…) phân tích dữ liệu để phát hiện vấn đề chất lượng dữ liệu\n• Xây dựng báo cáo và chấm điểm chất lượng dữ liệu theo các tiêu chuẩn, quy định, hướng dẫn...đã được ban hành\n• Cập nhật các tiêu chuẩn dữ liệu, quy trình đánh giá chất lượng dữ liệu trên công cụ chất lượng dữ liệu\n• Giám sát và định kỳ báo cáo về tình hình chất lượng dữ liệu\n• Phối hợp với chủ sở hữu dữ liệu và các đơn vị liên quan để giải quyết các vấn đề chất lượng dữ liệu\n• Phối hợp xây dựng các quy trình, quy định, tiêu chuẩn liên quan đến chất lượng dữ liệu\n\nYour skills and experience\n• Tốt nghiệp Đại học chuyên ngành kinh tế/ tài chính/ ngân hàng/ khoa học máy tính/quản lý hệ thống thông tin\n• Tối thiểu 1 năm kinh nghiệm trong lĩnh vực ngân hàng - tài chính\n• Có kinh nghiệm tham gia và triển khai các dự án lớn liên quan đến dữ liệu\n• Kiến thức và kỹ năng thực tế về truy vấn cơ sở dữ liệu như Oracle, Postgress, Mongo..\n• Chứng chỉ: Ưu tiên có các chứng chỉ nghề quốc tế về Quản trị dữ liệu như Certified Data Management Professional (CDMP), BI Tableau, …\n• Ngoại ngữ: TOEIC 400 trở lên hoặc chứng chỉ tương đương\n\nWhy you\'ll love working here\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n• Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể… \n• Du lịch nghỉ dưỡng hàng năm\n• Khám sức khỏe định kì\n• Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n• Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương \n\nCơ hội nghề nghiệp và phát triển bản thân:\n• Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng \n• Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng \n• Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh. \n• Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...) \n\nMôi trường làm việc lý tưởng với:\n• Những người cộng sự thân thiện và tài năng \n• Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(456, 370, 2, 'DevOps Engineer', 'POSITION SUMMARY\nWe are seeking a skilled DevOps Engineer to focus on scripting client installations and software upgrades. The ideal candidate will have extensive experience working with automation tools, source control, and continuous deployment solutions such as GitHub, AWS ECR, AWS CodeArtifacts, and ArgoCD. Experience in DevSecOps practices and familiarity with tools like Sigrid for code quality and security analysis are highly desired. This role requires close collaboration with developers and other stakeholders, as well as availability for weekend and off-hours support as needed.\n\nPRIMARY RESPONSIBILITIES INCLUDE\n- Develop, test, and maintain automated scripts for client software installations and upgrades.\n- Collaborate closely with software developers to streamline and optimize deployment processes.\n- Manage and maintain continuous integration/continuous deployment (CI/CD) pipelines using GitHub, AWS ECS, AWS Artifactory, and ArgoCD.\n- Integrate DevSecOps practices into CI/CD workflows to ensure secure development and deployment.\n- Use tools like Sigrid to analyze code quality, security vulnerabilities, and maintainability.\n- Monitor system performance and application health using Datadog and proactively resolve deployment and environment issues.\n- Participate in troubleshooting and resolving production issues, ensuring minimal downtime and quick resolutions.\n- Document processes, scripts, and procedures clearly for internal knowledge sharing.\n- Provide weekend and after-hours support as required to ensure smooth deployments and upgrades.\n- Act as an individual contributor by taking ownership of tasks, managing priorities independently, and delivering high-quality, reliable automation solutions.\n- Continuously seek opportunities to improve system performance, deployment speed, and security.\n- Adhere to and promote best practices in code management, version control, testing, and infrastructure automation.\n\nREQUIRED QUALIFICATIONS\n- Bachelor’s degree in Computer Science, Information Technology, or related field, or equivalent work experience.\n- Proven experience as a DevOps Engineer, especially scripting installations and software upgrades.\n- Strong proficiency with GitHub, AWS ECR, AWS CodeArtifacts, and ArgoCD.\n- Strong proficiency in Helm.\n- Experience with DevSecOps principles and integrating security into DevOps practices.\n- Experience using Sigrid or similar tools for code analysis and security validation.\n- Demonstrated ability to script and automate using tools like Bash, Python, PowerShell, or similar.\n- Solid understanding of software development life cycle (SDLC), CI/CD principles, and Agile methodologies.\n- Excellent problem-solving skills with the ability to troubleshoot complex deployment and configuration issues.\n- Strong collaboration and communication skills, with experience partnering effectively with development team\n\nPreferred Skills:\n- Familiarity with Docker, Kubernetes, or other containerization technologies.\n- Experience with infrastructure as code tools such as Terraform or CloudFormation.\n- Knowledge of observability and logging practices using Datadog.\n\nWork Environment:\n- Willingness and flexibility to provide weekend and off-hour support when necessary.\n- Collaborative, dynamic team environment focused on continuous improvement and innovation.\n- Ability to work independently and manage time effectively in a fast-paced, evolving technical environment.\n\nWhy you\'ll love working here\nBeing a part of FORTNA, you are offered:\n- Flexible working hours (5 working days/week), no timekeeping \n- Competitive salary with annual review \n- 100% official salary during the probation period; 13th-month salary\n- Onsite opportunities in the US, UK (1-3 months/year)\n- Sponsored training and self-development opportunities (English, PMP, CSM...)\n- 10% paid working time per week for personal development (attending soft skill courses, reading books, working on side projects, self-teaching any new IT-related concepts)\n- Bao Viet Premium health-care insurance for employee and 2 dependents \n- Modern facilities with Laptop Dell Precision 7670 chip i9-12950HX, Ram 64GB, SSD 512GB, RTX A2000 + 2 monitor Dell Ultrasharp U2422HE\n- Annual luxury vacations, bi-monthly Happy Hour\n- Exciting company outings/events and team building activities, \n- Supportive, international, dynamic working environment and talented, culturally diverse teams\n- A large pantry full of snack, drink, and seasonal fresh fruit\n\nTake the deal and let\'s explore many more benefits!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nam Building, 22D Dương Đình Nghệ, Yên Hoà, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(457, 371, 2, 'Fullstack Developer (NestJS/ RxJS/ Angular)', 'Job description\n- Design, develop, and maintain scalable microservices using NestJS with RxJS \n- Apply Domain-Driven Design (DDD) principles to design robust and maintainable systems \n- Work with Kafka and MQTT in building message-driven architectures \n- Collaborate with the frontend team, with knowledge of Angular being a plus \n- Optimize performance and ensure scalability in system design and implementation \n- Lead technical discussions, advise for architecture decisions, and participate in code reviews \n- Work with databases such as PostgreSQL and Redis for efficient data storage and caching \n- Maintain high standards for code quality and documentation \n\nYour skills and experience\n- Bachelor’s degree in Software Engineering, Information Technology, or a related field \n- 5+ years of experience in backend or fullstack development \n- Proven experience with NestJS and RxJS in production environments \n- Experience or familiarity with Angular is an advantage \n- Strong background in microservices architecture and Domain-Driven Design (DDD) \n- Hands-on experience with Kafka and MQTT for message-driven architectures \n- Proficient in working with PostgreSQL and Redis \n- Solid understanding of clean architecture, software design patterns, and performance optimization \n- Experience mentoring team members is a plus \n- Basic proficiency in English, especially in reading and writing technical documentation \n- Strong problem-solving skills and a proactive mindset \n- Excellent communication and collaboration skills \n\nWhy you\'ll love working here\n- Attractive income package \n- 13th-month salary \n- Annual salary review and performance appraisal \n- Coverage of social insurance, health insurance, and unemployment insurance based on level \n- Company-sponsored annual health check-ups \n- Regular team-building events and company outings \n- Sponsored learning and development opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '47 Nui Thanh, Hoa Thuan Dong Ward, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(458, 289, 2, 'Chuyên viên Quản trị hệ thống CNTT (Linux, DevOps)', '- Quản trị, vận hành, giám sát các hệ thống máy chủ, thiết bị lưu trữ, ảo hóa, hệ điều hành, hệ thống lưu trữ dữ liệu, sao lưu/phục hồi dữ liệu nhằm đảm bảo hệ thống công nghệ thông tin của VRB luôn sẵn sàng đáp ứng hoạt động kinh doanh.\n- Tham gia xây dựng, triển khai các dự án, giải pháp hạ tầng công nghệ thông tin.\n- Nghiên cứu và đề xuất các giải pháp công nghệ mới tối ưu cho hệ thống công nghệ thông tin tại VRB.\n- Tham gia khắc phục các sự cố nhằm đảm bảo hệ thống công nghệ thông tin VRB hoạt động ổn định.\n- Phối hợp rà soát, xây dựng các chính sách, qui trình, qui định, tài liệu về quản trị, vận hành cơ sở hạ tầng CNTT.\n\nTrình độ đào tạo: \n- Tốt nghiệp Đại học trở lên các trường trong nước/ nước ngoài\n- Chuyên ngành: Công nghệ thông tin, Tin học ứng dụng, Khoa học máy tính, Kỹ thuật phần mềm, Điện tử viễn thông, Kỹ thuật thông tin\nYêu cầu kinh nghiệm: \n- Có kiến thức vững và kinh nghiệm thực tiễn trong:\n+ Quản trị hệ thống Active Directory, Email Exchange Server.\n+ Triển khai và quản trị hệ thống ảo hóa (ưu tiên VMWare ESXi/vCenter).\n+ Hệ điều hành Windows Server và Linux (CentOS, Ubuntu, RHEL...).\n- Hiểu biết về cấu hình và vận hành máy chủ HPE, IBM, hệ thống SAN Storage.\n- Ưu tiên ứng viên đã từng trực tiếp triển khai hoặc vận hành các hệ thống có tính sẵn sàng cao (HA), hệ thống CoreBanking, InternetBanking,.. và có các chứng chỉ quốc tế (MCSA, MCSE, VMWare, RHCSA/RHCE, CompTIA Server+/Storage+, hoặc tương đương…) là lợi thế tuyển dụng.\nNgoại ngữ: Có khả năng nói, viết bằng tiếng Anh. Chứng chỉ tiếng Anh yêu cầu: tối thiểu tương đương trình độ B1 trở lên theo khung tham chiếu trình độ ngoại ngữ chung Châu Âu.\nTuổi: Không quá 40 tuổi.\nYêu cầu khác:\n- Chịu được áp lực công việc, sẵn sàng làm ngoài giờ khi có sự cố cần xử lý.\n- Tinh thần trách nhiệm cao, bảo mật tuyệt đối, có khả năng làm việc độc lập và xử lý sự cố trong tình huống áp lực.\n- Nghiêm túc, cầu tiến, chịu khó, nhiệt tình trong công việc.\n\n\n- Ưu tiên ứng viên nộp hồ sơ bằng Tiếng Anh.\n\nHưởng lương hấp dẫn, phù hợp với năng lực và kinh nghiệm.\nLàm việc và phát triển trong môi trường trẻ trung, năng động và luôn giàu nhiệt huyết.\nCó cơ hội thăng tiến cao, được làm việc trong môi trường thân thiện, sáng tạo và phát triển.\nĐược tham gia các chương trình đào tạo nghiệp vụ của Ngân hàng.\nĐược chi bổ sung thu nhập theo kết quả làm việc, vị trí công việc và hưởng các cơchế khuyến khích theo quy định của VRB.\nDu lịch - Nghỉ dưỡng - Team building hằng năm.\nKhám sức khỏe định kỳ và chế độ bảo hiểm sức khỏe do VRB tài trợ.\nCác phúc lợi hiếu, hỷ, tiền mừng sinh nhật, thai sản, …', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '75 Trần Hưng Đạo, Hoàn Kiếm, Hà Nội, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(459, 229, 2, 'Home Trading System Developer (Frontend - JavaScript)', 'Top 3 reasons to join us\n1. Full SHUI as Vietnamese Law\n2. 15-day annual leave, Christmas leave\n3. Premium Private Medical Insurance PVI\n\nJob description\nSCOPE OF WORK\nHeadquarter: Daoukiwoom Group - Find more at: \nIndustry: Finance & Trading\n\n- Develop Home Trading System Desktop Application by using JavaScript under C++\n- Work directly with remote team to clarify tasks and requirements\n- Develop new features based on the user requirements. (analyzing requirements and system design)\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance (need to communicate with backend developers and testers)\n- Managing time and resources based on the WBS/Redmine\n- Compile a daily-report about the progress of tasks\n- Write high-quality, clean, elegant, maintainable, and testable code\n- Maintaining technical documents up-to-date\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the Kiwoom Framework for Kiwoom Indonesia, Finansia (in Thailand), and so on.\n\nYour skills and experience\nSkill Required\nEducation & Technical skills:\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Minimum 2-3 years of experience in JavaScript development.\n- Strong understanding of object-oriented programming and design patterns (MVC, MVVM).\n- Ability to write clean, maintainable, and well-documented code.\n- Familiarity with version control systems (e.g., SVN).\n- Experience with issue-tracking tools (e.g., Redmine).\n\nSoft Skills & Communication\n- Strong problem-solving and analytical skills.\n- Able to communicate in English, written and spoken.\n- Strong communication skills and teamwork, international experience is preferred.\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nNice to have:\n- Over 1 year of experience in developing securities solutions, including a PC-based trading platform – HTS (Home Trading System).\n- Experience on developing with MFC C++.\n- Experience on working with oversea team.\n\nWhy you\'ll love working here\nBENEFITS\nIncome & Achievement\n- Competitive salary, salary review once a year\n- 13th month salary and Annual Performance Bonus\n- MVP and Shining star awards at the end of year\n- Global and professional working environment\n\nWorkplace Happiness\n- Full SHUI as Vietnamese Law\n- Premium Private Medical Insurance PVI and annual health check\n- 15-day annual leave\n- 01 day Christmas leave and 90-min menstrual leave for women\n- Company event, YEP and monthly gathering time\n- Gifts on special occasion and fully stocked snack corner\n- Sponsored training courses and book purchase quarterly\n- Be well-equipped with new working equipment\n\nSPECIAL OFFER\n- Providing training and education experience in Korea with Korean Finance/IT expert\n- Providing opportunities to work and support in IT/Finance fields overseas\n\nHIRING PROCESS: The interview will be conducted at our office in Ho Chi Minh city.\nRound 1:\nStep 1: Live coding test\nStep 2: Interview with part team leader (upon passing coding test)\nStep 3: Interview with Director\nRound 2: Final interview with Head Office in Korea.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '14F, AP Tower, 518B Dien Bien Phu Street, Ward 21, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(460, 372, 2, 'Frontend Developer (JavaScript/ HTML/ CSS/ ReactJS)', 'As a Frontend Developer you will join an experienced team and be tasked to deliver to its full potential. Your KPI’s will include project delivery – JavaScript, HTML, CSS, Razor View, C# development & delivery for CMS projects, client satisfaction with your development productivity and quality. Researching new technology, investigating it and being involved in prototype creation. Working towards your company funded CMS Accreditation.\n\nAs a Frontend Developer, you will:\nDevelop web applications and components using CMS\nParticipating in all phases of the development life cycle\nWrite well-structured, efficient, clean and testable code base\nKeeps project manager well informed of status of development effort.\nResolve and/or escalate issues in a timely fashion.\nMust have:\n2+ years’ experience working in Software Development\nSolid experience and understanding of the entire web development process with web technology including CMS templates for pages and components and integration with frontend.\nHands-on experience with markup languages\nProficient in JavaScript (Vanilla and any libraries/frameworks such as React or Vue), CSS & preprocessors, tools such as Webpack or Vite.\nFamiliarity with design tools such as Figma and Adobe XD\nExperience in OOP, design patterns, software development best practices (Agile preferred) and versions control platforms\nKnowledge of SEO principles\nGood at problem-solving and analytical skills.\nBasic English communication skills (both verbal & written), especially in the global software development environment.\nNice to have:\nExperience in CMS development is a plus such as Sitefinity, Sitecore, Umbraco, AEM.\nCertified in any CMS is a BIG PLUS.\n\nWhy you\'ll love working here:\nNice and friendly working environment. Great location with shops and cafes in the building.\nLots of interesting and challenging projects to work on.\nInternational environment\nSupport Laptop or MacBook\nCompany paid certifications\nCompetitive salary (based on qualifications and experience)\nExtended health care includes family\nFull salary social insurance contribution.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 3, Saigon Coworking, 204C Nguyen Van Huong Street, Ward Thao Dien, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(461, 373, 2, 'AI Engineer (Python/ Machine Learning/ Computer Vision)', 'ABOUT US: The newly established company, is named Company Central Pte. Ltd., a strategic subsidiary of Est rouge inc.. Company Central was established on 20 December 2023 with a vision to modernize the business through cutting-edge technology, and now situated in a prime location in Singapore.\n\nCompany Central provides HR Tech solutions with SaaS model. Starting from Applicant Tracking System (ATS), offering unique services that cater to the evolving market demands.\n\nWe aim to expand our business to entire Southeast Asian market. We start from Vietnam. We serves diverse customers who recruit people frequently and help streamline their recruitment process.\n\nYour skills and experience\n\nHas 3 years of experience in a similar position.\nBachelor’s degree in Computer Science, Information Technology, Computer Engineering, Mathematics.\nHave good problem-solving skills\nBe proficient in at least one programming language, preferably Python.\nExperience in one or more areas of AI, such as: Machine Learning, Computer Vision, Image Processing, Natural Language Processing.\nGood understanding of the latest research and technologies in Artificial Intelligence;\nHands-on experience with one or more deep learning frameworks (TensorFlow, Caffe, Theano, PyTorch)\nExperienced with the latest GPT series models and proficient in Prompt Engineering.\nGood English reading and writing skills.\n\nWhy you\'ll love working here\n\nFlatt-ER organization: Unlike traditional Flat Organization, Flatt-ER Organization still maintains the layers of one company’s structure while minimizing the redundancy. The Flatter Organizational Model is expected to create more multi-way communication lines in one and many layers, which allows one employee in a company to easily connect with anyone he wants without any barriers.\nWorking methodology: Agile development is applied by focusing on Humans to build the communication network based on support and trust in a project team/group, leading to success.\nOpen and friendly workspace: All you need to relax is provided right in the office.\nExtra self-improvement benefits: extra health care insurance ‘ER CARE’ designed only for members of Est Rouge; flexible working hours; English classes; Yoga classes; Technical classes (Scrum Master, Product Owner); Mindfulness workshop.\nVarious attractive activities: Open Talk; Team building; Company trip; New Year Party.\nWorking equipment: Macbook & Apple devices.\nPerformance review twice a year.\n12 days’ annual leave.\nPerformance bonus at the end of the year.\nWorking time: Monday - Friday (8:00 ~ 9:00 -> 11:30; 13:00 -> 17:30).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lô 31-32 Nguyễn Hữu An, phường Nại Hiên Đông, Son Tra, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(462, 374, 2, 'Senior SRE', 'BeGroup strives to build reliable and easy to use systems. We believe in measuring all aspects of our applications and infrastructure. Our focus on automation and process improvement enables us to accomplish innovative, scalable and reliable systems.\n\nWe value constant self-improvement, honest feedback, clear communication and empathy for the users of our services.\n\nWe are looking for a Site Reliability Engineer who is excited about applying SRE principles to system infrastructure.\n\nResponsibilities:\n- Build and maintain an observability framework to provide metrics and availability\n- Implement and manage resource utilization, billing and make suggestions for optimization.\n- Analyze performance bottleneck based on monitoring data implement and manage security and compliance policies.\n- Build scalable and reliable distributed systems\n- Work with the development team to continuously improve the availability, stability, reliability, latency and scalability of the system\n\nYour skills and experience\nRequirements:\n- 3+ years of hands-on experience in a relevant SRE role.\n- Strong expertise in one or more cloud providers (AWS, GCP, Azure) and their managed services.\n- In-depth understanding of MySQL/PostgreSQL architecture and high availability solutions.\n- Proficiency in at least one scripting language such as Python, Go or Bash.\n- Strong knowledge of Linux systems, networking, and performance tuning.\n- Intermediate experience with infrastructure-as-code tools (e.g., Terraform, Packer, Ansible).\n- Strong background in containerization technologies (Docker, Kubernetes) and service mesh frameworks (Istio, Linkerd).\n- Hands-on expertise with microservices observability, log analysis, and monitoring tools (e.g., ELK Stack, Prometheus, Grafana, Clickhouse).\n- Respond to and deal with database failures in a timely manner, and continue to track and optimize for performance.\n- A strong automation mindset with a passion for streamlining processes.\n\nValues:\n- We believe our values make a difference\n- We value, support, and help each other grow\n- We are committed to active inclusion and diversity\n- We are transparent and believe the best idea wins\n- We succeed when our customers succeed\n- And we keep it fun!\n\nWe believe that ideas are more important than titles, everything is more fun together, everyone drives change, and everyone is an owner. While we believe the perks and benefits that we offer are terrific, nothing excites us more than having the ability to collaborate with intelligent, highly motivated and talented people on challenging problems as we work to change the face of ride-sharing platforms.\n\nWhy you\'ll love working here\nBenefits\n- 13th salary\n- Social Insurance\n- Medical healthcare\n- Annual health check\n- 15 days annual leave\n- Transportation fee (BE\'s services)\n- Performance bonus\n- Holiday bonus\n- Team Building and many engagement activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FIVESTAR BUILDING, 28bis Mac Dinh Chi, Dakao, Distric1, HCM City, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(463, 243, 2, 'Middle/Senior C# Developer (WPF, English) - Up to 3200$', 'Rakuten FinTech Vietnam Co., Ltd. is the company, which was established in 2021, and the subsidiary of Rakuten Card, which is one of the biggest credit card company in Japan. Our mission is to develop internal system and mission-critical system for Rakuten Card and FinTech group companies to contribute to FinTech business growth, also to provide attractive environment for talented engineers in both Vietnam and Japan.\n\nThis position will have responsibility to develop Desktop Application, Web API and more for our Fintech services such as “Rakuten Card”, “Rakuten Pay”, Rakuten Bank” etc.\n\nResponsibilities\n- Perform requirement analysis, design and technical documentation\n- Design, build, and maintain efficient, reusable, and reliable C# code\n- Work to improve and enhance quality in automated testing, etc\n- Work with leader and teammates to estimate and plan for projects.\n\nYour skills and experience\nMust have:\n- At least 5+ years working in C# software development\n- Good experience with GUI development for Windows applications.\n- Good experience with Windows Presentation Foundation\n- Good at English communication\n- Good experience with unit testing\n- Good knowledge with source control and defect tracking tool\n- Must be independent, responsible, and self-motivated with the ability to learn and achieve superior results\n- Strong communication skills with proven ability to present complex ideas and document in a clear and concise way.\n\nNice to have:\n- Experience in automation test\n- Experience in Java web development\n- Experience with building large, enterprise projects\n\nWhy you\'ll love working here\n- Commuting Allowances \n- Meal Allowances \n- Performance Bonus \n- Tet Bonus (Annual Bonus) \n- Salary review \n- Health checkup \n- Premium Health care \n- Company Trip \n- Annual Leave \n*Benefits might be updated to add on, please let us know if you want to know more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24th-25th Floor, A&B Tower, 76A Le Lai Street, Ben Thanh Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(464, 375, 2, '3D Rigging Artist (Animation, Unreal Engine, Python)', 'Vlast Việt Nam là công ty tiên phong trong việc sản xuất animation và nhân vật mang tính sáng tạo. Chúng tôi truyền tải cảm xúc đến mọi người thông qua những câu chuyện độc đáo và đồ họa nổi bật, và đang tạo ra những nội dung được yêu thích trên toàn thế giới. Chúng tôi đang tìm một ứng viên sử dụng thành thạo Maya, có hiểu biết sâu về quy trình và kỹ thuật trong hoạt hình.\n\nMô tả công việc\n- Character Rigging\n- Hiểu và thiết kế khung xương dựa trên model thực tế\n- Hiểu và thiết kế khung xương tạo chuyển động hoạt hình.\n- Character Skinning\n- Thực hiện skinning cho model khớp với khung xương đã thiết kế.\n- Thực hiện skinning facial rigging\n- Rigging trang phục (bao gồm rigging mô phỏng chuyển động)\n- Thiết kế, tối ưu hóa và duy trì hệ thống rigging hoạt động ổn định trên Maya và UE.\n\nYour skills and experience\n- Tối thiểu 2 năm kinh nghiệm trong lĩnh vực Rigging/Technical Artist\n- Hiểu quy trình và kỹ thuật Animation\n- Có kinh nghiệm sử dụng phần mềm Maya (Ưu tiên ứng viên có thể làm 3dsMax)\n- Có kinh nghiệm sử dụng Python\n- Ưu tiên người có kinh nghiệm làm Unreal Engine\n- Có tính cầu tiến, trách nhiệm cao và làm việc nhóm tốt\n- Có kinh nghiệm làm Animation\n- Ứng viên sáng tạo và mong muốn tìm hiểu các kỹ thuật mới.\n- Giao tiếp tiếng Anh cơ bản (bắt buộc)\n\nLưu ý: Yêu cầu bắt buộc nộp Portfolio: video hoạt động bộ rig và bộ rig mẫu (Các hồ sơ thiếu Portfolio sẽ tự động bị loại)\n\nWhy you\'ll love working here\n- Mức lương cạnh tranh, lương tháng 13, thưởng theo hiệu quả công việc. Tổng lương lên đến 14-17 tháng lương/năm.\n- Chế độ nghỉ phép hấp dẫn: phép năm, nghỉ phép du lịch cá nhân, nghỉ hiếu hỉ từ 15-22 ngày/năm\n- Bảo hiểm xã hội theo quy định nhà nước + Bảo hiểm chăm sóc sức khỏe PTI.\n- Công ty hỗ trợ tiền cơm trưa, phí gửi xe.\n- Hỗ trợ đồ ăn nhẹ, thức uống, cafe trong suốt quá trình làm việc.\n- Thời gian làm việc: 8h30 - 17h30 (Thứ 2 - Thứ 6), nghỉ trưa 12h - 13h.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '268 Trần Hưng Đạo, Phường 11, Quận 5, Hồ Chí Minh (Tòa nhà Ngân Hàng ACB), District 5, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(465, 376, 2, 'Automation Tester (QA QC, Tester, English)', 'Top 3 reasons to join us\n1. International professional working environment \n2. Opportunities to travel to Europe for training\n3. Clear career path and established process\n\nJob description\n- Analyze and understand business and technical requirements and work with clients across different domains and industries\n- Design and implement the test strategy, workflow/framework used for automated testing in the project in relation to the software development and CI/CD\n- Collaborate in project teams to test developed applications in a structured and successful way\n- Develop and document test cases and test plans based on functional and technical requirements along with writing guidelines for test automation processes\n- Create, execute and maintain automated scripts\n- Manage and report on test deliverables and test execution\n- Take responsibility for certifying the quality of the solution\n- Create and execute manual test scripts as needed\n- Work and collaborate in an agile international environment with experienced and skilled colleagues in Vietnam and Europe\n- Plan and organize your own work and accurately report issues and progress in a timely manner\n- Identify areas for own personal development\n\nYour skills and experience\n- Bachelor’s or Master’s degree within a relevant IT specialization\n- Good English skills both in writing and verbally\n- At least 0.5-3 years of experience from a similar position\n- Strong understanding of software development, testing methodologies and developing test automation frameworks\n- Hands on experience in building test automation frameworks – preferably using technologies such as .Net, Selenium, Katalon, Cucumber, Jenkins and batch testing\n- Experience in using tools for test management, tracking defects, capturing test evidence and analyzing data\n- Open towards, and able to quickly learn, new technologies\n- Effectively estimate work and produce deliverables on time\n\nWhy you\'ll love working here\n- Clear Academy system and mentoring program to help you develop your career within Netcompany\n- Opportunities to go to Europe for training\n- Performance appraisal twice a year\n- Professional Scandinavian working environment that values innovation, creativity and new ideas along with being supportive, fun and flexible\n- 24/7 Mental Wellbeing Companion Program to help you overcome challenges and crisis in your life and work\n- Advanced technical solutions, agile culture and the opportunity to work with the latest technologies\n- Attractive salary that is adjusted annually based on your performance along with an annual performance bonus\n- Attractive Healthcare insurance program for you and your family\n- Various training on trending technologies, best practices and soft skills\n- Management and leadership are accessible and encourage input from employees\n- Working with a variety of clients and colleagues all over the world\n- Social and sports activities hosted by Netcompany After Dark (Summer Party, Friday bar, go-kart, BBQ, escape room, football, badminton, table tennis etc)\n\nIn Netcompany we believe that a diverse and inclusive workplace is central to our success, which is why all qualified candidates are invited to apply regardless of gender, sexual orientation, disability, age, religion and belief, ethnic background, nationality, gender identity or culture. We are committed to live out a culture where we provide equal opportunities for all.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floors 24-25-26-27-29-31, Opal Tower. 92 Nguyen Huu Canh Street, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(466, 377, 2, 'Frontend Developer (React Js)', 'Job description\n- Develop responsive, high-performance web applications using React.js.\n- Collaborate with UI/UX designers to implement modern, intuitive user interfaces.\n- Optimize applications for speed, scalability, and cross-browser compatibility.\n- Integrate frontend components with backend services and APIs.\n- Keep up with the latest frontend technologies and industry trends.\n\nYour skills and experience\n- Minimum of 3 years of experience in frontend development using React.js.\n- Proficient in JavaScript (ES6+), HTML5, CSS3, and React.js libraries.\n- Strong understanding of frontend architecture and UI/UX design principles.\n- Experience with state management tools like Redux or Context API.\n- Strong problem-solving skills and high attention to detail.\n- Experience with React Native is a plus.\n\nWhy you\'ll love working here\n- Review 1 ~ 2 times per year\n- Opportunities for professional development and growth\n- Collaborative and innovative work environment\n- Working equipment provided by the company\n- Join birthday party, holiday party organized by the company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Apartment B1, D’ Verano Residential, Thu Thiem new urban area, An Khanh Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(467, 378, 2, 'Game Tester (Manual Tester, QA QC)', 'Top 3 reasons to join us\n- MacBook Pro/Extra screens &amp; Remote Work policy\n- Premium health insurance package for you, relative\n- Company Trip 4-5*, Yoga, Gym/Fitness/English club\n\nJob description\n- Write, execute and maintain test cases.\n- Estimate and perform testing following test plans. Align and report testing status with development on a daily basis.\n- Analyze the results of testing, submit defect reports, and lead the triage of defect reports to ensure that they are properly prioritized and assigned.\n- Implement and maintain the testing process to ensure both the development team and QA team stays on the same page and issues are solved efficiently.\n- Follow up on requests from the development team.\n- Ensure effective internal and external communication. Proactively implement initiatives to enhance test processes and foster collaboration between internal and external QA teams.\n\nYour skills and experience\nSKILLS\n- 2 years of experience in QA/QC/testing roles (games, mobile apps, or web applications).\n- Reporting and synthesis\n- Identifying test case scenarios\n- Writing test cases and checklists\n- Problem-solving &amp; troubleshooting\n- Bug reporting and isolation\n- Communication &amp; teamwork\n- Strong English Reading &amp; Communication\n\nKNOWLEDGE\n- Experience playing games at all skill levels.\n- Software, Hardware, and Mobile Platform Testing Knowledge\n- Essential Game Features: iOS &amp; Android\n- Game development and QA Processes\n- Agile/Scrum Methodology\n- Test tools\n\nABILITIES\n- Working with Work Management Tools: Jira, Zephyr Scale, Firebase\n- Analyzing &amp; Creating Test Cases\n- Analyzing Game Documents\n- Prioritization, Time Management\n- Passion for Games\n- Growth Mindset\n- Quick Learner\n- Work Ethic\n\nWhy you\'ll love working here\n- Great facility to work. You will have a MacBook and extra high-definition screens\n- Premium health insurance package and annual medical check-up\n- Sponsorship for training courses\n- Interesting activities: gym/fitness club at work, English club, corporate social responsibility events...\n- Attractive signing bonus for important positions\n- With regular discussions with the CEO, founders, and executives of the company, you will have a lot of opportunities to learn from experts in their fields\n- Annual bonus and project bonus\n- International opportunity to expose and grow\n- At least one abroad travels every year. We often send our elites to international conferences like GDC, WWDC, Google I/O... to update the latest technology\n- Full labor insurance (social, health, unemployed)\n- Annual leave 12 days / sick leave 2 days / remote work 12 days\n- Free food &amp; drinks, kitchen at work, PlayStation after work\n- Friday evening party, happy hour, team activities, and awesome parties…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '40A Lam Sơn, Phường 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(468, 225, 2, 'Middle/Senior Java Engineer', 'By applying for the above position, you accept and agree that your personal data and any information stated in the attached curriculum vitae (CV) will be used and processed by ITViec and NAB Vietnam for recruitment purposes. The storage and processing of such information will comply with the applicable laws of Vietnam, and the policies and procedures of ITViec and NAB Vietnam regarding personal data, as amended from time to time.  ABOUT THE JOB  We are seeking motivated Java Engineers (all levels) who are passionate, results focused to take accountability for the delivery of Microservices that will be used by banking front end applications. You will be part of our delivery team and will be responsible for providing technical leadership throughout all phases of the software delivery life cycle as we initiate a transformation of NAB technology.  At NAB, we believe success comes from our people. We\'re committed to supporting your talent and skills through your career, as you help us build a culture that affects change for our customers and for the community too.  YOUR JOB RESPONSIBILITIES  Design, develop, review, implement, and manage Java applications and services for the production and pre-release environments;  Design, develop, review, implement, and manage continuous integration, build management and deployment scripts, systems, and any code as required;  Participate in Agile software development, prototyping, and code review with international development teams to build scalable microservices-based products and APIs using Java technologies on AWS Cloud architecture;  Fully understand the requirements of the customer or business and utilize this knowledge to develop applications that are consistent with this;  Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and tooling;  Provide robust coding practices, solid unit/component test coverage, and debugging code.  Mentor, provide technical direction and engineering leadership for a team of engineers (for Lead)  Provide leadership to team members (for Lead)  Your skills and experience  Must have  For Middle level: 3+ years of experience as a software engineer in a complex development environment.  For Senior level: 5+ years of experience as a software engineer in a complex development environment.  Solid experience in Java 8+ and Springboot.  Experience in designing & developing RESTful APIs and complex microservices based system; troubleshooting and debugging in microservice  Experience in Cloud computing and AWS or Azure  Experience with unit testing and integration testing  Practical experience in Containers (ECS, Kubernetes, Docker) and FaaS (AWS Lambda) technologies  Good English communication skills (both verbal & written), especially in the global software development environment.  Experience in Agile development environments;  Well-versed in writing structured, well-documented, maintainable, and clean code;  Good problem-solving and analytical skills  Nice-to-have  Practical experience in Containers (ECS, Kubernetes, Docker) and FaaS (AWS Lambda) technologies.  Experience in modern CI/CD pipelines and tools (e.g. Git, Ansible, Jenkins, NPM, Gradle).  Experience in the Banking or Financial Services industry.  Why you\'ll love working here  Generous compensation and benefit package  Attractive salary and benefits   20-day annual leave and 7-day sick leave, etc.   13th month salary and Annual Performance Bonus   Premium healthcare for yourself and family members   Exciting career and development opportunities   Large scale products with modern technologies in banking domain   Clear roadmap for career advancement in both technical and leadership pathways   Sponsored certificates in both IT and banking/finance   Premium accounts on Udemy/A Cloud Guru/Coursera/LinkedIn, etc.   English learning with native teachers   Professional and engaging working environment  Hybrid working model and excellent work-life balance    Well-equipped & modern Agile office with fully-stocked pantry    Annual company trip and events  A DIVERSE AND INCLUSIVE WORKPLACE WORKS BETTER FOR EVERYONE  NAB is a place where colleagues of all genders, sexualities and ages, carers and colleagues with disability, and colleagues from all cultures, races and religions have the opportunity to thrive, connect and grow.  If this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh / ROX Tower, 54A Nguyen Chi Thanh, Lang Thuong, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(469, 258, 2, 'VTS - Kỹ Sư Phát Triển ứng dụng Web (Java/ C#)', 'Gia nhập “vũ trụ” công nghệ Viettel, nơi bạn không chỉ được “đắm chìm” trong hàng loạt công nghệ xịn xò như Big Data, AI, IoT, AR/VR, Cloud, Blockchain… mà còn được trao cơ hội thực hiện sứ mệnh quan trọng: “Chung tay cùng Chính phủ kiến tạo – Chính phủ số”, đồng hành với doanh nghiệp và người dân giải quyết các vấn đề cấp bách của xã hội, hướng tới một cuộc sống tốt đẹp hơn cho mọi người.\n\nTại VTS (Tổng Công ty Giải pháp Doanh nghiệp Viettel), bạn sẽ được hiện thực hóa những ý tưởng táo bạo, tham gia vào các dự án công nghệ hàng đầu và phát triển giải pháp đột phá cho tương lai số. Đây chính là nơi khơi dậy đam mê, thúc đẩy sáng tạo và chắp cánh cho mọi ước mơ công nghệ của bạn. Sẵn sàng trở thành “ngôi sao sáng” trên hành trình chuyển đổi số và cùng Viettel tạo nên dấu ấn trong cuộc cách mạng công nghiệp 4.0? Let’s go!\n\n“Bậc Thầy Tối Ưu” – Kỹ Sư Phát Triển ứng dụng Web\n\nBạn sẽ làm gì?\n\n- Thiết kế kiến trúc hệ thống web (bao gồm cả database, API, microservices…) để đảm bảo tính mở rộng, bền vững và an toàn thông tin.\n- Tham gia code từ front-end “hút mắt” (HTML/CSS/JS/React/Angular…) đến back-end “vững chãi” (Java/.NET/PHP…), tích hợp CI/CD, container (Docker, Kubernetes) nếu cần.\n- Thường xuyên tối ưu code, rà soát hiệu năng hệ thống, “phản ứng nhanh” khi phát sinh lỗi để mang lại trải nghiệm mượt mà cho người dùng.\n- Phối hợp cùng team để không ngừng cải tiến giải pháp, áp dụng công nghệ mới, nâng cao bảo mật và khả năng chịu tải của sản phẩm.\n- Thực hiện và duy trì unit test, đảm bảo chất lượng code, sẵn sàng học hỏi và chia sẻ kiến thức với đồng đội.\n\nYour skills and experience\n\n- Bằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng hoặc tương đương.\n- Ngoại ngữ: Đọc hiểu tài liệu tiếng Anh ngon lành. Ưu tiên có chứng chỉ TOEIC 550+ (hoặc IELTS, TOEFL tương đương).\n- Nền tảng lập trình:\n  - Thành thạo ít nhất một ngôn ngữ lập trình (Java, C#, JavaScript…) phù hợp với Web\n  - Nắm rõ OOP, biết cách thiết kế class, hiểu sâu về các nguyên lý lập trình hướng đối tượng.\n- Kiến thức công nghệ:\n  - Xử lý dữ liệu có cấu trúc (string, record, object, collection…)\n  - Xử lý đa ngôn ngữ (localization)\n  - Thành thạo I/O cơ bản\n  - Thao tác với CSDL (query, commit, rollback…)\n  - Lập trình đa luồng (multithreading), quản lý concurrency, connection pooling\n  - Biết cách phân tích log để xử lý lỗi “thần tốc”\n\nTinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội.\n\nWhy you\'ll love working here\n\n- Lương cạnh tranh: Thu nhập “ổn áp”, xứng đáng với năng lực và kinh nghiệm.\n- Đầy đủ các khoản thưởng: Thưởng lễ Tết, quà tặng, du lịch nghỉ mát, hỗ trợ ăn trưa, cước điện thoại…\n- Nghỉ phép linh hoạt: 12 ngày phép + 3 ngày nghỉ mát + 1 ngày sáng tạo mỗi năm.\n- Bảo hiểm toàn diện: Hưởng đầy đủ BHXH, BHYT, BHTN theo quy định, cộng thêm gói bảo hiểm riêng từ Viettel.\n- Môi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo “bung nóc”.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Tran Huu Duc, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(470, 227, 2, 'Senior Quality Engineer', 'Top 3 reasons to join us\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description\nTesting and Quality Assurance:\n- Design, develop, and execute test plans and test cases to ensure comprehensive coverage of product requirements.\n- Perform functional, integration, regression, and system testing for both frontend and backend systems.\n- Create and maintain detailed reports on testing progress, defects, and outcomes.\n- Review and refine test strategies to optimize quality and efficiency.\n- Ensure cross-browser, cross-platform, and device compatibility for applications.\n\nAutomation Testing:\n- Develop, implement, and maintain automated test scripts using tools like Cucumber, Serenity BDD, and Playwright.\n- Conduct API testing using tools such as Postman and performance testing with JMeter.\n- Collaborate with the DevOps team to integrate automated tests into CI/CD pipelines using Jenkins and Git.\n- Leverage programming skills in Java or JavaScript to enhance testing frameworks.\n\nCollaboration and Delivery:\n- Collaborate with BAs, developers, and product managers to understand requirements, provide input, and ensure alignment.\n- Act as a quality advocate, focusing on delivering features that meet user needs and maintain high standards.\n- Evaluate product readiness and release timelines based on test results and team discussions.\n\nLeadership and Influence:\n- Share quality-focused practices and promote a quality-first mindset within the team.\n- Mentor team members on testing techniques and workflows to enhance overall quality.\n- Ensure workflows and processes are followed consistently and improve them when necessary.\n\nContinuous Monitoring and Improvement:\n- Monitor product performance and user feedback in production environments to identify improvement areas.\n- Stay updated with industry trends, tools, and best practices to continually improve testing processes.\n- Drive initiatives to improve product quality, user satisfaction, and team productivity.\n\nYour skills and experience\nEducation: Bachelor\'s Degree in Information Technology, Computer Science, or a related field\nExperience: Minimum of 4 years of experience as a Software Tester or QC Engineer, with significant exposure to both manual and automated testing.\nTechnical Skills:\n- Proficient in coding with the ability to learn and apply automation testing tools.\n- Deep understanding of APIs/Web-services and familiarity with testing tools such as Postman, BrowserStack, and curl.\n- Knowledge of Agile/Scrum methodologies and practices like TDD/BDD.\n\nTools and Documentation:\n- Proficient with Atlassian tools (Jira, Confluence) and mock-up tools (e.g., Figma, draw.io,..).\n- Ability to write Software Development Requirement Documents and Functional Specifications.\n- Experience with test automation frameworks (e.g., Playwright, Cucumber, cypress.io,..) is a plus.\n\nSoft Skills:\n- Excellent Problem-Solving skills and Critical Thinking.\n- Outstanding Communication and Documentation skills.\n- Ability to work collaboratively in a fast-paced, Agile environment.\n- Proactive and self-motivated with a strong sense of ownership.\n\nPreferred (but not required)\n- ISTQB certification or equivalent.\n- Experience in the eCommerce industry.\n- Familiarity with CI/CD pipelines.\n- Proficiency in English.\n\nWhy you\'ll love working here\nExceptional Total Compensation Package\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Full salary during probation & Guaranteed 13th month salary\n- 12 days work-from-home & 12 days of paid annual leave, plus seniority paid leave\n- Global health insurance package for yourself and direct family members, plus annual health checkup\n\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\n\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(471, 258, 2, 'Big Data Engineer (Java, Scala, SQL)', 'Top 3 reasons to join us\n- Dẫn đầu thị trường\n- Cơ hội thử thách và phát triển bản thân\n- Môi trường làm việc năng động\n\nJob description\nĐã nói đến Big Data thì Data phải BIG, nếu muốn bơi, ngụp, lặn trong data với các công nghệ mới nhất về Big Data như Hadoop, Spark, Kafka, Storm, Nifi, HBase, … thì Khối Công nghệ thông tin - VTT là một trong những lựa chọn tốt nhất. Hơn 200 nguồn dữ liệu khác nhau, với lượng dữ liệu được xử lý ~2TB dữ liệu/ ngày, và dữ liệu lưu trữ khoảng ~10PB, Viettel đang thực sự sở hữu  một trong những môi trường tốt nhất cho các Big Data Engineer.\nNgoài ra, khi trở thành Big Data Engineer trong Khối CNTT, các bạn còn có cơ hội học hỏi kinh nghiệm và được dẫn dắt bới các Big Data Architect, Senior Big Data Engineer hơn 10 năm kinh nghiệm trong nghề và đã được công nhận world class trong lĩnh vực của họ.\nMô tả công việc:\n- Xây dựng, phát triển các hệ thống lưu trữ, xử lý dữ liệu lớn (Big Data)\n- Xây dựng các giải pháp ETL có khả năng mở rộng linh hoạt với độ tin cậy cao, phục vụ cho việc khai thác/ ingest các loại dữ liệu (cấu trúc, lưu lượng, tốc độ) từ nhiều nguồn khác nhau\n- Xây dựng, phát triển các công cụ khai thác dữ liệu, quản trị dữ liệu\n- Thiết kế chi tiết giải pháp cho các luồng thu thập, chuẩn hóa, làm sạch, làm giàu, lưu trữ, xử lý, phân tích và hiển thị dữ liệu lớn\n- Thiết kế chi tiết giải pháp cho các luồng thu thập, chuẩn hóa, làm sạch, làm giàu, lưu trữ, xử lý,phân tích và hiển thị dữ liệu lớn\n- Phối hợp, hỗ trợ Data Scientist trong việc chuyển đổi các mô hình, thuật toán học máy, khai phá dữ liệu thành các bản đặc tả, thiết kế phần mềm đảm bảo chúng có thể được cài đặt, triển khai hiệu quả trên môi trường tính toán phân tán và có khả năng mở rộng tốt khi tập dữ liệu đầu vào tăng trưởng nhanh\n- Thiết kế giải pháp và trực tiếp phát triển các module, thư viện có tính chất nền tảng, có khả năng tái sử dụng cao, ảnh hưởng diện rộng.\n\nYour skills and experience\n- Trình độ tiếng anh: TOEIC tối thiểu 550\n- Kiến thức về lập trình, cấu trúc dữ liệu & giải thuật\n- Kiến thức về lập trình lưu trữ, xử lý dữ liệu phân tán, xử lý dữ liệu lớn (Hadoop, Spark, Elastic Search…\n- Kiến thức về xây dựng luồng xử lý dữ liệu (batch processing, stream procesing, ...)\n- Kiển thức về các loại CSDL (RDBMS, Graph Databases, NoSQL Products, ...)\n- Kỹ năng sử dụng ngôn ngữ lập trình (Java, Scala, ...), SQL\n- Kỹ năng thành thạo một trong các framework, thư viện lưu trữ, xử lý dữ liệu lớn (Hadoop,Spark, Kafka, Zookeeper, ...)\n- Kỹ năng sử dụng một trong các loại CSDL (Oracle, Neo4j, HBase, Cassandra, MongoDB, ..)\n\nWhy you\'ll love working here\n- Đãi ngộ\n# Dẫn đầu thị trường\n- Cơ hội được làm việc tại Tập đoàn tiên phong mở đường , kiến tạo tương lai thông minh, gắn kết của Việt Nam.\n- Cơ hội được thử sức trong những lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n# Môi trường năng động sáng tạo\n- Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo theo cách riêng.\n- Được khơi gợi cảm hứng làm việc với văn phòng xanh, không gian mở, hiện đại tiêu chuẩn quốc tế.\n# Cơ hội thử thách và phát triển\n- Áp dụng kiến thức, kĩ năng, kinh nghiệm chuyên môn giải quyết các bài toán hấp dẫn, thử thách tại Viettel.\n- Cơ hội thử sức ở nhiều lĩnh vực, sản phẩm và quốc gia khác nhau góp phần thay đổi xã hội .\n- Viettel cam kết cho bạn nền tảng vững chắc để học hỏi và phát triển.\n- Sẵn sàng trao quyền, cơ hội đột phá cho những người trẻ tuổi.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội được đào tạo, trao dồi kĩ năng định kì và nhu cầu thực tế.\n\n# Chế ngộ đãi ngộ hấp dẫn, cạnh tranh\n- Lương thưởng cạnh tranh trên thị trường, phản ánh đúng năng lực thực tế.\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày .\n- Thưởng thức bữa trưa thơm ngon tại Tập đoàn, được chọn lọc bởi các chuyên gia dinh dưỡng.\n- Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building thú vị.\n- Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.\n\n- Khác\nViettel tuyệt đối không thu bất cứ khoản tiền nào của ứng viên khi nộp hồ sơ tham gia dự tuyển và khi vào làm việc tại Viettel nếu trúng tuyển.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Keangnam Landmark Tower 72, Pham Hung, Nam Tu Liem, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(472, 238, 2, 'AI Engineer (Python,C++)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Phát triển, ứng dụng, tối ưu, tích hợp mô hình AI cho các bài toán ứng dụng trong hoạt động Kinh doanh/Ngân hàng về các lĩnh vực Computer Vision, NLP...\n- Tham gia vào các công đoạn triển khai dịch vụ: Kiến trúc hệ thống, thiết kế mô hình hoạt động, luồng hoạt động, chức năng, tối ưu performance\n- Coding, test metrics, service và unittest theo mô hình DevOps, MLOps\n- Nghiên cứu, tìm hiểu các bài báo khoa học mới nhất về AI, ML, DL\n- Với nhóm ứng viên là các bạn chuẩn bị tốt nghiệp tài năng và fresher: tham gia các chương trình đào tạo và dự án dành cho người mới để phát triển lên các vị trí chính thức.\n\nYour skills and experience\n- Tốt nghiệp Đại học các chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin....\n- Ưu tiên ứng viên có từ 1,5 năm kinh nghiệm tương đương\n- Có kiến thức và kỹ năng về MỘT TRONG NHỮNG nội dung sau:\n  - Ngôn ngữ lập trình Python, C/C++\n  - Service/MicroService với một trong các framework FastAPI/Flask/Django\n  - Tensorflow/Pytorch/DGL/PyG/Onnx\n  - API (Restful/gRPC), Lập trình an toàn, đảm bảo & tối ưu hiệu năng\n  - Git và Git Flow, Docker/ Kubernete, Kubeflow/MLFlow, TritonServer/ Tensorflow Serving\n  - Các dạng bài toán Supervised learning, Reinforcement learning\n  - Xử lý Ảnh (Computer Vision)/Video/Âm thanh/Ngôn ngữ tự nhiên (NLP)\n  - CNN/RNN/Transformer/Attention, SVM/KNN/Clustering, GNN vv...\n  - Kỹ thuật Knowledge Distiller/ Model Prune,  Model Quantization\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n  - Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…  \n  - Du lịch nghỉ dưỡng hàng năm\n  - Khám sức khỏe định kì\n  - Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n  - Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương  \n- Cơ hội nghề nghiệp và phát triển bản thân:\n  - Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng  \n  - Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng  \n  - Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.  \n  - Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)  \n- Môi trường làm việc lý tưởng với:\n  - Những người cộng sự thân thiện và tài năng  \n  - Cơ sở vật chất, không gian làm việc xanh và hiện đại.\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(473, 379, 2, 'Frontend developer (React JS/ Next JS)', 'At Softflex LLC, work ethics are highly valuable. We are a committed-to-success team that emphasizes collaboration and hard work.\nSoftflex team and management are determined to provide the smoothest work processes and create value with work invested. We are a team of doers, who strive for excellence and earn respect as outstanding software providers.\n\nWe are seeking a Frontend Developer (ReactJS, NextJS) to join our team as a short-term (renewable) contractor. The Frontend Developer \'s responsibilities will include:\n\n- Collaborate with other team members on projects\n- Develop and maintain web services and interfaces\n- Build web applications with web development best practices\n- Work with back-end developers to integrate UI components with APIs and databases\n- Gather and refine specifications and requirements based on technical requirements or UX design\n- Transform app designs into front-end code using HTML, CSS, JavaScript, and React JS with CSS framework (Tailwind or Bootstrap)\n- Develop and manage well-functioning databases and applications\n- Perform tests, troubleshoot, and fix bugs or other coding issues\n- Technical Documentation: Create and maintain comprehensive technical documentation for development, deployment, and operational processes.\n\nYour skills and experience:\n\n- At least 6 years FE, with 4 years on NextJS\n- Knowledge of HTML, CSS, JavaScript, and TypeScript to develop modern, responsive, and cross-browser-compatible websites.\n- Ability to read and understand PHP code (nice to have).\n- Ability to write clean, proper coding.\n- English skills: able to speak, and with good reading and writing abilities.\n- Ability to collaborate with teams and stakeholders to derive options and solutions to various problems.\n- Ability to plan, prioritize, and effectively manage multiple tasks to achieve objectives.\n- Ability to stay proactive, updated, and adapt to the latest technological advances, innovations, and changes.\n- Demonstrated ability to work effectively both independently and as a collaborative member of a team.\n\nWhy you\'ll love working here:\n\n- Attractive salary package (negotiable in the interview)\n- Annual leave (1 day per month)\n- Devices provision\n- Pantry offerings\n- Motorbike parking slot', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Epic tower, Lane 19 Duy Tan street, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(474, 380, 2, 'Technical Lead', 'We are looking for a Technical Lead to join our growing team in either Vietnam or Japan. This role requires strong technical expertise in full-stack development, cloud infrastructure, and architecture design. You\'ll lead development teams, drive architectural decisions, and ensure technical alignment with international clients — particularly in Japan, North America, Korea, and Singapore.\n\nWHAT WILL YOU DO?\n- Location working: HCMC office (Phu Nhuan Dist.) or Japan (Kansai)\n- Provide hands-on technical leadership across multiple projects involving enterprise systems, web/app or integrations, and AI-based solutions.\n- Architect scalable and secure systems.\n- Evaluate current systems, improve scalability, security, and performance, and promote best practices.\n- Guide onsite and offshore teams in Vietnam on implementation, code reviews, design standards, and technical excellence.\n- Manage project schedules, team resource planning, and technical reporting.\n\nYour skills and experience\nREQUIREMENT\n- Bachelor\'s degree or higher in Computer Science, Software Engineering, or a related field.\n- 5+ years of experience in software development, including:\n- Full-stack (Prefer: Java or Angular or ReactJS, NodeJS, Python, C#.NET)\n- Backend integration with REST APIs & microservices.\n- Database experience (Prefer: MySQL, Oracle, MongoDB or RDBMS, stored procedures,...)\n- Experience with cloud platforms (especially AWS) and CI/CD pipelines.\n- 2+ years in a leadership role (Team Lead or Technical Lead).\n- Strong communication and leadership skills.\n- Proactive, organized, and solution-driven mindset.\n\nLanguage Requirements (one of the following):\n- English: Proficient for communication with international clients.\n- Japanese: Business level or above (JLPT N2 or higher) for direct client interaction.\n\nNice to have:\n- Familiarity with AI or Generative AI concepts is a big advantage.\n- Experience with DevSecOps practices such as Snyk code scans is a plus.\n- Strong fundamentals in object-oriented design, data structures, algorithms, multithreading, and file handling.\n\nWhy you\'ll love working here\n- Health insurance, social insurance and Premium Health Insurance package for you.\n- Competitive salary package with 13th monthly salary and a good long-term and performance bonus monthly and yearly.\n- 5 working days per week (Monday-Friday), to some extent flexible working hours.\n- Free snacks and coffee every day.\n- Join the Soccer and Badminton Club.\n- Support onsite fee with two way airline tickets if customer requires.\n- Friendly, professional and open working environment.\n- Opportunities to gain hands-on experience in cutting-edge technologies.\n- You will become the key members of WATA as we WATA is growing faster and bigger now.\n- Guaranteed permanent employment and career development.\n- Skills up plan with Tech talk, soft skill talk, English club, working process training.\n- Company trip yearly.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, Toà nhà văn phòng 3 Bees, 281 Nguyễn Văn Trỗi, Phường 10, Phu Nhuan, Ho Chi Minh; Kansai, Japan', 'Full-time', '2025-10-07 20:59:18.149534'),
	(475, 276, 2, 'iOS Engineer (SwiftUI, Flutter )', 'ABOUT THE ROLE: We are seeking a highly skilled iOS Engineer to join our dynamic team. The primary purpose of this role is to design, develop, and maintain applications for Apple\'s iOS platform. The successful candidate will collaborate with cross-functional teams to define, design, and ship new features, ensuring the performance, quality, and responsiveness of applications. This role reports to the Mobile Development Manager and plays a crucial part in contributing to the success of our organization by delivering high-quality mobile applications.\n\n🎖 What to do\n- Design and build advanced applications for the iOS platform\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Ensure the performance, quality, and responsiveness of applications\n- Identify and correct bottlenecks and fix bugs\n- Help maintain code quality, organization, and automatization\n- Continuously discover, evaluate, and implement new technologies to maximize development efficiency\n\n🎖 What you should have\n- Minimum of 3 years of hands-on experience in native iOS development.\n- Proven experience with SwiftUI in at least 2 projects.\n- Minimum of 6 months of experience working with or studying Flutter.\n- Strong communication skills and ability to work effectively within a team.\n- Proficiency in English communication is a strong advantage.\n- Experience with writing Unit Tests is a plus.\n- Familiarity with modular architecture is considered a plus.\n\n💰 Competitive Salary – Deserved Rewards\n- Attractive salary, aligned with your skills and contributions.\n- Salary review twice a year to recognize your dedication.\n- Generous year-end bonus, based on individual performance.\n\n🩺 Comprehensive Healthcare – We Care About You\n- Premium health insurance package for extra protection.\n- Annual health check-ups at top-tier hospitals.\n- Ergonomic chairs to protect your health.\n- Access to mindfulness courses for your mental well-being.\n\n💻 Modern & Innovative Work Environment\n- Equipped with MacBook/Laptop & the latest technology to enhance productivity.\n- Dedicated office floors with 6 levels for various projects.\n\n🎓 Personal Development – Unlimited Growth Opportunities\n- Sponsored international certification exams, supporting professional advancement.\n- Specialized training courses & soft skills development to enhance expertise.\n- Flat organizational structure, enabling direct collaboration with leaders and fostering creativity and innovation.\n- Transparent and well-defined career advancement opportunities.\n\n🚀 Agile Mindset – People-Centric Growth\n- Open, flexible, and supportive work culture, driving collective success.\n- Stronger team connections, creating a dynamic and efficient workplace.\n\n🎉 Work Hard – Play Hard\n- Exciting activities: Open Talks, IT Seminars, Team Building, Project Trips, Sports Day, Year-End Parties…\n- Diverse entertainment: PlayStation, Friday Happy Hours, Mindfulness-related activities…\n\n⏰ Flexible Working Hours\n- Monday - Friday: 8:00 AM - 11:30 AM | 1:00 PM - 5:30 PM.\n\n🌟 Join TechTus, where we work HAPPILY to achieve our DREAMS together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '49A Phan Bội Châu, phường Thạch Thang, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(476, 381, 2, 'Nhân viên IT Ứng dụng & Hệ thống', '1/ Quản trị tổng thể hệ thống CNTT (Server, mạng, bảo mật, thiết bị)\n- Vận hành và duy trì hệ thống hạ tầng CNTT của công ty bao gồm: máy chủ (server), hệ thống mạng LAN/WAN/Wifi, camera, hệ thống email và các phần mềm ứng dụng dùng chung.\n- Đảm bảo hệ thống hoạt động ổn định, an toàn và bảo mật: giám sát hiệu suất, xử lý sự cố kỹ thuật, cập nhật và vá lỗi hệ thống định kỳ.\n- Quản lý tài khoản người dùng nội bộ: phân quyền truy cập, bảo mật dữ liệu, kiểm soát quyền hạn sử dụng.\n- Thực hiện sao lưu và khôi phục dữ liệu định kỳ, xây dựng quy trình đảm bảo an toàn thông tin.\n- Theo dõi và kiểm kê toàn bộ thiết bị công nghệ: PC, laptop, máy in, thiết bị mạng,… Đề xuất bảo trì, thay thế hoặc nâng cấp khi cần thiết.\n\n2/ Quản lý tài nguyên số và hỗ trợ kỹ thuật\n- Quản lý phần mềm bản quyền, domain, hosting, email, và các dịch vụ công nghệ đang sử dụng.\n- Hỗ trợ kỹ thuật và xử lý các yêu cầu phát sinh từ người dùng nội bộ liên quan đến CNTT.\n- Đề xuất phương án nâng cấp, mở rộng hệ thống theo nhu cầu phát triển của công ty.\n\n3/ Nghiên cứu và triển khai ứng dụng phần mềm phục vụ công việc\n- Chủ động nghiên cứu và đề xuất các phần mềm giúp tối ưu hóa công việc vận hành, quản lý và giao tiếp nội bộ (như: CRM, ERP, quản lý công việc, quản lý tài sản, v.v.).\n- Làm việc với nhà cung cấp phần mềm để demo giải pháp, so sánh chi phí – hiệu quả, và xây dựng kế hoạch triển khai.\n- Dẫn dắt các dự án chuyển đổi số, đảm bảo quá trình triển khai đồng bộ, hiệu quả giữa các bên.\n- Đào tạo sử dụng phần mềm mới, xây dựng tài liệu hướng dẫn và hỗ trợ vận hành ban đầu.\n\n4/ Tư vấn và các nhiệm vụ khác liên quan đến CNTT\n- Tư vấn, đề xuất mua sắm thiết bị, phần mềm phù hợp nhu cầu phát triển công ty.\n- Duy trì hồ sơ kiểm kê thiết bị CNTT và đề xuất cải thiện môi trường làm việc công nghệ.\n- Thực hiện các nhiệm vụ khác liên quan đến CNTT theo sự phân công của Trưởng phòng HCNS hoặc Ban Giám đốc.\n\nYour skills and experience\n1. Bằng cấp – kinh nghiệm làm việc:\n- Bằng cấp/ chứng chỉ: Tốt nghiệp Cao đẳng/ Đại học Chuyên ngành Công nghệ thông tin, Điện tử viễn thông, Khoa học máy tính,…\n- Kinh nghiệm từ 01 năm trở lên ở vị trí tương đương.\n\n2. Kỹ năng:\n- Nhanh nhạy công nghệ, yêu thích nghiên cứu và ứng dụng phần mềm mới nhằm tối ưu công việc; có kỹ năng tìm kiếm, so sánh, đánh giá phần mềm hiệu quả.\n- Có kinh nghiệm triển khai phần mềm, chuyển đổi số nội bộ, bao gồm làm việc với nhà cung cấp, demo giải pháp, đào tạo người dùng và dẫn dắt triển khai là lợi thế.\n- Hiểu biết và kinh nghiệm về cài đặt, vận hành, quản trị hệ thống server; am hiểu các sự cố liên quan đến server, có khả năng phân tích lỗi và xây dựng phương án backup dữ liệu phù hợp.\n- Thành thạo hệ thống mạng LAN, WAN, Wifi, Domain, NAS và các thiết bị mạng; có tư duy hệ thống và logic tốt trong quản trị hạ tầng CNTT.\n- Chủ động, cầu tiến, sẵn sàng học hỏi và đổi mới; có tinh thần trách nhiệm cao trong công việc.\n- Có khả năng làm việc độc lập và làm việc nhóm tốt; phối hợp hiệu quả với các phòng ban để hỗ trợ kỹ thuật và giải pháp công nghệ.\n- Ưu tiên ứng viên có khả năng dẫn dắt nhóm, đào tạo người dùng, đồng hành cùng tổ chức trong quá trình phát triển công nghệ.\n\nWhy you\'ll love working here\nThời gian làm việc: Từ thứ Hai đến Sáng thứ Bảy\n- Sáng: từ 8 giờ 30 đến 12 giờ 00\n- Chiều: từ 13 giờ 00 đến 17 giờ 30\n\nIV/ Lương thưởng:\n- Tổng thu nhập từ 10 triệu đến 14 triệu.\n- Thưởng kết quả kinh doanh theo năm.\n\nV/ Quyền lợi:\n1. Môi trường làm việc, tiện ích:\n- Môi trường làm việc trẻ trung - năng động - thân thiện - chuyên nghiệp.\n- Hỗ trợ máy móc, trang thiết bị phục vụ cho công việc.\n- Hỗ trợ trà, cà phê, nước uống, đồ ăn nhẹ,... tại khu vực ăn uống của công ty.\n- Tủ mát, lò vi sóng, máy pha cà phê, bàn bi lắc,... tiện ích ngay tại văn phòng.\n\n2. Chế độ đãi ngộ, phúc lợi:\n- Thu nhập hấp dẫn, xứng đáng với năng lực.\n- Quy trình đánh giá hiệu suất công việc rõ ràng, nhiều cơ hội thăng tiến theo năng lực và phát triển theo định hướng cá nhân.\n- Thưởng kết quả kinh doanh theo năm, đội nhóm, cá nhân có thành tích xuất sắc,...\n- Thưởng đột xuất sáng kiến, cải tiến, thưởng dự án/ hiệu quả công việc khác ..\n- Cơ hội được tham gia các khóa đào tạo, phát triển kỹ năng và chuyên môn.\n- Đãi ngộ, phúc lợi: Lễ Tết, hiếu hỉ, sinh nhật, ốm đau, thai sản, phúng điếu,...\n- Ngày nghỉ hàng tuần, phép năm, nghỉ Lễ Tết,... theo quy định của Luật lao động.\n- Chính sách khám sức khỏe tổng quát định kỳ hàng năm (công ty chi trả chi phí).\n- Chính sách Bảo hiểm Tai nạn và Chăm sóc sức khỏe.\n- Được hưởng đầy đủ quyền lợi theo quy định của Luật lao động, Bảo hiểm xã hội.\n\n3. Hoạt động nội bộ, truyền thông:\n- Các hoạt động gắn kết nội bộ, truyền thông văn hóa doanh nghiệp: Team-building, sinh nhật công ty, tất niên, tân niên, tea-break các dịp lễ, mini-game công ty, thương hiệu,...\n- Các câu lạc bộ thể thao: Bóng đá, cầu lông,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Long Tower, Tầng 16, 101 - 103 Nguyễn Cửu Vân, P. 17, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(477, 260, 2, 'Backend NodeJS Developer (Typescript, NestJS, NextJS)', 'WHO ARE WE?  Digital Unicorn is a French digital agency with a passionate and ambitious team. We specialize in:\n- Mobile Application Development\n- Website Development\n- AI/Deep Learning\n- UX/UI Design\nWe’re more than just a company — we’re a small hub for those who want to step into an international working environment. Here, you’ll train, work, and build your career foundation, all while growing friendships that last.\nAt Digital Unicorn:\n- We share and support each other\n- We build meaningful products for startups\n- We create a space where you can enjoy working and growing.\n\nWE ARE HIRING: Backend NodeJS Developer:\nLevel: Senior\nType: Full-time In-house, On-site\n\nAbout the Role\nDigital Unicorn is looking for experienced NodeJS Developers to join our high-priority SAS project. You will work on a modern backend stack, building robust, scalable, and maintainable systems. This is a great opportunity to work in a dynamic environment alongside talented engineers.\n\nResponsibilities:\n- Design, develop, and maintain backend systems using NodeJS, NestJS, and Typescript\n- Collaborate with frontend developers using NextJS to integrate APIs and services\n- Ensure system reliability, scalability, and performance\n- Write clean, efficient, and well-documented code\n- Participate in architectural design and code reviews\n- Troubleshoot, test, and maintain software to ensure strong optimization and functionality\n- Work in cross-functional teams to deliver high-quality software on time.\n\nYour skills and experience\n- 5+ years of hands-on experience with NodeJS and backend development\n- Proficiency in Typescript, NestJS, and RESTful APIs\n- Experience with NextJS and fullstack integration is a plus\n- Strong understanding of backend architecture, microservices, and cloud-based solutions\n- Familiar with CI/CD and modern DevOps practices\n- Good communication skills with basic spoken English level\n- Ability to work independently and in a team.\n\nWhy you\'ll love working here:\n- Training policy, salary, and bonus that match your skills and experience\n- Provision of full devices for work\n- 100% salary during the probation period\n- Full insurance policies\n- Dynamic, comfortable, and creative working environment\n- Team Building events/company trips every year\n- Snacks and fruits for breaks\n- Sports activities to recharge positive energies\n- Immerse in an English-speaking environment for professional foreign communication.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3F, 94 Ho Nghinh, Son Tra, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(478, 339, 2, 'Senior/Middle DevOps Engineer (Python, AWS)', 'Position Summary:\nThe candidate will be responsible for automated deployments, ensuring the highest reliability and scalability of our Production services, and efficiently managing our cloud platform infrastructure.\nOur ideal candidate is a professional with experience in automating deployments with modern configuration and deployment management systems. The candidate requires a broad knowledge of systems, servers, load balancers, storage, security, networking, and some background in programming. We are using cloud infrastructure (AWS), containerization, CI, and CD processes.\n\nResponsibilities: \nBuild, scale, and monitor various highly complex applications in our cloud platform infrastructure (AWS, GCP, etc.).\nBuild and maintain CI/CD pipelines to support automated deployments.\nBuild and manage containerization platforms (Docker & Kubernetes).\nManage and support multitier architecture focusing on web technology stack (CDN, Reverse Proxy, Application, DB).\nCollaborate with development teams to with application developers to automate and accelerate applications\' testing, release, and deployment into a runtime environment quickly and reliably.\nReview and recommend solutions and tools to improve the software development process. focusing on automation, efficiency, and quality enhancement.\nProactively look for ways to automate the installation and upkeep of build tools and dependencies.\nManaging pre/post-release code merges and the code branching strategies.\nResponsible for mentoring and teaching existing team members. As such, the ideal candidate must have experience clearly explaining solutions to complex problems and demonstrate the ability to lead and impart knowledge effectively to junior resources.\nMonitor system performance, ensure high availability, and maintain system reliability.\nTroubleshoot and resolve infrastructure and deployment issues promptly.\n\nYour skills and experience:\nStrong hands-on experience with CI/CD tools (Jenkins, GitLab CI, etc.), scripting languages (Bash, Python, etc.) and configuration management tools (Ansible, etc.)\nStrong experience with cloud platforms (AWS, GCP) and infrastructure-as-code (e.g., Terraform, CloudFormation).\nExperience with production deployments of Kubernetes Cluster -Experience in automating provisioning and managing Hybrid-Cloud infrastructure (AWS and On-Prem) at scale.\nExperience with monitoring and logging tools (Prometheus, Grafana, ELK/Graylog, etc.).\nRespond to, troubleshoot and drive root cause analysis (RCA) of complex live production incidents and cross-platform issues handling OS, Networking and Database in a cloud-based SaaS / IaaS environments by following and implementing SRE best practices.\nCapable of estimating costs of various approaches, and finding simple and inexpensive solutions to complex problems.\nEnjoy automating tasks, rather than repeating them.\nDegree in IT/Computer Science/Computer Engineering or related discipline. \nAt least 4 years of experience in DevOps position. \nStrong interpersonal and communication skills, both oral and written. \nAble to work in a dynamic and ever-changing industry. \nA self-initiated and proactive team player who can work with minimal supervision.\n\nWhy you\'ll love working here:\nAttractive compensation, regular assessments, and salary reviews;\n13th-month salary and annual bonus;\n20 days annual leave;\n100% salary during the probation period;\n100% social insurance, premium healthcare insurance, and annual routine check-up;\nUnlimited access to a selection of food and beverages;\nSpecial celebrations on 8/3, Father\'s day, 20/10, Christmas, Tet holiday, etc.;\nCompany activities: annual teambuilding, New Year party, quarterly company party, weekly fruits day, monthly birthday, etc.;\nSports activities: badminton, football, bowling, cycling, etc.;\nIn-house acoustic music band;\nCinema days with blockbuster movies.\n\nProjects & Team:\nInternational working environment with a young, friendly, dynamic team, and creative;\nFlat organizational structure;\nCompany sponsors overseas in-class training and online training courses.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 12, Hai Au Building, 39B Truong Son Street, Ward 4, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(479, 382, 2, '05 Back-end NodeJS Developer (SQL/DevOps)', 'Job Highlights\n- Be part of the PropTech\n- Be part of change, Be part of the solution\n- Exposure to International standards and cutting-edge technologies\n\nCompany Introduction\niCondo Vietnam is a leading provider of property management technology and solutions in the proptech industry based in Singapore with a development office in Ho Chi Minh City. iCondo Vietnam provides property management solutions to clients in Singapore, Australia, and Indonesia. We are expanding rapidly and are seeking passionate and experienced Back-end NodeJS Developers to join our robust fully-stacked IT Team.\n\nBeing part of the iCondo Vietnam team is very much like being part of a family. Your contributions are valued and will effect change. You will be nurtured and exposed to our dynamic, process-oriented, creative culture as we seek to explore software and hardware solutions to continually improve and deliver the highest quality level of service to our clients. You will also be exposed to various iCondo team members in Singapore, Australia and Indonesia. At iCondo Vietnam, be prepared to explore, experiment to push boundaries to continually exceed expectations and to cater to the different needs in each market.\n\nJob Description\n- Design and write with the cutting edge NodeJS to improve the availability, scalability, latency, and efficiency of back-end\'s range of services;\n- Work with the engineering team to explore and create new design/architectures geared towards scale and performance;\n- Engage in service capacity and demand planning, software performance analysis, tuning and optimization;\n- Work closely with infrastructure team in building and scaling back-end services as well as performing root cause analysis investigations;\n- Debug and modify complex, production software.\n\nYour skills and experience\n1/ Must have:\n- 4+ years of proven experience in NodeJS development.\n- This role requires candidates with a solid IT background, typically gained through 4 to 10 years of experience, with a strong emphasis on software development experience.\n- Strong proficiency in NodeJS, demonstrating in-depth understanding of its core concepts, asynchronous programming, and best practices.\n- Strong knowledge in at least one of the following languages: NodeJS (mandatory), Golang (preferred, but not obligatory).\n- Strong problem-solving skills with the ability to analyze and resolve complex technical issues.\n- Relevant experience with relational databases such as MySQL or PostgreSQL, including schema design and query optimization.\n- Adequate knowledge of Continuous Integration/Continuous Deployment (CI/CD) pipelines.\n- Experience with cloud platforms, specifically AWS.\n- Experience with containerization and orchestration using Kubernetes.\n- Good English communication skills, specifically in writing and reading.\n\n2/ Nice to have:\n- Basic understanding of UI/UX principles.\n- Experience with the React.js framework.\n- Familiarity with Microservices Architecture and Distributed Systems.\n- Availability to start work immediately.\n\n***Please submit your CV in PDF file format***\n\nWhy you\'ll love working here\n- Attractive salary with annual salary review, 13th-month salary, performance bonus;\n- Allocate modern working devices: Laptop, MacBook, Monitor, Test Phone, etc...\n- Insurances following Vietnamese labor law & Premium Healthcare package for you;\n- Certificate training package;\n- Work-life balance 40-hr per week from Mon to Fri (8:30 AM - 5:30 PM);\n- Flexible 12 days leave & Vietnam public holidays;\n- Annual health check-ups & other benefits: wedding, funeral, offspring delivery support;\n- Annual company trips, company events, team building activities;\n- Offering free snacks, tea, coffee, energy drinks, and by-choice request at the pantry;\n- A young, friendly, dynamic, and well-equipped environment to be creative;\n- Chance to work on exciting projects and work with fascinating overseas clients.\n- Work closely with various iCondo team members in Singapore, Australia and Indonesia;\n- Overseas travel opportunities for working related.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Pho Quang, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(480, 209, 2, 'Leader for DIAG Team (onsite China)', 'A subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nPROJECT OVERVIEW\nAs successful candidates:\nYou will take part in multi-million project for high-profile customer, which are automotive industry leaders Japan (Onsite China).\nYou will work on a full life cycle for automotive software used in a car such as Autosar software.\nYou have a great career advance to expand your horizon not only in the automotive industry but also the international working experience.\n\nRESPONSIBILITIES\nManage Development full life cycle of automotive software for various microcontrollers.\nWork with various kinds of microcontroller from Renesas, NXP, …\nPerform Requirement Analysis, (high and low) Design, Coding, Unit Testing, Integration Testing and Quality Testing.\n\nYour skills and experience\nWorking experience in programming in C/C++, Embedded Development.\nWorking experience in Diagnostic stack, UDSonCAN, OBD, OBDonUDS.\nWorking experience in development of full life cycle for automotive software (Requirement Analysis, (High-Low) Design, Coding, Unit Testing, Integration Testing and Quality Testing).\nDevelopment experience on Automotive microcontroller families like Renesas, NXP, …\nKnowledge of Diagnostic Communication Manager (DCM) and Diagnostic Event Manager (DEM).\nExperience with configuration tools and testing devices (e.g. Davinci, EB Tresos, CANoe, CANalyzer, VFlash, etc.)\nGood knowledge of hardware, software embedded system concepts and architecture.\nAbility to troubleshoot issues to resolution. Strong problem solving and root cause analysis skills.\nExperience with configuration management software (SVN, GIT)\nAbility to analyze / study new technical, new hardware.\nTeamwork and communication skills.\nGood in Japanese level: Can communicate/explain with customers about output/input (N3+).\nGood in English communication is a strong plus point.\n\nNice to have:\nWorking experience on AUTOSAR compliant BSW software related to diagnostics, MCAL driver development is a strong plus.\nOverall understanding of automotive systems.\nWorking with ISO 26262 (Functional Safety) and ASPICE process levels.\n\nWhy you\'ll love working here\nFPT Care insurance plan tailored for FPT employees.\nAttractive annual summer vacation allowance.\nSponsored training courses for personal growth and up to 100% coverage for certification costs.\nGlobal and inclusive workplace with monthly cross-cultural events.\nInternational exposure and career growth across global locations.\nWork-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Software Đường D1 Phường Tân Phú , District 9, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(481, 383, 2, 'Senior Java Backend Engineer', 'Top 3 reasons to join us\n\n1. Competitive package salary and learning culture\n2. Hybrid working environment\n3. Premium health care for you and your family.\n\nJob description\nPosition Summary\nWe are looking for a qualified, creative, energetic and self-starting Server Engineer with wide experience in developing and optimizing web application.\n\nResponsibilities\n• Build and develop products or systems with high numbers of users.\n• Improve the efficiency of existing products.\n• Build the architecture and design of new products and features.\n• Researching new technologies to apply in current and future projects.\n• Coaching and mentoring skills for junior developers.\n• Adhere to the company\'s project development process.\n\nYour skills and experience\nMust to have\n• Strong experience with JAVA.\n• Deep knowledge of OOP, design pattern.\n• Have Experience in one of these frameworks as Spring/Spring Boot.\n• Review code skills.\n• Strong knowledge of databases (Database Design & Optimization).\n• Eager to learn new technology and to resolve project.\n• Have a passion for exploring new technology and have always been the pioneer into exploring new technology.\n\nNice to have\n• Good at English or Japanese is an advantage.\n• Experience with development/operation of systems with large quantities of data and traffic.\n\nWhy you\'ll love working here\n1. Package: Competitive package, including 13th month salary and salary review (02) times per year.\n2. Benefits\n    - Hybrid working that gives members more chances to have work-life balance\n    - Communication Fund\n    - Transportation Allowances\n    - Fully-paid social insurance and premium health insurance for employees and their family\n    - Annual Health Check\n    - Corporate Stock Options based on Group Policy\n3. Top-notch equipment, tools and facilities for efficient working with various Open Spaces.\n4. Professional development via various training activities (with Udemy account, Language Courses, etc)\n5. Joining in interesting activities such as company trip, sport events, and various events throughout the year.\n6. Opportunity to collaborate with a global team (Japan, Korea, Thailand, Indonesia and Taiwan).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 20 - 21, tháp 1, tòa nhà Capital Place, 29 Liễu Giai, phường Ngọc Khánh, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(482, 317, 2, 'Embedded Linux Engineer (C++, Linux)', 'JOB SUMMARY:\nWe are seeking a skilled and motivated Embedded Software Engineer with a strong background in Embedded Linux and C++ to join our dynamic development team. In this role, you will be responsible for designing, developing, and maintaining software for embedded systems, ensuring seamless integration with Linux-based environments. You will work closely with cross-functional teams to deliver high-performance solutions for a variety of embedded applications.\n\nSPECIFIC RESPONSIBILITIES:\n- Solicit, generate and manage requirements related to SW components;\n- Apply internal process for new product development;\n- Design and implement complex software subsystems and whole systems within a larger embedded product using software engineering best practices.\n- Take design choice autonomously and validate that in a cooperative process and be able to lead deep technical discussion;\n- Troubleshoot the design, drive the relation with Validation and Verification team in a fruitful manner;\n- Study and benchmark the competitor’s products;\n- Preparing reports, manuals and other documentation on the status, operation and maintenance of software;\n- Participating in peer-reviews of solution designs and related code.\n\nYour skills and experience\nTechnical skills and background:\n- Bachelor\'s degree in computer engineering, software engineering, computer science, electrical engineering or equivalent\n- Good communications (English, Vietnamese)\n- Strong technical skills including understanding of software development principles\n- Proficiency in C++ (C++ 19)\n- Familiar with Linux user space programming and debugging\n- Familiar with Linux kernel space programming (device drivers for I2C, SPI, PCI, USB)\n- Familiar with Yocto project\n- Knowledge of common development tools (GIT, Jenkins, CMAKE).\n\nSoft skills:\n- Interpersonal abilities, ability to work with a team, attention to details, flexibility and creativity, proactive, project management skills, capability to work in a dynamic international team and in a complex environment, problem solving attitude, open minded.\n- Anticipate needs and potential technical issues and roadblocks in the development phase; shows initiative, ownership, and commitment; sustains a consistent, high level of productivity. Good at understanding and resolving issues and opportunities, evaluating them from different perspectives. Customer oriented; looks for solutions to augment customer or supplier’s satisfaction.\n\nEducation & Experience:\n- Bachelor\'s Degree (or equivalent experience) in Computer Science, Electrical Engineering, or related field.\n- 4+ years of professional experience in embedded software development, with a focus on Linux and C++\n- Experience with Linux-based embedded systems, including Linux kernel, Yocto project is highly desirable.\n\nWhy you\'ll love working here\nCAREER OPPORTUNITIES:\n- Live in a high-end technology R&D environment\n- Be proud to see your own developed products sold all over the world\n- Strong knowledge and skills improvement through practical training and technical experience\n- Career promotion with proven capabilities\n- Opportunity for overseas training (US, Europe, etc.)\n\nBENEFITS:\n Working day: from Monday to Friday (08:00 AM- 4:30 PM)\n- Salary and Allowance: Competitive\n- Incentive, Reward and Bonus: Outstanding employee award with attractive bonus, semi-annual KPI reward, Long term incentive for key positions and Annual bonus\n- Company’s labor policy completely pursuant to Vietnam labor legislation: working conditions, social & health insurance paid based on gross salary.\n- Mobility: Global mobility program in US and/or Italy\n- Benefits: Free meals, transportation allowances, accident insurance 24x24, private health care insurance including dependents; gifts for Vietnam national days, scholarship for children of employees\n- Exciting leisure: Sport activities, corporate parties, company trip once a year, monthly teambuilding.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Datalogic Vietnam LLC. F04, Lot I-4A, Saigon High Tech Park, Long Thanh My Ward, Thu Duc, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(483, 384, 2, 'Front-end Developer (JavaScript, HTML, CSS, TypeScript)', 'Nami Foundation is a pioneer organization in the field of digital assets and blockchain technology in Vietnam, with a strong focus on developing innovative financial technology products.\nWe are now looking for Front-end Developer (all level) as the description below:\nJob Description:\n• Work together with cross-functional teams to define, design, and ship new features.\n• Design, build and maintain efficient, reusable, and reliable web apps (ReactJS) or mobile (React Native).\n• Review, test, and verify code for adherence to quality and security standards.\n• Ensure the best possible performance, quality, and responsiveness of the applications.\n• Help maintain code quality and organization.\nYour skills and experience\nRequirements:\n• At least 6 months - 1 year of experience with the full lifecycle of project development for web applications.\n• Experience working with Javascript and experience with ES6 syntax. Solid knowledge of Javascript and HTML / CSS.\n• Experience in working with Redux, REST API, Socket.\n• Experience with REST-style interfaces and other web service-related technologies.\n• If you are a mobile developer: requires experience with Typescript.\n• Ability to read and understand English documents.\n• Having the spirit of startup work, ready to overtime if needed.\nNice to have:\n• Bonus for degrees in: Computer Science, Computer Engineering, or Software Engineering.\n• Experience in financial systems, especially payment/blockchain/forex domain, is a great bonus.\n• Advantage: Ability to optimize code, know how to make the frontend work smoothly. Take the trouble to learn to solve the problem. Have thought about the system, application structure.\nWhy you\'ll love working here\n• Salary range: Negotiable based on your experiences & qualifications.\n• Working hours: 09:00 - 18:00, Monday to Friday.\n• Flexible workspace: Flexible according to Nami\'s policy.\n• Nami\'s culture values ​​diversity, listening, and openness.\n• At Nami, internal knowledge-sharing and research sessions are held regularly.\n• At Nami, we take care of lunches, drinks for health & Weekly Happy Hour.\n• Nami cares about the physical and mental health of its employees, so annual health check-ups are organized at medical facilities.\n• Employee bonding activities are regularly organized at Nami.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Masteri Millennium, 132 Ben Van Don Street, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(484, 385, 2, 'Senior Software Engineer (ReactJS, NodeJS, PHP, Python)', 'Take the clearer route to smart career growth. At clearer.io, we’re reimagining eCommerce by enhancing search, discovery, and customer engagement through a standout suite of innovative apps. Our mission is straightforward yet powerful: to empower our partners with solutions that streamline their operations, foster customer trust, and drive sustainable growth. We’re not just about technology - we’re about making eCommerce smarter, simpler, and more impactful, delivering solutions that inspire confidence and create real results.\nWith fresh investment and rapid growth, this is the perfect time to join our journey. When you become part of clearer.io, you step into a role where your work truly matters. Here, you’ll have the opportunity to own your projects, drive outcomes, and make an impact within a supportive, diverse team of professionals dedicated to customer success. We value clarity, results, and a customer-centric approach that keeps us focused on delivering real value to our partners every step of the way.\nIf you’re ready to cut through the clutter and focus on what really matters in a dynamic eCommerce landscape, clearer.io is the place to grow, lead, and shape the future of online retail. Join us, and be part of a team that’s committed to making eCommerce clearer, more efficient, and more rewarding for everyone.\nYour Impact:\nAs a Senior Software Engineer, you will be a technical leader, driving the design and development of major features and systems for our cloud-based SaaS platform. You will architect complex solutions, mentor and coach other engineers, and collaborate with product leadership to shape our technical roadmap. This role offers a significant opportunity to influence the direction of our technology and the growth of our engineering team.\nThis position is located in Vietnam and fully remote.\nWhat You’ll Do:\nLead the design and development of major features and systems for cloud-based SaaS applications.\nArchitect and implement complex, scalable, and highly available solutions.\nDrive technical decisions and provide technical leadership across multiple teams.\nMentor and coach other engineers, fostering a culture of technical excellence.\nCollaborate with product management and other stakeholders to define product roadmaps and technical strategy.\nIdentify and mitigate technical risks and dependencies.\nProactively identify and address performance bottlenecks, security vulnerabilities, and scalability challenges.\nEvangelize best practices and contribute to the development of engineering standards.\nEvaluate and recommend new technologies and architectural patterns.\nLead incident response and resolution for critical production issues.\nYour skills and experience\nWhat You’ll Bring:\nTypically requires a minimum of 5 years of related experience with a Bachelor’s degree in Computer Science, Engineering, or equivalent.\nExperience with e-commerce and with specific experience of Shopify a plus!\nExpert-level proficiency in at least one frontend framework (React preferred or Angular/Vue) and experience with advanced UI concepts.\nExpert-level proficiency in at least one backend language (Node.js preferred or PHP/Python/Go) and experience with microservices architecture.\nDeep understanding of software architecture principles and design patterns.\nProven experience designing and building large-scale, distributed systems.\nExtensive experience with cloud platforms (e.g., AWS, Azure, GCP) and cloud-native technologies (e.g., Kubernetes, Docker).\nStrong experience with DevOps practices and tools.\nExcellent communication, collaboration, and leadership skills.\nProven ability to mentor and guide other engineers.\nExperience with performance tuning, security hardening, and system monitoring.\nExperience leading and influencing technical direction within a team or organization.\nProficient in English.\nQualities:\nWhat other characteristics do we look for? Leadership for sure. But what does that mean? Well, some of the attributes we appreciate include:\nInquisitiveness\nHaving pride in one’s workTenacity: trying to work it out but knowing when to ask for help\nFollow-thru and dependability\nA strong belief in the team’s success \nMost importantly, friendly/kind/a good teammate\nDemonstrable examples of leading individuals/teams driving architectural direction, establishing best-practices and patterns.\nWhy you\'ll love working here\nCustomers at the heart: We make our customers the stars of our show and help them thrive. When they grow, so do we. We obsess over their needs so we can dream big on their behalf.\nPurposeful progress: We harness our ingenuity to keep leveling up and growing stronger. We take initiative, think boldly, and don’t settle for the status quo. Every risk teaches us something new.\nEndless innovation: We take action, refine our work, and drive meaningful growth for each other and our customers. Humble in our pursuit, we continuously seek to improve. We ask ‘How can we help?’ striving always to make a meaningful\nAlways open: With transparency we simplify the complex, collaborate globally and empower everyone. We believe openness in our communication - with customers, partners, and team members - is essential for building strong relationships.\nClear Benefits:  \n100% Remote Culture: Work from anywhere that brings you happiness.\nPerformance-based Year-End Bonus: Recognizing and rewarding your individual contributions.\nWellness Allowance: Support for classes promoting physical and mental health.\nTime Off: 20 days/year, in addition to Vietnam holidays.\nMacBook Provided.\nCollaborative Events: Offline meet-ups, monthly gatherings, year-end party, and company trips.\nContinuous Learning: Technical and general workshops, online resources.\nHealth and Wellness Benefits: Generali Health Care, annual check-up.\nInternational Exposure: Enhance expertise and English communication skills.\nBe a part of clearer.io—where your expertise fuels real change in eCommerce. Come and join us - it’s clear we’re the place to be!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 46, Bitexco Financial Tower, 2 Hai Trieu Street, Ben Nghe Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(485, 386, 2, '02 Associate Reporting Specialist (Data Analyst)', 'Role Purpose\nAn Associate Reporting Specialist should have a basic understanding of best practices, can execute on tasks with supervision from others. Individuals will create basic level insights and recommendations in their area of expertise. Individuals in this role will continue to provide support to the team and begins to lead MS efforts with low complexity.\n\nPrimary Responsibilities\n• Is a dedicated resource to complete the daily Shares Outstanding task\n• Must review all relevant links compiled in the files generated for the specified jurisdictions (UK, FR, DE, BE, SE, FI, DK, IC).\n• All changes in Shares Outstanding and Total Voting Rights must be recorded and uploaded to Ref01 by EOD each day.\n• Actively engage with other team members\n• Analyze any discrepancies & variances\n• Reviewer of the drafts calculations\n• Handles all client facing communication/L1\n• Acts as a first point of escalation for clients\' incidents/L1\n• Continuous customer experience improvement\n• Handles shares outstanding & other client specific queries\n• KPIs reporting\n• Incidents reporting\n• Creating and running reports that provide insight into ongoing shares performance\n• Providing analysis and presentation of data, reports dashboards to key stakeholders\n• Prepare and maintain documentation, as required\n\nExperience required\nEssential\n• 3 + years\' relevant experience\n\nDesirable\n• Financial / Investment Services software experience in a client facing role.\n\nSkills required\nEssential\n• Must be self-motivated as well as creative and efficient in proposing solutions to complex, time-critical problems.\n• Ability to manage multiple projects and deadlines, tight timeframes, and willingness to work extended hours periodically based upon client expectation.\n• Good analytical and problem-solving skills with a high attention to detail.\n• Must be a team-player with the ability to work within collaborative environments.\n• Ability to understand technical issues at a high level and articulate them to internal and external stakeholders.\n• Ability to understand revenue forecasts, and mitigate impact of project schedule delays.\n• Must have excellent communication, organization, and time management skills.\n\nWhy you\'ll love working here\n*** Growth Opportunities\nTo support our fast growth, Confluence is seeking smart, hard-working people to join the Confluence team. Pursue dynamic growth opportunities while working with leading technologies.\n\n*** Values & Culture\nDriven by a commitment to four core corporate values — integrity, imagination, discipline and service — Confluence has created a culture which fosters professional growth and employee satisfaction while delivering exceptional results for our clients around the world.\n\n*** Top-Tier Benefits\nConfluence offers a comprehensive compensation package which includes highly competitive salaries and exceptional benefits.\n\n*** Confluence Cares\nShare a spirit of community service when working at Confluence by getting involved with local organizations and outreach programs.\n\nNote: If you wish to apply, please do so through the job on our careers page ( Click on Company website)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '127 Ung Văn Khiêm, Phường 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(486, 387, 2, 'Senior PHP Developer (Laravel, Symfony)', 'Job description\n- Working on Laravel, Symfony web-based projects.\n- Writing RESTful API based on PHP for applications.\n- Researching new technologies.\n\nYour skills and experience\n- 3 years+ experience in Laravel, Symfony framework development.\n- Good understanding of MySQL, MS SQL, RESTful API.\n- Good understanding of data structures and algorithms.\n- Good understanding about security.\n- Good understanding about Authentication, SSO.\n- Good understanding about File I/O, Stream.\n- Have knowledge about Redis, JS, microservice, Websocet.\n- Familiar with GIT, JIRA.\n- Have knowledge about Linux is a plus.\n- Experienced in SMS, OTP, Top-up.\n- Have good common sense and logical mindset when analyzing requirements. Further skills: Ability to read and understand English technical documentations is a plus.\n\nWhy you\'ll love working here\n- Salary: according to ability.\n- Bonus 13th month salary, holidays, Tet,... and job performance.\n- Participate in health insurance, social insurance, public holidays, 12 days of leave/year and other welfare regimes as prescribed by law.\n- Fully equipped for work.\n- Open, youthful working environment and many opportunities for career advancement.\n- Participate in training courses to improve professional skills according to job requirements.\n- Participate in teambuilding programs, company vacations organized quarterly/yearly.\n- Working from Monday to Friday, 8:30 AM - 5:30 PM.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '39/3 Trần Nhật Duật, Phường Tân Định, Quận 1, Thành phố Hồ Chí Minh, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(487, 388, 2, 'Senior Backend Engineer (Golang & Python)', 'Join the founding tech team transforming Vietnam’s largest café chain into a digital-first F&B and retail powerhouse. As a Senior Backend Engineer, you\'ll architect and scale high-impact systems that connect ERP, POS, sales channels, and internal tools, handling millions of weekly transactions with real-world complexity. We work with Golang, Node.js, Python, Postgres, and Kubernetes. This role is for you if you want ownership, scale, and impact.\n\nYou’ll be part of a core team led by seasoned engineers on a mission to digitally transform Vietnam’s leading coffee chain. This is your chance to:\n\n- Shape system architecture and build critical backend services from the ground up.\n- Work in a professional, modern engineering environment using CI/CD, mono-repo, API gateways, feature flags, and more.\n- Solve real-world problems at hyper-scale with millions of weekly transactions.\n- Collaborate in a high-ownership, mission-driven culture.\n- Grow under leadership that built the “Best Engineering Company to Work for in Vietnam”.\n\nIf you\'re seeking meaningful work with high impact, let’s talk.\n\nWhat You’ll Do\n- Design, build, and scale backend services using Golang, Node.js, and Python.\n- Integrate with complex systems—ERP, POS, e-commerce, inventory, HRMS, logistics, and more. Own the full service lifecycle: architecture, development, testing, deployment, operations. Optimize database schemas and queries for performance and scalability.\n- Build APIs and event-driven systems for seamless cross-system communication.\n- Ensure high system reliability through robust logging, monitoring, and incident response.\n- Write clean, efficient, testable code and contribute to design docs and engineering standards. Mentor junior engineers and foster a culture of technical excellence.\n\nYour skills and experience\n- 5+ years building and operating backend systems, ideally in F&B, retail, or similar domains.\n- Strong coding and design skills in Go, Node.js, or Python.\n- Expertise in relational databases, data modeling, and performance tuning.\n- Experience with Kubernetes, microservices, and CI/CD pipelines.\n- Solid grasp of OIDC, OAuth2, and secure API practices.\n- Familiarity with cloud platforms (GCP, Azure) and containerized environments.\n- Strong CS fundamentals (algorithms, data structures, distributed systems).\n- Excellent communication skills and fluency in business English.\n- A “get-it-done” mindset with high ownership.\n\nWhy you\'ll love working here\nVTI offers you a fulfilling working experience with:\n- Health care and dental insurance.\n- Phone and gas allowance.\n- 12 paid leave days a year.\n- Good discounts at Highlands Shops and Pho24 shops.\n- Prime location in Sala.\n- Sponsored events (Women’s Day, Men’s Day, Halloween party, Christmas party, Year-end party, and more).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khu đô thị Sala, 119 - 127 Nguyen Co Thach, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(488, 389, 2, 'Technical Leader (Java, Oracle, CentOS)', 'Job description\n- Lãnh đạo DEV Team, hướng dẫn và hỗ trợ chuyên môn cho các thành viên trong nhóm.\n- Định hướng, phân tích và thiết kế kiến trúc hệ thống, đảm bảo hệ thống bền vững, an toàn thông tin, hiệu suất cao, dễ bảo trì, nâng cấp và mở rộng.\n- Lập trình Java core/Java web, API trên nền core framework của công ty hoặc các framework khác tùy sản phẩm, dự án.\n- Tham gia phát triển các hệ thống sản phẩm, dịch vụ của công ty: Phát triển các Module của sản phẩm/dịch vụ; Phối hợp với BA, Tester fix bug, update module; Merge code.\n- Thống nhất các mục tiêu, sản phẩm cũng như đưa ra phương án kỹ thuật của dự án.\n- Xử lý các vấn đề kỹ thuật phát sinh trong quá trình phát triển.\n- Các công việc khác theo yêu cầu của Trưởng bộ phận IT.\n\nYour skills and experience\n- Tốt nghiệp ĐH trở lên chuyên ngành Công nghệ thông tin; Kỹ thuật phần mềm, Hệ thống thông tin, ...hoặc các ngành tương đương\n- Có từ 5 năm kinh nghiệm trở lên tham gia dự án thực tế, trong đó có ít nhất 2 năm kinh nghiệm Lead\n- Thành thạo ngôn ngữ lập trình Java; Database: Oracle; Operating System: CentOS\n- Hiểu biết về SQL Language\n- Có kinh nghiệm lập trình Backend (server side), API\n- Có kinh nghiệm lập trình xử lý file PDF, xử lý ảnh\n- Có thể đọc hiểu tài liệu kỹ thuật bằng tiếng anh\n\nƯu tiên - Điểm cộng lớn với các Ứng viên có:\n- Có kinh nghiệm lập trình eID, lập trình eKYC, lập trình OCR\n- Biết về lập trình AI; lập trình hệ thống (phần cứng, thiết bị ngoại vi)\n- Có kinh nghiệm xử lý dữ liệu lớn\n- Chủ động và có tinh thần trách nhiệm cao trong công việc.\n\nWhy you\'ll love working here\n- Thời gian làm việc: Thứ 2 – Hết Sáng Thứ 7 (08h00 – 17h30)\n- Địa chỉ làm việc: Tầng 5, Toà nhà ACCI, Số 210 Lê Trọng Tấn, Thanh Xuân, Hà nội.\n- Quyền lợi:\n- Thu nhập: từ 30 đến 35 triệu/tháng, thỏa thuận phù hợp với năng lực ứng viên.\n- Chế độ bảo hiểm, phúc lợi theo quy định của pháp luật và chính sách công ty.\n- Thưởng hằng năm, thưởng lễ tết, thưởng nóng cho những thành tích nổi bật\n- Tham gia đầy đủ BHXH và các chế độ theo quy định của Bộ Luật lao động.\n- Thời gian làm việc giờ hành chính từ thứ 2 đến thứ 7.\n- Nghỉ phép, lễ theo qui định của nhà nước. Bên cạnh đó, bạn còn nhận được quà nhân dịp Lễ Tết (30/4-1/5, 2/9, Tết Dương lịch, 8/3, 1/6,…) và các dịp sinh nhật, ốm đau, hiếu hỉ, kỉ niệm ngày cưới,..\n- Chế độ du xuân, nghỉ mát cùng Công ty. Các hoạt động gắn kết nội bộ.\n- Môi trường làm việc từ Lãnh đạo đến nhân viên đều rất trẻ trung, năng động. Là nơi để bạn thể hiện và phát triển được khả năng của bản thân.\n- Cơ hội phát triển sự nghiệp bền vững và đề cao các giá trị Văn hóa doanh nghiệp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5 (block Vietinbank) tòa nhà ACCI, số 210 Lê Trọng Tấn, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(489, 360, 2, '(Middle/Senior/Leader) .Net Developer (C#, SQL)', 'We are seeking skilled .NET Developers (Intermediate, Senior, and Lead levels) with a minimum of 3 years of professional experience in .NET development. Successful candidates will join our international team and contribute to the development of our Mortgage Lending platform. This role involves close collaboration with team members in both Vietnam and the Netherlands, providing a dynamic and culturally diverse work environment.\n\nResponsibilities:\n- Design, develop, and maintain .NET applications with a focus on technical excellence.\n- Collaborate effectively with international team members to deliver high-quality software solutions.\n- Participate in code reviews to ensure adherence to coding standards and best practices.\n- Troubleshoot and resolve technical issues to ensure smooth project execution.\n- Create and maintain clear and comprehensive technical documentation.\n\nFrameworks Used:\n- .NET Framework, .NET 8\n- Entity Framework\n- Web API\n- Dependency Injection, Autofac\n- NServiceBus\n- NHibernate\n- Azure Pipelines\n- Helm Charts\n\nYour skills and experience:\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- Strong English communication skills, both written and verbal.\n- Minimum of 3 years of experience in .NET development.\n- Proficiency in C# and the .NET framework.\n- Experience with SQL databases.\n- Strong understanding of object-oriented programming principles.\n- Excellent problem-solving skills and attention to detail.\n- Effective communication and teamwork abilities.\n- Experience with Azure DevOps and Azure Pipelines is a plus.\n- Experience working in an international team is a plus.\n\nWhy you\'ll love working here:\n- Fixed 13th-month salary and performance bonus.\n- Full salary during probation and full social insurance coverage.\n- Hybrid working model with a good work-life balance.\n- Premium healthcare (including annual health check-up).\n- 16 days of annual leave per year.\n- 5 paid sick leave days.\n- Dynamic and international English-speaking working environment.\n- Regular gatherings (happy hours, bimonthly dinners, social events, etc.).\n- Annual company trip.\n- Fully stocked pantry with coffee and snacks.\n- Budget for team activities.\n- Supportive and diverse work environment that promotes continuous learning.\n- Opportunity for traveling and training in the Netherlands.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '106 Nguyen Van Troi Street, Ward 17, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(490, 291, 2, 'Fullstack Developer (Reactjs, Java)', 'Top 3 reasons to join us\n1. Thử việc 2 tháng 100% lương\n2. Cơ hội được tham gia vào các dự án CNTT lớn\n3. Tổng thu nhập một năm lên đến 14-15 tháng lương\n\nJob description\n- Thiết kế và phát triển ứng dụng web Fullstack với Java Spring Boot (Backend) và ReactJS (Frontend).\n- Xây dựng và triển khai các ứng dụng Microservices.\n- Tích hợp cơ sở dữ liệu Postgres vào các dự án.\n- Tham gia vào quá trình thiết kế và xây dựng các hệ thống backend có khả năng mở rộng (scalable).\n- Tối ưu hóa hiệu suất và đảm bảo bảo mật cho các ứng dụng Backend.\n- Áp dụng nguyên lý lập trình hướng đối tượng trong việc phát triển và bảo trì mã nguồn.\n- Hiểu biết và kinh nghiệm sử dụng gRPC để xây dựng và triển khai dịch vụ truyền thông giữa các thành phần.\n- Tham gia vào quy trình phát triển theo Agile/Scrum\n\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin hoặc cao hơn\n- Có kinh nghiệm làm việc và kiến thức chuyên sâu về Java, Spring Boot, React, HTML, JavaScript từ 4 năm trở lên.\n- Có kinh nghiệm với Microservices Architecture, Event-driven Architecture\n- Hiểu biết về các nguyên lý SOLID và các mô hình thiết kế phổ biến.\n- Hiểu biết và áp dụng nguyên lý lập trình hướng đối tượng.\n- Kinh nghiệm trong lập trình đa luồng và xử lý multi-instances.\n- Hiểu biết và có kinh nghiệm tích hợp gRPC vào các dự án.\n- Khả năng làm việc độc lập và trong nhóm.\n- Kỹ năng giải quyết vấn đề và học hỏi nhanh chóng.\n- Biết cách tối ưu hiệu năng và xử lý lỗi hệ thống.\n- Có kinh nghiệm với các Python Framework là điểm cộng.\n\nWhy you\'ll love working here\n- Tham gia vào các dự án quy mô Bộ ngành, quốc gia, được làm việc cùng nhiều chuyên gia có nhiều kinh nghiệm.\n- Lương: theo thoả thuận theo năng lực.\n- Thưởng tháng lương thứ 13, thưởng KPI (6 tháng một lần, tức 1 năm 2 lần), thưởng theo kết quả kinh doanh, thưởng nóng theo hiệu quả công việc, thưởng ngày lễ (tổng thu nhập một năm lên đến 14-15 tháng lương).\n- Các chế độ phúc lợi khác dành cho nhân viên: sinh nhật, kết hôn, sinh con, ăn trưa, YEP, du lịch, happy hour, team building tháng, tea break, quà lễ/tết,…\n- Hoạt động thể dục thể thao năng động: bóng đá, cầu lông, tennis,…\n- Cung cấp thiết bị làm việc.\n- Tham gia đầy đủ các chế độ bảo hiểm (BHXH, BHYT, BHTN…), khám sức khoẻ định kỳ theo quy định của Nhà nước;\n- Chính sách hỗ trợ đào tạo nâng cao năng lực nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '385C Nguyễn Trãi, Phường Nguyễn Cư Trinh, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(491, 390, 2, 'Senior Scrum Master (Agile, Devops, .NET, JavaScript)', 'As a Scrum Master, you will support an agile team by applying Scrum practices and enhancing team performance. Your responsibilities include maintaining focus, removing blockers, and fostering continuous improvement.  • Assist in development and implementation  • Drive continuous improvement  • Identify and address organizational barriers to agility  • Collaborating with Product Owners and Developers  • Contribute to strategic agile initiatives  You will participate in development work as a senior full-stack developer. While your main focus is on Scrum Master tasks, you will join the development team to actively deliver work items.\n\nAlso, if you are a senior/medior full-stack developer who meets the qualifications for full-stack developer, we would love to hear from you!\n\nYour skills and experience  • 5+ years of experience as full-stack developer  • Back-end  • Expert on .NET / C# / MS SQL / OData (Required)  • Knowledge of MS Graph / YAML pipelines / CI/CD (required)   • Front-end   • Modern web development: JavaScript/CSS/HTML/Microsoft SQL Server/Entity Framework Core   (required)  • Libraries: React (Required)  • Design: Fluid Design (optional)  • Had real exp with Blazor server is a plus  • 5+ years as a Scrum Master with successful agile team leadership  • English level fluently  • In-depth knowledge of Scrum, Agile, and Microsoft Azure DevOps (required)  • General knowledge of IAM processes and applications (optional)  • Strong coaching and facilitation skills  • Experience in conflict resolution, servant leadership, and organizational change  • Advanced certifications (e.g., PSM II/III, CSP-SM, SAFe Agilist) are a plus\n\nWhy you\'ll love working here  • Extra free lunch/snacks/fruits every day.  • Free English class every week.  • Technical Training supporting packages.  • An international working environment with open-minded culture, friendly colleagues and supportive team leaders.  • English speaking environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '117 Ly Chinh Thang Street, Vo Thi Sau Ward, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(492, 391, 2, 'Junior Backend Developer (NodeJS/ Golang)', 'Job description\n- Báo cáo trực tiếp đến Quản lý dự án or Quản lý trực tiếp. Report to the Project Manager or Line Manager.\n- Làm việc với nhóm thiết kế về thiết kế sản phẩm hoặc thiết kế wireframe ứng dụng khi được yêu cầu. Working with the design team on product design or designing application wireframe when required.\n- Giải quyết lỗi và sự cố kỹ thuật. Resolve bugs and technical issues.\n- Đảm bảo tuân thủ quy định bảo mật và pháp luật. Ensure compliance with security and regulatory requirements.\n- Hỗ trợ nhóm Frontend: đảm bảo backend được thiết kế phù hợp để hỗ trợ tốt các giao diện người dùng và trải nghiệm của frontend. Frontend team support: ensure the backend is properly designed to support the frontend user interfaces and experiences.\n\nYour skills and experience\n- Kỹ năng thiết yếu Essential Skills\n  - Giao tiếp tốt bằng Tiếng Anh gồm cả nói và văn bản (đọc, nói, nghe, viết). Good communication in English both spoken and written (reading, speaking, listening, writing).\n  - Hơn 1 năm kinh nghiệm chuyên môn trong lĩnh vực này. 2+ years of professional experience in this industry.\n  - Thành thạo Node.js hoặc GoLang. Proficiency in Node.js or GoLang.\n  - Kinh nghiệm làm việc đã được chứng minh trong các dự án lớn. Proven working experience in large projects.\n  - Hiểu biết sâu sắc về RESTful API và kiến trúc microservices. Strong understanding of RESTful APIs and microservices architecture.\n  - Hiểu biết sâu sắc và có kinh nghiệm với PostgreSQL, PgPool, PgBouncer. Strong understanding and experience with PostgreSQL, PgPool, PgBouncer.\n  - Kiến thức về Git Knowledge of Git\n  - Kiến thức về các cơ sở dữ liệu no-SQL khác: Redis, Cassandra, Neo4j, MongoDB… Knowledge of other no-SQL databases: Redis, Cassandra, Neo4j, MongoDB...\n  - Kỹ năng giao tiếp nội bộ và đối mặt với stakeholder xuất sắc. Excellent stakeholder-facing and internal communication skills.\n  - Kỹ năng giao tiếp bằng văn bản và bằng lời nói tuyệt vời. Excellent written and verbal communication skills.\n  - Kỹ năng tổ chức vững chắc bao gồm chú ý đến chi tiết và kỹ năng đa nhiệm. Solid organizational skills including attention to detail and multitasking skills.\n  - Luôn tìm hiểu và cập nhật thông tin sâu sắc, đặc biệt trong ngành công nghệ. Khả năng thích ứng với các công nghệ mới. Always learn and update information deeply, especially in the industry of technology. Adaptability to new technologies.\n  - Đam mê đổi mới, tự động hóa, giải quyết vấn đề và kỹ năng phân tích. Passion for innovation, automation, problem-solving, and analytical skills.\n  - Lãnh đạo & làm việc nhóm. Leadership & Teamwork.\n  - Kỹ năng tư duy phân tích và khái niệm. Analytical and conceptual thinking skills.\n  - Khả năng làm việc tốt dưới áp lực và độc lập. Ability to work well under pressure and independently.\n  - Sự chú ý đến chi tiết. Attention to detail.\n\n- Bạn nên là một chuyên gia trong: You should be an expert in\n  - Kiến thức về quy trình CI/CD. Knowledge of CI/CD pipelines\n  - Kinh nghiệm với các nền tảng đám mây như AWS. Experience with cloud platforms such as AWS\n  - Kinh nghiệm với ngăn xếp ELK. Experience with ELK stack\n  - Data & BigData.\n  - AIoT\n\n- Bạn nên có kiến thức về một số công nghệ dưới đây: You should have knowledge of several of these technologies\n  - Kiến thức về các công nghệ chứa như Docker và các công cụ điều phối như Kubernetes. Knowledge of containerization technologies like Docker and orchestration tools like Kubernetes.\n  - AI & Data science\n  - Microservices\n  - Blockchain\n  - UX/UI\n  - Databases\n  - Enterprise architecture (EA)\n  - Programming languages\n  - Product & Project Management\n\n- Văn hoá, thái độ và tiềm năng: Culture, attitude and potential\n  - Minh bạch, trách nhiệm, thái độ làm việc tích cực, chủ động. Transparency, responsibility, positive and proactive working attitude.\n  - Kỹ năng giao tiếp và hợp tác. Communication and collaboration skills.\n  - Đối xử tốt với mọi người. Treat others well.\n  - Tiềm năng phát triển. Potential for growth.\n  - Tiềm năng quản lý. Management potential\n\n- Quyền hạn: Your power\n  - Theo các văn bản thỏa thuận được thống nhất và ban hành. According to the agreed and issued agreement documents.\n\nWhy you\'ll love working here\n- Chính sách tiền lương: Salary policy\n  - Mức lương thử việc bằng 85% mức lương chính thức (02 tháng). The probationary salary is 85% of the official salary (02 months).\n  - Mức lương chính thức từ 10.000.000 VND - 18.000.000 VND GROSS (tùy thuộc vào năng lực). The official salary form 10.000.000 VND - 18.000.000 VND GROSS (depending on ability).\n- Chế độ phụ cấp, bảo hiểm theo quy định của pháp luật. Allowance and insurance regime as prescribed by laws.\n- Làm việc từ thứ Hai đến thứ Sáu và sáng thứ Bảy, giờ làm việc: Working from Monday to Friday and Saturday morning, working hours:\n  - Sáng: 09h00 - 12h00 ; Sáng thứ Bảy: 09h00 - 13h00. Morning: 09.00am - 12:00pm ; Saturday morning: 09:00 - 13:00.\n  - Chiều: 01:00 pm - 06:00 pm. Afternoon: 01:00pm – 06:00pm.\n- Đi du lịch cùng công ty ít nhất một lần mỗi năm. Company trip at least once a year.\n- Chúng tôi luôn có kế hoạch xác định lộ trình nghề nghiệp phù hợp cho từng cá nhân và mở ra nhiều cơ hội thăng tiến và phát triển nghề nghiệp một cách năng động. We always have plans to define career paths matching for each person and open opportunities for promotions and career development in a dynamic.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '8th Floor, Bach Dang Complex Building, 50 Bach Dang, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(493, 182, 2, 'Technical Scrum Master (Agile)', 'Are you a Technical Scrum Master that can still code and test when your team requires it? Do you have experience in product development and desire to build high performing teams? If so read on.\n\nAbout our Team\nOur team is responsible for creating a brand of new digital financial platforms and apps that are highly reliable and scalable using modern engineering practices. You will be joining a project which talented software engineers in our Digital Bank Build team who is responsible for designing, building and maintaining the new digital banking platform and the customer channels. As part of the team, you will be responsible for implementing software features, involve in technical designs and writing tests to ensure the high quality delivery of the product. The teams operate in Scrum and DevOps model.\n\nAbout the job\nWe are looking for an experienced and versatile Technical Scrum Master who will be responsible for building a new scrum team for the delivery of one of our new fintech products.\n\nThe Scrum Master critical responsibility is for the team and for optimal flow of work to DONE. Scrum Masters are expected to do this by setting the pace for delivery and being proactive in planning and forecasting for upcoming deliverables. To be successful in the role you should demonstrate pragmatism in your approach and be sensitive to the environment that we operate in, using your skills and knowledge to appropriately influence the delivery approach.\n\nWe are seeking a motivated individual with:\n- Excellent English speaking and written skills. (Mandatory)\n- Foster an open, honest and transparent relationship with key stakeholders\n- Excellent presentation and facilitation, coaching and mentorship skills\n- Strong stakeholder management and communications experience\n- Strong ability to influence cross-functional teams and leadership\n- Demonstrate assertiveness, being the voice of reason and authority\n- Must be enthusiastic and bring high-energy to the delivery team\n- Responsible for continuous delivery and management of technical debt\n- Previous experience leading small teams while still being hands-on\n\nYour skills and experience\n- At least 2+ years recent experience as a Scrum Master.\n- Accountable for the quality of agile ceremonies including daily scrums, sprint planning, showcases and retrospectives\n- Ability to provide constructive and timely feedback to delivery team members and stakeholders\n- Conflict resolution within/between delivery team and stakeholders\n- Ability to negotiate priorities and timelines with stakeholders\n- Setting the pace/cadence for delivery and motivating teams to succeed\n- Ensuring the delivery team commits to their definition of done\n- Visual representation and management of work in the sprint e.g. card walls and burn-up charts\n- Management of the Master Story List (MSL), ensuring it is adequately maintained, stories are up to date and ready to play into a sprint\n\nKnowledge of at least 3 of the following areas:\n- Mobile: iOS or Android\n- Web: HTML5, CSS3, Angular JS, Javascript\n- Microsoft .Net (C#, ASP, Framework), SQL Server\n- Quality Assurance, Automation Testing\n- Web Security, OWASP\n- Java, Oracle\n- DevOps, Continuous Delivery\n\nWhy you\'ll love working here\nAt TYME opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments or people leadership.\n\nSome of our benefits:\n- Meal and parking allowance covered by company.\n- Full benefits and salary rank during probation.\n- Insurances as Vietnamese labor law and premium health care for you and your family.\n- SMART goals and clear career opportunities (technical seminar, conference and career talk) - we focus on your development.\n- Values driven, international working environment and agile culture.\n- Overseas travel opportunities for training and working related.\n- Internal Hackathons and company\'s events (team building, coffee run, blue card...)\n- Pro-Rate and performance bonus.\n- 15-day annual + 3-day sick leave per year from company.\n- Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower, Lumiere Riverside, 277 Vo Nguyen Giap, An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(494, 392, 2, 'Remote Senior Fullstack Engineer (NodeJS/ReactJS)', 'Top 3 reasons to join us\n\nGain very attractive salary and benefits;\n\nBe a developer, not a coder;\n\nExcellent environment and team to help you grow.\n\nJob description\n\nDevelop features from the end-to-end cycle: from Front-end to Back-end;\n\nCoordinate with cross-functional team members for clarification;\n\nEnsure quality by writing test cases by using Jest, Cypress;\n\nFollow coding conventions and best practice standards within the project.\n\nYour skills and experience\n\nMore than 5 years of working experience in software development;\n\nSolid experience with both NodeJS (NestJS) and ReactJS (or NextJS), with a strong emphasis on backend development;\n\nIn-depth knowledge of microservices architecture principles;\n\nHands-on experience with testing frameworks like Jest and Cypress;\n\nExcellent communication skills in English, both written and verbal;\n\nCollaborative team player, accustomed to working in an Agile environment;\n\nDaily meetings and hourly catchups with the cross-functional team via Huddle.\n\nWhy you\'ll love working here\n\nRemote working model and flexible working hours;\n\nFull social insurance including probationary period; \n\n12 days of annual leave and 3 additional special holidays (Swedish National Day, Christmas Eve & your Birthday);\n\nAnnual leaves increase by loyalty;\n\nPremium health care package for employees & family members;\n\nEnglish, professional working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote', 'Full-time', '2025-10-07 20:59:18.149534'),
	(495, 393, 2, 'Senior Software Engineer (Python, JavaScript, ERP)', 'Top 3 reasons to join us\n- Flexible working hours at the office.\n- International team, daily English communication\n- Motivating bonus system for our employees.\nJob description\n- Technical Solution Design: Collaborate with analysts to design and implement technical solutions that meet client specifications.\n- Custom Module Development: Develop and integrate custom modules into the Odoo ERP system, ensuring seamless functionality.\n- API Integration: Design, develop, and integrate APIs to connect Odoo with third-party applications and external systems.\n- Data Orchestration: Implement and manage workflows for efficient data processing and automation between different systems.\n- Code Review and Quality Assurance: Conduct thorough code reviews to ensure stability, reliability, and optimal performance.\n- Issue Analysis and Debugging: Analyze and debug issues to maintain system integrity and performance.\n- Collaboration and Reporting: Work with developers and business users to gather data requirements, execute technical solutions, and prepare reports.\n- Mentorship: Train and mentor junior developers, fostering a culture of continuous learning and improvement.\nYour skills and experience\n- Education Background: Advanced Diploma or Bachelor\'s Degree in Computer Science, Information Technology, Physics, or Engineering.\n- Professional Experience: Minimum of 5 years as a Software Engineer, preferably with experience with ERP systems.\n- Programming Proficiency: Strong experience in Python and Object-Oriented Programming; familiarity with JavaScript and mobile development is a plus.\n- API Development & Integration: Hands-on experience in designing and integrating RESTful, APIs, JSON, and web services.\n- Data Orchestration: Experience in managing automated data workflows and inter-system data synchronization.\n- Database Expertise: Proficient in SQL and NoSQL database systems; experience with MySQL, PostgresSQL, or Oracle is beneficial.\n- ETL & Data Processing: Understanding of data transformation and ETL principles; experience with data pipelines is a plus.\n- Version Control: Experience using GitLab and GitHub for source code management and collaboration.\n- CI/CD & Deployment: Familiarity with CI/CD pipelines using GitLab CI, Jenkins, or similar tools for automated testing and deployment is a plus.\n- Cloud & Messaging System: Knowledge of cloud solutions (AWS, GCP, Azure) and messaging queues (Celery, RabbitMQ) is advantageous.\n- Communication Skills: Strong verbal and written communication skills in English; proficiency in French is a plus.\n- Soft Skills: Strong analytical thinking, problem-solving abilities, and the ability to perform well under pressure.\nWhy you\'ll love working here\n- Compensation & Perks: We offer an attractive salary package, including a performance-based bonus. Your hard work and successful projects directly translate into your rewards.\n- Team Building & Events: We believe in creating a diverse and inclusive workplace culture that supports the growth and well-being of our team members both professionally and personally.\n- Coaching & Mentoring: Our comprehensive coaching and mentoring program empowers our staff for future success. We provide coaching sessions with documentation and practices to accelerate learning, refine skills, and navigate challenges.\n- Flexible Working Hours: At Portcities, we understand that our team has diverse needs and responsibilities outside of work. We have flexible working hours, so you can better manage your schedule and find the optimal time for productivity.\n- Internal Transfer Opportunities: Portcities, with 12 branches worldwide, offers internal transfer opportunities, providing exposure to different regions and cultures and enhancing your career journey.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '10 Vinh Khanh Street, Ward 10, PLS Building (1st Floor), District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(496, 394, 2, 'Mobile Developer (ReactJS/React Native)', 'Fincorp is one of the leading Fintech companies with many products, one of which is Fmarket - the online platform allowing customers to trade open-ended funds (fmarket.vn) and F-Platform (fplatform.fincorp.vn) which provides management and distribution solutions for Fund Management Companies. The latter has been trusted and used by VinaCapital - one of the biggest Fund management Companies in Vietnam.\n\nJob Description:\n- Develop and maintain cross-platform mobile applications (iOS & Android) using React Native.\n- Collaborate with Backend, UI/UX teams to design, optimize, and enhance app performance.\n- Ensure the quality, scalability, and security of mobile applications.\n- Troubleshoot issues and improve app functionality based on user feedback and team requirements.\n- Stay up-to-date with new technologies and industry trends.\n\nYour skills and experience:\n- Bachelor’s degree in Computer Science/IT or related field.\n- At least 3 years of experience working with React Native.\n- Experience with RESTful APIs, third-party libraries, Redux, Flexbox, Push Notification.\n- Familiarity with native build tools, like XCode, Gradle Android Studio.\n- Familiar with releasing apps to the App Store and Google Play.\n- High sense of responsibility in work.\n- Strong logical thinking and problem-solving skills.\n- Eager to learn and continuously improve.\n- Preference will be given to male candidates. Please include a recent profile picture in your CV.\n\nWhy you\'ll love working here:\n- Salary range: 1.000 - 1.500$.\n- 13th month salary and additional bonuses.\n- Yearly company trip.\n- Laptop/PC provided upon joining.\n- Free snack and beverage.\n- Great allowances (parking, birthday, happy hours, team building).\n- Salary review at least one time per year based on employee\'s performance and contribution.\n- Great fintech company with most promising products, open and positive environment.\n- Other benefits stated in Vietnamese Labor Law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bcons Tower, 176 Nguyen Van Thuong, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(497, 395, 2, 'Junior iOS developer (Swift, Objective C)', 'We are looking for iOS Talents to join our highly motivated hard working & playing team developing our e-commerce service. •          Work directly with Yahoo! JAPAN team (service planner, technical leaders, designer, engineers…) to figure out user’s needs, problems; expectations to contribute ideas & solution as well as to realize/ resolve them. •          Deliver outputs with expected quality, speed, compliance in order to bring the best values to product/service’s end users. •          Mentor or coach junior members if needed to achieve a certain level of competency or performance to meet project’s objectives. \n\nYour skills and experience\nSkills & Experience: • Have more than 2 years of experience as an iOS Developer.\n• Experience working with GIT and JIRA. \nTechnical skills: • Proficient in Swift and CocoaTouch, with main focus on Swift Projects. \n• Good experience with Xcode environment setup and optimization. \n• Strong understanding of Restful APIs and Clean Architecture principles. \n• Experience with UIKit, SwiftUI, and Foundation framework. \n• Proficient in AutoLayout, Animation and adapting to multiple screen sizes. \nCode quality: • Knowledge of Clean Code Principles and the ability to write and maintainable code. \n• Experience with writing Automation tests (Test Code) to ensure code quality. \nAdditional skills: • Experience in Backend development (JAVA/Node.js) or Frontend development (React) is a big plus point. \nSoft skills: • Logical thinking and problem-solving skills are required. \n• Able to work independently or collaboration, and communication skills when working with others. \n• Ability to proactively learn and acquire necessary skills for existing or future project. \n• Ability to work effectively in a team environment and contribute to team success. \n• Experience working in JP company is a plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 10, Tháp 2, Tòa nhà Saigon Centre, 67 Lê Lợi, phường Bến Nghé, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(498, 182, 2, 'Senior DevOps Engineer (Cloud, AWS)', 'We are seeking an experienced Senior DevOps Engineer (AWS) to join our team and play a crucial role in supporting our engineering and business operations.\n\nThe ideal candidate will be responsible for the implementation of tools and processes which enable rapid development and deployment of software.\n\nYour mission is to embrace continuous integration/deployment in a delivery pipeline that will perform automated quality checks, deploy cloud infrastructure and applications quickly, and provide operational tooling and metrics that can be consumed by development teams. To be successful, you will have a blend of development experience and operational experience that provides a good understanding of the developers you are working with, while also balancing critical systems uptime.\n\nMain responsibilities:\n- Contribute to developing continuous delivery, automation, and building pipelines to create an excellent experience for developers and customers\n- Identify and develop opportunities to improve our processes and tools for automation\n- Learn new skills and help foster a continuous delivery and cloud-first mindset\n- Manage your day-to-day workload and requests using agile practices as part of a team and community\n- Periodic after-hours on-call support is required with over-time\n- Ability to travel occasionally (up to 10% of the year)\n\nYour skills and experience\nRequirements:\n- Bachelor\'s or Master\'s degree in Computer Science, Information Technology, or a related field.\n- Experience in managing Linux operating systems\n- Experience using Docker and container orchestration, such as ECS/EKS is a plus\n- Knowledge of one or more of the following AWS CloudFormation/Terraform/CDK for infrastructure provisioning.\n- Knowledge of the source control and its related concepts (Gitlab/Git flow, Trunk base, branches, etc.).\n- Experience with CI/CD tools (such as Jenkins, TeamCity, AWS CodePipeline, CodeDeploy) or configuration management tools (such as Ansible, Chef, Puppet..)\n- Familiarity with at least one programming language (Python, Bash, etc.).\n- Knowledge of networking, firewalls, load balancers, high availability, etc..\n- Good skills in English and the ability to communicate effectively with business and technical teams.\n- Demonstrate good logical thinking and problem-solving skills.\n- Be curious and self-learning attitude.\n- Experience in SDLC and Agile methodologies.\n- Ability to work independently and as part of a team.\nNice to have:\n- Experience in the banking or finance industry\n- AWS certification(s) related to Advanced Networking\n- AWS Certified DevOps Engineer - Professional\n\nWhy you\'ll love working here\nYou’ll love working with us if you are:\n- Passionate about technology.\n- Independent but also a good team player.\n- Comfortable with a high degree of ambiguity.\n- Focused on usability and speed.\n- Keen on presenting your ideas to your peers and management.\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\nSome of our benefits:\n- Meal and parking allowances are covered by the company.\n- Full benefits and salary rank during probation.\n- Insurances such as Vietnamese labor law and premium health care for you and your family.\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\n- Values-driven, international working environment, and agile culture.\n- Overseas travel opportunities for training and work-related.\n- Internal Hackathons and company events (team building, coffee run, etc.).\n- Pro-Rate and performance bonus.\n- 15-day annual + 3-day sick leave per year from the company.\n- Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower, Lumiere Riverside, 277 Vo Nguyen Giap, An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(499, 396, 2, 'Trưởng nhóm Giải pháp CNTT', 'Job description\n• Hệ thống giám sát và cảnh báo an ninh: Tích hợp phần cứng đầu cuối với phần mềm quản lý và giám sát trung tâm sử dụng các tính năng và công nghệ thông minh như phân tích hình ảnh, phân tích sự kiện, phân tích hành vi...\n• Hệ thống Âm thanh thông báo, hội nghị truyền hình, camera nhiệt,...\n• Hệ thống CNTT bao gồm Server, Switch, Firewall, Wifi...\n• Các giải pháp về AI trong phân tích hình ảnh và thiết bị ngoại vi\n• Đào tạo và hỗ trợ đội ngũ nhân sự IT, phát triển năng lực đội ngũ chuyên môn\n• Quản lý và điều phối nhóm kỹ thuật, phân công nhiệm vụ, kiểm soát tiến độ và chất lượng dự án\n• Tham gia quản lý dự án: xây dựng kế hoạch, theo dõi thực hiện, đánh giá rủi ro và đưa ra giải pháp xử lý\n• Các công việc khác theo sự chỉ đạo của Giám đốc công nghệ.\nYour skills and experience\n• Trình độ học vấn: Tốt nghiệp đại học trở lên chuyên ngành CNTT, Khoa học Máy tính viễn thông, điện tử, kỹ sư phần mềm,...hoặc các chuyên ngành khác có liên quan.\n• Kinh nghiệm: Tối thiểu 2-3 năm trong lĩnh vực CNTT, có ít nhất 1 năm ở vị trí quản lý hoặc trưởng nhóm.\n• Kiến thức chuyên môn:\n- Thành thạo về kiến trúc hệ thống phần mềm, dữ liệu và bảo mật.\n- Hiểu rõ các mô hình phát triển phần mềm: Agile, Scrum, Waterfall.\n- Kỹ năng phân tích nghiệp vụ và thiết kế giải pháp kỹ thuật.\n- Khả năng sử dụng Tiếng Anh tốt là một lợi thế\n• Kỹ năng mềm:\n- Kỹ năng lãnh đạo, giao tiếp và làm việc nhóm tốt.\n- Khả năng quản lý thời gian, giải quyết vấn đề và ra quyết định.\n- Có tư duy đổi mới và định hướng khách hàng.\nWhy you\'ll love working here\n• Mức lương: Thỏa thuận theo năng lực, Upto 25 triệu\n• Thời gian làm việc: Từ thứ Hai – Thứ bảy (nhưng trong một tháng chỉ làm việc 2 ngày thứ Bảy)\n- Sáng: 8h00 -12h00\n- Chiều: 13h30 – 17h30\n• Được tham gia các chế độ BHXH, BHYT, BHTN, ... theo quy định của Công ty và nhà nước\n• Thưởng hiệu quả công việc, Lễ, Tết, sinh nhật, lương tháng 13,...\n• Được tham gia các sự kiện của Công ty như: Teambuilding, sinh nhật, YEP,...\n• Thưởng năng suất làm việc, hiệu quả công việc, trách nhiệm,...\n• Môi trường làm việc chuyên nghiệp, trẻ, năng động, phát triển bản thân, ham học hỏi, nhiệt huyết,...\n• Có cơ hội tham gia các dự án lớn của Công ty, được tiếp xúc với nhiều hãng công nghệ hàng đầu thế giới,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'SN77 TT3D KĐT mới Phùng Khoang, Văn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(500, 308, 2, 'Java Backend Developer (Spring)', 'Top 3 reasons to join us\n- Attractive income.\n- Being recognized, fair compensation.\n- Open and honest culture.\n\nJob description\n- We\'re looking for an experienced senior Java to join us. You will have opportunities to improve your skills and contribute to develop new and exciting solutions to our products.\n- The applicant must show ability to work productively both independently and in a team environment.\n- Automate ETL pipelines and ML workflow\n\nYour skills and experience\n- At least 4 years experience in Java\n- Good knowledge of key Open source technologies, such as: Spring-boot, Spring, Hibernate, Jetty, Jackson, JUnit, Apache Commons and SLF4J\n- Experience in the development of larger Java solutions\n- Be an efficient and quality-oriented person with experience from project based on Agile methods like Kanban and Scrum\n- Experience with ORM technologies like JPA and Hibernate, are comfortable with the JDBC / SQL and database systems such as POSTGRESQL, MYSQL\n- Experience with NoSQL (Redis, Cassandra, Hbase, MongoDB, ...).\n- Experience with application servers like Jetty and Tomcat, and know to Web services and integrations based on SOAP and REST\n- Good knowledge of solutions related to construction and integration Maven, Team City, and Jenkins/Hudson\n- Plus: experience in BigData Architect (Hadoop, Kafka, Spark).\n\nWhy you\'ll love working here\nWhat We Offer\n- Competitive salary: 1200 – 1600USD/ month, plus performance bonuses & potential ESOP.\n- A strategic role in scaling one of Vietnam’s most innovative proptech platforms.\n- Fast-paced, impact-driven, tech-enabled working environment with real market influence.\n- Complete benefits package, including insurance, company trips, team building, and regular internal engagement activities.\n- Generous special Employee Stock Ownership Plan (ESOP), which is approved by the Board of Director.\n\nInside our engineering team:\n- We iterate constantly. There\'s no such thing as the best version of anything, just a constant streams of improvements and tests.\n- We move fast, really fast. Major changes can be executed in a few days, many times just a few hours.\n- We have a data-informed mindset. We try to use data to inform our decision as much as possible.\n- We are independent. Most of the time, your team will not need technical assistance from other teams.\n- We take risks. We\'re not afraid to challenge "best practices".\n\nOur attractive offers include:\n- Open communication with passionate and experienced members.\n- Challenging working environment.\n- Social insurance, unemployment insurance under the Insurance Law\n- Internal events to bond our mutual understanding & spirit such as team building, team outing, Citic\'s birthday, Year-end party...\n- Generous special Employee Stock Ownership Plan (ESOP), which is approved by the Board of Director.\n- 40 flexible working hours per week from Monday to Friday.\n- Young, dynamic working environment with strong startup culture.\n- Training and career development opportunities.\n- Company team building, annual Birthday party and other events: New Year, X-mas, Mid Autum Festival,…\n- Support fee for parking, marriages, child births, hospitalization.\n- Sport clubs (Running, Badminton, Soccer).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lakeview 1, An Khanh Ward, District 2, HCMC, District 2, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(501, 397, 2, 'Chuyên viên Vận hành Công nghệ (NOC)', 'MỤC TIÊU CÔNG VIỆC: Thực hiện việc theo dõi, giám sát và báo cáo tình trạng hoạt động của hệ thống, ứng dụng và dịch vụ nhằm cung cấp thông tin hữu ích cho ban quản lý. Phát hiện và xử lý kịp thời các sự cố về hệ thống, ứng dụng và dịch vụ nhằm đảm bảo duy trì hoạt động liên tục và ổn định của hệ thống.\nNHIỆM VỤ, TRÁCH NHIỆM CHÍNH: \n- Giám sát và phát hiện kịp thời các sự cố thông qua các công cụ giám sát và cảnh báo\n- Phân tích các thông tin cảnh báo, sự kiện và log để xác định nguyên nhân gốc rễ của sự cố\n- Triển khai các biện pháp khắc phục và phục hồi hệ thống, ứng dụng và dịch vụ.Ghi chép, theo dõi và báo cáo tình trạng xử lý sự cố.\n- Phối hợp với các nhóm kỹ thuật, phát triển ứng dụng, kiến trúc và các bên liên quan khác để chia sẻ thông tin và phối hợp xử lý sự cố\n- Hỗ trợ các nhóm chuyên môn trong việc phân tích nguyên nhân gốc rễ và đề xuất các giải pháp khắc phục\n- Tham gia các khóa đào tạo tổng quan CNTT, đào tạo kiến thức liên quan tới hệ thống.Thực hiện các nhiệm vụ khác theo sự phân công của Lãnh đạo.\nYour skills and experience:\n- Tốt nghiệp cao đẳng trở lên các ngành Công nghệ thông tin, điện tử viễn thông, tài chính, ngân hàng, toán tin.\n- Có ít nhất 1 năm kinh nghiệm trong lĩnh vực vận hành, giám sát và xử lý sự cố hệ thống, ứng dụng và dịch vụ. Kinh nghiệm trong việc sử dụng các công cụ giám sát, phân tích log và cảnh báo để phát hiện và xử lý sự cố. Hiểu biết về các quy trình và phương pháp xử lý sự cố tiêu chuẩn như: khoanh vùng, cách ly, phục hồi, báo cáo sự cố. Kinh nghiệm trong việc phân tích nguyên nhân gốc rễ của sự cố và đề xuất các giải pháp khắc phục.\n- Có kỹ năng sử dụng các công cụ giám sát (monitoring tools) như Nagios, Zabbix, Prometheus để theo dõi tình trạng hoạt động của hệ thống, ứng dụng và dịch vụ. Có kỹ năng sử dụng các công cụ CLI (Command Line Interface) và GUI (Graphical User Interface) để thao tác và kiểm soát các hệ thống.\n- Biết sử dụng hệ điều hành Linux, Windows Server.\n- Kỹ năng giao tiếp, truyền đạt thông tin về tình trạng sự cố và các giải pháp khắc phục một cách rõ ràng, hiệu quả.\n- Biết cách phối hợp và làm việc nhóm với các bộ phận khác như kỹ thuật, phát triển ứng dụng, kiến trúc... để xử lý các sự cố phức tạp.\n- Khả năng làm việc hướng tới kết quả.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Gelex Tower, 52 Lê Đại Hành, phường Lê Đại Hành, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(502, 398, 2, 'Senior .NET Core Developer (ASP.NET, C#, English)', 'We are looking for a talented Senior .NET Core Developer to join our software development team. You will be responsible for building and maintaining high-quality backend applications, integrating with frontend systems, and ensuring optimal performance and security.\nOpen for Fresher and Mid-Senior Level Candidates to join our team.\n\nFor Fresher-level candidates, we provide a structured training and mentoring program, with opportunities to work on real projects and grow professionally.\n\n1. Technical Skills:\nExperience:  \nAt least 3–5 years of experience in software development using .NET Core/.NET Framework.\nPractical experience with .NET Core projects, API development, and integration with frontend or third-party systems.\n\nBackend Development:  \nProficient in C#, .NET Core, ASP.NET Core, Entity Framework Core, and related technologies.\nStrong understanding of Object-Oriented Programming (OOP), MVC pattern, and design patterns (e.g., Dependency Injection, Repository Pattern).\nSkilled in developing RESTful APIs, microservices architecture, and using tools such as Swagger and Postman.\n\nIntegration & Development:  \nExperience working with databases such as SQL Server, PostgreSQL, MySQL, or NoSQL databases (e.g., MongoDB, Redis).\nUnderstanding of the Software Development Life Cycle (SDLC), including architecture design, testing (unit & integration testing), and deployment (CI/CD).\nAbility to optimize application performance, ensure security (authentication/authorization), and handle complex technical issues.\n\nPreferred (Nice-to-Have):  \nExperience with frontend technologies such as Java, NodeJS, Angular, React, or Vue.js.\nKnowledge of cloud services (AWS, Azure, Google Cloud) or container technologies like Docker, Kubernetes.\n\n2. English Skills:\nProficient in English communication (both speaking and writing) to work with international teams and clients.\n\n3. Soft Skills & Responsibilities:  \nTeamwork:\nWork in Agile/Scrum environment, collaborate with Scrum Master and development teams.\nParticipate in product design, technical evaluations, and code reviews to ensure code quality.\n\nLeadership:\nAbility to lead small teams, mentor junior/mid-level developers, or take on Tech Lead responsibilities.\nProvide technical solutions, optimize development processes, and ensure non-functional requirements are met.\n\nProblem-Solving:\nCapable of analyzing, designing system architecture, and resolving complex technical problems.\nResearch and apply new technologies in projects.\n\n4. Education & Experience:  \nBachelor’s degree in Information Technology, Computer Science, Software Engineering, or related fields.\n3–5 years of experience working in tech companies, preferably with international or outsourcing projects.\n\n*** Application Requirements:  \nA detailed CV listing experience and completed projects.\nRelevant certificates (if any).\n\nWhy you\'ll love working here\nBenefits:\nWorking hours: 8:00 AM – 5:00 PM, Monday to Friday.\nFlexible working model: Mainly on-site, with remote work flexibility when needed (not a fully remote position).\nCompetitive Salary: 20 – 35 million VND/month.\nFull insurance in accordance with the law.\nPaid leave, 13th-month salary.\nTeam building activities, skill development training.\nProfessional and dynamic working environment with career growth opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '62 Đường số 6, KDC CityLand Park Hills, P 10, Go Vap, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(503, 195, 2, 'Senior Automation Engineer', 'ABOUT TIMO\n\nEverybody dreams of being rich(er) and fears being poor. Timo supports you in achieving this dream. Financially, we support across the 5 functions of money: moving, managing, accessing, growing, and protecting your money.\n\nBeing rich however means more than just having a lot of money. Enjoying a rich life includes making money more fun and emotional by embedding banking services into your lifestyle and within your social circle to unlock a truly rich life.\n\nA day in your life might include\n\nDesign, implement, and maintain scalable and reusable test automation frameworks using Robot Framework.\nCreate and manage automated test cases for UI, API, and integration testing.\nIntegrate automated tests into CI/CD pipelines using tools such as Jenkins, GitLab CI, or similar.\nLead code reviews and provide mentorship to junior automation engineers.\nCollaborate with developers, QA, and DevOps teams to identify and resolve defects and improve test coverage.\nAnalyze test results, generate reports, and log defects using tools like JIRA.\nContribute to the continuous improvement of testing processes, tools, and methodologies.\n\nYour skills and experience\n\nHow to succeed in this role:\n\nBachelor’s or Master’s degree in Computer Science, Engineering, or a related field.\n5+ years of experience in test automation, with at least 3 years focused on Robot Framework.\nStrong proficiency in Python, as Robot Framework uses Python-based libraries.\nExperience with SeleniumLibrary, API libraries (e.g., RequestsLibrary), and database validations.\nSolid understanding of software QA methodologies, tools, and processes.\nExperience with CI/CD tools (e.g., Jenkins, GitLab).\nHands-on experience with version control systems such as Git.\nExcellent problem-solving, analytical, and debugging skills.\nStrong communication and collaboration abilities.\n\nSound exciting? Get in touch today!\n\nWelcome talent from any background. We have seen talents with both banking and non-banking backgrounds able to shine and become key contributors. Timo is not just a bank!\n\nWhy you\'ll love working here\n\nOur deliverable is a leading software that is changing the way people do banking. You will be proud of your work and you will share with everybody that you helped to build Timo.\n\nYou’ll be joining a team of experts who are technically savvy, creative, and who share the intention of reinventing banking in Vietnam. You work closely with international architects and front-end consultants, product managers, and designers to develop the system. You will learn a lot from them.\n\nCompany Benefits:\n\nFull benefits and salary during probation\nPremium health care insurance\nCompetitive salary and learning culture\nOther benefits as per stated in Vietnamese Labor Law', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '412 Nguyen Thi Minh Khai, Ward 5, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(504, 238, 2, 'CVCC Kiến trúc Giải pháp DL- Data Solution Architect', 'Top 3 reasons to join us\n• Mức lương cạnh tranh, hấp dẫn\n• Môi trường làm việc chuyên nghiệp, thân thiện\n• Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n• Xây dựng và đóng góp ý kiến về quy trình, quy định liên quan đến kiến trúc và mô hình dữ liệu.\n• Đảm bảo các kiến trúc dữ liệu tuân thủ các tiêu chuẩn và kiến trúc phê duyệt của ngân hàng.\n• Nghiên cứu, đề xuất, quy hoạch và tư vấn các giải pháp dữ liệu nhằm đáp ứng yêu cầu phân tích dữ liệu và báo cáo.\n• Tiếp nhận, đánh giá, quy hoạch và tư vấn giải pháp cho các sản phẩm, dịch vụ dữ liệu từ các đơn vị nghiệp vụ.\n• Xây dựng sản phẩm/dịch vụ dữ liệu, đảm bảo đáp ứng đúng tiến độ và tiêu chuẩn chất lượng đã cam kết.\n\nYour skills and experience\n• Tốt nghiệp Đại học trở lên chuyên ngành Công nghệ Thông tin, Khoa học Máy tính, Toán tin, Hệ thống Thông tin hoặc các ngành liên quan.\n• Tối thiểu từ 5-7 năm kinh nghiệm trong lĩnh vực Data Architecture, Data Engineering hoặc các vị trí liên quan, thiết kế và triển khai kiến trúc dữ liệu, đặc biệt là trong các dự án chuyển đổi số hoặc nền tảng số của ngân hàng\n• Kinh nghiệm làm việc trên các Database Oracle, Postgres, MongoDB, Redis\n• Kinh nghiệm làm việc trên các Storage S3,HDFS\n• Có kinh nghiệm sử dụng công nghệ, công nghệ odi, datastage, spark, flink\n• Có kinh nghiệm làm việc trên các nền tảng Cloud\n• Có hiểu biết về các hệ thống ngân hàng\n\nWhy you\'ll love working here\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n• Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n• Du lịch nghỉ dưỡng hàng năm\n• Khám sức khỏe định kì\n• Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n• Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\nCơ hội nghề nghiệp và phát triển bản thân:\n• Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n• Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n• Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n• Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\nMôi trường làm việc lý tưởng với:\n• Những người cộng sự thân thiện và tài năng\n• Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(505, 399, 2, 'Junior Scrum Master/Agile Coach', 'Top 3 reasons to join us\n- Thu nhập 14-17 tháng lương/ năm\n- Thưởng tất cả các ngày Lễ tết\n- T2-T6, Giờ làm việc linh hoạt \n\nJob description\n1. Phối hợp lập kế hoạch Sprint\n- Tham gia Sprint Planning cùng Product Owner và Developers để xác định mục tiêu Sprint, lựa chọn User Stories, ước lượng độ phức tạp (Story Points) và xây dựng Sprint Backlog.\n- Đảm bảo Backlog luôn được tổ chức, ưu tiên rõ ràng và sẵn sàng cho Sprint tiếp theo.\n2. Điều phối các buổi Scrum Ceremonies\n- Chủ trì Daily Stand-up hằng ngày (15 phút): theo dõi tiến độ công việc, thu thập thông tin về vấn đề, ngăn chặn chậm trễ.\n- Tổ chức Sprint Review: trình bày kết quả đầu ra của Sprint với các bên liên quan, thu thập phản hồi để tối ưu sản phẩm.\n- Tổ chức Sprint Retrospective: phân tích kết quả Sprint vừa qua, tìm điểm nghẽn và đề xuất cải thiện cho Sprint kế tiếp.\n- Hỗ trợ Backlog Refinement (Grooming) để liên tục làm rõ và cập nhật User Stories.\n3.Loại bỏ trở ngại (Remove Impediments)\n- Hỗ trợ Developers trong việc giải quyết các vấn đề phát sinh (kỹ thuật, quy trình, phối hợp giữa các bộ phận…) kịp thời.\n- Liên hệ với các phòng ban liên quan (kiểm thử, hạ tầng, thiết kế, PO, v.v.) để thu thập thông tin và phối hợp xử lý.\n4.Bảo vệ nhóm trước những thay đổi ngoài kế hoạch\n- Ngăn chặn việc thêm yêu cầu đột ngột (scope creep) khi Sprint đang diễn ra, đảm bảo nhóm tập trung vào các mục tiêu đã cam kết. \n- Thông báo kịp thời cho Product Owner và các bên liên quan nếu cần điều chỉnh mục tiêu hoặc kế hoạch. Theo dõi và báo cáo tiến độ \n- Cập nhật và duy trì công cụ quản lý Sprint (Jira, Azure DevOps, Trello, v.v.), quản lý Sprint Board, Burn-down Chart. \n- Báo cáo tình hình tiến độ, chỉ số (velocity, cycle time, impediments) cho Product Owner, Project Manager và Ban Lãnh Đạo. Hỗ trợ Product Owner và Developers \n- Giúp Product Owner mô tả User Stories ngắn gọn, rõ ràng, đủ điều kiện (Definition of Ready).\n- Hướng dẫn nhóm phát triển thực hiện ước lượng (Planning Poker), xác định “Definition of Done” cho từng User Story. \n- Khuyến khích Developers tự tổ chức, chủ động đề xuất cải tiến quy trình, công cụ hoặc workflow. Đào tạo và chia sẻ kiến thức Agile/Scrum \n- Hỗ trợ, hướng dẫn thành viên mới hoặc các bộ phận khác trong công ty hiểu và tuân thủ quy trình Scrum. \n- Chia sẻ kinh nghiệm thực hành tốt (best practices) để nâng cao hiệu quả làm việc theo Agile.\n\nYour skills and experience\n- Từ 1 năm kinh nghiệm chính thức ở vị trí Scrum Master hoặc vai trò tương đương trong dự án phát triển phần mềm. \n- Nắm vững nguyên tắc, giá trị và khung làm việc Scrum (Scrum Guide); hiểu các artefacts (Product Backlog, Sprint Backlog, Increment) và ceremonies (Sprint Planning, Daily Scrum, Sprint Review, Sprint Retrospective). \n- Hiểu biết cơ bản về các chỉ số Agile (velocity, burn-down, cycle time, lead time) và khả năng sử dụng chúng để đánh giá, cải tiến quy trình. Kỹ năng công cụ o Sử dụng thành thạo một trong các công cụ quản lý Agile/Scrum phổ biến: Jira, Azure DevOps, Trello, ClickUp hoặc tương đương. \n- Biết cách cấu hình Board, Backlog, Sprint; tạo Báo cáo (Dashboard, Burn-down Chart, Cumulative Flow Diagram). \n- Kỹ năng sử dụng các công cụ giao tiếp và cộng tác: Confluence, Slack, Microsoft Teams, Zoom (hoặc Google Meet). Kỹ năng mềm \n- Facilitation: Khả năng dẫn dắt cuộc họp, khuyến khích mọi thành viên tham gia, đảm bảo cuộc họp đạt mục tiêu trong khung thời gian quy định. \n- Giao tiếp và lắng nghe: Truyền đạt thông tin rõ ràng với Product Owner, Developers, QA và các bên liên quan; lắng nghe, thấu hiểu nhu cầu, băn khoăn của từng thành viên để hỗ trợ kịp thời. \n- Giải quyết xung đột: Định hướng, khéo léo hòa giải khi có mâu thuẫn nội bộ hoặc giữa các bên.\n- Tư duy phản biện: Phân tích nguyên nhân gốc rễ (root cause) khi gặp vấn đề, đề xuất giải pháp cụ thể và khả thi. \n- Tinh thần tự tổ chức & chủ động cải tiến: Khích lệ nhóm chủ động tìm cách cải tiến quy trình, công cụ, cách làm việc.\n\nWhy you\'ll love working here\n- Lương từ 500$ - 1000$\n- Thưởng tất cả các ngày Lễ tết như Tết Dương lịch, Tết Âm lịch, 8/3, tết Trung thu, 2/9, Sinh nhật Công ty, 20/10, Men\'s day…\n- OT được hưởng lương.\n- 12 ngày nghỉ phép/năm. Sau 05 năm làm việc được tăng thêm 03 ngày phép.\n- Môi trường trẻ trung, hiện đại, được dẫn dắt bởi các quản lý là chuyên gia hàng đầu trong lĩnh vực Tài chính, Chứng khoán, Ngân hàng.\n- Được tham gia vào các dự án trên Web và App về các sản phẩm tài chính của Công ty\n- Bảo hiểm sức khỏe cá nhân chuyên biệt, khám sức khỏe hàng năm tại các cơ sở uy tín\n- Thời gian làm việc: 8h00 – 17h00 từ thứ 2 đến thứ 6.\n- Địa điểm: Tầng 16, tòa nhà Geleximco, 36 Hoàng Cầu, Ba Đình, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa Geleximco, 36 Hoàng Cầu, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(506, 400, 2, 'Caspeco - Sr Frontend Dev (ReactJS/Angular/TypeScript)', 'Caspeco is looking for a Senior Frontend Engineer to work in our beautiful office in HANOI, VIETNAM.\n\nCaspeco builds systems for the restaurant and experience industry. Our products consist of Booking, Cash Register, Staffing, and Analysis. The company today consists of around 150 employees serving 2500 customers in an organization where decision paths are short, every employee makes a difference, and new ideas and initiatives are rewarded.\n\nToday, Caspeco offers four complete systems for the hospitality and experience industry. We call them and together they can drive your entire business forward. We’ve packed our systems with features that we know make a difference; they save time, reduce the risk of mistakes, improve communication and increase margins both in terms of payroll and raw materials.\n\nWhat will you do?\n- Work closely together with UX and Product management in delivering top class customer experience.\n- Contribute and further develop our in-house UI component library.\n- Maintain high standards for code quality, system reliability, and security.\n- Present plans and solutions to both technical and non-technical stakeholders.\n- Contribute and support the team in improving our software practices and processes to help excel even further.\n\nYour skills and experience\nDesired skills and experience:\n- Extensive experience (+ 5 years) in front-end development using modern frameworks and languages such as React, Angular, and TypeScript.\n- Good understanding and hands-on experience with back-end development in C# and .NET Core.\n- Experience with Azure Cloud, including the deployment, management, and integration of cloud-based solutions.\n- Technical background with expertise in modern engineering practices.\n- Good understanding of system design principles and distributed architecture, helping you build scalable and reliable services\n- Excellent in verbal and written English.\n\nWhy you\'ll love working here\nYou will be:\n- Fast moving company with attractive tech stack.\n- Forward leaning company when coming to engineering principles and characterized by short decision paths and an open atmosphere, where we share experiences and collaborate closely with each other.\n- Your contribution with skills and expertise will be highly valued to help us reach our ambitions.\n\nWhat will you get?\n- You’ll get to work with experienced software engineers worldwide at a market leading, innovative Scandinavian SaaS company looking to accelerate growth.\n- Scandinavian Work Culture: creativity, innovation and work-life balance.\n- Competitive salary and 100% official salary during the probation period.\n- Annual review and 13th month salary.\n- Premium healthcare and accident insurance.\n- Wellness package supports employees to stay healthy and wealthy.\n- Exciting company outing/events and team building activities.\n- On-site and training opportunities in Nordic.\n- Modern working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 19, tòa nhà Peakview Tower, 36 Hoàng Cầu, Đống Đa, Hà Nội, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(507, 197, 2, 'Senior Backend Engineer - AGI (Python)', 'We are seeking a highly skilled and motivated Senior Developer to join our growing team, responsible for building and maintaining our calling platform. This platform is a mission-critical service that manages the routing of phone calls, schedules, and relays messages, and handles payment processing, making debt recovery more efficient. As a Senior Developer, you will play a vital role in designing, developing, deploying, and maintaining high-quality, scalable, and resilient systems. You will collaborate with a team of talented engineers to build and improve upon our existing microservices architecture, driving innovation and efficiency within our platform. Our current stack is heavily Python-based, utilizing frameworks like FastAPI and tools such as SQLAlchemy, Redis, Celery, and more. We are committed to expanding our technological horizons and are planning to incorporate more languages, particularly Golang, into our ecosystem to leverage its strengths in performance and concurrency, aligning with the practices of other teams within the company. In addition to backend services, we are also seeking engineers who can contribute to building dynamic and responsive user interfaces using modern front-end techniques.\n\nYour skills and experience:\n- Bachelor\'s degree in Computer Science, Engineering, or a related field, or equivalent experience.\n- 5+ years of professional experience in software development, with a proven track record of building and deploying production-ready applications.\n- Strong proficiency in either Python, Golang, Node.js or C# and their associated ecosystem.\n- Willingness to move to another if required. \n- Experience with relational databases (e.g., PostgreSQL) and NoSQL databases (e.g., Redis).\n- Solid understanding of software engineering principles, design patterns, and best practices.\n- Experience building and consuming RESTful APIs.\n- Familiarity with containerization (Docker) and orchestration (e.g., Kubernetes).\n- Experience with version control systems (e.g., Git).\n- Excellent problem-solving, analytical, and communication skills.\n\nDomain Expertise (You’re likely to be using one or more of these concepts described here for your day-to-day)\n- Experience in writing detailed technical specification and documentation. \n- Proven experience in optimizing database performance, including query optimization, indexing strategies, and schema design.\n- Experience with database profiling tools and techniques to identify and resolve database bottlenecks\n- Strong SQL skills, particularly with PostgreSQL (or similar).\n- Experience with domain driven design and test driven development\n- Familiarity with UDP, websockets, VoIP protocols (SIP, RTP, WebRTC) and their underlying mechanisms.\n- Familiarity with telephony signaling and media processing.\n- Familiarity with codecs, cloud telephony platforms, routing and their impact on call quality.\n- Familiarity with call routing, IVR systems, and call queuing.\n- Familiarity with concepts such as consistent hashing, lock free data structures and orchestration.\n\nWhy you\'ll love working here:\n- Competitive compensation package, including 13th-month salary and performance bonuses\n- Comprehensive health care coverage for you and your dependents\n- Generous leave policies, including annual leave, sick leave, and flexible work hours\n- Convenient central district 1 office location, next to a future metro station\n- Onsite lunch with multiple options, including vegetarian\n- Grab for work allowance and fully equipped workstations\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Havana Tower - 132 Ham Nghi, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(508, 186, 2, 'Technical Artist (Unity, Game)', 'Job description\n- Tối ưu hóa tài nguyên đồ họa \n- Thiết kế và viết Shader (Sử dụng Shader để tạo hiệu ứng hình ảnh đặc biệt (lửa, khói, nước, ánh sáng... và Tối ưu hóa shader để phù hợp với các nền tảng như mobile, PC, VR...)\n- Thiết lập pipeline nghệ thuật\n- Tạo hệ thống hiệu ứng hình ảnh (VFX) (Dùng Unity để tạo hiệu ứng như nổ, khói, ánh sáng, kỹ năng nhân vật...\n- Hỗ trợ Animation\n- Tạo tool tùy chỉnh trong Unity Editor để giúp các artist và designer làm việc hiệu quả hơn\n- Tối ưu hóa nội dung game cho từng nền tảng\nYour skills and experience\n- Bắt buộc có khả năng lập trình Shader cho Unity (có thể dùng ShaderLab thay thế)\n- Bắt buộc có hiểu biết sâu rộng về toàn bộ các công cụ dùng trong quy trình phát triển game\n- Có khả năng thiết lập ánh sáng (light rigging)\n- Bắt buộc có kỹ năng quản lý chất lượng và tối ưu hóa tài nguyên (asset)\n- Có thể thiết kế toàn bộ pipeline xử lý asset\n- Kinh nghiệm: Tối thiểu 10 năm (có thể cân nhắc từ 8 năm trở lên) \n- Nhận CV tiếng anh - tiếng Việt\nWhy you\'ll love working here\n✨ CHẾ ĐỘ PHÚC LỢI HẤP DẪN TẠI CÔNG TY ✨\nThu nhập cạnh tranh:\nMức lương hấp dẫn, thưởng tháng 13 và thưởng thâm niên.\nThưởng theo hiệu quả công việc, xét thưởng vào các dịp Lễ – Tết.\nĐánh giá tăng lương 1 lần/năm, trường hợp nổi bật sẽ được xét tăng lương ngay tại thời điểm.\nChế độ nghỉ phép:\n12 ngày nghỉ phép có lương mỗi năm theo quy định – nghỉ thoải mái, vẫn nhận lương đầy đủ.\nSự kiện nội bộ ấm áp:\nHàng năm tổ chức “Ngày hội gia đình” vào tháng 5, có quà tặng bằng tiền mặt dành tặng ông bà, cha mẹ, vợ/chồng và con cái của nhân viên – thể hiện sự trân trọng với cả gia đình bạn.\nChế độ quà tặng nhân dịp đặc biệt:\nTặng quà các ngày lễ: Tết Dương lịch, Tết Âm lịch, 30/4, Trung thu, 8/3, 20/10.\nCả nhân viên nam và nữ đều có quà.\nNhân viên chính thức trên 6 tháng được tặng quà sinh nhật trị giá 5 triệu đồng/người.\nThưởng hiệu suất riêng:\nNgoài lương chính còn có các khoản thưởng, bonus hàng tháng tùy theo đóng góp.\nHỗ trợ nơi ở:\nNhân viên ở xa được sắp xếp chỗ ở miễn phí, thuận tiện cho công việc.\nCơ hội học hỏi và phát triển:\nLàm việc cùng các chuyên gia hàng đầu trong nước và quốc tế.\nGiao lưu, học hỏi với đồng nghiệp quốc tế giúp cải thiện tiếng Anh và mở rộng tư duy toàn cầu.\nChăm sóc sức khỏe toàn diện:\nKhám sức khỏe định kỳ tại các bệnh viện quốc tế như BV Phương Đông.\nMiễn phí tiêm phòng HPV, cúm cho nhân viên.\nTrải nghiệm công tác và du lịch:\nCác chuyến công tác nước ngoài kết hợp du lịch, khám phá đặc sản và địa danh nổi tiếng.\nĐược tài trợ các hoạt động gắn kết team, học hỏi kiến thức lập trình qua các buổi giao lưu, workshop.\nVăn phòng hiện đại, tiện nghi:\nKhông gian làm việc rộng rãi, thoáng mát.\nCó bánh, trà, café phục vụ mỗi ngày.\nBữa trưa đầy đủ dinh dưỡng, ngon miệng dành riêng cho nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'B4-12 Vinhomes Gardenia Hàm Nghi, Đường Hàm Nghi, Phường Cầu Diễn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(509, 401, 2, 'Senior Front-end Developer (ReactJS,JavaScript)', 'Top 3 reasons to join us\n- Môi trường tốt, cơ hội học hỏi và thăng tiến\n- Sản phẩm chất lượng\n- Lương top market, thưởng cao\n\nJob description\n- Tham gia các cuộc họp đánh giá code và thiết kế kiến ​​trúc.\n- Sở hữu và thực hiện các tính năng end-to-end với Product Owner và Designer.\n- Đảm bảo rằng code của bạn đạt chất lượng và hiệu suất cao.\n- Phối hợp làm việc với các team khác và nội bộ team engineers.\n*Chi tiết sẽ trao đổi kỹ hơn khi phỏng vấn.\n\nYour skills and experience\n- Có tính kỷ luật, tinh thần đồng đội, hỗ trợ, tận tâm, cam kết cao.\n- Hơn 3 năm kinh nghiệm phát triển web với ReactJS.\n- Ưu tiên ứng viên có kinh nghiệm về Mobile hoặc Backend.\n- Hiểu và thực hành nguyên tắc SOLID + DRY để viết code rõ ràng và ngắn gọn.\n- Có khả năng giải thích các nguyên tắc cốt lõi và công nghệ frontend cho các kỹ sư khác.\n- Có khả năng nghiên cứu, giải thích và áp dụng công nghệ mới.\n- Giỏi các công nghệ front-end sau: Gabsby/NextJS/SSR, Mobx/Redux, ReactJS Lifecycle/React Hooks, Jest + React Testing Library, StyledComponent, LESS, Nrwl, Typescript, GraphQL.\n\nWhy you\'ll love working here\n- Lương top market\n- Lương tháng 13 + Performance bonus (1 năm/1 lần)\n- Xét tăng lương 1 năm/ 1 lần\n- Môi trường tốt, cơ hội học hỏi và thăng tiến rõ ràng\n- Lương: 30.000.000 - 50.000.000 VND/ tháng (Net)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '458/14 Ba Thang Hai Street, Ward 12, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(510, 356, 2, 'NodeJS Developer (Junior/Middle/Senior)', 'Top 3 reasons to join us:\n- Attractive salary, benefits, hybrid working\n- Technical training sessions (internal – external)\n- PVI Healthcare insurance\n\nJob description:\n- Work directly with US/EU clients to implement features of system\n- Assist with application architecture design and implementation.\n- Develop web services and unit test\n- Adhere to and recommend improvements to project coding standards.\n- Work in a team environment with shared code; disciplined use of source code control and process documentation.\n- Solve technical problems\n\nYour skills and experience:\nMUST-HAVE SKILLS:\n- Have experience in NestJS projects\n- ExpressJS, Restful API, Microservices, Serverless\n- Experience in MongoDB and one of relational databases MySQL, Postgresql\n- Architecture, algorithm knowledge\n- Good at verbal/non verbal English, able to work in an international environment\n- Good at analyzing & problem-solving skill\n\nWhy you\'ll love working here:\nCompetitive Salary and Brilliant Health Benefits:\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan\n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program\n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment:\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support.\n- Surrounded with friendly, open-minded, young and supportive colleagues\n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training:\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '17th Floor, 36 Tran Quoc Toan, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(511, 402, 2, 'Senior/Lead Data Scientist (Machine Learning, Python)', 'Top 3 reasons to join us\n- Big Data\n- Machine Learning\n- Big scale\n\nJob description\n- Leading and hand-on working with a team of Machine Learning Engineers and Data Scientists to deliver end-to-end ML products, from initiating ideas, building models, conducting A/B tests, to analyzing and productionizing the results;\n- Collaborating with Product and Business to shape new and existing products;\n- Collecting, cleaning, preparing data at large scale for modeling;\n- Adding new features, exploring new approaches to keep pushing the model performance;\n- Participating in productionizing Machine Learning models for live production;\n- Designing, conducting A/B tests and analyzing the results for experiment insights;\n- Building pipelines for continuously validating and updating models;\n- Working closely with software engineers to make the right trade-offs between model performance and engineering requirements;\n- Building frameworks and tooling to perform data science tasks easier;\n- Providing coaching and mentoring for team members, helping them to develop a successful career in Machine Learning and Data Science. Delivering timely feedback to help team members grow.\n\nYour skills and experience\n- 5+ years of hand-on industrial experience with Big Data and Machine Learning.\n- Strong understanding of mathematical foundations of Machine Learning algorithms.\n- Have practical experience in applying Machine Learning in Fintech\n- Have practical experience in applying Machine Learning in Fraud detection, Pricing, and Financial Services is a plus.\n- Have practical experience in applying Machine Learning in finance service is a plus.\n- Strong product ownership. You take a high responsibility for what you build. You keep a high bar for product quality.\n- Strong communication skills. This position requires working closely with business, product managers, and other stakeholders.\n- Being able to understand deeply what impacts the business, and drive the ML team to deliver those impacts are essential skills.\n- Experience in a managing or leading role is a plus.\n- If you are looking for a place to grow your career and impact millions of people, MoMo might be just the right place for you.\n\nWhy you\'ll love working here\nWe are passion with new technologies, not follow the old-track of outsourcing. We love our product and ready to sacrifice everything for it! You often argue with your boss? Don’t worry, here in M_Service, you will get salary increase if you win your boss in argument. We love objection!!! You hate company trip in hotel, resort? We only conquer difficult and hottest road in team building. Do you want to join?  \nWhat you will get:\n- Competitive compensation package.\n- Performance-based bonus.\n- Insurance package.\n- Chance to work with smart people with international experience.\n\nOur benefits:\n- Attractive compensation & benefits.\n- 13th month salary bonus and yearly performance bonus.\n- 15 paid days off per year\n- Premium health care insurance\n- Great allowances (lunch, parking, birthday, happy hours....)\n- Salary review  at least one time per year based on employee\'s performance and contribution.\n- Outing/team-building activities (company trip , soccer sport, english club, running club,..).\n- Other benefits as per stated in Vietnamese Labor Law\n- Work with experienced & strong team.\n- Friendly, dynamic & flexible working environments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor, Phu My Hung Tower, 08 Hoang Van Thai Str, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(512, 403, 2, 'Junior Fullstask Developer (ReactJS/ NodeJS)', 'Job description\n- Tham gia phát triển và vận hành hệ thống web platform\n- Frontend: Xây dựng giao diện bằng ReactJS + NextJS, tối ưu SEO và tốc độ tải trang (SSR/SSG).\n- Backend: Phát triển RESTful API bằng NodeJS + ExpressJS.\n- Database: Làm việc với MongoDB / MySQL.\n- Phối hợp với UI/UX, QA, tham gia vào quy trình phát triển phần mềm thực tế.\n- Hỗ trợ vận hành, fix bug, tối ưu hiệu suất và bảo mật.\n- Tham gia vào quá trình review code, viết tài liệu kỹ thuật.\n\nYour skills and experience\n- Có ít nhất 1 năm kinh nghiệm thực tế với ReactJS + NodeJS.\n- Có hiểu biết và đã sử dụng NextJS, hiểu các khái niệm SSR/CSR/SSG.\n- Làm việc tốt với REST API, Axios hoặc Fetch.\n- Biết sử dụng Git, GitHub.\n- Kỹ năng làm việc nhóm, tự học tốt, có trách nhiệm với công việc.\n\nWhy you\'ll love working here\n- Môi trường làm việc năng động\n- Được tham gia BHXH, BHYT, BHTN theo quy định pháp luật\n- Hỗ trợ cơm trưa tại văn phòng\n- Mức lương thỏa thuận: 8-12 triệu gross', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '60C Đ. Trường Sơn, Phường 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(513, 238, 2, 'Data Analysis and Fraud model', 'Chuyên viên Phân tích dữ liệu xây dựng mô hình nhận diện tội phạm công nghệ cao - Data Analysis and Fraud model\n\n- Nghiên cứu, áp dụng các kỹ thuật phân tích dữ liệu trong nhận diện tội phạm công nghệ cao: chân dung, hành vi đối tượng;\n- Nghiên cứu, xây dựng các Mô hình Machine Learning, Deep Learning, AI (Random Forest, XGboost, Neural Network, LSTM, LLM, ...) trong nhận diện tội phạm công nghệ cao;\n- Xây dựng Hệ thống nhận diện tội phạm công nghệ cao: Cybercrime Intelligence, Detection Kernel (Rules/Mô hình), ...;\n- Quản lý, kiểm định, vận hành, đánh giá, theo dõi và tối ưu các kịch bản/Mô hình đã triển khai;\n- Xây dựng các kịch bản để phát hiện gian lận.\n- Quản lý, theo dõi tính hiệu quả/phù hợp và cải tiến liên tục các kịch bản để phát hiện gian lận.\n- Tham gia đánh giá rủi ro, tư vấn giải pháp kiểm soát rủi ro gian lận với các quy trình, sản phẩm mới của Ngân hàng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(514, 305, 2, 'Leader QC Engineer (Automation)', 'Top 3 reasons to join us\n- Advance your career in the gaming industry\n- Take ownership and grow with global talents\n- Build games played by millions worldwide\n\nJob description\n- Collaborate with product managers, developers, and QC engineers to define test strategies, test plans, and automation scope.\n- Prioritize automation efforts based on risk, impact, and business value.\n- Design and implement end-to-end automation testing strategies for web, mobile, desktop, and API applications.\n- Develop and maintain scalable automation frameworks using tools like Selenium, Playwright, Appium, or REST-assured.\n- Ensure automation scripts are reliable, maintainable, and integrated into CI/CD pipelines (e.g., GitLab CI, Bitbucket, GitHub Actions, Jenkins).\n- Optimize test environments, data, and infrastructure to enhance efficiency.\n- Provide insights on automation coverage, execution results, and defect trends (e.g., Allure Report, Cucumber Report).\n- Drive best practices in test automation, including test-driven development (TDD) and behavior-driven development (BDD).\n- Stay up to date with emerging tools and technologies to improve automation efficiency.\n- Collaborate with cross-functional teams, demonstrating strong communication and problem-solving skills.\n\nYour skills and experience\nRequirements\n- 5+ years of experience in software testing, including 3+ years in automation. \n- Strong hands-on experience with test automation frameworks (Selenium, Playwright, Appium, REST-assured).\n- Proficiency in JavaScript, TypeScript, or Java.\n- Experience working with databases (MySQL, MongoDB, PostgreSQL, etc.).\n- Familiarity with CI/CD pipelines (Jenkins, GitLab CI, GitHub Actions, Bitbucket).\n- Knowledge of containerization (Docker) and cloud platforms (AWS, Azure, Google Cloud) is a plus.\n\nNice-to-Have\n- Experience with contract testing (e.g., Pact) or API mocking tools.\n- Familiarity with performance testing tools (e.g., k6, LoadRunner, JMeter).\n\nWhy you\'ll love working here\n- Competitive Package & Perks\n- Career Growth & Internal Mobility\n- Modern workspace & Unique Culture\n- Product-Driven, Cutting-Edge & Scalable Technology\n- Global Mindset & Regional Ambitions', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Z06 Đường số 13, Phường Tân Thuận Đông, Quận 7, Thành phố Hồ Chí Minh, Việt Nam, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(515, 227, 2, 'Senior Automation Test Engineer', 'Job description\nTesting and Quality Assurance:\n- Perform functional, integration, regression, and system testing for both frontend and backend systems.\n- Create and maintain detailed reports on testing progress, defects, and outcomes.\n- Review and refine test strategies to optimize quality and efficiency.\n- Ensure cross-browser, cross-platform, and device compatibility for applications.\n\nAutomation Testing:\n- Develop, implement, and maintain automated test scripts using tools like Cucumber, Serenity BDD, and Playwright.\n- Conduct API testing using tools such as Postman and performance testing with JMeter.\n- Collaborate with the DevOps team to integrate automated tests into CI/CD pipelines using Jenkins and Git.\n- Leverage programming skills in Java or JavaScript to enhance testing frameworks.\n\nCollaboration and Delivery:\n- Collaborate with BAs, developers, and product managers to understand requirements, provide input, and ensure alignment.\n- Act as a quality advocate, focusing on delivering features that meet user needs and maintain high standards.\n- Evaluate product readiness and release timelines based on test results and team discussions.\n\nLeadership and Influence:\n- Share quality-focused practices and promote a quality-first mindset within the team.\n- Mentor team members on testing techniques and workflows to enhance overall quality.\n- Ensure workflows and processes are followed consistently and improve them when necessary.\n\nContinuous Monitoring and Improvement:\n- Monitor product performance and user feedback in production environments to identify improvement areas.\n- Stay updated with industry trends, tools, and best practices to continually improve testing processes.\n- Drive initiatives to improve product quality, user satisfaction, and team productivity.\n\nYour skills and experience\nEducation: Bachelor\'s Degree in Information Technology, Computer Science, or a related field from a reputable university.\nExperience: Minimum of 5 years of experience as a Software Tester or QC Engineer, with significant exposure to automated testing.\nTechnical Skills:\n- Proficient in coding with the ability to learn and apply automation testing tools.\n- Deep understanding of APIs/Web-services and familiarity with testing tools such as Postman, BrowserStack, and curl.\n- Knowledge of Agile/Scrum methodologies and practices like TDD/BDD.\nTools and Documentation:\n- Proficient with Atlassian tools (Jira, Confluence) and mock-up tools (e.g., Figma, draw.io,..).\n- Ability to write Software Development Requirement Documents and Functional Specifications.\n- Experience with test automation frameworks (e.g., Playwright, Cucumber, cypress.io,..) is a plus.\nSoft Skills:\n- Excellent Problem-Solving skills and Critical Thinking.\n- Outstanding Communication and Documentation skills.\n- Ability to work collaboratively in a fast-paced, Agile environment.\n- Proactive and self-motivated with a strong sense of ownership.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi / New setup, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(516, 393, 2, 'Senior Consultant (Business Analyst, ERP, Odoo)', 'Overview:\nPortcities seeks a dynamic and experienced Senior Consultant to join our consulting team. We are looking for someone who can help us in driving the successful delivery of complex IT projects, offering strategic insights, and managing client relationships. With a minimum of 5 years of experience, the Senior Consultant leads project teams, ensures alignment with client goals, and contributes to business development efforts. This role requires a blend of technical expertise, business acumen, and leadership skills to deliver impactful solutions that meet clients\' needs.\n\nKey Responsibilities:\n- Analyze client business processes and requirements to design business solutions with detailed requirements. Produce Functional Specification, UAT plan, and prepare case tests, flowcharts, and diagrams.\n- Accompany customers in the full delivery cycle from software configuration to Go-live.\n- Internal testing on configuration/development should be conducted before releasing them for UAT.\n- Create a user manual and provide training and support to end-users as per the agreement defined.\n- Troubleshoot and resolve Odoo-related issues.\n- Collaborate with cross-functional teams for system integration.\n- Stay updated on Odoo developments and suggest improvements.\n- Support the sales team during pre-sales by creating and presenting a demo.\n- Prepare presentation slides in English or other specific language if required.\n- Prepare MoM in English or other specific language if required.\n- Able to manage and control budget, timeline, and scope of small-medium sized projects.\n- Develop and coach your subordinates.\n\nYour skills and experience\nRequirements:\n- Bachelor\'s degree in Information Systems / Computer Science / Business / Accounting / Management. A master\'s degree in business management is an advantage.\n- Minimum of 5 years of relevant experience in ERP implementation.\n- In-depth knowledge of VAS or VFRS is an advantage.\n- Good communication, presentation, and writing skills in English.\n- Strong knowledge of Odoo ERP system, including configuration and customization.\n- Knowledge of other ERP systems and business applications.\n- Language Skills: Vietnamese and English.\n\nPrefer:\n- Proven experience as an Odoo Consultant/ Python or similar role.\n- Experience in communicating across internal and external organizations.\n- Conceptual and analytical thinker – ability to extract, analyze, and document complex business and technical requirements/strategies.\n\nWork Arrangement:\n- Hybrid working arrangement: four days in the office and one day remote.\n\nWhy you\'ll love working here\nCompensation & Perks\nWe offer an attractive salary package, including a performance-based bonus. Your hard work and successful projects directly translate into your rewards.\n\nTeam Building & Events\nWe believe in creating a diverse and inclusive workplace culture that supports the growth and well-being of our team members both professionally and personally.\n\nCoaching & Mentoring\nOur comprehensive coaching and mentoring program empowers our staff for future success. We provide coaching sessions with documentation and practices to accelerate learning, refine skills, and navigate challenges.\n\nFlexible Working Hours\nAt Portcities, we understand that our team has diverse needs and responsibilities outside of work. We have flexible working hours, so you can better manage your schedule and find the optimal time for productivity.\n\nInternal Transfer Opportunities\nPortcities, with 12 branches worldwide, offers internal transfer opportunities, providing exposure to different regions and cultures and enhancing your career journey.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '10 Vinh Khanh Street, Ward 10, PLS Building (1st Floor), District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(517, 211, 2, 'DevOps Engineer', 'Job description\nAs a Devops/Senior DevOps, you will play a critical role in ensuring the reliability, scalability, and performance of our company\'s digital infrastructure and services. You will work closely with cross-functional teams, including software engineers, system administrators to design, build, and maintain highly available systems that can handle large-scale traffic and deliver exceptional user experiences.\n\nYour primary focus will be on automating operational tasks, optimizing system performance, and monitoring system health.\n\nResponsibilities:\nAutomation: Develop and maintain automation tools and frameworks to streamline operational processes and reduce manual intervention. Automate repetitive tasks and build self-healing systems.\nSystem Reliability: Monitor and maintain the reliability and availability of the company\'s digital infrastructure, including servers, networks, databases, and applications.\nIncident Management: Respond to and resolve incidents in a timely manner, ensuring minimal downtime and impact on users. Conduct post-incident analysis and implement preventive measures to avoid future incidents.\nPerformance Optimization: Identify system bottlenecks and performance issues, and work with development teams to optimize system performance and scalability.\nContinuous Monitoring: Implement monitoring solutions to track system health, performance, and availability. Proactively identify and resolve issues before they impact users.\nCapacity Planning: Collaborate with the infrastructure team to perform capacity planning and ensure that systems have sufficient resources to handle expected growth and traffic spikes.\nDeployment and Release Management: Develop and improve deployment and release processes to ensure smooth and error-free deployments. Implement canary releases and A/B testing strategies.\nCollaboration: Work closely with software engineering and DevOps teams to promote a culture of collaboration and shared responsibility for system reliability and performance.\nDocumentation: Create and maintain comprehensive documentation for system configurations, procedures, and troubleshooting guides.\n\nYour skills and experience\nRequirements:\nBachelor\'s degree in Computer Science, Information Technology, or a related field (or equivalent work experience).\nStrong knowledge of Linux/Unix systems and networking concepts.\nExperience with scripting languages (e.g., Bash, Python).\nExperience with infrastructure-as-code tools (e.g., Terraform) and configuration-as-code tools (e.g., Ansible)\nFamiliarity with containerization and orchestration technologies (e.g., Docker, Kubernetes, Rancher).\nHands-on experience with monitoring, logging and tracing tools (e.g., Victoriametrics Grafana, Otel, Signoz.).\nHave good mindset on DevOps culture.\nStrong problem-solving skills and the ability to analyze complex systems.\nExcellent communication and collaboration skills.\n\nWhy you\'ll love working here\nChứng khoán SSI nhận 3 giải thưởng nơi làm việc tốt nhất:\nHighly competitive remuneration package: Attractive monthly salary, 13th month salary, KPIs cash bonus, Public holiday cash bonus, Birthday gift, Lunar new year gift,...\nPremium AON healthcare insurane and full labor insurance\n12 days Annual leave + 2 days sick leave with full paid\nLuxury team-building trip and varied engagement activities\nJoining the leisure clubs: Football, E-Sport, Running, Gym, Yoga....\nFully sponsored training to build your career\nProfessional, open minded and supportive working enviroment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Luong Yen, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(518, 404, 2, 'Senior/Middle Front-end (ReactJS) Developer', 'ABOUT ESOFT\nEsoft is one of the world’s leading real-estate tech companies specializing in property presentations, image processing, 3D visualization, and online marketing of properties worldwide.\nOur customers are real estate agents and property-marketing companies in Europe, US, and Australia who rely on us for our fast service, our innovative solutions, and high and consistent quality. The company was founded in 2000 in Denmark and our platform in Vietnam has been operating since 2007. We currently employ more than 800 people in our offices in Vietnam, Denmark, Sweden, and Norway.\nTo learn more about our company’s business and culture, please visit our website.\n\nAt Esoft, we encourage all applicants from minorities, women, the people with disabilities and all other qualified applicants.\n\nTHE POSITION\nAs a Senior Frontend Developer at Esoft Systems, you will be responsible for designing, developing, and implementing user interface components using React. In this critical role, you will be the central decision-maker for all frontend technology choices, ensuring that our applications are robust, scalable, and user-friendly. You will collaborate closely with our backend developers, and product managers to deliver top-tier solutions.\n\nKEY RESPONSIBILITIES\nLead the design and development of complex web applications using React.\nMake critical decisions on frontend technology stack, frameworks, and tools to ensure optimal performance and maintainability.\nCollaborate with cross-functional teams to define, design, and deliver new features.\nOptimize applications for maximum speed and scalability.\nDevelop and enforce best practices for frontend development, including coding standards, testing, and documentation.\nStay up-to-date with the latest industry trends and technologies to ensure Esoft Systems remains at the forefront of frontend development.\n\nREQUIREMENTS\nFluent in verbal and written English\nEquivalent to at least 3-5 years of professional experience as a frontend developer, working with React.\nStrong experience with state management libraries (e.g., Redux, NgRx).\nProficient in modern build tools and package managers (e.g., Webpack, Babel, npm, yarn).\nFamiliarity with RESTful APIs and integration with backend services.\nExcellent problem-solving skills and attention to detail.\nStrong communication and collaboration skills.\nAbility to work in a fast-paced, agile environment.\n\nPREFERRED QUALIFICATIONS\nExperience with TypeScript.\nKnowledge of responsive design principles and mobile-first development.\nExperience with testing frameworks and tools (e.g., Jest, Cypress).\nPrevious experience in a leadership or mentoring role.\n\nMINDSET & ATTITUDE\nBe a team player, work toward the common goal of the team, is willing to support other colleagues\nEager to learn the new technologies\nHave good mindset, attitude & commitment\n\nWhy you\'ll love working here\nWe are a diverse crowd of doers and thinkers who work 24/7 from our offices in Denmark, Sweden and Vietnam, all of us towards the same goal – creating outstanding solutions and the best customer experience.\nOur purpose is to make it easier to market real estate. For nearly 20 years, we have worked passionately to help realtors all over the world by delivering reliably image solutions and great marketing tools.\nJoining us, you’ll have an opportunity to continue building your career in an international and successful company with market-leading, innovative solutions. In every business unit and in every office around the world, Esoft has always been driven by a strong team spirit and an even stronger sense of pride. We strive to provide an interesting workplace, where people work and interact across cultures and time zones. We cherish creativity and innovation, and we invest in training and development of employees.\nAlso, you will join a dynamic and international environment anchored in a strong company culture that encourages and fosters creativity, innovation, respect and equality. Our values - quality, credibility, openness, innovation, care, and passion – are based on a belief that we can make a difference – for each other and our clients. Our award-winning CSR policy and high employee ethics are proofs that we walk the talk.\n\nWHAT WE OFFER\nWe are looking to build a long-term relationship, and you will be part of a team that is in a very exciting development phase.\nWe offer a competitive salary and benefit package including an attractive incentive plan, other activities like: Team building, company trip, Year End Party…that fit the selected candidate’s experience and qualifications.\nAdditional benefits include 13th and 14th month salary as per regulations set forth in our staff manual. Insurance contributions as regulated by the law.\nBesides fully participate in SIUIHI, we offer private health insurance including family members as per regulations set forth in our staff manual; Annual health check as well as meals (co-sharing) consumed in the company’s canteen.\nTraining activities are carried out both at a corporate as well as individual level.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa Hàn Việt, 203 Minh Khai, Phường Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(519, 333, 2, 'CyberSecurity Solution Engineer (DevOps, NetSecOps)', 'Job description\n- Tư vấn và bán các sản phẩm, giải pháp liên quan đến An ninh mạng và Bảo mật:\n  - Kiểm thử bảo mật phần mềm và ứng dụng: SAST, SCA, IAST, DAST…\n  - Kiểm thử hạ tầng mạng, giám sát và an ninh mạng (SoC)\n  - Giải pháp thu thập thông tin trên không gian mạng (OSINT)\n  - Máy chủ hiệu năng cao (HPC) của các đối tác công nghệ hàng đầu như: BlackDuck (Hoa Kỳ), Picus (Hoa Kỳ), IriusRisk (Tây Ban Nha), Apposite (Hoa Kỳ), Niagara (Hoa Kỳ), Exxact (Hoa Kỳ),..\n- Phát triển thị trường và xây dựng và duy trì mối quan hệ với các khách hàng phụ trách.\n- Tìm hiểu nhu cầu tiềm năng và đề xuất giải pháp phù hợp cho khách hàng. Cập nhật thường xuyên các xu hướng công nghệ mới cho khách hàng.\n- Lập kế hoach kinh doanh, marketing. Phối hợp phòng marketing tổ chức hội thảo, demo, road show, tham gia các sự kiện giới thiệu giải pháp, sản phẩm.\n- Báo cáo công việc hằng ngày /tuần/ tháng cho cấp quản lý và Ban giám đốc theo quy định và/ hoặc khi có yêu cầu.\n- Được đào tạo sản phẩm, công nghệ do đối tác tổ chức để nâng cao kỹ năng chuyên môn và được cập nhật kiến thức công nghệ thường xuyên.\nYour skills and experience\n- Tốt nghiệp đại học trở lên chuyên ngành: Công nghệ thông tin, Khoa học Máy tính, An ninh Mạng, Bảo Mật, Điện tử viễn thông hoặc các ngành có liên quan.\n- Có ít nhất 1 hoặc 2 năm kinh nghiệm trong lĩnh vực CNTT. Có kinh nghiệm DevSecOps, NetSecOps… là một lợi thế.\n- Tiếng Anh: đọc hiểu và soạn thảo tài liệu kỹ thuật, có khả năng giao tiếp các nội dung kỹ thuật với chuyên gia nước ngoài.\n- Sử dụng thành thạo MS Office, đặc biệt là kỹ năng lập báo cáo PoC, đề xuất giải pháp kỹ thuật.\n- Có tính tổ chức, đáng tin cậy, năng động và tự tin. Tư duy tích cực và có trách nhiệm cao trong công việc.\nWhy you\'ll love working here\n- Mức lương thưởng hấp dẫn theo năng lực\n- Thưởng: Các ngày lễ như 30/4, 1/5, 2/9...; lương tháng 13, incentive\n- Được cấp máy tính xách tay, sim điện thoại trả sau và thẻ taxi Mai Linh, Grab (sử dụng khi làm việc ngoài văn phòng).\n- Được cấp thẻ cư dân Vinhomes GreenBay để tận hưởng mọi tiện ích cao cấp của KĐT\n- Được tham gia du lịch cùng Công ty hàng năm.\n- Được tham gia BHXH, BHYT, BHTN theo quy định của Luật Lao động Việt Nam.\n- Các trợ cấp khác: Theo Luật lao động Việt Nam, theo Nội quy lao động và Quy chế tài chính của Công ty.\n- Thời gian làm việc: sáng 8.00-17.00 từ thứ 2 đến thứ 6 và 2 buổi sáng thứ 7/ tháng\n- Địa điểm làm việc: Phòng 1701, Tòa G3, KĐT Vinhomes Green Bay, Số 7 Đại lộ Thăng Long, Mễ Trì, Nam Từ Liêm, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3, Tòa nhà SCETPA, 19A Cộng Hòa, Phường 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(520, 405, 2, 'AI Engineer (AWS, Python, Java, R, C++)', 'As an AI Data Engineer, you will play a crucial role in designing and building scalable data pipelines, infrastructure, and machine learning systems to support AI-driven projects. You will collaborate closely with AI Product Managers, Data Scientists, and Software Engineers to develop AI models and solutions tailored to business needs.\n\nYour key responsibilities will include:\n\n1. Data Pipeline Development: Designing, building, and maintaining scalable data transformation, ingestion, and storage pipelines to support AI and machine learning applications.\n2. AI Model Deployment: Collaborating with data scientists and AI engineers to deploy machine learning and AI models into production environments.\n3. Infrastructure Automation: Automating AI infrastructure to streamline development workflows for data scientists and AI engineers.\n4. Model Development & Integration: Assisting in building AI models from the ground up, transforming machine learning models into APIs, and integrating them with other systems for real-world applications.\n5. Statistical Analysis: Conducting statistical analysis to interpret model results and inform business decisions.\n6. AI Experimentation: Running experiments and tests for machine learning models and AI applications, ensuring optimal performance.\n7. Collaboration: Partnering with cross-functional teams, including electronics and robotics departments, to integrate AI solutions effectively.\n8. System Maintenance: Monitoring and retraining systems to ensure continuous improvement and alignment with evolving business goals.\n9. Stakeholder Communication: Translating complex AI outcomes into actionable insights for business users and stakeholders.\n10. Other tasks required by CTO/ CEO.\n\nYour skills and experience\n\nEducational Background:\n1. Bachelor’s or Master’s degree in Computer Science, Data Engineering, Artificial Intelligence, or a related field.\n\nTechnical Expertise:\n1. Extensive experience in building data pipelines and deploying AI/ML models into production environments.\n2. Proficiency in programming languages such as Python, Java, C++, or R.\n3. Strong knowledge of statistics, calculus, and probability for algorithm development and model evaluation.\n4. Hands-on experience with machine learning frameworks like TensorFlow, PyTorch, or Scikit-learn.\n\nCloud Experience:\n1. + 3 years of experience in deploying AI models, expertise in cloud services (e.g., AWS, Azure, or Google Cloud).\n2. Must hold a relevant cloud certification, such as AWS Certified Data Analytics, AWS Certified Machine Learning Specialty, or equivalent.\n\nAI Specializations:\n1. Familiarity with natural language processing, computer vision, and common AI model architectures.\n2. Experience in transforming AI models into APIs for integration with other systems.\n\nAdditional Skills:\n1. Solid understanding of data engineering practices, including ETL, feature engineering, and data preprocessing.\n2. Ability to work collaboratively in an agile and fast-paced environment.\n3. Strong problem-solving and communication skills.\n4. Demonstrated ability to run AI experiments and optimize performance through testing.\n\nPreferred Qualifications:\n1. Experience with robotics or electronics integration.\n2. A track record of contributing to end-to-end AI product development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '117 Nguyen Cuu Van, Ward 17, Binh Thanh District, Ho Chi Minh City, Viet Nam, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(521, 325, 2, 'Junior PM - Japanese&amp;English speaking (1 year contract)', 'Top 3 reasons to join us\n1. Cutting-edge technology in semiconductor design\n2. Competitive compensation and benefit package\n3. Young, dynamic, team-oriented working environment\n\nJob description\n- Support project management in the global enterprise applications (ERP, SCM, CRM, MDM etc.) implementation project\n- Support the Team with the organization of the Planning Ceremonies (Backlog grooming, Planning, Review & Retro, as well as daily stand-up)\n- Maintain the backlog, and ensure that JIRA is always updated by the team in order to reflect the reality of the ongoing operations.\n- Support the team to remove road-blockers, and be a facilitator for the day-to-day operations in execution, and support the team to respect the timeline.\n- Report to management when deadlines can’t be met, or when there are operational issues encountered in the team.\n\nYour skills and experience\n- Strong ability to communicate and written Japanese language and English is a MUST\n- Added advantage if candidate have below experience but not mandatory:\n- have an experience of taking project management, integration management and/or cross-functional team management in an enterprise applications project, preferrable in a large size and/or a global project.\n- have worked on a global project or in a global work environment.\n- Experience with Agile methodologies with enterprise-level application development projects.\n- Experience with manufacturing and supply chain technology projects.\n- Experience supporting an IT technical organization\n\nWhy you\'ll love working here\nRenesas Design Vietnam Company Limited aims to provide our employees with comprehensive compensation and benefit plans, and a professional working environment. Some featured benefits are:  \n- Competitive salary/bonus based on working performance.  \n- Excellent training program.  \n- Opportunity for promotion.  \n- Fair assessment.  \n- 24/24 hour insurance package including social and medical and unemployed insurance  \n- Dynamic people.  \n- Team-oriented environment.  \n- Sport activities and Annual company trip', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '31 Tan Thuan, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(522, 341, 2, 'Senior Devops Engineer, Upto 2000$', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, Thử việc 2 tháng 120% lương \n- Bảo hiểm full lương\n- Bảo hiểm sức khỏe\n\nJob description\n- Chịu trách nhiệm xây dựng, quản lý, vận hành toàn bộ cơ sở hạ tầng bao gồm toàn bộ các cloud services và server\n- Xây dựng chiến lược và triển khai các biện pháp bảo mật thông tin\n- Phát triển và triển khai các script và công cụ tự động giám sát, cảnh báo và quản trị các ứng dụng trên nền tảng cloud, đảm bảo phát hiện và phản hồi sớm các vấn đề về hệ thống và ứng dụng để đảm bảo tính sẵn sàng cao, tối ưu hiệu suất và chi phí\n- Phối hợp với đội dự án để thực hiện các công việc:\n  - Thiết kế, triển khai cài đặt các ứng dụng trên nền tảng cloud\n  - Thực hiện sao lưu và phục hồi dữ liệu định kỳ, đảm bảo khả năng phục hồi dữ liệu đầy đủ, chính xác và kịp thời của ứng dụng\n  - Triển khai các giải pháp load balancing, auto scaling, và auto recovering cho các dịch vụ phục vụ nhiều người dùng trên nền tảng Cloud\n  - Tự động hóa quy trình và phát triển giải pháp CI/CD, phục vụ triển khai, nâng cấp hoặc fix lỗi hệ thống\n- Thực hiện các công việc khác theo chỉ đạo của cấp trên\n\nYour skills and experience\n- Tốt nghiệp đại học chuyên ngành công nghệ thông tin hoặc điện tử viễn thông\n- Có tối thiểu 5 năm kinh nghiệm tại vị trí Devops Engineer hoặc tương đương\n- Có kinh nghiệm làm việc với các dịch vụ cloud như Azure, AWS,v.v...\n- Có kinh nghiệm làm việc liên quan đến các giao thức kết nối mạng và các cơ chế bảo mật\n- Có kinh nghiệm với Ansible và Terraform\n- Có kinh nghiệm sử dụng các công cụ giám sát và cảnh báo (ví dụ Prometheus và Grafana, EFK stack (Elasticsearch - Fluentd - Kibana))\n- Có kinh nghiệm làm việc với các hệ thống server Windows và Linux\n- Có hiểu biết về CI/CD sử dụng Jenkins, Docker\n- Biết lập trình ít nhất 1 trong các ngôn ngữ (ví dụ: Python, Go, Bash)\n\nWhy you\'ll love working here\n1. Lương và Phúc Lợi\n  - Rank lương upto 50M Gross\n  - Thời gian làm việc 5 ngày/ tuần, checkin linh hoạt từ 7h30 đến 8h30 (Nghỉ Thứ 7, Chủ Nhật). Nghỉ trưa 1 tiếng, từ 12h00 đến 13h00\n  - Thử việc 120% lương\n  - Tham gia đầy đủ Bảo hiểm tuân thủ theo Luật Lao động hiện hành (Đóng full lương)\n  - Bảo hiểm sức khỏe\n  - Hỗ trợ ăn trưa\n  - Khám sức khỏe định kỳ hàng năm\n  - Tối thiểu 13 tháng lương 1 năm, và các khoản thưởng vào các ngày lễ khác\n  - Thưởng giới thiệu ứng viên 20M – 40M/1 người tùy từng thời điểm\n  - Thưởng bằng cấp 5-20M/1 lần\n  - Thưởng lễ tết 1M/1 lần\n  - Tiền ma chay, hiếu hỉ 2M/1 người\n  - Đánh giá tăng lương 2 lần/năm\n  - Tham gia các sự kiện ngoại khóa, hoạt động Team Building, Workshop, tiệc sinh nhật hàng tháng,...Du lịch 1 lần/năm trong nước hoặc nước ngoài\n2. Cơ hội nghề nghiệp\n  - Làm việc, học hỏi và phát triển cùng đồng nghiệp là những kỹ sư trẻ tài năng, đam mê và có lý tưởng lớn\n  - Được tham gia các chương trình training về kỹ năng công nghệ và kỹ năng mềm, phương pháp làm việc\n  - Được tư vấn và chia sẻ về phát triển năng lực và nghề nghiệp bản thân\n  - Có nhiều cơ hội đi onsite làm việc tại Nhật \n3. Môi trường làm việc\n  - Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, công bằng\n  - Có cơ hội thăng tiến lên các vị trí Leader, quản lý\n  - Tinh thần làm việc nhóm tốt, hỗ trợ nhiệt tình từ đồng nghiệp\n  - Tham gia các khóa học training tiếng Nhật, kỹ năng mềm, kiến thức kỹ thuật\n  - Tham gia các Club Game, Bóng đá, Tiếng Nhật\n  - Có cơ hội làm việc và đào tạo tại Nhật Bản.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 23+26, Tòa nhà Handico Tower, Khu đô thị mới Mễ Trì Hạ, đường Phạm Hùng - Phường Mễ Trì - Quận Nam Từ Liêm - Hà Nội, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(523, 406, 2, '3 React Native Developers', 'We are seeking a talented and motivated React Native Developer to join our dynamic team. In this role, you build and maintain mobile applications for both iOS and Android platforms using React Native. You will work closely with designers and back-end developers to create high-quality, responsive, and performant applications that offer seamless user experiences.\n\nBesides, you will have opportunities to work with different mobile technologies like Flutter or building native modules.\n\nResponsibilities:\n- Develop and maintain mobile applications for iOS and Android using React Native.\n- Collaborate with cross-functional teams, including designers and backend developers, to define and implement application features.\n- Write clean, efficient, and reusable code.\n- Ensure responsive, intuitive applications perform well across various mobile devices.\n- Implement native modules and optimize performance for mobile platforms.\n- Integrate third-party APIs and services to enhance app functionality.\n- Troubleshoot and debug issues, ensuring smooth app performance.\n- Stay updated with the latest trends and technologies in mobile development.\n- Write automated tests and ensure the quality of the application codebase.\n- Maintain code quality, organization, and responsiveness.\n\nYour skills and experience:\n- React Native knowledge and mobile development relevant requirements are mandatory. Other points would be your advantages.\n- Bachelor\'s degree in Computer Science, Software Engineering, or a related field.\n- Proven experience as a React Native Developer or in a similar mobile development role.\n- Strong proficiency in React Native, JavaScript, and ES6+.\n- Experience with native mobile development (iOS/Android) and integrating native modules.\n- Familiarity with mobile development tools and IDEs (e.g., Xcode, Android Studio, VSCode).\n- Knowledge of version control systems such as Git.\n- Strong understanding of RESTful APIs and integrating them into mobile applications.\n- Experience with Redux for state management in React Native.\n- Familiarity with mobile app deployment and release processes for both iOS and Android.\n- Strong problem-solving skills and ability to work independently or as part of a team.\n- Excellent communication skills and attention to detail.\n- Experience with TypeScript and/or GraphQL.\n- Familiarity with testing libraries and tools (e.g., Jest, Mocha).\n- Knowledge of Firebase or other backend services.\n- Experience building apps with push notifications, location services, and camera functionality.\n- Familiarity with continuous integration (CI) and continuous delivery (CD) pipelines.\n\nWhy you\'ll love working here:\n- Working Shifts (From Mon to Fri)\nThis position requires candidates to be willing to change shifts depending on project requirements. The working shifts are in the following list:\n- Regularly: 8:30 AM - 6:00 PM (including 1.5 hours lunch break)\n- Or Afternoon - Evening: 2:00 PM - 11:00 PM (including 1hour dinner break and can add/subtract 1 hour depending on the season)\n\nWe offer the successful candidates benefits as follows:\n- iMac, MacBook Pro, and Laptop for all staff\n- iPhone, iPad, and Android testing devices are provided\n- Competitive salary\n- Company party\n- Annual health check\n- Annual company trip\n- Opportunities to work onsite (US, Canada, Hong Kong, Singapore, and other countries)\n- Health Insurance (In-patient and Out-patient)\n- Accident insurance 24/24\n- Good working conditions and environment\n- Professional development of technical and soft skills through day-to-day work and training sessions\n- The company’s labor policy is completely under Vietnamese labor legislation plus other benefits offered by the company (Company trips, Team building, etc.)\n- Birthday gifts\n- Sports clubs (football)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'HDWEBSOFT BUILDING 15 Thep Moi, Ward 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(524, 211, 2, 'Chuyên gia quản trị cơ sở dữ liệu (DBA Expert)', '1. Design And Implementation\n- Define the configuration for the database implementation within the organization. This shall include proper sizing and the detail requirement on parameters, file location, etc.\n- Determine and monitor the capacity and utilization of databases and corresponding hardware.\n- Determine the upgrade path for over utilized databases and corresponding hardware.\n- Verify the justification of the database requirement from vendors for their solution installing in the company.\n- Implement the design in professional manner.\n- Ensure zero data loss by proper backup/recovery mechanism design.\n- Ensure the database facilities operating and recovery within the agreed SLA.\n- Determine the best approach for system protection requirement such as load balancing, failover, remote site protection, etc.\n- Determine the risks in database facilities and the resolution to rectify the risks\n\n2. Operation Support\n- Perform any database cleansing ensuring the health working environment.\n- Implement ETL, clean up and transform external data to fit the desired format, efficiently importing large volumes of data extracted from multiple systems into a data warehouse environment.\n- Determine the effectiveness of the restoration for the database by the backup data.\n- Determine/define the mechanism for the monitoring of the performance & exceptions of the database facilities.\n- Determine/define the mechanism on detecting any issues happening in the database facilities in the campus.\n- Rectify the issues immediately if happening.\n- Perform user administrative activities on database level but not included user administration on application level.\n- Define/design the operation reports required to summaries the status of the database facilities for management. This shall include the utilization vs capacity, rate of availability, issues, etc.\n\n3. Security & Authentication\n- Determine potential weaknesses of the database software and the company’s overall system.\n- Determine how to protect the database facilities.\n- Implement best practices to minimize security risks.\n- Set up access policy according to the company’s role matrix to control who has access and what type of access they are allowed.\n- Set up audit policy.\n- Consult audit logs in the case of a security breach or irregularity.\n\n4. Documentation & Version Control\n- Document the design of the database facilities with the detail of diagram, system parameters and requirement, protection mechanism, and other related material as well as its historical changes becoming part of the IT Architecture Dossier.\n- Prepare the documents keep the latest and historical information of the facilities becoming part of the inventory control of the department.\n- Maintain the configuration document for each facility keeping the latest configuration parameter, historical changes on parameters in each device, and the method of changing the parameter becoming part of the\n- Configuration Control and Version Control within the department\n- Prepare the operation guide for each facility.\n\nYour skills and experience\n- University Degrees or above in IT, Computer Mathematics or related subjects.\n- At least 5 years as Database Administrator in companies in the field of banking, finance, telecommunications or equivalent.\n- Expert knowledge of Oracle Database (12c and higher) or Microsoft SQL Server Database (2016 and higher), is a must.\n- IBM DB2, PostgreSQL and MongoDB administrative experience is an advantage.\n- In-depth experience of databases running on Unix server.\n- Solid experience in supporting High Availability database environment: various operating systems, clustering, HA, event debugging and issue resolution.\n- Proficiency in using PLSQL (or T-SQL, PL/pgSQL ...) is a strong advantage.\n- Experience of database tuning and capacity planning is an advantage.\n- Experience with securities trading systems is an advantage.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Luong Yen, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(525, 407, 2, 'Kỹ sư cầu nối - BrSE', 'Với vai trò BrSE, bạn sẽ là cầu nối giữa các phòng ban liên quan tại công ty AZoom JP (tại Nhật) và đội ngũ kỹ sư phần mềm tại AZoom Vietnam (tại Việt Nam). Công việc cụ thể: - Tiến hành nghiên cứu, phân tích yêu cầu kinh doanh và đảm bảo các thành viên trong nhóm hiểu rõ nền tảng, mục tiêu và các vấn đề kinh doanh cần được giải quyết. - Tham gia vào cuộc họp với các phòng ban liên quan phía Nhật Bản, nắm chắc các yêu cầu và thiết kế hệ thống rồi truyền đạt cho đội dự án ở Việt Nam - Chia nhỏ các yêu cầu thành từng mục và kiểm soát thứ tự ưu tiên, trạng thái, kế hoạch hoàn thiện của các hạng mục đó - Quản lý dự án: lập kế hoạch, theo dõi, kiểm soát tiến độ thực hiện dự án, phối hợp, báo cáo với các bên liên quan trong việc quản lý dự án. - Hợp tác với các Managers/Leaders để giải quyết các vấn đề liên quan (vấn đề kĩ thuật, yêu cầu thay đổi, các vấn đề trong khâu vận hành, yêu cầu điều tra, yêu cầu của khách hàng) - Tạo tài liệu kỹ thuật liên quan\n\nYour skills and experience\n- Tiếng nhật tương đương N2 trở lên, thành thạo 4 kỹ năng nghe, nói, đọc, viết - Có ít nhất 02 năm kinh nghiệm BrSE/BA - Có kinh nghiệm phân tích nghiệp vụ dự án, phân tích yêu cầu - Có kinh nghiệm viết tài liệu liên quan đến kỹ thuật; quy trình - Trách nhiệm cao trong công việc - Kỹ năng làm việc độc lập cũng như làm việc nhóm tốt - Cẩn thận, tỉ mỉ, chi tiết trong công việc - Ưu tiên ứng viên có nền tảng kỹ thuật ngành CNTT\n\nWhy you\'ll love working here\n- Thử việc nhận full lương, đóng BHXH full lương - Thưởng tháng lương thứ 13 - Xét tăng lương 2 lần/năm - Các loại trợ cấp ăn trưa, tiếng Nhật lên đến 5 triệu đồng/tháng - Trợ cấp chức vụ (Leader) lên đến 6 triệu/tháng - Cấp Macbook kèm server riêng - Làm việc giờ hành chính, không có OT - Chế độ xin nghỉ - làm bù linh hoạt - Khám sức khỏe hàng năm tại bệnh viện uy tín - Du lịch hàng năm, team building hàng tháng - Free snack, coffee, tea - Các câu lạc bộ bóng đá, cầu lông - Môi trường thân thiện; cấu trúc phẳng, mọi ý kiến của nhân viên đều được lắng nghe và tiếp thu - Có lộ trình phát triển rõ ràng cho từng cá nhân - Hưởng đầy đủ các quyền lợi khác theo quy định chung của công ty và pháp luật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Handico Tower, Khu đô thị Mễ Trì Hạ, Phạm Hùng, Nam Tu Liem, Ha Noi; Tùng Lâm Tower, 35 Núi Thành, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(526, 408, 2, 'Fresh Full Stack Developer', 'We are seeking talented, fresh Full stack Developers to join our team, contribute to our initiatives, and stay abreast of the latest technological advancements. New engineers will undergo training and contribute to our projects, setting the foundation for a successful career in the software engineering industry.\n\nRole Description\n- Study project requirements, solution architecture, and current source code (if available).\n- Design, develop, and implement new features and functionalities for existing and new applications.\n- Investigate and diagnose software defects, identifying root causes and implementing effective fixes.\n\nYour skills and experience\n- Bachelor’s degree in computer science, software engineering, or related field.\n- Understanding of Object-Oriented Programming, Micro-services, Design Patterns, Clean Architecture, and SOLID programming principles.\n- Experience or familiarity with ReactJS for frontend development.\n- Experience or familiarity with .NET Core and C# for backend development.\n- Basic knowledge of SQL and database management concepts.\n- Understanding of RESTful APIs and web development principles.\n- Knowledge of version control systems (Git) is preferred.\n- Having experience in Azure Cloud development is a plus.\n- Good oral and written English communication is a plus.\n- Passion for full-stack development and learning new technologies.\n\nWhy you\'ll love working here\nWhy Join Us?\n- Competitive salary + performance bonus + 13th-month salary (pro-rata).\n- Full benefits during probation, including meal and parking allowances.\n- Generous leave policy: 16 annual leave days, including 11 Vietnam Holidays, 4 sick days, and 1 birthday leave.\n- Opportunities for growth: technical seminars, certifications, and career development.\n- Fun, collaborative culture with events like Hackathons and team-building activities.\n- Work-life balance with a 40-hour workweek (Mon-Fri).\n\nRecruitment Process\nWe follow a simple, transparent 3-step recruitment process:\n- Application Review: Submit your resume. Shortlisted candidates will be contacted within 5 business days.\n- Interview: A technical and behavioral interview (virtual or in-person) to assess your skills and cultural fit.\n- Final Decision: Feedback and offer rollout within 1-2 weeks after the interview.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà B1, UEH Campus B, 279 Nguyễn Tri Phương, Phường 5, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(527, 409, 2, 'Mid/Sr Data Engineer (MongoDB, Python)', 'Decentralab /di:\'sentrəlab/ is a high-quality Web3 Studio based in Da Nang. We focus on creating decentralized applications (dApps) on blockchain technology. Our goal is to empower innovation by providing the tools and expertise necessary to build and deploy decentralised applications that can disrupt traditional industries and create new business models.\nRole Overview: \nAs a Data Engineer at Decentralab, you’ll work closely with blockchain data, especially focusing on on-chain perpetual trading data. Your responsibility is to focus on data cleaning, enrichment, and transformation processes that turn raw blockchain data into valuable trading insights. Working with our MongoDB and Elasticsearch stack, you\'ll ensure our perpetual trading data is accurate, complete, and enriched with the context needed for meaningful market analysis..\nThis is an excellent opportunity for someone passionate about blockchain, trading markets, and data engineering to grow in a fast-paced but balanced work environment — no overtime expected.\nKey responsibilities: \nImplement robust data cleaning processes for on-chain perpetual trading data.\nDevelop data enrichment pipelines that add context and value to raw blockchain transactions.\nCreate transformation workflows that normalize and standardize trading data across different sources.\nDesign data quality checks and validation processes to ensure accuracy and reliability.\nIdentify patterns and anomalies in trading data to improve data quality.\nEnrich trading data with additional market context and metadata.\nCollaborate with backend engineers to ensure clean data integration.\nBuild feature extraction processes to support trading analytics.\nDocument data cleaning methodologies and enrichment techniques.\nYour skills and experience\nKey qualifications: \nOver 2 years of experience in data engineering with a focus on data cleaning and enrichment.\nStrong skills in data transformation, normalization, and standardization techniques.\nExperience with data quality assessment and improvement methodologies.\nProficiency working with MongoDB for data storage and transformation.\nExperience with Elasticsearch for enriched data indexing.\nKnowledge of ETL processes for complex data sources.\nExperience with data deduplication and reconciliation techniques.\nFamiliarity with metadata management and data enrichment sources.\nWorking knowledge of Python or similar languages for data manipulation.\nProblem-solving mindset with attention to data quality details.\nAbility to collaborate effectively with backend engineering teams.\nNice to have skills: \nUnderstanding of blockchain data structures and transaction formats.\nBasic understanding of perpetual trading markets is a plus.\nExperience working on blockchain projects or decentralized applications (dApps).\nExperience in financial trading (crypto, forex) is an advantage.\nIn-depth knowledge of microservices deployment technologies.\nAbility to work independently and collaborate effectively with cross-functional teams.\nWhy you\'ll love working here:\nTraining in on-chain perpetual trading markets and data structures.\nHands-on experience with data enrichment for blockchain trading data.\nCollaborative work environment with knowledgeable colleagues in the trading domain.\nBonus as a 13th Month Salary (depending on business performance).\nYearly SAAS allowance of up to $600 for productivity tools.\nPremium Healthcare Insurance.\nLunch Support.\nCompany trips, weekly happy hour.\nAnnual Health-check.\nErgonomic office desks and chairs.\nSnacks, drinks, and entertainment space with drums, billiards, ping pong, a football table, VR games, board games and more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '70 Phan Thanh, Thạc Gián, Thanh Khe, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(528, 410, 2, 'React Native Developer (JavaScript / TypeScript)', 'Phát triển và duy trì các ứng dụng mobile liên quan tới bất động sản, bản đồ, chat và đăng tin.\n* Tích hợp API từ backend (RESTful API).\n* Đề xuất các giải pháp kỹ thuật nhằm nâng cao hiệu quả và trải nghiệm người dùng.\n* Hỗ trợ và tham gia vào các dự án ReactJS nếu cần.\n\nYour skills and experience\n- Biết và đã dùng các công cụ AI như ChatGPT.\n- Tối thiểu 1 năm kinh nghiệm phát triển ứng dụng mobile bằng React Native.\n- Thành thạo JavaScript/TypeScript, làm việc với React Native CLI.\n- Có kinh nghiệm làm việc với Rematch, Reanimated, WebSocket, Map, RealmDB/SQLite.\n- Hiểu về native module (Android/iOS), push notification, Firebase, camera, location.\n- Có kinh nghiệm phát hành app trên App Store, Google Play.\n- Kỹ năng làm việc nhóm, tư duy logic và giải quyết vấn đề tốt.\n\nWhy you\'ll love working here\n1. Mức lương cứng 13-18 triệu/tháng tùy năng lực khi phỏng vấn\nLưu ý:\n- Mức lương có thể điều chỉnh dựa trên năng lực thực tế, đặc biệt là với ứng viên có kinh nghiệm Có thể làm việc với native module (Java,ObjectiveC,swift), Microservices, AWS, DevOps, CI/CD (Backend) hoặc biết ngôn ngữ native(Java,ObjectiveC,swift) để tăng hiệu năng, tối ưu codebase, có app trên Store.\n- Nếu ứng viên có thể kiêm nhiệm Fullstack (Backend+ Node.js + React Native), mức lương có thể tăng 10 - 20% so với mức trên.\n\n2. Thưởng hiệu suất (Performance Bonus): Hoàn thành công việc trước deadline thưởng 5-10% lương cứng/dự án\n- Điều kiện nhận thưởng\n- Code clean, ít bug, dễ maintain (được đánh giá qua code review).\n- Cải tiến mang lại tăng trưởng thực tế cho sản phẩm (có số liệu đo lường).\n- Đạt yêu cầu về hiệu suất & tối ưu tài nguyên (giảm crash rate, load nhanh hơn).\n\n3. Phụ cấp & Phúc lợi bổ sung\n- Khám sức khỏe định kỳ, BHXH đầy đủ\n- Du lịch hàng năm cùng công ty\n\n4. Thời gian và điều kiện làm việc\n- Thời gian làm việc: Thứ 2 đến thứ 7 hàng tuần, từ 8h đến 17h, nghỉ trưa từ 12h-13h30, nghỉ lễ tết theo nhà nước trừ khi trong giai đoạn chạy dự án.\n- Điều kiện làm việc: Làm việc tại văn phòng hiện đại, trang thiết bị đầy đủ (máy tính bàn, máy chiếu…)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '182 Phường Lê Lợi, Son Tay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(529, 411, 2, 'System Engineer - Hanoi', 'Top 3 reasons to join us\n- Attractive salary & benefits you\'ll love\n- Building large-scale products\n- Working in one of the best places to work in VN\n\nJob description\n- Hỗ trợ kỹ thuật Level 2 (technical support/onboarding) cho khách hàng sử dụng các dịch vụ VNGCloud (Kubernetes, Server, Storage, CDN).\n- Triển khai, cấu hình và xử lý sự cố liên quan đến Kubernetes, Server, VPN, Firewall, Load Balancer.\n- Hỗ trợ khách hàng migrate hệ thống từ on-premises lên VNGCloud.\n- Vận hành và tối ưu hạ tầng cloud để giảm chi phí và tăng hiệu suất cho khách hàng.\n- Quản trị hệ thống Linux, viết script tự động hóa và xử lý sự cố.\n- Giám sát hệ thống bằng các công cụ như Prometheus, Grafana hoặc tương tự.\n- Áp dụng các biện pháp bảo mật để bảo vệ hạ tầng và dữ liệu khách hàng.\n- Làm việc với đội ngũ phát triển để đưa ra các đề xuất tối ưu, cải tiến cho sản phẩm. Triển khai, tích hợp hệ thống ứng dụng tới khách hàng hiệu quả.\n- Có thể xây dựng pipeline CI/CD tích hợp với Kubernetes và các công cụ DevOps.\n\nYour skills and experience\n- 1-2 năm kinh nghiệm ở vị trí System tại các công ty ICT, SI, Hosting\n- Thành thạo Linux/Windows: Kinh nghiệm quản trị hệ thống trên các distro Linux (Ubuntu, CentOS), Windows; có khả năng viết một số script sử dụng shell, python...\n- Nắm vững kiến thức về networking, hypervisor (KVM), container (Docker), webserver (Nginx, Apache), VPN, và Load Balancer.\n- Hiểu biết và thực hành với các cơ sở dữ liệu như MySQL, MongoDB, và hệ thống ELK Stack.\n- Có kiến thức về Kubernetes, hoặc đã triển khai K8s trên môi trường on-premises hoặc cloud.\n- Chịu khó học hỏi và tự nghiên cứu, có kỹ năng phân tích, làm việc nhóm và giải quyết vấn đề nhanh chóng.\n\nWhy you\'ll love working here\nWe hope VNG is a place where you build your career. Whether you want to pursue to be a manager or focus on professional development, we acknowledge and appreciate your talents. Therefore, we open up to you more promotion opportunities in VNG, and designed program to help you succeed in every single career path.\n\nNO SUIT, NO TIE: At VNG, we do not have many rules because we respect you and want to make comfortable atmosphere to help employees perform their jobs well.\n\nCompany “pay” for you: Lunch, parking, swimming, learning English or gym for free and you know you are really in care.\n\nNO BARRIERS: Office of VNG is an open space because we always try to remove all barriers to help members easily shares with each other.\n\nBeing a big family: Like a gift for family day. A party for the kids. We know how much your family matters.\n\nNO RANK At VNG, members are encouraged to contribute ideas and debate with the others.\n\nBe explored: Ph.D., un-academic guy, bookish girl, fashion designers ... VNGers are different and this diversity makes life more colorful.\n\nNO "OFFICE": Office is like your home. You can hang paintings, plant trees, even feed aquarium on the desk.\n\nBe showed your best: VNGers like to "mortification" with the group games such as: Fansipan climbing, waterfall rafting, go over heat mats; there activities not only are tightening friendship, but also practice their bravery.\n\nGAMING: Even if you do not make the game, stealing beans in the boss’s garden or versusing with your colleagues in a sword competition play online is also an interesting way to relax.\n\nChanging the world: Creating an entertainment channel, building a social network and developing a game. On the Internet world, every single thing you did can change the lives of many people.\n\nLet’s join VNG to share our mission: \'MAKE THE INTERNET CHANGE VIETNAMESE LIVES\'', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phố Nguyễn Chí Thanh, Phường Láng Thượng, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(530, 354, 2, 'Senior Android Developer (Mini CTO)', 'Top 3 reasons to join us\n- Đãi ngộ đi cực kỳ hấp dẫn\n- Du lịch, teambuilding hàng quý cùng người thân\n- Cơ hội trao quyền để lead dự án\n\nJob description\n- Phát triển và tối ưu hóa ứng dụng Android\n- Tham gia vào quá trình trải nghiệm sản phẩm, đề xuất giải pháp sáng tạo để cải thiện trải nghiệm người dùng\n- Làm việc cùng đội phát triển dự án để bảo trì, sửa lỗi và cải tiến ứng dụng\n- Code review, đào tạo, phát triển kỹ năng cho các thành viên trong nhóm\n- Tự kiểm tra chất lượng sản phẩm trước khi Release\n- Báo cáo tiến độ và tình trạng công việc định kỳ\n- Hợp tác chặt chẽ với team product design và cải thiện giao diện người dùng dựa trên phản hồi thực tế\n- Nghiên cứu, lập kế hoạch và triển khai công nghệ mới trong phát triển ứng dụng\n\nYour skills and experience\n- Tối thiểu 3 năm kinh nghiệm phát triển ứng dụng Android bằng Kotlin\n- Thành thạo kiến thức lập trình Android: Activity, Fragment, Service, Database (Room), Networking (Retrofit)\n- Kinh nghiệm sử dụng các thành phần Android Jetpack: ViewModel, LiveData, Room, WorkManager, Compose\n- Hiểu biết và sử dụng được các design pattern (đặc biệt là MVVM)\n- Ưu tiên ứng viên có kiến thức về quảng cáo (AdMob, Google Ads) hoặc tích hợp giao dịch trong ứng dụng (IAP)\n\nKỹ năng\n- Giải quyết vấn đề\n- Giao tiếp, làm việc nhóm, lắng nghe và truyền đạt thông tin\n- Học hỏi và tự học tốt; tổ chức và quản lý thời gian\n\nTố chất\n- Đam mê công nghệ\n- Tự chủ và trách nhiệm\n- Kiên nhẫn và chịu áp lực tốt\n- Tư duy logic, tư duy hệ thống\n- Tỉ mỉ, cẩn thận\n\nWhy you\'ll love working here\n- Thử việc 2 tháng hưởng 100% lương chính thức.\n- Review lương, thưởng 2 lần/năm.\n- Trợ cấp tiền ăn trưa, gửi xe.\n- Thu nhập không giới hạn: Lương cứng + thưởng KPI, thưởng dự án, lương tháng 13, thưởng Tết,…\n- Khám sức khỏe định kỳ hàng năm.\n- Du lịch hàng năm, dã ngoại hàng quý 4 lần/năm, được hỗ trợ du lịch cùng người thân.\n- Hưởng đầy đủ các chế độ bảo hiểm theo quy định của nhà nước khi là nhân viên chính thức.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2 tháp A, tòa Rivera Park, 69 Vũ Trọng Phụng, Thanh Xuân, Hanoi, Vietnam, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(531, 201, 2, 'Solution Architect (Technical Owner)', 'We are looking for an innovative and experienced Solution/Technical Architect to lead the design and implementation of scalable, resilient, and secure architectures for our fintech platforms. This role plays a key part in shaping the technical vision and system blueprint for digital financial services at One Mount - VinID Pay. You will work closely with cross-functional teams to ensure that architecture decisions align with business goals, technological capabilities, and long-term scalability.\n\nBeing a member of One Mount - VinID Pay with target to become a leading Fintech company in Vietnam, we is building the most convenient online payment and finance service for customers:\n- Providing convenient and diversified payment/fintech solutions.\n- Building proactive and effective operating tools.\n- Developing platform for One Mount\'s digital financial ecosystem, which has been bringing thoroughness to customers & effective support for subsidiaries with breakthrough & quality products and taking that as a premise to reach\n\nResponsibilities\n- Design and maintain the overall architecture of applications and cloud infrastructure (microservices, event-driven, cloud-native).\n- Analyze functional and non-functional requirements to produce high-quality architecture and solution design documents.\n- Evaluate the business impact of technical decisions and ensure architecture supports product scalability, reliability, and security.\n- Lead system improvement initiatives by identifying technical debt and proposing architectural refactoring when needed.\n- Explore and introduce emerging technologies that improve developer productivity, system performance, or platform capabilities.\n- Align with stakeholders (Product, Business, Security, Engineering) to ensure shared understanding and buy-in on solution direction.\n- Guide and mentor development teams in applying best practices in software design, DDD, API design, and infrastructure usage.\n\nYour skills and experience\n- Bachelor’s degree in Computer Science, Software Engineering, or related fields; Master’s degree is a plus.\n- 7+ years of experience in software engineering and system architecture, preferably in fintech or digital platform environments.\n- Proven experience designing distributed systems using microservices and event-driven architecture.\n- Strong expertise in enterprise Java (Spring Boot, WebFlux), DDD, and reactive systems.\n- Solid experience with Google Cloud Platform (GKE, Pub/Sub, Cloud SQL, Firestore, etc.).\n- Experience with relational (PostgreSQL, MySQL) and NoSQL (MongoDB, Bigtable) databases.\n- Hands-on knowledge of CI/CD, container orchestration, infrastructure-as-code (Terraform, Helm), and observability tools.\n- Familiarity with fintech-related architecture concerns: real-time data, security standards (PCI-DSS, OAuth2, etc.), and compliance.\n\nMindset & Soft Skills\n- Strong collaboration and communication skills, able to work cross-functionally and influence stakeholders.\n- Agile mindset with a product-centric approach and continuous improvement attitude.\n- High ownership, strong problem-solving ability, and a customer-centric mindset.\n\nWhy you\'ll love working here\nBenefit and Perks\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check \n- Laptop, screen and other needed facilities/accounts/tools for work\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'relly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\nWorking Environment\n- Open & collaborative working space foster both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms, sleep corner.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tower 2 (T26) Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(532, 412, 2, 'Software Engineer (C++, C#)', '1. Hỗ trợ hiện trường và bảo trì phần mềm thiết bị bán dẫn:\n- Cài đặt, bảo trì và xử lý sự cố phần mềm thiết bị bán dẫn\n- Thu thập và phân tích yêu cầu từ khách hàng (VoC)\n- Thăm trực tiếp khách hàng trong và ngoài nước, hỗ trợ kỹ thuật (Toàn cầu: Mỹ, Đài Loan, Hàn Quốc, Nhật Bản)\n- Phân tích log phần mềm thiết bị bán dẫn\n\n2. Test chức năng phần mềm:\n- Viết và tiếp nhận các trường hợp test (Test Case)\n- Test mô phỏng\n- Viết báo cáo test và đưa ra các điểm cần cải tiến\n- Bảo trì phần mềm điều khiển thiết bị\n\n3. Phát triển chức năng phần mềm:\n- Phát triển và gỡ lỗi chức năng phần mềm theo đơn vị/khối\n- Phát triển driver truyền thông\n- Thiết kế và hiện thực giao diện người dùng (GUI)\n\nYour skills and experience\n- Từ 0 đến 5 năm lĩnh vực có liên quan, hoặc tốt nghiệp Đại học chuyên ngành\n- Am hiểu chương trình C++, C#\n- Tiếng Anh hoặc tiếng Hàn đọc hiểu trong công việc\n- Sẵn sàng tham gia đào tạo, công tác nước ngoài (Hàn, Mỹ, Nhật, Đài Loan,...)\n\nWhy you\'ll love working here\n- Thời gian làm việc: từ thứ 2 đến thứ 6 (5 ngày/ tuần)\n- Môi trường làm việc năng động, chuyên nghiệp, với nhiều cơ hội phát triển\n- Thử việc hưởng 100% lương, thường không phát sinh OT (nếu phát sinh sẽ chi trả theo Luật Lao động)\n- Team- building, company trip\n- Lương, thưởng, xét tăng lương hàng năm\n- Đào tạo nước tại Hàn Quốc và phụ cấp đào tạo', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 13, Tòa nhà Charvit Tower, 117 Trần Duy Hưng, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(533, 413, 2, 'Business Analyst (SQL, ERP)', 'Job description\nQuote & Sales Analysis\n- Review daily quotes to assess frequency and quote to sale conversion ratios.\n- Identify products with high quote activity but little or no sales.\n- Recommend adjustments to selling prices and pricing structures to improve competitiveness and profitability.\nPricing Strategy\n- Analyze and maintain selling prices for both outright sales and exchange programs.\n- Recommend price changes based on historical data, demand trends, and market conditions.\n- Review cost structures and suggest strategies for maximizing margins.\nMarket & Competitor Research\n- Gather and compare pricing data from suppliers, distributors, and online marketplaces.\n- Track trends in competitor pricing and availability to support informed decision making.\nSales Trend Monitoring\n- Monitor daily sales performance and flag items that are consistently selling out without price updates.\n- Recommend price increases or stock adjustments based on supply and demand dynamics.\nWork Order & Inventory Movement Review\n- Analyze completed work orders to understand part usage and reorder needs.\n- Provide recommendations on which items should be restocked based on movement and historical trends.\nLost Sales & No-Bid Review\n- Monitor unquoted or lost quote opportunities to determine which products should be considered for stocking.\n- Identify missed opportunities and provide recommendations to capture more business.\nSystem Management & Process Control\n- Implement warnings or system blocks to prevent quoting or invoicing of parts not available for resale.\n- Work with internal teams to ensure process integrity and data accuracy.\nYour skills and experience\n- 2+ years experience as a Business Analyst, Sales Analyst, or related role (preferably in manufacturing, distribution, or supply chain).\n- Strong Excel, SQL skills and experience with ERP systems.\n- Good written and verbal English proficiency\n- Solid understanding of pricing models, sales performance metrics, and inventory analysis.\n- Strong attention to detail and the ability to interpret and act on large sets of data.\n- Effective communicator with ability to work across departments.\nWhy you\'ll love working here\n- Salary: Negotiation \n- Full-time employee.\n- Pay salary bi-weekly (2 weeks/1 times)\n- Working from Monday to Friday (Sat & Sun off)\n- Transportation pick up from Hanoi to Noi Bai.\n- 13th-month salary, long-term service bonus\n- Full coverage insurance for the family: children and spouse\n- + Accident insurance 24/7 will cover the medical, treatment in hospital…\n- + Health insurance for the sick or disease treatment….\n- Others benefit Wedding, Funeral, Sick….\n- Traveling, teambuilding, heath check-up….', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lot. 24,25,26 Noibai Industrial Zone, Quang Tien, Soc Son, Soc Son, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(534, 275, 2, 'Automation Test Lead (QA QC / Tester)', 'Our Testers work with project teams to ensure software quality through systematic test planning, execution, and defect tracking, ensuring functionality, performance, and reliability of applications before deployment. With deep knowledge of various types of applications, databases, and operating systems, they maintain high standards of product excellence and user satisfaction.\n\nAs a Test Lead at Endava, you will be in charge of developing test strategy, test plan, and implementing automated tests to assure the quality of our software applications. You will take part in a specific project and work directly with our global stakeholders.\n\nResponsibilities:\n- Leading and managing a team of testers, ensuring effective testing strategies and test case execution.\n- Analyzing users stories, use cases and requirements, and collaborating closely with other team members.\n- Designing, developing, maintaining and extending automation scripts using various frameworks and programming languages.\n- Executing all levels of testing, detecting and tracking software defects and inconsistencies.\n- Managing client interaction.\n- Applying quality engineering principles throughout the Agile product life cycle.\n\nYour skills and experience:\n- 8+ working in testing experience within 4+ years of experience working in automation testing.\n- Strong knowledge of Software Development Life Cycle (SDLC), QA methodologies, tools, and processes.\n- Experience in creating comprehensive test strategy, test plan, test scenario, and test report.\n- Experience in building automation testing frameworks from scratch.\n- Experience in Web Services & API automated testing.\n- Experience in OOP and Java programming.\n- Basic knowledge in SQL query.\n- Quickly adapt to new technologies and acquire domain knowledge.\n- Strong analytical and problem-solving skills.\n- Excellent communication skills, both verbal and written.\n- Ability to work in a fast-paced, collaborative environment.\n\nNice to have:\n- Performance testing tools (e.g., JMeter) experience would be a plus.\n- Familiarity with CI/CD pipelines and integration with testing tools.\n- ISTQB CTFL Certification or equivalent quality assurance certification.\n\nWhy you\'ll love working here:\nAt Endava, we are offering opportunities and exciting development for our people to build an engaging technical community.\n\nSome of our benefits:\n- Competitive salary package, annual leave encashment, 13th month salary, referral bonus.\n- Career coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership.\n- Learning Opportunities: Complex projects, rotations, internal tech communities, training, coaching, online learning platforms subscriptions, English programme, certifications, pass-it-on sessions, workshops, conferences.\n- Work-Life Balance: Hybrid work and flexible working hours, employee assistance programme.\n- Health: Global internal wellbeing programme, access to wellbeing apps, premium health check, extra insurance.\n- Community: Global internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations.\n- Other: Trade Union benefits, Welcome package and gift-giving frequency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '9-11 Dong Da street, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(535, 182, 2, 'Middle/Senior Java API Engineer (Microservice, AWS)', 'About our Team:\nOur team is responsible for creating a brand of new digital financial platforms and apps that are highly reliable and scalable using modern engineering practices. You will be joining a project which talented software engineers in our Digital Bank Build team who is responsible for designing, building, and maintaining the new digital banking platform and the customer channels. As part of the team, you will be responsible for implementing software features, involve in technical designs, and writing tests to ensure the high-quality delivery of the product. The teams operate in Scrum and DevOps models.\nWe’re looking for top engineers out there! During the interview process, we will test your coding and design skills to assess your experience and depth of knowledge. Don’t worry our interview process will be fun!\nResponsibilities:\nAs a Java backend engineer, you will be working within a specific problem where you will design, develop, and deploy backend services with a focus on scalability, high availability, and low latency.\nDrive the efficient delivery of change through analysis, definition, and documentation of requirements whilst identifying potential solutions using agile delivery frameworks.\nSolve complex technical and business problems and learn new technology and frameworks.\nBe part of a team that will take full responsibility for the features you own.\nDesign, develop, test, deploy, monitor, and improve, you are responsible for the full life-cycle of your product – build it, own it.\nYour skills and experience\nYou will be a perfect match if your profile ticks some below items:\nMust-have:\nA pragmatic mindset.\nOutstanding problem-solving ability, eagerness to learn, and curiosity.\nA few years of software development experience with one or more general-purpose programming languages.\nStrong database and schema design for large-scale applications.\nAdaptable attitude and personality that is ready for continuous change.\nCollaboration and culture fit in the Agile experience will be an advantage.\nGood English skills.\nNice to have:\nExperience in developing distributed systems on top of micro-services architecture, event-driven architecture using Java, Spring and Spring boot, Kafka, Redis, etc. is a big plus\nExperience in AWS, Ansible, Packer, Docker, Rancher, and K8s is a big plus\nExperienced in automated testing frameworks is a plus\nGood English listening and speaking is a big plus\nExperience working in the banking and the financial domain is a plus\nWhy you\'ll love working here\nYou’ll love working with us if you are:\nPassionate about technology.\nIndependent but also a good team player.\nComfortable with a high degree of ambiguity.\nFocused on usability and speed.\nKeen on presenting your ideas to your peers and management.\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\nSome of our benefits:\nMeal and parking allowances are covered by the company.\nFull benefits and salary rank during probation.\nInsurances such as Vietnamese labor law and premium health care for you and your family.\nSMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\nValues-driven, international working environment, and agile culture.\nOverseas travel opportunities for training and work-related.\nInternal Hackathons and company events (team building, coffee run, etc.).\nPro-Rate and performance bonus.\n15-day annual + 3-day sick leave per year from the company.\nWork-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(536, 316, 2, 'Senior Java Backend Engineer', 'Top 3 reasons to join us:\n- Attractive salary package and valuable benefits\n- Get the opportunity to access global L&D programs\n- Hybrid and flexible working environment\n\nJob description\n\nBUSINESS TRAVEL CLUB\n\nThe HRS Business Travel Club (BTC) is the Business Unit managing and developing the HRS E-Commerce platforms of the well-known hotel portal businesses of HRS.de and HOTEL.DE that gradually transform into much more than “just” a platform. BTC provides its members, individual business travelers and SMEs, with a distinct range of exclusive services, which shape tomorrow´s upgraded travel experience. The goal of BTC is to deliver growth as well as sustainable profitability over time by enhancing customer loyalty between the brand and its customers, enabling the Brands Repositioning in the marketplace and unlocking additional potentials via optimized supplier management. Thus, BTC and its products, plays an important role in HRS´s DACH strategy as it revolves around a disruption of the interplay between hotel and workplace supply and e-commerce and a domination of the Business Travel DACH market. Your mission is to further develop and shape the "The HRS Business Travel Club" and its solutions and make it the next innovation of the HRS Group together with a great team.\n\nPOSITION\n\nWe are looking for an experienced Java Backend Developer (all genders) to join our global development teams to innovate and improve the business travel experience. You will play a key role in developing comprehensive software solutions for the HRS ecosystem. This includes hyper-personalized accommodation bookings, flexible workspace reservations and on-the-go payments as part of a product ecosystem that puts the customer first. The role requires expertise in Java backend development with a focus on creating robust, scalable solutions that support a dynamic, personalized travel experience and contribute to the company\'s vision of becoming the mobile travel companion for business travellers.\n\nCHALLENGE\n\nTogether with your team you take the customer view first and raise the bar in delivering business travel solutions:\n- Develop and execute resilient and scalable services tailored to enhance the operational efficiency and customer experience for millions of users\n- Collaborate across teams on high-level engineering concepts and practices\n- Work with product owners and other development team members to identify new features and user stories required for new/revised applications or large/complex development projects.\n- Promote high quality aimed at areas such as security, reliability, testability, and maintainability\n- Drive innovation by contributing new ideas for our processes, tools, and technologies\n\nYour skills and experience\n\nFOR THIS EXCITING MISSION YOU ARE EQUIPPED WITH...\n- 3+ years of proven hands-on Java Software Development experience \n- Strong knowledge of modern software engineering principles, patterns, and best practices. Understanding of micro-service and serverless architectures.\n- Experience designing and developing Restful APIs\n- Experience with cloud-native data stores and data processing systems\n- Experience in developing/deploying solutions to AWS Cloud\n- Experience with relational and non-relational data stores\n- Exposure to fault-tolerant, highly available distributed systems\n- Ability to work in a team, fast learning, and enthusiasm for the realization of innovative products\n- Fluency in English, spoken and written\n\nWhy you\'ll love working here\n- Open and flat environment, highly appreciate your idea and constantly supporting your skill development.\n- Innovative and international learning and development program, we dedicate to supporting employees’ growth and development of skills.\n- Challenging products with onsite opportunities in Europe (Germany, Australia, Poland, etc.)\n- Full salary and benefits as an official employee on probation.\n- 13th-month salary & short-term incentives: we offer incentives as defined by the company’s success in the previous year.\n- 15+ annual leaves per year.\n- Full healthcare compliance.\n- Premium healthcare for employees.\n- Gifts for every special occasion.\n- Supportive working conditions: Laptop, MS Surface Hub.\n- Free and unlimited snacks, tea, coffee, and by-choice request.\n- Premium company trip & business traveling programs and other exciting activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Anna building, Quang Trung software city, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(537, 353, 2, 'Data Engineering (Python, SQL, Oracle)', 'We are seeking a skilled and passionate data to join our Data team. The successful candidate will play a crucial role in designing, building, and managing our data systems, providing valuable insights to support strategic decision-making and drive business growth.\n\nResponsibilities:\n- Collaborate with the Data team to gather, collect, and synthesize data from various systems into the data warehouse\n- Design and implement data warehouse, data mart, and data dictionary architectures to meet business needs\n- Analyze data from multiple sources using advanced statistical and extract meaningful insights.\n- Develop and maintain comprehensive KPI reports to track business performance and inform decision-making.\n- Develop SBV reports\n- Partner with stakeholders across various departments, including business, sales, marketing, and IT, to gather requirements and communicate analysis results\n- Share data analysis knowledge and expertise with team members and conduct training sessions\n\nYour skills and experience\n\nSkills:\n- 2+ years of experience in data engineering, data operation, with a proven track record of success in large-scale and complex projects\n- Proficiency in data analysis programming languages such as PL/SQL, SQL, Python\n- Experience working with big data tools and platforms like Oracle, PostgreSQL, Spark.\n- In-depth knowledge of statistics, machine learning, and advanced data analysis techniques\n- Good at written and verbal communication skills\n- Strong collaboration and teamwork abilities\n- Creative problem-solving and critical thinking skills\n- Ability to learn quickly and adapt to new environments\n\nKnowledge:\n- Domain expertise in the finance, banking\n- Understanding of emerging data analysis trends and technologies\n- Bachelor\'s degree in Computer Science, University Of Science, or a related field\n\nBonus:\n- Experience with cloud platforms like AWS and Azure\n- Familiarity with Power BI\n- Understanding of financial concepts and banking products.\n\nWhy you\'ll love working here\nHDBank tạo cảm giác nơi làm việc như là một ngôi nhà thứ hai để bạn thỏa sức sáng tạo và đam mê.\n- Thưởng 13,14 \n- Thưởng theo xếp loại \n- Bảo hiểm y tế, bảo hiểm tai nạn \n- Du lịch nghỉ mát hằng năm \n- Tăng lượng dịnh kì', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(538, 414, 2, 'Senior Odoo Developer ( Python )', 'We are looking for a motivated Senior ERP Odoo Developer to join our ERP consulting firm. As a Senior ERP Odoo Developer, you will play a critical role in designing, developing, and deploying Odoo ERP solutions tailored to client needs. You will collaborate with cross-functional teams, lead technical discussions, and provide expertise in Odoo architecture and development. Your ability to analyze requirements, implement customizations, and optimize performance will be key to driving project success.\n\nResponsibilities\n\nOdoo ERP Development:\nArchitect, design, estimate, develop, and maintain Odoo customizations and modules follows business requirements.\nPerform FIT/GAP analysis of configurations using Odoo out-of-the-box against business requirements.\nPropose solutions, approaches to business problems, workflows,reports to be customized using Odoo.\nCollaborate on deployment and system configuration.\nCollaboration & Support:\nLead the technical aspects of Odoo projects, providing guidance to junior developers.\nCollaborate with consultants, and project managers to gather and understand business requirements.\nParticipate in architecture design and code reviews to ensure code quality.\nAssist in troubleshooting and fixing bugs in Odoo modules and installations.\nProvide technical support to clients post-deployment.\nIntegration & Migration:\nIntegrate Odoo with third-party applications (REST APIs, XML-RPC, JSON-RPC, MessageQueue, SQL, etc.).\nEnsure seamless data exchange between Odoo and external systems.\nSupport data migration tasks, including extraction, transformation, and loading (ETL) processes.\nPerformance Optimization:\nAssess, identify and troubleshoot performance issues in Odoo application.\nOptimize code and queries for enhanced performance and scalability.\nTesting & Documentation:\nWrite unit tests and participate in QA processes to ensure software quality.\nPrepare technical documentation for internal use and client delivery.\nStay up to date with the latest Odoo versions and recommend upgrades when necessary.\n\nYour skills and experience\nBachelor’s degree in Computer Science, Information Technology, or a related field (or equivalent work experience).\n3+ years of experience in Odoo development.\nExpertise in Python, JavaScript, HTML, CSS, and PostgreSQL.\nProven experience with Odoo\'s core modules (CRM, Sales, Accounting, Inventory, MRP, etc.) from Odoo 16 or newer versions.\nExperience with web services and integrations (REST APIs, XML-RPC, JSON-RPC, MessageQueue, SQL, etc.)\nStrong understanding of Odoo architecture, ORM, APIs, best practices of development and relevant business processes.\nLearning Agility: Ability and willingness to quickly learn and adapt to new technologies, frameworks, or programming languages as required.\nSoft Skills:\nStrong problem-solving skills and attention to detail.\nGood communication skills in English for interacting with both technical and non-technical stakeholders.\nAbility to lead and mentor junior developers.\nStrong client-facing skills with the ability to gather requirements and present technical solutions.\n\nWhy you\'ll love working here\nVery competitive salary commensurate with experience.\nComprehensive benefits package including:\nPrivate healthcare insurance (PTI) for you and your family\nSocial insurance with full salary\nTechnical and soft skills training and professional certifications supported (e.g. weekly English classes).\nFlexible working time (9:30 AM to 6:00 PM, Monday to Friday).\nAnnual leave & work from home up to 54 days/years + 1 more day after every 2-year.\nOpportunities for professional development and career advancement.\nOther employee benefits: sickness, birthday, International Women’s Day (March 8th), Vietnam Women’s Day (October 20th), Children\'s Day (June 1st), and family emergencies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'HAGL Building, 6th & 7th Floor, 3/1 Thanh Thai, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(539, 347, 2, 'Fullstack Developer (React + Supabase/PHP)', 'Top 3 reasons to join us\n- Có thể làm việc từ xa\n- Văn phòng mới! Trong công ty có góc cafe\n- Cơ hội thăng tiến cao\n\nJob description\n- Tham gia phát triển, bảo trì và tối ưu hóa các ứng dụng web sử dụng ReactJS, Next.js và Supabase.\n- Thiết kế và xây dựng giao diện người dùng hiện đại, chuẩn UI/UX, thân thiện với nhiều loại thiết bị.\n- Phát triển các tính năng sử dụng Supabase (PostgreSQL, Auth, Realtime...) kết hợp với React/Next.\n- Thực hiện các task được giao theo yêu cầu cụ thể của dự án, đảm bảo đúng tiến độ và chất lượng.\n- Phối hợp với các thành viên trong team để kiểm tra, sửa lỗi và hoàn thiện chức năng.\n- Làm việc theo mô hình labo, kỹ sư sẽ trở thành nhà phát triển chuyên trách của khách hàng, nhận chỉ thị và báo cáo trực tiếp với khách hàng Nhật Bản.\n\nYour skills and experience\nBẮT BUỘC:\n- Có kinh nghiệm làm việc với ReactJS và Next.js.\n- Có kinh nghiệm thực tế với Supabase hoặc hiểu biết rõ về các dịch vụ backend-as-a-service.\n- Thành thạo JavaScript (hoặc TypeScript), HTML, CSS.\n- Thành thạo Git, có kinh nghiệm làm việc theo quy trình Git (branching, pull request, conflict resolution…)\n- Có tư duy logic, khả năng tự học và giải quyết vấn đề độc lập.\n- Cẩn thận, chủ động trong công việc, có khả năng tự tìm hiểu và hoàn thành task được giao.\n- Có khả năng tạo tài liệu thiết kế tổng quát và chi tiết để trình bày cho khách hàng.\n\nƯU TIÊN\n- Ưu tiên ứng viên có kinh nghiệm làm việc trực tiếp với khách hàng Nhật hoặc từng làm việc trong mô hình labo.\n\nWhy you\'ll love working here\n- Thử việc FULL lương.\n- Thưởng lương tháng lương thứ 13.\n- Mức lương xứng đáng với năng lực của mình.\n- Xét tăng lương 2 lần/năm.\n- Hỗ trợ tiền trợ cấp giữ xe.\n- Sau khi làm việc một thời gian, có thể bàn bạc đăng ký làm việc theo hình thức WFH.\n- Tặng quà sinh nhật, tham gia tiệc theo quý.\n- Được đóng các khoản BHXH, BHYT, BHTN, KPCĐ theo quy định của pháp luật.\n- Kiểm tra sức khỏe định kỳ hàng năm.\n- Được đào tạo các kỹ năng cần thiết theo yêu cầu công việc.\n- Được làm việc trong môi trường chuyên nghiệp, năng động, cơ hội thăng tiến cao.\n- Snack …. FREE trong thời gian làm việc.\n- Du lịch công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'An Phu Plaza Building, 117-119 Ly Chinh Thang Street, Ward Vo Thi Sau, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(540, 415, 2, 'Tester (QA QC)', 'Job description\n- Đọc hiểu các tài liệu mô tả yêu cầu người dùng.\n- Thiết kế và thực hiện các trường hợp kiểm thử trên ứng dụng di động / web theo các thông số kỹ thuật.\n- Xác định các vấn đề về hệ thống / thiết kế và thực hiện các giải pháp.\n- Xây dựng chiến lược kiểm tra / kế hoạch kiểm tra.\n- Làm việc chặt chẽ với Lập trình viên.\n- Xây dựng kế hoạch công việc, báo cáo, đánh giá công việc của cá nhân, đóng góp các sáng kiến nâng cao chất lượng và năng suất công việc.\n\nYour skills and experience\nThái độ\n- Suy nghĩ tích cực, hòa đồng, vui vẻ\n- Cầu tiến, ham học hỏi, chăm chỉ\n- Cố gắng hoàn thành tốt công việc đúng deadline\n- Có tinh thần trách nhiệm cao\n- Chủ động đặt câu hỏi và tìm giải pháp trước khi làm\n\nYêu cầu chuyên môn\n- Ít nhất 1 năm kinh nghiệm\n- Có kinh nghiệm với Selenium, Appium là 1 điểm mạnh\n- Có kiến thức kỹ thuật tốt về phương pháp thiết kế và phát triển web\n- Có kinh nghiệm vẽ test plan, test case, ghi chú lỗi và báo cáo liên quan\n- Hiểu biết tốt về toàn bộ quá trình phát triển, bao gồm đặc điểm kỹ thuật, tài liệu và đảm bảo chất lượng\n- Khả năng quản lý nhiều nhiệm vụ được giao, chú ý đến từng chi tiết\n\nKỹ năng\n- Biết sử dụng các công cụ AI hỗ trợ công việc\n- Kỹ năng làm việc nhóm\n- Kỹ năng tư duy sáng tạo\n- Kỹ năng phân tích và giải quyết vấn đề \n\nWhy you\'ll love working here\n- Chế độ Bảo hiểm sức khoẻ PTI\n- Chế độ BHXH, BHYT, BHTN, nghỉ lễ, nghỉ phép (12 ngày/năm) theo luật lao động\n- Thưởng dự án theo doanh thu, thưởng Tết, lương tháng 13 và các phúc lợi hấp dẫn (Bảo hiểm sức khoẻ,…)\n- Thời gian làm việc năng động; môi trường làm việc trẻ trung, thoải mái; không gian làm việc rộng rãi, thoáng mát; được cung cấp các trang thiết bị hỗ trợ công việc.\n- Đồng nghiệp vui vẻ thân thiện, không ngừng chia sẻ và học hỏi tạo ra nhiều giá trị bền vững\n- Được đào tạo kiến thức và kỹ năng, phát triển kinh nghiệm bài bản\n- Được tài trợ các khóa học về chuyên môn\n- Lộ trình phát triển bản thân rõ ràng, tham gia đào tạo chuyên môn để nâng cao năng lực\n- Tham gia các hoạt động vui chơi giải trí, du lịch, team-building hàng năm, teabreak cuối tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '87 Street No. 1, Quarter 3, Phu Huu Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(541, 192, 2, 'AI Engineer (Machine Learning/ Deep Learning)', 'Job description\n- Thiết kế, phát triển và triển khai các mô hình AI/ML cho AI Chatbot, AI Co-pilot, Conversational AI, Virtual-agents.\n- Nghiên cứu và áp dụng các công nghệ AI mới nhất để cải thiện hiệu suất và chất lượng của sản phẩm; cũng như trải nghiệm khách hàng.\n- Làm việc chặt chẽ với team Product và Engineering để hiểu rõ yêu cầu sản phẩm và phát triển các giải pháp AI phù hợp.\n- Thực hiện các thử nghiệm và đánh giá mô hình để đảm bảo chất lượng trước khi triển khai.\n- Tích hợp các mô hình AI vào các sản phẩm và dịch vụ hiện có của công ty.\n- Nghiên cứu và phát triển các kỹ thuật AI mới nhất.\n- Tham gia vào việc viết tài liệu kỹ thuật và đào tạo các thành viên khác trong nhóm.\n- Thực hiện các công việc khác được lãnh đạo giao\n\nYour skills and experience\nYêu cầu chính:\n- Tốt nghiệp chuyên ngành CNTT hoặc các ngành liên quan CNTT,  Khoa học máy tính.\n- Có ít nhất 2-4 năm kinh nghiệm làm việc trong lĩnh vực AI/ML.\n- Có kiến thức chuyên môn về các mô hình học máy như Deep Learning, Reinforcement Learning, Natural Language Processing (NLP).\n- Có kinh nghiệm làm việc với các framework AI phổ biến như TensorFlow, PyTorch, Keras, etc.\n- Kỹ năng lập trình tốt bằng Python và hiểu biết về các thư viện liên quan đến AI như Numpy, Pandas, Scikit-learn, etc.\n- Kinh nghiệm với NLP và hiểu biết về các công nghệ Conversational AI là một lợi thế.\n- Thành thạo thêm Golang là một lợi thế\n\nKỹ năng:\n- Kỹ năng làm việc độc lập và làm việc nhóm.\n- Tinh thần cầu tiến, cởi mở và thích học hỏi. Tư duy sáng tạo và giải quyết vấn đề. Có tinh thần startup và tư duy sản phẩm.\n- Đề cao trách nhiệm trong công việc, ý thức chất lượng sản phẩm.\n- Kỹ năng xử lý tình huống tốt, cẩn thận, trách nhiệm cao trong công việc.\n- Không yêu cầu tiếng anh.\n- Ứng viên có kinh nghiệm phát triển product là một lợi thế.\n\nWhy you\'ll love working here\nMức lương:\n- Lương cứng: Deal theo năng lực + Thưởng tháng lương thứ 13\n- Thời gian làm việc: 8:30 – 18:00 từ Thứ Hai đến Thứ Sáu.\nCƠ HỘI VÀ THỬ THÁCH\n- Cơ hội được làm việc trong môi trường chuyên nghiệp, hiện đại và năng động. Thử sức với các Product hấp dẫn, thử thách đủ lớn với các ý tưởng đột phá.\n- Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng, trao quyền, cho phép bạn làm việc, sáng tạo theo cách riêng. Tài năng và thành tích của từng nhân viên được trân trọng, nhân viên xuất sắc được khen thưởng hàng năm.\n- Cơ hội phát triển năng lực, được hỗ trợ kèm cặp chuyên môn.\n\nCHÍNH SÁCH ĐÃI NGỘ\n- Review lương từ 1-2 lần/năm.\n- Có thưởng kinh doanh theo tình hình kinh doanh của công ty hằng năm\n- Cung cấp máy móc công cụ làm việc\n- Có cơ hội trở thành nhân sự Key của công ty và nhận được Cổ phần thưởng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 13 Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(542, 416, 2, 'Backend Engineer', 'Top 3 reasons to join us\n\nAttractive Compensation Package\nPremium Healthcare for You and Relatives\nHybrid Work Mode\n\nJob description\nAbout LINE VIETNAM\nOur products are focusing on online media business industry. Our mission is to bring people, information and services closer together by making use of AI Technology.\nWe also have many interesting projects specified for AI and Block-chains. You will have a great chance to:\nWorking in a very Silicon Valley start-up style with a professional, international environment. Developing your career in a famous product company and working with latest technologies in the world.\n\nYour skills and experience\nResponsibilities\nMaintain and Enhance Services:\nWork on the Marketing Platform built on Java and Spring Boot, utilizing MySQL, Redis, and Kafka.\nSupport the Contents Platform developed with Kotlin and Spring Boot, using MySQL and Kafka.\nDevelopment and Implementation:\nCollaborate with the planning team to develop new features and functionalities.\nIdentify and improve inefficient system operations to enhance performance and reliability.\nCode Quality and Collaboration:\nWrite and maintain comprehensive test codes to ensure software quality and reliability.\nParticipate in code reviews, providing and receiving constructive feedback.\nRequirements\n5 years of experience in backend development.\nProficiency in Java and Spring Boot frameworks.\nExperience with databases such as MySQL and messaging systems like Kafka.\nFamiliarity with Redis is a plus.\nFamiliarity with Kotlin is a plus.\nStrong understanding of writing and maintaining test codes.\nExcellent communication skills and a team-oriented mindset.\nAbility to critically analyze systems and propose improvements.\nEnglish speaking is must\nKindly be informed that by submitting your resume to this opportunity, you would agree to allow LINE Vietnam Co. Ltd. to store your personal information and document for recruitment purpose.\nYou can also request to delete your personal information by sending an email to us, at dl_devcareer\n\nWhy you\'ll love working here\nDynamic, Innovative and Friendly Working Environment.\nTop Attractive Salary.\nWorking with top professional experts with latest and challenging technologies for Line app and Line eco-system.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Building, 285 Cach Mang Thang Tam Street, Ward 12, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(543, 417, 2, '[Boomi] API Integration Engineer (JavaScript, Groovy)', 'About the Role\nWe are looking for a Boomi Integration Engineer to support our ongoing integration projects across enterprise systems. You will work closely with our in-house team to design, develop, and troubleshoot integration solutions using Dell Boomi AtomSphere. This is a remote, project-based role with the potential for extension based on performance and project pipeline.\nWorking hours: 9:00 AM – 6:00 PM, Monday to Friday\n\nYour skills and experience\nMust Have:\nProven experience with Dell Boomi AtomSphere (minimum 1 year).\nStrong knowledge of APIs (REST/SOAP), data formats (JSON, XML), and integration best practices.\nExperience integrating cloud and on-premise systems (e.g., NetSuite, Salesforce, SAP, Odoo, Workday).\nFamiliarity with error handling, scheduling, and Boomi process components.\nAbility to work independently and deliver on deadlines.\n\nNice to Have:\nBoomi Developer or Architect certification.\nExperience with other iPaaS platforms such as MuleSoft, Celigo, TIBCO, or WebMethods.\nExperience with Boomi Master Data Hub, EDI, or API Management.\nFamiliarity with scripting languages (JavaScript, Groovy).\n\nWhy you\'ll love working here\nWork on high-impact digital transformation projects.\nCollaborate with a global team of integration experts.\nAccess to certifications and continuous learning.\nCompetitive compensation and benefits.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '248/33/11 Nguyễn Thái Bình, Ward 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(544, 418, 2, 'Java Engineer (Spring Boot, SQL)', 'Phát triển phần mềm chủ yếu cho các khách hàng nước ngoài như Hàn Quốc, Mỹ,...;\nNghiên cứu, phát triển các công nghệ, giải pháp cho các sản phẩm của công ty: Phát triển phần mềm, đề xuất ứng dụng công nghệ mới, tích hợp hệ thống;\nTìm hiểu về công nghệ mới theo yêu cầu công việc;\nPhân tích, thiết kế hệ thông, làm tài liệu thiết kế chi tiết.\nThực hiện các nhiệm vụ khác theo sự phân công của Ban lãnh đạo\n\nTrình độ học vấn: Tốt nghiệp Đại học trở lên các chuyên ngành có liên quan\nChuyên môn:\nThành thạo lập trình Java, có kinh nghiệm tốt với Spring Boot\nKinh nghiệm với Hibernate là lợi thế\nCó hiểu biết về Restful Api.\nHiểu biết về lập trình hướng đối tượng, đa luồng\nLàm việc thành thạo với ít nhất một trong các CSDL dạng SQL và NoSQL\nSử dụng thành thạo Git hoặc các phần mềm tương tự\nSử dụng thành thạo với ít nhất 1 công cụ test API, vd: Postman\nCó kinh nghiệm phát triển dự án sử dụng JWT\nCó kinh nghiệm phát triển dự án theo mô hình MVC\nCó kinh nghiệm phát triển dự án sử dụng GRPC là một lợi thế.\nCó kiến thức về Strut là một lợi thế\nCó kiến thức về Time series DB như Apache Druid là một lợi thế.\nKhả năng tự học các ngôn ngữ công nghệ mới là một lợi thế lớn\nCó thể đọc và viết bằng tiếng Anh. Giao tiếp tốt là lợi thế\n\nKinh ngiệm:\nCó kinh nghiệm từ 3 năm liên tục phát triển phần mềm trở lên\nƯu tiên có kinh nghiệm ở các dự án lớn\n\nThu nhập thỏa thuận theo năng lực\nKhám sức khỏe định kỳ hàng năm\nDu lịch hàng năm\nCác chế độ khác theo quy định của Công ty', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khu đô thị Xa La, Phúc La, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(545, 419, 2, 'MES Engineer (ERP)', 'Job description\n- Cài đặt và cấu hình hệ thống MES, ERP\n- Giám sát và bảo trì hệ thống \n- Phân tích dữ liệu và báo cáo \n- Nghiên cứu và đào tạo người dùng về chức năng mới \n- Kiểm soát tồn kho giữa 2 hệ thống \n- Nghiên cứu và cải tiến hệ thống phù hợp với sản xuất và phòng ban liên quan\n\nYour skills and experience\n- Tốt nghiệp cao đẳng/đại học chuyên ngành CNTT\n- Có kinh nghiệm làm việc với hệ thống MES, ERP \n- Kỹ năng phân tích dữ liệu và báo cáo \n- Kỹ năng giao tiếp, khả năng làm việc độc lập và làm việc nhóm \n- Có hiểu biết về các thiết bị IT, cài đặt phần mềm, hệ thống mạng là một lợi thế \n- Chịu được áp lực cao \n- Tiếng Anh giao tiếp cơ bản(Tiếng Trung/ Hàn là lợi thế)\n- Có 2 năm kinh nghiệm với công việc tương \n- Có kinh nghiệm làm việc trong công ty sản xuất \n- Có kinh nghiệm với MS Office\n\nWhy you\'ll love working here\n- Bonus: Mức lương, thưởng cạnh tranh, phụ cấp chức vụ, phụ cấp xăng xe, phụ cấp con nhỏ,...\n- Healthcare Plan: Các chế độ BHXH, lương tăng ca theo quy định của nhà nước\n- Training: Cơ hội đào tạo nội bộ & ở nước ngoài và cơ hội phát triển sự nghiệp.\n- Team Activities: Được tham gia nhiều hoạt động ngoại khóa: Garden party, Workshop, Football, Badminton, Yoga,...\n- Canteen: Miễn phí đồng phục, đồ uống, ăn trưa, ăn tối (tùy theo thời gian làm việc),...\n- Others: Môi trường làm việc trẻ trung, năng động', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lô P-4, khu công nghiệp Tràng Duệ, xã An Hòa , Huyện An Dương , Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(546, 211, 2, 'Chuyên gia chính sách và tuân thủ An ninh thông tin-GRC', '• Thiết lập, chuẩn hóa, ban hành, triển khai, cập nhật và quản lý các văn bản chính sách, quy định, tiêu chuẩn, quy trình, hướng dẫn ATTT tuân theo yêu cầu của UBCK, ISO 27001,…\n• Giám sát, kiểm tra và đánh giá định kỳ mức độ tuân thủ các chính sách, quy định, tiêu chuẩn, quy trình ATTT đã ban hành đối với các hệ thống CNTT.\n• Tham gia nghiên cứu, đề xuất các biện pháp kiểm soát, giải pháp công nghệ tăng cường an toàn theo các khuyến nghị của tiêu chuẩn bảo mật, yêu cầu của pháp luật.\n• Xây dựng kiến trúc quy trình, quy định và triển khai xây dựng quy trình quy định quản lý dịch vụ CNTT theo ITIL\n• Lập chương trình kiểm soát tuân thủ chính sách an toàn thông tin và các quy định quản trị CNTT, bao gồm điều lệ kiểm soát, phạm vi kiểm soát, đồng thuận của các bên liên quan và cách thức thực hiện\n• Duy trì danh mục rủi ro thông tin của công ty và kiểm soát tiến độ/chất lượng của các biện pháp kiểm soát rủi ro\n• Tổ chức phối hợp với các bộ phận khác: xây dựng, phát triển và triển khai các chương trình đào tạo nhận thức và tuân thủ ATTT, đánh giá rủi ro dành cho công ty và khách hàng.\n• Phối hợp bộ phận Truyền thông thực hiện truyền thông định kỳ về tuân thủ và rủi ro ATTT.\n• Thực hiện các công việc khác theo phân công của Cấp quản lý trực tiếp.\n\n• Trình độ: Đại học trở lên ngành Công nghệ thông tin hoặc liên quan.\n• Ngoại ngữ: Đọc hiểu những thông tin, tài liệu bằng tiếng Anh.\n• Kinh nghiệm: Tối thiểu 05 năm kinh nghiệp làm việc tại vị trí tương đương.\n• Có kiến thức về: Quy trình/quy định/tuân thủ/quản lý rủi ro lĩnh vực CNTT, quy trình triển khai các hệ thống CNTT trong lĩnh vực tài chính/ngân hàng.\n• Có kiến thức, kinh nghiệm làm việc các tiêu chuẩn quốc tế ISO 27001, ITIL, COBIT, NIST và quy định ATTT trong ngành chứng khoán, Tài chính Ngân hàng.\n\n• Highly competitive remuneration package: Attractive monthly salary, 13th month salary, KPIs cash bonus, Public holiday cash bonus, Birthday gift, Lunar new year gift,...\n• Premium AON healthcare insurance and full labor insurance\n• 12 days Annual leave + 2 days sick leave with full paid\n• Luxury team-building trip and varied engagement activities\n• Joining the leisure clubs: Football, E-Sport, Running, Gym, Yoga....\n• Fully sponsored training to build your career\n• Professional, open minded and supportive working enviroment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Luong Yen, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(547, 182, 2, 'ITSM Engineering (Atlassian Ecosystem)', 'We’re looking for a passionate ITSM Engineer to join our growing digital banking team! You’ll play a key role in building, improving, and supporting IT Service Management (ITSM) solutions using the Atlassian Ecosystem (Jira Service Management, JIRA, Confluence, etc.). This is your chance to make a real impact by streamlining IT processes, enhancing collaboration, and ensuring smooth, efficient operations for our digital banking services.\n\nBuild and Configure ITSM Solutions: Use Atlassian tools to design ITSM workflows, service catalogs, and knowledge bases that fit our digital banking needs.\n\nImprove and Innovate: Identify opportunities to improve existing processes and implement solutions that enhance incident, problem, change, and service request management.\n\nBe the Atlassian Expert: Serve as the main point of contact for Jira Service Management, Jira, Confluence, Jira Product Discovery, ensuring it’s always running smoothly and meeting our needs.\n\nCollaborate with Teams: Work closely with engineers, security experts, and operations teams to integrate ITSM practices into our digital banking platform.\n\nStay Ahead: Keep up with new features in the Atlassian Ecosystem and ITSM best practices to help us continuously improve.\n\nYour skills and experience\n\nExperience with Atlassian Tools: Hands-on experience with Jira Service Management and Confluence.\n\nITIL Knowledge: Familiar with ITIL practices and frameworks.\n\nProblem Solver: Strong analytical and problem-solving skills.\n\nGreat Communicator: Able to explain complex ideas in a clear and simple way, working well with both technical and non-technical team members.\n\nBanking Bonus: Experience in digital banking or financial services is a plus, but not required.\n\nWhy you\'ll love working here: You’ll love working with us if you are:\n\nPassionate about technology.\nIndependent but also a good team player.\nComfortable with a high degree of ambiguity.\nFocused on usability and speed.\nKeen on presenting your ideas to your peers and management.\n\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\n\nSome of our benefits:\nMeal and parking allowances are covered by the company.\nFull benefits and salary rank during probation.\nInsurances such as Vietnamese labor law and premium health care for you and your family.\nSMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\nValues-driven, international working environment, and agile culture.\nOverseas travel opportunities for training and work-related.\nInternal Hackathons and company events (team building, coffee run, etc.).\nPro-Rate and performance bonus.\n15-day annual + 3-day sick leave per year from the company.\nWork-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower, Lumire Riverside, 277 Vo Nguyen Giap, An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(548, 233, 2, 'Senior System Software Engineer (Linux)', 'Job description\n- Design and implement system software for accelerating LLM inference, with a focus on PyTorch-based runtime environments\n- Develop high-throughput network software to support low-latency data transmission between compute nodes\n- Benchmark and analyze the performance of LLM inference and various AI/HPC workloads on target platforms\n- Design and optimize I/O scheduling strategies for efficient data movement\n- Manage and deploy software environments on Linux-based systems\n\nYour skills and experience\nCareer Qualifications\n- Solid understanding of computer architecture, operating systems, networking stacks\n- 2+ years of hands-on experience with programming in Linux environments\n- Experience with network communication protocols and systems-level network programming\nPreferred Qualifications\n- Experience with Linux kernel programming or contributing to open-source kernel modules\n- Good background in distributed computing and parallel programming models\n- Familiarity with deep learning and machine learning systems, especially those involving LLM fine-tuning and inference frameworks\n- Understanding of Retrieval-Augmented Generation (RAG) pipelines and their integration in LLM inference systems\nPreferred Character\n- Facilitating collaboration within and across teams to root-cause and debug issues\n- Good decision-making skill respecting team members’ opinions\n- Good communication skill to collaborate with HW/SW development teams in Korea\n\nWhy you\'ll love working here\n- Competitive salary based on experience and skills.\n- Professional working environment with a clear promotion roadmap.\n- Salary review and performance bonus every year.\n- Full social insurance, health insurance, and travel allowances.\n- Opportunities to work on advanced semiconductor projects with cutting-edge 5nm and 2nm technologies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3 Nguyen Luong Bang, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(549, 420, 2, 'Fullstack Dev (Python, NextJS, ReactJS, SQL)', 'About Epsilon Labs Vietnam\nEpsilon Labs VN, specializes in developing and implementing cutting-edge ERP and CRM solutions. We create innovative enterprise software solutions that help businesses streamline their operations and enhance customer relationships.\n\nPosition Overview\nWe are seeking an experienced Fullstack Developer to lead our development initiatives in building scalable microservices-based applications. The ideal candidate will have strong expertise in both Python backend development and modern frontend technologies, with a focus on building high-performance, distributed systems.\n\nKey Responsibilities\n- Architect and implement microservices-based solutions\n- Lead the design and development of high-performance APIs using FastAPI\n- Optimize application performance and implement caching strategies\n- Design and maintain database schemas and data models\n- Implement secure communication between distributed services\n- Ensure code quality and implementation of best practices\n\nYour skills and experience\nRequired Qualifications\n- Have at least 3+ years of professional software development experience\n- Proven experience with microservices architecture using FastAPI\n- Strong expertise in React.js and Next.js development\n- Track record of developing complex client portals and enterprise solutions\n- Deep understanding of async programming in Python\n- Experience with container orchestration and cloud deployments\n- Strong problem-solving and system design skills\n\nBackend Development\n- Strong expertise in Python-based microservices architecture\n- Extensive experience with FastAPI and its key features:\n  - Asynchronous programming using async/await\n  - API documentation using OpenAPI/Swagger\n  - High-performance request handling\n- Proficiency in database technologies:\n  - SQL: PostgreSQL, MySQL\n  - NoSQL: MongoDB, Redis\n- Experience with message queues and caching:\n  - CI/CD pipeline implementation (GitHub Actions/GitLab CI)\n\nFrontend Development\n- Advanced proficiency in React.js, Next.js, and TypeScript\n- Strong experience with modern frontend architectures and state management\n- Expertise in server-side rendering and static site generation with Next.js\n- Experience building complex client portals and dashboards\n\nWhy you\'ll love working here\nInterview Process: Our interview process consists of two rounds, Round 01 (Online) and Round 2 (Offline)\n\nWhat We Offer:\n- Competitive salary range: Up to 30 Mill VND\n- Opportunity to receive company tokens after 1 year of service\n- Health insurance coverage\n- Professional development opportunities\n- Modern work equipment\n\nLocation and Working Hour: \n- Location: Ward Thanh My Loi Thu Duc City, Ho Chi Minh City Vietnam\n- Working hours: Flexible working hours', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'phường Thạnh Mỹ Lợi , Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(550, 421, 2, 'Backend/Platform Engineer (Java or Golang, DevOps)', 'ABOUT US: Founded in 2014, GEEK Up is a strategic digital product partners of 100+ brands in Southeast Asia as TPBank, Heineken, SSI, Saint-Gobain, Waitrr, Funding Societies, Karzo, etc. Agile is our DNA. It is about how we think, how we approach problem, how we regularly retrospect our work, how we being transparent and communicate with every member in our teams. Every product and design decision from GEEK Up is based on empathy towards user experience in order to bring them the highest values.\n\nWe have a huge belief that local talents can definitely build products with global standards. You will be the one to place the stones building a product from vision and ideation, to implementation and running it live.\n\nMore about us:\n\nSCOPE OF WORK: As a core member of Backend Development team, you will coordinate with cross-function teams in 4 stages of product development including planning, implementation, deployment and operations\n\nUnderstand business logic & product requirements (including both functional and non-functional)\n\nArchitect product and core infrastructure with long term reliability, scalability, and security in mind\n\nPropose technical solutions to the problem, including but not limited to database design, flow diagram, sequence diagram\n\nBuild high performance, well-structured backend services, ensuring high-quality maintainable & testable code\n\nContinuously cross-check and review code within the team, ensuring that the final output is up to quality standard\n\nLearn new technologies, languages, and techniques so that you are able to adapt to the requirements of the project\n\nEngage in continuously deploying and scaling back-end services in both Cloud & On-premise Infrastructure as well as performance analysis, tuning and optimization\n\nPropose solutions and fixing problems encountered during development and operations\n\nYour skills and experience\n\nTo start your adventure at our Backend Development team, you should have:\n\nBachelor Degree in Computer Science or any related fields.\n\n5+ years of hands-on experience in Backend Development, with strong proficiency in at least one core programming language (e.g., Java, Golang, TypeScript...).\n\nExperienced in design backend architecture and system flows with an eye on scalability, security, and long-term reliability.\n\nConfidently propose and visualize technical approaches based on blur requirements, include but not limited to database schema, flow diagrams, sequence diagrams,…\n\nWrite clean, maintainable, testable code with high performance in mind.\n\nShow real curiosity for how data flows through systems, and how to model it well.\n\nExperienced in deployment backend services on both Cloud and On-premise infrastructure; familiar with CI/CD pipelines, service scaling, performance analysis, and optimization is a big plus.\n\nHands-on skills in Deployment and Monitoring using tools like Docker, Prometheus, Grafana, Git, etc.\n\nDisplay systematic thinking, solid critical-thinking, and problem-solving abilities.\n\nBe open to learning and adopting new technologies as needed.\n\nExperienced taken part in mentoring, knowledge-sharing, or played a role in building up technical capabilities in a team, is highly preferred.\n\nWhy you\'ll love working here\n\nFOR YOUR BETTER WORK\n\nYou will participate in the process of discovering, finding and proposing solutions, not just simply implementing the existing ones\n\nYou can seize the opportunity to continually receive constructive feedback and suggestions, so you can easier realize what you have done well and what needs to be improved\n\nThere are team members sharing lessons learned, so each and everyone can keep building up knowledge and experience\n\nFOR YOUR BETTER GROW\n\nOur flat structure with no middle management enables you to leverage your own strengths, and make room for you to grow yourself in whatever aspect you desire.\n\nThere are weekly workshops and sharings, where we exchange our knowledge and experience, from technical to soft skills, from work to daily life subjects\n\nWe embrace the eagerness of learning and sharing, so you will always have room to raise your own voice\n\nFOR YOUR BETTER STAY\n\nThe flat structure will also enable you to choose your own career path and there will be a broad range of career opportunities available on your adventure at GEEK Up\n\nThese perks will equip you with a clear mind and a healthy body: Weekly exercise with your teammates; morning coffee with free drinks; fruits, and nutritious drinks in our shared kitchen with a well-stocked fridge\n\nYou can also enjoy team-building, retreats and other customized quarterly events with other team members.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(551, 422, 2, 'Python Developer (Flask, MongoDB, Redis)', 'We are looking for a self-motivated and experienced Python Developer to join our growing team. As part of our backend engineering team, you will be responsible for building and maintaining scalable APIs and data systems that power our applications. You will work closely with cross-functional teams to ensure our backend infrastructure is robust, efficient, and reliable.\n\nResponsibilities\n- Design, develop, and maintain APIs using Python and Flask. Manage and optimize MongoDB databases and Redis sessions.\n- Write clean, efficient, and well-documented code following best practices. Collaborate with other team members in code reviews, testing, and deployments.\n- Troubleshoot and resolve issues in development, testing, and production environments.\n- Participate in architectural discussions and contribute to technical decisions. Take initiative and ownership of assigned tasks, and follow through with minimal supervision.\n- Ensure high levels of accuracy and reliability in data handling and processing.\n\nYour skills and experience\nMinimum Qualifications\n- 1+ years of hands-on experience with:\n  - Python & Flask\n  - MongoDB \n  - Redis\n- Strong attention to detail and organizational skills.\n- Excellent problem-solving skills and ability to think critically.\n- Capable of working independently and managing your own workload. Strong communication skills and ability to collaborate effectively in a team environment.\n- Solid understanding of software development best practices, design patterns, and software architecture.\n- Good time management and task prioritization skills.\n\nNice to Have\n- Experience with Docker for containerizing applications.\n- Familiarity with GitLab CI/CD pipelines.\n- Experience working with PostgreSQL.\n- Exposure to ReactJS or other frontend frameworks.\n\nTech Stack\n- Version Control & CI/CD: GitLab \n  - Containerization: Docker\n- Backend: Python (Flask) \n  - Database: MongoDB \n  - Session Store: Redis\n- Frontend (optional): ReactJS\n\nWhy you\'ll love working here\n- Bảo hiểm xã hội, bảo hiểm y tế, đóng thuế TNCN theo luật Lao Động.\n- 12 ngày nghỉ phép năm có lương\n- Company trip, môi trường làm việc startup năng động, cởi mở.\n- Lương tháng 13, tùy theo tình hình kinh doanh của công ty có thể thưởng thêm.\n- Việc đồng hành xây dựng những viên gạch đầu tiên của công ty startup sẽ có nhiều đãi ngộ thăng tiến đi cùng sự phát triển của công ty hơn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thủ Dầu Một gần Thủ Đức, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(552, 423, 2, 'Senior Java Software Engineer (working in Singapore)', 'About the Role: We are seeking a highly skilled and experienced Senior Java Software Engineer to join our dynamic team working Permanent in Singapore. Description: Work together with project team to design and implement quality solutions as per customers’ requirements. Debugging and resolving technical problems that arise. Participate in solutioning meetings with project team and customers. Responsible to deliver high quality codes for implementations. Being a mentor for junior Software Engineers.\nYour skills and experience Requirements: Bachelor’s degree in Computer Science or equivalent. Technical Requirements: At least 6 years of strong hands-on experience with Java and Spring stack. Working knowledge of Web API, REST, XML, JSON. Hands-on experience in UI/UX development using JSP, HTML5, CSS3, JavaScript. Able to define solution and prepare technical specifications according to Functional Specifications.\nInterpersonal Requirements: Excellent written and verbal reasoning and communication skills. Excellent problem-solving skills with high level of initiative. Meticulous, detailed and able to work with minimal supervision. Ability to work under pressure and meeting tight deadlines. Ability to lead technical solutions end to end.\nAdded Advantage: Complete minimum 3 Software Development Life Cycle (SDLC). Experience in Banking Solution development will be an advantage. Experience in UNIX environments, systems setup and application deployment will be an advantage. Experience working in a cross cultural team with multi geographical locations (onsite-offshore) will be an advantage. Advantage if worked on Agile Framework or aware of basic Agile terminologies and processes. Provide technical input during the business development life cycle. Participate in experimentation to assess new solution/application paths. Identify challenges to help the development of formalized solution methodologies. Interface and coordinate tasks with internal and external technical resources. Collaborate to provision estimates, develop overall implementation solution/application plan, and serve as a lead as required, to implement the installation, customization, and integration efforts. Experiences working on Containers (e.g. Docker, Kubernetes) and DevOps technology on VMware infrastructure and/or Public Cloud (e.g. AWS, Azure, Oracle, Alibaba) will be an added advantage. In-depth knowledge of Cloud & distributed architectures, Microservice, API best practice design. Experienced in CI/CD and exposed to standard development ecosystem: SonarQube, Jira/Confluence, SVN, Jenkins, Eclipse. Offers visa sponsorship for international candidates.\nWhy you\'ll love working here: Salary upto SGD 10,000. An international, dynamic and professional working environment. Attractive remuneration package (100% salary during probation). 15 paid leaves/ year. Maternity/ paternity leave. Annual health check. Annual salary review. Performance rewards. Premium healthcare insurance. Team building, Lunar New year Celebration, Projects celebration. Free in-house coffee, tea and snack (cookies, candies…).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 12th Diamond Flower Tower, 48 Le Van Luong street, Nhan Chinh ward, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(553, 424, 2, 'Python Developer', 'We are currently in the process of recruiting a Python Developer - level Fresher/Junior. For additional information, please refer to the details provided below.\n\n- Execute the data migration project for the customer.\n- Directly work with customers via email to exchange information during project implementation.\n- Work with the team to analyze and resolve technical issues.\n- Collaborate with the Sales team and Test Team to resolve the related problems.\n- Participate in the development and maintenance of the LitExtension system.\n\nYour skills and experience:\n- Graduated in Information Technology or equivalent fields.\n- At least 6 months of experience working with Python.\n- Understanding of relational databases, especially MySQL.\n- Ability to use English: Reading + Writing Skills.\n- Good problem-solving skills. IT process management skills and teamwork abilities.\n- Understanding e-commerce platforms is advantageous (Shopify, WooCommerce, Magento,...).\n- Knowledge of DevOps and CI/CD tools is a plus.\n\nWhy you\'ll love working here:\n- Income: Upto 20.000.000 VND/month.\n- Bonus for exceeding KPI, level up, quarter, bonus on 30/04-01/05, 02/09, year-end bonus, etc.\n- Team-building activity, Holiday trips, Regular bonding, Tea breaks.\n- An innovative and diverse working environment, with respect and support from colleagues and management.\n- Improve English skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '10th Lilama Office Building, no.56 To Huu Street, Trung Van ward, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(554, 425, 2, 'Senior MIS Specialist (Data Analyst, SQL, Python, Java)', 'Job description\n\nBáo cáo & Phân tích\n• Thiết kế và triển khai các báo cáo phân tích định kỳ và theo yêu cầu (productivity, performance, tài chính, vận hành...).\n• Đảm bảo tính chính xác, kịp thời và hiệu quả của hệ thống báo cáo MIS.\n• Xây dựng mô hình dữ liệu và bảng điều khiển (dashboard) tương tác.\n\nReporting & Analysis\n• Design and implement periodic and ad-hoc analytical reports (e.g. productivity, performance, financial, operational reports).\n• Ensure the accuracy, timeliness, and efficiency of the MIS reporting system.\n• Develop data models and interactive dashboards.\n\nTối ưu hóa dữ liệu\n• Rà soát, làm sạch và chuẩn hóa dữ liệu từ nhiều nguồn (SQL, Excel, APIs...)\n• Tối ưu hóa quy trình ETL và tự động hóa báo cáo\n• Hỗ trợ đề xuất cải tiến cấu trúc kho dữ liệu.\n\nData Optimization\n• Review, clean, and standardize data from various sources (SQL, Excel, APIs, etc.).\n• Optimize ETL processes and automate reporting.\n• Support recommendations for improving data warehouse structures.\n\nHỗ trợ hệ thống / ứng dụng\n• Quản lý và giám sát vận hành hệ thống CRM, ứng dụng mobile, website phục vụ bán hàng, chăm sóc khách hàng…\n• Phối hợp với đội IT và các bộ phận để duy trì và cải tiến các hệ thống, ứng dụng\n• Hỗ trợ kiểm thử (UAT), xác minh và hỗ trợ người dùng khi triển khai hệ thống liên quan đến các hệ thống và ứng dụng của công ty.\n• Xác định lỗi, xử lý sự cố hoặc phối hợp với nhà cung cấp phần mềm để đảm bảo hệ thống hoạt động ổn định.\n\nSystem / Application Support\n• Manage and monitor the operation of CRM systems, mobile applications, and websites for sales and customer service purposes.\n• Collaborate with the IT team and relevant departments to maintain and enhance systems and applications.\n• Support user acceptance testing (UAT), validation, and provide user support during system implementation.\n• Identify bugs, troubleshoot issues, or coordinate with software vendors to ensure system stability.\n\nPhân tích nâng cao\n• Ứng dụng mô hình phân tích nâng cao vào việc dự đoán xu hướng hoặc đánh giá hiệu suất.\n• Khai thác khả năng AI để tăng tốc phân tích và đề xuất giải pháp.\n\nAdvanced Analytics\n• Apply advanced analytics models to forecast trends and evaluate performance.\n• Leverage AI capabilities to accelerate data analysis and generate actionable insights.\n\nPhối hợp & đào tạo\n• Hỗ trợ đào tạo người dùng nội bộ về cách sử dụng báo cáo, dashboard hoặc công cụ dữ liệu.\n• Tham gia các dự án phân tích, chuyển đổi số nội bộ.\n\nCollaboration & Training\n• Support internal training on how to use reports, dashboards, and data tools.\n• Participate in internal analytics and digital transformation projects.\n\nYour skills and experience\n\nBẰNG CẤP VÀ YÊU CẦU GIÁO DỤC\n• Ưu tiên ứng viên Tốt nghiệp Đại học các ngành: Công nghệ thông tin, Hệ thống thông tin, Khoa học dữ liệu, Tài chính hoặc tương đương.\n• Prefer a Bachelor degree in any of the following fields: Information Technology, Information Management, Data Science, Finance or related fields.\n\nKĨ NĂNG YÊU CẦU\n• Tối thiểu 3 năm kinh nghiệm trong lĩnh vực MIS, phân tích dữ liệu, hoặc Business Intelligence.\n• Minimum 3 years of experience in MIS, data analysis, or Business Intelligence.\n• Ưu tiên ứng viên từng triển khai hệ thống báo cáo doanh nghiệp, hoặc hỗ trợ hệ thống CRM, ứng dụng mobile, website.\n• Prefered candidates with experience in enterprise reporting systems, or supporting CRM systems, mobile apps, or websites.\n• Thành thạo SQL, có kinh nghiệm với MongoDB.\n• Proficient in SQL; experience with MongoDB is a plus.\n• Sử dụng Python/Java để xử lý và trực quan hóa dữ liệu.\n• Hands-on experience with Python/Java for data processing and visualization.\n• Thành thạo Tableau, Power BI hoặc Excel (Pivot Table, VBA là lợi thế).\n• Skilled in Tableau, Power BI, or Excel (Pivot Table; VBA is a plus).\n• Hiểu biết cơ bản về tích hợp hệ thống qua API hoặc nền tảng cloud là điểm cộng.\n• Basic understanding of system integration via APIs or cloud platforms is a bonus.\n• Có khả năng phối hợp triển khai hoặc vận hành hệ thống CRM.\n• Experience in CRM deployment or operations is preferred.\n• Tư duy hệ thống, phân tích logic.\n• Strong system thinking and logical analysis skills.\n• Chủ động, có tinh thần hỗ trợ nội bộ.\n• Proactive and supportive team player.\n• Có khả năng giao tiếp hiệu quả với các phòng ban.\n• Ability to communicate effectively with crossfunctional teams.\n\nWhy you\'ll love working here\n• Mức lương cạnh tranh.\n• Competitive salary package.\n• Môi trường năng động, có cơ hội đào tạo và tiếp cận công nghệ mới.\n• Dynamic working environment with opportunities for training and access to new technologies.\n• Lương tháng 13.\n• 13th -month salary bounus.\n• Quyền lợi khác theo qui định luật lao động hiện hành (Nghỉ phép, BHYT, BHXH).\n• Full benefits in accordance with current labor laws (annual leave, health insurance, social insurance, etc.).\n• Được cung cấp công cụ làm việc.\n• Equipments provision.\n• Xét tăng lương mỗi năm 1 lần.\n• Annual salary review.\n• Thử việc nhận full lương.\n• Full salary during probation period.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, Toà nhà L\'Mak the Signature, 147 Hai Bà Trưng, Phường Võ Thị Sáu, Quận 3, TPHCM, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(555, 227, 2, 'Data Analyst – StoreFront eCommerce | $55K/year', 'As a Data Analyst, you will be responsible for the following tasks and duties:\n\n1. Strategic Analysis & Insight Generation:\n   - Collect, clean, and analyze data from diverse sources, including user behavior metrics, campaign performance metrics, and customer engagement metrics.\n   - Manage data from A/B testing, including user tracking event data, aggregating and splitting it into multiple versions for analysis.\n   - Develop hypotheses and provide actionable insights to improve storefront experiences, optimize ad campaigns, enhance customer retention strategies, and evaluate the effectiveness of new features or content through A/B testing.\n   - When comparing versions in A/B testing, provide the confidence level of the results, determine the required number of views (users) and duration for the test to achieve statistically significant outcomes. Define the Definition of Done (DoD) for the two versions A and B in the experiments.\n   - Utilize data visualization techniques to create charts and dashboards that communicate key trends and support decision-making for cross-functional teams.\n\n2. Dashboard & BI Development:\n   - Build and maintain real-time BI dashboards to track critical metrics such as conversion rates, customer lifetime value, and results from A/B tests.\n   - Assist in the creation of a self-service BI system, enabling teams to explore data and generate reports tailored to their needs, including monitoring and analyzing A/B tests.\n\n3. Data Management & Integration:\n   - Define and manage data schemas for eCommerce-specific objects (e.g., product catalogs, tracking user events) and data from A/B tests to optimize data accessibility for analysis.\n   - Ensure the data warehouse maintains high data quality standards, is optimized for performance, and meets the needs of our global platform, including supporting analyses from A/B testing.\n\n4. Team Collaboration:\n   - Collaboration with Team Members: Work closely with team members to comprehend data requirements and deliver appropriate data solutions to meet business needs.\n   - Cross-functional Collaboration: Engage with cross-functional teams to support and facilitate data-driven decision-making throughout the organization.\n\nBy undertaking these responsibilities, you will play a crucial role in driving data-informed decisions and strategies, ultimately contributing to the success and growth of our organization.\n\nYour skills and experience:\n- Educational Background: Bachelor\'s degree preferred in Data Science, Computer Science, Mathematics, Statistics, or a related field.\n- Professional Experience: At least 3 years working in a Data Analyst role.\n- Technical Proficiency: Expertise in SQL, Python, and BI tools, along with a strong understanding of data modeling, data warehousing, and real-time data monitoring. Familiarity with cloud technologies and DevOps practices is essential.\n- Database Management: Understanding the principles of database management and being able to perform exploratory data analysis is essential.\n- Analytical Skills: Strong ability to analyze datasets and utilize data visualization techniques to derive meaningful insights.\n- Communication Skills: Strong verbal and written communication skills, capable of presenting data insights clearly and contributing to decision-making processes.\n- Innovative Thinking: Ability to keep pace with industry trends in data analytics methodologies and tools, applying this knowledge to drive the business forward.\n- English proficiency is required.\n\nPreferred (but not required):\n- Machine Learning Techniques: Familiarity with machine learning algorithms and their applications in data analysis.\n- Big Data Platforms: Experience with big data technologies such as Hadoop and Spark for handling large datasets.\n- Programming Proficiency: Skilled in programming languages like Python and R for data analysis and automation tasks.\n- Familiarity with the Agile toolset, such as Gitlab, Jira, Confluence, and Slack.\n\nWhy you\'ll love working here:\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\n\nExceptional Compensation:\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total annual compensation of $55,000, reflecting your expertise and contribution.\n\nGrowth Opportunities:\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\n\nGlobal Vision:\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\n\nIn addition to development tasks, you’ll collaborate closely with other Centers of Excellence (CoEs) to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(556, 426, 2, 'Kỹ sư cầu nối (BrSE)', 'Top 3 reasons to join us\n- Thưởng: Tháng 13, thưởng Ngày lễ…\n- Xét tăng lương mỗi năm một lần\n- Chế độ du lịch hằng năm \n\nJob description\n- Là cầu nối giữa khách hàng Nhật Bản và đội dự án ở Việt Nam.\n- Làm việc trực tiếp với khách hàng Nhật: giao tiếp, thương lượng, nhận, phân tích các yêu cầu của dự án phần mềm... và truyền đạt cho đội dự án ở Việt Nam.\n- Hỗ trợ PM hoặc trở thành PM của dự án\n- Kiểm soát tiến độ thực hiện dự án, phối hợp với khách hàng và cấp trên trong việc quản lý dự án.\n\nYour skills and experience\n- Có từ 2 - 3 năm kinh nghiệm ở vị trí BrSE.\n- Có kiến thức về IT, thành thạo trao đổi logic, kỹ thuật với khách hàng.\n- Có kinh nghiệm làm việc một trong các ngôn ngữ Java, PHP, .Net, iOS, Android...và quản trị dự án phần mềm cho khách hàng Nhật.\n- Tiếng Nhật từ N2 trở lên, giao tiếp tốt và có thể làm việc trực tiếp với khách hàng người Nhật.\n- Có kỹ năng quản lý và tư duy logic tốt.\n- Có khả năng làm việc nhóm và tinh thần trách nhiệm cao.\n\nWhy you\'ll love working here\n- Môi trường làm việc thoải mái cùng với đồng nghiệp cởi mở, thân thiện\n- Được hưởng đầy đủ các chế độ đãi ngộ và các khoản bảo hiểm BHXH, BHYT, BHTN.\n- Công ty đóng bảo hiểm trên lương cơ bản\n- Xét tăng lương mỗi năm một lần.\n- Thưởng: Tháng 13, thưởng Ngày lễ…\n- Làm việc 5 ngày/tuần (được nghỉ Thứ 7 và Chủ nhật).\n- Công ty cung cấp thiết bị làm việc cho toàn bộ nhân viên chính thức (bao gồm thử việc)\n- Công ty phụ cấp thêm 500.000 VNĐ/tháng tiền xăng xe nếu nhân viên đi làm xa hơn 10km (Áp dụng từ tháng ký hợp đồng chính thức)\n- Chế độ du lịch hằng năm và các hoạt động liên hoan công ty\n- Từ Thứ 2 đến Thứ 6: 8:00 – 12:00 và 13:30 – 17:30\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 9, Tòa nhà STA Building, 618 đường 3/2, Phường 14, District 10, Ho Chi Minh; Tầng 3, Số 20 Lê Quang Hòa, Phường Hòa Xuân, Cam Le, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(557, 245, 2, 'Back End Developer (Java, MySQL, Spring)', 'LG CNS đang tìm kiếm các lập trình viên Back-end đủ tiêu chuẩn tham gia vào nhóm. Bạn sẽ phát triển trong việc phát triển ứng dụng web trong các lĩnh vực khác nhau, chẳng hạn như: AI Machine learning / Data , Security & Solution, DX…\n\n- Đảm bảo hiệu suất, chất lượng và khả năng đáp ứng tốt nhất có thể của các ứng dụng ở phía Back-end\n- Luôn cập nhật các công nghệ mới nổi\n- Trao đổi chi tiết khi phỏng vấn\n\nYour skills and experience\n\n- Có ít nhất 3 năm kinh nghiệm về JAVA \n- Có kinh nghiệm phát triển ứng dụng web\n- Phát triển dựa trên Spring, Spring Boot F/W\n- Phát triển API (REST API)\n- Sử dụng thành thạo 1 trong các ngôn ngữ DB như MySQL, MongoDB , Oracle , SQL \n- Git, Jira, Confluence\n- Hiểu và áp dụng CI/CD\n- Giao tiếp Tiếng anh ở mức trung bình (TOEIC trên 550 và các chứng chỉ tương tự hoặc tự tin giao tiếp tiếng anh)\n\nƯU TIÊN\n\n- Có kinh nghiệm làm việc trong môi trường Kubernetes, Cloud (AWS, GCP) sử dụng Python\n- Biết làm về GO\n- Có kinh nghiệm về tối ưu hóa SQL\n- Giao tiếp tiếng Hàn\n\nWhy you\'ll love working here\n\n- Lương, thưởng sẽ được thảo luận sau khi thông qua CV & Phỏng vấn\n- Review đánh giá năng lực hàng năm và điều chỉnh tăng lương theo hiệu quả công việc\n- Phụ cấp chứng chỉ ngoại ngữ tiếng hàn (TOPIK)\n- Chăm sóc sức khỏe: Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp\n- Điều kiện làm việc thoải, linh hoạt\n- Cơ hội phát triển nghề nghiệp tốt với các dự án thú vị và đầy thử thách;\n- Các khóa đào tạo tiếng Anh, tiếng Hàn, kỹ thuật, kỹ năng mềm;\n- Cơ hội học các khóa học đặc biệt của LG CNS, công nghệ mới và bảo mật\n- Quà tặng vào các dịp lễ, tết (30/4-1/5, 2/9, tết v.v)\n- Các hoạt động ngoài trời với sự hỗ trợ của công ty: câu lạc bộ thể thao, team building, tiệc happy hour, sinh nhật, du lịch, sự kiện nhân viên và gia đình, v.v.\n- Thời gian làm việc: 8 tiếng từ T2 - T6 (8:00- 12:00/ 13:00- 17:00), Happy hour chiều thứ 6 hàng tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(558, 227, 2, 'Senior Software Tester, Global E-commerce Data Platform', 'Top 3 reasons to join us\n1. Top-notch Annual Income\n2. Global Health Insurance\n3. 5-star Office in the centre of Hanoi\n\nJob description\nTesting and Quality Assurance:\n- Design, develop, and execute test plans and test cases to ensure comprehensive coverage of product requirements.\n- Perform functional, integration, regression, and system testing for both frontend and backend systems.\n- Create and maintain detailed reports on testing progress, defects, and outcomes.\n- Review and refine test strategies to optimize quality and efficiency.\n- Ensure cross-browser, cross-platform, and device compatibility for applications.\n\nCollaboration and Delivery:\n- Collaborate with BAs, developers, and product managers to understand requirements, provide input, and ensure alignment.\n- Act as a quality advocate, delivering features that meet user needs and maintain high standards.\n- Evaluate product readiness and release timelines based on test results and team discussions.\n\nLeadership and Influence:\n- Share quality-focused practices and promote a quality-first mindset within the team.\n- Mentor team members on testing techniques and workflows to enhance overall quality.\n- Ensure workflows and processes are followed consistently and improve them when necessary.\n\nContinuous Monitoring and Improvement:\n- Monitor product performance and user feedback in production environments to identify areas for improvement.\n- Stay updated with industry trends, tools, and best practices to continually improve testing processes.\n- Drive initiatives to improve product quality, user satisfaction, and team productivity.\n\nYour skills and experience\nEducation: Bachelor\'s Degree in Information Technology, Computer Science, or a related field from a reputable university.\nExperience: Minimum of 5 years of experience as a Software Tester or Quality Control, with significant exposure to manual testing.\nTechnical Skills:\n- Deep understanding of APIs/Web-services and familiarity with testing tools such as Postman, BrowserStack, and CURL.\n- Knowledge of Agile/Scrum methodologies and practices like TDD/BDD.\n\nTools and Documentation:\n- Proficient with Atlassian tools (Jira, Confluence) and mock-up tools (e.g., Figma, draw.io,..).\n- Ability to write Software Development Requirement Documents and Functional Specifications.\n\nSoft Skills:\n- Excellent Problem-Solving skills and Critical Thinking.\n- Outstanding Communication and Documentation skills.\n- Ability to work collaboratively in a fast-paced, Agile environment.\n- Proactive and self-motivated with a strong sense of ownership.\n\nPreferred (but not required)\n- ISTQB certification or equivalent.\n- Experience in the eCommerce industry.\n- Experience with automation testing.\n- Proficiency in English.\n\nWe believe in providing equal opportunities to all employees. Therefore, we encourage all qualified individuals, regardless of gender, age, disability, race, ethnicity, origin, religion, or economic background, to apply. Our primary focus in hiring is to drive our company forward with talented and dedicated individuals.\n\nWhy you\'ll love working here\nExceptional Total Compensation Package\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Full salary during probation & Guaranteed 13th month salary.\n- 12 days work-from-home & 12 days of paid annual leave, plus seniority paid leave.\n- Global health insurance package for yourself and direct family members, plus annual health checkup.\n\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\n\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(559, 427, 2, 'Game Designer (English)', 'Job description\n- Lên ý tưởng, xây dựng kịch bản chi tiết cho game\n- Thiết kế level, phân tích, thực hiện cân bằng game\n- Phối hợp cùng Developer và Artist để phát triển tính năng và hoàn thiện sản phẩm game\n- Phân tích chỉ số, đánh giá và đưa ra các phương án tối ưu nhằm đem lại trải nghiệm tốt nhất cho người chơi\nYour skills and experience\n- Yêu thích làm game\n- Kinh nghiệm tối thiểu 1 năm ở vị trí tương đương\n- Khả năng tư duy, sáng tạo tốt\n- Có trách nhiệm cao trong công việc, thái độ cầu tiến và ham học hỏi công nghệ mới\n- Có khả năng đọc hiểu tài liệu bằng Tiếng Anh là một lợi thế\nWhy you\'ll love working here\n- CƠ HỘI THĂNG TIẾN HOẶC ĐỀ XUẤT LÊN LÀM PM, TECHLEAD,... TRONG THỜI GIAN NGẮN NẾU ĐÃ CÓ KINH NGHIỆM\n- Mức lương upto $1500, thử việc hưởng 100% lương.\n- Lương NET, không phải đóng bảo hiểm hay bất kỳ chi phí nào\n- Thưởng linh hoạt, hấp dẫn: Thưởng quý, thưởng lễ, thưởng tết,.. thu nhập mỗi năm 15-20 tháng lương.\n- Review lương 6 tháng/lần\n- Du lịch, team building tối thiểu 2 lần/năm, hoa quả quà chiều, được thoải mái chơi các trò chơi tại công ty: bi-a, PS, board game,...\n- BHXH, khám sức khỏe định kỳ,12 ngày nghỉ phép/năm và ngày lễ\n- Cơ hội được tham gia và xây dựng các dự án game chất lượng,được làm việc với những đồng nghiệp có kinh nghiệm hàng đầu trong ngành game mobile, cơ hội phát triển và thăng tiến rộng mở\n- Được làm việc với nhiều khách hàng quốc tế và nhiều đối tác lớn như Google,Facebook,Unity....\n- Cơ hội được học hỏi, được thử sai, được rèn luyện bản thân và trau dồi kinh nghiệm thực chiến với việc hỗ trợ 30-100% chi phí các khóa học nhiều kỹ năng\n- Môi trường thân thiện, trẻ trung, hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, Toà Sun Square, Số 21 Lê Đức Thọ, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(560, 428, 2, 'Senior Mobile Developer (iOS/Android)', 'Top 3 reasons to join us\n- Competitive salary \n- Premium health care package \n- 7 working hours/day\n\nJob description\nDomain: Financial Service, Crypto network, EC platform, AI avatar, AI chatbot, Game, Decentralize\nTech-stack: Aws, Jenkins, GitLab, java, NodeJS, micro service, centralized wallet, docker, Reacts, vue.js\nWe are seeking 01 Android Developer and 01 iOS Developer. The job will perform following tasks:\n- Work closely with Product Managers, technical stakeholders, to craft, design and propose mobile solutions, and agile delivery plans.\n- Lead and manage the mobile application team in delivering the product features according to plan, using agile delivery methodology\n- Develop Android/iOS applications aimed at a vast number of diverse Android/iOS devices.\n- Integrate with back-end services\n- Design, develop and optimize the performance of Mobile Apps products\n- Participate in all stages of the software development process, including: requirements analysis, design, research new technologies...\n- Participate in contributing ideas with leader and customers to improve products or work processes.\n- Solve issues, perform tasks according to plan, report work progress to the Line Manager\n\nYour skills and experience\nJob Requirements:\nFor iOS Developer: \n- Have at least 5 years of experience in developing iOS applications\n- Have an understanding of the architecture of iOS applications and use design patterns proficiently;\n- Have a solid knowledge of Swift/Objective C;\n- Having hands-on experience with Android is an advantage\n- Have strong knowledge on OOP (Object Oriented Programming) and SOLID principles.\n- Have knowledge in application architecture, data structure, clean code, design patterns, refactoring, code efficiency, memory, caching, multi-threading, test driven development and application profiling.\n- Have knowledge in source version control: SVN, Git.\n- Experience working Cloud of Google such as: Firebase, Firestore, Google Map...\n- Understanding of XML/JSON based RESTFUL APIs.\n- Have strong knowledge in custom view, custom view group and touch event dispatcher.\n- Experience with Clean Architecture, MVVM, VIPER, Swift UI, Reactive Programming, dependency injection is a huge plus.\n\nFor Android Developer: \n- At least 5 years working experience on mobile development, Java, Kotlin…\n- Having hands-on experience with Android is an advantage\n- Have strong knowledge on OOP (Object Oriented Programming) and SOLID principles.\n- Have knowledge in application architecture, data structure, clean code, design patterns, refactoring, code efficiency, memory, caching, multi-threading, test driven development and application profiling.\n- Have knowledge in source version control: SVN, Git.\n- Experience working with third party libraries and APIs .\n- Understanding of XML/JSON based RESTFUL APIs.\n- Have strong knowledge in custom view, custom view group and touch event dispatcher.\n- Experience with the Architecture component, reactive programing, dependency injection is a huge plus.\n\nPersonality Requirements:\n- You thrive in independent work environments, demonstrating strong attention to detail with minimal supervision.\n- You are proactive, dependable, and dedicated to delivering high-quality results.\n- With a hands-on, can-do approach, you\'re always ready to take initiative and tackle challenges head-on.\n- You embrace continuous learning and willingly contribute wherever support is needed.\n- Agile methodologies and writing clean, maintainable code are integral to your workflow.\n- You collaborate effectively with cross-functional teams to build successful, user-centered products.\n- You stay informed about emerging technologies and trends, and you\'re comfortable navigating diverse, multicultural environments.\n- You possess excellent English communication skills, both spoken and written.\n\nWhy you\'ll love working here\n- Working hours: 9:00 - 17:00 (5 days per week); Breaking time: 12:00-13:00\n- Salary: Up to $4000\n- 100% Offered Salary in probation time\n- Modern working equipment (Macbook,...)\n- Performance Review: 2 times/year based on employee\'s performance and contribution;\n- Well-equipped with insurance package as stated by Labor code\n- Premium PVI Health Insurance Package for all members\n- Transportation allowance and free parking included.\n- Technical seminars and workshops annually.\n- Free snack, coffee, tea available.\n- Variety of corporate events: weekly tea-break, monthly birthday parties, quarterly team building to New Year party, company trip etc.\n- Friendly, open and fast-paced environment where every idea is welcomed.\n- Other benefits as per stated in Vietnamese Labor Law\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 3, The Loop Building, 241 Xuan Thuy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(561, 429, 2, 'Chuyên viên An toàn thông tin (Security, Linux)', 'Job description\n- Triển khai, vận hành giải pháp an ninh, bảo mật (Firewall, IDS/IPS, DLP, WAF,...)\n- Theo dõi, thực hiện xử lý các các cảnh báo từ hệ thống giám sát An ninh thông tin.\n- Xây dựng quy trình, tiêu chuẩn và thiết lập, áp dụng các chính sách, tiêu chuẩn kỹ thuật liên quan đến bảo mật hệ thống..\n- Đánh giá, kiểm duyệt các phương án, giải pháp liên quan đến an ninh mạng.\n- Tham gia hỗ trợ triển khai giải pháp đảm bảo An toàn thông tin cho các dự án của Công ty.\nYour skills and experience\n- Trình độ: Tốt nghiệp Đại học chuyên ngành An toàn thông tin, Mạng máy tính, Công nghệ thông tin hoặc chuyên ngành có liên quan;\n- Có nền tảng kiến thức tốt về Hệ điều hành (Windows, Linux), Network (TCP/IP, DNS, HTTP/HTTPS, và các giao thức khác)\n- Từng triển khai với các khách hàng là một lợi thế, biết về docker và SOC\n- Có kiến thức cơ bản, kinh nghiệm về An toàn thông tin, các phương thức tấn công mạng, các lỗ hổng trong ứng dụng.\n- Có hiểu biết, kinh nghiệm làm việc với các thiết bị: Firewall, IDS/IPS,...\n- Ưu tiên các ứng viên có các chứng chỉ chuyên môn: Security+, CISSP, CEH…\n- Tiếng Anh: đọc hiểu tài liệu kỹ thuật;\n- Năng động, cầu tiến, chịu khó học hỏi và chịu được áp lực công việc;\n- Có thể đi công tác theo yêu cầu của công việc\nWhy you\'ll love working here\n- Thu nhập tương xứng với năng lực và hiệu quả công việc (Mức thu nhập tùy theo năng lực và thỏa thuận khi phỏng vấn)\n- Lương tháng thứ 13, thưởng theo kết quả kinh doanh của Công ty và thưởng cuối năm;\n- Chế độ bảo hiểm đầy đủ.\n- Chế độ khám sức khỏe định kỳ hàng năm (1 lần/năm)\n- Gói bảo hiểm chăm sóc sức khỏe hàng năm.\n- Chế độ nghỉ phép theo quy định của Luật\n- Chế độ du lịch và chế độ vào các ngày lễ lớn trong năm.\n- Chế độ ăn trưa, đi lại thực hiện công việc bằng thẻ taxi.\n- Cơ hội thăng tiến và phát triển nghề nghiệp;\n- Cơ hội tham gia các khoá đào tạo nghiệp vụ;\n- Các đãi ngộ khác theo quy định của Công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, tòa nhà Samsora, số 105 Chu Văn An, Phường Yết Kiêu, Quận Hà Đông, Tp. Hà Nội, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(562, 302, 2, 'QA Engineer (Manual Tester/Performance/Automation Test)', 'Top 3 reasons to join us\n- Premium Healthcare check\n- Bonus up to 15%/month\n- 100% salary on probation\n\nJob description\n● Design, develop, and execute comprehensive performance testing strategies, including load, stress, scalability, and endurance tests\n● Analyze performance test results, identify bottlenecks, and provide actionable insights for optimization. Create detailed performance test reports for stakeholders\n● Work closely with development, and product management teams to understand product architecture, performance requirements, and business use cases\n● Develop and maintain automated performance testing scripts using industry-standard tools to streamline testing processes.\n● Utilize monitoring tools to track system performance and diagnose issues during testing\n● Contribute to the enhancement of performance testing methodologies, tools, and processes for improved efficiency and accuracy\n● Plan, configure, and maintain test environments, ensuring accurate simulation of production-like conditions\n● Investigate and troubleshoot performance issues, collaborating with development teams to identify and address root causes.\n● Create and maintain performance test documentation, including test plans, test scripts, and test results\n\nYour skills and experience\n● Bachelor\'s degree in Computer Science, Engineering, or a related field, or equivalent practical experience\n● 3-5 years of experience in performance testing, preferably in a software product environment\n● Strong experience with performance testing tools\n● Proficiency in scripting languages like Python, JavaScript, or Shell for automation purposes\n● Experience working with cloud platforms (AWS, Azure) and virtualized environments\n● Solid understanding of software development life cycle (SDLC) and Agile methodologies\n● Strong analytical and problem-solving skills with attention to detail\n● Excellent communication and teamwork abilities\n\nNice to have:\n● Experience with cloud platforms (AWS, Azure, Google Cloud) and virtual environments (VMware, Hyper-V, KVM)\n● Familiarity with backup and disaster recovery products like Nakivo, Veeam, Acronis, or similar\n● Ability to analyze performance metrics, diagnose issues, and suggest optimizations specific to data backup and recovery\n● Strong communication abilities to document and present performance test results\n\nGiven the high volume of CVs applied, we can only manage to respond to candidates whose profiles aligns with the position within 5 working days. We appreciate your understanding and enthusiastic towards our company.\n\nWhy you\'ll love working here\nThe Nakivo team in Vietnam has been changing very fast in the recent years, we have grown from a group of 6 engineers to the current team size of 80 and we are expecting to grow even more in the next following years.\nWe welcome and embrace people, regardless of their background, religion, nationality or gender, but focus on diversity, contribution, determination and work ethic. At Nakivo, we are trying to improve every day, to become a competitive choice for talented people, by offering\n- Flexible working hours: Office opens from 7.00 AM to 12.00 AM\n- 13-month bonus & performance bonus\n- 100% salary on probationary period\n- Private health care package\n- Premium health care check\n- Gift (cash/voucher) for every special occasion: New Year\'s Eve, Tet holidays, International Women\'s Day, International Children\'s Day, Mid-Autumn Festival and Birthday\n- 15-18 annual leaves/year, 5 Sick Leaves and additional leaves (up to 3 days)\n- Team building\n- Free and un-limited snacks, tea, coffee, and by-choice request.\n**Due to the high volume of CVs we receive, we will only be able to respond to candidates whose profiles are a good match for the position within 5 working days. We appreciate your understanding and hope for your patience in this matter. Thank you!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '16 Le Quy Don, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(563, 391, 2, 'Junior Frontend Developer ( JavaScript/ TypeScript)', 'Job description\n- Report to the Project Manager or Line Manager.\n- Working with the design team on product design or designing application wireframe when required.\n- Resolve bugs and technical issues.\n- Ensure compliance with security and regulatory requirements.\n- Frontend team support: ensure the backend is properly designed to support the frontend user interfaces and experiences.\n\nYour skills and experience\n- Strong proficiency with TypeScript/Javascript.\n- 1+ years of relevant experience with a bachelor’s degree in computer science.\n- Strong experience at ReactJS/React Native.\n- Experience in developing frontend applications, with expertise in deep optimization of end-user experience, stability & scalability, code modularity, and rendering latency.\n- Experience with Babel, Webpack, HTTP2, or other JavaScript building tools.\n- Experience with API Integration (Restful API and GraphQL).\n\nPriority:\n- Good English communication skills (listening, speaking, reading, writing).\n- Ability to work independently and in a team environment.\n- Proactive attitude towards continuous learning and skill development.\n\nCulture, attitude and potential:\n- Transparency, responsibility, positive and proactive working attitude.\n- Communication and collaboration skills.\n- Treat others well.\n- Potential for growth.\n- Management potential.\n\nWhy you\'ll love working here\n- Salary policy: The probationary salary is 85% of the official salary (02 months). The official salary form 8.000.000 - 20.000.000 GROSS (depending on ability).\n- Work in a dynamic and flexible environment.\n- The training costs, professional guidance, and skill development are fully sponsored.\n- Allowance and insurance regime as prescribed by laws.\n- Company trip at least once a year.\n- There is always a plan to define a suitable career path for each individual, opening up numerous opportunities for advancement and dynamic professional growth.\n- Working from Monday to Friday and Saturday morning (flexible), working hours: Morning: 09.00am - 12:00pm; Saturday morning: 09:00am - 01:00pm; Afternoon: 01:00pm – 06:00pm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '8th Floor, Bach Dang Complex Building, 50 Bach Dang, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(564, 430, 2, 'Mid. Frontend Dev - HTML5/CSS3/JavaScript', 'Solis Lab is hiring now Frontend Dev - HTML5/CSS3/JavaScript. Join Solis Lab, a dynamic team crafting websites for top-tier brands with millions of monthly views. We\'re looking for a developer who is eager to turn intricate designs into stunning, responsive, and accessible web components. If you\'re detail-oriented, proactive, and ready to dive into front-end web development best practices, we want you!\n\nYour main responsibilities include:\n- Transform design files (Sketch, Zeplin, Figma) into responsive and accessible front-end components.\n- Uphold and advance accessibility, performance, and coding standards.\n- Collaborate with the team leader and project manager to keep projects on schedule and aligned with goals.\n- Engage with the technical lead to research and adopt cutting-edge front-end practices.\n\nYou are perfect for this position if:\n- Have a keen eye for details and can interpret design requirements into front-end code precisely.\n- Writes clean, maintainable code that is designed for reusability and scalability across various projects.\n- Demonstrates independence and initiative, proactively researching and devising technical solutions for challenging tasks.\n- Conducts thorough quality assurance on your work before seeking reviews from team leaders.\n- Supports fellow team members, is willing to share knowledge, and provides mentorship to less experienced developers.\n- Takes pride in delivering high-quality work and is committed to excellence. Only apply if you\'re ready to invest the time and effort required to achieve the highest standards.\n\nYour Skills and Experience:\n- Basic proficiency in English reading and writing.\n- Strong critical thinking and problem-solving abilities.\n- Ability to write SEO-friendly, semantic HTML5.\n- Expert knowledge of developing cross-platform/browsers (Chrome, Safari, Firefox) for web development.\n- Proficient with modern CSS including frameworks like Tailwind CSS, and native features such as Flexbox, Grid, Transforms, and Animation.\n- Basic knowledge of CSS preprocessors like Sass, Less, or PostCSS.\n- Skilled in JavaScript ES6+ (ES7/8/9) without relying on jQuery.\n- Familiarity with JavaScript frameworks such as React or Vue.js.\n- Extensive experience with responsive web design.\n- Comfortable using design tools like Sketch, Zeplin, and Figma.\n- Proficient in code versioning tools, particularly Git.\n- Portfolio required: demo projects, GitHub profile, code snippets, etc. (2 live front-end project samples, 1 code sample demonstrating BEM, Tailwind CSS, or other CSS conventions, 1 code sample showing modular ES6+ JavaScript usage).\n\nThe following skills are NOT REQUIRED, but huge bonus points if you have them:\n- Webpack / Babel / Vite.\n- WordPress / Shopify.\n\nWhy you\'ll love working here:\nExperience a fast-paced development agency life in a team that values leadership, craftsmanship, innovation, teamwork, and simplicity. Our team updates technology stacks, conventions, and workflows constantly. We move fast and learn faster. Stagnation or mediocrity is not acceptable. Continuous improvement is our way of life. If you\'re bothered by any of these things, don\'t apply.\n\nIf that doesn\'t bother you, then you are one of us, and you will love this. Your experience and skills will grow more quickly than those of your peers in other companies. All we focus on is learning and improving through our day-to-day work, and at the same time, enjoying the company of our colleagues, whom we select very carefully.\n\nWe also provide the following benefits:\n- Total annual income equivalent to 14 months of salary (standard salary + Tet + bonus).\n- Professional working environment: We provide you with top-notched tools including MacBook Pro, iPhone, Android devices for testing. We don\'t aim to micro-manage our employees. You will be the one who manages our expectations.\n- A clear vision of your career progress: Performance/Roadmap review every 3 months. Growth tracks and career roadmap are carefully designed to build your confidence as you progress through the levels.\n- Grow to be a Specialist or Jack of all trade: Opportunity to work with modern but pragmatic tech stacks for front-end and back-end. We pay for any courses, books, or conferences that you need to level up your skills.\n- You are encouraged to have a life outside of work. Besides public holidays, you get 12 paid days off a year. Our fun and engaging reward system let you book extra paid leaves or remote working days for your efforts as a team player. You get one extra day off for every year you work at Solis Lab.\n- Yearly health check-up. We also provide premium health insurance for family members of senior-level members. There are regular team-building activities, trips, parties.\n- Join clubs such as swimming, badminton, billiards,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 4 - tòa nhà Hà Thành Plaza - 102 Thái Thịnh, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(565, 431, 2, 'DevOps Engineer (Powershell, .Net, English)', 'At Optimizely, our platform is the product. As we advance the next generation of our industry-leading platform for delivering digital experiences, we are looking for a Software Engineer to help us build upon and expand our vision. As a software engineer at Optimizely you will be responsible for designing, implementing, releasing, and maintaining our platform functionality.\n\nAs a Devops Engineer, you will:\n\nBuild reusable, maintainable, reliable, and scalable platform automation using PowerShell\nDevelop, deploy, and maintain the services that enable Optimizely’s SaaS and PaaS product lines\nContribute to the architecture and design decision making process\nPursue growth by maintaining an awareness of the state of technology, engineering techniques and best practices\n\nYour skills and experience\n\nYou have 5+ years of experience in the development of scalable, production services\nHands on experience with cloud infrastructure such as Azure or AWS minimum of 2 Years\nScripting and software development across one or more programming languages Powershell\nYou can breakdown complex user stories into sub-tasks of appropriate scope for efficient delivery\nYou are approaching an expert level competency in core language areas\nYou are actively sharing your knowledge and skills to help team members grow\nYou maintain an awareness of the state of technology, tools, and techniques\nYou are knowledgeable in the development and operational aspects of cloud-based software\nYou require little oversight beyond high level direction\nYou have a bachelor’s or master’s degree in Computer Science or equivalent experience\n\nWhy you\'ll love working here\n\nWe are certified the Great Place to Work 2024-2025.\nHackdays for self-studying and researching any IT-related subjects.\n5 working days/week with flexible working time and no overtime.\nAnnual unforgettable company outing.\nInternational, professional, creative working environment and talented teams.\nOnsite opportunities in Europe and US.\nCommon cultural-sportive- art Clubs and activities, sponsored and/or supported by the Company (Ex: Football, GYM, Swimming, Guitar, English…).\nPowerful workstation: Core i7-9700, 16-32 GB RAM, 02 x QHD 2560x1440 monitors (2K resolution).\n100% official salary during the probation period, 13th month salary, annual salary raise.\nUp to 03 extra paid-leave days per year.\nSocial, Health and Unemployed Insurance are based on 100%.\nGross salary and fully paid by Company.\nExtra bonus at $ 60 per special occasions (Birthday, Labor Day, National Day, Solar New year, Lunar New Year).\nLunch allowance at $30 per month.\nBaby allowance for a child under 03 years old is $ 12 per month.\nAON Premium Healthcare Insurance package for employees and their children up to 18 years old.\nDaily various foods, drink, and seasonal fresh fruits.\nAnd many other benefits, let\'s join us to discover!\n\nOptimizely is committed to a diverse and inclusive workplace.\nOptimizely is an equal opportunity employer and does not discriminate on the basis of race, national origin, gender, gender identity, sexual orientation, protected veteran status, disability, age, or other legally protected status.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '165 Thái Hà, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(566, 182, 2, 'AWS DevOps Lead (DevOps, AWS)', 'We seek a highly skilled and motivated AWS DevOps Lead with a strong background in software development, expertise in AWS Cloud, and a solid understanding of the banking domain. A crucial part of the role is championing and leading infrastructure as code. You will be responsible for implementing tools and processes that enable rapid software development and deployment.\nYour mission is to embrace continuous integration/deployment in a delivery pipeline that will perform automated quality checks, deploy cloud infrastructure quickly, and provide operational tooling and metrics that development teams can consume. To succeed, you will have a blend of development experience and operational experience that provides a good understanding of the developers you are working with while balancing critical systems uptime.\nYour responsibilities\n• Collaborate with cross-functional teams to gather requirements and design scalable and maintainable software solutions.\n• Build integration solutions for seamless communication between microservices, APIs, and third-party systems.\n• Contribute to developing continuous delivery, automation frameworks, and pipelines to create an excellent experience for developers and customers.\n• Optimize database interactions and ensure data integrity across distributed systems.\n• Develop and enforce best practices for messaging, integration, and data pipeline architectures.\n• Identify and develop opportunities to improve our processes and tools for automation.\n• Learn new skills and help foster a continuous delivery and cloud-first mindset.\nYour skills and experience\n• 7+ years of experience in the field of DevOps including backend development using Python or Java,\n• At least 2+ years in a lead role. (DevOps or Technical Lead)\n• Proficient in Apache Kafka, including Kafka Connect, Schema Registry, etc.\n• Expertise in building and deploying microservice and event-driven architecture, distributed systems, event sourcing, CQRS patterns, etc..\n• Experience using AWS foundation services (VPC, ECS, Lambda, RDS, SNS, SQS, Eventbridge, etc..).\n• Hands-on experience with tools like Kafka Connectors, Debezium, etc.. \n• Solid experience with application integration patterns, RESTful APIs, and messaging protocols.\n• Able to do hands-on, deep-dive details and work closely with team members to troubleshoot and optimize our platform.\n• Able to design scalability systems as well as multi-country patterns for our platform\n• Knowledge of one or more AWS CloudFormation/Terraform/CDK for infrastructure provisioning.\n• An automation mindset with the ability to develop tooling to improve the efficiency of repeatable tasks, reliability, and performance.\n• Understanding cloud change management practices with an awareness of compliance and security standards.\n• Good skills in English and the ability to communicate and coordinate effectively with business partners and technical teams.\n• Demonstrate good logical thinking and problem-solving skills.\n• Be curious and have a self-learning attitude.\nBig Plus:\n• AWS Certification Developer Associate or DevOps / SA Professional.\n\nYou are:\n• Passionate about technology\n• Independent but also a team player\n• Comfortable with a high degree of ambiguity\n• Focused on usability and speed\n• Keen on presenting your ideas to your peers and management.\n\nWhy you\'ll love working here\n• You’ll love working with us if you are:\n• Passionate about technology.\n• Independent but also a good team player.\n• Comfortable with a high degree of ambiguity.\n• Focused on usability and speed.\n• Keen on presenting your ideas to your peers and management.\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\nSome of our benefits:\n• Meal and parking allowances are covered by the company.\n• Full benefits and salary rank during probation.\n• Insurances such as Vietnamese labor law and premium health care for you and your family.\n• SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\n• Values-driven, international working environment, and agile culture.\n• Overseas travel opportunities for training and work-related.\n• Internal Hackathons and company events (team building, coffee run, etc.).\n• Pro-Rate and performance bonus.\n• 15-day annual + 3-day sick leave per year from the company.\n• Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(567, 258, 2, 'Data Scientist (R, Python, SQL)', 'Với sứ mệnh đưa Viettel “Trở thành đơn vị đứng đầu Việt Nam về ứng dụng phân tích dữ liệu vào hoạt động điều hành, sản xuất kinh doanh”, hiệu quả của các dự án PTDL trong Viettel đang tăng lên từng ngày từng giờ. Từ doanh thu trung bình ~70 tỷ/ tháng năm 2019, đầu năm 2020 con số này đã tăng lên ~250 tỷ/ tháng và đang tiếp tục tăng, khẳng định vị thế của Viettel trong chuyển đổi tổ chức thành tổ chức hướng dữ liệu cũng như ứng dụng PTDL vào hoạt động sản xuất, kinh doanh.\nTrở thành thành viên trong Khối CNTT với vai trò Data Scientist, các bạn sẽ được tham gia các khóa đào tạo nội bộ và quốc tế về các bước để ứng dụng PTDL tạo ra doanh thu; được tham gia các dự án thực tế, được sử dụng các công cụ Data Visualization hàng đầu như Tableau, QLik, ... Được trải nghiệm tương tác với lượng dữ liệu khổng lồ (hàng trăm triệu khách hàng, hàng tỷ bản ghi dữ liệu, ....), được xây dựng các mô hình dữ liệu dựa trên các thuật toán học máy, học máy chuyên sâu, ...\nMô tả công việc:\n- Xây dựng, đánh giá, fine tune các model ML, statistics để giải quyết use case của dự án theo yêu cầu và giải pháp đã có.\n- Xác định, thực thi các phương pháp chuẩn hoá, biến đổi, tổng hợp, trích chọn dữ liệu phù hợp để xây dựng feature cho các thuật toán ML.\n- Phối hợp với data analyst để thực hiện triển khai sample test / pilot dựa trên output của model.\n- Xây dựng các tài liệu theo quy trình, quy định và các tài liệu khác để trình bày giải pháp, phương pháp xây dựng và sử dụng kết quả của model.\nYour skills and experience:\n- TA 550 TOEIC hoặc tương đương.\n- Kiến thức về các thuật toán machine learning cơ bản: decision trees, linear regression, ensemble (random forest, boosting tree), k-means, SVM…\n- Kiến thức về các thuật toán deep learning phổ biến: CNN, LSTM, RNN…\n- Kiến thức về thống kê, phân tích khám phá dữ liệu (Exploratory Data Analysis - EDA).\n- Kiến thức về lập trình, cấu trúc dữ liệu & giải thuật, lý thuyết đồ thị.\n- Kiến thức về xác suất thống kê, đại số tuyến tính, giải tích.\n- Kỹ năng sử dụng thành thạo một trong các thư viện machine learning (scikit-learn, pyspark ML, TensorFlow, Keras).\n- Kiến thức về xử lý dữ liệu phân tán, xử lý dữ liệu lớn (Hadoop, Spark) - optional.\n- Kỹ năng sử dụng ngôn ngữ lập trình: R, Python.\n- Kỹ năng sử dụng ngôn ngữ SQL.\n- Kỹ năng xây dựng luồng ETL.\nWhy you\'ll love working here:\n- Đãi ngộ:\n   # Dẫn đầu thị trường\n   - Cơ hội được làm việc tại Tập đoàn tiên phong mở đường , kiến tạo tương lai thông minh, gắn kết của Việt Nam.\n   - Cơ hội được thử sức trong những lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n   # Môi trường năng động sáng tạo\n   - Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo theo cách riêng.\n   - Được khơi gợi cảm hứng làm việc với văn phòng xanh, không gian mở, hiện đại tiêu chuẩn quốc tế.\n   # Cơ hội thử thách và phát triển\n   - Áp dụng kiến thức, kĩ năng, kinh nghiệm chuyên môn giải quyết các bài toán hấp dẫn, thử thách tại Viettel.\n   - Cơ hội thử sức ở nhiều lĩnh vực, sản phẩm và quốc gia khác nhau góp phần thay đổi xã hội.\n   - Viettel cam kết cho bạn nền tảng vững chắc để học hỏi và phát triển.\n   - Sẵn sàng trao quyền, cơ hội đột phá cho những người trẻ tuổi.\n   - Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n   - Cơ hội được đào tạo, trao dồi kĩ năng định kỳ và nhu cầu thực tế.\n   # Chế ngộ đãi ngộ hấp dẫn, cạnh tranh\n   - Lương thưởng cạnh tranh trên thị trường, phản ánh đúng năng lực thực tế.\n   - Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày.\n   - Thưởng thức bữa trưa thơm ngon tại Tập đoàn, được chọn lọc bởi các chuyên gia dinh dưỡng.\n   - Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building thú vị.\n   - Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.\nViettel tuyệt đối không thu bất cứ khoản tiền nào của ứng viên khi nộp hồ sơ tham gia dự tuyển và khi vào làm việc tại Viettel nếu trúng tuyển.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Keangnam Landmark Tower 72, Pham Hung, Nam Tu Liem, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(568, 401, 2, 'Senior Java Software Engineer (AWS,MongoDB)', 'Top 3 reasons to join us\n- Môi trường tốt, cơ hội học hỏi và thăng tiến\n- Sản phẩm chất lượng\n- Lương top market, thưởng cao\n\nJob description\n- Design and build RESTful APIs to meet product requirements from designs and specifications.\n- Implement backend services and integrations using Java and relevant frameworks/libraries.\n- Follow best practices for API design, documentation, testing, security and performance.\n- Collaborate closely with other teams such as product, design and front-end to ensure alignment.\n- Contribute to architecture decisions and continually improve code quality.\n\nYour skills and experience\n- Minimum 3 years of experience developing backend software using Java\n- Proficient with Java, Spring Boot/Micronaut frameworks for RESTful API development\n- Experience with MongoDB and PostgreSQL databases\n- Experience with AWS cloud infrastructure is a plus\n- Bachelor\'s degree in Computer Science or related field\n- Familiarity with source control tools like Git and agile methodologies like Scrum.\n\nWhy you\'ll love working here\n- Lương top market\n- Lương tháng 13 + Performance bonus (1 năm/1 lần)\n- Xét tăng lương 1 năm/ 1 lần\n- Môi trường tốt, cơ hội học hỏi và thăng tiến rõ ràng\n- Lương: 30.000.000 - 50.000.000 VND/ tháng (Net)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '458/14 Ba Thang Hai Street, Ward 12, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(569, 432, 2, 'Senior Salesforce Engineer', 'Top 3 reasons to join us:\n1. Attractive Package and Dedication bonus\n2. Hybrid and flexible working environment \n3. Working directly with Agile global teams\n\nJob description:\n- Provide Salesforce Commerce Cloud (SFCC) technology expertise for solution design and technical implementation\n- Translate business and marketing challenges into well-designed solutions.\n- Design, code, unit test, and code review iterative improvements to the platform.\n- Collaborate cross-functional team to determine the best path for Salesforce platform implementation.\n- Drive technical process improvements to site release strategy\n- Ensure adherence to sound architecture.\n- Maintain and document processes/procedures and provide seamless hand-off to business users to utilize.\n- Technical complexity reduction\n- Improve and maintain engineering guidelines\n- Stay current with digital commerce technology\n- Stay in tune with the latest Salesforce technology updates, changes, community, and roadmaps.\n- Understand the ins and outs of complex technology environments and know how to optimize solutions for efficiency and simplicity\n- Enjoy teaching and coaching the .NET development team and business team on how to best use Salesforce Commerce Cloud.\n\nYour skills and experience:\nMust have:\n- Certifications in Salesforce Commerce Cloud B2C (Preferred)\n- 3-5 years’ experience in implementing Salesforce Commerce Cloud B2C (Demandware) solutions.\n- 3-5 years hands-on experience in web technologies including: HTML, CSS, JavaScript, JSON, AJAX, jQuery, web analytics, XML, web services (SOAP/REST), and open source packages/libraries\n- Experience with Salesforce Commerce Cloud B2C Storefront Reference Architecture (SFRA).\n- Experience in the implementation of digital commerce components such as users, catalog, pricing, inventory, and payment\n- Experience in digital commerce integration, such as SFMC and ERP\n- Extensive development knowledge, specifically around server-side and client-side JavaScript.\n- Experience with git source control and collaboration tools such as JIRA, Confluence, Slack\n- Experience in agile development methodology.\n- Experience with web frameworks, interactive web development, and responsive web design\n- Experience with site speed optimization.\n- Experience and working knowledge of secure development practices.\n- Excellent written and verbal communication skills.\n- Ability to collaborate effectively with non-technical personnel.\n\nCandidate profiles:\n- Candidate should have a strong mix of technical and functional experience with eCommerce systems, including content management systems, back-end, and front-end development.\n- Must be able to efficiently manage multiple initiatives simultaneously and excel in a high-growth environment.\n- Must be highly motivated, a go-getter with great strengths in making decisions\n- Must be a solutions-oriented problem solver, highly analytical, and a strategic thinker.\n- Experienced in delivering using (hybrid) Agile methodology.\n- Excellent communication, mentoring, and team-building skills.\n\nWhy you\'ll love working here:\n- Attractive salary based on your performance.\n- Annual 13th month salary.\n- Dedication bonus will be paid once a year.\n- Premium healthcare insurance, Annual health checks up.\n- Hybrid working (1-day WFH per week).\n- Breakfast are available at office in early morning and snack in late afternoon.\n- Team building allowance.\n- Annual Company team building trip.\n- Clubs (Football, Badminton, Biking, Running, Chess, Music band).\n- Exclusive training programs for all staff in technical, soft skills and process.\n- English class.\n- Technical clubs.\n- Marriage allowance, having newborn baby allowance, bereavement allowance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3, toà nhà FLC Landmark - Ngõ 60, phường Dương Khuê, Mỹ Đình, Nam Tu Liem, Ha Noi; 364 Cong Hoa, Tan Binh, Ho Chi Minh; 162 Nguyễn Cơ Thạch, Phường Hoà Hải, Ngu Hanh Son, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(570, 433, 2, 'Data Engineer (SQL, MongoDB, Oracle, Java/Python)', 'MỤC ĐÍCH CÔNG VIỆC\n- Phối hợp cùng team IT để tối ưu tốc độ các phần mềm, nâng cao hiệu quả trải nghiệm người dùng.\n- Xây dựng các dự án mới theo yêu cầu của công ty.\n- Phối hợp vận hành hệ thống giao dịch chứng khoán (gồm Core system, Web trading, Mobile trading, Bảng giá và các hệ thống phụ trợ khác).\n\nNHIỆM VỤ VÀ TRÁCH NHIỆM\n- Thiết kế hệ thống dữ liệu: Thiết kế kiến trúc hệ thống ETL/ELT, data warehouse, data lake\n- Xây dựng pipeline: Phát triển và duy trì pipeline xử lý dữ liệu (ETL/ELT) từ nhiều nguồn khác nhau\n- Làm sạch và chuẩn hóa dữ liệu: Đảm bảo dữ liệu đầu vào đúng chuẩn, chất lượng cao\n- Quản lý và tối ưu hóa cơ sở dữ liệu: Xây dựng và tối ưu hóa các bảng dữ liệu lớn (big data) trên các hệ quản trị cơ sở dữ liệu\n- Tích hợp dữ liệu: Tích hợp dữ liệu từ các hệ thống CRM, ERP, ứng dụng nội bộ hoặc bên ngoài\n- Hỗ trợ phân tích dữ liệu: Hợp tác với Data Analyst, Data Scientist để cung cấp dữ liệu và tạo dataset phù hợp\n- Bảo mật & tuân thủ: Đảm bảo dữ liệu được xử lý đúng theo các quy định bảo mật và pháp lý (ví dụ: GDPR)\n- Giám sát và logging: Xây dựng hệ thống theo dõi pipeline, cảnh báo lỗi dữ liệu.\n\nYour skills and experience\nTrình độ học vấn: Tốt nghiệp Đại học/ Cao đẳng trở lên\nChuyên ngành: Công Nghệ Thông tin\nKiến thức chuyên môn: \n- Sử dụng thành thạo Hệ điều hành Windows và Linux\n- Kiến thức vững về cơ sở dữ liệu quan hệ và phi quan hệ (PostgreSQL, MySQL, MongoDB, SQLServer, Oracle…).\n- Thành thạo các công cụ ETL: Apache Airflow, Talend, dbt…\n- Kinh nghiệm với hệ thống lưu trữ dữ liệu: Data warehouse (BigQuery, Redshift, Snowflake).\n- Thành thạo SQL, Python (hoặc Scala, Java)\n- Quen thuộc với hệ thống phân tán: Kafka, Spark, Hadoop\n- Có hiểu biết về CI/CD, DevOps là một lợi thế\n- Có khả năng tổng hợp dữ liệu ở các nguồn dữ liệu khác nhau để tạo report.\n\nKinh nghiệm: \n- Từ 1-3 năm kinh nghiệm trong vai trò tương đương (Junior/Medior/Senior)\n- Ưu tiên có kinh nghiệm trong lĩnh vực chứng khoán, tài chính.\n\nKỹ năng mềm:\n- Kỹ năng làm việc độc lập, làm việc nhóm tốt\n- Tư duy logic và khả năng giải quyết vấn đề\n- Cẩn thận, tỉ mỉ, có trách nhiệm cao trong công việc\n- Chủ động học hỏi công nghệ mới.\n\nWhy you\'ll love working here\nThu nhập:\n- Lương theo năng lực\n- Thưởng KPI theo hiệu quả công ty & cá nhân\n\nPhúc lợi:\n- Bảo hiểm sức khỏe cao cấp, khám sức khỏe định kỳ hàng năm\n- Tài trợ chi phí lấy chứng chỉ hành nghề, đào tạo chuyên môn\n\nMôi trường làm việc:\n- Văn phòng tại Quận 1, TP.HCM\n- Thời gian làm việc: 8h15 - 17h00 (Thứ 2 đến Thứ 6), nghỉ Thứ 7 & Chủ nhật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lầu 2, số 6 Hồ Tùng Mậu, Phường Nguyễn Thái Bình, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(571, 434, 2, 'Senior Tester', 'We’re looking for a Senior Tester who will define, implement test strategy, design test and execute manual test as well as create automation test scripts for web based, Mobile app products.\n\nThe main responsibilities of the Senior Tester include:  \n- Analyze Business Requirements, create test plan & develops test cases, automation scripts and execute manual testing, automated testing.  \n- Design, develop and execute test automation frameworks and test automation suites for multi-projects.  \n- Assist in the training/mentoring of other members.  \n- Perform Web Application Performance Testing and Security Testing.\n\nYour skills and experience:\n- Strong skills in analyzing requirement, defining test strategy and designing test  \n- Minimum 3 years of experience in Manual Testing and 1 year in Automation Testing (e.g., Selenium, Playwright,..)  \n- Web testing experience is mandatory; mobile application testing is a strong plus.  \n- Background in Manual and Automation Testing with GUI test, Selenium, Robot Framework or VS Coded UI is preferred  \n- Prior work experience with databases and SQL  \n- Must have experience working Test methods, with white box, black box, etc.  \n- Hands-on experience with collaboration and project management tools such as Jira, Microsoft Teams, DevOps and Confluence.  \n- Experience in API testing  \n- Experience with CMS/Ecommerce (Optimizely, Umbraco, Kentico,..) or migration testing is a plus  \n- ISTQB certification is a significant advantage.  \n- Logical thinking required as engineers  \n- Good at presentation, report writing skills, communication skills, problem solving skills, analytical skills, attention to details  \n- Ability to work independently, self-directed as well in a team  \n- Have a high sense of responsibility  \n- Attitude to learn new technologies quickly  \n- Good verbal and written communication skills (English & Vietnamese)  \n\nWhy you\'ll love working here:\n- Attractive salary with bi-yearly review, 13th-month bonus, performance bonus, public holiday bonuses, birthday gift, employee service awards up to $1,000  \n- Opportunities to join global technical conferences  \n- A clear career path with proper training courses, workshops, fully sponsored certificate exams  \n- Advanced AON health insurance (during labor contract) and accident insurance (during probation) in addition to the regulated insurances  \n- Professional, flexible & dynamic working environment that is diversified with different nationalities, open-minded, creative, supportive, friendly, and encouraging  \n- Regular communication from Management on the company’s strategy, development plan, and new opportunities to employees  \n- Bright working space with modern facilities including the newest software  \n- Employees and families are engaged and taken care of by the company via Trade Union activities  \n- Summer vacation at 5-star resort  \n- Sports & cultural activities all year around to strengthen both your physical & mental health  \n- NICEF - our own Charity program where our employees raise funds and help people with difficulties in Vietnam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Unit 2.3, 2nd Floor, Etown 1, 364 Cong Hoa street, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(572, 435, 2, 'System Admin (Linux, AWS)', 'Job description\n- Be responsible for managing, operating, and ensuring security for operating systems: Installation, configuration setup, operation, backup, monitoring, troubleshooting, and system recovery.\n- Manage, monitor, support implementation partners, and deploy systems or virtualization platforms, cloud, high-performance systems, and other systems related to Linux, Windows Server, virtualization platforms, cloud...\n- Document the managed systems.\n- Collaborate closely with other technical teams within the company and partners to fulfill tasks and projects effectively.\n\nYour skills and experience\n- At least 2 years of experience in infrastructure and systems, including over 2 years in Linux deployment and management.\n- Ability to work independently in monitoring and troubleshooting internal network systems and Linux servers (Ubuntu, CentOS, Oracle).\n- Proficiency with system management tools, techniques, and resources on Linux: FTP, SSH, NFS, NIS, MySQL, MS SQL, Git/SVN, Ansible, Docker, Kubernetes, etc.\n- Experience and strong knowledge of virtualization platforms: vCenter, Proxmox, Verge IO, XenServer…\n- Experience with AWS.\n- Expertise in security hardening for Linux and Windows Server, with the support of the security team.\n- Be able to communicate in English regarding technical matters.\n- Eagerness to learn.\n- Candidates with the following will be advantageous:\n- Experience with managing other cloud infrastructures besides AWS, such as Alibaba Cloud, Azure, or GCP.\n- Experience in DevOps and infrastructure as code.\n\nWhy you\'ll love working here\n- 13th month salary.\n- Holidays and full annual leave in accordance with State regulations.\n- Participate in all insurances (social insurance, health insurance, unemployment insurance), enjoy full policies and regimes according to the Labor Law.\n- Dynamic and humane working environment Annual trip.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '366 Nguyễn Trãi, District 5, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(573, 436, 2, 'Product Owner, Thu nhập Upto 20M', '1. Nghiên cứu thị trường \n- Phân tích đối thủ: Đánh giá sản phẩm cùng phân khúc, nhận diện điểm mạnh/yếu, xu hướng công nghệ hoặc tính năng mới. \n- Hiểu người dùng: Thu thập insight từ khảo sát, phỏng vấn, hoặc dữ liệu để đề xuất cải tiến sản phẩm. \n\n2. Quản lý sản phẩm \n- Quản lý backlog: Có khả năng quản lý backlog hiệu quả, tối ưu hóa workflow phát triển sản phẩm. \n- Đề xuất giải pháp: Kết hợp giữa nhu cầu người dùng, khả năng kỹ thuật và business goal để cân bằng resource. \n- Làm việc chặt chẽ với đội ngũ Dev và QC để đảm bảo sản phẩm được phát triển theo đúng yêu cầu và tiến độ.\n\nYour skills and experience\n- Có ít nhất 1 năm kinh nghiệm trong vai trò Product hoặc các vị trí tương tự. \n- Có kinh nghiệm về phương pháp Agile/Scrum và kinh nghiệm làm việc với các đội ngũ phát triển Agile. \n- Có kỹ năng giao tiếp tốt \n- Có khả năng tìm hiểu, phân tích và giải quyết vấn đề một cách logic \n- Kỹ năng giải quyết vấn đề sáng tạo và tinh thần cầu tiến. \n- Có kinh nghiệm làm việc ở vị trí tương tự với các sản phẩm SaaS.\n\nWhy you\'ll love working here\n- Tham gia BHXH, BHYT, BHTN theo quy định.\n- Chế độ phép năm, sinh nhật, du lịch định kỳ hàng năm.\n- Lương tháng 13, thưởng Lễ- Tết, thưởng theo kết quả hoạt động kinh doanh công ty cuối năm.\n- Môi trường làm việc trẻ trung, năng động, thân thiện, vui vẻ\n- Hỗ trợ chi phí cho NV tham gia các khóa học đào tạo, nâng cao nghiệp vụ…\n- Và các chính sách phúc lợi hấp dẫn khác…\n- Cơ hội triển khai các dự án, tiếp xúc với những công nghệ mới nhất và học hỏi từ những đồng nghiệp giỏi, trở thành full-stack developer\n- Được tiếp xúc với nền tảng điện toán đám mây Amazon Web Services', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Nova Evergreen - 42/2 đường Nguyễn Văn Trỗi, phường 15, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(574, 437, 2, 'Nhân viên IT (Oracle, ERP, CRM)', 'Tiếp nhận và xử lý yêu cầu: \n- Nhận yêu cầu hỗ trợ từ người dùng qua điện thoại, email, ticket hoặc trực tiếp. \n- Ghi nhận thông tin, phân tích sự cố và đưa ra hướng xử lý kịp thời. \n- Phối hợp với các bộ phận kỹ thuật khác để giải quyết sự cố phức tạp. \n\nHướng dẫn và đào tạo người dùng: \n- Hướng dẫn sử dụng phần mềm (ERP, CRM, hệ thống nội bộ, v.v.). \n- Soạn tài liệu hướng dẫn sử dụng và quy trình thao tác. \n- Hỗ trợ đào tạo người dùng mới hoặc triển khai phần mềm mới. \n\nQuản lý và giám sát hệ thống: \n- Theo dõi hoạt động phần mềm, phát hiện sớm lỗi hệ thống. \n- Thực hiện cập nhật, nâng cấp phần mềm định kỳ. \n- Đề xuất cải tiến hệ thống để nâng cao hiệu suất và trải nghiệm người dùng. \n\nKiểm thử và triển khai phần mềm: \n- Tham gia kiểm thử các bản cập nhật, tính năng mới. \n- Hỗ trợ triển khai phần mềm đến các bộ phận sử dụng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lô 2-4-5 Khu CN Nam Thăng Long, Bac Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(575, 438, 2, 'Fresher-Junior Android Developer (Java/Kotlin)', 'Tham gia phát triển các hệ thống phần mềm trên hệ điều hành ANDROID , bao gồm:\n- Phân tích và phát triển các ứng dụng trên nền tảng Android.\n- Phối hợp với nhóm thiết kế để xác định các tính năng của ứng dụng.\n- Đảm bảo chất lượng và hiệu suất của ứng dụng theo thông số kỹ thuật.\n- Xác định các vấn đề tiềm ẩn và giải quyết các tắc nghẽn ứng dụng.\n- Sửa lỗi ứng dụng trước khi phát hành chính thức.\n- Thiết kế và triển khai các bản cập nhật ứng dụng.\n\nỨng viên có ít nhất 1 năm kinh nghiệm phát triển ứng dụng mobile native (Java/Kotlin).\nCó kinh nghiệm tích hợp các RESTful API và các SDK, thư viện trong quá trình phát triển ứng dụng.\nCó hiểu biết tốt về các thư viện và API của bên thứ ba, chẳng hạn như OKHTTP, RxJava, Firebase, Coroutine, Flow, Room.\nCó kiến thức về cấu trúc dữ liệu, giải thuật, lập trình hướng đối tượng.\nThành thạo sử dụng Git để quản lý mã nguồn\nCó kinh nghiệm test, debug và tối ưu hiệu năng cho ứng dụng\nKỹ năng giao tiếp, giải quyết vấn đề, kỹ năng làm việc nhóm tốt.\nĐiểm cộng nếu ứng viên có\n- Có kinh nghiệm làm việc với iOS swift\n- Đã tích hợp billing, admob vào dự án Android\n- Ứng viên có hồ sơ Github và/hoặc Stack Overflow đang hoạt động\n\nThời gian làm việc: Từ 8h00 – 17h30, Thứ 2 – Thứ 6 (nghỉ trưa 1,5 tiếng).\nLương up to 20M\nTăng lương định kỳ hằng năm theo năng lực.\nCompany trip hằng năm, team-building hằng tháng.\nThưởng dự án, thưởng kết quả kinh doanh, thưởng nóng, thưởng lễ Tết, lương tháng thứ 13,...\nMôi trường làm việc trẻ trung, năng động, vui vẻ\nNhân viên làm trên 2 năm trở đi được cộng thêm phép.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '74 Đỗ Pháp Thuận, Đà Nẵng, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(576, 439, 2, 'Scrum Master (Project Manager, Agile)', 'Techcom Securities (TCBS) đang tìm kiếm một Scrum Master cho bộ phận Công nghệ thông tin (CNTT) tại văn phòng Hà Nội. Ứng viên sẽ chịu trách nhiệm mang lại các giá trị cho các bên liên quan, trao quyền, dẫn dắt và hướng dẫn các lập trình viên tại các văn phòng khác nhau trong nhóm phát triển phần mềm thành công, tự sắp xếp công việc, và thích ứng nhanh với các thay đổi.\n\nĐây là cơ hội để bạn trở thành một thành viên trong đội ngũ ngân hàng đầu tư sáng tạo và uy tín hàng đầu Việt Nam!\n\nĐịa điểm: Hà Nội, Việt Nam\n\nTrách nhiệm bao gồm, nhưng không giới hạn:\n- Chịu trách nhiệm các quy trình cải tiến và mô hình phát triển phần mềm Agile trong nhóm\n- Ưu tiên loại bỏ các trở ngại và đào tạo nhóm giải quyết vấn đề\n- Xây dựng mối quan hệ mạnh mẽ, tin cậy với các bô phận kinh doanh, nhóm khách hàng và trong nội bộ nhóm, bằng cách giúp nhóm làm việc minh bạch và quản lý các vấn đề phát sinh\n- Duy trì sự tập trung của nhóm vào các giá trị và kết quả mang lại cho khách hàng, cũng như tối ưu hoá các chuỗi công việc\n- Dẫn dắt nhóm theo văn hoá liên tục cải tiến, giảm tải lãng phí\n- Dẫn dắt nhóm liên tục hoàn thành công việc\n- Giúp nhóm đạt được tiến độ công việc ổn định, cũng như môi trường cho sự cải tiến và học tập\n- Phát triển, theo dõi và trao đổi các báo cáo và thông số làm việc cho nhóm\n- Đào tạo nhóm về các nguyên tắc và thực tiễn mô hình Agile để nhóm phát triển và đạt hiệu suất, năng suất cao hơn\n- Hỗ trợ việc phát triển, lập kế hoạch và hoàn thành danh mục công việc cho nhóm\n\nKỹ năng và kinh nghiệm của bạn:\n- Cử nhân Công nghệ thông tin và/hoặc Kinh doanh hoặc các chứng chỉ chuyên ngành\n- Chứng chỉ Scrum Master/Iteration Manager và có kinh nghiệm áp dụng sâu sắc\n- Ít nhất 3 năm kinh nghiệm được chứng minh phù hợp\n- Kinh nghiệm làm việc cho các tổ chức lớn\n- Kinh nghiệm dẫn dắt nhóm với các thành viên ở các văn phòng khác nhau\n- Ít nhất 1 năm kinh nghiệm trong vai trò Scrum Master/Iteration Manager\n- Kỹ năng xuất sắc trong việc dẫn dắt nhóm bao gồm: huấn luyện, giải quyết các xung đột và khuyến khích thảo luận nhóm về các phương án, giải pháp thay thế.\n- Kinh nghiệm truyền tải, thúc đẩy và dẫn dắt các nguyên tắc và thực tiễn mô hình Agile\n- Kỹ năng giao tiếp tiếp, bao gồm kỹ năng thương lượng và gây ảnh hưởng.\n\nTại sao bạn sẽ yêu thích làm việc ở đây:\n- Review lương 1 lần/ năm\n- Cán bộ nhân viên sẽ có từ 12- 15 ngày phép/ năm\n- Bảo hiểm AON cho Cán bộ nhân viên\n- Công ty có các CLB thể thao sinh hoạt hàng tuần (đá bóng, chạy bộ, cầu lông)\n- Team building 1 lần/ 1 năm theo tiêu chuẩn 5 sao\n- Môi trường làm việc trẻ, năng động, cơ hội phát triển cao\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hội sở Techcombank, 6 Quang Trung, Trần Hưng Đạo, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(577, 440, 2, 'Backend Developer (Laravel/ MySQL/ PostgreSQL)', 'Job description\n- Thiết kế, phát triển và duy trì các dịch vụ phụ trợ bằng Laravel và ecosystem của Laravel .\n- Tối ưu hóa truy vấn cơ sở dữ liệu để đảm bảo hiệu suất và khả năng mở rộng của hệ thống.\n- Triển khai và duy trì API RESTful cho giao diện người dùng và tích hợp của bên thứ ba.\n- Đảm bảo các biện pháp bảo mật tốt nhất được tuân thủ trong hoạt động API và cơ sở dữ liệu.\n\nNgoài ra\n- Làm việc chặt chẽ với nhóm nghiệp vụ để chuyển đổi các yêu cầu thành các giải pháp kỹ thuật.\n- Viết code sạch, hiệu quả và dễ bảo trì theo các chuẩn ISO đưa ra.\n- Thực hiện đánh giá mã và đóng góp vào việc cải thiện quy trình phát triển.\n- Cập nhật những xu hướng mới nhất về Laravel và các công nghệ liên quan.\n\nYour skills and experience\n1. Bắt buộc\n- Có ít nhất 3 năm kinh nghiệm làm việc với Laravel trong môi trường sản xuất.\n- Thành thạo MySQL/PostgreSQL , bao gồm tối ưu hóa truy vấn và thiết kế cơ sở dữ liệu.\n- Kinh nghiệm xây dựng và tích hợp API RESTful .\n- Quen thuộc với Git và làm việc trong môi trường phát triển cộng tác.\n- Bằng Cử nhân (hoặc cao hơn) chuyên ngành CNTT hoặc các lĩnh vực liên quan, ưu tiên ứng viên đến từ các trường đại học hàng đầu.\n\n2. Ưu tiên\n- Kinh nghiệm với VueJS (Vue 3) , bao gồm phát triển dựa trên thành phần.\n- Kinh nghiệm xây dựng và tích hợp API RESTful.\n- Có khả năng làm Frontend cùng với Vuejs (Vue3)\n\nWhy you\'ll love working here\n- Tiền lương: thoả thuận khi phỏng vấn\n- Phụ cấp ăn trưa\n- Được làm việc trong môi trường năng động, hiện đại.\n- Tạo điều kiện học hỏi và nâng cao khả năng chuyên môn.\n- Được hưởng các chế độ BHXH, BHYT, BHTN, tham quan, nghỉ phép, thưởng năng suất, nghỉ các ngày lễ theo quy định của Luật lao động hiện hành.\n- Nơi làm việc: Bệnh viện Đa Khoa Phương Đông (Số 9, Phố Viên, Cổ Nhuế 2, Quận Bắc Từ Liêm, Hà Nội)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bệnh viện đa khoa Phương Đông. Số 9, Phố Viên, phường Cổ Nhuế 2, Bac Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(578, 441, 2, 'Middle/ Senior iOS Developer - Up to 3200$', 'Top 3 reasons to join us\n• Competitive salary packages.\n• Dynamic and open-sharing working environment.\n• Hybrid and flexible working mode.\n\nJob description\nAbout the job\nOur team is growing because our customer is growing, which means we need you!\nWe are looking for an experienced (Senior) iOS Engineer to join our Spartan Team. Who is passionate about building, testing, and working closely with various stakeholders to deliver top-notch software. You will be able to solve challenging problems, work with the latest tech stack, and work with talented engineers to contribute meaningfully.\n\nResponsibilities\n• Be part of the engineering team where we architecture and implement new features.\n• Build iOS applications for various startups.\n• Strong focus on high-quality mobile UI.\n• Work closely with various business partners (backend, UI/UX).\n• Writing functional and integration tests.\n\nYour skills and experience\nWhat we\'ll love about you\n• Fluent in English, able to communicate directly with customers\n• Bachelor\'s degree in Computer Science or related field.\n• 3+ years of experience with native iOS development.\n• Excellent understanding of computer science fundamentals, data structures, and algorithms.\n• Experience developing native iOS applications in SwiftUI\n• Deep understanding of the value of dependency injection and testing.\n• Experience with one of the following iOS architecture patterns: MVP, MVVM, MVI.\n\nWhy you\'ll love working here\n• 100% salary during probation\n• Competitive compensation packages\n• Diamond package Health care from Bao Viet Insurance\n• Provide lunch meals for interns.\n• Technical, Soft skills, English Training courses\n• An open and transparent culture where people are valued, treated fairly, trusted, and empowered\n• Training and career development opportunities\n• Flexible Working Time and Hybrid Working - Working from anywhere!\n• Device Provided with latest Macbook Pro\n• Happy Hour, Company Trip, Year End Party, and many other events\n• Unlimited paid time off (PTO) - You are entitled to Unlimited Paid Time Off as long as you deliver!\n• Sponsoring sports participation costs - We have play hours where our team meets up for PS5 Gaming and Football sessions, also with Strava Yearly Subscription\n• Challenging yourself with high and difficult goals by participating in unprecedented business models in the market.\n• Working in an environment that is highly flexible and open, eager to incubate any valuable idea.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '29 Nguyễn Văn Mai phường 8, District 3, Ho Chi Minh and 47 My Da Tay 6, Ngu Hanh Son, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(579, 442, 2, 'Mid/Senior Backend Engineer (Python/Java/Go preferred)', 'Our mission and where you fit in\nAt Employment Hero, we’re an ambitious bunch of people on a mission to make employment easier and more valuable for everyone.\nOur world-class software is the easiest way for businesses to manage HR, payroll, employee engagement, and benefits.\nSince our inception in 2014, we\'ve had some pretty impressive growth (100% YoY), reached unicorn status in 2022, and now serve 300,000 businesses globally, with 2 million+ users on the platform. We have no plans to slow down. \nThere’s never been a more exciting time to join one of the fastest-growing SaaS unicorns, so let’s see if we could be a match!\n\nIn your role, you\'ll be focused on…\nAs a growing team, we need innovative and passionate Middle Backend Software Development Engineers to join our squads who will be a vital part of our engineering team, responsible for developing product features and collaborating with colleagues in design, product, and engineering. You will take ownership of writing automated tests for your production codes and work with cutting-edge technologies, focusing on tech stacks such as Ruby on Rails and ReactJS. In addition, you will have the opportunity to work on a diverse range of products and features.\n\nResponsibilities:\n- Develop and maintain both frontend and backend components of web applications using Ruby (80%) and ReactJS (20%)\n- Collaborate with product team to gather requirements and translate them into technical solutions\n- Contribute to the technical strategy and delivery of your squad and take part in scrum ceremonies.\n- Ensure high-quality code by conducting testing and code reviews, both for yourself and your colleagues.\n- Share your knowledge and mentor Junior Developers within your squad.\n- Collaborate with highly respected Software Development Engineers in a high performing and supportive environment.\n- Demonstrate your passion for working on highly complex and technically challenging development projects.\n- Enhance legacy features for our award-winning HR tech platform.\n\nYour skills and experience\nYou’re the hero we’re looking for if:\n- Over 3 years of experience in Software Development, with a focus on Server-side and RESTful API Development and integration.\n- Proficiency in OOP languages such as Python, NodeJS, Java, Go, PHP, etc., is highly desirable, with the expectation that you are willing to learn Ruby upon joining our team.\n- Demonstrated experience implementing, maintaining and deploying full-stack web technologies\n- Strong skills in Object-Oriented Programming (OOP).\n- Strong understanding of standard Software Engineering processes, Testing, and Agile methodology\n- A team player that always puts colleagues ahead of yourself and has a highly adaptable and versatile approach to work\n- You are passionate about learning and sharing your knowledge, and not afraid to challenge your peers, but also welcome being challenged\n- You have experience in mentoring team mates, or even leading an Engineering squad\n- English language abilities, both written and verbal - you’ll be working with people across the world, including from Australia.\n\nIt’ll be great, but not essential, if you also have experience with:\n- Bachelor\'s degree in Computer Science of Software Engineering or an equivalent\n- Experience in developing highly modular mobile applications and mobile application performance tuning\n- Experience in translating design wireframes into functioning UI components\n- Experience in functional programming\n- Familiarity with AWS tooling and environments, including EC2, Kubernetes, etc.\n\nExperience is important, but for us the biggest measure of success is people who can live and breathe our EH Way of working. Show us what you can bring to the table, and we’ll empower you to let your talents shine.\n\nWhy you\'ll love working here\nWhy you love working here?\n- We are remote-first, where you can work from the comfort of your home, and enjoy flexible working time\n- Work your local hours! 40-hour work week, Monday to Friday\n- 100% Salary During Probation\n- A generous budget to spend on setting up your home office\n- We set you up for success with the latest and greatest hardware, tools and tech\n- Budgets towards continuing your learning\n- Annual Global Gathering in 1 week - Road to Dubai in 2025!!!\n- Refer friends to open jobs and receive a cash bonus for every successful referral you make\n- Participate in our Employee Share Options Program - you’ll be a part owner of Employment Hero.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cach Mang Thang 8, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(580, 411, 2, 'Data Engineer, Zalopay (Open to Senior)', 'As a Big Data Platform in Zalopay, we are developing a high quality data warehouse that can address business problems, provide data insight to each business aspect, transform product to Data-driven decision making manner.\n\nWe are seeking a highly skilled (Senior) Data Engineer to join our Data Platform team with a dedicated focus on data quality, observability, and governance. In this role, you will design and build core infrastructure and frameworks to ensure that our data is accurate, reliable, discoverable, and compliant. Your work will directly impact the trustworthiness and usability of data across the organization.\n\nResponsibilities:\n- Design and implement systems and frameworks to automate data quality checks, including profiling, validation, anomaly detection, and lineage tracking.\n- Define and enforce data quality standards, SLAs, and best practices across the data lifecycle.\n- Build and maintain data governance infrastructure, including metadata management, schema versioning, data cataloging, and access controls.\n- Collaborate with data engineers, analysts, and compliance teams to define and support data policies and compliance requirements (e.g., data retention, masking, auditing).\n- Integrate or extend open-source tools (e.g., Apache Atlas, Great Expectations, DataHub, etc.) into the platform.\n- Work with pipeline owners to ensure data observability and transparency across ingestion, transformation, and serving layers.\n- Lead efforts to document and communicate data governance strategies to stakeholders and promote a data-driven culture.\n\nYour skills and experience:\n- Bachelor’s degree in computer science, engineering, mathematics, or a related technical discipline.\n- 4+ years of experience as a Data Engineer working with large-scale data systems.\n- Proven hands-on experience in building or maintaining data quality frameworks and governance systems.\n- Strong understanding of data quality concepts, including data validation, profiling, anomaly detection, and rule-based checks.\n- Experience implementing or integrating tools for metadata management, data cataloging, and lineage tracking.\n- Solid experience in the Hadoop ecosystem (e.g., HDFS, Hive, Spark, YARN).\n- Have experience with NoSQL databases such as MongoDB, Elastic search.\n- Proficiency in one or more programming languages: Python, Java, Scala.\n- Familiarity with workflow orchestration tools such as Apache Airflow.\n- Knowledge of modern cloud computing platforms and concepts is a plus.\n\nSoft Skills:\n- Ability to work independently and as part of a team.\n- Strong organizational skills and the ability to manage multiple projects simultaneously.\n- Strong attention to detail, structured problem-solving skills, and ability to lead cross-functional initiatives.\n- Excellent communication skills and the ability to work closely with both technical and business teams.\n\nWhy you\'ll love working here:\nWe hope VNG is a place where you build your career. Whether you want to pursue to be a manager or focus on professional development, we acknowledge and appreciate your talents. Therefore, we open up to you more promotion opportunities in VNG, and designed program to help you succeed in every single career path.\n\nNO SUIT, NO TIE: At VNG, we do not have many rules because we respect you and want to make comfortable atmosphere to help employees perform their jobs well.\n\nCompany “pay” for you: Lunch, parking, swimming, learning English or gym for free and you know you are really in care.\n\nNO BARRIERS: Office of VNG is an open space because we always try to remove all barriers to help members easily shares with each other.\n\nBeing a big family: Like a gift for family day. A party for the kids. We know how much your family matters.\n\nNO RANK At VNG, members are encouraged to contribute ideas and debate with the others.\n\nBe explored: Ph.D., un-academic guy, bookish girl, fashion designers ... VNGers are different and this diversity makes life more colorful.\n\nNO "OFFICE": Office is like your home. You can hang paintings, plant trees, even feed aquarium on the desk.\n\nBe showed your best: VNGers like to "mortification" with the group games such as: Fansipan climbing, waterfall rafting, go over heat mats; there activities not only are tightening friendship, but also practice their bravery.\n\nGAMING: Even if you do not make the game, stealing beans in the boss’s garden or versusing with your colleagues in a sword competition play online is also an interesting way to relax.\n\nChanging the world: Creating an entertainment channel, building a social network and developing a game. On the Internet world, every single thing you did can change the lives of many people.\n\nLet’s join VNG to share our mission: \'MAKE THE INTERNET CHANGE VIETNAMESE LIVES\'.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'VNG Campus, Tân Thuận Đông, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(581, 443, 2, '03 Backend Dev (Java, C#, Typescript, NodeJS, .NET)', 'Job description\n- Tham gia phát triển các hệ thống backend theo yêu cầu dự án, sử dụng một trong các ngôn ngữ: .NET Core, Java (Spring Boot), hoặc Node.js.\n- Thiết kế, xây dựng và bảo trì API RESTful phục vụ frontend/web/mobile.\n- Làm việc với cơ sở dữ liệu: SQL Server, MySQL, hoặc MongoDB.\n- Viết code rõ ràng, có cấu trúc, dễ bảo trì.\n- Tham gia cùng team phân tích yêu cầu, ước lượng và triển khai chức năng.\n- Fix bug, xử lý lỗi kỹ thuật, tối ưu hiệu năng hệ thống.\n\nYour skills and experience\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học, Cao Đẳng chuyên ngành CNTT hoặc có chứng chỉ tương đương từ 1-3 năm.\n- Thành thạo các ngôn ngữ Java, C#, Typescript, Javascript...\n- Thành thạo các môi trường phát triển Java, .Net, Node.js.\n- Có thể viết thành thạo các câu truy vấn dữ liệu từ CSDL.\n- Có thể sử dụng thành thạo các framework: Spring boot, JPA/Hibernate, EF.\n- Có thể triển khai ứng dụng trên các môi trường Linux, Docker, K8s.\n- Có thể phân tích yêu cầu và đưa ra thiết kế về ứng dụng.\n- Có hiểu biết về Elastic Search, Redis, message broker...\n- Có hiểu biết về các mô hình phát triển ứng dụng.\n- Có hiểu biết về lập trình an toàn thông tin.\n- Có hiểu biết về mạng và giao thức mạng.\n- Có khả năng tư duy tốt.\n- Đọc hiểu tài liệu bằng tiếng Anh.\n\nƯu tiên ứng viên:\n- Có thể lập trình fullstack.\n- Có kinh nghiệm làm việc trong các dự án lớn, làm việc theo quy trình.\n- Có khả năng lãnh đạo nhóm.\n- Có khả năng làm việc độc lập, tìm hiểu công nghệ mới.\n- Có khả năng tìm giải pháp, gỡ lỗi.\n- Có thể làm việc ngoài giờ hành chính, ngày nghỉ, đi công tác xa.\n\nWhy you\'ll love working here\n- Thu nhập:\n  - Lương từ 15 triệu/tháng tùy theo kinh nghiệm, công nghệ chính.\n  - Lương làm thêm giờ nếu phải làm ngoài giờ theo yêu cầu công việc.\n  - Lương tháng 13, thưởng cuối năm, thưởng dự án...\n- Thời gian làm việc:\n  - Thời gian làm việc 8h/ngày, 5 ngày/tuần: từ 8h30 đến 17h30 (có thể thay đổi cho phù hợp với mùa, điều kiện giao thông, dịch bệnh... nhưng không quá 8h/ngày, 5 ngày/tuần)\n  - Có chế độ nghỉ phép, nghỉ lễ, nghỉ hiếu, hỉ... theo quy định của luật lao động.\n- Khác:\n  - Được cung cấp đầy đủ trang thiết bị để làm việc.\n  - Được tham gia BHXH, BHYT, BHTN theo quy định của luật.\n  - Được xét tăng lương 6 tháng/lần hoặc chủ động đề xuất tăng lương nếu thấy mình có năng lực.\n  - Được thoải mái đóng góp ý kiến với các chế độ, chính sách hay môi trường làm việc của công ty nhằm nâng cao hiệu quả làm việc, sáng tạo.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'số 90 phố Trung Kính, phường Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(582, 253, 2, 'Unity Game Developer - MINTROCKET', 'Top 3 reasons to join us\n- 13th Month salary, work 5 days a week\n- Annual Company Trip, Quarterly team building\n- Premium health insurance, Support sport clubs\n\nJob description\n- Develop game content using the Unity engine\n- Develop tools necessary for game production and collaboration\n\nYour skills and experience\nQualifications\n- Experience in game development using the Unity engine\nGeneral Competencies\n- Passion and dedication for game development\n- Ability to read, write, and communicate in English\n- Positive mindset and proactive communication skills\n- Strong sense of responsibility for assigned tasks\n- Logical thinking and creative problem-solving skills\nJob-Specific Skills\n- Proficiency in C# programming\n- Understanding of 2D/3D programming\n- Knowledge and implementation of data structures and algorithms\nPreferred Qualifications\n- Understanding of game physics and mathematics\n- Experience in client profiling and optimization\nOur recruitment process:\n1. Application screening (Resume in English is required)\n2. An offline test\n3. F2F Interview (Only 1 round)\n4. Job offer\n\nWhy you\'ll love working here\n- Chance to work on global projects with multicultural teams, world-class games.\n- Attractive salary and benefits.\n- Professional work environment.\n- Open culture where every employee is valued, treated fairly and trusted.\n- 13th salary every year at least 1-month salary.\n- From 12 days Annual Leave\n- Government social, health, and unemployment insurance.\n- Lunch Allowance\n- Annual salary review based on employee performance and company success\n- Annual Company Trip, Year End Party\n- Events during Birthday, Full Moon Festival, other important holidays.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UOA Tower, 11th Floor, 06 Tan Trao Street, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(583, 444, 2, 'Product Owner (Agile, Scrum)', 'Là cầu nối giữa các bên liên quan (Business, Tech, UI/UX, Marketing...) nhằm xác định rõ nhu cầu và chuyển hóa thành yêu cầu phát triển sản phẩm.\nQuản lý backlog sản phẩm, viết user stories, mô tả tính năng và ưu tiên theo giá trị kinh doanh.\nLàm việc chặt chẽ với đội ngũ phát triển để đảm bảo đúng tiến độ, chất lượng và mục tiêu của sprint.\nKiểm thử và xác nhận tính năng sau khi phát triển (UAT).\nTheo dõi, đo lường hiệu quả sản phẩm sau khi release và đề xuất các cải tiến liên tục.\nHỗ trợ xây dựng tài liệu sản phẩm, release notes và hướng dẫn sử dụng cho người dùng nội bộ hoặc khách hàng.\nTối thiểu 1–2 năm kinh nghiệm ở vị trí Product Owner, hoặc các vai trò liên quan đến phát triển phần mềm.\nCó khả năng hiểu nhanh mô hình sản phẩm, phân tích nhu cầu người dùng và viết tài liệu rõ ràng.\nKỹ năng giao tiếp tốt, có thể truyền đạt nhu cầu và mục tiêu sản phẩm một cách rõ ràng cho team kỹ thuật.\nBiết cách làm việc trong môi trường Agile/Scrum là lợi thế.\nChủ động, có tư duy logic và khả năng giải quyết vấn đề.\nƯu tiên ứng viên có kinh nghiệm làm sản phẩm nội bộ, SaaS hoặc nền tảng số.\nMức lương: upto 20tr\nReview lương 6 tháng/lần \nQuỹ lương 14-16 tháng/năm\nThưởng quý, lễ, Tết, lương tháng 13\nCác chế độ theo Luật Lao động: BHXH, ngày phép,...\nTrợ cấp gửi xe, trà cafe miễn phí, hỗ trợ các chi phí khác theo nhu cầu công việc.\nĐược tham gia các sự kiện, du lịch, team building, happy hours,...\nMôi trường làm việc trẻ trung, năng động.\nThời gian làm việc: 8h30 – 12h30; 14h00 – 18h00; từ thứ 2 đến thứ 6; 2 thứ 7 cách tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 4- Số 11 Nguyễn Xiển - Thanh Xuân - Hà Nội , Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(584, 445, 2, 'Senior Backend Engineer (Golang, Java, Python)', 'Cho Tot team is expanding to continuously innovate our marketplace ecosystem to better serve Vietnamese via advanced technology. We are looking for talented and passionate individuals to join our foundation software, engineering team. You will be one of the few key talents who build and run services that are used by tens of millions of Vietnamese people. You will need to tackle highly scaled distributed systems, work in a highly automated devops environment on top of many open source, CNCF software. You will be supported by our solid SRE team to really craft the software and run the product that you are proud of and other engineers admire.\n\nWhat you will do:\n- Solve engineering problems to enable a smart Marketplace ecosystem of products and services.\n- Design, Build, Run and improve backend services and framework of creating microservices.\n- Manage individual project priorities, deadlines, and deliverables.\n- Improve engineer efficiency with common libraries, tooling, and platform.\n\nYour skills and experience:\n- At least 4 years of experience in Golang or confident that you can pick it up in no time.\n- Solid production experience with one or more general-purpose programming languages including but not limited to C/C++, Python, Java, Javascript ES6.\n- Experience working with one or more from the following: web application development, Unix/Linux environments, distributed systems, machine learning, networking, developing large software systems.\n- Experience with two or more data systems but not limited to Postgres, MongoDB, Elasticsearch, Redis, Kafka, Cassandra.\n- Experience with Docker, Kubernetes.\n- Familiar with Microservices, event-driven architecture.\n- BA or MA degree in engineering, computer science, or another technical related field. Or formerly competitive programmer.\n\nWhy you\'ll love working here:\n- Join plenty of Sharing and Learning activities as part of our initiatives to contribute to the tech community in Vietnam.\n- Get 15 days of annual leave and 5 days of sick leave per year.\n- Health insurance for employee.\n- Get 13th month salary and annual performance bonus.\n- Participate in regular team building activities and company parties.\n- Get opportunities to attend training courses abroad.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UOA Tower - 6 Tan Trao, Tan Phu, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(585, 446, 2, '[Da Nang] Junior Developer (Python/NodeJS/ReactJS)', 'PASONA VIETNAM is a 100% Japanese-owned company specializing in producing software and providing information technology services for domestic and foreign companies. Due to our business expansion, we need to recruit more Programmers (Developers) with the following job content:\n\n- Develop, maintain, and upgrade applications based on client requirements.  \n- Analyze, design, and build software in collaboration with the team.  \n- Implement new features from specification to deployment.  \n- Communicate, attend online meetings, and exchange requirements with Japanese clients.  \n- Research, learn, and apply new technologies in projects.  \n- Participate in various projects and multitask when necessary.  \n- Adhere to software development processes following Agile principles.  \n- Propose ideas to improve project efficiency and quality.\n\nWorking hours:\nMon - Fri, 8:00 - 17:00\n\nRequirements:\n- 6 months - 2 years of experience in software development, especially in outsourcing/offshore projects.  \n- Proficiency in at least one programming language: Python or JavaScript/TypeScript (ReactJS, NodeJS).  \n- Familiarity with software development methodologies such as Agile/Scrum or Waterfall.  \n- Experience with databases like MySQL or PostgreSQL, including query optimization.  \n- Proficiency in version control tools like Git/GitLab.  \n- Have knowledge about Docker, Container and CI/CD.  \n- Strong problem-solving skills, logical thinking, and the ability to work independently.\n\nPreference:\n- Experience working in a Japanese company  \n- Communication skills in Japanese\n\nWhy you\'ll love working here:\n- Experience to learn large-scale development project  \n- As the team isexpending, you may participate as a core member  \n- Professional, stable and friendly working environment  \n- Compulsory insurance and overtime payment on the TOTAL SALARY under the labor contract  \n- Holiday on the occasion of company establishment day annually besides the holidays in accordance with the law  \n- Quarterly birthday party, annual health check', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '243 Phan Dang Luu, Khue Trung Ward, Cam Le, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(586, 186, 2, 'UI Designer (UI-UX)', 'Job description\n- Thiết kế UI cho các sản phẩm\n- Thiết kế UI cho Website và Landing Page nhằm giới thiệu dịch vụ, sản phẩm hoặc chiến dịch Marketing của công ty.\n- Thiết kế UI cho hệ thống CMS giúp khách hàng dễ dàng quản lý nội dung, kênh, và người dùng.\n- Tham gia vào việc bổ sung, chuẩn hóa, hoàn thiện Product Design System: Foundation, Components, Patterns, Design Tokens và Guidelines dùng cho lập trình viên triển khai đồng bộ.\n- Phối hợp với team sản phẩm để trình bày ý tưởng qua các Product Concept, tạo slide, hình ảnh minh họa giúp đội ngũ kinh doanh, marketing hoặc đối tác dễ hiểu.\n- Ứng dụng AI để tăng tốc thiết kế, tiết kiệm thời gian.\n- Làm việc chặt chẽ với BA, UX Designer, Product Manager, Developer để đảm bảo sản phẩm được thiết kế đúng mục tiêu, dễ triển khai và thân thiện với người dùng.\nYour skills and experience\n- Sử dụng thành thạo các phần mềm thiết kế ( Illustrator, Pigma, v.v.)\n- Kinh nghiệm: từ 5 năm trở lên \n- Yêu cầu: Có portfolio (hồ sơ năng lực cá nhân)\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\nWhy you\'ll love working here\n- ✨ CHẾ ĐỘ PHÚC LỢI HẤP DẪN TẠI CÔNG TY ✨\n- Thu nhập cạnh tranh:\nMức lương hấp dẫn, thưởng tháng 13 và thưởng thâm niên.\nThưởng theo hiệu quả công việc, xét thưởng vào các dịp Lễ – Tết.\nĐánh giá tăng lương 1 lần/năm, trường hợp nổi bật sẽ được xét tăng lương ngay tại thời điểm.\n- Chế độ nghỉ phép:\n12 ngày nghỉ phép có lương mỗi năm theo quy định – nghỉ thoải mái, vẫn nhận lương đầy đủ.\n- Sự kiện nội bộ ấm áp:\nHàng năm tổ chức “Ngày hội gia đình” vào tháng 5, có quà tặng bằng tiền mặt dành tặng ông bà, cha mẹ, vợ/chồng và con cái của nhân viên – thể hiện sự trân trọng với cả gia đình bạn.\n- Chế độ quà tặng nhân dịp đặc biệt:\nTặng quà các ngày lễ: Tết Dương lịch, Tết Âm lịch, 30/4, Trung thu, 8/3, 20/10.\nCả nhân viên nam và nữ đều có quà.\nNhân viên chính thức trên 6 tháng được tặng quà sinh nhật trị giá 5 triệu đồng/người.\n- Thưởng hiệu suất riêng:\nNgoài lương chính còn có các khoản thưởng, bonus hàng tháng tùy theo đóng góp.\n- Hỗ trợ nơi ở:\nNhân viên ở xa được sắp xếp chỗ ở miễn phí, thuận tiện cho công việc.\n- Cơ hội học hỏi và phát triển:\nLàm việc cùng các chuyên gia hàng đầu trong nước và quốc tế.\nGiao lưu, học hỏi với đồng nghiệp quốc tế giúp cải thiện tiếng Anh và mở rộng tư duy toàn cầu.\n- Chăm sóc sức khỏe toàn diện:\nKhám sức khỏe định kỳ tại các bệnh viện quốc tế như BV Phương Đông.\nMiễn phí tiêm phòng HPV, cúm cho nhân viên.\n- Trải nghiệm công tác và du lịch:\nCác chuyến công tác nước ngoài kết hợp du lịch, khám phá đặc sản và địa danh nổi tiếng.\nĐược tài trợ các hoạt động gắn kết team, học hỏi kiến thức lập trình qua các buổi giao lưu, workshop.\n- Văn phòng hiện đại, tiện nghi:\nKhông gian làm việc rộng rãi, thoáng mát.\nCó bánh, trà, café phục vụ mỗi ngày.\n- Bữa trưa đầy đủ dinh dưỡng, ngon miệng dành riêng cho nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'B4-12 Vinhomes Gardenia Hàm Nghi, Đường Hàm Nghi, Phường Cầu Diễn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(587, 250, 2, '[Da Nang & Ho Chi Minh] Scrum Master', 'Top 3 reasons to join us\n- Performance Bonus\n- Health care program for staff & dependants\n- Well-being program\n\nJob description\n- Responsible for promoting and supporting Scrum by helping everyone understand Scrum theory, practices, principles, and values.\n- Ensure that the Scrum process works well and properly.\n- Coach the team on how to use Scrum practices and values to delight customers.\n- Coach the scrum team in self-organization.\n- Collaborate closely with the Product Owner to manage the product backlog.\n- Facilitate Scrum events and other meetings as needed, e.g. product backlog refinement, planning, daily scrum, sprint review, and sprint retrospective.\n- Facilitate getting the work done without coercion, assigning, or dictating the work.\n- Facilitate discussion, decision-making, and conflict resolution.\n- Guide the team to minimize and eliminate impediments.\n- Provide all support to the team using a servant leadership style whenever possible.\n- Help the scrum team achieve higher levels of scrum maturity.\n- Work with other Scrum Masters to increase the effectiveness of applying Scrum in the Organization.\n\nPERSONAL ATTRIBUTES:\n- Responsible to create a safe environment where problems can be raised without fear of blame, retribution, or judgment.\n- An individual who is able to raise the morale of the team if it gets low.\n\nYour skills and experience\n- Having knowledge of Scrum techniques and artifacts.\n- Highly proficient in spoken and written English skills.\n- Working technical knowledge of the software development process – design, development, test, and deployment.\n- Strong communication, collaboration, leadership, conflict resolution, and time management skills.\n- Applicable knowledge of the technologies used by the team.\n- Analytical skills to be able to solve problems and remove impediments.\n- Strong interpersonal skills including mentoring, coaching, collaborating, and team building.\n- Certified Scrum Master is a plus.\n\nWhy you\'ll love working here\nMore on OTSV – what is it like to work in OTSV? At OTSV, work is a form of self-fulfillment, we encourage staff to leave their comfort zone, think out of the box, and share their ideas without hesitation. As a team, we analyze and evaluate issues objectively to learn quickly from mistakes. We believe in ‘fail quick, success quick’ and strive to keep pace with the forefront of technology to digitize ONE’s business.\n\nIn line with the Agile methodology, we have an open office concept with lots of meeting areas for spontaneous team meetings. We aim to make our staff feel as comfortable in the office as they would feel at home. You will love working here!\n- Competitive salary\n- Annual Increment\n- 13th-month salary\n- Performance Bonus\n- Social Security co-contribution based on full gross salary\n- Premium health care (Bao Viet Insurance) for employees & dependents (parents or spouse and children).\n- Lunch allowance\n- Free drinks and snacks\n- 17 days of Annual Leave\n- Annual health screening reimbursement: Up to 4,700,000 VND\n- Well-being allowance: 13,800,000VND/year\n- Training and education sponsorship: 38,000,000VND/year.\n\nWe value Teamwork and organization team meals, gatherings, and other recreational and team bonding activities regularly.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3-4 tòa nhà Phi Long, 52 Nguyễn Văn Linh, Hai Chau, Da Nang, Tòa nhà ETOWN 6 - 364 Cộng Hòa, Phường 13, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(588, 298, 2, 'Senior QA/QC Engineer/Designer (English)', 'Our dynamic and growing product company is seeking a highly skilled and motivated Senior QA/QC Engineer to join our international team. English is the primary language used for all internal and external communications and documentation within this role and our development teams. In this pivotal role, you will be instrumental in ensuring the quality of our web and mobile applications. You\'ll take charge of manual test case management, collaborate effectively with cross-functional stakeholders (Product Managers, Developers, etc. – primarily in English), and contribute to application development within an agile "Squad" environment. Our Squads are small, empowered teams that rapidly and consistently manage the entire product lifecycle, from design and development to testing and operations. If you are passionate about quality, fluent in English, and thrive in a collaborative, fast-paced setting, this is the perfect opportunity for you.\n\nJob Scope\nAs a Senior QA/QC Engineer, your key responsibilities will include:\n\nTest Design & Execution: Designing, developing, and executing comprehensive test cases for web and mobile applications. All test documentation, reporting, and communication will be conducted in English.\nReporting & Analysis: Creating detailed test reports, developing robust test plans, and delivering insightful Bug Analysis post-testing, all in English.\nQuality Advocacy: Championing product quality by proactively identifying areas for improvement in system requirement definitions and enhancing the UAT process. You will be empowered to create and implement your improvement plans, communicating your proposals and findings in English.\nRisk Management: Engaging in the early stages of projects to detect, assess, and mitigate risk factors such as bugs, specification ambiguities, and schedule changes, through clear English communication.\nContinuous Improvement: Planning and implementing measures to prevent the recurrence of identified issues and continuously refine testing processes, with all related documentation in English.\n\nOur Development Environment\nAutomation Testing: Autify, Playwright, MagicPod\nBackend: Ruby (on Rails), Go, Amazon Aurora (MySQL), Elasticsearch, DynamoDB\nFrontend: Nuxt.js/Vue.js, ReactJS\nMobile App: Kotlin, Swift, Flutter\nCI/CD & Version Control: CodePipeline, CodeBuild, CircleCI, GitHub Actions\nCollaboration & Design Tools: Swagger, Docker, ZenHub, Figma\n\nYour skills and experience\nRequirements\nMust-Haves:\nA strong alignment with Andpad\'s mission and values.\nMinimum of 3 years of hands-on experience in testing Web Services and Mobile Applications.\nProven experience in developing comprehensive test cases, executing test suites, and meticulously reporting test results (in English).\nDemonstrable experience in security testing OR performance testing.\nGood command of both spoken and written English for daily work communication.\nStrong interpersonal and communication skills, with the ability to collaborate effectively within development projects using English as the primary language.\n\nNice-to-Haves:\nA proactive approach to staying updated with industry trends and researching new technologies.\nExperience working in agile development environments.\nPrevious experience in a web or mobile product development company.\nExperience working within a Japanese corporate culture is a plus.\nJapanese language proficiency is an advantage (though not required for daily operations).\nExperience with API testing (e.g., using tools like Postman, Rest Assured).\n\nWhy you\'ll love working here\nCompetetive Compensation: Attractive salary package with comprehensive insurance coverage.\nPerformance Recognition: Biannual performance reviews (twice per year).\nGenerous Bonuses: 13th-month salary bonus.\nWork-Life Balance: Hybrid working model.\nAmple Time Off: 18 days of leave annually (12 days of annual leave + 6 days of company-specific New Year/Tet holidays).\nPremium Benefits: Premium Healthcare Insurance Package effective from day one.\nWellness Focus: Annual Health Check-up.\nCareer Growth: Excellent career development opportunities, including exposure to and hands-on experience with the latest technologies in an English-speaking environment.\nContinuous Learning: Sponsorship for courses and certifications to support your professional development.\nInnovation Rewards: Bonuses for patents and inventions.\nTeam Spirit: Company trips, Year-End Parties, and gifts for Tet and other holidays.\nTech & Tools: MacBook Pro or suitable laptop provided.\nReferral Rewards: Attractive Referral Program.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3rd Floor, Dong Nhan Building, 90 Nguyen Dinh Chieu, Da Kao Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(589, 447, 2, 'Automation Test', 'Top 3 reasons to join us\n- Attractive salary\n- International trainings\n- Interacting with leading-edge technologies\n\nJob description\n- Analyze software project requirements in embedded software\n- Create/update test case for testing (if any).\n- Create/update test scripts or build automation tools for testing.\n- Setup test environment; execute automation test scripts and ensure automation test result reliability.\n- Perform manual testing (if any).\n- Log, verify & manage defects on defect tracking system\n- Troubleshoot project issues to detect root cause and propose solution to resolve project issues.\n- Escalate testing risks and issues\n- Follow test leader’s assignment.\n\nYour skills and experience\nBasic Qualification:\n- Bachelor degree in Information Technology, Computer Science, Computer Engineering, Electronic Engineering, Telecommunication Engineering or equivalent\n- Ability to have verbal and written communication skills in English\n- Has good logical thinking\n- Has at least 3 years experience in coding position (Automation Testing or/and Developer), with at least 2 year experience in Python language and Robot Framework.\n- Experienced with CI/CD/CT, Jenkins is preferred\n- Fluent Git, experience with Application Life Cycle Management tools (e.g., Jira, CodeBeamer, Polarion, etc.)\n- Well understanding about SDLC and testing process\n- Experienced with Agile (Scrum/Kanban/SAFe) working methods is preferred\n- Has ability to create TC\n- Good at team working\n\nNice to have:\n- Good attitude is a plus point\n- ISTQB Foundation Certifications\n- Having knowledge about Reg.ex is a plus.\n- Good knowledge about Linux is a plus.\n\nWhy you\'ll love working here\n- Competitive salary (Negotiable according to ability and experience).\n- 5 working days/week: Monday - Friday, Day-off: Saturday - Sunday.\n- Working time: 8:00 ~ 17:00\n- Bonus on holidays, Birthday...; 13th-month salary\n- Insurance in full gross salary\n- Working in a multinational company, a modern and professional international working environment.\n- Enjoy benefits according to the Labor Law and other remuneration policies according to the company\'s regulations such as social insurance, health insurance, unemployment insurance, company’s birthday leave, seniority bonus, periodic health examination\n- Overseas travel regime for employees who have outstanding contributions to the Company.\n- Training opportunities in Korea and other countries.\n- Prioritizing personal development, improving professional skills and expertise, and unleashing creativity, bosses, and colleagues are always ready to listen and help.\n- Participating in team building activities, birthday parties, and Tet holidays with many exciting activities.\n- The company has a pantry area, tea, and coffee that is refilled monthly.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lot 2C1 Mac Thai Tong Street, Trung Hoa Ward, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(590, 289, 2, 'Chuyên viên Quản trị cơ sở dữ liệu - DBA (Database,SQL)', 'Top 3 reasons to join us\n- Môi trường làm việc năng động\n- Chế độ phúc lợi đầy đủ của Ngân hàng\n- Thu nhập xứng đáng, thưởng tối thiểu 2 tháng,dự án\n\nJob description\n- Quản trị và vận hành các hệ thống cơ sở dữ liệu chính và dự phòng đảm bảo sự an toàn, tính sẵn sàng và tính toàn vẹn của cơ sở dữ liệu.\n- Triển khai và duy trì các cơ chế bảo vệ cơ sở dữ liệu, bao gồm: sao lưu định kỳ, clustering, mirroring, replication, khôi phục dữ liệu sau sự cố (recovery), đảm bảo khả năng khắc phục thảm họa (disaster recovery) hiệu quả.\n- Tối ưu hóa hiệu suất hệ thống cơ sở dữ liệu thông qua phân tích truy vấn, điều chỉnh cấu trúc, chỉ số (index), thống kê, cấu hình bộ nhớ và xử lý lỗi để đảm bảo hoạt động hiệu quả, ổn định.\n- Đề xuất, đánh giá và thử nghiệm các công nghệ cơ sở dữ liệu mới, phù hợp với định hướng phát triển hạ tầng công nghệ và hệ sinh thái ứng dụng của ngân hàng.\n- Phối hợp rà soát, xây dựng quy trình, quy định về quản trị, vận hành giám sát hệ thống cơ sở dữ liệu.\n- Báo cáo, tư vấn cho các cấp quản lý những vấn đề phát sinh liên quan tới các hệ thống cơ sở dữ liệu được giao.\n\nYour skills and experience\n- Trình độ đào tạo:  Tốt nghiệp Đại học trở lên các trường trong nước/ nước ngoài\n- Chuyên ngành: Công nghệ thông tin, Tin học ứng dụng, Khoa học máy tính, Kỹ thuật phần mềm, Điện tử viễn thông, Kỹ thuật thông tin\n- Yêu cầu kinh nghiệm: Có ít nhất 01 năm kinh nghiệm làm việc trong lĩnh vực quản trị cơ sở dữ liệu, ưu tiên các ứng viên có kinh nghiệm chuyên môn làm việc với cơ sở dữ liệu Oracle (ưu tiên phiên bản 11g/12c/19c);\n- Có khả năng tối ưu hóa hiệu năng hệ thống (performance tuning), phân tích truy vấn, điều chỉnh index/statistics, quản trị tablespace, partitioning.\n- Hiểu biết tốt về SQL Server, PostgreSQL hoặc các hệ quản trị cơ sở dữ liệu khác.\n- Có và/hoặc chứng chỉ Oracle: OCA, OCP, ... là lợi thế tuyển dụng;\n\n- Ngoại ngữ: Có khả năng nói, viết bằng tiếng Anh. Chứng chỉ tiếng Anh yêu cầu: tối thiểu tương đương trình độ B1 trở lên theo khung tham chiếu trình độ ngoại ngữ chung Châu Âu.\n- Tuổi:  Không quá 40 tuổi.\n- Yêu cầu khác:\n- Chịu được áp lực công việc, sẵn sàng làm ngoài giờ khi có sự cố cần xử lý.\n- Tinh thần trách nhiệm cao, bảo mật tuyệt đối, có khả năng làm việc độc lập và xử lý sự cố trong tình huống áp lực.\n- Nghiêm túc, cầu tiến, chịu khó, nhiệt tình trong công việc.\n- Ưu tiên ứng viên nộp hồ sơ bằng Tiếng Anh.\n\nWhy you\'ll love working here\n- Hưởng lương hấp dẫn, phù hợp với năng lực và kinh nghiệm.\n- Làm việc và phát triển trong môi trường trẻ trung, năng động và luôn giàu nhiệt huyết\n- Có cơ hội thăng tiến cao, được làm việc trong môi trường thân thiện, sáng tạo và phát triển.\n- Được tham gia các chương trình đào tạo nghiệp vụ của Ngân hàng.\n- Được chi bổ sung thu nhập theo kết quả làm việc, vị trí công việc và hưởng các cơ chế khuyến khích theo quy định của VRB.\n- Du lịch - Nghỉ dưỡng - Team building hằng năm.\n- Khám sức khỏe định kỳ và chế độ bảo hiểm sức khỏe do VRB tài trợ.\n- Các phúc lợi hiếu, hỷ, tiền mừng sinh nhật, thai sản, …', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '75 Trần Hưng Đạo, Hoàn Kiếm, Hà Nội, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(591, 182, 2, 'Quality Assurance Lead (QA QC)', 'Are you ready to lead the next evolution of Quality Assurance in digital banking? We’re hiring a QA Automation Lead who will own the automation testing strategy, drive shift-left testing practices, and embed quality deeply into every stage of our SDLC. This is a key leadership role where you will guide our teams toward continuous testing, scalable automation, and measurable quality—all to support reliable, secure, and delightful banking experiences.\n\nKey Responsibilities\n\nAutomation Strategy & Execution\n- Define and lead the end-to-end QA automation roadmap.\n- Select and scale modern test frameworks for mobile, web, API, and microservices.\n- Embed automated testing in CI/CD pipelines (AWS Pipeline, Jenkins).\n- Drive test data strategy and environment readiness for automated runs.\n\nShift-Left & Continuous Testing\n- Advocate for quality engineering from design to production.\n- Introduce shift-left testing and coach and driving feature teams on writing reliable integration tests, component test and API and E2E Test.\n- Collaborate with DevOps(Pipeline) Team to enable parallel test execution and fast feedback loops.\n\nQuality Metrics & Insights\n- Establish test coverage, pass rate, defect leakage KPIs, and trend dashboards.\n- Provide actionable insights using tools like XRAY, TestRail, or custom dashboards.\n- Review failures to root-cause issues and close quality gaps upstream.\n\nTeam Leadership & Coaching\n- Lead and coaching a growing automation QA team across Portfolio.\n- Pair testing sessions, and QA guilds with engineering team and QA Team to uplift skills and practices.\n- Provide clear direction, feedback, and career guidance for QA Team.\n\nCross-Team Collaboration\n- Work closely with Engineering, Product, and Security to align on quality objectives.\n- Ensure automation efforts scale across portfolio and platforms (iOS, Android, Web, Backend..).\n- Lead initiatives that improve release confidence, cycle time, and regression resilience.\n\nYour skills and experience\n\nTechnical Skills\n- 5+ years in test automation with 2+ years in a lead role.\n- Solid coding skills in JavaScript, Java, Python, or similar for writing test scripts.\n- Experience with frameworks like Cypress, Playwright, Selenium, Appium, or REST Assured.\n- Familiar with BDD/TDD, service virtualization, and mocking/stubbing tools.\n- Exposure to Microservices, Event-driven architecture, and Serverless functions.\n\nMindset & Experience\n- Strong advocate of test automation as a product enabler, not a QA function.\n- Experience in high-regulation environments (banking, fintech, payments preferred).\n- Proven ability to lead through influence, clarity, and accountability.\n\nSoft Skills\n- Passionate communicator, motivator, and hands-on leader.\n- Comfortable challenging the status quo and introducing best practices.\n- Curious, analytical, and always optimizing the test strategy for better coverage and speed.\n\nWhy you\'ll love working here\n\nYou’ll love working with us if you are:\n- Passionate about technology.\n- Independent but also a good team player.\n- Comfortable with a high degree of ambiguity.\n- Focused on usability and speed.\n- Keen on presenting your ideas to your peers and management.\n\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\n\nSome of our benefits:\n- Meal and parking allowances are covered by the company.\n- Full benefits and salary rank during probation.\n- Insurances such as Vietnamese labor law and premium health care for you and your family.\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\n- Values-driven, international working environment, and agile culture.\n- Overseas travel opportunities for training and work-related.\n- Internal Hackathons and company events (team building, coffee run, etc.).\n- Pro-Rate and performance bonus.\n- 15-day annual + 3-day sick leave per year from the company.\n- Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(592, 448, 2, 'Senior IT Business Analyst (Data Experience)', 'Job description\n• Work closely with BA Lead, Product Managers and Developers to gather and document business requirements for software products.\n• Collaborate with clients to understand their needs and propose tailored solutions that meet their requirements.\n• Analyze and map business processes, identifying opportunities for improvement and innovation.\n• Develop detailed functional specifications, user stories, and use cases to guide the development team.\n• Facilitate workshops and meetings to elicit requirements, present findings, and drive consensus among stakeholders.\n• Ensure that business analysis activities align with the overall product strategy and roadmap.\n• Monitor project progress, manage risks, and communicate effectively with stakeholders to ensure timely delivery of software products.\n• Stay current with industry trends, best practices, and emerging technologies in software development and business analysis.\n\nYour skills and experience\n*Must have*\n• Bachelor\'s degree in Computer Science, Information Technology, Business Administration, or a related field, a Master\'s degree is a plus.\n• 5–8+ years of experience as a Business Analyst, with at least 2 years focused on data/AI-related initiatives.\n• Strong understanding of data lifecycle management, data modeling, and analytics platforms (e.g., Power BI, Tableau, SQL).\n• Familiarity with AI/ML concepts, frameworks, and lifecycle (e.g., model training, validation, deployment, monitoring).\n• Proven experience translating business problems into data or AI requirements.\n• Excellent analytical and problem-solving skills, with the ability to translate complex business requirements into technical specifications.\n• Exceptional communication and interpersonal skills, with the ability to collaborate effectively with cross-functional teams.\n• Proficiency in business analysis tools and techniques, such as process modeling, data analysis, and requirements management.\n• Experience with software development tools and platforms, such as JIRA, Confluence, or similar.\n• Fluent in English with excellent communication and negotiation skills.\n• Willingness to travel to client sites internationally.\n\n*Prefer to have*\n• A solid understanding of the industry and the target market in Digital Transformation, Information Management System, E Commerce and Finance technologies.\n\nWhy you\'ll love working here\n• Professional and flexible working environment\n• Fast-track career development opportunities\n• Competitive compensation package\n• 13th-month salary\n• Performance bonus\n• MacBook Pro M4/ Dell Latitude Ultra 7 provided\n• Recognition rewards for outstanding performers\n• Full social, health, and insurance coverage\n• Healthcare: Annual health check-up, Health Insurance\n• Annual leaves: 14 days\n• Active company clubs and social activities\n• Comprehensive training: Technical skills, Soft skills, English', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24F Deutsches Haus - 33 Le Duan Street, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(593, 449, 2, 'Chuyên gia Phát triển và Tích hợp dữ liệu - K.CNTT', 'Top 3 reasons to join us\n- Môi trường năng động và cơ hội thăng tiến\n- Chế độ lương thưởng hấp dẫn\n- Bảo hiểm sức khỏe cao cấp (bảo hiểm toàn diện)\n\nJob description\nNhiệm vụ chính\n- Nhận phân công công việc của lãnh đạo có thẩm quyền, lập kế hoạch công việc chi tiết và báo cáo tiến độ, kết quả công việc cho lãnh đạo;\n- Tham gia các hoạt động đào tạo, hướng dẫn, trao đổi kiến thức, sinh hoạt chuyên môn và các hoạt động sinh hoạt chung khác trong Khối.\n\nNhiệm vụ chuyên môn\n- Thiết kế giải pháp và phát triển việc trích xuất, chuyển đổi, làm sạch dữ liệu trở thành nguồn dữ liệu tin cậy đảm bảo dữ liệu luôn được cập nhật thường xuyên hoặc định kỳ từ nguồn\n- Thiết kế luồng dữ liệu và phát triển tích hợp dữ liệu cho Hồ dữ liệu và Kho dữ liệu và các hệ thống khác;\n- Xây dựng và định kỳ rà soát các tiêu chuẩn tích hợp dữ liệu và phương pháp thiết kế theo từng thời kỳ phù hợp với chiến lược phát triển của NH\n- Phối hợp với Khối TCKT tham gia đánh giá, xây dựng quy định, quy trình, hướng dẫn liên quan đến Quản trị và khai thác Nền tảng phân tích Dữ liệu toàn hàng;\n- Xây dựng các quy định liên quan đến cung cấp dịch vụ trên hệ thống tích hợp dữ liệu;\n- Chuyển giao sản phẩm/dịch vụ sang Trung tâm vận hành công nghệ theo quy trình chuyển giao hiện hành, tuân thủ các tiêu chuẩn về vận hành hệ thống;\n- Phối hợp điều tra và khắc phục nguyên nhân lỗi dịch vụ\n- Nghiên cứu và đề xuất các giải pháp công nghệ mới phù hợp theo lộ trình và chiến lược phát triển của ngân hàng\n- Tư vấn cho lãnh đạo các giải pháp để khắc phục các vấn đề hoặc tối ưu hoạt động của Khối CNTT theo quy trình cải tiến liên tục\n- Tổ chức đào tạo, hướng dẫn, trao đổi kiến thức và sinh hoạt chuyên môn\n- Các công việc khác theo chức năng nhiệm vụ của phòng Tích hợp dữ liệu\n\nThực hiện các nhiệm vụ khác theo phân công của Trưởng phòng tích hợp dữ liệu\n\nYour skills and experience\nBằng cấp: Tốt nghiệp Đại học trở lên các chuyên ngành thuộc lĩnh vực Công nghệ Thông tin, Tài chính Ngân hàng, Kinh tế;\nKiến thức chuyên môn:\n- Theo yêu cầu về năng lực chuyên môn và năng lực quản lý quy định trong Khung năng lực của Khối CNTT trong từng thời kỳ;\nKinh nghiệm làm việc:\n- Có tối thiểu 4 năm kinh nghiệm làm việc trong lĩnh vực CNTT;\nKỹ năng, phẩm chất:\n- Kỹ năng Đọc, hiểu tài liệu và giao tiếp bằng Tiếng Anh;\n- Có tư duy chiến lược, sáng tạo và đổi mới, tinh thần trách nhiệm cao trong công việc;\n- Kỹ năng giao tiếp tốt;\n- Kỹ năng xây dựng, quản lý và phát triển đội nhóm tốt;\n- Kỹ năng lập và triển khai kế hoạch;\n- Kỹ năng làm việc độc lập hoặc làm việc theo nhóm;\n\nWhy you\'ll love working here\n- Được tham gia vào các dự án công nghệ lớn, các sáng kiến trọng điểm mang tính đột phá số hóa của Ngân hàng\n- Trải nghiệm các kiến trúc, công nghệ mới nhất, làm việc trực tiếp với các đối tác hàng đầu thế giới (AWS, IBM, Temenos…)\n- Môi trường năng động và cơ hội thăng tiến, với văn hóa doanh nghiệp mang bản sắc riêng\n- Chế độ lương thưởng hấp dẫn\n- Bảo hiểm sức khỏe cao cấp (bảo hiểm toàn diện)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '22 Ngô Quyền, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(594, 227, 2, 'Junior Data Engineer, Global E-commerce Data Platform', 'Top 3 reasons to join us\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description\n- Collaborate with Data Analysts and Business Teams to understand data needs and provide timely solutions for reporting and insights.\n- Work on data integration from various sources, including APIs, web services, and databases.\n- Utilize tools such as AWS QuickSight, Grafana, and Google Sheets for data visualization to support business decision-making.\n- Support developing and maintaining scalable data pipelines and ETL/ELT processes to collect, clean, and process large-scale datasets in data systems.\n- Monitor data pipeline performance and troubleshoot issues to ensure data integrity and availability.\n- Document technical processes, contribute to data catalogs, and ensure compliance with data governance policies.\n- Engage in continuous learning and improvement, staying updated with industry best practices in Data Engineering.\n\nYour skills and experience\nEducation: Bachelor\'s degree in Computer Science, Information Systems Management or related fields.\nExperiences:\n- 2+ years of experience in data engineering, ETL development, or a similar role.\n- Proficiency in using advanced SQL queries to extract valuable insights from datasets.\n- Experience in one of the following programming languages: Python or C# for data processing and scripting.\n- Experience with relational databases, such as PostgreSQL, MySQL, Oracle, or MS SQL Server.\n- Understanding of cloud computing platforms (e.g., AWS, GCP, Azure).\n- Excellent problem-solving skills, attention to detail, and the ability to work independently or as part of a team.\n- Strong communication and collaboration skills, particularly in an Agile environment.\n- Proficient in English, with the ability to communicate, read, and write effectively in a professional work environment.\n\nPreferred (but not required)\n- Experience working with BI tools such as AWS QuickSight, Grafana, or Google Sheets.\n- Familiarity with data orchestration tools like Airflow or dbt.\n- Exposure to cloud-based storage solutions and data lake architecture.\n- Familiarity with the Agile toolset, such as GitLab, Jira, Confluence, and Slack.\n\nWhy you\'ll love working here\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\nExceptional Compensation\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total annual compensation $30,000, reflecting your expertise and contribution.\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\nIn addition to development tasks, you’ll collaborate closely with other CoEs to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(595, 258, 2, 'Product Management  - Viettel Future Changemakers 2025', 'Viettel Future Changemakers là chương trình quản trị viên tập sự của Viettel - nơi quy tụ những người trẻ dám nghĩ, dám làm, có khả năng lãnh đạo và có tư duy đột phá. Chương trình đào tạo, kết hợp với luân chuyển sẽ giúp tập sự viên xây dựng được tư duy hệ thống, tư duy chiến lược và phát triển năng lực lãnh đạo, từ đó trở thành những hạt giống mang lại những thay đổi lớn, tích cực cho xã hội.\n\nChương trình Viettel Future Changemakers kéo dài 18 tháng, dự kiến triển khai từ tháng 08/2025 – 01/2027, chia làm 02 giai đoạn:\n\n- Giai đoạn 1 (1 tháng): Trại huấn luyện tập trung - Được đào tạo tập trung bởi nhiều chuyên gia của Viettel và các Tập đoàn công nghệ lớn thế giới\n- Tổng quan về Quản lý sản phẩm\n- Kiến thức về Lập chiến lược sản phẩm (Ideas & User needs, Competitive & Market Analysis, Customer Development)\n- Kiến thức về Thiết kế và phát triển sản phẩm\n- Kiến thức về Marketing & Ra măt sản phẩm\n- Các kỹ năng cần thiết về Quản lý sản phẩm\n\n- Giai đoạn 2 (17 tháng): Tập sự tại các dự án trọng điểm thuộc đơn vị\n- Tập sự viên được tham gia các dự án, công việc tại các phòng ban liên quan để hiểu rõ về 03 khía cạnh của Quản lý sản phẩm (1) Kinh doanh (2) Công nghệ (3) Khách hàng.\n- Mentor là người có chuyên môn cao trong lĩnh vực sẽ hướng dẫn tập sự viên\n- Management coach là cán bộ quản lý có kỹ năng lãnh đạo tốt sẽ tư vấn cho tập sự viên\n- Tham gia lên ý tưởng cho các sản phẩm trọng điểm của Viettel và tham gia cuộc thi “The Changemakers” với cơ hội nhận thưởng lên đến 30 triệu/ đồng và được trình bày đề xuất trước Ban Tổng Giám đốc Tập đoàn.\n- Các hoạt động kết nối: Tham gia nhiều hoạt động kết nối tài năng, cán bộ quản lý tại Viettel.\n\nYour skills and experience:\n- Ứng viên bên trong và bên ngoài Viettel tốt nghiệp đại học loại Giỏi trở lên các ngành Công nghệ thông tin, Khoa học máy tính, Quản trị kinh doanh, Tài chính ngân hàng, Marketing, Kinh tế và các ngành tương đương; hoặc đạt các thưởng quốc gia/quốc tế trong các lĩnh vực liên quan; hoặc có thành tích xuất sắc khi tham gia các dự án lớn trong lĩnh vực liên quan.\n- Ưu tiên ứng viên có 02 năm kinh nghiệm làm Marketing, Product Owner, Phân tích nghiệp vụ, Phát triển phần mềm cho các sản phẩm công nghệ.\n- Tiếng Anh tối thiểu 700 điểm TOEIC hoặc tương đương (Chấp nhận điểm thi trên E-learning bài TOEIC đầy đủ và các chứng chỉ quốc tế tương đương).\n- Địa điểm: Hà Nội (Đối với ứng viên khác khu vực Hà Nội sẽ được tài trợ máy bay 02 chiều nếu trúng tuyển và tham gia đầy đủ chương trình)\n- Thời hạn ứng tuyển: Trước 08/06/2025 (Ưu tiên hồ sơ nộp sớm)\n- Hình thức thi: Vòng 1 - IQ, Tiếng Anh Toeic, Vòng 2: Online test, Vòng 3: Assessment day tại Hà Nội, Vòng 4: Phỏng vấn hội đồng.\n\nWhy you\'ll love working here:\n- Thu nhập: 30-47 triệu/tháng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Keangnam Landmark Tower 72, Pham Hung, Nam Tu Liem, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(596, 220, 2, 'Chuyên viên Triển khai và hỗ trợ phần mềm y tế (SQL)', 'Tham gia triển khai và hỗ trợ cài đặt phần mềm y tế trong hệ thống sản phẩm của công ty;\nTiếp nhận các yêu cầu của khách hàng, hỗ trợ kiểm tra, xử lý yêu cầu và hướng dẫn người sử dụng phần mềm;\nGiải quyết mọi thắc mắc, vấn đề phát sinh từ phía khách hàng;\nThực hiện các công việc khác theo phân công của Quản lý trực tiếp.\n\nTốt nghiệp hoặc chuẩn bị tốt nghiệp Đại học, cao đẳng chuyên ngành công nghệ thông tin (không còn lịch học tại trường);\nNăng động, kỹ năng giao tiếp tốt, có khả năng sử dụng tốt tin học văn phòng;\nSẵn sàng đi công tác tại các tỉnh thành trên cả nước.\nHiểu biết và có khả năng viết truy vấn CSDL;\nCó kinh nghiệm làm việc với cơ sở dữ liệu PostgreSQL, SQL Server, MySQL, C#, HTML, CSS, Angular...; (Không yêu cầu kinh nghiệm)\nChủ động trong công việc, giải quyết vấn đề nhanh, chịu được áp lực công việc.\n\nƯu tiên: \nỨng viên có kinh nghiệm triển khai phần mềm Quản lý bệnh viện và Quản lý phòng khám;\nỨng viên có kinh nghiệm trong việc triển khai, hỗ trợ các phần mềm thuộc lĩnh vực y tế.\n\nLương net: Thỏa thuận theo năng lực;\nCông ty đóng Bảo hiểm xã hội theo quy định;\nMôi trường làm việc thân thiện, chuyên nghiệp, cơ hội thăng tiến cao;\nHỗ trợ thiết bị làm việc và đào tạo chuyên sâu về nghiệp vụ trong lĩnh vực phần mềm Y Tế;\nChế độ bảo hiểm, phúc lợi đầy đủ theo quy định của công ty;\nĐược tham gia vào các dự án, cập nhật công nghệ mới nhất;\nĐược hỗ trợ đào tạo nghiệp vụ và hướng dẫn quy trình vận hành thực tế cùng đội ngũ chuyên gia trong các lĩnh vực: Y tế....\nCác chế độ theo Luật Lao động hiện hành và các phúc lợi theo quy định của Công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sàn Văn phòng số VP5 tầng 2 tòa nhà Pan Horizon, Xuân Thủy, Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(597, 227, 2, 'Senior Frontend Engineer (ReactJs/NextJs)', 'Top 3 reasons to join us\n\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description\n\nFrontend Development & Optimization\n- Design, develop, and implement user-facing features using ReactJS and NextJS.\n- Optimize web applications for performance, scalability, and cross-browser compatibility.\n- Lead the implementation of Server-Side Rendering (SSR) and Client-Side Rendering (CSR) for complex features.\n- Ensure clean, maintainable, and scalable code through adherence to industry standards and peer code reviews.\n- Debug and resolve performance bottlenecks using tools like Sentry, Kong logs, and Cloudflare.\n- Translate wireframes and prototypes into high-quality, responsive, and accessible code.\n- Collaborate with UI/UX designers to deliver user-centric and consistent experiences.\n\nSystem Integration & Maintenance\n- Work closely with backend teams to integrate APIs seamlessly into the frontend.\n- Participate in deployment processes and ensure system stability through efficient debugging and issue resolution.\n\nCross-Functional Collaboration\n- Collaborate with stakeholders to analyze requirements and break them into actionable technical tasks.\n- Work with cross-functional teams (backend, QA, DevOps) to ensure the successful delivery of projects.\n\nKnowledge Sharing & Continuous Improvement\n- Share knowledge with team members and provide guidance on frontend best practices.\n- Proactively suggest improvements to workflows, tools, and code quality to enhance team productivity and product quality.\n\nYour skills and experience\n\n- Education: Bachelor’s degree in Information Technology, Computer Science, or related fields.\n- Experience:\n  - 4-8 years of experience in frontend development with strong expertise in ReactJS, NextJS, and modern JavaScript.\n  - Proficient in state management tools like Redux, Recoil, or similar libraries.\n  - Hands-on experience in building responsive, cross-browser-compatible, and accessible web applications.\n  - Hands-on experience with Node.js to develop APIs and optimize SSR logic.\n  - Familiarity with modern frontend tools and workflows (e.g., Webpack, Vite, Git).\n  - Basic understanding of AWS S3, Cloudflare, or similar tools for asset delivery.\n  - Has knowledge of Postgres, KAFKA, Elasticsearch, S3/Minio\n  - Capable of translating business requirements into technical solutions.\n  - English proficiency.\n\n- Soft Skills:\n  - Strong problem-solving skills.\n  - Familiarity with Agile/Scrum.\n\n- Preferred Skills (but not required):\n  - Has knowledge of design, and coding principles (e.g.: clean code, DRY/KISS, SOLID).\n  - Knowledge of testing frameworks like Jest, React Testing Library.\n  - Familiarity with CI/CD pipelines for frontend applications.\n  - Experience with eCommerce platforms is a plus.\n\nWhy you\'ll love working here\n\n- Highly competitive remuneration package: Attractive monthly salary and allowances, 13th-month salary, and additional average 18 months annual bonuses per year.\n- Training & Development budget, Team building budget, 5-star company events, 12 days Work-from-home allowance & much more.\n- Generali\'s global health insurance for employees and family.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(598, 185, 2, 'Software Engineer (.NET WPF) English speaking', 'Top 3 reasons to join us\n• Hybrid working model and good work-life balance\n• 15+ days of paid leave per year\n• Premium health insurance for employee\n\nJob description\n• As a Software Developer, you will play a key role in designing, building, and maintaining software solutions using the Microsoft Stack of Technologies. Your daily tasks will involve end-to-end software development, where you will use your proficiency in C#, .NET, WPF/XAML, Web APIs, LINQ, and Entity Framework. You will also utilise your skills to write and optimise SQL queries, ensuring performance and scalability. You will be part of a team that builds service-oriented or microservices-based applications, following industry best practices for object-oriented programming and design. Your work will require you to ensure high quality code, write unit-tested code, and apply effective debugging skills to resolve any issues across different environments.\n• In this role, you will have the opportunity to contribute to a team that values collaboration and continuous improvement. While working in an Agile environment, you will participate in Scrum or Kanban methodologies to deliver solutions efficiently. You may also be involved in test-driven or acceptance test-driven development to ensure that the software meets business requirements. Your work could extend to creating applications on Microsoft Azure and using tools such as FitNesse or Postman.\n\nYour skills and experience\n• To be successful in this role, you should have a degree in Computer Science, such as B.E./B.Tech. or MCA, or equivalent experience.\n• You need to bring 3-4 years of professional experience in software development and a strong understanding of object-oriented programming principles, UML, and software development practices.\n• Your ability to ensure performance management and troubleshoot C# or SQL-related performance issues is essential.\n• It would be beneficial if you have experience in WPF development, working in Agile team environments, and using methodologies such as Scrum or Kanban.\n• Familiarity with test driven development and cloud platforms like Microsoft Azure would also be advantageous.\n• In addition to your technical expertise, you should have excellent analytical and problem-solving skills and strong communication abilities, both written and verbal.\n• Being self motivated, detail-oriented, and able to work effectively both independently and as part of a team will be key to your success in this position.\n\nWhy you\'ll love working here\n• Join a dynamic and fast-growing global network, tackle great challenges with large-scale products, and work with modern technologies\n• We support your development and are committed to advancing your career\n• Hybrid and flexible working environment with attractive benefits\n• We embrace diversity! As an Equal Opportunity Employer, we value strength in diversity and prohibit discrimination in any form\n• English-speaking environment where you will have opportunities to work on global projects and connect with experienced colleagues from around the world\n• Hybrid working model and good work-life balance\n• 13th-month salary bonus and annual performance bonus\n• 100% offered salary and mandatory social insurances in 2-month probation\n• 15+ days of paid leave per year\n• Premium health insurance\n• Annual company trip and various team building activities and appreciation gifts', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(599, 450, 2, 'Senior Software Engineer - Backend', 'About the role:\nWe are seeking team members who strive to solve hard problems, take pride in delivering world-class products, and are strong team players.\nYou are someone who wants to see the impact of your work making a difference every day. You find passion in the craft and are constantly seeking improvement and better ways to solve tough problems.\n\nResponsibilities:\n- Contribute to the ideation, technical design, implementation, and testing of product features that empower our business and deliver impact to our customers.\n- Produce high-quality software following good architecture and design principles that are scalable.\n- Design & deliver thoughtfully crafted APIs to drive the interactions between our client applications and backend services.\n- Collaborate with the team to define the future of the ShopBack experience.\n- Strong mentoring skills with the ability to provide technical guidance and review code.\n\nYour skills and experience\n\nRequirements:\n- 4+ years of experience developing consumer-facing web applications or complex distributed systems.\n- Proven experience designing complex distributed systems, management products, or business applications.\n- Understanding of good software design principles and have applied principles to professional work.\n- Hands-on experience working with Node.js (Preferred).\n- Have experience in TypeScript (Preferred).\n- Have knowledge in Test Driven Development (TDD), CI/CD.\n- Experience building and deploying applications and services into cloud environments (AWS highly desired).\n- Strong experience in the design and implementation of robust and highly scalable web services.\n- Ability to work effectively in a fast-paced, complex technical environment with high adaptability and flexibility.\n- Good English communication.\n\nWhy you\'ll love working here\nHave these benefits and a lot more at ShopBack VN:\n- Attractive Stock Options for all employees\n- Performance Bonus\n- 13-month Salary\n- 15 days of annual leave + 3 days of Medical leave + 1 day of birthday leave\n- 5 days of Additional Time Off (after annual leave entitlement is fully utilized)\n- IDP Budget\n- PVI Healthcare Insurance\n- Other benefits: Fun monthly and quarterly activities; Fully stocked pantry of fun and healthy food/snacks\n\nOur #SHOPBACK Values\nOur Values are not “Sound/Feel Good” values that are for show. We understand how our values build our culture and believe these aligned values will help us work better together to achieve our mission. We will hire, part ways, recognize or reward ShopBackers based on our values. Upholding these values is as important as our performance at work.\n\nHere are our 8 Values #SHOPBACK:\n- Succeed as One\n- Honour Our Customers\n- Own the Problem \n- Pave New Roads \n- Be Better Every Day \n- Always Be Curious \n- Can’t is Not an Option\n- Keep It Real', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Complex Tower, 285 Cach Mang Thang Tam Street, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(600, 224, 2, 'Golang Engineer (Data Platform/BI Application project)', 'We are hiring Senior Backend Engineers for 2 projects: \n- Integrated data platform project\n- Cloud BI application project\nYou’ll play a key role in architecting, developing, and scaling robust backend systems that power user-facing applications and advanced data/AI solutions used by millions. This is an exciting opportunity for engineers who are passionate about solving complex technical challenges at scale and thrive in a collaborative, cross-functional environment. You’ll work closely with skilled frontend, QA, and data engineers to deliver impactful and high-performance systems.\n- System Development: Design, develop, test, deploy, maintain, and enhance mission-critical backend services, APIs, and data processing systems.\n- API Engineering: Build clean, efficient, and scalable APIs for consumption by frontend applications and external/internal partners.\n- Code Quality: Write clean, maintainable, and well-tested code that adheres to best practices and team standards.\n- Cross-functional Collaboration: Partner with frontend engineers to define API contracts and integrate server-side logic.\n- Collaborate with QA engineers to ensure system testability and maintain product quality.\n- Work with data engineers to define data integration and processing pipelines.\n- Scalability & Performance: Identify performance bottlenecks, optimize system scalability and reliability, and ensure high availability under load.\n- Mentorship: Share knowledge, support team growth, and mentor junior engineers on technical skills and engineering best practices.\n\nYour skills and experience\nMust Have\n- 5+ years of professional experience in backend web development.\n- 3+ years of hands-on experience with Golang (or strong experience with Python and willingness to learn Golang).\n- Proven expertise in designing, building, and consuming secure RESTful APIs.\n- Solid experience with relational databases (e.g., PostgreSQL, MySQL), including schema design and query optimization.\n- Practical experience developing systems using cloud services on AWS, GCP, or Azure (preferably AWS).\n- Experience with CI/CD pipelines and tools.\n- Familiarity with containerized development using Docker, and understanding of orchestration tools like Kubernetes.\n- Strong knowledge of core computer science concepts: data structures, algorithms, software design principles, and engineering best practices.\n- Experience with performance profiling, optimization, and system reliability enhancements.\n\nNice to Have\n- Experience with GraphQL API design or consumption.\n- Background in developing BI-related systems, or API-first systems.\n- Experience with Go frameworks such as Gin or Echo.\n- Experience with Infrastructure as Code (e.g., Terraform).\n- Familiarity with frontend technologies (e.g., TypeScript, React).\n- A proactive attitude and a sense of ownership for delivering high-quality features.\n\nCommunication\n- Strong interpersonal and communication skills with experience working in cross-functional teams.\n- Enthusiastic about mentoring and supporting the growth of other engineers.\n- High level of ownership and accountability.\n- Business-level English proficiency (4 skills).\n\nTop 3 reasons to join us\n- Hybrid working; Flexible time; Macbook Pro\n- L&D programs; 17 days off\n- 13.7 million B2C users; 140,000+ business customer\n\nWhy you\'ll love working here\nCaring Mental & Physical Recreation: \n- Hybrid working\n- Full salary in probation & 13th month salary\n- Social insurance on full salary from probation\n- Premium Health insurance from probation\n- Flexible start 8AM-9AM from Mon-Fri\n- 16 days off annually + 1 Birthday Leave \n- Paternity leave extra 5 days \n- Annual company trip; Quarterly team building activities\n- Club activities\n- Annual health check \nCaring Career & Development: \n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- Well-equipped facility: Macbook pro,  additional monitor,.. \n- Soft skill workshops\n- Tech seminars\n- Monthly and biannually Recognition Awards\n- Performance review twice/year', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ETown Central Building, 11 Doan Van Bo, Ward 13, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(601, 451, 2, 'Android Developer (Flutter)', 'Job description\n• Tham gia xây dựng và triển khai ứng dụng Mobile/Tablet (Flutter)\n• Nghiên cứu giải pháp và triển khai giải pháp theo yêu cầu của từng sản phẩm\n• Tối ưu và nâng cấp mã nguồn để đảm bảo hiệu quả, ổn định và an toàn, có hiệu suất cao và thân thiện với người dùng.\n• Tìm giải pháp, lên kế hoạch ý tưởng giải quyết các tính năng mới hoặc các vấn đề người dùng gặp phải\n• Tham gia, đề xuất các phương án tối ưu trải nghiệm người dùng cho ứng dụng/ Launcher\n\nYour skills and experience\n• Có kinh nghiệm lập trình Flutter từ 2 năm trở lên.\n• Thành thạo làm việc với Git.\n• Có kiến thức về OOP, giải thuật, design pattern.\n• Nắm được các mô hình MVP, MVVM.\n• Có kinh nghiệm lập trình các ứng dụng Android, lập trình cross-platform.\n\nWhy you\'ll love working here\n• Thưởng cuối năm thưởng hiệu quả công việc....\n• Thưởng các ngày lễ, Tết; sinh nhật, thưởng sáng kiến...\n• Môi trường làm việc trẻ, năng động. Môi trường làm việc ổn định, lâu dài, cơ hội học hỏi các công nghệ mới nhất, cơ hội trưởng thành, tiến thân.\n• Du lịch, khám sức khỏe định kỳ.\n• Các khoản phụ cấp khác: Phụ cấp ăn trưa, gửi xe, công tác...\n• Đóng BHXH, BHYT, BHTN.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'VP Tầng 9, tòa nhà Viwaseen, 48 Tố Hữu, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(602, 227, 2, 'Intermediate/Senior Data Engineer', 'Top 3 reasons to join us\n1. Top-notch Annual Income\n2. Global Health Insurance\n3. 5-star Office in the centre of Hanoi\n\nJob description\n1. Design, develop, and maintain scalable data pipelines and ETL/ELT processes to collect, clean, and process large-scale datasets in data systems.\n2. Collaborate with Data Scientists, Data Analysts, and other stakeholders to understand data requirements and develop Data Lake and Data Warehouse solutions for analytics, reporting, and AI/ML. Utilize BI tools like Grafana, AWS QuickSight, and Google Sheets for data visualization.\n3. Build and optimize data architecture, including Lakehouse (AWS S3, Delta Lake), Data Warehouse (Redshift), and technologies like Kafka for both streaming and batch data processing.\n4. Monitor and troubleshoot data pipeline issues to ensure data integrity and timely delivery. Utilize tools such as Sentry, Grafana, Prometheus, and AWS CloudWatch to track logs and send alerts via Slack.\n5. Document technical processes, maintain data catalogs, and ensure compliance with data governance policies. Use the Atlassian toolset (Jira, Confluence) or Slack for work management and team collaboration.\n6. Optimize the performance, reliability, and cost-efficiency of data systems. Enhance the scalability and efficiency of all components, including Kafka, dbt, Airflow, Airbyte, and storage solutions like PostgreSQL, Elasticsearch, Redis, and AWS S3, as well as data processing and orchestration frameworks.\n7. Continuously research and implement new technologies to optimize the current system, applying best practices in Data Engineering and DataOps.\n\nYour skills and experience\n1. Bachelor\'s degree in Computer Science or a related field.\n2. 4+ years of experience in data engineering, ETL development, or a similar role.\n3. Proficiency in using advanced SQL queries to extract valuable insights from datasets.\n4. Proficiency in one of the following programming languages: Python, C#, or Java for data processing and scripting.\n5. Experience with relational databases, such as PostgreSQL, MySQL, Oracle, or MS SQL Server.\n6. Experience with cloud computing platforms (e.g., AWS, GCP, Azure).\n7. Knowledge of data architecture concepts and cloud-based storage solutions.\n8. Knowledge of document databases, including Elasticsearch, Redis, MongoDB, or Apache Solr.\n9. Strong problem-solving skills, attention to detail, and the ability to work independently or as part of a team.\n10. Excellent communication and collaboration skills, particularly in an Agile environment.\n11. Proficient in English, with the ability to communicate, read, and write effectively in a professional work environment.\n\nPreferred (but not required)\n1. Knowledge of container orchestration, such as AWS EKS or Kubernetes.\n2. Experience with microservice architecture.\n3. Experience with data visualization tools, such as AWS QuickSight or Grafana.\n4. Experience with data streaming platforms, such as Apache Kafka or Apache Nifi.\n5. Familiarity with data integration from various sources, such as web services, APIs, and file systems.\n6. Familiarity with the Agile toolset, such as GitLab, Jira, Confluence, and Slack.\n\nWhy you\'ll love working here\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\nExceptional Compensation\n1. Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n2. Total annual compensation $40,000, reflecting your expertise and contribution.\nGrowth Opportunities\n1. Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n2. Clear career advancement pathways and access to continuous professional development programs.\nGlobal Vision\n1. Contribute to projects that redefine how brands connect with consumers globally.\n2. Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\nIn addition to development tasks, you’ll collaborate closely with other CoEs to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(603, 452, 2, 'Middle/Senior Backend Developer (NodeJS/NestJS)', 'This is a full-time, on-site role for a Mid/Senior Backend Developer (NodeJS/NestJS) at Uniscore in Ho Chi Minh City. As a Backend Developer, you will be responsible for developing and maintaining the server-side of the application, collaborating with the front-end developers, and designing databases. You will also be involved in code review and troubleshooting to ensure high-quality software development.\n\nResponsibilities:\n- Work directly with the Product Owner and other IT developers to clarify requirements and propose solutions.\n- Participate in the complete software development cycle (requirement analysis, planning, implementation, code review, testing, deployment, operation, monitoring, etc.).\n- Develop new features requested by the Product Owner.\n- Backup source code, optimize security layers, and monitor server performance to handle high user loads.\n- Continuously listen to user feedback to find ways to improve product quality.\n- Research technologies and share knowledge with colleagues.\n\nYour skills and experience:\n- 3+ years of experience in back-end development.\n- Expertise in JavaScript, NodeJS (ExpressJS, NestJS).\n- Experience in deploying NodeJS backend applications to servers.\n- Strong understanding of database design: SQL and NoSQL.\n- Familiarity with database services: PostgreSQL, MySQL, DynamoDB, Elasticsearch.\n- Experience with API design: GraphQL, RESTful.\n- Experience in integrating APIs with third-party services (Google Cloud, Firebase, Payments, etc.).\n- Knowledge of CI/CD and proficiency in writing unit tests.\n- Ability to scale an application to support millions of users.\n- Eager to enhance technical knowledge and explore/adopt new technologies.\n- Strong analytical and problem-solving skills.\n- Proactive, honest, and committed to self-improvement.\n- Profound knowledge of servers, Nginx, caching strategies, HAProxy, and Varnish Cache.\n\nWhy you\'ll love working here:\n- Competitive salaries and bonuses\n- Participate in work vacations and teambuilding activities.\n- Many bonuses on big occasions such as April 30, September 2, birthdays, or help for weddings, funerals, Tet presents, and Mid-Autumn gifts.\n- Happy hours every Thursday\n- Clear and comprehensive wage and bonus review policy every year\n- 13th month wage plus annual bonuses (based on business scenario)\n- Opportunity to sign up for a 5-star gym\n- Participate in after-hours activities like football, badminton, game tournaments, and gym opening.\n- Beautiful rooms with numerous conveniences in the office.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '628A Đ. Võ Nguyên Giáp, An Phú, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(604, 227, 2, 'Data Product Manager, Global Supply Chain System', 'Top 3 reasons to join us\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description\n- Establish clear goals for inventory optimization - such as minimizing stockouts, reducing overstock, or improving replenishment cycles - aligned with overall business strategy.\n- Create and maintain a product roadmap that prioritizes initiatives (e.g., real-time inventory monitoring, and automated reordering systems).\n- Collaborate with supply chain teams, operations, finance, marketing, and customer service to understand pain points and business needs.\n- Translate business problems into clear, actionable product requirements and user stories for data science and engineering teams.\n- Work closely with data scientists, engineers, UX/UI designers, and business analysts to build and refine data products\n- Partner with data scientists to design, test, and validate predictive models and algorithms\n- Work with analytics teams to build dashboards and visualizations that provide real-time insights\n- Oversee the integration of disparate data sources (e.g., sales, supplier data, and warehouse systems) to create a unified view for analytics.\n\nYour skills and experience\n- Background in Data Science, Data Engineering, Data Analysis, or Product Management\n- Knowledge of statistical modeling and machine learning techniques\n- Proficiency in data analysis tools like Excel, SQL, Python, and data visualization software\n- Strong problem-solving skills and ability to think analytically\n- Strong verbal and stakeholder-facing communication skillset\n- Solid documentation writing skills\n- English proficiency\n- Knowledge of Agile methodologies and experience working in Agile environments\n\nPreferred (but not required)\n- Strong business acumen and understanding of e-commerce operations\n- Experience with inventory management systems and software\n- Experience in managing projects, including setting timelines, milestones, and deliverables\n\nWhy you\'ll love working here\n- We’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\n\nExceptional Compensation\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total annual compensation over $100,000, reflecting your expertise and contribution.\n\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale business.\n- Clear career advancement pathways and access to continuous professional development programs.\n\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, and operational efficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(605, 453, 2, 'Senior Fullstack Engineer (NodeJS/Typescript preferred)', 'Top 3 reasons to join us\n- Culture Built by Tech People, for Tech People\n- Flexible In-Office and Remote Work Arrangements\n- Premium Health Coverage\n\nJob description\n- Develop, support, and maintain software applications using best practices across a range of technologies ensuring high-quality, maintainable, efficient, tested, and scalable code.\n- Provide input into the target state architecture for the platform.\n- With their peers, develop a robust, automated, and modern CICD practice within the team.\n- Developing high-quality solutions collaboratively with the team and appropriate members throughout the engineering function using a mix of front-end (web and mobile) and back-end technologies.\n- Working incrementally towards delivery of the platform. Collaborating closely with Product using customer data and insights to drive the solutions.\n- Establishing strong quality and automation practices and processes.\n- Working closely with our Platform teams to implement software leveraging our internal platforms, tools, frameworks, and infrastructure where appropriate.\n- Collaborating closely with product owners, delivery leads, and business analysts to break down, estimate, and deliver business requirements.\n- Contributing to the improvement of software development lifecycle processes.\n- Participate in and, at times, facilitate Engineering Dojos driving a culture of Engineering Excellence.\n- Provide continuous support and guidance to less senior colleagues through regular coaching activities and support them in fulfilling their personal development plans.\n\nYour skills and experience\n- Proficient in verbal and written English\n- 5+ years of software engineering experience\n- Expertise in TypeScript/JavaScript, React, and front-end development; proficiency in full-stack development with at least one server-side language (NodeJS preferred).\n- Hands-on experience with AWS.\n- Experienced in Continuous Delivery practices (CI, TBD, etc.)\n- Hands-on experience of testing methodologies (e.g., TDD, BDD, mocking) or a willingness to develop further in this area.\n- Experience using automation tools to build robust, automated build/release/deploy processes (e.g. GitHub Actions).\n- Experience leveraging modern software design patterns (e.g., SOLID, Strategy/Observer/Facade, hexagonal architecture) and both object-oriented and functional programming.\n- Experience using, building, and running containers locally and exposure to concepts pertaining to container orchestration in a production environment (e.g. ECS, EKS/Kubernetes, docker-compose).\n- Commitment to continuous learning and staying up to date with software engineering trends.\n- Experience in designing team and service interfaces, leveraging contracts and specifications (OpenAPI / Swagger) to drive discussions and designs.\n- Proven ability to work successfully in and with a remote, global team.\n\nWhy you\'ll love working here\nJoin us to make the world a better place. Every day is an opportunity to learn new things and do something you\'re proud of.\n\nOUR VALUES\n- Collaboration: At CBTW, collaboration is the heart of our success. We foster a culture where our people, clients, and network work together, to encourage innovative ideas and deliver meaningful results that shape a better world.\n- Commitment: We are dedicated to making a positive impact on the environment and society. At the heart of our commitment is education, as we firmly believe in empowering future generations with knowledge and opportunities. Through allocating a significant portion of our resources, we aim to create a better world and contribute to a sustainable future.\n- Evolution: We eagerly embrace change, cultivating an environment of continuous evolution. We empower our team with personalized career paths, that fuel growth and enhance skills. We prioritize improvement and innovation, delivering advanced solutions to clients, and aim to strengthen alliances within our network of partners.\n- Positive Thinking: We infuse optimism and creativity into all aspects of our work through Positive Thinking. We approach every situation with open-mindedness, transparency, flexibility, and solution orientation. Working together, we bring our positive dynamism to benefit our people, clients, and network.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(606, 454, 2, 'Junior React Developer (ReactJS, JavaScript)', 'Job description\n- Tham gia phát triển các dự án Website, Mobile App theo định hướng và hướng dẫn của team leader.\n- Tham gia thiết kế và phát triển các tính năng, hỗ trợ bảo trì và cải tiến hệ thống hiện có.\n- Học hỏi và áp dụng các quy trình phát triển phần mềm chuyên nghiệp, đảm bảo hiệu quả và chất lượng sản phẩm.\n- Báo cáo công việc hàng ngày/tuần cho Technical Leader.\n- Phối hợp với các bộ phận liên quan để đảm bảo tiến độ và chất lượng công việc.\n- Thực hiện các công việc khác theo sự phân công từ cấp trên.\n\nYour skills and experience\n- Tư duy học hỏi tích cực, khả năng làm việc nhóm tốt, có tinh thần trách nhiệm và cam kết.\n- Có thể làm việc độc lập với các task được giao và chủ động tìm hiểu giải pháp.\n- Có kiến thức cơ bản về:\n  - React (ReactJS, React Native), JavaScript, TypeScript\n  - HTML/CSS, Git, RESTful API\n- Ưu tiên có hiểu biết hoặc từng thực hành với:\n  - Redux, NextJS, PostgreSQL\n  - Công cụ build và release ứng dụng Android/iOS cơ bản\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc tương đương.\n- Có trên 1 năm kinh nghiệm thực tế liên quan đến ReactJS hoặc React Native.\n\nƯu tiên\n- Có khả năng đọc hiểu tài liệu kỹ thuật bằng tiếng Anh (tương đương IELTS 5.0+ là một lợi thế).\n- Ứng viên đã từng làm việc hoặc có dự án liên quan đến hệ thống ERP hoặc ứng dụng Chat.\n- Có sản phẩm cá nhân đã được public trên GitHub, store hoặc portfolio cá nhân.\n\nWhy you\'ll love working here\n- Lương: 10 – 12 M.\n- Tham gia vào các dự án phát triển App, plugin thú vị và đa dạng\n- Thưởng tháng thứ 13, thưởng dự án (Thưởng thành tích, thưởng cá nhân xuất sắc)\n- Các chế độ phúc lợi: Team-building hàng tháng, nghỉ mát hàng năm, khám sức khoẻ định kỳ…\n- Được tham gia các chương trình đào tạo nội bộ, và các trung tâm đào tạo kỹ năng\n- Các chế độ theo quy định của Pháp luật Lao động Việt Nam (BHXH, BHYT, BHNT…)\n- Nghỉ phép năm, nghỉ lễ tết theo quy định của Nhà nước Việt Nam\n- Môi trường làm việc chuyên nghiệp, trẻ trung và chia sẻ.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 145 Ngọc Hồi, Hoang Mai, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(607, 217, 2, 'Senior Backend Engineer (Golang, Agentic, AI)', 'About Us\nReforged Labs is a YC-backed, Sandhill Road funded AI startup revolutionizing how the world\'s top mobile gaming studios market themselves to hundreds of millions of players. We\'re building cutting-edge AI technology that powers sophisticated ad analysis and generation pipelines for elite global gaming companies.\nWe don\'t follow trend; we set them. Our engineering team builds solutions that rival the best Silicon Valley has to offer, creating technology that generates millions of dollars in value for our customers.\n\nThe Role\nWe\'re seeking an exceptional Senior Backend Engineer to join our fast-growing team in Ho Chi Minh City. This is not a role for the average developer; we\'re looking exclusively for extraordinary talent who can compete with the best engineers globally.\n\nYou\'ll design and implement robust backend services that power our AI-driven platforms, working at the intersection of distributed systems, cloud infrastructure, and machine learning operations. Your code will directly impact how hundreds of millions of players discover and experience games.\n\nCore Responsibilities\n- Architect and build intelligent agent systems that can understand context, plan execution paths, select appropriate tools, and process data with exceptional accuracy\n- Design scalable, high-performance systems for processing and analyzing large volumes of video ad performance data\n- Implement sophisticated APIs that enable real-time ad performance analysis and automated content generation\n- Create efficient data pipelines and workflows that integrate with advanced AI capabilities\n- Drive technical decisions that will shape our platform\'s architecture and future direction\n- Build Agentic Workflows that can consistently deliver value\n- Ship production-ready features that provide demonstrable multi-million dollar value to our customers.\n\nYour skills and experience\nRequired Experience\n- 5+ years of backend development experience building complex distributed systems\n- Strong experience with Golang, with demonstrated mastery of concurrency patterns, performance optimization, and idiomatic code\n- Proven track record building production services on AWS or GCP, leveraging their full ecosystem of tools\n- Experience with design patterns for agentic workflows and prompt engineering\n- Exceptional problem-solving skills with a history of solving complex technical challenges independently\n- Experience building and maintaining high-throughput production REST APIs and microservices\n- Having built Agentic Workflows in production-ready applications\n- Deep understanding of software architecture patterns, distributed systems, and clean code principles\n- Professional English communication skills—both verbal and written\n\nEssential Qualities\n- Self-leadership: You can drive technical initiatives from conception to completion with minimal guidance\n- Intellectual curiosity: You stay ahead of technical trends and continuously expand your knowledge\n- High standards: You\'re never satisfied with "good enough" and push for technical excellence\n- Collaborative mindset: You thrive in environments where ideas are openly discussed and challenged\n- Speed and execution focus: You balance perfectionism with pragmatism to ship high-quality code rapidly\n- Passion for solving hard problems: You\'re energized rather than drained by technical challenges\n\nInterview Process\n1. Initial Technical Screen (45-60 mins)\n- Algorithm problem-solving exercise\n- Technical background discussion\n- High-level experience overview\n2. Take-Home Project (1 week to complete)\n- Real-world problem related to our domain\n- Opportunity to demonstrate your skills comprehensively\n3. Project Review & System Design (60-90 mins)\n- Deep dive into your project implementation\n- Architecture and scalability discussion\n- Advanced system design challenge\n4. Final Leadership Conversation (60 mins)\n- Vision alignment with founders\n- Culture and team fit discussion\n- Two-way Q&A about growth opportunities\n\nWe aim to complete the entire process within 2-3 weeks.\nNote: This role is designed for elite engineering talent. If you\'re not consistently recognized as among the most capable engineers in your current organization, this position is likely not a good fit. We\'re looking for candidates who can demonstrate outstanding technical abilities and deliver outsized impact.\nIf you believe you\'re among the most skilled backend engineers and are excited about building cutting-edge AI systems, we want to talk to you.\n\nWhy you\'ll love working here\nWhy You\'ll Love Working Here\n- Industry-leading compensation package\n- Work on technology that is genuinely world-class and cutting-edge, not just by local standards\n- Build products that compete globally and set new industry standards\n- Compensation package targeting top-tier engineers (significantly above local market rates)\n- Opportunity to be an early engineer at a rapidly growing, well-funded AI startup\n- Direct impact on products used by major gaming studios reaching hundreds of millions of users\n- Potential for international recognition and career advancement opportunities\n- Challenging, fast-paced environment that will accelerate your professional growth\n- Collaborative culture where your ideas matter and technical excellence is valued\n\nOur Engineering Culture\n- We operate in agile sprint cycles with a focus on rapid iteration and continuous delivery. Our\nteam values independence and ownership, with each engineer taking full responsibility for their features from architecture to production deployment.\n- We maintain high standards for code quality while moving quickly to meet market demands. We are building a culture that combines Silicon Valley engineering practices with exceptional local talent.\n- Located in Ho Chi Minh City, we\'ve created a work environment that combines Silicon Valley engineering practices with local talent, offering the unique opportunity to work on global-scale problems while being part of Vietnam\'s growing tech ecosystem.\n- We are an equal opportunity employer and value diversity at our company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 , 2 Thi Sách, Phường Bến Nghé, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(608, 455, 2, 'Business Analyst (Upto  $1600, Product Company)', 'Job description\n- Proactively engage in the software development process by eliciting, researching, analyzing, and consulting on business requirements for key projects.\n- Attend meetings with the North American product team to gather and clarify product requirements.\n- Create detailed documentation and requirements specifications for development.\n- Collaborate with testers to ensure development outcomes meet agreed-upon requirements.\n- Draft and distribute user manuals and guides for end-users.\n- Perform other tasks as assigned by the supervisor.\n\nYour skills and experience\nQualifications:\n- At least 3+ years of experience working as a Business Analyst (BA).\n- Strong verbal and written English skills, capable of supporting the team with English documentation.\n- Excellent analytical skills with the ability to understand complex software systems quickly.\n- Proficiency in creating clear, concise documentation.\n- Strong communication, presentation, and management skills, with the ability to handle multiple projects simultaneously.\n- Experience in ERP, E-Commerce, or the Telecommunication domain is preferred.\n- Basic understanding of databases, particularly MySQL.\n- A bachelor\'s degree in Computer Science, Software Engineering, Information Technology, or a related field is a plus.\n\nWhy you\'ll love working here\nIf you thrive in a fast-paced and dynamic environment, consider Softel Solutions, a wholly-owned telco subsidiary of HTH Communications headquartered in Hanoi, as the perfect place to advance your career. As a subsidiary of HTH Communications, Softel is a leading software provider offering unparalleled support in the wireless industry. We provide services to nationwide carriers, regional operators, MVNOs, independent agents, and equipment manufacturers. Our FCC-licensed ETC designations enable us to provide broadband Prepaid wireless services to over million subscribers nationwide through our affiliate brands: AirVoice Wireless, AirTalk Wireless, and TAG Mobile.\n\nSoftel Solutions with 2 modern office branches and fully equipped with office equipment will provide employees with a professional and safe working environment. We provide employees with the following existing benefits and we will continuously develop our talents\' benefit packages better in the future:\n- Flexible working time: 8 hours/day from Monday to Friday. You will work at the office from 9:00 AM - 6:00 PM.\n- 12 annual days, 11 public holidays, pay insurance (BHXH, BHYT, BHTN), and other benefits based on the Vietnam Labor Code.\n- Review salaries and bonuses annually based on employee performance.\n- Extremely valuable awards honor outstanding groups and individuals at the Year-end Party.\n- Project bonus and salary review according to the work quality.\n- Opportunity to travel and on-site work in the US.\n- Working with major carriers in the US.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, Tòa nhà Geleximco, 36 phố Hoàng Cầu, Ô Chợ Dừa, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(609, 456, 2, 'Tech Lead', 'Top 3 reasons to join us\n- Performance & salary review yearly\n- Yearly performance bonus\n- Full salary-based social insurance & PVI Insurance\n\nJob description\nSearch & Personalization\nKey Responsibilities\n- Search Optimization – Design and improve search ranking algorithms, query understanding, and relevance models to enhance product discovery.\n- Recommendation Systems – Build and refine AI/ML-driven recommendations that drive conversions, increase order size, and improve user engagement.\n- Personalization & AI – Develop dynamic, real-time personalization models based on user behavior, transaction history, and contextual data.\n- Scalability & Performance – Optimize search indexing, ranking, and filtering for high performance and reliability across millions of products and users.\n- Data-Driven Decision Making – Work with Data Science and Product teams to analyze search patterns, user behavior, and performance metrics to improve search and recommendation accuracy.\n- A/B Testing & Experimentation – Implement and manage experimentation frameworks to test new ranking models, personalization strategies, and UI/UX improvements.\n- Collaboration – Work closely with Product, UX, Engineering, and Business teams to align search and personalization logic with customer needs and business goals.\n- Mentorship & Best Practices – Guide engineers in search infrastructure, ML models, and scalable system design while enforcing clean, maintainable, and efficient code.\n\nSeller Experience & Operations\nKey Responsibilities\n- Seller Center Development – Lead the development of Buymed’s Seller Center, ensuring a smooth onboarding experience, intuitive dashboard, and robust performance tracking for sellers.\n- Warehouse Management System (WMS) – Enhance inventory tracking, inbound/outbound processes, and automation for efficient warehouse operations.\n- Transportation Management System (TMS) – Develop and maintain route optimization, real-time tracking, and fleet management tools to improve delivery efficiency.\n- Operational Efficiency & Automation – Drive process automation across fulfillment, logistics, and seller operations to reduce costs and increase throughput.\n- Scalability & Performance – Ensure system reliability and scalability to support high transaction volumes and expanding logistics operations.\n- Collaboration – Work closely with Logistics, Supply Chain, Product, and Engineering teams to improve fulfillment workflows and seller experiences.\n- Monitoring & Troubleshooting – Implement real-time monitoring, predictive maintenance, and data-driven insights to proactively resolve system bottlenecks.\n- Mentorship & Code Quality – Lead by example, ensuring high-quality code, conducting code reviews, and mentoring engineers in system design and best practices.\n\nCustomer Experience\nKey Responsibilities\n- Technical Leadership – Own the architecture, development, and optimization of PDP, Checkout, and Dashboard to drive conversions and improve user engagement.\n- Scalability & Performance – Ensure fast load times, reliable order processing, and a seamless checkout experience for thousands of daily transactions.\n- Collaboration – Work closely with Product, UX/UI, Data, and Engineering teams to create intuitive and data-driven customer experiences.\n- Mentorship & Code Quality – Lead by example, conducting code reviews, mentoring engineers, and driving a culture of technical excellence.\n- System Design & Innovation – Continuously improve Buymed’s PDP, checkout, payments, and customer dashboard, integrating the latest technologies and best practices.\n- Monitoring & Troubleshooting – Ensure high availability, reliability, and bug-free experiences across core purchasing flows.\n\nYour skills and experience\n1. Tech Lead – Customer Experience\n- Lead a team focused on building user-facing features with high performance, stability, and great UX.\n- Proficient in both frontend and backend (React, Golang), API design, microservices architecture on GCP.\n- Experienced in performance optimization, concurrency, caching strategies, and developer efficiency (CI/CD, automation).\n- Preferred: background in eCommerce, user engagement optimization, A/B testing, or checkout flow improvements.\n\n2. Tech Lead – Seller Experience & Operations\n- Lead the development of systems that empower sellers and optimize operational processes (seller tools, logistics, backend ops).\n- Strong expertise in Golang, distributed systems, scalable microservices, and event-driven architecture.\n- Deep knowledge of database design, caching, cloud infrastructure (GCP), and operational automation.\n- Preferred: experience in eCommerce, logistics, supply chain, or optimization models (e.g., demand forecasting).\n\n3. Tech Lead – Search & Personalization\n- Lead the development of intelligent search and personalization systems leveraging AI/ML.\n- Expertise in search platforms (Elasticsearch, OpenSearch, etc.), ranking algorithms, vector/semantic search.\n- Strong skills in Python or Golang, big data tools (Spark, Kafka, Airflow), and distributed microservices.\n- Preferred: experience with deep learning, multi-modal search (text/image/voice), and A/B testing frameworks.\n\nWhy you\'ll love working here\n- Performance & salary review yearly\n- Paid social insurance based on full salary\n- PVI Insurance\n- Medical Checkup\n- 15 days of annual leave\n- Parking allowance', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vincom Center Đồng Khởi, 45A Lý Tự Trọng, p. Bến Nghé,, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(610, 457, 2, 'Junior Java Developer (SQL, Spring)', 'Top 3 reasons to join us\n\n- Nền tảng cơ sở vững chắc\n- Đội ngũ nhân lực chuyên nghiệp\n- Môi trường làm việc thân thiện, tiềm năng\n\nJob description\n\n- Bảo trì và phát triển hệ thống bán lẻ tại thị trường Nhật Bản:\n- Điều tra & giải quyết vấn đề được liên lạc (thiết kế, code, test)\n- Tham gia nghiên cứu, thực hiện các dự án mới\n\nYour skills and experience\n\n- Thành thạo Web (HTML, Javascript, CSS)\n- Nắm vững Java, có kinh nghiệm làm việc trên các MVC Framework như Struts, Spring\n- Kiến thức tốt về DB: SQL Server/Oracle, ưu tiên có kinh nghiệm tối ưu truy vấn query\n- Có kinh nghiệm sử dụng Git / SVN\n- Tiếng Anh: đọc viết\n- Tiếng Nhật: biết tiếng Nhật là lợi thế\n- 1 - 3 năm kinh nghiệm\n\nƯu tiên ứng viên:\n\n- Biết tiếng Nhật cơ bản hoặc có kinh nghiệm làm việc tại công ty Nhật\n- Có kinh nghiệm trong lĩnh vực bán lẻ\n\nWhy you\'ll love working here\n\n-能力と現在の給与に基づいて支給に拠り決定\n- 昇給1年1回, 賞与1年2回\n- 社員旅行　１年1回\n- 成績優秀者は日本への研修旅行招待\n- 当社は2014年1月にベトナムで設立されたばかりの会社で皆さんに平等に成功のチャンスがあります。\n- 当社は日本で最大手の流通小売業向けのSystem Integratorです。日本への出張や研修に参加出来るチャンスが多くあります\n- 法律上の有給休暇以外、９日の特休休日が取得可能\n\n- Được xác định dựa trên năng lực và mức lương hiện tại\n- Tăng lương 1 năm 1 lần, thưởng 2 lần/năm\n- Company trip mỗi năm 1 lần\n- Nhân viên xuất sắc được mời đi du lịch Nhật Bản.\n- Công ty chúng tôi mới thành lập tại Việt Nam vào tháng 1 năm 2014, vì vậy mọi người đều có cơ hội thành công như nhau.\n- Công ty chúng tôi là nhà tích hợp hệ thống cho ngành phân phối và bán lẻ lớn nhất Nhật Bản. Có nhiều cơ hội tham gia các chuyến công tác và đào tạo tại Nhật Bản\n- Ngoài ngày nghỉ phép hàng năm, công ty còn có thêm khoảng 9 ngày nghỉ phép đặc biệt', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'WASECO building,10 Pho Quang Street, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(611, 458, 2, '[HCM] Salesforce Developer (All level) | Up to 55M VND', 'Job description:\n- Use Salesforce APIs to integrate Salesforce with other tools and third-party applications\n- Actively focus on developing effective communication and relationship-building skills, with stakeholders, clients, and team.\n- Thorough understanding of Manufacturing data models, design considerations, and connected external systems\n- Data Migration in Salesforce\n\nMust have:\n- Bachelor’s Degree in Computer Science or related field\n- From 3 – 6+ years experience as a Salesforce Developer.\n- Have Salesforce Platform Developer 1 Certified.\n- Apex development.\n- Hands-on experience in administration setup, e.g., managing users, security controls, and data as well as creating roles, profiles, and reports.\n- Experience in designing custom objects, custom fields, picklists, page layouts, workflow, approval processes, validation rules, custom tabs, reports, Visualforce pages, dashboards, and email generation according to application requirements\n\nNice to have (Optional):\n- Candidates with the following Salesforce certifications are preferred:\n  - Salesforce Administrator\n  - Salesforce Platform Developer I, II\n  - Salesforce Application Architect\n  - Salesforce Javascript Developer I\n  - Salesforce Certified Administrator (SCA)\n- Good English or Japanese.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Dong Nhan Building, 90 Nguyen Dinh Chieu, Da Kao, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(612, 356, 2, 'Middle/Senior Java Developer (Spring Boot, English, AI)', 'Top 3 reasons to join us\n- Attractive salary, benefits, hybrid working\n- Technical training sessions (internal – external)\n- PVI Healthcare insurance\n\nJob description\n- Design, build and maintain APIs, services\n- Debug production issues across services and multiple levels of the stack\n- Work with engineers across the company to build delightful features that span various parts of the system\n- Collaborate with our business, product, and operations teams to understand and solve our users’ pain points\n\nYour skills and experience\nMUST HAVE SKILLS:\n- You have 5+ years of software development experience\n- You have strong software development experience using Java\n- You have experience in Spring MVC, Spring Boot, Hibernate, building Restful\n- Knowledge of Cloud services such as AWS or Azure\n- Experience with Micro Services\n- Experience with Docker, GitHub Actions, Terraform\n- Experience with PostgreSQL and Redi\n- Strong English communication (speaking)\nNICE TO HAVE:\n- Experience : Copilot, Claude, MCP, N8N...\n\nWhy you\'ll love working here\nCompetitive Salary and Brilliant Health Benefits\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan\n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program\n- The staff of the quarter and year reward\nProgressive and Fun Working Environment\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support.\n- Surrounded with friendly, open-minded, young and supportive colleagues\n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\nValuable Training\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Orchard Parkview, 130 – 132 Hong Ha, Ward 9, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(613, 459, 2, 'Product Owner Manager', 'Infinity Technologies Global là công ty công nghệ được thành lập bởi các Founder nhiều kinh nghiệm, tập trung phát triển các sản phẩm công nghệ phục vụ hàng trăm triệu người dùng toàn cầu. Chúng tôi đang từng bước tạo ra hệ sinh thái toàn diện, đầy đủ với rất nhiều sản phẩm có hàm lượng công nghệ cao đáp ứng mọi nhu cầu người dùng.\nTầm nhìn và mục tiêu chiến lược tới 2026:\n- Hệ sinh thái đạt trên 1B+ người dùng toàn cầu.\n- Mở rộng các Business thành viên hoạt động trong lĩnh vực Mobile App, Software, Blockchain, Mobile game và Venture Capital.\nVăn hoá doanh nghiệp:\n- Thẳng thắn, minh bạch, công bằng\n- Tốc độ, chinh phục\n- Tập trung mục tiêu\nChúng tôi không tuyển nhân sự, chúng tôi TÌM KIẾM CỘNG SỰ cho mục tiêu chinh phục global.\nNếu bạn là người đam mê chinh phục, có tham vọng lớn và dám hành động để đạt được kết quả đột phá, chúng tôi là nơi tốt nhất dành cho bạn.\n1. Mô tả công việc\n- Phụ trách team product làm những sản phẩm mobile app trên thị trường global liên quan tới tool & productivity, photo & video, entertainment, AI,... (CH Play và App Store)\n- Tối ưu sâu những sản phẩm hiện đang kinh doanh theo hướng data-driven.\n- Xây dựng, đào tạo và quản lý đội ngũ nhân sự thuộc team product.\nYour skills and experience\n- Bắt buộc:\n  - Có kinh nghiệm đảm nhiệm vai trò Leader/Manager ở vị trí liên quan đến Product Owner trong các công ty Mobile Apps/Games, hoặc từng làm việc ở vị trí tương đương tại các công ty công nghệ.\n  - Có tư duy End User và Customer Centric, Data-driven.\n  - Có hiểu biết sâu sắc và thành thạo các công cụ phân tích người dùng (Firebase, Google Analytics, Apple Connect, Revenue Cat...)\n  - Quản lý được toàn bộ chu trình build và tối ưu sản phẩm, phân bổ nguồn lực.\n  - Có kinh nghiệm tuyển dụng, đào tạo và phát triển đội ngũ nhân sự.\n  - Có Business Sense, có thể chuyển hoá từ mục tiêu kinh doanh sang chiến lược sản phẩm.\n  - Hiểu rõ và có kinh nghiệm trong việc xây dựng sản phẩm theo mô hình Agile/Scrum.\n  - Có kiến thức, kinh nghiệm và phương pháp làm việc cực kỳ chặt chẽ, sáng tạo, logic, được chứng minh qua quá trình làm việc và thành tích đạt được.\n  - Có kỹ năng lập kế hoạch rõ ràng theo mục tiêu và lộ trình phát triển sản phẩm của công ty.\n  - Thành thạo kỹ năng đọc - viết tiếng Anh.\n- Ưu tiên:\n  - Ưu tiên các ứng viên sinh năm 1990-1996.\n  - Có kinh nghiệm làm các sản phẩm liên quan đến Mobile App là lợi thế.\n  - Có niềm đam mê trong việc xây dựng sản phẩm và thiết kế lấy người dùng làm trung tâm.\n  - Kỹ năng giao tiếp và thuyết trình tốt.\nWhy you\'ll love working here\n- Mức lương 30.000.000 - 45.000.000 VNĐ.\n- Review lương, thưởng 2 lần/ năm (Tháng 1 và tháng 7), mức lương tăng upto 25%/ đợt review, thưởng 1-4 tháng lương/năm.\n- Thưởng ngày lễ, sinh nhật cho CBNV.\n- Trang bị các thiết bị làm việc phù hợp với công việc.\n- Có khu vực ăn uống riêng, khu căng tin hoàn toàn miễn phí.\n- Chương trình Khám sức khỏe định kỳ hằng năm.\n- Chương trình Happy Time vào chiều thứ 6 hàng tuần.\n- Ngày nghỉ phép còn lại trong năm sẽ được chuyển sang ngày lương.\n- Môi trường làm việc chuyên nghiệp, lành mạnh, cơ hội thăng tiến cao.\n- Các chương trình, hoạt động vui chơi giải trí vào các dịp lễ, Tết, du lịch, team building.\n- Hệ sinh thái các sản phẩm có hàng triệu người dùng hàng tháng trên toàn cầu: Âu, Úc, Mỹ, Ấn Độ, Brazil, South Africa...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2, tòa nhà Đồng Lợi, ngõ 1160 đường Láng, Láng Thượng, Đống Đa, Hà Nội, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(614, 331, 2, 'Mobile Engineer (Flutter)', 'As a Mobile Engineer at Teko, together we shape our product. In doing so, you\'ll face a huge amount of challenges that you may not have a chance to face in any other companies out there. They are:\n\n- Write clean code to develop & maintain mobile applications (android/iOS) in digital transformation projects\n- Ensure UI/UX of mobile applications\n- Research and provide solutions for digital transformation problems\n- Develop base, high performance libraries to be used across projects\n- Collaborate with other team (web app, backend) to deliver feature on time with high quality\n\nYOUR SKILLS AND EXPERIENCE:\n\n- A Bachelor degree in Information Technology or relevant hands-on experience (at least 1 year) as Flutter developer\n- Knowledge of native platform (android/iOS) is a plus\n- Ability to analyze problem and express ideas clearly in communication and documentation\n- A solid Agile/Scrum mindset, comfortable with rapid iteration and continuous improvement; Proficiency in utilizing collaborative tools like Confluence, Jira, etc\n\nWhy you\'ll love working here:\n\n- Negotiable salary according to qualification (13th-month salary + performance bonus);\n- 02 months probation with 100% of Gross salary;\n- The working environment is open, energetic and professional. More opportunities for career promotion;\n- Free Food & Drink: lunch, fresh fruit/cake, coffee&tea;\n- Annual health check and attractive Premium healthcare coverage under the company’s own policy;\n- Employee Relationship: company trip, team bonding & clubs;\n- Leave Paid: 12 days for annual leave & 6 days for sick leave (max 18 days);\n- Working time: Monday to Friday (Flexible from 8:30 - 9:00 AM to 5:30 - 6:00 PM).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Gems Empire Tower, 201 Truong Chinh, Thanh Xuan, Ha Noi; 2nd Floor, 16 Nguyen Van Linh St., Nam Duong W., Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(615, 330, 2, 'Senior Data Engineer (Python, DWH, Alert)', 'Top 3 reasons to join us:\n- Competitive packages Parking fee & Lunch allowance\n- Flexible working hour. Annual leave 15 days/ year\n- Room to grow professionally. Sponsorship for L&D\n\nJob description:\n- Build the infrastructure required for optimal extraction, transformation, and loading of data from a wide variety of data sources.\n- Clarify requirements with Developers and Business users to build a data mart that meets functional/non-functional business requirements.\n- Design and maintain optimal data pipeline architecture.\n- Support internal training and proper documentation ensuring the successful onboarding of new team members.\n- Implement internal process improvements: automating manual processes, optimizing data delivery, re-designing infrastructure for greater scalability, etc.\n- Develop efficient software code for multiple use cases leveraging Spark and Big Data Technologies for various use cases built on the platform.\n\nYour skills and experience:\n- At least 5+ years’ experience working as a Senior Data Engineer role, ETL with large amounts of data. Bachelor’s degree in related technical discipline.\n- Experience with data warehousing architecture, Data modeling and ETL data pipeline.\n- Experience in monitoring data quality, code factor, Data quality control alert, ...\n- Experience with using the following software/tool in the big data field.\n- NoSQL and OLAP database: MongoDB, Elastic search, etc.\n- Good at programming languages: Scala, Python, Java.\n- Experience in the data testing process.\n- Experience in performing root cause analysis, identify problems and propose recommendations for improvement.\n- Strong organizational and multitasking skills with the ability to balance competing priorities.\n- Fundamental knowledge of modern cloud computing platforms and concepts is a plus (AWS/GCP).\n\nWhy you\'ll love working here:\n- 100% salary on your probation period.\n- 15 full-paid days off per year.\n- 13th-month bonus salary.\n- Room to grow with support from the team and sponsorship for L&D.\n- Performance review 2 times/year.\n- Competitive packages.\n- Room to grow professionally, sponsorship for learning & development of related skills.\n- Opportunity to work on a mission that can transform the lives of millions of Vietnamese.\n- Annual Performance Bonuses (up to 2 salary months per year).\n- Parking fee & Lunch allowance.\n- Annual Health Checkup, Premium Health Care (Manager level), Accident Insurance for all members.\n- Enjoy a variety of corporate events, from sports competitions, monthly birthday parties, and team building to Year-End Party, etc.\n- Flat, open, and fast-paced environment where every idea is welcomed.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '402 Nguyễn Thị Minh Khai, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(616, 397, 2, 'Senior Software Engineer (Java, Spring boot, SQL)', 'MỤC TIÊU CÔNG VIỆC: Thiết kế và phát triển các ứng dụng Java hiệu suất cao cho hệ thống LOS, CRM, đóng góp vào toàn bộ vòng đời phát triển phần mềm và cung cấp các giải pháp phần mềm có thể mở rộng và chất lượng cao.\nNHIỆM VỤ, TRÁCH NHIỆM CHÍNH:\nCộng tác với các đơn vị nghiệp vụ, bao gồm kiến trúc sư phần mềm, quản lý sản phẩm, các đơn vị kinh doanh, thiết kế để phát triển các ứng dụng Java.\nThiết kế và triển khai ứng dụng bằng ngôn ngữ Java hiệu quả và đáng tin cậy, đảm bảo hiệu suất và bảo mật.\nThực hiện đánh giá mã nguồn để duy trì chất lượng và tuân theo các tiêu chuẩn mã hóa.\nGỡ lỗi, khắc phục sự cố và giải quyết các nhược điểm và sự cố phần mềm, đảm bảo độ tin cậy của ứng dụng.\nTham gia phân tích yêu cầu và thảo luận thiết kế phần mềm để đề xuất các giải pháp sáng tạo.\nPhát triển và duy trì tài liệu kỹ thuật để tham khảo và báo cáo.\nCập nhật thông tin về xu hướng công nghệ liên quan đến Java, các cách thực hành tốt nhất và tiêu chuẩn ngành.\nXác định tầm nhìn kỹ thuật cho việc phát triển phần mềm, phù hợp với mục tiêu kinh doanh và thực tiễn tốt nhất của ngành.\nCộng tác với các nhà phát triển khác để xây dựng các giải pháp phần mềm có thể mở rộng và hiệu quả.\nGóp phần vào toàn bộ vòng đời phát triển phần mềm, từ khái niệm và thiết kế đến thử nghiệm, triển khai và hỗ trợ.\n*** LÝ DO ĐỒNG HÀNH CÙNG SHBFINANCE:\nMôi trường làm việc chuyên nghiệp, cởi mở.\nThời gian làm việc từ thứ 2 – thứ 6, nghỉ trưa 1h30’ (40h/tuần).\nChế độ làm việc Hybrid working từ 1 - 2 ngày làm việc từ xa/ tuần.\nĐồng nghiệp thân thiện, cởi mở với tư duy đề cao sự phát triển của mỗi cá nhân;\nVăn phòng làm việc với không gian mở, rộng rãi, được cung cấp đầy đủ các trang thiết bị để phục vụ cho công việc.\nQuan tâm đặc biệt đến nhân viên:\nGói đãi ngộ cạnh tranh cùng chính sách nâng lương theo định kỳ. Tổng thu nhập TB 14 tháng lương/năm;\nHỗ trợ ăn trưa lên tới 1.200.000 VND/tháng; Hỗ trợ gửi xe 200.000 VND/ tháng.\nNghỉ hưởng lương ngày sinh nhật + quà sinh nhật.\nQuyền lợi chăm sóc sức khỏe đặc quyền bảo hiểm sức khỏe toàn diện SHBFC Care;\nKhám sức khỏe thường niên tại bệnh viện hàng đầu Việt Nam;\nDu lịch thường niên, hoạt động team building năm.\nTập trung hỗ trợ sự phát triển cá nhân:\nĐược tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng các cấp quản lý tài năng, giàu kinh nghiệm;\nCơ hội tham gia các dự án lớn, đối tác quốc tế, đi đầu trong lĩnh vực tài chính tiêu dùng;\nChính sách hỗ trợ các hoạt động học tập, nâng cao trình độ ngoại ngữ, trao đổi, chia sẻ kiến thức, giao lưu văn hoá (Training, Seminar...)\nYour skills and experience:\nBằng cử nhân về Khoa học máy tính, Kỹ thuật phần mềm hoặc lĩnh vực liên quan trở lên.\nĐã có kinh nghiệm tương đương trong vai trò kỹ sư cao cấp phát triển phần mềm với ngôn ngữ Java, ưu tiên nếu có thêm kinh nghiệm phát triển phần mềm với ngôn ngữ PHP.\nƯu tiên am hiểu lĩnh vực tài chính ngân hàng, hệ thống LOS.\nThông thạo các nguyên tắc phát triển phần mềm, lập trình hướng đối tượng và các cách thực hành tốt nhất của Java.\nKỹ năng thiết kế cơ sở dữ liệu và SQL (ví dụ: MySQL, PostgreSQL, Oracle).\nKỹ năng phát triển ứng dụng web (HTML, CSS, JavaScript).\nThành thạo quy trình kiểm thử, gỡ lỗi và khắc phục sự cố phần mềm.\nKỹ năng về các công nghệ container hóa và điều phối quy trình (ví dụ: Docker, Kubernetes).\nThành thạo hệ thống kiểm soát phiên bản (ví dụ: Git).\nThành thạo về BPMN, DMN, lược đồ cơ sở dữ liệu, giao thức truyền thông hệ thống như HTTP, Restful API, Dịch vụ web.\nCó kinh nghiệm với các nền tảng và dịch vụ đám mây (ví dụ: AWS, Azure) là một lợi thế.\nKhả năng làm việc theo nhóm / tổ chức.\nKhả năng làm việc hiệu quả trong sự thay đổi.\nKhả năng lập kế hoạch và tổ chức.\nKỹ năng giải quyết vấn đề.\nWhy you\'ll love working here:\nMôi trường làm việc chuyên nghiệp, cởi mở, chú trọng 5 giá trị cốt lõi: “Thông minh – Chính trực – Dũng cảm – Thân thiện – Hợp tác”.\nThời gian làm việc từ thứ 2 – thứ 6 (40h/ tuần);\nChế độ làm việc Hybrid dành riêng cho CBNV khối Công nghệ;\nĐồng nghiệp thân thiện, cởi mở với tư duy đề cao sự phát triển của mỗi cá nhân;\nVăn phòng làm việc với không gian mở, rộng rãi, được cung cấp đầy đủ các trang thiết bị để phục vụ cho công việc.\nQuan tâm đặc biệt đến nhân viên:\nGói đãi ngộ cạnh tranh;\nHỗ trợ ăn trưa 1.200.000 VND/tháng; Hỗ trợ gửi xe 200.000 VNĐ/ tháng;\nQuyền lợi chăm sóc sức khỏe đặc quyền bảo hiểm sức khỏe toàn diện SHBFC Care;\nNghỉ phép ngày sinh nhật;\nKhám sức khỏe thường niên tại bệnh viện hàng đầu Việt Nam cùng các chế độ BHXH theo quy định của nhà nước;\nDu lịch thường niên, hoạt động team building năm;\nTập trung hỗ trợ sự phát triển cá nhân:\nĐược tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng các cấp quản lý tài năng, giàu kinh nghiệm;\nCơ hội tham gia các dự án lớn, đi đầu trong lĩnh vực tài chính tiêu dùng;\nChính sách hỗ trợ các hoạt động học tập, trao đổi, chia sẻ kiến thức, giao lưu văn hoá (Training, Seminar...)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Gelex Tower, 52 Lê Đại Hành, phường Lê Đại Hành, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(617, 238, 2, '(Fresher) BackEnd Engineer (Java, Spring)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\nJob description\n- Tham gia lập trình, phát triển các hệ thống, ứng dụng của Ngân hàng.\n- Tham gia phát triển dịch vụ tích hợp với các hệ thống core như: T24, WAY4, BPM, CRM, CIC ...\n- Tham gia phát triển API trên API Gateway phục vụ tích hợp với các đối tác trong nước và quốc tế.\n- Nghiên cứu, thử nghiệm, triển khai áp dụng các xu hướng công nghệ mới vào việc phát triển: GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL ...\n- Tham gia các chương trình training, đào tạo để hoàn thiện chuyên môn, nhằm phát triển lên các vị trí chính thức sau chương trình đào tạo\nYour skills and experience\n- Những bạn chuẩn bị tốt nghiệp hoặc đã tốt nghiệp dưới 1 năm tại các trường Đại học.\n- Chuyên ngành tốt nghiệp: Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin ...\n- Có kiến thức, hiểu biết về 1 trong các ngôn ngữ lập trình BackEnd, ưu tiên Java\n- Có kỹ năng làm việc với Spring framework: spring core, spring sercuity, spring boots.\n- Hiểu biết về 1 trong các loại database: Oracle, Sqlserver, PostgreSQL, Mongodb.\n- Ưu tiên các bạn tốt nghiệp loại Giỏi, Xuất sắc, có thành tích cao, đạt giải thưởng, có nghiên cứu khoa học trong quá trình học Phổ thông, Đại học (ứng viên nên thể hiện nội dung này trong CV)\n- Ứng viên có thể làm việc fulltime là một lợi thế. Yêu cầu onsite tối thiểu 7/10 buổi làm việc trong tuần (từ thứ 2 - thứ 6).\nWhy you\'ll love working here\n**Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:**\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương  \n**Cơ hội nghề nghiệp và phát triển bản thân:**\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng  \n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng  \n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.  \n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)  \n**Môi trường làm việc lý tưởng với:**\n- Những người cộng sự thân thiện và tài năng  \n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(618, 419, 2, 'Software Developer (.NET, ASP.NET, C#)', 'Job description\n- Phát triển hệ thống MES dựa trên nền tảng có sẵn\n- Phân tích và xử lý các lỗi nhận được từ các phòng ban liên quan \n- Nghiên cứu và đào tạo người dùng về chức năng mới \n- Nghiên cứu và cải tiến hệ thống phù hợp với sản xuất và phòng ban liên quan \n- Giám sát và bảo trì hệ thống \n- Phân tích dữ liệu và báo cáo\n\nYour skills and experience\n- Có kinh nghiệm lập trình .NET winform, C#, ASP.NET \n- Có kiến thức về HTML, CSS, JS..\n- Có kinh nghiệm làm việc với database \n- SQL(Truy vấn, tối ưu truy vấn, Procedure..)\n- Có kinh nghiệm làm việc trong công ty sản xuất \n- Có kinh nghiệm với MS Office \n- Kỹ năng giao tiếp, khả năng làm việc độc lập và làm việc nhóm \n- Chịu được áp lực cao \n- Ngôn ngữ: Tiếng Anh giao tiếp cơ bản(Tiếng Trung/Tiếng Hàn là lợi thế) \n- Có ít nhất 2 năm kinh nghiệm \n- Có hiểu biết về các thiết bị IT, cài đặt phần mềm, hệ thống mạng là một lợi thế\n\nWhy you\'ll love working here\n- Bonus: Mức lương, thưởng cạnh tranh, phụ cấp chức vụ, phụ cấp xăng xe, phụ cấp con nhỏ,...\n- Healthcare Plan: Các chế độ BHXH, lương tăng ca theo quy định của nhà nước\n- Training: Cơ hội đào tạo nội bộ & ở nước ngoài và cơ hội phát triển sự nghiệp.\n- Team Activities: Được tham gia nhiều hoạt động ngoại khóa: Garden party, Workshop, Football, Badminton, Yoga,...\n- Canteen: Miễn phí đồng phục, đồ uống, ăn trưa, ăn tối (tùy theo thời gian làm việc),...\n- Others: Môi trường làm việc trẻ trung, năng động', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lô P-4, khu công nghiệp Tràng Duệ, xã An Hòa , Huyện An Dương , Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(619, 460, 2, 'Frontend/Full Stack Developer (VueJS, NodeJS, Angular)', 'We’re looking for a Frontend or Fullstack Developer who is passionate about building scalable web and hybrid mobile apps. You will take part in the entire development process: from building UI/UX prototypes to delivering high-performance features on both web and mobile platforms\n\n- Build and maintain modern web applications.\n- Maintain and optimize the system of existing products.\n- Develop hybrid web/mobile apps.\n- Cooperate with business, planning and other related personnel to complete relevant tasks and objectives.\n- Participate in code reviews, technical discussions, and continuous improvement.\n\nYour skills and experience:\n\n- 3+ years of frontend development experience or fullstack development experience.\n- Strong experience in VueJS (Vue 2 or Vue 3).\n- Hands-on experience with Cordova or Capacitor, and knowledge of Angular 2+.\n- Proficient in JavaScript, HTML5, CSS3, and modern ES6+ features.\n- Experience working with REST APIs.\n- Good understanding of responsive and adaptive UI.\n- Familiar with Figma, Sketch, or similar tools.\n- Experienced in working with various UI frameworks such as Bootstrap, Element, Ant Design, and Tailwind.\n\nNice to Have:\n\n- Experience with NodeJS (backend).\n- Experience with Docker, CI/CD pipelines (e.g., GitLab CI).\n- Exposure to AWS, Azure, or other cloud platforms.\n- Experience working on product-based development (e.g., long-term platform building, owning features from planning to release).\n\nWhy you\'ll love working here:\n\n1. Competitive and attractive salary based on candidate\'s ability.\n2. Year-end bonus: Salary of 13th month.\n3. Working days: Monday - Friday, 8 hours per day.\n4. Review salary annually.\n5. Social insurance, health insurance, unemployment insurance according to the provisions of law.\n6. Team-building every 3 months, Summer holiday.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tran Thai Tong, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(620, 253, 2, 'MMORPG Server Developer (Games/C++)', 'Top 3 reasons to join us\n\n1. 13th Month salary, work 5 days a week\n2. Annual Company Trip, Quarterly team building\n3. Premium health insurance, Annual Health check-up\n\nJob description\n\n- Development of MMORPG game servers\n- Development of game service operation environments and tools\n\nYour skills and experience\n\nGeneral Competencies\n- Passion and dedication to game development\n- Positive attitude and proactive communication skills\n- Strong sense of responsibility for assigned tasks\n- Logical thinking and creative problem-solving abilities\n\nJob-Specific Skills\n- Understanding and implementation of object-oriented programming\n- Understanding and implementation of multithreaded programming\n- Understanding and implementation of network programming\n- Database schema design and procedure implementation skills\n- Understanding and implementation of various data structures and algorithms\n\nPreferred Qualifications\n- Experience in online game server development\n- Experience using commercial server engines\n- Experience in development within Linux environments\n\nOur recruitment process:\n1. Application screening\n2. An offline test \n3. F2F Interview (Only 1 round)\n4. Job offer\n\nWhy you\'ll love working here\n- Chance to work on global projects with multicultural teams, world-class games.\n- Attractive salary and benefits.\n- Professional work environment.\n- Open culture where every employee is valued, treated fairly. and trusted.\n- 13th salary every year at least 1-month salary.\n- From 12 days Annual Leave\n- Government social, health, and unemployment insurance.\n- Lunch Allowance\n- Annual salary review based on employee performance and company success\n- Annual Company Trip, Year End Party\n- Events during Birthday, Full Moon Festival, other important holidays', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UOA Tower, 11th Floor, 06 Tan Trao Street, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(621, 313, 2, 'Product Manager (Agile, Scrum)', '1. Product Strategy & Vision\n- Define and communicate a clear product vision and roadmap, aligned with business objectives and market needs.\n- Conduct market research, competitor analysis, and user interviews to identify opportunities and inform product decisions.\n- Balance user needs, technical feasibility, and business goals to deliver value-driven solutions.\n\n2. Project Management\n- Oversee the entire product lifecycle, including requirement analysis, planning, execution, deployment, and post-launch evaluation.\n- Ensure on-time delivery of high-quality products by managing timelines, resources, and scope effectively.\n- Collaborate closely with cross-functional teams to refine processes and resolve roadblocks.\n\n3. Collaboration & Stakeholder Management\n- Work with UX/UI designers to create intuitive, user-centric designs and maintain alignment with brand identity.\n- Partner with engineering teams to ensure technical feasibility and efficient implementation.\n- Act as the primary point of contact for stakeholders, managing expectations and keeping them informed.\n\n4. Continuous Improvement\n- Monitor product performance, gather feedback, and use insights to drive iterations and enhancements.\n- Establish and maintain a design system to ensure scalability and consistency across products.\n- Stay updated on emerging trends, technologies, and industry practices to maintain a competitive edge.\n\nYour skills and experience\n- 5+ years of experience in product management, software development, or related fields.\n- Proven ability to lead cross-functional teams and successfully manage complex projects.\n- Strong knowledge of Agile/Scrum methodologies and software development life cycles.\n- Excellent communication skills with a demonstrated track record of stakeholder engagement and alignment.\n\nNice-to-Have\n- Experience in SaaS, E-commerce, or Q-commerce product development.\n- Or experience in fintech, SaaS, or investment platform development.\n- Familiarity with CI/CD practices and DevOps principles.\n- Certification in PMI, Agile, or Scrum.\n- Exposure to UX/UI design principles and tools like Figma or Adobe Creative Suite.\n\nWhy you\'ll love working here\n- Competitive salary commensurate with experience.\n- Flexible working hours to support work-life balance and productivity.\n- Opportunity to work in a dynamic startup environment with a passionate and talented team.\n- Chance to make a significant impact on the growth and success of innovative products.\n- Exposure to cutting-edge technologies and innovative projects.\n- Collaborative culture that values creativity, diversity, and continuous learning.\n- Career growth and skill development opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24 Huỳnh Khương Ninh, Phường Đa Kao, Quận 1, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(622, 461, 2, 'UI-UX Designer', 'Công ty ETU Mobile hoạt động trong lĩnh vực sản xuất và phát hành ứng dụng mobile app (Android/iOS).\nLà một công ty trẻ, với sự sáng tạo, kiên trì, nhiệt huyết, chúng tôi đã cùng nhau đưa những sản phẩm chất lượng tới tay hàng triệu người dùng toàn cầu.\nMô tả công việc:\n- Thiết kế trải nghiệm người dùng (UX) tối ưu và giao diện người dùng (UI) hấp dẫn cho ứng dụng di động.\n- Nghiên cứu yêu cầu người dùng và mục tiêu kinh doanh để đưa ra giải pháp thiết kế sáng tạo và hiệu quả.\n- Phát triển wireframe, prototype và tài liệu UX khác.\n- Thiết kế giao diện UI chi tiết, đảm bảo tính thẩm mỹ, nhất quán và khả năng tương tác cao.\n- Xây dựng và duy trì hệ thống thiết kế (design system).\n- Phối hợp chặt chẽ với các bộ phận Phát triển, Kiểm thử, Marketing và liên quan.\n- Nghiên cứu và cập nhật xu hướng thiết kế UI/UX.\n- Thực hiện các công việc thiết kế, sáng tạo khác theo yêu cầu.\nYour skills and experience:\n- Kiến thức vững chắc về nguyên tắc thiết kế UX/UI cho ứng dụng di động (iOS & Android).\n- Thành thạo các công cụ thiết kế UI/UX phổ biến (Figma, Adobe XD...).\n- Kinh nghiệm xây dựng wireframe, prototype và design system.\n- Hiểu biết về typography, color theory, layout và visual hierarchy.\n- Kinh nghiệm làm việc với Human Interface Guidelines (Apple) và Material Design (Google).\n- Ít nhất 1 năm kinh nghiệm thiết kế UI cho ứng dụng di động.\n- Tư duy thiết kế lấy người dùng làm trung tâm.\n- Khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Kỹ năng giao tiếp và trình bày ý tưởng tốt.\n- Tinh thần trách nhiệm cao, chủ động và ham học hỏi.\n- Ưu tiên ứng viên có kĩ năng đa dạng như Photoshop, Adobe Premiere, Canva, Capcut.\n- Biết tiếng anh và sử dụng AI trong công việc là một lợi thế.\n- Ứng viên đính kèm portfolio design trong CV.\nWhy you\'ll love working here:\n- Thu nhập thỏa thuận (up to 16.000.000).\n- Phụ cấp ăn trưa, phụ cấp chuyên cần lên đến 1.000.000Đ.\n- Gửi xe free.\n- Hưởng các quyền lợi sinh nhật, nghỉ phép hàng năm.\n- Thưởng dự án, thưởng lễ tết đầy đủ.\n- Tham gia các hoạt động Teambuilding.\n- Môi trường Startup làm việc năng động, vui vẻ, team đoàn kết.\n- Không gian làm việc rộng rãi, đầy đủ tiện nghi.\n- Nhiều hoạt động gắn kết: Du lịch, Team building hàng năm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 12, Tháp C, Tòa nhà Hồ Gươm, số 102 đường Trần Phú, Phường Mộ Lao, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(623, 277, 2, 'Project Manager', 'Main responsibilities\nProject Planning/Management\n- Work together with stakeholder of the project and corresponding personnel, and/or vendor to define the scope of the project.\n- Work with stakeholders and vendor to define the reasonable project plan with proper resource assignment. Manage the progress of the project to achieve the target schedule, quality, and budget.\n- Define/review/revise the test plan of the system. Verify the correctness of test result. Test plans included unit test, integration test, stress test, user acceptance test.\n- Understand the requirement on system integration.\n- Communicate properly with third party systems for integration.\n- Define the integration plan as well as the cost/resource required for integration.\n- Monitor the readiness of third party system for integration.\nResource Management\n- Assign resource to project. For human resource, assign resource by loading, skillset, and availability and monitor resource utilization and achievement. For monetary resource, ensure it is within the agreed budget, For machinery resource, ensure their availability.\nQuality & Risk Management\n- Ensure the delivery of the project is up to the quality standard from stakeholder/users.\n- Ensure the delivery of the project having the international quality standard.\n- Determine the project risks. Find the resolution for the potential risks.\n- Communicate effectively with project committee, stakeholders/key users for any potential risks of the project.\n- Execute the resolution if required.\nUsers & Vendor Management\n- Discuss/communicate with key users/stakeholders to ensure the user-requirements fully implemented in the project.\n- Prepare regular clear and correct executive summary for stakeholders and key users to understand the status of project.\n- Ensure the stakeholders/key users fully aware of the progress of the project.\n- Fully responsible for vendor engagement from vendor selection, bidding process to vendor negotiation.\n- Ensure vendor fully aware the requirements of the project with deliverables satisfying the needs of users.\n- Close monitor the implementation of vendor following the project schedule.\n- Negotiate the best cost with vendor for the implementation.\n- Ensure vendor following the SDLC with proper testing of your delivery.\nChange Control\n- Regular communicate with users to determine any change on user requirement.\n- Proper reflect the changes to vendor. Determine whether the changes impact to the project delivery as well as project cost.\n- Communicate proper to the project committee for any changes on project schedule and cost due to the change on requirement. Obtain consent from project committee for applying the changes.\n\nYour skills and experience\n- University or college degree in IT, Computer Mathematics or related subjects.\n- Minimum 7 years Business Analysis experience included 2 years in project management experience.\n- Fully understanding of SDLC, and ITIL. PMP certification.\n- Experience identifying, analyzing and managing project risks on large, complex projects.\n- Experience directly managing IT projects with budgets exceeding 1 million USD.\n- Experience on forecasting, resource capacity and planning and schedule and budget performance reporting.\n- Experience leading/ managing PMO services and functions supporting IT Projects.\n- Experience defining project management standards and auditing projects for compliance.\n- Extensive business analysis experience on deriving the project requirements.\n- Experience using and mentoring on the use of MS Project and MS Project.\n- Good presentation, written and verbal communication skill.\n- Knowledge on unix, database included DB2, Oracle, and/or Informix.\n- Good presentation, written and verbal communication skill.\n- Communication skills, communication confidence, team work, good customer relations;\n- Ability to work independently, under pressure and large,\n- Reading technical documents in English good, basic communication\n\nWhy you\'ll love working here\n- Thu nhập hấp dẫn, lương thưởng theo performance\n- Thưởng các ngày Lễ /Tết (theo chính sách công ty từng thời kì)\n- Chế độ ngày phép hấp dẫn theo từng cấp bậc\n- Bảo hiểm bắt buộc theo quy định, BH sức khỏe cao cấp cho CBNV\n- Được tham gia các khóa đào tạo tùy thuộc vào khung đào tạo cho từng vị trí.\n- Thời gian làm việc: từ thứ 2 – thứ 6 \n- Môi trường làm việc năng động, thân thiện, có nhiều cơ hội học đào tạo, học hỏi và phát triển; được tham gia nhiều hoạt động văn hóa thú vị (cuộc thi về thể thao, tài năng, hoạt động team building,…)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 25, Toà nhà Văn phòng Thương mại, số 89 Láng Hạ, Phường Láng Hạ, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(624, 462, 2, 'UX/UI Design Leader', 'Mô tả công việc\n\nThiết kế và tối ưu giao diện:\nChịu trách nhiệm thiết lập hình ảnh tổng thể cho sản phẩm và các phương án UI, bao gồm biểu tượng, thành phần, bố cục, phối màu.\nLiên tục tối ưu thiết kế giao diện dựa trên phản hồi người dùng và dữ liệu phân tích, nâng cao tính thân thiện và nhất quán trong trải nghiệm người dùng.\n\nDuy trì quy chuẩn thiết kế và thư viện thành phần:\nXây dựng và duy trì hệ thống quy chuẩn thiết kế (Design System), bao gồm thư viện thành phần, biểu tượng và hướng dẫn phong cách UI.\nĐảm bảo tính thống nhất trong thiết kế, nâng cao hiệu quả hợp tác giữa các thành viên trong nhóm.\n\nPhối hợp liên phòng ban:\nPhối hợp chặt chẽ với Quản lý Sản phẩm và Nhà thiết kế Tương tác, hiểu rõ nhu cầu sản phẩm và điểm đau của người dùng, chuyển hóa chúng thành giao diện trực quan, dễ sử dụng.\nHợp tác với đội ngũ phát triển để đảm bảo thiết kế được hiện thực hóa với chất lượng cao trong quá trình triển khai.\n\nNắm bắt xu hướng và đổi mới:\nTheo dõi các xu hướng và công cụ mới trong lĩnh vực UI, không ngừng nâng cao khả năng sáng tạo và biểu đạt hình ảnh.\nTích cực tham gia thảo luận, đánh giá thiết kế trong nhóm, đưa ra những gợi ý và ý kiến giá trị cho sản phẩm.\n\nYour skills and experience\n\n1. Học vấn và kinh nghiệm:\n• Tốt nghiệp Đại học chuyên ngành Mỹ thuật, Thiết kế thị giác, Thiết kế tương tác, Truyền thông số hoặc lĩnh vực liên quan.\n• Tối thiểu 3 năm kinh nghiệm trong thiết kế UX/UI, có sản phẩm thiết kế UX/UI hoàn chỉnh hoặc portfolio ấn tượng. (Vui lòng đính kèm link sản phẩm hoặc portfollio vào trong CV)\n\n2. Kỹ năng thiết kế:\n• Thành thạo các công cụ thiết kế chủ đạo (Figma, Sketch, Adobe XD, Photoshop, Illustrator…).\n• Hiểu sâu về phối màu, bố cục, hình tượng, biểu tượng; có khả năng sáng tạo phù hợp với định vị thương hiệu và sản phẩm.\n\n3. Nhận thức về trải nghiệm người dùng:\n• Có tư duy cơ bản về trải nghiệm người dùng (UX), hiểu về luồng tương tác và cấu trúc thông tin.\n• Biết cân bằng giữa nhu cầu người dùng và mục tiêu kinh doanh, chú trọng cả tính tiện dụng và tính thẩm mỹ.\n\n4. Giao tiếp và hợp tác:\n• Kỹ năng giao tiếp tốt, trình bày rõ ràng ý tưởng thiết kế, làm việc hiệu quả với các nhóm chức năng khác nhau.\n• Có tinh thần đồng đội, sẵn sàng tiếp nhận phản hồi và liên tục cải thiện.\n\n5. Học hỏi và đổi mới:\n• Nhạy bén với xu hướng thiết kế và công nghệ mới, chủ động học hỏi, thử nghiệm công cụ và phương pháp mới.\n• Tư duy nắm bắt hệ thống business tốt\n\nWhy you\'ll love working here\n\n• Mức lương cạnh tranh, thưởng hiệu suất\n• Bảo hiểm xã hội full lương, chế độ chăm sóc sức khỏe, nghỉ phép có lương theo quy định\n• Hoạt động gắn kết đội nhóm, cơ hội đào tạo chuyên môn giúp phát triển sự nghiệp', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No 58, Huynh Man Dat Street, Ward 19, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(625, 239, 2, 'Flutter Developer (Dart / OOP / Windows / iOS /Android)', 'About Us: Bosch Sensortec\nBosch Sensortec is the technology leader in sensing solutions based on microelectromechanical systems (MEMS) and dedicated to the consumer electronics world. Our success in MEMS sensors and solutions is built on a remarkable team driven by passion, innovation and flexibility.\nFind out more about the applications we make possible for smartphones, tablets, wearables, AR/VR, smart homes and the IoT in our website\n\nKey responsibilities:\n- Develop and maintain apps using Flutter & Dart.\n- Integrate with native components (C, C#, C++).\n- Ensure app performance, scalability and stability.\n- Review code, debug issues, and write clear documentation.\n- Collaborate with cross-functional teams to bring intuitive UI/UX to life.\n\nYour skills and experience\nMust-have:\n- Bachelor / Master degree, major in Computer Science or Information Technology or related field\n- Strong experience with Flutter / Dart.\n- Experience building cross-platform apps (Android/iOS/Windows).\n- Solid understanding of OOP, SOLID, MVVM/MVC, BLoC.\n- Good knowledge of multithreading, file handling, streams.\n- Proficiency in English (written and spoken).\n\nNice-to-have:\n- Knowledge of BLE, sensor integration, or location services.\n- Experience with embedded systems or full-stack Flutter development.\n- Familiarity with CI/CD, Git, Jenkins, Jira, Confluence.\n\nWhy you\'ll love working here\nWhy BOSCH?\nBecause we do not just follow trends, we create them. Together we turn ideas into reality, working every day to make the world of tomorrow a better place. Do you have high standards when it comes to your job? So do we. At Bosch, you will discover more than just work.\n\nBenefits and Career Opportunities\n- Working in one of the Best Places to Work in Vietnam and Top 30 of the Most Innovative Companies all over the world\n- English-speaking environment, with opportunity to be part of innovation team and work in global projects\n- Onsite opportunities\n- Engage in our diverse training programs which surely help strengthen both your personal and professionalism\n- Flexible working time\n- 13th-month salary bonus + attractive performance bonus (you\'ll love it!) + annual performance appraisal\n- 100% offered salary and mandatory social insurances in 2-month probation\n- 15++ days of annual leave + 1-day of birthday leave\n- Premium health insurance for employee and 02 family members\n- Lunch and parking allowance\n- Good benefits of company activities such as: football, badminton, yoga, Aerobic, team building…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Capital Place, 29 Lieu Giai Street, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(626, 226, 2, 'Senior DevOps Engineering ( Python, AWS)', 'I. Công tác vận hành dịch cụ công nghệ:\n- Phân công, điều phối, xử lý trực tiếp các yêu cầu về dịch vụ công nghệ được giao, đảm bảo cơ chế phản hồi và cam kết chất lượng tiến độ xử lý yêu cầu hỗ trợ dịch vụ công nghệ tại bộ phận;\n- Kiểm soát và giám sát chặt chẽ mức độ tuân thủ quy định, quy trình, thời gian cam kết của công tác vận hành dịch vụ công nghệ theo chính sách, cơ chế của Tổ chức hiệu lực theo từng thời kỳ\n\nII. Vận hành dịch vụ CNTT:\n- Áp dụng và thực thi khung quản lý dịch vụ công nghệ ITIL, Agile trong công tác hỗ trợ và vận hành dịch vụ công nghệ tại tổ chức.\n- Thực thi và quản lý các yêu cầu hỗ trợ dịch vụ công nghệ, thay đổi trên các hệ thống công nghệ để đảm bảo tất cả các yêu cầu đều được hỗ trợ dứt điểm, đáp ứng yêu cầu của kinh doanh, quản trị dịch vụ và đúng theo SLA cam kết.\n- Xử lý và quản lý sự cố, vấn đề công nghệ phát sinh. Phối hợp với các bộ phận liên quan xử lý các lỗi phát sinh ảnh hưởng đến dịch vụ công nghệ, đảm bảo các lỗi phát sinh được xử lý theo đúng SLA và thống nhất giữa các bên.\n- Thực hiện tổng hợp báo cáo các mảng hoạt động được phân công gửi cán bộ quản lý, phòng ban liên quan.\n- Hiểu biết dịch vụ và soạn thảo hướng dẫn xử lý các tình huống thường gặp.\n- Tham gia xây dựng quy trình ITSM cho các sản phẩm, dịch vụ công nghệ của tổ chức trong từng thời kỳ.\n- Thực hiện các công việc khác theo phân công của lãnh đạo.\n\nIII. Đề xuất cải tiến dịch vụ:\n- Đề xuất các cải tiến nâng cao chất lượng dịch vụ và phối hợp với các bộ phận liên quan thực hiện.\n\nPhối hợp với các bên để các lỗi phát sinh được xử lý triệt để\n\nYour skills and experience\n- Có bằng Đại học chính quy trở lên về chuyên ngành CNTT, Điện tử Viễn thông, Tài chính, Kinh tế\n- 3 năm kinh nghiệm trở lên trong lĩnh vực hỗ trợ dịch vụ công nghệ trong đó có 1 năm kinh nghiệm trở lên tại vị trí tương đương\n- Có kinh nghiệm về mảng Vận hành Dịch vụ Data là một lợi thế\n- Hiểu biết về lĩnh vực ngân hàng, thương mại điện tử, chăm sóc khách hàng trung thành (loyalty) là một lợi thế\n- Có kinh nghiệm trong việc vận hành và chăm sóc khách hàng, dịch vụ hỗ trợ công nghệ theo ITIL, Agile\n- Nắm vững hệ thống internet banking, thẻ, ví, Loyalty\n- Tham gia dự án sản phẩm tài chính ngan hàng liên quan\n- Có kinh nghiệm sử dụng công nghệ container (Kubenetes, docker)\n- Có kiến thức tốt và kinh nghiệm về các nền tảng và dịch vụ Cloud (AWS là lợi thế).\n- Có kiến thức về scripting languages (bash hoặc python)\n- Hiểu biết về centralized logging: Elasticsearch, Logstash, Kibana\n- Hiểu biết về quy trình Devops, CI/CD\n- Có kinh nghiệm tham gia xây dựng kiến trúc các dự án về hybrid cloud, microservices là lợi thế.\n- Có các chứng chỉ về Cloud, DevOps là lợi thế.\n- Tiếng Anh đọc hiểu tài liệu tiếng anh chuyên ngành tốt, giao tiếp tốt là một lợi thế.\n- Cẩn thận, trung thực, nhanh nhẹn\n- Kỹ năng giao tiếp, đàm phán\n- Lập kế hoạch, thực thi, quản lý công việc được giao\n- Có khả năng tổng hợp phân tích đánh giá vấn đề/yêu cầu.\n- Có khả năng đọc hiểu tài liệu bằng tiếng Anh\n\nWhy you\'ll love working here\n- Thu nhập hấp dẫn, lương thưởng cạnh tranh theo năng lực.\n- Thưởng các ngày lễ, Tết (theo chính sách công ty từng thời kỳ).\n- Chế độ ngày phép hấp dẫn theo cấp bậc công việc.\n- Bảo hiểm bắt buộc theo luật lao động và bảo hiểm chăm sóc sức khỏe cho CBNV tùy theo cấp bậc và thời gian công tác.\n- Được tham gia các khóa đào tạo tùy thuộc vào khung đào tạo cho từng vị trí.\n- Môi trường làm việc năng động, thân thiện, có nhiều cơ hội học hỏi và phát triển; được tham gia nhiều hoạt động văn hóa thú vị (cuộc thi về thể thao, tài năng, hoạt động teambuilding...).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '20th Floor, 89 Lang Ha, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(627, 463, 2, 'PHP Web Application Developer (net salary $900-$1,500)', 'We are looking for a proactive and skilled PHP Laravel Developer to join our growing team. You will play a key role in developing and maintaining web applications that power the operations of leading property developers and management companies. If you\'re someone who enjoys solving complex problems, writing clean and efficient code, and contributing to real-world solutions, we’d love to meet you.\n\nResponsibilities\n• Design, develop, and maintain web applications using PHP (Laravel framework) and Microsoft SQL Server (MSSQL).\n• Collaborate with front-end developers to integrate user-facing elements with server-side logic.\n• Optimize application performance, scalability, and security.\n• Participate in the full software development lifecycle: requirement gathering, system design, coding, testing, deployment, and maintenance.\n• Write clean, well-documented, and maintainable code.\n• Troubleshoot, debug, and resolve application issues.\n• Contribute to technical documentation and code reviews.\n\nWork closely with business analysts and project stakeholders to deliver impactful features.\n\nRequirements\n• 1–3 years of hands-on experience in web application development using PHP (Laravel preferred).\n• Solid understanding of SQL, with experience in MSSQL or MySQL.\n• Familiar with REST APIs, HTML, CSS, and JavaScript.\n• Experience using version control systems (Git).\n• Build, document, and maintain RESTful APIs for internal modules and third-party integrations.\n• Support and contribute to CI/CD pipeline setup and deployment processes.\n• Strong problem-solving skills and attention to detail.\n• Comfortable working independently and in a collaborative team environment.\n• Ability to understand business requirements and translate them into technical solutions.\n• Bonus: Experience in business process applications.\n\nWhy you\'ll love working here\n• A very attractive salary package;\n• 13th month salary, contingency performance bonus;\n• Hanoi Office: 7 Flr., A-B Tower, Imperia Garden Building, 143 Nguyen Tuan Str.\n• Working hour: 8.30am-5.30pm (Mon - Fri) and by assignment;\n• Review and increment twice a year;\n• Salary paid by exchange rate at VCB monthly;\n• Knowledge sharing and learning on all IT aspects oversea;\n• Annual leave: Maternity, Married...;\n• Social, Healthcare, Unemployment Insurance;\n• Private health care program for you and your family members;\n• Seminar, Trip, Training oversea allowance;\n• Company trip, Team building/Happy hour, Birthday party, Sport team, Entertainment, Games club, Yoga...;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '7th Flr., A-B Tower, Imperia Garden Building, 143 Nguyen Tuan Str., Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(628, 464, 2, 'Mobile Developer (kotlin, swift, flutter, react native)', 'Join the Revolution in Vietnamese Fintech!\n\nRole Overview:\n- Craft the beautiful and smooth mobile experience our users will love! You\'ll translate designs into reality, building features for our credit card app.\n- Develop user interface components and implement features for our mobile application (iOS/Android) using the chosen framework (React Native, Flutter, or native) under the guidance of the Lead Engineer.\n- Collaborate closely with UI/UX designers to ensure pixel-perfect implementation and intuitive interactions.\n- Integrate with backend APIs, manage application state, and ensure data is displayed correctly and efficiently.\n- Write unit and integration tests for frontend components to ensure code quality and stability.\n- Debug and resolve frontend issues, optimizing for performance and responsiveness across different devices. Utilize AI tools for generating boilerplate code, suggesting component structures, or assisting with debugging.\n\nYour skills and experience\n\nMust-Have Skills & Experience:\n- Proven experience (2+ years) in frontend development, specifically building mobile applications using React Native, Flutter, or native (Swift/Kotlin).\n- Strong understanding of the chosen framework\'s core concepts, component lifecycle, and state management.\n- Experience consuming RESTful APIs and handling asynchronous operations.\n- Proficiency with HTML, CSS (or equivalents in the mobile framework), and JavaScript/TypeScript.\n- Familiarity with version control (Git) and mobile debugging tools.\n- Attention to detail and a passion for creating great user experiences. Comfortable using AI coding assistants.\n\nGood-to-Have Skills & Experience:\n- Experience working with design systems.\n- Experience with mobile testing frameworks.\n- Understanding of mobile performance optimization techniques.\n- Familiarity with CI/CD processes for mobile apps.\n- Experience in fintech or building consumer-facing apps.\n\nWhy you\'ll love working here\nReady to build the future of digital finance in Vietnam? An innovative AI-driven early-stage fintech, founded by former McKinsey partners and backed by global investors, is looking for the best young subject matter experts in Vietnam to help them launch! If you thrive in fast-paced, \'zero-to-one\' environments and don’t feel afraid of challenging the status quo in digital banking, credit cards and BNPL, let\'s talk!\nOur benefits include competitive compensation, 5 days work week, flexible working, 20 days annual leave, immersive learning and a lot more.\nWe\'re growing our core team in Ho Chi Minh City and looking for passionate trailblazers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thảo Điền, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(629, 238, 2, 'Senior Manual Tester (Test Lead)', 'Top 3 reasons to join us:\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description:\n- Thực hiện tìm hiểu, phân tích và làm rõ yêu cầu. Xây dựng chiến lược kiểm thử cho yêu cầu sản phẩm, dịch vụ Ngân hàng Lõi\n- Xây dựng kế hoạch kiểm thử, thiết kế kịch bản kiểm thử, thực hiện kiểm thử\n- Xây dựng tài liệu cho các yêu cầu sau khi đã thực hiện\n- Quản lý nhóm kiểm thử, phân tích và theo dõi kết quả kiểm thử; báo cáo kết quả kiểm thử, đảm bảo chất lượng phần mềm trước khi đưa lên Production\n- Phối hợp và hỗ trợ bộ phận nghiệp vụ xây dựng kế hoạch, kịch bản kiểm thử người sử dụng (UAT); hỗ trợ kiểm thử UAT, kiểm thử sau golive\n- Phân tích /đánh giá nguyên nhân lỗi sau golive\n- Xây dựng và cải tiến quy trình kiểm thử, quy trình phát triển phần mềm\n\nYour skills and experience:\n- Tốt nghiệp Đại học trở lên các chuyên ngành: Công nghệ thông tin, Toán tin, Điện tử Viễn thông, Kế Toán, Tài chính Ngân hàng....\n- Có trên 4 năm kinh nghiệm trong công tác kiểm thử trong ngân hàng, tổ chức tài chính, công ty công nghệ, trong đó có ít nhất 01 năm làm việc với các dự án liên quan đến hệ thống ngân hàng lõi (ưu tiên T24)\n- Có kinh nghiệm làm việc theo mô hình Agile/Scrum\n- Ưu tiên:\n  - Có kinh nghiệm kiểm thử tự động\n  - Có kinh nghiệm quản lý nhóm\n  - Có chứng chỉ quốc tế về kiểm thử: ISTQB, CETPA, CSTE, Seed Infotech, Qspiders Software Testing\n\nWhy you\'ll love working here:\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\nCơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng \n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng \n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh. \n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n\nMôi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng \n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(630, 407, 2, 'Senior Javascript Developer (VueJS/NodeJS)', 'Top 3 reasons to join us\n- Cấp Macbook kèm server riêng\n- Thử việc nhận full lương, đóng BHXH full lương\n- Business TOP1 thị trường Nhật Bản\n\nJob description\n- Tham gia vào tất cả các khâu trong quá trình phát triển phần mềm, bao gồm:\n  ○ Tìm hiểu và phân chia yêu cầu\n  ○ Đề xuất giải pháp kỹ thuật\n  ○ Thiết kế bản vẽ, kiến trúc phần mềm và cấu trúc dữ liệu\n  ○ Phát triển phần mềm với công nghệ Vuejs/Nodejs theo tiêu chuẩn clean-code\n  ○ Kiểm thử phần mềm, phát hiện lỗi và sửa lỗi\n  ○ Nghiên cứu kỹ thuật, công nghệ mới để tối ưu hóa hệ thống và nâng cao trải nghiệm sản phẩm.\n- Lên kế hoạch và triển khai các tính năng hoặc các tác vụ bảo trì/nâng cấp hệ thống nội bộ.\n- Tích cực giảm nợ kỹ thuật (technical debt), đồng thời trao đổi với team khi có nhu cầu refactor lớn.\n- Hiểu rõ mục đích của các tính năng đang triển khai, và truyền đạt lại mục êu đó tới team khi cần.\n- Thiết kế và tổ chức code có cấu trúc rõ ràng, dễ bảo trì và mở rộng theo quy mô dự án.\n- Hỗ trợ đồng đội thông qua pair programming, review code, và mentoring.\n- Tham gia vào chương trình đào tạo kỹ thuật cho nhân viên trong công ty.\n- Tham gia vào các seminar nội bộ về công nghệ.\n- Tham gia vào quy trình phỏng vấn - tuyển dụng tại công ty.\n- Các công việc khác trao đổi cụ thể khi phỏng vấn.\n\nYour skills and experience\n- Tốt nghiệp ngành CNTT các trường cao đẳng, đại học\n- Có ít nhất 3 năm kinh nghiệm phát triển phần mềm với Node.js (ưu tiên có kinh nghiệm ở cả frontend và backend).\n- Thành thạo Git và hiểu quy trình CI/CD cơ bản.\n- Có thể setup deploy ứng dụng do mình triển khai theo ít nhất một cách đơn giản.\n- Hiểu sâu về kiến trúc phần mềm, design patterns, và clean code.\n- Linh hoạt thích ứng với thay đổi về mức độ ưu tiên hoặc kế hoạch dự án.\n- Có kỹ năng giao tiếp và truyền đạt tốt trong nhóm kỹ thuật và với các bên liên quan.\n- Tư duy phản biện tốt, chủ động trong công việc, tinh thần học hỏi và hỗ trợ team.\n- Tích cực, chủ động học hỏi nâng cao năng lực kỹ thuật.\n- Có tinh thần trách nhiệm cao, cởi mở, cầu thị.\n\nWhy you\'ll love working here\n- Thử việc nhận full lương, đóng BHXH full lương\n- Thưởng tháng lương thứ 13, thưởng performance hàng năm\n- Xét tăng lương 2 lần/năm\n- Các loại trợ cấp ăn trưa, tiếng Nhật lên đến 5 triệu đồng/tháng\n- Trợ cấp chức vụ (Leader) lên đến 6 triệu/tháng\n- Cấp Macbook kèm server riêng\n- Làm việc giờ hành chính, không có OT\n- Chế độ xin nghỉ - làm bù linh hoạt\n- Khám sức khỏe hàng năm tại bệnh viện uy tín\n- Du lịch hàng năm, team building hàng tháng\n- Free snack, coffee, tea\n- Các câu lạc bộ bóng đá, cầu lông\n- Môi trường thân thiện; cấu trúc phẳng, mọi ý kiến của nhân viên đều được lắng nghe và tiếp thu\n- Có lộ trình phát triển rõ ràng cho từng cá nhân\n- Hưởng đầy đủ các quyền lợi khác theo quy định chung của công ty và pháp luật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Handico Tower, Khu đô thị Mễ Trì Hạ, Phạm Hùng, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(631, 400, 2, 'Caspeco-Senior Backend .NET Dev (.NET Core, C#, Azure)', 'Caspeco is looking for a Senior Backend Engineer to work in our beautiful office in HANOI, VIETNAM. Caspeco builds systems for the restaurant and experience industry. Our products consist of Booking, Cash Register, Staffing, and Analysis. The company today consists of around 150 employees serving 2500 customers in an organization where decision paths are short, every employee makes a difference, and new ideas and initiatives are rewarded.\n\nToday, Caspeco offers four complete systems for the hospitality and experience industry. We call them and together they can drive your entire business forward. We’ve packed our systems with features that we know make a difference; they save time, reduce the risk of mistakes, improve communication and increase margins both in terms of payroll and raw materials.\n\nWhat will you do?\n- Develop and maintain high-performance backend systems supporting customer frontends.\n- Collaborate with frontend engineers, product managers, and data teams to create cohesive, impactful solutions.\n- Design and implement REST APIs and microservices using C# and .NET Core.\n- Design and improve the observability of our system and services.\n- Maintain high standards for code quality, system reliability, and security.\n- Present plans and solutions to both technical and non-technical stakeholders.\n- Contribute and support the team in improving our software practices and processes to help excel even further.\n\nNotes:\n- CV in English.\n\nYour skills and experience\nMinimum requirements:\n- 8+ years of experience in backend development with expertise in C# and .NET Core.\n- 5+ years of experience with Azure Cloud, Azure Container Apps, Azure Kubernetes Service, Azure App Services, Docker.\n- Technical background with expertise in modern engineering practices.\n- Solid understanding of system design principles and distributed architecture, enabling you to build scalable and reliable backend services.\n- Strong experience in CI/CD practices and Github Action, Azure Devops, Terraform, Event driven systems.\n- Experience in SQL Server, Mongo, Redis and Azure Storage account.\n- Experience in RESTful APIs best practices.\n- Excellent in verbal and written English.\n\nWhy you\'ll love working here\nYou will be:\n- Fast moving company with attractive tech stack.\n- Forward leaning company when coming to engineering principles and characterized by short decision paths and an open atmosphere, where we share experiences and collaborate closely with each other.\n- Your contribution with skills and expertise will be highly valued to help us reach our ambitions.\n\nWhat will you get?\n- You’ll get to work with experienced software engineers worldwide at market leading, innovative Scandinavian SaaS company looking to accelerate growth.\n- Scandinavian Work Culture: creativity, innovation and work-life balance.\n- Competitive salary and 100% official salary during the probation period.\n- Annual review and 13th month salary.\n- Premium healthcare and accident insurance.\n- Wellness package supports employees to stay healthy and wealthy.\n- Exciting company outing/events and team building activities.\n- On-site and training opportunities in Nordic.\n- Modern working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 19, tòa nhà Peakview Tower, 36 Hoàng Cầu, Đống Đa, Hà Nội, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(632, 322, 2, 'Mobile Developer (Lead/Senior)', 'We are looking for iOS (Objective-C and Swift) and Android (Java, Kotlin) developers to join our mobile team. For this role you will have the opportunity to work for large banking corporations, contributing into mobile native application development in the finance industry.\n\nYou will help mobile team to develop new native features or modernize existing native application to latest cutting-edge technologies.\n\nAs mobile developer you will work within mobile team and interact closely other team (Backend, Business Analyst…) on a wide variety of collaborative and innovative engagements.\n\nResponsibilities:\n· Working on native mobile apps for large banking corporations\n· Collaborating with other team members to build native apps (either iOS, either Android)\n· Design, build, and maintain efficient, reusable, reliable, testable and secure code\n· Cooperating with product owner and UI designer to produce modern and reliable native apps\n· Ensure the best possible performance, quality, and responsiveness of the applications\n· Identify bottlenecks and bugs, and find solutions to fix issues\n· Help team to maintain code quality, organization, and automatization\n\nYour skills and experience\n\nMust Have:\n- At least years of experience in native mobile development (either iOS, either Android)\n- Solid knowledge of Objective-C and Swift or Java and Kotlin as well as associated SDKs and frameworks\n- Knowledge of software design and best practices for mobile native development\n- Tools: Gradle, Maven, GIT, JIRA/Confluence\n- Experience working with RESTful API\n- Working with Agile/Scrum methodology\n- Good written and verbal communication skills in English\n\nNice to Have:\n- CI/CD tools\n- Test and Test automation tools and frameworks\n- Familiar with performance monitoring and optimization\n- Familiar with security and authentication mechanisms\n- Previous experience in banking domain\n\nWhy you\'ll love working here\n\nLife at Capgemini is dynamic and fun, a place where people love to work. A career with freedom, full of learning and development opportunities and the support to help you achieve your best.\n\nA career at Capgemini is rewarding and constantly transforming. Here are the top ten reasons why people love working at Capgemini.\n\n1. Your values are our values: \nWe’re guided by seven core values: honesty, boldness, trust, freedom, team spirit, modesty, and fun. If you share those values, then you’ll find your place with us.\n\n2. People come first\nThrough our People Charter, we encourage free exchange of ideas, respect for differences, and wellbeing in the workplace for everyone.\n\n3. Never stop learning\nAt the Capgemini Group University, you’ll learn via classroom-based and virtual courses, e-learning modules and rich-media online resources.\n\n4. Feel free to grow\nOver the course of your career, your goals may shift. Want to change your focus? Switch tracks? We’re here to help.\n\n5. Get inspired by your colleagues\nOur cultural diversity means you’ll always have something to learn from those around you.\n\n6. Forget the notion of the “typical day”\nChallenge and variety are constants here. From the work you do to the people you meet to the places you travel, we’ll keep you on your toes.\n\n7. Strike a balance that works for you\nYou’re human—and so are we! We strive to make sure our employees achieve a healthy, happy work-life balance.\n\n8.Count on us for career growth\nWe’re always growing and so should you. We prioritize the personal development of our team members with our Capgemini Group University.\n\n9.Your Love for Travel\nWe have 300 offices in 40 countries around the world. You’ll have opportunities to travel or work in different locations.\n\n10.Dig in your first day\nWhether you join us as a recent graduate or a seasoned professional, you’ll start to work directly on challenging projects from day one.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '106 Nguyen Van Troi, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(633, 336, 2, 'Pre-BrSE/ BrSE Fresher/Junior (VBA, Japanese N3+)', 'Top 3 reasons to join us\n- 13th Salary + Yearly Performance Bonus\n- Amazing training and development opportunities\n- Health Insurance Package\n\nJob description\n- Giao tiếp với khách hàng Nhật về tất cả các vấn đề liên quan đến dự án\n- Phân tích và phát triển dựa trên module khách hàng yêu cầu bằng VBA\n- Xác minh và xây dựng các tài liệu thiết kế\n- Quản lý tất cả tài liệu đi và đến của dự án\n- Phối hợp chặt chẽ với Trưởng Bộ phận để theo dõi và kiểm soát tiến độ của các dự án\n\nYour skills and experience\n- Tốt nghiệp ĐH Chuyên ngành CNTT hoặc các chuyên ngành liên quan\n- Kinh nghiệm làm việc ở vị trí Pre-BrSE/ BrSE và đã sử dụng VBA tối thiểu 6 tháng\n- Trình độ tiếng Nhật tương đương N3 trở lên, mạnh dạn và sẵn sàng giao tiếp, làm việc trực tiếp với khách hàng Nhật\n- Ưu tiên có kinh nghiệm thiết kế\n- Ưu tiên đã có kinh nghiệm quản lý teamsize 3-5 người\n\nWhy you\'ll love working here\nChế độ đãi ngộ\n- Lương thỏa thuận theo năng lực thực tế của ứng viên. Performance review: 1 lần/năm.\n- Trợ cấp đi lại, trợ cấp ăn trưa, trợ cấp tiếng Nhật, trợ cấp onsite khi tham gia dự án bên khách hàng...\n- Tối thiểu 13 tháng lương/ năm, thưởng nhân viên xuất sắc quý, năm, thưởng nhân viên đạt giải MVP năm 1 chuyến du lịch Nhật Bản\n- Nghỉ theo lịch công ty, nghỉ theo lịch khách hàng Nhật (ngoài các ngày nghỉ theo quy định, 1 năm có thêm 2 đợt nghỉ dài)\n- Nghỉ tham gia Ngày hội khai giảng cùng con\n- Chế độ chăm sóc phụ nữ: Nghỉ sinh lý phụ nữ: 8h/ tháng; Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày\n\nChế độ chăm sóc sức khỏe cho nhân viên\n- Bảo hiểm y tế, bảo hiểm xã hội, bảo hiểm thất nghiệp trên mức lương chính thức theo quy định của Luật lao động\n- Bảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên làm việc trên 1 năm\n- Khám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín (Bệnh viện Thu Cúc, bệnh viện Medlatec…)\n\nVăn phòng làm việc tiện ích: Miễn phí trà, có máy pha coffee tại khu vực ăn uống của công ty\n\nCác hoạt động sôi nổi\n- Hoạt động team building kết nối đội nhóm hàng quý\n- Các CLB thể thao: bóng đá, bóng bàn, bi lắc...\n- Hoạt động du lịch thường niên và các sự kiện lớn trong công ty\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '266 Doi Can, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(634, 262, 2, 'Country Cyber Security and Privacy Officer', 'Huawei is a leading global provider of information and communications technology (ICT) infrastructure and smart devices. We have 208,000+ employees and operate in over 170 countries and regions, serving more than three billion people around the world. We are committed to bringing digital to every person, home and organization for a fully connected, intelligent world.\n\nKEY RESPONSIBILITIES OF THIS ROLE\n\nA CSPO manages local ICT cyber security and privacy protection business in a unified manner. In addition to business compliance, a CSPO improves internal cyber security and privacy protection capabilities and builds trust in cyber security and privacy protection with external stakeholders to facilitate business success of the rep office/country.\n\n1. Insight and business planning: Gain insights into local laws and regulations, understand the security and privacy requirements of local governments, regulators, and customers as well as local industry best practices, and develop local business budgets and plans.\n2. Policy and process adaptation: Implement security and privacy policies locally, optimize local business directives and relevant processes, provide supervision and guidance, and organize the implementation.\n3. Compliance and risk control: Use risk control methodologies to identify local security and privacy risks, develop and implement compliance and risk control solutions, establish crisis management plans (CMPs), and properly handle crises.\n4. Communication and trust building: Proactively identify external stakeholders, work with business departments to establish mechanisms for routine communication with local regulators, customers, industry organizations, and standards organizations, and organize mechanism implementation.\n5. Organization and capability building: Build local security and privacy organizations, improve local security compliance awareness and professional capabilities, and assess and promote the improvement of capability tools provided by the HQ.\n\nYour skills and experience\n- Bachelor’s degree or above in Cyber Security/ Information Security/ Computer Science or Information Technology related field\n- Knowledge: Be familiar with different cyber security or privacy protection standards and certification frameworks in the industry, and be adept at analyzing policies, laws, and regulations. People with external certifications such as CISSP/IAPP are preferred.\n- Capabilities: \n1. Insight and planning: Gain in-depth insights into and understand local security and privacy laws/regulations as well as local organizations\' security and privacy requirements, and integrate them into business plans.\n2. External communication: Deliver speeches and presentations as a Huawei spokesperson, and effectively communicate with local security and privacy regulators, industry and standards organizations, and customer organizations.\n3. Connection and execution: Be result-oriented and capable of cross-department collaboration, coordination, and promotion.\n4. Learning: Always be ready to learn and be capable of identifying own professional and business capability gaps and quickly bridging them through self-learning, training & practice, etc.\n5. Business understanding: Have a deep understanding of business requirements, and properly manage security and privacy risks in business to safeguard business success.\n\nExperience: Successful cyber security and privacy protection experience in large enterprises or regulators of the local ICT industry as well as industry influence; or long-term business management experience at Huawei (solution sales, delivery and service, public relations, compliance management, etc.). Appropriate experience in external communication (including communication with the government, media, industry, and customers). Successful experience in department management and cross-cultural team management (preferred); influence and impetus in regions/rep offices.\n\nWhy you\'ll love working here\n- WORKING TIME AND BENEFITS:\n1. Monday to Friday (08:30-18:00).\n2. Participating in full insurance benefits (health insurance, social insurance, unemployment insurance), the company supports 24/24 accident insurance and health care insurance for employees.\n3. Professional working environment, multinational company, good career development opportunities. Cultural and sports activities, taking care of employees\' health and life are organized periodically...\n4. Salary: negotiable.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '33rd Floor, Keangnam Landmark, E6, Pham Hung Street, Me Tri Ward, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(635, 465, 2, 'Full-stack Java Developer (Senior/Middle)', 'Top 3 reasons to join us\n- Very attractive salary package & performance bonus\n- 20 days annual leaves\n- Full legal package and 100% salary on probation\n\nJob description\nPosition Summary:\nPerform development activities to build and maintain WEB-based software systems.\n\nResponsibilities:\n- Participate in developing web applications using Angular, CSS, and Java technologies.\n- Understand application requirements and workflow from mock-ups and converting to workable code.\n- Perform coding, testing, and reviewing in line with user & system requirements to deliver programs that meet client’s needs and meet the release milestone.\n- Perform 3rd-level support to rectify production issues and provide solutions.\n\nYour skills and experience\nSkills & Qualifications:\n- Good Diploma/Degree in Computer Science/Information Technologies.\n- Web development knowledge (HTML, CSS, Angular, JavaScript, jQuery, JSON, etc.).\n- Java EE development experience (Java Core, Java EE, SPRING).\n- Database/SQL knowledge (SQL, Stored Procedures, and MySQL).\n- Project experience in CSS animation, or Mobile animation work is an added advantage.\n- Familiar with Agile and Continuous Integration and Continuous Delivery (Deployment).\n- Knowledge of code versioning tools including Git, or SVN.\n- Able to quickly learn new technologies, frameworks, and development languages.\n- Strong interpersonal and communications skills, both oral and written.\n- Strong debugging and problem-solving skills.\n- Understands what to build optimized for speed and scalability.\n- Able to work in a dynamic and ever-changing industry.\n\nFor Senior Web Developer:\n- Has a STRONG background in Angular, JQuery, JavaScript, and J2EE/Spring to develop web-based Java applications.\n- Has 2-year experience in mentoring and guiding small teams.\n- Has matured thinking process, good analytic and problem-solving skills.\n\nWhy you\'ll love working here\nBenefits:\n- Attractive compensation, regular assessments, and salary reviews;\n- 13th-month salary and annual bonus;\n- 20 days annual leave;\n- 100% salary during the probation period;\n- 100% social insurance, premium healthcare insurance, and annual routine check-up;\n- Unlimited access to a selection of food and beverages;\n- Special celebrations on 8/3, Father\'s day, 20/10, Christmas, Tet holiday, etc.;\n- Company activities: annual teambuilding, New Year party, quarterly company party, weekly fruits day, monthly birthday, etc.;\n- Sports activities: badminton, football, bowling, cycling, etc.;\n- In-house acoustic music band;\n- Cinema days with blockbuster movies.\n\nProjects & Team:\n- International working environment with a young, friendly, dynamic team, and creative;\n- Flat organizational structure;\n- Company sponsors overseas in-class training and online training courses.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '20 Sông Thao, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(636, 466, 2, 'Front End Developer (React JS, TypeScript)', 'Phát triển giao diện người dùng cho các ứng dụng nội bộ sử dụng ReactJS vàTypeScript.\nPhối hợp với team backend để tích hợp API và đảm bảo luồng dữ liệu mượt mà, chính xác.\nTối ưu hiệu năng hiển thị và trải nghiệm người dùng.\nTham gia vào quá trình phân tích yêu cầu, thiết kế UI/UX, và đóng góp ý tưởng cải thiện sản phẩm.\nĐảm bảo chất lượng code thông qua review, viết test và tài liệu hóa.\n\nCÓ ít nhất 2 năm kinh nghiệm làm việc với ReactJS.\nThành thạo TypeScript, HTML, CSS (hoặc TailwindCSS là một lợi thế).\nHiểu rõ cách hoạt động của React hooks, component lifecycle, state management (ví dụ: Redux, Context API).\nCó kinh nghiệm làm việc với RESTful API.\nCó khả năng làm việc độc lập và chủ động trong công việc.\nSử dụng tốt Git và quen với quy trình làm việc nhóm.\n\nĐiểm cộng\nKinh nghiệm với các thư viện UI như Ant Design hoặc tương tự.\nBiết viết unit test với React Testing Library hoặc Jest.\nCó kiến thức cơ bản về tối ưu SEO, performance frontend.\nĐã từng làm việc với ứng dụng nội bộ doanh nghiệp là một lợi thế.\n\nLương cơ bản: 12 triệu đến 16 triệu.\nĐược hưởng các quyền lợi theo chính sách của công ty và quy định của nhà nước.\nReview lương 2 lần/năm (tùy vào năng lực), lương tháng 13, cùng nhiều chế độ thưởng khác nhau.\nTeam building 2 lần/năm.\nCó cơ hội tham gia các khóa đào tạo, phát triển, nâng cao năng lực làm việc.\nLàm việc trong môi trường chuyên nghiệp, năng động, nhiều cơ hội phát triển năng lực bản thân, đãi ngộ dựa trên năng lực và sự nhiệt tình sáng tạo của từng thành viên.\nNghỉ 12 ngày phép năm và các ngày lễ tết, dịp đặc biệt của công ty.\nHỗ trợ ăn trưa, gửi xe.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '265 Hong Lac, P. 10, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(637, 467, 2, 'Engineering Manager', 'M Village is a forward-thinking hospitality company building high-impact products using modern, cloud-native architectures. Our mission is to deliver scalable and resilient solutions that create real value for our users. We are seeking a technically strong Engineering Manager to lead key engineering initiatives and make foundational decisions that drive our product and platform success.\n\nRESPONSIBILITIES:\n\nRole Overview:\nAs Engineering Manager, you will be both a leader and a technologist. You’ll lead cross-functional teams working on backend services (Golang, Python), web applications (ReactJS), mobile apps (Flutter), and infrastructure (AWS). You’ll be responsible for architectural design, technology stack decisions, engineering excellence, and people development.\n\nKey Responsibilities:\nLead and mentor a team of engineers working across backend, frontend, and mobile stacks.\nDrive architectural design and technical strategy for scalable cloud-native systems on AWS.\nMake decisions on technology stack, tooling, and frameworks based on performance, maintainability, and business needs.\nCollaborate with product, design, and business stakeholders to translate requirements into technical solutions.\nConduct technical reviews and ensure high-quality code, security, and performance standards.\nGuide the development of backend services (primarily in Golang and Python), web applications (ReactJS), and mobile apps (Flutter).\nFoster a strong engineering culture of ownership, innovation, and continuous improvement.\nScale the team by hiring top talent and promoting a culture of learning and collaboration.\n\nYour skills and experience:\nBachelor\'s or Master\'s degree in Computer Science/Engineering or a related technical field.\n8+ years of experience in software development (including 2+ years managing or technically leading engineering teams.)\nStrong hands-on experience with:\n\nBackend: Golang (primary)\nPython (secondary)\nFrontend: ReactJS \nMobile: Flutter\nCloud: Deep expertise in AWS services (EKS, S3, RDS, etc.)\nProven experience designing and deploying scalable, secure, and resilient distributed systems on AWS.\nSolid understanding of software engineering best practices (testing, CI/CD, observability, etc.).\nExcellent problem-solving and communication skills.\nGood communication and collaboration skills, with the ability to mentor and lead team members effectively.\nNice to Have: Experience building or leading platform teams or internal developer tools. Familiarity with container orchestration (EKS) and infrastructure as code (Terraform).\n\nWhy you\'ll love working here:\n13th-month salary\nFull salary on probation\nAnnual Leave: 12 days \nPremium Health insurance \nEmployee discount for M Village\'s booking service\nProvide budget for Laptop purchasing \nSocial insurance: in accordance with the Social Insurance Law\nOther allowance (Team bonding, birthday, marriage,...)\nAnnual Performance Review', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'SCIC Building - 16 Trương Định, Phường Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(638, 258, 2, 'VHT - Embedded Software Engineer (Linux, C++)', 'Top 3 reasons to join us\n- Dẫn đầu thị trường\n- Cơ hội thử thách và phát triển bản thân\n- Môi trường làm việc năng động\n\nJob description\nVới hơn 1200 nhân sự chất lượng cao , Tổng Công ty Công Nghiệp Công Nghệ Cao Viettel (VHT) trực thuộc Tập đoàn Công nghiệp - Viễn thông Quân, đã và đang trở thành nơi hội tụ của nhiều Tiến sỹ, Thạc sỹ được đào tạo tại các Quốc gia phát triển như Mỹ, Pháp, Anh, Hàn Quốc, Nhật Bản,...\nHướng tới sứ mệnh tạo ra các sản phẩm khí tài quân sự và dân sự Made-in-Vietnam, Made-by-Vietnamese, tiến tới mục tiêu nắm giữ công nghệ lõi, VHT tập trung nghiên cứu phát triển các hệ thống chỉ huy và điều khiển, radar, thiết bị thông tin, hệ thống chỉ thị mục tiêu hải đảo, các hệ thống tác chiến điện tử, mô hình mô phỏng tập trận, các hệ thống cảnh giới quang điện tử...đi kèm với các sản phẩm thiết bị mạng viễn thông như hệ thống truy cập di động, cố định, các thiết bị truyền dẫn, hệ thống mạng lõi và các thiết bị Chip, thiết bị Y tế, camera… nhằm tăng cường khả năng an ninh quốc gia, quốc phòng, bảo vệ biên giới và lãnh thổ Việt Nam và từ đó hiện thực hóa tham vọng để trở thành “Tổ hợp Công nghiệp Quốc phòng” tầm cỡ trong khu vực và trên thế giới.\nMô tả công việc:\n- Tham gia phân tích yêu cầu và thiết kế chức năng, thiết kế module cho hệ thống nhúng.\n- Nghiên cứu phát triển driver, ứng dụng cho các tính năng của sản phẩm.\n- Lập trình, kiểm thử chức năng theo yêu cầu thiết kế quản lý chất lượng đảm bảo chất lượng hệ thống.\n- Xây dựng bài đo, phương pháp đánh giá; phương pháp debug lỗi trong quá trình lập trình, kiểm thử sản phẩm.\n\nYour skills and experience\n- Tốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: Công nghệ thông tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\n- Trình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\n- Có tối thiểu 02 năm kinh nghiệm liên quan đến vị trí ứng tuyển.\n- Có kiến thức nền tảng về kỹ thuật vi xử lý và kỹ thuật điện tử (điện tử tương tự, điện tử số, mạch logic...), kiến trúc máy tính, hệ điều hành, kỹ thuật lập trình.\n- Sử dụng tốt ít nhất 01 công cụ lập trình nhúng cho vi điều khiển, vi xử lý cao cấp (ARM, DSP, ASIC).\n- Sử dụng tốt ngôn ngữ lập trình C/C++.\n- Có kinh nghiệm làm việc trên hệ điều hành Linux.\n- Có kinh nghiệm lập trình ngoại vi, giao tiếp bộ nhớ, giao tiếp số (UART/SPI/I2C/CAN...).\n\nWhy you"ll love working here\nĐãi ngộ\n# Dẫn đầu thị trường\n- Cơ hội được làm việc tại Tập đoàn tiên phong mở đường , kiến tạo tương lai thông minh, gắn kết của Việt Nam.\n- Cơ hội được thử sức trong những lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n\n# Môi trường năng động sáng tạo\n- Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo theo cách riêng.\n- Được khơi gợi cảm hứng làm việc với văn phòng xanh, không gian mở, hiện đại tiêu chuẩn quốc tế.\n\n# Cơ hội thử thách và phát triển\n- Áp dụng kiến thức, kĩ năng, kinh nghiệm chuyên môn giải quyết các bài toán hấp dẫn, thử thách tại Viettel.\n- Cơ hội thử sức ở nhiều lĩnh vực, sản phẩm và quốc gia khác nhau góp phần thay đổi xã hội.\n- Viettel cam kết cho bạn nền tảng vững chắc để học hỏi và phát triển.\n- Sẵn sàng trao quyền, cơ hội đột phá cho những người trẻ tuổi.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội được đào tạo, trao dồi kĩ năng định kì và nhu cầu thực tế.\n\n# Chế ngộ đãi ngộ hấp dẫn, cạnh tranh\n- Lương thưởng cạnh tranh trên thị trường, phản ánh đúng năng lực thực tế.\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày .\n- Thưởng thức bữa trưa thơm ngon tại Tập đoàn, được chọn lọc bởi các chuyên gia dinh dưỡng.\n- Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building thú vị.\n- Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.\n\nKhác\nViettel tuyệt đối không thu bất cứ khoản tiền nào của ứng viên khi nộp hồ sơ tham gia dự tuyển và khi vào làm việc tại Viettel nếu trúng tuyển.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(639, 256, 2, 'Backend Developer (NodeJS, NestJS)', 'About Us\nLitmers is a No-code & Code Outsourcing Agency leading innovation in the outsourced development space. We specialize in fast, cost-efficient software delivery without compromising on quality.\nSince our launch in January 2023 with just four team members, we’ve expanded to 50 people by May 2025, completed over 110 projects, and achieved 78% year-over-year revenue growth.\nRecognized as one of the top no-code Bubble development teams in Asia, we are currently ranked 13th out of 368 global Bubble agencies (as of April 2025). We also earned Gold Partner status within just 2.5 years, placing us in the top 5 globally by growth rate.\n\nPosition Overview\nWe are seeking a Node.js Developer to join our growing team. In this role, you will design and implement web applications using Node.js/Express and NestJS with TypeScript that power our data integration and visualization platform. You will also take part in designing and implementing technical solutions that address both business and product challenges while ensuring our applications be consistent, performant and scalable.\n\nResponsibilities\n- Design and develop robust web applications using Node.js, Express, and NestJS with TypeScript.\n- Implement technical solutions to address business and product challenges.\n- Optimize application performance and scalability to ensure efficient operations.\n- Contribute to the architecture and design of highly scalable systems.\n- Develop and maintain CI/CD pipelines.\n- Work with cloud infrastructure, particularly AWS and Serverless architecture.\n- Collaborate with cross-functional teams to deliver high-quality software solutions.\n\nYour skills and experience\n- Minimum of 3 years of experience in software development.\n- Strong problem-solving skills and analytical thinking.\n- Confidence with JavaScript/Node.js and TypeScript. Experience with Express and NestJS is a huge plus.\n- Experience with TypeORM or Prisma, and implementing DTOs in a production environment.\n- Proficient in SQL and database optimization.\n- Decent knowledge of Node.js asynchronous programming patterns.\n- Experience with AWS services and Serverless architecture.\n- Upper-intermediate level of spoken English for effective communication.\n- Good understanding of containerization (Docker and K8s).\n- Understanding of CI/CD pipeline.\n- Experience in Data Engineering industry is a plus.\n\nWhy you\'ll love working here\n- 13th-month salary: calculated as one month\'s actual basic salary if the employee works for 12 months of the calendar year.\n- Annual Leaves: employee who has been working for 12 months or more is entitled to fully-paid annual leave with 12 days.\n- Social Insurance, Medical Insurance, Unemployment Insurance: Yes\n- Convenient shared office in Thao Dien, HCM\n- Flexibility in commuting time (8:30~9:30 AM)\n- Flexible working time with notice (ex. Visiting hospital, bank etc)\n- Latest device support in any type (Mac, monitors etc)\n- Working 5 weekdays (Mon-Fri)\n- Work-related books and lectures supported\n- External activities (Clubs)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thao Dien, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(640, 182, 2, 'IT Governance Officer', 'The IT Governance Officer will execute and maintain IT internal controls over processes in compliance with company standards. Monitors and troubleshoots together with the Cybersecurity team in threat detection. Oversees IT operational potential risks to deploy controls in place appropriately. Plans and executes remediations for risk findings. Assists the IT service delivery team with day-to-day work.\n\nKey Responsibilities:\nMonitor and troubleshoot with the line manager and cybersecurity team or vendor on threat protection and cyberattacks.\nMonitors and investigates phishing emails reported from staff, if it is required to block url/domain and/or email of the sender.\nMaintains security policy up to date to make sure hardening policy is applied strictly on MacOS and Windows Devices as well as the logon policy standard.\nInvestigates and works with end users to resolve any security breaches, which would be escalated to cyber cybersecurity team for technical issues if required.\nMonitors and collaborates with the cyber team to ensure timely remediation of vulnerabilities and misconfigurations.\nMonitors and troubleshoots all failed/missed updates from weekly patching reports.\nAssists the line manager in deploying all security features where required.\nReports monthly on device compliance status.\nMaintains user matrix with roles and system access, together with engineering head advice that requires review and update yearly.\nProcesses quarterly access review and update with line managers and system owners.\nWorks together with the cybersecurity team to conduct an IT internal Pentest with the vendor, then schedules with the line manager to remediate any findings with high or medium potential risks.\nMonitors and reports on the protection of data lost through outbound email rules as well as hard disk encryption for compliance\nMaintain and improve System Access management processes on the core system, such as MS Entra ID.\nWork closely with Cyber Security and IT Operations teams to ensure governance alignment.\n\nYour skills and experience\nBachelor’s degree in information technology, Cybersecurity, Computer Science, or a related field (or equivalent work experience).\nMinimum three years of experience working in related areas, including software installation, policy deployment, patch updates, and troubleshooting in Windows & MacOS environments.\nExperience with Microsoft Entra ID, Microsoft Intune, and Microsoft 365 portal.\n\nPreferred Qualifications:\nIT certifications (e.g., Network+, ITIL or Microsoft certifications).\nKnowledge of cybersecurity principles and practices.\nExperience with scanning and endpoint tools (e.g., Endpoint Central, Cisco Secure Endpoint, Tenable.io/Nessus)\nExperience with internal and external IT audit\n\nWhy you\'ll love working here\nYou’ll love working with us if you are:\nPassionate about technology.\nIndependent but also a good team player.\nComfortable with a high degree of ambiguity.\nFocused on usability and speed.\nKeen on presenting your ideas to your peers and management.\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\n\nSome of our benefits:\nMeal and parking allowances are covered by the company.\nFull benefits and salary rank during probation.\nInsurances such as Vietnamese labor law and premium health care for you and your family.\nSMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\nValues-driven, international working environment, and agile culture.\nOverseas travel opportunities for training and work-related.\nInternal Hackathons and company events (team building, coffee run, etc.).\nPro-Rate and performance bonus.\n15-day annual + 3-day sick leave per year from the company.\nWork-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(641, 223, 2, 'DevOps Engineer', 'Akila is looking for a DevOps Engineer with ambition, creativity and a passion for sustainability and technology. Our team is involved in a wide variety of technologies, like digital twin, 3D engine development and cross platform development. This role will be critical for Akila’s development, as it represents both Mobile and Web platform. Candidate should be comfortable working in a fast-moving startup environment where speed, hard work and fresh thinking are critical to success.\n\nIn charge of automatic operation and maintenance, project delivery, deployment, monitoring and service governance and optimization of Akila platform.\nImprove the efficiency and quality of software development, operation and maintenance.\nDesign and develop DevOps infrastructure and CI/CD framework.\nProvide tech support on safety, promote security programs and platforms.\nAnalyze and solve problems, be able to quickly respond to emergencies.\n\nYour skills and experience:\nExperience with DevOps tools and technologies, like Git, Jenkins, Maven, Terraform and common tools like ELK, Prometheus.\nRich experience with Docker containers and skilled in using Docker, Kubernetes and Istio.\nExperience with Cloud providers like Azure and AWS, must be familiar with those popular PAAS services like MySQL, Redis, Object Storage, Click-house and IoT Time Series Database and CDN etc.\nFamiliar with one or more programming languages, Python and Shell are preferred.\nHave in-depth understanding of distributed architecture, like microservice architecture, service-mesh.\nBe familiar with mainstream R&D technologies, with open-source community are preferred.\nProficient in Linux system administration and command-line tools.\nPerform zero-downtime upgrades for serving critical online traffic and tight SLA batch jobs.\nKnowledge of application security testing tools (SAST, DAST, SCA) is a plus.\nKnowledge of MLOPS is a plus.\nExcellent trouble shooting skill.\nProactive & Plan-Do-Check-Act attitude with good capabilities of problem solving.\nExcellent attention to details, follow-through design and be able to work independently.\nAdaptable, resilient, and positive attitude.\nGood English communication.\n\nWhy you\'ll love working here:\nThe opportunity to work on groundbreaking digital-twin technology that directly contributes to decarbonization and sustainable building practices.\nCollaborate with industry leaders in AI, 3D visualization, and simulation.\nBe part of a fast-growing, innovative team shaping the future of digital twins.\nCompetitive salary and benefits package, with flexible work arrangements.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Peakview Tower, 36 Hoang Cau, O Cho Dua, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(642, 468, 2, 'AI Solutions Engineer (Python/Machine Learning/LLM)', 'We are looking for a skilled and product-minded AI Solutions Engineer to join our Product Department. In this role, you will help identify real business problems and turn them into scalable AI/ML solutions. You’ll work closely with cross-functional teams to develop and deploy end-to-end AI products that bring measurable value to the company.\n\nKey Responsibilities:\n- Identify and assess opportunities to apply AI/ML (especially LLMs, APIs, or custom models) to internal business processes.\n- Build and deploy end-to-end AI solutions such as chatbots, document processing tools, recommendation engines, etc.\n- Integrate AI solutions with internal systems (e.g., CRMs, databases, internal tools).\n- Fine-tune or prompt-tune open-source or API-based LLMs to address specific business use cases.\n- Work closely with product managers, business stakeholders, and data teams to align AI solutions with actual business needs.\n- Communicate technical solutions to non-technical audiences when required.\n\nYour skills and experience:\nEducation & Experience:\n- Bachelor’s degree in Computer Science, Software Engineering, Information Technology, or a related field.\n- Minimum 5 years of professional experience in relevant domains.\n\nTechnical skills:\n1. Applied AI/ML:\n- Hands-on experience with LLMs such as GPT, LLaMA, Mistral, etc.\n- Proficiency with frameworks/libraries like LangChain, LlamaIndex, or Haystack.\n- Experience with fine-tuning, embedding-based retrieval (RAG), or model adaptation.\n- Worked with vector databases such as FAISS, Weaviate, or Pinecone.\n\n2. Software Engineering:\n- Strong Python skills (FastAPI, Flask, or similar frameworks).\n- Experience with REST APIs, microservices, Docker, and cloud platforms (AWS, GCP, Azure).\n- Basic understanding of CI/CD pipelines, version control, and software deployment.\n\n3. Data Engineering:\n- Ability to work with both structured and unstructured data.\n- Experience building data pipelines and performing preprocessing.\n- Familiar with SQL, Pandas, and ideally some Apache tools (e.g., Spark, Airflow is a plus).\n\n4. Product & Business Mindset:\n- Ability to translate business problems into technical AI/ML solutions.\n- Comfortable working with and explaining ideas to non-technical stakeholders.\n- Cares about ROI, user experience, and solution scalability.\n\nLanguage:\n- Proficient in English, particularly in reading technical documentation and collaborating with cross-functional teams.\n\nWhy you\'ll love working here:\n- Working in the financial/securities environment.\n- Competitive salary and bonus based on performance of staff.\n- Salary review every year, many opportunities for career development.\n- Participating in the types of compulsory insurance as policy.\n- Receiving annual health care, full health insurance and accident 24/24.\n- Participating in the company\'s training programs.\n- Being supportive of the tuition fee for the training courses.\n- Participating in sports activities, charitable programs, quarterly teamwork and annual trip.\n- Working in a professional and dynamic environment, and enjoy the fresh air, peaceful environment at Phu My Hung urban.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 21, Phú Mỹ Hưng Tower, số 08 Hoàng Văn Thái, Phường Tân Phú, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(643, 308, 2, 'Geospatial Analysis Team Leader (GIS, Data Analysis)', 'About Citics\nCitics is a comprehensive and pioneering real estate technology platform in Vietnam, built on big data, AI, and seamless digital solutions. By integrating valuation, mortgage referral, property transactions, and investment services into a single platform, Citics simplifies and enhances transparency across the entire real estate journey. Today, Citics operates in over 30 provinces, has digitized more than 33 million properties nationwide, and partners with over 80% of the leading banks in Vietnam. This strong foundation affirms Citics’ position as a trailblazer in the digital transformation of Vietnam’s real estate market.\n\nJob Summary\nWe are seeking a skilled and experienced Geospatial Analysis Team Leader to manage and grow our GIS capabilities. This role involves leading a Geospatial Data team and collaborating across departments to drive data quality, innovation, and scalability in our geospatial services. In this role, you will support various geospatial projects by analyzing geographic data, creating maps, and providing insights that assist in decision-making processes.\n\nDuties and Responsibilities\n- Lead and manage the Geospatial Analysis Team (5 - 10 members), including task planning, mentoring, and performance evaluation.\n- Develop and maintain documentation, standard operating procedures, and internal training resources.\n- Collect, process, and analyze cadastral, zoning, and real estate development data.\n- Ensure data quality through validation, aggregation, and continuous improvement.\n- Manage the storage and synchronization of cadastral and planning data within internal systems.\n- Build and optimize automated and semi-automated GIS workflows using tools such as FME, Model Builder (ArcGIS Pro), Model Designer (QGIS), Spatial ETL, and Python.\n- Advise the Board of Directors on GIS strategy and implementation aligned with business goals.\n- Support cross-functional teams with expertise in cadastral and zoning data.\n\nYour skills and experience\nExperience:\n- 3–5 years in geospatial analysis, with at least 3 years in a technical leadership or project management role within GIS.\n\nTechnical Skills:\n- Strong command of coordinate systems (VN2000, HN72, WGS84) and transformations.\n- Advanced skills in handling cadastral and planning datasets from basic to complex levels.\n- Excellent problem-solving, communication, and team collaboration abilities.\n\nTools & Technologies:\n- GIS Platforms: ArcGIS Pro, QGIS (including Model Builder/Designer)\n- ETL Tools: FME Form (formerly FME Desktop)\n- Databases: PostgreSQL with PostGIS extension\n- Server/Backend: GeoServer, Python (especially with Pandas, GeoPandas, Shapely)\n- CAD: MicroStation, AutoCAD\n\nData Formats:\n- Vector: *.shp, *.geojson, *.json, *.gdb\n- Raster: *.mbtiles, *.geotiff, *.pbf\n- CAD: *.dgn, *.dwg\n\nWhy you\'ll love working here\nInside our engineering team:\n- We iterate constantly. There\'s no such thing as the best version of anything, just a constant streams of improvements and tests.\n- We move fast, really fast. Major changes can be executed in a few days, many times just a few hours.\n- We have a data-informed mindset. We try to use data to inform our decision as much as possible.\n- We are independent. Most of the time, your team will not need technical assistance from other teams.\n- We take risks. We\'re not afraid to challenge "best practices".\n\nOur attractive offers include:  \n- Open communication with passionate and experienced members.\n- Challenging working environment.\n- Social insurance, unemployment insurance under the Insurance Law\n- Internal events to bond our mutual understanding & spirit such as team building, team outing, Citic\'s birthday, Year-end party...\n- Generous special Employee Stock Ownership Plan (ESOP), which is approved by the Board of Director.\n- 40 flexible working hours per week from Monday to Friday.\n- Young, dynamic working environment with strong startup culture.\n- Training and career development opportunities.\n- Company team building, annual Birthday party and other events: New Year, X-mas, Mid Autum Festival,…\n- Support fee for parking, marriages, child births, hospitalization.\n- Sport clubs (Running, Badminton, Soccer).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lakeview 1, An Khanh Ward, District 2, HCMC, District 2, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(644, 469, 2, 'Fullstack Developer (Go/Python/NodeJS/ReactJS)', 'How are you going to make a difference? As a Fullstack Engineer at Gearment, you will contribute to designing and developing scalable backend microservices using Go and implementing user-facing frontend features with ReactJS for our multi-channel e-commerce platform.\n\nDesign and develop backend systems with Go in a microservices architecture.\nBuild responsive, high-performance frontend components using ReactJS.\nIntegrate with third-party marketplaces (Amazon, Etsy, eBay, etc.) for data synchronization.\nWrite unit tests to ensure code quality and coverage.\nCollaborate with Product Owners, QC, and SRE teams to ensure product quality, performance, and security.\nMentor junior engineers and contribute to building a strong engineering team.\nImplement the frontend & backend features for involved products/applications.\n\nYour skills and experience\n4+ years of software development experience, with strong proficiency in Go (or Python/NodeJS) and ReactJS\nSolid understanding of microservices architecture, Git, and modern software development principles (Clean Code, TDD, DDD, etc.).\nFamiliar with cloud environments and deployment practices (CI/CD, GitFlow).\nExperience with monitoring tools (Prometheus, Grafana, InfluxDB) and APM solutions (Sentry, Datadog, Elastic APM, etc.).\nStrong foundation in algorithms, data structures, and system performance optimization.\nStrategic thinking and strong problem-solving mindset.\nCalm under pressure, proactive, and self-organized.\nHigh integrity and ownership.\n\nBig Plus:\nAdvanced database tuning and performance optimization.\nExtensive experience in CI/CD implementation (Jenkins, CircleCI, etc.).\nKnowledge of monitoring systems (InfluxDB, Grafana, AWS CloudWatch, Prometheus).\nExperience with APM & error tracking tools (Sentry, NewRelic, Datadog, Elasticsearch APM).\nFamiliarity with logging systems (ELK/EFK stack).\n\nWhy you\'ll love working here\nSalary: Up to 45,000,000 Gross\n100% official salary during the probation period\nPremium health care insurance and annual health check-ups.\nAll benefits followed Vietnamese labor law, including a 13th-month salary plus a competitive bonus.\nBonding money per quarter\nAnnual company trip and team building\nWeekly Happy Lunch on Friday\nBonuses and gifts for holidays, Tet, etc\nDynamic and professional working environment.\nAllocate modern working devices: Laptop, Second Monitor and anything you need.\nWorking from Monday to Friday (8.30 am – 5.30 pm)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 5 - Jabes 1 Building, 244 Cống Quỳnh, Phạm Ngũ Lão Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(645, 470, 2, 'Software Developer (Winforms, SQL, C#)', '- Phân tích viết tài liệu.\n- Lập trình các modul theo phân công của quản lý dự án.\n- Báo cáo tiến độ và tình trạng công việc cho người quản lý trực tiếp.\n- Hỗ trợ, bảo trì hệ thống phần mềm trong quá trình vận hành.\n- Có thể tham gia triển khai phần mềm khi dự án cần.\n\nYour skills and experience:\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc tương đương\n- Thành thạo lập trình Winform nền C#.\n- Có kinh nghiệm làm việc với MS SQL.\n- Có khả năng học hỏi nhanh.\n- Chủ động, có tinh thần trách nhiệm cao đối với công việc.\n- Có tư duy tốt, hiểu biết về data structures và algorithm.\n- Nắm vững lập trình hướng đối tượng OOP.\n- Có khả năng đọc hiểu tài liệu tiếng Anh.\n- Có kinh nghiệm làm các dự án ERP là một lợi thế\n\nWhy you\'ll love working here:\n- Lương: 15-22tr\n- Thưởng theo từng dự án khi hoàn thành mỗi giai đoạn.\n- Thưởng dài hạn theo lợi nhuận phát sinh của mỗi sản phẩm mà cá nhân có tham gia theo tỷ lệ tương ứng với đóng góp.\n- Lương tháng 13, Thưởng thành tích cuối năm, Thưởng tết dương lịch và các ngày lễ tết, các phúc lợi như sinh nhật, cưới hỏi, ốm đau, hỗ trợ đường xa...\n- Xét tăng lương 2 lần/ năm.\n- Hỗ trợ cơm trưa tại VP công ty.\n- Được tham gia BHXH, BHYT theo quy định của nhà nước.\n- Du lịch nghỉ mát hàng năm.\n- Khám sức khỏe toàn diện định kỳ.\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc.\n- Môi trường năng động cho phép phát huy tối đa khả năng và tính sáng tạo trong công việc.\n- Các CLB : bóng bàn, Yoga, đá bóng, Game E-Sport.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 5C, Tổ 14, Phường Định Công, Hoang Mai, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(646, 229, 2, 'Web Developer', 'Headquarter: Daoukiwoom Group - Find more at: \nIndustry: Finance & Trading\n \n• Develop and maintain Web apps using Java Spring Boot\n• Work directly with remote team to clarify tasks and requirements\n• Develop new features based on the user requirements (analyzing requirements and system design)\n• Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance\n• Managing time and resources based on the WBS\n• Write high-quality, clean, elegant, maintainable, and testable code\n• Maintaining technical documents up-to-date\n• You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n• Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the Kiwoom Framework for Kiwoom Indonesia, Finansia (in Thailand), and so on\n\nYour skills and experience\nEducation & Technical skills:\n• Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n• At least 3 years of relevant experience in Java development, Spring Framework and SQL.\n• Experience and knowledge in markup language, including HTML, CSS.\n• Experience with frontend JavaScript.\n\nSoft Skills & Communication \n• Able to communicate in English, written and spoken.\n• Strong problem-solving and analytical skills.\n• Strong communication skills and teamwork, international experience is preferred.\n\nNice to have:\n• Understand of API design and implementation.\n• Ability to write clean, easy to understand code.\n• Familiarity with version control systems, such as Git or SVN.\n• Familiarity with issues tracking tools, such as Redmine.\n• Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nWhy you\'ll love working here\nSPECIAL OFFER\n• Providing training and education experience in Korea with Korean Finance/IT expert \n• Providing opportunities to work and support in IT/Finance fields overseas\n\nBENEFITS\nIncome & Achievement\n• Competitive salary, salary review once a year\n• 13th month salary and Annual Performance Bonus\n• MVP and Shining star awards at the end of year\n• Global and professional working environment\n\nWorkplace Happiness\n• Full SHUI as Vietnamese Law\n• Premium Private Medical Insurance PVI and annual health check\n• 15-day annual leave\n• 01 day Christmas leave and 90-min menstrual leave for women\n• Company event, YEP and monthly gathering time\n• Gifts on special occasion and fully stocked snack corner\n• Sponsored training courses and book purchase quarterly\n• Be well-equipped with new working equipment\n\nHIRING PROCESS:  The interview will be conducted at our office in Ho Chi Minh city. \nRound 1:\n• Step 1: Live coding test\n• Step 2: Interview with part team leader (upon passing coding test)\n• Step 3: Interview with Director\nRound 2: Final interview with Head Office in Korea', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '14F, AP Tower, 518B Dien Bien Phu Street, Ward 21, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(647, 214, 2, 'Software Engineer (C++, OOP, Middleware)', 'Top 3 reasons to join us\nCompetitive salary & up-to 16-month income / year\nAttractive allowances & benefits\nFlexible working time with many company holidays\n\nJob description\nAs an Automotive Software Engineer with one of 2 teams, you will be responsible:\n\nVehicle Network Team:\n• Researching and developing applications, framework service (middleware) for Car Infotainment, AVN (Audio Video Navigation) and Telematics system in both C/C++ Linux Embedded and Android Framework (AOSP)\n• Develop software products with cutting edge automotive technologies (Bluetooth/Wi-Fi, OTA & SW Update, In-Vehicle Network services: Ethernet, Diagnostic, Car Interface)\n(*) Bluetooth/Wi-Fi jobs are available for both C/C++ Linux and Android Framework AOSP, the other technologies are only for C/C++ Linux.\n• Participating in the full Software Development Life Cycle (Agile, ASPICE, NPI) from requirement analysis, creating software design documents (HLD/LLD, detailed design), implementation, testing (UT/IT), and maintenance\n• Collaborate with team to delivery reliable software on time based on project milestone.\n• Handle technical problems, and report progress, and work results to the technical leader.\n• Generate reports, communicate with local managements and head quarter\n\nTelematics SW Team:\n• Develop Automotive Telematics features in both Application and Middleware layers, such as Remote Services, Crowded Data Collection and Power, Routing, Telephony Managers.\n• Participating in the full Software Development Life Cycle (Automotive SPICE, Agile) from requirement analysis, creating software design documents, implementation, testing and verification.\n• Collaborate with team to delivery reliable software on time based on project milestone.\n• Handle technical problems, and report progress, and work results to the technical leader. • Generate reports, communicate with local managements and head quarter\n\nYour skills and experience\n*** General requirements:\n• Bachelor degree in Information Technology, Computer Science, Computer Engineering, Electrical Engineering, Telecommunication Engineering, Mathematics, Mechanics and Informatics or equivalent.\n• Strong motivation to develop career in automotive software field.\n• Software development experience in C++ programming;\n• Having good knowledge with OOP, OOAD (Object-Oriented Analysis and Design);\n• Having hands-on experience to use JIRA, GIT and Gerrit;\n• Having hands-on experiences in developing large software systems;\n\n* Highly talented & experienced candidates will be considered for Senior/Leader positions.\n\n*** These skills would be considered as an advantage but not the must:\n• Experiences related to multi-thread, multi-process programming;\n• Having hands-on experiences to use and implement design patterns (MVC, Singleton, Observers);\n• Experiences related to develop application using Qt/QML;\n• Experiences related to design and develop GUI frameworks, front-end applications;\n• Ability to effectively present information to top management, public groups, and/or board of directors.\n\nWhy you\'ll love working here\n13th month salary + Incentive bonus (Total remuneration package / year: up to 16-month salary) + Annual salary review;\nHYBRID WORKING, flexible working time (Mon - Fri)\nSupport for lunch, transportation and other allowances (Coding Expert, Technical leader, phone...);\nPremium health care & accident insurance;\nTotal 20 days off (12 days of annual leave & additional 8 days of company holidays: Summer holiday, Mid-Autumn, Christmas, LG and VS DCV Foundation Days);\nSupport fee to get TOEIC & technical certifications (ISTQB, Agile Scrum...);\nOn-site & training opportunities abroad;\nCompany trip, sport clubs (zumba, football, pingpong, badminton,...);\nMonthly budget for team activities, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 17 đến tầng 21, Tòa văn phòng, Lotte Mall Hà Nội, Số 272 Võ Chí Công, Phường Phú Thượng, Quận Tây Hồ, Thành phố Hà Nội, Tay Ho, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(648, 298, 2, 'Senior Android Developer (Kotlin)', 'ANDPAD Việt Nam is looking for one Android Mobile Developer (Kotlin) who can join our team and develop the application in cooperation with the product manager. Working in the form of Squad, a small team can quickly and consistently engage in everything from design to development, testing and operation.\n\nAlso, there are a lot of opportunities to work with new languages ​​and frameworks other than the main language in an international environment.\n\n■ Job Scope\n- Design and implementation function of the product in charge of using Kotlin and other mobile technologies such as Flutter\n- Refactoring of existing applications, enhancements performance, Cost reduction of regression testing by implementing appropriate test code\n- High-performance design and development of camera module and drawing functions\n- API design and implementation linked with backend\n- Requirements definition and specification formulation in collaboration with product managers, designers and QA\n- Keep up to date on the latest industry trends and best practices in mobile technologies and apply them to the product\n- Enjoy working on challenging solutions and systems\n\nNote: The assigned product will be determined based on the candidate\'s skills and preferences, as well as the internal structure of the company.\n\n■ Development environment\n- Programming: Kotlin, Dart\n- Framework: Kotlin, Flutter\n- Infrastructure: AWS / GCP\n- CI/CD: CircleCI / Bitrise / Fastlane / GitHub Actions\n- Knowledge Tool: Confluence / esa\n- VCS: GitHub\n- Others: Slack / Jira\n\nYour skills and experience\nMust-haves:\n- Empathy for Andpad\'s mission and values\n- 6+ years of experience in developing native applications for Android Native using Kotlin\n- Experience of architecture design, frameworks and technologies selection based on application requirements\n- Experience as a technical lead throughout the full project development lifecycle\n- Creating high quality code for security, performance, scalability, etc.\n- Excellent algorithms, analytical, problem-solving skills and improving application performance\n- Continuously discover, evaluate, and implement new technologies to maximize development efficiency\n- Experience in dealing with scalability in line with service growth\n- Familiar with Restful / GraphQL API\n- Excellent developing functions with writing test code\n- Have knowledge of Mobile application security\n- Conduct regular code reviews and provide feedback to team members adhering to best practices\n- Participate in the planning process for software development projects and ensure meeting quality and deadlines on delivery.\n- Skills in communicating smoothly with team members and other stakeholders\n- Good at English communication\n\nNice to haves:\n- Experience to build project from scratch\n- Ensure high-quality work by monitoring individual and team performance and addressing any issues through appropriate guidance and mentoring\n- Responsible for supervising, managing and motivating the mobile development team\n- Ability to write project documentation\n- Experience in developing hybrid applications for Flutter using Dart\n- Experience in developing native applications for iOS Native using Swift\n- Experience in automation test\n- Project management skills\n\nWhy you\'ll love working here\n- Competitive salary package, including full insurance coverage.\n- Annual performance review: twice/ year.\n- 13th-month salary Bonus.\n- Hybrid working model.\n- 18 days of leave: 12 days of annual leave, 6 days of New Year Leave.\n- Premium Healthcare Insurance Package starting from day one.\n- Annual Health Check-up.\n- Excellent career development opportunities, with exposure to and experience in the latest technologies.\n- Patents and Inventions bonus.\n- Company trip, Year-End Party, Gifts for Tet/ Holidays.\n- MacBook Pro/laptop is provided.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3rd Floor, Dong Nhan Building, 90 Nguyen Dinh Chieu, Da Kao Ward, District 1, Ho Chi Minh; 2F, Building C, Office Area, Udic Complex, Hoang Dao Thuy Street, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(649, 262, 2, 'ICT Enterprise Sales Director', 'Huawei is a leading global provider of information and communications technology (ICT) infrastructure and smart devices. We have 207,000+ employees and operate in over 170 countries and regions, serving more than three billion people around the world. We are committed to bringing digital to every person, home and organization for a fully connected, intelligent world. Total R&D investment over the last decade now exceeds CNY977.3 billion.\n\nKEY RESPONSIBILITIES OF THIS ROLE\n1. Build relationships with mid- and high-level decision maker in named accounts, collaborate with customers, and act as the primary owner of office-level projects to support the achievement of order and revenue targets.\n2. Proactively gain insights into the current status and development trends in the industries of corresponding premier, strategic, and core customers.\n3. Effectively present the business value of Huawei\'s solutions to the customers.\n4. Responsible for overall satisfaction and relationship with big customers\n5. Ensure good understanding of customers’ requirements and current market information\n6. Involve in all activities to ensure the establishment of the brand\n7. Explore for opportunity to achieve sales target with pre-sales team\n8. Pro-actively deliver new sales\n\nYour skills and experience\n1. Master the key communication points regarding new scenarios, and support business development of premier, strategic, and core named accounts.\n2. Knowledge Requirements:\n- Master the knowledge of main products: server, storage, router, switch, wifi, etc.\n- Have a good command of scenario-based industry solution knowledge.\n- Master the basic knowledge of enterprise project operation.\n3. Bachelor’s degree or above in Telecommunication/ Electrical/ Computer Science or Economy related field\n4. Strong experience in selling ICT products: server, storage, network, wifi, etc\n5. High achiever who is ambitious, energetic, independent, and able to work well in a fast change environment\n6. Resourceful, possess excellent communication and interpersonal skills\n7. Must be able to communicate effectively in English.\n8. Familiar with international trading, international law, business management principles, credit collection, finance management, bidding procedures etc.\n\nWhy you\'ll love working here\n* Working time and benefits: \n• Monday to Friday (08:30-18:00). \n• Competitive Salary and performance bonus. Full salary in 2 months of probation. \n• Comprehensive online training platform and overseas training opportunities.\n• Participating in full insurance benefits (health insurance, social insurance, unemployment insurance), the company supports 24/24 accident insurance and health care insurance for employees.\n• Professional working environment, multinational company, good career development opportunities. Cultural and sports activities, taking care of employees\' health and life are organized periodically...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '33rd Floor, Keangnam Landmark, E6, Pham Hung Street, Me Tri Ward, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(650, 238, 2, '[Junior, Middle] Mobile Developer (Flutter)', 'Top 3 reasons to join us\n1. Mức lương cạnh tranh, hấp dẫn\n2. Môi trường làm việc chuyên nghiệp, thân thiện\n3. Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Phát triển ứng dụng di động (iOS và Android) của MBBank, gồm các hệ thống nội bộ và ứng dụng dành cho khách hàng với quy mô 30 triệu khách hàng cá nhân và 300.000 khách hàng doanh nghiệp - đứng đầu Việt Nam về quy mô phục vụ.\n- Tham gia phân tích nghiệp vụ, đề xuất các giải pháp, hỗ trợ các thành viên trong team phát triển (3 - 6 thành viên/dự án)\n- Làm việc chặt chẽ với các team Sản phẩm, UX/UI và Backend để thiết kế, xây dựng các sản phẩm, nền tảng và tính năng mới.\n- Phối hợp cùng các nhà cung cấp trong và ngoài nước triển khai các giải pháp Công nghệ mới nhất về phát triển ứng dụng di động.\n\nYour skills and experience\n- Tốt nghiệp Đại học các chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin...\n- Tối thiểu 01 năm kinh nghiệm làm việc thực tế tại các công ty hoặc dự án về lập trình Mobile, ưu tiên ứng viên có kinh nghiệm với Flutter.\n- Có kiến thức và kinh nghiệm về lập trình với Objective C/Swift/Java/Kotlin.\n- Có kỹ năng sử dụng state management và local storage như SQLite, Shared Preference, nắm vững cơ chế hoạt động của Flutter.\n- Thành thạo sử dụng XCode, Android Studio và các công cụ phân tích như Flipper hoặc Dart DevTools.\n- Đã tham gia phát hành ít nhất 01 ứng dụng được phát hành trên App Store hoặc Google Play.\n\nWhy you\'ll love working here\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\nCơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\nMôi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng\n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(651, 471, 2, 'WordPress Developer (Onsite |Remote)', 'We’re passionate about adding great people to our team. We want people who have hustle and a desire to make things better. We’re currently seeking a WordPress Developer to join our development team. We are looking for someone who wants to make an impact on their peers, the product, and our customers. As a WordPress Developer, you will be responsible for both back-end and front-end development, including creating WordPress themes and custom plugins. We expect you to understand the latest industry trends and content management systems strongly. The ideal candidate will have experience working with WooCommerce.\n\nResponsibilities\n- Maintain and develop websites by CMS WordPress.\n- Build new WordPress pages from provided designs in a timely manner\n- Build WordPress plugins as needed by customers\n- Develop custom WordPress themes and functionalities with PHP\n- Maintain, update, and troubleshoot WordPress websites\n- Do implementation as well as conduct reviews for others.\n- Other assignments from the Manager\n\nYour skills and experience\nMust to have:\n- WordPress expertise, including plugins and 3rd party marketplace, with demonstrated experience in custom theme development and management of core and custom modules.\n- Proficient in building WooCommerce WP sites with large traffic & data, good performance, and security.\n- Experience with creating custom WordPress plugins, WooCommerce plugins\n- Good understanding of front-end technologies, including HTML5, CSS3, SCSS JavaScript, jQuery\n- Proficient in PHP backend to handle effectively and carefully, in professional ways (PSR, MVC, OOP, Systematic Development, Version Control, and Git…)\n- Hands-on experience with RESTful APIs and formats (JSON, XML)\n- Responsibility and proactive\n- Positive thinking, can-do attitude\n- Good written communication skills in English\n\nWhy you\'ll love working here\n- Professional working environment: Clearly-defined internal process and top-notched facilities including Mac, iPhone, Android devices for testing.\n- Clear vision of your career progress: performance review with potential for raise every 6 months.\n- Grow to be a full-stack developer: Opportunity to work with cutting-edge technologies, both front-end and back-end.\n- Days off: Public holidays, and on top of that, 12 paid days off a year, with possibility for more depending on performance level.\n- Premium health insurance for team members\n- You are encouraged to have a life outside of work: Regular team building activities in and outside of office.\n- 13 month salary, lunch allowance + other performance bonuses\n\nWorking Place: 152 Pho Duc Chinh, Truc Bach, Ba Dinh, HN. (Open to work remotely with the candidates not based in HN)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '152 Phó Đức Chính Trúc Bạch, Ba Dinh, Ha Noi; Work remotely, Other, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(652, 405, 2, 'Cloud Data Engineering Lead (AWS, Python, SQL, Java)', 'As a Head of Cloud Data, you are to be in the top technology edge and working closely with various cloud technology leaders. Join us now and be a part of the next generation of cloud technology. Your responsibilities will include:\n\nKey Responsibilities:\n- Designing, coding, and testing software modules/applications for data collection;\n- Identifying, creating, and preparing data required for modern Data Analytics, Data Science; 00Building modern Data Architect (Data Lake, Data Warehouse, and Data Lakehouse) solutions using existed cloud provided services;\n- Creating and documenting the tests to meet requirements;\n- Deploying Data services solutions into cloud environments and integrating them with other components in the application;\n- Maintaining, tuning, and adapting applications to keep them performing to specifications ;\n- Lead/ Manage Data team ;\n- Other tasks as assigned by CTO, CEO\n\nYour skills and experience:\n- +7 years of experience in data engineering and cloud data processing services (AWS, Azure, and (or) Google Cloud Platform)\n- Fluency in SQL and Python is must, knowledge of other languages are preferable (Scala, Java)\n- Experienced with ETL/ELT and Data Integration tools like : Airflow, AWS Glue, Talend(opt), Airbyte or Fivetran, DBT - Query Engine/Data Processing: Prestodb, Flink, Pyspark - Database Engine/Streaming: AWS Redshift(opt), MongoDB, PostgreSQL, Kafka, SQL, MySQL, Oracle(opt)\n- Experienced in real-time data processing like Kafka, Apache Flink, Apache Beam\n- Experienced in using data orchestrations like Apache Airflow, and (or Dagster, Luigi)\n- Interest or experience in Big Data technologies (Hadoop, Spark, Data Bricks, Snowflake)\n- Lead/ Manage team skills\n- Open mindset, ability to quickly adapt to new technologies and learn new practice.\n\nWhy you\'ll love working here\n1. Workplace\n- Work at the heart of cloud innovation and transformation across Vietnam and the region.\n- Collaborate with world-class cloud engineers and business leaders.\n- Join a young and dynamic team with awesome projects applying the latest technology\n- Working with specialists worldwide provides you with a fantastic opportunity to expand your skill set.\n- Culture of openness and honesty in which individuals are respected and encouraged to achieve their full potential\n\n2. Benefits comprise\n- 13th-month salary and attractive performance bonuses.\n- Premium Healthcare and Accident insurance.\n- Free parking and allowances: Lunch, Marriage, Newborn baby and others are applied.\n- A spacious pantry fully equipped with a coffee maker, fridge, microwave, snacks, milk , tea and more\n- A wide range of sports and social activities: badminton, tech clubs, etc.\n- Chance to be honored quarterly and annually with recognition awards for individuals, teams, long-term service, etc.\n- Engaging events: annual company trips, team buildings, internal events, Company’s Year-end party.\n- Training programs including AWS certification support.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '117 Nguyen Cuu Van, Ward 17, Binh Thanh District, Ho Chi Minh City, Viet Nam, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(653, 472, 2, 'Vision Engineer (C++, C#, Python)', 'The successful applicants will carry out the following responsibilities:\n\nDesign and develop features based on customer requirements.\nDevelop new inspection algorithms using image processing/machine learning (ML) techniques\nMaintain and optimize the performance of existing algorithms\nWork with cross-functional teams (QA/SW/TS) to address software-related issues (Especially in memory leaks, hangs, crashes, etc.)\nManage the Unit Test to ensure high-quality source code\nDevelop tools for data collection and analysis to improve work performance\nIntegrate the developed algorithms to company’s common library.\nReport work progress to the manager\n\nYour skills and experience\n\nExperience in software development using C++/C#/Python (3+ YoE)\nGood knowledge about OOP, Data Structure, Design Pattern, UML\nExperience in multi-threading, multi-processing\nExperience in using source version control (Git, SVN) and management tool (Jira, Jenkins, …)\nExperience in Digital/Signal Processing, especially on Computer Vision & Image Processing. (OpenCV, IPP, …)\nGood knowledge on Machine learning (ML) techniques.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Trang An Complex bldg, CT1, 1 Phùng Chí Kiên (TS & TQA team), Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(654, 238, 2, 'Pentester', 'Job description:\n- Rà soát an ninh các dịch vụ của Ngân hàng & Công ty thành viên\n- Rà soát mã độc/webshell /audit máy chủ của Ngân hàng & Công ty thành viên\n- Nghiên cứu đề xuất giải pháp an ninh\n- Phối hợp triển khai các giải pháp an ninh\n- Xây dựng & chuẩn hóa các quy trình đánh giá an toàn thông tin (ATTT)\n\nYour skills and experience:\n- Tốt nghiệp hệ chính quy các Trường Đại học trong nước hoặc nước ngoài\n- Chuyên ngành đào tạo: Công nghệ thông tin, Toán tin, Điện tử Viễn thông, kế toán ... tương đương\n- Tối thiểu 01 năm kinh nghiệm đánh giá/kiểm thử bảo mật hệ thống, xử lý sự cố an toàn thông tin.\n- Hiểu biết về ISO27001, PCIDSS, ITIL…\n- Có hiểu biết về chính sách/quy trình ATTT\n- Hiểu biết CSDL, các công cụ lập trình phổ biến nền tảng web/mobi;\n- Hiểu biết và đánh giá được nền tảng ứng dụng web/app, đánh giá các lỗ hổng hạ tầng dịch vụ (DB, WEB SERVER,…). Đánh giá các dịch vụ của các tổ chức tài chính lớn tại Việt Nam, Nước ngoài;\n- Có kinh nghiệm sâu rộng về cơ sở dữ liệu, hệ điều hành, mạng, giải pháp an ninh bảo mật là một lợi thế;\n- Có chứng chỉ về CEH / CHFI / OSCP / OSCE / Security+ là một lợi thế\n- Có CVE hoặc công bố nghiên cứu ATTT trên các tạp chí chuyên ngành là một lợi thế\n\nWhy you\'ll love working here:\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\nCơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng \n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\nMôi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng \n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(655, 473, 2, 'DevOps Engineer', 'Job description\n- Tham gia trực tiếp vào các dự án tư vấn giải pháp và triển khai DevSecOps cho khách hàng;\n- Triển khai, cài đặt và cấu hình các công cụ liên quan DevSecOps, CI/CD như Container Orchestration (Kubernetes/OpenShift), Source Code Management (GitLab, GitHub), Automation Tools (Jenkins, GitLab CI, …), Artifact Management Tools (Nexus, JFrog), Code Scanning Tools (Sonarqube, Semgrep, BlackDuck, Coverity, …);\n- Triển khai, cài đặt, cấu hình các giải pháp Observability (Logging, Monitoring, Tracing);\n- Xây dựng CI/CD pipeline cho các ứng dụng;\n- Hỗ trợ vận hành, quản trị các giải pháp và công cụ nêu trên cho khách hàng;\n- R&D các giải pháp, công nghệ mới liên quan đến DevOps, DevSecOps, Cloud-Native, AI, …\n\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành liên quan;\n- Kinh nghiệm làm việc: từ 02 năm trở lên, trong đó có từ 01 năm kinh nghiệm DevOps;\n- Có kinh nghiệm làm việc với các công cụ DevOps cơ bản như: Git, Repo, Scan tools, …;\n- Có kinh nghiệm làm việc với containers, k8s;\n- Có kinh nghiệm làm việc với các công cụ tự động hóa như Ansible hay Terraform;\n- Có kinh nghiệm làm việc với các công cụ giám sát hệ thống như Grafana, Elasticsearch;\n- Ưu tiên có kinh nghiệm với lập trình phần mềm;\n- Trình độ tiếng Anh: giao tiếp cơ bản, có khả năng nghiên cứu, đọc hiểu và viết tài liệu chuyên môn bằng tiếng Anh;\n- Đam mê công nghệ và có kỹ năng giải quyết vấn đề.\n\nWhy you\'ll love working here\n- Hưởng mức lương từ 20M - 40M/tháng tùy theo năng lực;\n- Thời gian làm việc từ Thứ 2 đến Thứ 6. Nghỉ Thứ 7, Chủ nhật và các ngày lễ, Tết theo quy định;\n- Môi trường làm việc hướng đến sự phát triển, ổn thỏa, hài lòng và có ý nghĩa của toàn thể công ty và các thành viên. Trong đó đề cao các giá trị tôn trọng và công bằng, trung thực và tử tế, chuyên nghiệp và chu đáo;\n- Hưởng đầy đủ quyền lợi và được đóng bảo hiểm theo Bộ luật Lao Động;\n- Chế độ chăm sóc sức khỏe: chu đáo và cá nhân hoá:\n- Khám sức khỏe định kỳ có hỗ trợ tùy chỉnh theo nhu cầu và tình trạng sức khoẻ của mỗi người;\n- Trang bị gói bảo hiểm sức khỏe hàng năm của các công ty bảo hiểm như Bảo Việt, PVI, VBI…;\n- Thưởng cuối năm: Lương tháng 13 + thưởng theo tình hình kinh doanh của Công ty;\n- Thưởng các dịp lễ, Tết;\n- Tham gia các khóa đào tạo nội bộ, phát triển kỹ năng và tư vấn lộ trình phát triển;\n- Có cơ hội tham gia hội thảo công nghệ, các khóa đào tạo nâng cao và chuyên sâu, tiếp cận công nghệ mới;\n- Tham gia chương trình du lịch và team building hàng năm của công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, AC Building, số 3 ngõ 78 Phố Duy Tân, Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(656, 474, 2, 'Java Developer (Middle - Senior - Team Leader)', 'Top 3 reasons to join us\n• Multinational working environment\n• Attractive salary\n• Top 1 System Reform professional company in Japan\nJob description\n• Participate in product planning and design and provide technical implementation solutions.\n• Responsible for core architecture design, business code writing, and tool development.\n• Complete the coding and debugging of the designated modules on time according to the project schedule and progress.\n• Review the project code and adjust, optimize and expand the existing system according to the needs of the project.\n• Overcome various technical problems such as performance and multithreading.\nYour skills and experience\nMUST HAVE\n• Over 3 years of practical experience in Java (Spring/Spring Boot/TERASOLUNA/Seasar2/wacs/struts).\n• Practical knowledge of version control systems, SVN/GitHub etc.\n• Experience with SQL and JPA/Hibernate/MyBatis/iBATIS.\n• Knowledge of databases such as Oracle/DB2/PostgreSQL, etc.\n• A structured mindset with the ability to adapt to changes in a fast-growing organization.\n• Ability to work well as part of a team in a fast-paced environment.\nNICE TO HAVE\n• Hands-on experience with Kubernetes and Docker.\n• Familiarity with DevOps toolchain: GitHub, SonarQube, etc.\n• Knowledge of Screen Template such as JSP, HTML5, Thymeleaf etc.\n• Experience with elastic AWS infrastructure.\n• Priority will be given to those who know English/Japanese.\n• Ambitious and results-driven personality.\nWhy you\'ll love working here\n• Career development based on your skill and expectation. Have opportunity to become part of our young Leadership team.\n• Professional and flexible working environment\n• Multinational working environment, you will have opportunities for overseas assignments at company branches (Japan, China, US).\n• Competitive salary: ~55M Gross\n• Upto 15 months’ salary per year\n• Monthly KPI Evaluation and Outstanding Employees Bonus\n• Training courses:\n• Technical skills training\n• Japanese – English training by foreign teacher\n• Dynamic activities: Company trip, teambuilding activities, monthly birthday, weekly happy times.\n• Annual health check-up at a good hospital.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '14th floor, Richy Tower, No 35 Mac Thai To, Yen Hoa ward, Cau Giay district, Ha Noi., Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(657, 239, 2, '[Women Leadership in Tech] Embedded Resource Manager', 'We’re empowering and promoting Women Leadership roles in Software Engineering within the Automotive domain, specifically in Power Solutions – Software & Controls.\nThis role is at the heart of our mission to reshape the talent landscape through inclusive, forward-thinking talent management. As a Resource Manager, you will play a strategic role in nurturing, developing, and deploying talent effectively to meet dynamic project demands.\n\nKey Responsibilities\n\n- Developing and implementing technology road map for team\n- Collaboratively working with project and talent stream for technical issues \n- Partnering with development functions for demand-supply management \n- Enable associates to find work aligned to the skills \n- Well-nourished and well-orchestrated talent management and development \n- Effective risk management in technical complexity and volatility \n- Increase of engineering efficiency \n- Availability of the right technical associates at the right time for the right projects\n\nYour skills and experience\n\nMust Have:\n- Bachelor’s or Master’s degree in Computer Science, Electrical & Electronics Engineering, or a related engineering field.\n- 10+ years of experience in project/program management with strong leadership and organizational development skills.\n- Proven experience in the embedded systems field and in managing teams of 50+ members.\n- Solid understanding of software requirements and the software development lifecycle.\n- Proficiency in V-Model and Agile methodologies for effective project execution.\n- Demonstrated ability to lead teams, mentor individuals, and support both technical and personal development.\n- Excellent communication skills in English, both written and verbal.\n- Strong ability to collaborate effectively across departments and multidisciplinary teams.\n\nNice to Have:\n- Experience in the automotive embedded systems field.\n- Familiarity with continuous integration (CI) and continuous delivery (CD) practices.\n- PMP and/or Scrum Master certification(s) preferred.\n\nWhy you\'ll love working here\n\nWhy BOSCH?\nBecause we do not just follow trends, we create them. Together we turn ideas into reality, working every day to make the world of tomorrow a better place. Do you have high standards when it comes to your job? So do we. At Bosch, you will discover more than just work.\n\nBenefits and Career Opportunities\n- Working in one of the Best Places to Work in Vietnam and Top 30 of the Most Innovative Companies all over the world\n- English-speaking environment, with opportunity to be part of innovation team and work in global projects\n- Onsite opportunities\n- Engage in our diverse training programs which surely help strengthen both your personal and professionalism\n- Flexible working time\n- 13th-month salary bonus + attractive performance bonus (you\'ll love it!) + annual performance appraisal\n- 100% offered salary and mandatory social insurances in 2-month probation\n- 15++ days of annual leave + 1-day of birthday leave\n- Premium health insurance for employee and 02 family members\n- Lunch and parking allowance\n- Good benefits of company activities such as: football, badminton, yoga, Aerobic, team building…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa street, ward 13, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(658, 475, 2, 'DevOps Engineer (AWS)', 'Top 3 reasons to join us\n- International product company with a neat product!\n- Work-life balance, with local working hours\n- Improve and practice your English every day!\n\nJob description\nWe’re rebuilding a global SaaS platform used by chefs and foodservice pros for over 20 years—with a fresh focus on AI, real-time data, and elegant infrastructure.\n\nYou’ll join a product-led team that values clean architecture, fast feedback loops, and writing documentation your future self will thank you for. Your mission: lead our shift from Linode to AWS, set up GitOps CI/CD, and help us scale securely and cost-effectively.\n\nYour Toolbox\n- Cloud Infrastructure\n  - AWS ECS (Fargate), ALB, Route 53, VPC, WAF\n  - Cost-optimised scaling with Karpenter or ASG\n  - Terraform-managed infrastructure\n  - Secrets Manager, IAM, ECR, S3\n\n- CI/CD & Deployment\n  - GitLab pipelines + Git-based environments\n  - Docker containers with branch previews\n  - AWS CodeDeploy for zero-downtime releases\n\n- Observability & Performance\n  - Grafana dashboards, Prometheus metrics\n  - Sentry + CloudWatch\n  - DORA metrics for team insights\n\n- Security & Compliance\n  - SOC-2 aligned: access control, secrets rotation\n  - Vulnerability scans, audit logging\n\nWhat You’ll Do\n- Lead migration from on-prem to scalable AWS infra\n- Design and maintain GitOps-style CI/CD pipelines\n- Define infra patterns that boost dev productivity\n- Implement SOC-2 aligned security practices\n- Set up monitoring and error tracking that just works\n- Create clean docs\n\nWe care about fast deploys, secure infra, and systems that scale beautifully. If you do too—let’s talk!\n\nYour skills and experience\nRequirements\n- 3+ years or more in DevOps/SRE roles supporting production systems\n- Strong experience with AWS services (ECS, EC2, RDS, S3, IAM)\n- Proficient in Docker containerization and ECS orchestration\n- Experience with GitOps principles and CI/CD pipelines\n- SOC-2 or similar compliance knowledge and implementation\n- Familiarity with monitoring tools (Grafana, Sentry, CloudWatch)\n- Very good written English for documentation\n- Experience with infrastructure migration projects\n\nBonus:\n- DORA metrics implementation and team productivity optimization\n- Terraform and Infrastructure as Code expertise\n- Cost optimization and FinOps practices\n- Security tooling and vulnerability management\n- Experience in Python or TypeScript is big plus\n\nWhy you\'ll love working here\n- Lead a complete cloud transformation project\n- Modern toolchain with clean architecture ownership\n- Autonomy with clear migration roadmap\n- High engineering standards and meaningful impact\n- Friendly, international environment\n- Fast decision-making and collaborative culture', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hoang Dao Thuy, Trung Hoa Ward, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(659, 303, 2, 'Android Engineer', 'About FuelCloud\nFuelCloud’s mobile app is a crucial piece of the FuelCloud customer experience, and the Android Engineer position will work on optimizing and adding new features to make the app even more impactful for our customers. You’ll work with a cross-functional team to define, design, and deliver new features that build towards FuelCloud’s vision of the future of fueling.\nIn our fast-paced environment, you’ll need to work efficiently and collaboratively with your teammates to iteratively develop new features and bug fixes. Whether you’re taking on a task independently or working in concert with your colleagues, your ultimate responsibility will be to make the FuelCloud Mobile app the best that it can be.\n\nJob description\n• Ensure the performance, quality, and responsiveness of the applications by identifying and resolving any bugs or performance issues.\n• Conduct thorough testing and debugging to optimize application functionality and user experience.\n• Participate in code reviews to maintain code quality and ensure adherence to coding standards and best practices.\n\nYour skills and experience\n• Proven experience in developing and maintaining mobile applications.\n• Good knowledge of Android platform: Activity, Fragment, jetpack compose, process & thread, memory management, performance management…\n• Solid problem-solving skills and attention to detail\n• DSA is a part of our interview process\n• Communicate well in English\n• Experience in working with Socket (TCP/UDP) is a plus\n• Have experience in Flutter is a plus.\n\nWhy you\'ll love working here\nWe’ve worked hard to build the workplace culture we’ve always dreamed of - one where we celebrate each other\'s successes, work hard together, and know when it’s time to relax. We know that we can’t reach our goals alone, and think that our culture makes it a little easier to come to work and makes our biggest goals achievable. At FuelCloud, you’ll be using cutting-edge technology and taking on interesting challenges every day with a team that is genuinely happy to have you!\n\nBenefit:\n• Attractive salary (Full salary during probationary period)\n• 13th month - salary\n• Provide Laptop & Screens for working\n• Ability to travel to US\n• Working with expat team\n• Premium health care insurance for you and your family\n• Free annual health check\n• 15 days of PTO and no working OT\n• Company trip & team dinners\n• Many team activities: Birthday party, Mid-Autumn Festival, Christmas, Year End party,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No 22, B2 Street, Sala Urban Residence, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(660, 431, 2, 'Automation QA Engineer (English, QA/QC)', 'We are seeking a highly skilled and experienced Automation QA Engineer to join our software development team. The ideal candidate will have a strong background in automation testing, with a particular emphasis on search technologies and GraphQL. This role will also involve occasional integration tasks for various products, including CMS and Commerce systems.\n\nKey Responsibilities: \n- Design, develop, and maintain automated test scripts to ensure the quality and performance of our software products. \n- Collaborate with development teams to understand product requirements and create comprehensive test plans. \n- Execute automated tests and analyze results to identify defects and areas for improvement. \n- Provide expertise in search technologies and GraphQL to enhance testing strategies. \n- Occasionally cover integration tasks for products such as CMS and Commerce systems. \n- Participate in code reviews and contribute to continuous improvement of testing processes. \n- Mentor junior QA engineers and share best practices within the team.\n\nYour skills and experience\n- Minimum of 3 years of experience in automation testing within software development. \n- Proficiency in search technologies and GraphQL is a significant advantage. \n- Strong understanding of software development lifecycle and QA methodologies. \n- Excellent problem-solving skills and attention to detail. \n- Strong communication and collaboration skills. \n- Ability to work independently and as part of a team.\n\nWhy you\'ll love working here\n- We are certified the Great Place to Work 2024-2025.\n- Hackdays for self-studying and researching any IT-related subjects.\n- 5 working days/week with flexible working time and no overtime.\n- Annual unforgettable company outing.\n- International, professional, creative working environment and talented teams.\n- Onsite opportunities in Europe and US.\n- Common cultural-sportive- art Clubs and activities, sponsored and/or supported by the Company (Ex: Football, GYM, Swimming, Guitar, English…).\n- Powerful workstation: Core i7-9700, 16-32 GB RAM, 02 x QHD 2560x1440 monitors (2K resolution).\n- 100% official salary during the probation period, 13th month salary, annual salary raise.\n- Up to 03 extra paid-leave days per year.\n- Social, Health and Unemployed Insurance are based on 100%.\n- Gross salary and fully paid by Company.\n- Extra bonus at $ 60 per special occasions (Birthday, Labor Day, National Day, Solar New year, Lunar New Year).\n- Lunch allowance at $30 per month.\n- Baby allowance for a child under 03 years old is $ 12 per month.\n- AON Premium Healthcare Insurance package for employees and their children up to 18 years old.\n- Daily various foods, drink, and seasonal fresh fruits.\n- And many other benefits, let\'s join us to discover!  \n\nOptimizely is committed to a diverse and inclusive workplace. \nOptimizely is an equal opportunity employer and does not discriminate on the basis of race, national origin, gender, gender identity, sexual orientation, protected veteran status, disability, age, or other legally protected status.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '165 Thái Hà, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(661, 476, 2, 'Junior/Mid Fullstack Engineer (TypeScript/JavaScript)', 'Welcome to SMG Vietnam!\nSMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nThis job refers to our Real Estate brands,  and , the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing.\n\nWe are looking for a Junior/Mid Fullstack Engineer to help us build the future of the Swiss real estate market by contributing to our cutting edge, cloud based, technology stack. You will get to collaborate and access the wealth of knowledge and experience from a community of amazing engineers who come from all parts of the globe and are ready to share their expertise and aid you in your path to fulfilling your potential.\n\nJoin our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nOur tech stack\nFrontend: Vue.js with TypeScript\nBackend: Node.js and TypeScript, following a serverless microservices architecture in an AWS cloud environment (Lambda, DynamoDB, SQS, SNS, S3, etc.)\nMonitoring: Datadog\nDocumentation: Backstage\nLearn more about us and our engineering practices in our blog at \n\nYour Mission :\nBuilding and experimenting: Writing clean, modular code within a modern, serverless architecture, with a focus on refining and experimenting with functionality.\nCollaborating and creating: Working closely with a talented team of engineers to design, develop, and deliver features that make a real impact on users.\nLearning and applying: Gaining hands-on experience with AWS Serverless, CI/CD, and other cutting-edge tools like AI/Datalake, continuously enhancing skills along the way.\nContributing to innovation: Bringing fresh ideas to improve both software and processes, always looking for opportunities to push boundaries.\nYour responsibilities will evolve as we grow.\n\nWhat will you bring to the ride?\nFluent in English, both written and spoken.\nBachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience.\n1+ years of experience in Software Development.\nExperience with TypeScript/JavaScript, with proficiency in at least one of the following:\nComfortable with Vue.js or React.js, and capable of building modern web applications.\nExperience with Node.js backend development, including implementing synchronous and asynchronous services.\nSome exposure to AWS services and a Serverless Technology Stack.\nStrong sense of ownership and responsibility for what the team builds. Before blindly adding code to a codebase, be able to identify problematic areas and refactor them with maintainability and stability in mind.\nCurious, open-minded, and enthusiastic about growing in a collaborative team environment.\nAbility to use AI tools to assist with coding is a plus.\n\nWhy you\'ll love working here\nAttractive salary you’ll love!!!\nFull salary in probation\n13th-month bonus, Annual bonus from Profit Growth Sharing Plan\n21+ annual paid days off\n24 paid days equivalent per year for learning & knowledge sharing activities\nFull contribution to social insurance\nPremium private insurances coverage for you and your family members\nPersonal development plan and yearly budget for educational courses, and conferences, aiming to grow both your soft and hard skills\nClear Career Growth Framework and Supports\nAssistance and support through all aspects of the onboarding process\nLots of team activities and regular Hackathons\nAnnual Trips to Switzerland and other European countries\nFlexible working time\nHybrid working model (home office and in-office)\n40 hours per week, Mon-Fri, No OT\nModern Macbook laptops\nFree food, Sports Clubs, Monthly Townhall and frequent engagement activities\nWork in an open-minded, friendly, positive, transparent, and agile environment.\nAPPLY NOW, SO A GREAT CAREER OPPORTUNITY WON\'T BE MISSED!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Tower, 285 CMT8, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(662, 477, 2, 'Database Administrator(CSDL, Oracle, Banking)', 'Top 3 reasons to join us\n\n1. Lương/ thưởng hấp dẫn\n2. Cơ hội thăng tiến nghề nghiệp cao\n3. Môi trường làm việc thân thiện, năng động\n\nJob description\n\n- Tiếp nhận và xử lý yêu cầu lv2 liên quan đến cơ sở dữ liệu/hệ thống ETL dữ liệu\n- Housekeeping dữ liệu, đảm bảo tính toàn vẹn và an toàn dữ liệu\n- Tiếp nhận bàn giao vận hành các hệ thống cơ sở dữ liệu\n- Thực hiện cập nhật bản vá lỗi, bản vá điểm yếu an toàn thông tin, nâng cấp phiên bản cơ sở dữ liệu/hệ thống ETL dữ liệu\n- Viết tài liệu hướng dẫn, kiểm tra thực hiện các công việc vận hành cơ sở dữ liệu/hệ thống ETL dữ liệu\n- Xử lý các sự cố phát sinh liên quan đến cơ sở dữ liệu/hệ thống ETL dữ liệu\n- Cấu hình các giải pháp nâng cao tính sẵn sàng và phục hồi thảm họa cho cơ sở dữ liệu\n- Đánh giá định kỳ, lên phương án tối ưu hiệu năng cơ sở dữ liệu/hệ thống ETL dữ liệu\n- Tham gia góp ý, đề xuất thiết kế hệ thống cơ sở dữ liệu cho các giải pháp phần mềm chuẩn bị triển khai\n- Đề xuất, thực hiện quy hoạch, thiết kế hệ thống cơ sở dữ liệu đảm bảo tối ưu hóa tài nguyên hạ tầng, nâng cao hiệu năng hệ thống ứng dụng, đảm bảo tính sẵn sàng và phục hồi thảm họa của cơ sở dữ liệu\n- Tối ưu và tự động hoá vận hành cơ sở dữ liệu/hệ thống ETL dữ liệu\n- Tham gia xây dựng, đề xuất điều chỉnh quy trình quản trị cơ sở dữ liệu và các tiêu chuẩn cấu hình cơ sở dữ liệu\n- Báo cáo cho ban giám đốc về các hoạt động của hệ thống cơ sở dữ liệu\n\nYour skills and experience\n\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Toán tin…\n- Ít nhất 5 năm ở vị trí quản lý và vận hành cơ sở dữ liệu\n- Có kinh nghiệm làm việc theo các quy trình, tiêu chuẩn quản lý cơ sở dữ liệu và ứng dụng\n- Có chứng chỉ về CSDL: OCA/OCP/MSSQL…\n- Có chứng chỉ Cloud Azure/Google/AWS là một lợi thế\n- Làm việc với hạ tầng và hệ điều hành đa dạng Windows Server, AIX, Solaris, Linux,…\n- Làm việc với các hệ thống HA, DC/DR (Active-Active, Active-Passive)\n- Mức độ thành thạo các hệ quản trị CSDL quan hệ Oracle, MS SQL Server, MySQL, PostgreSQL…\n- Đánh giá và tuning hiệu năng CSDL.\n- Có khả năng thiết lập tự động hoá trong vận hành, thiết kế CSDL, xây dựng tài liệu, đọc hiểu mã nguồn PL/SQL, T-SQL\n- Có kiến thức/ Hiểu biết về bảo mật trong CSDL\n- Có kiến thức và khả năng vận hành các hệ quản trị CSDL NoSQL là một lợi thế\n- Có Kiến thức/ Hiểu biết về xử lý dữ liệu lớn là một lợi thế.\n- Có hiểu biết và vận hành tốt các hệ thống ETL dữ liệu là một lợi thế\n- Có hiểu biết và vận hành tốt các hệ thống trên nền tảng container (Docker, K8s…) và Cloud là một lợi thế.\n\nWhy you\'ll love working here\n\n**Lương và phúc lợi hấp dẫn:**\n- Mức lương cạnh tranh, phản ánh trực tiếp kỹ năng và kinh nghiệm của ứng viên (chi tiết sẽ được thảo luận trong buổi phỏng vấn)\n- 13 ngày nghỉ phép linh hoạt, bao gồm ngày sinh nhật và các dịp quan trọng khác\n- Bảo hiểm đầy đủ theo luật lao động, cùng với ABBANK CARE - chương trình phúc lợi bổ sung đặc biệt dành cho ABBankers\n- Lãi suất vay ưu đãi - Quyền lợi đặc biệt dành cho nhân viên ABBANK\n\n**Cơ hội phát triển nghề nghiệp hấp dẫn:**\n- Gia nhập các dự án chuyển đổi quy mô lớn, cộng tác cùng các chuyên gia hàng đầu để áp dụng công nghệ mới nhất trong ngành ngân hàng\n- Lộ trình phát triển sự nghiệp rõ ràng, được tạo điều kiện cho cả sự phát triển kỹ thuật và quản lý\n- Hỗ trợ đào tạo và chứng chỉ trong lĩnh vực IT, ngân hàng/tài chính\n\n**Môi trường làm việc năng động:**\n- Mô hình làm việc linh hoạt, trẻ trung, khuyến khích đổi mới và sáng tạo\n- Văn phòng được trang bị hiện đại, kèm theo các thiết bị tiên tiến nhất dành cho nhân viên\n- Tổ chức thường xuyên các hoạt động ngoại khóa (team building, hội thảo, và các sự kiện văn nghệ), tạo điều kiện cho nhân viên gắn kết và phát triển.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '36 Hoàng Cầu, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(663, 302, 2, 'IT System Admin (Cloud Storage, Ceph, Linux)', 'Top 3 reasons to join us\n- Flexible working hour\n- Private health care insurance \n- Premium annual health care check\n\nJob description\n● Deploy, configure and expand Ceph clusters (OSD, MON, MGR, RGW)\n● Monitor cluster health, performance and capacity; remediate issues\n● Set up systems and services as per Dev and QA requests\n\nYour skills and experience\nRequired Qualifications:\n● 5 years of experience administering large-scale Linux environments in production\n● At least 2 years of hands-on experience designing, deploying, and operating Ceph\nstorage clusters in an enterprise or service-provider setting\n● Strong Linux sysadmin skills (RHEL/CentOS or Ubuntu)\n● Scripting/automation with Bash, Python or Ansible\n● Solid TCP/IP networking (VLANs, jumbo frames, LACP)\n● Experience with Prometheus/Grafana or equivalent monitoring\n● Good English\n\nDesired Qualifications:\nAny item below would be a plus:\n● Ceph Certified Administrator (RHCE-Ceph) or similar\n● Virtualization experience: VMware, Proxmox, Hyper-V\n● Cloud management experience (AWS / Azure / Google Cloud)\n\nGiven the high volume of CVs applied, we can only manage to respond to candidates whose profiles aligns with the position within 5 working days. We appreciate your understanding and enthusiastic towards our company.\n\nWhy you\'ll love working here\nThe Nakivo team in Vietnam has been changing very fast in the recent years, we have grown from a group of 6 engineers to the current team size of 80 and we are expecting to grow even more in the next following years. We welcome and embrace people, regardless of their background, religion, nationality or gender, but focus on diversity, contribution, determination and work ethic. At Nakivo, we are trying to improve everyday, to become a competitive choice for talented people, by offering\n- Flexible working hours: Office opens from 6.00 AM to 10.00 PM\n- 13-month bonus & performance bonus\n- 100% salary on probationary period\n- Private health care package\n- Healthcare package for family members\n- Premium health care check\n- Gift (cash/voucher) for every special occasion: New Year\'s Eve, Tet holidays, International Women\'s Day, International Children\'s Day, Mid-Autumn Festival and Birthday\n- Up to 18 annual leaves/year, 5 sick leaves and additional leaves (up to 3 days)\n- Team building\n- Free and un-limited snack, tea, coffee and by-choice request.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '16 Le Quy Don, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(664, 408, 2, 'Technical Architect (Azure, .NET, English)', 'We are seeking a highly skilled and forward-thinking Technical Architect to join our team. You will play a key role in shaping the technical direction of our projects, contributing to architecture design, and ensuring solutions are scalable, secure, and future-ready.\n\nRole Responsibilities\n- Participate in architecture design with scalability, performance, security, and easy maintenance, and create development environments along with the client\'s architects.\n- Transform the architectural design of the application into a framework.\n- Provide in-depth technical and hands-on leadership and guidance to the development & support team, ensuring alignment with project goals and objectives.\n- Lead code reviews, design discussions, and technical planning sessions to drive continuous improvement.\n- Manage the development process to ensure that design and coding standards are being followed, application requirements are fully implemented, technologies are efficiently and correctly implemented, and a high level of maintainability and extensibility is achieved.\n- Support for development and bug fixes. Respond to user-reported issues, troubleshoot technical problems, and provide timely resolutions.\n- Investigate and diagnose software defects, identifying root causes and implementing effective fixes.\n- Collaborate with cross-functional teams, including designers, product managers, and other developers, to deliver high-quality technical solutions.\n\nYour skills and experience\n- Bachelor’s degree in computer science, software engineering, or a related field.\n- 7+ years of relevant experience in the IT industry and at least 2 years in Technical Architect role.\n- Solid technical background with good knowledge in OOP & SOA principles, design patterns, and industry best practices for software development following Agile methodology.\n- Proven experience in a Technical Architect role for mobile and enterprise applications, with demonstrated ability to guide and mentor a development team and handle day-to-day activities.\n- Strong experience in React, .NET framework, Azure Application Services, Azure Integration Services, and Azure SQL development to develop enterprise applications.\n- Experience in Azure LLM, LangGraph is a plus.\n- Strong analytical and troubleshooting skills.\n- Ability to work effectively in a fast-paced, dynamic environment.\n- Excellent interpersonal, English oral & writing communication skills and ability to effectively collaborate with diverse people such as clients, developers, quality assurance, subject matter experts, and architects.\n\nWhy you\'ll love working here\nWhy Join Us?\n- Competitive salary + performance bonus + 13th-month salary (pro-rata).\n- Full benefits during probation, including meal and parking allowances.\n- Generous leave policy: 16 annual leave days, including 11 Vietnam holidays, 4 sick days, and 1 birthday leave.\n- Opportunities for growth: technical seminars, certifications, and career development.\n- Fun, collaborative culture with events like hackathons and team-building activities.\n- Work-life balance with a 40-hour workweek (Mon-Fri).\n\nRecruitment Process\nWe follow a simple, transparent 3-step recruitment process:\n- Application Review: Submit your resume. Shortlisted candidates will be contacted within 5 business days.\n- Interview: A technical and behavioral interview (virtual or in-person) to assess your skills and cultural fit.\n- Final Decision: Feedback and offer rollout within 1-2 weeks after the interview.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà B1, UEH Campus B, 279 Nguyễn Tri Phương, Phường 5, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(665, 284, 2, 'Data Analytics Specialist (SQL, Oracle, Python)', 'The Data Analytics Specialist for Andros Vietnam, based in Thao Dien District, is responsible for organizing data related to sales numbers, market research, logistics, linguistics, or other behaviors. They utilize technical expertise to ensure data is accurate and high-quality. Data is then analyzed, designed, and presented in a way that assists individuals, businesses, and organizations make better decisions.\nUsing automated tools to extract data from primary and secondary sources.\nRemoving corrupted data and fixing coding errors and related problems.\nDeveloping and maintaining databases, data systems – reorganizing data in a readable format.\nPerforming analysis to assess quality and meaning of data.\nFilter Data by reviewing reports and performance indicators to identify and correct code problems.\nUsing statistical tools to identify, analyze, and interpret patterns and trends in complex data sets that could be helpful for the diagnosis and prediction.\nAssigning numerical value to essential business functions so that business performance can be assessed and compared over periods of time.\nAnalyzing local, national, and global trends that impact both the organization and the industry.\nPreparing reports for the management stating trends, patterns, and predictions using relevant data.\nWorking with programmers, engineers, and management heads to identify process improvement opportunities, propose system modifications, and devise data governance strategies.\nPreparing final analysis reports for the stakeholders to understand the data-analysis steps, enabling them to take important decisions based on various facts and trends.\n\nYour skills and experience:\nAt least 2 years of experience as a Data Analyst Specialist in a related industry.\nStrong mathematical skills to help collect, measure, organize and analyze data.\nKnowledge of programming languages like SQL, Oracle, R, MATLAB, and Python.\nTechnical proficiency regarding database design development, data models, techniques for data mining, and segmentation.\nExperience in handling reporting packages like Business Objects, programming (JavaScript, XML, or ETL frameworks), databases.\nProficiency in statistics and statistical packages like Excel, SPSS, SAS to be used for data set analyzing.\nAdept at using data processing platforms like Hadoop and Apache Spark.\nKnowledge of data visualization software like Tableau, Qlik.\nKnowledge of how to create and apply the most accurate algorithms to datasets in order to find solutions.\nGreat organizational and time management skills.\nExceptional interpersonal, collaboration, and communication abilities. A team player with good social skills.\nExcellent analytical and problem-solving skills.\nPrecise with deadline, detailed at work, flexible, service-oriented, and customer-driven.\nPassionate with Database creation, procedure, reporting, statistics.\nProactive, responsible, and reliable.\nEnthusiastic and eager to learn.\nFluent in English, French is a plus.\n\nWhy you\'ll love working here:\nCompetitive salary and benefits.\nFull social and other insurances.\nFast-growing working environment delivering perfect opportunities for self-development and autonomous capacity.\nRich interaction with many different departments in the company, allowing everyone to cultivate experiences thoroughly.\nDynamic and inclusive working environment where all ideas are welcome and discussed. ✓ Flexible working hours.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 9, Tòa nhà Phụ nữ, 20 Nguyễn Đăng Giai, Thảo Điền, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(666, 232, 2, 'Product Manager (English)', 'As a Senior Product Manager, you will be part of the Regional PMO Team in defining the product vision and ensuring that the product supports the company’s overall strategy and goals. You will also be heavily involved in the Product Lifecycle, which includes gathering and prioritizing requirements and working closely with stakeholders and partners/vendors to ensure revenue and customer satisfaction goals are met.  \n\nResponsibilities:\n• Work closely with the Head of PMO to define product strategy and roadmap\n• Manage the Vietnam PMO Team, including Product Managers, Business Analysts, and QA Testers.\n• Liaise with Technical Team to ensure deliverables are delivered on time and within resources allocated (eg: provide Business Unit testing support, ensure all pre-implementation activities are completed, provide post-implementation support of the product)\n• Ensure Business/Product Requirements Documents (BRDs/PRDs) adhered to business requirements, and are reviewed and sign-off by business Units  \n• Manage stakeholders’ expectations, provide regular project updates.  \n• Provide leadership and guidance to Team members, promoting a collaborative and high-performing Team  \n• Work with internal/external parties to assess partnerships and licensing opportunities.\n\nRequirements:\n• Bachelor\'s degree in business informatics, business, or a related field.\n• Minimum 5 years experience as a Product Manager or in Project Management roles.\n• Fluent English\n• Experienced in seeing Products through the full life cycle.  \n• Experience in stakeholders’ management and vendor management skills.\n• Proven track record in defining and launching medium to large scale products successfully\n• Analytical mindset with a strong ability in decision making and problem solving\n• Excellent written and verbal communication skills.  \n• Good working experience in Waterfall/Agile methodologies, and using tools such as JIRA and Confluence  \n• PMP or equivalent certification is preferred.\n\nWhy you\'ll love working here:\n• A young and dynamic team where you can develop your career path and improve your English skills\n• An exciting project which uses cutting-edge technology\n• 18 days annual leave per year\n• 13th-month salary\n• Private insurance for employees. After 1 year, company will cover the insurance for family members (spouse, children)\n• Providing Laptop to work\n• Company trip \n• Annual health check \n• Monthly teambuilding activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1st Floor, L’Mak Plaza (Nam A Plaza), 127 Hong Ha, Ward 09, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(667, 338, 2, 'Trưởng Phòng Phần Mềm (Technical Manager)', 'Job description\n- Lập kế hoạch triển khai công việc: Xác định thời gian, nguồn lực, và phạm vi dự án, phân chia giai đoạn, xác định các mốc kiểm tra, và lên kế hoạch chi tiết cho từng giai đoạn\n- Phân công nhiệm vụ: Giao nhiệm vụ cho các thành viên trong phòng, chỉ định người chịu trách nhiệm cho từng mảng công việc, và đảm bảo mỗi thành viên hiểu rõ vai trò và trách nhiệm của mình trong dự án.\n- Hỗ trợ đội ngũ: Cung cấp hướng dẫn kỹ thuật, đảm bảo các thành viên có đủ kiến thức và kỹ năng để hoàn thành nhiệm vụ, giải đáp thắc mắc và hỗ trợ khi cần thiết.\n- Tổ chức họp định kỳ: Tổ chức các cuộc họp định kỳ để theo dõi tiến độ, cập nhật thông tin, giải quyết vấn đề, và đánh giá hiệu quả công việc.\n- Đánh giá hiệu suất: Thực hiện đánh giá hiệu suất công việc của các thành viên trong đội, ghi nhận thành tích và chỉ ra những điểm cần cải thiện.\n- Báo cáo tiến độ: Lập báo cáo tiến độ dự án định kỳ, cung cấp thông tin về tiến độ công việc, vấn đề phát sinh, và đề xuất giải pháp cho cấp quản lý cao hơn.\n- Tư vấn Ban lãnh đạo về các rủi ro, đề xuất sáng kiến trong công tác triển khai công việc.\n- Phối hợp với các bộ phận khác: Làm việc chặt chẽ với các bộ phận khác trong công ty, như kinh doanh, sản phẩm, hoạch định, kiểm thử, v.v., để đảm bảo công việc được thực hiện một cách hiệu quả và đồng bộ.\n- Đào tạo và phát triển đội ngũ: Tổ chức các buổi đào tạo, chia sẻ kiến thức và kinh nghiệm, và hỗ trợ phát triển kỹ năng của các thành viên trong đội.\n- Kiểm soát chất lượng phần mềm: Hợp tác với nhóm kiểm thử và đảm bảo chất lượng (QA) để kiểm tra chức năng, hiệu năng, và bảo mật của sản phẩm trước khi triển khai.\nYour skills and experience\n- Tốt nghiệp Đại học trở lên Ngành Công nghệ thông tin hoặc các ngành liên quan khác\n- Độ tuổi: 30 – 45 tuổi\n- Ít nhất 3 năm ở vị trí quản lý cấp độ phòng trở lên và quản lý ít nhất 5 nhân viên và ít nhất 6 năm làm việc trong lĩnh vực phát triển phần mềm.\n- Có kinh nghiệm, kiến thức chuyên sâu về các ngôn ngữ lập trình, kiến trúc hệ thống, cơ sở dữ liệu, bảo mật, công nghệ AI và các công nghệ khác liên quan đến phát triển phần mềm.\n- Có kinh nghiệm xây dựng, triển khai các giải pháp liên quan đến thanh toán, thương mại điện tử, tích điểm, chăm sóc khách hàng, dịch vụ 24/7 cho khách hàng là 1 lợi thế\n- Kỹ năng chuyên môn và công cụ hỗ trợ:\n  - Khả năng phân tích và đưa ra giải pháp kỹ thuật hiệu quả\n  - Am hiểu về quy trình phát triển phần mềm Agile/Scrum\n  - Kiểm soát chất lượng phần mềm, đảm bảo hiệu suất và bảo mật\n  - Kỹ năng quản lý dự án và phân bổ nguồn lực\n- Kỹ năng mềm:\n  - Kỹ năng lãnh đạo và quản lý đội ngũ\n  - Kỹ năng giải quyết vấn đề\n  - Khả năng phân tích và đưa ra giải pháp kỹ thuật hiệu quả\n  - Cẩn trọng, tinh thần sáng tạo và đam mê với công nghệ\nWhy you\'ll love working here\n1. Lương: Lương thoả thuận theo năng lực và kinh nghiệm\n2. Thưởng: Theo quy định của Công ty.\n   - Thưởng năm: định mức 01 tháng lương 13 theo thâm niên và thưởng thêm theo kết quả công việc\n   - Thưởng lễ Tết (08/03, 20/10, 30/04 và 01/05, 02/09, 1/1, ...)\n3. Phúc lợi:\n   - Du lịch hàng năm\n   - Bảo hiểm xã hội, y tế theo luật định.\n   - Khám sức khỏe định kỳ 06 tháng/1 lần\n   - Nghỉ thứ Bảy và Chủ nhật.\n   - Môi trường làm việc chuyên nghiệp, năng động, sáng tạo và luôn được khuyến khích cải tiến.\n   - Được đào tạo Nghiệp vụ và Kỹ Năng liên tục, có cơ hội thăng tiến lên các vị trí cao hơn.\n   - Cơ sở vật chất, công cụ làm việc hiện đại, tiện nghi, ứng dụng công nghệ, chuyển đổi số\n   - Cơ hội làm việc và phát triển tại Công ty công nghệ sáng tạo trong lĩnh vực thương mại điện tử, loyalty, ví điện tử, truyền thông, dịch vụ giá trị gia tăng, truyền thông…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ICOM Building, số 17/93 Trần Thái Tông, Dịch Vọng, Cầu Giấy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(668, 238, 2, 'Quality Assurance (QA) Manager', 'Top 3 reasons to join us\n• Mức lương cạnh tranh, hấp dẫn\n• Môi trường làm việc chuyên nghiệp, thân thiện\n• Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n• Xây dựng tiêu chuẩn chất lượng dịch vụ Công nghệ thông tin\n• Xây dựng, cải tiến các quy trình, quy định về dịch vụ Công nghệ thông tin\n• Giám sát và có phương pháp cải tiến liên tục để nâng cao chất lượng dịch vụ Công nghệ thông tin\n• Tuyển dụng, đào tạo, quản lý, phát triển nhân sự\n\nYour skills and experience\n• Tốt nghiệp đại học chính quy các trường Đại học chuyên ngành: CNTT, điện tử, toán tin, tài chính, ngân hàng\n• Hiểu biết quy trình, quy định phát triển phần mềm\n• Có ít nhất 7 năm kinh nghiệm phát triển phần mềm\n• Hiểu biết sâu sắc về tiêu chuẩn chất lượng dịch vụ CNTT\n  • Có ít nhất 5 năm kinh nghiệm QA\n  • Có ít nhất 3 năm kinh nghiệm với vai trò Quản lý cấp tương đương.\n• Ưu tiên: Có Kinh nghiệm BA/Test.\n• Ưu tiên: Có Kinh nghiệm tại ngân hàng.\n• Ưu tiên: Có chứng chỉ QA theo thông lệ Quốc tế (ISO, CMMI, ITIL)\n\nWhy you\'ll love working here\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n• Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n• Du lịch nghỉ dưỡng hàng năm\n• Khám sức khỏe định kỳ\n• Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n• Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương  \nCơ hội nghề nghiệp và phát triển bản thân:\n• Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng  \n• Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng  \n• Được trải nghiệm các phương pháp học tập  mới và phát triển năng lực theo lộ trình công danh.  \n• Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\nMôi trường làm việc lý tưởng với:\n• Những người cộng sự thân thiện và tài năng  \n• Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(669, 184, 2, 'Expert, Customer Experience Design', '- The job holder is responsible for ensuring a customer-centric approach, delivering a smooth and consistent customer experience across all touchpoints throughout their journey with the bank.\n- The job holder will design, develop and implement changes to drive a differentiating customer experience and improve customer engagement within target customer segments.\n\nKey Accountabilities (1)\nCustomer Experience Design\n- Lead squads to identify new data insights that can be used to enrich the customer journey for better customer experience.\n- Implement dynamic framework of system driven triggers and draft a roadmap of customer life stage events to support holistic engagement of customers.\n- Lead squads in identifying existing process inefficiencies as well as methods to save costs and improve user experience.\n- Develop, implement and analyze feedback channels to identify pain points, define short term action points and permanent fixes to remove pain points.\n- Implement tools and skillsets to plan, design and facilitate improvement workshop for projects / initiatives / process mapping, storyboarding, user persona, cost-impact analysis.\n\nKey Accountabilities (2)\nManaging Projects\n- Manage project conflicts, challenges and dynamic business requirements to keep operations running at high performance.\n- Work with team leads to resolve people problems and project roadblocks, conduct root cause analysis to help squads continuously improve their practices to ensure maximum productivity.\n\nKey Accountabilities (3)\nManaging Stakeholders\n- Interface with stakeholders to understand pain points and gather inputs from data specialists to derive features development and enhancements on product.\nManaging Talent\n- Develop and coach more junior employees to identify gaps in their competencies and build development plans.\n\nKey Relationships - Direct Manager Director, Customer Experience Design\nKey Relationships - Direct Reports\nKey Relationships - Internal Stakeholders Cross functional team members within Disvision and across Divisions\nKey Relationships - External Stakeholders Partners providing professional services\n\nYour skills and experience\n- Bachelor\'s or Master\'s Degree in a technical or business management discipline\n- 6 Sigma certification (preferred)\n- 5 years of relevant experience in a financial institution\n- Experience in working with clients and designing customer journeys\n- Experience in product management or customer segment management\n- Strong understanding of Agile principles, practices and Scrum methodologies.\n- Experience working in Agile teams to support digital transformation projects.\n- Experience in process improvement and LEAN thinking methodologies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 23 Lê Duẩn, phường Bến Nghé, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(670, 439, 2, 'DevOps Engineer (Python, AWS, Linux)', 'Techcom Securities (TCBS) đang tìm kiếm một số kỹ sư DevOps để tham gia bộ phận CNTT của chúng tôi tại văn phòng Hà Nội. Ứng viên sẽ quản lý và tự động hóa các quy trình triển khai của công ty bằng cách sử dụng các kỹ thuật Continuous Integration và Continuous Delivery.\n\nĐây là cơ hội để bạn trở thành một thành viên trong đội ngũ ngân hàng đầu tư sáng tạo và uy tín hàng đầu Việt Nam! Nơi làm việc: Hà Nội, Việt Nam.\n\nTrách nhiệm bao gồm, nhưng không giới hạn:\n- Tự động hóa và quản lý các quy trình triển khai bằng cách sử dụng kỹ thuật Continuous Integration và Continuous Delivery.\n- Chuẩn hóa môi trường làm việc từ Dev/Test cho đến production. - Quản lý máy chủ, ứng dụng và tất cả các phần mềm nội bộ được công ty sử dụng.\n- Giám sát tính hiệu quả của hệ thống và thực hiện điều chỉnh nếu cần thiết.\n- Phác thảo cấu hình cơ sở hạ tầng hệ thống - DevOps Engineer phải tham gia ngay vào giai đoạn phát triển sản phẩm.\n- Tham gia vào các cảnh báo hệ thống trên cơ sở trực tiếp.\n- Luôn tìm kiếm các phương pháp kỹ thuật tốt nhất trong và ngoài nước.\n- Làm việc trực tiếp với team phát triển để build và quản lý môi trường lập trình, kiểm thử, tích hợp CI/CD, thúc đẩy văn hoá DevOps trong team.\n\nYour skills and experience:\n- Cử nhân hoặc Thạc sĩ về CNTT & Công nghệ hoặc lĩnh vực liên quan.\n- Kinh nghiệm về viết mã/mã hóa (ví dụ: Go, Python, Bash).\n- Có kinh nghiệm với các phần mềm CI/CD (ví dụ: Gitlab CI, Jenkin).\n- Có kinh nghiệm với các dịch vụ đám mây như Microsoft Azure, Amazon AWS (Amazon).\n- Có kinh nghiệm với các dịch vụ như Docker, Kubernetes, v.v.\n- Có kinh nghiệm với các công cụ tự động hóa / dàn dựng và các hệ thống quản lý cấu hình như Ansible, SaltStack, CloudFormation, Puppet, v.v.\n- Đã từng làm trên hệ thống giám sát như ELK.\n- Có hiểu biết về các giải pháp giám sát như Prometheus, Grafana, checkmk, ... là một lợi thế.\n- Có thế mạnh về các kỹ năng quản trị Linux - Là người có trách nhiệm, cẩn thận, toàn vẹn, khả năng giao tiếp tốt và thái độ trung thực.\n- Cài đặt và sử dụng vài Web Server phổ biến như: Apache và Nginx.\n- Tìm hiểu một số khái niệm và chức năng thường được sử dụng: Caching Server, Load balancer, Reverse Proxy, and Firewall.\n- Tối thiểu 6 tháng làm việc trong lĩnh vực CNTT với vai trò DevOps vận hành các công cụ jenkins, jira, git (Gitlab, Bitbucket…), hệ điều hành Linux, Windows Server.\n\nWhy you\'ll love working here:\n- Review lương 1 lần/ năm.\n- Cán bộ nhân viên sẽ có từ 12- 15 ngày phép/ năm.\n- Bảo hiểm AON cho Cán bộ nhân viên.\n- Công ty có các CLB thể thao sinh hoạt hàng tuần (đá bóng, chạy bộ, cầu lông).\n- Team building 1 lần/ 1 năm theo tiêu chuẩn 5 sao.\n- Môi trường làm việc trẻ, năng động, cơ hội phát triển cao.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'C5 Building Tower, D’Capitale Tower, 119 Tran Duy Hung, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(671, 245, 2, 'IT Project Manager', 'We are looking for an experienced and technically strong IT Project Manager to join LG CNS Vietnam Build Center. As a PM, you will be responsible for managing software development projects for global clients (mainly Korean and international enterprises). A solid technical foundation in mobile or web development is required to effectively lead the development team and communicate with stakeholders.\n\nManage the end-to-end lifecycle of IT projects including planning, execution, monitoring, and delivery.\nLead and coordinate a cross-functional development team including developers, testers, and business analysts.\nWork closely with clients and LG CNS Korea HQ to gather requirements, define scope, and align expectations.\nEnsure projects are delivered on time, within scope, and within budget.\nIdentify project risks and develop mitigation plans.\nEnsure high quality of deliverables by managing code quality, testing, and deployment processes.\nPrepare and maintain all project documentation (project plans, reports, meeting minutes, etc.)\nMentor and guide junior team members.\n\n[Required]\nBachelor\'s degree in information technology, Computer Science, or related field.\nAt least 5 years of experience in software development and 3+ years in project management roles.\nStrong technical background with hands-on experience in at least one of the following:\niOS (Swift/Objective-C)\nAndroid (Kotlin/Java)\nJava (Spring Framework, J2EE)\n.NET (C#, ASP.NET, .NET Core)\nExperience in Agile/Scrum or Waterfall project management methodologies.\nGood communication and leadership skills.\nFluent in English (both written and spoken).\n\n[Nice to have]\nExperience working with Korean clients or in Korean companies.\nPMP, Scrum Master, or other PM certifications is a plus.\nExperience managing offshore or distributed teams.\nKorean language proficiency is a strong advantage.\n\nWhy you\'ll love working here\n- Best remuneration: Periodically review and adjust salary once a year, PI bonus twice a. Allowances for lunch, transportation, and phone charges. Party with the team once a. Workshop travel for the whole company once a year. Bonuses/Gifts for holidays, International Labor Day, International Women\'s Day, etc.\n- High-class, modern office: 5-star standard office with modern equipment, large rest and entertainment areas (game area, karaoke room, reading room, cafe counter, snack bar, etc.) Meet all members\' needs, especially the office has an airy and beautiful view that is among the most beautiful in Hanoi.\n- Top equipment: Each employee is equipped with the latest generation LG Gram laptop and modern large LG screen.\n- Best working time: Work 8 hours/day (8:00 ~ 17:00), from Monday to Friday. No pressure to work overtime/weekends!\n- Flexible, youthful working style: LG CNS Vietnam members are mostly from the 9-10x generation, with a youthful, modern, and fair working style!\n- Creative environment, valuing individual opinions: With a young and talented team, we always appreciate the creativity and suggestions that members make.\n- Opportunities to work/study in Korea and abroad: With customers and projects mostly from abroad, your opportunities for training and onsite abroad will always be open!\n- Other: Happy hours every Friday, Team outing monthly, join clubs like football, badminton, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(672, 398, 2, 'Senior Angular Developer (Typescript, UI, English)', 'We are looking for a talented Senior Angular Developer to join our software development team. You will participate in international projects, developing high-quality user interfaces, integrating with backend systems, and ensuring optimal performance for our products. Open for both Fresher and Experienced candidates who are passionate about web technologies and eager to grow in a dynamic and professional environment.\n\nFor Fresher-level candidates, we offer a clear training roadmap and hands-on mentorship to help you build strong foundations and grow your career.\n\n1. Technical Skills\nExperience:\n• Minimum 3–5 years of experience in software development using Angular.\n• Hands-on experience in real-world projects utilizing the Angular framework, UI development, and backend API integration.\nFrontend Development:\n• Proficient in AngularJS/Angular, TypeScript, JavaScript, HTML5, CSS3, and libraries like RxJS, NgRx.\n• Strong understanding of Object-Oriented Programming (OOP) and the MVC pattern.\n• Skilled with tools such as Webpack, Angular CLI, and package managers (npm, yarn).\nIntegration & Development:\n• Experience working with RESTful APIs, GraphQL, or similar protocols.\n• Familiar with the Software Development Life Cycle (SDLC), including architecture design, unit/integration testing, and CI/CD deployment.\n• Ability to design responsive user interfaces and optimize web performance.\nNice-to-Have:\n• Experience with other frameworks such as React, React Native, Vue.js, or Node.js.\n• Knowledge of microservices, cloud services (AWS, Azure, Google Cloud), or backends like .NET, Java, Python.\n\n2. English Skills\n• Fluent in English (both spoken and written) to collaborate with international teams and clients.\n\n3. Soft Skills & Responsibilities\nTeamwork:\n• Work in Agile/Scrum teams alongside Scrum Masters and cross-functional development groups.\n• Participate in product design, technical assessments, and code reviews to ensure code quality.\nLeadership:\n• Capable of leading small teams, mentoring junior/mid-level developers, or acting as a Tech Lead.\n• Provide technical solutions, improve development processes, and ensure non-functional requirements are met.\nProblem-Solving:\n• Strong analytical thinking, system architecture design, and complex issue resolution.\n• Research and apply new technologies to enhance project outcomes.\n\n4. Education & Experience\n• Bachelor\'s degree in Information Technology, Computer Science, Software Engineering, or related fields.\n• 3–5 years of experience in technology companies, preferably with international or outsourcing environments.\n\n*** Application Requirements\n• Detailed CV outlining past experience and completed projects.\n• Relevant certifications (if available).\n\nWhy you\'ll love working here\nBenefits:\n• Working hours: 8:00 AM – 5:00 PM, Monday to Friday\n• Flexible working model: Mainly on-site, with remote work flexibility when needed (not a fully remote position)\n• Competitive Salary: 20 – 35 million VND/month\n• Full insurance in accordance with the law\n• Paid leave, 13th-month salary\n• Team building activities, skill development training\n• Professional and dynamic working environment with career growth opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '62 Đường số 6, KDC CityLand Park Hills, P 10, Go Vap, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(673, 478, 2, 'UI/UX Designer – Thoughtful Interfaces, Real Impact', 'We’re looking for a designer who cares deeply about user experience and builds intuitive, meaningful digital products. Join us to shape interfaces that not only look great but truly make a difference.\n\n- UI/UX design for the 6ixgo responsive web and hybrid app\n- Improve and enhance platform usability based on user behavior data\n- Create design content, banners, and social media visuals from a brand perspective\n- Design key visuals and icons for core platform features and develop corresponding design guidelines\n- Ensure compatibility across various device environments (PC / mobile web / app)\n\nYour skills and experience:\n- 3–5 years of experience in UI/UX design and planning for platforms or service-based products\n- Experience in creating design content and icons with consistent brand identity\n- Proficiency in tools such as Figma, Adobe XD, Photoshop, Illustrator, and Zeplin\n- Strong user-centered thinking and data-driven problem-solving skills\n- Proven collaboration and communication skills with planners, developers, and marketers\n- Portfolio submission required, including projects with over 60% personal involvement (Clearly describe the problem definition, design process, and final outcome)\n\nPreferred Qualifications:\n- Experience with responsive web and app-based design projects\n- Experience collaborating with global teams or the ability to communicate effectively in English\n\nWhy you\'ll love working here:\n- 13th month salary\n- 12 days annual leave per year\n- Full support for Vietnam’s mandatory social insurance (social, health, and unemployment insurance)\n- All standard Vietnam calendar holidays\n- Annual salary review\n- Great location with shops, restaurants, gym, cafes and swimming pool in the building.\n- Nice and friendly working environment.\n- Work directly with international clients.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'THE SUN AVENUE 28 Mai Chi Tho, An Phu Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(674, 186, 2, 'Client Developer (Unity, C#, JavaScript)', 'Xây dựng phát triển tính năng Gameplay như lập trình các cơ chế gameplay : di chuyển nhân vật, chiến đấu, thu thập vật phẩm, mini-game, AI đơn giản… Thực hiện theo thiết kế từ Game Designer\nTạo và quản lý các thành phần UI (menu, inventory, bảng điểm, HUD...) bằng Unity UI (uGUI) hoặc TextMeshPro.\nTrao đổi thông tin , Giao tiếp với Server (Backend)\nXử lý dữ liệu & lưu trữ cục bộ\nHiển thị đồ họa và hiệu ứng\nTích hợp SDK và nền tảng\nTối ưu hiệu năng\n\nYour skills and experience\nBắt buộc ứng viên sử dụng được Unity\nThành thạo C# và có thể sử dụng JavaScript\nBắt buộc có kinh nghiệm sử dụng công cụ Git, và có hiểu biết về CI/CD\nKinh nghiệm: từ 5 năm trở lên\nYêu cầu: Có portfolio kèm mã nguồn (code đính kèm để có thể đánh giá kĩ năng thực tế)\n\nTrong quá trình phỏng vấn:\nCó thể có bài thi tự luận về Design Pattern\nKèm bài kiểm tra lập trình (coding test)\nNhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nWhy you\'ll love working here\n✨ CHẾ ĐỘ PHÚC LỢI HẤP DẪN TẠI CÔNG TY ✨\nThu nhập cạnh tranh:\nMức lương hấp dẫn, thưởng tháng 13 và thưởng thâm niên.\nThưởng theo hiệu quả công việc, xét thưởng vào các dịp Lễ – Tết.\nĐánh giá tăng lương 1 lần/năm, trường hợp nổi bật sẽ được xét tăng lương ngay tại thời điểm.\nChế độ nghỉ phép:\n12 ngày nghỉ phép có lương mỗi năm theo quy định – nghỉ thoải mái, vẫn nhận lương đầy đủ.\nSự kiện nội bộ ấm áp:\nHàng năm tổ chức “Ngày hội gia đình” vào tháng 5, có quà tặng bằng tiền mặt dành tặng ông bà, cha mẹ, vợ/chồng và con cái của nhân viên – thể hiện sự trân trọng với cả gia đình bạn.\nChế độ quà tặng nhân dịp đặc biệt:\nTặng quà các ngày lễ: Tết Dương lịch, Tết Âm lịch, 30/4, Trung thu, 8/3, 20/10.\nCả nhân viên nam và nữ đều có quà.\nNhân viên chính thức trên 6 tháng được tặng quà sinh nhật trị giá 5 triệu đồng/người.\nThưởng hiệu suất riêng:\nNgoài lương chính còn có các khoản thưởng, bonus hàng tháng tùy theo đóng góp.\nHỗ trợ nơi ở:\nNhân viên ở xa được sắp xếp chỗ ở miễn phí, thuận tiện cho công việc.\nCơ hội học hỏi và phát triển:\nLàm việc cùng các chuyên gia hàng đầu trong nước và quốc tế.\nGiao lưu, học hỏi với đồng nghiệp quốc tế giúp cải thiện tiếng Anh và mở rộng tư duy toàn cầu.\nChăm sóc sức khỏe toàn diện:\nKhám sức khỏe định kỳ tại các bệnh viện quốc tế như BV Phương Đông.\nMiễn phí tiêm phòng HPV, cúm cho nhân viên.\nTrải nghiệm công tác và du lịch:\nCác chuyến công tác nước ngoài kết hợp du lịch, khám phá đặc sản và địa danh nổi tiếng.\nĐược tài trợ các hoạt động gắn kết team, học hỏi kiến thức lập trình qua các buổi giao lưu, workshop.\nVăn phòng hiện đại, tiện nghi:\nKhông gian làm việc rộng rãi, thoáng mát.\nCó bánh, trà, café phục vụ mỗi ngày.\nBữa trưa đầy đủ dinh dưỡng, ngon miệng dành riêng cho nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'B4-12 Vinhomes Gardenia Hàm Nghi, Đường Hàm Nghi, Phường Cầu Diễn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(675, 479, 2, '05 Middle/Senior Flutter Developer (Dart)', 'Top 3 reasons to join us\n- Xét tăng lương 2 lần/năm\n- Teambuilding hàng quý\n- Thu nhập: 13 tháng lương/năm\n\nJob description\n- Tham gia vào quá trình phát triển ứng dụng di động sử dụng Flutter framework \n- Tối ưu hóa hiệu suất và đảm bảo sự tương thích đa nền tảng \n- Đảm bảo chất lượng mã nguồn trong quá trình phát triển. \n- Sử dụng công cụ test để đảm bảo chất lượng code \n- Làm việc chặt chẽ với các thành viên khác trong nhóm phát triển, bao gồm thiết kế UI/UX, quản lý dự án và nhóm phát triển backend \n- Phối hợp để lên kế hoạch phát triển sản phẩm và xây dựng team \n- Tham gia vào các dự án của công ty và khách hàng.\n\nYour skills and experience\n1. Kinh nghiệm: \n- Tối thiểu 02 năm kinh nghiệm làm việc với Flutter \n\n2. Kỹ năng: \n- Thành thạo Flutter và Dart \n- Có khả năng build, customize các dự án mobile app \n\n3. Khả năng: \n- Chịu được áp lực công việc, kiên trì và có tinh thần giải quyết khó khăn. \n- Nhiệt tình, nhanh nhẹn, hoạt bát và có trách nhiệm với công việc. \n- Có tinh thần cầu tiến, chủ động trong công việc.\n\nWhy you\'ll love working here\n- Mức lương theo năng lực từ 15M – 30M + phụ cấp \n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ... \n- Xét tăng lương 2 lần/năm: 1 lần theo định kỳ và 1 lần đột xuất theo năng lực và hiệu quả công việc \n- Thời gian làm việc: 09h00 - 18h30 (nghỉ trưa 1h30p) \n- Thứ 2,3,5,6 làm việc tại công ty, thứ 4 và thứ 7 làm việc online (2 thứ 7 bất kỳ làm việc tại công ty) \n- Phép năm tối thiểu 12 ngày theo Quy định của Pháp luật hiện hành \n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành \n- Được tham gia các hoạt động tập thể sôi động của công ty: Nghỉ mát hàng năm, Teambuilding, Sinh nhật công ty, Gala cuối năm....', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '56 Quang Trung, Phường Tăng Nhơn Phú B, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(676, 297, 2, 'Fullstack Developer (NodeJS,ReactJS)', 'We are looking for a full-stack web developer to join our team with NodeJS/ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc.\n\nLocation: Ho Chi Minh, Da Nang, Hanoi\n\nWhat You’ll Be Doing\n- Working on Web and Mobile products for a diverse range of clients and industries.\n- Working and pair programming with other developers to build applications with Node.JS and ReactJS.\n- Designing & implementing back-end API using Node.JS\n- Working with the Product Owner to convert business requirements into technical designs.\n- Cooperating with the UI Designer to implement modern minimalist designs into production.\n- Applying proven technologies and best practices to level up your technical skills: NestJS, Redux\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n\nYour skills and experience\nMust have\n- Require a minimum of 5 years of experience with Node.js\n- Require a minimum of 2 years of experience with ReactJS or similar, such as Svelte, VueJS, AngularJS.\n- Require relevant knowledge of relational database systems such as MySQL, PostgreSQL, and SQL Server.\n- Experience with Extreme Programming methodologies such as Test-Driven Development, Refactoring, and Continuous Integration.\n- Experience with Agile Process and Scrum Methodologies.\n- Excellent written and verbal communication skills in English.\n\nNice to have\n- Experience with serverless architecture, eg, AWS Lambda, GCP Cloud Function, etc.\n- Experience with security, performance, and scalability.\n- Experience with NoSQL, Message Queue.\n- Experience with Infrastructure as Code (IaC) tools such as Terraform, Ansible, or CloudFormation.\n\nWho We Are\nCodeLink is an innovative and design-focused development agency. We focus on user-centric design and agile development to bring the product vision of our clients to life. We handle the end-to-end development of products, developing the product vision through product understanding, designing experiences through UX design, refining these flows with modern UI design, and developing products through iterative agile development.\n\nTop 3 Reasons To Join Us\n- Use cutting-edge & proven technologies\n- Work directly with international clients\n- Open environment with a focus on learning\n\nCompany Benefits\n- Three days remote every week and four full remote weeks per year.\n- Gold level Health Insurance coverage from Bao Viet Insurance, a yearly complete Health Check and social insurance\n- All office benefits and full salary during probation.\n- Flexible working time starting anytime up to 10 AM working Monday - Friday with no overtime and a long lunch break.\n- Allowance for everything: meals, parking, petrol, along with unlimited snacks and nice coffee every day.\n- Choose from a brand-new Mac or PC device.\n- Salary review twice a year with opportunities for promotions and spot awards.\n- 12 days annual leave per year, with all days not taken paid out in cash, plus 2 sick leave days.\n- Yearly Training Budget up to 5 million VND per staff. On top of that, Professional coaching program, buddy system, tech talks, agile sessions, and 1on1 private English classes are available.\n- Yearly company trip, monthly activities, and other Celebrations for special days in the year, such as Women’s Day, YEP, and Christmas.\n- Employee-led clubs within the company; games teams, sports teams, etc.\n- Modern open-space office with comfortable workspace, a PS4 games room, and chill-out areas.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Da Nang, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(677, 480, 2, 'Senior Automation Tester/ QA Engineer (English)', 'Top 3 reasons to join us\n- Friendly and flexible hybrid working environment\n- Work with international clients and diverse teams\n- Competitive benefits\n\nJob description\nAutomation Testing \n- Building and maintaining test frameworks with Cypress, Playwright, WebDriver IO. \n- Automating web and API tests and integrating tests into CI/.\n\nManual Testing \n- Creating and executing test cases from requirements. \n- Performing functional, regression, UI, and exploratory testing.\n\nAnalytical & Problem-Solving \n- Identifying gaps and edge cases in requirements. \n- Conducting root cause analysis and risk assessments.\n\nTeamwork\n- Working cross-functionally to ensure quality and delivery.\n- Ready to lead QA teams and assigned tasks by priority.\n\nYour skills and experience\n- At least ~3 years of experience in QA, Automation Testing. \n- Testing Tools: Cypress, Playwright, Postman, Selenium \n- Languages: JavaScript, TypeScript (optional), HTML/CSS \n- CI/CD: Jenkins, GitHub Actions, GitLab CI. \n- Version Control: Git. \n- Familiar with Agile development process (Scrum, Kanban). \n- Proficiency in using JIRA, Monday, or Azure DevOps for task management and bug tracking. \n- Good communication in English.\n\nWhy you\'ll love working here\n- Attractive salary and benefits packages, including full social insurance on salary.\n- 100% salary during Probation Period\n- Premium Healthcare and Accident insurance coverage.\n- 14 days of leave, including 12 days of annual leave and 2 personal leave days.\n- English-speaking working environment\n- Gifts on special occasions + holidays (Tet, Full-moon festival, Birthday, Christmas etc.)\n- Employee Referral Program\n- Additional bonuses. (13th bonus, Talented retention bonus)\n- Engaging team-building activities, company trips, and year-end parties.\n- Diverse training opportunities for technical and soft skills.\n- Commitment to community development, including regular charity initiatives and blood donation drives.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '314/6 Điện Biên Phủ, Phường 11, Quận 10, TP.HCM, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(678, 428, 2, 'Senior Japanese Manual Tester/QC (Up to $3000)', 'Top 3 reasons to join us\n• Competitive salary \n• Premium health care package \n• 7 working hours/day\n\nJob description\n• Develop test plans, test procedures, test reports and manage testing efforts for assigned company’s projects.\n• Research project documentation with the project team leader and project members\n• Analyze software test results and recommend corrective actions \n• Define testing method, exit criteria and measurement for test, considerations, resources and conditions for performing test.\n• Create & Review test cases/ test plan.\n• Provide testing estimates and participate in project planning. \n• Report bugs and errors to development teams.\n• Analyzing test results on database impacts, errors or bugs, and usability.\n• Analyze change requests and update test documents (Test plan, test cases,…).\n• Work with cross-functional teams to ensure quality throughout the software development lifecycle.\n• Review and report test status to the QC Manager \n\nYour skills and experience\n• Graduated from TOP UNIVERSITY specializing in Information Technology or Graduated as an exceptional student from a high school dedicated to gifted individuals, with a focus on Mathematics, Physics, Mathematics Information, and Chemistry.\n• The candidates win the National/International Awards is an advantage\n• Have experience working with AI project\n• Proficient in English\n• Experience in manual and automated testing\n• Experienced with SQL scripting\n• Have experience in testing API, web and mobile applications.\n• Over 5 years experience in software testing.\n• Solid testing and a demonstrated experience in delivering quality products to customers are required.\n• Software Testing: Capable of working on all levels of the architecture, design, and implementation of security systems.\n• Strong analytical, testing and debugging skills.\n• Ability to think and solve problems in creative ways.\n• Have experience in developing test plans, test procedures, test reports.\nPersonality Requirements\n• Multi- tasking, ability to deal with stress and deadline \n• Ability of working independent and teamwork, can work under high pressure;\n• Willing to work overtime if needed\n\nWhy you\'ll love working here\n• Salary: $1000 - $3000\n• Working hours: 9:00 - 17:00 (5 days per week); Breaking time: 12:00-13:00\n• Modern working equipment\n• Salary Review: 1 times/year based on employee\'s performance and contribution;\n• Well-equipped with insurance package as stated by Labor code\n• Premium PVI Health Insurance Package for all members\n• Transportation allowance and free parking included.\n• Technical seminars and workshops annually.\n• Free snack, coffee, tea available.\n• Variety of corporate events: weekly tea-break, monthly birthday parties, quarterly team building to New Year party, company trip etc.\n• Friendly, open and fast-paced environment where every idea is welcomed.\n• Other benefits as per stated in Vietnamese Labor Law', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 3, The Loop Building, 241 Xuan Thuy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(679, 481, 2, 'Junior Fullstack Developer', 'Top 3 reasons to join us:\n- Build products that matter to the community\n- Dynamic environment with challenging opportunities\n- Supportive leadership and team\n\nJob description:\n- Phát triển hệ thống phân tán cho dịch vụ music streaming\n- Phát triển giao diện web cho các module trong hệ thống, tích hợp hệ thống đã có.\n- Phân tích, tìm và sửa lỗi dịch vụ\n- Tối ưu ứng dụng để tối đa hoá tốc độ và khả năng mở rộng\n- Triển khai, vận hành hệ thống\n- Viết chương trình sạch sẽ, dễ hiểu, có khả năng tái sử dụng\n- Viết các test case.\n\nYour skills and experience:\n- 1-2 năm kinh nghiệm với Python, có kinh nghiệm sử dụng Flask, SQLAlchemy là lợi thế\n- 1-2 năm kinh nghiệm với phát triển web front-end sử dụng JavaScript, có kinh nghiệm với NextJS, ReactJS là lợi thế.\n- 1-2 năm kinh nghiệm với thiết kế, phát triển microservice và thiết kế REST-API\n- Có ít nhất 1 năm kinh nghiệm thiết kế CSDL quan hệ, có kinh nghiệm sử dụng CSDL không quan hệ là một lợi thế.\n- Có kinh nghiệm với Kubernetes, Helm là lợi thế\n- Có kinh nghiệm viết test tự động, CI/CD\n- Có kinh nghiệm triển khai, cấu hình hệ thống là một lợi thế\n\nWhy you\'ll love working here:\n- Tại DIIJAM, chúng tôi tạo ra các sản phẩm mang lại trải nghiệm tương tác cộng đồng cao, tạo ra giá trị thực sự cho ngành âm nhạc. Bạn sẽ làm việc trong một môi trường năng động với nhiều cơ hội học hỏi, cùng với những phúc lợi hấp dẫn như:\n- Nhận 100% lương trong thời gian thử việc.\n- Xét tăng lương 1 lần/năm.\n- Được cung cấp đầy đủ trang thiết bị làm việc.\n- Môi trường làm việc linh hoạt, có một ngày làm việc từ xa mỗi tháng.\n- Các phúc lợi khác theo chính sách của công ty (du lịch, dã ngoại hàng năm, thưởng Tết theo quy định và các chính sách khác).\n- Đội ngũ lãnh đạo hỗ trợ tận tình.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Golden West Building, 2 Le Van Thiem, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(680, 482, 2, 'Senior Front-End Developer (US Start Up Company)', 'About the Company:\nWe are currently seeking a skilled Front End Developer with a strong background in ReactJS to join our dynamic team. If you are passionate about creating responsive, user-friendly web applications with the latest technologies and thrive in a collaborative environment, we would be excited to hear from you.\n\nKey Responsibilities:\n- Develop and maintain high-quality front-end architecture with ReactJS.\n- Design and implement scalable React UI libraries from scratch.\n- Collaborate with back-end developers and web designers to improve usability.\n- Utilize front-end bundlers like Webpack and Rollup for efficient code compilation.\n- Employ micro frontends techniques using Module Federation to enhance scalability and maintainability.\n- Ensure the technical feasibility of UI/UX designs.\n- Optimize applications for maximum speed and scalability.\n- Maintain and improve website.\n- Stay up-to-date with emerging technologies.\n- Responsible for mentoring and managing junior developers.\n\nYour skills and experience:\nRequirements:\n- Minimum 5 years of hands-on experience with ReactJS.\n- Deep understanding of ReactJS and its core principles.\n- Proficient in JavaScript (ES6+), HTML, and CSS (CSS Modules).\n- Experience in developing React UI libraries from scratch.\n- Familiarity with micro frontends techniques and Module Federation.\n- Strong expertise with front-end bundlers like Webpack and Rollup.\n- Ability to work independently to deliver high-quality results within set deadlines.\n- Demonstrates strong academic performance, reflecting a solid foundation in relevant fields.\n- Possesses excellent problem-solving skills and critical thinking abilities, capable of navigating complex challenges effectively.\n- Exhibits a strong willingness to learn and embraces the dynamic, innovative culture of a startup environment.\n\nNice to Have:\n- Experience in developing custom dashboards.\n- Knowledge of the SignalR library for real-time web functionality.\n- Familiarity with web performance optimization techniques.\n- Experience with testing frameworks such as Jest, Enzyme, etc.\n\nWhy you\'ll love working here:\n- Hybrid Work Model: Work from the office two days a week to foster team interaction and build strong connections.\n- Annual Leave: Enjoy 15 days of annual leave each year.\n- Comprehensive Insurance: Full health and social insurance coverage.\n- Monthly Team Dinners: A budget allocated for team dinners each month to strengthen bonds.\n- Company Trips: Join us for regular company outings.\n- Laptop Provision: A laptop provided for all employees.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'H3 Building, 384 Hoang Dieu, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(681, 317, 2, 'Software Testing Engineer', 'We are seeking an experienced Testing Software Engineer with a minimum of 2+ years of experience in software testing and quality assurance. In this role, you will be responsible for designing, developing, and executing test plans and automated test suites for a range of software applications and systems. You will play a key role in ensuring that our software products meet the highest quality standards and perform as expected:\n- Collaborate to test projects, including planning, progress tracking, and test coverage analysis.\n- Monitor project status, test coverage, and test case/defect quality. Analyzes project cost, efficiency, and risks.\n- Collaborate with development team to define test requirements, cases, and timelines.\n- Collaborate with development teams to understand requirements and resolve testing issues.\n- Conducts and oversees various testing types (functional, regression, performance).\n- Analyze test results and drive continuous improvement of testing processes.\n- Provide weekly project updates and reports, including achievements, issues, and risks.\n\nTECHNICAL SKILLS:\n- Experience in software testing, with a focus on automatic identification products.\n- Proficient in Agile development methodologies (Scrum, Kanban) and experience working in Agile teams.\n- Proficient in test management tools such as Jira, JAZZ IBM, and experience with other Agile project management tools.\n- Experience in test automation frameworks such as Robot Framework and Test Complete.\n- Experience in developing and maintaining automated test scripts using [e.g., Python, Java].\n- Strong analytical and problem-solving skills: Ability to identify and troubleshoot complex technical issues.\n\nSOFT SKILLS:\n- Ability to effectively prioritize tasks and meet deadlines.\n- Excellent communication skills: Ability to clearly articulate technical issues to both technical and non-technical stakeholders.\n- Eagerness for new technologies and innovation: A passion for staying up to date with the latest testing trends and technologies in the Auto ID industry.\n\nEXPERIENCES:\n- 2+ years of experience in Testing SW\n\nEDUCATION:\n- Telecommunication Engineering, Computers Science and Electronic, Information Technology or related major\n\nNICE TO HAVE:\n- ISTQB Foundation certificates\n- Agile Foundation certificates\n- API Testing specialist certificates\n\nWhy you\'ll love working here:\nCAREER OPPORTUNITIES:\n- Live in a high-end technology R&D environment\n- Be proud to see your own developed products sold all over the world\n- Strong knowledge and skills improvement through practical training and technical experience\n- Career promotion with proven capabilities\n- Opportunity for overseas training (US, Europe, etc.)\n\nBENEFITS:\n- Working day: from Monday to Friday (08:00 AM- 4:30 PM), One Smart working day per week\n- Salary and Allowance: Competitive\n- Incentive, Reward and Bonus: Outstanding employee award with attractive bonus, semi-annual KPI reward, Long term incentive for key positions, Annual bonus\n- Company’s labor policy completely pursuant to Vietnam labor legislation: working conditions, social & health insurance paid based on gross salary.\n- Mobility: Global mobility program in US and/or Italy\n- Benefits: Free meals, transportation allowances, accident insurance 24x24, premium health care insurance including dependents; gifts for Vietnam national days, scholarship for children of employees\n- Exciting leisure: Sport activities, corporate parties, company trip once a year, monthly teambuilding.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Datalogic Vietnam LLC. F04, Lot I-4A, Saigon High Tech Park, Long Thanh My Ward, Thu Duc, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(682, 211, 2, 'Chuyên viên phát triển phần mềm (Python Developer)', 'Top 3 reasons to join us\n- Attractive salary and bonus package\n- Premium AON healthcare insurance\n- Fully sponsored training to build your career\n\nJob description\n- Thiết kế, phát triển các tính năng mới cho hệ thống.\n- Tham gia triển khai các RESTful API cung cấp cho FE.\n- Bảo trì, tối ưu hóa hiệu suất của hệ thống để đảm bảo khả năng xử lý dữ liệu nhanh chóng và đáp ứng được khối lượng truy cập lớn.\n\nYour skills and experience\n- Tốt nghiệp đại học trở lên chuyên ngành CNTT, Toán, hoặc các chuyên ngành liên quan\n- Trên 3 năm kinh nghiệm ở vị trí backend với ngôn ngữ Python;\n- Sử dụng thành thạo Framework FastAPI.\n- Hiểu biết về các hệ thống cơ sở dữ liệu PostgreSQL.\n- Hiểu rõ về các công cụ quản lý source code như Git, SVN.\n- Có kinh nghiệm làm việc với hệ thống Tài chính\n\nWhy you\'ll love working here\n- Chứng khoán SSI nhận 3 giải thưởng nơi làm việc tốt nhất: \n- Highly competitive remuneration package: Attractive monthly salary, 13th month salary, KPIs cash bonus, Public holiday cash bonus, Birthday gift, Lunar new year gift,...\n- Premium AON healthcare insurance and full labor insurance\n- 12 days Annual leave + 2 days sick leave with full paid\n- Luxury team-building trip and varied engagement activities\n- Joining the leisure clubs: Football, E-Sport, Running, Gym, Yoga....\n- Fully sponsored training to build your career\n- Professional, open minded and supportive working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Luong Yen, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(683, 483, 2, 'PHP Developer (JP No.1 E-Commerce Platform)', 'Top 3 reasons to join us\n- Young/Dynamic/Free/Team-work\n- Learning and Experiencing New IT Skills\n- Career Path to PM\n\nJob description\nCompany Information\n- YRGLM VIETNAM is a company established December 2013 in HCMC, owned by YRGLM Inc. in Japan.\nYRGLM VIETNAM provides Marketing Platform Business, which is No.1 Share of Japanese Market.\nBesides, YRGLM VIETNAM develops the system which uses "EC-CUBE", No.1 Share of Japanese E-Commerce Platform.\nWith Data and Technology, we will support Marketing Activities by companies around the world and become a company that creates happiness for sellers and buyers.\n\nJob Description\n- EC-CUBE, Open Platform in E-commerce:\n- Designing, Developing, and Maintaining Online Stores using EC-CUBE\n- Customizing, Improving Performance, Solving Problems, Improving Systems of Security Measures and Developing\n- Collaborating with PM to manage project progress and deadlines\n- You will carry out these tasks in close communication with PMs and Technical Leaders.\n\nIdeal Candidate\n- Can sympathize with the Business Content and Vision of YRGLM VIETNAM\n- Can work with ambition, motivation, and sense of responsibility\n- Is interested in new technologies and always thinks about how to apply them into work\n- Understands the goal of the product and is team-oriented\n- Is flexible, energetic, patient, and able to work in a multicultural environment\n- Understands the right and obligation\n\nYour skills and experience\nNecessary:\n- More than 3 years of Work Experience as a PHP developer.\n- More than 3 years of Work Experience of Symfony/Laravel Framework.\n- Experience in HTML, CSS, jQuery, Ajax.\n- Experience in popular DBMS like PostgreSQL, MySQL.\n- Experience in PHPUnit & CodeCeption.\n- Experience with tools: Jira, Visual Studio Code/PhpStorm, Docker, Github, ...\n- Experience in Reviewing Work Results of others (Cross, Mob Review).\n- Have Knowledge about Software Testing, Database Analyzing and Designing.\n- Team Work Skills, Logical Explanations and Presentations.\n\nPlus Point:\n- Graduated from IT major is Desirable.\n- Experience in Ecommerce EC-CUBE or other Ecommerce related system is BIG PLUS.\n- Have Designed or Developed a System on the AWS platform.\n- Experience in AI Utilization Skills (Effective Use of Prompt Entries, Achievements).\n- Quick Catch-up on System Structure.\n\nWhy you\'ll love working here\nWhy work at YRGLM VIETNAM?\n- In order to Follow the Latest Browser Trends and Respond at the Fastest Speed in the industry, engineers can take the Initiative in Developing New Specifications and Functions.\n- Because we are Promoting Cloud Computing from On-Premise, we can be Involved in Development and Migration that fully Utilizes the Advantages of Cloud Computing such as Serverless Architecture.\n- By Taking Charge from the Project Planning Stage, you can Proceed with Member Assignment and PJ Progress Method with Discretion.\n- By Collaborating with the Planning Department, you can Get Involved from the Stage of Studying the Realization Specifications.\n- In the Future, regardless of your own team or other teams, you will be Involved in the Training of Engineers from New Graduates / Mid-career Recruitment.\n- In the Future, you may be Involved in Product Development in the New Business Start-up Phase.\n- You can Experience Large-Scale PJ such as Offshore Development with Overseas Group Companies.\n- You can Develop Software to Realize Customer Solutions with Contributing to Japan\'s largest EC-OSS package software, "EC-CUBE" and Advanced Development.\n- You can Realizing Safe Software Development which has a Security Perspective.\n- You can Obtain Training and Practical Experience to Improve Quality and Productivity.\n\nWorking hours\n- Monday to Friday from 8:00 am to 5:30 pm\n- Morning 1h Flex Time (You can work from 7:30-8:30 am and finish 5:00-6:00 pm) *Keep 8h Working Time \n- 12: 00 -13: 30 break\n\nSalary\n- Salary that can be negotiated based on ability\n- 100% salary payment even during the trial period *Personal income tax (PIT): 10% during the probation period\n- Twice a year update salary (April and October)\n- Twice a year bonus payment (July: 50-100%/monthly Salary, January: 50-100%/monthly Salary) *Up to your Ability and Evaluation\n\nTraining\n- In-house training in technology, management, language, and quality control\n- Payment of external training costs\n- Payment of certification examination fee\n- Payment of book purchase costs\n- Overseas training support in Japan\n\nHoliday\n- Full paid leave for 12 days a year\n- Company establishment date\n- Holidays in the year specified in the law (April 30th, September 2nd, New Year\'s Day)\n\nAward\n- Quarterly Best of team\n- Annual MVP Award\n\nWelfare\n- Social insurance (SI, HI, UI) (calculated 100 % based on salary)\n- Annual voluntary health insurance\n- Motorcycle insurance/Motorcycle Parking Fee at Company or Half Way of Grab Bike Fee\n- Regular health checkup (once a year)\n- Team building activities (Company trip and so on…)\n- Sports activities (badminton, football, billiards etc.)\n- Tet gift / birthday gift.\n- Wedding, baby gifts, condolences.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '308 Robot Tower, Dien Bien Phu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(684, 484, 2, 'Project Manager/Technical PreSales', 'Ecotek đang dẫn dắt Ecopark phát triển trở thành mô hình Thành phố thông minh kiểu mẫu của Việt Nam theo phê duyệt của Bộ Xây dựng. Để đạt được thành tích này, tập đoàn đã xác định chuyển đổi kỹ thuật số là một trong những mục tiêu quan trọng trong tương lai, được thực hiện thông qua việc số hóa và số hóa hoạt động quản lý vận hành, thiết lập mạng lưới đối tác dịch vụ kỹ thuật số và phát triển các dịch vụ cốt lõi.\nChúng tôi đã phát triển và triển khai phiên bản City O/S đầu tiên tại khu đô thị Ecopark và hiện đã sẵn sàng đưa sản phẩm cốt lõi của mình đến các dự án phát triển bất động sản và khu đô thị khác. City O/S đang đổi mới cách các nhà quản lý bất động sản và nhà phát triển bất động sản vận hành các khu đô thị ở Việt Nam và chúng tôi hiện đang tìm kiếm một người quản lý dự án hoặc điều phối viên dự án để chịu trách nhiệm quản lý nhiều dự án.\n\nMô tả công việc:\n- Xây dựng và duy trì mối quan hệ khách hàng, hỗ trợ hậu mãi, upsell/cross-sell dịch vụ\n- Tiếp nhận yêu cầu từ khách hàng, phân tích nghiệp vụ, phối hợp với team kỹ thuật đưa giải pháp phù hợp.\n- Lập kế hoạch triển khai dự án, bao gồm timeline, nguồn lực, ngân sách, rủi ro và mục tiêu cụ thể.\n- Phân tích nhu cầu khách hàng, đề xuất và trình bày giải pháp phần mềm/dịch vụ tương ứng.\n- Thực hiện tư vấn, báo giá, demo sản phẩm, hỗ trợ đàm phán và ký kết hợp đồng.\n- Đồng hành cùng bộ phận kinh doanh trong việc xây dựng mối quan hệ dài hạn với khách hàng, triển khai chính sách hậu mãi, chăm sóc và gia tăng giá trị hợp đồng.\n- Thực hiện nội dung giới thiệu sản phẩm, proposal, hồ sơ năng lực hoặc bản chào thầu.\n\nKỹ năng và kinh nghiệm của bạn:\n- Tư duy logic tốt, tư duy hướng giải pháp, tư duy phản biện\n- Kỹ năng giao tiếp, đàm phán, thuyết trình giải pháp tốt.\n- Tối thiểu 2–3 năm kinh nghiệm ở vị trí quản lý dự án trong lĩnh vực CNTT, phần mềm hoặc điện nhẹ.\n- Có kinh nghiệm làm việc trực tiếp với khách hàng.\n- Có kỹ năng phân tích yêu cầu khách hàng và chuyển hóa thành kế hoạch kỹ thuật cụ thể.\n- Tham gia quá trình UAT, thực hiện thủ tục nghiệm thu, hỗ trợ hoàn thiện hồ sơ dự án.\n- Có tư duy dịch vụ: đặt trải nghiệm và nhu cầu khách hàng lên hàng đầu.\n- Hiểu và tham gia quy trình bán hàng, từ tiếp cận – tư vấn – chốt deal – hậu mãi – mở rộng hợp đồng.\n- Kỹ năng tổng hợp, viết tài liệu, báo cáo dự án rõ ràng.\n- Có kỹ năng giao tiếp bằng tiếng Anh.\n\nTại sao bạn sẽ thích làm việc ở đây:\n- Trở thành một phần của Ecotek - công ty công nghệ với văn hóa khởi nghiệp trẻ trung và cởi mở, nơi tiếng nói của bạn luôn được lắng nghe và trân trọng.\n- Tham gia các hoạt động Team building và Happy hour định kỳ, du lịch và sự kiện thường niên với quy mô công ty và tập đoàn.\n- Được khám sức khỏe định kỳ và nhận thẻ khám sức khỏe miễn phí hàng năm.\n- Được ứng lương trước ngày nhận lương hàng tháng bằng việc sử dụng ứng dụng ứng lương linh hoạt Ekko của công ty.\n- Mức lương cạnh tranh, thưởng theo dự án.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Văn phòng Ecotek, Khu đô thị Ecopark, Xuân Quan, Văn Giang, Hưng Yên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(685, 485, 2, 'DevOps Engineer (Linux, Docker, CI/CD)', 'Job description\n- Thiết lập, quản lý và tối ưu hệ thống CI/CD cho các ứng dụng phát triển trên nền tảng NodeJS.\n- Triển khai, giám sát và bảo trì hệ thống trên các nền tảng Cloud (AWS, Azure, Google Cloud).\n- Xây dựng, triển khai và quản lý hệ thống container hóa sử dụng Docker và Kubernetes.\n- Theo dõi, phát hiện và xử lý kịp thời các sự cố hệ thống, đảm bảo hiệu suất hoạt động và an ninh bảo mật.\n- Phối hợp chặt chẽ với các team Frontend, Backend và Product để tối ưu hiệu năng và hỗ trợ triển khai các tính năng mới.\n\nYour skills and experience\n- Có ít nhất 5 năm kinh nghiệm ở vị trí DevOps hoặc tương đương.\n- Thành thạo NodeJS, hiểu sâu về JavaScript, npm/yarn.\n- Kinh nghiệm làm việc thực tế với Docker, Kubernetes, và các công cụ CI/CD (Jenkins, GitLab CI, GitHub Actions).\n- Có kinh nghiệm quản trị hệ thống Linux, thành thạo Bash script.\n- Có kinh nghiệm triển khai và quản lý các dịch vụ cloud như AWS (EC2, S3, RDS), Azure hoặc Google Cloud.\n- Sử dụng thành thạo các công cụ monitoring và logging như Prometheus, Grafana, ELK Stack.\n- Chủ động, trách nhiệm cao trong công việc, khả năng phân tích và xử lý vấn đề nhanh chóng, hiệu quả.\n- Giao tiếp và làm việc nhóm tốt.\n\nWhy you\'ll love working here\n- Mức lương cạnh tranh từ 20 – 30 triệu/tháng (thỏa thuận theo năng lực).\n- Môi trường và thời gian làm việc linh hoạt.\n- Chế độ phúc lợi hấp dẫn: du lịch hàng năm, team-building, bảo hiểm sức khỏe cao cấp, nghỉ phép năm.\n- THỜI GIAN LÀM VIỆC: Thứ 2 – Thứ 6 (9h00 – 18h00), nghỉ Thứ 7 & Chủ Nhật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '., District 8, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(686, 229, 2, 'Senior Backend Developer - PHP/Laravel', 'Top 3 reasons to join us\n- We truly value your thoughts and opinions\n- International and professional environment\n- Honest, Transparent, Open-minded, Respect\n\nJob description\n- Coordinate with Leader and team to build a web API system, web application using PHP (Laravel), Python, WordPress CMS.\n- Writing high-quality code, troubleshooting and debugging.\n- Research new technologies suitable for investment projects of the company.\n- Making API documentation for better communication with front-end developers.\n\nYour skills and experience\n- From 5 years of PHP development experience, with an emphasis on web applications.\n- Experience with PHP (Laravel), database design & SQL skills.\n- Experience with NoSQL (ElasticSearch, MongoDB), Caching (Redis, Memcached).\n- Experience with code version control tools (Git is preferred), CI/CD tools (Gitlab).\n- Experience with unit testing frameworks (PHPUnit), debugging (XDebug).\n- Experience in REST API development.\n- Basic English communication.\n- Knowledge of Frontend framework (Vue.js or React).\n- Knowledge of Real-Time Communication (FireBase, Socket).\n- Knowledge of system performance and scaling, database troubleshooting.\n- Knowledge of Linux systems.\n\nPreference\n- Good understanding of the Rest API.\n- Good understanding of the communication process between Front-end and Back-end.\n- Experience in using Git to manage and collaborate with code.\n\nWhy you\'ll love working here\nSPECIAL OFFER\n- Providing training and education experience in Korea with Korean Finance/IT expert.\n- Providing opportunities to work and support in IT/Finance fields overseas.\n\nBENEFITS\nIncome & Achievement\n- Competitive salary, salary review once a year.\n- 13th month salary and Annual Performance Bonus.\n- MVP and Shining star awards at the end of year.\n- Global and professional working environment.\n\nWorkplace Happiness\n- Full SHUI as Vietnamese Law.\n- 15-day annual leave, Christmas leave and 30-min menstrual leave for women.\n- Annual health check, company trip, YEP and monthly gathering time.\n- Gifts on special occasions and fully stocked snack corner.\n- Sponsored training courses and book purchase quarterly.\n- Be well-equipped with new working equipment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '14F, AP Tower, 518B Dien Bien Phu Street, Ward 21, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(687, 486, 2, 'Mid/Sr. Games Server Developer (Unity, PHP, NodeJS)', 'Top 3 reasons to join us\n- Thưởng lương tháng thứ 13\n- Review lương định kỳ\n- Thưởng chuyên cần, hiệu suất \n\nJob description\n- Phát triển server-side cho game mobile mới trên iOS/Android (Client sử dụng Unity)\n- Sử dụng PHP (CodeIgniter) & Node.js\n- Thiết kế API, database, logic hệ thống\n\nYour skills and experience\nYÊU CẦU\n- Trên 3 năm kinh nghiệm phát triển game server-side\n- Thành thạo thiết kế hệ thống server-side\n- Có tư duy logic và khả năng giải quyết vấn đề tốt\n- Chỉ nhận CV tiếng Anh\n\nƯU TIÊN\n- Kinh nghiệm phát triển game bằng Unity\n- Kinh nghiệm MMO & real-time game (Node.js)\n- Kỹ năng lãnh đạo & giao tiếp tiếng Anh cơ bản\n\nCÔNG NGHỆ SỬ DỤNG:\n- Ngôn ngữ: PHP (CodeIgniter), Unity (C++), Node.js\n- Database: MySQL, MongoDB\n- Tool khác: Redis\n\nWhy you\'ll love working here\n- Thưởng lương tháng thứ 13 \n- Thưởng nhân viên chuyên cần mỗi tháng \n- Thưởng nhân viên đạt hiệu suất tốt mỗi quý \n- Tiền mừng sinh nhật, mừng cưới, mừng sinh em bé \n- Tổ chức Event, Party, quà mừng v.v vào các dịp quan trọng\n- Quầy Pantry với đồ ăn nhẹ phong phú. Đặc biệt Happy Friday mỗi tuần\n- Review lương định kỳ mỗi năm \n- Môi trường làm việc chuyên nghiệp, cởi mở, hòa đồng và thân thiện \n- Khám sức khỏe định kỳ mỗi năm tại bệnh viện của Nhật (có giảm giá khám cho gia đình của nhân viên)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '2nd Floor, Mach Building, 127 Ung Van Khiem Street, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(688, 466, 2, 'Backend Developer (NodeJS, Nest JS, TypeScript)', 'Job description\n- Phát triển và bảo trì các ứng dụng quản lý nội bộ của công ty sử dụng NestJS.\n- Thiết kế, triển khai và tối ưu hệ thống backend hiệu quả, bảo mật và dễ mở rộng.\n- Xây dựng và duy trì các API phục vụ cho hệ thống nghiệp vụ.\n- Tham gia vào quá trình phân tích yêu cầu, thiết kế kiến trúc hệ thống và đề xuất giải pháp kỹ thuật.\n- Đảm bảo chất lượng code qua việc viết test, review code và tài liệu hóa.\n\nYour skills and experience\n- Có ít nhất 2 năm kinh nghiệm phát triển backend với Node.js, trong đó ít nhất 1 năm sử dụng NestJS.\n- Thành thạo TypeScript và các mô hình thiết kế trong backend.\n- Kinh nghiệm với PostgreSQL hoặc hệ quản trị cơ sở dữ liệu quan hệ khác.\n- Hiểu rõ về RESTful API, bảo mật backend, xác thực và phân quyền người dùng.\n- Có khả năng làm việc độc lập, chủ động và phối hợp tốt với các thành viên khác.\n- Biết sử dụng Git và quen thuộc với quy trình làm việc nhóm.\n\nĐiểm cộng\n- Có kinh nghiệm triển khai hệ thống theo kiến trúc microservices.\n- Đã từng làm việc với các hệ thống quản lý nội bộ cho doanh nghiệp.\n- Có kiến thức hoặc kinh nghiệm về DevOps (CI/CD, Docker, Kubernetes).\n- Biết viết unit test hoặc e2e test bằng Jest hoặc công cụ tương tự.\n\nWhy you\'ll love working here\n- Lương cơ bản: 12 triệu đến 16 triệu.\n- Được hưởng các quyền lợi theo chính sách của công ty và quy định của nhà nước.\n- Review lương 2 lần/năm (tùy vào năng lực), lương tháng 13, cùng nhiều chế độ thưởng khác nhau.\n- Team building 2 lần/năm.\n- Có cơ hội tham gia các khóa đào tạo, phát triển, nâng cao năng lực làm việc.\n- Làm việc trong môi trường chuyên nghiệp, năng động, nhiều cơ hội phát triển năng lực bản thân, đãi ngộ dựa trên năng lực và sự nhiệt tình sáng tạo của từng thành viên.\n- Nghỉ 12 ngày phép năm và các ngày lễ tết, dịp đặc biệt của công ty.\n- Hỗ trợ ăn trưa, gửi xe.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '265 Hong Lac, P. 10, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(689, 487, 2, '02 Senior Data Engineer', '*According to Decree No.13/2023/ND-CP on protecting personal data (“PDP”), Home Credit Vietnam would apply "Personal Data Processing Agreement" with all candidates to ensure compliance with the decree.\nBy submitting this application to Home Credit Vietnam Finance Company Limited through ITViec, you agree to allow Home Credit to proceed your provided information in accordance with Personal Data Processing Agreement that you have read, fully understood and agreed to the entire content at link.\n\nResponsibilities:\nCollaboration in Virtual Domain-aligned Team:​​\n- Work closely with the Product Owner, Data Scientists/Analysts and other colleagues in agile way towards shared product goals​​\n- Ensure and promote proper data model design and feasibility of data products including AI/ML model training/serving​\n\nContinuous Improvement, Technical Excellence and Accountability:​​\n- Follow and enrich data product building blocks and code templates, review and approve changes from contributors​\n- Follow, select and apply the latest technologies and best practices in data integration and AI/ML​ aligned with context of our company​\n\nAutomated Testing, Code Quality and Documentation:​​\n- Implement and maintain quality standards for data products​ (well-documented, reusable, scalable, performing, DRY)​\n- Ensure regular testing and validation are implemented as vital part of automated CI/CD​​\n- Monitor and improve the performance and efficiency of data flows​​\n\nYour skills and experience\nMust have:\n- Strong experience in Data Engineer/Analytics Engineer, skills in Spark, Kafka, Python, Dbt, Iceberg, Airflow\n- Demonstrated experience designing dimensional data model, effective algorithms to process data, software engineering principles\n- Proficiency in SQL and Python\n- Good English & communication\n- Good stakeholder management skills\nNice to have:\n- Finance/Banking/Ecommerce domain knowledge, especially in Risk, Antifraud, CRM models\n- Microservice architecture with Docker and Kubernetes development experience\n\nWhy you\'ll love working here\nUnderstanding candidates\' expectations of the ideal workplace, we always put the people element at the top of our priorities. ​\nCompensation programs and employees\' development opportunities for employees are always significantly invested in, bringing you:​\nPrimary benefits:\n- 13th-month Salary and performance- based KPI Bonus​\n- 15+ Annual Leaves​\n- Full Social Insurance, 24/7 Accidental Insurance, Annual Medical Check- up​\n- Team Building and CSR activities: Year- end Party, New-year Party, Company trip, Charity activities, Blood donation​\n- Learning workshops: Udemy E-learning, English courses, Senior management development training programs​\nOur culture fosters your career development through: ​\n1. Strategy ​\n- Thinking Big: We focus on creating meaningful and sustainable opportunities for the company. ​\n- Customer Obsession: We try to understand future customer needs, trends, and the impact of digital transformation. ​\n2. Implementation ​\n- Digital Savviness: We seek to understand the technological aspects of the business to enhance efficiency and customer experience. ​\n- Entrepreneurship: We communicate the company\'s strategy and purpose to others, inspire and lead them effectively. ​\n- Risk in mind: We consider risks and their possible effects before making decisions. ​\n- Operational Excellence:  We stay focused on the goal, disciplined in tightening tasks to the end. ​\n3. Building the organization ​\n- People Centricity: We sustain focus on the development of team members through meaningful development plans and learning opportunities. ​\n- Integrity: We always stay focused on the goal you need to achieve, refrain from getting into personal conflicts.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '20 Nguyen Dang Giai, District 2, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(690, 258, 2, 'VTS - Chuyên Viên Quản Trị Dự Án (Agile/ Azure)', 'Gia nhập “vũ trụ” công nghệ Viettel, nơi bạn không chỉ được “đắm chìm” trong hàng loạt công nghệ xịn xò như Big Data, AI, IoT, AR/VR, Cloud, Blockchain… mà còn được trao cơ hội thực hiện sứ mệnh quan trọng: “Chung tay cùng Chính phủ kiến tạo – Chính phủ số”, đồng hành với doanh nghiệp và người dân giải quyết các vấn đề cấp bách của xã hội, hướng tới một cuộc sống tốt đẹp hơn cho mọi người. Tại VTS (Tổng Công ty Giải pháp Doanh nghiệp Viettel), bạn sẽ được hiện thực hóa những ý tưởng táo bạo, tham gia vào các dự án công nghệ hàng đầu và phát triển giải pháp đột phá cho tương lai số. Đây chính là nơi khơi dậy đam mê, thúc đẩy sáng tạo và chắp cánh cho mọi ước mơ công nghệ của bạn. Sẵn sàng trở thành “ngôi sao sáng” trên hành trình chuyển đổi số và cùng Viettel tạo nên dấu ấn trong cuộc cách mạng công nghiệp 4.0? Let’s go! Bạn sẽ làm gì? Phối hợp với PMO, AM đưa ra lộ trình triển khai và chi phí dự án để làm việc với khách hàng. Quản lý dự án: Xác định yêu cầu, mong muốn, phạm vi dự án với người BẢO TRỢ dự án và các bên liên quan (Stakeholder) như khách hàng, đối tác, nhà cung cấp... Khởi tạo dự án: Xác định mục tiêu, phạm vi công việc dự án, các nguồn lực dự kiến của dự án, các bên liên quan tương tác đến dự án. Làm việc với khách hàng xác định yêu cầu, mong muốn của khách hàng về sản phẩm/dịch vụ. Khởi tạo dự án: Xác định mục tiêu, phạm vi công việc dự án, các nguồn lực dự kiến của dự án, các bên liên quan tương tác đến dự án. Lập dự án (bao gồm phương án và kế hoạch dự án), dựa trên phạm vi công việc, chi phí và các mốc cần hoàn thành của dự án. Chia nhỏ các công việc, thứ tự các công việc cần thực hiện và đề xuất nhân sự thực hiện dự kiến. Đề xuất tiêu chuẩn và số lượng nhân sự cần tham gia dự án theo từng giai đoạn của kế hoạch dự án. Quản lý tiến độ và chất lượng dự án. Kiểm soát tiến độ các công việc của dự án, của thành viên dự án theo kế hoạch. Thực hiện các hoạt động dự án tuân thủ theo đúng quy trình yêu cầu. Quản lý các vấn đề, rủi ro có thể phát sinh trong quá trình thực hiện dự án (về tiến độ, nhân sự, chi phí, môi trường dự án, điều kiện đảm bảo, ...). Từ đó đề xuất giải pháp và kế hoạch xử lý vấn đề, phòng tránh rủi ro. Quản lý doanh thu chi phí của dự án. Quản lý đối tác outsource để đảm bảo tiến độ, chất lượng và quy trình của Tập đoàn (nếu có). Phối hợp QA, QC đánh giá quy trình, chất lượng hệ thống. Nghiệm thu với khách hàng. Đóng dự án: Thực hiện các thủ tục kết thúc dự án. Cập nhật tài liệu, bài học kinh nghiệm của dự án. Your skills and experience: Bằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng, Khoa học dữ liệu hoặc tương đương. Ngoại ngữ: Đọc hiểu tài liệu tiếng Anh ngon lành. Ưu tiên có chứng chỉ TOEIC 650+ (hoặc IELTS, TOEFL tương đương). Kiến thức, kinh nghiệm: Có ít nhất 4 năm kinh nghiệm làm việc tại vị trí tương đương. Hiểu biết và nắm rõ về các phương pháp quản lý dự án hiện đại như PMI, Agile. Viết tài liệu quản lý dự án, chủ động, độc lập trong công việc. Có khả năng dẫn dắt team dự án thực hiện dự án theo yêu cầu đề ra của cấp trên. Tổ chức, quản lý tốt với các thành viên dự án. Kinh nghiệm tham gia các dự án về CNTT, có các chứng chỉ MCSA(O365…) , Azure, AWS hoặc các chứng chỉ quản lý dự án như PMP, PMI-ACP là một lợi thế. Khả năng nghiên cứu giải pháp công nghệ và chịu được áp lực công việc cao, giải quyết tình huống tốt. Tinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội. Why you\'ll love working here: Lương cạnh tranh: Thu nhập “ổn áp”, xứng đáng với năng lực và kinh nghiệm. Đầy đủ các khoản thưởng: Thưởng lễ Tết, quà tặng, du lịch nghỉ mát, hỗ trợ ăn trưa, cước điện thoại… Nghỉ phép linh hoạt: 12 ngày phép + 3 ngày nghỉ mát + 1 ngày sáng tạo mỗi năm. Bảo hiểm toàn diện: Hưởng đầy đủ BHXH, BHYT, BHTN theo quy định, cộng thêm gói bảo hiểm riêng từ Viettel. Môi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo “bung nóc”.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Tran Huu Duc, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(691, 488, 2, '[Middle-Senior] CV An toàn thông tin - Red Team', 'Mô tả công việc:\n- Thực hiện các hoạt động giả lập tấn công theo mô hình Red Team để đánh giá mức độ phòng thủ an ninh của hệ thống thông tin: Ứng dụng web, hệ thống mạng, thiết bị đầu cuối, nhân sự (Social Engineering),...\n- Thực hiện kiểm tra thâm nhập (penetration testing), khai thác lỗ hổng, mô phỏng hành vi của attacker thực tế nhằm xác định điểm yếu trong hệ thống của khách hàng;\n- Chủ động nghiên cứu và khai thác các lỗ hổng bảo mật đã công bố (CVE, 1-day vulnerabilities);\n- Xây dựng PoC (Proof of Concept) và khai thác các lỗ hổng bảo mật trong môi trường kiểm thử để kiểm chứng mức độ ảnh hưởng;\n- Báo cáo chi tiết về các lỗ hổng, khai thác thành công, đánh giá rủi ro và đề xuất khắc phục;\n- Tham gia đào tạo và xây dựng đội ngũ.\n\nTrình độ: Middle - Senior\n\nQuốc tịch: Việt Nam\nTrình độ:\n- Tốt nghiệp Đại học ngành an toàn thông tin;\n- Có chứng chỉ OSCP, OSCE, CRTP hoặc kỹ năng tương đương.\n\nKỹ năng:\n- Thành thạo Web/App/Infra Pentest, Red Teaming, AD Exploitation, Cloud Security;\n- Thành thạo các công cụ: Cobalt Strike, Burp Suite, BloodHound, Sliver, Havoc,...\n- Khả năng giao tiếp tốt, kỹ năng thuyết trình và tư vấn dịch vụ, sản phẩm;\n- Khả năng làm việc nhóm với cường độ và áp lực cao;\n- Nhanh nhạy, linh hoạt, có tư duy dịch vụ.\n\nKinh nghiệm:\n- 3-5 năm kinh nghiệm khai thác lỗ hổng, chơi CTF;\n- Kinh nghiệm bypass EDR/XDR, evasion, post-exploitation;\n- Ưu tiên các ứng viên đã có kinh nghiệm quản lý đội nhóm, trưởng dự án (RedTeam Lead).\n\nLương, thưởng:\n- Lương theo thỏa thuận: 25 – 30 triệu VNĐ/tháng Gross;\n- Lương tháng thứ 13, thưởng dự án theo quy định của công ty.\n\nQuyền lợi:\n- Môi trường làm việc trẻ trung, năng động và thân thiện, chú trọng đào tạo, phát triển;\n- Cung cấp thiết bị làm việc;\n- Được hưởng các chế độ phúc lợi, bảo hiểm theo quy định của pháp luật và các chính sách ưu việt khác của Công ty;\n- Văn hóa Công ty: Đa dạng và hòa nhập (D&I), chú trọng cân bằng giữa công việc, cuộc sống cá nhân và đời sống tinh thần với những hoạt động hấp dẫn: Thể thao, Happy Hour, Team Building, Du lịch hằng năm,...\n- Giờ làm việc linh hoạt;\n- Cơ hội làm việc và hợp tác với các chuyên gia hàng đầu trong ngành An ninh mạng, mở rộng kiến thức và nâng cao kỹ năng chuyên môn;\n- Được hỗ trợ đào tạo chuyên sâu, thi các chứng chỉ chuyên môn phục vụ công việc;\n- Lộ trình thăng tiến rõ ràng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Trung tâm đổi mới sáng tạo quốc gia (NIC), số 6 ngõ 7 Tôn Thất thuyết, Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(692, 489, 2, 'Software Engineer (.Net/Java/SQL)', 'Top 3 reasons to join us\n- Attractive Salary and Benefits\n- Amazing Clients\n- Product driven company\n\nJob description\nYou will have the opportunity to focus on the aspects of the job that you enjoy the most. Specifically, you will:\n- Developing scalable new features for our software product that exceeds our customer’s needs.\n- Building architecture for our platform to ensure optimal performance.\n- Obtaining requirement feedback from internal teams/clients to maintain/support the product development.\n- Write the Unit Tests for robust development.\n- Performing code reviews on other team members’ work.\n- Taking ownership of projects and having the opportunity to further your knowledge\n- Taking control over your productivity and improving your time management and communication skills\n\nYour skills and experience\nThe most successful candidates for this role will have:\n- Proficiency with any backend programming languages.\n- Proficiency in English (both verbal and written).\n- At least 3 years practical experience on a web-based application.\n- A solid fundamental understanding of software development.\n- An understanding of complex algorithms and data structures, as well as a passion for intellectual challenges.\n- Strong self-discipline for delivering well-tested, complete features/modules under a tight schedule and the capability for rational thinking.\n- Experience with the database management tool SQL is a plus, but not mandatory.\n- Experience with C#, .Net could be a plus, but not mandatory.\n- A Bachelor’s Degree in any relevant major (e.g. Information Technology, Computer Science, etc.).\n\nWhy you\'ll love working here\nYou would love to work and find those values with us:\n- Flat structure and distributed decision making: We also allow each employee to directly weigh in on our priorities.\n- Transparency: We value transparency, openness and accountability, whether it is with our customers or internally.\n- Meritocracy: Employee\'s recognition and advancement is based purely on their individual and collective achievements.\n- Deep work: We do everything we can to let you focus deeply on your work.\n\nAs a full-time employee, you are eligible for our benefits program:\n- Attractive salary package.\n- Monthly performance bonus.\n- 100% Gross Salary in the probation period.\n- 13th-month salary.\n- 18 days of annual leaves (cashback allowed if not used)\n- 4 days of company trip.\n- Multiple allowances (Lunch, Gym, Parking, Birthday/Tet/Wedding voucher...).\n- Full social, healthy, and unemployment insurance.\n- Premium healthcare insurance for you and coverage for 1 extra family member.\n- Monthly team-building activities (Bowling, Go-Kart, Candle Handmade workshop....) and special celebrations on Autumn Festival, Halloween, Christmas, Tet, …\n- Monthly happy lunch and daily happy hours with free snacks, soft drinks, fruit, and coffee.\n- Sports activities (PlayStation 5, Badminton, Football,...).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Saigon Trade Center Building, 37 Ton Duc Thang, District 1, Ho Chi Minh; 14 Lang Ha, Thanh Cong, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(693, 452, 2, 'Business Analyst', 'Top 3 reasons to join us\n1. FREE Gym at 5-star Center.\n2. Friendly and fun working environment.\n3. Team building every year.\n\nJob description\n1. Develop and implement business analysis methodologies, standards, and best practices.\n2. Utilize data analytics to support business decision-making processes.\n3. Develop and maintain dashboards, reports, and key performance indicators (KPIs) to track business performance.\n4. Translate complex business process issues into technical requirements.\n5. Conduct business process analysis and recommend solutions to enhance operational efficiency.\n6. Collaborate with the software development team to provide technical solutions that meet business requirements.\n7. Create detailed documentation including business requirements, process flows, and user stories to guide development and implementation.\n8. Ensure that technical solutions are designed and implemented to enhance user experience and business productivity.\n\nYour skills and experience\n1. Bachelor’s degree in Computer Science, Information Systems, Business Administration, Finance, or a related field.\n2. 2-4 years of experience working as a Business Analyst in software development companies.\n3. Proven experience in writing high-quality technical documentation, particularly API documentation.\n4. Fluent in English, both written and spoken.\n5. Knowledge or passion for sports, especially football (soccer), is an advantage.\n6. Familiarity with Figma or similar tools for UI/UX collaboration is a plus.\n\nWhy you\'ll love working here\n1. Competitive salaries and bonuses\n2. Participate in work vacations and teambuilding activities.\n3. Many bonuses on big occasions such as April 30, September 2, birthdays, or help for weddings, funerals, Tet presents, and Mid-Autumn gifts.\n4. Happy hours every Thursday\n5. Clear and comprehensive wage and bonus review policy every year\n6. 13th month wage plus annual bonuses (based on business scenario)\n7. Opportunity to sign up for a 5-star gym\n8. Participate in after-hours activities like football, badminton, game tournaments, and gym opening.\n9. Beautiful rooms with numerous conveniences in the office.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '628A Đ. Võ Nguyên Giáp, An Phú, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(694, 314, 2, '(Đống Đa HN) Lập trình Game Backend (PHP/Node.js)', 'Top 3 reasons to join us\n1. Không có Over Time, Cân bằng cuộc sống\n2. Cơ hội tiếp cận công nghệ mới, AI\n3. Đóng bảo hiểm full lương, chế độ linh hoạt\n\nJob description\n- Xây dựng và duy trì hệ thống backend sử dụng PHP hoặc Node.js phục vụ game hoặc web-app.\n- Thiết kế và triển khai RESTful API / Webhook phục vụ giao tiếp giữa frontend (Cocos2d-JS/WebView) và server.\n\nYour skills and experience\n- Kinh nghiệm tối thiểu 1 năm với PHP (Laravel là lợi thế) hoặc Node.js.\n- Có kinh nghiệm với hệ sinh thái AWS, đặc biệt: S3, Lambda, API Gateway, DynamoDB.\n- Thành thạo thiết kế API RESTful, hiểu biết về bảo mật JWT/Auth token.\n- Hiểu cách xử lý đồng thời (concurrent user), chống DDoS, rate limiting.\n- Hiểu biết về CI/CD (CodePipeline, GitHub Actions, hoặc tương đương).\n- Đọc hiểu tài liệu kỹ thuật tốt.\n- Source control với git.\n\n▼Kĩ năng mong muốn khác\n- Đã từng triển khai backend cho game mobile/web.\n- Có kinh nghiệm log & debug backend qua CloudWatch hoặc tương đương.\n- Có kinh nghiệm sử dụng serverless framework hoặc Terraform để quản lý hạ tầng.\n- Biết thêm GraphQL là lợi thế.\n- Hiểu cơ bản về frontend: JavaScript, Cocos2d-JS, Unity WebGL.\n\nWhy you\'ll love working here\n1. Mức lương hấp dẫn từ 800 USD đến 1500 USD.\n2. Review lương hàng năm.\n3. Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp đóng full lương.\n4. Được thêm 1 ngày nghỉ có phép vào ngày sinh nhật.\n5. Tham gia lớp học tiếng Nhật, đào tạo chuyên môn do công ty tổ chức.\n6. Tham gia hoạt động Teambuilding và du lịch hàng năm.\n7. Trợ cấp chứng chỉ IT, chứng chỉ tiếng Nhật, trợ cấp tham gia hội thảo.\n8. Tự do ăn mặc thoải mái, không gò bó.\n9. Happy time ăn uống 1 lần 1 tuần.\n10. Trợ cấp câu lạc bộ thể thao: bóng đá, cầu lông, gym,….\n11. Nghỉ sau sinh 6 tháng.\n12. Kho truyện tranh và sách tiếng Nhật free.\n13. Đồng nghiệp trẻ trung, năng động, thân thiện, hoà đồng.\n14. Phục vụ đồ uống miễn phí.\n15. Giờ làm việc : từ thứ 2 đến thứ 6 hàng tuần (8:00 ~ 12:00 và 13:30 ~ 17:30).\n\nĐến với Neos bạn sẽ có được:\n1. Đa dạng cơ hội: Tiếp cận nhiều lĩnh vực và công nghệ tiên tiến trong các dự án outsource, dự án của công ty có đa dạng lĩnh vực, đa dạng công nghệ.\n2. Linh hoạt lựa chọn: Tham gia các dự án với ngôn ngữ lập trình theo sở thích và định hướng phát triển cá nhân.\n3. Học hỏi từ chuyên gia: Làm việc cùng đồng nghiệp và khách hàng Nhật Bản, rèn luyện phong cách làm việc chuyên nghiệp và tỉ mỉ.\n4. Môi trường thoải mái: Văn hóa cởi mở, đồng nghiệp hòa đồng, luôn sẵn sàng hỗ trợ nhau.\n5. Cân bằng công việc và cuộc sống: Hầu như không có Overtime, chú trọng sức khỏe và đời sống cá nhân.\n6. Khuyến khích phát triển: Hỗ trợ chi phí chứng chỉ chuyên môn, trợ cấp cho các câu lạc bộ thể thao, thúc đẩy sự tiến bộ và chăm sóc nhân viên toàn diện.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, tòa nhà Ocean Park, số 1 Đào Duy Anh, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(695, 260, 2, 'Fullstack Web Developer (NodeJS, ReactJS, GraphQL)', 'WHO ARE WE? Digital Unicorn is a French digital agency with a passionate and ambitious team. We specialize in:\nMobile Application Development\nWebsite Development\nAI/Deep Learning\nUX/UI Design\nWe’re more than just a company — we’re a small hub for those who want to step into an international working environment. Here, you’ll train, work, and build your career foundation, all while growing friendships that last.\nAt Digital Unicorn:\nWe share and support each other\nWe build meaningful products for startups\nWe create a space where you can enjoy working and growing.\nWE ARE HIRING: Full-stack Web Developer\nLevel: Middle/Senior\nType: Full-time, On-site\nKey Responsibilities\nDevelop, test, and maintain full-stack applications using Node.js, React.js, and GraphQL\nCollaborate with UI/UX designers, product managers, and other developers to deliver high-quality solutions\nDesign and implement APIs, services, and complex frontend features\nOptimize application performance and troubleshoot technical issues\nEnsure high code quality through code reviews, unit testing, and adherence to best practices\nContinuously research and adopt new technologies to improve development processes.\nYour skills and experience\n5+ years of hands-on experience in fullstack web development\nStrong expertise in Node.js for backend development\nProficient in React.js for frontend development\nExperience with GraphQL for API integrations\nSolid understanding of REST APIs, databases (SQL/NoSQL), and server-side logic\nFamiliarity with version control systems like Git\nFluent in English with strong communication skills (spoken & written)\nAbility to work effectively onsite and collaborate closely with cross-functional teams.\nWhy you\'ll love working here\nTraining policy, salary, and bonus that match your skills and experience\nProvision of full of devices for work\n100% salary during the probation period\nFull insurance policies\nDynamic, comfortable, and creative working environment\nTeam Building events/ company trips every year\nSnacks and fruits for breaks\nSports activities to recharge positive energies\nImmerse in an English-speaking environment for professional foreign communication.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3F, 94 Ho Nghinh, Son Tra, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(696, 274, 2, 'Android Software Engineer (Junior/Middle/Senior)', 'As an Android Software Engineer, you will work on building scalable, high-performance applications with a focus on performance optimization and clean architecture.\n\n- Implement Android (Kotlin) and Flutter components of our SaaS product\n- Drive the entire mobile software lifecycle, from prototyping to commercialization and post-launch support\n- Build clean, well-tested, and maintainable code that aligns with our cross-platform architecture and performance goals\n- Participate in design reviews, code reviews, and contribute to cross-functional discussions and continuous improvement\n- Partner with Product, Design, and Backend teams to deliver quality Android applications\n\nFor Senior:\n- Propose architecture and design reviews to ensure high standards in software quality\n- Set a high technical standard for the team through code and design reviews\n- Enhance engineering processes, including sprint planning, stand-ups, and long-term planning\n- Mentor junior/middle engineers, foster growth, and technical skill development within the team\n\nYour skills and experience\n- Bachelor’s Degree in Computer Science / Information Technology / Software Development or related fields\n\nMust have:\n- 1+ year of experience in Kotlin and Flutter cross-platform technologies\n- Hands-on experience in independently completing or participating in large-scale Android projects\n- Good understanding of framework principles, and practical experience in performance optimization for low-end device models, including but not limited to startup, memory, network, etc\n- Understand Jetpack components, familiar with annotation frameworks, and have practical experience\n- Good/Fluent English communication is mandatory\n\nNice to have:\n- Practical experience in catering apps, with architecture ability preferred\n- Experience with hardware knowledge reserves and practical experience (including but not limited to printers, external card machines, USB/Bluetooth communication) is preferred\n\nWhy you\'ll love working here\n- We are a multinational, product-driven company specializing in proprietary POS solutions — developing in-house and delivering directly to our worldwide customers.\n\nBenefits\n- Recognition & Rewards:\n  - 13th-month salary\n  - Loyalty Bonus programs\n  - Biannual Performance and Salary review\n- Comprehensive Insurance Coverage:\n  - Full government public insurance contributions based on gross salary\n  - Premium health insurance\n  - Annual health check\n- Clear career development and growth structure; Training sessions and Learning workshops\n- 14 days of annual leave and one additional day of leave for every year of service\n- Laptop/MacBook and top-notch facilities are provided based on each role\n- Agile/Scrum-based internal workflows for efficient and collaborative development\n- Company trips, parties and regular team-building activities; Weekly happy hour, coffee, snacks, and board games\n- Overseas travel opportunities based on the individual performance and policies for each evaluation period\n\nWorking Environment & Culture\n- International Workplace: English-speaking environment\n- Positive and Open-Minded Culture: Engineers are encouraged to propose innovative solutions that enhance productivity and code quality\n- 1-on-1 Mentorship: Monthly coffee sessions with managers offer personalized feedback, goal setting, and career development opportunities\n- Flexible Working Hours: Promote work-life balance and individual productivity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '42/37-38 Hoàng Diệu, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(697, 238, 2, '(Middle, Senior) Network Administrator (Cisco)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Triển khai, cấu hình, vận hành, giám sát hệ thống mạng tại các đơn vị, các trung tâm vùng, mạng lõi.\n- Triển khai giám sát hệ thống hỗ trợ quản trị Công nghệ Thông tin: DNS, NTP, DHCP, Zabbix, Cacti, PRTG,...\n- Xây dựng các tài liệu, hướng dẫn, quy trình đảm bảo kết nối hệ thống thông tin ổn định, an toàn.\n- Tham gia phối hợp xây dựng, triển khai các tiêu chuẩn kết nối hệ thống thông tin ổn định, đảm bảo tuân thủ thông lệ quốc tế yêu cầu trong các tiêu chuẩn như ISO27001, PCI DSS, NIST,…\n- Nghiên cứu các công nghệ, kỹ thuật, ứng dụng phục vụ đảm bảo kết nối an toàn bảo mật cho hệ thống thông tin của ngân hàng.\n\nYour skills and experience\n- Tốt nghiệp hệ chính quy các Trường Đại học trong nước hoặc nước ngoài\n- Chuyên ngành đào tạo: Công nghệ thông tin, Toán tin, Điện tử Viễn thông hoặc tương đương\n- Chứng chỉ nghề bắt buộc: CCNA trở lên hoặc tương đương;\n- Chứng chỉ nghề khuyến khích: CCNP trở lên hoặc tương đương\n- Tối thiểu 01 năm kinh nghiệm triển khai, vận hành, giám sát hệ thống mạng kết nối (với các thiết bị của các hãng như Cisco (bắt buộc), HP, Juniper, Extreme, Check Point, Palo Alto, Fortinet...);\n- Hiểu biết, có chứng chỉ liên quan và có kinh nghiệm thực hiện đáp ứng tuân thủ các tiêu chuẩn quốc tế về An toàn thông tin như ISO27001, PCI DSS, NIST,… là lợi thế (vd ISO27001 Lead Auditor, CISSP,…)\n- TOEIC 450 trở lên hoặc chứng chỉ tương đương\n\nWhy you\'ll love working here\nTrải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể… \n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\nCơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\nMôi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng\n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(698, 397, 2, 'Solution Architect', 'As a Solution Architect at SHBFinance, you will be responsible for designing, developing, and implementing end-to-end solutions that meet the complex needs of our customers and our enterprise business users, working in shaping the technological landscape of our organization, specifically in the domain of banking and consumer finance industry. You will work closely with cross-functional teams to understand requirements, assess existing systems, and design architecture that aligns with business goals.\n\nYou will lead the design and development of cutting-edge solutions that enhance our ability to deliver financial products and services to our customers efficiently and securely. The Solution Architect is a key figure in our technology team and will collaborate with various stakeholders, including software developers, business analysts, and project managers, to create robust and scalable solutions that align with our strategic objectives.\n\nKey Responsibilities\n\n• Solution Design: Collaborate with business users, business analysts, and project managers to define solution requirements, objectives, and scope. Create comprehensive solution designs that address these requirements while considering scalability and future needs. Creating high-level solution designs that meet the business requirements and align with the company\'s long-term technology strategy.\n\n• Technology Evaluation: Research and assess emerging technologies, tools, and platforms to ensure that the proposed solutions are aligned with industry best practices and advancements.\n\n• Architecture Development: Create detailed technical architecture blueprints, outlining system components, interfaces, and infrastructure requirements. Ensure that the architecture adheres to security, performance, and compliance standards.\n\n• Technical Documentation: Prepare and maintain comprehensive technical documentation, including design specifications, system diagrams, and other relevant documents to support the development process.\n\n• Quality Assurance: Oversee the quality and performance of the solutions, conducting regular reviews and assessments to ensure that they meet the defined requirements and standards.\n\n• Client Communication: Serve as the technical liaison with business users, explaining technical concepts, addressing client concerns, and providing insights into the technology roadmap.\n\n• Risk Assessment: Identify potential technical risks and challenges in projects and develop mitigation strategies\n\n• Technical Leadership: Provide technical leadership and guidance to development teams, ensuring the implementation of best practices and architectural principles.\n\n• System Integration: Oversee the integration of various systems and technologies, ensuring seamless data flow and functionality across multiple platforms.\n\n• Scalability and Performance: Design solutions that are scalable, reliable, and performant, capable of handling the growth and demands of the consumer finance industry.\n\n• Security and Compliance: Ensure that all solutions meet the highest standards of security and compliance with relevant financial regulations and industry standards.\n\n• Emerging Technologies: Stay updated on emerging technologies and trends in consumer finance and apply this knowledge to develop innovative solutions.\n\n• Collaboration: Work closely with development teams to guide the implementation of the proposed architecture, providing technical leadership, and addressing any design or implementation issues. Collaborate with cross-functional teams, including business analysts, software developers, and project managers, to understand requirements and provide architectural guidance.\n\n• Documentation: Create and maintain detailed architecture documentation, including design specifications and diagrams.\n\n• Cost Analysis: Conduct cost-benefit analysis of proposed solutions and recommend costeffective alternatives.\n\nREASONS TO JOIN SHBFINANCE\nA professional, open working environment that emphasizes 5 core values: "Smart – Honest – Brave – Friendly – Cooperation":\n• Working hours: Monday to Friday, with a 1.5-hour lunch break.\n• Work form home form 1 - 2 days/ week\n• Friendly and open-minded colleagues who value individual development.\n• Spacious open office with all necessary equipment provided for work.\n\nSpecial attention to employees:\n• Competitive compensation package with regular salary increases. Total income can reach up to 14 months\' salary per year.\n• Lunch allowance of up to 1,200,000 VND/month.\n• Birthday leave + birthday gift\n• Exclusive healthcare benefits with comprehensive SHBFC Care insurance.\n• Annual health check-ups at top hospitals in Vietnam, along with social insurance benefits as per state regulations.\n• Annual company trips and team-building activities.\n\nFocused on supporting personal development:\n• Guidance, companionship, and career development support from experienced, talented managers.\n• Opportunities to participate in major projects, leading in the consumer finance sector.\n• Support for learning activities, knowledge exchange, and cultural interaction (Training, Seminars, etc.).\n\nQualifications\n• Bachelor\'s or Master\'s degree in Computer Science, Information Technology, or related field.\n• Proven experience as a Solution Architect or a similar role in designing and implementing complex technical solutions such as Senior/Principal Software Engineer, Technical Architect. Preferably in the insurance, banking, or consumer finance, securities industry or related fields.\n• In-depth knowledge of software and hardware architecture, cloud computing, and integration technologies.\n• In-depth knowledge of software programing principles (e.g: SOLID), design patterns (e.g: GoF), and best practices.\n• Strong problem-solving and analytical skills, with the ability to design solutions that meet business requirements.\n• Strong foundation in security knowledge for enterprise systems and services.\n• Excellent communication and interpersonal skills for client interactions and team collaboration, excellent in transformation idea into practical milestone and tasking.\n• Familiarity with various programming languages (e.g: Java, .NET, Go, Python, nodejs, …etc) and software development methodologies (e.g: Agile, DevOps, CI/CD theory and practices).\n• Experience with cloud/private-cloud computing platforms such as Azure, AWS, GCP,….etc and microservices architecture.\n• Business proficient level of English (TOEIC, IELTS certificates or equivalent) to attend meetings with foreigner stakeholders, provide support to applications, help team to take the best decision and document your work.\n\nPreferred Skills\n• Expertise in system integration, enterprise architecture, and scalability.\n• Proven ability to thrive in an agile development environment following either XP, Scru and enterprise at scale framework like SAFe, Spotify, Scrum@Scale, LeSS, ..etc.\n• Knowledge of mobile development frameworks (e.g., Native Android/iOS, Flutter, ReactJS).\n• Experience with front-end development frameworks (e.g., Angular, React, Vue).\n• Having knowledge about finance industry, familiar various business domains of CRM, finance and accounting, loan origination & management, …etc is plus.\n• Skilled in generalizaion, ability in negotiation, working in presures, parallel tasking and processing.\n• Understanding about Data Goverance for enterprise organizaiton, having expericence in framework and practices is plus.\n• Industry certifications such as TOGAF or Azure, AWS Certified Solutions Architect is a plus.\n• Able to establish and develop standards and enterprise policy.\n\nWhy you\'ll love working here\nMôi trường làm việc chuyên nghiệp, cởi mở, chú trọng 5 giá trị cốt lõi: “Thông minh – Chính trực – Dũng cảm – Thân thiện – Hợp tác”\n• Thời gian làm việc từ thứ 2 – thứ 6 (40h/ tuần);\n• Chế độ làm việc Hybrid dành riêng cho CBNV khối Công nghệ;\n• Đồng nghiệp thân thiện, cởi mở với tư duy đề cao sự phát triển của mỗi cá nhân;\n• Văn phòng làm việc với không gian mở, rộng rãi, được cung cấp đầy đủ các trang thiết bị để phục vụ cho công việc.\n\nQuan tâm đặc biệt đến nhân viên:\n• Gói đãi ngộ cạnh tranh;\n• Hỗ trợ ăn trưa 1.200.000 VND/tháng; Hỗ trợ gửi xe 200.000 VNĐ/ tháng;\n• Quyền lợi chăm sóc sức khỏe đặc quyền bảo hiểm sức khỏe toàn diện SHBFC Care;\n• Nghỉ phép ngày sinh nhật;\n• Khám sức khỏe thường niên tại bệnh viện hàng đầu Việt Nam cùng các chế độ BHXH theo quy định của nhà nước;\n• Du lịch thường niên, hoạt động team building năm;\n• Tập trung hỗ trợ sự phát triển cá nhân:\n• Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng các cấp quản lý tài năng, giàu kinh nghiệm;\n• Cơ hội tham gia các dự án lớn, đi đầu trong lĩnh vực tài chính tiêu dùng;\n• Chính sách hỗ trợ các hoạt động học tập, trao đổi, chia sẻ kiến thức, giao lưu văn hoá (Training, Seminar...).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Gelex Tower, 52 Lê Đại Hành, phường Lê Đại Hành, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(699, 490, 2, 'Hybrid - Ruby On Rails Developer (Ruby, SQL)', 'Are you looking for an opportunity to make an impact, grow your skills and catapult your career with a growing company?\nMealSuite is looking for Backend Software Engineer to join our development team on our mission to revolutionize the continuum of care through our all-in-one foodservice management technology.\nOur International Development team\'s mission is to build innovative solutions that help our customers in senior living and healthcare industries enhance the mealtime experience for their patients and residents. In an industry that is constantly evolving, MealSuite’s software comes with a promise for continual innovation and growth with our customers. We never stop pushing boundaries and are always steering the future of our industries as innovation leaders in our space.\nAs part of our Development team, your mission is to stay on top of the latest releases, contribute to projects, and deliver the best quality solutions for our customers.\nYou will:\nDesign and develop new features for our best in class foodservice management software\nDesign, build and maintain efficient, reusable, and reliable Ruby code\nAnalyze client requirements to develop functional and technical software requirements\nMaintain and troubleshoot existing application\nCollaborates with development, QA, product and customer support teams all over the world\nSupervise and support other junior developers in fulfilling tasks as well as improving their skills\nPresent new and innovative ideas\nHelping team members with a collaborative spirit\nContributes to maintaining an open, friendly and innovative working environment for every member\nYour skills and experience\n4+ years of overall software development experiences using Ruby on Rails framework.\nStrong insight into Ruby syntax and its nuances.\nA knack for writing clean, readable Ruby code.\nExperience consuming and designing RESTful APIs.\nSolid SQL / relational database experience (Postgres is a plus).\nExperience working with Redis and Sidekiq.\nExperience with version control (Git, GitHub).\nSolid understanding of object-oriented programming.\nUnderstanding of Agile development and Scrum practices.\nA passion for helping people with a collaborative spirit.\nAbility to work as part of a team, understand the problems of other team members, and when necessary, go above and beyond the job description to work towards a broader team goal.\nWhy you\'ll love working here\nStock options\nVietnam labor law contract with full benefits\n13th months bonus\n1 day work remote every week\nUp to 22 days annual leave\n100% probation salary\nUnlimited access to Udemy Business online learning platform\nFree snacks & beverages\nFlexible working time\nTeam events\nAwesome and meaningful products', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cobi Tower 1, 69 Hoàng Văn Thái street, Phú Mỹ Hưng, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(700, 491, 2, 'Senior Full-stack Web and AI Developer', 'Top 3 reasons to join us\n- Supported AI tools\n- High salaries & 6-month HR reviews\n- Beautiful offices in convenient areas in HCMC, DN\n\nJob description\nAbout Us\nAt East Agile, we’re at the forefront of the AI revolution, developing innovative, AI-powered solutions that transform industries. Our impressive portfolio includes past collaborations with industry giants like Twitter and Samsung, and our current projects feature cutting-edge ventures such as and other forward-thinking AI startups. We’re looking for exceptional talent driven by a passion for integrating artificial intelligence into next-generation web applications.\n \nThe Opportunity\nAs our Senior Full-stack Web Developer, you’ll play a pivotal role in shaping the future of web development and AI technology. You’ll collaborate directly with founders and cross-functional teams to deliver sophisticated, scalable, and impactful web applications. Your work will not only enhance productivity but also set new standards in the industry.\nAt East Agile, we believe in empowering our developers to grow professionally. Many of our team members have transitioned into leadership roles, such as CTOs and CEOs, and have gone on to secure positions at top firms like Google. Joining East Agile is more than a job—it’s a career-defining opportunity that opens doors to elite job opportunities and leading graduate programs.\nYou will build the user facing frontend, the supporting backend infrastructure and the AI processes behind modern applications. This is an application development role, not a data scientist role.\n \nWhat You’ll Do\n- Collaborate & Innovate: Work hand-in-hand with founders and a dynamic team to deliver AI-enhanced web applications that bring innovative ideas to life.\n- Full-Stack Development: Build and maintain both front-end and back-end systems that seamlessly integrate to create a superior user experience.\n- Cloud Deployment: Develop, deploy, and maintain applications on leading cloud platforms, including AWS, GCP, and Azure, ensuring they support millions of users efficiently.\n- AI Utilization: Leverage advanced AI tools and methodologies, such as generative AI frameworks, vector/graph databases, Retrieval-Augmented Generation (RAG), and large language models (LLMs), to boost development efficiency and code quality.\n- Mentorship & Growth: Contribute to a collaborative environment, sharing knowledge and fostering continuous learning among team members.\n\nYour skills and experience\nWhat We’re Looking For\n- Experience:\n  - Minimum of 2 years of professional experience in full-stack web development, with a proven track record of building scalable and resilient web applications.\n- Technical Skills:\n  - Proficient in Python, with experience in frameworks such as Flask or Django.\n  - Strong understanding of modern programming languages like Go, Rust or Move.\n  - Familiarity with cloud environments, including hands-on experience with AWS, GCP, and Azure.\n  - Experience with AI-driven development, including advanced prompt engineering, generative AI, and the ability to leverage AI tools for software development.\n  - Understanding of vector and graph databases, RAG, and working with multiple LLMs is a plus.\n- Methodologies & Mindset:\n  - Strong foundation in modern software design principles and test-driven development.\n  - Proven ability to quickly adapt to new technologies and methodologies in a fast-paced, innovative environment.\n  - Experience working in an agile development environment using methodologies like SCRUM and Extreme Programming is preferred.\n- Communication:\n  - Excellent verbal and written communication skills in English, with the ability to break down complex technical concepts into clear, actionable insights.\n- Education:\n  - A degree in Computer Science, Mathematics, or a related field from a recognized institution is preferred. Practical experience and a strong portfolio of work are highly valued.\n\nWhy you\'ll love working here\nWhat We Offer\n- Competitive Compensation:\n   - A salary range of $1,500 - $4,000 per month, reflective of your experience and capabilities.\n- Bonuses & Benefits:\n   - End-of-year Tet bonus.\n   - Comprehensive health insurance.\n   - 15 days of annual leave.\n   - A balanced 40-hour work week with flexible hours.\n- Professional Growth:\n   - Continuous learning opportunities, such as internal workshops and industry conferences.\n   - A collaborative and dynamic work environment that fosters innovation and creativity.\n- Work Environment:\n   - A vibrant, modern office space in Ho Chi Minh City (District 10 and Thao Dien Area) or Da Nang.\n   - Remote work options are available for senior employees with a proven track record of success.\n\nJoin Us\nIf you’re excited about the challenge of building AI-powered, scalable web applications and shaping the future of technology, we’d love to hear from you. Apply now to join a team that values innovation, collaboration, and the relentless pursuit of excellence.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '16 Tam Dao, District 10, Ho Chi Minh; NA, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(701, 492, 2, 'Fullstack Software Engineer (Golang, ReactJS)', 'Top 3 reasons to join us:\n1. Competitive salary and bonus\n2. Young and innovative working environment\n3. Work with the brightest minds\n\nJob description:\n1. Tham gia phát triển sản phẩm của công ty, xây dựng dựa trên kiến trúc micro-services và vận hành trên nền tảng Kubernetes\n2. Tham gia sâu vào quy trình phát triển sản phẩm, từ lên ý tưởng, làm rõ yêu cầu, thiết kế giải pháp công nghệ và phát triển tính năng. Phối hợp và tư vấn giải pháp công nghệ, cùng các thành viên khác thiết kế sản phẩm hợp lý, mang lại giá trị cao về business.\n3. Code quality: chủ động và có trách nhiệm trong việc nâng cao chất lượng code thông qua automated testing / refactor tech debts / code reviews. Áp dụng các kỹ thuật best practice như DRY, KISS, etc. vào thực tế để có code base đẹp, dễ maintain và dễ tiếp cận với người mới. Tham gia review code của các thành viên khác / projects khác để hiểu rõ mọi hệ thống của công ty cũng như nâng cao tiêu chuẩn chất lượng code của cả team.\n4. Chủ động nghiên cứu các công nghệ mới, sẵn sàng chia sẻ thông tin và kiến thức cho các thành viên khác cùng phát triển, và đưa các công nghệ mới vào ứng dụng tại các dự án của công ty.\n5. Đóng góp ý kiến, cải thiện và nâng cao hiệu quả của quy trình phát triển phần mềm theo Agile và Scrum.\n\nYour skills and experience:\n1. Có kiến thức nền tảng tốt về khoa học máy tính và phát triển phần mềm.\n2. Hiểu rõ các kiến thức cơ bản, nâng cao, best practices trong việc phát triển các ứng dụng cả server side và client side.\n3. Nhiều hơn 2 năm kinh nghiệm phát triển phần mềm, có thể phát triển hoàn chỉnh một sản phẩm từ việc viết API Restful, GraphQL... đến việc dựng giao diện người dùng phức tạp.\n4. Có kinh nghiệm với việc viết unit test, integration test, test driven development và chủ động thực hành những practice về test để đảm bảo sản phẩm trước khi bàn giao cho tester và xa hơn là user đã không còn có những lỗi hiển nhiên.\n5. Kỹ năng giao tiếp tốt, có khả năng giải thích, trình bày kiến thức một cách rõ ràng, dễ hiểu.\n6. Hiểu và ứng dụng được CI/CD.\n7. Hiểu và ứng dụng được các principles trong thiết kế, phát triển phần mềm.\n8. Điểm cộng: Kinh nghiệm làm việc với K8s là một lợi thế.\n\nWhy you\'ll love working here:\n1. Thu nhập cạnh tranh trong ngành + thưởng theo hiệu quả công việc\n2. 12 ngày phép/năm, bảo hiểm sức khỏe PVI cá nhân và ưu đãi phí cho người thân.\n3. Môi trường đồng nghiệp cởi mở, năng động, hỗ trợ đồng đội cùng phát triển, tập trung vào hiệu quả công việc, tối ưu phát triển công nghệ, tối ưu vận hành.\n4. Được chịu trách nhiệm làm các tính năng quan trọng của sản phẩm (không phải dự án maintain). Thử thách với chuỗi sản phẩm có yêu cầu UX và tính thẩm mỹ cao.\n5. Cơ hội phát triển sự nghiệp rõ ràng tại một trong các startup đang phát triển nhanh nhất VN (vốn hoá công ty hiện đạt 150 triệu $)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 tòa nhà Pax Sky số 63-65 Ngô Thì Nhậm, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(702, 370, 2, 'Senior Software Engineer (Java, English)', 'Top 3 reasons to join us\n- Flexible working time \n- On-site opportunities in the US, UK\n- Healthcare insurance for employee & 2 dependents\n\nJob description\nPRIMARY RESPONSIBILITIES INCLUDE\n- Designing and developing high quality distributed applications of FORTNA Warehouse Execution System (WES) – a real-time processing system.\n- Developing Proof of Concept implementations to establish the feasibility and demonstrating the application of new technology to new products or extensions to existing products.\n- Performing activities for hiring and training new developers.\n- Taking the lead in designing, implementing, and testing new software products and technologies.\n- Participating in designing, developing, and delivering solutions for end-users and Clients.\n- Assisting Software QA and Infrastructure Engineers in Qualifying, Deploying, and Packaging Company’s software product and libraries.\n- Assisting Software QA in the design and development of test plans and frameworks.\n- Maintaining high-quality software source code and design documentation.\n- Providing remote support and troubleshooting for clients\' systems.\n\nYour skills and experience\nREQUIRED QUALIFICATIONS\n- Bachelor’s degree in Computer Science, Engineering, or related field\n- 6+ years of relevant experience in Java development, with solid expertise in:\n- Network Programming, Multi-threading, and Socket Programming\n- Microservices architecture, DLL plug-in libraries in C++, pthreads, and ActiveMQ\n- Hands-on experience with:\n- DevOps practices: CI/CD, containerization (Docker), automation (Jenkins or similar), and infrastructure-as-code (Terraform, Ansible)\n- RPM Package Manager, auto-build tools, and source control (e.g., Git)\n- Experienced with some mix of SQL and Oracle, TCP/IP, JMS\n- Strong grasp of Object-Oriented Analysis and Design (OOAD), including design patterns and software development principles\n- Good foundation in Data Structures and Algorithms\n- Proficiency in English (both written and spoken)\n- Strong interpersonal, time management, and problem-solving skills\n- A collaborative team player who works effectively with both technical and non-technical stakeholders.\n\nNice to have:\n- Time sensitive, high transaction-based processing experience\n- Experience with other open-source operating systems and development tools\n- Software development life cycle (SDLC) experience with a sizeable product/project\n- Excellent oral and written communication skills and the ability to clearly articulate to project members and stakeholders.\n- Guiding junior engineers\n- Having the desire to pick up and learn new technical skills.\n\nNOTE: We appreciate all applications; however, only shortlisted candidates will be contacted.\n\nWhy you\'ll love working here\nBeing a part of FORTNA, you are offered:\n- Flexible working hours (5 working days/week), no timekeeping \n- Competitive salary with annual review \n- 100% official salary during the probation period; 13th-month salary\n- Onsite opportunities in the US, UK (1-3 months/year)\n- Sponsored training and self-development opportunities (English, PMP, CSM...)\n- 10% paid working time per week for personal development (attending soft skill courses, reading books, working on side projects, self-teaching any new IT-related concepts)\n- Bao Viet Premium health-care insurance for employee and 2 dependents \n- Modern facilities with Laptop Dell Precision 7670 chip i9-12950HX, Ram 64GB, SSD 512GB, RTX A2000 + 2 monitor Dell Ultrasharp U2422HE\n- Annual luxury vacations, bi-monthly Happy Hour\n- Exciting company outings/events and team building activities, \n- Supportive, international, dynamic working environment and talented, culturally diverse teams\n- A large pantry full of snack, drink, and seasonal fresh fruit\n\nTake the deal and let\'s explore many more benefits!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nam Building, 22D Dương Đình Nghệ, Yên Hoà, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(703, 493, 2, 'Senior| Mid UI UX Designer (Communicate in English)', 'Job description\n- Responsible for the entire design.\n- Responsive layout when designing landing page, adaption wireframes.\n- Gather and evaluate user requirements in collaboration with clients, product managers and engineers.\n- Commitment with your timeline.\n- Do best your assigned tasks.\n\nYour skills and experience\n- 3 - 5 years of experience.\n- Ability to communicate in English with Foreigner clients\n- Expert knowledge of Figma, Sketch, or XD, Photoshop, AI, Illustrator.\n- Specialize in layout and colors. The portfolio or prototype is a must. The portfolio should showcase a good mix of web and mobile applications.\n- Proven ability to implement usable and attractive interfaces.\n- Excellent time management skills and ability to meet deadlines.\n- Ability to complete assignments quickly, efficiently, and precisely.\n- Ability to research website (Ui/ UX, branding, User personas, competitor, SEO keyword, key takeaway… )\n\nWhy you\'ll love working here\n- Our team members are awesome, fun, and most of all, super talented!\n- 13-month salary per year\n- Salary will be reviewed 9 months once time per year\n- Bonus for birthday: 500K\n- Bonus at the end year depends on dedication, excellence, bringing higher benefits.\n- Monthly company party.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3 Toà nhà RedHomes, B82 Bạch Đằng,Phường 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(704, 342, 2, 'Software Developer (.Net, C#, SQL)', 'Top 3 reasons to join us\n- Extremely competitive salary.\n- Healthcare insurance package.\n- 13th month and productivity bonus.\n\nJob description\n- Lead in designing, coding, testing, debugging, configuring, and documenting new software utilizing technologies for the project assigned.\n- Work in an Agile software development environment (using Scrum)\n- Refactor existing software.\n- Able to independently design quality solutions for large features.\n- Collaborate with Product Management, Software Quality Assurance, and other development teams to ensure that solutions are efficient, consistent and fulfill business needs.\n- Training and Mentoring Junior Team Member\n\nYour skills and experience\nQUALIFICATIONS AND EDUCATION REQUIREMENTS\n- Bachelor of Science degree in Computer Science or related field (Major: Computer Science, Architecture, Structure Engineer). Additional, equivalent work experience may be substituted for the degree requirement \n- 3-8 years of experience working as a Software Engineer and related roles;\n- C#, .NET Framework, .NET, MSSQL, WPF and other development tools and languages as required.\n- Win Form Application\n- Testing: Familiar with all test types.\n- Good at 2D or 3D mathematics.\n- Familiar with Software Development Life Cycle (SDLC).\n- English: Ability to understand written and spoken English at an advanced level.\n\nWhy you\'ll love working here\n- Extremely competitive salary.\n- 13th month & productivity Bonus.\n- Yearly salary review.\n- Healthcare insurance package.\n- 24/24 Personal accident insurance.\n- State-of-the-art office environment.\n- Yearly outing.\n- Detailed induction, training and on-going career development.\n- Opportunity for overseas training and travel.\n- English training programs.\n- 5-day week.\n- Flexible start-times.\n- Free lunch.\n- Free parking.\n- Full Social Club including gym, yoga, football, badminton, swimming.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'A5 Building, E- Office Park, Road, Tân Thuận, Đ. Sáng Tạo, Tân Thuận Đông, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(705, 494, 2, 'Senior Full-stack Developer (C# ASP.NET, React)', 'Arbin Instruments currently has vacancies for a self-driven, passionate and results focused Senior Full-stack Developer to be part of our specialist team that will be dedicated to develop and maintain the software that supports the Arbin’s products.\n\nYou will have to work in an agile environment, collaborating with highly skilled people who are proactive, passionate about technology and results driven.\n\nEssential Duties & Responsibilities\n· Responsible for designing, coding, and implementing software solutions (both backend and frontend) using modern techniques and programming languages.\n· Provides high-level database development assistance in creating specific applications for businesses.\n· Works harmoniously in a cross-functional team comprising managers, supervisors, business analysts, systems personnel, network staff, and other developers in ensuring the delivery of software solutions as planned, within set budget, and timely.\n· Provides excellent customer service by responding to and assisting with help desk calls to resolving issues.\n· Performs administrative duties as well as some project management tasks.\n\nPrimary Objectives\n· To add more R&D manpower on the development of data processing applications to Arbin’s products\n\nSpecific Responsibilities of the job (Optional)\n· No\n\nYour skills and experience\n· Sound knowledge of traditional as well as agile software development methodologies.\n· Ability to apply an object-oriented programming language in creating applications.\n· Experience working with ASP.NET core\n· Experience working with React + Vite + Typescript, Tailwind, Antd.\n· Proficient in building and maintaining dynamic and interactive frontend elements\n· Experience working with PostgreSQL, MS SQL Server\n· Experience in programming with communication protocols, e.g. TCP/IP, UDP.\n· Experience working with Amazon cloud, Google cloud, Azure cloud.\n· Experience working with Jira Collaboration Tools.\n· Nice To Have Experience working with CI-CD (Continuous Integration-Continuous Deployment) using Docker, K8S.\n· Nice To Have Experience in other languages, e.g. C#, C++, Python, Golang.\n· UI/UX Design experience with Figma or similar tools is a plus\n\nEducation and Experience\n· Degree or equivalent experience: Bachelor or above.\n· Years of experience: at least 5 years.\n· Specialized training in: Computer Science or Computer Engineering or related.\n· Active affiliations: No requirement.\n· Other requirements (certifications and so forth): No.\n· English requirement: confident in reading and writing, listening/speaking fine for presentation.\n· Chinese language is a plus.\n\nWhy you\'ll love working here\n• As a privately-owned company, Arbin promotes a family/team-oriented culture and a friendly atmosphere\n• Arbin offers 02 new Full HD 27 inch monitor screen, 01 DELL laptop 1TSSD and 01 professional swivel chair per staff\n• Full salary probation (02 months)\n• Compulsory insurance (BHXH, BHYT, BHTN,…)\n• Bao Viet Healthcare Insurance Package\n• Good career growth opportunities with interesting and challenging projects\n• Competitive salary depending on skills and capabilities\n• Annual performance review: once/year\n• Additional bonuses based on the performance\n• English-speaking environment, with opportunity to be part of innovation team and work in global projects\n• Tea break time with light beverage and food for staffs\n• Working time: Monday-Friday 8:00-17:30 , lunch time: 1,5 hour. Off on Saturday.\n• 12 days annual leaves & public holidays\n• Year-End Party, New-Year Party, gift for Tet, team-building trip.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '205 GS1, Dong Hoa, Di An, Binh Duong (Sát cạnh Thủ Đức), Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(706, 475, 2, 'QA Tester & Business Analyst – FoodTech SaaS Full-time', 'Help Shape the Future of MenuWise\n\nWe’re building a smart platform that helps professional chefs manage ingredients, recipes, and costs using accurate, rich food data. We’re looking for a QA Tester & Business Analyst who’s sharp, curious, and passionate about food and data.\n\nWhat You’ll Do\n- Take ownership of our App Administration site\n- Test new features and UI across our app\n- Work with chefs and food experts to research and identify improvements to our Admin site data\n- Suggest new fields, data and logic to enrich and expand our ingredient data\n- Help define and write test cases for key user flows (specify automated testing flows for Devs to implement)\n- Participate in agile sprints, giving feedback on priorities and quality\n- Ensure all details—big and small—are polished and user-friendly\n\nWhy Join Us\n- Help chefs around the world do their job better\n- Work on a global SaaS platform from Vietnam\n- Learn about culinary data, ingredient science, and UI testing\n- Be paid to practice your English every day!\n- Work with cutting edge tech, shaping the future of food-service around the world\n\nYOUR SKILLS AND EXPERIENCE\nYOU MIGHT BE A GREAT FIT IF YOU:\n- 2+ years in QA, testing, or business analysis\n- Strong English (spoken and written)\n- Excellent attention to detail and structured thinking\n- Interest in food, ingredients, or nutrition (or willingness to learn)\n- Experience with agile teams and SaaS platforms\n- Know how to use AI prompts to be more productive and efficient\n- Bonus: Experience with big data or machine learning features\n\nOUR CULTURE\nWe’re a team of 11 across Vietnam and the Philippines, and we genuinely love what we do. You’ll be joining a tight-knit group that values:\n- Working smart over working hard.\n- Clear communication as our #1 tool for collaboration.\n- Work-life balance, with local working hours and no late-night calls.\n- Celebrating wins, big or small.\n- Innovation and fresh thinking.\n- Teamwork, because we all succeed together.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hoang Dao Thuy, Trung Hoa Ward, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(707, 495, 2, 'Fresher/Junior Software Devs in C/C++ Up to $2,000', 'Fresher/Junior profiles are both welcomed (fresh newcomers will be trained and guided by mentor)\nBasic knowledge to develop Windows-based C/C++ applications in digital data processings by using OpenCV\nOptimize the source program and minimize the issues to make better software products\nReport and present about works and ideas.\n\nGeneral Requirements:\nBachelor’s or higher degree in Computer Science, Electronics, Information Science or relevant departments in Physics, Mathematics, other Engineerings.\nHands-on experience with Windows-based C/C++ applications.\nBasic English in speaking, listening and reading.\nGood logical thinking & self-learning skills.\nGood team player and communication skills.\nExperience with Git or other source code management tool.\n\nNice to have:\nFresher or Junior with 01- 02 working years in programming.\nGood knowledge about Software Development Process.\nHave abilities to learn quickly, design efficiently, and write clean code.\nGood analytical and mathematical skills to develop new algorithms. Hands-on experience in image processing, OpenCV, object detection.\nGood team-work spirit working with other Developers and Client to ensure best user experience.\n\nWhy you\'d love working here:\nClose one-on-one mentorship.\nCooperative and motivating environment that encourages self-autonomy.\nCompetitive Salary & Benefits that increase with experience over time.\nChallenging environment working with high-end leading technology.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3rd Floor, 3D Creative Center Building, No 3, Duy Tan Street, Dich Vong Hau Ward, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(708, 496, 2, '(Senior) Automation Tester (QA/QC, Java, JavaScript)', 'Job description\nAs a (Senior) Automation Tester, you\'ll lead automation efforts for web, mobile, and API platforms, ensuring high-quality software. You\'ll also advocate for shift-left testing and shape the testing culture, making a direct impact on software quality and delivery.\n\nKey Responsibilities:\n- Develop and maintain automated tests (Playwright, Selenium and Cypress) for web and API.\n- Integrate tests into CI/CD pipelines (Jenkins, GitLab CI).\n- Collaborate with cross-functional and off-shore teams to align testing with business goals.\n- Lead test strategies for performance, stability, and security.\n- Contribute to technical roadmaps, improving automation practices.\n- Participate in Agile ceremonies (e.g., sprint planning, stand-ups).\n- Mentor junior testers on best practices and continuous improvement.\n\nYour skills and experience\nKey Requirements:\n- 3+ years of experience in automation testing.\n- Hands-on experience with automation frameworks (e.g., Playwright, Selenium, and Cypress).\n- Strong programming skills in one or more of (JavaScript, TypeScript, Java or Python) for writing robust, scalable tests.\n- Experience with CI/CD pipelines and version control (e.g., Jenkins, GitLab CI).\n- Experience in API testing with tools like Postman, Swagger, and SoapUI.\n- Familiarity with Agile (e.g., Scrum/Kanban), TDD, and BDD.\n- In-depth knowledge of test automation principles, design patterns, and best practices.\n- Fluent English communication skills.\n- Good problem-solving, communication, and collaboration skills.\n- Strong analytical skills and attention to detail.\n- Proactive and result-driven, with organizational skills.\n\nNice to have:\n- Experience with performance testing tools (e.g., JMeter, LoadRunner).\n- Familiarity with security testing practices (e.g., vulnerability scanning, penetration testing).\n- Familiarity with containerized testing environments.\n- Experience with cloud technologies (e.g., AWS).\n- Knowledge of DevOps/SecOps practices.\n\nWhy you\'ll love working here\n- Attractive salary and bonuses (Annual and Performance Bonus)\n- Ensure private healthcare insurance package, yearly medical check-up, support allowance...\n- Total 23 days of paid annual leave\n- High-ownership working environment, challenging projects, on-the-job coaching, and training programs\n- Great-place-to-work activities (company trips, sports clubs...)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Emporium, 3rd Floor, 184 Le Dai Hanh, Ward 15, District 11, Ho Chi Minh city, District 11, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(709, 497, 2, '[HCM/DN] Junior Automation Tester (Playwright/Katalon)', 'We are looking for an Automation Test Engineer to join our team. In this role, you will:\n\n- Execute all testing activities to improve product quality, work closely with the team (developers, business analysis, customer service, operation, etc.) to deliver product success\n- Address the test automation needs in a methodical, detail-oriented manner with the help of robust analytical skills and problem-solving capacity\n- Automate functional, regression and performance acceptance tests\n- Have complete responsibility for enhancing end-to-end automated test coverage\n- Participate in sprint planning and work closely with the Scrum team to analyze requirements and provide necessary test recommendations\n\nYour skills and experience\n\nQualifications\n\nGeneral requirements:\n\n- Intermediate or higher English proficiency.\n- 2+ years of hands-on experience in automation testing.\n- Strong analytical, troubleshooting, and problem-solving skills.\n- Effective communication and teamwork in English-speaking environments.\n- Proactive, eager to learn, and adaptable to new frameworks and tools.\n- Comfortable delivering results under deadlines and changing priorities.\n\nTechnical requirements:\n\n- Proficiency in developing automated tests for API, UI automation, web and mobile applications.\n- Strong domain knowledge of the software development process, especially the software testing process.\n- Solid testing experiences (requirement analysis, test strategy, test approach, test plan, test techniques included black box, risk-based, exploratory, non-UI testing, etc.).\n- Experience in creating and running automated tests using testing frameworks like Katalon, Playwright, Selenium, Appium, etc.\n- Proficient in at least one programming language for test automation (JavaScript, Python, or Java preferred).\n- Hands-on experience in using test tools like TestNG, Mocha, Jasmine, Nightwatch, etc.\n- Experience on using tools: Postman, Git, IntelliJ IDEA, soapUI, cURL, fetch, etc.\n\nNice to have:\n\n- Experience testing live-streamed media or video platforms.\n- Exposure to additional frameworks like Cypress, or Detox.\n- Prior use of cloud-based mobile device farms.\n- Familiarity with performance or security testing automation.\n\nWhy you\'ll love working here\n\nPerks You\'ll Enjoy \n\n- Working in one of the Best Places to Work in Vietnam\n- Building large-scale & global software products\n- Working & growing with Passionate & Talented Team\n- Diverse careers opportunities with Software Outsourcing, Software Product Development, IT Solutions & Consulting\n- Attractive Salary and Benefits\n- Two performance appraisals every year and performance bonus\n- Remote work available and flexible working time\n- Onsite opportunities: short-term and long-term assignments in North American (U.S, Canada), Europe, Asia.\n- Various training on hot-trend technologies, best practices and soft skills\n- Premium healthcare insurance for you and your loved ones\n- Company trip, big annual year-end party every year, team building, etc.\n- Fitness & sport activities: football, tennis, table-tennis, badminton, yoga, swimming…\n- Joining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,…\n- Free in-house entertainment facilities (foosball, ping pong, gym…), coffee, and snack (instant noodles, cookies, candies…)\n\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '02 Tan Vien, ward 2, Tan Binh, Ho Chi Minh; 2/9 Street, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(710, 498, 2, 'Junior Frontend Developer (Angular/ JavaScript)', 'Job description\n- Tham gia phát triển các dự án về Web, xây dựng các chức năng front-end của Website, Web application.\n- Phối hợp với các back-end developers và web designers để cải thiện tính khả dụng\n- Báo cáo tiến độ và tình trạng công việc cho quản lý.\n- Nghiên cứu, tìm hiểu các công nghệ về HTML/CSS Javascript mới nhất để áp dụng cải tiến sản phẩm.\n\nYour skills and experience\nYêu cầu:\n- Tốt nghiệp các ngành liên quan đến CNTT.\n- Trên 1 năm KN kinh nghiệm lập trình Javascript\n- Thành thạo các ngôn ngữ phát triển web: HTML, CSS và JavaScript.\n- Có kinh nghiệm về Angular (bắt buộc)\n- Hiểu biết cơ bản về các web frameworks và thư viện web (React, Angular hoặc Vue.js).\n- Hiểu biết cơ bản về công nghệ, ngôn ngữ lập trình hoặc công cụ liên quan\n- Kỹ năng giải quyết vấn đề tốt và tỉ mỉ, ham học hỏi\n- Khả năng giao tiếp và làm việc nhóm tốt, trách nhiệm cao trong công việc\n- Welcome các bạn đam mê công nghệ, phát triển web, ham học hỏi và luôn mong muốn cập nhật những công nghệ mới nhất.\n- Có kiến thức cơ bản về UX/UI\n- Có kiến thức về Responsive Design\n\nƯu tiên\n- Ứng viên mạnh về thiết kế giao diện\n- Ưu tiên ứng viên nữ\n\nWhy you\'ll love working here\n- Lương & Thưởng\n- Chế độ tăng lương, thưởng tháng 13 hằng năm, mức lương thưởng hấp dẫn phù hợp với năng lực.\n- Đào tạo\n- Thường xuyên tổ chức những buổi training, rèn luyện kỹ năng lập trình.\n- Phúc lợi\n- Du lịch công ty hằng năm\n- Ngoài chế độ bảo hiểm cơ bản theo quy định của luật Lao Động, công ty còn tham gia Bảo hiểm sức khỏe đặc biệt cho nhân viên có hợp đồng dài hạn với công ty.\n- Khám sức khỏe định kỳ hằng năm\n- Khác\n- Trà, coffee... miễn phí\n- Hoạt động vui chơi, tiệc cuối năm, giáng sinh, tiệc sinh nhật hằng tháng\n- Được hưởng phúc lợi đặc biệt như tiền mừng kết hôn, tiền mừng khi sinh con...\n- Hoạt động thể thao (cầu lông, bóng đá...)\n- Môi trường làm việc: đồng nghiệp trẻ trung, năng động, tích cực học hỏi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '15.01 Khối văn phòng Cao ốc Thái An, 2290 Quốc Lộ 1A, Phường Trung Mỹ Tây, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(711, 499, 2, 'Manual Software Tester (QA/QC from 3yrs Exp)', 'CƠ HỘI LÀM VIỆC VỚI PRODUCT HỆ THỐNG LỚN - CAREER PATH RÕ RÀNG - WORK-LIFE BALANCE!!!\nMÔI TRƯỜNG PHÁT TRIỂN MỚI NHẤT: SỬ DỤNG AI (GEMINI/ CHAT GPT/ GITHUB COPILOT)\n\nRakus Việt Nam là công ty 100% vốn đầu tư từ RAKUS Co., Ltd. - công ty nổi tiếng hàng đầu tại Nhật Bản cung cấp các dịch vụ đám mây (SaaS), giúp các doanh nghiệp điều hành hoạt động của mình một cách nhanh chóng, tiện dụng nhất.\nChúng tôi đang tuyển dụng 2 vị trí Middle/Senior Manual Tester: \nLÀM VIỆC OFFLINE FULLTIME TẠI VĂN PHÒNG HEADOFFICE QUẬN 12.\nTham gia team phát triển Hệ thống Web Application đang được sử dụng bởi hơn 10,000 Công ty tại Nhật Bản.\n\nNếu:\n・Bạn đang là Middle/Senior Manual Tester và mong muốn phát triển thành Team Leader trong tương lai.\n・Bạn mong muốn môi trường làm việc lâu dài (ít nhất 3 năm trở lên)\n・Bạn có năng lực tập trung và thích tìm hiểu sâu về 1 hệ thống.\n\nHãy đến với Rakus Việt Nam.\nLà một Tester của Rakus VN, bạn sẽ chịu trách nhiệm đảm bảo chất lượng phần mềm & sản phẩm Web Application của chúng tôi, thực hiện nhiệm vụ kiểm thử như sau:\n- Tạo test case chi tiết và tiến hành kiểm thử phần mềm.\n- Thực hiện test, log lỗi và theo dõi tiến độ fix bug, gồm: Functional test, regression test, smoke test, Monkey test, integration test.\n- Quản lý và theo dõi vòng đời các vấn đề trong hệ thống\n- Kiểm soát chất lượng đảm bảo hệ thống/sản phẩm được tạo đúng như thiết kế\n- Cải tạo/cập nhật các test cases hiện có để tăng hiệu quả và độ tin cậy\n- Phối hợp chặt chẽ nhóm lập trình để đảm bảo chất lượng sản phẩm\n- Báo cáo với Project Manager/ Project leader, tương tác với team phát triển để hiểu sản phẩm và các tính năng của chúng.\n\nYêu cầu cơ bản:\n• Có từ 3 năm kinh nghiệm trở lên trong lĩnh vực Test Manual.\n• Hiểu được các ứng dụng trên nền tảng Cloud, có kinh nghiệm trong kiểm thử Web app, đặc biệt là kiểm thử các Web app dựa trên ngôn ngữ Java.\n• Có khả năng đọc hiểu tài liệu tốt.\n• Có khả năng trình bày tốt khi viết test case.\n• Có kiến thức tốt/ kinh nghiệm về quy trình và kỹ thuật Kiểm thử, có các kỹ năng kiểm thử (viết test cases, thực hiện Testcases, phát hiện lỗi, report lỗi, kiểm tra lỗi)\n• Kỹ năng phân tích, điều tra sự ảnh hưởng tốt.\n• Khả năng làm việc độc lập và cẩn thận, tỉ mỉ\n• Khả năng tự quản lý và quản lý thời gian tốt, kỹ năng giải quyết vấn đề tốt\n• Có tinh thần trách nhiệm trong công việc\n• Kỹ năng giao tiếp tốt.\n\nƯu tiên:\n• Có kiến thức automation testing hoặc nền tảng về chuyên môn IT\n• Có thể đọc hiểu tiếng Anh cơ bản\n\nĐược cung cấp 100 % New Laptop ram 16GB + 2 màn hình cho nhân viên mới.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, Tòa nhà QTSC Building 01, Đường số 14, Lô số 34, Khu Công viên phần mềm Quang Trung, Phường Tân Chánh Hiệp, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(712, 222, 2, 'Automation Tester (Java, Oracle, Selenium, SQL)', '• Tham gia kiểm thử, test tự động (automation) các phần mềm, hệ thống phần mềm.\n• Xây dựng kịch bản automation test, xây dựng tool test tự động cho ứng dụng: web, mobile\n• Thực hiện test các sản phẩm, dịch vụ theo yêu cầu.\n• Nghiên cứu và cập nhật các công cụ test và kiến thức mới hỗ trợ cho công việc.\n• Làm việc nhóm hoặc độc lập, giao tiếp với cấp trên và thành viên liên quan đến công việc test.\n*** Chi tiết công việc sẽ trao đổi thêm trong quá trình phỏng vấn ***\n\n• Có ít nhất 2 năm kinh nghiệm automation web và test cho mobile (Android, iOS).\n• Có kinh nghiệm test auto với database SQL\n• Kiến thức vững về SDLC\n• Kiến thức về CI/CD và quy trình tự động hóa kiểm thử.\n• Ngôn ngữ lập trình: Thành thạo Java\n• Cơ sở dữ liệu: Thành thạo Oracle\n• Automation: Thành thạo Selenium\n+ Kinh nghiệm sử dụng Selenium WebDriver để kiểm thử các ứng dụng web.\n+ Kinh nghiệm thiết lập và duy trì Selenium Grid cho việc kiểm thử trên nhiều môi trường.\n• Có khả năng làm việc nhóm, luôn sẵn sàng hỗ trợ các thành viên khác trong dự án.\n• Phối hợp với các nhóm phát triển và QA để thu thập yêu cầu kiểm thử, phân tích lỗi và cải tiến quy\ntrình kiểm thử.\n• Ứng viên có kinh nghiệm test các dự án làm các dự án ngân hàng là một lợi thế\n\n- Thu nhập thỏa thuận, tương xứng với năng lực và đóng góp.\n- Được trải nghiệm và thực hiện nhiều nhiệm vụ, vị trí khác nhau khi triển khai dự án.\n- Môi trường trẻ trung, năng động, điều kiện làm việc hiện đại, văn minh\n- Được tham gia nhiều hoạt động phong trào được công ty tổ chức thường xuyên như: CBL bóng đá, CLB cầu lông, Teambuilding, Du lịch hè, Tiệc sinh nhật công ty, Tiệc Tổng kết năm v.v...\n- Được công ty hỗ trợ chi phí học và thi chứng chỉ chuyên ngành phục vụ cho công việc.\n- Cơ hội thăng tiến cho các bạn trẻ có năng lực.\n- Hưởng đầy đủ các chế độ theo luật lao động hiện hành và các chính sách đãi ngộ tốt.\n- Được hưởng chương trình chăm sóc sức khoẻ thường niên SEATECH HEALTHCARE với đầy đủ quyền lợi thăm khám ngoại trú và hạn mức bảo lãnh viện phí lên tới 180tr/năm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '98 Nguy Nhu Kon Tum, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(713, 449, 2, 'Chuyên gia Quản trị Cơ sở dữ liệu - K.CNTT', 'Top 3 reasons to join us\n• Môi trường năng động và cơ hội thăng tiến\n• Chế độ lương thưởng hấp dẫn\n• Bảo hiểm sức khỏe cao cấp (bảo hiểm toàn diện)\n\nJob description\nNhiệm vụ chính\n• Nhận phân công công việc của lãnh đạo có thẩm quyền, lập kế hoạch công việc chi tiết và báo cáo tiến độ, kết quả công việc cho lãnh đạo;\n• Tham gia các hoạt động đào tạo, hướng dẫn, trao đổi kiến thức, sinh hoạt chuyên môn và các hoạt động sinh hoạt chung khác trong Khối.\n\nNhiệm vụ chuyên môn:\n• Chịu trách nhiệm quản trị, vận hành các hệ thống quản trị cơ sở dữ liệu và hệ thống liên quan đảm bảo hoạt động liên tục;\n• Triển khai các tiêu chí giám sát các hệ trên các công cụ đã có; Triển khai các thay đổi theo đúng quy trình quản lý thay đổi của PVcomBank; Phát hiện, tiếp nhận và xử lý các sự cố, yêu cầu hỗ trợ theo đúng các quy trình quản lý sự cố và vấn đề của PVcomBank; Thực hiện sao lưu dự phòng và kiểm thử định kỳ dữ liệu sao lưu dự phòng theo các quy định, quy trình, hướng dẫn của PVcomBank; Xây dựng kế hoạch, thực hiện diễn tập triển khai và định kỳ rà soát chiến lược và kế hoạch chi tiết phục hồi sau thảm họa (DRP);\n• Nghiên cứu và đề xuất các giải pháp tối ưu công tác vận đảm bảo an toàn tính liên tục, tuân thủ các tiêu chuẩn quản lý độ tin cậy (SRE); Nghiên cứu và đề xuất các tiêu chuẩn về hệ thống quản trị, vận hành và các giải pháp công nghệ nhằm nâng cao chất lượng dịch vụ và năng lực công nghệ của PVcomBank; Quản lý công tác bảo trì, bảo hành; Định kỳ thực hiện cập nhật các bản vá được cung cấp từ nhà cung cấp theo quy trình quản lý bản vá, quản lý thay đổi của PVcomBank; Phát hiện, đánh giá các rủi ro về mặt kĩ thuật; Tham gia triển khai các dự án; Lập kế hoạch, thực hiện đánh giá, báo cáo, đề xuất danh mục các chương trình nâng cấp khả năng đáp ứng của hệ thống (system capacity), đáp ứng nhu cầu tăng trưởng kinh doanh liên tục của PVcomBank;\n• Đánh giá hiệu năng định kỳ và đưa ra phương án xử lý đảm bảo chất lượng dịch vụ; Tư vấn, khuyến nghị về mặt kỹ thuật và chính sách nhằm tuân thủ theo các tiêu chuẩn, quy định của pháp luật; Cung cấp đầy đủ, kịp thời các thông tin, tài liệu cho các đơn vị thuộc PVcomBank khi có yêu cầu; Tham gia xây dựng và cải tiến quy định, quy trình, hướng dẫn liên quan đến quản trị, vận hành, thực hiện công việc tuân thủ đầy đủ theo quy định, quy trình, hướng dẫn đã được phê duyệt;\n• Nghiên cứu và đề xuất các giải pháp công nghệ mới phù hợp theo lộ trình và chiến lược phát triển của ngân hàng;\n• Tư vấn cho lãnh đạo các giải pháp để khắc phục các vấn đề hoặc tối ưu hoạt động của Khối CNTT theo quy trình cải tiến liên tục;\n• Tổ chức đào tạo, hướng dẫn, trao đổi kiến thức và sinh hoạt chuyên môn.\n• Thực hiện các nhiệm vụ khác được giao.\n\nThực hiện các nhiệm vụ khác theo phân công của lãnh đạo Phòng và lãnh đạo Trung tâm.\n\nYour skills and experience\nBằng cấp: Tốt nghiệp Đại học trở lên các chuyên ngành thuộc lĩnh vực Công nghệ Thông tin, Điện tử viễn thông, Toán tin, Tài chính Ngân hàng;\nKiến thức chuyên môn:\n• Theo yêu cầu về năng lực chuyên môn và năng lực quản lý quy định trong Khung năng lực của Khối CNTT trong từng thời kỳ.\n• Có tối thiểu 04 năm kinh nghiệm làm việc trong lĩnh vực Công nghệ thông tin.\n\nKỹ năng, phẩm chất:\n• Kỹ năng Đọc, hiểu tài liệu và giao tiếp bằng Tiếng Anh;\n• Có khả năng nghiên cứu độc lập.\n• Kỹ năng lập và triển khai kế hoạch;\n• Kỹ năng giải quyết vấn đề và ra quyết định.\n\nWhy you\'ll love working here\n• Được tham gia vào các dự án công nghệ lớn, các sáng kiến trọng điểm mang tính đột phá số hóa của Ngân hàng\n• Trải nghiệm các kiến trúc, công nghệ mới nhất, làm việc trực tiếp với các đối tác hàng đầu thế giới (AWS, IBM, Temenos…)\n• Môi trường năng động và cơ hội thăng tiến, với văn hóa doanh nghiệp mang bản sắc riêng\n• Chế độ lương thưởng hấp dẫn\n• Bảo hiểm sức khỏe cao cấp (bảo hiểm toàn diện)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '22 Ngô Quyền, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(714, 227, 2, 'Software Architect (.Net)', 'Top 3 reasons to join us\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description\nDevelopment & Deployment\n- Develop clean, scalable code using .NET Core in Micro-service Architecture & Cloud-native.\n- Develop backend Data-storage & Data-flows with Postgres, ES, Kafka, and various Cloud data toolsets.\n- Test and deploy system (micro-)services & (micro-)apps on AWS EKS/Kubernetes with Docker toolset.\n\nProject Management:\n- Develop and maintain comprehensive documentation throughout the software development lifecycle (SDLC).\n- Actively participate in defining technical specifications within the Agile/Scrum development process.\n- Support Product Owner in planning and prioritize backend tasks to ensure timely delivery of project milestones and objectives.\n\nSystem Architecture:\n- Lead the design and evolution of backend architecture to support current and future business needs.\n- Evaluate and integrate new technologies, tools, and frameworks to improve system performance and developer efficiency.\n- Participate in reviewing architectures with Team Leads & SAs.\n\nCode Review & Team Coaching\n- Provide technical direction, mentorship, and code reviews for the backend team.\n- Coach team to ensure compliance with best practices and high quality coding standards.\n\nYour skills and experience\nEducational Background:\n- Bachelor’s degree in computer programming, computer science, or a related field\nExperience\n- At least 7+ years of professional development experience.\n- A minimum of 1 year of hands-on experience with Cloud Native Computing using platforms such as AWS, GCP, or Azure.\n- At least 2 years of experience leading a team.\n- Proven track record of working in a product-focused company for at least the last 2 consecutive years.\nTechnical Skills:\n- Expert in C#, .NET, .NET Core, Core, Entity Framework Core, LINQ\n- Expert in Relational database modeling & design with Postgres\n- Deep understanding of computer architectures, data structures and algorithms, SOLID principles\n- Proficient knowledge of Microservices, Clean-code\n- Understanding of Agile/Scrum methodologies\nSoft Skills:\n- Good communication skills.\n- Strong problem-solving skills with a Value-Driven mindset.\nEnglish skill: TOEIC >= 750 or IELTS >= 6.0 (Reading & Writing)\nPreferred (but not required)\n- Document DB modeling & design with Elasticsearch\n- DevOps, SysOps in AWS and Git CI/CD experience\n- Object Storages with AWS S3\n- Message Queues with KAFKA & Message Queue\n- Messaging with Sendgrid, Twilio, AWS SNS,…\n- e-Commerce Experience (Inventory or Warehouse Management)\n\nWhy you\'ll love working here\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\nExceptional Compensation\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total annual compensation over $70,000, reflecting your expertise and contribution.\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi, New setup, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(715, 500, 2, 'Remote Frontend ReactJS ~ 1500$', 'ELotus is a business technology partner, focused on building technological innovations for leading enterprises. We focus on enterprise SaaS products that automate the manual processes and digitise the analogue records and documentation for our clients. We are a tight-knit team of professionals with experience in building products for clients.  The Frontend Developer is responsible for developing and maintaining applications and components relating to those applications within the Digital product suite.\n\nAs a Frontend Engineer, you will: \nWrite reusable, testable code. Unit tests are required for critical code paths. \nMaintain the shared libraries, infrastructure that\'s used in all the products. \nResponsible for live issues, troubleshooting. \nCode review and Mentoring of peer developers.\n\nYour skills and experience\nMinimum qualifications: \nEnglish at basic level, ability to read IT documentation and communicate with team mates. \nMinimum 2-year experience with front-end development frameworks with ReactJS, TypeScript\nExperience in creating custom UI \nUse Unix system and development tools efficiently (You should know more than 15 git sub-commands, and common shortcuts of your daily tools). \nPreferred qualifications: \nExperience with SASS/LESS \nMobile UI/UX experience nice to have \nStrong algorithm and data structure knowledge \nGood knowledge of at least 01 design language such as Bootstrap. \nDeep understanding of common topics: RESTful, HTTP, parallel processing, DOM, browser rendering engines, UI responsive, websocket, caching, … \nReviewing and assisting with Client requirements \nReviewing and assisting with Designs (UI/UX, functional and technical) \nAssisting with Sprint capacity and Issue Management \nAssisting with CI/CD Build Process. \nAssisting Support teams with Queries and Issues that they may raise from Clients\nTechnologies we\'re using for the Frontend: - ReactJS, Typescript, SCSS, Ionic - Single SPA, Webpack - Github CI/CD, Kubernetes\n\nWhy you\'ll love working here\nRemote working with flexible time \nNet salary for Junior from 700$ \nFull salary during probation period. \nMacBook for staff \nOpportunity for onsite at Singapore office', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'G - Office, 19 Cao Thang, Quarter 2, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(716, 353, 2, '[Data engineer] CVCC/TBP Khai thác dữ liệu (SQL,Python)', 'Mô tả công việc:\nBạn sẽ là cầu nối giữa dữ liệu và các bộ phận nghiệp vụ, đóng vai trò quan trọng trong việc xây dựng và vận hành hệ thống báo cáo, phân tích dữ liệu phục vụ cho quá trình ra quyết định của Ngân hàng. Công việc chính bao gồm:\n\n- Thiết kế và phát triển: Thiết kế kiến trúc dữ liệu, xây dựng các data pipeline, data warehouse, data mart, data dictionary.\n- Xử lý dữ liệu: Viết các câu lệnh SQL phức tạp, xây dựng các job ETL để xử lý và biến đổi dữ liệu.\n- Tối ưu hóa: Tối ưu hóa hiệu suất truy vấn, cấu trúc dữ liệu để đảm bảo hệ thống hoạt động ổn định và hiệu quả.\n- Phối hợp: Làm việc chặt chẽ với các bộ phận nghiệp vụ để hiểu rõ yêu cầu, cung cấp các báo cáo phân tích chính xác và kịp thời.\n\nYêu cầu công việc:\n- Kinh nghiệm: \n  - Tối thiểu 3 năm kinh nghiệm trong lĩnh vực phân tích dữ liệu hoặc kỹ thuật.\n  - Có kinh nghiệm làm việc với các hệ cơ sở dữ liệu lớn (PostgreSQL, Oracle, MongoDB) và các công cụ xử lý dữ liệu lớn (Spark, Hadoop).\n  - Hiểu sâu về các quy trình ETL, data warehousing, data modeling.\n\n- Kỹ năng:\n  - Kỹ thuật: Thành thạo SQL, Python, các công cụ ETL (Airflow, Luigi, Flink), cloud services AWS (EC2, S3, EMR, Glue, Athena, Redshift), Big Data (Databricks, Apache Spark).\n  - Mềm: Khả năng giao tiếp tốt, truyền đạt súc tích, làm việc nhóm, giải quyết vấn đề, tư duy logic, chủ động và trách nhiệm cao.\n\n- Kiến thức:\n  - Hiểu biết về domain tài chính, quản lý rủi ro.\n  - Có kinh nghiệm làm việc trên các quy trình dữ liệu Data governance.\n  - Có kinh nghiệm làm việc với các công cụ quản lý dự án (Confluence, Jira).\n\n- Khác:\n  - Đã từng tham gia các dự án lớn liên quan đến khai thác dữ liệu với vai trò là techlead.\n  - Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh.\n  - Đảm bảo tính bảo mật và tuân thủ quy định của Ngân hàng.\n\nYêu cầu tài liệu hóa:\n- Thành thạo việc xây dựng các tài liệu kỹ thuật (ERD, Database schema).\n- Có khả năng trình bày rõ ràng các giải pháp kỹ thuật.\n\nTop 3 reasons to join us:\n- Môi trường làm việc thân thiện, chuyên nghiệp\n- Lương thưởng tương xứng năng lực làm việc\n- Có cơ hội phát triển bản thân\n\nWhy you\'ll love working here:\n- Đánh giá và xét thưởng tương xứng với năng lực.\n- Được quy hoạch, huấn luyện và đào tạo bài bản, tiếp cận với những công nghệ mới nhất và hiện đại nhất trong lĩnh vực tài chính.\n- Được hỗ trợ phát triển bản thân tối đa.\n- Du lịch, teambuilding hằng năm.\n- Lương tháng 13, lễ, Tết.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(717, 409, 2, 'Middle Backend Developer (NodeJS, NestJS, TypeScript)', 'Top 3 reasons to join us\n1. Yearly SAAS allowance of up to $600\n2. Premium Healthcare Insurance\n3. On-Chain Data at Scale\n\nJob description\nAbout Us\nDecentralab is a high-quality Web3 Studio based in Da Nang, Vietnam, that specializes in developing decentralized applications (dApps) and contributing to the blockchain ecosystem. Our mission is to drive innovation by providing the tools and expertise necessary to build and deploy decentralized applications that can transform traditional industries and create new business models.\n\nJob Description\nWe are looking for a Backend Developer to join our team and be responsible for the development and maintenance of server-side applications, particularly those related to blockchain and the EVM ecosystem. You will be instrumental in building robust server logic and ensuring high performance and responsiveness to requests from the front-end.\n\nResponsibilities\n- Integration of user-facing elements developed by a front-end developer with server-side logic.\n- Write reusable, testable, and efficient code.\n- Build business logic for blockchain application layers.\n- Take full ownership of your code and deliver efficient solutions.\n- Integration of data storage solutions and data processing pipelines.\n- Take responsibility for the outcomes related to your work.\n- Implement security and data protection measures.\n- Optimize applications for performance and scalability.\n- Support and collaborate with other team members to ensure high-quality outcomes.\n\nYour skills and experience\nRequirements\n- Minimum 2 years of experience with Node.js and Nest.js\n- Strong proficiency in TypeScript\n- Experience with MongoDB and Mongoose\n- Understanding and experience with Redis and Kafka\n- Experience working with Docker and Kubernetes\n- Integrated Elasticsearch in applications\n- Basic knowledge of Linux and ability to work in a Linux environment\n- Familiarity with EVM ecosystem (Ethereum, Arbitrum, Optimism) and smart contracts\n- Logical and system thinking with strong optimization skills\n\nNice to Have\n- Experience in blockchain or decentralized application projects\n- Experience in financial domains (crypto, forex)\n- Deep knowledge of microservices deployment\n- Ability to work independently and collaboratively in a cross-functional team\n\nWhy you\'ll love working here\n- NET salary up to 30M VND/month (increased based on ability)\n- Comprehensive training about perpetual trading market and blockchain data structures\n- Exposure to real enriched blockchain trading data\n- Collaborative working environment with strong trading knowledge\n- 13th-month salary bonus based on business performance\n- Premium healthcare insurance\n- Daily lunch support\n- Company trips and weekly happy hours\n- Annual health check-ups\n- Ergonomic office furniture\n- In-house entertainment zone: drum, billiards, ping pong, foosball, VR games, board games, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '70 Phan Thanh, Thạc Gián, Thanh Khe, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(718, 432, 2, 'Lead Software Engineer (ReactJS/ SIGN-ON BONUS)', 'Top 3 reasons to join us\n- Sign-on bonus 40M & a rewarded Danang trip!\n- Attractive Package & Dedication Bonus\n- Hybrid and flexible working environment\n\nJob description\nTechnical Hands-on (80%)\n- Develop secure, scalable, and maintainable cloud services across our tech stack: Javascript, TypeScript, React, Cloudfare, and Terraform.\n- Design, develop, review, implement, and manage continuous integration, build management and deployment scripts, systems, and any code as required\n- Create new customer value in small increments, delivered continuously to production.\n- Collaborate across teams and functions to help define our architecture and technical roadmap.\n- Provide robust coding practices, solid unit/component test coverage, and debugging code.\n\nLeadership (20%)\n- Manage and mentor a small group of other engineers, and create a safe and inclusive environment for the team\n- Work closely with product managers and designers to solve open-ended customer problems.\n- Make pragmatic decisions and sensible tradeoffs informed by high-level business objectives.\n- Mentor and support other engineers while creating a safe and inclusive environment for our diverse team.\n\nYour skills and experience\n- At least 8+ years of experience designing, developing, and operating cloud software at scale, with strong hands-on technical and give solutions for the clients.\n- Solid experience in JavaScript ES6/ Typescript working with ReactJS, and Tailwind CSS.\n- Experience in designing & developing RESTful APIs (GraphQL desirable) and microservices based system; troubleshooting and debugging in microservice\n- Experience in Cloud computing, especially Amazon Web Services (AWS)\n- Experience with unit testing and integration testing\n- Good English & Vietnamese communication skills, both verbal and written.\n- Experience with technical leadership and people management, including the ability to mentor and support other engineers and align engineering work with high-level organisational goals.\n- Ability to manage risk, ambiguity, dependencies and cross-functional stakeholders\n- Experience working with distributed teams in global engineering organisations\n- Well-versed in writing structured, well-documented, maintainable, and clean code.\n- Good problem-solving and analytical skills.\n\nWhy you\'ll love working here\nCompensation & rewards\n- Attractive and competitive performance-based compensation package (40M VND sign-on bonus + Trip to Danang)\n- Generous year-end 13th-month bonus\n- Loyalty and annual dedication rewards\n\nTime off & flexibility\n- 12 annual leave days, 11 public holidays, 1 Christmas day off and 5 sick leave days\n- Flexible check-in time, 1-day remote work per week, and the freedom to work from any of our offices in Da Nang, Hue, or Ha Noi\n\nHealth & well-being\n- Comprehensive healthcare package with premium insurance and annual health check-ups\n\nTeam engagement\n- Team-building allowance and annual company trips for a fun and connected workplace\n- Sports & hobby clubs with football, badminton, biking, running, chess, or music band groups\n\nPersonal development\n- Continuous learning & development with exclusive technical & soft skills training, English classes, and technical clubs\n- Annual budget for the professional development plan, with a focus on the budget allocated for learning and certification exams.\n\nLife event support\n- Financial aid for marriage, newborns, and bereavement to support you through every stage of life', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(719, 450, 2, 'Engineering Manager', 'About the role:\nWe\'re searching for a senior engineering leader with a keen understanding of product development to lead an outstanding team of engineers as we scale for future expansion. You\'ll create a team vision and an engineering roadmap to help the team deliver on several products and engineering projects. You will demonstrate ShopBack leadership ideals, contribute to our wonderful culture, and build strong relationships at all levels of the company.\n\nResponsibilities:\nBe a role model of the ShopBack culture.\nBalance multiple businesses and product priorities to deliver maximal impact.\nDevelop an engineering strategy that places our systems in a position to scale and innovate in the future.\nBuild a team of top engineering talent that is high-performing, inclusive, and diverse.\nForm strong, trusted relationships with Product Managers, Engineering Leadership, and Business Stakeholders.\nHelp your team grasp priorities and provide context to help them make better decisions by assisting them in understanding priorities and providing context.\nDrive success in a flat company with few processes and a strong focus on individual accountability.\nUnderstand the business and develop domain expertise in relevant functions.\n\nYour skills and experience\nRequirements:\n5+ years of professional software development experience.\n2+ years of experience leading an engineering team.\nA proven track record of developing high-performing teams capable of solving complex problems and delivering elegant, scalable solutions.\nExperience leading engineering teams and delving into technical details to assist the team in making decisions that result in efficient, flexible, scalable systems.\nCapability to attract, develop, and retain top engineering talent.\nInteractions with senior leadership require executive presence.\nYou are an excellent communicator with exceptional listening skills and the ability to see the big picture and effectively communicate it at all levels.\nYou successfully influence product direction as a thought partner to your business stakeholders. Product Managers actively seek out your ideas (PMs). You can take a conceptual idea and turn it into a test that is both feasible and meets business requirements.\n\nWhy you\'ll love working here\nHave these benefits and a lot more at ShopBack VN:\nAttractive Stock Options for all employees\nUp to 4-month salary of Performance Bonus\n13-month Salary\n15 days of annual leave + 3 days of Medical leave + 1 day of birthday leave \n5 days of Additional Time Off (after annual leave entitlement is fully utilized)\nIDP Budget\nPVI Healthcare Insurance\nOther benefits: Fun monthly and quarterly activities; Fully stocked pantry of fun and healthy food/snacks; Ping-Pong table, PS4 in the office!  \nWhich of these core values connects with you the most?\nOur Mission: To make shopping rewarding, delightful, and accessible.\nOur #SHOPBACK Values\nOur Values are not “Sound/Feel Good” values that are for show. We understand how our values build our culture and believe these aligned values will help us work better together to achieve our mission. We will hire, part ways, recognize or reward ShopBackers based on our values. Upholding these values is as important as our performance at work.\nHere are our 8 Values #SHOPBACK:\nSucceed as One\nHonour Our Customers\nOwn the Problem \nPave New Roads \nBe Better Every Day \nAlways Be Curious \nCan’t is Not an Option\nKeep It Real', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Complex Tower, 285 Cach Mang Thang Tam Street, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(720, 302, 2, 'Project Manager', 'Top 3 reasons to join us\n- Flexible working hour\n- Private health care insurance \n- Premium annual health care check\n\nJob description\n- Manage the international product development teams (including dev, tester, product managers) to ensure that assigned duties meet the business requirements and the company\'s objectives.\n- Build and manage the project plans to ensure works are identified, assigned and completed on time with good quality.\n- Organize and run meetings to ensure the transparency of information between management and development.\n- Manage changes to different aspects of the projects (scope, schedule, quality indexes, ...).\n- Create and maintain comprehensive project documentation throughout the entire process.\n- Identify, track, manage, prevent and resolve any project issues that may occur.\n- Measure and report project performance using appropriate tools and techniques.\n- Perform risk management to minimize project risks.\n\nYour skills and experience\n- 3+ years of project management experience in the IT/Software industry\n- Experience in traditional SDLC, Agile methodologies (SCRUM, Kanban, ...) and have acceptable knowledge with the others.\n- Have experience with people management and resource management for a medium-sized organization.\n- Proven experience in scope definition, project estimation, quality management, resource management and/or risk management\n- Strong familiarity with project management software tools, methodologies, and best practices.\n- Ability to effectively present and report project status to high-level management.\n- Ability to work with cross-functional and globally distributed development teams.\n- Ability to react to project adjustments and alterations promptly and efficiently.\n- Advanced English (fluent preferable).\n- Excellent analytical, verbal, and written communication skills\n\nDesired Qualifications:\n- Bachelor’s degree in Computer Science or related field, advanced degree preferred, or equivalent.\n- TOEIC 800+ or equivalent\n- Highly responsible, well-organized, communicative, proactive, dare-to-lead and dare-to-do attitude\n- Technical stacks: Java, HTML, CSS, C/C++, VMware, Hyper-V, AWS EC2, Odoo...\n- Experience with Jira, Confluence, SVN, TeamCity.\n\nGiven the high volume of CVs applied, we can only manage to respond to candidates whose profiles aligns with the position within 5 working days. We appreciate your understanding and enthusiastic towards our company.\n\nWhy you\'ll love working here\nThe Nakivo team in Vietnam has been changing very fast in the recent years, we have grown from a group of 6 engineers to the current team size of 70 and we are expecting to grow even more in the next following years.\nWe welcome and embrace people, regardless of their background, religion, nationality or gender, but focus on diversity, contribution, determination and work ethic. At Nakivo, we are trying to improve everyday, to become a competitive choice for talented people, by offering\n- Flexible working hours: Office opens from 6.00 AM to 10.00 PM\n- 13-month bonus & performance bonus\n- 100% salary on probationary period\n- Private health care package\n- Premium health care check\n- Gift (cash/voucher) for every special occasion: New Year\'s Eve, Tet holidays, International Women\'s Day, International Children\'s Day, Mid-Autumn Festival and Birthday\n- 15-18 annual leaves/year, 5 sick leaves and additional leaves (up to 3 days)\n- Team building\n- Free and un-limited snack, tea, coffee and by-choice request.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '16 Le Quy Don, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(721, 427, 2, 'Unity Developer (C#, Games, English)', 'Job description\n- Xây dựng và phát triển các dự án Game mobile trên nền tảng Unity cho Android và iOS\n- Sửa lỗi và cải thiện tính năng, hiệu suất trò chơi\n- Xây dựng và triển khai kiến trúc hệ thống game (game architecture design)\n- Phối hợp với các thành viên trong team để vận hành và tối ưu hoá sản phẩm\n- Cùng team lên ý tưởng và giải pháp cho các tính năng mới của game\n- Tham gia quá trình xây dựng team dev; chia sẻ và phát triển chuyên môn dev của công ty\n\nYour skills and experience\n- Yêu thích làm game\n- Thành thạo C# & Unity\n- Có kinh nghiệm 1 năm trở lên ở vị trí tương tự, hiểu biết về Design Pattern, Unity Engine\n- Khả năng tư duy, sáng tạo tốt\n- Có nền tảng tư duy thuật toán, cấu trúc giải thuật, tư duy logic tốt.\n- Có trách nhiệm cao trong công việc, thái độ cầu tiến và ham học hỏi công nghệ mới\n- Có khả năng đọc hiểu tài liệu bằng Tiếng Anh là một lợi thế\n\nWhy you\'ll love working here\n- CƠ HỘI THĂNG TIẾN HOẶC ĐỀ XUẤT LÊN LÀM PM, TECHLEAD,... TRONG THỜI GIAN NGẮN NẾU ĐÃ CÓ KINH NGHIỆM\n- Mức lương upto $1500, thử việc hưởng full lương\n- Lương net, không phải đóng bảo hiểm hay bất kỳ chi phí nào\n- Thưởng LINH HOẠT & HẤP DẪN: Thưởng nóng, thưởng quý, thưởng tết... (thu nhập mỗi năm tối thiểu 15 tháng lương)\n- Review lương 6 tháng/lần\n- Du lịch, team building ít nhất 2 lần/năm, hoa quả quà chiều, được thoải mái chơi các trò chơi tại công ty: bi-a, PS, board game,...\n- BHXH, khám sức khỏe định kỳ,12 ngày nghỉ phép/năm và ngày lễ\n- Cơ hội được tham gia và xây dựng các dự án game chất lượng,được làm việc với những đồng nghiệp có kinh nghiệm hàng đầu trong ngành game mobile, cơ hội phát triển và thăng tiến rộng mở\n- Được làm việc với nhiều khách hàng quốc tế và nhiều đối tác lớn như Google, Facebook, Unity....\n- Cơ hội được học hỏi, được thử sai, được rèn luyện bản thân và trau dồi kinh nghiệm thực chiến với việc hỗ trợ 30-100% chi phí các khóa học nhiều kỹ năng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, Toà Sun Square, Số 21 Lê Đức Thọ, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(722, 501, 2, 'Lead Back-End Engineer', 'Top 3 reasons to join us\n- Top 10 global leaders in the social gaming sector\n- Global talented members and a thriving workplace\n- Desirable benefit package for you and your family\n\nJob description\n- Provide technical leadership, guidance, and direction to the backend team for project execution.\n- Ensure backend stability and quality, owning the backend technical architecture.\n- Collaborate and communicate with the stakeholders on backend project planning and execution.\n- Collaborate with stakeholders to analyze business requirements, ensuring technical feasibility and alignment with detailed product specifications.\n- Review and approve backend technical documentation and code.\n- Provide mentorship, training, and oversee the career development of backend engineers.\n- Other tasks as assigned.\n\nYour skills and experience\n- 10+ years of backend software development experience, with 3+ years in a leadership role.\n- Bachelor’s or Master’s degree in Computer Science, Engineering, or a related field.\n- Good command of English – both written and spoken.\n\nTechnical proficiency\n- Expert-level implementation skills with C#, ASP.NET and .NET Core.\n- Strong understanding and proficiency in design patterns, data structures, and development best practices.\n- Extensive experience and understanding of microservices architecture, RESTful APIs.\n- Hands-on experience with Azure services or any other equivalent cloud platforms.\n- Advanced understanding of both relational and NoSQL databases.\n- Familiarity with CI/CD pipelines and DevOps practices.\n\nLeadership & collaboration\n- Proven ability to lead and mentor Engineering teams, fostering a culture of continuous learning and improvement.\n- Excellent communication skills to effectively collaborate with cross-functional teams, including product managers and frontend developers.\n\nPreferred qualifications\n- Experience in the gaming industry\n- Experience working and collaborating with global teams across multiple time zones\n- Experience working with Unity\n\nAdditional note: You may be expected to complete a test as part of the interviewing procedure.\n\nWhy you\'ll love working here\n- Work directly with a global team of young and talented playMAKERS regardless of gender, age or experience.\n- Unlimited growth opportunities and continuous improvement with English classes, workshops and other technical training courses by highly-skilled members from all over the world.\n- Bao Viet Premium healthcare coverage is 1.2 billion VND/person/year (including you and ALL your dependents).\n- A company of fulfillment: 100% salary on probation, 100% covered Social insurance, Health insurance and Unemployment insurance since probation. Moreover, Compulsory insurance for employees is also filled by the company. You only need to bear PIT.\n- 13 months salary/year.\n- Discretionary bonus.\n- Employee referral bonus program (Very attractive bonus range: from 300USD to 1000USD).\n- Flexible working time: 5 working days/ week - from Monday to Friday (Time won\'t be your fear, because productivity is what we care about).\n- Annual leave: 15 days in 1st year, 17 days in 2nd year, and 20 days each year thereafter.\n- Sick leave: 5 days/year.\n- Delicious, fresh and free meals are served daily!\n- High-end workstation laptop and screens.\n- Equipment Allowance: 4,500,000 VND to pick your keyboard/ mouse/ headphone... in your own style.\n- Team building activities, staff trips, and company events across the year.\n- Other benefits: Sickness, funeral: support up to 2,000,000 VND/person; marriage, childbirth, and public holidays: up to 500,000 VND/person.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UDIC Building, Hoang Dao Thuy Street, Trung Hoa Ward, Cau Giay District, Hanoi City, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(723, 272, 2, 'Senior Process Quality Assurance (PQA, QA QC)', 'Top 3 reasons to join us\n1. Môi trường năng động và sáng tạo\n2. Cơ hội phát triển sự nghiệp\n3. Chế độ đãi ngộ canh tranh\n\nJob description\n1. Thiết kế & Quản trị khung kiểm soát dự án\n- Xây dựng, vận hành và tối ưu hệ thống quản lý quy trình SDLC.\n- Phối hợp Bộ phận Quản trị Hệ thống (Jira Admin) cấu hình workflow, trường tùy chỉnh, báo cáo.\n\n2. Giám sát & Đánh giá tuân thủ\n- Giám sát hoạt động dự án để phát hiện sớm các vấn đề.\n- Thực hiện audit định kỳ/đột xuất; lập khuyến nghị và theo dõi kế hoạch khắc phục.\n\n3. Quản lý rủi ro dự án\n- Phối hợp Quản lý dự án xác định rủi ro, đề xuất và giám sát biện pháp phòng ngừa/khắc phục.\n- Đảm bảo quy trình đáp ứng ISO 9001, ISO 27001, CMMI, ITIL và quy định pháp luật.\n\n4. Báo cáo & Cải tiến liên tục\n- Tổng hợp báo cáo chất lượng dự án tuần/tháng cho Ban Lãnh đạo.\n- Phân tích nguyên nhân gốc rễ, đề xuất giải pháp Kaizen/PDCA và tự động hóa quy trình khi khả thi.\n\n5. Hỗ trợ & Đào tạo đội ngũ\n- Đào tạo thành viên dự án về quy trình, công cụ và kiểm soát chất lượng.\n- Xây dựng và cập nhật định kỳ tài liệu e-learning.\n\nYour skills and experience\n- Tốt nghiệp đại học trở lên.\n- Tối thiểu 3 năm kinh nghiệm tại vị trí tương đương.\n- Có kinh nghiệm triển khai và giám sát quy trình trong tổ chức.\n- Có khả năng hướng dẫn, đào tạo và hỗ trợ đơn vị thực hiện quy trình.\n- Kinh nghiệm xây dựng công cụ giám sát, đánh giá hiệu quả vận hành.\n- Khả năng phân tích dữ liệu để đo lường và cải tiến quy trình.\n- Sử dụng thành thạo công cụ báo cáo (Excel nâng cao, Power BI, Tableau, SQL).\n- Kỹ năng sử dụng công cụ quản lý và giám sát quy trình.\n- Thành thạo các công cụ BPM (Bizagi, Camunda, Visio) để thiết kế và theo dõi quy trình.\n- Sử dụng thành thạo các nền tảng quản lý công việc (Jira, Confluence, ServiceNow).\n- Am hiểu về các hệ thống giám sát hiệu suất (KPI, OKR).\n- Ưu tiên có các chứng chỉ chất lượng: ISO 9001, ISO 27001, CSQA, Lean Six Sigma,...\n- Có tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty.\n\nWhy you\'ll love working here\n1. Cộng đồng những người làm nghề chính trực và dấn thân phụng sự\n- Môi trường làm nghề tài chính chuyên nghiệp.\n- Làm việc với tinh thần làm chủ, sáng tạo và thách thức.\n\n2. Tổng thu nhập theo năng lực\n- Thu nhập xứng đáng theo năng lực và giá trị đóng góp.\n- Xem xét thay đổi thu nhập hàng năm.\n\n3. Chế độ đãi ngộ\n- Tham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động.\n- Được tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24.\n\n4. Tổ chức học tập và văn hóa sôi nổi\n- Không gian làm việc mở với trang thiết bị hiện đại.\n- Các hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '43 Lê Văn Lương, Nhân Chính, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(724, 357, 2, 'Middle/Senior Fullstack Developer (.NET)', 'Top 3 reasons to join us\n- Start up company\n- Hybrid working\n- Work-Life Balance\n\nJob description\n- Design, build and maintain a high-scale, multiplayer game platform.\n- Develop and maintain microservices to ensure a modular and scalable architecture.\n- Collaborate with international teams to ensure successful project delivery.\n- Ensure consistent code quality, performance, and reliability.\n- Train and support other team members.\n\nYour skills and experience\n- 4+ years of continuous software development experience.\n- Strong expertise in designing and building microservice architectures.\n- Deep knowledge of .NET Core framework.\n- Experience with Apache Kafka, Redis, and MongoDB.\n- Has background in real-time systems and working with Socket.IO.\n- Familiarity with container orchestration using Kubernetes.\n- Proficient in frontend development with React and TypeScript.\n\nWhy you\'ll love working here\n- Competitive salary\n- Hybrid work style with 6 - 8 remote days per month—balance work and life your way.\n- 12 paid leave days per year, plus national holidays.\n- Flexible hours, Monday to Friday—your weekends are all yours.\n- Work with a young, passionate, and supportive team that loves what they do.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Co-working, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(725, 502, 2, 'Senior Software Engineer (Node.JS, Python & AWS cloud)', 'YOUR BRILLIANT FUTURE IN TECH IS NOW\nWelcome to the world of Zoi. We are those who build the digital evolution of our enterprise customers, closing the gap between enterprise IT and new technologies. Zoi strives to bring the cloud to the Retail and Manufacturing industries with innovative solutions that deliver real value.\nWe are expanding our European teams in Stuttgart, Berlin, Cologne, Lisbon, Barcelona, Figueres, Sevilla and Las Palmas. We are also looking for support at our international locations in Mexico City, and Ho Chi Minh City.. Just choose your favorite Zoi city! Travel between our locations is possible.\nWHAT YOU DO:\nAs an active part of the development team you will work on software solutions on your own responsibility.\nYou know technical Best Practices such as Serverless, CQRS, Microservices and Micro Frontends like the back of your hand and use them to convert agile requirement descriptions from user stories and use cases into suitable software components\nYour tasks extend over the entire stack of an application.\nTo automate the delivery of software artefacts, you convert test cases into test code to ensure that the application\'s results are secured for the team.\nYour project topics range from enterprise web portals with connection to ERP systems and payment providers to complex IoT product development with app, platform, and communication development.\nWHO YOU ARE:\nAt least 3–5 years of experience in a similar position.\nA candidate has at least experienced 2 languages (JavaScript, ES6/7, Node.js, Python, C#/.NET) and one of them is Nodejs/.NET/Python, and has cloud experiences in AWS or Azure.\nYour wealth of experience with one of the popular front-end frameworks such as React, Vue.js, or Angular 2 puts you ahead of the pack.\nCSS2 + 3, LESS, SASS, and CSS design patterns are part of your knowledge as well.\nYour interface protocol know-how includes experience with the web services REST and maybe also SOAP.\nWhen it comes to application deployments, you are familiar with Continuous Integration and Development (CI/CD) pipeline experiences.\nYou have already gained experience in the Internet of Things environment - or you are interested at least.\nAs a team player, you take a responsible and solutions-oriented approach to problems.\nA strong analytical mind, as well as dedication and initiative, characterize you in project teams, you quickly find your footing because you are well organized and appreciate interdisciplinary work.\nFluent communication skills in English\nWhy you\'ll love working here\nDo you like to be surrounded by brilliant minds? Awesome. At Zoi, you become part of our community of tech enthusiasts and develop your full potential. Create fresh ideas and shape the digital transformation of our enterprise customers sustainably.\nGOOD WORK SHOULD BE REWARDED - which is why we offer various bonus models at our company\nTIME IS WISDOM - 20 % of your working time is available for experimenting and education\nSKILL YOURSELF UP - Zoi can only be as good as you are. That’s why we value constant training and development\nBE FREE - thanks to our absolutely flexible working hours and work remotely from any of our locations\nDEVELOP YOURSELF - with our individual certification and training plan\nFAMILY COMES FIRST - rely on our financial support for childcare\nREFUEL - at our regular free Friday lunch\nZoi is an equal opportunity employer, we\'re committed to helping you do your best work. Our promise is to champion diversity, build an inclusive culture and do our part to create a more equitable professional landscape.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '49 Dien Bien Phu, Da Kao Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(726, 238, 2, 'Chuyên viên Quản lý máy chủ - Server Administrator', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Thực hiện cài đặt hệ thống hạ tầng phần cứng máy chủ bao gồm: Máy chủ vật lý (Blade server, Rackmount server) hoặc trên môi trường ảo hóa (VMware)\n- Phối hợp với các đơn vị thực hiện việc cấu hình các thông số của hệ điều hành (Windows server, Linux …) nhằm tăng cường bảo mật và hiệu suất hoạt động của máy chủ\n- Giám sát liên tục hiệu năng của hệ thống, tối ưu hóa việc sử dụng tài nguyên và xử lý kịp thời các sự cố phát sinh\n- Thực hiện việc nghiên cứu, triển khai các giải pháp tự động hóa trong công tác quản trị và vận hành hệ thống. Nghiên cứu và đề xuất các giải pháp kỹ thuật nhằm cải tiến, nâng cao chất lượng hạ tầng máy chủ và dịch vụ hạ tầng CNTT cho khác hàng nội bộ và bên ngoài của Ngân hàng\n- Phối hợp với các đơn vị liên quan thực hiện công tác cập nhật bản vá (patching) và nâng cấp phiên bản hệ điều hành nhằm đáp ứng các quy định về bảo mật của ngân hàng và các tiêu chuẩn khác như ISO 27001, PCI-DSS…\n- Vận hành hạ tầng sao lưu và phục hồi dữ liệu cho hệ thống máy chủ\n- Xây dựng tài liệu kỹ thuật, tài liệu quản trị, vận hành trong phạm vi công việc được giao theo quy\n\nYour skills and experience\n- Trình độ học vấn: Tốt nghiệp các Trường Đại học trong nước hoặc nước ngoài\n- Chuyên ngành đào tạo: Công nghệ thông tin, Toán tin, Điện tử Viễn thông…\n- Có kiến thức về kiến trúc hạ tầng hệ thống (kiến trúc kết nối, kiến trúc phân chia tải …)\n- Có kinh nghiệm phụ trách trực tiếp quản trị hạ tầng máy chủ với quy mô trên 500 server hoặc tối thiểu 3 năm kinh nghiệm ở tổ chức lớn.\n- Có kinh nghiệm làm việc với các loại hạ tầng máy chủ vật lý blade hoặc rackmount như HP, Cisco UCS, Dell…\n- Có kinh nghiệm làm việc và vận hành hệ thống ảo hóa Vmware hoặc các nền tảng ảo hóa.\n- Có kinh nghiệm làm việc với các hệ thống quản lý và monitor tập chung (Zabbix, Splunk….)\n\nƯu tiên:\n- Ứng viên có kinh nghiệm triển khai các dự án trong lĩnh vực tài chính ngân hàng.\n- Ứng viên có các chứng chỉ MCA (Windows Server Hybrid Administrator), Linux LPI...\n- Có khả năng nghiên cứu tài liệu nước ngoài về các hệ thống mới.\n- Kỹ năng viết tài liệu, thuyết trình, thuyết phục tốt.\n- Tiếng Anh trình độ tương đương 5.5 IELTS, có thể làm việc trực tiếp với các đối tác nước ngoài.\n\nWhy you\'ll love working here\n**Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:** \n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể… \n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương \n\n**Cơ hội nghề nghiệp và phát triển bản thân:** \n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng \n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng \n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh. \n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...) \n\n**Môi trường làm việc lý tưởng với:** \n- Những người cộng sự thân thiện và tài năng \n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(727, 238, 2, 'Chuyên viên Cao cấp Kiểm thử nghiệp vụ Ngân hàng lõi', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Thực hiện tìm hiểu, phân tích và làm rõ yêu cầu. Xây dựng chiến lược kiểm thử cho yêu cầu sản phẩm, dịch vụ Ngân hàng Lõi\n- Xây dựng kế hoạch kiểm thử, thiết kế kịch bản kiểm thử, thực hiện kiểm thử.\n- Xây dựng tài liệu cho các yêu cầu sau khi đã thực hiện\n- Quản lý nhóm kiểm thử, phân tích và theo dõi kết quả kiểm thử; báo cáo kết quả kiểm thử, đảm bảo chất lượng phần mềm trước khi đưa lên Production\n- Phối hợp và hỗ trợ bộ phận nghiệp vụ xây dựng kế hoạch, kịch bản kiểm thử người sử dụng (UAT); hỗ trợ kiểm thử UAT, kiểm thử sau golive;\n- Phân tích /đánh giá nguyên nhân lỗi sau golive.\n- Xây dựng và cải tiến quy trình kiểm thử, quy trình phát triển phần mềm.\n\nYour skills and experience\n- Tốt nghiệp Đại học trở lên các chuyên ngành: Công nghệ thông tin, Toán tin, Điện tử Viễn thông, Kế Toán, Tài chính Ngân hàng....\n- Có trên 4 năm kinh nghiệm trong công tác kiểm thử trong ngân hàng, tổ chức tài chính, công ty công nghệ, trong đó có ít nhất 01 năm làm việc với các dự án liên quan đến hệ thống ngân hàng lõi (ưu tiên T24)\n- Có kinh nghiệm làm việc theo mô hình  Agile/Scrum\n- Ưu tiên:\n  - Có kinh nghiệm kiểm thử tự động\n  - Có kinh nghiệm quản lý nhóm\n  - Có chứng chỉ quốc tế về kiểm thử: ISTQB, CETPA, CSTE, Seed Infotech, Qspiders Software Testing...\n\nWhy you\'ll love working here\n**Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:** \n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể… \n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương \n**Cơ hội nghề nghiệp và phát triển bản thân:** \n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng \n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng \n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh. \n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...) \n**Môi trường làm việc lý tưởng với:** \n- Những người cộng sự thân thiện và tài năng \n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(728, 503, 2, 'Product Engineer – Growth & Automation', 'Now we need someone to make the platform feel intelligent and seamless — across internal tools, user-facing flows, and smart automations.\nWe’re hiring a Product Engineer based in Vietnam to:\n• build the internal dashboards, workflows, and UI glue that keeps the company moving\n• wire together frontend, automation, and backend logic as needed\n• support platform growth by owning specific product slices end-to-end.\n\nYou’ll operate at the intersection of growth, automation, and product — building things that make Tocco faster, smarter, and more scalable.\n\nBuild and connect frontend flows that feel smart\n→ Custom quote builders, form-based editors, onboarding wizards.\n\nOwn internal tools and dashboards\n→ Track supplier activity, map user engagement, manage Unbox logistics.\n\nUse AI to automate tedious work\n→ Auto-tag suppliers with GPT, draft summaries, trigger outreach.\n\nPlug in third-party services and APIs\n→ Clerk, Supabase, Typeform, Notion API, email tools, Zapier.\n\nSupport core platform work when needed\n→ Help build or modify pages using React/Next.js and Prisma.\n→ Review and extend backend APIs, design simple data queries.\n\nMake things happen fast\n→ If something’s blocking the team or user journey — you’ll find a way to fix it.\n\nWe’ll probably love working with you iff…\n• You’ve built and shipped small products or features end-to-end.\n• You’ve used React/TypeScript in real-world settings.\n• You’ve connected APIs, automated workflows, or built custom tooling.\n• You can write basic backend logic (Prisma, Supabase functions).\n• You love finishing things, not just starting them.\n• You’re more interested in impact than perfect code.\n\nWhy you\'ll love working here\n• Real ownership over tools and product flows.\n• You’ll be one of the first 10 people at Tocco.\n→ Your work will directly shape the product and user experience.\n• Mission-led team working on materials, climate, and production systems.\n• Possible IRL team meetups (SEA, Europe, based on what’s possible).\n• Async work, minimal meetings, maximum trust.\n• Salary: location-adjusted + equity (from next round onwards based on performance).\n\nthe ball is in your court now!\nReach out to us at the form below. We’ll get back to you as soon as possible. We move fast.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '., Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(729, 297, 2, 'Security Engineer', 'Top 3 reasons to join us\n• Global product & excellent team\n• Focus on quality & personal growth\n• 3 remote days per week\n\nJob description\nWhat You’ll Be Doing\n• Act as the Security Champion for the organization, promote awareness, alignment, and adoption of secure development practices across engineering teams.\n• Lead security design reviews and advise engineering teams on best practices for building secure, privacy-conscious solutions.\n• Conduct internal security audits, lead awareness initiatives, and deliver training to ensure compliance with company security policies.\n• Manage Mobile Device Management (MDM) and various SaaS platforms to maintain secure and compliant environments.\n• Enforce a Secure Software Development Lifecycle (SSDLC) within development teams.\n• Support ISO 27001 readiness and ongoing compliance efforts by collaborating with leadership and cross-functional teams to implement required controls.\n• Provide ad-hoc security guidance for client projects when needed, focusing on frameworks, reviews, and process alignment rather than daily delivery.\nYour skills and experience\nMust Have\n• Minimum of 3 years of experience in a Security Engineer role.\n• Strong understanding of security and compliance principles across both development and cloud environments.\n• Familiarity with secure development standards and frameworks, including:\n  • OWASP Top 10 and common threat modeling methodologies\n  • ISO 27001:2022 security controls\n  • Secure Software Development Lifecycle (SSDLC) principles\n• Experience in supporting internal compliance efforts, conducting internal audits, and aligning teams with policy requirements.\n• Knowledge of industry standards and regulations such as ISO 27001, SOC 2, GDPR, CSA (Cloud Security Alliance), HIPAA, and PCI-DSS.\n• Excellent written and verbal communication skills in English.\nNice to Have\n• Experience ensuring compliance with data privacy laws such as CCPA, HIPAA, and GDPR.\n• Knowledge of client-facing security requirements and defining security compliance processes per project.\n• Hands-on experience with vulnerability scanning tools (e.g., Nessus, OpenVAS) and strong skills in analyzing scanning reports.\n• Understanding of cloud technologies (AWS, Azure, and GCP)\n• Familiar with working with API designing standards and databases such as: GraphQL, RestAPI, Postgres, MySQL, Kafka,.. \n• Understanding and working knowledge of Cloud-native application security concepts.\nWhy you\'ll love working here\nWho We Are\nCodeLink is an innovative and design-focused development agency. We focus on user-centric design and agile development to bring the product vision of our clients to life. We handle the end-to-end development of products, developing the product vision through product understanding, designing experiences through UX design, refining these flows with modern UI design, and developing products through iterative agile development.\nWe work with both early-stage product teams and teams with existing products from a wide range of countries and industries. We focus on modern technologies and work directly with our clients. We design using design-thinking principles on tools such as Sketch, Figma, Zeplin, and more, and develop products leveraging our tech stack of React, React Native, Rails, Python, and Node.JS.\nOur Core Values\n1. Take full ownership of delivery\n    We take ownership of our client projects and ensure that we deliver what we are in charge of to the best possible outcome.\n2. Deliver our highest level of quality\n    We take pride in the high quality that we deliver and work at a sustainable pace to ensure we can always deliver on that quality.\n3. Stay consistent in plans and processes\n    We keep open and transparent communication with our teammates and our client whilst following agile development practices.\n4. Have empathy for all those we work with\n    We show empathy and respect to all those we work with to gain a deeper understanding without any judgment or assumption.\n5. Continuously improve and grow\n    We aim high with a growth mindset and see every day as an opportunity to develop ourselves, our processes, and our products.\nTop 3 Reasons To Join Us\n• Use cutting-edge & proven technologies\n• Work directly with international clients\n• Open environment with a focus on learning\nWhy You’ll Love Working With Us\nWe work hand-in-hand with our clients to fully invest in their product development and build solutions together for their target market.\n• We fully invest in our team, we will help you build yourself up in any area you feel you need development, be it in English, learning a new design tool, developing your design thinking, and more. We want to make sure that you’re always learning and developing yourself whilst a part of our team.\n• We respect both Product and Technology equally, ensuring all of the Products we work on have features with true market potential and ensuring all of the team contribute to, understand, and believe in what they are developing.\n• We are very selective with our clients, we only work on awesome products we believe in and that show strong market potential.\n• We respect you and your personal hours, we keep a sustainable pace by working standard 8 hour days from Monday to Friday, ensuring we only plan for what we can achieve.\n• We are fully agile and only work with Clients who work the same, working with set sprint goals and working at our rate of velocity.\n• You will have ownership over your role, giving you the opportunity to experiment and try new processes to better improve your day-to-day responsibilities. We are always open to improving our processes.\nCompany Benefits\n• An open and dynamic working environment with no dress code and the freedom to be yourself.\n• Modern open-space office with comfortable workspace, a PS4 games room, and chill-out areas.\n• Salary review twice a year with opportunities for promotions and spot awards.\n• Yearly Training Budget up to 5 million VND per staff.\n• Culture of recognition with monthly rewards for those with the most kudos.\n• All office benefits and full salary during probation.\n• Flexible starting time up to 10 AM working Monday - Friday with no overtime and a long lunch break.\n• Two days remote every week taken on any days you choose so you can work from wherever you like.\n• Full Vietnamese holidays off with 12 annual leave days per year with all days not taken paid out in cash.\n• Yearly company trip, monthly team all-hands activities, welcome lunches for new members, the monthly budget for team celebrations.\n• Celebrations for special days in the year, such as Women’s Day, YEP, Christmas.\n• Gold level Health Insurance coverage from Bao Viet Insurance and a yearly complete Health Check.\n• Employee-led clubs within the company; games teams, sports teams, etc.\n• Buddy system, tech, and product talks, mentoring, and paid-for training for any skills you’d like to develop.\n• Weekly agile sessions and professional coaching.\n• Meal allowance, parking allowance, petrol allowance, and unlimited snacks and coffee every day.\n• Options for a full MAC or PC set-up are completely provided.\nWhere We Work\nHCMC Head Office: Level 8, Vina Building, 131 Xo Viet Nghe Tinh, Ward 17, Binh Thanh District, HCMC\nHanoi Office: Ba Dinh District, Ha Noi City\nDa Nang Office: Hai Chau District, Da Nang City.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '131 Xo Viet Nghe Tinh 17 Ward, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(730, 504, 2, '[HN/ HCM] Business Analyst (Scrum/ Agile)', 'Top 3 reasons to join us\n- Salary starting at $1500 Net or higher\n- Bonuses for holidays and Lunar New Year\'s Eve\n- Bonuses based on business results\n\nJob description\n- Collect and analyze requirements from relevant departments, identify opportunities to improve software systems to meet long-term business strategies and corporate goals\n- Write detailed, clear and accurate SRS (System Requirement Specification) documents, ensuring all system requirements are well understood and meet customer expectations.\n- Responsible for designing and drawing business process diagrams (BPMN) and other diagrams such as Use Case, Activity Diagram, to describe requirements and workflow, ensuring transparency and understanding for stakeholders.\n- Lead and participate in project development process according to Scrum Agile model, closely coordinate with development team (DEV), ensure that features and products fully meet business requirements.\n- Responsible for monitoring and improving software testing processes, writing and reviewing complex test cases, ensuring software quality and usability of the final product.\n- Provide requirements analysis strategy, plan and coordinate project activities, ensuring progress, quality and budget compliance.\n- Proactively lead UI/UX initiatives, working with design teams to ensure intuitive, easy-to-use user interfaces and optimized user experiences.\n- Ensure the continuity and sustainable development of the system, make recommendations for improvement, help the system develop and adapt to the changing needs of the business.\n\nCandidates in Hanoi will work at the office - candidates in HCM will work remotely until the office setup is complete.\n\nYour skills and experience\n- At least 3-5 years of experience as a Business Analyst, with in-depth understanding of software development process and project management.\n- Solid knowledge of software development (DEV), able to communicate, negotiate and work effectively with programmers to clarify technical requirements and find suitable solutions.\n- Deep experience in writing SRS documents, ensuring accuracy and understanding for relevant departments\n- Skill in designing and drawing BPMN process diagrams, Use Case, Activity Diagram and other diagrams, able to communicate complex processes in an easy to understand manner.\n- Extensive knowledge of Scrum Agile model, experienced working in Agile projects as BA.\n- Excellent software testing skills, able to write, review test cases and ensure the product is of the highest quality.\n- Ability to lead and manage projects, ability to coordinate and motivate working groups to achieve common goals.\n- Strong logical and analytical thinking, able to identify and solve complex problems.\n- Deep understanding of UI/UX, ability to make improvement suggestions to enhance user experience.\n\nPriority:\n- Experience working with project management tools (JIRA, Confluence, Lark, etc.) and design tools such as Visio, Lucidchart.\n- Experience working with large and complex systems, understanding of software architecture and complex data management systems.\n\nWhy you\'ll love working here\n- Salary starting at $1500 Net or higher, depending on the candidate\'s performance assessment.\n- Bonuses for holidays and Lunar New Year\'s Eve\n- Bonuses based on monthly/quarterly/yearly business results.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '18 Lại Đà, Xã Đông Hội, Dong Anh, Ha Noi / Online, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(731, 505, 2, 'Python Backend Developer (Django, FastAPI, MongoDB)', 'Top 3 reasons to join us\n- Work with Cisco, Avaya, Microsoft\n- Promote \n- Dynamic Environment \n\nJob description\n- Thiết kế, phát triển các tính năng mới cho hệ thống Unify CRM.\n- Tham gia triển khai các RESTful API cung cấp cho FE và Mobile tích hợp.\n- Bảo trì, tối ưu hóa hiệu suất của hệ thống để đảm bảo khả năng xử lý dữ liệu nhanh chóng và đáp ứng được khối lượng truy cập lớn.\n- Xử lý các vấn đề phát sinh trong quá trình sử dụng của khách hàng.\n- Thực hiện các công việc khác liên quan đến công việc do TBP yêu cầu.\n\nYour skills and experience\n- Trên 2 năm kinh nghiệm ở vị trí backend với ngôn ngữ Python sử dụng thành thạo framework Django (biết sử dụng framework FastAPI là một lợi thế).\n- Hiểu biết về các hệ thống cơ sở dữ liệu NoSQL cụ thể là MongoDB (Có kiến thức về Elasticsearch là một lợi thế).\n- Hiểu rõ về các công cụ quản lý source code như Git, SVN.\n- Có kinh nghiệm làm việc với hệ thống CRM là một lợi thế (Salesforce, Vtiger, Odoo..).\n- Có khả năng làm việc độc lập và làm việc nhóm, kỹ năng giao tiếp tốt.\n- Có kỹ năng giải quyết vấn đề và tư duy logic tốt.\n- Có khả năng tổ chức công việc và quản lý thời gian hiệu quả.\n\nWhy you\'ll love working here\n- Mức lương: 13tr – 23tr\n- Thời gian làm việc: 08h00-17h00 (từ thứ 2 - thứ 6) \n- Phúc lợi: chế độ lương hấp dẫn,chế độ phúc lợi khác theo Luật lao động và chính sách của công ty.\n- Được tham gia đầy đủ BHXH theo quy định nhà nước và gói bảo hiểm sức khỏe cho nhân viên.\n- Cấp Laptop làm việc.\n- Du lịch hàng năm, các hoạt động nội bộ mỗi tháng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'P12B4, lầu 12B, Tòa nhà REE Tower, số 09 Đoàn Văn Bơ, phường 13, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(732, 506, 2, 'Business Analyst (UI-UX, Agile)', 'The Company\nReal Estate Doc (REDOC) is a B2B software platform that breaks the norm by converting traditional real estate and banking documentation transactions digital!\nThrough digitalization and data-driven automation, the REDOC software helps to simplify real estate transactions, provides seamless workflow processes and improves sales efficiency in real estate and sales driven organisations.\nWe are looking for young and motivated technically-skilled individuals to join us and be part of the change in digitising the real estate industry!\n\nThe Career Opportunity \nWant to work for a Singapore-based Tech Company? We are looking for skilled Business Analysts to work with us and drive the change in the industry.\nThe Business Analyst (BA) plays a key role in bridging business objectives with technical execution. You will work closely with stakeholders across departments to gather and analyze requirements, design workflows, and support development teams to deliver scalable ERP and SaaS-based web applications. You’ll act as the translator between business needs and engineering realities, with a strong focus on digitization, automation, and user-centric design.\n\nYour responsibilities:\n1. Requirement Management\nElicit and document business and user requirements through interviews, workshops, surveys, and on-site observation.\nDistinguish clearly between business needs, user expectations, and system constraints.\nWrite and maintain BRD, FSD, SRS, user stories, and use cases.\nPrioritize requirements using MoSCoW, Value vs Effort Matrix.\n\n2. Process Modeling & Documentation\nDesign wireframes, user flows, process diagrams, and mockups (via Figma, Lucidchart).\nMaintain requirement traceability in tools like Jira and Confluence.\nClearly log change requests and impact assessments with proper stakeholder sign-off.\n\n3. SDLC Engagement\nSupport all SDLC phases: Discovery, Development, UAT, and Deployment.\nWork within Agile frameworks based on project context.\n\n4. Technical & System Understanding\nUnderstand modern web application architecture, including Frontend, Backend, APIs and databases.\nActively participate in technical discussions with client-side engineers and solution architects to understand implementation feasibility and constraints.\nCollaborate with internal technical teams to translate business requirements into clear data models, and system behavior.\nProvide rough effort estimates and assist in timeline negotiation based on technical complexity, dependencies, and constraints.\nProactively identify and explain potential technical blockers, security concerns, or architectural limitations when clients raise feature requests or change requirements.\nUnderstand and interpret common system error codes or integration failures to guide clients and internal teams toward quick resolution.\n\n5. Stakeholder & Communication Management\nFacilitate alignment between business and tech teams via meetings, reports, and status updates.\nCommunicate findings, issues, and proposals effectively in both verbal and written forms.\nProduce clear documentation: meeting minutes, training guides, user manuals.\n\n6. Product & Project Contribution\nCollaborate with PMs and Product Owners on roadmap planning and prioritization.\nSupport QA team in preparing test scenarios and validating acceptance criteria.\nParticipate in sprint reviews and release planning sessions.\n\nYour skills and experience\nAt least 2 years of experience as a Business Analyst in large scale ERP System and Banking domain\nKnowledge of RESTful APIs, web architecture, databases.\nComfortable working in cloud-hosted environments (Azure preferred).\nStrong Ability to translate business requirements into functional, non-functional, and technical requirements.\nStrong spoken and written English skills.\nUnderstanding of Agile and experience working in Agile driven environments with working knowledge of Agile tools (JIRA/Confluence).\nAbility in using suitable tools for business modeling, drawing business flows/diagrams, wireframing such as Balsamiq, Figma.\nStrong presentation skills; able to translate technical detail into business context.\nExperienced with UI/UX, and with a user centric mindset or understanding.\nExperience with financial and document management technology is a plus.\n\nWhy you\'ll love working here\nCompetitive salary package\nFull salary for probation\n13th-month salary\nMentoring and coaching from Seniors in the Organisation\nCareer path to becoming a Leader or Specialist along with a fast-growing startup\nOverseas work opportunities in Singapore and the S.E. Asia region\nBe part of a young, dynamic team, which are pushing the applications of technology to change the real estate industry\n14 day Annual leave + Sick leaves + Vietnamese holidays\nComfortable work environment, no dress code.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '5A Tran Phu, District 5, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(733, 507, 2, 'Lead Software Engineer, Backend', 'About Grab and Our Workplace\nGrab is Southeast Asia\'s leading superapp. From getting your favourite meals delivered to helping you manage your finances and getting around town hassle-free, we\'ve got your back with everything. In Grab, purpose gives us joy and habits build excellence, while harnessing the power of Technology and AI to deliver the mission of driving Southeast Asia forward by economically empowering everyone, with heart, hunger, honour, and humility.\n\nGet to Know the Team\nThe Financial Engineering team builds safe, secure and high throughput payments primitives. We oversee a range of platform primitive components such as Wallet, Reconciliation Engine and API Gateway. We take pride in building distributed systems that have a impact on the lives of millions of users in our endeavour to out-serve the underserved population.\n\nGet to Know the Role \nYou will have opportunities to design backend services. Not only will you get to collaborate with the product, business, and program management teams to be on top of your deliverables, you will also serve as a mentor to your teammates to help meet the teams\' deliverables and goals. This role is based in Vietnam and onsite. You will report directly to the Vietnamese Engineering Manager.\n\nThe Critical Tasks You Will Perform\n- Design and develop robust, scalable, and high-performance software applications using GoLang.\n- Identify, prioritize, and execute tasks in the software development life cycle. Automate tasks through appropriate tools and scripting.\n- Collaborate with a cross-functional team to define, design, and ship new features and functionalities.\n- Lead the architecture and coding standards efforts, ensuring clean & efficient code.\n- Implement modern best practices and patterns in software development.\n- Mentor junior software engineers, providing guidance and support to foster their growth and development.\n- Conduct code reviews, ensuring coding standards, best practices, and security guidelines are adhered to.\n- Troubleshoot, debug, and upgrade existing software.\n- Stay up-to-date with emerging trends and technologies in software development to continuously improve our products and processes.\n\nYour skills and experience\nWhat Essential Skills You Will Need\n- Bachelor\'s degree in Computer Science, Engineering, or a related field.\n- 5+ years experience in backend development with clear architecture mindset\n- Solid understanding of programming principles, financial transaction consistency, and Git version control.\n- Experience with software development life cycle and agile methodologies.\n- Proven experience in designing scalable and maintainable architectures.\n- Strong communication and teamwork skills, with the ability to collaborate effectively with cross-functional teams.\n- A passion for mentoring and guiding junior team members.\n- A continuous learner, open to embracing new technologies and development practices.\n- Aspirations to be/become a Team Lead is a pre.\n- Experience with a relational database such as MySQL, PostgreSQL, or Oracle\n- Experience deploying code in AWS, Azure, or Google Cloud environments.\n\nWhy you\'ll love working here\nLife at Grab\nWe care about your well-being at Grab, here are some of the global benefits we offer:\n- We have your back with Term Life Insurance and comprehensive Medical Insurance.\n- With GrabFlex, create a benefits package that suits your needs and aspirations.\n- Celebrate moments that matter in life with loved ones through Parental and Birthday leave, and give back to your communities through Love-all-Serve-all (LASA) volunteering leave.\n- We have a confidential Grabber Assistance Programme to guide and uplift you and your loved ones through life\'s challenges.\n\nWhat we stand for at Grab\nWe are committed to building an inclusive and equitable workplace that enables diverse Grabbers to grow and perform at their best. As an equal opportunity employer, we consider all candidates fairly and equally regardless of nationality, ethnicity, religion, age, gender identity, sexual orientation, family commitments, physical and mental impairments or disabilities, and other attributes that make them unique.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CMC Creative Space, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(734, 239, 2, 'IT Consultant manager/Business Analyst Lead', 'About the Role: \nWe are seeking an accomplished Senior IT Consultant Manager to join our high-performing team dedicated to delivering innovative internal IT solutions that empower our global organization of 500,000 users. In this pivotal role, you will lead a team of Business Analysts and IT consultants to navigate complex workflows platform, drive strategic migration efforts, deliver insightful business analytics, and provide expert guidance on all aspects of IT solutions. Your blend of leadership, technical acumen, and strategic vision will be instrumental in shaping the future of our IT landscape and ensuring alignment with overarching business objectives. \n\nKey Responsibilities: \nLeadership and Mentorship: Provide inspirational leadership and guidance to a team of BAs and IT consultants, fostering a collaborative and high-performing environment that encourages professional development and knowledge sharing. \nWorkflows Platform Modernization: Lead the analysis of workflows platform, meticulously documenting requirements and identifying gaps to facilitate a seamless migration to new technologies. Your expertise will be essential in understanding the complexities of existing systems and ensuring a successful transition to modern platforms. \nRequirements Elicitation and Documentation: Engage with diverse stakeholders across the organization to elicit, analyze, and document business requirements, translating them into clear, concise, and actionable user stories that drive development efforts. \nCross-Functional Collaboration: Act as a liaison between business units and the development team, fostering clear communication, managing expectations, and ensuring successful project delivery. Your ability to navigate both technical and business domains will be key to establishing strong partnerships and achieving project goals. \nData-Driven Decision Making: Design and implement business insights dashboards, providing stakeholders with actionable intelligence and key performance indicators to facilitate informed decision-making and strategic planning. \nStrategic Planning and Advisory: Contribute to the development of business plans, reports, and strategic initiatives, leveraging data-driven insights to improve product efficiency, streamline migration timelines, and drive overall business value. Ensure that the Business Plan and its resulting outcomes are not only actionable but also resonate with all stakeholders, fostering a sense of ownership and engagement. \nAgile Adoption and Advocacy: Champion Agile methodologies, actively participating in sprint planning, backlog grooming, and retrospectives, and cultivating an Agile mindset within the team. Your leadership will be instrumental in ensuring the team delivers value iteratively and incrementally. \n\nWork Packages & Additional Responsibilities: \nStakeholder Management: Cultivate and maintain strong relationships with stakeholders across the organization, adeptly managing expectations, addressing concerns, and resolving conflicts. Inspire the adoption of new technologies at every step of the product delivery process, effectively communicating their benefits and addressing any potential challenges. \nProcess Optimization: Continuously identify opportunities to optimize existing processes and workflows, driving efficiency gains and contributing to a culture of continuous improvement. \nChange Management: Play an active role in organizational change management efforts, supporting users through the adoption of new systems and processes. Your ability to communicate change effectively, build trust, and address concerns will be essential in facilitating smooth transitions and minimizing disruption. \nUser Acceptance Testing: Plan and execute comprehensive user acceptance testing (UAT), ensuring that solutions meet business requirements, user needs, and adhere to quality standards. \nTraining & Documentation: Develop clear and concise training materials and user documentation to facilitate seamless adoption of new technologies and processes. \nCross-Functional Collaboration: Thrive in a multinational team with diverse backgrounds and aspirations, fostering intensive collaboration and establishing effective cross-functional development practices. \nFunctional Work Item Tracking: Ensure functional work items are clearly defined, tracked, and managed throughout the project lifecycle. \nNon-Functional Work Item Creation: Identify, define, and prioritize non-functional requirements, ensuring they are incorporated into the project plan. \nEngagement Activities: Support or plan activities to engage stakeholders and foster a collaborative environment. \n\nYour skills and experience: \nProven Experience: 10+ years of Business Analysis experience, with a demonstrable track record of success in internal IT solutions and workflows platform migration projects. \nEducation Background: Graduate in Bachelor’s degree or preferably Master’s degree in Information Technology Business Management or Computer Science. \nLeadership & Mentorship: Proven ability to lead, inspire, and mentor a team of BAs and consultants, fostering a high-performing and collaborative environment. \nAnalytical Acumen: Exceptional analytical and problem-solving skills, with the ability to dissect complex systems and processes and identify opportunities for improvement. \nExceptional Communication: Superior written and verbal communication skills, adept at tailoring your message to both technical and non-technical audiences and building strong relationships with stakeholders at all levels. \nData-Driven Decision Making: Proficiency in data analysis and visualization tools, with a demonstrated ability to derive actionable insights from complex datasets. \nAgile Expertise: Experience working in an Agile environment, with a solid understanding of Agile principles, practices, and ceremonies. \nTechnical Aptitude: Familiarity with the software development lifecycle, relevant technologies, and architectural principles. \nCertifications: Relevant certifications such as CBAP, PMI-PBA, or Agile certifications are highly desirable. \nCross-Cultural Sensitivity: Ability to work effectively in a diverse and multinational environment, demonstrating respect and appreciation for different perspectives and cultural nuances.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa street, ward 13, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(735, 508, 2, 'Fullstack Developer (Python/JavaScript)', 'Top 3 reasons to join us\n- Work with modern tools and clear processes\n- Grow your skills on real-world projects\n- Contribute directly to business success\n\nJob description\n- Build and maintain fullstack web apps using Python (Flask, FastAPI) and JavaScript/TypeScript (React, Next.js)\n- Develop and integrate REST APIs for modern web applications\n- Collaborate closely with product, design, and engineering teams\n- Use AI-powered tools to boost development productivity\n- Write clean, maintainable code across frontend and backend\n\nYour skills and experience\n- 4–5 years of hands-on fullstack software development experience, especially in:\n  - Python (Flask, FastAPI)\n  - JavaScript / TypeScript (Node.js, React, Next.js)\n- Practical experience working with vector search technologies, particularly Convex\'s vector capabilities, for both backend and frontend applications.\n- 6+ months of experience with Prompt Engineering and AI coding accelerators (Cursor, Windsurf, Claude, V0, Bolt) to boost coding productivity.\n- Experience with Pimcore or other Product Information Management (PIM) systems is an advantage.\n\nTechnical Skills\n- Strong expertise in REST API development and integration, including:\n  - Backend: Building scalable APIs with Flask and FastAPI.\n  - Frontend: Integrating APIs into modern React/Next.js applications.\n- Solid understanding of data structures, algorithms, and software design patterns across both backend and frontend architectures.\n- Skilled in Next.js for building high-performance, server-rendered web applications.\n- Practical experience in developing and integrating AI-enhanced features into production applications (e.g., AI search, AI assistants).\n- Familiarity with machine learning frameworks such as TensorFlow, PyTorch, and scikit-learn (preferred).\n- Deployment experience using cloud platforms (AWS, GCP, Azure — bonus) and serverless environments (Vercel, Convex).\n- Experience with Docker for containerized fullstack development (preferred).\n\nSoft Skills\n- Strong problem-solving mindset across the full stack (frontend, backend, and infrastructure).\n- Effective communication skills to collaborate with engineers, product teams, designers, and business stakeholders.\n- Strong commitment to writing clean, maintainable, and well-documented code for both frontend and backend projects.\n\nWhy you\'ll love working here\n- Remote working, hence no need to commute to work daily. Great for applicants in smaller towns or cities.\n- 5 days working per week but in blocks of 5 days when necessary, which means up to 2 weekends may be spent working. Your manager is empowered to grant you extra vacation.\n- Plenty of learning and training during office hours\n- Teamwork is expected and it is the way we work. Managers will guide and interact with you closely.\n- The first month\'s salary is 30 million VND. And will be reviewed for an increase from the second month.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 1, Ho Chi Minh; Cau Giay, Ha Noi; Others', 'Full-time', '2025-10-07 20:59:18.149534'),
	(736, 393, 2, 'ERP Odoo Consultant (Business Analyst)', 'Top 3 reasons to join us\n- Flexible working hours at the office.\n- International team, daily English communication\n- Motivating bonus system for our employees.\n\nJob description\n- Analyze client business processes and requirements to design business solutions with detailed requirements. Produce Functional Specification, UAT plan, and prepare case tests, flowcharts, and diagrams.\n- Accompany customers in the full delivery cycle from software configuration to Go-live.\n- Internal testing on configuration/development should be conducted before releasing them for UAT.\n- Create a user manual and provide training and support to end-users as per the agreement defined.\n- Troubleshoot and resolve Odoo-related issues.\n- Collaborate with cross-functional teams for system integration.\n- Stay updated on Odoo developments and suggest improvements.\n- Support the sales team during pre-sales by creating and presenting a demo.\n- Prepare presentation slides in English or other specific language if required.\n- Prepare MoM in English or other specific language if required.\n- Able to manage and control budget, timeline, and scope of small-medium sized projects.\n- Develop and coach your subordinates.\n\nYour skills and experience\n- Bachelor\'s degree in Information Systems / Computer Science / Business / Accounting / Management. A master\'s degree in business management is an advantage.\n- Minimum of 2 years of relevant experience in ERP Odoo implementation.\n- Good communication, presentation, and writing skills in English.\n- Strong knowledge of Odoo ERP system, including configuration and customization.\n- Proven experience as an Odoo Consultant or similar role.\n- Odoo certification(s) or equivalent industry certifications.\n- Knowledge of other ERP systems and business applications.\n- Language Skills: Native/Fluent in Vietnamese is required, while proficiency in English is preferred.\n- Work Authorization Requirement: Candidates must have valid work authorization in Vietnam to be considered for this position.\n\nWhy you\'ll love working here\nCompensation & Perks\nWe offer an attractive salary package, including a performance-based bonus. Your hard work and successful projects directly translate into your rewards.\nTeam Building & Events\nWe believe in creating a diverse and inclusive workplace culture that supports the growth and well-being of our team members both professionally and personally.\nCoaching & Mentoring\nOur comprehensive coaching and mentoring program empowers our staff for future success. We provide coaching sessions with documentation and practices to accelerate learning, refine skills, and navigate challenges.\nFlexible Working Hours\nAt Portcities, we understand that our team has diverse needs and responsibilities outside of work. We have flexible working hours, so you can better manage your schedule and find the optimal time for productivity.\nInternal Transfer Opportunities\nPortcities, with 12 branches worldwide, offers internal transfer opportunities, providing exposure to different regions and cultures and enhancing your career journey.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '10 Vinh Khanh Street, Ward 10, PLS Building (1st Floor), District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(737, 509, 2, 'AI Developer', 'Coder Trove is seeking an AI Developer to join immediately working on a FinTech application. Working closely with our team you will be given regular training and support, and work in a fun and friendly team environment.\n\nYour role:\n- Develop, optimize, and deploy AI modules for business process automation, focusing on Large Language Models (LLMs) and agent-based systems.\n- Design and implement machine learning (ML) and deep learning (DL) models to support LLM agents and related applications.\n- Create automation solutions tailored to invoice financing and other business needs, ensuring scalability and reliability.\n- Integrate AI solutions into existing infrastructure in collaboration with cross-functional teams, ensuring seamless deployment and performance.\n- Conduct data preprocessing, feature engineering, and exploratory data analysis to prepare high-quality datasets for model training and evaluation.\n- Stay at the forefront of AI and ML advancements by exploring and experimenting with the latest technologies and methodologies.\n- Document project workflows, model architectures, and key development milestones for knowledge sharing and process transparency.\n- Collaborate with the Project Manager and team to fulfill additional project-related tasks as needed.\n\nYour skills and experience\n- Having a degree in Computer Science, Computer Science, Artificial Intelligence, Data Science, or related field is helpful but not required.\n- 1–3 years of hands-on experience in AI/ML development.\n- Proficiency in Python and frameworks such as TensorFlow or PyTorch.\n- Solid understanding of machine learning algorithms and data structures.\n- Strong problem-solving skills and attention to detail.\n- Good English communication skills, both written and spoken.\n- Proven ability to analyze business data models and manage training/fine-tuning processes.\n- Previous work with international teams and using English for communication;\n\nNice to Have (But Not Required):\n- Hands-on experience with Python frameworks like FastAPI, LangChain, or LangGraph.\n- Experience with the MERN stack (MongoDB, Express, React, Node.js) to support integration and deployment of AI solutions within web-based systems.\n- Familiarity with OpenAI APIs or other Large Language Model providers and their integration into business solutions.\n- Strong background in ML/DL frameworks (e.g., PyTorch) and experience in deploying production-grade AI models.\n- Experience with Agile/Scrum;\n\nWhy you\'ll love working here\n- A 13-month salary bonus.\n- 13 days of paid leave and 10 days of sick leave.\n- WFH as needed.\n- High-quality health insurance and health check-ups.\n- Company trips.\n- Regular team events with office food delivered twice a week; extra drinks and snacks are always available.\n- Support for training and certifications to improve your skills.\n- A friendly management team, a flexible working environment, and opportunities for career growth.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '30 Nguyễn Thị Diệu , District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(738, 510, 2, 'Technical Lead (Java/Golang)', 'Top 3 reasons to join us\n\n1. Sự nghiệp thăng tiến không giới hạn\n2. Dự án công nghệ trong và ngoài nước\n3. Thu nhập hấp dẫn, đãi ngộ toàn diện\n\nJob description\n- Phân tích yêu cầu kỹ thuật của sản phẩm, lựa chọn công nghệ và xây dựng kiến trúc hệ thống cho sản phẩm và hệ thống nội bộ của công ty\n- Là người định hướng và đưa ra các giải pháp kỹ thuật cho các dự án của công ty bao gồm: công nghệ sử dụng, kiến trúc phần mềm, chiến lược và định hướng phát triển phần mềm\n- Sizing hệ thống\n- Đánh giá cấu trúc hệ thống hiện tại, đề xuất các giải pháp để cải thiện hệ thống, giám sát và hướng dẫn team dev thực hiện các giải pháp đưa ra\n- Phân tích yêu cầu dự án, thiết kế giải pháp cho từng dự án cụ thể\n- Giải quyết các vấn đề kỹ thuật phát sinh\n- Nghiên cứu các công nghệ hiện và đề xuất thay đổi khi cần thiết\n\nYour skills and experience\n- Có ít nhất 5 năm kinh nghiệm làm việc trong lĩnh vực phát triển phần mềm.\n- Hiểu biết sâu rộng về các ngôn ngữ lập trình và framework như Java/Golang và các công nghệ web.\n- Có kinh nghiệm với các phương pháp phát triển phần mềm như Agile, Scrum, và DevOps.\n- Đã từng làm việc trong vị trí teamlead trong dự án phần mềm. Hiểu biết về quản lý dự án, kế hoạch hóa, và theo dõi tiến độ dự án.\n- Có kiến thức chuyên sâu về các khái niệm kỹ thuật như kiến trúc phần mềm, thiết kế hệ thống, và bảo mật thông tin.\n- Có kinh nghiệm làm việc với các công nghệ tích hợp như Redis, Kafka, Nginx, API Gateway...\n- Có kinh nghiệm về tối ưu database, tối ưu source code\n- Có khả năng giải quyết các vấn đề kỹ thuật phức tạp và đưa ra các giải pháp hiệu quả.\n- Có khả năng giao tiếp mạch lạc với các thành viên trong đội ngũ, quản lý và các bộ phận khác trong tổ chức.\n- Có khả năng viết báo cáo và tài liệu kỹ thuật một cách rõ ràng và dễ hiểu.\n- Sử dụng thành thạo các công cụ quản lý mã nguồn như Git, SVN.\n- Có kinh nghiệm với các công nghệ và framework phổ biến như Docker, Kubernetes, và Jenkins.\n- Hiểu biết về quản lý cơ sở dữ liệu và các công nghệ liên quan.\n\nWhy you\'ll love working here\n1. Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh thỏa thuận theo kinh nghiệm và năng lực.\n- Lương tháng 13, Thưởng quý, Thưởng dự án, Thưởng năng suất.\n- Nghỉ mát, thưởng ngày lễ và các ngày chỉ có ở Viettel như Ngày Sáng Tạo - 1/6, 22/12, quà Tết Dương, Tết Âm tri ân Gia đình, người sinh thành (25-30 triệu/năm)\n- 16 ngày nghỉ phép/năm hưởng nguyên lương\n- Bảo hiểm sức khỏe bảo hiểm sức khỏe cho người thân, bảo hiểm nhân thọ,…\n- Hưởng các Chính sách đãi ngộ toàn diện của "Người Viettel"\n\n2. Cơ hội phát triển bản thân\n- Cơ hội thăng tiến không giới hạn, trở thành quản lý của các dự án mới\n- Được thử sức với các công nghệ mới, dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội được đào tạo, trau dồi kĩ năng, chuyên môn để phát triển toàn diện.\n\n3. Môi trường làm việc\n- Được làm việc trong Tập đoàn toàn cầu, tiên phong thực hiện sứ mệnh kiến tạo xã hội số.\n- Môi trường mở, trẻ trung, năng động, trân trọng, yêu thương, tương hỗ & lắng nghe mỗi người từ những ý tưởng nhỏ nhất.\n- Không gian làm việc xanh, mở, hiện đại.\n\n4. Địa điểm làm việc\n- 36A Dịch Vọng Hậu, Cầu Giấy, Hà Nội\n- Thời gian làm việc: Thứ 2 đến thứ 6', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '36A Dịch Vọng Hậu, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(739, 229, 2, 'Server Developer ( C language )', 'Headquarter: Daoukiwoom Group - Find more at: \nIndustry: Finance & Trading\n\n- Develop server-side systems using Unix/Linux C programming within the Kiwoom platform, utilizing CISAM, IPC, and Shared Memory\n- Collaborate directly with remote teams to clarify tasks and requirements\n- Analyze user requirements and participate in system design to develop new features\n- Investigate and resolve reported issues and bugs during integration testing, user acceptance testing, and maintenance testing\n- Manage time and resources effectively based on the Work Breakdown Structure (WBS)\n- Compile weekly progress reports detailing task status and developments\n- Engage in continuous self-learning to acquire domain knowledge, prepare reports, and conduct seminars to share insights\n- Write high-quality, clean, maintainable, and testable code following best practices\n- Ensure technical documentation is accurate and up-to-date\n- Mentor junior developers and provide technical training when necessary\n- Gain hands-on experience in all stages of diverse projects, covering various aspects of software engineering and fostering your professional growth.\n\nYour skills and experience\nEducation & Experience\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Minimum 2-3 years of professional experience in C language\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nTechnical skills\n- Experience with C language focus in: CISAM, IPC, Shared Memory\n- Prior experience with Korean stock market systems is a significant advantage.\n- Familiarity with version control systems, such as Git or SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n\nSoft Skills & Communication\n- Able to communicate in English, written and spoken (processed by English interview).\n- Strong communication skills and teamwork, international experience is preferred.\n- Strong problem-solving and analytical skills.\n\nGive Reference\n- Over 1 year of experience in developing securities solutions under channel server side\n- Experience on working with oversea team.\n- Develop and maintain the Channel Server for the Korean stock market system.\n\nWhy you\'ll love working here\nSPECIAL OFFER\n- Providing training and education experience in Korea with Korean Finance/IT expert\n- Providing opportunities to work and support in IT/Finance fields overseas\n\nBENEFITS\nIncome & Achievement\n- Competitive salary, salary review once a year\n- 13th month salary and Annual Performance Bonus\n- MVP and Shining star awards at the end of year\n- Global and professional working environment\n\nWorkplace Happiness\n- Full SHUI as Vietnamese Law\n- Premium Private Medical Insurance PVI and annual health check\n- 15-day annual leave, Christmas leave and 90 min menstrual leave for women\n- Company event, YEP and monthly gathering time\n- Gifts on special occasion and fully stocked snack corner\n- Sponsored training courses and book purchase quarterly\n- Be well-equipped with new working equipment\n\nHIRING PROCESS: The interview will be conducted at our office in Ho Chi Minh city.\nRound 1:\n- Step 1: Live coding test\n- Step 2: Interview with part team leader (upon passing coding test)\n- Step 3: Interview with Director\nRound 2: Final interview with Head Office in Korea.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '14F, AP Tower, 518B Dien Bien Phu Street, Ward 21, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(740, 203, 2, 'Senior Data Engineer (Python, SQL)', 'Top 3 reasons to join us\n- Disruptive innovations\n- People-oriented philosophy of doing business\n- Your footprint on regional on-demand market\n\nJob description\n- Build, maintain and optimize in-house data infrastructure including database, data warehouse, orchestration system, data streaming and batching pipelines.\n- Work with multiple Cloud Platforms such as GCP, AWS, Databricks.\n- Work with big and complex datasets for multiple departments.\n- Create a benchmark, alert, and audit log for the data system.\n- Communicate with stakeholders including Product, Software Engineers, Business Users, Data Analysts and Data Scientists to solve data-related requests.\n\nYour skills and experience\n- Bachelor degree in Computer Science or Software Engineer or Information System\n- Specializing in data science or a higher degree is a big plus.\n- From 04 year experiences in data engineer role and building data platforms and pipelines for analytics.\n- Excellence in at least one programming language such as Python, Java, Scala, Go, Javascript, Typescript, R.\n- Excellence at SQL in DBMS.\n- Experience with cloud services such as GCP, AWS.\n- Experience with various OLTP and OLAP databases and data warehouses: MongoDB, PostgreSQL, BigQuery, ClickHouse, etc.\n- Experience with streaming process platforms and streaming concepts such as Redpanda, Kafka, RabbitMQ, CDC or open-sources.\n- Experience with data pipeline and workflow management tools: Airflow, dbt, Airbyte, etc.\n- Knowledge of data visualization tools like Metabase, PowerBI, Looker Studio, etc.\n- Exposure to emerging open-source or technologies to apply.\n- Experience with building and developing API with Python, Go or Javascript/Typescript.\n- Experience with using source version control such as gitlab, github.\n- Experience with Hadoop, Spark, Databricks is a big plus.\n- Experience with Kubernetes is a big plus.\n\nWhy you\'ll love working here\nAt Ahamove, we are always driven by data and recognize it as a fuel for innovation. We collect, analyze and integrate data into every corner of the enterprise. \nThe data team is the backbone of our company. Just like the “on-demand delivery” segment, our data team provides "on-demand technologies" to serve our fast-changing business needs and evolving market. Our data team has the power to try many up-to-date solutions, tools and technologies such as Cloud Services, Big Data Distributed System, Machine Learning Model...\nCurrently, we have created different data positions to solve a variety of problems which are fun, challenging and meaningful. We welcome young talents with fresh minds to join us on our way to become a 5-star company.\nLet\'s grow together.\n\nBenefit\n- Grab/Be for work: 1M/month\n- Laptop & PVI insurance\n- Working 5 days/week (Mon - Fri)\n- Competitive salaries and benefits according to experience and education level\n- And more\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Rivera Park 7/28 Thành Thái, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(741, 245, 2, 'Cloud/DevOps Engineer', 'Top 3 reasons to join us\n- Salary and bonus based on ability\n- Young and fun working environment \n- Opportunities to study and work abroad.\n\nJob description\n- Design and implement secure, scalable, and highly available cloud solutions using platforms like AWS, GCP, or Azure, …\n- Lead cloud migration projects, ensuring minimal downtime and seamless transitions from on-premises or between cloud providers.\n- Automate infrastructure provisioning using IaC tools such as Terraform, or CloudFormation.\n- Automate configuration management using tools such as Ansible or Chef.\n- Deploy and manage containerized applications on platforms like EKS, GKE, or AKS.\n- Design and enhance CI/CD pipelines, adopting GitOps using tools like Jenkins, GitLab CI, or ArgoCD for streamlined deployments.\n- Implement and maintain monitoring tools to track system performance, availability, and scalability.\n- Analyze and manage cloud resource costs, implementing strategies for cost optimization.\n- Enforce and maintain cloud security practices to create a secure and compliant environment.\n- Collaborate with Development Team, Security Team, and Operations Team to ensure cloud solutions align with business and technical goals.\n- Provide technical leadership by making strategic decisions and driving innovation across projects (for senior roles).\n- Mentor and guide team members, fostering a culture of collaboration, learning, and technical excellence (for senior roles).\n- Stay updated with industry trends, continuously leveraging new practices to enhance team performance (for senior roles).\n\nYour skills and experience\n- Bachelor’s degree or higher in IT, Computer Science, or a related field.\n- At least 3 years of experience in roles such as Cloud Architect, Cloud Consultant, or DevOps Engineer with expertise in AWS, GCP, or Azure.\n- Familiarity with scripting languages such as Bash, Python, or Golang is a plus.\n- Experience with AI/ML technologies, including Cloud AI platforms, AI Orchestrators, and DataOps, is a plus.\n- Proven experience in leading technical teams or managing projects is an advantage.\n- In-depth knowledge of system design, architecture patterns, and cloud best practices.\n- Strong problem-solving abilities and analytical skills.\n- Proficiency in English; understanding Korean is a significant advantage.\n\nWhy you\'ll love working here\n- Best remuneration: Periodically review and adjust salary once a year, PI bonus twice a. Allowances for lunch, transportation, and phone charges. Party with the team once a. Workshop travel for the whole company once a year. Bonuses/Gifts for holidays, International Labor Day, International Women\'s Day, etc.\n- High-class, modern office: 5-star standard office with modern equipment, large rest and entertainment areas (game area, karaoke room, reading room, cafe counter, snack bar, etc.) Meet all members\' needs, especially the office has an airy and beautiful view that is among the most beautiful in Hanoi.\n- Top equipment: Each employee is equipped with the latest generation LG Gram laptop and modern large LG screen.\n- Best working time: Work 8 hours/day (8:00 ~ 17:00), from Monday to Friday. No pressure to work overtime/weekends!\n- Flexible, youthful working style: LG CNS Vietnam members are mostly from the 9-10x generation, with a youthful, modern, and fair working style!\n- Creative environment, valuing individual opinions: With a young and talented team, we always appreciate the creativity and suggestions that members make.\n- Opportunities to work/study in Korea and abroad: With customers and projects mostly from abroad, your opportunities for training and onsite abroad will always be open!\n- Other: Happy hours every Friday, Team outing monthly, join clubs like football, badminton, etc...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(742, 511, 2, 'Kỹ Sư Giải Pháp Nghiệp Vụ (Business Analyst)', 'Top 3 reasons to join us\n- Excellent environment and team to help you grow.\n- Competitive salary and learning culture\n- International professional working environment\n\nJob description\n- Xây dựng giải pháp nghiệp vụ (đối với dự án nâng cấp có nghiệp vụ cụ thể, rõ ràng)\n  - Khảo sát nhu cầu, phân tích và mô hình hóa nghiệp vụ khách hàng\n  - Xây dựng tài liệu phân tích nghiệp vụ (PTYC), làm Prototype\n  - Chốt thống nhất với khách hàng về yêu cầu bài toán\n  - Xây dựng tài liệu giải pháp và thiết kế chi tiết tính năng về mặt người dùng theo yêu cầu của Trưởng sản phẩm hoặc khách hàng. (Chi tiết các trường dữ liệu, các trường hợp ràng buộc, ngoại lệ)\n  - Giải đáp, trao đổi các thắc mắc về mặt nghiệp vụ của đội dự án.\n- Quản lý dự án\n  - Cập nhật tài liệu liên quan trong dự án theo quy trình.\n  - Quản lý và lưu trữ các yêu cầu thay đổi theo đúng quy trình.\n  - Hỗ trợ AM, PM nghiệm thu sản phẩm/hệ thống với khách hàng\n  - Tính toán nỗ lực, chi phí thực hiện cho các yêu cầu nghiệp vụ.\n\nYour skills and experience\n- Bằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng hoặc tương đương.\n- Ngoại ngữ: Đọc hiểu tài liệu tiếng Anh. Ưu tiên có chứng chỉ TOEIC 550+ (hoặc IELTS, TOEFL tương đương).\n- Kiến thức, kinh nghiệm:\n  - Có tối thiểu 2 năm kinh nghiệm ở vị trí ứng tuyển.\n  - Có kiến thức về các kĩ thuật phân tích nghiệp vụ, mô hình hóa các luồng nghiệp vụ như: các mô hình chức năng nghiệp vụ, mô hình dữ liệu quan hệ, ngôn ngữ UML, tạo Use case, BPMN,…\n  - Biết cách xây dựng prototype của sản phẩm/ứng dụng.\n  - Có khả năng giao tiếp, diễn đạt tốt\n  - Tư duy phản biện, kỹ năng đàm phán\n  - Tổ chức các cuộc họp.\n- Tinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội.\n\nWhy you\'ll love working here\n- Lương cạnh tranh: Thu nhập "ổn áp", xứng đáng với năng lực và kinh nghiệm.\n- Môi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '46A Nguyễn Văn Đậu,P.6, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(743, 212, 2, 'Software Development Manager', 'We are seeking an experienced bilingual (Vietnamese/ English) and motivated Software Development Manager to lead a team of software engineers in the design, development, testing, and deployment of scalable software solutions. You will be responsible for guiding technical execution, promoting best practices, and ensuring successful project delivery aligned with business goals.\n\nKey Responsibilities:\n• Team Leadership: Manage, mentor, and grow a team of software engineers through coaching, career development, and performance reviews.\n• Project Management: Oversee project planning, execution, and delivery across multiple software initiatives, ensuring timelines and quality standards are met.\n• Technical Guidance: Collaborate with architects and senior engineers to ensure high-quality code and system architecture. Participate in code reviews and design discussions.\n• Agile Practices: Drive agile methodologies (Scrum, Kanban, etc.), promote continuous integration and deployment (CI/CD), and improve development workflows.\n• Cross-Functional Collaboration: Work closely with Product Managers, QA, DevOps, and UX teams to align software delivery with business objectives.\n• Recruitment & Onboarding: Assist in hiring top Software Development talent and ensure smooth onboarding processes for new team members.\n• Metrics & Reporting: Define and monitor development KPIs, track team productivity, and report progress to senior leadership.\n\nYour skills and experience:\n• Bachelor’s or Master’s degree in Computer Science, Engineering, or related discipline.\n• 5+ years of experience in software development, with 2+ years in building enterprise applications. Experience developing enhancements for ERP systems (Epicor, SAP, Dynamics and or Oracle).\n• Strong knowledge of software engineering principles, architecture, and modern development stacks (e.g., JavaScript/TypeScript, Angular, Python, Java, C#, Xamarin, Mobile (IOS / Android), cloud services like AWS/Azure/GCP).\n• Experience managing full SDLC (Software Development Lifecycle) in agile environments.\n• Excellent leadership, communication, and decision-making skills.\n• Proven track record of delivering high-quality software products on time.\n\nWhy you\'ll love working here:\n• Performance bonuses End Year Bonus.\n• Health insurance.\n• Professional development budget.\n• Provide laptops and necessary equipment for work.\n• May require some local and international travel.\n• Collaborative, inclusive team culture.\n• Yearly team building.\n• Flexible hours and remote work options.\n• Health insurance.\n• Salary Adjustment 2 time/ year.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '196A Nguyen Van Huong, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(744, 450, 2, 'Senior Software Engineer - Frontend', 'About the role:\nWe are seeking team members who strive to solve hard problems, take pride in delivering world-class products, and are strong team players.\nYou are someone who wants to see the impact of your work making a difference every day. You find passion in the craft and are constantly seeking improvement and better ways to solve tough problems.\n\nResponsibilities:\n• Contribute to the ideation, technical design, implementation, and testing of product features that empower our business and deliver impact to our customers.\n• Produce high-quality software following good architecture and design principles that are scalable.\n• Design and deliver well-thought-out user interfaces with a strong sense of the overall user experience.\n• Collaborate with the team to define the future of the ShopBack experience.\n• Strong mentoring skills with the ability to provide technical guidance and review code.\n\nYour skills and experience\nRequirements:\n• 4+ years of experience building and designing delightful user experiences as a frontend engineer.\n• Strong knowledge of HTML, CSS, and JavaScript.\n• Understanding of good software design principles and have applied principles to professional work.\n• Hands-on experience working with ReactJS (Preferred) and ecosystem.\n• Have knowledge in Test Driven Development (TDD), CI/CD.\n• Familiarity with RESTful APIs and TypeScript.\n• Ability to work effectively in a fast-paced, complex technical environment with high adaptability and flexibility.\n\nWhy you\'ll love working here\nHave these benefits and a lot more at ShopBack VN:\n• Attractive Stock Options for all employees\n• Up to 4-month salary of Performance Bonus\n• 13-month Salary\n• 15 days of annual leave + 3 days of Medical leave + 1 day of birthday leave \n• 5 days of Additional Time Off (after annual leave entitlement is fully utilized)\n• IDP Budget\n• PVI Healthcare Insurance\n• Other benefits: Fun monthly and quarterly activities; Fully stocked pantry of fun and healthy food/snacks; Ping-Pong table, PS4 in the office! \n\nWhich of these core values connects with you the most?\nOur Mission: To make shopping rewarding, delightful, and accessible.\nOur #SHOPBACK Values\nOur Values are not “Sound/Feel Good” values that are for show. We understand how our values build our culture and believe these aligned values will help us work better together to achieve our mission. We will hire, part ways, recognize or reward ShopBackers based on our values. Upholding these values is as important as our performance at work.\n\nHere are our 8 Values #SHOPBACK:\n• Succeed as One\n• Honour Our Customers\n• Own the Problem \n• Pave New Roads \n• Be Better Every Day \n• Always Be Curious \n• Can’t is Not an Option\n• Keep It Real', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Complex Tower, 285 Cach Mang Thang Tam Street, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(745, 512, 2, 'Bridge Project Manager (BrSE/ IT Communicator)', 'Xin chào and こんにちは！, chúng tôi là Vitalify Asia, một công ty IT có trụ sở tại Nhật Bản và hoạt động tại Thành phố Hồ Chí Minh từ năm 2008.\nChúng tôi đang mở rộng hoạt động kinh doanh và tuyển dụng cho vị trí BPM (Bridge Project Manager), dành cho cả cấp độ senior và junior.\nBPM là một vai trò độc đáo tại VFA, kết hợp giữa BrSE/ IT Communicator và Quản lý Dự án, dựa trên triết lý của chúng tôi. Vai trò này bao gồm giao tiếp bằng ngoại ngữ và quản lý dự án.\nNhững kỹ năng quan trọng cho vị trí này bao gồm khả năng hiểu biết về kinh doanh và kỹ năng giao tiếp. Nếu bạn có tiềm năng, chúng tôi sẽ đào tạo, ngay cả khi bạn chưa có kinh nghiệm trước đó.\nChúng tôi hy vọng đây sẽ là cơ hội tuyệt vời cho sự phát triển của bạn.\nJOB DESCRIPTION\n- Joining a real DevOps (Healthcare/Global Market) project as a professional BPM.\n+ Healthcare, Fintech, Startup, Games, AR/VR, and AI.\n+ DevOps, Agile as our standard, and Enterprise Waterfall projects.\n+ We usually work with product owners directly as per our policy.\n- Discussing requirement/schedule/system design with Japanese product owner directly.\n- Reporting process of project daily, weekly and monthly\n- Manage project estimation with the team.\nSKILL & EXPERIENCE REQUIREMENTS:\n- Experience Project Management or experience leading projects (PL, BrSE, IT comm etc...) within the past few years.\n- Experience in programming with any programming language is a plus.\n- Communication smoothly in Japanese (N2〜 level)\n- Communication skills in simple English (Chatting & Talking)\n- Having a sense of recognizing the issue & suggesting Kaizen plan.\n- Experience in creating System Design Documents, Development and Testing Plans is a plus.\n- Logical thinking & explanation skill based on factual data or numbers\n- Passion to learn hard, and become a high-level BPM, PMO, PM Specialist in short-term.\nABOUT US\nWe are a Japan-based web & mobile app development company (Outsourcing and some in-house products). We provide rapid product development and improvement on a DevOps basis with the teams committed to providing value to users.\nLocated in Ho Chi Minh City, Vietnam, we have been operating since 2008.\n<Vitalify Asia Co., Ltd.>\n▪BUSINESS CONTENTS: Mobile / Web & AI development (Outsourcing / In-house Products)\n▪LOCATION: 224A-224B Dien Bien Phu, District 3, HCMC\n▪ESTABLISHMENT: 2008\n▪NUMBER OF EMPLOYEES: 150 (with 15 legal aliens Japanese and 1 Korean)\nWORKING ENVIRONMENT\n▪PC: Macbook Pro / Air for all employees ☆\n▪Process: Agile ☆ / Waterfall / Hybrid\n▪Method: DevOps ☆\n▪Group Ware (Email/Storage/Docs): Google Workspace ☆\n▪Communication Tools: Chatwork ☆ / Slack / Etc..\n▪Online MTG Tools: Zoom ☆ / Google Meet ☆ / Etc..\n▪PJ Task Management: Redmine ☆ / Jira / Backlog / Etc..\n▪Employee Evaluation Policy: We evaluate your growth, & We will adjust your salary to market value or more ▪Testing Device (Smart Phone): A lot of the latest\n▪Checkin/out Time Management: Own System (Apps)\n▪Certification Allowance: Many kinds, salary base up\n▪Salary Review: Every 6 months\n▪Party & Event: A lot\n▪Career path: We define two main paths. Organizational management or expert(Specific Tech, PJ Management, UX design, Sales, Marketing, etc.). Even becoming Director, CTO, and also CEO of us is possible.\nOFFICE ENVIRONMENT\n▪Office Type: Individual French Villa with Garden\n▪Commute Type: Office & Remote (Hybrid)\n▪Desk: Free desk or fixed desk, with a lot of free space ▪Parking : Ready & Free at office garden area\n▪Office Wifi: Very fast! (Individual Line)\n▪Crowded Elevator : Never happen!\n▪Refrigerator: x4 (Always inside)\n▪Water Server: x5 Drink water forever!\n▪Personal Locker: One per person\n▪MTG Room & Space: 9 rooms & a lot of free space\n▪Co-worker : Nice!\n▪Rooftop Cafe Area: Have a break! ▪Dresscode: None\n▪Office Gym & Zen space: Yes! let\'s work out! ▪Chill Spot: Many!\n▪Sound System: Yes! Let\'s Play M.U.S.I.C ▪Music Instrument: Guitar x3 , Cajon x1\n▪Restroom: x4 room & x3 small x5 room 🚺🚹', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '224A-224B  Dien Bien Phu, Vo Thi Sau Ward, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(746, 475, 2, 'Backend Developer (JavaScript/TypeScript/NestJS/SQL)', 'Top 3 reasons to join us\n\nInternational product company with a neat product!\nWork-life balance, with local working hours\nImprove and practice your English every day!\n\nJob description\nIn 2004, we launched an app called MyRecipes that changed the way chefs worked in New Zealand. For the first time, they could cost recipes and check nutrition info in just minutes. Before that, it was slow, hard, and full of mistakes.\nWe didn’t know it then, but we were one of the first SaaS tools for chefs. That was just the start.\nNow, 20 years later (yes, time flies!), we’re building a brand-new version. With modern tech, a fresh design, and global users in mind — we’re ready to bring this to the world.\n\n👀 Who We’re Looking For\nWe’re looking for a NestJS developer who is confident with TypeScript and enjoys writing clean, efficient server-side code.\nYou’ll join a small, friendly, international team. Together, we’ll build fast, smart tools for chefs and food businesses.\n\n🔧 What You’ll Do\n- Backend Logic – Write and improve the logic that runs on the server\n- Database – Design, manage, and speed up our PostgreSQL database\n- APIs – Build APIs that connect the frontend, backend, and third-party tools\n- Integrations – Work with other systems like payments, support tools, and analytics\n- Performance – Make sure everything runs fast, securely, and reliably\n- Testing – Test and debug your work to keep things stable and bug-free\n\n💡 Why Join Us?\n- You’ll work on a real product with active users who love it\n- You’ll be part of a modern tech team using bleeding edge tech\n- You’ll help shape a product that chefs use every day around the world\n- You’ll get to build something meaningful — and learn a lot along the way\n- Practice and improve your English every day!\n\nYour skills and experience\nExperience\n- 3+ years of experience\n- Proficiency in JavaScript and TypeScript: Strong understanding of JavaScript and TypeScript, including their core concepts.\n- Database Knowledge: Excellent understanding of SQL and NoSQL databases (e.g., PostgreSQL, MongoDB, MySQL).\n- RESTful APIs: Familiarity with RESTful API design and implementation.\n- Version Control: Experience with code versioning tools (e.g., Git).\n- Front-End Familiarity: Basic knowledge of front-end technologies.\n- Server Deployment: Understanding of server deployment processes.\n- Experience with unit tests.\n- Basic English communication skills\n\nQualifications\n- Bachelor’s degree in Computer Science, Information Technology, or related field.\n\nWhy you\'ll love working here\nOur current team of 11 are based in Vietnam and the Philippines and are all incredibly passionate about what we do. We\'re very excited about what we are building and cant wait to release our new version. We follow agile methodology and love working together as a team.\n\nOur team values and team culture revolve around:\n- Simplification over complication. Removing and decrypting jargon.\n- Efficiency and smart thinking over hard work.\n- Work-life balance. We all value local working hours and respect time away from work.\n- We celebrate the wins. And often.\n- Teamwork. Collaboration fuels our success. We all win together.\n- Innovation. We seek new ways to solve problems.\n- Delight. Usability is good, but delight is better. We aim to surprise and exceed expectations.\n- Communication. Above all else, clear communication keeps us aligned.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hoang Dao Thuy, Trung Hoa Ward, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(747, 488, 2, '[Middle-Senior] CV An toàn thông tin - Blue Team', 'Mô tả công việc:\n- Triển khai và vận hành các giải pháp ATTT, xây dựng quy trình trong việc vận hành giám sát an ninh mạng;\n- Tham gia ứng cứu sự cố trên các hệ thống, nền tảng khác nhau (Windows, Linux,...);\n- Phát triển và quản lý vòng đời của rule detection để hỗ trợ quá trình giám sát và ứng phó sự cố;\n- Nghiên cứu, phát triển các sản phẩm, giải pháp an ninh mạng;\n- Nghiên cứu, mô phỏng các kỹ thuật tấn công mới, đề xuất biện pháp phòng chống;\n- Viết tài liệu & đào tạo về quy trình vận hành, hướng dẫn sử dụng các hệ thống ATTT;\n- Tham gia đào tạo, xây dựng đội ngũ Blueteam và RnD.\n\nTrình độ: Middle - Senior\n\nQuốc tịch: Việt Nam\n\nTrình độ:\n- Tốt nghiệp Đại học ngành an toàn thông tin;\n- Có chứng chỉ OSDA, CDSA hoặc kỹ năng tương đương.\n\nKỹ năng:\n- Nắm vững các công nghệ hạ tầng: Docker, Kubernetes, Ansible, ESXi,...\n- Thành thạo Python hoặc Golang, có khả năng phát triển công cụ hỗ trợ trong công việc;\n- Có khả năng làm việc độc lập;\n- Tư duy sắc bén và khả năng giải quyết vấn đề tốt;\n- Khả năng giao tiếp tốt, kỹ năng thuyết trình và tư vấn dịch vụ, sản phẩm;\n- Khả năng làm việc nhóm với cường độ và áp lực cao.\n\nKinh nghiệm:\n- Có 3 đến 5 năm kinh nghiệm trong lĩnh vực An ninh mạng, vận hành các hệ thống giám sát an toàn thông tin. Nắm được quy trình trong việc vận hành giám sát an ninh mạng;\n- Có kinh nghiệm DFIR, sử dụng các công cụ hộ trợ như Volatility, FTK Imager, Sysinternals Suite, Velociraptor,...\n- Có kinh nghiệm triển khai giải pháp bảo mật mã nguồn mở như Firewall, IDS/IPS, SIEM, SOAR,...\n- Có kinh nghiệm xây dựng, dẫn dắt đội nhóm trong các nhiệm vụ của Blueteam;\n- Có kinh nghiệm quản lý là một lợi thế.\n\nLương, thưởng:\n- Lương theo thỏa thuận: 25 – 30 triệu VNĐ/tháng Gross;\n- Lương tháng thứ 13, thưởng dự án theo quy định của công ty.\n\nQuyền lợi:\n- Môi trường làm việc trẻ trung, năng động và thân thiện, chú trọng đào tạo, phát triển;\n- Cung cấp thiết bị làm việc;\n- Được hưởng các chế độ phúc lợi, bảo hiểm theo quy định của pháp luật và các chính sách ưu việt khác của Công ty;\n- Văn hóa Công ty: Đa dạng và hòa nhập (D&I), chú trọng cân bằng giữa công việc, cuộc sống cá nhân và đời sống tinh thần với những hoạt động hấp dẫn: Thể thao, Happy Hour, Team Building, Du lịch hằng năm,...\n- Giờ làm việc linh hoạt;\n- Cơ hội làm việc và hợp tác với các chuyên gia hàng đầu trong ngành An ninh mạng, mở rộng kiến thức và nâng cao kỹ năng chuyên môn;\n- Được hỗ trợ đào tạo chuyên sâu, thi các chứng chỉ chuyên môn phục vụ công việc;\n- Lộ trình thăng tiến rõ ràng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Trung tâm đổi mới sáng tạo quốc gia (NIC), số 6 ngõ 7 Tôn Thất thuyết, Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(748, 513, 2, 'Software Developer (Server, Back-End, DevOps, Unity)', 'About The Role\n\nBootloader Studio is shipping real-time, emotion-aware experiences in Unity. We need a Backend-first engineer who will own our cloud services while lending a hand with DevOps automation and the odd IT tweak. If wearing a couple of hats in a fast-moving startup sounds like fun, let’s talk.\n\nDomain: games and interactive apps\nMain stack: Unity, Unity Polyspatial, Unity Cloud, Swift, iOS\nDevices: Apple Vision Pro and other VR/XR headsets\n\nDuties & Responsibilities\n\n1. Core Development & Integration\n● Participate in full software development life cycle, from feasibility analysis to implementation and deployment.\n● Design, implement and maintain microservices.\n● Integrate third-party APIs and internal services in a secure and scalable way.\n● Contribute to the technical design and documentation of new solutions.\n● Troubleshoot system issues and identify opportunities for improvement.\n\n2. DevOps & Infrastructure\n● CI/CD Pipeline Management: Develop, implement, and maintain continuous integration/continuous deployment (CI/CD) pipelines to automate build, test, and deployment processes.\n● Infrastructure as Code: Utilize Infrastructure as Code (IaC) practices to manage, provision, and scale production environments efficiently.\n● Containerization & Orchestration: Oversee container orchestration (e.g., Docker, Kubernetes) to ensure reliable deployment and scaling of microservices.\n● Performance Monitoring: Implement and manage monitoring and logging solutions to optimize system performance and ensure high availability. Familiar with logging and tracking solutions like SigNoz or Grafana.\n● Collaboration: Work closely with cross-functional teams to integrate DevOps best practices, streamline deployments, and improve operational resilience.\n\n3. IT Duties\n● Infrastructure & Support: Collaborate with IT teams to ensure the proper configuration, maintenance, and security of internal systems and networks.\n● System Troubleshooting: Provide support for hardware and software issues affecting development and production environments.\n● Compliance & Security: Ensure adherence to IT policies and security guidelines across server operations and data management.\n● Monitoring & Maintenance: Assist in the monitoring of system health, coordinating with IT support to minimize downtime.\n\nYour skills and experience\n\nQualifications & Skills\n● Programming Languages: Python, Go, C#, JavaScript, SQL, TypeScript, Unix Shell\n● Database Technologies: Experience with PostgreSQL, Redis. Experience with columnar database (Snowflake, Clickhouse) is a plus.\n● API Frameworks: Experience with REST & RPC API frameworks (e.g., FastAPI, Flask, Protocol Buffer)\n● Cloud Providers: AWS, Google Cloud\n● Containerization: Proficiency with Docker, Kubernetes\n● Development Practices: Test-driven development (TDD) and domain-driven design (DDD)\n● CI/CD & Tooling: Familiarity with Jenkins, GitHub Actions, or similar tools\n● Workflow: Experience with Agile development (e.g., Scrum, Kanban)\n● Self-driven and proactive mindset\n● Clear communication, especially in async and remote settings\n● Ability to balance technical quality with pragmatic delivery  \n\nNice To Have\n● Working experiences with Unity, C# are a strong plus.\n● Familiar with CI/CD shipping Android and IOS Applications from Unity\n\nWhy you\'ll love working here\n\nWhat we offer?\nWe don\'t just offer a job; we provide a career and experience platform for passionate individuals to grow and learn – and ultimately realize a personal vision. Working with us means being part of a dynamic team that encourages curiosity, continuous learning, and celebrates innovation. You\'ll have the chance to work on projects that matter, and your contributions will shape the future of our company and the industry as a whole.\nIf you\'re ready to embark on a thrilling journey where you won\'t just follow a job description but help define it, apply now!  \n\nWhy us?\n• Proven record: our team has a proven record of building great companies.\n• Contribute: excellent exposure and accountability as you help shape the future of our company.  \n• Scale with us: obtain unique experience as an early employee of a growing company.\n• Work with meaning & fun: your work will impact millions of users, positively.\n• Competitive compensation: we pay well.\n• Equity: be an owner in what you build, and share in the company’s success.\n\nEqual Employment\nWe believe in equal opportunities for everyone. We treat every applicant and employee fairly, regardless of race, color, religion, gender, sexual orientation, national origin, age, or disability. We value the unique background and experience each person brings to our team. Join us and be part of a workplace where everyone has a chance to shine.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà The Nexx, 32 Phạm Ngọc Thạch, Phường Võ Thị Sáu, Quận 3, Hồ Chí Minh, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(749, 380, 2, 'Technical Project Manager', 'We are seeking a highly capable Technical Project Manager to lead software and system integration projects, working with international clients across sectors including energy, IT, and enterprise solutions. You will be the communication bridge between clients and development teams (both onsite and offshore) and ensure high-quality, on-time delivery aligned with global standards.\n\nWHAT WILL YOU DO?\n\nLocation working: HCMC office (Phu Nhuan Dist.) or Japan (Tokyo)\nLead end-to-end project delivery including planning, execution, and reporting.\nAct as a liaison between international clients (especially in Japan, US, UK, Korea, Singapore) and offshore teams in Vietnam.\nManage and coordinate team members to ensure successful and timely delivery of high-quality software.\nFacilitate communication with stakeholders, discussing technical topics such as Java-based architectures, integration flows (API, data sync, messaging), and AWS cloud infrastructure.\nMonitor risks, manage issues, track progress, and ensure adherence to Agile/Scrum or Japanese PM methodologies.\nImprove system performance, user experience, and reporting efficiency.\nMentor and guide team members to support their technical and professional growth.\nProvide status updates and stakeholder presentations.\n\nYour skills and experience\n\nREQUIREMENT\n\nBachelor’s degree in Computer Science, Software Engineering, or related fields.\n5+ years of experience in project management or software development.\nStrong technical background with knowledge in: Java-based backend systems or System integration projects.\nExperience managing distributed/offshore development teams.\nFamiliarity with project tracking tools such as Jira or Redmine.\nExcellent organizational, leadership, and communication skills.\n\nLanguage Requirements (one of the following):\nEnglish: Proficient for communication with international clients\nJapanese: Business level or above (JLPT N2 or higher) for direct client interaction\n\nPreferred Qualifications:\nExperience with Cloud platforms such as AWS/Azure is a plus.\nScrum Master certification is a plus.\n\nWhy you\'ll love working here\n\nHealth insurance, social insurance and Premium Health Insurance package for you.\nCompetitive salary package with 13th monthly salary and a good long-term and performance bonus monthly and yearly.\n5 working days per week (Monday-Friday), to some extent flexible working hours.\nFree snacks and coffee every day.\nJoin the Soccer and Badminton Club.\nSupport onsite fee with two way airline tickets if customer requires.\nFriendly, professional and open working environment.\nOpportunities to gain hands-on experience in cutting-edge technologies.\nYou will become the key members of WATA as we WATA is growing faster and bigger now.\nGuaranteed permanent employment and career development.\nSkills up plan with Tech talk, soft skill talk, English club, working process training.\nCompany trip yearly.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Others', 'Full-time', '2025-10-07 20:59:18.149534'),
	(750, 514, 2, 'Frontend Developer (ReactJS, TypeScript, English)', 'At NFQ, we focus on Scaling Business—helping companies grow, optimize, and transform through technology and strategic consulting. With 800+ experts across 8 offices, we don’t just build software; we partner with businesses to solve complex challenges, drive efficiency, and unlock new growth opportunities.\nUnlike traditional outsourcing, our approach goes beyond executing tasks—we advise, challenge, and co-create solutions that enable businesses to scale effectively. Whether it’s expanding into new markets, streamlining operations, or driving digital transformation, we are committed to delivering impact that lasts.\n\nWhy NFQ?\n\n🔹 Fairness – We treat our colleagues, clients, shareholders, and the environment with integrity and respect.\n🔹 Entrepreneurship – We think like entrepreneurs, taking smart risks and turning ideas into real impact.\n🔹 Excellence – We go beyond expectations to deliver results that truly make a difference.\n\nWe’re looking for a Senior Frontend Engineer to join DataBus, Shopware’s new event-streaming middleware. Nexus, its visual drag-and-drop workflow designer, is the frontend where merchants can seamlessly connect Shopware to any third-party solution without writing code. Built on a working MVP with React 18, Vite, and Tailwind, your team’s mission will be to transform this prototype into a production-grade application for thousands of merchants.\n\nIn this role, you will:\n\n- Deep-dive the current client/ and other relevant parts of the codebase in the shopware/swag-nexus repository React Flow canvas, Zustand stores, RTKQuery, Playwright tests).\n- Fully understand Shopwareʼs App System and setup Nexus as a Shopware App, focusing on the frontend implementation Ship a hardening backlog: state isolation, performance budgets, accessibility & keyboard navigation, Skeleton loading patterns.\n- Pair with backend on SSE / WebSocket log-stream UX.\n- Replace ad-hoc components with the new Nexus design system (shadcn/ui + Tailwind) if needed. Own the workflow-canvas architecture: node palette, mini-map, reversible history, snaplines.\n- Implement credential & secret management UI with inline validation.\n- Introduce feature flags and remote config for staged roll-outs.\n- Drive E2E test coverage to 90 % of critical paths Playwright).\n\nYour skills and experience:\n\n- 5+ years professional Frontend experience with strong React + TypeScript in production.\n- Proven record shipping complex single-page apps (drag-and-drop, realtime data, or rich editors). Deep understanding of state-management patterns (selector memoisation, optimistic updates, cache invalidation). Performance and DX mindset: Web Vitals, bundle-splitting, dev-server tooling.\n- Accessible-first mentality WCAG 2.1 AA.\n- Familiarity with automated testing pyramid (unit > component > e2e) and CI gating.\n- Comfortable reading backend OpenAPI specs and modelling strong client typings.\n- Excellent English communication; ability to work 34 h overlap with CET.\n\nNice-to-haves:\n\n- Experience with visual programming frameworks (e.g., Blockly, Drawflow), Canvas/WebGL or workflow automation platforms (e.g., n8n, Zapier).\n- Awareness of event-driven architectures (Kafka, NATS, Redis Streams) and Go programming.\n- Knowledge of Shopware 6 plugin/app ecosystem or other e-commerce platforms.\n- Exposure to OpenTelemetry tracing or feature-flag platforms.\n\nWhy you\'ll love working here:\n\nPerks That Make a Difference:\n🏆 Join Vietnam’s Best IT Company – Recognized by ITViec for 7 consecutive years, including 2 successive years as the Winner. Work with some of the best minds in the industry and be part of a company that’s redefining how businesses scale through technology.\n🌍 Career Growth & Leadership Development – Work closely with NFQ’s leadership team, gain mentorship from experienced executives, and have direct exposure to high-level strategic decisions. Your growth is limitless, as long as you’re ready to step up, opportunities will always be there for you.\n💰 Competitive Compensation – We believe great talent deserves great rewards. Expect an attractive salary, performance-based bonuses, and a benefits package that reflects your impact. We value talent over salary budgets—exceptional contributions deserve exceptional rewards.\n✨ And Many More Benefits to Explore! But most importantly healthy work-life balance and an environment where you can thrive—professionally and personally. Including:\n- Laptop is provided.\n- Community Tech activities.\n- A fun & dynamic environment and freedom to be creative.\n- Modern office with a flexible relaxing zone.\n- 13th-month salary pro-rata (based on business situation/performance).\n- Performance review 2 times/ year.\n- Extra Premium Healthcare & Annual Health-check.\n- 15 days annual leaves.\n\nWorking time: Monday – Friday (9AM - 6PM)\nLocations: NFQ welcomes you to our offices in Vietnam (Ho Chi Minh, Da Nang, Hanoi, Can Tho), choose the location that suits you best and join us on a journey of innovation and excellence.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(751, 254, 2, 'Frontend Developer – ReactJS', 'Are you a passionate front-end developer looking to contribute to the development of enterprise-class applications that drive planning and revenue growth. Our ideal candidate will be demonstrably skilled, have strong, hands-on experience with React and Redux to develop enterprise applications. The candidate will play a critical role in application design and development.\n\nResponsibilities:\n- Develop and maintain scalable ReactJS solutions.\n- Collaborate with team and stakeholders to analyze requirements.\n- Write clean, testable, and efficient front-end code, adhering to best practices.\n- Ensure application is rendered consistently with UI/UX near pixel-perfect.\n- Manage routings and integrate RESTful APIs.\n- Optimize front-end solutions and seamlessly integrate.\n- Write unit and integration tests to ensure functionality and reliability.\n- Troubleshoot and debug applications to resolve technical issues.\n- Conduct code reviews and provide constructive feedback to team members.\n- Create clear and concise documentation (docs-as-code) for code, routings, and APIs.\n- Ensure application security and compliance with industry and regional standards.\n- Stay updated with the latest technologies and tools in ReactJS development and apply them to improve existing solution.\n\nYour skills and experience:\n- Excellent development skills required. Excellent communication skills required. Solid mathematics skills required. Intermediate English skills required.\n\nQualifications:\n- Bachelor’s degree in computer science, software engineering, or related field.\n- Three or more years of experience in ReactJS development.\n- Solid experience with design patterns, developing from architecture and design documents.\n- Proven expertise with front-end technologies React, Typescript and related libraries.\n- Strong experience with CSS & UI libraries including Tailwind and MaterialUI.\n- Experience with Next.js, Node.js, Express.js.\n- Experience with dynamic rendering, CSR and SSR.\n- Solid experience with Zustand, Redux and Redux Toolkit.\n- Strong experience with performance optimization techniques.\n- Proven experience with Web Services, RESTful APIs and best practices.\n- Experience with IntelliJ and GIT or similar versioning tools and coding standards.\n- Excellent attention to detail.\n- Strong analytical and problem-solving skills.\n- Excellent communication and teamwork abilities.\n- Experience collaborating with business, engineering, operational, and product stakeholders, spanning business requirements, functional specifications, and test plans.\n- Maintaining a constant focus on the applications delivering client value.\n\nPreferred:\n- Knowledge of Python or Java.\n- Knowledge of SQL and database.\n- Knowledge of cloud services like AWS or Azure.\n- Previous experience working in a Startup environment.\n- Previous experience working in an Agile/Scrum environment.\n\nWhy you\'ll love working here:\n- Income negotiated according to experience and ability, with 13th month salary and bonus up to 15th month salary based on excellent performance and business results.\n- Loyalty program after second year, bonus up to 1 month salary based on product launches.\n- Social insurance, health insurance and salary insurance after signing labor contract.\n- Startup culture, young, dynamic English-speaking work environment. You are a stakeholder.\n- Software engineering, building real product. Attention and commitment to real engineering.\n- Challenged to master with mentoring and coaching, from engineering to project management and presentation skills.\n- Sponsoring over achievers for technical certifications.\n- New equipment, professional development environments, in-house servers and hybrid cloud.\n- Empowered to experiment with opensource and Linux lab environments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '26 Thao Dien Street, Thao Dien, Thu Duc, HCMC, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(752, 393, 2, 'Software Engineer (Python, JavaScript, ERP)', 'Job description: \n- Technical Solution Design: Collaborate with analysts to design and implement technical solutions that meet client specifications.\n- Custom Module Development: Develop and integrate custom modules into the Odoo ERP system, ensuring seamless functionality.\n- API Integration: Design, develop, and integrate APIs to connect Odoo with third-party applications and external systems.\n- Data Orchestration: Implement and manage workflows for efficient data processing and automation between different systems.\n- Code Review and Quality Assurance: Conduct thorough code reviews to ensure stability, reliability, and optimal performance.\n- Issue Analysis and Debugging: Analyze and debug issues to maintain system integrity and performance.\n- Collaboration and Reporting: Work with developers and business users to gather data requirements, execute technical solutions, and prepare reports.\n- Mentorship: Train and mentor junior developers, fostering a culture of continuous learning and improvement.\nYour skills and experience: \n- Education Background: Advanced Diploma or Bachelor\'s Degree in Computer Science, Information Technology, Physics, or Engineering.\n- Professional Experience: Minimum of 5 years as a Software Engineer, preferably with experience with ERP systems.\n- Programming Proficiency: Strong experience in Python and Object-Oriented Programming; familiarity with JavaScript and mobile development is a plus.\n- API Development & Integration: Hands-on experience in designing and integrating RESTful, APIs, JSON, and web services.\n- Data Orchestration: Experience in managing automated data workflows and inter-system data synchronization.\n- Database Expertise: Proficient in SQL and NoSQL database systems; experience with MySQL, PostgresSQL, or Oracle is beneficial.\n- ETL & Data Processing: Understanding of data transformation and ETL principles; experience with data pipelines is a plus.\n- Version Control: Experience using GitLab and GitHub for source code management and collaboration.\n- CI/CD & Deployment: Familiarity with CI/CD pipelines using GitLab CI, Jenkins, or similar tools for automated testing and deployment is a plus.\n- Cloud & Messaging System: Knowledge of cloud solutions (AWS, GCP, Azure) and messaging queues (Celery, RabbitMQ) is advantageous.\n- Communication Skills: Strong verbal and written communication skills in English; proficiency in French is a plus.\n- Soft Skills: Strong analytical thinking, problem-solving abilities, and the ability to perform well under pressure.\nWhy you\'ll love working here: \n- Compensation & Perks: We offer an attractive salary package, including a performance-based bonus. Your hard work and successful projects directly translate into your rewards.\n- Team Building & Events: We believe in creating a diverse and inclusive workplace culture that supports the growth and well-being of our team members both professionally and personally.\n- Coaching & Mentoring: Our comprehensive coaching and mentoring program empowers our staff for future success. We provide coaching sessions with documentation and practices to accelerate learning, refine skills, and navigate challenges.\n- Flexible Working Hours: At Portcities, we understand that our team has diverse needs and responsibilities outside of work. We have flexible working hours, so you can better manage your schedule and find the optimal time for productivity.\n- Internal Transfer Opportunities: Portcities, with 12 branches worldwide, offers internal transfer opportunities, providing exposure to different regions and cultures and enhancing your career journey.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '10 Vinh Khanh Street, Ward 10, PLS Building (1st Floor), District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(753, 250, 2, '[Da Nang & Ho Chi Minh] Technical Architect', 'Top 3 reasons to join us\n\nINNOVATIVE, CREATIVE - Think outside of the box\nKEEP CHALLENGING - Never stay in your comfort zone\nCRITICAL THINKING\n\nJob description\nPRIMARY JOB RESPONSIBILITIES\n\nDevelopment Oversight: Lead the software development life cycle, ensuring project delivery aligns with organizational objectives.\nTechnical Solutions Design: Collaborate with stakeholders to design efficient software solutions and verify technical feasibility.\nArchitectural Guidance & Design: Define system architecture, establish coding standards, and ensure alignment with non-functional requirements.\nArchitectural Execution & Integration: Oversee software development, facilitate continuous integration/deployment, and maintain monitoring for system performance.\nArchitectural Validation & Quality Assurance: Conduct architecture evaluations, enforce continuous testing, and validate non-functional requirements.\nArchitectural Management: Develop project roadmaps, manage technical risks, maintain the technical backlog, and mentor team members.\n\nYour skills and experience\nPOSITION QUALIFICATIONS AND REQUIREMENT\n\nFull-stack Development Expertise: Extensive experience in both backend (Node.js/NestJS) and frontend (React/Next.js) development.\nCommunication: Fluency in English is required.\nExperience: 3-5 years of experience in a similar Technical Architect role.\nCloud Infrastructure: Advanced knowledge of cloud platforms (preferably Google Cloud), with expertise in Kubernetes, Service Mesh, and optimizing infrastructure for large-scale, secure, and resilient systems.\nApplication Architecture: Expertise in designing, evaluating, and validating modern software architectures such as Microservices, Domain-Driven Design (DDD), Clean Architecture.\nData Architecture: Expertise in designing and managing data models, with a strong focus on PostgreSQL, as well as other SQL/NoSQL databases, ensuring optimal performance and scalability.\nNon-Functional Requirements: Proven expertise in managing and optimizing system non-functional requirements, including performance, security, and scalability.\nTechnical Troubleshooting: Strong problem-solving skills for diagnosing and resolving technical and production incidents effectively.\nTechnical Communication: Excellent communication skills to convey complex technical concepts clearly to both technical and non-technical stakeholders.\n\nPERSONAL ATTRIBUTES:\nExperience in mentoring people\nCalm in finding resolutions for issues/problems\n\nWhy you\'ll love working here\nMore on OTSV – what is it like to work in OTSV?\nAt OTSV, work is a form of self-fulfillment, we encourage staff to leave their comfort zone, think out of the box, and share their ideas without hesitation.  As a team, we analyze and evaluate issues objectively to learn quickly from mistakes. We believe in ‘fail quick, success quick’ and strive to keep pace with the forefront of technology to digitize ONE’s business.\nIn line with the Agile methodology, we have an open office concept with lots of meeting areas for spontaneous team meetings.\nWe aim to make our staff feel as comfortable in the office as they would feel at home.\nYou will love working here!\n\n13th-month salary\nPerformance Bonus\nSocial Security co-contribution based on full gross salary\nPremium health care (Bao Viet Insurance) for employees & dependents (parents or spouse + children).\nLunch allowance\nFree drinks and snacks\n17 days of Annual Leave\nAnnual health screening reimbursement: VND4,700,000/year\nWell-being allowance: VND13,800,000 VND/year\nTraining and education sponsorship: 38,000,000/year  \n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà ETOWN 6 - 364 Cộng Hòa, Phường 13, Tan Binh, Ho Chi Minh, Tầng 3-4 tòa nhà Phi Long, 52 Nguyễn Văn Linh, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(754, 515, 2, 'DevOps (Linux, Java, Golang, JavaScript)', 'We are looking for a DevOps to be part of our expanding team. We are looking for people who share our passion and can help us achieve our goal. As a DevOp, your responsibilities will be:\n\n- Manage and operate application systems\n- Understand business processes and application functions\n- Test and ensure the quality, efficiency and safety of applications\n- Monitor and report on the operation, performance and traffic of applications.\n- Coordinate with application developers/application monitoring teams to build application dashboards/alerts\n- Receive 24/7 warning notifications from the application monitoring team, then verify and handle\n- Support analysis and send errors to the development team/supplier, coordinate with the development team/supplier to check and handle incidents as assigned.\n- Coordinate with relevant departments System Administration/DBA/ANTT/3rd Party to check and handle incidents as assigned\n- Perform installation, deployment, and update applications according to the documents of the development team/supplier\n- Perform system configurations according to approved requirements from management\n- Administer VMware virtual servers with Windows Server OS, Linux OS, PosgreSQL DB operating systems\n- Administration of Linux-based applications: Wazuh monitoring application, Jabbix, Voice Asterisk\n- Install and develop system administration applications, monitoring warnings, and network security.\n\nYour skills and experience:\n\n- University degree or higher in Information Technology, Software, Computer Engineering, Telecommunications Electronics\n- Have at least 2 years of experience in a similar position\n- Basic English reading and understanding\n- Good understanding of software development processes.\n- Good understanding of Microservices and Monolithic Services application models\n- Understanding and experience in Linux operating system administration\n- Experience in programming applications in Java, Golang, JS languages\n- Experience in managing applications on Docker and Container platforms is an advantage\n- Experience in business analysis is an advantage\n- Experience in deploying and managing CI/CD (Continuous Integration/Continuous Deployment) systems, including the use of tools such as Jenkins, GitLab CI/CD, or other similar tools.\n- Proficient in Git, good grasp of Git Flow\n- Proficient in software such as Ansible, Terraform, Jenkins, ArgoCD ...\n- Skills in writing scripts and automation to create automated processes for system deployment, configuration and management.\n- Have skills in managing and applying system monitoring methods and tools to ensure application performance and availability.\n- Have the ability to work collaboratively and communicate well with other members of the development, project management and system management team.\n- Have analytical thinking skills, problem solving, problem zoning to solve problems in a short time.\n- Have the ability to apply AI and new technology to work.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'BIDV Tower, 194 Tran Quang Khai, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(755, 492, 2, 'Fullstack Software Engineer (ReactJS, Flutter, Python)', 'Top 3 reasons to join us\n- Competitive salary and bonus\n- Young and innovative working environment\n- Work with the brightest minds\n\nJob description\n- Tham gia phát triển sản phẩm của công ty - domain fintech/securities, xây dựng dựa trên kiến trúc micro-services và vận hành trên nền tảng Kubernetes\n- Tham gia sâu vào quy trình phát triển sản phẩm, từ lên ý tưởng, làm rõ yêu cầu, thiết kế giải pháp công nghệ và phát triển tính năng. Phối hợp và tư vấn giải pháp công nghệ, cùng các thành viên khác thiết kế sản phẩm hợp lý, mang lại giá trị cao về business.\n- Code quality: chủ động và có trách nhiệm trong việc nâng cao chất lượng code thông qua automated testing / refactor tech debts / code reviews. Áp dụng các kỹ thuật best practice như DRY, KISS, etc. vào thực tế để có code base đẹp, dễ maintain và dễ tiếp cận với người mới. Tham gia review code của các thành viên khác / projects khác để hiểu rõ mọi hệ thống của công ty cũng như nâng cao tiêu chuẩn chất lượng code của cả team.\n- Chủ động nghiên cứu các công nghệ mới, sẵn sàng chia sẻ thông tin và kiến thức cho các thành viên khác cùng phát triển, và đưa các công nghệ mới vào ứng dụng tại các dự án của công ty.\n- Đóng góp ý kiến, cải thiện và nâng cao hiệu quả của quy trình phát triển phần mềm theo Agile và Scrum.\n\nYour skills and experience\n- Có kiến thức nền tảng tốt về khoa học máy tính và phát triển phần mềm.\n- Hiểu rõ các kiến thức cơ bản, nâng cao, best practices trong việc phát triển các ứng dụng cả server side và client side.\n- Nhiều hơn 2 năm kinh nghiệm phát triển phần mềm, có thể phát triển hoàn chỉnh một sản phầm từ việc viết API Restful, GraphQL... đến việc dựng giao diện người dùng phức tạp trên Mobile hoặc Web. Quen thuộc với stack công nghệ hiện tại tại công ty chúng tôi là một lợi thế : Reactjs, Flutter, Golang/Python.\n- Có kinh nghiệm với việc viết unit test, integration test, test driven development và chủ động thực hành những practice về test để đảm bảo sản phẩm trước khi bàn giao cho tester và xa hơn là user đã không còn có những lỗi hiển nhiên.\n- Kỹ năng giao tiếp tốt, có khả năng giải thích, trình bày kiến thức một cách rõ ràng, dễ hiểu.\n- Hiểu và ứng dụng được CI/CD.\n- Hiểu và ứng dụng được các principles trong thiết kế, phát triển phần mềm.\n- Điểm cộng: Kinh nghiệm làm việc với K8s là một lợi thế.\n\nWhy you\'ll love working here\n- Thu nhập cạnh tranh trong ngành + thưởng theo hiệu quả công việc\n- 12 ngày phép/năm, bảo hiểm sức khỏe PVI cá nhân và ưu đãi phí cho người thân.\n- Môi trường đồng nghiệp cởi mở, năng động, hỗ trợ đồng đội cùng phát triển, tập trung vào hiệu quả công việc, tối ưu phát triển công nghệ, tối ưu vận hành.\n- Được chịu trách nhiệm làm các tính năng quan trọng của sản phẩm (không phải dự án maintain). Thử thách với chuỗi sản phẩm có yêu cầu UX và tính thẩm mỹ cao.\n- Cơ hội phát triển sự nghiệp rõ ràng tại một trong các startup đang phát triển nhanh nhất VN (vốn hoá công ty hiện đạt 150 triệu $).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 tòa nhà Pax Sky số 63-65 Ngô Thì Nhậm, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(756, 516, 2, '(Senior) RPA Developer', 'Top 3 reasons to join us\n- Clear and progressive career path\n- Building large-scale products\n- Worldwide environment & work mobility\n\nJob description\nMain tasks and activities\n- Analyze business requirements to design and implement automation solutions that align with the architectural, security, and migration needs outlined in the document provided by the business.\n- Follow best practices for automation development across all tools and platforms used.\n- Collaborate closely with the team to deliver complete end-to-end automation projects, including bot development and deployment.\n- Apply the Software Development Life Cycle (SDLC) methodology throughout the project lifecycle.\n- Create and maintain documentation such as Process Design Documents (PDDs) and Solution Design Documents (SDDs), among others.\n- Participate in delivering automation demonstrations to stakeholders.\n- Continuously update and enhance technical skills through training and certifications in UiPath and Automation Anywhere.\n- Provide regular and accurate status updates to management and internal teams.\n- Conduct technical knowledge-sharing sessions within the team or upon request.\n- Serve as a backup resource for team members when needed to ensure project continuity.\n- Offer operational support to users, including troubleshooting, issue resolution, and implementing preventive measures beyond the core technical role.\n\nReporting line\n- Report directly to the Team Leader based in Ho Chi Minh.\n\nYour skills and experience\nEducational background\n- Graduate in Computer Science or a related field from a recognized technical university.\n\nTechnical skills\n- 3-5 years of hands-on experience in designing and delivering Robotic Process Automation (RPA) solutions, with proven work on UiPath and Automation Anywhere projects.\n- Experience working in a Microsoft environment (Office, SharePoint, Teams) and involvement in related developments.\n- Demonstrated experience across the full Software Development Life Cycle (SDLC).\n- Proficiency in troubleshooting application and system issues to ensure smooth automation functionality.\n- Strong analytical, conceptual, and problem-solving skills with extensive experience in analyzing and mapping business processes in service-based organizations.\n- Excellent verbal and written communication skills, with the ability to collaborate effectively across diverse teams and interact with stakeholders at all organizational levels.\n- A positive, proactive attitude and strong team player, contributing to a productive work environment.\n\nAdvantageous to have:\n- Experience with tools such as Power Automate, Python, Optical Character Recognition (OCR), and Intelligent Document Processing (IDP) is advantageous.\n- Experience in writing SQL queries.\n- Basic or advanced knowledge of programming languages such as C#, Java, or others.\n- Ability to work independently as well as in geographically distributed teams.\n- Familiarity with Microsoft Azure DevOps and Git is a plus.\n\nLanguage\n- Fluent in English, both written and spoken.\n- Proficiency in French is a plus.\n\nWhy you\'ll love working here\n- Being a pioneer in contributing to team development with a long-term vision.\n- High-ownership working environment: You will take full responsibility and control of your missions contributing to the team\'s success in a daily collaboration with Paris teams.\n- Continuous skill improvement with new technologies, challenging projects, on-the-job coaching, knowledge exchange with technical experts, and training programs (locally and in Paris).\n- Annual performance review: recognize your efforts and identify development/ improvement needs.\n- 13th-month Salary\n- Salary review every year + Performance bonuses\n- Be secure in your mind with employee care: private healthcare insurance package, medical check-ups, allowance support...\n- Lunch allowances and In house coffee bar\n- Well-equipped facility\n- Free parking\n- Great-place-to-work activities (company trips, sport clubs...): enhance teamwork spirit and facilitate your work-life balance.\n- Opportunity to participate in global events (Hackathon, Seminar, Innovation Factory...).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lầu 6, tòa nhà E-town 2, số 364 đường Cộng Hòa, phường 13, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(757, 517, 2, 'Backend Software Engineer (Python, Django)', 'About Koidra\nKoidra is at the forefront of climate tech innovation, offering intelligent automation solutions that enable high-tech greenhouses, biomass energy facilities, and food processing plants to excel in both sustainability and production efficiency. We are dedicated to helping these industries reduce their environmental impact while maximizing operational effectiveness.\nBy integrating advanced machine learning, IoT technologies, and principles from Math and Physics, our systems extend the precision and efficiency of operations beyond what\'s possible through human efforts alone. Koidra\'s smart automation empowers facilities to broaden their control, minimize reliance on manual expertise, and embrace a scalable approach to environmental responsibility in industrial automation.\nDiscover more about Koidra and our game-changing technology on our About Us page.\nKey responsibilities \n👉 Architect and develop stable web applications\n👉 Rapidly build, iterate, test and deploy new features and products\n👉 Analyze and improve efficiency, scalability, and stability of various system resources\n👉 Maintain and monitor a high-quality robust codebase\n👉 Manage and contribute to code and large scale projects from inception to completion \nTech Stack that we\'re using\n- Backend: Python , Django\n- Infrastructure: GCP , PostgreSQL , Gitlab (CI/CD)\nYour skills and experience\n🔗AT LEAST 3 years of industry experience in a back-end or full-stack engineering role\n🔗 Proficient understanding of Python or equivalent programming languages such as C#, Javascript, Golang\n🔗 Experience in API designing and implementation\n🔗 Experience in databases design, development and maintenance\n🔗 Experience in architecture design is a plus\n🔗 Experience working with systems dealing with time series data, real-time data processing, and data analytics is a plus\nWhy you\'ll love working here\n✅ Competitive Salary with annual performance reviews and potential for bonuses\n✅ Health & Wellness: Comprehensive health care \n✅ Flexible Work Arrangements: Choose from flexible working hours, remote working days, or hybrid working mode \n✅ Learning & Growth: Annual allowance for courses, certifications, and conferences. Monthly in-house tech talks \n✅ Tech Setup: Latest MacBook Pro or equivalent, dual monitors \n✅ Regular Team Bonding events: From monthly team gathering to annual offsite retreats \n✅ Daily Perks: Free lunches, unlimited snacks, and coffee \n✅ Diverse & Inclusive Environment: Be a part of a company that celebrates diversity and champions inclusivity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '8-10 Tạ Hiện, P. Thạnh Mỹ Lợi, TP. Thủ Đức, TP. HCM, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(758, 342, 2, 'Manual/Automation Tester - Quality Analyst (QA QC)', 'Top 3 reasons to join us\n• Extremely competitive salary.\n• Healthcare insurance package.\n• 13th month and productivity bonus.\n\nJob description\n• Design, develop, document, train, and execute complex software test cases used for the regression testing cycle\n• Functional testing of new features and regression testing of existing features and functionality for each new software release\n• Join meetings with Stakeholders\n• Collaborate with Dev teams (Vietnam, US, Europe) and Product Owners to evaluate and clarify product requirements and designs\n• Support the team to troubleshoot the issues\n• Testing on web application and window application\n• Log and report bugs\n• Working on Agile process\n• Work primarily on the MiTek Production application-integrated and simplified production system to help you accurately manage the production of components throughout your plant\n• Willing to support the other projects if need\n\nYour skills and experience\n• Experience in testing Web and/or window applications\n• Experience in test automation for Web, window applications, and API with any framework and programming language is a plus\n• Knowledge of Home Building processes or software a plus\n• English communication\n• Attention to detail\n• Strong desire to build a high-quality product\n• Good problem-solving, collaboration, and communication skills\n• Ability to work in a team\n• Knowledge of testing processes and techniques\n\nWhy you\'ll love working here\n• Extremely competitive salary.\n• 13th month & productivity Bonus.\n• Yearly salary review.\n• Healthcare insurance package.\n• 24/24 Personal accident insurance.\n• State-of-the-art office environment.\n• Yearly outing.\n• Detailed induction, training and on-going career development.\n• Opportunity for overseas training and travel.\n• English training programs.\n• 5-day week.\n• Flexible start-times.\n• Free lunch.\n• Free parking.\n• Full Social Club including gym, yoga, football, badminton, and swimming.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'A5 Building, E- Office Park, Road, Tân Thuận, Đ. Sáng Tạo, Tân Thuận Đông, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(759, 301, 2, 'Senior QC Engineer (Tester/QA QC) - Up to $1,000', 'Top 3 reasons to join us\n- Allowances on holidays and quarterly bonus\n- PTI insurance package\n- Open working environment with young people\n\nJob description\n- Create test cases based on project specifications (functional, application, and regression).\n- Executing Web application testing, Mobile testing, and API testing\n- Troubleshoot and assess test issues to determine failure points.\n- Provide estimates for testing task times and meeting durations.\n- Manage testing schedule.\n- Report and document bugs/issues in a clear, timely, and concise manner.\n- Work closely with our development team to ensure delivery of quality implementations.\n- Escalate project issues to management when appropriate.\n- Identify potential project risks and provide recommendations to mitigate risks.\n- You will have chances to be transformed to an Automation Test Engineer in the future with assignments to develop a QC Test Automation Platform using one of the frameworks: Lavarel Dusk, Selenium, …\n\nYour skills and experience\n- MUST HAVE\n- 3 years more experience in testing web, app, mobile, …\n- Good experience in MANUAL testing for web-based and mobile (iOS, Android) applications\n- Clear understanding in software testing.\n- Prepare test plan, test cases and perform testing manually or automated.\n- Good problem-solving skills and teamwork skills.\n- Careful, meticulous, industrious, agile.\n- Proactive, creative, enthusiastic, responsible at work, have good logical thinking.\n- Ability to communicate to collect or clarify all project requirements.\n- Able to bear good pressure if the project requirements are urgent\n- Ability to quickly grasp new technology, new techniques\n- NICE TO HAVE\n- Good knowledge in Load/Performance testing, API testing, SQL database is a plus\n- English or Japanese: Reading document/ Communication\n- Positive thinking and have a progressive spirit\n\nWhy you\'ll love working here\n- BENEFITS WE HAVE:\n- Attractive salary\n- 13rd month salary and Quarterly bonus\n- PTI insurance package\n- Allowance for parking/birthday/holidays\n- Periodically teambuilding activities\n- Open working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '7th floor, Loyal building, 151 Võ Thị Sáu, phường Võ Thị Sáu, quận 3, TPHCM, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(760, 518, 2, '[Fresher] Lập Trình Viên - học bổng đào tạo', '[TTS/Fresher] Tuyển sinh chương trình học bổng đào tạo lập trình viên\nK-Tech College là chương trình đào tạo lập trình viên được tài trợ 100% bởi chính phủ Hàn Quốc, giúp cho các ứng viên ngành lập trình tiếp cận kiến thức và các công nghệ từ thực tế, văn hóa công sở và kỹ năng làm việc. Từ đó giúp cho ứng viên dễ dàng có được công việc phù hợp.\n\nThông tin chương trình:\nNội dung đào tạo: lập trình web, kỹ năng mềm\nĐối tượng: ứng viên năm 3/ năm 4, fresher.\nThời gian đào tạo: 3 tháng, Sáng từ 9:00 - 12:00, chiều từ 13:30 - 17:00\nMục đích: đào tạo nâng cao kỹ năng lập trình cho ứng viên chuyên ngành lập trình web tại VN.\n\nĐược hỗ trợ cơm trưa trong quá trình học\nĐược đào tạo miễn phí các kiến thức về lập trình và thực hành dự án thực tế\nCó cơ hội đi thực tế ngắn hạn tài Hàn Quốc\nHọc bổng cuối khóa dành cho học viên xuất sắc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '11F Cobi Tower 2, số 2-4 Đường Số 8, Tân Phú, Quận 7, Thành phố Hồ Chí Minh, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(761, 325, 2, 'Lead Fullstack  Engineer', 'About this role\nAs a Full Stack Engineer, you will develop the user interfaces for and manage the full lifecycles of AI/ML application experiences.\n\nAbout our team\nOur global AI, Data & Analytics Division at Renesas is experiencing an increasing demand for AI and Generative AI (LLM) based solutions. Working closely with our business partners, we deliver AI solutions to help drive value for Renesas at a global enterprise scale. We are seeking passionate candidates that will thrive as part of a global team of technologists that love empowering customers, collaborating with teammates, and using the latest AI and Data technologies.\n\nResponsibilities\n- Build and enhance user interfaces and experiences for AI solutions, including front-end and back-end systems and deploying complete applications.\n- Develop and maintain full stack AI/ML applications using Databricks tools and frameworks.\n- Collaborate with data scientists and AI/ML engineers, and domain experts on cross-functional projects using Databricks Workspaces.\n- Keep up to date with the latest developments and trends in AI/ML applications and Databricks technologies.\n\nYour skills and experience\nMust Have\n- Bachelor\'s degree or higher in computer science, engineering, or a related field.\n- 10+ years of professional experience in the tech industry.\n- Strong management skills, including team leadership and cross-functional coordination.\n- Proficiency in JIRA, Confluence, and related project management tools.\n- Expertise in system/solution architecture design, with solid knowledge of cloud platforms (e.g., AWS, Azure, GCP).\n- Ability to create and communicate technical designs using tools like Draw.io.\n- Fluent English communication skills, both written and verbal.\n- Experience working with AI team members, or a strong motivation to learn and collaborate in AI-related projects.\n\nNice-to-Have Skills:\n- Knowledge of DevOps practices and tools.\n- Experience with frontend development using React.\n- Familiarity with backend technologies, including Python, MongoDB, and PostgreSQL.\n\nWhy you\'ll love working here\nRenesas Design Vietnam Company Limited aims to provide our employees with comprehensive compensation and benefit plans, and a professional working environment. Some featured benefits are:\n- Competitive salary/bonus based on working performance.\n- Excellent training program.\n- Opportunity for promotion.\n- Fair assessment.\n- 24/24 hour insurance package including social and medical and unemployed insurance.\n- Dynamic people.\n- Team-oriented environment.\n- Sport activities and Annual company trip.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '31 Tan Thuan, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(762, 519, 2, 'Fresher-Middle QA/ Tester', 'Job description\n- Phân tích yêu cầu và thiết kế các test case hiệu quả, bao phủ toàn diện các chức năng của phần mềm.\n- Thực hiện kiểm thử thủ công (Manual Testing) cho các ứng dụng web và mobile.\n- Báo cáo lỗi chi tiết, chính xác, kèm theo các bước tái tạo lỗi (bug report).\n- Theo dõi quá trình sửa lỗi và kiểm tra lại sau khi lỗi được khắc phục (regression testing).\n- Tham gia vào các cuộc họp nhóm, thảo luận về kế hoạch kiểm thử và kết quả kiểm thử.\n- Hỗ trợ đội ngũ phát triển trong việc đảm bảo chất lượng sản phẩm.\n- Đề xuất các giải pháp cải tiến quy trình kiểm thử để nâng cao hiệu quả công việc.\n\nYour skills and experience\n- Có từ 1 năm kinh nghiệm trong lĩnh vực kiểm thử phần mềm.\n- Hiểu biết về các phương pháp kiểm thử phần mềm (black-box testing, white-box testing, ...).\n- Thành thạo các kỹ thuật viết test case, test plan, test report.\n- Có kinh nghiệm sử dụng các công cụ quản lý lỗi như Jira, Bugzilla (hoặc các công cụ tương tự).\n- Khả năng phân tích, tư duy logic tốt, cẩn thận, tỉ mỉ.\n- Kỹ năng giao tiếp tốt, làm việc nhóm hiệu quả.\n- Có khả năng làm việc độc lập và chịu được áp lực công việc.\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành liên quan.\n\nWhy you\'ll love working here\n- Mức lương cạnh tranh, phù hợp với năng lực và kinh nghiệm.\n- Thưởng hiệu quả công việc, thưởng các ngày lễ, tết theo quy định của công ty.\n- Được đóng bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật lao động.\n- Môi trường làm việc năng động, chuyên nghiệp, thân thiện.\n- Cơ hội được đào tạo và phát triển nghề nghiệp.\n- Tham gia các hoạt động team building, du lịch hàng năm.\n- Team building, Du lịch hàng năm, Thưởng hiệu quả làm việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2, tòa nhà văn phòng HL Tower, số 6 ngõ 82 phố Duy Tân, Phường Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(763, 483, 2, 'Backend Developer (Python, AWS)', 'We will entrust you with the application development work of our marketing DX support service, such as an advertising effectiveness measurement platform with the largest market share in the industry.\n\n[In particular]\n- You will be mainly in charge of the overall development from requirement definition to release in the project, such as new functions and performance improvement.\n- You will be engaged in a wide range of development, such as the back-end part for acquiring/analyzing a large amount of measurement data and the front-end part with various functions for marketing business support.\n- As a leader, you will manage the tasks of the members as well as team building, including member development.\n\nKey responsibilities and accountabilities include (but not limited to):\n- Understanding of requirements\n- Technical survey of new functions (PoC)\n- Application design\n- Implementation of application and implementation of UT\n- Code review\n- Document creation\n\n■ Necessary:\n- More than 3～5 years of Python Backend Development\n- More than 1～3 years of System or Application Design & Analysis\n- Have Experience the AWS platform.\n- Database or Caching Skills (at least 3 years): such as MS SQL, PostgreSQL, MongoDB, Redis, ElasticSearch, RabbitMQ\n- Quick Catch-up on System Structure\n- Experience in Code Design\n- Experience in Unit Test Specification Creation\n- Team Work Skills, Logical Explanations and Presentations\n- Experience in Functional and Non-Functional Requirements Definition\n- Technical Follow-up and Training for Development Members\n- Design and Promotion of Technical Training Policy Together with CTO\n- Joining Date from May 2025\n\n■ Plus Point:\n- Graduated from IT major is Desirable\n- Japanese Skill\n- Have Experience or Desire to Develop in: REST API, Docker, HTML5, NodeJS, ReactJS, Java\n- Have Practical Experience in Using GenAI tools to Support Programming, Documentation, Testing, or System design (Clear Understanding of the Security and Ethical Risks associated with using GenAI in a Corporate Environment.)\n- Strong Knowledge and Good Experiences in Scaling a Production System to Serve up to Thousands of Transactions per Second (tps)\n\nWhy Work at Yrglm Vietnam?\n- You can be involved in the design/development of an analysis platform that handles tens of billions of transaction data annually.\n- You can develop a system while acquiring marketing business knowledge.\n- In order to follow the latest browser trends and respond at the fastest speed in the industry, engineers can take the initiative in developing new specifications and functions.\n- Because we are promoting cloud computing from on-premise, we can be involved in development and migration that fully utilizes the advantages of cloud computing such as serverless architecture.\n- By collaborating with the planning department, you can get involved from the stage of studying the realization specifications.\n- In the future, regardless of your own team or other teams, you will be involved in the training of engineers from new graduates/mid-career recruitment.\n- In the future, you may be involved in product development in the new business start-up phase.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '308 Robot Tower, Dien Bien Phu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(764, 290, 2, 'Business Analyst (ERP)', '1. Thu thập và phân tích yêu cầu: \n• Làm việc với các phòng ban (Tài chính, Kế toán, Mua hàng, Kho, Bán hàng, Sản xuất...) để thu thập yêu cầu nghiệp vụ.\n• Phân tích và chuẩn hóa yêu cầu, chuyển hóa thành tài liệu nghiệp vụ (URD).\n2. Thiết kế giải pháp và tài liệu hoá:\n• Phối hợp với các bên liên quan để đề xuất giải pháp phù hợp\n• Viết tài liệu đặc tả chức năng (SRS), thiết kế giao diện (Mockup), hỗ trợ thiết kế giải pháp tích hợp (nếu cần)\n3. Triển khai dự án\n• Phối hợp với đội dự án trong giai đoạn phát triển\n• Tham gia kiểm thử chấp thuận người dùng (UAT), đảm bảo chức năng hoạt động đúng với yêu cầu nghiệp vụ\n• Tổ chức đào tạo, hướng dẫn sử dụng cho người dùng cuối và xử lý sự cố khi vấn đề xảy ra\n• Tiếp nhận, quản lý các yêu cầu thay đổi từ khách hàng\n4. Một số công việc khác từ BGĐ (nếu có phát sinh).\n\nYour skills and experience:\n- Có kinh nghiệm > 3 năm triển khai ERP;\n- Kỹ năng giao tiếp tốt, có thể thuyết phục và xây dựng mối quan hệ;\n- Tính cách năng động, tự tin và luôn muốn khám phá cơ hội mới;\n- Tốt nghiệp chuyên ngành CNTT, Toán Tin, Viễn thông; ... \n- Chủ động trong công việc, cam kết đảm bảo tiến độ đã đề ra;\n- Có khả năng thu thập, phân tích, tổng hợp thông tin, viết tài liệu;\n- Có tư duy logic, kỹ năng phân tích và giải quyết vấn đề tốt, giao tiếp & trình bày vấn đề tốt;\n- Tỉ mỉ, năng động, linh hoạt, có khả năng chịu được áp lực cao trong công việc;\n- Có khả năng đọc hiểu các tài liệu kỹ thuật bằng tiếng Anh.\n\nWhy you\'ll love working here:\n- Lương: 14tr-35tr tùy năng lực và kinh nghiệm làm việc  \n- Review lương 1 năm 1 lần;\n- Được làm việc trong môi trường công nghệ chuyên nghiệp, năng động, thử thách và nâng cao trình độ bản thân;\n- Được tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn.\n- Được cấp đồng phục, hỗ trợ ăn trưa, gửi xe tại công ty;\n- Được đóng BHXH, BHYT, BHTN, phép năm;\n- Gói khám sức khỏe định kỳ hàng năm, thưởng Lễ Tết, 30/04, 01/05, 2/9 …\n- Tham gia các hoạt động team-building, happy time, sinh nhật thành viên, đá bóng, du lịch,...\n- Thời gian làm việc: từ Thứ 2 đến Thứ 6 và thứ 7 cách tuần, sáng từ 08h00 đến 12h00, chiều từ 13h30 đến 17h30;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, tòa nhà Hoàng Ngọc, Số 4 ngõ 82 Dịch Vọng Hậu Cầu Giấy, Phường Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(765, 520, 2, 'Senior Golang Developer', 'Top 3 reasons to join us\n- 1 trong 10 website có lượng truy cập lớn nhất\n- Môi trường năng động, trẻ, sáng tạo, gắn kết\n- Mức lương hấp dẫn và tăng dần theo năng lực\n\nJob description\n- Phát triển Backend cho các Website/ App của CellphoneS, Điện Thoại Vui (Golang)\n- Liên tục cập nhật kiến thức, nghiên cứu công nghệ mới để ứng dụng trong công việc và phát triển sản phẩm của Công ty.\n- Xác định và giảm thiểu rủi ro trong các yêu cầu của dự án\n- Nghiên cứu, đề xuất các tính năng mới (cũng như cải tiến / nâng cao) cho website/ App\n- Lập trình, thiết kế module chi tiết và tích hợp.\n- Tham gia tư vấn và xử lý các vấn đề lớn về kỹ thuật liên quan đến luồng và logic khi có sự cố phát sinh trong dự án.\n- Thời gian làm việc: 8h30 - 17h30 (Thứ 2 - Thứ 6), Nghỉ trưa 1h30\'. Sáng Thứ 7 WFH\n\nYour skills and experience\n- Có từ 4 năm kinh nghiệm Backend, trong đó có ít nhất 3 năm kinh nghiệm làm việc với Golang.\n- Kiến thức về OOP, Data structure, Design Patterns.\n- Kinh nghiệm làm việc với Database MySQL, PostgreSQL.\n- Kinh nghiệm làm việc với Microservices: K8S, Message Queue, Monitor.\n- Kỹ năng quản lý, tổ chức và phân tích, với khả năng giải quyết vấn đề.\n\nĐiểm cộng cực lớn nếu bạn:\n- Kinh nghiệm làm việc Elastic Search, PHP/Laravel, Python.\n- Kinh nghiệm với tối ưu hóa hiệu suất trang web.\n- Khả năng nghiên cứu, cung cấp trình bày, cung cấp bản demo của công nghệ mới.\n- Kinh nghiệm làm việc với Vuejs, Nuxtjs\n\nWhy you\'ll love working here\n1. Chế độ đãi ngộ\n- Mức thu nhập từ 25 triệu - 40 triệu/ tháng\n- Thăng tiến theo tăng trưởng công ty và khả năng chuyên môn.\n- Được hưởng đầy đủ chính sách theo quy định: BHXH, BHYT, các phúc lợi khác theo luật Lao động (Tham gia BHXH dựa trên mức LCB của vị trí)\n- Tham gia Gói Bảo hiểm nâng cao PTI\n- Thưởng cuối năm từ 1,5-3 tháng thu nhập\n- Review lương 1 năm 1-2 lần tuỳ năng lực.\n\n2. Đào tạo - Phát triển\n- Cơ hội làm việc với nhiều dự án quan trọng và thăng tiến sự nghiệp cùng với sự phát triển của Công ty\n- Được nghiên cứu, đào tạo và làm việc với các công nghệ / hệ thống tiên tiến\n- Được công ty tạo điều kiện và hỗ trợ khi tham gia các khóa đào tạo, phát triển năng lực.\n\n3. Môi trường làm việc\n- Làm việc và phát triển tại một trong những hệ thống thuộc top bán lẻ công nghệ\n- Làm việc với team trên 15 nhân sự giàu kinh nghiệm\n- Môi trường coi trọng năng lực và khả năng sáng tạo với nhiều dự án đa dạng\n- Tham gia nhiều hoạt động thiện nguyện cùng Công ty và các tổ chức thiện nguyện khác\n- Các hoạt động thể thao với nhiều CLB: CLB Bóng Đá, CLB Cầu Lông, CLB Chạy bộ….', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '350-352 Võ Văn Kiệt, Phường Cô Giang, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(766, 521, 2, 'Database Engineer Expert', 'Job Description:\nWe are seeking a Database Engineer Expert to join our dynamic team. The ideal candidate will possess extensive experience in database administration, and ETL processes. This role requires a proactive individual who can manage and optimize our database systems, design and implement ETL processes, and ensure data integrity and performance.\n\nKey Responsibilities:\nDatabase Architecture & Design: Design, develop, and maintain scalable database architectures, ensuring high performance, reliability, and availability.\nDatabase Administration: Manage, monitor, and optimize database performance, including regular tuning, backup/recovery strategies, and capacity planning.\nData Modeling: Work closely with software engineers to design and implement efficient database schemas for new and existing applications.\nQuery Optimization: Analyze and optimize complex SQL queries to ensure maximum efficiency and performance.\nDatabase Security: Implement and maintain security protocols, ensuring databases are secure against unauthorized access and vulnerabilities.\nAutomation: Develop and implement automation scripts and tools for database management, deployments, and monitoring.\nDatabase Migration: Lead and execute database migrations, upgrades, and consolidations, ensuring minimal downtime and data integrity.\nCollaboration: Work with cross-functional teams, including software developers, devops engineers, and business analysts, to support their database needs and ensure alignment with business objectives.\nDisaster Recovery: Develop and maintain disaster recovery plans, ensuring regular testing and validation of backup and restore processes.\nDocumentation: Create and maintain detailed database design documentation, best practices, and operational procedures.\n\nETL Development:\nDesign, develop, and optimize ETL processes to extract, transform, and load data from various sources into data warehouses.\nAnalysts to understand data requirements and translate them into robust ETL workflows.\nEnsure data integrity, quality, and consistency across different data sources and destinations.\nImplement best practices for ETL process design, development, and deployment.\n\nYour skills and experience\nEducation: \nBachelor of degree in Computer Science, Information Technology, or a related field.\nExperience:\n5+ years of hands-on experience in database development, administration, and architecture.\nExtensive experience with multiple database platforms such as PostgreSQL, MySQL, Oracle, SQL Server, and NoSQL databases.\nExpertise in database clustering, replication, sharding, and partitioning.\nProven experience in optimizing complex queries and resolving performance bottlenecks.\n\nSkills:\nStrong proficiency in SQL, PL/SQL, and scripting languages (e.g., Python, Bash).\nExpertise in database design principles, normalization, and indexing\nHands-on experience with cloud databases (AWS RDS, Azure SQL, Google Cloud SQL) is a plus.\nProficiency in database monitoring tools (e.g., Nagios, Zabbix, Prometheus, Grafana) and backup solutions.\nStrong understanding of database security practices, data encryption, and GDPR compliance.\nExcellent troubleshooting and problem-solving skills with a focus on root cause analysis.\n\nPreferred Skills:\nKnowledge of ETL tools (e.g., Apache Airflow) or willing to learn.\n\nWhy you\'ll love working here\nSee yourselves in a new light\nIn essence of joining our company, you will be given the scope to seize every opportunity and helped to acquire specific competencies you’ll need to succeed either you wish to go wide or go deep. Our company prides ourselves on our underpinned principle of nurturing people in not only HR policies but also in our culture. We value innovations and we need people to work on initiatives and carry on our business vision of operating excellence and market leadership.\nAlongside with these, we believe our staff members deserve a good working condition, so that in addition to social health insurance you will be accessible to health and accident insurance and will be eligible to join in team building every year. We also value your efforts; for this reason, we give you both financial and non-financial rewards such as: KPI bonus, Best Initiatives, Best performer or Best manager of the year, etc.\n\nCompany\'s Benefits\nFinancial support:\nProbation with full salary\nLunch allowance\nWedding support\nFamily funeral support\n13th month salary + KPIs bonus\nPerformance rewards and awards\nHealthcare Insurance\nEvents and activities:\nChristmas\nYear End party\nTeam Building\nFamily Day\nSport Day.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'REE Tower, 9 Doan Van Bo, Ward 12, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(767, 460, 2, 'Web/Mobile Tester (QA/QC, Junior/Middle - Leader)', 'Top 3 reasons to join us:\n1. Global product & excellent team\n2. Opportunity to work with Global customers\n3. Competitive and attractive salary\n\nJob description:\n1. Analyze user stories, use cases, and requirements for validity and feasibility.\n2. Design, develop, and execute comprehensive test plans and test cases.\n3. Perform all levels of testing, including Functional, Integration, System, and Regression.\n4. Collaborate closely with developers, product managers, and other stakeholders to clarify requirements and resolve issues.\n5. Provide clear test reports and feedback to the development team and manager.\n\nYour skills and experience:\n1. Bachelor\'s degree in Computer Science, Software Engineering, Information Systems, or a related field.\n2. At least 1 year of hands-on experience in software testing.\n3. Experience testing both Web and Mobile applications.\n4. Strong analytical and problem-solving skills.\n5. Ability to write test cases, discuss and report progress in English.\n6. Familiar with Jira or Redmine tools.\n\nNice to have:\n1. Experience with API testing and basic data analysis.\n2. Knowledge or hands-on experience with Automation Testing (e.g., Selenium, Appium, etc.).\n3. Experience in a team leader or mentorship role is a plus.\n\nWhy you\'ll love working here:\n1. Competitive and attractive salary based on candidate\'s ability.\n2. Year-end bonus: Salary of 13th month.\n3. Working days: Monday - Friday, 8 hours per day.\n4. Review salary annually.\n5. Social insurance, health insurance, unemployment insurance according to the provisions of law.\n6. Team-building every 3 months, Summer holiday.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tran Thai Tong, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(768, 317, 2, 'Testing Software Supervisor', 'Top 3 reasons to join us\n- Supportive, Productive & Fair Working Environment\n- Empowerment, Recognition and Rewards\n- Oversea Training Opportunitiy and Mobility Program\n\nJob description\nRESPONSIBILITIES:\n- Supervise the activities of design, validation and testing, being responsible for ensuring a detailed understanding of these needs and the submission of proper documentation;\n- Direct work assignments, scheduling, and reviews of work in progress. Handles personnel actions including performance reviews, salary recommendations, and coordination of training and development;\n- Provide the technical governance of the team and ensures its efficiency and the good communication with the other teams, external and internal\n- Promote the continuous improvement process within the product’s life cycle;\n- Participate in department budgeting activities as required\n\nJOB DETAILS AND SPECIFICATIONS\n- Supervise and lead a team of Software Test Engineers in planning, executing, and managing comprehensive testing strategies for software products.\n- Collaborate with cross-functional teams to define test requirements, test cases, and testing timelines.\n- Provide technical guidance and support to ensure the test team delivers high-quality and defect-free software.\n- Coordinate with development teams to understand project requirements and resolve testing-related issues.\n- Conduct and oversee various types of testing, including functional, regression, and performance testing.\n- Implement and maintain test automation following best practice and recommended frameworks from the global testing team to enhance testing efficiency and reuse.\n- Analyze test results and work towards continuous improvement of testing processes.\n- Stay informed about industry trends, testing tools, and best practices, encourage the team to be innovative and to foster new patent proposal.\n- Participate to the regular CMB meeting for reporting the evolution of the development and bug-fixing.\n- Help the director to define the budget and resources plan including selection of SW and HW tools needed for the work.\n- Prepare weekly reports for the direct director highlighting the major achievements, issues and risks related to the development.\n- Provide training for new resources added to the team and planning and monitoring activities to improve the team know-how.\n- Manage internal conflict and found appropriate solution.\n\nYour skills and experience\nTECHNICAL SKILLS:\n- Proven experience in software testing, with a focus on automatic identification products.\n- Proven Experience on testing Android products such as Smartphone, Tablets, POS, and Mobile products in general.\n- Strong knowledge of testing methodologies, tools such as Jazz, Robot Framework, Test Complete, and best practices.\n- Experience in test automation and scripting languages.\n- Familiarity with agile development methodologies and continuous integration practices.\n- Strong analytical and problem-solving skills.\n- Prior experience in managing complex projects from conception to delivery\n\nSOFT SKILLS:\n- Strong leadership skills with the ability to motivate and guide a technical team.\n- Excellent communication skills and the ability to work collaboratively in a cross-functional environment.\n- Eager of new technologies and innovation\n- Planning and time management\n\nREQUIREMENTS:\n- Education: Telecommunication Engineering, Computers Science and Electronic, or related major\n- Language: English (good command in both speaking, writing, reading, listening)\n- YoE: 8+ years of experience in Testing SW\n- Nice to have: ISTQB Foundation certificates, Agile Foundation certificates, API Testing specialist certificates\n\nWhy you\'ll love working here\nCAREER OPPORTUNITIES:\n- Live in a high-end technology R&D environment\n- Be proud to see your own developed products sold all over the world\n- Strong knowledge and skills improvement through practical training and technical experience\n- Career promotion with proven capabilities\n- Opportunity for overseas training (US, Europe, etc.)\n\nBENEFITS:\n- Working day: from Monday to Friday (08:00 AM- 4:30 PM), One Smart working day per week\n- Salary and Allowance: Competitive\n- Incentive, Reward and Bonus: Outstanding employee award with attractive bonus, semi-annual KPI reward, Long term incentive for key positions and Annual bonus\n- Company’s labor policy completely pursuant to Vietnam labor legislation: working conditions, social & health insurance paid based on gross salary.\n- Mobility: Global mobility program in US and/or Italy\n- Benefits: Free meals, transportation allowances, accident insurance 24x24, premium health care insurance including dependents; gifts for Vietnam national days, scholarship for children of employees\n- Exciting leisure: Sport activities, corporate parties, company trip once a year, monthly teambuilding', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Datalogic Vietnam LLC. F04, Lot I-4A, Saigon High Tech Park, Long Thanh My Ward, Thu Duc, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(769, 522, 2, 'Senior Frontend Developer (VueJS, ReactJS)', 'Top 3 reasons to join us\n- Professional working environment\n- Attractive benefit\n- Work and approach with latest/hot technologies\n\nJob description\nProject\'s information:\n- Develop a large scalable website to manage salon shops across Southeast Asia based on microservices architecture and Azure services.\n- Develop other management systems based on our core services.\n\nProject\'s tool & technologies:\n- Vue 2 & 3, VueX.\n- Webpack 4, Bootstrap 4, Web Socket.\n- DevOps CI/CD.\n- Agile, GitLab.\n- And other tools & technologies…\n\nAs a middle frontend developer, you will be responsible for:\n- Work closely with developers to integrate dynamic functions programmed into front-end functionalities.\n- Research new products and technologies.\n- Work with backend team to implement system features.\n- Work with QC team to debug issues.\n- Provide a clean & maintainable code.\n- Assist in performance enhancements and solve more complex problems with the guidance of seniors.\n\nIn addition to the responsibilities mentioned above, as a senior frontend developer, you will also be responsible for:\n- Analyze & enhance app\'s performance - monitor & improve based on metrics: load time, rendering time, memory usage, minimize API calls,…\n- Improve UI/UX: User-Centric Design is the main point.\n- Code Review & guide Juniors.\n- Skilled in researching and developing creative solutions such as AI tools...\n\nYour skills and experience\nMust Have:\n- At least 7 years of experience in Frontend development.\n- Strong critical thinking and problem-solving skills.\n- Ability to write well-structured, clean code.\n- Expert in JavaScript (ES6+), advanced CSS, and semantic HTML5.\n- Deep understanding of browser data transmission mechanisms and JavaScript concepts.\n- Familiarity with CSS preprocessors such as Sass or Less.\n- Understanding of UI/UX principles and the ability to implement responsive, user-friendly designs.\n- Experienced in Vue 2 & 3 and familiar with the common Vue ecosystem (Vue Router, Vuex, Pinia, Vite, etc.).\n- Knowledge of caching, lazy loading, push notifications, and web application performance analysis.\n- Ability to self-learn and adapt to new technologies quickly.\n- Intermediate English level (speaking and listening are not required).\n\nNice to Have:\n- Experience in optimizing existing user interface designs.\n- Experienced in optimizing page loading speed and improving system performance.\n\nWhy you\'ll love working here\nAs the Ahasoft\'s employee, you are entitled to have:\n- Attractive benefits.\n- A professional and friendly working environment.\n- Training to other positions (Backend, mobile).\n- Social Insurance is based on full salary.\nAnd many benefits as below:\n- 13th month salary.\n- Employee loyalty rewards.\n- Private Healthcare insurance.\n- Annual company trip (domestic/international).\n- Annual leave: 15 days per year.\n- Paid remained leaves.\n- English class support (2.000.000 VND/Month).\n- Support for motorcycle parking fee.\n- Technical and soft skills training.\n- Monthly team dinner (500.000 VND/Member/Month) and year-end party.\n- Employee of the Year gifts and lucky draw prizes at the year-end party.\n- Modern equipment such as coffee machines, ice makers.\n- Snack and beverage.\n- Watch movies at least twice a year.\n- Leisure activities: Mid-Autumn Festival, Christmas, Lunar New Year, etc.\n- Birthday, Mid-Autumn and Lunar New Year\'s gift (1.000.000 VND).\n- Full payment on probation time.\n- Leave entitlement during the probation period.\n- All allowances and benefits by Vietnam\'s Labor Law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'MIOS Building, 121 Hoang Hoa Tham Street, Ward 7, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(770, 334, 2, 'Senior PHP Developer - Up to 50M', '1. Job Description\nVoyager is seeking a Senior PHP Developer to join and lead our backend development team. This role involves building and maintaining high-performance, secure, and scalable web systems that integrate efficiently with the frontend and other systems. The ideal candidate will have hands-on experience with PHP (Laravel preferred), strong system thinking, and the ability to provide technical direction for the team.\n\n2. Responsibilities\n● Develop and optimize backend or full-stack systems based on project requirements.\n● Design system architecture that is sustainable, secure, maintainable, and scalable.\n● Review code, mentor, and support junior team members.\n● Propose technical solutions and suitable technologies for each project.\n● Collaborate with frontend, QA, and IT Comtor teams to ensure project quality and timelines.\n● Ensure adherence to software development processes and coding standards.\n● Report progress and assist in managing technical risks.\n● Participate in building internal development processes and technical standards.\n● Further details will be discussed during the interview.\n\nYour skills and experience\n● Bachelor\'s or college degree in Information Technology or a related field.\n● At least 5 years of experience in PHP development, with a preference for Laravel framework.\n● Proficient in PHP, MySQL/PostgreSQL, and RESTful APIs.\n● Strong understanding of OOP, MVC, and SOLID principles.\n● Experience with source control tools (Git), CI/CD, and Unit Testing.\n● Familiarity with Agile/Scrum development processes.\n● Strong system thinking, problem-solving skills, and a high sense of responsibility.\n● Preferred qualifications:\n○ Experience with Docker, Redis, and Microservices.\n○ Knowledge of or experience working with high-load systems.\n\nWhy you\'ll love working here\n● Salary up to 50 million VND or higher, negotiable based on capability.\n● Performance reviews 1–2 times per year with performance-based bonuses.\n● Full benefits package: 13th-month salary, social insurance, health insurance, and extended PVI health coverage.\n● 100% support for professional development courses (e.g., advanced PHP, Japanese language, etc.).\n● Work equipment provided: MacBook Pro or other devices as required.\n● Company culture activities: Birthday parties, team-building events, and regular internal activities.\n● Office amenities: Football, ping pong table, free coffee and snacks.\n● Career path:\n○ Promotion opportunities to Tech Lead/PM.\n○ Career development guidance and support every 6 months.\n○ Clearly defined personal and team goals.\n● Working hours: Monday to Friday, from 8:00 AM to 5:00 PM, with lunch break from 12:00 PM to 1:00 PM.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 02, SBI Building, Street 03, Quang Trung Software City, Tan Chanh Hiep Ward, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(771, 253, 2, '[Fresher/Experienced] C++ Game Developer', 'Top 3 reasons to join us\n\n- 13th Month salary, work 5 days a week\n- Annual Company Trip, Quarterly team building\n- Premium health insurance, Support sport clubs\n\nJob description\n\n- Development of a 3D online action game using Unreal Engine 5\n- Implementation of character skills\n- Implementation of game content\n\nYour skills and experience\nRequired Skills\n- Understanding and proficiency in the C++ programming language\n- Development experience using commercial engines like Unity or Unreal\n- Understanding the action game genre\n- Passion for creating fun games\n- A mindset that values teamwork and aims to grow together with colleagues\n\nPreferred Qualifications\n- Practical experience and leadership in commercial game development\n- Development experience using Unreal Engine\n- Mathematical understanding of 3D space (Translation, Rotation, Scaling, Matrix Transformation, etc.)\n\nNote:\n- Please send your resume in English.\n- It is a full-time job working in the office. (Part-time or remote work is not accepted)\n\nOur recruitment process:\n\n1. Application screening\n2. An offline test \n3. F2F Interview (Only 1 round)\n4. Job offer\n\nWhy you\'ll love working here\n\n- Chance to work on global projects with multicultural teams, world-class games.\n- Attractive salary and benefits.\n- Professional work environment.\n- Open culture where every employee is valued, treated fairly, and trusted.\n- 13th salary every year at least 1-month salary.\n- From 12 days Annual Leave\n- Government social, health, and unemployment insurance.\n- Lunch Allowance\n- Annual salary review based on employee performance and company success\n- Annual Company Trip, Year End Party\n- Events during Birthday, Full Moon Festival, other important holidays.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UOA Tower, 11th Floor, 06 Tan Trao Street, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(772, 523, 2, 'Leader/Mid/Senior Android Developer(Java/Kotlin)', 'We are seeking a skilled Android Developer to join our team. As a Android Developer, you will be responsible for designing, developing, and maintaining mobile/tablet applications. Your primary focus will be on delivering high-quality software that meets the needs of our clients and end-users.\n\nJob Description:\n- Joining a real Mobile project as a professional engineer\n- To develop and deliver codes for the Point Of Sale/Payment gateway projects in accordance with time, quality, and cost standards.\n- Help plan, architect, and lead development of a brand new mobile application project\n- Write clean, well-documented, and well-tested code using best practices for Android development\n- Provide team members with project status and details through GitHub and code reviews\n- Advise the team on best practices and industry trends to implement new technologies.\n\nYour skills and experience\n- Must Have\n  - At least 3+ years of native mobile app development in Android (Java/Kotlin).\n  - Solid understanding of the full mobile development.\n  - Understand at least one of these architectures: MVP, MVVM, Clean Architecture.\n  - Know some design patterns (singleton, factory, data repository...).\n  - Strong experience in building custom UI, Constraint Layout, and complex interfaces.\n  - Have experience working on memory leak, performance issue.\n  - Good logical thinking and problem solving.\n  - Willingness to update and learn new technologies.\n  - Experience with Git.\n  - Top-notch teamwork and excellent communication skills.\n- Nice To Have\n  - Familiarity with CI/CD pipelines\n  - Experience with iOS development is a big plus.\n\nWhy you\'ll love working here\n(Interview after Tet holiday)\n(Job onsite)\n- 13th-month bonus salary and project bonus, long-term bonus\n- Salary review once a year based on employee performance and contribution\n- Loyalty reward Program (Bonus for every 5 years, 7 years of service)\n- Opportunity to develop your career and access new IT technologies\n- Free coffee\n- Professional Development Opportunities (Pluralsight Account)\n- Team building every 4 months, company trip, Birthday\n- High-performance equipment, extra high definition screens for working\n- 12 days of annual leave\n- Swimming pool and basketball court\n- Employee-friendly working conditions, longstanding colleague\n- Other benefits as stated in Vietnamese Labor Law\n- Work Life Balance: 9:00 AM - 6:00 PM from Monday - Friday.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 17, Đường Số 6, Khu Dân Cư Trí Kiệt, Phường Phước Long B, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(773, 325, 2, 'Global Microsoft Endpoint Engineer', 'This role is part of a Global Endpoint computing team, responsible for development, standardization, and management of the company’s global PC and mobile device infrastructure.\n\nManage and maintain a global co-managed Intune and Configuration Manager environment with of over 25,000 endpoints.\nDevelop and perform software deployments and operating system configuration changes using various software development & automation techniques.\nProvide direct 3rd line end user support for escalated PC and mobile device issues and needs.\nWork with vendors as needed to resolve application or end user issues.\nIdentify improvements in existing functionality and recommend enhancements.\nManage and deliver project activities as part of the overall roadmap.\nBe able to investigate issues under tight time constraints and be able prioritize work accordingly.\nBe able to work with minimal supervision.\nWrite and maintain appropriate documentation.\n\nKey Performance Measures\nThe availability of the Microsoft Endpoint manager services to the business.\nDelivering project goals to the required standard and on time.\nResolving personally assigned incident tickets promptly to the expected standard.\n\nQualifications\nBachelor or Master degree with relevant background (e/g Information Systems), or similar Proven track record of successful projects in the area of Microsoft Endpoint management.\n5 years’ experience supporting Windows client OS with minimum of 2 years supporting Windows 10/ 11.\n5 years’ experience developing, implementing, and administrating Microsoft Configuration Manager / MECM and Intune.\nGood understanding of where endpoint management fits into wider IT and reliant \\ dependent technologies (AD, GPO, Entra, Networking etc…).\nEndpoint management Certified preferred.\nProficiency in PowerShell scripting.\nProblem solving skills coupled with a strong customer focus.\nExcellent communication both written and verbal.\n\nWhy you\'ll love working here\nRenesas Design Vietnam Company Limited aims to provide our employees with comprehensive compensation and benefit plans, and a professional working environment. Some featured benefits are: \n- Competitive salary/bonus based on working performance.\n- Excellent training program.\n- Opportunity for promotion.\n- Fair assessment.\n- 24/24 hour insurance package including social and medical and unemployed insurance. \n- Dynamic people.\n- Team-oriented environment.\n- Sport activities and Annual company trip.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '31 Tan Thuan, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(774, 524, 2, 'Senior Java Backend Developer (Spring)', 'Senior Java Backend Developer: Has responsibility for implementation of assigned tasks in making the plan, design, development, technical support related to software development under the project member role.  Design, develop, and maintain scalable and high-performance backend systems using Java (Spring Boot, Spring Cloud).  Develop and optimize RESTful APIs and microservices architecture.  Implement security and data protection best practices.  Work with relational (MySQL, PostgreSQL) and NoSQL (MongoDB, Redis) databases.  Optimize application performance, ensuring reliability and scalability.  Collaborate with frontend developers, DevOps engineers, and product managers to deliver high-quality software solutions.  Write clean, efficient, and well-documented code following best practices.  Conduct unit and integration testing to ensure software quality.  Participate in Agile development, including sprint planning, stand-up meetings, and retrospectives.  Have at least 5 years of experience in JAVA (Highly preferred)  Have experience developing web applications  Have Java programming experience  Developed based on Spring, Spring Boot F/W, Spring MVC...  API Development (REST API)  RDBMS (MySQL, PostgreSQL, Oracle) & SQL, PL/SQL  Have knowledge Python language  Git, Jira, Confluence  Understand and apply CI/CD  Good at communicate in English  Be proactive and responsible at work.  [Nice-to-have]  Experience working in Kubernetes and Cloud environments (AWS, GCP)  Experience in SQL optimization  Why you\'ll love working here  Salary : Negotiable  Consideration for salary increase: Once per year  Social insurance paid according to regulations.  Company\'s own insurance.  Bonus on Tet holidays and other major holidays of the year.  Company vacation once per year.  There is a 13th salary month and bonus according to the year\'s contribution.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phòng 17-18, Nhà 8, Đường số 13, CVPM Quang Trung, Phường Tân Chánh Hiệp, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(775, 319, 2, 'Java Developer (Da Nang, HCMC)', 'Top 3 reasons to join us\n- Attractive package\n- Hybrid working policy & flexible hours\n- Europe onsite opportunities\n\nJob description\n- Work with international customers and colleagues from Germany, France, the Czech Republic, and the US\n- Independent conception and implementation of new functions in complex application landscapes\n- Coding in the frontend and backend, mainly with Java and JavaScript\n- Creation of technical documentation\n\nThis job is open to both Vietnamese citizens and foreigners living in Vietnam.\nPlease send us your application in English.\n\nYour skills and experience\n- General qualifications\n- Strong English communication skills (both verbal & written)\n- 2+ years of professional experience in international software projects (flexible depending on how fast your learning and technical developing capabilities are)\n- Degree in engineering or natural sciences (university or technical college)\n- Technical skills\n- Must have\n- Understanding of software development tools, processes, and architecture\n- Experience with multi-tier or service-oriented web applications\n- Experience with Java/Kotlin and J2EE frameworks such as Spring\n- Experience with relational databases, SQL, and ORM technologies\n- Nice to have\n- Experience in agile software development\n- Experience in build tools: Gradle, Maven\n- Experience in search engines such as Lucence, Solr, Elasticsearch\n- Experience with testing practices and tools (JUnit, Mockito...)\n- Experience in microservices architect\n- Proficient understanding of code versioning tools (Git is preferred)\n- Soft skills\n- Sense of responsibility, communication skills, and team spirit\n- Willingness to learn and build a deep understanding\n- Be able to work independently and under pressure\n- A passion for software development, new trends, and technologies in IT\n\nWhy you\'ll love working here\n- Good salary and a bonus if things work well\n- Working & growing with an international team\n- Onsite opportunities: short-term and long-term assignments in Europe\n- 18 days off allowance per year\n- Premium insurance for for you and your family member (spouse/ parent/ children) & yearly check-up\n- Loyalty program after three years and five years\n- Flexible working time (40h/week) with hybrid working policy\n- Highly professional equipment (Mac/Thinkpad, 2 screens, adjustable desks)\n- Intense English course for the first 3 months by our native English teachers and optional English seminars during the working time\n- Training sponsored by mgm\n- An amazing company trip once a year, team-building with the project team and month-end with the whole company, covered by mgm.\n- Free in-house entertainment facilities (darts, piano, climbing wall), drinks (coffee, beer, soft drinks,…) and food (cookies, fruit,…) and out-house company-funded sport clubs (football, swimming, badminton...)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(776, 525, 2, 'Project Manager  (Java, Chinese, English)', '1. Serve as a project staff member of the IT team, responsible for technology, management, and coordination of internal development projects\n2. Analyze and organize the requirements of each task, and control project time\n3. Matters assigned by supervisor\n\nRequired conditions:\n1. More than 1 year of operational project management experience\n2. Possess a bachelor’s degree or above in asset management or payroll related fields\n3. Those who have worked in the IT team are preferred\n4. Ability to speak Chinese and be able to communicate and coordinate\n\nPriority conditions:\n1. Have English skills and be able to communicate, coordinate and read English API documents\n2. Have experience in program development, preferably Java\n3. Familiar with SQL and MySQL syntax\n\nWhy you\'ll love working here\n- Flexible working time\n- Opportunity to study and work with foreign experts.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '459 Sư Vạn Hạnh, Phường 12, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(777, 526, 2, 'Technical Lead (Ruby/Java/Python/PHP)', 'By reinventing the old industry with new technology’s power, RAKSUL is delivering satisfaction and happiness to customers every day with global offices in Japan, Vietnam, and India. We have developed various products based on e-commerce platforms, whether they are incubation, growth-phase products, or long-term core business products.\nWe are looking for comrades to create great products in HCMC office together!\n\nMain technology:\n- Ruby on Rails for backend\n- Vue.js, Typescript for frontend\n- AWS (EC2, ECS) for infrastructure\n\nResponsibilities:\nYour mission is to ensure a top-tier service level for our system and develop a technical strategy that enhances business outcomes and streamlines the operation of our e-commerce platform. You will work closely with Product Managers, Business Development, and Customer Support teams.\n\nLeveraging your solid cooperation skills with various stakeholders and identifying product specifications for an optimal customer experience, you will design system interfaces and databases. This will enable your team\'s software engineers to deliver top-tier performance and ensure consistent operations.\n\n- Provide technical solutions and prioritize tasks in alignment with the business and product roadmaps.\n- Respond promptly to inquiries from customer support and address troubleshooting needs.\n- Design interfaces and databases to support new platform integrations.\n- Ensure Service Level Objectives (SLO) for product quality, high availability, and high throughput\n- Implement and review code with your team members.\n- Offer guidance and mentoring to junior and new team members.\n- Foster strong relationships with all project stakeholders.\n\nYour skills and experience\nBasic Qualification\n- Experience in operating and re-architecting systems operated more than 5 years.\n- Confident with Ruby/PHP/Python/Java or what other languages but willing to deal with Ruby. \n- Highly productive coding and designing unit testing skill with Linux and web-based application’s frameworks (fluent in at least two of the following: Ruby on Rails, NestJS, Laravel, CakePHP, Django, etc.)\n- Hand-on experience with designing and tuning complex relational databases such as MySQL, PostgreSQL.\n- Experience with improving legacy code/system and working with REST API, and GraphQL.\n- Experience with designing and implementing asynchronous processes using event streaming services such as Kafka.\n- Familiar with cloud computing such as AWS, GCP\n\nOther skills\n- Decent communication English skill to work with global members.\n- Strong documentation skill utilizing tools such as Notion, Clickup, Github Wiki, etc.\n- Pair programming and/or mob programming.\n- Ability to work with others and preference on teamwork.\n- Strong interest to change old industries with technology.\n\nWhy you\'ll love working here\n- 15 annual days of a year, and also available during probation time\n- Premium Private healthcare package\n- Salary review TWICE a year with attractive performance bonus up to 2 months\n- MacBook Pro, Ergonomic chairs, 140cm wide desk from your first working day\n- Individually tailored learning and development plan\n- Boost your English with in-house training by a native teacher\n- Maintain work-life balance with in-house activities, sports clubs, and regular events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '34th Floor, Lim Tower 1, 9-11 Ton Duc Thang, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(778, 206, 2, 'Senior System Administrator (Shift Work)', 'Top 3 reasons to join us\n1. Attractive remuneration package with 18 days off\n2. Smart people, interesting project & swiss quality\n3. Travel opportunities to Switzerland\n\nJob description\nYour responsibilities\n- We are seeking a skilled System Administrator Specialist that will be part of our Corporate IT, VN team with deep expertise in Windows 11, Azure (including EntraID, Intune MDM & MAM, BitLocker, Autopilot), and client hardware management (Dell & HP).\n- You will play a critical role in the full lifecycle management of our global staff’s endpoint devices (+2,000 workplaces), including Windows 11, macOS, and mobile services. Your primary focus will be leveraging Microsoft Azure Intune to deploy, manage, and secure these devices while ensuring operational excellence and innovation in workstation services. You work with Level 2 Experts to develop strategies, standards, IT skill sets and infrastructure directions.\n- Your mission includes delivering professional and timely services in relation with all office IT-infrastructure.\n- Challenge our current solution and propose innovations\n\nYour skills and experience\nYour qualifications\n- 7+ years of IT experience, with at least 5 years in relevant technologies at L2/L3 support levels.\n- Proven expertise in Microsoft Intune for endpoint management, including OSD, application deployment, and security updates.\n- Strong knowledge of Windows 11, macOS, and mobile device management in a global environment. Also familiar of software/OS deployments, updates management, asset intelligence, and desired configuration management, as well as hands-on experience with tools like KACE and BitLocker infrastructure.\n- Hands-on experience with Active Directory, Group Policies, and antivirus console management.\n- Proficiency in PowerShell scripting for automation and task management.\n- The offer covers working Shift-time (Support Group wide in Swiss timezone).\n- Flexible shift with compensation to be discussed during the interview process.\n\nNice to have\n- Certifications such as Microsoft Certified Intune and Azure Administrator Associate or equivalent.\n- Excellent oral and written communication skills, with strong interpersonal and presentation abilities.\n- Ability to design efficient processes and work independently in a fast-paced environment.\n- Flexibility to adjust to changing requirements, schedules, and priorities.\n- Proven ability to mentor and provide technical guidance to team members.\n- Strong commitment to quality and process improvement using ITIL best practices.\n\nWhy you\'ll love working here\n- Professional European-based company\n- Attractive salary\n- Performance bonus of up to 4 months‘ salary\n- Opportunities for travel to Europe\n- Hybrid home/ office working model\n- Flexible working time\n- Structured training & development roadmap\n- Good work-life balance\n- Premium healthcare insurance\n- Loyalty programs\n- Well-being activities\n- Annual company trips and team-building events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CII Building, 152 Điên Biên Phủ, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(779, 238, 2, 'DevOps Engineer', 'Top 3 reasons to join us\n1. Mức lương cạnh tranh, hấp dẫn\n2. Môi trường làm việc chuyên nghiệp, thân thiện\n3. Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Xây dựng và tối ưu hóa quy trình DevOps/DevSecOps, áp dụng nguyên tắc tự động hóa trong việc triển khai các ứng dụng công nghệ thông tin.\n- Triển khai, vận hành quản trị các giải pháp/công cụ tự động hóa CICD/IaC, công nghệ Containerization/Kubernetes. (Gitlab, Jenkins, Nexus, Docker, ISTIO, Ansible, Rancher, ...)\n- Tham gia vào giai đoạn phát triển sản phẩm, thiết kế các thành phần phi chức năng đảm bảo an ninh và support trong quá trình vận hành (thiết kế hệ thống theo các chính sách, quy định đảm bảo an ninh, chuẩn hóa logging, tracing và thông tin monitoring ELK, Prometheus, Grafana, ...)\n- Phụ trách deploy, optimizing, monitoring, analysis sản phẩm dịch vụ.\n\nYour skills and experience\n1. Tốt nghiệp hệ chính quy các Trường Đại học các chuyên ngành đào tạo: Công nghệ thông tin, Toán tin, Điện tử Viễn thông...\n2. Vị trí mởi với ứng viên mới ra trường có đam mê đối với mảng DevOps\n3. Nắm được logic code, nắm được tiến trình của code\n4. Ưu tiên các ứng viên có:\n   + Kinh nghiệm làm việc thực tế DevOps/DevSecOps tại các công ty công nghệ hoặc IT cho các tổ chức tài chính là một lợi thế.\n   + Hiểu biết về quy trình phát triển phần mềm và quen thuộc với tư duy làm việc Agile.\n   + Kỹ năng phân tích tư duy logic xử lý vấn đề.\n   + Kiến thức 1 trong các loại database: Oracle, Sqlserver, PostgreSQL, Mongodb,…\n   + Kinh nghiệm xây dựng CI/CD Pipeline, sử dụng các công cụ Jenkins, Gitlab, Nexus, Harbor, Docker, Helm, Kubernetes, Prometheus, Grafana\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n   - Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…  \n   - Du lịch nghỉ dưỡng hàng năm\n   - Khám sức khỏe định kì\n   - Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n   - Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n- Cơ hội nghề nghiệp và phát triển bản thân:\n   - Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n   - Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n   - Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n   - Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n- Môi trường làm việc lý tưởng với:\n   - Những người cộng sự thân thiện và tài năng\n   - Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(780, 449, 2, 'Lập trình viên CP4BA, ABAP, HANA,CAMUDA, Reactjs, Java', 'Top 3 reasons to join us\n• Môi trường năng động và cơ hội thăng tiến\n• Chế độ lương thưởng hấp dẫn\n• Bảo hiểm sức khỏe cao cấp (bảo hiểm toàn diện)\n\nJob description\n1. 01 Nhân sự DEV: Phân tích/Phát triển/maintain… hệ thống Quản trị nguồn nhân lực - HCM của SAP. Cung cấp API tích hợp HCM với các hệ thống khác\n2. Tham gia phát triển các hệ thống ứng dụng quản lý, tự động hóa quy trình nghiệp vụ của ngân hàng như: Quy trình tín dụng, Quản trị nhân sự - HCM, phê duyệt lãi suất, Quản lý tỷ giá, quay số trúng thưởng, loyalty, sms, mobile…\n3. Phát triển các phần mềm trên nền tảng công nghệ: Java, React admin, Reactjs, AWS, treaming data, Spring Framework/J2EE/Web service/JMS,kafka/ Oracle/SQL server Database…… Được tiếp cận với các hệ thống lớn, các công nghệ mới…Và được hướng dẫn đào tạo nếu chưa có kinh nghiệm.\n4. Phối hợp các đơn vị khắc phục các vấn đề phát sinh của các hệ thống hiện tại nếu có.\nĐược tham gia các khóa đào tạo nội bộ và nâng cao của Khối CNTT/Ngân hàng để nắm bắt các công nghệ hiện đại, công nghệ mới…\n\nYour skills and experience\nTrình độ chuyên môn\n• Trình độ chuyên môn: Tốt nghiệp đại học/cao đẳng/trung cấp hoặc tương đương các chuyên ngành phù hợp như CNTT/Toán/Toán tin/Điện tử viễn thông hoặc các chuyên ngành có liên quan đến CNTT;\n• Trình độ ngoại ngữ: Tiếng Anh tốt là lợi thế, yêu cầu tối thiểu có thể đọc được tài liệu tiếng anh;\n\nKiến thức:\n• Có base cơ bản về lập trình\n• Ưu tiên ứng viên có kiến thức về phân tích thiết kế phần mềm, lập trình hướng đối tượng và kiến trúc ứng dụng\n• Ưu tiên ứng viên có kiến thức tốt về quản trị ứng dụng trên nhiều nền tảng công nghệ\n• Ưu tiên ứng viên có kiến thức về hệ thống thông tin Ngân Hàng\n• Được đào tạo, hướng dẫn trực tiếp nếu chưa có kinh nghiệm\n\nKinh nghiệm\n• Đã có kinh nghiệm lập trình một trong các ngôn ngữ ABAP của SAP, nền tảng CP4BA – ECM, BPM, ODM, Camuda, ReactJS/Spring Framework/ Java, J2EE/Web service/JMS,kafka/ Oracle/SQL server Database…\n• Ưu tiên ứng viên có kinh nghiệm phân tích thiết kế hệ thống phần mềm, quy trình phát triển, quy trình DEVSECOPS, CI-CD…\n• Đã từng tham gia các dự án triển khai hệ thống phần mềm cho các ngân hàng thương mại, hoặc có hiểu biết về nghiệp vụ ngân hàng và các hệ thống phần mềm của ngân hàng là một lợi thế\n\nKỹ năng\n• Khả năng nắm bắt công việc nhanh, quản lý, sắp xếp, xử lý công việc khoa học.\n• Khả năng tự nghiên cứu công nghệ ứng dụng vào công việc tốt.\n• Khả năng giao tiếp tốt.\n• Khả năng tư duy, sáng tạo, phân tích, tổng hợp tốt.\n• Khả năng làm việc độc lập, phối hợp làm việc nhóm, quản lý nhóm tốt\n• Có tinh thần trách nhiệm cao trong công việc\n\nWhy you\'ll love working here\nChế độ & Chính sách:\n• Lương thưởng hấp dẫn: 500 - 2000USD\n• Full các chế độ về bảo hiểm y tế, bảo hiểm xã hội, bảo hiểm thất nghiệp, phụ cấp ăn trưa, làm thêm ngoài giờ, nghỉ mát hàng năm…\n• Được nghỉ thứ 7 & Chủ nhật và các ngày nghỉ lễ tết theo quy định', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '22 Ngô Quyền, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(781, 527, 2, '[ShopeeFood] Product Manager', 'About the team - ShopeeFood Product  Product Management is the team that works closely with the Regional Product Team and other cross-functional partners to surface needs, prioritize, test, rollout, and iterate on products. We’re focused on making incredible solutions for our customers, and that\'s why we are looking to hire a passionate and entrepreneurial candidate who seeks to contribute to the growth of food delivery industry. Join us to be part of the team. Your work will touch millions of people a day and is something your friends and family will experience and love.\n\nJob Description:\nWe are looking for a Product Lead to direct product strategy, roadmap development and ensure high return on investment.\n- Architecturing product & product strategy, ensuring that it aligns with the company’s broader goals and market opportunities.\n- Creating and maintaining a detailed product roadmap that outlines major initiatives and timelines.\n- Troubleshooting pain points from both business needs and product performance angles.\n- Identifying and exploring new product opportunities, leveraging emerging technologies and market trends.\n- Ensure features from design to live stage are well aligned with the end goals crafted.\n- Tracking the key and supporting product metrics, in line with overall business metrics to measure product performance and drive continuous improvement.\n- Collaborating with Regional PMs & Developers to ensure product feature roadmaps are delivered on time in full.\n- Collaborating with Local Business cross functional teams to identify the key questions and improvements to be delivered through features initiatives & development.\n- Leadership and development for the Product team to ensure the deliverables aligned with the whole business. Fostering a culture of growth and continuous improvement within the product team.\n\nYour skills and experience:\n- Proven 7+ years’ experience as a Product Manager or similar role, 2+ years experience as a Product Lead is a plus.\n- Strong understanding of product lifecycle management and operational processes. Experience in managing and developing e-commerce or related O2O industry products is preferred.\n- Technical Understanding: Familiarity with the technologies and platforms used in the product development process.\n- Solid knowledge and experience in data analysis to interpret product performance metrics and make data-driven decisions.\n- Able to work under fast paced environment to response to changes in market conditions or internal priorities.\n- Resilience to handle challenges and changes with a positivity and a focus on finding solutions with clear goals in mind.\n- Proficiency in organizational, leadership, communication, and interpersonal skills.\n- Proficiency in project management and problem-solving skills.\n- Fluent in English.\n\nWhy you\'ll love working here:\n- Attractive salary, annual performance bonus\n- Health care insurance, annual health check\n- 14 days annual leave & 6 days sick leave\n- Learning and Development program\n- Free food, drinks at pantry\n- Quarterly Team Building', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sonatus Building, 15 Le Thanh Ton, Ben Nghe Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(782, 528, 2, 'Fullstack Developer (PHP, Laravel, VueJS)', 'PURPOSE:  B2BE is looking for a passionate Fullstack Developer to join our product team. You will be involved in both Front-End and Back-End development, helping to build flexible and configurable digital products used globally.  OBJECTIVES:  Join the product team to build configurable products Collaborate with functional teams across different regions to deliver high-quality results based on defined requirements Follow development best practices to ensure reliability, performance, and consistency across products  RESPONSIBILITIES:  Develop and maintain web applications (Front-End & Back-End) Collaborate with international teams to ensure successful project delivery Ensure consistent code quality, performance, and reliability Contribute to product enhancements and ongoing improvements  YOUR SKILLS AND EXPERIENCE  REQUIREMENTS:  Bachelor’s degree in IT, Computer Science, Software Engineering, or related field 6+ months of experience in web development using: Laravel HTML, JavaScript, CSS TypeScript, VueJS (Vue 3)/Vuetify 3 MySQL Git Knowledge of web services (REST, JSON), web security Have knowledge of Data Structures, System Architectures, Algorithms, Database Design and Object - Oriented Programming; Good attitude and teamwork spirit Fluent in English communication (both written and verbally)  NICE-TO-HAVE SKILLS:  Experience with supply chain systems Logical thinking and problem-solving skills Familiarity with: CodeIgniter JQuery HTML5, ES2024 MVC/HMVC frameworks Microservices Redis Kafka Socket TypeScript Docker S3-compatible storage   WHY YOU\'LL LOVE WORKING HERE  International, dynamic and friendly working environment Opportunities for personal and professional growth Social & health insurance 100% salary during probation period Regular team bonding and engagement events Company laptop provided Petrol allowance after confirmation 13th month salary Annual medical check-up Bao Viet Care 24/24 Insurance after 1 year 14 annual leave days/year (increased with years of service)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '151 Vo Thi Sau, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(783, 529, 2, 'Junior FrontEnd Developer (HTML, CSS, JavaScript)', 'Job description\n- Tham gia thiết kế, xây dựng nền tảng học tập cho trung tâm đào tạo IELTS IZONE. Phụ trách phát triển các dự án EdTech tại IZONE.\n- Xây dựng các tính năng cho giao diện người dùng tuân theo các tiêu chuẩn thiết kế, đảm bảo khả năng bảo trì và mở rộng.\n- Bảo trì và hoàn thiện các vấn đề còn tồn đọng và đề xuất cải thiện.\n- Thu thập ý kiến phản hồi và xây dựng các hướng giải quyết cho người sử dụng và khách hàng để cải tiến và nâng cao chất lượng dự án.\n- Là cầu nối giữa việc việc thiết kế và xây dựng mã nguồn, phối hợp giữa các bên để đem tới cho người dùng sản phẩm tốt nhất.\nYour skills and experience\n- Có trên 1 năm kinh nghiệm làm việc ở vị trí Frontend Engineer\n- Có kiến thức chuyên môn về HTML, CSS và JavaScript & Typescript\n- Có kinh nghiệm chuyên môn về framework web ReactJS\n- Nắm vững các khái niệm cốt lõi về web và trình duyệt (ví dụ: cách trình duyệt phân tích cú pháp HTML  và xây dựng một trang web)\n- Có kiến thức, hiểu biết sâu và kinh nghiệm làm việc với design system.\n- Có thể phân tích bug và đề xuất giải pháp cho các module phần mềm từ cơ bản đến phức tạp\nTECH:\n- React kết hợp với CSS framework Tailwind.\n- Quản lý data model với MobX \n- Java, Postgres và Redis ở Backend\n- Git\n- Design system với các thư viện React UI Component\n- Prosemirror-based content editor \nWhy you\'ll love working here\n- Cung cấp trang thiết bị làm việc\n- Môi trường startup năng động, chuyên nghiệp, tư duy mở, không giới hạn các việc đề xuất, phát triển ý tưởng.\n- Học miễn phí các khoá học IELTS tại trung tâm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 4, ngõ 95, Hoàng Cầu, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(784, 530, 2, 'Senior Software Developer Level 2', 'SEADEV is a product company that delivers effective, affordable sales and digital marketing solutions to our clients. We measure our success not only in terms of profit, but also in terms of global spiritual impact. As a company, we seek to care for our team members and bring transformation to lives in our community. Over the next 10 years we are laser focused on achieving our targets of growing our business 10-fold, supporting over 500 jobs in 10 developing markets, while positively transforming the communities we work within by giving financially and volunteering our time.\n\nJOB OVERVIEW\n\nThe Senior Software Developer Level 2 will join the ShedPro () team and report directly to the Product Manager. has been the main focus for Seadev over the past three years, with a mission to develop cutting-edge sales and lead generation products (including 3D Configurator for Sheds & Carports, Sales-Focused Website and Google Ads Management) catered specifically to shed builders, manufacturers, and dealers in the North American market.  As the Senior Software Developer Level 2, you will play a vital role in crafting the next generation of our products, from designing and implementing new features to refining existing functionalities. Collaborating closely with cross-functional teams, you\'ll ensure our solutions meet top standards. With a focus on problem-solving and innovation, you\'ll drive our projects forward, shaping the future of ShedPro\'s offerings.\n\nYour skills and experience\n\n- Minimum 5 - 7 years of working experience as a software developer, software architect, or similar.\n- Strong proficiency in JavaScript/TypeScript and Node.js.\n- Knowledge of multiple front-end (e.g. HTML/CSS, JavaScript) and server-side (e.g. PHP, Node.js) languages.\n- Experience with the Git version control system.\n- Familiar with Agile software development practices.\n- Solid understanding of RESTful API design principles.\n- Experience with ReactJS/Laravel & Wordpress.\n- Experience in cloud solution development with AWS.\n- Fluent in English skills (writing, speaking, listening, reading).\n- Experience working with international clients directly.\n- Experience in writing unit tests is a plus.\n- Understanding and experience working with 3D models or Babylon.js is a plus.\n\nWhy you\'ll love working here\n\n- Bonus: 13th Salary, Work anniversary bonus, Referral bonus.\n- Gifts: Birthday gifts for employees and their children, Wedding anniversary gift, Tet\'s gift, Baby shower, Women\'s day, Children\'s day.\n- Healthcare: Private Health Insurance & Annual Health Checkup.\n- Performance & Salary Review: Annual assessments to ensure fair and equal pay based on performance results.\n- >20 days off per year.\n- Friday off in July and August: Enjoy longer weekends, recharge, and soak up the summer sun.\n- Learning & Development: Weekly training & inspirational talks at our Social Forum and English classes.\n- Vietnam Social Security: Contribution from probation period.\n- Healthy Food & Snacks: FREE daily snack and Friday lunch.\n- Team building events and holidays: Company retreat, Family Day, Thanksgiving, Christmas, Year End party.\n- Sport activities: Badminton & football.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '33 An Thượng 33 street, Bac My An ward, Ngu Hanh Son, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(785, 252, 2, 'Senior Backend Developer (MPC Crypto Wallet Project)', 'Position Overview\nRegen Tech is building the next generation of secure, privacy-preserving digital wallets using Multi-Party Computation (MPC). We are seeking a Senior Backend Developer to help architect, scale, and secure the core infrastructure of our platform. This role sits at the intersection of cloud engineering, cryptographic coordination, and cross-platform system design, working closely with experts across mobile, firmware, and cryptography teams.\n\nYou will lead and contribute to the development of services that orchestrate secure operations between cloud systems, mobile clients, and hardware devices, ensuring high performance, auditability, and fault tolerance.\n\nKey Responsibilities\n- Lead the design, implementation, and deployment of scalable cloud-based backend services to support MPC-driven wallet functionality.\n- Coordinate architectural decisions between cloud, mobile, and hardware teams, ensuring seamless integration of cryptographic protocols.\n- Define and implement secure authentication, transaction workflows, key orchestration logic, and encrypted communication flows.\n- Manage system observability, cloud performance, CI/CD pipelines, and security posture across environments.\n- Participate in or lead engagements with internal and external security auditors.\n- Mentor junior engineers and potentially build/manage a backend/cloud team.\n- Guide long-term cloud infrastructure strategy, especially around Google Cloud Platform (GCP) and Kubernetes-based environments.\n\nYour skills and experience\nMust-have:\n- Bachelor’s or Master’s degree in Computer Science, Engineering, or a related field.\n- 5+ years of professional experience in backend development, with a focus on distributed systems, cloud orchestration, and service reliability.\n- Proficiency in Go, Node.js, TypeScript, or other modern backend languages.\n- Experience designing and building REST/gRPC APIs, microservices, and asynchronous workflows.\n- Deep understanding of cloud infrastructure (GCP, AWS, or Azure), with strong knowledge of containerization (Docker), orchestration (Kubernetes), and CI/CD pipelines (GitHub Actions, GitLab CI, etc.).\n- Experience working with SQL/NoSQL databases (e.g., PostgreSQL, Redis, MongoDB).\n- Strong security mindset, with experience building secure-by-default systems and supporting user privacy.\n- Excellent communication and collaboration skills across multi-disciplinary teams.\n\nNice-to-have:\n- Direct experience with cryptographic systems, MPC protocols, or key management infrastructure.\n- Familiarity with blockchain protocols, smart contracts, or crypto wallet systems.\n- Hands-on experience with GCP and services like Compute Engine, GKE, Cloud Functions, Cloud Storage.\n- GCP Certifications (e.g., Cloud Architect, DevOps Engineer) are a plus.\n- Experience working with mobile or embedded hardware is a strong bonus.\n\nWhy you\'ll love working here\n- Work on cutting-edge crypto tech: Be part of a team building secure, MPC-powered wallet technology that’s reshaping the future of digital asset protection.\n- Collaborate with top talent: Work alongside a world-class team of engineers and crypto experts who value quality, innovation, and continuous learning.\n- Flexible & remote-friendly environment: Enjoy the freedom to work from anywhere or join us in Ho Chi Minh City - your impact matters more than your location.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote', 'Full-time', '2025-10-07 20:59:18.149534'),
	(786, 531, 2, '7 month contract Frontend Engineer (HTML, CSS, Vue)', 'Why Pizza Hut Digital Ventures?\nWe love pizza. We eat it a lot. There’s no doubt about that and we’re proud of it. But what makes us different is that it’s our people that drive the success of our business.\nAlongside KFC, Taco Bell and The Habit Burger Grill, we are part of the Yum! Family; the world’s largest restaurant company with nearly 43,000 restaurants in over 140 countries. At Pizza Hut, we are on a journey to build the most loved global brand and the fastest growing in every country; we have big plans over the next 5 years to achieve explosive growth in a competitive and ever-growing market. We want to make it easy to get the best pizza and digital is at the core for this. From building a world-class platform and clean mobile experiences we are pushing the boundaries to ensure we are a source of innovation.\n\nThe role:\nPHDV are working on a multi-year project to consolidate their online ordering product across all of the markets that we support globally. The team you will be working on is the front-end team, which will play a crucial role in building the new UI platform & working in partnership with other teams to enable them to build their own experiences for all of our markets.\nAs a cross functional team of Engineers, Designers, Delivery Managers and more, the front-end team works as a unit to deliver high quality outputs. We typically work by having an idea, analyzing it and then running experiments to see if this is the way we should move forwards. Everybody has a voice within the team and, when required, we will come together to work collaboratively to solve a problem. It’s important to us that everyone is bought into the process and understands what we’re doing and why.\n\nResponsibilities:\nBuilding secure, componentized frontend web applications using progressive enhancement and responsive design\nIntegrating with custom APIs hosted in AWS.\nWorking closely with the team to deliver a clean and maintainable codebase.\nResponsible for building componentized frontend web applications using progressive and responsive design.\nCollaborate with the product and design team to improve UI performance and enhance UX experiences.\nContinuous input into product roadmap.\n\nYour skills and experience\nRequirements:\n3+ years of experience building and designing delightful user experiences as a frontend engineer.\nStrong grasp of both written and verbal communication in English.\nProficiency with HTML5, CSS3, and Javascript (Typescript is a big plus, but you can pick it up on the job if not!).\nGood knowledge of Vue.js and VueX (familiarity with React.js and single page application is a plus).\nHands-on experience in using CSS preprocessors like SCSS, SASS, or LESS.\nFamiliar with Webpack configuration.\nHave experience in implementing and designing large-scale front-end web applications.\nHands-on experience in integrating with REST APIs.\nProficiency in code versioning tools such as Github, Bitbucket or Gitlab.\nBasic understanding of HTTP requests and responses.\n\nNice to have:\nDon’t worry if you don’t tick any of these boxes yet, we can help bring you up to speed!\nBasic understanding of NPM modules.\nMicro Frontend experience.\nGraphQL experience.\n\nWhy you\'ll love working here\nAttractive Benefits:\nAnnual Leave: 1.5 days/ month\nFlexible Friday afternoon\nFull salary insurance\nRegular engagement activities: sport clubs, internal events…\nSupport Macbook and Monitor.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Waseco Building - 10 Pho Quang Street, Ward 02, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(787, 532, 2, 'QA Automation Test (QA QC, Tester, English)', 'Sunbytes is a leading Tech & Talent Solutions company known for innovative and scalable solutions. We focus on achieving goals for our partners and team members, delivering high-quality products and services, and fostering a supportive, challenging work environment. Our diverse team shares a common purpose, making Sunbytes a great place to work.\n\nWe offer comprehensive long-term partnerships, including recruitment, dedicated worldwide talents, and custom software development tailored to meet client needs.\n\nAbout the Role:\n\nSunbytes is actively seeking a highly skilled QA Automation Engineer to play a pivotal role dedicated exclusively to our distinguished Dutch client in the ever-evolving field of IoT security. Picture yourself joining a team of exceptionally talented individuals from Europe and Asia, collaborating seamlessly with our client in the Netherlands to deliver trailblazing software solutions in the dynamic IoT security industry.\n\nAs a QA Automation Engineer, you won\'t just be part of a team; you\'ll be instrumental in crafting innovative products that not only meet but exceed the expectations of our clients. Collaborate with a team of highly proficient software engineers to create solutions that add substantial value. The allure doesn’t end there – success in this role opens the door to a long-term position, offering an exceptional opportunity to grow in tandem with the escalating success of our client.\n\nResponsibilities\n\n- Collaborate with cross-functional teams to ensure the quality of software applications.\n- Conduct API and UI testing to verify functionality, reliability, and user-friendliness.\n- Develop and execute comprehensive manual test cases; promptly report and track identified issues.\n- Implement automated tests using Typescript (and Jest) to enhance software efficiency and accuracy.\n- Utilize industry-standard frameworks for API automation testing.\n- Leverage Jira Xray for effective test resources management and collaboration within the testing competence center.\n- Knowledge of SQL for data analysis would be a nice addition.\n\nYour skills and experience\n\n- Minimum of 3 years of experience in testing and quality assurance.\n- Proficiency in Typescript (or Javascript) for developing automated tests.\n- Strong experience in API automation testing (Postman or Swagger).\n- Knowledge of Selenium for automated web browser testing is a good addition.\n- Highly motivated with a proactive approach to problem-solving.\n- Excellent communication and collaboration skills.\n- Ability to work independently and as part of a team.\n- Strong organizational skills and attention to detail.\n\nWhy you\'ll love working here\n\nWhat can you expect from us\n\nWe offer you a young, challenging and friendly environment with a free dress code, a competitive salary, full health benefits and social insurance and individual career path planning.\n\nFurthermore we offer\n- 16 days annual leave (18 after 2 years of employment);\n- 3 sick days per year;\n- 4 creative days per year where you can explore new techniques and possibilities;\n- A yearly company trip;\n- 13th month salary;\n- Premium Health Insurance 24/7.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '400/8A Ung Văn Khiêm, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(788, 468, 2, 'Project Manager (Business Analyst/Agile/Scrum/Jira)', 'Top 3 reasons to join us\n- Competitive salary, bonus, review salary/year\n- Participate in full government-regulated insurance\n- A professional working environment\n\nJob description\nOverview\nWe are seeking an experienced Project Manager to lead cross-functional teams in developing innovative products and features for the securities industry. This role involves managing projects from concept to launch while ensuring alignment with market needs, client expectations, and company objectives.\n\nKey Responsibilities\n- Oversee the end-to-end delivery of product development projects, ensuring they meet scope, timeline, and budget requirements.\n- Develop detailed project plans, manage resources, track progress, and communicate status updates to stakeholders.\n- Collaborate with business analysts, web developers, data analysts, and other key stakeholders to define project requirements and ensure alignment with business goals.\n- Identify and mitigate risks, resolve issues promptly, and ensure compliance with relevant industry standards and regulations.\n- Conduct post-project evaluations and recommend improvements to enhance future project outcomes.\n\nYour skills and experience\n- Bachelor‘s degree in Business, Finance, Computer Science, or a related field.\n- Minimum 3 years of experience as a Project Manager or Business Analyst, preferably within the financial services, e-commerce, startup, or software sectors.\n- Demonstrated experience in designing web applications, mobile apps, and other digital platforms.\n- Proficiency in project management tools such as Jira, Asana, etc.\n- Practical experience with project methodologies like Agile, Scrum, or Waterfall.\n- Excellent communication, organizational, and leadership skills.\n- Strong English communication skills (verbal and written).\n\nWhy you\'ll love working here\n- Working in the financial/securities environment.\n- Competitive salary and bonus based on the performance of staff.\n- Salary review every year, many opportunities for career development.\n- Participating in the types of compulsory insurance as policy.\n- Receiving annual health care, full health insurance and accident 24/24.\n- Participating in the company\'s training programs.\n- Being support the tuition fee for the training courses.\n- Participating in sports activities, charitable programs, quarterly teamwork and annual trip.\n- Working in a professional and dynamic environment, and enjoy the fresh air, peaceful environment at Phu My Hung urban.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 21, Phú Mỹ Hưng Tower, số 08 Hoàng Văn Thái, Phường Tân Phú, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(789, 515, 2, 'Java/Golang/Angular Developer (Middle/ Senior)', 'We are looking for a Java/ Golang/ Angular Developer to be part of our expanding team. Your main goal is to develop products with FinTech and Payments processing industry.\n\nAs a Developer, your responsibilities will be:\n- Meeting with customer for requirement and development\n- Design Solution, Module base on Sale/Customer requirements\n- Monitor, Update team on project implementation\n- Developing and implementing Payment, Retail and FinTech projects.\n- R&D on assigned modules and projects for company and customers.\n- Working on both domestic and oversea projects.\n\nGeneral skills:\n- At least 03 years working experiences\n- Bachelor’s degree in computer programming, computer science, or a related field.\n- Good knowledge of programming practices and design patterns.\n- Solid understanding of object-oriented design concepts.\n- Ability to analyze and familiarize with complex systems.\n- Speaking, Writing and Reading English is preferred.\n- Familiar with application programming using Java/J2EE, JavaScript, XML\n- Good knowledge on Database system: Oracle, SQL Server, MySQL\n- Experience with Web Service (SOAP and RESTful).\n\nOpportunity to become Technical Leader if you have:\n- Good leadership skills; analytical skills and communication skills\n- Logical thinking & Problem – solving skills\n\nWhy you\'ll love working here:\n- Competitive salary, negotiable based on competence\n- Performance-based bonuses twice a year, depending on KPI and company business results\n- Lunch allowance: 730,000 VND/month\n- In addition to 12 annual leave days as per labor law, additional paid summer leave based on seniority\n- Health insurance for employees and their family members\n- Participation in company-organized team-building programs and annual community activities\n- Working schedule: Monday – Friday, plus 2-3 Saturday mornings per month\n- Opportunities to join internal training and development programs\n- Full benefits including social insurance (SI), health insurance (HI), unemployment insurance (UI), annual health check-ups, and other benefits as per company policies and labor law regulations.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'BIDV Tower, 194 Tran Quang Khai, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(790, 533, 2, 'Senior AI Engineer/ NLP Engineer', 'GIỚI THIỆU CHUNG:\nVinBigdata\nCông ty cổ phần VinBigdata được thành lập theo định hướng trở thành tập đoàn Công nghệ – Công nghiệp – Thương mại Dịch vụ hàng đầu Việt Nam của Vingroup. Với lợi thế đặc biệt về hạ tầng dữ liệu lớn, VinBigdata cung cấp các sản phẩm, giải pháp ứng dụng trí tuệ nhân tạo, giúp doanh nghiệp đẩy nhanh quá trình chuyển đổi số, tối ưu hiệu quả vận hành, kinh doanh và gia tăng trải nghiệm người dùng cuối. Là một công ty trẻ trung và đang trong giai đoạn phát triển nhanh chóng, VinBigdata luôn chào đón những tài năng gia nhập công ty để cùng thực hiện mục tiêu “Công nghệ Việt – Vì tương lai Việt”.\n\nVề phòng ban chuyên môn:\nKhối Công nghệ trợ lý ảo nghiên cứu và ứng dụng các bài toán trí tuệ nhân tạo trong xử lý tiếng nói và xử lý ngôn ngữ tự nhiên để xây dựng nên các giải pháp Trợ lý ảo cho người dùng cá nhân và doanh nghiệp. Hai sản phẩm tiêu biểu của Khối là Vivi – trợ lý ảo toàn diện cho người Việt đã và đang hoạt động trên toàn bộ các sản phẩm xe điện của VinFast; và Vinbase – nền tảng trợ lý ảo đa nhận thức toàn diện, là nền tảng giúp phát triển Vivi và các trợ lý ảo khác hoạt động trên các hệ thống trả lời và nhắn tin tự động thông minh.\nPhòng xử lý ngôn ngữ tự nhiên là một bộ phận của khối Công Nghệ trợ lý ảo có nhiệm vụ nghiên cứu phát triển các công nghệ lõi về xử lý ngôn ngữ phục vụ các sản phẩm như Chatbot, Callbot, Trợ lý ảo trong hệ sinh thái VinBase.\n\nMỤC ĐÍCH CỦA VỊ TRÍ NÀY:\n- Xây dựng được các mô hình hoặc thuật toán tối ưu trong lĩnh vực xử lý ngôn ngữ tự nhiên.\n- Xây dựng và thực thi các giải pháp hiệu quả cho các sản phẩm ứng dụng các công nghệ về xử lý ngôn ngữ tự nhiên.\n\nTRÁCH NHIỆM:\n- Đọc và tìm hiểu các công nghệ về xử lý ngôn ngữ mới nhất trong các bài báo khoa học/blog công nghệ.\n- Thực thi các mô hình và thuật toán trong các nghiên cứu trước đó để kiểm chứng hoặc cải tiến.\n- Phát triển các mô hình và thuật toán mới.\n- Tham gia thiết kế và đóng gói các giải pháp ứng dụng các công nghệ xử lý ngôn ngữ trong các sản phẩm/dự án Chatbot, Callbot, Trợ lý ảo.\n- Các công việc khác theo phân công của cấp trên.\n\nYÊU CẦU:\nHọc vấn:\n- Tốt nghiệp các trường Đại học chuyên ngành: Công nghệ thông tin, Khoa học máy tính hoặc tương đương.\n\nKinh nghiệm:\n- Tối thiểu 2 năm kinh nghiệm làm việc trong lĩnh vực NLP.\n- Ưu tiên các ứng viên đã có kinh nghiệm làm việc tại các công ty về AI, hoặc làm việc trong các dự án nghiên cứu.\n\nKỹ năng:\n- Kỹ năng mềm: Có khả năng làm việc nhóm tốt, khả năng giao tiếp diễn giải vấn đề tốt.\n- Kỹ năng chuyên môn: Khả năng tự học và nghiên cứu tốt, có kiến thức chuyên môn sâu về lĩnh vực học máy thống kê, học sâu, xử lý ngôn ngữ tự nhiên.\n- Kỹ năng máy tính: Khả năng lập trình tốt, có tư duy lập trình và tư duy thuật toán. Sử dụng thành thạo các ngôn ngữ lập trình như Python, Java, C++, các nền tảng lập trình học máy và học sâu như Skearn, Pytorch, Tensorflow.\n- Ngoại ngữ: Thành thạo Tiếng Anh.\n\nĐiểm cộng/ Ưu tiên:\n- Ưu tiên các ứng viên có thành tích trong nghiên cứu khoa học, có các bài báo nghiên cứu tại các hội nghị, tạp chí.\n- Ưu tiên các ứng viên có giải thưởng trong các cuộc thi lập trình, hoặc các cuộc thi trong các challenge về machine learning hoặc xử lý ngôn ngữ tự nhiên ví dụ như Kaggle, NLP share-task, VLSP, etc.\n\nPhúc lợi:\n- Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của Luật Lao động (BHXH, BHYT, BHTN) và được Công ty mua Bảo hiểm sức khỏe cá nhân theo cấp bậc vị trí, khám sức khỏe định kỳ tại Bệnh viện và Trung tâm khám sức khỏe uy tín trên toàn quốc.\n- Được hưởng chế độ ưu đãi khi sử dụng các dịch vụ như: Ưu đãi học phí (Vinschool), khám chữa bệnh (Vinmec), nghỉ dưỡng (Vinpearl), mua xe (VinFast), … theo chế độ của Tập đoàn.\n- 12 ngày nghỉ phép năm, nghỉ các ngày lễ, Tết theo quy định của pháp luật.\n- Được cấp máy tính xách tay, trang thiết bị làm việc khác phù hợp với yêu cầu công việc.\n- Phụ cấp ăn trưa hàng tháng.\n- Canteen rộng rãi, trang bị đầy đủ các thiết bị cần thiết như máy pha cà phê, tủ lạnh, lò vi sóng, các loại trà và cà phê hạt được bổ sung hàng ngày.\n- Chương trình chăm sóc sức khỏe tinh thần cho CBNV.\n- Tham gia các hoạt động nội bộ, hoạt động teambuilding, du lịch hàng năm của công ty.\n\nCơ hội phát triển:\n- Cơ hội làm việc trong môi trường chuyên nghiệp, công nghệ dẫn đầu về AI, quy tụ hơn 100 nhà khoa học, chuyên gia, kỹ sư đến từ các trường đại học hàng đầu thế giới và Việt Nam như: ĐH Yale (Mỹ), ĐH Johns Hopkins (Mỹ), ĐH Illinois (Mỹ), ĐH Toulouse (Pháp), ĐH Cambridge (Anh Quốc), Đại học Bách Khoa, Đại học Công nghệ – Đại học Quốc gia, …\n- Được xây dựng kế hoạch phát triển cá nhân.\n- Được tài trợ các khóa học miễn phí trên Coursera, tham gia các khóa học chuyên môn, kỹ năng mềm, quản lý,… phù hợp với yêu cầu công việc và nhu cầu phát triển của mỗi cá nhân.\n- Được hỗ trợ một phần chi phí thi các chứng chỉ chuyên môn phục vụ công việc.\n\nMôi trường làm việc:\n- Văn phòng hiện đại, tiện nghi, trẻ trung và chuyên nghiệp.\n- Tham gia không giới hạn các câu lạc bộ: cộng đồng đọc sách, CLB cầu lông, bóng bàn, bóng đá (công ty hỗ trợ một phần chi phí cho các hoạt động của CLB).\n- Môi trường làm việc cởi mở, khuyến khích CBNV đóng góp ý kiến, sáng kiến, ý tưởng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Century Tower, T14, Khu đô thị Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(791, 238, 2, '[Middle, Junior] Java Fullstack Developer (Spring)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Phát triển, trực tiếp lập trình các hệ thống, ứng dụng của Ngân hàng, gồm các hệ thống nội bộ và ứng dụng dành cho khách hàng với quy mô 30 triệu khách hàng cá nhân và 300.000 khách hàng doanh nghiệp.\n- Phát triển hoặc phối hợp triển khai cùng các nhà cung cấp cho các giải pháp Công nghệ.\n- Quản lý, phát triển dịch vụ tích hợp với các hệ thống core như: T24, WAY4, BPM, CRM, CIC ...\n- Quản lý, phát triển API trên API Gateway phục vụ tích hợp với các đối tác trong nước và quốc tế.\n- Nghiên cứu, thử nghiệm, triển khai áp dụng các xu hướng công nghệ mới vào việc phát triển: GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL ...\n\nYour skills and experience\n- Tốt nghiệp Đại học các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Khoa học máy tính, Hệ thống thông tin...\n- Có kinh nghiệm làm việc thực tế tại các công ty hoặc dự án về lập trình Backend\n- Thành thạo 1 trong các ngôn ngữ BackEnd, ưu tiên Java.\n- Thành thạo Spring framework: spring core, spring sercuity, spring boots.\n- Thành thạo một trong trong các loại database: Oracle, Sqlserver, PostgreSQL, Mongodb.\n- Có kinh nghiệm trong domain tài chính, ngân hàng là lợi thế\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n- Cơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n- Môi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng\n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(792, 534, 2, 'Unity Developer (C#/ Games)', 'Top 3 reasons to join us\n\n- Chính sách Thưởng dự án minh bạch không giới hạn\n- Cơ hội tham gia&amp;học hỏi các đối tác lớn Google....\n- Tham gia các dự án Games chất lượng cao \n\nJob description\n\n- Sử dụng Unity, C# để sản xuất, phát triển các dòng game Hyper Casual, Puzzle đa nền tảng; phát hành trên Google Play, App Store &amp; Web; định hướng target các thị trường Tier 1 bằng các sản phẩm chất lượng cao;\n- Cùng team lên ý tưởng và giải pháp cho các tính năng trong game;\n- Sửa lỗi và cải thiện tính năng, hiệu suất của game;\n- Tích cực góp ý, phối hợp với các bộ phận như Artist, Animation để thực hiện các phần liên quan tới game feel nhằm đem lại trải nghiệm game “đã” nhất cho người dùng;\n- Tích hợp SDK của các bên thứ 3 vào game;\n- Phối hợp với các thành viên khác trong team để vận hành và tối ưu sản phẩm.\n\nYour skills and experience\n\n- Có ít nhất 1 năm kinh nghiệm sử dụng Unity &amp; C#; ít nhất 1 năm kinh nghiệm tham gia sản xuất, phát triển các sản phẩm game puzzle; đã trực tiếp tham gia phát triển sản phẩm phát hành ra thị trường global là 1 lợi thế;\n- Hiểu biết và sử dụng thành thạo C#, Unity: UI Canvas, 2D Animation (Spine/DragonBone), Animator, Particle System, Physic, Performance/Size Optimization; có kiến thức tốt về OOP, Design Patterns; có tư duy thiết kế hệ thống game dòng mid-core;\n- Yêu thích game và chơi game;\n- Tinh thần dấn thân, không ngại thất bại, không kỳ vọng thành công sớm, kiên trì với công việc;\n- Tinh thần trách nhiệm cao, chăm chỉ, cần cù, kỷ luật cao trong công việc, có khả năng chịu được áp lực công việc cao;\n- Có khả năng quản lý task, sắp xếp và điều phối, phân chia công việc tốt;\n- Khả năng làm việc độc lập và cộng tác nhóm tốt; chủ động trong công việc;\n- Có tinh thần lắng nghe, sẵn sàng chia sẻ và học hỏi các kiến thức công nghệ mới;\n- Có khả năng đọc, hiểu và tìm kiếm các tài liệu bằng Tiếng Anh.\n\nWhy you\'ll love working here\n\n- Mức lương cạnh tranh (10 - 15M), thoả thuận thêm khi phỏng vấn;\n- Chính sách thưởng dự án minh bạch, rõ ràng và không giới hạn;\n- Lộ trình thăng tiến rộng mở, có cơ hội lớn trở thành trưởng nhóm, quản lý;\n- Có cơ hội được tham gia và học hỏi với các đối tác lớn Google, Facebook, Unity...;\n- Chế độ lương thưởng, hiếu hỉ, trà chiều free cùng môi trường trẻ đầy nhiệt huyết;\n- Cơ hội được tham gia sản xuất các dự án games chất lượng cao để phát triển bản thân;\n- Thưởng dự án hàng quý khi sản phẩm đạt doanh thu, thưởng thâm niên, lương tháng 13 đầy đủ.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(793, 535, 2, '05 Java Senior Developer / Tech Lead (Microservices)', 'We are seeking a skilled developer to work on a centralized and optimized customer interaction, sales process, and customer service management platform. This role involves building a scalable and secure system that seamlessly integrates with existing business applications to enhance customer engagement and drive business growth.\n\nApplication Development & Maintenance\n- Design, develop, and maintain Java applications using Spring Boot and Spring Framework.\n- Implement RESTful APIs and integrate with frontend applications.\n- Write efficient, scalable, and maintainable code.\n\nDatabase Management\n- Develop and optimize database queries for MySQL and MongoDB.\n- Work with JPA/Hibernate for ORM (Object Relational Mapping) and ensure efficient database interactions.\n\nSpring Framework Expertise\n- Utilize Spring Core, Spring MVC, Spring Security, Spring Data JPA, and Spring Boot for application development.\n- Implement Spring Security for authentication and authorization.\n\nTesting & Debugging\n- Write and maintain unit tests (JUnit, Mockito).\n\nVersion Control & CI/CD\n- Manage source code using Git and repositories like GitHub/GitLab/Bitbucket.\n\nContinuous Learning & Improvement\n- Stay updated with the latest trends in Java, Spring, MySQL, MongoDB, and emerging technologies.\n- Improve existing features and propose innovative solutions.\n- Make quality and usability your primary goals.\n- Problem investigation, system troubleshooting, and bug fixing.\n\nYour skills and experience\n- Minimum of 5 years of experience in Java backend development using Spring Boot or similar frameworks.\n- Proficiency in Java 8+ with strong knowledge of OOP (Object-Oriented Programming) concepts.\n- Experience with Spring Framework, including:\n   - Spring Boot (Microservices development)\n   - Spring MVC (Web applications)\n   - Spring Data JPA (ORM with Hibernate)\n   - Spring Security (Authentication & Authorization)\n- Experience with JPA/Hibernate for ORM and database interactions.\n- Proficiency in developing RESTful APIs and working with API documentation tools like Swagger/OpenAPI.\n- Good knowledge of version control systems, preferably Git (GitHub, GitLab, or Bitbucket).\n- Familiarity with CI/CD pipelines (Jenkins, GitHub Actions, GitLab CI, or equivalent).\n- Basic knowledge of containerization using Docker (Kubernetes is a plus).\n- Understanding of caching mechanisms (Redis, Ehcache) and messaging systems (RabbitMQ, Kafka) is a plus.\n- Experience with testing frameworks such as JUnit, Mockito for unit and integration testing.\n- Experience with Web Layout Design and Development: HTML5, JavaScript, CSS, JQuery, AJAX is a plus.\n- Good to have knowledge in eCommerce systems, Hybris SAP.\n- Good willingness to learn new technologies required for work.\n\nWhy you\'ll love working here\n- 13th-month salary bonus.\n- One additional day for Annual leave after each year of service.\n- Full base insurance contribution (Social, Medical, and Unemployment insurance).\n- Attractive healthcare insurance.\n- Lunch & parking allowance.\n- Gift in special events.\n- Sponsorship for training courses, professional certificates.\n- Monthly Company’s meeting for employees’ understanding about company’s strategy and development plan; Happy Hour with snack and fresh fruit.\n- Various team building, sports activities, company trips, parties, and Trade Union activities.\n- Weekly social activities for Cycling club, football club,etc.\n- English speaking, professional, dynamic work environment with multi-national team members.\n- Opportunity to work on-site abroad.\n- Various charity activities to create opportunities for employees to help the poor and unfortunate people in Vietnam community.\n- Above benefits are designed for Vietnamese employees. Expat\'s package will be communicated in offer letter, including work permit support term and condition.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '285  Viettel Complex Building, Cach Mang Thang Tam , District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(794, 536, 2, 'Fullstack Developer (ReactJS, VueJS, Python)', 'Chúng tôi đang tìm kiếm một Full Stack Developer có kinh nghiệm để phát triển và duy trì các ứng dụng web, làm việc với khách hàng quốc tế và đảm bảo chất lượng sản phẩm đạt tiêu chuẩn cao nhất.\n\nTrách nhiệm chính\n- Phát triển và tối ưu hóa các ứng dụng web sử dụng các công nghệ hiện đại như ReactJS, VueJS, Python, Laravel và NodeJS (AdonisJS)\n- Hợp tác với khách hàng quốc tế và các thành viên trong nhóm để cung cấp giải pháp chất lượng cao\n- Tham gia vào quá trình review code và đóng góp vào các quyết định về kiến trúc\n- Quản lý kiểm soát phiên bản và quy trình triển khai sử dụng Git\n- Giao tiếp bằng tiếng Anh cho các vấn đề kỹ thuật, cập nhật dự án và giải quyết sự cố\n\nYêu cầu thiết yếu\n- Tối thiểu 2 năm kinh nghiệm trong phát triển phần mềm chuyên nghiệp\n- Thành thạo các công nghệ: ReactJS/VueJS, Python, PostgreSQL, Redis, RabbitMQ, Laravel và NodeJS (AdonisJS)\n- Kinh nghiệm vững chắc về phát triển frontend với ReactJS hoặc VueJS\n- Khả năng giao tiếp tiếng Anh trong môi trường làm việc quốc tế\n- Kiến thức vững chắc về Git và các quy trình kiểm soát phiên bản\n- Kinh nghiệm làm việc với Docker và Nginx\n- Kỹ năng giải quyết vấn đề và giao tiếp tốt\n\nYếu tố cộng điểm\n- Kinh nghiệm làm việc với bản đồ: Có kinh nghiệm tích hợp và làm việc với các API bản đồ (ví dụ: Google Maps API, Mapbox, OpenStreetMap) và các thư viện liên quan để hiển thị và tương tác với dữ liệu không gian\n- Kiến thức về DevOps là một lợi thế\n\nĐiều kiện làm việc\n- Địa điểm: Văn Quán, Hà Đông, Hà Nội\n- Thời gian làm việc: Thứ 2 - Thứ 6 (08:00 - 17:30)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Văn Quán, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(795, 537, 2, 'Cloud Data Engineering Lead (Python, AWS)', 'Company Description\nOur client empowers organizations by transitioning legacy workloads to cutting-edge Cloud, DevOps, and AI technologies. As Vietnam\'s AWS Partner of the Year for two years in a row, they bring deep expertise and innovative thinking to every project.\nThey\'re not just a consultancy—they\'re a transformation partner. Their dynamic team of engineers, architects, and DevOps experts is passionate about delivering impactful cloud solutions across industries, including FinTech, BFSI, and Digital Startups.\n\nAbout the Role\nWe are looking for a Cloud Data Engineering Lead to take the reins in designing and delivering modern cloud-native data architectures. You’ll be working at the intersection of big data and cloud computing—building scalable systems, managing a talented data team, and helping clients solve complex data challenges. This is a unique opportunity to work with top-tier technology leaders, drive innovation, and leave your\nmark on some of the most ambitious cloud projects in the region.\n\nKey Responsibilities\n● Architect and build modern cloud-native data platforms (Data Lakes, Lakehouses, Data Warehouses).\n● Develop robust data pipelines and ETL/ELT processes using modern frameworks (Airflow, Glue, DBT, etc.).\n● Manage real-time data ingestion and streaming solutions with Kafka, Flink, or Apache Beam.\n● Collaborate with DevOps and cloud architects to deploy scalable solutions on AWS (or GCP/Azure).\n● Guide and mentor a growing team of data engineers and AI engineers, helping shape project outcomes and team growth.\n● Write clean, efficient code using SQL and Python; maintain and tune data solutions for performance.\n● Contribute to project scoping, design reviews, and strategic data decisions with CTO and CEO.\n● Stay ahead of technology trends and recommend new approaches for data strategy and architecture.\n\nYour skills and experience\nMust-Have:\n• 7+ years in data engineering, cloud data architecture, or related roles, with 2+ years in leadership roles.\n• Hands-on experience with cloud platforms (AWS preferred)\n• Proficient in SQL and Python; strong coding discipline.\n• Familiar with orchestration tools like Apache Airflow, Dagster, or Luigi.\n• Knowledge of modern data integration tools (Fivetran, Airbyte, Talend, AWS Glue).\n• Experience with query engines and processing tools: Presto, Flink, PySpark, DBT.\n• Understanding of modern databases and real-time data systems (Redshift, MongoDB, Kafka, PostgreSQL).\n\nNice-to-Have:\n• Exposure to Big Data platforms like Snowflake, Databricks, or Hadoop.\n• AWS Data Analytics or related cloud certifications.\n• Strong leadership, communication, and stakeholder management skills.\n\nWhy you\'ll love working here\n• Work with cutting-edge cloud & AI technologies.\n• Join global projects with real impact across industries.\n• Modern, dynamic, and multicultural work environment.\n• Clear career path and learning support with access to certifications (AWS, etc.).\n• Flexible working environment and collaborative team culture.\n• Annual company trips, fun team events, and great office vibes.\n• Competitive salary and full benefits package.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ward 11, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(796, 433, 2, 'Fullstack  Developer (Javascript, Express/ NextJS/Koa)', 'Quản trị và phát triển các phần mềm phục vụ hoạt động nội bộ và sản phẩm công ty, bao gồm:\nPhát triển và triển khai phần mềm nội bộ:\nTiếp nhận yêu cầu từ các phòng ban, tiến hành phân tích, lập trình, cài đặt, và hướng dẫn sử dụng phần mềm cho người dùng.\nTham gia phát triển sản phẩm:\nCùng đội ngũ phát triển xây dựng hệ thống bảng điện chứng khoán và ứng dụng giao dịch chứng khoán trên nền tảng Android/iOS.\nTối ưu hóa hiệu năng và trải nghiệm người dùng:\nCải thiện tốc độ, khả năng phản hồi và sự ổn định của các ứng dụng.\nPhân tích hành vi người dùng:\nXây dựng hệ thống log/tracking để thu thập và phân tích dữ liệu hành vi người dùng, phục vụ cho việc tối ưu sản phẩm.\nKinh nghiệm: Tối thiểu 1 năm trong lĩnh vực phát triển phần mềm.\nTư duy sản phẩm: Đam mê cải tiến sản phẩm, mong muốn nâng cao chất lượng mỗi ngày.\nHiểu biết kỹ thuật:\nAm hiểu giao thức HTTP và các phương thức: GET, POST, PUT, DELETE, v.v.\nBiết về giao thức MCP (Model Context Protocol) là một lợi thế.\nCó kinh nghiệm với ít nhất một framework:\nFront-end: AngularJS, Angular, VueJS, React\nBack-end: ExpressJS, NextJS, KoaJS\nKiến thức tốt về OOP, mô hình dữ liệu và design patterns.\nThành thạo SQL và khả năng xử lý, tổng hợp dữ liệu từ nhiều nguồn để tạo báo cáo.\nKỹ năng mềm:\nKhả năng trình bày, giao tiếp rõ ràng.\nTư duy logic, chủ động trong công việc, làm việc nhóm và độc lập tốt.\nTrung thực, siêng năng, có khả năng chịu áp lực cao.\nThu nhập:\nLương theo năng lực\nThưởng KPI theo hiệu quả công ty & cá nhân\nPhúc lợi:\nBảo hiểm sức khỏe cao cấp, khám sức khỏe định kỳ hàng năm\nTài trợ chi phí lấy chứng chỉ hành nghề, đào tạo chuyên môn\nMôi trường làm việc:\nVăn phòng tại Quận 1, TP.HCM\nThời gian làm việc: 8h15 - 17h00 (Thứ 2 đến Thứ 6), nghỉ Thứ 7 & Chủ nhật\nVăn hóa năng động, trẻ trung, thường xuyên tổ chức teambuilding trong và ngoài nước.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lầu 2, số 6 Hồ Tùng Mậu, Phường Nguyễn Thái Bình, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(797, 387, 2, 'Senior Front-end Developer (ReactJS)', 'Job description\n- Code, implement, unit test, maintain and troubleshoot web application.\n- Comply with established coding quality standard of the company.\n- Assist Team Leader in reviewing work results of low-level members.\n- Participate in R&D, training, knowledge sharing activities.\n- Follow the project and organization processes, policies and regulations.\n- Ensure the assigned tasks to be performed on-time and with high quality.\n- Report to Team Leader.\n\nYour skills and experience\n- At least 3+ years of experience in front-end development\n- Have strong knowledge about any of JavaScript framework in production (React + Redux or other state manager).\n- Experience in Functional Programming\n- Experience in HTML5/CSS3, Sass/LESS, jQuery and Bootstrap, CSS architecture (Atomic, BEM).\n- Experience in CSS in JS is a plus.\n- Experience in responsive web design.\n- Understanding of GIT, Webpack (Module loader), Unit test\n- Good at math and algorithms.\n- Capable of managing document versions, source code versions; using project management system (e.g. Atlassian Jira, Redmine...)\n- Experience in React Native, React Native Module.\n\nWhy you\'ll love working here\n- Competitive salary with performance-based bonuses.\n- Allowances: 1,070,000 VND per month on lunch and transportation\n- Positive and open-minded environment which is made up of people who are always ready to listen and share.\n- A vibrant, creative work environment where ideas are celebrated.\n- Equipment and devices provided at work, or allowance for using personal devices.\n- Opportunities for professional growth and development.\n- A supportive team that values collaboration and innovation.\n- Number of days-off, public and New Year holidays, annual leave will be under Labor Law\n- Entitled to Social insurance, health insurance, underemployment insurance and other benefits according to the company\'s policies\n- Health screening and wellness check-up services at prestigious hospitals\n- Comprehensive benefits package including health, dental…\n- Working hours: 8:30 – 17:30 from Monday – Friday.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '39/3 Trần Nhật Duật, Phường Tân Định, Quận 1, Thành phố Hồ Chí Minh, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(798, 510, 2, 'Quality Assurance Manager (QAM)', 'Top 3 reasons to join us\n1. Sự nghiệp thăng tiến không giới hạn\n2. Dự án công nghệ trong và ngoài nước\n3. Thu nhập hấp dẫn, đãi ngộ toàn diện\n\nJob description\n- Xây dựng khung quy trình công ty và chủ trì cải tiến hệ thống quy trình đặc biệt quy trình sản xuất phần mềm cho OS theo các công nghệ, mô hình, phương pháp mới (DevSecOps, Design Thinking, Shiftleft Testing, CICD, Agile…); theo thực tế áp dụng và ý kiến Khách hàng.\n- Đưa ra các mục tiêu, chương trình hành động để nâng cao mức độ tuân thủ quy trình như đánh giá nội bộ, số hóa quy trình.\n- Định nghĩa và triển khai thực tế các hoạt động đảm bảo chất lượng sản phẩm theo yêu cầu của Khách hàng, nội bộ\n- Đo đạc, đánh giá, phân tích các số liệu quy trình, chất lượng, tiến độ dự án; từ đó đưa ra các nguy cơ , xu hướng, vấn đề và đề xuất quy trình, chất lượng\n- Quản lý nhân sự QA, đào tạo và định hướng công việc cho nhân sự QA\n- Định hướng công cụ ứng dụng đảm bảo Quản lý chất lượng bao gồm yêu cầu phát triển công cụ và các công cụ thương mại như Jira, SVN, Power BI...\n\nYour skills and experience\n- Tốt nghiệp đại học về các lĩnh vực Công nghệ thông tin, Điện tử viễn thông\n- Ít nhất 5 năm kinh nghiệm tại vị trí QA (Quality Assurance) trong lĩnh vực phát triển phần mềm, trong đó ít nhất 3 năm ở vị trí quản lý\n- Đã tham gia triển khai ít nhất 1 trong các tiêu chuẩn CMMi, ISO\n- Có khả năng tìm hiểu, nghiên cứu để làm chủ/ triển khai áp dụng các quy trình quản lý sản xuất tại đơn vị như Agile, CICD\n- Đọc hiểu tài liệu tiếng Anh tốt, giao tiếp ở mức cơ bản\n- Ưu tiên có các chứng chỉ quốc tế liên quan như PSM, CSQA, Lead Auditor...\n- Ưu tiên có thêm kinh nghiệm quản lý nhóm CSKH, tiếp nhận phản ánh CNTT\n- Tư vấn bất cứ vùng quy trình nào theo mô hình tổ chức đơn vị và yêu cầu SLA\n- Phân tích, thẩm định số liệu chất lượng\n- Sử dụng thành thạo các công cụ, phần mềm của công ty ( Microsoft, Dashboard, Power BI, Confluence, Jira, SVN...) \n\nWhy you\'ll love working here\n1. Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh thỏa thuận theo kinh nghiệm và năng lực.\n- Lương tháng 13, Thưởng quý, Thưởng dự án, Thưởng năng suất.\n- Nghỉ mát, thưởng ngày lễ và các ngày chỉ có ở Viettel như Ngày Sáng Tạo - 1/6, 22/12, quà Tết Dương, Tết Âm tri ân Gia đình, người sinh thành (25-30 triệu/năm)\n- 16 ngày nghỉ phép/năm hưởng nguyên lương\n- Bảo hiểm sức khỏe Pijico, bảo hiểm sức khỏe cho người thân, bảo hiểm nhân thọ,…\n- Hưởng các Chính sách đãi ngộ toàn diện của \'Người Viettel\'\n\n2. Cơ hội phát triển bản thân\n- Cơ hội thăng tiến không giới hạn, trở thành quản lý của các dự án mới\n- Được thử sức với các công nghêm mới, dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội được đào tạo, trau dồi kĩ năng, chuyên môn để phát triển toàn diện.\n\n3. Môi trường làm việc\n- Được làm việc trong Tập đoàn toàn cầu, tiên phong thực hiện sứ mệnh kiến tạo xã hội số.\n- Môi trường mở, trẻ trung, năng động, trân trọng, yêu thương, tương hỗ & lắng nghe mỗi người từ những ý tưởng nhỏ nhất.\n- Không gian làm việc xanh, mở, hiện đại.\n\n4. Địa điểm làm việc\n- Tòa nhà Thành Công, 80 Dịch Vọng Hậu, Cầu Giấy, Hà Nội\n- Thời gian làm việc: Thứ 2 đến thứ 6', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '36A Dịch Vọng Hậu, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(799, 476, 2, 'Mid/Senior QA/QC Engineer (Manual or Hybrid)', 'Welcome to SMG Vietnam!\n\nSMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nYour Mission :\nThis job refers to our Automotive brands, and . We are journeying to simplify our products and strengthen our technology stack through a large-scale rewrite. We’re building on a modern technology stack with Java, following best practices, and striving to build/measure/learn at a high cadence. Join our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nSpecifically, you will work on:\n- Work as part of an agile team:\n  - Be the voice of QA during agile ceremonies. Autonomously drive the testing life cycle to ensure quality from medium to large size features while reducing the system\'s tech debt or legacy issues in assigned projects\n  - Collaborate with agile teams to ship valuable product increments.\n  - Actively participate in ticket refinement/grooming by bringing up unforeseen scenarios and use cases.\n\n- Perform thorough functionality tests:\n  - Review acceptance criteria, developer notes, and design documents to formulate test cases.\n  - Test domain-driven web referencing database-heavy back-end systems and check the consistency across devices, browsers, and operating systems.\n  - Conduct periodic exploratory testing in test environments.\n\n- Be responsible for product quality:\n  - Work with the engineering teams to derive testing requirements throughout the development cycle.\n  - Provide inputs on high-level test scenarios, challenges, risks, resources, test estimates, etc., during test planning meetings.\n\n- Support Bug Triage process:\n  - Reproduces bugs and isolates problems and verifies fixes.\n  - Report any bugs/defects found in a clear, friendly, and easily reproducible manner.\n  - Keep track of incidents, does deep root cause analysis followed by recommended action items.\n  - Track defects and helps troubleshoot errors.\n\nYour skills and experience\nWhat will you bring to the ride?\n- 4+ years’ experience in the same role.\n- Good hands-on experience in:\n  - API testing using Postman for REST-based designs.\n  - Testing UI responsive web application (preferably React).\n  - Database testing (e.g., SQL, PostgreSQL).\n- A pragmatic and proactive approach to problem-solving.\n- A strong sense of ownership and accountability for the product’s quality.\n- Familiarity with Agile methodologies and an Agile mindset.\n- Willing to take on new challenges proactively.\n\nNice-to-Have Qualifications:\n- Understanding of automation testing concepts or ability to do automation testing (e.g., Cypress).\n- Basic scripting skills (e.g., JavaScript).\n- Experience with mobile testing (iOS and/or Android).\n- Familiarity with security testing principles.\n\nWe value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique.\n\nWhy you\'ll love working here\n- Attractive salary you’ll love!!!\n- Full salary in probation\n- 13th-month bonus, Annual bonus from Profit Growth Sharing Plan\n- 21+ annual paid days off\n- 24 paid days equivalent per year for learning & knowledge sharing activities\n- Full contribution to social insurance\n- Premium private insurances coverage for you and your family members\n- Personal development plan and yearly budget for educational courses, and conferences, aiming to grow both your soft and hard skills\n- Clear Career Growth Framework and Supports\n- Assistance and support through all aspects of the onboarding process\n- Lots of team activities and regular Hackathons\n- Annual Trips to Switzerland and other European countries\n- Flexible working time\n- Hybrid working model (home office and in-office)\n- 40 hours per week, Mon-Fri, No OT\n- Modern Macbook laptops\n- Free food, Sports Clubs, Monthly Townhall and frequent engagement activities\n- Work in an open-minded, friendly, positive, transparent, and agile environment.\n\nAPPLY NOW, SO A GREAT CAREER OPPORTUNITY WON\'T BE MISSED!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Tower, 285 CMT8, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(800, 491, 2, 'QA Engineer', 'You will begin working in our Ho Chi Minh City office on a state-of-the-art AI application. All of your work will be conducted in English, including daily meetings where you are expected to raise concerns and understand complex issues so that you can explain them to others. You will stay at the forefront of internet application development and will have frequent opportunities to learn new technologies.\n\nWhat You’ll Do\n- Collaborate with product managers and designers to understand their objectives.\n- Write automated tests for AI web and mobile applications.\n- Run test suites, analyze failures, and escalate issues to the development team.\n- Help other developers replicate and debug issues.\n- Understand user psychology and experience, as well as how users interact with AI applications.\n\nWhat We’re Looking For\nExperience:\n- At least one year of commercial experience working with AI web and mobile applications.\n\nTechnical Skills:\n- Excellent logical skills.\n- Strong attention to visual and process details.\n- Good programming skills in languages such as Ruby, Python, or JavaScript.\n- Understanding of HTML and CSS selectors.\n- Good knowledge of UX/UI best practices.\n- Familiarity with Unix, including Mac OS X or Linux command line.\n- Preferably experience working with large international engineering teams.\n- Preferably experience with testing tools such as Selenium, Robot Framework, Appium, or similar.\n- Preferably experience working in an agile development environment with automated tests and SCRUM processes.\n\nCommunication:\n- Excellent verbal and written English communication skills.\n- Willing to work closely and continuously with programmers, developers, and product managers.\n\nEducation:\n- A degree from a reputable Vietnamese or foreign university is preferred.\n\nWhat We Offer\n- Competitive Compensation: High salary, depending on experience and capabilities.\n- Bonuses & Benefits: End-of-year Tet bonus, Comprehensive health insurance, 15 days of annual leave, A balanced 40-hour workweek with flexible hours.\n- Professional Growth: Continuous learning opportunities such as internal workshops and industry conferences, A collaborative, dynamic work environment that fosters innovation and creativity.\n- Work Environment: A vibrant, modern office space in Ho Chi Minh City.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '16 Tam Dao, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(801, 258, 2, 'VTS - Software Tester (QA QC/ SQL)', 'Gia nhập “vũ trụ” công nghệ Viettel, nơi bạn không chỉ được “đắm chìm” trong hàng loạt công nghệ xịn xò như Big Data, AI, IoT, AR/VR, Cloud, Blockchain… mà còn được trao cơ hội thực hiện sứ mệnh quan trọng: “Chung tay cùng Chính phủ kiến tạo – Chính phủ số”, đồng hành với doanh nghiệp và người dân giải quyết các vấn đề cấp bách của xã hội, hướng tới một cuộc sống tốt đẹp hơn cho mọi người.\n\nTại VTS (Tổng Công ty Giải pháp Doanh nghiệp Viettel), bạn sẽ được hiện thực hóa những ý tưởng táo bạo, tham gia vào các dự án công nghệ hàng đầu và phát triển giải pháp đột phá cho tương lai số. Đây chính là nơi khơi dậy đam mê, thúc đẩy sáng tạo và chắp cánh cho mọi ước mơ công nghệ của bạn. Sẵn sàng trở thành “ngôi sao sáng” trên hành trình chuyển đổi số và cùng Viettel tạo nên dấu ấn trong cuộc cách mạng công nghiệp 4.0? Let’s go!\n\nBạn sẽ làm gì?\n- Lập kế hoạch, kịch bản và thực hiện kiểm thử\n  * Tìm hiểu, làm rõ tài liệu giải pháp các chức năng phức tạp để phân tích và lựa chọn phương pháp/công cụ/ framework kiểm thử (kiểm thử thủ công/tự động)\n  * Viết kịch bản kiểm thử các chức năng phức tạp (theo hướng dẫn ULNL)\n  * Chuẩn bị đủ dữ liệu test cho chức năng cần kiểm thử\n  * Thực hiện kiểm thử độc lập theo kịch bản.\n- Phân tích và báo cáo kiểm thử\n  * Báo cáo kết quả, tiến độ kiểm thử sản phẩm\n  * Viết tài liệu HDSD theo yêu cầu, đào tạo & hướng dẫn người dùng.\n\nYour skills and experience\n- Bằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng, hoặc các chuyên ngành Kỹ thuật khác liên quan.\n- Ngoại ngữ: Đọc hiểu tài liệu tiếng Anh ngon lành. Ưu tiên có chứng chỉ TOEIC 550+ (hoặc IELTS, TOEFL tương đương).\n- Kiến thức, kinh nghiệm:\n  * Kiến thức về SQL nâng cao\n  * Nắm vững nghiệp vụ hệ thống trong mảng sản phẩm liên quan\n  * Sử dụng thành thạo các công cụ quản lý cấu hình lỗi\n  * Sử dụng thành thạo tin học văn phòng\n  * Có khả năng phân tích và trao đổi về yêu cầu.\n\nTinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội.\n\nWhy you\'ll love working here\n- Lương cạnh tranh: Thu nhập “ổn áp”, xứng đáng với năng lực và kinh nghiệm.\n- Đầy đủ các khoản thưởng: Thưởng lễ Tết, quà tặng, du lịch nghỉ mát, hỗ trợ ăn trưa, cước điện thoại…\n- Nghỉ phép linh hoạt: 12 ngày phép + 3 ngày nghỉ mát + 1 ngày sáng tạo mỗi năm.\n- Bảo hiểm toàn diện: Hưởng đầy đủ BHXH, BHYT, BHTN theo quy định, cộng thêm gói bảo hiểm riêng từ Viettel.\n- Môi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo “bung nóc”.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Tran Huu Duc, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(802, 255, 2, 'Senior Product Designer', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.  \nJob Description:  \nWe are seeking a Senior Product Designer to join our product development team of creative technologists and problem-solvers. This role focuses on crafting visually compelling marketing assets and intuitive digital products, with an emphasis on end-to-end visual and UI/UX design for websites, landing pages, and SaaS applications (e.g., payment portals and dashboards). The ideal candidate is a forward-thinking designer eager to explore modern design trends and tools.  \nCore Responsibilities:  \nDeliver complete design solutions including conceptual web design, landing pages, UI elements, and sales decks.\nMaintain visual consistency across products and channels while aligning with brand standards.\nLead ideation, whiteboarding, and collaborative sessions to define creative concepts.\nWork closely with cross-functional teams to ensure designs meet quality and timeline expectations.\nPresent designs clearly to internal and global teams in English.\nManage multiple design tasks effectively in a fast-paced environment.  \nYour skills and experience  \nTechnical Skills:  \n7+ years of experience in graphic/visual, UI/UX, and product design.\nStrong marketing and website design background, ideally from agency companies.\nProficiency in Figma and hands-on experiences with Adobe Creative Cloud (Photoshop, Illustrator, After Effects...).\nExperience using AI tools to support design processes and boost productivity, such as automating repetitive tasks or enhancing creative output.\nAbility to create clean, user-focused designs with strong attention to visual detail.\nFamiliarity with the SAFe Agile methodology.\nIndependent, proactive, and solution-driven mindset.\nComfortable working under pressure with tight deadlines.\nGood English communication and presentation skills.\nPortfolio Requirement:  \nA strong portfolio showcasing relevant visual, UI/UX and product design work is required.  \nThings That Will Separate You From The Rest:  \nHave basic knowledge of HTML/CSS/JavaScript for smooth development handoff.\nHands-on experience with Canva, Webflow or other no-code web design platforms.\nSkills in motion graphics or basic video editing.  \nEducation or Certifications:  \nBachelor’s degree in Graphic Design, or related field  \nJob Type:  \nFull-time (Hybrid)  \nSchedule:  \nMonday to Friday  \nWhy you\'ll love working here  \nHighly competitive salary  \nFull salary for probation & full coverage of social insurance.\nPremium healthcare for you and your beloved one.\nMonthly childcare support\n13th-month salary.\nAnnual Leave: 15 days; Paternity Leave: 6 weeks, Bereavement leave: 10 days.\nFlexible working time, focus on output (no checking time attendance)\nVarious active sporty clubs: Football, Billiards, Badminton, E-sport clubs\nFrequent opportunities to travel to US headquarter from 3-6 months.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Six8 Building: 24-26 Phan Dinh Giot Street, Tan Binh District, HCMC., Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(803, 538, 2, 'Java Developer (Spring, Spring Boot, Spring MVC)', 'We are looking for a Java Developer with solid experience in developing scalable web applications using Java EE, Spring Framework, and Spring Boot. The ideal candidate will have hands-on experience with JSP, Servlets, MyBatis, Themeleaf and strong SQL skills for working with relational databases including MySQL, Oracle, and PostgreSQL.\n\nKey responsibilities:\n- Maintain web applications using Java, Spring, Spring Boot, Themeleaf, JSP, and Servlets.\n- Develop RESTful APIs and backend services with Spring Boot.\n- Integrate MyBatis for data persistence and SQL mapping.\n- Write and optimize complex SQL queries for MySQL, Oracle, and PostgreSQL\n- Collaborate with the publisher to implement the front-end\n- Collaborate with BA to analyze requirements, best practices for solutions\n- Write unit and integration tests for both the frontend and backend before deployment\n\nRequired Skills & Qualifications:\n- Strong proficiency in Java, Java Web\n- Hands-on experience with Spring, Spring Boot, Spring MVC.\n- Good understanding and practical use of Spring JPA, MyBatis \n- Experience with MySQL, Oracle, and PostgreSQL databases.\n- Familiarity with REST APIs, JSON, and XML.\n- Proficient with build tools such as Maven, Gradle, Ant.\n- Experience with version control systems like Git.\n- Solid understanding of object-oriented design and design patterns.\n- Ability to clearly communicate with both technical and non-technical team members\n- Good attitude: Collaboration, teamwork, unity for common goals (provide customer satisfaction), long-term plan.\n\nPreferred Qualifications:\n- Experience with JUnit, Mockito or other testing frameworks.\n- Familiarity with DevOps CI/CD pipelines is a plus.\n- Experience in ArgoCD, K8s\n- Experience with Agile Scrum\n\nWhy you\'ll love working here:\n- Attractive salary\n- Global standard working environment\n- 100% salary during probation period\n- 13th-month salary (based on Company\'s business performance)\n- Birthday Bonus, New Year Bonus \n- Social Insurance, health insurance, unemployment insurance after probation \n- Health Check \n- Training & development opportunities\n- Laptop and PC for everyone\n- Flexible to adjust working hours (e.g., 8:30 AM – 5:30 PM or 1:00 PM – 9:00 PM as needed)\n\nAbout MEGAZONE CLOUD:\nMEGAZONE CLOUD (MZC), headquartered in Seoul, South Korea, emerged from Megazone Corporation’s cloud business with substantial investment support (Series A, B, and C). Since 2018, MZC has been dedicated to empowering enterprises through cloud-based platforms, helping them achieve digital transformation and innovation. With a robust partnership with Amazon Web Services, MZC delivers comprehensive consulting services and technology solutions globally, serving over 3,700 clients including leading Korean enterprises like Samsung, LG, and Lotte Group. Beyond Korea, MZC has established offices in Hong Kong, Palo Alto, Japan, and Hanoi, actively expanding its global footprint.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(804, 539, 2, 'HCM - Mid/Sr Java Dev (English, Spring, Oracle, JSP)', 'Top 3 reasons to join us\n- Thỏa sức phát triển trong môi trường năng động\n- Thời gian check-in linh hoạt\n- Chế độ phúc lợi toàn diện \n\nJob description\n- Work as software developer on the web-based application product in JAVA- related and open-source technologies\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project development with high quality.\n- Participate in all phases of the development cycle.\n- Actively join planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n- Respond to and resolve IT support requests from employees via phone, email, or service request system\n\nYour skills and experience\nREQUIRED SKILLS AND EXPERIENCE\n- Good command of English (both written/verbal) is essential\n- 5+ years of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend\n- Able to analyze, design, develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner)\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc.\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications\n- Solid understanding of OOP, design patterns, and coding standards\n\nPREFERRED QUALIFICATIONS\nExperience with:\n- AWS\n- MS .Net / .Net Core\n- Kubernetes\n- React.js\n- Nginx\n- JUnit\n- Jasper Report\n- ElasticSearch & Kibana (ELK)\n- Grafana\n- Prometheus (monitoring/alerts)\n\nWhy you\'ll love working here\n- Probation salary is 100% of official salary\n- 13th-month salary and performance review twice a year\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n- Project Bonus\n- IT Certificate allowance\n- Health Care Insurance\n- Social, health and unemployment Insurance following Government policy\n- Enjoy company summer trips and other team building activities held  monthly and quarterly\n- Work five days per week with flexible check-in time\n- Professional, creative and dynamic working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, Tòa Luxhome Điện Biên Phủ 607 Điện Biên Phủ, Phường 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(805, 448, 2, 'Senior QC Manual Engineer', 'Job description\nParticipate in reviewing and analyzing the project requirements to understand test objectives and provide input on the testability of requirements and estimation for the testing activities.\nParticipate in client meetings to ensure that engagement work products and deliverables are of the highest quality.\nAssist in the planning, creating, and controlling the test environment(s).\nDevelop the test plan and test strategy for the project.\nWrite and execute the test cases for the web and mobile applications.\nExecute the test and report defects.\nMonitor defects and follow-up actions in the defect tracking system.\nEnsure all test-related work is carried out per the defined standards and procedures.\nTransfer knowledge, monitor engagement team performance, and provide feedback on the team.\nMonitor and coach QCs in the project.\nTo perform other tasks assigned by the Line Manager and Project Manager.\nYour skills and experience\nUniversity level with bachelor’s degree in computer science or equivalent.\nGood experience in software testing for web and mobile applications.\nGood knowledge of automation tests, performance tests, and security tests.\nHave 5+ years of experience in software testing.\nGood verbal and written communication skills in English.\nAnalytical mind and problem-solving aptitude.\nHave a proactive and good working relationship with other team members.\nAble to manage a team of 3+ people.\nExperience with agile/scrum methodology.\nWhy you\'ll love working here\nWhy you\'ll love working here\nProfessional and flexible working environment\nFast-track career development opportunities\nCompetitive compensation package\n13th-month salary\nPerformance bonus\nMacbook Pro M4/ Dell Latitude Ultra 7 provided\nRecognition rewards for outstanding performers\nFull social, health, and insurance coverage\nHealthcare: Annual health check-up, Health Insurance\nAnnual leaves: 14 days\nActive company clubs and social activities\nComprehensive training: Technical skills, Soft skills, English', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24F Deutsches Haus - 33 Le Duan Street, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(806, 540, 2, 'Security Operations Engineer - DevSecOps', 'Are you passionate about cybersecurity and ready to take a hands-on role in driving the evolution of our security operations? As a Medior/Senior Security Operations Engineer - DevSecOps at Aurify, you’ll play a pivotal role in building and refining our Google Security Operations Center (SOC), with a specific focus on SIEM and SOAR automation.\n\nYou will be part of our Security Operations team, responsible for monitoring and escalating security alerts across our infrastructure and implementing cutting-edge security procedures. This role goes beyond production security—it encompasses securing our internal systems and processes. We’re looking for someone with both practical and theoretical knowledge in IT security, capable of not only enforcing policies but also continuously improving them to meet evolving security challenges.\n\nWhat you’ll be doing \n- Building and optimizing our Google SOC, including SIEM and SOAR implementation (Google Chronicle)\n- Automation of the Security operation processes by using DevSecOps principles\n- Monitoring, analyzing, and escalating security alerts from our Google Chronicle SIEM\n- Developing, evolving, and enforcing security policies and incident response plans\n- Driving the creation of SIEM dashboards and enhancing monitoring and alerting capabilities\n- Managing and mitigating CVE vulnerabilities on our platforms and base images\n- Assisting with the implementation of security measures for both external and internal systems\n- Implementing and automating static code scanning processes to identify and remediate vulnerabilities early in the development lifecycle\n- Leading efforts in automated security scanning for continuous monitoring of code and infrastructure security\n- Participating in the on-call security response rotation to handle critical security incidents\n\nYour skills and experience\nRequirements\n- Hands-on experience with SIEM (preferably Google Chronicle) and SOAR solutions\n- Strong knowledge of CVE management and experience with vulnerability mitigation\n- Solid understanding of cloud security (GCP and/or AWS)\n- Knowledge of container security (Docker, Anchore)\n- Practical experience in developing and implementing security policies and incident response plans\n- Strong command of English (both written and spoken)\n- Ability to collaborate effectively with cross-functional teams\n- Experience with Linux systems (RedHat/CentOS) and using Jira for project management\n\nNice To Have\n- Experience with OSSECC, Wazuh, Tenable.io, Burpsuite, Cloudsuite\n- Familiarity with Ansible, Opsgenie, and Prometheus\n- Experience with patch management solutions such as Katello/Satellite\n- Experience in automation with Python \n- A keen focus on real-world security issues and the ability to differentiate between buzz and practical security\n\nSoft skills \n- Excellent communication skills to work constructive and in cooperation with internal and external teams\n- Be assertive, knowledgeable and trustworthy\n- High degree of responsibility and autonomy\n\nWhy you\'ll love working here\n- Office hours: 9:00 AM 🡪 12:00 PM, 1:00 PM 🡪 06:00 PM, off on Saturday and Sunday. Annual holidays leave will be following Vietnam law and as company regulations.\n- 25 days of annual leave\n- Flexible working hours\n- Competitive remuneration package\n- 13th salary\n- Social insurance, health insurance, and unemployment insurance will be under Labor Law.\n- Generous private medical health insurance for employees & family members\n- Dynamic, young & international environment\n- Team building activities & outing\n- Brand new & state-of-the-art Agile office\n- Opportunity for traveling & training in Europe.\n\nAs a member of the Aurify team, you\'ll have the unique opportunity to work on projects that integrate state-of-the-art technologies with a customer-centric approach. You\'ll be at the forefront of implementing practices that ensure cost management and security compliance, all within a framework that values simplicity and smart solutions, echoing the mission of Unifiedpost. Join us in our journey to navigate the complexities of the cloud landscape together, providing peace of mind and empowering businesses to focus on their core activities with the assurance of performance, high availability, and security excellence.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 28, tòa nhà Opal, số 92 Nguyễn Hữu Cảnh, Phường 22, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(807, 541, 2, 'Senior Frontend Developer (ReactJS/Redux, UX, WebGPU)', 'Role Description\nWe are seeking a talented Senior Front End Developer to join our team and create user-friendly and responsive web interfaces for BioTuring\'s bioinformatics platforms.\n\nKey Responsibilities\n- Architect, design, and implement high-performance, user-friendly frontend for multiple data intensive applications, one of them is similar to Google Earth-like product - but for exploring the biological universe.\n- Maintain and enhance the current frontend codebase using modern frameworks and tools.\n- Collaborate with UX/UI designers to implement user-friendly interfaces and reusable frontend libraries.\n- Collaborate with Back-end developers to come up with solutions with speed and scalability.\n\nYour skills and experience\n- Excellent problem-solving skills and attention to detail.\n- Minimum 5 years of experience in Front end developer or relevant positions.\n- Strong UX design sense\n- Previous experience in a lead role\n- Experience in web application performance tuning, React/Redux applications.\n- Experience with geospatial visualizations and interactive maps for large data using libraries such as WebGL, Three.js, WebGPU.\n- Previous experience in a startup or agile development environment.\n\nWhy you\'ll love working here\n- Competitive salary and benefits package.\n- A collaborative and supportive work environment.\n- Challenging computational problems with enormous chances to learn and grow your career in a rapidly evolving field.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '4th Floor, tower A Thao Dien Pearl, 12 Quoc Huong Str., Thao Dien ward, dist 2, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(808, 517, 2, 'Senior Frontend Software Engineer', 'Koidra is at the forefront of climate tech innovation, offering intelligent automation solutions that enable high-tech greenhouses, biomass energy facilities, and food processing plants to excel in both sustainability and production efficiency. We are dedicated to helping these industries reduce their environmental impact while maximizing operational effectiveness.\nBy integrating advanced machine learning, IoT technologies, and principles from Math and Physics, our systems extend the precision and efficiency of operations beyond what\'s possible through human efforts alone. Koidra\'s smart automation empowers facilities to broaden their control, minimize reliance on manual expertise, and embrace a scalable approach to environmental responsibility in industrial automation.\n\nImplement responsive and intuitive UI for our products\nBuild efficient and reusable front-end systems and abstraction\nAnalyze and enhance application for maximum performance\nCollaborate with UI/UX designers to iterate on design and implementation\nCollaborate with backend engineers to effectively build features and ship experiments\nPractice disciplined software engineering (e.g. automated testing, code reviews, …)\nSupport, share knowledge and grow junior team members\n\n5 years of industry experience in a front-end engineering role\nProficient understanding of TypeScript and modern frontend stacks such as Vue.JS or React.JS\nExperience in system design and system optimization\nExperience collaborating directly with product team members\nProficient understanding of cross-browser compatibility to help long term maintenance\nYou find yourself fit our culture\n\nAt Koidra, you\'ll have an opportunity to work with world experts in Machine Learning and Software Engineering.\n\nOther benefits\n✅ Competitive compensation in a fast-growing startup\n✅ Lunch and refreshment allowance\n✅ Private health insurance\n✅ Workstation provided for maximum productivity: Thinkpad laptop, 24\' Ultrasharp Monitor (can request a larger one), excellent keyboard/mouse, etc.\n✅ Active and agile working environment; flexible time culture\n✅ Opportunity to impact the company (and hence the global stage) in big ways', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '8-10 Tạ Hiện, P. Thạnh Mỹ Lợi, TP. Thủ Đức, TP. HCM, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(809, 542, 2, 'Odoo Developer', 'About the role\nAs an Odoo Developer, you will take full ownership of building and customizing Odoo ERP modules that meet the company’s operational and strategic goals. You will collaborate closely with business stakeholders, other developers, and IT infrastructure teams to ensure robust, scalable, and well-integrated solutions.\n\nAccountabilities\n• Develop, customize, and maintain Odoo modules in accordance with project requirements.\n• Analyze user needs and deliver scalable Odoo applications tailored to business workflows.\n• Troubleshoot, debug, and upgrade existing Odoo systems.\n• Collaborate with users and team members to gather and refine specifications.\n• Integrate Odoo with third-party tools using RESTful APIs.\n• Write technical documentation and provide end-user training where needed.\n• Ensure code quality, security, and performance best practices are followed.\n\nYour skills and experience\n• 5+ years of hands-on experience with Odoo (v13 or newer).\n• Proficient in Python with solid understanding of Odoo framework internals.\n• Strong knowledge of PostgreSQL, XML, and ORM techniques.\n• Experience integrating Odoo with other systems via RESTful APIs.\n• Familiarity with Linux-based deployment and system administration.\n• Experience with Git and collaborative development workflows.\n• Strong analytical and problem-solving skills.\n• Excellent communication skills and the ability to translate business needs into technical specifications.\n• Based in HCMC or Danang, Vietnam\n\nWhy you\'ll love working here\nAt Lovepop, we are committed to creating an environment where employees feel valued, supported, and empowered to grow. Our benefits package includes:\nLeave Policy\nAnnual leave increases with seniority and job level. Employees earn 1 additional day of leave every 3 years of service. We also observe the U.S. Independence Day holiday.\nAllowances and Bonuses\nMeal allowance, transportation allowance, housing allowance, childcare allowance, mobile phone allowance, compliance allowance, perfect attendance bonus, 13th-month salary, and performance-based bonuses.\nInsurance Coverage\nFull social insurance contributions based on actual salary. In addition, we offer health insurance and private health coverage for employees and up to 2 family members (depending on level).\nLearning and Development\nAnnual programs for professional skills training and soft skills development to support your career growth.\nConvenient Location\nOur modern office is located in the heart of the city.\nCSR Programs\nAnnual charity, education support, and community engagement programs to give back and make a difference.\nEngagement Activities\nSports Day, Teambuilding events, Gala Dinner, and more fun activities to strengthen team spirit.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Room 18A, Level 18, The Nexus (Nguyen Sieu gate), 3A-3B Ton Duc Thang Boulevard, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(810, 205, 2, 'QA Fullstack/Automation (Product experience required)', 'QA Engineer (Fullstack)  At LeapXpert, we\'re revolutionizing business communication by seamlessly integrating the familiarity of consumer messaging apps with enterprise-grade security and compliance.  As pioneers in responsible business communications, we empower employees and clients to connect through their preferred messaging platforms while upholding the highest standards of governance and security.  Our mission is to transform workplace communication globally.  We\'ve been recognized as a Visionary in Gartner\'s Magic Quadrant for Digital Communications Governance and Archiving Solutions, raised a $20 million Series B funding round—bringing our total funding to $60 million, and earned the trust of top-tier institutions worldwide, who rely on our platform daily to streamline client communications.  This is just the beginning—we\'re growing rapidly and we\'re seeking passionate, talented individuals to join our team.  This is your opportunity to work on impactful projects using cutting-edge technologies alongside driven innovators from around the world.  Apply now to be part of something revolutionary!  We\'re looking for a QA Engineer (Fullstack) who is responsible for testing and ensuring excellent, commercial-grade quality of our software products and services, as well as coordinating with the teams responsible for other layers of the product infrastructure.  Building a product is a highly collaborative effort, and as such, a strong team player with a commitment to perfection is required. Responsibilities:  Develop, maintain and execute both manual and automation test cases for major projects, maintenance, and emergency releases  Design and implement automation tests scripts, debug and define corrective actions  Identify, analyze and report test results  Report, track, and monitor defects in the defect tracking system  Investigate defect reports from production support, isolate their causes, inform development teams for fixing and retest to ensure adequate resolutions.  Prepare test documents and review with development teams when necessary  Work closely with the engineering and development teams to design testing strategies  Work on the interpretation of quality assurance issues and problems for technical and non-technical users  Your skills and experience  3+ years of work experience as a QA Engineer, strong in automation testing.  Good experience in automation testing for web-based and mobile applications with Selenium, Appium using JavaScript/NodeJS  Experience using tools like Codeceptjs, Cloud device, Device farm  Experience in testing with Python  Good English communication  Experience in testing big data (data migration, ETL, data modeling...)  Good experience in writing new test cases based on requirements  Ability to effectively manage time, and arrange and carry out multiple tasks of different priorities  Experience in developing, documenting and implementing quality assurance standards  Experience with cross-browser, cross-platform and responsive testing (PC and mobile)  Willing to learn and adopt new technologies and testing methodologies  Good knowledge of testing methodology and tools, experience with Agile methodology is a plus  Familiar with BDD  Experience in testing API’s and Web Services Ability  Familiar with Performance Testing: Jmeter  Experience with Docker is a plus  Experience with Security Testing is a plus  Familiar with Git, Github  Good understanding on CI / CD: Circle/ Jenkins…. etc.  Experience of Android and iOS development. Strong experience on one platform over the other is a plus.  Why you\'ll love working here  You are looking for:  An awesome job opportunity with an attractive remuneration package  Working on site with a stylish and comfortable environment.  Friendly coworkers who support each other to win together as a team.  Working in a team that encourages AI adoption, experimenting with and learning new AI tools to enhance the developer experience.  A flat, product-focused organization and Agile teams that allow you to bring value and ideas to the product and the company  Opportunities to learn and be trained in new technologies and methodologies  Facing new and innovative challenges to deliver a commercial-grade, world-class product  Career growth in multiple directions, based on your preferences and abilities  Benefits:  13th Salary, paid pro-rata, every month to allow more flexible financial plans  18 annual leaves and 1 birthday leave   Full salary on probation   Full social insurance according to Vietnam Labor Law   Premium Health Care Insurance   Annual health check   Lunch and parking allowances   Team building, fun monthly, quarterly activities and so much more fun are waiting for you!  Relax with Tabletop foosball, PlayStation, massage chair in the office   Annual Performance Review   Attractive career path   Advanced technical solutions, Agile culture and the opportunity to work with the latest technologies  Sounds like a good fit? Come and join the team at LeapXpert!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '195/10E Dien Bien Phu, Ward 15, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(811, 378, 2, 'Game Developer (Unity, C#)', 'Top 3 reasons to join us\n- MacBook Pro/Extra screens & Remote Work policy\n- Premium health insurance package for you, relative\n- Company Trip 4-5*, Yoga, Gym/Fitness/English club\n\nJob description\n- Plan and develop mobile game projects on the Unity platform.\n- Implement and optimize new features based on game designs provided by the planning team.\n- Collaborate with backend developers to ensure smooth, efficient end-to-end connectivity with the server.\n- Establish and maintain robust development pipelines and workflows.\n- Write clean, efficient, and reusable code following the company’s coding standards and MVC Design Pattern.\n- Conduct performance optimization to ensure games run smoothly across devices.\n- Identify and resolve technical bottlenecks, bugs, or other issues promptly.\n- Design and implement game patches, updates, and WhiteBox testing processes to ensure product quality.\n- Maintain high industry standards for all projects.\n\nYour skills and experience\nKNOWLEDGE:\n- Solid understanding of Unity, including its ecosystem and advanced features.\n- Proficiency in scripting (C#), textures, animations, GUI styles, and user session management.\n- Strong understanding of mobile game development workflows and optimization techniques.\n- Experience with server integration, REST APIs, and end-to-end connectivity (e.g., integrating client-side Unity projects with server-side APIs).\n- Knowledge of memory management and space optimization for mobile devices.\n- Familiarity with automated testing platforms, unit testing, and debugging tools.\n- Proficiency with version control systems (e.g., Git, SVN, Mercurial).\n- Familiarity with Scrum Agile methodology and full-stack game development is a plus.\n\nSKILL:\n- Proficient in Unity and C#.\n- 5+ years of experience as a Unity/Unity3D Developer.\n- 5+ years of experience with MVC Design Pattern in game development.\n- Strong analytical skills and ability to troubleshoot and resolve complex technical issues.\n- Good communication skills in English for effective collaboration with international teams.\n\nABILITY:\n- Open-minded and eager to learn new technologies or concepts.\n- Reliable, proactive, and highly detail-oriented.\n- Strong problem-solving mindset and ability to work independently.\n- Excellent teamwork and work ethic.\n\nWhy you\'ll love working here\n- Great facility to work. You will have a MacBook and extra high-definition screens\n- Premium health insurance package and annual medical check-up\n- Sponsorship for training courses\n- Interesting activities: gym/fitness club at work, English club, corporate social responsibility events...\n- Attractive signing bonus for important positions\n- With regular discussions with the CEO, founders, and executives of the company, you will have a lot of opportunities to learn from experts in their fields\n- Annual bonus and project bonus\n- International opportunity to expose and grow\n- At least one abroad travels every year. We often send our elites to international conferences like GDC, WWDC, Google I/O... to update the latest technology\n- Full labor insurance (social, health, unemployed)\n- Annual leave 12 days / sick leave 2 days / remote work 12 days\n- Free food & drinks, kitchen at work, PlayStation after work\n- Friday evening party, happy hour, team activities, and awesome parties…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '40A Lam Sơn, Phường 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(812, 258, 2, 'VTS - Kỹ Sư Phát Triển ứng dụng Mobile (Flutter/Java)', 'Gia nhập “vũ trụ” công nghệ Viettel, nơi bạn không chỉ được “đắm chìm” trong hàng loạt công nghệ xịn xò như Big Data, AI, IoT, AR/VR, Cloud, Blockchain… mà còn được trao cơ hội thực hiện sứ mệnh quan trọng: “Chung tay cùng Chính phủ kiến tạo – Chính phủ số”, đồng hành với doanh nghiệp và người dân giải quyết các vấn đề cấp bách của xã hội, hướng tới một cuộc sống tốt đẹp hơn cho mọi người.\n\nTại VTS (Tổng Công ty Giải pháp Doanh nghiệp Viettel), bạn sẽ được hiện thực hóa những ý tưởng táo bạo, tham gia vào các dự án công nghệ hàng đầu và phát triển giải pháp đột phá cho tương lai số. Đây chính là nơi khơi dậy đam mê, thúc đẩy sáng tạo và chắp cánh cho mọi ước mơ công nghệ của bạn. Sẵn sàng trở thành “ngôi sao sáng” trên hành trình chuyển đổi số và cùng Viettel tạo nên dấu ấn trong cuộc cách mạng công nghiệp 4.0? Let’s go!\n\n“Phù Thủy Code Di Động” – Kỹ Sư Phát Triển ứng dụng Mobile\n\nBạn sẽ làm gì?\n- Xây dựng kiến trúc ứng dụng mobile (iOS/Android/Hybrid) dựa trên nền tảng UI/UX hấp dẫn người dùng, đáp ứng tốt các yêu cầu về hiệu năng và bảo mật.\n- “Hô biến” ý tưởng thành những tính năng “xịn sò”, từ màn hình đăng nhập “mượt mà” đến tích hợp API, Cloud service (Firebase, AWS, Azure…) thông minh.\n- Tối ưu tài nguyên, xử lý concurrency, “chăm sóc” hiệu năng để app hoạt động trơn tru, hạn chế crash, lag.\n- Update các tính năng mới thường xuyên, đảm bảo app luôn bắt kịp xu hướng công nghệ.\n\nPhối hợp cùng đội kiểm thử, thực hiện unit test, integration test, duy trì chuỗi CI/CD, sẵn sàng chỉnh sửa, nâng cấp ứng dụng khi cần.\n\nYour skills and experience\n- Bằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng hoặc tương đương.\n- Ngoại ngữ: Đọc hiểu tài liệu tiếng Anh ngon lành. Ưu tiên có chứng chỉ TOEIC 550+ (hoặc IELTS, TOEFL tương đương).\n- Nền tảng lập trình: Thành thạo ít nhất một ngôn ngữ lập trình Mobile ( mobile Flutter/Java/Kotlin/Swift). Nắm rõ OOP, biết cách thiết kế class, hiểu sâu về các nguyên lý lập trình hướng đối tượng.\n- Kiến thức công nghệ: Xử lý dữ liệu có cấu trúc (string, record, object, collection…), Xử lý đa ngôn ngữ (localization), Thành thạo I/O cơ bản, Thao tác với CSDL (query, commit, rollback…), Lập trình đa luồng (multithreading), quản lý concurrency, connection pooling, Biết cách phân tích log để xử lý lỗi “thần tốc”.\n\nTinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội.\n\nWhy you\'ll love working here\n- Lương cạnh tranh: Thu nhập “ổn áp”, xứng đáng với năng lực và kinh nghiệm.\n- Đầy đủ các khoản thưởng: Thưởng lễ Tết, quà tặng, du lịch nghỉ mát, hỗ trợ ăn trưa, cước điện thoại…\n- Nghỉ phép linh hoạt: 12 ngày phép + 3 ngày nghỉ mát + 1 ngày sáng tạo mỗi năm.\n- Bảo hiểm toàn diện: Hưởng đầy đủ BHXH, BHYT, BHTN theo quy định, cộng thêm gói bảo hiểm riêng từ Viettel.\n- Môi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo “bung nóc”.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Tran Huu Duc, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(813, 260, 2, 'Python Developer (Apache Airflow, SQL)', 'WHO ARE WE? \nDigital Unicorn is a French digital agency with a passionate and ambitious team. We specialize in:\n- Mobile Application Development\n- Website Development\n- AI/Deep Learning\n- UX/UI Design\nWe’re more than just a company — we’re a small hub for those who want to step into an international working environment. Here, you’ll train, work, and build your career foundation, all while growing friendships that last.\nAt Digital Unicorn:\n- We share and support each other\n- We build meaningful products for startups\n- We create a space where you can enjoy working and growing\nAbout the Role\nWe are looking for a Python Developer with solid experience in backend development and workflow orchestration tools like Airflow. As part of our in-house engineering team, you will play a key role in building, maintaining, and optimizing data pipelines and backend services to support our internal systems and business operations.\nKey Responsibilities:\n- Develop, monitor, and maintain data pipelines using Apache Airflow and Python\n- Build and optimize ETL workflows for data ingestion and transformation\n- Collaborate with stakeholders to understand and deliver on data requirements\n- Design scalable and maintainable data architecture solutions\n- Manage and version control code using Git and Docker\n- Write clean, testable, and efficient SQL and Python code\n- Participate in agile processes and contribute to continuous improvement.\nYour skills and experience\nQualifications:\n- 5+ years of hands-on experience in Python development\n- Proven experience with Airflow for task scheduling and data orchestration\n- Strong understanding of software development best practices\n- Familiarity with RESTful APIs, version control (Git), and SQL\n- Able to work collaboratively in a team-oriented environment\n- Fluent English speaking skills (able to communicate with clients)\nPreferred:\n- Experience with containerization tools (Docker, Kubernetes)\n- Familiarity with cloud platforms (AWS, GCP, Azure)\n- Understanding of CI/CD pipelines\n- Exposure to data engineering workflows or ETL pipelines.\nWhy you\'ll love working here:\n- Training policy, salary, and bonus that match your skills and experience\n- Provision of full of devices for work\n- 100% salary during the probation period\n- Full insurance policies\n- Dynamic, comfortable, and creative working environment\n- Team Building events/ company trips every year\n- Snacks and fruits for breaks\n- Sports activities to recharge positive energies\n- Immerse in an English-speaking environment for professional foreign communication.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3F, 94 Ho Nghinh, Son Tra, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(814, 467, 2, 'Software Engineer', 'We are seeking a talented Backend Software Engineer to join our team. The ideal candidate will have experience with Golang and Postgres, and be open to learning Python and NodeJS. Strong skills in system design, a passion for tackling challenges, and the ability to work with Odoo are highly desirable.\n\nA.    RESPONSIBILITIES:\n●    Develop and maintain backend services\n●    Collaborate with the team to design and implement scalable and reliable systems\n●    Solve complex technical problems and provide innovative solutions\n●    Build CI/CD pipelines\n●    Run applications on multiple cloud platforms\n●    Develop features for back office system using Odoo\n\nYour skills and experience\n●    1 - 3 years hands on experience with Golang/ Python\n●    Deep understanding Postgres DB.\n●    Experience in system design for high scalable systems.\n●    Experience in writing tests.\n●    Experience with Python, NodeJS is a plus.\n●    Experience with Odoo is a plus.\n●    Willing to work on FE, Mobile, DevOps tasks is a plus.\n\nIf you are passionate about backend development, enjoy taking on challenges, and are eager to expand your skill set, we encourage you to apply.\n\nWhy you\'ll love working here\n- 13th-month salary\n- Full salary on probation\n- Annual Leave: 12 days \n- Premium Health insurance \n- Employee discount for M Village\'s booking service\n- Provide budget for Laptop purchasing \n- Social insurance: in accordance with the Social Insurance Law\n- Other allowance (Team bonding, birthday, marriage,...)\n- Annual Performance Review', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'SCIC Building - 16 Trương Định, Phường Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(815, 312, 2, 'Bảo mật hệ thống, bảo mật mạng (Security, System Admin)', 'Top 3 reasons to join us\n- Thu nhập từ 24 - 26 tháng lương/năm\n- Được đào tạo trend công nghệ mới\n- Team building, year-end party...\n\nJob description\n- Thiết kế, thử nghiệm và triển khai hệ thống bảo mật cho hệ thống máy chủ, máy trạm, ứng dụng, hệ cơ sỡ dữ liệu, mạng, truyền thông.\n  - Phối hợp nghiên cứu, phân tích, đánh giá, thiết kế mô hình triển khai vận hành và đề xuất với lãnh đạo phòng giải pháp bảo mật liên quan đến bảo mật hệ thống hoặc bảm mật mạng.\n  - Thực hiện triển khai các giải pháp bảo mật liên quan đến bảo mật hệ thống, endpoints vào trong hệ thống mạng của NHCTVN\n- Xây dựng quy trình, tiêu chuẩn và thiết lập, áp dụng các chính sách, tiêu chuẩn kỹ thuật liên quan đến bảo mật hệ thống, mạng, truyền thông.\n  - Thiết lập, duy trì, cập nhật các, tiêu chuẩn, chính sách bảo mật hệ thống, harding máy chủ, endpoints, kết nối mạng\n- Đánh giá, kiểm duyệt các phương án, giải pháp liên quan đến an ninh hệ thống, an ninh mạng.\n  - Thực hiện kiểm tra, đánh giá kiểm duyệt an toàn bảo mật các phương án, giải pháp bảo mật các hệ thống máy chủ, máy trạm, ứng dụng, cơ sở dữ liệu.\n- Thực hiện khắc phục các sự cố bảo mật liên quan hệ thống máy chủ, giải pháp bảo mật\n  - Khắc phục các sự cố bảo mật liên quan đến hệ thống, mạng, truyền thông.\n  - Đảm bảo các hệ thống ứng dụng có liên quan hoạt động liên tục, ổn định\n\nYour skills and experience\n- Trình độ:  Đại học hệ chính quy, chuyên ngành CNTT/điện tử viễn thông.\n- Kỹ năng chuyên môn:\n  - Có kiến thức kỹ thuật về hệ điều hành Linux, Window\n  - Có kiến thức và kinh nghiệm làm việc với các hệ thống IAM, các hệ thống xác thực SSO, MFA, AD, Exchange…\n  - Khả năng tự động hóa công việc là 1 lợi thế.\n  - Ưu tiên các ứng viên có các chứng chỉ về ATTT: CEH, OSCP, CEH…và/hoặc khả năng khai thác lỗ hổng CVE của hệ điều hành/ứng dụng là 1 lợi thế.\n- Kinh nghiệm\n  - Đối với vị trí CVC: Số năm kinh nghiệm liên quan: 2-3 năm kinh nghiệm trong lĩnh vực Bảo mật hệ thống, có kinh nghiệm ở các mảng, lĩnh vực liên quan đến ATTT.\n  - Đối với vị trí CVCC: Số năm kinh nghiệm liên quan: 3-5 năm kinh nghiệm trong lĩnh vực Bảo mật hệ thống, có kinh nghiệm ở các mảng, lĩnh vực liên quan đến ATTT.\n- Kỹ năng mềm\n  - Khả năng làm việc trong môi trường áp lực cao/ngoài giờ;\n  - Khả năng làm việc độc lập và theo nhóm;\n\nWhy you\'ll love working here\n- Dẫn đầu thị trường\n  - Cơ hội được làm việc tại một trong ngân hàng Big4.\n  - Cơ hội được thử sức trong những lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n  - Được tham gia vào các dự án lớn: Kho dữ liệu thô – VietinBank Data Lake, Hệ thống khách hàng VietinBank 360, VietinBank Cloud Data Lake…\n- Môi trường năng động sáng tạo\n  - Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo.\n  - Nơi hội tụ của các Machine Learning Engineer, Data Engineer, Software Engineer hàng đầu với nhiều năm kinh nghiệm trong các lĩnh vực tài chính ngân hàng.\n- Chế ngộ đãi ngộ hấp dẫn, cạnh tranh: \n  - Thu nhập từ 24 - 30 tháng lương/năm\n  - Được thư giãn, khơi nguồn sáng tạo mỗi ngày.\n  - Được đào tạo, định hướng chuyên môn thường xuyên;\n  - Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building thú vị\n  - Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '183 Nguyễn Lương Bằng, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(816, 543, 2, '[Junior-Senior] Product Designer (Figma, SaaS, UX/UI)', 'About Us\nAvian Solutions is a fast-growing aviation software startup, transforming the way the private aviation industry operates. Our core belief is that great design is not an afterthought — it’s at the heart of the product. We’re a tight-knit, ambitious team building smart, beautiful, and scalable solutions for complex workflows.\n\nWe’re looking for a creative, detail-oriented Product Designer who can turn complexity into elegant simplicity. You’ll work across responsive websites, SaaS platforms, customer portals, and mobile apps — helping shape a unified experience across our product ecosystem. If you’re driven by stunning interfaces, frictionless UX, and love bringing structure to complex systems — we’d love to hear from you.\n\nWhat You’ll Do\nAs our next Product Designer, you will:\n- Partner with product managers, engineers, and stakeholders to define, design, and refine powerful user experiences.\n- Own the entire design lifecycle: from research and wireframes to high-fidelity Figma mockups and interactive prototypes.\n- Design intuitive and beautiful UI across multiple platforms: websites, internal portals, mobile apps, and B2B SaaS tools.\n- Work on real, complex products — from private jet quoting platforms to internal dashboards — and bring order to technical chaos through visual clarity.\n- Validate design ideas with testing, feedback loops, and iteration.\n- Help maintain and evolve our design system for visual consistency across products.\n- Participate in user testing and QA to ensure pixel-perfect implementation.\n\nYour skills and experience\nWhat We’re Looking For\nMust-Haves:\n- 2+ years of proven experience in Product/UI/UX Design, with a portfolio showcasing real products, not just concept work.\n- Mastery of Figma for both prototyping and production design. \n- You should be fast, organised, and thoughtful in how you use it.\n- Creative problem-solving mindset – you should love turning ambiguous requirements into exceptional, user-friendly UI.\n- Strong command of UX principles and ability to articulate design decisions.\n- Experience designing responsive web interfaces, mobile apps, and SaaS platforms.\n- Strong collaboration skills – you’ll work closely with developers to ensure your designs are feasible, accessible, and implemented as intended.\n- Good written and spoken English communication.\n\nNice-to-Haves:\n- Familiarity with Agile or lean product development environments.\n- Experience with aviation, logistics, or B2B SaaS tools. \n- A basic understanding of HTML/CSS for better developer collaboration.\n- Experience working within or maintaining a design system.\n\nYou’ll Thrive Here If You\n- Obsessed with detail, typography, spacing, and user psychology.\n- Highly autonomous – you don’t wait to be told what to do.\n- Excited by startups, fast-paced environments, and solving real-world problems.\n- Inspired by good design and driven to constantly improve.\n- Not afraid to challenge norms and bring fresh ideas to the table.\n\nHow to Apply\nIf you\'re excited to bring clarity to complexity and design experiences people love — we want to hear from you!\nPlease include:\n- A link to your portfolio (required)\n- Your updated CV\n- A short note about why this role is a great fit for you.\n\nWhy Join Us?\nBe part of a mission-driven startup building something that truly transforms an industry. Maintain a healthy work-life balance with 40-hour workweeks and no overtime. iMac provided. Competitive salary and benefits. A chance to disrupt the Private Aviation industry with data and your toolkit.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '29, No. 10 Street, Sala Urban Area, An Loi Dong Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(817, 206, 2, 'Senior Java Developer', 'Top 3 reasons to join us\n- Attractive remuneration package with 18 days off\n- Smart people, interesting project & swiss quality\n- Travel opportunities to Switzerland\n\nJob description\n- Participate in innovative software development life cycle using agile methodologies\n- Adhere to the coding standards, best practices, common design patterns & principles\n- Delivery of high quality software together with the team, including design, code, troubleshooting, tests, documentation\n- Write the technical design and detailed design for the tasks\n- Self-manage tasks as per the timelines and quality\n- Coach, supervise or lead when necessary other developers and team members \n\nYour skills and experience\n- Bachelor\'s degree in computer science or equivalent\n- Good knowledge of OOP, SOLID principles, Design pattern, data modeling\n- Able to read and write technical documents in the English language\n- Good technical, analytical, and problem-solving skills\n- Passionate, pro-active, and keen to learn new technologies (or move to mission part)\n- Experience in the Java technology and ecosystem\n- Experience in SQL and database management systems\n- Knowledge of Javascript, HTML, XML, CSS\n- At least 5 years experience in software development of this applied stack\n- Proven experience of coaching and supervising other developers and team members\n- Proven experience: Spring, SpringBoot, Hibernate, etc.\n\nNice to have\n- Knowledge of the Agile methodology (Scrum)\n- Knowledge of CI/CD (Jenkins, Docker)\n- Experience and/or certifications on Amazon, Azure and Oracle clouds.\n- Experience in Web development (Angular, ReactJS) or Windows App development\n- Experience in leading a project or a team\n- Oral communication skills in English\n\nWhy you\'ll love working here\n- Professional European-based company\n- Attractive salary\n- Performance bonus of up to 4 months‘ salary\n- Opportunities for travel to Europe\n- Hybrid home/office working model\n- Flexible working time\n- Structured training & development roadmap\n- Good work-life balance\n- Premium healthcare insurance\n- Loyalty programs\n- Well-being activities\n- Annual company trips and team-building events\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CII Building, 152 Điên Biên Phủ, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(818, 544, 2, '[Bảo Lộc] Backend Developer (NodeJS, Typescript/NestJS)', 'VILL – Ứng dụng đa dịch vụ dành riêng cho người Việt, được tạo nên bởi chính người Việt, với sứ mệnh mang đến những trải nghiệm tiện ích vượt trội, phục vụ nhu cầu thiết thực của người dân trên khắp mọi miền Tổ quốc.\nVị Trí tuyển dụng: Lập Trình Viên Back-End (NodeJS)\nĐịa Điểm: Làm việc tại văn phòng ở Thành phố Bảo Lộc, Lâm Đồng (Không làm việc REMOTE)\nPhỏng vấn: phỏng vấn Online trước khi quyết định\nMô Tả Công Việc:\n- Xây dựng và phát triển các tính năng mới trên ứng dụng Back-End Server.\n- Kinh nghiệm làm việc với cơ sở dữ liệu như MySQL, Elasticsearch, Redis.\n- Nghiên cứu các công nghệ, kỹ thuật mới, thực hiện các nhiệm vụ khác được giao.\n- Xây dựng backend quản lý (server-side) cho các hệ thống vận hành tại VILL.\n- Viết code các tính năng theo nhu cầu vận hành, làm việc với Docker, Kubernetes, message queue, database (MySQL), API, CI...\n- Tham gia thiết kế kiến trúc phần mềm và cấu trúc dữ liệu.\n- Nghiên cứu áp dụng những kỹ thuật đảm bảo yêu cầu người dùng.\n- Tối ưu hóa hệ thống để xử lý dữ liệu lớn.\n- Triển khai code trên server test và production.\n- Viết code sạch, rõ ràng, dễ bảo trì.\nYour skills and experience:\n- Có 3+ năm kinh nghiệm trong phát triển NodeJS, với chuyên môn về TypeScript và NestJS.\n- Có kiến thức về Microservice, đã sử dụng qua Message Broker như RabbitMQ.\n- Có kiến thức tốt về sử dụng frontend framework (VueJS, ReactJS).\n- Sử dụng thành thạo RESTful APIs và các cơ chế xác thực danh tính (Cookies, JWT).\n- Có tư duy logic tốt trong việc xử lý các yêu cầu liên quan đến quy trình và số liệu.\n- Có ý thức viết code sạch, tỉ mỉ, chi tiết.\n- Ham học hỏi, sẵn sàng và có khả năng tự học ngôn ngữ công nghệ mới (nếu cần).\n- Có tinh thần làm việc của startup và sẵn sàng chia sẻ, đào tạo cho đồng nghiệp.\nWhy you\'ll love working here:\n- Lương & phúc lợi hấp dẫn\n - 12 phép năm\n - Cuối năm, thưởng thành tích, thưởng ngày lễ, thưởng sinh nhật;\n - Thẩm định và xét lương hàng năm;\n - Gói phụ cấp hấp dẫn;\n - Bảo hiểm Y Tế/. BHXH\n- Các khóa đào tạo: Đào tạo kỹ thuật, đào tạo Softskills, nội bộ và nước ngoài, v.v.\n- Hoạt động:\n - Company trip & Team building every year;\n - Tiệc tất niên;\n - Team building cho Team / Dept hàng tháng;\n - Câu lạc bộ: FOOTBALL CLUB, FOOD LOVERS, LUNCH DAY,…\n- Phương tiện di chuyển: Taxi phục vụ công tác\n- Mã Khuyến Mãi dành cho nhân viên\n- Cơ hội được đào tạo & làm việc tại công ty thương mại điện tử hàng đầu Việt Nam;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'VILL VIETNAM - Trung Tâm Thương Mại Hàng Dừa, Nguyễn Công Trứ, Phường 1, Bao Loc, Lam Dong', 'Full-time', '2025-10-07 20:59:18.149534'),
	(819, 545, 2, 'Business Analyst (Figma)', 'Làm cầu nối giữa người dùng và đội ngũ kỹ thuật, đảm bảo sản phẩm phần mềm hoặc giải pháp được phát triển đúng nhu cầu – đúng mục tiêu – đúng cách.\n\nNHIỆM VỤ CHÍNH\n- Phân tích yêu cầu nghiệp vụ, viết tài liệu mô tả chức năng (BRD, SRS…)\n- Giao tiếp, thu thập thông tin từ các phòng ban và khách hàng\n- Vẽ wireframe, flow, prototype trên Figma\n- Làm việc chặt chẽ với Dev, Tester, UI/UX để đảm bảo đúng yêu cầu\n- Theo dõi, kiểm thử và nghiệm thu sản phẩm\n- Báo cáo công việc theo yêu cầu của cấp trên.\n\nYour skills and experience\n- Nữ, tốt nghiệp Đại học các ngành liên quan (CNTT, Kinh tế, QTKD…)\n- Đã có kinh nghiệm làm BA từ 6 tháng trở lên\n- Sử dụng thành thạo Figma\n- Có kiến thức hoặc kinh nghiệm trong lĩnh vực giáo dục / công nghệ giáo dục / AI\n- Giao tiếp tốt, tư duy rõ ràng, có khả năng viết tài liệu\n- Sẵn sàng làm việc onsite, không remote.\n\nWhy you\'ll love working here\n- Thu nhập cạnh tranh: 7.000.000 – 12.000.000/tháng\n- Hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty: Nghỉ phép năm, nghỉ lễ, Tết theo quy định của công ty, tiệc công ty, team-building, du lịch hàng năm.\n- Được training, tiếp xúc, giao lưu, học hỏi với những đồng nghiệp giỏi, đam mê công nghệ và tâm huyết với sản phẩm.\n- Có cơ hội tham gia trực tiếp vào các dự án giáo dục quy mô lớn, hợp tác, tiếp xúc gặp gỡ với nhiều trường đại học trên toàn quốc. Cơ hội thăng tiến lên vị trí Trưởng nhóm chỉ sau 6–12 tháng nếu thể hiện tốt.\n- Đội ngũ khởi nghiệp trẻ, nhiệt huyết, tham vọng và nhân văn. Tất cả đồng lòng tạo ra giá trị thực tế cho gia đình, nhà trường và xã hội. Môi trường an toàn, lành mạnh, drama-free.\n- Thời gian làm việc:\n- 8h00 - 17h30 (thứ 2 đến thứ 6)\n- 8h00 - 12h00 (thứ 7)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, toà nhà VIT, 519 Kim Mã, Ngọc Khánh, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(820, 546, 2, 'Business Analyst', 'Job description\n- Làm việc trực tiếp với khách hàng để thu thập và làm rõ yêu cầu nghiệp vụ\n- Thực hiện phân tích và xây dựng tài liệu đặc tả yêu cầu nghiệp vụ\n- Đào tạo, giải thích cho các Lập trình viên hiểu rõ nghiệp vụ & mong muốn của khách hàng\n- Tham gia nghiệm thu phần mềm đảm bảo phần mềm đáp ứng đúng, đủ yêu cầu của khách hàng\n\nYour skills and experience\n- Tốt nghiệp Đại học trở lên các chuyên ngành: Công nghệ thông tin, Quản trị kinh doanh, Kinh tế.\n- Có tối thiểu 1 năm kinh nghiệm tại vị trí tương đương\n- Giao tiếp tốt, nắm bắt vấn đề nhanh, khả năng tự học hỏi tốt\n- Có khả năng thu thập, tổng hợp, phân tích thông tin\n- Có khả năng viết tài liệu, đào tạo và thuyết trình\n- Cẩn thận, trách nhiệm trong công việc\n\nWhy you\'ll love working here\n.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'E8-TT9 Khu đô thị sinh thái Xuân Phương, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(821, 547, 2, 'Junior Backend Developer (NodeJS)', 'Job description\n- Tham gia phát triển các dự án/ sản phẩm chiến lược của công ty\n- Xây dựng hệ thống Backend và lập trình các tính năng theo chỉ dẫn của quản lý\n- Triển khai các biện pháp bảo mật để bảo vệ dữ liệu và hệ thống\n- Thiết kế và triển khai các giải pháp lưu trữ dữ liệu\n- Chủ động và phối hợp cùng các team khác để hoàn thành các việc được giao\n- Tìm hiểu, áp dụng các công nghệ mới và phương pháp phát triển để nâng cao chất lượng sản phẩm\n\nYour skills and experience\n- Sv chuẩn bị hoặc đã tốt nghiệp các ngành liên quan đến công nghệ thông tin (có thể đáp ứng làm việc full-time)\n- Có kinh nghiệm cơ bản với các ngôn ngữ Back-End hoặc mong muốn chuyển từ ngôn ngữ khác qua Back-end, cụ thể là NodeJS\n- Có kinh nghiệm với ít nhất một relational database (MySQL, PostgreSQL ...)\n- Có kinh nghiệm phân tích dữ liệu là một điểm cộng\n- Có kỹ năng tư duy logic và thuật toán tốt, phân tích và giải quyết vấn đề\n- Kỹ năng giao tiếp, teamwork và quản lý thời gian\n- Có tinh thần cầu tiến, ham học hỏi\n\nWhy you\'ll love working here\n- Thu nhập hấp dẫn: Up to 12.000.000 VNĐ (Deal dựa trên năng lực)\n- Thời gian thử việc 2 tháng\n- Tham gia BHXH, BHYT, BHTN theo quy định của Nhà nước\n- Tổng phụ cấp 1,460,000 VNĐ/22 ngày công\n  - Phụ cấp ăn trưa (550k/tháng)\n  - Phụ cấp thiết bị (500k/tháng)\n  - Phụ cấp điện thoại (300k/tháng)\n  - Phụ cấp gửi xe (110k/tháng)\n- Review và feedback về năng lực, trao đổi định hướng với Leader hàng tháng\n- Mỗi đợt review lương được thực hiện tối đa 6 tháng/lần (tuỳ thuộc vào hiệu quả công việc)\n- Môi trường làm việc trẻ trung, nhiệt huyết, trao đổi cởi mở, nhiều cơ hội phát triển, được thử sức với nhiều thử thách mới\n- Thưởng theo Performance & doanh thu các hoạt động của công ty', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '216 Nguyễn Trãi, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(822, 363, 2, 'System Admin (IT Support, IT Governance)', '1. Quản trị tổng thể hệ thống CNTT (Server, mạng, bảo mật, thiết bị)\n- Vận hành và duy trì hệ thống hạ tầng CNTT của Công ty gồm: máy chủ (server), hệ thống mạng LAN/WAN/Wifi, Camera, hệ thống email và các phần mềm ứng dụng dùng chung.\n- Đảm bảo hệ thống hoạt động ổn định, an toàn và bảo mật.\n- Quản lý tài khoản người dùng: phân quyền truy cập, bảo mật dữ liệu, kiểm soát quyền hạn sử dụng.\n- Thực hiện sao lưu và khôi phục dữ liệu định kỳ, xây dựng quy trình đảm bảo an toàn thông tin.\n- Theo dõi và kiểm kê toàn bộ thiết bị công nghệ trong công ty, đề xuất bảo trì, thay thế hoặc nâng cấp khi cần thiết.\n\n2. Quản lý tài nguyên số và hỗ trợ kỹ thuật\n- Quản lý phần mềm bản quyền, domain, hosting, email và các dịch vụ công nghệ đang sử dụng.\n- Hỗ trợ kỹ thuật và xử lý các yêu cầu phát sinh từ người dùng nội bộ liên quan CNTT.\n\n3. Nghiên cứu và triển khai ứng dụng phần mềm phục vụ công việc\n- Chủ động nghiên cứu và đề xuất các phần mềm tối ưu hóa công việc vận hành, quản lý và giao tiếp nội bộ.\n- Làm việc NCC phần mềm để demo giải pháp, so sánh chi phí hiệu quả và xây dựng kế hoạch triển khai.\n- Phụ trách công tác chuyển đổi số của doanh nghiệp.\n\n4. Các nhiệm vụ khác liên quan CNTT\n- Tư vấn, đề xuất mua sắm thiết bị, phần mềm phù hợp với nhu cầu phát triển của công ty.\n- Thực hiện Demo các giải pháp/phần mềm của Công ty với khách hàng.\n- Thuyết minh kỹ thuật giải pháp Công ty đã phát triển.\n- Thiết lập tài khoản, cài đặt và hướng dẫn sử dụng App cho người dùng.\n- Phối hợp với các đối tác thuê ngoài thực hiện các công tác lắp đặt, cấu hình thiết bị/hệ thống cho khách hàng.\n- Ghi nhận các lỗi phát sinh trong quá trình triển khai phần mềm và phối hợp với các đơn vị liên quan để xử lý, theo dõi tiến độ và báo cáo cấp trên.\n- Thực hiện các nhiệm vụ khác liên quan CNTT theo sự phân công của cấp trên.\n\nYour skills and experience\n- Tốt nghiệp cao đẳng/đại học chuyên ngành CNTT, Điện tử viễn thông, Khoa học máy tính.\n- Kinh nghiệm 02 năm trở lên ở vị trí tương đương.\n- Nhanh nhạy công nghệ, có kinh nghiệm triển khai phần mềm.\n- Có kỹ năng demo giải pháp, đào tạo người dùng và dẫn đắt triển khai là một lợi thế.\n- Hiểu biết và có kinh nghiệm về cài đặt, vận hành, quản trị hệ thống server. Am hiểu các sự cố liên quan đến server, có khả năng phân tích lỗi và xây dựng phương án backup dữ liệu phù hợp.\n- Thành thạo hệ thống mạng LAN, WAN, Wifi, Domain, NAS và các thiết bị mạng.\n- Có tư duy hệ thống và logic tốt trong quản trị hạ tầng CNTT.\n\nWhy you\'ll love working here\n- Lương thỏa thuận theo năng lực.\n- Được hưởng lương T13, chế độ nghĩ phép, lễ, thưởng theo thành tích công việc và các chế độ phúc lợi khác như du lịch, team building…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '120 Nguyễn Minh Hoàng, Phường 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(823, 225, 2, 'Lead Java Engineer', 'By applying for the above position, you accept and agree that your personal data and any information stated in the attached curriculum vitae (CV) will be used and processed by ITViec and NAB Vietnam for recruitment purposes. The storage and processing of such information will comply with the applicable laws of Vietnam, and the policies and procedures of ITViec and NAB Vietnam regarding personal data, as amended from time to time.\n\nABOUT THE JOB  \nWe are seeking motivated Lead Java Engineers, who are passionate, results focused to take accountability for the delivery of Microservices that will be used by banking front end applications. You will be part of our delivery team and will be responsible for providing technical leadership throughout all phases of the software delivery life cycle as we initiate a transformation of NAB technology.  \nAt NAB, we believe success comes from our people. We\'re committed to supporting your talent and skills through your career, as you help us build a culture that affects change for our customers and for the community too.\n\nYOUR JOB RESPONSIBILITIES  \n- Design, develop, review, implement, and manage Java applications and services for the production and pre-release environments;  \n- Design, develop, review, implement, and manage continuous integration, build management and deployment scripts, systems, and any code as required;  \n- Participate in Agile software development, prototyping, and code review with international development teams to build scalable microservices-based products and APIs using Java technologies on AWS Cloud architecture;  \n- Fully understand the requirements of the customer or business and utilize this knowledge to develop applications that are consistent with this;  \n- Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and tooling;  \n- Provide robust coding practices, solid unit/component test coverage, and debugging code.  \n- Mentor, provide technical direction and engineering leadership for a team of engineers (for Lead)  \n- Provide leadership to team members (for Lead)\n\nYour skills and experience\nMust have\n- For Lead level: 7+ years of experience as a software engineer in a complex development environment.  \n- Solid experience in Java 8+ and Spring/Springboot.  \n- Experience in designing & developing RESTful APIs and complex microservices based system; troubleshooting and debugging in microservice  \n- Experience in Cloud computing and AWS or Azure  \n- Experience with unit testing and integration testing  \n- Practical experience in Containers (ECS, Kubernetes, Docker) and FaaS (AWS Lambda) technologies  \n- Good English communication skills (both verbal & written), especially in the global software development environment.  \n- Experience in Agile development environments;  \n- Well-versed in writing structured, well-documented, maintainable, and clean code;  \n- Good problem-solving and analytical skills  \n\nNice-to-have\n- Practical experience in Containers (ECS, Kubernetes, Docker) and FaaS (AWS Lambda) technologies.  \n- Experience in modern CI/CD pipelines and tools (e.g. Git, Ansible, Jenkins, NPM, Gradle).  \n- Experience in the Banking or Financial Services industry.\n\nWhy you\'ll love working here\n1. Generous compensation and benefit package  \n- Attractive salary and benefits  \n- 20-day annual leave and 7-day sick leave, etc.  \n- 13th month salary and Annual Performance Bonus  \n- Premium healthcare for yourself and family members  \n\n2. Exciting career and development opportunities  \n- Large scale products with modern technologies in banking domain  \n- Clear roadmap for career advancement in both technical and leadership pathways  \n- Sponsored certificates in both IT and banking/finance  \n- Premium accounts on Udemy/A Cloud Guru/Coursera/LinkedIn, etc.  \n- English learning with native teachers  \n\n3. Professional and engaging working environment  \n- Hybrid working model and excellent work-life balance  \n- Well-equipped & modern Agile office with fully-stocked pantry  \n- Annual company trip and events  \n\nA DIVERSE AND INCLUSIVE WORKPLACE WORKS BETTER FOR EVERYONE  \nNAB is a place where colleagues of all genders, sexualities and ages, carers and colleagues with disability, and colleagues from all cultures, races and religions have the opportunity to thrive, connect and grow.  \n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh / ROX Tower, 54A Nguyen Chi Thanh, Lang Thuong, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(824, 531, 2, 'Senior Automation Quality Engineer', 'Top 3 reasons to join us\n- Flexible Friday afternoon\n- 18 Annual Leave + 5 Recharge Days/ Year\n- Hybrid working model\n\nJob description\n- Design, develop, and maintain automated test scripts for Mobile apps (React Native), Web applications, and APIs.\n- Initiate and support backend performance testing.\n- Set up and manage CI pipelines to integrate automated tests into the development lifecycle.\n- Ensure test coverage and quality metrics are met across platforms.\n- Participate in code reviews and contribute to test strategy discussions.\n- Collaborate with Development and Infrastructure teams to stabilize tests.\n- Work independently while mentoring junior engineers and contributing to team-wide quality initiatives.\n\nYour skills and experience\nRequired Qualifications\n- 3–5 years of experience in test automation across Mobile, Web, and API.\n- Proficiency in programming languages such as JavaScript, TypeScript or Java.\n- Strong understanding of test automation frameworks and best practices. (e.g., Playwright, Appium, WebdriverIO)\n- Experience with CI/CD tools with the ability to integrate automated testing into deployment workflows.\n- Familiarity with mobile device farms (e.g., BrowserStack, Sauce Labs).\n- Excellent English communication skills (written and verbal).\n- A proactive mindset and a passion for quality engineering in a fast-paced, cross-functional team environment.\nPreferred Qualifications\n- Experience automating React Native applications using tools like Appium or Detox.\n- Exposure to performance testing tools (e.g., k6, Gatling) is a plus.\n- Familiarity with containerized environments (e.g., Docker) and cloud-based CI/CD pipelines.\n- ISTQB or equivalent QA certification.\n\nWhy you\'ll love working here\nAttractive Benefits:\n- 100% salary during probation period\n- Annual Leave: 18 days/ year\n- Five “Recharge Days” – Extra days, in addition to company holidays.\n- Flexible Friday afternoon\n- Full salary insurance\n- 13th-month bonus\n- Advanced health insurance (Generali)\n- Regular engagement activities: sport clubs, internal events…\n- Support Macbook and Monitor\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Waseco Building - 10 Pho Quang Street, Ward 02, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(825, 186, 2, 'Lập trình website (ReactJS, UI-UX, JavaScript)', 'Job description\n- Phát triển giao diện người dùng bằng React (JS).\n- Thiết kế UI/UX, giao diện web, banner, layout...\n- Kết nối với backend (API)\n- Chuyển bản thiết kế thành HTML/CSS/JS chuẩn, tối ưu hiển thị trên trình duyệt.)\n\nYour skills and experience\n- Có thẩm mỹ tốt và nền tảng thiết kế đồ họa vững chắc.\n- Có tư duy thiết kế độc lập và một mức độ tư duy trừu tượng nhất định. Có thể phát triển phong cách tương tác và quy chuẩn thiết kế từ prototype sản phẩm, chú trọng đến chi tiết.\n- Khả năng làm việc nhóm và phối hợp liên phòng ban tốt, tinh thần trách nhiệm cao.\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nWhy you\'ll love working here\n✨ CHẾ ĐỘ PHÚC LỢI HẤP DẪN TẠI CÔNG TY ✨\n- Thu nhập cạnh tranh:\nMức lương hấp dẫn, thưởng tháng 13 và thưởng thâm niên.\n- Thưởng theo hiệu quả công việc, xét thưởng vào các dịp Lễ – Tết.\n- Đánh giá tăng lương 1 lần/năm, trường hợp nổi bật sẽ được xét tăng lương ngay tại thời điểm.\n- Chế độ nghỉ phép:\n12 ngày nghỉ phép có lương mỗi năm theo quy định – nghỉ thoải mái, vẫn nhận lương đầy đủ.\n- Sự kiện nội bộ ấm áp:\nHàng năm tổ chức “Ngày hội gia đình” vào tháng 5, có quà tặng bằng tiền mặt dành tặng ông bà, cha mẹ, vợ/chồng và con cái của nhân viên – thể hiện sự trân trọng với cả gia đình bạn.\n- Chế độ quà tặng nhân dịp đặc biệt:\nTặng quà các ngày lễ: Tết Dương lịch, Tết Âm lịch, 30/4, Trung thu, 8/3, 20/10.\n- Cả nhân viên nam và nữ đều có quà.\n- Nhân viên chính thức trên 6 tháng được tặng quà sinh nhật trị giá 5 triệu đồng/người.\n- Thưởng hiệu suất riêng:\nNgoài lương chính còn có các khoản thưởng, bonus hàng tháng tùy theo đóng góp.\n- Hỗ trợ nơi ở:\nNhân viên ở xa được sắp xếp chỗ ở miễn phí, thuận tiện cho công việc.\n- Cơ hội học hỏi và phát triển:\nLàm việc cùng các chuyên gia hàng đầu trong nước và quốc tế.\n- Giao lưu, học hỏi với đồng nghiệp quốc tế giúp cải thiện tiếng Anh và mở rộng tư duy toàn cầu.\n- Chăm sóc sức khỏe toàn diện:\nKhám sức khỏe định kỳ tại các bệnh viện quốc tế như BV Phương Đông.\n- Miễn phí tiêm phòng HPV, cúm cho nhân viên.\n- Trải nghiệm công tác và du lịch:\nCác chuyến công tác nước ngoài kết hợp du lịch, khám phá đặc sản và địa danh nổi tiếng.\n- Được tài trợ các hoạt động gắn kết team, học hỏi kiến thức lập trình qua các buổi giao lưu, workshop.\n- Văn phòng hiện đại, tiện nghi:\nKhông gian làm việc rộng rãi, thoáng mát.\n- Có bánh, trà, café phục vụ mỗi ngày.\n- Bữa trưa đầy đủ dinh dưỡng, ngon miệng dành riêng cho nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'B4-12 Vinhomes Gardenia Hàm Nghi, Đường Hàm Nghi, Phường Cầu Diễn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(826, 225, 2, 'Manager Data Engineer', 'At NAB, we are at the doorstep of building a next-generation Security Information and Event Management (SIEM) system. As part of this mission, we are seeking a dynamic and experienced Manager to lead our SIEM Engineering team. This is a unique opportunity to be on the ground floor of a new capability, where you will play a crucial role in supporting the transition from the incumbent SIEM while shaping the future of SIEM capabilities at NAB.\n\nYOUR JOB RESPONSIBILITIES\nDesign, develop and implement solutions in collaboration with other technical teams.\nUse engineering best practices in the undertaking of day-to-day responsibilities.\nIdentify and implement process and architecture improvements.\nActively identify, report, and implement risk remediation tasks as appropriate to your role.\n\nYou will:\nLead and manage a team of SIEM engineers, initially focused on managing data and supporting a transition from the incumbent SIEM.\nCreate, implement and maintain rigorous processes.\nExhibit and maintain high engineering standards, including documentation.\nExhibit and set the level of urgency within the team in addressing issues.\nHave a solid background in data processing and storage, alerting and searching techniques and technologies to guide and validate the work of your team.\n\nYour skills and experience\n3+ years engineering or people leadership\n5+ years experience with building, and maintaining ETL pipelines, data lakes or SIEM\nExperience with a subset of the following technologies:\nAmazon SNS/SQS\nAzure Service Bus\nAzure Event Hubs\nApache Kafka\nWindows Event Forwarder\nSyslog\nCribl\nSplunk, including Data Modelling\nData lake (eg Data Bricks)\nIdeally experience leading a team with service management responsibilities\nIdeally experience with Cyber Security domain\nTertiary qualification in a Technology discipline or related field\nQualifications and/or certifications in data, engineering and/or cybersecurity are highly valued.\n\nWhy you\'ll love working here\nTHE BENEFITS AND PERKS\n1. Generous compensation and benefit package\nAttractive salary and benefits\n20-day annual leave and 7-day sick leave, etc.\n13th month salary and Annual Performance Bonus\nPremium healthcare for yourself and family members\nMonthly allowance for team activities\nPremium welcome kit and frequent appreciation gifts\nExtra benefits for long-term employees\n\n2. Exciting career and development opportunities\nLarge scale products with modern technologies in banking domain\nClear roadmap for career advancement in both technical and leadership pathways\nWell-structured learning and development programs (technical and soft skills)\nSponsored certificates in both IT and banking/finance\nPremium account on Udemy\nEnglish learning with native teachers\nOpportunity for traveling & training in Australia\n\n3. Professional and engaging working environment\nHybrid working model and good work-life balance\nWell-equipped & modern Agile office with fully stocked pantry\nSpecial programs to improve your physical and mental health\nAnnual company trip and events\nA solid talented team behind you – great people who love what they do\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(827, 548, 2, 'Senior Fullstack Developer (JavaScript, SAP, English)', 'Senior Fullstack Developer (JS) – Drive Innovation in Solar Power\n\nAre you ready to make a real impact in one of the world’s most exciting industries? Join a US-based company at the forefront of the sustainability movement, focusing on solar energy—an industry booming with opportunity and purpose.\n\nWe\'re building a cutting-edge, complex project management system that powers operations across our entire company—and we want you to be a core part of the team.\n\nWhat You\'ll Be Doing\nAs part of our core development team, you will:\n● Develop and own new features from concept to deployment\n● Hunt down bugs and ensure smooth, reliable performance\n● Deliver high-quality code—functionally solid and scalable\n● Contribute to planning, demos, and reporting to keep stakeholders in sync\n● Bring your ideas to life—your voice matters here, and you\'ll have space to lead features from scratch to production\n\nNo surprises—we’ll stick to these responsibilities. No extra hats unless you want to wear them.\n\nYour skills and experience\nWhat We\'re Looking For\nYou’ll thrive here if you have:\n● 5+ years of hands-on software development experience\n● Strong JavaScript skills and are confident across both frontend and backend\n● A passion for learning and are open to exploring new tech (e.g., SAP)\n● An ownership mindset—you build it, you test it, you stand by it\n● Fluent English communication skills (you’ll work closely with global teams)\n\nBonus Points\nYou’ll stand out even more if you have:\n● Experience refactoring or migrating legacy systems into modern, scalable architectures\n● Familiarity with SAP\n● Knowledge of caching solutions like Redis\n\nWhy you\'ll love working here\n● Top-tier compensation in Vietnam—even in today’s market\n● Flexible, trust-based work culture – We care about outcomes, not your screen time\n● Hybrid work model – You choose your rhythm between home and office\n● Premium gear to help you do your best work\n● Room to grow – Pitch your ideas, drive solutions, and shape your own path.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '9th Floor, CMARD2 Building, Suite 901, 45 Dinh Tien Hoang, Ben Nghe Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(828, 520, 2, 'Senior .NET Developer (Retail, ERP)', 'Top 3 reasons to join us\n1 trong 10 website có lượng truy cập lớn nhất\nMôi trường năng động, trẻ, sáng tạo, gắn kết\nMức lương hấp dẫn và tăng dần theo năng lực\n\nJob description\nPhát triển hệ thống:\nThiết kế và phát triển các microservices cho hệ thống ERP.\nXây dựng REST APIs hỗ trợ ứng dụng web và mobile.\nTối ưu hóa hiệu năng và khả năng mở rộng của hệ thống.\nThiết kế database và tối ưu hóa truy vấn.\n\nPhát triển nghiệp vụ:\nTự động hóa và tối ưu hóa quy trình nghiệp vụ.\nTích hợp giữa các phân hệ ERP, đảm bảo dữ liệu đồng nhất và chính xác.\n\nVai trò dẫn dắt:\nThực hiện code review và hướng dẫn thành viên trong nhóm.\nPhân tích yêu cầu và đề xuất giải pháp kỹ thuật.\nNghiên cứu và áp dụng công nghệ mới vào hệ thống.\n\nXây dựng coding standards và các best practices.\n\nCore Systems\nBackend: .NET Core 6+, REST APIs, EF Core\nDatabase: SQL Server, MongoDB, Redis\nMessage Queue: Kafka, RabbitMQ\nInfrastructure: Docker, Kubernetes, Rancher\nFrontend: Flutter (Mobile & Web)\n\nYour skills and experience\nĐối với Senior từ trên 4 năm kinh nghiệm phát triển với .NET Core và C#.\nĐối với Middle từ 2-4 năm kinh nghiệm .NET Core và C#\nThành thạo thiết kế RESTful APIs.\nHiểu biết sâu về thiết kế và tối ưu hóa database.\nKinh nghiệm làm việc với microservices architecture.\nNắm vững OOP, Design Patterns, và Clean Architecture.\n\nƯu tiên:\nKinh nghiệm với Docker, Kubernetes, Kafka/RabbitMQ, hoặc Redis.\nTriển khai CI/CD pipeline.\nHiểu biết hoặc từng làm việc với ERP systems và business process automation.\n\nLợi thế:\nKinh nghiệm phát triển reporting & analytics.\nHiểu biết về Flutter.\nKinh nghiệm với các nền tảng cloud như GCB.\n\nWhy you\'ll love working here\nChế độ đãi ngộ\nĐối với Senior từ trên 4 năm kinh nghiệm phát triển với .NET Core và C#. (Thu nhập từ 35 triệu - 50 triệu)\nĐối với Middle từ 2-4 năm kinh nghiệm .NET Core và C# (Thu nhập từ 20-32 triệu)\nThăng tiến theo tăng trưởng công ty và khả năng chuyên môn\nĐược hưởng đầy đủ chính sách theo quy định: BHXH, BHYT, các phúc lợi khác theo luật Lao động\nĐược hưởng Gói Bảo hiểm nâng cao PTI\nThưởng năm hấp dẫn từ 1,5-3 tháng thu nhập\n\nĐào tạo - Phát triển\nCơ hội làm việc với nhiều dự án quan trọng và thăng tiến sự nghiệp cùng với sự phát triển của Công ty\nĐược nghiên cứu, đào tạo và làm việc với các công nghệ / hệ thống tiên tiến\nĐược công ty tạo điều kiện và hỗ trợ khi tham gia các khóa đào tạo, phát triển năng lực.\n\nMôi trường làm việc\nLàm việc và phát triển tại một trong những hệ thống thuộc Top hệ thống bán lẻ công nghệ.\nCấp laptop/ màn hình hỗ trợ công việc\nMôi trường trẻ trung, năng động, coi trọng năng lực và khả năng sáng tạo với nhiều dự án đa dạng\nTham gia nhiều hoạt động thiện nguyện cùng Công ty và các tổ chức thiện nguyện khác\nTham gia CLB thể thao: Bóng đá, cầu lông, chạy bộ….', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '350-352 Võ Văn Kiệt, Phường Cô Giang, , District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(829, 253, 2, '(Entry Level/No experience required) Web Developer', 'Top 3 reasons to join us\n\n1. 13th Month salary, work 5 days a week\n2. Annual Company Trip, Quarterly team building\n3. Premium health insurance, Support sport clubs\n\nJob description\n\n- Develop browser-based frontend applications.\n- Create prototypes and review new technologies.\n- Collaborate on user experience (UX) and user interface (UI) design.\n- Maintain code quality through code reviews and teamwork.\n\nYour skills and experience\nRequirements\n\n- Strong interest in game development.\n- Understanding of responsive web design.\n- Ability to solve cross-browser compatibility issues.\n- Excellent problem-solving and communication skills.\n- Willingness to continuously explore and implement new technologies.\n- Understanding of performance optimization and web accessibility.\n\nPreferred Qualifications\n\n- Familiarity with various data visualization tools.\n- Experience with modern frontend frameworks (React, Angular, Vue.js, etc.).\n\nOur recruitment process\n\n1. Application screening\n2. F2F Interview (Only 1 round)\n3. Job offer\n\nWhy you\'ll love working here\n\n- Chance to work on global projects with multicultural teams, world-class games.\n- Attractive salary and benefits.\n- Professional work environment.\n- Open culture where every employee is valued, treated fairly. and trusted.\n- 13th salary every year at least 1-month salary.\n- From 12 days Annual Leave\n- Government social, health, and unemployment insurance.\n- Lunch Allowance\n- Annual salary review based on employee performance and company success\n- Annual Company Trip, Year End Party\n- Events during Birthday, Full Moon Festival, other important holidays\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UOA Tower, 11th Floor, 06 Tan Trao Street, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(830, 235, 2, 'Chuyên Viên Kiểm Toán Công Nghệ Thông Tin', '1. Tham gia các Đoàn kiểm toán về CNTT.\n- Làm trưởng các Đoàn/nhóm kiểm toán về nghiệp vụ CNTT:\n- Xây dựng đề cương/kế hoạch; Hướng dẫn kiểm toán chi tiết cho từng cuộc/nhóm kiểm toán.\n- Phân công, hướng dẫn công việc cho các thành viên trong đoàn/nhóm.\n- Triển khai công tác chuẩn bị cho các đoàn/nhóm kiểm toán: Thu thập đầy đủ các quy định; các hồ sơ, tài liệu; khai thác các dữ liệu, số liệu liên quan đến nội dung, phạm vi, thời hiệu của cuộc/nhóm kiểm toán.\n- Nhận diện, đánh giá rủi ro để chọn mẫu, xác định phạm vi mẫu kiểm toán phù hợp với kế hoạch kiểm toán đã được duyệt.\n- Tổ chức thực hiện, điều hành đoàn/nhóm kiểm toán.\n- Kiểm toán, rà soát kết quả kiểm toán và các kiến nghị đề xuất của các thành viên trong Đoàn/nhóm trước khi tổng hợp kết quả kiểm toán; lập Báo cáo kết quả kiểm toán của đoàn/nhóm kiểm toán.\n\n2. Đánh giá, xây dựng hồ sơ rủi ro kiểm toán.\n- Thu thập hồ sơ, thông tin liên quan đến các rủi ro (bao gồm rủi ro tiềm ẩn/ rủi ro đã phát hiện) đối nghiệp vụ được phân công; thực hiện phân tích, đánh giá rủi ro; tổng kết, phân loại rủi ro; lưu trữ hồ sơ rủi ro.\n- Cảnh báo và tư vấn các biện pháp phát hiện, phòng ngừa, giảm thiểu rủi ro.\n\n3. Phối hợp với các Phòng nghiệp vụ trong Khối KTNB xây dựng các công cụ kiểm toán.\n\n4. Công tác đào tạo.\n- Tham gia các khóa đào tạo do LPBank/hoặc bên ngoài tổ chức theo yêu cầu công việc;\n- Tự đào tạo, nghiên cứu cập nhật các quy định nội bộ, quy định pháp luật đảm bảo nắm vững, hiểu rõ quy định liên quan đến nghiệp vụ được phân công;\n- Tham gia hướng dẫn cán bộ mới trong nhóm/trong mảng công việc được phân công phụ trách. Chia sẻ kinh nghiệm kiểm toán đối với từng nghiệp vụ, kỹ năng, phương pháp kiểm toán tại các buổi họp/buổi tự đào tạo của toàn Khối KTNB.\n\nYour skills and experience\n- Yêu cầu chuyên môn thành thạo về lĩnh vực công nghệ thông tin (CNTT) có thể đảm đương vị trí Trưởng đoàn/Phó đoàn/Trưởng nhóm trong Đoàn kiểm toán\n- Có kiến thức, hiểu biết cơ bản về nghiệp vụ ngân hàng và am hiểu chuyên sâu về nghiệp vụ CNTT trong hoạt động ngân hàng\n- Có khả năng điều hành công việc ở một Đoàn/nhóm kiểm toán trong đoàn, có tính chủ động\n- Tốt nghiệp Đại học loại Khá trở lên, chuyên ngành Công nghệ thông tin hoặc chuyên ngành phù hợp với kiểm toán CNTT\n- Tối thiểu 04 năm kinh nghiệm làm việc trong lĩnh vực CNTT\n- Ưu tiên ứng viên có kinh nghiệm làm Kiểm toán nội bộ về CNTT tại Ngân hàng/Kiểm toán độc lập đã có kinh nghiệm kiểm toán CNTT tại Ngân hàng\n- Ưu tiên ứng viên có các chứng chỉ CIA,CISA/CISM/CISSP\n- Ngoại ngữ Tiếng Anh tương đương trình độ B, tin học tương đương trình độ C\n- Có khả năng sử dụng thành thạo công cụ xử lý, phân tích dữ liệu như: SQL, Dashboard, VBA, Power BI, Python, Tableau...\n- Chịu được áp lực công việc cường độ cao\n- Kỹ năng quản lý, kỹ năng thuyết trình và giải quyết vấn đề tốt\n\nWhy you\'ll love working here\n- Quyền lợi : \n- Cơ hội tạo ra dấu ấn trong hành trình sự nghiệp số của bản thân khi tham gia xây dựng các dự án ĐANG phát triển và là TRỌNG ĐIỂM của Ngân hàng (thay vì xây dựng từ giai đoạn đầu).\n- Cơ hội trải nghiệm các kiến trúc, công nghệ mới nhất trên thị trường Tài chính - Ngân hàng.\n- Cơ hội nhận gói thu nhập hấp dẫn cùng với rất nhiều chế độ phúc lợi toàn diện chỉ dành cho các CBNV.\n- Cơ hội đào tạo chuyên môn, học hỏi từ những chuyên gia đầu ngành, luân chuyển công việc sang các phòng ban khác phù hợp với lộ trình thăng tiến nghề nghiệp.\n- Cơ hội làm việc tại văn phòng làm việc đạt chuẩn Top A với các trang thiết bị máy móc hiện đại nhất, tiên tiến nhất, tham gia những hoạt động thường niên của Ngân hàng nhằm nâng cao đời sống CBNV.\n\nPhúc Lợi :\n- Máy tính xách tay \n- Bảo hiểm \n- Phụ cấp (Thâm niên, Ăn trưa,...)\n- Du lịch nước ngoài \n- Đồng phục \n- Thưởng\n- Chăm sóc sức khỏe \n- Đào tạo \n- Tăng lương \n- Chế độ nghỉ phép\n- Chế độ tập thể dục\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'LPBank Tower, 210 Tran Quang Khai, Trang Tien, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(831, 549, 2, 'Senior GCP Engineer (Cloud/ Linux/ SQL)', 'Develop understanding of Google Cloud\'s GKE product technology and underlying architectures by troubleshooting, reproducing, and determining the root cause for customer-reported issues, building tools, and faster diagnosis.\n\nYour skills and experience\n\n➢  Must requirements:\nExperience in Computer Networking (e.g., TCP/IP, Routing, Load balancing, etc.).\nExperience with Linux/Unix or Windows systems, from the kernel to the shell, file systems, and client-server protocols.\nIn-depth hands-on work experience with implementations of Google Cloud Platform (GCP)\nExperience in Architecture Designing IaaS (Virtual Machines), PaaS(App Service, Cloud Function)\nGood at CI/CD pipeline creation and Container repository\nProgramming experience in one or more of the following: Python, Java, JavaScript, Shell Script\nExperience in Kubernetes on Cloud (Containerization basics, Control-plane components of  Kubernetes, Deployments, Jobs, and Scaling Persistent Data and Storage)\nExperience in SQL and NoSQL databases, such as MongoDB, PostgreSQL, CouchDB ...\nStrong Engineering mindset to automate tasks, deployment & support, etc,\nRelative experience in Infrastructure as a Code (IaaC) (i.e., Terraform, Cloud Formation…)\nExperience in Identity and Access (Cloud IAM)\nExperience in Docker / K8S / Istio / Envoy Proxy\nExperience in Docker, Kubernetes, Kafka, RabbitMQ, VerneMQ\nExperience with Logging/Monitor tools such as: Prometheus/Grafana, ELK …\nExperience debugging complex workload issues across large-scale, multi-node environments\nExperience development and deploy micro services-based applications in public cloud (GCP, OCI …)\n➢  Good to Have:\nGCP certification will be a plus.\nExperience working with RESTful web services.\nIOT architecture : IoT Mqtt Gateway, IoT Mqtt Broker, BigData.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zone 3 và Zone 4, Tầng 16, tòa nhà Văn phòng 789, số 147 đường Hoàng Quốc Việt, Phường Nghĩa Đô, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(832, 388, 2, 'Data Engineer/ Data Analysis (Power BI)', 'Data Engineer is taking responsibility for building Data Warehouses and making BI automatic reports\n1. Effectively engage stakeholders to understand their business problems and formulate a data-driven resolution approach.\nDocument and follow existing processes for reporting and data quality management.\nProvide ad-hoc data and analytics support to the business and perform other related duties as assigned.\n2. Visualize data using reporting/ dashboard tools & techniques and be accountable for the availability, quality, and accuracy of reporting. * Actively look for potential simplification/ automation areas and implement these changes.\n3. Continuous research and improvement to become a subject matter expert on our data repositories/ analytic solutions. Provide thought leadership to the team on use and interpretation.\n4. Actively look for potential simplification/ automation areas and implement these changes.\n5. Inherently curious about data and strongly desires to keep up with the latest analytics/ visualization and machine learning developments.\n6. Providing the guidelines/ training to all Users in using BI tools/report.\n7. Other related tasks by the Manager\n\nYour skills and experience\nEducation: Bachelor\'s degree in Statistics, Applied Math, Computer Science, or a related field.\nExperience:\n3+ years of experience in data analytics, working closely with business functions.\nHands-on experience building and managing Power BI solutions, including datasets, reports, dashboards, and data models.\nFamiliarity with ETL/ELT tools and data integration frameworks. Understanding of data modeling, star/snowflake schemas, and best practices for BI performance optimization.\nStrong communication and stakeholder management skills, with the ability to translate business needs into technical solutions.\nProficient in Microsoft Excel, SQL, and Visualization tools.\nPower BI and Azure experience is a plus.\nExperience with Python/ R programming is a plus.\nWork related skills\nExperience in retail is highly desirable but optional.\nStrong strategic thinking with agility and a growth mindset.\nAbility to communicate with non-technical/ technical peers.\nSoft skills\nAttention to detail.\nCritical thinking.\nCan-do attitude.\nDecent communication skills.\n\nWhy you\'ll love working here\nVTI offers you a fulfill working experience with:\nHealth care and dental insurance.\nPhone and gas allowance.\n12 paid-leave days a year.\nGood discounts at Highlands Shops and Pho24 shops.\nPrime location in Sala.\nSponsored events (Women’s Day, Men’s Day, Halloween party, Christmas party, Year-end party, and more).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khu đô thị Sala, 119 - 127 Nguyen Co Thach, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(833, 246, 2, '.NET Developer (C#, SQL, OOP, API)', 'Chúng tôi đang tìm kiếm Developer .NET có ít nhất 2 năm kinh nghiệm để gia nhập đội ngũ phát triển sản phẩm lâu dài tại PickoNow. Nhân sự mới sẽ làm việc chặt chẽ với Product Owner, UI/UX Designer và các thành viên khác trong dự án để xây dựng và phát triển ứng dụng PickoNow, mang đến trải nghiệm tuyệt vời cho cộng đồng pickleball.\n- Phát triển, tối ưu và bảo trì ứng dụng sử dụng .NET (C#, ASP.NET Core).\n- Làm việc với Product Owner để phân tích yêu cầu, đề xuất giải pháp kỹ thuật phù hợp.\n- Xây dựng và tích hợp API, làm việc với cơ sở dữ liệu (SQL Server, PostgreSQL).\n- Tối ưu hiệu năng và bảo mật cho ứng dụng.\n- Kiểm tra, sửa lỗi, nâng cấp tính năng và đảm bảo chất lượng sản phẩm.\n\n**Your skills and experience**\n- Có tối thiểu 2 năm kinh nghiệm ở vị trí tương ứng (.NET)\n- Thành thạo lập trình hướng đối tượng (OOP), có hiểu biết về mô hình MVC hoặc MVVM.\n- Có kinh nghiệm làm việc với các hệ thống API (RESTful API, GraphQL).\n- Kinh nghiệm với Git (GitHub, GitLab, hoặc Bitbucket).\n- Có trách nhiệm với công việc, sẵn sàng học hỏi công nghệ mới.\n- Nếu biết cả .NET và Flutter là một lợi thế nhưng không bắt buộc.\n- Ưu tiên ứng viên có kinh nghiệm làm việc với CI/CD, Docker, Kubernetes.\n\n**Why you\'ll love working here**\n- Mức lương cạnh tranh theo năng lực.\n- Môi trường làm việc năng động, chuyên nghiệp, có cơ hội thăng tiến.\n- Được làm việc với đội ngũ giàu kinh nghiệm, học hỏi và phát triển kỹ năng.\n- Hỗ trợ đào tạo, tham gia các khóa học nâng cao chuyên môn.\n- Được tham gia bảo hiểm và các phúc lợi theo quy định của công ty.\n- Chế độ thưởng theo dự án, hiệu suất làm việc.\n- Cơ hội làm việc trong ngành công nghệ thể thao và startup sáng tạo.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '188 A6 Nguyễn Văn Hưởng, phường Thảo Điền, Quận 2, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(834, 501, 2, 'Systems Architect (Hybrid/Fully Remote)', 'playSTUDIOS is seeking a Systems Architect to design and implement robust technical solutions that support our suite of web applications to ensure seamless integration with third-party games and apps. You will work closely with product managers, engineering teams, and other stakeholders to align business requirements with technical strategy, ensuring scalability, reliability, and performance of our systems.\n\nWe have a deep passion for quality, and expect someone with a high personal bar.\n\nThe Systems Architect will report to the Technical Director with duties including:\n\n- Define and evolve the system architecture across, backend services, internal platforms, and operational tooling.\n- Work closely with internal engineering teams to ensure the architecture is translated effectively into development work.\n- Collaborate with internal teams and other architects to integrate systems across the organization.\n- Provide technical leadership and guidance to development teams in implementing the proposed architecture and solutions.\n- Stay up to date with industry trends, emerging technologies, and best practices to continuously improve solutions.\n- Contribute to the development of internal tooling and processes to improve the efficiency and effectiveness of the development team.\n- Evaluate new technologies and make recommendations to evolve and future-proof our systems.\n- Identify potential risks and proactively propose mitigation strategies.\n\nYour skills and experience:\n\n- 5+ years of experience in systems architecture, with a proven track record in architecting web applications, tooling solutions, and integrations.\n- Good command of English - written and spoken.\n- Strong background in designing scalable, high-performance systems.\n- Extensive experience with web technologies (e.g., Node.js, React, Angular, Python, Java, etc.).\n- Familiarity with API design and integration (REST, GraphQL, SOAP, etc.).\n- Expertise in database technologies (e.g., SQL, NoSQL, distributed databases).\n- Strong understanding of microservices, containers, and orchestration (Docker, Kubernetes, etc.).\n- Experience with authentication, security protocols, and identity management (OAuth, JWT, etc.).\n- Knowledge of CI/CD pipelines and development practices (Git, Jenkins, etc.).\n- Strong verbal and written communication skills, with the ability to convey complex technical concepts to non-technical stakeholders.\n- Ability to collaborate in a fast-paced, cross-functional environment.\n- Familiar and comfortable with agile methodologies.\n\nAdditional Notes:\n\n- You may be expected to complete a test as part of the interviewing procedure.\n- Expat candidates are encouraged to apply.\n\nWhy you\'ll love working here:\n\n- Work directly with a global team of young and talented playMAKERS regardless of gender, age or experience.\n- Unlimited growth opportunities and continuous improvement with English classes, workshops and other technical training courses by highly-skilled members from all over the world.\n- Bao Viet Premium healthcare coverage is 1.2 billion VND/person/year (including you and ALL your dependents).\n- A company of fulfillment: 100% salary on probation, 100% covered Social insurance, Health insurance and Unemployment insurance since probation. Moreover, Compulsory insurance for employees is also filled by the company. You only need to bear PIT.\n- 13 months salary/year.\n- Discretionary bonus.\n- Employee referral bonus program (Very attractive bonus range: from 300USD to 1000USD).\n- Flexible working time: 5 working days/ week - from Monday to Friday (Time won\'t be your fear, because productivity is what we care about).\n- Annual leave: 15 days in 1st year, 17 days in 2nd year, and 20 days each year thereafter.\n- Sick leave: 5 days/year.\n- Delicious, fresh and free meals are served daily!\n- High-end workstation laptop and screens.\n- Equipment Allowance: 4,500,000 VND to pick your keyboard/ mouse/ headphone... in your own style.\n- Team building activities, staff trips, and company events across the year.\n- Other benefits: Sickness, funeral: support up to 2,000,000 VND/person; marriage, childbirth, and public holidays: up to 500,000 VND/person.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'UDIC Building, Hoang Dao Thuy Street, Trung Hoa Ward, Cau Giay District, Hanoi City, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(835, 189, 2, 'Embedded Project Management (MCU, C++)', 'Top 3 reasons to join us\n- Attractive Salary & Benefit\n- Yearly Performance Bonus (2 Times/Year)\n- Premium Health Insurance.\n\nJob description\n- Assist Product Management of Enterprise display devices with a sense of product ownership\n- Develop product Features for Tizen models with support of Platform team.\n- Execute Product commercialization following Samsung PLM process and phases \n- Software Configuration Management and Release/Build management.\n- Collaborate with the R&D, QA, and business team in delivery\n- Requirement gathering and analysis\n- Product feature specification update in relevant systems.\n- Prepare documentation for product releases.\n- Handling Market Support queries and drive critical market issues along with technical and support teams.\n- Keeping track of bug reports and allocating bug fixes to a release schedule\n- Working with distributed workforce [Korea, India , Poland , UK , China, US etc ] to accomplish new feature developments and enhancements in Product.\n- Should be able to narrow down the problem based on the analysis of the logs and code.\n- Others job assigned by Leader\n\nYour skills and experience\n- Bachelor’s degree in Computer Science, S/W Engineering or IT related field\n- Has at least one year of experience in embedded software development\n- We are OPEN for Experienced Embedded Engineer that plan to become Project Manager\n- Hands On experience on working on various microcontrollers/processors\n- Experience in SW development using C/C++, Debugging Tools\n- Hands-on experience on working with communication protocols like UART, SPI, I2C\n- Knowledge of MCU interrupt handling, bootloaders, flash operations and peripheral programming\n- Knowledge in DTV mobile connectivity technologies [like Miracast, DLNA etc] is a big plus\n- Knowledge about Linux build system is a big plus\n- Good in English communication for working\n\nWhy you\'ll love working here\n- Yearly Performance Bonus 2 times/year (up to 3-month salary) + 13th Salary. (At least 15 months).\n- Flexible working week policy.\n- Intensive Training Program.\n- Oversea Biz-trip\n- Linkedin E-Learning & Udemy unlimited access.\n- Premium Health Insurance.\n- 100% salary and mandatory social insurances in 2-month probation.\n- Daily shuttle bus from city center to company\n- Team Building Gifts quarterly.\n- Free luncheon.\n- Birthday Gifts.\n- Training Opportunities in Korea.\n- Take part in various significant activities such as SEHC Festival, SEHC Cup, Town Hall Meeting, Liên Quân Mobile Champion, SEHC Marathon, SEHC Hackathon, SEHC Home Town,....', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lot I-11, D2 Road, Saigon Hi-tech Park, Tang Nhon Phu B Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(836, 550, 2, 'Backend Golang Developer (OOP, PostgreSQL, MySQL)', 'Job description\n- Tham gia trực tiếp vào phát triển sản phẩm chiến lược của công ty, tiếp cận các sản phẩm về AI, các công nghệ mới nhất.\n- Làm việc cùng Tech Team trẻ trung, nhiệt huyết và năng động vô cùng.\n- Mức lương: 15 – 25 triệu\n\nMô tả công việc:\n- Tham gia phát triển các hệ thống backend sử dụng ngôn ngữ Golang.\n- Thiết kế và triển khai các dịch vụ microservice, xử lý hiệu năng cao, có khả năng mở rộng.\n- Tích hợp và xử lý dữ liệu qua các hệ thống message broker như Kafka.\n- Làm việc với Elasticsearch để xây dựng hệ thống tìm kiếm, phân tích dữ liệu real-time.\n- Thiết kế và tối ưu hệ thống cơ sở dữ liệu quan hệ (PostgreSQL, MySQL...).\n- Phối hợp với các team khác (Frontend, DevOps, QA) để đảm bảo chất lượng sản phẩm.\n- Tham gia review code, cải tiến kỹ thuật và hiệu năng hệ thống.\n\nYour skills and experience\nYêu cầu chuyên môn:\n- Có ít nhất 2 năm kinh nghiệm lập trình Golang trong môi trường sản phẩm thực tế.\n- Nắm vững lập trình hướng đối tượng (OOP), mô hình kiến trúc RESTful API.\n- Có kinh nghiệm làm việc với Kafka (producer, consumer, topic management...).\n- Hiểu biết về Elasticsearch (index, mapping, query, aggregation...).\n- Thành thạo cơ sở dữ liệu quan hệ như PostgreSQL, MySQL; biết thiết kế lược đồ, tối ưu query.\n- Có kinh nghiệm sử dụng Git, CI/CD cơ bản.\n- Tư duy logic tốt, chủ động, có tinh thần học hỏi và teamwork.\n\nĐiểm cộng\n- Biết thêm về Docker, Kubernetes, hoặc một số hệ thống message queue khác.\n- Đã từng tham gia vào hệ thống có lượng người dùng lớn, cần tối ưu hiệu năng.\n\nWhy you\'ll love working here\n- Làm việc từ thứ 2 đến thứ 6 (sáng 8h30, chiều 5h30)\n- Được đóng BHXH, BHYT, BHTN theo đúng luật BHXH\n- Các chế độ phúc lợi, thưởng sinh nhật, các ngày lễ 30/04, 01/05, 02/09, Tết dương lịch.\n- Có chế độ thâm niên, thưởng Tết cho nhân viên\n- Có cơ hội thăng tiến lên các vị trí cấp cao\n- Tăng lương theo năng lực và hiệu quả công việc\n- Các hoạt động tập thể: Teambuiding, Year end party\n- Được mua BH sức khỏe cao cấp\n- Môi trường làm việc chuyên nghiệp, lịch sự.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '24 Thể Giao, phường Lê Đại Hành, quận Hai Bà Trưng, Hà Nội, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(837, 551, 2, 'Fullstack Developer (PHP, Laravel, ReactJS/VueJS)', 'Top 3 reasons to join us\n1. Lấy con người làm trung tâm \n2. Cơ hội học tập\n3. Môi trường quốc tế \n\nJob description\n1. Dẫn dắt việc thiết kế, phát triển và triển khai các ứng dụng web có khả năng mở rộng cao.\n2. Xây dựng và duy trì các pipeline CI/CD để tự động hóa quy trình kiểm thử, xây dựng và triển khai.\n3. Quản lý và tối ưu hạ tầng bằng các công cụ như Docker, Kubernetes, Terraform hoặc tương tự.\n4. Giám sát hiệu suất ứng dụng và tình trạng hạ tầng; xử lý sự cố và triển khai các giải pháp phòng ngừa.\n5. Đảm bảo tuân thủ các nguyên tắc bảo mật trong quá trình phát triển và quản lý hạ tầng.\n6. Hướng dẫn, đào tạo các lập trình viên junior và cung cấp sự lãnh đạo kỹ thuật cho các dự án.\n7. Phối hợp chặt chẽ với khách hàng, quản lý dự án, QA và các bên liên quan khác để đảm bảo chất lượng sản phẩm.\n8. Tham gia review code, đưa ra quyết định về kiến trúc hệ thống và viết tài liệu kỹ thuật.\n\nSố lượng: 02  \n\nYour skills and experience\n1. Tối thiểu 5 năm kinh nghiệm phát triển phần mềm.\n2. Thành thạo với PHP và framework Laravel.\n3. Thành thạo với Vue JS hoặc React JS.\n4. Thành thạo làm việc với MySQL hoặc PosgreSQL, có khả năng thiết kế cơ sở dữ liệu, cải tiến hiệu năng truy vấn.\n5. Có kinh nghiệm vững chắc với các công cụ và quy trình DevOps: pipeline CI/CD, Infrastructure as Code (Terraform, CloudFormation), containerization (Docker), orchestration (Kubernetes), và các nền tảng đám mây (AWS, Azure, GCP).\n6. Thành thạo Git, kiểm thử tự động và chiến lược triển khai.\n7. Hiểu biết về các công cụ giám sát và logging (Prometheus, Grafana, ELK, CloudWatch, v.v.).\n8. Kỹ năng giải quyết vấn đề, debug và phân tích tốt.\n9. Có kiến thức về bảo mật trong DevOps và môi trường cloud.\n10. Kỹ năng giao tiếp và hợp tác tốt.\n11. Có kinh nghiệm với 1 số ngôn ngữ lập trình khác như Java, Python...\n12. Có kinh nghiệm với kiến trúc microservices.\n13. Hiểu biết về các công nghệ serverless (AWS Lambda, Azure Functions, v.v.).\n14. Có kinh nghiệm tối ưu hiệu suất và xử lý vấn đề mở rộng.\n\nWhy you\'ll love working here\n1. Mức lương: Từ 40 – 50 triệu VNĐ (Thỏa thuận dựa trên năng lực).\n2. Tham gia đầy đủ chế độ bảo hiểm xã hội, bảo hiểm y tế và bảo hiểm thất nghiệp \n3. Hưởng chế độ phúc lợi Lễ, Tết và thưởng theo quy định của Công ty.\n4. Nghỉ phép, nghỉ lễ theo Luật lao động Việt Nam.\n5. Xét tăng lương hàng năm theo năng lực\n6. Cơ hội thăng tiến nếu có thành tích làm việc tốt. Môi trường làm việc năng động, thân thiện, khuyến khích nhân viên phát triển và đóng góp ý kiến\n\nTHÔNG TIN CHUNG  \n1. Thời gian làm việc: Từ 08h30 đến 17h30 các ngày trong tuần (nghỉ thứ Bảy & Chủ Nhật)\n2. Được cung cấp thiết bị làm việc: laptop, PC…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'SUCED Building - 108 Nguyen Hoang, My Dinh 2, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(838, 235, 2, 'CV Phân tích và Triển khai BPM (Java/Business Analyst)', 'Phòng ban: CNTT\nBáo cáo cho: Trưởng nhóm BPM / Trưởng phòng Phát triển ứng dụng\nMục tiêu công việc: Tham gia phân tích nghiệp vụ, thiết kế quy trình và triển khai tự động hóa quy trình bằng nền tảng BPMN, đặc biệt là Camunda BPM. Hỗ trợ các đơn vị trong việc số hóa quy trình nghiệp vụ nhằm nâng cao hiệu quả vận hành và kiểm soát.\nNhiệm vụ chính:\n- Triển khai xây dựng BPMN cho các quy trình nghiệp vụ ngân hàng.\n- Tích hợp Camunda với các hệ thống hiện hữu (Core Banking, CRM, DMS...).\n- Theo dõi, giám sát và tối ưu hóa hiệu suất quy trình.\n- Phối hợp với các nhóm khác (BA, DevOps, QA,...) để đảm bảo hệ thống hoạt động ổn định và đúng yêu cầu.\n\nYour skills and experience:\n- Tốt nghiệp đại học chuyên ngành CNTT, Hệ thống thông tin hoặc tương đương.\n- Tối thiểu 1 năm kinh nghiệm làm việc với BPMN, ưu tiên có kinh nghiệm thực tế với Camunda Platform 7 hoặc 8.\n- Hiểu biết về BPMN 2.0 (Business Process Model and Notation) và các nguyên tắc thiết kế quy trình.\n- Thành thạo các công nghệ và ngôn ngữ lập trình liên quan như Java, Spring Boot, hoặc Groovy.\n- Kinh nghiệm làm việc với REST API và các dịch vụ tích hợp khác.\n- Kỹ năng giải quyết vấn đề và tối ưu hóa quy trình.\n- Có tư duy hệ thống, khả năng giao tiếp và làm việc nhóm tốt.\n- Ưu tiên ứng viên đã từng làm việc trong lĩnh vực ngân hàng/tài chính.\n\nQuyền lợi:\n- Cơ hội tạo ra dấu ấn trong hành trình sự nghiệp số của bản thân khi tham gia xây dựng các dự án ĐANG phát triển và là TRỌNG ĐIỂM của Ngân hàng (thay vì xây dựng từ giai đoạn đầu).\n- Cơ hội trải nghiệm các kiến trúc, công nghệ mới nhất trên thị trường Tài chính - Ngân hàng.\n- Cơ hội nhận gói thu nhập hấp dẫn cùng với rất nhiều chế độ phúc lợi toàn diện chỉ dành cho các CBNV.\n- Cơ hội đào tạo chuyên môn, học hỏi từ những chuyên gia đầu ngành, luân chuyển công việc sang các phòng ban khác phù hợp với lộ trình thăng tiến nghề nghiệp.\n- Cơ hội làm việc tại văn phòng làm việc đạt chuẩn Top A với các trang thiết bị máy móc hiện đại nhất, tiên tiến nhất, tham gia những hoạt động thường niên của Ngân hàng nhằm nâng cao đời sống CBNV.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'LPBank Tower, 210 Tran Quang Khai, Trang Tien, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(839, 552, 2, 'Senior Frontend Developer', 'Top 3 reasons to join us\n- Competitive compensation, 13-month salary\n- Premium health care insurance for you \n- US Product and friendly working environment\n\nJob description\nWhat you will do:\n- Build and extend the services, systems, and algorithms that power our delivery platform\n- Add new features to many of our web apps and build new web apps using existing apis or work with the backend team to design new apis\n- Build frontend components to reuse for many applications\n- Contribute to the current frontend/backend structure to improve to build applications Development of real-time processing systems (websocket/streaming events)\n\nYour skills and experience\nKnowledge and experience:\n- At least 5 years in front-end development and 3 years with ReactJS\n- Strong proficiency in front-end web applications development: HTML5, CSS3, JavaScript (ES6 or supersets like TypeScript)\n- Strong experience with ReactJs\n- Strong experience with state management like: redux/recoil/mobx....\n- Strong experience developing and integrating with APIs\n- Experience planning and writing unit, functional, and integration tests\n- Experience building software for the cloud (GCP or AWS)\n\nSoft skills:\n- Ability to explore new technologies and resolve technical challenges\n- Written English is a must to communicate with US\n- Ability to easily dive into code written in unfamiliar languages\n- Ability to manage multiple/competing priorities and make the right tradeoffs and timely delivery of features\n- Ability to partner with product management to determine feasibility and generate technical requirements\n- Great communication and documentation skills\n- Great attention to details\n- A commitment to learning and continuous self-improvement\n\nNice to have:\n- Experience working with geospatial data and location-based services\n- Experience with e-commerce, logistics, and logistics algorithms (e.g. capacitated VRP)\n- Good spoken English is preferable\n\nWhy you\'ll love working here\n- Flexible working hours, Monday to Friday\n- 100% salary in probation\n- 100% salary social insurance contribution\n- Premium health care insurance for you \n- 12 days of Annual leave + 05 days of Sick leaves covered by the Company + 12 days working remote per year\n- 13th month salary upon company\'s performance and your working time of the year\n- Competitive compensation\n- Macbook Pro + extra monitor + other devices needed\n- A lot of engagement activities: Happy team lunch, Monthly birthday party, Summer trip, Year-end Party,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '206A Nguyen Trai, Trung Van, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(840, 553, 2, 'UI-UX Designer (Sketch, Figma, Axure, Adobe suite)', 'Top 3 reasons to join us\n• Attractive salary & benefit\n• Dynamic and friendly working environment\n• High promotion opportunities\n\nJob description\n• Work closely with Product Managers, and Developers to deliver excellent user experiences\n• Create  and  or prototypes to articulate the desired experience to wide audiences\n• Knowledgeable in Design Toolsets: Sketch or Figma, Zeplin, InVision, etc.\n• Translate high-level requirements into beautiful, intuitive, and functional user interfaces\n• Conduct research to identify user requirements\n• Review the usability, visual language and integrity of the product regularly\n• Design and manage visual guidelines of the project\n• Implement and iterate on designs and flows to ensure consistency across product’s platforms.\n\nYour skills and experience\n• At least 2 year hands-on experience in #UI design of responsive  (Android/iOS)\n• Expertise in standard #UI software such as  suite (, , ), etc.\n• Understanding of web element properties, basic  ,  framework for responsive web (Nice to have)\n• English is requested\n• Proficiency in design tools: Figma, Adobe Creative Suite or similar.\n• Demonstrate a track record of delivering requirements in a dynamic environment.\n• Proficiency in typography, sketching, composition, layout, color, iconography, illustration, and the presentation of information is a plus.\n\nWhy you\'ll love working here\n• Full compulsory payment\n• 28 days leave\n• Meal and Laptop\n• Professional, young, dynamic and friendly working environment\n• Attractive salary and benefit.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '14 đường 39, Phường An Khánh, Tp. Thủ Đức, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(841, 245, 2, 'C Language Developer', 'We are looking for a Senior C Language Developer to join our LG CNS Vietnam Build Center. You will be working on high-performance system-level development with deep integration into network protocols and testing environments. The ideal candidate is a strong C programmer with high-level understanding of networking, packet analysis, and testing frameworks.\n\nDesign, implement, and optimize software modules in pure C for embedded or system-level applications.\n\nDevelop and maintain network-related features, including TCP/UDP stack handling.\n\nAnalyze and debug network traffic using tools like TCPDump, Wireshark, etc.\n\nIntegrate and apply testing frameworks/tools to validate and ensure code stability and performance.\n\nWork closely with global teams (Korea HQ) to gather requirements, align on architecture and deployment strategy.\n\nReview and maintain high standards of code quality, documentation, and security.\n\nParticipate in performance tuning and issue resolution in production-like environments.\n\n[Required]\nBachelor’s degree or higher in Computer Science, Software Engineering, or related field.\n5+ years of experience in C programming in Linux/Unix environments.\nStrong experience in network programming, including TCP/IP, UDP, socket programming.\nHigh-level understanding of TCPDump, Wireshark, and general packet analysis techniques.\nExperience with unit testing frameworks (e.g. CMocka, Unity) or custom test environments.\nGood debugging skills using GDB, Valgrind, or similar tools.\nFamiliarity with multi-threaded programming, memory management, and performance optimization.\nEffective communication skills in English (Korean is a plus).\n\nOpportunity\nAttractive salary and bonus will be discussed after going through CV & Interview\nTopik allowance\nReview capacity annually and adjust salary increases according to work performance.\nHealth care: Premium health insurance, Annual health check-up\nYoung working environment\nGood career development opportunities with interesting and challenging projects.\nEnglish, Korean, technical, soft skills training courses.\nOpportunity to learn special courses from LG CNS, new technology and security.\nGifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\nOutdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\nWorking hours: 8 hours from Monday - Friday (8 hours/day)\n\nLocation\nOnsite 15th Floor, Keangnam Landmark 72, Me Tri, Nam Tu Liem, Hanoi\n\nHiring Process\nBook an Interview Schedule with HR manager.\n1st interview with VN Senior Leaders (Offline meeting room)\n2nd Interview with Kr Senior PM (Online meeting room) *\nIf passed, negotiate salary and bonus.\nConfirm onboarding Date.\n\nWhy you\'ll love working here\n- Best remuneration: Periodically review and adjust salary once a year, PI bonus twice a. Allowances for lunch, transportation, and phone charges. Party with the team once a. Workshop travel for the whole company once a year. Bonuses/Gifts for holidays, International Labor Day, International Women\'s Day, etc.\n- High-class, modern office: 5-star standard office with modern equipment, large rest and entertainment areas (game area, karaoke room, reading room, cafe counter, snack bar, etc.) Meet all members\' needs, especially the office has an airy and beautiful view that is among the most beautiful in Hanoi.\n- Top equipment: Each employee is equipped with the latest generation LG Gram laptop and modern large LG screen.\n- Best working time: Work 8 hours/day (8:00 ~ 17:00), from Monday to Friday. No pressure to work overtime/weekends!\n- Flexible, youthful working style: LG CNS Vietnam members are mostly from the 9-10x generation, with a youthful, modern, and fair working style!\n- Creative environment, valuing individual opinions: With a young and talented team, we always appreciate the creativity and suggestions that members make.\n- Opportunities to work/study in Korea and abroad: With customers and projects mostly from abroad, your opportunities for training and onsite abroad will always be open!\n- Other: Happy hours every Friday, Team outing monthly, join clubs like football, badminton, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(842, 270, 2, 'Manual QA Engineer (Tester, QA QC, English)', 'As a Manual QA/QC Engineer, you will be responsible for the following tasks:\n- Develop and execute detailed test plans, test cases, and test scripts.\n- Collaborate with cross-functional teams to understand project requirements and ensure comprehensive test coverage.\n- Utilize Agile testing metrics to monitor and report on the quality of the software.\n- Identify, document, and track bugs and issues, ensuring they are resolved in a timely manner.\n- Conduct regression testing to verify that new features and bug fixes do not adversely affect existing functionality.\n- Work closely with developers and product managers to provide feedback and drive continuous improvement.\n\nYour skills and experience:\n- Agile Testing Metrics: Experience in applying Agile testing metrics to assess and improve software quality.\n- Software Testing Experience: At least 2 years of hands-on experience in manual software testing.\n- Domain Expertise: Experience in testing Insurance domains/projects (Must have)\n- Analytical Skills: Strong analytical and problem-solving abilities, with keen attention to detail.\n- Communication: Excellent written and verbal communication skills.\n- Team Player: Ability to work collaboratively in a team-oriented environment.\n- English Communication: Proficiency in English, with excellent written and verbal communication skills, essential for daily meetings and direct interactions with cross-country Managers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Long Tower, 101-103 Nguyen Cuu Van, Binh Thanh Dist., HCMC, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(843, 444, 2, 'Middle Java Developer', 'Tham gia phát triển dự án sử dụng Java.\nTham gia vào quá trình phát triển phần mềm: phân tích, thiết kế và nghiên cứu công nghệ mới.\nPhối hợp với nhóm để đảm bảo dự án đáp ứng thời gian với chất lượng và hiệu suất cao.\nCó khả năng lường trước và giải quyết những khó khăn có thể xảy ra trong suốt vòng đời của dự án.\nChi tiết cụ thể trao đổi khi phỏng vấn.\n\nTốt nghiệp các trường đại học/cao đẳng chuyên ngành công nghệ thông tin, khoa học máy tính,... hoặc các chuyên ngành khác tương tự.\nCó từ 3 năm kinh nghiệm với Java , có hiểu biết về Scala là 1 lợi thế.\nCó hiểu biết các hệ thống cơ sở dữ liệu: MySQL, PostgreSQL, Docker;\nƯu tiên có kinh nghiệm setup CI/CD hay server management;\nNắm vững lập trình hướng đối tượng OOP;\nCó khả năng sử dụng Anh đọc hiểu tài liệu. Có thể giao tiếp tốt là lợi thế rất lớn.\nƯu tiên có kinh nghiệm làm việc tại công ty outsource;\nTư duy logic tốt, học hỏi nhanh;\nCó khả năng tự nghiên cứu, phân tích và giải quyết vấn đề.\n\nMức lương: upto 35tr.\nReview lương 6 tháng/lần.\nQuỹ lương từ 14-16 tháng/năm.\nCó cơ hội phát triển career path nếu có mong muốn.\nThưởng quý, lễ, Tết, lương tháng 13.\nCác chế độ theo Luật Lao động: BHXH, ngày phép,...\nTrợ cấp gửi xe, trà cafe miễn phí, hỗ trợ các chi phí khác theo nhu cầu công việc.\nĐược tham gia các sự kiện, du lịch, team building, happy hours,...\nMôi trường làm việc trẻ trung, năng động.\nThời gian làm việc: 8h30 – 12h30; 14h00 – 18h00; từ thứ 2 đến thứ 6; 2 thứ 7 cách tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 4- Số 11 Nguyễn Xiển - Thanh Xuân - Hà Nội , Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(844, 191, 2, 'Middle Android Developer (Java/Kotlin)', 'Top 3 reasons to join us:\n- Môi trường trẻ trung, năng động\n- Không làm thứ 7, chủ nhật\n- Lộ trình thăng tiến rõ ràng\n\nJob description:\n- Tham gia vào toàn bộ vòng đời phát triển sản phẩm, từ lên ý tưởng, thiết kế, phát triển đến triển khai và bảo trì ứng dụng di động trên cả hai nền tảng Android.\n- Phối hợp trực tiếp với Development Lead để triển khai các tác vụ công việc hàng ngày.\n- Tối ưu hiệu năng (performance) và trải nghiệm người dùng (UX/UI) cho ứng dụng, đảm bảo khả năng đáp ứng lượng truy cập lớn (2 triệu MAU).\n- Xây dựng và triển khai các tính năng mới, đồng thời cải tiến các tính năng hiện có dựa trên phản hồi của người dùng và phân tích dữ liệu.\n- Đề xuất và áp dụng các giải pháp kỹ thuật, công nghệ mới (nếu có).\n- Phối hợp với Product Manager, UI/UX Designer và các thành viên khác trong team để thực thi roadmap sản phẩm.\n- Chủ động học hỏi, nâng cao kiến thức chuyên môn và có cơ hội chia sẻ, hướng dẫn các thành viên junior trong đội ngũ.\n\nYour skills and experience:\n- Độ tuổi: 25-30 (ưu tiên)\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc chuyên ngành liên quan.\n- Từ 3-5 năm kinh nghiệm làm việc trong lĩnh vực phát triển ứng dụng di động.\n- Thành thạo ngôn ngữ lập trình và nền tảng: Java/Kotlin cho phát triển Android.\n- Có kinh nghiệm làm việc với các ứng dụng có quy mô lớn, lượng người dùng cao và hiểu biết về các thách thức liên quan.\n- Hiểu biết về tối ưu hiệu năng (performance optimization) và quản lý bộ nhớ (memory management) trên nền tảng di động.\n- Có tư duy sản phẩm tốt, khả năng phân tích và giải quyết vấn đề kỹ thuật một cách hiệu quả.\n- Tinh thần trách nhiệm cao, chủ động trong công việc, có khả năng làm việc độc lập và phối hợp nhóm tốt.\n\nƯu tiên (điểm cộng) nếu ứng viên có:\n- Có kinh nghiệm làm việc với Flutter để phát triển ứng dụng cross-platform, sử dụng các công cụ phân tích như Firebase Analytics, Crashlytics.\n- Hiểu biết về A/B testing và các phương pháp tối ưu hóa tỷ lệ chuyển đổi.\n- Kiến thức về App Store Optimization (ASO), chiến lược push notifications để tăng tương tác người dùng.\n- Kinh nghiệm làm việc với caching mechanisms, tối ưu database, và API cho ứng dụng di động.\n\nWhy you\'ll love working here:\n1.  Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án\n- Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm theo năng lực.\n\n2.  Chế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn\n- Tham gia BHXH sau thử việc, 12 ngày phép năm.\n- Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ.\n- Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết...\n- Học miễn phí các sản phẩm ngôn ngữ của công ty.\n\n3.  Cơ hội phát triển bản thân:\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Môi trường product đi sâu chuyên môn về sản phẩm, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác  marketing, sales, chăm sóc khách hàng và khách hàng.\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp.\n- Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6.\n- Làm việc tại: Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Toà nhà Toyota Thanh Xuân - 315 Trường Chinh, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(845, 364, 2, 'Data Analyst', 'Job description\n• Communicate with clients and stakeholders to identify requirements for dashboards and reports.\n• Communicate effectively with Beyondsoft’s offshore team in Shanghai, China to report the progress and status of the projects.\n• Build and maintain reports and dashboards in Power BI to track traffic and other business metrics on daily/weekly/monthly basis\n• Analyze data and extract insights to help business team make better strategic decisions.\n• Troubleshoot report refresh failures and apply timely remediation.\n\nYour skills and experience\n• Bachelor\'s degree in a computer-related field. \n• 2 years+ experiences of work related to data analysis.\n• Familiar with database, especially Sqlserver,skilled in SQL programming.\n• Strong experience with PowerBI,skills in other visualization tools（like Tableau）are acceptable.\n• Fluent English, able to work and communicate with China or US team.\n• Excellent communication skills. \n• Ability to speak Mandarin will added advantage.\n\nWhy you\'ll love working here\n1. Innovative Work Culture: Join a team where creativity and innovation are at the heart of everything we do. Our IT company thrives on new ideas, and we encourage a collaborative environment where every voice is heard. You\'ll have the opportunity to work on cutting-edge projects that push the boundaries of technology. \n2. Career Growth & Learning Opportunities: We believe in the power of continuous learning. Whether it’s through mentorship, online courses, or access to industry conferences, we provide the tools you need to grow professionally. You’ll have opportunities to learn and advance in your career, all while working with some of the best minds in the industry.\n3. Flexible Work Environment: Work-life balance is key. We offer flexible hours, remote work options, and a supportive environment that adapts to your needs. Whether you\'re a night owl or an early bird, we trust our employees to manage their time in a way that allows for both productivity and personal time.\n4. Collaborative Team Spirit: We know that great things happen when people come together. Our teams are diverse, inclusive, and driven to succeed. From brainstorming sessions to cross-departmental collaboration, you’ll work with talented individuals who are passionate about what they do.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '32 Pham Ngoc Thach, Ward Vo Thi Sau, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(846, 515, 2, 'Network – System Administrator', 'We are looking for a Network System Administrator to be part of our expanding team. We are looking for people who share our passion and can help us achieve our goal. As a Network System Administrator, your responsibilities will be: Design, deploy, manage and maintain network systems (LAN, WAN, VPN, Wireless, Firewall, Load Balancer...). Monitor network performance, troubleshoot, optimize the system to ensure stability and security. Propose and deploy network security solutions to prevent security threats. Support users and other departments in the company on network-related issues. Research and test new technologies to improve network system efficiency. Performing disaster recovery operations and data backups. Troubleshooting, diagnosing and resolving hardware, network and system problems. Monitoring network performance to determine if adjustments need to be made. Knowledge of threat modeling, risk assessment methodologies, and security risk management. Check, update hotfixes and security patches for the server system periodically. Administer Domain, DNS, SSL. Configure and update Policies as required. Participate in identifying and applying solutions to optimize costs to ensure the safety of security infrastructure and server systems. Participate in developing processes, regulations, and instructions for system operation and administration.\n\nYour skills and experience: Bachelor\'s degree in Information Technology, Telecommunications, or a related field. Basic knowledge of networking, IT systems, and telecommunications. CCNP/Security+ certification or equivalent knowledge is preferred. Good knowledge and experience in Networking and Security. Have knowledge on Linux, Proxmox, VMware. Having Knowledge to advise team and solving technical issue independently. Strong problem-solving skills and attention to detail. Ability to work collaboratively in a fast-paced environment. Planning skills: Ability to plan to carry out personal tasks. Problem solving skills: Ability to handle problems (including risks) related to expertise and services based on flexible use of procedures and regulations to analyze and select appropriate methods. Communication skills: Ability to present, exchange information, and solve work effectively. Self-learning ability: Ability to self-learn and improve expertise and professionalism. Teamwork skills: Ability to coordinate and actively participate in group work as assigned. Basic English reading and understanding.\n\nWhy you\'ll love working here: Competitive salary, negotiable based on your competence. Performance-based bonuses (twice a year). Monthly lunch allowance (730,000 VND). Additional paid summer leave (based on seniority), in addition to 12 days of annual leave. Comprehensive health insurance package for employees and family members. Full statutory benefits: Social Insurance (SI), Health Insurance (HI), Unemployment Insurance (UI), annual health check-up. Company team-building activities and annual community events. Working hours: Monday to Friday, with 2–3 Saturday mornings per month. Access to internal training and development programs. Opportunity to work in a collaborative, product-focused environment where ideas and ownership are valued.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'BIDV Tower, 194 Tran Quang Khai, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(847, 480, 2, 'Senior iOS Engineer (Swift, Objective C, English)', 'Top 3 reasons to join us\n- Friendly and flexible hybrid working environment\n- Work with international clients and diverse teams\n- Competitive benefits\n\nJob description\n- Partner with the Project Manager toward improving and fulfilling the technical direction of the product\n- Be passionate about Mobile - iOS, stay relevant, and understand how to implement advancement for existing or new Application/Software design\n- Design, develop, review, implement, and manage iOS application code and services for production and pre-release environments\n- Working in a team of software engineers, product owners, and UI/UX designers in creating and continuously improving end-to-end solutions\n- Participated in Agile software development, prototyping, and code review with development teams to build scalable microservices-based products\n\nYour skills and experience\n- 4~YOE in iOS development, with a proven track record of delivering high-quality applications\n- Swift or Objective-C programing languages\n- SwiftUI and UIKit\n- Swift Combine and Swift Concurrency\n- iOS architecture patterns (e.g., MVC, MVVM, VIPER), Clean architecture, SOLID principles and experience in designing scalable, and maintainable applications\n- iOS Frameworks such as Core Data and Core Animation\n- Apple’s Design Principles and Application interface guidelines\n- Push Notifications and Cloud Messaging\n- RESTful APIs and JSON/XML data formats\n- Git and other version control\n- Experience working in an Agile development environment, unit testing, UI testing, and other testing methodologies, CI/CD, Project Management Tools\n- Good communication in English.\n\nWhy you\'ll love working here\n- Attractive salary and benefits packages, including full social insurance on salary.\n- 100% salary during Probation Period\n- Premium Healthcare and Accident insurance coverage.\n- 14 days of leave, including 12 days of annual leave and 2 personal leave days.\n- English-speaking working environment\n- Gifts on special occasions + holidays (Tet, Full-moon festival, Birthday, Christmas etc.)\n- Employee Referral Program\n- Additional bonuses. ( 13th bonus, Talented retention bonus)\n- Engaging team-building activities, company trips, and year-end parties.\n- Diverse training opportunities for technical and soft skills.\n- Commitment to community development, including regular charity initiatives and blood donation drives.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '314/6 Điện Biên Phủ, Phường 11, Quận 10, TP.HCM, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(848, 554, 2, 'Fullstack Dev (PHP, Laravel, Angular, ReactJS, Java)', 'Job description\n- Giám sát và duy trì hoạt động website.\n- Sửa chữa, bổ sung các tính năng của các website theo yêu cầu của team kinh doanh\nYour skills and experience\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ thông tin\n- Có ít nhất 1 năm kinh nghiệm ở vị trí tương đương (phát triển website,Vận hành Website,...)\n- Có kinh nghiệm về PHP (Laravel), Angular, ReactJS, Java (Spring Boot) là một lợi thế lớn.\n- Khả năng phân tích và giải quyết vấn đề kỹ thuật nhanh chóng, logic.\n- Kỹ năng giao tiếp và phối hợp tốt với các phòng ban.\n- Khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Tinh thần chủ động, trách nhiệm cao trong công việc.\nWhy you\'ll love working here\n- Mức lương cạnh tranh từ 8-15tr, tương xứng với năng lực và kinh nghiệm.\n- Lương tháng 13 và thưởng hiệu suất theo kết quả kinh doanh.\n- Được làm việc trong môi trường năng động, trẻ trung, chuyên nghiệp.\n- Cơ hội phát triển bản thân, học hỏi và tiếp cận các công nghệ mới.\n- Được đóng đầy đủ BHXH, BHYT, BHTN theo quy định của pháp luật.\n- Các chế độ phúc lợi khác: du lịch hàng năm, teambuilding,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, số 31 ngõ 135 Đội Cấn, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(849, 555, 2, 'Software Engineer (Java, Python, C++) - Up to 50M', 'Job description\n- Tham gia phân tích, thiết kế kiến trúc và phát triển các hệ thống phần mềm của công ty.\n- Đảm bảo chất lượng mã nguồn, hiệu năng và khả năng mở rộng của hệ thống.\n- Viết tài liệu hướng dẫn vận hành, khai thác.\n- Đảm bảo phát triển phần mềm tuân thủ theo các tiêu chuẩn (An toàn thông tin, công nghệ).\n- Đề xuất các cải tiến kỹ thuật, công nghệ mới nhằm nâng cao hiệu suất làm việc và chất lượng hệ thống..\n- Đào tạo dev level thấp hơn\n\nYour skills and experience\n- Tốt nghiệp Đại học bằng khá trở lên chuyên ngành CNTT, ĐTVT, Toán tin Ứng dụng\n- Có ít nhất 2 năm kinh nghiệp phát triển ứng dụng bằng các ngôn ngữ: Java, Python, C++\n- Có kiến thức chuyên sâu về cấu trúc dữ liệu và giải thuật, quy trình phát triển phần mềm, Design Patterns, Cloud và mạng máy tính.\n- Kinh nghiệm về phát triển các hệ thống Microservice và SOA\n- Kỹ năng giải quyết vấn đề, dẫn dắt và làm việc nhóm\n- Thành thạo một trong các công nghệ Webservices (SOAP/RESTful), Websocket, Hibernate, JPA, HTML5/CSS3, Spring MVC, Struts\n- Thành thạo một trong các hệ quản trị CSDL quan hệ: Oralce, MySQL, SQL Server\n- Khả năng phân tích, giải quyết vấn đề tốt, tư duy hệ thống, chịu được áp lực cao.\n- Tiếng anh tương đương 550 TOEIC trở lên.\n\nƯu tiên:\n- Tốt nghiệp các trường: Đại học Bách khoa Hà Nội, Đại học Công nghệ - ĐHQGHN, Học viện Bưu chính Viễn thông, FPT, …\n- Có kinh nghiệm xây dựng và triển khai các hệ thống kiến trúc Microservice\n- Đã làm việc theo Agile, có kinh nghiệm sử dụng Jira, Jenkin, …\n- Năng động, sáng tạo và có khả năng tự nghiên cứu\n- Có các chứng chỉ quốc tế về lập trình và cơ sở dữ liệu.\n\nWhy you\'ll love working here\n- Thu nhập từ 18M up to 50M.\n- Tham dự các dự án lớn, ứng dụng các công nghệ hàng đầu.\n- Lộ trình thăng tiến và phát triển sự nghiệp.\n- Chế độ nghỉ mát và khám sức khỏe, đóng BHXH theo quy định của Luật lao động.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà 3B, khu đô thị Resco, đường Phạm Văn Đồng, Bac Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(850, 556, 2, 'Software Dev (C#/JS/PHP/ReactJS) – Japan Onsite – N3', '- Địa điểm làm việc: Nagoya (Nhật Bản)\n- Nhận ứng viên ở cả Hà Nội , Đà Nẵng, Hồ Chí Minh và trên Toàn Quốc\n- Phát triển và nâng cấp hệ thống Website, WebApp theo yêu cầu khách hàng.\n- Phát triển các giải pháp về ERP(Enterprise Resource Planning), PLM (Product Lifecycle Management) cho các khách hàng là các công ty lớn ở Nhật.\n- Các giải pháp về tự động hóa công nghiệp, thông minh, quản lý và điều khiển hệ thống,dây chuyền sản xuất thông qua giao diện người dùng.\n\n- Tiếng Nhật tương đương với N3 trở lên (bắt buộc, nếu chưa có bằng thì yêu cầu trình độ giao tiếp tương đương level N3 ).\n- Tối thiểu 3 năm kinh nghiệm Web Developer (Backend).\n- Biết ít nhất về 1 front-end framework (Reactjs, ...).\n- Thành thạo ít nhất 1 trong các ngôn ngữ C#, JS, PHP.\n- Có tư duy về kiến trúc hệ thống web, có khả năng tối ưu tốc độ, số lượng users, request.\n\n- Tham gia các khóa đào tạo tiếng Nhật miễn phí, giúp nâng cao kỹ năng giao tiếp và làm việc hiệu quả hơn.\n- Làm việc cùng các kỹ sư cao cấp về AI, Embedded, nâng cao chuyên môn và mở rộng kiến thức công nghệ.\n- Mức lương từ 320-500 man/1 năm\n- Nghỉ thứ 7 và Chủ nhật\n- Có 3 đợt nghỉ dài trong năm (mỗi đợt khoảng 9-11 ngày nghỉ);\n- Xét tăng lương 1 lần/ năm, Thưởng 2 lần/năm;\n- BHXH, y tế đầy đủ;\n- Khám sức khỏe hàng năm;\n- Có trợ cấp nhà ở, đi lại, vợ, con;\n- Có kí túc xá cho các bạn độc thân;\n- Team building theo quý, du lịch hàng năm, và rất nhiều các hoạt động vui chơi khác.\n- Cơ hội thăng tiến rõ ràng, phát triển sự nghiệp lâu dài tại Nhật Bản.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3A, số 4 ngõ 82 phố Dịch Vọng Hậu, Phường Dịch Vọng Hậu, Cau Giay, Ha Noi; ., District 1, Ho Chi Minh; 167 Phan Chu Trinh, Cam Le, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(851, 356, 2, 'Middle/Senior AI Engineer', 'Top 3 reasons to join us\n- Attractive salary, benefits, hybrid working\n- Technical training sessions (internal – external) \n- PVI Healthcare insurance\n\nJob description\n- Join in developing and applying the ML/DL techniques to resolve our client’s business problems such as building chatbot systems, LLM/Prompt, OCR systems, fraud detection systems, facial recognition systems…\n- Join in developing some internal products applying AI models\n\nYour skills and experience\n**MUST-HAVE SKILLS**:\n- Have programming skills in one of these languages: Python, Java...\n- At least 2 years of experience working with AI/ML projects as a Data Engineer, Research Engineer, or Software Engineer.\n- Have experience with one of ML/DL Frameworks: Tensorflow, Pytorch, Keras, scikit-learn, Pandas, Langchain, LlamaIndex…\n- Have experience working with OpenAI, Gemini, any LLM... to build agents, workflows, or RAG systems.\n- Have experience with one of chatbot building frameworks or services like Rasa, Dialogflow, Transfomer, BERT, LLM/Prompt…\n- Familiar with OCR algorithms or services: OpenCV, Tesseract, Textract (AWS), Google Cloud Vision, PaddleOCR.\n- Experience with common development tools: Linux, GPU server, Google Colab, Jupyter, Git, Docker.\n- Good English proficiency and communication skills.\n\n**NICE TO HAVE:**\n- Experience with backend web development (Flask, Django, FastAPI)\n- Experience with SkyPilot, Triton, Sherpa, Icefall\n- Experience with SQL database (PostgresSQL, MySQL), NoSQL database (MongoDB), Vector database (Chroma, LanceDB, Qdrant...)\n- Experience with building APIs and services using REST, SOAP, etc.\n- Experience in MLOps system: MLflow, DVC, Feature Store, Airflow, CI/CD...\n- Experience in Generative AI, Large Language Model, Prompt Engineer, Diffusion model, HuggingFace, Ollama, LlamaCPP\n\nWhy you\'ll love working here\n**Competitive Salary and Brilliant Health Benefits**\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan \n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program \n- The staff of the quarter and year reward\n\n**Progressive and Fun Working Environment**\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support. \n- Surrounded with friendly, open-minded, young and supportive colleagues \n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\n**Valuable Training**\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '17th Floor, 36 Tran Quoc Toan, Hai Chau, Da Nang; Orchard Parkview, 130 – 132 Hong Ha, Ward 9, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(852, 439, 2, 'Automation Test Engineer (Java, Tester, QA QC) ~ $2000', 'Top 3 reasons to join us\n- Attractive, competitive salary Up to $2000\n- Professional environment\n- Annual 5-star-company trip\n\nJob description\n- Tự động hóa các trường hợp kiểm thử nhằm đảm bảo chất lượng hệ thống.\n- Đưa ra các giải pháp kiểm thử tự động trên các thành phần khác nhau của hệ thống.\n- Tích hợp với các hệ thống quản lý kiểm thử, hệ thống thích hợp liên tục (CI / CD).\n- Tham gia thiết kế giải pháp đáp ứng cho các nhu cầu nghiệp vụ.\n- Tìm hiểu các công nghệ mới nhất để áp dụng hệ thống hiện tại.\n\nYour skills and experience\n- Bắt buộc\n  - Tốt nghiệp các chuyên ngành công nghệ thông tin/kỹ thuật.\n  - Nắm vững các khái niệm lập trình hướng đối tượng, các nguyên tắc thiết kế SOLID.\n  - Nắm vững các framework kiểm thử. Ưu tiên Serenity JUnit/Serenity Screenplay pattern.\n- Cần có\n  - Có kinh nghiệm thực hiện kiểm thử tự động trên UI/API/Contract.\n  - Hiểu các kỹ thuật kiểm thử cơ bản.\n  - Thành thạo ngôn ngữ lập trình Java.\n  - Có kinh nghiệm làm việc với hệ thống microservice.\n  - Có kinh nghiệm làm việc với mô hình Scrum.\n  - Có kinh nghiệm làm việc với các công cụ\n    - CI/CD: Jenkins pipeline.\n    - Message queue: Kafka / Rabbit / Active.\n    - Database: Oracle / MS SQL / Postgres / Redis.\n    - Contract test: Pact.\n    - Docker / Kubernetes.\n    - Git / Jira / Confluence.\n- Kỹ năng mềm\n  - Đam mê công nghệ.\n  - Lười test thủ công.\n  - Cởi mở, thân thiện, giao tiếp tốt.\n  - Thích lĩnh vực tài chính.\n\nWhy you\'ll love working here\n- Review lương 1 lần/ năm\n- Cán bộ nhân viên sẽ có từ 12- 15 ngày phép/ năm\n- Bảo hiểm AON cho Cán bộ nhân viên\n- Công ty có các CLB thể thao sinh hoạt hàng tuần (đá bóng, chạy bộ, cầu lông)\n- Team building 1 lần/ 1 năm theo tiêu chuẩn 5 sao\n- Môi trường làm việc trẻ, năng động, cơ hội phát triển cao', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hội sở Techcombank, 6 Quang Trung, Trần Hưng Đạo, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(853, 414, 2, 'Lead ERP Odoo Consultant', 'Top 3 reasons to join us\n- Utilization Bonus , 13th salary\n- Weekly English training with foreign.\n- Healthcare insurance (PTI) for you and your family\n\nJob description\n- If you\'re passionate about solving business challenges with scalable ERP solutions\n- If you enjoy leading teams and driving project success from discovery to delivery\n- If you\'re eager to collaborate directly with US clients and global teams\n- If you want to work at the intersection of consulting, technology, and leadership\n- If you have strong communication and project management skills in English\n\nThen this Lead Consultant role at Novobi is the perfect opportunity for you!\n\nWhat will you do?\n- Collaborate with clients to analyze business requirements and translate them into tailored ERP (Odoo) solutions.\n- Lead ERP discovery and implementation projects, from requirement gathering and system configuration to user adoption and support.\n- Conduct analysis, document, and map client workflows, ensuring the system meets business needs and enhances operational efficiency.\n- Provide strategic guidance on ERP best practices, process optimization, and integration planning.\n- Manage project timelines, budgets, deliverables, and stakeholder communications to ensure success.\n- Coordinate global cross-functional teams to ensure project milestones are met.\n- Develop and implement change management strategies to support user adoption of the new system.\n- Provide regular project status updates to executive management.\n- Lead workshops and training sessions for clients\' key stakeholders and end users to ensure successful adoption and utilization of the ERP system.\n- Provide ongoing support and troubleshooting assistance to clients post-implementation, addressing any issues or concerns in a timely manner.\n- Mentor junior consultants and contribute to internal knowledge sharing and team growth.\n\nYour skills and experience\nWhat skills will you gain?\n- Strategic Leadership & Project Management\n➢ Planning and leading multi-phase ERP projects for US clients.\n➢ Managing risks, resources, and stakeholder expectations in real-world enterprise environments.\n➢ Delivering solutions that align with both technical requirements and business goals.\n\n- Client Engagement & Communication\n➢ Leading client-facing activities including discovery, training, and support.\n➢ Enhancing your English communication skills in a 100% English-speaking environment.\n➢ Building long-term client relationships through trust and value delivery.\n\n- ERP & Business Process Expertise\n➢ Deepening your understanding of ERP systems (especially Odoo) across multiple domains like manufacturing, supply chain, and retail.\n➢ Learning to design scalable solutions that streamline core business functions.\n➢ Handling end-to-end processes: requirements, data migration, configuration, testing, and support.\n\n- Team Development & Mentorship\n➢ Supporting team members’ growth through coaching, feedback, and knowledge sharing.\n➢ Leading by example in a high-performance consulting environment.\n\nQualifications\n- Exceptional communication and interpersonal skills, with the ability to effectively interact with clients, stakeholders, and team members at all levels in English.\n- Ability to work collaboratively with global cross-functional teams.\n- Excellent analytical skills with a keen attention to detail and the ability to solve complex problems independently.\n- Detail-oriented, with strong project management and organizational skills.\n- Good understanding of business processes across various industries and the ability to translate requirements into ERP solutions.\n- Willingness to work at night to communicate with clients in the US several days a week.\n- Bachelor\'s degree in Computer Science, Information Systems, Business Administration, or related field preferred.\n- Has a proven track record of at least 3-5 years of experience managing business solution implementation projects.\n\nPREFERRED QUALIFICATIONS\n- Prior experience in consulting or professional services is preferred.\n- Experience with manufacturing, supply chain, retail, or field-service operations is preferred.\n- Experience with ERP implementation is a plus, ideally with the most prominent and widely used in the industry such as Odoo (preferred).\n\nWhy you\'ll love working here\n- Very competitive salary commensurate with experience.\n- Comprehensive benefits package including:\n  - Private healthcare insurance (PTI) for you and your family\n  - Social insurance with full salary\n- Technical and soft skills training and professional certifications supported (e.g. weekly English classes).\n- Flexible working time (9:30 AM to 6:00 PM, Monday to Friday).\n- Annual leave & work from home up to 54 days/years + 1 more day after every 2-year.\n- Opportunities for professional development and career advancement.\n- Other employee benefits: sickness, birthday, International Women’s Day (March 8th), Vietnam Women’s Day (October 20th), Children\'s Day (June 1st), and family emergencies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'HAGL Building, 6th & 7th Floor, 3/1 Thanh Thai, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(854, 458, 2, '[HCM] Java Developer (Middle) | Up to 35M VND', 'Chúng tôi đang tìm kiếm Lập trình viên Java tham gia vào dự án công nghệ trong lĩnh vực du lịch và thương mại điện tử.\n\nTriển khai kiến trúc phần mềm cho hệ sinh thái của dự án thương mại điện tử về du lịch: Đặt vé máy bay, khách sạn và du lịch online trong nước (Nhật Bản) và quốc tế.\nThiết kế, phát triển và tối ưu hóa hiệu suất sản phẩm trên nền tảng Java.\nLuôn cập nhật các công nghệ, kỹ thuật mới nhất.\nĐược đào tạo trở thành kỹ sư Fullstack.\nDự án dài hạn, công việc ổn định.\nKỹ thuật chính sử dụng trong dự án:\n- Fullstack FE (Python pyramid, backbone (Framework JS), jinja2 template.\n- BE (Java) Framework chính: Seasar của Nhật 90% (tương tự Spring Boot), Spring Boot (10%)\n\nBạn cần có:\nTốt nghiệp Đại học chuyên ngành CNTT hoặc tương đương.\nCó tối thiểu 3 năm kinh nghiệm lập trình với ngôn ngữ Java.\nCó kiến thức tốt về thuật toán, lập trình hướng đối tượng (OOP) Java/JEE và Spring (DI, AOP, IoC)\nKinh nghiệm làm Web service: MVC, RESTful (SOAP)\nDB: SQL/JDBC và ORM/Hibernate (MySQL,Oracle)\n\nBạn có là lợi thế (Không bắt buộc):\nKiến thức HTML, CSS, JavaScript\nBiết hoặc muốn tìm hiểu về frameworks JS (Angularjs, VueJS,BackboneJS).\nApache Tomcat, Jboss…\n\nPhúc lợi – Mức lương cạnh tranh và nhiều gói chế độ hấp dẫn khác;\nPhát triển cá nhân – Cơ hội tiếp cận nhiều công nghệ mới và nhiều cơ hội thử thách với các dự án khác nhau;\nMôi trường – Cơ hội làm việc trong môi trường chuyên nghiệp, sáng tạo, đa ngôn ngữ – Nơi mỗi cá nhân, tập thể tại Hybrid Technologies cùng nhau phát triển và nỗ lực hiện thực hóa giấc mơ chung.\n\nGói phúc lợi hấp dẫn mà chúng tôi mang tới cho bạn:\nChế độ lương – thưởng: Mức lương cạnh tranh & hấp dẫn. Lương tháng 13 và các khoản thưởng khác theo quy chế công ty. Phụ cấp ăn trưa, gửi xe hay quà tặng các ngày lễ trong năm (8/3, 20/10, Trung Thu, …). Chế độ tăng ngày phép theo thâm niên.\nĐánh giá hiệu suất công việc: 2 lần/năm.\nChăm sóc sức khỏe: Gói bảo hiểm sức khỏe toàn phần dành cho nhân viên & mở rộng dành cho người thân nhân viên có thâm niên làm việc. Khám sức khỏe định kỳ hàng năm.\nHoạt động ngoại khóa do công ty tài trợ: Hoạt động từ thiện. Các giải đấu do công ty tổ chức: Bóng đá, Bóng bàn, E-sport … \nMôi trường làm việc: Không gian chung và không gian làm việc xanh-sạch-năng động, cùng trang thiết bị làm việc luôn được cập nhật mới nhất.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Dong Nhan Building, 90 Nguyen Dinh Chieu, Da Kao, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(855, 557, 2, 'Senior Infrastruture Engineer (AWS, Azure, Linux)', 'Founded in 2009 in Orange County, California, Yes4All has grown to become one of the leading names in the fitness, furniture and lifestyle market. A significant player in e-commerce since 2016, we were among the first invited to Amazon’s Vendor Central (AVC) program and have been a top-12 Sports & Outdoors brand on Amazon since 2021.\n\nWe expanded our presence across the USA and 17 international markets, reaching $132M GMV with 74% YoY growth in 2023, achieving 26% YoY GMV growth in 2024 and a 3.5X increase in EBITDA. With 2,000+ SKUs on platforms like Amazon, Wayfair, and Walmart, we continue to scale.\n\nGuided by Mr. Nguyen Chi My, we leverage Vietnam’s competitive strengths and strategic manufacturing partnerships to drive innovation. Beyond our own success, we empower Vietnamese SMEs, providing expertise to scale internationally.\n\nAt Yes4All, our people are at the heart of our success. We empower our team members to Shine The S.E.A by embracing extreme ownership, which fosters authentic and trust-based collaboration and drives sustainable value creation. As part of the CriTICal SquaD, our members embody core competencies that set us apart. We foster a dynamic and supportive environment, encouraging individuals to grow, take initiative, and make incredible impacts.\n\nOur vision: To become the global leader in innovative products and services, delivering excellence, quality and affordability for all.\n\nOur mission: To empower global consumers with access to quality and affordable products through innovative e-commerce solutions, while fueling the success of innovators, brands and manufacturers.\n\nJoin us and be part of a passionate team that is redefining the fitness and lifestyle industry!\n\nInfrastructure Design: Design, implement, and maintain the network system to architect a scalable, secure, and resilient infrastructure that meets business and technical requirements, whether on-premises, hybrid, or in the cloud.\n\nInfrastructure Implementation: Manage and configure infrastructure using infrastructure-as-code tools such as Terraform, Ansible, or CloudFormation.\n\nSystem Administration: Monitor and maintain the health and performance of production systems, identifying and resolving issues proactively.\n\nNetwork Management: Managing and maintaining network systems to ensure efficient, secure, and reliable operation through Configuration, Fault detection and resolution, Device and inventory management, Policy enforcement, and Performance monitoring.\n\nServer Management: Managing physical and virtual servers running various operating systems, such as Windows Server, Linux, and Unix. Installing and configuring server software, monitoring server performance, and performing regular maintenance tasks.\n\nStorage Management: Managing storage systems, including SAN, NAS, and cloud storage solutions. Configuring storage arrays, optimizing storage performance, and implementing data backup and disaster recovery solutions.\n\nSecurity and Compliance: Implementing security measures to protect the company’s infrastructure from cyber threats and vulnerabilities. Ensuring compliance with relevant regulations and standards, such as GDPR, HIPAA, and PCI DSS.\n\nCollaboration and Communication: Collaborating with other members of the IT team, as well as with stakeholders from different departments. Communicating effectively with team members, management, and end-users to understand requirements and provide support.\n\nDocumentation and Reporting: Documenting infrastructure configurations, procedures, and troubleshooting steps. Generating reports on infrastructure performance, capacity, and usage metrics.\n\nYour skills and experience\n\nKnowledge\n\nBachelor’s degree in Computer Science, Information Technology, or a related field.\n\nSkills\n\nFamiliarity with network systems like firewalls, switches, and servers, and knowledge of cloud platforms such as AWS, Azure, or Google Cloud.\nStrong knowledge of Infrastructure & Systems such as Windows Server and Linux administration, Active Directory, DNS, DHCP, Group Policy …; Networking with Routing, switching, VLANs, firewalls; LAN/WAN design and configuration …\nProficiency in Disaster Recovery & High Availability.\nHands-on experience with CI/CD tools like Jenkins, GitLab CI/CD or CircleCI.\nExcellent problem-solving skills and the ability to work well under pressure.\nStrong communication and collaboration skills.\nExperience\n\nAt least 4 years of experience in IT infrastructure design, implementation, and administration.\n\nWhy you\'ll love working here\n\n1. FOR YOU TO JOIN\n\nFinancial Well-being: A competitive salary with 13th month salary, annual performance bonus and a variety of allowances.\nSalary review: annually or on excellent performance.\nActivities: company trips, team-building, and other customized monthly bonding events.\nAnnual leaves: 16 days off and 01 Birthday Leave per year.\nHealthcare: annual health check, insurance according to Labor Law and extra PTI Insurance package.\nWorking Environment: dynamic, friendly environments with working time flexibility, and other perks include snacks, coffee, and healthy food provided daily suited for hardworking, fun, and team collaboration.\n\n2. FOR YOU TO GROW\n\nAmbition: We are now keeping on with our hyper growth to multicategory, multichannel, multimarket, and expanding into the world largest e-commerce enabler. Hence, there will continuously be opportunities to challenge yourself, learn new skills and knowledge.\nChallenges: Your voice can always be heard as we embrace the eagerness of learning and sharing. You can be your own boss and create your own value with the ability to take initiative and make decisions in all aspects of work.\nChances: Be led and coached by experienced and inspirational leaders and participate in various training courses where you can enlarge your knowledge and experience in the E-commerce and Supply Chain industry.\n\n3. FOR YOU TO STAY\n\nPeople: Having a headquarter in the US and an operation office in Vietnam, our team is young and highly motivated. You will be working with and alongside members having experiences from International Corporations or high profile from Vietnam that share the same passion and dedication.\nCulture: Our working environment is humble, collaborative and 100% healthy. We promote Exchange & Speak out, you can receive transparent and supportive feedback so you can perform the best.\nCareer path: Provide you with a great career path, open to rotating for your better understanding of the company and contribute across many of our functions.\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '127 Hong Ha, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(856, 207, 2, 'Senior AI Engineer (Python/C++/C#)', 'Top 3 reasons to join us\n• Lộ trình phát triển sự nghiệp đa chiều\n• Cơ hội đào tạo, công tác tại Nhật, Singapore, Mỹ..\n• Mức lương hấp dẫn, chế độ thưởng dựa trên năng lực\n\nJob description\nResearch and develop AI / Deep Learning / Machine Learning applications for various business, product, service of Panasonic (Image processing, NLP, voice recognition, embedded AI).\n\nYour skills and experience\nMust have\n• At least 2 years experiences in Digital Image Processing and Computer Vision.\n• Good programming skill in one of languages C, C++. C#. Python.\n• Familiar with Digital Image Processing, Computer Vision, Machine learning, Deep Learning (2D & 3D, OpenGL, Point cloud, etc).\n• Experiences with Computer Vision projects like Image Segmentation, Object Detection, Image Retrieval, Image Classification with Opencv library is strong plus.\n• Experiences with common Deep Learning frameworks (OpenCV, Tensor Flow, Pytorch, etc).\n\nNice to have\n• Experience in development and optimization of AI, Deep Learning or Machine Learning into embedded system such as Jetson TX board, FPGA board, ARM board, DSP board is a strong plus.\n\nWhy you\'ll love working here\nPanasonic R&D Center Vietnam was established in April 2007, is a company specializing in R&D of Panasonic Group in Vietnam with the aim of enhancing R&D activities in the field of digital home appliances, automation, mobility in Vietnam, providing R&D services for software solutions in today\'s hottest fields such as AI, Cloud, IoT in a chain of R&D centers of worldwide corporations.\n\n1. Career Path Development\n• Long-term multi-career roadmap;\n• Learning & development (Language Training, Technical Training, Soft-skill Training, On-job Training, etc.)\n• Oversea business trips (Japan, China, Singapore, US, Mexico, EU, etc.)\n\n2. Work-life Balance\n• Flexible working time that supports work-life balance (Core time: 9:00-16:00; 5 days from Monday - Friday/ week)\n• Additional special holiday\n\n3. Compensation package\n• Attractive salary  \n• Competitive bonus package depend on abilities, performance and competencies\n• Diversified allowance scheme\n\n4. Wellness\n• Well-protected with 24/7 personal accident and medical care insurance;\n• Well-designed Annual Health Check-up program;\n\n5. Activities\n• Team-building activities; Birthday Party; Year-end party; Sport Day/ Family Day\n• Summer Vacation (Trip to famous tourist spots domestic/ overseas,…)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lotte Tower, 54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(857, 558, 2, 'Software Developer (PHP, Laravel, NodeJS)', '1 - Tham gia phát triển, bảo trì, nâng cấp các ứng dụng phục vụ ngành Logistics trên nền tảng PHP, Laravel hoặc Nodejs (bao gồm cả frontend và backend)\n2 - Xây dựng các sản phẩm có số lượng lớn user sử dụng\n3 - Nghiên cứu, phát triển và ứng dụng các công nghệ mới AI, ML…\n4 - Thực hiện các công việc khác liên quan (phân tích, thiết kế, viết tài liệu kỹ thuật liên quan đến dự án, …. ) theo yêu cầu từ cấp trên.\n\n1 - Có kinh nghiệm làm việc với PHP, Laravel hoặc NodeJS\n2 - Nắm vững cơ sở dữ liệu MySQL, MongoDB\n3 - Am hiểm các design pattern phổ biến: Singleton, Factory, Adapter, Strategy,...\n4 - Có tư duy hệ thống & logic tốt\n5 - Có tư duy thiết kế APIs, thiết kế kiến trúc hệ thống phần mềm, đáp ứng khả năng mở rộng và số lượng người sử dụng lớn\n6 - Có kỹ năng bảo mật hệ thống phần mềm: CSRF, DDoS, SQL Injection,....\n7 - Có khả năng làm việc độc lập & làm việc nhóm\n8 - Chịu được áp lực công việc cao.\n\n1 - Lương: Theo năng lực\n2 - Review lương hàng năm\n3 - Được tham gia BHXH, BHYT\n4 - Hưởng lương tháng 13 theo chính sách Công ty\n5 - Làm việc trong môi trường trẻ, đồng nghiệp thân thiện\n6 - Được sử dụng miễn phí các dịch vụ hồ bơi, tập gym tại nơi làm việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '346 Bến Vân Đồn, P1, Q4, HCM (Lầu 5, Block A1), District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(858, 353, 2, 'Backend Developer (Java)', 'Top 3 reasons to join us\n- Môi trường làm việc thân thiện, chuyên nghiệp\n- Lương thưởng tương xứng năng lực làm việc\n- Có cơ hội phát triển bản thân\n\nJob description\n- Các dự án cần sự xây dựng backend hỗ trợ (kết nối đối tác) hoặc các dự án đã có sẵn nhân sự front-end; đòi hỏi nhân sự chuyên trách phát triển back-end\n- Phát triển các nội dung xử lý phía back-end theo yêu cầu dự án\n- Phát triển API kết nối với front-end hay đối tác\n- Đảm bảo các tiêu chuẩn bảo mật và mã hóa\n- Tuân thủ quy trình/quy định của HDBank\n\nYour skills and experience\n- Có ít nhất 3 năm kinh nghiệm trong lĩnh vực phát triển phần mềm ở vị trí backend\n- Đã từng tham gia ít nhất 4-5 dự án trong đó đảm nhiệm việc phát triển back-end; hoặc 2 dự án lớn (có 5 người tham gia trở lên)\n- Thành thạo với ngôn ngữ lập trình .Net/Java\n- Có kinh nghiệm về PL/SQL \n- Có kinh nghiệm phát triển  API Web Services, tương tác với API và sử dụng thành thạo các công cụ lập trình như Eclipse, Netbean\n- Thành thạo về Java core Back-End, xử lý tốt Multithread (Xử lý tối thiểu 1000-2000 giao dịch cùng lúc), Multi-processing, cơ chế Hash table, cơ chế xử lý file.\n- Có kinh nghiệm về các tiêu chuẩn bảo mật\n- Thành thạo việc thiết kế CSDL trên DB Oracle, MS SQL …\n- Có kinh nghiệm làm việc với các hệ điều hành Enterprise Linux, HP-UX\n- Có kinh nghiệm về SVN, GIT, Jira;\n- Có kinh nghiệm với các quy tắc thiết kế OOP;\n- Có kinh nghiệm về các dự án ESB, Open API\n- Có hiểu biết về Docker và Microservices\n- Có hiểu biết vẽ MQ, cache...\n- Có hiểu biết về mockup API\n- Thành thạo việc xây dựng các tài liệu đặc tả kỹ thuật (Technical Specification Document), bao gồm: ERD, Database schema, swagger APIs,…\n- Có khả năng đọc hiểu tài liệu tiếng Anh\n\nWhy you\'ll love working here\n- Đánh giá và xét thưởng tương xứng với năng lực.\n- Được làm việc tại Ngân hàng duy nhất tại Việt Nam đạt giải thưởng “Nơi làm việc tốt nhất Châu Á” 5 năm liên tiếp.\n- Phúc lợi tuyệt vời sẽ thúc đẩy động lực làm việc, tạo năng lượng tích cực cho bạn và gia đình suốt quá trình làm việc tại đây.\n- Teambuilding hàng năm \n- Lương tháng 13, thưởng Lễ và Tết \n- Và còn nhiều điều hấp dẫn khác đang chờ bạn trải nghiệm tại HDBank', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(859, 559, 2, 'Front-End Developer (VueJS - Typescript)', 'Top 3 reasons to join us\n•    Full Social Insurance, Premium Insurance\n•    Budget For Learning & Training Course\n•    Flexible working time, Full salary in probation\n\nJob description\nCompany Overview\nis a Mega Value Innovator in Entertainment headquartered in Korea, since its foundation in 2002, Smilegate has continuously strived for happier lives and a more hopeful society by developing and providing quality games and content. Smilegate operates businesses in areas of game development and services, investments, and social contributions; develops and discovers various games and cultural content; and provides them as global services by increasing their value. The representative game is CROSSFIRE the world’s no.1 online FPS game with more than 670 million players from 80 countries, has surprising records such as having over 8 million concurrent users, has reached $10.5 billion in sales revenue since its global launch.\n\nSmilegate Vietnam\nEntering the Vietnam market from 2023, Smilegate Vietnam\'s mission is to provide stable development & operation of the Smilegate platform and services, expanding beyond the development center to the region and expanding into an Asian hub.\n\nWhat You\'ll Do\n1.    Web front-end development based on vue.js (nuxt.js) and Typescript.\n2.    STOVE web service, new project development support\n3.    STOVE web front framework advancement - Common UI componentization and modularization, new project development support\n4.    Advancement of the front STOVE web framework\n5.    Common UI componentization and modularization\n6.    Secure platform stability\n7.    Apply unit tests\n\nYour skills and experience\nRequirements:\n1.    6+ years of experience in web front development\n2.    Web frontend framework (Vue.js, Nuxt) experience\n3.    Good at HTML/CSS(SCSS)/JavaScript.\n4.    Experience in optimizing HTML, CSS, & JavaScript to improve web performance.\n5.    Experience with SSR/ISG/SSG.\n6.    Experience with Tailwind.\n7.    Good at design system (CSS).\n8.    Have experience or knowledge of atomic design and design common components.\n9.    REST API calls and JavaScript asynchronous processing capabilities.\n10.    Communication Skills\n11.    Be able to collaborate across our process via workspace tooling (Jira, Git ops, Confluence…)\n12.    Be able to develop flexible and complicated design, make good decisions in architecture for new projects not only to develop added features.\n\nNice to have:\n1.    Experience working with international technical teams.\n2.    Node server operation experiences (Server/service (ec2, k8s, …) monitoring, deployment (CI/CD), etc.\n3.    Web security knowledge.\n4.    Other front-end development and operation experience such as Typescript, Pinia, etc.\n5.    Experience in configuration management such as Git\n6.    Code quality maintenance/operation experience through TDD\n7.    Good at technical documentation and technical planning.\n8.    Good at technical analysis for technical challenges.\n9.    Experience with Agile collaboration tools and techniques: Jira, Confluence, Git collaboration workflow.\nWhy you\'ll love working here\n•    Attractive salary you’ll love (full salary in probation for experienced candidates)\n•    13th-month bonus\n•    14 days of paid annual leave, increasing by 1 day each year\n•    Premium health insurance\n•    Learning and development budget to upgrade skills and knowledge.\n•    Flexible working timeframe\n•    Modern working equipment (Macbook or LG Gram depending on job, additional monitors etc...).\n•    Pantry with well-stocked snacks, beverages, coffee machine, massage chair… to help you relax and recharge\n•    Engagement activities (monthly team bonding, beer time, yearly company trip…)\n•    Sponsored sports clubs, Korean classes, and so on\n•    Business trip opportunities to Korean Headquarters\n•    Open, friendly, positive work environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CII Tower, 152 Dien Bien Phu, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(860, 560, 2, 'AI Backend Developer (NodeJS / Python)', 'Top 3 reasons to join us\n• Join an AI firm shaping the future of technology\n• Fast-paced startup with autonomy and big impact\n• Competitive salary, benefits, and career growth\n\nJob description\n• Design and prototype AI-native solutions, including AI conversation flows and RAG pipelines.\n• Provide support with troubleshooting and debugging, including suggesting and implementing fixes.\n• Ensure applications are built to optimize speed, data, and responsiveness for end users.\n• Develop robust scalable solutions that can manage large data sets.\n• Integrate with cloud-native platforms (AWS, GCP, Azure) to deploy scalable AI workflows\n• Communicate effectively - must be able to discuss and clearly communicate technical issues.\n• Must be at ease working in an agile environment with little supervision.\n\nYour skills and experience\n• Bachelor’s Degree in Computer Science/Information Systems/Software Engineering, or comparable experience.\n• 4+ years in Backend Development.\n• Strong 3+ years of experience with NodeJS/Typescript and NestJS Framework.\n• 1+ year of experience with Python.\n• Proficiency with AI Agentic frameworks (Langchain, Langgraph).\n• Understanding of vector and graph databases and RAG.\n• Solid understanding of OOP & design patterns.\n• Knowledge of containerization technologies like Docker and Kubernetes.\n\nPreferred Qualifications:\n• Real world experience in taking a commercial system from conception to launch.\n• Should embody a passion for continuous improvement and test-driven development.\n\nWhy you\'ll love working here\n• Opportunity to lead AI-driven innovations in smart device technology.\n• Work in a fast-paced startup environment where your impact is visible.- Competitive salary and performance-based bonuses.\n• Dynamic, collaborative, and international work culture.\n• Learning and development opportunities to enhance your career growth.\n\nOther benefits:\n• Standard 40-hour work week, from Monday to Friday.\n• 18 days of annual leave.\n• 24 days of work from home.\n• Social, medical and unemployment insurance plus other benefits in accordance with regulations.\n\nIf you\'re excited about driving AI-powered device projects success and want to be part of a high-growth startup, apply now.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '96 Nguyễn Thị Minh Khai, Phường Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(861, 291, 2, 'Business Analyst', 'Top 3 reasons to join us\n1. Thử việc 2 tháng 100% lương\n2. Cơ hội được tham gia vào các dự án CNTT lớn\n3. Tổng thu nhập một năm lên đến 14-15 tháng lương\n\nJob description\n- Khảo sát, thu thập, phân tích yêu cầu nghiệp vụ của khách hàng. Tìm hiểu nắm bắt các quy trình, quy định nghiệp vụ phải tuân thủ;\n- Tài liệu hoá thành tài liệu nghiệp vụ dự án. Kiểm soát việc đáp ứng yêu cầu nghiệp vụ của phần mềm;\n- Đào tạo cho các thành viên dự án và những bên liên quan đều hiểu nghiệp vụ;\n- Quản lý các yêu cầu thay đổi khi khách hàng có yêu cầu và chuyển cho đội kỹ thuật để thực hiện yêu cầu đó;\n- Thực hiện kiểm tra phần mềm phiên bản cuối trước khi cập nhật cho khách hàng;\n- Nghiên cứu và cập nhật các công cụ và kiến thức mới hỗ trợ cho công việc;\n- Thực hiện các công việc khác theo sự phân công của Lãnh đạo đơn vị, Quản lý trực tiếp.\n- Thời gian làm việc VP HN: T2 - sáng T7 8:00AM - 17:30PM. Nghỉ 2 sáng thứ 7/tháng.\n\nYour skills and experience\n- Có tối thiểu 5 năm kinh nghiệm làm việc trong các dự án phát triển với vai trò BA hoặc 2 năm kinh nghiệm làm việc trong dự án vốn công với vai trò BA;\n- Hiểu biết về quy trình phát triển phần mềm. Hiểu biết về nhiệm vụ của người thực hiện phân tích yêu cầu;\n- Có khả năng tìm kiếm, thu thập và tổng hợp thông tin yêu cầu nghiệp vụ của khách hàng;\n- Có khả năng viết tài liệu URD, SRS;\n- Biết mô hình hóa các yêu cầu phần mềm;\n- Chủ động, sáng tạo, nhiệt tình, trách nhiệm trong công việc;\n- Biết lắng nghe, kiên trì học hỏi, cẩn thận và tỉ mỉ;\n- Cần cù, nhanh nhẹn, sức khỏe tốt, có khả năng làm việc với cường độ cao, không ngại di chuyển, có thể đi công tác tỉnh, onsite bên khách hàng khi có yêu cầu;\n- Từng làm phân tích nghiệp vụ dự án nhà nước làm điểm cộng;\n- Đọc hiểu tài liệu chuyên ngành bằng tiếng Anh là 1 lợi thế.\n\nWhy you\'ll love working here\n- Tham gia vào các dự án quy mô Bộ ngành, quốc gia, được làm việc cùng nhiều chuyên gia có nhiều kinh nghiệm.\n- Lương: theo thoả thuận theo năng lực.\n- Thưởng tháng lương thứ 13, thưởng KPI (6 tháng một lần, tức 1 năm 2 lần), thưởng theo kết quả kinh doanh, thưởng nóng theo hiệu quả công việc, thưởng ngày lễ (tổng thu nhập một năm lên đến 14-15 tháng lương).\n- Các chế độ phúc lợi khác dành cho nhân viên: sinh nhật, kết hôn, sinh con, ăn trưa, YEP, du lịch, happy hour, team building tháng, tea break, quà lễ/tết,…\n- Hoạt động thể dục thể thao năng động: bóng đá, cầu lông, tennis,…\n- Cung cấp thiết bị làm việc.\n- Tham gia đầy đủ các chế độ bảo hiểm (BHXH, BHYT, BHTN…), khám sức khoẻ định kỳ theo quy định của Nhà nước;\n- Chính sách hỗ trợ đào tạo nâng cao năng lực nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '103 Nguyễn Tuân, Phường Thanh Xuân Trung, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(862, 476, 2, 'Junior Android Engineer', 'Welcome to SMG Vietnam! SMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nThis job refers to our Real Estate brands, and , the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing.\n\nWe are looking for an Junior Android Engineer who is passionate about mobile development and eager to work on high-quality Android application. As a key contributor to our mobile engineering team, you will focus on delivering clean, efficient, and reliable code, working closely with other engineers, designers, and product managers. This role is ideal for an engineer looking to deepen their Android expertise and contribute to complex projects in a supportive environment.\n\nJoin our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nYour Mission:\n- Assist in designing, developing, and maintaining Android applications, focusing on clean, maintainable code.\n- Collaborate closely with product managers, designers, and senior engineers to implement new features and enhancements.\n- Participate in code reviews, learn from feedback, and apply best practices to improve code quality.\n- Write Unit and UI tests with guidance to ensure code reliability.\n- Learn and apply modern Android architecture patterns to build scalable features.\n- Continuously improve your skills and contribute to the team\'s knowledge-sharing culture.\n- Help identify and fix bugs, optimize performance, and support releases under the guidance of more experienced team members.\n- Stay curious and up-to-date with Android development trends, tools, and best practices.\n\nYour responsibilities will evolve as we grow.\n\nWhat will you bring to the ride?\n- Fluency in English written and verbal communication.\n- Bachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience.\n- 1+ year of experience developing Android applications in Kotlin (Java is a plus).\n- Basic understanding of Android components and tools (e.g., Activities, Fragments, Android Studio).\n- Some exposure to modern development practices such as MVVM, Jetpack components, or reactive programming is a plus.\n- Willingness to learn and apply best practices in mobile development, testing, and architecture.\n- Comfortable with consuming REST APIs and working with local storage (e.g., Room, SharedPreferences).\n- Curious, open-minded, and enthusiastic about growing in a collaborative team environment.\n\nNice-to-Have Qualifications:\n- Exposure to CI/CD, version control (e.g., Git), or test automation frameworks.\n- Awareness of mobile app performance and monitoring tools (e.g., Firebase, Datadog).\n- Familiarity with privacy, security, or accessibility in mobile apps.\n\nWhy you\'ll love working here:\n- Attractive salary you’ll love!!!\n- Full salary in probation\n- 13th-month bonus, Annual bonus from Profit Growth Sharing Plan\n- 21+ annual paid days off\n- 24 paid days equivalent per year for learning & knowledge sharing activities\n- Full contribution to social insurance\n- Premium private insurances coverage for you and your family members\n- Personal development plan and yearly budget for educational courses, and conferences, aiming to grow both your soft and hard skills\n- Clear Career Growth Framework and Supports\n- Assistance and support through all aspects of the onboarding process\n- Lots of team activities and regular Hackathons\n- Annual Trips to Switzerland and other European countries\n- Flexible working time\n- Hybrid working model (home office and in-office)\n- 40 hours per week, Mon-Fri, No OT\n- Modern Macbook laptops\n- Free food, Sports Clubs, Monthly Townhall and frequent engagement activities\n- Work in an open-minded, friendly, positive, transparent, and agile environment.\n\nAPPLY NOW, SO A GREAT CAREER OPPORTUNITY WON\'T BE MISSED!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Tower, 285 CMT8, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(863, 255, 2, 'Senior Full Stack Developer (Java/ReactJS)', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nJob Description:\nAt Aperia, we thrive on innovation and the strength of our dynamic development team. We are currently seeking a Senior Full Stack Developer (Java/ReactJS) with a strong background in Java and J2EE who is passionate about modern technologies, cloud-native architecture, and secure, scalable systems. If you’re eager to push boundaries and drive meaningful impact in a fast-paced fintech environment, we want to hear from you.\n\nCore Responsibilities:\n- Full lifecycle - analysis, design, development, testing and implementation- of new or enhancements to middleware (micro) services\n- Maintain middleware modules and services with code quality standards\n- Keep applications free of security vulnerabilities in compliance with organization’s security policies\n- Assist in troubleshooting and resolving production issues. Provide suggestions for preventative steps\n- Incorporate suggestions for improvements and enhancements where meaningful\n- May assist/lead in developing and maintaining technical documentation and store it in central locations (like Confluence, SharePoint) for accessible to team members.\n\nYour skills and experience:\nTechnical Skills:\n- 8+ years of hands-on experience in Java/J2EE development.\n- Expertise in Spring, Spring Boot, Spring Cloud, Spring Security, Spring Data, and RESTful APIs.\n- Working knowledge of RabbitMQ or similar message brokers.\n- Proficiency in Oracle PL/SQL.\n- Strong unit testing skills with JUnit.\n- Exposure to ReactJS on the frontend.\n- Experience with build tools like Maven, and artifact repositories like Nexus.\n- Familiarity with Postman for API testing and PCF (Pivotal Cloud Foundry).\n- Demonstrated experience in addressing security vulnerabilities and managing open-source dependencies.\n- Maintain high code quality using tools like SonarQube.\n- Version control and CI/CD experience using GitLab.\n- Proficient with Atlassian tools including JIRA and Confluence.\n- Solid understanding of Linux environments\n\nThings that will separate you from the rest:\n- Experience with JIRA integration and custom workflows.\n- Familiarity with logging and monitoring tools like Splunk.\n- Ability to collaborate effectively with onshore and offshore teams.\n- Background in the finance or banking industry.\n- Strong problem-solving, debugging, and communication skills (written and verbal).\n\nJob Type:\n- Full-Time\n\nSchedule:\n- Monday to Friday\n\nWork Location:\n- The Six8 Building: 24-26 Phan Dinh Giot, Tan Binh District, HCMC\n- VDB Tower: 74 Quang Trung, Hai Chau, Danang\n\nWhy you\'ll love working here:\n- Highly competitive salary\n- Full salary for probation & full coverage of social insurance.\n- Premium healthcare for you and your beloved one.\n- Monthly childcare support\n- 13th-month salary.\n- Annual Leave: 15 days; Paternity Leave: 6 weeks, Bereavement leave: 10 days.\n- Flexible working time, focus on output (no checking time attendance)\n- Various active sporty clubs: Football, Billiards, Badminton, E-sport clubs\n- Frequent opportunities to travel to US headquarters from 3-6 months.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Six8 Building: 24-26 Phan Dinh Giot, Tan Binh District, HCMC; VDB Tower: 74 Quang Trung, Hai Chau, Danang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(864, 368, 2, 'Senior AI Engineer (Machine Learning, Python, SQL)', 'About BeWao\nBeWao is a pioneering health and wellness platform tailored to the Vietnamese market. We empower users to achieve their nutrition and fitness goals through personalized solutions driven by cutting-edge technology, AI innovations, and localized expertise. As part of our mission to redefine health in Vietnam, we are seeking a talented Senior AI Engineer to join our dynamic team.\n \nAbout the Role\nAs an Senior AI Engineer, you will be at the forefront of developing and integrating advanced AI technologies into our products. You’ll work on cutting-edge AI solutions such as personalized meal planning, food recognition, coaching copilot, and AI recommendation systems. Collaborating with cross-functional teams, you will design, implement, and deploy AI-driven systems that provide innovative, user-centric solutions.\n \nWhat You’ll Do\nDesign, develop, and fine-tune machine learning and AI models, including Retrieval-Augmented Generation (RAG), LLMs, and recommendation systems.\nBuild and maintain workflows for multi-agent systems, agent workflows, and Personal AI Assistants.\nIntegrate and optimize personalized coaching and meal planning algorithms.\nWork with large datasets to preprocess, analyze, and extract meaningful insights.\nCollaborate with Product and Engineering teams to deploy AI models into production environments.\nContinuously experiment and innovate, leveraging the latest advancements in AI and data science.\n\nYour skills and experience\nTechnologies We Use\nAI/ML Stack: Retrieval-Augmented Generation (RAG), Large Language Models (LLMs), fine-tuning techniques, multi-agent systems, agent workflows.\nDevelopment Languages: Python, TypeScript\nInfrastructure: TensorFlow, PyTorch, LangChain, Hugging Face, GCP, Serverless architecture\nData & Tools: SQL, PostgreSQL, MongoDB, Redis, Pandas, NumPy\nRecommendation Systems: Personal AI Assistant, collaborative filtering, content-based filtering\nRequired Skills & Experience\nEducational Background: Bachelor’s or Master’s in Computer Science, Data Science, Machine Learning, or related field.\nExperience: 3+ years of professional experience in AI/ML or data science roles, with a proven track record of deploying AI solutions in production.\nTechnical Expertise: \nProficient in machine learning, deep learning, and natural language processing techniques.\nExperience working with LLMs, fine-tuning, and multi-agent systems.\nStrong understanding of recommendation systems, including collaborative and content-based filtering.\nFamiliarity with AI workflows, including RAG, agent workflows, and personalization strategies.\nProgramming Skills: Proficient in Python, with experience in AI/ML frameworks like TensorFlow, PyTorch, and LangChain.\nData Handling: Experience working with large datasets, data preprocessing, and analytics using tools like Pandas and NumPy.\nSoft Skills: A team player with strong problem-solving skills, the ability to communicate complex ideas effectively, and a passion for innovation.\n\nWhy you\'ll love working here\nWhy Join Us?\nCompetitive salary and benefits: Up to 50M\nGenerous leave policy: \nPublic holidays\n12 days annual leave\n3 additional Company Holidays (Christmas, Vietnamese Family Day, Birthday leave)\nComprehensive insurance coverage and allowances (parking, transportation).\nRecreational facilities (billiards, table tennis) for a balanced work-life experience.\n\nApply Now\nJoin BeWao and contribute to creating AI-driven innovations that redefine health and wellness in Vietnam. Let’s build something amazing together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '95-97 Nguyễn Cơ Thạch, Phường An Lợi Đông, Thành phố Thủ Đức, TP Hồ Chí Minh, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(865, 225, 2, 'Manager/ Lead DevOps (MIS)', 'Top 3 reasons to join us\n- Very competitive remuneration package\n- Build products for millions of users in Australia\n- Hybrid and flexible working environment\n\nJob description\n- Demonstrated strong leadership skills with a proven track record in managing and coaching technical teams, fostering collaboration, accountability, and continuous improvement.\n- Solid background as a DevOps Engineer, with hands-on experience in automation, CI/CD pipelines, environment configuration, and system reliability.\n- Adept at building effective relationships across business and technical teams to ensure successful implementation of strategic technical solutions.\n- Proven ability to use both business and technical acumen to define, implement, and align IT solutions with evolving business needs.\n- Provided services to guide, support, and assure solution design aligns with strategic directions, architectural standards, and best practices.\n- Willing and capable to upskill in Mainframe environments, contributing to Mainframe Security Uplift initiatives while bridging legacy and modern technologies.\n\nYour skills and experience\n- Experience managing cross-functional teams, coaching junior engineers, and fostering a high-performance team culture.\n- DevOps Tools & Technologies: Git, GitHub, CI/CD, NodeJS, Java JDK, Python, AWS, and SQL.\n- Mainframe Exposure: JCL (Job Control Language), ISPF, SDSF, RACF – with a willingness to develop deeper expertise.\n- Agile Delivery: Certified Scaled Agile Framework (SAFe) Practitioner, experienced in Agile ceremonies, planning, and story tracking.\n\nWhy you\'ll love working here\nTHE BENEFITS AND PERKS\n1. Generous compensation and benefit package\n- Attractive salary and benefits\n- 20-day annual leave and 7-day sick leave, etc.\n- 13th month salary and Annual Performance Bonus\n- Premium healthcare for yourself and family members\n- Monthly allowance for team activities\n- Premium welcome kit and frequent appreciation gifts \n- Extra benefits for long-term employees\n2. Exciting career and development opportunities \n- Large scale products with modern technologies in banking domain\n- Clear roadmap for career advancement in both technical and leadership pathways\n- Well-structured  learning and development programs (technical and soft skills)\n- Sponsored certificates in both IT and banking/finance\n- Premium account on Udemy \n- English learning with native teachers\n- Opportunity for traveling & training in Australia\n3. Professional and engaging working environment\n- Hybrid working model and good work-life balance \n- Well-equipped & modern Agile office with fully stocked pantry\n- Special programs to improve your physical and mental health\n- Annual company trip and events \n- A solid talented team behind you – great people who love what they do.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(866, 498, 2, 'Junior JavaScript Developer', 'Job description\n- Lập trình phát triển phần mềm /firmware cho các edge computer\n- Nghiên cứu & phát triển (R&D) sản phẩm mới.\n- Tham gia phát triển các dự án mới theo yêu cầu của khách hàng.\n- Báo cáo tiến độ và tình trạng công việc cho quản lý.\n\nYour skills and experience\nYêu cầu bắt buộc:\n- Trên 1 năm KN kinh nghiệm lập trình Javascript\n- Tư duy lập trình tốt và có khả năng điều tra, nghiên cứu.\n- Có kiến thức tốt về Cơ sở dữ liệu và Lập trình hướng đối tượng.\n- Thường xuyên cập nhật và nắm bắt nhanh những công nghệ, kỹ thuật mới.\n- Có tinh thần trách nhiệm trong công việc.\n- Năng động, sáng tạo, thích giao tiếp.\n- Có khả năng làm việc nhóm cũng như làm việc độc lập.\n\nƯu tiên\n- Có thêm kinh nghiệm về lập trình ứng dụng web app với Java, SQL, Javascript, CSS, PostgreSQL, Oracle...\n- Có kiến thức cũng như khả năng thiết kế, lập trình Framework\n- Có kiến thức cũng như đã làm việc trên linux là một lợi thế\n\nWhy you\'ll love working here\nLương & Thưởng\n- Chế độ tăng lương, thưởng tháng 13 hằng năm, mức lương thưởng hấp dẫn phù hợp với năng lực.\n\nĐào tạo\n- Thường xuyên tổ chức những buổi training, rèn luyện kỹ năng lập trình.\n\nPhúc lợi\n- Du lịch công ty hằng năm\n- Ngoài chế độ bảo hiểm cơ bản theo quy định của luật Lao Động, công ty còn tham gia Bảo hiểm sức khỏe đặc biệt cho nhân viên có hợp đồng dài hạn với công ty.\n- Khám sức khỏe định kỳ hằng năm\n\nKhác\n- Trà, coffee... miễn phí\n- Hoạt động vui chơi, tiệc cuối năm, giáng sinh, tiệc sinh nhật hằng tháng\n- Được hưởng phúc lợi đặc biệt như tiền mừng kết hôn, tiền mừng khi sinh con...\n- Hoạt động thể thao (cầu lông, bóng đá...)\n- Môi trường làm việc: đồng nghiệp trẻ trung, năng động, tích cực học hỏi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '15.01 Khối văn phòng Cao ốc Thái An, 2290 Quốc Lộ 1A, Phường Trung Mỹ Tây, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(867, 561, 2, 'Lập trình viên Automation (Python, JavaScript, English)', 'Job description\n• Tham gia lập trình và phát triển các công cụ/ giải pháp tự động hóa phục vụ cho các dự án.\n• Làm việc trực tiếp với các tài liệu kỹ thuật, yêu cầu dự án bằng tiếng Anh.\n• Thiết kế, xây dựng, kiểm thử và bảo trì các ứng dụng tự động hóa liên quan đến xử lý dữ liệu, web automation, tích hợp API,...\n• Hỗ trợ team xử lý lỗi kỹ thuật, tối ưu hóa hiệu suất của các quy trình tự động.\n• Viết tài liệu hướng dẫn sử dụng, tài liệu kỹ thuật và báo cáo tiến độ công việc.\n• Phối hợp với các thành viên trong và ngoài nước để đảm bảo tiến độ và chất lượng của dự án.\n\nYour skills and experience\n• Tốt nghiệp cao đẳng hoặc đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan.\n• Tối thiểu 2 năm kinh nghiệm làm việc trong lĩnh vực lập trình automation hoặc các vị trí tương đương.\n• Thành thạo ít nhất một ngôn ngữ lập trình bậc cao: Python, JavaScript,...\n• Có kinh nghiệm sử dụng và làm việc trên các Linux distributions (Ubuntu, CentOS, Fedora Linux,...) cho server hoặc desktop.\n• Có kinh nghiệm làm việc với API, web automation tools (Selenium, Puppeteer, Playwright,...), xử lý dữ liệu (Excel, CSV, JSON), hoặc RPA tools (UiPath, Microsoft Power Automate,...) là lợi thế.\n• Có kinh nghiệm sử dụng machine learning libraries và frameworks (Scikit-learn, Tensorflow, Pytorch,...) là một lợi thế.\n• Có kinh nghiệm sử dụng ít nhất một data visualization tool: Tableau, Microsoft Power BI, Looker Studio ...\n• Có khả năng đọc hiểu và làm việc với tài liệu kỹ thuật bằng tiếng Anh.\n• Tiếng Anh: TOEIC từ 785 điểm trở lên hoặc IELTS từ 6.0 trở lên (bắt buộc).\n• Tư duy logic tốt, chủ động, có khả năng làm việc độc lập và phối hợp nhóm hiệu quả.\n• Ưu tiên ứng viên đã từng tham gia dự án offshore hoặc làm việc với khách hàng quốc tế.\n• Biết sử dụng các phần mềm thiết kế và có mắt thẩm mỹ là một lợi thế.\n\nWhy you\'ll love working here\nCHẾ ĐỘ ĐÃI NGỘ\n• Thu nhập: 13.000.000 - 18.000.000 vnđ/ tháng.\n• Thưởng theo hiệu quả công việc.\n• Phúc Lợi sau khi ký hợp đồng lao động chính thức:\n- 12 ngày phép năm và nghỉ lễ theo quy định của pháp luật.\n- Được thực hiện đánh giá kết quả công việc, xét tăng lương ít nhất 1 năm một lần.\n- Đóng bảo hiểm theo quy định của Luật lao động.\n- Môi trường làm việc cởi mở, thân thiện.\n- Du lịch hàng năm.\n\nĐIỀU KIỆN LÀM VIỆC\n• Thời gian làm việc: 9h - 17h, từ thứ Hai đến thứ Sáu, nghỉ trưa 1h (12h - 13h)\n• Địa điểm làm việc: Toà nhà Tiến Lộc, Số 155 - 157 An Dương Vương, phường 8, quận 5 , Thành phố Hồ Chí Minh.\n• Môi trường làm việc năng động, hỗ trợ và có cơ hội phát triển nghề nghiệp rõ ràng.\n• Cơ hội làm việc trong các dự án quốc tế, nâng cao kỹ năng chuyên môn và tiếng Anh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà Tiến Lộc, 155 - 157 An Dương Vương, Quận 5, TP.HCM, District 5, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(868, 315, 2, 'Senior DevOps Engineer', 'Job description\n\n1. Infrastructure Management and Operations (On-Premise)\n- Design, implement, and maintain infrastructure following DevOps methodologies, ensuring security, continuity, and scalability.\n- Manage activities related to DevSecOps, including security automation, source code scanning, and continuous security assessment.\n- Integrate and operate CI/CD tools to optimize software development and infrastructure workflows.\n- Perform other related technical tasks as required.\n\n2. Security System Implementation and Operations\n- Manage, deploy, and maintain security systems such as firewalls, IDS/IPS, and other network security solutions.\n- Develop and enforce security policies to ensure protection and compliance with standards such as ISO 27001, GDPR, SOC 2, etc.\n- Monitor and respond to security incidents, ensuring the system operates safely and reliably.\n- Set up and maintain monitoring and logging systems to detect and respond promptly to potential threats.\n- Collaborate closely with software development teams and security teams to ensure security standards are integrated throughout the software development and system operations lifecycle.\n- Create and maintain technical documentation on deployment processes, system configurations, and security policies.\n- Conduct regular security assessments and vulnerability scans to identify and remediate weaknesses in the system.\n\nYour skills and experience\n- Degree in IT, Software Engineering, Computer Science, or related field.\n- 5+ years of experience in SRE/DevOps roles, especially with On-Premise infrastructure.\n- 2+ years of technical team management experience.\n- Strong understanding of Agile/SCRUM or Kanban workflows.\n- Experience in entertainment/OTT or video streaming is a plus.\n- Proficient in virtualization and containerization (VMware, KVM, Docker, Kubernetes).\n- Solid knowledge of system, network, and application security (VPN, Firewall, IDS/IPS).\n- Skilled in Linux/Unix, configuration tools (Ansible, Puppet, Chef).\n- Familiar with security standards (ISO 27001, GDPR, SOC 2).\n- Experience with monitoring/logging tools (Prometheus, Grafana, ELK, Splunk).\n- Good understanding of networking (TCP/IP, HTTP, DNS).\n- Scripting in Shell, Go, or Python.\n- Cloud experience (AWS, GCP, Azure).\n- Familiar with CI/CD tools (Git, Ansible, Terraform).\n\nWhy you\'ll love working here\n💰 Competitive Compensation\n13th-month salary, sign-on bonus, performance-based reviews, and attractive bonuses.\n\n🚀 Growth Opportunities\nAccess to training and advanced technologies.\n\n📱 Exciting Projects\nWork on leading entertainment apps and OTT platforms.\n\n🌟 Open Culture\nWe value ideas, creativity, and innovation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '222 Pasteur, Phường Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(869, 562, 2, 'Game Developer (Phaser/Cocos)', 'Job description\n- Transform design ideas into functional games.\n- Effectively lead and manage the development team.\n- Develop tools to accelerate the development process and provide solutions.\n- Create and oversee the development plan.\n- Design, build, and maintain efficient, reusable, and reliable code.\n- Ensure the best performance, quality, and responsiveness of applications and games.\n\nYour skills and experience\n- At least 3 years of relevant work experience and possess a clear understanding of designing games to meet user needs, in addition to working in a high-performance team.\n- Proficiency in JavaScript/TypeScript.\n- Strong knowledge and experience in Cocos/ Phaser/ PixiJS Creator.\n- Strong working knowledge of 2D, 2.5D game development.\n- Ability to work independently and collaboratively within a team.\n- Strong proficiency with version control tools such as Git, and project management tools like JIRA.\n- Excellent communication skills, with the ability to work effectively with international teams and understand requirements clearly.\n- Logical approach to problem-solving.\n- Good English communication skills, both written and verbal.\n\nWhy you\'ll love working here\n- Working in a professional, friendly, well-equipped office.\n- Attractive salary and annual salary review.\n- Full social insurance, health insurance & unemployment insurance according to Vietnam Labour Law.\n- 12-day annual leave per year.\n- 13th month salary.\n- Performance bonus.\n- PVI Health Care.\n- Enjoy diversified activities: Monthly Team-building, Company trip, Play Games (PlayStation, Board Games, etc…)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The West Tower, 265 Cầu Giấy, Phường Dịch Vọng, Quận Cầu Giấy, Thành phố Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(870, 275, 2, 'Junior/Middle Java Developer (Spring)', 'Development is the largest discipline at Endava. Our developers design, build, and release software products in multiple programming languages, frameworks, and libraries. Always collaborating with cross-functional project teams, our developers are adaptable problem-solvers with a client-oriented mindset.  As a Java Developer at Endava, you will work in a professional and cross-functional team for payment gateway services. You\'ll be involved in the full development lifecycle of a software system. Contribute to delivering new products to the market by meeting customer\'s requirements and product development programs. Be an integral part of a Scrum team and contribute to Agile processes.\nResponsibilities:\n- Designs, estimates, and implements technical solutions for medium/high complexity applications.\n- Participates actively in all phases of application development lifecycle.\n- Collaborates with various project stakeholders to provide support for clarifying requirements, processes, architecture, and priorities.\n- Recommends and promotes IT industry standards, tools, practices (DevOps, etc.) to achieve well-engineered software products.\n- Proposes improvements and escalates risks/issues related to development activities.\n- Participates in the review of the work done by development team members.\n- Learns and applies new technologies, practices, and tools as appropriate to the project.\n- Participates in internal and external tech communities, events.\n- Shares experience and knowledge gained from projects.\nYour skills and experience:\n- 2+ years of experience in software development.\n- Proficiency in Java and tools such as IntelliJ IDEA, Spring, Hibernate, Maven/Gradle.\n- Understanding of OOP, functional programming, and clean code principles (SOLID, GoF, MVVM).\n- Practical experience in platform-specific database systems and SQL.\n- Understanding of Git or similar version control systems.\n- Basic knowledge with CI/CD tools and Agile methodologies (Scrum, Kanban)\n- Experience with testing and mocking frameworks.\n- Familiar with communication protocols such as HTTP, REST, JSON, TCP/IP.\n- Good problem-solving skills, teamwork, communication abilities and analytical thinking.\n- Intermediate English proficiency.\nWhy you\'ll love working here:\nAt Endava, we are offering opportunities and exciting development for our people to build an engaging technical community.\nSome of our benefits:\n- Competitive salary package, annual leave encashment, 13th month salary, referral bonus.\n- Career coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership.\n- Complex projects, rotations, internal tech communities, training, coaching, online learning platforms subscriptions, English programme, certifications, pass-it-on sessions, workshops, and conferences.\n- Hybrid work and flexible working hours, employee assistance programme.\n- Global internal wellbeing programme, access to wellbeing apps, premium health check, extra insurance.\n- Global internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '9-11 Dong Da street, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(871, 563, 2, 'Cloud Solutions Architect', 'TECHVALLEY is looking for a Junior Cloud Engineer /Solution Architect who provides technical design and solutions to customers in Vietnam, in terms of cloud computing adoption. This is a unique opportunity to play a key technical member of Vietnam business founding team in an exciting, fast-growing business environment. The ideal candidate is a problem-solving oriented technologist who has a genuine passion about utilizing emerging technologies for complex enterprise problems.\nIn this role, you will be responsible for owning the technical engagement and ultimate success around specific cloud implementation; defining and designing implementation architectures, responding to RFPs, developing a deep expertise in CLOUD offerings and general cloud computing technologies, collaborating with off-shore teams within TECHVALLEY and external partners, and being a subject matter expert for regional customers. You’re also encouraged to proactively participate in pilot projects developing technical solution demos based on cutting-edge technologies with headquartered teams. This role will report to the Head of Vietnam Business.\nWhat you will do:\n- AWS Cloud and local cloud (CMC, Viettel and Viettel Cloud)’s basic implementation, optimization and migration.\n- Responsible for presenting complex solutions and integrations in a clear and articulate manner.\n- Closely work with in-region sales colleagues to develop business opportunities and achieve jointly agreed business objectives.\n- Design and propose solutions that address the client’s need demonstrating how cloud services benefit the customer’s business.\n- Work as a key role between sales and off-shore solutions delivery teams ensuring a smooth project execution and successful delivery.\n- Deliver technical enablement and updates to country sales team.\n- Serve as a technical support of customers in English.\nYour skills and experience:\n- 3+ years of enterprise OS, System, network and Cloud experiences related to solution architect experience with foreign customers (specially Korea).\n- 1+ years of hands-on experience in developing and operating scalable web applications or web services.\n- Ability to understand and present complex technical topics to both technical and business leaders.\n- Strong foundational knowledge in one or more of following domains; micro-services, databases, networking, security and datacenter operation.\n- Variety of experiences working as an architect and systems or software or network engineer.\n- Ability to work effectively across internal and external organizations.\n- Strong written and oral communications skills in English.\n- Proficient technical communication with customer and project team.\n- BS degree in Computer Science or relevant experiences.\nPreferred Qualifications:\n- Intermediate/advanced knowledge of cloud computing concepts and services (particularly, AWS and Microsoft Azure Cloud services).\n- Excellent English speaking, writing and communication skill.\n- Experience architecting, designing and migrating workloads to the public cloud.\n- Cloud certifications holder (ex. AWS, Azure or GCP).\n- Self-starter working in a fast-paced, changing but highly collaborative team environment.\n- Experience with customer support.\nWhy you\'ll love working here:\n.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '17F, West Tower, Lotte Center, 54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(872, 201, 2, 'Senior Flutter Developer (Android and/or iOS platforms)', 'ABOUT ONE MOUNT\nOne Mount is Vietnam\'s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam\'s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\nOne Mount Real Estate (OMRE) is a property technology company that provides a comprehensive platform to help customers experience a simple and seamless home buying and selling journey. OMRE is the first company in Vietnam capable of integrating the entire real estate transaction process on a single platform, from online to in-person. In addition, OMRE owns the first home valuation product in Vietnam. Don\'t miss the opportunity to become a member in PropTech field at One Mount Real Estate - A member company of One Mount ecosystem, a strategic partner of the leading bank in Vietnam Techcombank and the investor owns the most sought-after luxury apartments in the market, Masterise Home, Vinhomes.\n\nMAIN RESPONSIBILITIES:\nWe are looking for experienced Senior Mobile Developers (Flutter) to join our high-powered experienced product team who follow agile development principles, and who value well-designed software, creative thinking and thrive on solving the un-solvable. You will be working on technology spanning mobile communications (voice, messaging, email), and fintech/payments all underpinned by strong security and privacy principles. This is a fantastic opportunity to work at a well-established and leading start-up in Vietnam as One Mount Group and you will be part of OMRE - OneHousing team - focusing on building the most complete and trusted platform for buying and selling a home in Vietnam\nResponsibilities\n- Develop quality software and web applications\n- Analyze and maintain existing software applications\n- Design highly scalable, testable code\n- Discover and fix programming bugs\n\nYour skills and experience\n- Bachelor\'s degree or equivalent experience in Computer Science or related field\n- Desire to work in a startup environment, able to self-manage and work remotely.\n- Minimum 5 years of hands-on experience in building and deploying mobile applications using Flutter (Android and/or iOS platforms).\n- Proven experience integrating with third-party libraries, SDKs, and APIs.\n- Working knowledge of the general mobile landscape, architectures, trends, and emerging technologies.\n- Solid understanding of the full mobile development life cycle, including automated testing and building.\n- Experience working in an agile development process.\n- Proficiency with version control (Git) and experience with CI/CD pipelines, ideally using tools such as GitHub Actions, Jenkins, or similar.\n- Write clear, maintainable and testable code that you are proud of.\n- Having published one or more apps to the Google Play Store or Apple App Store is a strong plus.\n\nWhy you\'ll love working here\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check\n- Laptop, screen and other needed facilities/accounts/tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'Reilly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n- Grow your career with opportunities across the dynamic ecosystem of Techcombank & Masterise Group.\n- Access special loan offers with competitive interest rates and flexible grace period options tailored to your financial needs.\n\nWorking Environment\n- Open & collaborative working space fosters both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms.\n- Personal lockers with QR code access.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tower 2 (T26) Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(873, 366, 2, 'UI Frontend Engineer (HTML/CSS/UX)', 'We are looking for UI Frontend Engineers (HTML/CSS/UX). Join NAVER Vietnam as a UI Frontend Engineer to develop visually stunning, user-friendly interfaces for our products. You\'ll collaborate with cross-functional teams, contribute creative solutions, and implement design guidelines. If you\'re passionate about creating amazing user experiences, apply now!\n\nYour qualification:\n- Ideally, 1+ year of work experience in Front-end development and 1+ year of work experience in UI/UX.\n- Proficient in HTML/CSS and JavaScript.\n- Plan and manage design projects to ensure timely delivery and to adhere to deadlines.\n- Create wireframes, storyboards, user flows, process flows, and site maps to effectively convey design concepts and interactions.\n- Maintain and improve our design system.\n- Proficient in Responsive/Adaptive Design.\n- Experience with at least one of the JS frameworks, like AngularJS/ReactJS/VueJS basically.\n- Excellent mastery of web standards, cross-browser compatibility, accessibility, and SEO.\n- Experience with version control systems, like Git.\n- Familiar with software like Figma.\n\nIt\'s a big plus if you:\n- Ability to build new Front-end frameworks like Bootstrap, Semantic-UI, Skeleton, etc.\n- Ability to build a new Storybook or write a Storybook.\n- Ability to write snapshots and visual tests.\n- Ability to coach and mentor team members in their professional development and build a self-organizing team.\n- Can Speak Korean.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package:  Performance appraisal every year, incentive bonus...\n- Learning and development opportunities: We provide an annual budget for employees to learn anything related to languages (Korean, English) and technologies & monthly budget for buying any book you want to read.\n- Protecting and enhancing healthcare plan for you and your family: We provide premium health insurance for you and 2 family members, a health check every year, and a premium gym membership.\n- Employee engagement activities: You will be involved in a fun and respectful working environment, we support a monthly budget for team engagement.\n- Other benefits: One-off allowance for setting up working from home corner, work dedication bonus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '4th and 9th Floor, Block B, Viettel Building, 285 CMT8, Ward 12, District 10, Ho Chi Minh city, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(874, 201, 2, 'Senior Backend Engineer (Java/ Spring Boot)', 'ABOUT ONE MOUNT\nOne Mount is Vietnam’s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam’s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\nOne Mount Real Estate (OMRE) is a property technology company that provides a comprehensive platform to help customers experience a simple and seamless home buying and selling journey. OMRE is the first company in Vietnam capable of integrating the entire real estate transaction process on a single platform, from online to in-person. In addition, OMRE owns the first home valuation product in Vietnam. Don\'t miss the opportunity to become a member in the PropTech field at One Mount Real Estate - A member company of One Mount ecosystem, a strategic partner of the leading bank in Vietnam Techcombank and the investor owns the most sought-after luxury apartments in the market, Masterise Home, Vinhomes.\n\nMAIN RESPONSIBILITIES\nWe are looking for experienced Senior/Lead Java Developer to join our product team in OMRE (OneHousing product). This is a fantastic opportunity to work at a well-established and leading start-up in Vietnam as One Mount Group.\n\nResponsibilities\n- Writing clean & high-quality code\n- Maintain & improve running- functionality as well as design and develop new system, new feature if needed\n- Deliver end-to-end, including unit test, integration test and deployment to PROD\n- Participate in code reviews & control coding quality standards\n\nYour skills and experience\n- Minimum 5 years of hands-on development experience in Java (Spring Boot framework)\n- Good understanding of Data Structures and Algorithms\n- Expertise in SQL/ NoSQL Databases (MySQL, PostgreSQL, MongoDB)\n- Experience with RESTful APIs, Microservices\n- Familiarity with Redis, Kafka\n- Experience in high-performance, low-latency systems, handling large-scale data processing and real-time transactions\n- Experience with Docker/Kubernetes and Cloud Infrastructure is a plus\n- Experience with Agile or Scrum software development methodologies\n- Prior experience within the PropTech sector is highly desirable.\n\nWhy you\'ll love working here\nBenefit and Perks\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check \n- Laptop, screen and other needed facilities/accounts/tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'relly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n\nWorking Environment\n- Open & collaborative working space foster both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms, sleep corner.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tower 2 (T26) Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(875, 564, 2, 'Web Developer (WordPress/ UI UX)', 'Job description\n- Phối hợp với team thiết kế để dựng UI/UX.\n- Xây dựng thư viện, plugin.\n- Sửa lỗi, tối ưu hiệu năng web và giao diện responsive.\n- Làm các công việc khác liên quan theo yêu cầu của cấp trên.\n\nYour skills and experience\n- Tốt nghiệp Cao Đẳng, Đại Học các chuyên ngành liên quan.\n- Có kinh nghiệm 1-2 năm vị trí tương đương.\n- Có kinh nghiệm bên Wordpress, Elementor, PHP, MariaDB.\n- Hiểu rõ về RESTful API, xử lý JSON.\n- Rành Laravel là một lợi thế.\n\nWhy you\'ll love working here\n- Mức thu nhập: 8.000.000 VNĐ – 12.000.000 VNĐ\n- Tham gia chế độ BHXH, BHYT, BHTN, Công đoàn theo quy định của pháp luật.\n- Du lịch hằng năm, tài trợ các chương trình training hỗ trợ nâng cao kiến thức chuyên môn.\n- Thưởng tháng, quý, năm, lương tháng 13, các chương trình thưởng nóng, lễ, tết.Tham gia chế độ BHXH, BHYT, BHTN, Công đoàn theo quy định của pháp luật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '163 Nguyễn Thị Nhung, KDC Vạn Phúc, Quốc lộ 13, Phường Hiệp Bình Phước, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(876, 565, 2, 'Kỹ Sư Giải Pháp Mạng (Network Solution Engineer)', 'Job description\n- Tham gia vào các dự án SI cho mạng doanh nghiệp với vai trò tổ chức, điều phối, giám sát việc triển khai.\n- Tư vấn, thiết kế, hỗ trợ các công việc triển khai (nếu cần). Các hạng mục triển khai bao gồm:\n  - Router, Switch, Wifi\n  - Internet Gateway, Wifi Marketing, HSIA\n  - Firewall\n  - Server (Windows, Linux), Ảo hóa\n  - Monitoring,…\n- Troubleshooting, hỗ trợ xử lý các sự cố mạng\n- Tham gia tìm kiếm, tìm hiểu, thử nghiệm, đánh giá các giải pháp mới phù hợp với định hướng của NetNam và nhu cầu của khách hàng.\n\nYour skills and experience\n- Từ 2-3 năm kinh nghiệm, ưu tiên có kinh nghiệm về thiết kế, triển khai mạng doanh nghiệp, hoặc có kinh nghiệm vận hành hệ thống mạng, hệ thống hạ tầng CNTT\n- Có kiến thức tốt về routing, switching, security, wireless, datacenter\n- Có kiến thức cơ bản về các lĩnh vực cloud, ảo hóa, IoT, 4G/5G\n- Có kinh nghiệm triển khai các sản phẩm của Cisco, Juniper, HPE, Ruckus, Fortinet, CheckPoint,...\n- Có khả năng nghiên cứu công nghệ, sản phẩm và giải pháp mới ứng dụng cho công việc.\n- Có kỹ năng giao tiếp, làm việc liên phòng ban. Có khả năng thuyết trình và viết các tài liệu kỹ thuật. Có kinh nghiệm quản lý dự án.\n\nWhy you\'ll love working here\n- Mức lương cạnh tranh, tối thiểu 13.5 tháng lương mỗi năm\n- Mức lương có thể thương lượng dựa trên năng lực ứng viên\n- Thưởng lễ, Tết\n- Phụ cấp ăn trưa 50.000đ/ngày\n- BHXH, BHYT, BHTN\n- Khám sức khỏe định kỳ tại bệnh viện cao cấp\n- Du lịch, teambuilding trong và ngoài nước (2-3 chuyến/năm)\n- Môi trường làm việc: Thân thiện, năng động, khuyến khích sáng tạo và thay đổi\n- Các CLB thể thao như bóng đá, yoga, chạy bộ được công ty hỗ trợ\n- Cơ hội đào tạo, hướng dẫn từ các chuyên gia công nghệ có kinh nghiệm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2, Tòa nhà HITC, 239 Xuân Thủy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(877, 197, 2, 'Backend Engineer (Go, Java)_Co-Lending Partnership', 'Become a Backend Engineer at Trusting Social and join our transformative Co-Lending partnership initiative, where you\'ll contribute to projects reshaping financial services globally and in Vietnam. Your work will involve enhancing automated credit evaluation systems to efficiently manage high volumes of applications through instant registration, approval, and decision-making processes. Furthermore, you\'ll play a key role in revolutionizing credit card experiences by facilitating instant issuance, payments, and providing numerous benefits to empower financial freedom for users.\n\nResponsibilities:\n- Develop Scalable Web Service APIs: Build highly scalable, highly available, and fault-tolerant web service APIs designed to handle millions of transactions per day.\n- Agile & DevOps Practices: Follow Agile methodologies and DevOps practices such as CI/CD to deliver quality code rapidly to market.\n- Seamless Integrations: Create software services that integrate effortlessly and securely with banks, third-party platforms, and vendors.\n- Innovative Problem Solving: Think outside the box, innovate, experiment, and continuously improve by learning quickly from failures to provide simple yet effective solutions to complex problems.\n\nYour skills and experience:\n\nEducational Background:\n- Bachelor’s degree or higher in Computer Science, Engineering, or a related field.\n\nExperience:\n- 5+ years of software development experience.\n- Solid expertise in Golang (or the confidence to learn it quickly when coming from other similar programming languages).\n\nAPI Design & Development:\n- Proficient in designing and developing RESTful APIs and gRPC interfaces.\n- Experience building backend services optimized for high performance, scalability, and reliability.\n\nDatabase Expertise:\n- Strong database and schema design skills for performance and scalability across both relational and NoSQL databases (e.g., MySQL, PostgreSQL, MongoDB, Redis, Elasticsearch, RocksDB).\n\nSystem Design:\n- Deep understanding of complex system design, design patterns, data structures, algorithms, microservices, and event-driven architecture.\n- Experience with system tuning for high performance and reliability.\n\nDevOps & Tooling:\n- Hands-on experience with CI/CD tools such as GitHub workflows and Jenkins.\n- Familiarity with Docker containers and Kubernetes.\n- Knowledge of automated testing practices, caching techniques, and version control systems like Git.\n\nNice to Have:\n- Experience with cloud platforms (AWS, GCP, or Azure).\n- Exposure to or interest in the AI domain with a willingness to leverage AI to enhance team productivity.\n- Experience with microservice architecture is a plus.\n\nWhy you\'ll love working here:\n- Competitive compensation package, including 13th-month salary and performance bonuses\n- Comprehensive health care coverage for you and your dependents\n- Generous leave policies, including annual leave, sick leave, and flexible work hours\n- Convenient central district 1 office location, next to a future metro station\n- Onsite lunch with multiple options, including vegetarian\n- Grab for work allowance and fully equipped workstations\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Havana Tower - 132 Ham Nghi, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(878, 566, 2, 'Senior Java Developer (SQL, Python)', 'We are looking for a Senior Java Developer to expand our Development team in Hanoi, Vietnam.\n\nOutpost24 empowers organizations to achieve cyber resilience with a complete range of continuous threat exposure management (CTEM) solutions. Our cloud platform unifies asset discovery and management, automates security testing, and quantifies risk in business context. Executives and security teams around the world trust Outpost24 to identify the attack surface and prioritize the most important security issues to accelerate risk reduction. Founded in 2001, Outpost24 is headquartered in Sweden, with additional offices in the US, the UK, the Netherlands, Belgium, Denmark, France, Spain and Vietnam.\n\nAs a Senior Java Developer, you will:\nYou will be part of one of development teams developing high quality tools for our product platform. You will be part of solving the challenges, we are working with. You will also help us integrate new technology that can improve our product or smarter deployment set. Further you will have a huge impact on the product feature set and implementation. If you want to make a difference, have an impact and develop by having highly skilled people around you - this could be the opportunity for you!\n\nWhat you will do:\n- Develop high quality code that is scalable, maintainable and secure.\n- Be creative to help find solutions to business requirements.\n- Constantly seek ways and technologies to improve our quality and performance.\n- Work in a development team to deliver a high-quality product in an agile work environment.\n- Be part of developing next generation security products.\n- Make a difference for the team.\n\nYour skills and experience:\n- At a minimum, you should have a bachelor’s degree in Software Development or equivalent.\n- Have solid understanding of the full software development life cycle.\n- Have at least five (05) years’ experiences with Java development tech stack and willingness to learn other programming languages.\n- Experience in SQL (PostgreSQL, SQLite, etc.)\n- Experience in working with Linux.\n- Experience in any of the following is an advantage:\n  - Python and Bash\n  - Scalable and high availability systems (Kubernetes, Kafka, containers, ELK etc.)\n  - Webservices\n  - Microservice architecture\n- Willing to work and migrate with legacy systems.\n- Have excellent and analytical problem-solving skills.\n- Have ability to learn quickly and manage yourself independently.\n- Have strong verbal and written communication skills in English.\n\nWhy you\'ll love working here:\n- An opportunity to work with experienced software engineers worldwide at market leading, innovative Scandinavian SaaS company looking to accelerate growth.\n- A modern working environment with fun colleagues and challenging tasks.\n- A Scandinavian work culture that emphasizes creativity, innovation, and work-life balance.\n- A competitive compensation and benefits package, with 100% salary during the probation period.\n- A 13th-month salary with an annual salary review.\n- Flexible working hours from Monday-Friday, with no overtime.\n- Premium healthcare and accident insurance: the best healthcare plan cover for employees and their children.\n- A wellness package supports employees in staying healthy and wealthy.\n- Exciting company outings/events and team-building activities.\n- A possibility to attend on-sites and conferences in Europe.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '18th Floor, Peakview Tower, 36 Hoang Cau, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(879, 353, 2, 'E-Banking Application Development Deputy Manager', '1. Trách nhiệm chính\n- Đảm bảo hệ thống ứng dụng ngân hàng điện tử hoạt động an toàn, ổn định, hiệu quả, đáp ứng mục tiêu và chiến lược phát triển của HDBank.\n- Đảm bảo các dự án phát triển ứng dụng ngân hàng điện tử thực hiện đúng yêu cầu về chất lượng và tiến độ.\n\n2. Các công việc thực hiện\n- Trình độ & kinh nghiệm làm việc:\n  - Chịu trách nhiệm làm việc trực tiếp với phòng ban nghiệp vụ và ghi nhận ý kiến trực tiếp của người dùng cuối để hoạch định kế hoạch phát triển NHĐT trong từng giai đoạn.\n  - Trực tiếp tham gia đánh giá, phân tích và thiết kế kiến trúc các ứng dụng ngân hàng điện tử đảm bảo hoạt động an toàn, ổn định và hiệu quả.\n  - Giám sát tiến độ thực hiện các dự án và công tác triển khai các sản phẩm mới lên hệ thống.\n  - Làm việc với các phòng ban, đối tác liên quan trong quá trình triển khai ứng dụng.\n  - Huấn luyện chuyên môn cho nhân sự, hỗ trợ giải quyết các vấn đề khó khăn và liên tục cải tiến hoạt động của hệ thống.\n  - Nghiên cứu và định hướng phát triển công nghệ đối với hệ thống ứng dụng ngân hàng điện tử.\n  - Phân tích các báo cáo về hệ thống và đánh giá các dự án đã thực hiện, từ đó đề xuất các giải pháp thực hiện các sản phẩm mới hiệu quả hơn.\n  - Thực hiện các công việc khác theo phân công của cấp trên.\n\n- Phát triển con người:\n  - Đảm bảo dự phòng nguồn lực, định hướng phát triển bản thân và các nhân sự phụ trách.\n  - Tổ chức khai thác, sử dụng hiệu quả, tối ưu các nguồn lực và ngân sách của phòng.\n  - Định kỳ đánh giá kết quả thực hiện công việc của các cán bộ, nhân viên, đề xuất các chế độ đối với cán bộ, nhân viên như tiền lương, tiền thưởng, khen thưởng, kỷ luật…\n\n- Tuân thủ:\n  - Đảm bảo toàn bộ hoạt động của Bộ phận tuân thủ theo các quy trình, quy định, tiêu chuẩn. Cải tiến quy trình hoạt động đảm bảo an toàn\n  - Hướng dẫn, giám sát việc triển khai chính sách, quy định, quy chế, quy trình.\n\nYour skills and experience\n1. Các yêu cầu về bằng cấp/chứng chỉ\n- Tốt nghiệp Đại học trở lên, chuyên ngành: CNTT hoặc các chuyên ngành tương đương.\n- Trình độ Tin học: thành thạo vi tính văn phòng.\n- Trình độ ngoại ngữ (Tiếng Anh): Khả năng giao tiếp tốt, đọc hiểu tài liệu liên quan.\n\n2. Yêu cầu về kinh nghiệm/kiến thức\na. Tối thiểu 05 năm kinh nghiệm công tác trong lĩnh vực sau:\n- Machine Learning & Deep Learning: Làm việc với các bài toán thị giác máy tính (Computer Vision), đặc biệt liên quan đến OCR tài liệu, nhận diện khuôn mặt, xác thực EKYC.\n- Lập trình Python: Thành thạo Python, có kinh nghiệm xây dựng pipeline huấn luyện và tiền xử lý dữ liệu cho AI/ML.\n- Làm việc với dữ liệu lớn: Có kinh nghiệm quản lý, xử lý và huấn luyện mô hình trên tập dữ liệu hình ảnh lớn (hàng trăm ngàn đến hàng chục triệu ảnh), biết cách tối ưu hóa pipeline dữ liệu (ví dụ: dùng TensorFlow Data API, multiprocessing, TFRecords, augmentation hiệu quả trên quy mô lớn).\n- Framework AI: Thành thạo TensorFlow hoặc công nghệ tương đương, nắm vững cách xây dựng, huấn luyện và tối ưu hóa mô hình. Có khả năng làm việc với PyTorch hoặc các nền tảng khác là điểm cộng.\n- Xử lý ảnh: Có kinh nghiệm sử dụng OpenCV, Pillow hoặc các thư viện xử lý ảnh để chuẩn hóa, tăng cường dữ liệu, và hỗ trợ quá trình huấn luyện mô hình.\n- Kiến thức thuật toán: Hiểu rõ các mô hình CNN, RNN/LSTM, Transformer ứng dụng trong OCR và nhận diện khuôn mặt. Có kinh nghiệm thực tế về Transfer Learning, Fine-tuning mô hình pre-trained.\n- Triển khai mô hình: Có kinh nghiệm đưa mô hình AI vào sản phẩm thực tế bằng TensorFlow Serving, TensorFlow Lite hoặc các phương pháp tối ưu mô hình inference.\n\nb. Có ít nhất 02 năm làm quản lý với vị trí tương đương.\nc. Hiểu biết chuyên sâu về các hệ thống CNTT ứng dụng trong ngân hàng.\nd. Có khả năng xây dựng chương trình, kế hoạch, khả năng tổng hợp, quan sát, nhạy bén và tạo sự đoàn kết khi làm việc.\n\n3. Các yêu cầu khác về phẩm chất, tính cách/kỹ năng, khả năng\na. Kỹ năng:\n- Kỹ năng tổ chức triển khai hệ thống ứng dụng ngân hàng điện tử.\n- Kỹ năng đánh giá hiệu suất công việc.\n- Kỹ năng đàm phán, thuyết phục.\n- Kỹ năng ra quyết định.\n- Kỹ năng quản lý nhân sự, đào tạo và định hướng phát triển. \n- Quản lý sự thay đổi.\n\nb. Tố chất:\n- Tính tuân thủ cao.\n- Điềm tĩnh.\n- Chính trực, đáng tin cậy.\n- Tự tin và  sáng tạo.\n- Chịu áp lực công việc.\n- Nỗ lực hướng tới kết quả.\n\nWhy you\'ll love working here\n- Thưởng 13,14\n- Thưởng theo xếp loại\n- Bảo hiểm y tế, bảo hiểm tai nạn\n- Du lịch nghỉ mát hằng năm\n- Tăng lượng định kì.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(880, 567, 2, 'Java Backend - 13T Lương', 'Top 3 reasons to join us\n- Mức thu nhập cạnh tranh, chế độ đãi ngộ hấp dẫn\n- MT trẻ và chuyên nghiệp, đồng nghiệp thân thiện\n- Được làm sản phẩm với lượng người dùng lớn\n\nJob description\n- Xây dựng các module lõi cho nền tảng Logistics thế hệ mới của ViettelPost.\n- Tối ưu hóa các nghiệp vụ, thuật toán, kiến trúc để nâng cao chất lượng sản phẩm.\n- Làm việc trực tiếp với các đội nghiệp vụ để thực thi sản phẩm theo đúng yêu cầu. Tư vấn ngược lại cho đội nghiệp vụ để thông minh hóa quy trình.\n- Xây dựng các sản phẩm mới phục vụ hàng triệu người dùng của ViettelPost\n(Thông tin dự án sẽ được trao đổi chi tiết trong buổi phỏng vấn)\n\nYour skills and experience\n- Tốt nghiệp Đại học các chuyên ngành CNTT, Khoa học máy tính,... Ưu tiên ứng viên tốt nghiệp các trường Bách Khoa, Học viện kỹ thuật quân sự, Học viện Bưu chính, ĐH Công nghệ-ĐH Quốc gia Hà Nội hoặc các trường ĐH đào tạo ở quốc tế.\n- Level Senior yêu cầu có 4++ năm kinh nghiệm phát triển phần mềm trở lên với ngôn ngữ JAVA, có kinh nghiệm với các framework như Spring, Quarkus, ZK.\n- Level Junior yêu cầu có 2++ năm kinh nghiệm phát triển phần mềm trở lên với ngôn ngữ JAVA, có kinh nghiệm với các framework như Spring, Quarkus, ZK.\n- Level Fresher yêu cầu tốt nghiệp đúng chuyên ngành tương đương CNTT, GPA từ 3.0/4 trở lên; tốt nghiệp các trường Bách Khoa, Học viện kỹ thuật quân sự, Học viện Bưu chính, ĐH Công nghệ-ĐH Quốc gia Hà Nội hoặc các trường ĐH quốc tế\n- Có kinh nghiệm làm việc với một trong các Database Oracle, MariaDB, Postgre, MongoDB, Redis, ElasticSearch.\n- Có kinh nghiệm làm việc với một trong các hệ thống Message Queue (Kafka, RabbitMQ, MQTT)\n- Có hiểu biết về thiết kế hệ thống, design pattern, OOP là một lợi thế.\n- Sử dụng thành thạo các công cụ quản lý code như SVN, Github.\n- Có kiến thức triển khai cơ bản hệ thống trên hệ điều hành Linux.\n- Có khả năng làm việc độc lập và làm việc nhóm, chịu được áp lực cao.\n- Có khả năng tư duy logic và nghiên cứu công nghệ mới\n- Có khả năng đọc hiểu tài liệu tiếng Anh chuyên ngành.\n\nWhy you\'ll love working here\nTại Tổng Công ty Cổ phần Bưu chính Viettel, các ứng viên sẽ được làm việc trong môi trường năng động, trẻ trung và chuyên nghiệp, với các đãi ngộ hấp dẫn sau:\n1. Chế độ về lương thưởng, thu nhập\n- Mức lương từ 15M - 30M đối với Junior, 30M - 50M đối với Senior, 50M++ đối với Teamleader (Chuyên gia).\n- Có chế độ hỗ trợ tiền điện thoại và ăn trưa, nghỉ mát hàng năm; kèm theo là các khoản thưởng vào các dịp lễ lớn (30/4, 1/5, 2/9, ngày thành lập Tập đoàn, Tổng Công ty, Tết Dương/ Âm)\n\n2. Chương trình chăm sóc sức khỏe\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và các gói bảo hiểm sức khỏe khác.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n- Phụ nữ có con nhỏ dưới 1 tuổi sẽ được nghỉ thêm 1h/ngày\n\n3. Đào tạo, phát triển\n- Hàng tuần, công ty tổ chức buổi Seminar trao đổi, chia sẻ về các công nghệ mới nhất; là cơ hội để các thành viên học hỏi lẫn nhau.\n- Được tham gia các khóa học bổ ích từ các diễn giả Quốc tế tại Học viện Viettel\n- Có cơ hội thăng tiến trong nghề nghiệp.\n\n4. Hoạt động tập thể hấp dẫn, phong phú\n- Tham gia vào hoạt động \'Happy Time" vào chiều thứ 6 hàng tuần cùng với chương trình sinh nhật tháng.\n- Chương trình teambuilding, văn hóa, du lịch nghỉ mát hấp dẫn và đa dạng.\n- Các hoạt động thể dục thể thao cùng các giải đấu được Tập đoàn tổ chức.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 2, Ngõ 15, Đường Duy Tân, Phường Dịch Vọng Hậu, Quận Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(881, 568, 2, 'Frontend Expert', 'Top 3 reasons to join us\n- Product environment, startup mindset\n- Open, dynamic, international working environment\n- Great package, 18 leave days, travel to Europe\n\nJob description\nYour responsibilities\n- Participate in innovative software development life cycle using agile methodologies\n- Be responsible for quality of technical solution of medium to complex application\n- Solve technical conflicts and make rationale decision between technical choices\n- Adhere to the coding standards, best practices, common design patterns & principles\n- Set standards, give technical directions, and perform reviews to verify the adherence to coding standards\n- Hand-on to solve complex technical issues. Perform code review, provide recommendations and directions for continuous improvement of the code quality, technical debt reduction, unit tests, coding standards\n- Collaborate with architecture team to update and/or build the technical designs.\n- Coach and train developers, help them to implement the software in line with the designs and standards, and to become independent on technical aspects\n- Self-manage in designing the technical stack for development projects. When necessary, research new or emerging technologies and frameworks, give recommendations, build proofs of concept and conduct trainings\n\nYour skills and experience\n- Bachelor\'s degree in computer science or equivalent\n- Has 8 years of proven experience in software development of this applied stack\n- Able to hands-on and set up code base for medium to complex application\n- Able to read and write technical documents, report in the English language\n- Able to bridge the technical discussions between developers and other non technical stakeholders\n- Able to work independently and as part of the team\n- Able to multi-task and prioritize tasks effectively\n- Has a wide range of technical knowledge in many areas such as: back-end, database, cloud\n- Ability to understand designs documented in mainstream methodologies such as ADD, UML and BPMN\n- Experienced in continuous integration and deployment technologies (Jenkins, Docker, Cloud)\n- Strong mindset and skillset in controlling technical quality, proven experience in design review, code review, and clean-code tools such as Sonar\n\nNice to have\n- Experience and/or certifications on Amazon, Azure and Oracle clouds\n- Experience on IT Operations and live systems (in production)\n- Knowledge of the Agile methodology (Scrum)\n- Knowledge of other programming languages\n- Experience in leading a project or a team\n\nWhy you\'ll love working here\n- Professional European-based company\n- Attractive salary\n- Performance bonus of up to 4 months’ salary\n- Opportunities for travel to Europe\n- Hybrid home/office working model\n- Flexible working time\n- Structured training & development roadmap\n- Good work-life balance\n- Premium healthcare insurance\n- Loyalty programs\n- Well-being activities\n- Annual company trips and team-building events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CII Building, 152 Điên Biên Phủ, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(882, 224, 2, 'Senior/Principal Golang Engineer (Backend, AWS, mySQL)', 'We have exciting opportunities for 1 Senior and 1 Principal Golang Engineers to join our dynamic team. Key responsibilities include:\n- Design and develop services which can handle a massive amount of data\n- Design good database considering functional and non-functional requirements\n- Write clean and maintainable code\n- Improve code by continuous refactoring\n- Monitor application performance and fix system failures\n- Train junior/middle members\n\nYour skills and experience\n\nMust Have\n- From 5 years of experience in Backend Development\n- Solid experience with Golang\n- Good understanding of SOLID principles, common design patterns and best practices\n- Solid experience with MySQL or PostgreSQL including performance tuning and optimization\n- Experience with complicated system architecture which includes API linkage with external systems\n- Experience with application performance monitoring and optimization\n- Experience with automation testing, E2E testing\n- Extensive knowledge of web security\n- Familiarity with CI/CD, Docker\n- Good English communication skills\n- Experience of leading a project as a team leader\n- Strong sense of ownership\n\nNice to Have\n- Understanding of Graphql.\n- Understanding of Google Cloud Platform.\n- Experience with Amazon Web Services\n- Experience with service operation on production\n- Experience with frontend development (TypeScript, ReactJS/VueJS)\n- Experience of training junior/middle members\n\nWhy you\'ll love working here\nCaring Mental & Physical Recreation:\n- Hybrid working\n- Full salary in probation & 13th month salary\n- Social insurance on full salary from probation\n- Premium Health insurance from probation\n- Flexible start 8AM-9AM from Mon-Fri\n- 16 days off annually + 1 Birthday Leave\n- Paternity leave extra 5 days\n- Annual company trip; Quarterly team building activities\n- Club activities\n- Annual health check\n\nCaring Career & Development:\n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- Well-equipped facility: Macbook pro,  additional monitor,..\n- Soft skill workshops\n- Tech seminars\n- Monthly and biannually Recognition Awards\n- Performance review twice/year', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(883, 182, 2, 'Mobile Technical Lead (iOS, Android, Kotlin, Swift)', 'Are you an experienced Mobile Technical Lead looking for your next career move? Do you have a background in design & architecture and development of digital products? If so read on.\n\nThe team:\nYou will be part of our Digital Delivery Hub who are responsible for designing, developing and maintaining some of the most interesting and innovative digital apps within the financial services space that are at the forefront of the market. Our Hub is focused on building a world class User Experience, Design and Web / Mobile Development team that can work with the business to realise an exciting digital strategy.\n\nThe role:\nWe are looking for a talented Mobile Technical Lead who still does hands-on development to contribute in the development and execution of an innovative mobile banking solution in Asia. This will include the development of in-country and cross-border solutions across all facets of a mobile banking operation including customer experience and design, developing and implementing new products and services, process engineering and other functional deliverable. Risk management and technology innovation will be essential for your success.\n\nYou will be responsible for technically leading and coaching our engineers who work in cross-functional delivery teams to design and build best-of-breed mobile solutions whilst maintaining necessary support for ongoing products.\n\nYour duties will be to:\n- Collaborate with our technical leaders to establish a vision for our mobile engineering initiatives. Design and develop cutting-edge applications for Android and iOS platforms.\n- Work closely with cross-functional teams to define, design, and deliver new features.\n- Provide coaching, guidance, and mentorship to mobile developers to facilitate their professional growth.\n- Work on addressing bugs and improving application performance.\n- Continuously research, evaluate, and implement innovative technologies to optimize development efficiency.\n- Participate in the planning process for software development projects, ensuring adherence to quality standards and timely delivery.\n- Design the architecture for new products and features.\n- Provide leadership and mentorship to a team of mobile developers, offering guidance and support to achieve individual objectives and deliver high-quality code.\n\nYour skills and experience\nTechnical Skills:\n- 6+ years of experience in Mobile Development.\n- 2+ years of experience as a Mobile Development Team Leader.\n- Proven expertise in either iOS (SwiftUI and UIKit) or Android (Kotlin) development. While proficiency in both platforms is not mandatory, it will be a plus.\n- Experience working on various mobile apps, preferably large-scale applications with multi-country targets.\n- Experience with modern mobile architecture.\n- Having experience in KMP(Kotlin Multiplatform) development is a big plus.\n- Familiarity with backend development technologies (E.g. APIs and databases)\n- Experience with continuous integration and continuous delivery/continuous deployment.\n- Experience with Modularization and code artifact management.\n\nSoft skills:\n- Excellent communication and teamwork abilities.\n- Excellent problem-solving and analytical skills.\n- Strong willingness to learn new practices and technologies.\n- Exceptional interpersonal skills, including facilitation and negotiation.\n- Understanding and experience of Agile methodology.\n- Experience in working across several technical domains with the ability to ‘deep dive’ where required and ensure correct solutions are implemented.\n- Ability to translate technical talk to the business.\n- Ability to deliver convincing presentations that provide significant insight and generate consensus and buy-in.\n- Experience managing and leading a development team.\n\nWhy you\'ll love working here\nYou’ll love working with us if you are:\n- Passionate about technology.\n- Independent but also a good team player.\n- Comfortable with a high degree of ambiguity.\n- Focused on usability and speed.\n- Keen on presenting your ideas to your peers and management.\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\n\nSome of our benefits:\n- Meal and parking allowances are covered by the company.\n- Full benefits and salary rank during probation.\n- Insurances such as Vietnamese labor law and premium health care for you and your family.\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\n- Values-driven, international working environment, and agile culture.\n- Overseas travel opportunities for training and work-related.\n- Internal Hackathons and company events (team building, coffee run, etc.).\n- Pro-Rate and performance bonus.\n- 15-day annual + 3-day sick leave per year from the company.\n- Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower, Lumiere Riverside, 277 Vo Nguyen Giap, An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(884, 569, 2, 'Senior Java Developer (Spring, MySQL, Hibernate)', 'The Role:\nThe incumbent is responsible assisting the IT head or team in the facilitation, coordination, implementation, executive, control and completion of each marketing project for the business need; while remaining aligned with strategy, commitments, and goals of the organization.\nJob Responsibilities:\nThe position requires strong attention to detail, operational task management and problem- solving ability.\n1. Maintain high quality of products with participation in code review and design reviews.\n2. Build high quality products and contribute important impacts on our product roadmap planning.\n3. Propose and implement solutions/product with Java, JavaScript, SQL, Spring, Python and Shell Scripts.\n4. Provider guidance to Junior and suggestion to other colleagues with deep understanding of technology stacks.\n5. Propose better software architecture with the right design pattern for a suitable situation.\n6. Provide in depth support to Technical Support Analyst.\n7. Work with front end team to build a high perform, user friendly and stable web product.\n8. Solving puzzles from clients’ feedback and logs to find out the real cause.\n9. Research on up-to-date technology stacks to continue bring better performance and higher quality products to stakeholders.\n10. Write down documentation for different technology and knowledge to share knowledge among everyone.\n11. Provide insight for database performance and stability.\n\nYour skills and experience:\n1. Diploma / Bachelor’s Degree / Professional Certificates in Computer Science / Information Technology / Software Engineering, etc.\n2. From 7 years - 12 years+ of relevant experience in Java web development.\n3. Familiar with Java, JavaScript, SQL and Shell Scripts.\n4. Have experience in guiding or mentoring juniors/freshers.\n5. Candidate should possess a good understanding of and practical experience with Java Web based application development.\n6. Strong Java skills and object-oriented design experience, and design patterns.\n7. Experience in using Spring & Hibernate in programming works are highly preferred.\n8. Familiar with Unix/Linux environment.\n9. Familiar with different source control tools.\n10. Good knowledge with microservices is an added advantage.\n11. Experience in database performance tuning and query enhancement is an added advantage.\n12. Experience in dev-ops relevant tasks is an added advantage.\n13. Knowledge on Billing/charging interface/API is an added advantage.\n14. Ability to work with customers and identify adoption barriers and put forth plans to address these issues.\n15. Excellent analytical, problem solving, teamwork and communication skills.\n16. Willing to go extra mile to get job done at high standard.\n17. Required language(s): Good English communication skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cobi Tower 2, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(885, 570, 2, 'Mid/Senior QA/Tester (Remote, upto $2000)', 'About EasyRx: EasyRx is an innovative healthcare technology company revolutionizing how patients access and receive prescription medications through local pharmacies. Our platform connects patients, doctors, and local pharmacies to provide cost-plus prescription delivery services, making healthcare more accessible and transparent. Position Overview: We\'re seeking a detail-oriented Quality Assurance Tester to join our growing team. The ideal candidate will help ensure the quality and reliability of our web and mobile applications that serve patients, healthcare providers, and pharmacies. Key Responsibilities: Execute manual testing across web applications and mobile applications (iOS/Android) for our product. Create and maintain detailed test cases and test plans. Perform functional, regression, and user acceptance testing. Verify proper integration between patient, provider, and pharmacy interfaces. Document and track bugs using issue tracking systems. Work closely with developers to resolve identified issues. Validate compliance with HIPAA requirements and healthcare data security standards. Your skills and experience: Required Qualifications: 3-6 years of software QA testing experience overall. 2-3 years of web applications testing experience. 3-4 years of mobile apps testing experience (iOS/Android). Experience with test case management tools and bug tracking systems. Excellent attention to detail and problem-solving skills. Strong verbal and written communication abilities (English and Vietnamese). Ability to work independently and manage multiple testing priorities. Preferred Qualifications: Experience testing healthcare or pharmacy applications. Knowledge of HIPAA compliance and healthcare data security. Experience with API testing. Familiarity with Agile development methodologies. Experience testing payment processing systems. Experience working in a startup environment. Why you\'ll love working here: Opportunity to make a significant impact on healthcare accessibility in the United States. Remote-friendly work environment. Collaborative and innovative team culture. Professional development opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote HCM, District 1, Ho Chi Minh; Remote, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(886, 571, 2, 'Backend Developer (PHP/ .NET/ SQL)', 'Job description\n- Tiếp nhận các yêu cầu thay đổi, phát triển thêm các chức năng, báo cáo từ các đơn vị nghiệp vụ sử dụng phần mềm. \n- Phối hợp team phát triển ứng dụng (DEV) & ERP để phân tích, đánh giá các yêu cầu, chức năng nghiệp vụ, báo cáo của phần mềm. \n- Thực hiện lập trình, phát triển các chức năng, báo cáo của hệ thống ERP, các phần mềm khác của Công ty. \n- Quản trị, phân tích cơ sở dữ liệu Database của các phần mềm. \n- Tham gia triển khai các phần mềm mới của Công ty. \n- Tiếp nhận tài liệu kỹ thuật, mã nguồn (Source code) từ các nhà cung cấp phần mềm để quản lý, phát triển.\n\nYour skills and experience\n- Nam, tốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT, lập trình \n- Kinh nghiệm 02 năm trở lên lập trình phát triển phần mềm. \n- Sử dụng tốt các ngôn ngữ: PHP/.NET, cơ sỏ dữ liệu SQL Server, PL/SQL các Framework, công cụ của ứng dụng, tích hợp API. \n- Có kinh nghiệm lập trình, phát triển ERP (ưu tiên Oracle) & các phần mềm khác. \n- Làm việc độc lập & theo nhóm \n\nWhy you\'ll love working here\n- Lương : 15 – 20 triệu (gross) – thử việc 2 tháng \n- Sau thử việc , tham gia BHXH theo quy định. \n- Phụ cấp tiền điện thoại, tiền cơm trưa, giữ xe \n- Lương tháng 13 \n- Du lịch hằng năm; khám sức khỏe tổng quát 1 năm 1 lần ở BV lớn (BV Đại học Y Dược, BV Xuyên Á..) \n- Thưởng 500k/mỗi dịp lễ : giỗ tổ; 30/4; 1/5; 2/9….. \n- Nghĩ Tết 2 tuần không trừ lương (chỉ trừ phép). \n- CTY + CÔNG ĐOÀN Tặng quà cho CB-CNV mỗi dịp Tết; Tết thiếu nhi; Học bổng cho con em CB-CNV có thành tích học tập tốt. \n- Nếu là thành viên lâu năm (36 tháng) sẽ được cty mua riêng gói Bảo hiểm toàn diện (PVI, MIC..) \n- Đề xuất tăng lương hằng năm theo chính sách của công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, tòa nhà VRG, số  177 Hai Bà Trưng, P. Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(887, 275, 2, 'Senior/Lead Java Developer (Spring)', 'Development is the largest discipline at Endava. Our developers design, build, and release software products in multiple programming languages, frameworks, and libraries. Always collaborating with cross-functional project teams, our developers are adaptable problem-solvers with a client-oriented mindset. \n\nAs a Senior Developer (Java) at Endava, you will work in a professional and cross-functional team for payment gateway services. You\'ll be involved in the full development lifecycle of a software system. Contribute to delivering new products to the market by meeting customer\'s requirements and product development programs. Be an integral part of a Scrum team and contribute to Agile processes.\n\nResponsibilities:\nDesigns, estimates, and implements technical solutions for medium/high complexity applications.\nParticipates actively in all phases of the application development lifecycle.\nCollaborates with various project stakeholders to provide support for clarifying requirements, processes, architecture, and priorities.\nRecommends and promotes IT industry standards, tools, and practices (DevOps, etc.) to achieve well-engineered software products.\nProposes improvements and escalates risks/issues related to development activities.\nParticipates in the review of the work done by development team members.\nLearns and applies new technologies, practices, and tools as appropriate to the project.\nParticipates in internal and external tech communities, events, etc.\nShares experience and knowledge gained from projects.\n\nYour skills and experience\n5+ years of experience in software development \nStrong command of Java, with hands-on experience using IntelliJ IDEA, Spring, Hibernate, Maven/Gradle \nDeep understanding of OOP, design/architectural patterns, and clean code principles (SOLID, GoF, MVVM) \nPractical experience in platform-specific database systems and SQL. \nProficient in version control systems such as Git \nSolid experience with testing and mocking frameworks. \nFamiliar with communication protocols such as HTTP, REST, JSON, TCP/IP. \nExperience with Agile methodologies (e.g., SCRUM, KANBAN). \nKnowledge of CI/CD tools and practices. \nGood problem-solving skills and analytical thinking. \nExcellent communication and collaboration abilities \nUpper-intermediate English proficiency \n\nWhy you\'ll love working here\nAt Endava, we are offering opportunities and exciting development for our people to build an engaging technical community. \n\nCareer coaching, learning and development: Certifications, soft skills, training licenses.\nEndava Digital Library and tech conferences. \nCulture and work environment: Company-sponsored team-based sports, hobby clubs, tech & social communities.\nSome of our benefits\nFinance: Competitive salary package, annual leave encashment, 13th month salary, referral bonus; \nCareer Development: Career coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership;\nLearning Opportunities: Complex projects, rotations, internal tech communities, training, coaching, online learning platforms subscriptions, English programme, certifications, pass-it-on sessions, workshops, conferences;\nWork-Life Balance: Hybrid work and flexible working hours, employee assistance programme;\nHealth: Global internal wellbeing programme, access to wellbeing apps, premium health check, extra insurance;\nCommunity: Global internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations;\nOther: Trade Union benefits, Welcome package and gift-giving frequency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '9-11 Dong Da street, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(888, 377, 2, 'Backend Developer (Java, Node.JS)', 'Job description\n• Develop responsive, high-performance web applications using Node.JS, Java. Expert at building web applications backend from scratch.\n• Manage and optimize server infrastructure on AWS.\n• Troubleshoot and resolve technical issues promptly.\n• Optimize applications for speed, scalability, and cross-browser compatibility.\n• Keep up with the latest backend technologies and industry trends. Maintain documentation for projects and ensure compliance with industry standards.\n\nYour skills and experience\n• Minimum of 3 years of experience in backend development using Java, Node.JS.\n• Familiar with RESTful APIs and working with third party APIs\n• Experience with some types DBMS like MySQL, MariaDB, ...\n• Advanced skills in managing and utilizing AWS servers.\n• Strong problem-solving skills and high attention to detail. Excellent communication and team collaboration abilities.\n• Proficiency with Git and version control practices.\n• High level of diligence, meticulousness, and responsibility in work.\n\nWhy you\'ll love working here\n• Opportunities for professional development and growth\n• Collaborative and innovative work environment\n• Working equipment provided by the company\n• Join birthday party, holiday party organized by the company\n• Review 1 ~ 2 times per year', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Apartment B1, D’ Verano Residential, Thu Thiem new urban area, An Khanh Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(889, 572, 2, 'Fullstack Web Developer (.NET/VueJS)', 'Top 3 reasons to join us\n- Xét tăng lương định kỳ hằng năm\n- Được đóng bảo hiểm xã hội đầy đủ\n- Thưởng Tết hấp dẫn\n\nJob description\n- O&M (Operation & Maintenance) cho các hệ thống web như DDMS, R+, EOS tại Việt Nam.\n  - Công nghệ chính: .NET, Vue.js\n  - Nhiệm vụ: Giám sát hệ thống, xử lý sự cố, tối ưu hiệu suất → đảm bảo hệ thống vận hành ổn định.\n- Xây dựng tài liệu O&M và hệ thống tri thức nội bộ.\n  - Ghi lại quy trình xử lý, hỗ trợ tối ưu hóa tương lai.\n- Phát triển API:\n  - Thiết kế và xây dựng các API chất lượng cao.\n  - Đảm bảo tính ổn định, bảo mật, dễ sử dụng.\n- Phát triển frontend:\n  - Thành thạo Vue.js và Nuxt.js.\n  - Tập trung vào trải nghiệm người dùng và giao diện trực quan.\n- Quản trị CSDL:\n  - Làm việc với SQL Server: CRUD cơ bản, backup dữ liệu.\n  - Cấu hình IIS server trên Windows:\n    - Biết cách triển khai, cấu hình, khôi phục khi gặp sự cố.\n- Kỹ năng phân tích & xử lý sự cố:\n  - Có khả năng logic tốt, xử lý nhanh các sự cố vận hành.\n- Kỹ năng giao tiếp với khách hàng:\n  - Giao tiếp tốt bằng tiếng anh\n  - Chủ động lắng nghe phản hồi, đưa yêu cầu từ khách hàng về cho team phát triển nội bộ.\n- Ý thức bảo mật thông tin cao:\n  - Hiểu và áp dụng các kiến thức về an ninh thông tin trong công việc.\n\nYour skills and experience\n- Kinh nghiệm:\n  - Tối thiểu 3 năm kinh nghiệm trong phát triển .NET, web và O&M.\n  - Ưu tiên ứng viên có kinh nghiệm full-stack.\n- Kỹ năng chuyên môn:\n  - .NET / C#: Thành thạo, có khả năng phát triển và bảo trì hệ thống độc lập.\n  - API Development: Có nhiều kinh nghiệm với RESTful APIs, Viết API chất lượng cao.\n  - SQL Server: Thành thạo SQL, biết thiết kế và tối ưu CSDL.\n  - Windows IIS: Có thể triển khai và bảo trì môi trường server độc lập.\n  - Vue.js / Nuxt.js: Phát triển và duy trì giao diện front-end hiện đại.\n  - English: Có khả năng giao tiếp tốt bằng tiếng Anh với khách hàng và quản lý người nước ngoài.\n\nWhy you\'ll love working here\n- Xét tăng lương định kỳ hằng năm dựa trên hiệu quả công việc và mức độ cống hiến.\n- Có quỹ ăn uống riêng cho team – thường xuyên tổ chức ăn uống, giao lưu gắn kết đội ngũ.\n- Văn phòng luôn có sẵn đồ ăn vặt, nước uống và cà phê phục vụ nhân viên trong giờ làm việc.\n- Được đóng bảo hiểm xã hội đầy đủ theo quy định nhà nước ngay khi ký hợp đồng chính thức.\n- Thưởng Tết hấp dẫn, tùy theo kết quả kinh doanh của công ty và thành tích cá nhân.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '69 đường Tân Lập, phường Đông Hòa, Di An, Binh Duong', 'Full-time', '2025-10-07 20:59:18.149534'),
	(890, 526, 2, 'Technical Lead (Java, English, ID Platform)', 'ABOUT US\nBy reinventing the old industry with new technology’s power, RAKSUL is delivering satisfaction and happiness to customers every day with global offices in Japan, Vietnam, and India. \nOur company operates multiple web services, and a seamless service experience powered by a unified ID across the organization is essential. \nWe are looking for comrades to create great products in HCMC office together!\n\nRESPONSIBILITIES\nThis role provides the opportunity to transform the customer experience from both technical and business perspectives. By leading the adoption of new technology stacks and modernizing legacy monolithic applications, you will enhance service value and significantly impact the overall business. \nWe seek a leader with both technical expertise and a business-oriented mindset to drive this success. Your mission is to build a cross-functional ID platform that provides a smooth service experience to our customers, promotes site usage, and enhances the overall value of our business.\n\n- Lead technology selection and software architecture decisions\n- Manage project timelines and deliverables\n- Ensure code quality and release quality\n- Facilitate smooth communication with relevant stakeholders to ensure project success\n- Ensure the security level meets business requirements\n- Operate the core platform services in the production environment and develop additional features\n\nYour skills and experience\nQualification\n- Decent communication English skill to work with global members.\n- Over 10 years of experience as a server-side engineer.\n- At least 5 years experience in Java development.\n- Hands-on experience with front-end technologies.\n- Proven expertise in designing and developing medium to large-scale applications.\n- Practical experience with authentication and authorization middleware, including Keycloak, AWS Cognito, Auth0, and similar platforms.\n- Strong foundational knowledge of core technologies such as authentication, authorization, session management, and secure web application development.\n- Demonstrated ability to proactively address challenges and communicate effectively.\n\nNice to have:\n- Experience in Ruby/Go/NodeJS\n- Experience in designing and developing ID platforms\n- Experience in modernizing legacy applications\n\nWhy you\'ll love working here\n- 15 annual days of a year, and also available during probation time\n- Premium Private healthcare package\n- Salary review TWICE a year with attractive performance bonus up to 2 months\n- MacBook Pro, Ergonomic chairs, 140cm wide desk from your first working day\n- Individually tailored learning and development plan\n- Boost your English with in-house training by a native teacher\n- Maintain work-life balance with in-house activities, sports clubs, and regular events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '34th Floor, Lim Tower 1, 9-11 Ton Duc Thang, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(891, 245, 2, 'Back End Python Developer (Python, AWS)', 'LG CNS is a leading IT service provider, delivering innovative solutions in AI, cloud computing, big data, and smart factory automation. Our Vietnam Build Center is expanding, and we are looking for talented Python Developers to join our growing team.\n\n- Develop, optimize, and maintain scalable Python applications.\n- Collaborate with cross-functional teams to design, develop, and deploy software solutions.\n- Write clean, efficient, and well-documented code following best practices.\n- Debug and troubleshoot issues to ensure application stability and performance.\n- Work with databases, APIs, and third-party libraries to build robust applications.\n- Participate in code reviews, design discussions, and Agile development processes.\n\nYour skills and experience:\n[Required]\n- 3+ years of experience in Python development.\n- Bachelor\'s degree\n- Proficiency in Python frameworks such as Fast API\n- Experience in working with ORM such as SlqAlchemy, JPA\n- Experience working with DB Configuration Management such as Alembic, Flyway\n- Experience in debugging in Kubernetes, Docker/Container, Cloud (AWS) environment\n- Experience in AWS Cognito/AWS S3/AWS SES/AWS Lambda\n- Strong problem-solving and analytical skills.\n- Good communication skills and the ability to work in a team environment.\n\n[Preferred]\n- Experience with Resource optimization\n- Experience in solving complex problems with Application and Cloud resource\n- Experience in Digital Marketing domain\n\nOpportunity\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Topik allowance\n- Review capacity annually and adjust salary increases according to work performance.\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8 hours/day)\n\nWhy you\'ll love working here:\n- Best remuneration: Periodically review and adjust salary once a year, PI bonus twice a year. Allowances for lunch, transportation, and phone charges. Party with the team once a year. Workshop travel for the whole company once a year. Bonuses/Gifts for holidays, International Labor Day, International Women\'s Day, etc.\n- High-class, modern office: 5-star standard office with modern equipment, large rest and entertainment areas (game area, karaoke room, reading room, cafe counter, snack bar, etc.) Meet all members\' needs, especially the office has an airy and beautiful view that is among the most beautiful in Hanoi.\n- Top equipment: Each employee is equipped with the latest generation LG Gram laptop and modern large LG screen.\n- Best working time: Work 8 hours/day (8:00 ~ 17:00), from Monday to Friday. No pressure to work overtime/weekends!\n- Flexible, youthful working style: LG CNS Vietnam members are mostly from the 9-10x generation, with a youthful, modern, and fair working style!\n- Creative environment, valuing individual opinions: With a young and talented team, we always appreciate the creativity and suggestions that members make.\n- Opportunities to work/study in Korea and abroad: With customers and projects mostly from abroad, your opportunities for training and onsite abroad will always be open!\n- Other: Happy hours every Friday, Team outing monthly, join clubs like football, badminton, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa Keangnam Landmark 72, Mễ Trì, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(892, 366, 2, 'Frontend Engineer (ReactJS) - Webtoon', 'NAVER Corp is South Korea’s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia’s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the best workplace by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us:\n\nWe are looking for the Frontend Engineer (ReactJS) in the Ha Noi office.\n\nYour daily tasks:\n- Develop and operate Webtoon Services.\n- Co-Work with Global Webtoon Teams.\n\nYour background:\n- Should have the knowledge of advanced ReactJS.\n- Ideally, 5+ years of work experience on Frontend to serve large-scale and high-traffic projects.\n- Enjoy discussions about the stability and scalability of Frontend systems.\n- Good understanding of asynchronous request handling partial page updates, AJAX, NodeJS, SSR.\n- Experience in Data Structure, Algorithm, Distributed Service.\n- Understand the importance of writing high Maintainable Code, Clean Code.\n- Open-minded, honest and have a positive attitude towards people.\n- Good at communication skills in general and English skills in particular.\n\nIt’s a big plus if you:\n- Familiar with Front-end performance optimization.\n- Experience in Responsive Web.\n- Experience in developing and operating with Node.js.\n- Experience in developing and operating with Docker & Kubernetes.\n- Big Plus, you can communicate basically in Korean.\n\nWhy you\'ll love working here:\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n- A work-life balance: Hybrid working model with modern city-center offices, 14 days of annual leave (increasing yearly) and an additional day off for your birthday.\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills.\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7.\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(893, 492, 2, 'Middle/Senior Flutter Developer', 'Top 3 reasons to join us\n1. Competitive salary and bonus\n2. Young and innovative working environment\n3. Work with the brightest minds\n\nJob description\n- Tham gia sâu vào quy trình phát triển sản phẩm, từ lên ý tưởng, làm rõ yêu cầu, thiết kế giải pháp công nghệ và phát triển tính năng. Phối hợp và tư vấn giải pháp công nghệ, cùng các thành viên khác thiết kế sản phẩm hợp lý, mang lại giá trị cao về business.\n- Nhận thiết kế qua Figma và dựng UI/UX theo Designer yêu cầu. Hoặc thiết kế nháp bằng Wireframe, dựng nhanh tính năng/sản phẩm và yêu cầu Designer hoàn thiện lại và dựng UI/UX. Điều chỉnh / phản biệt lại thiết kế với UI/UX Designer nếu thiết kế bị thiếu luồng, thiếu màn hình hoặc tốn quá nhiều efforts nhưng không mang lại nhiều giá trị sản phẩm (ROI thấp)\n- Thiết kế và xây dựng Mobile app hiệu năng cao, tiết kiệm pin, tối ưu hoá dưng lượng băng thông. Đảm bảo chất lượng UI/UX trên các kiểu và kích cỡ màn hình khác nhau; trên các nền tảng khác nhau (iOS / Android)\n- UI/UX: Sử dụng và tối ưu các thư viện và cơ chế xử lý dữ liệu realtime và trình diễn dữ liệu (data visualization) với hiệu năng cao, nâng cao trải nghiệm giao dịch Nhanh, Mượt và Chính xác cho các nền tảng đầu tư của Encapital\n- UX: Tập trung vào tính chi tiết và bố cục hợp lý của Button, Table, Box, Tooltips… hiển thị trên sản phẩm. Tạo hiệu ứng nâng cao chất lượng tương tác tại các điểm chạm sản phẩm với người dùng.\n- Code quality: chủ động và có trách nhiệm trong việc nâng cao chất lượng code thông qua automated testing / refactor tech debts / code reviews. Áp dụng các kỹ thuật best practice như DRY, KISS, etc. vào thực tế để có code base đẹp, dễ maintain và dễ tiếp cận với người mới. Tham gia review code của các thành viên khác / projects khác để hiểu rõ mọi hệ thống của công ty cũng như nâng cao tiêu chuẩn chất lượng code của cả team.\n- Chủ động nghiên cứu các công nghệ mới, sẵn sàng chia sẻ thông tin và kiến thức cho các thành viên khác cùng phát triển, và đưa các công nghệ mới vào ứng dụng tại các dự án của công ty.\n- Đóng góp ý kiến, cải thiện và nâng cao hiệu quả của quy trình phát triển phần mềm theo Agile và Scrum.\n\nYour skills and experience\n- Có kinh nghiệm từ 3 năm trở lên trong vai trò Frontend Developer cho nền tảng Mobile.\n- Thành thạo Flutter. Hiểu rõ các kiến thức cơ bản, nâng cao, best practices.\n- Sử dụng cơ bản một công cụ thiết kế UI/UX như Figma, Adobe XD, Adobe Ai/Photoshop, Principle, …\n- Có khả năng tự thiết kế (draft) và dựng nhanh sản phẩm mà không cần chờ có thiết kế.\n- Có kiến thức nền tảng tốt về khoa học máy tính và phát triển phần mềm.\n- Kỹ năng giao tiếp tốt, có khả năng giải thích, trình bày kiến thức một cách rõ ràng, dễ hiểu.\n- Có kiến thức về các build tools.\n- Có kiến thức tốt về networking là lợi thế.\n- Hiểu và ứng dụng được CICD.\n- Hiểu và ứng dụng được các principles trong thiết kế, phát triển phần mềm.\n- Hiểu về frontend optimization và ứng dụng được trong dự án thực tế.\n\nĐiểm cộng:\n- Kinh nghiệm với Dart và Typescript là một lợi thế nhưng không bắt buộc\n- Thẩm định được tính logic và thẩm mỹ của UI/UX Design.\n- Có nhiều kinh nghiệm cải thiện UX người dùng\n- Đã có kinh nghiệm trên 1 năm xây dựng, tối ưu sản phẩm đáp ứng lượng truy cập lớn (- 1 triệu lượt truy cập/ngày trở lên).\n- Kiên trì, tỉ mỉ, trách nhiệm.\n\nWhy you\'ll love working here\n- Quyền lợi\n- Môi trường đồng nghiệp giỏi, thuộc hàng ngũ top 1% trong lĩnh vực. Cởi mở, năng động, hỗ trợ đồng đội cùng phát triển.\n- Văn hoá startup tập trung vào sản phẩm và khách hàng, song song với phát triển năng lực team và cá nhân\n- Được chịu trách nhiệm làm các tính năng quan trọng của sản phẩm mới (ko phải dự án maintain). Thử thách với chuỗi sản phẩm có yêu cầu UX và tính thẩm mỹ cao.\n- Cơ hội phát triển sự nghiệp rõ ràng tại một trong các startup đang phát triển nhanh nhất VN (vốn hoá công ty hiện đạt 150 triệu $)\n- Lương thưởng và đãi ngộ thuộc hàng TOP của thị trường\n- Chế độ BHYT cao cấp (PVI) do công ty chi trả; BHXH và nghỉ phép theo quy định của nhà nước\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 tòa nhà Pax Sky số 63-65 Ngô Thì Nhậm, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(894, 256, 2, 'Python Backend Developer (Junior)', 'About Endash\nEndash is revolutionizing data analytics with our AI-powered data integration and visualization platform. We enable businesses of all sizes to easily build data pipelines and dashboards without requiring dedicated data teams. Our solution connects to over 500 data sources and features innovative AI tools including Text2SQL functionality and automated insight generation, allowing non-technical users to perform complex data analysis without coding knowledge.\nPosition Overview\nWe are seeking a Python Developer to join our growing team.\nIn this role, you will design and implement web applications using Python/FastAPI that power our data integration and visualization platform.\nYou will also help architect and implement technical solutions that address both business and product challenges, ensuring our applications remain consistent, high-performing, and scalable.\nKey Responsibilities\nDesign and develop robust web applications using Python/FastAPI.\nImplement technical solutions to address business and product challenges.\nOptimize application performance and scalability to ensure efficient operations.\nContribute to the architecture and design of highly scalable systems.\nDevelop and maintain CI/CD pipelines.\nCollaborate with cross-functional teams to deliver high-quality software solutions.\nYour skills and experience\nStrong problem-solving skills and analytical thinking.\nConfidence with Python. Experience with FastAPI and SQLAlchemy is a huge plus.\nFamiliarity with the following technologies: PostgreSQL, BigQuery, Redis, Kafka, Trino.\nStrong SQL skills and experience with database optimization.\nUpper-intermediate level of spoken English for effective communication.\nProficient in Python concurrency.\nSolid understanding of containerization technologies like Docker and Kubernetes.\nGood understanding of CI/CD pipelines.\nExperience in Data Engineering industry is a plus.\nFamiliarity with orchestration tools such as Airflow, Prefect, etc., is a plus.\nExperience in distributed systems is a plus.\nWhy you\'ll love working here\n13th-month salary: calculated as one month\'s actual basic salary if the employee works for 12 months of the calendar year.\nAnnual Leaves : employee who has been working for 12 months or more is entitled to fully-paid annual leave with 12 days.\nSocial Insurance, Medical Insurance, Unemployment Insurance: Yes\nConvenient shared office in Thao Dien, HCM\nFlexibility in commuting time (8:30~9:30 AM)\nFlexible working time with notice (ex. Visiting hospital, bank etc)\nLatest device support in any type (Mac, monitors etc)\nWorking 5 weekdays (Mon-Fri)\nWork-related books and lectures supported\nExternal activities (Clubs)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thao Dien, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(895, 573, 2, 'Fullstack Developer (.NET, Java, Python)', 'Job description\n- Lập trình các ứng dụng phần mềm phục vụ cho hoạt động sản xuất, kinh doanh của Công ty trên các nền tảng web, windows form. Cụ thể:\n- Phối hợp với các bộ phận khác để đưa ra ý tưởng cho các mẫu thiết kế phần mềm, ứng dụng mới.\n- Xây dựng phần mềm, ứng dụng mới bằng các ngôn ngữ lập trình thích hợp.\n- Phát triển và xây dựng các tính năng mới cho phần mềm.\n- Nâng cấp phần mềm và các hệ thống để đảm bảo tính bảo mật và hiệu quả hơn.\n- Phối hợp với nhóm Service Desk để viết tài liệu hướng dẫn sử dụng.\n- Kiểm tra và bảo trì các chương trình, ứng dụng định kỳ, tiến hành sửa lỗi khi có vấn đề xảy ra.\n- Triển khai và giới thiệu sản phẩm phần mềm tới khách hàng\n\nYour skills and experience\n- Tốt nghiệp từ đại học chuyên ngành công nghệ thông tin, phần mềm....\n- Sử dụng một số ngôn ngữ lập trình:.NET/C#, Java, Python, Web Service\n- Có kiến thức về SQL, MSSQL\n- Lập trình với hệ CSDL: MSSQL, MySQL, Postgres, Oracle\n- Thành thạo HTML, CSS, Bootstrap, Javascript, Jquery (Ưu tiên sử dụng ReactJs)\n- Kinh nghiệm sử dụng GIT như GitHub/GitLab, Docker container\n- Có khả năng phân tích, tổng hợp dữ liệu ở các nguồn dữ liệu khác nhau..\n- Kỹ năng làm việc độc lập, làm việc nhóm tốt.\n- Hoạt bát, siêng năng, trung thực, chịu áp lực công việc.\n- Ưu tiên có kinh nghiệm triển khai các giải pháp phần mềm quản trị doanh nghiệp đặc biệt các doanh nghiệp có yếu tố sản xuất, xây dựng các phần mềm, thiết kế database, big data.\n\nWhy you\'ll love working here\n- Thu nhập 15 - 30 triệu( Gồm Lương + phụ cấp + thưởng.\n- Được tham gia chính sách phát triển nhân sự ưu việt: được cấp quỹ đào tạo hàng năm để chủ động tham gia các khóa học ngoài, được tham gia chương trình đào tạo inhouse. - Bảo hiểm xã hội đóng trên 100% lương.\n- Các chế độ phép năm, lễ tết,... theo đúng 100% quy định của pháp luật lao động\n- Được làm việc trong một môi trường coi trọng người lao động, văn hóa doanh nghiệp rõ nét. - Các chế độ phúc lợi đầy đủ. - Làm việc 5,5 ngày / tuần, nghỉ chiều thứ 7 và ngày chủ nhật.\n- Phụ cấp: Ăn trưa\n- Quyền lợi: Bảo hiểm xã hội, Bảo hiểm full lương, Khám sức khỏe định kỳ, Team building, Du lịch hàng năm, Phụ cấp thâm niên, Thưởng hiệu quả làm việc, Thưởng tháng 13\n- Địa điểm làm việc: Hà Nội: 285A Ngô Gia Tự, Long Biên, Long Biên\n- Thời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 7 (từ 08:00 đến 12:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 285A Ngô Gia Tự, Long Biên, Hà Nội, Long Bien, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(896, 574, 2, 'Middle Blockchain Developers (NodeJS, ReactJS)', 'Chúng tôi đang tìm kiếm 3 Middle - Senior Blockchain Developer tài năng để gia nhập đội ngũ phát triển của HOLA TECH. Vị trí này đóng vai trò quan trọng trong việc xây dựng và phát triển các giải pháp blockchain tiên tiến, góp phần định hình tương lai của công nghệ phân tán. Nếu bạn có kinh nghiệm sâu về smart contract, DeFi, DApps và các nền tảng blockchain hàng đầu, đây là cơ hội tuyệt vời để bạn phát huy năng lực và phát triển sự nghiệp.\n\nYour skills and experience:\n- Có trên 2-3 năm kinh nghiệm làm việc thực tế trong lĩnh vực phát triển blockchain.\n- Kinh nghiệm sâu sắc với việc phát triển Smart Contract, các ứng dụng DeFi và DApp phức tạp.\n- Có kinh nghiệm làm việc tốt trên các nền tảng blockchain phổ biến như Solana và EVM (Ethereum Virtual Machine - bao gồm Ethereum, BSC, Polygon, v.v.).\n- Sở hữu kỹ năng giải quyết vấn đề mạnh mẽ và tư duy hệ thống tốt, có khả năng phân tích và xử lý các vấn đề kỹ thuật phức tạp.\n- Có kinh nghiệm làm việc trong môi trường phát triển phần mềm sử dụng quy trình Agile/Scrum.\n- Thành thạo ít nhất một trong các ngôn ngữ/công nghệ liên quan như Node.js, React.js và có kinh nghiệm làm việc với Docker và thư viện/SDK Web3.\n\nWhy you\'ll love working here:\n- Được hưởng đầy đủ các chế độ phúc lợi theo quy định của pháp luật: Đóng BHXH, BHYT.\n- Lương tháng 13 và các khoản thưởng hấp dẫn dựa trên hiệu quả công việc, thưởng đầu và cuối dự án.\n- Tham gia các hoạt động team building, du lịch, sự kiện công ty thường xuyên.\n- Làm việc trong môi trường trẻ trung, năng động, khuyến khích sáng tạo và phát triển cá nhân.\n- Cơ hội phát triển kỹ năng giao tiếp trực tiếp với khách hàng, mở rộng mạng lưới quan hệ.\n- Được tạo điều kiện để phát triển toàn diện các kỹ năng mềm, kỹ năng quản lý và kỹ năng lãnh đạo thông qua các dự án và hoạt động đào tạo nội bộ/bên ngoài.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa ecolife, 58 Tố Hữu, Nam Từ Liêm, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(897, 202, 2, 'Cloud Engineer Team Leader (M365, Azure)', 'Are you a skilled technical professional with a passion for leadership and cloud technologies? As the Cloud Engineer Team Leader at Dinotronic Vietnam, you’ll play a dual role: providing hands-on technical expertise (up to 60 - 70% of your time) while leading a dynamic team of 5 engineers (30-40%). Here\'s what your role will look like:\n\n- Manage a team of five Cloud Engineers, help them coordinate & follow-up on tasks and check on quality & deadlines\n- Coordinate between Vietnam team and Switzerland headquarters, dispatch task & tickets, maintain proactive communication\n- Lead the DevOps sprint meetings and conduct testing\n- Work on reporting tasks and security requests\n- Provide guidance and technical support to team members to foster skill growth\n- Maintain, improve, and support customer environments using Microsoft 365 and Azure technologies\n- Onboard customers to standardized M365 & Azure environments, manage migrations, conduct proof of concepts (PoC), and suggest solutions together with our international team\n- Handle support incidents, daily operational tasks, enhance the security of our services and work on modern cloud technologies depending on your skills and preferences\n- Optional, if interested: Work on automating our onboarding-tasks and enforcing our standards by using PowerShell scripts and Azure DevOps as well as Power Platform, supporting our vision of a fully-automated managed service provider\n\nWe’re looking for a technical leader who can inspire and empower the team while maintaining hands-on technical expertise. Here’s what we’d love to see:\n\n- A degree in IT (e.g. computer science, information technology)\n- Leadership skills with working experience as a team lead in a similar field\n- Strong communication skills and basic project management skills\n- Solid knowledge of Azure or Microsoft 365 backend like Entra ID, EXO, SPO etc.\n- A very good level of English, a self-driven and innovative mindset, reliable, and a passion for IT\n- Bonus points if you have (optional):\n- Experience in cloud automation (PowerShell, DevOps, or Power Automate)\n- Knowledge of network/firewall administration\n- Interest or experience in security, information & identity protection, AVD/W365, ARM, infrastructure-as-code, Azure Automation, Power Automate, or related fields\n- Microsoft certifications (not a must, but always a plus)\n\nAt Dinotronic, IT isn’t just a job—it’s our passion. We’re a cloud-only managed service provider with a dynamic, international team spanning our Vietnam office and Swiss headquarters. Between both teams we work together on interesting technologies, follow processes according to ITIL and we love what we do.\n\nHere’s why you’ll love being part of our team:\n- Leading a skilled, motivated team that loves IT as much as you do\n- Work with cutting-edge cloud technologies\n- Receive training for the job and enough time for learning—plus support to earn Microsoft certifications\n- Enjoy a positive, respectful working environment in an inspiring team, with flexible conditions, an attractive salary & benefits package\n- Grow your career in exciting fields like M365, security, cloud infrastructure, scripting, leadership or related fields\n\nLooking forward to welcoming you onboard our team soon!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '147-149 Vo Van Tan, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(898, 575, 2, 'Fullstack Developer Senior (NodeJS, ReactJS)', 'We\'re looking for a Full-Stack Developer to join our team with NodeJS & ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc. who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.\n\nYou will:\n- Working with Product Owners to convert business requirements into technical designs.\n- Working and pair programming with other developers to build applications with Node.JS and ReactJS.\n- Design and develop scalable front-end solutions using ReactJS\n- Build and maintain robust back-end systems with NodeJS\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Ensure code quality, security, and performance optimization.\n\nYour skills and experience:\n- Knowledge of responsive design techniques and front-end optimization methods.\n- At least 3 years of experience as a Full-Stack Developer (Node.js & React.js).\n- Strong proficiency in front-end technologies, particularly React.\n- Expertise in back-end development using Node.js.\n- Hands-on experience with Web3 integration.\n- Solid understanding of smart contract development and deployment.\n- Good command of English (both verbal and written).\n- Knowledge of cryptography and blockchain is a plus.\n\nWhy you\'ll love working here:\n- 13th Salary\n- Build World class product(s): We love to solve complex problems and learn new things.\n- Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n- Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n- Enjoy competitive salary, bonus according to work performance\n- Assistance with operational tools and equipment.\n- Health insurance program for employees provided by PVI.\n- Annual health check-up from Medlatec Clinic\n- Participate in social insurance after becoming an official employee\n- Salary review twice a year. It means we are pushing each other to be better everyday.\n- Flexible working hours, freestyle attire\n- Perks You\'ll Enjoy:\n- Working in a young, super talented, and supportive team environment\n- Technical, English certificate bonus\n- Day-off: 12 days/year and Vietnam holidays\n- Happy Hour, Football club, English club, and many exciting activities\n- Company trip/ team building/ Year End Party\n- Free coffee, snacks, and drinks.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '68 Xo Viet Nghe Tinh, Hoa Cuong Nam, Cam Le, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(899, 446, 2, '[Da Nang] Middle Programmer (Java/Kotlin, SQL, Oracle)', 'PASONA VIETNAM is a 100% Japanese-owned company specializing in producing software and providing information technology services for domestic and foreign companies. Due to our business expansion, we need to recruit more Programmers (Developers) with the following job content:\n\nYou will join a project focused on data migration from MySQL to Oracle, playing a key role in designing, developing, and testing tools and scripts to support this process\n\nKey responsibilities include:\n- Develop and maintain backend modules using Java or Kotlin.\n- Design and implement data migration scenarios from MySQL to Oracle.\n- Optimize SQL queries and data structures to ensure high performance during migration.\n- Write Shell Scripts for automation tasks as needed.\n- Collaborate with QA to develop testing tools and validate data post-migration.\n- Analyze technical requirements and contribute to system documentation\n\nWorking hours:\n- Mon - Fri, 8:00 - 17:00\n\nYour skills and experience\nRequirements\n- 3–4 years of experience in software development using Java or Kotlin.\n- Proficient in SQL, with hands-on experience in MySQL and/or Oracle.\n- Strong understanding of large-scale data processing and performance optimization in migration tasks.\n- Experience with tools or frameworks for data migration and validation (custom-built or third-party).\n- Solid teamwork, high responsibility, and proactive working attitude.\n\nPreference\n- Ability to read and understand technical documents in Japanese.\n- Experience writing and using Shell Scripts (bash) for automation tasks.\n\nWhy you\'ll love working here\n- Experience to learn large-scale development project\n- High promotion opportunities and career development opportunities for competent individuals\n- As the team is expending, you may participate as a core member\n- Professional, stable and friendly working environment\n- Compulsory insurance and overtime payment on the TOTAL SALARY under the labor contract\n- Holiday on the occasion of company establishment day annually besides the holidays in accordance with the law\n- Quarterly birthday party, annual health check.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '243 Phan Dang Luu, Khue Trung Ward, Cam Le, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(900, 224, 2, 'Principal Frontend Engineer (ReactJS)', 'Top 3 reasons to join us\n- Hybrid working; Flexible time; Macbook Pro\n- L&D programs; 17 days off \n- 13.7 million B2C users; 140,000+ business customer\n\nJob description\n- Develop and Deliver products with high responsibility, availability, scalability, security, and maintainability.\n- Work with a product manager, a designer, and backend engineers to implement product features.\n- Provide technical direction and validate technical solutions to ensure quality and scalability in React & Next.js development.\n- Resolve any technical issues, risks, and challenges, escalating as necessary and providing solutions.\n- Contribute to create a sophisticated development team, applying Agile/Scrum methodologies to deliver projects successfully.\n- Support the growth of junior to mid-level engineers through hands-on teaching and coaching, thereby maximizing the team\'s output.\n\nYour skills and experience\nMust have\n- 8+ years experience in web development\n- 5+ years for frontend development for React/Typescript\n- Experience with Agile development.\n- Strong understanding of JavaScript fundamentals\n- Strong knowledge of HTML and CSS\n- Experience with frontend testing frameworks (Jest, Mocha, etc…)\n- ​​Experience using, designing, and building GraphQL Web Service APIs\n- Experience in designing system architecture\n- Experience in designing and maintaining UI components (Stotrybook, Visual Regression Test, etc…)\n- Excellent English verbal communication skills\n\nNice to have\n- 1+ years experience with backend development (Golang/ Java/ NodeJS/ Others)\n- Experience with CI/CD (Github workflow, Circle CI) and infrastructure (AWS, Heroku)\n- Container-based development (Docker, docker-compose, Kubernetes) experience\n- Experience with scrum master role.\n- Experience utilizing design systems.\n- Experience in utilizing state management libraries (Redux etc..)\n- Understanding of microfrontend architecture\n\nWhy you\'ll love working here\nCaring Mental & Physical Recreation: \n- Hybrid working\n- Full salary in probation & 13th month salary\n- Social insurance on full salary from probation\n- Premium Health insurance from probation\n- Flexible start 8AM-9AM from Mon-Fri\n- 16 days off annually + 1 Birthday Leave \n- Paternity leave extra 5 days \n- Annual company trip; Quarterly team building activities\n- Club activities\n- Annual health check\n\nCaring Career & Development: \n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- Well-equipped facility: Macbook pro, additional monitor,.. \n- Soft skill workshops\n- Tech seminars\n- Monthly and biannually Recognition Awards\n- Performance review twice/year', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ETown Central Building, 11 Doan Van Bo, Ward 13, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(901, 345, 2, 'Senior NodeJS Developer', 'We are looking for a talented and experienced Node.JS developer to join our team. The ideal candidate will have a strong understanding of SAP CAP (Or other Node.JS Framework like Nest.JS) and SAP UI5 (Or other Frontend Framework like React.JS/Angular/Vue.JS), as well as experience working on SAP BTP Platforms. The developer will be responsible for developing, maintaining, and deploying high-quality web applications.\n\nResponsibilities:\n- Manage the operation and project of NodeJS team\n- Develop and maintain web applications using SAP CAP and SAP UI5 on SAP BTP Platform.\n- Work with a team of developers to deliver high-quality software on time.\n- Troubleshoot and resolve application issues.\n- Work with other teams to ensure that applications meet business requirements.\n- Stay up-to-date on the latest technologies and trends\n\nYour skills and experience:\n- Bachelor\'s degree in computer science or a related field\n- 5+ years of experience in web development\n- Strong understanding of JavaScript, TypeScript, and Node.JS\n- Experience with SAP CAP (Or other Node.JS Framework like Nest.JS)  and SAP UI5 (Or other Frontend Framework like React.JS/Angular/Vue.JS)\n- Experience working on SAP BTP Platforms or other Cloud Platform like AWS, GCP, Microsoft Azure,…\n- Good knowledge of Non-Functional Requirements (Security, Performance, Scalability…). Be able to identify, treat, interpret, and come up with conclusions about the Non-Functional Requirements of a project.\n- Good knowledge of architecture standards and solutions for his/her base technology platform, including reference architectures, and integration models/architectures (Clean Architecture, Micro-services,...).\n- Strong problem-solving skills.\n- Understands and speaks in English freely, fluently, and accurately, and can infer information from spoken or written in more complex situations.\n- Familiar with working in an Agile environment\n\nWhy you\'ll love working here:\n- 15 days of annual leaves\n- Competitive salary (+13-month salary include) \n- Health insurance, social insurance according to the government regulations \n- PVI Healthcare Insurance \n- Have a chance to work in an international, friendly, open environment \n- Annual Travel opportunity', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '324 Le Van Sy, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(902, 366, 2, 'Backend Engineer (Java/Spring) - GSaaS', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea’s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia’s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: \n\nWe are looking for Backend Engineers (Java/Spring) for GSaaS\'s projects.\n\nYour daily task:\n- Responsible for developing and maintaining the server-side components using the Java programming language.\n- Write and maintain technical documentation, including system architecture and API specifications.\n- Take a look at NAVER WORKS services.\n\nYour skills and experience\n\nYour background:\n- 4+ years of work experience on related work.\n- Bachelor\'s degree or above in Computer Science or related field.\n- Good at Java basic skills, experience with multi-threaded programming, IO, JVM garbage collection.\n- Experience with Java performance tuning and find and resolve troubleshoot experience with Spring, Spring MVC, Spring Boot, MyBatis, MySQL, High Availability, High Concurrency Related Technologies.\n- Experience with Linux basic command, independently complete project deployment, troubleshoot.\n- Open-minded, honest and have a positive attitude towards people.\n- Good at communication skills in general and English skills in particular.\n\nIt\'s a big plus if you:\n- Experience with big data projects, Kafka & Hbase.\n\n*Due to the volume of interest and applications we receive, our response time may be slower than usual. We appreciate your patience and understanding as we carefully review each application.\n\nWhy you\'ll love working here\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n- Competitive income package: Performance appraisal every year, incentive bonus...\n- Learning and development opportunities: We provide an annual budget for employees to learn anything related to languages and technologies & monthly budget for self-development plan\n- Protecting and enhancing healthcare plan for you and your family: We provide premium health insurance for you and 2 family members, a health check every year, and a premium gym membership\n- Employee engagement activities: You will be involved in a fun and respectful working environment, we support a monthly budget for team engagement\n- Other benefits: One-off allowance for setting up working from home corner, work dedication bonus', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '4th and 9th Floor, Block B, Viettel Building, 285 CMT8, Ward 12, District 10, Ho Chi Minh city, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(903, 197, 2, 'MLops Engineer', 'We are looking for qualified MLops Engineer for the eKYC project, who will help us build up our digital identity verification products.\n\nYour primary focus will be:\n- Developing and managing the backend system which encapsulates and provides control flow of various ML models.\n- Developing ML models and implementing novel solutions for various problems including fraud detection, face matching, OCR in computer vision.\n- Act as interfaces between product team, engineering team and data science team to ensure smooth integration of ML solutions.\n- Integrate ML models and ensure consistency in model interfaces and interaction as per product requirements.\n- Monitor and optimize system performance and resource consumption.\n- Manage development servers and environments.\n- Communicate with the product team, infrastructure team, engineering team and data science team to ensure consistency in requirement, development, integration, and deployment.\n- Optimize and deploy "tiny" ML solutions on limited computation power devices such as mobile devices and web platforms.\n- Having an opportunity to learn from production across many nations.\n- This position reports to the Lead data scientist.\n\n(Optional) Have an opportunity to work under supervision of an experienced data scientist to:\n- Build eKYC components (object classification/detection, ocr, fraud detection, abnormal detection), using state-of-the-art methods\n- Develop ML models and provide solutions for acquisition, verification, validation, and fraud detection of user data\n\nYour skills and experience:\n- BS or MS in Computer Science or related fields\n- Having 1-3 years of experience in Data science and MLOps\n- Must be proficient in software design and software development.\n- Must be proficient in Python, scripting language. Experience with other programming languages (C++, Java, Javascript ...) is a plus\n- Must be proficient in Linux system, version control system (Git), virtualization and SW packaging tool (docker)\n- Great communication skills\n\nDesired Skills:\n- Experience with ML framework: Tensorflow, Pytorch, Mxnet, ONNX.\n- Experience with managing data science and computer vision toolkit, such as JupyterHub, OpenCV... is a plus\n- Experience with working with databases and query language is a plus.\n- Familiar with MLOPs concept and toolkit is a plus\n- Basic understanding of machine learning techniques and algorithms\n- BS/MS in Computer Science with focus on machine learning is a plus\n\nWhy you\'ll love working here:\n- Competitive compensation package, including 13th-month salary and performance bonuses\n- Comprehensive health care coverage for you and your dependents\n- Generous leave policies, including annual leave, sick leave, and flexible work hours\n- Convenient central district 1 office location, next to a future metro station\n- Onsite lunch with multiple options, including vegetarian\n- Grab for work allowance and fully equipped workstations\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Havana Tower - 132 Ham Nghi, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(904, 327, 2, 'Database Architect', 'We are looking for an experienced Database Expert to join our team and take full ownership of all database-related tasks for upcoming projects. The ideal candidate will be responsible for designing, managing, optimizing, and maintaining databases that support scalable, secure, and high-performance applications. You will work closely with a dynamic team, including Korean members, so strong communication skills and cross-cultural collaboration experience are important.\n\nKey Responsibilities\n\nDesign, develop, and maintain database schemas and architectures for new and existing systems.\nEnsure data integrity, security, and availability across multiple projects.\nOptimize SQL queries and improve database performance.\nCollaborate with frontend/backend developers to define data models and ensure smooth data integration.\nSet up database backup and recovery procedures.\nMonitor database systems and resolve any performance or security issues.\nPrepare documentation and guidelines for database usage and access.\nSupport database migration and versioning processes.\n\nYour skills and experience\n\nProven 7-10 years of experience as a Database Administrator, Database Engineer, or similar role.\nStrong knowledge of relational databases such as PostgreSQL, MySQL, or SQL Server.\nExperience with NoSQL databases (e.g., MongoDB, Redis) is a plus.\nSolid understanding of database design, normalization, indexing, and query optimization.\nFamiliarity with cloud-based database solutions (e.g., AWS RDS, Google Cloud SQL) is an advantage.\nExperience with tools like pgAdmin, DBeaver, or similar.\nGood problem-solving skills and attention to detail.\nAbility to work independently and as part of a multicultural team.\nGood at English (verbal and written).\n\nWhy you\'ll love working here\n\n13th-month salary, annual performance review\nLaptop upon joining.\nYearly company trip.\nModern facility, flexible and open environment.\nOpportunity for business trips to other countries.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cong Hoa, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(905, 410, 2, 'Backend Developer (Java/ Spring/ NodeJS/ Golang)', 'Job description\n- Phát triển và duy trì hệ thống backend cho các sản phẩm bất động sản, bản đồ, ứng dụng chat và đăng tin.\n- Đảm bảo hiệu suất cao, tiết kiệm tài nguyên.\n- Xây dựng hệ thống backend theo kiến trúc microservice.\n- Sẵn sàng học hỏi và thay đổi các công nghệ mới.\n- Đề xuất các giải pháp kỹ thuật nhằm nâng cao hiệu quả hệ thống.\n\nYour skills and experience\n- Biết và đã dùng các công cụ AI như ChatGPT.\n- Tối thiểu 1 năm kinh nghiệm và thành thạo một trong các ngôn ngữ: Java (Spring Boot), Node.js (NestJS), Golang (Gin/Fiber).\n- Có kinh nghiệm làm việc với cơ sở dữ liệu quan hệ (PostgreSQL) và NoSQL (MongoDB).\n- Am hiểu và có kinh nghiệm với JWT, OAuth, Firebase.\n- Kinh nghiệm với Docker, Redis, Kafka, RabbitMQ là lợi thế.\n- Kỹ năng làm việc nhóm tốt, tư duy logic và giải quyết vấn đề nhanh chóng.\n\nWhy you\'ll love working here\n1. Mức lương cứng 13-18 triệu/tháng tùy năng lực khi phỏng vấn\n  - Lưu ý: Mức lương có thể điều chỉnh dựa trên năng lực thực tế, đặc biệt là với ứng viên có kinh nghiệm làm Microservices, DevelOps, AWS, CI/CD (Backend) hoặc React Native với biết ngôn ngữ native (Java, ObjectiveC, swift) để tăng hiệu năng.\n  - Nếu ứng viên có thể kiêm nhiệm Fullstack (Backend+ Node.js + React Native), mức lương có thể tăng 10 - 20% so với mức trên.\n2. Thưởng hiệu suất (Performance Bonus): Hoàn thành công việc trước deadline thưởng 5-10% lương cứng/dự án.\n  - Lưu ý: Nếu ứng viên chủ động đề xuất giải pháp tối ưu code, hệ thống hoặc UI/UX, công ty sẽ có thưởng đặc biệt tùy vào mức độ ảnh hưởng.\n  - Thưởng sẽ đánh giá dựa trên code review, performance tracking và phản hồi từ team.\n3. Thưởng doanh thu & kết quả kinh doanh.\n  - Nếu công ty đạt hoặc vượt doanh thu kỳ vọng, Backend & React Native Developer sẽ nhận được thưởng theo doanh thu.\n  - Nếu ứng viên góp phần vào tăng trưởng sản phẩm (cải thiện tốc độ backend, giảm chi phí server, tối ưu UI/UX khiến user tăng) sẽ có thưởng theo quý, năm.\n4. Phụ cấp & Phúc lợi bổ sung.\n  - Khám sức khỏe định kỳ, BHXH đầy đủ.\n  - Du lịch hàng năm cùng công ty.\n5. Thời gian và điều kiện làm việc.\n  - Thời gian làm việc: Thứ 2 đến thứ 7 hàng tuần, từ 8h đến 17h, nghỉ trưa từ 12h-13h30, nghỉ lễ tết theo nhà nước trừ khi trong giai đoạn chạy dự án.\n  - Điều kiện làm việc: Làm việc tại văn phòng hiện đại, trang thiết bị đầy đủ (máy tính bàn, máy chiếu…).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '182 Phường Lê Lợi, Son Tay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(906, 576, 2, 'C++ Developer', 'As a C++ Developer, you will be responsible for:\n- Analyzing requirements and designing technical solutions.\n- Writing technical specifications and system architecture documents based on input from the PM or customer.\n- Developing robust and maintainable C++ code for various platforms.\n- Performing unit tests and debugging to ensure high code quality.\n- Investigating issues and proposing effective solutions.\n- Collaborating with team members to continuously improve development processes.\n- Driving technical innovation and process improvement within the team.\n\nYour skills and experience\nMust-have:\n- Bachelor’s degree in Computer Science, Computer Engineering, Electrical Engineering, or a related technical field.\n- At least 1 year of experience in C++ application development.\n- Strong knowledge of data structures, algorithms, design patterns, and software engineering principles.\n- Experience with multi-threaded and multi-tasking software development.\n- Familiarity with the full software development life cycle (SDLC).\n- Working knowledge of version control tools such as Git or SVN.\n- Good communication, teamwork, and time management skills.\n- Ability to read and comprehend technical documentation in English.\n- Willingness to continuously learn new technologies and improve skillsets.\n\nNice-to-have / is a plus:\n- Experience in cross-platform development on both Windows and Linux is a plus.\n- Familiarity with embedded systems, hardware programming, and robot/device control is a plus.\n- Experience with Jenkins and CI/CD processes is a plus.\n- Experience with driver development, EtherCAT communication, or semiconductor software is a strong advantage.\n\nWhy you\'ll love working here\n- High salaries for high performance.\n- 100% salary during probation.\n- Salary Review: 2 times/ year, 13th month salary, project bonus.\n- Professional, dynamic, youthful working environment.\n- Interesting extra-curricular activities and other welfare accordance of the company. Company trip and team building parties.\n- Opportunity to join training course at Japan.\n- Work off on Saturday and Sunday by weekly, birthday leave,...\n- Parking allowance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Block B, Waseco Building, 10 Pho Quang Street, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(907, 577, 2, 'Android Developer (Middle - Senior | New Headcounts)', 'JOB PURPOSE/MISSION:\nThe Android developer participates in projects team to deliver software for android payment terminals. Working with other team members, he defines and implements modules, supports integration in final products, and helps in analysis and resolution of technical issues.\n\nReporting to: Tech Lead\n\nKEY RESPONSIBILITIES:\n- Understand projects’ goals, studying business domain and technical areas as needed\n- Participate in team activities to establish designs and plans\n- Deliver quality implementations of features\n- Help maintain common processes and tools\n\nKey Performance Objectives/Indicators:\n- Consistently delivering according to commitments\n- Technical deliverables have good quality (as reported by Tech Lead)\n- Demonstrated understanding of business requirements (Payment, EMV, security, …) is plus point\n\nSKILLS/COMPETENCY SPECIFICATION\nCompetency/Skill Requirements:\n- Practical experience with software development on Android (patterns, tools)\n- Have experience in requirement analysis and design\n- Experience in Kotlin/Coroutine or Java\n- Experience in synchronization processing\n- Experience in problem solving\n\nBehaviour skills:\n- Team player, willing to share, learn and guide other members\n- Invest in improving own skills (domain, practices, tool, …)\n- Open-minded and good teamwork\n- Proactive working attitude and high responsibility\n\nLanguages:\n- Able to communicate in English\n\nEducation Qualifications / Experience Requirements:\n- Middle: 2-5 years of experience\n- Senior: >5 years of experience\n\nWhy you\'ll love working here:\n- Work life balance, no OT, 15 days off\n- Chance to go onsite/other countries for training\n\nAttractive benefits:\n- Great salary package, annual performance review\n- Performance bonus\n- Full salary in probation\n- Social insurance on full salary from probation\n- Premium Health insurance covering for employees, lawful spouse, and unlimited number of children from probation\n- 15 days off annually, paid sick leaves, annual Heath Check-up\n- Working from Monday – Friday, from 9AM to 6PM, no OT\n- Annual company trip, quarterly team building activities, weekly Happy Hour\n- English communication skill training\n- Equipment: Laptop, monitor\n- Free coffee and snack', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '21 Duy Tân, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(908, 578, 2, 'Network Security', '1. Trách nhiệm:\na, Triển khai, vận hành các giải pháp Network, Endpoint Security\n- Chịu trách nhiệm đảm bảo an toàn thông tin mức network, endpoint trên toàn Công ty, bao gồm hệ thống tại Data Center và hệ thống mạng người dùng văn phòng, các hệ thống Wifi nội bộ, Wifi trải nghiệm, Wifi khách hàng\n- Triển khai các giải pháp an toàn thông tin\n- Network security\n- Endpoint security\n- VPN\n- Các giải pháp Access Control\n- Các giải pháp xác thực\n- Quản trị vận hành các hệ thống an toàn thông tin bao gồm các công việc vận hành, nâng cấp, sao lưu cấu hình, phục hồi, vá các lỗ hổng bảo mật, tối ưu hoạt động, xây dựng các quy trình vận hành hệ thống và hướng dẫn thực thi trên các hệ thống\n- Network security (Firewall, IDS/IPS/ NAC)\n- Endpoint security (AV, EPP, EDR)\n- Data & Database security (DBF, DAM/FAM, …)\n- VPN\n- Các giải pháp an toàn thông tin khác\n- Quản lý kết nối và truy cập mức hệ thống/ứng dụng và người dùng (chính sách kết nối, truy cập hệ thống, CSDL, Internet, …) trên các hệ thống Network security (Firewall, NAC)\n- Quản lý cấp phát phân quyền truy cập từ xa (remote access)\n- Cập nhật, khai báo các chính sách theo Quy chế bảo mật thông tin và các chính sách, quy định quản lý truy cập khác\n- Thu thập và báo cáo số liệu bảo mật\n\nb, Triển khai, vận hành các giải pháp App Sec, DevSecOps, Cloud Sec\n- Triển khai các hệ thống phục vụ quản lý an toàn thông tin nhóm Application security\n- Waf - tường lửa ứng dụng\n- Phòng chống DdoS\n- Quản lý chứng thư và các nghiệp vụ ký số\n- Hạ tầng HSM, các giải pháp quản lý khóa mã hóa \n- Giải pháp thu thập log tập trung, SIEM\n- Giải pháp phòng chống gian lận\n- Các giải pháp phục vụ DevSecOps\n- Các giải pháp Cloud computing secuirty\n- Xây dựng phương án thu thập dữ liệu, tổng hợp và hiển thị các dashboard giám sát theo yêu cầu từ nhóm SOC và các nhóm IT vận hành, IT system, DEV cũng như các yêu cầu khác trên công nghệ thu thập log tập trung và SIEM\n- Quản trị, vận hành các hệ thống an toàn thông tin bao gồm các công việc vận hành, nâng cấp, sao lưu cấu hình, phục hồi, vá các lỗ hổng bảo mật, tối ưu hoạt động, xây dựng các quy trình vận hành hệ thống và hướng dẫn thực thi trên các hệ thống an toàn thông tin nhóm Application Security ở mục (i)\n- Xây dựng profile các loại tấn công mạng và tối ưu các giải pháp WAF, phòng chống DdoS dựa trên traffic thực tế của từng nhóm ứng dụng và từng loại tấn công mạng đảm bảo khai thác tối đa chức năng phòng chống tấn công của giải pháp\n- Phối hợp điều tra các sự cố tấn công mạng, thâm nhập mạng trên các hệ thống an toàn thông tin quản lý (tương đương xử lý lớp 2)\n\nc, Triển khai, vận hành các giải pháp Data Security, IAM\n- Triển khai các giải pháp an toàn thông tin bảo vệ dữ liệu\n- File & Database Activity Monitoring\n- File & Database Encryption & Tokenization\n- IAM\n- DLP\n- DRM/IRM\n- Quản trị vận hành các hệ thống an toàn thông tin bao gồm các công việc vận hành, nâng cấp, sao lưu cấu hình, phục hồi, vá các lỗ hổng bảo mật, tối ưu hoạt động, xây dựng các quy trình vận hành hệ thống và hướng dẫn thực thi trên các hệ thống\n- Data & Database security (DBF, DAM/FAM, …)\n- DLP\n- DRM/IRM\n- IAM\n- Cập nhật, khai báo các chính sách DLP\n- Cập nhật, khai báo các chính sách quản lý truy cập, phân quyền dữ liệu DRM/IRM\n- Quản lý truy cập, phân quyền các hệ thống Data & Database Security\n- Quản lý cấp phát tài khoản, truy cập, phân quyền trên các hệ thống nghiệp vụ\n- Quản lý cấp phát tài khoản, truy cập, phân quyền trên các hệ thống máy chủ và hạ tầng CNTT\n- Quản lý định danh và phân quyền các tài khoản đặc quyền\n\nd, Giải pháp an toàn thông tin:\n- Nghiên cứu các xu hướng trong lĩnh vực Fintech như eWallet, P2P lending, Personal Loan, ... và rủi ro về an ninh mạng đi cùng\n- Nghiên cứu các giải pháp an toàn thông tin, thử nghiệm và đưa ra kiến trúc đảm bảo an toàn thông tin cho các công nghệ mới như Blockchain, AI, Microservices, Cloud Computing, SDN, ..\n- Nghiên cứu kiến trúc công nghệ an toàn thông tin, giải pháp an toàn thông tin cho các xu thế chuyển dịch như DevSecOps, Cloud Computing\n- Nghiên cứu, thử nghiệm, đánh giá các giải pháp an toàn thông tin nhằm nâng cao tính bảo mật thông tin mức network/system (TACACS, captive portal, wireless security, honeypot, quản lý bản vá, …)\n\n\n2. Your skills and experience\n- Tốt nghiệp đại học trở lên các chuyên ngành CNTT, ATTT, Toán máy tính hoặc các chuyên ngành kỹ thuật phù hợp.\n- Ưu tiên ứng viên có chứng chỉ CEH, Security +, PCNSE/CCSP/CCSE, CCNP-Security, JNCIS, ISO27000, v.v.)\n- Tối thiểu 3 năm kinh nghiệm làm việc CNTT, ít nhất 2 năm trong vai trò Quản trị viên bảo mật.\n- Có kinh nghiệm làm việc trên các nền tàng cloud như AWS, Azure là một lợi thế.\n- Có kinh nghiệm thực tế đối với các mục mô tả trong nhiệm vụ và trách nhiệm.\n- Kỹ năng lập và quản lý kế hoạch, kỹ năng quản trị dự án, kỹ năng giải quyết vấn đề.\n\n3. Why you\'ll love working here\n- Môi trường chuyên nghiệp, năng động, luôn cập nhật ứng dụng kỹ thuật mới cho vận hành\n- Đồng nghiệp giàu chuyên môn, thân thiện, gắn kết, hỗ trợ\n- Cơ hội không giới hạn dành cho nhân viên tài năng\n- Chế độ cạnh tranh, hình thức đa dạng, thu hút gắn kết\n- Đào tạo bài bản, chuyên nghiệp, chú trọng phát triển cá nhân\n- Công ty có nhiều hoạt động thể hiện trách nhiệm với cộng đồng\n\nChế độ:\n- Lương cạnh tranh\n- Thưởng cuối năm hấp dẫn\n- Review lương hàng năm\n- Phòng gym và HLV miễn phí\n- Thưởng ngày lễ tết', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '65 Cảm Hội, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(909, 579, 2, 'Senior iOS Developer (Swift)', 'We are looking for talented Senior Mobile Developers (iOS) who strive to solve the hard problems, take pride in delivering world-class products and are strong team players.  \n\n- Design and build advanced applications for the iOS platform  \n- Collaborate with cross-functional teams to define, design, and ship new features  \n- Unit-test code for robustness, including edge cases, usability, and general reliability  \n- Work on bug fixing and improving application performance  \n- Continuously discover, evaluate, and implement new technologies to maximize development efficiency  \n- Adapt and sequentially improve the interface following multiple beta tests  \n\nYour skills and experience:  \n- 3+ year experience developing native iOS app with Swift  \n- Proficient with SwiftUI and Combine  \n- Strong proficiency in iOS with Design Patterns and Architecture  \n- Experience with 3rd party integrations - Google Firebase and other Google service  \n- Ability to handle all aspects of developing a feature-set independently as well as integrate it into a greater project  \n- Deliver product in time and high quality clean code  \n- Experience of web development with API-feed data  \n- Experience with Multi- Threading with Grand Central Dispatch, NSOperation, Async/Await  \n- Proven successfully at least 2 mobile apps that is developed with selected skillset  \n- Optimize application performance, battery usage, and memory footprint.\n\nNICE TO HAVE:  \n- A good knowledge in Core -ML, VisionKit  \n- Experience with on-device AI features like image classification, NLP, or recommendation systems.  \n- Experience with integrating AI/ML models using CoreML, CreateML, or third-party frameworks (e.g. TensorFlow Lite, PyTorch Mobile).  \n- A good knowledge in Prompt Engineering  \n- Published apps on the App Store.  \n- A good knowledge of in UX/UI.\n\nWhy you\'ll love working here:  \n\n- Salary:  \n  - 100% salary during probation  \n  - 13th-month salary  \n  - Performance bonus  \n  - Salary review at least one time per year based on employee\'s performance and contribution  \n- Health & Insurance:  \n  - Social Health Unemployment Insurance  \n  - Premium health insurance  \n  - Annual health check-ups  \n- Annual leave: 12-14 days  \n- Working environment:  \n  - MacBook Pro is provided.  \n  - Friendly and fun/ Coffee, tea, snack bar everyday/ Company trip, team building, monthly party, etc.  \n  - Outing/team-building activities (company trip, soccer sport, running club, etc.);  \n  - Work with experienced & strong team;  \n  - Friendly, dynamic & flexible working environments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sarica No. 6 D9 Street, An Loi Dong, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(910, 580, 2, 'Ruby on Rails Developer (MVC, SQL)', '1. Giới thiệu công ty \nBewell Pharma sắp ra mắt, hướng tới mục tiêu trở thành một trong những hệ thống bán lẻ và sỉ dược phẩm hàng đầu tại Việt Nam. Chúng tôi đang trong quá trình phát triển mạnh mẽ với hệ thống E-commerce (bao gồm website bán hàng online và ứng dụng di động) cũng như hệ thống ERP để tối ưu hóa vận hành. Hiện tại, chúng tôi đang tìm kiếm Ruby on Rails Developer (Chuyên viên phát triển phần mềm) nhiệt huyết, có kinh nghiệm để tham gia vào đội ngũ.\n\n2. Trách nhiệm công việc \n- Tham gia phát triển và tối ưu hóa hệ thống E-commerce, bao gồm website và API phục vụ hàng ngàn người dùng. \n- Thiết kế và triển khai các tính năng mới đáp ứng yêu cầu kinh doanh, đảm bảo hiệu suất và khả năng mở rộng. \n- Viết mã rõ ràng, dễ đọc và tuân thủ các tiêu chuẩn phát triển phần mềm. \n- Phối hợp với các thành viên trong nhóm để review code, kiểm thử và cải tiến chất lượng sản phẩm. \n- Hỗ trợ xử lý lỗi và sự cố phát sinh trên môi trường production. \n- Chủ động đề xuất giải pháp kỹ thuật để nâng cao trải nghiệm người dùng và hiệu quả vận hành hệ thống.\n\nYour skills and experience\n- Bắt buộc: \n- Từ 2 năm kinh nghiệm làm việc với Ruby on Rails. \n- Có kiến thức vững về lập trình hướng đối tượng và mô hình MVC. \n- Thành thạo làm việc với cơ sở dữ liệu quan hệ như MySQL hoặc PostgreSQL. \n- Có kinh nghiệm tích hợp API bên thứ ba và xử lý luồng dữ liệu trong hệ thống E-commerce. \n- Biết cách viết mã sạch, có thể tái sử dụng và dễ bảo trì. \n- Có hiểu biết cơ bản về kiểm thử tự động (unit test, integration test). \n- Có tư duy logic tốt và tinh thần chủ động học hỏi. \n- Quen thuộc với Git và quy trình làm việc nhóm qua pull request. \n\n- Ưu tiên: \n- Kinh nghiệm với Redis, Sidekiq hoặc các job queue khác. \n- Quen thuộc với CI/CD, Docker hoặc có kinh nghiệm triển khai lên môi trường staging/production. \n- Có kinh nghiệm làm việc trong hệ thống E-commerce thực tế.\n\nWhy you\'ll love working here\n- Mức lương hấp dẫn \n- Thưởng hàng quý theo doanh thu. \n- Lương tháng 13. \n- Bảo hiểm đầy đủ theo quy định. \n- Lộ trình thăng tiến rõ ràng, có cơ hội trở thành core team member. \n- Cơ hội làm việc với các dự án thách thức và sáng tạo. \n- Môi trường làm việc thân thiện, sẵn sàng hỗ trợ lẫn nhau.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '144 Đồng Văn Cống, Thạnh Mỹ Lợi, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(911, 532, 2, 'Technical Project Manager', 'About Sunbytes\nSunbytes is a leading Tech & Talent Solutions company known for innovative and scalable solutions. We focus on achieving goals for our partners and team members, delivering high-quality products and services, and fostering a supportive, challenging work environment. Our diverse team shares a common purpose, making Sunbytes a great place to work.\n\nWe offer comprehensive long-term partnerships, including recruitment, dedicated worldwide talents, and custom software development tailored to meet client needs.\n\nJoin Us Are you a seasoned project management professional with a strong technical background and a passion for Agile methodologies? Sunbytes seeks a dynamic Senior Technical Project Manager to join our team and ensure the success of software development projects in the IoT industry by effectively leading teams, aligning business objectives, and maintaining seamless client communication. This role offers an opportunity to work on impactful solutions that drive innovation and efficiency.\n\nAbout the Role\nSunbytes is looking for a Senior Technical Project Manager to take on a strong leadership role in guiding both project execution and team development. This is a full-time position requiring a solid background in software development, Agile & Scrum processes, and client-facing communication.\n\nAs the Senior Technical Project Manager, you will lead Agile software development projects, ensuring smooth execution, aligning teams with business objectives, and maintaining seamless client communication. In addition to overseeing project delivery, you will play a key leadership role in the local development team, fostering a high-performance culture, mentoring team members, and ensuring alignment with the company’s vision and values.\n\nThis role requires a proactive leader who can optimize workflows, drive innovation, and empower the team, ensuring both project success and a strong connection between the client and the development team.\n\nJob Requirements\n- Inspire and align the team with the client’s vision, mission, and values by ensuring clear communication of business objectives, fostering ownership, and driving a shared sense of purpose.\n- Lead Agile & Scrum processes by facilitating sprints, tracking tasks in Jira, and ensuring smooth execution while aligning development efforts with business goals.\n- Provide technical leadership by understanding and addressing development challenges, ensuring best practices, and guiding the team in making informed technical decisions.\n- Act as the primary liaison between the development team and stakeholders by translating technical discussions into clear, actionable insights for the client while managing expectations and priorities.\n- Identify and mitigate risks early by proactively solving potential bottlenecks, communicating trade-offs to stakeholders, and ensuring project continuity.\n- Continuously improve processes by refining Agile workflows, fostering a collaborative team culture, and encouraging best practices.\n\nYour skills and experience\nTechnical skills:\n- At least 5 years of experience in a similar position, successfully leading Agile software teams.\n- Proven ability to optimize development workflows, drive technical decision-making, and enhance team productivity.\n- Expertise in Agile & Scrum methodologies, including sprint planning, backlog management, and Jira tracking.\n- Strong technical understanding of how to evaluate and communicate development challenges and solutions effectively.\n- Experience in risk and issue management, with the ability to proactively identify bottlenecks and implement solutions.\n\nSoft skills:\n- Align with the client’s vision, mission, and values by fostering ownership and a shared sense of purpose within the team.\n- Strong leadership skills to create a motivated, high-performing development team.\n- Excellent communication skills to align team efforts with business goals and facilitate clear discussions with stakeholders.\n- Foster a collaborative and innovative team culture, ensuring continuous learning and process improvement.\n- Problem-solving mindset to anticipate challenges, provide actionable insights, and manage stakeholder expectations effectively.\n\nWhy you\'ll love working here\nWhat can you expect from us\nWe offer you a young, challenging and friendly environment with a free dress code, a competitive salary, full health benefits and social insurance and individual career path planning.\nFurthermore we offer\n- 16 days annual leave (18 after 2 years of employment);\n- 3 sick days per year;\n- 4 creative days per year where you can explore new techniques and possibilities;\n- A yearly company trip;\n- 13th month salary;\n- Premium Health Insurance 24/7.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '400/8A Ung Văn Khiêm, Ward 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(912, 217, 2, 'Senior Product Designer (AI/UX, Enterprise SaaS)', 'About Us\nReforged Labs is a YC-backed, Sandhill Road funded AI startup revolutionizing how the world\'s top mobile gaming studios market themselves to hundreds of millions of players. We\'re building cutting-edge AI technology that powers sophisticated ad analysis and generation pipelines for elite global gaming companies.\nWe don\'t follow trend; we set them. Our engineering team builds solutions that rival the best Silicon Valley has to offer, creating technology that generates millions of dollars in value for our customers.\n\nThe Role \nWe\'re seeking an exceptional Senior Product Designer to join our fast-growing team in Ho Chi Minh City. This is not a role for the average designer; we\'re looking exclusively for extraordinary talent who can compete with the best designers globally.\n\nYou\'ll spearhead the user experience design of our AI-driven platforms, crafting intuitive interfaces that make powerful technology accessible and delightful to use. Your designs will directly impact how hundreds of millions of players discover and experience games through our AI-powered marketing tools.\n\nCore Responsibilities \n● Design elegant, intuitive interfaces for our AI copilot tools that seamlessly blend sophistication with usability\n● Create comprehensive user journeys and information architecture for complex AI-powered workflows\n● Develop and maintain a cohesive design system that ensures consistency across our product suite\n● Translate product requirements into thoughtful user experiences that make AI capabilities accessible\n● Collaborate closely with product and engineering teams to bridge user needs with technical possibilities\n● Gather and incorporate user feedback through thoughtful iteration cycles\n● Drive design decisions that shape our platform\'s user experience and future direction\n● Set the standard for design excellence and best practices across the organization\n\nYour skills and experience\nRequired Experience \n● 5+ years of product design experience with a focus on complex digital products\n● Strong portfolio demonstrating exceptional design work that has reached millions of users\n● Experience designing interfaces for AI-powered products or features\n● Expert knowledge of design tools (Figma, Sketch, etc.) and prototyping techniques\n● Track record of designing B2B SaaS applications and consumer-facing products\n● Deep understanding of how humans interact with AI systems and how to design for these interactions\n● Experience with user research, testing methodologies, and data-informed design decisions ● Professional English communication skills (verbal and written)\n\nEssential Qualities \n● Creative problem-solver who can make complex technologies accessible through intuitive design\n● Strategic thinker who considers both short-term usability and long-term product vision\n● Self-starter mentality with strong ownership of the design process from concept to implementation\n● Excellence in time management and ability to meet ambitious deadlines\n● Clear communication skills, especially around design decisions and trade-offs\n● Collaborative mindset with the ability to incorporate feedback while maintaining design integrity\n● Passion for creating exceptional user experiences that drive product adoption and engagement\n● Comfort working in a fast-paced startup environment\n\nInterview Process \n1. Initial Portfolio Review & Discussion (60 mins)\n○ Portfolio presentation and walkthrough\n○ Design thinking and problem-solving discussion\n○ High-level experience overview\n2. Design Challenge (1 week to complete)\n○ Real-world problem related to our domain\n○ Opportunity to demonstrate your skills comprehensively\n3. Design Review & Collaboration Exercise (90 mins) ○ Deep dive into your design challenge solution\n○ Collaborative design exercise with our team\n○ Discussion on design systems and scalability\n4. Final Leadership Conversation (60 mins)\n○ Vision alignment with founders\n○ Culture and team fit discussion\n○ Two-way Q&A about growth opportunities\n\nWe aim to complete the entire process within 2-3 weeks.\n\nNote: This role is designed for elite design talent. If you\'re not consistently recognized as among the most capable designers in your current organization, this position is likely not a good fit. We\'re looking for candidates who can demonstrate outstanding design abilities and deliver outsized impact.\n\nIf you believe you\'re among the most skilled product designers and are excited about shaping cutting-edge AI interfaces, we want to talk to you.\n\nWhy You\'ll Love Working Here\nIndustry-leading compensation package\nWork on technology that is genuinely world-class and cutting-edge, not just by local standards\nBuild products that compete globally and set new industry standards\nCompensation package targeting top-tier engineers (significantly above local market rates)\nOpportunity to be an early engineer at a rapidly growing, well-funded AI startup\nDirect impact on products used by major gaming studios reaching hundreds of millions of users\nPotential for international recognition and career advancement opportunities\nChallenging, fast-paced environment that will accelerate your professional growth\nCollaborative culture where your ideas matter and technical excellence is valued.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 , 2 Thi Sách, Phường Bến Nghé, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(913, 475, 2, 'Middle/Senior Python Developer (Machine Learning)', 'About Us  In 2004, (called MyRecipes back then) rocked the food service industry with an app which enabled users to do things they previously could only dream of. We gave New Zealand\'s professional chefs the power to cost any recipe in just minutes, as well as know the nutrition - something which was prone to error, was difficult, and used to take a long time.  While we made headlines, and were in fact SAAS pioneers, we didn\'t think much of this. For us, it was just the beginning of a mission which had only just begun.  Fast forward 20 years, (gee! where did that go?!) with the support of our users who love our app, we\'re on a new mission to take this to the world using cutting edge tech to do things even smarter, easier and faster.  We’re looking for a strong python backend end developer with some experience in machine learning and excellent communication skills to collaborate closely with our team, ensuring solutions are well-aligned with real-world needs.  You should bring sharp analytical and problem-solving abilities, along with experience working in agile teams and a solid understanding of agile principles. Your ability to navigate technical challenges and contribute to a collaborative, fast-paced environment will be key to your success in this role. Education: Bachelor’s or Master’s degree in Computer Science, Mathematics, or related fields Responsibilities: Design, build, and maintain scalable backend systems and APIs Develop robust infrastructure to support data processing and integration of ML models Implement and manage deployment pipelines for backend services and machine learning workflows Build automated testing frameworks for backend components and ML pipelines Ensure system performance, reliability, and scalability in production environments Monitor and debug backend and ML systems to ensure high availability and security Collaborate with frontend, DevOps, and data teams to deliver integrated, production-ready solutions Optimize backend workflows and ML pipelines for efficiency, maintainability, and continuous delivery  Your skills and experience Must have: 3+ years python experience 1+ years machine learning experience. Experience with libraries like Scikit-Learn Experience with backend API’s Experience with relational or non-relational databases. Eg Mongo and Postgres Experience with FastAPI or similar Might have: General knowledge in python libraries related to scraping, data processing. Experience with Dev-ops (CI/CD) Experience with pipelines Basic English communication skills Qualifications Bachelor’s degree in Computer Science, Information Technology, or related field. Why you\'ll love working here Our current team of 11 are based in Vietnam and the Philippines and are all incredibly passionate about what we do. We\'re very excited about what we are building and cant wait to release our new version. We follow agile methodology and love working together as a team.  Our team values and team culture revolve around:  Simplification over complication. Removing and decrypting jargon.  Efficiency and smart thinking over hard work.  Work-life balance. We all value local working hours and respect time away from work.  We celebrate the wins. And often.  Teamwork. Collaboration fuels our success. We all win together.  Innovation. We seek new ways to solve problems.  Delight. Usability is good, but delight is better. We aim to surprise and exceed expectations.  Communication. Above all else, clear communication keeps us aligned.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hoang Dao Thuy, Trung Hoa Ward, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(914, 287, 2, 'Technical Project Manager (Agile, Scrum, APIs, Cloud)', 'We are seeking a highly motivated Technical Project Manager to lead and manage complex technical projects, coordinate cross-functional teams, and ensure timely delivery of high-quality solutions. The ideal candidate has a strong technical background, excellent communication skills, and proven experience in managing software development or IT projects.\n\nResponsibilities: \n- Define project scope, objectives, and deliverables in collaboration with stakeholders. \n- Develop detailed project plans, including schedules, resource allocation, and risk management. \n- Coordinate and communicate with development, QA, design, and other teams to ensure smooth project execution. \n- Monitor project progress, identify potential risks and delays, and implement mitigation strategies. \n- Ensure projects are delivered on time, within scope, and within budget. \n- Facilitate sprint planning, stand-ups, and retrospectives in agile environments. \n- Manage stakeholder expectations and provide regular status updates. \n- Oversee technical documentation and ensure quality standards are maintained. \n- Continuously improve project management processes and methodologies.\n\nYour skills and experience\nRequirements: \n- Bachelor\'s degree in Computer Science, Information Technology, or related field. \n- Proven experience as a Technical Project Manager or in a similar role. \n- Strong technical background with an understanding of software development lifecycle, APIs, cloud services, or relevant technologies. \n- Experience with Agile/Scrum methodologies. \n- Excellent communication, leadership, and problem-solving skills. \n- Ability to manage multiple projects simultaneously. \n- Proficiency with project management tools (e.g., Jira, Trello, MS Project).\n\nPreferred Qualifications: \n- PMP, Scrum Master, or equivalent certification. \n- Experience with specific technologies relevant to our industry (e.g., AWS, Azure, Docker). \n- Knowledge of software architecture and system design.\n\nWhy you\'ll love working here\n- Attractive salary - 13rd month salary and performance bonus\n- A great team behind you - you\'ll work with great people who love solving problems\n- Embracing multiple, new technical stacks to accelerate business development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Charmington La Pointe Officetel Apartments, 181 Cao Thang St, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(915, 298, 2, 'Senior iOS Native Engineer (Swift)', 'ANDPAD Việt Nam is seeking a Senior iOS Native Engineer (Swift) who can join our team and develop the application in cooperation with the product manager. Working in the form of Squad, a small team can quickly and consistently engage in everything from design to development, testing and operation.\n\nAlso, there are a lot of opportunities to work with new languages  and frameworks other than the main language in an international environment.\n\n■ Job Scope\n• Design and implementation function of the product in charge of using Swift and other mobile technologies such as Flutter\n• Refactoring of existing applications, enhancements performance, Cost reduction of regression testing by implementing appropriate test code\n• High-performance design and development of camera module and drawing functions\n• API design and implementation linked with backend\n• Requirements definition and specification formulation in collaboration with product managers, designers and QA\n• Keep up to date on the latest industry trends and best practices in mobile technologies and apply them to the product\n• Enjoy working on challenging solutions and systems\n\nNote: The assigned product will be determined based on the candidate\'s skills and preferences, as well as the internal structure of the company.\n\n■ Development environment\n• Programming: Swift, Dart\n• Framework: RxSwift, Flutter\n• Infrastructure: AWS / GCP\n• CI/CD: CircleCI / Bitrise / Fastlane / GitHub Actions\n• Knowledge Tool: Confluence / esa\n• VCS: GitHub\n• Others: Slack / Jira\n\nYour skills and experience\nMust-haves:\n• Empathy for Andpad\'s mission and values\n• 6+ years of experience in developing native applications for iOS Native using Swift\n• Experience of architecture design, frameworks and technologies selection based on application requirements\n• Experience as a technical lead throughout the full project development lifecycle\n• Creating high quality code for security, performance, scalability, etc.\n• Excellent algorithms, analytical, problem-solving skills and improving application performance\n• Continuously discover, evaluate, and implement new technologies to maximize development efficiency\n• Experience in dealing with scalability in line with service growth\n• Experience in UIKit and SwiftUI\n• Experience in Asynchronous programming, Reactive programing skills\n• Familiar with Restful / GraphQL API\n• Excellent developing functions with writing test code\n• Have knowledge of Mobile application security\n• Conduct regular code reviews and provide feedback to team members adhering to best practices\n• Participate in the planning process for software development projects, and ensure meeting quality and deadlines on delivery.\n• Skills in communicating smoothly with team members and other stakeholders\n• Good at English communication\n\nNice to haves:\n• Experience to build project from scratch\n• Ensure high-quality work by monitoring individual and team performance and addressing any issues through appropriate guidance and mentoring\n• Responsible for supervising, managing and motivating the mobile development team\n• Ability to write project documentation\n• Experience in developing hybrid applications for Flutter using Dart\n• Experience in Android Native (Kotlin)\n• Experience in automation test\n• Project management skills\n\nWhy you\'ll love working here\n• Competitive salary package, including full insurance coverage. \n• Annual performance review: twice/ year.\n• 13th-month salary Bonus.\n• Hybrid working model.\n• 18 days of leave: 12 days of annual leave, 6 days of New Year Leave.\n• Premium Healthcare Insurance Package starting from day one.\n• Annual Health Check-up.\n• Excellent career development opportunities, with exposure to and experience in the latest technologies.\n• Patents and Inventions bonus.\n• Company trip, Year-End Party, Gifts for Tet/ Holidays.\n• MacBook Pro/laptop is provided.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3rd Floor, Dong Nhan Building, 90 Nguyen Dinh Chieu, Da Kao Ward, District 1, Ho Chi Minh; 2F, Building C, Office Area, Udic Complex, Hoang Dao Thuy Street, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(916, 463, 2, '.NET/C# developers ($1,000-$1,600 net)', '• Design and architect complex, scalable Broker/Banking applications;\n• Develop and code business applications, multi-tiered web and client server applications using: C#, Oracle/MS SQL, Microservices experiences;\n• Knowledge and experience with Web API/Restful API, SPA;\n• Strong Object-Oriented design skills;\n• Provides technical expertise to maintain environments and troubleshoot issues with software delivery;\n• Technical design, mentoring and implementation of best practices and processes;\n• Develop the software architecture based on the business requirements and constraints;\n• Ensure efficiency of your team by giving them technical advices along the delivery process;\n• Be responsible to deliver proof of concepts which validates technical choices;\n• Organize knowledge sharing and continuous learning;\n• To carry out any other duties as and when directed;\n\n• Candidates must possess at least a Diploma, Advanced Diploma, Bachelor’s Degree, or higher in Computer Science/Information Technology or equivalent;\n• Minimum 3 years working experiences in Software analysis, design, development & implementation;\n• Strong analytical and technical skill on C#/.Net, Oracle/MS SQL with Store Procedure;\n• Execute full software development life cycle (SDLC);\n• Develop flowcharts, layouts and documentation to identify requirements and solutions;\n• Write well-designed, testable code;\n• Integrate software components into a fully functional software system;\n• Develop software verification plans and quality assurance procedures;\n• Troubleshoot, debug and upgrade existing systems;\n• Able to work as a team member with other technical staff, such as developers and infrastructures team members;\n• Strong team player as well as an independent learner;\n• Able to work under stress to meet timeline;\n\n• A very attractive salary package: 1,000USD - 1,600USD in net;\n• 13th month salary, contingency performance bonus;\n• Hanoi Head Office: 7 Flr., A-B Tower, Imperia Garden Building, 143 Nguyen Tuan Str., Thanh Xuan, Hanoi\n• Working hour: 8.30am-5.30pm (Mon - Fri) and by assignment;\n• Review and increment twice a year;\n• Knowledge sharing and learning on all IT aspects oversea;\n• Annual leave: Maternity, Married...;\n• Social, Healthcare, Unemployment Insurance;\n• Private health care program for you and your family members;\n• Seminar, Trip, Training oversea allowance;\n• Company trip, Team building/Happy hour, Birthday party...;\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '7th Flr., A-B Tower, Imperia Garden Building, 143 Nguyen Tuan Str., Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(917, 189, 2, 'Embedded Software Engineer (Fresher/Junior/Middle)', 'Currently SEHC\'s DA S/W R&D G is launching new projects for 2025. Therefore we are looking for Embedded Software Engineer talents to join our team to work with global team in India, Korea, China, etc.:  Duties:  - Measure and maximize product quality while keeping the milestone timelines intact.  - Should be able to narrow down the problem based on the analysis of the logs and code.  - Ability to define a problem with well-defined scope.  - Requirement gathering and analysis.  - Work closely with R&D team W/W for timely completion of feature development and ensure smooth delivery to market on time.  - Handling Market Support queries and drive critical market issues along with technical and support teams.  - National and abroad traveling involved time to time.  General Requirement:  - Bachelor’s degree in Computer Science, S/W Engineering or IT related field.  - Freshers are welcome.  - Good in English communication for working.  - Mastery in problem analysis, problem resolution.  - Fast learning skills and mindset required to quickly understand new technologies and new modules in product.  - Ability to multi-task and manage tasks with varying priorities.  - Tech-savvy and passionate about building products.  Technical Requirement:  - Knowledge & Experience of software design, development.  - Knowledge in Embedded system (GPIO, UART, SPI, RTC, I2C, Watchdog, interrupt).  - Knowledge in MCU/STM/ARM programming.  - C/C++, Debugging Tools.  - Hands-on experience on IOT product will be preferred.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lot I-11, D2 Road, Saigon Hi-tech Park, Tang Nhon Phu B Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(918, 466, 2, 'Fresher/Jr. IT Support/System Admin (Linux, Networking)', 'Job description\n- Tính chất công việc: Theo ca được phân công. Ngày 3 ca làm việc: 8h00’ - 16h00’, 16h00’ - 24h00’, 00h00’ - 8h00’.\n- Chịu trách nhiệm hỗ trợ khắc phục sự cố cho khách hàng.\n- Quản trị hệ thống Hosting Cpanel, DirectAdmin, aaPanel.\n- Quản trị máy chủ trên hệ điều hành Linux, Windows Server.\n- Quản trị các máy ảo trên nền ảo hóa Type 1 như Proxmox, VMware ESXi.\n- Quản trị hệ thống firewall chống tấn công DoS/DDoS.\n- Quản trị hệ thống Web Server, Mail Server.\n- Tham gia phát triển các công nghệ/công cụ phục vụ cho công việc, các dự án về triển khai và quản trị hệ thống theo yêu cầu.\n\nYour skills and experience\n- Độ tuổi: < 25 tuổi\n- Tốt nghiệp đại học/cao đẳng chuyên ngành Công nghệ thông tin, Mạng máy tính, An ninh mạng, Quản trị hệ thống (kèm theo bảng điểm).\n- Sử dụng thành thạo hệ điều hành Linux.\n- Có chứng chỉ LPI 1, LPI 2 hoặc có kiến thức tương đương LPI 1, LPI 2.\n- Có chứng chỉ CCNA hoặc có kiến thức tương đương CCNA.\n- Am hiểu về các services như Apache, Nginx, MySQL, PHP, SQL Server.\n- Nắm vững 1 ngôn ngữ lập trình bất kỳ (Bash, Python, PHP,..).\n- Năng động, có trách nhiệm với công việc.\n- Giao tiếp tốt, trung thực, phát âm rõ ràng.\n- Nhiệt tình, nhanh nhạy trong công việc, có khả năng chịu được áp lực công việc.\n- Có khả năng nghiên cứu độc lập, đọc hiểu tài liệu tiếng Anh tốt.\n\nWhy you\'ll love working here\n- Lương cơ bản: 8 triệu đến 10 triệu.\n- Được hưởng các quyền lợi theo chính sách của công ty và quy định của nhà nước.\n- Review lương 2 lần/năm (tùy vào năng lực), lương tháng 13, cùng nhiều chế độ thưởng khác nhau.\n- Team building 2 lần/năm.\n- Có cơ hội tham gia các khóa đào tạo, phát triển, nâng cao năng lực làm việc.\n- Làm việc trong môi trường chuyên nghiệp, năng động, nhiều cơ hội phát triển năng lực bản thân, đãi ngộ dựa trên năng lực và sự nhiệt tình sáng tạo của từng thành viên.\n- Nghỉ 12 ngày phép năm và các ngày lễ tết, dịp đặc biệt của công ty.\n- Hỗ trợ ăn trưa, gửi xe.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '265 Hong Lac, P. 10, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(919, 374, 2, 'Senior Mobile Engineer (Android/Flutter)', 'Top 3 reasons to join us\n- Flexibility to perform\n- Careers without boundaries\n- Learning and development opportunities\n\nJob description\n\nResponsibilities:\n- You will work closely with the Product, UX/UI and Backend teams to design, build new products, platforms and features.\n- More senior engineers will act as a role model and mentor to more junior members.\n- Build re-usable Mobile software components for the CAKE platform.\n- Collaborate with QA on continuous integration and delivery (CI/CD) as well as other automated and manual testing to make sure our app release cycles.\n- You will monitor the performance of the live apps and continuously improve them on both code and experience level.\n- Design, build and improve the mobile experiences for one of the world’s fastest growing mobile app in FINTECH industry.\n- Provide technology leadership to the team and foster engineering excellence.\n- Communicate, collaborate and work effectively across cross functional teams in a global environment.\n- Identify and correct bottlenecks and fix bugs.\n- Help maintain code quality, organization and automatization.\n\nYour skills and experience\n\nRequirements:\n- Bachelor’s degree in Computer Science, related technical field, or equivalent practical experience.\n- At least 4 years of experience in Flutter or Android\n- Experienced with third-party libraries, APIs, web services and JSON, e.g Dagger 2, RxJava, Retrofit, GSON etc.\n- Should have an excellent understanding of Java - OOPS, Interface, Abstract class, Collection framework.\n- A good overall understanding of the modern mobile development landscape and different programming paradigms (e.g. unit and e2e testing, CI/CD, object-oriented and functional programming, UX, analytics, REST/GraphQL APIs)\n- Understanding the MVC/MVP/MVVM design patterns.\n- You are quick on your feet, always aiming for quality and are a natural collaborator.\n- Familiarity with Scrum & Agile.\n\nWhy you\'ll love working here\n\nBenefits\n- 13th salary\n- Social Insurance\n- Medical healthcare\n- Annual health check\n- 15 days annual leave\n- Transportation fee (BE\'s services)\n- Performance bonus\n- Holiday bonus\n- Team Building and many engagement activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FIVESTAR BUILDING, 28bis Mac Dinh Chi, Dakao, Distric1, HCM City, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(920, 581, 2, 'Mobile Developer (Reactnative)', 'JOB ROLE: Mobile Developer (REACT NATIVE)\n\nWe are looking for a talented and motivated React Native Developer to join our mobile development team. You will be responsible for developing and maintaining cross-platform mobile applications with a focus on performance, scalability, and great user experience.\n\nKey Responsibilities:\n- Develop mobile applications using React Native, ensuring high performance and high-quality visual elements and responsiveness.\n- Work closely with product owner, designers, and backend developers to deliver high-quality features.\n- Optimize app performance and ensure smooth UI/UX across iOS and Android.\n- Write clean, modular, and testable code following industry best practices and coding standards.\n- Troubleshoot and debug issues, and deploy timely fixes.\n- Integrate third-party APIs, native modules, and platform-specific features.\n- Participate in code reviews, sprint planning, and other agile ceremonies.\n\nYour skills and experience:\n- 3.5+ years of experience in mobile app development.\n- Proficiency in JavaScript (ES6+); TypeScript is a plus.\n- Solid understanding of React Native architecture, React lifecycle, hooks, and navigation libraries (e.g., Wix React Native Navigation, React Navigation).\n- Experience with React Context, Redux, or other state management libraries.\n- Experience with React Native Reanimated, FlashList, or Skia.\n- Knowledge of mobile performance optimization techniques.\n- Proficiency in caching and memoization techniques to enhance application performance.\n- Familiarity with native modules integration (iOS/Android).\n- Experience working with RESTful APIs and third-party libraries, particularly with Firebase integration.\n- Experience with real-time communication using Socket.IO or similar libraries.\n- Understanding of mobile security best practices.\n- Familiarity with mobile testing tools (e.g., Jest, Detox, Appium) is a plus.\n- Proficient with version control (Git), CI/CD pipelines (e.g., Fastlane, GitHub Actions), and bug tracking tools (e.g., JIRA).\n- Good communication skills and ability to work in a collaborative environment.\n- Ability to work independently and take ownership of features from concept to deployment.\n\nWhy you\'ll love working here:\n- Working time: 5 days/week (Monday to Friday)\n- Opportunity for promotion and career development\n- Competitive Income and Attractive Bonus Policy\n- Compulsory Insurances full salary (Social Insurance, Health Insurance, Unemployment Insurance) based on the Labor Code and PVI premium health Insurance based on the Company\'s regulations\n- 11 Public holidays based on the Labor Code, 15-22 Annual leave days based on the Company\'s regulation, 5-year-employee has 1 more annual leave day\n- Company Team Building Trip every year\n- Participate in other Company activities: Sports, Family Day, Children\'s Day\n- Training sponsorship programs: Securities certificates, Soft skills, Technical skills\n- Professional and dynamic working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Công ty Cổ phần Chứng khoán Vietcap – Tầng 19 Tháp tài chính Bitexco, 02 Hải Triều, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(921, 582, 2, 'Senior Golang Developer (JavaScript, HTML, CSS3, MVC)', 'SGH Asia is a leading technology solutions provider specializing in digital transformation, offering services such as software development, IT support, business process outsourcing, and data digitalization.\nWe are looking for a Freelancer Senior Golang Developer to join us and work on our client’s projects using cutting-edge technologies.\nThe ideal candidate will design, develop, and maintain our back-end services, focusing on performance and scalability. This role demands excellent problem-solving skills, a deep understanding of web development, and the ability to thrive in a fast-paced environment.\nResponsibilities:\nDesign and Development:\n- Code Development: Design, develop, and maintain efficient, reusable, and reliable code using Golang.\n- Application Performance: Build scalable, high-performance applications and APIs.\n- Collaboration: Work with cross-functional teams to define, design, and deliver new features.\n- Problem-Solving: Identify bottlenecks and bugs, and propose effective solutions.\n- Code Quality: Maintain high code quality, organization, and automation.\n- Code Reviews: Conduct reviews and provide constructive feedback to team members.\n- Team Leadership: Manage and lead junior backend engineers in delivering platform functionality.\n- Project Management: Provide hands-on resource management for all backend development activities.\n- Industry Trends: Stay updated on the latest technologies to ensure cutting-edge systems.\nCollaboration and Support:\n- Strategic Planning: Collaborate with senior engineering teams on planning and development.\n- User Experience: Partner with the UX department to design and deploy scalable technologies to enhance user satisfaction.\n- Reporting: Report on the status of development, operations, quality, and performance to senior leadership.\n- Standards Compliance: Ensure systems meet business requirements and standards.\nYour skills and experience:\n- 4+ years of experience with Golang\n- Strong understanding of Golang’s synchronous behavior\n- Familiarity with MVC design patterns\n- Basic knowledge of front-end technologies (JavaScript, HTML5, CSS3)\n- Understanding of accessibility and security compliance\n- Knowledge of scalable application design principles\n- Experience with user authentication and authorization across systems\n- Ability to integrate multiple data sources and databases\n- Familiarity with SQL/NoSQL databases and their query languages\n- Proficiency in code versioning tools like Git.\nWe’re excited to meet talented individuals who are passionate about building great products—come join our team!\nWhy you\'ll love working here:\nWe are always on the lookout for creative, passionate, curious, innovative, and solution-driven team players who want to maximize their growth potential in a dynamic, collaborative, and diverse business environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'SGH Building, 21/4 Nguyen Thi Huynh Street, Ward 8, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(922, 364, 2, 'Software Development Engineer (C#, SQL, Javascript)', 'Job description\n1. Maintain automated data onboarding and diagnostic tools for AIP partners \n2. Monitor ADF pipelines and mitigate pipeline runs as needed \n3. Maintain Privacy Dashboard and Bing user interests for Bing Growth team usage \n4. Participate and resolve live sites in related areas \n5. Data Platform development and maintenance, Notebook based processing pipelines and MT migration \n6. Manage the regular data quality Cosmos/MT jobs \n7. Online tooling and support such as DADT tools \n8. Watch out the abnormal pattern, perform ad-hoc data quality analysis, investigate daily the user ad click broken cases\n\nYour skills and experience\n1. Bachelor’s degree or higher in Computer Science or a related field. \n2. At least 3 years of experience in software development. \n3. Good quality software development and understanding.\n4. Ability to quickly communicate across time zones.\n5. Excellent written and verbal communication skills in English\n6. Self-motivated\n7. Software design and development experience with at least one of C#/Javascript\n8. Technologies: Apache Spark, Apache Flink, Apache Kafka, Hadoop, Cosmos, SQL\n9. Azure resource management: ADF, Azure Key vaults, Managed Identity, Azure Storage, etc. \n10. Big data experience is a plus \n\nWhy you\'ll love working here\n1. Innovative Work Culture: Join a team where creativity and innovation are at the heart of everything we do. Our IT company thrives on new ideas, and we encourage a collaborative environment where every voice is heard. You\'ll have the opportunity to work on cutting-edge projects that push the boundaries of technology.\n2. Career Growth & Learning Opportunities: We believe in the power of continuous learning. Whether it’s through mentorship, online courses, or access to industry conferences, we provide the tools you need to grow professionally. You’ll have opportunities to learn and advance in your career, all while working with some of the best minds in the industry.\n3. Collaborative Team Spirit: We know that great things happen when people come together. Our teams are diverse, inclusive, and driven to succeed. From brainstorming sessions to cross-departmental collaboration, you’ll work with talented individuals who are passionate about what they do.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '32 Pham Ngoc Thach, Ward Vo Thi Sau, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(923, 181, 2, 'Mid/Senior Backend Developer (NestJS, PostgreSQL, AWS)', 'LocalLife.Asia là nền tảng kết nối du khách với trải nghiệm cộng đồng thực thụ tại các vùng nông thôn, miền núi, dân tộc thiểu số khắp châu Á. Đây không chỉ là du lịch, mà là hành trình sống cùng, học cùng, làm cùng người dân địa phương.\n\nChúng tôi không dẫn bạn đi du lịch, chúng tôi dẫn bạn vào lòng người dân.\n\nLà MidSenior Backend Developer, bạn sẽ :\n\n📌 Nhiệm vụ:\n- Thiết kế và triển khai API cho các chức năng: đặt chỗ, quản lý người dùng, dịch vụ homestay/tour/xe.\n- Làm việc với PostgreSQL, Redis, và triển khai trên AWS (ECS Fargate, S3).\n- Tích hợp hệ thống thanh toán nội địa (Momo, ZaloPay).\n- Thiết lập CI/CD cơ bản (Docker, GitHub Actions).\n\nYour skills and experience\n- Tối thiểu 2 năm kinh nghiệm với NestJS, TypeScript, PostgreSQL. \n- Kinh nghiệm sử dụng Docker và thiết lập CI/CD. \n- Hiểu biết về kiến trúc hệ thống và khả năng làm việc độc lập. \n- Ưu tiên ứng viên đã từng làm việc trong các dự án startup hoặc hệ thống đặt chỗ.\n\nWhy you\'ll love working here\n- Mức lương hấp dẫn\n- Lương tháng thứ 13\n- Khám sức khoẻ hàng năm\n- Thi thoảng - Code mọi nơi, test luôn sản phẩm du lịch cộng đồng\n- Chuyển sang chế độ làm việc Hybrid nếu đáp ứng thời gian làm việc đủ lâu.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '63 Nguyễn Hiến Lê, phường Hoà Xuân, Cam Le, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(924, 345, 2, '[English] Software Customer Support Specialist', 'We seek a qualified Software Customer Support Specialist to ensure our customers have exceptional experience with SimpleMDG. You will provide top-notch technical support, assist in troubleshooting several types of product issues, and offer professional guidance to help customers make the most of our product. Your dedication to customer happiness is crucial to our mission of delivering high-quality service and cultivating long-term customer relationships. Standout candidates will be excellent problem-solvers with outstanding communication and customer service skills.\n\nResponsibilities:\n- Identify and clarify product issues while working collaboratively with customers to achieve prompt resolution.\n- Maintain excellent verbal and written communication skills and a high level of customer service with a focus on first-reply resolution.\n- Engage with customers by means of email, customer portal, and chat to manage customer relationships and to ensure successful execution of requests.\n- Develop and update both internal and customer-facing knowledge base documentation including user guides, help articles and training videos.\n- Work closely with other departments to report and resolve technical issues to ensure our product is meeting the needs of the customer.\n- Participate in shift or on-call rotation as needed by the department to ensure all support hours are effectively covered. There are 3 shifts to be covered: 9AM – 6PM, 3PM – 12AM, and 12AM - 9AM next morning. (the first 2 shifts will be more common than the last shift)\n\nYour skills and experience:\n- 2-3 years of experience in Software Customer Support\n- Fluent in English\n- Strong communication, interpersonal skills, customer empathy and determination to resolve issues\n- Ability to influence others (internal and external stakeholders) through persuasion, negotiation, and consensus building\n- Analytical, data and process-oriented mind-set\n- Demonstrates a desire for continuous learning and self-improvement for the benefit of yourself and your team.\n- Enthusiastic and creative in problem solving\n- The ability to quickly learn new applications and technologies.\n\nWhy you\'ll love working here:\n- 15 days of annual leaves\n- Competitive salary (+13-month salary include) \n- Health insurance, social insurance according to the government regulations \n- PVI Healthcare Insurance \n- Have a chance to work in an international, friendly, open environment \n- Annual Travel opportunity', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '324 Le Van Sy, Ward 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(925, 583, 2, '(Mid/Senior) Java Developer (Spring, MVC, OOP, CI/CD)', 'Top 3 reasons to join us\n\n- Fun, Flexible And Professional Working Environment\n- Global Career Growth Opportunities\n- Attractive Salary, Bonus And Annual Salary Review\n\nJob description\n\n- Design, develop, and maintain Java applications using Spring Boot and Spring Framework.\n- Implement RESTful APIs and integrate with frontend applications.\n- Write efficient, scalable, and maintainable code.\n- Develop and optimize database queries for MySQL and MongoDB.\n- Work with JPA/Hibernate for ORM (Object Relational Mapping) and ensure efficient database interactions.\n- Utilize Spring Core, Spring MVC, Spring Security, Spring Data JPA, and Spring Boot for application development.\n- Implement Spring Security for authentication and authorization.\n- Write and maintain unit tests (JUnit, Mockito).\n- Manage source code using Git and repositories like GitHub/GitLab/Bitbucket.\n- Stay updated with the latest trends in Java, Spring, MySQL, MongoDB, and emerging technologies.\n- Improve existing features and propose innovative solutions.\n- Make quality and usability your primary goals.\n- Problem investigation, system troubleshooting and bug fixing.\n\nYour skills and experience\n\n- Minimum of 4 years of experience in Java backend development using Spring Boot or similar frameworks.\n- Proficiency in Java 8+ with strong understanding of OOP (Object-Oriented Programming) concepts.\n- Experience with the Spring Framework, including: Spring Boot (Microservices development), Spring MVC (Web applications), Spring Data JPA (ORM with Hibernate), Spring Security (Authentication & Authorization).\n- Experience with JPA/Hibernate for ORM and database interactions.\n- Proficiency in developing RESTful APIs and working with Swagger/OpenAPI for documentation.\n- Good knowledge of Git (GitHub, GitLab, or Bitbucket).\n- Familiarity with CI/CD pipelines (e.g., Jenkins, GitHub Actions, GitLab CI).\n- Experience with testing frameworks such as JUnit and Mockito for unit and integration testing.\n- Good willingness to learn new technologies as required for the role.\n\nNice-to-have Skills:\n\n- Basic knowledge of Docker (Kubernetes is a plus).\n- Understanding of caching mechanisms (e.g., Redis, Ehcache).\n- Familiarity with messaging systems (e.g., RabbitMQ, Kafka).\n- Experience with front-end technologies like HTML5, JavaScript, CSS, JQuery, AJAX.\n- Knowledge of eCommerce systems, especially SAP Hybris.\n\nWhy you\'ll love working here\n\n- You will become the key members of WATA TECH as we WATA TECH is growing faster and bigger now\n- Guaranteed permanent employment and career development.\n- Outdoor activities with company support: team building, happy hour party monthly, birthday, company trip, women days, Mid-Autumn festival, sport clubs, etc.\n- Opportunities to improve English skills within an international team – English is an official language.\n- Opportunities to gain hands-on experience in cutting-edge technologies\n- Skills up plan with Tech talk, soft skill talk, English club, working process training.\n- 5 working days per week (Monday-Friday), some extent flexible working hours.\n- Competitive salary package with 13th monthly salary, a good long-term and performance bonus.\n- Performance review twice a year.\n- Loyalty Employee Benefit.\n- Support onsite fee with two way airline tickets if customer requires.\n- Friendly, professional and open working environment.\n- Premium Health Insurance package for you.\n- Attractive signing bonus.\n- Free snack-drink.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '50 Cửu Long, Phường 2, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(926, 205, 2, 'Principal Software Engineer (Mobile), up to 4k', 'At LeapXpert, we\'re revolutionizing business communication by seamlessly integrating the familiarity of consumer messaging apps with enterprise-grade security and compliance.\n\nAs pioneers in responsible business communications, we empower employees and clients to connect through their preferred messaging platforms while upholding the highest standards of governance and security.\n\nOur mission is to transform workplace communication globally.\n\nWe\'ve been recognized as a Visionary in Gartner\'s Magic Quadrant for Digital Communications Governance and Archiving Solutions, raised a $20 million Series B funding round—bringing our total funding to $60 million, and earned the trust of top-tier institutions worldwide, who rely on our platform daily to streamline client communications.\n\nThis is just the beginning—we\'re growing rapidly and we\'re seeking passionate, talented individuals to join our team.\n\nThis is your opportunity to work on impactful projects using cutting-edge technologies alongside driven innovators from around the world.\n\nApply now to be part of something revolutionary!\n\nWe are looking for a Senior Software Engineer (Mobile) who has strong experience with Mobile to be in charge of architecting and building performant mobile apps on both the iOS and Android platforms. You will be, as well, collaborating with teams on other layers of the product infrastructure.\n\nResponsibilities:\n- Build pixel-perfect, buttery smooth UIs across both mobile platforms \n- Leverage native APIs for deep integrations with both platforms \n- Diagnose and fix bugs and performance bottlenecks for performance that feels native\n- Reach out to the open-source community to encourage and help implement mission-critical software fixes as React Native moves fast and often breaks things \n- Maintain code and write automated tests to ensure the product is of the highest quality\n\nYour skills and experience:\n- Strong native development skills in either Android (Java/Kotlin) or iOS (Objective-C/Swift) - must be confident jumping into native modules when needed. \n- Experience with React Native is required - you\'ll be working directly with it as part of your daily responsibilities. \n- Solid problem-solving ability with a deep understanding of mobile architecture, debugging, and performance optimization. \n- Proven experience in leading small teams or mentoring junior developers, with a focus on code quality and delivery. \n- Hands-on experience with automated testing tools such as Jest.\n- Proficient in both functional and object-oriented programming paradigms\n- Comfortable integrating and troubleshooting third-party libraries and resolving complex dependency issues.\n- Solid grasp of RESTful APIs, network layers, and offline storage techniques. \n- Strong experience with Git and collaborative workflows. \n- Excellent communication skills in English (spoken & written). \n- A team player with a leadership mindset, attention to detail, and drive to high standards. \n- Experience in using AI tools to accelerate development (e.g. Copilot, ChatGPT, or similar) is a plus.\n\nWhy you\'ll love working here:\nYou are looking for: \n- An awesome job opportunity with an attractive remuneration package \n- Working on site in a stylish and comfortable environment \n- Friendly coworkers who support each other to win together as a team \n- Working in a team that encourages AI adoption, experimenting with and learning new AI tools to enhance the developer experience \n- A flat, product-focused organization and Agile teams that allow you to bring value and ideas to the product and the company \n- Opportunities to learn and be trained in new technologies and methodologies \n- Facing new and innovative challenges to deliver a commercial-grade, world-class product \n- Career growth in multiple directions, based on your preferences and abilities\n\nBenefits: \n- 13th Salary, paid pro-rata, every month to allow more flexible financial plans \n- 18 annual leaves and 1 birthday leave \n- Full salary on probation \n- Full social insurance according to Vietnam Labor Law\n- Premium Health Care Insurance \n- Annual health check \n- Lunch and parking allowances \n- Team building, fun monthly, quarterly activities, and so much more fun are waiting for you! \n- Relax with Tabletop foosball, PlayStation, massage chair in the office \n- Annual Performance Review \n- Attractive career path \n\nAdvanced technical solutions, Agile culture and the opportunity to work with the latest technologies Sounds like a good fit? Come and join the team at LeapXpert!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '195/10E Dien Bien Phu, Ward 15, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(927, 225, 2, 'QA Manager (QA QC, Automation Test)', 'By applying for the above position, you accept and agree that your personal data and any information stated in the attached curriculum vitae (CV) will be used and processed by ITViec and NAB Vietnam for recruitment purposes. The storage and processing of such information will comply with the applicable laws of Vietnam, and the policies and procedures of ITViec and NAB Vietnam regarding personal data, as amended from time to time.\n\nYOUR JOB RESPONSIBILITIES\n1. Quality Management \n- Accountable for all quality aspects in multiple squads or multiple sub-domains. \n- Define and align with stakeholders (HO, PQEM, EM) on the testing strategy and approach. \n- Participate in the strategic delivery planning of the squads and domain. \n- Promote and implement Shift-Left testing and Automation first. \n- Maintain and enforce testing approach, best practices, align/adapt to the global processes. \n- Understanding the testing challenges/blockers, be an escalation point for quality issues and help to resolve them. \n- Participate in software development process including fixing complex production code, reviewing code, and contributing to software design, if required. \n- Drive the design, implementation, maintenance of automation frameworks and CI/CD integration. \n- Manage all the stages of testing (ST, ST +1, SIT) and the SIT environment. \n- Define, monitor and report the quality metrics. \n- Manage release testing activities. review, sign-off testing results. \n\n2. Talent Management \n- Recruit and make QE hiring decision. \n- Participate in planning and allocating QEs across multiple squads. \n- Build a strong team culture and foster employee engagement. \n\n3. Performance Management \n- Define the QE goals based on the domain and QE center’s priorities. \n- Have development/career plans and 1-1 for team members. \n- Provide feedback and assess the performance on a quarter/annual basis. \n\n4. Capability Building \n- Identify gaps, organize training for upskilling the QE capabilities. \n- Train and enable senior QEs to take leadership roles. \n- Contribute to building cross-domain capabilities for NAB. \n\n5. Innovation \n- Drive, contribute towards innovation in QE processes/tools and domain’s innovations. \n- Support the QE colleagues to stay on top of the latest testing technology trends.\n\nYour skills and experience\n- 10-15 years of quality engineering experience along with people leadership experience of large teams (15 – 30 members) with excellent leadership and organizational skills to simultaneously direct, inspire, coach, and lead multiple quality teams in a dynamically changing environment. \n- Strong quality mindset and familiar with implementing shift-left testing approach. \n- Expert in testing methodologies and techniques, extensive experience with the quality engineering practices of end-to-end enterprise grade systems. \n- Ability to implement domain level strategies to improve the quality of application. \n- Knowledge of software development, software design, and overall system architecture. \n- Strong programming skills in any programming language. (such as Java, JavaScript, Python) \n- Expert in automation architect and framework development from scratch using specific domain testing stack. (Such as Selenium, Appium, Espresso, WDIO, Playwright, Rest Assured, )\n- Solid Cloud and CI/CD Experience - Knowledge of AWS, Azure, Docker & Kubernetes, Jenkins \n- Demonstrable problem-solving and decision-making skills along with strong teamwork, collaboration & communication. \n- Ability to learn and become an SME in a banking domain or subdomain(s) \n\nWhy you\'ll love working here\n1. Generous compensation and benefit package  \n- Attractive salary and benefits \n- 20-day annual leave and 7-day sick leave, etc. \n- 13th month salary and Annual Performance Bonus \n- Premium healthcare for yourself and family members \n2. Exciting career and development opportunities  \n- Large scale products with modern technologies in banking domain \n- Clear roadmap for career advancement in both technical and leadership pathways \n- Sponsored certificates in both IT and banking/finance \n- Premium account on Udemy \n- English learning with native teachers \n3. Professional and engaging working environment  \n- Hybrid working model and excellent work-life balance \n- Well-equipped & modern Agile office with fully-stocked pantry \n- Annual company trip and events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh, ROX Tower, 54A Nguyen Chi Thanh, Lang Thuong, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(928, 258, 2, 'VIC - Backend Developer ( NodeJS, Java, PHP)', 'Top 3 reasons to join us\n• Dẫn đầu thị trường\n• Cơ hội thử thách và phát triển bản thân\n• Môi trường làm việc năng động\n\nJob description\nTrung tâm Công nghệ thông tin là đơn vị xây dựng, triển khai, duy trì các hệ thống phần mềm, số hóa các quy trình thuộc lĩnh vực quản trị doanh nghiệp (tài chính, tài sản, kho, mua sắm, nhân sự...) trong Tập đoàn, triển khai các công cụ phần mềm hỗ trợ nghiệp vụ cho các đơn vị trực thuộc. Đồng thời, trung tâm cũng nghiên cứu và triển khai các giải pháp ERP nhằm nâng cao năng lực quản trị, nâng cao hiệu quả sử dụng tài nguyên (bao gồm cả tài nguyên con người), nhất quán về cách thức quản lý và đảm bảo tính tuân thủ của Viettel trên toàn cầu.\n• Phát triển backend (sử dụng NodeJS/Java/PHP), đảm bảo đáp ứng đúng các yêu cầu nghiệp vụ.\n• Phối hợp với các bộ phận liên quan để làm rõ yêu cầu kỹ thuật, xây dựng kiến trúc hệ thống và tích hợp dữ liệu.\n• Tham gia viết unit test, kiểm thử chức năng và xử lý lỗi trong quá trình triển khai.\n• Deploy code trên server test và production.\n• Giám sát và đảm bảo hệ thống vận hành ổn định, tối ưu.\n• Nghiên cứu và đề xuất cải tiến hiệu năng, kiến trúc hệ thống, công nghệ mới nhằm nâng cao chất lượng sản phẩm, tối ưu hóa hệ thống để xử lý dữ liệu lớn.\n• Các công việc khác theo phân công của quản lý\n\nYour skills and experience\n• Tốt nghiệp Đại học loại khá trở lên chuyên ngành CNTT, KHMT hoặc các ngành liên quan.\n• TOIEC >=550 hoặc tương đương.\n• Có ít nhất 3 năm kinh nghiệm lập trình backend (sử dụng NodeJS/Java/PHP).\n• Có kiến thức và tư duy lập trình hướng đối tượng (OOP).\n• Có hiểu biết về CI/CD\n• Có kiến thức về cơ sở dữ liệu.\n• Có kiến thức về an toàn thông tin\n• Có hiểu biết về quy trình phát triển phần mềm theo mô hình Agile/Scrum.\n• Ưu tiên ứng viên có kinh nghiệm tích hợp hệ thống và triển khai ứng dụng trên nền tảng cloud (AWS, GCP,...).\n\nWhy you\'ll love working here\n• Thu nhập hấp dẫn, thỏa thuận theo năng lực và kinh nghiệm.\n• Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo theo cách riêng.\n• Được khơi gợi cảm hứng làm việc với văn phòng xanh, không gian mở, hiện đại tiêu chuẩn quốc tế.\n• Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày.\n• Thưởng thức bữa trưa thơm ngon tại Tập đoàn, được chọn lọc bởi các chuyên gia dinh dưỡng.\n• Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building.\n• Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, Trụ sở chính của Tập đoàn Viettel, Lô D26, Khu đô thị mới Cầu Giấy, phường Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(929, 584, 2, 'Senior / Expert Data Engineer (3 head counts)', 'What working at Zuhlke is all about. We work on Projects for purpose, making it our mission to give our work a deeper meaning, ensuring we are focused on creating positive change through technology and digital innovation. We are Flexible, offering a variety of working options to cater to our people’s needs. We pride ourselves on having a Growth mindset with a strong learning culture and we invest in learning and development but also believe strongly in learning on the job and through mentorship and coaching. Sustainability is one of our top strategic goals. We are carbon neutral as a business, and we are strategically positioning our business offerings in decarbonisation, healthcare and green energy to help clients develop sustainable digital solutions. We care about the work we do. Diversity and inclusion are also high on the agenda. We are constantly looking to improve and develop, increasing diversity and developing a more inclusive workplace for all.\n\nYour role includes.\n1. Being a trusted advisor, guiding our customers towards a successful technical solution to their data challenges.\n2. Communicating the what, why and how of proposed solutions to technical and non-technical stakeholders.\n3. Understanding the big data world whilst developing, testing, and monitoring distributed data processing pipelines.\n4. Extrapolating versatile data sets and sources to produce high quality, reproducible datasets in a scalable and maintainable way.\n5. Collaborating with different data roles such as Architects, Software Engineers and Data Scientists with ease.\n6. Understanding the needs of multiple types of producers and consumers for our data services, ensuring our products meet their requirements.\n7. Delivering projects in an Agile way, building iteratively to produce value from data early and frequently.\n8. Keeping yourself technically sharp, being open to learning new concepts and technologies.\n9. Working collaboratively with colleagues and clients, be it onsite, in the Zuhlke office, or from home.\n\nWe would love to hear from you if you have ANY of the following: We encourage our data engineers to be open to learn new technology on a project-by-project basis. We are looking for Data Engineers who have a sample of the following skills and experience:\n1. Experience of designing, building and maintaining data products that meet the needs of data consumers.\n2. An understanding of common approaches to data analysis, machine learning and data visualisation so you can produce the right data for data consumers.\n3. Experience with a variety of approaches to data architectures (e.g. Data Lake, Data Mesh, Data Warehouse, streaming, batch processing)\n4. Hands-on experience with databases both relational and NoSQL.\n5. Familiarity with big data infrastructures and concepts for storing and processing large and/or heterogeneous data volumes.\n6. Practical knowledge of handling varied types of structured and unstructured data (text, tabular, graph, time-series, geospatial, image, etc.).\n7. Working knowledge of containerisation and public and private Cloud environments.\n8. Knowledgeable about information security and data governance.\n9. Excellent and practical data programming skills with experience in different programming languages like Java or Python.\n10. You have experience delivering projects to deadlines, with an emphasis on quality, ideally in client facing contexts.\n\nYou would have the opportunity to work with a variety of technologies and tools, including:\n- Programming Languages – Python, Java, SQL.\n- Cloud environments – AWS (must have) /GCP/Azure\n- Big Data Frameworks – Hadoop, Spark, Kafka\n- Databases - PostgreSQL, MongoDB, Hive\n- Orchestration and Containerisation – Airflow, Docker\n\nBehaviors:\n- You’re open, proactive, responding to changes quickly and with agility while learning in the process\n- You maximise benefit as simply as possible but as complexly as needed\n- You recognize and seize opportunities confidently and take an entrepreneurial approach\n- You focus on the customer and guide them from the concept phase through to market success\n- You’re able to persuade people through clear communication, negotiation skills, empathy and an ability to see things from others’ perspective\n- You establish long-term, partnership-oriented relationships and develop and maintain them\n- You think and act in the interests of the organisation as a whole and utilise synergies\n- You take personal initiative in confronting obstacles and failures, have an optimistic overall attitude and take measures to ensure performance in the long term\n\nLearn more about a career in  at Zuhlke. Even if you feel you don\'t meet all the requirements yet, we are still happy to get to know you, learn more about your ambitions and ideas and look forward to receiving your application!\n\nWe are Stonewall Diversity Champions. Stonewall is an organisation who is committed to LGBTQ+ inclusion and provides guidance to companies who are members and share the same values.\n\nWe welcome people from all backgrounds, regardless of their gender, personality, national origin, race, religion, colour, sexual orientation, gender identity, age, marital status, disability or veteran status.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Sentry P Building - 7th Floor, 16 Nguyen Dang Giai, Thao Dien Ward, Thu Duc City, Ho Chi Minh City, Vietnam, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(930, 204, 2, 'QC Engineer (Manual + Automation, Tester, QA QC)', 'We are looking for a QC Engineer (Manual + Automation) to join the Lumin team at DSV. As a QC Engineer, you will be part of a talented and committed community, passionate about delivering a high-quality experience for our customers.\n\nResponsibilities\nAs a QC Engineer, you are responsible for:\n- Review documentation and requirements to determine intended functionality.\n- Create comprehensive test strategies and plans that cover both manual and automated tests to ensure product quality.\n- Create and execute manual test cases to assess performance according to product specifications.\n- Design and implement automation scripts using automation frameworks and tools to increase testing efficiency and coverage.\n- Work closely with the development team to understand product requirements and ensure that the software meets quality standards before it is deployed.\n- Conduct system, integration, regression, accessibility, performance, and user acceptance testing to ensure comprehensive software quality.\n- Support defining the user story acceptance criteria and ensuring stories meet a high level of quality.\n- Participate in Agile development processes, including attending scrum and sprint planning meetings, to provide feedback and insights.\n\nYour skills and experience\nGood candidate for QC Engineer position should have the following qualifications:\n- Typically have 3+ years of experience in a software testing role, focusing on both manual web and API testing (at least 1 year of experience in API testing) as well as automation testing.\n- Understanding of Software Development Life Cycle (SDLC) and Software Testing Life Cycle (STLC).\n- Good English communication skills (both verbal & written), especially in the global software development environment.\n- Solid knowledge of testing methodologies covering test levels, static testing, and dynamic testing.\n- Ability to develop test plans, test cases, and testing reports.\n- Ability to test web applications across multiple browsers and mobile applications across different devices and operating systems.\n- Knowledge of API testing tools such as Postman for backend testing.\n- Experience with automation tools such as Cypress, Selenium, and Appium for web and mobile testing.\n- Ability to communicate effectively with development teams, project managers, and other stakeholders.\n- Collaborating with other team members and departments to ensure comprehensive testing coverage.\n- Ability to work in a dynamic and continuously changing environment.\n\nNice to have:\n- ISTQB Certification.\n- Experience in the E-signature domain.\n- Experience in testing AI features.\n- Familiar with JavaScript (we’re using it to write e2e).\n\nWhy you\'ll love working here\nWhy You\'ll Love Working Here?\n- Salary Up to $1800\n- Working & growing with Passionate & Talented Team.\n- Diverse careers opportunities with Software Outsourcing, Software Product.\n- English environment with projects from US, UK, …\n- Projects in various domains (pdf, logistic, online contract, medical …)\n- Various training on hot-trend technologies, best practices and soft skills.\n- Have 2 - 3 remote days / week (Flexible).\n- Working time 35 hours/week (Monday – Friday).\n- Maximum 16 days annual leave per year.\n- Refund annual leave days at the end of year. \n- Professional training process (support Udemy training course, >5000 courses).\n- Training course refund (AWS…)\n- Attractive Salary and Benefits.\n- Performance review.\n- Almost all customers from the US, UK ….\n- MacBook Pro provided.\n- Personal laptop allowance: $250 per year. \n- Employee referral bonus: $100 - $500.\n- Project referral bonus: 5% project value contract. \n- Social insurance, PVI Premium health care for you and your loved ones. \n- 13th month salary and Bonus based on team performance.\n- Free in-house entertainment facilities (bilak, ping pong,…), coffee, snacks, instant noodles,…\n- Sport activities: football, table-tennis, table football…\n- Company trips, team building, office parties, ….', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No. 53-55-57, Pho Duc Chinh street, Nguyen Thai Binh ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(931, 585, 2, 'Mobile Engineer (React Native)', 'Job description\n- Develop Hubble software solutions by studying the requirements, use-cases, and process flow to accomplish organization and engineering mission.\n- Work with the team in formulating software architecture, technology stack, and innovative solutions.\n- Assist in the execution of Hubble’s technical aspects specifically enhancement, implementation, and deployment of Hubble’s product and service.\n- Analyse technical feasibility of the software solution from the problem definition, technical requirements, and proposed solutions. Work closely with the product team to document and develop requirements, estimation of timeline, and work plans.\n- Adhere to high quality software development principles, best-practices, design patterns, and code documentation. Research on new technologies, current state-of-the-art development tools and equipment, and opportunities for process improvement.\n- Assist the management in developing and implementing new processes to increase productivity and effectiveness of the engineering team.\n\nYour skills and experience\n- Fluency in written and spoken English is required for communication with international teams and clients\n- Minimum 1 year of software engineering experience building Mobile Applications.\n- Experience working on ReactJS / React Native applications.\n- A passion and drive for learning technologies and applying them pragmatically.\n- Outstanding problem-solving skills and a solid grasp of object-oriented programming.\n- An ability to contribute to a technical discussion and the openness to listen and learn from your peers.\n- Have a good understanding of mobile application architecture.\n- Have a good understanding of various software engineering design patterns.\n- Comfortable with working in a fast-paced environment and highly collaborative team to solve real business problems.\n- Versatility and enthusiasm to tackle new problems across the full-stack and to learn new frameworks as we continue to push technology forward.\n\nWhy you\'ll love working here\n- 100% probation salary.\n- 14 days annual leave (+1 day per year, max 21 days).\n- Hybrid work (at least 2 days in office).\n- Full salary social insurance contribution.\n- Private health insurance (Bao Viet) & annual health check-up.\n- MacBook provided within 2-month probation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '261 Hoang Van Thu st, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(932, 586, 2, 'Junior Frontend Developer (JavaScript/ HTML/ CSS)', 'Job description\n- Tối ưu các luồng xử lý, các nghiệp vụ phức tạp trên giao diện\n- Phát triển và nâng cấp các tính năng trong các dự án đang hoạt động với ngôn ngữ Javascript.\n- Xây dựng các microsite, trang quản lý (CRM, HRM, CMS ...) cho các dự án mới với framework ReactJS.\n- Tương tác dữ liệu với API được đội Backend cung cấp.\n- Phát triển kỹ năng thiết kế UI hoặc định hướng UX.\n- Thực hiện các công việc khác liên quan theo yêu cầu của cấp trên.\n\nYour skills and experience\n- Có kinh nghiệm React Fundamentals,State Management, Redux Toolkit, HTTP Handling, Built Tools, Test Framework (Jest/ Enzyme),Server Side Scripting (NextJS), Browser Developer Tools\n- Có kinh nghiệm làm việc với javascript (ES6,7), HTML, CSS hoặc SCSS, SASS là một lợi thế\n- Có kinh nghiệm làm việc với 1 trong các frontend framework: ReactJS, Angular, VueJS.\n- Ưu tiên từng làm về Typescript\n- Đã từng làm việc với GIT, JIRA\n- Tiếng Anh giao tiếp tốt\n\nƯu Tiên:\n- Ưu tiên có kiến thức và kinh nghiệm làm việc\n\nWhy you\'ll love working here\n- Thưởng ngày lễ theo tình hình kinh doanh của công ty.\n- Thưởng Tết hấp dẫn, tương đương với kết quả công việc đạt được.\n- Tham gia các buổi seminar về công nghệ cuối tuần của Phòng Lập trình;\n- Pantry xinh xắn với rất nhiều đồ ăn nhẹ: trà, cafe, trà sữa, bánh,... Đồ ăn luôn luôn được refill theo nhu cầu.\n- Hưởng đầy đủ BHXH và các chế độ chính sách khác theo quy định của Bộ Luật lao động và công ty.\n- Được thỏa sức sáng tạo và triển khai các ý tưởng mới.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Times city, Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(933, 577, 2, 'Senior QA Engineer (New Headcounts)', 'JOB PURPOSE/MISSION: Ingenico Android Competence Center is tasked with building and maintaining reference software to use across all regions.\nThe Senior QA oversees validation and delivery of products from the center. He/She is expected to lead a project ensuring continuous testing during elaboration, as well as release testing.\n\nREPORTING TO: Test Manager\n\nKEY RESPONSIBILITIES:\n- Work with Agile Project Lead to understand features and establish tests strategy (unit, integration)\n- Assess test effort and establish test plans\n- Build test cases, continuously improve test coverage\n- Coordinate with development group for continuous validation (unit tests)\n- Support automation team to develop automation tool\n- Work with Test Manager to define KPI for QA team, manage KPI and report to Direct Manager\n- Manage release identification and validation (CI)\n- Guide members on tools and processes\n\nYour skills and experience:\nSKILLS/COMPETENCY SPECIFICATION\nCompetency/Skill Requirements:\n- Excellent knowledge base of Quality Control & Quality Assurance\n- Good knowledge base of Project Management\n- Hand-on experience in testing mobile applications, especially Android apps\n- Be able to self-study & investigate technical issues in a certain period of time\n- High-level analytical skills\n- Critical & creative thinker\n- Be active & good at teamwork\n- Good at leadership (having team leading experience with team size 2~4 members is preferred)\n- Good at problem solving and communication skills\n- Knowledge of Payment domain is a plus\n\nLanguages:\n- English communication\n\nEducation Qualifications / Experience Requirements:\n- 5+ years of experience testing field\n\nWhy you\'ll love working here:\n- Work life balance, no OT, 15 days off\n- Chance to go onsite/other countries for training\n\nAttractive benefits:\n- Great salary package, annual performance review\n- Performance bonus\n- Full salary in probation\n- Social insurance on full salary from probation\n- Premium Health insurance covering for employees, lawful spouse, and unlimited number of children from probation\n- 15 days off annually, paid sick leaves, annual Heath Check-up\n- Working from Monday – Friday, from 9AM to 6PM, no OT\n- Annual company trip, quarterly team building activities, weekly Happy Hour\n- Equipment: Laptop, monitor\n- Free coffee and snack.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '21 Duy Tân, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(934, 353, 2, 'Mobile Developer (React Native, iOS, Android)', 'Top 3 reasons to join us\n- Môi trường làm việc thân thiện, chuyên nghiệp\n- Lương thưởng tương xứng năng lực làm việc\n- Có cơ hội phát triển bản thân\n\nJob description\n- Lập trình, phát triển các hệ thống, ứng dụng của Ngân hàng.\n- Tự phát triển hoặc phối hợp cùng các nhà cung cấp phát triển/ triển khai các giải pháp CNTT.\n- Quản lý, phát triển dịch vụ cho khách hàng trong và ngoài ngân hàng\n- Nghiên cứu, thử nghiệm, triển khai áp dụng các xu hướng công nghệ mới\n- Duy trì hoạt động của các sản phẩm dịch vụ trong phạm vi quản lý.\n- Lead các dự án Mobile (đặc biệt cả iOS và Android, React Native ), trực tiếp lập trình và hỗ trợ các thành viên trong nhóm lập trình gồm 03 - 06 thành viên\n- Tham gia phân tích nghiệp vụ, đề xuất giải pháp, phương án triển khai nhằm cải tiến, nâng cao hiệu quả của các dự án trong quá trình làm việc.\n- Lên timeline công việc, chia tasks cho các thành viên trong nhóm, giám sát và hỗ trợ các thành viên hoàn thành đúng cam kết.\n\nYour skills and experience\n- Tối thiểu 03 năm làm việc thực tế tại các công ty, dự án về lập trình (React Native).\n- Tối thiểu 1 năm kinh nghiệm làm việc với mỗi platform iOS – Android\n- Có kinh nghiệm xây dựng CI/CD cho mobile platform.\n- Nắm vững cách thức viết tích hợp Native Module, Native view giao tiếp với React Native. JavascriptEngine giao tiếp với native\n- Có kiến thức sử dụng state management, local storage SQLite, Shared Preference, nắm vững cơ chế hoạt động, kiến trúc của React Native và Flutter.\n- Có kiến thức và kinh nghiệm sử dụng thành thạo XCode, Android studio, các công cụ phân tích (Flipper, Dart devtool).\n- Đã tự đẩy được tối thiểu 02 ứng dụng lên 02 kho ứng dụng (AppStore, CHPlay).\n- Ưu tiên ứng viên có kinh nghiệm làm Backend (Spring boot, Java)\n- Ưu tiên ứng viên có kinh nghiệm web frontend (Reactjs, Angularjs, Vuejs)\n- Ưu tiên ứng viên kinh nghiệm trong mảng tài chính, ngân hàng\n\nWhy you\'ll love working here\n- HDBank tạo cảm giác nơi làm việc như là một ngôi nhà thứ hai để bạn thỏa sức sáng tạo và đam mê.\n- Thưởng 13,14 \n- Thưởng theo xếp loại \n- Bảo hiểm y tế, bảo hiểm tai nạn \n- Du lịch nghỉ mát hằng năm \n- Tăng lượng dịnh kì', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(935, 315, 2, 'Platform Manager (CDN ecosystems)', 'Job description\n\nPlatform Architecture & Strategic Initiatives\n- Lead platform initiatives in four pillars: CDN Optimization, Experience Platform, Engagement Platform, and Transcode System.\n- Drive strategy for CDN routing decisions based on cost, network condition, and real-time performance.\n- Define architecture and workflows for real-time A/B testing & feature flagging platforms used across product teams.\n- Oversee development of a centralized engagement platform across push, email, chat... personalized by user segmentation.\n- Collaborate with SRE to shift legacy transcoding infrastructure (e.g., Flussonic) to cutting-edge cloud-native solutions like BytePlus or self-hosted.\n\nTeam Building & Development\n- Recruit qualified personnel to meet organizational and technical requirements.\n- Build and mentor a multi-disciplinary team across backend, frontend, mobile, and QA.\n- Define, implement, and evaluate KPIs for direct reports to ensure alignment with team and company objectives.\n\nCross-team Collaboration\n- Coordinate with Product, Data, and Engineering stakeholders to ensure dynamic configurability without code-level intervention.\n- Provide technical consultation and support to development teams on platform-related challenges, ensuring alignment with scalability, security, and performance standards.\n- Prepare and present security and platform health reports to relevant stakeholders and senior management, offering insights and recommendations to inform strategic decisions.\n\nYour skills and experience\n- Graduated from college or higher in IT, Software Engineering, Computer Science, or a related field.\n- 7+ years of experience in software/platform engineering, with 2+ years in technical management.\n- Proven track record in building platform services or internal developer tools at scale.\n- Deep understanding of CDN ecosystems, routing logic, and cost optimization strategies.\n- Experience with A/B testing platforms and data-driven decision systems (e.g., Uber\'s XP, Optimizely, LaunchDarkly).\n- Familiarity with customer engagement tools (Braze, OneSignal, Firebase) and messaging pipelines.\n- Cloud experience (GCP, AWS, BytePlus CDN, Gcore) and containerized deployments (K8s, Docker).\n- Team collaboration and leadership skills; proactive in professional and personal development.\n- Ability to clearly articulate technical issues to non-technical stakeholders.\n\nWhy you\'ll love working here\n💰 Competitive Compensation\n13th-month salary, sign-on bonus, performance-based reviews, and attractive bonuses.\n🚀 Growth Opportunities\nAccess to training and advanced technologies.\n📱 Exciting Projects\nWork on leading entertainment apps and OTT platforms.\n🌟 Open Culture\nWe value ideas, creativity, and innovation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '222 Pasteur, Phường Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(936, 587, 2, 'Middle/Senior Quality Control Officer', 'Job Purpose:\n- Consult/Review project test strategy and test plan\n- Ensure product/project quality with deliverables\n- Continuously improve the test process\n- Develop skills and ensure resources for project implementation\n\nJob Requirements:\n- Define/suggest a test strategy for the project\n- Review Test plan, test cases/checklist/scenarios\n- Analyze business requirements, changes, and impacts\n- Design, and develop a test plan, and test cases, and define business scenarios.\n- Execute test, log a bug, and create a test report\n- Communicate with the dev to verify the bug\n- Coordinate and communicate testing timelines to the Test Manager Project Manager and related stakeholders.\n- Training, sharing testing skills or testing knowledge Monitor testing progress\n\nYour skills and experience:\n1, Qualification: Graduate from the University of IT or finance field\n2, Experience:\n- At least 2 years experience in Insurance or Banking testing\n- Experience in developing test plans, test cases, reports\n- Strong written and verbal communications skills\n- Experience working on different development lifecycles: Agile scrum, Waterfall\n- Strong problem-solving skills\n- Strong quality orientation\n- Strong leadership skill\n3, Certification: ISTQB Foundation\n4, Technical Competencies:\n- Software development:\n+ Have knowledge about software development lifecycle\n+ Experience working on different development lifecycles: Agile, Scrum, Waterfall\n- Software Testing:\n+ Have knowledge about software testing lifecycle\n+ Have knowledge about API testing, SQL testing\n- Tools & languages: Have knowledge about defect management, test management\n\nReasons to join us:\n- Competitive salary and annual package\n- MIC Premium Healthcare, Life & Cancer Insurance\n- 15 days for annual leave & wellness allowance\n\nWhy you\'ll love working here:\nBeing an Amazers at MBAL, you are offered:\n- No working on the weekends (5 working days/week from Monday to Friday) and no overtime\n- Competitive salary with annual review and performance bonus\n- 100% official salary during the probation period\n- MIC Premium Healthcare Insurance for each employee with his/her 03 dependents\n- Provide Life Insurance & Cancer Insurance for the company\'s members\n- Annual leave: 15 days/year\n- Outstanding Wellness allowances\n- Lunch/Mobile/Travel allowances\n- Sponsored training and self-development opportunities (English, PMP, CSM, ITIL...)\n- Modern facilities for convenient working.\n- Specific benefits on the holidays of the Union (Company birthday, New Year\'s holidays, Mid-Autumn Festival, Vietnamese Family\'s Day - June 28, Vietnamese Children\'s Day - June 1, Women\'s Day - March 8 & October 20, ...)\n- Exciting company outings/events and team-building activities\n- Supportive, international, dynamic working environment and talented, culturally diverse teams\n- A large pantry full of snacks, drinks, and seasonal fresh fruit\n\nTo create the HAPPINESS together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, tòa nhà MB – 21 Cát Linh, phường Cát Linh, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(937, 588, 2, 'Kĩ sư an toàn bảo mật, an toàn thông tin (Linux/Unix)', 'Top 3 reasons to join us\n- Mức lương tốt\n- Chủ động trong công việc\n- Đào tạo trong và ngoài nước\n\nJob description\n- Có kinh nghiệm tham gia trực tiếp cấu hình, quản trị và vận hành các thiết bị và hệ thống bảo mật, bao gồm:\n- Tường lửa (Firewall): Check Point, Fortinet, Palo Alto\n- Chống tấn công từ chối dịch vụ (Anti-DDoS): Radware DefensePro, Arbor\n- Tường lửa ứng dụng web (WAF): Imperva SecureSphere, F5 ASM, AWS WAF\n- Hệ thống phát hiện và phản hồi mở rộng (XDR): Trend Micro Vision One, CrowdStrike Falcon XDR, SentinelOne Singularity XDR, Sophos Intercept X, và các nền tảng XDR tích hợp khác.\n- Quản lý tài khoản đặc quyền (PAM): CyberArk, BeyondTrust\n- Hệ thống giám sát và phân tích nhật ký bảo mật (SIEM): IBM QRadar, Splunk, ELK, ArcSight\n- Giám sát, phát hiện và xử lý sự cố an ninh thông tin.\n- Phối hợp với các bộ phận kỹ thuật khác xử lý sự cố hệ thống và dịch vụ.\n- Cập nhật, rà soát và hoàn thiện các quy trình, chính sách và báo cáo tuân thủ bảo mật theo chuẩn ISO 27001, NIST, PCI-DSS.\n- Thực hiện bảo trì, cập nhật bản vá bảo mật định kỳ hoặc đột xuất cho các hệ điều hành và ứng dụng nền tảng.\n- Nghiên cứu, thử nghiệm và đề xuất giải pháp bảo mật mới.\n- Phối hợp cùng nhà thầu thực hiện kiểm thử xâm nhập (Pentest) định kỳ, triển khai hệ thống bảo mật mới.\n- Tham gia tổ chức đào tạo nâng cao nhận thức bảo mật cho cán bộ, nhân viên.\n\nYour skills and experience\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, An toàn thông tin, Điện tử viễn thông. Ưu tiên ứng viên từ Đại học Bách Khoa, Đại học Công nghệ, Học viện Bưu chính Viễn thông,…\n- Nắm vững kiến thức về mạng máy tính (tối thiểu tương đương CCNA).\n- Thành thạo hệ điều hành Linux/Unix:\n- Làm việc tốt với các bản phân phối như Red Hat, CentOS, Ubuntu. Quản trị dịch vụ nền tảng, phân quyền hệ thống, xử lý sự cố với các công cụ như: journalctl, auditd, tcpdump, lsof, strace, netstat, htop,…\n- Có kinh nghiệm triển khai và vận hành Firewall Check Point, WAF Imperva, Anti-DDoS,…\n- Ưu tiên ứng viên có kinh nghiệm với SIEM (ELK, Splunk, QRadar), XDR, PAM (CyberArk).\n- Có khả năng viết hoặc tham gia xây dựng báo cáo kiểm toán bảo mật là lợi thế.\n- Ưu tiên ứng viên có các chứng chỉ bảo mật sau (có thể đang học hoặc đã đạt được):\n- CompTIA Security+ – , Check Point CCSA / CCSE , CEH, CISSP, OSCP, GCIH ....\n\nWhy you\'ll love working here\n- Môi trường làm việc chuyên nghiệp, năng động, nhiều cơ hội phát triển.\n- Được đào tạo chuyên sâu và hỗ trợ thi các chứng chỉ quốc tế về an toàn thông tin.\n- Cơ hội thăng tiến lên vị trí Team Leader, Chuyên gia bảo mật cấp cao.\n- Được tham gia BHXH, BHYT, BHTN đầy đủ ngay khi kết thúc thử việc.\n- Lương, thưởng cạnh tranh, tăng lương định kỳ theo hiệu suất.\n- Chế độ nghỉ phép năm, khám sức khỏe định kỳ, du lịch, nghỉ thai sản đầy đủ theo quy định của công ty và pháp luật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 16, tòa nhà LPB 210 Trần Quang Khải, Phường Tràng Tiền, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(938, 589, 2, 'Senior Manual QA (QA QC, Tester, Agile)', 'We are seeking a skilled QA Engineer to join our team. This role supports testing across Windows applications, mobile apps, devices, or web, with a focus on a Windows-based video capture application integrated with a cloud service. You will work independently, applying your Windows testing experience to ensure quality based on requirements. You’ll collaborate with developers and stakeholders to deliver reliable software, leveraging your expertise without needing detailed “how-to” training.\n\nResponsibilities:\n- Develop and execute test plans and cases, performing functional, regression, integration, performance, and exploratory testing.\n- Identify, document, and track defects in tools like Jira, collaborating with developers and QA peers to resolve issues.\n- Work with cross-functional teams to define requirements and participate in Agile/Scrum ceremonies (sprint planning, stand-ups, retrospectives).\n- Track quality metrics and provide concise reports on test results, coverage, and system quality.\n- Manage task priorities, recommend trade-offs when needed, and contribute to improving QA processes and tools.\n\nRequirements:\n- 3-5 years of experience in software testing or quality assurance, preferably on Windows platforms.\n- In-depth knowledge of the Windows operating system and proficiency with its tools (e.g., Event Viewer, CMD/PowerShell, Resource/Performance Monitor).\n- Basic understanding of networking concepts and troubleshooting (e.g., private vs. public networks, NAT, firewalls, ping, tracert, IPv4).\n- Expertise in manual testing with a strong grasp of testing methodologies, including functional, regression, and performance testing.\n- Good at written and verbal communication skills in English.\n- Familiarity with Software Development Life Cycle (SDLC) and Agile methodologies, along with tools like Jira.\n- Strong analytical mindset and problem-solving abilities.\n\nWorking Location:\nETOWN CENTRAL BUILDING, 07 - 11 Doan Van Bo Street, District 4, HCMC.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No. 16-18 Xuan Dieu, Ward 4, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(939, 590, 2, 'IT Team Leader (Java Spring Boot, ReactJS)', 'Top 3 reasons to join us\n- Mức lương hấp dẫn\n- Dự án và công nghệ thử thách, thú vị\n- Môi trường làm việc năng động, tự do sáng tạo\n\nJob description\n- Hiểu biết về các công cụ, quy trình và kiến trúc phát triển phần mềm\n- Hiểu biết sâu sắc về HTML / CSS, Java, JavaScript\n- Làm việc tốt với Springboot, Spring Security, ReactJS\n- Làm việc tốt với một trong các hệ cơ sở dữ liệu SQL/Oracle\n- Có hiểu biết về mô hình MVC, kiến trúc SOA, Microservices, REST Apis\n- Trải nghiệm với các ứng dụng web đa tầng hoặc hướng dịch vụ\n- Có kinh nghiệm về ReactJS/VueJS hoặc AngularJS và hệ sinh thái của nó\n- Có kinh nghiệm làm việc với Java Spring, UI/UX  / Mobi App / IoT là 1 lợi thế.\n- Có kinh nghiệm về thực hành và công cụ kiểm tra\n- Có kinh nghiệm trong kiến trúc microservices\n- Có khả năng làm việc theo nhóm, quản lý dự án đúng tiến độ.\n- Tinh thần trách nhiệm, kỹ năng giao tiếp và tinh thần đồng đội\n- Sẵn sàng học hỏi và xây dựng sự hiểu biết sâu sắc\n- Có khả năng làm việc độc lập và chịu áp lực\n- Niềm đam mê phát triển phần mềm, các xu hướng mới và công nghệ trong CNTT\n\nYour skills and experience\n- Role: senior fullstack (có kinh nghiệm IT > 3 năm)\n- Technical: Java Spring Boot, Reactjs (Nextjs), Oracle Database, có kinh nghiệm quản lý server cụ thể là linux centos\n- Có kinh nghiệm làm việc với TypeScript\n- Hiểu biết về các công cụ, quy trình và kiến trúc phát triển phần mềm\n- Hiểu biết sâu sắc về HTML / CSS, Java, JavaScript\n- Làm việc tốt với Springboot, Spring Security, ReactJS.\n\nWhy you\'ll love working here\n- Mức lương thỏa thuận, đãi ngộ xứng đáng: từ 30 - 50M\n- BHYT, BHXH đầy đủ theo quy định của nhà nước\n- Dự án và công nghệ thử thách, thú vị\n- Môi trường làm việc vui vẻ, năng động, tự do sáng tạo\n- Được trang bị cơ sở vật chất đầy đủ\n- Nhận offer đi làm ngay\n- Địa chỉ trụ sở: Tầng 19, Tòa nhà Indochina Park Tower, Số 4 Nguyễn Đình Chiểu, Phường Đa Kao, Quận 1, Tp.HCM\n- Địa chỉ làm việc: 178/8 Phan Đăng Lưu, Phường 3, Quận Phú Nhuận, Tp. HCM', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '178/8 Phan Đăng Lưu, Phường 4, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(940, 258, 2, 'VTS - Kỹ Sư Giải Pháp Nghiệp Vụ (Business Analyst)', 'Top 3 reasons to join us\n- Dẫn đầu thị trường\n- Cơ hội thử thách và phát triển bản thân\n- Môi trường làm việc năng động\n\nJob description\nGia nhập “vũ trụ” công nghệ Viettel, nơi bạn không chỉ được “đắm chìm” trong hàng loạt công nghệ xịn xò như Big Data, AI, IoT, AR/VR, Cloud, Blockchain… mà còn được trao cơ hội thực hiện sứ mệnh quan trọng: “Chung tay cùng Chính phủ kiến tạo – Chính phủ số”, đồng hành với doanh nghiệp và người dân giải quyết các vấn đề cấp bách của xã hội, hướng tới một cuộc sống tốt đẹp hơn cho mọi người.\nTại VTS (Tổng Công ty Giải pháp Doanh nghiệp Viettel), bạn sẽ được hiện thực hóa những ý tưởng táo bạo, tham gia vào các dự án công nghệ hàng đầu và phát triển giải pháp đột phá cho tương lai số. Đây chính là nơi khơi dậy đam mê, thúc đẩy sáng tạo và chắp cánh cho mọi ước mơ công nghệ của bạn. Sẵn sàng trở thành “ngôi sao sáng” trên hành trình chuyển đổi số và cùng Viettel tạo nên dấu ấn trong cuộc cách mạng công nghiệp 4.0? Let’s go!\n\nBạn sẽ làm gì?\n- Xây dựng giải pháp nghiệp vụ (đối với dự án nâng cấp có nghiệp vụ cụ thể, rõ ràng)\n  - Khảo sát nhu cầu, phân tích và mô hình hóa nghiệp vụ khách hàng\n  - Xây dựng tài liệu phân tích nghiệp vụ (PTYC), làm Prototype\n  - Chốt thống nhất với khách hàng về yêu cầu bài toán\n  - Xây dựng tài liệu giải pháp và thiết kế chi tiết tính năng về mặt người dùng theo yêu cầu của Trưởng sản phẩm hoặc khách hàng. (Chi tiết các trường dữ liệu, các trường hợp ràng buộc, ngoại lệ)\n  - Giải đáp, trao đổi các thắc mắc về mặt nghiệp vụ của đội dự án.\n- Quản lý dự án\n  - Cập nhật tài liệu liên quan trong dự án theo quy trình.\n  - Quản lý và lưu trữ các yêu cầu thay đổi theo đúng quy trình.\n  - Hỗ trợ AM, PM nghiệm thu sản phẩm/hệ thống với khách hàng\n  - Tính toán nỗ lực, chi phí thực hiện cho các yêu cầu nghiệp vụ.\n\nYour skills and experience\n- Bằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng, Kinh tế hoặc tương đương.\n- Ngoại ngữ: Đọc hiểu tài liệu tiếng Anh ngon lành. Ưu tiên có chứng chỉ TOEIC 550+ (hoặc IELTS, TOEFL tương đương).\n- Kiến thức, kinh nghiệm:\n  - Có tối thiểu 1 năm kinh nghiệm ở vị trí ứng tuyển.\n  - Có kiến thức về các kĩ thuật phân tích nghiệp vụ, mô hình hóa các luồng nghiệp vụ như: các mô hình chức năng nghiệp vụ, mô hình dữ liệu quan hệ, ngôn ngữ UML, tạo Use case, BPMN,…\n  - Biết cách xây dựng prototype của sản phẩm/ứng dụng.\n  - Có khả năng giao tiếp, diễn đạt tốt\n  - Tư duy phản biện, kỹ năng đàm phán\n  - Tổ chức các cuộc họp.\n- Tinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội.\n\nWhy you\'ll love working here\n- Lương cạnh tranh: Thu nhập “ổn áp”, xứng đáng với năng lực và kinh nghiệm.\n- Đầy đủ các khoản thưởng: Thưởng lễ Tết, quà tặng, du lịch nghỉ mát, hỗ trợ ăn trưa, cước điện thoại…\n- Nghỉ phép linh hoạt: 12 ngày phép + 3 ngày nghỉ mát + 1 ngày sáng tạo mỗi năm.\n- Bảo hiểm toàn diện: Hưởng đầy đủ BHXH, BHYT, BHTN theo quy định, cộng thêm gói bảo hiểm riêng từ Viettel.\n- Môi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo “bung nóc”.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Tran Huu Duc, Hanoi, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(941, 295, 2, 'ReactJS Developer (JavaScript, React Native)', 'Job description\n- Chịu trách nhiệm phát triển, kiểm thử UI/UX của ứng dụng, đảm bảo ứng dụng đẹp mắt và thuận tiện cho người dùng cuối \n- Hợp tác với các thành viên khác hoàn thành dự án đúng yêu cầu, đúng thời gian - Phát triển code và thư viện có thể tái sử dụng trong tương lai \n- Tối ưu ứng dụng về tốc độ và quy mô \n- Hỗ trợ người dùng cuối \n- Nâng cấp, cải tiến các chương trình hiện tại \n- Xây dựng tài liệu kỹ thuật về phát triển hệ thống và tài liệu sử dụng \nYour skills and experience\n- Có 4 năm kinh nghiệm trong Front-end \n- Sử dụng thành thạo Javascript, HTML , CSS , responsive design \n- Có 2 năm kinh nghiệm lập trình React/ React Native \n- Có kinh nghiệm với Angular/ Vue là một lợi thế \n- Có kinh nghiệm ưu hiệu năng ứng dụng (tốc độ, khả năng mở rộng, Memory Usage. CPU Utilization, ) là một lợi thế \n- Có kinh nghiệm với Redux/ Flux/ Recoil hoặc các thư viện tương đương là một lợi thế là một lợi thế \n- Có good sense về UI/UX, tạo trải nghiệm tốt cho người dùng \n- Có kinh nghiệm với Webpack, Vite là một lợi thế \n- Có kinh nghiệm với triển khai trên môi trường đám mây, môi trường ảo hóa là một lợi thế - Có khả năng viết code sạch, và viết tài liệu mô tả đầy đủ \n- Có kinh nghiệm với native iOS / Android app development là một lợi thế - Có kinh nghiệm phát triển ứng dụng cho ngân hàng, bảo hiểm, thương mại điện tử - Có khả năng tư duy phân tích và giải quyết vấn đề \n- Có khả năng sử dụng tiếng Anh tốt cho công việc \n- Có tinh thần trách nhiệm, tự chủ, chịu được áp lực cao trong công việc, tác phong làm việc chuyên nghiệp, có khả năng làm việc độc lập và theo nhóm; \n- Ham học hỏi, mong muốn khám phá năng lực của bản thân. \n- Yêu thích các công nghệ mới, lĩnh vực mới', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phòng 605, Tầng 6, tháp B, tòa nhà Hongkong Tower, 243A la thành, láng thượng, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(942, 396, 2, 'Kỹ sư CNTT', 'Job description\n- Khảo sát, thiết kế, lên dự toán, bóc tách khối lượng các dự án công nghệ thông tin. Bao gồm: Camera giám sát, Thiết bị an ninh, Tổng đài, Thiết bị báo cháy, Kiểm soát vào ra, Báo động ....\n- Hỗ trợ giám sát, triển khai thi công các công trình công nghệ thông tin.\n- Hỗ trợ kỹ thuật khách hàng\n- Các công việc khác theo sự chỉ đạo của Giám đốc.\n\nYour skills and experience\n- Tốt nghiệp Đại học chyên ngành CNTT, viễn thông, điện tử, kỹ sư phần mềm,....hoặc các chuyên ngành khác có liên quan.\n- Có hiểu biết về các hệ thống CNTT, phần mềm, phần cứng, mạng máy tính là một lợi thế\n- Có ít nhất 1 năm kinh nghiệm ở vị trí tương đương\n- Khả năng sử dụng Tiếng Anh tốt là một lợi thế\n\nWhy you\'ll love working here\n- Mức lương: Thỏa thuận theo năng lực, Upto 15 triệu\n- Thời gian làm việc: Từ thứ Hai – Thứ bảy (nhưng trong một tháng chỉ làm việc 2 ngày thứ Bảy)\n• Sáng: 8h00 -12h00\n• Chiều: 13h30 – 17h30\n- Được tham gia các chế độ BHXH, BHYT, BHTN, ... theo quy định của Công ty và nhà nu̇ớc\n- Thưởng hiệu quả công việc, Lễ, Tết, sinh nhật, lương tháng 13,...\n- Được tham gia các sự kiện của Công ty như: Teambuilding, sinh nhật, YEP,...\n- Thưởng năng suất làm việc, hiệu quả công việc, trách nhiệm,...\n- Môi trường làm việc chuyên nghiệp, trẻ, năng động, phát triển bản thân, ham học hỏi, nhiệt huyết,...\n- Có cơ hội tham gia các dự án lớn của Công ty, đu̟ợc tiếp xúc với nhiều hãng công nghệ hàng đầu thế giới,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'SN77 TT3D KĐT mới Phùng Khoang, Văn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(943, 289, 2, 'Chuyên viên An ninh bảo mật CNTT (Security)', 'Top 3 reasons to join us\n- Môi trường làm việc năng động\n- Chế độ phúc lợi đầy đủ của Ngân hàng\n- Thu nhập xứng đáng, thưởng tối thiểu 2 tháng,dự án\n\nJob description\n- Quản trị, giám sát và vận hành hệ thống an ninh bảo mật của VRB, bao gồm: tường lửa (Firewall), hệ thống phát hiện và ngăn chặn xâm nhập (IDS/IPS), hệ thống quản trị sự kiện bảo mật (SIEM), bảo mật endpoint, DLP, anti-virus,.... \n- Xây dựng, thiết lập và tối ưu hóa các chính sách, cấu hình và quy tắc bảo mật trên các hệ thống CNTT, đảm bảo an toàn hệ thống, dữ liệu và người dùng trong toàn ngân hàng. \n- Tham gia lập kế hoạch, thực hiện kiểm tra, đánh giá và phân tích rủi ro an toàn thông tin định kỳ hoặc đột xuất đối với các hệ thống CNTT, ứng dụng nghiệp vụ và hạ tầng mạng tại VRB. Phối hợp xử lý và điều tra các sự cố an ninh mạng, bao gồm phát hiện, phân tích nguyên nhân, khoanh vùng, ngăn chặn, khắc phục hậu quả và báo cáo sự cố bảo mật.\n- Nghiên cứu, đề xuất và triển khai các giải pháp bảo mật mới, công nghệ an ninh mạng tiên tiến, đáp ứng yêu cầu phát triển hệ thống CNTT của VRB.\n- Tham gia xây dựng, rà soát, cập nhật các chính sách, quy trình, quy định và tài liệu nội bộ về an toàn thông tin, phù hợp với quy định của pháp luật, Ngân hàng Nhà nước và tiêu chuẩn quốc tế (ISO 27001...).\n- Tham gia triển khai các dự án CNTT tại VRB.\n\nYour skills and experience\nTrình độ đào tạo: \n- Tốt nghiệp Đại học trở lên các trường trong nước/ nước ngoài\n- Chuyên ngành: Công nghệ thông tin, Tin học ứng dụng, Khoa học máy tính, Kỹ thuật phần mềm, Điện tử viễn thông, Kỹ thuật thông tin\nYêu cầu kinh nghiệm: \n- Hiểu biết về các công nghệ, công cụ và hệ thống bảo mật thông dụng: Firewall, IDS/IPS, SIEM, Endpoint Security, DLP, VPN, MFA, PKI…\n- Hiểu biết về các kỹ thuật, phương pháp kiểm tra đánh giá an toàn bảo mật hệ thống, ứng dụng (White box, grey box, black box testing).\n- Có khả năng phân tích, đánh giá và quản trị rủi ro an toàn thông tin trong hệ thống CNTT phức tạp.\n- Thông thạo các kỹ thuật tìm kiếm, phân tích và khai thác điểm yếu, kỹ thuật hacking, các biện pháp phòng/chống, khắc phục lỗi.\n- Có các chứng chỉ trong lĩnh vực an ninh thông tin (CompTIA Security+ / CySA+, CEH, CHFI, CISSP, CISA, ISO/IEC 27001 hoặc tương đương hoặc cao hơn) là lợi thế tuyển dụng.\nNgoại ngữ: Có khả năng nói, viết bằng tiếng Anh. Chứng chỉ tiếng Anh yêu cầu: tối thiểu tương đương trình độ B1 trở lên theo khung tham chiếu trình độ ngoại ngữ chung Châu Âu.\nTuổi: Không quá 40 tuổi.\nYêu cầu khác:\n- Chịu được áp lực công việc, sẵn sàng làm ngoài giờ khi có sự cố cần xử lý.\n- Tinh thần trách nhiệm cao, bảo mật tuyệt đối, có khả năng làm việc độc lập và xử lý sự cố trong tình huống áp lực.\n- Nghiêm túc, cầu tiến, chịu khó, nhiệt tình trong công việc.\n\n- Ưu tiên ứng viên nộp hồ sơ ứng tuyển bằng Tiếng Anh.\n\nWhy you\'ll love working here\n- Hưởng lương hấp dẫn, phù hợp với năng lực và kinh nghiệm.\n- Làm việc và phát triển trong môi trường trẻ trung, năng động và luôn giàu nhiệt huyết\n- Có cơ hội thăng tiến cao, được làm việc trong môi trường thân thiện, sáng tạo và phát triển.\n- Được tham gia các chương trình đào tạo nghiệp vụ của Ngân hàng.\n- Được chi bổ sung thu nhập theo kết quả làm việc, vị trí công việc và hưởng các cơchế khuyến khích theo quy định của VRB.\n- Du lịch - Nghỉ dưỡng - Team building hằng năm.\n- Khám sức khỏe định kỳ và chế độ bảo hiểm sức khỏe do VRB tài trợ.\n- Các phúc lợi hiếu, hỷ, tiền mừng sinh nhật, thai sản, …', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '75 Trần Hưng Đạo, Hoàn Kiếm, Hà Nội, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(944, 591, 2, 'Full Stack Developer (Golang, ReactJS)', 'At OplaCRM, we are not building rockets to the moon, we develop innovative software products that both our customers and internal teams love. As a product development company with high ambitions and elite teams, we empower our developers to take ownership and execute tasks with minimal guidance.\n\nJob Description\nAs a Full Stack Developer, you will:\n- Develop and maintain scalable web applications using Golang (Back End, ReactJS (Front End), ReactJS (Web) and React Native (Mobile)\n- Collaborate with cross-functional teams to design, develop, and deploy new features.\n- Ensure the performance, security, and responsiveness of applications.\n- Work with databases, particularly PostgreSQL, and integrate with Hasura.\n- Deploy and maintain applications using AWS, Google Cloud services.\n- Continuously improve the system architecture and development practices.\n\nYour skills and experience\nWe are looking for candidates who:\n- Have 1-3 years of experience working as a Full Stack Developer with Golang and ReactJS.\n- Are familiar with Hasura, PostgreSQL, and AWS, Google Cloud services (a plus).\n- Can work independently and take ownership of tasks with minimal supervision.\n- Are problem-solvers, eager to learn, and thrive in a fast-paced environment.\n- Have strong communication skills and a collaborative mindset.\n\nWhy you\'ll love working here\n- Work in an ambitious, fast-growing product company.\n- Engage with cutting-edge technologies and diverse projects.\n- Collaborate with a team of skilled and passionate engineers.\n- Competitive salary and benefits package.\n- A dynamic and flexible work environment that values innovation and growth.\n- Location: Sarina A0011, Thu Duc, HCM.\n- Working time: 9:00 AM - 6:00 PM.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Van Phuc City, 14 Bis Street No.36, Hiep Binh Phuoc Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(945, 356, 2, 'Junior Network Engineer', 'Top 3 reasons to join us\n1. Attractive salary, benefits, hybrid working\n2. Technical training sessions (internal – external)\n3. PVI Healthcare insurance\n\nJob description\n- Is responsible for the continuous standardization of network-related implementation and policies.\n- Developing, optimizing and monitor the network system to meet the development needs of the Company and Clients.\n- Develop, implement and control processes and controlling measures to ensure information security according to ISO 9001:27001.\n- Report system status to manager & propose solutions to handle if necessary. Including upgrade/repair/replacement to ensure stable operation of the system.\n- Helpdesk end users.\n\nYour skills and experience\nMUST-HAVE SKILLS:\n- At least 1 year of experience in networking management.\n- Knowledge on the fundamentals such as IPv4/IPv6 addressing, VLAN, switching and routing configurations.\n- Experience in designing, implementing, operating and troubleshooting networking devices and technologies (Structured Cabling, WAN, LAN, Network Security, Wireless) in standardized operating environment.\n\nNICE TO HAVE:\n- Firewall IDS/IPS rules optimization, load balancing of applications.\n- Network Access Control (NAC), Public Key Infrastructure (PKI), Cybersecurity threats and mitigations, Content Distribution Network (CDN).\n\nWhy you\'ll love working here\nCompetitive Salary and Brilliant Health Benefits:\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus.\n- Bonus programs for candidate referral, technical article writing.\n- Interest-free loan support for personal plan.\n- Allowance for sickness, maternity, paternity and periodic health examination.\n- PVI healthcare program.\n- The staff of the quarter and year reward.\n\nProgressive and Fun Working Environment:\n- A professional English-speaking working environment with Agile – Scrum model.\n- Hybrid Working Model: Flexible working time and WFH support.\n- Surrounded by friendly, open-minded, young and supportive colleagues.\n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …).\n\nValuable Training:\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...).\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '17th Floor, 36 Tran Quoc Toan, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(946, 238, 2, 'Solution Architect (Java)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Chủ trì xây dựng thiết kế giải pháp cho các sản phẩm, đáp ứng nhu cầu nghiệp vụ và phù hợp tiêu chuẩn kiến trúc, công nghệ:\n  - Tham gia làm rõ đầu bài và tư vấn cho nghiệp vụ, BA về yêu cầu đầu bài\n  - Xây dựng thiết kế tổng thể giải quyết bài toán nghiệp vụ\n  - Phối hợp với các AA xây dựng thiết kế chi tiết để giải quyết bài toán nghiệp vụ\n  - Phối hợp với các AA kiểm soát các phát triển tuân thủ thiết kế\n- Tham gia xây dựng Kiến trúc tham chiếu của MB: Tham gia team cùng với EA, AA xây dựng các mẫu thiết kế, cây quyết định, tài liệu hướng dẫn, mã nguồn mẫu đáp ứng các tiêu chuẩn, nguyên tắc thiết kế, kiến trúc\n- Tham gia xây dựng các quy hoạch:\n  - Cung cấp các thông tin, thực hiện khảo sát hiện trạng phục vụ quy hoạch\n  - Tham gia đánh giá và đề xuất giải pháp quy hoạch\n- Các công việc khác:\n  - Tham gia review sự cố các hệ thống/giải pháp được phân giao.\n  - Phối hợp với các bên liên quan để đề xuất và xác định kích thước (sizing) hệ thống.\n  - Tham gia thử nghiệm, đánh giá công nghệ mới\n\nYour skills and experience\n- Tốt nghiệp Đại học ngành Công nghệ thông tin, Toán học, Điện tử viễn thông tại các trường đại học uy tín như Đại học Bách Khoa, Đại học Quốc gia, … hoặc có chứng chỉ lập trình viên quốc tế tương đương.\n- Tối thiểu 04 năm kinh nghiệm lập trình và thiết kế phần mềm\n- Có kiến thức về nhiều ngôn ngữ: Java,go, python …\n- Hiểu biết tốt về các về các framework : Spring, Angular, React , Go-zero ....\n- Hiểu biết tốt về các dòng database : Oracle, MySQL, Mongodb …\n- Hiểu biết tốt về các ứng dụng nền tảng và kiến trúc triển khai: Redis, kafka, GG ...\n- Hiểu biết tốt về các mô hình kiến trúc : Monolitic, Microservice, Serverless, Event-Driven ...Các mô hình kiến trúc khác: Mini fontend, Miniapp ...\n- Am hiểu về thiết kế ứng dụng trên nhiều khía cạnh như tích hợp, bảo mật, quy hoạch mạng …\n- Hiểu biết và có kiến thức thực tế với các mô hình phát triển như waterfall, agile ...\n- Có kinh nghiệm làm việc trên các nên tảng private cloud, public cloud, các nền tảng containerization\n- Vị trí mở với các senior dev có định hướng chuyển sang SA\n- Ngoại ngữ (Tiếng Anh) - TOEIC tối thiểu 550\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n  - Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n  - Du lịch nghỉ dưỡng hàng năm\n  - Khám sức khỏe định kì\n  - Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n  - Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n- Cơ hội nghề nghiệp và phát triển bản thân:\n  - Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n  - Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n  - Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n  - Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n- Môi trường làm việc lý tưởng với:\n  - Những người cộng sự thân thiện và tài năng\n  - Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(947, 356, 2, 'Senior Fullstack NodeJS Developer (ReactJS, Typescript)', 'Top 3 reasons to join us\n- Attractive salary, benefits, hybrid working\n- Technical training sessions (internal – external) \n- PVI Healthcare insurance\n\nJob description\n- Analyze requirements and design software system features.\n- Develop and maintain software systems.\n- Recommending and implementing improvements to processes and technologies\n- Developing high-performance applications by writing testable, reusable, and efficient code\n- Review code and work output of other team members.\n- Train and support other team members.\n- Collect lessons learned, best practices, and new knowledge from experience and incorporate them into the company knowledge base.\n\nYour skills and experience\nMUST-HAVE SKILLS:\n- At least 4 years of experience in NodeJS/ReactJS and its ecosystem.\n- Proficiency in TypeScript.\n- Strong understanding of RESTful APIs and web services.\n- Experience with database systems such as MongoDB, PostgreSQL, or MySQL.\n- Experience with real-time processing and concurrency.\n- Understanding of system architecture design.\n- Knowledge and application of programming principles and design patterns.\n- Familiarity with version control systems, particularly Git.\n- Knowledge of software development best practices, including code reviews, testing, and CI/CD.\n- Excellent problem-solving skills and attention to detail.\n- Ability to work collaboratively in a team environment.\n- Good communication skills in English.\n\nNICE TO HAVE:\n- Experience with LLMs, Cursor, Github Copilot,...\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- Experience with cloud platforms such as AWS, Azure, or Google Cloud.\n- Knowledge of containerization technologies like Docker and Kubernetes.\n- Familiarity with microservices architecture.\n- Experience with Agile/Scrum methodologies.\n- Knowledge of serverless computing (e.g., AWS Lambda, Azure Functions).\n- Experience with GraphQL.\n- Familiarity with WebSockets for real-time communication.\n- Experience with NestJS framework.\n- Knowledge of Prisma ORM.\n- Familiarity with message brokers like RabbitMQ or Kafka.\n- Understanding of CI/CD tools like Jenkins, GitHub Actions, or GitLab CI/CD.\n- Experience working in healthcare and logistics domains.\n\nWhy you\'ll love working here\nCompetitive Salary and Brilliant Health Benefits\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan \n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program \n- The staff of the quarter and year reward\nProgressive and Fun Working Environment\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support. \n- Surrounded with friendly, open-minded, young and supportive colleagues \n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\nValuable Training\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Orchard Parkview, 130 – 132 Hong Ha, Ward 9, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(948, 428, 2, 'Senior AI Engineer (Python - Up to $4000)', 'Top 3 reasons to join us: Competitive salary, Premium health care package, 7 working hours/day.\n\nJob description: Domain: Financial Service, Crypto network, EC platform, AI avatar, AI chatbot, Game, Decentralize.\nTech-stack: Python.\nUnderstand the core principles of machine learning and AI model operations.\nEvaluate, select, and integrate pre-trained AI models (computer vision, NLP, speech, recommendation, LLM, etc.) into business applications.\nDevelop AI-powered backend services, APIs, and microservices to serve AI models.\nBuild scalable pipelines for data preprocessing, model inference, and post-processing.\nWrite clean, maintainable, and efficient programming code.\nContinuously monitor and optimize system performance and model behavior.\nTroubleshoot and debug applications.\nStay updated with industry trends and propose innovative ideas for new features and improvements.\n\nYour skills and experience: Bachelor’s or Master’s degree in Computer Science, Software Engineering, or a related field from a Top university. Solid understanding of how AI models work: supervised learning, unsupervised learning, deep learning, transfer learning, etc. Experience working with popular pre-trained models and frameworks (Hugging Face, OpenAI API, TensorFlow Hub, PyTorch Hub, Azure AI, Google AI, AWS AI, etc.). Proficient in Python and key data science packages (NumPy, Pandas, etc.). Experience developing backend services using REST API, FastAPI, Flask, or similar frameworks. Experience working with real-time systems (WebSockets, streaming data). Familiarity with deploying models on cloud platforms (AWS, GCP, Azure) or edge devices. Experience with containerization (Docker) and orchestration (Kubernetes) is a plus. Understanding of basic MLOps concepts: model versioning, monitoring, and retraining workflows. Strong problem-solving skills and the ability to translate business needs into technical solutions. Have good communication skills in English, especially in reading and writing technical documentation (Equivalent to IELTS 5.5).\n\nPersonality requirements: Hard working, responsible, strong interpersonal and communication skills. Problem-solving mindset and ability to adapt A.I model for practical applications. Ability to work independently and teamwork, can work under high pressure. Ready to work overtime.\n\nWhy you\'ll love working here: Working hours: 9:00 - 17:00 (5 days per week); Breaking time: 12:00-13:00. Modern working equipment (Macbook,...). Performance Review: 2 times/year based on employee\'s performance and contribution; Well-equipped with insurance package as stated by Labor code. Premium PVI Health Insurance Package for all members. Transportation allowance and free parking included. Technical seminars and workshops annually. Free snack, coffee, tea available. Variety of corporate events: weekly tea-break, monthly birthday parties, quarterly team building to New Year party, company trip etc. Friendly, open and fast-paced environment where every idea is welcomed. Other benefits as per stated in Vietnamese Labor Law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 3, The Loop Building, 241 Xuan Thuy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(949, 592, 2, 'Middle/Senior Back End Developer (Java)', 'Top 3 reasons to join us\n- Hybrid Working style and Flexible working time\n- Competitive salary, bonus, expenses and allowances\n- 15 days of paid leave + Health Care Insurance\n\nJob description\n- Developing and implementing features relevant to Backend side with Agile Scrum Methodology\n- Maintaining and improving performance of existing systems with flexible solutions.\n- Modifying and refactoring according to changing business requirements.\n- Implementing high-quality software with automation testing.\n- Open-minded newly with many interesting tools and libraries.\n- Self-improvement with huge technical documents and sharing, coaching presentations.\n- For senior level: Support Lead Backend Developer to manage junior/fresher\n\nYour skills and experience\nMust:\n- Willingness to develop and improve services with the sense of ownership\n- Experience development web application using Java from 3 years (exclude training period)\n- Experience with Spring Boot, Spring MVC\n- Basic knowledge and experience with SQL\n- Experience in team development with using Git\n- Experience in development performance-oriented DML\n- Experience in development DDL\n- Experience in designing APIs based on the OpenAPI specification\nPreferable:\n- Experience with UI library/framework such as React\n- Experience with PHP\n- Knowledge of basic security issues such as SQL injection, XSS, CSRF, etc\n- Experience with web application development using cloud service such as AWS\n- Experienced in team building\n- Experience with Scrum development\n- Basic knowledge and experience with Clean Architecture\n\nOnline Interview Process: Test code => 1st Interview(Technical) => Final Interview (Culture Fit Check)\n\nWhy you\'ll love working here\n- Annual Leave: 15 days/ year\n- Flexible Working Time (Hybrid Working)\n- 100% Salary in Probation\n- Salary Review (Twice a Year)\n- 13th Salary bonus\n- Social Insurance for 100% Salary\n- Travel Allowance\n- Premium Health Care Insurance for employees (PTI)\n- Annual Health Check\n- Device Full Provide\n- Monthly Happy Hour, Company Trip, Year End Party and Events\n- Marriage / Baby Gift\n- Funeral Expenses\n- Referral Bonus\n- Skill Improvement Course for Employees (Udemy)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor An Phu Plaza, Vo Thi Sau Ward, District 3, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(950, 193, 2, 'Senior Technical Solutions Manager', 'Top 3 reasons to join us\n1. Positive work environment, support & determination\n2. Very attractive salary & benefits \n3. Development opportunities & improve a quality life\n\nJob description\n- Evaluate business needs and provide scalable technology solutions with a focus on performance and resiliency in terms of software/application specifications and design documents based on architectural blueprints designed by the solution architect and/or Head of Digital Technology.\n- Analyze current technologies used within the company and determine ways to improve. Presents and defends architectural, design, and technical choices to support our technology goals.\n- Provide the development team with architectural blueprints to follow.\n- Guide and assist the development team in resolving technical issues throughout the development process to ensure consistency with initial design, and to ensure software meets all requirements of quality, availability, performance, security, etc. via critical steps of Technical Design and Code Reviews, refactoring of application state, etc.\n- Troubleshoot and resolve issues with coding or design.\n- Develops high-quality code that follows industry standard best practices and considers performance and resiliency.\n- Ensure that the work plan is properly assigned, major timelines are cascaded with the Digital Technology team and the correct documentation is in place and communicated regularly.\n- Carry out the day-to-day tasks such as stand-up calls, meetings, deployments, and relevant important activities.\n- Support leading and mentoring engineers to achieve a greater level of programming skills.\n- Ensure corrective and preventive maintenance and service requests are prioritized and properly delivered.\n- Ensure that service, operational, and support requirements are taken into consideration and solutions are ready to be transitioned to the live.\n- Responsible for ensuring that sufficient testing of solutions has taken place to minimize any disruption during the transition to live.\n- Ensure that the right levels of communication are provided, relationships around the business are developed and nurtured and the expectations of key stakeholders are managed.\n- Improve the product quality and productivity over time.\n- Work closely with cross-functional teams to successfully monitor the progress of initiatives.\n\nYour skills and experience\n1. Education level\nBachelor‘s degree in computer science, information technology, engineering, system analysis or a related study, or equivalent experience.\n\n2. Knowledge & Experience\n- Minimum 10 years of experience working in software development, and at least 5 years in the Technical Lead/Technical Architect position, with proven experience in designing scalable and large systems and making high-level technology decisions.\n- Good knowledge of software and service design (SOA, microservices, messaging, 12-factor methodology).\n- Minimum 3 years of experience in architecting complex projects across technologies like API development, Microservices, Enterprise service bus, and Messaging technologies.\n- Experience in designing different types of APIs and articulating their value proposition.\n- Knowledge and understanding of different modeling languages (such as UML …).\n- Good understanding of strategic and new and emerging technology trends, and the practical application of existing, new, and emerging technologies to new and evolving business and operating models.\n- Good knowledge of Cloud, Containers, and PaaS platforms, formal certification from either GCP, Azure or AWS is a plus.\n- Experience with products and architecture/delivery of solutions in any of Amazon AWS, Microsoft Azure, GCP, ... is a big advantage.\n- Have knowledge of DevOps and container management platforms like Kubernetes and Docker, familiar with CI / CD and Agile software development processes.\n- Strong understanding and familiarity with the fundamentals of cloud systems administration.\n- Experience in banking, finance, or securities sectors is a big plus.\n\n3. Soft skills\n- Ability to present complex concepts and solutions in a way that’s easy to understand to non-technical audiences.\n- Excellent troubleshooting and communication skills\n- Can communicate verbal and written English\n- High responsibility and teamwork\n- Can work under high pressure\n- Ability to meet deadlines and deliver within our high-demand environment\n- Required to be a highly motivated team player, focused on customer satisfaction and solution/results driven.\n\nWhy you\'ll love working here\nUnderstanding candidates\' expectations of the ideal workplace, we always put the people element at the top of our priorities. \n\nPrimary benefits:\n- Attractive KPI Bonus annual\n- Review Salary and performance annual\n- 16+ Annual Leaves​, 5 sick leaves, 1 day off birthday\n- Full Social Insurance, Annual Medical Check- up​, Health insurance\n- Team Building and company activities: Year- end Party, New-year Party, Company trip, Charity activities\n- Learning workshops: e-learning, English courses, career development training programs​\n- Sports clubs: gym, yoga, running, football, tennis, badminton.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'AB Tower, 76A Le Lai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(951, 593, 2, 'AI & Workflow Automation Engineer (Python, JavaScript)', 'Job description\n- Phân tích quy trình hiện tại, tìm điểm tắc nghẽn & cơ hội tự động hóa. Thiết lập, tối ưu workflow automation, CI/CD.\n- Thiết lập workflow trên Zapier/n8n/Make hoặc các platform tương đương để thay thế thao tác thủ công.\n- Đề xuất, xây dựng, và triển khai app/platform tích hợp API AI (ChatGPT, OpenAI, …) để đẩy mạnh các kênh quảng cáo nhằm tăng doanh số.\n- Hỗ trợ team vận hành; viết hướng dẫn đơn giản & hướng dẫn team sử dụng tool AI.\n- Giám sát hiệu năng, bảo trì & nâng cấp hệ thống.\n\nYour skills and experience\n- Tốt nghiệp/Cử nhân CNTT, Khoa học dữ liệu, AI hoặc tương đương.\n- Ưu tiên mới ra trường với dự án cá nhân/đồ án tốt nghiệp thành công (không bắt buộc kinh nghiệm làm việc tại doanh nghiệp).\n- Thành thạo Python hoặc JavaScript/TypeScript.\n- Hiểu biết cơ bản về ML/AI frameworks hoặc API AI.\n- Có portfolio/chứng minh các dự án tự động hoá workflow thành công (Zapier, n8n, Make…) và/hoặc các dự án ứng dụng AI thực tế (NLP, Computer Vision, ChatGPT API, v.v.).\n- Kinh nghiệm với Docker, Git, CI/CD pipelines là lợi thế.\n- Tư duy logic, chủ động, kỹ năng giải quyết vấn đề tốt.\n\nWhy you\'ll love working here\n- Lương: 13 - 18 triệu VNĐ/tháng (thỏa thuận)\n- On-site linh hoạt, hỗ trợ remote khi cần.\n- Được training & cấp license tool AI, access khóa học online.\n- Môi trường startup năng động, report trực tiếp CEO.\n- Review lương 2 lần/năm; Thưởng performance, ngày nghỉ lễ, health check-up.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'NV21 - Khu biệt thự Imperia Garden - 203 Nguyễn Huy Tưởng - Thanh Xuân Trung, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(952, 594, 2, 'Team Leader Back-End Developer (Golang, SQL)', 'Job description\n- Design, develop, and maintain robust and scalable backend systems using Golang.\n- Collaborate with front-end developers and other team members to integrate user-facing elements with server-side logic.\n- Optimize applications for maximum speed and scalability.\n- Implement security and data protection measures.\n- Develop and manage well-functioning databases and applications.\n- Write clean, maintainable, and efficient code.\n- Troubleshoot, debug, and upgrade existing software.\n- Conduct code reviews and provide constructive feedback to peers.\n- Document development processes, architecture, and standard components.\n\nYour skills and experience\n- 1+ years Golang experience in production use case.\n- Knowledge/Experience of SQL and common relational database systems such as PostgreSQL and MySQL.\n- Experience in Microservice Architecture.\n- Excellent problem-solving skills and attention to detail.\n- Basic English communication required.\n- Preferred Qualifications:\n    - Knowledge/Experience of the following datastore: Redis, TimescaleDB\n    - Experience golang web framework like Mux or Gin.\n    - Knowledge/Experience in HTML, VUE.\n\nWhy you\'ll love working here\n- Salary: Negotiated based on ability during interview.\n- Performance review once a year for salary increase consideration.\n- Friendly and professional team working environment.\n- Many opportunities to learn and develop personal skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '43/5 Lý Thường Kiệt, Phường 7, District 11, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(953, 207, 2, 'Senior DevOps/Data Engineer', '• Access to the highest technical resources available for problem resolution or new feature creation.\n• Level 3 technicians attempt to duplicate problems and define root causes, using product designs, code, or specifications.\n• Once a cause is identified, the company decides whether to create a new fix, depending on the cause of the problem. New fixes are documented for use by level 1 and level 2 personnel.\n\nYour skills and experience\n1. Must have:\n• Language: Good English\n• Technical: Technical skill: K8s, Jenkins, .Net, Kafka, DB PostgreSQL...\n• Have experienced in automating deployment with K8S.\n\n2. Nice to have:\n• Have experienced in Database and Data processing: Protgress SQL, DoK, Druid, Superset, Redis, Kafka\n• Have experienced in logging management systems such as ELK\n• Have experienced in programming and familiar with at least 1 programming language. Prefer .Net and C#\n• Have experience working with factory environment or factory system such as MES, ERP\n• Have experienced in customer support and customer care.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lotte Tower, 54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(954, 201, 2, 'Lead Frontend Developer (ReactJS)', 'ABOUT ONE MOUNT\nOne Mount is Vietnam\'s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam\'s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\nOne Mount Real Estate (OMRE) is a property technology company that provides a comprehensive platform to help customers experience a simple and seamless home buying and selling journey. OMRE is the first company in Vietnam capable of integrating the entire real estate transaction process on a single platform, from online to in-person. In addition, OMRE owns the first home valuation product in Vietnam. Don\'t miss the opportunity to become a member in PropTech field at One Mount Real Estate - A member company of One Mount ecosystem, a strategic partner of the leading bank in Vietnam Techcombank and the investor owns the most sought-after luxury apartments in the market, Masterise Home, Vinhomes.\nMAIN RESPONSIBILITIES:\n- Work with Product Managers and Designers to implement and design the next generation of products\n- Build, and write unit test for new features\n- Partner with backend teams to help shape API endpoints\n- Work with UX teams to deliver important functionality to our flagship application\n- Be a key member of a team of front end engineers\n- Maintain excellent coding standards and practices\n- Training for Fresher/Junior developer\n- Design, develop, review, implement, and manage ReactJS application code for the production\n- Understand the requirements of the business and utilize this knowledge to develop applications that are consistent with this\n- Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and tooling.\nYour skills and experience\n- +5 years of experience working in Software Development (with 1+ year experience in leading or mentoring frontend engineers in an agile team for Lead position)\n- Previous experience working as a ReactJS developer\n- Strong Javascript/Typescript skills (ES6) and ReactJS\n- Strong knowledge of development based on REST API.\n- Hands-on experience with HTML5, CSS3, and responsive design including accessibility, SEO and security concerns\n- Experience in SSR/SSG React-based frameworks like NextJS. Good knowledge about NextJS is big plus\n- Experience in modern data-fetching library of Reactjs: React Query, or SWR (nice to have)\n- Familiarity with utility-first CSS framework as Tailwind, and CSS module\n- Solid experience in modern front-end build pipelines and tools (e.g. Git, Webpack, Gulp, NPM)\n- Knowledge of testing frameworks like Jest, React Testing Library, MSW, faker…\n- Excellent in problem-solving and analytical skills (must)\n- Experience with clean code, SOLID, and Design pattern (Prototype, container/presentational, observer, module, High order component, render props…)\n- Good experience in Agile (Scrum model) development environments (must)\nWhy you\'ll love working here\nBENEFITS AND PERKS\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check\n- Laptop, screen and other needed facilities/accounts/tools for work\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'Reilly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n- Grow your career with opportunities across the dynamic ecosystem of Techcombank & Masterise Group.\n- Access special loan offers with competitive interest rates and flexible grace period options tailored to your financial needs.\nWorking Environment\n- Open & collaborative working space fosters both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms.\n- Personal lockers with QR code access.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tower 2 (T26) Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(955, 595, 2, '[Hà Nội] Thiết kế và phát triển ERP (C# WinForms)', 'Job description\n- Thiết kế và phát triển ERP \n- Có kinh nghiệm phát triển C# winform \n- Có kinh nghiệm phát triển MS-SQL \n- Có kinh nghiệm phát triển hệ thống ERP sản xuất, mua nguyên vật liệu, bán hàng và nhân sự. \n- Có kinh nghiệm phát triển MES\n- Chi tiết công việc sẽ trao đổi trong khi phỏng vấn\n\nYour skills and experience\n- Tốt nghiệp ĐH có liên quan\n- Có từ 3 năm kinh nghiệm trở lên về mảng phát triển ERP\n- Có kinh nghiệm phát triển C# winform \n- Có kinh nghiệm phát triển MS-SQL \n- Có kinh nghiệm phát triển hệ thống ERP sản xuất, mua nguyên vật liệu, bán hàng và nhân sự. \n- Có kinh nghiệm phát triển MES\n- Có thể giao tiếp bằng tiếng Anh\n- Nhanh nhẹn, có khả năng làm việc độc lập, làm việc nhóm\n\nWhy you\'ll love working here\n- Thời gian làm việc: thứ 2 - thứ 6 (8h00 - 17h00).\n- Lương: thỏa thuận trực tiếp khi phỏng vấn\n- Chế độ BHXH, thai sản, … theo luật lao động\n- Thưởng lương tháng 13, lễ tết, sinh nhật, ….\n- Môi trưởng làm việc thoải mái, sạch sẽ. Công ty 100% vốn đầu tư của Hàn Quốc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà IC, số 82 Duy Tân, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(956, 596, 2, 'Sr Frontend Software Engineer(ReactJS/VueJS/TypeScript)', 'Top 3 reasons to join us\n- Start-up company with high salary + bonus\n- Macbook Pro M3 & 2 Monitors\n- Modern Tech + Opportunity to business trip in JP\n\nJob description\nMain Duties:\n- Participate in the documentation process, requirements analysis, design the interface, deployment, code review, unit testing and operating the product.\n- Ensure the interface loads quickly and works smoothly on different platforms.\n- Troubleshoot interface software and debug application code\n- Update and maintain the user interface as required or as needed.\n- Interact with other members of the development team to ensure alignment and compatibility between application components\n- Training, support and motivate team members.\n- Research and develop new technology related to project\n\nYour skills and experience\nMust-have\n- Preferably a bachelor’s degree in IT, Computer Science or related fields\n- 03+ years for Web service development\n- Experience as throughout the full project development lifecycle from the zero\n- Experience with TypeScript, NextJS, NuxtJS\n- Have a learning mindset, willing to switch languages ​​from ReactJS to Vues or vice versa. You can choose 01 option as below:\n    Option 1: ReactJS\n    - 03+ years of experience in ReactJS\n    - Experience in State management Redux(redux-toolkit), redux-thunk, redux-saga\n    - Experience in Function Component is the main, but Class Component can also be used in some cases.\n    Option 2: VueJS\n    - 03+ years of experience in VueJs\n    - Familiarity with Composition API\n\nNice to have\n- GraphQL development experience\n- Have knowledge in Http API / Rest API and the difference regardless of language\n- Can develop functions that meet system requirements by considering vulnerabilities in authentication (Cookie, Session, JWT), etc.\n- Someone who understands SAML, SSO, etc. and can support system expansion.\n- Experience in UI/UX design\n\nWhy you\'ll love working here\n# Working environment\n- Start up company in Vietnam, but in Japan we have more than 1,000 members.\n- Modern technology\n- English-speaking environment with Managers\n- Working time: Monday to Friday - 9:00 to 18:00 (Flexible)\n- Working style: Office\n\n# We want to work with members\n- Professional\n- Integrity\n- Respect\n- Eager to learn\n- Meet deadlines\n\n# Why you love with us\n- Macbook Pro + 02 monitors\n- 13th month bonus + KPI bonus.\n- Performance Review 02 times/ year\n- Social insurances follow Vietnam law.\n- Awards (Most Value Person, Extraordinary bonus mode).\n- Voluntary insurance for employees.\n- Voluntary insurance for management level (plus 02 relatives).\n- 100% probation salary .\n- 12 days annual leave\n- Various training \n- Technical seminar\n- Opportunity to work in Japan offices\n- Company building events (Company trip, Year end party..)\n- Team building events \n- Free tea, coffee, botox water\n- Flexible lunch time\n- Parking fee\n- Start company projects from Zero\n\nOur products will make huge difference in the world, as we have a much recognized sales distribution capability to spread what you develop the best, starting with the Japanese market then to the rest in the future. Wanna challenge your limits? Oh yeah, it’s here to try it.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '20th Floor, Viettel Tower, 285 Cach Mang Thang Tam, Ward 12, District 10, Ho Chi Minh City Vietnam, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(957, 303, 2, 'QA QC Contractor - 4 months', 'We are seeking a Quality Control Contractor to support our team during a critical product phase. This is a 4-month contract role, ideal for a detail-oriented, proactive individual with a solid background in software testing. You’ll support testing activities for upcoming releases to help ensure smooth releases and system reliability. This is a great opportunity to work on Mobile apps and Firmware systems.\n\nResponsibilities:\n- Execute manual test cases for mobile and Firmware (as a plus) based on requirements.\n- Collaborate with stakeholders to clarify expected behavior and test coverage\n- Support regression and smoke testing for upcoming releases.\n- Assist in test case creation and documentation updates as needed.\n- Ensure timely testing feedback and bug validation within the sprint or release cycle.\n\nYour skills and experience:\n- At least 3 years of experience in software QA or testing roles.\n- Strong understanding of testing methodologies, SDLC, and defect lifecycle.\n- Experience with bug tracking and test case management tools (e.g., Jira, TestRail).\n- Solid problem-solving skills and attention to detail.\n- Ability to work independently and hit deadlines in a fast-paced environment.\n- Understanding Networking Protocols such as TCP/IP, UDP, Bluetooth, and Wi-Fi is a plus.\n- Experience working with embedded Linux systems is a plus.\n- Good written English skills.\n\nWhy you\'ll love working here:\nWe’ve worked hard to build the workplace culture we’ve always dreamed of - one where we celebrate each other\'s successes, work hard together, and know when it’s time to relax. We know that we can’t reach our goals alone, and think that our culture makes it a little easier to come to work and makes our biggest goals achievable. At FuelCloud, you’ll be using cutting-edge technology and taking on interesting challenges every day with a team that is genuinely happy to have you!\n\nBenefits:\n- Attractive salary (Full salary during probationary period)\n- 13th month - salary\n- Provide Laptop & Screens for working\n- Ability to travel to US\n- Working with expat team\n- Premium health care insurance for you and your family\n- Free annual health check\n- 15 days of PTO and no working OT\n- Company trip & team dinners\n- Many team activities: Birthday party, Mid-Autumn Festival, Christmas, Year End party,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No 22, B2 Street, Sala Urban Residence, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(958, 440, 2, 'Software Developer (VueJS/ Laravel)', 'Job description\n1. Phát triển Backend:\n- Thiết kế, phát triển và duy trì các dịch vụ phụ trợ bằng Laravel và ecosystem của Laravel.\n- Tối ưu hóa truy vấn cơ sở dữ liệu để đảm bảo hiệu suất và khả năng mở rộng của hệ thống.\n- Triển khai và duy trì API RESTful cho giao diện người dùng và tích hợp của bên thứ ba.\n- Đảm bảo các biện pháp bảo mật tốt nhất được tuân thủ trong hoạt động API và cơ sở dữ liệu.\n\n2. Phát triển Frontend:\n- Xây dựng và duy trì các tính năng hướng tới người dùng bằng VueJS (Vue 3).\n- Làm việc chặt chẽ với các nhà thiết kế UI/UX để tạo ra các thành phần giao diện có thể tái sử dụng và mở rộng quy mô.\n\n3. Các công việc khác:\n- Làm việc chặt chẽ với nhóm nghiệp vụ để chuyển đổi các yêu cầu thành các giải pháp kỹ thuật.\n- Viết code sạch, hiệu quả và dễ bảo trì theo các chuẩn ISO đưa ra.\n- Thực hiện đánh giá mã và đóng góp vào việc cải thiện quy trình phát triển.\n- Cập nhật những xu hướng mới nhất về Laravel, VueJS và các công nghệ liên quan.\n\nYour skills and experience\n- Trình độ chuyên môn: Tốt nghiệp đại học trở lên\n- Có ít nhất 2 năm kinh nghiệm làm việc với Laravel, VueJs trong môi trường sản xuất.\n- Kinh nghiệm với VueJS (Vue 2 hoặc Vue 3), bao gồm phát triển dựa trên thành phần.\n- Thành thạo MySQL/PostgreSQL, bao gồm tối ưu hóa truy vấn và thiết kế cơ sở dữ liệu.\n- Kinh nghiệm xây dựng và tích hợp API RESTful.\n- Quen thuộc với Git và làm việc trong môi trường phát triển cộng tác.\n- Bằng Cử nhân (hoặc cao hơn) chuyên ngành CNTT hoặc các lĩnh vực liên quan, ưu tiên ứng viên đến từ các trường đại học hàng đầu.\n\nWhy you\'ll love working here\n- Tiền lương: thoả thuận khi phỏng vấn\n- Phụ cấp ăn trưa\n- Được làm việc trong môi trường năng động, hiện đại.\n- Tạo điều kiện học hỏi và nâng cao khả năng chuyên môn.\n- Được hưởng các chế độ BHXH, BHYT, BHTN, tham quan, nghỉ phép, thưởng năng suất, nghỉ các ngày lễ theo quy định của Luật lao động hiện hành.\n- Nơi làm việc: Bệnh viện Đa Khoa Phương Đông (Số 9, Phố Viên, Cổ Nhuế 2, Quận Bắc Từ Liêm, Hà Nội)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bệnh viện đa khoa Phương Đông. Số 9, Phố Viên, phường Cổ Nhuế 2, Bac Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(959, 597, 2, 'Project Director Assistant (PMO)', 'About ITC  Join ITC, a trailblazing force with offices in Shanghai, Singapore, Melbourne and Saigon. We are a hub of innovation for Fortune 500 companies and industry leaders, guiding them through the complexities of the Chinese and APAC markets.  At ITC, you\'ll play a pivotal role in transforming their business landscapes using cutting-edge MarTech, e-Commerce, and Omnichannel solutions. As part of our team, you\'ll not only witness but also contribute to significant ROI achievements and market successes. We\'re not just navigating the future of digital commerce; we\'re creating it. Be a part of our journey to redefine industry standards and elevate market experiences across Asia.  With a talented team of 60 professionals across APAC, our 2024 milestones include:  Orchestrating 30+ digital transformation workshops for global leaders like Coty, LVMH, and Unilever Prestige  Empowering 5,000+ Sales Associates across luxury brands like Moncler, Margiela, Moschino, and Christies with comprehensive omnichannel training programs and change management  Spearheading Salesforce Commerce Cloud implementations for luxury brands in China, notably with LVMH and other fashion groups  Driving eCommerce growth with bespoke website development for clients like Brandy Melville and Hublot  Scaling fast fashion to 10,000+ daily orders with optimized e-commerce solutions  Igniting sales for Hublot, Omega, and Fred via high-performing Mini Programs in China  Expanding The Hour Glass\'s presence across 9 APAC markets with integrated solutions.  What You Will Get Out of This Position  As a Project Manager, you will take ownership of end-to-end delivery for large-scale digital projects, with a strong emphasis on eCommerce and CMS platforms. You will work directly with enterprise clients, managing cross-functional teams and ensuring project success from scoping to post-launch support. This is a client-facing, leadership role that combines technical understanding, stakeholder management, resource planning, and profitability oversight.  Responsibilities:  Lead full lifecycle delivery of complex and high-valued eCommerce projects, from discovery through post-launch  Lead multidisciplinary teams of 2-4 members including designers, developers (front- and backend), QA engineers, and analysts.  Ensure the project is delivered on time, within budget, and meets high-quality standards and business goals.  Define and oversee scope, timelines, budgets, resourcing, and risk management strategies.  Serve as the main point of contact for clients, managing expectations, scope, and change requests.  Negotiate timelines and budgets with clients while ensuring profitability and operational feasibility.  Conduct stakeholder meetings, workshops, and presentations to ensure alignment on vision, priorities, and deliverables.  Provide hands-on leadership and guidance in eCommerce topics, including product setup, cart and checkout flows, OMS, and inventory workflows.  Facilitate architecture discussions and system design planning, especially for headless and API-first projects.  Create and review flow diagrams, architecture maps, and solution documentation for internal and client use.  Work with internal stakeholders to optimize resource planning, project assignments, and workload balancing.  Your skills and experience  Requirements  Must have:  2-3+ years of experience in project management, with at least one full eCommerce project from 0 to 1 successfully delivered in the past 12 months.  Fluent in English with excellent communication skills and writing skills.  Ability to conduct Pre-sales presentations in front of clients.  Experience in managing and communicating at senior and executive levels.  Experience in managing large scale projects in the following solutions: Web/APP E-commerce platform; CRM/Salesforce implementation; MarTech;   Strong working knowledge of eCommerce architecture, CMS products (especially WordPress), and headless frameworks.  Demonstrate strong CMS knowledge—WordPress is a must, and Drupal is a plus.  Proven ability to manage both business expectations and technical realities.  Ability to engage and partner with the customer and internal staff as required.  Ability to work in a multicultural team with different time zones.  Ability to identify problems and work to resolution as required.  Excellent understanding of web and mobile application development lifecycle.  Experience leading diverse project teams and navigating fast-paced, client-driven environments.  Familiarity with Agile/Scrum, Jira, Confluence, and tools like Figma or Miro.  Nice to have:  Open Source technical background preferred;   Understanding of some if not all: Laravel, ReactJS, React Native, Javascript, HTML/CSS, Objective-C/Swift, Java/Kotlin, will be a huge plus;  Additional language (French, Chinese…);  Why you\'ll love working here  Are you looking for an innovative and dynamic company that puts the emphasis on productive fun in an engaging work environment? If the answer is yes, then working at IT Consultis should be the right fit for you.  Working with us means nurturing your own career and investing in your future. Here are reasons why you should join IT Consultis:  Employment and insurance benefits above the market  Professional career path and frequent objectives, review  Multicultural team (14+ nationalities), non-stop parties, sharing, learning  Lovely office with modern facilities  Working equipment provided  Fun and dynamic team with great ambition, always fight for the same goal  Free parking lot for your beloved motorbikes  Pantry area with snacks, drinks available all the time  Other exciting team building activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '19 Tan Canh, Ward 1, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(960, 504, 2, '[HN/ HCM] Data Analyst (English/ MS Office)', 'Top 3 reasons to join us\n\n- Monthly leave: 6–7 days per month\n- Bonuses on holidays, performance-based bonuses\n- Annual company trips and vacations.\n\nJob description\n\n- Data Collection & Processing: Gather, clean, and organize data from various sources to ensure accuracy and usability.\n- Data Analysis: Use analytical tools to explore data, identify trends, patterns, and actionable insights.\n- Reporting: Develop and present analytical reports, dashboards, and data visualizations to support business decisions.\n- Cross-Department Collaboration: Work closely with marketing, sales, and product teams to understand needs and provide necessary analysis.\n- Process Improvement: Recommend data-driven solutions to optimize operations and business outcomes.\n- KPI Monitoring & Evaluation: Track key performance indicators and assess the effectiveness of strategies and programs.\n\nCandidates in Hanoi will work at the office - candidates in HCM will work remotely until the office setup is complete.\n\nYour skills and experience\n\n- No gender preference. Age: Born in 1986 or later.\n- Experience: Minimum 5 years in the applied position.\n- Proficient in MS Office (Word, Excel, PowerPoint, Forms...) and Google Tools (Sheets, Docs, Slides, etc.).\n- English: Fluent communication is a plus.\n- Quick to adapt, high stress tolerance, and strong sense of responsibility.\n\nWhy you\'ll love working here\n\n- Bonuses on holidays and Tet; performance-based bonuses (monthly/quarterly/yearly).\n- 100% meal expenses covered.\n- Frequent short/long-term business trips, domestic and international. Company covers 100% of accommodation and meals during trips.\n- Monthly leave: 6–7 days per month (depending on level/position).\n- Annual company trips and vacations.\n- 100% support for job-related training courses upon request. No reimbursement required if the employee resigns.\n- Professional – Dynamic – Fair – Human-centric working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '18 Lại Đà, Xã Đông Hội, Dong Anh, Ha Noi; Online, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(961, 598, 2, 'Backend Developer (NodeJS,JavaScript,PHP)', '📝 Công việc chính\nPhát triển hệ thống sử dụng Java và Node.js\nThiết kế server và cơ sở dữ liệu cho các dự án liên quan đến blockchain và tài chính của công ty\nMôi trường làm việc linh hoạt, đa dạng\n⏱️ Thời gian làm việc & OT\nCó thể làm thêm giờ (OT) khi cần thiết\nPhụ cấp và chế độ đãi ngộ OT hấp dẫn\n🌟 Ưu tiên\nCó kinh nghiệm xây dựng pipeline CI/CD\nCó kinh nghiệm sử dụng AWS Lambda hoặc kiến trúc Serverless\nKinh nghiệm phát triển các blockchain mainnet (Ethereum, Bitcoin, XRP, v.v.)\nCó thể giao tiếp tiếng Anh cơ bản\nCó tinh thần đóng góp ý kiến và sẵn sàng thử thách kỹ thuật\nKỹ năng giải quyết vấn đề và phản ứng nhanh\nCó đam mê phát triển bản thân và mong muốn gắn bó lâu dài\n-Kinh nghiệm phát triển Node.js từ 2 năm trở lên (Ưu tiên biết thêm PHP)\n-Kinh nghiệm phát triển với Node.js, TypeScript, JavaScript, MySQL, Redis, Kafka\n-Thành thạo sử dụng Git\n-Hiểu biết về các công nghệ liên quan như Docker, Microservice, HTTP, API, REST\n-Có khả năng thực hiện migration cơ sở dữ liệu hoặc tối ưu hiệu suất\nMức lương siêu cạnh tranh\nChế độ làm việc 4+1 (04 ngày làm việc chính thức, 01 ngày làm việc remote)\nTrợ cấp ăn trưa 70.000đ/1 bữa, gửi xe miễn phí, văn phòng đầy đủ bánh kẹo, cafe, nước uống\nKý hợp đồng lao động, đóng bảo hiểm đầy đủ\nChế độ lương thưởng hấp dẫn, lương tháng 13\nMôi trường làm việc năng động, cấp trên tâm lý, đồng nghiệp trẻ trung, đoàn kết hỗ trợ nhau trong công việc\nCơ hội giao lưu học hỏi về những công nghệ tiên tiến nhất trong lĩnh vực CNTT nói chung và phát triển lập trình web, app nói riêng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '766/1 Sư Vạn Hạnh, phường 12,, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(962, 599, 2, 'Bridge Engineer (BrSE,Project Manager) (tiếng Nhật)', 'Chúng tôi đang tìm kiếm một BrSE/PM có kinh nghiệm phát triển linh hoạt và có thể lãnh đạo nhóm kỹ thuật phát triển dịch vụ SNS mới đồng thời duy trì liên lạc chặt chẽ với các thành viên phía Nhật Bản.\n\nỞ vị trí này, bạn có thể tận dụng các công cụ AI (vd: Cursor, Bolt.new, Vercel v0, Dify, OpenAI o1, Claude 3.5 Sonnet, v.v.) để thúc đẩy hiệu quả, và đổi mới trong quá trình phát triển. Chúng tôi đặc biệt hoan nghênh những người muốn làm việc quản lý dự án bằng cách sử dụng Generative AI hoặc những người có kinh nghiệm trong lĩnh vực này.\n\nTối ưu hóa và hợp lý hóa quy trình phát triển bằng các công cụ AI\nQuản lý nhóm kỹ thuật và quản lý tiến độ dự án\nKết hợp với đối tác Nhật Bản nhằm xác định yêu cầu, xây dựng thông số kỹ thuật, báo cáo tiến độ...\nQuản lý mảng phát triển và thiết kế FE (Vue.js, Nuxt.js) cũng như BE (Node.js, Express, MySQL)\nXem xét và triển khai các công nghệ và công cụ mới\n\nIdea Candidate:\nTạo ra sự đổi mới trong quá trình phát triển bằng cách sử dụng công nghệ AI\nChủ động giới thiệu các công nghệ và công cụ mới giúp cải thiện kỹ năng của cả nhóm.\nCó khả năng lãnh đạo và dẫn dắt các thành viên\nCó khả năng giao tiếp hiệu quả giữa team Nhật Bản và Việt Nam\nCó niềm đam mê và tinh thần trách nhiệm dẫn dắt dự án đến thành công\n\nCareer level: Middle - Senior\n\nRequired skills & experiences:\nTiếng Nhật từ N3 (giao tiếp tốt)\nTừng làm dự án phát triển với Node.js, JavaScript và TypeScript như FE : Vue.js, Nuxt.js,... BE : Express, MySQL\nTừng làm dự án phát triển trên AWS\nKinh nghiệm phát triển với mô hình Agile\nCó ý thức sử dụng AI trong công việc nhằm nâng cao hiệu suất (Cursor, Bolt.new, vercel v0...)\nKĩ năng phân tích yêu cầu\n2+ YoE quản lý dự án\n\nA plus:\nJLPT N3 trở lên giao tiếp tốt\nTiếng anh thương mại\nKinh nghiệm tham gia các dự án sử dụng LLM như OpenAI o1, Claude 3.5 Sonnet, v.v.\nKinh nghiệm phát triển hệ thống trong các lĩnh vực Web3 như blockchain\nKinh nghiệm phát triển hệ thống trong lĩnh vực giải trí BtoC\nKinh nghiệm với Docker và Linux\nKinh nghiệm phát triển hệ thống cho các dự án liên quan đến âm thanh\n\nWhy you\'ll love working here:\n18 ngày nghỉ/năm\nHỗ trợ ăn trưa\nTeam building package\nBHXH full lương\nPhụ cấp công tác\nLương tháng 13\nGiờ làm việc: 9:00 - 18:00 (Thứ Hai - Thứ Sáu)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hive Villa, 29 Nguyễn Bá Lân, Thảo Điền, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(963, 600, 2, 'Project Manager (ERP)', 'About the job:\nLead and manage digital transformation initiatives within the manufacturing environment, including ERP implementation, production process digitalization, inventory management, traceability systems, and integration of IT systems with on-site operations.\n\nKey Responsibilities:\nPlan, implement, and monitor digital transformation projects such as ERP (e.g. SAP, Odoo), MES, WMS, DMS, traceability systems, and QA/QC automation in manufacturing.\nWork closely with departments such as Production, Inventory, Finance, HR, and Quality to gather business requirements and identify process improvement opportunities.\nAct as the bridge between internal teams and external vendors/consultants during solution design, customization, testing, and deployment.\nManage project budgets, timelines, scope, and risks. Ensure alignment with business goals at every project milestone.\nOrganize user training sessions and develop SOPs, user manuals, and support documentation for system operation.\nTrack and analyze post-implementation metrics (e.g. ROI, production KPIs, automation levels) and recommend further optimizations.\n\nYour skills and experience:\nBachelor’s degree in Industrial Engineering, Manufacturing, IT, Business Administration, or a related field.\nMinimum 3–5 years of experience managing digital transformation or IT implementation projects in a manufacturing environment.\nStrong understanding of manufacturing operations (e.g. mass production, batch processing, quality control, maintenance, supply chain).\nHands-on experience with systems such as ERP, MES, WMS, or other factory-focused platforms.\nProficient in project management (budgeting, scheduling, risk control); PMP, Agile, or equivalent certifications are a plus.\nStrong communication skills, especially in translating business needs into technical requirements.\nGood English proficiency (spoken & written) – especially for working with international vendors and reading documentation.\n\nWhy you\'ll love working here:\n5 working days/week (Monday to Friday), weekends off\nHybrid work policy offered.\nCompany-supported sports and team-building activities (e.g., football, badminton).\nCelebration events (Happy hour, Birthday parties, Holiday gifts, Year-end party).\nAnnual company trip and regular team-building events\nFree snacks, tea, and coffee at the office.\nFree parking.\nRelaxed, friendly workplace with great facilities.\nOpportunities for promotion and career development.\n13th-month salary and annual salary review.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '77 Le Trung Nghia, Ward 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(964, 601, 2, 'IT Product Architect', 'Job description\n- Thiết kế kiến trúc tổng thể cho các sản phẩm công nghệ (phần mềm & phần cứng)\n- Phối hợp chặt chẽ với các bộ phận kỹ thuật – kinh doanh – vận hành trong quá trình triển khai hệ thống\n- Tham gia các dự án lớn trong lĩnh vực giao thông thông minh: ITS, ETC, thu phí nội đô, đường sắt...\n\nYour skills and experience\n- Độ tuổi: 30 – 45\n- Tốt nghiệp Đại học trở lên chuyên ngành CNTT\n- Tối thiểu 3-5 năm kinh nghiệm ở các vị trí: Product Architect / Solution Architect / Tech Lead / Product Owner\n- Có kiến thức vững về hệ thống phần mềm, phần cứng và tích hợp hệ thống\n- Có tư duy logic, kỹ năng làm việc phối hợp đa phòng ban hiệu quả\n- Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực giao thông thông minh\n\nWhy you\'ll love working here\n- Bạn là người có tư duy hệ thống, đam mê công nghệ và mong muốn được tham gia thiết kế, xây dựng các sản phẩm công nghệ quy mô lớn? Đây chính là cơ hội dành cho bạn!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 15, Toà Cục Tần số, 115 Trần Duy Hưng, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(965, 602, 2, 'URGENT - [Remote] Ruby on Rails Developer', 'Top 3 reasons to join us\n- Competitive Salary and Attractive Bonuses\n- Unique Salary Reviews\n- Exciting and Challenging Projects\n\nJob description\nThe job description will be discussed in detail during the interview process.\n\nYour skills and experience\n- 4+ years of experience with Ruby on Rails, SQL, and testing frameworks like RSpec or Minitest. \n- Proficiency with Rails versions 5+ and understanding of upgrade impacts. \n- Strong expertise in Git for version control and familiarity with QA processes. \n- In-depth knowledge of MySQL and relational database systems. \n- Experience working with Docker containers. \n- Background in e-commerce platforms or complex backend systems, with the ability to quickly adapt to new domains. \n- Proven track record as a Ruby on Rails Developer with successful project deliveries. \n- Solid understanding of software architecture and design patterns, enabling sound decision-making.\n- Strong problem-solving skills and the ability to make effective technical decisions.\n- English communication skills with clients are required.\n- Candidates who can start early will be given priority.\n\nWhy you\'ll love working here\n- Competitive Salary and Attractive Bonuses: We proudly offer salaries above market rates, along with performance bonuses to recognize your contributions. \n- Exciting Projects: You\'ll have the chance to work on innovative projects that challenge your skills and creativity, keeping your work engaging and rewarding.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '270/22/63 Nguyễn Thị Búp, Phường Hiệp Thành, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(966, 186, 2, 'Server Game Developer (.NET, C#, Game)', 'Mô tả công việc\n- Xây dựng server game bằng .NET/C#  \n+ Phát triển hệ thống server cho game: API RESTful hoặc WebSocket, sử dụng .NET Core / ASP.NET.\n+ Xử lý các nghiệp vụ chính : Đăng nhập, đăng ký, xác thực, Tạo và quản lý nhân vật,Tính toán trận đấu (PvP, PvE),Hệ thống vật phẩm, kỹ năng, tiến trình game,Tính toán thưởng, nhiệm vụ, hệ thống sự kiện.\n- Giao tiếp với client (Unity, web...)\n+ Nhận request từ client, xử lý logic và gửi lại dữ liệu (JSON hoặc Binary).\n+ Đảm bảo kết nối an toàn, chống fake request, timeout...\n+ Hỗ trợ truyền dữ liệu theo thời gian thực (real-time) với SignalR, WebSocket, hoặc TCP socket tùy nhu cầu game.\n- Quản lý và lưu trữ dữ liệu :\n+ Thiết kế và thao tác với SQL database (MS SQL Server, PostgreSQL...).\n+ Tối ưu hóa truy vấn, xây dựng hệ thống lưu tiến trình, thống kê, lịch sử giao dịch.\n+ Kết hợp với Redis / NoSQL để lưu cache, tăng hiệu năng server.\n- Xử lý lỗi và sự cố:\n+ Phân tích và khắc phục lỗi trong quá trình kiểm thử tích hợp, kiểm thử chấp nhận người dùng (UAT) và kiểm thử bảo trì, đảm bảo độ ổn định và hiệu suất hệ thống.\n- Quản lý dự án:\n+ Quản lý thời gian và nguồn lực hiệu quả dựa trên Cấu trúc phân rã công việc (WBS) để đảm bảo tiến độ và chất lượng dự án.\n\nYour skills and experience\n- Bắt buộc ứng viên sử dụng được : .NET (C#)\n- Bắt buộc có kinh nghiệm sử dụng công cụ Git, và có hiểu biết về CI/CD\n- Kinh nghiệm: từ 5 năm trở lên cân nhắc về số năm kinh nghiệm tương ứng với mức lương.\n- Yêu cầu: Có portfolio, đính kèm mã nguồn (code)\n\nTrong quá trình phỏng vấn:\n- Có thể có bài thi tự luận về Design Pattern\n- Kèm bài kiểm tra lập trình (coding test) ( nhằm đánh giá cả tư duy lập trình lẫn khả năng thiết kế phần mềm.)\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt.\n\nWhy you\'ll love working here\n✨ CHẾ ĐỘ PHÚC LỢI HẤP DẪN TẠI CÔNG TY ✨\n- Thu nhập cạnh tranh:\n+ Mức lương hấp dẫn, thưởng tháng 13 và thưởng thâm niên.\n+ Thưởng theo hiệu quả công việc, xét thưởng vào các dịp Lễ – Tết.\n+ Đánh giá tăng lương 1 lần/năm, trường hợp nổi bật sẽ được xét tăng lương ngay tại thời điểm.\n- Chế độ nghỉ phép:\n+ 12 ngày nghỉ phép có lương mỗi năm theo quy định – nghỉ thoải mái, vẫn nhận lương đầy đủ.\n- Sự kiện nội bộ ấm áp:\n+ Hàng năm tổ chức “Ngày hội gia đình” vào tháng 5, có quà tặng bằng tiền mặt dành tặng ông bà, cha mẹ, vợ/chồng và con cái của nhân viên – thể hiện sự trân trọng với cả gia đình bạn.\n- Chế độ quà tặng nhân dịp đặc biệt:\n+ Tặng quà các ngày lễ: Tết Dương lịch, Tết Âm lịch, 30/4, Trung thu, 8/3, 20/10.\n+ Cả nhân viên nam và nữ đều có quà.\n+ Nhân viên chính thức trên 6 tháng được tặng quà sinh nhật trị giá 5 triệu đồng/người.\n- Thưởng hiệu suất riêng:\n+ Ngoài lương chính còn có các khoản thưởng, bonus hàng tháng tùy theo đóng góp.\n- Hỗ trợ nơi ở:\n+ Nhân viên ở xa được sắp xếp chỗ ở miễn phí, thuận tiện cho công việc.\n- Cơ hội học hỏi và phát triển:\n+ Làm việc cùng các chuyên gia hàng đầu trong nước và quốc tế.\n+ Giao lưu, học hỏi với đồng nghiệp quốc tế giúp cải thiện tiếng Anh và mở rộng tư duy toàn cầu.\n- Chăm sóc sức khỏe toàn diện:\n+ Khám sức khỏe định kỳ tại các bệnh viện quốc tế như BV Phương Đông.\n+ Miễn phí tiêm phòng HPV, cúm cho nhân viên.\n- Trải nghiệm công tác và du lịch:\n+ Các chuyến công tác nước ngoài kết hợp du lịch, khám phá đặc sản và địa danh nổi tiếng.\n+ Được tài trợ các hoạt động gắn kết team, học hỏi kiến thức lập trình qua các buổi giao lưu, workshop.\n- Văn phòng hiện đại, tiện nghi:\n+ Không gian làm việc rộng rãi, thoáng mát.\n+ Có bánh, trà, café phục vụ mỗi ngày.\n+ Bữa trưa đầy đủ dinh dưỡng, ngon miệng dành riêng cho nhân viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'B4-12 Vinhomes Gardenia Hàm Nghi, Đường Hàm Nghi, Phường Cầu Diễn, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(967, 603, 2, 'Mid. Full Stack Developer  (ReactJS/React Native)', 'Top 3 reasons to join us\n- At Silentium, we value attitude the most\n- Attractive salary with Premium Healthcare plan\n- Great team & project, Big bonus\n\nJob description\n- Develop and maintain applications using Node.js, ReactJS, and React Native\n- You’ll take extreme ownership of your work. Every day is a challenge to ensure you perform to the level you and your product team agreed on upfront\n- Work closely with the Product Manager, Product Designer, and other developers to deliver the product\n- Architect and develop excellent React Native Applications while maintaining high-quality code\n- Write unit and integration tests for Mobile\n- Work with the Native Module as needed\n- Release applications to Google Play and Apple Store\n- Taking care of the Continuous Delivery pipeline for Mobile to guarantee the continuity of the delivery\n\nYour skills and experience\n- 2 years of professional React-native development experience\n- At least 4 years of professional development experience, proficient in the JavaScript and TypeScript ecosystems.\n- Experience with writing Unit tests, integration tests, and end-to-end tests using frameworks like (Jest, AVA, Cypress, Playwright, etc.)\n- Experience working with Swift, Objective-C, or Java (on Android) would be a plus\n- Experience working with handling Cryptography, handling sensitive data on the App would be a plus\n- Very self-motivated, proactive working style. We move as a team where every team member reaches out for a problem to solve, not the other way around\n- A critical thinking and product mindset.\n- Professional and be a TEAM PLAYER, because we can move nowhere without a team.\n- Keep yourself updated, mobile development is moving too fast for us to stay still\n\nWhy you\'ll love working here\n- Hybrid Working Model\n- A lot of ownership of your work. We tackle challenges, as a team\n- Chance to design a complex system and see that comes live\n- Very open environment, with no hierarchy, we want you to be the change you seek\n- Competitive salary. We pay what you deserve, not what the paper says\n- Full compulsory Social, Health, and Unemployment insurance.\n- Sponsored Grab support to work at a beautiful office in D2 with unlimited free coffee, tea, snacks, and fruit to keep you energized.\n- High-tech gear to support your work: Apple/Windows laptops, an extra monitor, etc.\n- Up to 13 days of annual leave with a loyalty program. Get 1 day more extra AL after 1st 2 years, and get 1 day more /year from the next year.\n- Additional 03 days off: Christmas leave (25/12), Vietnamese Family Day (28/6), Birthday leave\n- Gifts on special days like birthdays, Tet, and Holidays\n- Premium Health Insurance for yourself and family members\n- Loyalty Program Cash & Annual Leave - up to $1000\n- 13th-month bonus salary\n- Yearly Company Trip; Monthly/Quarterly team-building activities and special celebrations on Autumn Festival, Halloween, Christmas, Tet, …\n- Big chance to grow as a person. We use Eventstorming, Service Blueprint, Empathy map, and a lot of modern toolsets to make our life easier and we are eager to share that with you\n- Even bigger chance to grow as an engineer. We\'re all open to trying and applying new technology; if it doesn\'t work, well, we have learned\n\nInterview process\n- Screening Test: A straightforward test at application. Please provide a submission timeline once you understand the requirements. Feedback will be given within one working day.\n- Technical Interview: Discussion with the Team Leader and Sub Lead to assess your technical skills (around 1-2 hours).\n- Peer-to-Peer Interview: Meet with your potential teammates (Product Manager, Designer, and other developers).\n- Final Feedback: Provided within three working days.\n\nNotes: \nPlease note that we will only contact candidates whose profiles closely match the qualifications and requirements outlined for the role. If you do not receive a response from us, it means that you have not been shortlisted for the next steps at this time. We thank you for your understanding.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '95-97 Nguyễn Cơ Thạch (Khu đô thị Sala) - P. An Lợi Đông - Q2, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(968, 255, 2, 'QA Automation Engineer (Playwright,TypeScript)', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nWe are seeking a highly skilled and motivated QA Automation Engineer to join our team in Ho Chi Minh City, Vietnam. This is an in-office position and offers an exciting opportunity to work with cutting-edge technologies in a dynamic and collaborative environment. As a QA Automation, you will play a crucial role in ensuring the quality and performance of our software products.\n\nCore Responsibilities\n- Design, develop, and maintain automated test scripts using Playwright, Selenium, and other test automation tools.\n- Conduct exploratory testing to identify and document software defects.\n- Perform performance testing using JMeter to ensure the scalability and reliability of our applications.\n- Test applications in both OnPrem environments and cloud-based platforms.\n- Work with Azure DevOps to manage test cases, test plans, and CI/CD pipelines.\n\nFunctional Responsibilities\n- Collaborate with SAFe Agile teams to deliver high-quality software products.\n- Create detailed documentation and data-driven reports to communicate test results and insights.\n- Understand and test microservices, micro frontends, APIs, and provide comprehensive test coverage.\n\nYour skills and experience\nTechnical Skills\n- Minimum 3 years of experience in QA automation and exploratory testing.\n- Proficiency in Playwright/TypeScript, Selenium, JMeter (preferred), and other relevant testing tools.\n- Experience with performance testing and analyzing performance metrics.\n- Familiarity with SAFe Agile methodologies and working in Agile teams.\n- Hands-on experience with Azure DevOps and CI/CD pipelines.\n- Strong understanding of testing microservices, micro frontends, and APIs.\n- Excellent documentation and reporting skills with a data-driven approach.\n- Detail-oriented with strong analytical and problem-solving skills.\n- Effective communication skills and ability to work collaboratively in a team environment.\n- Excellent English communication skills are required.\n\nThings that will separate you from the rest\n- Experience in the Fintech industry.\n- Knowledge of other test automation frameworks and tools.\n- Certifications in QA or related fields.\n\nEducation or Certifications\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n\nWhy you\'ll love working here\n- Highly competitive salary\n- Full salary for probation & full coverage of social insurance.\n- Premium healthcare for you and your beloved one.\n- Monthly childcare support\n- 13th-month salary.\n- Annual Leave: 15 days; Paternity Leave: 6 weeks, Bereavement leave: 10 days.\n- Flexible working time, focus on output (no checking time attendance)\n- Various active sporty clubs: Football, Billiards, Badminton, E-sport clubs\n- Frequent opportunities to travel to US headquarter from 3-6 months.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Six8 Building: 24-26 Phan Dinh Giot Street, Tan Binh District, HCMC., Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(969, 356, 2, 'Senior Angular Developer', 'Top 3 reasons to join us\n1. Attractive salary, benefits, hybrid working\n2. Technical training sessions (internal – external)\n3. PVI Healthcare insurance\n\nJob description\n- Develop and maintain applications.\n- Write clean and maintainable code that follows modern programming principles\n- Build UI components for maximum performance and reusability\n- Participate in code reviews and contribute to team knowledge sharing.\n- Troubleshoot and debug applications.\n- Stay up-to-date with the latest industry trends and technologies.\n\nYour skills and experience\nMUST-HAVE SKILLS:\n- At least 4 years of experience in Angular and its core principles.\n- Familiarity with HTML, CSS, and JavaScript/Typescript.\n- Experience with responsive design frameworks (like Bootstrap, Angular Material,...)\n- Familiarity with state management libraries (such as NgRx)\n- Knowledge of RESTful APIs and web services.\n- Experience with GIT source control, Agile process\n- Strong problem-solving skills and attention to detail.\n- Good communication and teamwork skills.\n- Eagerness to learn and adapt to new technologies.\n- Possesses the ability to communicate in English fluently and naturally in a professional setting, as well as the capability to present or discuss technical issues in detail.\n\nNICE TO HAVE:\n- Have experience in LLMs, Cursor, Github Copilot,...\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- Have experience in Electron,Tauri\n- Have experience in Reactjs, Vuejs, NodeJs, WEB API\n- Have experience in database such as Posgresql, Mongodb, MySql, DynamoDB,...\n\nWhy you\'ll love working here\nCompetitive Salary and Brilliant Health Benefits:\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan\n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program\n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment:\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support.\n- Surrounded with friendly, open-minded, young and supportive colleagues\n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training:\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Orchard Parkview, 130 – 132 Hong Ha, Ward 9, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(970, 238, 2, 'Chuyên viên Quản trị CSDL- Database Administrator (DBA)', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Quản lý đảm bảo hoạt động của hệ thống CSDL toàn ngân hàng bao gồm một hoặc nhiều các loại CSDL sau: MongoDB, PostgreSQL, NoSQL, Oracle, SQL Server, MySQL/MariaDB.\n- Triển khai, cấu hình, giám sát tối ưu hiệu năng, thực hiện thay đổi, nâng cấp phiên bản hệ thống CSDL.\n- Xây dựng và áp dụng các giải pháp dự phòng, công cụ giám sát CSDL (Grafana/Prometheus,...) và công cụ tự động hóa trong vận hành hệ thống.\n- Tham gia các dự án của ngân hàng liên quan đến hệ thống dữ liệu.\n\nYour skills and experience\n- Tốt nghiệp đại học chính quy ngành Công nghệ thông tin, Toán tin, Điện tử viễn thông,...\n- Chấp nhận ứng viên mới/chuẩn bị tốt nghiệp, yêu cầu tốt nghiệp loại Khá trở lên.\n- Ưu tiên có kinh nghiệm xây dựng công cụ giám sát (Prometheus/Grafana) hoặc quản trị phần mềm ETL.\n- Có kinh nghiệm về SQL/PLSQL, bash shell, Linux/Unix/Windows.\n- Có chứng chỉ MariaDB, OCA, OCP của Oracle, MS SQL Server hoặc tương đương là lợi thế.\n- Kỹ năng nghiên cứu, viết tài liệu, thuyết trình, phân tích và giải quyết vấn đề tốt.\n- Khả năng làm việc nhóm và độc lập tốt.\n- Tiếng Anh tốt, có thể làm việc trực tiếp với đối tác nước ngoài.\n- Trung thực, cẩn trọng, chịu được áp lực cao.\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương.\n- Cơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng.\n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng.\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n- Môi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng.\n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(971, 604, 2, 'Senior Data Engineer (Python, SQL)', 'Overall Job Purpose\nThe Senior Data Engineer will be part of Data Engineering team which is creating, maintaining, scaling and improving the enterprise data platform providing the data for AI/Data Science solutions, applications/tools, and other digital use cases.\n\nCore Responsibilities\nDesign, develop, and maintain robust, scalable and sustainable data products and build & optimize data pipeline and infrastructure.\nCollaborate with stakeholders to understand their data requirements and translate them into technical solutions.\nIdentify and implement data quality monitoring and validation processes to ensure data integrity.\nImplement data quality frameworks and ensure data governance best practices, including data lineage, data documentation, and data security.\nBuild out the infrastructure required for optimal extraction, transformation, and loading of data from a wide variety of data sources using Synapse, ADF, Spark, Kafka, or similar technologies.\nWork closely with Data Analysts and Data Architect to support their data needs and enable advanced analytics and machine learning initiatives.\nContribute to the development of the organization\'s data strategy, including evaluating new technologies, tools, and frameworks to enhance the data engineering ecosystem.\n\nYour skills and experience\nEducational Qualification & Experience:\nBA/BS degree in Computer Science, Computer Engineering, Electrical Engineering or related technical field\n4-8 years to total IT experience preferably in field of data engineering\n4+ years\' experience with Azure services including IAM, Synapse, DataLake, SQL Server, ADF etc.\n2+ years\' experience in creating and deploying docker containers on Kubernetes.\n2+ years\' experience in supporting development teams on Kubernetes best practices, troubleshooting, and performance optimization.\n2+ years\' experience with CI/CD pipelines toll such as Jenkins and GitHub Actions\n2+ years\' experience with Synapse data warehousing and data lake solutions\nStrong programming skill in Python, PySpark and SQL\n4+ years of experience in scripting and automation using languages such as Bash, Python, or Go2+ years of experience with infrastructure-as code tools such as Terraform, Ansible, or CloudFormation and containerization technologies (e.g., Docker, Kubernetes).\nKnowledge of Agile methodologies and software development lifecycle processes\nProven experience in designing and implementing large-scale data solutions, including data pipelines and ETL processes on Azure.\n\nRequired Knowledge:\nTroubleshoot and resolve data-related issues, performance bottlenecks, and scalability challenges on Azure\nSolid understanding of DevOps principles and experience with infrastructure automation using tools like Terraform or CloudFormation.\nHands-on experience with cloud platforms - Azure, and related services (e.g., Synapse, Data Lake, etc.).\nUnderstandings of data warehousing concepts and best practices\nWork closely with stakeholders to understand business requirements and translate them into data solution designs.\nStrong understanding of data architecture principles, data modelling techniques, and data integration patterns.\n\nLanguage(s) and Software:\nExcellent in English (speaking and writing)\n\nKey Behaviors:\nSoft Skills (Professional) List maximum 3\na) Excellent communication skills with a strong technology focus.\nb) Excellent analytical abilities.\nc) Problem Solving – providing sustainable solutions.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '215 Nguyen Van Thu, Da Kao ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(972, 519, 2, 'Mobile Developer (Flutter)', 'Phát triển và bảo trì các ứng dụng di động trên nền tảng iOS và/hoặc Android.\nThiết kế, xây dựng và triển khai các tính năng mới cho ứng dụng.\nViết code sạch, hiệu quả và dễ bảo trì.\nThực hiện kiểm thử đơn vị và tích hợp.\nCải thiện hiệu suất và khả năng mở rộng của ứng dụng.\nHợp tác với các thành viên khác trong nhóm để hoàn thành dự án.\nĐáp ứng các yêu cầu kỹ thuật và thời hạn dự án.\nNghiên cứu và áp dụng các công nghệ mới vào dự án.\n\nCó ít nhất 01 năm kinh nghiệm phát triển ứng dụng Mobile trên nền tảng Android hoặc iOS.\nThành thạo ít nhất một trong các ngôn ngữ hoặc thư viện sau: \n• Dart/Flutter\n• Kotlin (Android)\n• Objective-C/Swift (iOS)\n• JavaScript/React Native\nHiểu biết sâu về OOP, biết cách sử dụng và tối ưu hóa hiệu suất code trong Flutter.\nThành thạo các Dart Collections như: List, Set, Map và các phép xử lý nâng cao: where, map, fold, expand, any, every, collection if, collection for, v.v.\nTư duy tốt về thiết kế UI/UX, tuân theo guideline của từng nền tảng.\n\nCó kinh nghiệm trong việc tối ưu: \n• Trải nghiệm người dùng (UX)\n• Hiệu suất ứng dụng (Performance)\n• Dung lượng ứng dụng (App size)\n\nKiến thức & kỹ năng bổ trợ:\nThành thạo quản lý trạng thái bằng một trong các thư viện: • Riverpod (ưu tiên)\n• Bloc\n• GetX\nCó khả năng làm việc độc lập và phối hợp nhóm hiệu quả.\nChủ động, sáng tạo, có tinh thần trách nhiệm cao, đảm bảo tiến độ công việc.\n\nƯu tiên:\nCó kinh nghiệm làm việc trong các quy trình hiện đại như: Scrum, Agile, OKRs\nCó khả năng đọc hiểu và tra cứu tài liệu tiếng Anh\nCó sản phẩm thực tế đã phát hành trên App Store hoặc Google Play\nCó kinh nghiệm phát triển Hybrid App bằng Flutter\nHiểu biết về kiến trúc Clean Code, Separation of Concerns.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2, tòa nhà văn phòng HL Tower, số 6 ngõ 82 phố Duy Tân, Phường Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(973, 605, 2, 'Junior/Middle Business Analyst (UI/UX, Agile)', 'Top 3 reasons to join us\n• Xét duyệt tăng lương định kỳ.\n• Môi trường làm việc thân thiện, năng động\n• Tham gia các chương trình đào tạo\n\nJob description\n• Tiến hành khảo sát, thu thập yêu cầu và các hạng mục công việc từ khách hàng, nhân sự các phòng ban, đánh giá tính khả thi và tác động có liên quan.\n• Lên ý tưởng thiết kế bằng storyboards, sơ đồ quy trình và sitemaps.\n• Thiết kế prototye (Mockup) cho sản phẩm, giao diện người dùng.\n• Tạo và quản lý hệ thống tài liệu: tài liệu đặc tả yêu cầu, đặc tả hệ thống, danh sách tính năng, hướng dẫn sử dụng phần mềm.Tổ chức hướng dẫn, hỗ trợ cho người sử dụng sản phẩm và xử lý sự cố khi vấn đề xảy ra.\n\nYour skills and experience\n• Yêu cầu: Nam/ nữ: 24- 35 tuổi, đã tốt nghiệp Đại học\n• Junior gần 1 năm KN: 8-12 triệu/tháng\n• Kinh nghiệm 2-3 năm trở lên tại vị trí tương đương\n• Có các kỹ năng: Phân tích và giải quyết vấn đề, lập kế hoạch, thuyết trình, giao tiếp và làm việc nhóm.\n• Có kiến thức về quy trình phát triển phần mềm Agile, Waterfall....\n• Sử dụng thành thạo các techniques như: Brainstorming; Backlog Management; Use Cases and Scenarios; User Stories; Business Rules Analysis\n• Đọc hiểu Tiếng Anh tốt.\n• Có khả năng tư duy và phân tích tốt.\n• Có khả năng làm việc độc lập và tự nghiên cứu, ứng dụng.\n• Làm việc thông minh, chú ý tới chi tiết, tuân thủ tiến độ được giao.\n\nWhy you\'ll love working here\n• Thu nhập:\n• Junior gần 1 năm KN: 8-12 triệu/tháng\n• 2-3 năm KN trở lên: 16 - 22 triệu/ tháng,  \n• Phụ cấp ăn trưa, thưởng lễ tết, lương tháng thứ 13\n• Chế độ sinh nhật, ốm đau, hiếu hỉ, thai sản, bảo hiểm ...theo quy định.\n• Môi trường làm việc thân thiện, năng động, đồng nghiệp nhiệt tình.\n• Tham gia các chương trình đào tạo nội bộ/ khóa học nâng cao nghiệp vụ\n• Xét duyệt tăng lương định kỳ.\n\nĐịa điểm làm việc: Discovery Complex 302 Cầu Giấy, Dịch Vọng, Cầu Giấy, Hà Nội\nThời gian làm việc:  Từ thứ 2- thứ 5: 8h-18h, thứ 6: 8h-17h. Nghỉ thứ 7, Chủ nhật', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 38 tòa Discovery Complex 302 Cầu Giấy, Dịch Vọng, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(974, 606, 2, 'AI Engineer (Senior/Expert)-Analytical AI, LLMs, GenAI', 'VPBank hiện là một trong những Ngân hàng có tốc độ tăng trưởng nhanh nhất tại Việt Nam, cung cấp đa dạng các dịch vụ và được nhiều khách hàng tin dùng. VPBank đặc biệt chú ý đến việc nâng cao hiệu quả hoạt động qua việc phân tích các dữ liệu kinh doanh.\n\nMục đích của vị trí:\nChịu trách nhiệm chính trong việc triển khai, tham mưu cho Giám đốc Trung tâm và/hoặc Trưởng phòng trong việc lập kế hoạch và phối hợp với đơn vị kinh doanh, đơn vị hỗ trợ kinh doanh và các trung tâm/phòng ban khác trong nội bộ khối EDA.\nDẫn dắt và chịu trách nhiệm chính việc ứng dụng các phương pháp phân tích nâng cao, học máy, học sâu và/hoặc GenAI để xây dựng ứng dụng AI/phân tích hệ thống dữ liệu phức tạp, tìm kiếm các hiểu biết sâu sắc về hành vi khách hàng và đưa ra các khuyến nghị chiến lược có giá trị cho đơn vị.\nĐóng vai trò cố vấn chuyên môn, hướng dẫn phát triển năng lực kỹ thuật trong nhóm\n\nNhiệm vụ chính: \n1. Lập kế hoạch và phối hợp triển khai sáng kiến phân tích nâng cao, AI/ML/GenAI\n- Tham mưu cho Trưởng phòng trong việc xây dựng kế hoạch triển khai các sáng kiến phân tích nâng cao, học máy, học sâu và/hoặc GenAI phù hợp với định hướng chiến lược.\n- Chủ động phối hợp với các đơn vị kinh doanh, hỗ trợ kinh doanh và các phòng/ban liên quan trong nội bộ Khối EDA để xác định bài toán, thống nhất yêu cầu, thiết kế giải pháp và phương án triển khai.\n\n2. Chủ động triển khai các giải pháp khoa học dữ liệu và trí tuệ nhân tạo cho các đơn vị trong ngân hàng\n- Dẫn dắt định hướng kỹ thuật và chịu trách nhiệm chính các giải pháp phân tích nâng cao, AI/ML/GenAI cho các bài toán chiến lược hoặc có độ phức tạp cao, có khả năng tạo ra tác động lớn đến hoạt động kinh doanh, vận hành hoặc trải nghiệm khách hàng toàn hàng.\n- Thiết kế và giám sát triển khai các sản phẩm dữ liệu hoặc mô hình AI/ML/GenAI có khả năng tái sử dụng và mở rộng quy mô, đóng vai trò then chốt trong các sáng kiến quan trọng nhắm thúc đẩy kinh doanh, tối ưu hóa kênh tiếp cận, tự động hóa vận hành, ra quyết định thông minh và cá nhân hóa hành trình khách hàng.\n- Tư vấn kỹ thuật cho các phòng ban nghiệp vụ, giúp định hình bài toán kinh doanh thành các giải pháp phân tích cụ thể và khả thi; đồng thời đảm bảo việc lựa chọn thuật toán, kiến trúc mô hình, pipeline dữ liệu và các công nghệ nền tảng là phù hợp và tối ưu.\n- Thực hiện hoặc giám sát phân tích khám phá dữ liệu chuyên sâu và khai thác insight chiến lược, giúp Ban điều hành, các khối kinh doanh/vận hành thấu hiểu khách hàng, xác định cơ hội tăng trưởng, hoặc phát hiện rủi ro tiềm ẩn.\n- Tham gia đánh giá và giám sát chất lượng toàn bộ vòng đời mô hình, bao gồm việc thiết kế hệ thống giám sát mô hình (model monitoring), đánh giá drift, lên kế hoạch re-training và kiểm soát rủi ro mô hình (model risk).\n- Đóng vai trò cố vấn chuyên môn (technical mentor) cho các chuyên viên trong nhóm/phòng/bộ phận khác, hỗ trợ phát triển năng lực nội bộ, lan tỏa thực hành tốt và xây dựng năng lực AI/ML/GenAI bền vững cho tổ chức.\n- Chủ động cập nhật, thử nghiệm và lan tỏa các công nghệ, phương pháp mới trong lĩnh vực AI/ML/GenAI (như foundation models, vector database, agentic workflows…), góp phần giúp ngân hàng bắt kịp và đón đầu xu hướng công nghệ.\n\n3. Nghiên cứu & cập nhật kỹ thuật, công nghệ mới\n- Thường xuyên nghiên cứu, cập nhật các xu hướng, kỹ thuật tiên tiến trong lĩnh vực phân tích dữ liệu, học máy, học sâu và/hoặc GenAI theo định hướng từ cấp quản lý hoặc chuyên gia nội bộ.\n- Chủ động tìm hiểu và dẫn dắt, thử nghiệm các công nghệ, framework và mô hình mới để nâng cao hiệu quả triển khai giải pháp dữ liệu và AI tại ngân hàng.\n- Tích cực tham gia các diễn đàn chuyên môn, hội thảo nội bộ/ngoại bộ, seminar nhằm mở rộng kiến thức và chia sẻ kinh nghiệm thực tiễn với đội nhóm.\n- Tham gia hỗ trợ đào tạo, hướng dẫn cho các thành viên cấp thấp hơn trong nhóm khi được phân công.\n- Chủ động chia sẻ, huấn luyện hoặc xây dựng tài liệu nội bộ nhằm lan tỏa kiến thức và thúc đẩy đổi mới sáng tạo.\n\n4. Thưc hiện các công việc khác theo phân công của cấp thẩm quyền\n\nYour skills and experience\n- Tốt nghiệp Đại học trở lên trong các lĩnh vực liên quan như: Khoa học Máy tính (Computer Science), Toán học/Toán ứng dụng (Mathematics/Applied Mathematics), Thống kê (Statistics), Kỹ thuật (Engineering), Khoa học Dữ liệu (Data Science), Kinh tế lượng, Tài chính định lượng (Econometrics, Quantitative Finance), hoặc các ngành liên quan đến phân tích dữ liệu và xử lý thông tin.\n- Tối thiểu 5–7 năm kinh nghiệm trong phân tích nâng cao, phát triển mô hình học máy/học sâu và/hoặc triển khai ứng dụng AI/GenAI phục vụ mục tiêu kinh doanh rõ ràng.\n- Có kinh nghiệm dẫn dắt kỹ thuật trong các dự án AI/ML/GenAI từ phân tích yêu cầu đến triển khai, giám sát và cải tiến mô hình.\n- Thành thạo triển khai giải pháp trên các nền tảng cloud (AWS, Azure, GCP, Databricks...), bao gồm quy trình CICD, API hóa mô hình, auto retraining,…\n- Có kinh nghiệm làm việc chéo với nhiều đơn vị (business, IT, compliance, vận hành) để đảm bảo tính thực tiễn, an toàn và hiệu quả khi triển khai ứng dụng phân tích nâng cao.\n- Đã từng đóng vai trò mentor hoặc đào tạo nội bộ cho đội nhóm hoặc các chuyên viên cấp dưới.\n- Ưu tiên ứng viên có kinh nghiệm làm việc tại ngân hàng lớn, tổ chức tài chính, hoặc môi trường có dữ liệu lớn và độ phức tạp cao.\n- Nắm chắc kiến thức về các mô hình thống kê, kỹ thuật dự báo, thuật toán học máy, học sâu và/hoặc GenAI; có khả năng lựa chọn và áp dụng phù hợp với bài toán thực tế.\n- Có khả năng vận dụng các kỹ thuật phân tích thống kê, kiểm định giả thuyết và phân tích dữ liệu phức tạp; có khả năng đưa ra các phân tích và khuyến nghị mang tính thực tiễn cao.\n- Thành thạo Python và các thư viện phổ biến phục vụ cho phân tích nâng cao, học máy, học sâu (như Pandas, Scikit-learn, TensorFlow, PyTorch) và GenAI (Transformers, LangChain...).\n- Hiểu và có thể tuân thủ quy trình phát triển dự án phân tích dữ liệu nâng cao – từ xử lý dữ liệu, huấn luyện mô hình, đánh giá đến triển khai ứng dụng AI/ML/GenAI vào thực tế.\n- Kỹ năng trình bày, thuyết phục và kết nối tốt với các bên liên quan kỹ thuật và phi kỹ thuật (business owner, vận hành, IT), giúp thúc đẩy quá trình triển khai AI/ML vào thực tiễn.\n- Kỹ năng mentoring, có khả năng hỗ trợ phát triển năng lực cho các thành viên cấp dưới hoặc các bạn trẻ trong nhóm.\n- Kỹ năng tư duy phản biện và phân tích đa chiều, có thể đánh giá các giải pháp phân tích dưới góc nhìn kỹ thuật, kinh doanh và rủi ro.\n- Có khả năng chủ động đề xuất sáng kiến, và chuyển hóa insight thành hành động cụ thể phục vụ mục tiêu kinh doanh.\n\nWhy you\'ll love working here\n- Thu nhập hấp dẫn, lương thưởng cạnh tranh theo năng lực (16-18 tháng lương/năm)\n- Thưởng các Ngày lễ, Tết cạnh tranh\n- Được vay ưu đãi với lãi suất hấp dẫn theo quy định của ngân hàng\n- Chế độ ngày phép 14-16 ngày phép/năm theo cấp bậc\n- Bảo hiểm sức khỏe VPBank care cho CBNV theo cấp bậc\n- Được tham gia các khóa đào tạo tùy thuộc vào Khung đào tạo cho từng vị trí\n- Môi trường làm việc năng động, thân thiện, có nhiều cơ hội học đào tạo, học hỏi và phát triển; được tham gia nhiều hoạt động văn hóa thú vị (cuộc thi về thể thao, tài năng, hoạt động teambuiding...)\n- Thời gian làm việc: Từ thứ 2 – thứ 6 & sáng thứ 7\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '89 Lang Ha, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(975, 607, 2, '(Senior) Golang Developer', 'Top 3 reasons to join us\n- We build a professional & fun working environment.\n- We focus on your growth, yes the long-term growth.\n- We develop the future-ready digital bank platform.\n\nJob description\nAs a Backend Developer (Golang), you will be entrusted with the responsibility of crafting high-quality solutions for premier investment banks globally. Your daily tasks will encompass working within a Scrum framework, developing innovative functionalities, conducting module testing, documenting your progress, and reporting to the Team Leader.\n\nKey Activities:\n- Backend Development: Design and construct advanced backend services using the Go programming language.\n- Collaboration: Work in synergy with cross-functional teams to conceptualize, design, and deliver new features.\n- Data Integration: Interface with external data sources and APIs.\n- Quality Assurance: Conduct unit tests on code for robustness, including edge cases, usability, and overall reliability.\n- Continuous Improvement: Continually discover, assess, and implement new technologies to optimize development efficiency.\n- Bug Fixing: Address bug fixing and enhance application performance.\n\nYour skills and experience\n- At least 2 years of experience as a Backend GoLang developer.\n- Demonstrable experience in software development.\n- Practical experience in backend development.\n- Profound familiarity with the Go programming language.\n- Experience with OOP, MVC Design Pattern, Clean Architecture, Go Routines, and Unit Tests.\n- Comprehensive understanding of the full backend development life cycle.\n- Experience with databases such as PostgreSQL or MySQL.\n\nWhy you\'ll love working here\nHR benefits\n- Competitive salary\n- Salary band per level are reviewed once per year\n- 13th month salary pro rata depending on the employee’s length of service (within a calendar year), paid with the December salary\n- Monthly lunch allowance: 700,000 VND/employee\n- Parking: GFT covers the monthly parking fee for employee motorbikes\n- Performance evaluation is once per year, for 2 purposes:\n  > Performance bonus   > Salary increments\nHealth care\n- Private health insurance: including accident, outpatient, in-patient, maternity, and dental for all permanent employees who pass 2-month probation.\n- Optical: expense claim for eyewear\n- Annual health check-ups.\nVacation\n- Maximum 18-day vacation leave/year (with the ability to carry over 05 days till 31st March of the following year)\n- Adding one more annual leave day for each two-year anniversary.\nHealthy lifestyle\n- Sports and hobby clubs: company has an annual fund for fitness activities, which is allocated per month as team’s vote.\n- Range of healthy snacks, tea, coffee, milk and beer on tap\nSocial\n- Company townhall: each 6 weeks\n- CSR activities: as per company’s CSR guideline\n- Onsite tour/training courses at other GFT offices and client’s destination overseas (where applicable).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '29A Nguyen Dinh Chieu, District 1, Ho Chi Minh & 174 Thai Ha, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(976, 608, 2, 'iOS Developer (Swift)', 'Job description\n- Tham gia phát triển các dự án iOS: Bạn sẽ làm việc trực tiếp trên các dự án iOS, giúp phát triển ứng dụng và cải thiện chất lượng sản phẩm.\n- Làm việc theo nhóm dưới sự hướng dẫn của cấp trên: Bạn sẽ làm việc trong môi trường nhóm, phối hợp với các thành viên khác để đạt được mục tiêu chung.\n- Đảm bảo tiến độ và chất lượng công việc: Bạn cần duy trì chất lượng công việc cao và đảm bảo hoàn thành đúng tiến độ đã đề ra.\n\nYour skills and experience\n- 3-6 tháng kinh nghiệm lập trình iOS: Có ít nhất 3-6 tháng kinh nghiệm lập trình iOS hoặc có dự án thực tế tương tự.\n- Thành thạo Swift, biết SwiftUI là lợi thế: Bạn phải có kỹ năng vững với Swift, nếu có kinh nghiệm với SwiftUI thì sẽ là điểm cộng.\n- Sử dụng tốt UIKit, Auto Layout, Storyboard: Bạn cần nắm vững các công cụ và thư viện cơ bản như UIKit, Auto Layout để thiết kế giao diện người dùng.\n- Biết làm việc với RESTful API, JSON: Bạn cần có khả năng làm việc với các API, hiểu cách xử lý dữ liệ̂u JSON trong ứng dụng.\n- Có kinh nghiệm sử dụng Firebase, Google Cloud Platform Services: Kinh nghiệm làm việc với các công cụ của Google sẽ là một lợi thế.\n- Hiểu về lưu trữ dữ liệu cục bộ (UserDefaults, Realm, Core Data...): Bạn cần biết cách sử dụng các công cụ lưu trữ dữ liệu như UserDefaults, Realm, hoặc Core Data.\n- Ham học hỏi, chủ động, tư duy logic tốt: Bạn cần có tinh thần học hỏi và khả năng giải quyết vấn đề tốt.\n\nWhy you\'ll love working here\n- Hỗ trợ lương trong thời gian thực tập/thử việc: Bạn sẽ được nhận lương trong suốt thời gian thực tập học hoặc thử việc\n- Cơ hội học hỏi, nâng cao kỹ năng và được đào tạo chuyên sâu về lập trình iOS.\n- Tham gia dự án thực tế, có cơ hội trở thành nhân viên chính thức: Bạn sẽ được làm việc trên các dự án thực tế và có cơ hội trở thành nhân viên chính thức nếu thể hiện tốt.\n- Môi trường làm việc năng động, chuyên nghiệp: Bạn sẽ làm việc trong một môi trường thân thiện, đầy thử thách và chuyên nghiệp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '60 Le Quang Dao, Ngu Hanh Son, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(977, 345, 2, '[Da Nang & HCM] QA/QC Engineer', 'Job Description:\nWe are looking for a skilled and detail-oriented Manual QA/QC Engineer to join our team. A minimum of one year\'s expertise in quality assurance and quality control processes is required. As a Manual QA/QC Engineer, you will be responsible for ensuring the high quality and dependability of our products.\nResponsibilities:\n- Conduct manual testing of software applications and systems to identify defects and ensure functionality meets quality standards.\n- Collaborate closely with cross-functional teams, including developers, and product managers, to understand project requirements and user expectations.\n- Create detailed test plans, test cases, and test scripts that effectively cover all aspects of the software, including edge cases and user scenarios.\n- Execute test cases and document test results, including defects and issues found during testing.\n- Identify, report, and track defects using designated tools, and work with the development team to ensure timely resolution.\n- Participate in regular team meetings to discuss project progress, potential issues, and improvements to the QA/QC process.\nYour skills and experience:\nMust have:\n- Bachelor\'s degree in computer science, Engineering, or a related field (or equivalent work experience).\n- More than 1.5 years in a similar role.\n- Design, write test cases and execute test cases\n- Ability to analyze problems in detail, helping engineers determine the root cause in order to resolve the issue quickly.\n- Own work planning and reporting\n- Ability to read & understand English documents.\nNice to have:\n- Experience in API testing.\n- Experience working within an Agile environment.\n- Have domain knowledge ERP, SAP is a plus\n- Have good spoken of English.\nWhy you\'ll love working here:\n- 15 days of annual leaves\n- Competitive salary (+13-month salary include) \n- Health insurance, social insurance according to the government regulations \n- PVI Healthcare Insurance \n- Have a chance to work in an international, friendly, open environment \n- Annual Travel opportunity', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '324 Le Van Sy, Ward 2, Tan Binh, Ho Chi Minh & 199 Dong Da, Thach Thang, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(978, 609, 2, 'Chuyên Viên ERP (SQL, English)', 'Job description\nDaily Operations (40%): Ensure stable ERP performance, monitor error logs, coordinate with vendor for bug fixes.\nSystem Improvement (25%): Propose and test new features or modules, ensure upgrades align with business needs.\nUser Support (20%): Train new users, create manuals, resolve support tickets.\nReporting (15%): Work with departments to improve existing reports and dashboards.Being involved in decision-making processes\nYour skills and experience\nTuổi từ 24t đến 45t.Có kinh nghiệm từ 2 năm trở lên.\nTốt nghiệp Đại Học các ngành có liên quan.\nTốt nghiệp đại học chuyên ngành Hệ thống thông tin quản lý, Công nghệ thông tin, Quản trị kinh doanh, Tài chính – Kế toán hoặc các ngành liên quan\nÍt nhất 2 năm kinh nghiệm triển khai hoặc hỗ trợ hệ thống ERP\nCó kinh nghiệm viết truy vấn SQL, script\nƯu tiên ứng viên hiểu rõ quy trình sản xuất, đặc biệt trong ngành dệt may\nHiểu biết về cấu trúc BOM (Bill of Materials) và ứng dụng trong lập kế hoạch sản xuất\nTiếng Anh giao tiếp tốt 4 kỹ năng\nWhy you\'ll love working here\nLàm việc từ 8h00 đến 17h(trưa nghỉ 1 tiếng)Từ thứ 2 đến thứ 6.\nLương thỏa thuận theo năng lực\nMức lương: Thỏa thuận theo năng lực\nPhụ cấp cơm trưa: 35,000 vnd/ ngày.(thanh toán vào lương)\nPhụ cấp nước uống: 10,000 vnd/ ngày.(thanh toán vào lương)\nChế độ: tham gia BHXH sau 2 tháng thử việc, thử việc 100% lương và tham gia BHXH full lương.\nLƯƠNG THÁNG 13, Lễ tết…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lô C28-C29, Đường 16, Khu Công Nghiệp Hiệp Phước, Xã Hiệp Phước, Nha Be, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(979, 610, 2, 'IT MIS Executive (ERP, Data Analysis, English)', 'Summary of Position\nAnne Hill International School (AHIS) seeks a highly motivated and experienced MIS Executive (Helpdesk) to join our growing team. You have experience with School Information System (SIS) experience and have at least 2 successful implementations will have an advantage. SIS knowledge should include, but not limited to Person Records Management, Teaching Management, Timetable management, School Reporting, Admissions/Registrations, Enrollment cycles, Fee management, Activities/ECA management, Student Care, Facilities Management, and portal management for students, teachers and parents would be advantageous.\n\nResponsibilities\n- Provide technical support and troubleshooting for staff and students.\n- Manage and maintain the school’s SIS and other software applications.\n- Assist with the implementation of new IT systems and upgrades.\n- Develop and deliver training to staff on IT systems and software.\n- Ensure data integrity and security.\n- Coordinate and work with overseas vendors.\n- Manage user expectations and provide excellent customer service.\n- Work on weekends and late nights when necessary.\n-  Work under tight timelines and management pressure\n- Other requirements by line manager\n\nYour skills and experience\nEducation\n- Bachelor’s degree in IT, Computer Science, or a related field.\n- Relevant certifications in IT service management or ERP systems.\n\nShared requirements:\n- Must be able to speak and write in English. Communication is important as we coordinate and work with overseas vendors.\n- Must have successfully completed at least 2 full ERP implementation cycles.\n- Must have strong analytic skills and the ability to learn new domain processes quickly\n- Must have at least 2 years SaaS experience\n- Ability to communicate and present to work team stakeholders as well as project leaders\n- Must be able to work on weekends and late nights when necessary\n- Must be able to work under tight timelines and management pressure\n- Must be skilled in multitasking, problem solving, root-cause analysis, and managing users’ expectations\n- Must have strong work ethics and critical thinking abilities\n- Nice to have report writing, KPI/Dashboard development, and Business Intelligence skills with at least 2 years of experience\n\nFinance MIS executive:\n- Must have full understanding of Finance modules and features within standard ERP solutions\n- Must have full understanding of accounting practices\n- Must have at least 5 years experience in Finance implementation and Post-Live support\n- Nice to have Sales, Distribution, and/or Procurement domain experience/knowledge\n- Nice to have actual end-user experience in Finance\n\nSales, Distribution, and Procurement MIS executive:\n- Must have full understanding of Sales, Distribution, and Procurement modules and features within standard ERP solutions\n- Must have at least 5 years experience in these domains for implementation and Post-Live support\n- Nice to have Finance domain experience/knowledge\n- Nice to have actual end-user experience in Sales, Distributions, and/or Procurement\n\nWhy you\'ll love working here\n- Free school meals\n- Housing allowance \n- Medical insurance \n- School leave for break term', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '19 Giang Van Minh, An Phu, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(980, 356, 2, 'DevOps Engineer (Junior/Middle)', 'JOB DESCRIPTION\n\nDesign and manage Kubernetes Helm charts and CI/CD pipelines for secure, scalable rollouts.\nOperate and secure Linux-based infrastructure\nManage PostgreSQL\nDesign, implement, and manage cloud infrastructure on platforms such as AWS\nDevelop and maintain robust CI/CD pipelines using tools like Jenkins, GitLab CI/CD, GitHub Actions, AWS Codebuild, AWS CodePipeline\nAutomate infrastructure deployments using Infrastructure as Code (IaC) tools such as Terraform\nImplement comprehensive monitoring, logging, and alerting solutions using tools such as ELK\nProactively identify technical gaps in existing solution designs, conduct research and development to propose improvements, and take the lead in executing and implementing the recommended solutions.\nEnsure systems adhere to security best practices, perform security assessments, and apply patches proactively.\n\nYour skills and experience\n\nMUST HAVE:\n\nAt least 2 years of experience in DevOps roles, especially in international software projects\nExperience with public cloud platforms: AWS\nExperience with following languages: powershell script, bash script\nFamiliarity with databases and messaging systems: PostgreSQL\nExperience with Docker, Kubernetes or another container based system\nExperience with IaC tools: Terraform\nExperience with logging system Kibana\nExperience with Jenkins or similar tools\nFamiliarity with networking concepts (TCP/IP , DNS, firewalls, load balancers)\nMUST be good at verbal/non verbal English\n\nNICE TO HAVE:\n\nExperience with one of the following tools: Ansible, Team City, Github Action\nWilling to work over the weekend to when production server have issues\nExperience to migrate on-premise system into cloud\n\nWhy you\'ll love working here\n\nAt Saigon Technology, we believe that "Your success is our mission"\n\nCompetitive Salary and Brilliant Health Benefits\nAttractive salary (13th-month salary, salary review twice/year) and project bonus\nBonus programs for candidate referral, technical article writing\nInterest-free loan support for personal plan\nAllowance for sickness, maternity and paternity and Periodic health examination\nPVI health care program The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\nA professional English-speaking working environment with Agile – Scrum model\nHybrid Working Model: Flexible working time and WFH support.\nSurrounded with friendly, open-minded, young and supportive colleagues Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\nSponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\nSponsor fee for joining any technical training sessions and courses.\nFree English workshops\n\nFOR MORE DETAILS: \nFanpage: \nWebsite: \n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Orchard Parkview, 130 – 132 Hong Ha, Ward 9, Phu Nhuan, Ho Chi Minh / 17th Floor, 36 Tran Quoc Toan, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(981, 592, 2, 'Bridge Engineer (BrSE,Project Manager)', 'Overall:\n- Make a bridge to facilitate offshore development projects.\n- Explanation of development policies and specifications to engineers.\n- Detailed confirmation of specifications.\n- Help with taking communication between Vietnamese engineers and Japanese engineers.\n- Detail requirement for Senior ~ Leader level:\n- 開発において上流工程のすべての経験あり（要求分析、要件定義、基本設計、詳細設計）\n- BSEの指導、育成経験あり\n- 日本側のPMのサポートなしでプロジェクト管理できる\n- BSEの日本側とのコミュニケーション指導経験あり\n\nYour skills and experience\n- Age: 25 -38\n- Must:\n  - Experience in working with software developers \n  - Experience in being Project Manager\n  - Japanese skill: Equivalent to N2 or N1\n  - English skill : Basic ~ Pre-intermediate\n  - Open for candidate with strong experience of IT Communicator (from 3 years above) with career path to become BrSE \n- Preferable: Experienced in team building\n- Recruitment Process: Test → 1st interview → Final interview → Offer \n- CV required language: Japanese\n\nWhy you\'ll love working here\n- Annual Leave: 15 days/ year\n- Flexible Working Time (Hybrid Working) \n- 100% Salary in Probation\n- Salary Review (Twice a Year) \n- 13th Salary bonus\n- Social Insurance for 100% Salary\n- Travel Allowance\n- Premium Health Care Insurance for employees (PTI)\n- Annual Health Check \n- Device Fully Provide, Monitor,…\n- Monthly Happy Hour, Company Trip, Year End Party and Events\n- Marriage / Baby Gift\n- Funeral Expenses\n- Referral Bonus\n- Skill Improvement Course for Employees (Udemy)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor An Phu Plaza, Vo Thi Sau Ward, District 3, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(982, 239, 2, '[Women Leadership in Tech] Embedded Engineering Manager', 'We’re empowering and promoting Women Leadership roles in Software Engineering within the Automotive domain.\nThe Embedded Software Engineering Manager/ Program Manager will be responsible for oversee and coordinate a portfolio of related projects, aligning program objectives with organizational goals, managing cross-functional teams, and ensuring successful delivery within scope, time, and budget constraints.\n\nKey Responsibilities\n- Plan, manage, and monitor programs from initiation through completion.\n- Coordinate multiple related projects to achieve strategic business goals.\n- Define program scope, objectives, and deliverables in collaboration with senior stakeholders.\n- Develop detailed work plans, schedules, project estimates, and status reports.\n- Lead program governance, including risk management, resource allocation, and performance tracking.\n- Communicate program status, issues, and milestones to stakeholders and executive leadership.\n- Manage and mentor project managers or team leads working on associated projects.\n- Ensure all projects under the program align with organizational standards and frameworks.\n- Identify interdependencies and mitigate risks across projects.\n- Scout for opportunities for expanding project / service business\n- Setting and aligning programs goals with organization goals & strategies\n- Steer the Programs / Projects in the portfolio by Leading the steering committee\n- Drive synergies amongst the Programs / Projects / Operations in the portfolio\n- Customer engagement and commitment with respect to portfolio / program scope\n- Introduce innovative approaches to project / program success\n\nYour skills and experience\nMust Have:\n- Bachelor’s or Master’s degree in Computer Science, Electrical & Electronics Engineering, or a related engineering field.\n- Above 15 years of experience, including at least 5 years in program management or 10 years in project management, with strong leadership and organizational skills.\n- Experience in embedded software development for Automotive domain.\n- Proven experience managing stakeholders across diverse countries and cultures.\n- Expertise in software requirements, development processes, and the full project lifecycle.\n- Proficient in V-Model and Agile methodologies for effective project execution.\n- Strong business acumen, including experience in project sponsorship, steering committee participation, and strategic alignment.\n- Demonstrated ability to lead complex, cross-domain, and cross-functional initiatives while managing large teams.\n- Excellent communication skills in English, both written and verbal, for effective stakeholder engagement.\n- Proficiency with project management tools such as MS Project, JIRA, or Asana.\n- The ideal candidate is collaborative, supportive, and thrives in team environments.\n\nNice to Have:\n- Certifications such as PMP, PgMP, or other relevant credentials.\n\nWhy you will love working here\nWhy BOSCH?\nBecause we do not just follow trends, we create them. Together we turn ideas into reality, working every day to make the world of tomorrow a better place. Do you have high standards when it comes to your job? So do we. At Bosch, you will discover more than just work.\n\nBenefits and Career Opportunities\n- Working in one of the Best Places to Work in Vietnam and Top 30 of the Most Innovative Companies all over the world\n- English-speaking environment, with opportunity to be part of innovation team and work in global projects\n- Onsite opportunities\n- Engage in our diverse training programs which surely help strengthen both your personal and professionalism\n- Flexible working time\n- 13th-month salary bonus + attractive performance bonus (you\'ll love it!) + annual performance appraisal\n- 100% offered salary and mandatory social insurances in 2-month probation\n- 15++ days of annual leave + 1-day of birthday leave\n- Premium health insurance for employee and 02 family members\n- Lunch and parking allowance\n- Good benefits of company activities such as: football, badminton, yoga, Aerobic, team building…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa street, ward 13, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(983, 353, 2, 'Data Engineering (Python, SQL, Oracle)', 'We are seeking a skilled and passionate data to join our Data team. The successful candidate will play a crucial role in designing, building, and managing our data systems, providing valuable insights to support strategic decision-making and drive business growth.\nResponsibilities:\n- Collaborate with the Data team to gather, collect, and synthesize data from various systems into the data warehouse\n- Design and implement data warehouse, data mart, and data dictionary architectures to meet business needs\n- Analyze data from multiple sources using advanced statistical and extract meaningful insights.\n- Develop and maintain comprehensive KPI reports to track business performance and inform decision-making.\n- Develop SBV reports\n- Partner with stakeholders across various departments, including business, sales, marketing, and IT, to gather requirements and communicate analysis results\n- Share data analysis knowledge and expertise with team members and conduct training sessions\nYour skills and experience\nSkills:\n- 2+ years of experience in data engineering, data operation, with a proven track record of success in large-scale and complex projects\n- Proficiency in data analysis programming languages such as PL/SQL, SQL, Python\n- Experience working with big data tools and platforms like Oracle, PostgreSQL, Spark.\n- In-depth knowledge of statistics, machine learning, and advanced data analysis techniques\n- Good at written and verbal communication skills\n- Strong collaboration and teamwork abilities\n- Creative problem-solving and critical thinking skills\n- Ability to learn quickly and adapt to new environments\nKnowledge:\n- Domain expertise in the finance, banking\n- Understanding of emerging data analysis trends and technologies\n- Bachelor\'s degree in Computer Science, University Of Science, or a related field\nBonus:\n- Experience with cloud platforms like AWS and Azure\n- Familiarity with Power BI\n- Understanding of financial concepts and banking products\nWhy you\'ll love working here\nHDBank tạo cảm giác nơi làm việc như là một ngôi nhà thứ hai để bạn thỏa sức sáng tạo và đam mê.\n- Thưởng 13,14 \n- Thưởng theo xếp loại \n- Bảo hiểm y tế, bảo hiểm tai nạn \n- Du lịch nghỉ mát hằng năm \n- Tăng lượng dịnh kì', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25 Nguyễn Thị Minh Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(984, 611, 2, 'SENIOR FLUTTER Developer', 'CHÚNG TÔI MUỐN CÙNG BẠN VƯƠN RA BIỂN LỚN\nChúng tôi đang tìm kiếm lập trình viên Flutter tài năng để tham gia phát triển ứng dụng quản lý bán hàng thông minh\nBạn có cơ hội được học hỏi không ngừng, phát triễn tư duy cùng kỹ năng lập trình, áp dụng kỹ thuật mới nhất để tạo ra sản phẩm chất lượng ưu việt cho hàng triệu người dùng. Hãy đến với chúng tôi để đưa sự nghiệp của bạn song hành với sự lớn mạnh của công ty.\n\nMô tả công việc\n- Thiết kế và xây dựng ứng dụng theo kiến trúc Clean Architecture đáp ứng hiệu suất cao, linh hoạt, dễ mở rộng bảo trì \n- Phát triển thành phần UI UX chuyên sâu có khả năng tái sử dụng cao, tối ưu hiệu suất hoạt động\n- Lập trình mã code đảm bảo tốc độ xử lý nhanh tối ưu trên nhiều dòng thiết bị Android / IOS,  code dễ test dễ bảo trì \n- Viết Unit test, debug và tối ưu hiệu suất hoạt động ứng dụng\n- Phối hợp các đội nhóm khác (API, QA/QC …) xây dựng phát triển và tích hợp API  các giải pháp dịch vụ bên thứ 3\n\nYour skills and experience\n- Ít nhất  2~3 năm kinh nghiệm phát triển và triển khai ứng dụng Flutter từ giai đoạn đầu và đẩy lên app store, play store \n- Tư duy logic tốt, khả năng giải quyết vấn đề, nắm vững thiết kế OOP , design pattern\n- Có khả năng xây dựng UI component library riêng, tối ưu hiệu suất hiện thị và có thể tái sử dụng cao\n- Khả năng viết code nhanh và chính xác theo đặt tả yêu cầu\n- Kinh nghiệm xử lý tối ưu bộ nhớ và hiệu suất ứng dụng \n- Có kinh nghiệm phát triển native app cho Android hoặc IOS\n- Có kinh nghiệm xây dựng ứng dụng chat/message  là  một lợi thế.\n\nWhy you\'ll love working here\n- Được phát triễn bản thân trong môi trường nhiều thử thách, trải nghiệm phát triễn sản phẩm trực tiếp cho người Việt và toàn cầu\n- Phát huy khả năng tìm hiểu áp dụng công nghệ mới vào sản phẩm thực tế, nâng cao kỹ năng lập trình, tiếp cận xử lý tối ưu dữ liệu lớn\n- Làm việc môi trường năng động cùng với đội ngũ chăm sóc khách hàng nhiệt tình dễ thương. Sếp luôn sẵn sàng ghi nhận các ý kiến đóng góp mọi thành viên\n- Định kỳ xét lương 2 lần/năm\n- Thưởng theo năng lực và kết quả công việc\n- Thưởng lương tháng 13\n- Teambuilding tổ chức sinh nhật hàng tháng, du lịch hàng năm\n- Chế độ nghỉ lễ tết, BHYT/BHXH/BHTN theo quy định của Luật Lao động.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '260/11 Nguyễn Thái Bình P.12 Tân Bình HS Building , Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(985, 504, 2, '[HN/ HCM] Fullstack Developer (PHP/ Laravel)', 'Top 3 reasons to join us\n- Salary: up to $3,000 Net or higher\n- 100% salary on probationary period\n- Bonuses for holidays and Lunar New Year’s Eve\n\nJob description\n- Develop and maintain robust, scalable web applications using PHP with frameworks such as Laravel, Yii2, or similar ones.\n- Design and implement front-end interfaces using HTML, CSS, and JavaScript frameworks such as Vue.js, React, or Angular.\n- Collaborate with cross-functional teams to define, design, and implement new features.\n- Identify and resolve issues in existing software applications.\n- Optimise application performance and ensure scalability.\n- Keep abreast of emerging technologies and industry trends.\n\nCandidates in Hanoi will work at the office - candidates in HCM will work remotely until the office setup is complete.\n\nYour skills and experience\n- Bachelor\'s degree in Computer Science, Information Technology, or related fields.\n- Must have 05+ years of experience working with PHP and at least one PHP framework such as Laravel, Yii2, or similar ones.\n- Proven experience in both front-end and back-end development of web applications.\n- Exceptional analytical and problem-solving skills.\n- Strong ability to work independently as well as collaboratively within a team.\n- Willing to work overtime or go on business trip.\n\nWhy you\'ll love working here\n- Salary: up to $3,000 Net or higher, depending on the candidate\'s performance assessment.\n- 100% salary on probationary period.\n- Bonuses for holidays and Lunar New Year’s Eve. Bonus base on monthly/ quarterly/ yearly business.\n- Company-sponsored annual vacation benefit.\n- Sponsor 100% of the costs of professional development courses relevant to the role (at the employee\'s request), with no reimbursement required upon resignation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(986, 227, 2, 'Technical Architect (ReactJs, NextJS)', 'Top 3 reasons to join us\n- Top-notch Annual Income\n- Global Health Insurance\n- 5-star Office in the centre of Hanoi\n\nJob description\nSystem Design & Architecture:\n- Define and oversee the architecture for scalable and maintainable NextJS applications.\n- Lead the design of reusable, modular components and efficient state management solutions.\n- Ensure best practices for responsive, accessible, and high-performance UI development.\n\nSystem Deployment & Maintenance:\n- Manage the deployment of NextJS applications with SSR and API integrations.\n- Work with Cloudflare, AWS S3, and other tools to ensure optimal performance.\n\nDevelopment & Code Review:\n- Write and review high-quality code, client-side rendering (CSR), and APIs.\n- Mentor team members in advanced Node.js and NextJS techniques.\n- Ensure timely delivery of high-quality features that improve operational workflows.\n\nProject Management:\n- Collaborate with stakeholders to define project scope, requirements, and timelines.\n- Plan, prioritize, and manage the delivery of technical tasks within an Agile framework.\n\nTeam Growth & Leadership:\n- Mentor and train team members in both technical and professional skills.\n- Encourage the team to stay updated with the latest frontend technologies and trends.\n- Lead knowledge-sharing sessions to keep the team updated with evolving frontend trends.\n\nYour skills and experience\nEducation:\n- Bachelor’s degree in Information Technology, Computer Science, or related fields.\nExperience:\n- 7+ years of frontend development experience, with at least 2 years in a leadership or technical lead role.\n- Strong expertise in ReactJS, NextJS, and modern JavaScript (ES6+).\n- Proficient in state management tools such as Redux, Recoil, or similar libraries.\n- Extensive experience in building responsive, cross-browser-compatible, and accessible web applications.\n- Advanced hands-on experience with Node.js, including developing APIs and optimizing SSR logic for scalable solutions.\n- Proficiency with frontend tools and workflows (e.g., Webpack, Vite, ESLint, Git).\n- Familiarity with AWS S3, Cloudflare, and similar tools for asset delivery and performance optimization.\n- Capable of translating complex business requirements into scalable and efficient technical solutions.\n- Knowledge of architectural patterns like Clean Architecture, Domain-Driven Design (DDD), and principles such as SOLID, TDD, and DRY/KISS.\n- Hands-on experience with testing frameworks like Jest and React Testing Library.\n- Experience with CI/CD pipelines for deploying and managing frontend applications.\n- Exposure to eCommerce platforms and the specific challenges associated with them.\n- English proficiency.\nSoft Skills:\n- Strong problem-solving and critical-thinking skills.\n- Good communication and collaboration skills, with the ability to mentor and lead team members effectively.\n- Familiarity with Agile/Scrum methodologies and experience managing tasks within this framework.\nPreferred (but not required):\n- Has knowledge of design, and coding principles (e.g.: clean code, DRY/KISS, SOLID).\n- Has knowledge Node.js.\n- DevOps, SysOps in AWS, and CI/CD experience.\n\nWhy you\'ll love working here\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\nExceptional Compensation\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total Annual compensation over $70,000, reflecting your expertise and contribution.\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi; New setup, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(987, 516, 2, 'Application Integration Engineer (Java, English)', 'CEVA Logistics provides global supply chain solutions to connect people, products and providers all around the world. Present in 170 countries and with more than 110,000 employees spread over 1,500 sites, we are well on our way to achieving our vision: to be a Top 5 global 3PL.\n\nWe believe that our employees are the key to our success. We want to engage and empower our diverse, global team to co-create value with our customers through our solutions in contract logistics and air, ocean, ground, and finished vehicle transport. That is why CEVA Logistics offers a dynamic and exceptional work environment that fosters personal growth, innovation, and continuous improvement.\n\nCESA Vietnam was founded in 2018; CESA started as a development center in Vietnam, then now became a technology company of CEVA Logistic, specializing in Microsoft .Net technologies (ASP.Net MVC, API, Azure,...), ESB platform (Webmethods, Java...) and delivers projects using Agile methodology.\nWorking with us, you’ll have the opportunity to develop your skills and career in an exciting workplace in touch with an international and innovative environment.\nDARE TO GROW! Join CESA Vietnam / CEVA Logistics, and you will be part of a team that values imagination, encourages boldness and exemplarity, and is committed to excellence in everything we do. Join us in our mission to shape the future of global logistics as we become a global leader in the logistics industry. As we continue growing at a fast pace, will you “Dare to Grow” with us?\n\nMain tasks and activities\n- Responsible in designing, implementing, and maintaining integrations between applications/systems (internal applications within CEVA or external applications from numerous trading partners), ensuring smooth data flow and communication\n- Design, develop, review, test, and manage underlaying integration frameworks and components that are being used by other integration teams\n- Responsible for mentoring, reviewing code and helping other team members with technical issues\n- Ensure maintenance and management of developed solutions\n- Participate to common daily/weekly meeting with project teams based in Paris or India.\n- Realize daily and weekly activity reporting using Group tools.\n\nYour skills and experience\nEducational background\n- Graduate in computer science or related fields\nTechnical skills\n- For Middle level: 3+ years of experience as a software engineer in a complex development environment.\n- For Senior level: 5+ years of experience as a software engineer in a complex development environment.\n- Solid experience in Java programming language\n- Experience in designing & developing RESTful APIs\n- Experience with unit testing and integration testing\n\nAdvantageous to have:\n- Domain knowledge and experience in Transport and Logistics is a plus\n- Experience in working as enterprise application integration engineer before\n- Hands-on experience with any messaging system/service such as RabbitMQ, Kafka, Google Cloud Pub/Sub, etc.\n- Experience with any Cloud platforms (Microsoft Azure, AWS, GCP, etc.)\nLanguage\n- Good communication in English (written and spoken)\nSoft skills\n- Have good logical and critical thinking\n- Having passion for technology and a continuous learning mindset\n- Good problem-solving and analytical skills\n- Good team player and positive attitude.\n\nWhy you\'ll love working here\n- Being a pioneer in contributing to team development with a long-term vision.\n- High-ownership working environment: You will take full responsibility and control of your missions contributing to the team\'s success in a daily collaboration with Paris teams.\n- Continuous skill improvement with new technologies, challenging projects, on-the-job coaching, knowledge exchange with technical experts, and training programs (locally and in Paris).\n- Annual performance review: recognize your efforts and identify development/ improvement needs.\n- 13th-month Salary\n- Salary review every years + Performance bonuses\n- Be secure in your mind with employee care: private healthcare insurance package, medical check-ups, allowance support...\n- Lunch allowances and In house coffee bar\n- Well-equipped facility\n- Free parking\n- Great-place-to-work activities (company trips, sport clubs...): enhance teamwork spirit and facilitate your work-life balance.\n- Opportunity to participate in global events (Hackathon, Seminar, Innovation Factory...).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lầu 6, tòa nhà E-town 2, số 364 đường Cộng Hòa, phường 13, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(988, 238, 2, 'Chuyên viên Quản trị ứng dụng - Application Management', 'Top 3 reasons to join us\n- Mức lương cạnh tranh, hấp dẫn\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n- Phân tích, tối ưu hóa tham số ứng dụng;\n- Tác động vào ứng dụng – Change: thông qua việc phối hợp với các bên liên quan: DEV, NET, DBA, MC\n- Điều phối, xử lý các lỗi ghi nhận từ ứng dụng (issues, problems): khoanh vùng, phối hợp với các bên (nội bộ, bên ngoài) đánh giá và xử lý\n- Phân tích log, đánh giá đề xuất, phối hợp với các bên đưa ra giải pháp cải thiện chất lượng ứng dụng, cải thiện trải nghiệm người dùnng\n- Tham gia các dự án với vai trò quản lý ứng dụng: cài đặt, triển khai,… theo mô hình DevOps\n\nYour skills and experience\n- Tốt nghiệp Đại học (chính quy) chuyên ngành: CNTT, Toán Tin, Điện tử Viễn thông...\n- Chấp nhận chuẩn bị hoặc mới tốt nghiệp loại Khá trở lên các trường đại học phù hợp.\n- Có kinh nghiệm cài đặt, quản trị, cấu hình, tinh chỉnh tối ưu ứng dụng, Middleware, SOA. Ưu tiên hiểu biết cài đặt Corebank T24, TCServer, Websphere, Jboss\n- Có kiến thức, kinh nghiệm quản trị  CSDL Oracle tại các Ngân hàng, Tập đoàn & Công ty về CNTT là một lợi thế\n- Có kiến thức về hệ thống UNIX, Linux - Khả năng nghiên cứu tốt\n- Kỹ năng viết tài liệu, thuyết trình, thuyết phục tốt\n- Kỹ năng phân tích, giải quyết vấn đề tốt\n- Kỹ năng làm việc nhóm và làm việc độc lập tốt\n- Tiếng Anh tốt, có thể làm việc trực tiếp với các đối tác nước ngoài.\n- Trung thực, tin cậy, cẩn trọng.\n- Có khả năng làm việc dưới môi trường nhiều áp lực, liên tục thay đổi\n\nWhy you\'ll love working here\n- Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:\n- Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể…\n- Du lịch nghỉ dưỡng hàng năm\n- Khám sức khỏe định kì\n- Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n- Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương\n- Cơ hội nghề nghiệp và phát triển bản thân:\n- Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng\n- Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng\n- Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh.\n- Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...)\n- Môi trường làm việc lý tưởng với:\n- Những người cộng sự thân thiện và tài năng\n- Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(989, 183, 2, 'Frontend Engineer (ReactJS, Javascript)', 'We are building an environment where personal development is a focus. We want all members to grow with the company through hands-on projects and industry best practices. Our clients have extremely high expectations and that sets a bar for our quality of work.\n\nWe’re looking for a Frontend Developer (ReactJS) for our organization. For this role, we need people who are eager to take ownership and love learning new things.\n\nWe are growing at a brisk pace and we want you to be part of our success.\n\nWhat you\'ll be doing:\n- Develop high-performance web applications.\n- Analysis requirements and maintain technical documentation.\n- Contribute ideas & solutions to the products.\n- Write clear and maintainable code.\n- Participate in all phases of the product development process including analyzing user requirements, designing system architecture, coding, testing, and deployment.\n- Build front end for advanced user experience.\n- Build reusable components/modules for websites with responsive design.\n- Work with API endpoints or Mercure for dynamic content updating.\n- Ensure UI/UX of developed pages and software with near pixel-perfect design.\n- Develop and optimize frontend UI to ensure the application is rendered consistently in cross-browser environments.\n- Cooperate to connect frontend software development with an expert backend team.\n\nYour skills and experience\nMust have:\n- Proficient in React stack (ReactJS, State Management, Functional Programming).\n- Good knowledge with HTML5, CSS3, SASS/SCSS.\n- Experience in developing responsive layouts leveraging CSS and media queries.\n- Good knowledge of UI/UX practices.\n\nGood to have:\n- Familiar with deployment, scaling, monitoring, and performance tuning.\n- Familiar with Agile Process and Scrum Methodologies.\n- Familiar with Extreme Programming methodologies of TDD (Test Driven Development), Refactoring, and Continuous Integration).\n- Familiar with GraphQL.\n\nWhy you\'ll love working here\n- Above industry standard salaries.\n- Friendly working environment and flexible working hours.\n- 13th salary, insurance, and team-building activities.\n- We work hand-in-hand with our clients to fully invest in their product development and build solutions together for their target market.\n- We fully invest in our team, we will help you build yourself up in any area you feel you need development, be it in English, learning a new design tool, developing your design thinking, and more. We want to make sure that you’re always learning and developing yourself whilst a part of our team.\n- We respect both Products and Technology equally, ensuring all of the Products we work on have features with true market potential and ensuring all of the team contribute to, understand, and believe in what they are developing.\n- We respect you and your personal hours, we keep a sustainable pace by working standard 8 hours days from Monday to Friday, ensuring we only plan for what we can achieve.\n- We are fully agile, working with set sprint goals and working at our rate of velocity.\n- You will have ownership over your role, giving you the opportunity to experiment and try new processes to better improve your day-to-day responsibilities. We are always open to improving our processes.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '56A Le Khoi, Phu Thanh, Tan Phu, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(990, 612, 2, 'IT Engineer', 'IT engineer/technician is responsible for the installment and maintenance of both a company\'s computer systems and its computing systems. They work as part of the IT team and utilize computers and telecommunications to control, gather, and store information, and are called upon to use their technical knowledge to solve the company\'s technological challenges that arise.\n\nIT engineer/technician to discuss system needs and help troubleshoot any network and software issues experienced by employees. They are called upon to train the company staff on newly implemented or installed hardware and software systems and fix the software, hardware, and network issues at the company. They respond to and address IT issues and general IT-related concerns or requests. To ensure the company\'s software security remains intact, IT engineers typically run monthly reports to gather security information and provide these reports to the .\n\nImplement programs in all disciplines to conform to district and state curriculum and/or instructional objectives.\n\nPreparation of literature reviews and other analytical work as requested.\n\nParticipate in the estimation and planning of iterative/agile releases.\n\nHelp to evaluate vendor products to make recommendations for purchase.\n\nAttend regular customer and team department meetings as scheduled.\n\nTrack project timelines, and budgets.\n\nAble to do programming and program coding.\n\nTroubleshoot, and devise solutions to complex operational problems within the capacity and operation.\n\nOversee every aspect of assigned primetime series on the network, cable, and streaming services.\n\nProvide feedback to the General Manager when timeline or resourcing constraints develop.\n\nMay act as a technical lead on projects as assigned.\n\nEffectively communicate priorities and work direction to complete assigned tasks on time and within budget.\n\nEnsure effective handoff to the operations team for ongoing maintenance and troubleshooting.\n\nOversee data entry and system accuracy functions.\n\nFluent in a variety of programming languages, software, scripting, and systems.\n\nAble to understand web technologies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lô CN1-1, KCN Sông Công II, Tân Quang, Song Cong, Thai Nguyen', 'Full-time', '2025-10-07 20:59:18.149534'),
	(991, 531, 2, 'Senior Java Software Engineer', 'We are seeking a highly skilled and motivated Sr. Software Engineer with expertise in Java to join our dynamic team. In this role, you will have the opportunity to lead and contribute to critical projects, collaborate with international teams, and ensure the delivery of innovative, high-quality solutions that exceed client expectations.\n\nKey Responsibilities\n\nProject Ownership:\nTake end-to-end responsibility for assigned projects, driving them to successful completion with high-quality deliverables.\nDesign, develop, and rigorously test robust, scalable, and cutting-edge web applications to deliver superior user experiences.\nCollaborate with stakeholders to refine project requirements and specifications, offering technical insights and recommendations.\nLeverage native APIs and frameworks for seamless integrations, ensuring optimal system performance and user satisfaction.\nIdentify, troubleshoot, and resolve performance bottlenecks and bugs, ensuring applications run efficiently at scale.\nMaintain high standards of code integrity through rigorous testing, documentation, and adherence to best practices.\nProactively monitor systems, resolving issues promptly to minimize downtime and optimize system reliability.\n\nClient Interaction: Interface directly with international clients, building strong relationships and understanding their unique requirements to deliver exceptional results.\n\nGlobal Collaboration: Work closely with teams based in the United Kingdom and the United States, ensuring seamless coordination and project success.\n\nProblem Solving: Analyze complex technical challenges and devise creative solutions, driving innovation within the team and organization.\n\nKnowledge Sharing: Mentor and guide team members, sharing expertise to foster a culture of continuous learning and growth.\n\nYour skills and experience\nCore Skills\nExtensive experience with core Java concepts including object-oriented programming, multithreading, generics, and collections.\nProficiency with Spring, Spring Data, Dependency Injection (DI), and transaction management.\nStrong skills in building RESTful APIs, working with microservices architecture, and expertise in server technologies like Tomcat and Jetty.\nDemonstrated ability to design scalable, well-documented APIs for internal and external clients, including API authentication, authorization, and versioning.\nExperience writing unit, integration, and end-to-end tests to ensure code quality and reliability.\nProficiency with debugging tools and techniques to maintain high-performance systems.\nExpertise in SQL databases (e.g., PostgreSQL) and NoSQL solutions (e.g., MongoDB, DynamoDB), including database design, optimization, and data modeling.\nProven ability to optimize backend systems for performance and scalability.\n\nDevOps and Cloud\nFamiliarity with CI/CD tools like Jenkins, CircleCI, or Harness to automate build and deployment pipelines.\nHands-on experience with AWS services such as EC2, EKS, S3, RDS, and Lambda for scalable cloud-based solutions.\nStrong knowledge of Kubernetes (K8s), including container orchestration, scaling, and deployment of microservices in a distributed system.\nExperience with monitoring and logging tools like DataDog to track performance, logs, and metrics in Kubernetes environments.\n\nVersion Control and Agile Practices\nProficiency in GitHub for version control and team collaboration.\nExperience working in Agile environments, participating in sprints, and collaborating with cross-functional teams.\n\nBonus Skills\nFamiliarity with JavaScript and TypeScript, including ES6+ syntax, is highly advantageous.\n\nWhy you\'ll love working here\nAttractive Benefits:\n100% salary during probation period\nAnnual Leave: 18 days/ year\nFive “Recharge Days” – Extra days, in addition to company holidays.\nFlexible Friday afternoon\nFull salary insurance\n13th-month bonus\nGift + 1 day off for birthday\nAdvanced health insurance (Generali)\nRegular engagement activities: sport clubs, internal event…\nSupport Macbook and Monitor', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Waseco Building - 10 Pho Quang Street, Ward 02, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(992, 238, 2, 'Oracle Developer (Database, PL/SQL, ETL, OFSAA)', 'Top 3 reasons to join us\n• Mức lương cạnh tranh, hấp dẫn\n• Môi trường làm việc chuyên nghiệp, thân thiện\n• Được làm việc với các hệ thống hiện đại, tiên tiến\n\nJob description\n• Tham gia phát triển các dự án quản trị nội bộ (Quản trị Rủi ro, Kế toán - Tài chính, Tính lương v.v)  của ngân hàng trên nền tảng Oracle: OFSAA, EBS, APEX ..\n• Thiết kế, xây dựng Cơ sở dữ liệu theo từng tính năng nghiệp vụ.\n• Lập trình cơ sở dữ liệu PL/SQL, phát triển các chức năng xử lý dưới tầng Cơ sở dữ liệu.\n• Sử dụng T2T để biến đối dữ liệu, phát triển các thủ tục  PL/SQL.\n• Tuning đảm bảo hiệu năng database.\n• ETL dữ liệu và tạo báo cáo, dashboard thuộc các công cụ Oracle (BI, OAS v.v).\n• Phối hợp với hãng và đối  tác, xử lý issue theo CSI Oracle\n\nYour skills and experience\n• Tốt nghiệp hệ chính quy các Trường Đại học, chuyên ngành: Công nghệ thông tin, Toán tin, Điện tử Viễn thông, Kế Toán, Tài chính Ngân hàng...\n• Thành thạo một trong các ngôn ngữ lập trình: SQL/PLSQL, NoSQL, Java\n• Có khả năng phát triển trên ít nhất 1 công cụ ETL hoặc báo cáo (Pentaho, ODI, GG, Oracle BI, Tableau,...)\n• Ưu tiên:\n  • Có kinh nghiệm phát triển, nền tảng kiến trúc OFSAA\n  • Có hiểu biết về lĩnh vực ngân hàng, tài chính, bảo hiểm, chứng khoán\n  • Có kinh nghiệm về xử lý bất đồng bộ, xử lý đa nhiệm, và xử lý dữ liệu theo thời gian thực (near realtime), data streaming trên các nền tảng Oracle, Kafka Streams,…\n\nWhy you\'ll love working here\n<strong>Trải nghiệm Thu nhập hấp dẫn với gói đãi ngộ toàn diện:</strong>\n• Thưởng thành tích tháng 13; Thưởng thành tích theo kết quả công việc 06 tháng, 1 năm ; Thưởng các dịp lễ tết trong năm ; Thưởng theo danh hiệu cá nhân và tập thể… \n• Du lịch nghỉ dưỡng hàng năm\n• Khám sức khỏe định kì\n• Gói bảo hiểm sức khỏe cá nhân và người thân (MIC)\n• Quà tặng và ngày nghỉ sinh nhật hưởng nguyên lương \n<strong>Cơ hội nghề nghiệp và phát triển bản thân:</strong>\n• Được thử sức với các nền tảng công nghệ mới, tham gia vào những dự án chuyển đổi lớn của ngân hàng \n• Có cơ hội học hỏi từ các Chuyên gia, Lãnh đạo nội bộ hàng đầu tại MB trong lĩnh vực IT, Tài chính ngân hàng \n• Được trải nghiệm các phương pháp học tập mới và phát triển năng lực theo lộ trình công danh. \n• Hưởng các chính sách hỗ trợ, khuyến khích học tập, nâng cao trình độ và phát triển bản thân (chứng chỉ nghề quốc tế...) \n<strong>Môi trường làm việc lý tưởng với:</strong>\n• Những người cộng sự thân thiện và tài năng \n• Cơ sở vật chất, không gian làm việc xanh và hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa nhà MB, số 18 Lê Văn Lương, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(993, 227, 2, 'Data Engineering Lead - Up to 30 Months\' Annual Salary', 'Top 3 reasons to join us\n1. Top-notch Annual Income\n2. Global Health Insurance\n3. 5-star Office in the centre of Hanoi\n\nJob description\n1. Data Platform Development: Architect and optimize a scalable Lakehouse-based Data Platform (AWS S3, Delta Lake, Redshift) with robust pipelines using Airflow, Airbyte, dbt, and Kafka.\n2. ML/AI Integration: Design and implement data infrastructure for ML/AI workflows, including feature stores, model training pipelines, and inference systems.\n3. Collaboration: Partner with Data Scientists and stakeholders to translate business requirements into scalable data and ML/AI solutions, enabling analytics, reporting, and predictive modeling.\n4. Performance Optimization: Ensure scalability, reliability, and cost-efficiency of data systems, optimizing tools like Kafka, dbt, Airflow, and storage solutions.\n5. Innovation & Research: Continuously research and implement new technologies to enhance the platform, applying best practices in Data Engineering, DataOps, and MLOps.\n6. Data Governance Implementation: Design and implement Data Governance frameworks, including policies, processes, and tools for data quality, data lineage, data cataloging, access control, and compliance with regulations (e.g., CCPA, PII). Utilize tools like AWS Glue, Lake Formation, or Collibra to ensure data integrity and security.\n7. Technical Leadership: Define the technical roadmap, establish best practices in Data Engineering and DataOps, and mentor a team of data engineers.\n8. Team Management: Plan and assign tasks to data engineers, evaluate performance, and support the professional development of the team.\n\nYour skills and experience\n1. Bachelor\'s degree in Computer Science or a related field.\n2. 6+ years of experience in data engineering, with at least 2 years in a leadership or team management role.\n3. Proficiency in advanced SQL and programming languages such as Python, C#, or Java for data processing and scripting.\n4. Strong experience with relational databases (e.g., PostgreSQL, MySQL) and cloud platforms (e.g., AWS, GCP, Azure).\n5. Deep knowledge of data architecture, including Lakehouse, Data Warehouse, and document databases (e.g., Elasticsearch, Redis).\n6. Experience designing and implementing complex data architectures (e.g., Lakehouse, Data Mesh) and data processing systems (streaming and batch).\n7. Proven experience deploying ML/AI models into production, including building and managing data pipelines for model training and inference.\n8. Strong leadership skills, including team management, project planning, and effective communication with both technical and non-technical stakeholders.\n9. Excellent problem-solving skills, attention to detail, and the ability to work independently or lead a team in an Agile environment.\n10. Proficient in English, with the ability to communicate, read, and write effectively in a professional work environment.\n\nPreferred (but not required)\n1. Knowledge of container orchestration, such as AWS EKS or Kubernetes.\n2. Experience with microservice architecture.\n3. Experience with data visualization tools, such as AWS QuickSight or Grafana.\n4. Experience with data streaming platforms, such as Apache Kafka or Apache Nifi.\n5. Knowledge of data governance and compliance regulations (e.g., GDPR, CCPA).\n6. Familiarity with the Agile toolset, such as GitLab, Jira, Confluence, and Slack.\n\nWhy you\'ll love working here\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\nExceptional Compensation\n1. Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n2. Total annual compensation $70,000, reflecting your expertise and contribution.\nGrowth Opportunities\n1. Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n2. Clear career advancement pathways and access to continuous professional development programs.\nGlobal Vision\n1. Contribute to projects that redefine how brands connect with consumers globally.\n2. Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\nIn addition to development tasks, you’ll collaborate closely with other CoEs to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 1, Tòa nhà Pax Sky, 63-65 phố Ngô Thì Nhậm, Phường Phạm Đình Hổ, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(994, 613, 2, 'QA/QC Engineer (Manual)', 'ABOUT US \nFloware is a leader in building innovative software to transform the way people live, play, work, and learn. Our mission is to create smart solutions that benefit everyone and solve their daily challenges. We were the first in Vietnam to develop an iOS app and our first OS X application SmartDay debuted on the Mac App Store at #5. \nLocation: Ho Van Hue Street, Phu Nhuan District, HCMC \nOffice hour: Monday – Friday (8:30 AM – 5:30 PM) \nJob Description \nUnderstand and analyze requirements .\nExecute manual testing in Web, applications on Mac OS and mobile.\nCreate test plan, test case, test scenarios.\nSet-up testing environment.\nReport the testing result to Leader and PM.\nYour skills and experience \nSkills and Experience \nAt least 2 years in testing web and mobile application.\nGood knowledge on Software Testing process, testing activities, testing types.\nExperience in analyst requirements, developing, performing test cases.\nCarefulness and logic thinking.\nGood English communication skills. \nWhy you\'ll love working here \nWHY FLOWARE\nWe challenge ourselves every day to find better solutions and better ways to do things. We ask difficult questions and work together to solve them. We believe in doing the right things as well as doing things right. We value honesty, hard work, integrity, and transparency. We are committed to transforming people’s lives, will you join us today? \nCOMPENSATION & BENEFITS\n100% salary during probation period\nFull income tax, insurance paid by company (Net Salary)\n13th month of salary\nPremium Health Insurance Package\nPerformance bonus up to 96 million dong or more in the year\nFree office lunch, fruit, coffee, tea, snack bar everyday\nFriendly, flexible, and fun working environment\nVery attractive salary based on skills and experience\nMonthly team activity allowance\nGreat opportunity for career development\nCompany trip, team building, monthly party, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '43 Hồ Văn Huê, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(995, 368, 2, 'Quality Control Mobile Apps Tester (QA QC, IOS/Android)', 'About BeWao\nBeWao is a pioneering health and wellness platform tailored to the Vietnamese market. We empower users to achieve their nutrition and fitness goals through personalized solutions driven by cutting-edge technology and localized expertise. As part of our mission to redefine health in Vietnam, we are seeking a detail-oriented Quality Control (QC) Mobile App Tester to join our dynamic team.\n\nAbout the Role\nAs a QC Mobile App Tester, you\'ll be responsible for ensuring the quality, functionality, and user experience of BeWao\'s mobile applications. You\'ll work closely with our development and product teams to identify bugs, validate features, and maintain the highest standards of app performance across different devices and platforms.\n\nWhat You\'ll Do\n- Test BeWao\'s mobile applications thoroughly across iOS and Android platforms\n- Design and execute comprehensive test cases for new features and existing functionality\n- Perform manual testing including functional, usability, compatibility, and regression testing\n- Identify, document, and track bugs and issues using appropriate tools\n- Collaborate with developers to reproduce and resolve identified issues\n- Validate user stories and acceptance criteria to ensure requirements are met\n- Test app performance across different devices, screen sizes, and operating system versions\n- Conduct exploratory testing to discover potential edge cases and user experience issues\n- Participate in release testing and ensure quality gates are met before app deployment\n\nYour skills and experience\nTechnologies & Tools We Use\n- Mobile Platforms: iOS, Android\n- Testing Tools: Manual testing techniques, device testing labs\n- Bug Tracking: JIRA, Trello, or similar project management tools\n- Communication: Slack, Microsoft Teams\n- Development Stack: React Native, TypeScript (understanding beneficial)\n\nAbout You\nWe\'re looking for a meticulous, detail-oriented tester who is passionate about mobile app quality. You should be:\n- Experienced: 2+ years of experience in mobile app testing or quality assurance\n- Detail-Oriented: Strong attention to detail with excellent analytical and problem-solving skills\n- Tech-Savvy: Familiar with mobile platforms (iOS/Android) and understanding of mobile app development lifecycle\n- Communicative: Excellent written and verbal communication skills in Vietnamese and English\n- Systematic: Ability to create and follow structured test plans and documentation\n- User-Focused: Understanding of user experience principles and mobile app usability standards\n- Adaptable: Comfortable working in a fast-paced startup environment with changing requirements\n\nPreferred Skills\n- Automation Testing Experience: Knowledge of mobile automation testing frameworks such as:\n  - Detox for React Native applications\n  - Playwright for end-to-end testing\n  - Appium, XCUITest or Espresso\n- Experience with performance testing and mobile app optimization\n- Basic understanding of programming concepts (JavaScript/TypeScript preferred)\n- Experience with API testing tools (Postman, REST clients)\n- Knowledge of health and wellness applications or healthcare domain\n\nWhy you\'ll love working here\nWhy Join Us?\n- Competitive salary and benefitspackage\n- Generous leave policy:\n  - Public holidays\n  - 12 days annualleave\n  - 3 additional Company Holidays (Christmas, Vietnamese Family Day, Birthday leave)\n- Comprehensive insurance coverage and allowances (parking, transportation)\n- Performance-based annual 13th-month salary (may apply)\n- Recreational facilities (billiards, table tennis) for a balanced work-life experience\n- Opportunity to work on meaningful health and wellness technology\n- Professional growth opportunities in a rapidly expanding startup\n\nApply Now\nJoin BeWao and help us deliver exceptional mobile experiences that shape the future of health and wellness in Vietnam. Be part of ensuring our users have access to reliable, high-quality applications that support their wellness journey!\nTo apply, please send your CV and a brief cover letter explaining your interest in mobile app testing and quality assurance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '95-97 Nguyễn Cơ Thạch, Phường An Lợi Đông, Thành phố Thủ Đức, TP Hồ Chí Minh, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(996, 375, 2, 'Unreal Engine Artist (Designer, 3ds Max)', 'Vlast Việt Nam là công ty tiên phong trong việc sản xuất animation và nhân vật mang tính sáng tạo. Chúng tôi truyền tải cảm xúc đến mọi người thông qua những câu chuyện độc đáo và đồ họa nổi bật, và đang tạo ra những nội dung được yêu thích trên toàn thế giới.\n\nMô tả công việc\n- Ưu tiên cho những Artist có kinh nghiệm trên phần mềm Unreal Engine, làm phim hoạt hình nhân vật.\n- Ưu tiên ứng viên biết sử dụng công cụ đồ họa 3D hoặc các công cụ thiết kế.\n- Thực hiện Virtual Idol và những hình ảnh liên quan đến nội dung IP, làm Unreal Look Dev\n- Xây dựng bầu không khí hài hòa cho tổng thể của video, cải thiện phong cách thẩm mỹ để cho ra output cuối cùng.\n- Điều chỉnh ánh sáng, sequencer, rendering trong Unreal Engine.\n\nYour skills and experience\n- Yêu cầu năng lực thẩm mĩ và năng lực đạo diễn video\n- Biết cách xây dựng tư thế của nhân vật, và có hiểu biết nhất định về chuyển động của cơ thể.\n- Khả năng thu thập những xu hướng thời trang mới nhất\n- Có khả năng tự quản lý công việc và tích cực giải quyết vấn đề, hoàn thành công việc được giao.\n- Có đạo đức nghề nghiệp để đảm bảo triệt để sự bảo mật thông tin từ công việc.\n- Ưu tiên ứng viên có khả năng tiếng Anh hoặc tiếng Hàn\n\nLưu ý: Yêu cầu bắt buộc nộp Portfolio video (Các hồ sơ thiếu Portfolio sẽ tự động bị loại)\n\nWhy you\'ll love working here\n- Mức lương cạnh tranh, lương tháng 13, thưởng theo hiệu quả công việc. Tổng lương lên đến 14-17 tháng lương/năm.\n- Chế độ nghỉ phép hấp dẫn: phép năm, nghỉ phép du lịch cá nhân, nghỉ hiếu hỉ từ 15-22 ngày/nămBảo hiểm xã hội theo quy định nhà nước + Bảo hiểm chăm sóc sức khỏe PTI.\n- Công ty hỗ trợ tiền cơm trưa, phí gửi xe.\n- Hỗ trợ đồ ăn nhẹ, thức uống, cafe trong suốt quá trình làm việc.\n- Thời gian làm việc: 8h30 - 17h30 (Thứ 2 - Thứ 6), nghỉ trưa 12h - 13h', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '268 Trần Hưng Đạo, Phường 11, Quận 5, Hồ Chí Minh (Tòa nhà Ngân Hàng ACB), District 5, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(997, 614, 2, 'Senior Full-Stack Developer (Java, ReactJS, NodeJS)', 'Decathlon Vietnam is seeking a highly skilled and autonomous Senior Full-Stack Developer to be the pioneering software engineer in our Vietnam branch. This is a unique opportunity to build and shape the local development landscape, creating impactful solutions that integrate with our global "Decathlon United" IT systems (APIs, Kafka flows, Data Lake, etc.). You will be responsible for the end-to-end development of microservices and web tools, directly contributing to the efficiency and growth of our operations in Vietnam. This role requires a proactive, versatile individual who can manage projects independently, from requirements gathering to deployment and maintenance, much like working in a dynamic startup environment.\n\nResponsibilities:\n- Develop and maintain robust microservices and applications (Java Spring Boot, ReactJS).\n- Integrate local solutions with Decathlon United global APIs and systems.\n- Manage the full development lifecycle: from requirements gathering with internal teams (Sales, Finance) to deployment and maintenance.\n- Collaborate with Decathlon United technical teams for integrations and access.\n- Ensure high standards of code quality, security, reliability, and documentation.\n- Support existing NodeJS services and develop Google Apps Scripts for automation.\n\nYour skills and experience:\n\nRequired Technical Skills:\n- Proven Full-Stack experience, strong in Java Spring Boot and ReactJS.\n- Scope: 80% Backend, 20% Frontend and apps scripts, etc.\n- Expertise in building & consuming RESTful APIs; understanding of HTTP standards.\n- Database design, integration, and management.\n- Experience with microservices architecture; Kubernetes is a plus.\n- Familiarity with Kafka or similar messaging systems.\n- Working knowledge of NodeJS and Google Apps Script.\n- Understanding of CI/CD principles (Jenkins is a plus).\n- Knowledge of API security (OAuth 2.0) and data formats (JSON, XML).\n- Proficient with Git.\n\nRequired Soft Skills:\n- Highly autonomous, proactive, and results-oriented.\n- Strong problem-solving, analytical, and technical decision-making skills.\n- Excellent communication (English essential) and collaboration abilities.\n- Adaptable, versatile, and a continuous learner.\n- Product-oriented mindset with strong ownership.\n- Comfortable in an Agile environment; team player.\n- Sport enthusiast is a plus.\n\nWhy you\'ll love working here:\n- Freedom and Responsibility to dare, be yourself, and take action!\n- Join a young, dynamic, and friendly team with collective sports activities.\n- Personal and career development plan with your leader.\n- Be a shareholder: exclusive annual option to invest in Decathlon\'s shares.\n- Monthly performance bonus and 13th-month salary.\n- Annual Salary review in March.\n- 18 annual leave days.\n- Comprehensive Health Care Insurance and annual health check.\n- Sport allowance.\n- 20% staff discount for all Decathlon products.\n- MacBook & screen monitors supplied.\n- 100% salary during a 2-month probationary period.\n- Work in HCMC (Binh Thanh), work-from-home negotiable post-probation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Pax Sky Building, 26 Ung Van Khiem Street, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(998, 224, 2, 'QA Manager - Exp in Back Office/Human Resource projects', 'About us\nAt Money Forward Vietnam (MFV), we are actively engaged in the forefront of financial technology. Our portfolio, encompassing over 50 services across B2C, B2B, and B2B2C sectors, aims to mitigate financial challenges for a broad audience. A critical aspect of our strategy is developing our engineering team within a global framework. As part of the Money Forward Group, transitioning swiftly into a global tech leader, MFV is strategically positioned to enhance our engineering capabilities through focused investment.\nWe are advancing a major project in enterprise-level HR solutions, collaboratively developed by our teams in Vietnam and Japan, targeted initially at Japanese companies with future plans for global expansion. To push this project forward, we are looking for a capable leader to oversee our diverse engineering team, including Backend, Frontend, QA, and Product Owner. This role involves close collaboration with our Japanese team and driving the product toward sustained success over the next three years and beyond. This position offers visibility to senior management in Vietnam and Japan and represents a significant opportunity for career development as a senior manager in QA.\n\nKey Responsibilities:\nLead a Team: Direct a project team of 10+ members, managing all aspects of product development and fostering team cohesion.\nIncidents management: Monitor and review incidents, develop improvement plans to prevent recurrence, and ensure their implementation within the organization.\nProcess Improvement: Collaborate with the Japan team to refine the QA process, ensuring efficiency and best practices.\nTalent Management: Hire and mentor top QA engineering talent, focusing on skill development and team performance enhancement.\nPerformance Evaluation: Conduct transparent and fair performance evaluations, from goal setting to final assessments.\nStakeholder Communication: Serve as the primary liaison for project communications with stakeholders, managing expectations and updates.\n\nYour skills and experience\nMust-have:\nDegree in Information Technology, Software Engineering, Information Systems, or equivalent experience\n5+ years of QA engineer’s experience\n3+ years managing the QA team\nBuilt and/or led a QA engineering team of 5+ members\nExperience for back office (HR related) application software\nExcellent problem-solving in ambiguous situations without clear instructions\nManaging and monitoring Incidents in the production environment, making improvement plans\nProven people management skills: team building, employee satisfaction, career development, and mentoring\nFamiliar with Agile methodologies like Scrum, Kanban, Scrum of Scrum, and its best practices\nProfessional working proficiency in English.\nISTQB certification or equivalent knowledge; Advanced Level is highly recommended.\n\nNice-to-have:\nB2B Application Expertise: Experience in managing or developing B2B applications, with a knack for solving complex business and technology challenges, particularly in finance, accounting, banking systems, and scalable web applications.\nAnalytical Decision-Making: Leveraging data analysis for strategic decisions, emphasizing software development metrics and user engagement.\nCross-functional and Innovative Leadership: Experience in cross-departmental collaboration and leading R&D efforts to foster innovation and align product development with company goals.\nLanguage Skills: Japanese proficiency is a plus to understanding business requirements and customer voices. (N2 level or above recommended)\n\nSoft Skills:\nStrong communication and collaboration skills.\nPositive, proactive mindset with perseverance in overcoming challenges.\nA team-oriented approach, fostering a shared commitment to quality.\n\nWhy you\'ll love working here\nCaring Mental & Physical Recreation:\nHybrid working: 2 days at the office and 3 days WFH\nWorking hour: Flexible start 8AM-9AM from Mon-Fri\nFull salary in probation\nInsurance: Applied from Probation period:\nSocial Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\nPrivate health insurance & accident insurance. From Managing level: extra for family members\nBonus: 13th month salary\n17 - 24 paid days off and more\nPaternity leave: Extra 5 days\nAnnual company trip; Quarterly team building\nBilliards & Running club\nAnnual health check\nWell-equipped facility: Macbook pro, additional monitor, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ETown Central Building, 11 Doan Van Bo, Ward 13, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(999, 615, 2, 'Senior Java Backend Developer (Spring, SQL)', 'As a proud member of Galaxy Holdings - Sovico Group, Galaxy Technology stands as a dynamic force in the digital realm, recognized for our prowess in talent and customizable solutions. We are dedicated to propelling businesses worldwide to new heights through cutting-edge digital, software, and IT solutions. Across diverse industries, including Aviation, EAI, Fintech, Manufacturing, Automotive, Blockchain, Medical, Health Tech, Real Estate, Hospitality, Education, and beyond, we serve as a strategic partner, empowering organizations with innovation and excellence. Responsibilities and Duties The Java Backend Developer role aims to engineer and maintain robust backend systems that serve as the backbone of digital banking solutions. The professional in this role is tasked with designing, implementing, and optimizing Java-based applications and services, ensuring they meet the high standards of performance, security, and scalability required in the banking industry. The developer will work closely with cross-functional teams to translate business requirements into technical solutions, maintain code quality, and continuously improve the system architecture. Collaborate with cross-functional teams to design and implement robust backend services. Employ modern Java technologies to improve system performance, security, and scalability. Maintain a clean codebase with adherence to industry best practices for upgradability and maintenance. Contribute to code reviews and apply debugging skills to ensure system reliability. Promote a team culture that values diversity, equity, inclusion, and respect. Your skills and experience Degree in Software Engineering, Information Technology, Computer Science or relevant. From 3 - 6 years of experience with Java or Java 17+. Spring Framework: Spring boot 3+. Proficiency with Spring Framework (Spring Boot3+, etc.). Database: Postgres(proceduce/function...). Kafka, Rabbit MQ, Redis, otel & prometheus. Cron job, schedule. Docker. Possess knowledge of data encryption, checksum, and data integrity techniques. Knowledge of testing methodologies and frameworks. Why you\'ll love working here Attractive income Up to 45M Pay your full salary in two months of probation. Review salary once per year. 12 days of annual leave. Year-end bonus/ performance bonus based on the business performance. Social, Health and others Insurance are based on Labor Law and Health insurance PVI. Activities: Company Trip, Year End Party, Sport (football, badminton, running club…), Christmas, Charity activities, … Good work environment and working in a professional, friendly, well-equipped environment. Chances to work in a big and global team, work directly with customers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa Nhà PV Gas, 673 Nguyễn Hữu Thọ, Phường Phước Kiển, Nha Be, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1000, 374, 2, 'Senior Search Engineer', 'Top 3 reasons to join us\n- Flexibility to perform\n- Careers without boundaries\n- Learning and development opportunities\n\nJob description\nAbout the Role \nWe’re looking for a skilled Search Engineer to help us build and optimize high-performance search systems. You’ll work on improving relevance, integrating ML models, and scaling search infrastructure that directly impacts user experience. If you’re excited about search quality and system efficiency, we’d love to talk.\n\nResponsibilities:\n- Design, develop, and optimize the Elasticsearch infrastructure.\n- Analyze search logs and user behavior to continuously improve query relevance, ranking, and retrieval quality.\n- Work closely with data scientists to integrate machine learning models into the search pipeline (e.g., semantic search, re-ranking, personalization).\n- Implement advanced search features such as autocomplete, typo correction, synonym expansion, query understanding, and faceted search.\n- Build and scale high-performance search systems with low latency and high throughput.\n- Collaborate with product and engineering teams to define search quality metrics (CTR, nDCG, recall, etc.) and deliver measurable improvements.\n\nYour skills and experience\n- 3–5 years of experience building or maintaining large-scale search or information retrieval systems.\n- Hands-on experience with search platforms like Elasticsearch, Apache Solr.\n- Strong understanding of search relevance concepts: tokenization, analyzers, ranking algorithms (BM25, TF-IDF), boosting, etc.\n- Solid programming skills in Python, Java.\n- Experience with query log analysis, A/B testing, and relevance tuning.\n- Familiarity with information retrieval theory and modern ranking techniques.\n- (Bonus) Experience integrating machine learning models into search (e.g., Learning to Rank).\n- (Bonus) Familiarity with distributed systems, microservices, and stream processing (e.g., Kafka).\n\nNice to have: \n- Enthusiastic about creating impactful product solutions \n- Knowledge of vector search and ANN libraries (e.g., FAISS, Milvus, Qdrant, Weaviate).\n- Experience working with semantic search, NLP, or recommendation systems.\n\nWhy you\'ll love working here\nBenefits\n- 13th salary\n- Social Insurance\n- Medical healthcare\n- Annual health check\n- 15 days annual leave\n- Transportation fee (BE\'s services)\n- Performance bonus\n- Holiday bonus\n- Team Building and many engagement activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FIVESTAR BUILDING, 28bis Mac Dinh Chi, Dakao, Distric1, HCM City, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1001, 616, 2, 'Manual Tester (Junior - middle - Senior)', 'Job description\n- Tham gia phân tích, làm rõ yêu cầu nghiệp vụ và kỹ thuật từ các bên liên quan (BA, PO, Dev...).\n- Xây dựng test case, checklist kiểm thử, test data. Thực hiện kiểm thử, báo cáo lỗi và theo dõi quá trình xử lý lỗi.\n- Phối hợp chặt chẽ với đội ngũ phát triển để đảm bảo quy trình kiểm soát chất lượng.\n- Hỗ trợ thực hiện kiểm thử UAT, kiểm thử sau khi golive. Phân tích và đánh giá nguyên nhân các lỗi phát sinh sau golive.\n- Thực hiện các công việc theo sự phân công của quản lý.\n\nYour skills and experience\n- Tối thiểu 3 năm kinh nghiệm kiểm thử phần mềm thủ công (manual testing) trên nền tảng Mobile và Web.\n- Có kinh nghiệm kiểm thử API và sử dụng SQL thành thạo để kiểm tra dữ liệu.\n- Làm việc tốt trong môi trường Agile/Scrum, hiểu rõ vai trò của tester trong mô hình này.\n- Nắm vững quy trình phát triển phần mềm và các loại kiểm thử: functional, regression, integration…\n- Tư duy phân tích tốt, có khả năng xử lý vấn đề độc lập.\n- Ưu tiên ứng viên có kinh nghiệm dự án trong lĩnh vực Fintech hoặc có hiểu biết về sản phẩm tài chính.\n\nWhy you\'ll love working here\n- Làm việc từ T2 - T6.\n- Lương thỏa thuận theo năng lực, thưởng tháng lương 13, thưởng Tết căn cứ vào kết quả kinh doanh và thành tích của nhân sự đạt được trong năm.\n- Du lịch, teambuilding, khám sức khỏe, review lương thực hiện định kì 1 lần/năm.\n- Hỗ trợ ăn trưa 50k/ngày.\n- Gói khám sức khỏe tổng quát định kì hàng năm.\n- BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành.\n- Được thử thách trong các dự án lớn, có cơ hội khẳng định năng lực bản thân và phát triển sự nghiệp.\n- Môi trường làm việc thân thiện, năng động, sáng tạo, khuyến khích phát triển cá nhân.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 7 Đào Duy Anh, , Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1002, 600, 2, 'Tech Lead (NodeJS, ReactJS, React Native, AWS)', 'Role Summary\nAs a Technical Owner, you’ll take full ownership of the technical side of our product — from system architecture to delivery. You’ll work closely with founders, product teams, and engineers to bring ideas to life in a fast-paced, resource-constrained startup environment.\n\nJob Responsibilities:\n- Own and drive the technical vision and architecture of the product.\n- Design and build core features from scratch using scalable, modern technologies.\n- Collaborate with the founding team to shape the product roadmap based on technical feasibility and long-term scalability.\n- Make key architectural decisions (e.g. monolith vs microservices, cloud provider, database selection, devops pipeline).\n- Write clean, maintainable code and enforce best practices (code review, testing, CI/CD).\n- Mentor junior engineers and build a strong engineering culture as the team scales.\n- Stay hands-on with development (approx. 50–70% coding, 30–50% leading/mentoring).\n- Communicate tech decisions clearly to both technical and non-technical stakeholders.\n\nYour skills and experience\nSkill & Qualification Requirements\n- 5+ years of software development experience, including 1–2 years in a leadership/ownership role.\n- Experience building early-stage products, ideally from MVP to production scale.\n- Strong skills in either frontend (React, Vue...) or backend (Node.js, Python, Java...) – ideally both.\n- Good grasp of cloud platforms (AWS, GCP, or similar), CI/CD, databases, and system design.\n- Ability to prioritize speed vs scalability, depending on stage of product.\n- Comfortable working with ambiguity, limited specs, and tight deadlines.\n- Excellent communication skills – can align tech with business.\n\nBonus Points\n- Experience in a founding tech team or CTO track.\n- Experience with analytics, A/B testing, feature flagging, etc.\n- Familiarity with lean methodology, or agile delivery.\n- Interest in building developer culture and hiring early team members.\n\nWhy you\'ll love working here\n- 13th-month salary, review salary twice a year\n- 5 working days/week (Monday to Friday), weekends off\n- Hybrid work policy offered.\n- Company-supported sports and team-building activities (e.g., football, badminton).\n- Celebration events (Happy hour, Birthday parties, Holiday gifts, Year-end party).\n- Annual company trip and regular team-building events\n- Free snacks, tea, and coffee at the office.\n- Free parking.\n- Relaxed, friendly workplace with great facilities.\n- Opportunities for promotion and career development.\n- 13th-month salary and annual salary review.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '77 Le Trung Nghia, Ward 12, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1003, 617, 2, '[HN/Hybrid] Junior Full-stack Developer (SaaS)', 'Job description\n- Tham gia vào đội ngũ Product team, tập trung Maintain (30%) và Phát triển tính năng mới (70%) cho sản phẩm SaaS B2B trong lĩnh vực E-commerce\n- Thiết kế, phát triển và bảo trì các ứng dụng web fullstack sử dụng các công nghệ như ReactJS, VueJS, Nodejs, Golang.\n- Phân tích yêu cầu, thiết kế kiến trúc hệ thống và triển khai các tính năng mới.\n- Cộng tác chặt chẽ với các thành viên trong nhóm để đảm bảo dự án được hoàn thành đúng tiến độ và chất lượng.\n- Tìm hiểu và áp dụng các công nghệ mới để nâng cao hiệu suất của sản phẩm.\n\nYour skills and experience\n- Ít nhất 02 năm kinh nghiệm làm việc trong vai trò Fullstack Engineer (có kinh nghiệm/hiểu biết về nghiệp vụ của TMĐT)\n- Có kinh nghiệm làm việc với các công nghệ Frontend: ReactJS, VueJS và Backend: Golang, NodeJS.\n- Tốt nghiệp từ ĐH trở lên các ngành CNTT, Kỹ thuật máy tính, Khoa học máy tính,… ưu tiên từ các trường ĐH Top đầu như HUST, UET, PTIT…\n- Thành thạo về Database: Mysql, Postgres\n- Có hiểu biết cơ bản về cloud: AWS, Google cloud\n- Git: thành thạo các công cụ Version Control\n- Có khát khao và tư duy phát triển sản phẩm, chủ động tìm kiếm các giải pháp để cải thiện sản phẩm.\n- Có khả năng làm việc độc lập và làm việc nhóm.\n- Khả năng giải quyết vấn đề tốt và tư duy logic.\n- Ưu tiên ứng viên có kinh nghiệm làm việc với các hệ thống có quy mô lớn, xử lý lượng traffic cao.\n\nWhy you\'ll love working here\n- Mức lương: Up to $1500/month (sẵn sàng thoả thuận theo năng lực)\n- Làm việc theo cơ chế Hybrid\n- Chính sách Review năng lực và level cố định 06 tháng/lần với quy trình cùng khung năng lực – đảm bảo rõ ràng minh bạch\n- Gói thu nhập năm hấp dẫn: Lương tháng thứ 13 + Thưởng Performance năm (upto 02 tháng lương)\n- Thưởng tiền mặt cho các dịp Lễ Tết lớn của Việt Nam: Đầu năm, Ngày Quốc Khánh, Ngày 30/4 -1/5,…\n- Quỹ tài trợ Học phí thường niên (tài trợ từ 90-100%) cho nhân sự\n- Cơ hội phát triển công việc và năng lực chuyên môn vượt bậc qua Bài toán làm sản phẩm cho lượng User dùng từ lớn đến rất lớn (thị trường Global Ecom)\n- Hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.\n- Tài trợ cho toàn bộ CBNV khám sức khoẻ tổng quát 1 lần/năm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No 3 Lane 120, Truong Chinh Street, Dong Da, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1004, 606, 2, 'Junior/Fresh Candidates-VPBankTechnologyHackathon2025', 'VPBank Technology Hackathon 2025 tiếp tục triển khai tương tự format chương trình năm 2024 đã phối hợp thành công cùng AWS. Cụ thể, VPBank đưa ra các thử thách (challenge statements) để Nhóm tham gia lựa chọn và đề xuất ý tưởng, giải pháp công nghệ và hiện thực hóa giải pháp thông qua kỹ năng, kinh nghiệm để phát triển giải pháp đó trên nền tảng online của AWS. Chương trình bao gồm 5 Phases:  \n- Phase 0: Registration - Đăng ký & sơ loại hồ sơ (Online)  \n- Phase 1: Learn - Kick-off giới thiệu chương trình & AWS fundamentals (Offline & Online)  \n- Phase 2: Ideation – Nhóm tham gia xây dựng ý tưởng giải pháp cho thử thách và submit online  \n- Phase 3: Develop - Nhóm tham gia xây dựng giải pháp theo thử thách đã lựa chọn trên nền tảng AWS online  \n- Phase 4: Compete - Nhóm tham gia có giải pháp xuất sắc nhất trình bày tại Final Round (Offline).  \n- Phase 5: Selection & Hiring Process – Nhóm/cá nhân có kết quả xuất sắc nhất theo tiêu chí chấm điểm của Chương trình & theo kết quả của Hội đồng chấm điểm sẽ nhận được các phần thưởng từ VPBank (cash), quà tặng từ AWS (Gift card) và ưu tiên tuyển dụng chính thức vào VPBank (Đơn vị đánh giá và lựa chọn theo qui trình tuyển dụng tại VPBank)  \n  \nCÁCH THỨC ĐĂNG KÝ  \n- Hình thức: Đăng ký theo nhóm (3-5 thành viên) hoặc đăng ký cá nhân (BTC sẽ ghép nhóm)  \n- Đăng ký ngay tại website Tuyển dụng VPBank.  \nYour skills and experience  \n- Junior/Fresh: dành cho các bạn mới tốt nghiệp ĐH loại Khá trở lên nhóm ngành CNTT & Khoa học dữ liệu và có dưới 2 năm kinh nghiệm làm việc.  \n- Senior & Expert: dành cho ứng viên đã tốt nghiệp Đại học và có kinh nghiệm làm việc trên 2 năm.  \nWhy you\'ll love working here  \n5 LÝ DO BẠN KHÔNG THỂ BỎ LỠ VPBANK TECHNOLOGY HACKATHON 2025  \nVới thông điệp "Chinh phục công nghệ, Kiến tạo tương lai", VPBank Technology Hackathon 2025 cam kết mang tới những trải nghiệm đáng giá:  \n- Tự do lựa chọn đề bài công nghệ trong lĩnh vực Ngân hàng để chinh phục thử thách;  \n- Đội ngũ hướng dẫn với gần 40 chuyên gia giàu kinh nghiệm của VPBank cùng AWS sẽ đồng hành & hướng dẫn Bạn qua các chặng thi đấu;  \n- Giải thưởng hấp dẫn bằng tiền mặt từ VPBank & phần thưởng tài trợ từ đối tác AWS;  \n- Cơ hội gia nhập đội ngũ VPBank Young Talents 2025 – với lộ trình phát triển nghề nghiệp chuyên biệt dành cho những thí sinh xuất sắc nhất;  \n- Cơ hội tham gia trực tiếp các dự án công nghệ triệu đô của Ngân hàng & tiếp tục phát triển giải pháp ý tưởng từ Hackathon thành dự án thực tiễn tại VPBank.  \nBạn có đam mê công nghệ?  \n- Bạn muốn thử sức với các bài toán thực chiến của ngành ngân hàng số?  \n- Bạn đã sẵn sàng bứt phá và chạm tới những cơ hội phát triển sự nghiệp tại VPBank?  \nVPBank Technology Hackathon 2025 sẵn sàng chào đón Bạn!  \nĐăng ký ngay hôm nay để trở thành những chiến binh đầu tiên tham gia hành trình chinh phục thử thách hấp dẫn đang chờ đợi Bạn phía trước.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '89 Lang Ha, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1005, 184, 2, 'Junior/Senior/Expert Java Developer', 'Top 3 reasons to join us\n1. Top-tier banking environment in Vietnam\n2. Challenging opportunities for the “Greater” You\n3. Attractive career path and benefits\n\nJob description\nA. Software Development\n• Responsible for ensuring that the bank\'s digital platforms work well by managing back end site databases, performance issues, security and that the server, application and database communicate with each other.\n• Responsible for collaborating with business tribes to understand the needs and technical requirements before building a web application.\n• Responsible for the server-side web application logic and integration with front-end codes\n• Collaborate with Front End Developers to design more functional and cohesive codes to enhance user experience.\n• Responsible for driving the application lifecycle with a key focus in coding and debugging of web applications based on feedback from testers and users.\n• Compile and analyze data, process and codes to troubleshoot problems and identify areas for improvement.\n\nB. Software Documentation\n• Work closely with tribe and squad members to translate business requirements into technical design documents.\n• Review and implement technical requirement documents by coding flowcharts, layouts, diagrams, charts, code comments and guides for the program.\n\nYour skills and experience\nA. Domain Expertise\n• 3 - 8 years of relevant experience in software development in Finance - Banking domain\n• Solid foundation in Java programming.\n• Experience in development on ESB, API platforms, and Kafka platforms.\n• Understanding of SOAP and RESTful services, with knowledge of message standards such as JSON and XML.\n• Basic knowledge of databases such as Oracle, MS SQL, etc.\n• Experience using tools such as FTP, SSH, and XML editors.\n• Familiarity with CI/CD toolchains: Git, Jenkins, Maven, Nexus, etc.\n• Possess ESB/API certifications from Oracle/IBM/TIBCO, Mulesoft, etc.\n• Experience in programming with XQuery and XSLT.\n• Experience in AWS (bonus point)\n\nB. Agile / Digital Experience\n• Understands Agile principles, practices and Scrum methodologies.\n• Experience working in Agile teams to support digital transformation projects.\n\nC. Qualifications\n• Bachelor\'s degree in computer science, software engineering or information technology\n• English according to TCB\'s regulations in each period.\n\nD. Personal Attributes\n• Passionate about technology and excited about the impact of emerging / disruptive technologies\n• Ownership mindset with a focus on getting things fixed, not simply discovered\n• A self-starter who thrives in an environment that fosters entrepreneurial thinking and innovation\n• Believes in the non-hierarchical culture of collaboration, transparency and trust across the team\n\nWhy you\'ll love working here\nWHY BECOME IT/DATA EXPERTS AT TECHCOMBANK?\n• Investing over 500 million USD to develop large-scale IT projects, Techcombank is one of the leading banks in Technology trends in Vietnam\n• You will grow with Techcombank by having the opportunity to learn from top experts from across the world\n• Techcombank provides a rewarding remuneration structure that commensurate with your achievement and contribution\n• Techcombank is the Top 2 Best place to work in the banking industry where you can experience various exciting activities throughout the year: Company anniversary, Team building, Active Saturday, Year End Party, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 6 Quang Trung, phường Trần Hưng Đạo, Hoan Kiem, Ha Noi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1006, 545, 2, 'Software Developer (PHP/ Laravel/ MySQL)', 'Tham gia phát triển, tối ưu và bảo trì hệ thống phần mềm của công ty. Đảm bảo phần mềm vận hành hiệu quả, bảo mật và thân thiện với người dùng. Phối hợp chặt chẽ với các bộ phận liên quan để triển khai sản phẩm đúng tiến độ, đáp ứng nhu cầu thực tế và không ngừng cải tiến chất lượng kỹ thuật cũng như trải nghiệm người dùng.\n\nNHIỆM VỤ CHÍNH\n- Tham gia phân tích, thiết kế và lập trình các module phần mềm theo yêu cầu.\n- Viết mã nguồn đảm bảo hiệu suất, bảo mật và khả năng mở rộng.\n- Phối hợp với nhóm kiểm thử để sửa lỗi và cải tiến hệ thống.\n- Cập nhật và viết tài liệu kỹ thuật liên quan đến phần mềm được phát triển.\n- Tham gia vào việc bảo trì, nâng cấp hệ thống hiện tại.\n- Tích cực trao đổi với các bộ phận khác (BA, Tester, UI/UX...) để đảm bảo chất lượng sản phẩm.\n- Đề xuất các giải pháp kỹ thuật và công nghệ để cải tiến sản phẩm.\n- Báo cáo công việc theo yêu cầu của cấp trên.\n\nYour skills and experience\n- Tốt nghiệp chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Có kiến thức về OOP, design pattern.\n- Thành thạo Laravel Framework, ưu tiên ứng viên có kinh nghiệm thực tế với các dự án Laravel.\n- Thành thạo MySQL; có kinh nghiệm với MongoDB là một lợi thế.\n- Sử dụng thành thạo Git để quản lý mã nguồn và làm việc nhóm.\n- Có kinh nghiệm thiết kế và phát triển RESTful API.\n- Tinh thần trách nhiệm trong công việc cao, thông minh, chăm chỉ, cẩn thận.\n- Kỹ năng giải quyết vấn đề, tư duy logic nghiệp vụ tốt.\n- Ưu tiên ứng viên có kinh nghiệm phát triển hệ thống LMS hoặc phần mềm quản lý đào tạo.\n- Ứng viên có hiểu biết hoặc từng làm việc với Vue.js hoặc React.js để hỗ trợ phần giao diện.\n- Có từ 1 năm kinh nghiệm phát triển phần mềm backend với PHP/Laravel.\n- Khả năng phối hợp hiệu quả với frontend team hoặc xử lý các phần giao diện đơn giản là một lợi thế.\n\nWhy you\'ll love working here\n- Thu nhập cạnh tranh: 10.000.000 – 15.000.000/tháng.\n- Hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty: Nghỉ phép năm, nghỉ lễ, Tết theo quy định của công ty, tiệc công ty, team-building, du lịch hàng năm.\n- Được training, tiếp xúc, giao lưu, học hỏi với những đồng nghiệp giỏi, đam mê công nghệ và tâm huyết với sản phẩm.\n- Có cơ hội tham gia trực tiếp vào các dự án giáo dục quy mô lớn, hợp tác, tiếp xúc gặp gỡ với nhiều trường đại học trên toàn quốc. Cơ hội thăng tiến lên vị trí Trưởng nhóm chỉ sau 6–12 tháng nếu thể hiện tốt.\n- Đội ngũ khởi nghiệp trẻ, nhiệt huyết, tham vọng và nhân văn. Tất cả đồng lòng tạo ra giá trị thực tế cho gia đình, nhà trường và xã hội. Môi trường an toàn, lành mạnh, drama-free.\n- Thời gian làm việc:\n  - 8h00 - 17h30 (thứ 2 đến thứ 6)\n  - 8h00 - 12h00 (thứ 7)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, toà nhà VIT, 519 Kim Mã, Ngọc Khánh, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1007, 618, 2, 'Software Engineer (C#, Java, .Net, MySQL, Oracle)', 'Job description\n- Quản lý, khai thác và sử dụng có hiệu quả các phần mềm.\n- Xây dựng, phát triển các phần mềm phù hợp với yêu cầu của công ty.\n- Sửa chữa, bảo trì, duy trì hệ thống phần mềm. Quản lý hệ thống CNTT.\n\nYour skills and experience\nYêu cầu công việc:\n- Kỹ năng giao tiếp và kỹ năng làm việc nhóm tốt;\n- Có ý thức tự giác, cẩn thận, trung thực và tinh thần trách nhiệm cao trong công việc;\n- Có khả năng làm việc độc lập, chịu áp lực công việc cao;\n- Khả năng học hỏi và phát triển;\n- Khả năng làm việc theo ca, kíp và lịch làm việc linh hoạt;\nTiêu chuẩn tuyển dụng:\n- Là công dân Việt Nam, tuổi đời từ 21 đến 35;\n- Giới tính: Nam, Nữ\n- Trình độ: Đại học trở lên, chuyên ngành Phần mềm/ Lập trình.\n- Sử dụng thành thạo ít nhất một ngôn ngữ lập trình: Ưu tiên C#/C++/Java/.Net ...\n- Có hiểu biết sâu về SQL, MySQL/ Oracle\n- Có kinh nghiệm với một trong các Frontend Framework\n- Kinh nghiệm từ 3 năm trở lên, ưu tiên có kinh nghiệm và hiểu biết về các phần mềm về hải quan: Cargo sport/ Hermes/ Hải quan một cửa …\n- Tiếng Anh: Giao tiếp cơ bản/ đọc hiểu tài liệu chuyên ngành tiếng Anh.\n\nWhy you\'ll love working here\n- .', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cảng hàng không quốc tế Nội Bài, Xã Phú Cường, Huyện Sóc Sơn, Soc Son, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1008, 619, 2, 'QA QC Engineer - Functional & AI Tester (English)', '🌍 Join SynergieGlobal – Where Innovation Meets Excellence!\nAt SynergieGlobal, our global expertise and client-first mindset help businesses lead in an ever-evolving tech landscape. We foster a collaborative, innovation-driven culture where top talent tackles complex challenges head-on. If you\'re passionate about high-impact work and next-gen technology, we’d love to have you on board.\n\n🚀 Why Join SynergieGlobal?\n🌍 English-speaking & High-tech Environment – Collaborate directly with U.S. teams on cutting-edge, innovative projects\n💸 Profit-sharing Program – Your contributions drive success, and you share in the rewards\n🤝 Training & Career Growth – Ongoing learning opportunities with a clear path for professional development and advancement\n\n🔍 What You\'ll Do\n✅ Create & Execute: Develop test plans and test cases based on project needs, covering functional, non-functional, and Voice AI-specific scenarios\n✅ End-to-End Validation: Ensure applications and AI systems function correctly throughout the development lifecycle\n✅ Simulate User Experience: Validate AI response quality by simulating real-world usage, identifying bias, and testing robustness\n✅ Document Findings: Capture and annotate screenshots/videos to report anomalies and unexpected outputs\n✅ Track Bugs: Log and monitor issues using Trello, Jira, or equivalent, with clear documentation\n✅ Test Reliability: Assess AI model performance for accuracy, scalability, and consistency\n✅ Collaborate & Improve: Work with developers and AI engineers to troubleshoot and refine AI-driven features\n\nYour skills and experience\n🖥 Technical Skills\n📅 3+ years in software quality assurance or functional testing roles, preferably in web or AI-related environments\n💡 Strong understanding of software testing methodologies\n🌐 Proficient in browser-based testing and troubleshooting\n📸 Skilled in screen capturing, recording, and annotation\n🛠 Familiar with project tools (Trello, Jira, or equivalents)\n🤖 Basic understanding of LLMs and AI tools\n🕵️‍♂️ Experience with browser dev tools is a plus\n🧪 Familiarity with automation tools (Selenium, Playwright, etc.)\n\n🗣 Soft Skills\n🗣 Fluent English: Comfortable communicating with global teammates and AI systems\n📝 Clear Communicator: Able to report issues and collaborate effectively\n🔍 Attention to Detail: Thorough and precise in testing processes\n🧠 Critical Thinking: Capable of identifying edge cases and potential issues\n\nWhy you\'ll love working here\n💰 Competitive salary based on experience (with annual reviews)\n🎉 13th-month salary + Profit sharing\n🌴 12 days annual leave\n⏰ 40-hour work week with flexible hours\n✈️ Annual company trips + birthday celebrations\n📈 Clear career growth path\n🌟 Supportive, high-tech U.S. working environment with modern tools and global exposure\n📚 Ongoing training in both technical and soft skills\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tran Quang Khai, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1009, 620, 2, 'Data Engineer (Python/Golang/Java/C++)', 'We are looking for a highly skilled Data Engineer to design, develop, and maintain scalable data pipelines and infrastructure. In this role, you will collaborate closely with Data Analyst, Data Scientist, and cross-functional teams to ensure seamless data availability, reliability, and performance. Your responsibilities will include building and optimizing ETL workflows, enhancing data storage efficiency, and integrating diverse data sources to support advanced analytics and business intelligence initiatives. This position reports to the Data & Analytics Manager / Head of Business Technology Solutions.\n\nKey Responsibilities\n\n- Engage in the full lifecycle of data platform development, including building and maintaining data warehouses and data lakes, as well as designing, implementing, and optimizing scalable ETL processes (batch/streaming) to support analytics, machine learning, and business intelligence initiatives.\n- Collaborate with development team to integrate data from various sources, including from core system database, APIs and streaming platform.\n- Contribute to building the data infrastructure for a Quant Trading Platform, including real-time market data ingestion, processing, and management to support scalable and efficient algorithmic trading strategies.\n- POC and adopting new technologies to improve data platform management in large-scale high throughput.\n- Ensure data integrity, quality, and governance by implementing best practices in data validation and monitoring.\n- Ensure compliance with security, privacy, and regulatory standards for data handling.\n- Reporting and other tasks relevant to data engineer domain knowledge.\n- Bachelor/Master Degree in Applied Mathematics, Quantitative and Computational Finance, Computer Science or equivalent domain.\n\nYour skills and experience\n\n- 3+ years of experience in Data Engineering or similar role.\n- Solid technical skill, proficient in programming languages such as Python (or Go, Java, C++) and are willing to learn new technologies.\n- Experience with big data technologies (Spark, Hadoop, Beam, Kafka) and distributed computing.\n- Knowledge of ETL tools (Airflow, dbt, Talend, etc.), DevOps and CI/CD for data pipelines.\n- Hands-on experience with cloud platforms (GCP, Azure, AWS) is a plus.\n- Previous experience in a business or industry-specific setting (e.g., finance, retail, healthcare) is a plus.\n- Strong teamwork skills, honesty, dignity, and responsibility.\n- Precision, passion, open-mindedness, and quick self-learning skills in big data, as well as enthusiasm for solving business problems.\n\nWhy you\'ll love working here\n\n- Attractive salary\n- Government Social Insurance is based on full of gross salary\n- Full salary during probation\n- Working Monday – Friday, 8am:5pm\n- For every 5 work-years, +2 day to annual leave​​\n- Diverse company culture activities: Annual Year End Party, Quarterly party, Company outings, Team building, Coffee and Snack, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sailing Tower, 111A Pasteur, Ward Ben Nghe, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1010, 244, 2, 'Software Developer (E-Commerce & AI Integration)- 2 EXP', '1. Thiết kế và xây dựng hệ thống sàn thương mại điện tử\n2. Phát triển hệ thống Affiliate (tiếp thị liên kết)\n3. Tích hợp AI:\n- Gợi ý sản phẩm (recommender system)\n- Chatbot hỗ trợ khách hàng\n- Phân tích hành vi người dùng\n- Tự động tối ưu hóa quảng cáo/sản phẩm\n4. Vận hành và bảo trì hệ thống:\n- Quản lý cơ sở dữ liệu\n- Giám sát hiệu suất, bảo mật\n- Tối ưu trải nghiệm người dùng\n\nYour skills and experience:\n- Thành thạo ngôn ngữ lập trình Web (JavaScript/TypeScript, Python, PHP,...)\n- Hiểu kiến trúc hệ thống thương mại điện tử\n- Có kinh nghiệm với các mô hình Affiliate\n- Biết sử dụng hoặc tích hợp AI (OpenAI API, TensorFlow, hoặc thư viện ML cơ bản)\n- Hiểu về bảo mật, phân quyền người dùng\n- Có kinh nghiệm tích hợp cổng thanh toán.\n- Làm việc tại khu vực Quận 3\n\nWhy you\'ll love working here:\n- Lương có kinh nghiệm từ 2 năm trở lên Junior / Fresher+ ( 12-20 Triệu )/ Lương thỏa thuận cho những trường hợp có kinh nghiệm đặc biệt.\n- Thù lao và phụ cấp theo chính sách chung của công ty.\n- Thù lao đặc thù theo tiến độ công việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '213 Điện Biên Phủ, Phường Võ Thị Sáu, Quận 3, TP. Hồ Chí Minh, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1011, 606, 2, 'Data Operator/Senior IT Operator (Oracle, PL/SQL, DBA)', 'Top 3 reasons to join us\n\n- People Development\n- High promotion opportunities\n- Very attractive salary package\n\nJob description\nNhóm 1: Lập kế hoạch và chuẩn bị\n- Lập kế hoạch chi tiết cho việc giám sát hệ thống nhằm phát hiện sớm các vấn đề có thể phát sinh.\n- Rà soát lại danh mục tài liệu vận hành và cập nhật trên hệ thống quản lý version của từng hệ thống quản lý.\n- Lập kế hoạch xây dựng các công cụ đo lường hệ thống, công cụ hỗ trợ vận hành nhằm ổn định hệ thống, vận hành tối ưu.\n- Xây dựng kế hoạch triển khai các cập nhật bản vá lỗ hổng bảo mật cho các hệ thống đang quản lý.\n\nNhóm 2: Vận hành và bảo trì\n- Hỗ trợ level 2 theo danh mục dịch vụ đã cam kết SLA\n- Trao đổi với nhà cung cấp và phòng ban nội bộ khác để cài đặt hệ thống/triển khai hệ thống, điều tra khi xảy ra sự cố và giải quyết vấn đề\n- Theo dõi hiệu suất hệ thống để giữ cho hệ thống khả dụng và ổn định\n- Cấu hình hệ thống: Thay đổi cấu hình hệ thống theo yêu cầu Nghiệp vụ\n- Khắc phục sự cố và giải quyết các vấn đề kịp thời theo yêu cầu SLA\n- Cập nhật các bản vá lỗi thường xuyên theo định kỳ\n\nNhóm 3: Phân tích, cải tiến và hỗ trợ\n- Đưa ra danh sách các điểm yếu, các yêu cầu góp phần tăng cường hiệu suất, chất lượng hệ thống.\n- Tích cực nêu ý tưởng cải tiến, tự động hóa để giảm bớt công việc thủ công, nâng cao hiệu quả hoạt động vận hành\n- Tư vấn và hỗ trợ Dev và SA phân tích tác động của những thay đổi trong hệ thống, nhằm giữ cho hệ thống hoạt động tốt và ổn định\n- Cung cấp tư vấn kỹ thuật, hỗ trợ cho Nhóm hỗ trợ và người sử dụng\n- Tư vấn, hướng dẫn cho các thành viên khác trong đơn vi về chức năng/năng lực của hệ thống.\n\nNhóm 4: Quản lý và báo cáo\n- Chịu trách nhiệm về hiệu suất, tính toàn vẹn và bảo mật của ứng dụng\n- Thông báo trước cho cấp quản lý về các điểm khiếm khuyết và đề xuất phương pháp giảm thiểu rủi ro.\n- Phối hợp chặt chẽ với BA và Dev để hỗ trợ các nhiệm vụ liên quan đến hệ thống\n\nPhụ trách văn bản, quy trình vận hành ứng dụng. Tuân thủ Quy trình vận hành và các quy trình liên quan khác trong VPBank\n\nYour skills and experience\nTrình độ Học vấn​/ Educational Qualifications\n- Tốt nghiệp Đại học chuyên nghành CNTT, Khóa học máy tính hoặc bằng cấp tương tương.\n\nCác Kinh nghiệm liên quan/ Relevant Experience\n- Có từ 4 năm kinh nghiệm trong việc phát triển, vận hành và bảo trì hệ thống CNTT cho Banking/Fintech đặc biệt là các hệ thống lớn như AML, DWH, Corebanking T24 là một lợi thế.\n\nKiến thức/ Chuyên môn có liên Quan\n- Hiểu rõ kiến trúc CSDL Oracle có hiểu biết về lập trình và tìm lỗi trên một số ngôn ngữ lập trình thông dụng như: PL/SQL, Java,…\n- Có hiểu biết về việc phát triển báo cáo; vận hành/ phát triển ETL Job\n- Có kiến thức về CI/CD, cụ thể từng làm hoặc tiếp cận với Jenkins\n- Có kinh nghiệm làm việc với DB Oracle, SQL Server\n- Có hiểu biêt DataPipeline trên nền tảng AWS\n- Có kinh nghiệm vận hành và phát triển trên AWS Cloud (VPC, EC2, Lambda, Dynamo, Glue, Step Functions..)\n- Có kinh nghiệm làm việc với AI/ML\n- Có kinh nghiệm phát triển Teraform\n- Có kiến thức làm về Spark/SparkSQL\n- Có kinh nghiệm sử dụng Python/ PySpark\n- Có kinh nghiệm làm việc với các hệ điều hành máy chủ như Windows Server, Linux\n- Có kinh nghiệm làm việc với Web Server: Web Logic, khác\n- Có kinh nghiệm phát triển, vận hành trên nền tảng AWS Cloud\n- Có kinh nghiệm làm việc với các công cụ giám sát: Graphana,  ITom, Cloud Watch...\n- Có kinh nghiệm triển khai, vận hành/ phát triển giải pháp Oracle OFSAA là một lợi thế lớn.\n\nWhy you\'ll love working here\n5 LÝ DO BẠN KHÔNG THỂ BỎ LỖI VPBANK TECHNOLOGY HACKATHON 2025\n- Với thông điệp "Chinh phục công nghệ, Kiến tạo tương lai", VPBank Technology Hackathon 2025 cam kết mang tới những trải nghiệm đáng giá:\n- Tự do lựa chọn đề bài công nghệ trong lĩnh vực Ngân hàng để chinh phục thử thách;\n- Đội ngũ hướng dẫn với gần 40 chuyên gia giàu kinh nghiệm của VPBank cùng AWS sẽ đồng hành & hướng dẫn Bạn qua các chặng thi đấu;\n- Giải thưởng hấp dẫn bằng tiền mặt từ VPBank & phần thưởng tài trợ từ đối tác AWS;\n- Cơ hội gia nhập đội ngũ VPBank Young Talents 2025 – với lộ trình phát triển nghề nghiệp chuyên biệt dành cho những thí sinh xuất sắc nhất;\n- Cơ hội tham gia trực tiếp các dự án công nghệ triệu đô của Ngân hàng & tiếp tục phát triển giải pháp ý tưởng từ Hackathon thành dự án thực tiễn tại VPBank.\n- Bạn có đam mê công nghệ?\n- Bạn muốn thử sức với các bài toán thực chiến của ngành ngân hàng số?\n- Bạn đã sẵn sàng bứt phá và chạm tới những cơ hội phát triển sự nghiệp tại VPBank?\nVPBank Technology Hackathon 2025 sẵn sàng chào đón Bạn!\nĐăng ký ngay hôm nay để trở thành những chiến binh đầu tiên tham gia hành trình chinh phục thử thách hấp dẫn đang chờ đợi Bạn phía trước.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '89 Lang Ha, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1012, 599, 2, 'Fullstack Engineer (NodeJS, VueJS, NuxtJS, Express)', 'We are looking for a fullstack engineer with experience in agile development and the ability to demonstrate strong technical skills in both FE and BE. You will be responsible for developing important functions such as implementing a payment and points management system for the SNS platform we are developing, wallet integration using blockchain technology, and token issuance.\nIf you would like to get involved with generative AI technology in the future, there will also be opportunities to participate in related projects.\n\nJob Description\n- Frontend UI/UX design and development using Vue.js and Nuxt.js\n- Backend API design and development using Node.js, Express, and MySQL\n- Design and development of payment systems and point management systems\n- Implementation of wallet integration and token issuance utilizing blockchain technology\n- System infrastructure setup and management using AWS and Docker\n- Collaboration with Japanese development teams to promote agile development processes\n- Improvement of code quality, refactoring, and performance optimization.\n\nIdea candidate\n- Flexible in adapting to technological advancements and proactive in learning new frameworks and tools\n- Team-oriented with strong communication skills for smooth collaboration\n- High problem-solving ability, capable of identifying and addressing issues independently\n- Interested in utilizing skills in specialized fields such as blockchain and payment systems\n- Motivated to challenge generative AI technologies in the future.\n\nYour skills and experience\nRequired skills & experiences\n- Native Vietnamese speaker\n- Experience with Node.js, JavaScript, and TypeScript\n- Experience in frontend design, development, and operation using Vue.js, Nuxt.js, etc.\n- Experience in backend development using Express and MySQL\n- Development and operational experience with AWS\n- Experience in Agile system development\n- Experience developing payment or point management systems\n- Experience developing high-traffic websites, large scale\n- Experience with SQL tuning/optimization.\n\nA plus\n- Development experience with containerization using Docker\n- Experience developing escrow and payment processing systems\n- Experience in blockchain/Web3 system development\n- System development experience in B2C entertainment industry\n- Experience developing voice-enabled applications and systems\n- Development experience integrating Large Language Models (LLMs)\n- Passion for generative AI technologies\n- Strong cloud platform experience with AWS, including DevOps practices, CI/CD implementation, and system monitoring\n- Hands-on experience with infrastructure as code using Terraform\n- Ability to design and maintain scalable, reliable cloud systems (AWS preferred)\n- Strong knowledge of database optimization and maintenance, especially with Amazon RDS\n- Proficiency in Shell and Python scripting.\n\nWhy you\'ll love working here\n- 18 ngày nghỉ/năm\n- Hỗ trợ ăn trưa\n- Team building package\n- BHXH full lương\n- Phụ cấp công tác\n- Lương tháng 13\n- Giờ làm việc: 9:00 - 18:00 (Thứ Hai - Thứ Sáu)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hive Villa, 29 Nguyễn Bá Lân, Thảo Điền, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1013, 592, 2, 'Golang/GCP Server Side Engineer', 'Top 3 reasons to join us\n- Flexible working time (Hybrid) \n- Competitive salary, bonus, expenses and allowances\n- Chance to upgrade current position \n\nJob description\n- Server-side development and maintenance in service development\n- Research on tools and libraries\n- Server-side testing\n- Proactively sharing knowledge with the organization\n- Development of middleware (including BFF)\n\nYour skills and experience\nMust:\n- Willingness to develop and improve services with a sense of ownership\n- Experience developing with Golang/Nodejs/Python from total 3 years+\n- Development experience with Golang (1 years+)\n- Experience developing infrastructure using GCP (1 years+)\n- Experience tuning query performance using SQL (2 years+)\n- Experience using containers such as Docker\n- Experience with automation using CI/CD tools\n- Experience developing in a team using Git\n- Experience with Scrum development\nPreferable:\n- Development experience with Node.js and TypeScript\n- Experience in designing server-side architecture\n- Experience in API design using mock servers\n- Development experience using data warehouses\n- Development experience using GCP\'s AI/ML services\n\nWhy you\'ll love working here\n- Annual Leave: 15 days/ year\n- Flexible Working Time (Hybrid Working & Flexible Check-in) \n- 100% Salary in Probation\n- Salary Review (Twice a Year) \n- 13th Salary bonus\n- Social Insurance for 100% Salary\n- Travel Allowance\n- Premium Health Care Insurance for employees (PTI)\n- Annual Health Check \n- Full Device Provide: MAC equipment, Monitors,.. \n- Monthly Happy Hour, Company Trip, Year End Party and Events\n- Marriage / Baby Gift\n- Funeral Expenses\n- Referral Bonus\n- Skill Improvement Course for Employees (Udemy)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor An Phu Plaza, Vo Thi Sau Ward, District 3, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1014, 592, 2, 'Golang/GCP Server Side Lead Engineer', 'Top 3 reasons to join us\n• Flexible working time (Hybrid) \n• Competitive salary, bonus, expenses and allowances\n• Chance to upgrade current position \n\nJob description\n• Server-side development and maintenance in service development\n• Research on tools and libraries\n• Server-side testing\n• Proactively sharing knowledge with the organization\n• Development of middleware (including BFF)\n\nYour skills and experience\nMust: \n• Sense of ownership and willingness to develop and improve services\n• 4 years+ of development experience with Golang\n• 3 years+ of experience in infrastructure design and development using GCP\n• 3 years+ of experience in query performance tuning using SQL\n• 3 years+ of experience participating in discussions on technical feasibility at the requirement definition stage and creating basic designs\n• Experience using containers such as Docker\n• Experience with automation using CI/CD tools\n• Experience in team development using Git\n• Experience with Scrum development\nPreferable:\n• Development experience with Node.js and TypeScript\n• Experience in designing server-side architecture\n• Experience in API design using mock servers\n• Development experience using data warehouses\n• Development experience using GCP\'s AI/ML services\n• Experience in team building\n\nWhy you\'ll love working here\n• Annual Leave: 15 days/ year\n• Flexible Working Time (Hybrid Working & Flexible Check-in) \n• 100% Salary in Probation\n• Salary Review (Twice a Year) \n• 13th Salary bonus\n• Social Insurance for 100% Salary\n• Travel Allowance\n• Premium Health Care Insurance for employees (PTI)\n• Annual Health Check \n• Full Device Provide: MAC equipment, Monitors..\n• Monthly Happy Hour, Company Trip, Year End Party and Events\n• Marriage / Baby Gift\n• Funeral Expenses\n• Referral Bonus\n• Skill Improvement Course for Employees (Udemy)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor An Phu Plaza, Vo Thi Sau Ward, District 3, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1015, 260, 2, 'Fullstack Mobile Dev (React Native, NodeJS, ReactJS)', 'WHO ARE WE? Digital Unicorn is a French digital agency with a passionate and ambitious team. We specialize in:\n\nMobile Application Development\nWebsite Development\nAI/Deep Learning\nUX/UI Design\n\nWe’re more than just a company — we’re a small hub for those who want to step into an international working environment. Here, you’ll train, work, and build your career foundation, all while growing friendships that last.\n\nAt Digital Unicorn:\n\nWe share and support each other\nWe build meaningful products for startups\nWe create a space where you can enjoy working and growing\n\nWE ARE HIRING: Fullstack Mobile Developer:\n\nLevel: Mid-Senior\nType: Full-time In-house, On-site\n\nAbout the Role\nDigital Unicorn is seeking a Fullstack Mobile Developer who is experienced in building high-performance mobile applications using React Native and has a solid understanding of backend development with NodeJS. The ideal candidate will join a high-priority project and contribute to both the frontend (mobile) and backend development lifecycles.\nThis is a great opportunity to work in a dynamic, fast-paced environment with a talented team.\n\nResponsibilities:\n- Develop and maintain cross-platform mobile applications using React Native\n- Build and manage backend services using NodeJS and GraphQL\n- Collaborate with designers and product managers to deliver seamless user experiences\n- Write clean, efficient, and scalable code using Typescript\n- Ensure the performance, quality, and responsiveness of applications\n- Participate in code reviews and contribute to team knowledge-sharing\n- Troubleshoot and debug technical issues across the full stack\n\nYour skills and experience\n- 4+ years of experience as a Fullstack Developer or Mobile Developer\n- Strong proficiency with React Native, NodeJS, ReactJS, Typescript, GraphQL\n- Experience integrating RESTful APIs and/or GraphQL endpoints\n- Solid understanding of software development best practices\n- Ability to communicate in English at a basic speaking level\n- Team player with excellent problem-solving skills\n\nWhy you\'ll love working here\n- Training policy, salary, and bonus that match your skills and experience\n- Provision of full of devices for work\n- 100% salary during the probation period\n- Full insurance policies\n- Dynamic, comfortable, and creative working environment\n- Team Building events/ company trips every year\n- Snacks and fruits for breaks\n- Sports activities to recharge positive energies\n- Immerse in an English-speaking environment for professional foreign communication', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3F, 94 Ho Nghinh, Son Tra, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1016, 621, 2, 'Senior Java Developer/ Java Tech Lead', 'Top 3 reasons to join us\n\n- Culture Built by Tech People, for Tech People\n- Flexible in-office and remote work arrangements\n- Premium Health Coverage\n\nJob description\n\n- Refactoring and standardization of existing systems.\n- Documentation and alignment with governance and security standards.\n- Auto-updating libraries and integrations with GCP.\n- Writing clean, well-tested code that adheres to platform architecture and best practices.\n- Capable of setting technical direction, leading code reviews, and ensuring consistent quality and alignment across teams.\n- Provide continuous support and guidance to less senior colleagues through regular coaching activities and support them in fulfilling their personal development plans.\n\nYour skills and experience\n\n- Strong experience in backend development with over 5 years of expertise in Java (For Lead: at least 7 years with 2+ years of managing a team).\n- Solid experience in JavaScript, with expertise in ReactJS, Redux and related libraries.\n- Solid skills in software architecture and design.\n- Excellent technical documentation abilities.\n- Strong English communication skills (both verbal and written), particularly in global software development environments.\n- Experience working in offshore software consulting environments.\n- Previous exposure to video streaming platforms is a significant advantage, though not mandatory.\n\nWhy you\'ll love working here\nJoin us to make the world a better place. Every day is an opportunity to learn new things and do something you\'re proud of.\n\nOUR VALUES\n\nCollaboration: At CBTW, collaboration is the heart of our success. We foster a culture where our people, clients, and network work together, to encourage innovative ideas and deliver meaningful results that shape a better world.\n\nCommitment: We are dedicated to making a positive impact on the environment and society. At the heart of our commitment is education, as we firmly believe in empowering future generations with knowledge and opportunities. Through allocating a significant portion of our resources, we aim to create a better world and contribute to a sustainable future.\n\nEvolution: We eagerly embrace change, cultivating an environment of continuous evolution. We empower our team with personalized career paths, that fuel growth and enhance skills. We prioritize improvement and innovation, delivering advanced solutions to clients, and aim to strengthen alliances within our network of partners.\n\nPositive Thinking: We infuse optimism and creativity into all aspects of our work through Positive Thinking. We approach every situation with open-mindedness, transparency, flexibility, and solution orientation. Working together, we bring our positive dynamism to benefit our people, clients, and network.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa, Tan Binh, Ho Chi Minh; TNR Tower, 54A Nguyen Chi Thanh, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1017, 331, 2, 'System Engineer (Junior/Middle)', 'TEKO đang tìm kiếm một người có kinh nghiệm trong lĩnh vực quản lý hạ tầng Data Center để tham gia đảm bảo vận hành, tối ưu và bảo trì hệ thống on-premises của công ty. Vị trí này sẽ làm việc chặt chẽ với các thành viên trong team để giám sát phần cứng, quản lý kết nối mạng, đảm bảo hiệu suất và tính sẵn sàng của hệ thống, cũng như đề xuất các giải pháp cải tiến hạ tầng.\n\nJob Description:\n\n- Triển khai, vận hành & giám sát hạ tầng vật lý tại Data Center (Server, Storage, Router, Switch, Firewall, Load Balancer,...).\n- Quản lý kết nối mạng giữa các hệ thống on-prem & các dịch vụ liên quan.\n- Giảm thiểu downtime, xử lý sự cố và đảm bảo hệ thống hoạt động ổn định\n- Lên kế hoạch và thực hiện các hoạt động bảo trì định kỳ, nâng cấp phần cứng và phần mềm.\n- Đề xuất và triển khai các biện pháp tối ưu hiệu suất hệ thống, bảo mật dữ liệu và an toàn thông tin.\n- Phối hợp với nhóm kỹ thuật để triển khai các ứng dụng và dịch vụ trên hạ tầng on-prem, đảm bảo sự đồng bộ và hiệu quả cũng như giám sát, phát hiện và khắc phục các sự cố.\n- Phối hợp với các nhà cung cấp và đối tác để đảm bảo việc cung cấp dịch vụ và linh kiện thay thế.\n- Xây dựng tài liệu kỹ thuật, SOP và hướng dẫn vận hành hạ tầng, hỗ trợ các thành viên trong team.\n- Theo dõi và báo cáo về tình trạng hệ thống, đề xuất các phương án mở rộng và nâng cấp khi cần thiết.\n\nYour skills and experience:\n\n- Tốt nghiệp đại học chuyên ngành CNTT, Khoa học máy tính, Kỹ thuật mạng hoặc các ngành liên quan.\n- Kinh nghiệm triển khai, vận hành, giám sát hệ thống Máy chủ. Ex: Hệ thống máy chủ (DELL, HP), Storage (SAN/NAS), Hệ thống ảo hóa (VMware, Proxmox, Xen Citrix), Hệ thống Sao lưu và phục hồi dữ liệu.\n- Kinh nghiệm làm việc với các hệ điều hành Linux/Windows Server.\n- Hiểu biết về hệ thống mạng (LAN, WAN, VPN, Firewall, Load balancer) và các giao thức định tuyến động như BGP, OSPF,...\n- Kinh nghiệm triển khai, vận hành, giám sát hệ thống mạng kết nối (với các thiết bị của các hãng như Cisco, Juniper, Fortinet…\n- Hiểu biết về các công cụ giám sát hệ thống (Zabbix, Prometheus, Grafana, v.v.).\n- Ưu tiên ứng viên có chứng chỉ chuyên môn như CCNA, CCNP, LPI, VMware,...\n- Hiểu biết và có kinh nghiệm thực hiện đáp ứng tuân thủ các tiêu chuẩn quốc tế về An toàn thông tin như ISO27001\n- Kỹ năng xử lý sự cố, giám sát hiệu suất hệ thống và tối ưu tài nguyên.\n- Khả năng làm việc nhóm tốt, phối hợp với các thành viên trong team để đảm bảo hệ thống hoạt động ổn định.\n\nWhy you\'ll love working here:\n\n- Mức lương thỏa thuận theo năng lực (13 tháng lương + thưởng hiệu quả công việc);\n- Chế độ đãi ngộ hấp dẫn cạnh tranh: hỗ trợ cơm trưa, gửi xe, free cafe, daily food....\n- Môi trường làm việc cởi mở, trẻ trung, có cơ hội thăng tiến trong công việc;\n- Tham gia BHXH theo quy định Luật Lao Động, được công ty mua bảo hiểm bảo lãnh 24h theo chính sách dành riêng cho nhân viên Teko;\n- Được khuyến khích tham gia các chương trình đào tạo, học tập không ngừng trong công ty;\n- Được tham gia các chương trình teambuilding, nghỉ mát do công ty tổ chức hàng quý/năm;\n- Ngày nghỉ: 12 ngày nghỉ phép/ năm và 6 ngày nghỉ ốm nguyên lương (max 18 ngày nghỉ);\n- Giờ làm việc: Thứ 2 - Thứ 6 (09:00 - 18:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Gems Empire Tower, 201 Truong Chinh, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1018, 182, 2, 'Senior Product Prompt Engineer (Java, Python)', 'Summary: We are looking for a visionary Product Prompt Engineer with a strong foundation in backend engineering, capable of building and integrating frontend systems, backend systems, customer service portals, and operations portals using AI tools. In this role, you will be at the forefront of adopting an AI-first approach to product development, continually challenging existing workflows and foundational engineering principles, while engaging in rapid experimentation to enhance value delivery to customers. This is an exciting opportunity for those passionate about product development and AI-driven workflows.\n\nTop 5 Reasons Why We Are the Next Destination for Your Career\n\n1. Innovation-Driven Environment: Work with state-of-the-art technologies, including Serverless AWS, AI-augmented engineering, microservices, Java, and Python.\n2. Impactful Work: Shape products that enhance financial inclusivity and access in emerging markets.\n3. Collaborative Culture: Join a forward-thinking team that values innovation, teamwork, and continuous learning.\n4. Competitive Benefits: Enjoy a comprehensive package, professional growth opportunities, and a balanced work-life environment.\n5. Learning and Growth: Access SMART goals, technical seminars, conferences, and training to support your career advancement.\n\nKey Responsibilities:\n1. Take the lead with AI-first adoption, leveraging AI tools and prompt engineering skills to automate work wherever possible so that we can improve time-to-value.\n2. "Question the requirements", to get to the essence of what is actually needed, ensuring that we are building the right things right.\n3. Collaborate with a new, AI-first product development team where you’ll be at the heart of building and scaling innovative enterprise financial products, driving meaningful impact from day one.\n4. Take end-to-end ownership of the product, designing systems to satisfy customers and validating assumptions with data driven insights.\n5. Innovate like a startup—lead the charge from concept to deployment, continuously testing, learning, and improving your product with every iteration.\n6. Embrace the full product lifecycle; prioritise it, understand it, design it, build it, test it, run it and own it.\n\nYour skills and experience\n\nMust-have skills:\n1. Backend engineering experience: at least 7 years of backend engineering experience in one or more programming languages (Python, Java).\n2. Team Leadership: at least 1 year of experience in leading teams or projects, including mentoring, code reviews, and owning delivery.\n3. System Architecture Design: Strong experience in designing and implementing system architectures, including defining technical solutions and making high-level design decisions.\n4. AI Tools: Proficient with Cursor or Windsurf; comfortable integrating AI tools into the development workflow.\n5. Product-obsessed: You live and breathe product thinking—you’re not just here to generate code, but to own the product and drive its success. You focus on solving customer problems and delivering experiences that make a difference.\n6. Customer focused: You can talk to directly customers or subject matter experts and ask questions to deeply understand their needs so that you can deliver products that resonate.\n7. Creative problem-solver: You tackle complex challenges with creativity and an analytical mindset, always balancing technical decisions with business outcomes.\n8. Adaptability & hustle: You thrive in an ever-evolving environment, where you can wear many hats, pivot quickly, and move fast without losing focus on the big picture.\n9. Team player with an edge: You bring a strong collaborative spirit to an AI-first team, but you’re also ready to lead initiatives and be the go-to person for the features you own.\n10. Fluent in English: You’re a smooth communicator, capable of turning technical jargon into easy-to-understand ideas for both teammates and stakeholders.\n11. Automation lover: You believe in the power of automated testing frameworks to build robust and reliable systems.\n12. Love for Learning: You love learning new domains of knowledge and technologies so that you can build better products faster. You know there is always more to learn and are always open to being wrong.\n13. Early Adopter: You have already built a few simple apps with AI tools, experimented with mcp servers and are familiar with prompt engineering.\n\nNice to Have:\n1. Understanding of System Thinking\n2. Experience with Behaviour Driven Development\n3. Avid Reader\n\nWhy you\'ll love working here\n\nYou’ll love working with us if you are:\n1. Passionate about technology.\n2. Independent but also a good team player.\n3. Comfortable with a high degree of ambiguity.\n4. Focused on usability and speed.\n5. Keen on presenting your ideas to your peers and management.\n\nAt TYME, opportunities are here for the taking. If you want to be part of our purpose and live and lead through our values, we can offer exciting development opportunities through expanded lateral roles, stretch assignments, or people leadership.\n\nSome of our benefits:\n1. Meal and parking allowances are covered by the company.\n2. Full benefits and salary rank during probation.\n3. Insurances such as Vietnamese labor law and premium health care for you and your family.\n4. SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development.\n5. Values-driven, international working environment, and agile culture.\n6. Overseas travel opportunities for training and work-related.\n7. Internal Hackathons and company events (team building, coffee run, etc.).\n8. Pro-Rate and performance bonus.\n9. 15-day annual + 3-day sick leave per year from the company.\n10. Work-life balance 40-hr per week from Mon to Fri.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 5 - 6, East Tower,  Lumiere Riverside, 277 Vo Nguyen Giap,  An Phu Ward, Thu Duc City, HCMC., Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1019, 622, 2, 'QA Tester', 'Collaborate within a multidisciplinary team to develop engineering documentation that ensures compliance with QMS, ISO 9001:2015, and quality control standards, while verifying alignment with customer manufacturing requirements.\n\nKey Tasks:\n• Develop and implement plans to achieve company quality objectives, while monitoring progress and results.\n• Oversee the Quality Management System (QMS).\n• Ensure daily adherence to QMS procedures, assisting staff as needed.\n• Draft and maintain procedures and work instructions.\n• Collect performance data and generate monthly reports.\n• Continuously analyze operations to identify areas for improvement.\n• Manage and promote the effective use of the Internal Reporting (IR) system.\n• Develop and execute product design verification and testing plans.\n• Transfer validated final product designs to project leaders for customer release.\n• Report on the overall state of the QMS to management, providing recommendations for continuous improvement.\n• Perform additional related tasks as required.\n\nYour skills and experience\n\nEducation\n• Bachelor’s degree in electrical engineering or a related field.\n• Additional coursework in electronic design, embedded systems, industrial design, and project management is preferred.\n\nExperience\n• Minimum of two years of quality assurance experience, specifically applying ISO 9001 standards within engineering, product development, or manufacturing.\n• At least one year of experience in test engineering, specializing in electronics, software, or mechanical systems.\n\nTechnical Knowledge\n• General knowledge of manufacturing techniques and principles for electronic, software, and mechanical products.\n• Solid understanding of QA laboratory testing, including test planning, test case development, and execution for mechatronic products (mechanical, electronic, firmware/software).\n• Experience with QA test environments, including Jira, SVN, TestRail, or custom tracking tools like Excel.\n• Knowledge of customer service principles, including needs assessment techniques, quality standards, alternative delivery systems, and customer satisfaction evaluations.\n• Understanding product design verification testing methodologies for mechatronic systems.\n• Expertise in test analysis, test reporting, deviation handling, Statistical Process Control (SPC), and Six Sigma (preferred).\n• Familiarity with industrial standards, including EtherCAT, Ethernet Conformance Test, PROFINET Conformance Test, and DeviceNet Conformance Test.\n• Capabilities in Electromagnetic Interference (EMI) and Electromagnetic Compatibility (EMC) testing at third-party labs (such as Quatest) and certification processes for CE compliance.\n• Experience with Python, LabVIEW, DAQ, and PLC programming is a plus.\n• Implementation of ISO 9001:2015 QMS requirements.\n\nSkills\n• Strong project management, analytical, and communication skills.\n• Independent, objective, detail-oriented, and proactive approach to work.\n• Ability to systematically organize and document QMS performance, assessments, and continuous improvements.\n• Capability to summarize and report QMS findings to management, along with improvement recommendations.\n• Skill in identifying nonconformities in QMS and product designs, collaborating with teams to issue and execute improvement reports.\n• Ability to plan, conduct, and document validation testing of product designs.\n• Effective team player with solid communication skills.\n• Intermediate English.\n\nWhy you\'ll love working here\n• Competitive salary, allowances, and bonus.\n• 100% salary on probationary period.\n• Full social insurance as regulated.\n• Annual 13th-month bonus + annual salary appraisal.\n• 24-day paid leave per year (12 annual and 12 sick leaves).\n• Annual Health Check-up.\n• Premium healthcare and life insurance.\n• Occasional gift for public holidays.\n• Education & Training grant.\n• Participate in networking events and seminars.\n• A talented and experienced multifunction development team.\n• Opportunities to travel abroad.\n• The involvement of the entire project development of company products.\n• Sport recreation, relax room.\n• Team building, company trips.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '4th floor, L11-L12, Mieu Noi, Ward 3, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1020, 255, 2, 'Middle Full-Stack Developer (.NET, ReactJS)', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.  We are looking for a talented and motivated Full Stack Developer (.NET, React) to join our dynamic team. As a Full Stack Developer, you will work on developing and maintaining web applications using .NET, React, and SQL Server. You will collaborate with cross-functional teams to deliver high-quality software solutions that meet our clients\' needs. Core Responsibilities Develop and maintain web applications using .NET, SQL Server, and React. Ensure the quality and performance of applications through testing and code reviews. Follow best practices for software development, including coding standards, code reviews, and version control using Azure DevOps. Work within the SAFe Agile framework to deliver projects on time and within scope. Functional Responsibilities Participate in all phases of the software development lifecycle, including requirements gathering, design, coding, testing, and deployment. Collaborate with cross-functional teams to define and implement new features. Assist in continuous integration and continuous deployment (CI/CD) processes using Azure DevOps. Your skills and experience Technical Skills Proficiency in .NET, React, and SQL Server. Strong understanding of web development principles and best practices. Experience with Azure DevOps for version control and CI/CD processes. Familiarity with the SAFe Agile methodology. Excellent problem-solving skills and attention to detail. Strong communication skills in English, both written and verbal. Things that will separate you from the rest Experience with Node.js Experience with other front-end frameworks/libraries such as Vue.js Angular Knowledge of cloud services and infrastructure, especially Azure. Experience with RESTful API design and development. Understanding microservices and event driven architecture. Education or Certifications Bachelor’s degree in Computer Science, Information Technology, or related field. Why you\'ll love working here Full salary for probation & full coverage of social insurance. Premium healthcare for you and one family member. Monthly childcare support 13th-month salary. Annual Leave: 15 days; Paternity Leave: 6 weeks, Bereavement leave: 10 days. Flexible working time, focus on output (no checking time attendance) Various active sporty clubs: Football, Billiards, Badminton, E-sport clubs Frequent opportunities to travel to US headquarter from 3-6 months.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Six8 Building: 24-26 Phan Dinh Giot Street, Tan Binh District, HCMC., Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1021, 623, 2, 'Business Analyst', 'Job description\n- Receive and unify information and requests from customers.\n- Prepare reports on product orientation, customer needs and market situation.\n- Research and analyze requirements and business processes of the project. Study and analyze similar products at home and abroad and provide product development orientation.\n- Develop presentation documents, explain to programmers to clearly understand the desires and business to optimize the product.\n- Develop various types of software design analysis documents.\n- Develop user manuals after the software is deployed to ensure that the software is used exactly as required.\n- Research and master products, technologies, software solutions, propose the application of new technologies.\n- Coordinate with other departments of the company to ensure project progress and quality.\n\nYour skills and experience\n- University graduate, preferably in IT and related fields.\n- Minimum 1 year of BA experience.\n- Have basic general knowledge of software structure, system design analysis, database.\n- Proficiency in business analysis techniques, modeling business flows such as: Business function models, relational data models, UML language, creating Use cases...\n- Having knowledge of software programming and a passion for technology is an advantage.\n- Proficiency in office software.\n- Good document writing skills.\n- English required\n\nWhy you\'ll love working here\n- Basic salary up to 23M+ project bonus\n- 13th month salary and year-end bonus (based on business results)\n- Working hours from 8:30 am to 6:00 pm from Monday to Friday, off on Saturday and Sunday\n- Probation period up to 2 months with 100% salary\n- Participate in tours and team building at least 2 times/year (there will be long trips to change the working atmosphere).\n- Have the opportunity to participate in quality courses for self-development.\n- Young, dynamic, competitive working environment, working on international projects and products.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No 12, Alley 40 Ngụy Như Kon Tum, Thanh Xuan, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1022, 624, 2, 'Backend Developer (Golang, NodeJS, Linux)', 'Job description\n- Thiết kế và phát triển các back-ends APIs/Service cho hệ thống, sản phẩm của công ty.\n- Xây dựng các sản phẩm theo định hướng của công ty. Phát triển triển các ứng dụng theo mô hình microservice có tính mở rộng và ổn định cao.\n- Tham gia đóng góp ý kiến, phát triển các ý tưởng thành thực tế.\n\nYour skills and experience\n- Tốt nghiệp đại học chính quy chuyên ngành: CNTT, Khoa học máy tính .\n- Tối thiểu ít nhất 1 năm làm việc với vai trò Backend sử dụng Golang hoặc Nodejs\n- Sẵn sàng học và làm việc với các ngôn ngữ mới.\n- Có kinh nghiệm làm việc với mô hình MicroService và các giao thức liên quan như HTTP/HTTP2, gRPC, AMQP …\n- Sử dụng tốt Linux, công nghệ container như Docker.\n- Thành thạo sử dụng CSDL Postgre, MongoDb, Redis …\n- Khả năng giao tiếp tốt, hòa đồng, làm việc trong môi trường năng động và cường độ áp lực công việc cao.\n- Có khả năng tư duy logic, giải quyết vấn đề tốt.\n- Hiểu biết về ERP, Saas hoặc đã từng tham gia dự án ERP, Saas là điểm cộng.\n- Đam mê học hỏi và khả năng tự nghiên cứu công nghệ mới\n\nWhy you\'ll love working here\n- Mức Lương 10-20M, thỏa thuận theo năng lực.\n- Lộ trình phát triển bản thân rõ ràng, tham gia đào tạo chuyên môn để nâng cao năng lực.\n- Trải nghiệm dự án thách thức lớn.\n- Xét tăng lương 2 lần/ năm.\n- Thưởng định kỳ 2 lần/ năm, thưởng nóng và các phúc lợi hấp dẫn.\n- Tham gia các hoạt động vui chơi giải trí, du lịch, team building, ăn uống cùng  thành viên trong công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2, Tòa Nhà AC Building, 78 Duy Tân, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1023, 625, 2, 'Mobile Developer (React Native/Flutter)', 'Tại FinHub, chúng tôi đang tái định nghĩa cách mọi người đầu tư và quản lý tài sản. Chúng tôi xây dựng các sản phẩm tài chính thông minh như nền tảng đầu tư quỹ mở và cố vấn tài chính tự động (robo-advisors), với mục tiêu làm cho việc đầu tư trở nên dễ tiếp cận, thông minh và cá nhân hóa cho người dùng tại Việt Nam và Đông Nam Á.\n\nMô tả công việc\n- Thiết kế, phát triển và duy trì ứng dụng di động đa nền tảng (iOS & Android) bằng React Native, hoặc Flutter\n- Hợp tác chặt chẽ với đội ngũ sản phẩm, thiết kế và backend để cung cấp trải nghiệm người dùng mượt mà, bảo mật và hiệu quả.\n- Tham gia xây dựng kiến trúc ứng dụng có khả năng mở rộng, bảo mật cao trên hạ tầng AWS.\n- Tối ưu hiệu năng, UI/UX và trải nghiệm người dùng.\n- Viết mã sạch, có tài liệu và tham gia code review.\n- Tham gia quy trình phát triển Agile, cải tiến sản phẩm liên tục dựa trên phản hồi từ người dùng.\n\nYour skills and experience\n- Tối thiểu 5 năm kinh nghiệm phát triển phần mềm, trong đó có kinh nghiệm vững với React Native và/hoặc Flutter.\n- Có kinh nghiệm triển khai ứng dụng lên App Store và Google Play.\n- Hiểu rõ về kiến trúc ứng dụng di động, quản lý trạng thái, hiệu năng và các nguyên tắc bảo mật trong ứng dụng fintech.\n- Ưu tiên ứng viên có kinh nghiệm tích hợp API tài chính, dữ liệu đầu tư hoặc danh mục người dùng.\n- Kỹ năng phân tích, giải quyết vấn đề tốt và đam mê với đổi mới công nghệ tài chính.\n\nWhy you\'ll love working here\n- Trở thành thành viên chủ chốt trong hành trình xây dựng sản phẩm đầu tư tại Việt Nam.\n- Mức lương cạnh tranh, thưởng theo hiệu suất.\n- Môi trường làm việc linh hoạt: hybrid, full-time hoặc part-time.\n- Cơ hội phát triển cá nhân và đảm nhận vai trò lãnh đạo công nghệ.\n- Văn hóa năng động, sáng tạo và định hướng công nghệ.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'NIC Building, số 6 ngõ 7 Tôn Thất Thuyết, Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1024, 439, 2, 'Java Developer (Spring, OOP) Up to $2000', 'Top 3 reasons to join us\n- Attractive, competitive salary Up to $2000\n- Professional environment\n- Annual 5-star-company trip\n\nJob description\nMô hình hóa các khái niệm lõi của nghiệp vụ, xây dựng nền tảng và khung của lõi API, phát triển tính năng cho các dòng sản phẩm tài chính (cổ phiếu, trái phiếu, chứng chỉ quỹ) và các dòng tính năng công nghệ (on-boarding, customer service, OTP/soft-token,…)\n- Làm việc sát với team nghiệp vụ nhằm đưa ra giải pháp tối ưu mang lại giá trị cao nhất cho kinh doanh\n- Hiểu yêu cầu nghiệp vụ, có khả năng mô hình hóa yêu cầu với dữ liệu, quy trình, đối tượng, công thức,… để đưa vào thiết kế giải pháp\n- Khả năng tư duy và thiết kế hệ thống có khả năng mở rộng cao, đáp ứng yêu cầu tổng quát của nghiệp vụ\n- Phát triển nền tảng quản lý tài sản, bao gồm từ lõi API trên microservice đến luồn giao dịch của từng sản phẩm đầu tư trên các kênh khác nhau (iOS, Android, web)\n- Tích hợp với các hệ thống hỗ trợ khác như CRM, DWH, các hệ thống trao đổi thông tin, gửi nhận thông tin, hệ thống bảo mật, phân quyền, quản lý định danh…\n- Tìm hiểu các công nghệ mới nhất và lên chiến lược áp dụng cho hệ thống hiện tại\n\nGia nhập một trong 25 scrum team để xây dựng các sản phẩm công nghệ tài chính hàng đầu, như:\n- Core giao dịch chứng khoán\n- Core giao dịch phái sinh\n- Core giao dịch trái phiếu\n- Core giao dịch chứng chỉ quỹ\n- Hệ thống phân tích dữ liệu thời gian thực\n- Hệ thống lệnh điều kiện thời gian thực\n- Hệ thống thưởng điểm thông minh\n- Hệ thống quy trình doanh nghiệp\n\nYour skills and experience\n- Tốt nghiệp đại học chuyên ngành CNTT/Kỹ thuật hoặc tương đương (APTech, …)\n- Nắm vững khái niệm Object Oriented Programming (OOP) và nguyên tắc thiết kế theo OOP. Hiểu nguyên tắc thiết kế theo khung SOLID\n- Nắm vững các ngôn ngữ và framework: Core java, SpringMVC/SpringBoot, Reactive programming (Reactor, RxJava...)\n- Nắm vững kỹ năng và framework testing (Unit Test, Jmeter, JMC...), tư duy viết code có thể kiểm thử được (testable code)\n- Có kinh nghiệm với các DB và MQ: Oracle, MS SQL, RabbitMQ, Redis, PostgreSQL\n- Có kinh nghiệm và tư duy theo phương pháp Agile\n- Hiểu biết về các thư viện, framework trong cộng đồng: Apache,..  \n\nKỹ năng nên có:\n- Ưu tiên ứng viên có kinh nghiệm lập trình với các ngôn ngữ khác: Go/Python\n- Ưu tiên ứng viên có kinh nghiệm với Docker, Kubernetes, CI/CD, DevOps\n- Ưu tiên ứng viên đã làm việc với các framework quy trình: BPM  \n\nKỹ năng mềm:\n- Chủ động và nhiệt huyết trong công việc\n- Có kỹ năng tìm hiểu và giải quyết vấn đề\n- Coding có trách nhiệm, giữ code vệ sinh\n- Ưu tiên ham thích về tài chính\n\nWhy you\'ll love working here\n- Review lương 1 lần/ năm\n- Cán bộ nhân viên sẽ có từ 12- 15 ngày phép/ năm \n- Bảo hiểm AON cho Cán bộ nhân viên\n- Công ty có các CLB thể thao sinh hoạt hàng tuần (đá bóng, chạy bộ, cầu lông)\n- Team building 1 lần/ 1 năm theo tiêu chuẩn 5 sao\n- Môi trường làm việc trẻ, năng động, cơ hội phát triển cao ', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hội sở Techcombank, 6 Quang Trung, Trần Hưng Đạo, Hoan Kiem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1025, 299, 2, 'Java Technical Leader - Global Market', 'Top 3 reasons to join us\n- Attractive salary package + signin bonus\n- Professional working environment \n- Opportunity to become core manager\n\nJob description\n- Lead the design, development, and deployment of scalable Java-based applications and microservices. \n- Provide technical guidance, enforce coding standards, and mentor development team members. \n- Collaborate with cross-functional teams to ensure high-quality delivery aligned with business goals.\n\nYour skills and experience\n- Must have excellent communication \n- Fluent in English communication\n- Strong academic background or relevant work experience \n- Must have 1+ years track record of leading small engineering teams \n- Must have 6+ years of experience with Java & Advanced knowledge of Springboot framework \n- Must have 3+ years exposure to Docker, Kubernetes, Helm Charts, GitHub Actions \n- Good attitude and accountable\n\nWhy you\'ll love working here\n- Working time: 8.30 am – 5.30 pm from Monday to Friday.\n\nOPPORTUNITIES AND CHALLENGES:\n- Opportunity to work in a professional, modern and energizing setting.\n- Challenging projects, possibilities, cutting-edge technology, and problems.\n- An open and dynamic working atmosphere that promotes the interchange of ideas, while also empowering you to work and create in your own style. Each employee\'s talent and accomplishments are valued, and outstanding employees are recognized and rewarded on a yearly basis.\n- Opportunities for capacity development, as well as assistance with professional certification expenses, are available to those who work in the field (1 million - 5 million).\n- Some advanced certifications will cover the full cost of studying and taking the exam.\n\nATTRACTIVE REWARDING POLICY AND WORK-LIFE BALANCE:\n- Review salary 1-2 times/year, with the possibility of an unexpected salary rise based on capacity an infinite number of times per year\n- Policy for 13th-Month Salary Bonus and Holiday Bonuses According to Company Regulations.\n- Holiday travel mode (package 5-7 million/person), team building,...\n- Full participation in social insurance, as well as a yearly health checkup at a reputable hospital.\n- Comprehensive visit policy for personnel and relatives: birthday, marriage, childbirth, illness, etc.\n- The football club, cycling car, badminton, ... are just a few of the sports and cultural activities available.\n- Allowance for classes and training awards: Learning Star of the Month,\n- A chance to be the face of the year\'s study, the royalties...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 8, Tòa IDMC, Số 18 Tôn Thất Thuyết, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1026, 626, 2, 'Java Kotlin Dev (OOP, SQL, Spring, Git)', 'Job description\n- Develop new features or maintain existing features\n- Conduct testing to ensure the features are delivered with relatively few bugs/issues and within deadlines\n- Communicate with other teams for technical support when necessary\n- Ensure conformity of work to software quality standards\n- Comfortable in a Scrum team, using lean and Agile methodologies.\n\nYour skills and experience\n- 2+ years experience in Java/Kotlin Spring Boot\n- Strong knowledge of OOP and Design Patterns\n- Experience with SQL, database design, query optimization\n- Basic understanding of front-end technologies, such as JavaScript, HTML5, and CSS3\n- Proficient understanding of code versioning tools, such as Git\n\nBig bonus: (Nice to have)\n- Understanding accessibility and security compliance\n- Experience in NextJS is big plus\n- Experience in Microservice is big plus\n- Knowledge of AWS is an advantage\n- User authentication and authorization between multiple systems, servers, and environments\n\nWhy you\'ll love working here\n- Exciting Projects (MedTech, HRTech, Video Streaming, Drone, FinTech, FoodTech) with Great Team. Working with Agile Scrum model\n- Competitive Salary\n- Full salary insurance, premium health insurance & annual medical check\n- 12 days off allowance per year\n- Working time (40h/week)\n- Highly professional equipment (own laptop, adjustable desks, macbook pro...)\n- Team building, annual company trip & annual party\n- Allowances: Lunch, travel, birthday, wedding ', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '344 đường 2/9, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1027, 627, 2, 'Backend Developer (.NET/ C#/ Entity Framework)', 'Job description\n- Thiết kế tổng thể hệ thống, các module thành phần, các chức năng chi tiết.\n- Lập trình phát triển, bảo trì các chức năng hệ thống phía back-end.\n- Tối ưu các thành phần hệ thống phía back-end: code, database.\n- Triển khai và tích hợp các thành phần hệ thống phía back-end.\n\nYour skills and experience\n- Tốt nghiệp Đại học/cao đẳng chuyên ngành: công nghệ thông tin, khoa học máy tính, kỹ nghệ phần mềm (Software Engineer) hoặc tương đương.\n- Có kinh nghiệm lập trình .NET (C#), Entity Framework.\n- Có kinh nghiệm lập trình WinForms, WPF, ASP.NET, WEB API.\n- Có kinh nghiệm với các hệ quản trị CSDL như: SQL Server, MySQL.\n- Có kinh nghiệm sử dụng Git.\n- Có khả năng phân tích thiết kế hệ thống, áp dụng design pattern, microservice.\n- Có kinh nghiệm giải quyết các vấn đề về perfomance trên hệ thống cần xử lý lượng dữ liệu lớn.\n- Có kinh nghiệm làm về các sản phẩm quản lí bán hàng, MES, REALTIME.\n\nWhy you\'ll love working here\n- Thu nhập theo năng lực: Từ 10 - 18 triệu/ tháng.\n- Thưởng dự án.\n- Phụ cấp thuê nhà hàng tháng (nếu phải thuê nhà).\n- Chế độ thưởng hấp dẫn: Thưởng ngày lễ, Tết, sinh nhật, thưởng nóng, dự án,..; các chế độ đãi ngộ dành cho nhân viên và gia đình: quà lễ, Tết, các chế độ thăm hỏi sức khỏe theo quy định công ty.\n- Có nhiều cơ hội tham gia các khóa học phát triển năng lực và tư duy do DACO đầu tư 100%.\n- Làm việc cùng đội ngũ nhân sự ưu tú, thân thiện, hòa đồng, đa dạng lứa tuổi (2xxx-197x), có nhiều cơ hội thăng tiến và phát triển nghề nghiệp.\n- Được cung cấp đầy đủ trang thiết bị phục vụ cho công việc (laptop, sim số, điện thoại, email, đồng phục).\n- Có thể kết thúc thời gian thử việc sớm – dưới 2 tháng tùy năng lực.\n- Hỗ trợ khác: điện thoại, xăng xe, xe đưa đón công tác, công tác phí.\n- Công ty chuẩn bị bữa trưa cho nhân viên, đảm bảo dinh dưỡng và vệ sinh an toàn thực phẩm.\n- Được tham gia các hoạt động team building, du lịch lên đến 03 lần/năm.\n- Được tài trợ kiểm tra sức khỏe định kỳ hàng năm cho mọi nhân viên.\n- Thời gian làm việc: Thứ 2 - Sáng thứ 7. Từ 8h - 17h.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số nhà 146 (Đường Cầu Bươu) - Xã Tân Triều, Thanh Tri, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1028, 232, 2, '(Mid/Senior) Backend Developer (NodeJS, English)', 'The Backend Developer will be a key part of the Information Technology department that builds, supports, and scales the IT business applications or projects of Integrated Health Plans Malaysia and entities. This individual will ensure the systems are within quality and meeting the service performance expectation.\n\nWe are looking for many talents for all levels. \n\nResponsibilities\n- Involved in new systems development, enhancements and maintenance to existing applications to ensure alignment with business objectives\n- Responsible for programming, problem resolution and user support for one or more system applications\n- Plan, execute and monitor projects assigned to ensure deliverables are within scope, budget and schedule\n- Prepares technical and user documentation\n\nYour skills and experience\n- 2+ years of hands-on experience in JavaScript, Typescript software development \n- Good English skills\n- Good experience and understanding of Object-Oriented Programming (OOP), Algorithm & Structures\n- Good working experience developing backend for web and mobile applications and integrating enterprise systems\n- Good working experience with Typescript, NodeJS, RESTful APIs and related technologies\n- Good working experience with the No-SQL and RDBMS Databases (MongoDB & MySQL)\n- Good working experience with Source/Version Control tools such as Git\n- Demonstrable portfolio of projects in the technologies listed above \n- Process strong analytical skills\n- Team player with good interpersonal and communication skills\n\nWhy you\'ll love working here\n- A young and dynamic team where you can develop your career path and improve your English skills\n- An exciting project which uses cutting-edge technology\n- 14 days annual leave per year\n- 13th-month salary\n- Private insurance for employees. After 1 year, company will cover the insurance for family members (spouse, children)\n- Providing Laptop to work\n- Company trip \n- Annual health check \n- Monthly teambuilding activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1st Floor, L’Mak Plaza (Nam A Plaza), 127 Hong Ha, Ward 09, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1029, 507, 2, 'Senior Software Engineer, Fullstack (JavaScript,NodeJS)', 'About Grab and Our Workplace\nGrab is Southeast Asia\'s leading superapp. From getting your favourite meals delivered to helping you manage your finances and getting around town hassle-free, we\'ve got your back with everything. In Grab, purpose gives us joy and habits build excellence, while harnessing the power of Technology and AI to deliver the mission of driving Southeast Asia forward by economically empowering everyone, with heart, hunger, honour, and humility.\n\nJob Description\nGet to Know the Team\nThe Business Process Automation (BPA) team is a longstanding group within Grab Operations, dedicated to coding automation solutions across all countries and verticals. Their mission is to reduce manual work, enhance system connectivity, and develop bespoke scripts that drive organizational value. The team is composed of diverse professionals, including data analysts, full-stack engineers, problem solvers, and innovators.\n\nGet to Know the Role\nWe are seeking a talented and innovative Senior Software Engineer, Fullstack to join Automation Platform team. As a key member of our engineering department, you will be responsible for developing and maintaining high-performance, scalable, and user-friendly web applications. You will report to the Regional BPA - Automation Platform Manager and will work onsite at Grab office, CMC Creative Space, D7, HCMC.\n\nThe Critical Tasks You Will Perform\n- Design, develop and maintain microservices in Automation Platform\n- Write clean, efficient, and maintainable code for both front-end and back-end components\n- Work with product managers and designers to translate user needs into functional, scalable solutions\n- Optimize application performance and ensure user experiences\n- Implement security and data protection measures\n- Participate in code reviews and provide constructive feedback to team members\n- Stay up-to-date with emerging technologies and industry trends\n- Troubleshoot, debug, and upgrade existing systems\n- Develop and manage well-functioning databases and applications\n- Write technical documentation to guide future development and maintenance\n\nYour skills and experience\nWhat Essential Skills You Will Need\n- Bachelor\'s degree in Computer Science, Software Engineering, or a related field\n- Minimum of 4 years of professional software development experience\n- Knowledge of and experience working in front-end and back-end programming languages (Javascript, HTML, CSS, NodeJS, VueJS..).\n- Computer science fundamentals, including algorithms and data structures\n- Experience with Docker, Kubernetes, and CI/CD pipelines\n- Familiarity with database technologies (SQL and NoSQL)\n- Knowledge of web services and RESTful API design\n- Experience with version control systems, preferably Git\n- Experience with Agile development methodologies\n- Familiarity with cloud platforms (e.g., AWS, Google Cloud, or Azure)\n- Open-source project contributions are highly valued\n\nWhy you\'ll love working here\nLife at Grab\nWe care about your well-being at Grab, here are some of the global benefits we offer:\n- We have your back with Term Life Insurance and comprehensive Medical Insurance.\n- With GrabFlex, create a benefits package that suits your needs and aspirations.\n- Celebrate moments that matter in life with loved ones through Parental and Birthday leave, and give back to your communities through Love-all-Serve-all (LASA) volunteering leave.\n- We have a confidential Grabber Assistance Programme to guide and uplift you and your loved ones through life\'s challenges.\n\nWhat we stand for at Grab\nWe are committed to building an inclusive and equitable workplace that enables diverse Grabbers to grow and perform at their best. As an equal opportunity employer, we consider all candidates fairly and equally regardless of nationality, ethnicity, religion, age, gender identity, sexual orientation, family commitments, physical and mental impairments or disabilities, and other attributes that make them unique.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'CMC Creative Space, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1030, 459, 2, 'Middle/Senior MLOps Engineer - Generative AI', 'Infinity Technologies Global là công ty công nghệ được thành lập bởi các Founder nhiều kinh nghiệm, tập trung phát triển các sản phẩm công nghệ phục vụ hàng trăm triệu người dùng toàn cầu. Chúng tôi đang từng bước tạo ra hệ sinh thái toàn diện, đầy đủ với rất nhiều sản phẩm có hàm lượng công nghệ cao đáp ứng mọi nhu cầu người dùng.\n\nTầm nhìn và mục tiêu chiến lược tới 2026:\n- Hệ sinh thái đạt trên 1B+ người dùng toàn cầu.\n- Mở rộng các Business thành viên hoạt động trong lĩnh vực Mobile App, Software, Blockchain, Mobile game và Venture Capital.\n\nVăn hoá doanh nghiệp:\n- Thẳng thắn, minh bạch, công bằng\n- Tốc độ, chinh phục\n- Tập trung mục tiêu\n\nChúng tôi không tuyển nhân sự, chúng tôi TÌM KIẾM CỘNG SỰ cho mục tiêu chinh phục global.\n\nNếu bạn là người đam mê chinh phục, có tham vọng lớn và dám hành động để đạt được kết quả đột phá, chúng tôi là nơi tốt nhất dành cho bạn.\n\n1. Mô tả công việc\n- Xây dựng và tối ưu AI pipeline, tập trung vào Generative AI, đặc biệt là mô hình Stable Diffusion, từ thu thập dữ liệu, tiền xử lý, huấn luyện đến triển khai\n- Huấn luyện và fine-tuning mô hình Stable Diffusion sử dụng kỹ thuật LORA, quản lý checkpoint để tối ưu hiệu suất và chất lượng sinh ảnh\n- Thiết kế và tối ưu prompt để cải thiện chất lượng đầu ra của mô hình Generative AI\n- Phối hợp với đội ngũ Backend để tích hợp mô hình AI vào các sản phẩm thực tế (ví dụ: ứng dụng sinh ảnh hoặc video)\n- Đóng gói và triển khai mô hình trên môi trường sản xuất sử dụng Docker\n- Theo dõi các tiến bộ mới trong Generative AI để nâng cao hiệu quả mô hình\n\nYour skills and experience\n- Bắt buộc\n- Tối thiểu 1 năm kinh nghiệm ở vị trí AI Engineer, Research Engineer hoặc các vị trí tương đương liên quan tới công việc Generative AI\n- Thành thạo công cụ phổ biến: Automatic1111 (A1111) Web UI và ComfyUI và biết sử dụng các tính năng chính: txt2img, img2img, inpainting và outpainting\n- Có kinh nghiệm về các model: Stable Diffusion, Flux\n- Có kinh nghiệm sử dụng ControlNet để điều khiển chính xác bố cục, tư thế và các chi tiết cụ thể trong hình ảnh được tạo ra\n- Có thể train và fine-tuning LoRA để tạo ra các phong cách hoặc đối tượng tùy chỉnh\n- Biết sử dụng prompt cơ bản để kiểm soát chính xác các yếu tố: nội dung, phong cách nghệ thuật, bố cục, ánh sáng và dải màu. Negative prompts để loại bỏ các chi tiết không mong muốn và cải thiện chất lượng đầu ra\n- Có hiểu biết các thành phần cốt lõi: UNet, VAE (Variational Autoencoder), Text Encoder (ví dụ: CLIP), checkpoints\n- Có hiểu biết cơ bản về PyTorch, openCV, Docker\n- Kỹ năng phân tích và xử lý lỗi trong pipeline Generative AI, khả năng quản lý thời gian hiệu quả.\n\n- Ưu tiên:\n- Kinh nghiệm với các công cụ MLOps (MLflow hoặc DVC) để quản lý pipeline Generative AI\n- Kinh nghiệm tối ưu model, pipeline, vận hành hệ thống phục vụ nhiều người dùng cùng lúc\n- Kinh nghiệm làm việc với các công cụ giám sát như Prometheus, Grafana\n- Hiểu biết về Kubernetes hoặc CI/CD cho mô hình AI\n\nWhy you\'ll love working here\n- Mức lương: 20.000.000 - 40.000.000 VNĐ\n- Review lương, thưởng 2 lần/ năm (Tháng 1 và tháng 7), mức lương tăng upto 25%/ đợt review, thưởng 1-4 tháng lương/năm\n- Thưởng ngày lễ, sinh nhật cho CBNV\n- Trang bị các thiết bị làm việc phù hợp với công việc \n- Hỗ trợ tham gia các khóa đào tạo và hội thảo liên quan tới AI\n- Cơ hội học hỏi từ đội ngũ chuyên gia về Stable Diffusion và Generative AI\n- Có khu vực ăn uống riêng, khu căng tin hoàn toàn miễn phí\n- Chương trình Khám sức khỏe định kỳ hằng năm\n- Chương trình Happy Time vào chiều thứ 6 hàng tuần\n- Ngày nghỉ phép còn lại trong năm sẽ được chuyển sang ngày lương\n- Môi trường làm việc chuyên nghiệp, lành mạnh, cơ hội thăng tiến cao \n- Các chương trình, hoạt động vui chơi giải trí vào các dịp lễ, Tết, du lịch, team building.\n- Hệ sinh thái các sản phẩm có hàng triệu người dùng hàng tháng trên toàn cầu: Âu, Úc, Mỹ, Ấn Độ, Brazil, South Africa...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2, tòa nhà Đồng Lợi, ngõ 1160 đường Láng, Láng Thượng, Đống Đa, Hà Nội, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1031, 414, 2, 'Senior Odoo ERP Consultant (BA/Consultant)', 'Top 3 reasons to join us\n- Utilization Bonus , 13th salary\n- Weekly English training with foreign.\n- Healthcare insurance (PTI) for you and your family\n\nJob description\n- If you enjoy analyzing complex business challenges and translating them into ERP solutions\n- If you\'re passionate about optimizing systems and leading end-to-end digital transformation projects\n- If you want to work directly with US clients and gain hands-on experience in ERP consulting\n- If you\'re skilled at balancing technical execution with client engagement and leadership\n- If you have strong English communication and project management skills\n\nWhat will you do?\n- Conduct an in-depth analysis of business processes and translate them into system requirements.\n- Lead small-scale ERP implementation projects (small size projects), managing full cycles from discovery to deployment.\n- Create detailed project documentation including functional specs, process flows, and data mappings.\n- Provide expert recommendations on ERP best practices and business process optimization.\n- Support system configuration, testing, and user training to ensure smooth implementation.\n- Assist with data migration, integration, and validation throughout project phases.\n- Coordinate project plans, monitor progress, manage risks, and report status to stakeholders.\n- Lead client workshops and deliver post-go-live support.\n- Mentor junior consultants and foster a collaborative consulting team culture.\n\nWhat skills will you gain?\n- ERP & Business Process Consulting\n - Conducting business analysis across various industries (finance, manufacturing, supply chain, retail).\n - Designing scalable ERP workflows and configurations that align with client objectives.\n - Supporting testing, migration, and deployment for real ERP implementation projects.\n\n- Project Management & Leadership\n - Leading multiple small-scale ERP projects with ownership of timeline, budget, and quality.\n - Applying change management strategies and managing stakeholder expectations.\n - Practicing hands-on leadership while coordinating internal and external resources.\n\n- Client Communication in English\n - Engaging directly with US clients in an English-speaking environment.\n - Leading presentations, demos, and training sessions.\n - Handling post-implementation feedback and support with professionalism.\n\n- Mentorship & Internal Collaboration\n - Supporting junior team members with guidance and knowledge transfer.\n - Enhancing internal processes through knowledge-sharing and experience-based improvements.\n\nYour skills and experience\n- Bachelor\'s degree in Computer Science, Information Technology, Business Administration, or a related field.\n- Good knowledge of leading ERP systems (e.g., SAP, Oracle, Microsoft Dynamics, NetSuite or Odoo) and related technologies.\n- Good project management skills, with the ability to manage multiple projects simultaneously.\n- Excellent communication, presentation, and interpersonal skills in English.\n- Ability to work independently and collaboratively in a fast-paced, client-focused environment.\n- Excellent analytical skills with a keen attention to detail and the ability to solve complex problems independently.\n- Willingness to work at night to communicate with clients in the US several days a week.\n\nPREFERRED QUALIFICATIONS\n- Prior experience in ERP consulting, with a proven track record of successful project delivery is preferred.\n- Good understanding of business processes across various industries, including finance, supply chain, manufacturing, retail and field services is preferred.\n- Experience with ERP implementation is a plus, ideally with the most prominent and widely used in the industry, such as Odoo (preferred).\n\nWhy you\'ll love working here\n- Very competitive salary commensurate with experience.\n- Comprehensive benefits package including:\n - Private healthcare insurance (PTI) for you and your family\n - Social insurance with full salary\n- Technical and soft skills training and professional certifications supported (e.g. weekly English classes).\n- Flexible working time (9:30 AM to 6:00 PM, Monday to Friday).\n- Annual leave & work from home up to 54 days/years + 1 more day after every 2-year.\n- Opportunities for professional development and career advancement.\n- Other employee benefits: sickness, birthday, International Women’s Day (March 8th), Vietnam Women’s Day (October 20th), Children\'s Day (June 1st), and family emergencies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'HAGL Building, 6th & 7th Floor, 3/1 Thanh Thai, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1032, 628, 2, 'Full Stack Developer (Python, AWS, DevOps, Neoj4)', '1. Design & Development\n- Develop clean, efficient and maintainable code for backend services and occasionally frontend components\n- Write and maintain unit, component, and integration tests to ensure software reliability and functionality\n- Participate in code reviews to maintain quality standards and share knowledge across the team\n\n2. Collaboration & Teamwork\n- Collaborate with developers, designers, and stakeholders to deliver well-integrated features\n- Support your team in decision-making processes and contribute to effective work organization\n\n3. Documentation & Requirements\n- Create and maintain clear technical documentation and specifications\n- Help manage and clarify requirements for the software components you work on\n\n4. Performance & Improvement\n- Optimize the interaction between backend and frontend for performance, scalability, and security\n- Actively contribute to the continuous improvement of our systems and development practices\n\nYour skills and experience\n- Strong backend development skills with Python and experience with AWS services such as SQS, S3, Lambda / ECS\n- Experience working with graph databases, ideally Neo4j\n- Familiarity with the Serverless Framework and a basic understanding of DevOps practices, including CI/CD\n- Comfortable working with frontend code; experience with React is helpful, Angular is our future direction. Familiarity with AWS Amplify is a plus.\n- A structured, solution-oriented working style with the ability to work independently and collaboratively\n\nWhy you\'ll love working here\n- Our fixed base salary is paid within 13 salaries and as extra, you have a 3% variable that is based on company performance\n- Private health insurance (incl. up to 2 family members)\n- Full coverage of social insurance (incl. probation period)\n- Free lunch while working in the office\n- Vacation: 15 days a year\n- Flexible hybrid work policy\n- Great team events\n- Gifts for holidays', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6Fl, DC Tower, 111D Ly Chinh Thang Street, Vo Thi Sau ward, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1033, 319, 2, 'Frontend Developer (Da Nang, HCMC)', 'Top 3 reasons to join us\n- Attractive package\n- Hybrid working policy & flexible hours\n- Europe onsite opportunities\n\nJob description\n- Work with international customers and colleagues from Germany, France, the Czech Republic, and the US\n- Conception and implementation of new functions in complex application landscapes\n- Development and design of new web interfaces and optimization of their usability and performance\n- JavaScript frontend development in different architectures (including serverside/clientside/single-page). Evaluation and introduction of innovative frontend technologies\n- Development of various frontends for desktop, tablet, and mobile devices, dashboard applications, data visualization, and prototype development in close cooperation with our UI/UX team.\n\nThis job is open to both Vietnamese citizens and foreigners living in Vietnam.\nPlease send us your application in English.\n\nYour skills and experience\n- General qualifications\n  - Strong English communication skills (both verbal & written)\n  - 2+ years of professional experience in international software projects (flexible depending on how fast your learning and technical developing capabilities are)\n  - Degree in engineering or natural sciences (university or technical college)\n\n- Technical skills\n  - Must have\n    - Understanding of software development tools, processes, and architecture\n    - In-depth understanding of in HTML/CSS, JavaScript\n    - Experience with frontend frameworks such as ReactJS, Angular, VueJS...\n  - Nice to have\n    - Professional experience in the implementation of complex JavaScript applications\n    - Professional experience in ReactJS and its ecosystem\n    - Experience with TypeScript, Webpack, Redux\n    - Experience with unit testing frameworks (Mocha, Jest, Enzyme...)\n    - Experience in agile software development\n    - Proficient understanding of code versioning tools (Git is preferred)\n\n- Soft skills\n  - Sense of responsibility, communication skills, and team spirit\n  - Willingness to learn and build a deep understanding\n  - Be able to work independently and under pressure\n  - A passion for software development, new trends, and technologies in IT.\n\nWhy you\'ll love working here\n- Good salary and a bonus if things work well\n- Working & growing with an international team\n- Onsite opportunities: short-term and long-term assignments in Europe\n- 18 days off allowance per year\n- Premium insurance for you and your family member (spouse/parent/child) & yearly check-up\n- Loyalty program after three years and five years\n- Flexible working time (40h/week) and hybrid working policy\n- Highly professional equipment (Mac/Thinkpad, 2 screens, adjustable desks)\n- Intense English course for the first 3 months by our native English teachers and optional English seminars during the work time\n- Training sponsored by mgm\n- An amazing company trip once a year, team-building with the project team, and month-end with the whole company, covered by mgm\n- Free in-house drinks (coffee, beer, soft drinks,…) and food (cookies, fruit, …) and out-house company-funded sport clubs (football, swimming, badminton, …)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '195A Hai Bà Trưng, Võ Thị Sáu Ward, District 3, Ho Chi Minh, 7 Phan Chau Trinh, Hải Châu 1, Hai Chau, Da Nang, 71 Quang Trung, Hải Châu 1, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1034, 629, 2, 'Server Engineer (Linux/ Virtuozzo/ Acronis/ WHM)', 'Ứng viên có kinh nghiệm thực hiện: Linux; OpenVZ/Virtuozzo; KVM; cPanel bind; Exim/Postfix; Fortigate; Customer support\n\nTriển khai các giải pháp Monitor hệ thống (Supermicro)\nCài đặt, cấu hình, tích hợp, Server, Fortigate\nCài đặt, cấu hình, tích hợp hệ điều hành Linux (Redhat, AlmaLinux, Debian và ứng dụng trên hệ thống máy chủ theo yêu cầu từng dự án.\nCài đặt, cấu hình, tích hợp về ảo hóa (OpenVZ/Virtuozzo, Proxmox)\nCài đặt, cấu hình, tích hợp về backup: (Acronis)\nCác phần mềm /giải pháp khác theo dự án.\n\nThực hiện dịch vụ kỹ thuật:\nHỗ trợ kỹ thuật từ xa/tại chỗ khi có yêu cầu nhằm đảm bảo hệ thống khách hàng hoạt động 24/7.\nHướng dẫn sử dụng/đào tạo chuyển giao công nghệ cho khách hàng.\nGia hạn các dịch vụ sắp hết hạn (tên miền, SSL, máy chủ chia sẻ…)\nSửa chữa, thay thế linh kiện, kiểm tra trạm máy chủ ở các IDC khi có yêu cầu.\nCác công việc khác theo yêu cầu của Trưởng Bộ phận.\n\nTốt nghiệp ĐH/CĐ chuyên ngành CNTT, Điện tử viễn thông hoặc tương đương.\nCó kiến thức về Hệ điều hành Linux.\nƯu tiên ứng viên có kinh nghiệm về các SP giải pháp, sao lưu, ảo hóa, server, storage.\nTư duy phân tích và giải quyết vấn đề tốt, ưu tiên có tư duy hệ thống tốt.\nCó khả năng làm việc độc lập dưới áp lực cao.\nCó khả năng nghiên cứu và viết tài liệu đào tạo kỹ thuật.\nNgoại ngữ: giao tiếp cơ bản, đọc hiểu được tài liệu chuyên ngành, email. Ưu tiên ứng viên đã có các chứng chỉ tương đương TOIEC 500.\n\nLương gross: 20.000.000~25.000.000/tháng (thương lượng).\nĐược hưởng đầy đủ các chế độ theo quy định của pháp luật (BHYT, BHXH, BHTN).\nReview lương hàng năm.\nLương tháng 13.\nCác chế độ phúc lợi theo nội quy, quy chế của Công ty (tham quan, nghỉ mát, lương thưởng, nghỉ Tết lễ,…). Thưởng vào các ngày lễ lớn trong năm.\nKhám sức khỏe hàng năm.\nThẻ Bảo hiểm sức khỏe hàng năm.\nĐược làm việc trong môi trường chuyên nghiệp, thân thiện.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '85 Dien Bien Phu, Da Kao Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1035, 401, 2, 'Senior UI/UX Designer (Edtech)', 'Top 3 reasons to join us\n1. Môi trường tốt, cơ hội học hỏi và thăng tiến\n2. Sản phẩm chất lượng\n3. Lương top market, thưởng cao\n\nJob description\n- Phối hợp chặt chẽ với Product Owner, Developer và các bên liên quan để nhận yêu cầu và tạo ra giải pháp thiết kế phù hợp với nhu cầu sản phẩm.\n- Thiết kế UI chỉn chu, đẹp mắt, đảm bảo tuân thủ đúng design system và tạo trải nghiệm nhất quán trên toàn bộ nền tảng.\n- Thiết kế UX chuẩn chỉnh, tối ưu hóa hành trình người dùng (user journey) và đảm bảo trải nghiệm mượt mà, trực quan.\n- Xây dựng file thiết kế đầy đủ tất cả scenario, đảm bảo đúng logic, đúng data trước khi bàn giao cho team phát triển.\n- Theo dõi phản hồi từ người dùng, phân tích hành vi để cải tiến và tối ưu hóa sản phẩm liên tục.\n- Chủ động tham gia vào quá trình góp ý, đề xuất cải tiến sản phẩm cùng toàn bộ team.\n\nYour skills and experience\n- Thành thạo Figma và các công cụ thiết kế UI/UX khác (Adobe XD, Sketch, InVision…).\n- Ít nhất 5 năm kinh nghiệm trong thiết kế UI/UX với portfolio mạnh thể hiện năng lực và tư duy thiết kế.\n- Kỹ năng thiết kế UI đẹp, đồng nhất, đảm bảo sự chuyên nghiệp và tinh tế trong từng chi tiết.\n- Tư duy logic tốt, có khả năng phân tích luồng dữ liệu và tối ưu hóa trải nghiệm người dùng.\n- Tính kỷ luật, chăm chỉ, có trách nhiệm cao trong công việc, luôn đảm bảo tiến độ và chất lượng thiết kế.\n- Khả năng nghiên cứu, sáng tạo giải pháp để liên tục cải tiến và nâng cao trải nghiệm sản phẩm.\n\nWhy you\'ll love working here\n- Lương từ 40 triệu đồng/tháng (thương lượng theo năng lực) + thưởng theo hiệu suất.\n- Chế độ bảo hiểm, nghỉ phép, phúc lợi đầy đủ theo quy định.\n- Cơ hội đào tạo, phát triển kỹ năng chuyên môn, tham gia vào các dự án có tác động lớn.\n- Môi trường sáng tạo, năng động, đề cao sự đổi mới và tinh thần làm chủ công việc.\n- Làm việc trong đội ngũ có chuyên môn cao, học hỏi không ngừng và phát triển nghề nghiệp bền vững.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '458/14 Ba Thang Hai Street, Ward 12, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1036, 533, 2, 'Middle/Senior Fullstack Engineer', 'GIỚI THIỆU CHUNG:\n\nVinBigdata\nCông ty cổ phần VinBigdata được thành lập theo định hướng trở thành tập đoàn Công nghệ – Công nghiệp – Thương mại Dịch vụ hàng đầu Việt Nam của Vingroup. Với lợi thế đặc biệt về hạ tầng dữ liệu lớn, VinBigdata cung cấp các sản phẩm, giải pháp ứng dụng trí tuệ nhân tạo, giúp doanh nghiệp đẩy nhanh quá trình chuyển đổi số, tối ưu hiệu quả vận hành, kinh doanh và gia tăng trải nghiệm người dùng cuối. Là một công ty trẻ trung và đang trong giai đoạn phát triển nhanh chóng, VinBigdata luôn chào đón những tài năng gia nhập công ty để cùng thực hiện mục tiêu “Công nghệ Việt – Vì tương lai Việt”.\n\nVề phòng ban chuyên môn:\nKhối Công nghệ trợ lý ảo nghiên cứu và ứng dụng các bài toán trí tuệ nhân tạo trong xử lý tiếng nói và xử lý ngôn ngữ tự nhiên để xây dựng nên các giải pháp Trợ lý ảo cho người dùng cá nhân và doanh nghiệp. Hai sản phẩm tiêu biểu của Khối là Vivi – trợ lý ảo toàn diện cho người Việt đã và đang hoạt động trên toàn bộ các sản phẩm xe điện của VinFast; và Vinbase – nền tảng trợ lý ảo đa nhận thức toàn diện, là nền tảng giúp phát triển Vivi và các trợ lý ảo khác hoạt động trên các hệ thống trả lời và nhắn tin tự động thông minh.\nPhòng phát triển nền tảng gồm các kỹ sư trẻ tài năng cung cấp nguồn động lực và năng lượng mạnh mẽ cho việc phát triển Vivi và các sản phẩm trong hệ sinh thái Vinbase.\n\nMỤC ĐÍCH CỦA VỊ TRÍ NÀY:\n- Tham gia thiết kế, xây dựng và bàn giao các dự án phát triển Trợ lý ảo triển khai trên nền tảng Vinbase.\n- Phát triển kiến trúc tích hợp Vinbase và các nền tảng khác.\n\nTRÁCH NHIỆM:\n- Thiết kế giải pháp và triển khai các hệ thống, sản phẩm AI, Machine learning có khả năng co giãn, luôn luôn sẵn sàng và có khả năng chịu lỗi.\n- Phát triển sản phẩm phần mềm có khả năng tích hợp hiệu quả và an toàn đến các nền tảng và đối tác bên thứ 3.\n- Tham gia và tuân thủ các quy trình phát triển phần mềm linh hoạt, thực hành DevOps, CICD để phát triển và triển khai phần mềm với tốc độ cao nhất.\n- Phát triển sản phẩm với UIUX có tính đồng bộ về mặt trải nghiệm và dễ sử dụng.\n- Các công việc khác theo phân công của cấp trên.\n\nYour skills and experience\nYÊU CẦU:\nHọc vấn:\n- Tốt nghiệp các trường Đại học chuyên ngành: Công nghệ thông tin, Khoa học máy tính hoặc tương đương.\nKinh nghiệm:\n- Trên 3 năm kinh nghiệm làm việc trong lĩnh vực phát triển phần mềm.\n- Có kinh nghiệm thiết kế và phát triển các hệ thống back-end với kiến trúc Microservice sử dụng Python/Golang/NodeJS.\n- Có kinh nghiệm phát triển front-end sử dụng một trong các công nghệ sau: react, vue.\n- Có hiểu biết về giải thuật, design pattern.\n- Có hiểu biết về các phương pháp giao tiếp, xác thực giữa client – server và server – server: HTTP, GRPC, WebSocket, Message Queue…\n\nKỹ năng:\n- Kỹ năng mềm: Tư duy giải quyết vấn đề, Khả năng làm việc nhóm, Khả năng truyền đạt giao tiếp.\n- Kỹ năng chuyên môn: Thiết kế hệ thống, Thiết kế hướng đối tượng, Thiết kế CSDL, Javascript.\n- Kỹ năng máy tính: Sử dụng Linux, Windows, MacOS, Word, Excel.\n- Ngoại ngữ: Tiếng Anh khá.\n\nĐiểm cộng/Ưu tiên:\n- Có kinh nghiệm làm việc với các nền tảng cloud như AWS, Azure hay GCP.\n- Có kinh nghiệm tham gia dự án triển khai theo Agile Scrum/Kanban.\n\nWhy you\'ll love working here\nPhúc lợi:\n- Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của Luật Lao động (BHXH, BHYT, BHTN) và được Công ty mua Bảo hiểm sức khỏe cá nhân theo cấp bậc vị trí, khám sức khỏe định kỳ tại Bệnh viện và Trung tâm khám sức khỏe uy tín trên toàn quốc.\n- Được hưởng chế độ ưu đãi khi sử dụng các dịch vụ như: Ưu đãi học phí (Vinschool), khám chữa bệnh (Vinmec), nghỉ dưỡng (Vinpearl), mua xe (VinFast), … theo chế độ của Tập đoàn.\n- 12 ngày nghỉ phép năm, nghỉ các ngày lễ, Tết theo quy định của pháp luật.\n- Được cấp máy tính xách tay, trang thiết bị làm việc khác phù hợp với yêu cầu công việc\n- Phụ cấp ăn trưa hàng tháng.\n- Canteen rộng rãi, trang bị đầy đủ các thiết bị cần thiết như máy pha cà phê, tủ lạnh, lò vi sóng, các loại trà và cà phê hạt được bổ sung hàng ngày.\n- Chương trình chăm sóc sức khỏe tinh thần cho CBNV.\n- Tham gia các hoạt động nội bộ, hoạt động teambuilding, du lịch hàng năm của công ty.\n\nCơ hội phát triển:\n- Cơ hội làm việc trong môi trường chuyên nghiệp, công nghệ dẫn đầu về AI, quy tụ hơn 100 nhà khoa học, chuyên gia, kỹ sư đến từ các trường đại học hàng đầu thế giới và Việt Nam như: ĐH Yale (Mỹ), ĐH Johns Hopkins (Mỹ), ĐH Illinois (Mỹ), ĐH Toulouse (Pháp), ĐH Cambridge (Anh Quốc), Đại học Bách Khoa, Đại học Công nghệ – Đại học Quốc gia, …\n- Được xây dựng kế hoạch phát triển cá nhân.\n- Được tài trợ các khóa học miễn phí trên Coursera, tham gia các khóa học chuyên môn, kỹ năng mềm, quản lý,… phù hợp với yêu cầu công việc và nhu cầu phát triển của mỗi cá nhân.\n- Được hỗ trợ một phần chi phí thi các chứng chỉ chuyên môn phục vụ công việc.\n\nMôi trường làm việc:\n- Văn phòng hiện đại, tiện nghi, trẻ trung và chuyên nghiệp.\n- Tham gia không giới hạn các câu lạc bộ: cộng đồng đọc sách, CLB cầu lông, bóng bàn, bóng đá (công ty hỗ trợ một phần chi phí cho các hoạt động của CLB).\n- Môi trường làm việc cởi mở, khuyến khích CBNV đóng góp ý kiến, sáng kiến, ý tưởng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Century Tower, T14, Khu đô thị Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1037, 416, 2, 'Frontend Engineer', 'Top 3 reasons to join us\n- Attractive Compensation Package\n- Premium Healthcare for You and Relatives\n- Hybrid Work Mode\n\nJob description\nAbout LINE VIETNAM\nOur products are focusing on online media business industry. Our mission is to bring people, information and services closer together by making use of AI Technology.\nWe also have many interesting projects specified for AI and Block-chains. You will have a great chance to:\nWorking in a very Silicon Valley start-up style with a professional, international environment. Developing your career in a famous product company and working with latest technologies in the world.\n\nYour skills and experience\nResponsibilities \n- Implement frontend for web applications with modern technologies\n- Hands-on experience with React and Next.js \n- Improve the efficiency of existing products  \n- Build the architecture and design of new products and features  \n- Research new technologies to apply in the current and future projects  \n- Implement UI components and libraries  \nQualifications \n- At least 5 years of experience in Javascript  \n- Proficiency in TypeScript, JavaScript, HTML, and CSS, with a strong interest in how things work under the hood \n- Passionate about development, building highly functional, great eyes on details, always look for UX improvement to deliver an outstanding user experience \n- Familiarity with source control (git/git-flow) and code review \n- Experience in SPA development based on MV* \n- Understanding of server, database and good experience in RESTful API design and development \n- Experience working in a monorepo environment using tools like Lerna or Nx is plus \n- Familiarity with end-to-end testing tools such as Playwright or Cypress is plus \n- Experience with CI/CD pipelines, especially using GitHub Actions \n- High ownership, self-sufficient and continuous effort to find solutions for doing repeated tasks, easily adapt and learn new things \n- Experience building multilingual and globally distributed web services \n- English speaking is must\n\nKindly be informed that by submitting your resume to this opportunity, you would agree to allow LINE Vietnam Co. Ltd. to store your personal information and document for recruitment purpose.\nYou can also request to delete your personal information by sending an email to us, at dl_devcareer\n\nWhy you\'ll love working here\n- Dynamic, Innovative and Friendly Working Environment.\n- Top Attractive compensation.\n- Working with top professional experts with latest and challenging technologies for Line app and Line eco-system', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viettel Building, 285 Cach Mang Thang Tam Street, Ward 12, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1038, 630, 2, 'Junior IT Support (ERP, Python/PHP, SQL)', 'Top 3 reasons to join us\n- Cơ hội đào tạo nâng cao chuyên môn và kỹ thuật.\n- Môi trường làm việc hiện đại thân thiện năng động.\n- Hoạt động team building, nghỉ mát và sự kiện.\n\nJob description\n- Số lượng: 1\n- Lương: 9-10tr\n- Truy vấn, quản trị, bảo trì cơ sở dữ liệu ERP theo yêu cầu.\n- Đảm bảo, duy trì hệ thống công nghệ thông tin khối văn phòng và cửa hàng.\n- Xác định, chẩn đoán và hỗ trợ người dùng các sự cố về máy tính.\n- Cấu hình modem, hệ thống wifi, switch, các thiết bị mạng, máy in.\n- Làm việc với các nhà cung cấp về vấn đề bảo hành, bảo trì các thiết bị công nghệ thông tin.\n- Phối hợp với các phòng ban khác khi có yêu cầu.\n\nYour skills and experience\n- Tốt nghiệp Cao đẳng trở lên chuyên ngành Công nghệ thông tin.\n- Có ít nhất 1 năm kinh nghiệm ở vị trí tương đương.\n- Nắm vững về hệ thống phần cứng máy vi tính, hệ thống mạng.\n- Kỹ năng làm việc nhóm tốt.\n\nWhy you\'ll love working here\n- BHXH theo Luật lao động quy định.\n- Cơ hội huấn luyện, đào tạo chuyên môn nâng cao nghiệp vụ và kỹ thuật.\n- Đồng nghiệp, môi trường làm việc hiện đại, năng động, thân thiện và cởi mở.\n- Các hoạt động như team-building gắn kết thành viên, nghỉ mát hàng năm và sự kiện nội bộ tại công ty…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '37 Tran Quoc Hoan, Ward 4, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1039, 209, 2, 'Senior Embedded Software Engineer - Salary up to $3000', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nJOB OVERVIEW\nFA.CDC is collaborating with global automotive OEM and Tier 1 on developing head units and MCU for global markets. You will be involved in various activities for Automotive market such as Researching and Developing Software Defined Vehicles with cutting-edge solutions for both Application and Framework/APIs development on a robust and reusable embedded environment. Moreover, it will be a precious chance to work with top experts of automotive industry to enhance both your technical knowledge and English.\n\nRESPONSIBILITIES\nWe are looking for talent engineers joining our team in:\n- Bring up device\n- Flashing device\n- Modify device driver\n- Modify bootloader\n- Measure, optimize overall performance (Boot process, CPU, RAM, Disk, …)\n- Control Android build system\n\nYour skills and experience\n- Graduated from a university specialized in Electronics Engineering, Automatic Control, Automation, Computer Science, or related fields.\n- At least 3-5 years of experience working with Android platform/Linux kernel\n- Have participated in successful projects related to embedded software\n- Demonstrated proficiency in C programming language\n- Deep understanding about Android partition, Android boot process, Android Security model, Android GKI\n- Deep understanding about AOSP build system\n- Demonstrated proficiency in Kernel Driver development (Interrupt, Spinlock, multi-threading, …), Bootloader development, Device tree.\n- Familiarity with Schematics, Datasheet\n- Proficiency in using tools and software related to embedded software design\n- Familiarity with using Multi Metter, Oscilloscopes, …\n- Effective use of Git, Gerrit code review, CI/CD tools (Jenkin, QuickBuild, …)\n- English: TOEIC 600+\n- Soft skill: Strong Organizational, Analytical, Problem solving, Proactive, Teamwork, Independent work\n- Have one/more of following skills/experience is an advantage:\n- Holding specialized certifications, degrees, or relevant training courses.\n- Experience in device bring up of In-Vehicle Information system (Audio, BT, Wifi, Camera, Sensors, …)\n- Familiarity with Android boot processes (e.g. U-Boot) and bring-up experience\n- Broad knowledge of Qualcomm, NXP, Renesas, …\n- Experience in improvement Boot KPI, optimize resources (Disk, RAM,…)\n\nWhy you\'ll love working here\n- FPT Care insurance plan tailored for FPT employees\n- Attractive annual summer vacation allowance\n- Sponsored training courses for personal growth and up to 100% coverage for certification costs\n- Global and inclusive workplace with monthly cross-cultural events\n- International exposure and career growth across global locations\n- Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Building, 17 Duy Tân Str., Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1040, 533, 2, 'Middle/Senior Backend Engineer', 'GIỚI THIỆU CHUNG:\n\nVinBigdata\nCông ty cổ phần VinBigdata được thành lập theo định hướng trở thành tập đoàn Công nghệ – Công nghiệp – Thương mại Dịch vụ hàng đầu Việt Nam của Vingroup. Với lợi thế đặc biệt về hạ tầng dữ liệu lớn, VinBigdata cung cấp các sản phẩm, giải pháp tiên ứng dụng trí tuệ nhân tạo, giúp doanh nghiệp đẩy nhanh quá trình chuyển đổi số, tối ưu hiệu quả vận hành, kinh doanh và gia tăng trải nghiệm người dùng cuối.\nLà một công ty trẻ trung và đang trong giai đoạn phát triển nhanh chóng, VinBigdata luôn chào đón những tài năng gia nhập công ty để cùng thực hiện mục tiêu “Công nghệ Việt – Vì tương lai Việt”.\nChúng tôi đề cao và tìm kiếm các nhân sự có tinh thần sáng tạo, đam mê tạo ra những sản phẩm và dịch vụ mới giúp người Việt Nam có cuộc sống tiện lợi, văn minh và lành mạnh hơn, sẵn sàng thử thách bản thân, học hỏi và chịu được áp lực lớn trong công việc.\n\nVề phòng ban chuyên môn:\nKhối Công nghệ trợ lý ảo nghiên cứu và ứng dụng các bài toán trí tuệ nhân tạo trong xử lý tiếng nói và xử lý ngôn ngữ tự nhiên để xây dựng nên các giải pháp Trợ lý ảo cho người dùng cá nhân và doanh nghiệp. Hai sản phẩm tiêu biểu của Khối là Vivi – trợ lý ảo toàn diện cho người Việt đã và đang hoạt động trên toàn bộ các sản phẩm xe điện của VinFast; và Vinbase – nền tảng trợ lý ảo đa nhận thức toàn diện, là nền tảng giúp phát triển Vivi và các trợ lý ảo khác hoạt động trên các hệ thống trả lời và nhắn tin tự động thông minh.\n\nMỤC ĐÍCH CỦA VỊ TRÍ NÀY:\n- Tham gia thiết kế, xây dựng và triển khai các hệ thống back-end cho nền tảng Vinbase\n- Tham gia thiết kế, xây dựng và bàn giao các dự án phát triển Trợ lý ảo triển khai trên nền tảng Vinbase\n\nTRÁCH NHIỆM:\n- Thiết kế giải pháp và triển khai các hệ thống, sản phẩm AI, Machine learning có khả năng co giãn, luôn luôn sẵn sàng và có khả năng chịu lỗi.\n- Phát triển sản phẩm phần mềm có khả năng tích hợp hiệu quả và an toàn đến các nền tảng và đối tác bên thứ 3.\n- Tham gia và tuân thủ các quy trình phát triển phần mềm linh hoạt, thực hành DevOps, CICD để phát triển và triển khai phần mềm với tốc độ cao nhất.\n- Hướng dẫn các thành viên ít kinh nghiệm hơn, chủ động đóng góp và thực hiện các ý tưởng để cải thiện chất lượng sản phẩm, hiệu suất làm việc của nhóm và môi trường làm việc trong công ty.\n- Các công việc khác theo phân công của cấp trên.\n\nYour skills and experience\n- Học vấn:\n  + Tốt nghiệp Đại học trở lên trong chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc tương đương\n  + Xếp loại bằng từ Khá trở lên\n- Kinh nghiệm:\n  + Trên 2 năm làm việc trong lĩnh vực phát triển phần mềm\n  + Trên 1 năm kinh nghiệm thiết kế và phát triển các hệ thống back-end sử dụng kiến trúc Microservice sử dụng Python/Golang\n  + Có kinh nghiệm làm việc với các loại cơ sở dữ liệu quan hệ và NoSQL\n  + Có kinh nghiệm viết kiểm thử tự động, có kinh nghiệm sử dụng Jenkins, CICD, Docker, Kubenetes, có kinh nghiệm sử dụng các phương pháp caching, queue, pubsub\n  + Nắm được kiến thức cơ bản về cấu trúc dữ liệu, thiết kế hướng đối tượng, design pattern\n  + Có kinh nghiệm làm việc sâu về hệ thống, dữ liệu và thuật toán\n  + Có hiểu biết về các giao thức kết nối, API như RESTful, Websocket, GRPC\n- Năng lực chuyên môn:\n  + Thành thạo 1 trong các ngôn ngữ lập trình Python/Golang\n  + Thiết kế, tối ưu và quản lý dữ liệu bằng các hệ quản trị như MySQL, PostgreSQL hoặc MongoDB\n  + Xây dựng kiến trúc phần mềm vững chắc, đảm bảo hiệu suất, khả năng mở rộng và tính ổn định của hệ thống.\n  + Áp dụng các nguyên tắc OOP (Object-Oriented Programming) để xây dựng mã nguồn sạch, dễ mở rộng và bảo trì, tối ưu hóa cấu trúc hệ thống phần mềm.\n- Yêu cầu khác:\n  + Kỹ năng mềm: Tư duy giải quyết vấn đề, Khả năng làm việc nhóm, Khả năng truyền đạt giao tiếp\n  + Kỹ năng máy tính: Sử dụng tốt Linux, Windows, MacOS, Word, Excel\n  + Ngoại ngữ: Tiếng Anh khá\n- Điểm cộng/Ưu tiên ứng viên:\n  + Có kinh nghiệm làm việc với các nền tảng cloud như AWS, Azure hay GCP\n  + Có hiểu biết về các nền tảng và công nghệ học máy như TensorFlow hay PyTorch.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Century Tower, T14, Khu đô thị Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1041, 201, 2, 'Senior/ Middle AI Engineer (Python)', 'One Mount is Vietnam’s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam’s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nMAIN RESPONSIBILITIES\nWe are seeking highly skilled AI Engineers to enhance our product team. This position focuses on developing and implementing AI and data solutions within the real estate domain.\nBuild Data Pipelines: You\'ll directly build pipelines for collecting, processing, and standardizing real estate data (listings, transactions, legal documents, images, maps, etc.).\nDevelop Automated Valuation Models (AVM): Develop real estate valuation models based on big data.\nOptimize Search & Recommendation Engines: Enhance search and product recommendation tools using Recommendation Systems and NLP (Natural Language Processing) algorithms.\nIntegrate AI into Products: Collaborate with software architects, GIS, backend, and product teams to integrate AI models into real-world products.\nImplement & Improve ML Ops: Deploy, monitor, and continuously improve machine learning models in a production environment (ML Ops).\n\nYour skills and experience\nGraduated with a degree in Computer Science, Mathematics, AI, or equivalent fields.\nMinimum of 2 years of practical experience in deploying ML/AI models.\nProficient in Python and related libraries: Pandas, Scikit-learn, XGBoost, PyTorch/TensorFlow.\nExperienced with ETL systems, crawling, and big data processing.\nFamiliar with database systems: SQL & NoSQL (PostgreSQL, MongoDB, Elastic, BigQuery...).\nExperience API-izing models and deploying machine learning models to the Cloud (GCP/AWS preferred).\nExperience in PropTech, FinTech, AdTech platforms or data-driven products.\nExperience processing digital map data (Geospatial, GIS, Google Maps, Mapbox...).\nKnowledge of real estate, finance, investment, or online user behavior.\nLogical thinking, ability to work in a fast-paced environment, and not afraid to experiment.\n\nWhy you\'ll love working here\nSalary & Allowances\n13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\nLunch allowance: 730.000 VND/month\nSpecial occasion bonus: 2.500.000VND/year\nAnnual leaves: Up to 20 days/year (based on levels)\nHealth: Social insurance, premium health insurance, yearly health check \nLaptop, screen and other needed facilities/accounts/tools for work\nCareer Growth\nYearly salary review and promotion\nDiverse career path: Management or Expert and functions rotation opportunity\nFree learning sources in Udemy, Coursera, O’Reilly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\nRecognition and awards at team and organizational levels.\nGrow your career with opportunities across the dynamic ecosystem of Techcombank & Masterise Group.\nAccess special loan offers with competitive interest rates and flexible grace period options tailored to your financial needs.\nWorking Environment\nOpen & collaborative working space fosters both individual focus and teamwork activities\nYoung, dynamic, and collaborative working atmosphere\nUnwind zones: gaming, table tennis, yoga, gyms, bath rooms.\nPersonal lockers with QR code access.\nQuarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tower 2 (T26) Times City, 458 Minh Khai, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1042, 224, 2, 'Java/Kotlin Engineer (Senior/Principal_Banking Project)', 'Top 3 reasons to join us\nHybrid working; Flexible time; Macbook Pro\nL&D programs; 17 days off \n13.7 million B2C users; 140,000+ business customer\n\nJob description\nWho we are?\nMoney Forward is embarking on an exciting new venture in collaboration with Sumitomo Mitsui Financial Group and Sumitomo Mitsui Banking Corporation to explore the provision of BaaS (Banking as a Service) and digital banking solutions. We are seeking a talented Backend Engineer to join our core banking team, which will be at the heart of this initiative.\n\nResponsibilities and Duties\nAs a Software Engineer in the Core Banking Team, you will leverage Mambu, a leading cloud banking platform for neobanks and challenger banks, to build one of the most reliable and agile banking systems in the industry. Our goal is to shape the future of digital banking in Japan, making it more accessible and user-friendly than ever before.\n• Acquire domain knowledge in digital banking, including deposits, loans, clearing and settlement, basic accounting, domestic exchange, and Zengin network.\n• Actively engage with product owners to define requirements.\n• Develop, test, and deploy code that meets non-functional quality gates such as static code analysis, software composition analysis, SAST, and DAST, while maintaining numerical accuracy.\n• Design and build high-performance, scalable microservices centered around APIs.\n• Pursue test automation and continuous improvement, including API testing.\n• Take responsibility for the entire software development lifecycle.\n\nYour skills and experience\nMust have\n• Approximately 5 years of hands-on experience with Java or Kotlin and Spring Boot.\n• Practical experience with SQL, Apache Kafka, and related technologies.\n• Experience in creating and automating tests.\n• Hands-on experience with relational/non-relational databases, including transaction management, query optimization, and schema design.\n• Experience in microservice architecture and API design with a focus on scalability, maintainability, and supportability.\n• Proven experience in development with sufficient domain knowledge (not necessarily in the financial industry).\n• Understanding of CI/CD concepts and practices.\n• Experience developing cloud-native applications in major cloud environments such as AWS, Azure, or GCP.\n• Bachelor\'s or Master\'s degree in Computer Science or a related field, or equivalent practical experience.\n\nNice to have\n• Experience working in financial institutions, particularly banks or fintech companies.\n• Basic knowledge of accounting or double-entry bookkeeping.\n• Knowledge of CCP and settlement mechanisms.\n• Experience implementing CI/CD pipelines from development to production in the cloud.\n• Experience in AI development and/or experience in using AI tools to improve development processes. Money Forward recently announced our AI Strategy roadmap which focuses on improving AI-driven operational efficiencies, as well as integrating AI agents into our products to deliver better value to our users.\n\nLanguage Requirements\n• English: Business level (TOEIC score of 700 or above)\n\nWho We’re Looking For\n• Ability to quickly adapt to changing priorities and situations.\n• A critical thinker who questions the status quo.\n• Excellent communication skills with the ability to articulate ideas clearly.\n• Willingness to learn necessary domain knowledge and technologies.\n• Understanding of DevOps/DevSecOps.\n\nTechnology Stack and Tools Used\n• Kotlin, Spring Boot, Gradle, jOOQ, Liquibase, Kotest/JUnit, Karate/Rest Assured\n• Redis, MySQL\n• Docker, AWS ECS\n• Apache Kafka (AWS MSK)\n• Mambu cloud banking platform\n• GitHub, Backstage, Amazon ECR\n• GitHub Actions, ArgoCD, Sonar Cloud, Detekt, AeyeScan\n• ChatGPT, Copilot, Gemni\n\nWhy you\'ll love working here\nCaring Mental & Physical Recreation:\n• Hybrid working\n• Full salary in probation & 13th month salary\n• Social insurance on full salary from probation\n• Premium Health insurance from probation\n• Flexible start 8AM-9AM from Mon-Fri\n• 16 days off annually + 1 Birthday Leave \n• Paternity leave extra 5 days \n• Annual company trip; Quarterly team building activities\n• Club activities\n• Annual health check\nCaring Career & Development:\n• Clear Career path\n• Foreign language & International technology-related certifications sponsoring\n• Well-equipped facility: Macbook pro, additional monitor..\n• Soft skill workshops\n• Tech seminars\n• Monthly and biannually Recognition Awards\n• Performance review twice/year', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ETown Central Building, 11 Doan Van Bo, Ward 13, District 4, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1043, 631, 2, 'UI-UX Web Designer (HTML, CSS, Figma, Prototype)', 'Top 3 reasons to join us\n- Môi trường trẻ, năng động\n- Cơ hội phát triển bản thân\n- Up to 17th-month salary\n\nJob description\n- Thiết kế giao diện website thương mại điện tử đảm bảo tính thẩm mỹ, UX/UI tối ưu.\n- Sử dụng Figma để thiết kế wireframes, mockups và prototypes.\n- Phối hợp với team phát triển để chuyển đổi thiết kế thành giao diện thực tế.\n- Thiết kế banner, landing page, và các thành phần đồ họa liên quan đến e-commerce.\n- Cập nhật xu hướng thiết kế mới, tối ưu UI/UX để nâng cao trải nghiệm người dùng.\n- Hỗ trợ điều chỉnh thiết kế dựa trên phản hồi của người dùng và bộ phận kinh doanh.\n\nYour skills and experience\n- Có kinh nghiệm từ 1-3 năm trong lĩnh vực thiết kế web, ưu tiên e-commerce.\n- Thành thạo Figma, có kỹ năng tạo prototype và làm việc theo design system.\n- Có kiến thức về UI/UX, hiểu biết về hành vi người dùng trên nền tảng thương mại điện tử.\n- Biết sử dụng các công cụ thiết kế khác như Photoshop, Illustrator là một lợi thế.\n- Có khả năng làm việc nhóm, giao tiếp tốt và tư duy sáng tạo.\n- Ưu tiên ứng viên có kinh nghiệm làm việc với developers hoặc hiểu về HTML/CSS cơ bản.\n\nWhy you\'ll love working here\n- Thời gian làm việc: 08h30 - 17h30, từ thứ 2 - thứ 6\n- Mức lương: thỏa thuận\n- Tham gia BHXH \n- Phụ cấp cơm trưa \n- Lương tháng 13 + thưởng cuối năm \n- Thưởng khi đạt KPI \n- Review lương hằng năm \n- Du lịch hằng năm \n- Tham gia các khóa học chuyên môn để phát triển chuyên môn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '40 Hoa Đào, Phường 02, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1044, 624, 2, 'Android Developer (Java, Kotlin, OOP)', 'Job description\n- Xây dựng và phát triển các ứng dụng mới trên nền tảng Android\n- Trau dồi kiến thức, kinh nghiệm để đáp ứng nhu cầu công việc\n- Cùng team lên ý tưởng và giải pháp cho các tính năng mới của ứng dụng\n- Sửa lỗi và cải thiện tính năng, hiệu suất của sản phẩm.\n\nYour skills and experience\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật phần mềm hoặc các ngành liên quan.\n- Nắm chắc kiến thức cơ bản trong phát triển ứng dụng Android.\n- Sử dụng tốt Kotlin/Java\n- Hiểu cơ bản về Android SDK và các thành phần chính như Activities, Services, Broadcast Receivers, Content Providers.\n- Hiểu cơ bản về mô hình triển khai ứng dụng MVVM, Clean Architecture.\n- Thành thạo lập trình hướng đối tượng (OOP), Cấu trúc dữ liệu và giải thuật.\n- Tư duy logic, khả năng phân tích và giải quyết vấn đề một cách hiệu quả.\n- Kỹ năng giao tiếp tốt và khả năng làm việc nhóm.\n\nƯu tiên\n- Đã và đang sử dụng jetpack compose trong công việc.\n- Kiến thức về thư viện: Sử dụng cơ bản các thư viện hỗ trợ như Coroutines, Flow, LiveData.\n- Kỹ năng mềm: Khả năng làm việc độc lập, chịu được áp lực công việc và có tinh thần học hỏi, đổi mới.\n\nWhy you\'ll love working here\n- Mức lương hấp dẫn lên đến 15 triệu đồng/tháng.\n- Review lương 2 lần/năm.\n- Hưởng lương tháng 13 hàng năm, thưởng dự án không giới hạn.\n- Được đào tạo bài bản cùng leader có nhiều năm kinh nghiệm trong phát triển Mobile app.\n- Lộ trình phát triển bản thân rõ ràng, tham gia đào tạo chuyên môn để nâng cao năng lực.\n- Có cơ hội thăng tiến lên làm Leader, PM.\n- Trải nghiệm dự án thách thức lớn.\n- Đóng BHXH, BHYT theo quy định của pháp luật.\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động và sáng tạo.\n- Tham gia các hoạt động vui chơi giải trí, du lịch hàng năm, team building hàng quý, ăn uống cùng thành viên trong công ty trong các dịp Sinh nhật Công ty, 8/3, 20/10, Gala cuối năm,... Teabreak chiều thứ 5 hàng tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 2, Tòa Nhà AC Building, 78 Duy Tân, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1045, 585, 2, 'QA Engineer', 'Job description\n\nWhat you will be doing:\n- Work with internal teams (Engineering/Product) to understand requirements and product features; also review and analyze requirements, specifications, and technical design documents, providing timely feedback\n- Develop detailed, comprehensive, and well-structured test plans and test cases\n- Prioritize, plan and execute testing activities\n- Design, develop, and execute automated tests, while also contributing to the enhancement and clear documentation of our automation framework and scripts. Actively identify, report, track, and verify software defects.\n- Perform regression tests and apply creative exploratory testing techniques to discover challenging scenarios and edge cases.\n\nYour skills and experience\n\nWhat we need from you:\n- Minimum 3 years of hands-on experience in software quality assurance, including developing and maintaining test automation.\n- Fluency in written and spoken English is required for communication with international teams and clients.\n- Strong understanding of software QA fundamentals, methodologies, tools, and processes.\n- Proven experience creating automated tests using test frameworks (e.g., Katalon Studio, Selenium Java, WebdriverIO).\n- A detail-oriented person, and motivated to proactively identify and resolve issues.\n- Willing to help your teammates, share your knowledge with them, and learn from them.\n- Collaborative, adaptable, and dedicated to continuous learning and improvement, both personally and for team processes.\n\nWhy you\'ll love working here\n- 100% probation salary\n- 14 days annual leave (+1 day per year, max 21 days)\n- Hybrid work (at least 2 days in office)\n- Full salary social insurance contribution\n- Private health insurance (Bao Viet) & annual health check-up\n- MacBook provided within 2-month probation', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '261 Hoang Van Thu st, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1046, 514, 2, 'Lead AI Consultant (LLMs, GenAI)', 'At NFQ, we focus on Scaling Business—helping companies grow, optimize, and transform through technology and strategic consulting. With 800+ experts across 10 offices, we don’t just build software; we partner with businesses to solve complex challenges, drive efficiency, and unlock new growth opportunities.\n\nUnlike traditional outsourcing, our approach goes beyond executing tasks—we advise, challenge, and co-create solutions that enable businesses to scale effectively. Whether it’s expanding into new markets, streamlining operations, or driving digital transformation, we are committed to delivering impact that lasts.\n\nWhy NFQ?\n\n🔹 Fairness – We treat our colleagues, clients, shareholders, and the environment with integrity and respect.\n🔹 Entrepreneurship – We think like entrepreneurs, taking smart risks and turning ideas into real impact.\n🔹 Excellence – We go beyond expectations to deliver results that truly make a difference.\n\nAs part of our mission to build world-class AI Consulting Services, we are seeking a strategic and business-savvy AI Consulting Lead to drive our client engagements and shape the future of our offerings.\n\nThis is a high-impact, client-facing role for someone who can confidently engage with C-suite executives—entrepreneurs, CEOs, CTOs—and translate business goals into actionable AI strategies. You’ll work closely with our Data, Engineering, and Product teams to design and deliver transformative AI solutions.\n\nWhat You’ll Do\n\nEngage directly with executive-level stakeholders to understand their strategic goals, operational pain points, and AI-readiness.\nTranslate high-level business needs into concrete AI strategies, balancing market relevance, technical feasibility, and business value.\nDesign tailored AI solutions, collaborating with internal technical teams to ensure clarity, alignment, and delivery excellence.\nAct as a trusted advisor throughout the consulting lifecycle—from discovery and ideation to solution design and implementation oversight.\nLead and support pre-sales activities, including proposal development, technical pitches, and high-level solution architecture.\nStay ahead of emerging trends in AI/ML, generative AI, and LLMs, and guide clients in understanding their strategic implications.\nEnsure delivery teams stay aligned with business outcomes and help build long-term client relationships.\nChampion the growth of the AI Consulting practice internally through bold, high-energy leadership.\n\nYour skills and experience\n\n5+ years of experience in AI, Data, and Technology Consulting, ideally with exposure to both technical and strategic workstreams.\nDemonstrated ability to engage and influence C-suite stakeholders.\nProven track record designing and delivering AI/ML solutions, especially with generative AI and LLMs.\nHands-on experience with Python and relevant AI/ML frameworks (e.g., TensorFlow, PyTorch, LangChain).\nStrong strategic thinking: able to bridge the gap between business vision and technical execution.\nExcellent communicator: articulate, persuasive, and capable of conveying complex ideas to diverse audiences.\nEntrepreneurial mindset: proactive, hands-on, and focused on delivering real business impact.\nFluent in English (verbal & written); additional languages are a plus.\n\nWhy you\'ll love working here\n\nBe at the forefront of meaningful AI innovation—not just hype.\nShape a new AI Consulting service line with leadership backing and resources.\nCollaborate with ambitious founders, global teams, and clients building impactful products.\nWork in a flat, transparent culture that values autonomy and bold thinking.\nEnjoy a flexible, growth-oriented environment with global exposure.\n\nPerks That Make a Difference:\n\n🏆 Join Vietnam’s Best IT Company – Recognized by ITViec for 7 consecutive years, including 2 successive years as the Winner. Work with some of the best minds in the industry and be part of a company that’s redefining how businesses scale through technology.\n🌍 Career Growth & Leadership Development – Work closely with NFQ’s leadership team, gain mentorship from experienced executives, and have direct exposure to high-level strategic decisions. Your growth is limitless, as long as you’re ready to step up, opportunities will always be there for you.\n💰 Competitive Compensation – We believe great talent deserves great rewards. Expect an attractive salary, performance-based bonuses, and a benefits package that reflects your impact. We value talent over salary budgets—exceptional contributions deserve exceptional rewards.\n✨ And Many More Benefits to Explore! But most importantly healthy work-life balance and an environment where you can thrive—professionally and personally. Including:\n\nLaptop is provided.\nCommunity Tech activities.\nA fun & dynamic environment and freedom to be creative.\nModern office with a flexible relaxing zone.\n13th-month salary pro-rata (based on business situation/performance).\nPerformance review 2 times/ year.\nExtra Premium Healthcare & Annual Health-check.\n15 days annual leaves.\n\nWorking time: Monday – Friday (9AM - 6PM)\n\nLocations: NFQ welcomes you to our offices in Vietnam (Ho Chi Minh, Da Nang, Ha Noi & Can Tho), choose the location that suits you best and join us on a journey of innovation and excellence.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Podium Floor, Sapphire 2 Tower, 92 Nguyen Huu Canh Street, Ward 22, Binh Thanh, Ho Chi Minh / 23rd Fl. G8 Golden building, 65 Hai Phong Street, Hai Chau, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1047, 464, 2, 'Backend Developer (AWS, Golang, NodeJS, Java)', 'Job description\nGet hands-on building the powerful backend services that drive our fintech platform! You\'ll be a key player in developing APIs and integrations.\nDesign, develop, test, and maintain backend microservices and APIs according to the architecture defined by the Lead Engineer.\nImplement integrations with our core SaaS platforms (CMS, Risk, Loyalty) and our partner bank\'s systems.\nWrite clean, efficient, well-documented, and testable code.\nCollaborate with frontend engineers, product managers, and other teams to deliver features.\nTroubleshoot and resolve backend issues, ensuring system stability and performance. Utilize AI tools for code completion, debugging assistance, or generating unit tests.\n\nYour skills and experience\nMust-Have Skills & Experience:\nSolid experience (2+ years) in backend development using relevant languages (Java, Go, Python, Node.js - aligning with the Lead\'s choice) and familiarity with Card Management Systems\nExperience building and consuming RESTful APIs.\nUnderstanding of database concepts (SQL and/or NoSQL).\nFamiliarity with software development best practices, including version control (Git), testing, and clean code principles.\nStrong problem-solving skills and a collaborative attitude.\nEagerness to learn new technologies and the fintech domain. Comfortable using AI coding assistants.\n\nGood-to-Have Skills & Experience:\nExperience with cloud platforms (AWS, GCP, Azure).\nFamiliarity with microservices architecture or containerization (Docker).\nExperience with CI/CD tools.\nPrior experience in fintech or payments.\nExperience integrating with third-party APIs\n\nWhy you\'ll love working here\nReady to build the future of digital finance in Vietnam? 🇻🇳✨ An innovative AI-driven early-stage fintech, founded by former McKinsey partners and backed by global investors, is looking for the best young subject matter experts in Vietnam to help them launch ! 🚀\nIf you thrive in fast-paced, \'zero-to-one\' environments and don’t feel afraid of challenging the status quo in digital banking, credit cards and BNPL, let\'s talk!\nOur benefits include competitive compensation, 5 days work week, flexible working, 20 days annual leave, immersive learning and a lot more.\nWe\'re growing our core team in Ho Chi Minh City and looking for passionate trailblazers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thảo Điền, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1048, 503, 2, 'Fullstack Product Engineer', 'We’re looking for a Founding Fullstack Engineer to help us move fast — and smart — across our platform and tooling. You’ll shape our tech stack, make high-leverage decisions, and build the foundation for a product that needs to be both powerful and beautiful. You’ll join a small, focused team and ship meaningful product from day one. \n\nYou’ll work on things like:\n- Build our next-gen supplier profile editor, with dynamic data structures\n- Create a custom analytics dashboard for buyers and internal use\n- Integrate OpenAI workflows to power smart search, automated tagging, and matchmaking\n- Architect and implement onboarding flows with Clerk + Supabase\n- Design clean, dev-friendly internal APIs to support future contributors\n- Refactor and simplify legacy product components (Next.js, Prisma)\n\nYou’ll also help us think:\n- How should our system model “materials”, “suppliers”, “applications”?\n- What kind of UI lets people compare radically different products?\n- Where can we use AI to reduce friction and amplify user delight?\n\nWhat you’ll use regularly — and what we hope you’re great at.\nCurrent Tech Stack:\n- Frontend: Next.js (App Router), React, TypeScript\n- Backend: Prisma ORM, PostgreSQL\n- Auth: Clerk\n- Infra / Data: Supabase, Algolia\n- AI / Automation: OpenAI, Cursor.ai, Zapier, GPT-based triggers\n- Other: Vercel, Notion API, Typeform, custom internal tools\n\nYou don’t need to know everything — we care more about mindset than mastery.\n\nYou must have:\n- TypeScript\n- React/Next.js (App Router)\n- Prisma ORM\n\nBonus points for:\n- Clerk, Supabase, Algolia\n- AI integration (OpenAI, )\n- Experience building internal tooling or dashboards\n- Designing dev-friendly backend APIs\n\nWhy you\'ll love working here:\n- Seat at the early table (Top 10 hires)\n- Real influence on product, infra, architecture\n- Mission that connects to climate, not just code\n- Remote-first team, async-friendly\n- Regular IRL low-carbon team meetups\n- Fast feedback, lots of trust, no meetings for the sake of it\n- Salary: location-adjusted + equity (from next round onwards)\n\nthe ball is in your court now!\nReach out to us at the form below. We’ll get back to you as soon as possible. We move fast.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1049, 225, 2, 'Senior SRE / DevOps Engineer', 'By applying for the above position, you accept and agree that your personal data and any information stated in the attached curriculum vitae (CV) will be used and processed by ITViec and NAB Vietnam for recruitment purposes. The storage and processing of such information will comply with the applicable laws of Vietnam, and the policies and procedures of ITViec and NAB Vietnam regarding personal data, as amended from time to time.\n\nABOUT THE JOB\nWe\'re seeking Senior DevOps/Site Reliability Engineers who have had a proven track record of running critical shared application platforms in a production cloud environment who will take a team-first approach and can act as a multiplier, making other engineers better at their craft.\nYou will be responsible for behaving in accordance with NAB\'s Code of Conduct and demonstrating the Enterprise Behaviours in all customers, community and employee interactions, protecting NAB information and information systems.\n\nYOUR JOB RESPONSIBILITIES\n- Work in fortnightly iteration-based software development environment and required to attend Daily stand-ups, retros, planning, showcases and other Scrum activities;\n- Provide support to customers of our services during business hours and in a rotating support roster due to the 24x7 nature of the services;\n- Work on Change Requests, Incidents, Defects and Problem Records;\n- Maintain software and infrastructure currency;\n- Troubleshoot, debug and upgrade existing systems;\n- Participate in Service Governance and Compliance activities;\n- Complete mandatory trainings and keep your skills up to date based on project requirements and personal development;\n- Establish Quarterly/Yearly professional development goals;\n- Design, develop, test, deploy, maintain and improve software;\n- Develop flowcharts, layouts and documentation to identify requirements & solutions;\n- Write well designed & high-quality testable code;\n- Produce specifications and determine operational feasibility;\n- Integrate software components into fully functional platform;\n- Apply pro-actively & perform hands-on design and implementation of best practice CI/CD;\n- Coaching & mentoring of other Service Team members;\n- Develop/contribute to software verification plans and quality assurance procedures;\n- Document and maintain software functionality;\n- Comply with project plans, industry standards and regulatory requirements;\n- Work with Product Owners and Managers, Solution Designers, Tech Leads, Operations teams, Engineering Managers, Head of Technology, Release Train Engineers and Scrum Masters to determine software development requirements and Release priorities besides driving Operational efficiencies.\n\nYOUR SKILLS AND EXPERIENCE\n- 5+ years’ extensive experience of DevOps or Site Reliability Engineer across all Phases of the software lifecycle;\n- Experienced in AWS or Azure cloud technologies;\n- Experience in building CI/CD pipeline automation, tooling (Github, Jenkins, Artifactory, and Docker) and Compliance as code;\n- Have an in-depth understanding of microservice architecture, API management, and distributed systems concepts;\n- Experience with cloud services is essential, in particular, our core AWS Technologies (EC2, ECS, EKS, S3, DynamoDB, Lambda, CloudFormation, CloudWatch, SQS, SNS, ...);\n- Experience hands-on Infrastructure as Code abilities e.g. Terraform, Ansible, Packer, Python;\n- Skills on AppDynamics, Splunk & OpenSearch or any kind of monitoring & observability tools;\n- Linux/Unix Scripting experience, good database programming skills in JDBC, Hysterix, PostgreSQL or Oracle database;\n- Ability to develop code and work with testers and developers;\n- Experienced and highly capable in continually developing and balancing technical and soft skills with an understanding that making great software requires both problem identification and prevention;\n- Strong communication, documentation, organization, and time management skills;\n- Good English skills, both oral and written.\n\nWHY YOU\'LL LOVE WORKING HERE\n1. Generous compensation and benefit package\n- Attractive salary and benefits\n- 20-day annual leave and 7-day sick leave, etc.\n- 13th month salary and Annual Performance Bonus\n- Premium healthcare for yourself and family members\n\n2. Exciting career and development opportunities\n- Large scale products with modern technologies in banking domain\n- Clear roadmap for career advancement in both technical and leadership pathways\n- Sponsored certificates in both IT and banking/finance\n- Premium account on Udemy\n- English learning with native teachers\n\n3. Professional and engaging working environment\n- Hybrid working model and excellent work-life balance\n- Well-equipped & modern Agile office with fully-stocked pantry\n- Annual company trip and events\n\nA DIVERSE AND INCLUSIVE WORKPLACE WORKS BETTER FOR EVERYONE\nNAB is a place where colleagues of all genders, sexualities and ages, carers and colleagues with disability, and colleagues from all cultures, races and religions have the opportunity to thrive, connect and grow.\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Hallmark, 15 Tran Bach Dang, Thu Thiem Ward, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1050, 632, 2, 'Business Analyst (Fluent in Korean)', 'Overview:\nYouthDev is looking for a Business Analyst who is fluent in Korean to join our dynamic and fast-paced team. In this role, you will work directly with stakeholders from Media Korean’s team in Korea, supporting real-world software development projects. This is an excellent opportunity for someone who is eager to grow their Business Analysis skills in a cross-functional and international environment.\n\nKey Responsibilities:\n- Work directly with Media Korean’s team in Korea.\n- Collaborate with stakeholders to gather business and product requirements.\n- Participate in brainstorming sessions to generate new feature ideas and improvements.\n- Analyze and document requirements in the form of user stories and acceptance criteria.\n- Assist in planning and preparing requirements in time for sprint grooming sessions.\n- Join weekly BA meetings with stakeholders to review and refine upcoming sprint content.\n- Work closely with developers and QA to ensure clear understanding of requirements.\n- Support the creation of user guides, feature documents, and training materials.\n- Participate in feature demos and present updates to key stakeholders.\n\nYour skills and experience\nQualifications:\n- Proficient in Korean (TOPIK Level 5 or above, or equivalent).\n- Bachelor’s degree in Korean Language Studies, Business, Information Technology, or related fields.\n- 1+ years of experience in Business Analysis or a software development environment is preferred.\n- Strong analytical thinking, communication, and documentation skills.\n- Able to work collaboratively with cross-functional teams and manage multiple priorities.\n- Eagerness to learn and grow in a fast-paced and agile work environment.\n\nWhy you\'ll love working here\nWhat We Offer:\n- Opportunity to work closely with Korean partners and international teams.\n- On-the-job training and mentorship from senior BAs and product leaders.\n- Clear career development path and performance-based growth opportunities.\n- Collaborative and supportive team culture.\n- Competitive salary and benefits package.\n- Salary: 10,000,000 – 30,000,000 VNĐ\n- Working hours: 9h00 – 18h00, from Monday to Friday', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '215 Nguyễn Gia Trí, Phường 25, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1051, 633, 2, 'Software Developer (PHP/ Laravel)', 'Công ty Cổ phần Dịch vụ Chữ ký số Intrust là một thành viên của Intrust Group, đơn vị hàng đầu cung cấp dịch vụ Chữ ký số từ xa IntrustCA và các ứng dụng giao dịch điện tử, chuyển đổi số cho các khách hàng lớn trong lĩnh vực Ngân hàng, Tổ chức tài chính, Doanh nghiệp FDI, các đơn vị sự nghiệp công lập và cơ quan hành chính nhà nước. Môi trường làm việc trẻ, năng động, chuyên nghiệp, nhiều cơ hội để nâng cao năng lực bản thân, đãi ngộ xứng đáng, trọng dụng nhân tài.\n\nMÔ TẢ CÔNG VIỆC\n- Tham gia phát triển các dự án lớn với nhiều lĩnh vực.\n- Tham gia khảo sát, thiết kế các bài toán quản lý theo yêu cầu khách hàng.\n- Chủ động, đam mê công việc, sẵn sàng chấp nhận thách thức, luôn chú ý phát triển bản thân lên tầm cao mới.\n- Năng động, cầu tiến, có mục tiêu rõ ràng về sự nghiệp, ham học hỏi\n- Chủ động trong công việc, có tinh thần trách nhiệm cao để hoàn thành công việc được giao.\n- Chúng tôi có nhiều dự án sử dụng nhiều nền tảng công nghệ như: Php, Angular, Laravel, NodeJS, Java, .NET… (ưu tiên có kinh nghiệm về php laravel). Bạn chỉ cần có kiến thức cơ bản một trong các công nghệ trên và chúng tôi sẽ đào tạo thêm để các bạn trở thành những chuyên gia.\n\nYour skills and experience\n- Nam, nữ tốt nghiệp đại học, cao đẳng, có khả năng tư vấn tốt, ưu tiên có kinh nghiệm 1 năm trở lên.\n- Ưu tiên ứng viên sử dụng ngôn ngữ lập trình  php laravel\n- Có khả năng ứng xử, giao tiếp, xử lý tình huống nhanh nhạy, linh hoạt \n- Có tinh thần trách nhiệm cao, tận tụy trong công việc, ham học hỏi.\n- Có khả năng chịu được áp lực công việc, làm việc độc lập hoặc theo nhóm hiệu quả\n- Tính tình ôn hòa, nhã nhặn, kiên nhẫn, không nổi nóng.\n- Thành thạo vi tính văn phòng (word, excel, email, …)\n\nWhy you\'ll love working here\n- Lương cơ bản + phụ cấp + thưởng kinh doanh. Lương tháng 13\n- Xét tăng lương 1 lần/năm, lộ trình thăng tiến rõ ràng  \n- Được đào tạo nghiệp vụ trước khi bắt đầu công việc.  \n- Nhiều cơ hội thăng tiến tốt lên các vị trí cao hơn (trưởng nhóm, trưởng phòng,…) hoặc các chuyên môn khác.\n- Văn hóa công ty phong phú cho phép phát huy tối đa khả năng chủ động sáng tạo.\n- Hưởng các chế độ bảo hiểm xã hội, y tế theo quy định.  \n- Hỗ trợ các khóa huấn luyện kỹ năng nghề nghiệp, kỹ năng mềm, ...\n- Ðược tham gia các hoạt động ngoại khóa, du lịch, …\n- Công ty cung cấp các thiết bị như: Máy tính, điện thoại, ...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, Tòa nhà Báo nông thôn ngày nay, Dương Đình Nghệ, Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1052, 634, 2, 'Product Manager (Blockchain/Product Owner)', 'Top 3 reasons to join us\n- Competitive salary\n- Income: Project bonuses, Tet bonuses\n- Social/health/unemployment insurance \n\nJob description\n1. Responsible for end-to-end design of company-related products, including but not limited to product planning, business research, requirements analysis, documentation, prototyping, and development follow-up.\n2. Collaborate with business teams to handle system design, roadmap planning, feature module design, and system optimization for online business products, delivering the optimal system solutions from a cost-benefit perspective.\n3. Work closely with operations and tech development teams to ensure smooth product launches, follow up on optimizations and iterations promptly, and ensure system security and stability.\n4. Familiar with common business models and regulatory practices in the financial industry, actively cooperating with business and technical teams to support rapid business development and improve management.\n\nYour skills and experience\n1. Associate degree or higher, with a background in Computer Science, Finance, or Mathematics preferred.\n2. Over 3 years of experience as an internet product manager, with at least 1 year of experience in blockchain-related work.\n3. Ability to independently draft product requirement documents, drive system launches, and demonstrate strong product design and planning skills.\n4. Familiarity with market and event operations is a plus.\n5. Basic understanding of financial industry concepts.\n6. Familiarity with Web3 projects is preferred.\n\nWhy you\'ll love working here\n1. Competitive salary, commensurate with experience and skills.\n2. Income: Project bonuses, Tet bonuses, and holiday bonuses.\n3. Eligible for social insurance, health insurance, and unemployment insurance in accordance with current labor laws and company policies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '121 Ngo Gia Tu, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1053, 635, 2, 'ERP Developer (C#, .NET, Required: D365 FO)', 'Top 3 reasons to join us\n- Opportunities to learn, grow and develop\n- Discounted English courses for employee and family\n- Good salary and benefits\n\nJob description\n- Use MS SQL and related technologies to maintain and customize Microsoft Dynamics installations \n- Collaborate with other Developers, Project Managers, Business Partners, End Users to identify, troubleshoot and implement solutions\n- Conduct unit testing and debugging along with system and integration testing\n- Produce technical specifications and software design documents \n- Develop and support interfaces/integrations between D365 and related in-house or external business systems\n- Provide technical solution to troubleshoot issues\n- Willing to upskill/ use different framework if required\n\nYour skills and experience\nQualifications\n- Must have University degree in Information Technology / Management Information Systems or equivalent\n- Minimum 2 years of working experience in design and development of Dynamics AX components (Required: D365 FO. Preferred: AX 2012).\n\nPreferred experience:\n- 2+ years strong .Net / C#\n- 2+ years working on APIs and integration between multiple systems\n- PHP and/or Python is an added advantage\n\nSkills: Good planning and communication skills\nLanguage: English\nSoft skill: Good problem solving, teamwork skill\nOther requirements\n- Team player\n- Proactive\n- Independent\n\nWhy you\'ll love working here\n- Competitive salary\n- Professional working environment\n- ILA ELT Courses Discount:  90% for employee; 75% for 1st relation of employee; 50% for 2nd and 3rd relation of employee\n- Engagement activities (Training, ILA Socials)\n- Health Check\n- Healthcare Insurance\n- 14 days annual leave', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ILA Headquarter - 15 Tran Bach Dang, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1054, 607, 2, 'Project Manager', '(This position will work at the Client\'s site in Nha Be District, HCMC) What do we do? As a pioneer for digital transformation GFT develops sustainable solutions across new technologies – from cloud engineering and artificial intelligence to blockchain/DLT. With its deep technological expertise, strong partnerships, and comprehensive market know-how GFT offers advice to the financial and insurance sectors, as well as in the manufacturing industry. Through the intelligent use of IT solutions GFT increases productivity and creates added value for clients. Companies gain easy and safe access to scalable IT-applications and innovative business models.  Who are we? Having started in Germany in 1987, GFT Technologies has grown to become a trusted Software Engineering and Consulting specialist for the international financial industry, counting many of the world’s largest and best-known Banks as our clients. We are an organization that empowers you to not only explore but raise your potential and seek out opportunities that add value. At GFT, diversity, equality, and inclusion are at the core of who we are. Ensuring a diverse and inclusive working environment for all communities is one of the main pillars of our diversity strategy, based on our core values and culture. We have been certified for 2022/23 as a ‘Great place to work’ in the APAC region. So, if you want to have the opportunity to work with an outstanding and progressive organization this position could be right for you. We are seeking an accomplished and highly experienced Project Manager to join our dynamic team. The successful candidate will play a pivotal role in managing project delivery and leading project teams to implement IT solutions that meet our clients\' strategic objectives.  Role responsibilities Lead and manage IT projects from initiation through to successful completion, ensuring delivery within defined scope, timelines, and budget Act as Scrum Master for multiple teams, facilitating Agile ceremonies and promoting the adoption of Agile best practices Collaborate with stakeholders to clearly define project scope, objectives, and deliverables, ensuring alignment with business goals Develop and maintain comprehensive project plans, including timelines, milestones, and resource allocations Monitor project progress, proactively identifying and addressing risks and issues to ensure project success Foster effective communication and collaboration across cross-functional teams and stakeholders Provide regular project status updates and detailed reports to stakeholders and senior management Ensure strict adherence to GFT’s project management methodologies, standards, and best practices Champion continuous improvement initiatives to enhance project delivery processes and team performance.  Your Skills and Experience Bachelor’s degree in Computer Science, Information Technology, Business Administration, or a related field Project Management Professional (PMP) or Certified ScrumMaster (CSM) certification is highly desirable A minimum of 12 years of experience in project management and Agile methodologies, ideally within the IT or banking industry Demonstrated success in managing complex projects and delivering high-quality results. Strong leadership and team management skills, with the ability to inspire, motivate, and develop project teams Excellent communication and interpersonal skills, with a proven ability to build strong relationships with stakeholders at all levels Exceptional problem-solving and decision-making capabilities Proficiency in project management tools such as Microsoft Project, JIRA, or equivalent.  Preferred Skills Extensive experience in digital banking or financial services projects In-depth knowledge of cloud platforms (GCP, AWS) and associated technologies Familiarity with DevOps practices and tools Banking domain knowledge is a plus  Note:  Due to the high volume of applications we receive, we are unable to respond to every candidate individually. If you have not received a response from GFT regarding your application within 10 workdays, please consider that we have decided to proceed with other candidates. We truly appreciate your interest in GFT and thank you for your understanding.  Why you\'ll love working here HR benefits Competitive salary Salary band per level are reviewed once per year 13th month salary pro rata depending on the employee’s length of service (within a calender year), paid with the December salary Monthly lunch allowance: 700,000 VND/employee Parking: GFT covers the monthly parking fee for employee motorbikes Performance evaluation is once per year, for 2 purposes:   Performance bonus   Salary increments  Health care Private health insurance: including accident, outpatient, in-patient, maternity, and dental for all permanent employees who pass 2-month probation. Optical: expense claim for eyewear Annual health check-ups.  Vacation Maximum 18-day vacation leave/year (with the ability to carry over 05 days till 31st March of the following year) Adding one more annual leave day for each two-year anniversary.  Healthy lifestyle Sports and hobby clubs: company has an annual fund for fitness activities, which is allocated per month as team’s vote. Range of healthy snacks, tea, coffee, milk and beer on tap  Social Company townhall: each 6 weeks CSR activities: as per company’s CSR guideline Onsite tour/training courses at other GFT offices and client’s destination overseas (where applicable).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '29A Nguyen Dinh Chieu, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1055, 209, 2, 'Project Manager - Up to $4000', 'WORK LOCATION: Ha Noi, Ho Chi Minh, Da Nang, Hue\n\nJOB OVERVIEW\nWe are looking for a Project Manager to participate in the project of consulting and developing a sales chain management system; an accounting system for a manufacturing company; production management system for watch manufacturing customers.\n\nRESPONSIBILITIES\n- Work with Customers to define technical and business requirements.\n- Coordinating with the sales department, participating in the consulting phase to come up with a design solution to propose to the customer.\n- Create and provide proposal, estimation.\n- Implement strategic consulting and project implementation, manage and direct the project successfully.\n- Complete the tasks of the PM in the project.\n- Financial management / financial health of the project.\n- Implement standard processes of FSO on project management.\n\nYour skills and experience\n\nBasic Qualifications:\n- Experience as a project manager (PM) or Business Analysis for End-user from 5 years or more.\n- Be fluent in Japanese (N1 or equivalent N1).\n- Good documentation and presentation skills.\n- Have a good understanding of the software development stages in the project with End-users customers.\n- 5 years of experience in software development projects.\n\nNice to have:\n- Having PMP/PMI-ACP certificate is an advantage.\n- Professional in accounting and e-commerce or warehouse/Logistics/production management.\n- Experience in project management of 50 ~ 100 people or more with scope RD~AMS.\n\nWhy you\'ll love working here\n- Be part of our hugely international environment; we are currently working for Japanese/Global projects, where you can have many opportunities to working overseas;\n- Competitive salary package based on skills and experience.;\n- We create great teams and take very good care of them;\n- Great opportunity to grow with the company;\n- Frequent staff activities and company parties;\n- Awesome social events and parties for employees;\n- 20% discount on school fee if your sons/ daughters join FPT School;\n- Udemy/ ELSA PRO accounts for every employee & Udacity accounts for Managers.\n\nSpecial offer for senior level:\n- Relocating package: Up to 100M (for senior candidates from Hanoi/HCM.C to Danang City);\n- Loan support: 4% interest rate (1 – 2 Billion VND package).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Building, 17 Duy Tân Str., Cau Giay, Ha Noi, F-Town 3, 3 Võ Chí Công, Phường Long Thạnh Mỹ, Thu Duc City, Ho Chi Minh, Tòa nhà FPT Complex, Đường Nam Kỳ Khởi Nghĩa, Phường Hòa Hải, Ngu Hanh Son, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1056, 636, 2, 'Senior Backend (Laravel, NodeJS, MySQL)', 'Top 3 reasons to join us\n- Lương + thưởng dự án\n- Cơ hội lên Tech Lead/Core Team\n- Làm việc linh hoạt, hỗ trợ tài liệu & thiết bị\n\nJob description\n- Thiết kế kiến trúc hệ thống (Monolith/Microservice)\n- Code Laravel + NodeJS, thiết kế API, xử lý logic phức tạp\n- Tối ưu DB (MySQL/PostgreSQL), tích hợp Redis, Queue\n- Review code, hỗ trợ team dev, xử lý lỗi sản phẩm\n- Tham gia CI/CD, Docker, GitLab, cấu hình môi trường dev/stage/prod\n\nYour skills and experience\n- ≥ 4 năm Laravel, có kinh nghiệm NodeJS\n- Thành thạo MySQL/PostgreSQL, Git, Docker\n- Có tư duy hệ thống, làm việc chủ động, phối hợp tốt\n- Ưu tiên: Biết DevOps (AWS, Nginx), bảo mật API, từng làm hệ thống lớn\n- Độ tuổi: 1994 - 1999\n\nWhy you\'ll love working here\n- Lương + thưởng dự án\n- Môi trường kỹ thuật mở, đề cao tư duy logic\n- Cơ hội lên Tech Lead/Core Team\n- Làm việc linh hoạt, hỗ trợ tài liệu & thiết bị', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '112/10 KDC Vạn Phúc, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1057, 613, 2, 'Mid/Sr Automation Test (Python,  QA QC, Tester)', 'ABOUT US\nFloware is a leader in building innovative software to transform the way people live, play, work, and learn. Our mission is to create smart solutions that benefit everyone and solve their daily challenges. We were the first in Vietnam to develop an iOS app and our first OS X application SmartDay debuted on the Mac App Store at #5.\nLocation: Ho Van Hue Street, Phu Nhuan District, HCMC\nOffice hour: Monday – Friday (8:30 AM – 5:30 PM)\nWHAT YOU’LL DO\n• Work closely with the development team (Backend, Frontend, DevOps, R&D, Technical Director, PM) to collaborate, understand the product requirements and knowledge clearly and accurately.\n• Perform testing phases including Dev, QA, and Staging environments.\n• Design, develop, and maintain automated test scripts for API testing using the Postman tool with an existing Python framework.\n• Collaborate with cross-functional teams to understand API specifications and design efficient and comprehensive test cases.\n• Design, develop, and maintain automated test scripts for Functional and Sync UI testing for crossed-platforms (Mac, Web, iPhone, iPad) using the existing Python framework.\n• Integrate automated tests into the CI/CD nightly pipeline and the instant execution for efficient testing processes.\n• Monitor and analyze test results, investigate failures, and provide feedback to the development team.\n• Report daily to the Team Leader and Technical Director about problems/issues/risks at the Backend side.\n• Document working efforts on Confluence to provide feedback, evidence, and a further improvement in the team.\n• Take the main responsibility for your own assignment and provide improvements for the product quality.\n• Participate in client meetings to discuss and agree on the automation testing approach and follow it up in new automation test opportunities.\nYOUR SKILLS AND EXPERIENCE\nWHO YOU ARE\n• At least 2 years in automation testing and ensuring product quality.\n• Hands-on experience with a programming language such as Python.\n• Experience in API automation testing (Python, Java, JMeter, Postman, etc.)\n• Experience in Mobile automation testing (Python, Java, Appium, iOS, Android, etc.)\n• Experience in Web automation testing (Python, Java, Selenium, Chrome, Firefox, Safari, Headless, etc.)\n• Experience in CI/CD process (Github, Jenkins, Gitlab CI, nightly run, etc.)\n• Experience in Performance and Security testing is a plus.\n• Have strong analytical and problem-solving skills.\n• Have a proactive and good work relationship with other team members.\nWHY FLOWARE\nWe challenge ourselves every day to find better solutions and better ways to do things. We ask difficult questions and work together to solve them. We believe in doing the right things as well as doing things right. We value honesty, hard work, integrity, and transparency. We are committed to transforming people’s lives, will you join us today?\nCOMPENSATION & BENEFITS\n• 100% salary during probation period\n• Full income tax, insurance paid by company (Net Salary)\n• 13th month of salary\n• Premium Health Insurance Package\n• Performance bonus up to 96 million dong or more in the year\n• Free office lunch, fruit, coffee, tea, snack bar everyday\n• Friendly, flexible, and fun working environment\n• Very attractive salary based on skills and experience\n• Monthly team activity allowance\n• Great opportunity for career development\n• Company trip, team building, monthly party, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '43 Hồ Văn Huê, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1058, 510, 2, 'AI Engineer', 'Top 3 reasons to join us\n1. Sự nghiệp thăng tiến không giới hạn\n2. Dự án công nghệ trong và ngoài nước\n3. Thu nhập hấp dẫn, đãi ngộ toàn diện\n\nJob description\n- Tham gia phát triển các sản phẩm nội bộ về Chatbot, CV, OCR, Voice2Text ... bằng ứng dụng AI từ các kỹ thuật ML, DL, Transformer, LLM/ Prompt/ Multi agent.\n- Đảm bảo chất lượng dữ liệu, kết quả mô hình, báo cáo định kỳ tự động.\n- Chịu trách nhiệm bảo trì, cải thiện, làm sạch và thao tác dữ liệu, khắc phục các sự cố tồn tại.\n- Thiết kế API giao tiếp với các hệ thống nội bộ, hợp tác với các nhóm khác để tích hợp giải pháp xây dựng sản phẩm hoàn thiện.\n- Đóng gói và triển khai trên môi trường Product với docker và docker-compose.\n- Xây dựng các tài liệu Thiết kế tổng thể, giải pháp, Thiết kế chi tiết, tài liệu Giám sát, theo quy trình DS/AI.\n\nYour skills and experience\n- Có kinh nghiệm từ 1 năm trở lên với vị trí tương đương\n- Tốt nghiệp ĐH chuyên ngành: Khoa học dữ liệu, Khoa học máy tính, CNTT, Toán học ứng dụng, Điện tử viễn thông hoặc chuyên ngành khác liên quan.\n- Kiến thức về lập trình, cấu trúc dữ liệu và giải thuật, lý thuyết đồ thị.\n- Kiến thức về xác suất thống kê, đại số tuyến tính, giải tích.\n- Kiến thức về các loại CSDL (RDBMS, Graph Databases, NoSQL Products, ...).\n- Kiến thức về học máy (Machine Learning), học sâu (Deep Learning), về xử lý ngôn ngữ tự nhiên (NLP), xử lý hình ảnh;\n- Sử dụng thành thạo một trong các thư viện học máy: Scikit-learn, TensorFlow, Keras, PyTorch;\n- Kỹ năng lập trình thành thạo Python, SQL.\n- Kỹ năng đọc bài báo khoa học và lập trình lại các thuật toán, giải pháp đề xuất trong bài báo khoa học.\n- Kỹ năng trực quan hóa dữ liệu.\n- Kỹ năng triển khai với các nền tảng containerization (Docker, Kubernetes) là một điểm cộng.\n- Kỹ năng với các nhiệm vụ trong NLP: conversational AI, information extraction, text summarization, text completion, sentiment analysis,...\n- Kỹ năng với các nhiệm vụ trong LLM: LangChain, vector embeddings, NLTK, GPT-3, GPT-4, ChatGPT, Claude, Mistral, LLaMA, spaCy, Stanford CoreNLP, word2vec, Alpaca , FastText, BERT, VectorDB, BERT, LLM/Prompt, LangGraph\n- Có kinh nghiệm làm việc với các thư viện python: numpy, matplotlib/seaborn, pandas, scikit learn, Jupyter notebook, v.v.\n- Có kinh nghiệm trong xây dựng kiến trúc, phát triển, triển khai các giải pháp phân tích dữ liệu là một điểm cộng.\n\nWhy you\'ll love working here\n1. Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh thỏa thuận theo kinh nghiệm và năng lực.\n- Lương tháng 13, Thưởng quý, Thưởng dự án, Thưởng năng suất.\n- Nghỉ mát, thưởng ngày lễ và các ngày chỉ có ở Viettel như Ngày Sáng Tạo - 1/6, 22/12, quà Tết Dương, Tết Âm  tri ân Gia đình, người sinh thành (25-30 triệu/năm)\n- 16 ngày nghỉ phép/năm hưởng nguyên lương\n- Bảo hiểm sức khỏe , bảo hiểm sức khỏe cho người thân, bảo hiểm nhân thọ,…\n- Hưởng các Chính sách đãi ngộ toàn diện của "Người Viettel"\n\n2. Cơ hội phát triển bản thân\n- Cơ hội thăng tiến không giới hạn, trở thành quản lý của các dự án mới\n- Được thử sức với các công nghêm mới, dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội được đào tạo, trau dồi kĩ năng, chuyên môn để phát triển toàn diện.\n\n3. Môi trường làm việc\n- Được làm việc trong Tập đoàn toàn cầu, tiên phong thực hiện sứ mệnh kiến tạo xã hội số.\n- Môi trường mở, trẻ trung, năng động, trân trọng, yêu thương, tương hỗ & lắng nghe mỗi người từ những ý tưởng nhỏ nhất.\n- Không gian làm việc xanh, mở, hiện đại.\n\n4.Địa điểm làm việc\n- Địa điểm: 36A Dịch Vọng Hậu, Cầu Giấy, Hà Nội\n- Thời gian làm việc: Thứ 2 đến thứ 6', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '36A Dịch Vọng Hậu, Cầu Giấy, Hà Nội, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1059, 637, 2, 'Frontend Developer (ReactJS, NextJS, JavaScript)', 'Glohow helps businesses go global. Our solutions and services include co-publishing of mobile games and applications, strategy consultation, marketing, PR, product development, project management, LiveOps management, localization, media content production, design, and arts.\n\nAs our business continues to thrive, we are currently seeking a skilled Frontend Developer to design and build high-quality, scalable components while ensuring seamless user interactions. In this role, you will collaborate with cross-functional teams to deliver intuitive, efficient, and secure web applications and contribute to the development of a scalable and reliable platform.\n\nWith our company growing rapidly, we’re actively expanding our team to meet increasing business demands. This ongoing hiring effort is a testament to our strong growth, exciting new projects, and commitment to investing in top talent.\n\nResponsibilities\n- Design and implement high-quality, scalable components with complex workflows.\n- Integrate and maintain microservices within the existing system, ensuring their quality and availability.\n- Collaborate closely with UI/UX designers, product owners, QA engineers, and backend developers to deliver polished applications.\n- Participate in all phases of the development lifecycle, including planning, estimating, building, and maintaining applications.\n\nYour skills and experience\n- 4+ years of experience in Frontend and Web Development, with at least 2 years of expertise in React.js development.\n- Strong knowledge of React.js and Next.js, including adherence to Next.js code conventions.\n- A passion for writing clean, maintainable, and high-quality code.\n- Proficient in tuning web client security and performance, such as optimizing HTML performance and handling JavaScript/React.js errors.\n- Solid experience in implementing Authentication & Authorization workflows in Single Page Applications (SPAs).\n- Expertise in creating intuitive and user-friendly interfaces by applying UI/UX best practices.\n- Experience with WebSockets or pub/sub technologies for real-time communication.\n- Proficiency in using version control systems like Git.\n- Ability to collaborate effectively with cross-functional teams using English.\n- Familiarity with Agile software development methodologies.\n- A Bachelor’s degree in Computer Science or a related field.\n\nPreferred Skills\n- Experience with Docker for managing different environments.\n- Familiarity with Node.js and server-side development.\n- Exposure to AI integration within CMS systems.\n\nWhy you\'ll love working here\n- The perks of working with us!\n  - Free training prior to the work\n  - Five-day work week 09:00 am to 06:00 pm\n- When your life works, Your work works!\n  - Birthday Leave\n  - TGIS (Thank God It\'s Six Hours Today!)\n  - Annual leave\n- Happiness comes first, let\'s enjoy our treats!\n  - Company Trip (Playshop)\n  - Cafe/Snack Bar\n  - Festival/ Birthday Event\n- Because your good health is our secret weapon!\n  - Annual Health Check-up\n  - Health Insurance\n  - Sick Leave\n\nWork at Glohow:\n- Global Working Environment\n  - Constantly learning and growing in the global working environment, you are encouraged to experience different areas of business across various countries.\n- Diversity\n  - Work with an open mindset and allow people to share their ideas to develop a multinational and multicultural organization that respects diverse ideas to accomplish the final result.\n- Specialty Improvement\n  - With the diversity, individuality, and charm of every member of Glohow, our warm working culture encourages all members to grow and improve. Every member has their own specialty and skillset - so we call each other by our names, not by our positions or levels.\n\nDon\'t hesitate and let\'s get global together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, Số 12 + 12 BIS, Trần Quang Khải, Phường Tân Định, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1060, 637, 2, 'Project Manager (EN Speaking)', 'Glohow is a global game business partner who is dedicated to shining a spotlight on various contents and bringing their businesses to a global level. Our solutions and services include co-publishing of mobile games and applications, strategy consultation, marketing, PR, product development, project management, LiveOps management, localization, media content production, design, and arts.\n\nAs our business continues to thrive, we are looking for a Project Manager with strong potential to grow into a product-oriented role.\n\nThis position goes beyond simply managing schedules and tasks. Initially, you will collaborate closely with design, development, and operations teams to manage project timelines and execution. Over time, as your understanding of the platform deepens, you will gradually take part in product planning and strategic discussions.\n\nThis role is designed with a long-term growth path toward becoming a Product Planner or Product Manager.\n\nKey Responsibilities\n- Manage project schedules and milestones in close collaboration with the design and development teams.\n- Lead weekly check-ins, track issues, and manage priorities to ensure smooth project progress.\n- Actively participate in product-related meetings to build a strong understanding of platform structure and goals.\n- Use collaboration tools such as ClickUp and Notion to document requirements, schedules, and feedback.\n- Support early-stage planning tasks such as writing user scenarios and defining product requirements.\n\nGrowth Path\n- Begin with project execution responsibilities.\n- Gradually participate in product and design discussions and take ownership of specific product areas and contribute to feature proposals.\n\nYour skills and experience\n- 1–3 years of experience as a Project Manager or in a similar role.\n- Strong communication skills and structured thinking.\n- A proactive mindset with genuine interest in understanding user and product challenges.\n- Able to communicate effectively in English (spoken and written).\n\nPreferred Qualifications\n- Experience in SaaS or platform-based services.\n- Exposure to product planning, QA, or UX research.\n- Experience working in multicultural or cross-functional teams.\n\nWhy you\'ll love working here\n- The perks of working with us!\n  - Free training prior to the work\n  - Five-day work week 09:00 am. to 06:00 pm\n- When your life works, Your work works!\n  - Birthday Leave\n  - TGIS (Thank God It\'s Six Hours Today!)\n  - Annual leave\n- Happiness comes first, let\'s enjoy our treats!\n  - Company Trip (Playshop)\n  - Cafe/Snack Bar\n  - Festival/ Birthday Event\n- Because your good health is our secret weapon!\n  - Annual Health Check-up\n  - Health Insurance\n  - Sick Leave\n\nWork at Glohow\n- Global Working Environment\n  - Constantly learning and growing in the global working environment, you are encouraged to experience different areas of business across various countries.\n- Diversity\n  - Work with an open mindset and allow people to share their ideas to develop a multinational and multicultural organization that respects diverse ideas to accomplish the final result.\n- Specialty Improvement\n  - With the diversity, individuality, and charm of every member of Glohow, our warm working culture encourages all members to grow and improve. Every member has their own specialty and skillset - so we call each other by our names, not by our positions or levels.\n\nDon\'t hesitate and let\'s get global together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, Số 12 + 12 BIS, Trần Quang Khải, Phường Tân Định, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1061, 465, 2, 'Software QC Engineer (Automation, Manual)', 'Position Summary:\n\nDesign, maintain automation framework and develop automation’s test cases using Selenium Java.\n\nResponsibilities:\n\nComplete assigned tasks from your direct superior on time.\nDetermine test objectives through detailed analysis in order to automate features comprehensively.\nDevelop, plan and implement automated test cases based on software requirements and technical understanding.\nDevelop and extend the current test automation infrastructure to be more efficient, both in execution and in reporting.\nRun tests (including manual test or automation test or both) against AUT builds/releases during its development lifecycle.\nPerform manual testing upon request for simple feature.\nCreate bug reports into Bug Tracking system and follow bug life cycle.\nReport testing status and test results (daily or/and weekly) to superior (Project Leader or Direct Manager) accurately and in a timely manner.\nSupport, mentor or coach members in automation skills.\n\nYour skills and experience\n\nSkills & Qualifications:\n\nDegree in IT/Computer Science/Computer Engineering or related discipline.\nProgramming skill is a MUST (Java).\n2+ years in development or automated testing, writing test cases, executing test cases.\n1+ years experience with enterprise automation tools or opened-source tools (Selenium is preferred).\nExperience with Version Control (SVN,GIT), CI/CD system (Jenkin).\nInterpersonal and communications skills, both oral and written.\nAble to work in a dynamic and ever-changing industry.\nGood English written and verbal communication skills are preferred.\nLogical thinking, detail-oriented, willing to take challenges.\nBe able to work in a fast-paced environment.\n1+ years experience in manual testing across various test types (API, Functional, UI, Acceptance, etc.).\nHave good knowledge of testing methodologies & techniques and the defect reporting process.\nExperience with bug-tracking systems such as JIRA.\nProblem Solving skill, Issue escalation skill, Time management skill.\n\nWhy you\'ll love working here\n\nBenefits:\n\nAttractive compensation, regular assessments, and salary reviews;\n13th-month salary and annual bonus;\n20 days annual leave;\n100% salary during the probation period;\n100% social insurance, premium healthcare insurance, and annual routine check-up;\nUnlimited access to a selection of food and beverages;\nSpecial celebrations on 8/3, Father\'s day, 20/10, Christmas, Tet holiday, etc.;\nCompany activities: annual teambuilding, New Year party, quarterly company party, weekly fruits day, monthly birthday, etc.;\nSports activities: badminton, football, bowling, cycling, etc.;\nIn-house acoustic music band;\nCinema days with blockbuster movies.\n\nProjects & Team:\n\nInternational working environment with a young, friendly, dynamic team, and creative;\nFlat organizational structure;\nCompany sponsors overseas in-class training and online training courses.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '20 Sông Thao, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1062, 279, 2, 'Project Manager (Odoo, ERP)', 'Chúng tôi đang tìm kiếm một Quản lý Dự án Odoo ERP kinh nghiệm và nhiệt huyết để dẫn dắt việc triển khai hệ thống Odoo ERP cho doanh nghiệp vận hành công viên giải trí quy mô lớn, Đô thị Du lịch hàng đầu Đông Nam Á. Với hệ thống chuỗi cung ứng du lịch, dịch vụ, nghỉ dưỡng, giáo dục, khoa học công nghệ và đô thị thông minh hàng đầu, rộng gần 400ha, vốn đầu tư lên đến 3,5 tỷ đô.\n\nQuản lý toàn bộ dự án triển khai hệ thống Odoo ERP từ giai đoạn khảo sát, thiết kế giải pháp, triển khai, đào tạo, kiểm thử đến khi vận hành chính thức (Go-live). Đảm bảo dự án được thực hiện đúng tiến độ, đúng phạm vi và ngân sách, phù hợp với định hướng chiến lược và mô hình kinh doanh đặc thù của tổ hợp giải trí – du lịch – bán lẻ.\n\nNhiệm vụ chính:\n- Quản lý dự án tổng thể: Lập kế hoạch, tổ chức, điều phối và giám sát tiến độ triển khai Odoo ERP (bao gồm các phân hệ như Bán hàng, CRM, Kho, Mua hàng, Kế toán, Nhân sự, POS, Resort, Vé tham quan...).\n- Phối hợp với các phòng ban: Làm việc chặt chẽ với các khối kinh doanh như công viên giải trí, khách sạn – resort, nhà hàng, bán lẻ, phòng vé, nhân sự, kế toán... để thu thập yêu cầu nghiệp vụ, chuẩn hóa quy trình và đảm bảo tính ứng dụng thực tiễn của hệ thống.\n- Quản lý nhà cung cấp: Làm việc với đối tác triển khai Odoo, giám sát chất lượng dịch vụ, đảm bảo đối tác thực hiện đúng cam kết và tiến độ.\n- Kiểm soát rủi ro và thay đổi: Theo dõi rủi ro dự án, đánh giá tác động của các thay đổi và đề xuất giải pháp xử lý kịp thời.\n- Đảm bảo chất lượng triển khai: Giám sát việc kiểm thử (UAT), đào tạo người dùng cuối và chuyển giao tài liệu hướng dẫn sử dụng hệ thống.\n- Báo cáo & truyền thông dự án: Cập nhật tiến độ và tình trạng dự án định kỳ cho Ban Giám đốc; xây dựng và duy trì truyền thông nội bộ giúp tăng mức độ đồng thuận và chấp nhận thay đổi.\n\nYour skills and experience:\n- Tốt nghiệp đại học chuyên ngành CNTT, Hệ thống thông tin quản lý, Kinh tế, Quản trị kinh doanh hoặc tương đương.\n- Có tối thiểu 3 năm kinh nghiệm quản lý triển khai ERP (ưu tiên Odoo).\n- Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực du lịch, giải trí, khách sạn, F&B học bán lẻ.\n- Có kiến thức tốt về quản lý dự án theo phương pháp Waterfall, Agile là lợi thế.\n- Kỹ năng giao tiếp, điều phối và quản lý xung đột tốt.\n- Có tư duy hệ thống, khả năng phân tích và giải quyết vấn đề nhanh chóng.\n- Thành thạo tiếng Anh là một điểm cộng.\n\nWhy you\'ll love working here:\n- Mức lương cạnh tranh, thưởng theo kết quả dự án.\n- Môi trường làm việc năng động, sáng tạo trong lĩnh vực du lịch – giải trí.\n- Cơ hội tham gia các dự án chuyển đổi số quy mó lớn.\n- Xe ca đưa rước ở Hồ Kỳ Hòa hoặc hỗ trợ nhà ở cộng đồng nếu ở lại công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '120 Xa lộ Hà Nội, Phường Tân Phú, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1063, 613, 2, '[Sign-on bonus] Senior Backend Developer (NodeJS)', 'ABOUT US  Floware is a leader in building innovative software to transform the way people live, play, work, and learn. Our mission is to create smart solutions that benefit everyone and solve their daily challenges. We were the first in Vietnam to develop an iOS app and our first OS X application SmartDay debuted on the Mac App Store at #5.  • Location: Ho Van Hue Street, Phu Nhuan District, HCMC  • Office hour: Monday – Friday (8:30 AM – 5:30 PM)  Job Description  The Senior Backend Engineer (SBE) designs complex backend technology solutions, develops code, and tests and maintains new and existing systems. As part of Floware’s Infrastructure & Security team, he partners closely with development teams to define scope and requirements for reusable services with integration services and APIs, and to use appropriate technology solutions for the business. The BE is a key member of the team responsible for delivering robust solutions while defining backend standards for all development teams at Floware VN.  Your skills and experience  WHO YOU ARE  • 3+ years of experience designing, developing, and managing RESTful APIs.  • 3+ years of experience developing in NodeJS.  • Demonstrated design and programming skills using NodeJS, JSON, Web Services, XML, XSLT, etc.  • Excellent experience in designing and implementing database systems with integrity, scalability, performance, reliability, security in mind.  HUGE PLUS IF YOU ARE/HAVE  • Excellent fullstack developer.  • Excellent understanding of backend development best practices and standards.  • Impeccable leadership skills and able to drive solutions.  • Excellent understanding of CI/CD.  • Excellent experience designing and developing backend microservices.  Why you\'ll love working here  WHY FLOWARE  We challenge ourselves every day to find better solutions and better ways to do things. We ask difficult questions and work together to solve them. We believe in doing the right things as well as doing things right. We value honesty, hard work, integrity, and transparency. We are committed to transforming people’s lives, will you join us today?  COMPENSATION & BENEFITS  • 100% salary during probation period  • Full income tax, insurance paid by company (Net Salary)  • 13th month of salary  • Premium Health Insurance Package  • Performance bonus up to 96 million dong or more in the year  • Free office lunch, fruit, coffee, tea, snack bar everyday  • Friendly, flexible, and fun working environment  • Very attractive salary based on skills and experience  • Monthly team activity allowance  • Great opportunity for career development  • Company trip, team building, monthly party, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '43 Hồ Văn Huê, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1064, 638, 2, 'Business Analyst', 'Job description\n- Thu thập, phân tích và làm rõ yêu cầu kinh doanh từ các phòng ban\n- Nghiên cứu thị trường, xu hướng sản phẩm, đối thủ cạnh tranh và hành vi người tiêu dùng\n- Đề xuất giải pháp cải tiến quy trình kinh doanh, hệ thống quản lý đơn hàng, và sản phẩm\n- Theo dõi hiệu quả triển khai các thay đổi và đưa ra báo cáo phân tích kết quả\n- Làm việc chặt chẽ với các đối tác để đảm bảo quy trình vận hành trơn tru\n\nYour skills and experience\n- Ưu tiên ứng viên có từ 01 năm kinh nghiệm ở vị trí tương đương\n- Ứng viên có hiểu biết về TMĐT, Dropshipping, công nghệ\n- Thành thạo tin học văn phòng (Word, Excel, PowerPoint)\n- Kỹ năng phân tích vấn đề, tư duy logic và khả năng đưa ra giải pháp thực tế\n- Giao tiếp tốt, linh hoạt, làm việc nhóm hiệu quả\n- Tiếng Anh đọc hiểu, giao tiếp cơ bản\n\nWhy you\'ll love working here\n- Mức lương thỏa thuận theo năng lực\n- Thưởng hoa hồng theo doanh thu tháng\n- Thưởng lễ, tết, lương tháng 13 và thưởng theo năng lực hằng tháng\n- Hưởng đầy đủ các chế độ BHXH, BHYT, BHTN theo Luật lao động\n- Môi trường làm việc trẻ trung, năng động, sáng tạo', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '345 Hoàng Thị Loan, Lien Chieu, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1065, 639, 2, 'Senior Web Developer (PHP/Python/JavaScript)', 'About us:\nrakumo Co., Ltd is a 100% Japanese-owned company, specializing in web design, web applications, and mobile applications for the Japanese market—one of the most demanding and quality-focused markets in the world.\nUnlike many offshore companies with repetitive tasks, rakumo offers a professional, collaborative, and technology-driven working environment where you will:\nWork directly with experienced Japanese experts\nApply and explore cutting-edge technologies\nGrow your career with clear development paths\n\nOur Mission\nBuild a cooperative and professional workplace together\nInspire passion and excitement in every working day\nTurn your dreams and our shared vision into reality\n\nIf you\'re a developer who loves challenges, solves problems logically, and constantly seeks growth—rakumo is the place for you.\n\nJob Description:\nYou will be responsible for:\nAnalyzing system requirements and proposing suitable technical solutions\nDesigning and developing high-performance web applications\nWorking closely with the QA/QC team to ensure top-notch product quality\nInvestigating bugs, improving system performance, and providing technical support when needed.\n\nYour skills and experience\nMust have\nBachelor\'s degree in Computer Science or related field\n3–5 years of experience in web development using at least one backend language: Python / PHP / Ruby / Java / .NET\nStrong knowledge of JavaScript (including jQuery and vanilla JS)\nExperience with modern JavaScript frameworks such as React.js, Angular.js, or similar\nSolid understanding of database design and normalization up to 3NF\nStrong logical thinking and problem-solving skills\nEagerness to learn and quickly apply new technologies\n\nNice to have:\nExperience with Google Cloud Platform (GCP) or Amazon Web Services (AWS)\nFamiliarity with Git and version control workflows\nA good sense of design and understanding of UX/UI principles\n\nWhy you\'ll love working here\nCompetitive salary with regular reviews\nPerformance-based bonuses and holiday incentives\nA professional, international working environment focused on growth\nSupportive team culture and open communication\nTeam-building events, technical workshops, and learning sessions\nOpportunities to work directly with Japanese experts and contribute to real-world projects for top-tier clients in Japan\nHoliday (30/4, 2/9), Year-end..\n13th-month salary before Tet.\nPVI premium health insurance\nAnnual company trip, team building, picnic programs & happy hour monthly\n12 days annual leave (14 days for female) + 1 day “rakumo day” + 1 day your birthday\nMon – Fri (8a.m-5.30p.m).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa, Etown 1, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1066, 469, 2, 'Middle QC Engineer (QA QC/ERP)', 'As a Middle QC Engineer, you will play a vital role in maintaining and improving our product quality. You will collaborate closely with both junior and senior team members, guiding junior QC engineers and contributing to a high-performing QA team. Your expertise will help us implement and execute robust test strategies while optimizing our QA/QC practices.\n1. Quality Control Process:\n- Focus on the quality control of the in-house FFM and WMS systems.\n- Collaborate with Product Owners and Developers to understand and resolve tasks.\n- Integrate implemented features with developers and ensure timely task completion.\n- Document tasks thoroughly, including test reports\n\nRate of expectations from 90 to 100%.\n\n2. Team Building:\n- Guide and mentor Junior QC Engineers to enhance their skills and performance.\n- Foster a high-performing team environment with measurable performance indicators, achieving team growth\n\nRate of expectations from 80-90%.\n\n3. Skill Development:\n- Actively pursue knowledge and skills for career advancement.\n- Improve productivity and suggest ideas for task completion and system enhancements.\n- Assist in importing and organizing test cases into a test management platform (e.g.,TestRail) to facilitate future automation processes\n\nRate of expectations from 80-90%.\n\nYour skills and experience:\n- At least 3 years of experience in QA/QC experience with a minimum of 2 years experience in E-commerce and ERP is preferred.\n- Strong analytical skills for requirements and problem analysis.\n- Ability to read and create test plans, test data, test cases, checklists, and release notes.\n- Familiarity with Jira and Confluence or any test management tools.\n- Experience with UI, API, and database testing.\n- Basic knowledge of automation testing; capable of setting up and converting test cases.\n- Results-oriented with a focus on decision-making and problem-solving.\n- Innovative and creative with a continuous improvement mindset.\n- Proactive and self-motivated; able to manage conflicts and negotiate effectively.\n- Strong stakeholder management, influence, and persuasion skills.\n- Excellent organizational skills, integrity, and the ability to remain calm under pressure.\n\nWhy you\'ll love working here:\n- Salary: Upto 28,000,000 (Gross)\n- 100% official salary during the probation period\n- Premium health care insurance and annual health check-ups.\n- All benefits followed Vietnamese labor law, including a 13th-month salary plus a competitive bonus.\n- Bonding money per quarter\n- Annual company trip and team building\n- Weekly Happy Lunch on Friday\n- Bonuses and gifts for holidays, Tet such as Mid Autumn, Women’s day, etc\n- Dynamic and professional working environment.\n- A laptop – Macbook Pro and second monitor and devices (if any) that fit your needs.\n- Working from Monday to Friday (8.30 am – 5.30 pm)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Floor 5 - Jabes 1 Building, 244 Cống Quỳnh, Phạm Ngũ Lão Ward, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1067, 640, 2, 'Junior Front-End Developer (ReactJS/ HTML/ CSS)', 'Xây dựng phân hệ front-end (giao diện người dùng) các tính năng được yêu cầu từ team phát triển sản phẩm cũng như từ người dùng, cụ thể:\n- Tham gia vào việc phát triển sản phẩm của công ty\n- Bảo trì, nâng cấp cho front-end sản phẩm của công ty.\n- Nghiên cứu và áp dụng các công nghệ mới để tối đa hóa hiệu quả phát triển sản phẩm.\n- Phối hợp và hỗ trợ với team back-end một cách chủ động và chặt chẽ để nâng cao trải nghiệm người dùng trên từng điểm tiếp xúc.\n\nCÓ hiểu biết về lập trình hướng đối tượng.\nHiểu biết về HTML / CSS / Javascript/ Vuejs\nThành thạo ReactJS\nCó khả năng đọc hiểu tài liệu tiếng Anh.\nCó khả năng làm việc độc lập và theo nhóm.\nCẩn thận, kiên nhẫn và ham học hỏi.\nSử dụng laptop cá nhân.\n\nChế độ lương - thưởng: Mức lương cạnh tranh & hấp dẫn.\nĐánh giá năng lực, xem xét điều chỉnh lương 1 lần 1 năm.\nThời gian làm việc: Từ thứ 2 đến thứ 6, từ 8h30 - 17h30 ( Thứ 4 làm việc tại nhà )\nĐược hưởng đầy đủ chế độ phúc lợi: BHYT, BHXH, Du lịch, team building,...\nLàm việc trong môi trường trẻ trung năng động.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '143 Phạm Huy Thông, phường 6, Go Vap, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1068, 637, 2, 'Mid/Senior Backend Engineer (Java, Spring, English)', 'Location: Vietnam/ Full-time/ On site\n\nGlohow is a global game business partner who is dedicated to shining a spotlight on various contents and bringing their businesses to a global level.\n\nAs our business continues to thrive, we are currently seeking a seasoned Backend Developer to design and implement backend systems that power our in-house platforms and enable the company to scale.\n\nIn this role, you\'ll collaborate with cross-functional teams to develop new features, tackle complex technical challenges, and contribute to the development of a scalable and reliable platform.\n\nKindly cherish and value your individuality and ideas, your colors will glow and shine through our globalized mindset and workflow.\n\nResponsibilities:\n- Design, implement, and maintain backend systems that support the company\'s growth and scalability.\n- Collaborate closely with product managers and UX designers to define and refine feature specifications.\n- Debug and resolve complex issues, including performance bottlenecks, scale challenges, and bugs across the stack.\n- Troubleshoot and resolve issues such as stuck jobs in message queues or bugs in backend services.\n- Ensure the delivery of clean, high-quality, and maintainable code.\n\nYour skills and experience:\n- 4+ years of experience in Backend and Web Development, with 2+ years working with Java and Spring Framework.\n- Strong expertise in building and maintaining HTTP/RESTful APIs and object-oriented programming principles.\n- Hands-on experience with RDBMS and NoSQL databases (e.g., Elasticsearch, MongoDB).\n- Advanced knowledge of the Spring Framework and its modules, including Spring Data, Spring Security, Spring OAuth2, Spring AOP, and Spring Cloud.\n- Familiarity with microservices architecture and its application in CMS development.\n- Proficiency in working with both synchronous and asynchronous technologies.\n- Strong understanding of design patterns and their application in software architecture.\n- Solid experience with Git and version control systems.\n- Ability to collaborate effectively with cross-functional teams using English.\n- Familiarity with Agile software development methodologies.\n- Bachelor\'s degree in Computer Science or a related field.\n\nNice to have:\n- Experience with setting up and maintaining CI/CD pipelines.\n- Familiarity with Docker for managing development and production environments.\n- Previous experience in AI integration within CMS systems.\n\nWhy you\'ll love working here:\n- The perks of working with us!\n  - Five-day work week 09:00 am. to 06:00 pm\n- When your life works, Your work works!\n  - Birthday Leave\n  - TGIS (Thank God It\'s Six Hours Today!)\n  - Annual leave\n- Happiness comes first, let\'s enjoy our treats!\n  - Company Trip (Playshop)\n  - Cafe/Snack Bar\n  - Festival/ Birthday Event\n- Because your good health is our secret weapon!\n  - Annual Health Check-up\n  - Health Insurance\n  - Sick Leave\n\nWork at Glohow:\n- Global Working Environment\n  - Constantly learning and growing in the global working environment, you are encouraged to experience different areas of business across various countries.\n- Diversity\n  - Work with an open mindset and allow people to share their ideas to develop a multinational and multicultural organization that respects diverse ideas to accomplish the final result.\n- Specialty Improvement\n  - With the diversity, individuality, and charm of every member of Glohow, our warm working culture encourages all members to grow and improve. Every member has their own specialty and skillset - so we call each other by our names, not by our positions or levels.\n\nDon\'t hesitate and let\'s get global together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6, Số 12 + 12 BIS, Trần Quang Khải, Phường Tân Định, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1069, 209, 2, '[Healthcare] Senior Java Developer', 'A subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n\n- Design, develop, and maintain backend services using Java 17 and Spring Boot 3.x.\n- Implement RESTful APIs for data access and service communication.\n- Write complex SQL queries for Oracle 19c and ensure performance tuning.\n- Integrate with third-party APIs, Azure cognitive services, and PDF processing tools (e.g., PDFBox).\n- Develop cloud-native applications with containerization and deployment on Azure.\n- Implement CI/CD pipelines using GitHub Actions.\n- Collaborate with QA and frontend teams to deliver end-to-end features.\n\nYour skills and experience\n\n- 5+ years of backend development experience with Java and Spring Boot.\n- Proficiency in Java programming, including experience with Java 8 or higher. Familiarity with Java EE and microservices architecture.\n- Strong experience with Spring Boot, Spring Cloud, and Hibernate. Understanding of RESTful API development and SOAP web services.\n- Proficiency in Oracle SQL (medium to complex queries).\n- Experience with containerizing applications and deploying to Azure.\n- Familiar with GitHub Actions or similar CI/CD tools.\n\nPreferred:\n- Exposure to healthcare data workflows and enterprise analytics.\n- Experience working with PDFBox and data-driven application architecture.\n\nWhy you\'ll love working here\n\n- Performance-based bonuses up\n- FPT Care insurance plan tailored for FPT employees\n- Attractive annual summer vacation allowance\n- Sponsored training courses for personal growth and up to 100% coverage for certification costs\n- Global and inclusive workplace with monthly cross-cultural events\n- International exposure and career growth across global locations\n- Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Building, 17 Duy Tân Str., Cau Giay, Ha Noi; F-Town 3, 3 Võ Chí Công, Phường Long Thạnh Mỹ, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1070, 641, 2, 'Software Development Manager', 'About STYL Solutions:\nRide on the wave of Industry 4.0! Join STYL Solutions in the forefront of using Fintech and IoT technologies for smart city/nation transformation. Headquartered in Singapore with an R&D center in Vietnam, STYL Solutions designs, develops, and supplies hardware, software, and integrated solutions for applications in payment, loyalty management, location tracking, self-service operation, and telemetry. Our market segment coverage extends from financial services, retail, mass transit, and education to social services markets in Singapore and South Asia Pacific.\nOur vision is to use Fintech and IoT to create smart and efficient cities that enhance Quality of Life through convenience and healthier living.\nWe are seeking an experienced and visionary Software Development Manager to lead our dynamic development team. In this role, you will provide strategic leadership, ensure the timely delivery of high-quality software solutions, and foster a culture of collaboration and innovation. Your contributions will drive excellence in software development and help position our organization as a leader in the Fintech IoT industry.\nYour responsibilities will include, but are not limited to:\n1. Leadership and Team Development:\n- Define and communicate a strategic vision for software development teams, emphasizing Fintech IoT innovations.\n- Mentor team members, promoting skill enhancement and professional growth.\n- Recruit and develop top talent, creating a cohesive and high-performing team.\n- Foster a culture of innovation, accountability, and continuous improvement.\n\n2. Project and Resource Management:\n- Manage the entire project lifecycle—from initial planning to final delivery—ensuring timeliness and adherence to quality standards.\n- Optimize resource allocation to maximize productivity and project outcomes.\n- Identify and mitigate project risks proactively, addressing potential delays and technical challenges.\n- Manage and identify good software outsource/design houses.\n\n3. Collaboration and Communication:\n- Partner with key stakeholders to align development initiatives with business objectives and evolving industry trends.\n- Foster clear communication across internal teams and with external partners.\n- Work closely with Project Managers and Hardware teams to deliver secure, integrated solutions.\n\n4. Technical and Process Excellence:\n- Implement and advocate best practices in software development, such as agile methodologies, IoT-specific protocols, and CI/CD practices.\n- Promote code quality, testing standards, and continuous optimization of development processes.\n- Stay informed about emerging technologies and trends in IoT and Fintech, leveraging insights to drive innovation and competitiveness.\n\n5. Performance and Alignment:\n- Regularly evaluate team performance, providing constructive feedback and support to drive continuous improvement.\n- Ensure team efforts align with organizational goals and product roadmaps, balancing short-term deliverables with long-term priorities.\n\nYour skills and experience:\nHere at STYL Solutions, we encourage our employees to take initiative, propose ideas, and provide them with the opportunity to dive into multiple projects. We are looking for candidates who possess the following:\n- Demonstrated experience in a leadership role, managing software development teams in a fast-paced, product-driven IT environment.\n- Strong foundation in engineering best practices, system architecture, and software design.\n- Proven expertise in managing and delivering large-scale, complex software projects.\n- Proficiency in multiple programming languages (e.g., Java, Python, JavaScript, C++), cloud technologies, microservices architecture, and modern development frameworks.\n- Experience leading cross-functional teams and collaborating with product managers, designers, and stakeholders to deliver exceptional software products.\n- In-depth knowledge of Agile methodologies (e.g., Scrum, Kanban) and expertise in CI/CD, DevOps, and automated testing.\n- Excellent problem-solving, communication, and interpersonal skills, with the ability to lead technical discussions and influence decisions.\n- Commitment to fostering a positive, collaborative, and growth-oriented team environment.\n- Background in working within a product-focused company, especially with multiple product teams, is a significant advantage.\n- Bachelor’s or Master’s degree in Computer Science, Engineering, or a related field.\n\nWhy you\'ll love working here:\nSTYL Solutions will give you the favorable conditions you need to tackle difficult problems and learn cutting-edge technologies:\n- International working environment with friendly and passionate colleagues.\n- Onsite opportunity to Japan, and Singapore for training and supporting customer.\n- Meaningful work with experienced & strong technical veterans.\n- Flat structure, simple processes & transparency.\nIn addition to providing you with professional growth, STYL Solutions is also committed to taking care of our employees, personally. As a full-time employee, you are automatically enrolled in our benefits program, which includes:\n- Attractive compensation, regular assessments, and salary reviews;\n- Performance bonus;\n- 19 paid days off per year;\n- WFH 1 day per week*\n- 100% salary & full social insurance during probation period;\n- Premium health care insurance (PVI);\n- Free lunch, snacks, coffee and tea;\n- Special celebration on 8/3, 1/6, Xmas, Tet holiday...;\n- Outing/team-building activities (company trip, sport, dinner...)\n*Only apply to full-time employees meeting work conscientiousness criteria and maintaining remote productivity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '25-27, B4 Street, Sala Urban Area, District 2, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1071, 428, 2, 'Business Analyst Manager / BA Manager - Upto $5000', 'Top 3 reasons to join us\n• Competitive salary \n•  Premium health care package \n• 7 working hours/day\n\nJob description\nTeam Management & Leadership\n• Lead, mentor, and manage a team of IT Business Analysts, fostering a collaborative, growth-oriented and high-performing environment that encourages innovation and critical thinking. \n• Define team objectives, conduct performance reviews, and identify training and development needs. \n• Establish and maintain BA best practices, standards, and methodologies within the organization\n\nStakeholder & Requirement Management\n• Collaborate with business owners and product teams to understand strategic goals and identify business needs. \n• Oversee the elicitation, analysis, documentation, and management of business and technical requirements for various projects. Ensure requirements are clear, concise, testable, and aligned with business objectives and product vision \n• Analyze and document existing operational processes and identify areas for improvement. \n• Utilize various BA techniques such as user stories, use cases, process flows, mock-up and data models to effectively capture and communicate requirements. \n• Manage changes to requirements through a defined change control process. \n\nProduct Development\n• Actively participate in the product development lifecycle, providing BA expertise and insights. \n• Contribute to the definition of product roadmaps, features, and functionalities. \n• Support the planning and execution of product launch activities. Operation Support \n• Lead the investigation and analysis of production issues, working closely with technical teams to identify root causes and implement effective solutions.\n• Ensure timely communication and updates regarding production issues to relevant stakeholders. \n• Contribute to the development and maintenance of knowledge bases and troubleshooting guides. \n• Collaborate with operational teams to execute the operation activities, define and implement new processes and workflows.\n\nYour skills and experience\n• Bachelor’s degree or higher in Information Technology, Computer Science, or related field. Graduates from top universities or specialized gifted schools are highly preferred. \n• 8+ years of experience as a Business Analyst, including at least 3 years in a team leadership or managerial role. \n• Proficiency in tools such as Figma, Visio, Visual Paradigm for process modeling and mockups. \n• Hands-on experience with Jira, Confluence, and SQL for requirements and data analysis. \n• Strong understanding of the fintech industry and specific knowledge in one or more of the following areas: AI, Crypto, Blockchain technology, NFTs, and NFT Games; is an advantage. \n• Experience working in Agile environments; Scrum certification is an advantage. \n• Excellent analytical, problem-solving, and critical thinking skills. \n• Strong communication, interpersonal, and stakeholder management skills.\n• Ability to work independently and as part of a team in a fast-paced environment \n• Strong command of English (both verbal and written)\n\nWhy you\'ll love working here\nWhy Join Us?  \n• Lead AI-driven innovation in a fast-growing tech company.  \n• Work with a passionate team building cutting-edge AI solutions.  \n• Opportunity to shape the future of the AI engineering team at Blue Belt .  \n\nBenefits & Compensation  \n• Salary: Up to $5,000/month (100% offered during the probation period).  \n• Work Schedule: Monday – Friday (9:00 AM – 5:00 PM, with a lunch break from 12:00 PM – 1:00 PM).  \n• Performance-based Salary Reviews: Twice a year based on contributions and achievements.  \n• Modern Equipment: State-of-the-art tools and technologies provided for an efficient workflow.  \n\nComprehensive Insurance:\n• Full benefits as per the Labor Code.  \n• Premium PVI Health Insurance for all employees.  \n\nTransportation & Perks:  \n• Transportation allowance and free motorbike parking.  \n• Complimentary snacks, coffee, and tea.  \n• Other benefits as per stated in Vietnamese Labor Law\n\nLearning & Development:  \n• Annual technical seminars and workshops.  \n• Training programs and professional development opportunities.  \n\nCompany Culture & Events:  \n• Weekly tea breaks, monthly birthday celebrations, quarterly team-building activities.  \n• Annual company trips and year-end parties.  \n• A fast-paced, open, and collaborative work environment where every idea is valued.  \n\nJoin us and be a part of an innovative, cutting-edge technology company shaping the future of blockchain, AI, and decentralized solutions!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Level 3, The Loop Building, 241 Xuan Thuy, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1072, 310, 2, 'Senior Product Designer', 'We are seeking a versatile and innovative Senior Product Designer to join our team and contribute to our diverse AECO projects. In this hybrid role, you will use your design skills to ensure seamless, intuitive, and emotionally engaging interactions across complex systems such as Digital Twins, Mixed Reality platforms, and more. You will lead efforts to design and refine user journeys, build cohesive design systems, and create visually stunning, user-centered interfaces that elevate how our users interact with cutting-edge technologies.\n\nKey Responsibilities\nConduct user research, interviews, and usability testing to deeply understand user needs, behaviors, and pain points.\nMap user journeys, design personas, and create wireframes, storyboards, and flow diagrams to guide the development process.\nCollaborate with cross-functional teams to define and prioritize product features that enhance the overall user experience.\nAdvocate for the user throughout the design and development process, ensuring design decisions are driven by user insights and data.\nAnalyze and iterate on existing UX designs based on user feedback, analytics, and performance metrics.\nContribute to the creation, development, and maintenance of design systems, expressed through UI components such as layouts, fonts, colors, icons, animations, and micro-interactions.\nDesign highly legible, user-friendly, and aesthetically compelling interfaces that align with user needs and business goals.\nDevelop interactive prototypes to demonstrate innovative design concepts in real-time 3D environments, Digital Twins, Mixed Realities, and traditional UI formats.\nIncorporate animations and micro-interactions to create engaging and delightful user experiences.\n\nYour skills and experience\nEducation & Experience:\nBachelor’s degree in UX Design, UI Design, Interaction Design, Graphic Design, or a related field.\nProven experience in UX/UI design for digital products, particularly within AECO, Digital Twins, or 3D real-time environments.\nStrong portfolio showcasing both UX and UI design, including user journeys, design systems, and high-fidelity interfaces.\nSkills:\nExpertise in UX tools such as Figma, Adobe XD, Miro, and user testing platforms.\nProficiency in UI tools like Figma, Rive, Protopie, and familiarity with 3D and Mixed Reality platforms.\nStrong ability to translate research and user data into intuitive and engaging design solutions.\nExperience with animations, micro-interactions, and interactive prototypes to showcase advanced design concepts.\nAbility to balance technical constraints with creative expression, optimizing for both functionality and aesthetics.\nSoft Skills:\nExcellent communication and collaboration skills, with a track record of working effectively in multidisciplinary teams.\nStrong analytical and problem-solving skills, coupled with a user-first mindset.\nBonus Qualifications:\nExperience with coding (e.g., HTML, CSS, JavaScript) to better collaborate with developers.\nFamiliarity with tools like Unity or Unreal Engine for designing within 3D environments.\nDeep understanding of accessibility standards and inclusive design principles.\nWe accept working from both Ho Chi Minh City and Hanoi[Work from home]\n\nWhy you\'ll love working here\nWe provide our staff with:\n- Very attractive salaries that commensurate with work experience.\n- Have a chance to develop your career and access new IT technologies\n- Be able to have business trip in Singapore and meeting strategic partnership\n- Be supported and work with experienced and friendly member.\n- Professional and nice work environment.\n- Work from home.\n- Bonus based on your proficiency.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1073, 607, 2, 'Python Technical Leader (Smart Contract)', 'About GFT\nGFT is a global leader in digital transformation, offering innovative technology solutions across financial services, insurance, and manufacturing industries. We combine deep domain expertise with leading-edge technologies like cloud, blockchain, AI, and smart contracts to build scalable and future-ready systems for our clients. With a strong commitment to diversity, sustainability, and continuous innovation, GFT has been recognized as a Great Place to Work across multiple regions.\n\nRole Overview\nWe are looking for a Python Technical Lead (Smart Contract) to join our digital banking practice. In this role, you will be responsible for designing, developing, and leading the implementation of Smart Contracts. You will act as the technical owner for smart contract solutions, mentoring developers, collaborating with stakeholders, and driving high-quality delivery in complex environments.\n\nKey Responsibilities\n- Lead end-to-end smart contract architecture, development, testing, and deployment\n- Translate business requirements into scalable and maintainable smart contract designs\n- Collaborate with business analysts, product owners, and clients to define workflows and financial product logic\n- Review and approve designs, code, and testing strategies to ensure reliability and compliance with industry best practices\n- Manage CI/CD pipelines and DevOps processes for smart contract deployments\n- Troubleshoot and resolve issues in development, staging, and production environments (e.g., posting failures, schedule conflicts, interest miscalculations)\n- Mentor and guide a team of smart contract developers, conducting code reviews and setting quality standards\n- Own and manage technical delivery timelines, sprint planning, and risk mitigation across multiple client engagements\n- Coordinate closely with trainers for Thought Machine Smart Contract to gain hands-on experience and continuously enhance domain expertise.\n\nYour skills and experience\nRequired Skills & Experience\n- 10+ years of backend development experience, with 2+ years in Python (strong core Python expertise required)\n- 2+ years of hands-on experience developing smart contracts\n- Deep knowledge of Vault smart contract architecture, hooks, posting instructions, and version upgrades\n- Experience in designing and implementing complex financial products such as savings accounts, loans, credit cards, and schedules\n- Solid understanding of CI/CD pipelines, unit/integration/e2e testing, Git branching strategies (Git Flow, Trunk, GitHub Flow)\n- Proven experience leading agile teams, sprint planning, and backlog grooming\n- Familiarity with DevOps tools like GitHub, CircleCI, SonarQube, Artifactory, and monitoring/debugging tools\n- Knowledge of CQRS pattern and scalable microservices architecture\n- Ability to lead client-facing technical discussions, workshops, and requirement-gathering sessions\n- Ability to be on-site if required.\n\nNice to Have\n- Experience in retail banking or financial institutions, especially around accounting principles (e.g., double-entry bookkeeping)\n- Exposure to Vault workflows, Vault UI, or the product lifecycle of core banking systems\n- Thought Machine certification(s) or experience with Vault development environments.\n\n(Due to the high volume of applications we receive, we are unable to respond to every candidate individually. If you have not received a response from GFT regarding your application within 10 workdays, please consider that we have decided to proceed with other candidates. We truly appreciate your interest in GFT and thank you for your understanding.)\n\nWhy you\'ll love working here\nHR benefits\n- Competitive salary\n- Salary band per level are reviewed once per year\n- 13th month salary pro rata depending on the employee’s length of service (within a calendar year), paid with the December salary\n- Monthly lunch allowance: 700,000 VND/employee\n- Parking: GFT covers the monthly parking fee for employee motorbikes\n- Performance evaluation is once per year, for 2 purposes:\n > Performance bonus   > Salary increments\nHealth care\n- Private health insurance: including accident, outpatient, in-patient, maternity, and dental for all permanent employees who pass 2-month probation.\n- Optical: expense claim for eyewear\n- Annual health check-ups.\nVacation\n- Maximum 18-day vacation leave/year (with the ability to carry over 05 days till 31st March of the following year)\n- Adding one more annual leave day for each two-year anniversary.\nHealthy lifestyle\n- Sports and hobby clubs: company has an annual fund for fitness activities, which is allocated per month as team’s vote.\n- Range of healthy snacks, tea, coffee, milk and beer on tap.\nSocial\n- Company townhall: each 6 weeks\n- CSR activities: as per company’s CSR guideline\n- Onsite tour/training courses at other GFT offices and client’s destination overseas (where applicable).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '29A Nguyen Dinh Chieu, District 1, Ho Chi Minh; 174 Thai Ha, Dong Da, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1074, 642, 2, 'Co-founder kiêm Tech Lead (Ứng dụng Mobile AI)', 'Top 3 reasons to join us\n• Mức lương & phúc lợi hấp dẫn bạn sẽ yêu thích\n• Thưởng cổ phần ESOP cho sự nỗ lực và thành công\n• Môi trường làm việc thân thiện và sáng tạo\nJob description\n• Lãnh đạo đội ngũ kỹ thuật (~5 thành viên gồm Developer, QA, …): Quản lý công việc hàng ngày, định hướng mục tiêu và đảm bảo hiệu suất làm việc cao cũng như sự gắn kết của cả nhóm. \n• Định hướng công nghệ: Nghiên cứu, đề xuất và quyết định các giải pháp kỹ thuật; lựa chọn kiến trúc hệ thống và tech stack phù hợp với chiến lược sản phẩm (có thể gồm React Native, Flutter hoặc native iOS/Android). \n• Phát triển sản phẩm: Tham gia trực tiếp vào quá trình xây dựng ứng dụng di động tích hợp AI – từ thiết kế hệ thống, viết code, review code – đảm bảo sản phẩm ổn định, hiệu suất cao và có khả năng mở rộng. \n• Phối hợp chiến lược: Làm việc chặt chẽ với các nhà đồng sáng lập khác để định hình tầm nhìn và lộ trình sản phẩm, đảm bảo công nghệ phục vụ tốt cho mục tiêu kinh doanh. \n• Quản lý & đào tạo: Hỗ trợ tuyển dụng và đào tạo các thành viên kỹ thuật mới; xây dựng quy trình làm việc linh hoạt, thúc đẩy văn hóa học hỏi và sáng tạo trong nhóm kỹ thuật.\nYour skills and experience\n• Kinh nghiệm kỹ thuật: Có kinh nghiệm vững vàng trong phát triển ứng dụng di động. \n• Thành thạo một hoặc nhiều framework/nền tảng như React Native, Flutter, iOS/Android. \n• Ưu tiên ứng viên từng thiết kế kiến trúc hệ thống hoặc dẫn dắt kỹ thuật trong các dự án thực tế. \n• Kiến thức AI: Hiểu biết về tích hợp AI/Machine Learning vào ứng dụng (thông qua API, thư viện AI, v.v.) là một lợi thế lớn. \n• Kỹ năng lãnh đạo: Từng giữ vai trò Tech Lead/Team Lead hoặc vị trí quản lý kỹ thuật tương đương. \n• Có khả năng dẫn dắt, truyền cảm hứng và nâng cao năng lực cho đội ngũ kỹ sư.\n• Tinh thần startup: Đam mê khởi nghiệp, làm việc với tinh thần “đồng sáng lập” – chủ động, sáng tạo, trách nhiệm cao – không giới hạn trong mô tả công việc cố định. \n• Sẵn sàng đảm nhiệm nhiều vai trò khác nhau khi cần để đạt mục tiêu chung. \n• Ưu tiên: Ứng viên đã từng tham gia hoặc đồng sáng lập startup, hiểu rõ những thách thức và cách vận hành ở giai đoạn đầu. \n• Địa điểm: Sẵn sàng làm việc full-time, onsite tại Hà Nội (Quận Nam Từ Liêm). \n• Ngôn ngữ: Không yêu cầu tiếng Anh (làm việc trong môi trường tiếng Việt).\nWhy you\'ll love working here\n• Vai trò đồng sáng lập: Đóng vai trò như một nhà đồng sáng lập thực thụ của công ty. Bạn sẽ có tiếng nói quan trọng trong các quyết định sản phẩm và công nghệ, được tự chủ cao trong công việc và cùng chia sẻ thành công của startup. \n• Chế độ đãi ngộ: Không có lương cố định ban đầu; thay vào đó, bạn sẽ nhận 3% doanh thu quảng cáo của sản phẩm (sau khi trừ chi phí máy chủ AI). Gói thưởng theo doanh thu này phản ánh sự trân trọng đóng góp của bạn và mang lại tiềm năng thu nhập rất cao khi sản phẩm phát triển. \n• Cổ phần & tương lai: Cơ hội nắm giữ cổ phần công ty hoặc tăng tỷ lệ lợi ích trong tương lai. Khi startup gọi vốn thành công hoặc đạt doanh thu ổn định, cơ chế lương thưởng sẽ được xem xét lại một cách tương xứng. \n• Môi trường startup: Làm việc trong môi trường startup Việt Nam năng động, cởi mở, đề cao văn hóa học hỏi – sáng tạo – trách nhiệm. Được khuyến khích thử nghiệm ý tưởng mới, dám nghĩ dám làm và học hỏi từ cả thành công lẫn thất bại. \n• Thử thách & phát triển: Tham gia từ giai đoạn khởi đầu giúp bạn trải nghiệm việc xây dựng sản phẩm từ con số 0. Cơ hội phát triển bản thân lên vị trí CTO trong tương lai, tích lũy kinh nghiệm khởi nghiệp quý báu và mở rộng network trong cộng đồng công nghệ. \n• Đội ngũ đam mê: Cùng làm việc với những đồng đội trẻ trung, tài năng và nhiệt huyết. Mọi ý kiến sáng kiến của bạn đều được lắng nghe và coi trọng, cùng nhau tạo ra sản phẩm có giá trị thực sự cho người dùng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tòa Viwaseen, 48 Tố Hữu, Nam Tu Liem, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1075, 239, 2, 'Automation Test (Tester/QA QC/Selenium/Java/Appium)', 'Top 3 reasons to join us\n- Committed 13th-mth bonus + attractive yearly bonus\n- Premium Healthcare for you and 2 family members\n- 16++ days of paid leave per year\n\nJob description\n- Develop, maintain and execute automation test cases for major projects, maintenance, and emergency releases\n- Design and implement automation tests scripts, debug and define corrective actions\n- Identify, analyze and report test results\n- Report, track, and monitor defects in the defect tracking system\n- Investigate defect reports from production support, isolate their causes, inform development teams for fixing and retest to ensure adequate resolutions.\n- Work closely with the PO and development teams to design testing strategies.\n- Work on the interpretation of quality assurance issues and problems for technical and non-technical users\n\nYour skills and experience\n- Bachelor’s degree in IT, Software Engineering, Computer Science, or a related field.\n- 2–8 years of hands-on experience in automation testing for web, API, and mobile apps using Java, Selenium, and Appium.\n- Bonus points for experience with JMeter for performance testing.\n- Skilled in writing clear, effective test cases from requirements.\n- Strong at juggling multiple tasks and managing priorities with ease.\n- Solid experience in cross-browser, cross-platform, and responsive testing (Web, API and mobile)\n- Familiar with version control tools like Git or similar.\n- Analytical mindset with strong problem-solving skills.\n- Curious, eager to learn, and always open to new tools and testing trends.\n- English: conversational\n\nWhy you\'ll love working here\nWhy BOSCH?\n- Because we don\'t just follow trends, we create them.\n- Because we do not just follow trends, we create them. Together we turn ideas into reality, working every day to make the world of tomorrow a better place.\n\nDo you have high standards when it comes to your job? So do we. At Bosch, you will discover more than just work.\n\nBenefits and Career Opportunities\n- Working in one of the Best Places to Work in Vietnam and Top 30 of the Most Innovative Companies all over the world\n- English-speaking environment, with opportunity to be part of innovation team and work in global projects\n- Onsite opportunities\n- Engage in our diverse training programs which surely help strengthen both your personal and professionalism\n- Flexible working time and working model\n- 13th-month salary bonus + attractive performance bonus (you\'ll love it!) + annual performance appraisal\n- 100% offered salary and mandatory social insurances in 2-month probation\n- 15++ days of annual leave + 1-day of birthday leave\n- Premium health insurance for employee and 02 family members\n- Lunch and parking allowance\n- Good benefits of company activities such as: football, badminton, yoga, Aerobic, team building…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '15 Tran Bach Dang Street, Thu Thiem New Urban Area, An Phu , District 2, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1076, 643, 2, 'Sr Frontend Developer ( ReactJs, JavaScript, UI-UX)', 'About PAVE - A product of Discovery Loft\nPAVE 🔧🚗is an innovative automotive technology company transforming the way the world inspects vehicles. Powered by Intelligent Damage Detection capabilities, PAVE enables anyone with a smartphone to complete a guided vehicle inspection simply by taking photos of their car.\nHeadquartered in Toronto, our team brings deep expertise from both the automotive and technology industries, blending the best of artificial intelligence and automotive intelligence.\n\nResponsibilities\nCollaborate closely with the UI/UX team to deeply understand the design system, component logic, and design methodology (e.g., atomic design, responsive principles, accessibility). Validate and ensure the technical feasibility of design requirements, and provide feedback to UI/UX when necessary.\nTake ownership of translating high-fidelity UI/UX designs into pixel-perfect, maintainable frontend code using HTML, SCSS, and JavaScript. Ensure consistency and alignment between design specifications and implementation across various screens and platforms.\nLeverage Tailwind CSS (utility-first CSS framework) for styling components. Design the UI components to be framework-agnostic and easily integratable with modern libraries: ReactJs, SvelteJs, or Laravel Livewire projects.\nOptimize UI components for performance, responsiveness, and cross-browser compatibility across web-capable devices and embedded webviews.\nUse Storybook (or a similar component workbench) to develop and document UI components in isolation​. Maintain a living style guide and interactive documentation so designers and developers can browse and test components. Write unit and integration tests for components to guarantee quality and catch regressions early.\nWork with various front-end teams to integrate the new UI framework into their applications. Provide support and gather feedback from these internal teams, iterating on components or adding new features to the framework based on real-world usage and requirements.\nWrite robust, scalable code and manage upgrades of frontend frameworks and third-party modules with a strong focus on coding standards and security.\nImplement and maintain testing for UI components using tools like Jest, Mocha, or Chai to ensure reliability and stability.\nParticipate in code reviews, share best practices, and contribute to frontend architecture decisions across teams.\nStay up-to-date with the latest front-end technologies, trends, and best practices. Continuously evaluate and incorporate improvements (e.g. new tools, libraries, or techniques) to keep the custom framework modern and maintainable over time.\n\nYour skills and experience\nWhat We’d Love From You\nWe’d be delighted if you could share a web product you helped build, where your frontend implementation contributed to a smooth, responsive, and user-friendly UI. We’re also interested in hearing about how you collaborated with designers and ensured a great user experience through code.\nBe open minded to things you do not know, consistently learn and grow the skills necessary for the job Be ready to adjust and implement new plans in a fast paced environment Be confident and responsible; responsible down to a single line of code.\nAlways be working on self improvement; willing to review your progress and see how you can make it better\nGetting the job done is a priority.\nHave good sportsmanship and be competitive; we have structured the responsibilities to be somewhat like a game!\nBe respectful and helpful to others and your working environment\nTreat yourself well and save the Earth.\nBe motivated, creative and passionate - it will ignite the rest!\nGood English communication skills, both verbal and written.\nRequirements\nExperience:\n5+ years of frontend development experience, with at least 2 years in a senior or tech lead role.\nProven track record delivering high-quality web applications in cross-functional teams.\nPrior experience collaborating closely with design teams (especially UI/UX Managers or Product Designers).\nTechnical Skills:\nSolid understanding of HTML5, CSS3, and core web fundamentals.\nExperience with CSS frameworks or methodologies (e.g. Tailwind CSS, BEM, Sass/LESS). Familiarity with Tailwind CSS is a strong plus, or willingness to learn it for implementing utility-first styling at scale.\nExpertise in JavaScript, with deep proficiency in TypeScript for large codebases.\nStrong proficiency with at least one modern front-end framework, especially React.js (hooks, context, state management, etc.). Familiarity with Svelte.js (or similar frameworks like Angular or Vue) is a plus, and an ability to quickly learn new frameworks is expected to achieve cross-framework integration.\nExperience using tools like Storybook for building and showcasing UI components in isolation. Comfortable documenting components, writing usage examples, and utilizing such tools for UI testing and development workflow.\nProficient with version control (Git) and collaborative development workflows (pull requests, code reviews). Experience with modern build tools/bundlers (Webpack, Vite, Rollup) and package managers (npm/yarn) for distributing libraries.\nStrong knowledge of web accessibility standards (WCAG) and experience ensuring UIs are accessible. Exposure to writing tests for the front-end (unit tests with Jest, component tests, and end-to-end tests with tools like Cypress) to validate UI behavior.\nAbility to optimize front-end code for performance. Familiar with performance debugging/profiling tools and techniques to improve load times and rendering (e.g., Lighthouse, Chrome DevTools).\nSoft Skills:\nExcellent problem-solving and analytical skills. Capable of architecting solutions to complex UI challenges and making design decisions that scale for a large codebase.\nStrong communication skills with the ability to explain technical decisions to non-technical stakeholders, and to understand design considerations from the UX team’s perspective.\nExperience mentoring or leading frontend developers, conducting code reviews, and promoting engineering excellence.\nProactive, ownership-driven mindset with the ability to work independently or lead frontend efforts within a cross-functional squad.\nEducation: Bachelor’s degree in Computer Science, Information Technology, or a related field, or equivalent practical experience.\n\nWhy you\'ll love working here\n1. Competitive Compensation & Perks\nAttractive salary package.\n15 days of annual leave.\nYear-end bonus equal to one month’s salary.\nPremium healthcare coverage for you and your family.\nThoughtful appreciation gifts throughout the year.\n2. Growth & Learning Opportunities\nWork on cutting-edge, large-scale products in the car inspection field.\nClear career paths for both technical experts and aspiring leaders.\nContinuous learning programs to sharpen your skills and grow your career.\nLearn from everything, everywhere—but be a smart copy-paster, not a copycat!\nBe ready to embrace and implement new ideas in a fast-paced environment.\n3. An Inspiring Workplace\nFlexible hybrid work model and a strong focus on work-life balance.\nA modern, fully-equipped Office with a well-stocked pantry.\nBe motivated, creative, and passionate—we can’t ask for more!\nRespect and care for your teammates, your environment, and even yourself.\nTreat yourself well, and while you’re at it, save the Earth too.\n4. A Mindset for Growth\nHave the courage to move fast, stay flexible, and take full responsibility for every single line of code.\nAlways look back at your work and strive to make it better—nothing is perfect, and that’s where you come in.\nIt’s okay to be late sometimes, but make sure you’re fully accountable and aware of your actions.\n5. A Dynamic and Open Culture\nWe don’t stick rigidly to the gameplan, so feel free to add or remove your own “blah blah” from this list.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '33/26 Đường số 9, Phường An Khánh, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1077, 644, 2, 'Project Manager', 'Chịu trách nhiệm quản lý dự án bao gồm việc lập kế hoạch điều phối và hoàn thành dự án đúng thời hạn; giám sát tất cả các khía cạnh của dự án; xác định thời hạn, phân công trách nhiệm, theo dõi và tổng hợp tiến độ thực hiện dự án; thực hiện các báo cáo cho cấp quản lý và các bên liên quan trong dự án. Cụ thể:\n\nLập kế hoạch và thiết kế dự án:\n- Gặp gỡ với các bên liên quan để thảo luận về mục tiêu và phạm vi dự án\n- Tổ chức các buổi làm việc để thu thập thông tin và phản hồi từ các bên liên quan\n- Phân tích các yêu cầu của dự án\n- Xác định các hoạt động cần thực hiện để đáp ứng các yêu cầu của dự án\n- Lập lịch trình các hoạt động\n- Xác định nguồn lực, ngân sách cần thiết cho dự án\n- Phân công trách nhiệm cho các thành viên trong nhóm dự án\n- Trình bày kế hoạch dự án cho các bên liên quan\n\nTriển khai và Giám sát dự án:\n- Dẫn dắt và theo dõi các hoạt động phát triển/ triển khai dự án để đạt được các mục tiêu của dự án\n- Theo dõi và giám sát triển khai theo kế hoạch\n- Đảm bảo dự án triển khai theo tiến độ về thời gian, ngân sách đã được dự toán và thống nhất\n- Quản lý các bên liên quan, các kết quả đầu ra để đảm bảo mục tiêu và kết quả dự án\n- Quản lý các thay đổi, issue trong dự án\n- Báo cáo tiến độ dự án cho Ban lãnh đạo, các bên liên quan trong dự án\n\nĐóng dự án:\n- Thực hiện đánh giá kết quả dự án theo các tiêu chí của dự án\n- Thực hiện nghiệm thu dự án với các bên liên quan\n- Thực hiện các thủ tục đóng dự án\n\nSẵn sàng làm việc linh hoạt,có thể trao đổi và hỗ trợ công việc trước 12h đêm nếu dự án yêu cầu (được tính OT hoặc có thỏa thuận riêng).\n\nYour skills and experience:\n- Tốt nghiệp các trường Đại học chuyên ngành CNTT hoặc các ngành khác có liên quan\n- Từ 2 năm kinh nghiệm quản trị dự án\n- Có khả năng nghiên cứu nhanh và nắm bắt được kiến thức về hệ thống cũng như các điểm quan trọng về kỹ thuật/công nghệ\n- Kiến thức về Quản lý dự án, và quy trình triển khai dự án\n- Kỹ năng tổ chức, lãnh đạo và dẫn dắt đội ngũ, đặt mục tiêu, thúc đẩy, tạo gắn kết\n- Kỹ năng lập kế hoạch, theo dõi và kiểm soát tiến độ\n- Kỹ năng quản lý phạm vi, chi phí và thời gian dự án\n- Kỹ năng giao tiếp, đàm phán và ra quyết định\n\nWhy you\'ll love working here:\n- Thu nhập upto 15-20M tùy năng lực, 4-6 tháng xét tăng lương 1 lần;\n- Sau 2 tháng thử việc sẽ được cân nhắc lên nhân viên chính thức, hưởng đầy đủ quyền lợi về BHXH\n- Được tham gia vào các dự án lớn như: hệ thống học trực tuyến K12Online, cổng thanh toán BiPay, Chuyển đổi số VP TW Đảng, ...\n- Được trang bị toàn bộ thiết bị làm việc\n- Nghỉ phép: 12 ngày/ năm\n- Môi trường làm việc năng động, sáng tạo với đội ngũ CBNV đầy nhiệt huyết. Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding, sự kiện công ty, tiệc mặn ngọt,....', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tháp Đông, CC Học Viện Quốc Phòng, đường Nguyễn Văn Huyên kéo dài, Xuân La, Tây Hồ, Hà Nội, Tay Ho, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1078, 645, 2, 'Senior Frontend Developer', 'YOU\nYou want to be a key member of a strong team of creators who take pride in their work and support one another. As a Front-end Developer, you will be responsible for collaborating with the team to build a variety of Simpson Strong-Tie digital products, leveraging your valuable skills and competence, and contributing to the growth of the organization. You’ll focus on delivering intuitive, efficient, and innovative solutions that address business needs, helping drive progress forward. Your impact will be recognized, and if career growth is important to you, we not only know how to support your development—we\'re passionate about it:\n\nWHAT YOU’LL BE DOING\n\nFront-end Development\nDevelop, test, and maintain highly performant and scalable code using modern front-end frameworks.\nBuild reusable and modular components and libraries for future use.\nEnsure that the web applications are responsive, fast, and optimized for various devices and browsers.\nWrite and maintain high-quality, clean, and well-documented code that follows best practices in JavaScript/TypeScript, HTML, and CSS/SASS.\n\nArchitecture & Design\nLead the design and development of complex front-end applications, ensuring scalability and performance.\nCollaborate with backend engineers to ensure seamless integration between the front-end and backend systems via REST APIs or WebSockets.\nInfluence the architecture and design decisions of the product, including component structure, state management, and data flow.\n\nPerformance Optimization\nOptimize application performance by leveraging techniques such as lazy loading, code splitting, and asset optimization.\nUse tools like Lighthouse and Chrome DevTools to monitor and improve front-end performance metrics like render time and load time.\n\nCross-Functional Collaboration\nCollaborate with multiple product teams to implement design artifacts held in Figma and similar tools into finished static resources for incorporation into Simpson Strong-Tie’s digital products.\nCollaborate with product managers to define and implement product features and improvements.\nLead technical discussions with backend engineers, designers, and other stakeholders to build cohesive and efficient systems.\nPartner with other teams across the organization to weigh in on project priorities, project estimation, and risk identification for roadmap projects.\nContribute to multiple releases across Simpson Strong-Tie’s digital product portfolio.\n\nMentorship & Code Reviews\nMentor Interns, Engineer and Associate Senior Engineer, and provide guidance on best practices, architectural decisions, and professional growth.\nPerform regular code reviews to ensure high-quality code and provide constructive feedback.\nLead efforts to establish and enforce coding standards and best practices across the team.\n\nTesting & Quality Assurance\nEnsure high code quality through the implementation of unit tests, integration tests, and end-to-end (E2E) testing using frameworks.\nParticipate in bug triaging and resolve technical issues quickly and efficiently.\n\nContinuous Improvement\nDrive continuous improvement in front-end development processes, tools, and frameworks.\nStay up to date with emerging trends and best practices in front-end development and bring innovative ideas to the team.\nWork with the DevOps team to integrate front-end applications into CI/CD pipelines and ensure seamless deployment.\n\nYour skills and experience\nIf you can do everything listed above, you’ve got what it takes. Perhaps some of the following would be helpful too:\nAt least 5 years of overall software development experience, with an emphasis on web applications and front-end technologies\nStrong proficiency in a modern front-end framework such as React, Angular, Next, or Lightning Web Components\nStrong proficiency in HTML, SCSS/SASS/CSS, Javascript/Typescript\nStrong understanding of RESTful APIs, and real-time web technologies (e.g., WebSockets)\nExperience with front-end build tools (e.g., Webpack, Vite, Babel, ESLint, Prettier)\nProficient with version control systems such as GIT\nProficient with JIRA and Confluence\nExcellent organizational and communication skills\nFluent English communication skills (both verbal and non-verbal)\nUnderstand and design for non-functional concerns such as performance, cost optimization, maintainability, developer experience, and responsive design\nComfortable working across multiple product areas, building relationships, and connecting different workstreams into a unified system for all\nFamiliarity with state management patterns and libraries\nFamiliarity with cross-browser compatibility issues and ways to work around them\nFamiliarity with web security principles and experience with front-end security vulnerabilities (e.g., XSS, CSRF)\nFamiliarity with Figma, design systems, knowledge of frameworks/tooling such as atomic design principles, design tokens, and semantic naming\nFamiliarity with Agile/Scrum methodology\nHelpful if some experience with a form of SVG framework: D3, Highcharts, ReactCharts\nHelpful if some experience with web rendering engines like BabylonJS\nExposure to cloud-based architecture like Azure\n\nWhy you\'ll love working here\nAttractive salary with 100% salary during probation\n13th-month salary, Performance bonus, Salary review annually\nPremium health care program for employees + one of your beloved ones, Annual medical check-up\n14 vacation days, Christmas Day per year\nOpportunity to be on-site in the USA\nChance to collaborate and work with global stakeholders\nProvide training to develop our employee‘s knowledge and skills (Internal training: LinkedIn Learning, and another online training course, TechTalk sharing within Software Development Division; External training: Management, English, Soft Skills, ….)\nBenefits for special holidays (Birthday, Marriage, Women’s Day, Tet Holidays, Mid-Autumn, Newborn babies, International Children‘s Day…)\nCompany trip and Year-End party every year\nSocial, sports and several team building activities\nYoung, friendly and international working environment\nModern working conditions and entertainment facilities at the office\nSnacks, tea and coffee all the time\nCompliance fully to Vietnam Labor code.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sabay Building, 427 Truong Chinh Street, 14 Ward, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1079, 232, 2, 'Mid/Senior Business Analyst (English required)', 'Top 3 reasons to join us\n- Exciting projects and young team\n- Global company and dynamic environment\n- Competitive Salary and great benefits\n\nJob description\n- Liaising between the IT department, User Experience department, and the Executive branches\n- Analyzing, understanding strategic business needs, and planning for growth\n- Acting as an information source and communicator between business branches; proposing solutions to meet business requirements as well as the design of technical systems if necessary\n- Writing and maintaining robust functional specifications\n- Be familiar with the SCRUM Agile Development methodology and Conduct regular stand-ups with the development team and product owner in the capacity of a SCRUM Master.\n- Managing change requests from stakeholders\n- Conducting Quality Assurance and Quality Control tests, A/B tests, and UAT sections with users and product owners\n- Utilizing and analyzing IT data for business insights\n- Enhancing the quality of IT products and services\n- Analyzing data to inform business decisions\n- Sourcing and implementing new business technology\n- Finding technological solutions to business requirements\n- Producing reports on application development and implementation\n\nYour skills and experience\n- Diploma/Degree in Computer Engineering, Business Administration or related field\n- 3+ years in an IT Business Analyst role\n- Excellent command of English\n- Excellent problem-solving skills\n- Analytical mindset\n- Exceptional interpersonal skills\n- Excellent written and verbal communication skills\n- Attention to detail\n- [Bonus] SCRUM Master Certification\n- [Bonus] IT Development experience\n- [Bonus] Experience in Healthcare or Insurance industry\n\nWhy you\'ll love working here\n- A young and dynamic team where you can develop your career path and improve your English skills\n- An exciting project which uses cutting-edge technology\n- 14 days annual leave per year\n- 13th-month salary\n- Private insurance for employees. After 1 year, company will cover the insurance for family members (spouse, children)\n- Providing Laptop to work\n- Company trip \n- Annual health check \n- Monthly teambuilding activities\n\nWhen applying for this position at Fullerton Health Vietnam, you have provided us with your information. Please trust that we are always dedicated and set strict privacy principles. Please read the \'Privacy Policy\' below to understand more about our commitment to respecting and protecting the rights of applicants.\nPrivacy Policy: www.fullertonhealth.com/vn/chinh-sach-bao-mat', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1st Floor, L’Mak Plaza (Nam A Plaza), 127 Hong Ha, Ward 09, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1080, 646, 2, 'Java Developer (Agile, Cloud)', 'Mô tả: 5y+ Java, kinh nghiệm trong lĩnh vực phát triển phần mềm trong lĩnh vực Tài chính, Ngân hàng.\n\n1. Chức năng vị trí công việc: \n- Thực hiện phát triển sản phẩm, dịch vụ trên nền tảng ứng dụng số hóa dịch vụ Ngân hàng số cho KHCN/KHDN, hệ sinh thái\n- Phối hợp xây dựng các tiêu chuẩn công nghệ, tích hợp, kiến trúc theo định hướng chiến lược của ngân hàng\n- Phối hợp thực hiện quy hoạch ứng dụng, các giải pháp cải tiến để cải thiện tốc độ, hiệu quả và khả năng mở rộng ứng dụng.\n\n2. Trách nhiệm công việc:\n- Tham gia phát triển Backend cho hệ thống nền tảng và các sản phẩm, dịch vụ ngân hàng số.\n- Tuân theo các tiêu chuẩn thiết kế, tiêu chuẩn mã nguồn, đảm bảo khả năng kiểm thử, bảo mật và hiệu năng cao cho hệ thống.\n- Phối hợp với team BA, Frontend, SA,... triển khai dự án đảm bảo các yêu cầu về chất lượng, tiến độ.\n- Thực hiện Unit Test. Hỗ trợ kiểm thử SIT/UAT, sửa lỗi và nghiệm thu chức năng.\n- Xây dựng tài liệu kỹ thuật, tài liệu hướng dẫn triển khai hệ thống.\n\n3. Yêu cầu về năng lực: \n- Yêu cầu ở cấp độ 3 với nhóm năng lực chuyên môn sau:\n+ Hiểu biết về sản phẩm, dịch vụ ngân hàng số\n+ Kinh nghiệm lập trình, tích hợp giải pháp\n+ Hiểu biết về kiến trúc giải pháp phần mềm\n+ Kinh nghiệm về Agile, DevOps, CI/CD, và Cloud\n+ Kỹ năng giao tiếp, lập tài liệu và thuyết minh giải pháp kỹ thuật.\n+ Kỹ năng phân tích, giải quyết vấn đề, tối ưu hóa\n\n4. Yêu cầu về bẳng cấp, kinh nghiệm: \n- Bằng cấp: Đại học chính quy trở lên trong lĩnh vực Công nghệ thông tin \n- Kỹ năng: \n+ Thành thạo lập trình hướng đối tượng với Java\n+ Có kinh nghiệm thiết kế và phát triển RESTful API, Web socket.\n+ Hiểu biết về kiến trúc Microservice (MSA), SOA, Event-Driven Architecture (EDA)\n+ Có kinh nghiệm phát triển và tích hợp RESTful API, Web socket. Hiểu biết về kiến trúc Microservice.\n+ Nắm vững kiến thức về cấu trúc dữ liệu và giải thuật.\n+ Sử dụng thành thạo các IDE phát triển và công cụ quản lý mã nguồn (Git)\n+ Hiểu biết về Agile/Scrum\n+ Hiểu biết và có kinh nghiệm thực tế với Cloud, DevOps, CI/CD, Container, Docker, k8s\n+ Nhiệt tình, trách nhiệm với công việc - Giao tiếp tốt. Có khả năng đọc hiểu, nghiên cứu tài liệu kỹ thuật bằng tiếng Anh\n+ Lập kế hoạch và quản lý thời gian hiệu quả\n\n1.Thu nhập cạnh tranh – Mức lương hấp dẫn theo năng lực và kinh nghiệm (thỏa thuận khi trúng tuyển).\n2.Phúc lợi toàn diện – Hưởng đầy đủ chế độ bảo hiểm theo luật lao động cho CBNV\n3.Chế độ nghỉ phép ưu đãi – 13 ngày/năm, bao gồm 01 ngày nghỉ sinh nhật.\n4.Môi trường làm việc năng động, linh hoạt, trẻ trung.\n5.Phát triển sự nghiệp – Cơ hội đào tạo, thăng tiến rõ ràng trong môi trường chuyên nghiệp được hỏi hỏi thực hiện nhiều dự án lớn.\n6.Hoạt động gắn kết đa dạng – Tham gia team building, hội thao, văn nghệ và nhiều sự kiện nội bộ hấp dẫn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 15 ngõ 112 đường Chùa Võ, Phường Dương Nội, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1081, 492, 2, 'Senior AI/NLP Engineer (Python, PyTorch)', 'We\'re seeking a talented Data Scientist to join our Data Science and AI (DSAI) team in revolutionizing stock trading and investment for Vietnamese individuals. You\'ll play a pivotal role in developing and enhancing Ensa - our AI-powered Virtual Investment Assistant. Ensa aims to be a trusted companion and source of inspiration for investors, simplifying complexities and helping them navigate market challenges.\nYour focus will be on leveraging cutting-edge AI technologies, including Large Language Models (LLMs), Autonomous Agents, and Retrieval-Augmented Generation (RAG), to build Ensa. If you\'re ready to be part of a dynamic team driving change in the world of stock trading, we want to hear from you!\n\nDevelop and fine-tune Large Language Models (LLMs) to enhance Ensa\'s interaction capabilities and information delivery.\nDevelop algorithms for personalizing investment experiences, predicting market trends, and optimizing investment portfolios for individual investors.\nIntegrate and maintain a financial knowledge base for RAG, ensuring Ensa stays updated with the latest market information.\nConduct research on market trends, historical data, and user preferences to enhance Ensa\'s recommendation capabilities.\nWork on MLOps to deploy and maintain machine learning models in a production environment.\nStay updated with the latest advancements in AI, NLP, quantitative trading.\n\nYour skills and experience\n\nStrong problem-solving skills with a focus on product development (mandatory).\nExperience with Large Language Models and building recommendation systems is highly advantageous.\nExperience in implementing and optimizing Retrieval-Augmented Generation (RAG) systems.\nRobust programming skills in Python and PyTorch.\nStrong problem-solving abilities and a keen interest in uncovering patterns and insights within data.\nA drive to continuously learn and master new technologies and methodologies (mandatory).\n\nWhy you\'ll love working here\n\nFastest growing fintech startup with state-of-the-arts technology.\nTop notch engineering team.\nCompetitive salary with regular review and advancement.\nOpportunity to take charge of your own works and directly contribute to company products.\nSmall, young and close-knit team. We move fast, work hard and play hard.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 6 tòa nhà Pax Sky số 63-65 Ngô Thì Nhậm, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1082, 647, 2, 'Senior FullStack Dev (NodeJS, ReactJS, AWS) - Remote', 'About us:\nAutomation Consulting Pty Ltd is an Australian-based AI and automation consultancy helping businesses streamline operations with smart, scalable solutions.\n\nAbout Our Client\nOur client is a dynamic Australian FinTech startup revolutionizing payments. Their innovative platform empowers businesses with cutting-edge payment solutions, enhancing efficiency while offering valuable rewards. Launched in 2019, they\'ve quickly become one of Australia\'s fastest growing fintech companies.\n\nRole Overview:\nWe\'re seeking skilled and passionate full-stack developers to join our client\'s distributed team.\nThis is a remote contract position based in Vietnam, working with an Australian development team.\n\nIMPORTANT NOTE:\nThis role is specifically with our client (Australian FinTech) and NOT with Automation Consulting. The scope of work is focused on payment platform development and does NOT include any GenAI development work.\n\nTech Stack\n* Frontend: React, TypeScript, MaterialUI\n* Backend: Node.js, GraphQL, Express\n* Infrastructure: AWS, Terraform, Docker\n* Databases: PostgreSQL, MongoDB\n\nKey Responsibilities:\n• Design and implement scalable microservices\n• Build and maintain responsive web applications\n• Bug fixes and production support\n• Platform maintenance and feature enhancements\n• Mentor junior developers and provide technical guidance\n• Conduct code reviews and promote best practices\n• Collaboration with product and design teams\n\nYour skills and experience\n• 5+ years of full-stack web application experience or 5+ years in one or more of the key technologies\n• Strong proficiency in Node.js, TypeScript, and React\n• Experience with AWS cloud services and Terraform\n• Knowledge of PostgreSQL and/or MongoDB\n• Excellent problem-solving and analytical thinking skills\n• Strong English communication skills (both written and verbal)\n• Proven ability to work effectively in distributed teams\n• Strong organizational skills and attention to detail\n\nWhy you\'ll love working here\nWhat We Offer:\n• Competitive salary.\n• Flexible working hours for work-life balance.\n• Partnership approach ("work with us, not for us").\n• Laptop provided for work purposes.\n• Contractors responsible for their own taxes and business expenses.\n• Collaborative and nurturing environment.\n• Knowledge sharing and skill enhancement opportunities.\n• Respectful and inclusive team culture.\n• Long-term opportunity with ongoing projects and growth potential.\n\nAdditional Information: This is a contract-based opportunity, not permanent employment.\n\nApplication Process\n1. Initial Interview (15 minutes)\n2. Technical interview with Engineering Team\n3. Technical Interview and Live Coding\n4. Cultural Fit Interview', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Remote (anywhere), Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1083, 328, 2, 'Backend Programmer (NodeJS/Java/Python/English)', 'We are dedicated to providing innovative, engaging, and high-quality H5 web chatroom AI and mini-game solutions for users worldwide, creating seamless cross-platform gaming and chat experiences.\n\nResponsibilities\n- Develop and maintain backend systems for real-time gaming and web chat applications.\n- Proficient in PHP, Laravel, MySQL, Redis, and CentOS \n- Familiar with Golang, RESTful services, Node.js, Python, Ruby, Java\n- Experience with NoSQL and cache systems such as MongoDB and Redis\n- Proficient with Git, Linux, Docker, and Kubernetes (K8S) \n- Skilled in MS SQL and PostgreSQL database setup and management \n- Experience with multi-threaded programming and high-load system architecture. \n- Write and maintain technical documentation for projects.\n\nYour skills and experience\n- Proficient in Linux, Java, Python, Ruby, or PHP\n- MySQL, PostgreSQL, Node.js\n- 2-3 years of experience in the same position.\n- Open mindset for AI and innovation; skilled in using creative AI tools.\n- Detail-oriented with strong problem-solving skills.\n- Strong self-learning skills, proficient with Git\n- Must bring work samples to interview.\n- Good English communication skills\n\nWhy you\'ll love working here\n- Salary range: 20,000,000 VND – 40,000,000 VND/month (based on experience).\n- Monthly meal allowance\n- Official employees enjoy paid leave, holiday bonuses, and Tet bonuses as per company policy.\n- Generous bonus system:13th-month salary, performance bonuses\n- Internal events: Happy Hour, Internal Party, Company trip\n- Young, dynamic, and fun working environment.\n- Work Schedule: Monday-Friday (5 days/week)\n- Address: 99 Nguyen Thi Nhung, Thu Duc City', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '99 Nguyễn Thị Nhung, Hiệp Bình Phước, Thủ Đức, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1084, 288, 2, 'Business Analyst (Product, English)', 'ABOUT THE JOB:\nParcel Perform is looking for a passionate, dynamic, and motivated Business Analyst to drive continuous improvement across our product processes, features, and operations at Parcel Perform. You will have a direct impact on the success of the company, and your work will help grow our platform that allows our users to provide the best e-commerce delivery experience for their customers from around the globe.\n\nWHAT YOU\'LL DO:\n- Support development of product requirements for selected development epics; utilising research, investigation, validation of concepts and other tools to ensure requirements align with overall product and business goals.\n- Drive ad-hoc customer requests for a select number of topics, from solution and effort estimates, to facilitating timely communication with customer-facing teams, to working closely with Product to solution complex requests.\n- Own and maintain key product master documents through working with various contributors to ensure that the information is kept up-to-date while enforcing format and structure standards.\n- Support the epic development process, coordinating closely with the squad and squad leads to ensure epic requirements are developed, tested, deployed and clearly communicated to customer-facing teams.\n- Provide close support for a particular Squad through a certain period, or provide flexible resources for high-priority initiatives across the Tribe.\n- Ensure clear monitoring and regular reporting of topics, utilising various communication aspects like documentation, slides, visuals, and more.\n\nYOUR SKILLS AND EXPERIENCE\nWHO YOU ARE:\n- At least 3 years of working in relevant positions in technology and software development companies.\n- Process management experience, with a track record of coordinating with multiple stakeholders across business functions to execute complex projects.\n- Excellent critical thinking, organizational and communication skills, and keen attention to detail.\n- Able to use investigative prowess, data analysis, and domain understanding to generate proper solutions for customers\n- Adaptability and flexibility to work with rapidly-changing requirements and prioritization, and managing multiple ongoing projects at once.\n- Quick, proactive, and effective communication and action.\n- Able to communicate clearly and effectively in English and Vietnamese is required.\n- A background in the e-commerce logistics, supply chain, or logistics transportation domain will be an advantage.\n\nWHAT YOU WILL RECEIVE IN RETURN!\nWe at Parcel Perform are dedicated to being a platform for growth for all our team members, regardless of function and location.\n\n- The opportunity to work in a fast-growing, super exciting and innovative business that will revolutionize the e-commerce logistics industry. You will be the needle of success on the growth of a global product that will become a key platform behind successful e-commerce logistics worldwide.\n- The ability to continuously learn and develop in an international setting with you being a critical driver behind the success of us achieving our mission.\n- An environment where everybody never stops growing and focuses on succeeding - we continuously work with you on your strengths and weaknesses across many important dimensions and look at ways for you to address them and further your development.\n- Your entry ticket into being part of the Parcel Perform journey, where you will work with and alongside people from around the world that share the same passion and dedication.\n\nWHO ARE WE AT PARCEL PERFORM!\nParcel Perform (www.parcelperform.com) is a leading e-commerce delivery experience platform, empowering businesses to optimize the entire customer journey from checkout to delivery and returns. By unifying logistics data and providing actionable insights and intelligent automation, including leveraging AI capabilities, Parcel Perform helps businesses enhance customer satisfaction, streamline operations, and drive growth. With a global reach and an extensive carrier network, Parcel Perform is the trusted partner for ambitious e-commerce businesses, marketplaces, and 3PLs worldwide. We’re committed to continuously innovating, using data to optimize every step of the e-commerce delivery.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Grace Tower, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1085, 205, 2, 'Senior/Lead Java Dev (Spring, English), up to 4,500 USD', 'At LeapXpert, we\'re revolutionizing business communication by seamlessly integrating the familiarity of consumer messaging apps with enterprise-grade security and compliance.\n\nAs pioneers in responsible business communications, we empower employees and clients to connect through their preferred messaging platforms while upholding the highest standards of governance and security.\n\nOur mission is to transform workplace communication globally.\n\nWe\'ve been recognized as a Visionary in Gartner\'s Magic Quadrant for Digital Communications Governance and Archiving Solutions, raised a $20 million Series B funding round—bringing our total funding to $60 million, and earned the trust of top-tier institutions worldwide, who rely on our platform daily to streamline client communications.\n\nThis is just the beginning—we\'re growing rapidly and we\'re seeking passionate, talented individuals to join our team.\n\nThis is your opportunity to work on impactful projects using cutting-edge technologies alongside driven innovators from around the world.\n\nApply now to be part of something revolutionary!\n\nWe are looking for Senior Backend Java Software Engineers responsible for building backend services; Restful, AKKA, gRPC, events sourcing (Kafka) based on Micro-service Architecture and integrating with banking systems. This includes anything between complex groups of back-end services and integrations. Your primary responsibilities will be in the design and development of these applications, mentorship of mid-developers, and coordination with the rest of the team working on different roles: QC/QA, Test Automation, Product Owner. Thus, a commitment for collaboration on problem-solving, architecture design, TDD, BDD and product quality is highly valued.\n\nTo be successful in this role, you should be able to identify the requirements/User Stories to define tasks including non-functional requirements and work with cross-functional teams delivering expected products. Ultimately, you’ll help us roll out products that deliver our company’s vision and help in creating enterprise-grade communication solutions.\n\nResponsibilities:\n- Design, document, build, and maintain efficient, reusable, and reliable Java services\n- Ensure the best possible performance, quality, and responsiveness of the applications\n- Identify bottlenecks and defects, and devise solutions to these problems\n- Translate application User Stories and use-cases into functional applications\n- Help to maintain code quality, organization, and automatization\n\nYour skills and experience:\n- 5+ years of work experience as a Backend Engineer (Java)\n- Familiar with Agile development processes\n- Good English communication and documentation skills\n- Strong in Java core (at least JDK 8 or above, preferred 11), OOP and Design Pattern\n- Micro-service development using Spring or based on AKKA and gRPC\n- Have have experience with scalable products\n- Message queue: Kafka, RabbitMQ\n- Experience with popular search engine frameworks: ElasticSearch, SOLR\n- DB skills (SQL/NoSQL): performance optimization\n- Non-Blocking IO, Asynchronous processing\n- Experience with Kubernetes (big plus)\n- Testing: TDD, BDD (big plus)\n- Familiar with Cloud providers such as AWS, GCP, and Azure\n\nWhy you\'ll love working here:\n- You are looking for: \n- An awesome job opportunity with an attractive remuneration package\n- Working on site with a stylish and comfortable environment.\n- Friendly coworkers who support each other to win together as a team.\n- Working in a team that encourages AI adoption, experimenting with and learning new AI tools to enhance the developer experience.\n- A flat, product-focused organization and Agile teams that allow you to bring value and ideas to the product and the company\n- Opportunities to learn and be trained in new technologies and methodologies\n- Facing new and innovative challenges to deliver a commercial-grade, world-class product\n- Career growth in multiple directions, based on your preferences and abilities\n\nBenefits:\n- 13th Salary, paid pro-rata, every month to allow more flexible financial plans\n- 18 annual leaves and 1 birthday leave\n- Full salary on probation\n- Full social insurance according to Vietnam Labor Law\n- Premium Health Care Insurance\n- Annual health check\n- Lunch and parking allowances\n- Team building, fun monthly, quarterly activities and so much more fun are waiting for you!\n- Relax with Tabletop foosball, PlayStation, massage chair in the office\n- Annual Performance Review\n- Attractive career path\n- Advanced technical solutions, Agile culture and the opportunity to work with the latest technologies\n\nSounds like a good fit? Come and join the team at LeapXpert!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '195/10E Dien Bien Phu, Ward 15, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1086, 582, 2, 'Junior .NET Developer (JavaScript, SQL)', 'Top 3 reasons to join us\n\n- Highly attractive salary\n- 13th month salary, bonus, abroad and local trip\n- Opportunity for overseas training (Germany)\n\nJob description\n\n- Location: Phu Nhuan, HCMC.\n- Working hours: 9a.m – 6p.m Mon-Fri (Hybrid Model).\n\nYour skills and experience\n\nResponsibilities\n\n- Experience working with the following combination of programming languages (C#, JS/TS, TSQL).\n- Experience with .NET & .NET Core, ASP.NET Core, JavaScript, Typescript, Entity Framework, RESTful services.\n- Experience with client-side web application frameworks React/Angular.\n- Strong understanding of databases as well as experience in:\n  - Developing data layer software based on SQL Server or a comparable DBMS.\n  - Writing data access code using .NET (EF or a comparable ORM, LINQ, plain TSQL).\n- Strong understanding of web application development and web/application servers (eg, IIS, Kestrel).\n- Understanding of Azure Cloud Architecture.\n- Experience in dependency management tools (NuGet).\n- CI/CD practices, build management tools (MSBuild).\n- API development (OData, ASP.NET Core Web APIs).\n- Good understanding of best practices around software development (eg, code repositories according to Git, Clean code, DevOps, quality assurance measures, solution documentation, OOD principles, modular software development practices (DI & IoC), and TDD).\n- Ability to develop and maintain existing large code bases.\n- Strong understanding of application architecture (event-driven, command pattern, …).\n\nNice to have\n\n- Experience in working with PDF files, including generating, manipulating, and extracting data from PDFs.\n- Familiarity with PDF libraries (eg, iText, Pdf-Tools, PDFBox, Adobe PDF Library).\n- Experience with Messaging Queues: RabbitMQ, MSMQ, etc.\n- Containerization experience with Kubernetes and Docker.\n\nQualifications\n\n- Excellent ENGLISH communication skills are a MUST.\n- University degree in the field of Computer Science/ Engineering or similar study\n- For Junior: 2+ years of professional experience in software development using the Microsoft .NET stack (.NET framework 4+, .NET Core, .NET standard)\n\nWhy you\'ll love working here\n\n- Attractive salary\n- 13th-month salary\n- FULL Social Insurance, Health Insurance, Unemployment Insurance\n- 15 Annual Leave days per year + 3 Sick Leave days per year\n- Premium Private Health, and 24/24 Accident Insurance\n- Annual Company Trip, Year-end Party, and other activities\n- Gifts on Birthday, Tet Holiday, Mid-Autumn Event…..\n- Stable and long-term partnership.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'SGH Building, 21/4 Nguyen Thi Huynh Street, Ward 8, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1087, 351, 2, 'Middle DevOps Engineer (System Engineering/SRE)', 'Top 3 reasons to join us\n• The world of passion, challenge, innovation\n• We\'re a family of young souls united by talents\n• Passions and Trust\n\nJob description\n• Manage VM/Cloud infrastructure:\n• Develop and maintain scripts and current tools.\n• Building, contributing to our monitoring system.\n• Prepare CI/CD.\n• Perform designing, optimizing infrastructure to make our system more stable\n\nYour skills and experience\nMust have\n• At least 4 years in DevOps, System Engineering, or SRE roles with hands-on experience managing web servers and Linux systems.\n• Experienced in Linux/Unix\n• Hands-on experience on cloud platform (AWS)\n• Ability to do scripting (bash, python …)\n• Experienced with Kubernetes, Docker\n• Experienced with Monitoring stack (Prometheus, Grafana …\nNice to have\n• Familiar with SCM, Git workflow, CI/CD, GitOps, Code quality & security\n• PLUS: Experience with DBA or database management (Mysql, Postgresql).\n• PLUS: Ability to do designing for large-scale system\n\nWhy you\'ll love working here\nWe believe that motivation & personality of the employees are the only shortcut to the promotion of the corporate and contributions to the society. We will try our best to create a corporate environment where all employees can realize their dreams and goals.\nFeatured benefits include:\n• Monday - Friday/ 9am - 6pm\n• Have opportunity to work with global merchants and join the dynamic, young and friendly project team; stable career path;\n• Attractive salary based on skills and experience; 13th month salary & seniority bonus; Employee’s marriage, maternity bonus; Birthday voucher gift;\n• Annual salary review;\n• PTI Healthcare, annual health check;\n• Regular technical seminar & external/ internal training courses;\n• Providing free coffee, tea & snack;\n• Internal engagement events: Teambuilding; Town-hall, birthday gift voucher, mid-autumn, new year and kick-off parties, yearly company trip;\n• FireGroup Sports Clubs: Running, Football, Badminton, etc;\n• Laptop/ PC/ Monitor \'re provided', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Flemington Tower, 182 Le Dai Hanh Street, District 11, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1088, 646, 2, 'QA QC Engineer (Tester, Agile)', 'Yêu cầu: 2y+ testing, có kiến thức tổng quan về ngân hàng và am hiểu nghiệp vụ ngân hàng- Mô tả:\n1. Chức năng vị trí công việc: \n- Tiếp nhận các yêu cầu về Kiểm thử các sản phẩm, dịch vụ trên nền tảng ứng dụng số hóa dịch vụ Ngân hàng số cho KHCN/KHDN, hệ sinh thái\n- Phân tích /đánh giá nguyên nhân lỗi sau golive\n\n2. Trách nhiệm công việc:\n- Tiếp nhận các yêu cầu về Xây dựng kịch bản Kiểm thử các sản phẩm, dịch vụ trên nền tảng ứng dụng số hóa dịch vụ Ngân hàng số cho KHCN/KHDN, hệ sinh thái.\n- Thực hiện tìm hiểu, phân tích và làm rõ yêu cầu. Xây dựng chiến lược kiểm thử cho yêu cầu sản phẩm, dịch vụ.\n- Xây dựng kế hoạch kiểm thử, viết kịch bản, tạo báo cáo kiểm thử, báo cáo lỗi kiểm thử. Xây dựng tài liệu cho các yêu cầu sau khi đã thực hiện.\n- Thực hiện kiểm thử, đánh giá chất lượng sản phẩm.\n- Phân tích /đánh giá nguyên nhân lỗi sau golive.\n- Điều phối công việc trong nhóm theo Agile/ Scrum.\n\n3. Yêu cầu về năng lực: \n- Yêu cầu ở cấp độ 2 với những nhóm năng lực sau:\n+ Am hiểu về sản phẩm, dịch vụ của tổ chức\n+ Hiểu biết về Ngành, Nghiệp vụ\n+ Có kiến thức và kinh nghiệm về kiểm thử\n+ Thành thạo sử dụng các công cụ thực hiện kiểm thử/ quản lý dự án như:Jira\n+ Quản lý thời gian và khả năng chia sẻ thông tin tốt\n+ Kinh nghiệm làm việc trong môi trường áp dụng triết lý Agile\n\n4. Yêu cầu về bẳng cấp, kinh nghiệm: \n- Tốt nghiệp hệ chính quy các Trường Đại học trong nước hoặc nước ngoài. Chuyên ngành đào tạo: Công nghệ thông tin, Toán tin, Điện tử Viễn thông, kế toán, Tài chính Ngân hàng \n- Có kiến thức tổng quan về ngân hàng và am hiểu nghiệp vụ ngân hàng \n- Có hiểu biết/kinh nghiệm thực tế về các nghiệp vụ ngân hàng, ngân hàng số( Internet Banking, Mobile Banking), Thanh toán (Mobile payment).\n- Ưu tiên ứng viên có kinh nghiệm làm việc với Agile/Scrum - Có hiểu biết sâu, rộng về hoạt động kiểm thử phần mềm \n- Ưu tiên các ứng viên có kinh nghiệm kiểm thử phần mềm với các REST/API Microservices hoặc Android và IOS là một lợi thế.\n- Ưu tiên Có chứng chỉ đào tạo về kiểm thử là 1 lợi thế \n- Ưu tiên ứng viên có kinh nghiệm trong công tác kiểm thử tự động là 1 lợi thế \n- Ưu tiên ứng viên đã có kinh nghiệm làm việc với các hệ thống Trục tích hợp/ESB, API Management, T24, Smart Vista là một lợi thế.\n\n5.Thu nhập cạnh tranh – Mức lương hấp dẫn theo năng lực và kinh nghiệm (thỏa thuận khi trúng tuyển).\n6.Phúc lợi toàn diện – Hưởng đầy đủ chế độ bảo hiểm theo luật lao động cho CBNV\n7.Chế độ nghỉ phép ưu đãi – 13 ngày/năm, bao gồm 01 ngày nghỉ sinh nhật.\n8.Môi trường làm việc năng động, linh hoạt, trẻ trung.\n9.Phát triển sự nghiệp – Cơ hội đào tạo, thăng tiến rõ ràng trong môi trường chuyên nghiệp được hỏi hỏi thực hiện nhiều dự án lớn.\n10.Hoạt động gắn kết đa dạng – Tham gia team building, hội thao, văn nghệ và nhiều sự kiện nội bộ hấp dẫn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 15 ngõ 112 đường Chùa Võ, Phường Dương Nội, Ha Dong, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1089, 648, 2, 'Sr Business Analyst (LOS sau vay/Core Bank/Core T24)', 'Top 3 reasons to join us\n- Attractive Compensation and Benefits\n- Limitless Opportunities for Professional Growth\n- Ownership of Cutting-Edge Projects\n\nJob description\n- Tham gia vào các dự án về LOS sau vay (Core Bank, Thẩm định, Định giá...)\n- Mô hình hóa yêu cầu phân tích theo công cụ đa dạng phù hợp (URD, SRS, Usecase, User story, Diagram…) để làm rõ yêu cầu giao tiếp với nghiệp vụ và các BU để làm rõ yêu cầu/phân tích/tài liệu hóa… và xác nhận với người dùng cuối\n- Phân tích về nghiệp vụ, đánh giá khả thi và đưa ra tư vấn về nghiệp vụ, kinh doanh, vận hành một cách tối ưu nhất\n- Đưa ra được yêu cầu về phạm vi công việc, đánh giá sơ bộ nguồn lực/thời gian thực hiện để phản hồi cho đơn vị có căn cứ đưa ra quyết định về việc có thực hiện yêu cầu hay không\n- Đề xuất và thiết kế giải pháp phù hợp với yêu cầu nghiệp vụ và tối ưu theo kiến trúc Microservice\n- Phối hợp với các bên liên quan (cán bộ phát triển/ cán bộ thiết kế) trong việc quyết định thiết kế các chức năng của giải pháp\n- Phối hợp với Giám đốc dự án (PM), Trưởng nhóm phát triển và bộ phận Quản lý chất lượng trong quá trình giám sát và quản lý các hạng mục công việc của dự án bao gồm việc kiểm soát chất lượng và xác nhận kết quả với các bên có liên quan\n- Xác định các vấn đề và rủi ro trong quá trình triển khai dự án, hỗ trợ trong các chiến lược giảm thiểu rủi ro và báo cáo lên các cấp quản lý nếu cần\n\nYour skills and experience\n- Học vấn: Tốt nghiệp Đại học ngành CNTT, Hệ thống thông tin hoặc các chuyên ngành có liên quan\n- Có tối thiểu 03 năm kinh nghiệm về BA, đặc biệt có kinh nghiệm tham gia triển khai dự án sản phẩm lending cho Ngân hàng/Công ty tài chính (Điều kiện bắt buộc). Ưu tiên có kinh nghiệm tham gia các dự án về LOS (Sau vay), Core (Core Banking, Core T24...), Thẩm định, Định giá...\n- Am hiểu về lĩnh vực tài chính/ngân hàng, am hiểu về lĩnh vực ngành/nghề đang cung cấp\n- Đề cao trách nhiệm trong công việc, ý thức chất lượng sản phẩm tốt; đam mê tìm tòi nghiên cứu học hỏi công nghệ mới, phát triển bản thân\n- Ưu tiên ứng viên có thể đọc hiểu tài liệu tiếng Anh\n- Hiểu biết và mong muốn làm việc trong một môi trường phát triển Agile, chuyên nghiệp\n\nWhy you\'ll love working here\n1. Chế độ chính sách\n- Lương thỏa thuận hấp dẫn + lương KPIs (theo tháng): 25,000,000 -40,000,000 VND\n- Thưởng cuối năm + thưởng Lễ/Tết + thưởng sinh nhật + thưởng đột xuất khi hoàn thành tốt nhiệm vụ.\n- BHXH + bảo hiểm chăm sóc sức khỏe cho nhân viên (F88 Care)\n\n2. Môi trường làm việc\n- Cơ hội làm việc tại Công ty Fintech về dịch vụ tài chính\n- Được làm việc trong môi trường trẻ năng động, luôn coi Công nghệ thông tin là yếu tố trọng tâm để phát triển\n- Áp dụng mô hình phát triển phần mềm theo Agile, Scrum\n- Môi trường làm việc cởi mở và năng động với các giá trị cốt lõi sâu sắc truyền cảm hứng làm việc đến nhân viên\n- Khuyến khích trao đổi ý tưởng, đề cao sự sáng tạo trong công việc\n- Cơ hội tham gia gắn kết với tập thể thông qua các hoạt động văn hóa sôi động: Teambuilding, Tất niên, 8/3, 20/10, Giáng sinh…\n\n3. Cơ hội phát triển\n- F88 cam kết cho bạn nền tảng vững chắc để học hỏi và phát triển\n- Tham gia đào tạo bài bản, chuyên nghiệp từ Học viện F88\n- Sẵn sàng trao quyền, cơ hội đột phá cho nhân viên\n\nThời gian làm việc: Từ 08h30 - 17h30, từ thứ 2 - thứ 6', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'G-Group Tower, 5 Nguyễn Thị Duệ, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1090, 649, 2, 'Blockchain Wallet Engineer (Java, Golang)', 'Top 3 reasons to join us\n- Flexible working time (Mon - Fri).\n- Attractive salary and bonus \n- Young & friendly colleagues.\n\nJob description\n- Participate in the architectural design of encrypted digital currency wallet systems.\n- Responsible for the development, deployment, maintenance, and optimization of wallet backend interfaces.\n- Handle security-related development and testing for wallets, including vulnerability prevention and audits.\n- Develop wallet solutions for various blockchains and derivative protocols to address user cryptocurrency deposits and withdrawals.\n- Lead backend development for trading systems and application systems.\n\nYour skills and experience\n- Bachelor’s degree or higher in Computer Science, Software Engineering, or related fields; 3-5 years of work experience.\n- Proficient in programming languages: Golang and Java.\n- Solid understanding of fundamental networking protocols: TCP/IP, UDP, HTTP, and WebSocket.\n- In-depth knowledge of blockchain principles, mechanisms, and cryptographic algorithms (e.g., Bitcoin, Ethereum).\n- Familiarity with data structures, algorithms, and expertise in cryptography, security protocols, and encryption algorithms.\n- Strong grasp of blockchain structures (e.g., Bitcoin, Ethereum), key management, and signing methods.\n- Experience with internet technologies such as MySQL, NoSQL, RPC, MQ (Message Queues), caching, and microservices architecture.\n- Excellent teamwork and cross-functional communication skills; proactive learning mindset with a focus on tracking open-source advancements.\n\nWhy you\'ll love working here\n- Flexible working time (Mon - Fri).\n- Attractive salary and bonus based on your capabilities and experience: $1000 - $2000.\n- A chance to practice English communication with our expat colleagues.\n- MacBook M2 provided on the first day and a 27in Dell monitor for everyone.\n- Young & friendly colleagues. - In-house gym & cafeteria.\n\nInterview Process (Offline):\n1st round Interview (1 hour)\n- Having interview with interviewers from related Department.\n- Note: Interview result will be sent to your email within 5 days.\n\n2nd round Interview (1 hour)\n- Having interview with General Manager for further discussion about the position and company culture.\n- Note: The interview result will be sent to your email within 5 days.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 9 Nguyễn Cơ Thạch, phường An Lợi Đông, Quận 2, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1091, 287, 2, 'DevOps Engineer (AWS, Cloud)', 'About Us \nCubicStack Solutions is a software development company with its namesake approach of three dimensional thinking upon various stages and levels of application design and development. We maintain in-house product that are in the FinTech space while also having anchor, long-term clients around the world across Asia and Europe in the Blockchain space. CubicStack also works with Venture Capitalist firms to invest in and innovate new products and technologies. Now we are now expanding and looking for DevOps Engineer\n\nResponsibilities\n- Build, manage and maintain cloud infrastructure (AWS, DigitalOcean)\n- Building CI/CD for deployment\n- Work with the development team to deploy new features, bugs fix\n- Monitor, troubleshoot and improve system availability, performance and security\n- Manage and config domains\n\nYour skills and experience\n- Minimum 2-years of working experience as DevOps engineer or System Engineer/System Administrator (Linux)\n- Has at least 1 year experience with AWS architecture and services (VPC, EC2, ALB, ECS, S3, RDS, Lambda, Cloudwatch)\n- Experience in using Terraform to deploy and manage infrastructure\n- Working knowledge with Docker and using Docker container clusters in production\n- Experience in building and operating CI/CD pipelines using Git on cloud services (Bitbucket, Gitlab...)\n- Knowledge of administration Database (MySQL, MongoDB)\n- Familiar with Monitoring and Alerting tools: Grafana, Prometheus, AWS Cloud Watch...\n- Working knowledge of scripting using Bash/Python\n- Understanding of networking and firewall concepts\n- Good problem solving and troubleshooting skills\n- Ability to work independently and on a team\n- Carefulness and Responsibility\n\nWhy you\'ll love working here\n- Attractive salary - 13rd month salary and performance bonus\n- A great team behind you - you\'ll work with great people who love solving problems \n- Equipment provided includes Macbook Pro and widescreen monitor\n- Premium healthcare package\n- Monthly team dinners and annual company trips\n- Opportunity to greatly improve English skills with CubicStack’s international client\n- Embracing multiple, new technical stacks to accelerate business development\n- International Working Environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Charmington La Pointe Officetel Apartments, 181 Cao Thang St, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1092, 329, 2, 'Fullstack Developer (Backend focus Java, .NET, NodeJS)', 'Job Description – K&M Holdings\n\nJob title: Fullstack Developer (Backend focus)\nLocation: Truong Cong Giai, Cau Giay, Hanoi, Vietnam\nTerms: Full-time\nSalary/rate: Up-to $1750 plus benefits\n\nProposition:  \n• JOB OFFER after 1 ROUND INTERVIEW\n• Mentorship by seasoned Tech Leads & free access to modern learning courses\n• While NOT mandatory, strong English reading/listening skills are highly recommended for ongoing course learning & documentation review\n\nAbout us: K&M Holdings is a dynamic startup in Hanoi specializing in SaaS/AaaS solutions. Our flagship products include an IP Telephony platform built on Asterisk, a coalition loyalty app, and AI-powered customer care agents.\n\nAbout the role:\nIn this role, you will be responsible for building core backend services for our products from feature-oriented logic to API instrumentation, metering pipeline, pricing logic and expose aggregated usage data for DevOps team. Additionally, you might be required to get involved in frontend development using standard frameworks.\n\nResponsibilities: \n• Write clean, maintainable backend code in backend-focus tech stacks (NodeJS, Java, C#, Go…). Use modern frameworks (e.g. Express, Spring Boot) and database technologies (SQL/NoSQL) to build scalable services. Participate in design reviews and maintain high code quality.\n• Work closely with product managers, QA, frontend engineers, and a dedicated DevOps team. Focus on application logic – the DevOps team handles deployment, CI/CD, and infrastructure.\n• Instrument and record resource usage (API requests, token counts, compute time) for each customer and license. Build automated reporting to summarize usage for customers and internal finance teams.\n• Develop customer-facing and internal APIs or microservices for usage and billing data. Ensure usage data flows securely between on-prem or client deployments and the central billing system.\n• Implement enterprise licensing features such as license key validation and enforcement of subscription terms. Support flat subscriptions alongside consumption tiers, and handle on-premise deployments that periodically report usage back to the cloud for billing.\n• Develop and maintain the web application and occasionally contribute to mobile app development using cross-platform frameworks.\n\nYour skills and experience\n• Bachelor’s degree in Computer Science or a related field.\n• 4+ years of professional software development (mid–senior level) with significant backend focus.\n• Proficiency in one or more backend languages: Node.js, Go, C# or Java. Additionally, proficiency in back-end frameworks such as: ExpressJS, KoaJS, NestJS, Java Springboot, Gin, Fiber.\n• Strong understanding of API designs and data modelling (SQL or NoSQL databases). Familiarity with frontend frameworks (React or Vue) for basic integration.\n• Experience designing subscription or usage-based billing systems, metering, or analytics pipelines is highly desirable. Understanding of tokenized usage metrics or compute/time-based billing shows strong alignment.\n• Experience with containerization & usage-analytics & monitoring tools (Docker/Kubernetes & Prometheus/Grafana).\n\nWhy you\'ll love working here\n• Salary: Up to $1750 plus benefits\n• JOB OFFER after 1 online interview round\n• Clear career path & ESOP opportunities upon product launch\n• Mentorship by seasoned Tech Leads & free access to modern learning courses\n• While NOT mandatory, strong English reading/listening skills are highly recommended for ongoing course learning & documentation review\n• Social, Health, and Unemployment Insurance provided after probation period\n• Annual leave in accordance with regulations\n• Public holidays off as per labor laws\n• Holiday bonuses: 13th-month salary bonus\n• Team building activities, monthly birthday celebrations, etc.\n• Support for parking fees, lunch, beverages, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '66 Trương Công Giai, Dịch Vọng, Hà Nội, Vietnam, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1093, 329, 2, 'Automation/Manual Tester & Business Analyst', 'Job Description – K&M Holdings\n\nJob title: Automation/Manual Tester & Business Analyst\nLocation: Truong Cong Giai, Cau Giay, Hanoi, Vietnam\nTerms: Full-time\nSalary/rate: Up-to $1500 plus benefits\n\nProposition:\n• JOB OFFER after 1 ROUND INTERVIEW\n• Mentorship by seasoned Tech Leads & free access to modern learning courses\n• While NOT mandatory, strong English reading/listening skills are highly recommended for ongoing course learning & documentation review\n\nAbout us:\nK&M Holdings is a dynamic startup in Hanoi specializing in SaaS/AaaS solutions. Our flagship products include an IP Telephony platform built on Asterisk, a coalition loyalty app, and AI-powered customer care agents.\n\nAbout the role:\nIn this role, you will be working as a member of the centralized Support team that support all 3 flagship products. You will design and execute automated test scripts for our AI-enhanced Web/PWA and mobile applications, while also engaging directly with clients to gather and document requirements. This position calls for a hands-on engineer/analyst who thrives in a fast-paced start-up environment, bridging the gap between cutting-edge technology and customer success.\n\nResponsibilities:\n• Test Automation: Develop, execute, and maintain automated test scripts using frameworks and tools (e.g. Selenium, Cypress, Appium) to ensure product quality. Analyse test results, log defects, and collaborate with developers to resolve issues.\n• Test Planning: Create and update test plans, test cases, and acceptance criteria aligned with project requirements and AI-related workflows. Lead functional, regression, and integration testing efforts to validate Web/PWA and mobile features.\n• Requirements Gathering: Conduct client interviews and workshops to elicit and document business/product requirements. Analyse current processes and identify areas for improvement. Ensure requirements are clear, complete, and aligned with product goals.\n• Specification & Story Writing: Translate client requirements into well-defined user stories, technical specifications, and process flows for the development team. Collaborate in Agile ceremonies (sprint planning, backlog grooming) to prioritize work based on business value.\n• Stakeholder Collaboration: Work closely with product managers, designers, and engineers to clarify requirements and test scenarios. Act as a bridge between business stakeholders and technical teams, ensuring both sides understand each other’s needs. Participate in client demos and UAT sessions to gather feedback.\n• CRM and AI Feature Support: Leverage knowledge of CRM systems (e.g. Salesforce, HubSpot) to validate data flows and integrations related to client solutions. Stay abreast of AI/ML concepts and help test AI-driven features (e.g. recommendation engines, ML workflows) to ensure they meet requirements.\n• Documentation & Reporting: Maintain clear documentation of test processes, results, and product workflows. Provide regular status updates and metrics to the team, and assist in post-release support if needed.\n\nYour skills and experience:\n• Bachelor’s degree in Computer Science, Engineering, or a related field (or equivalent experience).\n• Experience: 3+ years of professional experience combining software QA/Automation and business analysis roles, ideally in a technology or product-driven company. Mid-senior level candidates should show a track record of taking ownership and driving projects end-to-end.\n• Technical Skills: Proficiency with automation testing tools (e.g. Selenium, JUnit, Cypress, Appium) and programming/scripting languages (e.g. Java, Python, JavaScript). Strong understanding of SDLC and Agile methodologies.\n• Analytical & Communication Skills: Excellent analytical and problem-solving abilities, with strong verbal and written communication skills. Able to distill complex concepts for both technical and non-technical audiences.\n• Business Analysis: Experience writing user stories, acceptance criteria, and functional specifications. Skilled at requirements gathering, process mapping, and translating business needs into technical deliverables.\n• Client-Facing: Comfortable engaging with clients or stakeholders to elicit requirements and present findings. Strong interpersonal skills and a service-oriented mindset.\n• CRM & Domain Familiarity: Working knowledge of CRM platforms and how business processes (sales, support, etc.) flow through them. Ability to quickly learn domain contexts to test relevant scenarios.\n• Self-Driven: Adaptable and proactive, with the ability to work in a fast-changing start-up environment. Comfortable juggling multiple projects and wearing multiple hats.\n• AI/ML Testing: Familiarity with AI and machine learning concepts or workflows. Experience testing data pipelines or AI-driven application features.\n• PWA/Mobile Expertise: Prior experience with Progressive Web Apps and mobile app development/testing. Knowledge of cross-platform issues and mobile-specific test strategies.\n• Automation Frameworks: Exposure to Behavior-Driven Development (BDD) tools (e.g. Cucumber) or CI/CD pipelines for test automation.\n• Certifications & Tools: ISTQB, CBAP, or equivalent certifications are a plus. Experience with project tools like Jira, Confluence, or similar is advantageous.\n• Agile Mindset: Demonstrated ability to thrive in Agile teams, embrace rapid iteration, and contribute to continuous improvements.\n\nWhy you\'ll love working here:\n• Salary: Up to $1500 plus benefits\n• JOB OFFER after 1 online interview round\n• Clear career path & ESOP opportunities upon product launch\n• Mentorship by seasoned Tech Leads & free access to modern learning courses\n• While NOT mandatory, strong English reading/listening skills are highly recommended for ongoing course learning & documentation review\n• Social, Health, and Unemployment Insurance provided after probation period\n• Annual leave in accordance with regulations\n• Public holidays off as per labor laws\n• Holiday bonuses: 13th-month salary bonus\n• Team building activities, monthly birthday celebrations, etc.\n• Support for parking fees, lunch, beverages, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '66 Trương Công Giai, Dịch Vọng, Hà Nội, Vietnam, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1094, 650, 2, 'Fullstack  Developers (.NET, C#, DevExpress, SQL)', 'Top 3 reasons to join us\n• Môi trường làm việc hiện đại, chuyên nghiệp.\n• Chính sách đầu tư đào tạo và nâng cao kỹ năng\n• Lương Thỏa thuận theo năng lực.\n\nJob description\n• Hợp tác chặt chẽ với chuyên viên phân tích nghiệp vụ để chuyển đổi yêu cầu của người dùng cuối thành các giải pháp số hóa cụ thể trong hệ thống ERP.\n• Viết mới hoặc sửa đổi các chức năng hiện có trên hệ thống ERP cũ sử dụng VB.Net và SQL Server.\n• Tối ưu hóa mã nguồn và truy vấn SQL để đảm bảo hiệu suất và khả năng mở rộng của hệ thống ERP.\n• Làm việc chặt chẽ với các thành viên trong nhóm phát triển và các bộ phận khác để đảm bảo công việc được hoàn thành một cách nhanh chóng và hiệu quả.\n• Chia sẻ kiến thức và kinh nghiệm với đồng nghiệp để nâng cao hiệu suất làm việc của toàn đội.\n• Nghiên cứu và áp dụng các công nghệ và xu hướng mới trong lĩnh vực ERP để cải tiến hệ thống.\n• Tham gia vào các khóa học đào tạo và tự học để không ngừng nâng cao kỹ năng cá nhân.\n• Tuân thủ các quy trình và tiêu chuẩn lập trình cũng như bảo mật thông tin do tổ chức đặt ra.\n• Chịu trách nhiệm báo cáo tiến độ công việc cho cấp quản lý.\n• Viết tài liệu hướng dẫn, tư vấn, hỗ trợ và giải quyết các yêu cầu của người dùng cuối để họ hiểu và sử dụng hệ thống ERP hiệu quả.\n• Hỗ trợ trong việc tìm kiếm và đánh giá các giải pháp ERP phù hợp với nhu cầu của công ty.\n• Có kinh nghiệm triển khai phần mềm ERP đóng gói như SAP S/4HANA, SAP B1 hoặc Microsoft Dynamics là một lợi thế lớn.\n\nYour skills and experience\n• Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các lĩnh vực liên quan.\n• Đã có kinh nghiệm triển khai và phát triển hệ thống ERP của các công ty sản xuất.\n• Tối thiểu 3-5 năm kinh nghiệm phát triển phần mềm, ưu tiên có kinh nghiệm làm việc với hệ thống ERP.\n• Thành thạo ngôn ngữ lập trình C# và .NET Framework cho Windows Forms.\n• Kiến thức vững về lập trình hướng đối tượng (OOP).\n• Kinh nghiệm phát triển ứng dụng web với HTML5, CSS3, JavaScript, và các framework như Angular, React, hoặc Vue.js\n• Kiến thức về cơ sở dữ liệu quan hệ như SQL Server, MySQL hoặc Oracle.\n• Kỹ năng phân tích yêu cầu người dùng và chuyển đổi chúng thành các giải pháp kỹ thuật.\n• Khả năng giải quyết vấn đề một cách sáng tạo và hiệu quả.\n• Khả năng giao tiếp tốt để làm việc hiệu quả với các nhóm phát triển và khách hàng.\n• Kỹ năng làm việc nhóm mạnh mẽ và khả năng thích nghi với môi trường làm việc động.\n• Kinh nghiệm làm việc trong môi trường phát triển phần mềm theo mô hình Agile/Scrum là một lợi thế.\n• Có khả năng tự học và cập nhật các công nghệ mới.\n• Tinh thần trách nhiệm cao và khả năng làm việc độc lập.\n\nWhy you\'ll love working here\n• Môi trường làm việc hiện đại, chuyên nghiệp, năng động, thân thiện, nhiều điều kiện, học hỏi và thăng tiến\n• Lương Thỏa thuận theo năng lực.\n• Lương tháng 13, lương thâm niên quy định công ty\n• Được hỗ trợ cơm trưa.\n• Được hưởng đầy đủ các chế độ dành cho người lao động theo như quy định pháp luật hiện hành (nghỉ phép, lễ, tết,…)\n• Được hưởng các chính sách phúc lợi theo quy định của Công ty: sinh nhật cá nhân, cưới hỏi, thăm hỏi ốm đau, du lịch nghỉ mát, khám sức khỏe định kỳ hằng năm.\n• Tham gia đầy đủ BHYT, BHXH, BHTN theo quy định và các quyền lợi khác theo quy định của luật lao động.\n• Thời gian làm việc: 7h45 đến 16h45, từ thứ 2 - thứ 7, nghỉ 2 ngày thứ 7 trong tháng\n• Thưởng chuyên cần 800.000 đồng/tháng\n• Công ty có chính sách đầu tư đào tạo và nâng cao kỹ năng nhân sự nắm giữ vị trí quản lý trong tương lai.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '100 Đường 400, P. Tân Phú, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1095, 651, 2, 'Senior Java Developer (Spring Boot,JavaEE,Good English)', 'About the job:\nJoin a dynamic team of Java developers working on a cutting-edge global platform for processing thousands of invoices per second. This platform focuses on identities, payments, finance, and documents and offers an opportunity to shape the future of electronic trading applications.\n\n• Collaborate closely with the Product Manager to create exceptional (mobile) applications and enhance the overall experience for Unifiedpost Payments & Identity customers.\n• Ensure the implementation of secure solutions that meet the platform\'s requirements.\n• Conduct code reviews, establish and maintain secure CI/CD operations, and foster collaboration with other units and programs within Unifiedpost Group.\n\nThis is what you win:\nWe offer a competitive salary package based on your experience and qualifications, along with flexible hybrid working hours. As a fintech company, our environment is fast-paced and diverse, providing daily learning opportunities.\n\nWe would be happy to see:\n• Experience developing Java applications (min 5 year for senior level), with a strong focus on Java 17 or a more recent version.\n• Excellent verbal and written communication skills in English (if possible experience working with native speaking English or Western European colleagues)\n• Adaptability, a growth mindset, and the ability to thrive in a scaling organisation.\n• Be passionate about software development; always curious about new technologies and development methods and share them with your colleagues;\n• Be proactive, take ownership, focus on problem solving more than problem finding and think about continuous improvement – always find new tools and methods for yourself and your colleagues;\n• Value team effort, be a team player and deliver autonomously with little supervision;\n\nRequired experience and knowledge\n• Practical experience in Java frameworks & libraries: Spring/Spring Boot, JavaEE\n• Experience with consuming and creating REST web services\n• Experience applying security practices in software development\n• Focus on creating and using JUnit tests as part of a CI/CD operations\n• Proficiency in git version control system and maven\n\nNice to have experience and knowledge\n• Experience with applying encryption, signing and hashing techniques\n• Experience with Docker-based service development.\n• Familiarity with Kubernetes and container orchestration, including Minikube.\n• Familiarity with tools like Jenkins, Maven, Jira\n• Familiarity with code reviewing best practices\n• Familiarity with standards such OAuth 2.0, REST, ...\n• Experience with Google Cloud Platform (GCP)\n\nWhy you\'ll love working here\n• Office hours: 9:00 AM – 12:00 PM, 1:00 PM – 06:00 PM, off on Saturday and Sunday. Annual holidays leave will be following Vietnam law and as company regulations.\n• 25 days of annual leave\n• Flexible working hours\n• Competitive remuneration package\n• 13th salary\n• 14th salary (applicable for employees who have worked at UPVN for over 3 years)\n• Social insurance, health insurance, and unemployment insurance will be under Labor Law.\n• Generous private medical health insurance for employees & family members\n• Dynamic, young & international environment\n• Team building activities & outing\n• Brand new & state-of-art Agile office\n• Opportunity for traveling & training in Europe', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '28th floor, Opal Tower, 92 Nguyen Huu Canh Street, Ward 22, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1096, 211, 2, 'Senior ERP Business Analyst', '1. Phân tích nghiệp vụ:\n- Thu thập và phân tích yêu cầu nghiệp vụ từ các bộ phận liên quan, bao gồm Tài chính Kế toán, Quản lý kho, Quản lý tài sản cố định.\n- Hiểu rõ các quy trình nghiệp vụ hiện tại và đề xuất giải pháp tối ưu hóa trên hệ thống ERP.\n- Viết tài liệu mô tả nghiệp vụ (BRD) chi tiết và đầy đủ.\n\n2. Triển khai hệ thống:\n- Tham gia vào quá trình triển khai hệ thống ERP, bao gồm cấu hình, cài đặt, thử nghiệm và vận hành.\n- Hỗ trợ đội ngũ kỹ thuật trong việc giải quyết các vấn đề kỹ thuật liên quan đến nghiệp vụ.\n- Đảm bảo hệ thống ERP được triển khai theo đúng yêu cầu và phù hợp với nhu cầu của doanh nghiệp.\n\n3. Đào tạo và hỗ trợ:\n- Đào tạo người dùng về cách sử dụng hệ thống ERP.\n- Hỗ trợ người dùng giải quyết các vấn đề phát sinh trong quá trình sử dụng hệ thống.\n- Cập nhật tài liệu hướng dẫn sử dụng hệ thống.\n\n4. Quản lý dự án:\n- Lập kế hoạch và theo dõi tiến độ dự án triển khai hệ thống ERP.\n- Báo cáo tiến độ dự án cho ban lãnh đạo.\n- Giải quyết các vấn đề phát sinh trong quá trình triển khai dự án.\n\nYÊU CẦU ỨNG VIÊN\n- Tốt nghiệp Đại học chính quy chuyên ngành Kinh tế, Tài chính - Kế toán, Quản trị kinh doanh, Công nghệ thông tin hoặc các ngành liên quan.\n- Có ít nhất 5 năm kinh nghiệm làm việc trong lĩnh vực phân tích nghiệp vụ hoặc triển khai hệ thống ERP (ưu tiên kinh nghiệm với hệ thống Oracle EBS);\n- Có kiến thức chuyên môn về nghiệp vụ tài chính kế toán, quản lý nhập xuất kho, quản lý tài sản cố định.\n- Có khả năng phân tích, tổng hợp và giải quyết vấn đề tốt.\n- Kỹ năng giao tiếp và thuyết trình tốt.\n- Khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n\nƯu tiên:\n- Ứng viên có kinh nghiệm triển khai hệ thống ERP cho các doanh nghiệp cùng ngành.\n- Ứng viên có chứng chỉ BA quốc tế (CBAP, CCBA) là một lợi thế.\n- Ứng viên có khả năng sử dụng thành thạo các phần mềm Microsoft Office (Word, Excel, PowerPoint).\n\nWhy you\'ll love working here\n- Chứng khoán SSI nhận 3 giải thưởng nơi làm việc tốt nhất:\n- Highly competitive remuneration package: Attractive monthly salary, 13th month salary, KPIs cash bonus, Public holiday cash bonus, Birthday gift, Lunar new year gift,...\n- Premium AON healthcare insurance and full labor insurance\n- 12 days Annual leave + 2 days sick leave with full paid\n- Luxury team-building trip and varied engagement activities\n- Joining the leisure clubs: Football, E-Sport, Running, Gym, Yoga....\n- Fully sponsored training to build your career\n- Professional, open minded and supportive working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '1 Luong Yen, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1097, 644, 2, 'Business Analyst (BA)', 'Các công việc chính:\n- Phân tích thiết kế sản phẩm mới\n- Cải tiến sản phẩm đã có\n- Hỗ trợ thủ tục bàn giao, nghiệm thu, thanh toán\n\nChi tiết:\nPhân tích thiết kế sản phẩm mới:\n- BA đóng vai trò trung tâm trong việc phát triển sản phẩm mới, cụ thể:\n- Khảo sát yêu cầu của khách hàng. Thường khách hàng sẽ do AM của Viettel đi tiếp xúc trực tiếp, chỉ cần làm việc với AM của Viettel, có thể trao đổi từ xa.\n- Tham khảo sản phẩm các đối thủ trên thị trường, các sản phẩm tương tự của nước ngoài.\n- Xây dựng Danh sách tính năng của sản phẩm.\n- Thiết kế layout sản phẩm\n- Làm việc với designer để thiết kế giao diện sản phẩm\n- Làm việc với đội dev để xây dựng quy trình\n- Làm việc với quản trị dự án để xây dựng lộ trình phát triển sản phẩm\n- Làm việc với đội test để kiểm thử sản phẩm\n- Phối hợp với khách hàng để triển khai, nghiệm thu sản phẩm\n\nCải tiến sản phẩm đã có:\n- Đánh giá các tính năng còn chưa tốt của sản phẩm cũ, tham khảo các sản phẩm tương tự trên thị trường để đề ra phương án nâng cấp, sau khi thống nhất phương án nâng cấp thì tiến hành các bước tương tự như việc thiết kế sản phẩm mới\n\nHỗ trợ thủ tục bàn giao, nghiệm thu, thanh toán:\n- BA cần học cách xây dựng báo giá theo chuẩn của Bộ TTTT, phối hợp với đội DEV, Designer, Test để xây dựng các loại tài liệu bàn giao theo quy định của Viettel.\n- Ngoài ra, Nhân viên BA cần có kiến thức cơ bản về Lập trình web (backend) bằng PHP, trên framework do công ty tự phát triển hơn 13 năm, gồm các nhóm ứng dụng chính: Website doanh nghiệp, trường học, Portal bộ ban ngành, LMS, HRM, TMĐT.\n- Quản lý source code bằng SVN.\n- Có leader hướng dẫn từng bước.\n- Quản lý công việc bằng công cụ quản trị dự án nội bộ.\n- Làm việc với bộ phận kiểm thử và phát triển sản phẩm để tối ưu, sửa lỗi, phát triển chức năng mới.\n\nYour skills and experience:\n- Từ 3 năm kinh nghiệm ở vị trí BA hoặc tương đương\n- Có kiến thức về UML, biết vẽ sơ đồ usecase, sơ đồ hoạt động\n- Biết cách vẽ mockup- Biết cách vẽ mockup\n- Có kiến thức cơ bản về thiết kế CSDL\n- Biết cách sử dụng 1 số phần mềm quản lý bất kỳ\n- Hiểu về các quy tắc UI - UX\n- Có khái niệm về thiết kế sản phẩm cho App, Web\n- Có khả năng giao tiếp tốt với đối tác\n- Có kinh nghiệm làm việc nhóm\n\nWhy you\'ll love working here:\n- Thu nhập upto 20M;\n- 6 tháng xét tăng lương 1 lần.\n- Sau 2 tháng thử việc sẽ có đánh giá kết quả của leader và được xem xét nâng lương, ký hợp đồng lao động chính thức, đóng bảo hiểm.\n- Được tham gia vào các dự án lớn như: hệ thống học trực tuyến K12Online, cổng thanh toán BiPay, Chuyển đổi số VP TW Đảng, ...\n- Một năm được nghỉ 12 ngày phép\n- Thưởng lương tháng 13\n- Môi trường làm việc năng động, sáng tạo với đội ngũ CBNV đầy nhiệt huyết. Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding, sự kiện công ty, tiệc mặn ngọt,….\n- Thời gian làm việc: T2-T7 (T7 nghỉ cách tuần). Buổi sáng: 8h-12h, buổi chiều: 13h30-17h30', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tháp Đông, CC Học Viện Quốc Phòng, đường Nguyễn Văn Huyên kéo dài, Xuân La, Tây Hồ, Hà Nội, Tay Ho, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1098, 432, 2, 'Mid/Senior QC Engineer (Tester)', 'Top 3 reasons to join us\n1. Attractive Package and Dedication bonus\n2. Hybrid and flexible working environment \n3. Working directly with Agile global teams\n\nJob description\n- Analyze, design, create, and execute C#/Javascript automated test cases for back end microservices.\n- Create functional testing in automated tests, including unit testing, API testing, integration testing, end-to-end testing, regression tests, etc.\n- Perform manual testing if proper and carry out non-functional testing.\n- Collaborate with developers, BAs, and scrum teams to ensure thorough understanding and coverage of testing requirements.\n- Identify, log, and track defects, working closely with developers and team to resolve issues.\n- Code review and educate developers to create good automated tests.\n- Collaborate closely as part of the development team by providing a client viewpoint.\n- Actively participate in sprint planning and other Agile ceremonies, providing insights into quality and testing progress.\n- Research new technologies available and its proper application; make suggestions/contributions for the improvement of software testing/quality/delivery.\n\nYour skills and experience\nMust have:\n- Strong experience in Cypress, Playwright, or Selenium.\n- Solid experience with API testing, unit testing, and integration testing. \n- Experience with SQL databases and be able to write SQL script. \n- Good understanding of the software development lifecycle (SDLC) especially in Agile environments. \n- Strong communication and collaboration skills, with the ability to work effectively in a team. \n- A confident and dynamic attitude with a proactive approach to problem-solving. \n- A willingness to learn and adopt new automation technologies is a significant advantage.\n\nNice to have:\n- Can understand C# code and discuss with developers the issues in C# code. \n- Experience with understanding complicated software systems, microservice architecture. \n- Experience with event driven architecture – Kafka, service bus etc. \n- Experience with Accessibility Testing or Non-functional testing such as Performance testing, Resilience testing, Security testing. \n- Experience with APM tools such as Datadog. \n- Experience with CI/CD, Azure DevOps. \n- Experience with code commit and code review. \n\nSoft skills:  \n- Effective verbal English skills in video conferences and face-to-face communication.\n- Know how to manage tasks and perform context switching\n- Have a resilience mindset, handle stress well.\n- Proactive and self-learning mentality.\n\nWhy you\'ll love working here\n1. Attractive and competitive performance-based compensation package\n2. Generous year-end 13th-month bonus\n3. Loyalty and annual dedication rewards\n4. 12 annual leave days, 11 public holidays, 1 Christmas day off and 5 sick leave days\n5. Flexible check-in time, 1-day remote work per week, and the freedom to work from any of our offices in Da Nang, Hue, or Ha Noi\n6. Onsite opportunity in Australia\n7. Comprehensive healthcare package with premium insurance and annual health check-ups\n8. Breakfast is available at office in early morning and snack in late afternoon\n9. Team-building allowance and annual company trips for a fun and connected workplace\n10. Sports & hobby clubs with football, badminton, biking, running, chess, or music band groups\n11. Continuous learning & development with exclusive technical & soft skills training, English classes, and technical clubs\n12. Financial aid for marriage, newborns, and bereavement to support you through every stage of life.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '364 Cong Hoa, Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1099, 462, 2, 'Tester (QA/QC)', 'Job description\n- Analyze business requirements and collaborate with the BA/Dev teams to clarify process flows.\n- Understand the business logic to develop suitable test plans and test cases for each module.\n- Perform manual or automated testing to ensure product quality.\n- Log and manage bugs, track fixes, and validate resolutions.\n- Contribute to improving testing processes and product quality.\n\nYour skills and experience\n- Minimum 2–4 years of experience in software testing.\n- Strong analytical skills and understanding of business requirements are a must.\n- Ability to write comprehensive and clear test cases.\n- Proficient in tools such as Jira, TestRail, Postman, etc.\n- Detail-oriented, responsible, able to work independently and in a team.\n\nPreferred:\n- Experience in fintech or AI/ML projects is a plus.\n- Knowledge or experience in API testing, performance testing, or test automation (e.g., Selenium, Katalon).\n\nWhy you\'ll love working here\n- Professional work environment with friendly colleagues.\n- Opportunities to work on cutting-edge projects (AI, data processing, digital finance, etc.).\n- Performance-based allowance, bonus.\n- Career advancement opportunities to QA Leader role.\n- Full-salary-based Social Insurance Contribution.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'No 58, Huynh Man Dat Street, Ward 19, Binh Thanh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1100, 652, 2, 'Senior Java API Developer (Aws, Microservices)', 'Top 3 reasons to join us\n• We CARE about you and always put FAIRNESS first\n• Flexible & open international working environment\n• Chance to work onsite with the team\n\nJob description\n\nABOUT THE TEAM\nOur team is responsible for creating a brand of new digital financial platforms and apps that are highly reliable and scalable using modern engineering practices. You will be joining a project which talented software engineers in our Digital Bank Build team who is responsible for designing, building, and maintaining the new digital banking platform and the customer channels. As part of the team, you will be responsible for implementing software features, involve in technical designs, and writing tests to ensure the high-quality delivery of the product. The teams operate in Scrum and DevOps models.\nWe’re looking for top engineers out there! During the interview process, we will test your coding and design skills to assess your experience and depth of knowledge. Don’t worry our interview process will be fun!\n\nWE ARE LOOKING FOR A PERSON, WHO WILL​\n• As a backend engineer, you will be working within a specific problem where you will design, develop, and deploy backend services with a focus on scalability, high availability, and low latency.\n• Drive the efficient delivery of change through analysis, definition, and documentation of requirements whilst identifying potential solutions using agile delivery frameworks.\n• Solve complex technical and business problems and learn new technology and frameworks.\n• Be part of a team that will take full responsibility for the features you own.\n• Design, develop, test, deploy, monitor, and improve, you are responsible for the full life-cycle of your product – build it, own it.\n\nYour skills and experience\nA POTENTIAL CANDIDATE WILL HAVE\nYou will be a perfect match if your profile ticks some below items:\nMust-have:\n• A pragmatic mindset.\n• Outstanding problem-solving ability, eagerness to learn, and curiosity.\n• A few years of software development experience with one or more general-purpose programming languages.\n• Strong database and schema design for large-scale applications.\n• Adaptable attitude and personality that is ready for continuous change.\n• Collaboration and culture fit in the Agile experience will be an advantage.\n• Good English skills.\nNice to have:\n• Experience in developing distributed systems on top of micro-services architecture, event-driven architecture using Java, Spring and Spring boot, Kafka, Redis, etc. is a big plus\n• Experience in AWS, Ansible, Packer, Docker, Rancher, and K8s is a big plus\n• Experienced in automated testing frameworks is a plus\n• Good English listening and speaking is a big plus\n• Experience working in the banking and the financial domain is a plus.\n\nWhy you\'ll love working here\nAttractive Benefits:\n• 13th-month salary bonus provided to all staff members.\n• Comprehensive healthcare insurance package for you and your dependents.\n• Annual health check-up included.\n• 12 days of annual leave per year, with the opportunity for 1 additional day per year, up to a maximum of 18 days. Additionally, 3 special Restaff holidays are granted on December 24th, 25th, and 26th.\n• Hybrid working model allowing for 1 day per week of remote work.\n• English-speaking working environment.\n• Overseas business trip opportunities available.\n• Sponsorship and encouragement for staff members to pursue further education through coverage of tuition fees and examination costs.\n• Product-oriented approach with an agile project management style, offering a dynamic work environment and the chance to gain expertise in the latest technologies.\n• Regular gathering parties and team-building activities.\n• Complimentary coffee (including cappuccino, cafe latte, latte macchiato, etc.), milk, and juice.\n• Working hours from 9 am to 6 pm, Monday to Friday, with a one-hour lunch break and a thirty-minute break in the afternoon.\n• Annual Performance Appraisal opportunities.\n• English communication skills training provided.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Centec Tower - 72-74 Nguyen Thi Minh Khai, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1101, 653, 2, 'Senior Java Engineer (Java, AWS, English)', 'About us\nAs a Fortune 500 company, we are on the front edge of an IT transformation for how people work and deliver solutions. As part of our commitment to making things better, we are focused on enabling and supporting your career development and growth. With dedicated, tech-specific learning programs, self-paced learning options, and access to conferences and professional development resources we want you to build a career that sets you up for success. As part of our tech and digital teams you’ll enjoy: A progressing tech stack that champions the use of emerging technologies. Opportunities for continuous learning and growth. A diverse, inclusive, and collaborative team and environment. Work life balance and flexible work arrangements.\n\nJob Responsibilities\n- Collaborate with Scrum Masters, Product Owners, and peer engineers to iteratively create technical solutions that meet business and technical requirements.\n- Work as part of an innovative team, acting as a strong advocate for continuous integration, continuous delivery, quality assurance, and test/process automation. Be skilled in troubleshooting production issues and coordinating with peer engineers to streamline code deployment.\n- Handle end-to-end development, including coding, testing, and debugging during each cycle.\n- Enjoy experimenting with the latest innovative trends in front-end and back-end development.\n- Work under limited supervision, demonstrate ability to debug new software or significant enhancements to existing software to achieve desired results and documents appropriate aspects of those deliverables.\n- Support feature technical implementation.\n- Create and maintain technical documentation.\n- Research technology and bring new ideas to the team.\n- Possess a deep understanding of the product and business goals which you can translate into technology decisions.\n\nYour skills and experience\n- Bachelor’s degree in Computer Science, Software Engineering, or a related field (or equivalent experience).\n- 3+ years of experience with Spring Framework (Spring Boot, Spring Data, Spring Security).\n- Strong understanding of RESTful API design principles.\n- Proficiency in Java programming language.\n- Experience with AWS cloud platform (ECS Fargate, EC2, Lambda, ALB, API Gateway).\n- Experience with implementing ApigeeX Oauth2.0.\n- Experience with database management systems (RDBMS, NoSQL) like Oracle, SQL Server, PostgreSQL, DynamoDB.\n- Familiarity with API testing frameworks (Postman, JUnit)\n- Experience with CI/CD practices and tools (Jenkins pipelines, GitHub Actions-based workflows etc.).\n- Proficient in English and Vietnamese languages.\n\nWhy you\'ll love working here\n- You will love working at Liberty Vietnam:\n- A professional, dynamic and international working environment\n- Advanced Technology Approach\n- Opportunities for career development\n- Attractive benefits\n\nCompany\'s Benefits\nFinancial support\n- Probation with full salary\n- Lunch allowance\n- Transport allowance\n- Telephone allowance\n- KPIs bonus\n- Performance rewards and awards\n\nInsurance\n- Social Insurance\n- Health Insurance\n\nEvents and activities\n- Year End party\n- Team Building\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '45 Ly Tu Trong, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1102, 342, 2, 'Fresher/ Junior Security Engineer (English Speaking)', 'Responsible for engineering, implementing, and monitoring security solutions for the protection of computer systems, networks, and information. This position involves additional support requirements such as 24-hour on-call coverage for High-Severity Security Incidents and translation of security messages from English to Vietnamese.\n\nRole Responsibilities and Typical Activities (Duties & Responsibilities)\n\nProvide analysis of Endpoint Protection logs, as well as logs from various types of security sensors and controls systems\nPerform Root Cause Analysis of security incidents for further tuning and improvement of detection and response effectiveness.\nDevelop, execute, and track the performance of security measures to protect information, network infrastructure and computer systems.\nConfigure, troubleshoot, and maintain security software and hardware.\nEducate and train employees on security best practices.\nEnsure that the organization’s data and infrastructure are protected by enabling the appropriate security controls and identifying security gaps that may exist.\nPerform regional phishing campaigns.\nHours:  Would like person to have 2-3 hour overlap with US timezone.\n\nYour skills and experience\n\nPosition Characteristics\nEnglish skill \nExcellent fluency in English, both written and verbal.\nMust be self-motivated, team oriented and possess strong communication, interpersonal, and organizational skills.\nCandidate should be detail oriented, and self-motivated with a demonstrated ability to problem solve.\n\nCustomer Service \nHas a strong sense of urgency and commitment to quality customer service is required.\n\nEssential Criteria\nQualification \nBachelor’s degree, or equivalent experience.\n\nExperience \nExperience in Cybersecurity Operations. \nFunctional Networking knowledge preferred. \nIT Functional Windows/Linux Administration & Hardening experience preferred.\n\nProfessional knowledge and skills \nHand on experience with: SIEM, Anti-Malware/Endpoint Protection, Active Directory, IDS/IPS/Firewall, RegeX, Python, PowerShell, Email Security (DMARC, D-KIM, SPF) are highly desirable.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'A5 Building, E- Office Park, Road, Tân Thuận, Đ. Sáng Tạo, Tân Thuận Đông, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1103, 654, 2, 'Project Coordinator ( Project Manager/ E Commerce )', 'About Convert Digital (CD): Based in Australia (Melbourne, Sydney & Brisbane) and Vietnam (Hanoi), CD is a leading international ecommerce development company that designs, develops and integrates best practice Magento, Shopify, BigCommerce & Commercetools ecommerce solutions. We work with global leading retailers and online merchants as the most experienced Magento, Shopify & BigCommerce partners to deliver integrated ecommerce and digital solutions. We are a young, strong and growing team of eCommerce experts. Made up of a projects team, a client success team and a tech team, we offer all rounded solutions to deliver amazing results. We keep our team and clients happy by always supporting each other. Convert Digital is always looking for motivated eCommerce professionals to join our fast growing team in Hanoi. We offer the best working environment to make you feel that you are relaxing but actually working effectively. Below are our requirements for your consideration: As a Project Coordinator you will: Be a core member of a creative team that is responsible for all aspects of ongoing e-commerce website development; from the initial specification, through to developing, testing and launching. Receive, understand, interpret and respond to project plans/proposals. Manage end to end delivery on a variety of eCommerce projects development. Collaboratively work with product development and core engineering teams to ensure development of new features and functionalities to a high standard as per requirements. Engage with all members of the engineering team both on site and off site to completely understand the systems – end to end. Report to the direct manager on a weekly basis. You have the following Knowledge, Skills and Abilities (KSAs): Graduate from university (FTU or international universities is plus). Experience in project management or business analysis is plus. Experience in eCommerce is highly regarded. Strong communication skills. Experience working in an International company is a bonus. Fluency in English and Vietnamese. Excellent problem solving skills. Great team work spirit. Ability to motivate and work under pressure. Willing to be proactive in learning. Female applicants with 2-5 working experience years are preferred. Why you\'ll love working here: Very competitive salary; 15 annual leave and 5 sick leave per year; Young and dynamic team in a friendly and professional, international working environment; Gym, Yoga and other Sports packages. Pay full Social insurance, Health insurance; Bao Viet health insurance package; Many team activities: happy hour every Friday, team lunch, cinema, birthday party, team building every quarter, company trip (Korea, Bali, Taiwan, Singapore, Nha Trang, Da Nang, Phu Quoc, ...); Bonus on birthday, International Children Day, Mid-autumn festival; Quarterly bonus and 13th month salary; Annual health checkup at the top hospital in Vietnam; Work time: from Monday to Friday (40h/week).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '58A Ngo Thi Nham, Hai Ba Trung, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1104, 207, 2, 'Full-stack Developer (NodeJS, Python)', 'Top 3 reasons to join us\n• Lộ trình phát triển sự nghiệp đa chiều\n• Cơ hội đào tạo, công tác tại Nhật, Singapore, Mỹ..\n• Mức lương hấp dẫn, chế độ thưởng dựa trên năng lực\n\nJob description\n• Develop and Maintain web services: create, manage web services and interfaces; modify and improve existing systems for better performance and usability.\n• Testing and Debugging: perform tests, troubleshoot software, and fix bugs to ensure high-quality code.\n• Work with actual factory data to drive innovative solutions.\n• Collaborate with cross-functional teams to define, design, and implement new features.\n• Implementing systems at the factory, directly handling issues on-site the production line.\n• Documentation: write and maintain technical documentation for code and processes.\n\nYour skills and experience\n1. Must have\n• Proven Experience: demonstrated experience as a full stack developer or similar role.\n• Technical Proficiency: proficiency in front-end languages (HTML, CSS, JavaScript) and back-end languages (Node.js, Python)\n• Database Knowledge: familiarity with databases like MongoDB, MySQL, PostgreSQL, or SQL Server.\n• Knowledge of optimization algorithms, specifically Simulated Annealing.\n• Proficiency in a Linux development environment.\n2. Nice to have\n• Cloud Services: experience with cloud services like AWS.\n• DevOps: familiarity with DevOps practices and tools such as Docker, and Jenkins.\n• Version Control: experience with version control systems like Git.\n• Communication skills: excellent communication and teamwork skills.\n\nWhy you\'ll love working here\nPanasonic R&D Center Vietnam was established in April 2007, is a company specializing in R&D of Panasonic Group in Vietnam with the aim of enhancing R&D activities in the field of digital home appliances, automation, mobility in Vietnam, providing R&D services for software solutions in today\'s hottest fields such as AI, Cloud, IoT in a chain of R&D centers of worldwide corporations \n1. Career Path Development\n• Long-term multi-career roadmap;\n• Learning & development (Language Training, Technical Training, Soft-skill Training, On-job Training, etc.)\n• Oversea business trips (Japan, China, Singapore, US, Mexico, EU, etc.)\n2. Work-life Balance\n• Flexible working time that supports work-life balance (Core time: 9:00-16:00; 5 days from Monday - Friday/ week)\n• Additional special holiday\n3. Compensation package\n• Attractive salary \n• Competitive bonus package depend on abilities, performance and competencies\n• Diversified allowance scheme\n4. Wellness\n• Well-protected with 24/7 personal accident and medical care insurance;\n• Well-designed Annual Health Check-up program;\n5. Activities\n• Team-building activities; Birthday Party; Year-end party; Sport Day/ Family Day\n• Summer Vacation (Trip to famous tourist spots domestic/ overseas,…)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Lotte Tower, 54 Lieu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1105, 655, 2, 'Fullstack Developer (ReactJS, HTML, CSS, PHP, English)', 'We are looking for an experienced and proactive Full stack developer to join our team. The ideal candidate will work on various client projects, with main focus on childcare platform which connect parents and childcare providers. You will be an integral part of the team, enhancing and maintaining the childcare platform and other projects. This role is fully remote.\n\nKey Responsibilities:\n\n- Develop, enhance and maintain software applications to meet project specification and standards\n- Optimise performance and reliability of systems for daily operations\n- Implementation of new features and enhancements of user experience\n- Analyze, troubleshoot and resolve technical issues promptly\n- Maintain and improve code quality by writing clean, scalable and tested code\n- Keep up to date with industry best practices, trends and new technologies\n\nOur Technical Stack\n\nRequired:\n- HTML\n- CSS\n- ReactJS\n- PHP\n- Integration with Restful API\n\nNice to have:\n- Git\n- Docker\n- Docker compose\n- Symfony\n- Laravel\n- Twig\n- Python\n- Java\n\nSkills and experience:\n\n- 3+ years of professional software development experience\n- Strong proficiency in Frontend & Backend Technologies\n- Familiar with Agile/Kanban methodology\n- Conversational level of English, spoken and written\n- Ability to learn quickly\n\nWhy you\'ll love working here\n\n- 20 - 30 million dependent on experience\n- Full remote working\n- 15 days paid holiday (including UK public holidays)\n- Work on project for international clients\n- Lots of opportunities to learn new technologies', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Regus Gatwick C/O Sipher Accounting & Tax RH10 9LU Crawley United Kingdom', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1106, 402, 2, 'Senior Product Executive (P2P/CreditTech/InvestTech)', 'About the Role:\nAt MoMo, Product Executives are the builders behind products that serve millions of Vietnamese every day. We’re hiring talented and driven Product Executives to join three key teams: P2P Payment, CreditTech, and InvestTech. You’ll be part of the full product lifecycle – from ideation to launch – and work cross-functionally with Business, Design, Tech, and Data to create best-in-class fintech experiences.\nWhether you\'re passionate about transforming how people transfer money, access credit, or invest, there’s a place for you here.\n\nWhat You\'ll Do:\n- Drive product discovery and define user-centric solutions.\n- Collaborate with Business, UX, Tech, and Data to build and optimize features.\n- Monitor product performance and continuously improve user experience.\n- Stay ahead of market trends to build competitive and innovative features.\n- Own your roadmap and make data-informed decisions.\n\nExplore Each Opportunity at MoMo Career with keywords:\n- Senior Product Executive - P2P\n- Senior Product Executive - Credit Tech\n- Senior Product Executive - Invest Tech\n\nWho We’re Looking For:\n- 2–4 years of experience in Product, Business Analyst, or related roles (Tech/Startup/FMCG background is a plus).\n- Strong logical thinking, problem-solving, and communication skills.\n- Passionate about building digital products that impact millions of users.\n- Experience working with cross-functional teams.\n- Comfortable with data-driven decision-making and working in fast-paced environments.\n\nWhy you\'ll love working here:\nWe are passion with new technologies, not follow the old-track of outsourcing. We love our product and ready to sacrifice everything for it! You often argue with your boss? Don’t worry, here in M_Service, you will get salary increase if you win your boss in argument. We love objection!!! You hate company trip in hotel, resort? We only conquer difficult and hottest road in team building. Do you want to join?\n\nWhat you will get:\n- Competitive compensation package.\n- Performance-based bonus.\n- Insurance package.\n- Chance to work with smart people with international experience.\n\nOur benefits:\n- Attractive compensation & benefits.\n- 13th month salary bonus and yearly performance bonus.\n- 14 paid days off per year\n- Premium health care insurance\n- Great allowances (lunch, parking, birthday, happy hours....)\n- Salary review at least one time per year based on employee\'s performance and contribution.\n- Outing/team-building activities (company trip , soccer sport, english club, running club,..).\n- Other benefits as per stated in Vietnamese Labor Law\n- Work with experienced & strong team.\n- Friendly, dynamic & flexible working environments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor, Phu My Hung Tower, 08 Hoang Van Thai Str, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1107, 656, 2, 'Sr. Java Backend Developer (Spring, SQL, English)', 'You will join other Developers, Manager Engineers, Test Automation Engineers, and Business Analysts. You’ll help to build key modules of our product where you’ll use and grow your experience to architect and build cloud applications, APIs and back end Java services to maintain high availability and reliability.\n\nYou’d work across the Service Team collaborating within your own squad, individual developers, and manager engineers to deliver first class banking software that provides real value to our customers and an outstanding user experience. You will be a strong team player with good written and verbal communication skills, and a desire to participate in all aspects of the SDLC.\n\nResponsibilities:\n\nBe part of a team that will take full responsibility for the features you own.\nDesign, build, and maintain efficient, reusable, and reliable web and native mini apps using Java.\nFollow our Software Development Life Cycle (based on SAFE methodology).\nGaining a deep understanding of our technology stack, driving our strategic plans with the ability to raise questions where necessary.\nSupporting the deployment and progression of services from test environments through to production. \n\nYour skills and experience\n\nApplicants must have a strong background in:\n\nEnglish communication\nJava + SpringBoot\nKafka\nREST API\nStrong SQL knowledge\nAWS (S3, RDS, CloudWatch)\nExperience working in distributed systems\nDocker\nKubernetes (K8S)\nExperience working with linux system\nSecurity aspects - Experience working with Public/Private Key, X509, mTLS\n\nWhy you\'ll love working here\n\nHybrid working\nGlobal Training \nPerformance bonus\nFull social insurance, unemployment insurance, health insurance\nPersonal incident and health insurance\nWonderful and Human focus Environment\nDynamic and young work force\nGreat working environment (relax corners, PS4, ping-pong table etc.)\nAllowances (lunch, parking, mobi, transportation)\nTravel opportunities (Inter sites mobility)\nTeam activities (CSR, Coffee hours, Friday Talking, YEP, …)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '9th Floor, Viettel Tower, 285 Cach Mang Thang 8, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1108, 657, 2, 'Senior AI Developer (Python)', 'Top 3 reasons to join us\n- Performance Bonus\n- Annual health check\n- Happy Hour every Friday\nJob description\n- Involving in data science/AI projects from beginning to delivery.\n- Analyzing, proposing, developing, and evaluating solutions to solve our clients’ business problems.\n- Collaborating with our PMs or other stakeholders to define project plan/ roadmap.\n- Collecting, cleaning, and preparing datasets for modeling.\n- Deploying and monitoring the AI systems.\n- Continuously learning to keep up with the rapid changes in the field of AI.\nYour skills and experience\n- At least 3+ years of experience with programming in Python (AI).\n- Experienced in working with LLM models, especially GenAI models.\n- Experienced in working with cloud computing services (MS Azure, AWS…)\n- Experienced with AI/ML algorithm research & development, preferably NLP field.\n- Possessing excellent communication skills in English, (communicating sufficiently in Japanese is a plus).\n- Having a sufficient background in Mathematics, or Statistics.\n- Strong critical thinking and problem-solving abilities, being able to formulate AI solutions from business requirements.\n- Being a good team player, willing to provide support to other members if needed.\n- Being flexible to participate in different parts of a project if required\nPreferable qualifications:\n- Having a passion for the educational field.\n- Experienced in developing or researching algorithms in the educational field.\n- Experienced in modeling learning behavior data.\n- Having an MS or PhD in Computer Science, Statistics, Mathematics, or relevant fields.\n- Being familiar with designing REST APIs.\n- Having a great desire to study the most leading-edge research\nWhy you\'ll love working here\n- Annual health check.\n- 13th month salary bonus and performance bonus.\n- PVI private insurance registration\n- Support for gasoline (800,000 VND/month).\n- Happy hour party every Friday (1 hour), year-end party, and other events.\n- Gifts on various occasions (wedding, lunar new year, mid-autumn...)\n- Support for costs of participating in online classes (work-related).\n- Take a day off on your birthday.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 9, Tòa nhà TNR, 180-192 Nguyễn Công Trứ, Phường Nguyễn Thái Bình, District 1, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1109, 658, 2, 'Java Developer (Spring Boot, SQL, AWS)', 'Top 3 reasons to join us\n\n- Review tăng lương định kỳ\n- Chính sách về sức khỏe và chế độ bảo hiểm\n- Làm việc theo team có tinh thần trách nhiệm cao\n\nJob description\n- Phân tích, tìm hiểu để nắm rõ các yêu cầu nghiệp vụ từ Chuyên viên phân tích nghiệp;\n- Phân tích thiết kế các dịch vụ, cấu trúc cơ sở dữ liệu, thuật toán cần thiết dựa trên yêu cầu nghiệp vụ cho chức năng được giao, đảm bảo tuân thủ quy định của framework phát triển ứng dụng;\n- Phát triển các chức năng của phần mềm ứng dụng theo yêu cầu nghiệp vụ được giao, thực hiện kiểm thử unit test trước khi bàn giao cho đội kiểm thử;\n- Tài liệu hóa và chuyển giao các chức năng đã phát triển xong cho đội kiểm thử và tiến hành sửa lỗi nếu có;\n- Tham gia vào team R&D của công ty để tìm hiểu các công nghệ, kỹ thuật mới.\n\nYour skills and experience\nBắt buộc:\n- Tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc có kinh nghiệm thực tiễn tương đương;\n- Có kinh nghiệm 2 năm trở lên làm về backend;\n- Hiểu biết chuyên sâu ngôn ngữ lập trình Java; sử dụng thành thạo Spring Framework, Spring Boot;\n- Có kiến thức về Microservice, RESTful API;\n- Biết cách giải quyết các vấn đề cơ bản liên quan đến an toàn vào bảo mật;\n- Có khả năng thảo luận với đội FrontEnd, BA để đưa ra giải pháp tốt nhất cho sản phẩm;\n- Có khả năng xác định và tối ưu các vấn đề của: Server, Database…;\n- Có kinh nghiệm tối ưu SQL query giúp cái thiện tốc độ hệ thống;\n\nƯu tiên:\n- Ứng viên đã có kinh nghiệm trong lĩnh vực tài chính, ngân hàng;\n- Hiểu biết về Amazon Web Service (AWS), Microsoft Azure, GCP, Docker là một lợi thế.\n\nWhy you\'ll love working here\nChế độ tiền lương và khen thưởng cho nhân viên của MBV gắn liền với kết quả hoạt động kinh doanh và chất lượng dịch vụ của mỗi nhân viên khi thực hiện công việc được giao. Một năm, nhân viên được hưởng tối thiểu 13 tháng lương, được nhận các phụ cấp theo chế độ như phụ cấp trách nhiệm, độc hại, phụ cấp rủi ro tiền mặt, phụ cấp chuyên môn; ngoài ra nhân viên còn được hưởng thêm lương theo năng suất và mức độ hoàn thành công việc; thưởng cho các đơn vị, cá nhân tiêu biểu trong năm, thưởng sáng kiến; thưởng trong các dịp lễ tết của Quốc gia và kỷ niệm thành lập MBV… Nhân viên chính thức của MBV được hưởng đầy đủ các quyền lợi phù hợp với quy định của Ngân hàng và Pháp luật hiện hành.\n- Lương thỏa thuận theo năng lực\n- Môi trường làm việc năng động, chuyên nghiệp, có lộ trình thăng tiến rõ ràng, minh bạch, review tăng lương định kỳ\n- Chính sách về sức khỏe và chế độ bảo hiểm theo Luật Lao động Việt Nam\n- Cung cấp trang thiết bị đầy đủ để phục vụ công việc.\n- Làm việc theo team có tinh thần trách nhiệm cao\n- Cơ hội đào tạo và phát triển nghề nghiệp', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '3 Liễu Giai, Liễu Giai, Ba Dinh, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1110, 640, 2, 'Senior Backend Developer (PHP/ Laravel)', 'Job description\n- Tham gia xây dựng hệ thống CRM của công ty\n- Đưa ra những giải pháp từ yêu cầu để đạt được hiệu suất cao\n- Luôn cập nhật những công nghệ mới để đạt được hiệu quả cao trong công việc.\n- Thực hiện các yêu cầu công việc từ cấp trên\n\nYour skills and experience\n- Có kinh nghiệm 2 năm lập trình web\n- Có kinh nghiệm làm việc với Laravel và các framework khác của PHP\n- Am hiểu về HTML 5, CSS, JavaScript, AJAX\n- Có kiến thức về database (MySQL, NoSQL)\n- Có kiến thức về web service và RESTful API\n- Có kinh nghiệm làm việc với hệ thống - 10.000 user truy cập cùng lúc là 1 điểm cộng\n- Sử dụng thành thạo Git\n\nWhy you\'ll love working here\n- Mức lương cạnh tranh: Upto 30tr\n- Thời gian làm việc: Từ thứ 2 đến thứ 6, từ 8h30 - 17h30 ( Thứ 4 làm việc tại nhà )\n- Được hưởng đầy đủ chế độ phúc lợi: BHYT, BHXH, Du lịch, team building,...\n- Làm việc trong môi trường trẻ trung năng động.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '143 Phạm Huy Thông, phường 6, Go Vap, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1111, 328, 2, 'Business Analyst (Games, AI)', 'We are seeking a detail-oriented and strategic Business Analyst to support the planning and delivery of our Mini Game and AI-related products. You will work as a bridge between business stakeholders, designers, and technical teams, helping to translate product ideas into clear, actionable specifications. Your insights will help shape product features that are fun, innovative, and technically feasible.\n\nResponsibilities\n- Work closely with stakeholders to gather and clarify business requirements for mini games and AI-powered features.\n- Conduct market and user research to identify trends, opportunities, and competitive benchmarks.\n- Create detailed BRDs (Business Requirement Documents), user stories, and functional specifications.\n- Collaborate with product managers, designers, and developers to define MVP scope and feature prioritization.\n- Analyze game mechanics and AI behavior flow to ensure alignment with business goals.\n- Participate in sprint planning, daily standups, and UAT sessions.\n- Identify and mitigate project risks early through clear communication and documentation.\n- Provide data-driven insights post-launch using user feedback and analytics.\n\nYour skills and experience\n- Minimum 3 years of experience as a Business Analyst in a tech or digital product environment.\n- Strong understanding of game mechanics, user interaction, and AI logic.\n- Experience working with cross-functional teams in Agile/Scrum environments.\n- Ability to write clear, concise user stories and acceptance criteria.\n- Good analytical, problem-solving, and communication skills.\n- Familiarity with tools like Jira, Confluence, Figma, Miro, or similar.\n- Ability to bridge creative and technical perspectives.\n- Strong attention to detail and organization.\n\nNice To Have\n- Experience in the game industry or working on gamification projects.\n- Basic understanding of AI models, machine learning pipelines, or LLMs (e.g., ChatGPT, Midjourney, etc.).\n- Familiarity with game engines or front-end development basics.\n- Knowledge of user psychology or game engagement metrics.\n\nWhy you\'ll love working here\n- Salary range: 20,000,000 VND – 45,000,000 VND/month (based on experience).\n- Monthly meal allowance.\n- Official employees enjoy paid leave, holiday bonuses, and Tet bonuses as per company policy.\n- Generous bonus system: 13th-month salary, performance bonuses.\n- Internal events: Happy Hour, Internal Party, Company trip.\n- Young, dynamic, and fun working environment.\n- Work Schedule: Monday-Friday (5 days/week).\n- Address: 99 Nguyen Thi Nhung, Thu Duc City.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '99 Nguyễn Thị Nhung, Hiệp Bình Phước, Thủ Đức, Thu Duc City, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1112, 659, 2, 'Jr/Sr Software Frontend (Angular/TypeScript/HTML5/CSS3)', 'Job description\n- Tham gia xây dựng hệ thống phần mềm do công ty phát triển.\n- Thiết kế giao diện cho tính năng mới, hiện thực giao diện tính năng theo bản thiết kế của Designer.\n- Phối hợp cùng đội ngũ BA phân tích, thiết kế, đưa ra giải pháp phát triển sản phẩm đúng, đủ, tiện lợi với yêu cầu người dùng cuối.\n- Phối hợp với đội lập trình backend tích hợp các API cho sản phẩm.\n- Tham gia nghiên cứu góp ý và chia sẻ giúp cải thiện chất lượng sản phẩm.\n- Xây dựng và tích hợp các micro-frontend trong kiến trúc microservices.\n\nYour skills and experience\n- Tốt Nghiệp Cao đẳng/Đại học, chuyên ngành công nghệ phần mềm.\n- Ít nhất 1 năm kinh nghiệm lập trình angular 8+ và trình biên dịch CSS:SASS.\n- Có kinh nghiệm trong thiết kế giao diện web, phát triển sản phẩm trên nền web.\n- Có kinh nghiệm thiết kế giao diện web responsive.\n- Có kinh nghiệm làm việc với các API.\n- Có kinh nghiệm làm việc với BA, Designer là một lợi thế.\n- Có tinh thần trách nhiệm trong công việc, tinh thần tập thể cao.\n- Có kinh nghiệm thiết kế và triển khai micro-frontend hoặc kiến trúc SPA modular.\n- Có kinh nghiệm viết unit test với Jest/Testing Library(React/Vue), Jasmine/Karma(Angular).\n- Hiểu rõ các khái niệm performance web (critical rendering path, code splitting, lazy loading).\n- Khả năng nắm bắt, nghiên cứu công nghệ mới, khả năng tự học, tự nghiên cứu.\n- Chủ động, đam mê công việc, sẵn sàng chấp nhận thách thức, luôn chú ý phát triển bản thân lên tầm cao mới.\n- Kỹ năng giao tiếp tốt, cởi mở, thân thiện.\n- Kỹ năng làm việc nhóm hiệu quả.\n- Có tư duy logic và khả năng nghiên cứu tự giải quyết vấn đề.\n- Chịu được áp lực cao trong công việc.\n- Sử dụng thành thạo các công cụ Gitlab, Jira, ...\n\nWhy you\'ll love working here\n- Được ghi nhận, thưởng theo năng lực và hiệu quả công việc hàng quý/năm và theo quy định của Công ty.\n- Được cung cấp trang thiết bị làm việc (Macbook, Laptop, LCD 24…).\n- Được xem xét tăng lương ít nhất 1 năm/lần tùy vào năng lực và mức độ tiềm năng của Bạn.\n- Hỗ trợ chi phí đi công tác.\n- Môi trường, điều kiện làm việc chuyên nghiệp, tiện nghi, hiện đại, rộng rãi, thân thiện với môi trường, chuẩn văn phòng hạng B+.\n- Chế độ nghỉ phép và bảo hiểm (BHXH-BHYT-BHTN) theo quy định pháp luật.\n- Được mua bảo hiểm sức khoẻ cao cấp (Bảo hiểm Tai nạn tối đa 100 triệu đồng/người/năm, trợ cấp trong thời gian nghỉ điều trị tai nạn tối đa 180 ngày/năm/người; Điều trị nội trú do ốm đau, bệnh tật, thai sản tối đa 70 triệu đồng/năm/người; Điều trị ngoại trú, bệnh tật, nha khoa…) cho nhân sự và người thân.\n- Phụ cấp ăn sáng, ăn trưa và tiền gửi xe.\n- Thưởng Lễ, Tết, Sinh nhật, Kết hôn.\n- Teambuilding/quý, Du lịch/năm.\n- Được đánh giá năng lực làm việc theo quý/năm và nâng cấp bậc trong công việc; làm việc, cộng tác cùng đội ngũ nhân sự chất lượng cao, chuyên gia theo mô hình quản trị dựa trên OKRS, SAFe; nhiều cơ hội phát triển năng lực, thăng tiến sự nghiệp dựa trên năng lực và giá trị của bản thân.\n- Được xem xét tài trợ kinh phí các chương trình đào tạo, tham gia hội thảo trong nước và quốc tế giúp nâng cao năng lực, phục vụ công việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường 5, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1113, 315, 2, 'System Engineer (Networking, Security)', 'Job description\n1. System Design:\nBuild server systems, storage, and content delivery networks (CDN).\nParticipate in surveys and identify issues related to the system.\nProvide consultation and design solutions/services for IT infrastructure (building or upgrading network systems).\nPerform other related technical tasks as assigned.\n\n2. System Operation:\nMonitor and troubleshoot system incidents 24/7/365 at the Server Centers.\nPerform scheduled system upgrades as required.\nReport on daily system operations.\nResearch and propose ideas to minimize risks and potential errors.\n\nYour skills and experience\n- College degree or higher in Information Technology, Software Engineering, or a related field.\n- At least 1 year of experience in the position being recruited.\n- At least 1 year of experience in an equivalent role.\n- Preference given to candidates with experience in entertainment applications, OTT platforms, etc.\n- Solid understanding of networking and security.\n- Proficient in programming languages such as Shell script, Go, or Python. Knowledge of Lua, PHP, or JavaScript is a plus.\n- Basic understanding of Agile methodologies and software development practices.\n- Knowledge of networking concepts or possession of equivalent certifications.\n- Experience in system performance testing, evaluation, and proposing improvement solutions.\n- Experience with cloud services such as AWS, Google Cloud, or Microsoft Azure.\n\nWhy you\'ll love working here\n💰 Competitive Compensation\n13th-month salary, sign-on bonus, performance-based reviews, and attractive bonuses.\n\n🚀 Growth Opportunities\nAccess to training and advanced technologies.\n\n📱 Exciting Projects\nWork on leading entertainment apps and OTT platforms.\n\n🌟 Open Culture\nWe value ideas, creativity, and innovation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '222 Pasteur, Phường Võ Thị Sáu, District 3, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1114, 660, 2, 'Junior Fullstack Developer (Laravel, ReactJS, VueJS)', 'Reputyze Asia là một công ty quảng cáo công nghệ số có trụ sở tại thành phố Hồ Chí Minh chuyên cung cấp các dịch vụ chuyên nghiệp về Quản Lý Uy Tín Thương Hiệu Trực Tuyến và Số Hóa Truyền Thông & Tiếp Thị. Được thành lập với sứ mệnh Kiến Tạo Uy Tín Thương Hiệu, công ty luôn nỗ lực để thiết lập và bảo vệ vị thế thương hiệu của khách hàng trên môi trường internet.\n\nTrong giai đoạn mở rộng kinh doanh hiện tại, công ty cần tìm các tài năng, khát khao nghiên cứu và thử nghiệm các công nghệ mới vào tiếp thị số, tham gia vào đội ngũ trẻ và năng động của chúng tôi và cùng nhau phát triển công ty đến những chân trời mới.\n\nMô tả công việc:\n- Sử dụng PHP duy trì và phát triển ứng dụng/trang web cho khách hàng. Thảo luận những mục tiêu của dự án với nhóm nhà phát triển.\n- Phân tích yêu cầu của khách hàng, khung phát triển chính, thực hiện thiết kế và mã hóa.\n- Khắc phục sự cố và khắc phục bất kỳ vấn đề nào liên quan đến chương trình PHP.\n- Viết các tài liệu kỹ thuật cũng như các thông số phi kỹ thuật cùng với ghi chép tất cả các thủ tục.\n- Nghiên cứu và cung cấp các giải pháp kỹ thuật theo yêu cầu.\n- Làm việc chặt chẽ với pms và người kiểm thử hoàn thành dự án.\n- Tạo ra kết quả hiệu quả và trong thời hạn thiết lập.\n\nYour skills and experience:\n- Có ít nhất 1 đến 2 năm kinh nghiệm lập trình PHP/MySQL.\n- Có kinh nghiệm làm việc với HTML, HTML5, Bootstrap CSS framework, JavaScript.\n- Có kinh nghiệm 1 trong các js framework: JQuery, VueJs, NextJS, có khả năng viết Javascript.\n- Có kinh nghiệm làm front-end cho dự án: Laravel, ECommerce, Wordpress.\n- Hiểu rõ về PHP hướng đối tượng, mô hình MVC.\n- Hiểu rõ về các bước đầy đủ của phát triển web responsive sử dụng HTML, CSS, JavaScript, và PHP/MySQL.\n- Sử dụng được các framework: CodeIgniter, Laravel, NodeJS,...\n- Có khả năng làm việc nhóm tốt.\n- Có thể sử dụng Git/Subversion (SVN).\n- Có khả năng chịu áp lực công việc.\n- Có tư duy phân tích và nắm bắt vấn đề nhanh vấn đề liên quan đến dự án.\n- Có trách nhiệm cao trong công việc, sẵn sàng thu xếp thời gian để hoàn thành công việc theo yêu cầu dự án.\n\nƯu tiên:\n- Có kinh nghiệm trong sử dụng APIs mạng XH như Facebook, Twitter.\n- Biết web services.\n- Sử dụng tiếng anh tốt.\n- Có kinh nghiệm sử dụng các CMS TMĐT khác như: Magento/ Woo Commerce/Opencart.\n- Có kinh nghiệm về SSO, Mobile Apps, ... là một lợi thế.\n- Sử dụng tốt Wordpress là lợi thế (theme, plugins).\n\nWhy you\'ll love working here:\n- Có cơ hội được đào tạo toàn diện về Công nghệ số và Quản trị truyền thông kỹ thuật số.\n- Có cơ hội tiếp cận với phương pháp và quy trình quản trị dự án truyền thông kỹ thuật số một cách có tổ chức và hiện đại.\n- Môi trường làm việc thân thiện, năng động và có cơ hội tiếp cận những công nghệ tiên tiến.\n- Chương trình Phát triển vượt trội cho những ứng viên tài năng.\n- Các chính sách khác: Nghỉ mát, Thưởng, Bảo hiểm, Phụ cấp,...theo Luật Lao Động.\n- Kinh nghiệm: 1 năm trở lên.\n- Loại công việc: Chính thức - toàn thời gian.\n- Ngành: Truyền thông, số hóa truyền thông, tiếp thị truyền thông mạng xã hội, tiếp thị bằng nội dung.\n- Lương: Cạnh tranh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3, tòa nhà AGA House, 72/24 Phan Đăng Lưu, Phường 5, Phu Nhuan, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1115, 288, 2, 'Data Analyst (SQL, Python)', 'Have a good grasp of analytics and want to utilize it for B2B software solutions in e-commerce logistics?  Parcel Perform is looking for an amazing team member to support us in data analytics! You have excellent statistics and analytics skills, 3-4 years of experience working with big and complex databases, you’re technically savvy and have a good grasp on query techniques? Are you also interested in e-commerce and like to take on new challenges? Help us drive Parcel Perform’s growth and join our team! We are looking for you!  WE NEED YOU ON OUR TEAM! As a Data Analyst, you will be responsible for compiling actionable insights from data and assisting sales, marketing, and technology teams to build data-driven processes. We at Parcel Perform will always put the customer first. We want them to get the most out of our data and showcase the endless possibilities of our service. You will be an important inflection point among their logistics data, challenges, and how our insights can support them. Your role will also involve driving initiatives to optimize the operational excellence of the data team.  Such complexity can be hard, especially with a focus on good operation practices. But that is ok. We aren’t here for ease anyway. We are here for people who want to up their game.\n\nWHAT YOU SHOULD BRING ALONG! We at Parcel Perform believe in innovation, energy, and resourcefulness for everything we do. We will not stop to deliver an outstanding product that we can be proud of and need you to help us to inform the world. You need to feel the same way about our offering and bring along the following things:  - Fluent in SQL to work with large data sets and relational databases to extract insights and optimize query planners; experience with Python a plus.\n- Knowledge of statistics and experience using statistical packages for analyzing datasets (e.g., Excel, SPSS, SAS)\n- Hand-on experience working with real data for customer insights, business, and market analysis. Work experience with logistics data is a plus.\n- Good communication skills, and the ability to translate business requirements into non-technical, lay terms.\n- Strong analytical skills with the ability to collect, organize, analyze, and disseminate significant amounts of information with attention to detail and accuracy.\n- Able to work independently as well as with cross-functional teams.\n- Open-minded, friendly, and strong willingness to keep learning and pushing yourself to higher and higher levels.  WHAT YOU WILL RECEIVE IN RETURN! We at Parcel Perform are dedicated to being a platform for growth for all our team members, regardless of function and location.   - The opportunity to work in a fast-growing, super exciting and innovative business that will revolutionize the e-commerce logistics industry. You will be the needle of success on the growth of a global product that will become a key platform behind successful e-commerce logistics worldwide.\n- The ability to continuously learn and develop in an international setting with you being a critical driver behind the success of us achieving our mission.\n- An environment where everybody never stops growing and focuses on succeeding - we continuously work with you on your strengths and weaknesses across many important dimensions and look at ways for you to address them and further your development\n- Your entry ticket into being part of the Parcel Perform journey, where you will work with and alongside people from around the world that share the same passion and dedication. \n\nWHO ARE WE AT PARCEL PERFORM! Parcel Perform (www.parcelperform.com) is a leading e-commerce delivery experience platform, empowering businesses to optimize the entire customer journey from checkout to delivery and returns. By unifying logistics data and providing actionable insights and intelligent automation, including leveraging AI capabilities, Parcel Perform helps businesses enhance customer satisfaction, streamline operations, and drive growth. With a global reach and an extensive carrier network, Parcel Perform is the trusted partner for ambitious e-commerce businesses, marketplaces, and 3PLs worldwide. We’re committed to continuously innovating, using data to optimize every step of the e-commerce delivery.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'The Grace Tower, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1116, 209, 2, 'Business Analyst - Up to $3000', 'WORK LOCATION: Ha Noi, Ho Chi Minh, Da Nang, Hue\n\nJOB OVERVIEW\nWe are looking for Business Analytic to participate in the project of consulting and developing SCM system for Japan’s TOP customers in electronic equipment manufacturing; financial system for customers related to Japanese media/communication and Japanese building management and operation system.\n\nRESPONSIBILITIES\n• Support to organize workshops, perform CRP with End-users to consult and complete the requirement / UI / UX documents.\n• Make basic design documents: Basic design, Architecture design document.\n• Plan to evaluate the system after implementation, UAT and train users to use the system developed by FPT.\n\nYour skills and experience\nBasic Qualifications:\n• Be fluent in Japanese ( N2 up )\n• Have at least 2 years of IT experience with projects working with End-users customers\n• Have good problem analysis and presentation skills\n• At least 3 years of experience in building and developing high level design documents such as RD ~ BD\n• Have the ability to consult and experience with SCM or production-related fields for at least 2 years.\n• Have management skills and understanding of Agile, Waterfall software development management methods\n• Ability to propose and persuade\n• Have 3 years of experience in testing or ensuring product quality after implement\n• Having a technical base of 5 years or more is an advantage.\n• Having the ability to consult and experience with SCM or production-related fields for at least 5 years.\n• 3+ years of experience in accounting, finance or television\n• 3+ years of experience in building operations and management.\n• 3+ years of experience in production domain and logistics\n\nNice to have:\n• Experience with ERP projects, Dynamic 365\n• Proficient in UML, Design and Modeling tools.\n\nWhy you\'ll love working here\n• Be part of our hugely international environment; we are currently working for Japanese/Global projects, where you can have many opportunities to working overseas;\n• Competitive salary package based on skills and experience.;\n• We create great teams and take very good care of them;\n• Great opportunity to grow with the company;\n• Frequent staff activities and company parties;\n• Awesome social events and parties for employees;\n• 20% discount on school fee if your sons/ daughters join FPT School;\n• Udemy/ ELSA PRO accounts for every employee & Udacity accounts for Managers.\n\nSpecial offer for senior level:\n• Relocating package: Up to 100M (for senior candidates from Hanoi/HCM.C to Danang City);\n• Loan support: 4% interest rate (1 – 2 Billion VND package).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'FPT Building, 17 Duy Tân Str., Cau Giay, Ha Noi; F-Town 3, 3 Võ Chí Công, Phường Long Thạnh Mỹ, Thu Duc City, Ho Chi Minh; Tòa nhà FPT Complex, Đường Nam Kỳ Khởi Nghĩa, Phường Hòa Hải, Ngu Hanh Son, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1117, 661, 2, 'Fullstack Developer(Python, Django, MySQL)- Up to 1800$', 'Top 3 reasons to join us\n• 14 tháng lương một năm\n• Cơ hội nhận Stock Option, full bảo hiểm xã hội\n• Môi trường cực thoải mái, không khuyến khích OT\n\nJob description\n• Thiết kế kiến trúc và xây dựng hệ thống client-side và server-side\n• Xây dựng giao diện người dùng của các ứng dụng web based \n• Thiết kế và xây dựng cơ sở dữ liệu dùng trong các hệ thống ứng dụng\n• Viết các Restful API\n• Kiểm tra phần mềm để đảm bảo yêu cầu và hoạt động hiệu quả\n• Khắc phục sự cố, gỡ lỗi và nâng cấp phần mềm\n• Xây dựng các tính năng và ứng dụng với thiết kế mobile responsive\n\nYour skills and experience\n• Có kinh nghiệm với vai trò Full stack developer hoặc tương tự\n• Có kinh nghiệm với lập trình Python phía backend\n• Có ít nhất 3 năm kinh nghiệm với các front-end frameworks (Django, jQuery, HTML, CSS, JS), có kinh nghiệm làm responsive web design.\n• Quen thuộc với các hệ quản trị cơ sở dữ liệu (ví dụ: MySQL, MongoDB)\n• Có kinh nghiệm làm việc với Web server, hệ điều hành Ubuntu\n• Kiến thức sâu rộng về OOP và design patterns\n• Có kinh nghiệm DevOps với AWS hoặc Azure, Docker\n• Tiếng Anh trung cấp\n• Kỹ năng giao tiếp và làm việc nhóm\n• Kỹ năng tổ chức\n• Growth mindset\n\nWhy you\'ll love working here\nMôi trường làm việc trẻ trung, thân thiện và thoải mái\n• Tham gia xây dựng và phát triển các sản phẩm hàng đầu của công ty\n• Khởi đầu mới ngay tại văn phòng mới với view làm việc cực chill! Khu pantry và giải trí luôn sẵn sàng chào đón để bạn thư thả tâm hồn〜\n• Làm việc cùng các member đến từ các quốc gia khắp nơi trên thế giới như Nhật Bản, Pháp, Đài Loan, Sri Lanka, Ấn Độ, Brazil,...\n• Những chuyên gia nhiều kinh nghiệm trong lĩnh vực AI sẽ giúp bạn định hướng và phát triển chuyên sâu về công nghệ AI hơn\n\nQuan tâm đặc biệt tới nhân viên với các khoản hỗ trợ hấp dẫn:\n• Mức lương khởi điểm ấn tượng upto $1,800\n• Lương tháng 14 và review tăng lương 1 năm 2 lần không giới hạn %\n• Cơ hội nhận thưởng cổ phần\n• Cơ hội đứng tên bằng sáng chế\n• Được tham gia đầy đủ các chế độ của Nhà nước quy định như: BHXH, BHYT, BHTN, ngày nghỉ phép năm.\n• Chế độ chăm sóc phụ nữ\n• Hỗ trợ chi phí khác như phụ chuyên cần, xăng xe, điện thoại,...\n• Du lịch nghỉ mát hàng năm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 3, số 6 ngõ 82 Duy Tân, phường Dịch Vọng Hậu, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1118, 499, 2, 'PHP Software Engineer (Middle/Senior)', 'CƠ HỘI LÀM VIỆC VỚI PRODUCT HỆ THỐNG LỚN - CAREER PATH RÕ RÀNG - WORK-LIFE BALANCE!!!  MÔI TRƯỜNG PHÁT TRIỂN MỚI NHẤT: SỬ DỤNG AI (GITHUB COPILOT/CHAT GPT/GEMINI)  ** Rakus Việt Nam là công ty 100% vốn đầu tư từ RAKUS Co., Ltd. - công ty nổi tiếng hàng đầu tại Nhật Bản cung cấp các dịch vụ đám mây (SaaS), giúp các doanh nghiệp điều hành hoạt động của mình một cách nhanh chóng, tiện dụng nhất.  **Chúng tôi đang tuyển dụng 3 vị trí Middle/Senior PHP Software Engineer: LÀM VIỆC OFFLINE FULLTIME TẠI VĂN PHÒNG HEADOFFICE QUẬN 12  - Domain: Hệ thống phần mềm phát hành và quản lý email Marketing - đang được sử dụng bởi hơn 1,7tr end-users tại thị trường Nhật Bản.  Nếu:  ・Bạn muốn tham gia phát triển một dự án lớn có độ khó cao về nghiệp vụ.  ・Bạn có định hướng thăng tiến lên Principal Software Engineer/Technical Leader.  ・Bạn mong muốn môi trường làm việc lâu dài (ít nhất 3 năm trở lên)  ・Bạn có năng lực tập trung và thích tìm hiểu sâu về 1 hệ thống.  Hãy đến với Rakus Việt Nam, dùng kỹ năng của bạn cùng Team PHP xây dựng các ứng dụng web dựa trên công nghệ Cloud.  - Cùng Quản lý dự án (PM) và các thành viên phát triển dự án phân tích đặc điểm kỹ thuật của sản phẩm, các thay đổi đặc điểm kỹ thuật và các chức năng mới bổ sung .  - Tham gia vào phát triển các dự án với vai trò Software Engineer từ giai đoạn Outline Design, Detail Design, Development/Implementation, Code review, Unit test, Release. Được đào tạo để trở thành Principal Software Engineer trong tương lai.  - Thiết kế Database, phát triển các chức năng đồng thời support các thành viên trong team.  - Làm các công việc khác theo sự phân công của PM.  Yêu cầu cơ bản:  - Có từ 3 năm kinh nghiệm trở lên làm việc với PHP trong các dự án phát triển web application (Development, Refactoring, Unit Test). Ưu tiên ứng viên yêu thích, có niềm đam mê với lập trình PHP thuần.  - Có kinh nghiệm với 1 (hoặc nhiều) trong các framework của PHP như: Laravel, CodeIgniter, Yii 2, CakePHP, Zend  - Thành thạo Javascript, HTML, CSS, SCSS, Jquery, Json, Ajax  - Thành thạo PostgreSQL hoặc MySQL  - Thành thạo Git (UI/Command)  - Đã từng sử dụng IDE: PHPStorm  Ưu tiên:  - Kinh nghiệm làm việc với Framework Javascript như: Vuejs, Reactjs, Angularjs  - Kinh nghiệm về xử lí dữ liệu lớn trên Database (Insert/Update/Delete)  - Có kiến thức hoặc kinh nghiệm viết Phpunit test.  - Có kinh nghiệm refactoring code, review code  - Có kiến thức và kinh nghiệm về quan điểm viết mã sạch (Clean code)  - Đọc hiểu tài liệu bằng tiếng Anh tốt  - Có khả năng đọc, hiểu và phân tích yêu cầu nghiệp vụ từ phía khách hàng  - Có khả năng phát hiện và giải quyết vấn đề tốt  - Có khả năng tạo/trình bày tài liệu kĩ thuật dễ hiểu và chia sẻ kiến thức với đồng nghiệp  - Có khả năng giao tiếp tốt  - Hiểu quy trình và phong cách làm việc tại công ty Nhật là một lợi thế.  Lưu ý: Không tuyển ứng viên nước ngoài.  TẠI SAO BẠN NÊN CHỌN RAKUS VIỆT NAM ?  1). Lương và Thưởng  - Lương tháng 13+14; đóng BHXH 100% lương gross.  - 100 % lương trong thời gian thử việc  - Tăng lương và trả Bonus 2 lần/năm  2). Thời giờ làm việc, nghỉ ngơi  - Thứ 2~ thứ 6, từ 8:30~ 17:30  - 12 ngày phép năm + 11 ngày nghỉ lễ lịch VN + 7 ngày nghỉ lễ lịch Nhật = 30 ngày  - Hầu như Không làm thêm giờ (No Overtime) 3). Đào tạo  - Cơ hội được cử đi Nhật đào tạo  - Các kỹ sư người Nhật hỗ trợ OJT (on the job training)  - Training kỹ năng mềm theo level  - Seminar kỹ thuật hàng tháng 4). Giải thưởng  - Yearly MVP – 2 đến 3 bạn Nhân viên xuất sắc mỗi năm được trải nghiệm và làm việc tại Nhật 1 tuần.  - Quarterly MVP – Giải thưởng Nhân viên xuất sắc của Quý  - Giải thưởng nhân viên 5 năm, … 5). Phúc lợi chăm sóc sức khỏe thể chất, tinh thần  - Bảo Hiểm xã hội đóng trên Full lương Hợp đồng  - Du lịch Công ty hàng năm (3 ngày 2 đêm), tài trợ 50% chi phí tour cho gia đình nhân viên  - Nhiều event suốt năm: ngày phụ nữ, ngày nam nhân, ngày Thiếu nhi,Trung thu, Giáng sinh, Tiệc cuối năm, teambuilding hàng quý, Các hoạt động với gia đình nhân viên, Tiệc sinh nhật hàng tháng ...  - Tham gia chương trình bảo hiểm sức khỏe cá nhân PVI  - Tham gia các CLB thể thao (Futsal, Badminton)  - Khám sức khỏe định kỳ.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 7, Tòa nhà QTSC Building 01, Đường số 14, Lô số 34, Khu Công viên phần mềm Quang Trung, Phường Tân Chánh Hiệp, District 12, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1119, 662, 2, 'ERP Support (Fresher Business Analyst)', 'Let’s become our Application Support, and you will participate in various technology projects at 7-Eleven Vietnam; collaborate closely with product managers and business stakeholders to gather requirements and feedback, and help address those needs effectively; conduct internal training sessions on 7-Eleven services for relevant departments; as an Application Support member, you are responsible for ensuring the delivery of 7-Eleven services to end-users with a focus on satisfaction. You will also support Product Managers in implementing assigned projects and contribute ideas to enhance 7-Eleven services where possible. \n\nWe expect you to duties and responsibilities include, but are not limited to: to create preliminary study documents in terms of business functional area; to create Gap analysis between new or change request and current system; to follow up IT implementation in order to make in line with Business Requirement; manage and maintain all parameters of the applications; frequently review and assess functionalities of in–used application to ensure the solution meets the business process and user ‘s needs; raise changes to development team and involved users if required; support end-users for any functional incidents. \n\nHaving these technical requirements will be your advance 0-1 year Knowledge, Skills and Abilities in Business Analyst / Application Support / Customer Support. Understood analyst and design system, get and sum up requirements, good communication skills. A fast learner, ability to multi-task and work independently under high pressure. Problem solving. Experience in Retail Tech. \n\nYou will love working here because we are cool, optimizing for scale, handling millions records of data; building real-time retails system at scale with Kafka; developing the Retail Management System helps 7-Eleven Vietnam to save cost and earn money such as Ecommerce Website, Payment Gateway, Loyalty Application, Supply Chain System, Warehouse Management System, POS, HHT. Refer on to get more details; modern tech stack (Google Cloud Platform, Docker, Kubernetes, Rancher) and tools (Google Chat, Jira); catching up with new technologies through the process: experiment, trial, adopt; in partnership with Grab, Google, ZaloPay, MoMo, Shopee, TAPTAP, Utop QR, VNPAY, Got It, Urbox for tech & digital integrations; agile at heart, everything is flexible and possible; flat team, nice colleagues, no boss; strong engineering culture, read more of our stories on . And some benefits: the flexible working environment in terms of time, office; (Mon - Fri; 9AM - 5PM); social insurance and comprehensive health care insurance included; support 50% to buy a new MacBook after passing probation (in case you do not use laptop provided by company); 13th month-salary; chances for training and development (learning outdoor/indoor, training course, soft skills); having allowances for meals, mobile phone, birthday, special days; company trip, and many team activities (movies, games, lunch); nice office at the center of Phu My Hung District 7.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cobi Tower II, No. 2-4, Street No. 8, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1120, 663, 2, 'Senior Golang Developer (PostgreSQL, Cloud)', 'Là một Senior Golang Developer tại Sellnity, bạn sẽ là thành viên chủ chốt của đội ngũ kỹ thuật, chịu trách nhiệm chính trong việc:\n- Phát triển và Tối ưu hóa Microservices:\n  - Thiết kế chi tiết, lập trình, kiểm thử và triển khai các microservices cốt lõi của hệ thống (ví dụ: User, Product (PIM), Order (OMS), Platform Integration, Fulfillment...) bằng ngôn ngữ Golang\n  - Xây dựng và bảo trì các API hiệu năng cao, chủ yếu sử dụng gRPC cho giao tiếp nội bộ và RESTful API khi cần thiết\n  - Triển khai các luồng xử lý sự kiện phức tạp, đảm bảo độ tin cậy và khả năng mở rộng sử dụng Kafka\n- Làm việc với Dữ liệu và Hạ tầng:\n  - Thiết kế schema, tối ưu hóa truy vấn và làm việc hiệu quả với các hệ quản trị cơ sở dữ liệu (PostgreSQL/AlloyDB, Redis)\n  - Đóng góp vào việc xây dựng và cải tiến quy trình CI/CD (sử dụng Docker, Kubernetes, GitHub Actions)\n  - Phối hợp với DevOps để đảm bảo các service được triển khai và vận hành ổn định trên môi trường cloud\n- Đảm bảo Chất lượng và Hiệu năng:\n  - Viết unit test, integration test để đảm bảo chất lượng mã nguồn\n  - Tham gia tích cực vào quy trình code review, chia sẻ kiến thức và kinh nghiệm\n  - Xác định và giải quyết các vấn đề về hiệu năng, tối ưu hóa thuật toán và tài nguyên hệ thống\n  - Đảm bảo các giải pháp tuân thủ các tiêu chuẩn về bảo mật\n- Hợp tác và Đóng góp:\n  - Hợp tác chặt chẽ với Product Owner, các kỹ sư khác (Backend, Frontend, QA, DevOps) để chuyển đổi yêu cầu nghiệp vụ thành các giải pháp kỹ thuật khả thi và hiệu quả\n  - Tham gia vào các buổi thảo luận kỹ thuật, đóng góp ý kiến về thiết kế và công nghệ\n  - Nghiên cứu và đề xuất áp dụng các công nghệ, thư viện mới phù hợp với định hướng phát triển của dự án.\n  - Có thể hướng dẫn và hỗ trợ các thành viên ít kinh nghiệm hơn.\n\nYêu Cầu Bắt Buộc:\n- Kinh nghiệm: 3-5 năm kinh nghiệm phát triển phần mềm backend, trong đó có ít nhất 3 năm kinh nghiệm làm việc chuyên sâu và thực chiến với Golang\n- Kiến thức Kỹ thuật:\n  - Hiểu biết vững chắc và có kinh nghiệm thực tế xây dựng, vận hành các hệ thống microservices.\n  - Kinh nghiệm thiết kế và phát triển RESTful APIs và gRPC\n  - Có kinh nghiệm làm việc với event-driven architecture và các message broker như Kafka (hoặc RabbitMQ)\n  - Kinh nghiệm làm việc thành thạo với PostgreSQL (hoặc các SQL DB tương tự) và Redis\n- Hiểu biết tốt về các công nghệ cloud (AWS/GCP/Azure)\n  - Quen thuộc với Docker và có hiểu biết về Kubernetes\n  - Kinh nghiệm với các quy trình CI/CD\n  - Kiến thức vững chắc về cấu trúc dữ liệu, giải thuật và các mẫu thiết kế phần mềm\n- Kỹ năng mềm:\n  - Khả năng đọc hiểu tài liệu kỹ thuật bằng tiếng Anh tốt\n  - Kỹ năng giao tiếp tốt, làm việc nhóm hiệu quả\n  - Tư duy logic, khả năng phân tích và giải quyết vấn đề tốt\n  - Tinh thần trách nhiệm cao, chủ động trong công việc và khả năng tự học hỏi nhanh.\n\nĐiểm Cộng (Ưu tiên):\n- Đã từng tham gia xây dựng các sản phẩm startup công nghệ từ giai đoạn đầu\n- Có kinh nghiệm thực tế sâu với Kubernetes, Istio\n- Có kinh nghiệm làm việc với các công cụ observability (Prometheus, Grafana, Loki, Jaeger)\n- Có kinh nghiệm với AlloyDB hoặc các giải pháp database tối ưu hiệu năng khác\n- Hiểu biết về Domain-Driven Design (DDD)\n- Có kinh nghiệm tối ưu hóa hiệu năng hệ thống (performance tuning) và xử lý các vấn đề về scalability\n- Có kinh nghiệm trong lĩnh vực e-commerce, logistics, ERP, PIM, OMS\n- Biết thêm các ngôn ngữ lập trình backend khác (Node.js, Java, Python) là một lợi thế.\n\nWhy you\'ll love working here:\n- Mức lương cạnh tranh, tương xứng với năng lực và kinh nghiệm\n- Cơ hội làm việc với sản phẩm thực tế, quy mô lớn và có tầm ảnh hưởng quốc tế\n- Tham gia vào quá trình định hình sản phẩm và công nghệ ngay từ giai đoạn đầu\n- Làm việc với các công nghệ mới nhất và đội ngũ kỹ sư tài năng\n- Môi trường làm việc startup năng động, linh hoạt, khuyến khích sự sáng tạo\n- Được hưởng đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định của Luật Lao Động\n- Chế độ nghỉ phép, nghỉ lễ theo quy định\n- Các phúc lợi khác theo chính sách của công ty\n- Review đánh giá năng lực định kỳ (2 lần/năm)\n- Lộ trình phát triển sự nghiệp rõ ràng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, 531 Đường Trần Hưng Đạo, Phường An Hải Tây, Son Tra, Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1121, 664, 2, 'Junior/Middle Web Developers (C#, .NET, ASP.NET)', 'Top 3 reasons to join us\n- Mức thu nhập hấp dẫn, từ 20tr trở lên \n- Dự án thực tế lớn (% thưởng dự án cao)\n- Làm việc với những đồng nghiệp giỏi, không gò bó\n\nJob description\n- Phát triển hệ thống theo kiến trúc MVC 4, 5 .Net, Net Core cho nền tảng trực tuyến.\n- Thực hiện công việc theo thiết kế đã có đảm bảo đúng tiến độ.\n- Hàng tháng được hỗ trợ bổ túc kiến thức, kinh nghiệm từ những chuyên gia đầu ngành\n\nYour skills and experience\n- Có kinh nghiệm làm việc với ngôn ngữ lập trình C#, ASP.NET, MVC;\n- Có hiểu biết Javascript, HTML (HTML5), CSS (CSS3), jQuery, .NET core (kinh nghiệm về  Angular, Jquery JS\n- Nắm vững kiến thức cơ bản về MSSQL Server (2014+)  \n\nNgoài ra ưu tiên các ứng viên:\n- Hiểu biết về Message queues:, MS Windows Service Bus\n- Có kinh nghiệm sử dụng cache như IIS Cached, MemCached, Redis cached;\n- Có kinh nghiệm làm việc với WebAPI, WCF, Windows Services;\n- Tiếng Anh: Đọc hiểu được tài liệu kỹ thuật, ưu tiên những người có chứng chỉ MCP về phát triển phần mềm\n\nWhy you\'ll love working here\n-  Mức lương: 15-30tr/tháng tùy vào năng lực\n-  Thưởng dự án hoàn thành\n-  Thưởng hiệu quả công việc hàng tháng\n-  Thưởng lương tháng 13\n-  Hưởng đầy đủ quyền lợi khi ký hợp đồng chính thức (BHXH, chế độ du lịch, teambuilding ...)\n-  Hỗ trợ 100% tham gia các khóa học liên quan đến công việc\n-  Review lương hàng năm\n-  Trả lương vào ngày mùng 5 hàng tháng\n-  Cung cấp thiết bị, không gian làm việc thoáng đãng, hiện đại, năng động', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Số 1, ngõ 163/8 Nguyễn Khang, Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1122, 665, 2, 'Senior Fullstack Developer (NodeJS/ ReactJS)', 'GIỚI THIỆU\nBlattsolutions là đơn vị tiên phong trong lĩnh vực giải pháp công nghệ và chuyển đổi số. Chúng tôi cung cấp phần mềm tùy chỉnh, hệ thống quản lý doanh nghiệp và giải pháp đám mây, phục vụ đa dạng khách hàng, trong đó phần lớn là doanh nghiệp tại Đức. Với kinh nghiệm làm việc trong môi trường quốc tế, chúng tôi cam kết mang đến giải pháp chất lượng cao, bảo mật và hiệu quả, đáp ứng tiêu chuẩn doanh nghiệp Đức. Môi trường start-up năng động và linh hoạt cùng đội ngũ nhân viên giàu kinh nghiệm, Blattsolutions hứa hẹn sẽ là nơi làm việc xứng đáng để các bạn thử sức.\n\nMÔ TẢ CÔNG VIỆC\n- Thiết kế, phát triển và triển khai ứng dụng web sử dụng NestJS (backend) và Next.js (frontend) hoặc các framework tương đương.\n- Xây dựng RESTful API, GraphQL, WebSockets với hiệu suất cao và khả năng mở rộng tốt.\n- Phát triển giao diện người dùng hiện đại, tối ưu SEO & SSR với Next.js, React.js, Redux, Tailwind CSS.\n- Quản lý cơ sở dữ liệu (PostgreSQL, MongoDB, Redis), tối ưu truy vấn và hiệu suất.\n- Triển khai và quản lý Docker, Kubernetes, CI/CD, AWS.\n- Đảm bảo bảo mật API, OAuth2, JWT, bảo vệ dữ liệu.\n- Quản lý, mentor đội nhóm, đảm bảo coding standards, code review và định hướng phát triển kỹ thuật.\n- Làm việc với khách hàng quốc tế, đặc biệt là thị trường Đức/châu Âu.\n\nYour skills and experience\n- Kinh nghiệm: Tối thiểu 5+ năm trong phát triển phần mềm.\n- Backend: Thành thạo Nodejs, NestJS, TypeScript, Python hoặc các ngôn ngữ tương đương.\n- Frontend: Thành thạo Next.js, React.js, Redux, Tailwind CSS.\n- Database: Quản lý & tối ưu PostgreSQL, MongoDB, Redis.\n- DevOps: Có kinh nghiệm triển khai Docker, Kubernetes, CI/CD, AWS.\n- Bảo mật: Nắm vững OAuth2, JWT, bảo mật API & dữ liệu.\n- Kỹ năng lãnh đạo: kỹ năng dẫn dắt, hướng dẫn thành viên mới.\n- Ưu tiên: Có kinh nghiệm với Prisma ORM, TypeOrm, Serverless (AWS Lambda, Firebase Functions), Hiểu biết về SEO & SSR trong Next.js, Đã làm việc với khách hàng Đức/châu Âu.\n\nWhy you\'ll love working here\n- Mức lương cạnh tranh (lên đến 30.000.000 VNĐ tùy theo năng lực).\n- Phụ cấp ăn trưa 50.000 VNĐ/ tháng.\n- Thưởng theo hiệu suất, dự án, lợi nhuận công ty.\n- Cơ hội thăng tiến lên vị trí quản lý cấp cao.\n- Làm việc với công nghệ tiên tiến, dự án lớn, khách hàng quốc tế (Đức, châu Âu).\n- Chính sách đào tạo & phát triển: Tham gia hội thảo, chứng chỉ chuyên môn, khóa học nâng cao kỹ năng lãnh đạo.\n- Môi trường làm việc chuyên nghiệp, linh hoạt (có thể hybrid/remote tùy dự án).\n- Chế độ phúc lợi đầy đủ: Bảo hiểm sức khỏe & xã hội theo quy định.\n- 12 ngày nghỉ phép/năm, cộng thêm ngày phép theo thâm niên.\n- Lương tháng 13 và thưởng lễ, Tết.\n- Team-building, du lịch hằng năm, các hoạt động gắn kết đội nhóm.\n\nTHỜI GIAN LÀM VIỆC: Từ thứ 2 - thứ 7 ( Nghỉ 2 ngày Thứ 7/ tháng và các ngày Chủ nhật) từ 9:00-18:00 ( nghỉ trưa 1 tiếng 12h30-13h30)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'BT17 Ơ2 phường Hoàng Liệt, Hoang Mai, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1123, 666, 2, 'Data Scientist (Machine Learning, Data Science, AI)', 'Are you looking to be more than just an ordinary Data Scientist? Do you have what it takes to see where you can improve the lives of others through a great and intelligent system to solve issues and improve life? Do you want your products to be used by millions of users in the world and know immediately how much they love your work?\n\nAs a Data Scientist with us, you will utilize a variety of data mining and analysis techniques to generate insights and develop algorithms/models, aiding in product enhancement and informed decision-making across countries. Your ability to turn data into business results and work effectively with diverse teams is crucial. Your passion for machine learning and research will be key in driving better business outcomes.\n\nThis role offers a challenging yet enriching experience in a fast-paced startup environment, revolutionizing the logistics industry with your expertise and passion for technology.\n\nKey Responsibilities:\n- Develop and implement machine learning, deep learning, and LLM-based solutions to address complex logistic challenges.\n- Handle and analyze large datasets with a keen eye for detail.\n- Collaborate across various AI subfields, including tabular data, NLP, and MLOps.\n- Collaborate with cross-functional teams to understand business challenges and objectives, translating complex data into actionable insights.\n- Contribute to the development and infrastructure of AI projects.\n- Work on the entire AI project lifecycle, from problem definition to deployment and monitoring.\n- Proactively propose solutions, conduct independent research, and seek guidance when necessary.\n- Communicate complex ideas clearly and effectively, both verbally and in writing.\n\nYour skills and experience\n\nEducation: Bachelor’s degree in any field, preferably with a combination of software engineering and statistical/mathematical skills.\n\nExperience: 2+ years of experience in a Data Scientist or similar role.\n\nSkills and Abilities:\n- Strong proficiency in machine learning, deep learning, and LLMs.\n- Familiarity with various AI subfields (tabular data, NLP, MLOps).\n- Comprehensive understanding of the AI project lifecycle.\n- Self-driven and capable of independent work.\n- Detail-oriented with a natural intuition for data.\n- Strong analytical and data-driven mindset.\n- Basic knowledge of data warehouses, databases, ETL/ELT, and SQL.\n- Excellent presentation and communication skills.\n\nPersonality Traits:\n- Genuine curiosity and enthusiasm for applying algorithms to solve problems.\n- Strong affinity for AI and a natural state of \'flow\' when working with it.\n- High motivation and a growth mindset to overcome challenges.\n- Comfortable working in a dynamic and fast-paced professional environment.\n\nWhy you\'ll love working here\n- Top 3 reasons to join us\n1. International Working Environment\n2. Stronger Career Path /Learning latest technologies\n3. Competitive compensation & Benefits\n\nBenefits\nREGIONAL COMPANY\n- An exciting opportunity to work with the fastest growing international logistics player.\n- International environment where you can work and learn with coworkers from different southeast asian markets.\n- Opportunities for onsite trip in our operating markets.\n- Flexible Working Hour and location (2 days/month)\n\nFOOD & BEVERAGE\n- Support Meal Allowance\n- Free Flow of Coffee and Drinks\n- Every Month Special Snack & Beers\n- Free Late Dinner Menu from near restaurant\n\nBONUSES\n- Loyalty Bonus Package\n- 13th Month Salary\n\nHEALTH & LEAVES\n- Annual Health Checkup\n- 100% Insurance According To Labor Law\n- Premium Healthcare Insurance Package \n- 15 Days Paid Annual Leave\n\nDEVELOPMENT PROGRAMS\n- Monthly Technical Sharing\n- Develop Personalized Career Path\n\nSOCIAL & ENTERTAINMENT\n- Welcome Kit From Deliveree\n- Welcome Gift Funky Toy (as part of our longest tradition)\n- Regular Team Social Events (Quarterly Company Parties)\n- Social Club activities\n- Cool Entertainment Area (Guitar, Video Games, ...)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '431 Hoàng Văn Thụ, Phường 4, Tân Bình, Hồ Chí Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1124, 402, 2, 'Senior/Lead Software Engineer (Java, Kotlin, Python)', 'Top 3 reasons to join us\n- Big Data\n- Machine Learning\n- Big scale\n\nJob description\n- Build robust, large-scale, high-performance systems with multiple components and constraints.\n- Research, design, and implement solutions for various fintech applications (e.g., decision engine, recommendation, user segmentation).\n- Deliver a complex project on time.\n- Collaborate with various teammates to productionize solutions at scale.\n- Optimize the performance and monitor real-time services.\n- Participate in implementing experimentation and deployment workflows.\n- Contribute to improving data quality, service quality, and experimentation tools.\n\nYour skills and experience\n- At least 5+ years as a Software Engineer, with fluency and experience in either backend languages such as Java, Kotlin, Python.\n- Bachelor’s Degree of Computer Science, Engineering, or related field\n- Strong foundation & engineering skills. Experienced in building high-performing systems.\n- As a builder, you go the extra mile to bring your prototypes to production.\n- Strong product ownership. You take a high responsibility for what you build. You keep a high bar for product quality.\n- Strong collaboration skills. You reach out to help other team members.\n- Experienced working with cloud services such as GCP, AWS, Azure is a plus.\n- Front-end working is a plus.\n- Experience in machine learning and rule-based systems is a plus.\n\nWhy you\'ll love working here\nWe are passion with new technologies, not follow the old-track of outsourcing. We love our product and ready to sacrifice everything for it! You often argue with your boss? Don’t worry, here in M_Service, you will get salary increase if you win your boss in argument. We love objection!!! You hate company trip in hotel, resort? We only conquer difficult and hottest road in team building. Do you want to join?\nWhat you will get:\n- Competitive compensation package.\n- Performance-based bonus.\n- Insurance package.\n- Chance to work with smart people with international experience.\n\nOur benefits:\n- Attractive compensation & benefits.\n- 13th month salary bonus and yearly performance bonus.\n- 14 paid days off per year\n- Premium health care insurance\n- Great allowances (lunch, parking, birthday, happy hours....)\n- Salary review  at least one time per year based on employee\'s performance and contribution.\n- Outing/team-building activities (company trip , soccer sport, english club, running club,..).\n- Other benefits as per stated in Vietnamese Labor Law\n- Work with experienced & strong team.\n- Friendly, dynamic & flexible working environments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '6th Floor, Phu My Hung Tower, 08 Hoang Van Thai Str, Tan Phu Ward, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1125, 258, 2, 'VIC - Mobile Developer (Flutter/ Android/iOS)', 'Top 3 reasons to join us\n- Dẫn đầu thị trường\n- Cơ hội thử thách và phát triển bản thân\n- Môi trường làm việc năng động\n\nJob description\n- Tham gia phân tích, thiết kế, phát triển, triển khai và quản lý các sản phẩm trên nền tảng Mobile App, đảm bảo đáp ứng lượng truy cập cao, tối ưu hóa trải nghiệm người dùng.\n- Ưu tiên hiệu suất và tính ổn định, đảm bảo khả năng xử lý tốt trong các tình huống phát sinh như tăng đột biến lưu lượng, tấn công, sự cố, ...\n- Làm việc với backend để tích hợp RESTful API, WebSocket, GraphQL, tối ưu hóa luồng xử lý, dữ liệu.\n- Triển khai các tính năng liên quan đến bảo mật cho mobile app như biometric authentication, passwordless, mã hóa dữ liệu.\n- Xử lý và khắc phục các lỗi, sự cố phát sinh trong quá trình phát triển và sau khi triển khai\n- Hướng dẫn, hỗ trợ khách hàng nắm nghiệp vụ trên hệ thống, xử lý lỗi phát sinh.\n\nYour skills and experience\n- Tốt nghiệp đại học loại khá trở lên chuyên ngành Công nghệ thông tin, Công nghệ phần mềm, Khoa học dữ liệu, Khoa học máy tính, Toán học ứng dụng, Điện tử viễn thông hoặc liên quan.\n- TOEIC >= 550 hoặc tương đương.\n- Có ít nhất 5 năm kinh nghiệm phát triển mobile app (Android, iOS), trong đó có ít nhất 03 năm kinh nghiệm phát triển ứng dụng mobile sử dụng Flutter.\n- Có kiến thức tốt về Native (iOS, Android)\n- Hiểu và có thể triển khai phần mềm theo kiến trúc phổ biến như: MVC, MVVC, Clean Architecture,...\n- Hiểu và triển khai thành thạo các Design Pattern như: Singleton, Factory, Protocol, ...\n- Có kinh nghiệm tích hợp module native vào ứng dụng cross-platform.\n- Có kinh nghiệm tham gia vào các Super app hoặc các ứng dụng triển khai dưới dạng Microservices FE là 1 lợi thế.\n- Có kinh nghiệm về nền tảng cross-platform khác như: React Native, Ionic,... là 1 lợi thế.\n\nWhy you\'ll love working here\n- Môi trường làm việc cởi mở và năng động, khuyến khích trao đổi ý tưởng ở mọi cấp, cho phép bạn làm việc, sáng tạo theo cách riêng.\n- Được khơi gợi cảm hứng làm việc với văn phòng xanh, không gian mở, hiện đại tiêu chuẩn quốc tế.\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày.\n- Thưởng thức bữa trưa thơm ngon tại Tập đoàn, được chọn lọc bởi các chuyên gia dinh dưỡng.\n- Cơ hội tham gia gắn kết với tập thể, tổ chức với các hoạt động team building.\n- Chế độ chăm sóc y tế đặc biệt cho CBNV và người thân với trang thiết bị hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tầng 5, Trụ sở chính của Tập đoàn Viettel, Lô D26, Khu đô thị mới Cầu Giấy, phường Yên Hòa, Cau Giay, Ha Noi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1126, 432, 2, 'Mid/Senior Fullstack .NET Engineer', 'Top 3 reasons to join us\n- Attractive Package and Dedication bonus\n- Hybrid and flexible working environment \n- Working directly with Agile global teams\n\nJob description\n- Design, develop, review, implement, and manage continuous integration, build management and deployment scripts, systems, and any code as required;\n- Participate in Agile software development, prototyping, and code review with international development teams to build scalable products and APIs using ASP.NET technologies on Azure and AWS Cloud architecture.\n- Play in a dynamic, collaborative, transparent, non-hierarchical, and ego-free culture where your talent is valued over a role title.\n- Work in collaborative teams and build quality code.\n- Help the team champion software quality, engender technical vision, and ensure clients are satisfied.\n\nYour skills and experience\nMust have:\n- At least 3 years of experience in Software Development with a similar role, focusing on .NET\n- Strong skills in C#, TypeScript, React, Angular, and GraphQL\n- Extensive experience with Azure and AWS cloud platforms\n- Proficient in working with relational databases, such as MS SQL, PostgreSQL, and MySQL\n- In-depth understanding and hands-on experience with microservices architecture\n- Familiar with Kafka and Redis for data streaming and caching\n- Proven experience in Agile development environments\n\nSoft skills:\n- Proficient in interpersonal and communication skills in both English and Vietnamese.\n- Collaboration: Work effectively in teams, share knowledge, and support mutual progress.\n- Openness: Foster an open environment where ideas and feedback are valued.\n- Learning Mindset: Embrace challenges, adapt to change, and prioritize continuous learning.\n\nWhy you\'ll love working here\n- Attractive and competitive performance-based compensation package\n- Generous year-end 13th-month bonus\n- Loyalty and annual dedication rewards\n- Comprehensive healthcare package with premium insurance and annual health check-ups\n- Flexible check-in time, 1-day remote work per week, and the freedom to work from any of our offices in Da Nang, Hue, or Ha Noi\n- 12 annual leave days, 11 public holidays, 1 Christmas day off and 5 sick leave days\n- Breakfast are available at office in early morning and snack in late afternoon.\n- Team-building allowance and annual company trips for a fun and connected workplace\n- Sports & hobby clubs with football, badminton, biking, running, chess, or music band groups\n- Continuous learning & development with exclusive technical & soft skills training, English classes, and technical clubs\n- Financial aid for marriage, newborns, and bereavement to support you through every stage of life.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ha Noi, Da Nang, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1127, 667, 2, 'Business Analyst', 'About Trustify Technology \nTrustify Technology brings to the world its excellent in Software Development & Testing Services as well as its cutting-edge solutions that can elevate the client product & service delivery. We become the trust partner in IT outsourcing by its collaborative approaches and how the cooperative steps are being nature.\n\nAbout Business Analyst Position\nWe are seeking a skilled IT Business Analyst with a solid background in the finance/accounting domain to join our dynamic team. In this role, you will be working closely with our UK-based client, collaborating across cross-functional teams to gather, analyze, and document business and technical requirements for various financial systems and solutions.\n\nResponsibilities\n- Collect and analyze business and system requirements from clients.\n- Prepare requirement documents, process flows, and functional specifications.\n- Collaborate with UK clients and internal teams for solution design and validation.\n- Monitor project progress, support testing phases, and address issues promptly.\n- Bridge communication between business users and technical teams.\n- Contribute to risk assessment and change impact analysis activities.\n\nYour skills and experience\n- Minimum 3 years of experience as a Business Analyst in IT projects.\n- Proven experience in the finance, accounting, or fintech domains.\n- Strong analytical and problem-solving skills.\n- Experience with tools such as JIRA, Confluence, Balsamiq, Figma, MS Visio, and MS Office Suite.\n- Good English communication.\n- Having a technical background is a strong plus.\n\nWhy you\'ll love working here\n- You play a key to success in our team.\n- Well compensation package based on performance and value creation.\n- Opportunities to work with talent people and deliver the best product to improve health.\n- Your Benefits upon this position\n- Bonus review bi-annually based on performance.\n- Bonus for excellent project performance.\n- Annually company trip & project close team outing.\n- Additional health care policy for employees Healthcare: Annual health check-up, Premium Health Insurance (Trustify Care).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Sabay Building, 40/4 Lam Son , Tan Binh, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1128, 198, 2, 'Senior Associate, AI-Powered Product Analysis and Ops', 'Are you driven by a passion for shaping the future of AI-powered products and thrive in a collaborative, fast-paced, and innovation-focused environment? At Renn Labs, we believe in the power of technology to transform industries, and we’re looking for Senior Product Associates to help us take our AI solutions to the next level. Join a dynamic team where your insights and creativity will directly contribute to building groundbreaking products that redefine the market. This isn’t just another job - it’s your chance to make a lasting impact while working with a team that values collaboration, excellence, and cutting-edge thinking.\n\nTHE IMPACT YOU\'LL MAKE IN THIS ROLE\n\n- Comprehensively conducting detailed market and competitor research to identify emerging trends and inform product strategy;\n- Diligently conducting planned testing and experimentation to optimize product features and improve user experiences;\n- Thoughtfully uncovering actionable insights by analyzing user behavior, product performance, and key metrics using analytics tools;\n- Precisely translating defined business needs into technical requirements for development teams, bridging the gap between all stakeholders;\n- Efficiently facilitating conducted requirement-gathering sessions and creating detailed documentation such as user stories, process flows, and acceptance criteria;\n- Fruitfully collaborating with teams to design and optimize thoroughly processes, ensuring they align with product capabilities;\n- Rigorously conducting product roadmap by facilitating operations, tracking progress, validating that solutions meet business and user expectations, and helping to maintain clear communication across teams;\n- Closely track key product performance metrics, gather user feedback and project metrics, using this data to recommend process improvements and product adjustments;\n- Compellingly presenting findings and recommendations through crafted reports, dashboards, and visualizations to drive informed decision-making;\n- Meticulously collaborating with Product Managers to define and maintain a data-driven roadmap, prioritizing features that deliver maximum value to users, identifying bottlenecks, risks, and blockers in the product lifecycle, working to resolve them and improve efficiency;\n- Dynamically staying at the forefront of evolving industry trends and emerging technologies, incorporating best practices into product and business strategies;\n- Constantly fostering a culture of creativity, collaboration, adaptability, persistence, a results-driven focus, high standards for deliverables, and continuous improvement within the Software team and throughout the entire company.\n\nWHAT YOU’LL NEED TO MAXIMIZE IMPACT IN THIS ROLE\n\n- Bachelor’s degree in Computer Science, Business, Data Analytics, or a related field, or equivalent practical experience.\n- Above 3 years of experience working as Product Analyst, Business Analyst, Product Owner, Project Coordinator, Product Operations etc.; The designated title will be assigned based on your strengths, experience, and potential for growth.\n- Experience gathering, analyzing, researching, documenting, and translate business needs into technical solutions;\n- Knowledge of UX design principles and one or many tools such as Figma, InVision, Adobe XD, Balsamiq etc.;\n- Proficiency with analytics tools (e.g., Google Analytics, SQL, Tableau, PowerBI etc.) and A/B testing methods;\n- Experience working in Agile frameworks and familiarity with product collaboration tools;\n- Strong analytical thinking, problem-solving skills, high attention to detail and accuracy in work delivery;\n- Excellent communication and interpersonal skills, allowing for effective collaboration in a fast-paced global environment;\n- Demonstrated ability in handling multiple projects simultaneously will set your application apart and give you a distinct advantage;\n- Last but not least, an eagerness to learn and a startup spirit at heart. This role provides extensive exposure to AI-driven product development, offering a pathway to advance in the future of technology.\n\nFeeling like you don\'t match all the criteria? That\'s completely fine. Done is better than perfect. We set our sights high and look toward a future filled with possibilities. We believe that when you possess an intense passion for creating high-value products and a commitment to continuously sharpening your skills, you can accelerate our journey towards these ambitious goals. If this job excites you even slightly, feel free to click apply. Let\'s start a conversation and explore the possibilities together.\n\nWhy you\'ll love working here\n\nAI-FIRST VENTURE STUDIO with decades of experience in entrepreneurship and innovative technology.\nRenn Labs is an exclusive innovation studio committed to incubating cutting-edge experiments and developing transformative solutions in AI, finance, and e-commerce. Our mission is to create exponential impact, empowering select partners to accelerate their growth and revolutionize their industries. Spearheaded by a top-tier venture capitalist and investor based in the United States and bolstered by a team of diverse experts, our expanding team in Vietnam is at the forefront of groundbreaking innovation.\nAt Renn Labs, we leverage a variety of AI techniques across our projects in the realms of investment and e-commerce. Our products are powered by advanced technologies, including OpenAI, Perplexity, Claude, and Gemini. We employ a range of approaches such as RAG, Roleplay, Replay, ReAct, Few-shot Learning, Chain of Thought etc.\nHere are some of our fascinating projects:\n- An AI-powered fundraising platform that is transforming the alternative investment industry. It provides access to 150K+ firms in the industry and includes an AI memo tool for writing sophisticated documents. Additionally, the platform features a due diligence tool that allows users to interact with financial documents. It also includes an AI-powered news curator tailored to the industry.\n- An AI-powered newsletter digest that helps individuals and companies navigate the ocean of information in the new AI age. It personalizes the newsletter experience by allowing users to choose from a curated list of the top 20 newsletters or connect Gmail to receive summaries of other newsletters.\n- An AI concierge for gift shopping that makes finding the perfect gift easier, faster, and more enjoyable.\n- An AI content platform for next-generation e-commerce that establishes a strong data foundation and connectivity to enable hyper-scalable generative content. It features product intelligence, generative AI content, enrichment and standardization, and microsite development.\n- An AI powered automated SEO content generator with best practices. It offers keyword analysis, competitor analysis, content generation, internal and external linking, and platform deployment.\n- And more projects that could originate from your ideas.\nRenn is embarking on an exciting “AI First” journey, harnessing cutting-edge technologies and methodologies adopted by top tech and digital innovators across the globe. Our transformation goes beyond just technology. We are deeply committed to investing in our people with AI tools.\nWe are a collective of innovators, thinkers, and creators. Our culture is built on the foundation of experimentation, continuous learning, and a relentless pursuit of excellence. We believe in empowering our small team to make big contributions, ensuring that every voice is heard and every idea is valued.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '200 Street 3/2, District 10, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1129, 305, 2, 'QA Manager (Head of Quality)', '1. Define and Lead QA Strategy: Develop and implement a comprehensive QA strategy aligned with VNGGames\' goals, including test planning, risk management, and quality standards.\n2. Drive Process Improvement: Embed quality throughout the development lifecycle by initiating process improvements and fostering a culture of continuous improvement.\n3. Lead QA Team Execution: Oversee the QA team in planning and executing manual, automated, and exploratory testing efforts.\n4. Collaborate with Cross-Functional Teams: Work closely with Product, Engineering, and DevOps teams to ensure clear requirements and shared ownership of quality.\n5. Champion Shift-Left Mindset: Promote early testing and quality feedback throughout the development process.\n6. Oversee Test Coverage and Reporting: Monitor test coverage, identify gaps, and guide resolution of quality issues.\n7. Set Quality Metrics and KPIs: Define and track quality metrics to ensure continuous improvement in platform reliability and performance.\n8. Mentor and Grow Team: Coach, train, and develop QA team members to enhance their skills and performance.\n\nYour skills and experience\n1. Certification: ISTQB Foundation certification or equivalent knowledge.\n2. Experience: At least 5 years of experience in software quality assurance, including 2+ years in a leadership role.\n3. Technical Knowledge: Strong understanding of modern QA practices, Agile development, and SDLC.\n4. Team Building: Proven experience building or scaling QA teams and implementing effective testing processes.\n5. Communication Skills: Ability to communicate effectively with technical and non-technical stakeholders.\n6. Strategic Thinking: Capacity to balance quality goals with time and resource constraints.\n7. Automation Familiarity: Knowledge of test automation concepts and tools (e.g., Selenium, Playwright, Postman) to lead automation efforts.\n\nNICE TO HAVE:\n- ISTQB Advanced Level certification or similar.\n- Background in software development or strong programming knowledge.\n- Experience defining quality metrics and QA processes.\n- Exposure to performance testing, security testing, or compliance-related QA.\n\nWhy you\'ll love working here\n- Competitive Package & Perks\n- Career Growth & Internal Mobility\n- Modern workspace & Unique Culture\n- Product-Driven, Cutting-Edge & Scalable Technology\n- Global Mindset & Regional Ambitions', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Z06 Đường số 13, Phường Tân Thuận Đông, Quận 7, Thành phố Hồ Chí Minh, Việt Nam, District 7, Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1130, 668, 2, 'Software Engineer Intern', 'Responsibilities\n\n- Assist in developing backend services of new features, delivering to our standard on time.\n- Collaborate with engineering to enhance the code quality and automated testing.\n- Investigate cutting edge technologies to improve site reliability, developer experience, customer experience, and raw performance.\n- Think outside the day-to-day and propose ways to elevate the art of e-commerce engineering.\n\nRequirements\nMust have\n\n- Solid computer science fundamentals such as theories, data structures, OOP, algorithms, design patterns, etc.\n- Experience with SQL, relational databases and noSQL ones.\n- Knowledge in the design or architecture of one or more projects in the school.\n- Good people skills.\n- Basic English communication skills, especially with reading and writing.\n\nNice to have\n\n- Learning computer science or related technical discipline.\n- Any trials with a testing framework (PHPUnit, Selenium, RSpec, Mockito).\n- Experience of message broker tools, web services (AWS, GCP, Azure or any cloud service providers).\n- Agile / Scrum software development processes.\n\nZALORA Engineering\n\nZALORA is the leading e-commerce company providing fashion throughout Southeast Asia. ZALORA Engineering has teams in Singapore and Vietnam to serve millions of users in Malaysia, Singapore, Hong Kong, Taiwan, Indonesia, Philippines. This regional diversity presents a lot of interesting challenges that you and your colleagues will face. You will learn a lot by tackling these challenges.\n\nZALORA\'s e-commerce platform is built with love by the engineering team. The Ho Chi Minh office, 12 Ton Dan, D4 (ZALORA Group) focuses completely on engineering and sets a high standard for software development in the field of e-commerce. This team creates the tech stack that powers ZALORA\'s stellar shopping experience. This ranges from the online shop and the mobile apps to ZALORA\'s complex logistics solutions.\n\nThe ZALORA Story\n\nZALORA is Asia’s leading online fashion, beauty and lifestyle destination, part of Global Fashion Group. As one of the region’s pioneer large-scale ecommerce platforms, ZALORA has established a strong presence throughout the region, particularly in Singapore, Indonesia, Malaysia, Brunei, the Philippines, Hong Kong, and in Taiwan, enjoying over 50 million visits per month.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 ホーチミン', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1131, 669, 2, 'Backend Engineer Intern (Full-time)', 'Apply Now\n\nHo Chi Minh\n\nFull-time\n\n26/05/2025\n\nAbout Firegroup Technology\n\nFireGroup envisions and strives to shape a world where e-commerce is easy, effective, and sustainable. Since our founding in 2016, we have specialized in providing a comprehensive portfolio of category-leading SaaS products for the global e-commerce market, including online store development, store management, sales & marketing automation, and almost every aspect of running an online business. After almost a decade in the market, we are loved by over 450,000 merchants and enterprises across 175+ countries and highly trusted by our globally renowned partners such as Shopify, BigCommerce, WooCommerce, Google, Meta, Tiktok, and Amazon.\n\nAs we continue on our development path, we relentlessly overcome challenges to develop innovative products that comprehensively and effectively solve problems in e-commerce, making online business easy and sustainable for everyone. Together, we aspire to build a future in which FireGroup emerges as a global leader in e-commerce innovation, offering world-class products trusted by industry experts around the world.\n\nWhy to build your career with us\n\nMake your impact globally on hundreds of thousands of merchants’ success\nDevelop your skills in a fast-paced and highly competitive SaaS market\nCreate and grow continuously among passionate talents with growth mindsets\n\nResponsibilities\n\nPHP/ NodeJS Development: Learn and apply PHP, JavaScript programming language to develop backend services\nDatabase Interactions: Learn to work with databases (e.g., PostgreSQL, MySQL) to store and retrieve data.\nCode Review and Improvement: Participate in code reviews to learn best practices and improve code quality.\nTesting and Debugging: Assist in writing unit and integration tests to ensure code reliability.\nProblem-Solving: Collaborate with the team to identify and solve technical challenges.\n\nQualifications\n\nStrong Academic Foundation: Pursuing a degree in Computer Science, Software Engineering, or a related field.\nProblem-Solving Skills: Ability to analyze problems and propose solutions.\nTeamwork: Effective communication and collaboration skills.\nCuriosity and Learning Mindset: Eagerness to learn new technologies and improve skills.\n\nBenefits\n\nDynamic working environment, many challenging opportunities, empowered to improve skills and abilities.\nGain practical, real-world experience in a dynamic E-commerce/ Technology environment.\nParticipate in the internal activities and additional benefits of the Company.\nBuild up a quality professional network.\nInternship allowance.\n\nThank you for your interest in the Backend Engineer Intern position at FireGroup Technology!\n\nPlease complete the FORM to help FireGroup assess your suitability for the role.\n\nContacts\n\nShould you need more information about this job, reach out to us at:\n\nTalent Acquistion team\n\nFireGroup’s Linkedin fanpage', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1132, 670, 2, 'FRESHER JAVA DEVELOPER', 'TPS Software is looking for enthusiastic and talented Fresher Java Developers to join our dynamic team. You’ll be part of a collaborative team focused on developing and maintaining innovative solutions across Fintech, Telecom, and other industries. Your key responsibilities are:\n\n- Participate in all phases of the development life cycle.\n- Develop well-designed, efficient source code and conduct unit and automation tests.\n- Perform bug fixing, maintenance, and enhancement of existing web modules.\n- Involve in team discussions to find solutions for new requirements.\n\nYour Experience And Skills\n\n- Bachelor’s or Master’s degree in Computer Science, Engineering, Mathematics, or a related field.\n- Solid understanding of Java Core and Java EE technologies (Servlets, JSPs/JSF, WebSocket, Spring Boot).\n- Familiarity with frontend frameworks like ReactJS and Angular.\n- Excellent interpersonal and communication skills.\n- Self-motivated and eager to learn.\n- Strong analytical and problem-solving abilities.\n- Good command of English (written and verbal).\n\nWhy you’ll love working with us?\n\n- Quarterly salary review for adjustment; yearly performance review for promotion\n- Opportunities for promotions and career development in a dynamic environment\n- Many exciting internal activities and meaningful corporate social responsibility (CSR)\n- Annual company trip\n- Working 5 days/week, from Mon-Fri, and 12-15 days of annual leave; maximum 30 sick leave days/year.\n- “Share to learn and learn to share” philosophy, friendly working environment with many energetic buddies.\n\nLocation: Tan Binh District, Ho Chi Minh City', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1133, 366, 2, 'UI Frontend Engineer (Intern Level)', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nWe are looking for UI Frontend Engineer (Intern Level)\n\nYour day-to-day:\n\nWe are looking for a passionate UI Engineer Intern to join Naver Vietnam, where you will contribute to the development of internal projects, focusing on building intuitive and user-friendly interfaces. As an intern, you will:\n\n- Work on internal web applications and tools, improve usability and functionality.\n- Collaborate with engineering and designing teams to develop high-quality UI components.\n- Gain hands-on experience with core technologies and apply them effectively in real-world scenarios to build confidence for future projects.\n\nYour qualification:\n\n- Proficient understanding of HTML/CSS and Javascript.\n- Understanding of UI/UX design principles, wireframing, and prototyping.\n- Understanding Design System knowledge.\n- Proficient in Responsive/Adaptive Design.\n- Experience with version control systems, like Git.\n- Familiar with software like Figma, and content management systems (CMS).\n\nIt\'s a big plus if you:\n\n- Strong design thinking, color sense, and typography skills.\n- Ability to build new Front-end frameworks like Bootstrap, Semantic-UI, Skeleton, etc.\n- Ability to coach and mentor team members in their professional development and build a self-organizing team.\n- Can Speak Korean.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1134, 671, 2, 'Software Development Intern', 'WebMD is an Equal Opportunity/Affirmative Action employer and does not discriminate on the basis of race, ancestry, color, religion, sex, gender, age, marital status, sexual orientation, gender identity, national origin, medical condition, disability, veterans status, or any other basis protected by law.\n\nAbout the Role:\nAre you a curious and motivated individual looking to gain real-world experience in software development? Join our team as a Software Development Intern and get hands-on exposure to modern technologies, agile practices, and a collaborative, fast-paced work environment.\n\nThis internship is designed to help you learn and grow. You’ll work closely with experienced developers, contribute to real projects, and sharpen your problem-solving skills.\n\nWhat You’ll Gain:\nMentorship from experienced software engineers developing enterprise applications\nExposure to production-level code and agile development with CI/CD\nOpportunity to contribute to meaningful projects\nA chance to transition into a full-time role based on performance\n\nWe have 2 types of interns: Backend Development Intern & Full Stack Development Intern.\n\n1) Backend Development Intern\nWhat You\'ll Do:\nAssist in building and maintaining web applications using modern frameworks like Ruby on Rails.\nCollaborate with developers on designing, coding, testing, and deploying features.\nParticipate in code reviews and agile team activities (e.g., stand-ups, retrospectives).\nHelp integrate third-party APIs and work with relational databases such as MySQL or PostgreSQL.\nWrite and maintain unit and integration tests under guidance (e.g., RSpec, Cucumber).\nLearn about DevOps practices such as CI/CD, AWS, and Docker through hands-on exposure.\nExplore best practices in software engineering, including TDD, Microservices, and Object-Oriented Design.\n\nWhat We Look For:\nCurrently pursuing or recently completed a degree in Computer Science or Software Engineering.\nSome coding experience with any programming language — Ruby, Java, PHP preferred.\nBasic understanding of web development frameworks (e.g., Rails, Laravel, Spring).\nEagerness to learn, ask questions, and work as part of a team.\nGood analytical and problem-solving skills.\nComfortable communicating in both Vietnamese and English.\n\n2) Full Stack Development Intern\nWhat You\'ll Do:\nAssist in building and maintaining web and/or mobile applications.\nCollaborate with developers on designing, coding, testing, and deploying features.\nParticipate in code reviews and agile team activities (e.g., stand-ups, retrospectives).\nExplore best practices in software engineering, including TDD, Microservices, and Object-Oriented Design.\n\nWhat We Look For:\nCurrently pursuing or recently completed a degree in Computer Science or Software Engineering.\nSome coding experience with:\nBackend: .NET Core with C#, ASP.NET Web APIs.\nFrontend: React/Angular, pure JavaScript.\nUnderstanding of object-oriented programming (OOP).\nComfortable communicating in both Vietnamese and English.\nBasic knowledge of Git and version control workflows.\n\nWe Prefer candidates with:\nFamiliarity with REST APIs, JSON, and web/mobile app architecture.\nEnthusiastic about UI/UX and attention to design details.\nCuriosity and willingness to explore AI-powered tools and workflows (e.g., GitHub Copilot, ChatGPT).\nEager to learn, adaptable, and self-motivated.\nEffective communication skills, IELTS 6.0 preferred.\nAttention to detail and willingness to receive feedback.\nEnthusiastic about mobile technologies and staying current with trends.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona metropolitană Ho Chi Minh City', 'Internship', '2025-10-07 20:59:18.149534'),
	(1135, 450, 2, 'Software Engineer Intern - Frontend', 'Our Journey\n\nShopBack began in 2014 as a late-night spark of inspiration between Henry and Joel — not just to build a Cashback platform, but to reimagine how brands and consumers connect. As former advertisers, they understood the limitations of traditional marketing, and saw an opportunity to deliver more value on both sides. That idea quickly turned into action, with the first prototype built during a 24-hour sprint. Today, ShopBack serves over 50 million users across 13 markets, partners with 20,000+ merchants, and powers over half a million transactions daily. We\'re building The World’s Most Rewarding Way to Shop — and looking for bold, driven individuals to join us.\n\nYour Adventure Ahead\n\n- Build stable, performant and highly available applications for our customers, merchants, and operators\n- Work on modern frontend web applications\n- Design and build APIs for meaningful user experiences on web and mobile\n- Improving and automating engineering processes to improve delivery velocity and quality\n\nEssentials To Succeed\n\n- Strong knowledge of HTML, CSS, and JavaScript\n- Some experience with relational or non-relational databases\n- Strong written and verbal communication skills\n- Active team player with strong problem-solving skills\n- Attention to detail and demonstrable design and UX sensibilities\n- Experience with client-side frameworks is a plus (Angular, Ember, Vue, React etc)-- Needed\n- Experience with server-side frameworks is a plus (Rails, Django, Spring, Nestjs, Nextjs etc)\n- Applicants from all varsities are welcome to apply, including University, Polytechnic, and ITE\n- Minimum commitment period of 6 months, full-time \n\nShopBackers\' DNA\n\n- Grit - We tackle all challenges head-on, working together to solve problems and achieve success.\n- Hunger - We value hard work, and having relentless drive.\n- Speed - We move fast and have a bias for action, all to deliver maximum impact.\n- Impact - We focus on results, always aiming for the best possible outcomes and timelines.\n- Growth - We embrace a growth mindset, constantly striving to learn, improve, and excel in our roles.\n\nExclusively for ShopBackers\n\n- Career progression paths and opportunities to take on greater challenges that help you realise your ambitions.\n- Be part of a winning team on a journey to global scale.\n- Competitive compensation based on your performance.\n- Candid, open, and collaborative culture where feedback is valued, for everyone to grow and improve every day.\n\nShopBack is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. We do not discriminate on the basis of race, color, religion, sexual orientation, national origin, age, disability, genetic information, veteran status, or any other protected status under applicable laws. Join our team and help us make a difference!\n\nWe are committed to protecting your data and ensuring fairness in our recruitment process. As part of this process, we use AI tools to assist with tasks such as application screening and candidate matching. These tools are designed to enhance efficiency and reduce bias, and their use complies with applicable data protection laws and our commitment to fair employment practices. Your personal data will be processed securely and transparently, and final hiring decisions are always made by our recruitment team, not by automated systems. If you have any questions about how your data is used, or wish to exercise any of your rights including the right to such processing, please contact us at dpo@shopback.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1136, 672, 2, 'Junior Frontend (UI) Software Engineer (Internship)', 'About Us\nTGM Research is one of the fastest growing and most innovative market research companies, offering valuable insights to businesses across various industries. We are committed to delivering high-quality market research solutions to our clients by connecting them with the right participants through our online panels.\n\nIf you are proactive, curious, creative type of person, who is a great team player and doesn’t hesitate to take responsibility and lead an independent project, we invite you to join our team and help our clients succeed in their research endeavours!\n\nAbout The Role\nAs a Junior Frontend (UI) Software Engineer, you will be responsible for developing and maintaining user-facing features of web applications. You will work closely with UX/UI designers, backend developers, and other team members to translate design wireframes and prototypes into functional, responsive, and visually appealing web interfaces. This role is ideal for someone starting their career in frontend development who is eager to learn, collaborate, and grow their technical skills.\n\nWe offer a 6-month trainee contract, with the possibility of extending it to a professional contract upon positive feedback after the trainee period.\n\nWhat You\'ll Do\n- Develop, test, and maintain responsive web pages and user interface components using HTML, CSS, and JavaScript.\n- Collaborate with UX/UI designers to implement design concepts and ensure brand consistency.\n- Work alongside backend developers to integrate frontend components with server-side logic.\n- Optimize web applications for maximum speed and scalability across devices and browsers.\n- Participate in debugging and fixing UI bugs and issues.\n- Ensure cross-browser compatibility and mobile responsiveness.\n- Write clean, maintainable, and reusable code following best practices.\n- Assist in creating and maintaining documentation related to frontend development.\n- Stay updated with emerging frontend technologies and industry trends.\n- Participate in code reviews and team knowledge sharing sessions.\n\nWhat We\'re Looking For\n- Proficiency in English - required\n- Basic to intermediate proficiency in HTML5, CSS3, and JavaScript.\n- Familiarity with frontend frameworks/libraries such as React, Angular, or Vue.js is a plus.\n- Understanding of responsive and adaptive design principles.\n- Ability to collaborate effectively with designers, backend developers, and other stakeholders.\n- Strong problem-solving skills and attention to detail.\n- Eagerness to learn new technologies and improve coding skills.\n- Good communication skills and ability to work in a team environment.\n- Experience with version control systems like Git is preferred.\n- Exposure to debugging tools such as Chrome DevTools.\n\nNice To Have\n- Knowledge of UI/UX design principles.\n- Experience with accessibility standards and SEO best practices.\n- Familiarity with Agile development methodologies.\n- Basic understanding of web performance optimization techniques.\n- Experience with content management systems and graphic design tools.\n\nWhat We Offer\n- Competitive salary and performance-based bonuses, based on experience\n- Professional development opportunities\n- International Team setup\n- Flexible Working Policy \n- A collaborative and innovative work environment\n- Working with the newest technologies and using modern tools\n\n#marketresearch #software #softwareengineer', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'HCMC, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1137, 673, 2, 'Software Engineer Intern', 'Company Description\n\nRakuna is an HR technology company based in Silicon Valley, US, and Hanoi, Vietnam providing total recruiting solutions for employers.\n\nWe are looking for a motivated and enthusiastic Software Engineer Interns to join our team!\n\nAs a Junior Software Developer, you will be responsible for supporting our software development team in all aspects of the development, testing, and implementation of our product.\n\nWant to be part of a transformative, learning culture that drives innovation? Join us!\n\nFor more info: https://www.rakuna.co/\n\nJob Description\n\n- Assist in building and/or managing product pipelines including planning, development, and maintenance. \n- Analyze information and evaluate results to choose the best solution to effectively solve problems. \n- Provide quality assurance (QA) support through product testings. \n- Work with peers, managers, and teams to create and support core functional teams - Sales & Marketing, Quality and Customer Success, and Operations. \n- Learn in-depth about how to create a product in a start-up environment. You might be the next entrepreneurial commander for your future start-up!\n\nQualifications\n\nMust have:\n\n- Commit at least 6-months as full-time intern; may have the opportunity to be offered full-time position post-internship if shown excellency at work. \n- Currently enrolled in a Bachelor\'s program in Computer Science, Information Technology or a related technical field. \n- Experience of coding in one of the following programming languages including but not limited to: Ruby, C++, Java, Python, Go..... \n- Demonstrated interest and ability to learn other coding languages as needed. \n- Developed communication skills, and adequate ability to speak and write in English. \n- Effective teamwork, project management, creative problem-solving. strong communication skills.\n\nNice to have (but not required):\n\n- Technology internship experience or work experience (e.g: research assistant, teaching assistant, personal projects, etc.). \n- Interested in or love the startup-like environment, want to challenge self and aim for a leadership prospect.\n\nAdditional Information\n\nPerks:\n\n- Be a part of a young, dynamic, multinational and multi-functional team that serves global customers with new everyday challenges (Our team has staff working in US and Vietnam). \n- Join a working culture that is fast-paced, goals driven, and committed to long-term career development. \n- Monthly 1-1 performance review with your supervisor/manager to ensure you meet your goals and get the support you need to succeed in your position. \n- High work flexibility and ownership.\n\nAddress: Head Office: 156 Viet Hung, Long Bien, Hanoi\n\nApply: Submit your resume to apply. Only qualified and shortlisted candidates will be contacted.\n\nApplication Deadline: Open until filled.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1138, 225, 2, 'NAB WeCamp Training Program', 'As part of our commitment to reducing the gender gap in tech, this program is dedicated to supporting women who are passionate about exploring opportunities in the IT field.\n\nCalling all students and career switchers to join a 10-week training program (part-time) to kickstart your careers in tech.\n\nWe want to empower and provide an opportunity for candidates interested in working in the IT Industry, even without a background in IT yet. So if you want to take your first step in the industry, join us whether you are:\n- Final-year Students who want to work in IT\n- Career Switchers into IT\n- Tech-savvy and passionate about IT\n\nWe will provide you with:\n- Fundamentals of programming\n- Free soft skills and English classes\n- Hands-on training on modern software development\n\nYou can join one of the two batches:\n- Automation testing (Quality Engineer)\n- Javascript (Engineer)\n\nAfter the course:\n- If qualified, after WeCamp, you will get direct admission to join our 3-month bootcamp, Starcamp, which will come with a monthly allowance and entry job opportunities at Australia\'s largest business bank\n- Self-learning skills to get you ready for entry job opportunities as a web developer in IT Industry in Vietnam\n- Certification of Completion\n\nJoin the bootcamp and kick start your careers in the IT Industry with NAB Vietnam.\n\nThis is a free program as part of NAB\'s commitment to helping reduce the gender gap in the IT Industry. You don\'t have to pay for anything but will have to commit to joining the entire program and spend time learning and improving your skills.\n\nIt\'s more than just a career at NAB! We believe in people with people and dreams, and we want you to achieve your aspirations. More than just a career, NAB Vietnam offers you a flexibility to balance your work - life, the opportunity to grow as professionals and people and a complete set of well-being offerings. If you have an appetite to learn, grow and elevate others around you, this is the place for you.\n\nCLOUD FIRST\n\nNAB is undergoing an exciting "Cloud First" technology transformations by taking advantage of the latest tools and techniques used by leading technology and digital companies globally. But it\'s not just about the Tech, we are also investing heavily in our people, so if you have an appetite to learn, grow and elevate others around you, this is the place for you!\n\nIT\'S MORE THAN MONEY\n\nWe naturally also provide a very competitive remuneration package but a career with us is about a lot more than money. We believe in people with ideas and dreams, and we want you to achieve your aspirations. We will work together to deliver exceptional products and outcomes that push the limits of our own aspirations. Out passion for creating value and exceeding our customers\' expectations means we are constantly striving to redefine our standards of excellence. You will have our backing to develop and our encouragement to explore, realize and reach your full potential.\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1139, 674, 2, 'Software Development Intern', 'Mô tả công việc\n\n- Assist in designing, coding, testing, and debugging software projects, including: CW Website, Stock Screener, Customer Portal, Broker Portal.\n- Collaborate with senior engineers and cross-functional teams to understand project requirements and deliver high-quality solutions.\n- Participate in code reviews to ensure adherence to best practices and coding standards.\n- Write unit tests and automation scripts to support internal projects.\n- Deploy automated testing solutions to ensure the functionality and performance of software projects.\n- Maintain and update technical documentation for future reference and knowledge sharing.\n\nYêu cầu công việc\n\n- Currently pursuing a degree in Computer Science, Information Technology, Software Engineering, or a related field.\n- Basic knowledge of NodeJS, RESTful API, NestJS, Java, ReactJS, and Python.\n- Experience with version control systems (e.g., Git, Gitflow, GitLab).\n- Understanding of database management systems (SQL, NoSQL, MongoDB, Redis, MySQL).\n- Familiarity with React framework and Microservices architecture is a plus.\n- Strong problem-solving and analytical thinking abilities.\n- Good communication and teamwork skills.\n- Eagerness to learn and adapt to new technologies.\n- Basic English skill.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Full-time internship allowance: 2.000000 VND/month and parking fee support: 400.000 VND/month.\n- Support for internship certification stamping (if required).\n- Opportunity to join team-building activities, internal events, and other company recreational activities.\n- Dynamic and professional working environment.\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: Tầng 21, Phú Mỹ Hưng Tower, 08 Hoàng Văn Thái, Phường Tân Phú, Quận 7', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1140, 675, 2, 'Thực tập sinh AI Engineer (Fulltime)', 'Sapo là công ty Công nghệ. Với khả năng và hướng đi rõ ràng, Sapo nhanh chóng khẳng định được vị trí hàng đầu trong việc xây dựng nền tảng công nghệ hỗ trợ lĩnh vực bán lẻ và TMĐT. Với hơn 230.000 khách hàng trên toàn quốc tin tưởng sử dụng, Sapo đang là doanh nghiệp có nền tảng quản lý và bán hàng đa kênh từ Online đến Offline được sử dụng nhiều nhất tại Việt Nam.\n\nĐội ngũ nhân viên Sapo hiện có hơn 1000 nhân sự có trình độ chuyên môn cao, luôn làm việc với tất cả sự nhiệt huyết và sức sáng tạo của tuổi trẻ đã xây dựng nên 1 văn hoá vô cùng trẻ trung và năng động. Đến với Sapo, bạn sẽ được trải nghiệm môi trường tuyệt vời, với chế độ đãi ngộ xứng đáng và đạt được thành công vượt mong đợi!\n\nMô tả công việc\n\nTham gia nghiên cứu, phát triển và tích hợp các ứng dụng AI cho sản phẩm của Sapo (Chatbot AI, hệ thống gợi ý, Conversation Insights...).\n\nHỗ trợ xử lý và phân tích dữ liệu (data preprocessing, data labeling, cleaning,…) phục vụ cho các mô hình học máy/học sâu.\n\nTham gia thiết kế, xây dựng, huấn luyện và đánh giá các mô hình AI (NLP, Computer Vision, Recommendation System,…) trên nền tảng công nghệ mới.\n\nTìm hiểu, tối ưu hiệu năng mô hình và đề xuất giải pháp cải tiến chất lượng.\n\nTham gia cùng đội ngũ nghiên cứu để cập nhật xu hướng công nghệ AI mới và đưa ra ý tưởng phát triển tính năng cho sản phẩm.\n\nPhối hợp với các bộ phận khác (Phát triển sản phẩm, Thiết kế,…) để triển khai và tích hợp AI vào quy trình, sản phẩm thực tế.\n\nYêu cầu công việc\n\nĐang theo học hoặc đã tốt nghiệp các chuyên ngành liên quan đến Khoa học Máy tính, Toán Tin, Hệ thống Thông tin, Trí tuệ Nhân tạo hoặc các ngành liên quan.\n\nNắm vững kiến thức nền tảng về Machine Learning, Deep Learning, thuật toán và cấu trúc dữ liệu.\n\nCó kỹ năng lập trình với ít nhất một ngôn ngữ (Python, C++, Java…). Ưu tiên ứng viên thành thạo Python và các thư viện phổ biến (TensorFlow, PyTorch, scikit-learn…).\n\nCó khả năng đọc hiểu tài liệu tiếng Anh tốt, chủ động học hỏi và cập nhật kiến thức mới.\n\nKỹ năng làm việc nhóm, tư duy logic, phân tích và giải quyết vấn đề tốt.\n\nƯu tiên ứng viên đã từng thực hiện dự án AI, tham gia các cuộc thi lập trình/khoa học dữ liệu hoặc có sản phẩm cá nhân (Github, Kaggle,…)\n\nThời Gian Làm Việc\n\nThực tập full-time (40 giờ/tuần)\nThời gian thực tập kéo dài tối thiểu 3-4 tháng.\nCó thể linh hoạt thời gian để phù hợp với lịch học (đối với sinh viên năm cuối).\n\nQuyền lợi\n\nLương/thưởng hấp dẫn theo quy định của công ty\nXét tăng lương định kỳ hàng năm\nMôi trường làm việc trẻ trung, sáng tạo\nChế độ BHXH, BHYT theo luật Lao động, ngoài ra được tham gia chương trình bảo hiểm Sapo Care\nĐược tham gia các khoá đào tạo từ các chuyên gia hàng đầu về thương mại điện tử, marketing online, phần mềm ...\n\nLiên hệ\n\nĐể tìm hiểu thêm chi tiết, vui lòng liên hệ:\nSĐT: 0913 198 910 (Ms Linh)\nEmail: tuyendung@sapo.vn\nWebsite công ty: https://www.sapo.vn/\nFanpage TD: https://www.facebook.com/tuyendungsapo/\nZalo OA: Tuyển Dụng Sapo\nĐịa chỉ văn phòng: Tòa Ladeco, số 266 Đội Cấn, Ba Đình, Hà Nội\n\nỨng tuyển vị trí: Thực tập sinh AI Engineer (Fulltime)\nClick để tải lên CV của bạn\nBạn có thể tải CV mẫu tại đây', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1141, 676, 2, 'Java Developer (Fresher)', 'Overview:\nAre you female students eager to dive into the tech world?\nOur Java DECP Program (DXC Early Career Professional) is designed for talented, passionate female graduates who are looking to join an agile world leader and are ready to use the power of technology to deliver mission-critical IT services that move the world. Our customers entrust us to deliver what matters most.\nWe believe every graduate is unique and our aim is to help you build a solid foundation in your professional career, apply your learnings, and discover new possibilities.\n\nRequirements:\n- Fresh graduates in Computer Science, Information Technology, Software Engineering or related technical field.\n- Good knowledge in Object-oriented programming concept.\n- Good English communication skills.\n- Has knowledge or relevant work experience in any of the following programming languages or technologies: Java/Java EE, Spring Boot, SQL, System, window server, …\n- Ability to learn in a short time and work under pressure.\n- Experience working in an international software development project will be advantageous.\n- Good analytical and communication skills.\n- Be able to work independently and in a workgroup.\n\nBenefits:\n- Competitive salary.\n- 1-on-1 mentorship throughout the Fresher program.\n- Comprehensive training with a professional curriculum.\n- Hands-on experience working on real projects.\n- High potential to become a full-time employee upon completion of the training program.\n- Dynamic and youthful work environment with plenty of growth opportunities.\n- Free DXC Learning Account (partner with Udemy and LinkedIn).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1142, 677, 2, 'STEM Internship (Sciences / Technology / Engineering / IT)', 'CRCC Asia’s STEM Internship Program connects ambitious students and graduates with hands-on experience in science, technology, and engineering across seven of Asia’s most innovative cities. You’ve worked in labs, debugged code, and solved equations. Now, take your STEM skills global this summer.\n\nJoin CRCC Asia, the world’s leading provider of international internships in Asia, on an award-winning internship program recognized by Bloomberg, CNBC, and The Wall Street Journal. With over 16 years of experience and 11,000+ alumni, we connect ambitious individuals with global career opportunities in Asia’s most progressive cities.\n\nWhy This Internship?\n\n- Conduct research or lab-based work in biomedical, health, or environmental sciences.\n- Develop apps, software, or data models with cutting-edge tech teams.\n- Work on engineering projects involving design, prototyping, or systems testing.\n- Support IT operations, cybersecurity, or UX/UI design in fast-paced environments.\n\nWhat You\'ll Gain\n\n- Guaranteed STEM internship in Asia\n- High-quality, fully furnished accommodation\n- Airport Pickup and 24/7 Emergency Support\n- Cultural integration: SIM & travel card, welcome orientation, and city tour\n- Orientation Weekend, including city tour\n- Business, Cultural, and Community outreach events\n- Exclusive Alumni Network and LinkedIn Groups\n- Discounted live, interactive language classes\n\nWho Should Apply\n\n- Undergraduate or graduate students in STEM or related fields\n- Motivated, globally minded individuals\n- Reasonable English-speaking fluency\n\nSummer 2025 Exclusive - Apply & Save! \nDeadline: May 31st - Apply now for internships from May to September and get up to $500 worth of discounts, flight vouchers, and more if you apply as a group!\n\nFees\nOur full internship program includes guaranteed placement, housing, career support, cultural events, and more. Prices start at $4,300, covering everything you need for a seamless and enriching international experience.\n\nSalary\nWhile internships aren\'t paid due to visa and legal restrictions, the value lies in the experience. You\'ll gain hands-on, career-boosting exposure with leading companies from agile startups to global firms. Some host companies may offer perks like stipends, meals, or transport support depending on their internal policies, but these are bonuses, not guarantees. Our priority is placing you where you\'ll learn, grow, and make an impact.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh e Região', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1143, 678, 2, 'CodeByte\'s Summer Accelerator 2025 (Global Internship Program)', 'TheCodeByte Summer Accelerator 2025 (Only LinkedIn Applications will be considered for Review)\n\nGlobal Elite Internship Cohort — Only 100 Spots Worldwide\n\nOrganization: TheCodeByte.in\nPosition: Summer Accelerator Fellow (Global Internship)\nLocation: 100% Remote\nDuration: Summer or Autumn 2025 Cohort (Flexible, Self-Paced)\nCohort Size: Strictly Limited to 100 Exceptional Students\n\nAn Unmatched Opportunity for the World’s Top Emerging Talent\nTheCodeByte Summer Accelerator 2025 is a one-of-a-kind, invitation-only internship experience for the top 100 most ambitious students and graduates worldwide.\n\nThis highly selective program is designed to accelerate your professional journey—offering unparalleled access to industry mentors, project-based learning, and an exclusive global network.\n\nWho Should Apply?\n- Undergrad in Science, Arts, university undergraduates, or recent graduates from any country.\n- A demonstrated passion for technology, product, business, or startups.\n- Vision, ambition, and the drive to stand out—no prior experience required.\n- Proficient in English (all program activities are conducted in English)\n\nWhat Sets This Program Apart\n- Global Prestige: Be one of just 100 selected from thousands of international applicants.\n- Real-World Impact: Work on high-impact projects, guided by expert mentors.\n- Personalized Growth: Receive tailored feedback, a certification, and a detailed performance report to power up your CV.\n- Career Acceleration: Exclusive access to career frameworks, recruiter insights, and TheCodeByte’s international professional network.\n- Scholarships: Reserved for exceptional early or high-potential applicants.\n- Onsite Meet-up & Networking: 2 days meet-up, knowledge Exchange, Bootcamp in Bangkok\n\nProgram Highlights\n- Cohort Size: Strictly limited to 100 elite students globally.\n- 100% Remote & Flexible: Learn from anywhere, at your own pace.\n- Project-Based: Contribute to challenging, real-world projects and present your work to industry leaders.\n- Mentorship: Get matched with a dedicated, senior professional mentor.\n\nHow to Apply\n1. Submit Your Application: www.thecodebyte.in/accelerator\n2. Connect with Us: Follow TheCodeByte on LinkedIn and Instagram for cohort updates.\n3. Selection Process: Only the most driven and promising applicants will be invited to join this elite cohort. Shortlisted candidates will be contacted directly by email.\n\nDue to the program’s exclusivity, applications are reviewed on a rolling basis and will close as soon as the 100 seats are filled. Early application is strongly recommended.\n\nAdditional Information\n- TheCodeByte is committed to global diversity and inclusion. Students from all backgrounds and locations are welcome to apply.\n- Cohort members will receive a premium resource pack valued at ₹20,000 (approx. £250) to jumpstart their careers.\n\nAre you ready to join the world’s most exclusive summer accelerator and become part of the next generation of tech leaders? Apply now at: Only LinkedIn Applications will be considered for Review\nContact: accelerator@thecodebyte.in', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1144, 679, 2, 'HCM – Junior Front-end Developer (ReactJS) – Hybrid Working', 'Junior Front-end Developer (ReactJS)\n\nHybrid Working\n\n"For millions of Vietnamese people never have to queue to buy ticket…again" – Van Tran – CEO\n\nVexere is a technology company aiming to revolutionize the travel and transportation industry in Vietnam. We are pioneering in comprehensive digital transformation of the transport industry with diverse web applications and latest technology apps. We are available on all super apps such as Grab, Momo, Zalopay… We have all types of tickets from low-priced to luxury cars. Today Vexere is the largest online inter-city bus ticketing platform that empowers millions of travelers to make their life journeys happier.\n\nJoin us to be part of a warrior team to conquer any difficulty, to strive for the best user experience. You will be part of the team to build all components in Vexere design language system and put to storybook where other teams can come and use your components at easy. Part of frontend team, you will build fast and sleek websites in ReactJS, applying the most modern philosophy such as Progressive Web App, Universal Web App to provide web content to user at blazing speed while still stick to SEO best practices. Constantly use Lighthouse and many other tools to monitor web performance and bundle sizes to optimize to the best.\n\nWe are proud to provide to you many challenging works while solving society problems, to make your life and your family’s life much better.\n\nFullstack developer is a plus.\n\nWorking location: Floor 2 Circo Hoang Dieu – 384 Hoang Dieu, Ward 6, District 4, HCMC\n\nBenefits:\nAttractive compensation package\nWe can offer over this rank depending on your interview performance\nQuarterly bonus\n100% salary on your probation period\n13th salary\nPerformance review 2 times/year\n1 day working remotely/week\nOpportunities to be lead by top CTOs, architects and leaders at Vexere\nCompany will plan and help you to build publish profile by publishing posts in medium.com and Vexere techblog under your name, being contributor in opensource projects managed by our company, tech talks\nAttractive stock option for hard-core developer/lead\n30% discount for Vexere members and 10% for their family/relatives when buying bus tickets to travel within Vietnam\nCompany trips, Teambuilding, Year-end party, and other festivities\nResponsibilities:\nBeing a part of a Product team, your work will be solving business requirements by designing solutions and shipping codes with quality.\nBeing a member of the Frontend Squad, you will be proactively analyzing things like technical debts and challenges to be improved and making changes. Learn and share within Frontend Squad to maximize knowledge of your team as well as yours.\nLead frontend team or a product if capable.\nRequirements:\nAt least one year of real work experience with React JS for Junior level and 3 years for Senior level, must understand basic philosophy of ReactJS and React component lifecycle\nSolid understanding of how to convert design into web template, ability to effectively structure html tags and CSS to deliver minimal and optimal content to user(HTML5/CSS3)\nFamiliar with ES6 and later\nApply proven technologies and best practices to level up your technical skills: Redux, Observables, ImmutableJS, Reselect, FlowType, Jest, Docker…\nBeing serious about code quality, experience in doing code review, familiar with unit testing\nGrow mindset: as our company grows 3 to 5 times a year, as a member you have no choice but to grow at least 3 times a year\nPlus:\nSolid understanding of webpack such as code splitting, handling assets…\nExperience with different frontend frameworks such as bootstrap, foundation, scss, jQuery, Angular, handlebars template, VueJS…\nGood understanding about SEO best practices, analytic tools such as google analytics\nGood understanding of data structures, algorithms and design patterns\nFamiliar with deployment, scaling, monitoring and performance tuning\nFamiliar with micro-service web architecture\nFamiliar with Agile Process and Scrum Methodologies\nTest automation\nPreferred\nHaving public profiles at GitHub/IT blogs\nHaving user-centric mind\nBe able to analyze our website and show us what can be improved\nAttention to detail\nFor More Information, Please Contact Us Via\nSend your CV to Email: careers@vexere.com\nZalo: 0989 036 781 – Mr. Hoa Dang Khoa', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1145, 680, 2, 'Intern, Data Engineer', 'Company Description\n\nAbout Grab and Our Workplace\n\nGrab is Southeast Asia\'s leading superapp. From getting your favourite meals delivered to helping you manage your finances and getting around town hassle-free, we\'ve got your back with everything. In Grab, purpose gives us joy and habits build excellence, while harnessing the power of Technology and AI to deliver the mission of driving Southeast Asia forward by economically empowering everyone, with heart, hunger, honour, and humility.\n\nJob Description\n\nGet to Know the Team \n\nData Engineers in Grab get to work on one of the largest and fastest growing data lakes of any company in South East Asia. We operate in a challenging, fast paced and ever changing environment that will push you to grow and learn.\n\nOur mission? Provide self-service data ingestion platforms with intuitive interface for all users at Grab and affiliates to ingest any data with business value at configurable freshness SLOs, cost effectively and reliably to data lake with intelligent automations to minimize the ongoing maintenance effort throughout the lifecycle of the pipeline.\n\nGet to Know the Role\n\nYou will support the mission of the team by maintaining and extending the platform capabilities through implementation of new features to support new ingestion use cases, automations to reduce the effort and incorporating new technologies to drive efficiency. You will go the extra mile to support platform users to get their job done reliably with minimum effort.\n\nYou will work onsite in HCMC and report to the Engineering Manager, who is based in Singapore.\n\nThe Critical Tasks You Will Perform\n\n- Maintain and extend the python backend APIs and automations used by the ingestion platform.\n- Maintain and extend the scala spark applications we use for data ingestion.\n- Design and Implement improvements to the existing architecture to support new use cases or improve efficiency.\n- Follow testing & SRE best practices to ensure the stability of the system.\n\nQualifications\n\nWhat Essential Skills You Will Need\n\n- Able to commit to a full-time internship (40 hours per week) in 6 months and work onsite at Grab HCMC office.\n- Undergraduate in Software Engineering, Computer Science. We are also happy to hire students from other quantitative fields who are passionate about programming & have built some cool software applications in the past.\n- Proficiency in Python or Scala.\n- Familiarity with data pipelines and related technology such as Airflow, Spark, S3, Relational DBs, Kafka, Flink and SQL.\n- Experience implementing backend APIs.\n- Familiarity with AWS & Terraform.\n\nAdditional Information\n\nLife at Grab\n\nWe care about your well-being at Grab, here are some of the global benefits we offer:\n\n- We have your back with Term Life Insurance and comprehensive Medical Insurance.\n- With GrabFlex, create a benefits package that suits your needs and aspirations.\n- Celebrate moments that matter in life with loved ones through Parental and Birthday leave, and give back to your communities through Love-all-Serve-all (LASA) volunteering leave\n- We have a confidential Grabber Assistance Programme to guide and uplift you and your loved ones through life\'s challenges.\n- Balancing personal commitments and life\'s demands are made easier with our FlexWork arrangements such as differentiated hours.\n\nWhat We Stand For At Grab\n\nWe are committed to building an inclusive and equitable workplace that enables diverse Grabbers to grow and perform at their best. As an equal opportunity employer, we consider all candidates fairly and equally regardless of nationality, ethnicity, religion, age, gender identity, sexual orientation, family commitments, physical and mental impairments or disabilities, and other attributes that make them unique.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1146, 681, 2, 'Intern / Fresher', 'Chúng tôi tìm kiếm những bạn trẻ có ước mơ cùng công nghệ tạo ra những thay đổi tích cực cho xã hội. Tuổi trẻ ắt hẳn luôn đi liền với nhiều hoài bão và những mơ hồ về con đường phía trước. Đồng hành cùng Sun*, chúng ta sẽ cùng nhau chinh phục những giới hạn mới, tìm ra con người mà bạn muốn trở thành trong tương lai để tạo ra những dấu ấn của riêng mình.\n\nHà Nội, Đà Nẵng\n\nIntern Web Back-end\n\nWHO WE ARE Với tầm nhìn dài hạn là xây dựng thế hệ kỹ sư mới xuất sắc về cả chuyên môn và kỹ năng mềm, Sun* Inc. tuyển dụng những bạn sinh viên năm cuối hoặc mới ra trường...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Nam Từ Liêm, Hanoi, Vietnam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1147, 264, 2, 'AI/GenAI Internship', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nWhat You’ll Bring\n\n• Study in Computer Science, Software Engineering or a related field.\n• Knowledge of basic algorithms, object-oriented, database design\n• Knowledge of machine learning, computer vision, backend development\n• Experience with Azure, AWS, GCP is plus.\n• Good at English in both writing and speaking skills is plus.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1148, 682, 2, 'MB Trainee - BackEnd Engineer (Sinh viên, Fresher) - Khối Công nghệ thông tin (HOLT.09)', 'Job Description\n- Participate in programming and developing banking systems and applications.\n- Contribute to developing integration services with core systems such as T24, WAY4, BPM, CRM, CIC, etc.\n- Assist in developing APIs on the API Gateway to support integration with domestic and international partners.\n- Research, test, and implement new technology trends in development, including GraphQL, Docker Containers (Kubernetes), CI/CD, Event Sourcing, CQRS, and NoSQL.\n- Participate in training programs to enhance professional skills, aiming for advancement to official positions after the trainee program.\n\nJob Requirement\n- Final-year university students or graduates within the past year.\n- Graduated in one of the following majors: Information Technology, Computer Science, Telecommunications, Software Engineering, Information Systems, etc.\n- Knowledge and understanding of at least one BackEnd programming language, with a preference for Java.\n- Skills in working with the Spring framework: Spring Core, Spring Security, Spring Boot.\n- Familiarity with at least one type of database: Oracle, SQL Server, PostgreSQL, MongoDB.\n- Preference given to candidates with: Excellent or Outstanding academic performance, high GPA, awards in professional competitions or provincial/national academic contests, scientific research experience during high school or university (Applicants should clearly state GPA and awards in their CV)\n- Full-time availability is an advantage.\n- Onsite work required for at least 7 out of 10 sessions per week (Monday to Friday).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1149, 683, 2, '[HCM, Regional Craftland] Cộng tác viên Game Developer', 'Job Description\n\n- Phối hợp lên ý tưởng, thiết kế và phát triển trò chơi trên nền tảng của Công ty\n- Phát triển, kiểm thử và đảm bảo vận hành các trò chơi với tiêu chuẩn chất lượng cao\n- Tối ưu hóa hiệu suất trò chơi và tạo các bản cập nhật, vá lỗi thường xuyên\n\nJob Requirements\n\nYêu cầu công việc\n\n- Trình độ từ Cử Nhân Đại Học hoặc Kỹ Sư Đại Học trở lên chuyên ngành liên quan đến Công nghệ thông tin\n- Có thể làm việc trên văn phòng tối thiểu 3.5 ngày/ tuần trong 6 tháng - 1 năm; Ưu tiên sinh viên năm 3, năm 4.\n- Nắm chắc về các khái niệm trong phát triển trò chơi như cơ chế, thiết kế giao diện và cân bằng trò chơi.\n- Nắm chắc kiến thức về lập trình hướng đối tượng.\n- Có kinh nghiệm sử dụng các công cụ quản lý phiên bản như Git hoặc SVN.\n- Có đam mê với game, chơi nhiều game đa dạng thể loại, ưu tiên thể loại bắn súng, game Free Fire\n- Có khả năng làm việc độc lập cũng như làm việc nhóm tốt\n\nĐiểm Cộng\n\n- Có kinh nghiệm với các ngôn ngữ: Lua, Python, Javascript, v.v.\n- Có kinh nghiệm phát triển trò chơi với các nền tảng UGC: Roblox, Mini World, Blockman GO, v.v.\n- Có kinh nghiệm phát triển trò chơi với các công cụ phát triển trò chơi: Unity, Cocos2dx, Unreal Engine, v.v.\n- Có kinh nghiệm lập trình trò chơi đa người chơi (multiplayer game)\n- Có kinh nghiệm triển khai kiến trúc client / server.\n\nHướng Dẫn Chuẩn Bị Hồ Sơ - Vui Lòng Chuẩn Bị Hồ Sơ Của Bạn Theo Danh Sách Sau\n\n- CV của bạn\n- File gaming resume (Bạn tải file về theo đường link, điền các thông tin cần thiết và gửi cùng CV khi bạn ứng tuyển vào vị trí): https://shorturl.at/6zbLP', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1150, 684, 2, 'THỰC TẬP SINH PYTHON CHO NGÀNH XÂY DỰNG', 'Bạn là sinh viên kỹ thuật xây dựng yêu thích công nghệ và lập trình? Bạn muốn tham gia vào các dự án thực tế, ứng dụng lập trình để tối ưu hoá công việc kỹ thuật? Đây là cơ hội dành cho bạn!\n\n🔍 Vị trí tuyển dụng: Thực tập sinh Lập trình Python ứng dụng trong Xây dựng\n🌐 Hình thức: Remote 100% – Full-time\n🕒 Thời gian: 8–12 tuần (tháng 7–9/2025)\n🎯 Mục tiêu chương trình:\n- Hướng dẫn sử dụng Python để tự động hóa tính toán trong thiết kế kết cấu & nền móng.\n- Tham gia phát triển các sản phẩm thực tế trên nền tảng Cemapp (app.cemcons.vn) – công cụ được hàng chục ngàn kỹ sư tin dùng.\n\n👤 Yêu cầu:\n- Sinh viên từ năm 2 hoặc kỹ sư mới tốt nghiệp các ngành xây dựng dân dụng, kỹ thuật xây dựng,...\n- GPA từ 7.5/10 hoặc 3.2/4\n- Có kiến thức lập trình Python hoặc VBA là lợi thế.\n- Tinh thần học hỏi cao, trung thực, chủ động, có khả năng làm việc nhóm từ xa.\n\n🎁 Quyền lợi:\n- Phụ cấp 3 triệu VNĐ/tháng (tùy năng lực)\n- Được mentor hướng dẫn trong suốt quá trình\n- Nhận giấy chứng nhận thực tập có dấu công ty\n\n📩 Cách thức ứng tuyển:\nGửi CV + Thư xin việc về: info@cemcons.vn\n⏳ Deadline: 20/06/2025\n📱 Liên hệ: Zalo 0961 421 723\n\n🌱 Đây là cơ hội để bạn không chỉ nâng cao kỹ năng lập trình mà còn hiểu rõ cách áp dụng công nghệ vào lĩnh vực xây dựng hiện đại. Cemcons mong đợi đồng hành cùng bạn!\n\n#Python #Xaydung #Thuctapsinh #Cemcons #CivilEngineering #Automation #Internship2025 #RemoteInternship', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1151, 685, 2, 'Software Developer (Vietnam)', 'Responsibilities: Full stack systems development. Technical investigation/research, risk assessment, estimation, and recommendation. Development of prototypes and proof-of-concept applications for technical proposals and demos. Program documentation. Product maintenance, support, and enhancement. Troubleshoot and debug existing systems. System migration and upgrade.\n\nQualifications:\nBachelors degree in Computer Sciences, Computer Engineering, or any course related to Information Technology, Engineering, and Mathematics. Excellent programming and problem-solving skills. Ability to develop software in Java or other enterprise programming languages. Ability to contribute to different phases of the software development life cycle (SDLC) or product development. Ability to communicate in English, verbal and written, in a concise and clear manner. Fast learner, detail-oriented. Able to work under pressure. Self-managing and able to collaborate with offsite team members. Can render extra hours whenever necessary. (Fresh graduates are encouraged to apply).\n\nWhat\'s in it for you:\nCompetitive salary package. Exposure to a variety of technologies and roles. Abundant opportunities to upskill and grow on the job. Being part of a global team of competent IT professionals. Being part of the companys continuous growth and R&D on new technologies. An environment focused on quality and streamlined processes: CMMI Level 5. Family-like work environment. Semi-flexible work schedule.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1152, 686, 2, 'Intern, Data Engineer', 'The role at a glance\n\nGet to Know the Team \n\nData Engineers in Grab get to work on one of the largest and fastest growing data lakes of any company in South East Asia. We operate in a challenging, fast paced and ever changing environment that will push you to grow and learn.\n\nOur mission? Provide self-service data ingestion platforms with intuitive interface for all users at Grab and affiliates to ingest any data with business value at configurable freshness SLOs, cost effectively and reliably to data lake with intelligent automations to minimize the ongoing maintenance effort throughout the lifecycle of the pipeline.\n\nGet to Know the Role\n\nYou will support the mission of the team by maintaining and extending the platform capabilities through implementation of new features to support new ingestion use cases, automations to reduce the effort and incorporating new technologies to drive efficiency. You will go the extra mile to support platform users to get their job done reliably with minimum effort.\n\nYou will work onsite in HCMC and report to the Engineering Manager, who is based in Singapore.\n\nThe Critical Tasks You Will Perform\n\n- Maintain and extend the python backend APIs and automations used by the ingestion platform.\n- Maintain and extend the scala spark applications we use for data ingestion.\n- Design and Implement improvements to the existing architecture to support new use cases or improve efficiency.\n- Follow testing & SRE best practices to ensure the stability of the system.\n\nSkills you need\n\nWhat Essential Skills You Will Need\n\n- Able to commit to a full-time internship (40 hours per week) in 6 months and work onsite at Grab HCMC office.\n- Undergraduate in Software Engineering, Computer Science. We are also happy to hire students from other quantitative fields who are passionate about programming & and have built some cool software applications in the past.\n- Proficiency in Python or Scala.\n- Familiarity with data pipelines and related technology such as Airflow, Spark, S3, Relational DBs, Kafka, Flink and SQL.\n- Experience implementing backend APIs.\n- Familiarity with AWS & Terraform.\n\nWhat we offer\n\nAbout Grab And Our Workplace\n\nGrab is Southeast Asia\'s leading superapp. From getting your favourite meals delivered to helping you manage your finances and getting around town hassle-free, we\'ve got your back with everything. In Grab, purpose gives us joy and habits build excellence, while harnessing the power of Technology and AI to deliver the mission of driving Southeast Asia forward by economically empowering everyone, with heart, hunger, honour, and humility.\n\nLife at Grab\n\nWe care about your well-being at Grab, here are some of the global benefits we offer:\n\n- We have your back with Term Life Insurance and comprehensive Medical Insurance.\n- With GrabFlex, create a benefits package that suits your needs and aspirations.\n- Celebrate moments that matter in life with loved ones through Parental and Birthday leave, and give back to your communities through Love-all-Serve-all (LASA) volunteering leave\n- We have a confidential Grabber Assistance Programme to guide and uplift you and your loved ones through life\'s challenges.\n- Balancing personal commitments and life\'s demands are made easier with our FlexWork arrangements such as differentiated hours\n\nWhat We Stand For At Grab\n\nWe are committed to building an inclusive and equitable workplace that enables diverse Grabbers to grow and perform at their best. As an equal opportunity employer, we consider all candidates fairly and equally regardless of nationality, ethnicity, religion, age, gender identity, sexual orientation, family commitments, physical and mental impairments or disabilities, and other attributes that make them unique.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1153, 536, 2, 'Student Web Developer', '[THỰC TẬP / PART-TIME] LẬP TRÌNH WEB (LARAVEL + VUEJS)\nĐịa điểm: Hà Đông\nThời gian: Linh hoạt (ưu tiên 20h/tuần trở lên)\nMức hỗ trợ: Thỏa thuận (có hỗ trợ thực tập)\nMô tả công việc\n- Tham gia phát triển và bảo trì các dự án web sử dụng Laravel (PHP) và VueJS\n- Làm việc với cơ sở dữ liệu PostgreSQL, thiết kế và truy vấn dữ liệu cơ bản\n- Tham gia phân tích yêu cầu và đưa ra giải pháp kỹ thuật dưới sự hướng dẫn của senior\n- Viết tài liệu kỹ thuật, mô tả logic xử lý\nYêu cầu\n- Là sinh viên năm 3 ngành CNTT hoặc các ngành liên quan\n- Có kiến thức cơ bản về JavaScript và lập trình hướng đối tượng\n- Có thể đọc hiểu tài liệu tiếng Anh kỹ thuật\n- Tư duy logic tốt, có tinh thần học hỏi, làm việc nhóm\n- Điểm cộng (không bắt buộc)\n    - Đã từng làm đồ án hoặc dự án nhỏ với Laravel/Vue\n    - Biết sử dụng Git cơ bản\n    - Biết thao tác với hệ quản trị CSDL như MySQL, PostgreSQL\nQuyền lợi\n- Được training và hỗ trợ từ các lập trình viên kinh nghiệm\n- Môi trường làm việc thân thiện, năng động\n- Có cơ hội trở thành nhân viên chính thức nếu thể hiện tốt\n- Hỗ trợ xác nhận thực tập và đóng dấu báo cáo thực tập (nếu cần)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1154, 687, 2, 'Thực tập sinh PHP', 'Mô tả công việc\n\n[HN] - Thực tập sinh Full-time/Part-time PHP định hướng Fullstack\n\nGiới thiệu chung về vị trí\n\nVNP hiện đang triển khai các Dự án ứng dụng công nghệ trong lĩnh vực giáo dục và Digital Content.\n\nĐội ngũ Developer khủng chủ chốt của công ty cho thấy sự chuyên nghiệp của mình với sự thành công của Dự án Digital Content. Tính đến thời điểm tháng 5/2014 - chỉ sau 1 năm ra mắt; dự án đã vượt mốc 100.000 lượt truy cập mỗi ngày, sở hữu 2.000.000 thành viên đăng ký, lọt vào top 100 các website phổ biến nhất tại Việt Nam, tỷ lệ tìm kiếm thuộc top 3 Google.\n\nHiện team cần chiêu mộ nhân sự nguồn, những TTS tài năng để cùng thực hiện những Dự án giáo dục nhiều tiềm năng trong tương lai.\n\nĐịa chỉ: 102 Thái Thịnh\n\nMô tả công việc\n\n- Tham gia thiết kế và xây dựng các dự án, ý tưởng khởi nghiệp về giáo dục.\n- Nghiên cứu và áp dụng công nghệ, kỹ thuật mới cho dự án: Realtime, Search Engine, Streaming, Media Process, Big Data, AI...\n\nYêu cầu\n\n- Đang là sinh viên chuyên ngành CNTT, Toán tin tại các trường như : ĐH Bách Khoa, ĐH Công nghệ, ĐH KHTN, ĐH Công nghiệp, Đại học Bưu chính Viễn thông, FPT, ...\n- Có hiểu biết về HTML, CSS, PHP, hướng đối tượng (OOP), đã tìm hiểu về 1 trong các framework Laravel, Codeigniter/CI, CakePHP,...\n- Ưu tiên các bạn đã làm Project (kèm theo link Github)\n- Chăm chỉ, chịu khó, có tinh thần chủ động học hỏi, không ngại khó ngại khổ.\n- Tư duy logic, sẵn sàng học thêm một ngôn ngữ (lập trình) mới.\n- Đam mê lập trình, chăm chỉ, hòa đồng. Sẵn sàng tìm hiểu và học hỏi cái mới, trách nhiệm với công việc.\n\nChế độ\n\n- Mức lương:\n\nLương Part-time upto 3.000.000 đồng/tháng theo năng lực\n\nLương Full-time upto 13.000.000 đồng/tháng theo năng lực\n\n- Được tham gia xây dựng các ứng dụng, website cho dự án startup.\n- Mọi góp ý về giải pháp, công nghệ đều được xem xét và áp dụng nếu khả thi.\n- Môi trường tốt để học hỏi trở thành Fullstack developer.\n- Trở thành nhân viên chính thức sau quá trình đào tạo và thử sức với các yêu cầu cao hơn.\n- Hỗ trợ cơm trưa, trợ cấp/lương theo hiệu quả công việc, xem xét theo từng tháng.\n- Tham gia các party nhỏ, vừa và lớn cùng team.\n- Đồng nghiệp Supportive, Leader xịn, Dự án nhiều tiềm năng phát triển\n- Được học hỏi kinh nghiệm từ kiến thức chuyên môn của các nhân viên trước.\n\nHồ sơ\n\nVui lòng gửi CV về email trangnk@vatgia.com\n\nTiêu đề CV gửi về ghi rõ: [PHP] - Họ tên\n\nHotline: 0912083918 (Ms.Trang)\n\nĐại học', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1155, 668, 2, 'Software Engineer Intern', 'Responsibilities\n\nAssist in developing backend services of new features, delivering to our standard on time.\nCollaborate with engineering to enhance the code quality and automated testing.\nInvestigate cutting edge technologies to improve site reliability, developer experience, customer experience, and raw performance.\nThink outside the day-to-day and propose ways to elevate the art of e-commerce engineering.\n\nRequirements\n\nMust have\n\nSolid computer science fundamentals such as theories, data structures, OOP, algorithms, design patterns, etc.\nExperience with SQL, relational databases and noSQL ones.\nKnowledge in the design or architecture of one or more projects in the school.\nGood people skills.\nBasic English communication skills, especially with reading and writing.\n\nNice to have\n\nLearning computer science or related technical discipline.\nAny trials with a testing framework (PHPUnit, Selenium, RSpec, Mockito).\nExperience of message broker tools, web services (AWS, GCP, Azure or any cloud service providers).\nAgile / Scrum software development processes.\n\nZALORA Engineering\n\nZALORA is the leading e-commerce company providing fashion throughout Southeast Asia. ZALORA Engineering has teams in Singapore and Vietnam to serve millions of users in Malaysia, Singapore, Hong Kong, Taiwan, Indonesia, Philippines. This regional diversity presents a lot of interesting challenges that you and your colleagues will face. You will learn a lot by tackling these challenges.\n\nZALORA\'s e-commerce platform is built with love by the engineering team. The Ho Chi Minh office, 12 Ton Dan, D4 (ZALORA Group) focuses completely on engineering and sets a high standard for software development in the field of e-commerce. This team creates the tech stack that powers ZALORA\'s stellar shopping experience. This ranges from the online shop and the mobile apps to ZALORA\'s complex logistics solutions.\n\nThe ZALORA Story\n\nZALORA is Asia’s leading online fashion, beauty and lifestyle destination, part of Global Fashion Group. As one of the region’s pioneer large-scale ecommerce platforms, ZALORA has established a strong presence throughout the region, particularly in Singapore, Indonesia, Malaysia, Brunei, the Philippines, Hong Kong, and in Taiwan, enjoying over 50 million visits per month.\n\nZALORA is not obligated to accept resumes from any third parties on behalf of potential candidates for any position (advertised or otherwise) by any means, unless ZALORA has executed a written agreement with such third party and has expressly requested such third party for candidate referrals. Third parties who provide unsolicited resumes of candidate(s) shall waive and forfeit all rights to claim for any placement fees or referral fees in the event that such candidate is eventually engaged or employed by ZALORA or Global Fashion Group.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 ホーチミン', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1156, 450, 2, 'Software Engineer Intern - QA', 'Our Journey\n\nShopBack began in 2014 as a late-night spark of inspiration between Henry and Joel — not just to build a Cashback platform, but to reimagine how brands and consumers connect. As former advertisers, they understood the limitations of traditional marketing, and saw an opportunity to deliver more value on both sides. That idea quickly turned into action, with the first prototype built during a 24-hour sprint. Today, ShopBack serves over 50 million users across 13 markets, partners with 20,000+ merchants, and powers over half a million transactions daily. We\'re building The World’s Most Rewarding Way to Shop — and looking for bold, driven individuals to join us.\n\nYour Adventure Ahead\n\n- Improve coverage of new and existing platforms, inclusive of native mobile and responsive web apps\n- Improve and maintain test automation across our entire tech stack\n- Write, maintain, and run tests\n- Identify bugs in new and existing code, determine root causes, and suggest possible bug fixes\n- Collaborate with QA engineers across our 3 technology hubs to improve service quality and delivery velocity\n\nEssentials To Succeed\n\n- Computer Science or related major  \n- Constantly curious, always looking to learn new technologies\n- Strong analytical, problem-solving, communication and decision-making skills\n\nShopBackers\' DNA  \n\nGrit - We tackle all challenges head-on, working together to solve problems and achieve success.\nHunger - We value hard work, and having relentless drive.\nSpeed - We move fast and have a bias for action, all to deliver maximum impact.\nImpact - We focus on results, always aiming for the best possible outcomes and timelines.\nGrowth - We embrace a growth mindset, constantly striving to learn, improve, and excel in our roles.\n\nExclusively for ShopBackers  \n\n- Career progression paths and opportunities to take on greater challenges that help you realise your ambitions.\n- Be part of a winning team on a journey to global scale.\n- Competitive compensation based on your performance.\n- Candid, open, and collaborative culture where feedback is valued, for everyone to grow and improve every day.\n\nShopBack is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. We do not discriminate on the basis of race, color, religion, sexual orientation, national origin, age, disability, genetic information, veteran status, or any other protected status under applicable laws. Join our team and help us make a difference!\n\nWe are committed to protecting your data and ensuring fairness in our recruitment process. As part of this process, we use AI tools to assist with tasks such as application screening and candidate matching. These tools are designed to enhance efficiency and reduce bias, and their use complies with applicable data protection laws and our commitment to fair employment practices. Your personal data will be processed securely and transparently, and final hiring decisions are always made by our recruitment team, not by automated systems. If you have any questions about how your data is used, or wish to exercise any of your rights including the right to such processing, please contact us at dpo@shopback.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Internship', '2025-10-07 20:59:18.149534'),
	(1157, 688, 2, 'Data Engineer Intern', 'Schaeffler is a dynamic global technology company and its success has been a result of its entrepreneurial spirit and long history of private ownership. Does that sound interesting to you? As a partner to all of the major automobile manufacturers, as well as key players in the aerospace and industrial sectors, we offer you many development opportunities.\n\nYour Key Responsibilities\n\n• Work with digitalization team in building end-to-end platforms and solutions for manufacturing environment, and visualization of data driven solutions.\n• Work on designing and implementing simple ETL processes using Python.\n• Gain exposure to Microsoft Azure tools like Azure Functions and Azure Data Factory to automate data workflows.\n• Assist in shaping data models to support AI usecase.\n\nYour Qualifications\n\n• 3rd or 4th year in Computer science or related area\n• Understanding of Python + SQL for data tasks.\n• Strong knowledge of SQL, preferably PostgreSQL\n• Open to learning about cloud platforms, including Azure\n• General understanding of data modeling, data quality, GenAI concepts\n• Good English communication and interpersonal skills\n• Strong passion for learning and adapting to new technologies\n\nAs a global company with employees around the world, it is important to us that we treat each other with respect and value all ideas and perspectives. By appreciating our differences, we inspire creativity and drive innovation. In this way, we contribute to sustainable value creation for our stakeholders and society as a whole. Together, we advance how the world moves.\n\nExciting assignments and outstanding development opportunities await you because we impact the future with innovation. We look forward to your application.\n\nwww.schaeffler.com/careers\n\nYour Contact\nSchaeffler Vietnam Co., Ltd.\nCao Quan Hoang\nFor technical questions, please contact this email address: technical-recruiting-support-AP@schaeffler.com\n\nKeywords: Graduates; Others; Full-Time; Limited; Administration, Services & Support;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Biên Hòa, Dong Nai, Vietnam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1158, 674, 2, 'Backend Developer Intern (NodeJS, Java)', 'Mô tả công việc\n\n- Assist in designing, coding, testing, and debugging APIs and Socket services, including eKYC GW, PHS Middleware services, and Market Data gateway.\n- Work closely with senior engineers and cross-functional teams to understand project requirements and contribute to high-quality solutions.\n- Participate in code reviews to learn and ensure adherence to best practices and coding standards.\n- Assist in writing unit tests and automation script tests, and contribute to deploying automation testing in internal projects to ensure the functionality and performance of software projects.\n\nYêu cầu công việc\n\n- Bachelor’s degree (or final-year student) in Information Technology or a related field.\n- Basic knowledge of NodeJS, RESTful API, NestJS, Java, ReactJS, and Python.\n- Experience with version control systems (e.g., Git, Gitflow, GitLab).\n- Understanding of database management systems (SQL, NoSQL, MongoDB, Redis, MySQL).\n- Familiarity with Linux, Docker, ExpressJS framework, WebSockets, and Microservices technology.\n- Intermediate English language skills (written and verbal).\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Full-time internship allowance: 2.000000 VND/month and parking fee support: 400.000 VND/month.\n- Participate in company training programs (professional skills, communication skills).\n- Support for internship certification stamping (if required).\n- Opportunity to join team-building activities, internal events, and other company recreational activities.\n- Dynamic and professional working environment, with opportunities to work and learn about investment knowledge directly from industry experts in the securities sector.\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: Tầng 21, Phú Mỹ Hưng Tower, 08 Hoàng Văn Thái, Phường Tân Phú, Quận 7\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1159, 689, 2, 'Coders - AI Training [Remote]', 'Requirements\nSwift, Python, Java, Go, Verilog, Typescript, Javascript, C++, or C# coding experience required.\nThis is a great opportunity to supplement your income while looking for longer or more full-time work, all while contributing to the development of new AI models using your domain expertise!\nOur client has hired over 1,000 Braintrust talent and intends to hire hundreds more!\nMany Braintrust coders earn over $12,000 per month!\nYou’ll have the flexibility to work as much or as little as you choose - 20hrs/week is suggested, but not a limit. Start working in as little as 48 hours. Your final hourly rate will be chosen by Outlier AI and determined by your location.\nWhat to expect: If qualified, you’ll be invited to complete a brief questionnaire that takes 3-5 minutes. If you successfully pass the questionnaire, you’ll be approved and able to begin work ASAP.\nRequired qualifications:\nProficiency working one of the following languages: Swift, Python, Java, Go, Verilog, Typescript, Javascript, C++, or C#.\nComplete fluency in the English language is required. You should be able to describe code and abstract information in a clear way.\nPreferred qualifications:\nBachelor\'s and/or Master\'s degree in Computer Science or equivalent. Students are welcome.\nNote: Outlier AI is partnering with Remotasks for this opportunity.\nWhat You’ll Be Working On\nOur client has partnered with organizations to train AI large language models, helping cutting-edge generative AI models write better code.\nExample projects might include:\nEvaluating the quality of AI-generated code, including human-readable summaries of your rationale.\nSolve coding problems, writing functional and efficient code.\nOptimize code to run at maximum efficiency.\nWriting robust test cases to confirm code works efficiently and effectively.\nWriting human-readable summaries of coding problems.\nWriting explanations of how code can solve problems and evaluate various solution approaches.\nNo previous experience with AI necessary! You will receive detailed instructions on what is expected of you after you complete the application and verification process.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'منطقة مدينة هو تشي منه الحضرية', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1160, 690, 2, 'Frontend Engineer - HCM', 'Company Overview:\n\nTechX is a trailblazer in cloud computing and data analytics, dedicated to empowering businesses in the banking, financial services, and enterprise sectors. Our flagship product, XData, revolutionizes data analytics by delivering advanced insights and innovative solutions that drive impactful outcomes.\n\nDescription:\n\nRole Summary\n\nThe Frontend Developer will take responsibility for developing, testing, and maintaining the user interface for the Performance Management System MVP. You will collaborate with design and backend teams to build intuitive, responsive web applications, helping to create an excellent user experience for employees, managers, and HR administrators. This role is ideal for an entry-level developer eager to contribute directly to a key project in a dynamic environment.\n\nKey Responsibilities\n\n- UI Development:\n  - Implement responsive, visually appealing user interfaces for key features (e.g., KPI dashboard, performance review forms) using React and JavaScript.\n  - Collaborate with design teams to bring wireframes and mockups to life, ensuring consistent branding and design standards.\n- API Integration:\n  - Integrate front-end components with backend services to enable data retrieval and display, working with APIs for real-time performance tracking and KPI updates.\n  - Ensure data is presented accurately and interacts seamlessly with the backend for dynamic functionality.\n- UI/UX Optimization:\n  - Work closely with users and stakeholders to understand usability requirements and implement feedback for an improved user experience.\n  - Optimize web applications for performance and scalability, ensuring smooth interactions and quick load times.\n- Testing and Debugging:\n  - Perform unit and component testing to ensure that frontend features function correctly across different devices and browsers.\n  - Identify, troubleshoot, and resolve any UI issues or bugs, collaborating with backend and QA teams as needed.\n- Documentation and Collaboration:\n  - Document code structure, components, and key features to support smooth handoffs and future maintenance.\n  - Coordinate closely with backend developers and project managers to ensure alignment on project milestones and timelines.\n\nQualifications\n\n- Education:\n  Bachelor’s degree in Computer Science, Web Development, or related field.\n- Skills and Experience:\n  - Proficiency in HTML, CSS, and JavaScript, with a solid understanding of frontend frameworks (React preferred).\n  - Familiarity with RESTful API integration and asynchronous data handling.\n  - Basic understanding of responsive and adaptive design principles for web applications.\n- Mindset:\n  - Strong problem-solving skills with an eye for design details.\n  - Self-motivated and capable of taking initiative to address UI improvements.\n  - Eager to learn and contribute in a collaborative, fast-paced environment.\n\nPreferred (but Not Required) Skills\n\n- Knowledge of frontend testing tools and frameworks (e.g., Jest, React Testing Library).\n- Exposure to version control systems, particularly Git.\n\nWhy Join Us?\n\nAs a Junior Frontend Developer, you’ll have the opportunity to take ownership of developing user interfaces that directly impact our Performance Management System MVP. This role offers hands-on experience in building dynamic, user-friendly applications, and a chance to work alongside experienced developers and project leads who are committed to supporting your growth. With opportunities to shape the user experience, this position is perfect for someone excited to apply their skills and make an impact.\n\nApply now and join our mission to transform data into meaningful business outcomes!\n\nDue to the high volume of applicants, only shortlisted candidates will be contacted. We apologize for this inconvenience!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه District 3 فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1161, 366, 2, 'UI Frontend Engineer (HTML/CSS/UX)', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nWe are looking for UI Frontend Engineer (HTML/CSS/UX). Join Naver Vietnam as a UI Frontend Engineer to develop visually stunning, user-friendly interfaces for our products. You\'ll collaborate with cross-functional teams, contribute creative solutions, and implement design guidelines. If you\'re passionate about creating amazing user experiences, apply now\n\nYour qualification: \n\n- Ideally, 1+ years of work experience in Front-end development and 1+ years of work experience in UI/UX\n- Proficient understanding of HTML/CSS and JavaScript.\n- Planned and managed design projects to ensure timely delivery and adherence to deadlines.\n- Create wireframes, storyboards, user flows, process flows, and site maps to effectively convey design concepts and interactions.\n- Maintain and improve our design system.\n- Proficient in Responsive/Adaptive Design.\n- Experience with at least one of the JS frameworks, like AngularJS/ReactJS/ VueJS basic.\n- Excellent mastery of web standards, cross-browser compatibility, accessibility, and SEO.\n- Experience with version control systems, like Git.\n- Familiarity with software like Figma.\n\nIt\'s a big plus if you:\n\n- Ability to build new Front-end frameworks like Bootstrap, Semantic-UI, Skeleton, etc.\n- Ability to build a new Storybook or write a Storybook.\n- Ability to write snapshots and visual tests. \n- Ability to coach and mentor team members in their professional development and build a self-organizing team.\n- Can Speak Korean.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses. \n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more! \n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville et périphérie', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1162, 691, 2, 'Software Engineer (Back-End)', 'What You Will Be Doing\n\nDeveloping a clean and maintainable code using software engineering best-practices and modern platforms.\nParticipating in full product development lifecycles from ideation to live production.\nDay-to-day tech operations such as server maintenance and deployment.\n\nWhat We Need From You\n\nHave a good understanding of web application architecture\nFluency in written and spoken English is required for communication with international teams and clients.\nHave a good understanding of various software engineering design patterns\nExperience in one or more of these frameworks: Ruby on Rails and GoLang will be advantageous\nExperience in building backend system that served web applications and mobile applications will be great\nVersatility and enthusiasm to tackle new problems across the full-stack and to learn new frameworks as we continue to push technology forward', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 ホーチミン', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1163, 692, 2, '[Bình Dương] Giáo viên coding', '1. Giảng dạy:\n• Dẫn dắt tất cả các lớp học sử dụng phương pháp Logiscool.\n• Đảm bảo sự thành công của học sinh bằng cách đạt được các mục tiêu học tập.\n• Thực hiện các buổi giới thiệu và các lớp học thử khi cần.\n\n2. Quản lý học thuật:\n• Hoàn thành đào tạo Logiscool và các khóa đào tạo bổ sung theo yêu cầu.\n• Lên kế hoạch và chuẩn bị các hoạt động lớp học; quản lý các nhiệm vụ trước và sau lớp học.\n• Cập nhật và duy trì thường xuyên các tài liệu và công cụ giảng dạy.\n\n3. Tương tác với học sinh và phụ huynh:\n• Xây dựng mối quan hệ vững chắc với học sinh, hướng dẫn họ đạt được mục tiêu của mình.\n• Đảm bảo sự hài lòng của học sinh và phản hồi nhanh chóng để thông báo cho phụ huynh.\n• Báo cáo các vấn đề lên Điều phối viên Học thuật của trường khi cần thiết.\n\nThời gian làm việc: 28 giờ mỗi tuần\nCác buổi tối trong tuần: 5:30 PM đến 8:30 PM\nCuối tuần: 8:30 AM đến 9:00 PM (tùy theo lịch học)\nNghỉ một ngày trong tuần.\n\nYêu cầu:\n• Bằng cử nhân về Công Nghệ Thông Tin hoặc lĩnh vực liên quan\n• Chứng chỉ nghiệp vụ sư phạm là một lợi thế\n• Kỹ năng giao tiếp, thuyết trình và nghiên cứu tốt\n• Có ít nhất 1 năm kinh nghiệm giảng dạy về lập trình, robotics hoặc tương tự\n• Hiểu và nắm vững các ngôn ngữ lập trình như Python, C++, Unity, Scratch, Roblox\n• Quen thuộc với các phần mềm giáo dục và công nghệ quản lý lớp học\n• Năng động, vui vẻ và thân thiện\n• Luôn cập nhật những xu hướng mới nhất về lập trình dành cho trẻ em và thanh thiếu niên\n\nĐịa chỉ: 736 Đ. Cách Mạng Tháng Tám, Chánh Nghĩa, Thủ Dầu Một, Bình Dương, Việt Nam', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1164, 693, 2, 'DevOps Engineer Intern', 'About Knorex\n\nEstablished in 2010, Knorex is a cutting edge advertising technology MNC with offices across USA, Singapore, Vietnam, India and Malaysia. Knorex provides Precision Performance Marketing products and solutions to the world\'s leading brands and media agencies. With its full-stack platform, Knorex XPO™ (https://xpo.knorex.com) supplies the technology platform to deliver the right marketing message to the right audience at the right moment and right place, underpinned by a multi-layered data-driven approach. Knorex XPO shields its customers from dealing with the complexity and fuss while delivering immersive, dynamic and personalized marketing experiences that connects with their users. Knorex also provides managed services to complement its offering.\n\nWhat You Will Be Doing\n\n- Develop, own, and maintain the infrastructure provisioning process (IaC) for cloud based environment on GCP, AWS\n- Manage and improve the existing CI/CD pipeline\n- Assist engineering teams to deliver new software capabilities using microservices\n- Identify technical problems and propose solutions\n- Ensure overall system safety and availability\n\nRequirements\n\n- Automation and project oriented mindset\n- Graduated or final year at university, available for a full-time internship (Monday-Friday, 5 days/week)\n\nIt would be nice if you had\n\n- Working knowledge with Kubernetes\n- Linux administration skills, including software packaging, distribution, and configuration\n- Knowledge of security best practices\n\nBenefits\n\n- You will have the advance to influence and drive the changes, at Knorex we welcome good ideas and accept any possibility to make our company great\n- We offer great learning opportunities, you will have exposure in cutting-edge performance marketing and advertising technology\n- Opportunity to work cross-country and with a variety of projects of a different nature\n- Monthly allowance', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1165, 694, 2, 'Thực tập sinh Blockchain Developer', '1. Responsible \n- Design and developing decentralized applications in DeFi space\n- Provide hands-on support and advice to DeFi development teams within Ftech’s ecosystem\n- Stay up-to-date regarding latest trends and developments in the DeFi space\n- Collaborating with company leadership to determine blockchain technology needs and functionalities.\n- Optimizing and securing blockchain applications by integrating new tools and technologies.\n- Keeping up with current blockchain technologies and cryptography methods.\n\n2. Requirements\n- REQUIRED KNOWLEDGE, SKILLS, AND ABILITIES\n- 3rd, 4th or final year students in a quantitative field, such as computer science, engineering, statistics, or applied mathematics and informatics and other related specializations.\n- Understanding principles of blockchain technology.\n- Experienced with NodeJS, ReactJS, Devops is a plus.\n- Having an ability to understand, research documents in English.\n- Good understanding about data structures and algorithms.\n- High sense of responsibility, desire to learn new technology.\n- DESIRED ADDITIONAL SKILLS AND ABILITIES\n- Experienced with Solidity, Rust, Golang is a big plus.\n- Understanding EVM, Proof of Work, Proof of Stake.\n- Have knowledge about Security in blockchain: Hashing function, Private/Public key, Digital Signature,...\n- Having knowledge about NFT Marketplace, Staking Systems, Yield Farming, Vesting Systems, Launchpad,... is a huge plus.\n\n3. Benefits\n- Allowance: 1-3 million dong/month + Bonus\n- Clear promotion roadmap, opportunity to access new technologies, knowledge and to work with experienced experts in AI\n- Be trained professionally by experienced mentors about expertise, soft skills before entering a specific job\n- Young and enthusiastic working environment, annual teambuilding and travelling\n- Diverse internal events:\n- Monthly employees’ birthday party: Happy Friday\n- Activities to celebrate the company\'s establishment day and holidays: International Women\'s Day 8/3, Vietnamese Women\'s Day 20/10, Christmas Day, New Year\'s Day, Mid-Autumn Festival, Children\'s New Year 1⁄6,...\n- Annual football tournaments, game tournaments and volunteer activities\n- Free Parking, pantry, microwave, coffee maker,...\n- Working time: 8h30 – 17h30 (off 1 hour for lunch) from Monday to Friday, Saturday and Sunday off\n\nĐịa chỉ làm việc:\nTrụ sở Hà Nội: 21 Ngõ Giếng, Phố Đông Các, Phường Ô Chợ Dừa, Quận Đống Đa, Thành phố Hà Nội\n\n____________________________________________________________________________________________\n\nFTECH CO., LTD là công ty công nghệ product đầu tư nghiên cứu chuyên sâu về lĩnh vực AI. Thành lập vào năm 2019, hiện công ty đã có mặt ở 3 thành phố Hà Nội, Hồ Chí Minh và Đà Nẵng với quy mô hiện tại ~400 nhân sự, là nơi quy tụ đội ngũ kỹ sư, chuyên gia hàng đầu nghiên cứu và xây dựng các giải pháp công nghệ phục vụ hệ sinh thái gia đình.\n\nBên cạnh đó, công ty là đối tác cao cấp của hơn 50 khách hàng trên các lĩnh vực kinh doanh đa dạng với hơn 20 dự án đang phát triển, nổi bật:\n\n● Nền tảng livestream trực tuyến - FBANG\n● Giải pháp thanh toán - FID - F365x\n● Ứng dụng phần mềm - SPAGO - FCAKE - FSCHOOL\n● Virtual Idol ảo - TIMI IDOL\n● Trò chơi điện tử - GAME CITY - LOẠN CHIẾN MOBILE\n\nVới mong muốn kiến tạo và lan tỏa hệ sinh thái công nghệ cho gia đình Việt, FTECH đang hướng tới trở thành doanh nghiệp công nghệ, ứng dụng trí thông minh nhân tạo hàng đầu Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội e Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1166, 676, 2, 'ServiceNow Fresher (proficient in Javascript)', 'ServiceNow is an immersive, cloud-based software platform that enables the automation of IT processes. ServiceNow helps companies manage digital workflows for business operations and is used by many of the world\'s largest organizations.\n\nDXC Vietnam is recruiting talented young individuals to join the ServiceNow team. If you\'re looking for an opportunity to intern, grow personally, and gain valuable experience, don\'t miss out on this chance!\n\nRequirements:\n- Graduated from universities or colleges with relevant majors such as Information Technology, Computer Science, etc.\n- Knowledge of JavaScript.\n- Can communicate in English, prefer having an English Certificate.\n- Having a Japanese language is a plus.\n- Commit to working at least 30 months after completing the Program.\n- Commit to joining all training courses for the Program.\n- Available to work full-time.\n\nBenefits:\n- Allowance: 5,000,000 VND/month.\n- 1-on-1 mentorship throughout the Fresher program.\n- Comprehensive training with a professional curriculum.\n- Hands-on experience working on real projects.\n- High potential to become a full-time employee upon completion of the training program.\n- Dynamic and youthful work environment with plenty of growth opportunities.\n- Free DXC Learning Account (partner with Udemy and LinkedIn).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1167, 695, 2, 'Intern Backend Dev (Japanese at least N3)', 'IVC Fresher Training Program ( IFTP) 2025 in 3 month\n\nSelection- Training Schedule & Location\n- 15 May - 09 Jun 2024: Profile Screening - interview & Open discussion\n- 10 - 25 Jun 2025 IFTP result\n- 1 Jul 2025 : Training.\n\nResponsibilities\n- 02 weeks with comprehensive training courses IVC experts ( technical and soft-skills )\n- 10 week with 100% live project :\n  - Read and understand requirement specification\n  - Analyze and create software specification\n  - Create System Design with instruction from Team Lead\n  - Do coding and unit test\n\nQualifications\n- Final year student or recent graduate majoring in Information Technology\n- Full-time internship\n- Work full time after internship\n- Experience in programing language Java/ Python/Net or Frontend and C++.\n- Deep knowledge of OOP platform and Database\n- Willing to study and develop other programming skills\n- Able to work independently and in a team\n- Possess analytical and problem-solving skills.\n- Careful, patient and willing to learn new technology\n- Logical thinking and analytical skills\n- Japanese at least N3\n\nBenefits:\n- With Competitive salary + Lunch allowance\n- Meeting and working with Technie mentor\n- Participate in full Software Development Life Cycle\n- Fulltime employment after program finished\n- Japanese culture and working atmosphere discovery.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1168, 696, 2, 'FrontEnd Developer', 'Mô tả công việc\n\nThiết kế, tạo và duy trì mã Python sạch, có thể tổng hợp, có thể tái sử dụng, đáng tin cậy và có thể bảo trì.\n\n- Viết bài kiểm tra đơn vị và kiểm tra tích hợp để đảm bảo chất lượng và hiệu suất của các ứng dụng.\n- Tiến hành đánh giá mã với các thành viên trong nhóm.\n- Xác định lỗi, và đưa ra giải pháp để giải quyết vấn đề.\n- Tìm hiểu và chia sẻ các công nghệ, ngôn ngữ và kỹ thuật mới để làm cho nhóm hoàn thành công việc của họ\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Huyện Phú Quốc, Kien Giang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1169, 697, 2, '[HCM] Junior Java Developer (2+)| $1200 - $2000| English', '1. INTRODUCTION\n\na. About WAO Hire:\nWAO Hire company, is a collective group of tech recruiters and developers. We help fast growing companies connect with talented developers. \nWe take the humanized approach to hire and work with developers, because we know that\'s the best way to find the best developers for businesses.\n\n2. RESPONSIBILITY:\nDevelop and maintain web applications using Java and Spring frameworks (Spring Boot, Spring MVC, etc.)\nDesign and implement RESTful APIs\nWork closely with the team to design database schema and optimize SQL queries (PostgreSQL, T-SQL)\nCollaborate with other developers using Git and version control tools\nParticipate in code reviews and apply best practices in software development\nTroubleshoot and debug applications in a Linux environment\nContinuously improve system performance and scalability\nLearn and apply new technologies as needed for the project\n\n3. REQUIREMENTS \nAt least 1 year of experience in Java development\nSolid understanding of common data structures in Java\nHands-on experience with Spring Boot, Spring MVC, and related frameworks\nFamiliar with version control tools, especially Git\nExperience working with RESTful APIs and web services\nGood knowledge of SQL and database design (PostgreSQL)\nBasic experience with T-SQL scripting\nStrong passion for programming and a proactive attitude\nResponsible, collaborative, and eager to learn independently\n\nNice to Have\nUnderstanding of Object-Oriented Programming (OOP) and design patterns\nExperience with distributed system architecture\nKnowledge of caching tools like Redis and how to use them effectively\nFamiliarity with Kafka or similar message queues\nBasic Linux skills for deployment and debugging\n\n4. BENEFITS:\nBeing a member of us, you will experience a youthful, flexible, and creative work environment\nCompetitive salary ($1200 - $2200)\nAnnual salary review.\nWorking in a professional, friendly, well-equipped environment both with foreigners and Vietnamese.\nExtensive on job training, you will always have a chance to work with new emerging technologies.\n12-day annual leave per year.\n\n5. WORKING TIME: 9:00 AM - 6:00PM, Monday to Friday\n\n6. INTERVIEW PROCESS: \n1st round: Test interview\n2nd round: Culture fit + Deal salary\n\n7. LOCATION: HCMC', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1170, 698, 2, 'Intern C#', 'MÔ TẢ CÔNG VIỆC:\n- Tham gia phát triển và bảo trì các ứng dụng trên nền tảng .NET, đặc biệt là các ứng dụng WPF/WinForm.\n- Hỗ trợ team phát triển trong các dự án thực tế dưới sự hướng dẫn của các lập trình viên giàu kinh nghiệm.\n- Tham gia coding, testing và khắc phục sự cố phần mềm.\n- Học hỏi, nâng cao kỹ năng lập trình và kiến thức về các công nghệ liên quan đến phát triển phần mềm.\n\nYÊU CẦU CÔNG VIỆC:\n- Sinh viên năm cuối hoặc mới tốt nghiệp chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan (full-time)\n- Có kiến thức cơ bản về C#, .NET Framework\n- Hiểu biết cơ bản về các khái niệm lập trình như OOP, cấu trúc dữ liệu và giải thuật.\n- Ưu tiên ứng viên có kinh nghiệm làm dự án về WPF hoặc WinForm (có thể là project cá nhân, đồ án hoặc thực tập trước đó).\n- Khả năng làm việc nhóm và giao tiếp tốt.\n- Tư duy logic, có khả năng học hỏi và cầu tiến\n- Có khả năng đọc hiểu tài liệu tiếng Nhật/Anh là một lợi thế.\n\nQUYỀN LỢI:\n-Được đào tạo và hướng dẫn trực tiếp từ các lập trình viên giàu kinh nghiệm.\n-Được tham gia vào các dự án thực tế và học hỏi các kỹ năng quan trọng trong ngành.\n-Cơ hội trở thành nhân viên chính thức ngay sau khóa đào tạo\n-Được tham gia các lớp học nội bộ tại công ty.\n-Cơ hội làm việc trong môi trường năng động, trẻ trung, thân thiện và chuyên nghiệp\n-Hỗ trợ phụ cấp thực tập.\n-Được tham gia các Câu lạc bộ của Công ty: CLB bóng đá, cầu lông, PES…..\n-Được tham gia các hoạt động tập thể sôi động của công ty: Nghỉ mát hàng năm, Teambuilding hàng quý, Gala cuối năm…. \n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Internship', '2025-10-07 20:59:18.149534'),
	(1171, 699, 2, 'Thực tập/Học việc Lập trình viên .Net Core & Oracle', 'Công ty Cổ phần Chứng khoán FPT (FPTS) tuyển dụng Thực tập sinh/Học việc Lập trình viên .Net Core & Oracle làm việc tại trụ sở chính Hà Nội\n\nSố lượng: 02\nHạn nộp hồ sơ: 25/06/2025\nMô tả công việc:\nTham gia khóa đào tạo chuyên sâu về lập trình web trên nền tảng .NET core, Oracle, Redis...\nTham gia xây dựng và nâng cấp các module, tính năng theo yêu cầu\nTham gia fix bugs và hỗ trợ khách hàng;\nTham gia nghiên cứu và trình bày các công nghệ mới.\nQuá trình tuyển dụng:\nThu thập và sơ loại hồ sơ ứng viên;\nPhỏng vấn với trưởng bộ phận\nĐánh giá và tiếp nhận ứng viên.\nYêu cầu:\nSinh viên Các trường Đại học khối ngành IT phần mềm: Công nghệ thông tin, Toán tin, lập trình viên hoặc tương đương…\nCó hiểu biết và kỹ năng cơ bản về lập trình phát triển phần mềm với nền tảng .NET Core (C#, ASP.NET Core.), Oracle\nCó hiểu biết về OOP/ SOA/Microservices là một lợi thế\nCó khả năng đọc hiểu tài liệu chuyên ngành bằng tiếng anh\nYêu thích và mong muốn theo đuổi nghề lập trình; chủ động, đam mê công việc, sẵn sàng chấp nhận thách thức\nTư duy logic tốt, Có khả năng tìm hiểu nghiên cứu công nghệ mới, công cụ, ngôn ngữ mới.\nCó tinh thần trách nhiệm với công việc.\nQuyền lợi:\nỨng viên sẽ có cơ hội học tập và làm việc trong môi trường thực tế, chuyên nghiệp, năng động;\nĐược hướng dẫn, huấn luyện bởi đội ngũ chuyên gia nhiều kinh nghiệm;\nỨng viên được trang bị đầy đủ kỹ năng và kiến thức chuyên sâu để làm việc sau mỗi khóa đào tạo;\nỨng viên sẽ có cơ hội trở thành nhân viên Chính thức với quyền lợi đãi ngộ tương xứng với năng lực và kết quả hoàn thành công việc.\nNộp hồ sơ\n\nGửi bản mềm CV tới hòm mail: bannhansu@fpts.com.vn.\n\nLưu ý: CV phải đính kèm ảnh chụp cá nhân. Tiêu đề mail ghi rõ tên và vị trí dự tuyển.\n\nVí dụ: “Nguyen Thi A - Ung tuyen vi tri Thuc tap sinh Lap trinh vien”\n\nThông tin liên hệ:\n\nBan Nhân sự FPTS - Công ty Cổ phần Chứng khoán FPT\n\nĐịa chỉ: 52 Lạc Long Quân, Tây Hồ, Hà Nội\n\nEmail: Bannhansu@fpts.com.vn ĐT: 1900 6446 (Ext: 6166)\n\nFacebook: https://www.facebook.com/tuyendungchungkhoanfpt/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1172, 700, 2, 'Thực tập sinh PHP', 'Mô tả công việc\n\n- Tham gia thực tập Full-time trong thời gian 2 tháng mà không mất bất kỳ 1 khoản phí nào từ khi nộp CV tới khi hoàn thành chương trình.\n- Tham gia chương trình đào tạo miễn phí về PHP, HTML, Mobile Apps, hệ thống thương mại điện tử và Magento.\n- Đào tạo cơ bản và chuyên sâu về Front-end và Back-end.\n- Tham gia các dự án nước ngoài theo hình thức on-job training.\n- Nhận sự hỗ trợ từ các Dev giỏi trong suốt quá trình training dưới dạng hình thức bài tập thực tế.\n- Tư vấn, định hướng công việc phù hợp với chuyên môn và sở thích.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1173, 701, 2, 'Junior Webmaster Intern (With Potential for Full-Time Employment)', 'Position Overview\n\nWe are looking for a motivated Junior Webmaster Intern with a background in either design or programming to join our team. This internship offers a unique opportunity to work closely with senior team members, an external agency, and the marketing team to maintain and improve our digital presence.\n\nThe role has the potential to transition into a full-time position based on performance and business needs.\n\nPlease note: This is an unpaid internship.\n\nKey Responsibilities\n\n• Website Management:\n  • Update and manage content on WordPress websites, ensuring accuracy and timeliness.\n  • Perform minor development tasks, including form edits and updates, plugin implementation, and basic coding (rarely required).\n\n• Website Maintenance:\n  • Regularly monitor and maintain website performance, uptime, and speed.\n  • Ensure websites are secure by managing updates, plugins, backups, and security measures.\n\n• Collaboration:\n  • Work closely with the senior webmaster, external agencies, and the marketing team to align website updates with marketing campaigns and goals.\n  • Support the implementation of SEO strategies and analytics tracking as guided by the marketing team.\n\n• Troubleshooting:\n  • Identify and resolve technical issues promptly to ensure a seamless user experience.\n  • Test and debug new website features or updates.\n\nQualifications And Skills\n\n• Background in design (UI/UX, graphic design) or programming (web development, coding).\n• Familiarity with WordPress, including themes, plugins, and basic customization.\n• Basic knowledge of web technologies such as HTML, CSS, and JavaScript.\n• Understanding of website security best practices and performance optimization.\n• Strong attention to detail and ability to manage multiple tasks effectively.\n• Excellent communication skills and a proactive attitude toward learning and problem-solving.\n\nPreferred Qualifications\n\n• Experience with adjacent platforms or tools such as Elementor and CMS platforms.\n• Knowledge of SEO principles and analytics tools like Google Analytics.\n• Familiarity with graphic design tools (e.g., Adobe Creative Suite, Canva) is a plus.\n\nWhat We Offer\n\n• Hands-on experience in managing professional websites in a collaborative environment.\n• Mentorship from experienced professionals in web development and marketing.\n• Opportunity to contribute to meaningful projects and campaigns.\n• Potential for full-time employment based on performance and company needs.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1174, 702, 2, 'Binance Accelerator Program - Frontend Developer (Big Data)', 'Binance is the global blockchain company behind the world’s largest digital asset exchange by trading volume and users, serving a greater mission to accelerate cryptocurrency adoption and increase the freedom of money.\n\nAre you looking to be a part of the most influential company in the blockchain industry and contribute to the crypto-currency revolution that is changing the world?\n\nAbout Binance Accelerator Program\n\nBinance Accelerator Program is a concise fixed-term program designed for Early Career Talent to have an immersive experience in the rapidly expanding Web3 space. You will be given the opportunity to experience life at Binance and understand what goes on behind the scenes of the worlds’ leading blockchain ecosystem. Alongside your job, there will also be a focus on networking and development, which will expand your professional network and build transferable skills to propel you forward in your career. Learn about BAP Program HERE\n\nWho May Apply\n\nCurrent university students who can work 5 days per week for a period of 6 month\n\nResponsibilities\n\n- Responsible for the construction of the underlying AI platform and the process-based platform combined with customer service business scenarios.\n- Build platform open capabilities and componentization to optimize the access experience of business, R&D, and design.\n- Promote efficient business iteration and improve system performance and stability through technical research and development and improvement.\n- Explore new AI web applications through product and technology innovation.\n\nRequirements\n\n- Understand front-end technologies such as JavaScript, CSS, HTML, protocols, security, network, performance optimization.\n- Have in-depth application of at least one mainstream front-end framework (React, Vue, etc.) and understand its design principles;\n- Familiarity with low-code canvas, configuration, and development tool related technologies is preferred.\n- Familiarity with graphics rich interactive development related technologies is preferred.\n- Possess good service awareness, sense of responsibility, strong learning ability, excellent team communication and collaboration skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh-Stadt, Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1175, 703, 2, 'Quality Control Fresher / Junior', 'About Kegmil\n\nKegmil is revolutionizing the way mission-critical assets are repaired and maintained – by transforming complex systems of people and processes into streamlined, intelligent operations. Our mission is to empower millions of deskless field service professionals across Asia’s asset-centric industries with superior technology to elevate service excellence, operational insight, and profitable growth. Our cloud-based, mobile-first, and AI-powered platform automates and optimizes every aspect of field service from job scheduling and dispatch to execution and reporting.\n\nKegmil is trusted by leading organizations across mission-critical sectors – including elevator, fire protection, data center, medical equipment, and aerospace – to build the next-generation digital backbone that unifies FSM, modular ERP, and AI agents into one seamless platform for simpler, smarter, field service.\n\nWe are a curious and collaborative team that finds purpose in solving real problems for our customers. We learn and grow together in a high-trust, inclusive culture – where ideas are heard, ownership is encouraged, and customer success is everyone’s priority.\n\nJob Type: Full-time\n\nResponsibilities\n\n- Learn to Assess and Support Product Quality\n- Support the assessment of product quality across the development lifecycle.\n- Learn to identify gaps or issues in testing processes, and contribute ideas to improve them.\n- Participate in efforts to ensure consistent delivery of high-quality software.\n- Collaborate on Quality from Day One\n- Work alongside the product and development team to understand new features, suggest edge cases, and ensure quality from the planning stage.\n- Assist in writing and maintaining test plans, test cases, and test scripts.\n- Help identify which test cases could be automated in future phases.\n- Support Testing Activities\n- Contribute to the execution of manual and (eventually) automated test cases.\n- Learn to perform different types of testing like regression, smoke testing, and exploratory testing under the guidance of QA leads.\n- Assist in setting up and running automated tests (training provided).\n- Participate in Bug and Incident Handling\n- Help review and reproduce bugs reported by users or QA\n- Collaborate with teammates and stakeholders to gather information and align on next steps.\n- Learn how to document and manage bugs using internal tools (e.g. Jira).\n- Be Part of the Team\n- Actively join team activities such as daily standups, sprint planning, refinements and retrospectives.\n- Bring curiosity, questions, and a willingness to learn from others on the team.\n\nRequirements\n\n- Are a final-year student or recent graduate in Computer Science, IT, or related fields. Are curious about how software works and love breaking things (in a good way).\n- Have basic knowledge of software testing, especially in testing techniques and test methodologies.\n- Have basic knowledge of software testing tools (e.g., Playwrite, Postman, Appium, Selenium) – or are eager to learn.\n- Skill in programming in some following Javascript, Typescript are a plus.\n- Team Collaboration: Ability to work effectively within a team and contribute to a collaborative environment.\n- Critical Thinking: analyzing the issue, features and use case.\n- Have a growth mindset and enjoy solving problems.\n- Communicate clearly in both English and Vietnamese.\n\nWhat We Offer\n\n- Competitive salary and comprehensive benefits package.\n- Dynamic and innovative work environment with opportunities for personal and professional growth.\n- Access to cutting-edge tools and technologies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1176, 704, 2, 'Intern (Resilience/Chaos Engineer), VN', 'Summary of Role\n\nV-Key is one of the world’s leading deep-tech companies in mobile cybersecurity. Our patented technology V-OS has been deployed by top banks, mobile payment providers, and governments to secure software solutions and protect more than 500 million application installation globally.\n\nWe are rapidly expanding into new markets and new customer segments. Apart from securing digital transactions for everyone, we are also enabling new generation technology by providing the cybersecurity infrastructure for banking, government and smart homes, among many others.\n\nAt V-Key, we are building towards a future where technology users can enjoy unprecedented security and convenience.\n\nWe are looking for an Intern (Resilience/Chaos Engineer) as part of Engineering – Quality Assurance Department.\n\nDuties and Responsibilities\n\nResearch: Conduct a thorough investigation into existing Chaos testing tools\nAnalysis: Analyze our current infrastructure and identify areas where Chaos testing could be most beneficial. This may involve collaborating with our development and operations teams to understand our system\'s architecture and potential vulnerabilities\nProposal: Develop a detailed proposal for implementing Chaos testing within our organization. This proposal should outline the tools and techniques to be used, the scope of the testing, and the expected outcomes, ensuring alignment with our organization\'s specific needs and goals\nPilot: Assist in setting up and executing a pilot Chaos testing program in a controlled environment. This will allow us to test the solution without risking production systems and gather valuable insights for future implementation\n\nRequirements\n\n4th-year student studying in Computer Science, Software Engineering, Artificial Intelligence or a related field.\nEnglish skills are required\nKnowledge with web development\nHave programming skill at any language is a Big Plus\nComfortable using Linux and Docker, some familiarity with Kubernetes, GitHub Actions, or observability tools (Prometheus, ELK, Grafana)\nStrong interest in infrastructure, DevOps, or cloud-native development\nEager to learn and explore how systems behave under failure\nA strong self-starter and adaptation\nAbility to work in a dynamic, fast moving and growing environment\nCritical thinker and problem-solving skills\nTeam player with great interpersonal and communication skills', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1177, 705, 2, 'Java Back-End Engineer', 'We are looking for a superstar content writer that has a high affinity with technology. The content writer will produce unique high-quality content to help us get closer to our goal of becoming the #1 trusted tech advisor for the different industries we serve (HiTech, MedTech, FinTech, Retail, and the IoT).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1178, 706, 2, 'Saga Vietnam Hackathon 2025', 'Saga Vietnam Hackathon is a coding competition co-hosted by Saga Foundation and VBI Academy, designed to discover pioneering developers and startups ready to build applications on Saga’s appchain-native platform.\n\n💰 Total prize pool: 150,000,000 VND (~$6,000+)\n\nLeveraging the innovative Chainlet architecture - where each application runs on its own dedicated blockchain - this hackathon offers Vietnamese builders a breakthrough opportunity to become early adopters within the Saga ecosystem. It’s also a gateway to international mentorship, grant funding, and global investor networks.\n\n👥 Who can join?\nWhether you\'re a Web3 developer, a startup founder, a student with a bold idea, or simply someone passionate about building the next generation of decentralized applications—Saga Vietnam Hackathon is open for you.\n\nNo prior experience with Saga? No worries. You\'ll receive hands-on support from mentors and core developers throughout the journey.\n\n❝ Many developers ask: “Why choose a new ecosystem like Saga for a hackathon?”\nThe answer is simple: because this is where opportunities begin.\n\nIn a fast-growing ecosystem like Saga, you\'re not just a participant - you’re a pioneer. And when you lead the way, you get:\n- More visibility and support from the ecosystem\n- Direct guidance from the core team and international mentors who are actively seeking real collaborators\n- Greater access to grants and investors—because you\'re not lost in a crowd of thousands\n\nAll you need is:\n- A sharp idea.\n- A team bold enough to execute it.\n- And an ecosystem wide open for its first generation of builders.\n\nSaga Hackathon is the platform you’ve been looking for. Here, you\'ll:\n- Build on Saga’s cutting-edge appchain infrastructure\n- Receive direct support from core developers and global mentors\n- Get the chance to pitch to investors and access post-hackathon grants\n\nSo what will you choose?\nTo fade into the crowd—or to become a name the ecosystem remembers from Day One?\n\nDon’t miss your chance to pioneer on Saga – a rising ecosystem built for appchain innovation.\n👉 Apply now: https://bit.ly/4krJbep', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1179, 707, 2, 'ReactJS Developer (Junior/Middle)', 'Job Description\n\n- Develop UI Elements to integrate with server side logic\n- Solve technical problems\n- Support teammates to solve problems\n\nJob Requirements\n\nMUST HAVE SKILLS:\n\n- At least 2 years of experience in ReactJS, Redux. NodeJS is a plus\n- Have good knowledge or experience in front-end technologies, such as HTML5, and CSS3\n- Experience with GIT source control, Agile process\n- MUST be good at English communication\n\nBenefits\n\nCompetitive Salary and Brilliant Health Benefits\n\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan \n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program \n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support.\n- Surrounded with friendly, open-minded, young and supportive colleagues \n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1180, 708, 2, 'Frontend Software Engineer', 'At Klaara, we\'re building an AI platform so advanced, even our code has code. We\'re a fast-paced startup turning complex algorithms into elegant solutions-one line of code at a time.\nWe are looking for highly skilled Frontend Software Engineer to join our dynamic engineering team. You will be responsible for developing and implementing user interface components using modern JavaScript frameworks and libraries such as React, Vue.js, or Angular. You will work with the UI/UX designer and bridge the gap between graphical design and technical implementation, taking an active role on both sides and defining how the application looks as well as how it works. You will take part of important software implementation and be responsible for, and not limited to: \n\n- Develop new user-facing feature. \n- Build and implement top-notch user interfaces using JavaScript and Angular framework. \n- Write clean, scalable, and reusable code and libraries following industry best practices and future use as well. \n- Ensure the technical feasibility of UI/UX designs.\n- Optimize application for maximum speed and scalability.\n- Assure that all user input is validated before submitting to back-end.\n- Collaborate with other cross-functional teams and stakeholders to ensure high-performance of applications. \n\nRequirements\n- Master\'s/Bachelor’s Degree in Information Technology, Computer Science, Software Engineering , or related field.\n- Proficient understanding of Angular. Other platforms such as ReactJS and VueJS are an asset.\n- Proficient understanding of client-side scripting and JavaScript frameworks.\n- Proficient understanding of cross-browser compatibility issues and ways to work around them.\n- Proficient understanding of GIT for versioning.\n- Familiarity with database management, such as MySQL, Oracle, and MongoDB.\n- Ability to solve technical challenges and solutions with a strong customer focus.\n- Strong debugging, problem-solving, and optimization skills.\n- Startup Spirit: Self-motivated, comfortable in a dynamic, evolving environment.\n- Good command of spoken & written English.\n- A fast learner and able to work independently.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1181, 450, 2, 'Software Engineer Intern - QA', 'Our Journey\n\nShopBack began in 2014 as a late-night spark of inspiration between Henry and Joel — not just to build a Cashback platform, but to reimagine how brands and consumers connect. As former advertisers, they understood the limitations of traditional marketing, and saw an opportunity to deliver more value on both sides. That idea quickly turned into action, with the first prototype built during a 24-hour sprint. Today, ShopBack serves over 50 million users across 13 markets, partners with 20,000+ merchants, and powers over half a million transactions daily. We\'re building The World’s Most Rewarding Way to Shop — and looking for bold, driven individuals to join us.\n\nYour Adventure Ahead\n\n- Improve coverage of new and existing platforms, inclusive of native mobile and responsive web apps\n- Improve and maintain test automation across our entire tech stack\n- Write, maintain, and run tests\n- Identify bugs in new and existing code, determine root causes, and suggest possible bug fixes\n- Collaborate with QA engineers across our 3 technology hubs to improve service quality and delivery velocity\n\nEssentials To Succeed\n\n- Computer Science or related major \n- Constantly curious, always looking to learn new technologies\n- Strong analytical, problem-solving, communication and decision-making skills\n\nShopBackers\' DNA\n\nGrit -  We tackle all challenges head-on, working together to solve problems and achieve success.\n\nHunger - We value hard work, and having relentless drive.\n\nSpeed - We move fast and have a bias for action, all to deliver maximum impact.\n\nImpact - We focus on results, always aiming for the best possible outcomes and timelines.\n\nGrowth - We embrace a growth mindset, constantly striving to learn, improve, and excel in our roles.\n\nExclusively for ShopBackers\n\nCareer progression paths and opportunities to take on greater challenges that help you realise your ambitions.\n\nBe part of a winning team  on a journey to global scale.\n\nCompetitive compensation based on your performance.\n\nCandid, open, and collaborative culture where feedback is valued, for everyone to grow and improve every day.\n\nShopBack is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. We do not discriminate on the basis of race, color, religion, sexual orientation, national origin, age, disability, genetic information, veteran status, or any other protected status under applicable laws. Join our team and help us make a difference!\n\nWe are committed to protecting your data and ensuring fairness in our recruitment process. As part of this process, we use AI tools to assist with tasks such as application screening and candidate matching. These tools are designed to enhance efficiency and reduce bias, and their use complies with applicable data protection laws and our commitment to fair employment practices. Your personal data will be processed securely and transparently, and final hiring decisions are always made by our recruitment team, not by automated systems. If you have any questions about how your data is used, or wish to exercise any of your rights including the right to such processing, please contact us at dpo@shopback.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1182, 709, 2, '[HN] JUNIOR DEVELOPER (ANY LANGUAGES)', 'Công nghệ\n\nTừ 01 năm kinh nghiệm\n\nLiên Hệ Ứng Tuyển Tại\ntuyendung@teky.edu.vn hoặc 02471096668\n\n- Thu nhập: 12.000.000đ - 16.000.000đ/tháng\n- Hạn nộp hồ sơ: 30.06.2023\n- Phòng ban: Công nghệ\n- Thời gian làm: Fulltime\n- Khu vực: Hà Nội\n- Số lượng: 1\n\nGửi hồ sơ ứng tuyển\n\nThông tin công việc\n\n- Thời gian làm việc: 8h00 - 17h00, nghỉ trưa 1 tiếng. Làm việc từ thứ 2 tới hết sáng thứ 7 hàng tuần\n- Nơi làm việc:\n  Teky Hội sở chính [Hà Nội]: Số B-TT01-51-53 Khu nhà ở Ngân Hà Vạn Phúc, phường Vạn Phúc, quận Hà Đông, TP Hà Nội\n\nMÔ TẢ CÔNG VIỆC\n\nSố lượng 02\n- Thiết kế và lập trình các tính năng cho sản phẩm EdTech sử dụng Python + Django/Ruby on Rails/PHP\n- Viết các đoạn code chất lượng: rõ ràng, dễ dàng bảo trì, tái sử dụng\n- Tham gia vào quá trình phân tích nghiệp vụ, thiết kế và phát triển các tính năng\n- Liên tục tối ưu sản phẩm, xử lý lỗi và nâng cao độ ổn định của hệ thống, trải nghiệm người dùng\n- Xây dựng các thư viện, API dùng chung cho các sản phẩm\n- Làm việc với các lập trình viên có kinh nghiệm, quản lý, thiết kế để xây dựng các sản phẩm\n- Địa điểm làm việc: Tầng 5, tòa MAC Plaza, số 10 Trần Phú, Hà Đông.\n\nGiới thiệu về team Hệ thống và Công nghệ \nTại TEKY, mọi hoạt động online/offline từ vận hành nội bộ (bán hàng, chăm sóc khách hàng, kế toán,..) cho đến quản lý học tập (lịch học, ôn bài, làm bài tập về nhà, tương tác với học sinh/phụ huynh) đều ứng dụng công nghệ bài bản, có hệ thống, và là tiêu chí bắt buộc mỗi nhân viên cần phải thành thạo. Team Hệ thống và Công nghệ là những người xây dựng, phát triển, vận hành các hệ thống; đảm bảo các hoạt động hàng ngày ở TEKY diễn ra hiệu quả nhất, mang lại trải nghiệm tốt nhất cho nhân sự nội bộ, phụ huynh và học sinh.\n\nYÊU CẦU CÔNG VIỆC\n- Tốt nghiệp Cao đẳng/Đại học hoặc cao hơn chuyên ngành Khoa học máy tính/Công nghệ thông tin/Hệ thống thông tin/Công nghệ phần mềm hoặc các chuyên ngành tương tự\n- Yêu thích lập trình, sáng tạo và thích giải quyết các vấn đề thách thức\n- Có kinh nghiệm làm việc thực tế với một trong các Web framework phổ biến: Django, Ruby on Rails, Node.js, PHP,…\n- Có hiểu biết vững vàng về các kiến thức nền tảng của khoa học máy tính: cấu trúc dữ liệu, thuật toán, cơ sở dữ liệu\n- Có kinh nghiệm làm việc thực tế với hệ cơ sở quản trị dữ liệu: MySQL, PostgreSQL, MongoDB\n- Tư duy giải quyết vấn đề logic\n- Kinh nghiệm làm việc từ 1 năm trở lên\n\nQUYỀN LỢI ĐƯỢC HƯỞNG\n- Lương, thưởng theo năng lực: 12 – 16 triệu/tháng, hoặc có thể thỏa thuận theo năng lực\n- Được làm việc cùng đội ngũ số 1 Việt Nam trong mảng STEAM cho K12: nhân sự tại TEKY là những người đang tạo và dẫn dắt xu hướng STEAM cho K12 ở Việt Nam\n- Con CBNV được học miễn phí các khóa học về công nghệ.\n- Lương tháng 13; thưởng hiệu quả kinh doanh theo quý, năm; thưởng lễ-tết theo quy định công ty\n- Được làm việc trong môi trường Giáo dục năng động, chuyên nghiệp, cơ sở vật chất hiện đại, giàu ý nghĩa xã hội.\n- Được hưởng đầy đủ các chế độ theo quy định của nhà nước (BHXH, BHYT, BHTN,…)\n- Được đi du lịch ít nhất 1 lần 1 năm, liên tục tham gia Teambuilding\n- Hưởng các chế độ khác ngoài lương theo định kỳ hoặc không định kỳ\n\nGửi hồ sơ ứng tuyển', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói, Hanoi, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1183, 710, 2, 'Ruby on Rails Intern', 'INTRODUCTION\nWelcome to Golden Owl Solutions - an environment full of youthful, dynamic and creative elements. With more than 10 years of experience in the field of IT outsourcing, we are always proud to provide each employee with a professional working environment and unlimited development opportunities. If you are an enthusiastic, confident and passionate person, join our team and conquer new challenges with us!\n\nWebsite: www.goldenowl.asia \nFanpage: https://www.facebook.com/goldenowl.asia/\n\nhttps://www.facebook.com/goldenowl.careers\nPhone: 028 3846 0098 \nTime working: 9:00 - 18:00, Mon - Fri\nLocation: 31-33 Nguyen Van Dau Street, Ward 6, Binh Thanh District, HCMC, Vietnam;\n\n62 Hoang The Thien, An Loi Dong, Thu Duc City, HCMC, Vietnam\n\nBENEFITS\n● Monthly allowance + parking allowance;\n● Tea-break & team-building monthly;\n● Opportunity to experience professional working environment; \n● On-job training; English training;\n● Opportunity to be promoted to a full-time position after an internship;\n\nREQUIREMENTS\n● 4th-year students in computer science, IT or related major;\n● Personal laptop is required;\n● Able to work full-time in 4-6 months during internship period (depends on your performance);\n● 15 months working after internship commitment;\n● Good command of English is a plus;\n● Strong background knowledge of HTML, CSS, OOP, database, any back-end programming language; \n● Knowledge about Ruby or Ruby on Rails is a plus; \n● Knowledge about: Git, SQL is a big plus;\n\nJOB DESCRIPTION\n● Work under coaching of team leader or senior developers; \n● Practice coding with high quality and effective outputs; \n● Estimate tasks; \n● Implement tasks, follow quality guidelines and time plan or the project; \n● Report task progress if needed; \n● Help other team members (PC and QC, team lead, other engineers);\n\nAPPLY: \nSend your CV with title [RUBY INTERN] - FULL NAME via our email: hr@goldenowl.asia \nOnly short-list candidates who meet our above mandatory requirements will be contacted.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1184, 711, 2, 'AI/GenAI Internship', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nWhat You’ll Bring\n\n- Study in Computer Science, Software Engineering or a related field.\n- Knowledge of basic algorithms, object-oriented, database design\n- Knowledge of machine learning, computer vision, backend development\n- Experience with Azure, AWS, GCP is plus.\n- Good at English in both writing and speaking skills is plus.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion\n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '호치민 지역', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1185, 712, 2, 'Fresh Game Designer (Casual/Puzzle)', 'Được thành lập năm 2018, Sun Studio là nhà phát triển games trên nền tảng web và các thiết bị di động với hơn 1 tỷ lượt chơi. Sứ mệnh của chúng tôi là tạo ra các trò chơi mà mọi người có thể dễ dàng tiếp cận (accessible) và yêu thích (enjoyable).\n\nHiện tại công ty có gần 70 thành viên với trên 40 đầu games (dòng hyper casual, casual và puzzle) và là đối tác chiến lược của các nền tảng web-games hàng đầu thế giới như: Facebook Instant Games, Microsoft Instant Games, Crazy Games, Game Distribution, Glance Gaming...\n\nChúng tôi cần tuyển 5 bạn Fresh Game Designers để hỗ trợ đội ngũ phát triển game trong việc thiết kế, cải thiện các games hiện tại và tương lai.\n\nMô tả công việc\n\n- Tham gia phân tích và lên ý tưởng cho các dự án Casual/Puzzle game của công ty\n- Thiết kế luật chơi, màn chơi, tính năng cho game đảm bảo tính giải trí và độ cân bằng\n- Phối hợp với đội ngũ lập trình, họa sĩ để triển khai và tinh chỉnh các tính năng trò chơi theo thiết kế\n- Tham gia play test (chơi thử) các phiên bản game, thu thập phản hồi từ người chơi và nhóm nội bộ để đề xuất cải thiện trải nghiệm\n- Hỗ trợ chuẩn bị và cập nhật các tài liệu thiết kế game (Game Design Document) nhằm truyền đạt ý tưởng một cách rõ ràng cho các thành viên liên quan\n\nKỹ năng và kinh nghiệm yêu cầu\n\n- Cần gửi portfolio để đánh giá\n- Đam mê game: Yêu thích chơi game, đặc biệt là các game mobile thể loại Casual và Puzzle, mong muốn tìm hiểu tâm lý người chơi game\n- Kiến thức nền tảng: Nắm vững các khái niệm cơ bản về thiết kế game (luật chơi, cơ chế gameplay, thiết kế level, v.v.) – có thể từ các dự án cá nhân, đồ án hoặc khóa học\n- Sáng tạo & ham học hỏi: Tư duy sáng tạo, thích tìm tòi ý tưởng mới và sẵn sàng tiếp thu phản hồi để hoàn thiện kỹ năng\n- Kỹ năng làm việc nhóm: Giao tiếp tốt, hòa đồng, biết lắng nghe và phối hợp nhịp nhàng với các thành viên khác trong nhóm\n- Ưu tiên: Có kinh nghiệm cơ bản với các công cụ thiết kế hoặc engine game (Unity, Unreal, hoặc các phần mềm thiết kế level) và có khả năng đọc hiểu tiếng Anh\n\nQuy trình tuyển dụng\n\n- Đánh giá Portfolio và CV\n- Video call phỏng vấn với Chuyên viên tuyển dụng (30 phút)\n- Phỏng vấn tại văn phòng với Trưởng nhóm (45-60 phút)\n\nChế độ đãi ngộ \n\n- Lương và giờ làm việc\n- Lương cho vị trí: hấp dẫn\n- Vị trí này sẽ làm việc tại văn phòng. Thời gian làm việc từ 9:00 - 18:30, từ thứ 2 đến thứ 6\n- Bảo hiểm và chế độ thưởng\n- Được tham gia đầy đủ BHXH/ BHYT/ BHTN theo quy định của luật lao động\n- Ngoài ra bạn sẽ được tham gia bảo hiểm sức khỏe riêng PVI\n- Phụ cấp ăn trưa hàng tháng\n- Thưởng cố định lương tháng 13\n- Thưởng cuối năm không giới hạn, tùy thuộc vào doanh thu của công ty và mức độ đóng góp của bạn trong các dự án\n- Cân bằng cuộc sống & công việc\n- Ngoài những ngày nghỉ lễ theo quy định của nhà nước, chúng tôi có thêm rất nhiều ngày nghỉ được trả lương và nghỉ ốm\n- Nơi làm việc thoải mái\n- Tại văn phòng, chúng tôi có khu vực giải trí, cung cấp đồ ăn phụ và đồ uống miễn phí để giúp bạn làm việc thoải mái và cân bằng\n- Góc Thư viện sách cho các bạn thích đọc sách giấy\n- Phát triển chuyên môn và giáo dục\n- Chúng tôi hoàn trả chi phí cho việc tham gia vào các hội nghị và khóa học có liên quan, đồng thời thường xuyên tổ chức các chương trình đào tạo nâng cao nghiệp vụ\n- Công ty có chính sách hỗ trợ việc thăng tiến và phát triển sự nghiệp của nhân viên\n- Giải trí và gắn kết\n- Hàng tuần / tháng / năm, chúng tôi tổ chức nhiều sự kiện, bao gồm các cuộc thi, thử thách thể thao, tiệc, happy hours, team building, hackathons và sự kiện ngoại tuyến dành cho từng đội\n- Dự án trách nhiệm xã hội\n- Chúng tôi tiếp tục triển khai các dự án từ thiện và hỗ trợ ý tưởng của nhân viên trong các cuộc thi tài trợ\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1186, 674, 2, 'Mobile Developer Intern (IOS/Android/Flutter)', 'Mô tả công việc\n\n- Assist in coding basic features of the stock trading application under the guidance of senior developers.\n- Integrate APIs from the backend to display stock data (e.g., stock prices, charts).\n- Perform testing of the application on iOS/Android devices to identify UI or functional issues.\n- Assist in fixing minor bugs as assigned.\n- Update the application’s UI based on designs from the UX/UI team.\n- Prepare simple technical documentation (e.g., API descriptions, setup guides).\n- Explore new technologies related to mobile development (Flutter, NFC, app security) and suggest improvements.\n- Attend team meetings to contribute ideas and learn from team members.\n\nYêu cầu công việc\n\n- Bachelor’s degree (or final-year student) in Information Technology or a related field.\n- Familiarity with mobile programming languages such as Swift (iOS), Kotlin/Java (Android), or Flutter/Dart (cross-platform).\n- Basic understanding of Object-Oriented Programming (OOP) and data structures.\n- Basic knowledge of RESTful APIs and how to integrate them with applications.\n- Experience using Git for source code management (GitHub, GitLab).\n- Familiarity with UI design tools such as Figma or Adobe XD.\n- Intermediate English language skills (written and verbal).\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Full-time internship allowance: 2.000000 VND/month and parking fee support: 400.000 VND/month.\n- Participate in company training programs (professional skills, communication skills).\n- Support for internship certification stamping (if required).\n- Opportunity to join team-building activities, internal events, and other company recreational activities.\n- Dynamic and professional working environment, with opportunities to work and learn about investment knowledge directly from industry experts in the securities sector.\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: Tầng 21, Phú Mỹ Hưng Tower, 08 Hoàng Văn Thái, Phường Tân Phú, Quận 7\n\nThời gian làm việc\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1187, 366, 2, 'Junior Frontend Engineer (JavaScript/ReactJS) - Naver Services', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nYour daily tasks:\n\nDevelop and maintain Frontend services for NAVER Services\nImplement Server-Side Rendering (SSR), CI/CD pipelines, and monitoring solutions\nCollaborate closely with teams in Korea\n\nYour background:\n\n2+ years of work experience in Frontend development\nHands-on experience in software development using JavaScript and ReactJS\nBasic understanding of web browser mechanisms and rendering processes\nFamiliarity with Data Structures and Algorithms\nInterest in discussing the stability and scalability of Frontend systems\nSolid problem-solving skills and effective communication\nOpen-minded, honest, and a positive attitude towards teamwork\n\nIt\'s a big plus if you:\n\nFamiliar with Frontend performance optimization\nExperience with Node.js and Next.js\nKnowledge of TypeScript, Kubernetes, Docker\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\nCompetitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\nLearning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\nProtecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\nEmployee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\nWorking environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\nDedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\nOther benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1188, 691, 2, 'Software Engineer (Front-End)', 'What You Will Be Doing\n\n- Developing a clean and maintainable code using software engineering best-practices and modern platforms.\n- Participating in full product development lifecycles from ideation to live production.\n- Day-to-day tech operations such as server maintenance and deployment.\n\nWhat We Need From You\n\n- Minimum 1 years of software engineering experience building Web Front End Applications.\n- Comfortable using English in a professional setting.\n- Experience working on ReactJS applications.\n- Have a good understanding of web application architecture\n- Have a good understanding of various software engineering design patterns\n- Versatility and enthusiasm to tackle new problems across the full-stack and to learn new frameworks as we continue to push technology forward.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '호치민 베트남', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1189, 689, 2, 'Swift Coders - AI Training [Remote] (Vietnamese Speakers Encouraged)', '* Swift, Python, Java, Go, Verilog, Typescript, Javascript, C++, or C# coding experience required\n\nThis is a great opportunity to supplement your income while looking for longer or more full-time work, all while contributing to the development of new AI models using your domain expertise!\n\nOur client has hired over 1,000 Braintrust talent and intends to hire hundreds more!\n\nMany Braintrust coders earn over $12,000 per month!\n\nYou’ll have the flexibility to work as much or as little as you choose - 20hrs/week is suggested, but not a limit. Start working in as little as 48 hours. Your final hourly rate will be chosen by Outlier AI and determined by your location.\n\nWhat to expect: If qualified, you’ll be invited to complete a brief questionnaire that takes 3-5 minutes. If you successfully pass the questionnaire, you’ll be approved and able to begin work ASAP.\n\nRequired qualifications:\nProficiency working one of the following languages: Swift, Python, Java, Go, Verilog, Typescript, Javascript, C++, or C#\nComplete fluency in the English language is required. You should be able to describe code and abstract information in a clear way.\n\nPreferred qualifications:\nBachelor\'s and/or Master\'s degree in Computer Science or equivalent. Students are welcome.\n\nNote: Outlier AI is partnering with Remotasks for this opportunity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1190, 450, 2, 'Consumer Operation System Intern', 'Our Journey\n\nShopBack began in 2014 as a late-night spark of inspiration between Henry and Joel — not just to build a Cashback platform, but to reimagine how brands and consumers connect. As former advertisers, they understood the limitations of traditional marketing, and saw an opportunity to deliver more value on both sides. That idea quickly turned into action, with the first prototype built during a 24-hour sprint. Today, ShopBack serves over 50 million users across 13 markets, partners with 20,000+ merchants, and powers over half a million transactions daily. We\'re building The World’s Most Rewarding Way to Shop — and looking for bold, driven individuals to join us.\n\nWe are looking for a motivated and detail-oriented Consumer Operation System Intern to join our Consumer Operations Application team. In this role, you will assist with the management and optimization of consumer operation systems. This opportunity is perfect for individuals who are excited to gain practical experiences in system management, automation technologies, and AI-driven solutions.\n\nWe are currently accepting applications for August 2025 to February 2026 internship period.\n\nYour Adventure Ahead\n\n- Consumer System Support: Assist in the day-to-day operation system management, including user administrations and system maintenance.\n- AI Chatbot Support: Assist in the setup, testing, and optimizing of the AI chatbot used in customer service operations. Monitor chatbot interactions to ensure accuracy and efficiency, providing suggestions for improvements. Collaborate with the team to update and maintain the chatbot’s knowledge base and response scripts. Analyze chatbot performance metrics and prepare reports for ongoing optimization.\n- Reporting and Documentation: Analyze data and create insightful reports to aid decision-making and drive continuous improvement efforts. Documenting the supporting pages for operational initiatives, projects, or product launches.\n\nEssentials To Succeed\n\n- Systems support enthusiast: You have a keen interest in exploring and managing customer service operations through systems, coupled with a strong desire to learn and engage with the latest technologies.\n- Analytical thinker: You possess good analytical and problem-solving skills.\n- Effective communicator: You have good English communication skills, enabling you to effectively engage and collaborate with cross-border stakeholders.\n- Proactive: You thrive in a fast-paced environment. You\'re the kind of person who takes the initiative and tackles challenges head-on.\n\nShopBackers\' DNA\n\n- Grit - We tackle all challenges head-on, working together to solve problems and achieve success.\n- Hunger - We value hard work, and having relentless drive.\n- Speed - We move fast and have a bias for action, all to deliver maximum impact.\n- Impact - We focus on results, always aiming for the best possible outcomes and timelines.\n- Growth - We embrace a growth mindset, constantly striving to learn, improve, and excel in our roles.\n\nExclusively for ShopBackers\n\n- Career progression paths and opportunities to take on greater challenges that help you realise your ambitions.\n- Be part of a winning team on a journey to global scale.\n- Competitive compensation based on your performance.\n- Candid, open, and collaborative culture where feedback is valued, for everyone to grow and improve every day.\n- Flow Day Thursday (1-day a week, optional to work from home or office).\n\nShopBack is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. We do not discriminate on the basis of race, color, religion, sexual orientation, national origin, age, disability, genetic information, veteran status, or any other protected status under applicable laws. Join our team and help us make a difference!\n\nWe are committed to protecting your data and ensuring fairness in our recruitment process. As part of this process, we use AI tools to assist with tasks such as application screening and candidate matching. These tools are designed to enhance efficiency and reduce bias, and their use complies with applicable data protection laws and our commitment to fair employment practices. Your personal data will be processed securely and transparently, and final hiring decisions are always made by our recruitment team, not by automated systems. If you have any questions about how your data is used, or wish to exercise any of your rights including the right to such processing, please contact us at dpo@shopback.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1191, 189, 2, 'Web App Developer', 'Position Summary\n\nRole and Responsibilities\n\nJOB RESPONSIBILITIES:\nDevelop and maintain web-based mobile applications for smart devices and robot.\nActively participate in the development process, taking responsibility for and completing assigned tasks.\nAnalyze and effectively solve problems that arise during project development.\nResearch, propose and implement solutions to improve project quality.\nCollaborate, support team members and other departments during work.\n\nSkills And Qualifications\n\nKNOWLEDGE, QUALIFICATION AND EXPERIENCE\n\nGeneral Requirement\n\nBachelor’s degree in computer science, Software Engineering or a related IT field.\nAt least 1 year of experience in software development.\nProficient in English for work purposes.\nStrong skills in problem analysis and resolution.\nFast learner with a mindset geared toward quickly understanding new technologies and product modules.\nAbility to multi-task and manage tasks with varying priorities.\nTech-savvy and passionate about building products.\nProactive at work\n\nTechnical Requirement\n\n(Mandatory)\n\nKnowledge in Web application technical programing: JavaScript, Typescript, CSS, HTML5, …\nGood at handling Web applications across multiple screens size.\nFamiliarity with ESLint for maintaining code quality and style.\nExperience in using and customizing component UI frameworks such as Antd design, Tailwind - flow bite, material design.\nUnderstanding of W3C standards and experience in handling W3 error compliance.\nExperience in writing and executing unit tests for web applications (Jest, Mocha, Cypress).\nKnowledgeable in Clean Architecture, design patterns (MVC, MVVM) and OOP.\nExperience with distributed version control systems (Git, SVN).\n\n(Optional)\n\nProficient in using Webpack for module bundling and optimizing web applications.\nStrong understanding of CI/CD principles.\nKnowledge & experience of handling IoT connection: Bluetooth, Socket, MQTT, IoT server\nHave experience of chat application (WebRTC, …)\nHave experience of software quality & performance\nKnowledge of image/video detection libraries (OpenCV, TensorFlow) will be highly appreciated\nExperience in Android/IOS development (native & cross-platform) is big plus\nFamiliar with Algorithm or have high level on Coding challenge platform like Leet code, Hacker Rank is a big plus\n\nEMAIL: NGUYEN.LT@SAMSUNG.COM\n\nPlease visit Samsung membership to see Privacy Policy, which defaults according to your location. You can change Country/Language at the bottom of the page. If you are European Economic Resident, please click here.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミンシティ都市圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1192, 713, 2, 'Frontend Engineer', 'Job Type\n\nFull-time\n\nResponsibilities and Duties\n\nOnce You Join Our Team, You Will\n\n- Collaborate with other team members (PM, UI, backend engineer, QA) to provide a seamless freight experience for our customer;\n- Participating design the front end architecture, collaborate with backend engineers to develop and deliver elegant product solutions;\n- Propose innovative technical solutions to hard business problems;\n- Curiosity and passion, understanding of LLM and AI Agent framework;\n- Lean and grow constantly, improve yourself and make the team member around you better\n\nRequirements\n\n- Familiarity with the development process and work patterns of internet products.\n- Fluent in frontend technologies, including HTML, CSS, JavaScript, and TypeScript.\n- Fluent in React, with practical experience in developing complete React projects.\n- Solid experience with common frontend frameworks, libraries, and tools such as Webpack, Babel, Vite, Turbo, Lerna, Next.js, React, and Vue.\n- Understanding and familiarity with Node.js, capable of project building, with some backend development experience in Node.js.\n- Proficiency in TypeScript; practical experience with TypeScript projects is a plus.\n- Familiarity with commonly used frontend state management tools, such as Redux, MobX, Observable, React Hooks, Zustand, and Recoil.\n\nPreferred Qualifications\n\n- Practical experience with TypeScript and React projects.\n- Experience in developing AI bots.\n- Some experience in backend development with Node.js and Python.\n- Familiarity with open-source LLM models and knowledge of projects like LangChain and Llama-Index.\n- Understanding of containerization and serverless development.\n- A personal blog or independent website is a plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 3, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1193, 679, 2, 'HCM – Junior Fullstack Developer (ReactJS+NodeJS) – Hybrid Working', 'Junior Fullstack Developer (ReactJS + NodeJS)\n\nVexere is a technology company aiming to revolutionize the travel and transportation industry in Vietnam. We are pioneering a comprehensive digital transformation of the transport industry with diverse web applications and latest technology apps. We are available on all super apps such as Grab, Momo, and Zalopay. Covering diverse vehicles from low-priced to luxury buses, with 1,000 bus operators on all over 3,000 routes, Vexere is the largest online inter-city bus booking platform that empowers millions of travelers to make their life journeys happier.\n\nWant to build a large-scale system with hundreds of thousands of concurrent users?\n\nWant to build an enterprise solution that could adapt to complex requirements from thousands of bus companies?\n\nCome to us to build a microservices ecosystem on the latest technologies such as kubernetes, istio service mesh, mirroring or shadowing traffic, event sourcing, domain driven design, test automation, CI/CD, etc. Each service has its own monitoring system to measure several performance metrics such as API response time, caching time, cache hit/miss ratio, database hit rate. We are proud to be one of the few companies in Vietnam that follow the path of a full CI/CD system architecture with dedicated senior devops engineers to make the life of a developer much easier. You are free to build and do experience on millions of users without worries.\n\nOur Tech Stack\n\nBackend:\nNode.js, ExpressJs\nRabbitMQ / Kafka / MSSQL / PostgreSQL / Redis / Elasticsearch\nDocker / Kubernetes / Jenkins\n\nFrontend\nReact.js / React Native\nES6 / Typescript\nRedux / Redux-Saga / Hooks\n\nResponsibilities\n\n- Develop high-quality solutions to meet business requirements by designing, coding, and shipping well-structured, maintainable software.\n- Identify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\n- Collaborate and share knowledge within the Frontend Squad to maximize team expertise and personal growth.\n- Take ownership: Lead a team or a product if capable, contributing to technical direction and best practices.\n\nRequirements\n\nMust-Have:\n- Proactive mindset, eager to take initiative and solve problems.\n- Fast learner, able to adapt quickly to new technologies.\n- From 1 to 3 years of real-world experience in software development.\n- Familiarity with macOS or Linux for development and deployment tasks.\n- Understanding of our technology stack (no need to master everything, but familiarity is required):\n  - Backend: Node.js, PostgreSQL, Redis, Elasticsearch.\n  - Frontend: React.js, Redux, Redux-Saga, Reselect, React Hooks.\n- Commitment to code quality:\n  - Strong experience in code reviews.\n  - Familiarity with unit testing best practices.\n  - Growth mindset: Ready to grow rapidly as the company scales several times a year.\n\nNice-to-Have (Plus)\n\n- Deep knowledge of Webpack: Code splitting, asset handling, optimization.\n- Strong foundation in computer science: Data structures, algorithms, design patterns.\n- Experience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\n- Familiarity with microservices architecture.\n\nBenefits\n\nCompetitive Compensation & Bonuses\n\n- Attractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n- 100% salary during the probation period.\n- Performance reviews twice a year with opportunities for salary adjustments.\n\nFlexible Work & Growth Opportunities\n\n- Hybrid working model: Work from home or at the office as needed.\n- Work alongside top CTOs, architects, and tech leaders at Vexere.\n- Build your public profile through:\n  - Publishing articles on Medium & Vexere Techblog under your name.\n  - Contributing to Open Source projects managed by Vexere.\n  - Speaking at tech talks and industry events.\n  - Attractive stock options for dedicated developers and team leads.\n\nExclusive Employee Perks\n\n- Up to 30% discount on bus tickets for Vexere employees and their families.\n- 12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\n- Vibrant and dynamic work environment with a friendly, supportive team.\n- Training sessions on negotiation, communication, work management, interpersonal skills, and software technology.\n- Exciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nWhat factors can help you trust Vexere?\n\nCurrently, Vexere is the largest online bus ticketing platform in Vietnam with more than 1000 inter-city bus companies, covering over 3,000 domestic and cross-border routes to help users find bus information and buy tickets online easily. At the same time, Vexere also provides reviews of passengers who have traveled these buses. Passengers can simply select their favorite seats, pay online, or pay in cash at convenience stores across the country.\n\nVexere Bus Management System (BMS) is used by more than 700 bus companies all over the country, helping bus companies to modernize management with effective management, optimized revenue, and costs. This is a revolution in the inter-city bus industry.\n\nOver 5,000 agents are using Vexere Agent Management System to increase ticket sales and serve their customers better.\n\nVexere’s efforts have been recognized and accompanied by famous institutional investors such as Woowa Brothers (the company owning Baemin), CyberAgent ventures (Japan), BonAngels (Korea), Pix Vine Capital (Singapore), Spiral Ventures (Japan), Access Ventures (Korea), NCore Ventures (Korea). Two investors of VeXeRe are Decacorns (>USD10B valuation).\n\nReview sobre Vexere\n\nFor More Information, Please Contact Us Via\n\n- Send your Resume to email: careers@vexere.com, with title: Fullname – Applied Position\n- Phone/ Zalo: 039.555.5486 (Mr. Nhân)\n- Office Location: Vexere Trading Service Co., Ltd – 2nd floor – Building H3, 384 Hoang Dieu, Ward 6, District 4, HCMC\n- Working Hours: Hybrid Working 8:30 am – 6:00 pm from Monday to Friday, and Saturday morning.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh e Região', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1194, 701, 2, 'WordPress Developer Internship', 'Please note: This is an unpaid internship.\n\nRequirements\nExperience using WordPress \nPHP/CSS/HTML\nEnglish\nAbility to solve problems with minimal direction, supervision\nPreferred Additional Skills/Experience\nExperience using Beaver Builder\nCustom Post Types\nAccess to Photoshop or GIMP for the opening of design files\nBeaver Builder Themer\nAbility to solve problems with minimal direction, supervision\nHigh degree of learning agility / fast and interested learner\nSelf-motivated, self-starter\nUses time efficiently\nPatient, positive and supportive attitude with team members\nExperience with WordPress installations, configuration, security, and theme development\nGoogle Page Speed Insights\nInitial Responsibilities\nEditing templates and CSS to match a design example\nTesting a series of custom features in a site\nBuilding HubSpot Templates and Modules\nWork closely with the webmaster for the Quotes Engine Project\nTarget Responsibilities\nCustom HubSpot, WordPress site builds – take a Photoshop file and apply the styles to a HubSpot CMS, WordPress child theme, work with Beaver Builder, PHP, and WordPress child theme templates to set up custom features and layouts as needed.\nModify and create new Beaver Builder modules to add support for features, complex functionality, and intricate styling that aren’t natively available.\nDevelop and maintain custom themes with an eye towards automation and end user-friendliness\nExtend 3rd party plugins with WordPress hooks, template overrides, or creative solutions to accomplish time-sensitive tasks\nPlugin troubleshooting/problem-solving.\nFeature documentation.\nTaking screenshots and writing out steps/instructions to be used in Thinkific for course-building\nProject debriefs – sharing your experience with a site or project build with the team.\nExamples of tasks\nWe receive a Photoshop file or HTML/CSS of a design for a website. The site is already installed and a HubSpot theme is set up. You would update the templates, modules, and pages to match the design.\nMarketing needs to make customizations to their events in Beaver Builder to display an external link that they can change from the WordPress admin. You would add a custom field that shows on posts with something like Advanced Custom Fields (ACF) and then modify the Beaver Builder post feed module to display data from the ACF field on the front end.\nA website with hundreds of already created posts and pages is being redesigned. You would create page templates and widgets that account for dynamic content in order to restyle existing posts in a way that ensures nothing slips through the cracks while working within the confines of the already existing website or proactively identifying new technology that would better serve the redesign and decrease redesign time.\nA designer you’re working with has finished their mock-up on a new site build with great UI/UX but is unsure how to handle dynamic content within their design. You proactively suggest solutions and utilize responsive frontend best practices to ensure the website looks good on every browser and every device regardless of what the content looks like. We will use WordPress or HubSpot only so it is important to learn or be certified on these.\nRequired Tools\nInternet connection\nGIMP or Photoshop CS 5.x or any version supporting grouped layers\nA text editor or IDE capable of editing WordPress code, Notepad++\nWhat’s TRG offering for you?\nIndependently Work From Anywhere (WFA) you want: our offices, your home, PJ’s Coffee, coffee shop, beach, it\'s up to you\nModern, green, and open office space with lounge areas, spacious lunchroom, free covered / secure motorbike parking unlimited free PJ’s Coffee from our own coffee shop downstairs\nWorking with our Diverse and Inclusive TRG community with colleagues WFA from across the globe\nStrong culture to support your learning development and growth\nMultiple (12+) networking/collaboration/learning/training events each month\nTraining and certification support\nFree access to our library (1000+ books), multiple online training portals/ universities/ academies', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1195, 714, 2, 'React Js Developer', 'We are looking for a Front-end Engineer — ideally with full-stack capability — to join our development team and work closely with the UK-based back-end team. The candidate will be responsible for implementing front-end features, ensuring smooth integration with APIs, and maintaining code quality and performance.\n\nResponsibilities\n\nCollaborate with the UK back-end team to develop and maintain front-end components of the platform.\nTranslate design requirements and wireframes into high-quality code.\nEnsure cross-browser compatibility, responsiveness, and performance.\nParticipate in sprint planning, code reviews, and knowledge-sharing sessions.\nTroubleshoot and debug front-end issues.\n\nRequirements\n\nBachelor\'s degree in Information Technology, Software Engineering, or a related field.\n2 years experience.\nProficiency in React (mandatory)\nKnowledge of .NET is a strong plus\nFamiliarity with HTML/CSS, RESTful APIs, version control (Git)\nUnderstanding of cross-browser compatibility and front-end optimization\nComfortable working with foreign clients — the client is based in the UK, and the English accent may be challenging for some\nNice to Have:\nExperience in working with UK or European clients\nUnderstanding of Agile/Scrum methodologies\nFull-stack capabilities with .NET (bonus)\n\nBenefits\n\nSocial and unemployment insurance coverage as per Vietnamese Labor Law; Bao Viet Insurance when join upper 1 .\nAnnual leave entitlement in accordance with the Vietnamese Labor Law.\n13th-month salary and annual salary review.\nBonuses for public holidays.\nMonthly team-party activities.\nSkill development through e-learning, workshops, and more.\nOffice perks including fruit, tea, and coffee, birthday gifts, and access to books.\nAccess to a PlayStation 5 gaming console in the office.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1196, 715, 2, 'Kỹ sư Phát triển Front-end (Front-end Engineer)', 'MÔ TẢ CÔNG VIỆC\nPhát triển các tính năng giao diện người dùng.\nLập trình các Landing page/ Microsite từ file thiết kế Figma.\nCó thể sử dụng thành thạo HTML, CSS, JS, Bootstrap, Tailwind CSS. Tối ưu code HTML/CSS theo chuẩn W3C, Responsive website để hỗ trợ chạy trên nhiều thiết bị và trình duyệt khác nhau.\nTạo hiệu ứng cho website sử dụng CSS3, HTML5 và Jquery.\nCó kỹ năng xử lý UI/UX theo yêu cầu của sản phẩm.\nLập trình UI/UX kết nối API sử dụng Reactjs.\nXây dựng và phát triển các sản phẩm hoặc hệ thống có số lượng người dùng cao.\nChịu trách nhiệm về chất lượng, trải nghiệm người dùng, thẩm mỹ của sản phẩm trong khi sản phẩm hoạt động.\nTham mưu, tư vấn về chất lượng, thẩm mỹ, trải nghiệm người dùng về các sản phẩm.\nYÊU CẦU\nTốt nghiệp chuyên ngành CNTT hoặc chuyên ngành liên quan.\nCó tư duy thẩm mỹ tốt.\nCó kinh nghiệm làm việc với Reactjs từ 1 năm kinh nghiệm.\nNắm rõ kiến thức về Redux#, hoặc Redux saga, Redux toolkit.\nĐã biết và làm việc thân thiện với cái api.\nHiểu rõ vẫn hành của javascript dom, promise, async.\nBiết framework nextjs là một lợi thế.\nĐã từng dùng các liberary Ui như Boostrap, Antd design, Material, Argon, Jquery…vv\nCó khả năng research tài liệu và đọc tài liệu.\nBiết rõ cái thẻ meata, font, layout.\nBiết CSS, Scss….vv và hiểu rõ các thuộc tính.\nQuyền lợi\nThu nhập thoả thuận dựa trên năng lực ứng viên.\n13 tháng lương, package 2000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\nĐược hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\nĐược hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\nĐược trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\nCó cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\nĐược cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\nCó cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1197, 716, 2, 'Thực tập sinh Dotnet', 'Mô tả công việc\n\nTham gia phát triển các dự án phần mềm.\n\n- Thực hiện coding theo các công việc được giao.\n- Một số công việc khác sẽ trao đổi cụ thể trong buổi phỏng vấn\n- Thực tập sinh khi vào làm sẽ được nghiên cứu về cách tiến hành công việc\n- Chúng tôi sẽ hướng dẫn và tập huấn cho nhân viên về ý thức chất lượng, team work cần thiết cho công việc nhóm.\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1198, 717, 2, 'Developer cho website/ứng dụng', 'Mô tả công việc\n\nCông Việc\n\n- Triển khai trang web / ứng dụng theo yêu cầu\n- Hỗ trợ bộ phận chăm sóc khách hàng và đội ngũ bán hàng\n\nYêu Cầu\n\n- Có 3 năm kinh nghiệm trở lên với vai trò developer\n- Có kinh nghiệm về Node.js (điểm cộng)\n- Có kinh nghiệm về MongoDB (điểm cộng)\n- Có kinh nghiệm về JavaScript (điểm cộng)\n- Kinh nghiệm phát triển di động (iOS/Android) (điểm cộng)\n- Trình độ tiếng anh trung cấp (điểm cộng)\n\nLợi Ích\n\n- Thu nhập: trên 20,000,000 và cố định (thỏa thuận tại buổi phỏng vấn), tiền thưởng, phụ cấp\n- Làm việc theo một doanh nghiệp AI Hàn Quốc tiên tiến\n- Làm việc với các công ty tiên tiến từ Hàn Quốc, Trung Quốc, Nhật Bản, Việt Nam\n- Bảo hiểm cho phép theo luật pháp Việt Nam\n- Làm việc trong môi trường cạnh tranh và phát triển, có cơ hội làm việc với các công ty tiên tiến khác từ Hàn Quốc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1199, 718, 2, 'Auslandspraktikum in der Softwareentwicklung im Bauwesen', 'Als GSI Software haben wir uns auf die Entwicklung von Softwarelösungen in der Baubranche spezialisiert. Mit unseren Teams in Berlin und Ho Chi Minh Stadt, Vietnam entwickeln wir sowohl eigene Softwareprodukte und unterstützen außerdem unsere Kunden und Partner bei der Produkt- und Plattformentwicklung. Zu diesen gehören internationale Ingenieurbüros, sowie zahlreiche namhafte Software- und Produkthersteller.\nIm Rahmen unseres Praktikumsprogramms bieten wir dir (m/w/d) die Möglichkeit in unserer Auslandsniederlassung in Vietnam ein Praktikum zu absolvieren.\nTasks\n- Du unterstützt in der Projektkommunikation und Koordination\n- Du wirkst mit bei der Produkt- und Plattformgestaltung\n- Du erstellst Anforderungsanalysen für unsere Kunden (Business Analysis)\n- Du unterstützt bei der Qualitätssicherung\nRequirements\n- Du bist motiviert, arbeitest selbstständig, zielstrebig und konzentriert\n- Du löst gerne technische Probleme und hast gute Studienergebnisse\n- Gute Deutsch- und Englischkenntnisse in Wort und Schrift\n- Grundwissen in Bauingenieurwesen und Softwareentwicklung\n- Vorzugsweise erste Erfahrungen mit BIM und Statik Software (ALLPLAN, Revit, Frilo, SOFiSTiK, …)\n- Interesse an der Arbeit in einem internationalen Team und anderen Kulturen\nBenefits\n- Arbeit an konkreten Projekten, welche die die Arbeit von über 100,000 Anwendern beeinflussen\n- Großartige Auslandserfahrung in unserem internationalen Team in Ho Chi Minh Stadt\n- Angemessene Praktikumsvergütung \n- Fortführung Werkstudententätigkeit in Berlin zu unserer Auslandsniederlassungen in Ho Chi Minh Stadt\nWir freuen wir uns auf deine aussagekräftige Bewerbungsunterlagen!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh Şehri, Ho Chi Minh Kenti, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1200, 719, 2, 'Java Developer', 'MÔ TẢ CÔNG VIỆC\n\n- Làm việc onsite tại ngân hàng, công ty đa quốc gia, tập đoàn với nhiều dự án và công nghệ khác nhau: Dự án Xử lí nợ, Dự án quản lí thanh toán...\n- Tham gia thiết kế ứng dụng, phân tích requirements, thiết kế hệ thống.\n- Có cơ hội được phát triển ứng dụng trên mảng tài chính, ví điện tử, cổng thanh toán, ngân hàng\n- Nghiên cứu và áp dụng các công nghệ mới\n- Tham gia các khóa đào tạo của công ty\n- Thiết kế và phát triển giải pháp nền tảng mới\n- Hỗ trợ và duy trì các ứng dụng web hiện có\n\nYÊU CẦU\n\n- Có kinh nghiệm phát triển ứng dụng web và api sử dụng Java, Java Spring, Java Spring boot\n- Thành thạo việc xây dựng và sử dụng Restful API, Proxy server (httpd)\n- Có kinh nghiệm làm việc với cơ sở dữ liệu Oracle, SQL\n- Có kinh nghiệm làm việc với HTML, CSS, JavaScript\n- Đã từng làm các dự án về internet banking là lợi thế\n- Có kinh nghiệm 2 năm ở vị trí tương tự\n\nQUYỀN LỢI\n\n- Thu nhập thỏa thuận + Thưởng\n- Làm việc trong môi trường chuyên nghiệp, năng động và phát huy được tối đa các năng lực bản thân.\n- Được tham gia các hoạt động dã ngoại, vui chơi giải trí, du lịch do công ty tổ chức.\n- Khen thưởng khi đạt chỉ tiêu, bình chọn nhân viên xuất sắc hàng tuần/hàng tháng/hàng quý.\n- Chế độ BHXH, BHYT, BHTN, thai sản theo quy định của nhà nước.\n- Tiệc Happy Hour hàng tháng, quà tặng sinh nhật, kết hôn,...\n- Được cấp thiết bị để làm việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 3, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1201, 720, 2, 'Junior Developer (ServiceNow - Training Path)', '🚀 We’re hiring: Junior Developer – Open to ServiceNow\n\n📍 Location: Hybrid – District 7, HCMC\n💼 Full-time | Entry-Level – Junior\n🌍 Join SCC – a UK-headquartered tech company delivering enterprise solutions across 5 countries\n\n👨‍💻 About the opportunity:\n\nAre you passionate about solving business problems with technology?\nNot experienced in ServiceNow yet? That’s OK.\nWe’re looking for junior developers who are eager to learn and ready to transition into the world of ServiceNow – a leading enterprise automation platform used by global organizations.\n\nThis is a rare chance to be trained, mentored and grow your career with real international projects.\n\n🔧 What you’ll do (after onboarding & training):\n\n• Learn to develop & configure ServiceNow applications (like ITSM, CMDB…)\n• Build small integrations with guidance\n• Write scripts, create workflows, and customize UI components\n• Support troubleshooting & testing alongside senior developers\n• Work with Agile team to deliver features on time\n• Participate in code review and team discussions to improve continuously\n\n🎯 We’re looking for someone who:\n\n• Has basic coding experience (in JavaScript, Java, Python, or similar)\n• Understands the software development life cycle\n• Communicates well in English (written + spoken)\n• Has a strong willingness to learn, explore new tools and ask good questions\n• Works proactively, not afraid of challenges\n• Can commit to long-term growth with us\n\n💡 Bonus if you have:\n\n• Any internship or project related to web dev / automation / IT systems\n• Familiarity with Agile/Scrum or Jira\n• Awareness of what ServiceNow is (but again, not mandatory)\n\n🌟 Why this is special:\n\n• Training & real-world exposure to ServiceNow – a high-demand, global platform\n• International working culture with UK, France & other EU teams\n• Hybrid working (Thu-Fri WFH) – no timesheet, no micromanagement\n• Full salary insurance, 13th month, performance bonus, and paid leave increases yearly\n\n🟢 Interested but unsure? Let’s connect and see if this path is right for you.\nThis is your gateway to a high-demand, global tech career.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1202, 721, 2, 'Software Engineer (Frontend)', 'Keyloop bridges the gap between dealers, manufacturers, technology suppliers and car buyers.\n\nWe empower car dealers and manufacturers to fully embrace digital transformation. How? By creating innovative technology that makes selling cars better for our customers, and buying and owning cars better for theirs.\n\nWe use cutting-edge technology to link our clients’ systems, departments and sites. We provide an open technology platform that’s shaping the industry for the future. We use data to help clients become more efficient, increase profitability and give more customers an amazing experience. Want to be part of it?\n\nRole Purpose\n\nThe Software Engineer (Frontend) predominantly works on projects utilising web front-end technologies but can also undertake full stack project builds including both back-end and front-end technologies.\n\nThe Software Engineer works with existing known technologies but also investigates new technologies and identifies application opportunities to new or existing products / projects applying the technology best fit-for-purpose. Working in an agile approach, you are expected to plan, prototype and build applications, in part or in full, whilst working as an individual or in a team.\n\nThe role is very much R&D orientated with prototypes & proof-of-concepts as common outputs refined through ongoing stakeholder feedback. Innovation, problem solving, and excellent technical skills are essential to this role.\n\nKey Responsibilities\n\n- Maintain & evolve existing software suite focussing on the frontend\n- Build of new products in part or full\n- Working on SaaS platforms and bespoke projects\n- Research new and existing technologies\n- Presentation of technology opportunities to stakeholders\n- Build of prototypes and proof of concepts\n- Basic creation of high-level technical documentation and specifications\n- Ensure the confidentiality, integrity, and availability of all IT business information\n- Working with established production processes but always looking for areas of improvement in efficiencies\n\nPerson Specification\n\n- Technical Competencies \n- HTML(5)\n- CSS & Tailwind\n- JavaScript (inc es6) / JQuery\n- React\n- NextJs\n- Shadcn/ui\n- Storybook\n- Knowledge of Node.js\n- Basic database knowledge e.g. MySQL / NoSQL\n- Basic understanding of version control systems (GIT/SVN)\n- Experience with restful API’s\n- Basic Figma knowledge\n- Awareness of some of the basic Amazon Web Services (S3, DynamoDB, EC2)\n- Serverless / SAM frameworks for AWS deployments\n- Unit testing; Jasmine / Karma / Jest / Istanbul\n- Behavioural & Personality Competencies:\n- Self-betterment; on-going personal and technical development\n- Work well as part of a team or as an individual\n- Drive for excellent results\n- Commercial Awareness\n- Effective communication skills\n- Engineering mindset\n- Organized & self-sufficient\n- Proactive with taking ownership & responsibility\n- Logical, methodical approach to problem and issue solving\n- Collaborative \n- Problem solving mindset\n- Innovative\n\nRequired Experience:\n\n- 2 or more years’ experience within their respective field\n- Exposure to CMS platforms (Wordpress / Joomla / Drupal / OctoberCMS or custom made)\n- Commercial experience working with frontend technologies\n- Experience in creation of technical documentation\n- Basic backend development PHP / MySql (advantageous)\n\nWhy join us?\n\nWe’re on a journey to become market leaders in our space – and with that comes some incredible opportunities. Collaborate and learn from industry experts from all over the globe. Work with game-changing products and services. Get the training and support you need to try new things, adapt to quick changes and explore different paths. Join Keyloop and progress your career, your way.\n\nAn inclusive environment to thrive\n\nWe’re committed to fostering an inclusive work environment. One that respects all dimensions of diversity. We promote an inclusive culture within our business, and we celebrate different employees and lifestyles – not just on key days, but every day.\n\nBe rewarded for your efforts\n\nWe believe people should be paid based on their performance so our pay and benefits reflect this and are designed to attract the very best talent. We encourage everyone in our organisation to explore opportunities which enable them to grow their career through investment in their development but equally by working in a culture which fosters support and unbridled collaboration.\n\nKeyloop doesn’t require academic qualifications for this position. We select based on experience and potential, not credentials.\n\nWe are also an equal opportunity employer committed to building a diverse and inclusive workforce. We value diversity and encourage candidates of all backgrounds to apply.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1203, 722, 2, 'Java Software Engineer', 'We are seeking an experienced Java Developer to join our team for a 6-month onsite project focused on building a centralized and optimized customer interaction, sales, and service platform. This is a hands-on backend role where you\'ll contribute to designing and developing scalable, secure systems that integrate with existing business applications to enhance customer engagement and drive growth.\n\nWorking Model\n- Location: Onsite in District 10, Ho Chi Minh City\n- Schedule: Full-time onsite for the first 2 months, then 1 remote day per week\n- Duration: 6-month contract\n- Salary: Up to 35 million VND NET/month\n\nKey Responsibilities\n- Develop and maintain Java applications using Spring Boot and related frameworks\n- Design and implement RESTful APIs\n- Manage and optimize database interactions (MySQL, MongoDB, JPA/Hibernate)\n- Apply Spring Security for authentication and authorization\n- Write clean, maintainable code with unit tests (JUnit, Mockito)\n- Use Git and CI/CD tools for version control and deployment\n- Troubleshoot issues, improve performance, and propose innovative solutions\n\nRequirements\n- 3+ years of Java backend experience (Java 8+, Spring Boot)\n- Strong knowledge of OOP, RESTful API development\n- Experience with Spring MVC, Spring Data JPA, and Spring Security\n- Familiar with Git, Swagger/OpenAPI, and CI/CD pipelines\n- Basic knowledge of Docker; experience with Redis, RabbitMQ, or Kafka is a plus\n- Frontend skills (HTML, JS, JQuery, AJAX) are a bonus\n- English communication skills required', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 10, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1204, 723, 2, 'Java Developer Junior', 'MÔ TẢ CÔNG VIỆC \n\n• Thực hiện nhiệm vụ theo yêu cầu của Lãnh đạo phòng.\n• Tham gia các dự án phần mềm của công ty & đối tác\n• Triển khai công việc lập trình theo kế hoạch đã được phân công và đảm bảo hoàn thành đúng tiến độ và chất lượng yêu cầu\n• Thời gian làm việc: T2 – T6, từ 8h30 – 17h30\n\nYÊU CẦU \n\n• Yêu cầu chuyên môn: thành thạo ngôn ngữ lập trình Java\n• Yêu cầu về kỹ năng lập trình, có khả năng sử dụng một trong các nền tảng sau: Frontend: Angular 6+, Backend: Một trong các Java-based framework sau: Spring Boot, Hibernate/MyBatis, JPA..\n• DB: MySQL/Oracle\n• Sử dụng thành thạo các tool: Intellij, SQL developer/ PLSQL, Git\n• Hiểu biết hoặc đã làm việc về Elastic search, Redis là một lợi thế\n• Hiểu biết hoặc đã làm việc với Docker là một lợi thế\n• Kinh nghiệm: tối thiểu 1 năm lập trình các nền tảng nêu trên\n\nQUYỀN LỢI \n\n• Mức thu nhập cạnh tranh 12 – 20M, deal theo năng lực\n• Tháng lương thứ 13, Review lương 2 lần/ năm tùy vào kết quả công việc.\n• Thưởng lễ, tết, thưởng dự án\n• Được hưởng đầy đủ 12 ngày nghỉ phép/năm theo quy định của nhà nước\n• “NMS care” bảo hiểm dành riêng cho nhân viên NMS.\n• Nghỉ mát: Theo chính sách của công ty (Tháng 5/6 hàng năm)\n• Môi trường làm việc hiện đại, thân thiện, có nhiều cơ hội phát triển bản thân.\n• Chính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1205, 682, 2, 'MB Trainee - AI Engineer (Fresher, sinh viên) - Khối Công nghệ thông tin (HOLT.14)', 'Job Description:\n- Participate in the development, application, optimization, and integration of AI models for real-world Business/Banking problems in areas such as Computer Vision, Natural Language Processing (NLP), etc.\n- Contribute to various service deployment phases: system architecture, operational model design, workflow, functional design, and performance optimization.\n- Participate in coding, metric testing, service development, and unit testing in alignment with DevOps and MLOps methodologies.\n- Research and explore the latest scientific publications in Artificial Intelligence (AI), Machine Learning (ML), and Deep Learning (DL).\n- Join training programs and trainee projects with the goal of progressing to official/full-time positions.\n\nJob Requirements:\n- Final-year student or recent graduate (within 1 year) in relevant majors: Information Technology, Computer Science, Electronics & Telecommunications, Software Engineering, Information Systems, etc.\n- Candidates should have knowledge in one or more of the following areas:\n    - Programming languages: Python, C/C++\n    - Service/Microservice development using one of the frameworks: FastAPI, Flask, or Django\n    - AI/ML frameworks: TensorFlow, PyTorch, DGL, PyG, ONNX\n    - APIs: RESTful, gRPC; secure coding practices with performance optimization\n    - Version control & deployment tools: Git (Git Flow), Docker, Kubernetes, Kubeflow, MLflow, Triton Inference Server, TensorFlow Serving\n    - Machine learning problem types: Supervised Learning, Reinforcement Learning\n    - Data types & processing: Image (Computer Vision), Video, Audio, Natural Language (NLP)\n    - Model architectures & algorithms: CNN, RNN, Transformer, Attention, SVM, KNN, Clustering, GNN, etc.\n    - Model optimization techniques: Knowledge Distillation, Model Pruning, Model Quantization', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Région métropolitaine de Hanoï', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1206, 724, 2, 'Full Stack Engineer (NodeJS, NextJS)', 'The Formo team is looking for a Software Engineer to work on high-complexity, strategic projects at Formo. You take ownership of your work, write high-quality, bug-free code, and proactively ensure correctness. With a growth mindset, you seek feedback, engage in technical discussions, and contribute to team success.\n\nResponsibilities\n* Write production-ready code that is testable, well-documented, and accounts for edge cases.\n* Develop UI components, frontend applications, back-end APIs, and libraries.\n* Participate in product development and contribute to technical discussions.\n* Stay updated on new trends and best practices in software development.\n* Collaborate across teams to drive technical decisions and processes.\n* Improve team velocity, reliability, and security through engineering best practices.\n\nQualifications\n* 1+ years of experience as a full-stack engineer (ReactJS & NodeJS).\n* Bachelor\'s degree in Computer Science, Software Engineering, or a related field.\n* Experience building frontend applications and backend APIs.\n* Proficiency in unit/integration testing, debugging, and test-driven development.\n* Understanding of system performance and scaling for large scale web services.\n* Experience with TypeScript libraries and SDKs is a plus.\n* Advanced SQL experience is a plus.\n* Knowledge of big data technologies and data pipelines is a plus.\n* Experience with Customer Data Platforms (CDPs) or web analytics platforms is a big plus.\n* Ownership mindset with a proven track record of delivering projects.\n* Strong English communication skills (written & spoken).\n* Ability to leverage AI tools to enhance development and productivity.\n* Product-oriented mindset with a strong interest in Web3, data platform, emerging technologies.\n\nYou’re a great fit if you:\n* Are passionate about building user-facing products and sweating the details to create exceptional experiences.\n* Have a growth mindset, eager to learn new frameworks, languages, or technologies—including blockchain.\n* Constantly seek innovative ways to solve complex problems through experimentation.\n* Take ownership of your work, always looking for ways to improve efficiency and effectiveness.\n* Are a strong team player with excellent communication and collaboration skills:\n* Open, transparent, and direct in your communication.\n* Receptive to feedback, new ideas, and opportunities for self-improvement.\n* Willing to contribute beyond your defined role.\n* Are a proactive self-starter, ambitious, and unafraid to challenge the status quo in a fast-paced startup environment.\n\nWhy Join us?\n* Shape the future. Web3 and crypto are bigger than most realize—you’ll be at the forefront, solving technical challenges alongside leading founders worldwide.\n* Accelerate your growth. Work with some of the brightest minds, engage in deep discussions, and receive continuous feedback to expand your skill set.\n* Learn and develop. We hold ourselves to high standards of technical and product excellence, offering opportunities to tackle new challenges and work with cutting-edge technologies.\n* Own your impact. We hire smart people and empower them—whether leading a project, optimizing processes, or building something entirely new.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1207, 709, 2, '[HN] JUNIOR DEVELOPER (ANY LANGUAGES)', 'Công nghệ\n\nTừ 01 năm kinh nghiệm\n\nLiên Hệ Ứng Tuyển Tại\ntuyendung@teky.edu.vn hoặc 02471096668\n\nThu nhập: 12.000.000đ - 16.000.000đ/tháng\nHạn nộp hồ sơ: 30.06.2023\nPhòng ban: Công nghệ\nThời gian làm: Fulltime\nKhu vực: Hà Nội\nSố lượng: 1\n\nGửi hồ sơ ứng tuyển\n\nThông tin công việc\n\nThời gian làm việc: 8h00 - 17h00, nghỉ trưa 1 tiếng. Làm việc từ thứ 2 tới hết sáng thứ 7 hàng tuần\nNơi làm việc:\nTeky Hội sở chính [Hà Nội]: Số B-TT01-51-53 Khu nhà ở Ngân Hà Vạn Phúc, phường Vạn Phúc, quận Hà Đông, TP Hà Nội\n\nMÔ TẢ CÔNG VIỆC\n\nSố lượng 02\n\nThiết kế và lập trình các tính năng cho sản phẩm EdTech sử dụng Python + Django/Ruby on Rails/PHP\nViết các đoạn code chất lượng: rõ ràng, dễ dàng bảo trì, tái sử dụng\nTham gia vào quá trình phân tích nghiệp vụ, thiết kế và phát triển các tính năng\nLiên tục tối ưu sản phẩm, xử lý lỗi và nâng cao độ ổn định của hệ thống, trải nghiệm người dùng\nXây dựng các thư viện, API dùng chung cho các sản phẩm\nLàm việc với các lập trình viên có kinh nghiệm, quản lý, thiết kế để xây dựng các sản phẩm\nĐịa điểm làm việc: Tầng 5, tòa MAC Plaza, số 10 Trần Phú, Hà Đông.\n\nGiới thiệu về team Hệ thống và Công nghệ \nTại TEKY, mọi hoạt động online/offline từ vận hành nội bộ (bán hàng, chăm sóc khách hàng, kế toán,..) cho đến quản lý học tập (lịch học, ôn bài, làm bài tập về nhà, tương tác với học sinh/phụ huynh) đều ứng dụng công nghệ bài bản, có hệ thống, và là tiêu chí bắt buộc mỗi nhân viên cần phải thành thạo. Team Hệ thống và Công nghệ là những người xây dựng, phát triển, vận hành các hệ thống; đảm bảo các hoạt động hàng ngày ở TEKY diễn ra hiệu quả nhất, mang lại trải nghiệm tốt nhất cho nhân sự nội bộ, phụ huynh và học sinh.\n\nYÊU CẦU CÔNG VIỆC\n\nTốt nghiệp Cao đẳng/Đại học hoặc cao hơn chuyên ngành Khoa học máy tính/Công nghệ thông tin/Hệ thống thông tin/Công nghệ phần mềm hoặc các chuyên ngành tương tự\nYêu thích lập trình, sáng tạo và thích giải quyết các vấn đề thách thức\nCó kinh nghiệm làm việc thực tế với một trong các Web framework phổ biến: Django, Ruby on Rails, Node.js, PHP,…\nCó hiểu biết vững vàng về các kiến thức nền tảng của khoa học máy tính: cấu trúc dữ liệu, thuật toán, cơ sở dữ liệu\nCó kinh nghiệm làm việc thực tế với hệ cơ sở quản trị dữ liệu: MySQL, PostgreSQL, MongoDB\nTư duy giải quyết vấn đề logic\nKinh nghiệm làm việc từ 1 năm trở lên\nQUYỀN LỢI ĐƯỢC HƯỞNG\nLương, thưởng theo năng lực: 12 – 16 triệu/tháng, hoặc có thể thỏa thuận theo năng lực\nĐược làm việc cùng đội ngũ số 1 Việt Nam trong mảng STEAM cho K12: nhân sự tại TEKY là những người đang tạo và dẫn dắt xu hướng STEAM cho K12 ở Việt Nam\nCon CBNV được học miễn phí các khóa học về công nghệ.\nLương tháng 13; thưởng hiệu quả kinh doanh theo quý, năm; thưởng lễ-tết theo quy định công ty\nĐược làm việc trong môi trường Giáo dục năng động, chuyên nghiệp, cơ sở vật chất hiện đại, giàu ý nghĩa xã hội.\nĐược hưởng đầy đủ các chế độ theo quy định của nhà nước (BHXH, BHYT, BHTN,…)\nĐược đi du lịch ít nhất 1 lần 1 năm, liên tục tham gia Teambuilding\nHưởng các chế độ khác ngoài lương theo định kỳ hoặc không định kỳ\n\nGửi hồ sơ ứng tuyển', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1208, 366, 2, 'Junior Frontend Engineer (ReactJS) - Naver Financial', 'About NAVER Corp and NAVER Vietnam:\nNAVER Corp\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\nNAVER Vietnam\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\nLearn more about us: https://navercorp.vn/\nYour daily tasks:\n- Develop and maintain Frontend services for NAVER Services\n- Implement Server-Side Rendering (SSR), CI/CD pipelines, and monitoring solutions\n- Collaborate closely with teams in Korea\nYour background:\n- 2+ years of experience with front-end languages (e.g., JavaScript or TypeScript).\n- 2+ years of experience with front-end frameworks, full-stack development, or API development.\n- Familiar with HTML and CSS\n- Understanding of design system and cross-browser compatibility.\n- Knowledge of web browser mechanisms and rendering processes\n- Experience with integration testing, debugging, or troubleshooting.\n- Self-motivated, proactive, honest, and a positive attitude towards teamwork.\nIt\'s a big plus if you:\n- Strong problem-solving and debugging skills.\n- Experience with Node.js and Next.js\n- Knowledge of Docker and Kubernetes\n- Experience in respecting and improving legacy code.\n- Experience working with Cloud Build, Cloud Deploy, and Github Actions.\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills.\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7.\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1209, 725, 2, 'Nhân viên Tester tiếng Anh', 'Mô tả công việc\n\n• Thực hiện test, phân tích lỗi, ghi nhận lỗi và báo cáo kết quả test của học viên đầu vào của trung tâm\n• Hiểu rõ và tư vấn lộ trình phù hợp cho học viên.\n\nKhác', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1210, 674, 2, 'Java Developer', 'Mô tả công việc\n\nWe are looking for an enthusiastic and eager Java Developer to join our growing team.\nThis is an excellent opportunity for individuals with a foundational understanding of software development principles who are keen to learn and build applications using the low-code platform.\nYou will work alongside experienced developers, contributing to the development and maintenance of our applications while gaining valuable hands-on experience.\n\nYêu cầu công việc\n\nBachelor\'s degree in Computer Science, Information Technology, or a related field\nBasic understanding of software development concepts and methodologies.\nPossesses knowledge and experience in Java programming\nStrong logical thinking and problem-solving skills.\nGood communication and teamwork skills.\nStrong analytical and problem-solving skills.\nFluency in English\n\nTại sao bạn yêu thích làm việc tại đây\n\nAttractive income package as negotiation\nGlobal and inclusive workplace with monthly cross-cultural events\nInternational exposure and career growth across global locations\nWork-life balance benefits supporting employee well-being\nPrivate health insurance with optional family coverage\nSummer vacation allowance\nSponsored training courses for personal growth\nComprehensive relocation package\n\nĐịa điểm làm việc\n\nHồ Chí Minh: Lô E3 Đ. Võ Chí Công, Quận 9\n\nThời gian làm việc\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hải Dương, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1211, 689, 2, 'Coders - AI Training [Remote]', 'Requirements\nSwift, Python, Java, Go, Verilog, Typescript, Javascript, C++, or C# coding experience required.\nThis is a great opportunity to supplement your income while looking for longer or more full-time work, all while contributing to the development of new AI models using your domain expertise!\nOur client has hired over 1,000 Braintrust talent and intends to hire hundreds more!\nMany Braintrust coders earn over $12,000 per month!\nYou’ll have the flexibility to work as much or as little as you choose - 20hrs/week is suggested, but not a limit. Start working in as little as 48 hours. Your final hourly rate will be chosen by Outlier AI and determined by your location.\nWhat to expect: If qualified, you’ll be invited to complete a brief questionnaire that takes 3-5 minutes. If you successfully pass the questionnaire, you’ll be approved and able to begin work ASAP.\nRequired qualifications:\nProficiency working one of the following languages: Swift, Python, Java, Go, Verilog, Typescript, Javascript, C++, or C#.\nComplete fluency in the English language is required. You should be able to describe code and abstract information in a clear way.\nPreferred qualifications:\nBachelor\'s and/or Master\'s degree in Computer Science or equivalent. Students are welcome.\nNote: Outlier AI is partnering with Remotasks for this opportunity.\nWhat You’ll Be Working On\nOur client has partnered with organizations to train AI large language models, helping cutting-edge generative AI models write better code.\nExample projects might include:\nEvaluating the quality of AI-generated code, including human-readable summaries of your rationale.\nSolve coding problems, writing functional and efficient code.\nOptimize code to run at maximum efficiency.\nWriting robust test cases to confirm code works efficiently and effectively.\nWriting human-readable summaries of coding problems.\nWriting explanations of how code can solve problems and evaluate various solution approaches.\nNo previous experience with AI necessary! You will receive detailed instructions on what is expected of you after you complete the application and verification process.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1212, 709, 2, '[HÀ NỘI] THỰC TẬP SINH/CỘNG TÁC VIÊN TESTER', 'Công nghệ\nTừ không yêu cầu kinh nghiệm\n\nLiên Hệ Ứng Tuyển Tại\ntuyendung@teky.edu.vn hoặc 02471096668\n\n- Thu nhập: 2.000.000đ - 5.000.000đ/tháng\n- Hạn nộp hồ sơ: 26.05.2023\n- Phòng ban: Công nghệ\n- Thời gian làm: Partime\n- Khu vực: Hà Nội\n- Số lượng: 2\n\n- Thời gian làm việc: Đăng ký tối thiểu 06 buổi/tuần. Sáng từ 8h00 -12h00, chiều từ 13h00-17h00. Nghỉ chiều thứ 7 và chủ nhật\n- Nơi làm việc:\n  - Teky Hội sở chính [Hà Nội]: Số B-TT01-51-53 Khu nhà ở Ngân Hà Vạn Phúc, phường Vạn Phúc, quận Hà Đông, TP Hà Nội\n  - Thực hiện manual test ứng dụng web và ứng dụng mobile\n  - Được đào tạo và áp dụng automated test vào công việc\n  - Các công việc khác theo sự phân công của quản lý.\n\nYêu Cầu\n- Cẩn thận, tỉ mỉ, chịu khó học hỏi \n- Biết sử dụng các câu lệnh SQL cơ bản\n- Làm việc tại văn phòng ít nhất 6 buổi/tuần.\n\nHỗ Trợ\n- Mức hỗ trợ: từ 2.000.000đ - 5.000.000đ/tháng tùy vào năng lực và đóng góp\n- Đối với các bạn đạt yêu cầu về kiến thức chuyên ngành và kỹ năng sẽ được hỗ trợ chi phí từ tháng đầu tiên.\n- Đối với các bạn cần đào tạo từ cơ bản: sau 1 tháng nếu đạt yêu cầu sẽ có hỗ trợ chi phí\n- Được hỗ trợ dấu thực tập\n- Được đào tạo, cầm tay chỉ việc\n- Cơ hội phát triển lên chính thức sau thời gian thực tập/cộng tác.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hanoi, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1213, 726, 2, 'TUYỂN DỤNG LẬP TRÌNH PHP', 'Mô tả công việc\n\n- Chịu trách nhiệm phát triển các ứng dụng phần mềm bằng cách sử dụng công nghệ PHP\n- Có khả năng đọc và hiểu các thông số kỹ thuật\n- Thực hiện ứng dụng phù hợp với những tiêu chuẩn chất lượng phần mềm đã thiết lập của công ty và thực hiện việc kiểm tra đơn vị\n- Tham gia thiết kế / code\n- Viết các thông số kỹ thuật với sự hỗ trợ từ kiến trúc sư kỹ thuật\n- Cải thiện chất lượng sản phẩm, tối ưu hóa tốc độ, hiệu năng của website\n\nĐại học', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1214, 727, 2, 'Cloud Engineer Intern (Data and Cloud focus)', 'Cloud Developer Intern\n\nAbout Us: Noventiq (Noventiq Holdings PLC) is a premier global provider of cutting-edge digital transformation and cybersecurity solutions, headquartered in London. We empower businesses to thrive in the digital age, connecting them with top-tier IT vendors and delivering our own innovative services and proprietary solutions.\n\nWhy Noventiq? Our success is driven by a robust three-dimensional strategy focused on expanding our market presence, diversifying our product portfolio, and enhancing our sales channels. Through strategic M&A activities, we are poised to capitalize on industry consolidation and achieve unprecedented growth. With a dynamic team of approximately 6,400 employees operating in around 60 countries, we have a significant footprint in regions with immense growth potential, including Latin America, EMEA, APAC, and a notable presence in India.\n\nYour Opportunity: Join a globally recognized organization, celebrated with multiple "Great Place to Work" awards. At Noventiq, your ideas matter. We foster an environment where innovation thrives and collaboration is a cornerstone. Be a part of our journey to drive digital transformation worldwide.\n\nReady to Make an Impact? If you\'re passionate about shaping the future of digital transformation and cybersecurity, we want you on our team. Join us and be a part of a global organization where your contributions are valued, and your potential is limitless. Join us today!\n\nNow we’re looking for Cloud Engineer Intern to bring your talent to Noventiq Vietnam. You’ll be a part of our Services Delivery team.\n\nWhat You’ll Do:\n- Creative, multi-tasking, self-motivated\n- Participation in delivering projects based on Microsoft on-premises services (Active Directory, Exchange Server), Microsoft 365 services, Microsoft Security and Azure cloud platform;\n- Writing project documentation and user\\admin guides;\n- Training sessions for customers.\n\nKnowledge And Skills:\n- Entry-level, 3rd/4th-year students or fresher to 6 months experience\n- Own basic knowledge in core IT principles and background/major in Computer Science\n- Good command of English (written and spoken)\n- Hands-on experience is a plus\n- Vietnam nationality only\n\nWhat We Offer:\n- Working time: Mond-Fri, flexible working time.\n- Allowance 4,000,000 VND/ month\n- Opportunity to be upgraded to Full-time employee\n- Get experience in cloud migration service\n- Learn and get Microsoft Azure certificates\n- Participate in Azure Cloud architecture design\n- Learn Microsoft 365 and Modern Workplace Service\n- Learn Microsoft on-premises services such as Active Directory, Exchange Server\n- On-the-job training and participation in practical projects\n- Opportunities to work with global colleagues from different cultures\n- Performance review and upgrade Full-time employee\n- Other activities: exciting engagement events, Training opportunities, etc.\n\nDon’t forget to include your CV and cover letter. We receive a lot of applications, but we try to notice each of our potential candidates.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1215, 723, 2, 'Tuyển lập trình viên Java tháng 4-2018', 'Vị trí: Lập trình viên Java\n\nMô Tả Công Việc\n\n– Tham gia xây dựng và phát triển hệ thống call center trên nền mã nguồn mở.\n\n– Phát triển các ứng dụng call center base Cloud.\n\n– Tham gia phát triển các giải pháp mobile voip.\n\n– Tham gia các dự án mới khác của công ty.\n\nYêu Cầu\n\n– Tốt nghiệp Đại học chuyên ngành CNTT, ĐTVT\n\n– Thành thạo ngôn ngữ lập trình Java, JavaScript, Jquery, PHP\n\n– Sử dụng tốt các hệ quản trị cơ sở dữ liệu như MYSQL, MSSQL.\n\n– Tinh thần trách nhiệm cao\n\n– Cẩn thận trong công việc\n\n– Tiếng Anh: Đọc tốt tài liệu chuyên ngành\n\n– Kinh nghiệm: 1 năm\n\nCác Phúc Lợi\n\n– Làm việc từ T2- T6.\n\n– Lương thưởng hấp dẫn: thỏa thuận theo năng lực\n\n– Được đóng BHYT, BHXH theo quy định của nhà nước\n\n– Được nghỉ mát hàng năm.\n\nThông Tin Liên Hệ\n\n– Gửi CV đến email: thuylt@nms.com.vn\n\n– Liên hệ trực tiếp: Công ty Dịch vụ di động thế hệ mới NMS. Tầng 3A, tòa Mỹ Đình Plaza, Số 138 Trần Bình, Hà Nội Ms. Thủy: Tel: 024 7300 8555 (ext 4000) – 01675033310\n\nThời hạn ứng tuyển: 30/06/2018', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1216, 691, 2, 'Software Engineer (Mobile)', 'What you will be doing:\n\nDevelop Hubble software solutions by studying the requirements, use-cases, and process flow to accomplish organization and engineering mission.\nWork with the team in formulating software architecture, technology stack, and innovative solutions.\nAssist in the execution of Hubble’s technical aspects specifically enhancement, implementation, and deployment of Hubble’s product and service.\nAnalyse technical feasibility of the software solution from the problem definition, technical requirements, and proposed solutions. Work closely with the product team to document and develop requirements, estimation of timeline, and work plans.\nAdhere to high quality software development principles, best-practices, design patterns, and code documentation. Research on new technologies, current state-of-the-art development tools and equipment, and opportunities for process improvement.\nAssist the management in developing and implementing new processes to increase productivity and effectiveness of the engineering team.\n\nWhat we need from you:\n\nProficient in English\nMinimum 1 year of software engineering experience building Web Front End or Mobile Applications.\nA passion and drive for learning technologies and applying them pragmatically\nOutstanding problem-solving skills and a solid grasp of object-oriented programming\nAn ability to contribute to a technical discussion and the openness to listen and learn from your peers.\nHave a good understanding of web frontend / mobile application architecture\nHave a good understanding of various software engineering design patterns\nExperience working on ReactJS / React Native applications.\nComfortable with working in a fast-paced environment and highly collaborative team to solve real business problems\nVersatility and enthusiasm to tackle new problems across the full-stack and to learn new frameworks as we continue to push technology forward\n\nAbout Hubble:\n\nHubble is a leading technology company focusing on the construction and engineering industry. We are on a mission to build the world’s first autonomous construction sites by automating and trading the 4M (Man, Machine, Material, Money) resources.\n\nOur solutions help digitise all your work processes, and connect all key project stakeholders - developers, consultants, fabricators, contractors, and facility managers - onto an all-in-one platform - The Hubble Platform.\n\nBuild faster and cheaper and with the highest quality and safety standards with Hubble’s impactful technologies. Let’s transform the way we build our cities for a better tomorrow. Today. Together. For generations to come.\n\nVisit us at www.hubble.build to learn more for #bettercitiesoftomorrow', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1217, 728, 2, 'HN - Junior Frontend Developer (19M)', '1. INTRODUCTION\n\n a. About Fetch:\n\n Our mission is to offer Vietnam’s most talented technologists a platform to connect with some of the world’s leading tech companies and build their expertise on a global scale. Over 4 years, Fetch has built a good reputation and is trusted by many Vietnamese and foreign companies; And Fetch will continue its good work to bridge the divide between the World and the Vietnam Tech sector.\n\n b. About Client:\n\n Our client has stood at the forefront of nurturing developer relationships and spearheading marketing efforts, ensuring tech products reach developers globally.\n\n Providing comprehensive support in developer relations and marketing for corporations, government bodies, and nonprofits, we\'ve partnered with over 250 esteemed entities such as Meta, Google, Mastercard, Intel, Nvidia, IBM, Circle, Polkadot, among others.\n\n With a network exceeding 300,000 developers, our client has pioneered the organization of hackathons, online contests, acceleration initiatives, gatherings, and marketing strategies for developers in more than 100 cities worldwide.\n\n 2. RESPONSIBILITIES\n\n Develop high-performance web applications.\n Analysis requirements and maintain technical documentation.\n Contribute ideas & solutions to the products.\n Write clear and maintainable code.\n Participate in all phases of the product development process including analyzing user requirements, designing system architecture, coding, testing and deployment.\n Build the front end for advanced user experience.\n Build reusable components/modules for websites with responsive design.\n Work with API endpoints or Socket for dynamic content updating.\n Ensure UI/UX of developed pages and software with near pixel-perfect design.\n Develop and optimize the front end UI to ensure the application is rendered consistently in cross-browser environments.\n Cooperate to connect front end software development with an expert backend team.\n\n 3. REQUIREMENT\n\n At least 2 years of experience working as a frontend developer.\n Proficient in the React ecosystem, including ReactJS, Redux, component-based architecture, and state management (e.g., Redux Toolkit, Context API).\n Familiar with functional programming concepts in JavaScript/TypeScript.\n Solid understanding of HTML5, CSS3, and preprocessors such as SASS/SCSS.\n Strong experience in building responsive, mobile-first UIs using CSS media queries and modern layout techniques (e.g., Flexbox, Grid).\n Hands-on experience integrating with RESTful APIs, and exposure to GraphQL or WebSocket is a plus.\n Understanding of cross-browser compatibility, accessibility, and frontend performance optimization is a bonus.\n Experience with version control systems like Git, and familiarity with tools such as Webpack, Vite, or ESLint is a plus.\n\n 4. WHY YOU‘LL LOVE WORKING HERE\n\n MacBook or high-end laptop for working.\n Attractive salary and annual salary review.\n Working in a professional, friendly, well-equipped environment both with foreigners and Vietnamese.\n With extensive on-the-job training, you will always have a chance to work with new emerging technologies.\n 12 days annual leave per year.\n 13th-month salary.\n Enjoy diversified activities:  Free snacks, Weekly and Monthly Team-building, Company trips, Play Games (PlayStation, Board games), and Play Sports (Football, Badminton...).\n\n 5. WORKING HOURS & LOCATION\n\n Working hours: From 9 AM - 6 PM, Monday to Friday.\n Location: \n + HN: 13th Floor, TTC Building - No.19, Duy Tan Street, Dich Vong Hau Ward, Cau Giay District, Hanoi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona capitalei Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1218, 729, 2, 'Thực tập sinh Web', 'Mô tả công việc\n\nJOB TITLE\n\nWeb/Mobile Intern\n\nJob Code: Intern - 01\n\nOBJECTIVE\n\nSavvycom is an international software development company specializing in mobile and web solutions. Our team is the combination of experienced IT consultants and experts from Germany and Vietnam.\n\nThis is an excellent opportunity for young and motivated developers to join an exciting company that is fast developing at presence in Vietnam. Your focus will be to work with our staffs in Vietnam, US, EU and Singapore in solution design, development and maintenance our mobile and web based systems.\n\nRESPONSIBILITY\n\n- Working in an international environment.\n- Participate in the software development project as an Internship member; be trained and implementing modules in the project, which directed by Project Manager.\n- Be trained on the software production process and quality management software.\n\nRequired Skills And Experience\n\nThe ideal candidate will demonstrate the following skill set:\n\n- Interested in programming. Have good background knowledge of Object Oriented Programming and Web programing.\n- Ability to use one or more popular programming languages such as: C++, Java, PHP, Python, Ruby or C#...\n- Agility - articulate - capable of good team work.\n- Ability to work independently - self directed as well with a team\n- Attitude to learn new and emerging technologies.\n- Ability to read / write documents in English.\n\nBenefits\n\n- Working in a young and professional environment.\n- Staying in a friendly and spiritual space (daily tea break, weekly sports time, monthly outdoor activity, teambuilding parties, internal events and quarterly/ annually holiday)\n- Obtain guidance and awareness of advanced technologies.\n- Receive benefits according to Savvycom’s internship regulations.\n- Working hours: At least 20 hours per week (Monday to Friday).\n\nWORKING LOCATION:\n\nHanoi: Floor 12, Viet A tower, Duy Tan Street, Cau Giay Dist, Hanoi\n\nHow To Apply\n\nLetters of interest and CVs in English should be sent electronically to Ms. Huong (job@savvycomsoftware.com).\n\nPlease indicate in the email subject “Application for - ”.\n\nOnly short-listed candidates will be invited for interviews.\n\nCONTACT INFORMATION\n\nHead Office in Hanoi: Floor 12, Viet A tower, Duy Tan Street, Cau Giay Dist, Hanoi\n\nHo Chi Minh Branch: Floor 1, 14B Ky Dong, Ward 9, Dist 3, HCMC\n\nEmail: job@savvycomsoftware.com\n\nWebsite: http://savvycomsoftware.com/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1219, 730, 2, 'Java Developer ~ $2500', 'JAVA DEVLOPER ~ $2500 - cơ hội nghề nghiệp tại Stringee\nChúng mình vẫn đang tìm kiếm những ứng viên tiềm năng tham gia vào đội ngũ phát triển sản phẩm:\n\nMô tả công việc:\n- Chịu trách nhiệm nghiên cứu & phát triển backend sử dụng ngôn ngữ/công nghệ: Java, MySQL, Redis, Memcached, Kafka, ElasticSearch, Docker, K8S,...\n- Thiết kế/lập trình các module, thiết kế giao tiếp cho hệ thống tải lớn hàng triệu người dùng (sử dụng cả Java).\n- Nghiên cứu sử dụng, chỉnh sửa các open source về VoIP, streaming phổ biến.\n- Chi tiết sẽ trao đổi cụ thể khi phỏng vấn.\n\nYêu cầu:\n- Thành thạo Java.\n- Nắm rất vững lập trình hướng đối tượng, Design Pattern.\n- Có kinh nghiệm về unit test và integration test.\n- Hiểu về lập trình đa luồng, non-blocking IO, xử lý bất đồng bộ,...\n- Đã từng làm việc với Socket, TCP/IP, các thư viện như SpringBoot, Netty, Apache MINA là lợi thế.\n- Đã từng làm việc với RabbitMQ, ActiveMQ, Kafka, Docker, K8S,... là lợi thế.\n- Có khả năng làm việc với Linux.\n\nChế độ đãi ngộ:\n- Lương từ $1000 - $2500 (phụ thuộc vào năng lực và kinh nghiệm của bạn, chúng tôi không bao giờ đãi ngộ thấp hơn khả năng của bạn).\n- Thưởng theo hiệu quả công việc (hoàn thành milestone, deadline, ...), thưởng năm, các dịp lễ tết.\n- Môi trường trẻ, năng động, sáng tạo, hỗ trợ tối đa sự phát triển và công việc của nhân viên.\n- Được đào tạo để thường xuyên nâng cao nghiệp vụ. Cơ hội được học hỏi, làm việc với công nghệ mới.\n- Được làm việc trong một môi trường chuyên nghiệp với các đối tác nước ngoài.\n- Được đóng bảo hiểm và các chế độ khác theo Luật lao động; khám sức khoẻ định kỳ hàng năm.\n- Được tham gia các câu lạc bộ thể thao: bóng đá, chạy bộ,…\n- Được tham dự các buổi đi chơi, dã ngoại, nghỉ mát,…\n\nHồ sơ:\n- CV bằng tiếng Việt hoặc tiếng Anh.\n\nLiên hệ:\n- Địa chỉ: Tầng 19, Leadvisors Tower, 643 Phạm Văn Đồng, Cổ Nhuế, Bắc Từ Liêm, Hà Nội.\n\n----------------------------------------------------------------\nGiới thiệu về Công ty:\n- Stringee là công ty công nghệ cung cấp nền tảng quản trị doanh nghiệp hợp nhất – Cogover, giúp số hóa toàn diện hoạt động quản trị và vận hành doanh nghiệp. Cogover ứng dụng công nghệ No-code/Low-code và AI, cho phép doanh nghiệp tự xây dựng và tùy chỉnh hệ thống qua thao tác kéo - thả và cấu hình đơn giản, mà không cần lập trình.\n- Hiện tại, Stringee cung cấp 3 bộ sản phẩm chính:\n\nQuản trị khách hàng: CRM, Service, CDP\nQuản trị nội bộ: HRM, Recruit, Marketing, Process, Site, Finance\nSố hóa giao tiếp: Communication APIs\n- Với hơn 3,000 doanh nghiệp sử dụng, 70 triệu người dùng cuối, và nhiều khách hàng lớn như Viettel, Mobifone, VNDIRECT, Techcombank, TPBank,... Stringee là một trong những nền tảng số Make in Vietnam tiên phong trong chuyển đổi số.\n- Stringee từng đạt giải Nhân tài Đất Việt 2018, Top 10 Sao Khuê 2023, và được Bộ TT&TT công nhận là Nền tảng số xuất sắc Make in Vietnam.\n- Giới thiệu kiến trúc ứng dụng 3 tầng của Cogover: www.youtube.com/cogover\n- Review văn phòng Stringee tại Hà Nội: www.youtube.com/vanphong\n- Tìm hiểu thêm tại website: cogover.com và stringee.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1220, 731, 2, 'Middle Java Developer', 'Duties & Responsibilities\n\n· Analyze business requirements, then prepare technical specifications and develop new systems or upgrade existing ones to meet business needs.\nSupport the team leader in analyzing technical aspects to propose optimal solutions, and assist colleagues in resolving technical issues to complete tasks/projects on time.\nInvestigate and resolve daily issues related to system functionalities and unexpected incidents to ensure timely handling.\nResponsible for performing unit tests for new features or enhancements within the assigned scope to ensure that developed modules meet business requirements.\nAssist users/team leaders in creating test scripts to fully cover all test cases.\n\nRequired Skills\n\nIT technical programming: at least 3 years.\nGood knowledge of an objective oriented language (Java)\nGood knowledge of web/application containers (Apache Tomcat, Jboss, IBM WebSphere ...) and web/application deployment.\nGood experience on SOAP, RESTful Web Services.\nGood skill at MS SQL Server programming (stored procedure, function, job, trigger, view).\nGood skill in database design, database management, particularly MS SQL.\nSolid understanding of the software development life cycle, Agile Scrum\nWorking knowledge of HTML5, CSS3, React, Flutter, and Javascript a plus\n\nEducation\n\nBachelor Degree in Computer Science/ Information Technology or equivalent;\n\nBenefits Provided:\n\nCompetitive salary and benefits\nWorking time: 8:30AM - 05:30PM, Monday – Friday;\n12 days of annual leave + 3 days of sick leave + 1 day of birthday per year\nParticipated in social insurance, unemployment insurance, health insurance and full policies according to the labor law;\n13th month salary & bonus policies, allowances at the Company;\nUNIT-Care health care insurance by level;\nSalary increases according to company regulations or unexpected salary raise in case of outstanding ability;\nProfessional and dynamic working environment, unlimited promotion opportunities;\nOpportunity to participate in many large projects in Vietnam & abroad;\nWork on the latest technology platform;\nJoin in company trip, teambuilding & community activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1221, 732, 2, 'Frontend Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nTechnologists at WorldQuant research, design, code, test and deploy firmwide platforms and tooling while working collaboratively with researchers. Our environment is relaxed yet intellectually driven. We seek people who think in code and are motivated by being around like-minded people.\n\nWhat You\'ll Do\n\n- Develop/Maintain internal web applications on cloud and on premise \n- Write well designed, testable code by using state of the art software development practices\n- Create website layout/user interface by using standard HTML/CSS practices\n- Create and maintain software documentation\n\nWhat You’ll Bring\n\n- Experience in HTML, CSS, JavaScript/TypeScript\n- Demonstrated experience developing scalable and robust software web applications\n- Experience with popular JavaScript libraries and tools such as React.js, jQuery, NPM\n- Expertise in Python web frameworks such as Django, Flask and others\n- Experience with CI/CD and version control systems\n- Experience with GCP\n- Working experience with SQL databases (MySQL, PostgreSQL)\n- A solid background in Unix/Linux environment\n- Excellent debugging and problem solving skills\n- Strong knowledge and understanding of algorithm and data structures\n- Finance experience is not required\n\nWhat We Offer\n\n- Competitive and attractive compensation package with clear career road-map – where you feel challenged every day\n- We offer a strong culture of learning and development: training courses, library, speakers, share and learn events\n- Learn from who sits next to you! Working in WQ you are surrounded by smart and talented people\n- Employee resources groups with strong diversity and inclusion culture\n- Premium Health Insurance and Employee Assistance Program\n- Generous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\n- Team building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\n- Annual company trip and occasional global conferences – opportunity to travel and connect with our global teams\n- Happy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1222, 705, 2, 'Frontend Developer (React.js)', 'Core Responsibilities\n\nCollaborate with the development team to discuss UI ideas and application requirements.\nReview application needs, identifying web-based user interactions.\nDevelop and implement responsive UI components using React concepts.\nWrite interface codes in JavaScript following React.js workflows.\nTroubleshoot and debug front-end code, improving performance and user experience.\nCreate and maintain front-end architecture supporting UI concepts.\nDocument application changes and updates.\nMaintain brand consistency throughout the design.\nImplement integration/unit tests to ensure reliable UI behavior.\n\nSkills & Qualifications\n\n3+ years of experience in React.js.\nProficiency in JavaScript, CSS, HTML, ES6, with solid fundamentals.\nKnowledgeable in data structures and algorithms.\nProficiency in front-end frameworks (React, Vue, TypeScript) and development models (MVC, MVVM), with an understanding of virtual DOM principles.\nExperience with Git version control and Node.js (for SSR implementations).\nStrong skills in front-end performance optimization.\nStrong problem-solving abilities, analytical thinking, and teamwork skills.\nFluent English communication.\nPreferably holds a Bachelor’s degree in IT, Computer Science, or related fields.\n\nBenefits\n\n100% salary during probation.\n5-day workweek, Monday to Friday (9 am–6 pm).\nFlat organization with open communication.\nFriendly, flexible working environment.\nCareer development opportunities, working alongside English-speaking developers.\n13th-month salary, insurance.\nAnnual team-building event with a ticket for one accompanying relative.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thôn Phú An, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1223, 720, 2, 'Software Engineer (willing to learn ServiceNow)', '🚀 We’re hiring: Junior Developer – Open to ServiceNow\n\n📍 Location: Hybrid – District 7, HCMC\n💼 Full-time | Entry-Level – Junior\n🌍 Join SCC – a UK-headquartered tech company delivering enterprise solutions across 5 countries\n\n⸻\n\n👨‍💻 About the opportunity:\n\nAre you passionate about solving business problems with technology?\n**Not experienced in ServiceNow yet? That’s OK.**\n**We’re looking for junior developers who are eager to learn and ready to transition into the world of ServiceNow – a leading enterprise automation platform used by global organizations.**\n\nThis is a rare chance to be trained, mentored and grow your career with real international projects.\n\n⸻\n\n🔧 What you’ll do (after onboarding & training):\n\n**• Learn to develop & configure ServiceNow applications (like ITSM, CMDB…)**\n• Build small integrations with guidance\n• Write scripts, create workflows, and customize UI components\n• Support troubleshooting & testing alongside senior developers\n• Work with Agile team to deliver features on time\n• Participate in code review and team discussions to improve continuously\n\n⸻\n\n🎯 We’re looking for someone who:\n\n**• Has basic coding experience (in JavaScript, Java, Python, or similar)**\n• Understands the software development life cycle\n**• Communicates well in English (written + spoken)**\n• Has a strong willingness to learn, explore new tools and ask good questions\n• Works proactively, not afraid of challenges\n• Can commit to long-term growth with us\n\n⸻\n\n💡 Bonus if you have:\n\n• Any internship or project related to web dev / automation / IT systems\n• Familiarity with Agile/Scrum or Jira\n• Awareness of what ServiceNow is (but again, not mandatory)\n\n⸻\n\n🌟 Why this is special:\n\n• Training & real-world exposure to ServiceNow – a high-demand, global platform\n• International working culture with UK, France & other EU teams\n• Hybrid working (Thu-Fri WFH) – no timesheet, no micromanagement\n• Full salary insurance, 13th month, performance bonus, and paid leave increases yearly\n\n⸻\n\n🟢 Interested but unsure? Let’s connect and see if this path is right for you.\nThis is your gateway to a high-demand, global tech career.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1224, 733, 2, 'Software Engineer (Java)', 'Intrepid Asia is a leading Ecommerce and Digital Solutions Provider in South East Asia. We offer end-to-end omni-channel ecommerce management, a wide range of Digital Marketing Services and advanced Market Intelligence, all powered by state of the art inhouse Technology to our client base of leading international brands across all key marketplaces and social platforms in all 6 SEA countries. Brands love our regional presence, our excellent data-driven and growth-focused services which are enabled by the strongest team in the industry, and our advanced marketing and tech capabilities.\n\nWe are growing rapidly and as the exclusive partner of Flywheel in SEA, we offer many exciting opportunities to work with leading brands across multiple categories and key industry players. By joining us, you will work on the cutting edge of digital commerce in SEA, and experience what it takes to drive a successful ecommerce business end to end.\n\nResponsibilities:\n- Engage with internal and external stakeholders to understand and deliver on their data related requirements and initiatives.\n- Lead the Identification, Design and Implementation of internal and external data process improvements and efficiencies.\n- Lead the architectural design for API integration and execution to third parties (WMS and ERP systems).\n- Manage, monitor and communicate on the status and resolution of issues relating to data integration, storage and transformation processes.\n- Evaluate and recommend technologies in the data ecosystem that support the enablement of business strategy and key business initiatives.\n\nWho we look for – the ideal profile:\n- At least 5 years experience of working in software, 3yrs+ experience knowledge of Java. \n- Strong experience in spring-boot, RESTful Web Services.\n- Experience with message queue systems: RabbitMQ, Kafka.\n- Experience with RDBMS, SQL, and object/relational mappings, dealing with large data (MySQL, Postgres...), NoSQL (MongoDB, Cassandra...)\n- Practical experience on one of Cloud Technologies (AWS, Google).\n\nBenefits:\n- Excellent and competitive compensation package.\n- Professional and open international working environment – culturally integrating the best of all cultures to take the best of each and ensure we build an energetic, commercial, and fun working atmosphere. \n- You are one of the pioneers of a new and cutting edge Intrepid product underpinned by strong tech. You have a key position in the Intrepid Insights team working on a unique product solving complex data challenges.\n- Ample opportunity for personal and professional development, both on the job and through regular training (Ecommerce topics, technical skills, soft skills, and leadership training) made available on our proprietary learning platform Intrepid University.\n- You will work with many brilliant co-workers who are movers and shakers of the industry, as well as with leading brand and ecosystem partners across all categories to shape their presence across all ecommerce platforms in the years to come, and will have a broad view on the latest developments in the South East Asian e-commerce ecosystem.\n\nCompany Benefit:\n- Competitive salary package with grow-up opportunities at startup speed.\n- 2 months probation with 100% of gross salary.\n- Up to 15 days off per year.\n- Working from home flexibly.\n- Annual Health check-up & Premium Healthcare Insurance.\n- Social, Health, and Unemployment Insurance based on full salary.\n- 2 performance reviews per year.\n- Team building monthly, company trip every year, 13th Salary.\n- On-the-job training and coaching with smart and friendly experts.\n- Union and other activities every month (8/3, 20/10, Mid-Autumn, Year-End Party, etc.).\n- Free tea, coffee, snacks for members every day.\n- Free Parking fee every month.\n\nNote: we will not be accepting any unsolicited resumes or CVs from headhunting or recruitment agencies at this point. Any CVs or profiles shared with us will not be entertained, and in the event of a dispute, Flywheel will not be liable for any material compensation to third parties.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1225, 734, 2, 'Java Web Developer', 'Make Our-Dreams Realized  MOR Software JSC.  MOR Software JSC is a company specializing in developing software products for the Japanese, Korean and American markets.  Currently, MOR has offices in the following cities: Tokyo (Japan), Ho Chi Minh, Hanoi and Da Nang. In addition, MOR is planning to open offices in Korea and the US.\nWebsite: https://morsoftware.com//  + MOR-HN (MH) is the "core" branch of MOR software with more than 250 employees, starting operations in October 2018. We always want to create a young, dynamic environment and constantly encourage employees to develop themselves.\nHanoi Office: 25F - B1 building, Roman Plaza, To Huu, Nam Tu Liem, Ha Noi\nPosition: Middle Java Developer  Job Description  • Develop and implement new features and functionalities • Collaborate with the team to ensure high-quality deliverables. • Participate in code reviews and design discussions. • Work closely with QA to ensure the quality of the code. • Ensure compliance with company policies, procedures, and quality standards throughout the project lifecycle.\nRequirements:\nMust Have: • Good communication skills in English. • Strong knowledge of Object-Oriented Programming (OOP). • Hands-on experience with: • Java 17+ and Spring Framework (Spring Boot, Spring Data, Spring Security…) • RESTful APIs • Docker • Relational Databases (e.g., MySQL, PostgreSQL) • Microservices architecture • Message brokers such as Kafka or RabbitMQ\nNice to Have: • Experience with cloud platforms: AWS, Azure, or Google Cloud. • Knowledge or practical experience in applying AI to work (e.g., recommendation systems, prediction models, automation…). • Experience with: • Jenkins (CI/CD) • NoSQL databases such as DynamoDB or MongoDB\nBenefits:\n• Salary: Negotiable based on qualifications/abilities. • Full salary in the probation time • Bonus 13th month salary, performance bonus, holiday bonus,... • Annual performance review, twice/ year • Sponsor exam and study costs for some professional certificates. • Opportunity to work and short/long training abroad • Learning encouragement fund: Japanese and English training courses held at the company, professional training courses, Udemy courses,... • Take part in playing football, badminton team, board game team • Opportunity to work in a young, dynamic, friendly, professional environment with a clear, fast, fully equipped process system. • Work directly with foreign customers, experienced members such as BA, Technical Team, PQA,… • Enjoy full benefits according to the provisions of the Labor Law. • Premium healthcare insurance (VBI) annually.\nMore information:\n• Company Address: 25th Floor, Tower B1, Roman Plaza, To Huu Street, Nam Tu Liem District, Hanoi. • Working Hours: 8:30 AM – 5:30 PM, Monday to Friday.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1226, 735, 2, 'Java Software Engineer', 'RESPONSIBILITIES\n\nPlan, develop, and maintain web and mobile apps supporting our products in the entertainment industry for massive user traffic in the APAC market.\nDesign and optimize backend systems for high-performance gaming applications.\nBuild and maintain APIs for seamless frontend-backend communication.\nEnsure system security and scalability for large-scale web systems.\nCollaborate with game designers and developers to deliver high-quality products.\nStay updated on core technologies and suggest improvements.\nResearch and apply new technologies to enhance products.\n\nREQUIREMENTS\n\nAt least 3 years of experience with Java.\nDevelop backend server systems effectively.\nUnderstand and implement algorithms and assess algorithm complexity.\nEnsure security for large web systems.\nHandle Protobuf and gRPC for microservices communication.\nUse GIT for version control.\nWork well both independently and in a team.\nAdapt to high-pressure environments.\nFamiliarity with Spring Boot.\n\nPreferable:\n\nWork with messaging systems: Kafka, RabbitMQ, ZeroMQ.\nUse Docker and Kubernetes for containerization and deployment.\nHave a good product mindset focused on user experience.\nKnowledge and working in caching.\nKnowledge about design patterns.\n\nBENEFITS\n\nCompetitive market-based salary.\nFull salary during the probation period.\nBe equipped with full working equipment (Macbook Pro).\n13th-month salary, year-end bonus, project-based incentives, and annual salary review.\nComprehensive healthcare program for all employees.\nHealth insurance coverage for employees and their dependents.\nAnnual company trips and team-building activities.\nDynamic and vibrant work environment with diverse clubs and engaging events, including Happy Monday Lunch, Happy Hour, birthday celebrations, and more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1227, 736, 2, 'Giảng Viên Khoá Học AI For Work(Prompter) Parttime', 'Mô Tả Công Việc\n- Truyền đạt kiến thức, kỹ năng về Prompt Engineering và ứng dụng AI trong công việc cho học viên với đa dạng đối tượng; đảm bảo học viên nắm vững kiến thức, vận dụng thành thạo các công cụ AI để tối ưu hiệu suất làm việc.\n- Giảng dạy kỹ thuật Prompt hiệu quả: cấu trúc prompt, few-shot prompt, least to most, prompt chaining, system prompt, mega prompt.\n- Giải thích và ứng dụng các framework giải quyết vấn đề với AI như cause-and-effect diagram, 5Whys, PDCA…\n- Hướng dẫn học viên sử dụng AI trong quản lý thời gian, thuyết trình, soạn email, ghi chú cuộc họp, tìm kiếm tổng hợp thông tin, xây dựng lộ trình học tập.\n- Giới thiệu, so sánh, hướng dẫn sử dụng công cụ AI như Google AI Studio, Perplexity, NotebookLM, ChatGPT, Fireflies, Google Calendar, Poe.\n\nYêu Cầu Ứng Viên\n- Am hiểu sâu sắc về Prompt Engineering và các kỹ thuật liên quan.\n- Thành thạo sử dụng các công cụ AI hiện đại, biết ưu nhược điểm và cách kết hợp các công cụ.\n- Có kinh nghiệm ứng dụng AI trong quản lý dự án, tối ưu hiệu suất công việc là lợi thế.\n- Kỹ năng giảng dạy, truyền đạt dễ hiểu, phù hợp với học viên đa dạng từ sinh viên đến người đi làm trung tuổi.\n- Tư duy phân tích, logic, sáng tạo, có tinh thần học hỏi và cập nhật kiến thức mới.\n- Ưu tiên có kinh nghiệm giảng dạy hoặc đào tạo về công nghệ số, AI hoặc lĩnh vực liên quan.\n\nQuyền Lợi Ứng Viên\n- Mức lương 600.000đ - 1.200.000đ/ buổi(3 tiếng, tùy level đảm nhận) + thưởng tùy vào năng lực.\n- Ưu đãi tham gia các khóa học của MindX (Global developer, AI, Product Manager...)\n- Đối với GV , được đăng ký vào danh sách Ứng viên tiềm năng của MindX Jobs, và được nhận các quyền lợi về thông tin việc làm chất lượng cao từ hệ thống đối tác doanh nghiệp trong nước và quốc tế của MindX Jobs\n- Cơ hội tạo ra sức ảnh hưởng, truyền cảm hứng cho các bạn trẻ về những công nghệ mới nhất\n- Cơ hội lựa chọn những học viên sáng giá về với đội của mình\n- Mở rộng mối quan hệ, giao lưu và học hỏi với mạng lưới founders, giảng viên, alumni hiện đang làm việc trong các lĩnh vực khoa học máy tính, phân tích dữ liệu, PM, UI-UX Design, v.v. ở các tập đoàn, công ty công nghệ hàng đầu thế giới\n- Được sử dụng không gian làm việc miễn phí tại MindX Space tại HN và TP. HCM\n- Review lương liên tục theo khả năng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi i okolice', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1228, 737, 2, 'Java Developer', 'Summary \nJoin Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia\'s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nJob Description\nAt Aperia, we rely on a dynamic team of developers. We\'re seeking a Java Developer who is ready to work on Back-end development. You will participate as part of the Service team and within the larger application team. You will participate in the analysis and estimation of work, develop and unit test your code, coordinate with front end service developers, Data warehouse team and our quality testers.\n\nCore Responsibilities\n• Design, develop, and maintain high-performance backend services using Java and related frameworks. \n• Build and maintain RESTful APIs using standard best practices and scalable design. \n• Produce well-structured, testable, and efficient code using core software development principles. \n• Troubleshoot complex server-side issues with strong debugging and problem-solving skills. \n• Create and maintain unit tests using JUnit and support automated testing in CI/CD pipelines. \n• Collaborate closely with cross-functional teams including frontend developers, QA, and data teams to align development efforts. \n• Refine and clarify technical requirements and contribute to technical design discussions. \n• Participate in Agile processes including sprint planning, estimation, code reviews, and retrospectives. \n• Integrate data from various backend services and databases while ensuring secure, reliable data handling.\n\nTechnical Skills:\n• Good English communication in both verbal and written.\n• Minimum 5 years\' experience in Java server-side development, including design and debugging of enterprise applications. \n• Proficiency in Core Java, J2EE, Kafka, Microservices and RESTful API development. \n• Solid experience with servlets, multithreading, and server-side architectural patterns. \n• Hands-on experience with Swagger or similar API documentation tools. \n• Strong SQL skills and experience writing and optimizing database queries. \n• Proven experience with JUnit and test-driven development. \n• Experience working in CI/CD environments using modern DevOps tools and practices.\n\nThings that will separate you from the rest:\n• Familiar with React, TypeScript or JavaScript.\n• Experience in the Fintech industry or enterprise-level financial applications. \n• Familiarity with internal tools such as Clarity or similar portfolio/project management applications. \n• Exposure to modern Java versions (8, 11, 17) and their advanced features. \n• Experience with cloud migration or cloud-native development (AWS, Azure preferred). \n• Familiarity with front-end frameworks such as React, and experience with CSS/HTML. \n• Basic knowledge of Python for scripting or data integration.\n\nEducation or Certifications\n• Bachelor\'s degree in computer science, related technical degree\n\nJob Type\n• Full-Time\n\nSchedule\n• Monday to Friday\n\nWork Location \n• The Six8 Building: 24-26 Phan Dinh Giot, Tan Binh District, HCMC\n• VDB Tower: 74 Quang Trung, Hai Chau, Danang\n\nBenefits\n• Health insurance \n• Dental insurance\n• Paid time off\n• Parental leave\n• Childcare assistance\n\nThis job description is not intended to be all-inclusive. An employee may also perform other reasonable related business duties as assigned by their immediate supervisor or management. Principals only.\nRecruiters please don\'t contact this job poster. DO NOT contact us with unsolicited services or offers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1229, 738, 2, 'FULLSTACK DEVELOPER EXECUTIVE', '🚀 JOB DESCRIPTION\nYou will work with us to build websites with millions of views per month for well-known brands around in Vietnam.\nYour main responsibilities include:\nTurn designs into responsive, functional, and accessible HTML / CSS / JavaScript, and liquid code on Shopify\nLearn AI and approach to ensure best practices in terms of accessibility, performance, and code standard\nWork with technical manager to research and stay on top of front-end web development best practices\nParticipate in R&D, training, knowledge sharing activities\nStrictly follow the project and organization processes, policies and regulations\nEnsure the assigned tasks to be performed on-time and with high quality\n\n✅ JOB REQUIREMENTS \nBachelor degree in computer science or equivalent\nAt least 2 years of working experience in CSS, HTML5 and Java-script, liquid, Nextjs\nHave 3+ year knowledge on backend with Nodejs, Python, PHP\nAble to quickly learn new technologies and Shopify\nGood time management, communication, problem solving skills\nProactive, well self-organized and responsible in work\nGood teamwork spirit\nGood logical thinking\nExperience in Object Oriented Programming (OOP)\nBasic data structure and algorithms\nDatabase: SQL, NoSQL, Cache\nLinux, Monitoring, Analyzing, DB Transaction, DB Backup\nGood understanding of design patterns and architectures\nGood understanding of database design in SQL and NoSQL\nWrite well designed, testable, efficient code by using best software development practices\nEnterprise integration (wider than REST APIs – Graphql)\nProficient understanding of Git\nFamiliarity with Automation workflow is a plus\nFamiliarity with Microservices is a plus\nKnowledge in Open API Specifications/ Swagger is a plus\nGood knowledge of software development life cycle models and process (SCRUM)\n\n🎯WORK LOCATION: 204 Vo Thanh Trang, Ward 11, Tan Binh District, HCMC\n🎯APPLY AT: tuyendung@shondoshoes.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tân Bình, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1230, 739, 2, 'Junior Developer (Javascript & HTML)', 'Company Description\n\nThe SOCOTEC Group offers its customers and partners missions throughout the life cycle of infrastructure and buildings to ensure compliance, extend their lifespan, improve their technical, energy and environmental performance, and thus guarantee the safety of people. Independent trusted third party and with offices in 26 countries and more than 11,300 people.\n\nSOCOTEC is a leading player in risk management and technical advice in the world. Established in Vietnam since 2018, SOCOTEC Vietnam works closely with colleagues in France, Germany, Italy, UK, USA, Spain, Netherlands and other SOCOTEC offices. For our office in Hanoi, we are looking immediately for a Technical Reporting Engineer\n\nJob Description\n\n• Design and develop custom worksheets, reports, and workflows using JavaScript and XML, with guidance from the Team. \n• Troubleshoot and resolve technical issues in applications, including configuration and deployment support. \n• Collaborate with cross-functional teams to translate business needs into data-driven solutions. \n• Learn and adapt to SpectraQEST and other enterprise systems (training provided). \n• Contribute to projects that integrate with wider infrastructure (networks, OS, etc.)\n• Receive mentorship to expand your skills in database design, SQL scripting, and future full stack development.\n\nQualifications\n\n• Degree in Computer Science, IT, or related field or equivalent hands-on experience (e.g., coding bootcamps, personal projects). \n• 1+ years of hands-on experience with JavaScript and XML\n• Basic understanding of SQL (querying, data extraction) and relational databases\n• Strong logical reasoning and ability to translate requirements into functional code. \n• Exposure to backend development or data-driven applications is an advantage\n• Familiarity with network/infrastructure basics (OS, APIs, etc.) is an advantage\n• Eagerness to learn enterprise systems like SpectraQEST (no prior experience needed)\n• Problem-solving mindset with a focus on teamwork and collaboration. \n• Ability to work independently on tasks while staying aligned with team goals.\n\nAdditional Information\n\n• Attractive salary and bonus with annual revision\n• Compulsory insurance pay as gross monthly salary\n• Flexible working time with 12 annual leave days & 15 work from home days\n• Team-building activities, Sport Clubs\n• Cooperation with colleagues around the world in a leading global group\n• Strong team spirit in an entrepreneurial environment of a growing company\n• People values, social responsibility and sustainability\n• Opportunities for self-development and career advancement\n• Internal training courses (technical, foreign language, soft skill)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đình Ba, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1231, 740, 2, 'Java Developer', 'Job Description\n\n- Work in a team of engineers to implement backend services in the platform\n- Build service definitions, OpenAPI specifications, SDKs, and documentation for other developers that consume these services\n- Integrate with other services and data sources using APIs, messaging systems, databases\n- Collaborate with the DevOps team on microservices design, containerization, and automated deployments\n- Build automated test suites to ensure these services are reliable and performant\n\nRequirements\n\n- Experience working with Java and one or more Java frameworks such as Spring Boot\n- Project experience around web service design and RESTful APIs\n- Expertise with the OpenAPI Specification (Swagger), RESTful APIs, and related tools such as Postman, cURL, and HTTPie\n- Experience integrating with 3rd party services and databases such as Redis, message queues, MongoDB, and ElasticSearch\n- Agile/SCRUM methodology experience\n- English is a must\n- Prefer Senior/Leader candidates\n\nJob Benefits\n\n- Salary: Negotiable\n- Performance review: 2 times/year\n- 14th-month salary bonus\n- KPI bonus based on project and performance\n- Extra package: 16 Mil /employee/year (Bonus at Tet, New Year, your birthday, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, …)\n- Opportunity to work in a professional, modern, and dynamic environment, take part in international projects\n- Opportunity to get on-job training and promotion\n- An excellent corporate culture with in/out of office activities that help to develop staffs ability and creativity\n- CMC health care and social insurance\n- Onsite opportunities: short-term and long-term assignments in US, EU,… (members of GEU/US).\n\n2+ years of experience\n\n- Please send your application via email: recruitment@cmcglobal.vn\n- Years of Experience Required\n- Required Education Level\n\nBachelor’s Degree\n\nJob Level\n\nMiddle/Senior\n\nWork Form\n\nFull-time\n\nEmail: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1232, 741, 2, 'Fresher Business Development (Software Service)', '1. Job Description: \n- Market research and participate in building marketing strategies.\n- Search for potential customers through marketing tools such as: Email, LinkedIn, Appolo.io...\n- Build and develop relationships with potential customers.\n- Set up meetings between (potential) customers with Sales Lead and Sales Partner\n- Report weekly and monthly work according to company regulations\n- Other tasks assigned by the Department Head.\n- Job details will be discussed during the interview.\n- Other tasks as required.\n\n2. Benefits and working environment:\n- Attractive salary package: Base Salary (7-8M net) + Quarterly Project Bonus + Commision\n- Package: 13 - 14 months salary per year \n- 100% salary paid during probation \n- Salary review twice a year \n- Work with great potential IT projects and programs (from US, UK, AU,...)\n- Professional working environments with young, enthusiastic and motivated teams \n- Join all the insurance regimes under the provision of the Labor Law \n- Other team building activities: Annual company trip, quarterly team building, happy hour, sport club, charity activities, etc. \n- Free entertainment parties: Birthday party, Anniversary party, Sum-up Party, Year-End Party, etc\n\n3. Qualifications:\n- Good in English (equivalent to IELTS 5.5 or above)\n- At least 1 year experience in Sales\n- Graduated from Universities (priority given to Universities majoring in Sales, Marketing)\n- Excellent knowledge in MS Office, Email, Outlook\n- Proficient in using marketing tools\n- Skilled in researching documents and social media platforms\n- Responsible for work, ability to work independently, able to withstand pressure\n- Agile, able to analyze and solve problems well.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1233, 366, 2, 'Junior Frontend Engineer (ReactJS) - Naver Financial', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nYour daily tasks:\n\n- Develop and maintain Frontend services for NAVER Services\n- Implement Server-Side Rendering (SSR), CI/CD pipelines, and monitoring solutions\n- Collaborate closely with teams in Korea\n\nYour background:\n\n- 2+ years of experience with front-end languages (e.g., JavaScript or TypeScript).\n- 2+ years of experience with front-end frameworks, full-stack development, or API development.\n- Familiar with HTML and CSS\n- Understanding of design system and cross-browser compatibility.\n- Knowledge of web browser mechanisms and rendering processes\n- Experience with integration testing, debugging, or troubleshooting.\n- Self-motivated, proactive, honest, and a positive attitude towards teamwork\n\nIt\'s a big plus if you:\n\n- Strong problem-solving and debugging skills.\n- Experience with Node.js and Next.js\n- Knowledge of Docker and Kubernetes\n- Experience in respecting and improving legacy code.\n- Experience working with Cloud Build, Cloud Deploy, and Github Actions.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1234, 742, 2, 'Fresher Mobile (React Native) Engineer', 'Company Description\n\nKMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines:\n\n- KMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions.\n- KMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality.\n- KMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors.\n\nJob Description\n\nYour key responsibilities:\n\n- Develop, and maintain high-quality React Native applications using clean code.\n- Working on mobile frameworks\n- Integration between cross environments - web and mobile\n- Implement pixel-perfect user interfaces that match designs.\n- Diagnose and repair bugs and performance bottlenecks for native-like performance\n- Work closely with the project team on daily tasks and participate in sprint demo meetings with clients\n- Communicate and report internally or directly to client on status or result of work.\n\nQualifications\n\nQualifications:\n\n- Bachelor’s degree in Information Technology, Computer Science, Software Engineering, or a related field.\n- Strong IT background with a GPA of 8+ (Please attach transcripts when submitting your CV).\n- At least intermediate or higher English proficiency (both written and verbal).\n- Minimum 6-month internship experience in software engineer is required.\n- Strong self-learning ability with a proactive, growth-oriented mindset.\n- Excellent analytical and problem-solving skills.\n- Ability to work independently and collaborate effectively in a team.\n\nTechnical requirements:\n\n- Passion for Mobile Applications Development using React Native\n- Knowledge with JavaScript frameworks/libraries that are more powerful than jQuery (e.g. ReactJS/Angular)\n- Strong fundamental knowledge of Web/Mobile application development, OOP, data structure, and algorithms\n- Have a good understanding of projects being done in university or during the internship\n- Basic knowledge in writing unit tests\n\nAdditional Information\n\nPerks You\'ll Enjoy \n\n- Working in one of the Best Places to Work in Vietnam\n- Building large-scale & global software products\n- Working & growing with Passionate & Talented Team\n- Diverse careers opportunities with Software Outsourcing, Software Product Development, IT Solutions & Consulting\n- Attractive Salary and Benefits\n- Performance appraisal twice a year and performance bonus\n- Onsite opportunities: short-term and long-term assignments in North American (U.S, Canada), Europe, Asia\n- Flexible working time\n- Various training on hot-trend technologies, best practices and soft skills\n- Premium healthcare insurance for you and your loved ones\n- Company trip, big annual year-end party every year, team building, etc.\n- Fitness & sport activities: football, tennis, table-tennis, badminton, yoga, swimming…\n- Joining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,…\n- Free in-house entertainment facilities (foosball, ping pong, gym…), coffee, and snack (instant noodles, cookies, candies…)\n\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1235, 679, 2, 'HCM – Junior Back-end Developer (NodeJS) – Hybrid Working', 'Junior Back-end Developer (NodeJS)\n\nHybrid Working\n\n“For millions of Vietnamese people never have to queue to buy ticket…again” – Van Tran – CEO\n\nVexere is a technology company aiming to revolutionize the travel and transportation industry in Vietnam. We are pioneering in comprehensive digital transformation of the transport industry with diverse web applications and latest technology apps. We are available on all super apps such as Grab, Momo, Zalopay … We have all types of tickets from low-priced to luxury cars. Today Vexere is the largest online inter-city bus ticketing platform that empowers millions of travelers to make their life journeys happier.\n\nWant to build a large-scale system with hundreds of thousands of concurrent users?\n\nWant to build an enterprise solution that could adapt to complex requirements from thousands of bus companies?\n\nCome to us to build microservices ecosystem on latest technologies such as kubernetes, itsio service mesh, mirroring or shadowing traffic, event sourcing, domain driven design, test automation, CI/CD … Each service has its own monitoring system to measure several performance metrics such as API response time, caching time, cache hit/miss ratio, database hit rate… We are proud to be one of the few companies in Vietnam that follow the path of a full CI/CD system architecture with dedicated senior devops engineer to make the life of developer much easier. You are free to build and do experience on millions of users without worries.\n\nSome of our high performance services are also built with Golang.\n\nWorking location: Floor 2 Circo Hoang Dieu – 384 Hoang Dieu, Ward 6, District 4, HCMC\n\nBenefits:\nAttractive compensation package\nWe can offer over this rank depending on your interview performance\nQuarterly bonus\n100% salary on your probation period\n13th salary\nPerformance review 2 times/ year\n1 day working remotely/week\nOpportuinities to be lead by top CTOs, architects and leaders at Vexere\nCompany will plan and help you to build publish profile by publishing posts in medium.com and Vexere techblog under your name, being contributor in opensource projects managed by our company, tech talks\nAttractive stock option for hard-core developer/lead\n30% discount for Vexere members and 10% for their family/relatives when buying bus tickets to travel within Vietnam\nCompany trips, Teambuilding, Year-end party, and other festivities\nResponsibilities:\nPart of backend team to convert existing monolithic system to micro-services architecture\nBeing a part of a Product team, your work will be solving business requirements by designing solutions and shipping codes with quality.\nBeing a member of the Backend Squad, you will be proactively analyzing things like technical debts and challenges to be improved and making changes. Learn and share within Backend Squad to maximize knowledge of your team as well as yours.\nLead backend team or a product if capable\nRequirements:\nAt least one year of real work experience with NodeJS\nFamiliar with ES6 and later\nFamiliar with linting, static type checker such as flow or TypeScript\nBeing serious about code quality, experience in doing code review, familiar with unit testing\nHave strong background in computer science and good understanding of data structures, algorithms and design patterns\nGrow mindset: as our company grows 3 to 5 times a year, as a member you have no choice but to grow at least 3 times a year\nPlus:\nFamiliar with deployment, scaling, monitoring and performance tuning\nFamiliar with micro-service web architecture, docker deployment\nFamiliar with Agile Process and Scrum Methodologies\nHaving public profiles at GitHub/IT blogs\n\nFor More Information, Please Contact Us Via\n\nSend your CV to Email: careers@vexere.com\nZalo 0989 036 781 – Mr. Hoa Dang Khoa', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1236, 715, 2, 'Kỹ sư Phát triển phần mềm (Software Engineer)', 'MÔ TẢ CÔNG VIỆC:\nLập trình mã nguồn nghiệp vụ theo yêu cầu người dùng, yêu cầu hệ thống, thiết kế chi tiết ở mức tính năng.\nLập trình giao diện theo thiết kế giao diện có sẵn.\nPhối hợp các thành viên khác trong nhóm tích hợp các tính năng hệ thống.\nPhối hợp với bộ phận quản lý chất lượng đảm bảo chất lượng hệ thống.\n\nYÊU CẦU:\n\nBắt Buộc\nTốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Toán – tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\nTrình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\nCó kiến thức cơ bản về lập trình và khả năng sử dụng ít nhất 1 ngôn ngữ lập trình (C/C++/Java/Android/iOS/Golang/React.JS).\nCó kiến thức cơ bản về công nghệ thông tin, ngôn ngữ mô hình hóa UML; quy trình phát triển phần mềm và toàn bộ vòng đời ứng dụng; mạng máy tính (các loại mạng, kiến trúc mạng, lập trình mạng, giao thức); ngôn ngữ truy vấn dữ liệu SQL, làm việc với hệ quản trị cơ sở dữ liệu, cấu trúc dữ liệu và giải thuật.\n\nƯu Tiên\nThạc sỹ, Tiến sỹ các chuyên ngành liên quan đã có quá trình nghiên cứu tại các quốc gia phát triển trên thế giới.\nỨng viên đã có kinh nghiệm đảm nhận vị trí tương đương tại các công ty, tổ chức uy tín trong nước hoặc thế giới.\n\nCHẾ ĐỘ ĐÃI NGỘ:\nĐược hưởng các khoản quà, thưởng lễ tết, nghỉ mát hỗ trợ ăn trưa, điện thoại liên lạc tối thiểu 2.000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\nĐược hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\nĐược hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\nĐược trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\nCó cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\nĐược cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\nCó cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.\nMức lương cạnh tranh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1237, 743, 2, '[LTS] Thực tập sinh Training Automation-Manual Tester', 'Vị trí tuyển dụng : Intern Tester\n\nSố lương : 10\n\nLoại hình : Full-time\n\nĐịa điểm làm việc : Hà Nội.\n\nMÔ TẢ CÔNG VIỆC\n\n- Tham gia khóa training kiểm thử 3 tháng, test automation (2 tháng) + manual test (1 tháng) các phần mềm, hệ thống phần mềm. Cụ thể hơn:\n- Viết Testcases + sử dụng tool automation test để tạo scripts automation test\n- Thực hiện test các sản phẩm, dịch vụ theo yêu cầu.\n- Nghiên cứu và cập nhật các công cụ test và kiến thức mới hỗ trợ cho công việc.\n- Làm việc nhóm hoặc độc lập, giao tiếp với cấp trên và thành viên liên quan đến công việc test.\n\nYÊU CẦU\n\n- Sinh viên đã tốt nghiệp các trường ĐH chuyên ngành công nghệ thông tin, yêu thích lâp trình.\n- Ưu tiên ứng viên có background học các ngành liên quan đến IT\n- Có khả năng sử dụng tiếng anh là một lợi thế LỚN\n- Có khả năng làm việc nhóm, luôn sẵn sàng hỗ trợ các thành viên khác trong dự án\n\nQUYỀN LỢI\n\n- Được tham gia khóa đào tạo Automation và Manual Testing (3 tháng) miễn phí.\n- Nhận trợ cấp 3M hàng tháng hấp dẫn.\n- Có cơ hội trở thành nhân viên chính thức\n- Được tham gia vào các dự án lớn của công ty domain Banking\n- Được làm việc với những cá nhân xuất sắc, có nhiều kinh nghiệm.\n- Được hưởng Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n- Môi trường làm việc năng động, các hoạt động: Teambuilding, bóng đá, du lịch hàng năm…\n- Khám sức khỏe định kỳ 1 năm/1 lần\n\nCONTACT\n\nLTS Recruitment Department\n\n- Phone Number: 02466607474\n- Email: hr@ltsgroup.tech/ lts.rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi', 'Internship', '2025-10-07 20:59:18.149534'),
	(1238, 744, 2, 'Data Engineer Intern', 'About the Role:\n\nWe are seeking a motivated and detail-oriented Data Engineer Intern to join our dynamic team. In this role, you will contribute to the development and optimization of our data infrastructure, focusing on automation, scalability, and efficiency. This internship offers an excellent opportunity to gain hands-on experience in web scraping, automation, and data engineering within a cutting-edge tech environment.\n\nResponsibilities:\n\n- Conduct research and develop efficient web scraping tools to gather and process data from various online sources.\n- Collaborate with the team to create and maintain automation processes using Python and APIs within an AWS environment.\n- Assist in the identification and resolution of potential bottlenecks in data workflows.\n- Support the design and implementation of internal process improvements, including:\n  - Redesigning data infrastructure to enhance scalability.\n  - Optimizing data delivery pipelines.\n  - Automating manual processes to improve operational efficiency.\n\nRequirements:\n\n- Basic understanding of web scraping techniques and tools, with a passion for data-driven solutions.\n- Fluent English.\n- Familiarity with Python programming for data manipulation and automation tasks.\n- Enthusiasm for working in cloud-based environments, such as AWS.\n- Strong analytical skills and a proactive approach to solving technical challenges.\n- Nice to Have:\n  - Exposure to data engineering tools or pipelines.\n\nWhat We Offer:\n\n- Hands-on experience in a fast-paced tech environment with mentorship from industry professionals.\n- Opportunities to work on impactful projects that shape the future of data engineering.\n- Collaborative and inclusive company culture that values curiosity and innovation.\n- Please note that this is an unpaid internship.\n\nIf you’re eager to learn, innovate, and grow in the field of data engineering, we’d love to hear from you. Apply today to be part of a team that values creativity and technical excellence!\n\nAbout ActiveFence:\n\nActiveFence is the leading tool stack for Trust & Safety teams, worldwide. By relying on ActiveFence’s end-to-end solution, Trust & Safety teams – of all sizes – can keep users safe from the widest spectrum of online harms, unwanted content, and malicious behavior, including child safety, disinformation, fraud, hate speech, terror, nudity, and more.\n\nUsing cutting-edge AI and a team of world-class subject-matter experts to continuously collect, analyze, and contextualize data, ActiveFence ensures that in an ever-changing world, customers are always two steps ahead of bad actors. As a result, Trust & Safety teams can be proactive and provide maximum protection to users across a multitude of abuse areas in 70+ languages.\n\nBacked by leading Silicon Valley investors such as CRV and Norwest, ActiveFence has raised $100M to date; employs 300 people worldwide, and has contributed to the online safety of billions of users across the globe.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1239, 745, 2, 'Fullstack Software Engineer (Backend Focus)', 'About ELSA:\nFounded in 2016, ELSA harnesses the power of generative AI to improve English communication skills globally with headquarters in San Francisco and offices in Lisbon, Tokyo, Jakarta, Singapore, Ho Chi Minh, Hanoi, and Sao Paulo. ELSA is at the forefront of AI-driven language learning innovation, transforming how people worldwide enhance their English-speaking skills. Vietnam. With over 50 million users and 1 billion hours of anonymized English audio data, ELSA’s depth of data and ability to improve English communication skills is unmatched. ELSA’s hyper-personalized learning paths adapt to users’ goals and interests, making learning engaging and effective. Business learners have industry and role-based learning, enabling them to improve their English daily at work. ELSA is backed by leading investors including Gradient Ventures - Google’s A.I. fund, Monk\'s Hill Ventures and Global Ventures. ELSA’s vision is to transform lives and organizations through effective spoken English.\n\nAbout the role:\nAs a Middle Full Stack Engineer, you will play a key role in developing and deploying software that solves critical business needs. You will not only be a skilled developer but also a leader and mentor, guiding your team to deliver high-quality, reliable, and maintainable software. You will have the opportunity to shape the development pipeline, influence technical decisions, and collaborate with stakeholders across the organization.\n\nKey Responsibilities:\nInfrastructure and Operations:\n- You keep the CI/CD pipelines in good health, adjusting them as needed.\n- You actively set availability and failure rate goals for services your team owns, and pursue them.\n- Identify and influence the resolution of infrastructure issues to maintain a reliable and efficient software environment.\n\nTeam Collaboration and Growth:\n- You force multiply for your team by finding ways to enable them to do more each day.\n- Fostering an environment of knowledge sharing and collaboration within the team.\n- Focus on enabling colleagues to solve problems independently rather than providing instant solutions.\n\nCode and Quality:\n- Your code quality is exemplary.\n- Advocate for automating repetitive tasks to reduce errors, save time, and improve efficiency.\n- Demonstrate a deep understanding of design patterns and architectural principles.\n\nContinuous Improvement:\n- Staying up-to-date on industry trends and technologies relevant to the team’s work.\n- Embracing experimentation and data-driven decision making for continuous improvement.\n\nCustomer Focus:\n- Empathizing with customer needs and translating them into technical solutions.\n- Gathering and analyzing customer feedback to inform product development and improvement.\n\nRequirements:\n- Bachelor’s degree in Computer Science, Software Engineering, or related field.\n- Proven experience as a Backend Engineer with a strong understanding of full-stack development and willing to expand your expertise to be a full stack engineer.\n- In-depth understanding of software development best practices, methodologies, and SDLC in a high-speed setting using cloud computing.\n- Strong problem-solving abilities and a commitment to delivering high-quality solutions.\n- Proficient in AWS and Microservice architectures.\n- Proficiency in technical decision-making and trade-offs, considering both short-term and long-term impacts.\n- Strong interpersonal and communication skills, enabling effective collaboration and stakeholder engagement.\n- Data-driven mindset with the ability to leverage data for strategic decision-making.\n- Experience with Python/NodeJS & Web/Flutter app development is an advantage.\n- Experience with test-driven development (TDD) and behavior-driven development (BDD) practices is an advantage.\n- Proficiency in English.\n\nWhy ELSA?\n- Competitive compensation.\n- Working time: Mon-Fri (Flexible working hour), hybrid working.\n- 12 days of Annual leave, 1 Birthday leave, 1 Christmas leave.\n- Private healthcare insurance (Generali).\n- Free ELSA Premium courses to polish your language skills.\n- Fun energetic team; international and collaborative culture.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh e Região', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1240, 674, 2, 'AI Engineer (Fresher, Sinh Viên)', 'Mô tả công việc\n\nTham gia phát triển, ứng dụng, tối ưu, tích hợp mô hình AI cho các bài toán ứng dụng trong hoạt động Kinh doanh/Ngân hàng về các lĩnh vực Computer Vision, NLP...\n\nTham gia vào các công đoạn triển khai dịch vụ: Kiến trúc hệ thống, thiết kế mô hình hoạt động, luồng hoạt động, chức năng, tối ưu performance\n\nTham gia Coding, test metrics, service và unittest theo mô hình DevOps, MLOps\n\nTham gia nghiên cứu, tìm hiểu các bài báo khoa học mới nhất về AI, ML, DL\n\nTham gia các chương trình đào tạo và dự án dành cho Trainee để phát triển lên các vị trí chính\n\nYêu cầu công việc\n\nSinh viên năm 4, tốt nghiệp dưới 01 năm Đại học các chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin....\n\nCó kiến thức và kỹ năng nền tảng về:\n\nNgôn ngữ lập trình: Python, C/C++\n\nService/MicroService với một trong các framework FastAPI/Flask/Django\n\nTensorflow/Pytorch/DGL/PyG/Onnx\n\nAPI (Restful/gRPC), Lập trình an toàn, đảm bảo & tối ưu hiệu năng\n\nGit và Git Flow, Docker/ Kubernete, Kubeflow/MLFlow, TritonServer/ Tensorflow Serving\n\nCác dạng bài toán Supervised learning, Reinforcement learning\n\nXử lý Ảnh (Computer Vision)/Video/Âm thanh/Ngôn ngữ tự nhiên (NLP)\n\nCNN/RNN/Transformer/Attention, SVM/KNN/Clustering, GNN vv...\n\nKỹ thuật Knowledge Distiller/ Model Prune, Model Quantization\n\nTại sao bạn yêu thích làm việc tại đây\n\n• Thu nhập : Thoã Thuận\n• Bảo hiểm\n• Du Lịch\n• Phụ cấp\n• Du lịch nước ngoài\n• Phụ cấp thâm niên\n• Công tác phí\n• Tăng lương\n• Chăm sóc sức khỏe\n• Thưởng\n• Chế độ nghỉ phép\n• Chế độ tập thể dục', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1241, 691, 2, 'Software Engineer (ReactJS)', 'What you will be doing:\n\nDeveloping a clean and maintainable code using software engineering best-practices and modern platforms.\nParticipating in full product development lifecycles from ideation to live production.\nDay-to-day tech operations such as server maintenance and deployment.\n\nWhat we need from you:\n\nMinimum 1 years of software engineering experience building Web Front End Applications.\nComfortable using English in a professional setting.\nExperience working on ReactJS applications.\nHave a good understanding of web application architecture\nHave a good understanding of various software engineering design patterns\nVersatility and enthusiasm to tackle new problems across the full-stack and to learn new frameworks as we continue to push technology forward\n\nAbout Hubble:\n\nHubble is a leading technology company focusing on the construction and engineering industry. We are on a mission to build the world’s first autonomous construction sites by automating and trading the 4M (Man, Machine, Material, Money) resources.\n\nOur solutions help digitise all your work processes, and connect all key project stakeholders - developers, consultants,fabricators, contractors, and facility managers - onto an all-in-one platform - The Hubble Platform.\n\nBuild faster and cheaper and with the highest quality and safety standards with Hubble’s impactful technologies. Let’s transform the way we build our cities for a better tomorrow. Today. Together. For generations to come.\n\nVisit us at www.hubble.build to learn more for #bettercitiesoftomorrow', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1242, 723, 2, 'Frontend Developer', 'MÔ TẢ CÔNG VIỆC \n\n- Phân tích yêu cầu, thiết kế, phát triển các Website lớn, phức tạp, đáp ứng hàng trăm nghìn người dùng.\n- Làm việc với nhiều dự án mới, công việc mới.\n- Thời gian làm việc: 9h00 – 18h30, nghỉ trưa 1h30’, Từ thứ 2 đến thứ 6 và thứ 7 đầu tiên của tháng.\n\nYÊU CẦU \n\n- Có khả năng tư duy tốt, chuyển đổi công nghệ nhanh\n- Có kỹ năng lập trình tốt Web Frontend: HTML, CSS, Javascript và sử dụng 1 trong các công nghệ web: Angular\n- Có ít nhất 1 năm kinh nghiệm phát triển product thực tế\n- Ưu tiên các ứng viên những yếu tố sau (không yêu cầu tất cả): Có khả năng phân phân tích thiết kế và có kinh nghiệm sử dụng tech stack: Python, Flask, Elaticsearch, MongoDB, Docker.\n\nQUYỀN LỢI \n\n- Mức thu nhập hấp dẫn 15-20M/ tháng\n- Tháng lương thứ 13, Review lương hàng năm tùy vào kết quả công việc\n- Môi trường làm việc hiện đại, thân thiện, có nhiều cơ hội phát triển bản thân\n- Thưởng lễ, tết, thưởng dự án.\n- “NMS care” bảo hiểm dành riêng cho nhân viên NMS.\n- Nghỉ mát: Theo chính sách của công ty (vào tháng 5-6 hàng năm).\n- Có cơ hội được xem xét nâng lương 2 lần 01 năm, tùy vào kết quả công việc.\n- Chính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1243, 689, 2, 'Front End Developers - AI Training [Remote]', 'Requirements\nSwift, Python, Java, Go, Verilog, Javascript, C++, or C# coding experience required\n\nThis is a great opportunity to supplement your income while looking for longer or more full-time work, all while contributing to the development of new AI models using your domain expertise!\n\nOur client has hired over 1,000 Braintrust talent and intends to hire hundreds more!\n\nMany Braintrust coders earn over $12,000 per month!\n\nYou’ll have the flexibility to work as much or as little as you choose - 20hrs/week is suggested, but not a limit. Start working in as little as 48 hours. Your final hourly rate will be chosen by Outlier AI and determined by your location.\n\nWhat to expect: If qualified, you’ll be invited to complete a brief questionnaire that takes 3-5 minutes. If you successfully pass the questionnaire, you’ll be approved and able to begin work ASAP.\n\nRequired qualifications:\nProficiency working one of the following languages: Swift, Python, Java, Go, Verilog, Javascript, C++, or C#\nComplete fluency in the English language is required. You should be able to describe code and abstract information in a clear way.\n\nPreferred qualifications:\nBachelor\'s and/or Master\'s degree in Computer Science or equivalent. Students are welcome.\n\nNote: Outlier AI is partnering with Remotasks for this opportunity\n\nWhat You’ll Be Working On\nOur client has partnered with organizations to train AI large language models, helping cutting-edge generative AI models write better code.\n\nExample projects might include:\nEvaluating the quality of AI-generated code, including human-readable summaries of your rationale\nSolve coding problems, writing functional and efficient code\nOptimize code to run at maximum efficiency\nWriting robust test cases to confirm code works efficiently and effectively\nWriting human-readable summaries of coding problems\nWriting explanations of how code can solve problems and evaluate various solution approaches\n\nNo previous experience with AI necessary! You will receive detailed instructions on what is expected of you after you complete the application and verification process.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1244, 714, 2, 'Node JS Developer', 'Nếu bạn đam mê backend và muốn tham gia xây dựng hệ thống API mạnh mẽ, bảo mật – đây là cơ hội dành cho bạn. Bạn sẽ làm việc với Node.js, thiết kế kiến trúc hệ thống, xử lý dữ liệu và đảm bảo hiệu suất cho các ứng dụng quy mô lớn.\n\nMô Tả Công Việc\n\n- Xây dựng và phát triển hệ thống backend sử dụng Node.js (Express hoặc NestJS), đảm bảo hiệu suất, bảo mật và khả năng mở rộng.\n- Thiết kế và tối ưu API phục vụ cho các ứng dụng web và mobile, đảm bảo tính ổn định và dễ sử dụng.\n- Làm việc với hệ quản trị cơ sở dữ liệu như MongoDB hoặc PostgreSQL: thiết kế schema hiệu quả, viết truy vấn tối ưu hóa.\n- Triển khai các cơ chế xác thực và phân quyền người dùng, bao gồm sử dụng JWT, OAuth2 và các tiêu chuẩn bảo mật hiện đại.\n- Tích hợp real-time data qua WebSocket, và sử dụng các công cụ hỗ trợ scale hệ thống như Redis, message queue (RabbitMQ, Kafka...).\n- Tham gia vào quá trình DevOps, bao gồm cấu hình CI/CD pipelines, triển khai ứng dụng trên Docker, AWS hoặc GCP.\n- Phối hợp với các bộ phận khác như frontend, QA, UI/UX để đảm bảo tiến độ và chất lượng sản phẩm.\n\nYêu Cầu\n\n- Có ít nhất trên 2 năm kinh nghiệm làm việc thực tế với Node.js.\n- Thành thạo Express.js hoặc có kinh nghiệm với NestJS là một lợi thế.\n- Hiểu sâu về kiến trúc RESTful API, có khả năng thiết kế API rõ ràng, dễ dùng.\n- Có kinh nghiệm làm việc với MongoDB và/hoặc PostgreSQL – hiểu về thiết kế cơ sở dữ liệu, truy vấn tối ưu.\n- Đã từng triển khai hệ thống có sử dụng WebSocket, Redis, message queues (như RabbitMQ hoặc Kafka).\n- Có hiểu biết về các công cụ hiện đại: Docker, CI/CD (GitLab CI, GitHub Actions...), AWS hoặc GCP.\n- Kỹ năng làm việc nhóm tốt, sẵn sàng học hỏi và chia sẻ kiến thức.\n\nQuyền Lợi\n\n- Được đóng bảo hiểm xã hội và bảo hiểm thất nghiệp theo quy định của Luật Lao động Việt Nam, cùng với bảo hiểm Bảo Việt.\n- Số ngày nghỉ phép năm theo đúng quy định của pháp luật Việt Nam.\n- Lương tháng 13 và xét tăng lương định kỳ hàng năm.\n- Thưởng các dịp lễ, Tết theo chính sách của công ty.\n- Tiệc team-building hàng tháng cùng đồng nghiệp.\n- Cơ hội phát triển kỹ năng thông qua các khóa học e-learning, workshop, và nhiều hoạt động khác.\n- Văn phòng tiện nghi: có trái cây, trà, cà phê hàng ngày, quà sinh nhật, và tủ sách nội bộ.\n- Thư giãn cùng PlayStation 5 ngay tại văn phòng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1245, 740, 2, 'Java Software Engineer', 'Responsibilities:\n·      Develop new service functions, including web frontend development.\n·      Implement functional improvements and new requirements as requested by headquarters.\n·      Refactor and maintain source code to improve performance and scalability.\n·      Debug and report root cause identification in case of system failures.\n·      Support service change and project management business.\n·      Develop back-end modules using Java, Spring Framework based on coding standards.\n·      Conduct code reviews to maintain high coding standards.\n·      Create deliverables related to quality assurance (unit test reports, integration test reports, etc.).\n·      Perform unit testing and integration testing to ensure system reliability.\n\nRequirements:\n·      3 - 7 years of relevant experience in Java Technicals (Java Springboot, Java Application, Java Core...)\n·    Experience working with open sources such as ElastichSearch, Logstask, Fluentd, Kibana, Kafka, Redis, RabbitMQ\n·  Experience working with a well-known database (such as Oracle, MySQL, PostgreSQL, NoSQL/ MongoDB, Redis)\n·      Experience in Docker and Kubernetes. Experience in CI/CD, micro-services implementations.\n·      Excellent problem-solving and debugging skills.\n·      Experience in the development and operation of open source-based solutions.\n·      Understanding of security in software development is a plus\n·      Ability to structure, analyze, and develop Oracle, MySQL, MS SQL, SQL tuning, MongoDB...\n·      Ability to Programming of XML, CSS, HTML5.\n·      Ability to Programming of JSP/ Spring/ mybatis/ jquery/ REST/ Web Service.\n·      Experience in banking/finance/fintech projects.\n\nBenefits:\n·  Opportunity to approach newest technology trends; development of your career within an international Company\n·      Building large-scale & global software products for our clients.\n·      Onsite opportunities: short-term and long-term assignments in US, Europe, Asia.\n·      Package:\n  o  Annual KPI bonus: 1-2 month salary (based on business’ situation)\n  o  Learning package: 3million/year\n  o  Extra package: 16million VND/year (Tet, New Year, CMC Corp’s birthday, 2/9 and gifts,…)\n·      Salary review 2 times/year or on excellent performance\n·      Social, health, and unemployment insurance per state regulations.\n·      Enhanced health insurance under the CMC Care program (Aon insurance)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1246, 746, 2, 'Lập trình viên.NET', 'Tham gia phân tích, thiết kế, phát triển các dịch vụ, hệ thống của công ty, trong lĩnh vực dịch vụ viễn thông hoặc trung gian thanh toán.\nNghiên cứu các công nghệ và sản phẩm mới và đề xuất ứng dụng vào thực tiễn.\nHỗ trợ các thành viên khác trong nhóm để hoàn thành các yêu cầu của dự án.\nTìm hiểu và thực hiện theo các quy trình phát triển phần mềm của công ty.\nThực hiện các nhiệm vụ khác do cấp trên giao. Chi tiết công việc sẽ được trao đổi trong lúc phỏng vấn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ハノイ首都圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1247, 747, 2, 'Java Engineer', 'Your responsibilities\nParticipate in innovative software development life cycle using agile methodologies\nAdhere to the coding standards, best practices, common design patterns & principles\nDelivery of high quality software together with the team, including design, code, troubleshooting, tests, documentation\nWrite the technical design and detailed design for the tasks\nSelf-manage tasks as per the timelines and quality\n\nYour qualifications\nBachelor\'s degree in computer science or equivalent\nGood knowledge of OOP, SOLID principles, Design pattern, data modeling\nAble to read and write technical documents in the English language\nGood technical, analytical, and problem-solving skills\nPassionate, pro-active and keen to learn new technologies (or moving to mission part)\nExperience in the Java technology and ecosystem\nExperience in SQL and database management systems\nKnowledge of Javascript, HTML, XML, CSS\nAt least 2 years experience in software development of this applied stack\n\nNice to have\nKnowledge of the Agile methodology (Scrum)\nKnowledge of CI/CD (Jenkins, Docker)\nExperience and/or certifications on Amazon, Azure and Oracle clouds.\nExperience in Web development (Angular, ReactJS) or Windows App development\nOral communication skills in English\n\nWhy you\'ll love working here\nProfessional European-based company\nAttractive salary\nPerformance bonus of up to 4 months‘ salary\nOpportunities for travel to Europe\nHybrid home/office working model\nFlexible working time\nStructured training & development roadmap\nGood work-life balance\nPremium healthcare insurance\nLoyalty programs\nWell-being activities\nAnnual company trips and team-building events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1248, 705, 2, 'Python Developer (Django/React.js)', 'As a Python Developer, You Will Be Responsible For\n\nWrite effective, scalable code\nDevelop back-end components to improve responsiveness and overall performance\nTest and debug programs\nImprove functionality of existing systems\nImplement security and data protection solutions\nAssess and prioritize feature requests\n\nYour Skills & Qualifications\n\nBachelor’s degree in computer science, information technology, or a similar field.\nAt least 3 year experience in backend development with Python (familiar with Django)\nExperience deploying code into AWS using services such as AWS EC2, Cloudwatch, Amplify and Lambda.\nExperience in working with ReactJS\nGood problem-solving skills.\nGood verbal English communication.\nPlus point: having experience in Typescript\n\nBenefits\n\nAnnual salary review\n100% salary during probation period.\n5-days working week (Monday-Friday) – working hours are between 9 am to 6 pm.\nRemote is possible\n12 days of annual leave\nFlat organization and open communication\nFriendly working environment and flexible working hours.\nGreat opportunity to develop career, collaborate with English speaking developers\nFree parking at the building\n13th salary, insurance.\nThe company organizes Team building every year (Free tickets for 01 relative to accompany).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thôn Phú An, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1249, 728, 2, 'HN - Junior Reactjs/ Junior Nodejs - 800$', '1. INTRODUCTION\na. About Fetch:\nOur mission is to offer Vietnam’s most talented technologists a platform to connect with some of the world’s leading tech companies and build their expertise on a global scale. Over 4 years, Fetch has built a good reputation and is trusted by many Vietnamese and foreign companies; And Fetch will continue its good work to bridge the divide between the World and the Vietnam Tech sector.\nb. About Client:\nOur client has stood at the forefront of nurturing developer relationships and spearheading marketing efforts, ensuring tech products reach developers globally.\nProviding comprehensive support in developer relations and marketing for corporations, government bodies, and nonprofits, we\'ve partnered with over 250 esteemed entities such as Meta, Google, Mastercard, Intel, Nvidia, IBM, Circle, Polkadot, among others.\nWith a network exceeding 300,000 developers, our client has pioneered the organization of hackathons, online contests, acceleration initiatives, gatherings, and marketing strategies for developers in more than 100 cities worldwide.\n\n2. RESPONSIBILITIES\n- Develop high-performance web applications.\n- Analysis requirements and maintain technical documentation.\n- Contribute ideas & solutions to the products.\n- Write clear and maintainable code.\n- Participate in all phases of the product development process including analyzing user requirements, designing system architecture, coding, testing and deployment. \n- Build the front end for advanced user experience.\n- Build reusable components/modules for websites with responsive design.\n- Work with API endpoints or Socket for dynamic content updating.\n- Ensure UI/UX of developed pages and software with near pixel-perfect design.\n- Develop and optimize the front end UI to ensure the application is rendered consistently in cross-browser environments.\n- Cooperate to connect front end software development with an expert backend team.\n\n3. REQUIREMENT\nREACTJS\n- At least 2 years of experience working as a frontend developer.\n- Proficient in the React ecosystem, including ReactJS, Redux, component-based architecture, and state management (e.g., Redux Toolkit, Context API).\n- Familiar with functional programming concepts in JavaScript/TypeScript.\n- Solid understanding of HTML5, CSS3, and preprocessors such as SASS/SCSS.\n- Strong experience in building responsive, mobile-first UIs using CSS media queries and modern layout techniques (e.g., Flexbox, Grid).\n- Hands-on experience integrating with RESTful APIs, and exposure to GraphQL or WebSocket is a plus.\n- Understanding of cross-browser compatibility, accessibility, and frontend performance optimization is a bonus.\n- Experience with version control systems like Git, and familiarity with tools such as Webpack, Vite, or ESLint is a plus.\n\nNODEJS\n- Minimum 2 years of experience in backend development, preferably in product-based companies.\n- Hands-on experience with Node.js and TypeScript, or other strongly typed programming languages.\n- Familiarity with the functional programming paradigm is a plus.\n- Good understanding of relational databases, especially MySQL. Able to write and optimize SQL queries.\n- Basic knowledge of system and database design, including normalization and common networking concepts (e.g., protocols, layers).\n- Awareness of asynchronous and concurrent programming (e.g., async/await, multithreading basics, coroutines, goroutines).\n- Exposure to scalable system components, such as message queues, caching, batch processing, and load balancing is a plus.\n- Experience with common tools such as Git, GitHub Actions, Swagger/OpenAPI, and optionally JMeter or similar.\n- Familiar with Redis or equivalent caching systems.\n- Basic knowledge of Docker and container-based development. Kubernetes knowledge is a bonus.\n\n4. WHY YOU‘LL LOVE WORKING HERE\n- MacBook or high-end laptop for working. \n- Attractive salary and annual salary review. \n- Working in a professional, friendly, well-equipped environment both with foreigners and Vietnamese.\n- With extensive on-the-job training, you will always have a chance to work with new emerging technologies.\n- 12 days annual leave per year.\n- 13th-month salary.\n- Enjoy diversified activities:  Free snacks, Weekly and Monthly Team-building, Company trips, Play Games (PlayStation, Board games), and Play Sports (Football, Badminton...).\n\n5. WORKING HOURS & LOCATION\n- Working hours: From 9 AM - 6 PM, Monday to Friday.\n- Location: \n+ HN: 13th Floor, TTC Building - No.19, Duy Tan Street, Dich Vong Hau Ward, Cau Giay District, Hanoi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1250, 748, 2, 'Java Engineer (Level Junior/Middle)', 'Vị trí tuyển dụng / Position: Java Engineer\n\nSố lượng / Quantity: 2\n\nThời gian làm việc / Working hours: 8:00-17:30, from Monday to Friday every week\n\nĐịa điểm làm việc / Work Location: \nTầng 3, tòa nhà Ngân hàng Vikki, 26 Lý Thường Kiệt, phường Vĩnh Ninh, quận Thuận Hóa, TP.Huế.\n3rd Floor, Vikki Bank Building, 26 Ly Thuong Kiet Street, Vinh Ninh Ward, Thuan Hoa District, Hue City.\n\nMức lương / Salary: Thỏa thuận theo năng lực / Negotiation\n\nMô tả công việc / Job description:\n- Phát triển và bảo trì các các dự án sử dụng Java, Spring, Spring Boot,Web Services và viết code script kiểm thử tự động bằng Selenium theo test case.\nResponsible for developing and maintaining applications using Java, Spring Framework, Spring Boot, Web Services, and implementing automated tests with Selenium.\n\n- Phân tích yêu cầu, đề xuất giải pháp, khắc phục sự cố hệ thống và nâng cao chất lượng sản phẩm.\nAnalyze requirements, propose solutions, troubleshoot system issues, and enhance product quality.\n\n- Tương tác hiệu quả với các bên liên quan (khách hàng, BA, PM, team dự án,...).\nCollaborate effectively with stakeholders (clients, business analysts, project managers, and development teams).\n\n- Đảm bảo chất lượng mã nguồn và hiệu quả của các kịch bản test tự động.\nPrioritize code quality and the effectiveness of automated test scripts.\n\n- Điều tra, xử lý lỗi và tối ưu hóa hiệu suất hệ thống.\nInvestigate issues, fix bugs, and optimize system performance.\n\nYêu cầu ứng viên / Requirements:\n- Tốt nghiệp Đại học ngành Công nghệ Thông tin hoặc các ngành/chương trình đào tạo liên quan.\nA Bachelor’s degree in Information Technology or other relevant disciplines/programs.\n\n- Trên 2 năm kinh nghiệm với việc phát triển phần mềm và tối thiểu 1 năm kinh nghiệm phát triển với Java trong các dự án thực tế.\nMinimum of 2 years of experience in software development, with at least 1 year of practical experience using Java in production-level projects.\n\n- Thành thạo các công nghệ Java, Spring, Spring Boot.\nHands-on experience with Java, Spring, and Spring Boot.\n\n- Có kinh nghiệm làm việc với Web Services (SOAP, REST) và các định dạng dữ liệu như XML, JSON.\nExperience with Web Services (SOAP, REST) and data formats like XML and JSON.\n\n- Kinh nghiệm lập trình viết script automation test - Selenium (Java).\nExperience in developing automation tests using Selenium.\n\n- Có kinh nghiệm với công nghệ đám mây - Amazon Web Services (AWS).\nFamiliarity with cloud technologies - Amazon Web Services (AWS).\n\n- Có thể đọc tài liệu tiếng Anh chuyên môn và trao đổi giao tiếp cơ bản trong công việc.\nAbility to read and understand professional documents in English and engage in basic communication within a work setting.\n\n- Giao tiếp tốt, teamwork, tư duy logic, chịu áp lực.\nGood communication, teamwork, logical thinking, and pressure handling.\n\n- Sẵn sàng học hỏi công nghệ mới và thích nghi với yêu cầu công việc.\nWillingness to learn new technologies and adapt to job requirements.\n\nQuyền lợi ứng viên / Benefits:\n- Làm việc trong môi trường đổi mới, liên tục phát triển và có cơ hội làm việc tại Nhật Bản.\nThe creative and innovative environment with career growth opportunities and chances to work in Japan.\n\n- Lương, thưởng xứng tầm năng lực.\nSalary and bonuses that match your skills and experience.\n\n- Làm việc 5 ngày/tuần, nghỉ thứ Bảy, Chủ Nhật và các ngày lễ theo quy định. Ngoài ra, có 12 ngày phép/năm theo Luật Lao động và 2 ngày làm việc từ xa (Work From Home) mỗi tháng.\n5-day workweek with weekends and public holidays off, plus 12 annual leave days and 2 work-from-home days per month.\n\n- Hưởng đầy đủ BHXH, BHYT và khám sức khỏe định kỳ hàng năm.\nComprehensive healthcare with social & health insurance, plus annual health check-ups.\n\n- Thưởng thức trà, cà phê, đồ ăn vặt miễn phí, tham gia CLB bóng đá, chơi PS4 sau giờ làm việc, cũng như các buổi party và company trip hàng năm.\nEnjoy free tea, coffee, and snacks, join the football club & PS4 gaming sessions, and participate in annual company trips and parties.\n\nThời hạn tiếp nhận hồ sơ / Deadline: \nĐến hết ngày: 30/06/2025 hoặc đến khi tìm được ứng viên phù hợp \nThe end of the day: 30/06/2025 or until a suitable candidate is found\n\nThông tin liên hệ & nộp hồ sơ / Contact us:\nCông ty TNHH Tenomad / Tenomad Company\n+ Address: Tầng 3, tòa nhà Ngân hàng Vikki, 26 Lý Thường Kiệt, phường Vĩnh Ninh, quận Thuận Hóa, TP.Huế\n3rd Floor, Vikki Bank Building, 26 Ly Thuong Kiet Street, Vinh Ninh Ward, Thuan Hoa District, Hue City.\n+ Email: hr@tenomad.com \n+ Hotline: 0234 6 271 757 or 0342 425 653 (Ms Hang)\n\nNộp CV qua Email: hr@tenomad.com, tiêu đề xin vui lòng ghi rõ: Họ và tên_Vị trí ứng tuyển hoặc điền thông tin ứng tuyển ngay tại form: https://bit.ly/43O5GEm\nSubmit your CV via email to hr@tenomad.com with the subject line: Full Name_Position Applied, or complete the application form directly on the form: https://bit.ly/43O5GEm', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hue, Provincia di Thua Thien-Hue, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1251, 749, 2, 'Java Developer', '1. Mô tả công việc\n● Phát triển các ứng dụng Web và Web service, tìm hiểu các công nghệ mới\n● Nhận task từ phía PM, tiến hành điều tra, estimate và thực hiện task. Có khả năng nghiên cứu và đề xuất giải pháp cải thiện hiệu quả công việc.\n● Tham gia vào thiết kế và review source code.\n● Cập nhật tiến độ và thông báo tình trạng công việc trực tiếp tới quản lý dự án.\n● Teamwork với các thành viên khác bao gồm Developer, QA, PM, BrSE để thực hiện dự án thành công.\n● Nâng cao performance, turning logic, cài đặt các nghiệp vụ mới.\n\n2. Yêu cầu công việc\n● Có trên 3 năm kinh nghiệm lập trình bằng ngôn ngữ Java, sử dụng framework Spring Boot.\n● Kinh nghiệm với các hệ thống database, thành thạo MySQL, SQL Server…\n● Có kinh nghiệm làm việc với REST API.\n● Có tư duy logic, sử dụng thuật toán tốt.\n● Nắm vững kiến thức về lập trình Java, OOP, Design Pattern.\n● Có kiến thức về CI/CD, AWS,…là điểm cộng.\n\n3. Quyền lợi và chế độ\nChế độ đãi ngộ\n● Mức lương: Up to 35,000,000 VNĐ\n● Thưởng ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch, …)\n● Thưởng dự án, thưởng performance\n● Tổng thu nhập: Từ 14 -15 tháng lương/năm.\n\nMôi trường làm việc\n● Mức lương hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc.\n● Thưởng dự án, thưởng theo hiệu quả công việc, thưởng Tết và các dịp lễ.\n● Được đánh giá và xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc.\n● Nghỉ thứ 7, Chủ nhật, nghỉ Lễ/Tết và nghỉ phép theo Quy định của Pháp luật hiện hành.\n● Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty.\n● Được tham gia chế độ chăm sóc sức khỏe 24/24 AMELA Care khi làm việc chính thức tại công ty từ 06 tháng trở lên.\n● Khám sức khỏe định kỳ 1 năm/1 lần.\n● Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan (hỗ trợ chi phí thi chứng chỉ, khen thưởng..).\n● Môi trường trẻ trung, năng động, thẳng thắn trao đổi và chia sẻ, thúc đẩy sự sáng tạo và phát triển.\n● Được tham gia các Câu lạc bộ của Công ty: CLB Bóng đá, Bilac…..\n● Được tham gia các hoạt động tập thể sôi động của công ty: Nghỉ mát hàng năm, Teambuilding hàng quý, Gala cuối năm…\n\nCơ hội phát triển\n● Tham gia vai trò chính trong việc tư vấn, xây dựng dự án từ giai đoạn đầu tiên.\n● Tham gia nhiều chương trình đào tạo công nghệ, phương pháp làm việc.\n● Được tham gia các chương trình đào tạo đa dạng và có nhiều cơ hội thăng tiến.\n\n4. Thời gian làm việc\n● Làm việc từ thứ 2 đến thứ 6.\n● Thời gian làm việc từ 8h00 đến 17h30.\n● Nghỉ trưa từ 12h00 – 13h30.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1252, 750, 2, 'Junior/Middle Frontend Developer (TypeScript/JavaScript)', 'About the team:\nFront end engineers at Zalopay build the interfaces to our promotions systems that reach millions of users. You will build the UI for products of marketing events especially Loyalty Feature (Zalopay priority), seasonal campaigns, advertising solutions as well as back-office management that power our promotions technologies, which can include scheduling systems, analytics, data visualizations, and so on.\n\nJob Responsibilities\n• Leverage the React for creating frontend feature\n• Create data visualization tools, user interfaces, libraries, and reusable code\n• Enhance application performance with constant monitoring\n• Translate wireframes and designs into good quality code\n• Optimize components to work seamlessly across different browsers and devices\n• Develop responsive web-based UI with high performance.\n\nJob Requirement\n• Minimum 3 years of experience in Web Development, especially in Front-end\n• Extensive experience with ReactJS, Redux and React-Route\n• Practically experienced with CSS modules in React\n• Familiar with state management libraries such as redux, mobx\n• Familiar with compile tools such as webpack\n• Familiar with TypeScript\n• Experienced with RESTful API and/or RPC such as gRPC\n• Understanding of user authentication/authorization approaches such as JWT\n• Strong desire to learn and grow all technical skills in an Agile environment\n• Comfortable with code reviews, writing well-structured, maintainable code\n• Good problem-solving and analytical skills', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1253, 751, 2, 'Developer (Java)', 'Company Description\n\nTechnology is our how. And people are our why. For over two decades, we have been harnessing technology to drive meaningful change.\n\nBy combining world-class engineering, industry expertise and a people-centric mindset, we consult and partner with leading brands from various industries to create dynamic platforms and intelligent digital experiences that drive innovation and transform businesses.\n\nFrom prototype to real-world impact - be part of a global shift by doing work that matters.\n\nJob Description\n\nDevelopment is the largest discipline at Endava. Our developers design, build, and release software products in multiple programming languages, frameworks, and libraries. Always collaborating with cross-functional project teams, our developers are adaptable problem-solvers with a client-oriented mindset.\n\nAs a Developer (Java) at Endava, you will work in a professional and cross-functional team for payment gateway services. You\'ll be involved in the full development lifecycle of a software system. Contribute to delivering new products to the market by meeting customer\'s requirements and product development programs. Be an integral part of a Scrum team and contribute to Agile processes.\n\nResponsibilities:\n\n• Designs, estimates, and implements technical solutions for medium/high complexity applications.\n• Participates actively in all phases of application development lifecycle.\n• Collaborates with various project stakeholders to provide support for clarifying requirements, processes, architecture, and priorities.\n• Recommends and promotes IT industry standards, tools, practices (DevOps, etc.) to achieve well-engineered software products.\n• Proposes improvements and escalates risks/issues related to development activities.\n• Participates in the review of the work done by development team members.\n• Learns and applies new technologies, practices, and tools as appropriate to the project.\n• Participates in internal and external tech communities, events.\n• Shares experience and knowledge gained from projects. \n\nQualifications\n\n• 2+ years of experience in software development.\n• Good understanding of different common programming paradigms (OOP, Functional, etc.).\n• Familiar with design/architectural patterns and clean code principles (e.g., SOLID, GoF, MVVM).\n• Proficiency in relevant programming languages, frameworks, and tools such as Java, IntelliJ IDEA, Spring, Hibernate, Maven, Gradle. Nice to have:\nKotlin.\n• Practical experience in platform-specific database systems and SQL.\n• Understanding of version control systems like Git or similar.\n• Experience with testing and mocking frameworks.\n• Familiar with communication protocols and standards such as HTTP, REST, JSON, TCP/IP.\n• Basic knowledge of Agile methodologies (e.g., SCRUM, KANBAN).\n• Basic knowledge of CI/CD tools and practices.\n• Good problem-solving skills and analytical thinking.\n• Excellent communication and teamwork abilities.\n• Intermediate English proficiency.\n\nAdditional Information\n\nDiscover some of the global benefits that empower our people to become the best version of themselves:\n\n• Finance:\nCompetitive salary package, referral bonus; \n• Career Development:\nCareer coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership;\n• Learning Opportunities:\nComplex projects, rotations, internal tech communities, training, certifications, coaching, online learning platforms subscriptions, pass-it-on sessions, workshops, conferences;\n• Work-Life Balance:\nHybrid work and flexible working hours, employee assistance programme;\n• Health:\nGlobal internal wellbeing programme, access to wellbeing apps;\n• Community:\nGlobal internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations.\n• Annual leave encashment;\n• 13th month salary;\n• Premium annual health check & Extra health & accident insurance;\n• Welcome kit and gift-giving frequency;\n• Attractive benefits of Trade Union;\n• Exciting English programme.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه هو شي مينه سيتي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1254, 703, 2, 'Java Developer', 'About Us\n\nKegmil is revolutionizing the way mission-critical assets are repaired and maintained – by transforming complex systems of people and processes into streamlined, intelligent operations. Our mission is to empower millions of deskless field service professionals across Asia’s asset-centric industries with superior technology to elevate service excellence, operational insight, and profitable growth. Our cloud-based, mobile-first, and AI-powered platform automates and optimizes every aspect of field service from job scheduling and dispatch to execution and reporting.\n\nKegmil is trusted by leading organizations across mission-critical sectors – including elevator, fire protection, data center, medical equipment, and aerospace – to build the next-generation digital backbone that unifies FSM, modular ERP, and AI agents into one seamless platform for simpler, smarter, field service.\n\nWe are a curious and collaborative team that finds purpose in solving real problems for our customers. We learn and grow together in a high-trust, inclusive culture – where ideas are heard, ownership is encouraged, and customer success is everyone’s priority.\n\nJob Title: Java Developer\n\nLocation: Remote/ Hybrid\n\nJob Type: [Full-time]\n\nExperience Level\nMid Level: 3 - 5 years of experience in Java\n\nKey Responsibilities\n- Work alongside highly talented & motivated team members passionate about solving hard, real-world problems with our unique and category-defining SaaS platform.\n- Work on latest Microservices, Service Mesh, Big Data, AI/Machine Learning.\n- Delight enterprise customers across multi-billion dollar industries in APAC.\n- Have a voice and make a tremendous impact on what you\'re building from the ground up.\n\nRequired Skills\n- Proficiency in Java programming language and related technologies (e.g., Springboot, Hibernate)\n- Strong understanding of object-oriented design principles and software development best practices\n- Experience with relational databases (e.g. PostgreSQL)\n- Knowledge of design API development technologies (e.g., Restful API, gRPC...)\n- Familiarity with Agile/Scrum methodologies\n- Problem-solving and analytical skills\n- Strong communication and collaboration skills\n- Ability to work effectively in a fast-paced environment and manage multiple tasks/projects simultaneously\n- Willing to learn and adapt Python\n\nWhy Join Us? \nAt Kegmil, you’ll be part of a team that values innovation and collaboration, working together to transform and lead the field service industry into a new era. We offer competitive salaries, comprehensive benefits, and opportunities for growth and development in an engaging, forward-thinking environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1255, 752, 2, 'Java Developer', 'WHO ARE WE? \n\nOur vision is to transform human behaviour into actionable intelligence.\n\nSQREEM is a leading Cognitive AI company specializing in delivering Behavioral Intelligence, a transformative approach to understanding, mapping, and predicting human behavior.\n\nUsing our proprietary Cognitive AI model, we process over 4 billion unrelated and unstructured data signals daily from the Open Web across 70+ countries. By decoding patterns, uncovering intent, and analyzing behaviors, we transform vast, complex datasets into actionable intelligence that businesses rely on to make smarter, more precise decisions.\n\nOur innovative technology powers ONE, our proprietary end-to-end platform, which enables organizations to turn complex behaviors into clear, data-driven insights. From understanding audience intent to curating highly refined segments, ONE bridges the gap between data and decision-making, empowering businesses to unlock meaningful engagement at scale.\n\nThe result is the world’s largest library of privacy-first, non-PII, GDPR-compliant intent and demographic signals, including ID-free cohorts that meet the highest global privacy and security standards, such as HIPAA, COPPA, GDPR, and ISO-27001.\n\nTo reach an under 18 audience, our platform, TotallyAwesome, is a contextual-first marketing solution that enhances ad effectiveness without using personal data and guarantees 100% brand safety. By combining human moderation, AI and psychological expertise, we deliver the right content to the right audience at the right time. Our multi-channel solutions reach over 600 million monthly users in APAC across apps, sites, YouTube, gaming, and influencers.\n\nWHAT WILL YOU BE DOING?\nOverview: Java Developer will use their technical expertise to research, recommend, design and implement web sites and applications. They will work with other developers to program based on coding standards, and to assure that all tasks and projects are completed with the highest quality.\n\nHow will YOU contribute to the Team? \n- Collaborate with stakeholders to gather and analyze technical and business requirements.\n- Design, develop, and maintain high-quality, scalable websites and applications.\n- Lead by example: plan, delegate, and monitor tasks assigned to junior developers, ensuring alignment with project timelines and standards.\n- Contribute to project success by providing support during critical phases, including occasional overtime when necessary.\n- Participate in client meetings and coordinate with third-party vendors as required.\n- Adhere to and advocate for established company processes, development standards, and best practices.\n\nWHO ARE WE LOOKING FOR? \n- A Bachelor degree in computer science or related field\n- Qualified applicants will have a minimum of 3 years’ experience successfully implementing\nsolutions in web-based applications using JAVA on Linux environments\n- Strong knowledge/experiences on OOP, data structure and algorithm\n- Strong understanding of SOA methodologies and service architectures\n- Experience using web servers, application containers, caching technologies\n- Knowledge on high-availability, high-scalability web applications\n- JavaScript, HTML, DHTML, CSS, others JS frameworks (Nodejs, AngularJS, …) are a plus\n- Other Technologies: Linux, Apache/Nginx, Web Services, TCP/IP, SVN…\n- Detailed and focused on quality\n- Must be self-motivated and able to achieve results\n- Aptitude to learn quickly and work well within a team environment\n- Genuine curiosity about the advancements in AI technologies, with an eagerness to explore new concepts and innovations.\n\nOUR ETIQUETTE \n\nWe work together to give everyone the power to share their story, explore what they love, and connect with one another in the process. In our culture, we live by the following values:\n- Innovation & Agility\n- Teamwork & Collaboration\n- Data Integrity & Ethics\n- Results driven performance\n- Human by design\n\nOur people are at the heart of what we do and the driving force behind our growth and success. We value our culture as the lifeblood of our business and work hard every day to maintain this as we continue to grow and scale our team. We believe in offering opportunities to learn and grow every day and we’ve got a strong track record in developing great people.\n\nWe are proud to be an equal opportunity workplace. We review job applications without regard to their race, color, religion, gender identity, national origin, citizenship, age, marital status.\n\nPERSONAL ATTRIBUTES\n- You are a self-starter, independent and problem solver. You consider yourself a high-performance personality\n- Understand what it means to deliver excellence.\n- Good sense of humor and ability to stay calm under pressure.\n- Well-organised with excellent communication and time management skills.\n\nWHAT CAN WE OFFER YOU \n- Our people are at the heart of what we do and the driving force behind our growth and success.\n- We value our culture as the lifeblood of our business and work hard every day to maintain this as we continue to grow and scale our team.\n- We believe in offering opportunities to learn and grow every day and we’ve got a strong track record in developing great people.\n- We are proud to be an equal opportunity workplace. We review job applications without regard to their race, color, religion, gender identity, national origin, citizenship, age, marital status.\n- Unlimited leave!\n- Finish early Fridays!\n- Social work environment\n- Flexible working arrangements\n- Mentorship programs\n- Remote working support across APAC markets\n- We are a team of passionate experts. We are not just leading in this industry; we are defining it.\n\nFor more details, please send an email to careers@totallyawesome.tv', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1256, 681, 2, '[HN_Hybrid]_Java Engineer (English Fluency)', 'WHAT WE DO:\nAt Sun Asterisk, we build cutting-edge, high-performance systems to tackle complex challenges. As a developer, you will:\nDesign Next-Level Architecture: Create scalable Kubernetes (K8s) solutions across on-premise, AWS, GCP, and Azure environments, ensuring seamless integration and performance.\nCraft High-Performance Databases: Design and optimize databases to handle massive data throughput with speed and efficiency.\nCode with Excellence: Implement Domain-Driven Design (DDD) principles and integrate pub/sub messaging systems for clean, modular, and scalable codebases.\nMaster Performance Optimization: Dive into large-scale databases, hunt down slow queries, and fine-tune systems for peak performance.\nElevate Monitoring and Reliability: Leverage AWS CloudWatch, GCP Monitoring, and Azure Monitor to proactively track performance, detect issues, and ensure systems are always reliable and fast.\nWHO YOU ARE:\nExperience Requirements\nMandatory Skills\nAt least 3 years of experience in developing Java Web applications.\nProficiency in Java Core and strong understanding of OOP and Design Patterns.\nExperience working with frameworks such as Spring, Struts, JSF, and J2EE.\nProficiency in HTML, CSS, and JavaScript.\nExperience in building Microservices and working with APIs.\nExperienced working with Agile model projects\nPrior experience collaborating with US/UK clients or clients in English-speaking markets.\nFamiliarity with monitoring (opentracing , open telementry…)\nSolid understanding of RESTful API Services and open API\nExperience in building Microservices and working with APIs and protocols: (HTTP , TCP , restful , grpc).\nProficiency in using Git\nFamiliarity with at least one RDBMS, such as MySQL or Postgres. Need to understand deeply with index , locking , complexity of query.\nExperience working with various databases, including RDS and NoSQL.\nSolid understanding , data structures, and basic algorithms.\nHands-on experience writing Unit Tests.\nBonus Points\nFrontend Skills: Experience in frontend frameworks such as ReactJS, Angular, VueJS…\nDevOps Skills: Knowledge or experience with CI/CD pipelines, Docker, Kubernetes, etc.\nAI/ML Knowledge: Familiarity or interest in Artificial Intelligence (AI) or Machine Learning (ML)\nSkill Requirements\nExcellent English communication skills\nStrong teamwork skills\nAbility to allocate tasks effectively\nStrong critical thinking and logical thinking skills\nEffective problem-solving skills\nAttitude Requirements\nPossess customer-oriented mindset\nEmbrace and adapt to changes\nBe committed to continuous development\nBENEFITS AND PERKS:\nProfessional, open-minded, and creative environment:\nWork with colleagues who embrace ideas to change the society\nRespect different perspectives within a team\nStrong learning culture that promotes individual development\nThe culture of taking risks to experience and thrive\nFocus on individual development\nBe consulted, accompanied, and supported in career development with the career path system (developing in expertise or management direction) that has been studied and tested for many years.\nBe oriented for individual, group, and organizational goals\nBe empowered\nBe supported to define a 3-month or 6-month goal (Goal Define Support)\nGet access to company Learning Hub online library with various courses provided by Udemy, LinkedIn,…\nSpecial care for employees\nSalary: Negotiable + competitive allowance (lunch, living allowance, beauty care, Japanese and IT certificates, etc.)\n13th-month salary bonus\nPerformance review: Twice/a year\nHybrid working policy; flexible check-in, check-out\nComprehensive health insurance Sun* Care\nSeniority Allowance\nWomen care allowance: Women’s physiological leave: 2.5 hours/month; Postpartum leave for female employees with under 1-year-old children: 1 hour/day\nPolicies supporting learning activities, knowledge sharing, and cultural exchange (Technology Seminar – Tech Expert, Club: Reading, Japanese, Music Club, …)\nAnnual company trip and quarterly team-building activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1257, 753, 2, 'Game UI/UX Designer (Music Entertaiment Platform)', 'We\'re looking for a talented Designer to join our Game team, research and design UI/UX and game assets that bring our mobile games to life and engage players worldwide.\n\nWhat You Will Do\n\n- Design user interfaces (UI) and game assets that are visually appealing, intuitive, and user-friendly for mobile games.\n- Collaborate closely with Developers, and Product Owners to ensure a cohesive and delightful player experience.\n- Stay up-to-date on mobile games UI/UX trends and best practices, continuously improving the game\'s usability and aesthetics.\n- Take ownership of the game\'s visual plan and direction, proactively planning and enhancing the user experience through visuals.\n- (Optional) Assist Marketing Team to prepare the material such as icons, screenshots, etc.\n\nTechnical skills requirements:\n\n- Minimum 1-3 years working with Graphic design softwares (Photoshop, Illustrator, Figma, etc.).\n- Can independently conduct research, update knowledge about mobile game trends. Having experience working with the Mobile Game industry is a plus.\n- Having experience working in animation design is a plus.\n- Graduated in Graphic Design, Game Design or related fields.\n- Basic knowledge and passion for music, digital marketing, and mobile games.\n\nSoft skills requirements:\n\n- A reliable person and able to work independently, with responsibility.\n- A creative person, flexible and adaptive to work with multiple games portfolio.\n- A communicative person who can discuss with the team about their ideas, projects and negotiate feedback effectively.\n- An energetic and open-minded collaborator.\n- A multi-tasker, who proactively seeks out opportunities to support the team.\n- Portfolio is required as part of the application.\n\nWhat We Offer:\n\n- Competitive salary and benefit packages.\n- ESOP package.\n- Opportunity to work on exciting mobile game projects.\n- Collaborative and supportive team environment.\n- Continuous learning and growth opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1258, 754, 2, 'Java Developer', 'Java Developer\n\n(*) Headcount: 3-4\n(*) Level: Senior 4-5\n(*) Languages: Good Communication\n(*) Process interview: 2 round\n(*) Working Hour: VNT.\n(*) Report Line: Techlead\n(*) Duration: 6 months\n(*) Working Type: Hybrid\n\nKEY RESPONSIBILITY:\nWe are seeking a skilled developer to work on a centralized and optimized customer interaction, sales process, and customer service management platform. This role involves building a scalable and secure system that seamlessly integrates with existing business applications to enhance customer engagement and drive business growth.\n\nApplication Development & Maintenance \nDesign, develop, and maintain Java applications using Spring Boot and Spring Framework.\nImplement RESTful APIs and integrate with frontend applications.\nWrite efficient, scalable, and maintainable code.\n\nDatabase Management \nDevelop and optimize database queries for MySQL and MongoDB.\nWork with JPA/Hibernate for ORM (Object Relational Mapping) and ensure efficient database interactions.\n\nSpring Framework Expertise \nUtilize Spring Core, Spring MVC, Spring Security, Spring Data JPA, and Spring Boot for application development.\nImplement Spring Security for authentication and authorization.\n\nTesting & Debugging \nWrite and maintain unit tests (JUnit, Mockito).\n\nVersion Control & CI/CD \nManage source code using Git and repositories like GitHub/GitLab/Bitbucket.\n\nContinuous Learning & Improvement \nStay updated with the latest trends in Java, Spring, MySQL, MongoDB, and emerging technologies.\nImprove existing features and propose innovative solutions.\nMake quality and usability your primary goals.\nProblem investigation, system troubleshooting and bug fixing.\n\nREQUIREMENT\nMinimum of 3 years of experience in Java backend development using Spring Boot or similar frameworks.\nProficiency in Java 8+ with strong knowledge of OOP (Object-Oriented Programming) concepts.\nExperience with Spring Framework, including:\nSpring Boot (Microservices development)\nSpring MVC (Web applications)\nSpring Data JPA (ORM with Hibernate)\nSpring Security (Authentication & Authorization)\nExperience with JPA/Hibernate for ORM and database interactions.\nProficiency in developing RESTful APIs and working with API documentation tools like Swagger/OpenAPI.\nGood knowledge of version control systems, preferably Git (GitHub, GitLab, or Bitbucket).\nFamiliarity with CI/CD pipelines (Jenkins, GitHub Actions, GitLab Cl, or equivalent).\nBasic knowledge of containerization using Docker (Kubernetes is a plus).\nUnderstanding of caching mechanisms (Redis, Ehcache) and messaging systems (RabbitMQ, Kafka) is a plus.\nExperience with testing frameworks such as JUnit, Mockito for unit and integration testing.\nExperience with Web Layout Design and Development: HTML5, JavaScript, CSS, JQuery, AJAX is a plus.\nGood to have knowledge in eCommerce systems, Hybris SAP.\nGood willingness to learn new technologies required for work.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1259, 742, 2, 'Fresher Mobile (React Native) Engineer', 'Company Description\n\nKMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines:\n\nKMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions. \nKMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality. \nKMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors. \n\nJob Description\n\nYour key responsibilities:\n\nDevelop, and maintain high-quality React Native applications using clean code. \nWorking on mobile frameworks\nIntegration between cross environments - web and mobile\nImplement pixel-perfect user interfaces that match designs. \nDiagnose and repair bugs and performance bottlenecks for native-like performance\nWork closely with the project team on daily tasks and participate in sprint demo meetings with clients\nCommunicate and report internally or directly to client on status or result of work. \n\nQualifications\n\nQualifications:\n\nBachelor’s degree in Information Technology, Computer Science, Software Engineering, or a related field. \nStrong IT background with a GPA of 8+ (Please attach transcripts when submitting your CV). \nAt least intermediate or higher English proficiency (both written and verbal). \nMinimum 6-month internship experience in software engineer is required. \nStrong self-learning ability with a proactive, growth-oriented mindset. \nExcellent analytical and problem-solving skills. \nAbility to work independently and collaborate effectively in a team. \n\nTechnical requirements:\n\nPassion for Mobile Applications Development using React Native\nKnowledge with JavaScript frameworks/libraries that are more powerful than jQuery (e.g. ReactJS/Angular)\nStrong fundamental knowledge of Web/Mobile application development, OOP, data structure, and algorithms\nHave a good understanding of projects being done in university or during the internship\nBasic knowledge in writing unit tests\n\nAdditional Information\n\nPerks You\'ll Enjoy \n\nWorking in one of the Best Places to Work in Vietnam\nBuilding large-scale & global software products\nWorking & growing with Passionate & Talented Team\nDiverse careers opportunities with Software Outsourcing, Software Product Development, IT Solutions & Consulting\nAttractive Salary and Benefits\nPerformance appraisal twice a year and performance bonus\nOnsite opportunities: short-term and long-term assignments in North American (U.S, Canada), Europe, Asia\nFlexible working time\nVarious training on hot-trend technologies, best practices and soft skills\nPremium healthcare insurance for you and your loved ones\nCompany trip, big annual year-end party every year, team building, etc. \nFitness & sport activities: football, tennis, table-tennis, badminton, yoga, swimming…\nJoining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,…\nFree in-house entertainment facilities (foosball, ping pong, gym…), coffee, and snack (instant noodles, cookies, candies…)\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1260, 755, 2, 'Junior Android Engineer - Hybrid working model 100%, Ho Chi Minh City', 'Company Description\n\nWelcome to SMG Vietnam!\n\nSMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nJob Description\n\nThis job refers to our Real Estate brands, Homegate and Immoscout24, the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing.\n\nWe are looking for an Junior Android Engineer who is passionate about mobile development and eager to work on high-quality Android application. As a key contributor to our mobile engineering team, you will focus on delivering clean, efficient, and reliable code, working closely with other engineers, designers, and product managers. This role is ideal for an engineer looking to deepen their Android expertise and contribute to complex projects in a supportive environment.\n\nJoin our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nYour Mission:\n- Assist in designing, developing, and maintaining Android applications, focusing on clean, maintainable code. \n- Collaborate closely with product managers, designers, and senior engineers to implement new features and enhancements. \n- Participate in code reviews, learn from feedback, and apply best practices to improve code quality. \n- Write Unit and UI tests with guidance to ensure code reliability. \n- Learn and apply modern Android architecture patterns to build scalable features. \n- Continuously improve your skills and contribute to the team\'s knowledge-sharing culture. \n- Help identify and fix bugs, optimize performance, and support releases under the guidance of more experienced team members. \n- Stay curious and up-to-date with Android development trends, tools, and best practices.\n\nYour responsibilities will evolve as we grow.\n\nQualifications\n\nWhat will you bring to the ride?\n- Fluency in English written and verbal communication. \n- Bachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience. \n- 1+ year of experience developing Android applications in Kotlin (Java is a plus). \n- Basic understanding of Android components and tools (e.g., Activities, Fragments, Android Studio). \n- Some exposure to modern development practices such as MVVM, Jetpack components, or reactive programming is a plus. \n- Willingness to learn and apply best practices in mobile development, testing, and architecture. \n- Comfortable with consuming REST APIs and working with local storage (e.g., Room, SharedPreferences). \n- Curious, open-minded, and enthusiastic about growing in a collaborative team environment. \n\nNice-to-Have Qualifications:\n- Exposure to CI/CD, version control (e.g., Git), or test automation frameworks. \n- Awareness of mobile app performance and monitoring tools (e.g., Firebase, Datadog). \n- Familiarity with privacy, security, or accessibility in mobile apps.\n\nWe value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique.\n\nAdditional Information\n\nWhat do we offer?\n- Competitive Benefits: Attractive salary, full pay during probation, 13th-month bonus, and full social insurance contributions. \n- Generous Leave: 21+ annual paid days off, 24 days for learning & sharing, and flexible working hours with no overtime. \n- Health & Wellness: Premium private insurance for you and your family, free food, and access to various classes and clubs. \n- Growth Opportunities: Personalized development plans, yearly education budgets, regular Hackathons, and potential travel to Switzerland and Europe. \n- Modern Work Environment: Hybrid model, top-tier equipment, and a friendly, agile, and transparent culture. \n- Supportive Onboarding: Comprehensive assistance to help you settle in.\n\nRecruitment Process \n\nWe believe hiring is a two-way street, where both parties get to know each other. Here\'s what you can expect:\n- Initial screening call with HR – A brief conversation to understand your background and expectations. \n- Meeting with the Hiring Manager – A deeper discussion about the role, your experience, and how we work. \n- Home assignment – A small project to showcase your skills in a real-world context. \n- Technical Assessment – A follow-up session to review your assignment and discuss technical topics in more detail. \n- Casual Meeting with Director – An informal conversation to align on vision, culture, and goals. \n\nAt SMG Vietnam, we value diverse perspectives and individual growth. We welcome candidates from all backgrounds and encourage you to apply, even if you don’t meet every requirement. Together, we embrace differences, nurture potential, and celebrate success.\n\nApply now\n\nTo take this opportunity, send us your detailed CV and feel free to add any supporting documents we need to look at in order to understand that you are the perfect fit.\n\nAbout Us\n\nSMG Swiss Marketplace Group AG. is a pioneering network of online marketplaces and cutting-edge European digital company that simplifies people’s lives with innovative products.\n\nSMG Swiss Marketplace Group AG. provides customers the best tools to meet their life decision needs. The portfolio includes Real Estate (ImmoScout24, Homegate, Flatfox, alle-immobilien.ch, Immostreet.ch, home.ch, Publimmo, Acheter-Louer.ch, CASASOFT, IAZI), Automotive (AutoScout24, MotoScout24), General Marketplaces (anibis.ch, tutti.ch, Ricardo) and Finance & Insurance (FinanceScout24, moneyland.ch).\n\nThe company was founded in November 2021 by TX Group AG, Ringier AG, La Mobilière and General Atlantic.\n\nDisclaimer\n\nSMG Swiss Marketplace Group AG primarily engages directly with candidates. We do not accept unsolicited resumes or candidate profiles from recruitment agencies unless we have specifically requested their assistance for particular roles. Any submissions made without a prior request from our Talent Acquisition team will not be acknowledged or considered. We appreciate the understanding and cooperation of recruitment agencies in respecting this policy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1261, 713, 2, 'Frontend Engineer', 'Job Type\n\nFull-time\n\nDescription\n\nResponsibilities and Duties\n\nOnce You Join Our Team, You Will\n\n- Collaborate with other team members (PM, UI, backend engineer, QA) to provide a seamless freight experience for our customer;\n- Participating design the front end architecture, collaborate with backend engineers to develop and deliver elegant product solutions;\n- Propose innovative technical solutions to hard business problems;\n- Curiosity and passion, understanding of LLM and AI Agent framework;\n- Lean and grow constantly, improve yourself and make the team member around you better\n\nRequirements\n\n- Familiarity with the development process and work patterns of internet products.\n- Fluent in frontend technologies, including HTML, CSS, JavaScript, and TypeScript.\n- Fluent in React, with practical experience in developing complete React projects.\n- Solid experience with common frontend frameworks, libraries, and tools such as Webpack, Babel, Vite, Turbo, Lerna, Next.js, React, and Vue.\n- Understanding and familiarity with Node.js, capable of project building, with some backend development experience in Node.js.\n- Proficiency in TypeScript; practical experience with TypeScript projects is a plus.\n- Familiarity with commonly used frontend state management tools, such as Redux, MobX, Observable, React Hooks, Zustand, and Recoil.\n\nPreferred Qualifications\n\n- Practical experience with TypeScript and React projects.\n- Experience in developing AI bots.\n- Some experience in backend development with Node.js and Python.\n- Familiarity with open-source LLM models and knowledge of projects like LangChain and Llama-Index.\n- Understanding of containerization and serverless development.\n- A personal blog or independent website is a plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 Quận 3', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1262, 723, 2, 'Tuyển dụng vị trí lập trình viên', 'Vị trí: Lập trình viên\nĐịa điểm làm việc: Công ty Cổ phần Dịch vụ Di động Thế Hệ Mới (NMS) – Tầng 3A, Mỹ Đình Plaza, 138 Trần Bình, Hà Nội\nSố lượng: 05 nhân sự\nMô tả công việc:\n\n– Phát triển phần mềm chuyên dụng cho các nhà mạng lớn tại Việt Nam và các đối tác nước ngoài.\n\n– Viết tài liệu thiết kế chi tiết, báo cáo kết quả Unit Test cho dự án.\n\nYêu cầu:\n\n– Ngôn ngữ lập trình: Có thể sử dụng ít nhất 1 trong các ngôn ngữ: Java (SE-EE), NodeJs, AngularJs, PHP.\n\n– Database: MySQL, Oracle 11g, SQL server.\n\n– Sử dụng thành thạo MS Office.\n\n– Có khả năng sử dụng tiếng anh đọc và viết.\n\n– Không yêu cầu kinh nghiệm, chấp nhận sinh viên mới ra trường và thực tập sinh. Ứng viên chỉ cần hiểu biết về lĩnh vực lập trình và ham học hỏi.\n\nĐãi ngộ:\n\n– Mức lương cạnh tranh, thưởng theo kết quả kinh doanh.\n\n– Làm việc trong môi trường chuyên nghiệp.\n\n– Được đào tạo các công nghệ mới nhất hiện nay.\n\n– Được đóng bảo hiểm xã hội và chế độ phúc lợi theo quy định của luật Lao động\n\nCách thức ứng tuyển:\n\n– Gửi CV đến email: yenttn@nms.com.vn\n\n– Mọi thắc mắc xin vui lòng liên hệ Phòng HCNS: Ms. Yến: 0473008555 – 01675486171\n\nThời hạn nhận hồ sơ: 10/03/2018', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1263, 756, 2, 'Junior Android Developer', 'JD TUYỂN DỤNG VỊ TRÍ “JUNIOR ANDROID DEVELOPER”\n\nVị trí: Junior Android Developer - Full-time\n\nĐịa điểm: Đà Nẵng\n\nThời gian: 8:00 - 17:30, nghỉ trưa 1h30’, làm việc từ T2-T6 \n\nWebsite : https://apero.vn/\n________________________________________________\n\n1. Mô tả công việc \n- Phát triển ứng dụng, module ứng dụng Android theo phân phối của Team Leader.\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động theo phân phối của team leader.\n- Phối hợp với Mid Level/ Senior Developer thực hành code review.\n- Phối hợp với các team liên quan vận hành dự án theo quy trình.\n- Tham gia hướng dẫn, đào tạo member mới.\n- Được phép tự do nghiên cứu công nghệ mới, đề xuất ý tưởng đóng góp vào dự án.\n\n2. Yêu cầu\n- Có kinh nghiệm lập trình Android tối thiểu 6 tháng.\n- Nắm được khái niệm Android cơ bản (Activity/Service/View System, Resource, Storage, Thread Handling).\n- Có kinh nghiệm sử dụng Jetpack Component, Coroutine/Rx.\n- Đã từng sử dụng một trong các mô hình kiến trúc MVP, MVVM.\n- Hiểu biết Design Pattern là một lợi thế.\n- Có khả năng dựng module độc lập là một lợi thế.\n- Am hiểu Agile Scrum là một lợi thế.\n- Đam mê, chủ động công việc, có kỹ năng làm việc nhóm, làm việc độc lập.\n- Đam mê phát triển sản phẩm.\n- Có kỹ năng làm việc nhóm/ theo quy trình là một lợi thế.\n\n2. Quyền lợi\n- Mức lương 12.000.000-20.000.000 VNĐ.\n- Xét tăng lương 1 lần/năm. Lương tháng 13\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN.\n- Các gói bảo hiểm ngoài BHXH: Bảo hiểm PTI, khám sức khỏe định kỳ hàng năm\n- Văn hóa làm việc GenZ,môi trường làm việc trẻ trung, sáng tạo, Dám nghĩ - dám làm, trà đá, bàn tròn,\nném đá sếp, áp dụng triệt để văn hóa 6K startup, TSB3C.\n- Thực chiến cùng quản lý, chuyên gia từ các tập đoàn lớn: Topica, VNG, Samsung,...\n- Du lịch hàng năm, team building, tea break hàng tuần\n\n4: Thông tin liên hệ\n- Người liên hệ : Apero – Ms. Xuân\n- Email liên hệ: xuanlt@apero.vn\n- Số điện thoại : 0342589422\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1264, 757, 2, '[HN] Software Engineer (Full-stack,Junior)', 'About Us\n\nBase.vn is a B2B SaaS (Software-as-a-Service) Company providing technology management solutions for SMEs enterprises.\n\nBase will bring to your business the smartest, most modern technology products, based on three main components: Data & Artificial Intelligence (Data & AI), Interaction (Interaction), and Platform platform (Open Platform). And imagination knows no bounds: With whatever application you have or need, Base can help you integrate into a common platform. With a strong belief in young Vietnamese engineers, we are looking for talented Software Engineer for the Platform Team to pursue Base’s mission together: Build great enterprise software for Asia.\n\nWhat You Do\n\nFrom the beginning, you will be guided by Senior Engineer or Team Lead to:\n\n- Understand the products we‘re passionately building and know what to improve yourself to build them better in the future\n- Understand and respect all the working principles\n- Efficiently work with all the materials\n- Get your very first products - “Starter Project" done, reviewed, and improved \n\nThen, you will join a full-cycle buildup apps/features in our platform:\n\n- Analyze product & Planning\n- Design Database\n- Develop & Test\n- Demo & Launch\n- Maintain & Update new features\n\nWho You Are\n\nWe‘re looking for talented Software Engineers (Junior) to join our team with below traits:\n\n- Solid knowledge in Algorithms & Data structures\n- Strong knowledge and experience in using any programming language (PHP/Javascript is an advantage)\n- Knowledge or experience in using Restful API, MySQL, HTML5, CSS3, Javascript, jQuery, AJAX, JSON\n- Understanding of performance optimization or experience in real applications in production, serving large amounts of users and data - is an advantage\n- Desire to participate in building the product "B2B SaaS - Make in Vietnam"\n\nSpecial Benefits\n\nWHAT YOU CAN GET\n\n- Attractive salary package up to 1600$ plus bonus based on performance\n- Flexible evaluation of salary increase (1-2 times/year) commensurate with work results\n- Opportunity to receive ESOP shares (employee stock ownership plan) for outstanding contributors\n- High performance computer and screen\n- Team building, vacation in a year, and other engagement activities\n- Other benefits as prescribed by the Labor Law\n\nPersonal Development\n\n- Fast-track career: Join a full cycle of building real products for market and continuously grow with the scalability of products.\n- Unlimited learning opportunities: Enhance your expertise through a comprehensive training program, guidelines from mentors, buddies, and product development challenges.\n- Visible values & impacts: Build world-class and high-performance products that solve pain points for millions of enterprises.\n- Talented colleagues: Work with a team of enthusiastic and professional Product Builders who have already built a highly large-scale system serving 60+ millions of pageviews, hundreds of thousands users each month, and 10,000+ enterprises; and graduated from top universities in Vietnam & the world (Stanford, UCLA, HUST, etc.).\n\nGET READY TO BE OUR SOFTWARE ENGINEER!\n\n- Round 1: CV Application \n- Round 2: Interview\n\nAddress Office: 16th floor, HUD Building, 37 Le Van Luong, Thanh Xuan, Hanoi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1265, 674, 2, 'Low-Code Developer', 'Mô tả công việc\n\n• We are looking for an enthusiastic and eager Junior Salesforce/Outsystems/Servicenow Developer to join our growing team.\n• This is an excellent opportunity for individuals with a foundational understanding of software development principles who are keen to learn and build applications using the low-code platform.\n• You will work alongside experienced developers, contributing to the development and maintenance of our applications while gaining valuable hands-on experience.\n\nYêu cầu công việc\n\n• Bachelor\'s degree in Computer Science, Information Technology, or a related field\n• Basic understanding of software development concepts and methodologies.\n• Familiarity with web technologies such as HTML, CSS, and JavaScript is a plus.\n• Basic knowledge of relational databases and SQL.\n• Strong logical thinking and problem-solving skills.\n• Eagerness to learn and work with the Salesforce/Outsystems/Servicenow platform.\n• Good communication and teamwork skills.\n• Strong analytical and problem-solving skills.\n• Fluency in English (both written and verbal)\n\nTại sao bạn yêu thích làm việc tại đây\n\n• Attractive income package as negotiation.\n• Global and inclusive workplace with monthly cross-cultural events.\n• International exposure and career growth across global locations.\n• Work-life balance benefits supporting employee well-being.\n• Private health insurance with optional family coverage.\n• Summer vacation allowance.\n• Sponsored training courses for personal growth.\n• Comprehensive relocation package.\n\nĐịa điểm làm việc\n\n• Hồ Chí Minh: Lô E3 Đ. Võ Chí Công, Quận 9\n\nThời gian làm việc\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1266, 758, 2, 'Automation Software Engineer (Python, JavaScript, C#)', 'We are seeking a dynamic and motivated Automated Test Engineer to develop and execute automated tests for our software and hardware designed by MiTek. In this position, you will be part of a high-performing and collaborative team. You will work closely with software developers, software quality and the product manager. This role is crucial in ensuring the quality and reliability of our products.\n\nResponsibilities: \n• Develop and verify the automated test cases on our existing software . \n• Work in an Agile software development environment (using Scrum), participate in meetings and collaborate with stack holders to ensure the quality of products \n• Track work status through issues tracking tool and report on the status of testing. \n• Identify, analyze, and document problems with program function, output, online screen, or content. And clarify if any questions \n• Perform testing activities from start to delivery of tasks and tracking status of found defects interact with stakeholders to help solve customer issues.\nYour skills and experience\n• 2+ years of experience identifying automation capabilities to support business process efficiencies\n• Good English communication and documentation skills \n• Proven experience as an Automated Test Engineer or similar role Experience in programming languages such as Python or C#. \n• Experience with test automation Robot Framework \n• Understanding of the Software Development Life Cycle (SDLC) and software testing methodologies \n• Possesses advanced functional or technical knowledge of complex problem-solving and process innovation. \n• High attention to detail and looks for ways to improve and promote quality; \n• Demonstrates accuracy and thoroughness. \n\nPreferred Qualifications: \n• Experience with Angular and Docker and HTML \n• Experience working with HMI for automated machines. \n• Experience Working with machine controllers, OPC UA\n\nWhy you\'ll love working here\n• Extremely competitive salary.\n• 13th month & productivity Bonus.\n• Yearly salary review.\n• Healthcare insurance package.\n• 24/24 Personal accident insurance.\n• State-of-the-art office environment.\n• Yearly outing.\n• Detailed induction, training and on-going career development.\n• Opportunity for overseas training and travel.\n• English training programs.\n• 5-day week.\n• Flexible start-times.\n• Free lunch.\n• Free parking.\n• Full Social Club including gym, yoga, football, badminton, swimming.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1267, 759, 2, 'C/C++ Developer (Fresher)', 'Our company is carrying out a maintenance project for banking system.\nMain job is to collaborate with customers for the maintenance and management of core banking system.\nResponsibilities\n-The tasks and responsibilities performed in the project are as follows:\n+ Implementing development and documentation on customer requirements\n+ Monitoring and providing technical support for operating systems\n+ Performing solutions through collaboration with customers\n-The basic development environment uses C/C ++/Proc C and Powerbuilder IDE Tool based on Oracle database and Tuxedo Middleware. In order to safely monitor the system, we operate using java script based on Node.js.\n-To this end, the project provides improving training in technical and overall work to ensure that all technicians meet job requirements\n\nRequirements:\n-Graduated from IT University or similar.\n-Bachelor degree is required.\n-Have experience on Backend systems using C/C++/Pro C (level Fresher - Pre Senior)\n-Experience in Java developing language (Java Core, Spring, Hibernate, etc.) or JavaScript/Node.JS is an advantage.\n-Experience in OOP/OOD, MVC.\n-Experience in Oracle, Design Patterns, Database concepts, Data Structure, Algorithms, and Distributed Services.\n-Welcome candidates having experience working in bank system.\n-Enthusiastic working attitude.\n-Working location: AGRISM site – Agribank An Khánh, Toà nhà HTCT2, Khu A5, Khu đô thị Nam An Khánh, Hoài Đức, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1268, 760, 2, 'Chuyên viên Vận Hành Hệ Thống Core Chứng Khoán', 'Địa điểm làm việc: Quận 1, TP. Hồ Chí Minh.\n\nMÔ TẢ CÔNG VIỆC\n- Vận hành hệ thống phần mềm Core Chứng khoán:\n- Nghiên cứu để hiểu rõ cách thức hoạt động của hệ thống phần mềm Core chứng khoán;\n- Vận hành hệ thống theo quy trình và checklist;\n- Tiếp nhận các yêu cầu hỗ trợ và phân tích, xử lý:\n- Nhận yêu cầu hỗ trợ từ khách hàng và các phòng ban nghiệp vụ liên quan đến: Kiểm tra lỗi phần mềm; Kiểm tra số liệu,...;\n- Phân tích & xử lý các yêu cầu hỗ trợ người dùng;\n- Tham gia triển khai dự án phần mềm:\n- Nghiên cứu cài đặt, vận hành và thử nghiệm các phần mềm mới theo yêu cầu\n- Đảm bảo tuân thủ đúng thời hạn của từng dự án theo quy định.\n\nYÊU CẦU CHUNG\n- Tốt nghiệp Đại học các chuyên ngành Công nghệ thông tin, Điện tử viễn thông,...;\n- Ít nhất 2 năm kinh nghiệm làm việc tại vị trí vận hành core của các ngành tài chính như: Chứng Khoán, Ngân hàng,...;\n- Có kiến thức hoặc kinh nghiệm sử dụng 1 trong các ngôn ngữ lập trình như Java, C++, tối thiểu 2 năm;\n- Kinh nghiệm làm việc trên môi trường Linux/Unix;\n- Có kinh nghiệm tham gia vào triển khai dự án; phát triển phần mềm tài chính là một lợi thế;\n- Ưu tiên các ứng viên có kiến thức về nghiệp vụ chứng khoán hoặc tài chính, ngân hàng,.....;\n- Khả năng làm việc độc lập, làm việc nhóm, và chịu được áp lực và trách nhiệm cao.\n\nQUYỀN LỢI\n- Hưởng mọi quyền lợi theo chính sách đãi ngộ từ công ty (bảo hiểm sức khỏe cao cấp, du lịch hàng năm,...);\n- Môi trường làm việc thân thiện, năng động, tạo điều kiện phát triển sự nghiệp;\n- Được hướng dẫn, đào tạo và tham gia việc huấn luyện tại công ty;\n- Nhiều phúc lợi khác khi gia nhập vào đội ngũ nhân sự năng động của MAS.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1269, 732, 2, 'Software Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nTechnologists at WorldQuant research, design, code, test and deploy projects while working collaboratively with researchers. Our environment is relaxed yet intellectually driven. We seek people who think in code and are motivated by being around like-minded people.\n\nThe Role: We are looking for exceptionally talented engineers to join our team. The team is responsible for building out a new business within WorldQuant, and this role involves software engineering on Data, Strategy, Trading, etc. You will be working with Quants very closely. Also you will have the opportunity to learn the full cycle of Quant business end to end.\n\nBuilding / improving the data layer\nBuilding the computational framework that runs our quant strategies\nWorking with Quant as pairs, provide technique support for Quants.\n\nWhat You’ll Bring\n\nTop university education. Experiences of participating ACM competitions is a plus.\nEducation degree higher then better. PhD degree is a plus.\nVery solid understanding of Data Structure and Algorithm\nCare about the conciseness and beauty of code. Already good at Python is a plus.\nExcellent communication skills (Will work with Quants closely)\n\nWhat We Offer\n\nCompetitive and attractive compensation package with clear career road-map – where you feel challenged everyday\nWe offer a strong culture of learning and development: training courses, library, speakers, share and learn events\nLearn from who sits next to you! Working in WQ you are surrounded by smart and talented people\nEmployee resources groups with strong diversity and inclusion culture\nPremium Health Insurance and Employee Assistance Program\nGenerous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\nTeam building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\nAnnual company trip and occasional global conferences – opportunity to travel and connect with our global teams\nHappy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Tsji Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1270, 740, 2, 'Fullstack Developer (Java/JS)', 'Job Description\n\nWork in a team of engineers to implement backend services in the platform\nBuild service definitions, OpenAPI specifications, SDKs, and documentation for other developers that consume these services\nIntegrate with other services and data sources using APIs, messaging systems, databases\nCollaborate with the DevOps team on microservices design, containerization, and automated deployments\nBuild automated test suites to ensure these services are reliable and performant\n\nRequirements\n\n2+ years of experience working with Java and one or more Java frameworks such as Spring Boot\nProject experience around web service design and RESTful APIs\nExpertise with the OpenAPI Specification (Swagger), RESTful APIs, and related tools such as Postman, cURL, and HTTPie\nExperience integrating with 3rd party services and databases such as Redis, message queues, MongoDB, and ElasticSearch\nAgile/SCRUM methodology experience\n\nSoft-skills\n\nPossible to co-work with team.\nGood at investigating and solving incident and problem skill.\nSelf-motivated and self-directed\n\nBenefits\n\nPackage: Package 14 salary months based on KPI + Extra package: 16M/year\nFull benefit with social insurance.\nAnnual health check and CMC care insurance under the company’s\nYoung and dynamic working environment.\nOpportunity to approach the newest technology trends\nExciting leisure: sports and art events (football club, family day…)\nThe company’s labor policy is entirely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trips, holidays, etc.)\n\nMinimum 2 years of experience in Java software development\n\nPlease send your application via email: recruitment@cmcglobal.vn\nYears of Experience Required\nRequired Education Level\nBachelor’s Degree\nJob Level\nJunior/Middle\nWork Form\nFull-time\nEmail: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1271, 698, 2, '[Hà Nội] Fullstack ( Java + Reactjs) Developer', 'MÔ TẢ CÔNG VIỆC:\n- Phát triển, tối ưu và bảo trì hệ thống web cho khách hàng Nhật Bản với Java (Spring Boot) ở backend & React ở frontend.\n- Tham gia toàn bộ SDLC: phân tích yêu cầu, thiết kế, coding, code-review, CI/CD và triển khai trên AWS.\n- Đề xuất giải pháp kỹ thuật, nâng cao hiệu năng (multithread, concurrency), đảm bảo bảo mật và chất lượng mã.\n- Mentor thành viên junior, phối hợp chặt chẽ với PM và khách hàng.\n\nYÊU CẦU:\n- Học vấn: Tốt nghiệp Đại học chuyên ngành CNTT hoặc liên quan.\n- Kinh nghiệm: 4 năm Java/Spring trong đó 2 năm React; từng đảm nhiệm vai trò full-stack.\n\nKỹ năng cốt lõi:\n- Java: OOP, Clean Code, Design Patterns; thuần thục Collection vs Stream, multithread/async; logging; đọc/ghi & migration dữ liệu DynamoDB.\n- DynamoDB: phân biệt và dùng đúng Query vs Scan, lấy dữ liệu bulk, thiết kế & sử dụng GSI hiệu quả.\n- React: quản lý state toàn cục với useContext hook, hiểu kiến trúc component, tối ưu render.\n- AWS: SSH vào EC2, xuất log, phát hiện & xử lý overload/instance die; kiến thức Auto-Scaling, CloudWatch là lợi thế.\n\nKhác:\n- MySQL hoặc NoSQL (MongoDB)\n- Thành thạo Git\n- Tư duy giải thuật tốt, tự học nhanh\n- Giao tiếp tiếng Nhật (N3+) là điểm cộng.\n\nCHẾ ĐỘ ĐÃI NGỘ:\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng kinh doanh cuối năm + thưởng dự án, thưởng các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe 24/24;\n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện);\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày;\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành;\n- Miễn phí đồ uống tại khu ăn uống của công ty;\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan;\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLUB Dance;...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm;...\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1272, 728, 2, 'Junior Backend Developer (Nodejs) - Offer up 19M', '1. INTRODUCTION\na. About Fetch:\nOur mission is to offer Vietnam’s most talented technologists a platform to connect with some of the world’s leading tech companies and build their expertise on a global scale. Over 4 years, Fetch has built a good reputation and is trusted by many Vietnamese and foreign companies; And Fetch will continue its good work to bridge the divide between the World and the Vietnam Tech sector.\nb. About Client:\nOur client has stood at the forefront of nurturing developer relationships and spearheading marketing efforts, ensuring tech products reach developers globally.\nProviding comprehensive support in developer relations and marketing for corporations, government bodies, and nonprofits, we\'ve partnered with over 250 esteemed entities such as Meta, Google, Mastercard, Intel, Nvidia, IBM, Circle, Polkadot, among others.\nWith a network exceeding 300,000 developers, our client has pioneered the organization of hackathons, online contests, acceleration initiatives, gatherings, and marketing strategies for developers in more than 100 cities worldwide.\n\n2. RESPONSIBILITIES\n- Write clean, efficient, and maintainable code. \n- Designs, codes or configures, tests, debugs, deploys, documents and maintains services using a variety of software development toolkits, testing/verification applications and other tools, while adhering to specific development best practices and quality standards.\n- Responsible for troubleshooting and issue analysis, as well as coding, testing and implementing software enhancements.\n- Perform performance analysis and optimization on high-traffic, high-volume systems.\n- Research test solutions for various problems scaling high-traffic, high-volume systems.\n\n3. REQUIREMENT\n- Minimum 2 years of experience in backend development, preferably in product-based companies.\n- Hands-on experience with Node.js and TypeScript, or other strongly typed programming languages.\n- Familiarity with the functional programming paradigm is a plus.\n- Good understanding of relational databases, especially MySQL. Able to write and optimize SQL queries.\n- Basic knowledge of system and database design, including normalization and common networking concepts (e.g., protocols, layers).\n- Awareness of asynchronous and concurrent programming (e.g., async/await, multithreading basics, coroutines, goroutines).\n- Exposure to scalable system components, such as message queues, caching, batch processing, and load balancing is a plus.\n- Experience with common tools such as Git, GitHub Actions, Swagger/OpenAPI, and optionally JMeter or similar.\n- Familiar with Redis or equivalent caching systems.\n- Basic knowledge of Docker and container-based development. Kubernetes knowledge is a bonus.\n\n4. WHY YOU‘LL LOVE WORKING HERE\n- MacBook or high-end laptop for working. \n- Attractive salary and annual salary review. \n- Working in a professional, friendly, well-equipped environment both with foreigners and Vietnamese.\n- With extensive on-the-job training, you will always have a chance to work with new emerging technologies.\n- 12 days annual leave per year.\n- 13th-month salary.\n- Enjoy diversified activities:  Free snacks, Weekly and Monthly Team-building, Company trips, Play Games (PlayStation, Board games), and Play Sports (Football, Badminton...).\n\n5. WORKING HOURS & LOCATION\n- Working hours: From 9 AM - 6 PM, Monday to Friday.\n- Location:  \n+ HN: 13th Floor, TTC Building - No.19, Duy Tan Street, Dich Vong Hau Ward, Cau Giay District, Hanoi.\nContact me via Zalo: 0938172076 (Minh Minh)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1273, 761, 2, 'Intern, Engineering and Technology', 'Internship\n\nAbout Us\n\nCoherent is a global leader in lasers, engineered materials and networking components. We are a vertically integrated manufacturing company that develops innovative products for diversified applications in the industrial, optical communications, military, life sciences, semiconductor equipment, and consumer markets. Coherent provides a comprehensive career development platform within an environment that challenges employees to perform at their best, while rewarding excellence and hard-work through a competitive compensation program. It\'s an exciting opportunity to work for a company that offers stability, longevity and growth. Come Join Us!\n\nNote to recruiters and employment agencies: We will not pay for unsolicited resumes from recruiters and employment agencies unless we have a signed agreement and have required assistance, in writing, for a specific opening.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ap An Thuan, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1274, 762, 2, 'Java Software Engineer', 'About the company\nWorking Location: District 1, HCMC (On-site)\nDomain: Fintech\nInterview: 2-3 rounds\nSeniority: Middle - Senior (3+ YoE)\n\nResponsibilities\nDesign solutions involving integration with multiple systems and services\nDevelop high volume, high performance, low latency and reliable mission critical applications\nWrite maintainable, robust, and testable code\nPerform code and test case review\nImplement processes, solutions or tools to improve software delivery and quality\nAble to adopt latest software development trends and industry best practices\n\nQualifications\nBachelor degree in computer science or relevant fields\nSoftware development experience in the finance, payment or banking industry is preferred\nExcellent communication, presentation and leadership skills\nExcellent knowledge in Java and one other programming language\nExcellent knowledge of Relational Databases, SQL and ORM technologies\nStrong foundation in frameworks such as Spring, jUnit, etc. Hands on experience in designing and developing applications using Spring & web services technologies.\nGood communication in Vietnamese and English are mandatory as the role requires working with Vietnamese and international teams.\nAble to work in a fast paced and result driven environment\n\nFor more information, kindly reach me via:\nPhone/ Zalo: 0968803561\nEmail: uyen.nguyen@ev-search.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1275, 702, 2, 'Pioneer Talent Program - Frontend Engineer (Compliance AI)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 230 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nAbout The Pioneer Talent Program\n\nAre you an early-career professional ready to kickstart your career in the dynamic world of blockchain? Binance’s Pioneer Talent Program is designed to nurture ambitious individuals like you. The program offers full-time roles where participants will gain hands-on expertise via a tailored training curriculum and personalized 1:1 mentorship from industry leaders. Dive behind the scenes of the world’s leading blockchain ecosystem while building the skills to thrive in Web3. Launch your career with purpose—join us in shaping the future of digital innovation.\n\nWho May Apply\n\nCandidates with up to 5 years of relevant work experience\n\nResponsibilities:\n- Design, develop, and maintain advanced web applications for Binance\'s internal teams, including AI-driven products and other business-critical applications.\n- Collaborate with cross-functional and cross-country teams to define, design, and implement new features across various projects.\n- Integrate and efficiently utilize third-party data sources, APIs, and AI models where applicable.\n- Develop and execute comprehensive unit tests to ensure code robustness, including handling edge cases, usability, and reliability.\n- Manage and oversee the feature launch release lifecycle, ensuring seamless integration across all product areas.\n- Troubleshoot issues, fix bugs, and optimize application performance.\n\nRequirements:\n- 2+ years of experience in developing production-ready web applications using JavaScript.\n- BS or MS degree in Computer Science, Engineering, or a related field required.\n- Must have experience with React and Vue; experience with other frontend frameworks is welcome.\n- Proven track record of delivering projects with high-quality UI across diverse application areas.\n- Preferred work experience in an exchange (cryptocurrency or traditional), financial or banking institution, eCommerce, or payments processing.\n- Strong experience in working with remote data via REST, JSON, and AI model APIs.\n- Demonstrated experience in using AI tools and technologies in daily work to enhance productivity and innovation.\n- Interest and knowledge in the crypto/blockchain/technology space preferred, with a keen interest in AI technologies.\n\nWhy Binance\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team).\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1276, 366, 2, 'Frontend Engineer (JavaScript/ReactJS) - Naver Services', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nYour daily tasks:\n\n- Develop NAVER Services\n- Design and implement Frontend services\n- Implement SSR, CI/CD Monitoring\n- Co-working with Korea teams\n\nYour background:\n\n- Should have the knowledge of advanced ReactJs\n- Ideally, 5+ years of work experience on Frontend to serve large-scale and high-traffic projects\n- Enjoy discussions about the stability and scalability of Frontend systems;\n- Good understanding of asynchronous request handling partial page updates, AJAX, NodeJS, SSR\n- Experience in Data Structure, Algorithm, Distributed Service\n- Understand the importance of writing high Maintainable Code, Clean Code\n- Open-minded, honest and have a positive attitude towards people\n- Good at communication skills in general and English skills in particular\n\nIt\'s a big plus if you:\n\n- Ideally, 1+ year of technical lead experience\n- Have experience in development with Node.js and Next.js\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1277, 763, 2, 'Full Stack Software Engineer', 'This position is onsite at our office in Ho Chi Minh City, Vietnam.\n\nAre you a talented engineer with passion to build beautiful, easy to use apps for users? Combine not only technical knowledge in Full-Stack JavaScript, Node.js, React.js but also your business acumen in learning and understanding how your apps add value to users. Join us to continue expanding our unique B2B SaaS app portfolios with already over 30,500 customers.\n\nAbout Us\n\nAt OptiSigns, we believe technology should be accessible and valuable to everyone, including non-technical users. Our mission is to create beautiful, user-friendly B2B SaaS applications that add real value to society. By helping businesses connect better with their customers and employees, we aim to drive revenue growth and enhance operational efficiency.\n\nResponsibilities\n\n- Work on the design and development of apps from concept to production.\n- Develop and maintain front-end components using modern JavaScript, TypeScript frameworks such as React.js or Angular.\n- Implement server-side logic and APIs using Node.js, Express.js, Nest.js or other back-end technologies.\n- Design and optimize database schemas and queries using relational and/or NoSQL databases.\n- Write clean, efficient, and maintainable code adhering to coding standards and best practices.\n- Collaborate with product managers, designers, and other stakeholders to define and prioritize features.\n- Stay up-to-date with emerging technologies and industry trends, and advocate for their adoption when appropriate.\n\nRequirements\n\n- 2-5+ years of experience in full-stack web development, with a strong focus on both front-end and back-end technologies.\n- Proficiency in front-end frameworks such as React.js, AngularJS.\n- Proficiency in back-end technologies such as Node.js, Express.js, Nest.js.\n- Experience with database systems such as MySQL, PostgreSQL, MongoDB, or Redis.\n- Strong problem-solving and analytical skills, with a track record of delivering scalable and reliable solutions.\n- Excellent communication and teamwork skills, with the ability to collaborate effectively with cross-functional teams.\n\nBenefits\n\n- Opportunity to travel and work at our U.S. office in Houston, TX\n- Latest Macbook Pro\n- Competitive Pay\n- Company Trip\n- Paid time off\n- Insurance', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1278, 753, 2, '[MEP team] Game Designer', 'OBJECTIVES \n\nWe are seeking an exceptional and innovative Game Designer to join our team in building, developing, and publishing multiple game portfolios. As a Game Designer, you will collaborate closely with passionate cross-functional teams to create extraordinary experiences for players worldwide.\n\nWhat You Will Do\n\n- Monitor, collect, and analyze in-game player data, conduct market research to synthesize insights, and transform these insights into actionable recommendations.\n- Brainstorm & consolidate ideas from team members to propose design solutions.\n- Take a lead in a high performance team (Music, Creative, Artist, Quality Control, User Acquisition) to ensure you will deliver the game that makes users love.\n- Maintain a game roadmap, prioritizing initiatives based on business impact.\n\nTechnical Skills Requirements\n\n- Minimum of 1-2 years of experience as a Game Designer, Product Owner for one or more mobile game products.\n- Proven expertise in game design, core loop, and monetization strategies for diverse revenue models (ads, in-app purchases, hybrid) is highly desirable.\n- Strong game analysis skills: applicants must be able to intelligently deconstruct & discuss the strengths and weaknesses of games\' design and experience.\n- Strong critical thinking and analytical skills, able to work effectively in a data-informed environment.\n- Good sense of user experience & psychology in user design.\n\nSoft Skills Requirements\n\n- A reliable, independent, and responsible individual.\n- Demonstrates a strong interest in and understanding of technology, marketing, analytics, and data-driven solutions.\n- A proactive learner who is eager to acquire new skills and stay updated on mobile market trends.\n- Experience creating wireframes, mockups, prototypes, and user interaction diagrams.\n- Practical application of Agile methodologies.\n- Fluent in English, both written and spoken.\n- An effective communicator capable of sharing ideas, discussing projects, and providing constructive feedback.\n\nWhat We Offer\n\n- Competitive salary and benefit packages.\n- ESOP package for all levels.\n- Personal learning and well-being budget\n- Team-building budget\n- Lunch and parking allowance\n- Minimum 12 days of paid annual leave, plus 10 days of paid sick leave.\n- 12 days working from home per year.\n- Opportunity to work on exciting mobile game projects.\n- Collaborative and supportive team environment.\n- Continuous learning and growth opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1279, 715, 2, 'Chuyên viên chính Trí tuệ nhân tạo', 'Nơi làm việc: Hà Nội/ TP. Hồ Chí Minh\n\nThời gian: Full-time\n\nMô tả công việc:\n- Nghiên cứu và phát triển nền tảng AI trên hệ điều hành linux tích hợp các loại chip AI phổ biến, tích hợp vào nền tảng MLOps - Serving và Training, phát triển các luồng trong nền tảng AI\n- Tối ưu giải pháp AI kết hợp giữa xử lý Biên và xử lý trên Cloud \n- Giải quyết các bài toán cụ thể về AI nhằm đề xuất cho khách hàng các trải nghiệm liên quan đến sản phẩm\n- Nghiên cứu các giải pháp công nghệ cho các bài toán AI \n- Định hướng nghiên cứu, tìm hiểu nội dung và xu thế công nghệ trên thế giới.\n- Xây dựng quy trình, kế hoạch, gắn kết-điều hành công tác nghiên cứu của nhóm thuật toán, kiểm tra đánh giá các công việc trong nhóm, training chuyên môn cho thành viên trong nhóm.\n\nYêu cầu công việc:\n- Tốt nghiệp Thạc sỹ trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính hoặc các chuyên ngành kỹ thuật khác liên quan.\n- Trình độ tiếng Anh tương đương tối thiểu 650 điểm Toeic.\n- Có ít nhất 5 năm kinh nghiệm trong lĩnh vực trí tuệ nhân tạo.\n- Thành thạo ít nhất một trong những ngôn ngữ lập trình C++, Python, Java. \n- Am hiểu về các mảng nghiệp vụ của AI, có chuyên môn sâu về ngành Xử lý ảnh số, đồng thời có ít nhất 3 năm kinh nghiệm giải quyết các project liên quan đến computer vision.\n- Có kinh nghiệm triển khai mô hình AI trên thiết bị\n- Có kỹ năng thiết lập kế hoạch nghiên cứu, quản lý và biểu đạt tốt, tạo được động lực làm việc cho các thành viên trong nhóm.\n- Ưu tiên ứng viên có kinh nghiệm về các dự án SLAM\n- Ưu tiên ứng viên có kinh nghiệm về model compression và model optimization (trên thiết bị).\n- Ưu tiên ứng viên có kinh nghiệm quản lý\n- Ưu tiên ứng viên đã có paper (trên các tạp chí uy tín), patent.\n\nChế độ đãi ngộ:\n- Được hưởng các khoản quà, thưởng lễ tết, nghỉ mát hỗ trợ ăn trưa, điện thoại liên lạc tối thiểu 2.000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\n- Được hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\n- Được hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\n- Được trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\n- Có cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\n- Được cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\n- Có cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1280, 764, 2, 'BrSE (Bình Thạnh, HCM) - Upto 3000$', 'MÔ TẢ CÔNG VIỆC\n- Quản lý nhóm thực hiện các dự án phát triển hệ thống web của công ty, thiết kế hệ thống và phân tích các hệ thống đã phát triển.\n- Truyền đạt các yêu cầu phát triển hệ thống từ trụ sở chính tại Nhật Bản tới các thành viên.\n- Tạo kế hoạch phát triển phần mềm từ design đến testing và quản lý dự án theo đó.\n- Đặt ra mục tiêu về chất lượng, chi phí, delivery và function, cũng như quản team để đạt được các mục tiêu đó.\n- Đánh giá và gửi feedback cho các thành viên.\n\nYÊU CẦU\n- N2 trở lên.\n- Có kinh nghiệm code PHP hoặc Java (ưu tiên PHP)\n- Kinh nghiệm phát triển Web System, ưu tiên có kinh nghiệm làm việc trong E-commerce.\n- Kinh nghiệm thiết kế DB, quản lý và cấu hình Server.\n- Khoảng 2 năm kinh nghiệm quản lý team.\n\nPHÚC LỢI\n- Thưởng theo dự án hàng tháng + Bonus tháng 13.\n- Đánh giá lương: 1-2 lần/năm.\n- Tổng số ngày nghỉ phép hưởng lương hàng năm 17 ngày (bao gồm 5 ngày nghỉ hè: chế độ đặc biệt chỉ có ở Rivercrane).\n- Gói bảo hiểm sức khỏe đặc biệt 2,5 ~ 3,5 triệu/ nhân viên/ năm.\n- Cơ hội được công ty đài thọ toàn phần đi onsite tại Nhật Bản trong 3 tháng.\n- Company Trip hàng năm.\n- Câu lạc bộ thể thao (bóng đá, bóng bàn, bi lắc, game online,…).\n- Được training và giao cơ hội thực hiện các kỹ năng để trở thành cấp quản lý cấp cao.\n- Chế độ chu cấp kinh phí (300$ ~ 1000$/người) tham gia các lớp nâng cao kiến thức kĩ thuật, softskill tại các trung tâm đào tạo uy tín.\n- Ngày hội toàn thể nhân viên và gia đình vào tháng 7 hàng năm.\n- Thứ 6 hàng tuần từ 14:30 trở đi là giờ tự nghiên cứu để nâng cao kiến thức.\n- Bảo hiểm bắt buộc được đóng trên lương gross.\n- Công ty đào tạo tiếng Nhật miễn phí, làm việc lâu dài tại Tokyo Nhật Bản.\n\nTHỜI GIAN LÀM VIỆC:\nT2-T6, 08h-17h\n\nĐỊA ĐIỂM:\nToà nhà EBM, 683-685 Điện Biên Phủ, Bình Thạnh', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه هو شي مينه سيتي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1281, 490, 2, 'Frontend developer', 'Are you looking for an opportunity to make an impact, grow your skills and catapult your career with a growing company?\n\nMealSuite is looking for a Frontend Developer to join our development team on our mission to revolutionize the continuum of care through our all-in-one foodservice management technology.\n\nOur International Development team\'s mission is to build innovative solutions that help our customers in senior living and healthcare industries enhance the mealtime experience for their patients and residents. In an industry that is constantly evolving, MealSuite\'s software comes with a promise for continual innovation and growth with our customers. We never stop pushing boundaries and are always steering the future of our industries as innovation leaders in our space.\n\nAs part of our Development team, your mission is to stay on top of the latest releases, contribute to projects, and deliver the best quality solutions for our customers.\n\nResponsibilities\n\n- Create, test, maintain web application and mobile application\n- Write, review, and maintain code in compliance with the established coding quality standards of the company\n- Write unit test and run through all the test cases for assigned tasks and ensure all cases are tested and passed before release for testing\n- Turn UI/UX designs into prototypes, creating excellent interactions from designs\n- Optimize application for maximum performance\n- Build reusable components for future use\n- Collaborate with back-end developers and web designers to improve usability\n- Be an active contributor during the project specification and requirement gathering phase\n- Identify problem areas and bring relevant changes\n- Self-train on new technologies\n- Others urgent task provided by leader or manager \n\nRequirements\n\n- 4 years + of overall proven software development experience, focusing on web/mobile application and front-end technologies\n- Proficient understanding of code versioning tools (GIT is preferred)\n- In-depth understating of HTML/CSS, JavaScript/Typescript and pre-processing languages such as LESS/SASS/SCSS\n- Intensive experiences of working with building front-end APIs\n- Experiences of front-end frameworks (e.g. Angular, Stencil, React)\n- Experiences of building web Native apps (e.g. Capacitor)\n- Experiences of layout techniques and frameworks (e.g. Ionic, Bootstrap)\n- Experience of unit testing frameworks (e.g. Jest, Jasmine, Cypress)\n- The ability to demonstrate hands-on experience in using current trends and best practices in front-end architecture, including performance optimization, accessibility, and usability\n- Outstanding problem-solving skills\n- Must be able to work flexible hours\n\nBenefits\n\n- Stock option\n- Vietnam labor law contract with full benefits\n- 1 day work remote every week\n- 18+ days annual leave\n- 100% probation salary\n- Unlimited access to online learning courses such as Udemy\n- Macbook pro provided\n- Free snacks & beverages\n- Flexible working time\n- Team events\n- Awesome and meaningful products', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1282, 247, 2, 'Java Developer', 'Murex is a global fintech leader in trading, risk management and processing solutions for capital markets.\n\nOperating from our 19 offices, 3 000 Murexians from over 60 different nationalities ensure the development, implementation and support of our platform which is used by banks, asset managers, corporations and utilities, across the world.\n\nJoin Murex and work on the challenges of an industry at the forefront of innovation and thrive in a people-centric environment.\n\nYou’ll be part of one global team where you can learn fast and stay true to yourself.\n\nMain activities to be performed.\n\n- Develop expertise in Murex interface solutions and general knowledge of the platform \n- Design, develop, test, deploy and maintain Systems Integration software \n- Validate solutions with co-workers within the team and seek advice and expertise of other teams \n- Study functional specifications and translate them to technical design \n- Document code throughout the development process \n- Work within Agile Framework practices \n- Enhance product quality by detecting bugs at an early stage: Be an advocate of automation, Test Driven Development, Continuous Integration and Continuous Delivery \n- Continuously learn and improve Functional, Technical and Leadership skills \n- Maintain good understanding and knowledge of the development best practices \n\nJob Requirements\n\n- Bachelor’s degree in computer science or engineering and/or equivalent experience \n- 1-4 years of experience \n- Excellent skills in programming language JAVA \n- Good skills in Object Oriented Programming \n- Experience with Enterprise Integration Patterns will be well regarded \n- Communication skills: Excellent written and verbal English is a must \n- Teamwork and cross-team collaboration \n- Analytical thinking and Problem solving \n- Drive for excellence \n- Eagerness to learn and develop', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1283, 765, 2, 'Software Engineer (Vietnam)', 'About Copado\n\nCopado is the #1 DevOps Platform for Salesforce and the Cloud. We harness the power of native CI/CD and Robotic Testing to drive digital transformation for 1,000+ of the most innovative brands on the planet — from Coca-Cola to eBay to Volkswagen. Our low-code platform unites non-technical admins and pro-code developers on the same system and empowers enterprises to scale end-to-end software delivery across multi-cloud environments.\n\nThe impact on your business? 20X faster releases, 94% fewer production bugs and 46% more Salesforce ROI. The impact on your team? No more late nights, weekend war rooms or stressful release days.\n\nBrief Summary Of Role\n\nThis role will be an individual contributor to be part of the development squad for Copado’s Essential’s DevOps application for the Salesforce platform. Copado Essentials has a rapidly growing global user base of over 10,000 enthusiastic users. We like to say that Salesforce DevOps starts with Copado Essentials. Essentials provides a simple, fast way for Salesforce developers to select and deploy Salesforce metadata between orgs. The premium edition, called Essentials+, adds version control to provide small development teams with the ability to detect merge conflicts, roll back changes, and a record for audit purposes.\n\nWhat You’ll Be Doing\n- Design & engineer elegant, yet scalable DevOps solutions that delight our users.\n- Bring an “AI first” mindset to product development and product features.\n- Ensure quality assurance by setting standards for unit tests, security tests and automated UI tests.\n- Support and maintain Essentials software releases and AWS infrastructure. Work with the development team to ensure system reliability & performance.\n- Partner with the Product team to align on features, build plan and product roadmap.\n\nWe Are Looking For Someone With\n- Passionate about software engineering craftsmanship.\n- Demonstrated ability to write secured, modular, clean and well tested code.\n- Strong understanding of object-oriented design patterns.\n- Fast learner with an interest to solve challenging problems at scale.\n- 2+ years of software engineering experience at innovative and fast-paced organizations.\n- Fluency in Java and the related ecosystem.\n- Salesforce experience is a plus.\n- Experience with modern Javascript framework (ie. Angular, React) is a plus.\n- Experience using and developing AI solutions is a plus.\n- Experience with building scalable web-based Saas products is a plus.\n- Experience with AWS infrastructure and scaling operations is a plus.\n- Open source contribution is a plus.\n- Proficient in both verbal and written English communication skills\n\nDisclaimer: Copado is Equal Employment Opportunity and Affirmative Action Employers. Qualified applicants will receive consideration for employment without regard to race, color, religion, sex, sexual orientation, gender perception or identity, national origin, age, marital status, protected veteran status, or disability status. Copado does not accept unsolicited headhunter and agency resumes. Copado will not pay any third-party agency or company that does not have a signed agreement with Copado.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1284, 450, 2, 'Software Engineer - Frontend', 'Our Journey\n\nShopBack began in 2014 as a late-night spark of inspiration between Henry and Joel — not just to build a Cashback platform, but to reimagine how brands and consumers connect. As former advertisers, they understood the limitations of traditional marketing, and saw an opportunity to deliver more value on both sides. That idea quickly turned into action, with the first prototype built during a 24-hour sprint. Today, ShopBack serves over 50 million users across 13 markets, partners with 20,000+ merchants, and powers over half a million transactions daily. We\'re building The World’s Most Rewarding Way to Shop — and looking for bold, driven individuals to join us.\n\nAbout The Role\n\nWe are seeking team members who strive to solve hard problems, take pride in delivering world-class products, and are strong team players.\n\nYou are someone who wants to see the impact of your work making a difference every day. You find passion in the craft and are constantly seeking improvement and better ways to solve tough problems.\n\nYour Adventure Ahead\n\n- Contribute to the ideation, technical design, implementation, and testing of product features that empower our business and deliver impact to our customers.\n- Produce high-quality software following good architecture and design principles that are scalable.\n- Design and deliver well-thought-out user interfaces with a strong sense of the overall user experience.\n- Collaborate with the team to define the future of the ShopBack experience.\n- Strong mentoring skills with the ability to provide technical guidance and review code.\n\nEssentials To Succeed\n\n- 2+ years of experience building and designing delightful user experiences as a frontend engineer.\n- Good knowledge of HTML, CSS, and JavaScript.\n- Understanding of good software design principles and have applied principles to professional work.\n- Hands-on experience working with ReactJS (Preferred) and ecosystem.\n- Have knowledge in Test Driven Development (TDD), CI/CD.\n- Familiarity with RESTful APIs and TypeScript.\n- Ability to work effectively in a fast-paced, complex technical environment with high adaptability and flexibility.\n\nShopBackers\' DNA\n\n- Grit - We tackle all challenges head-on, working together to solve problems and achieve success.\n- Hunger - We value hard work, and having relentless drive.\n- Speed - We move fast and have a bias for action, all to deliver maximum impact.\n- Impact - We focus on results, always aiming for the best possible outcomes and timelines.\n- Growth - We embrace a growth mindset, constantly striving to learn, improve, and excel in our roles.\n\nExclusively for ShopBackers\n\n- Career progression paths and opportunities to take on greater challenges that help you realise your ambitions.\n- Be part of a winning team on a journey to global scale.\n- Competitive compensation based on your performance.\n- Candid, open, and collaborative culture where feedback is valued, for everyone to grow and improve every day.\n- Work-From-Anywhere benefit to enable you to thrive personally and professionally.\n\nShopBack is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. We do not discriminate on the basis of race, color, religion, sexual orientation, national origin, age, disability, genetic information, veteran status, or any other protected status under applicable laws. Join our team and help us make a difference!\n\nWe are committed to protecting your data and ensuring fairness in our recruitment process. As part of this process, we use AI tools to assist with tasks such as application screening and candidate matching. These tools are designed to enhance efficiency and reduce bias, and their use complies with applicable data protection laws and our commitment to fair employment practices. Your personal data will be processed securely and transparently, and final hiring decisions are always made by our recruitment team, not by automated systems. If you have any questions about how your data is used, or wish to exercise any of your rights including the right to such processing, please contact us at dpo@shopback.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh e Região', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1285, 755, 2, 'Junior Android Engineer - Hybrid working model 100%, Ho Chi Minh City', 'Company Description\n\nWelcome to SMG Vietnam! SMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nJob Description\n\nThis job refers to our Real Estate brands, Homegate and Immoscout24, the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing.\n\nWe are looking for an Junior Android Engineer who is passionate about mobile development and eager to work on high-quality Android application. As a key contributor to our mobile engineering team, you will focus on delivering clean, efficient, and reliable code, working closely with other engineers, designers, and product managers. This role is ideal for an engineer looking to deepen their Android expertise and contribute to complex projects in a supportive environment.\n\nJoin our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nYour Mission:\n- Assist in designing, developing, and maintaining Android applications, focusing on clean, maintainable code. \n- Collaborate closely with product managers, designers, and senior engineers to implement new features and enhancements. \n- Participate in code reviews, learn from feedback, and apply best practices to improve code quality. \n- Write Unit and UI tests with guidance to ensure code reliability. \n- Learn and apply modern Android architecture patterns to build scalable features. \n- Continuously improve your skills and contribute to the team\'s knowledge-sharing culture. \n- Help identify and fix bugs, optimize performance, and support releases under the guidance of more experienced team members. \n- Stay curious and up-to-date with Android development trends, tools, and best practices. \nYour responsibilities will evolve as we grow.\n\nQualifications\n\nWhat will you bring to the ride?\n- Fluency in English written and verbal communication. \n- Bachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience. \n- 1+ year of experience developing Android applications in Kotlin (Java is a plus). \n- Basic understanding of Android components and tools (e.g., Activities, Fragments, Android Studio). \n- Some exposure to modern development practices such as MVVM, Jetpack components, or reactive programming is a plus. \n- Willingness to learn and apply best practices in mobile development, testing, and architecture. \n- Comfortable with consuming REST APIs and working with local storage (e.g., Room, SharedPreferences). \n- Curious, open-minded, and enthusiastic about growing in a collaborative team environment. \n\nNice-to-Have Qualifications:\n- Exposure to CI/CD, version control (e.g., Git), or test automation frameworks. \n- Awareness of mobile app performance and monitoring tools (e.g., Firebase, Datadog). \n- Familiarity with privacy, security, or accessibility in mobile apps. \n\nWe value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique.\n\nAdditional Information\n\nWhat do we offer?\n- Competitive Benefits: Attractive salary, full pay during probation, 13th-month bonus, and full social insurance contributions. \n- Generous Leave: 21+ annual paid days off, 24 days for learning & sharing, and flexible working hours with no overtime. \n- Health & Wellness: Premium private insurance for you and your family, free food, and access to various classes and clubs. \n- Growth Opportunities: Personalized development plans, yearly education budgets, regular Hackathons, and potential travel to Switzerland and Europe. \n- Modern Work Environment: Hybrid model, top-tier equipment, and a friendly, agile, and transparent culture. \n- Supportive Onboarding: Comprehensive assistance to help you settle in. \n\nRecruitment Process \n\nWe believe hiring is a two-way street, where both parties get to know each other. Here\'s what you can expect:\n- Initial screening call with HR – A brief conversation to understand your background and expectations. \n- Meeting with the Hiring Manager – A deeper discussion about the role, your experience, and how we work. \n- Home assignment – A small project to showcase your skills in a real-world context. \n- Technical Assessment – A follow-up session to review your assignment and discuss technical topics in more detail. \n- Casual Meeting with Director – An informal conversation to align on vision, culture, and goals. \n\nAt SMG Vietnam, we value diverse perspectives and individual growth. We welcome candidates from all backgrounds and encourage you to apply, even if you don’t meet every requirement. Together, we embrace differences, nurture potential, and celebrate success.\n\nApply now\n\nTo take this opportunity, send us your detailed CV and feel free to add any supporting documents we need to look at in order to understand that you are the perfect fit.\n\nAbout Us\n\nSMG Swiss Marketplace Group AG. is a pioneering network of online marketplaces and cutting-edge European digital company that simplifies people’s lives with innovative products. SMG Swiss Marketplace Group AG. provides customers the best tools to meet their life decision needs. The portfolio includes Real Estate (ImmoScout24, Homegate, Flatfox, alle-immobilien.ch, Immostreet.ch, home.ch, Publimmo, Acheter-Louer.ch, CASASOFT, IAZI), Automotive (AutoScout24, MotoScout24), General Marketplaces (anibis.ch, tutti.ch, Ricardo) and Finance & Insurance (FinanceScout24, moneyland.ch).\n\nThe company was founded in November 2021 by TX Group AG, Ringier AG, La Mobilière and General Atlantic.\n\nDisclaimer\n\nSMG Swiss Marketplace Group AG primarily engages directly with candidates. We do not accept unsolicited resumes or candidate profiles from recruitment agencies unless we have specifically requested their assistance for particular roles. Any submissions made without a prior request from our Talent Acquisition team will not be acknowledged or considered. We appreciate the understanding and cooperation of recruitment agencies in respecting this policy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1286, 766, 2, 'Lập Trình Viên PHP 7~15 triệu', 'Mô tả công việc\n\n• Tham gia trực tiếp vào dự án đang phát triển tại công ty, nắm bắt và phân tích các yêu cầu của khách hàng.\n• Phát triển các phần mềm ứng dụng trên điện thoại di động;\n• Thực hiện lập trình web theo yêu cầu khách hàng.\n• Code dự án với PHP.\n• Cụ thể sẽ trao đổi kỹ khi tham gia phỏng vấn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1287, 767, 2, 'MMORPG Game Developer (Fresher/Experienced)', 'Năng lực chung\n\n• Niềm đam mê và sự hứng thú với phát triển trò chơi\n• Thái độ tích cực và kỹ năng giao tiếp chủ động\n• Tinh thần trách nhiệm cao đối với các nhiệm vụ được giao\n• Tư duy logic và khả năng giải quyết vấn đề sáng tạo\n\nKỹ năng cụ thể cho công việc\n\n• Hiểu và triển khai lập trình hướng đối tượng\n• Hiểu và triển khai lập trình đa luồng\n• Hiểu và triển khai lập trình mạng\n• Kỹ năng thiết kế lược đồ cơ sở dữ liệu và triển khai quy trình\n• Hiểu và triển khai nhiều cấu trúc dữ liệu và thuật toán khác nhau\n\nKỹ Năng Được Ưu Tiên\n\n• Kinh nghiệm phát triển máy chủ trò chơi trực tuyến\n• Kinh nghiệm sử dụng công cụ máy chủ thương mại\n• Kinh nghiệm phát triển trong môi trường Linux\n\n[English version]\n\nGeneral Competencies\n\n• Passion and dedication to game development\n• Positive attitude and proactive communication skills\n• Strong sense of responsibility for assigned tasks\n• Logical thinking and creative problem-solving abilities\n\nJob-Specific Skills\n\n• Understanding and implementation of object-oriented programming\n• Understanding and implementation of multithreaded programming\n• Understanding and implementation of network programming\n• Database schema design and procedure implementation skills\n• Understanding and implementation of various data structures and algorithms\n\nPreferred Qualifications\n\n• Experience in online game server development\n• Experience using commercial server engines\n• Experience in development within Linux environments', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 7, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1288, 747, 2, 'Associate Java Engineer', 'Your responsibilities\n- Participate in innovative software development life cycle using agile methodologies.\n- Adhere to the coding standards, best practices, common design patterns & principles.\n- Produce efficient and high quality code via learning on the job.\n\nYour qualifications\n- Bachelor\'s degree in computer science or equivalent.\n- Good knowledge of OOP, SOLID principles, Design pattern, data modeling.\n- Able to read and write technical documents in the English language.\n- Passionate, pro-active and keen to learn new technologies.\n\nNice to have \n- Knowledge of the Agile methodology (Scrum).\n- Knowledge of JavaScript, HTML, XML, CSS.\n- Knowledge of Web development (Angular, ReactJS) or Windows App development.\n\nWhy you\'ll love working here\n- Professional European-based company\n- Attractive salary\n- Performance bonus of up to 4 months‘ salary\n- Opportunities for travel to Europe\n- Hybrid home/office working model\n- Flexible working time\n- Structured training & development roadmap\n- Good work-life balance\n- Premium healthcare insurance\n- Loyalty programs\n- Well-being activities\n- Annual company trips and team-building events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1289, 702, 2, 'Binance Accelerator Program - Backend Engineer (Content)', 'Binance is the global blockchain company behind the world’s largest digital asset exchange by trading volume and users, serving a greater mission to accelerate cryptocurrency adoption and increase the freedom of money.\n\nAre you looking to be a part of the most influential company in the blockchain industry and contribute to the crypto-currency revolution that is changing the world?\n\nBinance Accelerator Program is a concise 3 - 6 months program designed to have an immersive experience in the rapidly expanding Web3 space. You will be given the opportunity to experience life at Binance and understand what goes on behind the scenes of the world\' s leading blockchain ecosystem. Alongside your job, there will also be a focus on networking and development, which will expand your professional network and build transferable skills to propel you forward in your career. You will be hired under a junior fixed term contract.\n\nResponsibilities\n\n- Participate in the design, development, and optimization of the recommendation system to improve recommendation performance and user experience.\n- Research and apply technologies such as machine learning, data mining, and natural language processing to enhance recommendation algorithms.\n- Analyze user behavior data to uncover user needs and interests, and propose personalized recommendation strategies.\n- Assist with large-scale data processing and feature engineering to support the implementation of recommendation algorithms.\n- Collaborate closely with product and engineering teams to drive the iteration and innovation of the recommendation system.\n- Currently pursuing a Bachelor\'s or Master\'s degree in Computer Science, Software Engineering, Data Science, Statistics, or a related field.\n- Familiar with common machine learning algorithms and recommendation system models such as collaborative filtering, matrix factorization, and deep learning.\n- Strong programming skills and proficiency in languages such as Python or Go.\n- Good understanding of data structures and algorithms, with the ability to write efficient code.\n- Some experience in deep learning frameworks like TensorFlow or PyTorch is a plus.\n- Good analytical and problem-solving skills, with the ability to learn new technologies quickly.\n- A team player with good communication skills and proactiveness.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1290, 768, 2, 'C++ Graphics Programmer', 'Job Overview:\nTechChup is a leading technology company that specializes in developing high-performance software solutions. We are seeking a C++ Graphics Programmer to join our team in creating desktop software. In this role, you’ll contribute to developing dynamic, user-focused tools that deliver an engaging experience.\n\nResponsibilities\n• Develop and maintain real-time animation systems using modern C++.\n• Implement visual behaviors, motion logic, and animation blending.\n• Integrate models, textures, sounds, and animations into a seamless experience.\n• Work collaboratively with designers and artists to bring expressive interactions to life.\n• Optimize application performance across platforms with a focus on smooth animation and low resource usage.\n\nRequired Qualifications\n• Bachelor’s degree in Computer Science, Software Engineering, or a related field.\n• Minimum 1 year of professional experience in C++ development.\n• Proficiency in C++ with a strong grasp of object-oriented design.\n• Experience with graphics APIs like OpenGL, DirectX and/or frameworks like SDL.\n• Understanding of animation techniques, rendering pipelines, and asset integration.\n• Strong debugging, optimization, and cross-platform development skills.\n\nPreferred Qualifications\n• Experience developing animated character-driven software or user experiences.\n• Exposure to simple AI-driven behaviors, state machines, or behavior trees.\n• Comfort working with design teams on expressive, user-facing features.\n• Ability to balance performance with high visual fidelity in animation-rich applications.\n• Familiarity with creative tools (e.g., Adobe Creative Suite, Figma, Blender) to work effectively with designers or generate assets directly.\n• Familiarity with game engines like Unreal, Unity, Godot.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1291, 723, 2, 'Kỹ sư CNTT: PHP/JAVA Developer, IT phần cứng mạng', '1. Mô Tả Công Việc\n\n- Tham gia xây dựng và phát triển hệ thống call center trên nền mã nguồn mở.\n- Phát triển các ứng dụng call center base Cloud.\n- Tham gia phát triển các giải pháp mobile voip.\n- Tham gia các dự án outsourcing của công ty với các khách hàng đến từ Nhật, Singapore, Úc, Mỹ....\n\n2. Yêu Cầu\n\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc tương đương\n- Tư duy lập trình tốt\n- Nắm vững PHP Cơ bản, thành thạo một trong các Framework như Lavarel, WordPress, Phancol, Zend, Cake, Drupal,…\n- Có thể làm việc với CSDL SQL và No-SQL\n- Đã từng thiết kế, lập trình và triển khai các ứng dụng web trên nền tảng công nghệ sử dụng PHP\n- Có kỹ năng phân tích hệ thống, làm WBS\n- Có khả năng nghiên cứu và cập nhật công nghệ nhanh\n- Làm việc có trách nhiệm, cởi mở, nhiệt tình, khả năng làm việc độc lập hoặc theo nhóm\n\n3. Ưu Tiến\n\n- Ứng viên có kỹ năng phát triển extension\n- Có khả năng giao tiếp bằng tiếng Anh hoặc tiếng Nhật\n- Nắm vững quy trình phát triển phần mềm\n\n4. Chế Độ\n\n- Lương thỏa thuận – Up to 25M\n- Lương tháng 13\n- Thưởng theo Project và performance\n- Review 2 lần/ năm\n- Các khóa đào tạo nội bộ, được tham gia học tiếng Nhật tại Công ty\n- Cơ hội được onsite tại nước ngoài\n- Team building, company trip, khám sức khỏe định kì hàng năm.\n- BHXH, nghỉ phép, lễ tết, cưới hỏi,… và nhiều thứ hay ho đang chờ bạn.\n- Môi trường làm việc mở, văn hóa công ty phong phú cho phép phát huy tối đa khả năng và tính sáng tạo của ứng viên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1292, 769, 2, 'Chuyên viên Lập Trình PHP', 'Mô tả công việc\n\n- Phát triển các hệ thống, sản phẩm của công ty\n- Xây dựng hệ thông API kết nối với các hệ thống của Google, Facebook\n- Công việc chi tiết sẽ trao đổi thêm khi phỏng vấn\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1293, 770, 2, 'Java Software Engineer', 'Viettel Digital Service (VDS) – thành viên thứ 8 của Tập đoàn Viettel – tiên phong phát triển hệ sinh thái số, đặc biệt trong lĩnh vực Fintech với sản phẩm chủ lực là Viettel Money. Sứ mệnh của VDS là đưa công nghệ số đến mọi miền, nâng cao trải nghiệm khách hàng và góp phần xây dựng xã hội số tiện lợi, văn minh.\n\nMô tả công việc:\n\nPhát triển các dự án tài chính số như Viettel Money, Mobile Money, ví cá nhân/doanh nghiệp.\nXây dựng hệ thống tài chính điện tử cho thị trường nước ngoài.\nTham gia thiết kế, phát triển, nâng cấp và tối ưu hệ thống xử lý lưu lượng lớn.\nNghiên cứu và ứng dụng công nghệ mới.\n\nYêu cầu:\n\nTốt nghiệp đại học chuyên ngành CNTT hoặc Kỹ sư phần mềm, ưu tiên các trường Bưu chính Viễn thông, Bách khoa Hà Nội.\nTiếng Anh tương đương TOEIC 550+.\nKinh nghiệm Java từ 2 năm, thành thạo Java Core, các framework (Spring, Hibernate,...), SQL, PL/SQL, có kiến thức tối ưu CSDL.\nƯu tiên có hiểu biết về tài chính, microservices và đam mê sáng tạo.\n\nChế độ đãi ngộ:\n\nLàm việc từ thứ 2 đến thứ 6, tại văn phòng Keangnam Landmark 72, Hà Nội.\nMức lương cạnh tranh, thưởng hấp dẫn, đầy đủ BHXH, BHYT, BHTN.\nCơ hội thăng tiến, đào tạo trong nước và nước ngoài.\nMôi trường làm việc năng động, lãnh đạo trẻ, đồng nghiệp thân thiện.\nNghỉ dưỡng 3 ngày nguyên lương, hỗ trợ nghỉ dưỡng, các hoạt động văn hóa, thể thao, sự kiện đa dạng.\nBữa trưa dinh dưỡng phục vụ tại văn phòng.\n\nThông tin thêm:\n\nWebsite và Facebook: Viettel Digital\nSản phẩm tiêu biểu: Viettel Money', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1294, 771, 2, 'Java Developer (Middle/Senior)', 'Responsibilities\n- Contribute to all phases of development of an existing Java application\n- Understand and analyze the requirements\n- Assign, prioritize, and manage tasks in the application development life cycle\n- Review, check, and test team member’s code\n- Schedule and keep track of development phases\n- Design source code/ database structure\n- Support and give advice/ solution to a team member\n- Write well-design, testable, and efficient code\n- Write design documentation\n- Keep application is secure\n- Review work to ensure follow the policies set for the project\n- Follow the company application development processes and standards\n\nRequirements\n- BS/MS degree in Computer Science, Engineering, or a related field\n- 1-5 years of experience as a Java developer: Ability to write and debug Java code, strong in core Java and Java8, Profound insight into Java and JEE internals (Classloading, Memory Management, Transaction management, etc)\n- Excellent knowledge of Object Oriented programming, concurrency patterns in Java Spring Boot, Hibernate/JPA\n- Experience in the design, building, and development applications\n- Experience writing and optimizing SQL query\n- Good knowledge of DevOps (AWS – Amazon web service, Java web server – Maven, Tomcat, ...)\n- Good knowledge of Distributed and MicroService Patterns\n- Basic English\n\nBenefits\n- Working location: Binh Thanh district or onsite Japan\n- Salary range: up to USD 2,000 Gross', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1295, 674, 2, 'Lập Trình Viên Fullstack Developer', 'Mô tả công việc\n\n1/ Phân tích nhu cầu và lập kế hoạch triển khai\n\n- Tiếp nhận và làm rõ yêu cầu từ các phòng ban liên quan đến các hệ thống nghiệp vụ như CRM, HRM, ERP, POS,.. và các website bán hàng.\n- Phối hợp với các phòng ban để phân tích quy trình vận hành, xác định nhu cầu thực tế và đưa ra giải pháp công nghệ phù hợp.\n- Lập kế hoạch triển khai, xác định mốc thời gian và đề xuất tài nguyên kỹ thuật cần thiết.\n\n2/ Thiết kế kiến trúc và lập trình hệ thống\n\n- Thiết kế chi tiết các giải pháp công nghệ theo yêu cầu nghiệp vụ đã thống nhất, bao gồm tích hợp dịch vụ bên ngoài (thanh toán trực tuyến, đăng nhập qua bên thứ ba,...).\n- Lựa chọn và triển khai công nghệ phù hợp (ngôn ngữ lập trình, framework, cơ sở dữ liệu...) đảm bảo hệ thống vận hành hiệu quả, bảo mật, dễ bảo trì và tương thích đa nền tảng.\n- Thực hiện lập trình và kiểm thử nội bộ theo kịch bản giả lập tình huống thực tế trong vận hành.\n- Phối hợp với người dùng để kiểm tra tính ổn định, ghi nhận phản hồi và hiệu chỉnh phần mềm khi cần thiết.\n\n3/ Bảo trì, nâng cấp và hỗ trợ vận hành\n\n- Xử lý lỗi kỹ thuật phát sinh trong quá trình sử dụng: lỗi logic, giao diện, thao tác người dùng...\n- Cập nhật, nâng cấp tính năng và giao diện theo yêu cầu nghiệp vụ từ các bộ phận chuyên môn.\n- Theo dõi, đánh giá hiệu năng hệ thống và đề xuất phương án tối ưu hóa định kỳ.\n\nYêu cầu công việc\n\n1/ Kinh nghiệm: Tối thiểu 2 năm làm việc tại vị trí tương đương trong các công ty hoạt động trong lĩnh vực thương mại, bán lẻ, chuỗi cửa hàng, hoặc sàn thương mại điện tử.\n\n2/ Kỹ Năng Front-End\n\n- Thành thạo các ngôn ngữ và framework phát triển giao diện người dùng như Vue.js, React, HTML5, CSS3, Bootstrap hoặc các CSS framework tương tự.\n- Có tư duy thiết kế giao diện tối ưu trải nghiệm người dùng (UX/UI).\n\n3/ Kỹ Năng Back-End\n\n- Thành thạo ít nhất một trong các ngôn ngữ lập trình server-side như Node.js, Python, PHP,...\n- Có kinh nghiệm xây dựng RESTful API, xử lý nghiệp vụ phức tạp, bảo mật và tối ưu hiệu suất hệ thống.\n\n4/ Ưu Tiên (Điểm Cộng)\n\n- Có kinh nghiệm triển khai hệ thống theo kiến trúc Microservices, bao gồm phân tách dịch vụ, giao tiếp nội bộ qua message queue, và đảm bảo tính mở rộng linh hoạt.\n- Từng xử lý các bài toán dữ liệu lớn (big data), bao gồm lưu trữ, phân tích, và đồng bộ dữ liệu trên quy mô nhiều hệ thống.\n- Đã triển khai hoặc tham gia vào các dự án có yêu cầu cân bằng tải, tối ưu hiệu suất hệ thống và xử lý lượng người dùng lớn cùng lúc.\n- Thiết kế và giao diện: Có kiến thức và khả năng sử dụng các phần mềm thiết kế như Adobe Photoshop, Sketch, hoặc công cụ tương đương để làm việc với UI/UX designer (nếu có).\n- Cơ sở dữ liệu: Nắm vững kiến thức về SQL và có khả năng thiết kế, tối ưu hóa cơ sở dữ liệu quan hệ.\n- Công cụ phát triển: Sử dụng thành thạo các công cụ quản lý mã nguồn như Git, SVN (ưu tiên ứng viên có kinh nghiệm với Git workflow chuyên nghiệp).\n\n5/ Kỹ Năng Mềm\n\n- Khả năng quản lý thời gian, làm việc nhóm hiệu quả và giao tiếp tốt với các bộ phận liên quan.\n- Kỹ năng tư duy phân tích và giải quyết vấn đề linh hoạt trong môi trường làm việc thực tế.\n- Có tinh thần tự học và cập nhật công nghệ mới.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Thu nhập: dao động 20.000.000 - 25.000.000 (Lương cơ bản +Thưởng)\n- Chính sách lương thưởng đầy đủ, rõ ràng.\n- Thưởng cuối năm theo kết quả kinh doanh.\n- Đóng BHXH, BHYT theo quy định Nhà nước.\n- Tham gia du lịch công ty kết hợp các hoạt động xây dựng đội nhóm.\n- Mua hàng nội bộ với chính sách ưu đãi hàng tháng.\n- Nhận quà vào ngày sinh nhật theo chính sách cho từng cấp bậc.\n- Hoạt động ngoại khóa thường xuyên vào mỗi thứ 5 hàng tuần, bao gồm: bóng đá, cầu lông, chạy bộ...\n- Làm việc trong môi trường hoà đồng, không rào chắn, quản lý công việc bằng hệ thống và được tiếp nhận đầy đủ hướng dẫn từ đồng nghiệp và quản lý cấp trên.\n- Thường xuyên tổ chức những lớp đào tạo kiến thức sản phẩm, PCCC, sử dụng hệ thống công nghệ để quản lý kho hàng...với mong muốn bạn phát triển cùng MIA\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: 117 - 119 Bạch Đằng, Phường 15, Bình Thạnh\n\nThời gian làm việc\n\n- Thứ 2 – thứ 6: 8h – 17h / Thứ 7: làm 2 ngày, nghỉ 2 ngày', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1296, 772, 2, 'Nhân viên kỹ thuật (IT - phần cứng)', 'Mô tả công việc\n\n- Bảo trì và lắp đặt hệ thống máy tính, mạng của khách sạn.\n\n- Sửa chửa, lắp đặt hệ thống điện nước\n\n- Thực hiện các công việc khác do Trưởng bộ phận giao\n\nTrung cấp', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1297, 773, 2, 'Java Developer', 'Requirements\n- Have background in Computer Science/ Information Technology or equivalent\n- Have solid knowledge in Java, OOP and Unit testing\n- Experienced in Java, Quarkus/Spring framework\n- Experienced with front-end web frameworks such as Angular or NextJS\n- Familiar with Microservices architecture is a plus\n- Be able to communicate with customers in English\n- Good sense of teamwork, high responsibility, and self-organizing\n- Familiar with Agile development methodologies (Scrum, XP, Kanban) is an advantage\n\nResponsibilities \n- Working in a cross-functional Scrum team (05-09 members)\n- Daily coordination with the foreign Product Owner\n- Involving in planning, estimation, developing, and continuously delivering software\n- Self-assigning tasks and being self-responsible for the delivery\n- Joining onsite business trips, if required\n\nBenefits\n- Free lunch at the office\n- Competitive salary & 13th salary\n- 100% probationary salary; fully compulsory insurances\n- Annual premium healthcare and 24/24 personal accident insurance\n- Additional healthcare insurance for family members\n- Annual health check-ups\n- Working from home option\n- Flexible working hours; up to 18 days off per year\n- Loyalty bonuses (additional annual leaves, travel vouchers, salary bonus)\n- Free access to Udemy and ELSA speak\n- Free kindergarten for staff’s kids\n- Onsite/business trips in Europe, US, or Australia\n- Annual company trip\n\nAbout us\nFounded in 2008, Axon Active is a Swiss-based software development company with over 15 years of successful business. Currently, we have nearly 600 employees working across 60+ teams and serving over 40 clients worldwide. Our offices are strategically located in Ho Chi Minh City, Thu Duc City (Dist. 9), Da Nang, and Can Tho, each providing innovative and modern workspaces.\n\nAt Axon Active, we provide a professional and international working environment that values every team member\'s contribution. We offer numerous exciting job opportunities, along with competitive salaries and comprehensive benefits package. Additionally, each year, we send hundreds of our engineers on enriching business trips to Europe, the United States, and Australia. These opportunities not only enable our engineers to exchange cultural perspectives but also to share valuable experiences with experts from around the world.\n\nOur teams thrive on Agile methodologies, promoting individual responsibility and maximizing the potential of each member. Working at Axon Active, you will be empowered to set your own goals, self-assign your tasks, and take ownership of your work, all within a supportive environment that values work-life balance. We trust in your competence and sense of responsibility, your success is indeed our company\'s success.\n\nJoin our Axon Active Family NOW!\nJust send us your resume in English to job@axonactive.com\nIf you have further questions, feel free to contact us:\nTel: +84 28 7109 1234\nTeams: xuan.nguyen@axonactive.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ninh Kieu, Can Tho, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1298, 411, 2, 'Software Engineer (Java OR Golang)', 'We are seeking a talented Senior Backend Software Developer to join our team. As a key member of our Engineering team, you will collaborate closely with Product, Design, and Engineering teams to deliver integrated solutions that exceed our customers\' expectations. Additionally, you will play a vital role in enhancing our engineering processes, ensuring high availability and low latency in our mission-critical environment.\n\nResponsibilities:\n- Collaborate with cross-functional teams to create integrated solutions that delight our customers.\n- Design, develop, and maintain services and APIs that meet our high standards for availability, latency and security.\n- Utilize the latest open-source technologies to build robust and scalable microservices architecture systems.\n- Identify and address performance bottlenecks and security vulnerabilities.\n- Participate in code reviews and contribute to the continuous improvement of our engineering in development and deployment.\n- Enhance our engineering processes, including long-term planning, sprint execution, and stand-ups.\n\nRequirements:\n- Bachelor\'s Degree in Computer Science, Engineering, or related field.\n- 4+ years of Backend programming experience, with proficiency in Go OR Java (Spring Boot); familiarity with Node.js, or similar languages is a plus.\n- Proficiency in developing SQL and NoSQL databases, such as MySQL, MongoDB, and Redis.\n- Strong understanding of API and REST services, with experience integrating with Mobile and Web platforms.\n- Familiarity with Docker, Git, CI/CD, and Kubernetes is beneficial.\n- Proficiency in developing with message brokers such as Kafka and event-driven architectures.\n- Experience in product development and delivering highly-available, scalable systems; cloud development experience is advantageous.\n- Understanding of software architecture principles, design patterns, and best practices.\n- Excellent problem-solving and troubleshooting skills.\n- Strong communication and collaboration skills.\n- Experience with Agile development methods, particularly Scrum.\n- Experience in A/B Testing, Unit Testing, and Clean Code Development is desirable.\n- Effective communication skills in basic English.\n\nPreferred Qualification\n- Familiarity with DevOps practices and tools (ArgoCD, Terraform, Gitlab/Bitbucket CI).\n- Strong background in DB internals, indexes, transaction.\n- Generally understand observability data types, such as logs and metrics (Prometheus/Grafana/Loki)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1299, 774, 2, 'Bridge Software Engineer up to $3000', 'Chúng tôi mong muốn được hợp tác với các kỹ sư Việt Nam để tăng tốc độ phát triển.\nChúng tôi đang tìm kiếm các BrSE – cầu nối hợp tác giữa Nhật Bản và Việt Nam để có thể thực hiện việc phát hành các tính năng mới cũng như cải thiện dịch vụ một cách kịp thời mang tới cho người dùng.\nVị trí BrSE – Kỹ sư cầu nối giữa Việt Nam và Nhật Bản, sẽ chịu trách nhiệm cho việc phát triển web và ứng dụng như bổ sung các tính năng mới, cải thiện hiệu suất, cũng như cải tiến/đổi mới công nghệ dưới hình thức phát triển offshore (công ty con của chúng tôi tại Việt Nam)\nMô tả công việc\n■ Quản lý công việc phát triển dự án\nNắm được nội dung của các tài liệu, thông số kỹ thuật từ phía Nhật Bản và truyền đạt lại một cách dễ hiểu.\nTạo tài liệu Basic design (flowchart, UML, sơ đồ trình tự/sequence diagram) của tổng thể hệ thống dựa trên nội dung được chốt trong định nghĩa yêu cầu.\nQuản lý tiến độ của các dự án phát triển được giao.\nXem xét tài liệu các hạng mục kiểm thử tích hợp/integration testing, thực hiện UAT và đảm bảo chất lượng.\n■ Hỗ trợ thành viên team dự án phát triển Việt Nam\nHiểu rõ nội dung câu hỏi/vấn đề cần trao đổi và phản hồi một cách dễ hiểu.\nTrong trường hợp không thể đưa ra quyết định, sẽ xem xét nội dung và trao đổi với các thành viên phía Nhật Bản để cố gắng giải quyết vấn đề.\nHoạt động cải tiến nhằm nâng cao năng suất/chất lượng/hiệu suất phát triển/năng lực kỹ thuật trong công ty con tại Việt Nam.\n■ Hoạt động đào tạo và cải tiến hoạt động phát triển\nĐào tạo và hướng dẫn BSE tương lai.\nĐưa ra các đề xuất nội bộ để cải thiện hoạt động phát triển offshore.\n■ Môi trường phát triển:\nSử dụng: Server side: Node.j, front-end: React, React Native\nBasic design: Whimsical\nQuản lý source-code: Github\nQuản lý dự án: Backlog\nTest: Jest, Google sheet, GoogleAppScript\nCI: CircleCi\nInfrastructure (cơ sở hạ tầng): AWS・GCP\nSystem monitoring (giám sát hệ thống: NewRelic\nTrao đổi nội bộ: Slack\n\nYêu cầu công việc\n■ Kỹ năng/kinh nghiệm bắt buộc\nCó từ 3 năm kinh nghiệm ở vai trò BrSE/PM của dự án.\nKinh nghiệm quản lý trong quản lý tiến độ, quản lý chất lượng.\nKinh nghiệm tạo basic design và thực hiện kiểm thử/testing.\nNăng lực tiếng Nhật từ N2 trở lên, sử dụng tốt cả 4 kỹ năng trong công việc.\nCó định hướng làm product.\n■ Ưu tiên\nCó kinh nghiệm với phát triển Web, ứng dụng.\nKinh nghiệm thực hiện các hoạt động cải tiến trong hoạt động phát triển với quy trình PDCA.\nCó kinh nghiệm đào tạo nhân viên.\n■ Chân dung nhân sự muốn tìm kiếm\nThái độ tích cực không ngừng đối mặt với thách thức để mang tới trải nghiệm tốt nhất có thể cho người dùng.\nTích cực giao tiếp với các thành viên khác trong công ty để chủ động tiếp cận, hoàn thành các dự án phát triển mà mình tham gia.\nSuy nghĩ thấu đáo về mục tiêu bản thân đang hướng tới mình muốn trở thành người như thế nào để luôn luôn có những cải tiến mang lại ảnh hưởng.\n\nĐãi ngộ và quyền lợi cho CO-WELLers\nThưởng và review tăng lương 2 lần/năm\nThử việc hưởng 100% lương\nCa làm việc linh hoạt: 8h-17h; 8h30 – 17h30; 9h – 18h\nNgày phép: 14+ ngày/năm\nBảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên.\nKiểm tra sức khỏe định kỳ 1 năm/lần\nBHXH, BHYT, BHTN mức cao, đảm bảo quyền lợi người lao động.\nTrợ cấp hoạt động teambuilding hàng tháng, du lịch công ty 1 năm/lần\nDành riêng cho nhân viên nữ:\nNghỉ sinh lý 2,5h/tháng\nHưởng 100% lương trong thời gian thai sản\nThêm 5 ngày nghỉ khám thai trong thai kì\n\nMôi trường làm việc tuyệt vời\nTrang bị thiết bị làm việc trọn bộ, hiện đại, đáp ứng yêu cầu dự án.\nLàm việc và hướng dẫn bởi các chuyên gia/Senior nhiều kinh nghiệm thực tế.\nTrợ cấp hàng tháng cho các hoạt động của CLB thể thao (Yoga, Zumba, bóng đá…)\nThông tin chính sách mới/cải tiến được cập nhật đều đặn tới nhân viên.\nCó riêng khu vực thư giãn phục vụ hoạt động giải trí, ẩm thực.\nKhông gian làm việc mở, tiện nghi.\n\nCơ hội đào tạo và phát triển bản thân\nThường xuyên tổ chức các buổi đào tạo, seminar cập nhật xu hướng công nghệ.\nĐào tạo kiến thức chuyên môn, kĩ năng quản lý, kỹ năng mềm,… theo định hướng công ty và nhu cầu khảo sát nhân viên.\nHỗ trợ chi phí thi chứng chỉ chuyên môn. Trợ cấp chứng chỉ tiếng Nhật, chứng chỉ chuyên môn (lên tới 108 triệu) theo định hướng phát triển của Công ty.\nCác lớp đào tạo tiếng Nhật (sơ cấp – cao cấp) với giáo viên bản ngữ trong giờ hành chính.\nCơ hội làm việc tại Nhật Bản với các nhân sự có tiếng Nhật.\n\nCách thức ứng tuyển\nBước 1: Đọc kỹ nội dung và xác nhận “Đồng ý” với Thỏa thuận về việc xử lý và bảo vệ dữ liệu cá nhân của CO-WELL Asia tại đây.\nBước 2: Sau khi xác nhận “Đồng ý” với thỏa thuận này, bạn vui click vào ô nộp hồ sơ để cung cấp thông tin tham gia ứng tuyển vào Công ty chúng tôi.\n\nLiên hệ ứng tuyển: Ms Trang\nEmail: trang.hr@co-well.vn | Phone/zalo: 0988998740', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1300, 491, 2, 'Full Stack AI and Web Developer', 'Company Description\n\nEstablished in 1997 by a leading data scientist from Morgan Stanley, East Agile has grown into a successful software development company focusing on AI, statistical analysis, and Agile practices. Our experienced team of engineers delivers results quickly and frequently, with an emphasis on quality, flexibility, stability, and easy maintenance. We specialize in both offsite system development and onsite/offsite analytic consulting, working with technologies such as Python, Rust, node.js, Golang, Ruby on Rails, and more. Our clients range from new ventures to well-known brands like Twitter, Samsung, and Bank of America.\n\nRole Description\n\nThis is a full-time on-site role located in Ho Chi Minh City, Vietnam for a Full Stack AI and Web Developer. You can work from our 2 offices in Ho Chi Minh City: Thao Dien or Q10. The Thao Dien location is a 2 minute walk from the Thao Dien Pearl Metro station. You can also work from our office in Da Nang.\n\nThe Full Stack AI and Web Developer will be responsible for front-end and back-end web development, programming, and web design. The developer will work on creating AI-driven web applications, maintain existing applications, and collaborate with the team to implement new features and solve complex technical challenges.\n\nQualifications\n\nExperience in Front-End Development and Web Design skills including HTML, CSS, and JavaScript\nProficiency in Back-End Web Development and Programming skills including Python, node.js, Ruby on Rails, or similar languages\nStrong Web Development skills that cover both front-end and back-end development\nUnderstanding of AI prompting, vector embedding, MCP Servers, Agents.\nExcellent problem-solving and analytical skills\nAbility to work collaboratively in a team environment\nBachelor\'s degree in Computer Science, Engineering, or related field\nExperience with Agile methodologies is a plus', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1301, 775, 2, 'Junior/Middle Flutter Developer ~1000$', 'Braly là một trong các nhà phát triển ứng dụng di động trên Google Play và App Store hàng đầu Việt Nam. Chúng tôi tạo ra các sản phẩm phục vụ hàng chục triệu Users trên toàn cầu, nhằm mang đến những giải pháp công nghệ hữu ích trong cuộc sống. Hãy gia nhập đội ngũ tài năng của Braly để cùng chinh phục những cột mốc mới trên thị trường quốc tế!\n\nChúng tôi đang tuyển dụng vị trí Junior Flutter Developer với mô tả công việc như sau:\n\nMô tả công việc\n- Phát triển ứng dụng di động sử dụng Flutter theo phân sự phân công của Team Leader.\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động.\n- Phát triển các ứng dụng một cách linh hoạt, có cấu trúc tốt, mã nguồn và thư viện có thể tái sử dụng trong tương lai.\n- Tối ưu hoá hiệu suất và đảm bảo ứng dụng tương thích trên cả Android và iOS..\n- Lập trình các module tính năng theo bản phân tích thiết kế.\n\nYêu cầu ứng viên\n- Có từ 6 tháng kinh nghiệm phát triển ứng dụng bằng Flutter.\n- Thành thạo ít nhất một trong các state management (Provider. Bloc, GetX,...).\n- Hiểu biết tốt về các UI components & customization/animation, thiết kế giao diện người dùng cho nhiều loại thiết bị có màn hình khác nhau.\n- Có tư duy logic tốt, có khả năng phân tích và giải quyết vấn đề.\n- Hiểu biết Design Pattern, SOLID.\n- Có kiến thức tốt về Data Structures & Algorithm.\n- Có kinh nghiệm tối ưu performance, memory cho ứng dụng.\n- Có kinh nghiệm tích hợp Firebase, Admob, Subscription và In-App Purchases là một lợi thế.\n- Ưu tiên ứng viên có kinh nghiệm về native (Swift hoặc Kotlin/ Java).\n- Có kỹ năng làm việc nhóm, làm việc độc lập, có khả năng tự học hỏi và cập nhật các công nghệ mới.\n- Có đam mê phát triển sản phẩm product.\n\nQuyền lợi\n- Offer upto 1000$ + trợ cấp ăn trưa + trợ cấp đi lại.\n- Tháng lương 13.\n- Thưởng Tết Âm Lịch từ 01 - 05 tháng lương.\n- Thưởng các ngày lễ: 30/04, 01/05, 02/09, Tết Dương, 08/03, 20/10,... áp dụng cho tất cả nhân sự (chính thức, thử việc, thực tập sinh).\n- Thử việc tối đa 02 tháng 100% lương, có phép trong thời gian thử việc.\n- Được cung cấp hoàn toàn trang thiết bị phù hợp với vị trí công việc.\n- Review hiệu suất & lương thưởng định kỳ 2 lần/năm (tháng 1 & tháng 7).\n- Bảo hiểm, nghỉ lễ, phúc lợi đầy đủ theo quy định pháp luật, được cung cấp các gói khám sức khỏe định kỳ khi trở thành nhân viên chính thức.\n- Được đào tạo 1-1 bởi leader giàu kinh nghiệm từng làm tại công ty Tech lớn.\n- Cơ hội phát triển và tham gia vào các sản phẩm có chục triệu người dùng trên toàn cầu.\n- Miễn phí trà, cafe, nước ngọt tại Pantry.\n- Có cơ hội tham gia rất nhiều các CLB do công ty tổ chức và tài trợ: Bóng đá, bóng bàn, Bi-a, Board game, Chạy bộ, cầu lông....\n- Khu vực vui chơi với Bàn Bi-a siêu xịn, bàn bóng bàn, PS4 và nhiều bộ môn hấp dẫn khác\n- Team building/ du lịch 3 tháng/lần – Công ty tài trợ 100% chi phí.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj a okolí', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1302, 776, 2, 'Junior QC Engineer (Manual Tester, Global Project)', 'LOGIX TECHNOLOGY is a distinguished software services company, specializing in the provision of professional software development services, fostering strong partnerships through the establishment of offshore development centers, offshore product development, and software testing with an infrastructure-oriented approach. We excel at simplifying and enhancing offshore outsourcing, not only by delivering innovative solutions to meet our clients’ exact requirements through high-performance teams but also by significantly contributing to our clients’ success by reducing time-to-market and improving quality.\n\nAt LOGIX TECHNOLOGY, we are committed to delivering the highest level of professional excellence and making a significant impact in the software development sector. If you are a dedicated professional looking to join a dynamic team working with global leaders, we encourage you to explore the exciting opportunities that await you with us.\n\nJob Description\n\n- Be responsible for ensuring the quality of mission-critical, cloud-based software systems.\n- Work directly with software engineers and product managers, through all phases of the software development process to provide feedback on the functionality, reliability, usability, and efficiency of the software.\n- Evaluate current processes and implement improvements that will result in increased quality.\n- Can quickly learn our products inside and out, understand user flows; and partner’s product for edge cases.\n- Can collaborate well. Communication is key in this position. You will be working closely with other departments on a regular basis to ensure we continuously improve our ability to ship high-caliber solutions to our customers.\n- Generate and execute test cases and test plans.\n- Perform exploratory testing.\n- Troubleshoot issues to find root causes and suggest potential fixes.\n- Learn the designated client’s application and become familiar with health and human services to better understand the workflows and represent users in the development process.\n\nRequired Skills & Experience\n\n- Minimum 2 years of experience in a similar position.\n- Basic to intermediate knowledge of SQL.\n- Good English communication skills (verbal communication is a plus).\n- Educational background in Information Technology is a plus.\n- Good analytical and problem-solving skills.\n- Demonstrated ability to collaborate effectively and respectfully within Agile teams.\n- Basic knowledge of any of the following is a plus: Regular expressions, JavaScript, HTML/CSS, etc.\n\nBenefits & Perks\n\n- Attractive Salary & Benefits, full salary in probation.\n- Performance appraisal twice a year, 13th-month salary.\n- Healthcare and incident insurance.\n- 16 Paid Leave days/ year (12 Annual Leave, 02 Summer Leave ,01 Birthday Leave & 01 Christmas Leave).\n- Diverse careers opportunities with Software Services, Software Product Development.\n- Working and growing in a value driven, international working environment and standard Agile culture with passionate and talented teams.\n- Various training on hot-trend technologies, best practices, and soft skills.\n- Company trip, big annual year-end party every year, team building, etc.\n- Free in-house entertainment facilities: football, table football, PS, badminton, trekking…coffee, and snacks (instant noodles, cookies, candies…).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1303, 326, 2, 'Frontend Engineer (ReactJS)', 'YOUR NEW ROLE CODE LEAP We are looking for a Frontend Engineer to join our expert team in Ho Chi Minh City. This role is perfect for team players with a strong interest in developing their international career - not just as a coder, but as a product builder. YOUR EXCITING TASKS Design, build the frontend services for our client’s product and bring it to the next level Write high-quality, optimized and reusable code Review the code and provide feedback on possible problems Optimize the application for maximum speed and scalability Analyze, debug, and fix complex bugs Work with an international team based in Vietnam and Germany Write comprehensive technical documents YOUR PROFILE AND YOUR PERSONALITY At least 4 years of experience developing and designing web applications in dynamic environments Strong knowledge of JavaScript, TypeScript, ReactJS. Solid understanding of rendering strategies including client-side and server-side rendering Experience with modern UI libraries such as Tailwind, MUI, Ant Design, or Element Plus Familiarity with styling approaches, including SCSS, LESS, and styled-components Proficiency in building and maintaining design systems (e.g., Polaris, Chakra UI), and using Atomic Design Methodology to structure UI components Experience using Storybook, not only for component development but also for QA workflows Experience with tools like Redux, Jotai, and TanStack Query for efficient state and data management Proficiency with TanStack Router for modern routing in React applications Familiar with OpenAPI (Swagger), Postman, and HTTP clients like fetch or axios Hands-on experience with unit tests, as well as E2E testing using Jest, React Testing Library, Playwright, or Cypress Hands-on experience with reading and understanding technical documents You understand and know how to prioritize your tasks with a problem-solving mindset You don\'t take things personally and are comfortable with ambiguity and rapid changes common in early-stage product development You don\'t wait for others to tell you what you need to do, but proactively reach out to people, communicate, ask for help, and get things done You are proficient in communicating in the English language Nice to have Experience with cloud hosting platforms: AWS (CloudFront + S3), Azure (App Service), or on-premise setups Familiarity with front-end deployment pipelines, CI/CD workflows using GitHub Actions, and automated release tools like semantic-release or changesets Understanding of the CQRS pattern for backend communication Exposure to micro-frontends or modular front-end architectures Knowledge of remote logging and monitoring tools such as Sentry Benefits Await You At Code Leap Competitive salary and beneﬁts Year-end bonus (13th-month salary) Generous annual leave of up to 18 days Enjoy a stress-free and comfortable commute to and from work with our Grab Services sponsor Enjoy an endless selection of delicious refreshments, including gourmet coffee, beverages, snacks, and fresh fruits, all complimentary Focused on individual development: Unlimited access to Udemy and other recommendation courses Sponsored Professional certificates such as AWS, PMI, Scrum Master, etc Sharing session every Friday, come along with lunch provided by CODE LEAP 1-on-1 coaching with experienced professionals Flexible work policy, which provides flexible hours to accommodate personal schedules and commitments Dynamic, fun, and agile environment, perfect for sharing and creativity Open-minded, kind & humble colleagues CONTACT Please reach out and contact us now with your latest CV as well as a little description of yourself at jobs@codeleap.de. About Us With our expert teams spread across two continents, CODE LEAP provides innovative software solutions for venture-backed companies and leading enterprise businesses in Germany. Our teams in Germany and Ho Chi Minh City (Vietnam) work hand in hand to develop state-of-the-art solutions of the highest quality. Because collaborating with the right people is the secret to our successful growth. We future-proof organizations - be part of it!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミン市, ベトナム', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1304, 777, 2, 'Software Engineer (Ho Chi Minh)', 'As a Software Engineer at Caladan you will be part of a team responsible for owning a business area or application end to end. You’ll be surrounded by smart and motivated colleagues with complimentary skillsets. You’ll have variety in your work and see your code contribute directly to the success of the team.\n\nPrevious experience in trading on blockchain can be useful, but what really makes our Software Engineers successful is conscientiousness, logic, openness to new ideas and the curiosity to pull on a thread and see where it leads.\n\nWe\'re opening an office in Vietnam! Be part of an exciting opportunity to build from the ground up.\n\nWhat you\'ll be doing\n\n- Design, build, test and deploy proprietary software such as:\n  - Trading simulator optimised for distributed computations\n  - Large-scale data collection, management and visualisation systems\n  - Analytics tools to enable advanced mathematical modelling\n  - Post-trade analysis and reconciliation to support efficient operations\n- Document development phases and monitor systems\n- Automate tasks through appropriate tools and scripting\n\nThe Ideal Candidate\n\n- Experience of software development in small, fast-moving technology-driven companies; some interest or experience in trading or blockchain would be an advantage\n- Fluent with imperative and object-­oriented languages; Python, C#, Java or C++ preferred\n- Strong understanding of data structures, algorithms, and object-oriented programming\n- Familiarity with network and asynchronous programming, websockets & REST interfaces, agile development\n- Curious, likes problem solving and going down rabbit holes to find answers\n\nAbout Caladan\n\nCaladan makes digital asset markets more efficient and fair. We support exchanges, tokens, and institutional investors with on-exchange liquidity, DeFi expertise, treasury solutions, and investments. Since 2017 we\'ve been a pioneer in crypto market-making, powering over $50B in annual transactions across 1000+ assets.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミン市, ベトナム', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1305, 778, 2, 'Frontend Developer', 'About the job\n\nHCL Vietnam Company Limited belongs to HCLTech which is a global technology company, home to 220,000+ people across 60 countries, delivering industry-leading capabilities centered around digital, engineering and cloud, powered by a broad portfolio of technology services and products. We work with clients across all major verticals, providing industry solutions for Financial Services, Manufacturing, Life Sciences and Healthcare, Technology and Services, Telecom and Media, Retail and CPG, and Public Services. Consolidated revenues as of 12 months ending Mar 31, 2025, totaled $13.8 billion.\n\nWebsite: https://www.hcltech.com/\n\nABOUT THE ROLE\n\nAbout the project: Build 1st frontend platform for ANZ X, have an opportunity to develop yourself in frontend development in this very challenging job\n\nAt ANZx our purpose is to shape a world where people and communities thrive. We’re making this happen by improving our customers’ financial wellbeing so they can achieve incredible things – be it buying their home, building a business or saving for things big or small. As an Engineer you will be responsible for building innovative front-end technology for our end users, using best-of-breed network technologies, and modern software development practices.\n\nThe experience engineering team\'s mission is to provide the best software for customers to help them manage their money and save.\n\nJOB RESPONSIBILITY: \n\n- Leading and coaching engineers in your team to design and implement secure, scalable, and impactful solutions.\n- Helping us evolve our web platform. We currently use Next.js 14, managing the projects with Nx. We deploy our code to production using continuous deployment. \n- Working at a senior level across the programme team, collaborating with architects, engineers, and customer experience experts.\n- Self-organising your own priorities, you will facilitate rapid decision making for the team.\n- Shaping how ANZ delivers on their commitment to providing great customer service through technology.\n\nJOB REQUIREMENTS\n\nMust have:\n- From 6 years of web or application development experience including defining application architecture.\n- 2+ years working with ReactJS or NextJS using TypeScript (NextJS preferred)\n- Strong understanding of software engineering principles. \n- Ability to demonstrate UI design literacy.\n- Experience with frontend unit testing and familiarity with testing-library.\n- A good understanding of WCAG Accessibility 2.0, Level AA or higher (we do not expect you have experience; intermediate knowledge is okay)\n- Working in an agile team environment including relevant tools.\n- Good ability in English\n\nNice to have:\n- Ability to demonstrate working within cloud environments such as GCP, AWS or Azure.\n- Experience with setting up and working with continuous integration, continuous delivery, and continuous deployment (CI/CD)\n- Familiarity with a type system, or a willingness to learn.\n\nBENEFITS\n\n- 18 paid leaves per year (including 12 annual leaves + 6 personal leaves).\n- Insurance plan based on full salary + 13th salary + Performance Bonus.\n- 100% full salary in probation period.\n- Medical Benefit (Personal) and Family based on levels.\n- Working in a fast paced, flexible, and multinational working environment. Chance to travel onsite (in 49 countries).\n- Internal Training (Technical & Functional). Scope of English Training.\n- Working from Mondays to Fridays.\n\nFor support and more information, please contact:\nMai Huynh\nPhone/Zalo: +84 931583594\nEmail: mai.huynh@hlctech.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1306, 779, 2, 'Thực Tập Triển Khai Phần Mềm', 'Mô tả công việc\n\n- Tìm hiểu các yêu cầu nghiệp vụ của khách hàng.\n- Thực hiện cấu hình phần mềm, thiết kế báo cáo theo mô tả của tài liệu giải pháp.\n- Xây dựng kịch bản thử nghiệm, viết testcase và internal testing.\n- Tham gia đào tạo và chuyển giao hệ thống phần mềm cho các khách hàng.\n- Hướng dẫn, hỗ trợ người dùng vận hành hệ thống, kiểm tra kết quả vận hành.\n- Hỗ trợ khách hàng vận hành và sử dụng hệ thống.\n- Tương tác với các thành viên dự án để hoàn thành công việc.\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1307, 691, 2, 'Software Engineer (Golang/ Ruby on Rails)', 'What you will be doing:\n\n- Developing a clean and maintainable code using software engineering best-practices and modern platforms.\n- Participating in full product development lifecycles from ideation to live production.\n- Day-to-day tech operations such as server maintenance and deployment.\n\nWhat we need from you:\n\n- Minimum 1 years of software engineering experience building Backend\n- Experience in Golang and/or Ruby on Rails.\n- Fluency in written and spoken English is required for communication with international teams and clients.\n- Comfortable with working in a fast-paced environment and highly collaborative team to solve real business problems\n- Versatility and enthusiasm to tackle new problems across the full-stack and to learn new frameworks as we continue to push technology forward.\n\nAbout Hubble:\n\nHubble is a leading technology company focusing on the construction and engineering industry. We are on a mission to build the world’s first autonomous construction sites by automating and trading the 4M (Man, Machine, Material, Money) resources.\n\nOur solutions help digitise all your work processes, and connect all key project stakeholders - developers, consultants, fabricators, contractors, and facility managers - onto an all-in-one platform - The Hubble Platform.\n\nBuild faster and cheaper and with the highest quality and safety standards with Hubble’s impactful technologies. Let’s transform the way we build our cities for a better tomorrow. Today. Together. For generations to come.\n\nVisit us at www.hubble.build to learn more for #bettercitiesoftomorrow', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1308, 780, 2, 'Staff/Principal Web Engineer (Frontend focus)', 'We are looking for a Staff/Principal Web Engineer who will play a crucial individual contributor role in shaping the web architecture and development at Cake. You will lead the design, development, and optimization of our web platform, ensuring scalability, performance, and reliability. As a key technical expert, you will drive innovation, provide deep technical expertise, and collaborate with cross-functional teams to enhance user experience and system efficiency.\n\nThis role is ideal for an independent technical expert who wants to make a high-impact contribution without direct management responsibilities. If you are passionate about building cutting-edge web solutions and pushing boundaries in frontend architecture, we’d love to hear from you!\n\nJob Responsibilities\n\n- Architect and develop a scalable Micro-Frontend infrastructure, ensuring seamless integration across multiple projects.\n- Build and optimize web applications, covering both frontend and backend aspects, with a focus on performance, security, and maintainability.\n- Collaborate with internal teams and vendors to deliver high-quality web features that enhance user experience.\n- Conduct deep code analysis, reviews, and performance tuning to uphold best practices in accessibility, maintainability, and efficiency.\n- Influence product and technical decisions, proactively providing insights on improvements and delivering tasks within expected timelines.\n- Ensure code quality by following best software development principles, including clean code, modular design, and robust testing strategies.\n- Stay ahead of industry trends, continuously enhancing Cake’s web technology stack with modern solutions.\n\nJob Requirements\n\n- 5+ years of experience in software/frontend engineering, specializing in TypeScript/JavaScript and modern ReactJS frameworks.\n- Solid experience in at least one backend technology (e.g., Next.js, Node.js).\n- Strong knowledge of Micro-Frontend architectures (both Server-Side and Client-Side rendering).\n- Proven experience working with high-traffic, complex web applications and optimizing for scalability and performance.\n- Solid understanding of computer science fundamentals, including algorithms, data structures, and network principles.\n- Passion for user-centric design and building high-performance, responsive web applications.\n- Deep commitment to clean, maintainable code and software engineering best practices.\n- Strong problem-solving skills, an innovative mindset, and a drive for continuous learning.\n- Excellent communication and collaboration skills—comfortable working with cross-functional teams.\n\nOur benefit:\n\n- Competitive compensation including a 13th-month wage and up to 3 months of performance-based bonus.\n- MacBooks are currently supplied to all technical team members.\n- BE Corp budget (depending on your level) is allocated for using services such as transportation, food, and passenger car bookings in Be application.\n- The social insurance contribution amount will vary based on the individual’s level.\n- Annual health checks and premium medical healthcare (PTI) after probation.\n- 15 days of annual leave is applied for the entire employees.\n- Company trips, team-building activities, and happy hour events are organized on a quarterly or annual basis.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1309, 781, 2, 'Fullstack Developer (Java/ Angular/ ReactJS)', 'Nơi làm việc\n\nHà Nội\n\nCấp Bậc\n\nNhân viên\n\nHình Thức\n\nNhân viên chính thức\n\nKinh Nghiệm\n\n2 Năm\n\nMức Lương\n\nLương thỏa thuận\n\nNgành nghề\n\nCNTT - Phần mềm\n\nPhòng Ban\n\nCông nghệ\n\nHạn chót nhận hồ Sơ\n\n30/06/2025\n\nPhúc Lợi\n\nBảo hiểm\nDu Lịch\nThưởng\nChăm sóc sức khỏe\nĐào tạo\nTăng lương\nChế độ nghỉ phép\n\nMô tả công việc\n\nThiết kế, phát triển, nâng cấp, bảo trì các dự án với công nghệ Java/ Angular/ ReatJS.\nĐảm bảo hiệu suất, chất lượng, khả năng đáp ứng tốt nhất của hệ thống.\nTương tác với bộ phận kinh doanh, vận hành để hiểu nhu cầu của người sử dụng hệ thống.\n\nYêu cầu công việc\n\nTrình độ học vấn/Chứng chỉ\nTốt nghiệp đại học chuyên ngành Công nghệ thông tin, Hệ thống thông tin hoặc các lĩnh vực liên quan.\nKinh nghiệm làm việc\nCó từ 2 năm kinh nghiệm trở lên trong lĩnh vực phân tích, thiết kế, phát triển, mô tả tài liệu, triển khai và thử nghiệm các hệ thống phần mềm với các công nghệ Java/ Angular/ ReactJS.\nKiến thức/Kỹ năng/Năng lực chuyên môn\nCó kinh nghiệm thực hiện các mẫu thiết kế Java EE như MVC, Singleton, Session Facade, DAO\nKinh nghiệm trong lập trình đa luồng, collections, IO, mạng, JSP/Servlets và JDBC.\nCó kinh nghiệm trong Spring Framework như Spring Boot, Spring MVC, Spring JDBC/Data, Spring Security.\nCó kinh nghiệm cấu hình và triển khai ứng dụng trên nền tảng máy chủ Tomcat 7.0+\nKinh nghiệm tốt với hệ quản trị dữ liệu quan hệ (RDBMS MySQL, PostgreSQL) và kỹ thuật ORM (JPA2, Hibernate).\nCó kinh nghiệm trong phát triển Angular 12+ hoặc ReactJS 15+\nCó kiến thức về XML Suite of Technologies XML (XSL) và REST/JSON.\nCó khả năng thiết kế, viết Stored procedure, Function, tunning database với MySQL\nKinh nghiệm với các công cụ xây dựng và triển khai bao gồm Maven, logging và debugging bằng Log4j, Unit và Integration test sử dụng JUnit.\nCó kiến thức về phát triển ứng dụng sử dụng Software Development Life Cycle SDLC bằng cách sử dụng các phương pháp khác nhau như Agile/Scrum\nCó khả năng phân tích tốt, lập kế hoạch chiến lược tốt và kỹ năng giao tiếp. Có động lực cao, nhiệt tình và tự tạo cảm hứng.\nCó kinh nghiệm với Angular Progressive Web App (PWA)\nCó kinh nghiệm với Angular Mobile App with Ionic, Capacitor hoặc React Native\nCó kinh nghiệm lập trình Asp .NET Core\nCó kinh nghiệm với Oracle, MS SQL Server\nNăng lực cốt lõi\nCó tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty (IPAM & 4C)\n\nLỢI ÍCH VÀ QUYỀN LỢI\n\nCộng đồng những người làm nghề chính trực và dấn thân phụng sự\nMôi trường làm nghề tài chính chuyên nghiệp.\nLàm việc với tinh thần làm chủ, sáng tạo và thách thức.\nTổng thu nhập theo năng lực\nThu nhập xứng đáng theo năng lực và giá trị đóng góp.\nXem xét thay đổi thu nhập hàng năm.\nChế độ đãi ngộ\nTham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động.\nĐược tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24.\nTổ chức học tập và văn hóa sôi nổi.\nKhông gian làm việc mở với trang thiết bị hiện đại.\nCác hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1310, 782, 2, 'Blockchain Front-End Developer (2+ YOE upto $1500)', 'We are seeking a skilled Blockchain Developer with a minimum of 2 years of experience in front-end development to design, develop, and maintain user interfaces for our blockchain-based applications. The ideal candidate will have a strong understanding of blockchain technology, smart contracts, and decentralized systems, along with a passion for creating intuitive and responsive front-end experiences.\n\nResponsibilities:\n\nFront-End Development:\n- Design and develop user interfaces (UIs) for blockchain-based applications, ensuring a seamless and intuitive user experience.\n- Collaborate with UX/UI designers to translate wireframes and mockups into functional web applications.\n- Build responsive and visually appealing front-end components using modern frameworks like React.js, Vite, etc..\n- Integrate front-end applications with blockchain networks, smart contracts, and decentralized storage solutions.\n\nBlockchain Integration:\n- Work closely with blockchain developers to integrate front-end applications with blockchain protocols (EVM-Compatible).\n- Interact with smart contracts using Web3 framework or libraries like Web3.js, Ethers.js, Wagmi, Viem, etc..\n- Implement wallet integrations (e.g., MetaMask, WalletConnect) for user authentication and transaction signing.\n\nTesting and Optimization:\n- Write unit tests and conduct end-to-end testing for front-end applications to ensure reliability and performance.\n- Optimize applications for maximum speed, scalability, and security.\n\nCollaboration and Innovation:\n- Collaborate with cross-functional teams, including blockchain engineers, back-end developers, and product managers, to deliver high-quality solutions.\n- Stay up-to-date with the latest trends and advancements in blockchain technology and front-end development.\n\nRequirements:\n\nMust-Have:\n- Minimum of 2 years of proven experience as a Front-End Developer with a strong portfolio of web applications.\n- Proficiency in front-end technologies such as HTML, CSS, TypeScript, and modern frameworks (React.js, Vite).\n- Strong understanding of React core concepts (components, props, state, lifecycle methods)\n- Experience with popular React workflows (Redux, Context API, etc.)\n- Experience integrating front-end applications with blockchain networks and smart contracts.\n- Familiarity with blockchain concepts, including decentralized applications (dApps), smart contracts, and consensus mechanisms.\n- Knowledge of Web3 framework or libraries and tools like Web3.js, Ethers.js, Wagmi, Viem, etc.\n- Strong problem-solving skills and attention to detail.\n\nNice to Have:\n- Proven knowledge of distributed systems, Scaling Solutions, DeFi, NFT, SocialFi, and related blockchain domains.\n- Proven track record in developing complex end-to-end decentralized applications (DApps).\n\nBENEFITS:\n- Competitive income: $1200 - $1500\n- The company conducts annual performance reviews\n- Yearly performance bonus (up to 3 months\' salary)\n- 100% salary during the probation period\n- Insurance and annual health check-ups\n- 18 fully paid leave days per year\n- Company-provided equipment: Windows laptop, MacBook, or PC, depending on your job role\n- Ample growth opportunities: Develop your skills through structured training, collaboration with top industry experts, and scholarship programs to enhance your knowledge\n- Young, friendly, and inclusive work environment that respects diversity\n- Modern, spacious, and well-equipped office\n- Annual company trips, pizza parties, birthday gifts, coffee, and more!\n\nRECRUITMENT PROCESS:\n- Thank you for your interest in joining EVOL TECH! Please submit your application by clicking the \'Submit Application\' button below.\n- We will respond to you within 1 week of receiving your application. If you do not receive a response after one week, it means your application may not be suitable for this position. (Sometimes we are unable to respond to each application due to the large number of applicants. We greatly appreciate your interest and support.)\n- We will have a brief phone interview first (first round) and an online test (if applicable).\n- If you pass the phone interview and the online test, we will have an in-person interview regarding expertise (second round)\n- If you pass the second round, we will have an in-person interview regarding cultural fit (final round). If you pass the final round, you will undergo a 2-month probation before becoming a full member.\n- If you\'re available to start work right away, it would be highly beneficial.\n\nOnce again, thank you for considering EVOL TECH for your career aspirations. We eagerly anticipate the possibility of working together and achieving success!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1311, 766, 2, 'Lập Trình Viên PHP 7~15 triệu', 'Mô tả công việc\n\n- Tham gia trực tiếp vào dự án đang phát triển tại công ty, nắm bắt và phân tích các yêu cầu của khách hàng.\n- Phát triển các phần mềm ứng dụng trên điện thoại di động;\n- Thực hiện lập trình web theo yêu cầu khách hàng.\n- Code dự án với PHP.\n- Cụ thể sẽ trao đổi kỹ khi tham gia phỏng vấn\n\nKhác', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1312, 783, 2, 'DevOps Engineer Intern', 'KMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines: KMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions. KMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality. KMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors.\n\nThe Brilliant Career You Love Are you passionate about innovative software development and eager to sharpen your expertise every day? Do you dream of being part of a Great Team that creates awesome billion-dollar Software Products for U.S clients? Would you love to work in one of the Best Places to Work in Vietnam, a Top 10 ITC Company in Vietnam that invests in people development? If your answer is yes, we firmly believe that you will enjoy every single working day at KMS Healthcare.\n\nThis vacancy is an ideal opportunity for beginners who want to start their career on a high note. As one of our Software Engineer Interns, you will have the chance to acquire one of the hottest skills in the industry. You will receive training and work on complex systems using cutting-edge technology-based frameworks. Additionally, you will collaborate with talented developers, following high standard software development practices and CI/CD processes.\n\nAs an intern at KMS Healthcare, you will have the opportunity to learn and practice a wide range of skills, including but not limited to: Working under the guidance of technical leaders or senior developers, Practicing coding with a focus on high quality and effective outputs, Participating in all software development activities, Clarifying requirements with clients and the team, Writing high-quality code to implement software features or fix bugs, and implementing unit tests, Reporting project status to clients and the team.\n\nQualifications: Currently pursuing a degree in Computer Science/ Software Engineering/ Telecom & Networking or related field with an IT background, At least 4 working days per week in 3-6 months of internship; with possible conversion to permanent staff after internship are preferred, Good knowledge of one or more modern DevOps technologies, including Linux fundamentals and scripting, knowledge on various DevOps tools & technologies (source controls, configuration management, continuous testing, continuous monitoring, containerization, cloud), CI/CD, infrastructure as code, etc., Good verbal and written communication skills in English, Strong problem-solving and analytical skills, Collaborative mindset and ability to work well in teams, Curiosity and eagerness to learn emerging technologies, Attention to detail and commitment to high-quality work, Proactive and self-motivated with good time management.\n\nTo help us have a good understanding about your competencies & your dream job to match with future suitable KMSH opportunities, we look forward to receiving your academic transcript & the latest CV mentioning your desired position.\n\nAdditional Information: Working in one of the Best Places to Work in Vietnam, Top 10 ITC Company in Vietnam, Flexible working model: Flexible time & Hybrid working from Ho Chi Minh or Da Nang city, Attractive Allowance with possible conversion to permanent staff after internship are preferred, Diverse careers opportunities with Software Services, Software Product Development, Working and growing in a values-driven, international working environment and standard Agile culture with passionate and talented teams, Various training on hot-trend technologies, best practices and soft skills, Company trip, big annual year-end party every year, team building, etc., Fitness & sports activities: football, tennis, table tennis, badminton, yoga, swimming… Joining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,… Free in-house entertainment facilities (football, ping pong, gym…), coffee, and snacks (instant noodles, cookies, candies…) And much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '다낭, 베트남', 'Internship', '2025-10-07 20:59:18.149534'),
	(1313, 533, 2, 'Cộng tác viên Kiểm thử chất lượng/Tester', 'I. GIỚI THIỆU CHUNG\nVinBigdata\nCông ty cổ phần VinBigdata được thành lập theo định hướng trở thành tập đoàn Công nghệ – Công nghiệp – Thương mại Dịch vụ hàng đầu Việt Nam của Vingroup. Với lợi thế đặc biệt về hạ tầng dữ liệu lớn, VinBigdata cung cấp các sản phẩm, giải pháp tiên ứng dụng trí tuệ nhân tạo, giúp doanh nghiệp đẩy nhanh quá trình chuyển đổi số, tối ưu hiệu quả vận hành, kinh doanh và gia tăng trải nghiệm người dùng cuối.\n\nLà một công ty trẻ trung và đang trong giai đoạn phát triển nhanh chóng, VinBigdata luôn chào đón những tài năng gia nhập công ty để cùng thực hiện mục tiêu “Công nghệ Việt – Vì tương lai Việt”.\n\nChúng tôi đề cao và tìm kiếm các nhân sự có tinh thần sáng tạo, đam mê tạo ra những sản phẩm và dịch vụ mới giúp người Việt Nam có cuộc sống tiện lợi, văn minh và lành mạnh hơn, sẵn sàng thử thách bản thân, học hỏi và chịu được áp lực lớn trong công việc.\n\nGiới thiệu về phòng ban chuyên môn/ dự án:\nNhóm kỹ sư kiểm thử chất lượng của trợ lý ảo thông minh đảm nhiệm việc đảm bảo chất lượng trọng quá trình phát triển và triển khai các sản phẩm như hệ sinh thái trí tuệ nhân tạo đa nhận thức toàn diện Vinbase, trợ lý ảo Vivi ứng dụng linh hoạt trong hệ sinh thái thông minh trên xe ô tô, loa, nhà thông minh.\n\nII. MỤC ĐÍCH CỦA VỊ TRÍ NÀY\n- Chuẩn bị, cập nhật và duy trì tài liệu kiểm thử liên quan, bao gồm các kịch bản, sơ đồ, mẫu kiểm thử, đảm bảo tuân thủ quy trình thử nghiệm và tiêu chuẩn chất lượng. Thực hiện đánh giá phần mềm, hoàn thiện kịch bản kiểm thử và ghi lại bằng chứng kiểm thử để đảm bảo phần mềm đáp ứng thông số kỹ thuật.\n- Nghiên cứu & tìm hiểu yêu cầu nghiệp vụ, yêu cầu hệ thống từ BA hoặc các bên liên quan. Dựa vào kinh nghiệm và hiểu biết, góp ý & hỗ trợ BA hoàn thiện yêu cầu chi tiết. Thiết kế luồng hội thoại tương tác giữa khách hàng và bot trong nhiều ngữ cảnh khác nhau.\n- Thực hiện kiểm thử tự động để kiểm tra hệ thống và phần mềm, đồng thời ghi lại kết quả kiểm tra trong các báo cáo và tài liệu liên quan.\n- Phối hợp với các thành viên khác để thực hiện các công việc liên quan đến kiểm thử.\n- Phối hợp với khách hàng để cập nhật tài liệu liên quan.\n\nIII. TRÁCH NHIỆM\n- Nghiên cứu tài liệu về nghiệp vụ và kỹ thuật của hệ thống để tìm ra và đánh giá các ràng buộc của sản phẩm, bao gồm các sản phẩm: Hệ thống quản lý, Giải thuật AI, Backend, Frontend, ứng dụng mobile.\n- Lên kế hoạch và phương án kiểm thử theo quy trình Agile Scrum.\n- Chuẩn bị và cập nhật các tài liệu liên quan đến kiểm thử bao gồm: kế hoạch, kịch bản, sơ đồ mô tả, dữ liệu và các báo cáo kiểm thử theo tiêu chuẩn chất lượng.\n- Thực hiện kiểm thử, phối hợp với các thành viên khác để đánh giá chất lượng phần mềm.\n- Phát triển framework kiểm thử phần mềm của Trung tâm theo quy trình phát triển, áp dụng kiểm thử tự động.\n- Các công việc khác theo phân công của cấp trên.\n\nIV. YÊU CẦU\nHọc vấn:\n- Sinh viên hoặc người mới tốt nghiệp đại học chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan, có định hướng phát triển trong lĩnh vực Kiểm thử phần mềm.\n\nKiến thức và Kinh nghiệm:\n- Nắm được quy trình kiểm thử phần mềm, các kỹ thuật và chiến lược kiểm thử cơ bản.\n- Nhanh nhẹn, chăm chỉ, ham học hỏi và có tinh thần trách nhiệm cao trong công việc.\n- Hòa đồng, thân thiện, có khả năng làm việc nhóm và chủ động trong công việc.\n\nKỹ năng:\n- Kỹ năng mềm: Quản lý thời gian hiệu quả, giao tiếp tốt, phối hợp nhóm linh hoạt. Sẵn sàng hỗ trợ các mảng công việc khác khi cần thiết.\n- Kỹ năng chuyên môn: Có hiểu biết cơ bản về Backend, Frontend, Database, ứng dụng di động và vòng đời phát triển phần mềm.\n- Kỹ năng máy tính: Biết lập trình, có khả năng xây dựng framework kiểm thử tự động là một lợi thế.\n- Ngoại ngữ: Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh.\n\nV. THÔNG TIN CHUNG\nSố lượng: 03\nĐịa điểm làm việc: Tầng 9, tòa nhà Century, Times City, 458 Minh Khai, Hà Nội\nThời gian làm việc: 40 giờ/ tuần (từ Thứ Hai tới Thứ Sáu)\nChế độ phúc lợi: Mức lương hấp dẫn, tương xứng với năng lực và cạnh tranh trên thị trường.\nCơ hội phát triển: Cơ hội làm việc trong môi trường chuyên nghiệp, công nghệ dẫn đầu về AI, quy tụ hơn 100 nhà khoa học, chuyên gia, kỹ sư đến từ các trường đại học hàng đầu thế giới và Việt Nam như: ĐH Yale (Mỹ), ĐH Johns Hopkins (Mỹ), ĐH Illinois (Mỹ), ĐH Toulouse (Pháp), ĐH Cambridge (Anh Quốc), Đại học Bách Khoa, Đại học Công nghệ – Đại học Quốc gia, …\nĐược xây dựng kế hoạch phát triển cá nhân và tham gia đào tạo kỹ năng, chuyên môn phù hợp.\nMôi trường làm việc: Văn phòng hiện đại, tiện nghi, trẻ trung và chuyên nghiệp. Môi trường làm việc cởi mở, khuyến khích nhân viên đóng góp ý kiến, sáng kiến, ý tưởng.\n\nTrải nghiệm hệ sinh thái của VinBigdata:\n→ Linkedin: https://bit.ly/3g7IhDQ\n→ Youtube: https://bit.ly/3vMS88X\n→ Blog: https://lnkd.in/dMgbeqNh', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1314, 755, 2, 'Junior/Mid Fullstack Engineer (TypeScript/JavaScript) - Hybrid working model 100%', 'Welcome to SMG Vietnam! SMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.  This job refers to our Real Estate brands, Homegate and Immoscout24, the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing. We are looking for a Junior/Mid Fullstack Engineer to help us build the future of the Swiss real estate market by contributing to our cutting edge, cloud based, technology stack. You will get to collaborate and access the wealth of knowledge and experience from a community of amazing engineers who come from all parts of the globe and are ready to share their expertise and aid you in your path to fulfilling your potential. Join our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nOur tech stack: Frontend: Vue.js with TypeScript, Backend: Node.js and TypeScript, following a serverless microservices architecture in an AWS cloud environment (Lambda, DynamoDB, SQS, SNS, S3, etc.), Monitoring: Datadog, Documentation: Backstage.\n\nYour Mission: Building and experimenting: Writing clean, modular code within a modern, serverless architecture, with a focus on refining and experimenting with functionality. Collaborating and creating: Working closely with a talented team of engineers to design, develop, and deliver features that make a real impact on users. Learning and applying: Gaining hands-on experience with AWS Serverless, CI/CD, and other cutting-edge tools like AI/Datalake, continuously enhancing skills along the way. Contributing to innovation: Bringing fresh ideas to improve both software and processes, always looking for opportunities to push boundaries. Your responsibilities will evolve as we grow.\n\nQualifications: What will you bring to the ride? Fluent in English, both written and spoken. Bachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience. 1+ years of experience in Software Development. Experience with TypeScript/JavaScript, with proficiency in at least one of the following: Comfortable with Vue.js or React.js, and capable of building modern web applications. Experience with Node.js backend development, including implementing synchronous and asynchronous services. Some exposure to AWS services and a Serverless Technology Stack. Strong sense of ownership and responsibility for what the team builds. Before blindly adding code to a codebase, be able to identify problematic areas and refactor them with maintainability and stability in mind. Curious, open-minded, and enthusiastic about growing in a collaborative team environment. Ability to use AI tools to assist with coding is a plus. We value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique.\n\nAdditional Information: What do we offer? Competitive Benefits: Attractive salary, full pay during probation, 13th-month bonus, and full social insurance contributions. Generous Leave: 21+ annual paid days off, 24 days for learning & sharing, and flexible working hours with no overtime. Health & Wellness: Premium private insurance for you and your family, free food, and access to various classes and clubs. Growth Opportunities: Personalized development plans, yearly education budgets, regular Hackathons, and potential travel to Switzerland and Europe. Modern Work Environment: Hybrid model, top-tier equipment, and a friendly, agile, and transparent culture. Supportive Onboarding: Comprehensive assistance to help you settle in. Recruitment Process: We believe hiring is a two-way street, where both parties get to know each other. Here\'s what you can expect: Initial screening call with HR – A brief conversation to understand your background and expectations. Meeting with the Hiring Manager – A deeper discussion about the role, your experience, and how we work. Technical Assessment – A hands-on assessment of your skills, conducted via live coding and system design exercises. Casual Meeting with Director – An informal conversation to align on vision, culture, and goals.\n\nAt SMG Vietnam, we value diverse perspectives and individual growth. We welcome candidates from all backgrounds and encourage you to apply, even if you don’t meet every requirement. Together, we embrace differences, nurture potential, and celebrate success. Apply now to take this opportunity, send us your detailed CV and feel free to add any supporting documents we need to look at in order to understand that you are the perfect fit.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1315, 713, 2, 'Frontend Engineer', 'Job Type\n\nFull-time\n\nResponsibilities and Duties\n\nOnce You Join Our Team, You Will\n\n- Collaborate with other team members (PM, UI, backend engineer, QA) to provide a seamless freight experience for our customer;\n- Participate in designing the front end architecture, collaborate with backend engineers to develop and deliver elegant product solutions;\n- Propose innovative technical solutions to hard business problems;\n- Curiosity and passion, understanding of LLM and AI Agent framework;\n- Lean and grow constantly, improve yourself and make the team members around you better\n\nRequirements\n\nMinimum Qualifications\n\n- Bachelor degree in Computer science or related field;\n- At least 3+ years of working experience in the related field;\n- Fluent in JavaScript, CSS, HTML;\n- Fluent in Vue frameworks, MVC, MVVM architecture\n- Experience with at least one modern JavaScript framework (React, Vue)\n- Fluent in REST APIs in web context, GraphQL experience is a plus\n- Good engineering habits with maintaining codebase, familiarity with Git, Webpack;\n- Clear understanding of division between front end and back end;\n- Build products that delight the user, paying close attention to detail of UI elements;\n- Sensitivity to front-end architecture and components, preferably with experience working on large scale engineering projects;\n- A commitment and drive for quality, excellence and results balanced with a creative mindset;\n- Raise the quality and speed bar of the entire team and yourself into a position of maximum leverage;\n- Be familiar with AWS and amplify is a plus\n- Good communication skills, with fluent verbal English.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 3, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1316, 784, 2, 'Software engineer - F/M/X', 'Who are we?\n\nMantu is an independent international consulting player, founded in 2007. Bringing together expert and complementary brands, Mantu stands out for the breadth of its spectrum, responding to all business transformation challenges.\n\nIts activities are divided into four practices:\n\nLeadership & Advocacy, Technology, Digital Marketing & Experience, Total Talent Management.\n\nA wide range of skills, all serving a single mission: connecting and powering companies with leading teams and technology to succeed faster and sustainably. \n\nFrom its headquarters in Geneva, Switzerland, Mantu relies on a community of 12,000 talented people in more than 60 countries on 5 continents and has a turnover of 1 billion euros.\n\nJob Description\n\nJoin our team and start a new adventure in an international and dynamic environment, where you will be able to fulfil your career expectations in a fast-growing organization.\n\nAs a Software Engineer at Mantu, you will work in a collaborative and agile setting to design and develop innovative digital solutions for our business and clients.\n\nYour missions\n\n- Collaborate with business and technology stakeholders to analyze requirements and assess their impact on existing applications\n- Design, develop, test, deploy, maintain, and improve software solutions\n- Conduct code reviews to support your colleagues in their assigned tasks\n- Develop flowcharts, layouts, and documentation to define requirements and solutions\n- Implement and manage CI/CD pipelines to ensure continuous integration and deployment\n- Contribute to software testing plans and quality assurance procedures\n- Ensure compliance with project plans, industry standards, and regulatory requirements\n\nYour profile\n\n- Academic background: Bachelor’s degree or higher in Computer Science, Software Engineering or equivalent\n- Proficiency in application development using .NET Core & C#\n- Strong understanding of API development, microservices architecture, and event-driven systems (REST, RESTful)\n- Experience in configuration management using Git (understanding Gitflow vs. trunk-based development)\n- Hands-on expertise in CI/CD practices\n- Familiarity with Scrum methodology and Agile development workflows\n- Knowledge of Elasticsearch is a strong plus\n- Ability to document technical processes using methodologies such as C4, TOGAF, or 4+1\n- Fluent in Vietnamese and English\n- You have an ability to synthesize information and work efficiently in a collaborative environment\n\nWhy Us?\n\n- Being part in an International and multicultural environment.\n- Fast growing global company, opportunities to grow quickly with a tailored made career path.\n- Soft skill trainings: interpersonal communication, team management, project management.\n- Ability to support non-profit organizations.\n- You will have the opportunity to unlock your potential, both professional and personally.\n\nMantu is proud to be an equal-opportunity workplace. We are committed to promoting diversity within the workforce and creating an inclusive working environment. For this purpose, we welcome applications from all qualified candidates regardless of gender, sexual orientation, race, ethnicity, beliefs, age, marital status, disability, or other characteristics.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1317, 723, 2, 'Lập trình viên JAVA', 'NMS đang tìm kiếm 05 ứng viên cho vị trí lập trình viên java. Làm việc trực tiếp với đối tác, phối hợp triển khai dự án phần mềm tại Việt Nam.\n\nCơ Hội Và Lợi Ích\n\nLàm việc trong dự án lớn cùng các thành viên kỳ cựu tại NMS.\nTham gia lớp tiếng nhật sơ cấp (N4) – Học từ đầu tháng 12/2018, thời gian học 6 tháng.\nĐược đạo tào trước khi vào dự án (Onsite)\n\nMô Tả Công Việc\n\nBáo cáo trực tiếp cho Functional lead/Project Manager.\nThực hiện tư vấn, phân tích các yêu cầu từ khách hàng.\nLàm các loại tài liệu thiết kế chức năng dựa trên các yêu cầu của khách hàng (BRD)\nTạo test case, thực hiện UAT (User acception test) với khách hàng.\n\nQuyền Lợi\n\nMức thu nhập cạnh tranh\n“NMS care” bảo hiểm dành riêng cho nhân viên NMS.\nNghỉ hè: Theo chính sách của công ty ( vào tháng 5 hàng năm).\nCó cơ hội được xem xét nâng lương 2 lần 01 năm, tùy vào kết quả công việc.\nMôi trường làm việc hiện đại, thân thiện.\nChính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.\n\nYêu Cầu\n\nCó kinh nghiệm sử dụng Java.\nCó kinh nghiệm làm việc với các nền tảng Hirbernate, Spring, Struts, … là lợi thế.\nCó kinh nghiệm về hệ quản trị cơ sở dữ liệu Oracle, MySQL, MongoDB là lợi thế.\nTiếng anh yêu cầu có thể đọc và hiểu tài liêu\nKỹ năng làm việc theo nhóm tốt. Ưu tiên các ứng viên đã có kinh nghiệm thực hiện các dự án outsource.\n\nĐịa điểm làm việc: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình, Hà Nội\n\nỨng Tuyển Ngay\nMs Huyền: 0338 323 955/ 0969709429 / mail:huyenlt@nms.com.vn / skype:huyenthu.hr\n\n——————————–\n\nCông ty cổ phần Dịch vụ Di động Thế Hệ Mới (NMS)\n\n🏬 Hệ Thống Trụ Sở\n\n– Trụ sở chính NMS: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình, Hà Nội\n\n– Chi nhánh NMS Hòa Lạc: Tầng 8, Tòa nhà HTC Phú Cát, Khu công nghệ cao Hòa Lạc, Thạch Thất, Hà Nội\n\n– Chi nhánh NMS TP. Hồ Chí Minh: Lầu 3 – 385C – Nguyễn Trãi Quận 1 – TP. HCM\n\n– Chi nhánh Nhật Bản: 3F Hoshino Building, Nishi Shinjuku, Shinjuku, Tokyo\n\n☎ Điện thoại: 024.7300 8555\n\n🌎 Website: https://nms.com.vn/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1318, 785, 2, 'Java Software Engineer', 'GIỚI THIỆU VỀ CLEVAI\n\nClevai là một đơn vị đào tạo ứng dụng GenAI cho người lớn, và Toán, tiếng Anh trực tuyến cho trẻ em với công nghệ AI hàng đầu tại Việt Nam. Clevai trở thành top 3 đơn vị đào tạo Toán online chỉ sau hơn 2 năm thành lập, do kết hợp các lớp Live Streaming 2 thầy 1 trò, các lớp kèm nhóm nhỏ với công nghệ AI Adaptive Learning, các trò chơi và phần thưởng thú vị để triển khai các khóa học được đánh giá mức 4.8. Clevai là đơn vị tiên phong trong ứng dụng các công nghệ mới vào giáo dục, và là đơn vị tổ chức chuỗi hội thảo Tech For Study với hơn 20 diễn giả cao cấp là lãnh đạo các đơn vị công nghệ như VinAI, Earable, Ohmnibot…, các học giả từ Harvard, Oxford…, nhiều người trong số đó đang tham gia cố vấn cho Clevai. Clevai nhận đầu tư từ các quỹ Altara Ventures, FEBE Ventures, FJ Labs, và được HSBC và KPMG bình chọn trong số các “Người khổng lồ đang nổi ở Châu Á-Thái Bình Dương 2022”. Clevai đang có kế hoạch mở rộng ra Đông Nam Á và trở thành một trong top 5 hệ sinh thái giáo dục trực tuyến trong vòng 5 năm tới.\n\nLink web https://clevai.edu.vn/\n\nBẢN MÔ TẢ CÔNG VIỆC\n\nVị trí: Senior Java Developer\n\n1. Mô tả công việc: \nPhát triển và vận hành hệ thống:\n- Các hệ thống Back-end đáp ứng nhu cầu của 1-5 triệu người dùng traffic cao (Video, Audio) trong 3-5 năm tới\n- Triển khai các kiến trúc Microservice và Domain-Driven Design để thực thi các mục tiêu: tăng tốc độ triển khai sản phẩm, khả năng mở rộng cao cả về quy mô lẫn tính năng, tối ưu performance và reliability.\n- Xử lý các nguồn dữ liệu multi-sensor: Brainwave Detection, Webcam Emotion Detection, Voice Recognition… để xây các mô hình và ứng dụng AI-based Personalized Learning, GPT hỗ trợ việc dạy và học.\n- Làm việc trong các squad team theo mô hình Agile với đầy đủ các role, phân chia theo A/B Testing-driven và Architecture-led projects, theo các nhóm End-User và Enterprise User.\n- Môi trường công nghệ: Micro-Service Architecture from Day 1; main tech stacks: Java, PHP, Python, SpringBoot, ReactJS, React Native, mySQL, mongoDB, Redis, Kafka. Infrastructure 100% based on K8s.\n\n2. Yêu cầu:\n- 4 năm làm Back-End (lập trình Java) đã từng thiết kế solution cho ít nhất 2-3 dự án.\n- Tinh thần trách nhiệm cao cả về chất lượng code và tiến độ delivery.\n- Linh hoạt trong việc lựa chọn các giải pháp, thuật toán tùy theo từng mục tiêu: product velocity, khả năng mở rộng tính năng, performance, reliability…\n- Ưu tiên kinh nghiệm làm việc ở các công ty Tech có tên tuổi trong và ngoài nước.\n\n3. Quyền lợi:\n- Lương cạnh tranh Upto 3000$, Thưởng năng suất dựa trên đánh giá minh bạch mỗi kỳ 6 tháng.\n- Tốc độ tăng lương và cổ phần thưởng (ESOP) của các nhân tài (10% trên cùng) gấp 6x của nhân sự thông thường (35% dưới).\n- Cổ phiếu thưởng cho 90% quản lý và chuyên gia cấp trung, và cho 20% nhân viên cấp dưới.\n- Văn hóa đặc trưng kiểu Silicon Valley: Cấu trúc hóa các vấn đề qua “Voi”, Thẳng thắn cực đoan, các mục tiêu OKR hàng quý đo đạc qua dữ liệu, Bàn tròn “Ném đá sếp” mỗi kỳ, “Trà đá” khi có mâu thuẫn, “TGIF” hỏi đáp lãnh đạo trước toàn công ty hàng tháng…\n- Thử việc: 2 tháng hưởng 100% lương, BHXH theo quy định, thưởng sinh nhật, du lịch, team building,…\n\n4. Thông tin khác:\n- Trụ sở chính: Tầng 12, Bishub, Toà nhà Mipec, 229 Tây Sơn, Đống Đa, Hà Nội.\n- Khu vực HCM : Phường Đakao, Quận 1, TP HCM (HCM làm Hybrid).\n- Thời gian làm việc: Thứ 2 - Thứ 6, từ 09h00 - 18h30 (Nghỉ trưa 12h00 - 13h30).\n- Hình thức PV 2 Vòng : V1 CTO + Leader, V2: Phỏng vấn văn hóa + Deal lương.\n\n5. Cách thức ứng tuyển:\n- Ứng viên quan tâm vui lòng gửi CV qua mail: haott@clevai.edu.vn.\n- SDT/Zalo: 035 908 7677.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1319, 786, 2, '【教育事業】フロントエンドエンジニア', '職務内容\n\nスマートフォンやパソコンで様々な授業を受けることができる教育サービス「ZEN Study」のWebフロントエンド開発を担当していただきます。\n\n＜サービスの紹介＞\n\n私たちは、未来の「当たり前」の教育をつくるため、生徒・学生や教職員の「学ぶ」「教える」体験の最大化を日々目指しています。 日本発の本格的なオンライン大学「ZEN大学」や、3万名を超え日本最大の生徒数であるネットの高校「N高等学校・S高等学校・R高等学校」と連携し、ネットの時代に合わせた教育関連のサービスを開発・運営しています。\n\n※ R高等学校は2025年4月開校準備中\n\n【ZEN Study（旧: N予備校）】\n\nひとつで学習が完結するオールインワン学習アプリです。 主に次のような機能を提供しています。\n\n・リアルタイムに先生や仲間の生徒とコミュニケーションを取ることで理解を深める「ライブ授業」\n\n・自分のペースで学習を進めることができて一目で進捗率がわかる「教材」\n\n・学習者同士の教え合いの場「フォーラム」\n\n※「N予備校」は2024年8月末に「ZEN Study」にリニューアルしました\n\n【ZEN Compass】\n\n学習者を導く先生方などが利用するコーチング支援Webサービスです。 LMS(Learning Management System)として学習状況を見ることができるだけではなく、より学習者を効率的に支援できるように、さまざまな指標で先生方を支えます。\n\n＜募集背景＞\n\n私たちZEN StudyのWebフロントエンドチームは、より多くの人が安心して学習に集中できる状態にすることを使命としています。機能の提供にとどまらず、安定して快適な学習の場を作り、守り続ける必要があります。\n\nZEN Studyでは今後、「学ぶ人」の目標達成をより支援する機能、「教える人」の指導を支援する機能など、未来の「当たり前」となる学習の場になっていくべく、更なる変化を計画しています。\n\n全ての「学ぶ人」と「教える人」のために、新しい学習体験を一緒に作るWebフロントエンジニアを募集しています。\n\n＜業務内容＞\n\n実装だけでなく設計からリリース、FrontendOpsのような領域、ときには要件定義まで幅広く、アプリケーション開発に関わること全般をご担当いただきます。\n\n業務の一例：\n\n・アプリケーションのWebフロントエンド開発と改善\n\n　－新規機能や新規関連サービスのための調査・設計・開発\n\n　－コードベースの定常的なリファクタリングや、その方針に関する議論\n\n・アプリケーションのWebフロントエンドの運用\n\n　－Webフロントエンド実装のデプロイ・リリース\n\n　－エラー検知やパフォーマンス監視と修正\n\n　－依存ライブラリ、実行環境の定常的な更新\n\n　－上記全ての必要に応じた自動化\n\n・Webフロントエンド開発と開発チームのための種々の業務\n\n　－業務知識や開発知識のドキュメンテーション\n\n　－カジュアル面談や選考への参加などの採用活動\n\n＜開発環境＞\n\n□ 代表的な利用ライブラリ\n\n・React\n\n・Next.js\n\n・Vite\n\n・TypeScript\n\n・Styled Components, Panda CSS\n\n・Webpack\n\n・Biome, ESLint, Prettier\n\n・Storybook\n\n・Vitest, Jest, Testing Library\n\n□ 代表的な使用ツール\n\n・GitHub Enterprise\n\n・Figma\n\n・Slack\n\n・Google Workspace (Meet, Docs, Sheets, Slides)\n\n・Zoom\n\n・JIRA, Confluence\n\n・Sentry\n\n・Google Analytics\n\n＜関連リンク＞\n\n□ エンジニア採用説明資料\n\nhttps://speakerdeck.com/nnndev/for-engineers\n\n□ドワンゴ教育サービス開発者ブログ\n\nhttps://blog.nnn.dev/\n\n□ ZEN Study\n\nhttps://www.nnn.ed.nico/\n\n□ N高等学校・S高等学校・R高等学校プロジェクト採用\n\nhttps://www.nnn.ed.nico/recruit/\n\n□ ZEN大学\n\nhttps://zen.ac.jp\n\nhttps://www.syllabus.zen.ac.jp/\n\n働く魅力\n\n・学校運営をするドワンゴならではのプロダクト開発\n\n　－「ZEN Study」はN高グループの教材として、日々生徒に活用してもらうプロダクトになります。一般ユーザー向けの学習補助サービスは世の中にたくさんありますが、このプロダクトは学校での主要な学習までも担っています。教育領域に興味あるエンジニアには開発のやりがいがあるプロダクトだと思っています。\n\n・UI/UX観点で開発ができる\n\n　－N高グループの生徒が高校卒業に必要な単位を取得するために毎日触り、学ぶことにストレスを感じさせないためのプロダクト開発をフロントエンドエンジニアとして経験ができます。企画やデザイナーと一緒にUI・UXについてエンジニア観点で話しを進めながらプロダクト成長に関われるポジションです。\n\n・全員リードエンジニアのスタンス\n\n　－ユーザー体験を向上させるために常に最新技術を追求しながら、最適な技術選定をしてプロダクトに取り入れています。この技術選定は1人のリードエンジニアだけで行うのではなく、チーム全員で会話をしながら最適解を見つけていくため、裁量を持ちながら働きたい方にはやりがいあるポジションです。\n\n・働きやすさ\n\n　－リモートワーク、裁量労働制を導入しているため、ご自身の生活に合わせた働き方が可能です。また、評価制度や福利厚生なども整備されていて働きやすい環境です。\n\n必須要件\n\n・コンピューターサイエンスの基礎知識を身に着けている\n\n・HTML, JavaScript, CSS, WebブラウザやHTTPなど、Webの基礎知識がある\n\n・Webアプリケーションのフロントエンド開発経験が3年以上、または相当する経験がある\n\n・React等のコンポーネントベースなフレームワークを用いた開発に習熟している\n\n※ご応募時にGitHubアカウントや外部ブログURLなど、スキルがわかるものをご提出ください\n\n歓迎要件\n\n・大規模なWebフロントエンドの開発・運用経験がある\n\n・複雑なWebフロントエンドの開発・運用経験がある\n\n・Webフロントエンドのビルドからデプロイ、配信やキャッシュまで含めたWアーキテクチャ設計経験がある\n\n・Webフロントエンドのパフォーマンス改善に取り組んだ経験がある\n\n・Webフロントエンドのアクセシビリティ向上や、サービス全体のアクセシビリティ向上に取り組んだ経験がある\n\n・コードベースや開発環境の改善に継続的に取り組んだ経験がある\n\n・デザインやバックエンド等を含めた、Webフロントエンドの周りにある業務改善に取り組んだ経験がある\n\n・Webフロントエンドのエンジニアの採用活動に関わったことがある\n\n求める人物像\n\n・Webやプログラミングが好きな方\n\n・Webフロントエンドのプロであり続ける・あろうとし続ける方\n\n・現状を尊重した上で、とらわれずに目の前の問題と戦う方\n\n・問題や仕様の精緻な理解に基づく、大胆なアプローチができる方\n\n・理想が遠くても、一歩を積み重ねていける方\n\n・職種や職位、開発手法やフェーズにとらわれず、プロダクトの成功のために自発的に行動できる方\n\n・上記のようになりたいと考え、行動を始めている方\n\n職種 / 募集ポジション 【教育事業】フロントエンドエンジニア\n雇用形態 正社員\n給与 応相談 前職を考慮し、当社基準により決定いたします。\n昇給：年2回（6月・12月）本人の能力・役割に基づいて評価\n賞与：年2回（6月・12月）本人の成果に基づいて支給\n※ご入社時期、個人の評価、会社の業績により夏季賞与・冬季賞与額が変動いたします。\n※退職金は前払い退職金制度\n勤務地\n\n104-0061 東京都中央区銀座四丁目12-15 歌舞伎座タワー\n地図で確認 \n\n勤務形態 裁量労働制（1日8時間のみなし労働)\n休日休暇 完全週休2日制（土・日）、祝日（※超会議に伴う営業日変更あり） ・年次有給休暇（入社日に5日、入社日の3ヶ月後に15日付与） ・記念日休暇 ・年末年始休暇（12/29～1/3） ・リフレッシュ休暇（年度ごとに2日間付与） ・特別（慶弔）休暇\n手当・制度 ・テレワーク手当 ※テレワーク対象となる社員（条件有り）に対し、月額2万円を支給\n・通勤交通費手当（上限月額50,000円） ※テレワーク対象者は原則支給しない ただし、業務指示における出社時の交通費は会社が認める範囲で別途支給\n・育児手当（上限月額50,000円） ※扶養の子の保育料の半額を支給\n・役職手当（役職に応じて支給）\n・資格取得手当制度\n・サブスク手当（対象のサブスクを契約している場合、月額2千円を支給）\n福利厚生 ・各種社会保険完備（関東ITソフトウェア健康保険組合）\n・確定拠出年金制度\n・財形貯蓄制度\n・社員持株会制度\n・社内カウンセリング制度\n・同好会\n・健康保険組合各種サービス\n・社員限定美容室\n選考プロセス 書類選考後、2回の面接を想定しています。\n※1次面接までに当社が指定する適性検査を受検いただきます。\n※全てオンライン面接となります。\n※選考の過程でコードテストを実施する可能性があります。\n会社情報 会社名 株式会社ドワンゴ 代表者 代表取締役社長 夏野 剛 事業内容 ネットワークエンタテインメントコンテンツ及びシステムの企画、開発、運用、サポート、コンサルティング 設立 1997年8月6日 資本金 1億円（2019年3月29日現在） 所在地 〒104-0061 東京都中央区銀座4-12-15 歌舞伎座タワー 親会社 株式会社KADOKAWA 子会社 株式会社バンタン 株式会社スパイク・チュンソフト Spike Chunsoft, Inc. 株式会社バーチャルキャスト 株式会社カスタムキャスト 株式会社GeeXPlus 株式会社PUBLUS\n\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 12, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1320, 787, 2, 'Next JS Programmer', 'SFVN Investment Corporation operates as an Official Trading Member of Mercantile Exchange of VietNam (MXV). SFVN’s goal is not only to become the market leader in brokerage in commodity trading but also to provide the best quality services built by a team of professionals with expertise and experience. The foundation of the quality of the service is professionalism, transparency, and standards of professional ethics.\n\nWe are looking for a Next JS Programmer to create new software application systems as well as maintaining existing software applications used in the firm. This is a technical hands-on role. The primary focus for this position is application development, understanding and gathering of user requirements.\n\nResponsibilities:\n• Understand and gather requirements from users requirements for application system development.\n• Develop and maintain Next JS websites based on business requirements.\n• Develop and maintain in-house enterprise applications like out of office system, CRM, etc using Next JS framework.\n• Implement RESTful / Websocket API to communicate with Backend System.\n• Implement UI/UX and develop interactive and dynamic websites based on business requirements.\n• Maintain existing application systems and websites used by Straits Financial Group.\n• Maintain alignment with Straits Financial Group IT policies and procedures.\n\nCandidate Skills/Requirements:\n• Minimum 3 years application development experience ideally frontend development experience.\n• Strong knowledge and experience in Website development is desirable. Including but not limited to HTML5, CSS, Next JS, Node JS, Tailwind etc.\n• Ability to pick up new programming languages for application development.\n• Self-motivated, high level of dependability, organization, attention to detail, strong communication and problem solving skills required. Candidate must be able to efficiently multi-task in a fast-paced and challenging environment.\n• Strong team player.\n• Python coding and knowledge on Robotic Process Automation tools is a plus.\n• Background and working knowledge of IT Compliance and cybersecurity is a plus.\n• Working knowledge of commodity futures trading platforms is a plus.\n• Good at English is preferred.\n\nBenefits of candidates:\n• Competitive salary.\n• Health insurance, social insurance, unemployment insurance.\n• Travel and team building activities in accordance with the company\'s guidelines and policies.\n• Work in an international environment, utilizing English for seamless interaction with professional departments from diverse countries.\n• Working environment: Dynamic, fair competition.\n• Working time: 8:00 AM - 5:00 PM, Monday to Friday.\n• Probationary period: 2 months.\n\nLocation:\nSaigon Pearl Villas, Nguyễn Hữu Cảnh, Phường 22, Bình Thạnh, Thành phố Hồ Chí Minh, Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1321, 788, 2, 'Java Software Engineer', 'Job Description\n\n• Work in a team of engineers to implement backend services in the platform\n• Build service definitions, OpenAPI specifications, SDKs, and documentation for other developers that consume these services\n• Integrate with other services and data sources using APIs, messaging systems, databases\n• Collaborate with the DevOps team on microservices design, containerization, and automated deployments\n• Build automated test suites to ensure these services are reliable and performant\n\nRequirements\n\n• Experience min 3 years working with Java and one or more Java frameworks such as Spring Boot\n• Project experience around web service design and RESTful APIs\n• Expertise with the OpenAPI Specification (Swagger), RESTful APIs, and related tools such as Postman, cURL, and HTTPie\n• Experience integrating with 3rd party services and databases such as Redis, message queues, MongoDB, and ElasticSearch\n• Agile/SCRUM methodology experience\n\nJob Benefits\n\n• Salary: Negotiable\n• Performance review: 2 times/year\n• 14th-month salary bonus\n• KPI bonus based on project and performance\n• Extra package: 16 Mil /employee/year (Bonus at Tet, New Year, your birthday, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, …)\n• Opportunity to work in a professional, modern, and dynamic environment, take part in international projects\n• Opportunity to get on-job training and promotion\n• An excellent corporate culture with in/out of office activities that help to develop staffs ability and creativity\n• CMC health care and social insurance\n\nMail: dttnhung@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1322, 789, 2, 'Lập Trình Viên (PHP, .Net)', 'Mô tả công việc\n\n- Tham gia phát triển các sản phẩm của công ty theo nhiệm vụ được giao:\n- Mảng sản phẩm: Các giải pháp công nghệ về giáo dục như: Elearning, phần mềm thư viện libol ,sách giáo khoa điện tử, tài liệu học tập, classbook, …\n- Chi tiết dự án:\n- Phát triển các dự án Elearning: lập trình bằng ngôn ngữ PHP làm việc trên Moodle (chưa biết sẽ được đào tạo)\n- Phần mềm thư viện: ngôn ngữ lập trinh .Net: làm web và backend…(chưa biết sẽ được đào tạo)\n- làm các dự án web: không giới hạn ngôn ngữ, biết PHP và .Net là lợi thế\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1323, 702, 2, 'Pioneer Talent Program - Smart Contract Security Engineer', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 230 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nAbout The Pioneer Talent Program\n\nAre you an early-career professional ready to kickstart your career in the dynamic world of blockchain? Binance’s Pioneer Talent Program is designed to nurture ambitious individuals like you. The program offers full-time roles where participants will gain hands-on expertise via a tailored training curriculum and personalized 1:1 mentorship from industry leaders. Dive behind the scenes of the world’s leading blockchain ecosystem while building the skills to thrive in Web3. Launch your career with purpose—join us in shaping the future of digital innovation.\n\nWho May Apply\n\nCandidates with up to 5 years of relevant work experience\n\nAbout The Role\n\nThis is a unique opportunity to contribute to the field and contribute to the blockchain community. You will work hand-in-hand with various talented workers from Binance on the cutting-edge of crypto to guard safety across many projects and systems. You will also coordinate with other teams aside from the security group, which could provide you an in-depth understanding of the crypto world.\n\nResponsibilities\n\n- Conduct security audits and reviews on smart contracts and related protocols. Also write high-quality audit reports\n- Develop/Enhance automated scanning and monitoring tools for smart contracts\n- Utilize scanning tools to detect vulnerabilities in online contracts and promptly issue risk warnings\n- Conduct root cause analysis on various hacking incidents, examining the causes, processes, prevention, correction and basic fund tracing\n- Demonstrate a good understanding of EVM chains, and be familiar with DeFi design patterns\n- Perform a review analysis on newly disclosed vulnerabilities for smart contracts and summarize the root cause behind the exploits for early detection in the future\n\nRequirements\n\n- Currently enrolled or holding a bachelor\'s degree (or higher) in Computer Science or a related field\n- Proficient in either of the programming languages, such as Solidity, Go among others which are currently engaged with the Blockchain field\n- Basic understanding of common Smart Contract security vulnerabilities, Current incidents and Simulation testing\n- Basic understanding of blockchain and smart contract principles, experienced with reading Blockchain explorers and creating scripts to track and scan data\n- Understanding of different types of solidity libraries and security associated with it\n- Familiar with smart contract development testing cycle and transaction analysis\n\nAdditional Beneficial Skills\n\n- Passionate about cryptocurrency / DeFi / smart contract / blockchain\n- Basic understanding of using VSCode, Git, or other version control applications\n- Basic knowledge of detection, exploitation, and prevention of security vulnerabilities\n- Experience in smart contracts development (e.g Foundry, HardHat, etc.)\n- Have great interest in Binance, high work enthusiasm, fit into remote working culture and responsibility, good and humble work attitude.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Contract', '2025-10-07 20:59:18.149534'),
	(1324, 682, 2, 'Kỹ Sư Phát Triển BackEnd - Java Backend Developer (Middle, Junior level) - Khối Công nghệ thông tin (HOLT.03)', 'Job Description:\n- Develop and directly program banking systems and applications, including internal systems and customer-facing applications serving 30 million individual customers and 300,000 corporate customers.\n- Develop or coordinate deployment with vendors for technology solutions.\n- Manage and develop integration services with core systems such as T24, WAY4, BPM, CRM, CIC, etc.\n- Manage and develop APIs on the API Gateway to support integration with domestic and international partners.\n- Research, test, and implement new technology trends in development, including GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL, and more.\n\nJob Requirement:\n- Graduated from university with a major in Information Technology, Computer Science, Telecommunications and Electronics, Software Engineering, Information Systems, or related fields.\n- Practical work experience in backend programming through companies or projects.\n- Proficient in at least one backend programming language, preferably Java.\n- Skilled in the Spring framework, including Spring Core, Spring Security, and Spring Boot.\n- Experienced with at least one of the following databases: Oracle, SQL Server, PostgreSQL, or MongoDB.\n- Experience in the financial or banking domain is a plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj a okolí', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1325, 790, 2, 'Web App Developer', 'Position Summary\n\nRole and Responsibilities\n\n• JOB RESPONSIBILITIES: \n• Develop and maintain web-based mobile applications for smart devices and robot.\n• Actively participate in the development process, taking responsibility for and completing assigned tasks.\n• Analyze and effectively solve problems that arise during project development.\n• Research, propose and implement solutions to improve project quality.\n• Collaborate, support team members and other departments during work.\n\nSkills And Qualifications\n\n• KNOWLEDGE, QUALIFICATION AND EXPERIENCE\n\nGeneral Requirement\n• Bachelor’s degree in computer science, Software Engineering or a related IT field.\n• At least 1 year of experience in software development.\n• Proficient in English for work purposes.\n• Strong skills in problem analysis and resolution.\n• Fast learner with a mindset geared toward quickly understanding new technologies and product modules.\n• Ability to multi-task and manage tasks with varying priorities.\n• Tech-savvy and passionate about building products.\n• Proactive at work\n\nTechnical Requirement\n(Mandatory)\n• Knowledge in Web application technical programming: JavaScript, Typescript, CSS, HTML5, …\n• Good at handling Web applications across multiple screens size.\n• Familiarity with ESLint for maintaining code quality and style.\n• Experience in using and customizing component UI frameworks such as Antd design, Tailwind - flow bite, material design.\n• Understanding of W3C standards and experience in handling W3 error compliance.\n• Experience in writing and executing unit tests for web applications (Jest, Mocha, Cypress).\n• Knowledgeable in Clean Architecture, design patterns (MVC, MVVM) and OOP.\n• Experience with distributed version control systems (Git, SVN).\n\n(Optional)\n• Proficient in using Webpack for module bundling and optimizing web applications.\n• Strong understanding of CI/CD principles.\n• Knowledge & experience of handling IoT connection: Bluetooth, Socket, MQTT, IoT server\n• Have experience of chat application (WebRTC, …)\n• Have experience of software quality & performance\n• Knowledge of image/video detection libraries (OpenCV, TensorFlow) will be highly appreciated\n• Experience in Android/IOS development (native & cross-platform) is big plus\n• Familiar with Algorithm or have high level on Coding challenge platform like Leet code, Hacker Rank is a big plus\n\nEMAIL: NGUYEN.LT@SAMSUNG.COM\n\n• Please visit Samsung membership to see Privacy Policy, which defaults according to your location. You can change Country/Language at the bottom of the page. If you are European Economic Resident, please click here.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona metropolitană Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1326, 715, 2, 'Kỹ sư chính Phát triển phần mềm (Software Engineer)', 'Nơi làm việc: Hà Nội, Tp.Hồ Chí Minh\n\nMÔ TẢ CÔNG VIỆC:\nNghiên cứu các công nghệ phát triển phần mềm liên quan đến tính toán hiệu năng cao, xử lý dữ liệu, tương tác kết nối thiết bị ngoại vi, giao diện hiển thị để áp dụng vào sản phẩm.\nĐánh giá, phân tích, lựa chọn công nghệ sử dụng phát triển hệ thống.\nThiết kế mức cao hệ thống: thiết kế sơ đồ triển khai, sơ đồ thành phần, sơ đồ phân rã chức năng ...\nThiết kế framework dùng cho phát triển các hệ thống.\nReview, phản biện các thiết kế chi tiết, thiết kế cơ sở dữ liệu, thiết kế giao thức của hệ thống.\n \nYÊU CẦU:\nTốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Toán – tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\nTrình độ tiếng Anh tương đương tối thiểu 650 điểm Toeic.\nCó tối thiểu 5 năm kinh nghiệm trở lên đảm nhận vị trí tương đương.\nCó kinh nghiệm thiết kế tổng thể trong các dự án Công nghệ thông tin.\nThành thạo phân tích thiết kế hệ thống, software design pattern.\nCó kiến thức chuyên sâu về an toàn thông tin.\nAm hiểu sâu sắc và có kinh nghiệm liên quan đến thiết kế, phát triển phần mềm trong nhiều lĩnh vực khác nhau.\n\nƯu Tiên\n\nThạc sỹ, Tiến sỹ các chuyên ngành liên quan đã có quá trình nghiên cứu tại các quốc gia phát triển trên thế giới.\nỨng viên đã có kinh nghiệm đảm nhận vị trí tương đương tại các công ty, tổ chức uy tín trong nước hoặc thế giới.\n \nCHẾ ĐỘ ĐÃI NGỘ:\nĐược hưởng các khoản quà, thưởng lễ tết, nghỉ mát hỗ trợ ăn trưa, điện thoại liên lạc tối thiểu 2.000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\nĐược hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\nĐược hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\nĐược trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\nCó cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\nĐược cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\nCó cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.\nMức lương cạnh tranh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1327, 674, 2, 'Frontend Developer', 'Mô tả công việc\n\n- Phát triển ứng dụng tài chính trên nền tảng Web/Mobile.\n- Nghiên cứu các xu hướng công nghệ và kỹ thuật mới, đặc biệt là trong ngành công nghệ tài chính.\n- Phối hợp chặt chẽ với các chức năng khác để điều tra các vấn đề và sửa lỗi.\n- Cộng tác với các thành viên khác để thu thập yêu cầu và phát triển các tính năng mới.\n- Đảm bảo chất lượng mã nguồn và nâng cao hiệu suất ứng dụng.\n- Tối ưu hoá mã nguồn, đánh giá mã nguồn và kiểm tra đơn vị theo chỉ dẫn của quản lý dự án.\n\nYêu cầu công việc\n\n- Trình độ học vấn: Tốt nghiệp Cao đẳng trở lên, chuyên ngành Khoa học máy tính, Công nghệ thông tin, Toán – Tin học.\n- Kinh nghiệm:\n  - Có ít nhất 3 năm kinh nghiệm làm việc trong lĩnh vực phần mềm.\n  - Có kinh nghiệm trong ngành Tài chính tiêu dùng, Bảo hiểm, Ngân hàng là lợi thế.\n  - Có kinh nghiệm phát triển ứng dụng Mobile (Cross-Platform) là lợi thế.\n- Kỹ năng:\n  - Sử dụng thành thạo các công nghệ/công cụ: TypeScript/JavaScript, ES6, Redux, ReactJS, Redux, Redux-Saga, Hooks.\n  - Có kiến thức về cấu trúc dữ liệu & thuật toán, OOP, quản lý bộ nhớ, mẫu thiết kế, SOLID.\n  - Sử dụng thành thạo công cụ kiểm thử: CucumberJS., Jest/Mocha/Chai/Selenium.\n  - Am hiểu phương pháp Agile (làm việc trong Scrum) sử dụng Jira/Gitlab/Trello.\n  - Lợi thế: Flutter.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Thử việc 100% mức lương;\n- Ký Hợp đồng Lao động chính thức;\n- Chế độ Bảo hiểm xã hội, Bảo hiểm thất nghiệp, Bảo hiểm y tế theo quy định Nhà nước sau 2 tháng thử việc;\n- Bảo hiểm tai nạn 24/24;\n- Khám sức khỏe định kỳ;\n- Được tham gia khóa đào tạo chuyên môn;\n- 16 ngày phép/năm;\n- Lương tháng 13, thưởng và phụ cấp tùy theo từng vị trí.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1328, 791, 2, 'Leader Fullstack Software Engineer', 'What You\'ll Do:\n\n- Lead the architecture and development of scalable backend systems using Node.js (NestJS) and/or Java (Spring Boot).\n- Drive the design and implementation of clean, responsive, and maintainable frontends using ReactJS.\n- Oversee mobile application development using React Native for both iOS and Android.\n- Architect and integrate RESTful APIs and manage databases (SQL/NoSQL).\n- Mentor junior/mid-level developers, review code, and uphold engineering best practices.\n- Coordinate with cross-functional teams (PM, QA, Design) to deliver complete product features.\n- Conduct performance optimization, debugging, and testing (unit, integration).\n- Promote continuous learning and adoption of modern frameworks, tools, and dev workflows.\n\nWhat We\'re Looking For:\n\n- 4+ years of experience in fullstack development (frontend & backend).\n\nStrong hands-on experience with:\n\n- Frontend: ReactJS, HTML, CSS, JavaScript/TypeScript.\n- Backend: Node.js (NestJS), Java (Spring Boot).\n- Experience with React Native or mobile development is a big plus.\n- Deep understanding of API design, authentication, and database management (MySQL/PostgreSQL/MongoDB).\n- Solid grasp of Git workflows, CI/CD, testing, and deployment processes\n- Strong problem-solving mindset, leadership, and team collaboration skills.\n- Ability to mentor, coach, and uplift engineering standards across the team.\n\nWhat You\'ll Gain:\n\n- Technical leadership experience across web & mobile development.\n- Exposure to global projects with Korean and international clients.\n- Opportunity to shape system architecture and influence product direction.\n- Agile team environment focused on innovation and autonomy.\n- Fast-track promotion path to Engineering Manager or Solution Architect.\n\nWhat We Offer:\n\n- Paid internship with full salary during the training period.\n- 13th-month bonus for long-term interns or full-time hires.\n- Flexible hybrid work setup (office + remote).\n- 40-hour work week, Monday–Friday.\n- Open, friendly, agile team culture with opportunities for career growth.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1329, 792, 2, 'Frontend Developer', 'Company Description\nShuffle Up is a forward-thinking online gaming B2C and B2B company delivering transformational solutions and exceptional user experiences. We pride ourselves on agility, collaboration, and a commitment to delivery. We are seeking a Frontend Developer.\n\nRole Description\nThis is a full-time remote role for a Frontend Developer. The Frontend Developer will be responsible for developing and maintaining web applications, ensuring responsive web design, and collaborating with the back-end development team. The role involves creating high-quality user interfaces, optimizing web performance, and ensuring cross-browser compatibility.\n\nQualifications\n• Strong skills in Front-End Development and Responsive Web Design\n• Experience in Web Development and Software Development\n• Ability to collaborate with Back-End Web Development teams\n• Excellent problem-solving and analytical skills\n• Familiarity with web performance optimization\n• Experience in the gaming industry is a plus\n\nWhat We Offer:\n• An energetic start up work environment.\n• Competitive salary.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1330, 432, 2, 'SENIOR FRONT-END ENGINEER (NEW ZEALAND PROJECT)', 'Senior Front-end Engineer (New Zealand Project)\n\n12025-06-30\n\nApply Now\n\nResponsibilities\n\n- Develop and maintain a secure, scalable and maintainable platform using TypeScript, React, Terraform, Cloudflare and New Relic\n- Improve and evolve our design system to create engaging, accessible and efficient user experiences\n- Support and enhance continuous deployment tooling to enable rapid and reliable software delivery\n- Work collaboratively across cross-functional teams to drive technical improvements and manage production operations\n- Provide mentorship and guidance to other engineers, fostering an inclusive and supportive team environment\n\nRequirements\n\n- Bachelor’s degree in IT or related discipline.\n- 5+ years of experience designing, developing and operating cloud-based software at scale\n- Strong communication skills (verbal and written) to collaborate effectively in a cross-functional environment\n- Ability to make data-driven decisions grounded in team goals, domain knowledge and sound engineering principles\n- Confidence in managing risk, ambiguity and dependencies in a dynamic environment\n- A growth mindset with a strong sense of ownership and accountability\n- Experience working with distributed teams in global engineering organisations\n\nWhat We Offer\n\n- Attractive salary based on your performance.\n- Annual 13th month salary.\n- Dedication bonus will be paid once a year.\n- Premium healthcare insurance, Annual health checks up.\n- Hybrid working (1-day WFH per week).\n- Breakfast are available at office in early morning and snack in late afternoon.\n- Team building allowance.\n- Annual Company team building trip.\n- Clubs (Football, Badminton, Swimming, Chess, Music band).\n- Exclusive training programs for all staff in technical, soft skills and process.\n- English class.\n- Technical clubs.\n- Marriage allowance, having newborn baby allowance, bereavement allowance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1331, 793, 2, 'Client Engineer Intern', 'Developing trusting relationships, you\'ll work with clients to shape the future of their technology landscape.\n\nAs we help you combine your technical education with consultative sales best practices, you will accelerate enterprises\' success by providing award winning solutions across Cloud, Data & AI, Security and Automation.\n\n Your primary responsibilities will include:\n * Solution-Selling: Learn and employ solution-selling techniques to identify and engage decision makers and influencers, qualify business opportunities, and respond to clients\' needs.\n * Client Management: Manage a dedicated client set and define, confirm and communicate the differentiated value of IBM\'s technology at both the technical and business level.\n * Sales Process Management: Manage the entire sales process and ensure delivery against KPIs, with a strong emphasis on new business sales, while expanding existing accounts.\n * Collaboration with IBM Ecosystem: Collaborate with the broader IBM sales ecosystem, from Marketing to Sales and technical colleagues, to IBM Business Partners, in order to build sales campaigns and incremental pipeline.\n\nRequirements:\n * Work with Hiring Manager to ID up to 5 bullets max. You can get inspired by these examples below.\n * Technical Education: Completed technical degree such as Computer Science, Engineering, Information Systems, or a related field.\n * Communication Skills: Possess excellent communication and presentation skills that are engaging, compelling and influential.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1332, 794, 2, 'Pre Post Solution Sales Engineer -Product: Access Security Control: Face Recognition/Turntile/Lift Control', '-Working location: Phu Nhuan District, HCMC \n-Salary range: Max 1400 USD + Insurance + Performance Bonus \n\n1.Qualifications & Experience\n• Minimum 3 years of experience in related role like solution consultant or Solution Engineer or Pre Post Sales Engineer..... \n• Experience in IoT or Smart Workspace or Smart Building ...........\n• Hands-on experience with physical security systems (e.g., facial recognition, turnstile/lift access)\n• Strong understanding of system design, proposal writing, and solution deployment.\n• Familiarity with RFx and tender processes.\n• Solid project management skills for overseeing deployment from planning to go-live.\n• Strong communication skills—able to explain complex concepts to both technical and non-technical stakeholders.\n• Fluent English Communication\n• Bachelor’s degree in Engineering,...\n\n2.Key Responsibilities\n•Build and maintain strong relationships with clients in Vietnam, understanding their technical needs and delivering tailored solutions.\n•Demonstrate deep understanding of physical security systems (facial recognition access, turnstiles, lift control), and related technologies.\n•RFx Tender Submission: Lead and manage RFx preparation and submission, ensuring full compliance with requirements \n•System Demonstrations: deliver engaging product and solution demos to prospective customers.\n•Technical Proposal Development: craft detailed technical proposals addressing client challenges while showcasing the value of our solutions.\n•Solution Design: design and configure solutions based on customer requirements\n•System Deployment & Project Management\n-Plan, coordinate, and execute end-to-end solution deployment for client projects.\n-Oversee installation, testing, and commissioning of systems, ensuring on-time delivery and quality outcomes.\n-Troubleshoot and resolve technical issues during deployment phases.\n\n3.Company Info: \nSolutions distributor established in Singapore, specializes in Artificial Intelligence and Internet of Things technology. Aims to be a leading-edge provider of smart workspace and digital transformation solutions by offering a wide range of products and solutions catering to the needs of different customers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1333, 366, 2, 'Backend Engineer (Kotlin/Java/Spring) - Naver Clip', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nWe are looking for Backend Engineer (Java/Kotlin/Spring)\n\nYour daily task:\n\nDeveloping and improving NAVER Clip(short-form video) Service backend system\n- NAVER Clip event / promotion service page\'s backend API\n- Management system of general Clip business for administrator\n- Supporting system of Clip influencer\'s profile home\n- Additional development tasks related to the NAVER Clip domain\n- Collaborate with a Global team (Korean)\n\nYour background:\n- Over 2 years of experience in backend system development with Java\n- In-depth understanding of HTTP-based web services and video playback on web pages\n- Experience in development using Spring and Kotlin frameworks\n- Proficient in at least one RDBMS\n- JavaScript development experience in building dynamic web applications\n- Basic backend design skills based on an understanding of MSA, RESTful, etc\n- Positive mindset and a considerate attitude towards colleagues\n- Strong communication skills in English\n\nIt\'s a big plus if you:\n- Full-stack web developer\n- Maintenance of backend systems for handling massive-traffic volumes\n- Experience with NoSQL solutions\n- Experience in data analysis based on Big Data\n- Familiar with and able to use React as a front-end library\n- Strong communication skills in Korean\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1334, 795, 2, 'Java Backend Developer', 'Our client is looking for a skilled Java Spring Boot Developer to join their team in developing and maintaining web applications. This role includes working closely with remote teams, analyzing requirements, implementing new features, and supporting the stock trading platform.\n\nResponsibilities:\n- Develop and maintain web apps using Java Spring Boot\n- Collaborate with remote teams to clarify requirements\n- Analyze, design, and implement new features\n- Fix bugs during integration, UAT, and maintenance phases\n- Write clean, maintainable, and testable code\n- Maintain up-to-date technical documentation\n- Support IT development for stock trading platforms using the Kiwoom Framework\n\nRequirements:\n- 4+ years of Java development experience\n- Proficiency in Spring & related projects, SQL, and relational DBMS\n- Experience with frontend JavaScript, HTML, and CSS\n- Familiarity with Docker, AWS/Azure, and serverless technologies\n- Understanding of API design and Agile methodologies\n- Knowledge of version control tools (Git/SVN) and issue tracking systems (e.g., Redmine)\n- Good English communication skills (written and spoken)\n- Bachelor’s degree in Computer Science or related field\n\nWhy You Should Apply – Special Offer\n- Training and education experience in Korea with Korean Finance/IT experts\n- Opportunities to work and support in IT/Finance projects overseas\n- 13th-month salary & annual performance bonus\n- Year-end MVP and Shining Star awards\n- Full SHUI per Vietnamese law\n- Premium private medical insurance (PVI) & annual health check\n- 15 days annual leave + Christmas leave\n- 30-minute monthly menstrual leave for women\n- Gifts for special occasions & a fully stocked snack corner', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1335, 796, 2, 'Java Backend', 'Responsibilities\n- Develop core modules for ViettelPost\'s next-generation logistics platform.\n- Optimize business operations, algorithms, and system architecture to improve product quality.\n- Work directly with business teams to implement products in accordance with requirements; provide feedback and consultation to enhance and streamline business processes.\n- Develop new products to serve millions of ViettelPost users.\n\nQualifications\n- Graduated from universities with majors in Information Technology, Computer Science, etc. Priority is given to candidates graduating from universities such as HUST, MTA, PTIT, VNU-UET, FPT University, or international universities.\n- Senior Level: Requires 4+ years of software development experience with JAVA programming language and experience with frameworks such as Spring, Quarkus, ZK.\n- Junior Level: Requires 2+ years of software development experience with JAVA programming language and experience with frameworks such as Spring, Quarkus, ZK.\n- Experience working with one or more of the following databases: Oracle, MariaDB, PostgreSQL, MongoDB, Redis, ElasticSearch.\n- Experience working with one or more message queue systems: Kafka, RabbitMQ, MQTT.\n- Understanding of system design, design patterns, and object-oriented programming (OOP) is an advantage.\n- Proficient in using code management tools such as SVN, GitHub.\n- Basic knowledge of deploying systems on the Linux operating system.\n- Able to work independently and in teams, and perform well under high pressure.\n- Possesses logical thinking skills and the ability to research new technologies.\n- Able to read and understand English-language technical documents.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1336, 797, 2, 'Associate Software Engineer (Fresh Graduates Welcome)', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.\n\nThe Position\nJoin our mission to build cutting-edge cybersecurity solutions! As a key Software Engineer in the Deep CDR team at OPSWAT, you will develop high-performance security products using C++ and C# (.NET Core) for both Windows and Linux. You\'ll work at the binary and structural levels of files, designing scalable back-end engines that process millions of files daily. In this role, you\'ll also contribute to automation testing with Python, ensuring product reliability. Be part of an innovative team that values deep technical expertise in data structures, algorithms, OOP, and system design while tackling real-world cybersecurity challenges.\n\nWhat You Will Be Doing\n• Design, implement, and test OPSWAT MetaDefender products built on C++ and C# (.NET Core) for both Windows and Linux environments.\n• Build and develop an automation test framework using Python to ensure product quality and reliability.\n• Interact with data, including files, documents, images, etc., at both binary and structural levels.\n• Enrich features for existing software modules (back-end engines) which process millions of files daily, ensuring high performance and scalability.\n\nWhat We Need From You\n• Bachelor\'s or higher degree in Computer Science or related fields.\n• Strong knowledge of Computer Science fundamentals, including data structures and algorithms, operating systems, and computer systems.\n• Object-Oriented mindset, with expertise in OOP (Object-Oriented Programming) and OOD (Object-Oriented Design).\n• Logical thinking, critical thinking, and problem-solving skills.\n• Proficiency in English, particularly in reading and writing.\n\nIt Would be Nice if You Had\n• Programming experience with languages such as C++, C# or Python.\n• Basic knowledge of machine learning.\n• Experience with REST API and Web.\n• Familiarity with Docker, CD/CI pipelines, Git, TeamCity, Jira, and Confluence.\n\nOPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws.\n\nRecruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1337, 783, 2, 'DevOps Engineer Intern', 'Company Description\n\nKMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines:\n\n1. KMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions.\n2. KMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality.\n3. KMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors.\n\nJob Description\n\nThe Brilliant Career You Love \n\nAre you passionate about innovative software development and eager to sharpen your expertise every day?\n\nDo you dream of being part of a Great Team that creates awesome billion-dollar Software Products for U.S clients?\n\nWould you love to work in one of the Best Places to Work in Vietnam, a Top 10 ITC Company in Vietnam that invests in people development?\n\nIf your answer is yes, we firmly believe that you will enjoy every single working day at KMS Healthcare.\n\nThis vacancy is an ideal opportunity for beginners who want to start their career on a high note. As one of our Software Engineer Interns, you will have the chance to acquire one of the hottest skills in the industry. You will receive training and work on complex systems using cutting-edge technology-based frameworks. Additionally, you will collaborate with talented developers, following high standard software development practices and CI/CD processes.\n\nAs an intern at KMS Healthcare, you will have the opportunity to learn and practice a wide range of skills, including but not limited to:\n\n1. Working under the guidance of technical leaders or senior developers\n2. Practicing coding with a focus on high quality and effective outputs\n3. Participating in all software development activities\n4. Clarifying requirements with clients and the team\n5. Writing high-quality code to implement software features or fix bugs, and implementing unit tests\n6. Reporting project status to clients and the team\n\nQualifications\n\n1. Currently pursuing a degree in Computer Science/ Software Engineering/ Telecom & Networking or related field with an IT background\n2. At least 4 working days per week in 3-6 months of internship; with possible conversion to permanent staff after internship are preferred\n3. Good knowledge of one or more modern DevOps technologies, including Linux fundamentals and scripting, knowledge on various DevOps tools & technologies (source controls, configuration management, continuous testing, continuous monitoring, containerization, cloud), CI/CD, infrastructure as code, etc.\n4. Good verbal and written communication skills in English\n5. Strong problem-solving and analytical skills\n6. Collaborative mindset and ability to work well in teams\n7. Curiosity and eagerness to learn emerging technologies\n8. Attention to detail and commitment to high-quality work\n9. Proactive and self-motivated with good time management\n\nTo help us have a good understanding about your competencies & your dream job to match with future suitable KMSH opportunities, we look forward to receiving your academic transcript & the latest CV mentioning your desired position.\n\nAdditional Information\n\n1. Working in one of the Best Places to Work in Vietnam, Top 10 ITC Company in Vietnam\n2. Flexible working model: Flexible time & Hybrid working from Ho Chi Minh or Da Nang city\n3. Attractive Allowance with possible conversion to permanent staff after internship are preferred\n4. Diverse careers opportunities with Software Services, Software Product Development\n5. Working and growing in a values-driven, international working environment and standard Agile culture with passionate and talented teams\n6. Various training on hot-trend technologies, best practices and soft skills\n7. Company trip, big annual year-end party every year, team building, etc.\n8. Fitness & sports activities: football, tennis, table tennis, badminton, yoga, swimming…\n9. Joining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,…\n10. Free in-house entertainment facilities (football, ping pong, gym…), coffee, and snacks (instant noodles, cookies, candies…)\n\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1338, 755, 2, 'Junior/Mid Fullstack Engineer (TypeScript/JavaScript) - Hybrid working model 100%, Ho Chi Minh City', 'Company Description\n\nWelcome to SMG Vietnam!\n\nSMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nJob Description\n\nThis job refers to our Real Estate brands, Homegate and Immoscout24, the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing.\n\nWe are looking for a Junior/Mid Fullstack Engineer to help us build the future of the Swiss real estate market by contributing to our cutting edge, cloud based, technology stack. You will get to collaborate and access the wealth of knowledge and experience from a community of amazing engineers who come from all parts of the globe and are ready to share their expertise and aid you in your path to fulfilling your potential.\n\nJoin our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nOur tech stack\n\nFrontend: Vue.js with TypeScript\nBackend: Node.js and TypeScript, following a serverless microservices architecture in an AWS cloud environment (Lambda, DynamoDB, SQS, SNS, S3, etc.)\nMonitoring: Datadog\nDocumentation: Backstage\n\nLearn more about us and our engineering practices in our blog at https://medium.com/smg-real-estate\n\nYour Mission :\n\nBuilding and experimenting: Writing clean, modular code within a modern, serverless architecture, with a focus on refining and experimenting with functionality.\nCollaborating and creating: Working closely with a talented team of engineers to design, develop, and deliver features that make a real impact on users.\nLearning and applying: Gaining hands-on experience with AWS Serverless, CI/CD, and other cutting-edge tools like AI/Datalake, continuously enhancing skills along the way.\nContributing to innovation: Bringing fresh ideas to improve both software and processes, always looking for opportunities to push boundaries.\nYour responsibilities will evolve as we grow.\n\nQualifications\n\nWhat will you bring to the ride?\n\nFluent in English, both written and spoken.\nBachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience.\n1+ years of experience in Software Development.\nExperience with TypeScript/JavaScript, with proficiency in at least one of the following:\nComfortable with Vue.js or React.js, and capable of building modern web applications.\nExperience with Node.js backend development, including implementing synchronous and asynchronous services.\nSome exposure to AWS services and a Serverless Technology Stack.\nStrong sense of ownership and responsibility for what the team builds. Before blindly adding code to a codebase, be able to identify problematic areas and refactor them with maintainability and stability in mind.\nCurious, open-minded, and enthusiastic about growing in a collaborative team environment.\nAbility to use AI tools to assist with coding is a plus.\nWe value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique.\n\nAdditional Information\n\nWhat do we offer?\n\nCompetitive Benefits: Attractive salary, full pay during probation, 13th-month bonus, and full social insurance contributions.\nGenerous Leave: 21+ annual paid days off, 24 days for learning & sharing, and flexible working hours with no overtime.\nHealth & Wellness: Premium private insurance for you and your family, free food, and access to various classes and clubs.\nGrowth Opportunities: Personalized development plans, yearly education budgets, regular Hackathons, and potential travel to Switzerland and Europe.\nModern Work Environment: Hybrid model, top-tier equipment, and a friendly, agile, and transparent culture.\nSupportive Onboarding: Comprehensive assistance to help you settle in.\n\nRecruitment Process \n\nWe believe hiring is a two-way street, where both parties get to know each other. Here\'s what you can expect:\n\nInitial screening call with HR – A brief conversation to understand your background and expectations.\nMeeting with the Hiring Manager – A deeper discussion about the role, your experience, and how we work.\nTechnical Assessment – A hands-on assessment of your skills, conducted via live coding and system design exercises.\nCasual Meeting with Director – An informal conversation to align on vision, culture, and goals.\n\nAt SMG Vietnam, we value diverse perspectives and individual growth. We welcome candidates from all backgrounds and encourage you to apply, even if you don’t meet every requirement. Together, we embrace differences, nurture potential, and celebrate success.\n\nApply now\n\nTo take this opportunity, send us your detailed CV and feel free to add any supporting documents we need to look at in order to understand that you are the perfect fit.\n\nAbout Us\n\nSMG Swiss Marketplace Group AG. is a pioneering network of online marketplaces and cutting-edge European digital company that simplifies people’s lives with innovative products.\n\nSMG Swiss Marketplace Group AG. provides customers the best tools to meet their life decision needs. The portfolio includes Real Estate (ImmoScout24, Homegate, Flatfox, alle-immobilien.ch, Immostreet.ch, home.ch, Publimmo, Acheter-Louer.ch, CASASOFT, IAZI), Automotive (AutoScout24, MotoScout24), General Marketplaces (anibis.ch, tutti.ch, Ricardo) and Finance & Insurance (FinanceScout24, moneyland.ch).\n\nThe company was founded in November 2021 by TX Group AG, Ringier AG, La Mobilière and General Atlantic.\n\nDisclaimer\n\nSMG Swiss Marketplace Group AG primarily engages directly with candidates. We do not accept unsolicited resumes or candidate profiles from recruitment agencies unless we have specifically requested their assistance for particular roles. Any submissions made without a prior request from our Talent Acquisition team will not be acknowledged or considered. We appreciate the understanding and cooperation of recruitment agencies in respecting this policy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Củ Chi district, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1339, 798, 2, 'Full Stack Developer', 'VIETSWISS — A Great Land for Talents\n\nWE ARE HIRING: FULL-STACK DEVELOPER (No Fresher, English is a must)\n\nAre you a passionate Fullstack Developer looking for a place where your ideas matter, your growth is supported, and your work has real impact?\nWith 6 years of solid development in Vietnam and a strong, stable client base, VIETSWISS continues to grow, innovate, and create meaningful work that connects across borders.\n\nWhy VIETSWISS?\n- Stability: Long-term projects with loyal clients from Europe, no bench time, no sudden pivots.\n- Global Collaboration: Work side-by-side (and screen-to-screen!) with our Swiss team, who are talented, supportive, and share the same passion for clean code and clever solutions.\n- Growth Opportunities: We\'re still growing fast — and so can you. Your career path is yours to shape here.\n- People-first Culture: A team that works hard, laughs often, and values trust, creativity, and connection.\n\nLocation: Onsite at our cozy office in Thao Dien, District 2, Ho Chi Minh City\n\nCheck out the job description: https://bit.ly/3FiZ47B\n\nCome be part of a workplace where your skills shine and your potential is limitless.\n\nDo not hesitate to send your CV/portfolio to hoatran@vietswiss.com\nVisit these links below to know more about us\n- Website: vietswiss.com\n- LinkedIn: Our Company Page\n- We can’t wait to hear from you!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1340, 713, 2, 'Frontend Engineer', 'Description\n\nResponsibilities and Duties\n\nOnce You Join Our Team, You Will\n\n- Collaborate with other team members (PM, UI, backend engineer, QA) to provide a seamless freight experience for our customer;\n- Participating design the front end architecture, collaborate with backend engineers to develop and deliver elegant product solutions;\n- Propose innovative technical solutions to hard business problems;\n- Curiosity and passion, understanding of LLM and AI Agent framework;\n- Lean and grow constantly, improve yourself and make the team member around you better\n\nRequirements\n\nMinimum Qualifications\n\n- Bachelor degree in Computer science or related field;\n- At least 3+ years of working experience in related field;\n- Fluent in JavaScript, CSS, HTML;\n- Fluent in Vue frameworks, MVC, MVVM architecture\n- Experience with at least one modern JavaScript framework (React, Vue )\n- Fluent in REST APIs in web context, GraphQL experience is plus\n- Good engineering habits with maintaining codebase, familiarity with Git, Webpack;\n- Clear understanding of division between front end and back end;\n- Build products that delight the user, paying close attention to detail of UI elements;\n- Sensitivity to front-end architecture and components, preferably with experience working on large scale engineering projects;\n- A commitment and drive for quality, excellence and results balanced with a creative mindset;\n- Raise the quality and speed bar of the entire team and yourself into a position of maximum leverage;\n- be familiar with AWS and amplify is a plus\n- Good communication skills, with fluent verbal English.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Distrito 3, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1341, 799, 2, 'Software Engineer', 'Java, Python', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thanh Xuan Bac Ward, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1342, 800, 2, 'Senior Full-stack Developer, Zvideo (Focus FE)', 'Zalo Short Video is a newly updated feature on the Zalo application that allows users to create, watch, and share videos shot on mobile devices.\n\n🤖 What you will do\n\n- Participates in design, development, implementation of Zalo;\n- Develop high-volume, low-latency applications, delivering high-availability and performance;\n- May provide technical solutions and system architecture;\n- Program and optimize to ensure the best performance, quality and responsiveness of the applications;\n- Define site objectives by analyzing user requirements, envisioning system features and functionality;\n- Prepare and produce releases of software components;\n- Continuous improvement by researching new alternatives and technologies and presenting these for architectural review;\n\n👾 What you will need\n\n- At least 4 years of experience as a Full-stack Developer or similar role;\n- Proficiency in frontend technologies such as HTML, CSS, JavaScript, and frameworks like React JS, Next JS (60%);\n- Strong backend experience with Java (40%);\n- Experienced in SQL and NoSQL, good understanding how to optimize database in a large system;\n- Excellent of object-oriented programming, data structures and algorithms;\n- Excellent of Linux operating system, Web and network protocols such as: UDP/TCP, Get/Post, Session/Cookie, HTTP/HTTPS ...;\n- Good at problem-solving skills and creative under high pressure;\n- Young, active and willing to learn new technologies;\n- High responsibility, young, active, good at individual and team work;\n- Be able to read and understand English documents.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1343, 801, 2, 'Frontend Engineer', 'Fully Onsite Position*\n\n- Collaborate with other team members (PM, UI, backend engineer, QA) to provide a seamless freight experience for our customer;\n- Participating design the front end architecture, collaborate with backend engineers to develop and deliver elegant product solutions;\n- Propose innovative technical solutions to hard business problems;\n- Curiosity and passion, understanding of LLM and AI Agent framework;\n- Lean and grow constantly, improve yourself and make the team member around you better\n\nRequirements\n\n- Familiarity with the development process and work patterns of internet products.\n- Fluent in frontend technologies, including HTML, CSS, JavaScript, and TypeScript.\n- Fluent in React, with practical experience in developing complete React projects.\n- Solid experience with common frontend frameworks, libraries, and tools such as Webpack, Babel, Vite, Turbo, Lerna, Next.js, React, and Vue.\n- Understanding and familiarity with Node.js, capable of project building, with some backend development experience in Node.js.\n- Proficiency in TypeScript; practical experience with TypeScript projects is a plus.\n- Familiarity with commonly used frontend state management tools, such as Redux, MobX, Observable, React Hooks, Zustand, and Recoil.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1344, 197, 2, 'Backend Engineer (Python) - AGI', 'We are looking for Software Engineers to join our cutting-edge Artificial General Intelligence (AGI) project. If you are passionate about AGI, have a strong background in Python (Go, Java,...) and excel at problem-solving, critical thinking, and self-learning, we invite you to apply for this exciting opportunity.\n\nResponsibilities\n\n- Collaborate with engineering teams to design, develop, and deploy business critical solutions.\n- Stay continuously informed about the latest advancements and trends in the AGI field.\n- Write clean, maintainable, and efficient code to implement new features and functionalities.\n- Research and adopt new techniques and methodologies to solve complex problems, utilizing critical thinking and analytical skills.\n- Proactively identify and address complex issues related to task management, load balancing, and system scalability.\n- Share knowledge through peer-to-peer collaboration, conduct code reviews, provide technical guidance, and mentor junior team members as needed.\n\nRequirements\n\n- Bachelor’s degree or higher in Computer Science, Engineering, or a related field.\n- Over 3 years of experience in software engineering.\n- Proficiency in backend development in an object oriented language. Proficiency in either Python, Golang, Node.js or C# and the willingness to learn another.\n- Familiarity with distributed task management systems and job queues like Celery, Faktory, BullMQ or others.\n- Experience in full-stack engineering is highly desirable and willingness to work with tools like HTMX, jQuery or React.\n- Good understanding of relational databases, locks, indexes and transactions. Strong SQL skills.\n- Demonstrated ability to quickly learn and adapt to new technologies and programming languages.\n- Excellent problem-solving skills, with a strong understanding of algorithms and data structures.\n- Familiarity with best practices in the software development life cycle, including version control, code reviews, and testing frameworks.\n- Ability to work effectively both independently and collaboratively within a team environment.\n- Familiarity with writing unit tests.\n\nIf you believe you have what it takes to excel in this role and contribute to the development of AGI solutions, please submit your resume and any relevant code samples or project links. We look forward to reviewing your application and exploring the possibility of welcoming you to our team.\n\nWhat We Offer\n\nJoin our team and enjoy:\n\n- Competitive compensation package, including 13th-month salary and performance bonuses\n- Comprehensive health care coverage for you and your dependents\n- Generous leave policies, including annual leave, sick leave, and flexible work hours\n- Convenient central district 1 office location, next to a future metro station\n- Onsite lunch with multiple options, including vegetarian\n- Grab for work allowance and fully equipped workstations\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets\n\nAbout Us\n\nWe are an AI Fintech company specializing in assessing credit profiles of consumers in emerging markets combining pioneering AI with large alternative data sources. In 2020 we reached our ambitious milestone of credit profiling 1 billion consumers spanning 4 countries - Vietnam, Indonesia, India & the Philippines - and building a platform for the wider industry and the financial services industry, in particular, to provide the "un & under" served access to credit. At the core of this initiative has been our strict and unwavering adherence to the norms of consumer data privacy and consumer data rights.\n\nBut we\'re not satisfied as we embark on the next leg of our journey to deliver 100 million credit lines to consumers in the markets where we operate. Although this goal is ambitious, we truly believe that by harnessing the power of AI & Big Data we can deliver financial access at an unprecedented scale.\n\nAs a firm, we\'re audacious problem-solvers motivated by our impact on society. We deeply espouse the values of ownership - of our actions and initiatives, integrity in all we do, and agility in execution.\n\nWe place great importance on doing what is right, what is best, and what is innovative. If you are smart, driven, and want to make a difference in the world with the most advanced and fascinating technology, come join our team. We can satisfy your desire to explore new territory and give you the runway to really make an impact.\n\nAdditional Info\n\nLearn more about us here:\n\nhttps://www.youtube.com/watch?v=inAEDGvOcL8&t=29s', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1345, 802, 2, 'IT Developer', 'MÔ TẢ CÔNG VIỆC:\n- Tham gia phát triển và tối ưu hệ thống ERP nội bộ.\n- Phối hợp chặt chẽ với Business Analyst (BA) để phân tích yêu cầu, làm rõ nghiệp vụ và đề xuất giải pháp kỹ thuật phù hợp.\n- Tích hợp hệ thống với các đối tác bên ngoài như đơn vị vận chuyển, cổng thanh toán và nhà cung cấp kho bãi.\n- Phát triển các công cụ hỗ trợ hoạt động bán lẻ và mở rộng kinh doanh.\n- Đảm bảo hệ thống hoạt động ổn định, liên tục 24/7.\n- Tham gia vào quá trình chuyển đổi hệ thống từ MongoDB sang SQL Server.\nYÊU CẦU CÔNG VIỆC:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin\n- Tối thiểu 3 năm kinh nghiệm phát triển với NestJS.\n- Tối thiểu 3 năm kinh nghiệm với Angular trong phát triển frontend.\n- Có kinh nghiệm làm việc với cơ sở dữ liệu như MongoDB, SQL Server hoặc các hệ quản trị CSDL tương đương.\n- Khả năng phân tích nghiệp vụ, tư duy logic và giải quyết vấn đề tốt.\n- Kỹ năng làm việc nhóm tốt, đặc biệt trong việc phối hợp với BA và các bên liên quan để đảm bảo sản phẩm đúng yêu cầu và tiến độ.\n- Có kinh nghiệm kiểm thử, đảm bảo chất lượng phần mềm.\n- Ưu tiên ứng viên từng làm việc với MongoDB hoặc có kinh nghiệm chuyển đổi hệ thống từ NoSQL sang RDBMS.\n- Kinh nghiệm làm việc với AWS là một lợi thế.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Région métropolitaine de Hanoï', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1346, 803, 2, 'Java Backend/Fullstack-OS', 'SALARY RANGE : 17 - 28M Gross\nResponsibilities: (Fintech/Bank Project)\n- Writing clean & high-quality code\n- Maintain & improve running- functionality as well as design and develop new system, new feature if needed\n- Deliver end-to-end, including unit test, integration test and deployment to PROD\n- Participate in code reviews & control coding quality standards\n\nQualifications:\n- Minimum 2 years of hands-on development experience in Java (Spring Boot framework)\n- Good understanding of Data Structures and Algorithms\n- Expertise in SQL/ NoSQL Databases (MySQL, PostgreSQL, MongoDB)\n- Experience with RESTful APIs, Microservices\n- Familiarity with Redis, Kafka\n- Experience in high-performance, low-latency systems, handling large-scale data processing and real-time transactions\n- Experience with Docker/Kubernetes and Cloud Infrastructure is a plus\n- Experience with Agile or Scrum software development methodologies\n- Familiarity with the financial, banking, or payment gateway domain, including compliance and security best practices is a plus\nCách thức ứng tuyển\n- Trực tiếp qua tin nhắn HR\n- E-mail: recruitment4@ttc-solutions.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1347, 702, 2, 'Software Engineer ( Python + Java)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nWe are looking for a talented Java & Python Developer (Mid to Senior) to join our team. The successful candidate will join a greenfield project. The daily work content includes but doesn\'t limit to: Join the full life cycle of software development, including requirement gathering, designing, coding, testing and deployment.\n\nResponsibilities\n\n- Responsible for the architecture design, technology selection and overall implementation scheme formulation of the core back-end system\n- Lead the system design, code development and optimization to ensure the high availability, high performance and scalability of the system\n- Develop high-quality server-side applications and tools based on Java and Python\n- Deeply participate in the design and development of the company\'s large model related projects, and promote the application of AI capabilities in the business\n- Continue to learn and pay attention to AI Agent open source projects on GitHub (such as Auto-GPT, AgentGPT, LangGraph, etc.), and actively explore their application potential in actual business scenarios\n- Work closely with product, front-end and algorithm teams to promote high-quality and efficient project delivery\n- Guide and lead middle and junior development engineers to grow and improve the overall technical level of the team\n\nRequirements\n\n- Bachelor degree or above in computer related field, more than 8 years experience in back-end development;\n- Proficient in Java programming language and familiar with common back-end development frameworks (such as Spring Boot and Spring Cloud)\n- Proficient in Python, with cross-language development ability and practical project experience\n- Have project experience in large language model (LLM), familiar with its architecture principle, reasoning process and deployment practice\n- Familiar with distributed system, microservice architecture, message queue, cache, database and other back-end infrastructure\n- Have the ability to independently design system architecture and develop technical solutions, with good engineering thinking and code quality awareness\n- Pay close attention to the open source AI community, and have the habit of actively learning, researching and trying new technologies\n- Good communication skills, teamwork skills and project promotion ability\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1348, 804, 2, 'Python Microservices Engineer', 'What You’ll Do:\nWrite and debug Python-based microservices.\nIntegrate microservices with Kafka and connect them to PostgreSQL or similar databases.\nLink connections between microservices and databases in both development and production environments.\nIntegrate backend endpoints with Flutter and HTML/JavaScript frontends.\nDeploy services on servers and within Docker containers.\n\nMust-Have Skills:\nStrong experience with Python and the ability to write clean, efficient code quickly.\nSolid understanding of microservices architecture, including building and integration.\nEngineering mindset and troubleshooting skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1349, 674, 2, 'FULL STACK REACT DEVELOPER', 'Mô tả công việc\n\n- Phát triển, tối ưu giao diện web thương mại điện tử bằng ReactJS, Next.js.\n- Xây dựng hệ thống backend với Node.js, Express/NestJS, tích hợp API thanh toán, giỏ hàng, quản lý đơn hàng.\n- Thiết kế, tối ưu cơ sở dữ liệu (MongoDB, PostgreSQL, MySQL) đảm bảo hiệu suất cao.\n- Tích hợp các dịch vụ third-party (cổng thanh toán, vận chuyển, chatbot, AI/ML recommendation).\n- Cải thiện tốc độ tải trang, tối ưu SEO, đảm bảo trải nghiệm người dùng mượt mà.\n- Phối hợp với team UI/UX, Product Manager để phát triển tính năng mới.\n- Đảm bảo bảo mật hệ thống, xử lý lỗi, nâng cao tính ổn định.\n- Nghiên cứu công nghệ mới, đề xuất giải pháp nâng cấp hệ thống.\n\nYêu cầu công việc\n\n- Tối thiểu 3 năm kinh nghiệm phát triển web với ReactJS & NodeJS.\n- Thành thạo JavaScript, TypeScript, HTML, CSS (Tailwind/SCSS).\n- Có kinh nghiệm làm việc với RESTful API, GraphQL, WebSocket.\n- Hiểu về Microservices Architecture, Redis, Kafka là lợi thế.\n- Kinh nghiệm với AWS, GCP, Firebase, Docker, CI/CD là điểm cộng.\n- Tiếng Anh đọc hiểu tốt, có thể giao tiếp trong công việc.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Lương: Thỏa thuận theo năng lực + thưởng theo kết quả kinh doanh.\n- Lương T13, T14, tăng lương hàng năm theo năng lực.\n- Môi trường làm việc năng động trong ngành TMĐT toàn cầu.\n- Làm việc hybrid/remote linh hoạt.\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định.\n- Du lịch 2 lần/năm, quà/thưởng lễ tết.\n\nCách Thức Ứng Tuyển\n\nGửi CV + Bảng điểm (scan/ảnh file pdf, jpeg, png) về email career@makezbright.com hoặc liên hệ Zalo: 0942 485 129 (Vy PSA).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1350, 366, 2, 'Backend Engineer (Java)', 'About NAVER Corp and NAVER Vietnam:\nNAVER Corp\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\nNAVER Vietnam\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\nLearn more about us: https://navercorp.vn/\nWe are looking for Backend Engineer (Java).\nYour daily task:\n- Develop Java Backend part of various NAVER Services like Weverse, Security, VIBE, Commerce, Blog, NAVER Cloud etc.\n- Participating in code reviews and architecture design\n- Proactive, can-do attitude and strong commitment\nYour background:\n- Bachelor\'s degree in Computer Science or related technical field\n- 3+ years of work experience on Backend systems with Java applications to serve large-scale and high traffic projects\n- Have 2+ years of experience in Java Spring-Framework\n- Experience in a leadership role will be a big plus\n- Experience or strong knowledge of MSA and k8s\n- Experience or strong knowledge one of databases: PostgreSQL, MySQL, Oracle, MongoDB\n- Understanding & experience in Data structure, Algorithm, Distributed Service, OOP\n- Open-minded, honest and have a positive attitude towards people\n- Good at communication skills in general and English skills in particular\nIt\'s a big plus if you:\n- Have experience in DevOps\n- Have experience in Message Queue like Kafka\n- Have experience in ELK-stack\n- Have experience in Server Architecture Design for handling massive traffic\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Ho-Chi-Minh-Stadt', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1351, 789, 2, 'Lập trình viên IT', 'Mô tả công việc\n\n- Giới thiệu chung về vị trí:\n\nLập trình viên trong viễn thông chính là những người thổi hồn vào các dịch vụ giá trị gia tăng trên di động. Người lập trình sử dụng công cụ là các ngôn ngữ lập trình cơ bản như JavaScript, C, Sql, … để xây dựng nên những sản phầm dịch vụ hoàn thiện, đáp ứng nhu cầu ngày càng cao của khách hàng\n\n- Mô tả công việc:\n- Phân tích thiết kế hệ thống\n- Lập trình các giải pháp thông tin cho người sử dụng bằng cách phát triển, triển khai, và bảo trì các phần mềm\n- Triển khai các dự án công nghệ thông tin: khảo sát, lắp đặt, cấu hình, nghiệm thu\n- Hỗ trợ kỹ thuật, ứng cứu, xử lý các sự cố\n- Lập tài liệu xây dựng hệ thống và tài liệu hướng dẫn người sử dụng\n- Nghiên cứu sử dụng các giải pháp phần mềm phục vụ cho việc kinh doanh, quản lý\n\n- Yêu cầu:\n- Là SV tốt nghiệp chuyên ngành CNTT của các trường ĐH, CĐ trên cả nước. Khuyến khích SV mới ra trường\n- Không yêu cầu kinh nghiệm\n- Thành thạo một hoặc một số các ngôn ngữ lập trình như Java, JavaScript, Python, SQL (Vì Công ty mình làm chủ yếu bên Viễn thông nên Code rất đơn giản)\n- Hiểu biết tốt về jQuery, Nodejs\n- Công ty sẽ training trước khi vào dự án.\n- Có đam mê khám phá kỹ thuật, yêu thích lĩnh vực lập trình.\n\n- Chế độ:\n- Mức thu nhập thỏa đáng theo năng lực làm việc\n- Thử việc 2 tuần – 1 tháng: Lương cứng 6tr/tháng\n- % DT\n- trợ cấp\n- Ký hợp đồng sau thử việc: 8tr-10tr/tháng\n- % DT\n- trợ cấp\n- Được đóng đầy đủ BHXH, BHYT, BHTN chế độ nghỉ lễ, nghỉ phép theo luật lao động\n- Được đào tạo và làm việc trong môi trường chuyên nghiệp, có cơ hội thăng tiến.\n- Các hoạt động giao lưu văn hóa tinh thần, quan tâm, hỗ trợ của Công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1352, 805, 2, 'Java Software Engineer', 'Onsite tại văn phòng của khách hàng là Ngân hàng tại Hà Nội\n\n1. Mô tả công việc \n- Thiết kế cấu trúc ứng dụng\n- Lập trình, phát triển các ứng dụng của Ngân hàng\n- Thiết kế cơ sở dữ liệu ứng dụng\n- Thiết kế và triển khai API\n- Nghiên cứu, thử nghiệm, triển khai áp dụng các xu hướng công nghệ mới vào việc phát triển\n\n2. Yêu cầu kỹ năng (Requirements):\n- Có nhiều kinh nghiệm về Java và Spring Boot framework\n- 4+ năm kinh nghiệm về Java, ưu tiên có kinh nghiệm domain ngân hàng, tài chính\n- Có kinh nghiệm với client-side framework\n- Có kinh nghiệm làm việc với DB (SQL và NoSQL)\n- Có kinh nghiệm về Microservice, từng làm việc với AWS/OCP/K8S\n- Có kinh nghiệm triển khai REST API\n\nƯu tiên ứng viên:\n- Có kinh nghiệm quản lý dự án, làm việc theo phương pháp Agile\n- Có kiến thức tổng quan về ngân hàng và am hiểu sâu nghiệp vụ ngân hàng\n- Có hiểu biết/kinh nghiệm thực tế về các nghiệp vụ ngân hàng\n\n3 . Quyền lợi:\n- Toàn thời gian từ Thứ Hai đến Thứ Sáu, với các khung thời gian linh hoạt (8h-18h, 8h30-18h30, 9h-19h).\n- Bảo hiểm theo quy định và bảo hiểm premium health care\n- Du lịch hàng năm\n- Đánh giá tăng lương 2 lần/năm\n- Lương: up to 45 triệu gross/tháng + thưởng tháng 13 và thưởng KPI', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1353, 737, 2, 'Full Stack Developer (.NET, ReactJS)', 'Join Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia\'s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nWe are looking for a talented and motivated Full Stack Developer (.NET ReactJS) to join our dynamic team. As a Full Stack Developer, you will work on developing and maintaining web applications using .NET, SQL Server, and React. You will collaborate with cross-functional teams to deliver high-quality software solutions that meet our clients\' needs.\n\nCore Responsibilities\nDevelop and maintain web applications using .NET, React, and SQL Server.\nEnsure the quality and performance of applications through testing and code reviews.\nFollow best practices for software development, including coding standards, code reviews, and version control using Azure DevOps.\nWork within the SAFe Agile framework to deliver projects on time and within scope.\n\nFunctional Responsibilities\nParticipate in all phases of the software development lifecycle, including requirements gathering, design, coding, testing, and deployment.\nCollaborate with cross-functional teams to define and implement new features.\nAssist in continuous integration and continuous deployment (CI/CD) processes using Azure DevOps.\n\nTechnical Skills\nExcellent English communication\nProficiency in .NET, React, and SQL Server.\nStrong understanding of web development principles and best practices.\nExperience with Azure DevOps for version control and CI/CD processes.\nFamiliarity with the SAFe Agile methodology.\nExcellent problem-solving skills and attention to detail.\n\nThings that will separate you from the rest\nExperience with Node.js\nExperience with other front-end frameworks/libraries such as Vue.js Angular\nKnowledge of cloud services and infrastructure, especially Azure.\nExperience with RESTful API design and development.\nUnderstanding microservices and event driven architecture.\n\nEducation or Certifications\nBachelor\'s degree in Computer Science, Information Technology, or related field. \n\nJob Type\nFull-Time\n\nSchedule\nMonday to Friday\n\nWork Location \nThe Six8 Building, 24-26 Phan Dinh Giot, 2 Ward, Tan Binh District, Ho Chi Minh City.\n\nBenefits\nHealth insurance\nDental insurance\nPaid time off\nParental leave\nChildcare assistance\n\nThis job description is not intended to be all-inclusive. An employee may also perform other reasonable related business duties as assigned by their immediate supervisor or management.\n\nPrincipals only. Recruiters please don\'t contact this job poster. DO NOT contact us with unsolicited services or offers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1354, 806, 2, 'Odoo/Python developers', 'Company Description\nOperating globally from Ho Chi Minh City since 2009, we are currently the biggest Odoo integrator in Vietnam. Our specificity lies in the ability to manage large sophisticated Odoo-based business solutions with a high level of quality.\n\nRole Description\n- Understand the requirements provided by the business analysts\n- Provide workload estimates for the activities on the project\n- Choose the technical design for the implementation\n- Code following the coding guidelines and best practices\n- Ensure the correctness of the implementation before transmitting to the QC team\n- Work closely with the business analysts to ensure that the implementation fits the business need\n- Work closely with the technical lead to get advice for the implementation\n- Work closely with the project managers to define the content of each iteration and the planning of the deliveries\n- Work closely with the QC team to fix the bugs detected during the testing phases\n\nYour Skills & Experiences\n- Have more than 3 years experience with Odoo\n- Must have a degree in information technology\n- Must be familiar with web technologies\n- Must be familiar with object-oriented programming\n- Must be focused on quality, efficiency and continuous improvement\n- Must be able to read and write in English\n\nNice to have\n- Knowledge of Python and/or Odoo is a big plus (but not mandatory, Python is easy to learn, and we provide training to Odoo)\n- Experience in software development is a big plus (but not mandatory, talented and motivated beginners are welcome)\n- Involvement in open-source projects and/or interest for the open-source movement is a plus\n- Good oral communication skills in English and/or French is a plus\n- Knowledge of modern development methodologies and tools (agile methodologies, automatic testing, continuous integration, distributed version control systems, wikis, trac, jira,…) is a plus\n- Understanding of the processes of a company (sales, purchases, stock management, accounting, human resources,…) is a plus\n\nBenefit\n- A very attractive salary, including 13-month salary\n- Annual salary review\n- Premium healthcare insurance individual and family members\n- Loyal Employee Program for Trobzers\n- 17 days paid time off & work from home\n- Monthly IT bonus\n- Clear career path and personal development plan, with various training opportunities.\n- Annual company trip & health check-up\n- A fun working environment with free in-house entertainment facilities (PS4, pantry, coffee...) and fitness & sports activities, such as football, badminton…\n\n𝐅𝐔𝐋𝐋 𝐉𝐎𝐁 𝐃𝐄𝐒𝐂𝐑𝐈𝐏𝐓𝐈𝐎𝐍: https://trobz.com/jobs/detail/odoo-python-developers-2\n𝐇𝐎𝐖 𝐓𝐎 𝐀𝐏𝐏𝐋𝐘:\nSend your CV to job@trobz.com\nEmail subject: Application for Odoo TC - [Your Full Name]', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'An Phú, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1355, 376, 2, 'Software Developers', 'Company Description\n\nNetcompany is one of Northern Europe’s most successful IT Companies with headquarter located in Denmark and other 17 offices around the world. Netcompany Viet Nam is the only office in Asia. Globally Netcompany employs 8260+ of the most skilled IT Consultants and Developers.\n\nOur Projects come from Europe \n\nYou will get the chance to work on different programming languages and technologies as this will vary from project to project. A large part of our projects uses technologies like AngularJS, gulp, Sass, React and node.js on Java and .NET. Besides that, we work with SharePoint, Microsoft Dynamics CRM, Salesforce, Microsoft SQL-server, Sitecore, Oracle and Weblogic to name just a few. \n\nWe are looking for ambitious candidates to join us on a permanent basis to drive forward our delivery capability and deliver the optimal solutions to our clients in Europe. You will join our strong and dedicated team based in Ho Chi Minh City, where you will have the opportunity to work with some of the most skilled consultants in Vietnam and our technically skilled employees in Europe.\n\nWhy you should join us \n\nInternational professional working environment\nOpportunities to join training courses in Europe\nClear career path with strong academy system. In Netcompany we focus on improving your skills with our career development program and model, which are essential to make sure that all our software developers keep improving continuously. Once you join us, you are automatically enrolled in our Netcompany Academy and mentoring program, where we focus on different areas ranging from developing technical skills to more personal skills  \nKeep up with the latest technology trends. As our new senior/graduate, you will work with a lot of different and exciting solutions and technologies. You’ll be working on some of the largest, most complex and technically innovative IT programmes and projects for some of the most prestigious organizations in the world\nAs an employee in Netcompany you will also benefit from our large and global knowledge-based communities, Centers of Excellence. This covers a wide range of different knowledge groups, from specific technologies like .NET and Java to architecture. Combined, they offer the chance to learn from the best across our different countries\n\nJob Description\n\nAnalyze and understand business and technical requirements and work with clients across different domains and industries\nProduce high-quality design deliverables that describes how the solution will accommodate business and technical requirements\nResponsibility for larger functional and technical areas in the solution \nDesign, develop, and maintain efficient, reusable, and reliable code using best practices\nIdentify bottlenecks and bugs, and devise solutions to troubleshoot and address issues. \nConduct continuous unit and manual testing and deliver high quality solutions. \nWork and collaborate in an agile international environment with experienced and skilled colleagues in Vietnam and Europe\nPlan and organize your own work and accurately report issues and progress in a timely manner\nIdentify areas for own personal development\n\nQualifications\n\nOver 6 months working experience in IT Field\nBachelor or Master degree within a relevant IT specialization\nGood English skills both in writing and verbally\nStrong understanding of object-oriented programming and data modelling\nExperience in various design, architectural patterns and modern system development\nOpen towards and able to quickly learn new technologies\nAbility to work both independently and collaboratively as part of an international team\nProfessional pro-active attitude, taking responsibility and initiative\nEffectively estimate work and produce deliverables on time\n\nAdditional Information\n\nRecruitment process:\n\nPhone Screening (English Proficiency Test): Once your application is reviewed and meets the qualifications, the Recruitment Team will reach out to you via phone for a discussion. Please note, you may receive a call from an unknown number after submitting your application.\nIn-person Interview (Conducted in English, 2 Hours): The interview will take place at our office and will be conducted entirely in English. The session will be divided into two parts:\nIntroduction Round\nTechnical Round\nAnd other benefits that you would love:\n\nClear Academy system and mentoring program to help you develop your career within Netcompany \nPerformance appraisal twice a year to guarantee constructive feedback \nProfessional Scandinavian working environment that values innovation, creativity and new ideas along with being supportive, fun and flexible \n24/7 Mental Wellbeing Companion Program to help you overcome challenges and crisis in your life and work.\nAdvanced technical solutions, agile culture and the opportunity to work with the latest technologies \nAttractive salary that is adjusted annually based on your performance along with an annual performance bonus \nAttractive Healthcare insurance program for you and your family. \nVarious training on trending technologies, best practices, and soft skills \nManagement and leadership are accessible and encourage input from employees\nWorking with a variety of clients and colleagues all over the world \nSocial and sports activities hosted by Netcompany After Dark (Summer Party, Friday bar, go-kart, DIY workshops, outdoor activities, football, badminton, table tennis, basket ball, billboard etc.) \nIn Netcompany we believe that a diverse and inclusive workplace is central to our success, which is why all qualified candidates are invited to apply regardless of gender, sexual orientation, disability, age, religion and belief, ethnic background, nationality, gender identity or culture. We are committed to live out a culture where we provide equal opportunities for all.\n\nEither click the  ‘Apply Now’  button or send your details directly  to our recruitment team (recruitment.vn@netcompany.com) who will be able to help with any questions you may have.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '호치민, 베트남', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1356, 807, 2, 'Kỹ Sư Cầu Nối BrSE', 'Mô Tả Công Việc\n\nLàm việc trực tiếp với khách hàng để lấy yêu cầu.\nPhối hợp với team Nhật để xây dựng roadmap, giải pháp kỹ thuật và dẫn dắt dự án taị Việt Nam.\nPhối hợp với team lập trình thiết kế hệ thống, hạ tầng, đề xuất giải pháp.\nĐịnh hướng phát triển lên PM, Sales IT Manager, Quản lý chi nhánh.\n\nYêu Cầu Ứng Viên\n\nTiếng Nhật N2 trở lên, giao tiếp tốt với khách hàng Nhật.\nTừ 2 năm kinh nghiệm BrSE trở lên.\nBiết bất kỳ ngôn ngữ lập trình nào.\nƯu tiên có kiến thức hạ tầng hoặc phân tích dự án.\nCó kinh nghiệm quản lý cấp trung là lợi thế.\nTư duy logic, giải quyết vấn đề tốt, chủ động, có trách nhiệm.\nLàm việc nhóm tốt và chủ động.\nCó thể đi công tác Nhật ngắn hạn.\n\nChính Sách Phúc Lợi\n\nThưởng tháng 13, thưởng doanh thu, hoa hồng\nCó 18 ngày phép năm dành cho nữ và 12 ngày phép dành cho nam\nBảo hiểm xã hội đầy đủ\nBảo hiểm sức khỏe cá nhân\nReview lương hằng năm\nThưởng cá nhân xuất sắc, thưởng thâm niên\nCung cấp đầy đủ thiết bị làm việc\nThưởng các dịp Lễ, Tết, Trung Thu, …..\nHoạt động thường niên đa dạng: Team building, Company trip, Division picnics, Giáng sinh, Year end Party, 8/3, ...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1357, 808, 2, 'Intern Security Engineer', 'Job Description\n\n- Conduct penetration testing and perform code security reviews for product or project applications.\n- Build and maintain Security Information and Event Management (SIEM) systems.\n- Research cloud security technologies (Azure, AWS, GCP) and conduct cloud security audits.\n- Participate in network security maintenance, including incident analysis and investigation.\n- Explore cutting-edge security technologies, vulnerabilities, threat intelligence, and attack methods.\n\nRequirements\n\n- Senior college or university student, majoring in Cybersecurity, Computer Science, IT, or a related field.\n- Basic knowledge of Web/API penetration testing methodologies, security code reviews, and tools (e.g., Burp Suite).\n- Basic knowledge of at least one programming language, such as C#, JavaScript, Python, or Java.\n- Strong interest in researching security technologies and solving challenging problems.\n- Basic knowledge of Azure or any SIEM platform (e.g., Splunk, Azure Sentinel) is a plus.\n- Proficiency in spoken and written English.\n- Knowledge of Chinese is a plus.\n- Relevant certifications such as Offensive Security Certified Professional (OSCP), Offensive Security Web Expert (OSWE), or Certified Ethical Hacker (CEH) are a plus\n\nWork Location\n\n4th floor, Artemis, 03 Le Trong Tan, Khuong Mai ward, Thanh Xuan district, Hanoi\n\nBenefits\n\n- 5-day workweek\n- Young & vibrant working environment with great career development opportunities\n- Social insurance, medical insurance, and unemployment insurance, are based on actual salary\n- Yearly performance bonus (up to 2 months’ salary)\n- Regular team building events & internal activities (weekly happy hour, quarterly team building events, Lunar New Year parties, etc.)\n- Having an opportunity to be trained and work with professional experts.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Internship', '2025-10-07 20:59:18.149534'),
	(1358, 809, 2, 'Shopify Frontend Developer', 'About Lovepop\n\nLovepop is on a mission to create one billion magical moments.  We combine art x engineering to create the most magical paper art cards & gifts.  Featured on Shark Tank in 2015, Lovepop has become one of the top 10 Shark Tank investments in lifetime revenue.  Lovepop consistently ranks in the top Google results for cards online, enjoys 18% national brand awareness, and has helped its customers create over 50 million magical moments.  Our vision is to be the #1 online card destination for cards and we are building the team of A+ talent that will take us there.\n\nAbout the role\n\nWe are seeking a talented Shopify Frontend Developer to join our team. The ideal candidate will have experience working with Shopify’s ecosystem, including Liquid templates, Shopify APIs, and modern frontend technologies. You will be responsible for designing, developing, and optimizing Shopify storefronts, ensuring high performance and seamless user experiences.\n\nAccountabilities\n• Develop and customize Shopify themes using Liquid, HTML, CSS, and JavaScript\n• Optimize Shopify store performance for speed and responsiveness\n• Integrate third-party apps and APIs to enhance store functionality\n• Implement UI/UX best practices for improved customer experience\n• Work closely with designers and backend developers to implement store features\n• Debug and troubleshoot issues related to Shopify storefronts\n• Stay up-to-date with Shopify’s latest features, updates, and best practices\n\nQualifications\n• Must-Have Skills:\n• Proficiency in Shopify’s Liquid templating language\n• Strong experience in HTML5, CSS3, JavaScript, and jQuery\n• Familiarity with Shopify APIs and Shopify Plus features\n• Knowledge of responsive web design and cross-browser compatibility\n• Experience working with JSON, REST APIs, and third-party integrations\n• Strong debugging and troubleshooting skills\n• Nice-to-Have skills:\n• Experience with frameworks like React\n• Knowledge of headless commerce solutions with Shopify\n• Understanding of SEO best practices\n• Experience working with version control systems (Git)\n• Education & Experience\n• Bachelor’s degree in Computer Science, Web Development, or a related field (preferred but not required)\n• 3+ years of Shopify development experience\n\nLovepop Values\n• Engineering: Curiosity to discover how the world works\n• Hunger: Desire to take on more than is expected\n• Magic: Delivering unexpected experiences\n• Connection: Building relationships with each other', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1359, 810, 2, 'Software Engineer (WordPress & ReactJS)', 'At NFQ, we focus on Scaling Business—helping companies grow, optimize, and transform through technology and strategic consulting. With 800+ experts across 10 offices, we don’t just build software; we partner with businesses to solve complex challenges, drive efficiency, and unlock new growth opportunities.\n\nUnlike traditional outsourcing, our approach goes beyond executing tasks—we advise, challenge, and co-create solutions that enable businesses to scale effectively. Whether it’s expanding into new markets, streamlining operations, or driving digital transformation, we are committed to delivering impact that lasts.\n\nWhy NFQ?\n🔹 Fairness – We treat our colleagues, clients, shareholders, and the environment with integrity and respect.\n🔹 Entrepreneurship – We think like entrepreneurs, taking smart risks and turning ideas into real impact.\n🔹 Excellence – We go beyond expectations to deliver results that truly make a difference.\n\nWe are currently looking to expand our capabilities by adding a versatile developer with expertise in both WordPress and ReactJS. Join us to make your mark in a company where creativity meets technology. Your journey with NFQ Vietnam begins here!\n\nWhat You’ll Do\n- Lead the development, customization, and maintenance of a significant WordPress project for a few months\n- Develop custom WordPress themes and plugins, or customize existing ones to meet project requirements\n- Write clean, efficient, and well-documented PHP code within the WordPress framework\n- Implement responsive and interactive frontend interfaces using HTML, CSS, and JavaScript for the WordPress project\n- Collaborate with designers, content creators, and project managers during the WordPress project phase\n- Ensure the performance, security, and scalability of the WordPress site\n- After the initial project, actively participate in the development of modern web applications using ReactJS\n- Build reusable React components and frontend libraries\n- Integrate with backend APIs (including potentially the WordPress REST API) to fetch and display data\n- Collaborate with other React developers, participate in code reviews, and contribute to team knowledge sharing\n- Troubleshoot and debug frontend and potential backend issues\n- Stay up-to-date with the latest trends and best practices in both WordPress and ReactJS development\n\nWhat You’ll Bring\n- Min 6 months of proven experience as a WordPress Developer, demonstrating expertise beyond basic site setup and theme/plugin configuration\n- Strong proficiency in PHP, specifically within the WordPress development context\n- Extensive experience in custom WordPress theme and plugin development\n- Strong command of HTML, CSS, and vanilla JavaScript\n- Proficiency in ReactJS development, with 2 years of practical experience building modern web applications\n- In-depth understanding of core React concepts, including Hooks, functional components, state management (e.g., Context API, Redux, etc.)\n- Experience consuming RESTful APIs in React applications\n- Proficiency with Git for version control\n- Ability to work independently and take ownership of tasks, especially during the initial project phase\n- Excellent problem-solving skills and attention to detail\n- Good English communication skills and ability to collaborate effectively in a team environment\n\nNice-to-Have:\n- Experience developing custom Gutenberg Blocks using React\n- Experience with performance optimization techniques for both WordPress and React\n- Knowledge of MySQL database structure related to WordPress\n- Experience with modern frontend build tools (Webpack, Babel configuration)\n- Familiarity with testing frameworks (Jest, React Testing Library)\n\nWhy you\'ll love working here\n- 🏆 Join Vietnam’s Best IT Company – Recognized by ITViec for 7 consecutive years, including 2 successive years as the Winner. Work with some of the best minds in the industry and be part of a company that’s redefining how businesses scale through technology\n- 🌍 Career Growth & Leadership Development – Work closely with NFQ’s leadership team, gain mentorship from experienced executives, and have direct exposure to high-level strategic decisions. Your growth is limitless, as long as you’re ready to step up, opportunities will always be there for you\n- 💰 Competitive Compensation – We believe great talent deserves great rewards. Expect an attractive salary, performance-based bonuses, and a benefits package that reflects your impact. We value talent over salary budgets—exceptional contributions deserve exceptional rewards\n- ✨ And Many More Benefits to Explore! But most importantly healthy work-life balance and an environment where you can thrive—professionally and personally. Including:\n- Laptop is provided.\n- Community Tech activities.\n- A fun & dynamic environment and freedom to be creative.\n- Modern office with a flexible relaxing zone.\n- 13th-month salary pro-rata (based on business situation/performance).\n- Performance review 2 times/ year.\n- Extra Premium Healthcare & Annual Health-check.\n- 15 days annual leaves.\n\nLocation: NFQ welcomes you to our offices in Vietnam (Ho Chi Minh City, Da Nang City, Ha Noi City), choose the location that suits you best and join us on a journey of innovation and excellence\n- Working time: Monday - Friday (9AM - 6PM)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1360, 811, 2, 'Java Developer', '1.Mô tả công việc\n- Phát triển các ứng dụng Web và Web service, tìm hiểu các công nghệ mới\n- Nhận task từ phía PM, tiến hành điều tra, estimate và thực hiện task. Có khả năng nghiên cứu và đề xuất giải pháp cải thiện hiệu quả công việc.\n- Tham gia vào thiết kế và review source code.\n- Cập nhật tiến độ và thông báo tình trạng công việc trực tiếp tới quản lý dự án.\n- Teamwork với các thành viên khác bao gồm Developer, QA, PM, BrSE để thực hiện dự án thành công.\n- Nâng cao performance, turning logic, cài đặt các nghiệp vụ mới.\n\n2. Yêu cầu công việc\n- Có trên 3 năm kinh nghiệm lập trình bằng ngôn ngữ Java, sử dụng framework Spring Boot.\n- Kinh nghiệm với các hệ thống database, thành thạo MySQL, SQL Server…\n- Có kinh nghiệm làm việc với REST API.\n- Có tư duy logic, sử dụng thuật toán tốt.\n- Nắm vững kiến thức về lập trình Java, OOP, Design Pattern.\n- Có kiến thức về CI/CD, AWS,…là điểm cộng.\n\n3. Quyền lợi và chế độ\nChế độ đãi ngộ\n- Mức lương: Up to 35,000,000 VNĐ\n- Thưởng ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch, …)\n- Thưởng dự án, thưởng performance\n- Tổng thu nhập: Từ 14 -15 tháng lương/năm.\n\nMôi trường làm việc\n- Mức lương hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc.\n- Thưởng dự án, thưởng theo hiệu quả công việc, thưởng Tết và các dịp lễ.\n- Được đánh giá và xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc.\n- Nghỉ thứ 7, Chủ nhật, nghỉ Lễ/Tết và nghỉ phép theo Quy định của Pháp luật hiện hành.\n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty.\n- Được tham gia chế độ chăm sóc sức khỏe 24/24 AMELA Care khi làm việc chính thức tại công ty từ 06 tháng trở lên.\n- Khám sức khỏe định kỳ 1 năm/1 lần.\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan (hỗ trợ chi phí thi chứng chỉ, khen thưởng..).\n- Môi trường trẻ trung, năng động, thẳng thắn trao đổi và chia sẻ, thúc đẩy sự sáng tạo và phát triển.\n- Được tham gia các Câu lạc bộ của Công ty: CLB Bóng đá, Bilac…..\n- Được tham gia các hoạt động tập thể sôi động của công ty: Nghỉ mát hàng năm, Teambuilding hàng quý, Gala cuối năm…\n\nCơ hội phát triển\n- Tham gia vai trò chính trong việc tư vấn, xây dựng dự án từ giai đoạn đầu tiên\n- Tham gia nhiều chương trình đào tạo công nghệ, phương pháp làm việc\n- Được tham gia các chương trình đào tạo đa dạng và có nhiều cơ hội thăng tiến.\n\n4. Thời gian, địa điểm làm việc\n- Làm việc từ thứ 2 đến thứ 6\n- Thời gian làm việc từ 8h00 đến 17h30.\n- Nghỉ trưa từ 12h00 – 13h30\n- Địa điểm: Tầng 5, tháp A, tòa Keangnam, Mễ Trì, Nam Từ Liêm, HN.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1361, 812, 2, 'System/ Network/AV Engineer up to 30M', 'MÔ TẢ CÔNG VIỆC\n§ Tham gia triển khai các dự án về hạ tầng System/Network/Security/AV/ELV:\n§ Khảo sát chi tiết hiện trạng hệ thống khách hàng và báo cáo phân tích kết quả khảo sát.\n§ Thống nhất phạm vi công việc với Quản trị dự án và khách hàng.\n§ Chuẩn bị các tài liệu trước triển khai: thiết kế, kiểm thử và kế hoạch.\n§ Kiểm tra, bàn giao và lắp đặt thiết bị.\n§ Triển khai các tính năng của sản phẩm dự án theo thiết kế đã thống nhất hoặc theo yêu cầu của khách hàng.\n§ Báo cáo triển khai.\n§ Lập tài liệu triển khai, ghi nhận thông tin cấu hình và tài liệu vận hành.\n§ Thực hiện kiểm thử và bàn giao, hướng dẫn sử dụng hệ thống.\n§ Thực hiện các kiểm tra bảo mật định kỳ và đánh giá rủi ro.\n§ Xây dựng và duy trì các chính sách, quy trình và hướng dẫn bảo mật mạng.\n§ Hỗ trợ các hoạt động khắc phục sự cố bảo mật mạng và cung cấp tư vấn kỹ thuật về các vấn đề an ninh mạng.\nYÊU CẦU CÔNG VIỆC\n§ Bằng cử nhân/kỹ sư trong lĩnh vực Công nghệ Thông tin, An ninh Mạng hoặc các lĩnh vực liên quan.\n§ Có ít nhất 3 năm kinh nghiệm triển khai các giải pháp trong lĩnh vực Server, Network, AV (Audio Visual), ELV,.... \n§ Kiến thức sâu rộng về các giao thức mạng và các công nghệ bảo mật.\n§ Có các chứng chỉ thiết kế và triển khai các sản phẩm giải pháp mạng/bảo mật như CCNP, ACP-CA, PCNSE, CCSE, FCSS hoặc tương đương là lợi thế.\n§ Kiến thức và khả năng triển khai:\n§ Mảng sản phẩm: server, router, switch, wireless, internet load balancer, NGFW, NAC, IPS/IDS, EPP, XDR, SASE, video/audio conferencing.\n§ Hiểu biết và thành thạo cấu hình thiết bị mạng/bảo mật/hệ thống của Cisco, Aruba, Dell, Palo Alto Networks, Fortinet hoặc các hãng tương đương.\n§ Tính chất dự án: triển khai mới, nâng cấp/chuyển đổi các dự án tương đối phức tạp (multisite, đáp ứng số lượng user/ứng dụng lớn).\n§ Có thể đáp ứng vai trò lead kỹ thuật theo phân công dự án (lên kế hoạch, thiết kế, quản lý công việc nhóm).\n§ Tiếng Anh trình độ upper intermediate trở lên (IELTS 5.0/TOEIC 500+).\n§ Kỹ năng tin học văn phòng cơ bản (Word, Excel, PowerPoint) và các ứng dụng phục vụ dự án (AutoCad, Visio, MS Project hoặc tương đương).\nTHU NHẬP:\n§ Lương thỏa thuận theo năng lực và kinh nghiệm. \n§ Thưởng KPIs dựa vào kết quả đánh giá công việc quý/năm tùy theo vị trí công việc.\n§ Xét tăng lương theo năng lực và kết quả công việc định kỳ 1 lần/năm. Hoặc tăng lương đột xuất theo hiệu quả công việc.\nCHẾ ĐỘ ĐÃI NGỘ:\n§ Đóng BHXH đầy đủ ngay khi ký Hợp đồng chính thức.\n§ Nghỉ phép: 12 ngày/năm.\n§ Được tham gia các chương trình đào tạo chuyên môn, nghiệp vụ từ cơ bản đến nâng cao trong nước và nước ngoài. Được trang bị laptop/thiết bị công nghệ trong quá trình làm việc.\n§ Môi trường trẻ, năng động và chuyên nghiệp.\n§ Tham gia Team building và các hoạt động văn hóa đa dạng.\n§ Được vinh danh các giải thưởng năm của Công ty và khen thưởng trên các thành tích xuất sắc (dự án, kinh doanh, quản trị).\n§ Thời gian nghỉ hàng tuần: Nghỉ chiều thứ 7 & Chủ nhật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1362, 776, 2, 'Senior .Net Fullstack Engineer (Global Product/ Product Development)', 'LOGIX TECHNOLOGY is a distinguished software services company, specializing in the provision of professional software development services, fostering strong partnerships through the establishment of offshore development centers, offshore product development, and software testing with an infrastructure-oriented approach. We excel at simplifying and enhancing offshore outsourcing, not only by delivering innovative solutions to meet our clients’ exact requirements through high-performance teams but also by significantly contributing to our clients’ success by reducing time-to-market and improving quality.\n\nAt LOGIX TECHNOLOGY, we are committed to delivering the highest level of professional excellence and making a significant impact in the software development sector. If you are a dedicated professional looking to join a dynamic team working with global leaders, we encourage you to explore the exciting opportunities that await you with us.\n\nJob Description\n\nDevelopment & Implementation\n- Write, maintain, and test high-quality, efficient, and scalable code using .NET technologies.\n- Translate software requirements into functional, maintainable code.\n- Develop and implement unit tests and conduct thorough testing of all code.\n- Troubleshoot, debug, and fix software defects.\n\nDesign & Architecture\n- Participate actively in design discussions and contribute to system architecture decisions.\n- Create and maintain detailed design documents.\n- Adhere to software design principles such as SOLID and DDD.\n\nQuality Assurance\n- Write unit and integration tests to ensure code quality and functionality.\n- Own unit test coverage and identify areas for improvement.\n- Ensure high code quality and adherence to best practices.\n\nTeamwork & Mentorship\n- Mentor and guide junior developers, providing technical guidance and support.\n- Conduct code reviews and provide constructive feedback.\n- Assist in breaking down complex tasks into smaller, manageable sub-tasks.\n\nCollaboration & Communication\n- Effectively communicate technical information to both technical and non-technical audiences.\n- Collaborate effectively with cross-functional teams (e.g., product, design, QA).\n- Proactively identify and report project risks and issues.\n\nCloud & DevOps\n- Experience with developing and deploying applications on cloud platforms (Microsoft Azure, AWS…)\n\nRequired Skills & Experience\n- Bachelor’s degree in Computer Science, Software Engineering, or a related field.\n- 4+ years of experience in full-stack development: proficiency in Tech stack/language/framework Backend (.Net Core), Front-End (JavaScript, TypeScript, ReactJS, Angular, VueJS, HTML5 / CSS 3, SASS/LESS), Database (MySQL, MSSQL, PostgreSQL, MongoDB, Cassandra), Web Server (Nginx/Apache), DevOps (Jenkins/Docker Compose/SonarQube/Docker Swarm/Gitlab).\n- Strong understanding of object-oriented programming principles, design patterns, and architectural best practices.\n- Experience with cloud-native development and deployment on Microsoft Azure.\n- Familiarity with database design and development, preferably with experience in SQL Server..\n- Strong problem-solving, analytical, and debugging skills.\n- Strong communication and interpersonal skills.\n- Ability to work independently and as part of a high-performing team.\n- A strong work ethic and a passion for continuous learning.\n- Proficient English communication and writing.\n\nBenefits and Perks\n- Attractive Salary & Benefits, full salary in probation.\n- Performance appraisal twice a year, 13th-month salary.\n- Healthcare and incident insurance.\n- 16 Paid Leave days / year (12 Annual Leave, 02 Summer Leave, 01 Birthday Leave & 01 Christmas Leave).\n- Company trip, annual year-end party, team building activities.\n- Diverse careers opportunities with Software Services, Software Product Development.\n- Working and growing in a value driven, international working environment and standard Agile culture with passionate and talented teams.\n- Various training on hot-trend technologies, best practices, and soft skills.\n- Free in-house entertainment facilities: football, table football, PS, badminton, trekking…coffee, and snacks (instant noodles, cookies, candies…)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1363, 755, 2, 'Junior/Mid Fullstack Engineer (TypeScript/JavaScript) - Hybrid working model 100%', 'Company Description\n\nWelcome to SMG Vietnam! SMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nJob Description\n\nThis job refers to our Real Estate brands, Homegate and Immoscout24, the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing.\n\nWe are looking for a Junior/Mid Fullstack Engineer to help us build the future of the Swiss real estate market by contributing to our cutting edge, cloud based, technology stack. You will get to collaborate and access the wealth of knowledge and experience from a community of amazing engineers who come from all parts of the globe and are ready to share their expertise and aid you in your path to fulfilling your potential.\n\nJoin our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nOur tech stack\n\n- Frontend: Vue.js with TypeScript\n- Backend: Node.js and TypeScript, following a serverless microservices architecture in an AWS cloud environment (Lambda, DynamoDB, SQS, SNS, S3, etc.)\n- Monitoring: Datadog\n- Documentation: Backstage\n\nLearn more about us and our engineering practices in our blog at https://medium.com/smg-real-estate\n\nYour Mission:\n\n- Building and experimenting: Writing clean, modular code within a modern, serverless architecture, with a focus on refining and experimenting with functionality.\n- Collaborating and creating: Working closely with a talented team of engineers to design, develop, and deliver features that make a real impact on users.\n- Learning and applying: Gaining hands-on experience with AWS Serverless, CI/CD, and other cutting-edge tools like AI/Datalake, continuously enhancing skills along the way.\n- Contributing to innovation: Bringing fresh ideas to improve both software and processes, always looking for opportunities to push boundaries. Your responsibilities will evolve as we grow.\n\nQualifications\n\nWhat will you bring to the ride?\n\n- Fluent in English, both written and spoken.\n- Bachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience.\n- 1+ years of experience in Software Development.\n- Experience with TypeScript/JavaScript, with proficiency in at least one of the following:\n  - Comfortable with Vue.js or React.js, and capable of building modern web applications.\n  - Experience with Node.js backend development, including implementing synchronous and asynchronous services.\n  - Some exposure to AWS services and a Serverless Technology Stack.\n- Strong sense of ownership and responsibility for what the team builds. Before blindly adding code to a codebase, be able to identify problematic areas and refactor them with maintainability and stability in mind.\n- Curious, open-minded, and enthusiastic about growing in a collaborative team environment.\n- Ability to use AI tools to assist with coding is a plus.\n\nWe value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique.\n\nAdditional Information\n\nWhat do we offer?\n\n- Competitive Benefits: Attractive salary, full pay during probation, 13th-month bonus, and full social insurance contributions.\n- Generous Leave: 21+ annual paid days off, 24 days for learning & sharing, and flexible working hours with no overtime.\n- Health & Wellness: Premium private insurance for you and your family, free food, and access to various classes and clubs.\n- Growth Opportunities: Personalized development plans, yearly education budgets, regular Hackathons, and potential travel to Switzerland and Europe.\n- Modern Work Environment: Hybrid model, top-tier equipment, and a friendly, agile, and transparent culture.\n- Supportive Onboarding: Comprehensive assistance to help you settle in.\n\nRecruitment Process\n\nWe believe hiring is a two-way street, where both parties get to know each other. Here\'s what you can expect:\n\n- Initial screening call with HR – A brief conversation to understand your background and expectations.\n- Meeting with the Hiring Manager – A deeper discussion about the role, your experience, and how we work.\n- Technical Assessment – A hands-on assessment of your skills, conducted via live coding and system design exercises.\n- Casual Meeting with Director – An informal conversation to align on vision, culture, and goals.\n\nAt SMG Vietnam, we value diverse perspectives and individual growth. We welcome candidates from all backgrounds and encourage you to apply, even if you don’t meet every requirement. Together, we embrace differences, nurture potential, and celebrate success.\n\nApply now\n\nTo take this opportunity, send us your detailed CV and feel free to add any supporting documents we need to look at in order to understand that you are the perfect fit.\n\nAbout Us\n\nSMG Swiss Marketplace Group AG. is a pioneering network of online marketplaces and cutting-edge European digital company that simplifies people’s lives with innovative products.\n\nSMG Swiss Marketplace Group AG. provides customers the best tools to meet their life decision needs. The portfolio includes Real Estate (ImmoScout24, Homegate, Flatfox, alle-immobilien.ch, Immostreet.ch, home.ch, Publimmo, Acheter-Louer.ch, CASASOFT, IAZI), Automotive (AutoScout24, MotoScout24), General Marketplaces (anibis.ch, tutti.ch, Ricardo) and Finance & Insurance (FinanceScout24, moneyland.ch).\n\nThe company was founded in November 2021 by TX Group AG, Ringier AG, La Mobilière and General Atlantic.\n\nDisclaimer\n\nSMG Swiss Marketplace Group AG primarily engages directly with candidates. We do not accept unsolicited resumes or candidate profiles from recruitment agencies unless we have specifically requested their assistance for particular roles. Any submissions made without a prior request from our Talent Acquisition team will not be acknowledged or considered. We appreciate the understanding and cooperation of recruitment agencies in respecting this policy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Củ Chi district, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1364, 813, 2, 'LẬP TRÌNH VIÊN PHP', 'Mô tả công việc\n\n- Lập trình ứng dụng web theo yêu cầu dự án\n- Kiểm tra chất lượng trước khi chuyển cho tester\n- Nghiên cứu và phát triển các phần mềm, sản phẩm, module mới\n- Các nhiệm vụ khác theo yêu cầu của công ty\n\nĐại học', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1365, 702, 2, 'Binance Accelerator Program - Android Engineer', 'Binance is the global blockchain company behind the world’s largest digital asset exchange by trading volume and users, serving a greater mission to accelerate cryptocurrency adoption and increase the freedom of money.\n\nAre you looking to be a part of the most influential company in the blockchain industry and contribute to the crypto-currency revolution that is changing the world?\n\nJob Responsibilities:\n\n- Assist the Android development team in the design, development, and testing of mobile applications;\n- Write maintainable and high-performance code in Kotlin or Java;\n- Participate in product requirement reviews and provide feasible technical solutions;\n- Collaborate with UI/UX designers to deliver high-quality user interfaces and interactive experiences;\n- Troubleshoot and fix bugs, while continuously optimizing app performance;\n- Learn and apply mainstream Android development frameworks such as Android Jetpack, MVVM architecture, and Material Design;\n- Write technical documentation and support the release and deployment process.\n\nRequirements:\n\n- Proficiency in Java or Kotlin with a foundational understanding of Android development;\n- Familiar with Android Studio and basic layout components such as Activity, Fragment, RecyclerView, etc.;\n- Understanding of RESTful APIs and network communication using libraries like Retrofit and OkHttp;\n- Basic knowledge of Git version control;\n- Strong learning ability and a collaborative team player;\n- Personal projects or GitHub contributions are a strong plus.\n- Currently enrolled in a university program, majoring in Computer Science, Software Engineering, Information Technology, or a related field.\n\nPreferred Qualifications:\n\n- Familiarity with Jetpack components (LiveData, ViewModel, Room, etc.);\n- Experience using Firebase, Google Maps, or third-party SDKs;\n- Experience with cross-platform development tools like Flutter or React Native.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1366, 679, 2, 'Nhân Viên Triển Khai Phần Mềm – Khu Vực Miền Nam (Open for Fresher)', '🚌Nhân Viên Triển Khai Phần Mềm – Khu Vực Miền Nam\n(Open for Fresher)\nHiện tại, Vexere là hệ thống vé xe lớn nhất Việt Nam, với hơn 1.000 hãng xe hợp tác bán vé với Vexere, phủ rộng hơn 3.000 tuyến đường trong và ngoài nước giúp người dùng có thể tìm thông tin chuyến xe, hãng xe, và mua vé trực tuyến dễ dàng. Đồng thời, Vexere còn cung cấp những đánh giá của các hành khách đã đi những hãng xe này. Hành khách có thể dễ dàng lựa chọn trước chỗ ngồi yêu thích, thanh toán vé trực tuyến, tiền mặt tại các cửa hàng tiện lợi trên cả nước.\n\nCác thành viên của Vexere tin rằng một tổ chức được sinh ra là để giải quyết các vấn đề nhức nhối trong xã hội. Văn hóa công ty chú trọng tinh thần cộng đồng, hỗ trợ lẫn nhau. Tất cả thành viên Vexere luôn được tạo cơ hội để được thể hiện bản thân, đóng góp sáng kiến về sản phẩm và chiến lược, và hướng đến trở thành những nhà lãnh đạo trong tương lai.\n\nHãy cùng tham gia vào team Triển Khai Phần Mềm – Software Implementation (SI) tại Vexere để cùng hỗ trợ thêm thật nhiều đối tác nhà xe trong quá trình quản lý vận hành và thúc đẩy gia tăng doanh số, xứng tầm là đơn vị tiên phong trong quá trình cách mạng số hóa ngành vận tải xe khách tại Việt Nam.\n\nMô Tả Công Việc\n- Học và nghiên cứu các giải pháp Phần mềm quản lý nhà xe.\n- Hướng dẫn và triển khai phần mềm cho các đối tác vận tải.\n- Đào tạo nhân viên nhà xe cách sử dụng phần mềm một cách hiệu quả.\n- Hỗ trợ khách hàng trong quá trình vận hành sau triển khai.\n- Phối hợp với các phòng ban để đảm bảo chất lượng dịch vụ.\n- Thực hiện các nhiệm vụ khác theo yêu cầu từ cấp trên.\n\nYêu Cầu Công Việc\n- Tốt nghiệp từ Trung cấp trở lên các chuyên ngành CNTT, Quản trị kinh doanh hoặc các lĩnh vực liên quan.\n- Kỹ năng giao tiếp và truyền đạt tốt, có khả năng hướng dẫn người khác.\n- Kỹ năng tổ chức và quản lý công việc tốt, có thể làm việc độc lập.\n- Có thái độ tích cực.\n- Không yêu cầu kinh nghiệm (công ty sẵn sàng đào tạo từ cơ bản đến nâng cao) quan trọng là chịu học hỏi.\n\nChế Độ – Phúc Lợi\nBên cạnh việc tìm kiếm và định hướng nhân sự công ty đến các giá trị “right people”: tư duy logic, suy nghĩ tích cực, minh bạch và nhất quán, tò mò với những điều mới, giao tiếp dựa trên lắng nghe, khiêm tốn và trách nhiệm. Vexere còn không ngừng cải thiện, nâng cao chất lượng đời sống cho toàn thể nhân sự công ty, dưới đây là các giá trị phúc lợi mà bạn sẽ nhận được khi tham gia tại Vexere:\n- Mức lương căn bản theo năng lực\n- Bonus tháng + Trợ cấp điện thoại + Công tác phí (hỗ trợ 100%)\n- Thưởng KPI theo quý (up to 10 tháng lương căn bản/ năm)\n- Tổng thu nhập từ 12.000.000 – 17.000.000đ/ tháng \n- Được review lương định kỳ 1 năm 2 lần\n- Thưởng cuối năm\n- Thưởng tri ân nhân viên gắn bó lâu năm\n- Lộ trình thăng tiến rõ ràng, phù hợp với năng lực, có cơ hội định hướng phát triển lên các vị trí chủ chốt\n\nChế Độ Khác\n- Tham gia BHYT, BHXH, BHTN theo quy định, ký hợp đồng chính thức sau khi thử việc.\n- 12 ngày phép/ năm, 3 năm tăng 1 ngày phép, ngày phép được cộng dồn qua 2 năm tiếp theo hoặc quy ra lương\n- Khám sức khoẻ tổng quát hàng năm\n- Chính sách vay cá nhân, tạm ứng lương\n- Chính sách giảm giá vé xe cho nhân viên\n- Chính sách ốm đau, thai sản, hiếu hỉ…\n- Chính sách thưởng khi giới thiệu nhân viên vào làm việc\n- Chính sách khoá học đào tạo phát triển bản thân: 18 triệu/ năm\n\nThời Gian Làm Việc\n- Vexere đang áp dụng hình thức làm việc Hybrid (có thể linh hoạt làm tại nhà hoặc lên văn phòng)\n- Thời gian làm việc: từ 8h30-18h00 từ thứ Hai – thứ Sáu + sáng thứ Bảy\n\nĐược Tham Gia Các Hoạt Động\n- CLB thể dục thể thao của công ty\n- Chính sách cho các hoạt động teamwork mỗi tháng\n- Tham quan nghỉ mát, team building, year end party\n- Được làm việc tại văn phòng trẻ trung, sôi nổi: môi trường làm việc nhân văn, lành mạnh, cởi mở cùng với những người trẻ năng động\n\nHiểu thêm về chúng tôi tại: Review về Vexere\n\nCách Thức Ứng Tuyển – Nhân Viên Triển Khai Phần Mềm – Khu Vực Miền Nam\n- Để biết thêm thông tin về công việc, vui lòng liên hệ Bộ phận Nhân sự:\n- Gửi CV về Email: careers@vexere.com, tiêu đề: Vị trí ứng tuyển – Họ tên ứng viên\n- Zalo: 0989 036 781 (A. Đăng Khoa)\n- Văn phòng làm việc tại miền Nam: CirCO Hoàng Diệu – Tòa nhà H3, 384 Hoàng Diệu, Phường 6, Quận 4, TP HCM\n- Theo dõi Vexere Careers tại để cập nhật các vị trí tuyển dụng và rất nhiều những thông tin thú vị khác.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1367, 203, 2, '[HCM] QC Engineer (AI Project)', 'Job Description\n\n- Work closely with multiple stakeholders such as the business team, product managers, and engineers to sync up product features and troubleshoot issues.\n- Work with project developers, business analysts, and customer support teams to ensure software solutions meet our user expectations.\n- Develop software test cases based on consumer specifications and requirements.\n- Perform root cause analysis on defects found to identify and mitigate project risks.\n- Conduct exploratory and usability testing to locate bugs before the software is introduced into production.\n- Execute comprehensive testing against the software, ensuring all features function as designed and intended.\n- Contribute to the continuous improvement of software testing methodologies and develop standard operating procedures (SOPs), if necessary.\n- Perform functional and user scenario tests on Web platforms.\n- Communicate with the technical team and reproduce issues for the debug plan.\n- Work closely with the project team to understand user requirements and review issues.\n- Coordinate testing activities with other members.\n- Ensure UAT is delivered with approved quality and timeline.\n\nJob requirement\n\n- 2+ years of experience with software testing.\n- Experience in developing test cases, test plans, and execution tests (functional testing, non-functional testing).\n- Knowledge of computer architecture and tools for manual test, unit testing, integration testing, functional testing, and bug-tracking systems.\n- Good communication skills, who can convert business feedback into technical requirements and vice versa.\n- Experience in web and mobile applications.\n- Ability to multitask in a dynamic, fast-paced environment.\n- Having enthusiasm and passion at work, having a responsibility to ensure product quality.\n- Good at research, problem-solving, and troubleshooting.\n- Experience in APIs(Postman), database, and backend testing.\n- Having ISTQB certification is a plus\n\nWhy you\'ll love working here\n\nAhamove is the number 1 on-demand logistics company in Vietnam, the place to give you access to current and first-class technologies, as well as connect the e-commerce and payment platforms of millions of users.\n\n- At Ahamove, the sense of ownership is put on the top and the team is supported to complete your work, as well as supported and made favorable conditions for learning and self-improvement.\n- An open and honest culture where people are valued, treated fairly, trusted, and empowered.\n- Disruptive innovations\n- People-oriented philosophy of doing business\n- Your footprint on the regional on-demand market\n- Sharp, motivated colleagues in a fun office environment\n\nBenefit\n\n- Grab/Be for work: 1M/month\n- Laptop & PVI insurance\n- Working 5 days/week\n- Competitive salaries and benefits according to experience and education level\n- And more\n\nỨng tuyển ngay', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1368, 496, 2, 'Manual Tester (QA/QC, English required)', 'Job Description\n\n- Develop test cases based on specifications\n- Check test cases coverage customer’s requirement with Senior Tester or Business Analysts\n- Execute test according to the test plan\n- Report bug with detailed information\n- Qualify bug’s severity and priority rating\n- Provide estimations in hours\n- Report on time spent, progression\n- Ensure the first level of support\n- Automate tests.\n\nDesired Skills And Experience\n\n- Thorough understanding of the software life-cycle\n- Good understanding of various types of testing and design test case techniques\n- Knowledge of bug tracking tools such as Redmine, Trac, Bugzilla, Mantis, Testlink, JIRA\n- Working experience in reporting and describing anomalies\n- Knowledge of quality main KPIs\n- Customer-focused mindset, can-do attitude and high team-work spirit\n- Ability to ask the right question\n- Attention to details\n- Critical thinking and ability to see large picture\n- Ability to summarize and go straight to the point, proactive in communication\n- Good English communication\n- Knowledge/experience on the following subjects is an advantage\n  - Web application testing, desktop and mobile browsers\n  - Responsive web applications and Mobile applications\n  - Basic knowledge on HTML\n  - Automation testing concept\n\nWhy ekino?\n\n- High-ownership working environment: You will take full responsibility and control of your missions contributing to the team\'s success\n- Continuous skill improvement with new technologies, challenging projects, on-the-job coaching, and training programs\n- Annual performance review & bonus: recognize your efforts and identify development/ improvement needs\n- Clear career path: define your career development with long-term vision\n- Be secured in your mind with employee’s care: private healthcare insurance package, medical check-up, support allowance...\n- Great-place-to-work activities (company trip, sport clubs...): enhance teamwork spirit and facilitate your work-life harmony.\n\nThank you for your time and enthusiasm in our career opportunities.\n\nPlease kindly note that shortlisted candidates will be contacted within 3 weeks of application. Alternatively, we will reach out to you when another suitable chance arises in the future.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 11, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1369, 814, 2, '[iKame Apps] Backend Developer', 'Location:\nHà Nội\n\nSalary:\nUp to $1500\n\nExpiration date:\n30/06/2025\n\nMô tả công việc\n\n- Tham gia vào quá trình thiết kế, phát triển và triển khai các giải pháp có khả năng mở rộng, độ tin cậy, bảo mật.\n- Xây dựng RESTful APIs, Web Sockets, Caching, Load Balancing, Security, etc.\n- Liên tục nghiên cứu, cập nhật các công nghệ mới để ứng dụng vào sản phẩm.\n- Hỗ trợ cho các thành viên khác trong team phát triển.\n- Hỗ trợ mentor, phát triển đội ngũ Junior/Fresher.\n\nYêu cầu ứng viên\n\n- Ít nhất 2 năm kinh nghiệm lập trình Backend\n- Có kinh nghiệm Express JS, Nest JS.\n- Hiểu về cơ sở dữ liệu, thiết kế cơ sở dữ liệu, triển khai và tối ưu hóa cơ sở dữ liệu.\n- Nắm vững kiến thức về cấu trúc dữ liệu và giải thuật.\n- Khả năng đọc - viết tiếng Anh tốt (từ Intermediate trở lên).\n- Có kinh nghiệm về HTML5, CSS3 và JavaScript là một lợi thế.\n- Đã từng làm việc với Docker, Docker compose, Serverless, Pipeline CI/CD là một lợi thế.\n- Đã từng triển khai hệ thống Microservice, triển khai hệ thống trên AWS, Azure, GCP… là một lợi thế\n\nQuyền lợi\n\nChế Độ Phúc Lợi\n\n- Mức lương lên tới $1500, review lương ít nhất 2 lần/năm\n- Thưởng HẤP DẪN: Thưởng hiệu quả kinh doanh theo 2 quý/lần + Thưởng tháng lương thứ 13 + Thưởng Lễ + Thưởng giới thiệu ứng viên\n- Trợ cấp ăn trưa: 1 Tr/tháng\n- Thử việc 2 tháng full 100% lương\n- Trau dồi kinh nghiệm thực chiến với việc hỗ trợ tới 100% chi phí khóa học\n\nCơ Hội Tham Gia\n\n- Được đào tạo và tham gia phát triển đa dạng sản phẩm hướng tới CHẤT LƯỢNG & GHI DẤU ẤN – LÀ 1 TRONG NHỮNG CÔNG TY TOP ĐẦU MOBILE APP TẠI VIỆT NAM với hàng triệu users mỗi ngày\n- Lộ trình thăng tiến rõ ràng, đào tạo cùng các chuyên gia lão làng trong ngành\n- Môi trường trẻ, thiết bị hiện đại cùng văn phòng xịn xò view "triệu đô"\n- Các chế độ đãi ngộ khác như: Gói khám sức khỏe cao cấp, Teambuilding thường xuyên, Du lịch dài ngày trong và ngoài nước, CLB Thể thao, CLB Tri thức,...\n- "Grow everday" - Cùng nhau phát triển mỗi ngày\n- Thời gian làm việc: 08h30 - 18h00 thứ 2 đến thứ 6; nghỉ trưa 1,5h, không OT - cân bằng cuộc sống và công việc\n\nCÁCH THỨC ỨNG TUYỂN\n\n💌 Ứng viên gửi CV về email: recruitment@ikameglobal.com\n\n➡️Hotline: 024 6662 5287 | HR Department\n\n➡️Head Office: Tầng 9 & 10 tòa Peak View, số 36 Hoàng Cầu, Ô Chợ Dừa, Đống Đa, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1370, 815, 2, 'Japanese jobs at FPT Software Vietnam & Japan', 'Hi anh chị ứng viên, \nEm là Hồng (HongHT) – Talent Acquisition Leader tại FPT Software.\nHiện tại, thị trường Nhật Bản đang bước vào giai đoạn bùng nổ với tốc độ tăng trưởng ấn tượng. Và FPT Software – với khát vọng vươn ra toàn cầu – chắc chắn không đứng ngoài cuộc chơi này.\nChính vì vậy, chúng tôi đang mở rộng quy mô tuyển dụng với hàng loạt cơ hội "đắt giá" dành riêng cho các ứng viên biết tiếng Nhật – những người sẵn sàng đón đầu làn sóng phát triển mạnh mẽ tại thị trường này.\nNếu bạn đang tìm kiếm một bệ phóng sự nghiệp thực thụ tại môi trường toàn cầu, đây chính là thời điểm!\n🌟 HOT JOBS – JAPANESE JOBS 🌟\n💰 Mức lương lên tới $4,200 Gross\n🏢 Hình thức làm việc: Remote / Hybrid / Tại văn phòng\n🎌 Mở rộng tuyển dụng cho cả thị trường Việt Nam và Nhật Bản\nList job cụ thể theo từng location:\n📍 Hà Nội\n• Business Analyst (JP N2)\n• Project Manager (JP N2)\n• IT Comtor (JP N2)\n• Senior BrSE (JP N2)\n📍 Hồ Chí Minh\n• Presales / Business Analyst (JP N2)\n• Senior Manual Test / Automation Test / Test Lead / Test Manager (JP N2)\n• BrSE, IT Comtor, Project Manager / PMO (JP N2)\n• SAP Technical Manager / SAP Senior Project Manager (JP N2)\n📍 Đà Nẵng\n• Quality Assurance (JP N2)\n• Project Manager (JP N2)\n• Middle/Senior Automation Tester (JP N2)\n• IT Comtor (JP N2)\n• Middle / Senior BrSE / Developer (JP N2)\n• Business Analyst (Junior → Leader) (JP N2)\n• BrSE (Junior → Senior) (JP N2)\n• BrSE (for Automotive projects) (JP N2+)\n• Japanese Officer (JP N3+)\n• Middle/Senior DevOps Cloud (AWS / Azure) (JP N2)\n• Middle/Senior Automotive Tester (JP N2)\n• Middle/Senior Manual Tester (JP N2)\n📍 Quy Nhơn\n• Senior Project Manager (JP N2)\n• Business Analyst (Junior → Leader) (JP N2)\n📍 Huế\n• Senior IT Comtor (N2)\n• Business Analyst (Junior → Leader) (JP N2)\n• Middle/Senior BrSE (JP N2)\n📍 Nhật Bản\n• PM/FrontPM (JP N2)\n• PM (JP N2)\n• Business Analyst (Junior → Leader) (JP N2)\n• Middle/Senior BrSE/FrontSE (JP N2)\n• Senior System Engineer – C/C++ Automotive (JP N2)\n• Senior System Engineer – Model-Based Design (MBD) (JP N2)\n• Senior Software Engineer – Embedded (JP N2)\nNếu anh/chị đang cân nhắc tìm kiếm một cơ hội mới trong môi trường chuyên nghiệp, quốc tế – FPT Software luôn sẵn sàng chào đón anh/chị.\n👉 Anh/chị vui lòng kết nối với em qua Zalo để em hỗ trợ nhanh nhất: (+84) 967166294.\nHoặc các kênh ở phần chữ kí bên dưới của em ạ.\nChúc anh/chị tuần mới nhiều năng lượng nha.\nBest regards,\nHO THI HONG (Ms. Hootee).\nTalent Acquisition Leader (FWA.CTA)\nCentral Talent Acquisition - FPT Software\nMobile       (+84) 967 166 294\nMail         honght@fpt.com\nFind me at  http://linkedin.com/in/hothihong\nFacebook        https://www.facebook.com/hong.hootee', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1371, 801, 2, 'Frontend Engineer', 'Fully Onsite Position*\n\n- Collaborate with other team members (PM, UI, backend engineer, QA) to provide a seamless freight experience for our customer;\n- Participating design the front end architecture, collaborate with backend engineers to develop and deliver elegant product solutions;\n- Propose innovative technical solutions to hard business problems;\n- Curiosity and passion, understanding of LLM and AI Agent framework;\n- Lean and grow constantly, improve yourself and make the team member around you better\n\nRequirements\n\n- Familiarity with the development process and work patterns of internet products.\n- Fluent in frontend technologies, including HTML, CSS, JavaScript, and TypeScript.\n- Fluent in React, with practical experience in developing complete React projects.\n- Solid experience with common frontend frameworks, libraries, and tools such as Webpack, Babel, Vite, Turbo, Lerna, Next.js, React, and Vue.\n- Understanding and familiarity with Node.js, capable of project building, with some backend development experience in Node.js.\n- Proficiency in TypeScript; practical experience with TypeScript projects is a plus.\n- Familiarity with commonly used frontend state management tools, such as Redux, MobX, Observable, React Hooks, Zustand, and Recoil.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1372, 264, 2, 'Embedded Software Engineer (Junior/Middle/Senior)', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n- Requirement Analysis, Architectural Design, Detailed Design, Implementation, Unit Test, Integration Test, Qualification Test for HW driver, Embedded Software.\n- Compiling, flashing and debugging on ECU.\n- Teamwork and handle day-to-day work efficiently and independently.\n\nWhat You’ll Bring\n- Electronics/ Mechatronics/ Embedded Engineering/ Computer Engineering or relevant background.\n- Have 1+ hand-on year of experience in HW device driver, Embedded System.\n- Good in C/C++ programming for HW driver, Linux Kernel, Embedded Software, Compiler, Bashscript, Shell Script Makefile.\n- Have experience in working with HW Manual, Datasheet, Schemantic.\n- Have knowledge in some of Linux OS, Realtime OS.\n- Good in troubleshooting, critical thinking and teamwork.\n- Competent in English.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミンシティ都市圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1373, 674, 2, 'Game Developer (Cocos2d)', 'Mô tả công việc\n\nPhát Triển Gameplay\n\n- Đóng góp vào việc thiết kế và kiến trúc của các dự án game mới.\n- Đảm bảo tính khả thi về mặt kỹ thuật của các thiết kế UI/UX.\n- Viết mã sạch, hiệu quả, mạnh mẽ và được tài liệu hóa tốt.\n- Tích hợp các 3rd SDK (ví dụ: phân tích, quảng cáo, mua hàng).\n\nTối Ưu Hoá Và Debug\n\n- Xác định và giải quyết các thách thức kỹ thuật phức tạp và lỗi.\n- Tối ưu hóa hiệu suất trò chơi cho nhiều loại thiết bị di động (iOS, Android và Html5).\n- Hỗ trợ các bộ phận khác (Tester, Art, GD) trong quá trình kiểm thử sản phẩm.\n- Tham gia vào việc đánh giá mã nguồn và cung cấp phản hồi mang tính xây dựng cho các thành viên trong nhóm.\n\nKhả Năng Teamwork Với Team\n\n- Làm việc với các quản lý sản phẩm để xác định phạm vi dự án, tiến độ và sản phẩm bàn giao.\n- Làm việc chặt chẽ với GD, Artist, Anim, Sound để đảm bảo tích hợp mượt mà các yếu tố thiết kế, đồ họa tạo ra game hoàn chỉnh.\n- Đưa ra yêu cầu rõ ràng trong quá trình thiết kế trò chơi ví dụ: Yêu cầu về đồ hoạ, animation, dữ liệu tham ra tư vấn hoặc xây dựng giải pháp điều chỉnh nếu quá trình phát triển có vấn đề phát sinh.\n- Cung cấp sản phẩm test đúng theo cam kết của từng giai đoạn phục vụ quá trình kiểm thử, nhận xét sản phẩm 1 cách nhanh nhất có thể.\n\nCập Nhật Và Bảo Trì\n\n- Cập nhật nội dung mới, sửa lỗi định kỳ và cải thiện trải nghiệm người dùng.\n- Bàn giao sản phẩm cho người mới, chuẩn hoá quá trình sản xuất.\n\nYêu cầu công việc\n\nTrình độ học vấn: Bằng cấp liên quan đến Computer Science hoặc các lĩnh vực tương tự (hoặc kinh nghiệm thực tế tương đương).\n\nTrình Độ Chuyên Môn\n\n- Kinh nghiệm sâu rộng với Cocos2d-x framework và Lua Scripting.\n- Kinh nghiệm đã được chứng minh trong việc phát triển và phát hành các trò chơi di động trên nền tảng iOS và Android.\n- Có kinh nghiệm làm việc với game Multiplayer hoặc mong muốn làm việc với game Multiplayer là 1 lợi thế.\n- Kinh nghiệm phát triển ứng dụng di động native (Objective-C/Swift cho iOS, Java/Kotlin cho Android) là 1 lợi thế.\n\nKiến Thức Cần Thiết\n\n- Kiến thức phát triển cho nhiều nền tảng gồm IOS/ Android và Html5.\n- Khả năng tối ưu hóa hiệu suất game cho các nền tảng khác nhau gồm IOS /Android và Html5.\n- Có kinh nghiệm làm game multiplayer hoặc định hướng phát triển game có yếu tố multiplayer dạng MMORG.\n- Hiểu biết về các phương pháp phát triển linh hoạt (Agile /Scrum) để tăng cường sự hợp tác và hiệu quả trong nhóm.\n\nKỹ Năng Cần Thiết\n\n- Khả năng sử dụng thành thạo C++, Lua và cocos2d-x, luồng làm việc rõ ràng, hiệu quả để dễ maintain và quản lý.\n- Khả năng nhanh chóng xác định và giải quyết vấn đề về kỹ thuật phức tạp.\n- Biết sắp xếp ưu tiên trong công việc để đảm bảo tiến độ. Nắm được công việc của các bộ phận khác, đưa ra tư vấn, yêu cầu rõ ràng để đảm bảo chuyển giao công việc giữa các bộ phận hợp lý (Level Middle/Senior).\n- Kỹ năng giao tiếp truyền đạt thông tin.\n- Khả năng làm việc nhóm tốt, chủ động, quyết đoán trong công việc.\n- Khả năng sáng tạo, linh hoạt xử lý các thách thức trong quá trình phát triển game.\n- Đam mê với công nghệ và việc phát triển game. Luôn sẵn sàng học hỏi công nghệ mới để áp dụng vào sản phẩm.\n- Phối hợp với các bộ phận khác để xử lý công việc.\n\nTại sao bạn yêu thích làm việc tại đây\n\nPhúc lợi tài chính minh bạch và toàn diện\n\n- Chính sách xét điều chỉnh tăng lương 6 tháng/lần (Đánh giá theo hiệu suất, kết quả công việc và năng lực).\n- Ghi nhận sự đóng góp thông qua các khoản thưởng phong phú, hấp dẫn góp phần gia tăng thu nhập của nhân viên: Thưởng các ngày lễ 30/4-01/05, 02/09, Tết dương lịch, thưởng dự án, thưởng KPI, hiệu suất công việc hàng tháng, thưởng quý và lương tháng 13.\n- Được hưởng các mức Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n- Gói chăm sóc sức khỏe định kỳ hằng năm tại các Bệnh viện Đại học Y Hà Nội và Saigon Healthcare.\n\nChú trọng phát triển năng lực mỗi cá nhân\n\n- Chính sách hỗ trợ khuyến khích học tập, khen thưởng dành cho nhân viên đạt chứng chỉ đào tạo.\n- Được đào tạo và phát triển theo khung năng lực và lộ trình nghề nghiệp của từng vị trí thông qua các khóa đào tạo miễn phí trên hệ thống đào tạo trực tuyến E-learning Appota, các khoá học hàng đầu của Coursera, Udemy.\n- Được tham gia các Workshop, Master talk, CEO talk chia sẻ kiến thức và kinh nghiệm từ các chuyên gia trong và ngoài Công ty.\n- Có lộ trình thăng tiến rõ ràng. Chính sách luân chuyển công việc linh hoạt và cởi mở nhằm thúc đẩy nhân viên khám phá sức mạnh tiềm năng của bản thân và thử thách với những cơ hội mới.\n\nVăn hóa làm việc độc đáo\n\n- Tại Appota, mỗi nhân viên sẽ được làm việc mình thích, thích việc mình làm với văn hóa "No Boss Just Leader" cùng 7 giá trị cốt lõi IAPPOTA.\n- Mỗi cá nhân được trao quyền chủ động trong mọi việc, phát huy các thế mạnh, phá bỏ khuôn mẫu và sáng tạo theo phong cách riêng.\n- Được dẫn dắt, định hướng bởi định hướng bởi đội ngũ BOD có tầm với kim chỉ nam tập trung vào phát triển giá trị con người và tinh thần startup mạnh mẽ.\n- Môi trường trẻ trung, năng động và sáng tạo, nơi mọi ý tưởng táo bạo được đón nhận.\n\nTrải nghiệm sự chăm sóc tinh thần tận tâm và chu đáo\n\n- Được chăm sóc tỉ mỉ từ những bữa ăn sáng, ăn chiều miễn phí với chi phí 2.000.000/người/tháng và tận hưởng không gian cafe hiện đại dành riêng cho nhân viên.\n- Được trải nghiệm các hoạt động gắn kết đa dạng: Các hoạt động team building, chương trình Friday Frenzy, Đại tiệc sinh nhật công ty kết hợp du lịch hàng năm lên tới 10.000.000/người/năm, hội Chợ Tết độc lạ và các hoạt động thể thao thường niên khác.\n- Được thỏa sức tham gia các câu lạc bộ đa sắc màu: CLB Yoga, Bóng đá, Game Esports, Cầu lông, Zumba.\n\nThời Gian Làm Việc\n\n- Từ 8h30 - 18h00 từ thứ 2 đến thứ 6.\n- Từ 8h30 - 16h00 thứ 7 (Mỗi tháng đi làm 2 thứ 7).\n\nĐịa Điểm Làm Việc\n\n- Tòa LE Building, Số 11, Ngõ 71, Phố Láng Hạ, Phường Thành Công, Quận Ba Đình, Thành phố Hà Nội, Việt Nam.\n\nKhám Phá Văn Hoá Appota Tại\n\n- Website: Appota.com\n- Fanpage: https://www.facebook.com/appotacareers\n- Tiktok: https://www.tiktok.com/@appotagroup\n- Youtube: https://www.youtube.com/@Appota\n\nỨng viên quan tâm gửi CV về phòng Nhân sự:\n\n- Email: tuyendung@appota.com\n- Phone: 024 3519 1616\n- Địa chỉ: Tòa nhà LE Building, số 11 ngõ 71 Láng Hạ, Ba Đình, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1374, 816, 2, 'Human resource staff', 'Mô tả công việc\n\n• Tìm hiểu và lập các cơ sở dữ liệu ứng viên (Node JS, Java, Android, iOS, BA,....) dựa trên kế hoạch tuyển dụng thông qua các kênh khác nhau như: websites, diễn đàn, hội thảo việc làm...\n• Lưu trữ, cập nhật và quản lý thông tin ứng viên\n• Xét lọc hồ sơ ứng viên, liên hệ và sắp xếp các buổi phỏng vấn.\n• Xây dựng, triển khai và xúc tiến công tác truyền thông nhằm quảng bá thương hiệu; cùng một số hoạt động khác thúc đẩy động lực làm việc cho nhân viên\n• Các công việc khác về nhân sự bao gồm: theo dõi sự thay đổi nguồn nhân lực, làm hợp đồng thử việc, hợp đồng lao động và những công việc liên quan hành chính tổng hợp.\n• Tổ chức các sự kiện và hoạt động của Công ty.\n• Các công việc được chỉ định khác.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1375, 817, 2, 'React Developer', 'We’re seeking an experienced Senior React Developer to join our team and take a leading role in building and maintaining high-quality web applications. This role requires a strong grasp of modern JavaScript (ES6+), the React ecosystem, and software design principles. You will be responsible for writing clean, scalable, and efficient code while ensuring optimal performance and a seamless user experience.\n\nDesign, build, and maintain scalable front-end architecture using React.js and modern JavaScript.\nApply SOLID principles and best practices to ensure code quality, maintainability, and extensibility.\nWrite clean, maintainable, and scalable code with a strong emphasis on quality and performance.\nCollaborate closely with backend engineers to integrate RESTful APIs efficiently and securely.\nTroubleshoot, debug, and resolve front-end issues across different browsers and devices.\n\nIdeal candidates will have excellent experience in one or more of the technologies listed below:\n\n5+ years’ experience with React with OOP, JavaScript (ES5 & 6), TypeScript\nWorked with the popular libraries: React Query, Zod, Zustand/Mobx, Redux-Saga, React Router Dom, axios, Clsx, and date-fns.\nNice to have LaunchDarkly, React Query Dev Tools, React Query Persist Client, and NX.\nNice to have Tailwind CSS, Drag & Drop Kit, and SignalR Client.\nStrong knowledge of RESTful API, Chart, Notification, such as Firebase, Google Maps.\nExperience with React Native and React Native libraries (React-navigation, Expo) is a plus.\nKnow how to write Unit tests.\nExperience in team development using Git and CICD for mobile.\nUnderstand the standards of the process of building and deploying software.\nAbility to work under pressure.\nExperience developing web applications is a big plus.\nEnglish communication with clients.\n\nWorkplace:  Ha Noi, Da Nang.\n\nBenefits and Incentives:\n\nCompetitive Salary: Attractive and highly competitive salary packages.\nHealthcare: Premium healthcare insurance with annual check-ups at top-tier hospitals.\nPerformance Bonuses: Annual performance reviews with substantial bonuses and salary increases.\nOnsite Opportunities: Opportunities to work onsite in Silicon Valley and other locations.\nAdditional Salary: 13th-month salary bonus.\nHoliday Bonuses: Bonuses for Vietnamese public holidays, special holidays, and personal occasions (e.g., birthdays, newborn baby, marriage, bereavement, sickness).\nOvertime Compensation: Payment for overtime work.\nRemote Work: Work-from-home policy with 30 days per year.\nTech Support: Personal laptop and monitor support.\nCompany Events: Exciting company trips, team-building activities, New Year parties, sports activities, and monthly birthday celebrations with finger food.\nReferral Bonus: Incentives for successful employee referrals.\nPaid Leave: 12 days of fully paid annual leave.\nCollaborative Environment: Work in a collaborative, innovative, and supportive environment to make an impact in the security industry.\nLanguage Skills: Opportunities to speak English with clients.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1376, 808, 2, 'Junior AI Software Developer', 'Key Responsibilities\n\nDevelop and maintain backend systems using C#/.NET Core Framework.\nBuild responsive, user-friendly interfaces with ReactJS.\nWrite clean, maintainable code and assist in debugging and testing.\nCollaborate with cross-functional teams to integrate AI/ML models into applications.\nFollow best practices in full-stack development and maintain technical documentation.\nRegularly report progress and challenges to the team.\n\nRequired Skills And Qualifications\n\nBachelor’s degree in Computer Science, Software Engineering, or a related field (or equivalent practical experience).\nKnowledge of object-oriented programming and .NET (C#)\nBasic knowledge of ReactJS and component-based front-end development.\nUnderstanding of web development basics, including HTML, CSS, and JavaScript.\nFamiliarity with RESTful APIs and data handling.\nGood learning and research abilities\nHaving a sense of responsibility, persistence\nAble to work independently and in a team.\n\nPreferred Skills\n\nExposure to AI/ML technologies and a strong interest in AI integration.\nKnowledge of SQL or NoSQL databases.\nProficiency in version control systems like Git.\nEagerness to learn and adapt to emerging technologies and methodologies.\nProficiency in English with strong listening, speaking, and writing skills.\n\nWORK LOCATION\n\n2F Vinh Trung Plaza, No. 255-257 Hung Vuong, Vinh Trung, Thanh Khe, Da Nang\n\nBenefits\n\n5-day workweek with weekends off\nDynamic, professional environment with career growth opportunities\nSocial, medical, and unemployment insurance based on actual salary\nPerformance and salary review twice a year\nQuarterly bonus opportunities based on performance\nPotential for international onsite assignments\nRegular team-building events and internal activities (weekly happy hour, quarterly team building events, Lunar New Year parties, etc.)\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1377, 366, 2, 'Frontend Engineer (ReactJS/Wordpress) - GSaaS', 'About NAVER Corp and NAVER Vietnam:\nNAVER Corp\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\nNAVER Vietnam\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\nLearn more about us: https://navercorp.vn/\n\nWe are looking for a Frontend Engineer for GSaaS project.\nYour daily tasks:\n- Develop Frontend part of various SaaS services such as WORKS, SasS.\n- Take a look at NAVER WORKS services HERE.\n\nYour background:\n- 4+ years of work experience on Frontend; OR 4+ years of work experience in WordPress Front-end development (experience with Elementor is a plus);\n- Bachelor\'s degree or above in Computer Science or related field;\n- Proficient understanding of JavaScript, and programming experience with ES5/ES6;\n- Extensive programming experience in HTML5, CSS3, SASS or LESS;\n- Experts in React, its ecosystem and history. Ideally, experience with Redux, MobX;\n- Should have knowledge of Immutable Datastructures;\n- Ability to write testable code and write units using tools such as Jest, Sinon, and Enzyme;\n- Gulp and Webpack preferred Familiarity;\n- Understand the importance of writing high Maintainable Code, Clean Code;\n- Proficient understanding of Git (Experienced in merging, branching source code);\n- Open-minded, honest and have a positive attitude towards people;\n- Good at communication skills in general and English skills in particular.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミンシティ都市圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1378, 818, 2, 'Java Developer', 'TECHVIFY Corporation is an End to End AI-Powered Digital Transformation Partner.\nAt TECHVIFY, we don’t just build software.\nWe engineer breakthroughs.\nWe innovate with AI, craft with code, and scale with cloud.\nWe partner with startups, enterprises, and even competitors on a shared mission:\nTo turn bold ideas into real-world impact.\nIf you’re looking to lead digital transformation through intelligent software, we’re ready to build with you.\nLet’s create the future – together.\n\nResponsibilities\n- Collaborate with solution architects and product owners to refine technical requirements and translate them into solid system designs.\n- Write clean, efficient, and well-documented Java code, following best practices, design principles, and code standards.\n- Develop and maintain backend systems using Java (Java 8+), Spring Boot, Hibernate, and modern Java frameworks.\n- Build robust RESTful APIs and ensure seamless integration with front-end applications and third-party services.\n- Conduct thorough code reviews, mentor junior developers, and promote knowledge sharing within the team.\n- Debug complex issues and provide reliable, long-term solutions.\n- Continuously optimize system performance, scalability, and security.\n- Participate in all stages of the software development lifecycle: planning, design, development, testing, deployment, and maintenance.\n- Take part in Agile processes (Scrum/Kanban), including sprint planning, daily stand-ups, and retrospectives.\n\nRequirements\nMust have\n- Bachelor’s degree in Computer Science, Software Engineering, or related fields.\n- Minimum 5 years of Java backend development experience, including 2+ years at senior level.\n- Proficiency in Java 8+, Spring Boot, and Hibernate/JPA.\n- Experience building and integrating RESTful APIs and microservices.\n- Strong grasp of OOP, design patterns, and clean coding practices.\n- Solid SQL skills with relational databases (e.g., PostgreSQL, MySQL); familiarity with NoSQL is a plus.\n- Proficient in version control tools like Git, and experience with CI/CD pipelines.\n- Strong communication skills and the ability to work in a collaborative Agile environment.\n- Fluent in English (written and spoken).\n\nNice to have\n- Experience with Docker, Kubernetes, or similar container tools.\n- Exposure to cloud platforms (AWS, Azure, GCP).\n- Knowledge of message brokers like Kafka, RabbitMQ.\n- Certifications in Java or related technologies (OCP, OCM).\n- Familiarity with front-end technologies (React, Angular) is a plus.\n\nCore Competencies\n- System Design Thinking: Ability to architect scalable, maintainable backend systems and microservices with long-term extensibility in mind.\n- Performance Tuning & JVM Mastery: Deep knowledge of JVM internals, garbage collection, memory management, and performance optimization.\n- Clean Code Advocate: Commitment to writing modular, testable, and maintainable code following SOLID principles and industry best practices.\n- Leadership & Mentorship: Proven ability to guide junior developers through code reviews, technical coaching, and shared ownership of code quality.\n- Business-Driven Development: Strong product mindset with the ability to translate business problems into practical and impactful software solutions.\n\nBenefits\n- Salary: Up to 40M\n- Join a global team and work directly with many talents around the world.\n- Opportunities for onsite work in Japan, Singapore, Australia, and many other countries.\n- Work and grow in a dynamic, creative, and professional environment.\n- Healthcare: Premium Health Insurance TECHVIFY Care\n- 13 months’ salary per year.\n- Annual salary evaluation.\n- Sponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.\n\nHow to apply\nIf you are a driven and talented Senior Java Developer looking for an opportunity to be part of something extraordinary, please submit your resume and cover letter for consideration.\nJoin our team and let’s create amazing things together! Send your updated CV to this email address:\n- Email: careers@techvify.com.vn\n- About us: https://techvify-software.com/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1379, 819, 2, 'Junior/Middle Software Engineer', 'Position: Junior/Middle Software Engineer\nLocation: Le Van Luong, Thanh Xuan, Hanoi\nSalary: Up to USD 2,500 gross/month + 13th-month salary\nWork Setup: Hybrid (Work from home every Friday)\nCompany Type: Global technology company with international presence\n\nAbout the Role\nJoin a dynamic team that’s on a mission to help enterprises unlock the full potential of data and AI. Our platform enables both technical and non-technical users to create secure, reusable, and compliant data solutions at scale. Recognized by industry analysts and backed by leading investors, we are rapidly growing and evolving our core product into a modern, AI-powered cloud solution.\n\nWe value a high-performing culture built on collaboration, integrity, and continuous learning. Our team is spread globally and united by shared values:\n- Aim High\n- Customer First\n- One Team\n- Candid & Caring\n- Challenge with Fun\n\nThe Opportunity\nOur engineering team is driving a major transformation — migrating from a traditional on-premise model to a fully managed multi-cloud SaaS platform. The goal is to serve some of the world’s largest enterprises with a scalable, secure, and intuitive data management experience.\n\nAs a Software Engineer, you will contribute to this transformation by building, improving, and scaling our cloud-based enterprise web applications.\n\nYour Responsibilities\n- Build a robust and scalable cloud-native web application with self-service capabilities.\n- Improve and modernize the architecture of our SaaS platform, enhancing performance, security, and deployment efficiency.\n- Collaborate with feature teams to meet enterprise-grade SLAs and security standards.\n- Design user-friendly, impactful features that help enterprise clients manage their data more effectively.\n- Support the gradual decoupling of monolithic components into microservices for faster, independent delivery.\n- Take ownership of the full development cycle — from design to production.\n\nWhat You’ll Work On\n- Design systems that handle high volumes of data across cloud environments and various data sources.\n- Contribute to architectural discussions with a focus on scalability, modularity, and quality.\n- Write clean, testable, and maintainable code using best practices.\n- Deploy and operate your code in modern cloud environments.\n- Bring knowledge of multi-tenant architectures, distributed systems, and messaging technologies like RabbitMQ.\n\nPreferred Tech Stack\n- Languages & Frameworks: Java, Spring Boot, Kotlin, Python, .NET, GraphQL\n- Cloud & Infrastructure: AWS, Azure, Kubernetes, Helm, GitLab CI/CD\n- Databases: Aurora, PostgreSQL, Elasticsearch, Minio\n- Frontend: TypeScript, React/Vue, Apollo, MobX, Nx\n- Big Data: Spark, Redshift, Snowflake\n\nIdeal Candidate Profile\n- Enjoys solving complex problems and optimizing system performance.\n- Has a keen interest in cloud security and SaaS development.\n- Open to learning and mentoring within the team.\n- Comfortable with end-to-end ownership, including deployment and operational excellence.\n- Strong sense of responsibility and proactivity in a collaborative team setting.\n\nWork Equipment\n- Laptop provided\n\nBenefits & Perks\n- Full salary during probation\n- 13th-month salary\n- 15 days of paid annual leave\n- Full coverage for social and health insurance (maximized)\n- Premium healthcare plan\n- Company-sponsored English classes\n- Access to leading industry conferences\n- Online learning (Udemy and more)\n- Monthly team dinners', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Wilayah Ibu Kota Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1380, 487, 2, 'Back End Developer (Java)', 'KEY RESPONSIBILITIES:\n- Design, implement, test and maintain application software \n- To take part in software and architectural development activities\n- Contribute in all phases of the development lifecycle\n- Conduct software analysis, programming, testing and debugging, deployment\n\nREQUIREMENTS:\n- BS/MS degree in Computer Science, Engineering or a related subject \n- Good experience (minimum 3 years) with Java programming language: Object Oriented analysis, design and develop using common design patterns.\n- Have experience in Webserver (Tomcat, Nginx), DB migration (Flyway,…), API documentation (Swagger, Apiary)  \n- Familiarity with Docker, Kubernetes and Microservices  \n- Familiarity with Scrum/Agile methodology\n- Strong knowledge about CI/CD pipeline\n- Experience with test-driven development\n\nCOMPENSATIONS & BENEFITS:\n- 13th Salary Fixed and KPI Bonus.\n- Premium Health Care for personal.\n- 24/7 Accidental Insurance.\n- 100% Social Insurance.\n- Meal + Phone Allowance.\n- Yearly Medical Checkup.\n- 15 Annual Leaves.\n- Professional and Transparent Working Environment.\n- Apply The Latest Financial Technology in the World.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1381, 820, 2, 'Junior AI Engineer', 'MÔ TẢ CÔNG VIỆC\n\nPhát Triển Ứng Dụng AI-NLP\n\nXây dựng lõi xử lý ngôn ngữ áp dụng công nghệ AI với các thành viên khác trong team.\n\nPhát triển triển ứng dụng AI Chatbot cho đa lĩnh vực\n\nPhát Triển Ứng Dụng AI-Computer Vision\n\nPhát triển ứng dụng AI Computer Vision cho nhận diện khuôn mặt, phân tích biểu cảm, cảm xúc.\n\nPhát triển ứng dụng AI Computer Vision cho nhận diện các hành động của con người trong các bài toán về bán lẻ, xây dựng.\n\nYÊU CẦU\n\nCó kinh nghiệm với các kỹ thuật của Trí tuệ nhân tạo như: học máy giám sát, học máy không giám sát, học máy củng cố và lĩnh vực AI khác như xử lý ngôn ngữ tự nhiên, hệ thống khuyến nghị, học sâu và tương tác giữa con người và máy tính\n\nCó kinh nghiệm về xử lý dữ liệu, xử lý ảnh\n\nYêu Cầu Kĩ Năng\n\nCó kinh nghiệm làm việc với các bộ công cụ AI như: Tensoflow; Keras; Scikit; DL4J; …\n\nThành thạo các ngôn ngữ lập trình OOP và có kỹ năng phát triển prototype bằng các ngôn ngữ này (e.g. Python, Java, R, C++, etc.)\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 30 tháng 6, 2025\n\nChi tiết công việc\n\nSố Lượng\n\n2\n\nĐịa Điểm\n\nHà Nội\n\nKinh Nghiệm\n\n2 năm\n\nTrình Độ\n\nJunior\n\nHình Thức\n\nBán thời gian\n\nKỹ Năng\n\nAI', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1382, 776, 2, 'Senior Frontend Developer (ReactJS/Next.js, Product Development)', 'LOGIX TECHNOLOGY is a distinguished software services company, specializing in the provision of professional software development services, fostering strong partnerships through the establishment of offshore development centers, offshore product development, and software testing with an infrastructure-oriented approach. We excel at simplifying and enhancing offshore outsourcing, not only by delivering innovative solutions to meet our clients’ exact requirements through high-performance teams but also by significantly contributing to our clients’ success by reducing time-to-market and improving quality.\n\nAt LOGIX TECHNOLOGY, we are committed to delivering the highest level of professional excellence and making a significant impact in the software development sector. If you are a dedicated professional looking to join a dynamic team working with global leaders, we encourage you to explore the exciting opportunities that await you with us.\n\nJob Description\n\n- Design, develop, and maintain high-quality, scalable frontend code for core products.\n- Build responsive, accessible, and performant UI components following modern best practices.\n- Collaborate with Product Owners, Business Analysts, and UX/UI designers to translate requirements into seamless user experiences.\n- Integrate frontend applications with backend APIs, ensuring efficient and reliable data handling.\n- Optimize application performance, accessibility, security, and SEO as appropriate.\n- Contribute to architectural decisions, recommending improvements for scalability and maintainability.\n- Actively participate in Agile ceremonies, including sprint planning, reviews, and retrospectives.\n- Mentor junior developers and advocate for best practices in coding, testing, and documentation.\n\nRequired Skills & Experience\n\n- 4+ years of professional software development experience.\n- Proven expertise as a ReactJS developer with strong proficiency in JavaScript/TypeScript (ES6+).\n- Solid understanding of RESTful API integration.\n- Proficient in HTML5, CSS3, responsive design, accessibility standards, SEO, and web security best practices.\n- Experience with SSR/SSG frameworks, particularly Next.js (strong Next.js knowledge is a plus).\n- Familiarity with modern React data-fetching libraries such as React Query or SWR.\n- Experience working with utility-first CSS frameworks like Tailwind CSS and CSS Modules.\n- Comfortable with modern frontend build tools and version control, including Git, Webpack, Gulp, and NPM.\n- Knowledge of frontend testing frameworks and tools such as Jest, React Testing Library, MSW, and Faker.\n- Proficient English communication and writing.\n- Strong analytical and problem-solving skills.\n- Familiarity with clean code principles, SOLID design principles, and common design patterns.\n- Experience working in Agile/Scrum development environments.\n\nBenefits And Perks\n\n- Attractive Salary & Benefits, full salary in probation.\n- Performance appraisal twice a year, 13th-month salary.\n- Healthcare and incident insurance.\n- 16 Paid Leave days / year (12 Annual Leave, 02 Summer Leave ,01 Birthday Leave & 01 Christmas Leave).\n- Company trip, annual year-end party, team building activities.\n- Diverse careers opportunities with Software Services, Software Product Development.\n- Working and growing in a value-driven, international working environment and standard Agile culture with passionate and talented teams.\n- Various training on hot-trend technologies, best practices, and soft skills.\n- Free in-house entertainment facilities: football, table football, PS, badminton, trekking…coffee, and snacks (instant noodles, cookies, candies…)\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1383, 821, 2, 'Nhân viên triển khai phần mềm', 'Mô tả công việc\n\n• Cài đặt, hướng dẫn, hỗ trợ khách hàng sử dụng phần mềm.\n• Tiếp nhận yêu cầu của khách hàng.\n• Test chương trình phần mềm theo dự án\n• Trợ giúp khách hàng các nghiệp vụ phần mềm\n• Khảo sát, tiếp nhận và triển khai, nghiệm thu dự án\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1384, 822, 2, 'Senior Frontend Engineer (HTML/CSS/JS and React/Vue)', 'Senior Frontend Engineer (HTML/CSS/JS and React/Vue)\n\nUrgent\n\nHo Chi Minh\n\nTech/Engineer\n\nResponsibilities\n\n- Develop and maintain performant web applications with HTML/CSS/JS\n- Build reusable UI components and optimize applications for speed and scalability\n- Work with UX/UI designers to implement designs\n- Engage in Agile development, including planning and deployment\n- Debug and improve application performance\n- Write tests and maintain code quality\n- Help maintain technical documentation\n\nRequirements\n\nMust-have:\n- 4+ years of experience in web development (FE side).\n- Proficiency in JavaScript/Typescript, HTML, and CSS.\n- Familiarity with RESTful APIs and backend integration.\n- Experience with Git and Agile software development.\n- Strong sense of ownership.\n- Proactive and strong communication skills in English.\n\nNice-to-have:\n- Experience in designing and maintaining UI components.\n- Experience with ReactJS or VueJS.\n- Experience with Google Analysis.\n\nOur benefits\n\nCaring Mental & Physical Recreation\n\n- Hybrid working: 2 days at the office and 3 days WFH\n- Working hour: Flexible start 8AM-9AM from Mon-Fri\n- Full salary in probation\n- Insurance: Applied from Probation period:\n- Social Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\n- Private health insurance & accident insurance. From Managing level: extra for family members\n- Bonus: 13th month salary\n- 16 - 24 paid days off and more\n- Paternity leave: Extra 5 days\n- Annual company trip; Quarterly team building\n- Billiards & Running club\n- Annual health check\n- Well-equipped facility: Macbook pro, additional monitor..\n\nCaring Career & Development\n\n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- External & internal training courses\n- Soft-skill workshops\n- Tech seminars\n- Monthly and biannual Recognition Awards\n- Performance & salary review: twice/year (Jun & Dec)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1385, 823, 2, 'Technical Developer, Soft Goods', 'About us: Stanley - Built for Life® since 1913.\n\nStanley 1913 has fueled the human experience since the iconic Stanley vacuum bottle revolutionized the way people enjoyed food and beverage. Today, our colorful and thoughtfully designed products including the popular QuencherTM series go beyond function, elevating everyday moments with style and empowering active lifestyles. We’re a community of creators, builders and inventors who believe in creating sustainable products for a better life and world that minimize our impact on the planet. Learn more at www.stanley1913.com.\n\nWhat You\'ll Do\n\n- Partner closely with Stanley design and product development teams on existing and new projects. Provide input from engineering aspect to guide the product teams on construction and raw material choices.\n- Partner closely with Stanley Quality team and together lead critical milestone events such as Pre-Production runs, Pilot runs, Test Orders and similar. Identify weaknesses and trouble shoot solutions.\n- Partner closely with Stanley sourcing team to engage and train the manufacturing partners on industry best engineering practices for Soft Goods.\n- Collaborate closely with manufacturing partners ensuring optimization of the welding and sewing lines.\n- Attend regular meetings with cross functional teams and be able to provide updates, relay actions and improvements made, and point out risks and plans to offset.\n\nWho You Are\n\n- Engineering background with experience in textile cut and sew and RF welded soft goods.\n- Working knowledge of Six sigma methodology preferred.\n- Expert with Adobe Illustrator, 3D Modeling Preferred, and other professional software.\n- Excellent communication skills - written, spoken, listening.\n- Out of the box thinker, yet analytical and with a bias for process.\n- Strong planning & implementation skills, adherence to timelines a must.\n- Ability to influence to gain the best outcome for Stanley products.\n- Respond effectively to sensitive inquiries or complaints and maintain the confidentiality of sensitive information.\n\nEducation And Experience\n\n- Bachelor\'s degree or above, major in Engineering Discipline, preferred.\n- 8+ years of experience in soft goods engineering for a consumer goods brand with global reach.\n- Solid experience of technical writing, documentation and presentation\n- Confidence working with, and presenting to internal and external clients\n- Direct experience communicating directly with factories\n- Travel 30%~50%\n\nStanley is committed to a diverse and inclusive work environment. Stanley is an equal opportunity employer and does not discriminate based on race, national origin, gender, gender identity, sexual orientation, protected veteran status, disability, age, or other legally protected status. For individuals with disabilities who would like to request an accommodation, please reach out to recruiting@stanley1913.com.\n\nStanley is a total rewards company, which includes rewards beyond base salary. At Stanley, full-time employees are eligible for an annual bonus, based on company and individual results. In addition, we offer a variety of employee benefits, personalized time off, 14-Paid holidays, dental, vision, 401(k), and much more.\n\nAbout our parent company: Morgan Street Holdings\n\nStanley 1913 is part of Morgan Street Holdings (formerly HAVI), a privately owned enterprise with a diverse portfolio of operating companies. These include HAVI Supply Chain, tms, Stanley 1913, and Continental, which provide best-in-class sourcing and supply chain capabilities, brand-defining marketing and promotion services, innovative consumer products, and dining and refreshment food solutions. Morgan Street Holdings employs over 10,000 people and serves 300+ customers across the globe.\n\nMorgan Street Holdings supports Stanley 1913 with competitive pay and benefits, along with exposure to diverse industries and professional networking and development opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1386, 824, 2, 'CHUYÊN VIÊN CAO CẤP LẬP TRÌNH (JAVA, SPRING)', 'Bộ phận: Đổi mới Sáng tạo – Công nghệ (User Innovation)\n\nBáo cáo: Giám đốc Công nghệ\n\nCông Việc Chính\n- Tối ưu hóa và đảm bảo tính nhất quán và hiệu suất trên toàn hệ thống\n- Hợp tác với các thành viên khác để thiết kế, phát triển và triển khai các tính năng mới\n- Tối ưu hóa hệ thống để đảm bảo độ tin cậy và hiệu suất\n- Sửa lỗi và cải thiện hệ thống\n- Viết Unit test để ngăn ngừa các lỗi tương tự\n- Chịu trách nhiệm giải quyết lỗi nhanh nhất có thể\n- Cung cấp phương pháp và số liệu để giám sát hệ thống\n- Đóng góp kiến thức cho đội ngũ kỹ thuật\n- Đánh giá và review code với các thành viên trong nhóm.\n\nYêu Cầu\n- Bằng cử nhân ngành Khoa học Máy tính hoặc Kỹ thuật Phần mềm\n- Ít nhất 4 năm kinh nghiệm với ngôn ngữ lập trình Java (Spring, Springboot, Hibernate, jpa, v.v.)\n- Có kinh nghiệm trong lĩnh vực Trading/Dịch vụ Tài chính/Ngân hàng là một lợi thế lớn\n- Hiểu biết và có kiến thức tốt về Lập trình OOP, cấu trúc dữ liệu, các mẫu thiết kế và giải quyết vấn đề\n- Kinh nghiệm xây dựng RESTFUL/JSON API \n- Quen thuộc với kiến trúc Microservices\n- Có kinh nghiệm với RDBMS (PostgreSQL, MySQL, Oracle là một lợi thế, v.v.) \n- Có kinh nghiệm với NoSQL (MongoDB, couchbase là một lợi thế, v.v.)\n- Kiến thức về caching data (in-memory caching, Redis, v.v.)\n- Quen thuộc với Kafka\n- Hiểu biết về các dịch vụ cơ bản trong môi trường Cloud (pub/sub, máy ảo, docker, Kubernetes, v.v.)\n- Quen thuộc với phương pháp Agile/Scrum là một lợi thế\n- Kỹ năng giao tiếp và làm việc nhóm tốt\n- Quan tâm đến việc học hỏi những điều mới trong công việc\n- Nên có: Kiến thức về cloud (GCP, AWS, v.v.); CI/CD; Event store and stream-processing platform; Big-data or large-scale systems\n\nQuyền Lợi\n- Thời gian làm việc 5 ngày/tuần (Thứ Hai đến Thứ Sáu)\n- Cơ hội thăng tiến, phát triển nghề nghiệp công bằng\n- Thu nhập cạnh tranh\n- Chính sách Thưởng của Công ty\n- Chế độ BHXH, BHYT, BHTN theo quy định của Bộ luật Lao động và Bảo hiểm sức khỏe cao cấp PVI theo quy định của Công ty\n- Được hưởng 11 ngày nghỉ Lễ Tết theo quy định của Bộ luật Lao Động, 15-20 ngày phép năm theo quy định của Công ty, và thêm 1 ngày phép cho 5 năm làm việc\n- Được tham gia hoạt động du lịch nghỉ dưỡng hàng năm\n- Được tham gia các hoạt động khác của Công ty: Thể thao, Ngày hội gia đình, Ngày hội thiếu nhi\n- Chương trình tài trợ đào tạo: Chứng chỉ chứng khoán, kỹ năng mềm, kỹ năng chuyên môn\n- Môi trường làm việc chuyên nghiệp và năng động.\n\nNơi Làm Việc\n- Công ty Cổ phần Chứng khoán Vietcap\n- Tầng 19, Tòa nhà Bitexco, số 2 Hải Triều, Quận 1, HCM\n- Email ứng tuyển: job@vietcap.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1387, 397, 2, 'Middle/ Senior Software Engineer (Java)', '1. MỤC TIÊU CÔNG VIỆC: Thiết kế và phát triển các ứng dụng Java hiệu suất cao cho hệ thống LOS/CRM, đóng góp vào toàn bộ vòng đời phát triển phần mềm và cung cấp các giải pháp phần mềm có thể mở rộng và chất lượng cao.\n\nNHIỆM VỤ, TRÁCH NHIỆM CHÍNH:\n- Cộng tác với các đơn vị nghiệp vụ, bao gồm kiến trúc sư phần mềm, quản lý sản phẩm, các đơn vị kinh doanh, thiết kế để phát triển các ứng dụng Java.\n- Thiết kế và triển khai ứng dụng bằng ngôn ngữ Java hiệu quả và đáng tin cậy, đảm bảo hiệu suất và bảo mật.\n- Thực hiện đánh giá mã nguồn để duy trì chất lượng và tuân theo các tiêu chuẩn mã hóa.\n- Gỡ lỗi, khắc phục sự cố và giải quyết các nhược điểm và sự cố phần mềm, đảm bảo độ tin cậy của ứng dụng.\n- Tham gia phân tích yêu cầu và thảo luận thiết kế phần mềm để đề xuất các giải pháp sáng tạo.\n- Phát triển và duy trì tài liệu kỹ thuật để tham khảo và báo cáo.\n- Cập nhật thông tin về xu hướng công nghệ liên quan đến Java, các cách thực hành tốt nhất và tiêu chuẩn ngành.\n- Xác định tầm nhìn kỹ thuật cho việc phát triển phần mềm, phù hợp với mục tiêu kinh doanh và thực tiễn tốt nhất của ngành.\n- Cộng tác với các nhà phát triển khác để xây dựng các giải pháp phần mềm có thể mở rộng và hiệu quả.\n- Góp phần vào toàn bộ vòng đời phát triển phần mềm, từ khái niệm và thiết kế đến thử nghiệm, triển khai và hỗ trợ.\n\n*** LÝ DO ĐỒNG HÀNH CÙNG SHBFINANCE:\n- Môi trường làm việc chuyên nghiệp, cởi mở\n- Thời gian làm việc từ thứ 2 – thứ 6, nghỉ trưa 1h30’ (40h/tuần)\n- Chế độ làm việc Hybrid working từ 1 - 2 ngày làm việc từ xa/ tuần.\n- Đồng nghiệp thân thiện, cởi mở với tư duy đề cao sự phát triển của mỗi cá nhân;\n- Văn phòng làm việc với không gian mở, rộng rãi, được cung cấp đầy đủ các trang thiết bị để phục vụ cho công việc.\n\nQuan tâm đặc biệt đến nhân viên:\n- Gói đãi ngộ cạnh tranh cùng chính sách nâng lương theo định kỳ. Tổng thu nhập TB 14 tháng lương/năm;\n- Hỗ trợ ăn trưa lên tới 1.200.000 VND/tháng; Hỗ trợ gửi xe 200.000 VND/ tháng\n- Nghỉ hưởng lương ngày sinh nhật + quà sinh nhật\n- Quyền lợi chăm sóc sức khỏe đặc quyền bảo hiểm sức khỏe toàn diện SHBFC Care;\n- Khám sức khỏe thường niên tại bệnh viện hàng đầu Việt Nam;\n- Du lịch thường niên, hoạt động team building năm.\n- Tập trung hỗ trợ sự phát triển cá nhân:\n- Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng các cấp quản lý tài năng, giàu kinh nghiệm;\n- Cơ hội tham gia các dự án lớn, đối tác quốc tế, đi đầu trong lĩnh vực tài chính tiêu dùng;\n- Chính sách hỗ trợ các hoạt động học tập, nâng cao trình độ ngoại ngữ, trao đổi, chia sẻ kiến thức, giao lưu văn hoá (Training, Seminar...)\n\n2. YÊU CẦU\n- Bằng cử cử nhân về Khoa học máy tính, Kỹ thuật phần mềm hoặc lĩnh vực liên quan.\n- Vị trí Midle: Tối thiểu 03 năm - 05 năm kinh nghiệm trong vai trò kỹ sư phát triển phầm mềm với ngôn ngữ Java.\n- Vị trí Senior: Tối thiểu 05 năm kinh nghiệm trong vai trò kỹ sư cao cấp phát triển phần mềm với ngôn ngữ Java\n- Ưu tiên nếu có thêm kinh nghiệm phát triển phần mềm với ngôn ngữ PHP\n- Ưu tiên am hiểu trong lĩnh vực tài chính ngân hàng, hệ thống LOS.\n- Thông thạo các nguyên tắc phát triển phần mềm, lập trình hướng đối tượng và các cách thực hành tốt nhất của Java.\n- Kỹ năng thiết kế cơ sở dữ liệu và SQL (ví dụ: MySQL, PostgreSQL, Oracle).\n- Kỹ năng phát triển ứng dụng web (HTML, CSS, JavaScript).\n- Thành thạo quy trình kiểm thử, gỡ lỗi và khắc phục sự cố phần mềm.\n- Kỹ năng về các công nghệ container hóa và điều phối quy trình (ví dụ: Docker, Kubernetes).\n- Thành thạo hệ thống kiểm soát phiên bản (ví dụ: Git).\n- Thành thạo về BPMN, DMN, lược đồ cơ sở dữ liệu, giao thức truyền thông hệ thống như HTTP, Restful API, Dịch vụ web.\n- Có kinh nghiệm với các nền tảng và dịch vụ đám mây (ví dụ: AWS, Azure) là một lợi thế.\n- Khả năng làm việc theo nhóm / tổ chức.\n- Khả năng làm việc hiệu quả trong sự thay đổi.\n- Khả năng lập kế hoạch và tổ chức.\n- Kỹ năng giải quyết vấn đề.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1388, 668, 2, 'Software Engineer II- Android', 'The mobile team empowers Zalora e-commerce business by crafting the best Android app experience for our users. As a member of the mobile team, you will work on building features to provide a fun and seamless shopping experience for the millions of people who shop at ZALORA. You will work closely with cross-functional squads and crafting sophisticated apps with the Android SDK.\n\nOur app is currently written in a mix of Kotlin and Java, with all new code written in Kotlin. We\'re in the process of moving towards an architecture which will enable us to increase the testability of our code and help us maintain the excellent stability that our app enjoys.\n\nResponsibilities\n\nWork closely with the Product and UX Research team to develop features for the Android platform\nBuild high performance, well-structured native app with modern Android best-practices in mind.\nEnsure the performance, quality and responsiveness of the app.\n\nRequirements:\n\nProficiency in Kotlin, Android Jetpack, Coroutine or RxJava \nExcellent problem solving, critical thinking and communication skills.\nExperience with offline storage, concurrency, threading and performance tuning\nKnack for benchmarking and optimisation\nWorking knowledge of the general mobile landscape, architectures (MVVM or Clean architecture), trends, and emerging technologies\nSolid understanding of the full mobile development life cycle and design patterns\nBonus point if you have experience working with CI/CD, automation tools or functional programming.\n\nWhat we offer:\n\nA dynamic working environment\nAmazing office and great culture! Massage chairs, table tennis, video game room, quarterly team events, yearly company trip, end of the year party\nHybrid working environment and work from home set up allowance\nClear career progression plan and support\nEnglish classes\nMacbook or laptop when you start\nSocial insurance, medical insurance & health insurance\n13th month salary\nAnnual Bonus\n15 days of annual leave, 30 days of sick leave/mental health.\nSupport for Gym membership\n\nThe ZALORA Story\n\nZALORA is Asia’s leading online fashion, beauty and lifestyle destination, part of Global Fashion Group. As one of the region’s pioneer large-scale ecommerce platforms, ZALORA has established a strong presence throughout the region, particularly in Singapore, Indonesia, Malaysia, Brunei, the Philippines, Hong Kong, and in Taiwan, enjoying over 50 million visits per month.\n\nZALORA is not obligated to accept resumes from any third parties on behalf of potential candidates for any position (advertised or otherwise) by any means, unless ZALORA has executed a written agreement with such third party and has expressly requested such third party for candidate referrals. Third parties who provide unsolicited resumes of candidate(s) shall waive and forfeit all rights to claim for any placement fees or referral fees in the event that such candidate is eventually engaged or employed by ZALORA or Global Fashion Group.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1389, 813, 2, 'LẬP TRÌNH VIÊN PHP', 'Mô tả công việc\n\n- Lập trình ứng dụng web theo yêu cầu dự án\n- Kiểm tra chất lượng trước khi chuyển cho tester\n- Nghiên cứu và phát triển các phần mềm, sản phẩm, module mới\n- Các nhiệm vụ khác theo yêu cầu của công ty\n\nĐại học', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1390, 755, 2, 'Junior Android Engineer - Hybrid working model 100%', 'Welcome to SMG Vietnam! SMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change.\n\nThis job refers to our Real Estate brands, Homegate and Immoscout24, the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing.\n\nWe are looking for an Junior Android Engineer who is passionate about mobile development and eager to work on high-quality Android application. As a key contributor to our mobile engineering team, you will focus on delivering clean, efficient, and reliable code, working closely with other engineers, designers, and product managers. This role is ideal for an engineer looking to deepen their Android expertise and contribute to complex projects in a supportive environment.\n\nJoin our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing.\n\nYour Mission:\n- Assist in designing, developing, and maintaining Android applications, focusing on clean, maintainable code.\n- Collaborate closely with product managers, designers, and senior engineers to implement new features and enhancements.\n- Participate in code reviews, learn from feedback, and apply best practices to improve code quality.\n- Write Unit and UI tests with guidance to ensure code reliability.\n- Learn and apply modern Android architecture patterns to build scalable features.\n- Continuously improve your skills and contribute to the team\'s knowledge-sharing culture.\n- Help identify and fix bugs, optimize performance, and support releases under the guidance of more experienced team members.\n- Stay curious and up-to-date with Android development trends, tools, and best practices.\n\nYour responsibilities will evolve as we grow.\n\nQualifications\nWhat will you bring to the ride?\n- Fluency in English written and verbal communication.\n- Bachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience.\n- 1+ year of experience developing Android applications in Kotlin (Java is a plus).\n- Basic understanding of Android components and tools (e.g., Activities, Fragments, Android Studio).\n- Some exposure to modern development practices such as MVVM, Jetpack components, or reactive programming is a plus.\n- Willingness to learn and apply best practices in mobile development, testing, and architecture.\n- Comfortable with consuming REST APIs and working with local storage (e.g., Room, SharedPreferences).\n- Curious, open-minded, and enthusiastic about growing in a collaborative team environment.\n\nNice-to-Have Qualifications:\n- Exposure to CI/CD, version control (e.g., Git), or test automation frameworks.\n- Awareness of mobile app performance and monitoring tools (e.g., Firebase, Datadog).\n- Familiarity with privacy, security, or accessibility in mobile apps.\n\nWe value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique.\n\nWhat do we offer?\n- Competitive Benefits: Attractive salary, full pay during probation, 13th-month bonus, and full social insurance contributions.\n- Generous Leave: 21+ annual paid days off, 24 days for learning & sharing, and flexible working hours with no overtime.\n- Health & Wellness: Premium private insurance for you and your family, free food, and access to various classes and clubs.\n- Growth Opportunities: Personalized development plans, yearly education budgets, regular Hackathons, and potential travel to Switzerland and Europe.\n- Modern Work Environment: Hybrid model, top-tier equipment, and a friendly, agile, and transparent culture.\n- Supportive Onboarding: Comprehensive assistance to help you settle in.\n\nRecruitment Process\nWe believe hiring is a two-way street, where both parties get to know each other. Here\'s what you can expect:\n- Initial screening call with HR – A brief conversation to understand your background and expectations.\n- Meeting with the Hiring Manager – A deeper discussion about the role, your experience, and how we work.\n- Home assignment – A small project to showcase your skills in a real-world context.\n- Technical Assessment – A follow-up session to review your assignment and discuss technical topics in more detail.\n- Casual Meeting with Director – An informal conversation to align on vision, culture, and goals.\n\nAt SMG Vietnam, we value diverse perspectives and individual growth. We welcome candidates from all backgrounds and encourage you to apply, even if you don’t meet every requirement. Together, we embrace differences, nurture potential, and celebrate success.\n\nApply now\nTo take this opportunity, send us your detailed CV and feel free to add any supporting documents we need to look at in order to understand that you are the perfect fit.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Củ Chi district, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1391, 825, 2, '[Ha Noi] Software Engineer', 'Company Description\nAre you passionate about technology and looking to grow your career in the semiconductor equipment industry? Join Global ZEUS VINA, where we offer a professional, dynamic environment with competitive benefits and international opportunities!\n\n📌 WHAT WE OFFER\n⏰ Work schedule: Monday to Friday (5-day workweek)\n💰 100% salary during the probation period\n🛠 Little to no overtime (if any, it will be paid in accordance with labor laws)\n🎉 Team-building activities and company trips\n📈 Annual salary reviews and performance bonuses\n🌏 Training opportunities in South Korea with allowances\n\nJOB DESCRIPTION:\nOn-site Support & Software Maintenance for Semiconductor Equipment\nInstall, maintain, and troubleshoot software\nCollect and analyze customer requirements (VoC)\nProvide technical support to global clients (USA, Korea, Japan, Taiwan)\nAnalyze equipment software logs\n\nSoftware Testing\nWrite and execute test cases\nPerform simulation testing\nCreate test reports and suggest improvements\nMaintain equipment control software\n\nSoftware Development\nDevelop and debug software features/modules\nImplement communication drivers (e.g., Serial, TCP/IP)\nDesign and implement user interfaces (GUI)\n\nQualifications\nPrior experience in C++ or C#\nPrior experience (0- 3year) in semiconductor equipment is a big plus\nFamiliar with P&ID drawings, I/O Systems\nExperience in communication protocols (Serial, TCP/IP)\nStrong debugging and data analysis tool skills\nBachelor\'s degree in Computer Science or related field\nAbility to communicate in English or Korean for work purposes\nStrong problem-solving and self-learning abilities\nWillingness to travel or train abroad (Korea, USA, Japan)\n\n📝 APPLICATION\nPlease prepare:\nAn updated CV detailing your experience\nRelevant certificates or diplomas (if available)\n\n📧 Send your application to: zeusvina@globalzeus.com\n📞 Contact: Ms. Linh – 0978.561.443', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1392, 826, 2, 'REACT NATIVE DEVELOPER', 'Dear my connections,\nNam Long Software is still looking for #reactnativedeveloper\n#software #hcmsoftware #reactnativejobs\n\nMÔ TẢ CÔNG VIỆC:\n- Participate in the development and construction of the company\'s products on the React Native platform\n- Other related jobs\n- Job details will be discussed further during the interview\n\nYÊU CẦU ỨNG VIÊN: \n- More than 2 years of experience.\n- Experience with Redux, Redux Saga, React Hook,...\n- Ability to support and allocate work to other team members\n- Have a spirit of learning and self-improvement\n- Ability to work in a team or independently\n- Be responsible with your work\n\nQUYỀN LỢI:\n- Working time: Monday - Friday: 8:30 - 18:00 (lunch break 1h30\')\n- Working in a dynamic and professional environment with many opportunities for advancement.\n- Provide complete equipment to serve the job.\n- The company pays all social insurance, health insurance, and unemployment insurance.\n- Enjoy the welfare policies according to the company\'s regulations (Annual salary review, 13th month salary, KPI bonus, 12 days of leave, birthday celebration, lunch allowance, car parking,...)\n- Regular training and professional improvement.\n- Participate in cultural activities with typical colors of the company: Team building, and a series of interesting and attractive collective activities taking place monthly and quarterly at the company.\n- Competitive salary.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1393, 827, 2, 'Java Developer', 'Job Description\n\n– Tham gia thiết kế triển khai,vận hành và phát triển các phần mềm hệ thống trên nền tảng Java, Primefaces, Oracle\n\n– Tiếp cận, nghiên cứu các công nghệ về lập trình phần tán, kiến trúc Microservices, điện toán đám mây, trí tuệ nhân tạo để tích hợp vào các ứng dụng/dịch vụ\n\n– Báo cáo, và thực hiện các công việc theo yêu cầu của quản lý\n\n– Học tập các công nghệ mới theo yêu cầu của quản lý\n\nYêu cầu ứng viên\n\n– Tốt nghiệp Đại học chuyên về CNTT, Điện Tử, Viễn thông hoặc tương đương…\n\n– Có tối thiểu 1 năm kinh nghiệm phát triển phần mềm sử dụng ngôn ngữ lập trình Java Web (Primefaces, JS, JQuery, Hibernate,Servlet…) và Java Core\n\n– Có tối thiểu 1 năm kinh nghiệm làm việc với API (SOAP, Restful…)\n\n– Có tối thiểu 1 năm kinh nghiệm làm việc trên Database Oracle (SQL,PL/SQL)\n\n– Có khả năng nắm bắt nhanh quy trình vận hành dịch vụ,hoạt động của doanh nghiệp\n\n– Nhiệt tình,ham học hỏi, chủ động trong công việc và làm việc nhóm tốt\n\n– Có tư duy hệ thống,tư duy logic tốt,có kiến thức về cấu trúc dữ liệu và giải thuật cơ bản\n\nQuyền lợi\n\n– Đãi ngộ (lương, thưởng, review lương):\n\n– Lương cứng: 20 triệu – 30 triệu + thưởng KPIs cuối năm\n\n– Ký Hợp đồng lao động, đóng bảo hiểm đầy đủ, nghỉ 12 ngày phép năm, các ngày Lễ, Tết theo quy định Nhà nước.\n\n– Xét thưởng và xét tăng lương 2 lần/ năm.\n\n– Cơ chế lương 3 vòng thu nhập, có thưởng KPI tháng và KPI năm. Công thức lương gói thu nhập năm (Trung bình thu nhập 14 – 15 tháng lương/năm).\n\n– Được tham gia các khóa huấn luyện, đào tạo nâng cao kỹ năng, nghiệp vụ của CMC cũng như các hãng công nghệ lớn như Microsoft, IBM, Google …\n\n– Bảo hiểm chăm sóc sức khỏe Aon Care (điều trị nội trú và ngoại trú) dành cho nhân viên\n\n– Các ngày nghỉ lễ Tết theo quy định của nhà nước và có thưởng theo quy định của công ty\n\n– Cơ hội thử thách và phát triển\n\n– Cơ hội được làm việc tại công ty công nghệ viễn thông tư nhân hàng đầu Việt Nam (As an AWS Advanced Consulting Partner, First Premier Partner of Google Cloud in Viet Nam)\n\n– Cơ hội được tiếp cận, đào sâu những công nghệ mới nhất, tiên tiến nhất với tập khách hàng đa ngành và những dự án siêu khủng\n\n– Được dẫn dắt, hỗ trợ bởi team lead/chuyên gia ưu tú, đầu ngành trong lĩnh vực\n\n– Được ủng hộ, trao quyền cho sáng tạo và đột phá từ người trẻ\n\nVăn hoá môi trường làm việc:\n\n– Làm việc 5 ngày/tuần (khoảng 44h/tuần), nghỉ thứ 7, Chủ Nhật\n\n– Môi trường làm việc trẻ, năng động, sáng tạo, công bằng, kỷ luật\n\n– Văn phòng xanh, đạt tiêu chuẩn quốc tế\n\n– Tham gia gắn kết với tập thể, tổ chức với các hoạt động team building thú vị, các clb chạy và đá bóng, esport,…các party liên hoan của Công ty (sinh nhật, lễ Tết,…)\n\n– Chế độ chăm sóc y tế đặc biệt cho CBNV\n\nWage 20 - 30 triệu Type of work Fulltime Gender Nam/Nữ Experience 2 - 3 năm Quantity 2 Province, city Hà Nội Address Tầng 11, Tòa nhà CMC, số 11 Duy Tân, Cầu Giấy, Hà Nội Deadline 31/03/2022 Form submission Email', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1394, 828, 2, 'Java Backend Developer', 'Welfare\n\n- Attractive remuneration with competitive income and 6 months/year salaries/ efficient production and business.\n- A welfare package of $2000 per year including Tet bonus, holiday bonus and resort.\n- Being a colleague of a team of leading technology experts in fields such as: DPI, BigData, Machine Learning, AI, Data Mining, Speech Recognition, Virtual Assistant…\n- Improve capacity through intensive training courses, study support and professional certification exams.\n- Consider raising the minimum salary once a year. Access to attractive promotion opportunities.\n- 12 days holiday, 12 vacation days and 3 annual vacation days.\n- Always enjoy to the fullest full benefits of social insurance, health insurance, unemployment insurance and statutory leave and sick leave after signing the labor contract\n- Join the comprehensive health care MIC insurance package.\n- Relax, spark creativity with Happy Time every day, modern workspace.\n- Enjoy a delicious lunch, selected by nutritionists.\n- Working in key projects of the Group with large system scale.\n- Experience the multiculturalism when working with Viettel\'s personnel in more than 10 countries.\n\nJob Descriptions\n\n- Building an interactive system with a large number of users.\n- Statistics, analysis and data processing.\n- Building statistical modules according to the requirements of the users. customers on the basis of Big Data technology.\n- NoSQL database design organization.\n- Development and performance optimization for large data processing modules real-time.\n- Participate in research and customize new technologies as required by the project.\n\nJob requirements\n\nGeneral Requirements\n\n- Graduated from a regular university with good grade or higher, majoring in accordance with the position.\n- Having experience of 02 years or more (accepting the whole process of experience work while undergrad).\n- TOEIC 550/990.\n\nRequired Requirements\n\n- Master some knowledge of common data structures and algorithms.\n- Have an object-oriented design mindset and master some common design patterns. .\n- Familiar with SQL and some common DBMS.\n- Knowledge of computer networks (protocols and protocols).\n- Fluent. using relational databases, or NOSQL systems.\n- Proficient in object-oriented programming, Java core (preferably understanding of multiple thread programming systems).\n- Fluent in using one of the programming languages: Java, Python, Scala.\n- Know how to use software development tools: Gradle, Maven …\n\nPriority Requirements\n\n- Experience in working with Hadoop Ecosystems such as Kafka, Spark, Hbase… \n- Experience in writing Clean, Testable Codes', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1395, 814, 2, '[iKame Apps] Manual Tester', 'Location: Hà Nội\n\nSalary: Upto 20.000.000 VNĐ\n\nExpiration date: 31/07/2025\n\nMÔ TẢ CÔNG VIỆC\n\n- Đọc hiểu, phân tích tài liệu thiết kế app.\n- Thiết kế test case dựa trên tài liệu thiết kế app.\n- Thực hiện kiểm thử sản phẩm app theo test case đã thiết kế.\n- Báo cáo lỗi trong quá trình kiểm thử lên Bug Base.\n- Gửi báo cáo tiến độ kiểm thử cho Leader và PM.\n- Kiểm tra, tái hiện các lỗi phát sinh theo phản hồi của người sử dụng app.\n- Đảm bảo chất lượng sản phẩm trước khi phát hành ra thị trường.\n\nYÊU CẦU CÔNG VIỆC\n\n- Tốt nghiệp ngành CNTT hoặc tương tự.\n- Có ít nhất từ 1 năm kinh nghiệm trong lĩnh vực kiểm thử. Ưu tiên đã có kinh nghiệm Mobile App\n- Am hiểu về nền tảng Android, IOS và thị trường app.\n- Có kiến thức cơ bản về Database.\n- Hiểu biết về các quy trình phát triển sản phẩm phần mềm.\n- Có tư duy logic và clear rõ ràng về định hướng phát triển bản thân.\n- Có chứng chỉ ISTQB Foundation là một lợi thế.\n\nQUYỀN LỢI\n\n- Mức lương lên tới 20.000.000 triệu đồng; review lương 2 lần/năm\n- Thưởng HẤP DẪN: Thưởng hiệu quả kinh doanh theo 2 quý/ lần + Thưởng tháng lương thứ 13 + Thưởng Lễ\n- Được đào tạo và tham gia xây dựng và phát triển sản phẩm đa dạng thể loại hướng tới CHẤT LƯỢNG & GHI DẤU ẤN – cơ hội phát triển và thăng tiến rộng mở\n- Cơ hội được học hỏi, được thử sai, được đưa ý kiến để rèn luyện bản thân và trau dồi kinh nghiệm thực chiến với việc hỗ trợ 30-100% chi phí các khóa học mọi kỹ năng\n- Môi trường thân thiện, hiện đại, văn phòng đẹp xịn xò view toàn thành phố\n- Con người là số 1 - bạn sẽ được quan tâm từ thiết bị làm việc, bữa ăn xế chiều, tới chỗ ngủ, từ tủ đầy đồ ăn vặt tới bàn bi-a, bi-lắc, PS4 xả não, thư viện cho những tâm hồn yêu thích đọc sách...\n- Các chế độ đãi ngộ khác như Trợ cấp ăn trưa 1 triệu đồng/tháng, Gói khám sức khỏe cao cấp, Teambuilding thường xuyên, Du lịch dài ngày.\n- Thời gian làm việc: 08h30-18h00 thứ 2 đến thứ 6; nghỉ trưa 1,5h, không OT - cân bằng cuộc sống và công việc.\n\nCÁCH THỨC ỨNG TUYỂN\n\n💌 Ứng viên gửi CV về email: recruitment@ikameglobal.com\n\n➡️Hotline: 024 6662 5287 | HR Department\n\n➡️Head Office: Tầng 9 & 10 tòa Peak View, số 36 Hoàng Cầu, Ô Chợ Dừa, Đống Đa, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1396, 723, 2, 'Tester', 'MÔ TẢ CÔNG VIỆC \n\n- Tham gia vào các dự án phần mềm của Công ty\n- Đọc hiểu các tài liệu BA\n- Viết test case, test report.\n- Thực hiện công việc kiểm thử (manual test) để kiểm tra chất lượng sản phẩm trước khi chuyển cho khách hàng.\n- Cập nhật thông tin chi tiết về các lỗi của phần mềm tìm thấy lên công cụ quản lý dự án (Redmine, Jira…)\n- Theo dõi trạng thái sửa lỗi và kiểm tra lại việc sửa lỗi trước khi đóng lỗi\n- Thực hiện báo cáo chất lượng dự án phần mềm.\n- Phối hợp với đối tác/khách hàng trong quá trình test, fix bugs\n- Viết các tài liệu hướng dẫn sử dụng phần mềm theo phân công của quản lý\n\nYÊU CẦU \n\n- Khả năng phân tích, tư duy logic tốt.\n- Kỹ năng giao tiếp tốt\n- Tốt nghiệp Đại học / Cao đẳng (hoặc tương đương) các chuyên ngành CNTT, Điện tử – Viễn thông\n- Có ít nhất 2 năm kinh nghiệm ở vị trí tương đương\n- Có kinh nghiệm sử dụng SQL để phục vụ cho việc test phần mềm\n- Ưu tiên các ứng viên có các yếu tố sau:\n- Đã có kinh nghiệm test website và ứng dụng mobile (Android, iOS)\n- Khả năng sử dụng tiếng Anh trong công việc\n- Có kiến thức hoặc kinh nghiệm phát triển phần mềm theo mô hình Agile (Scrum)\n\nQUYỀN LỢI \n\n- Mức thu nhập cạnh tranh: upto 18M, Thỏa thuận theo năng lực\n- “NMS care” bảo hiểm dành riêng cho nhân viên NMS.\n- Nghỉ mát: Theo chính sách của công ty\n- Có cơ hội được xem xét nâng lương hàng năm tùy vào kết quả công việc.\n- Môi trường làm việc hiện đại, thân thiện.\n- Chính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1397, 829, 2, 'NodeJS Developer (Yêu cầu Tiếng Anh)', 'I. Mô tả công việc\n\n·       Tham gia phát triển các ứng dụng trên nền tảng NodeJS cho khách hàng, duy trì và nâng cấp các tính năng của sản phẩm\n\n·       Làm việc với các khách hàng đến từ những thị trường sử dụng tiếng Anh như US/UK, Australia, Singapore……\n\n·       Tư vấn giải pháp, thiết kế, xây dựng tạo ra các sản phẩm phần mềm tối ưu, phù hợp với nhu cầu của khách hàng\n\n·       Làm việc theo sự phân công của trưởng nhóm/quản lý dự án, phối hợp giữa các nhóm để phát triển sản phẩm\n\n·       Hỗ trợ các thành viên trong nhóm với các chức năng phức tạp, tham gia nhận xét, đánh giá source code của các thành viên trong nhóm\n\nII. Yêu cầu công việc\n\n·       Bằng cử nhân về Khoa học Máy tính, Công nghệ thông tin hoặc tương đương.\n\n·       Có ít nhất 2 năm kinh nghiệm viết Restful API với NodeJS bằng ExpressJs.\n\n·       Thành thạo ES6 và Typescript.\n\n·       Hiểu biết sâu sắc về cơ sở dữ liệu quan hệ như MySQL, Postgres và cơ sở dữ liệu phi quan hệ như MongoDB.\n\n·       Có kinh nghiệm làm việc với ORM như MikroORM, Prisma,…\n\n·       Có kinh nghiệm viết unit test sử dụng Jest, Jasmine, Mocha,…\n\n·       Viết tài liệu API bằng các công cụ như Swagger\n\n·       Khả năng làm việc nhóm và giao tiếp hiệu quả.\n\n·       Khả năng giao tiếp tiếng anh tốt\n\nIII. Quyền lợi chung\n\n·       Fix 13 tháng lương\n\n·       Thưởng performance 2 lần/năm vào tháng 6 và tháng 12\n\n·       Review lương 2 lần/năm vào tháng 4 và tháng 10\n\n·       Beauty care: 200.000 VND/người/tháng cho nhân viên nữ\n\n·       Quỹ đào tạo 3.000.000 VND/người/năm\n\n·       Phụ cấp thâm niên\n\n·       Thưởng chứng chỉ tiếng Nhật và các loại chứng chỉ khác theo quy định (nếu có)\n\n·       Bảo hiểm sức khỏe PVI cho nhân viên từ 1 năm thâm niên\n\n·       12 ngày phép năm, BHXH/BHYT/BHTN đầy đủ theo quy định của Luật lao động\n\n·       Nghỉ lễ Tết theo quy định Nhà nước và kèm theo thưởng cho các ngày lễ lớn trong năm: 30/4, 1/5, 2/9, Tết,…\n\n·       Thời gian làm việc: Thứ 2 đến thứ 6 từ 8h-17h30 (nghỉ thứ 7, chủ nhật), thời gian chấm công (check in) linh hoạt từ 7h30-8h30\n\n·       Địa điểm làm việc: Tầng 2 và Tầng 21, tòa Central Point, 219 Trung Kính, Yên Hòa, Cầu Giấy, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1398, 702, 2, 'Pioneer Talent Program - Java Engineer (Tech Compliance)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 230 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nAbout The Pioneer Talent Program\n\nAre you an early-career professional ready to kickstart your career in the dynamic world of blockchain? Binance’s Pioneer Talent Program is designed to nurture ambitious individuals like you. The program offers full-time roles where participants will gain hands-on expertise via a tailored training curriculum and personalized 1:1 mentorship from industry leaders. Dive behind the scenes of the world’s leading blockchain ecosystem while building the skills to thrive in Web3. Launch your career with purpose—join us in shaping the future of digital innovation.\n\nWho May Apply\n\nCandidates with up to 5 years of relevant work experience\n\nJob Description\n\nWe are seeking a talented Java Spring Developer with a minimum of 3 years of professional experience to join our team. This is a remote position, offering the flexibility to work from anywhere in the world. The ideal candidate will have a strong background in Java Spring Boot, with a focus on developing Java micro-service applications. Experience with AWS cloud services is considered a bonus, as well as full-stack development expertise and knowledge of blockchain technology.\n\nResponsibilities\n\n- Designing, developing, and maintaining Java micro-service applications using the Spring Boot framework.\n- Collaborating with cross-functional teams to define, design, and implement new features.\n- Writing clean, efficient, and maintainable code.\n- Conducting code reviews and providing constructive feedback to team members.\n- Troubleshooting and debugging applications to optimize performance.\n- Staying updated on emerging technologies and best practices in Java development.\n- Working closely with team members across different time zones to ensure effective collaboration and communication.\n\nRequirements\n\n- Bachelor\'s degree in Computer Science, Engineering, or related field.\n- 3+ years of professional experience in Java development.\n- Solid experience with Java Spring Boot for developing micro-service applications.\n- Experience with AWS cloud services is a plus.\n- Full-stack development experience is an advantage.\n- Knowledge of blockchain technology is preferred.\n- Strong problem-solving and communication skills.\n- Ability to work independently and as part of a distributed team.\n- Willingness to work time shifts to accommodate collaboration with team members in different geographic locations.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1399, 830, 2, 'Full Stack Java Developer (with Angular)', 'Are you looking for a position that challenges you to grow, explore new areas and contribute in multiple ways within a fast-paced workplace? Would you like the opportunity to work with a great variety of people in Vietnam and Switzerland? Join us in one of our Vietnamese location in Ho Chi Minh City and become a member of our cross-border team with colleagues in Zurich (Switzerland).\n\nAbout our company:\nmesoneer is one of the leading Swiss software companies in the fields of digital onboarding, process automation and the integration of complex peripheral systems. Our approximately 120 employees in Switzerland and Vietnam digitize and simplify business processes with individual software solutions, modernize outdated applications and develop in-house SaaS solutions. We need you for our customers in the finance and insurance sector, public administration and other industries!\n\nCompany size: 120 employees\nWebsite: https://www.mesoneer.io/en/\nFanpage: https://www.facebook.com/mesoneer\nLinkedin: https://www.linkedin.com/company/mesoneer/about/\n \nWhy you’ll love working here:\n- 13th-month salary bonus.\n- Flexible working time policy.\n- 12 Annual leaves, plus 5 core leave days each year.\n- 5 Sick leaves and 3 Bereavement leaves for relatives each year.\n- Annual Health check, PVI healthcare for employees and two family members.\n- Full-salary-based social insurance.\n- Annual salary review and based on performance and contribution.\n- A laptop, lunch, and parking fees are provided.\n- Kid allowance.\n- Activities: Company party, Family Day, Company trip, Happy hour, Happy birthday, Team building, …\n- Office located in the center with great accommodations (ergonomic chair, free drinks, snacks, game room, ...).\n\nYour skills:\n- 3+ years of experience in designing, developing, and maintaining projects using Java technologies.\n- Have deep understanding about Spring Framework (Spring Boot, Spring Security, Spring Data,..) and other well-known Java libraries.\n- Experienced in designing and building API for modern web applications using OpenAPI, OAuth2, JWT.\n- Experienced in working with relational database systems, e.g., Oracle, PostgreSQL.\n- Experienced in building front-end with modern web frameworks, especially Angular.\n- Be able to work with and/or set up continuous integration/delivery using tools like Jenkins, GitHub Action.\n- Familiarity with cloud platforms (e.g., AWS, OpenShift).\n- Understand agile methodology and experienced in Scrum framework.\n- High willingness to familiarize yourself with new challenges.\n- Fluent in reading and writing English and able to communicate.\n\nWhat are your responsibilities:\n- Collaborate with other teammates and Product Owners to deliver good project results, and ensure quality, costs, and deadlines are met.\n- Work closely with other team members to ensure projects have good quality and a stable development environment.\n- Participate in the entire software development life cycle, including requirements analysis, design, development, testing, deployment, and support.\n- Write clean, maintainable, and well-documented code.\n- Self-manage your time and work.\n- Other tasks assigned by Leader.\n\nPlease feel free to contact us for any questions or send your profiles to our recruiters at jobs.vn@mesoneer.io.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1400, 831, 2, 'Java Software Engineer', 'Location: HCM, DN, HN\nOpen position: 05\n\nQualification requirements\n- At least 3 years of experience as Java Developer\n- Understanding one of the relational databases (PostgreSQL, MySQL, Oracle, SQL Server, DB2)\n- Good communication in English\n- Degree in Computer Science or related field\n- Experience with designing database structures\n- Analytical mindset and good problem-solving skills\n- Good organizational skills\n- Ability to work both independently and as part of a team\n\nResponsibilities\n- Design, develop and test Java-based solutions using common standards and frameworks such as JPA, J2EE, Spring Boot, Spring MVC, Hibernate, ...\n- Translate software requirements into working and maintainable solutions within the existing application frameworks\n- Implement the product\'s lifecycle: Design, development, quality, deployment and maintenance\n- Develop and adhere to best practices for developing applications\n- Continuously contribute to team performance improvement and collaboration\n- Collaborate effectively across teams\n\nWhy you will love working here\n- Nice and friendly working environment.\n- Competitive salary with multiple bonus scheme\n- Lots of interesting and challenging projects to work on.\n- 13th-month salary benefits\n- Chance to work onsite abroad\n- We have a fun, Silicon Valley-style startup culture that values openness, fun, and awesomeness.\n- Attractive salary and annual salary review.\n- Provide devices for work.\n- Chance to become the leader of startup culture.\n- A fun, awesome work environment with multiple exciting bonus scheme\n- Progressive and international working environment.\n- Exciting company activities.\n- Free in-house entertainment facilities (football), coffee, and snacks (instant noodles, cookies, candies…)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói, Hanoi, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1401, 740, 2, 'BrSE (Japan)', 'Job Description\n\nCommunication between customer and offshore\nPerform requirement hearing and analysis, solution proposal\nPerform basic design, detailed design, test design creation/review in Japanese if needed\nPerform deliverables review for offshore team if needed\nAssist project manager on project scope, estimation, planning; monitoring and controlling\nSupport UAT testing and verifying bugs/issues\n\nRequirements\n\nJapanese level equivalent to N2 or above\nStrong communication skills both written and verbal\nHas of experience in participating in a series of required tasks (requirement hearing and analysis, basic design, detailed design)\nHas of experience with one of following technology stacks/platforms: Web application (Java, C#, PHP, Front-end language), Mobile application (Android, iOS), Embedded (C/C++), Salesforce, SAP, RPA, C++, AWS, Aras, Oracle.\n\nDesired Skills\n\nUnderstanding about Japanese culture and Japanese working style\nExperience managing big projects\nLeadership potentiality, high responsibility, good teamwork spirit\nPrefer candidate with work experience or study in Japan\n\nBenefits\n\nTraining in software quality systems.\nOpportunity to work with global standards.\nOpportunity to collaborate with consultants and certification organizations from world-renowned assessment bodies.\nTraining in implementing large-scale software projects at CMC Global.\nAttractive income of up to 750 man JPY/year, based on skills and experience, including a 14-month salary package and additional benefits.\nSalary review: Twice a year.\nBonuses: Twice a year, paid in April and October.\nCommutation allowance: Up to 20,000 JPY/month (by actual cost).\nHousing allowance: 30,000 JPY/month.\nFlight allowance: 80,000 JPY/year.\nFamily allowance: From 10,000 JPY/month.\nOvertime compensation: Paid according to Company Regulations and Japanese labor law.\nSpecial bonuses for passing certifications such as AWS, and other IT-related qualifications.\nSocial insurance: Fully covered, in accordance with Japanese labor law.\nHolidays: Based on the CMC Japan calendar (including national holidays in Japan).\n\nOpportunities\n\nA chance to build and grow a potential team from the ground up.\nYoung and dynamic working environment.\nFun leisure activities: sports and art events (clubs, family day, etc.).\nLabor policies fully compliant with Japanese labor laws.\nAdditional company benefits such as company trips, holiday events, and more.\nWork Location: Tokyo, Osaka, Fukuoka, Nagoya, Tochigi, Oita\n\n1+ years of experience as BrSE/Team leader/Project Manager\n\nPlease send your application via email: recruitment@cmcglobal.vn\nYears of Experience Required\nRequired Education Level\nBachelor’s Degree\nJob Level\nMiddle/Senior/Team Lead\nWork Form\nFull-time\nEmail: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vu Ban, Prowincja Hoà Bình, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1402, 532, 2, 'Principal Software Engineer', 'Sunbytes is a leading Tech & Talent Solutions company known for innovative and scalable solutions. We focus on achieving goals for our partners and team members, delivering high-quality products and services, and fostering a supportive, challenging work environment. Our diverse team shares a common purpose, making Sunbytes a great place to work.\n\nWe offer comprehensive long-term partnerships, including recruitment, dedicated worldwide talents, and custom software development, tailored to meet client needs.\n\nJoin Us Are you looking for the opportunity to work on billion-dollar projects, leveraging cutting-edge technology to deliver value and drive transformative change? If you are ready to make a difference and shape the future, this is the place for you.\n\nAbout The Role\n\nSunbytes is looking for a Principal Software Engineer to work with our client, who is a leading company that delivers solutions for the floating offshore oil and gas industry. This job is based at the client office in Ho Chi Minh City. The ideal candidate will be responsible for:\n\n- Combine leadership in engineering with hands-on coding, spending about 60-80% of your time actively writing code while guiding a team of up to 10 developers.\n- Exceptional engineers who do not prefer managerial roles are also welcome to apply, provided they clearly indicate their preference.\n- Collaborate with the Product Owner on creating the product roadmap and planning releases.\n- Cultivate a culture of high performance, with an emphasis on technical excellence, teamwork, and responsibility.\n- Efficiently allocate and oversee development tasks within the team.\n- Architect and design systems that are robust, scalable, and secure while producing clean, maintainable, and high-quality code.\n- Lead development efforts, including overseeing code reviews, testing, and debugging.\n- Continuously improve development processes, tools, and practices, integrating DevOps best practices throughout the workflow.\n\nRequirements\n\n- At least 7 years of professional software development experience, with at least 2 years in a leadership position.\n- Strong academic credentials in Comp Science/IT from top universities in Vietnam, or equivalent from foreign universities.\n- A T-shaped developer with wide-ranging technical knowledge and strong expertise in either frontend or backend systems.\n- Experience with data processing or machine learning/AI is a strong plus.\n- Enjoys solving complex, high-impact technical problems and exploring creative, unconventional solutions.\n- Open-minded and innovative, willing to challenge the status quo and try new approaches.\n- Proven track record of developing complex enterprise applications across multiple departments or business units.\n- Hands-on experience with cloud platforms such as AWS, Azure, or Google Cloud.\n- Skilled with containerization and orchestration technologies like Docker and Kubernetes.\n- Comfortable working with any programming language, our stack includes Python, React.js, and Azure.\n- Startup experience is a nice-to-have bonus.\n\nSoft skills\n\n- Excellent written and verbal communication skills in English.\n- Proven ability to lead and mentor teams.\n- Strong analytical and creative problem-solving capabilities.\n- Strong organizational skills with the ability to manage multiple projects and meet deadlines.\n\nBenefits\n\n- Competitive salary package\n- 13th-month salary for every 12 months of employment\n- 16 days of annual leave in the first year, increasing with tenure\n- New laptop and required software provided\n- Monthly mobile phone allowance\n- Annual salary review\n- Discretionary bonus\n- Medical coverage under company healthcare plan (legal spouse/children)\n- Personal accident and term-life insurance for employee and immediate family\n- Annual premium health check-up\n- Safety awards and Tet holiday gifts.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1403, 674, 2, 'Tuyển dụng Nhân Viên Python Automation Developer (Full Stack)', 'Mô tả công việc\n\nPSA là công ty eCommerce hoạt động trong các lĩnh vực Print-on-Demand, Dropshipping, Fulfillment và Bán lẻ online, phục vụ hơn 10,000+ khách hàng toàn cầu.\n\nChúng tôi đang phát triển các hệ thống nội bộ (ERP, OMS, CRM, Data Analytics...) nhằm tối ưu hóa quy trình vận hành và nâng cao trải nghiệm người dùng, hướng tới mô hình AI-driven eCommerce.\n\nMô Tả Công Việc\n\n- Viết script/python tools để crawl, quản lý dữ liệu sản phẩm/đơn hàng/đối tác từ Shopify, Amazon, TikTok Shop,...;\n- Tự động hóa quy trình vận hành: check đơn, quản lý file, dữ liệu, xuất/nhập Excel, PDF, CSV…;\n- Triển khai tool nội bộ có giao diện web (frontend đơn giản: HTML/CSS/JS hoặc framework bạn quen dùng);\n- Hỗ trợ team CS, Fulfillment, Marketing tối ưu hóa công việc thông qua đối tượng tự động hóa.\n\nYêu cầu công việc\n\nBắt Buộc\n\n- Từ 3+ năm kinh nghiệm với Python, đặc biệt trong môi trường automation;\n- Thành thạo Selenium, xử lý HTML/DOM, login bot, crawl data;\n- Biết xử lý file dữ liệu: Excel, CSV, PDF;\n- Biết xây dựng UI web đơn giản: HTML/CSS/JS hoặc framework frontend;\n- Tư duy logic, có khả năng xử lý sự cố và debug tốt.\n\nƯu Tiên\n\n- Từng làm việc trong các dự án eCommerce, fulfillment, dropshipping;\n- Biết xử lý task scheduling, cron job, auto notification, cloud VPS;\n- Đã từng xây các tool tự động đang được vận hành thực tế.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Lương: Thỏa thuận theo năng lực + thưởng theo hiệu suất;\n- Lương T13, T14, tăng lương hàng năm theo năng lực;\n- Tham gia BHXH, BHYT, BHTN theo quy định, khám sức khỏe tổng quát định kỳ;\n- Du lịch 2 lần/năm, quà/thưởng lễ tết, sinh nhật, đồ ăn vặt tại văn phòng,...;\n- Hỗ trợ ăn trưa, gửi xe, laptop làm việc;\n- Tham gia các khóa học nâng cao chuyên môn.\n\nHình thức làm việc (chọn 1 trong 2 hình thức sau):\n\n- Office: T2-T6: 9:00-17:30 (nghỉ trưa 1h30p) / sáng t7 remote: 8:00-12:00\n\nĐịa chỉ: Tropic Garden A2 - 56 Đường số 66, Thảo Điền, Thủ Đức, HCM\n\n- Remote: T2-T6: 8:30-17:30 (nghỉ trưa 1h30p) / sáng t7: 8:00-12:00\n\nCách Thức Ứng Tuyển\n\nGửi CV + Bảng điểm (scan/ảnh file pdf, jpeg, png) về email career@makezbright.com\nhoặc liên hệ Zalo: 0942 485 129 (Vy PSA).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1404, 832, 2, '[Hybrid] Software QA Engineer (Auto+Manual)', 'Responsibilities: \n- Create quality measurements to track product improvement by creating a standard test case document for execution tests.\n- Execute quality improvement testing and activities (manual and automatic testing).\n- Develop quality assurance standards and company processes.\n- Ensure products meet customer expectations and demand by finding the bug and reporting to the developer team and product manager.\n- Create reports documenting errors and issues to fix.\n- Work closely with the development team to improve existing products based on prototypes and deliver the product expectation as design/ prototype.\n- Maintain standards for reliability and performance of the production.\n\nRequirements: \n- A bachelor\'s degree in a related field is preferred.\n- Working knowledge of products and services.\n- In-depth understanding of industry standards and company policies.\n- Good customer focus.\n- Sharp attention to detail.\n- Strong analytical and problem-solving skills.\n- Meticulous and diligent attributes.\n- Great team player with the ability to work with minimal supervision.\n\nBenefits: \n- Hybrid working: 1-2 work from home days/week \n- 100% salary during probation period. \n- Performance Bonus: 13th-month salary if achieving performance \n- 2 times salary review/year \n- Expand your skills and career with continuous learning opportunities and real development support.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1405, 833, 2, 'BrSE', 'MÔ TẢ CÔNG VIỆC:\n- Là cầu nối giữa khách hàng Nhật Bản và đội dự án Offshore ở Việt Nam, giải quyết các vấn đề phát sinh trong dự án, và các vấn đề sau khi bàn giao.\n- Trao đổi trực tiếp với khách hàng Nhật Bản: lấy thông tin dự án, tài liệu yêu cầu, xác nhận lại thông tin và truyền đạt nội dung dự án về cho đội dự án ở Việt Nam.\n- Báo cáo với KH tiến độ dự án theo các loại hình báo cáo.\n- Kết hợp với Project Manager lên kế hoạch và kiểm soát tiến độ thực hiện dự án.\n- Thực hiện kiểm tra chất lượng sản phẩm đầu ra của dự án trước khi deliver cho Khách hàng.\n- Các công việc khác theo yêu cầu dự án.\n- Làm việc tại Hà Nội.\n\nYÊU CẦU CÔNG VIỆC:\n\nVới level Fresher, Junior:\n- Tốt nghiệp Cao đẳng, Đại học chuyên ngành CNTT hoặc liên quan.\n- Tiếng Nhật từ N2 trở lên.\n- Có khả năng biên dịch và soạn thảo tài liệu bằng tiếng Nhật.\n- Ưu tiên có kinh nghiệm lập trình ngôn ngữ bất kỳ.\n\nVới level Middle, Senior:\n- Có kinh nghiệm với vị trí BrSE từ 2 năm trở lên.\n- Tiếng Nhật từ N2 trở lên; Có khả năng biên dịch và soạn thảo tài liệu bằng tiếng Nhật.\n- Tốt nghiệp Cao đẳng, Đại học các chuyên ngành CNTT, Khoa học máy tính,... hoặc liên quan.\n- Có kinh nghiệm và thành thạo một trong các ngôn ngữ lập trình/framework: PHP/C#/.Net/Java/NodeJS/Python/Android/iOS/Ruby...\n- Ưu tiên có kinh nghiệm quản lý team (sẽ được traning thêm kỹ năng PM khi vào công ty).\n\nYêu cầu khác:\n- Có tinh thần trách nhiệm cao trong công việc.\n- Từng làm việc với khách hàng IT Nhật Bản.\n- Có khả năng làm việc độc lập và làm việc theo nhóm.\n- Có khả năng đọc hiểu tiếng Anh là lợi thế.\n\nQUYỀN LỢI:\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng kinh doanh + thưởng dự án, thưởng Tết và các dịp lễ;...\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe 24/24;\n- Khám sức khỏe định kỳ 1 năm/ 1 lần tại bệnh viện Đại học Y Hà Nội;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm;\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày;\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành.\n- Miễn phí đồ uống tại khu ăn uống của công ty;\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLB Dance;...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm;...\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1406, 834, 2, 'Structural Engineer (Transportation Infrastructure)', 'Take on a role in leading international projects for the development of transport infrastructure such as bridges and tunnels Collaborate almost daily with other Haskoning offices and teams in other countries. And have ample opportunities to grow into roles such as design leader. Will you be our new infrastructure construction engineer?\n\nWhat will you do\n\nYou will join our team working on large international tunnel and infrastructure projects. Samples of projects you may contribute to:\n\n- New underground ring road of Antwerp: A major infrastructure project in Western Europe.\n- Blankenburg connection: Another significant project aimed at improving connectivity.\n- Fehmarnbelt tunnel in Denmark: One of the longest immersed tunnels in the world.\n\nThese projects aim to improve the living environment and present plenty of interesting and challenging issues to solve.\n\nYour daily responsibilities include:\n\n- Contributing to the development and execution of large-scale infrastructure projects\n- Solving complex engineering problems both independently and within a team\n- Collaborating with multidisciplinary teams to ensure project success\n\nWe support your career growth with extensive training opportunities and the freedom to choose your development path. Additionally, you can participate in working groups focused on sustainability, safety, and diversity within our organization.\n\nWhere you will work\n\nAt Haskoning, you will join an independent, employee-owned international consultancy that combines engineering, design, and consultancy services with software and technology. Our mission, "Enhancing Society Together," drives us to create a positive impact on the world.​\n\nWe offer purpose-driven and challenging work in diverse international projects, leveraging our 140+ years of expertise. With over 6,800 employees in more than 25 countries, we work together to turn challenges into opportunities and make a real impact on society. We collaborate with leading clients in markets such as infrastructure, climate resilience, renewable energy, decarbonisation of industry, and sustainable mobility.\n\nWhat you bring\n\nYou are a true team player. Collaborating with various professionals inside and outside your team is key to successful solutions for complex issues. You can also listen well, give and receive constructive feedback, and communicate clearly both orally and in writing. Furthermore:\n\n- A university degree in civil engineering in a relevant field of study\n- At least five years of experience as an (underground) construction engineer and an affinity with geotechnics\n- Proficiency in both English and Vietnamese for effective communication\n- Proficiency in computer analysis and design software i.e. SAP2000, STAAD Pro\n- Experienced in structural analysis and design of large civil structures (such as bridges or tunnels)\n- Experienced in structural design according to International design standards\n- Good understanding of BIM/Revit working environment (should have been involved in numerous projects)\n- Familiar with advanced analysis i.e. nonlinear or dynamic analysis will be beneficial.\n\nWhat we offer you\n\nIn addition to developing yourself within the most beautiful and challenging international projects, we also offer you:\n\n- A good balance between work and private life, including a company laptop so you can work where and when you want\n- Salary growth opportunities and attractive bonuses\n- Plenty of training and development opportunities and growth into roles such as design leader or team leader\n- On-the job training with your assigned buddy during your initial stage with us, along with numerous training programs throughout your career to support your personal development\n- Accident insurance for you as our employees and health insurance coverage for you and their family members\n- A supportive environment focused on personal development, job satisfaction, and collaboration\n- An independent, non-listed company with a clear strategy to make a positive difference in the world and invest in its employees and digital developments.\n\nAre you our new colleague?\n\nThen we would like to meet you! Apply now by sending in your English CV using the button below.\n\nAt Haskoning, we are committed to fostering a diverse and inclusive workplace where everyone feels valued, respected, and empowered. Our mission of "Enhancing Society Together" drives us to create an environment that embraces each individual’s unique background, identity, and perspective. Regardless of your experience, background, age, gender, or other personal characteristics—you are welcome here. We believe that diversity makes us stronger and that an inclusive culture gives everyone the opportunity to grow and contribute. Read more about our ED&I initiatives on our dedicated webpage.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1407, 835, 2, 'Java Developer', 'POSITION: Java Developer\n\nWorking Location: Hà Nội, Việt Nam\nSalary: Up to 40,000,000 VND\nLevel: SENIOR\nJob Description:\n• Tham gia phát triển và bảo trì hệ thống đồng bộ dữ liệu lớn\n• Phân tích thiết kế giải pháp cho yêu cầu của khách hàng theo full quy trình: System design, development, testing, implementation, support, maintainance, enhancement\n\nJob Requirements:\n• Must have: Tốt nghiệp Đại học chuyên ngành IT hoặc liên quan\n• Tối thiểu 4 năm kinh nghiệm phát triển dự án phần mềm sử dụng ngôn ngữ lập trình Java\n• Có kinh nghiệm với Spring Framework, Spring Boot\n• Có kinh nghiệm về Oracle\n• Có kinh nghiệm về MS SQL\nNice to have:\n• Có kinh nghiệm về công nghệ container như Docker\n• Có kinh nghiệm về K8S\n• Có kinh nghiệm triển khai và vận hành hệ thống trên hệ điều hành Linux\n\nBenefits:\n• 100% lương trong 2 tháng thử việc\n• Bảo hiểm toàn phần ngay từ thời gian thử việc\n• Lương 15 tháng\n• Khám sức khỏe 1 lần/năm\n• Bảo hiểm tai nạn\n• 300$/nhân viên/năm cho chương trình đào tạo cá nhân\n• Cơ hội đào tạo ở nước ngoài\n• Nhiều hoạt động nội bộ: team binding, team training,…\n• Quà tặng cho mỗi nhân viên vào các ngày 30/4, 1/5; 2/9;....(tiền mặt)\n• Thưởng cho nhân viên có chứng chỉ ngoại ngữ.\n• Làm việc 5 ngày/tuần để đảm bảo cân bằng giữa công việc và cuộc sống\n\nInterviewing Process:\n• 1 vòng offline', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Việt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1408, 836, 2, 'Senior Front End Developer (Vue.js) - 2700$', 'We are a market intelligence platform that delivers actionable data to companies from developing markets, revealing who is purchasing what, at what price, from where, when, and why, to support revenue growth and expansion. Our network of qualified mappers, spread across urban areas in over 40 countries in Africa and South Asia, collects data from their local regions.\n\nWe are seeking an experienced Senior Front End Developer to join our team to create dynamic and responsive user interfaces using Vue 3. As a Senior Front End Developer, you will be responsible for designing, developing, and maintaining web applications, ensuring the delivery of high-quality code that meets our clients’ needs.\n\nWorking location: Dich Vong Hau, Cau Giay, Ha Noi\nWorking time: Monday to Friday, 9 am to 6 pm\n1. Responsibilities:\n● Develop high-quality, responsive user interfaces using Vue 3 and related technologies.\n● Write clean, maintainable and testable code using industry best practices.\n● Collaborate with back-end developers to integrate front-end components with server-side logic.\n● Participate in code reviews and contribute to continuous improvement of development processes.\n2. Requirements:\n● At least 5 years of experience in front-end development, with a focus on Vue.js.\n● Strong experience with Vue 3 and its ecosystem.\n● Knowledge of relational databases, such as MySQL or PostgreSQL.\n● Knowledge of RESTful architectural style and integration with back-end services.\n● Excellent problem-solving skills and attention to detail.\n● Ability to work independently and as part of a team.\n● Ability to read, understand, and communicate effectively in English.\n3. Benefits:\n● Competitive salary (up to $2.7k NET), biweekly payment.\n● Opportunities for career advancement and professional growth.\n● Working in a professional, young and dynamic environment.\n● Provided with a working computer or other necessary technology/equipment to perform job duties.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1409, 808, 2, 'Junior Software Developer - Da Nang', 'Job Description\n\nSupport senior developers and team lead to build features according to business requirements.\nWrite design documents\nFix bugs and build feature changes as required\nMonitor code performance and support senior developers/ team lead to optimize performance\n\nRequirements\n\nCollege or university graduated, major in computer science or IT or equivalent\nKnowledge of object-oriented programming and .NET (C#)\nProficient in using Visual Studio or Microsoft technology, HTML5, CSS3, JavaScript is an advantage\nHaving a sense of responsibility, persistence\nAble to work independently and in a team\nBasic spoken and written English\n\nWork Location\n\n2F Vinh Trung Plaza, No. 255-257 Hung Vuong, Vinh Trung, Thanh Khe, Da Nang\n\nBenefits\n\n5-day workweek\nYoung & vibrant working environment with great career development opportunities\nSocial insurance, medical insurance, unemployment insurance, are based on actual salary\nYearly performance bonus (up to 2 months’ salary)\nRegular team building events & internal activities (weekly happy hour, quarterly team building events, festival parties, etc.)\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1410, 366, 2, 'Backend Engineer (Java/Spring)', 'We are looking for Backend Engineers (Java) for GSaaS project.\n\nYour daily tasks:\nResponsible for developing and maintaining the server-side components using the Java programming language.\nWrite and maintain technical documentation, including system architecture and API specifications.\nTake a look at NAVER WORKS services HERE.\n\nYour background:\n4+ years of work experience on related work.\nBachelor\'s degree or above in Computer Science or related field.\nGood Java basic skills, experience with multi-threaded programming, IO, JVM garbage collection.\nExperience with Java performance tuning and find and resolve troubleshoot experience with Spring, Spring MVC, Spring Boot, MyBatis, MySQL, High Availability, High Concurrency Related Technologies.\nExperience with Linux basic command, independently complete project deployment, troubleshooting.\nOpen-minded, honest and have a positive attitude towards people.\nGood at communication skills in general and English skills in particular.\n\nIt\'s a big plus if you:\nExperience with big data projects, Kafka & Hbase.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\nCompetitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\nLearning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills...\nProtecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\nEmployee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\nWorking environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7...\nDedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\nOther benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1411, 837, 2, 'AI Resident (Engineering)', 'Company\nQualcomm Vietnam Company Limited, Hanoi Branch Office\n\nJob Area\nInterns Group, Interns Group > AI Resident\n\nQualcomm Overview\nQualcomm is a company of inventors that unlocked 5G ushering in an age of rapid acceleration in connectivity and new possibilities that will transform industries, create jobs, and enrich lives. But this is just the beginning. It takes inventive minds with diverse skills, backgrounds, and cultures to transform 5Gs potential into world-changing technologies and products. This is the Invention Age - and this is where you come in.\n\nGeneral Summary\nThe Qualcomm® AI Residency Program is a distinguished training ground for exceptional AI talent. It identifies and cultivates top young minds, shaping them into world-class AI experts and future industry leaders.\n\nQualcomm is opening applications for Engineering Residency Batch 1.\n\nAbout the Engineering Residency Program (ERP) (12 months): Residents will address practical AI engineering challenges in domains such as efficient AI, embedded engineering, and agentic AI. Engineering residents will develop robust engineering capabilities and engage in research rotations to become versatile, inquisitive AI engineers.\n\nEligibility & Qualifications\n• Final-year students or recent graduates in Computer Science (or cognate fields) from Vietnamese or international universities.\n• Minimum GPA: 3.2/4.0 or 8.0/10 or equivalent.\n• Strong, self-driven interest in research and ability to learn complex technical material.\n• Exceptional aptitude in mathematics and coding. Preference given to candidates with demonstrated abilities (e.g., research experience, competitions, GitHub repos, AI coursework).\n• Familiarity with Python and AI frameworks like TensorFlow, PyTorch, or Keras\n• Competent English language skills in reading, writing, and speaking. Specialized technical English communication training will be provided.\n• Corporate internship experience is a plus.\n\nKey Responsibilities\n• Collaborate with cross-functional teams to design, build, and deploy AI solutions for various applications.\n• Assist in data preparation, model training, and algorithm selection under the guidance of engineer mentors.\n• Conduct experiments and tests to evaluate the performance of AI models and optimize them for production.\n• Write clean and maintainable code that supports the development and deployment of AI systems.\n• Stay updated with the latest AI trends and technologies to bring innovative ideas to the team.\n\nSelection Process\nThe Qualcomm AI Residency Program employs a rigorous multi-stage selection process. The standard procedure includes the following rounds:\n• Application\n• Screening\n• Portfolio review\n• Coding interview\n• Video presentation\n• Technical interview\n\nA fast-track application is available for academically outstanding students who have demonstrated exceptional achievements, such as winning high prizes in International Olympiads in Mathematics, Informatics, or prestigious international programming competitions like ACM-ICPC. Applicants eligible for the fast-track process will be contacted separately.\n\nATTENTION: Your application must include the following documents:\n• Resume\n• Academic transcript\n• Academic diploma (if already graduated)\n• A letter of recommendation is optional but strongly encouraged.\n\nPlease combine all documents into a single PDF file and upload it with your application. Incomplete applications may not be considered.\n\nFor applicants in their final year of undergraduate study, a provisional graduation certificate is acceptable in place of the diploma.\n\nApplicants: Qualcomm is an equal opportunity employer. If you are an individual with a disability and need an accommodation during the application/hiring process, rest assured that Qualcomm is committed to providing an accessible process. You may e-mail myhr.support@qualcomm.com or call Qualcomm\'s toll-free number found here. Upon request, Qualcomm will provide reasonable accommodations to support individuals with disabilities to be able participate in the hiring process. Qualcomm is also committed to making our workplace accessible for individuals with disabilities.\n\nQualcomm expects its employees to abide by all applicable policies and procedures, including but not limited to security and other requirements regarding protection of Company confidential information and other confidential and/or proprietary information, to the extent those requirements are permissible under applicable law.\n\nTo all Staffing and Recruiting Agencies: Our Careers Site is only for individuals seeking a job at Qualcomm. Staffing and recruiting agencies and individuals being represented by an agency are not authorized to use this site or to submit profiles, applications or resumes, and any such submissions will be considered unsolicited. Qualcomm does not accept unsolicited resumes or applications from agencies. Please do not forward resumes to our jobs alias, Qualcomm employees or any other company location. Qualcomm is not responsible for any fees related to unsolicited resumes/applications.\n\nIf you would like more information about this role, please contact Qualcomm Careers.\n\n3076026', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1412, 838, 2, 'Java Developer', 'OVERVIEW\nAs a Mid/Senior-Level Java Developer, you will collaborate with Product Managers, UX/UI Designers and Developers, and Sales and Marketing teams to create and enhance localization web apps, or plugins/connectors for content management systems, eCommerce platforms, or product information management (PIM) systems. Your responsibilities will span the full software development lifecycle, including UI enhancements, database design, and overall product functionality, in a dynamic and technology-driven environment.\n\nDESCRIPTION\n- Develop and enhance localization web apps, or plugins and connectors.\n- Collaborate with cross-functional teams to meet product requirements.\n- Contribute to all aspects of product development, from UI functionality to database schema design.\n\nREQUIRED SKILLS\n- Strong expertise in Java/J2EE, and Spring framework.\n- Proven track record of successfully implementing all project life cycle stages from requirements implementation and enhancements, for several projects.\n- Proficiency in:\n  - Building REST-based services\n  - Writing clean, well-structured, and maintainable code that adheres to best practices and coding standards, including OWASP.\n  - Risk assessments and screenings of features, architectures, libraries, and 3rd party tools.\n  - SQL and NoSQL databases.\n\nExperience working with:\n- Spring modules like MVC, Core, Boot, Security, Data, and Data JPA, or equivalent technologies.\n- API documentation tools, like Swagger.\n- Libraries and stacks for logging, monitoring, and data analysis, like Logback, SLF4J, and ELK Stack.\n- Creating diagrams, descriptions, and flowcharts as part of system and feature documentation.\n- Unit tests for example with JUnit Mockito.\n\nYou:\n- Speak and write Business level English fluently, and adapt your communication to fit the audience.\n- Work creatively and independently, but in close collaboration with other roles and teams.\n- Maintain a strong sense of ownership of your work and project outcomes.\n- Have excellent problem-solving, analytical, and communication skills.\n- Adapt easily to multiple technologies.\n- Enjoy working in small and fast pace teams, with fast iterations, prototyping, and demos.\n- You are comfortable with shifting your working hours 1-2h to fit other time zones a few times a week.\n\nREQUIRED EXPERIENCE AND QUALIFICATIONS\n- 3+ years of experience in Software Design and Development.\n- Bachelor’s degree in computer science or equivalent experience.\n\nDESIRED SKILLS AND EXPERIENCE\n- Content management and Integration experience\n- Development tools like GIT, Maven, Docker, NGINX, Jenkins, and JIRA is a bonus.\n\nEnd your job search and find your career at TransPerfect #careersNOTjobs.\n\nWHY TRANSPERFECT:\nFor 30 years, we have honed a culture where all kinds of ideas are shared and new ventures are not only welcomed, but also encouraged. In this fast-paced environment, employees are intellectually stimulated so they can grow alongside the organization. From Intern to President, we believe that every single employee should have a voice and contribute to the amazing services we offer our clients.\n\nFor more information on the TransPerfect Family of Companies, please visit our website at www.transperfect.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1413, 839, 2, 'Full-Stack Developer (NodeJS, ReactJS)', 'Working Time: 8h30-17h30 Monday to Friday\nLocation: 319 Tower, 63 Le Van Luong, Trung Hoa, Cau Giay, Ha Noi\nSalary: Competitive, based on experience\n\nAbout us:\nFounded in 2020, Var Meta has 80+ engineers heavily focused on blockchain, virtual reality/augmented reality technologies and AI. We work with customers from different parts of the globe like Hong Kong, Japan, Singapore, US to help them build products like Crypto Trading Platform, Launchpad, Securities Tokenization Offerings, eWallets, and NFT Marketplace, etc. We are trusted by global brands like Ubisoft, Hedera, Aptos.\n\nAbout this opportunity:\nWe\'re looking for a Full-Stack Developer to join our team with NodeJS & ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc. who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.\n\nYou will:\n- Working with Product Owners to convert business requirements into technical designs.\n- Working and pair programming with other developers to build applications with Node.JS and ReactJS.\n- Design and develop scalable front-end solutions using ReactJS.\n- Build and maintain robust back-end systems with NodeJS.\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n- Collaborate with cross-functional teams to define, design, and ship new features.\n- Ensure code quality, security, and performance optimization.\n\nYour Skills and Experience:\n- Knowledge of responsive design techniques and front-end optimization methods.\n- At least 2-3 years of experience as a Full-Stack Developer (Node.js & React.js).\n- Strong proficiency in front-end technologies, particularly React.\n- Expertise in back-end development using Node.js.\n- Hands-on experience with Web3 integration.\n- Solid understanding of smart contract development and deployment.\n- Good command of English (both verbal and written).\n- Knowledge of cryptography and blockchain is a plus.\n\nWhy You\'ll Love Working Here:\n- Build World class product(s): We love to solve complex problems and learn new things.\n- Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n- Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n- Enjoy competitive salary, bonus according to work performance.\n- 13th Salary.\n- Assistance with operational tools and equipment.\n- Health insurance program for employees provided by PVI.\n- Annual health check-up from Medlatec Clinic.\n- Participate in social insurance after becoming an official employee.\n- Salary review twice a year. It means we are pushing each other to be better everyday.\n- Flexible working hours, freestyle attire.\n\nPerks You\'ll Enjoy:\n- Working in a young, super talented, and supportive team environment.\n- Technical, English certificate bonus.\n- Day-off: 12 days/year and Vietnam holidays.\n- Happy Hour, Football club, English club, and many exciting activities.\n- Company trip/ team building/ Year End Party.\n- Free coffee, snacks, and drinks.\n\nContact HR Var Meta via:\n- Email: hr@var-meta.com\n- Fanpage: https://www.facebook.com/profile.php?id=61558234221306', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1414, 840, 2, 'BACKEND / FULLSTACK DEVELOPER – MICRO SERVICE SYSTEMS', '🎯 Job Objective\nWe are looking for a Backend Engineer to join our product team in building scalable SaaS platforms and automation workflows based on microservice architecture. You will work closely with AI and Marketing teams to integrate AI solutions into business operations — including CRM systems, automation tools, chatbots, and more.\n\n🔧 Key Responsibilities\n- Design and develop backend systems using microservice architecture\n- Build robust API services (RESTful, GraphQL) for frontend, automation tasks, and AI modules\n- Integrate with third-party services such as Facebook API, Zalo, Google Sheets, Telegram, PayOS, etc.\n- Optimize system performance, security, and scalability\n- Collaborate closely with frontend developers, AI engineers, and operations teams to ensure on-time delivery\n\n✅ Required Qualifications\n- Proficient in Node.js, Python (FastAPI), PostgreSQL, Redis, and Docker\n- Solid experience with microservices and event-based architecture (e.g., RabbitMQ, Kafka)\n- Strong understanding of CI/CD pipelines, Git workflows, and scalable system design\n- Hands-on experience with SaaS product development or workflow-based platforms\n- Strong problem-solving skills and clean, maintainable coding practices\n\n🌟 Nice to Have (Optional)\n- Familiarity with DevOps practices (e.g., internal server builds, self-hosted AI models)\n- Experience working with AI systems, n8n, or workflow automation platforms\n- Ability to handle frontend tasks with ReactJS, TailwindCSS, and Vite\n\n🚀 Why Join Us?\n- Be part of an ambitious team building next-gen automation tools\n- Direct impact on business operations across industries\n- Collaborative and growth-driven environment with AI integration at the core.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1415, 755, 2, 'Junior Android Engineer - Hybrid working model 100%, Ho Chi Minh City', 'Welcome to SMG Vietnam! SMG Swiss Marketplace Group simplifies lives with innovative online marketplaces in Automotive, Real Estate, General Marketplaces, and Finance & Insurance. As SMG’s innovation hub, SMG Vietnam develops cutting-edge solutions in a collaborative, empowering environment. Recognized among the 2023 Asia & Vietnam Best Workplaces, we attract top digital talent to create exceptional user experiences for Switzerland. Guided by our core values—Better Together, Aim High, and Act Responsibly—we drive innovation and meaningful change. This job refers to our Real Estate brands, Homegate and Immoscout24, the largest real estate portals in Switzerland, with more than 15 million visits per month and more than 100,000 listings. We provide all users looking for a property with a transparent overview of the entire range of listings without them having to tediously visit different platforms. In addition to great products such as the mortgage or price calculator, we also offer editorial articles on topics such as housing and financing. We are looking for an Junior Android Engineer who is passionate about mobile development and eager to work on high-quality Android application. As a key contributor to our mobile engineering team, you will focus on delivering clean, efficient, and reliable code, working closely with other engineers, designers, and product managers. This role is ideal for an engineer looking to deepen their Android expertise and contribute to complex projects in a supportive environment. Join our dynamic team, located in six countries (Switzerland, Serbia, Vietnam, France, Germany, and India), where creativity thrives. Together, we tackle challenges, celebrate successes, and keep learning and growing. Your Mission: Assist in designing, developing, and maintaining Android applications, focusing on clean, maintainable code. Collaborate closely with product managers, designers, and senior engineers to implement new features and enhancements. Participate in code reviews, learn from feedback, and apply best practices to improve code quality. Write Unit and UI tests with guidance to ensure code reliability. Learn and apply modern Android architecture patterns to build scalable features. Continuously improve your skills and contribute to the team\'s knowledge-sharing culture. Help identify and fix bugs, optimize performance, and support releases under the guidance of more experienced team members. Stay curious and up-to-date with Android development trends, tools, and best practices. Your responsibilities will evolve as we grow. What will you bring to the ride? Fluency in English written and verbal communication. Bachelor’s degree in Computer Science, Engineering, or a related field, or equivalent work experience. 1+ year of experience developing Android applications in Kotlin (Java is a plus). Basic understanding of Android components and tools (e.g., Activities, Fragments, Android Studio). Some exposure to modern development practices such as MVVM, Jetpack components, or reactive programming is a plus. Willingness to learn and apply best practices in mobile development, testing, and architecture. Comfortable with consuming REST APIs and working with local storage (e.g., Room, SharedPreferences). Curious, open-minded, and enthusiastic about growing in a collaborative team environment. Nice-to-Have Qualifications: Exposure to CI/CD, version control (e.g., Git), or test automation frameworks. Awareness of mobile app performance and monitoring tools (e.g., Firebase, Datadog). Familiarity with privacy, security, or accessibility in mobile apps. We value the skills you bring and your ability to learn quickly, so don’t worry if your career path has been unique. What do we offer? Competitive Benefits: Attractive salary, full pay during probation, 13th-month bonus, and full social insurance contributions. Generous Leave: 21+ annual paid days off, 24 days for learning & sharing, and flexible working hours with no overtime. Health & Wellness: Premium private insurance for you and your family, free food, and access to various classes and clubs. Growth Opportunities: Personalized development plans, yearly education budgets, regular Hackathons, and potential travel to Switzerland and Europe. Modern Work Environment: Hybrid model, top-tier equipment, and a friendly, agile, and transparent culture. Supportive Onboarding: Comprehensive assistance to help you settle in. Recruitment Process: We believe hiring is a two-way street, where both parties get to know each other. Here\'s what you can expect: Initial screening call with HR – A brief conversation to understand your background and expectations. Meeting with the Hiring Manager – A deeper discussion about the role, your experience, and how we work. Home assignment – A small project to showcase your skills in a real-world context. Technical Assessment – A follow-up session to review your assignment and discuss technical topics in more detail. Casual Meeting with Director – An informal conversation to align on vision, culture, and goals. At SMG Vietnam, we value diverse perspectives and individual growth. We welcome candidates from all backgrounds and encourage you to apply, even if you don’t meet every requirement. Together, we embrace differences, nurture potential, and celebrate success. Apply now: To take this opportunity, send us your detailed CV and feel free to add any supporting documents we need to look at in order to understand that you are the perfect fit. About Us: SMG Swiss Marketplace Group AG. is a pioneering network of online marketplaces and cutting-edge European digital company that simplifies people’s lives with innovative products. SMG Swiss Marketplace Group AG. provides customers the best tools to meet their life decision needs. The portfolio includes Real Estate (ImmoScout24, Homegate, Flatfox, alle-immobilien.ch, Immostreet.ch, home.ch, Publimmo, Acheter-Louer.ch, CASASOFT, IAZI), Automotive (AutoScout24, MotoScout24), General Marketplaces (anibis.ch, tutti.ch, Ricardo) and Finance & Insurance (FinanceScout24, moneyland.ch). The company was founded in November 2021 by TX Group AG, Ringier AG, La Mobilière and General Atlantic. Disclaimer: SMG Swiss Marketplace Group AG primarily engages directly with candidates. We do not accept unsolicited resumes or candidate profiles from recruitment agencies unless we have specifically requested their assistance for particular roles. Any submissions made without a prior request from our Talent Acquisition team will not be acknowledged or considered. We appreciate the understanding and cooperation of recruitment agencies in respecting this policy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Củ Chi district, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1416, 841, 2, 'Lập trình viên PHP', 'Mô tả công việc\n\n- Tham gia phát triển, tối ưu các chức năng trên hệ thống E-learning tại website www.hocmai.vn và các hệ thống tác nghiệp khác.\n- Phân tích, thiết kế và phát triển các chức năng theo nhu cầu của người dùng và yêu cầu từ các bộ phận tác nghiệp khác.\n\nKhông yêu cầu', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1417, 676, 2, 'Java Software Engineer', 'Overview:\n\nHow would you like to join an international software development center in Vietnam to learn, to grow personally as well as professionally, and to gain valuable experience in a fast-paced development environment?\n\nAn exciting and challenging opportunity has been available for those who are passionate about learning and building applications using Java.\n\nYour primary responsibilities will include develop, and maintenance and perform assurance of software products. The successful candidate will be part of a high-performing development team in a high frequency/low latency environment.\n\nLocation & Program Schedule: \n\n• Training hour: Monday through Friday, 9:00AM – 6:00PM\n• Address: Etown 5, 364 Cong Hoa, Ward 13, Tan Binh District, HCMC\n\nRequirements:\n\n• Graduated from universities or colleges with relevant majors such as Information Technology, Computer Science, etc.\n• 1 year experience in Java Developer\n• Good knowledge in Object-oriented programming concept.\n• English communication skills, prefer having an English Certificate.\n• Has knowledge or relevant work experience in any of the following programming languages or technologies: Java/Java EE, .NET, C#,…\n• Ability to learn in a short time and work under pressure\n• Experience working in an international software development project will be advantageous.\n• Good analytical and communication skills\n• Be able to work independently and in a workgroup.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1418, 786, 2, '【教育事業】ソフトウェアエンジニア（データサイエンス）', '職務内容様々な授業を受けることができるWeb上の学習サービス「ZEN Study」や先生向けのコーチング支援Webサービス「ZEN Compass」、また関連する教育サービスのデータ活用をメインにした技術検証・それをアプリケーションに実装していく部分を担当していただきます。私たちは、未来の「当たり前」の教育をつくるため、生徒・学生や教職員の「学ぶ」「教える」体験の最大化を日々目指しています。2025年4月に開学予定の日本発の本格的なオンライン大学「ZEN大学」や、2万名を超え日本最大の生徒数であるネットの高校「N高等学校・S高等学校・R高等学校」と連携し、ネットの時代に合わせた教育関連のサービスを開発・運営しています。ひとつで学習が完結するオールインワン学習アプリです。主に次のような機能を提供しています。・リアルタイムに先生や仲間の生徒とコミュニケーションを取ることで理解を深める「ライブ授業」・自分のペースで学習を進めることができて一目で進捗率がわかる「教材」・学習者同士の教え合いの場「フォーラム」※「N予備校」は2024年8月末に「ZEN Study」にリニューアルしました学習者を導く先生方などが利用するコーチング支援Webサービスです。LMS(Learning Management System)として学習状況を見ることができるだけではなく、より学習者を効率的に支援できるように、さまざまな指標で先生方を支えます。私たち「ZEN Study（旧: N予備校）」の企画開発チームは、企画者とエンジニアの混合チームです。あらゆる学びたい人たちの、ひとりではなかなか学習が継続しないという課題に対して、彼らを自律的に生涯学習ができるような状態にできるようなサービスを目指し、日々企画開発を行っています。「ZEN Study（旧: N予備校）」に日々蓄積されていくN高等学校・S高等学校の生徒の学習ログなどのデータを元に、それぞれの学習者が効果的に学べる、学び続けることができる学習サイクルをどのように実現していくか検討し、データを活用した新サービスの技術検証、企画への提案・実際のアプリケーションの設計・実装を行えるようなデータサイエンス領域のソフトウェアエンジニアを募集しています。学習アプリ「ZEN Study（旧: N予備校）」やコーチ向けの「ZEN Compass」、または関連する教育サービスのデータ解析・技術検証、検証結果の実サービスへの適用に関わる設計・実装を主業務とし、必要に応じて企画者や教材開発者とのコミュニケーションを行なっていただきます。主業務の一例：・新企画の技術検証・機能開発に向けた設計・実装新企画構築に向けてさまざまな理論や手法を適用できるかを検証・プロトタイピング例：学力測定や行動理解のためのデータ分析、アダプティブラーニングやレコメンドなどのデータ活用型アプリケーションの実現など仮説検証後の課題抽出・企画への提案・データ解析基盤の構築・運用・改善他チームと協力しながらN予備校のデータを収集する部分の 検証・設計・構築実際に企画検証としてデータ解析を行い不足データの提案・設計・構築・企画開発と企画開発チームのための種々の業務業務知識や開発知識のドキュメンテーションカジュアル面談や選考への参加などの採用活動技術検証や解析によって変わりますが、代表的なものを記載します。使用言語/ライブラリ・Python・SQL・terraform（必要に応じて利用がある言語）・Ruby/Ruby on Rails・JavaScript・RPublic Cloud・GCP BigQuery, Cloud Functions, Cloud Storage…・AWS S3, RDS, Lambda…使用ツール・Figma, Miro・GitHub・Google Meet, Zoom・Slack, Google Workspace, JIRA, Confluence・Google Analytics・エンジニア採用説明資料https://speakerdeck.com/nnndev/for-engineers同じチームのエンジニアによる技術ブログhttps://blog.nnn.dev/entry/2021/06/17/110000https://blog.nnn.dev/entry/2022/05/16/110000https://blog.nnn.dev/entry/2022/07/22/110000https://blog.nnn.dev/entry/luigi-pipeline-visualization□ ZEN Studyhttps://www.nnn.ed.nico/□ N高等学校・S高等学校・R高等学校プロジェクト採用https://www.nnn.ed.nico/recruit/□ ZEN大学https://zen.ac.jp必須要件・コンピューターサイエンスの基礎知識を身に着けている・Webサービスやアーキテクチャの基礎知識を身につけている・統計の基礎知識を身につけている・データ解析およびサービス適用の実務経験がある・標準的なプログラミングスキルを持っている（プログラミング言語を用いて実務に必要な分析を実行できる。GUIでの経験は含めない）歓迎要件・サービスのパーソナライズのためのデータ分析基盤設計の実務経験がある・大規模なデータ解析の実務経験がある・教育測定や心理統計の知識、経験がある・Webアプリケーションの開発経験が3年以上ある、または相当の知識がある・GCPまたはAWSのサービスを業務で2年以上使用した経験がある、または相当の知識がある・データ収集基盤やDWHの構築経験がある・エンジニアチームのマネジメント経験・データ解析プロジェクトのマネジメント経験・教育に携わる意欲がある求める人物像・論理的思考力の基礎を身に付けている方・困難な課題に対し現実的な課題の再定義をしたりその解決方法を見いだしたりできる方・様々なステークホルダを巻き込んで議論を推進していける方・ものごとを多角的な視点から考えることができる方・ユーザーにより良い学習体験を届けることを中心に考えられる方職種 / 募集ポジション 【教育事業】ソフトウェアエンジニア（データサイエンス）雇用形態 正社員給与 応相談 前職を考慮し、当社基準により決定いたします。昇給：年2回（6月・12月）本人の能力・役割に基づいて評価賞与：年2回（6月・12月）本人の成果に基づいて支給 ※ご入社時期、個人の評価、会社の業績により夏季賞与・冬季賞与額が変動いたします。 ※退職金は前払い退職金制度勤務地 104-0061 東京都中央区銀座四丁目12-15 歌舞伎座タワー勤務形態 裁量労働制（1日8時間のみなし労働)休日休暇 完全週休2日制（土・日）、祝日（※超会議に伴う営業日変更あり） ・年次有給休暇（入社日に5日、入社日の3ヶ月後に15日付与）・記念日休暇・年末年始休暇（12/29～1/3）・リフレッシュ休暇（年度ごとに2日間付与）・特別（慶弔）休暇手当・制度 ・テレワーク手当 ※テレワーク対象となる社員（条件有り）に対し、月額2万円を支給・通勤交通費手当（上限月額50,000円） ※テレワーク対象者は原則支給しない ただし、業務指示における出社時の交通費は会社が認める範囲で別途支給・育児手当（上限月額50,000円） ※扶養の子の保育料の半額を支給・役職手当（役職に応じて支給）・資格取得手当制度・サブスク手当（対象のサブスクを契約している場合、月額2千円を支給）福利厚生 ・各種社会保険完備（関東ITソフトウェア健康保険組合）・確定拠出年金制度・財形貯蓄制度・社員持株会制度・社内カウンセリング制度・同好会・健康保険組合各種サービス・社員限定美容室選考プロセス 書類選考後、2回の面接を想定しています。 ※1次面接までに当社が指定する適性検査を受検いただきます。 ※全てオンライン面接となります。 ※選考の過程でコードテストを実施する可能性があります。会社情報会社名 株式会社ドワンゴ代表者 代表取締役社長 夏野 剛事業内容 ネットワークエンタテインメントコンテンツ及びシステムの企画、開発、運用、サポート、コンサルティング設立 1997年8月6日資本金 1億円（2019年3月29日現在）所在地 〒104-0061 東京都中央区銀座4-12-15 歌舞伎座タワー親会社 株式会社KADOKAWA子会社 株式会社バンタン 株式会社スパイク・チュンソフト Spike Chunsoft, Inc. 株式会社バーチャルキャスト 株式会社カスタムキャスト 株式会社GeeXPlus 株式会社PUBLUS', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 12, Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1419, 842, 2, 'LẬP TRÌNH VIÊN (ASP.NET)', 'Mô tả công việc\n\n- Xây dựng các website chuẩn SEO cho công ty và các đơn vị thành viên trên ngôn ngữ C# ASP.NET & SQL sever\n- Tham gia lập trình các module mở rộng trên nền tảng .NET cho phần mềm CRM của công ty.\n- Thực hiện các công việc khác theo yêu cầu của Trưởng bộ phận.\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1420, 843, 2, 'Software Engineer II', 'Global Fashion Group is the leading fashion and lifestyle destination in growth markets across LATAM, CIS, SEA and ANZ. From our people, to our customers and partners, we exist to empower everyone to express their true selves through fashion. Our four e-commerce platforms: dafiti, lamoda, ZALORA and THE ICONIC connect an assortment of international, local and own brands to more than one billion consumers from diverse cultures and lifestyles. GFG’s platforms provide seamless and inspiring customer experiences from discovery to delivery, powered by art & science that is infused with unparalleled local knowledge. Our vision is to be the #1 online destination for fashion & lifestyle in growth markets, and we are committed to doing this responsibly by being people and planet positive across everything we do.\n\nAbout The Function\nAt GFG, Technology is core to long-term success and is a crucial enabler of a great Customer Experience. We are a mix of experts in fashion, logistics, data analytics, marketing, and design, guided by business consultants and tech geniuses – everyone contributes to the success of GFG.\n\nAbout The Role\nIn this role as Software Engineer II you will be working closely with other people in the teams to provide architectural vision and strategy for GFG’s internal tools suite, and you will have the capability to provide detailed technical guidance to the team, enabling them to execute more effectively and deliver products on time.\n\nYou will also investigate the latest technologies to improve site reliability, the developer experience and raw performance.\n\nWhat Will You Do\n• Work in an agile environment to develop a best-in-market experience\n• Write and maintain clean and well-tested code\n• Work on distributed systems at scale with high traffic workloads\n• Collaborate with other software engineers and stakeholders in your team to build and maintain APIs in our microservices architecture (Kubernetes)\n\nWhat Will You Bring To The Team\n• BS/MS in Computer Science or related technical discipline\n• 2+ years of experience with high-traffic distributed systems and client-server architectures\n• A solid foundation in computer science, with strong competency in data structures, and algorithms\n• Proficiency in one high-level programming language such as Python, Golang, PHP..\n• Familiarity with a testing framework\n• Experience designing and building APIs\n• Experience with distributed systems and client-server architectures\n\nLife at GFG\n• #1 IT company to work for in Vietnam in 2021\n• Best practice scaled agile engineering\n• Amazing office and great culture! Massage chairs, table tennis, video game room, quarterly team events, yearly company trip, end of the year party\n• Hybrid working environment and work from home set up allowance\n• Clear career progression plan and support\n• English classes\n• Macbook or laptop when you start\n• Social insurance, medical insurance & AON insurance\n• 13th month salary\n• 15 days of annual leave, 30 days of sick leave/mental health, 1 day of occasion leave\n• Support for Gym membership\n• VND 60,000,000 referral reward for successfully referring someone to GFG\n\nApply today and join GFG in this exciting role shaping the face of fashion e-commerce! \nGlobal Fashion Group embraces diversity and equality of opportunity. We are committed to building an inclusive and diverse team representing all backgrounds, with as wide a range of perspectives as possible, and harnessing industry-leading skills. We believe that the more inclusive we are, the better our work will be. We welcome and consider applications to join our team from all qualified candidates, regardless of their characteristics. We comply with all applicable laws and regulations on non-discrimination in employment (and recruitment), as well as work authorization and employment eligibility verification requirements.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1421, 723, 2, 'Software Developer', 'Vị trí: Software Developer\n\nĐịa điểm làm việc: Tầng 3A, tòa nhà Mỹ Đình Plaza, số 138 Trần Bình, Nam Từ Liêm, Hà Nội.\n\nMô Tả Công Việc\nTriển khai xây dựng các giải pháp cổng giáo dục trực tuyến, hệ thống quản lý tri thức (KMS), hệ thống quản lý quan hệ khách hàng (CRM), hệ thống trả lời khách hàng (Call Center)\nXây dựng các hệ thống ERP trên nền điện toán đám mây\n\nYêu Cầu\nJava SE,EE 1 năm kinh nghiệm trở lên\nCSS + HTML5 thành thạo.\nOracle, my SQL 1 năm kinh nghiệm trở lên.\nƯu tiên các ứng viên thành thạo nodeJs.\nƯu tiên các ứng viên có kinh nghiệm sử dụng các platform Liferay, WordPress.\nƯu tiên các ứng viên có kinh nghiệm Spring , hibernate.\n\nQuyền Lợi\nCơ hội tham gia xây dựng các giải pháp Công nghệ thông tin mới, cung cấp các dịch vụ có ích cho xã hội.\nThu nhập hấp dẫn\nMôi trường làm việc linh hoạt\nCơ hội thăng tiến và phát triển bản thân\n\nLiên Hệ\nMs. Hương.\nMobile 0973 801 291\nTel 0473 008 555\nEmail Letan@nms.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1422, 844, 2, 'Kiến trúc sư giải pháp quảng cáo, Bộ phận quảng cáo gTech, khối Khách hàng chiến lược', 'Please visit this Google Careers posting for the English-translated version of this role. Minimum qualifications:\n\n- Bằng cử nhân hoặc kinh nghiệm thực tế tương đương. \n- Kinh nghiệm thiết kế hệ thống hoặc thành thạo một ngôn ngữ lập trình (ví dụ: Java, C++, Python và các ngôn ngữ tương tự).\n- Kinh nghiệm khắc phục sự cố kỹ thuật và quản lý khách hàng hoặc đối tác nội bộ/bên ngoài.\n\nPreferred qualifications:\n\n- Kinh nghiệm quản lý dự án/chương trình và có khả năng quản lý đồng thời nhiều dự án. \n- Kinh nghiệm làm việc trong ngành quảng cáo và công nghệ.\n- Kinh nghiệm trong một lĩnh vực chuyên ngành, hiểu biết các xu hướng và thử nghiệm kinh doanh liên quan đến khía cạnh kỹ thuật số.\n- Kinh nghiệm xây dựng bằng chứng về tính khả thi bằng cách sử dụng công nghệ web/viết tập lệnh (ví dụ: JavaScript, PHP, Python) và cơ sở dữ liệu SQL.\n- Khả năng hiểu các khái niệm kỹ thuật và truyền đạt chúng cho người không chuyên.\n- Kỹ năng cộng tác xuất sắc với các nhóm kinh doanh, kỹ sư giải pháp, v.v.\n\nAbout the job: Bộ phận Quảng cáo gTech chịu trách nhiệm cung cấp toàn bộ dịch vụ hỗ trợ, truyền thông và kỹ thuật cho những khách hàng thuộc mọi quy mô đang sử dụng các sản phẩm Quảng cáo của Google. Chúng tôi giúp khách hàng khai thác triệt để các sản phẩm Quảng cáo và sản phẩm dành cho Nhà xuất bản, đồng thời hướng dẫn khách hàng khi họ cần trợ giúp. Chúng tôi cung cấp đa dạng dịch vụ, từ dịch vụ hỗ trợ khách hàng tự giải quyết vấn đề và hỗ trợ bên trong sản phẩm, cho đến hỗ trợ tốt hơn thông qua các phiên tương tác, thiết lập tài khoản và triển khai chiến dịch quảng cáo, cung cấp giải pháp truyền thông theo nhu cầu kinh doanh và tiếp thị của khách hàng, cung cấp các giải pháp kỹ thuật và đo lường phức tạp, đồng thời hỗ trợ tư vấn cho các khách hàng lớn của chúng tôi. Các giải pháp này có thể được thiết kế riêng và điều chỉnh phù hợp với từng khách hàng, hoặc có thể mở rộng cho hàng triệu khách hàng trên toàn thế giới. Dựa trên nhu cầu ngày càng tăng của khách hàng đối với dịch vụ quảng cáo, chúng tôi hợp tác với nhóm Bán hàng, nhóm Sản phẩm và Kỹ thuật tại Google để phát triển những giải pháp, công cụ và dịch vụ tốt hơn, nhằm cải thiện sản phẩm và nâng cao trải nghiệm cho khách hàng. Là một phòng ban liên ngành và hoạt động trên toàn cầu, chúng tôi đảm bảo khách hàng luôn nhận được lợi tức đầu tư tối ưu khi hợp tác với Google và chúng tôi luôn là đối tác đáng tin cậy.\n\nBộ phận Quảng cáo gTech cung cấp các dịch vụ công nghệ nền tảng và những giải pháp kinh doanh tiên tiến cho nhà quảng cáo. Thông qua việc tư vấn kỹ thuật và triển khai các giải pháp truyền thông, Bộ phận Quảng cáo gTech giúp khách hàng đạt được mục tiêu kinh doanh, đồng thời xây dựng năng lực bền vững lâu dài.\n\nỞ vai trò này, bạn sẽ làm việc với các nhóm kinh doanh và khách hàng để hiểu rõ những ưu tiên và mục tiêu kinh doanh của họ, từ đó thiết kế các giải pháp kỹ thuật trong hệ sinh thái quảng cáo của Google. Bạn sẽ làm việc trực tiếp với những khách hàng ở cấp lãnh đạo và xác định các vấn đề cần giải quyết. Bạn sẽ áp dụng kiến thức về các sản phẩm quảng cáo của Google để đạt được các mục tiêu tiếp thị mà khách hàng đề ra. Google tạo ra các sản phẩm và dịch vụ để giúp thế giới trở thành một nơi tốt đẹp hơn, còn gTech có vai trò hiện thực hoá những sản phẩm và dịch vụ đó. Đội ngũ cố vấn đáng tin cậy của chúng tôi hỗ trợ khách hàng trên toàn cầu. Chúng tôi đưa ra các giải pháp dựa trên kỹ năng chuyên môn, hiểu biết sâu sắc về sản phẩm và khả năng hiểu rõ nhu cầu phức tạp của khách hàng. Dù là cung cấp một giải pháp "đo ni đóng giày" cho một vấn đề chưa từng có, hay sáng tạo ra một công cụ hữu ích cho toàn thể Google, thì mọi việc chúng tôi làm đều nhằm mục đích đảm bảo các sản phẩm của Google phát huy hết khả năng để mang lại thật nhiều giá trị cho khách hàng.\n\nĐể tìm hiểu thêm về gTech, mời bạn xem video của chúng tôi.\n\nResponsibilities:\n\n- Trao đổi với khách hàng bên ngoài và các bên liên quan phụ trách mảng kinh doanh trong nội bộ để xác định mục tiêu kinh doanh và mục tiêu tiếp thị của khách hàng thông qua phương pháp tư vấn. \n- Dẫn dắt các cuộc họp với khách hàng để tìm kiếm cơ hội xây dựng Kế hoạch kỹ thuật chung, Gói giải pháp tăng trưởng kỹ thuật số và Giải pháp độc lập, giúp khách hàng đạt được mục tiêu kinh doanh.\n- Phát triển chuyên môn về bộ Sản phẩm quảng cáo của Google và Hạ tầng kỹ thuật của khách hàng để thiết kế các giải pháp kỹ thuật đáp ứng nhu cầu của khách hàng.\n- Dẫn dắt các dự án kỹ thuật kéo dài nhiều quý bằng cách hợp tác với các phòng ban liên ngành trong nội bộ và cả bên ngoài (ví dụ: thành viên đội kỹ thuật và các đội khác không phụ trách mặt kỹ thuật).\n- Khám phá những cơ hội kích hoạt truyền thông đến từ hoạt động triển khai giải pháp kỹ thuật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1423, 845, 2, 'Node.js Developer', 'Your creative solutions supplier\n\nThe Role\n\nYou Will Be Responsible For\n\n- Writing well-designed, testable and efficient code.\n- Gathering and evaluating user feedback.\n- Working as a part of a dynamic team to deliver winning products.\n- Providing code documentation and other inputs to technical documents.\n- Supporting continuous improvement by investigating alternatives and new technologies and presenting these for architectural review.\n- Troubleshooting and debugging to optimise performance.\n\nIdeal Profile\n\n- You possess a Degree/Diploma in Computer Science, Engineering or related field.\n- You have at least 1 year experience, ideally within a Software Engineer role.\n- You possess strong analytical skills and are comfortable dealing with numerical data\n- You pay strong attention to detail and deliver work that is of a high standard\n- You enjoy finding creative solutions to problems\n\nWhat\'s on Offer?\n\n- Flexible working options\n- Excellent career development opportunities\n- Work alongside & learn from best in class talent', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1424, 846, 2, 'Kiểm Thử Phần Mềm - Tester - Erp', 'Mô tả công việc\n\n- Kiểm thử theo yêu cầu của khách hàng và của các thành viên.\n- Đảm bảo chất lượng của dự án\n- Hỗ trợ phản hồi và đào tạo khách hàng\n- Nắm rõ quy trình dự án đang tham gia\n- Thực hiện công việc theo quy trình của team\n- Báo cáo tuần hoặc ngày cho Leader, tùy theo quy trình dự án.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1425, 847, 2, 'Chuyên viên cao cấp Phát triển ứng dụng', 'Mô tả công việc:\n-Phát triển giải pháp ứng dụng CNTT: Thiết kế, lập trình và tùy chỉnh các ứng dụng, báo cáo, giao diện theo yêu cầu; đảm bảo hiệu suất, bảo mật và tích hợp hệ thống.\n-Hỗ trợ & bảo trì hệ thống: Hỗ trợ kỹ thuật người dùng, xử lý sự cố, bảo trì và kiểm thử các chương trình hiện có.\n-Tối ưu hóa & cải tiến: Tối ưu mã nguồn và hiệu suất hệ thống; đề xuất giải pháp kỹ thuật cải tiến dựa trên nhu cầu thực tế.\n-Đào tạo & hỗ trợ người dùng: Hướng dẫn và hỗ trợ người dùng cuối, đào tạo nội bộ về các ứng dụng liên quan.\n\nYêu cầu vị trí:\n- Có từ 5 năm kinh nghiệm trong lĩnh vực phát triển dự án.\n-Trên 2 năm kinh nghiệm làm việc trong lĩnh vực AI/ML.\n-Trên 2 năm kinh nghiệm lập trình Python, xây dựng và fine-tune Large Language Models (LLM), Retrieval-Augmented Generation (RAG) và chatbot agents.\n- Có kinh nghiệm làm việc trực tiếp với các phòng ban nghiệp vụ và các đội phát triển ứng dụng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1426, 237, 2, 'Full Stack Engineer', 'I. MÔ TẢ CÔNG VIỆC\n- Tham gia lập trình, vận hành, tối ưu các sản phẩm của công ty.\n- Tối ưu hóa hiệu suất và bảo mật của các ứng dụng Web.\n- Xác định và giải quyết các vấn đề liên quan đến ứng dụng Web.\n- Tham gia vào các quá trình kiểm soát chất lượng cho sản phẩm.\n- Các công việc khác theo sự phân công của Quản lý trực tiếp.\n- Chi tiết trao đổi qua cuộc phỏng vấn.\n- Thời gian làm việc: Từ thứ 2 đến hết sáng thứ 7, nghỉ chiều thứ Bảy và các ngày Chủ nhật.\n+ Sáng: từ 8h30 – 12h00.\n+ Chiều: từ 13h30 – 18h00\nII. QUYỀN LỢI\n- Mức lương: thỏa thuận\n- Phụ cấp ăn trưa.\n- Được hưởng các chế độ BHXH, BHYT, BHTN và các phúc lợi khác theo quy định của Luật lao động và của Công ty\n- Được đi du lịch và tham gia các hoạt động vui chơi, giải trí khác do công ty tổ chức hàng năm.\n- Được đào tạo bài bản, chuyên sâu nâng cao nghiệp vụ chuyên môn và kỹ năng mềm.\n- Được làm việc trong môi trường chuyên nghiệp, năng động, sáng tạo\nIII. YÊU CẦU\n- Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin, hoặc tương đương\n- Kinh nghiệm: từ 2 năm ở vị trí tương đương.\n- Thành thạo quy trình phát triển phần mềm, từ tiếp nhận yêu cầu, lựa chọn công cụ, ngôn ngữ, thiết kế CSDL, xây dựng frontend, backend, triển khai lên hệ thống server thật.\n- Thành thạo ngôn ngữ lập trình Javascript, CSS, HTML và một framework xây dựng frontend như ReactJS hoặc Angular, biết cách xây dựng website responsive chạy trên mobile.\n- Thành thạo một framework xây dựng backend như NodeJS Express, ngôn ngữ SQL, biết cách sử dụng ORM và vận hành hệ quản trị CSDL như MySQL hoặc Postgres.\n- Biết sử dụng các API và thiết kế API để tương tác với các dịch vụ của khách hàng.\n- Biết đọc tài liệu bằng tiếng anh.\n- Biết phát triển ứng dụng mobile (ReactNative) là một lợi thế.\n- Kỹ năng làm việc độc lập và làm việc nhóm tốt để giải quyết các vấn đề liên quan đến sản phẩm', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1427, 848, 2, '[ELCOM Hà Nội] Kỹ sư AI (Generative)', 'MÔ TẢ CÔNG VIỆC\nNghiên cứu, thử nghiệm và triển khai các mô hình Generative AI ứng dụng trong bài toán RAG, Agents và AI Workflow nhằm phục vụ các giải pháp chuyển đổi số.\nLàm việc với các framework hiện đại như LangChain, LlamaIndex để phát triển giải pháp RAG.\nThiết kế và xây dựng các quy trình AI Workflow sử dụng các công cụ như Langflow, Agno, N8N nhằm tự động hóa nghiệp vụ.\nHỗ trợ fine-tune và tối ưu các mô hình ngôn ngữ lớn (LLMs) như Qwen, LLaMA, v.v., bằng các kỹ thuật như LoRA, QLoRA, PEFT.\nTự triển khai mô hình (self-host) bằng các công cụ như vLLM, Ollama, llama.cpp.\nTích hợp LLM với vector database như FAISS, Weaviate, Milvus, Qdrant để xây dựng hệ thống tìm kiếm ngữ nghĩa và truy xuất thông tin thông minh.\nLàm việc chặt chẽ với đội ngũ sản phẩm và kỹ thuật để tích hợp AI vào backend và ứng dụng thực tế.\nYÊU CẦU\nTốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán ứng dụng hoặc các ngành liên quan.\nTối thiểu 2 năm kinh nghiệm trong lĩnh vực Machine Learning, Xử lý ngôn ngữ tự nhiên (NLP).\n\nKỹ Năng Cần Thiết\nThành thạo Python và các thư viện ML: PyTorch, TensorFlow, Transformers.\nCó kiến thức cơ bản về các mô hình LLMs như: Qwen, LLaMA, etc.\nƯu tiên ứng viên đã từng làm việc hoặc có trải nghiệm với các công cụ như LangChain, LlamaIndex, Langflow, N8N.\nCó khả năng xây dựng prompt hiệu quả, đặc biệt với ngôn ngữ tiếng Việt.\nHiểu biết hoặc đã làm việc với các vector database như: FAISS, Chroma, Weaviate, Qdrant.\nNắm vững kiến thức cơ bản về các phương pháp tối ưu hóa mô hình như LoRA, QLoRA, quantization.\nCó kinh nghiệm triển khai mô hình trong môi trường thực tế (production) là một lợi thế.\n\nLÝ DO ĐỂ ĐỒNG HÀNH VỚI ELCOM\nSự Tiên Phong Trong Công Nghệ\nVới truyền thống 30 năm hình thành phát triển, Elcom chắc chắn sẽ là nơi làm việc khiến bạn an tâm gắn bó lâu dài, với:\nTham gia ứng dụng công nghệ mới vào những sản phẩm lớn, bộ giải pháp toàn diện Top đầu thị trường thuộc các lĩnh vực Chuyển đổi số, An ninh Quốc phòng, giao thông thông minh,...\nĐược tiếp cận với xu hướng công nghệ hàng đầu, phát triển giải pháp thông minh "powered by AI"\n\nMôi trường thân thiện, chia sẻ, đồng hành:\nMôi trường CNTT năng động, thân thiện, cởi mở, tôn trọng sự khác biệt và đề cao sáng tạo, được làm chủ công việc và tận hưởng thành quả đạt được. Minh bạch, thẳng thắn trao đổi thống nhất với cấp trên trong suốt quá trình làm việc và các đợt review năng lực hàng năm.\n\nNền Tảng Vững Chắc Cho Phát Triển Sự Nghiệp, Thăng Tiến, Quyền Lợi\nGói đãi ngộ cạnh tranh với mức thu nhập hấp dẫn.\nGói thưởng trực tiếp từ lợi nhuận Công ty, 6 khoản thưởng cho các ngày Lễ khác trong năm, thưởng nóng, ESOP,.. \nPhụ cấp công tác. Cấp laptop và các phương tiện/tài khoản/thẻ ĐT/công cụ cần thiết khác cho công việc.\nChăm sóc sức khỏe: Bảo hiểm sức khỏe cho nhân viên và người thân với hạn mức lên tới $6000/người; khám sức khỏe định kỳ tại các bệnh viện hàng đầu.\nĐược hưởng toàn bộ các quyền lợi theo Luật lao động ban hành về chế độ tham gia bảo hiểm xã hội, nghỉ lễ, nghỉ phép năm.\nBữa trưa được phục vụ miễn phí tại văn phòng.\nCùng nhau đóng góp cho cộng đồng nhiều giá trị, có ý nghĩa sâu sắc với các chương trình từ thiện lớn của Công ty hàng năm: Trăng sáng yêu thương, Cơm có thịt,... \nCác hoạt động văn hóa, giải trí phong phú: Du lịch, teambuilding, ngày hội sinh nhật công ty tại các địa điểm du lịch, resort cao cấp, cháy hết mình tại các CLB thể thao (Zumba, bóng bàn, bóng đá, cầu lông), âm nhạc ( guitar, trống…)\nCác hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân…\nThời gian làm việc: thứ 2 đến thứ 6.\n\nĐịa điểm làm việc: Elcom Building, ngõ 15 phố Duy Tân, Cầu Giấy, HN\n\nThông tin liên hệ: Ms Linh: 086 9696 811 (zalo/viber/tele) Email: linhpt@elcom.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1428, 849, 2, 'Associate Solution Support Engineer -Business Technology Platform', 'We help the world run better\n\nAt SAP, we enable you to bring out your best. Our company culture is focused on collaboration and a shared passion to help the world run better. How? We focus every day on building the foundation for tomorrow and creating a workplace that embraces differences, values flexibility, and is aligned to our purpose-driven and future-focused work. We offer a highly collaborative, caring team environment with a strong focus on learning and development, recognition for your individual contributions, and a variety of benefit options for you to choose from.\n\nAbout SAP Labs Network And SAP Labs Vietnam\n\nSAP Labs Network is the global R&D setup where over 55,000 engineers around the world create, operate and support the most innovative enterprise solutions for SAP’s customers worldwide. SAP Labs Vietnam aims to become one of the key locations within the SAP Labs Network to support the engineering growth for SAP.\n\nMeet your team\n\nIf you’re searching for a diverse, multi-cultural team where you feel empowered, respected, and dedicated to your ideas and individual growth — you have come to the right place. Our team culture encourages and recognizes unique contributions and provides a fun, flexible, and inclusive work environment.\n\nThe new Technical Support Team at the SAP Vietnam/SAP Labs office in Ho Chi Minh City is critical to SAP\'s future success in the APAC region. We are looking for candidates who strive to make the world run better by delivering exceptional customer support and driving customer satisfaction.\n\nWhat You\'ll Do\n\nAs a BTP Associate Solution Support Engineer, you will troubleshoot and solve customer issues reported through industry-leading channels within SAP Business Technology Platform (BTP). This includes engaging directly with customers, collaborating with development teams, using knowledge repositories, simulating problems, and working on customer systems to resolve complex issues. Your goal is to deliver a high-quality customer experience while developing deep technical expertise.\n\nKey Responsibilities\n\n- Investigate and resolve complex, real-world customer issues related to SAP BTP.\n- Provide technical problem-solving and debugging expertise.\n- Recommend technical solutions and develop workarounds where needed.\n- Properly document communications and actions for customer issues in SAP’s CRM system.\n- Use SAP and third-party tools to diagnose issues on customer systems.\n- Participate in shift work, including weekends, as scheduled.\n- Continuously learn and master SAP software used by industries, governments, and multinational companies.\n\nTechnologies Supported\n\n- UX/UI and mobile-based technologies\n- SAP FIORI\n- Gateway\n- Relational databases\n- Operating Systems\n\nWhat You Bring\n\nEducation and Experience:\n\n- University degree or college diploma in Computer Science, Information Technology, Software Engineering, Business Information Systems, Engineering, Science, or Mathematics preferred (but not required).\n- 0–2 years of professional experience; new graduates are encouraged to apply.\n\nSkills And Competencies\n\n- Strong IT affinity and technical aptitude to troubleshoot customer issues effectively.\n- Excellent communication, collaboration, and customer service skills.\n- High proficiency in English (spoken and written).\n- Programming skills preferred.\n- Strong analytical and problem-solving abilities.\n- Open and professional communication style.\n- Strong team player who learns and adapts quickly.\n- Customer-centric mindset with a passion for delivering high-quality solutions.\n- Ability to thrive in a fast-paced, changing environment with a cloud-first mindset.\n\nCareer Development and Growth\n\nSAP is committed to supporting your professional growth and development:\n\n- Career Progression: SAP provides the tools and resources to help employees grow in their careers.\n- Training: A structured development plan combining on-the-job learning and formal training ensures continuous skill development.\n- Global Exposure: Collaborate with global teams and gain exposure to diverse industries and customer environments.\n\n#SAPLabsVietnamCareers\n\nBring out your best\n\nSAP innovations help more than four hundred thousand customers worldwide work together more efficiently and use business insight more effectively. Originally known for leadership in enterprise resource planning (ERP) software, SAP has evolved to become a market leader in end-to-end business application software and related services for database, analytics, intelligent technologies, and experience management. As a cloud company with two hundred million users and more than one hundred thousand employees worldwide, we are purpose-driven and future-focused, with a highly collaborative team ethic and commitment to personal development. Whether connecting global industries, people, or platforms, we help ensure every challenge gets the solution it deserves. At SAP, you can bring out your best.\n\nWe win with inclusion\n\nSAP’s culture of inclusion, focus on health and well-being, and flexible working models help ensure that everyone – regardless of background – feels included and can run at their best. At SAP, we believe we are made stronger by the unique capabilities and qualities that each person brings to our company, and we invest in our employees to inspire confidence and help everyone realize their full potential. We ultimately believe in unleashing all talent and creating a better and more equitable world.\n\nSAP is proud to be an equal opportunity workplace and is an affirmative action employer. We are committed to the values of Equal Employment Opportunity and provide accessibility accommodations to applicants with physical and/or mental disabilities. If you are interested in applying for employment with SAP and are in need of accommodation or special assistance to navigate our website or to complete your application, please send an e-mail with your request to Recruiting Operations Team: Careers@sap.com\n\nFor SAP employees: Only permanent roles are eligible for the SAP Employee Referral Program, according to the eligibility rules set in the SAP Referral Policy. Specific conditions may apply for roles in Vocational Training.\n\nEOE AA M/F/Vet/Disability\n\nQualified applicants will receive consideration for employment without regard to their age, race, religion, national origin, ethnicity, age, gender (including pregnancy, childbirth, et al), sexual orientation, gender identity or expression, protected veteran status, or disability.\n\nSuccessful candidates might be required to undergo a background verification with an external vendor.\n\nRequisition ID: 425761 | Work Area: Customer Service and Support | Expected Travel: 0 - 10% | Career Status: Graduate | Employment Type: Regular Full Time | Additional Locations: .', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1429, 850, 2, 'Senior Backend Developer (Java)', 'Mô tả công việc:\n- Phát triển và thử nghiệm các thành phần giải pháp, các dự án phần mềm của riêng mình từ thiết kế đến thực hiện và triển khai. Bao gồm không giới hạn việc xây dựng các ứng dụng trên web, mobile, đưa ra các giải pháp tích hợp hệ thống.\n- Nghiên cứu, thiết kế, triển khai các giải pháp phần mềm sáng tạo, cung cấp các dự án đúng thời hạn và đạt yêu cầu với chất lượng cao.\n- Nghiên cứu các công nghệ mới, liên tục cập nhật kiến thức và kỹ năng kỹ thuật của mình.\n- Xây dựng các tài liệu thiết kế, tài liệu để hỗ trợ bảo trì và sử dụng lại mã.\n- Phân tích và đề xuất những cải tiến trong quá trình phát triển tổng thể.\n- Phân tích và xem xét tài liệu.\n- Đánh giá mã và đánh giá môi trường thử nghiệm.\n- Tham gia vào các yêu cầu thu thập SDLC từ người dùng cuối.\n- Các công việc khác theo sự phân công của Quản lý trực tiếp.\n\nYêu cầu:\n1. Trình độ học vấn: Tốt nghiệp Cao đẳng trở lên về Kỹ thuật Máy tính, Khoa học Máy tính hoặc ngành tương đương.\n\n2. Kinh nghiệm:\n- Tối thiểu có 03 năm phát triển phần mềm (Java)\n- Có kinh nghiệm trong ngành Tài chính tiêu dùng, Bảo hiểm, Ngân hàng là một lợi thế.\n- Có kiến thức về kiến trúc hệ thống, design parttern, microservices,...\n- Hiểu biết sâu về các kỹ thuật/công nghệ: Redis, MongoDB, PostgreSQL, Kafka…\n- Có khả năng tuning performance của ứng dụng, hệ thống.\n- Có kinh nghiệm phát triển, sử dụng cloud, FrontEnd là một lợi thế.\n\n3. Kỹ năng:\n- Kiến thức về Java Spring Boot, ReactJS, CSS, C#...\n- Kiến thức về Frontend, Backend.\n\n4. Yêu cầu khác: Có tư duy về business.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1430, 851, 2, '[HN-Vietnam] Python Engineer - English Fluency', 'HIRING PYTHON ENGINEER (ENGLISH FLUENCY) - HYBRID AND OPEN FREELANCER\n\nWHAT WE DO:\nAt Sun Asterisk, we build cutting-edge, high-performance systems to tackle complex challenges. As a developer, you will:\n\nOwn and enhance the Flask-based Python backend, including API development and integration with the 3DAT SDK.\nDesign and implement the migration from a legacy CMS to a new MongoDB-based data storage system for user scores.\nCollaborate with frontend engineers to support rebranding and responsive UI behavior.\nHelp improve platform resilience, error handling, and test coverage.\nSupport containerized development and deployment workflows with Docker.\nWork in a small team with ownership over feature delivery and product hardening.\n\nWHO YOU ARE:\n#Experience Requirements\nMandatory Skills\n\n4+ years of professional backend development experience in Python.\nStrong experience with Flask or similar web frameworks (e.g., FastAPI).\nProficient in MongoDB or other NoSQL databases.\nComfortable working in Linux-based environments (Ubuntu) and using Docker.\nExperience building or maintaining RESTful APIs.\nSolid testing practices (unit, integration, API testing).\nStrong understanding of system design, performance optimization, and error handling.\nComfortable collaborating with frontend teams (React).\n\nDesired Skills\n\nExposure to AI SDK integration or computer vision projects.\nExperience working with proprietary SDKs or C++-backed Python bindings.\nFamiliarity with frontend development (React) or full-stack collaboration.\nExperience in CI/CD pipelines, deployment automation.\n\n#Skill requirements\n\nExcellent English communication skills\nOutstanding teamwork abilities\nProven ability to prioritize and allocate work\nSharp critical thinking and logical reasoning\nEffective problem-solving skills\n\n#Attitude Requirements\n\nCustomer-centric mindset\nAdaptability to change\nCommitment to continuous learning and growth\n\nBENEFITS AND PERKS:\nProfessional, open-minded, and creative environment:\nWork with colleagues who embrace ideas to change the society.\nRespect different perspectives within a team\nStrong learning culture that promotes individual development\nThe culture of taking risks to experience and thrive\nFocus on individual development\nBe consulted, accompanied, and supported in career development with the career path system (developing in expertise or management direction) that has been studied and tested for many years\nBe oriented for individual, group, and organizational goals\nBe empowered\nBe supported to define a 3-month or 6-month goal (Goal Define Support)\nGet access to company Learning Hub online library with various courses provided by Udemy, LinkedIn,…\n\nSpecial care for employees\nSalary: Negotiable + competitive allowance (lunch, living allowance, beauty care, Japanese and IT certificates, etc.)\n13th-month salary bonus\nPerformance review: Twice/a year\nHybrid working policy; flexible check-in, check-out\nComprehensive health insurance Sun* Care\nSeniority Allowance\nWomen care allowance: Women’s physiological leave: 2.5 hours/month; Postpartum leave for female employees with under 1-year-old children: 1 hour/day\nPolicies supporting learning activities, knowledge sharing, and cultural exchange (Technology Seminar – Tech Expert, Club: Reading, Japanese, Music Club, …)\nAnnual company trip and quarterly team-building activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '하노이 수도권 지역', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1431, 740, 2, 'Ruby on Rails Developer (Middle/Senior)', 'Job Description\n\n- Design, build, and maintain efficient, reusable, and reliable Ruby code\n- Ensure the best possible performance, quality, and responsiveness of the applications\n- Identify bottlenecks and bugs, and devise solutions to these problems\n- Help maintain code quality, organization, and automatization.\n- Delegate tasks and set deadlines for team members, monitor team performance, and report on metrics\n\nRequirements\n\n- At least 3 years of experience with Ruby\n- Understanding of the syntax of Ruby and its nuances\n- Understanding of functional programming style in Ruby\n- Skills for writing reusable Ruby libraries that may be used in expressive ways\n- Plenty of experience with server-side rendered web apps, knowledge of client-side rendered apps is useful but not essential\n- Git\n- PostgreSQL (or another relational DB i.e. MySQL, MariaDB, SQL Server)\n- Web frontend experience (HTML, CSS, JS, accessibility, responsive UIs)\n- AWS – mainly S3 and general understanding of cloud infrastructure, but experience with Lambda & Cloudfront would be nice to have\n\nBenefits\n\n- Package 14 salary months\n- Extra package per year\n- Young and dynamic working environment.\n- Continuous development of hard and soft skills through work and professional training.\n- Opportunity to approach the newest technology trends\n- Exciting leisure: sports and art events, football club, family day…\n- The company’s labor policy is completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holidays, etc.)\n\n2+ years of experience with Ruby\n\n- Please send your application via email: recruitment@cmcglobal.vn\n- Years of Experience Required\n- Required Education Level\n\nBachelor’s Degree\n\n- Job Level\n\nMiddle/Senior\n\n- Work Form\n\nFull-time\n\n- Email: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1432, 702, 2, 'Frontend Engineer - BTS team', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nJoin our Experience & Connectivity Team and be at the forefront of creating innovative platforms and services that connect and engage users and developers. As a member of our team, you will play a crucial role in designing and maintaining the infrastructure that enables seamless interactions and fosters a vibrant community. If you are passionate about building cutting-edge solutions and making a real impact, we invite you to apply and be part of our dynamic and forward-thinking team.\n\nResponsibilities\n\n- Work with product and design teams to develop website features and user interfaces.\n- Build, test, and maintain extensible back-end services and RESTful apis.\n- Design database architectures and optimize queries for performance and scalability.\n- Develop and deploy front-end applications using modern frameworks such as React.\n- Implement security best practices to ensure data integrity and platform security.\n- Troubleshooting, debugging, and problem solving across the stack.\n- Participate in code reviews to ensure code quality, readability, and maintainability.\n- Write clear, detailed technical documentation.\n\nRequirements\n\n- 3+ years in Front-end technology: Familiar with JavaScript/TypeScript and React framework.\n- Back-end technology: Familiar with Node.js and TypeScript development.\n- Database: Familiar with SQL database.\n- Version control: Familiar with Git and CI/CD pipeline.\n- Familiar with RESTful apis, authentication (e.g. OAuth2, JWT), and Web security related principles.\n- Strong problem solving skills and detail-oriented attitude.\n- Good communication skills, able to communicate smoothly with technical and non-technical team.\n\nPreferred Qualifications\n\n- Experience in online product development.\n- Experience in localization or translation related platform development is preferred.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1433, 674, 2, 'Full-Stack Developer (ReactJS, NodeJS)', 'Invest Talent JSC is supporting a fast-growing technology platform which focused on bridging financial technology and regulatory compliance. They\'re aim to simplify and automate compliance processes for businesses operating in finance and other regulated industries. Join us in building the next generation of ComplianceTech!\n\nWe are looking for a Full Stack Developer with a strong focus on Backend development to join product team. You will be working closely with cross-functional teams in a Scrum environment to build and maintain scalable, secure, and efficient features for the platform.\n\nKey Responsibilities\n\n- Develop, test, and maintain full-stack features using languages TypeScript or JavaScript\n- Using the technologies React, Node.js, and NestJS to develop the platform\n- Design and implement backend APIs and services that power the platform\'s core functionality\n- Work with the infrastructure on AWS to deploy and monitor services\n- Collaborate with designers, product managers, and other developers in a Scrum team Maintain clean, well-documented, and scalable code\n- Participate in code reviews, technical discussions, and architecture decisions \n\nYêu cầu công việc\n\nQualification\n\n- Minimum 3 years of experience in full-stack development\n- Strong experience with TypeScript, and familiar with JavaScript\n- Proficiency with React for frontend development and NodeJS for backend development\n- Have knowledge of NestJS or other NodeJS framework based on TypeScript\n- Experience with MongoDB; MySQL or PostgreSQL is a plus\n- Familiar with job queue or message queue architecture\n- Experience working with cloud infrastructure, especially AWS\n- Experience working in a Scrum team or Agile environment\n- Should have a start up spirit\n- Proficient in reading and writing English \n\nNice to Have\n\n- Experience in the fintech or compliance industry\n- Familiarity with CI/CD pipelines\n- Knowledge of application security and data privacy best practices', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1434, 808, 2, 'Intern QA Engineer - Da Nang', 'Job Description\n\nParticipate in the requirements discovery, testing of the software product.\nUsing Waterfall model and Agile model in projects.\nBuild and execute test cases.\nUse testing techniques such as black box testing, functional testing and regression testing\nHelp the Senior QA Engineer with performance testing and security testing to ensure stable software products\n\nRequirements\n\nSenior college or university student.\nAble to work full-time.\nCareful, good logical thinking, passionate about experimenting.\nHave a sense of responsibility, persistence.\nAble to work under pressure, hardworking, proactive, and responsible.\nGood communication skill.\nProficiency in English is required, including speaking, listening, reading, and writing.\nHaving certification in testing courses is an advantage.\nMajor in computer science or IT or equivalent is an advantage\n\nWork Location\n\n2F Vinh Trung Plaza, No. 255-257 Hung Vuong, Vinh Trung, Thanh Khe, Da Nang\n\nBenefits\n\n5-day workweek\nYoung & vibrant working environment with great career development opportunities\nPerformance review and bonus\nRegular team building events & internal activities (weekly happy hour, quarterly team building events, Lunar New Year parties, etc.)\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1435, 835, 2, 'Full Stack Engineer', 'Who We Are:\nWe are a legal technology platform that fundamentally changes how in-house legal teams engage with external counsel. Our purpose is to uncover the clear choice when buying complex services through centralized, streamlined, automated, and data-driven solutions.\nWe\'re growing and looking for a skilled, passionate engineer to join our team.\nYou\'ll help build our core products, improve our technology, and deliver solutions that make a positive impact on our clients.\n\nWhy You\'ll Love It Here:\nJoin a financially stable, fast-growing company trusted by the world\'s leading legal teams.\nCollaborate with a team of passionate, driven individuals committed to success.\nHave a direct influence on shaping our products, processes, and the future of LegalTech.\nTackle large-scale, complex projects while enjoying a flexible work environment.\nEnjoy competitive benefits and perks designed to help you thrive.\n\nWhat You Bring to the Team:\n5 years of experience in Fullstack development with NodeJS/ReactJS, with ReactJS accounting for at least 50%.\nSolid & practical grasp of software engineering principles and best practices.\nProficiency in JavaScript/TypeScript, Node.js, React.js, and any associated frameworks.\nExceptional problem-solving abilities with a practical approach.\nExcellent communication and interpersonal skills.\n\nBenefits:\nThe annual salary is $80.000 USD, and only suitable candidates are needed.\n13th-month salary + 5% annual performance bonus, full salary insurance.\n2-month full salary probation.\nESOP for employees.\nLeave and Tet holiday according to Vietnamese regulations.\n\nAnnual leave:\n20 days of leave, accumulated.\nAdditional paid leave from December 24 to January 1.\nPaid holidays.\n2 days of paid volunteering.\nParental leave.\nHealth care allowance: Health care: USD 50 / VND 1.2 million per month; very flexible and can be used for all health care related needs such as: gym card, class, massage, etc.\nLearning & Development Allowance: Up to $1,000/year learning and development support per employee, can be used for subject matter expert learning & development that is not required in the current role. For example, attending workshops, completing certifications, courses, etc.\nEmployer Charity Match Program.\nWork from Anywhere with Perks.\n\nInterview process: 4 rounds:\nRound 1: Casual, free-flow chat with Mr. Justin - up to ~1hr,\nRound 2: Initial chat with engineers: ~1hr\nRound 3: Pair programming and system design: ~2h30\nRound 4: Final interview: ~1hr', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 1, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1436, 852, 2, 'QA Engineer (Manual)', 'Work Location & Benefits\nOnsite: District 1, Ho Chi Minh City, Vietnam\nSalary: Negotiable, up to $1000 USD Gross.\nBenefits: Full social insurance (based on gross salary), variable allowance, 13th-month salary, provided equipment,...\nHiring Process: Test (English + Technical) & Online Interview\n\nResponsibilities:\nDesign and implement comprehensive tests for software before launch.\nEvaluate requirements and provide feedback.\nDevelop test plans and test cases.\nOrganize and prioritize testing activities.\nIdentify and track bugs during testing.\nConduct regression testing and monitor debugging outcomes.\nCollaborate with development teams for system testing.\nTrack quality assurance metrics.\nSuggest application and process improvements.\n\nRequirements:\nDegree in Computer Science, Engineering or related field (candidates from other majors with a relevant testing certificate are also welcome)\n2+ years of experience in Software Testing (Web and Mobile).\nExperience with Agile/Scrum processes.\nKnowledge of Fintech is a plus.\nSkills in automation testing is a plus.\nMUST have good English communication skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1437, 853, 2, 'Nodejs Developer', 'Requirement\n- From 3y of NodeJS experience, experienced in Agile/Scrum development environment\n- Ability to write structured, well-documented and maintainable code\n- Strong background in NodeJS (ES6). Practically experienced with REST APIs design and implementation\n- Expert knowledge of developing projects based on NodeJS and Express framework\n- Practically experienced with MongoDB, Redis and PostgreSQL. Solid professional experience in using NodeJS unit testing frameworks (Jest, Mocha, etc.)\n- Good problem-solving and analytical skills\n\nNice to have\n- Experience with AWS services (e.g., S3, ECS, Lambda).\n- Experience with message queuing systems (e.g., Kafka, SQS).\n- Knowledge of containerization and orchestration (e.g., Docker, ECS).\n- Understanding of microservices architecture.\n- Familiarity with authentication and authorization mechanisms (e.g., OAuth, JWT).\n- Strong written communication skills in English.\n- Good English speaking skills (You will get better with us).\n\nResponsibility\n- Code and test backend services in NodeJS.\n- Design, implement, and/or use RESTful web services. Building scalable microservices-based system.\n- Understand the needs of the customer or business and utilize this knowledge to develop applications that are consistent with the specific needs and requests of the customer.\n- Participate in agile software development, prototyping, and code reviews with a small team of developers.\n\nBenefit\n- Very attractive salary with a 13th-month salary.\n- Performance bonus based on effort and output.\n- All equipment will be provided.\n- Annual sponsored retreat trip.\n- Happy Hour every week.\n- Sick leave, maternity leave, vacation days.\n- Social Insurance PVI.\n- Health Insurance.\n- PTO / Sick leave.\n- Continuous growth and development for your career path.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 다낭', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1438, 854, 2, 'JavaScript Developer for Training AI Data', 'Accepted Locations\nWe accept applicants from the US, Canada, and most countries in LATAM and Europe. We are also accepting candidates from some countries in Africa and Asia. For the complete list of accepted locations, click here. This work is 100% remote.\n\nLoom Video\nOur Founder/CEO, Gabe Greenberg, created an in-depth Loom video that we highly recommend you watch! Check it out here: Loom Video\n\nOverview\nJoin our expert annotation team to create training data for the world\'s most advanced AI models. No previous AI experience is necessary. You\'ll get your foot in the door with one of the most prominent players in the AI/LLM space today. We\'re primarily seeking JavaScript/React developers with 3+ years of experience to train large AI language models, helping cutting-edge generative AI models write better frontend code. Projects typically include discrete, highly variable problems that involve engaging with these models as they learn to code. We currently have 200+ roles open!\n\nWhat Will I Be Doing?\n- Evaluating the quality of AI-generated code, including human-readable summaries of your rationale.\n- Building and evaluating React components, hooks, and modern JavaScript solutions.\n- Solving coding problems and writing functional and efficient JavaScript/React code.\n- Writing robust test cases to confirm code works efficiently and effectively.\n- Creating instructions to help others and reviewing code before it goes into the model.\n- Engaging in a variety of projects, from evaluating code snippets to developing full mobile applications using chatbots.\n\nPay Rates\nCompensation rates average at $30/hr and can go up to $50+/hr. Expectations are 15+ hours per week; however, there is no upper limit. You can work as much as you want and will be paid weekly per hour of work done on the platform.\n\nContract Length\nThis is a long-term contract with no end date. We expect to have work for the next 2 years. You can end the contract at any time, but we hope you will commit to 12 months of work.\n\nFlexible Schedules\nDevelopers can set their own hours. Ideal candidates will be interested in spending 40 hours a week. You will be assigned to projects, so strong performers will adapt to the urgency of projects and stay engaged, but we are incredibly flexible on working hours. You can take a 3-hour lunch with no problem. Instead of tracking your hours, you are paid according to time spent on the platform, calculated in the coding exercises.\n\nInterview Process\n- Apply using this Ashby form.\n- If you seem like a good fit, we\'ll send an async RLHF code review that will take 35 minutes and must be finished within 72 hours of us sending it.\n- You’ll receive credentials to the RLHF platform. We’re doing regular calls to answer any further questions about onboarding, as well as providing a support team at your disposal.\n- You’ll perform a simulated production-level task (RLHF task) on the platform. This will be the final stage, which will ultimately determine your leveling and which project you’ll be assigned. Successful completion of this process provides you with an opportunity to work on projects as they become available.\n\nTech Stack Priorities\nThe current priority for this team is frontend engineers who are well versed in JavaScript, React, and modern web development frameworks and libraries.\n\nRequired Qualifications\n- 3+ years of experience in a software engineering/software development role.\n- Strong proficiency with JavaScript/React and frontend development.\n- Complete fluency in the English language.\n- Ability to articulate complex technical concepts clearly and engagingly.\n- Excellent attention to detail and ability to maintain consistency in writing. Solid understanding of grammar, punctuation, and style guidelines.\n\nNice To Haves:\n- Bachelor\'s or Master\'s degree in Computer Science.\n- Experience with modern JavaScript frameworks and libraries (Next.js, Vue, Angular).\n- Familiarity with frontend testing frameworks (Jest, React Testing Library, Cypress).\n- Knowledge of state management solutions (Redux, Context API, MobX).\n- Experience with TypeScript and modern frontend tooling.\n- Recognized accomplishments or contributions to the coding community or in projects.\n- Proven analytical skills with an ability to approach problems creatively.\n- Adept communication skills, especially when understanding and discussing project requirements.\n- A commitment to continuous learning and staying updated with the latest coding advancements and best practices.\n- Enthusiasm for teaching AI models and experience with technical writing!\n\nIf you\'re passionate about JavaScript, React, and the future of frontend development, this is an excellent opportunity to contribute to cutting-edge AI technology while leveraging your expertise!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1439, 681, 2, '(HN) Fullstack Engineer (Typescript/English Fluency)', 'Note: Only Vietnamese Engineer\n\nWHAT WE DO\nAt Sun Asterisk, we build cutting-edge, high-performance systems to tackle complex challenges. As a developer, you will:\n- Develop frontend and backend features using React, Next.js, and tRPC.\n- Build responsive UI components and seamless user experiences for AI tool creation.\n- Design and implement backend business logic and API layers with tRPC.\n- Integrate and optimize database queries using Prisma and Kysely.\n- Collaborate with Product and AI teams to ensure feature completeness and performance.Ensure quality via code reviews, testing (unit/integration), and observability.\n\nWHO YOU ARE\n#Experience Requirements\nMandatory Skills\n- 4+ years of experience as a Full Stack or Frontend/Backend Engineer\n- Proficiency with TypeScript and React.\n- Experience building apps with Next.js (preferably using App Router).\n- Solid backend experience with tRPC or similar RPC/GraphQL APIs.\n- Familiarity with PostgreSQL and query performance optimization.\n- Experience using Prisma, Kysely, or any modern query builders.\n- Good communication skills, team-oriented, and comfortable in startup-paced environments.\n\nDesired Skills\n- Familiarity with AI tools or LLM-powered platforms.\n- Experience with Neon PostgreSQL or serverless databases.\n- Experience with Tailwind CSS, Zod, Vercel, or PlanetScale.\n- Understanding of Edge Functions or Serverless API patterns.\n\n#Skill requirements\n- Excellent English communication skills\n- Outstanding teamwork abilities\n- Proven ability to prioritize and allocate work\n- Sharp critical thinking and logical reasoning\n- Effective problem-solving skills\n\n#Attitude Requirements\n- Customer-centric mindset\n- Adaptability to change\n- Commitment to continuous learning and growth\n\nBENEFITS AND PERKS\n**Professional, open-minded, and creative environment:**\n- Work with colleagues who embrace ideas to change the society\n- Respect different perspectives within a team\n- Strong learning culture that promotes individual development\n- The culture of taking risks to experience and thrive\n\n**Focus on individual development**\n- Be consulted, accompanied, and supported in career development with the career path system (developing in expertise or management direction) that has been studied and tested for many years.\n- Be oriented for individual, group, and organizational goals\n- Be empowered\n- Be supported to define a 3-month or 6-month goal (Goal Define Support)\n- Get access to company Learning Hub online library with various courses provided by Udemy, LinkedIn,…\n\n**Special care for employees**\n- Salary: Negotiable + competitive allowance (lunch, living allowance, beauty care, Japanese and IT certificates, etc.)\n- 13th-month salary bonus\n- Performance review: Twice/a year\n- Hybrid working policy; flexible check-in, check-out\n- Comprehensive health insurance Sun* Care\n- Seniority Allowance\n- Women care allowance: Women’s physiological leave: 2.5 hours/month; Postpartum leave for female employees with under 1-year-old children: 1 hour/day \n- Policies supporting learning activities, knowledge sharing, and cultural exchange (Technology Seminar – Tech Expert, Club: Reading, Japanese, Music Club, …)\n- Annual company trip and quarterly team-building activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1440, 820, 2, 'Middle Java Developer', 'MÔ TẢ CÔNG VIỆC\n\nPhát triển và maintain các hệ thống của KH trên mô hình Spring MVC.\n\nHiểu biết về hệ quản trị dữ liệu: Oralce và Postgres.\n\nPhát triển các task do PM/Team lead assign.\n\nCó kỹ năng làm tài liệu: DB Design, API design, Screen design, basic design.\n\nTeamwork tốt.\n\nSẵn sàng OT nếu cần.\n\nCó kinh nghiệm làm front-end hoặc ngôn ngữ backend khác là 1 lợi thế\n\nYÊU CẦU\n\nTốt nghiệp đại học chính quy, học đúng chuyên ngành CNTT.\n\nKiến thức lập trình cơ bản tốt.\n\nKiến thức phân tích thiết kế hệ thống tốt.\n\nCó khả năng nghiên cứu tốt, chịu được áp lực, sắn sàng chuyển đổi công nghệ để đáp ứng công việc.\n\nTừ 3 năm kinh nghiệm làm việc với vị trí lập trình Java, am hiểu về Spring MVC.\n\nCó kinh nghiệm làm việc với các hệ quản trị PostgreSql, Oralce.\n\nNắm vững OOP, có hiểu biết design Pattern , client- server model, Architecture Pattern (MVP, MVVM,VIPER).\n\nHiểu biết về vòng đời phát triển phần mềm (water fall, agile).\n\nCó kinh nghiệm sử dụng công cụ quản lý version Git.\n\nCó tinh thần ham học hỏi và làm việc độc lập.\n\nCó kinh nghiệm làm các dự án migrate (là lợi thế).\n\nƯu Tiên\n\nCó khả năng viết tool để tăng performace và tăng độ chính xác.\n\nCó tiếng Nhật là lợi thế..\n\nYêu cầu tiếng Anh giao tiếp (Tối thiếu 650 TOEIC)\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định ky kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 27 tháng 6, 2025\n\nChi tiết công việc\n\nSố Lượng\n\n1\n\nĐịa Điểm\n\nHà Nội\n\nKinh Nghiệm\n\n3 năm\n\nTrình Độ\n\nMiddle\n\nHình Thức\n\nToàn thời gian\n\nKỹ Năng\n\nJava', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1441, 841, 2, 'Lập trình viên PHP', 'Mô tả công việc\n\n- Tham gia phát triển, tối ưu các chức năng trên hệ thống E-learning tại website www.hocmai.vn và các hệ thống tác nghiệp khác.\n- Phân tích, thiết kế và phát triển các chức năng theo nhu cầu của người dùng và yêu cầu từ các bộ phận tác nghiệp khác.\n\nKhông yêu cầu', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1442, 674, 2, 'Thực tập sinh Lập trình python (Python Development Internship)', 'Mô tả công việc\n\n- Phát triển các Bot làm Dịch vụ tự động hóa cho các lĩnh vực như Thương mại điện tử, Human Capital - HR, Financial Capital - Finance, Trading, Blockchain, Legal, Real Estate\n- Tìm và nghiên cứu để sử dụng lại các API có sẵn từ các công cụ nguồn mở để xây dựng ứng dụng dưới dạng dịch vụ web và sẽ được lưu trữ trên máy chủ.\n- Tìm và nghiên cứu các công cụ nguồn mở có sẵn, cấu hình các công cụ để tích hợp vào các công cụ của công ty lớn.\n- Quản lý và bảo trì máy chủ, thiết kế quy trình vận hành máy chủ, lập kế hoạch sử dụng và dự phòng máy chủ Ubuntu.\n\nYêu cầu công việc\n\n- Trình độ chuyên môn: Sinh viên năm thứ 2 đến cử nhân tốt nghiệp đại học các ngành liên quan như công nghệ thông tin, toán - tin học ...\n- Có kiến thức cơ bản về ngôn ngữ lập trình, đặc biệt là Python, biết sử dụng hệ điều hành Ubuntu, có kiến thức chuyên sâu về toàn bộ quy trình phát triển ứng dụng web (thiết kế, phát triển, triển khai)\n- Kỹ năng phân tích và quản lý thời gian, tư duy logic và thuật toán tốt\n- Chủ động trong công việc, có tinh thần trách nhiệm, có tinh thần làm việc nhóm, có khả năng nghiên cứu công việc mới, thực hiện các yêu cầu từ cấp trên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quoc Tuan Commune, Hai Phong City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1443, 855, 2, 'Junior System Engineer', 'Overview:\nWe’re looking for a motivated Junior System Engineer to support our core IT infrastructure. This role is ideal for someone with a strong understanding of Windows Server, Active Directory, and virtualization technologies like VMware or Hyper-V, who’s eager to grow in an enterprise environment.\n\nMain duties of job:\n- Monitoring and maintaining Infrastructure environments to agreed service levels\n- Managing incidents and problems appropriately within agreed service levels\n- Creating and performing authorized changes to customer environments, attending CABs where necessary\n- Perform root cause analysis on reoccurring incidents\n- Ensure technical documentation is completed and updated to professional standards\n- Scheduled maintenance and patching of Infrastructure environments as necessary\n- Contribute to the continuous improvement programs of all technology platforms across the datacenter\n- Call logging and escalation with third party vendors (such as Microsoft, VMware, Mimecast or Citrix)\n- Contributing to delivering team performance\n- Adhere to all company policies and processes as communicated by line management in accordance with corporate ISO accreditation levels\n- Troubleshooting infrastructure related technologies for Data center customers\n- May be required to occasionally to fill in single shifts on managed services shift roster\n\nSkills, Knowledge & Experience:\nEssential requirements:\n- Able to work as a member of a team but also manage up, across and down where required\n- Ability to troubleshoot technical problems and incidents\n- Ability to use the Service Desk tool to manage incidents/changes/problems tickets\n- Good English communications skills, both oral and written.\n- Basic technical knowledge of virtualization technologies (VMware, Hyper-V)\n- Basic technical Knowledge and hands on experience in the below technologies or variants of in an enterprise level support environment:\n    + Microsoft server products\n    + Microsoft Active Directory and integrated elements/technologies such as DNS, GPO, DHCP, AD DS\n\n🌟 Why Join SCC Vietnam?\n- Competitive salary & performance-based bonus\n- Comprehensive healthcare & family coverage\n- Annual leave, sick leave, and health checkups\n- International UK/French working environment\n- Company trips, team events & year-end parties\n- Travel insurance & onsite opportunities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1444, 856, 2, 'C / C++ Software Engineer  - Salary Up to 2500$ - Hybrid Working', 'LG Electronics Development Vietnam (LGEDV) Company focuses on smart & eco-friendly automotive components. The VC Company produces high-quality & state-of-the-art in-car infotainment systems that deliver both information and entertainment on the go for many of the world‘s biggest automobile brands.\n\nWe, LG Electronics Development Vietnam (LGEDV), conduct core R&D activities, and various product reliability tests in support of our vehicle component business.\n\nAs a C++ Software Engineer of LGEDV in the Da Nang office, your roles & responsibilities will be as follows:\n- Participating in software development projects and applications of in-vehicle infotainment systems (Infotainment) in the field of Automotive, including, Positioning information system (AVN), Vehicle condition warning (Cluster), In-vehicle networking, and telecommunications systems cooperation with Product Owner;\n- Use related technologies, including user-interactive applications (HMI Applications), frameworks, communication methods between frameworks and middleware;\n- Attend to full SWDL (Software Development Life Cycle) from requirement analysis, creating software design document (high-level design, detailed design), implementation, testing (UT/IT), and maintenance;\n- Self-assign tasks and fully be responsible for the quality/quantity of delivered results;\n- Ensure software development on time and ensure product quality;\n- Handle technical problems, report progress, and work results to management levels.\n\n1. General requirements:\nBasic Qualifications:\n- Bachelor’s degree in Information Technology, Computer Science, Computer Engineering, Electrical Engineering, Telecommunication Engineering, Mathematics, Mechanics, and Informatics or equivalent;\n- Background knowledge of computer systems (CPU, RAM, Operating System);\n- 1+ years’ experience in software programming language C/C++\n- Good understanding of OOP and Design Patterns (MVC, Observer, Strategy, etc.).\n\nPreferred Qualifications:\n- Having experience in Agile projects, V-model software development;\n- Having experience in developing at UML and using at least one of the source code management tools such as GIT;\n- Can use English at work.\n\n2. What we offer:\n- Hybrid Working Environment\n- Attractive and competitive salary package;\n- Full Salary during Probation time\n- 13th-month salary + incentive bonus ( total remuneration package: UP TO 16-MONTH SALARY);\n- Annual salary review;\n- Monthly transportation allowance\n- Support for lunch and other allowances (Coding Expert, Technical leader, phone...)\n- Paid 100% of insurance social\n- Premium health care & accident insurance;\n- Support fee to get TOEIC & Technical certifications;\n- Provided UDEMY account\n- English working environment\n- On-site & training opportunities in Korea, US, UK, France, etc.;\n- Company trip, sporty clubs (Football, Table Tennis, Badminton, Photography, Drawing, Music...);\n- Monthly budget for team building activities, etc.\n- 12 days of annual leave & 8 additional days of company holidays;\n- 5 working days/ week: Mon – Fri with flexible working time;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Danang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1445, 740, 2, 'C# Developer', 'Job Description\n\n• Gain understanding of customer’s needs through direct communication\n• Collaborate closely with the global team to complete design and testing documentation\n• Design and develop applications when customization or extensions to Microsoft solutions are needed\n• Responsible for coding, unit testing, and creating supporting documentation.\n• Continuously improve existing system with new technologies\n\nRequirements\n\n• A good understanding of Object-Oriented programming fundamentals, Software Design and Design Patterns\n• Preference will be given to candidates with experience in any of the following areas (the more the better):\n  • At least 2 years in C#\n  • Excellent knowledge of .NET framework and ASP.NET MVC, Web API\n  • .NET Core is a plus\n  • Entity Framework\n\nSoft-skills\n\n• Possible to co-work with team.\n• Good at investigating and solving incident and problem skill\n• Self-motivated and self-directed\n\nBenefits\n\n• Salary: Negotiable\n• Package: 14 salary months + Project bonus (If any) + Extra package: 16M/year\n• Young and dynamic working environment.\n• Opportunity to approach the newest technology trends\n• Exciting leisure: sports and art events (football club, family day…)\n• Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\n\n2 years experience of C# development\n\n• Please send your application via email: recruitment@cmcglobal.vn\n• Years of Experience Required\n• Required Education Level\n\nBachelor’s Degree\n\n• Job Level\n\nMiddle/Senior/Tech Lead\n\n• Work Form\n\nFull-time\n\n• Email: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1446, 844, 2, 'Kiến trúc sư giải pháp quảng cáo, Bộ phận quảng cáo gTech LCS', 'Please visit this Google Careers posting for the English-translated version of this role.\n\nMinimum qualifications:\n\n- Bằng cử nhân hoặc kinh nghiệm thực tế tương đương.\n- 5 năm kinh nghiệm ở vị trí quản lý dự án kỹ thuật hoặc làm việc trực tiếp với khách hàng.\n\nPreferred qualifications:\n\n- Kinh nghiệm xây dựng bằng chứng về tính khả thi bằng cách sử dụng công nghệ web/viết tập lệnh (ví dụ: JS, PHP, Python) và cơ sở dữ liệu SQL.\n- Kinh nghiệm quản lý dự án/chương trình, khả năng làm việc độc lập và quản lý nhiều dự án phức tạp cùng một lúc.\n- Kinh nghiệm làm việc trong ngành và công nghệ quảng cáo.\n- Khả năng tiếp thu các khái niệm kỹ thuật và truyền đạt các khái niệm đó một cách hiệu quả cho người không có chuyên môn kỹ thuật.\n- Kỹ năng cộng tác xuất sắc để làm việc với các nhóm khác trong Google (ví dụ: Nhóm bán hàng, nhóm Kỹ sư giải pháp và các nhóm khác).\n- Khả năng giao tiếp lưu loát bằng tiếng Việt vì đây là vai trò giao tiếp với khách hàng, đòi hỏi phải trao đổi bằng tiếng Việt với các bên liên quan tại địa phương.\n\nAbout The Job\n\nBộ phận Quảng cáo gTech áp dụng phương pháp sáng tạo, cộng tác và lấy khách hàng làm trung tâm để cung cấp các dịch vụ công nghệ nền tảng và giải pháp kinh doanh tiên tiến cho các nhà quảng cáo lớn. Thông qua việc tư vấn kỹ thuật và triển khai các giải pháp truyền thông, Bộ phận Quảng cáo gTech giúp khách hàng đạt được mục tiêu kinh doanh, đồng thời xây dựng năng lực bền vững lâu dài.\n\nKhi đảm nhận vai trò Kiến trúc sư giải pháp quảng cáo, bạn sẽ phối hợp chặt chẽ với các nhóm bán hàng và khách hàng của chúng tôi để tìm hiểu các ưu tiên cũng như mục tiêu kinh doanh của họ, từ đó thiết kế các giải pháp kỹ thuật dựa trên hệ sinh thái quảng cáo của Google. Bạn sẽ phát triển và áp dụng kiến thức chuyên môn của mình về các sản phẩm quảng cáo của Google để tự mình đáp ứng các mục tiêu tiếp thị của khách hàng.\n\nBộ phận Quảng cáo gTech chịu trách nhiệm cung cấp tất cả dịch vụ hỗ trợ, truyền thông và kỹ thuật cho khách hàng thuộc mọi quy mô đối với toàn bộ các sản phẩm Quảng cáo của Google. Chúng tôi giúp khách hàng khai thác triệt để các sản phẩm Quảng cáo và sản phẩm dành cho Nhà xuất bản, đồng thời hướng dẫn khách hàng khi họ cần trợ giúp. Chúng tôi cung cấp đa dạng dịch vụ, từ giúp khách hàng tự giải quyết vấn đề hiệu quả hơn và hỗ trợ trực tiếp trong sản phẩm, cho đến nâng cao trải nghiệm thông qua việc tương tác, thiết lập tài khoản và triển khai chiến dịch quảng cáo, cung cấp giải pháp truyền thông theo nhu cầu kinh doanh và tiếp thị của khách hàng, cung cấp các giải pháp kỹ thuật và đo lường phức tạp, đồng thời hỗ trợ tư vấn cho các khách hàng lớn của chúng tôi. Các giải pháp này có thể được thiết kế riêng và điều chỉnh phù hợp với từng khách hàng, hoặc có thể mở rộng cho hàng triệu khách hàng trên toàn thế giới. Dựa trên nhu cầu ngày càng tăng của khách hàng đối với dịch vụ quảng cáo, chúng tôi hợp tác với nhóm Bán hàng, nhóm Sản phẩm và Kỹ thuật tại Google để phát triển những giải pháp, công cụ và dịch vụ tốt hơn, nhằm cải thiện sản phẩm và nâng cao trải nghiệm cho khách hàng. Là một bộ phận liên ngành và hoạt động trên toàn cầu, chúng tôi đảm bảo khách hàng nhận được lợi tức đầu tư tối ưu từ Google và chúng tôi sẽ luôn là một đối tác đáng tin cậy.\n\nGoogle tạo ra các dịch vụ và sản phẩm để giúp thế giới trở thành một nơi tốt đẹp hơn, còn gTech có vai trò triển khai những dịch vụ, sản phẩm đó. Đội ngũ cố vấn đáng tin cậy của chúng tôi hỗ trợ khách hàng trên toàn cầu. Chúng tôi đưa ra các giải pháp dựa trên kỹ năng kỹ thuật, chuyên môn về sản phẩm và khả năng hiểu rõ nhu cầu phức tạp của khách hàng. Dù đó là giải pháp riêng cho một vấn đề chưa từng có, hay một công cụ mới hữu ích cho toàn thể Google, thì mọi việc chúng tôi làm đều nhằm mục đích đảm bảo các sản phẩm của Google phát huy hết khả năng để mang lại thật nhiều giá trị cho khách hàng.\n\nĐể tìm hiểu thêm về gTech, mời bạn xem video của chúng tôi.\n\nResponsibilities\n\n- Trao đổi với khách hàng bên ngoài và các bên liên quan phụ trách mảng kinh doanh trong nội bộ để xác định mục tiêu kinh doanh và mục tiêu tiếp thị của khách hàng thông qua phương pháp tư vấn.\n- Dẫn dắt các cuộc họp với khách hàng để tìm kiếm cơ hội xây dựng Kế hoạch kỹ thuật chung, gói giải pháp tăng trưởng kỹ thuật số và giải pháp độc lập, giúp khách hàng đạt được mục tiêu kinh doanh.\n- Phát triển chuyên môn về bộ Sản phẩm quảng cáo của Google và Hạ tầng kỹ thuật của khách hàng để thiết kế các giải pháp kỹ thuật dựa trên nền tảng đó nhằm đáp ứng nhu cầu của khách hàng.\n- Dẫn dắt các dự án kỹ thuật phức tạp kéo dài nhiều quý bằng cách cộng tác chặt chẽ với các phòng ban liên ngành cả trong nội bộ lẫn bên ngoài (thành viên nhóm có và không có chuyên môn kỹ thuật).\n- Khám phá những cơ hội kích hoạt truyền thông đến từ hoạt động triển khai các giải pháp kỹ thuật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Củ Chi, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1447, 857, 2, 'Chuyên viên lập trình FullStack JavaScript', 'bTaskee › Tuyển dụng › CHUYÊN VIÊN LẬP TRÌNH FULLSTACK JAVASCRIPT\n\nCHUYÊN VIÊN LẬP TRÌNH FULLSTACK JAVASCRIPT\n\nAPPLICATION DEADLINE\n\nClosed\n\nJob Descriptions\n\n- Design and Implement web application using ReactJS in the frontend, MeteorJS/ExpressJS in the backend.\n- Practice Test driven development throughout the development cycle.\n- Review code of other team members\n- Participate in designing and developing new features for large scale systems\n- Refactor & Optimize source code frequently to maintain high quality code base.\n- Work with other teams to provide solution for their requirements.\n\nJob Requirements\n\n- 3+ years of experience in programming with Javascript/TypeScript\n- Solid knowledge of ReactJS and its libraries\n- Solid knowledge of HTML & CSS\n- Good knowledge on web security & networking model.\n- Good knowledge in functional programming and design patterns in JavaScript.\n- Experience with Git, git-flow and code review process.\n- Good problem solving skill.\n- Strong sense of code ownership, code quality, and possess the ability to be involved in the entire Software development life cycle.\n- Preferably having some experience in :\n- Large scale systems, microservices.\n- Docker, kubernetes, CI, CD\n\nBenefits\n\n- Competitive salary depending on skills and capabilities\n- Bonus 13th month salary\n- All the employee’s benefits required by the Government\n- 12 annual leaves per year and other leaves/public holidays in accordance with the Labor Law of Vietnam', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1448, 858, 2, 'Back End Developer', 'Responsibility: The Senior Software Engineer is responsible to write software programs from design specifications; Determining requirements and providing project estimates and timelines and high level architecture design; Implement task lists, estimate deliver assignments as functional specifications, quality standards and project schedules; Reports status and issues; Documents detailed designs; Contributes to system architecture and design decisions; Perform other tasks assigned by the Product Owner, Project Manager & Technical Manager to figure out user’s needs, problems, expectations to contribute ideas & solution as well as to resolve them.\n\nRequired: Must have: Good knowledge of OOP, SOLID principles; 3+ years experienced in NodeJS, NestJS (static module, dynamic module); 2+ year experienced Postgresql / MongoDB; Creative thinking and good at problem solving; Strong knowledge of web service development (RESTful); Excellent communication, motivational, and interpersonal skills.\n\nNice to have: Having experiences mentoring and leading teams; Knowledge of cloud services – especially Google Cloud; Good knowledge of Docker Engine and K8S, cloud deployment, security.\n\nSalary & Benefits: Fixed salary negotiable based on competency + bonuses; 13th-month salary and performance-based bonuses; Bonuses according to company policies, including holiday, Tet, and company event bonuses; Comfortable, dynamic, and friendly working environment with high promotion opportunities; 12 annual leave days + birthday leave; leave days increase based on internal level and years of service; Full social insurance (BHXH), health insurance (BHYT), and participation in the company’s labor union; Benefits for personal events such as birthdays, weddings, illness, and maternity leave; Regular salary reviews based on company policies; Uniforms and gifts for company events; Clear career advancement path with comprehensive training and maximum support in work.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1449, 859, 2, 'Tester', '[𝐍𝐚𝐦 𝐓𝐮̛̀ 𝐋𝐢𝐞̂𝐦 - 𝐇𝐍] 𝐭𝐮𝐲𝐞̂̉𝐧 𝐝𝐮̣𝐧𝐠 𝐯𝐢̣ 𝐭𝐫𝐢́ 𝐓𝐞𝐬𝐭𝐞𝐫\n*𝒀𝒆̂𝒖 𝒄𝒂̂̀𝒖 𝒖̛́𝒏𝒈 𝒗𝒊𝒆̂𝒏:\n- Đã từng có kinh nghiệm làm việc trong lĩnh vực Tester (Fresher - Junior)\n- Có kinh nghiệm test API\n- Có kinh nghiệm, hiểu biết về CSDL, SQL\n- Nắm được quy trình phát triển phần mềm (đã có kinh nghiệm với Agile, Scrum là lợi thế).\n- Có kiến thức về kỹ thuật kiểm thử, các loại kiểm thử khác nhau.\n- Cẩn thận, tỉ mỉ, có trách nhiệm trong công việc. Có tư duy logic tốt, có khả năng làm việc độc lập và làm việc nhóm.\n*𝑸𝒖𝒚𝒆̂̀𝒏 𝒍𝒐̛̣𝒊 𝒖̛́𝒏𝒈 𝒗𝒊𝒆̂𝒏:\n- Có lộ trình làm việc rõ ràng.\n- Lương upto 12M + thưởng dự án.\n- Sau khi lên nhân viên chính thức với mức lương theo năng lực cùng những quyền lợi như lương tháng 13, thưởng dự án, thưởng theo tình hình kinh doanh của ông ty, chế độ nghỉ phép, lễ tết theo quy định của Nhà nước, và được đóng BH theo đúng quy định của nhà nước.\n𝐌𝐍 𝐪𝐮𝐚𝐧 𝐭𝐚̂𝐦 𝐈𝐁 𝐧𝐡𝐚̣̂𝐧 𝐉𝐃 𝐜𝐡𝐢 𝐭𝐢𝐞̂́𝐭 𝐧𝐡𝐞́!\n*𝘾𝙫 𝙪̛́𝙣𝙜 𝙩𝙪𝙮𝙚̂̉𝙣 𝙭𝙞𝙣 𝙜𝙪̛̉𝙞 𝙫𝙚̂̀:\nEmail: tuyendung@kiotproxy.com\n*𝙈𝙤̣𝙞 𝙩𝙝𝙤̂𝙣𝙜 𝙩𝙞𝙣 𝙭𝙞𝙣 𝙡𝙞𝙚̂𝙣 𝙝𝙚̣̂:\nzalo/SDT: 0839992707\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1450, 860, 2, 'Back End Developer', 'I/ YÊU CẦU CÔNG VIỆC\n- Tốt nghiệp đại học chính quy chuyên ngành: CNTT, Khoa học máy tính, Toán – tin\n- Tối thiểu 01 năm làm việc với vai trò Backend sử dụng Golang hoặc Rust.\n- Sẵn sàng học và làm việc với các ngôn ngữ mới.\n- Có kinh nghiệm làm việc với mô hình MicroService và các giao thức liên quan như HTTP/HTTP2, gRPC, AMQP … \n- Sử dụng tốt Linux, công nghệ container như Docker.\n- Thành thạo sử dụng CSDL Postgre, MongoDb, Redis …\n- Khả năng giao tiếp tốt, hòa đồng, làm việc trong môi trường năng động và cường độ áp lực công việc cao.\n- Có khả năng tư duy logic, giải quyết vấn đề tốt.\n- Đọc hiểu tài liệu tiếng anh, tổng hợp viết báo cáo nếu có yêu cầu.\n- Hiểu biết về blockchain hoặc đã từng tham gia dự án blockchain là điểm cộng.\n- Đam mê học hỏi và khả năng tự nghiên cứu công nghệ mới.\nII/ QUYỀN LỢI \n- Lương: thỏa thuận theo năng lực (15tr - 30tr), review lương sau 06 tháng làm việc chính thức.\n- Thưởng theo kết quả kinh doanh, thưởng nóng cho những đóng góp vượt trội\n- Tháng lương 13, thưởng lễ 05 lần/ năm.\n- Môi trường làm việc thân thiện, năng động, có cơ hội phát triển nghề nghiệp.\n- Tham gia dự án thực tế. Được đào tạo các kỹ năng chuyên môn cao.\n- Làm việc từ Thứ 2 - Thứ 6 hàng tuần (7,5h/ ngày).\n- Du lịch, khám sức khỏe hàng năm, Team Building hàng quý.\n- Gửi xe miễn phí, đồ ăn nhẹ Teabreak hàng ngày miễn phí.\nIII/ TRÁCH NHIỆM CHÍNH\n- Phát triển, tối ưu và bảo trì hệ thống backend của công ty.\n- Xây dựng các sản phẩm theo định hướng của công ty. Phát triển triển các ứng dụng theo mô hình microservice có tính mở rộng và ổn định cao.\n- Tham gia đóng góp ý kiến, phát triển các ý tưởng thành thực tế.\n- Domain: Crypto/Blockchain\nIV/ THỜI GIAN, ĐỊA ĐIỂM LÀM VIỆC\n- Thời gian: 7,5h/ ngày (Thứ 2 - Thứ 6) (Ko khuyến khích OT)\n- Địa điểm: Tòa nhà Golden Field, 24 Nguyễn Cơ Thạch, Nam Từ Liêm, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1451, 848, 2, 'Generative AI Engineer', '1.Mô tả công việc: \nNghiên cứu, thử nghiệm và triển khai các mô hình Generative AI ứng dụng trong bài toán RAG, Agents và AI Workflow nhằm phục vụ các giải pháp chuyển đổi số.\nLàm việc với các framework hiện đại như LangChain, LlamaIndex để phát triển giải pháp RAG.\nThiết kế và xây dựng các quy trình AI Workflow sử dụng các công cụ như Langflow, Agno, N8N nhằm tự động hóa nghiệp vụ.\nHỗ trợ fine-tune và tối ưu các mô hình ngôn ngữ lớn (LLMs) như Qwen, LLaMA, v.v., bằng các kỹ thuật như LoRA, QLoRA, PEFT.\nTự triển khai mô hình (self-host) bằng các công cụ như vLLM, Ollama, llama.cpp.\nTích hợp LLM với vector database như FAISS, Weaviate, Milvus, Qdrant để xây dựng hệ thống tìm kiếm ngữ nghĩa và truy xuất thông tin thông minh.\nLàm việc chặt chẽ với đội ngũ sản phẩm và kỹ thuật để tích hợp AI vào backend và ứng dụng thực tế.\n\n2.Yêu cầu:\nTốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán ứng dụng hoặc các ngành liên quan.\nTối thiểu 2 năm kinh nghiệm trong lĩnh vực Machine Learning, Xử lý ngôn ngữ tự nhiên (NLP).\n\nKỹ năng cần thiết:\nThành thạo Python và các thư viện ML: PyTorch, TensorFlow, Transformers.\nCó kiến thức cơ bản về các mô hình LLMs như: Qwen, LLaMA, etc.\nƯu tiên ứng viên đã từng làm việc hoặc có trải nghiệm với các công cụ như LangChain, LlamaIndex, Langflow, N8N.\nCó khả năng xây dựng prompt hiệu quả, đặc biệt với ngôn ngữ tiếng Việt.\nHiểu biết hoặc đã làm việc với các vector database như: FAISS, Chroma, Weaviate, Qdrant.\nNắm vững kiến thức cơ bản về các phương pháp tối ưu hóa mô hình như LoRA, QLoRA, quantization.\nCó kinh nghiệm triển khai mô hình trong môi trường thực tế (production) là một lợi thế.\n\nLÝ DO ĐỂ ĐỒNG HÀNH VỚI ELCOM\nVới truyền thống 29 năm hình thành phát triển, Elcom chắc chắn sẽ là nơi làm việc khiến bạn an tâm gắn bó lâu dài, với:\nSự tiên phong trong công nghệ:\nTham gia ứng dụng công nghệ mới vào những sản phẩm lớn, bộ giải pháp toàn diện Top đầu thị trường thuộc các lĩnh vực An ninh Quốc phòng, giao thông thông minh,...\nĐược tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng với hệ thống career path (phát triển theo hướng chuyên gia hoặc hướng quản lý).\nMôi trường thân thiện, chia sẻ, đồng hành:\nMôi trường làm việc thân thiện, cởi mở, tôn trọng sự khác biệt và đề cao sáng tạo, Elcomers được tự do phát triển các ý tưởng tiến bộ, cải tiến công việc.\nĐào tạo và phát triển liên tục với nhiều chương trình huấn luyện chuyên nghiệp, Manager hỗ trợ sát sao, nhiệt tình.\nKết nối tài năng: tập trung phát triển những con người có chung lý tưởng, mục tiêu, cùng trao giá trị và nhận thành công.\nNền tảng vững chắc cho phát triển sự nghiệp, thăng tiến, quyền lợi:\nGói đãi ngộ cạnh tranh với mức thu nhập hấp dẫn cùng chính sách review performance 2 lần/năm.\nChính sách thưởng hấp dẫn trực tiếp từ lợi nhuận Công ty, thưởng nóng theo thành tích, 6 khoản thưởng cho các ngày Lễ khác trong năm.\nChăm sóc sức khỏe toàn diện với gói Bảo hiểm sức khỏe Elcom care được thiết kế riêng cho CBNV.\nKhám sức khỏe thường niên tại bệnh viện hàng đầu cả nước.\nĐược hưởng toàn bộ các quyền lợi theo Luật lao động ban hành về chế độ tham gia bảo hiểm xã hội, nghỉ lễ, nghỉ phép năm.\nBữa trưa được phục vụ miễn phí tại văn phòng.\nCác hoạt động văn hóa, giải trí phong phú: Du lịch, teambuilding, ngày hội sinh nhật công ty tại các địa điểm du lịch, resort cao cấp, cháy hết mình tại các CLB theo sở thích (Zumba, bóng bàn, bóng đá, cầu lông).\nCác hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân...\nThời gian làm việc: thứ 2 đến thứ 6.\nĐịa điểm làm việc: Elcom Building, ngõ 15 phố Duy Tân, Cầu Giấy, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1452, 411, 2, 'Associate System Engineer', 'Mô tả công việc:\n- Hỗ trợ kỹ thuật Level 2 (technical support/onboarding) cho khách hàng sử dụng các dịch vụ VNGCloud (Kubernetes, Server, Storage, CDN).\n- Triển khai, cấu hình và xử lý sự cố liên quan đến Kubernetes, Server, VPN, Firewall, Load Balancer.\n- Hỗ trợ khách hàng migrate hệ thống từ on-premises lên VNGCloud.\n- Vận hành và tối ưu hạ tầng cloud để giảm chi phí và tăng hiệu suất cho khách hàng.\n- Quản trị hệ thống Linux, viết script tự động hóa và xử lý sự cố.\n- Giám sát hệ thống bằng các công cụ như Prometheus, Grafana hoặc tương tự.\n- Áp dụng các biện pháp bảo mật để bảo vệ hạ tầng và dữ liệu khách hàng.\n- Làm việc với đội ngũ phát triển để đưa ra các đề xuất tối ưu, cải tiến cho sản phẩm .Triển khai, tích hợp hệ thống ứng dụng tới khách hàng hiệu quả.\n- Có thể xây dựng pipeline CI/CD tích hợp với Kubernetes và các công cụ DevOps.\n\nYêu cầu:\n- 1-2 năm kinh nghiệm ở vị trí System tại các công ty ICT, SI, Hosting\n- Thành thạo Linux/Windows: Kinh nghiệm quản trị hệ thống trên các distro Linux (Ubuntu, CentOS), Windows; có khả năng viết một số script sử dụng shell, python...\n- Nắm vững kiến thức về networking, hypervisor (KVM), container (Docker), webserver (Nginx, Apache), VPN, và Load Balancer.\n- Hiểu biết và thực hành với các cơ sở dữ liệu như MySQL, MongoDB, và hệ thống ELK Stack.\n- Có kiến thức về Kubernetes, hoặc đã triển khai K8s trên môi trường on-premises hoặc cloud.\n- Chịu khó học hỏi và tự nghiên cứu, có kỹ năng phân tích, làm việc nhóm và giải quyết vấn đề nhanh chóng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1453, 830, 2, 'Middle Full-stack Java Developer (with Angular)', 'Are you looking for a position that challenges you to grow, explore new areas and contribute in multiple ways within a fast-paced workplace? Would you like the opportunity to work with a great variety of people in Vietnam and Switzerland?\n\nJoin us in one of our Vietnamese location in Ho Chi Minh City and become a member of our cross-border team with colleagues in Zurich (Switzerland).\n\nAbout our company:\nmesoneer is one of the leading Swiss software companies in the fields of digital onboarding, process automation and the integration of complex peripheral systems. Our approximately 120 employees in Switzerland and Vietnam digitize and simplify business processes with individual software solutions, modernize outdated applications and develop in-house SaaS solutions. We need you for our customers in the finance and insurance sector, public administration and other industries!\nCompany size: 120 employees\nWebsite: https://www.mesoneer.io/en/\nFanpage: https://www.facebook.com/mesoneer\nLinkedin: https://www.linkedin.com/company/mesoneer/about/\n\nWhy you’ll love working here:\n- 13th-month salary bonus.\n- Flexible working time policy\n- 12 Annual leaves, plus 5 core leave days each year.\n- 5 Sick leaves and 3 Bereavement leaves for relatives each year.\n- Annual Health check, PVI healthcare for employees and two family members\n- Full-salary-based social insurance.\n- Annual salary review and based on performance and contribution.\n- A laptop, lunch, and parking fees are provided.\n- Kid allowance.\n- Activities: Company party, Family Day, Company trip, Happy hour, Happy birthday, Team building, …\n- Office located in the center with great accommodations (ergonomic chair, free drinks, snacks, game room, ...).\n\nYour skills:\n- 3+ years of experience in designing, developing, and maintaining projects using Java technologies.\n- Have deep understanding about Spring Framework (Spring Boot, Spring Security, Spring Data,..) and other well-known Java libraries.\n- Experienced in designing and building API for modern web applications using OpenAPI, OAuth2, JWT... \n- Experienced in working with relational database systems, e.g., Oracle, PostgreSQL.\n- Experienced in building front-end with modern web frameworks, especially Angular. \n- Be able to work with and/or set up continuous integration/delivery using tools like Jenkins, GitHub Action. \n- Familiarity with cloud platforms (e.g., AWS, OpenShift). \n- Understand agile methodology and experienced in Scrum framework.\n- High willingness to familiarize yourself with new challenges.\n- Fluent in reading and writing English and able to communicate. \n\nWhat are your responsibilities: \n- Collaborate with other teammates and Product Owners to deliver good project results, and ensure quality, costs, and deadlines are met.\n- Work closely with other team members to ensure projects have good quality and a stable development environment. \n- Participate in the entire software development life cycle, including requirements analysis, design, development, testing, deployment, and support.\n- Write clean, maintainable, and well-documented code.\n- Self-manage your time and work.\n- Other tasks assigned by Leader. \n\nPlease feel free to contact us for any questions or send your profiles to our recruiters at jobs.vn@mesoneer.io', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1454, 861, 2, 'Senior Java Developer (HCM)', 'JOB DESCRIPTION\n- Work as software developer on the web-based application product in JAVA- related and open-source technologies\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project development with high quality.\n- Participate in all phases of the development cycle.\n- Actively join planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n- Respond to and resolve IT support requests from employees via phone, email, or service request system.\n\nREQUIRED SKILLS AND EXPERIENCE\n- Good command of English (both written/verbal) is essential\n- 5+ for senior of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend\n- Able to analyze, design, develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner)\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc.\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications\n- Solid understanding of OOP, design patterns, and coding standards.\n\nPREFERRED QUALIFICATIONS\nExperience with:\n- AWS\n- MS .Net / .Net Core\n- Kubernetes\n- React.js\n- Nginx\n- JUnit\n- Jasper Report\n- ElasticSearch & Kibana (ELK)\n- Grafana\n- Prometheus (monitoring/alerts).\n\nBENEFITS\n- Salary: up to 60M\n- Probation salary is 100% of official salary\n- 13th-month salary and performance review twice a year\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n- Project Bonus\n- IT Certificate allowance\n- Health Care Insurance\n- Social, health and unemployment Insurance following Government policy\n- Enjoy company summer trips and other team building activities held monthly and quarterly\n- Work five days per week with flexible check-in time\n- Professional, creative and dynamic working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1455, 862, 2, 'QA Tester', 'Join The Game! \nLeader in the development and publishing of multiplatform games, Gameloft® has established itself as a pioneer in the industry, creating innovative gaming experiences for 25 years. Gameloft creates games for all digital platforms, from mobile to cross-platform titles for PC and consoles. Gameloft operates its own established franchises such as Asphalt®, Dragon Mania Legends, March of Empires, and Dungeon Hunter, and also partners with major rights holders including LEGO®, Universal, Illumination, Hasbro®, Fox Digital Entertainment, Lamborghini®, and Ferrari®. Gameloft distributes its games in over 100 countries and employs 3,000 people worldwide. Every month, 1 billion unique users can be reached by advertisers in Gameloft games with Gameloft for brands, a leading B2B offering dedicated to brands and agencies. Gameloft is a Vivendi company.\n\nUnderstand project scope, requirements, game design, and assigned tasks.\nTest assigned features to detect bugs or unexpected behavior during the testing cycle.\nReport bugs clearly with steps to reproduce using tools like Jira or QA databases.\nCreate test cases for new features or platforms you’re responsible for.\nProvide constructive feedback on gameplay and user experience.\nCommunicate effectively with teams and suggest improvements to enhance testing and productivity.\n\nPassion for video games with experience across platforms (PC, console, mobile, web, TV).\n1–2 years of testing experience; PC/console testing is a plus.\nStrong sense of responsibility, self-discipline, and adaptability to change.\nGood observation, attention to detail, and problem-solving mindset.\nFamiliar with PC tools, testing software, MS Office, and Outlook.\nMedium to good English skills (reading, writing, reporting, and communication for projects).\n\nRecruitment Process\n(1) Screening call (Only candidates whose qualifications align with the role will be contacted. We sincerely appreciate your understanding)\n(2) Test\n(3) Interview(s)\n(4) Offer\n\nWork Location and Hours\nWork location 26 Ung Van Khiem, Binh Thanh District, Ho Chi Minh City.\nWork hours 0830 AM - 0600 PM, Monday - Friday.\n\nWhy Join Gameloft?\nYou want to work in an exceptional industry and create games downloaded more than 1 billion times per year.\nYou want to be part of a talented and supportive team of pioneers who have a passion for creating video games.\nYou want to contribute to a vibrant and dynamic atmosphere.\nYou want to join a global company and meet great people around the world.\nYou will work on an employment contract with competitive remuneration and benefits package.\nYou are looking for a fun place to work in the heart of the city.\n\nWhat We Offer\nA hybrid working model.\nA dynamic workplace environment, with over 18 nationalities, where hundreds of world-renowned game titles were born.\nA range of well-being events and policies to support employees physically, mentally, and emotionally.\nAn open-space office, a cafeteria, a terrace and a Gaming Area.\nVarious training packages, including internal training, sponsorship training, and e-learning (iLearn, Udemy,...).\nOpportunities to collaborate and train with Gameloft worldwide experts and develop yourselves.\nAn attractive monthly salary alongside Tet and other performance bonuses.\nMinimum 12 days of paid annual leave, plus 5 days of paid sick leave, Christmas leave, Birthday leave,...\n100% coverage of mandatory insurance and extra healthcare insurance.\nA monthly allowance to support lunch meals and working-from-home electricity and Internet bills.\nOther benefits from one of the best employers in Vietnam.\n\nWhat\'s more?\nWant to know more? Visit our websites\n\nSaigon Studio Website\nLinkedIn page\nFacebook page', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1456, 366, 2, 'Frontend Engineer (ReactJS) - Webtoon', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nWe are looking for the Frontend Engineer (ReactJS).\n\nYour daily tasks:\n- Develop and operate Webtoon Services\n- Co-Work with Global Webtoon Teams\n\nYour background:\n- Should have the knowledge of advanced ReactJs\n- Ideally, 5+ years of work experience on Frontend to serve large-scale and high-traffic projects\n- Enjoy discussions about the stability and scalability of Frontend systems\n- Good understanding of asynchronous request handling partial page updates, AJAX, NodeJS, SSR\n- Experience in Data Structure, Algorithm, Distributed Service\n- Understand the importance of writing high Maintainable Code, Clean Code\n- Open-minded, honest and have a positive attitude towards people\n- Good at communication skills in general and English skills in particular\n\nIt\'s a big plus if you:\n- Familiar with Front-end performance optimization\n- Experience in Responsive Web\n- Experience in developing and operating with Node.js\n- Experience in developing and operating with Docker & Kubernetes\n- Big Plus, you can communicate basically in Korean\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1457, 863, 2, 'Front-end Developer (React.js, Next.js)', 'Main Responsibilities:\n- Collaborate closely with cross-functional team members to deliver high-quality web projects.\n- Design, develop, and maintain responsive web services and user interfaces.\n- Implement web applications following modern development standards and best practices.\n- Integrate front-end components with APIs and back-end systems in cooperation with back-end developers.\n- Analyze technical requirements and UX designs to gather and refine project specifications.\n- Translate UI/UX design wireframes into functional front-end code using HTML, CSS, JavaScript, and ReactJS, applying frameworks such as Tailwind CSS or Bootstrap.\n- Develop and maintain reliable databases and application logic to support business needs.\n- Conduct thorough testing, identify bugs, and provide effective solutions to resolve coding issues.\n- Create and maintain detailed technical documentation to support development, deployment, and maintenance processes.\n\nJob Requirements:\n\nExperience:\n- Current: At least 4 years of front-end development experience, with 3+ years working with Next.js.\n- Target: 6 years of front-end experience, with a minimum of 4 years in Next.js.\n\nTechnical Skills:\n- Strong proficiency in HTML, CSS, JavaScript, and TypeScript for building modern, responsive, and cross-browser-compatible web applications.\n- Familiarity with ReactJS and CSS frameworks like Tailwind or Bootstrap.\n- Basic ability to read and understand PHP code is a plus.\n- Ability to write clean, well-documented, and maintainable code.\n\nSoft Skills:\n- Strong collaboration skills to work effectively with team members and stakeholders.\n- Excellent time management with the ability to prioritize and manage multiple tasks efficiently.\n- Adaptable and proactive in learning and applying new technologies and tools.\n- Strong problem-solving, analytical thinking, and logical reasoning capabilities.\n- Self-motivated, open-minded, and solution-oriented with a strong “can-do” attitude.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1458, 864, 2, 'Software Testing Engineer (QA)', 'About Swif.ai  Swif.ai is building an AI-powered platform that makes it effortless for companies to secure and keep every macOS, Windows and Linux device compliant. We’re a small, fast-moving crew that values ownership, candour and curiosity; if you thrive on turning complex problems into dependable products, you’ll feel right at home.\n\nWhat you’ll do\n\n- Own quality from day one. Create detailed, thorough test plans and cases that cover happy paths, edge cases and failure modes.\n- Automate the boring stuff. Design, build and maintain test-automation pipelines with open-source frameworks and scripting languages you love.\n- Hunt bugs before users do. Reproduce, document and track defects, then verify fixes with solid regression suites.\n- Collaborate cross-functionally. Partner with engineers, product managers and designers to define requirements and bake quality into every feature.\n- Measure and improve. Establish QA metrics—defect density, time-to-resolution, test-coverage trends—and drive continuous improvement.\n- Stay current. Evaluate new tools, frameworks and strategies so our test stack evolves along with the product.\n\nWhat we’re looking for\n\n- 2 + years in software QA (manual and automated) at a high-growth company.\n- Deep knowledge of modern QA methodologies, tools and processes.\n- Experience with both white-box and black-box testing and a knack for writing crystal-clear test plans.\n- Hands-on skill with automation tooling—and solid Python or shell-scripting chops.\n- Comfortable in Agile/Scrum environments; performance, security or API (Postman) testing experience is a bonus.\n- Excellent written and spoken English; familiarity with MDM/Munki or wider device-management ecosystems is a plus.\n\nLife at Swif.ai\n\nLaunched in 2022 and accelerated by YC, Swif.ai treats the company as a perpetual work-in-progress. We encourage experimentation, knowledge-sharing and respectful debate across a globally distributed team. You’ll get the autonomy to dive deep, the support to grow fast and a group of peers who care about building meaningful, reliable software.\n\nInterview process\n\n- Screen call (≈30 min). Get to know each other, chat through your background and answer your questions.\n- Take-home or live exercise. Show us how you approach real QA problems (five-day window).\n- Team interview. Meet future teammates, discuss your solution and dive deeper into technical and product thinking. We aim to schedule stages in pairs and keep the entire loop inside two weeks whenever possible.\n\nReady to raise the quality bar for every device in the enterprise? Apply today and help us build the future of secure, compliant fleet management.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1459, 835, 2, 'Java Developer', 'Company: Khách hàng Reco\nWorking Location: Hà Nội, Việt Nam\nSalary: Up to 40,000,000 VND\nLevel: SENIOR\nJob Description:\n• Tham gia phát triển và bảo trì hệ thống đồng bộ dữ liệu lớn;\n• Phân tích thiết kế giải pháp cho yêu cầu của khách hàng theo full quy trình: System design, development, testing, implementation, support, maintainance, enhancement.\nJob Requirements:\n• Must have:\n+ Tốt nghiệp Đại học chuyên ngành IT hoặc liên quan;\n+ Tối thiểu 4 năm kinh nghiệm phát triển dự án phần mềm sử dụng ngôn ngữ lập trình Java;\n+ Có kinh nghiệm với Spring Framework, Spring Boot;\n+ Có kinh nghiệm về Oracle;\n+ Có kinh nghiệm về MS SQL;\n• Nice to have:\n+ Có kinh nghiệm về công nghệ container như Docker;\n+ Có kinh nghiệm về K8S;\n+ Có kinh nghiệm triển khai và vận hành hệ thống trên hệ điều hành Linux.\nBenefits:\n• 100% lương trong 2 tháng thử việc;\n• Bảo hiểm full lương ngay từ thời gian thử việc;\n• 15 tháng lương;\n• Khám sức khỏe 1 lần/năm;\n• Bảo hiểm sức khỏe;\n• 300$/nhân viên/năm cho chương trình đào tạo cá nhân;\n• Cơ hội đào tạo ở nước ngoài;\n• Nhiều hoạt động nội bộ: team binding, team training,…\n• Quà tặng cho mỗi nhân viên vào các ngày 30/4, 1/5; 2/9;....(tiền mặt);\n• Thưởng cho nhân viên có chứng chỉ ngoại ngữ;\n• Làm việc 5 ngày/tuần để đảm bảo cân bằng giữa công việc và cuộc sống;\n• Giảm giá khi mua sản phẩm của công ty.\nInterviewing Process:\n• 1 vòng offline \nContact: \nVương Thị Thủy - Career Consultant\nEmail: thuy.vuong@reco-vn.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1460, 865, 2, '[HCM] Salesforce Developer (All level) | Up to 55M VND', 'MÔ TẢ CÔNG VIỆC\n- Use Salesforce APIs to integrate Salesforce with other tools and third-party applications\n- Actively focus on developing effective communication and relationship-building skills, with stakeholders, clients, and team.\n- Thorough understanding of Manufacturing data models, design considerations, and connected external systems\n- Data Migration in Salesforce\n\nYÊU CẦU CÔNG VIỆC\nMust have:\n- Bachelor’s Degree in Computer Science or related field\n- From 3 – 6+ years experience as a Salesforce Developer.\n- Have Salesforce Platform Developer 1 Certified.\n- Apex development.\n- Hands-on experience in administration setup, e.g., managing users, security controls, and data as well as creating roles, profiles, and reports.\n- Experience in designing custom objects, custom fields, picklists, page layouts, workflow, approval processes, validation rules, custom tabs, reports, Visualforce pages, dashboards, and email generation according to application requirements\n\nNice to have (Optional):\n- Candidates with the following Salesforce certifications are preferred:\n- Salesforce Administrator\n- Salesforce Platform Developer I, II\n- Salesforce Application Architect\n- Salesforce Javascript Developer I\n- Salesforce Certified Administrator (SCA)\n- Good English or Japanese.\n\nGÓI PHÚC LỢI HẠNH PHÚC CỦA HYBRID TECHNOLOGIES\n- Benefits & perks – Competitive salary and other attractive packages.\n- Personal Development – Opportunity to approach the latest technologies and take on diverse challenges through different projects.\n- Environment – Chances to work in a professional, creative & multilingual environment where people develop together and strive to materialize a shared dream.\n\nWhy you’ll love working at Hybrid Technologies?\n- Salary package: Competitive and negotiable. 13th salary and other bonuses according to company regulations. Lunch/Parking allowance, Gifts on annual holidays (March 8, October 20, Mid-Autumn Festival, …). Leave increases according to seniority.\n- Performance review: 2 times/ year\n- Health care: Health insurance package for employees & long-term employees’ families. Annual health check-up.\n- Activities sponsored: Charity Activities. Tournaments organized by company: Football, Table Tennis, E-sport…\n- Working Environment: Common space & the green-clean-dynamic working space with the newest up-to-date working equipment\n\nABOUT HYBRID TECHNOLOGIES\nHybrid Technologies – New view with you!\nHybrid Technologies is a Vietnam-Japan joint venture technology company that provides comprehensive solutions and diverse working models such as CRM Development & Cloud Service, Web/Mobile Application Development Service, AI/Blockchain Development Service, or Digital Consulting (DX) …\nAfter 09 years of establishment & development, Hybrid Technologies is proud of specific achievements attained with 04 branches in Vietnam & Japan and is now growing to over 600 employees and hundreds of projects & clients in several different technology fields.\nWith the mission of being a professional global technology company, and a reliable partner of clients, Hybrid Technologies strives and believes that by joining us, you will have the opportunity to develop your competencies, gain new experience and improve yourself in a professional and modern working environment, to reach a new view – where each individual and group become more and more awesome!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1461, 866, 2, 'QC Engineer (Fresher/Junior)', 'Who are we?\n\nAmaris Consulting is an independent technology consulting firm providing guidance and solutions to businesses. With more than 1,000 clients across the globe, we have been rolling out solutions in major projects for over a decade – this is made possible by an international team of 7,600 people spread across 5 continents and more than 60 countries. Our solutions focus on four different Business Lines: Information System & Digital, Telecom, Life Sciences and Engineering. We’re focused on building and nurturing a top talent community where all our team members can achieve their full potential. Amaris is your steppingstone to cross rivers of change, meet challenges and achieve all your projects with success.\n\nAt Amaris, we strive to provide our candidates with the best possible recruitment experience. We like to get to know our candidates, challenge them, and be able to give them proper feedback as quickly as possible. Here\'s what our recruitment process looks like:\n\nBrief Call: Our process typically begins with a brief virtual/phone conversation to get to know you! The objective? Learn about you, understand your motivations, and make sure we have the right job for you!\n\nInterviews (the average number of interviews is 3 - the number may vary depending on the level of seniority required for the position). During the interviews, you will meet people from our team: your line manager of course, but also other people related to your future role. We will talk in depth about you, your experience, and skills, but also about the position and what will be expected of you. Of course, you will also get to know Amaris: our culture, our roots, our teams, and your career opportunities!\n\nCase study: Depending on the position, we may ask you to take a test. This could be a role play, a technical assessment, a problem-solving scenario, etc.\n\nAs you know, every person is different and so is every role in a company. That is why we have to adapt accordingly, and the process may differ slightly at times. However, please know that we always put ourselves in the candidate\'s shoes to ensure they have the best possible experience.\n\nWe look forward to meeting you!\n\nJob Description\n\nABOUT THE JOB\n\n- Execute manual test cases based on software requirements and specifications.\n- Identify, log, and track defects during test execution.\n- Collaborate with developers and QA team members to troubleshoot and resolve issues.\n- Assist in preparing test data and environment for test scenarios.\n- Maintain and update test documentation.\n- Participate in regression and smoke testing during release cycles.\n- Ensure deliverables meet quality standards before deployment.\n- Support in analyzing test results and producing test reports.\n\nAbout You\n\n- Bachelor\'s degree in Computer Science, Information Technology, or related fields.\n- Experience in manual software testing.\n- Strong knowledge of software testing principles and defect tracking, ISTQB certification is a plus.\n- Strong critical thinking and problem-solving skills.\n- Good English communication skills is a big plus.\n- Self-motivated, proactive, and eager to learn new technologies.\n- Ability to collaborate effectively with teams and stakeholders.\n\nWHY AMARIS?\n\n- Competitive salary and 13th-month salary\n- 14+ annual leaves per year\n- Premium healthcare insurance, starting from your probation period\n- Project reviews and yearly performance appraisals\n- Annual company trips\n- Teambuilding activities: Team lunch/dinner, events, and celebrations, sports clubs (football, yoga, badminton, etc.)\n- International team with flexible working time + hybrid working\n- Tailor-made career path\n- Technical workshops and training courses\n- Mobility: Opportunities to be on-site abroad in our offices in over 60+ countries\n\nEqual Opportunity\n\nAmaris Consulting is proud to be an equal opportunity workplace. We are committed to promote diversity within the workforce and creating an inclusive working environment. For this purpose, we welcome applications from all qualified candidates regardless of gender, sexual orientation, race, ethnicity, beliefs, age, marital status, disability, or other characteristics.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville et périphérie', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1462, 867, 2, 'Embedded Software Engineer II,  Cybersecurity', 'Hybrid Controls Vietnam, is a wholly-owned subsidiary of New Eagle Consulting, an Engineering consulting company with Headquarters located in in Michigan USA. Incorporated in Vietnam in 2019, we are a small and growing group of enthusiastic engineers working on innovative solutions for the mobility domain.\n\nJob Description\n\nNew Eagle seeks a talented embedded software engineer to assist in the development of board support packages and cybersecurity initiatives for our powerful family of general-purpose electronic control units. Employees holding this position develop conceptual designs for new features, realize these designs through implementation in C code, and ultimately test the designs on hardware. This position also requires frequent collaboration with colleagues in the USA, who are responsible for extending the functionality of the board support packages.\n\nEssential Duties\n\n- Develop embedded C code for common automotive microcontrollers including ST SPC58, Infineon TC3XX, and NXP/ST ARM microcontrollers\n- Experience designing and implementing controls to improve the cybersecurity of embedded systems\n- Document designs and implementations (preferably in the Doxygen format)\n- Collaborate with global team members to facilitate proper integration of board support packages by higher layers of software\n- Test networking functions for CAN/LIN using common Vector tooling\n   - Experience with CAN-FD preferred\n\nRequired Qualifications\n\n- Bachelor’s degree equivalent (or higher) in Computer Engineering or related field\n- 5+ years of demonstrated prior experience developing embedded software, preferably for automotive applications\n- Demonstrated experience with ETAS CycurHSM, Vector vHSM, or similar cryptography stack\n- Demonstrated experience with key management protocols and storage systems\n- Knowledge of AUTOSAR SecOc, J1939-91C, or similar protocols\n- Experience working with secure bootloader solutions such as ETAS RTA-FBL or similar\n- Experience working with PowerPC, TriCore, or ARM Cortex MCUs, including their hardware security modules\n- Demonstrated strong functional knowledge of computer architecture\n- Demonstrated prior experience with on-target debugging\n- Demonstrated prior experience debugging CAN and/or LIN networks. Experience with Ethernet is an advantage\n- Exposed to software development life cycle\n\nPowered by JazzHR\n\nqjSAUHWDlH', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1463, 682, 2, 'Kỹ sư Phát triển Fullstack - Fullstack Developer - Khối Công nghệ thông tin (HOLT.04)', 'Job Description:\n- Develop and directly program banking systems and applications, including internal systems and customer-facing applications serving 30 million individual customers and 300,000 corporate customers.\n- Develop or collaborate with vendors to deploy technology solutions.\n- Manage and develop integration services with core systems such as T24, WAY4, BPM, CRM, CIC, etc.\n- Manage and develop APIs on the API Gateway to support integration with domestic and international partners.\n- Research, test, and implement new technology trends in development, including GraphQL, Docker Containers (Kubernetes), CI/CD, Event Sourcing, CQRS, and NoSQL.\n\nJob Requirement:\n- Graduated from university in majors such as Information Technology, Computer Science, Telecommunications Electronics, Software Engineering, Computer Science, Information Systems, etc.\n- Practical work experience in Backend programming at companies or projects.\n- Proficient in at least one Backend programming language, preferably Java.\n- Skilled in the Spring framework: Spring Core, Spring Security, Spring Boot.\n- Proficient in at least one of the following databases: Oracle, SQL Server, PostgreSQL, MongoDB.\n- Experience in the financial or banking domain is an advantage.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1464, 868, 2, 'Web3 Frontend Engineer (Onsite – HCM)', 'Work with the Best\n\nWe are Orderly, the ultimate destination for decentralized trading platforms. We are not satisfied with the limitations of centralized exchanges or the complexities of building decentralized order books. We aim to make trading easy, fast, and secure for everyone. How? By fusing the simplicity of CeFi with the power of DeFi.\n\nAt the heart of the issue lies “liquidity”. Builders often grapple with a paradox; traders need liquidity, but liquidity demands traders. Our solution is simple as is bold –concentrate all liquidity into one order book. One order book that connects all the liquidity in the crypto space.\n\nOur ambition doesn\'t stop there. We\'re omnichain, championing chain abstraction. We envision seamless transactions, where the underlying blockchain is merely a detail. By concentrating liquidity, we aim to redefine the crypto landscape, making bridging and wrapped assets a thing of the past.\n\nWe are Orderly, and we are here to revolutionize DeFi, democratizing access to financial opportunities and fostering a fair, equitable paradigm for all.\n\nA Glimpse into Your Future at Orderly Network\n\nWe’re hiring a Web3 Frontend Engineer to help us build the next generation of decentralized applications. You’ll work onsite with a fast-moving team in Ho Chi Minh City—no remote work—collaborating closely with smart contract developers, product managers, and designers.\n\nWhat will you be working on?\nBuild modern, responsive UIs using React.js or Next.js\nIntegrate with smart contracts via Web3.js or Ethers.js\nHandle wallet connections (MetaMask, WalletConnect, etc.)\nConnect to and display real-time data (orderbooks, price feeds) via WebSocket\nWork with APIs (GraphQL or REST) and manage data with PostgreSQL / Redis\nContribute to smart contract logic (basic/intermediate Solidity or Rust)\nIntegrate DeFi components like AMMs, orderbook DEXs, or liquidity pools\nAbout you\nStrong experience in React.js or Next.js, and UI libraries like Shadcn/UI, Chakra, or MUI\nSolid experience in Web3 development\nGood understanding of backend with Node.js\nIntermediate English communication (verbal & written) – you’ll work in an English-speaking environment\nMust be based in Ho Chi Minh City – onsite only, no remote\n\nInterested in Learning More?\nOur hiring process begins by meeting with our People Team, who help facilitate the process of placing you in your new role. You can expect to share your experience and ideas in online video interviews with our hiring team, made up of management and potential new colleagues.\nIf you have experience in developing trading systems or financial-related products is a plus.\nYou can prepare for this interview by mentally organizing your strategies and opinions on topics such as Web3, cryptocurrency trading platforms, and your vision of how to succeed.\nShare this! Don’t be afraid of friends or co-workers stealing this job! If you are amazing and smart we will find a place for you. Check out our External Referral Incentives Program as well.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミンシティ都市圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1465, 737, 2, 'Full Stack Developer (.NET, ReactJS)', 'Summary\n\nJoin Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia\'s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nJob Description\n\nWe are seeking a highly motivated Full-Stack Developer (.NET ReactJS) to join our development team. In this role, you will be responsible for designing, building, and maintaining robust web applications across the entire stack—from front-end UI/UX design to back-end services and databases. You will collaborate closely with cross-functional teams to deliver scalable, high-performance solutions that meet both user needs and business objectives.\n\nCore Responsibilities\n\n• Design and develop responsive, user-centric front-end components using modern JavaScript frameworks (e.g., ReactJS).\n• Develop and maintain scalable back-end APIs and services using technologies such as .NET Core.\n• Integrate front-end components with back-end logic and database systems (i.e. SQL).\n• Collaborate with UI/UX designers, product managers, and other developers to define and implement solutions.\n• Write clean, testable, and well-documented code.\n• Implement and maintain CI/CD pipelines to ensure rapid and reliable deployment of applications.\n• Optimize applications for performance, security, and scalability.\n• Troubleshoot and debug issues across the stack in development and production environments.\n• Participate in code reviews and mentor junior developers when needed.\n\nTechnical Skills\n\n• Minimum 3-4 years of experience as a full-stack developer using .Net Core, ReactJS and SQL.\n• Proficiency in front-end technologies: HTML, CSS, JavaScript, and one or more modern frameworks (React, Angular, etc.).\n• Strong experience with server-side languages such as .Net Core, C#.\n• Familiarity with database technologies (SQL, NoSQL).\n• Experience with RESTful APIs and microservices architecture.\n• Knowledge of version control systems like Git.\n• Familiarity with Agile/Scrum methodologies.\n• Excellent problem-solving and communication skills.\n\nThings that will separate you from the rest\n\n• Exposure to CI/CD tools like Jenkins, Docker, GitLab CI, Maven.\n• Familiarity with JIRA, Confluence, and Agile development methodologies.\n• Solid understanding of HTML5 and CSS.\n\nEducation or Certifications\n\n• Bachelor\'s Degree or higher, major in IT, Computer Science.\n\nJob Type\n\n• Full-Time.\n\nSchedule\n\n• Monday to Friday.\n\nWork Location\n\n• The Six8 Building: 24-26 Phan Dinh Giot, Tan Binh District, HCMC.\n• VDB Tower: 74 Quang Trung, Hai Chau, Danang.\n\nBenefits\n\n• Health insurance.\n• Dental insurance.\n• Paid time off.\n• Parental leave.\n• Childcare assistance.\n\nThis job description is not intended to be all-inclusive. An employee may also perform other reasonable related business duties as assigned by their immediate supervisor or management. Principals only. \n\nRecruiters please don\'t contact this job poster. DO NOT contact us with unsolicited services or offers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Ho-Chi-Minh-Stadt', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1466, 869, 2, 'Temenos Developer (Infinity)', 'About Finative At Finative, we help banks and fintech companies across APAC and Europe accelerate digital transformation through tailored IT solutions. We’re now looking for a Temenos Infinity Developer to join our remote team and build the future of core banking systems with us.\n\n🛠️ What You’ll Do\n- Design and develop Temenos Infinity (formerly Temenos UX/DS) digital banking applications\n- Work closely with product owners, BAs, and UI/UX teams to implement engaging user journeys\n- Customize and configure components using Temenos UXP, Temenos Digital Engagement Platform (DEP), and Infinity Studio\n- Integrate frontend layers with backend APIs, including Temenos Transact, TCIB, or third-party services\n- Participate in code reviews, system testing, and deployment processes\n- Troubleshoot and resolve application issues in both dev and production environments\n- Document solutions, configurations, and processes\n\n✅ What We’re Looking For\n- Experience developing in Temenos Infinity or Temenos Digital Front Office platforms\n- Strong skills in JavaScript/TypeScript, Angular, or React, ideally in Infinity context\n- Hands-on with Infinity Studio, Temenos UXP, and RESTful API integration\n- Familiarity with Temenos Transact or similar core banking systems\n- Understanding of digital banking channels: Retail, SME, Corporate, Onboarding\n- Ability to work in an agile, remote, and client-facing environment\n- Good English communication skills (written and spoken)\n\n✨ Nice to Have\n- Experience with Backbase, Finacle, or other digital banking platforms\n- Exposure to DevOps tools, CI/CD pipelines, or cloud-native deployment\n- Previous work on mobile banking apps or responsive UI design\n- Banking domain knowledge (KYC, onboarding, payments, accounts, etc.)\n\n📦 What You’ll Get\n- 100% remote working culture\n- Flat team structure, direct communication, no red tape\n- Work with international banking clients and modern banking stacks\n- Competitive compensation and opportunity for long-term collaboration\n\n💬 How to Apply\nPlease send us your CV at hr@finative.dev or apply here.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1467, 674, 2, 'Thực tập sinh Lập trình python (Python Development Internship)', 'Mô tả công việc\n\n• Phát triển các Bot làm Dịch vụ tự động hóa cho các lĩnh vực như Thương mại điện tử, Human Capital - HR, Financial Capital - Finance, Trading, Blockchain, Legal, Real Estate\n• Tìm và nghiên cứu để sử dụng lại các API có sẵn từ các công cụ nguồn mở để xây dựng ứng dụng dưới dạng dịch vụ web và sẽ được lưu trữ trên máy chủ.\n• Tìm và nghiên cứu các công cụ nguồn mở có sẵn, cấu hình các công cụ để tích hợp vào các công cụ của công ty lớn.\n• Quản lý và bảo trì máy chủ, thiết kế quy trình vận hành máy chủ, lập kế hoạch sử dụng và dự phòng máy chủ Ubuntu.\n\nYêu cầu công việc\n\n• Trình độ chuyên môn: Sinh viên năm thứ 2 đến cử nhân tốt nghiệp đại học các ngành liên quan như công nghệ thông tin, toán - tin học ...\n• Có kiến thức cơ bản về ngôn ngữ lập trình, đặc biệt là Python, biết sử dụng hệ điều hành Ubuntu, có kiến thức chuyên sâu về toàn bộ quy trình phát triển ứng dụng web (thiết kế, phát triển, triển khai)\n• Kỹ năng phân tích và quản lý thời gian, tư duy logic và thuật toán tốt.\n• Chủ động trong công việc, có tinh thần trách nhiệm, có tinh thần làm việc nhóm, có khả năng nghiên cứu công việc mới, thực hiện các yêu cầu từ cấp trên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quoc Tuan Commune, Haiphong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1468, 870, 2, 'IT Developer (System Development & Operations)', 'Working location: Thien Nhan Hospital Da Nang - 276-278-280 Dong Da Street, Da Nang City.\nType: Full-time\nReports to: (Not specified – can be updated if needed)\n\nKey Responsibilities:\n- Manage and optimize websites, booking systems, chatbots, and other digital tools.\n- Develop new features (web apps, internal portals, etc.).\n- Support server, domain, email, hosting, and data security operations.\n- Monitor, troubleshoot, and maintain existing IT systems.\n- Collaborate with software vendors for integration requests.\n\nRequirements:\n- Bachelor’s degree in IT, with at least 2 years of relevant experience.\n- Proficient in frontend (HTML/CSS/JS) and backend (PHP, Node.js, or Python).\n- Experience with CMS platforms like WordPress, Laravel, or similar frameworks.\n- Knowledge of system security, hosting, and server management is a plus.\n- Logical thinking, attention to detail, and a strong sense of responsibility.\n\nBenefits:\n- Attractive compensation based on capabilities.\n- Work in a modern, technology-focused healthcare environment.\n- Opportunities to enhance expertise through large-scale healthcare system projects.\n\nApply via email: hr.thiennhanhospital@gmail.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1469, 871, 2, 'Software Developer', 'Số lượng: 1 người\n\nKinh nghiệm: 2 - 3 năm\n\nBằng cấp: Cao Đẳng, Đại Học\n\nCấp bậc: Nhân viên\n\nNơi làm việc: Tp. HCM\n\nThu nhập/ tháng: 20 - 25 Triệu\n\nJob Descriptions\n\nThis role involves two main tasks: software development and user support. In software development, you\'ll create and maintain web/mobile applications, including work on Sunjin\'s system. For user support, you\'ll assist end-users with program issues and provide documentation and training to end-user for smooth operation.\n\nSoftware development\n\n- Incharge for developing and maintaining the SFA (Sales Force Automation) system. \n- Involved in developing Sunjin’s systems, such as HRM, SAP, and others. \n- Works with internal Business Analysts and key Users to develop softwares/solutions to fulfill business needs. \n- Apply new technologies and frameworks to develop flexible solutions that are suitable for the company\'s business.\n\nUser support:\n\n- Be the first-point contact for troubleshooting, and resolve issues/challenges related to business applications from users within the company.\n\nCompany main business applications: ERP (SAP B1), SFA, HRM, GOOGLE WORKPLACE\n\nJob Requirements\n\n- Bachelor’s Degree in computer science, engineering, or relevant field.\n- At least 2 years of JAVA development experience. Experience in operating CRM/SFA is preferred:\n  - Spring Framework, JSP, JavaScript, RDBMS (ORACLE, MS-SQL)\n- Ability to set up and WebSphere Application Server (Tomcat)\n- Ability to understand and develop Rest APIs\n- Have knowledge about Windows, Linux\n- Can understand English documents and make reports by English\n- Preference will be given to candidates working in internal companies\n\nWORKPLACE & WORK TIME\n\n- Workplace: Floor 12A, Sofic Tower, 10 Mai Chi Tho, Thu Thiem Ward, District 2, Ho Chi Minh City, Vietnam\n- Work time: 7:30 - 16:30 (Monday - Saturday), off 2 Saturdays a month\n\nCompensation & Benefits\n\n- Pay social insurance on total salary\n- 24/24 accident insurance for employees\n- Leave, holidays and company establishment date according to regulations\n- Provide breakfast and lunch at factories\n- Give birthday gifts and holiday gifts throughout the year\n- Annual travel\n- Internal and external training\n- 13th month bonus + productivity bonus based on business performance\n- Training program based on seniority\n- Foreign language allowance\n- Paid leave on the day the company is established\n- Support for shuttle and business vehicles outside the market\n- Phone, laptop, car support (according to company regulations)\n\nLiên hệ\n\nỨng viên quan tâm vui lòng gửi CV/ Resume theo địa chỉ mail:\n\nSunjinsouth@sj.co.kr\n\nMọi thắc mắc cần được giải đáp xin vui lòng gọi\n\nMr. Duc: 0337.416.150\n\nMs. Mai: 0396.764.259\n\nMs. Vũ: 0935.056.658', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Can Tho, Can Tho, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1470, 872, 2, 'Junior Game Developer', 'Join The Game! \nLeader in the development and publishing of multiplatform games, Gameloft® has established itself as a pioneer in the industry, creating innovative gaming experiences for 25 years. Gameloft creates games for all digital platforms, from mobile to cross-platform titles for PC and consoles. Gameloft operates its own established franchises such as Asphalt®, Dragon Mania Legends, March of Empires, and Dungeon Hunter, and also partners with major rights holders including LEGO®, Universal, Illumination, Hasbro®, Fox Digital Entertainment, Lamborghini®, and Ferrari®. Gameloft distributes its games in over 100 countries and employs 3,000 people worldwide. Every month, 1 billion unique users can be reached by advertisers in Gameloft games with Gameloft for brands, a leading B2B offering dedicated to brands and agencies. Gameloft is a Vivendi company.\nJob Description:\n- Develop, implement, and maintain game features using Game Engines (Unity, Roblox, Cocos Creator, Unreal).\n- Deliver and ensure high-quality game features.\n- Write efficient, clean, and reusable code to enhance gameplay and user experience.\n- Collaborate with game designers, artists and other team members to bring game concepts to life.\n- Analyzing existing features of the game and making changes to meet current needs.\nQualifications:\n- Proficiency in C#, Lua, JavaScript, Unity, Roblox.\n- Familiarity with AI (Copilot) is a plus.\n- Familiarity with mobile 2D/3D game development.\n- Good understanding of gameplay mechanics, UI, design patterns.\n- Familiarity with version control systems like Git.\n- Familiarity with VR/AR development, mobile optimization, CI/CD is a plus.\n- Ability to read, write, and communicate in English.\n- Good problem-solving mindset and communication skills.\n\nAdditional Information\nRecruitment Process:\n1) Screening call;\n2) Test;\n3) Interview(s);\n4) Offer.\n\nWork Location and Hours:\n- Work location 26 Ung Van Khiem, Binh Thanh District, Ho Chi Minh City.\n- Work hours 0830 AM - 0600 PM, Monday - Friday.\n\nWhy Join Gameloft?\n- You want to work in an exceptional industry and create games downloaded more than 1 billion times per year.\n- You want to be part of a talented and supportive team of pioneers who have a passion for creating video games.\n- You want to contribute to a vibrant and dynamic atmosphere.\n- You want to join a global company and meet great people around the world.\n- You will work on an employment contract with competitive remuneration and benefits package.\n- You are looking for a fun place to work in the heart of the city.\n\nWhat We Offer:\n- A hybrid working model (3 days WFO and 2 days WFH).\n- A dynamic workplace environment, with over 18 nationalities, where hundreds of world-renowned game titles were born.\n- A range of well-being events and policies to support employees physically, mentally, and emotionally.\n- An open-space office, a cafeteria, a terrace and a Gaming Area.\n- Various training packages, including internal training, sponsorship training, and e-learning (iLearn, Udemy,...).\n- Opportunities to collaborate and train with Gameloft worldwide experts and develop yourselves.\n- An attractive monthly salary alongside Tet and other performance bonuses.\n- Minimum 12 days of paid annual leave, plus 5 days of paid sick leave, Christmas leave, Birthday leave,...\n- 100% coverage of mandatory insurance and extra healthcare insurance.\n- A monthly allowance to support lunch meals and working-from-home electricity and Internet bills.\n- Other benefits from one of the best employers in Vietnam.\n\nWhat\'s more?\n- Want to know more? Visit our websites:\n- Saigon Studio website\n- LinkedIn page\n- Facebook page\n\nDue to the high number of applicants, we regret to inform you that only shortlisted candidates will be notified. Thank you for your understanding.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1471, 743, 2, '[LTS] Front End Developer (VueJS)', 'General Information\n\nQuantity: 2\nWorking place: Hanoi\nSalary: Negotiation\n\nJob Descriptions\n\nParticipate in development projects for Web application\nImplement responsive UI based on wireframes\nImplement interactive and dynamic components for use in CMS (Content Management Systems)\nPerform bugs fixing, maintaining, and enhancement\n\nRequirements\n\nAt least 1,5+ years of working as developers\nHTML/CSS, Responsive and cross-platform design,\nDeep understanding of syntax and semantics of JavaScript,\nAdvanced understanding of RESTful web services,\nModern front-end framework (Vue)\nOne of the backend languages is a plus – Java/Kotlin, C#, Go, NodeJS – intermediate level\nNice to have: Front-end testing framework (Jasmine, Jest, etc.), Version Control Systems (GIT) and best practices, CI/CD\nEnglish is a plus.\n\nBenefits\n\nAttractive salary. Performance-based award. Range up to 25M.\nYoung and dynamic working environment.\nContinuous development of hard and soft skills through work and professional training.\nOpportunity to approach the newest technology trends\nSalary review 2 times/year or on an excellent performance\nCompany’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.\n\nCONTACT\n\nLTS Recruitment Department\n\nPhone Number: 02466607474\nEmail: rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1472, 786, 2, '【教育事業】学校プラットフォーム開発フロントエンドエンジニア', '職務内容\n\n教務システムは、角川ドワンゴ学園が運営する日本最大の高校「N高等学校」「S高等学校」「R高等学校」の運営業務や生徒指導を行うためのシステムです。\n\nこちらの開発・運用をご担当いただきます。\n\n＜サービス内容＞\n\n〜日本最大のネットの高校を支える！技術で教育の未来を創る〜\n\n日本最大のネットの高校「N高等学校」「S高等学校」「R高等学校」などの教務システム開発・運用を担うエンジニアを募集しております！生徒数3万人を超える革新的な学びの場を、システムで支える重要なポジションです。\n\n生徒・保護者・教職員・事務員が日々の運営業務や生徒指導を行うための「N Lobby」などの教務システム開発・運用をご担当いただきます。\n\n【教務システムとは】\n\n学校運営に必要な様々な業務（校務）を管理するためのシステムです。N高等学校・S高等学校などの教職員・メンター・事務員が、生徒の学習や学校生活をサポートするために利用する、重要なシステムです。\n\n具体的には、以下のような機能があります。\n\n□生徒管理：\n\n履修登録・試験採点・成績管理・進級・卒業\n\n□学習サポート：\n\n学習管理システム「ZEN Study」との連携による、授業管理やテスト結果の共有・スクーリング（対面授業）の管理\n\n□入学手続き：生徒・保護者向けのマイページを提供し、オンラインでの出願手続きをサポート\n\n□入学までの各種手続き\n\n生徒の学校生活全体を支えるためのシステムであり、学校運営をスムーズに行う上で欠かせない存在です。\n\n＜募集背景＞\n\n事業拡大に伴い、教務システムの開発領域は拡大の一途を巡り、案件数も急増しています。\n\n各種手続きや申込みのデジタル化を推進し、業務効率化を図るため、新機能開発やシステム拡張のニーズが高まっています。\n\nまた、毎年1万人の生徒が増加し、現在ではアクティブな生徒数が3万人を超えています。増大するデータを適切に管理しながら、安定したサービス提供を続けていくことが求められています。\n\n現在、複数の開発プロジェクトを並行して進めており、特にアーキテクチャの見直しや技術的なチャレンジが増えている状況です。そこで、開発チームをリードし、技術的な課題を解決しながらシステムを進化させていくエンジニアを求めています。\n\nリーダーシップを発揮して開発を牽引したい方、新しい技術に挑戦しながら成長したい方にとって、大きな裁量と挑戦の機会がある環境です。\n\n共に教育業界の未来を創る仲間を募集します！\n\n＜お任せしたい業務例＞\n\n詳細設計\n実装\nテスト\nリリース\n運用\n不具合などの調査、修正\n\n＜開発環境＞\n\n□ 使用言語/ライブラリ\n\nTypeScript,Java,HTML/CSS,Nextjs(React)\n\n□ インフラ\n\nAWS(EC2,ECS,PostgreSQL)\n\n□ CI\n\nJenkins, GitHub Actions\n\n□ コミュニケーション\n\nSlack, Google Meet\n\n□ その他\n\nFigma,Wrike,GitHub Enterprise\n\n＜当ポジションの魅力＞\n\n教育の未来を創る 日本最大のネットの高校を支えるシステム開発に携わり、教育の可能性を広げるという社会貢献性の高い仕事です。\n\n技術的な挑戦 アーキテクチャの見直しや最新技術の導入など、常に新しい技術に触れ、スキルアップできる環境です。\n\n大きな裁量と成長機会 あなたのアイデアや技術力を活かして、システムをより良くしていくことができます。\n\n＜関連リンク＞\n\n□ エンジニア採用説明資料\n\nhttps://speakerdeck.com/nnndev/for-engineers\n\n□ ドワンゴ教育サービス開発者ブログ\n\nhttps://blog.nnn.dev/entry/2021/06/17/110000\n\n□ ZEN Study\n\nhttps://www.nnn.ed.nico/\n\n□ N高等学校・S高等学校・R高等学校プロジェクト採用\n\nhttps://www.nnn.ed.nico/recruit/\n\n□ ZEN大学\n\nhttps://zen.ac.jp\n\n必須要件\n\nReact等のコンポーネントベースなフレームワーク開発経験\nWebアプリケーション開発経験あり (3年以上)\n静的型付き言語の開発経験あり (3年以上)\n要件から設計まで落とし込めるスキル・経験をお持ちの方\nGitHub などでプルリクエスト駆動開発をしたことがある方\nORMを用いた開発経験\nORMにおいて、RDBに非効率的なクエリ (N+1等) を発行しない程度の理解がある方\nB2B 業務システム開発 3年以上\n\n歓迎要件\n\nTypeScriptの経験 (業務・プライベート問わず)\nパフォーマンスチューニングの経験 (フロント・バック問わず)\nテスト重視の開発経験\nRDBのスキーマ設計経験\n数百テーブルあるシステムの改修経験\nPostgreSQLでのパフォーマンス改善経験\nAWS EC2でのLinuxサーバ運用経験\nAWS Fargateでのコンテナアプリケーション構築経験\n業務システムの運用・保守対応経験\n開発向けの業務改善経験\n\n求める人物像\n\n自分の知らない技術にも意欲を持ち、自己の成長に積極的な方\n個人ではなくチームとしての成果を求めることができる方\n今の価値観に囚われず柔軟に対応できる方\n上記のようになりたいと考え、行動を始めている方\n\n職種 / 募集ポジション 【教育事業】学校プラットフォーム開発フロントエンドエンジニア\n雇用形態 正社員\n給与 応相談 前職を考慮し、当社基準により決定いたします。 昇給：年2回（6月・12月）本人の能力・役割に基づいて評価\n賞与：年2回（6月・12月）本人の成果に基づいて支給 ※ご入社時期、個人の評価、会社の業績により夏季賞与・冬季賞与額が変動いたします。 ※退職金は前払い退職金制度\n勤務地\n\n104-0061 東京都中央区銀座四丁目12-15 歌舞伎座タワー 地図で確認\n\n勤務形態 裁量労働制（1日8時間のみなし労働)\n休日休暇 完全週休2日制（土・日）、祝日（※超会議に伴う営業日変更あり） ・年次有給休暇（入社日に5日、入社日の3ヶ月後に15日付与） ・記念日休暇 ・年末年始休暇（12/29～1/3） ・リフレッシュ休暇（年度ごとに2日間付与） ・特別（慶弔）休暇\n手当・制度 ・テレワーク手当 ※テレワーク対象となる社員（条件有り）に対し、月額2万円を支給\n・通勤交通費手当（上限月額50,000円） ※テレワーク対象者は原則支給しない ただし、業務指示における出社時の交通費は会社が認める範囲で別途支給\n・育児手当（上限月額50,000円） ※扶養の子の保育料の半額を支給\n・役職手当（役職に応じて支給）\n・資格取得手当制度\n・サブスク手当（対象のサブスクを契約している場合、月額2千円を支給）\n\n福利厚生 ・各種社会保険完備（関東ITソフトウェア健康保険組合）\n・確定拠出年金制度\n・財形貯蓄制度\n・社員持株会制度\n・社内カウンセリング制度\n・同好会\n・健康保険組合各種サービス\n・社員限定美容室\n\n選考プロセス 書類選考後、2回の面接を想定しています。 ※1次面接までに当社が指定する適性検査を受検いただきます。 ※全てオンライン面接となります。 ※選考の過程でコードテストを実施する可能性があります。\n\n会社情報 会社名 株式会社ドワンゴ\n代表者 代表取締役社長 夏野 剛\n事業内容 ネットワークエンタテインメントコンテンツ及びシステムの企画、開発、運用、サポート、コンサルティング\n設立 1997年8月6日\n資本金 1億円（2019年3月29日現在）\n所在地 〒104-0061 東京都中央区銀座4-12-15 歌舞伎座タワー\n親会社 株式会社KADOKAWA\n子会社 株式会社バンタン 株式会社スパイク・チュンソフト Spike Chunsoft, Inc. 株式会社バーチャルキャスト 株式会社カスタムキャスト 株式会社GeeXPlus 株式会社PUBLUS', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 12군', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1473, 734, 2, 'Java Software Engineer', 'Make Our-Dreams Realized \nMOR Software JSC.\n\nMOR Software JSC is a company specializing in developing software products for the Japanese, Korean and American markets.\n\nCurrently, MOR has offices in the following cities: Tokyo (Japan), Ho Chi Minh, Hanoi and Da Nang. In addition, MOR is planning to open offices in Korea and the US.\n\nWebsite: https://morsoftware.com//\n\n+ MOR-HN (MH) is the "core" branch of MOR software with more than 200 employees, starting operations in October 2018. We always want to create a young, dynamic environment and constantly encourage employees to develop themselves.\n\nHanoi Office: 25F - B1 building, Roman Plaza, To Huu, Nam Tu Liem, Ha Noi\n\nPosition: Middle Java Developer  \n\nJob Description  \n- Develop and implement new features and functionalities  \n- Collaborate with the team to ensure high-quality deliverables.  \n- Participate in code reviews and design discussions.  \n- Work closely with QA to ensure the quality of the code.  \n- Ensure compliance with company policies, procedures, and quality standards throughout the project lifecycle.\n\nRequirements:  \nMust Have:  \n- Good communication skills in English.  \n- Strong knowledge of Object-Oriented Programming (OOP).  \n- Hands-on experience with:  \n- Java 17+ and Spring Framework (Spring Boot, Spring Data, Spring Security…)  \n- RESTful APIs  \n- Docker  \n- Relational Databases (e.g., MySQL, PostgreSQL)  \n- Microservices architecture  \n- Message brokers such as Kafka or RabbitMQ  \n\nNice to Have:  \n- Experience with cloud platforms: AWS, Azure, or Google Cloud.  \n- Knowledge or practical experience in applying AI to work (e.g., recommendation systems, prediction models, automation…).  \n- Experience with:  \n- Jenkins (CI/CD)  \n- NoSQL databases such as DynamoDB or MongoDB  \n\nBenefits:  \n- Salary: up to 30,000,000VND  \n- Full salary in the probation time  \n- Bonus 13th month salary, performance bonus, holiday bonus,...  \n- Annual performance review, twice/ year  \n- Sponsor exam and study costs for some professional certificates.  \n- Opportunity to work and short/long training abroad  \n- Learning encouragement fund: Japanese and English training courses held at the company, professional training courses, Udemy courses,...  \n- Take part in playing football, badminton team, board game team  \n- Opportunity to work in a young, dynamic, friendly, professional environment with a clear, fast, fully equipped process system.  \n- Work directly with foreign customers, experienced members such as BA, Technical Team, PQA,…  \n- Enjoy full benefits according to the provisions of the Labor Law.  \n- Premium healthcare insurance (VBI) annually.\n\nMore information:  \n- Company Address: 25th Floor, Tower B1, Roman Plaza, To Huu Street, Nam Tu Liem District, Hanoi.  \n- Working Hours: 8:30 AM – 5:30 PM, Monday to Friday.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1474, 864, 2, 'Backend Developer (Scala/Java)', 'Swif.ai is on a mission to transform how businesses leverage AI. We’re a tight-knit, fast-paced team focused on building innovative solutions that redefine efficiency, scalability, and user experience. If you’re eager to shape the future of AI—and aren’t afraid to push boundaries—read on.\n\nWhat You’ll Do\n\nArchitect & Develop: Build, maintain, and optimize high-performance backend systems using Scala (or Java).\nLeverage AI Tools: Use Windsurf, Cursor, or other AI-powered coding tools to accelerate development and elevate code quality.\nEnsure Reliability: Write clean, testable, and efficient code while implementing best practices for resilience and scalability.\nCollaborate Across Teams: Partner with product managers, data scientists, and frontend engineers to deliver cohesive, end-to-end solutions.\nDebug & Optimize: Investigate complex issues in production environments, identify bottlenecks, and implement improvements.\nCommit to Agility: Be prepared to work 6 days a week in a dynamic environment, ready to adapt and iterate quickly.\n\nWhat We’re Looking For\n\nProficiency in Scala/Java: Strong understanding of functional or object-oriented programming, concurrency, and distributed systems.\nAI-Driven Coding Experience: Familiarity (or willingness to learn) with AI agents like Windsurf, Cursor, or similar tools to streamline your workflow.\nSolid Technical Foundations: Deep knowledge of algorithms, data structures, and system design principles.\nProblem-Solving Mindset: Ability to tackle challenges with creativity and tenacity.\nTeam Player: Clear communication skills, openness to feedback, and a desire to share knowledge with colleagues.\nAdaptability & Grit: Comfortable with a 6-day work schedule and excited by the fast pace of a growing startup.\n\nWhy Join Swif.ai?\n\nPioneering Projects: Develop AI solutions that shape the next generation of business technology.\nRoom to Grow: Professional development, mentorship, and a trajectory for meaningful career advancement.\nCollaborative Environment: Work with a supportive team that values fresh perspectives and continuous learning.\nCompetitive Compensation: We reward the extra dedication, expertise, and ambition you bring to the table.\n\nReady to build the future of AI-driven solutions with Scala and Java? Apply now to join Swif.ai and make an impact!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1475, 679, 2, 'HCM – AI Engineer – LLM/NLP (Hybrid Working)', 'AI Engineer – LLM/NLP (Hybrid Working)\n\nVexere: Revolutionizing Travel and Transportation in Vietnam\n\nWe are a Vietnamese technology company aiming to revolutionize the travel and transportation industry. As the largest online bus ticketing platform in Vietnam, we help millions of travelers make unforgettable journeys. Recently we expanded to airlines, trains, and vehicle rentals in order to provide our customers with the best options for their travel plans.\n\nVexere’s Culture\n\nVexere members believe our organization exists to solve pressing societal problems. Our company culture emphasizes community spirit, mutual support, and open communication. We encourage all members to express ourselves, contribute ideas on products and strategies, and strive to become future leaders.\n\nVexere’s Vision\n\nVexere aspires to be a constantly growing and innovative business. We foster a strong culture of learning and development, aiming to leverage our technological strengths to continue revolutionizing the transportation and tourism sectors across Southeast Asia.\n\nWe are rebuilding every customer and employee touch-point as an AI-native experience. That ranges from booking a flight/bus/train seat to automating sale processes or leave requests. Engineers here get clear goals, full context, and the freedom to ship quickly while keeping reliability and safety paramount.\n\nResponsibilies\n\nMajor projects you will tackle\n\n- Omni-channel customer chatbot that handles FAQs, after-sales, and ticket booking for bus, flight, train, and vehicle-rental verticals—across text and voice.\n- Department-specific assistants for HR onboarding, finance invoice queries, operations incident triage, IT help-desk, and more—each powered by shared LLM components and n8n triggers.\n- Company-wide automation hub built on n8n, including reusable nodes and guard-rails that let non-technical teams create flows safely.\n- Multimodal expansion that blends text, speech, and images so customers can, for example, upload a ticket photo or speak a booking change request.\n- You will fine-tune foundation models, fuse retrieval with LLM reasoning, and iterate in Vietnamese, English, and other languages.\n\nWhat You Will Do\n\n- Design, implement, and continually improve our multi-agent framework. Build and refine agent components such as short- and long-term memory stores, planning/reflection loops, agent-to-agent messaging, and specialised prompt templates that let multiple agents collaborate on complex tasks.\n- Select and adapt OpenAI, Gemini models, Llama, Mixtral or better—using LoRA or full fine-tuning—so the models speak our brand voice in multiple languages.\n- Build and optimise retrieval-augmented pipelines, keeping latency below two seconds and hallucinations under five percent.\n- Craft prompts, refusal rules, and jailbreak tests; automate factuality, safety, and multimodal hallucination checks in CI.\n- Package models with Docker and serve them through FastAPI or gRPC behind vLLM, Triton Inference Server, or Text-Generation-Inference; add monitoring with Grafana / Prometheus for latency, drift, and GPU cost (for later milestones).\n- Pair daily with Conversation Designers, MLOps engineers, Automation engineers, and business stakeholders; publish model cards, data sheets, and rollback plans.\n\nRequirements\n\nMust-have qualifications\n\n- 1+ years of experience shipping NLP or generative-AI systems to production.\n- Strong Python and PyTorch skills plus heavy use of Hugging Face (Transformers, PEFT, Datasets).\n- Practical knowledge of vector databases such as milvus, pgvector, Qdrant, or Pinecone and hybrid-search techniques.\n- Demonstrated ability to raise containment or reduce hallucinations through data-driven experiments.\n- Solid engineering habits: Git, code reviews, unit and integration tests, CI/CD pipelines.\n- Clear spoken and written English; Vietnamese fluency is a bonus.\n\nNice-to-haves\n\n- Hands-on experience with Rasa, Dialogflow CX, or ASR/TTS pipelines for voice bots.\n- Deep GPU-performance tuning, including quantisation, KV-cache optimisation, or custom Triton kernels.\n- Familiarity with multi-agent frameworks such as PydanticAI, CrewAI, LangGraph or others.\n- A privacy-by-design mindset and working knowledge of GDPR or PDPA compliance.\n\nBenefits\n\n- Competitive salary + KPI-based quarterly bonuses.\n- Hybrid Working\n- Clear career progression with opportunities for advancement to key positions based on your capabilities.\n- Special discounted bus tickets for employees and their families.\n- Comprehensive periodic health check-up policies.\n- Participation in social insurance, health insurance, and unemployment insurance according to Vietnamese labor law after the probationary period.\n- 12 days of annual leave, with an additional day added every 3 years (convertible to salary).\n- Vibrant and dynamic working environment with a friendly and supportive team that shares knowledge and assists each other.\n- Training and development opportunities in negotiation, communication, work management, interpersonal skills, and software technology.\n- Free parking and allowances: Marriage, Newborn baby and others are applied.\n- A spacious pantry fully equipped with a coffee maker, microwave, milk, tea and more.\n- A wide range of sports and social activities: badminton, pickleball, football, etc.\n- Other perks to be discussed during the interview.\n\nFor More Information, Please Contact Us Via\n\n- Send your Resume to email: careers@vexere.com, with title: Fullname – Applied Position\n- Phone/ Zalo: 039 555 54 86 (Mr. Nhân)\n\nOffice Location: Vexere Trading and Services Co., Ltd. – 2nd Floor – Building H3, 384 Hoang Dieu, Ward 6, District 4, HCMC\n\nWorking Hours: 8:30 am – 6:00 pm from Monday to Friday, and Saturday morning.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1476, 411, 2, 'Security Engineer - Blue team', 'Mô tả công việc:\n- Giám sát, xử lý cảnh báo ATTT từ các nguồn dữ liệu Endpoint, Network, Gateway, Application,... để phát hiện và xử lý các hành vi bất thường: scan, recon, exploit, bruteforce,...\n- Tham gia xử lý, điều hành ứng cứu sự cố ATTT theo phân công.\n- Nghiên cứu các lỗ hổng mới (CVE), kỹ thuật tấn công mới của các nhóm APT. Threat Hunting chủ động tìm kiếm các mối đe dọa tiềm ẩn.\n- Xây dựng các nội dung Detection: phát triển và cải tiến các rules để phát hiện tấn công hiệu quả, giảm thiểu các cảnh báo sai.\n- Sử dụng hoặc xây dựng các playbook automation tăng tốc quá trình xử lý cảnh báo và điều tra ứng cứu sự cố.\n- Xây dựng hoặc cải thiện quy trình xử lý sự cố, xử lý cảnh báo, xử lý nguy cơ và các vấn đề khác liên quan đến hoạt động đảm bảo ATTT.\n- Đào tạo và hướng dẫn các Security Analyst Tier 1, Tier 2 để nâng cao năng lực đội nhóm.\n\nYêu cầu:\n- Tốt nghiệp Đại học chuyên ngành An toàn thông tin, Công nghệ thông tin, Khoa học máy tính hoặc các chuyên ngành khác có liên quan.\n- Tối thiểu 3 năm kinh nghiệm làm việc trong lĩnh vực An toàn thông tin.\n- Có kinh nghiệm forensic, xử lý sự cố và phân tích mã độc.\n- Sử dụng thành thạo các nền tảng SIEM, SOAR, và các công cụ khác hỗ trợ điều tra sự cố ATTT như Autoruns, Procexp, TCPView, PCHunter, các lệnh rà soát trên Linux,....\n- Kinh nghiệm chuyên sâu trong viết và tối ưu hóa detection rules trên SIEM, đặc biệt là ELK Stack.\n- Có kỹ năng phân tích và giải quyết vấn đề, kỹ năng trình bày bằng Tiếng Việt và Tiếng Anh.\n\nƯu tiên:\n- Kinh nghiệm triển khai các dự án AI SOAR hoặc tích hợp với các mô hình AI để phân tích cảnh báo và phản ứng sự cố là một lợi thế lớn.\n- Kinh nghiệm về system security (linux, windows), cloud security (AWS, Azure, GCP) và bảo mật container (Docker, Kubernetes).\n- Có kinh nghiệm săn tìm mối đe dọa chủ động (proactive threat hunting).\n- Có các chứng chỉ uy tín liên quan.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1477, 873, 2, 'Game Designer', '1. Mô tả công việc\n– Tìm hiểu, nghiên cứu thị trường và xu hướng game mới\n– Thiết kế bộ tài liệu game design đầy đủ về tính năng, nội dung, level, giao diện, âm thanh…\n– Tham gia triển khai dự án, kiểm soát chất lượng sản phẩm, vận hành và tối ưu các chỉ số cơ bản\n– Phân tích, đánh giá và cân bằng game.\n– Theo dõi, báo cáo và đưa ra các giải pháp tối ưu cho dự án.\n– Hỗ trợ team marketing chuẩn bị các tài liệu trong giai đoạn phát hành sản phẩm.\n\n2. Yêu cầu\n– Trên 6 tháng kinh nghiệm làm Game Design và đam mê chơi game, làm game.\n– Đã tham gia các dự án Puzzle, Casual, Midcore…\n– Có kiến thức, kinh nghiệm sử dụng các công cụ hỗ trợ triển khai dự án như firebase, analystic\n– Có kinh nghiệm test, kiểm soát chất lượng đầu ra\n– Có kiến thức chuyên môn tốt về: User experience, User behavior, Level design, Progression design, Monetization design\n– Thành thạo các công cụ làm tài liệu thiết kế game: word/excel, mind map, mockup/wireframe…\n– Có tư duy logic và tinh thần trách nhiệm cao trong công việc\n\n3. Quyền lợi:\n– Lương: up to 2000$\n– Nhiều hạng mục thưởng hấp hẫn: Thưởng tháng, thưởng doanh thu, thưởng quản lý/chuyên gia, thưởng thành thích và thưởng các dịp lễ Tết, sinh nhật công ty…\n– Lộ trình thăng tiến rõ ràng, minh bạch\n– Môi trường làm việc trẻ trung, năng động và thân thiện\n– Được chủ động đề xuất các ý tưởng cải tiến sản phẩm và chiến lược phát triển sản phẩm.\n– Được phát huy tối đa khả năng sáng tạo của bản thân.\n– Được nghỉ phép 14 ngày/năm và được tham gia ít nhất 2 kì nghỉ của công ty: du lịch hè và teambuilding cuối năm.\n– Chế độ nhà nước đầy đủ\n\n4. Hồ sơ bao gồm\n– CV nêu rõ kinh nghiệm làm việc\n– Link các sản phẩm.\n\nVui lòng gửi CV về email: hr@cscmobi.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1478, 197, 2, 'Backend Engineer (Go, Java) - DOP', 'Join Trusting Social as a Backend Engineer on our Credit Insight project, the cornerstone of our company, delivering automated credit scoring services to over 1 billion people globally by handling high volumes of applications efficiently through 100% automated registration, approval, and decision-making processes.\n\nResponsibilities\n\n- Develop Scalable Web Service APIs: Build highly scalable, highly available, and fault-tolerant web service APIs designed to handle millions of transactions per day.\n- Agile & DevOps Practices: Follow Agile methodologies and DevOps practices such as CI/CD to deliver quality code rapidly to market.\n- Seamless Integrations: Create software services that integrate effortlessly and securely with banks, third-party platforms, and vendors.\n- Innovative Problem Solving: Think outside the box, innovate, experiment, and continuously improve by learning quickly from failures to provide simple yet effective solutions to complex problems.\n\nRequirements\n\nEducational Background:\n\n- Bachelor’s degree or higher in Computer Science, Engineering, or a related field.\n\nExperience:\n\n- 5+ years of software development experience.\n- Solid expertise in Golang (or the confidence to learn it quickly when coming from other similar programming languages).\n\nAPI Design & Development:\n\n- Proficient in designing and developing RESTful APIs and gRPC interfaces.\n- Experience building backend services optimized for high performance, scalability, and reliability.\n\nDatabase Expertise:\n\n- Strong database and schema design skills for performance and scalability across both relational and NoSQL databases (e.g., MySQL, PostgreSQL, MongoDB, Redis, Elasticsearch, RocksDB).\n\nSystem Design:\n\n- Deep understanding of complex system design, design patterns, data structures, algorithms, microservices, and event-driven architecture.\n- Experience with system tuning for high performance and reliability.\n\nDevOps & Tooling:\n\n- Hands-on experience with CI/CD tools such as GitHub workflows and Jenkins.\n- Familiarity with Docker containers and Kubernetes.\n- Knowledge of automated testing practices, caching techniques, and version control systems like Git.\n\nNice to Have:\n\n- Experience with cloud platforms (AWS, GCP, or Azure).\n- Exposure to or interest in the AI domain with a willingness to leverage AI to enhance team productivity.\n- Experience with microservice architecture is a plus.\n\nWhat We Offer\n\n- Competitive compensation package, including 13th-month salary and performance bonuses.\n- Comprehensive health care coverage for you and your dependents.\n- Generous leave policies, including annual leave, sick leave, and flexible work hours.\n- Convenient central district 1 office location, next to a future metro station.\n- Onsite lunch with multiple options, including vegetarian.\n- Grab for work allowance and fully equipped workstations.\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday.\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized.\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets.\n\nAbout Us\n\nWe are an AI Fintech company specializing in assessing credit profiles of consumers in emerging markets combining pioneering AI with large alternative data sources. In 2020 we reached our ambitious milestone of credit profiling 1 billion consumers spanning 4 countries - Vietnam, Indonesia, India & the Philippines - and building a platform for the wider industry and the financial services industry, in particular, to provide the "un & underserved" access to credit. At the core of this initiative has been our strict and unwavering adherence to the norms of consumer data privacy and consumer data rights.\n\nBut we\'re not satisfied as we embark on the next leg of our journey to deliver 100 million credit lines to consumers in the markets where we operate. Although this goal is ambitious, we truly believe that by harnessing the power of AI & Big Data we can deliver financial access at an unprecedented scale.\n\nAs a firm, we\'re audacious problem-solvers motivated by our impact on society. We deeply espouse the values of ownership - of our actions and initiatives, integrity in all we do, and agility in execution.\n\nWe place great importance on doing what is right, what is best, and what is innovative. If you are smart, driven, and want to make a difference in the world with the most advanced and fascinating technology, come join our team. We can satisfy your desire to explore new territory and give you the runway to really make an impact.\n\nAdditional Info\n\nLearn more about us here:\nhttps://www.youtube.com/watch?v=inAEDGvOcL8&t=29s', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1479, 874, 2, 'Full Stack Developer (.NET, ReactJS)', 'Work location: Tan Binh, Ho Chi Minh City, Vietnam\nWork type: Hybrid (Mon-Thu in office; Fri at home)\nSalary: open to negotiation\n\nOVERVIEW\nJoin our company, a leader in SaaS solutions for the Payments and Compliance industries. The company is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, the company offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, the company is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. The company’s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at the company promises a great challenge, culture, and opportunities to forge your own path.\n\nDESCRIPTION\nWe are looking for a talented and motivated Full Stack Developer (.NET ReactJS) to join our dynamic team. As a Full Stack Developer, you will work on developing and maintaining web applications using .NET, SQL Server, and React. You will collaborate with cross-functional teams to deliver high-quality software solutions that meet our clients\' needs.\n\nCore Responsibilities:\n1. Develop and maintain web applications using .NET, React, and SQL Server.\n2. Ensure the quality and performance of applications through testing and code reviews.\n3. Follow best practices for software development, including coding standards, code reviews, and version control using Azure DevOps.\n4. Work within the SAFe Agile framework to deliver projects on time and within scope.\n\nFunctional Responsibilities:\n1. Participate in all phases of the software development lifecycle, including requirements gathering, design, coding, testing, and deployment.\n2. Collaborate with cross-functional teams to define and implement new features.\n3. Assist in continuous integration and continuous deployment (CI/CD) processes using Azure DevOps.\n\nJOB REQUIREMENTS\nTechnical Skills:\n1. Excellent English communication (preferable IELTS 7.5).\n2. Proficiency in .NET, React, and SQL Server (at least 3+ years in both .NET and React).\n3. Strong understanding of web development principles and best practices.\n4. Experience with Azure DevOps for version control and CI/CD processes.\n5. Familiarity with the SAFe Agile methodology.\n6. Excellent problem-solving skills and attention to detail.\n\nThings that will separate you from the rest:\n1. Experience with Node.js.\n2. Experience with other front-end frameworks/libraries such as Vue.js and Angular.\n3. Knowledge of cloud services and infrastructure, especially Azure.\n4. Experience with RESTful API design and development.\n5. Understanding microservices and event driven architecture.\n\nEducation or Certifications:\n1. Bachelor’s degree in Computer Science, Information Technology, or related field.\n\nINTERVIEW PROCESS\n1. HackerRank test tại nhà\n2. Phỏng vấn technical bằng tiếng Anh với Managers tại văn phòng\n3. Phỏng vấn online với PGĐ + Country Manager', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミン市, ベトナム', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1480, 674, 2, 'Tuyển Nhân Viên ML Engineer', 'Mô tả công việc\n\nPSA là công ty eCommerce hoạt động trong các lĩnh vực Print-on-Demand, Dropshipping, Fulfillment và Bán lẻ online, phục vụ hơn 10,000+ khách hàng toàn cầu.\n\nChúng tôi đang phát triển các hệ thống nội bộ (ERP, OMS, CRM, Data Analytics...) nhằm tối ưu hóa quy trình vận hành và nâng cao trải nghiệm người dùng, hướng tới mô hình AI-driven eCommerce.\n\nMô Tả Công Việc\n\nChúng tôi đang tìm kiếm Machine Learning Engineer để thiết kế và triển khai các giải pháp AI/ML ứng dụng trong hệ thống vận hành thương mại điện tử quy mô lớn.\n\nBạn sẽ làm việc cùng team Product, Data và Dev để:\n\n- Thiết kế, huấn luyện, và triển khai các mô hình ML cho:\n  - Dự đoán nhu cầu đơn hàng,\n  - Tối ưu tồn kho/kho vận,\n  - Recommendation hệ sản phẩm,\n  - Phân khúc khách hàng,\n  - Chatbot hỗ trợ CSKH.\n\n- Xây dựng pipeline xử lý dữ liệu (ETL) và hệ thống MLops cơ bản;\n- Đánh giá hiệu suất mô hình và triển khai lên production;\n- Tối ưu hóa chi phí và tài nguyên tính toán (GPU/Cloud).\n\nYêu cầu công việc\n\nBắt Buộc\n\n- Có từ 2-3 năm kinh nghiệm làm việc với ML (classification, regression, clustering...);\n- Thành thạo Python, NumPy, Pandas, Scikit-learn, TensorFlow hoặc PyTorch;\n- Có kinh nghiệm xử lý dữ liệu lớn, làm việc với data pipeline (Airflow, Spark, BigQuery là lợi thế);\n- Hiểu về triển khai mô hình trên môi trường thực tế (Docker, REST API, FastAPI, Flask);\n- Kỹ năng đọc hiểu tốt tài liệu tiếng Anh.\n\nƯu Tiên\n\n- Đã từng triển khai recommendation system, hoặc hệ thống AI trong eCommerce / Retail;\n- Có hiểu biết về kiến trúc MLops, model monitoring, versioning (MLflow, DVC);\n- Kinh nghiệm làm việc với các dịch vụ AI/ML trên Cloud (GCP Vertex AI, AWS SageMaker).\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Lương: Thỏa thuận theo năng lực + thưởng theo hiệu suất;\n- Lương T13, T14, tăng lương hàng năm theo năng lực;\n- Tham gia BHXH, BHYT, BHTN theo quy định, khám sức khỏe tổng quát định kỳ;\n- Du lịch 2 lần/năm, quà/thưởng lễ tết, sinh nhật, đồ ăn vặt tại văn phòng,...;\n- Hỗ trợ ăn trưa, gửi xe, laptop làm việc;\n- Tham gia các khóa học nâng cao chuyên môn.\n\nHình thức làm việc (chọn 1 trong 2 hình thức sau):\n\n- Office: T2-T6: 9:00-17:30 (nghỉ trưa 1h30p) / sáng t7 remote: 8:00-12:00\n- Remote: T2-T6: 8:30-17:30 (nghỉ trưa 1h30p) / sáng t7: 8:00-12:00\n\nĐịa chỉ: Tropic Garden A2 - 56 Đường số 66, Thảo Điền, Thủ Đức, HCM\n\nCách Thức Ứng Tuyển\n\nGửi CV + Bảng điểm (scan/ảnh file pdf, jpeg, png) về email career@makezbright.com hoặc liên hệ Zalo: 0942 485 129 (Vy PSA).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1481, 875, 2, 'Software Engineer', 'About Flex Living\n\nFlex Living is on a mission to transform the rental sector globally. We believe that renting a home should be as easy as buying an item from Amazon. Giving tenants the option to easily rent anywhere in the world and giving landlords simple, hassle-free property management without excessive management fees. We are building a small and dynamic team of A-Players, who are committed to growth and ready to scale Flex Living to a global powerhouse in its sector. We believe in rewarding ambition and promoting from within.\n\nPosition Summary\n\nAs a Software Developer, you will be instrumental in designing, developing, and maintaining robust digital solutions to support Flex Living’s operations and customer experiences. You will work on a variety of projects spanning front-end and back-end development, cloud deployment, and automation. This role requires strong problem-solving skills, adaptability, and a proactive approach to driving innovation and efficiency in our software systems.\n\nKey Responsibilities\n\nFull-Stack Development: Design, develop, and maintain scalable web applications using Node.js and React.\nDeployment & Cloud Management: Deploy and manage applications on AWS Cloud, utilizing serverless architecture.\nAPI Development: Design, implement, and optimize RESTful APIs using FastAPI (Python optional) and other modern frameworks.\nAutomation & Scripting: Build automation tools to streamline development processes.\nProblem-Solving & Debugging: Analyze complex problems, identify root causes, and implement efficient solutions.\nCollaboration & Communication: Work closely with cross-functional teams to ensure seamless integration and execution of key projects.\nCode Quality & Best Practices: Implement CI/CD pipelines, conduct code reviews, and ensure best practices in Git, testing, and software quality assurance.\n\nWhat We’re Looking For\n\nProficiency in Node.js, React, and AWS Cloud.\nExperience with serverless applications and cloud infrastructure.\nStrong problem-solving skills and ability to quickly learn new technologies.\nFamiliarity with FastAPI, Python, and scripting is a plus.\nUnderstanding of modern software development practices (CI/CD, testing, Git).\nExcellent communication and collaboration skills.\nAdaptability and a proactive, solution-oriented mindset.\n\nWhy Join Flex Living?\n\nBe part of an innovative and fast-growing company revolutionizing the real estate industry.\nOpportunity to build a team and establish a long-term presence in one of Europe’s most vibrant cities.\nCompetitive salary and performance-based incentives.\nA chance to grow professionally in a hands-on, entrepreneurial role.\n\nYou Should Not Apply If\n\nYou are looking for a corporate 9 to 5 job\nYou are political and enjoy gossiping and talking about people behind their backs.\nYou are looking for a stable and slow dead-end job\nYou do not aim to be one of the best in the world at what you do', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1482, 876, 2, 'Senior Java Software Developer', 'Key Responsibilities\n- Work as a software developer on web-based application products using Java and related open-source technologies.\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project developments with high quality.\n- Participate in all phases of the development cycle, including planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n- Respond to and resolve IT support requests from employees via phone, email, or service request system.\n\nRequired Skills & Qualifications\n- Good command of English (both written/verbal) is essential.\n- 5+ years of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend.\n- Ability to analyze, design, and develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner).\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools.\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc.\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications.\n- Solid understanding of OOP, design patterns, and coding standards.\n\nAdditional Information\nPreferred Qualifications:\n- Experience with AWS.\n- Experience with MS .Net / .Net Core.\n- Experience with Kubernetes.\n- Experience with React.js.\n- Experience with Nginx.\n- Experience with JUnit.\n- Experience with Jasper Report.\n- Experience with ElasticSearch & Kibana (ELK).\n- Experience with Grafana.\n- Experience with Prometheus (monitoring/alerts).\n\nBenefits:\n- Salary: Up to 60M VND\n- Probation salary is 100% of official salary.\n- 13th-month salary and performance review twice a year.\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year).\n- Project Bonus.\n- IT Certificate allowance.\n- Health Care Insurance.\n- Social, health, and unemployment Insurance following Government policy.\n- Enjoy company summer trips and other team-building activities held monthly and quarterly.\n- Work five days per week with flexible check-in time.\n- Professional, creative, and dynamic working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1483, 855, 2, 'Fullstack Developer (AWS)', '🌐 [HIRING] Fullstack Engineer – Cloud Application (Post Office Project)\n\n📍 Ho Chi Minh City | Hybrid | International Project\n🖥️ Cloud-native • Cross-functional team • Agile Scrum\n\n⸻\n\n🏢 About SCC & the Project\n\nSCC – Specialist Computer Centres – is Europe’s leading IT services provider, running mission-critical systems for 2,500+ clients across 50 countries. Our Vietnam team supports key projects for the UK & French markets.\n\nWe are hiring a Full-stack Developer to work on a major cloud-based system for Post Office UK – building secure, scalable applications in a cross-site Agile team with experts from Vietnam, UK, France, and Romania.\n\n⸻\n\n💼 Job Scope\n\nAs a core member of our Agile delivery team, you will:\n• Build and maintain modern, cloud-native applications and services (serverless, microservices).\n• Ensure system reliability, scalability, and performance.\n• Collaborate with architects, product owners, testers, and developers to deliver each sprint.\n• Apply security best practices and handle production issue troubleshooting.\n• Explore and apply new trends in cloud and software architecture.\n• Write and maintain clear technical documentation.\n\n⸻\n\n🧠 What You Bring\n\nMust-have:\n• 3+ years of experience in software development.\n• Proficient in Python, TypeScript, or C#.\n• Knowledge of at least one major cloud platform (AWS, Azure, or GCP).\n• Strong problem-solving mindset, attention to detail, and code quality standards.\n• Effective communication in English (verbal & written) – international teamwork.\n• Agile/Scrum team experience, preferably in global setups.\n\nNice-to-have:\n• Knowledge of AI/ML, Data Analytics, or Data Warehousing.\n• Experience using Power BI for building reports.\n• Familiarity with automation testing tools like Webdriver.io or Selenium.\n\n⸻\n\n👥 Team & Reporting\n• Work closely with VN & UK Technical Leads.\n• Collaborate with international teams (UK, France, Romania).\n\n⸻\n\n🎁 Why You’ll Love Working at SCC\n• Competitive salary + 13th-month pay + performance bonus.\n• Premium health care (includes dependents).\n• Hybrid working, international exposure, English-speaking environment.\n• Annual leave, sick leave, paid insurance, yearly health check.\n• Travel opportunities & per diem for onsite trips.\n\n⸻\n\n🚀 Join us if you want to:\n• Work on a large-scale UK national project.\n• Collaborate with international tech teams.\n• Be part of a team that builds reliable, secure, and smart cloud applications.\n\n📩 Apply now and let’s build future-ready systems together.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh e Região', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1484, 877, 2, 'Full Stack Engineer (NodeJS/Python)', 'Job Purpose\n\nAs a Full-stack Developer in the Logistics & Supply Chain domain, you will be responsible for developing and optimizing internal systems that support warehouse operations, transportation management, inventory tracking, and overall supply chain efficiency. You will work closely with product owners and business stakeholders to translate complex logistics requirements into scalable and robust software solutions.\n\nResponsibilities\n\n- Collaborate with business teams to analyze and understand logistics and warehouse-related requirements.\n- Design and implement end-to-end technical solutions for web-based internal systems.\n- Develop scalable frontend and backend modules using modern technologies.\n- Maintain and enhance application systems to support warehouse management, stock control, transportation tracking, etc.\n- Ensure performance, security, and reliability across logistics systems.\n- Set up and manage environments for development, testing, and deployment.\n- Actively participate in Agile/Scrum ceremonies and contribute to sprint goals.\n- Support users through UAT, training, documentation, and issue resolution.\n\nQualifications\n\n- Bachelor’s degree in Computer Science, Information Technology, or related fields.\n- At least 2- years of hands-on experience in fullstack development using:\n- Frontend: ReactJS, JavaScript, TypeScript\n- Backend: NodeJS\n- Database: PostgreSQL, MongoDB\n- Experience working on systems in logistics, supply chain, warehouse management, or related domains is a strong plus.\n- Familiarity with business logic in inventory movement, goods receiving/dispatching, transportation routing, etc. is highly preferred.\n- Experience in Agile/Scrum software development methodologies.\n- Proficient in using Git for source code versioning.\n- Strong analytical and problem-solving skills.\n- Self-motivated, proactive, and a good team player.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1485, 293, 2, 'Senior Front-End Engineer', 'Flodesk is one of the world\'s fastest-growing email marketing companies, built to help creators sell online and design emails that people love to get. Our commitment to small business owners is to create simple and intuitive tools that help them grow, nurture, and monetize their email list.\n\nWe\'re a remote-first company headquartered in San Francisco, California, with a globally distributed team—including an in-person office in Da Nang, Vietnam. Our team reflects the diversity and creativity of the people we serve. Join our mission to level the playing field for small business owners through good design\n\nAbout The Opportunity\n\nImplement, maintain, and update our component libraries, customer-facing websites/landing pages, and the web application at large.\nPush the boundaries of our web application to the next level in terms of performance, accessibility, and stability.\nContinuously refactor, improve and add automation testing for components (code coverage > 80%).\nProactively collaborate with our designers, provide feedback about UI/UX + animation, and bring new ideas to the table.\nProactively research new trends and updates in UX/UI technology.\nWork hand-in-hand with our current team to resolve issues in our core product, including but not limited to our proprietary WYSIWYG email builder.\n\nWhat you need to be successful\n\nStrong experience in HTML, CSS, and Javascript.\nFluent in React, Redux, and related tools.\nExperience writing automation testing—especially the React app.\nExperience in debugging and improving web app performance.\nHungry to learn and have the ability to learn things quickly.\nGood at English in both written and verbal.\n\nNice to haves:\n\nSpecific experience building web-based builder/drag and drop UI.\n\nWhy you should choose us\n\nWe are a profitable, fast-growing startup with a product that is transforming the industry. We value creativity, hard work, human connection, diversity, and being a great place to work!\n\nCompetitive salary and a 13th-month bonus.\nStock options for high contributors.\nPersonal development allowance of up to $1000/year.\nComprehensive healthcare coverage.\nFlexible work hours with standard five-day workweek.\nModern office with top-notch equipment like a Macbook Pro.\nOpportunities for career growth, including overseas options.\n\nIf you\'re passionate about making a difference and thriving in a dynamic, collaborative environment, we want to hear from you! Apply now and join us in shaping the future.\n\nFlodesk is an equal opportunity employer. We are committed to building a diverse and inclusive workforce and do not discriminate based on race, religion, color, national origin, ancestry, physical disability, mental disability, medical condition, genetic information, marital status, sex, gender, gender identity, gender expression, age, sexual orientation, veteran or military status, or any other legally protected characteristics, Flodesk is committed to providing reasonable accommodations for candidates with disabilities who need assistance during the hiring process. To request a reasonable accommodation, please email people@flodesk.com\n\nNotice to California-based Candidates for Employment. This California Candidate Privacy Notice is intended to provide information about how Flodesk collects and uses personal information to California consumers who apply for employment with Flodesk. If you are employed by Flodesk, refer to the Employee Handbook for additional information. For any questions about this notice, please contact People@flodesk.com.\n\nPersonal Information Flodesk Collects:\n\nIdentifiers Including name, address, email, telephone number, social security number, driver license number, passport number, and other personal identifying information. Characteristics of protected classifications under California or federal law, including demographic information and other personal information obtained during the application process, such as gender, race, national origin. Professional or employment-related information, such as salary/compensation and benefits packages, other relocation or job preferences, prior background, experience, skills, and other information in support of your application, reference information. Any other information you provide as a part of recruitment, job application, or interview process.\n\nPurposes for Collecting Personal Information:\n\nTo consider qualifications, skills, and interest for employment. To communicate with you during the recruitment and interview process. To provide compensation, including payroll, and administer stock options and benefits, including medical, dental, vision, commuter, and retirement benefits. To provide human resources services and conduct performance evaluations. To monitor work eligibility including work-related licenses, credentials, training, and eligibility to work in the United States. To improve recruitment and interview processes and ensure a safe and efficient working environment. To comply with applicable legal or regulatory requirements as Flodesk may transfer or store internationally your information, including to or in the United States, European Union and Vietnam and in the cloud, and this data may be subject to the laws and accessible to the courts, law enforcement and national security authorities of such jurisdictions.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1486, 878, 2, 'Full Stack Developer (Da Nang, Hybrid) (Visa and Relocation Package Provided)', 'About Nimble\n\nWe solve our client\'s most difficult business challenges through technology. Our company partners with the most ambitious companies around the world creating long-term impact with the work with do. If you want to grow together, work on challenging products and enjoy using the best tools and practices, Nimble is the right place for you!\n\nOur Core Values\n\n- Extreme Ownership: We treat our clients’ business as ours.\n- Bias for Action: Execution is everything. We act swiftly, prioritize decisive moves, and maintain a strong bias for action to deliver results.\n- Intensity: We tackle challenges with high energy and focus, delivering results through bold, committed actions.\n- Pragmatism: We prioritize practical, straightforward solutions that deliver results, creatively tackling complex challenges with determination.\n- Outcome Over Process: We always work toward impactful outcomes, driving results that matter. Processes help us repeat what works, but meaningful outcomes remain our North Star.\n- Truth Seeking: We seek truth with intellectual honesty, sharp critical thinking, and fact-driven reasoning.\n\nWhat You Will Do\n\n- You will be an active member or lead a team of developers in a project squad. We have a wide range of project sizes.\n- Decide which technologies are going to be used for front-end, back-end and define the overall architecture.\n- Work closely with the Product Owner to make sure the backlog is efficiently planned and occasionally assist in technical discussions with clients. Most of the client interfacing is done by the Product Owner.\n- Write clean, composable, and maintainable code as you develop world-class products for our clients.\n- Write automated tests to build and maintain the product we build for our clients.\n- Do code reviews with your squad members.\n- Learn new technologies languages like Ruby, Go, or Elixir, and techniques so that you are able to adapt to the evolving needs of our clients.\n- Knowledge sharing through team rituals.\n- Collaborate with other team members to define the internal processes and initiatives to help the company accomplish its mission. Our handbook has been written by the whole team.\n\nJob Requirements\n\n- Professional web development with 3+ years of experience. Experience in Ruby, JavaScript, Go or PHP is ideal (at least one of them).\n- Comfortable working both on frontend and backend.\n- At least basic experience with a modern JavaScript framework like ReactJS/Redux, VueJS or AngularJS.\n- Experience in writing automated tests for web applications.\n- Enjoy working on challenging solutions and systems.\n- Believe that building great applications is not only about delivering code that “works”, but involves thinking about reusability, maintainability, security, and performance.\n- A "Can do attitude" and a product mindset.\n- Confidence in communicating in English.\n\nWhy You\'ll Love Working Here\n\n- You’ll feel proud of every product we ship. We care deeply about quality, design, and doing things right—our name stands for excellence.\n- You’ll be surrounded by high performers. We’re a tight-knit, ambitious team that pushes each other to grow and thrive.\n- We\'re built differently. We’ve been profitable and bootstrapped since day one—no VC pressures, just smart, sustainable growth.\n- We take pride in craftsmanship. Whether it\'s code, design, or delivery, we hold ourselves to a high bar—because the little things shape the big picture.\n- Process with purpose. We follow agile principles not just in theory, but in practice. Our engineers work with clearly defined user stories, estimate using story points, and deliver iteratively in focused 1–2 week sprints.\n- Growth is part of the job. Through regular one-on-ones, structured feedback, and a clear leveling framework, we support every team member’s growth—not just in technical skills, but in communication, collaboration, and leadership.\n- Learning never stops. Access a vast library of resources like Pluralsight, PragPub, Leanpub, e-books, and more—plus a yearly education allowance to help you level up in any direction you choose.\n- We’ve got your back. From day one, you’ll get private medical insurance, social welfare coverage, and a company care fund.\n- We support your move. If you\'re joining us from abroad, we’ll take care of your visa, work permit, and provide a relocation package to help you settle in smoothly.\n- Flexibility that fits. We support a hybrid workstyle, giving you the freedom to find the right rhythm between home and office life.\n- Work with the right tools. We’ll set you up with a MacBook and a large external monitor so you can work comfortably and efficiently.\n- A workspace that works for you with our modern office in the heart of Ho Chi Minh City and Da Nang.\n- Stay fueled. Our kitchen is always stocked with drinks and snacks.\n- Take the time you need. Enjoy 26 days of paid leave a year (including public holidays), plus a sabbatical month every 3 years.\n- Celebrate your journey. From anniversary gifts to yearly company outings and spontaneous team activities, we make time for fun and appreciation.\n- ...and more perks to make work feel better.\n\nIf you are a passionate web professional looking to make a significant impact in a growing software development company, we would love to hear from you.\nJoin us in shaping the future with elevating web innovation!\n\nWe keep our recruitment process practical and straightforward.\n\nTo learn more about how we work, check our handbook named Compass, Github organization, and Medium account.\n\nWant to see what we have built? Check our Dribbble and Behance accounts.\n\nWant to keep in touch with us? Follow us on Facebook, Instagram, and LinkedIn.\n\nNimble is an equal opportunity employer.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1487, 879, 2, 'Java Developer', 'Headquartered in Singapore, Ant International powers the future of global commerce with digital innovation, enabling everyone and every business to thrive. In close collaboration with partners, we support merchants of all sizes worldwide to realize their growth aspirations through a comprehensive range of tech-driven digital payment and financial services solutions.\n\nWe are Ant International development team based on Vietnam, working on design, develop and maintain global Acquiring and E-Wallet products which offers 250+ payment methods in 150+ global markets. We have international offices in 20+ different countries.\n\nWe are opening Software engineers job position, with this job, you have the opportunity to work for one of the biggest-valued Fintech in the world, co-working with other most famous international financial institution systems & banks to deliver the smoothly payment experience to customers;\n\nJob Description\n- Design solutions involving integration with multiple systems and services\n- Develop high volume, high performance, low latency and reliable mission critical applications\n- Write maintainable, robust, and testable code\n- Perform code and test case review\n- Implement processes, solutions or tools to improve software delivery and quality\n- Able to adopt latest software development trends and industry best practices\n\nRequirements\n- Bachelor degree in computer science or relevant fields\n- Software development experience in the finance, payment or banking industry is preferred\n- Excellent communication, presentation and leadership skills\n- Excellent knowledge in Java and one other programming language\n- Excellent knowledge of Relational Databases, SQL and ORM technologies\n- Strong foundation in frameworks such as Spring, jUnit, etc. Hands on experience in designing and developing applications using Spring & web services technologies.\n- Good communication in Vietnamese and English are mandatory as the role requires working with Vietnamese and international teams.\n- Able to work in a fast paced and result driven environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1488, 880, 2, 'Freelance Software Developer (Java) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields. \n- You have at least 3 years of professional experience with Java\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you? \n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1489, 808, 2, 'JUNIOR SOFTWARE DEVELOPER (BI)', 'Job Description\n\nParticipate in company projects, understand customers\' business analysis scenarios, and organize them into clear analytical logic.\nUsing data analysis tools like Power BI to create visual reports, proficiently using various Power BI components such as data modeling and visualization, and master DAX functions.\nCollaborate with the internal team to ensure the accuracy of report data after project launch.\nConduct knowledge transfer for the project, sharing and training.\n\nRequirements\n\nCollege or university graduate.\nAble to work full-time.\nProficient in English (listening, speaking, reading, and writing).\nStrong logical thinking skills, enabling quick understanding of customer’s requirements and technical solutions.\nEffective communication and teamwork abilities.\nA strong sense of responsibility and resilience under pressure.\nProficient in using Power BI tools and DAX functions, SQL Server database.\nHaving the ability to handle multiple tasks and projects, and the ability to reprioritize when necessary.\nExperience with Power BI, familiar with the workflow of BI projects, and able to independently complete report development work, SQL Analysis Service, AWS, Amazon Redshift, understanding of data ETL processes is preferred.\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ダナン直轄市 ダナン', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1490, 316, 2, 'Java Developer (all genders)', 'HRS is transforming the future of corporate travel through innovative technology. In a $600 billion global lodging and meetings market, inefficiencies are rampant—from frustrating traveler experiences caused by outdated check-in and payment systems to millions lost annually due to missing or non-compliant invoices that block VAT reclaim. With travel increasingly complex and fragmented, the opportunity for innovation is enormous—and HRS is leading the charge.\nHRS offers an unparalleled end-to-end solution for managing corporate lodging, group travel, long stay, and meetings—all within a single, unified platform. With HRS Connect, companies gain access to a sleek, consumer-grade booking interface that consolidates fragmented travel spend and delivers full visibility across all travel categories. This is paired with HRS’s proprietary AI Copilot, which enables travel and procurement leaders to steer their programs strategically with real-time data, actionable insights, and one-click implementation of optimizations.\nTogether, these solutions empower organizations to drive measurable cost savings, boost policy compliance, and radically improve the traveler experience. The HRS platform enables customers to achieve up to 3x return on investment, achieve 100% invoice compliance, and increase corporate program adoption by over 20%—particularly in unmanaged spend areas like meetings and groups.\nWith over two decades of proprietary data, market-leading AI, and deep integration across the travel and expense ecosystem, HRS powers travel programs for 35% of the Fortune 500. From seamless payment to VAT-compliant e-invoicing and real-time reconciliation with SAP Concur and other ERP platforms, HRS offers unmatched transparency, governance, and performance—turning travel into a data-driven advantage with a sharp focus on customer excellence, compliance, and automation.\nBusiness Unit\nEnterprise Solutions is a business unit in HRS which integrates multiple solutions through the interchange of information from various business processes and related databases. Working in Enterprise Solutions means working on our core systems which enable our business processes on a daily basis.\nResponsibilities\n• Participate in the development and implementation of software solutions using Java.\n• Collaborate closely with the Product Manager to deliver optimal results.\n• Analyze and optimize system performance by eliminating bottlenecks.\n• Stay up to date with the latest technological trends and apply them appropriately within the project.\n• Create and maintain technical documentation when required.\n• Adhere to Scrum development methodologies.\n• Report directly to the Technical Leader.\nRequirements\n• Genuine passion for software development.\n• Eagerness and ability to quickly learn new tools, techniques, and technologies.\n• Minimum of 3 year of experience (or equivalent) in Java Enterprise development and SQL databases.\n• Strong understanding and practical experience with Object-Oriented Programming (OOP) and SOLID principles.\n• Proficient in building and consuming RESTful or SOAP web services.\n• Familiarity with Agile/Scrum methodologies.\n• Experience with C# is a big plus.\nPerspective\nAccess to a global network of a globally united and mutually responsible “Tribe of Intrapreneurs” that is passionately dedicated to renew the travel industry and while doing so reinvent the ways how businesses stay, work and pay.\nOur entrepreneurial driven environment of full ownership and execution focus offers you the playground to contribute to a greater mission, while growing personally and professionally throughout this unique journey. You will continuously learn from a radical culture of retrospectives and continuous improvement and actively contribute to making business life better, smarter and more sustainable.\nBenefits\n• Full salary and benefits as an official employee on probation.\n• Hybrid working model.\n• Open and flat environment, highly appreciate your idea and constantly supporting your skill development.\n• Innovative and international learning and development program, we dedicate to supporting employees’ growth and development of skills.\n• Challenging products with onsite opportunities in Europe (Germany, Australia, Poland, etc.).\n• 13th-month salary & short-term incentives: we offer incentives as defined by the company’s success in the previous year.\n• 15+ annual leaves per year.\n• Full healthcare compliance.\n• Premium healthcare for employees.\n• Gifts for every special occasion.\n• Supportive working conditions: Laptop, MS Surface Hub.\n• Free and unlimited snacks, tea, coffee, and by-choice request.\n• Premium company trip & business traveling programs and other exciting activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1491, 881, 2, 'Java Developer (Middle/Senior)', '1, Mô tả công việc \nTham gia xây dựng nền tảng full-stack phục vụ giao diện quản trị nội bộ (WebAdminPortal)\nPhát triển các thành phần backend sử dụng Java, Spring Boot, triển khai logic nghiệp vụ và tích hợp với frontend qua các API RESTful.\nPhối hợp với frontend (ReactJS) để thiết kế giao diện quản trị mượt mà, dễ sử dụng.\nPhân tích và giải quyết các bài toán nghiệp vụ phức tạp, từ frontend đến backend.\nTham gia review code, tối ưu hiệu năng hệ thống, đảm bảo chất lượng sản phẩm.\nĐóng góp ý tưởng, cải tiến về kiến trúc, luồng dữ liệu và trải nghiệm người dùng trong hệ thống quản trị.\nLàm việc trong môi trường Agile/Scrum, phối hợp với DevOps, QA, BA trong toàn bộ vòng đời phát triển phần mềm.\n\n2, Yêu cầu ứng viên\nTối thiểu 4 năm kinh nghiệm phát triển phần mềm, trong đó ít nhất:\nThành thạo Java Core, OOP, Spring Boot (MVC, Security, JPA), API design.\nCó kinh nghiệm làm việc với ReactJS (Hooks, Redux, React Router, Axios...).\nNắm vững HTML, CSS, JavaScript (ES6+), TypeScript là một lợi thế.\nHiểu về mô hình RESTful, cơ chế xác thực (JWT, OAuth2), CORS, session/cookie.\nKỹ năng tốt về Git, CI/CD, làm việc trong môi trường Agile/Scrum.\nTư duy logic tốt, có kinh nghiệm phân tích và giải quyết bài toán nghiệp vụ từ frontend đến backend.\n\nƯu tiên:\nCó kinh nghiệm về cấu trúc monorepo hoặc tách biệt FE/BE rõ ràng.\nHiểu và làm việc tốt với Docker, Kafka, Redis, hoặc PostgreSQL.\nTừng tham gia các hệ thống lớn: e-commerce, fintech, SaaS... là lợi thế.\nCó khả năng viết test unit (Jest, JUnit) và hiểu về TDD là điểm cộng.\n\n3, Quyền lợi \nChế độ lương, thưởng, thu nhập:\nThu nhập: hấp dẫn theo thỏa thuận theo kinh nghiệm và năng lực.\nPhúc lợi: hỗ trợ ăn trưa, điện thoại, nghỉ mát, thưởng ngày lễ và các ngày chỉ có ở Viettel như Ngày Sáng Tạo - 1/6, 22/12, quà Tết Dương, Tết Âm tri ân Gia đình, người sinh thành.\n\nMôi trường làm việc\nĐược làm việc trong Tập đoàn toàn cầu, tiên phong thực hiện sứ mệnh kiến tạo xã hội số.\nMôi trường mở, trẻ trung, năng động, trân trọng, yêu thương, tương hỗ & lắng nghe mỗi người từ những ý tưởng nhỏ nhất.\nKhông gian làm việc xanh, mở, hiện đại.\n\nCơ hội phát triển bản thân\nCó cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\nĐược thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước để trưởng thành.\nĐược trao quyền sáng tạo với đam mê của tuổi trẻ.\nCơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\nCơ hội được đào tạo, trau dồi kĩ năng, chuyên môn để phát triển toàn diện.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1492, 882, 2, 'Java Developer', 'Up to 40M\n\nCấp bậc\n\nSenior\n\nHình thức\n\nFull Time\n\nĐịa điểm làm việc\n\nHà Nội\n\nTECHVIFY Corporation is an End to End AI-Powered Digital Transformation Partner.\n\nAt TECHVIFY, we don’t just build software.\n\nWe engineer breakthroughs.\n\nWe innovate with AI, craft with code, and scale with cloud.\n\nWe partner with startups, enterprises, and even competitors on a shared mission:\n\nTo turn bold ideas into real-world impact.\n\nIf you’re looking to lead digital transformation through intelligent software, we’re ready to build with you.\n\nLet’s create the future – together.\n\nResponsibilities\n\nCollaborate with architects and product owners to define software requirements and specifications.\n\nWrite clean, maintainable, and efficient Java code, following best practices and coding standards.\n\nPerform code reviews to ensure code quality, consistency, and adherence to design patterns.\n\nTroubleshoot and debug complex issues in existing applications and provide effective solutions.\n\nOptimize application performance, scalability, and responsiveness.\n\nCollaborate with cross-functional teams to deliver high-quality software products, including front-end developers, testers, and product managers.\n\nContribute to the software development lifecycle, including requirements analysis, design, implementation, testing, and deployment.\n\nParticipate in Agile development processes, including sprint planning, stand-up meetings, and retrospectives.\n\nRequirements\n\nBachelor’s degree in Computer Science, Computer Engineering, or a related field.\n\nProven experience as a Java developer, with a minimum of 3 years experienced.\n\nStrong proficiency in Java, including experience with Java 8 or later.\n\nProficiency in Java frameworks such as Spring and Hibernate.\n\nExperience with RESTful web services and API development.\n\nSolid understanding of object-oriented programming (OOP) principles and design patterns.\n\nFamiliarity with front-end technologies and integration with Java applications.\n\nKnowledge of database systems, SQL, and NoSQL databases.\n\nProficiency in version control systems, such as Git.\n\nExcellent problem-solving and debugging skills.\n\nStrong communication and interpersonal skills.\n\nFluent in English, both written and spoken.\n\nAgile development experience is a plus.\n\nCertifications in Java or related technologies are a plus.\n\nBenefits\n\nSalary: Upto 40M\n\nJoin a global team and work directly with many talents around the world.\n\nOpportunities for onsite work in Japan, Singapore, Australia, and many other countries.\n\nWork and grow in a dynamic, creative, and professional environment.\n\nHealthcare: Premium Health Insurance TECHVIFY Care\n\n13 months’ salary per year.\n\nAnnual salary evaluation.\n\nSponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.\n\nHow to apply\n\nIf you are a driven and talented Java Developer looking for an opportunity to be part of something extraordinary, please submit your resume and cover letter for consideration.\n\nJoin our team and let’s create amazing things together! Send your updated CV to this email address:\n\nEmail: careers@techvify.com.vn\n\nAbout us: https://techvify-software.com/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1493, 870, 2, 'IT Developer (System Development & Operations)', 'Working location: Thien Nhan Hospital Da Nang - 276-278-280 Dong Da Street, Da Nang City.\nType: Full-time\nReports to: (Not specified – can be updated if needed)\n\nKey Responsibilities:\n- Manage and optimize websites, booking systems, chatbots, and other digital tools.\n- Develop new features (web apps, internal portals, etc.).\n- Support server, domain, email, hosting, and data security operations.\n- Monitor, troubleshoot, and maintain existing IT systems.\n- Collaborate with software vendors for integration requests.\n\nRequirements:\n- Bachelor’s degree in IT, with at least 2 years of relevant experience.\n- Proficient in frontend (HTML/CSS/JS) and backend (PHP, Node.js, or Python).\n- Experience with CMS platforms like WordPress, Laravel, or similar frameworks.\n- Knowledge of system security, hosting, and server management is a plus.\n- Logical thinking, attention to detail, and a strong sense of responsibility.\n\nBenefits:\n- Attractive compensation based on capabilities.\n- Work in a modern, technology-focused healthcare environment.\n- Opportunities to enhance expertise through large-scale healthcare system projects.\n\nApply via email: hr.thiennhanhospital@gmail.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thien Nhan Hospital Da Nang - 276-278-280 Dong Da Street, Da Nang City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1494, 679, 2, 'HN – Nhân Viên Triển Khai Phần Mềm – Khu Vực Miền Bắc', 'Nhân Viên Triển Khai Phần Mềm – Khu Vực Miền Bắc\n\nHiện tại, Vexere là hệ thống vé xe lớn nhất Việt Nam, với hơn 1.000 hãng xe hợp tác bán vé với Vexere, phủ rộng hơn 3.000 tuyến đường trong và ngoài nước giúp người dùng có thể tìm thông tin chuyến xe, hãng xe, và mua vé trực tuyến dễ dàng. Đồng thời, Vexere còn cung cấp những đánh giá của các hành khách đã đi những hãng xe này. Hành khách có thể dễ dàng lựa chọn trước chỗ ngồi yêu thích, thanh toán vé trực tuyến, tiền mặt tại các cửa hàng tiện lợi trên cả nước.\n\nCác thành viên của Vexere tin rằng một tổ chức được sinh ra là để giải quyết các vấn đề nhức nhói trong xã hội. Văn hóa công ty chú trọng tinh thần cộng đồng, hỗ trợ lẫn nhau. Tất cả thành viên Vexere luôn được tạo cơ hội để được thể hiện bản thân, đóng góp sáng kiến về sản phẩm và chiến lược, và hướng đến trở thành những nhà lãnh đạo trong tương lai.\n\nHãy cùng tham gia vào team Triển Khai Phần Mềm – Software Implementation (SI) tại Vexere để cùng hỗ trợ thêm thật nhiều đối tác nhà xe trong quá trình quản lý vận hành và thúc đẩy gia tăng doanh số, xứng tầm là đơn vị tiên phong trong quá trình cách mạng số hóa ngành vận tải xe khách tại Việt Nam.\n\nMô Tả Công Việc\n\n- Học và nghiên cứu các giải pháp Phần mềm quản lý nhà xe.\n- Triển khai phần mềm cho các đối tác nhà xe: hướng dẫn, cài đặt, cấu hình hệ thống theo quy trình.\n- Đào tạo nhân viên nhà xe sử dụng phần mềm hiệu quả và đúng quy trình.\n- Hỗ trợ đối tác xử lý các vướng mắc kỹ thuật, kết hợp với các team khác để đảm bảo quá trình vận hành trơn tru.\n- Ghi nhận các yêu cầu, phản hồi từ khách hàng để đề xuất cải tiến sản phẩm cùng team Product.\n- Phối hợp với các phòng ban nội bộ để đảm bảo tiến độ và chất lượng triển khai.\n- Báo cáo tiến độ công việc định kỳ cho cấp trên.\n\nYêu Cầu Công Việc\n\n- Tốt nghiệp Trung cấp/Cao đẳng/Đại học các ngành: Công nghệ thông tin, Quản trị kinh doanh, Hệ thống thông tin, hoặc ngành liên quan.\n- KHÔNG yêu cầu kinh nghiệm – chỉ cần có tư duy học hỏi, nhiệt tình và đam mê công nghệ.\n- Giao tiếp tốt, có khả năng hướng dẫn người khác.\n- Kỹ năng tổ chức công việc, làm việc độc lập hoặc theo nhóm.\n- Thái độ tích cực, sẵn sàng đi công tác (có hỗ trợ công tác phí 100%).\n\nChế Độ – Phúc Lợi\n\nBên cạnh việc tìm kiếm và định hướng nhân sự công ty đến các giá trị “right people”: tư duy logic, suy nghĩ tích cực, minh bạch và nhất quán, tò mò với những điều mới, giao tiếp dựa trên lắng nghe, khiêm tốn và trách nhiệm. Vexere còn không ngừng cải thiện, nâng cao chất lượng đời sống cho toàn thể nhân sự công ty, dưới đây là các giá trị phúc lợi mà bạn sẽ nhận được khi tham gia tại Vexere:\n\n- Lương Thưởng\n\n- Mức lương căn bản theo năng lực\n- Bonus tháng + Trợ cấp điện thoại + Công tác phí (hỗ trợ 100%)\n- Thưởng hiệu suất theo quý (tối đa 7 tháng lương/năm)\n- Review lương 2 lần/năm; Thưởng Tết, thưởng thâm niên\n- Lộ trình thăng tiến rõ ràng, phù hợp với năng lực, có cơ hội định hướng phát triển lên các vị trí chủ chốt\n\nChế Độ Khác\n\n- Tham gia BHYT, BHXH, BHTN theo quy định, ký hợp đồng chính thức sau khi thử việc.\n- 12 ngày phép/ năm, 3 năm tăng 1 ngày phép, ngày phép được cộng dồn qua 2 năm tiếp theo hoặc quy ra lương\n- Khám sức khoẻ tổng quát hàng năm\n- Chính sách vay cá nhân, tạm ứng lương\n- Chính sách giảm giá vé xe cho nhân viên\n- Chính sách ốm đau, thai sản, hiếu hỉ…\n- Chính sách thưởng khi giới thiệu nhân viên vào làm việc\n- Chính sách khoá học đào tạo phát triển bản thân: 18 triệu/ năm\n\nThời Gian Làm Việc\n\n- Vexere đang áp dụng hình thức làm việc Hybrid (có thể linh hoạt làm tại nhà hoặc lên văn phòng)\n- Thời gian làm việc: từ 8h30-18h00 từ thứ Hai – thứ Sáu + sáng thứ Bảy\n\nĐược Tham Gia Các Hoạt Động\n\n- CLB thể dục thể thao của công ty\n- Chính sách cho các hoạt động teamwork mỗi tháng\n- Tham quan nghỉ mát, team building, year end party\n- Được làm việc tại văn phòng trẻ trung, sôi nổi: môi trường làm việc nhân văn, lành mạnh, cởi mở cùng với những người trẻ năng động\n\nHiểu thêm về chúng tôi tại: Review về Vexere.\n\nCách Thức Ứng Tuyển\n\n- Để biết thêm thông tin về công việc, vui lòng liên hệ Bộ phận Nhân sự:\n- Gửi CV về Email: careers@vexere.com, tiêu đề: Vị trí ứng tuyển – Họ tên ứng viên\n- Zalo: 039 555 54 86 (A. Nhân)\n- Văn phòng làm việc tại miền Bắc: Tầng 3 – Tòa nhà 101 Láng Hạ, Đống Đa, Hà Nội\n- Theo dõi Vexere Careers tại để cập nhật các vị trí tuyển dụng và rất nhiều những thông tin thú vị khác.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'منطقة مدينة هو تشي منه الحضرية', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1495, 786, 2, '【ドワンゴ】エンジニア オープンポジション', '【募集概要】\n\nドワンゴが運営するサービス・事業に関するエンジニア採用を強化しており、課題解決、事業推進、サービスの成長に貢献いただける方を募集しております。\n\nドワンゴに関心をお持ちいただいているものの、応募先職種に迷っている方はぜひこちらからご応募ください。\n\n【業務内容の参考例】\n\n■スマートフォンアプリ開発エンジニア\n\nAndroid/iOS向けネイティブアプリケーションの企画開発を行なっていただきます。\n・日本最大級の動画サイト「ニコニコ動画」を中心とした「ニコニコ」サービスの、スマートフォン向けクライアントアプリケーションの開発\n・日本発の本格的なオンライン大学「ZEN大学」や、角川ドワンゴ学園が運営する日本最大の生徒数である高校「N高等学校・S高等学校・R高等学校」と連携した、オールインワン学習アプリの開発 など\n\n■Webアプリケーションエンジニア\n\nWebアプリケーションの開発を行っていただきます。\n・日本最大級の動画サイト「ニコニコ動画」を中心とした「ニコニコ」サービスに関連するWebアプリケーションの開発\n・角川ドワンゴ学園が運営する日本最大の生徒数である高校「N高等学校・S高等学校・R高等学校」の運営業務や生徒指導を行うためのシステム開発・運用 など\n\n■ITアーキテクト\n\n最新型のファンクラブ運営サービス「Sheeta」と、生放送・動画・ブログなどのチャンネル会員限定コンテンツを配信できる「ニコニコチャンネルプラス」にITアーキテクトとして参加していただきます。\n・ビジネス側（営業・企画）からシステム要求を引き出し、実際に設計・開発業務を行う開発会社との間で橋渡し\n\n■利用されている言語\n\nバックエンド : Go, Scala, PHP, Ruby, TypeScript, Java 等\nフロントエンド : TypeScript, JavaScript等\n\n＜エンジニア関連リンク＞\ndwango on GitHub：https://dwango.github.io/\nDwango Media Village：https://dmv.nico/ja/\nドワンゴ教育サービス開発者ブログ：https://blog.nnn.dev/\n\n必須要件\n\n■スマートフォンアプリ開発エンジニア\n・iOSもしくはAndroid向けネイティブアプリ開発の実務経験のある方\n\n■Webアプリケーションエンジニア\n・何らかのプログラミング言語によるWebアプリケーション開発の実務経験のある方\n\n※学歴不問\n\n＜応募書類補足＞\n今までの職務経歴と開発実績のわかる書類、また下記のような技術的なアピールができるものをお持ちでしたら、あわせてお送りください。\n・githubのアカウント(URL)\n・QiitaやZennなど技術系記事サービスのアカウント(URL)\n\n職種 / 募集ポジション 【ドワンゴ】エンジニア オープンポジション\n雇用形態 正社員\n給与 応相談\n前職を考慮し、当社基準により決定いたします。\n昇給：年2回（6月・12月）本人の能力・役割に基づいて評価\n賞与：年2回（6月・12月）本人の成果に基づいて支給\n※ご入社時期、個人の評価、会社の業績により夏季賞与・冬季賞与額が変動いたします。\n※退職金は前払い退職金制度\n\n勤務地\n104-0061 東京都中央区銀座四丁目12-15 歌舞伎座タワー 地図で確認\n\n勤務形態 裁量労働制（1日8時間のみなし労働)\n休日休暇 完全週休2日制（土・日）、祝日（※超会議に伴う営業日変更あり）\n・年次有給休暇（入社日に5日、入社日の3ヶ月後に15日付与）\n・記念日休暇\n・年末年始休暇（12/29～1/3）\n・リフレッシュ休暇（年度ごとに2日間付与）\n・特別（慶弔）休暇\n\n手当・制度\n・テレワーク手当 ※テレワーク対象となる社員（条件有り）に対し、月額2万円を支給\n・通勤交通費手当（上限月額50,000円） ※テレワーク対象者は原則支給しない ただし、業務指示における出社時の交通費は会社が認める範囲で別途支給\n・育児手当（上限月額50,000円） ※扶養の子の保育料の半額を支給\n・役職手当（役職に応じて支給）\n・資格取得手当制度\n・サブスク手当（対象のサブスクを契約している場合、月額2千円を支給）\n\n福利厚生\n・各種社会保険完備（関東ITソフトウェア健康保険組合）\n・確定拠出年金制度\n・財形貯蓄制度\n・社員持株会制度\n・社内カウンセリング制度\n・同好会\n・健康保険組合各種サービス\n・社員限定美容室\n\n選考プロセス\n書類選考後、面接を2～3回を想定しています。\n※1次面接までに当社が指定する適性検査を受検いただきます。\n※全てオンライン面接を想定しています。\n※選考の過程でコードテストを実施する可能性があります。\n\n会社情報\n会社名 株式会社ドワンゴ\n代表者 代表取締役社長 夏野 剛\n事業内容 ネットワークエンタテインメントコンテンツ及びシステムの企画、開発、運用、サポート、コンサルティング\n設立 1997年8月6日\n資本金 1億円（2019年3月29日現在）\n所在地 〒104-0061 東京都中央区銀座4-12-15 歌舞伎座タワー\n親会社 株式会社KADOKAWA\n子会社 株式会社バンタン 株式会社スパイク・チュンソフト Spike Chunsoft, Inc. 株式会社バーチャルキャスト 株式会社カスタムキャスト 株式会社GeeXPlus 株式会社PUBLUS', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 12, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1496, 883, 2, 'Back End Developer', 'Company Description\n\nWe suggest you enter details here.\n\nRole Description\n\nThis is a full-time on-site role for a Back End Developer located in Can Tho. The Back End Developer will be responsible for developing and maintaining server-side logic, ensuring high performance and responsiveness to requests from the front-end. Daily tasks include collaborating with front-end developers, integrating user-facing elements with server-side logic, optimizing applications for speed and scalability, and troubleshooting and debugging applications.\n\nQualifications\n\n• Proficiency in Back-End Web Development and Software Development\n• Strong understanding of Object-Oriented Programming (OOP) principles\n• Basic knowledge in Front-End Development\n• Programming skills in languages such as Java, Python, or Ruby\n• Excellent problem-solving and analytical skills\n• Ability to work collaboratively in a team environment\n• Bachelor\'s degree in Computer Science, Engineering, or a related field\n• Experience in working with databases and version control systems is a plus', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Can Tho, Can Tho, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1497, 723, 2, 'Backend Developer', 'MÔ TẢ CÔNG VIỆC \nTham gia nghiên cứu, phát triển các giải pháp an ninh mạng :\nGiám sát và phát hiện tấn công.\nQuản lý ATTT cho tổ chức/ doanh nghiệp.\nPhân tích yêu cầu, thiết kế hệ thống.\nTối ưu hiệu năng hệ thống.\n\nYÊU CẦU \nLập trình tốt, đặc biệt ngôn ngữ Python/ Golang\nKinh nghiệm 1-1,5 năm trở lên\nTư duy tốt, nắm bắt công nghệ nhanh.\nƯu tiên ứng viên (không yêu cầu tất cả):\nCó kiến thức Design pattern và thiết kế hệ thống.\nCó kinh nghiệm tối ưu hệ thống/tham gia dự án lớn, số lượng người dùng đáng kể.\nCó kinh nghiệm làm việc với hệ thống thu thập và phân tích log tập trung.\nBiết sử dụng công nghệ NoSQL, Redis, Kafka.\nƯu tiên ứng viên:\nCó kinh nghiệm làm việc trong các dự án sử dụng CI/CD\nCó kiến thức về Iaas/Paas/Saas và mô hình microservice, multi-tenancy architecture\nAm hiểu, có kinh nghiệm thực tế với các dự án chạy theo mô hình Agile/Scrum\nCó kinh nghiệm sử dụng các công cụ: Jenkins, kubernetes, Docker.\n\nQUYỀN LỢI \nMức thu nhập cạnh tranh: 600$ – 1000$\n“NMS care” bảo hiểm dành riêng cho nhân viên NMS.\nNghỉ mát: Theo chính sách của công ty (vào tháng 5-6 hàng năm).\nCó cơ hội được xem xét nâng lương 2 lần 01 năm, tùy vào kết quả công việc.\nMôi trường làm việc hiện đại, thân thiện.\nChính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1498, 884, 2, 'Software Engineer', 'VinAI is one of the world’s top 20 Artificial Intelligence research-based companies developing world- class products and services. Our head office is located in Hanoi, Vietnam with additional technology hubs across the US and Australia. We have more than 200 research scientists and AI engineers dedicated to the mission of transforming our state-of-the-art AI research into technology solutions for Vietnam and the global market. Our key investor is Vingroup, one of the largest conglomerates in Asia.\n\nSoftware Engineer\n\nThe ideal candidate will have proven ability to implement software application, strong programming skills, understand software development and software project management. You will join as a member of Software team and work on the project. We will develop an application, which lets drivers feel more comfortable and safe.\n\nWhat you’ll do\n- Work on real projects, meaningful and interesting work.\n- Have a great learning experience with a humble, inspiring team.\n\nWhat you’ll need.\n- Bachelor’s Degree in Automotive, Electrical, Communication or Computer Engineering\n- 2+ years professional experience with Automotive/ Autonomous Driving System or Software Development\n- 2+ years professional experience with SW development of mathematical concepts as well as algorithms\n- 5+ years professional work experience with System Linux and/or Linux programming using C++\n- 5+ years professional work experience with embedded software development for safety critical systems (e.g., automotive, aerospace) using C++\n\nNice to Have’s\n- Model based development skills using SysML and/or UML (ideally using Enterprise Architect)\n- Experience in the development of embedded systems in POSIX-based OS, QNX or Classical AUTOSAR\n- Knowledge of development processes (e.g ASPICE, version management, change management, reviews)\n- Awareness of AD industry trends, technologies, competitive products, best practices (HW/SW)\n- Experience in SOTIF analysis of Autonomous driving projects in System and/or SW level.\n- Knowledge and/or experience in developing SW applications using Adaptive/Classic AUTOSAR\n- Experience with Agile software engineering methodology\n\nWhy you’ll love work here.\n- The exciting environment of a fast-paced AI technology startup.\n- Opportunity to apply your knowledge and skills to make a real impact on the world.\n- Compensation is competitive and will consider the applicant’s current experience level.\n- Opportunity to continuously grow your knowledge and your leadership skills.\n- Opportunity to contribute, interact, share, and learn from exceptionally talented colleagues.\n\nContact\nInterested applicants are invited to send your application to v.loantt27@vinai.io or v.hoangnm31@vinai.io', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1499, 740, 2, 'Frontend Developer', 'Job Description\n\n- Develop new user-facing features\n- Build reusable code and libraries for future use\n- Ensure the technical feasibility of UI/UX designs\n- Optimize application for maximum speed and scalability\n- Assure that all user input is validated before submitting to back-end\n- Collaborate with other team members and stakeholders \n\nRequirements\n\n- At least 4+ year experience working with library ReactJS and framework VueJS.\n- 4+ years of experience in ReactJS, NextJS, Typescript\n- Familiar in using NextJS, TailwindCSS\n- Critical thinking\n- Willing to change or adapt new things\n- Knowledge about Agile or Waterfall methodology in software development\n- Have knowledge about the development checklist, requirement checklist\n- Nice to have: React Query, Atomic Design\n- Fluent in English communication. Bonus points: – Experienced with Design pattern, SOLID principle – Experienced with SCRUM, GIT, SVN, REDMINE, JIRA \n\nJob Benefits\n\n- Salary: Negotiable\n- Performance review: 2 times/year\n- 14th-month salary bonus\n- KPI bonus based on project and performance\n- Extra package: 16 Mil /employee/year (Bonus at Tet, New Year, your birthday, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, …)\n- Opportunity to work in a professional, modern, and dynamic environment, take part in international projects\n- Opportunity to get on-job training and promotion\n- An excellent corporate culture with in/out of office activities that help to develop staffs ability and creativity\n- CMC health care and social insurance\n- Onsite opportunities: short-term and long-term assignments in US, EU,… (members of GEU/US)\n\n2+ years of experience\n\n- Please send your application via email: recruitment@cmcglobal.vn\n\nYears of Experience Required\n\nRequired Education Level\n\nBachelor’s Degree\n\nJob Level\n\nMiddle/Senior\n\nWork Form\n\nFull-time\n\nEmail: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1500, 841, 2, 'Chuyên viên phát triển chương trình', 'Mô tả công việc\n\n- Trao đổi và thống nhất định hướng nội dung khóa học với các giáo viên\n- Đánh giá giáo viên và góp ý cho GV về chuyên môn: video và học liệu, bao gồm cả đánh giá giảng thử\n- Nghiên cứu nội dung sản phẩm đối thủ (các vấn đề về phương pháp giảng dạy và cách tiếp cận)\n- Tham gia xây dựng chương trình các môn học (bám sát chương trình giáo dục phổ thông mới) phục vụ cho việc xây dựng các sản phẩm của HOCMAI\n\nĐại học', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1501, 197, 2, 'Backend Engineer (Go, Java) - DOP', 'Join Trusting Social as a Backend Engineer on our Credit Insight project, the cornerstone of our company, delivering automated credit scoring services to over 1 billion people globally by handling high volumes of applications efficiently through 100% automated registration, approval, and decision-making processes.\n\nResponsibilities\n\n- Develop Scalable Web Service APIs: Build highly scalable, highly available, and fault-tolerant web service APIs designed to handle millions of transactions per day.\n- Agile & DevOps Practices: Follow Agile methodologies and DevOps practices such as CI/CD to deliver quality code rapidly to market.\n- Seamless Integrations: Create software services that integrate effortlessly and securely with banks, third-party platforms, and vendors.\n- Innovative Problem Solving: Think outside the box, innovate, experiment, and continuously improve by learning quickly from failures to provide simple yet effective solutions to complex problems.\n\nRequirements\n\nEducational Background:\n\n- Bachelor’s degree or higher in Computer Science, Engineering, or a related field.\n\nExperience\n\n- 5+ years of software development experience.\n- Solid expertise in Golang (or the confidence to learn it quickly when coming from other similar programming languages).\n\nAPI Design & Development\n\n- Proficient in designing and developing RESTful APIs and gRPC interfaces.\n- Experience building backend services optimized for high performance, scalability, and reliability.\n\nDatabase Expertise\n\n- Strong database and schema design skills for performance and scalability across both relational and NoSQL databases (e.g., MySQL, PostgreSQL, MongoDB, Redis, Elasticsearch, RocksDB).\n\nSystem Design\n\n- Deep understanding of complex system design, design patterns, data structures, algorithms, microservices, and event-driven architecture.\n- Experience with system tuning for high performance and reliability.\n\nDevOps & Tooling\n\n- Hands-on experience with CI/CD tools such as GitHub workflows and Jenkins.\n- Familiarity with Docker containers and Kubernetes.\n- Knowledge of automated testing practices, caching techniques, and version control systems like Git.\n\nNice To Have\n\n- Experience with cloud platforms (AWS, GCP, or Azure).\n- Exposure to or interest in the AI domain with a willingness to leverage AI to enhance team productivity.\n- Experience with microservice architecture is a plus.\n\nWhat We Offer\n\n- Competitive compensation package, including 13th-month salary and performance bonuses\n- Comprehensive health care coverage for you and your dependents\n- Generous leave policies, including annual leave, sick leave, and flexible work hours\n- Convenient central district 1 office location, next to a future metro station\n- Onsite lunch with multiple options, including vegetarian\n- Grab for work allowance and fully equipped workstations\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets\n\nAbout Us\n\nWe are an AI Fintech company specializing in assessing credit profiles of consumers in emerging markets combining pioneering AI with large alternative data sources. In 2020 we reached our ambitious milestone of credit profiling 1 billion consumers spanning 4 countries - Vietnam, Indonesia, India & the Philippines - and building a platform for the wider industry and the financial services industry, in particular, to provide the "un & under" served access to credit. At the core of this initiative has been our strict and unwavering adherence to the norms of consumer data privacy and consumer data rights.\n\nBut we\'re not satisfied as we embark on the next leg of our journey to deliver 100 million credit lines to consumers in the markets where we operate. Although this goal is ambitious, we truly believe that by harnessing the power of AI & Big Data we can deliver financial access at an unprecedented scale.\n\nAs a firm, we\'re audacious problem-solvers motivated by our impact on society. We deeply espouse the values of ownership - of our actions and initiatives, integrity in all we do, and agility in execution.\n\nWe place great importance on doing what is right, what is best, and what is innovative. If you are smart, driven, and want to make a difference in the world with the most advanced and fascinating technology, come join our team. We can satisfy your desire to explore new territory and give you the runway to really make an impact.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1502, 209, 2, 'BrSE', 'Job Brief/ Project Description/ Job Overview\nWe are looking for a Bridge Software Engineer to participate in the project that makes a Japanese company specializing in providing services related to cards and finance.\nResponsibilities/ Daily tasks you will take care:\n·      Bridge between the subsidiary in Vietnam and the parent company in Japan.\n·      Become a member of the company\'s web application development team.\n·      Responsible for product development and maintenance.\n·      Responsible for receiving requests from the parent company, analyzing and communicating requirements to developers in Vietnam.\n·      Support the Developer to develop the functions, check the functions which have worked properly with the requirements of customers or not.\n·      Contribute ideas and improve the quality of products\nRequirements/ Desired skills and experience\nBasic Qualification:\n·      Have Japanese communication N2 or above.\n·      Have 2 years of working experience in BA/BrSE position or equivalent position\n·      Skills: Teamwork, Analysis, Design, Communication and presentation by japanese.\n·      Proactivity, Self-study ability and Positive attitude at work.\n·      Proficient in UML, Design and Modeling tools.\n·      Experience with Java EE, Object Relational Mapping (ORM) Framework, Java Server Pages (JSP),\n·      Experience with Struts, Spring and / or Hibernate Frameworks, RESTful programming, Java Batch.\n·      Experience with JavaScript, TypeScript, HTML and CSS. process XML like XSD, XS..v.v.\n·      Experience with Service Oriented Architecture (SOA) .DB: Oracle, DB2, SQL Server, noSQL.\nNice to have:\n·      Experience with financial and card projects\n·      Have a solid foundation for object-oriented design / object-oriented programming (OOD / OOP)\nBenefits\n·      Be part of our hugely international environment; we are currently working for Japanese/Global projects, where you can have many opportunities to working overseas;\n·      Competitive salary package based on skills and experience.;\n·      We create great teams and take very good care of them;\n·      Great opportunity to grow with the company;\n·      Frequent staff activities and company parties;\n·      Awesome social events and parties for employees;\n·      “FPT care” health insurance provided by Petrolimex (PJICO) and is exclusive for FPT employees.\n·      Annual Summer Vacation: follows company’s policy and starts from May every year\n·      Salary review: 1 time per year\n·      International, dynamic, friendly working environment\n·      Annual leave, working conditions follow Vietnam labor laws.\n·      Other allowances: lunch allowance, working on-site allowance, etc.\nContact\n§ Contact Perso : Ms. Nguyen Thi My Dung (DungNTM2)\n§ Email                   : DungNTM2@fpt.com\nPhone: 090 6569 263', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1503, 432, 2, 'FULLSTACK .NET ENGINEER (AUSTRALIAN PROJECT)', 'Fullstack .NET Engineer (Australian Project)\n\n32025-06-30\n\nApply Now\n\nResponsibilities\n\n- Play in a dynamic, collaborative, transparent, non-hierarchical, and ego-free culture where your talent is valued over a role title.\n- Work in collaborative teams and build quality code.\n- Help the team champion software quality, engender technical vision, and ensure clients are satisfied.\n- Be problem solvers, think through hard problems and work with amazing people to make the solutions reality.\n- Practice agile software development and be a great team player.\n- Learn something new every day, and work on your great innovative idea with a team to apply to the project.\n\nRequirements\n\nMust have: \n\n- Minimum 3 years of experience in .NET development with expertise in developing large-scale enterprise applications and solutions.\n- Front-end: Typescript, JavaScript, web framework (Angular, React, Blazor).\n- Front-end: State management, web components, security, performance, accessibility.\n- Back-end: .NET, .NET Core, Web API, RESTFUL Design, Security, Authentication, Authorization\n- Back-end: SOLID, DRY, Separation of Concerns, Persistence Ignorance, Dependency Inversion.\n- ORM: EF Core, Dapper, ....\n- SQL: SQL Server, stored procedures, performance, profiling tools.\n- Testing: Unit testing, Integration Testing, understand different testing processes to ensure quality.\n- Deployment and Release: CI/CD, Azure DevOps, Terraform, Octopus.\n- Deployment cycles: TBD, feature branches, git flow, feature flags, etc.\n- Programming Principles: SOLID, DRY, Separation of Concerns, Persistence Ignorance, Dependency Inversion.\n- Proficient in Agile Software Development using the Scrum framework.\n- Have experience in Azure Cloud Platform.\n- Be self-sufficient and a good planner.\n\nNice To Have\n\n- Familiar with Domain Driven Design, Clean Architecture, SoA, and Micro Services.\n- Design system (Material 3, Primeng, Shadcn, MUI),\n- No-SQL: MongoDB, CosmosDB\n- Message broker system (Kafka, Azure Service Bus, RabbitMQ)\n- Experience in Workflow Development.\n- Hosting solutions like VM, web servers, containerization (Docker – Kubernetes)\n- Experience in Identity Server/IAM/Azure B2C/Okta and OIDC.\n- Understanding about Security practices, zero-trust policies.\n- Write clean and refactor code.\n- Possess a good mindset regarding technical solutions and technical best practices.\n\nSoft-skills:\n\n- Effective verbal English skills in video conferences and face-to-face communication.\n- Know how to manage tasks and perform context switching.\n- Have a resilience mindset, handle stress well.\n- Be a problem solver with great problem-solving skills.\n- Proactive and self-learning mentality.\n\nWhat We Offer\n\n- Attractive salary based on your performance. \n- Annual 13th month salary. \n- Dedication bonus will be paid once a year. \n- Premium healthcare insurance, Annual health checks up. \n- Onsite opportunity in Australia. \n- Hybrid working (1-day WFH per week).\n- Breakfast is available at office in early morning and snack in late afternoon.\n- Team building allowance.\n- Annual Company team building trip.\n- Clubs (Football, Badminton, Running, Biking, Chess, Music band).\n- Exclusive training programs for all staff in technical, soft skills and process.\n- English class.\n- Technical clubs.\n- Marriage allowance, having newborn baby allowance, bereavement allowance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1504, 702, 2, 'Data Scientist - AI Agent Development', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nWe are seeking a highly skilled and motivated Data Scientist to join our team, focusing on the development of domain AI agents for specific operational tasks handling; The ideal candidate will also have expertise in traditional Optical Character Recognition (OCR) and computer vision technologies. This role require some engineering experience to work closely with developers to integrate the solution to our existing systems.\n\nResponsibilities\n\nDesign, fine-tune, and deploy Large Language Models (LLMs) for AI agent applications.\nImplement Retrieval-Augmented Generation (RAG) pipelines to enhance the performance of AI agents in retrieving and generating contextually accurate responses.\nDevelop and optimize traditional OCR systems for document digitization and text extraction tasks.\nIntegrate OCR outputs with LLM-based AI agents to create seamless workflows for information processing.\nCollaborate with cross-functional teams to identify use cases, gather requirements, and deliver tailored AI solutions.\nConduct data preprocessing, feature engineering, and model evaluation to ensure robust performance.\nStay updated on the latest advancements in LLMs, RAG frameworks, computer vision, and OCR technologies.\nDocument methodologies, experiments, and results for internal knowledge sharing.\n\nRequirements\n\nMaster’s or Ph.D. in Computer Science, Data Science, Machine Learning, or a related field.\nStrong experience with LLM fine-tuning (e.g., GPT models, BERT) and familiarity with frameworks like Hugging Face or OpenAI APIs.\nProficiency in traditional OCR techniques using tools such as PaddleOCR models.\nStrong programming skills in Python; familiarity with libraries like PyTorch, TensorFlow, Scikit-learn, or similar.\nExperience with cloud platforms (AWS, Azure, GCP) for deploying machine learning models at scale.\nExcellent problem-solving skills and the ability to work independently or as part of a team.\n\nWhy Binance\n\nShape the future with the world’s leading blockchain ecosystem\nCollaborate with world-class talent in a user-centric global organization with a flat structure\nTackle unique, fast-paced projects with autonomy in an innovative environment\nThrive in a results-driven workplace with opportunities for career growth and continuous learning\nCompetitive salary and company benefits\nWork-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1505, 682, 2, 'Security Engineer - (Red Team) - Khối Công nghệ thông tin (HO25.214)', 'Job Description:\n- Perform security assessments, evaluations, and penetration testing of the information security system.\n- Conduct Red Team penetration tests, simulating real-world attacks to identify internal vulnerabilities and weaknesses within the SOC system.\n- Provide training and knowledge sharing sessions with team members.\n- Perform other tasks as assigned by the Manager.\n\nJob Requirement:\n- Bachelor\'s degree (full-time, from public/private domestic universities or international universities) in Cybersecurity, Information Security, Cryptography & Information Security, Information Technology, Information Systems, Software Engineering, Network Engineering, System and Network Administration, Electronics & Telecommunications, or equivalent fields.\n- Strong understanding of the root causes of security vulnerabilities (based on OWASP, CWE) and manual exploitation techniques (without relying on automated tools).\n- Knowledge of Red Team phases and experience with penetration testing tools as well as tools used in each Red Team phase.\n- Proficiency in at least one scripting language to develop exploits (e.g., Bash, PowerShell, Python, Perl, Java, .NET, etc.), and the ability to modify or create exploits for web applications and operating systems.\n- Advanced research and debugging skills in various programming languages to reconstruct exploits related to 1-day vulnerabilities (0-day vulnerability discovery is a plus).\n- Understanding of Blue Team defense and monitoring mechanisms, with the ability to bypass or evade these security measures (a significant advantage).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj a okolí', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1506, 674, 2, 'Senior .NET Developer (AI)', 'Mô tả công việc\n\n- Design, develop, and maintain APIs using .NET Core and C# within a microservices architecture to support logistics, warehouse, and inventory processes.\n- Work with PostgreSQL databases and write efficient SQL queries\n- Set up and optimize CI/CD pipelines to automate application deployment.\n- Use Docker to package, deploy, and manage applications in containerized environments.\n- Occasionally contribute to user interface (UI) development using frontend technologies (as needed).\n- Optimize backend system performance, ensuring stability and scalability.\n- Collaborate with the team to analyze requirements, design solutions, and implement new features.\n- Ensure code quality through testing, code reviews, and adherence to coding standards.\n\nYêu cầu công việc\n\n- At least 3-4 years of experience in developing applications using .NET Core and C#.\n- Proficient in SQL and experienced with PostgreSQL or other relational databases\n- Integrate AI models and APIs into existing systems to enhance functionality.\n- Stay updated on emerging technologies, particularly in AI and software development\n- Preferred Qualifications: Experience with AI-driven development tools\n- Knowledge of microservices architecture and designing distributed systems.\n- Experience with CI/CD tools (e.g., GitLab CI, Jenkins) and automated deployment processes.\n- Proficient in using Docker for packaging and deploying applications.\n- Familiarity with RESTful API architecture, design, and implementation.\n- Experience with Golang is a plus.\n- Basic understanding of frontend development (HTML, CSS, JavaScript).\n- Strong problem-solving skills, with the ability to work independently and collaborate effectively in a team.\n- Experience in logistics, warehouse, or inventory management domains is a plus.\n- Logical thinking, attention to detail, and a strong sense of responsibility for work quality.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Competitive salary and benefits\n- Attractive 13th month salary and performance bonus\n- Annual performance review for salary raise and promotion\n- Premium private insurance (PTI Insurance) with discount for family members\n- Annual health check\n- 12 days of annual leave\n- Company trips and team buildings\n- Gifts on special accession: individual /company birthday, Tet and Holidays\n- Internal activities, sport and social clubs\n- Opportunity to training both technical and soft skills to develop your career path\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: 02nd Floor, FPT Tan Thuan 2, Tan Thuan Processing Zone - No. 8, Tan Thuan Dong, District 7, Quận 7\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1507, 885, 2, 'Full stack development (Mid-Level)', 'At ITGRATE, we bring together digital strategy, high-quality software development, and innovation. Our hybrid team of engineers, consultants, and product thinkers spans Vietnam and Europe, delivering smart digital solutions that create long-term value for our clients. We believe in combining technical excellence with a human-centered approach—across mobile, cloud, and AI-driven solutions.\n\nWe are growing and looking for a Digital Consultant — a mid-level Digital Expert who can own technical modules, mentor junior colleagues, and support the delivery of innovative software systems. We are particularly excited about AI tools and workflow/agent-based automation to raise quality and efficiency in our delivery process—so if you’re passionate about that, we want to hear from you.\n\nTasks\nAs a Digital Consultant at ITGRATE, you will:\n\nTake technical ownership of features and software components in mobile or web projects.\nWork with cross-functional teams (Product, Design, QA, DevOps).\nDevelop and maintain apps and backend systems using best practices and modern tools.\nInvestigate and solve bugs and performance issues across environments.\nContribute to architectural decisions and internal tooling discussions.\nMentor junior team members and conduct code reviews.\nEngage with clients and project managers in English and/or Vietnamese.\nHelp explore and integrate AI tools, workflows, and automation agents into project delivery.\n\nRequirements\nWe’re looking for someone who:\n\nHas 3–5 years of experience in mobile or software development.\nSpecializes in one of the following technologies:\nFlutter\nNative Android (Kotlin/Java)\nNative iOS (Swift/Objective-C)\nUnderstands object-oriented programming principles deeply.\nIs curious and open to new technologies such as AI agents, cloud computing, DevOps, and CI/CD tools.\nCommunicates clearly in both English and Vietnamese; German is a bonus.\nWorks proactively, takes initiative, and is a reliable team player.\n\nBonus Points If You\n\nHave worked in consulting or client-facing roles.\nHave experience with cloud-native platforms or containerized deployment (e.g., AWS, GCP, Docker).\nHave contributed to open-source or side projects.\nHave knowledge of process automation, data pipelines, or AI toolchains.\n\nBenefits\n\nFlexible working hours.\nOpportunity to work with western clients.\nExposure to diverse projects and industries.\nPotential for ongoing collaboration based on performance and project needs.\nA transparent career development path toward Senior Digital Consultant or Architect.\nExposure to international projects with high-quality standards.\nFlexible hybrid work culture with a base in HCMC.\nAnnual learning & development budget for upskilling, certifications, and tech events.\nOpportunities to experiment with AI-driven workflows and automation agents.\nA collaborative, multicultural team that values trust, transparency, and ownership.\n\nOur Hiring Process:\n\nIntro Call – Get to know each other.\nTech Interview – With our developers and consultants.\nCase Challenge – Show us how you think and build.\nFinal Interview & Offer – Culture fit, goals, and what success looks like.\n\nNote:\n\nOnly short-listed candidates will be contacted.\nVietnamese nationals preferred.\nPlease include your reference contacts and your portfolio (if available) in your CV.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'เวียดนาม', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1508, 316, 2, 'Frontend Developer (all genders)', 'HRS, a pioneer in business travel, aims to elevate every stay through innovative technology. With over 50 years of experience, their digital platform, driven by ProcureTech, TravelTech, and FinTech, transforms how companies and travelers Stay, Work, and Pay.\n\nProcureTech digitally revolutionizes lodging procurement, connecting corporations and suppliers in a cutting-edge ecosystem. This enables seamless efficiency and automation, surpassing travelers\' expectations.\n\nTravelTech redefines the online lodging experience, offering personalized content from selection to check-in, ensuring an unparalleled journey for corporate travelers.\n\nIn FinTech, HRS introduces advancements like mobile banking and digital payments, turning corporate back offices into touchless lodging enablers, eliminating legacy cost barriers. The innovative 2-click book-to-pay feature streamlines interactions for travelers and hoteliers.\n\nCombining these technology propositions, HRS unlocks exponential catalyst effects. Their data-driven focus delivers value-added services and high-return network effects, creating substantial customer value.\n\nHRS\'s exponential growth since 1972 serves over 35% of the global Fortune 500 and leading hotel chains.\n\nJoin HRS to shape the future of business travel, empowered by a culture of growth and setting new industry standards worldwide.\n\nBUSINESS UNIT\nTravelTech enables travelers to search and book hotel and meeting room content via modern SAAS booking portals and APIs. Our mission is to provide high quality content and an outstanding user experience to the traveler on the one side and compliance and cost savings for the cooperate travel programs on the other side.\n\nPOSITION\nWe are looking for a Frontend Engineer React (all genders) who loves to build top notch SAAS application delivering an outstanding user experience for Travelers, Meeting Planners and Hotel Partners.\n\nCHALLENGE\n- Implement applications in JavaScript/Typescript (React) \n- Ensure quality of code is kept on a high level \n- Develop, implement and improve application architecture based on AWS Cloud \n- Support the Product Owner, Product Manager, and UX Designer with requirement engineering \n- Collaborate across teams with regards to overarching technical concepts and practices \n- Stabilize, perform improvement and refactor service layer and data model \n- You work on one of our core systems and implement our extranet application, used by thousands of clients to create and manage their assets, content and data.\n\nFOR THIS EXCITING MISSION YOU ARE EQUIPPED WITH...\n- Strong experience in JavaScript/Typescript, HTML/CSS, ReactJS \n- Proficient in building and maintaining dynamic and interactive frontend elements \n- Willingness to contribute to UI design improvements with attention to detail \n- Nice to know about deploying applications at scale with techniques like Infrastructure as Code, Canary or Blue­ Green Deployments \n- Utilize AI tools to increase development productivity and quality \n- Nice to know about AWS Amplify for building and deploying frontend applications \n- Good knowledge of flexible layout, making mobile terminal responsive layout, and solving screen adaptation problems \n- Good understanding of SCRUM/Agile methodologies \n- UI/UX Design experience with Figma or similar tools is a plus \n- Fluency in English, spoken and written.\n\nPERSPECTIVE\nAccess to a global network of a globally united and mutually responsible "Tribe of lntrapreneurs" that is passionately dedicated to renew the travel industry and while doing so reinvent the ways how businesses stay, work and pay.\n\nOur entrepreneurial driven environment of full ownership and execution focus offers you the playground to contribute to a greater mission, while growing personally and professionally throughout this unique journey. You will continuously learn from a radical culture of retrospectives and continuous improvement and actively contribute to making business life better, smarter and more sustainable.\n\nLOCATION, MOBILITY, INCENTIVE\nThe attractive remuneration is in line with the market and, in addition to a fixed monthly salary, all necessary work equipment and mobility, will also include an annual or multi-year bonus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1509, 732, 2, 'Full Stack Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nThe Role: Our group is looking for a seasoned full stack developer to work on important internal services which are critical to the firm. As a full stack developer, you will have the opportunity to advance the architecture and develop complex frontend views to ensure optimal user experiences.\n\n- Develop/Maintain internal web applications on cloud and on premise\n- Create/Present API design specifications\n- Write well designed, tested code\n- Create and maintain software documentation\n\nWhat You’ll Bring\n- Expertise in Python web frameworks such as FastAPI, Flask, Django and others\n- Experience in HTML, CSS, JavaScript/TypeScript\n- Demonstrated experience in developing scalable and robust software web applications\n- Experience with popular JavaScript libraries and tools such as React.js, jQuery, NPM\n- Working experience with SQL databases (PostgreSQL, MySQL)\n- A solid background in Unix/Linux environment\n- Experience with CI/CD\n- Experience with Docker and containerized application\n- Excellent debugging and problem solving\n- Experience with Kubernetes or distributed systems is a plus\n- Experience with GCP is a plus\n\nWhat We Offer\n- Competitive and attractive compensation package with clear career road-map – where you feel challenged every day\n- We offer a strong culture of learning and development: training courses, library, speakers, share and learn events\n- Learn from who sits next to you! Working in WQ you are surrounded by smart and talented people\n- Employee resources groups with strong diversity and inclusion culture\n- Premium Health Insurance and Employee Assistance Program\n- Generous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\n- Team building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\n- Annual company trip and occasional global conferences – opportunity to travel and connect with our global teams\n- Happy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1510, 886, 2, 'Web Developer (Java - Spring Boot)', 'Job overview and responsibility\n- Develop and maintain Web apps using Java Spring Boot.\n- Work directly with remote team to clarify tasks and requirements.\n- Develop new features based on the user requirements (analyzing requirements and system design).\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance.\n- Managing time and resources based on the WBS.\n- Write high-quality, clean, elegant, maintainable, and testable code.\n- Maintaining technical documents up-to-date.\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n\nRequired skills and experiences\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- At least 3 years of relevant experience in Java development, Spring Framework and SQL.\n- Experience and knowledge in markup language, including HTML, CSS.\n- Experience with frontend JavaScript.\n- Able to communicate in English, written and spoken. Strong problem-solving and analytical skills.\n\nReport to\n- CTO and Director\n\nInterview process\n- 2 rounds offline', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1511, 887, 2, 'Web Developer (Python, SQL)', 'LG CNS is looking for qualified Front-end developers to join the team. You will develop web applications in different fields, such as: Banking, ERP, ....\n\nYou will:\n\n- Working with clients to develop the overall look and design of a website.\n- Producing, maintaining and modifying websites and user interfaces\n- Incorporating applications, graphics, audio and video clips into client websites\n- Creating tools that enhance the user’s website experience.\n- Ensuring websites are accessible across many platforms, including laptops and smartphones.\n- Routinely testing websites for ease of use, speed and other quality factors\n- Fixing any website issues or bugs that arise"\n\nRequirement\n\n[Required]\n- 1 years or more of experience in:\n- Web/Mobile Application Development\n- Develop HTML, CSS, JavaScript, and jQuery\n- Experience with Python development\n- Experience with SQL\n- Experience Git, Jira, Confluence, etc.\n- Experience the project under the CI/CD process.\n- Good English communication skill \n\n[Nice to have]\n- Understanding Back-end (java spring, Python, PHP,...)\n- Experienced Boomi Solutions, ready to learn new technology\n- have knowledge or experience as iPaaS Solutions\n- Low Code-based development\n\nOpportunity\n\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Review capacity annually and adjust salary increases according to work performance.\n- Korean language certificate bonus (TOPIK)\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8:00 - 12:00 - 13:00 - 17:00)\n\nLocation\n\n15th Floor, Keangnam Landmark 72, Me Tri, Nam Tu Liem, Hanoi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1512, 888, 2, 'Frontend Leader (Angular)', '1. Mô tả công việc:\n·      Chịu trách nhiệm thiết kế và triển khai các ứng dụng WEB/Mobile có khả năng mở rộng. Đáp ứng các yêu cầu nghiệp vụ của Digital Banking, đảm bảo về hiệu năng, chất lượng và bảo mật.\n·      Kiểm soát và duy trì chất lượng code đảm bảo code rõ ràng, minh bạch, dễ bảo trì dễ kiểm thủ, dễ mở rộng và ít lỗi tiềm ẩn.\n·      Cập nhật các công nghệ mới nổi và đề xuất các giải pháp sang tạo để nâng cao chất lượng nền tảng.\n\n2. Yêu cầu kỹ năng (Requirements):\n·      Trên 5 năm kinh nghiệm làm việc với vai trò Frontend, có kinh nghiệm làm việc với các framework React, Reactnative, Angular.\n·      Có kinh nghiệm về Microfrontend\n·      Có kinh nghiệm về review code và đánh giá chất lượng code.\n·      Hiểu biết về API Restful, các công nghệ về messaging như WebSocket,… và các sử dụng trong thực tế.\n·      Có kinh nghiệm về HTML, CSS, Javascript,… và thiết kế responsive.\n·      Có hiểu biết về cách xác thực phân quyền, sử dụng JWT, OAuth,…\n·      Có kiến thức và kinh nghiệm làm việc với các thư viện, framework, SDK. \n·      Biết Debug và viết các automation test.\n·      Có tư duy lập trình hướng đối tượng.\n\nƯu tiên ứng viên:\n·      Có kinh nghiệm quản lý dự án, làm việc theo phương pháp Agile\n·      Có kiến thức tổng quan về ngân hàng và am hiểu sâu nghiệp vụ ngân hàng\n·      Có hiểu biết/kinh nghiệm thực tế về các nghiệp vụ ngân hàng\n\n3. Trình độ học vấn (Education Requirements):\nBằng cử nhân hoặc cao hơn trong lĩnh vực Khoa học máy tính, Công nghệ thông tin, hoặc các ngành liên quan.\n\n4. Các kỹ năng mềm (Soft Skills):\nNhiệt tình, trách nhiệm với công việc\nCó kỹ năng tư duy chiến lược, phân tích, xây dựng quy trình, sản phẩm công nghệ số\nKỹ năng phát hiện và phòng ngừa rủi ro trong quy trình, hoạt động liên quan công nghệ số.\nLập kế hoạch và quản lý thời gian hiệu quả\nKhả năng làm việc độc lập và theo nhóm.\nGiao tiếp tốt và khả năng lãnh đạo.\n\n5. Quyền lợi (Benefits):\nLương và phúc lợi hấp dẫn:\nMức lương cạnh tranh, phản ánh trực tiếp kỹ năng và kinh nghiệm của ứng viên (chi tiết sẽ được thảo luận trong buổi phỏng vấn)\n13 ngày nghỉ phép linh hoạt, bao gồm ngày sinh nhật và các dịp quan trọng khác\nBảo hiểm đầy đủ theo luật lao động, cùng với chương trình bảo hiểm sức khỏe cao cấp - chương trình phúc lợi bổ sung đặc biệt dành cho nhân viên\nLãi suất vay ưu đãi - quyền lợi đặc biệt dành cho nhân viên MSB\nCơ hội phát triển nghề nghiệp hấp dẫn:\nTham gia những dự án số hóa trọng điểm với vốn đầu tư lên tới 1000 tỉ đồng, ứng dụng những công nghệ mới nhất.\nĐược dẫn dắt bởi đội ngũ quản lý giỏi chuyên môn, đánh giá công bằng. Cơ hội làm việc trực tiếp với các đối tác hàng đầu thế giới (AWS; BCG; IBM; Temenos…).\nNhiều chương trình đào tạo nâng cao kỹ năng, năng lực chuyên môn. Được tham gia chương trình Lãnh đạo kế cận (Talent Pool) khi nhiều năm có hiệu suất năm việc tốt.\nLàm việc trong “Ngân hàng Chuyển đổi số tiêu biểu” được vinh danh 3 năm liên tiếp bởi Hiệp hội Ngân hàng và Tập đoàn dữ liệu quốc tế (IDG)\nVăn phòng làm việc đẳng cấp theo mô hình Agile tiên tiến. Cơ sở vật chất, công cụ lao động tốt, cấu hình mạnh mẽ.\nHỗ trợ đào tạo và chứng chỉ trong lĩnh vực IT, ngân hàng/tài chính.\nMôi trường làm việc năng động:\nMô hình làm việc linh hoạt, trẻ trung, khuyến khích đổi mới và sáng tạo\nVăn phòng được trang bị hiện đại, kèm theo các thiết bị tiên tiến nhất dành cho nhân viên\nTổ chức thường xuyên các hoạt động ngoại khóa (team building, hội thảo, và các sự kiện văn nghệ), tạo điều kiện cho nhân viên gắn kết và phát triển.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1513, 889, 2, 'Junior Full Stack Engineer - Remote', 'About Sleek\n\nThrough proprietary software and AI, along with a focus on customer delight, Sleek makes the back-office easy for micro SMEs.\n\nWe give Entrepreneurs time back to focus on what they love doing - growing their business and being with customers. With a surging number of Entrepreneurs globally, we are innovating in a highly lucrative space.\n\nWe operate 3 business segments:\n\nCorporate Secretary: Automating the company incorporation, secretarial, filing, Nominee Director, mailroom and immigration processes via custom online robots and SleekSign. We are the market leaders in Singapore with :5% market share of all new business incorporations\n\nAccounting & Bookkeeping: Redefining what it means to do Accounting, Bookkeeping, Tax and Payroll thanks to our proprietary SleekBooks ledger, AI tools and exceptional customer service\n\nFinTech payments: Overcoming a key challenge for Entrepreneurs by offering digital banking services to new businesses\n\nSleek launched in 2017 and now has around 15,000 customers across our offices in Singapore, Hong Kong, Australia and the UK. We have around 450 staff with an intact startup mindset.\n\nWe have achieved >70% compound annual growth in Revenue over the last 5 years and as a result have been recognised by The Financial Times, The Straits Times, Forbes and LinkedIn as one of the fastest growing companies in Asia. Backed by world-class investors, we are on track to be one of the few cash flow positive, tech-enabled unicorns based out of Singapore.\n\nSleek is also a proudly certified B Corp. Since we started our journey in 2017, we\'ve been committed to building Sleek as a force for good. In just over 5 years, we\'ve joined a community of industry leaders like Patagonia, Ben & Jerry\'s, and P&G who are building an inclusive, equitable, and a regenerative economy. We have planted over 29,271 trees to reforest our ecosystem and saved 7 tons of paper from landfills by processing over 1.4M pages through SleekSign. We aim to be Carbon Neutral by 2030.\n\nAbout The Role\n\nMission:\n\nAs the Fullstack Engineer, you will be at the forefront of transforming our technology landscape through comprehensive, end-to-end AI solutions. Your mission is to architect, develop, and deploy scalable systems that leverage advanced Artificial Intelligence and automation capabilities to drive operational efficiency, product innovation, and user satisfaction. You will work closely with cross-functional teams—ranging from data scientists and product managers to UX/UI designers and DevOps professionals—to ensure seamless integration of AI-powered features where they deliver the greatest value, while maintaining a robust software architecture and intuitive user experience. Your role will be instrumental in ensuring our next-generation platform not only meets client and internal needs but also sets new standards for innovation, reliability, and excellence in the AI-driven software industry.\n\nOutcomes:\n\nDeliver High-Quality Code: Consistently submit well-documented, maintainable, and robust code through Pull Requests (PRs) that include comprehensive tests (unit, integration) and adhere to team coding standards and best practices. Aim for high test coverage (e.g., >80%) on new code.\n\nApply Strong Fundamentals: Design and implement features demonstrating strong understanding and application of software architecture principles (e.g., SOLID, clean architecture), efficient database design (schema, indexing, query optimization), and API best practices (RESTful design, security).\n\nLeverage AI Tools Effectively: Integrate AI coding assistants and tools into your daily workflow to demonstrably improve development speed (e.g., reducing boilerplate, accelerating test writing, assisting debugging) without compromising code quality, maintainability, or introducing unnecessary complexity. Be prepared to share effective prompts and techniques.\n\nContribute to System Stability: Keep production rollback rate related to your contributions under 2% by enforcing comprehensive testing, leveraging CI/CD pipelines effectively, and adhering to established DevOps best practices.\n\nEngage in Collaborative Development: Actively participate in code reviews, providing timely, constructive feedback based on engineering principles and best practices. Respond proactively to feedback on your own PRs, contributing positively to team velocity and knowledge sharing.\n\nRequirements\n\nProfessional Background: You\'ve excelled as a Fullstack Engineer, AI Specialist, or a similar role for 1+ years, developing and deploying scalable applications that harness the power of AI.\n\nFront-End & Back-End: Fluent in React, NodeJS/NestJS, Typescript and SQL, with hands-on experience in microservices that are modular, reusable, and resilient. Experience with VueJS and MongoDB is a bonus.\n\nDatabases & Architecture: Comfortable with MongoDB/Supabase, ESR/RPC, and adept at designing solutions aligned with Clean/Hexagonal architecture, SOLID principles, ACID, and idempotency.\n\nAI Frameworks & Tools: Skilled in advanced AI ecosystems—LangChain, LlamaIndex, etc.—with experience in prompt engineering, RAG, and an interest in specialized hardware like Groq.\n\nQuality Advocate: Passionate about maintaining high testing standards, security patches, and thorough documentation for AI pipelines, ensuring consistent and reliable performance.\n\nInterpersonal Skills: Able to communicate fluidly with Agile teams, bridging gaps between product, UX, data science, and engineering to deliver successful AI initiatives.\n\nCloud & DevOps Expertise: Knowledge of AWS/GCP, when to leverage serverless/PaaS, and experience deploying microservices to Kubernetes—with a keen eye for best practices in MLOps and AI model lifecycle management.\n\nCollaboration & Independence: Equally comfortable working solo or in a team environment, driving projects from ideation to production while inspiring those around you.\n\nBenefits\n\nHumility and kindness: Humility is a core attribute we hire for, which means we have a culture of not taking ourselves too seriously and being able to laugh. Kindness is also incredibly important. We are committed to creating and nurturing a diverse and inclusive environment.\n\nFlexibility: You\'ll be able to work from home. If you need to start early or start late to cater to your family or other needs, we don\'t mind, so long as you get your work done and proactively communicate.\n\nFinancial benefits: We pay competitive market salaries and provide staff with generous paid time off and holiday schedules. Additionally, you\'ll be able to access our flexi benefits scheme for home office equipment or health and fitness expenditure. Certain staff at Sleek are also eligible for our employee share ownership plan and can share in the upside of our stellar growth trajectory as we work toward listing on a prominent stock exchange in the Asia Pacific region.\n\nPersonal growth: You\'ll get a lot of responsibility and autonomy at Sleek - we move at a fast pace so you\'ll be making decisions, making mistakes and learning. There\'s also a range of internal and external facing training programmes we run. We\'re also at the forefront of utilising AI in our space and are developing a regional centre of AI excellence. It is our intention that if you leave Sleek, you leave as a more well-rounded person and professional.\n\nInterview Process:\n\nThe successful candidate will participate in the below interview stages.\n\nTake Home Assessment:\n\nA take-home assessment to demonstrate your knowledge and skills in both frontend and backend development.\n\nEstimated time: 2 hours.\n\nNote: Assessment is unrelated to Sleek\'s business, and will not be used or distributed beyond the interview process.\n\nCase study interview\n\nA :60 minute chat with the member of the team to validate the technical aptitude of the candidate.\n\nCareer Deep Dive/Behavioral fit interview\n\nA :15 minute chat with a member of the HR Team\n\nOffer + reference calls\n\nWe\'ll make a non-binding offer verbally or over email, followed by a couple of short phone or video calls with references that you provide to us.\n\nRequirement for background screening\n\nPlease be aware that Sleek is a regulated entity and as such is required to perform different levels of background checks on staff depending on their role.\n\nThis may include using external vendors to verify the below:\n\nYour education\n\nAny criminal history\n\nAny political exposure\n\nAny bankruptcy or adverse credit history\n\nWe will ask for your consent before conducting these checks. Depending on your role at Sleek, an adverse result on one of these checks may prohibit you from passing probation.\n\nBy submitting a job application, you confirm that you have read and agree to our Data Privacy Statement for Candidates, found at sleek.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1514, 890, 2, 'Middle Angular (~40M Gross)', 'Công ty TNHH Nitori Digital Base Việt Nam là công ty con trực thuộc tập đoàn Nitori Holdings – tập đoàn chuyên về nội thất và đồ gia dụng lớn nhất Nhật Bản với hệ thống hơn 1000 cửa hàng trên khắp nước Nhật. Ngoài ra, sản phẩm của Nitori cũng dần trở lên quen thuộc với người dân Châu Á với loạt hơn 300 cửa hàng tại Trung Quốc, Hàn Quốc, Đài Loan, Hồng Kong, Singapore, Malaysia, Philippines, Thái Lan và Việt Nam. Đặc biệt, trong 4 nhà máy sản xuất của Nitori thì có tới 2 nhà máy đặt tại Việt Nam với quy mô 4500 nhân sự tại mỗi nhà máy. Quý 3 năm 2024, nhà máy thứ 3 tại Việt Nam chính thức khởi công với quy mô gấp 2.5 lần các nhà máy cũ. Sứ mệnh của Nitori Digital Base ViệtNam là giải quyết các bài toán của tập đoàn bằng công nghệ.\n\nCHẾ ĐỘ ĐÃI NGỘ \nThử việc nhận full lương, đóng BHXH full lương;\nThưởng lương tháng 13 và thưởng hiệu suất;\nXét tăng lương 01 lần/năm;\nNghỉ phép 15 ngày/năm;\nGiờ làm việc linh hoạt 8 tiếng/ngày, từ thứ Hai – thứ Sáu;\nChế độ làm việc hybrid theo quy định của công ty;\nCấp Macbook kèm màn hình riêng;\nKhám sức khỏe hàng năm tại bệnh viện uy tín;\nDu lịch hàng năm;\nHưởng đầy đủ các quyền lợi khác theo quy định chung của công ty và pháp luật.\n\nMÔ TẢ CÔNG VIỆC\nDự án bạn sẽ tham gia là dự án Ecommerce quy mô lớn của Nitori Holdings. Với tham vọng mở 3000 cửa hàng chuyên bán nội thất và hàng gia dụng trên khắp thế giới, Nitori Holdings hiện đang xây dựng lại hệ thống website bán hàng. Hệ thống này sẽ được tích hợp AI để phân tích dữ liệu, phân tích hành vi người dùng... Dự án này hiện đang trong giai đoạn đầu phát triển. Khi tham gia dự án này, bạn sẽ làm việc cùng đội ngũ kỹ sư phát triển phía Nhật Bản. Techstack của dự án: Java Spring Boot, Angular\nTham gia với vai trò là lập trình viên Frontend tập trung vào Angular;\nKhắc phục sự cố, phân tích và đề xuất điều chỉnh phần mềm để cải thiện hiệu suất hoặc khả năng bảo trì;\nTạo tài liệu kỹ thuật để tham khảo và báo cáo;\nCác nhiệm vụ khác từ người quản lý.\n\nYÊU CẦU CÔNG VIỆC\nTốt nghiệp chuyên ngành CNTT các trường đại học;\nCó thể giao tiếp tốt bằng tiếng Anh, tương đương Toeic 750 trở lên;\nCó ít nhất 04 năm phát triển web phía Frontend, mạnh về Angular;\nƯu tiên kinh nghiệm làm việc cho thị trường Nhật;\nCó khả năng truyền giao tiếp, truyền đạt tốt.\n\nLIÊN HỆ\nMrs.Đào Thị Xuân \nEmail: dao_thi_xuan@nitori.jp \nTell/Zalo: 0964-921-229', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1515, 878, 2, 'Full Stack Developer (HCMC, Hybrid) (Visa and Relocation Package Provided)', 'About Nimble\n\nWe solve our client\'s most difficult business challenges through technology. Our company partners with the most ambitious companies around the world creating long-term impact with the work with do. If you want to grow together, work on challenging products and enjoy using the best tools and practices, Nimble is the right place for you!\n\nOur Core Values\n\n- Extreme Ownership: We treat our clients’ business as ours.\n- Bias for Action: Execution is everything. We act swiftly, prioritize decisive moves, and maintain a strong bias for action to deliver results.\n- Intensity: We tackle challenges with high energy and focus, delivering results through bold, committed actions.\n- Pragmatism: We prioritize practical, straightforward solutions that deliver results, creatively tackling complex challenges with determination.\n- Outcome Over Process: We always work toward impactful outcomes, driving results that matter. Processes help us repeat what works, but meaningful outcomes remain our North Star.\n- Truth Seeking: We seek truth with intellectual honesty, sharp critical thinking, and fact-driven reasoning.\n\nWhat You Will Do\n\n- You will be an active member or lead a team of developers in a project squad. We have a wide range of project sizes.\n- Decide which technologies are going to be used for front-end, back-end and define the overall architecture.\n- Work closely with the Product Owner to make sure the backlog is efficiently planned and occasionally assist in technical discussions with clients. Most of the client interfacing is done by the Product Owner.\n- Write clean, composable, and maintainable code as you develop world-class products for our clients.\n- Write automated tests to build and maintain the product we build for our clients.\n- Do code reviews with your squad members.\n- Learn new technologies languages like Ruby, Go, or Elixir, and techniques so that you are able to adapt to the evolving needs of our clients.\n- Knowledge sharing through team rituals.\n- Collaborate with other team members to define the internal processes and initiatives to help the company accomplish its mission. Our handbook has been written by the whole team.\n\nRequirements\n\n- Professional web development with 3+ years of experience. Experience in Ruby, JavaScript, Go is ideal (at least one of them).\n- Comfortable working both on frontend and backend.\n- At least basic experience with a modern JavaScript framework like ReactJS/Redux, VueJS or AngularJS.\n- Experience in writing automated tests for web applications.\n- Enjoy working on challenging solutions and systems.\n- Believe that building great applications is not only about delivering code that "works", but involves thinking about reusability, maintainability, security, and performance.\n- A "Can do attitude" and a product mindset.\n- Confidence in communicating in English.\n\nWhy You\'ll Love Working Here\n\n- You’ll feel proud of every product we ship. We care deeply about quality, design, and doing things right—our name stands for excellence.\n- You’ll be surrounded by high performers. We’re a tight-knit, ambitious team that pushes each other to grow and thrive.\n- We\'re built differently. We’ve been profitable and bootstrapped since day one—no VC pressures, just smart, sustainable growth.\n- We take pride in craftsmanship. Whether it\'s code, design, or delivery, we hold ourselves to a high bar—because the little things shape the big picture.\n- Process with purpose. We follow agile principles not just in theory, but in practice. Our engineers work with clearly defined user stories, estimate using story points, and deliver iteratively in focused 1–2 week sprints.\n- Growth is part of the job. Through regular one-on-ones, structured feedback, and a clear leveling framework, we support every team member’s growth—not just in technical skills, but in communication, collaboration, and leadership.\n- Learning never stops. Access a vast library of resources like Pluralsight, PragPub, Leanpub, e-books, and more—plus a yearly education allowance to help you level up in any direction you choose.\n- We’ve got your back. From day one, you’ll get private medical insurance, social welfare coverage, and a company care fund.\n- We support your move. If you\'re joining us from abroad, we’ll take care of your visa, work permit, and provide a relocation package to help you settle in smoothly.\n- Flexibility that fits. We support a hybrid workstyle, giving you the freedom to find the right rhythm between home and office life.\n- Work with the right tools. We’ll set you up with a MacBook and a large external monitor so you can work comfortably and efficiently.\n- A workspace that works for you with our modern office in the heart of Ho Chi Minh City and Da Nang.\n- Stay fueled. Our kitchen is always stocked with drinks and snacks.\n- Take the time you need. Enjoy 26 days of paid leave a year (including public holidays), plus a sabbatical month every 3 years.\n- Celebrate your journey. From anniversary gifts to yearly company outings and spontaneous team activities, we make time for fun and appreciation.\n\n...and more perks to make work feel better.\n\nIf you are a passionate web professional looking to make a significant impact in a growing software development company, we would love to hear from you.\n\nJoin us in shaping the future with elevating web innovation!\n\nWe keep our recruitment process practical and straightforward.\n\nTo learn more about how we work, check our handbook named Compass, Github organization, and Medium account.\n\nWant to see what we have built? Check our Dribbble and Behance accounts.\n\nWant to keep in touch with us? Follow us on Facebook, Instagram, and LinkedIn.\n\nNimble is an equal opportunity employer.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1516, 880, 2, 'Freelance Software Developer (Python) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with Python.\n- Code review experience is a must.\n- Experience with AI projects is a plus.\n- Your level of English is advanced (C1) or above.\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines.\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge.\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments.\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio.\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Tsji Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1517, 531, 2, 'Frontend Engineer (7 month contract)', 'Why Pizza Hut Digital Ventures?\nWe love pizza. We eat it a lot. There’s no doubt about that and we’re proud of it. But what makes us different is that it’s our people that drive the success of our business.\nAlongside KFC, Taco Bell and The Habit Burger Grill, we are part of the Yum! Family; the world’s largest restaurant company with nearly 43,000 restaurants in over 140 countries. At Pizza Hut, we are on a journey to build the most loved global brand and the fastest growing in every country; we have big plans over the next 5 years to achieve explosive growth in a competitive and ever-growing market. We want to make it easy to get the best pizza and digital is at the core for this. From building a world-class platform and clean mobile experiences we are pushing the boundaries to ensure we are a source of innovation.\n\nThe role\nPHDV are working on a multi-year project to consolidate their online ordering product across all of the markets that we support globally. The team you will be working on is the front-end team, which will play a crucial role in building the new UI platform & working in partnership with other teams to enable them to build their own experiences for all of our markets. \nAs a cross functional team of Engineers, Designers, Delivery Managers and more, the front-end team works as a unit to deliver high quality outputs. We typically work by having an idea, analyzing it and then running experiments to see if this is the way we should move forwards. Everybody has a voice within the team and, when required, we will come together to work collaboratively to solve a problem. It’s important to us that everyone is bought into the process and understands what we’re doing and why.\n\nResponsibilities:\nBuilding secure, componentized frontend web applications using progressive enhancement and responsive design.\nIntegrating with custom APIs hosted in AWS\nWorking closely with the team to deliver a clean and maintainable codebase.\nResponsible for building componentized frontend web applications using progressive and responsive design.\nCollaborate with the product and design team to improve UI performance and enhance UX experiences.\nContinuous input into product roadmap.\n\nRequirements:\n3+ years of experience building and designing delightful user experiences as a frontend engineer.\nStrong grasp of both written and verbal communication in English.\nProficiency with HTML5, CSS3, and Javascript (Typescript is a big plus, but you can pick it up on the job if not!).\nGood knowledge of Vue.js and VueX (familiarity with React.js and single page application is a plus).\nHands-on experience in using CSS preprocessors like SCSS, SASS, or LESS.\nFamiliar with Webpack configuration.\nHave experience in implementing and designing large-scale front-end web application.\nHands-on experience in integrating with REST APIs.\nProficiency in code versioning tools such as Github, Bitbucket or Gitlab.\nBasic understanding of HTTP requests and responses.\n\nNice to have:\nDon’t worry if you don’t tick any of these boxes yet, we can help bring you up to speed!\nBasic understanding of NPM modules.\nMicro Frontend experience.\nGraphQL experience.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1518, 891, 2, '[Remote] Fullstack Engineer (React, NodeJS, English required)', 'COMPANY OVERVIEW \nOur client is a fast-growing international fintech startup on a mission to make entrepreneurship simpler. They help thousands of businesses eliminate administrative headaches by combining cutting-edge SaaS technology with expert human support. Their solution streamlines accounting, bookkeeping, and compliance, delivering real-time service with precision and speed. \n\nKEY RESPONSIBILITIES\n- Turn concepts, designs, and business requirements into scalable, maintainable, high-quality code using React and Node.js.\n- Build and maintain reusable components and libraries to ensure consistency and efficiency.\n- Optimize both frontend and backend systems for speed, scalability, and reliability.\n- Design and develop secure, efficient APIs for seamless data communication.\n- Champion full-stack best practices, including modular design, error handling, and performance tuning.\n- Write robust unit, integration, and end-to-end tests to ensure smooth and reliable deployments.\n- Prioritize security and privacy across the tech stack—handling authentication, encryption, and data protection.\n- Contribute to improving DevOps practices and CI/CD pipelines for streamlined deployments and monitoring.\n- Collaborate cross-functionally with designers, product managers, and engineers to ship features efficiently.\n- Stay current with emerging technologies to continuously improve development workflows and system architecture.\n\nMUST-HAVE REQUIREMENTS\n- 5+ years of full-stack development experience, with strong expertise in React (with hooks) and Node.js (Koa or Express).\n- Proficient in JavaScript and TypeScript.\n- Hands-on experience building scalable RESTful and WebSocket APIs with a focus on performance and security.\n- Solid understanding of database systems, especially PostgreSQL, including schema design and query optimization.\n- Strong background in frontend performance techniques such as code splitting, caching, and lazy loading.\n- Deep understanding of authentication and security (OAuth, JWT, API protection).\n- Experience with cloud platforms (preferably AWS), including services like Lambda, RDS, S3, and API Gateway.\n- Familiarity with CI/CD processes, Docker, and modern DevOps workflows.\n- Excellent problem-solving and debugging skills.\n- A growth mindset and eagerness to contribute to a strong, collaborative engineering culture.\n- Strong English communication skills - both written and verbal.\n\nPERKS & BENEFITS\n- Competitive salary in a fast-growing global team\n- Cross-cultural working environment to broaden your professional horizons\n- Annual budget for continuous professional development\n- Mental health leave\n- Flexible and hybrid working arrangements.\n\n📩Ping us for further discussion.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1519, 679, 2, 'HN – Nhân Viên Triển Khai Phần Mềm – Khu Vực Miền Bắc', 'Nhân Viên Triển Khai Phần Mềm – Khu Vực Miền Bắc\n\nHiện tại, Vexere là hệ thống vé xe lớn nhất Việt Nam, với hơn 1.000 hãng xe hợp tác bán vé với Vexere, phủ rộng hơn 3.000 tuyến đường trong và ngoài nước giúp người dùng có thể tìm thông tin chuyến xe, hãng xe, và mua vé trực tuyến dễ dàng. Đồng thời, Vexere còn cung cấp những đánh giá của các hành khách đã đi những hãng xe này. Hành khách có thể dễ dàng lựa chọn trước chỗ ngồi yêu thích, thanh toán vé trực tuyến, tiền mặt tại các cửa hàng tiện lợi trên cả nước.\n\nCác thành viên của Vexere tin rằng một tổ chức được sinh ra là để giải quyết các vấn đề nhức nhối trong xã hội. Văn hóa công ty chú trọng tinh thần cộng đồng, hỗ trợ lẫn nhau. Tất cả thành viên Vexere luôn được tạo cơ hội để được thể hiện bản thân, đóng góp sáng kiến về sản phẩm và chiến lược, và hướng đến trở thành những nhà lãnh đạo trong tương lai.\n\nHãy cùng tham gia vào team Triển Khai Phần Mềm – Software Implementation (SI) tại Vexere để cùng hỗ trợ thêm thật nhiều đối tác nhà xe trong quá trình quản lý vận hành và thúc đẩy gia tăng doanh số, xứng tầm là đơn vị tiên phong trong quá trình cách mạng số hóa ngành vận tải xe khách tại Việt Nam.\n\nMô Tả Công Việc\n\n- Học và nghiên cứu các giải pháp Phần mềm quản lý nhà xe.\n- Triển khai phần mềm cho các đối tác nhà xe: hướng dẫn, cài đặt, cấu hình hệ thống theo quy trình.\n- Đào tạo nhân viên nhà xe sử dụng phần mềm hiệu quả và đúng quy trình.\n- Hỗ trợ đối tác xử lý các vướng mắc kỹ thuật, kết hợp với các team khác để đảm bảo quá trình vận hành trơn tru.\n- Ghi nhận các yêu cầu, phản hồi từ khách hàng để đề xuất cải tiến sản phẩm cùng team Product.\n- Phối hợp với các phòng ban nội bộ để đảm bảo tiến độ và chất lượng triển khai.\n- Báo cáo tiến độ công việc định kỳ cho cấp trên.\n\nYêu Cầu Công Việc\n\n- Tốt nghiệp Trung cấp/Cao đẳng/Đại học các ngành: Công nghệ thông tin, Quản trị kinh doanh, Hệ thống thông tin, hoặc ngành liên quan.\n- KHÔNG yêu cầu kinh nghiệm – chỉ cần có tư duy học hỏi, nhiệt tình và đam mê công nghệ.\n- Giao tiếp tốt, có khả năng hướng dẫn người khác.\n- Kỹ năng tổ chức công việc, làm việc độc lập hoặc theo nhóm.\n- Thái độ tích cực, sẵn sàng đi công tác (có hỗ trợ công tác phí 100%).\n\nChế Độ – Phúc Lợi\n\nBên cạnh việc tìm kiếm và định hướng nhân sự công ty đến các giá trị "right people": tư duy logic, suy nghĩ tích cực, minh bạch và nhất quán, tò mò với những điều mới, giao tiếp dựa trên lắng nghe, khiêm tốn và trách nhiệm. Vexere còn không ngừng cải thiện, nâng cao chất lượng đời sống cho toàn thể nhân sự công ty, dưới đây là các giá trị phúc lợi mà bạn sẽ nhận được khi tham gia tại Vexere:\n\nLương Thưởng\n\n- Mức lương căn bản theo năng lực\n- Bonus tháng + Trợ cấp điện thoại + Công tác phí (hỗ trợ 100%)\n- Thưởng hiệu suất theo quý (tối đa 7 tháng lương/năm)\n- Review lương 2 lần/năm; Thưởng Tết, thưởng thâm niên\n- Lộ trình thăng tiến rõ ràng, phù hợp với năng lực, có cơ hội định hướng phát triển lên các vị trí chủ chốt\n\nChế Độ Khác\n\n- Tham gia BHYT, BHXH, BHTN theo quy định, ký hợp đồng chính thức sau khi thử việc.\n- 12 ngày phép/ năm, 3 năm tăng 1 ngày phép, ngày phép được cộng dồn qua 2 năm tiếp theo hoặc quy ra lương\n- Khám sức khoẻ tổng quát hàng năm\n- Chính sách vay cá nhân, tạm ứng lương\n- Chính sách giảm giá vé xe cho nhân viên\n- Chính sách ốm đau, thai sản, hiếu hỉ…\n- Chính sách thưởng khi giới thiệu nhân viên vào làm việc\n- Chính sách khoá học đào tạo phát triển bản thân: 18 triệu/ năm\n\nThời Gian Làm Việc\n\n- Vexere đang áp dụng hình thức làm việc Hybrid (có thể linh hoạt làm tại nhà hoặc lên văn phòng)\n- Thời gian làm việc: từ 8h30-18h00 từ thứ Hai – thứ Sáu + sáng thứ Bảy\n\nĐược Tham Gia Các Hoạt Động\n\n- CLB thể dục thể thao của công ty\n- Chính sách cho các hoạt động teamwork mỗi tháng\n- Tham quan nghỉ mát, team building, year end party\n- Được làm việc tại văn phòng trẻ trung, sôi nổi: môi trường làm việc nhân văn, lành mạnh, cởi mở cùng với những người trẻ năng động\n\nHiểu thêm về chúng tôi tại: Review về Vexere\n\nCách Thức Ứng Tuyển\n\n- Để biết thêm thông tin về công việc, vui lòng liên hệ Bộ phận Nhân sự:\n- Gửi CV về Email: careers@vexere.com, tiêu đề: Vị trí ứng tuyển – Họ tên ứng viên\n- Zalo: 039 555 54 86 (A. Nhân)\n- Văn phòng làm việc tại miền Bắc: Tầng 3 – Tòa nhà 101 Láng Hạ, Đống Đa, Hà Nội\n- Theo dõi Vexere Careers tại để cập nhật các vị trí tuyển dụng và rất nhiều những thông tin thú vị khác.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1520, 892, 2, 'PHP/JAVA/.NET/MOBILE DEVELOPER và QC', '💥 Mô Tả Công Việc\n\n✅ Có kiến thức cơ bản về PHP (WordPress), MySQL, HTML5/ CSS3, JavaScript (jQuery), Bootstrap,….\n\n✅ Đam mê học hỏi và làm việc phát triển website/ứng dụng PHP.\n\n✅ Muốn gia nhập vào đội ngũ làm việc chuyên nghiệp.\n\n✅ Kỹ năng đọc hiểu tài liệu Tiếng Anh.\n\nKhông yêu cầu', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Prowincja Thừa Thiên-Huế, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1521, 727, 2, 'Junior Cloud Engineer (M365&Azure)', 'Noventiq is hiring!\n\nAbout Us: Noventiq (Noventiq Holdings PLC) is a premier global provider of cutting-edge digital transformation and cybersecurity solutions, headquartered in London. We empower businesses to thrive in the digital age, connecting them with top-tier IT vendors and delivering our own innovative services and proprietary solutions.\n\nWhy Noventiq? Our success is driven by a robust three-dimensional strategy focused on expanding our market presence, diversifying our product portfolio, and enhancing our sales channels. Through strategic M&A activities, we are poised to capitalize on industry consolidation and achieve unprecedented growth. With a dynamic team of approximately 6,400 employees operating in around 60 countries, we have a significant footprint in regions with immense growth potential, including Latin America, EMEA, APAC, and a notable presence in India.\n\nYour Opportunity: Join a globally recognized organization, celebrated with multiple "Great Place to Work" awards. At Noventiq, your ideas matter. We foster an environment where innovation thrives and collaboration is a cornerstone. Be a part of our journey to drive digital transformation worldwide.\n\nReady to Make an Impact? If you\'re passionate about shaping the future of digital transformation and cybersecurity, we want you on our team. Join us and be a part of a global organization where your contributions are valued and your potential is limitless. Join us today!\n\nNow we’re looking for Junior Cloud Engineer to bring your talent to Noventiq Vietnam. You’ll be a part of our Services Delivery team.\n\nJob Responsibilities:\n- Participation in delivering projects based on Microsoft Office 365, Exchange, Azure AD and SSO; additional to VMware private cloud project\n- Writing project documentation and user/admin guides;\n- Provide training sessions for customers;\n- Collaboration with team (another engineers, project managers, HQ colleagues);\n- Technical support (3-rd line);\n\nPosition Qualifications:\n- Fresh grads are acceptable, from Technology major;\n- Experience in Office 365 configuring (tenant, Exchange,...) will be plus;\n- Experience in hybrid scenarios with on-premise Exchange and migrations;\n- Microsoft Exchange Server – knowledge of architecture, capability and functions;\n- Knowledge about Azure AD and SSO; VMware private cloud;\n- Good knowledge in core infrastructure (Microsoft Windows Server, Active Directory, DNS, System Center Configuration Manager) will be the privilege;\n- English language – basic level (reading, technical documentation). Colloquial level will be the privilege.\n\nWhat We Offer:\n- Working time: Mond-Fri, 9AM-6PM, flexible working time\n- Attractive salary with 100% salary during probation\n- Full-pay insurance, Compliance fully to Vietnam Labor code\n- Attractive Bonus, & Allowances for mobile, transportation, parking\n- Opportunities to work with global colleagues from different cultures\n- Premium Healthcare insurance for employee and family (spouse/children)\n- Annual Health check-up\n- Birthday paid day-off & Birthday gift\n- Recognition program, Referral program\n- Working device provided or reimbursement on personal device\n- Other activities: annual company trip, year-end dinner, exciting engagement events, Coaching opportunities, etc.\n- Annual Salary Review & Promotion.\n\nDon’t forget to include your CV with photo and cover letter. We receive a lot of applications, and we try to notice each of our potential candidates.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1522, 893, 2, 'Software Engineer II (Front End)', 'About Us\n\nWati is the world\'s leading WhatsApp-first conversational growth platform, empowering businesses to build deeper customer relationships and accelerate revenue growth.\n\nTrusted and loved by over 14,000 customers across 100+ countries, Wati has established itself as the premier choice for businesses leveraging WhatsApp and other messaging channels to connect with customers on their platform of choice.\n\nIn a world where real-time interactions drive growth, Wati\'s story is all about business growth through conversations. At Wati, we believe that every conversation matters, whether it\'s engaging a first-time prospect, nurturing a qualified lead, or deepening relationships with loyal clients. We transform these conversations into opportunities for building relationships, and strong relationships lead to increased revenue.\n\nOur Platform\n\nThe AI-native platform simplifies complex business operations by bringing all customer interactions under one intelligent roof. Designed for scalability and ease of use, our solution delivers a measurable ROI while adapting to businesses of all sizes, from emerging startups to established enterprises.\n\nOur Backing & Partnerships\n\nWati is proudly backed by world-class investors including Tiger Global, Sequoia Capital, DST Global, and Shopify. As a Premium-tier Partner of Meta, Google, and WhatsApp, we maintain the highest standards of integration and platform excellence.\n\nAs Wati continues to scale rapidly, we\'re looking for a Software Engineer II (Front End) to work closely with Development, QA, DevOps, Support and Product. You are a leader that will participate in senior technology strategy discussions, drive ideation across a distributed software team, develop implementation roadmaps and work with technical individuals to transform this into software products and solutions.\n\nWhat you\'ll do:\n\n- Develop, test, and maintain web applications using React, with a focus on creating clean, efficient, and reusable code\n- Collaborate with cross-functional teams, including design, product, and QA, to deliver a seamless and engaging user experience\n- Participate in the entire software development lifecycle, including planning, development, testing, and deployment\n- Implement front-end solutions that integrate with backend APIs and services in a secure and scalable manner\n- Optimize applications for performance, scalability, and accessibility\n- Participate in code reviews, contribute to technical discussions, and uphold high standards of code quality\n- Troubleshoot and resolve front-end issues, ensuring the best possible user experience.\n\nRequirements\n\n- Bachelor\'s degree in Computer Science, Engineering, or related field, or equivalent practical experience\n- 3+ years of hands-on experience with React development\n- Proficiency in JavaScript, HTML, CSS, and front-end development principles\n- Familiarity with state management libraries (e.g., Redux or Context API)\n- Experience with version control systems (e.g., Git)\n- Understanding of RESTful APIs and integrating front-end code with back-end services.\n\nWhat will make you stand out:\n\n- Experience developing or contributing to SaaS applications\n- Familiarity with component libraries and design systems to build consistent user interfaces\n- Understanding of cloud platforms and module federation is a big plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh-Stadt, Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1523, 769, 2, 'Trưởng Nhóm Lập Trình PHP', 'Mô tả công việc\n\n• Phát triển các hệ thống, sản phẩm của công ty\n• Xây dựng hệ thông API kết nối với các hệ thống của Google, Facebook\n• Công việc chi tiết sẽ trao đổi thêm khi phỏng vấn\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1524, 719, 2, 'iOS Developer', 'MÔ TẢ CÔNG VIỆC\n\n- Làm việc onsite tại nhiều đơn vị khác nhau với nhiều dự án và công nghệ khác nhau.\n- Tham gia thiết kế ứng dụng, phân tích requirements, thiết kế hệ thống.\n- Có cơ hội được phát triển ứng dụng trên mảng tài chính, ví điện tử, cổng thanh toán, ngân hàng.\n- Nghiên cứu và áp dụng các công nghệ mới.\n- Tham gia các khóa đào tạo của công ty.\n- Thiết kế và phát triển giải pháp nền tảng mới.\n- Hỗ trợ và duy trì các ứng dụng web hiện có.\n- Hỗ trợ và tối ưu hóa quy trình làm việc cho Nhóm vận hành.\n\nYÊU CẦU\n\n- Có kinh nghiệm làm việc với Objective-C/Swift.\n- Có kinh nghiệm sử dụng: Xcode, cocoapods, TestFlight, Jira...\n- Có kinh nghiệm làm việc với OOP, OOD, memory management, property, enums, structures, classes.\n- Có hiểu biết về protocol, delegate và higher order functions.\n- Hiểu biết về thiết kế UI, hiểu biết sâu về AFNetworking, Alamofire, JSON encoder, decoder.\n- Có khả năng thiết kế hệ thống (UML, detail design).\n- Nắm được cơ bản các mô hình MVC, MPV, MVVM.\n- Có hiểu biết nhất định về các design patterns.\n- Có kinh nghiệm làm việc trong các dự án theo mô hình Agile Scrum.\n- Có kiến thức SVN, Git.\n- Có kinh nghiệm từ 1 năm ở vị trí tương tự.\n\nQUYỀN LỢI\n\n- Thu nhập thỏa thuận + thưởng.\n- Nghỉ thứ 7, chủ nhật, phép năm và các ngày lễ theo quy định.\n- Chế độ BHXH, BHYT, BHTN, thai sản theo quy định của nhà nước.\n- Làm việc trong môi trường chuyên nghiệp, năng động và phát huy được năng lực của bản thân, cơ hội thăng tiến công bằng.\n- Được tham gia các hoạt động phong trào ngoại khoá, vui chơi giải trí, du lịch do công ty tổ chức.\n- Chính sách Sinh nhật, kết hôn, sinh con,...\n- Được tham gia các khóa đào tạo không giới hạn để nâng cao kỹ năng phục vụ cho công việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 3, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1525, 715, 2, 'Kỹ sư Trí tuệ nhân tạo (AI Engineer)', 'Nơi làm việc: Hà Nội/Tp.Hồ Chí Minh\n\nThời gian: Full-time\n\n• Mô tả công việc:\n• Nghiên cứu, thiết kế, phát triển các mô hình machine learning ứng dụng cho các sản phẩm, bao gồm các dạng thiết bị phần cứng có cấu hình khác nhau (cloud, PC, edge). \n• Tối ưu hóa các mô hình machine learning, tăng performance mà vẫn giữ được độ chính xác, độ ổn định bảo đảm đúng yêu cầu. \n• Deploy các mô hình machine learning lên các thiết bị với hệ điều hành khác nhau, chuyển đổi mô hình sang các dạng deploy được trên AI Chip (dlc, tensorRT) \n• Thống kê kết quả đầu ra của mô hình, chỉ ra ưu nhược điểm và những vấn đề cần giải quyết, nâng cao tính năng mô hình. \n\n• Yêu cầu công việc:\n• Tốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán – tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\n• Có tối thiểu 2 năm kinh nghiệm liên quan đến vị trí ứng tuyển.\n• Có nền tảng toán học tốt, về ma trận, xác suất thống kê, tối ưu hóa, machine learning, deep learning. \n• Có kinh nghiệm về các project machine learning cũng như deep learning. Sử dụng linh hoạt các thuật toán machine learning truyền thống (unsupervised, supervised) và các model deep learning.\n• Có kiến thức về ít nhất một mảng nghiệp vụ như xử lý ảnh, xử lý âm thanh…\n• Có kinh nghiệm làm việc với các thuật toán CNN, GCNN, RNN, LSTM. Có khả năng sử dụng các loại backbone VGG, ResNet, Mobilenet và các mô hình phát hiện và phân loại các object như YOLO, SSD, CenterNet, ArcFace…, thành thạo sử dụng transfer learning.\n• Linh hoạt sử dụng các loại loss function, có khả năng phân tích, nghiên cứu tạo mới loss function nhằm nâng cao tính năng thuật toán.\n• Sử dụng tốt ngôn ngữ lập trình Python, có kinh nghiệm chuyển đổi mô hình dùng SNPE, TensorRT, Tensor Core…\n\n• Ưu Tiên\n• Thạc sỹ, Tiến sỹ các chuyên ngành liên quan đã có quá trình nghiên cứu tại các quốc gia phát triển trên thế giới.\n• Ứng viên đã có kinh nghiệm đảm nhận vị trí tương đương tại các công ty, tổ chức uy tín trong nước hoặc thế giới.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1526, 894, 2, 'Fullstack Developer', 'ABOUT US\nBaller Headwear is a caps manufacturer servicing foreign brands. We are currently looking for a Fullstack Developer with 1+ year of experience and strong English skills to join our team. You will help us develop and maintain internal web applications that support our daily operations. This is a great opportunity to grow with a fast-moving company and contribute directly to real business needs.\n\nWHAT WILL YOU INVOLVE\n\n- Develop user interfaces with React / Next.js.\n- Build backend APIs using Node.js / NestJS.\n- Integrate with databases (PostgreSQL / MongoDB / Supabase).\n- Integrate core accounting and finance modules into our ERP ecosystem.\n- Deploy and manage cloud-based applications using Google Cloud Platform (GCP) services.\n- Collaborate with UI/UX designers, testers, and product owners to ensure end-to-end integration.\n- Write clean, maintainable, and scalable code.\n- Maintain Git repositories, follow Gitflow processes, and participate in CI/CD pipelines.\n- Bachelor’s degree in Information Technology, Computer Science, or a related field.\n\nWHAT WE NEED YOU HAVE\n\n- 2+ year of hands-on experience in fullstack development.\n- Strong understanding of TypeScript.\n- Experience with ReactJS, basic knowledge of Next.js (SSR/ISR is a plus).\n- Basic experience building APIs with Node.js, preferably NestJS.\n- Familiar with RESTful APIs, HTTP, JWT, and backend concepts.\n- Experience working on production-level applications.\n- Solid experience working with relational databases (PostgreSQL, MongoDB, Redis is a plus)\n- Good logical thinking and ability to learn quickly.\n- Fluent in English (both written and spoken).\n\nWHAT WE OFFER YOU\n\n- Salary: Negotiable based on experience.\n- One-month probationary period.\n- Work MacBook provided.\n- High social insurance contribution.\n- 13th-month salary bonus.\n- Meal provided at the workplace.\n- 12 days of annual and public holiday leave.\n- Team-building activities, weekly tea breaks, and internal events.\n- A professional working environment with opportunities to use and improve English skills.\n\nWorking time: Monday to Saturday: 7.30 am - 4:30 pm. Half day off on Saturday.\n\nWe are looking forward to seeing you in the interview to know better about each other.  \n\nPlease send your English application to hiring@ballerheadwear.com with the subject line: [Your Full Name] - [Position Applied For]\n\nBALLER HEADWEAR VIETNAM CO., LTD\nAddress: No. 8 Street, Hoa Khanh Industrial Park, Hoa Khanh Bac Ward, Lien Chieu District, Danang City, Vietnam\nMobile: 0862 030 373\nEmail: hiring@ballerheadwear.com  \nWebsite: ballerheadwear.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1527, 707, 2, '[ĐÀ NẴNG] REACTJS/NODEJS DEVELOPER (Good English)', '1. REACT.JS • Develop UI Elements to integrate with server side logic • Solve technical problems • Support teammates to solve problems\n\nMUST HAVE SKILLS:\n• At least 2 years of experience in ReactJS, Redux. NodeJS is a plus\n• Have good knowledge or experience in front-end technologies, such as HTML5, and CSS3\n• Experience with GIT source control, Agile process\n• MUST be good at English communication\n\n2. Node.JS • Work directly with US/EU clients to implement features of system\n• Assist with application architecture design and implementation.\n• Develop web services and unit test\n• Adhere to and recommend improvements to project coding standards.\n• Work in a team environment with shared code; disciplined use of source code control and process documentation.\n• Solve technical problems\n\nMUST HAVE SKILLS:\n• Have experience in NestJS projects\n• ExpressJS, Restful API, Microservices, Serverless\n• Experience in MongoDB and one of relational databases MySQL, Postgresql \n• Architecture, algorithm knowledge \n• Good at verbal/non verbal English, able to work in an international environment\n• Good at analyzing & problem-solving skill\n\nBENEFITS\nCompetitive Salary and Brilliant Health Benefits\n• Attractive salary (13th-month salary, salary review twice/year) and project bonus\n• Bonus programs for candidate referral, technical article writing\n• Interest-free loan support for personal plan \n• Allowance for sickness, maternity, paternity and periodic health examination\n• PVI health care program \n• The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n• A professional English-speaking working environment with Agile – Scrum model\n• Hybrid Working Model: Flexible working time and WFH support. \n• Surrounded with friendly, open-minded, young and supportive colleagues \n• Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming,…)\n\nValuable Training\n• Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n• Sponsor fee for joining any technical training sessions and courses.\n• Free English workshops\n\nContact me:\n🌵Fb: https://www.facebook.com/lam.chu.dieu.nhien/?locale=vi_VN \n🌵Email: nhien.lam@saigontechnology.com\n🌵Zalo: 0971970623', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1528, 895, 2, 'Chuyên viên Phát triển phần mềm', 'Mô tả công việc\n\n- Phân tích yêu cầu người dùng và đặc tả kỹ thuật, thiết kế giải pháp và triển khai thực hiện giải pháp phần mềm hệ thống chứng khoán;\n- Nghiên cứu, đề xuất, ứng dụng các giải pháp CNTT trong quản lý doanh nghiệp;\n- Hỗ trợ các phòng ban nghiệp vụ trong các công việc liên quan tới CNTT.\n\nYêu Cầu Công Việc\n\n- Trình độ:\n  - Tốt nghiệp Đại học trở lên chuyên ngành liên quan tới Công nghệ thông tin;\n  - Trình độ ngoại ngữ: đọc hiểu tiếng Anh chuyên ngành.\n\n- Kinh nghiệm:\n  - Có kinh nghiệm tối thiểu 02 năm;\n  - Ưu tiên: ứng viên có kinh nghiệm phát triển các ứng dụng Mobile App (nắm vững công cụ Lập trình Native/Hybrid, hiểu RESTful API và WebSocket), phát triển các hệ thống có số lượng lớn giao dịch đồng thời hoặc phát triển các hệ thống trong ngành Tài chính/Chứng khoán.\n\n- Năng lực/Kỹ năng:\n  - Giao tiếp tốt, có kỹ năng làm việc nhóm;\n  - Có tư duy logic và giải quyết vấn đề, yêu cầu kỹ năng phân tích, thiết kế tốt;\n  - Có kỹ năng điều phối công việc, cẩn thận và chịu được áp lực cao.\n\nChế Độ Lương Và Đãi Ngộ\n\n- Chế độ lương và đãi ngộ:\n  - Mức lương: Thỏa thuận, cạnh tranh trên thị trường và được hưởng thu nhập tăng thêm theo kết quả hoạt động kinh doanh của Công ty, xứng đáng với năng lực, kinh nghiệm và hiệu quả công việc;\n  - Được hưởng các khoản phụ cấp ăn trưa, trách nhiệm công việc,…;\n  - Được hưởng đầy đủ chế độ BHXH, BHYT và các chế độ phúc lợi khác theo quy định;\n  - Được hưởng gói Bảo hiểm chăm sóc sức khỏe và hỗ trợ y tế cho CBNV và tham gia bảo hiểm cho người thân;\n  - Có nhiều cơ hội thăng tiến; Được tạo điều kiện tối đa để phát huy hết khả năng;\n  - Môi trường làm việc văn minh, chuyên nghiệp.\n\nHồ Sơ Bao Gồm\n\n- Hồ sơ bao gồm:\n  - Mẫu Thông tin ứng viên đăng tải tại website: http://tuyendung.vcbs.com.vn mục Cơ hội nghề nghiệp, trong đó nêu rõ kinh nghiệm công tác và quá trình đào tạo;\n  - VCBS ưu tiên ứng viên gửi hồ sơ sớm; VCBS có thể kết thúc việc tuyển dụng trước hạn khi đã tìm được ứng viên phù hợp.\n  - Liên hệ: Cán bộ phụ trách tuyển dụng Ms. Hoàng Hán, SĐT: 0243.936.6990 máy lẻ 827.\n\nJob Tags\n- IT\n- Developer\n- Lập trình viên\n- Chuyên viên phần mềm\n- Software Engineer', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Trần Hưng Đạo, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1529, 743, 2, '.NET 3D Developer (English)', 'Responsibilities\n\n- Develop advanced, configurable 3D models within the Emulate3D platform, utilizing C#/.NET programming in Visual Studio.\n- Interpret engineering data and translate it into programmable engineering rules to enhance application functionality.\n- Design and develop software tools that extend the Emulate3D platform, including:\n- Building intuitive and responsive user interfaces using WPF.\n- Interacting with SQL databases for data management.\n- Creating seamless integrations and interfaces with other software applications.\n- Provide ongoing user support.\n- Collaborate with a small, dynamic software development team consisting of mechanical and software engineers based in The Netherlands and Vietnam.\n- Work closely with the product owner and business representatives to refine designs and align development efforts with business needs.\n\nQualifications\n\n- Bachelor’s degree in mechanical engineering, Computer Science, or a related field.\n- A minimum of 3 years of professional experience in a technical or software-oriented organization.\n- Strong interest in both engineering and programming.\n- Extensive programming experience, with a preference for proficiency in C#/.NET.\n- Familiarity with version control systems such as Git.\n- Proficiency in English, with excellent oral and written communication skills.\n- Strong interpersonal, organizational, time management and problem-solving skills.\n- Flexibility to occasionally work shifted hours, particularly during the initial training period.\n- Previous experience with Emulate3D is welcome, but not required.\n\nBenefits\n\n- Competitive salary with 100% official salary during the probation period; 13th-month salary\n- Bao Viet Premium health-care insurance for employees and 2 dependents\n- Sponsored training and self-development opportunities (Java, PMP, CSM...)\n- 10% paid working time per week for personal development (attending soft skill courses, reading books, working on side projects, self-teaching any new IT-related concepts)\n- Modern facilities with Laptop Dell Precision 7670 chip i9-12950HX, Ram 64GB, SSD 512GB, RTX A2000 + 2 monitor Dell Ultrasharp U2422HE\n- Supportive, international, dynamic working environment and talented, culturally diverse teams\n- A large pantry full of snack, drink, and seasonal fresh fruit.\n\nAddress: Thai Nam Building, Duong Dinh Nghe Street, Trung Hoa, Cau Giay, Ha', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1530, 740, 2, 'Back End Developer (Java - Python - VueJs)', 'JOB DESCRIPTION\n• Work in a team of engineers to implement backend services in the platform\n• Build service definitions, OpenAPI specifications, SDKs, and documentation for other developers that consume these services\n• Integrate with other services and data sources using APIs, messaging systems, databases\n• Collaborate with the DevOps team on microservices design, containerization, and automated deployments\n• Build automated test suites to ensure these services are reliable and performant\n\nREQUIREMENTS\n• Experience working with Java - Python - VueJs\n• At least 4 years of exp\n• Project experience around web service design and RESTful APIs\n• Expertise with the OpenAPI Specification (Swagger), RESTful APIs, and related tools such as Postman, cURL, and HTTPie\n• Experience integrating with 3rd party services and databases such as Redis, message queues, MongoDB, and ElasticSearch\n• Prefer Senior/Leader candidates\n\nJOB BENEFITS\n• Salary: Negotiable\n• 14th-month salary bonus\n• KPI bonus based on project and performance\n• Extra package: 16 Mil /employee/year (Bonus at Tet, New Year, your birthday, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, …)\n• Opportunity to work in a professional, modern, and dynamic environment, take part in international projects\n• Opportunity to get on-job training and promotion\n• An excellent corporate culture with in/out of office activities that help to develop staffs ability and creativity\n• CMC health care and social insurance\n• Onsite opportunities: short-term and long-term assignments in US, EU,… (members of GEU/US).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム Hanoi ハノイ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1531, 526, 2, 'Senior Backend Engineer (Ruby/Java/Python, hybrid)', 'With the vision of "BETTER SYSTEMS, BETTER WORLD", RAKSUL has been unlocking the potential of various industries with the power of technology. To scale our innovation globally, we are going to launch new product in the global market from Japanese market.\n\nMain technology:\n- Ruby on Rails for backend\n- Vue.js, Typescript for frontend\n- AWS(EC2, ECS) for infrastructure\n\nResponsibilities:\n- Demonstrate technical and product ownership with product managers and business teams\n- Guarantee the products quality, high availability, and high throughput for long term business impact and customers experience\n- Work DevOps of various services and partner solutions\n\nTechnical skills:\n- Confident with Ruby/Python/Java or any other languages but willing to deal with Ruby. \n- Solid experience with developing Linux and web-based application’s frameworks (fluent in at least one of the following: Laravel, CakePHP, Symfony, Ruby on Rails, Django, etc.)\n- Hand-on experience with designing and tuning relational databases such as MySQL, PostgreSQL.\n- Experience with improving legacy code/system and working with REST API, and GraphQL.\n- Familiar with cloud computing such as AWS.\n\nOther skills:\n- Decent communication English skill to work with global members.\n- Strong documentation skill utilizing tools such as Notion, Clickup, Github, Wiki, etc.\n- Pair programming and/or mob programming.\n- Guiding junior members\n- Ability to work with others and preference on teamwork.\n- Strong interest to change old industries with technology.\n\nWhy you love working here:\n- Attractive benefit package\n- At least 15 annual days of a year\n- Private healthcare package\n- Salary review TWICE a year + performance bonus\n- Flexible working hours/ Hybrid working style/ Work from home\n- Latest Macbook pro provided+ Ergonomic chairs with huge tables\n- Drinks and Snacks at the office, monthly team-building party.\n- Find more information about us at: https://recruit-vn.raksul.com/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1532, 896, 2, 'Full-Stack Developer, Platform Operations', 'We’re looking for a passionate and skilled Full-Stack Developer to join our team, focusing on building automation tools and innovative solutions that help web/app owners grow their businesses. This role is ideal for someone who enjoys solving complex problems, working independently, and driving projects from research to execution. You’ll play a key role in developing internal products that enhance monetization, streamline operations, and bring new opportunities for publishers to increase their revenue.\n\nWhat You\'ll Do\n\n- Develop and optimize automation tools to improve operational efficiency and support publisher growth.\n- Build and maintain internal dashboards to monitor performance and identify opportunities for optimization.\n- Create scalable, high-impact solutions that drive better monetization and new revenue opportunities for publishers.\n- Collaborate with cross-functional teams to define and implement new features.\n- Conduct research and prototyping to explore innovative ways to support and expand publisher success.\n- Resolve challenging technical issues.\n\nWho You Are\n\n- 3+ years of experience in both frontend and backend coding environments, development frameworks, and third-party libraries.\n- Proficient in: JavaScript/TypeScript, React, and Node.js.\n- Experience in developing and integrating APIs.\n- Strong understanding of HTML5, CSS3, and ES6.\n- Familiarity with RESTful APIs, GraphQL, web app tooling, testing, and debugging.\n- A proactive mindset with a hands-on approach, a strong drive to achieve results, and a strong sense of ownership over projects.\n- Strong problem-solving skills and ability to work independently.\n- Bonus points for experience with Google Cloud Platform, Amazon Web Services, or Docker containers.\n- Experience with automation & process optimization is a plus.\n- Experience in programmatic advertising, ad servers, or real-time bidding is a plus.\n- Familiarity with streaming media protocols (HLS, DASH) and SSAI is a plus.\n- Bachelor’s degree in IT/Computer Science or a related field; a graduate degree is a plus.\n- Open mind-set to utilize AI in daily tasks/operations.\n\nWhy You Will Love It\n\n- Competitive Salary\n- Performance Review (2 times per year)\n- Performance Bonus (1 time per year from 0.5-month to 3-month salary amount)\n- Annual Leave: 15 days and other leave types\n- Private health Insurance\n- MacBook to be provided\n- Good chance to explore new trends in the digital market\n- Opportunity to learn and work with the most advanced advertising technology platforms\n- Work in professional, active, international and dynamic environment.\n\nInterview Process\nWe have 4 rounds to proceed:\n\n- Online HR interview\n- Technical test\n- On-site interview by the line manager and tech specialist\n- Online interview with the head of this business\n- Final online interview by the Managing Director.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1533, 778, 2, 'Backend Developer (NodeJS) - GenAI Product', 'JOB DESCRIPTION\nJob Title: Senior Backend Developer (Node.JS) - GenAI product\nLocation: HCMC\n\nDUTY AND RESPONSIBILITIES: \n- Collaborate with cross-functional teams to understand business requirements and translate them into technical solutions.\n- Design, develop, and maintain web applications that enhance customer experiences and streamline internal processes.\n- Develop server-side applications using Node.js, ensuring high performance, scalability, and security.\n- Work on the end-to-end development lifecycle, from ideation and design to testing, deployment, and maintenance.\n- Proactively ask questions to clarify requirements and challenge existing solutions to improve and innovate workflow.\n- Participate in code reviews, identify improvements, and maintain coding standards and best practices.\n- Stay up-to-date with industry trends and technologies to incorporate best practices in software development.\n\nMAIN REQUIREMENTS:\nTo apply, candidates must have: \n- At least 6 years of experience as Backend Developer/ Software Engineer or equivalent\n- Bachelor\'s degree in Computer Science, Software Engineering, or related field.\n- Proven experience as a Backend Developer with expertise in Node.JS\n- Familiar with Nodejs and its ecosystem such as: Express.JS, Nest.JS, TypeScript, ...\n- Familiar with application testing (unit testing, integration testing, e2e testing, BDD).\n- Solid understanding of the full software development life cycle.\n- Has a continuous learning and growth mindset. You should be excited to learn something new as part of your daily work.\n- Knowledge of databases, including SQL and NoSQL solutions.\n- Solid problem-solving skills, a collaborative mindset, and positive thinker.\n- Strong English communication abilities.\n- Must be independent engineer and can make your own decision when the time is needed.\n\nCandidates are nice to have:\n- Knowledge in Micro-services architecture is a plus\n- Experience with containerization technologies (Docker, K8s) and cloud platforms (e.g., AWS, Azure, GCP) is a plus\n- Knowledge in AI domain is a plus (Generative AI, LLMs (Llama, Gemini, OpenAI), prompt engineering, Langchain, AWS Sagemaker, AWS Bedrock, GCP Vertex,...)\n\nBENEFITS:\n- Attractive package including base salary + 13th month salary + Performance Bonus.\n- Insurance based on full base salary and Medical Benefit (Bao Viet Insurance Package) for Employee and Family\n- 100% of full salary and benefits as an official employee from the 1st day of working\n- 100% salary during probation time\n- Working in a fast paced, flexible, and multinational working environment with opportunity to travel onsite (in 49 countries)\n- Internal Training (Technical & Functional & English)\n- Working with outstanding colleagues coming from top universities and top companies in Vietnam and foreign countries\n\n*** Note: We highly appreciate your interest in this position of HCL Vietnam. After reviewing all applications, only qualified candidates will be contacted for the next steps within 15 days from date of submission.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1534, 897, 2, 'Senior/Techlead ReactJS - ENG- HN/ĐN/HCM', 'Company Description\nFSOFT Innovation, also known as FOne (F1), is a subsidiary of FPT Software, focused on innovating and enhancing production and operational efficiency. Providing services such as IT Outsourcing, Managed Services, Business Process Outsourcing, Staffing Augmentation, and Testing Services, FSOFT Innovation plays a key role in contributing to FSOFT’s growth. With offices in Hanoi, Hue, Da Nang, Tam Ky, Quy Nhon, Ho Chi Minh City, and Can Tho, FSOFT Innovation aims to continue expanding nationwide. The company values continuous innovation and creativity to achieve great goals.\n\nRole Description\nLooking for Senior/Teamlead ReactJS developer with fluent English communication skills who can directly work with foreign clients. We are interested in hearing about any personal projects you may be working on or any self-learning you are undertaking; you will need to show a track record in software testing experience that can showcase your capabilities. There are plenty of opportunities within the team to both teach and learn so we are looking for candidates with excellent technical and communication skills who are able to clearly express themselves and their ideas. \n\nRESPONSIBILITY   \n- Developing new user-facing features using React.js\n- Building reusable components and front-end libraries for future use\n- Translating designs and wireframes into high quality code\n- Optimizing components for maximum performance across a vast array of web-capable devices and browsers\n- Collaborate with BE team to finalize the appropriate solution\n\nQualifications\n- At least 5+ years of experience in ReactJS \n- Strong proficiency with front-end web technologies like HTML/ CSS coding skills. \n- Strong proficiency in JavaScript, including DOM manipulation and the JavaScript object model \n- Strong proficiency with popular React.js workflows (such as Flux, MobX or Redux) \n- Strong proficiency with RESTful APIs \n- Experience with data structure libraries (e.g., Immutable.js) \n- Experience with newer specifications of EcmaScript \n- Experience with SSR (NextJS) \n- Experience with GraphQL \n- Experience with CSS layout (Flexbox, Grid, Positioning, Media Queries, …) \n- Familiar with CSS frameworks (Tailwind, Bootstrap 4/5, …) \n- Active Source control – Git/Github/Gitlab \n- Ensuring cross-device compatibility (with or without CSS frameworks) \n- Able to write well-structured, maintainable code \n- Optimizing components for maximum performance across a vast array of web-capable devices and browsers \n- A strong attention to detail and a creative mindset \n- History of working within an Agile product delivery team \n- English is a must (can facing and communicate with customer)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1535, 225, 2, 'Senior iOS Engineer', 'JOB SUMMARY\nWe\'re seeking passionate, results focused Senior iOS Engineers to work on our flagship mobile platform that serves millions of customers daily. As a Senior iOS Engineer within Mobile Banking at NAB Vietnam, you’ll own key modules of our global product where you’ll use and grow your experience to architect and build mobile applications to maintain high availability and reliability.\n\nRESPONSIBILITIES\n• Design, develop, review, implement, and manage iOS application code and services for the production and pre-release environments;\n• Participate in Agile software development, prototyping, and code review with international development teams to build scalable microservices-based products\n• Understand the requirements of the customer or business and utilize this knowledge to develop applications that are consistent with this;\n• Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and tooling;\n• Provide robust coding practices and solid unit and component test coverage, and code debugging.\n\nSKILLS & EXPERIENCE REQUIREMENTS\nMust have\n• +5 years’ experience working in Software Development.\n• Solid experience in designing & developing native mobile applications in iOS (App Routing, Accessibility, Authentication, Caching, Code Analysis, Logging, Analytics, Secure code practice), and using the following tools: Swift, Objective-C;\n• Solid experience in using the following components: Alamofire, Apollo GraphQL, RxSwift, Oauth2, CocoaLumberjack;\n• Solid experience in modern front-end build pipelines and tools (e.g. Git, Gradle, XcodeBuild);\n• Experienced with architectural patterns - Clean Architecture, MVVM, MVC;\n• Experienced with Unit tests, UI Tests, API Testing: Mocks, Stubs;\n• Solid experience in Agile (Scrum model) development environments\n• Well-versed in writing structured, well-documented, maintainable, and clean code\n• Excellent in problem-solving and analytical skills\n• Strong understanding of standard Software Engineering processes, Testing, and Agile methodology;\n• Good English communication skills (both verbal & written), especially in the global software development environment.\n\nNice to have\n• React Native experience;\n• Microservices approach;\n• Experienced in performance testing, Accessibility for mobile apps;\n• Mobile Apps Security: Application Security Transport, Local Data Storage, Reverse Engineer;\n• Experienced with device fragmentation issues.\n• Experience in the Banking or Financial Services industry;\n\nA DIVERSE AND INCLUSIVE WORKPLACE WORKS BETTER FOR EVERYONE\nWe know that our people make us who we are. That\'s why we have built a culture of respect – where everyone feels valued and appreciated for being their true authentic selves at NAB. With our focus on inclusion and diversity, and in partnership with our Employee Resource Groups, NAB is a place where First Nations colleagues, colleagues of all genders, sexualities and ages, carers and colleagues with disability, and colleagues from all cultures, races and religions have the opportunity to thrive, connect and grow.\n\nWe are intent on providing an environment where you can work your way. Ask about our many flexible work options and please let us know if we can provide any adjustments throughout the recruitment process.\n\nCLOUD-FIRST \nNAB is undergoing an exciting "Cloud First" technology transformation by taking advantage of the latest tools and techniques used by leading technology and digital companies globally. But it’s not just about the Tech, we are also investing heavily in our people, so if you have an appetite to learn, grow and elevate others around you, this is the place for you!\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1536, 702, 2, 'Java Engineer- Compliance', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.  Job Description  We are seeking a talented Senior Java Spring Developer with a minimum of 3 years of professional experience to join our team. This is a remote position, offering the flexibility to work from anywhere in the world. The ideal candidate will have a strong background in Java Spring Boot, with a focus on developing Java micro-service applications. Experience with AWS cloud services is considered a bonus, as well as full-stack development expertise and knowledge of blockchain technology.  Responsibilities  - Designing, developing, and maintaining Java micro-service applications using the Spring Boot framework. - Collaborating with cross-functional teams to define, design, and implement new features. - Writing clean, efficient, and maintainable code. - Conducting code reviews and providing constructive feedback to team members. - Troubleshooting and debugging applications to optimize performance. - Staying updated on emerging technologies and best practices in Java development. - Working closely with team members across different time zones to ensure effective collaboration and communication.  Requirements  - Bachelor\'s degree in Computer Science, Engineering, or related field. - 3+ years of professional experience in Java development. - Solid experience with Java Spring Boot for developing micro-service applications. - Experience with AWS cloud services is a plus. - Full-stack development experience is an advantage. - Knowledge of blockchain technology is preferred. - Strong problem-solving and communication skills. - Ability to work independently and as part of a distributed team. - Willingness to work time shifts to accommodate collaboration with team members in different geographic locations.  Why Binance  - Shape the future with the world’s leading blockchain ecosystem - Collaborate with world-class talent in a user-centric global organization with a flat structure - Tackle unique, fast-paced projects with autonomy in an innovative environment - Thrive in a results-driven workplace with opportunities for career growth and continuous learning - Competitive salary and company benefits - Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)  Binance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.  By submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1537, 898, 2, 'Solutions Engineer - Vietnamese Speaking', 'The Sui Foundation exists to support the development, growth and adoption of the Sui network. Sui is the first permissionless Layer 1 blockchain designed from the ground up to enable creators and developers to build unique Web3 experiences from gaming to finance.\n\nThe Sui Foundation is committed to three decentralization principles; Embrace transparency and level the playing field, Communicate openly to build a culture of trust, and Engage directly with the community.\n\nMission\n\nOnboard the next billion users to web3 by supporting the advancement and global adoption of the Sui blockchain.\n\nVision\n\nTo create a better world that unlocks opportunities through universal access and individual ownership.\n\nLocation: APAC, Remote\n\nTeam Description\n\nThe Solutions Engineering team is looking for hands-on engineers to help partners and internal teams design, build, and scale on the Sui blockchain. This team plays a critical role in enabling adoption by supporting integration with the Sui framework, designing and implementing smart contracts in the Move language, and building full-stack applications that serve as developer tools, internal products, or external-facing demos and PoCs. If you enjoy solving real-world problems with clean code and collaborating across engineering, product, and community teams, this is a unique opportunity to work at the core of a fast-moving Web3 ecosystem.\n\nRole Description\n\nAs a part of the Solutions Engineering team, you’ll play a key role in expanding the adoption of Sui & Move technologies among developers and partner companies all over the world.\n\nYou’ll design and develop Smart Contracts, create innovative Solutions and empower other software engineers by building tools, creating technical resources, and showcasing the innovative capabilities of the Sui ecosystem.\n\nThis role requires a proactive, developer-focused mindset, strong communication skills, and enthusiasm for helping others learn and build on cutting-edge blockchain technologies.\n\nResponsibilities\n\n- Build and maintain full-stack applications using Next.js, React, TypeScript, and Node.js with SQL and Key-Value storage technologies for data management.\n- Design and implement smart contracts using the Move programming language to support real-world use cases and learning scenarios\n- Create high-quality technical demos, internal tools, and reference applications that illustrate how to build on Sui and interact with the Move programming language\n- Collaborate with developer educators to support workshops, live coding sessions, and educational content Provide technical guidance to developers integrating Sui into their own applications\n\nRequired Qualifications\n\n- Solid experience with JavaScript/TypeScript and React for frontend development\n- Strong understanding of Next.js and Node.js for backend logic, APIs, and server-side rendering\n- Experience with SQL databases and Redis in a real-world, production setting\n- Familiarity with Tailwind CSS for building clean, responsive UIs\n- Ability to debug, profile, and optimize full-stack applications\n- Strong communication skills and a friendly, collaborative mindset\n- Approachable, open to feedback, and enjoy working closely with others to solve problems and share knowledge.\n- Professional fluency in Vietnamese (spoken and written) is required for this role.\n\nPreferred Qualifications\n\n- Prior exposure to blockchain, Web3, or smart contract development\n- Technical Teaching or Education Experience Demonstrated ability to teach or mentor developers through courses, bootcamps, workshops, or community engagement.\n- Comfort leading workshops, writing technical guides, or presenting to developer audiences\n\nOur team is 100% remote and we are hiring across the world. Here at the Sui Foundation, you’ll be joining a world-class team with tremendous growth potential as we bring the next billion users to web3.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1538, 899, 2, 'Reactjs Developer', 'Job Description\n\n- Develop modular and maintainable HTML, CSS, Javascript, and React JS for our website\n- Continuously improve functionality and customer-interface of new Web/Mobile applications\n- Interact with the business and other technology teams\n- Translate functional requirements documents & UX design specifications into technical design and implementation\n- Schedule and coordinate changes and releases for production applications\n- Identify and evaluate new UI technologies for implementation\n- Mentor and coach mid-level and junior-level developers\n\nCompensation & Benefits\n\n- Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n- Work performance review 2 times/ year (in April and October);\n- Performance bonus, 13th- month salary, public holidays bonus (2/9, 30/4, 1/5, 1/1); bonus for Excellent Employee and Excellent Team;\n- Social insurance, health insurance, unemployment insurance and Bao Viet care insurance;\n- 01 hour paid leave per day for women having children under 12 months\n- 01 day remote work per month; A flexitime allowance of 90-180 minutes per month for employees\n- Minimum 14 paid leaves per annum for all employees after probation;\n- Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks;\n- Yearly company trip and year-end party, quarterly team building and weekly eating together; English - Japanese Club, Sports Clubs;\n- Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company;\n- Flat, open and sharing culture with friendly management team; outsourcing company with product mindset;\n- Training courses and working opportunities with technical gurus who built and operated world-class applications with millions of users. This might be a good chance for graduated students to learn cutting-edge technologies and how to build scalable system from scratch;\n\nRequirements\n\n- Bachelor\'s degree from university in Computer Science, Technology or related field;\n- Strong Skills implementing UI design using HTML 5, CSS 3, react, JavaScript, consuming JSON web-services and AJAX;\n- 2 years of experience with Javascript ES6/ React/ Redux/\n- Experience in Responsive and Adaptive Web Design;\n- Experience in designing and developing UI for various devices (desktop, table, mobile, etc.);\n- Significant experience in using tools like Github, Jira, etc;\n- Experience working within short development cycles using agile methods;\n- Excellent communication, interpersonal and organizational skills;\n- Experience in performance tuning of the front end elements;\n- Strong problem-solving skills, excellent verbal and written communications skills; \n- Passion for keeping up to speed with the latest software tools and methodologies.\n- Good at English (speaking skills)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1539, 674, 2, 'Senior Fullstack Developer - Nodejs', 'Mô tả công việc\n\n- Phát triển hệ thống web backend bằng Node.js (NestJS) và tích hợp với các hệ thống nội bộ.\n- Thiết kế và xây dựng các API phục vụ trao đổi dữ liệu với frontend (React/Vue) và ứng dụng mobile.\n- Tham gia vào toàn bộ vòng đời phát triển sản phẩm: từ phân tích yêu cầu, thiết kế, coding, đến kiểm thử và triển khai.\n- Phát triển các chức năng liên quan đến chatbot AI, phân tích hành vi người dùng, tự động hóa quy trình xử lý nghiệp vụ nội bộ.\n- Xây dựng các module có thể tái sử dụng, phát triển thư viện hỗ trợ nội bộ.\n- Làm việc với cơ sở dữ liệu SQL và NoSQL như MySQL, PostgreSQL, MongoDB.\n- Tham gia vào quá trình phân tích và thiết kế hệ thống, phối hợp chặt chẽ với team Data/AI, Frontend và Product.\n- Đảm bảo hiệu suất xử lý tốt, đáp ứng lượng người dùng lớn và hoạt động ổn định\n- Tham gia vào dự án ứng dụng AI vào thực tiễn, có tính đổi mới và tác động lớn đến quy trình doanh nghiệp.\n\nYêu cầu công việc\n\n- Có 3–5 năm kinh nghiệm ở vị trí tương đương, đặc biệt với Node.js, NestJS.\n- Có kinh nghiệm làm việc cả backend và frontend (ưu tiên có kinh nghiệm với React hoặc Vue).\n- Hiểu rõ về phát triển RESTful API, cấu trúc hệ thống web, và mô hình microservice là một lợi thế.\n- Thành thạo ít nhất một trong các cơ sở dữ liệu: MySQL, MongoDB, PostgreSQL.\n- Có kiến thức tốt về lập trình hướng đối tượng, mô hình MVC và kiến trúc hệ thống.\n- Có kinh nghiệm làm việc với các quy trình Agile/Scrum.\n- Kỹ năng phân tích và giải quyết vấn đề tốt.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Mức lương cạnh tranh, thỏa thuận theo kinh nghiệm/năng lực;\n- Thời gian làm việc: Thứ Hai – Thứ Sáu, thời gian làm việc linh hoạt;\n- Được trang bị công cụ làm việc theo chính sách của công ty;\n- Môi trường làm việc trẻ trung, năng động, tài năng;\n- Được đánh giá review lương định kì 6 tháng/lần;\n- Thưởng ngày Lễ/Tết, vinh danh, tuyên dương hàng tháng;\n- Được khám sức khỏe định kỳ;\n- Du lịch/nghỉ mát cùng công ty hàng năm;\n- Các chế độ khác theo quy định của pháp luật.\n\nPhụ cấp\n\n- Ăn trưa\n\n- Thiết bị làm việc\n\n- Được cấp Máy tính\n\nQuyền lợi\n\n- Bảo hiểm xã hội, Team building, Du lịch hàng năm, Thưởng tháng 13, Thưởng hiệu quả làm việc\n\nĐịa điểm làm việc\n\n- Hà Nội: 19 Trần Thủ Độ - Hoàng Liệt - Hoàng Mai, Hoàng Mai\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:48)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1540, 808, 2, 'Junior QA Engineer (AI)', 'Job Description\n\n• Participate in the requirements discovery, testing of the software product.\n• Build and execute test cases.\n• Write Reports & Documentation: Write detailed reports about the identified defects, store and maintain testing documentation. \n• Support AI Model Testing: Participate in testing and evaluating machine learning models, including tests for accuracy, stability, and fairness (bias).\n• Automation testing, performance testing and security testing to ensure stable software products.\n\nRequirements\n\n• College or university graduate, major in computer science, IT or equivalent is an advantage.\n• Careful, good logical thinking, passionate about experimenting.\n• Have a sense of responsibility, persistence.\n• Able to work under pressure, hardworking, proactive, and responsible.\n• Good communication skill.\n• Have experience in AI, and know about auto/API test is an advantage.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1541, 316, 2, 'Java Engineer (all genders)', 'HRS, a pioneer in business travel, aims to elevate every stay through innovative technology. With over 50 years of experience, their digital platform, driven by ProcureTech, TravelTech, and FinTech, transforms how companies and travelers Stay, Work, and Pay.\nProcureTech digitally revolutionizes lodging procurement, connecting corporations and suppliers in a cutting-edge ecosystem. This enables seamless efficiency and automation, surpassing travelers\' expectations.\nTravelTech redefines the online lodging experience, offering personalized content from selection to check-in, ensuring an unparalleled journey for corporate travelers.\nIn FinTech, HRS introduces advancements like mobile banking and digital payments, turning corporate back offices into touchless lodging enablers, eliminating legacy cost barriers. The innovative 2-click book-to-pay feature streamlines interactions for travelers and hoteliers.\nCombining these technology propositions, HRS unlocks exponential catalyst effects. Their data-driven focus delivers value-added services and high-return network effects, creating substantial customer value.\nHRS\'s exponential growth since 1972 serves over 35% of the global Fortune 500 and leading hotel chains.\nJoin HRS to shape the future of business travel, empowered by a culture of growth and setting new industry standards worldwide.\nWe are looking for a Java Backend Engineer (all genders) who loves to build top notch SAAS application delivering an outstanding user experience for Travelers, Meeting Planners and Hotel Partners.\nAdding new feature capabilities to our platform\nContinuous improvement of the platform to identify and resolve bottlenecks in runtime and development aspects\nLeverage generative Al tools such as GitHub Copilot, Amazon Code Whisperer, etc., to accelerate software delivery\nEmploy best software engineering best practices such as Infrastructure as Code, Continuous Integration - Continuous Delivery/Deployment\nWrite quality code and documentation, as well as develop and apply comprehensive test automation\nDevelop, implement and improve highly scalable application architecture based on AWS Cloud\nCollaborate across teams with regards to overarching technical concepts and practices\nStabilize, perform improvement and refactor service layer and data model\nExperience building event-driven applications at scale on AWS is a plus\nStrong understanding of core software engineering concepts and API design\n2+ years of experience as a backend engineer in a production environment\nExperience deploying applications at scale with techniques like Infrastructure as Code, Canary or Blue-Green Deployments\nSignificant experience in one or more general purpose programming languages (Java, Scala, Python, SQL)\nExcellent knowledge of Java technologies and State-of-the-Art Frameworks (e.g. Spring Boot)\nExpertise in Backend engineering, distributed systems, databases, etc\nAbility to work in a team, fast learning and enthusiasm for the realization of innovative products\nKnowledge of and experience in working with agile methodologies\nFluency in English, spoken and written\nAccess to a global network of a globally united and mutually responsible “Tribe of Intrapreneurs” that is passionately dedicated to renew the travel industry and while doing so reinvent the ways how businesses stay, work and pay.\nOur entrepreneurial driven environment of full ownership and execution focus offers you the playground to contribute to a greater mission, while growing personally and professionally throughout this unique journey. You will continuously learn from a radical culture of retrospectives and continuous improvement and actively contribute to making business life better, smarter and more sustainable.\nThe attractive remuneration is in line with the market and, in addition to a fixed monthly salary, all necessary work equipment and mobility, will also include an annual or multi-year bonus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1542, 732, 2, 'Full Stack Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nTechnologists at WorldQuant research, design, code, test and deploy firmwide platforms and tooling while working collaboratively with researchers. Our environment is relaxed yet intellectually driven. We seek people who think in code and are motivated by being around like-minded people.\n\nAbout WorldQuant BRAIN\nBRAIN is a group within WorldQuant similar to a traditional B2C fintech setup. Our mission is to simplify quant finance and provide global remote-work opportunities to participants, while they learn quant finance, AI and ML concepts. WorldQuant BRAIN provides an advanced crowdsourcing platform for external participants to contribute signals, data, and more.\n\nWhat You\'ll Do\n- Develop backend application services and APIs.\n- Integrate with AWS and external cloud services.\n- Develop complex single page applications.\n- Optimize application for speed and scalability.\n- Build reusable components for usage across interfaces.\n- Develop responsive layouts for desktop and mobile devices.\n- Automate UI testing processes.\n- Be an active member of an agile engineering team who is continuously looking to improve team performance.\n- Work with leading cloud technologies (such as AWS, GCP).\n- Work with leading open-source technologies (such as MySQL, PostgreSQL, ELK stack, Sentry, Redis, Git, etc.).\n- Participate in periodic on-call duties.\n\nWhat You’ll Bring\n- Passion about software engineering, be strongly driven to build and run real-world applications at scale.\n- Eagerness to learn and introduce new technologies. Be curious about what\'s happening in the tech world.\n- Excellent coding skills, solid understanding of the broad Python ecosystem including Numpy, Pandas and Asyncio.\n- Expertise in Python web frameworks such as Django, DRF, Flask and others.\n- Experience with client side frameworks and libraries that interact with server side APIs such as React, Angular, Vue.js, Svelte, TypeScript, etc.\n- Ability to design detailed user interface features based on high-level requirements.\n- Demonstrated experience developing scalable and robust software.\n- Experience with SQL databases (MySQL, PostgreSQL).\n- Experience with microservices, caching tools, data visualization, log collection and aggregation, search, queuing systems.\n- Experience with Linux environment and shell scripting.\n- Bachelor’s degree in Computer Science or related discipline or equivalent job experience.\n- Excellent debugging and problem solving skills.\n\nWhat We Offer\n- Competitive and attractive compensation package with clear career road-map – where you feel challenged everyday\n- We offer a strong culture of learning and development: training courses, library, speakers, share and learn events\n- Learn from who sits next to you! Working in WQ you are surrounded by smart and talented people\n- Employee resources groups with strong diversity and inclusion culture\n- Premium Health Insurance and Employee Assistance Program\n- Generous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\n- Team building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\n- Annual company trip and occasional global conferences – opportunity to travel and connect with our global teams\n- Happy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1543, 887, 2, 'Frontend Developer (VueJS, Javascript, HTML)', 'Job Description\n[SW Development]\nLG CNS is looking for qualified Front-end developer brothers to join the group. You will develop in developing web applications in various fields, such as: MY DATA, Machine learning / Data Learning, LENA/TUNA etc.\nMission:\n1. Ensure the best possible performance, quality and responsiveness of applications on the front-end side\n2. Stay up to date on emerging technologies\n3. Exchange details when interviewing\n4. Manage and training members in your PART (if you was chosen as Part leader)\n\nRequirement\n[Required]\n1. Have at least 1 years of experience ( Prioritize high experience )\n2. Experienced web/mobile application development\n3. Can develop HTML, CSS, Javascript, jQuery\n4. Can develop based on SPA (Vue.js, Vuex)\n5. Experienced with collaboration tools like Git, Jira and Confluence\n6. Understand and use CI/CD\n7. English speaking on average ( or TOEIC on 550)\n\n[Preferred]\n1. Understand Back-end\n2. Use Typescript\n3. Experienced with Node.js\n4. Experienced with javascript charts (Echarts, Chart.js, d3js, etc.)\n5. Experience using Tailwind, MUI\n6. OAuth development experience\n7. Korean communication\n8. Team management experience\n\nOpportunity\n1. Attractive salary and bonus will be discussed after going through CV & Interview.\n2. Review capacity annually and adjust salary increases according to work performance.\n3. Korean language certificate bonus (TOPIK)\n4. Health care: Premium health insurance, Annual health check-up\n5. Young working environment, flexible working hours\n6. Good career development opportunities with interesting and challenging projects.\n7. English, Korean, technical, soft skills training courses.\n8. Opportunity to learn special courses from LG CNS, new technology and security.\n9. Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n10. Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n11. Working hours: 8 hours from Monday - Friday (8:00 - 12:00 - 13:00 - 17:00)\n\nLocation\n1. 15th Floor, Keangnam Landmark 72, Me Tri, Nam Tu Liem, Hanoi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1544, 900, 2, 'Junior/Senior Java Developer', 'I. Key Accountabilities:\n\nA. Software Development\n• Responsible for ensuring that the bank\'s digital platforms work well by managing back end site databases, performance issues, security and that the server, application and database communicate with each other.\n• Responsible for collaborating with business tribes to understand the needs and technical requirements before building a web application.\n• Responsible for the server-side web application logic and integration with front-end codes\n• Collaborate with Front End Developers to design more functional and cohesive codes to enhance user experience.\n• Responsible for driving the application lifecycle with a key focus in coding and debugging of web applications based on feedback from testers and users.\n• Compile and analyze data, process and codes to troubleshoot problems and identify areas for improvement.\n\nB. Software Documentation\n• Work closely with tribe and squad members to translate business requirements into technical design documents.\n• Review and implement technical requirement documents by coding flowcharts, layouts, diagrams, charts, code comments and guides for the program.\n\nII. Requirements:\n\nA. Domain Expertise\n• 2+ years of relevant experience in software development in Finance - Banking domain\n• Solid foundation in Java programming.\n• Experience in development on ESB, API platforms, and Kafka platforms.\n• Understanding of SOAP and RESTful services, with knowledge of message standards such as JSON and XML.\n• Basic knowledge of databases such as Oracle, MS SQL, etc.\n• Experience using tools such as FTP, SSH, and XML editors.\n• Familiarity with CI/CD toolchains: Git, Jenkins, Maven, Nexus, etc.\n• Possess ESB/API certifications from Oracle/IBM/TIBCO, Mulesoft, etc.\n• Experience in programming with XQuery and XSLT.\n• Experience in AWS (bonus point)\n\nB. Agile / Digital Experience\n• Understands Agile principles, practices and Scrum methodologies.\n• Experience working in Agile teams to support digital transformation projects.\n\nC. Qualifications\n• Bachelor\'s degree in computer science, software engineering or information technology\n• English is required\n\nD. Personal Attributes\n• Passionate about technology and excited about the impact of emerging / disruptive technologies\n• Ownership mindset with a focus on getting things fixed, not simply discovered\n• A self-starter who thrives in an environment that fosters entrepreneurial thinking and innovation\n• Believes in the non-hierarchical culture of collaboration, transparency and trust across the team\n\nIII. Working location: 119 Tran Duy Hung, Cau Giay, Hanoi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1545, 892, 2, 'PHP/JAVA/.NET/MOBILE DEVELOPER và QC', 'Mô tả công việc\n\n💥 Mô Tả Công Việc\n\n✅ Có kiến thức cơ bản về PHP (WordPress), MySQL, HTML5/ CSS3, JavaScript (jQuery), Bootstrap,…. \n\n✅ Đam mê học hỏi và làm việc phát triển website/ứng dụng PHP.\n\n✅ Muốn gia nhập vào đội ngũ làm việc chuyên nghiệp.\n\n✅ Kỹ năng đọc hiểu tài liệu Tiếng Anh.\n\nKhông yêu cầu', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thua Thien-Hue, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1546, 712, 2, 'Game Designer (Casual/Puzzle)', 'Được thành lập năm 2018, Sun Studio là nhà phát triển games trên nền tảng web và các thiết bị di động với hơn 1 tỷ lượt chơi. Sứ mệnh của chúng tôi là tạo ra các trò chơi mà mọi người có thể dễ dàng tiếp cận (accessible) và yêu thích (enjoyable).\n\nHiện tại công ty có gần 70 thành viên với trên 40 đầu games (dòng hyper casual, casual và puzzle) và là đối tác chiến lược của các nền tảng web-games hàng đầu thế giới như: Facebook Instant Games, Microsoft Instant Games, Crazy Games, Game Distribution, Glance Gaming...\n\nChúng tôi cần tuyển 5 bạn Game Designers (junior - mid - senior) để hỗ trợ đội ngũ phát triển game trong việc thiết kế, cải thiện các games hiện tại và tương lai.\n\nMô tả công việc\n\n- Thiết kế & Phát triển gameplay: Tìm hiểu xu hướng thị trường và đề xuất các ý tưởng gameplay mới; thiết kế và phát triển các cơ chế game, tính năng và hệ thống cho game Casual/Puzzle từ giai đoạn ý tưởng đến khi hoàn thiện\n- Thiết kế level & nội dung: Tạo ra các level, câu đố, sự kiện trong game hấp dẫn, đảm bảo độ cân bằng, nhịp độ phù hợp với đối tượng người chơi casual. Liên tục chỉnh sửa, nâng cấp nội dung dựa trên dữ liệu phản hồi để tăng tính lôi cuốn\n- Phân tích và cải thiện trải nghiệm: Phối hợp với bộ phận dữ liệu để phân tích hành vi người chơi và các chỉ số (ví dụ: tỷ lệ giữ chân, tỷ lệ hoàn thành màn chơi). Từ đó đề xuất điều chỉnh thiết kế nhằm tối ưu trải nghiệm và doanh thu\n- Cộng tác làm việc: Làm việc chặt chẽ với lập trình viên, họa sĩ, và Producer để đảm bảo ý tưởng thiết kế được hiểu đúng và triển khai hiệu quả. Tham gia các buổi đánh giá game, đóng góp ý kiến để cải thiện chất lượng sản phẩm ở mọi khía cạnh\n- Tài liệu hóa & Quy trình: Xây dựng và cập nhật đầy đủ Game Design Document và các tài liệu liên quan, đảm bảo các ý tưởng thiết kế được truyền đạt rõ ràng. Tuân thủ quy trình làm game agile, chủ động quản lý tốt thời gian và tiến độ công việc của mình\n\nKỹ năng và kinh nghiệm yêu cầu\n\n- Cần gửi portfolio để đánh giá\n- Kinh nghiệm thiết kế game: Có kinh nghiệm làm Game Designer trong ngành game (mobile hoặc PC). Tối thiểu 1-2 năm kinh nghiệm đối với cấp Junior, hoặc 3-5 năm trở lên đối với cấp Senior. Ưu tiên ứng viên từng tham gia phát triển các game Casual/Puzzle. Có khả năng để ý tới từng chi tiết nhỏ trong game\n- Tư duy thiết kế xuất sắc: Nắm vững nguyên lý thiết kế game, có khả năng cân bằng game (độ khó, phần thưởng, kinh tế trong game) và thấu hiểu tâm lý người chơi\n- Kỹ năng phân tích: Tư duy dữ liệu tốt, biết sử dụng số liệu và phản hồi người chơi để tinh chỉnh thiết kế. (Ví dụ: hiểu các KPIs như DAU, Retention, ARPU và cách thiết kế ảnh hưởng đến những chỉ số này). Thành thạo các công cụ như GA4 hoặc các hệ thống BI tương đương\n- Thành thạo công cụ: Sử dụng thành thạo các công cụ phục vụ thiết kế game: ví dụ như Unity (hoặc các game engine tương tự), công cụ thiết kế level, bảng tính Excel/Google Sheets (để lên thông số, cân bằng game)\n- Giao tiếp & Làm việc nhóm: Kỹ năng giao tiếp tốt, có thể trình bày ý tưởng mạch lạc và biết lắng nghe phản hồi. Kinh nghiệm làm việc trong nhóm đa chức năng; thái độ chuyên nghiệp, cầu tiến và sẵn sàng thích nghi với quy trình làm việc linh hoạt (Agile)\n- Ưu tiên: Ứng viên có kinh nghiệm thiết kế các tính năng free-to-play (ví dụ: hệ thống tiền tệ, cửa hàng, sự kiện live-ops) hoặc từng phát hành thành công ít nhất một game Casual/Puzzle\n- Khả năng giao tiếp bằng tiếng Anh tốt là một lợi thế\n\nQuy trình tuyển dụng\n\n- Đánh giá Portfolio và CV\n- Video call phỏng vấn với Chuyên viên tuyển dụng (30-45 phút)\n- Phỏng vấn tại văn phòng với Trưởng nhóm (45-60 phút)\n\nChế độ đãi ngộ \n\n- Lương và giờ làm việc\n- Lương cho vị trí: hấp dẫn\n- Vị trí này sẽ làm việc tại văn phòng. Thời gian làm việc từ 9:00 - 18:30, từ thứ 2 đến thứ 6\n- Bảo hiểm và chế độ thưởng\n- Được tham gia đầy đủ BHXH/ BHYT/ BHTN theo quy định của luật lao động\n- Ngoài ra bạn sẽ được tham gia bảo hiểm sức khỏe riêng PVI\n- Phụ cấp ăn trưa hàng tháng\n- Thưởng cố định lương tháng 13\n- Thưởng cuối năm không giới hạn, tùy thuộc vào doanh thu của công ty và mức độ đóng góp của bạn trong các dự án\n- Cân bằng cuộc sống & công việc\n- Ngoài những ngày nghỉ lễ theo quy định của nhà nước, chúng tôi có thêm rất nhiều ngày nghỉ được trả lương và nghỉ ốm\n- Nơi làm việc thoải mái\n- Tại văn phòng, chúng tôi có khu vực giải trí, cung cấp đồ ăn phụ và đồ uống miễn phí để giúp bạn làm việc thoải mái và cân bằng\n- Góc Thư viện sách cho các bạn thích đọc sách giấy\n- Phát triển chuyên môn và giáo dục\n- Chúng tôi hoàn trả chi phí cho việc tham gia vào các hội nghị và khóa học có liên quan, đồng thời thường xuyên tổ chức các chương trình đào tạo nâng cao nghiệp vụ\n- Công ty có chính sách hỗ trợ việc thăng tiến và phát triển sự nghiệp của nhân viên\n- Giải trí và gắn kết\n- Hàng tuần / tháng / năm, chúng tôi tổ chức nhiều sự kiện, bao gồm các cuộc thi, thử thách thể thao, tiệc, happy hours, team building, hackathons và sự kiện ngoại tuyến dành cho từng đội\n- Dự án trách nhiệm xã hội\n- Chúng tôi tiếp tục triển khai các dự án từ thiện và hỗ trợ ý tưởng của nhân viên trong các cuộc thi tài trợ', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1547, 901, 2, 'Back End Developer', 'Tham gia nghiên cứu phát triển sản phẩm mới\nThiết kế và phát triển các ứng dụng web bằng Python và PHP: Xây dựng Data base - Code (Lập trình back-end, front-end)\nTiếp nhận các yêu cầu từ Phòng nghiệp vụ/ tester để phân tích các lỗi phát sinh, khắc phục\nBảo hành, bảo trì sản phẩm/ dịch vụ phát sinh (Lỗi do lập trình -> Backend)\nNâng cấp dịch vụ. Custom theo nhu cầu khách hàng - Test\nCác công việc khác theo phân công của Trưởng phòng Công nghệ thông tin', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Région métropolitaine de Hanoï', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1548, 715, 2, 'Kỹ sư Phát triển phần mềm ứng dụng (Application Software Design Engineer)', 'Nơi làm việc: Hà Nội\n\nThời gian: Full-time\n\nSố lượng: 03\n\nMÔ TẢ CÔNG VIỆC:\n- Tham gia phân tích yêu cầu và thiết kế chức năng, thiết kế module cho phần mềm ứng dụng trên PC/Mobile cho lĩnh vực y tế và chăm sóc sức khỏe.\n- Nghiên cứu, phát triển platform IoT cho lĩnh vực thiết bị y tế và chăm sóc sức khỏe.\n- Thực hiện, phát triển các khối chức năng module hệ thống theo thiết kế.\n- Sửa lỗi trong quá trình phát triển sản phẩm.\n- Tối ưu và nâng cấp hệ thống.\n\nYÊU CẦU:\n- Tốt nghiệp đại học loại khá trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông,…hoặc các chuyên ngành Kỹ thuật khác liên quan.\n- Trình độ tiếng Anh: TOEIC tối thiểu 550 hoặc điểm IELTS, TOEFL tương đương.\n- Có tối thiểu 01 năm kinh nghiệm đảm nhận vị trí tương đương.\n- Có kiến thức cơ bản về lập trình, sử dụng thành thạo ít nhất một ngôn ngữ lập trình: Java/Android/IOS/ React Native/ Flutter...\n- Có kinh nghiệm làm việc với Restful, SOAP API để kết nối ứng dụng với Back-End.\n- Ưu tiên các ứng viên có kinh nghiệm phân tích hệ thống, software design pattern.\n\nƯu Tiên\n- Thạc sỹ, Tiến sỹ các chuyên ngành liên quan đã có quá trình nghiên cứu tại các quốc gia phát triển trên thế giới.\n- Ứng viên đã có kinh nghiệm đảm nhận vị trí tương đương tại các công ty, tổ chức uy tín trong nước hoặc thế giới.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1549, 902, 2, 'Nhân Viên QA', 'Mô tả công việc\n\n- Lập kế hoạch (lịch) kiểm soát chất lượng;\n- Thực hiện kiểm soát các hoạt động liên quan đào tạo, xác định các sai lỗi thường xảy ra của quá trình dựa vào hồ sơ, dữ liệu các hoạt động đã thực hiện (báo cáo các điểm không phù hợp)\n- Báo cáo hoạt động kiểm soát chất lượng hàng tháng;\n- Thu thập dữ liệu, tính toán các chỉ tiêu quá trình;\n- Thu thập, xử lý các ý kiến sinh viên;\n- Thực hiện khảo sát mức độ hài lòng Sinh viên từng học kỳ;\n- Tham gia các kỳ đánh giá nội bộ, đánh giá bên ngoài của BVC.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1550, 702, 2, 'Quantitative Developer - Java', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nThis team at Binance delivers a user-friendly interface and seamless trading experiences. We offer great flexibility with a wide range of converted tokens and trade sizes. Our users benefit from various trading services, including guaranteed execution prices with no slippage, the best quotations, algorithm bots, and bespoke assets and products. Join us and be part of a team that enhances the trading journey for millions.\n\nResponsibilities\n\nEngage in the full life cycle of software development, including requirement gathering, design, coding, testing, and deployment. Possess strong technical skills, enabling the delivery of high-quality production code. Collaborate with the convert team to enhance the effectiveness of trading models. Liaise with trading and operations teams to develop new products and improve existing ones. Establish and improve trading system infrastructure to handle large scale positions and orders. Identify system bottlenecks and bugs, and implement solutions to address these issues. Attending to production emergencies.\n\nRequirements:\n\nExperience in the full lifecycle of project development for Java applications. Strong understanding of software design, architecture, development, and integration. Solid knowledge of event processing models, multi-threading, enterprise integration patterns, web services, and REST. Experience with algorithmic trading systems, investment banks, hedge funds, trading firms, or brokerages is a strong plus. A degree in Computer Science, Engineering, or a Mathematics/Algorithm-related field is a bonus. Flexible with working hours to attend to production emergencies. Fluency in English is required to be able to coordinate with overseas partners and stakeholders.\n\nWhy Binance\n\nShape the future with the world’s leading blockchain ecosystem. Collaborate with world-class talent in a user-centric global organization with a flat structure. Tackle unique, fast-paced projects with autonomy in an innovative environment. Thrive in a results-driven workplace with opportunities for career growth and continuous learning. Competitive salary and company benefits. Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team).\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Tsji Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1551, 903, 2, 'Java Software Engineer', 'JOB DESCRIPTION\nPosition : MIDDLE JAVA DEVELOPER\nQuantity : 05\nType : Full-time\nLocation : 5th Floor, TTC Building, No. 19 Duy Tan St., Dich Vong Hau Ward, Cau Giay Dist., Hanoi Capital, Vietnam\n\nABOUT US\nAstek is a global player in engineering and technology consulting, founded in France in 1988. Today, we are +7500 engineers across over 26 countries in the world.\nWith expertise in many industrial and tertiary sectors, we support our international clients in the intelligent deployment of their products and services, and in the implementation of their digital transformation.\nAstek Vietnam is established in 2022 to increase group’s capability to support our clients’ operation around the globe, leveraging Vietnam talented engineers.\nMore information about our group: https://astekgroup.fr/\n\nJOB DESCRIPTION & REQUIREMENTS\nResponsibilities:\n• Develop and implement Java applications.\n• Write clean, efficient, and maintainable code.\n• Troubleshoot and debug applications.\n• Collaborate with cross-functional teams to deliver high-quality solutions.\n• Maintain up-to-date knowledge of Java technologies and industry trends.\n\nKey Skills\n• Java SQL Data Modeling & Optimization\n• Clean Code & Defensive Programming\n• Tech Stack: Jakarta EE (Java EE)\n• Java backend development with Spring Boot\n• Java Persistence API (JPA)\n\nRequirements Skills and Knowledge\n• Min 3+ experience years in Java Developer\n• Strong proficiency in Java programming.\n• Experience with Java frameworks (Spring, Jakarta EE) and libraries (Hibernate).\n• Knowledge of software design patterns and principles.\n• Proven problem-solving and debugging abilities.\n• Effective communication and teamwork skills.\n• Proficiency in English communication\n\nBENEFITS\n• Attractive salary: Nego. Performance based award.\n• Young and dynamic working environment.\n• Continuous development of hard and soft skills through work and professional training.\n• Opportunity to approach newest technology trends.\n• Salary reviews 1 times/year or on excellent performance\n• Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\n\nCONTACT\nASTEK VIETNAM\n• Contact Person: Ms. Dzung Nguyen\n• Phone Number: 0969988029\n• Email: Thi-Kim-Dung.NGUYEN@astek.net\n• Website: https://astekgroup.fr/?lang=en', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1552, 904, 2, 'Software Engineer II', 'MiTek® is a global provider of building solutions for the residential and commercial construction industries. Utilizing software, services, engineered products, and automated manufacturing equipment, MiTek partners with clients to accelerate their genius and deliver breakthroughs in building.\n\nWith a rich 60-year history and a network of 6,500 team members worldwide, MiTek pairs local expertise with global capabilities. As a Berkshire Hathaway (NYSE: BRK-A, NYSE: BRK-B) company since 2001, MiTek has a record of continuous growth and innovation.\n\nLearn more at www.mii.com.\n\nA Brief Overview\n\nDesigns and develops and maintains software applications for customers in the building industry. Collaborates in a cross-functional agile team to deliver high-quality, efficient solutions to customer needs.\n\nResponsibilities\n\nWhat You Will Do:\n\n- Write, test and debug software\n- Refactor code, to improve performance, stability, and scalability\n- Collaborate with cross-functional teams to ensure that solutions are efficient, consistent and fulfill business needs\n- Participate in design reviews, code reviews, and collaborative requirements reviews\n- Participate in software design, independently designing solutions for small to medium features\n- Apply generally accepted programming standards and techniques to ensure efficient performance and data manipulation\n\nQualifications\n\n- Bachelors Related Field required\n- 2+ Years of experience in software design and development using relevant technologies required\n- Equivalent combination of experience and education which clearly indicates the ability to perform the essential functions of the position may substitute on a year for year basis\n\nSoft Skills\n\nCommunication; Collaboration; Critical Thinking; Time Management; Learning Mindset; Self-Motivation; Creativity;\n\nPhysical Demands\n\nThis role is performed in an office environment where a computer, telephone and other office equipment are used as needed to perform the duties of the role.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Binh Thuan, Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1553, 905, 2, 'Looking for Freelancer or Agency Based In Vietnam to Development of a SaaS + NFC Application', 'Hello everyone,\n\nI’m currently looking for a reliable freelancer or a small tech team to help me create an MVP for a SaaS platform integrating NFC technology.\n\nProject Objective:\nDevelop a web application (and potentially mobile) that allows users to scan NFC tags to trigger actions or link content. The system will include:\n\n·       A user interface (signup, dashboard)\n·       NFC tag management (reading, linking, logs)\n·       An admin panel\n·       A solid SaaS foundation to scale quickly\n\nI\'m deeply involved in the project (product vision, strategy, testing) and looking for a partner willing to commit to building a real product with potential.\n\nLooking for someone with:\n\n·       Full-stack skills (Node.js / Django / Laravel, React or Vue…)\n·       NFC integration experience (Web NFC, iOS/Android, or similar)\n·       Autonomy, reliability, and a proactive mindset\n·       SaaS experience is a real plus\n\nMVP goal: within 2–3 months Initial budget: to be discussed based on scope \n\nIf interested, please contact me with:\n\n·       Your portfolio or similar projects\n·       Your favorite tools\n·       Your availability and working style\n\nThanks in advance! Feel free to share this with anyone who might be a good fit.\nLet me know if you\'d like a shorter version or help polishing it for a job board post or LinkedIn. Happy to assist!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1554, 906, 2, 'Senior Frontend Developer (VueJS)', 'Phạm vi công việc\n- Thiết kế và triển khai các chức năng của sản phẩm phụ trách sử dụng VueJS/ReactJS\n- Triển khai giao diện người dùng (UI) và cải thiện trải nghiệm người dùng (UX) phù hợp với hoạt động kinh doanh của khách hàng nhằm thúc đẩy chuyển đổi số (DX)\n- Xác định yêu cầu và xây dựng tài liệu đặc tả phối hợp với quản lý sản phẩm và nhà thiết kế\n- Rà soát thiết kế và lập trình của các kỹ sư khác\n\nMôi trường phát triển\n- Lập trình: TypeScript/HTML/CSS\n- Khung: VueJS, NuxtJS, ReactJS, NextJS\n- Cơ sở hạ tầng: AWS/GCP\n- CI/CD: Circle CI/Bitrise/GitHub Actions\n- Công cụ kiến ​thức: Confluence/esaV\n- CS: GitHubK\n- Khác: Slack/Jira/Trello2\n\nYêu cầu ứng viên:\nPhải có:\n- Thấu hiểu sứ mệnh và giá trị của Nodo\n- Hơn 4 năm kinh nghiệm trong vai trò phát triển phần mềm: Lập trình viên Frontend\n- Kinh nghiệm với ngôn ngữ TypeScript\n- Kinh nghiệm với các framework frontend (VueJS, ReactJS, v.v.)\n- Kiến thức và khả năng giải thích các nguyên lý vận hành web và sự khác biệt giữa các trình duyệt\n- Kiến thức cơ bản về bảo mật ứng dụng web\n- Kỹ năng phát triển và vận hành sử dụng các framework khác nhau\nƯu tiên:\n- Kiến thức về Java/Python\n- Kinh nghiệm phát triển các front-end microservices\n- Kinh nghiệm phát hiện và giải quyết sự cố từ nhật ký\n- Kinh nghiệm quyết định và triển khai chính sách kỹ thuật của nhóm với vai trò trưởng nhóm kỹ thuật\n- Kinh nghiệm sử dụng và hiểu các thư viện và framework\n- Kinh nghiệm phát hành và đóng góp vào OSS (Open Source Software)\n\nQuyền lợi\n- Mức lương 25 - 35 triệu tùy theo năng lực\n- Cơ hội thăng tiến rõ ràng trong môi trường làm việc năng động\n- Được tham gia các khóa học nâng cao kỹ năng chuyên môn\n- Chế độ bảo hiểm đầy đủ theo quy định của pháp luật\n- Thưởng theo hiệu quả công việc và các dịp lễ tết\n- Được tham gia các hoạt động team building, du lịch hàng năm\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Văn hóa phẳng, cởi mở và chia sẻ với đội ngũ quản lý thân thiện\n\nĐiều kiện làm việc và thông tin liên hệ\n- Địa điểm làm việc: Tầng 3, tòa nhà Audi, số 8 Phạm Hùng, Mễ Trì, Nam Từ Liêm, Hà Nội\n- Thời gian làm việc: Từ thứ Hai đến thứ Sáu\n- Sáng: 8h30 – 12h00, Chiều: 13h30 – 18h00\n\nLiên hệ\n- Phòng Tuyển dụng (Ms. Vy)\n- Liên hệ: 086.612.2387\n- Mail: vynhu@nodo.vn\n- Website: http://nodo.vn/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1555, 450, 2, 'Software Engineer - Backend', 'Our Journey\n\nShopBack began in 2014 as a late-night spark of inspiration between Henry and Joel — not just to build a Cashback platform, but to reimagine how brands and consumers connect. As former advertisers, they understood the limitations of traditional marketing, and saw an opportunity to deliver more value on both sides. That idea quickly turned into action, with the first prototype built during a 24-hour sprint. Today, ShopBack serves over 50 million users across 13 markets, partners with 20,000+ merchants, and powers over half a million transactions daily. We\'re building The World’s Most Rewarding Way to Shop — and looking for bold, driven individuals to join us.\n\nAbout The Role\n\nWe are seeking team members who strive to solve hard problems, take pride in delivering world-class products, and are strong team players.\n\nYou are someone who wants to see the impact of your work making a difference every day. You find passion in the craft and are constantly seeking improvement and better ways to solve tough problems.\n\nYour Adventure Ahead\n\n- Contribute to the ideation, technical design, implementation, and testing of product features that empower our business and deliver impact to our customers.\n- Produce high-quality software following good architecture and design principles that are scalable.\n- Design & deliver thoughtfully crafted APIs to drive the interactions between our client applications and backend services.\n- Collaborate with the team to define the future of the ShopBack experience. Strong mentoring skills with the ability to provide technical guidance and review code.\n\nEssentials To Succeed\n\n- 2+ years of experience developing consumer-facing web applications or complex distributed systems.\n- Proven experience designing complex distributed systems, management products, or business applications. Understanding of good software design principles and have applied principles to professional work.\n- Hands-on experience working with Node.js (Preferred).\n- Have experience in TypeScript (Preferred).\n- Have knowledge in Test Driven Development (TDD), CI/CD.\n- Experience building and deploying applications and services into cloud environments (AWS highly desired).\n- Strong experience in the design and implementation of robust and highly scalable web services.\n- Ability to work effectively in a fast-paced, complex technical environment with high adaptability and flexibility.\n\nShopBackers\' DNA\n\nGrit - We tackle all challenges head-on, working together to solve problems and achieve success.\n\nHunger - We value hard work, and having relentless drive.\n\nSpeed - We move fast and have a bias for action, all to deliver maximum impact.\n\nImpact - We focus on results, always aiming for the best possible outcomes and timelines.\n\nGrowth - We embrace a growth mindset, constantly striving to learn, improve, and excel in our roles.\n\nExclusively for ShopBackers\n\nCareer progression paths and opportunities to take on greater challenges that help you realise your ambitions.\n\nBe part of a winning team on a journey to global scale.\n\nCompetitive compensation based on your performance.\n\nCandid, open, and collaborative culture where feedback is valued, for everyone to grow and improve every day.\n\nWork-From-Anywhere benefit to enable you to thrive personally and professionally.\n\nShopBack is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. We do not discriminate on the basis of race, color, religion, sexual orientation, national origin, age, disability, genetic information, veteran status, or any other protected status under applicable laws. Join our team and help us make a difference!\n\nWe are committed to protecting your data and ensuring fairness in our recruitment process. As part of this process, we use AI tools to assist with tasks such as application screening and candidate matching. These tools are designed to enhance efficiency and reduce bias, and their use complies with applicable data protection laws and our commitment to fair employment practices. Your personal data will be processed securely and transparently, and final hiring decisions are always made by our recruitment team, not by automated systems. If you have any questions about how your data is used, or wish to exercise any of your rights including the right to such processing, please contact us at dpo@shopback.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1556, 723, 2, 'KỸ SƯ CẦU NỐI BrSe', 'Mô tả công việc: BrSe kết nối các dự án nước ngoài của NMS với khách hàng Nhật Bản khi cần có thể làm việc tại Nhật Bản trong thời gian ngắn hạn 2-3 tháng hoặc dài hạn >1 năm\n\nQuyền Lợi\n\n– Lương: UPTO 40 man/tháng\n\n– Onsite tại Nhật Bản thời gian ngắn/dài hạn\n\n– Môi trường năng động, chuyên nghiệp\n\n– Cơ hội phát triển nghề nghiệp rộng mở\n\nYêu Cầu\n\n– Tối thiểu 3 năm kinh nghiệm lập trình JAVA, PHP, C/C++, .NET…\n\n– Tiếng Nhật: N3 trở lên hoặc tương đương\n\n– Có khả năng lãnh đạo nhóm, tinh thần trách nhiệm cao\n\n– Ưu tiên có kinh nghiệm làm việc với khách hàng Nhật\n\nĐịa Điểm Làm Việc\n\n– [VIỆT NAM]: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình\n\n– [NHẬT BẢN]: 3F Hoshino Building, Nishi Shinjuku, Shinjuku, Tokyo\n\nỨng Tuyển Ngay\n\nMs Huyền: 0969.709.429 / mail:huyenlt@nms.com.vn / skype:huyenthu.hr\n\n——————————–\n\nCông ty cổ phần Dịch vụ Di động Thế Hệ Mới (NMS)\n\n🏬 Hệ Thống Trụ Sở\n\n– Trụ sở chính NMS: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình, Hà Nội\n\n– Chi nhánh NMS Hòa Lạc: Tầng 8, Tòa nhà HTC Phú Cát, Khu công nghệ cao Hòa Lạc, Thạch Thất, Hà Nội\n\n– Chi nhánh NMS TP. Hồ Chí Minh: Lầu 3 – 385C – Nguyễn Trãi Quận 1 – TP. HCM\n\n– Chi nhánh Nhật Bản: 3F Hoshino Building, Nishi Shinjuku, Shinjuku, Tokyo\n\n☎ Điện thoại: 024.7300 8555\n\n🌎 Website: https://nms.com.vn/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1557, 707, 2, 'Java Developer (Middle/Senior)', 'Job Description\n\nDesign, build and maintain APIs, services\nDebug production issues across services and multiple levels of the stack\nWork with engineers across the company to build delightful features that span various parts of the system\nCollaborate with our business, product, and operations teams to understand and solve our users’ pain points\n\nJob Requirements\n\nMUST HAVE SKILLS\n\nYou have 5+ years of software development experience\nYou have strong software development experience using Java\nYou have experience in Spring MVC, Spring Boot, Hibernate, building Restful\nKnowledge of Cloud services such as AWS or Azure\nExperience with Micro Services\nExperience with Docker, GitHub Actions, Terraform\nExperience with PostgreSQL and Redis\nStrong AI: Copilot, Claude, MCP, N8N...\nStrong English communication (speaking)\n\nBenefits\n\nCompetitive Salary and Brilliant Health Benefits\n\nAttractive salary (13th-month salary, salary review twice/year) and project bonus\nBonus programs for candidate referral, technical article writing\nInterest-free loan support for personal plan \nAllowance for sickness, maternity, paternity and periodic health examination\nPVI health care program \nThe staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\nA professional English-speaking working environment with Agile – Scrum model\nHybrid Working Model: Flexible working time and WFH support.\nSurrounded with friendly, open-minded, young and supportive colleagues \nAnnual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\nSponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\nSponsor fee for joining any technical training sessions and courses.\nFree English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1558, 774, 2, 'QA Tester (Tiếng Nhật)', 'Mô Tả Công Việc\n• Viết testcase, tạo test data chi tiết cho các dự án nhằm kiểm soát chất lượng của tất cả các ứng dụng sản phẩm trước khi chuyển giao cho khách hàng\n• Thực hiện test chức năng, hoạt động, tính ứng dụng của các sản phẩm\n• Report và xác nhận bug phát sinh\n• Report kết quả test cho Test leader\n\nYêu cầu\n• Từ 1-3 năm kinh nghiệm làm việc vị trí Tester/QA.\n• Có khả năng đọc hiểu, viết test cases Tiếng Nhật (tương đương N3 trở lên)\n• Có kinh nghiệm test web, desktop app, native app, api, batch.\n• Có hiểu biết về kiểm thử phần mềm như các giai đoạn kiểm thử (Unit test, Integration test, Functional test, System test, Acceptance test,…) và các kỹ thuật kiểm thử.\n• Có khả năng tạo các tài liệu liên quan như (test plan, test cases, test procedures, test scripts, test reports)\n• Có khả năng sử dụng câu lệnh truy vấn SQL, có kinh nghiệm thao tác với các CSDL.\n• Có khả năng đọc hiểu và xác nhận Specification của dự án.\n• Có kinh nghiệm sử dụng các test tools phụ vụ cho hoạt động test.\n• Có kinh nghiệm làm việc với Agile là 1 lợi thế.\n• Có khả năng tự tìm hiểu, nghiên cứu hệ thống mới.\n• Có khả năng làm việc dưới áp lực và keep deadline.\n• Có khả năng mở rộng công việc khác khi test leader yêu cầu.\n• Có khả năng estimate công việc, tự quản lý công việc của bản thân.\n• Có kinh nghiệm làm dự án thương mại điện tử\n• Có khả năng đọc và viết Tiếng Anh, ưu tiên có khả năng giao tiếp với khách hàng là một lợi thế\n\nĐãi ngộ và quyền lợi cho CO-WELLers\n• Thưởng và review tăng lương 2 lần/năm\n• Thử việc hưởng 100% lương\n• Ca làm việc linh hoạt: 8h-17h; 8h30 – 17h30; 9h – 18h\n• Ngày phép: 14+ ngày/năm\n• Bảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên.\n• Kiểm tra sức khỏe định kỳ 1 năm/lần\n• BHXH, BHYT, BHTN mức cao, đảm bảo quyền lợi người lao động.\n• Trợ cấp hoạt động teambuilding hàng tháng, du lịch công ty 1 năm/lần\n\nDành riêng cho nhân viên nữ:\n• Nghỉ sinh lý 2,5h/tháng\n• Hưởng 100% lương trong thời gian thai sản\n• Thêm 5 ngày nghỉ khám thai trong thai kì\n\nMôi trường làm việc tuyệt vời\n• Trang bị thiết bị làm việc trọn bộ, hiện đại, đáp ứng yêu cầu dự án.\n• Làm việc và hướng dẫn bởi các chuyên gia/Senior nhiều kinh nghiệm thực tế.\n• Trợ cấp hàng tháng cho các hoạt động của CLB thể thao (Yoga, Zumba, bóng đá…)\n• Thông tin chính sách mới/cải tiến được cập nhật đều đặn tới nhân viên.\n• Có riêng khu vực thư giãn phục vụ hoạt động giải trí, ẩm thực.\n• Không gian làm việc mở, tiện nghi.\n\nCơ hội đào tạo và phát triển bản thân\n• Thường xuyên tổ chức các buổi đào tạo, seminar cập nhật xu hướng công nghệ.\n• Đào tạo kiến thức chuyên môn, kĩ năng quản lý, kỹ năng mềm,… theo định hướng công ty và nhu cầu khảo sát nhân viên.\n• Các lớp đào tạo tiếng Nhật (sơ cấp – cao cấp) với giáo viên bản ngữ trong giờ hành chính.\n• Cơ hội làm việc tại Nhật Bản với các nhân sự có tiếng Nhật.\n\nCách thức ứng tuyển\nBước 1: Đọc kỹ nội dung và xác nhận "Đồng ý" với Thỏa thuận về việc xử lý và bảo vệ dữ liệu cá nhân của CO-WELL Asia tại đây.\nBước 2: Sau khi xác nhận "Đồng ý" với thỏa thuận này, bạn vui click vào ô nộp hồ sơ để cung cấp thông tin tham gia ứng tuyển vào Công ty chúng tôi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1559, 740, 2, 'BrSE (Việt Nam)', 'Job Description\n\n• Communication between customer and offshore\n• Perform requirement hearing and analysis, solution proposal\n• Perform basic design, detailed design, test design creation/review in Japanese if needed\n• Perform deliverables review for offshore team if needed\n• Assist project manager on project scope, estimation, planning; monitoring and controlling\n• Support UAT testing and verifying bugs/issues\n\nRequirements\n\n• Japanese level equivalent to N2 or above\n• Strong communication skills both written and verbal\n• Has of experience in participating in a series of required tasks (requirement hearing and analysis, basic design, detailed design)\n• Has of experience with one of following technology stacks/platforms: Web application (Java, C#, PHP, Front-end language), Mobile application (Android, iOS), Embedded (C/C++), Salesforce, SAP, RPA, C++, AWS, Aras, Oracle.\n\nDesired Skills\n\n• Understanding about Japanese culture and Japanese working style\n• Experience managing big projects\n• Leadership potentiality, high responsibility, good teamwork spirit\n• Prefer candidate with work experience or study in Japan\n\nBenefits\n\n• Training in software quality systems.\n• Opportunity to work with global standards.\n• Opportunity to collaborate with consultants and certification organizations from world-renowned assessment bodies.\n• Training in implementing large-scale software projects at CMC Global.\n• Offer up to 55M gross.\n• Package: 14 salary months + Project bonus (If any) + Extra package: 16M/year\n• Young and dynamic working environment\n• Opportunity to approach newest technology trends\n• Exciting leisure: sport and art events (football club, family day…)\n• Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\n\nOpportunities\n\n• A chance to build and grow a potential team from the ground up.\n• Young and dynamic working environment.\n• Fun leisure activities: sports and art events (clubs, family day, etc.).\n• Labor policies fully compliant with Japanese labor laws.\n• Additional company benefits such as company trips, holiday events, and more\n\nWork Location: Hà Nội, Đà Nẵng\n\n1+ years of experience as BrSE/Team leader/Project Manager\n\n• Please send your application via email: recruitment@cmcglobal.vn\n• Years of Experience Required\n• Required Education Level: Bachelor’s Degree\n• Job Level: Middle/Senior/Team Lead\n• Work Form: Full-time\n• Email: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói, Hanoi, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1560, 907, 2, 'Game Designer', 'About Lion Studios\n\nLion Studios is a mobile games publisher that works with mobile developers to get their games discovered by players around the world. Headquartered in San Francisco, Lion Studios’ creative and strategy teams utilize their expertise to help game developers break through the noise and grow their businesses. Since launching in 2018, Lion Studios has driven 90% of its games to the Top 10 in the App Store and Google Play and helped drive 16 games to #1 in the US App Store’s Top Free chart. Many of the studio’s games hit the top 10 and the top 20 across both the App Store and Google Play. Collectively, the studio has driven hundreds of millions of downloads. Check out some of our hit releases: Mr. Bullet, Happy Glass, Save the Girl, and Slap Kings.\n\nA Day in the Life:\n\nWe seek a creative game designer to join our team and work on our hybrid-casual puzzle games. As a game designer, you will be responsible for conceptualizing, designing, and implementing game mechanics, systems, and features that provide engaging and addictive gameplay experiences for our players.\n\nThe Impact You’ll Make:\n\n- Drive early-stage game development by contributing to concept ideation, core gameplay design and level design.\n- Design and refine gameplay mechanics with a focus on difficulty tuning, progression, and player engagement throughout the game development phase.\n- Provide feedback and direction on core gameplay through internal reviews and early testing.\n- Collaborate with cross-functional teams, including artists, developers, and producers, to ensure cohesive game design and implementation, fine-tune game balancing, pacing, and feel.\n- Analyze player behavior and gameplay data to identify areas for improvement and iterate on features to optimize key metrics.\n- Stay on top of industry trends across mobile, PC and console to help shape innovative and competitive gameplay experiences current mobile, PC, and console gaming trends.\n\nBasic Qualifications:\n\n- At least 3 years of experience as a game designer, focusing on hybrid casual games.\n- Strong understanding of game design principles, mechanics, and monetization, particularly in the puzzle genre.\n- Advanced analytical skills, ability to spot patterns and trends.\n- Experience with level design and funnel optimization.\n- Experienced with creating mock-ups and design documents.\n- Experienced in communicating with programmers, leading them through the execution of your designs, and giving feedback.\n- Proficiency in Vietnamese and English to communicate with both local Vietnamese and Lion teams.\n\nPreferred Qualifications:\n\n- Proficiency in Unity is a huge plus.\n- Familiarity with Figma or similar visual collaboration software.\n- Experience and general knowledge of working with AI tool.\n- Track record of publishing/working on a successful hyper/hybrid casual or casual titles.\n\nAppLovin has become aware of a scam targeting jobseekers with fake “app optimization” and similar roles. We do not ask our candidates to download apps or make any form of payment(s). AppLovin works with applicants through our Careers page and applovin.com email addresses. If you are contacted through other unofficial channels (such as WhatsApp or Telegram) or asked to download an app or make a payment, these contacts are not legitimate. Confirm the information here and contact us directly with any questions.\n\nLion Studios is an AppLovin Studio. AppLovin makes technologies that help businesses of every size connect to their ideal customers. The company provides end-to-end software and AI solutions for businesses to reach, monetize and grow their global audiences. For more information about AppLovin, visit: www.applovin.com.\n\nTo deliver on this mission, our global team is composed of team members with life experiences, backgrounds, and perspectives that mirror our developers and customers around the world. At AppLovin, we are intentional about the team and culture we are building, seeking candidates who are outstanding in their own right and also demonstrate their support of others.\n\nFortune recognized AppLovin as one of the Best Workplaces in the Bay Area 2022, and is a Certified Great Place to Work in 2021, 2022 and 2023. Check out the rest of our awards HERE.\n\nAppLovin is proud to be an equal opportunity employer that is committed to inclusion and diversity. All applicants will be considered for employment without attention to race, color, religion, sex, sexual orientation, gender identity, national origin, veteran or disability status, or other legally protected characteristics. Learn more about EEO rights as an applicant here.\n\nIf you need assistance and/or a reasonable accommodation due to a disability during the application or recruiting process, please send us a request at accommodations@applovin.com.\n\nAppLovin will consider for employment all qualified applicants with criminal histories in a manner consistent with applicable law. If you’re applying for a position in California, learn more here.\n\nPlease read our Global Applicant Privacy Notice to learn more about how AppLovin processes your personal information.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1561, 908, 2, 'MIDDLE JAVA DEVELOPER', '● Mô tả công việc:\n- Phát triển và vận hành các tính năng trong hệ sinh thái Ứng dụng YouMed.\n- Phối hợp chặt chẽ với khách hàng, các bộ phận liên quan để làm rõ yêu cầu và phát triển sản phẩm đúng mong đợi, chất lượng và đúng hạn.\n- Làm việc với các đối tác là các Bệnh viện, Phòng khám, Bác sĩ.\n- Sửa lỗi và cải thiện hệ thống, có khả năng giải quyết lỗi càng sớm càng tốt.\n- Thường xuyên bảo trì, tối ưu hóa hệ thống, source code để đảm bảo hiệu suất và tính nhất quán trên toàn hệ thống.\n\n● Yêu cầu ứng viên:\n- Ít nhất 03 năm kinh nghiệm trong lĩnh vực phát triển phần mềm với ngôn ngữ Java.\n- Hiểu biết và có kiến thức tốt về OOP, cấu trúc dữ liệu và giải thuật, các design patterns phổ biến.\n- Có kinh nghiệm làm việc với Vertx framework, asynchronous programming.\n- Có kinh nghiệm xây dựng RESTful/JSON-based APIs.\n- Kinh nghiệm làm việc với các cơ sở dữ liệu:\n    - Thành thạo SQL, đặc biệt với Mssql Server, MySQL.\n    - Có hiểu biết hoặc kinh nghiệm làm việc với NoSQL databases như MongoDB.\n- Kinh nghiệm phát triển vận hành hệ thống Microservices. Có kiến thức cơ bản về Docker, Kubernetes, Jenkins...\n- Có kiến thức về caching-data (in memory-caching, Redis, etc).\n- Có kinh nghiệm làm việc và xử lý dữ liệu lớn:\n    - Thành thạo các công nghệ như kafka, elasticsearch.\n    - Biết sử dụng công cụ Airflow, NiFi, hoặc các workflow scheduler là điểm cộng.\n- Có kinh nghiệm sử dụng Python trong các pipeline xử lý dữ liệu hoặc viết automation script phục vụ backend/data tasks.\n- Từng làm việc trong lĩnh vực y tế là một lợi thế.\n- Thái độ làm việc tốt và tinh thần trách nhiệm cao.\n- Khả năng làm việc độc lập và làm việc nhóm, có thể làm việc dưới áp lực cao.\n- Có khả năng nghiên cứu, phân tích, giải quyết vấn đề và tư duy logic tốt trong lập trình.\n- Sẵn sàng học hỏi và tìm hiểu những công nghệ mới.\n\n● Phúc lợi:\n- Lương thỏa thuận theo năng lực\n- Lương tháng 13\n- Tham gia đầy đủ BHXH, BHYT, BHTN theo quy định\n- Bảo hiểm y tế tư nhân\n- 12 ngày nghỉ phép và ngày lễ theo quy định của nhà nước\n- Làm việc trong môi trường chuyên nghiệp và năng động\n\n● Thông tin khác:\n- Địa điểm làm việc: Tòa nhà An Cư Đức Phú, 3/1 Thành Thái, Phường 14, Quận 10, TP. HCM\n- Thời gian làm việc: 8h30 – 12h, 13h – 17h30 (nghỉ trưa 1 tiếng từ 12h: 00pm-01:00pm) – Thứ Hai đến Thứ Sáu\n- Liên hệ gửi CV qua email: hr@youmed.vn với tiêu đề [Họ tên] – [Vị trí ứng tuyển]\n- Zalo/Phone: 078 505 3650 (Ms.Trinh)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1562, 837, 2, 'AI Resident (Engineering)', 'Qualcomm Vietnam Company Limited, Hanoi Branch Office\n\nInterns Group, Interns Group > AI Resident\n\nQualcomm Overview\n\nQualcomm is a company of inventors that unlocked 5G ushering in an age of rapid acceleration in connectivity and new possibilities that will transform industries, create jobs, and enrich lives. But this is just the beginning. It takes inventive minds with diverse skills, backgrounds, and cultures to transform 5Gs potential into world-changing technologies and products. This is the Invention Age - and this is where you come in.\n\nGeneral Summary\n\nThe Qualcomm® AI Residency Program is a distinguished training ground for exceptional AI talent. It identifies and cultivates top young minds, shaping them into world-class AI experts and future industry leaders.\n\nQualcomm is opening applications for Engineering Residency Batch 1.\n\nAbout the Engineering Residency Program (ERP) (12 months): Residents will address practical AI engineering challenges in domains such as efficient AI, embedded engineering, and agentic AI. Engineering residents will develop robust engineering capabilities and engage in research rotations to become versatile, inquisitive AI engineers.\n\nEligibility & Qualifications\n\n- Final-year students or recent graduates in Computer Science (or cognate fields) from Vietnamese or international universities.\n- Minimum GPA: 3.2/4.0 or 8.0/10 or equivalent.\n- Strong, self-driven interest in research and ability to learn complex technical material.\n- Exceptional aptitude in mathematics and coding. Preference given to candidates with demonstrated abilities (e.g., research experience, competitions, GitHub repos, AI coursework).\n- Familiarity with Python and AI frameworks like TensorFlow, PyTorch, or Keras.\n- Competent English language skills in reading, writing, and speaking. Specialized technical English communication training will be provided.\n- Corporate internship experience is a plus.\n\nKey Responsibilities\n\n- Collaborate with cross-functional teams to design, build, and deploy AI solutions for various applications.\n- Assist in data preparation, model training, and algorithm selection under the guidance of engineer mentors.\n- Conduct experiments and tests to evaluate the performance of AI models and optimize them for production.\n- Write clean and maintainable code that supports the development and deployment of AI systems.\n- Stay updated with the latest AI trends and technologies to bring innovative ideas to the team.\n\nSelection Process\n\nThe Qualcomm AI Residency Program employs a rigorous multi-stage selection process. The standard procedure includes the following rounds:\n\n- Application\n- Screening\n- Portfolio review\n- Coding interview\n- Video presentation\n- Technical interview\n\nA fast-track application is available for academically outstanding students who have demonstrated exceptional achievements, such as winning high prizes in International Olympiads in Mathematics, Informatics, or prestigious international programming competitions like ACM-ICPC. Applicants eligible for the fast-track process will be contacted separately.\n\nATTENTION: Your application must include the following documents:\n\n- Resume\n- Academic transcript\n- Academic diploma (if already graduated)\n- A letter of recommendation is optional but strongly encouraged.\n\nPlease combine all documents into a single PDF file and upload it with your application. Incomplete applications may not be considered.\n\nFor applicants in their final year of undergraduate study, a provisional graduation certificate is acceptable in place of the diploma.\n\nApplicants: Qualcomm is an equal opportunity employer. If you are an individual with a disability and need an accommodation during the application/hiring process, rest assured that Qualcomm is committed to providing an accessible process. You may e-mail myhr.support@qualcomm.com or call Qualcomm\'s toll-free number found here. Upon request, Qualcomm will provide reasonable accommodations to support individuals with disabilities to be able participate in the hiring process. Qualcomm is also committed to making our workplace accessible for individuals with disabilities.\n\nQualcomm expects its employees to abide by all applicable policies and procedures, including but not limited to security and other requirements regarding protection of Company confidential information and other confidential and/or proprietary information, to the extent those requirements are permissible under applicable law.\n\nTo all Staffing and Recruiting Agencies: Our Careers Site is only for individuals seeking a job at Qualcomm. Staffing and recruiting agencies and individuals being represented by an agency are not authorized to use this site or to submit profiles, applications or resumes, and any such submissions will be considered unsolicited. Qualcomm does not accept unsolicited resumes or applications from agencies. Please do not forward resumes to our jobs alias, Qualcomm employees or any other company location. Qualcomm is not responsible for any fees related to unsolicited resumes/applications.\n\nIf you would like more information about this role, please contact Qualcomm Careers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1563, 674, 2, 'NODE.JS DEVELOPER LEADER', 'Mô tả công việc\n\n- Dẫn dắt, quản lý và hỗ trợ nhóm lập trình backend, đảm bảo chất lượng code.\n- Thiết kế, phát triển và tối ưu các dịch vụ backend sử dụng Node.js, Express, NestJS.\n- Quản lý và tối ưu hóa cơ sở dữ liệu SQL (MySQL, PostgreSQL) hoặc NoSQL (MongoDB, Redis).\n- Phối hợp với nhóm frontend, sản phẩm và DevOps để triển khai các tính năng mới.\n- Đảm bảo hiệu suất, bảo mật và khả năng mở rộng của hệ thống.\n- Kiểm tra, review code và hỗ trợ tuyển dụng, đào tạo thành viên mới.\n- Xử lý lỗi và tối ưu hệ thống để đảm bảo hoạt động ổn định.\n- Nghiên cứu, cập nhật công nghệ mới để nâng cao hiệu suất phát triển.\n\nYêu cầu công việc\n\nBắt Buộc\n\n- Tối thiểu 3 năm kinh nghiệm phát triển với Node.js, trong đó ít nhất 1 năm ở vị trí Leader.\n- Thành thạo xây dựng RESTful APIs, WebSockets, GraphQL.\n- Kinh nghiệm triển khai kiến trúc microservices trên các nền tảng cloud (AWS, GCP, Azure).\n- Hiểu biết về Docker, Kubernetes, CI/CD pipelines.\n- Kinh nghiệm tối ưu hiệu suất, caching, bảo mật hệ thống.\n- Kỹ năng giải quyết vấn đề và quản lý đội nhóm tốt.\n\nƯu Tiên\n\n- Kinh nghiệm làm việc với các nền tảng thương mại điện tử hoặc hệ thống có lượng truy cập cao.\n- Có hiểu biết về các framework frontend (React, Vue, Next.js) là một lợi thế.\n- Kinh nghiệm làm việc với message queue (RabbitMQ, Kafka) và kiến trúc event-driven.\n\nThời Gian Làm Việc\n\n- Văn phòng: T2-T6: 9h-17h30 (nghỉ trưa 1h30p) / T7 remote: 8h-12h\n- Remote: T2-T6: 8h30-17h30 (nghỉ trưa 1h30p) / T7: 8h-12h\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Lương: Thỏa thuận theo năng lực + thưởng theo kết quả kinh doanh.\n- Lương T13, T14, tăng lương hàng năm theo năng lực.\n- Môi trường làm việc năng động trong ngành TMĐT toàn cầu.\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định.\n- Du lịch 2 lần/năm, quà/thưởng lễ tết.\n\nCách Thức Ứng Tuyển\n\nGửi CV + Bảng điểm (scan/ảnh file pdf, jpeg, png) về email career@makezbright.com hoặc liên hệ Zalo: 0942 485 129 (Vy PSA).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1564, 909, 2, 'Back-End Engineer /Java/', 'We are Ataccama, and we are on a mission to power a better future with data. Our product enables both technical and less technical ‘data people’ across their organizations to create high-quality, governed, safe, and reusable data products. It’s what made us a Leader in the Gartner Magic Quadrant® for Data Quality Solutions™, and what inspired Bain Capital Tech Opportunities to invest in our future growth.\n\nOur vision is to be the leading AI-powered cloud data management company and to do that, we’re making Ataccama a great place to work and grow. Our people are located across the globe. They succeed by collaborating as a team and thrive in our company culture defined by these core values:\n\nChallenging Fun\n\nONE Team\n\nCustomer Centric \n\nCandid and Caring \n\nAim High \n\nOur Current Challenge\n\nAtaccama Product & Engineering is at the forefront of a transformative journey, transitioning from an on-premise enterprise solution to a fully managed multi-cloud platform. We cater to Fortune 500 companies with stringent security and compliance requirements. Simultaneously, our clients expect a user-friendly, rapidly deployable collaborative data management platform that seamlessly adapts to their organizational needs.\n\nYour Challenge\n\n• Build a truly self-service application for business users so they can work with data even without learning SQL or needing assistance from more technically-skilled colleagues. We are democratizing access to data and making it available to anyone within an organization who needs it.\n\n• Find ways to automate most activities users must do to reduce the time needed to prepare data, allowing them to actually use the data for their work, and make data-driven decisions.\n\n• Create a product that contains all the features enterprise solutions must-have, while making it super-easy to use. We want to refute the myth that enterprise software must be ugly and painful to use–it’s a lie!\n\n• Take end-to-end ownership of the whole product and not just blindly focus on coding\n\nWhat You Will Do\n\n• Understand data management and write solutions suitable for DM domains. This means designing scalable systems, ready to perform under huge amounts of data.\n\n• Cooperate on software architecture. In Ataccama, anyone can propose and drive changes in our code’s architecture and design. You’ll need to work with microservices, messaging systems, and API designs covering different parts of the system.\n\n• Solve complex problems in data management, with an emphasis on performance.\n\n• Write clean, well-designed, documented, and testable code. We expect software engineers to understand and promote industry standards and best practices.\n\n• Take responsibility for your work, from code to production. We promote ownership of our work and expect you to deliver software that’s ready to deploy and run in cloud environments.\n\n• Take part in discussions and decisions impacting how our product is designed and written.\n\n• Be a team player who collaborates both within and outside the team\n\nIs This You?\n\n• You see challenges as opportunities. You’re ready to jump in and find what works.\n\n• You’re not afraid of complex applications, and you don’t mind doing some research when engines require complex algorithms and data structures to work efficiently.\n\n• You enjoy constantly learning new things and sharing your knowledge with\n\nOur Tech Stack\n\n• Backend:Java, Spring Boot, Kotlin, GraphQL, Python,jOOQ\n\n• Big data:Spark, Redshift, Snowflake\n\n• Frontend:TypeScript, React/Vue, Apollo, Nx, MobX,Styled Components\n\n• Storage:Postgres, Elastic, Minio\n\n• Infrastructure:GitLab CI/CD, Kubernetes, AWS\n\nWork Equipment\n\n• Laptop\n\nPerks & Benefits\n\n• Full compensation during the probation period\n• 13th salary\n• 15 days of vacation\n• Premium Healthcare\n• Online company language courses\n• Conference tickets to the best industry events of the year\n• Online courses & company access to Udemy to hone your skills\n• Events like our themed New Year’s parties and summer all-staffs', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1565, 808, 2, 'Junior QA Engineer - Da Nang', 'Job Description\n\n• Participate in the requirements discovery, testing of the software product.\n• Using Waterfall model and Agile model in projects.\n• Build and execute test cases.\n• Use testing techniques such as black box testing, functional testing and regression testing\n\nRequirements\n\n• Senior college or university student.\n• Able to work full-time.\n• Careful, good logical thinking, passionate about experimenting.\n• Have a sense of responsibility, persistence.\n• Able to work under pressure, hardworking, proactive, and responsible.\n• Good communication skills\n• Proficiency in English is required, including speaking, listening, reading, and writing.\n• Having certification in testing courses is an advantage.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1566, 797, 2, 'Software Engineer C++ (Junior Welcome)', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.\n\nThe Position\n\nWe are seeking passionate and hands-on C++ Developers to join our dynamic R&D and Product Engineering team. As a member of this team, you will play a pivotal role in the development of OPSWAT’s MetaDefender product, driving innovation and excellence in software engineering.\n\nWhat You Will Be Doing\n\n- You will be responsible for designing, developing, implementing, and thoroughly testing the OPSWAT MetaDefender product using C++. Your work will primarily focus on Windows and/or Linux environments.\n- Engage in research and rapid prototyping to validate innovative solutions, ensuring our product remains at the forefront of the industry.\n- Take ownership of major product features from conception to end-to-end delivery. Collaborate closely with Product Management to understand and meet product requirements effectively.\n- Participate actively in peer code reviews, contributing to maintaining high code quality standards within the team.\n\nWhat We Need From You:\n\n- Good command of modern C++ is essential for success in this role.\n- Experience with Windows and/or Linux development\n- Demonstrated expertise in coding and debugging, ensuring the delivery of robust and error-free software.\n- Good verbal and written communication skills\n- Self-motivated individuals with a proven track record of excelling in fast-paced environments will thrive in this role.\n\nIt Would Be Nice If You Had:\n\n- Familiarity with Agile and Scrum methodologies in a collaborative working environment.\n- Experience in designing and implementing REST APIs.\n- Knowledge of DBMS systems such as SQLite, PostgreSQL, etc.\n- Excellent object-oriented design and programming skills, particularly in multi-threaded applications.\n\nOPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws.\n\nRecruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1567, 316, 2, 'Frontend Software Developer (all genders)', 'HRS reinvents how businesses Work, Stay and Pay. Counting more than 5.000 corporations and 40 % of Fortune 500 companies in our customer base, HRS has emerged to the most trusted platform of digital software solutions in business travel hospitality worldwide.\n\nThe HRS platform is composed of three engines that each optimize one core building block along the corporate hospitality supply chain: Intelligent Procurement, Smart Booking and Invisible Payment. Through the integration of those engines into one large data-driven platform approach, our Lodging-as-a-Service value proposition enhances satisfaction of corporate employees and travelers, delivers the highest grade of process automation for corporate stakeholders and ensures strongest compliance end-to-end.\n\nBUSINESS UNIT\n\nThe HRS Business Travel Club (BTC) is the Business Unit managing and developing the HRS E-Commerce platforms of the well-known hotel portal businesses of HRS.de and HOTEL.DE that gradually transform into much more than “just” a platform. BTC provides its members, individual business travelers and SMEs, with a distinct range of exclusive services, which shape tomorrow´s upgraded travel experience. The goal of BTC is to deliver growth as well as sustainable profitability over time by enhancing customer loyalty between the brand and its customers, enabling the Brands Repositioning in the marketplace and unlocking additional potentials via optimized supplier management. Thus, BTC and its products, plays an important role in HRS´s DACH strategy as it revolves around a disruption of the interplay between hotel and workplace supply and e-commerce and a domination of the Business Travel DACH market. Your mission is to further develop and shape the "The HRS Business Travel Club" and its solutions and make it the next innovation of the HRS Group together within a great team!\n\nPOSITION\n\nAs a Frontend Engineer, you will be responsible for building our next generation of scalable frontends using Next.js. You\'ll develop and maintain frontend components with a customer-centric mindset, ensuring high performance and stability to enable exclusive services for our business travel club members.\n\nCHALLENGE\n\nWork with a wide range of systems, processes and technologies to own and solve problems from end-to-end\nDesign, build, and maintain APIs, services, frontends and systems across HRS\' engineering teams\nDevelop high-quality user experiences for our business travel club members at large-scale\n\nFOR THIS EXCITING MISSION YOU ARE EQUIPPED WITH...\n\nExpertise in Next.js, React, and modern frontend architecture patterns\nStrong understanding of state management solutions, especially Redux and Context API\nExperience with CSS Modules, Styled Components, or other CSS-in-JS solutions\nProficiency with Vercel deployment, AWS Cognito with Amplify, Google Maps API integration\nKnowledge of SEO best practices and implementation within Next.js applications\nExperience with analytics platforms and implementation (Google Analytics, Mixpanel, etc.)\nUnderstanding of Node.js serverless Lambda functions for backend integration\nEnjoyment for being a frontend specialist with knowledge of serverless backend architectures\nExperience in AWS cloud engineering, as we are on a journey to cloud-native, serverless, and NoOps environment\nThe ability to thrive in a collaborative environment involving different stakeholders and subject matter experts\nPride in working on projects to successful completion involving our technology stack\nThe ability to put yourself in the shoes of users and be a steward of crafting great experiences\nEnjoyment in working with a diverse group of people with different expertise\nSkills for upholding best practices in engineering, security, and design\nFluency in English, spoken and written\n\nPERSPECTIVE\n\nAccess to a global network of a globally united and mutually responsible “Tribe of Intrapreneurs” that is passionately dedicated to renew the travel industry and while doing so reinvent the ways how businesses stay, work and pay.\n\nOur entrepreneurial driven environment of full ownership and execution focus offers you the playground to contribute to a greater mission, while growing personally and professionally throughout this unique journey. You will continuously learn from a radical culture of retrospectives and continuous improvement and actively contribute to making business life better, smarter and more sustainable.\n\nLOCATION, MOBILITY, INCENTIVE\n\nThe attractive remuneration is in line with the market and, in addition to a fixed monthly salary, all necessary work equipment and mobility, will also include an annual or multi-year bonus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1568, 880, 2, 'Freelance Software Developer (Python) - Quality Assurance (AI Trainer)', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Crafting and answering questions related to computer science in order to help train AI models to meet project-specific guidelines. \n- Evaluating and ranking code generated by AI models\n- Ensuring clarity, consistency, and factual accuracy. \n- Providing feedback to writers and working with QA Specialists to uphold quality\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You are currently enrolled in or completed a Bachelor\'s degree or higher in Computer Science or a related field\n- You have at least 3 years of professional experience with Python\n- Experience with Cloud sourcing platform is a plus\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you? \n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1569, 910, 2, 'Technical Co-Founders Wanted | Software Developers & Machine Learning Engineers', '🌟 About Antler: We are a global early-stage investment firm that invests in startups from day zero. We provide funding, mentorship, and a global network to help you build and scale your startup. With Antler, you’ll have access to the resources you need to turn your vision into reality—whether you\'re still ideating or already started building.\n\n👩‍💼 Who are we looking for? Note: This ad is not for a job, but rather for the opportunity to find your co-founder and build your own VC-backed startup through a 10-week program with Antler.\n- Startup founders, serial entrepreneurs, and strong business leaders who love building new products and teams.\n- CTOs, software architects, designers, developers, and anyone who has built and scaled products from scratch.\n- Experts in their field and excellent communicators.\n- People who are always on top of and have a genuine passion for building next-generation products.\n- Driven and hungry individuals who want to build a successful company.\n\n📋 Details of the program:\n- The program runs for an initial 10 weeks, full-time in Ho Chi Minh City (Vietnam) and starting on 21 July 2025, where you are required to ideate and find your co-founder(s) from the cohort of 60-70 founders.\n- After two months you will present your team and business idea to the Antler Investment Committee. If accepted, you will receive a pre-seed investment of $120K USD for 12% equity, non-negotiable.\n- If you get an investment, you will continue to be part of the program for another 3 months during which Antler will work closely with you to accelerate your growth. At the end of this period, Antler arranges a demo day where we invite VCs, institutional investors, and local angel investors to help you connect with investors and raise your seed round.\n\nFor more details on what to expect 👉 https://www.linkedin.com/smart-links/AQGwMqMCzPe68Q\n\nBenefits:\n- 💵 Potential investment at the pre-seed stage\n- 🤝 Help finding your co-founder(s)\n- 👨‍🏫 Personalized coaching sessions with business experts\n- 🛫 Relocation grant of $2,000 if you\'re relocating from overseas to HCMC, Vietnam\n- 🏬 Shared office space at a premium co-working space with access to various amenities\n- 🌍 Access to a global network of start-up advisors and experts in their field\n\nSome examples of successful companies that were built as a result of Antler’s program, received pre-seed investment from Antler, and gone on to raise substantial investment are:\n- Xailient - the World’s fastest Computer Vision AI\n- BUYO - Pioneering bioplastics and material tech\n- SKYQRAFT - Affordable and safe powerline inspections with drones and AI\n- Airalo - The world’s first eSIM subscription and top-up store\n- homebase - Making home ownership accessible\n- Reebelo - Circular economy for e-devices\n\nReady to help shape the future of the world? Apply now to Antler and together we will build something truly amazing ✨', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1570, 712, 2, 'Game Designer (Casual/Puzzle)', 'Được thành lập năm 2018, Sun Studio là nhà phát triển games trên nền tảng web và các thiết bị di động với hơn 1 tỷ lượt chơi. Sứ mệnh của chúng tôi là tạo ra các trò chơi mà mọi người có thể dễ dàng tiếp cận (accessible) và yêu thích (enjoyable).\n\nHiện tại công ty có gần 70 thành viên với trên 40 đầu games (dòng hyper casual, casual và puzzle) và là đối tác chiến lược của các nền tảng web-games hàng đầu thế giới như: Facebook Instant Games, Microsoft Instant Games, Crazy Games, Game Distribution, Glance Gaming...\n\nChúng tôi cần tuyển 5 bạn Game Designers (junior - mid - senior) để hỗ trợ đội ngũ phát triển game trong việc thiết kế, cải thiện các games hiện tại và tương lai.\n\nMô tả công việc\n\n- Thiết kế & Phát triển gameplay: Tìm hiểu xu hướng thị trường và đề xuất các ý tưởng gameplay mới; thiết kế và phát triển các cơ chế game, tính năng và hệ thống cho game Casual/Puzzle từ giai đoạn ý tưởng đến khi hoàn thiện\n- Thiết kế level & nội dung: Tạo ra các level, câu đố, sự kiện trong game hấp dẫn, đảm bảo độ cân bằng, nhịp độ phù hợp với đối tượng người chơi casual. Liên tục chỉnh sửa, nâng cấp nội dung dựa trên dữ liệu phản hồi để tăng tính lôi cuốn\n- Phân tích và cải thiện trải nghiệm: Phối hợp với bộ phận dữ liệu để phân tích hành vi người chơi và các chỉ số (ví dụ: tỷ lệ giữ chân, tỷ lệ hoàn thành màn chơi). Từ đó đề xuất điều chỉnh thiết kế nhằm tối ưu trải nghiệm và doanh thu\n- Cộng tác làm việc: Làm việc chặt chẽ với lập trình viên, họa sĩ, và Producer để đảm bảo ý tưởng thiết kế được hiểu đúng và triển khai hiệu quả. Tham gia các buổi đánh giá game, đóng góp ý kiến để cải thiện chất lượng sản phẩm ở mọi khía cạnh\n- Tài liệu hóa & Quy trình: Xây dựng và cập nhật đầy đủ Game Design Document và các tài liệu liên quan, đảm bảo các ý tưởng thiết kế được truyền đạt rõ ràng. Tuân thủ quy trình làm game agile, chủ động quản lý tốt thời gian và tiến độ công việc của mình\n\nKỹ năng và kinh nghiệm yêu cầu\n\n- Cần gửi portfolio để đánh giá\n- Kinh nghiệm thiết kế game: Có kinh nghiệm làm Game Designer trong ngành game (mobile hoặc PC). Tối thiểu 1-2 năm kinh nghiệm đối với cấp Junior, hoặc 3-5 năm trở lên đối với cấp Senior. Ưu tiên ứng viên từng tham gia phát triển các game Casual/Puzzle. Có khả năng để ý tới từng chi tiết nhỏ trong game\n- Tư duy thiết kế xuất sắc: Nắm vững nguyên lý thiết kế game, có khả năng cân bằng game (độ khó, phần thưởng, kinh tế trong game) và thấu hiểu tâm lý người chơi\n- Kỹ năng phân tích: Tư duy dữ liệu tốt, biết sử dụng số liệu và phản hồi người chơi để tinh chỉnh thiết kế. (Ví dụ: hiểu các KPIs như DAU, Retention, ARPU và cách thiết kế ảnh hưởng đến những chỉ số này). Thành thạo các công cụ như GA4 hoặc các hệ thống BI tương đương\n- Thành thạo công cụ: Sử dụng thành thạo các công cụ phục vụ thiết kế game: ví dụ như Unity (hoặc các game engine tương tự), công cụ thiết kế level, bảng tính Excel/Google Sheets (để lên thông số, cân bằng game)\n- Giao tiếp & Làm việc nhóm: Kỹ năng giao tiếp tốt, có thể trình bày ý tưởng mạch lạc và biết lắng nghe phản hồi. Kinh nghiệm làm việc trong nhóm đa chức năng; thái độ chuyên nghiệp, cầu tiến và sẵn sàng thích nghi với quy trình làm việc linh hoạt (Agile)\n- Ưu tiên: Ứng viên có kinh nghiệm thiết kế các tính năng free-to-play (ví dụ: hệ thống tiền tệ, cửa hàng, sự kiện live-ops) hoặc từng phát hành thành công ít nhất một game Casual/Puzzle\n- Khả năng giao tiếp bằng tiếng Anh tốt là một lợi thế\n\nQuy trình tuyển dụng\n\n- Đánh giá Portfolio và CV\n- Video call phỏng vấn với Chuyên viên tuyển dụng (30-45 phút)\n- Phỏng vấn tại văn phòng với Trưởng nhóm (45-60 phút)\n\nChế độ đãi ngộ \n\n- Lương và giờ làm việc\n- Lương cho vị trí: hấp dẫn\n- Vị trí này sẽ làm việc tại văn phòng. Thời gian làm việc từ 9:00 - 18:30, từ thứ 2 đến thứ 6\n- Bảo hiểm và chế độ thưởng\n- Được tham gia đầy đủ BHXH/ BHYT/ BHTN theo quy định của luật lao động\n- Ngoài ra bạn sẽ được tham gia bảo hiểm sức khỏe riêng PVI\n- Phụ cấp ăn trưa hàng tháng\n- Thưởng cố định lương tháng 13\n- Thưởng cuối năm không giới hạn, tùy thuộc vào doanh thu của công ty và mức độ đóng góp của bạn trong các dự án\n- Cân bằng cuộc sống & công việc\n- Ngoài những ngày nghỉ lễ theo quy định của nhà nước, chúng tôi có thêm rất nhiều ngày nghỉ được trả lương và nghỉ ốm\n- Nơi làm việc thoải mái\n- Tại văn phòng, chúng tôi có khu vực giải trí, cung cấp đồ ăn phụ và đồ uống miễn phí để giúp bạn làm việc thoải mái và cân bằng\n- Góc Thư viện sách cho các bạn thích đọc sách giấy\n- Phát triển chuyên môn và giáo dục\n- Chúng tôi hoàn trả chi phí cho việc tham gia vào các hội nghị và khóa học có liên quan, đồng thời thường xuyên tổ chức các chương trình đào tạo nâng cao nghiệp vụ\n- Công ty có chính sách hỗ trợ việc thăng tiến và phát triển sự nghiệp của nhân viên\n- Giải trí và gắn kết\n- Hàng tuần / tháng / năm, chúng tôi tổ chức nhiều sự kiện, bao gồm các cuộc thi, thử thách thể thao, tiệc, happy hours, team building, hackathons và sự kiện ngoại tuyến dành cho từng đội\n- Dự án trách nhiệm xã hội\n- Chúng tôi tiếp tục triển khai các dự án từ thiện và hỗ trợ ý tưởng của nhân viên trong các cuộc thi tài trợ', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1571, 715, 2, 'Kỹ sư Phát triển phần mềm', 'Company Description\nViettel High Technology Industries Corporation (VHT) was established in 2011 as the ninth corporation of the Viettel Group, focusing on the high-tech industry in Vietnam. Specializing in equipment, tactical electronics services, and capabilities in the defense industry and telecommunication products, VHT is dedicated to innovative solutions that ensure safety. VHT aims to become a global organization with a unified vision of innovation.\n\nRole Description\nThis is a full-time on-site role for a Kỹ sư Phát triển phần mềm located in the Hanoi Capital Region. The Software Development Engineer will be responsible for designing, developing, and maintaining software applications. Daily tasks will include coding, debugging, testing, and collaboration with cross-functional teams to enhance software performance and user experience.\n\nQualifications\n- Proficiency in software development, coding, and debugging skills\n- Experience with software testing and quality assurance\n- Strong problem-solving and analytical skills\n- Ability to work collaboratively with cross-functional teams\n- Excellent written and verbal communication skills\n- Familiarity with telecommunication products and defense industry software is a plus\n- Bachelor\'s degree in Computer Science, Software Engineering, or a related field', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1572, 911, 2, 'AI Developer', '★ Mô Tả Công Việc\n\n• Phát triển và triển khai chatbot có khả năng tìm kiếm thông tin và tạo ra nội dung từ các mô hình ngôn ngữ lớn.\n\n• Tích hợp các mô hình AI vào ứng dụng di động (Android/iOS).\n• Thiết kế và tối ưu hóa pipeline xử lý dữ liệu cho chatbot và các tính năng AI khác.\n• Phân tích và cải thiện hiệu suất của hệ thống chatbot cũng như các hệ thống tích hợp mô hình AI khác.\n• Cập nhật và triển khai các công nghệ mới nhất trong AI và Machine Learning vào dự án.\n• Phối hợp để đảm bảo sự tương thích và hiệu suất của các mô hình AI.\n\n★ Yêu Cầu\n\n• Hiểu khái niệm cơ bản về các mô hình Generative AI như GANs, VAEs, và mô hình Diffusion.\n• Hiểu cơ bản về các công cụ lưu trữ và quản lý dữ liệu như cơ sở dữ liệu SQL/NoSQL và lưu trữ đám mây.\n• Có kiến thức về việc sử dụng các nền tảng AI cloud như AWS, Azure, Google Cloud.\n• Hiểu các cấu trúc dữ liệu cơ bản như mảng, danh sách liên kết.\n• Nắm các thuật toán cơ bản như sắp xếp (Bubble Sort, Insertion Sort), tìm kiếm tuần tự.\n• Hiểu biết về các mô hình phát triển phần mềm cơ bản như Waterfall, Agile.\n• Áp dụng các mô hình có sẵn từ các thư viện để giải quyết vấn đề cụ thể.\n• Sử dụng các mô hình AI có sẵn từ thư viện và triển khai vào môi trường thử nghiệm đơn giản.\n• Fine-tune các mô hình đơn giản cho các ứng dụng cụ thể (ví dụ: điều chỉnh mô hình GPT-3 cho bài toán cụ thể).\n• Xác định và sửa lỗi đơn giản trong mã nguồn với sự hướng dẫn.\n• Sử dụng các kỹ thuật debug cơ bản để tìm nguyên nhân vấn đề.\n• Biết cách sử dụng GitHub để quản lý mã nguồn, tạo pull request, merge code và cơ bản về workflow CI/CD với Jenkins.\n• Làm việc được với Docker ở cấp độ cơ bản (Ví dụ: build, push, run).\n• Có khả năng tham gia thảo luận nhóm, lắng nghe và đưa ra ý kiến cơ bản.\n• Đảm bảo hoàn thành công việc được giao đúng hạn với sự hướng dẫn từ người khác.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Châu district, Đà Nẵng, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1573, 676, 2, 'COBOL Developer (Fresher)', 'Overview:\nAre you female students eager to dive into the tech world?\nOur COBOL DECP Program (DXC Early Career Professional) is designed for talented, passionate female graduates who are looking to join an agile world leader and are ready to use the power of technology to deliver mission-critical IT services that move the world. Our customers entrust us to deliver what matters most.\nWe believe every graduate is unique and our aim is to help you build a solid foundation in your professional career, apply your learnings, and discover new possibilities.\n\nRequirements:\n- Fresh graduates in Computer Science, Information Technology, Software Engineering or related technical field.\n- Has knowledge about COBOL is a plus.\n- Good English communication skills.\n- Has knowledge or relevant work experience in any of the following programming languages or technologies: Java, .NET, C#, System, window server, …\n- Ability to learn in a short time and work under pressure.\n- Experience working in an international software development project will be advantageous.\n- Good analytical and communication skills.\n- Be able to work independently and in a workgroup.\n\nBenefits:\n- Competitive salary.\n- 1-on-1 mentorship throughout the Fresher program.\n- Comprehensive training with a professional curriculum.\n- Hands-on experience working on real projects.\n- High potential to become a full-time employee upon completion of the training program.\n- Dynamic and youthful work environment with plenty of growth opportunities.\n- Free DXC Learning Account (partner with Udemy and LinkedIn).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1574, 742, 2, 'Fresher Automation Test Engineer (QA/QC/Tester)', 'Company Description\n\nKMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines:\n\nKMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions.\nKMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality.\nKMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors.\n\nJob Description\n\nYour key responsibilities:\n\nDevelop a strong understanding of domain knowledge and client testing processes to execute testing activities effectively.\nWork closely with the project team on daily tasks and participate in sprint demo meetings with clients.\nDevelop, maintain and execute automated test scripts.\nIdentify, report, track, and monitor defects using the defect tracking system.\nPrepare and review test documentation to ensure accuracy and completeness.\nAddress issues related to testing quality and suggest improvements.\nCommunicate test progress, results, and quality risks both internally and directly with the client.\n\nYour key qualifications:\n\nGeneral requirements:\n\n4th-year student or recent graduate with a Bachelor\'s degree in Information Technology, Computer Science, Software Engineering, or a related field, with less than one (01) year of experience.\nStrong IT background with a GPA of 7.5+ (Please attach transcripts when submitting your CV).\nUpper-intermediate or higher English proficiency (both written and verbal).\nMinimum 3-month internship experience in software testing, automation testing, or a related field is a plus.\nStrong self-learning ability with a proactive, growth-oriented mindset.\nExcellent analytical and problem-solving skills.\nAbility to work independently and collaborate effectively in a team.\n\nTechnical requirements:\n\nSolid understanding of software testing concepts and methodologies, including manual, automation, integration, unit, and API testing.\nSolid programming skills in Python / Java / JavaScript, or other relevant languages.\nFamiliarity with testing tools (e.g., Katalon, Playwright, Selenium, Appium, JUnit), as well as tools for API testing (e.g., Postman), is a plus.\n\nAdditional Information\n\nBE YOUR BEST WITH KMS\n\nWorking in one of the Best Places to Work in Vietnam\nBuilding large-scale & global software products\nWorking & growing with Passionate & Talented Team\nDiverse careers opportunities with Software Outsourcing, Software Product Development, IT Solutions & Consulting\nAttractive Salary and Benefits\nPerformance appraisal twice a year and performance bonus\nOnsite opportunities: short-term and long-term assignments in North American (U.S, Canada), Europe, Asia.\nFlexible working time\nVarious training on hot-trend technologies, best practices, and soft skills\nPremium healthcare insurance for you and your loved ones\nCompany trip, big annual year-end party every year, team building,...\nFitness & sports activities: football, tennis, table tennis, badminton, yoga,...\nJoining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,.. \nFree in-house entertainment facilities (foosball, ping pong, gym,...), coffee (latte, cappuccino, espresso,...) and snack (instant noodles, cookies, candies,..)\nAnd much more...Send your Resume including Academic Transcript to join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1575, 912, 2, 'Backend Developer', 'CAREERS\n\nWork With Us\n\nExplore exciting career opportunities and become part of our dynamic team.\n\nBACKEND DEVELOPER\n\nQuantity: 02\n\nWorking Hours: 08:00 – 12:00, 13:30 – 17:30, Monday to Friday\n\nWork Location: Lot 05 – Lot 06, Area A2, Phuong Trang High-Rise Commercial Urban Complex, Nguyen Sinh Sac Street, Hoa Minh Ward, Lien Chieu District, Da Nang, Vietnam\n\nResponsibilities\n\nGeneral Responsibilities:\n\n- Commit to contributing personal value toward the company’s and department’s common goals.\n- Commit to achieving personal objectives as set.\n\nKey Job Responsibilities\n\n- Develop and maintain backend systems for the company’s products.\n- Analyze project requirements and design database structures accordingly.\n- Build and optimize APIs based on project specifications.\n- Write technical documentation, including API documentation, and collaborate with relevant teams for implementation.\n- Work closely with cross-functional teams (e.g., Frontend, QA, Product) to ensure backend systems meet business and technical requirements.\n- Debug and troubleshoot issues in backend systems to ensure high performance and reliability.\n- Stay updated on industry best practices and integrate new technologies to improve backend systems.\n- Perform other tasks as assigned by the Board of Directors or department leaders.\n\nRequirements\n\nMinimum Qualifications:\n\n- Experience: At least 2 years of experience in Backend Development.\n- Education: A college/university degree or equivalent in Information Technology, Computer Science, or related fields.\n- Programming Skills: Proficiency in at least one backend programming language: Python, PHP, or Node.js.\n- Core Knowledge:\n  - Strong foundation in OOP, algorithms, data structures, and design patterns.\n  - Experience working with databases such as AWS Redshift, MySQL, or PostgreSQL.\n  - Strong debugging skills and familiarity with writing unit tests.\n  - Understanding of system security and best practices for securing backend systems.\n- Tools & Workflow:\n  - Hands-on experience with source code management tools (e.g., Git).\n  - Familiarity with CI/CD workflows and tools.\n- Soft Skills:\n  - Strong logical thinking and analytical skills.\n  - Ability to work both independently and collaboratively within a team.\n  - A proactive attitude, professionalism, and a sense of responsibility.\n\nPreferred Qualifications (Nice-to-Have)\n\n- Experience in product-oriented projects, especially in Affiliate Marketing or SaaS platforms.\n- Proven ability to design and maintain microservices architectures.\n- Experience in deploying and maintaining systems with a large user base.\n- Familiarity with Agile/Scrum software development methodologies.\n- Experience integrating multiple data sources into a unified system.\n- Knowledge of AWS services and cloud-based deployments.\n\nBenefits\n\n- Salary: 15,000,000 VND – 35,000,000 VND (based on experience and performance).\n- Performance Reviews: Salary adjustments every 6 months based on demonstrated capability.\n- Equipment: Fully equipped with necessary working devices (e.g., MacBook).\n- Probation Period: Receive 85% of the official salary during the probation period.\n- Bonuses: 13th-month salary and additional holiday bonuses throughout the year.\n- Health Check-Ups: Annual check-ups at top-tier hospitals.\n- Insurance: Full compliance with Vietnamese labor laws regarding social insurance and welfare benefits.\n- Leave: 12 annual leave days and all Vietnamese public holidays.\n- Allowances: Travel and lunch allowances, plus access to free drinks and coffee at the office’s mini bar.\n- Environment: Work in a supportive and dynamic environment with talented and friendly colleagues.\n\nHow To Apply\n\nSubmit your CV via email to: tuyendung@permate.com\n\nSubject Line: Application for Backend Developer Position – [Your Name]', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1576, 764, 2, 'Jr.~Sr. PHP Developer (Laravel)', 'MÔ TẢ CÔNG VIỆC\n- Kiến trúc và phát triển hệ thống thương mại điện tử toàn cầu trên nền Web và Mobile, multi-domain, multi-languages với lượng traffic dữ liệu cực lớn. Lập trình mảng micro service.\n- Có cơ hội đảm trách tất cả các kỹ năng cần có của full-stack developer từ xây dựng yêu cầu đến release và vận hành hệ thống trên môi trường thực theo tiêu chuẩn Nhật Bản về qui trình và chất lượng.\n- Dự án product nên có cơ hội đề xuất và hiện thực những ý tưởng hay, hợp lý và hiệu quả nhằm hoàn thiện sản phẩm.\n\nYÊU CẦU\n- >= 1 năm kinh nghiệm phân tích, thiết kế hệ thống.\n- Junior >= 2 năm kinh nghiệm lập trình PHP (Laravel) hoặc Framework tương tự.\n- Senior >= 3 năm kinh nghiệm lập trình PHP (Lavarel) hoặc Framework tương tự ( trong đó >= 2 năm làm về Web EC).\n- Có kinh nghiệm chuyên sâu trong HTML/HTML5, CSS/CSS 3, JavaScript, JQuery, Ajax.\n- Có hiểu biết chuyên sâu về Apache server, Database MySQL, Linux server, Network, and Security.\n\nPHÚC LỢI\n- Bonus tháng 13.\n- Đánh giá lương: 1-2 lần/năm.\n- Tổng số ngày nghỉ phép hưởng lương hàng năm 17 ngày (bao gồm 5 ngày nghỉ hè: chế độ đặc biệt chỉ có ở Rivercrane).\n- Gói bảo hiểm sức khỏe đặc biệt 2,5 ~ 3,5 triệu/ nhân viên/ năm.\n- Cơ hội được công ty đài thọ toàn phần đi onsite tại Nhật Bản trong 3 tháng.\n- Company Trip hàng năm.\n- Câu lạc bộ thể thao (bóng đá, bóng bàn, bi lắc, game online,…).\n- Được training và giao cơ hội thực hiện các kỹ năng để trở thành cấp quản lý cấp cao.\n- Chế độ chu cấp kinh phí (300$ ~ 1000$/người) tham gia các lớp nâng cao kiến thức kĩ thuật, softskill tại các trung tâm đào tạo uy tín.\n- Ngày hội toàn thể nhân viên và gia đình vào tháng 7 hàng năm.\n- Thứ 6 hàng tuần từ 14:30 trở đi là giờ tự nghiên cứu để nâng cao kiến thức.\n- Bảo hiểm bắt buộc được đóng trên lương gross.\n- Công ty đào tạo tiếng Nhật miễn phí, làm việc lâu dài tại Tokyo Nhật Bản.\n\nĐịa điểm làm việc:\n- Toà nhà Havana, 132 Hàm Nghi, P.Bến Thành, Q.1\n- Toà nhà EBM, 685 Điện Biên Phủ, Q.Bình Thạnh.\n\nThời gian làm việc:\n- T2-T6, 8h-17h (nghỉ trưa 1 tiếng).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1577, 894, 2, 'Fullstack Developer', 'ABOUT US\n\nBaller Headwear is a caps manufacturer servicing foreign brands. We are currently looking for a Fullstack Developer with 1+ year of experience and strong English skills to join our team. You will help us develop and maintain internal web applications that support our daily operations. This is a great opportunity to grow with a fast-moving company and contribute directly to real business needs.\n\nWHAT WILL YOU INVOLVE\n- Develop user interfaces with React / Next.js.\n- Build backend APIs using Node.js / NestJS.\n- Integrate with databases (PostgreSQL / MongoDB / Supabase).\n- Integrate core accounting and finance modules into our ERP ecosystem.\n- Deploy and manage cloud-based applications using Google Cloud Platform (GCP) services.\n- Collaborate with UI/UX designers, testers, and product owners to ensure end-to-end integration.\n- Write clean, maintainable, and scalable code.\n- Maintain Git repositories, follow Gitflow processes, and participate in CI/CD pipelines.\n- Bachelor’s degree in Information Technology, Computer Science, or a related field.\n\nWHAT WE NEED YOU HAVE\n- 1+ year of hands-on experience in fullstack development.\n- Strong understanding of TypeScript.\n- Experience with ReactJS, basic knowledge of Next.js (SSR/ISR is a plus).\n- Basic experience building APIs with Node.js, preferably NestJS.\n- Familiar with RESTful APIs, HTTP, JWT, and backend concepts.\n- Experience working on production-level applications.\n- Solid experience working with relational databases (PostgreSQL, MongoDB, Redis is a plus)\n- Good logical thinking and ability to learn quickly.\n- Fluent in English (both written and spoken).\n\nWHAT WE OFFER YOU\n- Salary: Negotiable based on experience.\n- One-month probationary period.\n- Work MacBook provided.\n- High social insurance contribution.\n- 13th-month salary bonus.\n- Meal provided at the workplace.\n- 12 days of annual and public holiday leave.\n- Team-building activities, weekly tea breaks, and internal events.\n- A professional working environment with opportunities to use and improve English skills.\n\nWORKING TIME\n- Monday to Saturday: 7:30 AM - 4:30 PM.\n- Half-day off on Saturday.\n\n~~~ We look forward to meeting you in the interview and learning more about your aspirations! ~~\n\nBALLER HEADWEAR VIETNAM CO., LTD\nAddress: No. 08 Street, Hoa Khanh Industrial Park, Hoa Khanh Bac Ward, Lien Chieu District, Danang City, Vietnam\nMobile: 0862 030 373\nEmail: hiring@ballerheadwear.com\nWebsite: ballerheadwear.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1578, 411, 2, 'System Engineer', 'Install and configure services based on team requirements.\n\nDeploy and manage infrastructure across cloud environments with guidance.\nBuild and maintain CI/CD pipelines for efficient deployments.\nSet up monitoring, logging, and alerting systems to track system health.\nMonitor performance, troubleshoot issues, and respond to incidents with team support.\nAutomate routine tasks such as backups and system checks.\nWork with cloud services and databases to support application needs.\nCollaborate with the team to improve system security and performance.\n\nRequirement\n\nMin 2 years of experience in system administration (e.g., Linux, server management).\nFamiliarity with cloud platforms (e.g., AWS, GCP).\nSolid experience with Linux system administration and troubleshooting.\nProficiency in scripting languages (e.g., Bash, Python) for automation.\nHands-on experience with configuration management or IaC tools (e.g., Ansible, Terraform).\nBasic knowledge of containerization technologies (e.g., Docker, Kubernetes).\nFamiliarity with CI/CD pipeline tools (e.g., GitLab CI/CD, ArgoCD).\nExposure to monitoring and logging tools (e.g., Prometheus, Grafana, ELK).\nExperience installing or managing databases (e.g., Couchbase, MySQL).\nUnderstanding of basic networking concepts.\nStrong problem-solving skills and a teamwork-oriented, eager-to-learn mindset.\n\nNice to Have: Experience with advanced cloud features (e.g., load balancing, CDN).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1579, 707, 2, 'Manual QC Engineer (Junior/Middle)', 'Job Description\n\n- Working directly with the client, develop team: Weekly status report, discuss / clear requirement with Product Owner, Develop team\n- Creating and maintaining test cases\n- Executing test cases\n- Reporting and verifying issues\n\nJob Requirements\n\nMUST HAVE\n\n- At least 2 years of experience in manual testing\n- Having solid knowledge of test case design techniques and testing strategies\n- Experience with test case management tools: Zephyr, Qase\n- Experience with API testing\n- Good at English communication\n\nNICE TO HAVE\n\n- Experience API test with Postman scripts\n\nBenefits\n\nCompetitive Salary and Brilliant Health Benefits\n\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan \n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program \n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support. \n- Surrounded with friendly, open-minded, young and supportive colleagues \n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1580, 913, 2, 'Java Software Engineer', 'About the Company\n\nDXC Technology (NYSE: DXC) helps global companies run their mission-critical systems and operations while modernizing IT, optimizing data architectures, and ensuring security and scalability across public, private and hybrid clouds. The world\'s largest companies and public sector organizations trust DXC to deploy services to drive new levels of performance, competitiveness, and customer experience across their IT estates. Learn more about how we deliver excellence for our customers and colleagues at DXC.com.\n\nAbout the Role\n\nAyou will collaborate proactively with functional analysts to translate business and integration requirements into configurable application designs and solutions using Java / Java 2 EE technologies. The senior will have application maintenance ownership, and the ability to work effectively with other technologies and account teams. Your primary responsibility will be to design and develop these applications, and to coordinate with the rest of the team working on different layers of the infrastructure.\n\nResponsibilities:\n\n- Drive and coordinate the technical life cycle of Java web applications across architecture, design, coding, testing, QA, and production support.\n- Participate in and contribute to the design and technical architecture of Java web applications including the creation of detailed architectural specifications.\n- Collaborate with other developers and quality assurance engineers to deliver high quality products.\n- Develop a cooperative environment that fosters knowledge sharing and technical growth.\n- Provide technical guidance and mentoring to the development team.\n- Interview external resources for the project when necessary.\n- Directly report to PM and/or client.\n\nQualifications:\n\n- Bachelor’s degree in Computer Science\n- English certification if have\n- Japanese certificate if have\n\nRequired Skills:\n\nFrom 1 year to 7 years of experience in Java programming.\n- Have knowledge of Core Java, Servlet/JSP, JDBC, Webservice RESTful / SOAP, Hibernate, Spring, Spring MVC, Spring Boot, Microservices, Oracle, MSSQL and understanding of OOP.\n- Can communicate Japanese, level N3 and above\n- Can communicate English from level INT and above\n\nPay range and compensation package:\n\nCompetitive salary\n\nEqual Opportunity Statement:\n\nDynamic, Friendly, Supportive and Professional working environment with a solid and talented team behind you – great people who love to support each other.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1581, 326, 2, 'Senior Java Engineer', 'YOUR NEW ROLE CODE LEAP  We are looking for Java Engineer to join our expert team in Ho Chi Minh City. This role is perfect for team players with a strong interest in developing their international career - not just as a coder, but as a product builder.\n\nYOUR EXCITING TASKS\n- Maintain and migrate Java-based applications using Java into AWS cloud based\n- Work with cloud technologies, specifically AWS, to deploy and scale applications\n- Work with cross-functional team members: PM, project lead, engineers..\n- Optimize application performance and troubleshoot any issues\n- Write unit tests and ensure code quality through code reviews\n- Participate in Agile development processes and sprint planning\n\nYOUR PROFILE AND YOUR PERSONALITY\n- Bachelor\'s degree in Computer Science, Engineering, or related field (or equivalent experience)\n- At least 3 years of hands-on experience in Java development, including proficiency with Spring Boot\n- Have experience with AWS services (e.g., EC2, S3, RDS, Lambda)\n- Familiarity with RESTful APIs\n- Experience with version control systems, such as Git\n- Solid understanding of database design and SQL\n- Strong problem-solving skills and attention to detail\n- Ability to work collaboratively in a fast-paced, Agile environment\n- A team player, proactive, detailed oriented approach to drive projects and make them happen\n- Open to discussion, learning, sharing and feel comfortable to bring ideas\n- Excellent communication skills in English\n- Nice to have:\n  - Familiarity with tools like Docker, Kubernetes, and CI/CD pipelines\n  - AWS certification or similar cloud certifications\n\nBenefits Await You At Code Leap\n- Competitive salary and beneﬁts\n- Year-end bonus (13th-month salary)\n- Generous annual leave of up to 18 days\n- Enjoy a stress-free and comfortable commute to and from work with our Grab Services sponsor\n- Enjoy an endless selection of delicious refreshments, including gourmet coffee, beverages, snacks, and fresh fruits, all complimentary\n- Focused on individual development:\n  - Unlimited access to Udemy and other recommendation courses\n  - Sponsored Professional certificates such as Oracle Certified Professional Java Programmer (OCAJP, OCPJP), etc\n  - Sharing session every Friday, come along with lunch provided by CODE LEAP\n  - 1-on-1 coaching with experienced professionals\n- Flexible work policy, which provides flexible hours to accommodate personal schedules and commitments\n- Dynamic, fun, and agile environment, perfect for sharing and creativity\n- Open-minded, kind & humble colleagues\n\nCONTACT\nInterested? Let’s talk!\nPlease reach out and contact us now with your latest CV as well as a little description about yourself at jobs@codeleap.de\n\nAbout Us\nWith our expert teams spread across two continents, CODE LEAP provides innovative software solutions for venture-backed companies and leading enterprise businesses in Germany. Our teams in Germany and Ho Chi Minh City (Vietnam) work hand in hand to develop state-of-the-art solutions of the highest quality.\n\nBecause collaborating with the right people is the secret to our successful growth.\n\nWe future-proof organizations - be part of it!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1582, 439, 2, 'Software Engineer', 'Chức danh công việc: Kỹ sư lập trình phần mềm AI/ML \nBộ phận: Khối nghiên cứu và phát triển. \nMô tả công việc: \nChúng tôi đang tìm kiếm Kỹ sư Lập trình phần mềm Full-stack có nền tảng về AI/Machine Learning đam mê công nghệ, có tư duy sản phẩm, để tham gia xây dựng các sản phẩm tài chính thông minh, phục vụ lĩnh vực hoạt động đầu tư, giao dịch và phân tích dữ liệu tại công ty chứng khoán. \nBạn sẽ: \nTham gia phát triển các ứng dụng web và hệ thống backend tích hợp trí tuệ nhân tạo (AI), AI Agent, ML, … nhằm xây dựng các bài toán ứng dụng trong hoạt động Kinh doanh/Chứng Khoán/Ngân hàng. \nHợp tác chặt chẽ với đội ngũ Data Scientist để đưa các mô hình học máy (ML) vào hệ thống sản phẩm, từ thử nghiệm đến triển khai thực tế. \nTham gia vào các công đoạn triển khai dịch vụ: Kiến trúc hệ thống, thiết kế mô hình hoạt động, luồng hoạt động, chức năng, tối ưu performance luồng dữ liệu phục vụ các mô hình AI real-time. \nNghiên cứu, tìm hiểu các công nghệ mới nhất về AI, ML, DL. \nYêu cầu: \nCó từ 3+ năm kinh nghiệm lập trình Web, Java backend (Spring Boot), Python \nCó kiến thức nền tảng về Machine Learning / AI (đã học qua hoặc từng áp dụng vào dự án thực tế). \nHiểu biết về thiết kế hệ thống backend: REST API, cơ sở dữ liệu (PostgreSQL, MySQL). \nTư duy logic tốt, yêu thích công nghệ mới và có định hướng phát triển lâu dài trong lĩnh vực AI tài chính. \nƯu tiên: \nĐã từng làm việc trong lĩnh vực fintech, ngân hàng, chứng khoán hoặc startup AI. \nCó hiểu biết hoặc kinh nghiệm triển khai AI Agent, AI workflow: từ training model đến deployment (ML pipeline, inference service). \nĐã làm việc với các thư viện ML phổ biến: scikit-learn, TensorFlow, PyTorch hoặc framework như LangChain, DeepSeek, HuggingFace. \nCó làm quen với các Automation Workflow như: n8n,.. \nQuyền lợi: \nLàm việc tại TCBS công ty tài chính hàng đầu với định hướng số hóa và AI hóa các sản phẩm đầu tư. \nThu nhập cạnh tranh, thưởng hấp dẫn. \nCơ hội học hỏi từ các chuyên gia trong lĩnh vực tài chính, AI và Data Science. \nTham gia các dự án quy mô lớn, hệ thống phục vụ real-time với hàng chục nghìn user. \nMôi trường cởi mở, sáng tạo, khuyến khích học hỏi công nghệ mới và thử nghiệm ý tưởng AI vào sản phẩm thật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi i okolice', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1583, 702, 2, 'Java Engineer - Trading Tech', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nJoin the Exchange Service department at Binance, the world\'s leading cryptocurrency exchange serving over 250M+ registered users across 100+ countries. As dedicated software engineers, we are responsible for developing and maintaining the core trading platform, ensuring seamless and efficient operations. Our work solidifies Binance as the preferred choice for crypto enthusiasts worldwide.\n\nOur Margin Technology team is looking for a talented Java Engineer to join the team to work on greenfield projects related to margin trading. Be part of a forward-thinking team where your skills will drive innovation and make a significant impact.\n\nResponsibilities\n\nCollaborate with the cross-functional team with the development of new applications across crypto-related products, including but not limited to crypto exchange, fiat gateway, futures, margin, lending, etc.\nParticipate in the applications with different stages, covering POC, MVP, and launched product, hence, this role would face several types of jobs, such as requirement evaluation, workable solutions delivery, architecture design/implementation.\nPerform performance tuning, online incidents troubleshooting, improve system sustainability and maintainability, and technology innovation.\nEnsure coding quality on the core functions.\n\nRequirements\n\nBachelor\'s/Master\'s degree in Computer Science, Engineering or a related field.\nExperienced with financial and/or trading systems.\nExpertise in core Java and familiarity with the Spring framework ecosystem.\nStrong proficiency in MySQL and working knowledge of Redis.\nSkilled in distributed system design with an understanding of Kafka and its underlying principles.\nAbility to thrive under pressure and quickly acquire new knowledge.\nExcellent cross-team communication skills.\n\nWhy Binance\n\nShape the future with the world’s leading blockchain ecosystem\nCollaborate with world-class talent in a user-centric global organization with a flat structure\nTackle unique, fast-paced projects with autonomy in an innovative environment\nThrive in a results-driven workplace with opportunities for career growth and continuous learning\nCompetitive salary and company benefits\nWork-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1584, 914, 2, 'Software Engineer (Retail Media Integration)', 'Epsilo in a nutshell\n\nWe develop a closed-loop platform empowering brands and agencies to stay on top of the market trends, monitor digital shelf, automate campaigns, and leverage operational insights for digital commerce growth.\nOur platform serves a varied client including leaders, operators, and scientists in media, marketing, and e-commerce teams across brands, digital agencies, e-commerce enablers, and marketplaces, facilitating efficient revenue generation on Retail Media Network, a $100B category that will dominate the digital advertising for a decade.\nWe earn a track record of facilitating over $3 billion in GMV, optimizing more than $200 million in media spend, and catering to clients in over 10 countries worldwide.\nRecognized in Gartner\'s Market Guide for Digital Shelf Analytics alongside 15 other leading global SaaS companies from the US, Europe, and India.\nOur aspiration is to develop a Positional Software that simply change the way that advertisers gather insights and make decisions. A combination of Notion and The Trade Desk.\nBacked by “Surge by Peak XV Partner”.\n\nTasks\n\nWe are seeking a highly skilled Software Engineer to join our team and take ownership of the integration between our platform and retail media channels. The ideal candidate will have a strong background in software development, with expertise in building robust and scalable integrations that connect disparate systems and data sources.\nDesign, develop, and maintain integrations between Epsilo’s platform and various retail media channels, such as e-commerce platforms, advertising networks, and data providers.\nCollaborate with cross-functional teams, including Product Management, Sales, and Customer Success, to understand integration requirements and prioritize development efforts.\nArchitect scalable and resilient integration solutions that ensure seamless data exchange and real-time communication between Epsilo’s platform and external systems.\nImplement best practices for data synchronization, transformation, and validation to ensure data integrity and accuracy across integrated systems.\nMonitor integration performance and troubleshoot issues as they arise, working closely with internal teams and external partners to resolve technical challenges in a timely manner.\n\nRequirements\n\nMore than 4 years of experience working with Java or Python\nHave worked on at least 3 years in bank, e-commerce, logistics domain, is an advantage\nHaving experience in charge of Frontend: Basic (HTML, Javascript, jQuery)\nProficient in using database management systems (MySQL, SingleStore, ElasticSearch, Apache Ignite,…)\nExperience with data Processing: Apache Kafka, Apache Flink,…\nGood problem-solving skills and business logic thinking\nExperience working in groups (3-5 people)\n\nBenefits\n\n14 days annual leave per year, allowing ample time to rest and recharge\nComprehensive PVI insurance coverage after passing probation\nComplimentary lunch & parking for convenience\nTeam bonding activities with a budget of $20 per person per month\nExciting company trip annually to foster team spirit\nState-of-the-art company laptop provided for your professional use\n\nTechnical Skills Assessment: Candidates will receive an assessment via email, which must be completed within the specified timeframe.\nFirst Interview: This interview will be conducted by Manager, and will focus on evaluating your technical expertise and problem-solving abilities.\nSecond Interview: Conducted by CEO, this interview will involve an in-depth discussion of your past project experiences and future professional aspirations.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1585, 915, 2, '(ReactJS/NodeJS) Full Stack Developer', 'Your responsibilities:\n-Design, developing new programs, products, or features by analyzing the raw requirement.\n-Collaborating with the back-end developers and other team members to establish objectives and design more functional, cohesive codes to enhance the user experience.\nThe ideal candidate:\n-Bachelor’s degree or higher in Computer Science, Information Technology or equivalent\n-At least 3-year experience with the following areas: NodeJS, Expressor PHP...\n-At least 3-year experience with Javascript SPA lib/framework: Vue, React, Angular\n-Solid understandingand experience withdatabase MySQL, PostgreSQL, Mongo DB\n-Strong experience with RESTful API, JavaScript, HTML, Bootstrap.\n-Strong experience with Git and knowledge of Linux-Have basic knowledge of data structure and good at algorithms-Able to use Docker, Kubernetes... is a plus\n-Knowledge of VPS, domain, AWS is a plus\n-Write high-quality, clean, simple, and maintainable code, can apply design pattern and understand SOLID, DRY ... principles\n-Strong analytical skills, with excellent problem-solving abilities\n-Good mindset, willingness to learn and able to pick up new technology or new concepts fast\nWhy you’ll love working at Eastgate:\n-Attractive salary package \n-Eastgate Software is a Global Fortune 500 Preferred Vendor, so you will have an opportunity to work with many IT Experts around Europe and USA \n-Be emerged in a professional and motivating environment where you have opportunities to express your own ideas and improve your skill set through many interesting full-cycle projects\n-Flexible working time: 9:30 a.m. to 6:30 p.m., Monday to Friday, No Overtime (Only 8 working hours)\n-Performance review and appropriate gratification: twice a year\n-13th month salary + Project bonus\n-Free snacks, video gaming & movie nights, team social and sport activities\n-16 leave days/year (will be added an extra day each year and maximum 20 days for annual leave)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1586, 674, 2, 'Tuyển Nhân Viên Agentic AI Engineer', 'Mô tả công việc\n\nPSA là công ty eCommerce hoạt động trong các lĩnh vực Print-on-Demand, Dropshipping, Fulfillment và Bán lẻ online, phục vụ hơn 10,000+ khách hàng toàn cầu.\n\nChúng tôi đang phát triển các hệ thống nội bộ (ERP, OMS, CRM, Data Analytics...) nhằm tối ưu hóa quy trình vận hành và nâng cao trải nghiệm người dùng, hướng tới mô hình AI-driven eCommerce.\n\nMô Tả Công Việc\n\n- Xây dựng các AI Agents dùng LLM (GPT, Claude, Gemini...) để thực hiện các tác vụ tự động như:\n❖ Tự động xử lý ticket CSKH,\n❖ Tư vấn sản phẩm đa kênh (multi-channel agent),\n❖ Tối ưu nội dung marketing (viết mô tả, quảng cáo),\n❖ Phân tích hành vi khách hàng và đề xuất chiến dịch.\n- Làm việc với các nền tảng như LangChain, LlamaIndex, OpenAI API, RAG pipelines.\n- Thiết kế quy trình tương tác agent với hệ thống nội bộ (ERP, CRM, BI).\n- Theo dõi hiệu quả agent, tối ưu prompt và logic hành vi (prompt engineering/ fine-tuning).\n\nYêu cầu công việc\n\nBắt Buộc\n- Có kinh nghiệm triển khai ứng dụng với OpenAI API hoặc các LLM khác;\n- Thành thạo Python, REST API, và một số thư viện agent framework (LangChain, AutoGen, Semantic Kernel,...);\n- Hiểu về kiến trúc hệ thống tích hợp LLM, knowledge base, RAG;\n- Tư duy logic tốt, có khả năng thiết kế hành vi cho agent một cách modular;\n- Khả năng tự học công nghệ mới nhanh, yêu thích ứng dụng AI trong thực tế.\n\nƯu Tiên\n- Có kinh nghiệm làm việc với hệ thống eCommerce / SaaS là lợi thế lớn;\n- Đã từng fine-tune LLM hoặc làm việc với vector DB (Pinecone, FAISS, Weaviate...);\n- Biết về DevOps, MLOps hoặc có kinh nghiệm chạy sản phẩm AI ở quy mô production.\n\nTại sao bạn yêu thích làm việc tại đây\n- Lương: Thỏa thuận theo năng lực + thưởng theo hiệu suất;\n- Lương T13, T14, tăng lương hàng năm theo năng lực;\n- Tham gia BHXH, BHYT, BHTN theo quy định, khám sức khỏe tổng quát định kỳ;\n- Du lịch 2 lần/năm, quà/thưởng lễ tết, sinh nhật, đồ ăn vặt tại văn phòng,...;\n- Hỗ trợ ăn trưa, gửi xe, laptop làm việc;\n- Tham gia các khóa học nâng cao chuyên môn.\n\nHình thức làm việc (chọn 1 trong 2 hình thức sau):\n- Office: T2-T6: 9:00-17:30 (nghỉ trưa 1h30p) / sáng t7 remote: 8:00-12:00\nĐịa chỉ: Tropic Garden A2 - 56 Đường số 66, Thảo Điền, Thủ Đức, HCM\n- Remote: T2-T6: 8:30-17:30 (nghỉ trưa 1h30p) / sáng t7: 8:00-12:00\n\nCách Thức Ứng Tuyển\nGửi CV + Bảng điểm (scan/ảnh file pdf, jpeg, png) về email career@makezbright.com hoặc liên hệ Zalo: 0942 485 129 (Vy PSA).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1587, 916, 2, 'Senior Frontend Engineer (ReactJS, MicroFrontend)', 'You will work in a highly productive and collaborative team where your ideas will be listened to and put into action. This exciting opportunity would suit a Senior ReactJS Engineer who is looking to move upwards and onwards and is eager to work closely with senior management on interesting and super cool ideas. Join us to build some truly awesome products!  \n\nWhat you will do\n\n- Develop new user interface features on a large-scale of web application\n- Ensure the technical feasibility of UI/UX designs\n- Optimize application for maximum speed and scalability\n- Assure that all user input is validated before submitting to back-end\n- Develop web templates based on graphical web layout designs that follow the strict requirements.\n- Collaborate with other team members and stakeholders\n- Provide continuous support and guidance to less senior colleagues through regular coaching activities and support them in fulfilling their personal development plans  \n\nWhat you should have\n\n- Solid front-end development skills and experience in HTML5, CSS, JavaScript and TypeScript\n- Expertise in JavaScript libraries (ReactJS is required) and strong experience with state management\n- Experience with REST API development and consumption\n- Experience with build tools (we use Vite, though experience with other tools is also acceptable) and the broader JavaScript toolchain\n- Experience in writing testable code, experience in JavaScript testing both at a unit and integration level, code reviews, code standard\n- Familiar with AWS\n- Exposure to environment developing a large-scale web application, and experience to build and optimize performance\n- Experience with MicroFrontend is a plus\n- Good team player, providing guidance and assistance based on your experience in front-end development\n- Good understanding of CI-CD and Trunk-Based Development is highly desirable\n- Good basic knowledge of NodeJS and interest in growing into a full-stack development role over time\n- Good verbal communication skills in English\n- Worked in a SCRUM team\n- Be happy to coach, mentor and train less senior colleagues.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1588, 899, 2, 'Reactjs Developer (AI Project)', 'Intro\n\nSotaAgents is an innovative AI Agent Platform for Business developed by SotaLabs, a member of the Sota Holdings Group. We specialize in creating exceptional web and mobile applications with a focus on AI-powered business solutions. Our team consists of first-principle thinkers dedicated to building products that address genuine customer needs and deliver meaningful value.\n\nWhat Sets Us Apart\n- First-principle thinking approach to problem-solving\n- Customer obsession over competition-focused strategies\n- Long-term vision and planning\n- Employee empowerment in decision-making\n- Commitment to efficiency and excellence\n\nLevel: Fresher\n\nJob Description\n- Develop and maintain modern web interfaces with a strong focus on performance and user experience using React.js.\n- Collaborate with backend developers and designers to build efficient, user-friendly web applications.\n- Design and implement reusable, maintainable UI components following component-based architecture.\n- Create high-quality mockups and translate UI/UX designs (Figma, etc.) into functional React code.\n- Optimize web applications for maximum speed and responsiveness across devices.\n- Ensure responsive design and cross-browser compatibility.\n- Maintain consistency with company brand guidelines and design principles.\n- Ensure code quality through unit testing, UI testing, and code reviews.\n- Gather and evaluate user feedback to continuously improve the product.\n- Stay up to date with the latest frontend technologies, tools, and trends, especially within the React ecosystem.\n\nCompensation & Benefits\n🎯Flexible working regime and health care:\n- Flexible timekeeping (from 8:00 - 9:00 to 17:30 - 18:30)\n- Minimum 14 paid leaves per annum for all employees after probation\n- 01-day remote work per month\n- A flexitime allowance of 90-180 minutes per month for employees\n- 01 hour paid leave per day for women having children under 12 months\n- Social insurance, health insurance, unemployment insurance and MIC care insurance\n\n🎯Transparent And Fair Benefits\n- Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n- Work performance review 2 times/ year (in April and October)\n- 13th-month salary\n- Bonus Policy: Public holidays (2/9, 30/4, 1/5, 1/1,...); Personal Performances; Excellent Team; Performance bonus in Token of the project;..\n- Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company\n\n🎯Dynamic Environment And Open Culture\n- Year-end party, sports day, yearly company trip and quarterly team building,...with a generous budget\n- Socialize with colleagues through monthly Happy Hour\n- Monthly allowance when joining clubs: Soccer, Swimming, Yoga, Music,...\n- Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks,...\n- Flat, open and sharing culture with friendly management team; outsourcing company with product mindset\n\n🎯Strong Learning Culture\n- Free training courses for technical and soft skills (presentation skills, communication skills, foreign language courses,...)\n- Account to log in to our online learning system, which contains thousands of valuable lectures (LMS)\n- Participate in workshops, seminars, tech talk,... with sharing from experts inside and outside the company\n- Working opportunities with technical gurus who built and operated world-class applications with millions of users.\n\nRequirements\n- Minimum 1 years of experience working with React.js in frontend development.\n- Proficient in JavaScript (ES6+), HTML5, CSS3, and modern build tools like Webpack or Vite.\n- Hands-on experience with React Hooks, Context API, and state management libraries such as Redux or Zustand.\n- Strong understanding of Single Page Application (SPA) architecture.\n- Experience with Next.js or server-side rendering (SSR).\n- Experience working with RESTful APIs, WebSocket, and libraries like Axios or React Query.\n- Familiarity with frontend testing tools like Jest and React Testing Library is a plus.\n- Experience with TypeScript is preferred.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1589, 917, 2, 'Java Software Engineer', 'Responsibilities\n- Design, develop, and rigorously test robust, scalable, and cutting-edge web applications to deliver superior user experiences.\n- Leverage native APIs and frameworks for seamless integrations, ensuring optimal system performance and user satisfaction.\n- Identify, troubleshoot, and resolve performance bottlenecks and bugs, ensuring applications run efficiently at scale.\n- Maintain high standards of code integrity through rigorous testing, documentation, and adherence to best practices.\n- Proactively monitor systems, resolving issues promptly to minimize downtime and optimize system reliability.\n- Work closely with teams based in the United Kingdom and the United States, ensuring seamless coordination and project success.\n- Analyze complex technical challenges and devise creative solutions, driving innovation within the team and organization.\n- Strong spoken and written English for international collaboration.\n\nYour Skills and Experience\nCore Skills:\n- At least 4 years of experience with core Java concepts including object-oriented programming, multithreading, generics, and collections.\n- Proficiency with Spring, Spring Data, Dependency Injection (DI), and transaction management.\n- Strong skills in building RESTful APIs, working with microservices architecture, and expertise in server technologies like Tomcat and Jetty.\n- Experience writing unit, integration, and end-to-end tests to ensure code quality and reliability.\n- Proficiency with debugging tools and techniques to maintain high-performance systems.\n- Expertise in SQL databases (e.g., PostgreSQL) and NoSQL solutions (e.g., MongoDB, DynamoDB), including database design, optimization, and data modeling.\n- Proven ability to optimize backend systems for performance and scalability.\n\nDevOps and Cloud\n- Familiarity with CI/CD tools like Jenkins, CircleCI, GitHub Action, GitLab, Harness to automate build and deployment pipelines.\n- Hands-on experience with AWS services such as EC2, EKS, S3, RDS, SQS, SNS and Lambda for scalable cloud-based solutions.\n- Experience with monitoring and logging tools like DataDog to track performance, logs, and metrics in Kubernetes environments.\n\nVersion Control and Agile Practices\n- Proficiency in GitHub for version control and team collaboration.\n- Experience working in Agile environments, participating in sprints, and collaborating with cross-functional teams.\n\nBonus Skills\n- Familiarity with JavaScript and TypeScript, including ES6+ syntax, is highly advantageous.\n- Strong knowledge of Kubernetes (K8s), including container orchestration, scaling, and deployment of microservices in a distributed system.\n\nWhy You\'ll Love Working Here\nAttractive Benefits:\n- 100% salary during probation period\n- Annual Leave: 18 days/ year\n- Five “Recharge Days” – Extra days, in addition to company holidays.\n- Flexible Friday afternoon\n- Full salary insurance\n- 13th-month bonus\n- Gift + 1 day off for birthday\n- Advanced health insurance (Generali)\n- Regular engagement activities: sport clubs, monthly company lunches, internal event…\n- Support Macbook and Monitor\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1590, 774, 2, 'Fullstack Leader (NodeJS,ReactJS) upto 50M', 'Chúng tôi coi công việc của các kỹ sư là các nhà phát triển sản phẩm chứ không phải là phát triển hệ thống. Do đó, thay vì phát triển các tính năng được xác định sẵn, chúng tôi tin tưởng rằng vai trò của các kỹ sư là xem xét những chức năng nào cần tạo ra để đặt được mục tiêu và phát triển chúng một cách tối ưu. Do đó, các kỹ sư sẽ tham gia thảo luận, định hướng sản phẩm và hoạt động với tư cách là một Full-Stack Developer.\nMô tả công việc\nNhiệm vụ công việc:\n- Tham gia nhiều dự án với quy mô khác nhau, chịu trách nhiệm thiết kế, phát triển, thử nghiệm và đưa ra tất cả các tính năng cần thiết để đạt được mục tiêu dự án.\n- Tiến hành review sản phẩm cho các thành viên trong dự án.\n- Đề xuất cả tiến để rút ngắn thời gian và nâng cao dịch vụ.\nMôi trường phát triển:\n- Server-side sử dụng dụng NodeJS, Frontend sử dụng React, React Native, Flutter\n- Quản lý source-code: Github\n- Quản lý dự án: Backlog\n- CI: CircleCi\n- Infrastructure (cơ sở hạ tầng): AWS・GCP\n- Trao đổi nội bộ: Slack\nYêu cầu công việc\nYêu cầu về kỹ năng và kinh nghiệm:\n- Có từ 7 năm kinh nghiệm phát triển phần mềm ở vị trí Fullstack Developer\n- Có tối thiểu 5 năm kinh nghiệm phát triển đội nhóm teamsize 5 member\n- Có kinh nghiệm sử dụng tốt các frontend frameworks như: React, VueJS…\n- Có từ 3 năm kinh nghiệm sử dụng tốt Nodejs\n- Có kinh nghiệm thực hiện quy trình tự động hóa như CI.\n- Có kinh nghiệm thiết lập và vận hành môi trường sử dụng public cloud như AWS.\n- Có khả năng đọc và viết tiếng Anh tốt.\n- Có định hướng làm product.\nNhững đặc điểm chúng tôi tìm kiếm:\n- Tôn trọng công nghệ, luôn muốn nâng cao kỹ năng của bản thân và tham gia thảo luận để cải tiến hệ thống.\n- Sẵn sàng tham gia xây dựng những hệ thống phức tạp để đáp ứng yêu cầu kinh doanh.\n- Nhận thức được rõ công nghệ chỉ là phương tiện và có thể xem xét tất cả lựa chọn để đạt được mục tiêu.\n- Chủ động giao tiếp để góp phần tạo ra những dịch vụ xuất sắc.\nĐãi ngộ và quyền lợi cho CO-WELLers\n- Thưởng và review tăng lương 2 lần/năm\n- Thử việc hưởng 100% lương\n- Ca làm việc linh hoạt: 8h-17h; 8h30 – 17h30; 9h – 18h\n- Ngày phép: 14+ ngày/năm\n- Bảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên.\n- Kiểm tra sức khỏe định kỳ 1 năm/lần\n- BHXH, BHYT, BHTN mức cao, đảm bảo quyền lợi người lao động.\n- Trợ cấp hoạt động teambuilding hàng tháng, du lịch công ty 1 năm/lần\nDành riêng cho nhân viên nữ:\n- Nghỉ sinh lý 2,5h/tháng\n- Hưởng 100% lương trong thời gian thai sản\n- Thêm 5 ngày nghỉ khám thai trong thai kì\nMôi trường làm việc tuyệt vời\n- Trang bị thiết bị làm việc trọn bộ, hiện đại, đáp ứng yêu cầu dự án.\n- Làm việc và hướng dẫn bởi các chuyên gia/Senior nhiều kinh nghiệm thực tế.\n- Trợ cấp hàng tháng cho các hoạt động của CLB thể thao (Yoga, Zumba, bóng đá…)\n- Thông tin chính sách mới/cải tiến được cập nhật đều đặn tới nhân viên.\n- Có riêng khu vực thư giãn phục vụ hoạt động giải trí, ẩm thực.\n- Không gian làm việc mở, tiện nghi.\nCơ hội đào tạo và phát triển bản thân\n- Thường xuyên tổ chức các buổi đào tạo, seminar cập nhật xu hướng công nghệ.\n- Đào tạo kiến thức chuyên môn, kĩ năng quản lý, kỹ năng mềm,… theo định hướng công ty và nhu cầu khảo sát nhân viên.\n- Hỗ trợ chi phí thi chứng chỉ chuyên môn. Trợ cấp chứng chỉ tiếng Nhật, chứng chỉ chuyên môn (lên tới 108 triệu) theo định hướng phát triển của Công ty.\n- Các lớp đào tạo tiếng Nhật (sơ cấp – cao cấp) với giáo viên bản ngữ trong giờ hành chính.\n- Cơ hội làm việc tại Nhật Bản với các nhân sự có tiếng Nhật.\nCV ứng tuyển vui lòng gửi về: huong.hr@co-well.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1591, 918, 2, 'Kỹ Sư AI (.NET Core + AI Prompt Engineering)', 'Là Kỹ Sư AI tại Lạc Việt, bạn sẽ tham gia xây dựng và tối ưu hệ thống phần mềm tích hợp AI phục vụ cho các giải pháp doanh nghiệp quy mô lớn. Bạn kết hợp kỹ năng lập trình backend mạnh mẽ với tư duy logic và khả năng khai thác sức mạnh của AI để tăng tốc phát triển, kiểm thử và vận hành hệ thống.\n\nNhiệm Vụ Chính\n- Phân tích yêu cầu nghiệp vụ, thiết kế hệ thống dữ liệu và APIs phục vụ các tính năng tích hợp AI.\n- Phát triển RESTful APIs và các module backend xử lý khối lượng lớn giao dịch/ngày.\n- Đồng bộ dữ liệu giữa trụ sở chính và hàng trăm đơn vị kết nối.\n\nỨng dụng AI để:\n- Sinh mã nguồn backend (.NET, SQL)\n- Viết test case, mô phỏng luồng request-response\n- Tối ưu hóa logic, viết script migration, tự động hóa kiểm thử\n- Hợp tác chặt chẽ với Front End, BA, DevOps, QA, và đội triển khai.\n- Tham gia tái cấu trúc hệ thống theo hướng mở rộng, dễ bảo trì, có thể tích hợp AI toàn diện.\n- Hỗ trợ xây dựng các hệ thống AI như chatbot, recommendation engine, rule engine.\n\nYêu cầu công việc\n- Trình độ học vấn: Tốt nghiệp Đại học chuyên ngành CNTT, Khoa học Máy tính hoặc tương đương\n- Kinh nghiệm: Tối thiểu 3 năm kinh nghiệm lập trình backend với: .NET Core, C#, LINQ, EF Core, API, Multi-threading\n- Thành thạo SQL Server, PostgreSQL, có kinh nghiệm tối ưu hóa truy vấn, indexes, stored procedures.\n- Hiểu biết về Microservices, CQRS, Event-Driven Architecture là lợi thế.\n- Biết viết prompt AI phục vụ cho sinh mã, validate logic, test case là một điểm cộng.\n- Sử dụng thành thạo Git, CI/CD pipelines.\n- Tư duy phân tích, debug tốt; xử lý được logic phức tạp.\n\nYêu Cầu Kỹ Năng AI (Bắt Buộc)\n  Thành thạo các công cụ hỗ trợ lập trình bằng AI: ChatGPT, GitHub Copilot, Cody, AI Code Reviewer\n\nCó khả năng:\n- Viết prompt để sinh mã nguồn .NET & SQL\n- Đề xuất thiết kế cơ sở dữ liệu và logic kiểm thử\n- Tự động hóa quá trình kiểm thử, viết tài liệu kỹ thuật\n- Tăng tốc quy trình debug, viết unit test, mô phỏng request-response flow\n\nThông tin khác\n- Thử việc: 60 ngày\n- Thời gian làm việc: Thứ 2 - Thứ 6 8AM - 6PM\n- Ngày nghỉ: 12 ngày phép năm\n\nThông tin liên hệ\n- Công ty: LacViet Computing Corporation\n- Người liên hệ: Phòng Nhân Sự\n- Email: hrd@lacviet.com.vn\n- Địa chỉ liên hệ: 23 Nguyễn Thị Huỳnh, P. 8, Q. Phú Nhuận, TP.HCM', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1592, 808, 2, 'SOFTWARE ENGINEER', 'Job Description\n\nParticipate in design, development, and implementation of software features according to business requirements.\nWrite and maintain comprehensive design documents.\nDebug, troubleshoot, and resolve complex software defects and production issues.\nMonitor code performance, identify bottlenecks, and implement optimizations.\nCollaborate with cross-functional teams, including product managers, designers, and QA engineers, to deliver high-quality software.\n\nRequirements\n\nCollege or university graduated, major in computer science or IT or equivalent.\n3+ years of post-graduation work experience as a Software Engineer.\nExtensive experience in backend development using either .NET (C#) or Java.\nExperience with front-end technologies such as HTML5, CSS3, JavaScript, and modern JavaScript frameworks (e.g., React, Angular, Vue.js).\nKnowledge of setting up, maintaining, and monitoring Azure services such as Virtual Machine, Manage Disk, Azure SQL, Load Balancer, Application Gateway, etc. is a plus.\nAbility to work independently and effectively in a team environment.\nGood English communication skills, with the ability to communicate smoothly with customers.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1593, 739, 2, 'Technical Reporting Engineer (Monitoring)', 'Description Du Poste\nCompany Description\nSocotec is a leading European group engaging in Building & Real Estate, Infrastructure, Industry & Equipment and Certification & Training.\nToday, Socotec operates in 26 countries and 5 continents, delivering highly specialized professional services to its clients, with the same high-quality standards across the globe.\nSocotec Vietnam established in 2018 and has been developing quickly as The Offshoring Platform Providing Engineering Capacity to the whole Socotec Group, across all international platforms.\nWe provide a wide technical portfolio covering the needs of Socotec companies, focusing on 4 business lines:\nMONITORING & DATA SERVICES\nENGINEERING & SIMULATION\nBIM / CAD & AS-BUILT SURVEY\nSOFTWARE & IT SERVICES.\nSocotec Vietnam has been constantly acknowledged as one of the preferred employers in Vietnam, being certified with the Great Place to Work award in 2023 & 2024.\nWe are expanding our team to accommodate our fast-growing global client needs.\nJoin us in our mission to Build Trust For A Safer And Sustainable World\nContact: hr.vietnam@socotec.com\nJob Description\nPlan and manage own time to ensure delivery of all reports in the required timeframe\nWork on Real-time online monitoring platforms (Senceive Web Monitor/ Sensemetrics/ Vision/ Atlas/ Blue Trust Monitoring)\nMonitoring data processing & Technical data analysis: Produce graphs/plots (from data downloaded from web platforms or manual survey/monitoring) to do the basic analysis.\nCompile processed data into final technical report, weekly/monthly report. Send for verification or directly to client\nSupport with some Power BI Dashboard.\nQualifications\nBachelor of Engineer, Bachelor of Science, or above\n3 years experience in working within a construction related environment (Survey, Design, Construction, Monitoring, …)\nKnowledge of Building and Infrastructure Structures, Structural/Geotechnical/Environmental Monitoring.\nExcellent numerical skills. Highly competent in computer software, MS office (VBA is a plus).\nExcellent at Power BI or other Data Visualization softwares\nExcellent communication skills, both verbal and written in English\nUnderstanding of Quality requirements and Must have exceptional attention to detail. Ability to work on own initiative\nAdditional Information\nAttractive salary and bonus with annual revision\nCompulsory insurance pay as gross monthly salary\nFlexible working time with 12 annual leave days & 15 work from home days\nTeam-building activities, Sport Clubs\nCooperation with colleagues around the world in a leading global group\nStrong team spirit in an entrepreneurial environment of a growing company\nPeople values, social responsibility and sustainability\nOpportunities for self-development and career advancement\nInternal training courses (technical, foreign language, soft skill)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đình Ba, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1594, 910, 2, 'SaaS Co-Founders Wanted | Software-as-a-Service Visionaries', '🌟 About Antler: We are a global early-stage investment firm that invests in startups from day zero. We provide funding, mentorship, and a global network to help you build and scale your startup. With Antler, you’ll have access to the resources you need to turn your vision into reality—whether you\'re still ideating or already started building.\n\n👩‍💼 Who are we looking for? \nNote: This ad is not for a job, but rather for the opportunity to find your co-founder and build your own VC-backed startup through a 10-week program with Antler. \n- Experts in building and scaling SaaS products, with deep knowledge of cloud-native architectures and subscription-based business models.\n- Entrepreneurs who have developed B2B or B2C software solutions that drive efficiency, automation, or digital transformation.\n- Visionaries who understand customer pain points and can create intuitive, high-impact software that delivers real value.\n- Leaders who thrive in fast-paced environments, leveraging data-driven decision-making and rapid iteration.\n- Self-starters driven to launch and grow a world-class SaaS company.\n\n📋 Details of the program: \n- The program runs for an initial 10 weeks, full-time in Ho Chi Minh City (Vietnam) and starting on 21 July 2025, where you are required to ideate and find your co-founder(s) from the cohort of 60-70 founders.\n- After two months you will present your team and business idea to the Antler Investment Committee. If accepted, you will receive a pre-seed investment of $120K USD for 12% equity, non-negotiable.\n- If you get an investment, you will continue to be part of the program for another 3 months during which Antler will work closely with you to accelerate your growth. At the end of this period, Antler arranges a demo day where we invite VCs, institutional investors, and local angel investors to help you connect with investors and raise your seed round.\n\nFor more details on what to expect 👉 https://www.linkedin.com/smart-links/AQGwMqMCzPe68Q\n\nBenefits:  \n- 💵 Potential investment at the pre-seed stage  \n- 🤝 Help finding your co-founder(s)  \n- 👨‍🏫 Personalized coaching sessions with business experts  \n- 🛫 Relocation grant of $2,000 if you\'re relocating from overseas to HCMC, Vietnam  \n- 🏬 Shared office space at a premium co-working space with access to various amenities  \n- 🌍 Access to a global network of start-up advisors and experts in their field\n\nSome examples of successful companies that were built as a result of Antler’s program, received pre-seed investment from Antler, and gone on to raise substantial investment are:  \n- Xailient - the World’s fastest Computer Vision AI  \n- BUYO - Pioneering bioplastics and material tech  \n- SKYQRAFT - Affordable and safe powerline inspections with drones and AI  \n- Airalo - The world’s first eSIM subscription and top-up store  \n- homebase - Making home ownership accessible  \n- Reebelo - Circular economy for e-devices\n\nReady to help shape the future of the world? Apply now to Antler and together we will build something truly amazing ✨', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1595, 919, 2, 'Tester (Middle Level)', 'Job description:\n- Understand project documents\n- Analyze users stories and/use cases/requirements for validity and feasibility\n- Review test plan document and actively provide feedbacks on the task assignment\n- Develop test cases and preparing test data\n- Perform testing of web based and mobile applications.\n- Report and tracking bugs found and test results\n- Communicate issues to the supervisor in timely manner\n- Collaborate with software developers and other stakeholders to ensure quality standards are met\n- Accurately complete and submits status reports in a timely manner to supervisor.\n\nYour skills and experience:\n- 2-4 years of experience as a Software Tester\n- Good experience in manual testing for web-based and mobile (iOS/Android) applications\n- Ability to analyzing requirements and problems\n- Experience in create Test Plan, create Test Case, review test case in EN\n- Hands-on experience with functional testing, integration testing, regression testing, mobile testing\n- Hands-on experience with black box testing\n- Hands-on experience with automated testing tools\n- Experience working in an Agile/Scrum development process\n- Ability to communicate with various stakeholders (both technical and non-technical)\n- Be Careful, meticulous and good logical thinking\n- Be willing to learn new things\n- Experience with performance or security testing is a plus\n- English: reading, writing\n- ISTQB certification is a plus\n- UI/UX is a plus. Having a base on technology is a plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona capitalei Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1596, 715, 2, 'Kỹ sư Phát triển phần mềm', 'Company Description\nViettel High Technology Industries Corporation (VHT) was established in 2011 as the ninth corporation of the Viettel Group, focusing on the high-tech industry in Vietnam. Specializing in equipment, tactical electronics services, and capabilities in the defense industry and telecommunication products, VHT is dedicated to innovative solutions that ensure safety. VHT aims to become a global organization with a unified vision of innovation.\n\nRole Description\nThis is a full-time on-site role for a Kỹ sư Phát triển phần mềm located in the Hanoi Capital Region. The Software Development Engineer will be responsible for designing, developing, and maintaining software applications. Daily tasks will include coding, debugging, testing, and collaboration with cross-functional teams to enhance software performance and user experience.\n\nQualifications\n- Proficiency in software development, coding, and debugging skills\n- Experience with software testing and quality assurance\n- Strong problem-solving and analytical skills\n- Ability to work collaboratively with cross-functional teams\n- Excellent written and verbal communication skills\n- Familiarity with telecommunication products and defense industry software is a plus\n- Bachelor\'s degree in Computer Science, Software Engineering, or a related field', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1597, 709, 2, '[Hà Nội/Hải Phòng/Quảng Ninh] Giáo viên part-time giảng dạy stem', 'Giáo viên/Chuyên môn\n\nTừ Không yêu cầu kinh nghiệm kinh nghiệm\n\nLiên Hệ Ứng Tuyển Tại\ntuyendung@teky.edu.vn hoặc 02471096668\n\nThu nhập: 2.000.000đ - 7.000.000đ/tháng\nHạn nộp hồ sơ: 30.09.2025\nPhòng ban: Giáo viên/Chuyên môn\nThời gian làm: Partime\nKhu vực: Hà Nội, Quảng Ninh, Hải Phòng\nSố lượng: 12\n\nGửi hồ sơ ứng tuyển\n\nThông tin công việc\n\nThời gian làm việc: Đăng ký theo ca linh hoạt\nNơi làm việc:\nTeky Hội sở chính [Hà Nội]: Số B-TT01-51-53 Khu nhà ở Ngân Hà Vạn Phúc, phường Vạn Phúc, quận Hà Đông, TP Hà Nội\nTeky Hoàn Kiếm: Số 96 Hai Bà Trưng, Cửa Nam, Hoàn Kiếm, Hà Nội\nTeky Cầu Giấy: Tầng 3, Toà Nhà Thanh Chân, Số 6 Nguyễn Thị Thập Trung Hòa Nhân Chính, Quận Cầu Giấy, Hà Nội\nTeky Long Biên: Số 414 Nguyễn Văn Cừ, Bồ Đề, Long Biên, Hà Nội\nTeky Hải Phòng: 73 Điện Biên Phủ, Minh Khai, Hồng Bàng, TP Hải Phòng\nTeky Hạ Long: SH4 Times Garden, Đường 25 tháng 4, Bạch Đằng, Hạ Long, Quảng Ninh\nTeky Minh Khai: Tầng 3, số 463 Minh Khai, Vĩnh Tuy, Hai Bà Trưng, Hà Nội\nTeky Linh Đàm: Biệt thự 27, TT4A Khu Biệt Thự Tây Nam Linh Đàm, Hoàng Liệt, Hoàng Mai, Hà Nội.\nTeky Bắc Từ Liêm: LKC37, Dự án khu nhà ở thấp tầng A1TT1, Xuân Tảo\n\nBộ môn Lập trình & phát triển ứng dụng.\nTham gia giảng dạy (hoặc trợ giảng) lập trình, sử dụng các ngôn ngữ: Python, Scratch, HTML, Mobile App, JAVASCRIPT, JAVA.\nTham gia các buổi seminar, training.\n\nBộ môn Điện tử tự động & Robot.\nTham gia giảng dạy, trợ giảng đối với các môn học thuộc bộ môn điện tử – tự động hóa như: Lego Mindstorm, Arduino, Raspberry Pi...\nTham gia các buổi seminar, training.\n\nBộ môn Công nghệ 3D & Truyền thông đa phương tiện\nTham gia giảng dạy, soạn giáo án, dựng khung chương trình, trợ giảng đối với các môn học thuộc bộ môn vẽ tay 3D, In 3D, Quay phim, Làm phim, Nhiếp ảnh.\nTham gia các buổi seminar, training\n\nYêu cầu ứng viên\nĐang theo học, Tốt nghiệp Đại học các chuyên ngành Sư phạm, khoa công nghệ thông tin.\nLà giảng viên đã và đang giảng dạy tại các trường cấp 1, cấp 2 bộ môn Tin học, Công nghệ thông tin.\nĐang làm việc tại các công ty Truyền thông, Công nghệ thông tin.\nĐang là sinh viên đang theo học khoa CNTT, Điện tử – tự động, mỹ thuật,.truyền thông đa phương tiện.\n\nQuyền lợi được hưởng\nThu nhập trung bình từ 2 – 7 triệu/tháng (Theo bậc)\nCông việc lành mạnh, văn hoá doanh nghiệp giàu bản sắc\nCơ hội làm việc trực tiếp tham gia các dự án giáo dục mang tính quốc tế cao, có sự tham gia của các doanh nghiệp hàng đầu về giáo dục và công nghệ tại Mĩ, Hàn Quốc, Nhật Bản.\nThường xuyên tham gia các buổi đào tạo kĩ năng chuyên môn và kiến thức sư phạm, công nghệ hàng tháng.\nĐược làm việc trong môi trường Giáo dục năng động, chuyên nghiệp, cơ sở vật chất hiện đại.\nCơ chế đặc biệt khi hoàn thành nhiệm vụ.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Hà district, Prowincja Quảng Ninh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1598, 904, 2, 'Software Engineer II', 'MiTek® is a global provider of building solutions for the residential and commercial construction industries. Utilizing software, services, engineered products, and automated manufacturing equipment, MiTek partners with clients to accelerate their genius and deliver breakthroughs in building.\n\nWith a rich 60-year history and a network of 6,500 team members worldwide, MiTek pairs local expertise with global capabilities. As a Berkshire Hathaway (NYSE: BRK-A, NYSE: BRK-B) company since 2001, MiTek has a record of continuous growth and innovation.\n\nLearn more at www.mii.com.\n\nA Brief Overview\n\nKỹ sư Phần mềm là một vị trí với nhiệm vụ bao gồm tham gia vào toàn bộ chu trình phát triển phần mềm của từng dự án hoặc sản phẩm mà mình phụ trách. Báo cáo trực tiếp cho Quản Lý Bộ Phận, Kỹ Sư Phần Mềm phải đảm bảo cung cấp dịch vụ hiệu quả và nhanh chóng nhằm đáp ứng nhu cầu và kì vọng của khách hàng và tiếp tục phát triển cùng các thành viên trong nhóm.\n\nSoftware Engineer is a role which involves participating in the full software development lifecycle for each project or product you are assigned. Reporting to the Manager, the Software Engineer must ensure a smooth efficient service that meets the expectations and needs of our customers and continues to grow & develop our staff.\n\nResponsibilities\nWhat You Will Do:\n\n- Áp dụng các giải pháp kỹ thuật phần mềm tốt nhất nhằm đảm bảo chất lượng sản phẩm phần mềm và xây dựng một môi trường phần mềm tối ưu\n- Theo dõi, phân tích và hoàn thiện quá trình phát triển phần mềm hiện tại, đồng thời hỗ trợ xác định phương án cải thiện phù hợp\n- Liên lạc và tương tác với các thành viên trong nhóm nhằm đảm bảo sự tiến bộ liên tục;\n- Trao đổi với tất cả khách hàng và các cổ đông khác nhằm cung cấp được dịch vụ chất lượng cao nhất có thể\n- Chủ động và tích cực tham gia với tư cách là một thành viên nhóm Phát Triển Phần Mềm MiTek Vietnam, đoàn kết hướng đến mục tiêu trở thành một tổ chức vững mạnh\n- Tham gia hỗ trợ các công việc hằng ngày của nhóm\n- Thiết kế, lập trình, kiểm tra và gỡ rối, sử dụng công nghệ, công cụ phát triển và ngôn ngữ lập trình theo yêu cầu của dự án\n- Cộng tác với Quản Lý Sản Phẩm, Quản Lý Chất Lượng, DevOps, Kiến Trúc Sư phần mềm và các nhóm chức năng khác trong dự án (Ví dụ: Customer experience, Sales, Marketing), để đảm bảo rằng các giải pháp hiệu quả, nhất quán và đáp ứng nhu cầu kinh doanh\n- Làm việc trong môi trường phát triển phần mềm Agile (ví dụ: Scrum, Kanban), tham gia các cuộc họp cam kết, hồi cứu và lập kế hoạch\n- Chuyên cần trong giờ làm việc bình thường và ngoài giờ theo yêu cầu\n- Tham gia đánh giá các yêu cầu phần mềm\n- Tái cấu trúc sản phẩm hiện tại\n- Áp dụng các tiêu chuẩn phát triển sản phẩm và đảm bảo chất lượng để đảm bảo thao tác logic và dữ liệu chương trình hiệu quả\n- Tham gia vào quy trình thiết kế và kiểm tra thiết kế\n- Có khả năng tự thiết kế các giải pháp chất lượng cho các tính năng nhỏ và trung bình\n- Tiếp tục xây dựng gia đình MiTek Vietnam thông qua việc hỗ trợ khách hàng và đảm bảo cung cấp cho tất cả khách hàng dịch vụ chất lượng cao nhất\n- Các công việc khác theo sự phân công\n- Implement software engineering best practices to ensure the quality creation of software, and create an environment of software excellence\n- Monitoring, analyzing and improving the current development process – and help determine appropriate strategies for positive improvement\n- Liaising and interacting with all team members to ensure continuous improvement\n- Communicating with all customers and other stakeholders to the highest level of quality applicable\n- Positively and proactively participate as a member of the MiTek Vietnam Software Center, united in the pursuit of operational excellence\n- Participate in daily activities to support the Team\n- Design, code, test, and debug software, utilizing technologies, development tools and languages as required for the project assigned\n- Collaborate with Product Management, Software Quality Assurance, DevOps, Architecture, and other functional teams (e.g. Customer experience, Sales, Marketing), to ensure that solutions are efficient, consistent and fulfill business needs\n- Work in an Agile software development environment (e.g. Scrum, Kanban), participating in commitment, retrospective and planning meetings\n- Attendance during regular work hours and overtime as required\n- Participate in requirements reviews\n- Refactor existing software\n- Apply generally accepted development and quality assurance standards and techniques to assure efficient program logic and data manipulation\n- Participate in design and design reviews\n- Able to independently design quality solutions for small to medium features\n- Continue to grow the MiTek Vietnam family by supporting the customers and ensuring the highest level of service is provided to all customers.\n- Other reasonable duties as assigned\n\nQualifications\n\n- Tốt nghiệp Đại học hoặc Cao đẳng, ưu tiên chuyên ngành Khoa học máy tính hoặc Kỹ sư máy tính\n- Có hơn 2 năm kinh nghiệm trong lĩnh vực phần mềm hoặc các lĩnh vực liên quan với kiến thức sơ lược về các quy trình và giải pháp phát triển toàn cầu.\n- Trình độ tiếng Anh (CEFR) B1+ hoặc tương đương\n- Có kiến thức và kinh nghiệm vững chắc về phát triển phần mềm, sử dụng các công nghệ cho dự án được giao và nhất quán với nhóm, điển hình bao gồm sử dụng các mẫu thiết kế, Thiết kế hướng đối tượng, C#, .NET Framework, Cơ sở dữ liệu SQL, C, C++ cũng như các công cụ và ngôn ngữ phát triển khác theo yêu cầu\n- Có kinh nghiệm mạnh về Microsoft Visual Studio hoặc IDE tương đương khác\n- Có khả năng đưa ra mục đích và hướng đi rõ ràng trong công việc\n- Nắm bắt và truyền đạt các mục tiêu làm việc có thể đo lường\n- Truyền đạt thông tin ngắn gọn và rõ ràng\n- Hỗ trợ các thành viên trong nhóm trong quá trình đào tạo thực tế (hoặc khi được đào tạo)\n- Giải quyết các vấn đề và mâu thuẫn theo hướng tích cực\n- Tuân thủ theo các quy trình phù hợp của MiTek Việt Nam\n- Xây dựng một môi trường làm việc trong đó các thành viên trong nhóm hỗ trợ và đoàn kết với nhau\n- Có khả năng động viên và khuyến khích các thành viên trong nhóm đưa ra sáng kiến và đặt trọng tâm vào chất lượng\n- Xác định các cơ hội nhằm cải thiện quá trình phát triển và cung cấp các dịch vụ\n- Khuyến khích và hỗ trợ xây dựng một văn hóa làm việc trong đó các thành viên không ngừng phát triển\n- Hỗ trợ các thành viên trong nhóm khi công ty có các thay đổi\n- Có khả năng thể hiện được các giá trị cốt lõi của Công ty MiTek Việt Nam\n- Hiểu biết sâu sắc về dịch vụ khách hàng bao gồm việc thực hiện các quy định về sự hài lòng của nhân viên.\n- University or College degree, preferably major in Computer Science or Engineering\n- Have 2 plus years experience within software or related industry with a cursory knowledge of global development practices and procedures.\n- English level (CEFR) B1+ or equivalent\n- Have solid knowledge and experience in software development utilizing technologies for the project assigned and consistent with the team typically including using design patterns, Object Oriented Design, C#, .NET Framework, SQL Database, C, C++, and other development tools and languages as required\n- Strong experience with Microsoft Visual Studio or other equivalent IDE\n- Be able to provide a clear purpose and direction to your sprint tasks\n- Understand and communicate measurable performance objectives\n- Communicate clearly and succinctly\n- Support team members through on-the-job training (or being trained)\n- Resolve problems and conflicts positively\n- Conduct yourself in line with appropriate MiTek Vietnam procedures\n- Create a supportive, inclusive environment within the team\n- Ability to encourage and motivate staff to deliver on initiatives with a focus on quality\n- Identify opportunities for better service delivery and development\n- Promote and support continuous improvement culture\n- Support team members through change processes\n- Capability to live the MiTek Vietnam values\n- Demonstrated internal customer service insights including the implementation of employee satisfaction charters.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Binh Thuan, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1599, 893, 2, 'Software Engineer II - Full Stack', 'About Us\n\nWati is the world\'s leading WhatsApp-first conversational growth platform, empowering businesses to build deeper customer relationships and accelerate revenue growth.\n\nTrusted and loved by over 14,000 customers across 100+ countries, Wati has established itself as the premier choice for businesses leveraging WhatsApp and other messaging channels to connect with customers on their platform of choice.\n\nIn a world where real-time interactions drive growth, Wati\'s story is all about business growth through conversations. At Wati, we believe that every conversation matters, whether it\'s engaging a first-time prospect, nurturing a qualified lead, or deepening relationships with loyal clients. We transform these conversations into opportunities for building relationships, and strong relationships lead to increased revenue.\n\nOur Platform\n\nThe AI-native platform simplifies complex business operations by bringing all customer interactions under one intelligent roof. Designed for scalability and ease of use, our solution delivers a measurable ROI while adapting to businesses of all sizes, from emerging startups to established enterprises.\n\nOur Backing & Partnerships\n\nWati is proudly backed by world-class investors including Tiger Global, Sequoia Capital, DST Global, and Shopify. As a Premium-tier Partner of Meta, Google, and WhatsApp, we maintain the highest standards of integration and platform excellence.\n\nAs Wati continues to scale rapidly, we\'re looking for a Software Engineer II - Full Stack to work closely with Development, QA, DevOps, Support and Product. You are a leader that will participate in senior technology strategy discussions, drive ideation across a distributed software team, develop implementation roadmaps and work with technical individuals to transform this into software products and solutions.\n\nWhat you\'ll do:\n\n- Develop, test, and maintain web applications using React, with a focus on creating clean, efficient, and reusable code\n- Collaborate with cross-functional teams, including design, product, and QA, to deliver a seamless and engaging user experience\n- Participate in the entire software development lifecycle, including planning, development, testing, and deployment\n- Implement front-end solutions that integrate with backend APIs and services in a secure and scalable manner\n- Optimize applications for performance, scalability, and accessibility\n- Participate in code reviews, contribute to technical discussions, and uphold high standards of code quality\n- Troubleshoot and resolve front-end issues, ensuring the best possible user experience\n\nWhat will make you stand out:\n\n- Hands-on experience coding with tools like GitHub Copilot, Cursor, or other AI-assisted development environments\n- Proven track record of building and launching products from 0 to 1\n- Prior experience developing overseas or export-focused applications\n- Familiarity with microservices architecture.\n\nRequirements\n\n- Bachelor\'s degree in Computer Science, Engineering, or related field, or equivalent practical experience\n- 3+ years of hands-on experience with React development\n- Proficiency in JavaScript, HTML, CSS, and core front-end development principles\n- Solid foundation in server-side technologies, such as Node.js (Express, NestJS) or similar frameworks\n- Familiarity with state management libraries (e.g., Redux or Context API)\n- Experience with version control systems (e.g., Git)\n- Proficiency in English, with strong communication and collaboration skills, and a willingness to learn and adapt\n\nYour application will go through internal screening. Only shortlisted candidates will be contacted for further discussion. All personal data collected will be kept strictly confidential for recruitment purpose only.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1600, 713, 2, 'Java Software Engineer', 'Why you\'ll love working with us? In addition to an attractive and competitive offered package, Moatable offer an exciting blend of challenge, growth, and purpose. As a fast-paced SaaS company operating at the forefront of technical innovation, our teams tackle complex problems daily, giving engineers and product minds alike the opportunity to grow fast, think boldly, and lead with impact. Our largest business market is in the U.S., where we build software to high standards and face little direct competition, giving our teams the unique advantage of solving real, large-scale problems with global reach. If you\'re driven by growth, energized by challenge, and ready to lead, Moatable is where your next chapter begins. We are currently seeking a Java Backend Engineer with a minimum of 3 years of relevant experience to join our team in Vietnam. Key Responsibilities Participate in the requirements analysis, high-level design, detailed design, and the preparation of technical documentation for the project. Responsible for the development of core project modules, delivering technical solutions, and addressing key technical challenges. Design, build, and maintain efficient, reusable, and reliable backend system code. Ensure optimal performance, quality, and responsiveness of applications. Identify system bottlenecks and errors, and formulate solutions. Maintain code quality, organization, and automation. Requirements Required Skills and Qualifications: A minimum of 3 years of backend development experience. Solid foundational knowledge of Java, with a thorough understanding of concepts such as JVM, I/O, concurrency, and multithreaded programming. Proficient in SQL, with strong skills in using databases like MySQL, and a certain level of SQL optimization capability; familiarity with common NoSQL solutions such as Redis, along with an understanding of their respective advantages, disadvantages, and use cases, is preferred. Possess a certain level of oral and written communication skills in English, as well as strong time management abilities. Some basic knowledge of container and Kubernetes Good understanding of Http and restful API. Preferred Qualifications Experience with serverless architecture. Expertise in the development, analysis, and design of high-performance systems, ensuring system stability. Experience with AWS network infrastructure. About the Company Who We Are: Moatable provides management expertise, support services, and capital to help our SaaS businesses grow, scale, and reach their full potential. Our incubation and exit strategy encourage our subsidiary companies to act boldly, build strong businesses, and address their customers’ most pressing problems. The goal is to create value and, eventually, enable our subsidiaries to go public or strike out on their own. What We Do: We have been building two SaaS products Trucker Path: This is North America\'s most popular suite of applications for commercial over the road truck drivers. It helps users discover hundreds of thousands of truck-friendly locations, navigate confidently with reliable turn-by-turn truck navigation, source loads from one of the largest mobile load boards, and manage all their operations with a TMS platform that incorporates the entire ecosystem of offerings. Trucker Path\'s mission is to revolutionize the trucking and transportation industry, starting with the millions of truck drivers that represent this trillion-dollar industry. Featured in Forbes, TechCrunch, Wall Street Journal, and VentureBeat as one of the fastest-growing tech startups disrupting the freight industry, our technology provides over-the-road truck drivers with a safe, economical, and smart long-haul experience. We\'re proud to be the number one trucking platform with over one million active drivers that rely on our services. Our goal is to improve the lives of truck drivers and the efficiency of the $1T transportation industry through technology. Lofty: Based in Phoenix, AZ, Lofty is an award-winning real estate technology company providing an all-in-one CRM and sales acceleration platform. The platform is designed to help real estate professionals close more deals faster by combining IDX websites, lead generation, marketing automation, advanced lead management, and powerful AI to capture and convert leads into new agreements and closed-won business cost-effectively. At Lofty, we offer expansive mentorship from our employees across global offices to guide you through the start of your career. As you build networks and friendships with people that share your passion for technology, we welcome individuals from all backgrounds who seek to make a real impact and foster positive change. Loftyworks: At LoftyWorks, we provide software + service solutions to solve the back office needs of lettings agents, estate agents and professional landlords. Our approach brings a level of collaboration and expertise that is unmatched in the industry today. We specialise in rent processing (collection, reconciliation, client money and deposit management), bookkeeping and property management. LoftyWorks streamlines, cuts cost by up to 35%, improves compliance by typically 10% or more and de-risks operations in one. Website Links: Moatable: https://www.moatable.com/about/ Trucker Path：https://www.truckerpath.com/ Lofty：https://lofty.com/ Loftyworks：http://www.loftyworks.com/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1601, 711, 2, 'Embedded Software Engineer (Junior/Middle/Senior)', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n\n- Requirement Analysis, Architectural Design, Detailed Design, Implementation, Unit Test, Integration Test, Qualification Test for HW driver, Embedded Software.\n- Compiling, flashing and debugging on ECU.\n- Teamwork and handle day-to-day work efficiently and independently.\n\nWhat You’ll Bring\n\n- Electronics/ Mechatronics/ Embedded Engineering/ Computer Engineering or relevant background.\n- Have 1+ hand-on year of experience in HW device driver, Embedded System.\n- Good in C/C++ programming for HW driver, Linux Kernel, Embedded Software, Compiler, Bashscript, Shell Script Makefile.\n- Have experience in working with HW Manual, Datasheet, Schemantic.\n- Have knowledge in some of Linux OS, Realtime OS.\n- Good in troubleshooting, critical thinking and teamwork.\n- Competent in English.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona metropolitană Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1602, 920, 2, 'Progress OpenEdge Software Developer', 'Progress OpenEdge Developer\n\n100% Remote Work Position\n\nPosition Overview\n\nAs a Progress OpenEdge Developer, you will work with our Multipub product, designing and implementing projects and new client deployments. You will collaborate with cross-functional teams to deliver high-quality software solutions that meet our strategic business objectives.\n\nKey Responsibilities\n\n- Develop and maintain applications using Progress OpenEdge ABL (Advanced Business Language)\n- Design, code, test, and debug complex programs\n- Optimize existing applications for maximum speed and scalability\n- Implement database design and modifications using Progress Database\n- Collaborate with our Product team to translate requirements into technical specifications\n- Participate in code reviews and ensure adherence to coding standards\n- Document technical specifications and maintain system documentation\n- Support the migration of legacy systems to modern architectures\n- Troubleshoot production issues and provide timely solutions\n\nRequired Qualifications\n\n- 3+ years of experience with Progress OpenEdge Development (Version 11.x or higher)\n- Strong proficiency in Progress ABL/4GL programming\n- Experience with Progress Database administration and performance tuning\n- Familiarity with source control systems\n- Understanding of SQL and relational database concepts\n- Experience with Agile development methodologies\n- Strong problem-solving and analytical skills\n- Excellent communication and collaboration abilities\n\nPreferred Qualifications\n\n- Experience with Progress Dynamics/WebSpeed\n- Experience with WinForms\n- Familiarity with Docker containerization\n- Experience with private cloud platforms\n- Experience building or maintaining audience and subscription management systems\n- Experience with continuous integration/continuous deployment (CI/CD) pipelines\n\nSkills: problem-solving,advanced,ci/cd pipelines,progress database administration,design,webspeed,progress abl/4gl programming,progress database,progress dynamics/webspeed,winforms,progress openedge,docker,continuous deployment,source control systems,ci/cd,progress openedge abl,collaboration,progress dynamics,agile,docker containerization,adherence,openedge,agile development methodologies,database,communication,agile methodologies,continuous integration,agile development,relational database concepts,4gl,sql,specifications,analytical skills,private cloud platforms,code,performance tuning', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1603, 921, 2, 'Senior Software Engineer', 'About Marvell\n\nMarvell’s semiconductor solutions are the essential building blocks of the data infrastructure that connects our world. Across enterprise, cloud and AI, automotive, and carrier architectures, our innovative technology is enabling new possibilities.\n\nAt Marvell, you can affect the arc of individual lives, lift the trajectory of entire industries, and fuel the transformative potential of tomorrow. For those looking to make their mark on purposeful and enduring innovation, above and beyond fleeting trends, Marvell is a place to thrive, learn, and lead.\n\nYour Team, Your Impact\n\nMarvell is empowering the global data economy. Whether at the network core or edge, our leadership technologies make it possible for the world’s data to be processed, moved, stored and secured faster and more reliably. With leading intellectual property and deep system-level knowledge, Marvell\'s infrastructure semiconductor solutions are transforming the 5G, cloud computing, enterprise and automotive markets of tomorrow.\n\nAt Marvell, you’ll see your ideas put to work, share in the success of our company, and achieve a healthy life-work balance in a strong culture of corporate citizenship and global semiconductor leadership. If you are ready to excel, innovate, and truly enjoy where you work, apply now for the position detailed below.\n\nWhat You Can Expect\n\n• Develop secure bootloader and its infrastructure for Marvell\'s products.\n• Porting RTOS into embedded device.\n• Develop new features, enhance existing features, bug fixing.\n• Provide crypto agile architecture to meet future requirements.\n• Trouble shooting and fixing the issues.\n• Develop Threat Models, security policies, vulnerability assessment reports to address and improve the security posture of the product.\n• Assist team in compliance objectives to meet requirements for security standards such as FIPS, Common Criteria.\n• Provide domain expertise, advice and assistance to key internal stakeholders (engineering, product) and external stakeholders (customers).\n• Design and Develop secure authentication, encryption/decryption and key management function and integrate them with various products.\n\nWhat We\'re Looking For\n\n• Programming skills in C and embedded system (Must)\n• Having knowledge of algorithms, data structures, Bare metal, RTOS\n• Experience in Device drivers, Firmware of embedded device is an advantage\n• Excellent problem solving skills and and providing workable solutions\n• Proficiency in troubleshooting software issues and debugging a large codebase\n• Familiar with Agile process.\n• Good Understand of Security protocols like SSL and knowledge on Crypto algorithms\n• Good knowledge on public key cryptographic algorithms\n• Must have effective interpersonal and teamwork skills.\n• Excellent communication skills.\n• Must have the ability to multi-task in a fast-paced environment.\n• Bachelor’s degree in Computer Science, Electrical Engineering or related fields\n• Or Master’s degree and/or PhD in Computer Science, Electrical Engineering or related fields\n\nAdditional Compensation And Benefit Elements\n\n• Competitive salary, plus 13th-month salary and performance-based bonus\n• RSUs (Restricted Stock Units) for new joiners and on-going annually\n• Premium health & accident insurance for you and your family (spouse and children)\n• Annual medical check-up at a designated hospital arranged by Marvell\n• Generous paid leave policies: 15 annual leave days, 3 Recharge periods per year (company-wide off-work from Friday to Monday), 5 paid sick leave days, 3 days of volunteer time-off and 11 public holidays\n• Exciting Employee Events: Participate in fun activities throughout the year such as team birthdays, sports tournaments, company trips, mid-autumn, appreciation week, charity, health seminars, year-end party, and more.\n\nAll qualified applicants will receive consideration for employment without regard to race, color, religion, sex, national origin, sexual orientation, gender identity, disability or protected veteran status.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1604, 922, 2, 'Java Software Engineer', '[HO CHI MINH] JAVA ENGINEER\n📍𝗖𝗼𝗺𝗽𝗮𝗻𝘆 𝗕𝗮𝗰𝗸𝗴𝗿𝗼𝗻𝗱\n- Headqarters: Singapore\n- Offices: Over 30 locations worldwide\n- Employees: Approximately 16,000 globally\n- Product: a comprehensive suite of financial technology solutions\n🏢 𝗟𝗢𝗖𝗔𝗧𝗜𝗢𝗡: HCM, District 1\n💵𝗦𝗔𝗟𝗔𝗥𝗬: 50 - 80Mil\n✅𝗕𝗘𝗡𝗘𝗙𝗜𝗧𝗦:\n- 💰 13th-month salary + performance bonus\n- 📈 Annual review & salary raise\n- 🛡️ Full-salary social insurance + private health insurance\n- 💰 Performance Bonus: 2-5 months\n—------------------\n🌟𝗥𝗘𝗤𝗨𝗜𝗥𝗘𝗠𝗘𝗡𝗧:\n- At least 5-8+ years of experience with Java Development (Spring)\n- Understanding of Software Development Life Cycle & Agile Development\n- Fluent in English communication\n- Possess baseline problem-solving and debugging skills\n- Excellent communication skills and a strong collaborative mindset - Willingness to learn and stay updated on new technologies and programming languages\n- Possess foundational database knowledge, such as SQL, transactional and relational databases \n- Good communication in Vietnamese and English are mandatory as the role requires working with Vietnamese and international teams.\n—----------------\n𝗣𝗹𝗲𝗮𝘀𝗲 𝗰𝗼𝗻𝘁𝗮𝗰𝘁 𝗺𝗲 𝗳𝗼𝗿 𝗱𝗲𝘁𝗮𝗶𝗹𝗲𝗱 𝗶𝗻𝗳𝗼𝗿𝗺𝗮𝘁𝗶𝗼𝗻:\n📱 0967760995 (zalo)\n📩 quyen_trantruongnha@persolkelly.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1605, 721, 2, 'Senior Software Engineer - Frontend (React)', 'Keyloop bridges the gap between dealers, manufacturers, technology suppliers and car buyers. We empower car dealers and manufacturers to fully embrace digital transformation. How? By creating innovative technology that makes selling cars better for our customers, and buying and owning cars better for theirs.\n\nWe use cutting-edge technology to link our clients’ systems, departments and sites. We provide an open technology platform that’s shaping the industry for the future. We use data to help clients become more efficient, increase profitability and give more customers an amazing experience. Want to be part of it?\n\nRole Purpose:\nThe Senior Software Engineer (Frontend) predominantly works on projects utilising front-end web technologies but can also undertake whole builds including back-end technologies when required. The Software Engineer understands modern tools and languages within web development but also investigates new tools, libraries and identifies application opportunities to new or existing products / projects.\n\nWorking in an agile approach, you are expected to plan, prototype and build applications, in part or in full, whilst being able to work on your own, you will also be responsible for mentoring other engineers and assisting the Product Owner with agile ceremonies, including morning stand-ups and technical refinement of work, this also includes raising work requests and tickets within JIRA and making sure your team understand the work to be completed.\n\nThe role can be at times very much R&D orientated with prototypes & proof-of-concepts as common outputs refined through ongoing stakeholder feedback. Innovation, problem solving, and excellent technical skills are essential to this role. A senior engineer will have the ability to plan projects and features as-well as assist other Software Engineers when required.\n\nKey Responsibilities\n- Overseeing the programming, testing, AWS services and deployment of enterprise solutions relating to Frontend projects\n- Training and supporting other engineers within the team where necessary\n- Providing technical support to Business Analysts, Architects, Project Managers, and other Developers\n- Creating enterprise software documentation and providing ticket support\n- Testing segments of project code to ensure quality and checking for errors\n- Working closely with architects, clients and internal business stakeholders to create bespoke solutions outside of our core products\n- Recommending appropriate tools, technologies, and processes for the development of scalable and software solutions\n- Working with established production processes to maintain consistent standards and innovate where possible\n- Establishing coding standards, guidelines, and project practices\n- Ensure the confidentiality, integrity, and availability of all IT business information\n- Being prompt to meetings and making sure you attend those that require your attendance these may include:\n- Client meetings assisting the Product Owner from a technical perspective\n- Agile ceremonies such as stand ups, retrospective and refinement sessions\n- Internal stakeholder meetings\n\nPerson Specification\n- Technical Competencies:\n- HTML(5)\n- CSS & Tailwind\n- JavaScript / NodeJS\n- React\n- NextJs\n- Shadcn/ui\n- Storybook\n- Node.js\n- Database experience e.g. MySQL / NoSQL\n- Understanding of version control systems (GIT/SVN) including gitflow\n- Experience with restful API’s\n- Serverless / SAM frameworks for AWS deployments\n- Unit testing; Jasmine / Karma / Jest / Istanbul\n- Figma\n- Experience of some of the basic Amazon Web Services (S3, DynamoDB, EC2)\n\n- Behavioural & Personality Competencies\n- Self-betterment; on-going personal and technical development\n- Work well as part of a team or as an individual\n- Drive for excellent results\n- Commercial Awareness\n- Effective communication skills\n- Engineering mindset\n- Organized & self-sufficient\n- Proactive with taking ownership & responsibility\n- Logical, methodical approach to problem and issue solving\n- Collaborative \n- Problem solving mindset\n- Innovative\n\nRequired Experience\n- Minimum 3 years engineering experience (Including 1 year within a mid-level role)\n- Exposure to CMS platforms (Wordpress / Joomla / Drupal / OctoberCMS or custom made)\n- Commercial experience working with frontend technologies\n- Experience in creation of technical documentation\n- Basic backend development PHP / MySql (advantageous)\n\nWhy join us?\nWe’re on a journey to become market leaders in our space – and with that comes some incredible opportunities. Collaborate and learn from industry experts from all over the globe. Work with game-changing products and services. Get the training and support you need to try new things, adapt to quick changes and explore different paths. Join Keyloop and progress your career, your way.\n\nAn inclusive environment to thrive\nWe’re committed to fostering an inclusive work environment. One that respects all dimensions of diversity. We promote an inclusive culture within our business, and we celebrate different employees and lifestyles – not just on key days, but every day.\n\nBe rewarded for your efforts\nWe believe people should be paid based on their performance so our pay and benefits reflect this and are designed to attract the very best talent. We encourage everyone in our organisation to explore opportunities which enable them to grow their career through investment in their development but equally by working in a culture which fosters support and unbridled collaboration.\n\nKeyloop doesn’t require academic qualifications for this position. We select based on experience and potential, not credentials.\n\nWe are also an equal opportunity employer committed to building a diverse and inclusive workforce. We value diversity and encourage candidates of all backgrounds to apply.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1606, 923, 2, 'FULLSTACK DEV (DỰ ÁN GENAI)', 'FullStack Dev (Dự án GenAI)\n\nMÔ TẢ CÔNG VIỆC\n\n🎯 Về dự án C-Agent\nC-Agent là nền tảng quản lý tri thức và ứng dụng GenAI dành cho doanh nghiệp Việt Nam. Sản phẩm giúp doanh nghiệp xây dựng hệ tri thức nội bộ, tự động hóa trả lời câu hỏi từ người dùng, kết nối đa nguồn dữ liệu (Google Drive, Notion, GitHub, API...) và tạo quy trình workflow linh hoạt.\n\n🎯 Mục tiêu vai trò\nBạn sẽ tham gia xây dựng và phát triển toàn diện sản phẩm C-Agent, tập trung vào phát triển hệ thống backend chịu tải lớn (API, xử lý dữ liệu, tích hợp AI) và đảm bảo frontend hoạt động hiệu quả, trực quan cho người dùng.\n\n🛠 Trách nhiệm chính\n- Thiết kế và phát triển các API hiệu suất cao (RESTful, gRPC) phục vụ AI và ứng dụng web\n- Xây dựng các module backend phức tạp (authentication, authorization, rate limiting, logging, etc.)\n- Tích hợp hệ thống với các dịch vụ AI/LLM và luồng xử lý dữ liệu lớn\n- Làm việc cùng AI Engineer, Product Manager, BA để hiểu yêu cầu nghiệp vụ và xây dựng giải pháp phù hợp\n- Tham gia phát triển frontend (React/Next.js), đảm bảo tính năng và giao diện đồng bộ với backend\n- Đóng góp vào việc tối ưu kiến trúc hệ thống, cải tiến hiệu năng, và nâng cao chất lượng codebase\n\n🧠 Yêu cầu bắt buộc\n\n🌐 Backend (Ưu Tiên Chính)\n- Thành thạo Node.js (NestJS, Express), có thể tối ưu backend cho hệ thống chịu tải lớn\n- Hiểu rõ về kiến trúc Microservices, thiết kế API, xử lý concurrent requests\n- Kinh nghiệm làm việc với cơ sở dữ liệu SQL (PostgreSQL, MySQL) và NoSQL (MongoDB, Elasticsearch)\n- Hiểu về queue systems như Kafka, RabbitMQ, hoặc Redis Pub/Sub\n- Có kinh nghiệm xử lý auth (JWT, OAuth2) và bảo mật API\n\n🖥 Frontend (Nắm Vững)\n- Kinh nghiệm làm việc với React/Next.js hoặc Vue.js\n- Hiểu cách tối ưu hiệu suất frontend (lazy loading, SSR, caching)\n\n🎛 Hệ Thống & Triển Khai\n- Biết làm việc với Docker, Kubernetes là lợi thế\n- Hiểu CI/CD pipeline, testing (unit/integration test)\n\nCHẾ ĐỘ QUYỀN LỢI\n\nTHU NHẬP\n- Lương tháng thỏa thuận theo năng lực ứng viên\n- Gói thu nhập 14-15 tháng lương/năm\n- Gói phúc lợi tiền mặt hơn 9 triệu/năm vào các dịp Lễ, Tết, Sinh nhật Tập đoàn...\n- Xét tăng lương theo năng lực và kết quả công việc định kỳ 1 lần/năm. Hoặc tăng lương đột xuất theo hiệu quả công việc.\n\nCHẾ ĐỘ ĐÃI NGỘ\n- Đóng BHXH đầy đủ và BH sức khỏe CMC Care ngay khi ký Hợp đồng chính thức\n- Nghỉ phép: 12 ngày/ năm + 1 ngày nghỉ hưởng lương vào dịp sinh nhật bản thân\n- Được tham gia các chương trình đào tạo chuyên môn, nghiệp vụ từ cơ bản đến nâng cao. Tài trợ 100% chi phí tham gia các khóa học, thi chứng chỉ CNTT Quốc tế\n- Được trang bị laptop/thiết bị công nghệ trong quá trình làm việc\n- Môi trường trẻ, năng động và chuyên nghiệp\n- Tham gia Team building và các hoạt động văn hóa đa dạng\n- Được vinh danh các giải thưởng năm của Tập đoàn CMC, CMC TS và khen thưởng trên các thành tích xuất sắc (dự án, kinh doanh, quản trị)\n- Thời gian nghỉ hàng tuần: Nghỉ Thứ 7 & Chủ nhật\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 16 Tòa CMC - Số 11 Duy Tân - Cầu Giấy - Hà Nội, Cầu Giấy\n\nNộp đơn ứng tuyển công việc này\n- Họ & tên bạn *\n- Địa chỉ email *\n- Số điện thoại *\n- CV của bạn *\n- Click để chọn & tải lên CV của bạn\n- Mã bảo mật *\n- Nộp đơn ứng tuyển', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1607, 820, 2, 'Junior Brse', 'MÔ TẢ CÔNG VIỆC\n\nPhân tích và trao đổi trực tiếp các yêu cầu với khách hàng bằng tiếng Hàn\n\nTham gia phân tích các yêu cầu dự án\n\nThảo luận chi tiết dự án với các thành viên và quản lý tiến độ dự án\n\nBáo cáo cho khách hàng Hàn Quốc về tiến độ của dự án cũng như mọi khó khăn hàng ngày và hàng tuần\n\nThực hiện đánh giá và kiểm tra dự án cũng như chịu trách nhiệm về kết quả của dự án\n\nTích cực lên đưa các ý tưởng, giải pháp phát sinh trong quá trình thực hiện nhằm nâng cao chất lượng và kết quả của dự án.\n\nYÊU CẦU\n\nCó khả năng giao tiếp tốt bằng tiếng Hàn (từ Topik 5)\n\nThành thạo sử dụng ít nhất một trong các ngôn ngữ: Java, Php, NodeJS, Ruby …\n\nCó kinh nghiệm về lập trình Web FE/BE...\n\nCó kinh nghiệm hệ thống (client-server,...)\n\nCó kinh nghiệm tối thiểu 1 năm trao đổi và làm việc trực tiếp (nghe, nói, đọc, viết) với khách hàng Hàn quốc trong dự án IT.\n\nCó kỹ năng quản lý; Tinh thần trách nhiệm cao; Chịu áp lực công việc tốt.\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 28 tháng 6, 2025\n\nChi tiết công việc\n\nSố Lượng\n1\n\nĐịa Điểm\nHà Nội\n\nKinh Nghiệm\n2 năm\n\nTrình Độ\nJunior\n\nHình Thức\nToàn thời gian\n\nKỹ Năng\nBrse', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1608, 682, 2, 'Kỹ sư Phát triển AI - AI Engineer (Python,C++) - Khối Công nghệ thông tin (HOLT.13)', 'Job Description:\n- Develop, apply, optimize, and integrate AI models for business and banking applications in areas such as Computer Vision and NLP.\n- Participate in service deployment stages: system architecture, model design, workflow, functionality, and performance optimization.\n- Perform coding, test metrics, service, and unit testing following DevOps and MLOps methodologies.\n- Research and study the latest scientific papers on AI, Machine Learning (ML), and Deep Learning (DL).\n- For talented students and freshers: participate in training programs and trainee projects aimed at development into official positions.\n\nJob Requirement:\n- Graduated from university in majors such as Information Technology, Computer Science, Telecommunications Electronics, Software Engineering, Information Systems, etc.\n- Preference for candidates with at least 1.5 years of equivalent experience.\n- Knowledge and skills in one or more of the following areas:\n- Programming languages: Python, C/C++\n- Service/Microservice development using frameworks like FastAPI, Flask, Django\n- TensorFlow, PyTorch, DGL, PyG, ONNX\n- APIs (RESTful/gRPC), secure programming, ensuring and optimizing performance\n- Git and Git Flow, Docker/Kubernetes, Kubeflow/MLFlow, Triton Server/TensorFlow Serving\n- Supervised learning, Reinforcement learning problems\n- Image processing (Computer Vision), Video, Audio, Natural Language Processing (NLP)\n- CNN, RNN, Transformer, Attention mechanisms; SVM, KNN, Clustering, GNN, etc.\n- Knowledge Distillation, Model Pruning, Model Quantization techniques.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1609, 702, 2, 'Senior Software Engineer (Java/Python/LLM)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nRole Overview\n\nThis role is pivotal in scaling our AI-driven Customer Service (CS) chat analysis. The specialist will manage data processing pipelines, optimize large language model (LLM) prompts, and collaborate closely with the existing project lead and cross-functional teams. The ultimate goal is to help expand classification coverage, drive bot adoption, and maintain high accuracy—all while ensuring faster delivery of new features and stakeholder requests.\n\nResponsibilities:\n\n- Work with data warehouse team, to maintain real time data pipeline of CS business domain, to ensure timely and high-quality data inputs to the AI models.\n- Design, implement, and refine LLM prompts for enhanced attribution analysis of CS conversations.\n- Work closely with Ops teams to increase the stability of LLM solutions in a cloud or on-prem environment.\n- Conduct A/B testing and iterative improvements on LLM performance, and maintaining result accuracy.\n- Develop and maintain back-end services and automation scripts using Java or Python, ensuring seamless integration with existing systems.\n- Troubleshoot performance bottlenecks, optimize code, and safeguard data security and privacy.\n- Collaborate with CS, BI, and SL teams to gather requirements, clarify feature demands, and communicate technical constraints.\n- Maintain clear, concise documentation of data work flows, LLM prompt templates, and best practices.\n\nQualifications:\n\n- Bachelor’s or Master’s degree in Computer Science, Data Science, or a related field.\n- 5+ years of hands-on experience in Java data processing and pipeline development.\n- Experience with SQL/NoSQL databases, ETL pipelines, and data workflow orchestration tools (e.g., Airflow).\n- Proficient in Java / Python (at least one language) and Hive & Spark SQL programming languages.\n- Hands-on experience with AWS, GCP, or Azure is a plus.\n- Experience with LLM or NLP projects is highly desired\n- Excellent communication and teamwork skills, with the ability to work in a cross-functional environment.\n- Fluency in English is required to be able to coordinate with overseas partners and stakeholders. Additional languages would be an advantage.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1610, 924, 2, 'PHP Developer', 'Btab provides Ecommerce and Social Commerce solutions to help businesses succeed in both the online and offline space.\n\nBtab is not only a technology company but also a Business Hub.\n\nThe Role\n\nJob Description\n\nWe are looking for a PHP Developer responsible for managing back-end services and the interchange of data between the server and the users. Your primary focus will be the development of all server-side logic, definition and maintenance of the central database, and ensuring high performance and responsiveness to requests from the front-end. You will also be responsible for integrating the front-end elements built by your co-workers into the application. Therefore, a basic understanding of front-end technologies is necessary as well.\n\nResponsibilities\n\nIntegration of user-facing elements developed by front-end developers\nBuild efficient, testable, and reusable PHP modules\nSolve complex performance problems and architectural challenges\nIntegration of data storage solutions {​{may include databases, key-value stores, blob stores, etc.}\n}Develop, test, and maintain PHP-based web applications\n.Write clean, well-structured, and maintainable PHP code\n.Work with MySQL databases, optimizing queries and database structures\n.Integrate third-party APIs and payment gateways\n.Collaborate with front-end developers to implement responsive and interactive web designs\n.Debug, troubleshoot, and resolve software issues\nMaintain documentation for all development work\nKeep up to date with latest web technologies and best practices\n\nIdeal Profil\n\nSkills And Qualification\n\nProven experience as a PHP Developer (3+ years preferred)\nStrong knowledge of PHP, MySQL, HTML, CSS, JavaScript, and AJAX\nExperience with PHP frameworks like Laravel, CodeIgniter, or Symfony\nUnderstanding of RESTful APIs and integration\nFamiliarity with version control systems (Git, GitHub, or Bitbucket)\nKnowledge of front-end technologies like React, Vue.js, or Angular (a plus)\nExperience with cloud services (AWS, Azure, or Google Cloud)\nKnowledge of Docker, Kubernetes, or CI/CD pipelines\nUnderstanding of WordPress, Magento, or other CMS platforms\nExperience in unit testing and debugging PHP applications\n\nWhat\'s on Offer\n\nWork within a company with a solid track record of success\nExcellent career development opportunities\nAttractive salary & benefit', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1611, 925, 2, 'Senior/ Lead Nodejs_HN/HCM_60M net', 'Responsibilities\n• System Design & Development:\nDesign, develop, and maintain high-performance execution engines and data pipelines that can handle large volumes of transactions with minimal latency.\nImplement and optimize multi-threaded, asynchronous systems to ensure seamless and efficient processing of trading operations.\nDevelop modular, scalable, and secure microservices architectures that can be easily extended and maintained.\n• Team Leadership & Collaboration:\nMentor, and provide technical guidance to a team of developers, ensuring best practices in coding, testing, and deployment are followed.\nCoordinate with other team members to align backend development with overall project goals.\n• System Monitoring & Maintenance:\nMonitor live trading systems for errors, performance bottlenecks, and potential security vulnerabilities.\nQuickly diagnose, debug, and resolve issues in a high-stakes trading environment.\nImplement logging, monitoring, and alerting systems to ensure maximum uptime and reliability.\n• Innovation & Continuous Improvement:\nStay up-to-date with the latest technologies, particularly in the areas of blockchain, NodeJS, and system architecture.\nPropose and implement improvements to enhance system performance, scalability, and security.\nParticipate in the research and development of new trading strategies and algorithms.\n\nRequirements\n\nMust-haves:\n• Technical Skills:\n• NodeJS: Deep understanding of NodeJS, including experience with REDIS, multi-threading, asynchronous programming, and messaging queues (e.g., Redis queue, Kafka, RabbitMQ).\n• Database Management: Proficiency in MongoDB, with a strong focus on query optimization and data management best practices.\n• System Architecture: Expertise in modularization, microservices, and interface design, with a focus on building scalable and maintainable systems.\n• Monitoring & Debugging: Extensive experience in system logging, monitoring, and debugging complex systems.\n• Mathematical skills: Comfortable with basic algebraic mathematics.\n\nGood-to-haves:\n• Additional Programming Skills: Familiarity with GO and Assembly languages.\n• Algorithmic Trading: Understanding of trading algorithms.\n\nBenefits\n• Paid Leave: 12 days of paid leave per year.\n• Work Environment: Autonomy and resources to ensure the successful completion of projects in a progressive company culture focused on results, growth, and human development.\n• Performance Reviews: Bi-annual performance reviews with opportunities for bonuses.\n• Profit Sharing: Option for profit sharing after 1 year of employment, contingent on good performance.\n\nInterview Process\n1. Coding Test: Assessment of coding skills relevant to the role.\n2. Math Test: Evaluation of mathematical and problem-solving abilities.\n3. Technical Interview: In-depth discussion of technical expertise and experience.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1612, 187, 2, 'NodeJS Developer', '1. RESPONSIBILITIES: \n- Participating in global software development projects (Ecommerce, airline,..)\n- Be active in self-research and sharing solutions for complicated technical problems\n- Carrying out assigned tasks to meet all deadlines and deliver quality results.\n- Contributing in designing & implement features to meet customer’s requirements & deadlines.\n- Working directly with clients to resolve ambiguities, finalize requirements and ensure technical deliverables meet business expectations.\n\n2. REQUIREMENTS\n- Experience with NodeJS, JavaScript, TypeScript.\n- 2+ year experience with NodeJS backend development, Experienced at least 1 project with NestJS.\n- Experience with cloud computing (AWS services, Google services).\n- Knowledge of web services integrations (REST/SOAP).\n- Good English to communicate directly with clients on a daily basis.\n- Excellent in object-oriented programming knowledge and experience.\n- Understanding of Design Patterns.\n\nHaving the following skills is an advantage:\n- Experienced with integrating with other systems, such as CRM, ERP, Payment Gateways is a bonus point.\n- Experience with CI/CD and deploying applications to AWS Cloud.\n- Experience with website performance optimization.\n- Familiar with the Agile model, having knowledge with TDD/BDD applied in Agile is a plus.\n\n3. BENEFITS\nAt SmartOSC, we offer the best to your values\n- Attractive salary package: up to USD 2,400.\n- Salary review twice a year.\n- Flexible working hours.\n- Premium health care.\n- Working in one of the largest digital transformation agencies – A professional English environment.\n- Free English, Japanese, and professional training packages.\n- Firm’s Certified Qualifications Sponsorship for career development.\n- Annual company trip inside or outside Vietnam.\n- Other fun activities: happy hour, quarterly team building, football club, yoga club, swimming club, charity activities, etc.\n- Free entertainment parties: Birthday party, Anniversary party, Sum-up Party, Year-End Party, etc.\n\n4. TO APPLY\nPlease submit your CV to huyenht1@smartosc.com with the following information:\n● Job Application Letter with “NodeJS Developer” in the subject line.\n● Updated CV in English, including your contact e-mail, phone number and salary expectations.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Région métropolitaine de Hanoï', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1613, 316, 2, '.NET Developer (all genders)', 'HRS reinvents how businesses Work, Stay and Pay. Counting more than 5.000 corporations and 40 % of Fortune 500 companies in our customer base, HRS has emerged to the most trusted platform of digital software solutions in business travel hospitality worldwide.\n\nThe HRS platform is composed of three engines that each optimize one core building block along the corporate hospitality supply chain: Intelligent Procurement, Smart Booking and Invisible Payment. Through the integration of those engines into one large data-driven platform approach, our Lodging-as-a-Service value proposition enhances satisfaction of corporate employees and travelers, delivers the highest grade of process automation for corporate stakeholders and ensures strongest compliance end-to-end.\n\nBUSINESS UNIT\n\nEnterprise Solutions is a business unit in HRS which integrates multiple solutions through the interchange of information from various business processes and related databases. Working in Enterprise Solutions means working on our core systems which enable our business processes on a daily basis.\n\nCHALLENGE\n- Develop, test, and maintain applications using .NET, Angular/ReactJS, HTML, CSS, SQL Server, MongoDB…\n- Collaborate with cross-functional teams to analyze the business requirement, design, and deliver the best solution.\n- Write technical specifications.\n- Write clean code following the best practices and coding standards.\n- Identify, analyze, and resolve bugs and issues promptly.\n- Design and manage databases using SQL-Server and MongoDB to optimize performance.\n- Perform a unit test to ensure the Product quality.\n- Participate in code reviews and provide constructive feedback to peers.\n\nFOR THIS EXCITING MISSION YOU ARE EQUIPPED WITH...\n- Bachelor’s degree in Computer Science, Engineering, or a related field. \n- At least 4 years of experience in .NET development.\n- Solid understanding of OOP, SOLID principles.\n- Proficiency in Front-end languages (HTML, CSS, Angular, ReactJS…) is a plus.\n- Knowledge of DevOps, CI/CD pipelines.\n- Proficiency in solving the system performance is a plus.\n- Experience with Azure cloud platform is a plus.\n- Knowledge of Miro-services architecture.\n- Experience with AI tools is a plus.\n- Familiar with Agile/Scrum methodologies.\n- Good at English communication.\n\nSoft Skills\n- Being eager and willing to learn new techniques.\n- Problem solving.\n- Critical thinking.\n- Communication and teamwork.\n\nPERSPECTIVE\nAccess to a global network of a globally united and mutually responsible “Tribe of Intrapreneurs” that is passionately dedicated to renew the travel industry and while doing so reinvent the ways how businesses stay, work and pay.\n\nOur entrepreneurial driven environment of full ownership and execution focus offers you the playground to contribute to a greater mission, while growing personally and professionally throughout this unique journey. You will continuously learn from a radical culture of retrospectives and continuous improvement and actively contribute to making business life better, smarter and more sustainable.\n\nLOCATION, MOBILITY, INCENTIVE\nThe attractive remuneration is in line with the market and, in addition to a fixed monthly salary, all necessary work equipment and mobility, will also include an annual or multi-year bonus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1614, 926, 2, 'Python Developer', 'SETA INTERNATIONAL VIETNAM - RECRUITMENT\nJob Title: Python Developer\nThe job description:\n- We are looking for a Python Developer to join our engineering team and help us develop and maintain various software products.\n- The Python Developer responsibilities include writing and testing code, debugging programs and integrating applications with third-party web services. To be successful in this role, you should have experience using server-side logic and work well in a team.\n- Ultimately, you’ll build highly responsive web applications that align with our business needs.\n\nYour Skills and Experience:\n- At least 6 months experience in Python programming language\n- Familiar with at least one of Python RESTful frameworks, e.g. FastAPI, Django\n- Have experience working with distributed, micro-service system is a bonus point\n- Familiarity with Cloud AWS\n- Good team and communication skills\n- Good at speaking English\n- Willing to learn new technologies and tools\n\nBenefits\n- Salary: negotiate\n- Attractive salary and bonus based on performance.\n- Full benefits for employees according to the Vietnam Labor Laws: social and health insurance\n- An international, professional, young but innovative, knowledge-shared environment works closely with international experts. Have the opportunity to join conferences and workshops on exciting new technologies.\n- Holidays based on Vietnamese labor law + paid vacations\n- Company trip, Team Building\n\nContact:\nSETA International Viet Nam\nAdr.: HL Tower, 82 Duy Tan, Ha Noi\nEmail: hr@setacinq.vn\nWebsite: https://www.seta-international.com/\nFanpage: https://www.facebook.com/SETA.International.careers/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1615, 674, 2, 'Research & Development Specialist - HRM Software', 'Mô tả công việc\n\nPhân tích nghiệp vụ (Business Analysis)\n- Nghiên cứu và phân tích quy trình nhân sự như quản lý hồ sơ nhân sự, chấm công, tính lương, tuyển dụng, đánh giá,… mang tính tự động hóa và ứng dụng cao.\n- Làm việc với các bên liên quan để thu thập yêu cầu, xác định vấn đề và đề xuất giải pháp phù hợp.\n- Soạn thảo tài liệu nghiệp vụ: BRD, user story, use case, sơ đồ quy trình...\n- Phối hợp chặt chẽ với UI/UX, QA và backend đảm bảo đúng định hướng sản phẩm theo thông lệ thị trường\n- Kiểm thử chức năng từ góc độ người dùng và đề xuất cải tiến.\n\nNghiên cứu & đề xuất giải pháp (R&D)\n- Phân tích hành vi người dùng B2B trong lĩnh vực nhân sự.\n- Đánh giá các sản phẩm HRM trên thị trường để đưa ra đề xuất.\n- Lên kế hoạch cải tiến rõ ràng\n- Theo dõi sát quá trình phát triển\n\nLập trình giao diện người dùng (VueJS 3)\n- Xây dựng các module giao diện HRM bằng VueJS 3 (Composition API).\n- Tạo component tái sử dụng, tối ưu hiệu suất và tốc độ tải trang.\n- Tích hợp API, xử lý dữ liệu nghiệp vụ.\n- Tuân thủ tiêu chuẩn kỹ thuật về bảo mật và maintainability.\n- Chuyển thiết kế từ Figma thành giao diện thực tế chính xác.\n\nYêu cầu công việc\n- Bắt buộc:\n  - Tối thiểu 3 năm kinh nghiệm làm việc ở vị trí PO phần mềm hoặc frontend developer, ưu tiên nếu từng làm cả hai.\n  - Hiểu biết sâu về quy trình nhân sự trong doanh nghiệp vừa và lớn.\n  - Có tư duy hệ thống, phân tích logic tốt, giao tiếp rõ ràng.\n  - Có kinh nghiệm làm việc với VueJS 3, REST API, Axios, Vue Router và Pinia hoặc Vuex.\n  - Đã từng viết hoặc tham gia xây dựng các tài liệu nghiệp vụ, user story, sơ đồ hệ thống.\n- Ưu tiên:\n  - Kinh nghiệm làm việc trong các dự án phần mềm HRM, ERP hoặc SaaS B2B.\n  - Có kiến thức UI/UX, có thể sử dụng Figma, Balsamiq để dựng wireframe/mockup.\n  - Biết cơ bản về backend để phối hợp tốt với kỹ sư backend (REST, DB, auth…).\n  - Tiếng Anh đọc hiểu tài liệu kỹ thuật tốt.\n\nTại sao bạn yêu thích làm việc tại đây\n- Lương căn bản: Up to 1500 USD + Commission + KPI Performance Bonus\n- Cơ hội nghề nghiệp: Học hỏi kiến thức về Nhân sự, Giáo dục\n- BHXH, BHYT theo quy định NN.\n- Thưởng các ngày lễ tết, lương tháng 13, lương hiệu suất cv, các chế độ phúc lợi khác theo quy định công ty.\n- Nghỉ 1 ngày trong tháng sinh nhật, phép thâm niên\n- Gói bảo hiểm sức khỏe Bảo Việt cho nhân viên làm việc trên 3 tháng.\n- Môi trường cởi mở, tự chủ trong công việc.\n- Lộ trình thăng tiến\n- Happy hour, team building, company trip\n\nĐịa điểm làm việc: 18 Ba Vì, Phường 4, Tân Bình\nThời gian làm việc: 8h30-17h30 (thứ hai – thứ sáu) (Nghỉ thứ 7 & CN)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1616, 808, 2, 'QA Engineer - Interns', 'Job Description\n\n- Participate in the requirements discovery, testing of the software product.\n- Using Waterfall model and Agile model in projects.\n- Build and execute test cases.\n- Use testing techniques such as black box testing, functional testing and regression testing\n\nRequirements\n\n- Senior college or university student.\n- Able to work full-time.\n- Careful, good logical thinking, passionate about experimenting.\n- Have a sense of responsibility, persistence.\n- Able to work under pressure, hardworking, proactive, and responsible.\n- Good communication skills\n- Proficiency in English is required, including speaking, listening, reading, and writing.\n- Having certification in testing courses is an advantage.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1617, 742, 2, 'Senior Full-Stack Test Engineer', 'Company Description\n\nKMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines:\n\n\nKMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions.\nKMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality.\nKMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors.\n\nJob Description\n\n\nExecute all testing activities (manual and automation) to improve product quality, work closely with the team (developers, business analysis, customer service, operation, etc.) to deliver the product success\nAddress the test automation needs in a methodical, detail-oriented manner with the help of robust analytical skills and problem-solving capacity\nAutomate functional, regression and/or performance acceptance tests\nHave complete responsibility to enhance end-to-end automated test coverage\nParticipate in sprint planning and work closely with the Scrum team to analyze requirements and provide necessary test recommendations (such as Feature Testing, Smoke Testing and Regression Testing in both manual and automation)\n\nQualifications\n\nGeneral Requirements:\n\n\nAt least an intermediate skill level of English.\nLikely having 4+ years of experience in both manual and automation testing depending on how fast your learning and developing technical capability\nStrong domain knowledge on web and mobile app testing expertise\nStrong analytical, debugging, and problem-solving skills\nStrong dedication to quality and a positive, collaborative attitude and approach to testing\nBeing a senior member of the engineering team, self-motivated; able to find opportunities for improvement and tackle them without external direction\nStrong in communication and collaboration abilities\n\nTechnical requirements:\n\n\n4+ years of experience in software testing, with a mix of manual and automation.\nSolid understanding of mobile app development lifecycle and mobile architecture including iOS and Android\nProficiency in developing automated test scripts and frameworks for web and mobile testing\nStrong hands-on experience with Java, Selenium, and TestNG for web\nExperience in using Appium with Java for mobile automation testing\nFamiliarity with mobile testing on device farms like Perfector, Kobiton, Sauce Labs.\nExperience with CI/CD tools (e.g., Jenkins, GitHub Actions)\n\nAdditional Information\n\n\nPerks You\'ll Enjoy\n\n\nWorking in one of the Best Places to Work in Vietnam\nBuilding large-scale & global software products\nWorking & growing with Passionate & Talented Team\nDiverse careers opportunities with Software Outsourcing, Software Product Development, IT Solutions & Consulting\nAttractive Salary and Benefits\nTwo performance appraisals every year\nOnsite opportunities: short-term and long-term assignments in North American (U.S, Canada), Europe, Asia.\nFlexible working time\nVarious training on hot-trend technologies, best practices and soft skills\nPremium healthcare insurance for you and your loved ones\nCompany trip, big annual year-end party every year, team building, etc.\nFitness & sport activities: football, tennis, table-tennis, badminton, yoga, swimming…\nJoining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,…\nFree in-house entertainment facilities (foosball, ping pong, gym…), coffee, and snack (instant noodles, cookies, candies…) \n\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1618, 927, 2, 'Lead Web Frontend Developer', 'Job Summary\nWe are partnering with a leading foreign bank is looking for a Lead Web Frontend Developer to drive the development of high-performance, secure, and scalable web applications. You’ll play a key role in shaping frontend architecture, leading technical direction, and collaborating closely with cross-functional teams to deliver exceptional digital experiences.\n\nResponsibilities\n• Lead the design and development of modern, high-performance frontend applications that support critical banking operations and customer experiences.\n• Translate UI/UX designs from Figma into clean, scalable code using frameworks like React, Vue, or Angular.\n• Collaborate with backend teams to integrate RESTful APIs, ensuring seamless and efficient data flow.\n• Optimize web applications through performance profiling, dynamic loading, and code splitting.\n• Review UI/UX feasibility, provide technical input to designers, and drive best practices across teams.\n• Work closely with cross-functional engineering managers and stakeholders across multiple regions.\n• Mentor and support junior engineers, helping build a world-class tech team.\n\nQualifications\n• Bachelor’s degree (or higher) in Computer Science or a related field.\n• Proficient in HTML, JavaScript, TypeScript, CSS/Sass.\n• Experienced with modern frontend frameworks (React, Vue, Angular).\n• Skilled in version control tools (e.g., Git).\n• Knowledge of web standards, accessibility, and best practices.\n• Strong communicator and collaborator, with experience in agile/Scrum teams.\n• Fluent in English or willing to learn Chinese to collaborate across global teams.\n• Proactive, logical thinker with strong judgment and passion for learning.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1619, 188, 2, 'Fullstack (Java, Reactjs) Developer', 'Perform development activities to build new and maintain existing WEB-based software systems using Java Frameworks, Front-end frameworks and databases.\n\nResponsibilities\n- Participate in developing web applications, new modules, features from beginning till end in the functional system (It can be Full-Stack from Frontend to Backend services and databases depends on skills and experiences).\n- Participate in analyzing requirements, design architecture, perform coding, unit tests, testing and technical documentation in line with user & system requirements to deliver source code, documents and test scripts that meet client’s needs and meet the release milestone.\n- Perform bugs fixing, maintaining, enhancement existing WEB application modules.\n- Assist Team Leads, Managers in reporting project status and deliverable estimations.\n- Perform code review and supports colleagues.\n- Conduct training & coaching team members in software engineering development if required.\n- Supports team leads on maintaining development environments if required to make sure smooth development.\n- Perform 3rd level support in and after office hours if needed to ensure fastest possible recovery to service. \n\nSkills & Qualifications:\n- Software development skills using Java, ReactJS are required.\n- Good problem-solving skills.\n- Communication skills: Intermediate-level English (especially reading and writing).\n- Ability to work independently, proactive problem solver.\n\nKnowledge & Experience:\n- Have at least 5-years experience in Full-stack development using Java 17 and Spring Boot/ Spring Framework and web development using ReactJS and related libraries e.g. Redux, Webpack, Babel, Gulp, Sass, Axios.\n- Experience with RESTful Web Service with Spring/Spring Boot \n- Experience coding multi-threaded Java applications\n- Experience in MySQL with stored procedures, SQL and index\n- Experience in application performance troubleshooting\n- Understand OOP concepts and design patterns\n- Able to perform code review and give suggestions on solutions and designs\n- Experience in Junit and Jet.\n\nPLUS points:\n- Well design and develop web application with a large number of concurrent users and with high performance requirement is a BIG PLUS.\n- Experience with Java 21 is a PLUS.\n- Experience/Knowledge on any of Redis, Elasticsearch is a PLUS.\n\nBenefit:\n(*) BONUSES & REWARDS\n- Competitive Salary\n- 13th Month Salary & Performance Bonus \n- Employee of the Year Award\n\n(*) TRAINING & DEVELOPMENT\n- In-house & Overseas Training\n- Full reimbursement for international Technical Certification \n- Global career opportunity\n\n(*) ANNUAL PAID LEAVES\n- Vacation Leave: 12 days per year\n- Medical Leave: 8 days per year\n- 1 extra seniority day for every 3 years of service\n\n(*) HEALTHCARE\n- Annual Routine Check-up\n- Premium Healthcare Insurance \n- Comprehensive Insurance\n\n(*) WELLNESS AND LEISURE ACTIVITIES\n- Annual Team Building\n- Soccer & Badminton Club and Sports activities\n- Entertainment activities: Music band, Karaoke & Play-station time\n- Celebrations special events: Birthdays, Christmas, New Year/Year-end Party.\n\n(*) PERKS\n- Fruits Days Twice a Month\n- Unlimited snacks & beverages', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1620, 532, 2, 'Fullstack Developer (TypeScript)', 'Sunbytes is a leading Tech & Talent Solutions company known for innovative and scalable solutions. We focus on achieving goals for our partners and team members, delivering high-quality products and services, and fostering a supportive, challenging work environment. Our diverse team shares a common purpose, making Sunbytes a great place to work.\n\nWe offer comprehensive long-term partnerships, including recruitment, dedicated worldwide talents, and custom software development, tailored to meet client needs.\n\nJoin Us Are you a seasoned Fullstack Typesrcipt Developer with a passion for building modern web applications? Sunbytes seeks a dynamic developer to join our innovative team and contribute to exciting projects.\n\nAbout The Role Sunbytes is looking for a Fullstack Typesrcipt Developer with a passion for building scalable and efficient web applications using modern technologies like React and NodeJS. If you are someone who thrives in an agile, collaborative environment and enjoys working on diverse projects ranging from cutting-edge apps to legacy system improvements, we’d love to hear from you!\n\n• Design, develop, and maintain scalable and efficient web applications using JavaScript frameworks like React and NodeJS.\n• Work directly with clients to gather requirements, understand business needs, and provide technical solutions and guidance.\n• Support and improve existing legacy systems when needed, ensuring smooth functionality.\n• Follow best practices like SOLID, YAGNI, and KISS principles to ensure that code is maintainable, efficient, and scalable.\n• Prioritize tasks and maintain transparent communication with the project team and stakeholders to ensure alignment with project goals.\n\nRequirements\nTechnical skills\n• Bachelor\'s degree in Computer Science or a related field.\n• More than 3 years of proficiency in JavaScript/TypeScript, particularly with frameworks like React and NodeJS.\n• Solid understanding of the software development life cycle (SDLC) and Agile methodologies.\n• Follow best coding practices like SOLID, YAGNI, and KISS principles.\n• Experience in setting up and maintaining CI/CD pipelines is a plus.\n\nSoft Skills\n• Excellent communication and organization skills, with the ability to work across different time zones and collaborate with international teams.\n• Proactively learns and explores new technologies and approaches beyond the job scope.\n• Adjusts to new challenges, technologies, and project requirements.\n\nBenefits\n• A challenging and supportive work environment with opportunities to develop your career.\n• A dynamic and international team, providing a great career journey.\n• 16 days annual leave.\n• 3 sick days per year.\n• 4 creative days per year where you can explore new techniques and possibilities.\n• Premium Health Insurance 24/7.\n• Cover Social Insurance as local law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1621, 928, 2, 'EMBEDDED SW ENGINEER (FBL Topic)', 'Location Ho Chi Minh City, Vietnam\n\nFORVIA HELLA is a listed, international automotive supplier. Coming together with Faurecia in the FORVIA Group, we build the world\'s seventh largest supplier of automotive technologies. As a global market leader in high-growth areas, FORVIA employs 157,000 people worldwide. FORVIA HELLA therein stands for high-performance lighting technology and automotive electronics. At the same time, we cover a broad service and product portfolio for the spare parts and workshop business as well as for manufacturers of special vehicles with our Business Group Lifecycle Solutions. With around 37,500 employees at over 125 locations, the Company is active worldwide and generated adjusted sales of € 8.1 billion on a preliminary basis in the fiscal year 2023.\n\nYOUR TASKS\n\nIn the business division Electronics, you will be working with the software development team for electronics control units.\n\n▪ Design, develop & test product-specific software of automotive electronics module & system over the entire product development cycle;\n\n▪ Apply model-based development on a distributed embedded system;\n\n▪ Work on SW-architecture, write, test and debug code according to software requirement specification and the defined process;\n\n▪ Discuss with customer about specific solution for electronics modules & system, including function implementation and system interface;\n\n▪ Complete software module test report and integration test report according to test result;\n\n▪ Primarily responsible of software modules of HELLA products;\n\n▪ Other job assigned by Department Manager.\n\nYour Qualifications\n\n▪ Minimum bachelor degree in computer science, engineering, or related field.\n\n▪ 2-5 years experience in Embedded System.\n\n▪ Embedded development tool especially Rhapsody, Polyspace, WindIdea, Davinci, DOORs, PTC…\n\n▪ Be proficient with C programming language, firmware, bare-metal programming.\n\n▪ Be familiar with embedded microcontroller 16-/32-bit microprocessor is a plus.\n\n▪ Write and review Software specifications, Architecture and Design documents for the system.\n\n▪ Experience with simulation and development tools, e.g. Vector CANoe, etc\n\n▪ Real Time Operating System OSEK Programming Experience Preferred\n\n▪ Knowledge on Communication & Diagnostic protocols: CAN, LIN, Ethernet and TCP/IP protocols and UDS.\n\nRequired Skills\n\n▪ Knowledge and skills related to AUTOSAR, CAN, MEM, UDS, RTOS.\n\n▪ Experienced with Flash Bootloader\n\n▪ Good communication in English and presentation skills.\n\n▪ Familiarity with Agile methodology is an advantage.\n\nEven if you do not meet all our requirements, do not hesitate to apply to us, because the further development of our employees is very important to us and opens up a wide range of opportunities for you in our company.\n\nFORVIA HELLA stands for the variety of all employees. Inclusion and diversity are firmly anchored in our company culture. We are continuously looking for new team players and welcome applications from all interested parties, regardless of their ethical and social background, age, religion, gender, disability, sexual orientation or identity.\n\nPlease send us your application via our career portal, stating your salary requirements and earliest possible starting date, with the reference number req16448.\n\nHELLA Vietnam Co., Ltd.\n\nVong Nguyen', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1622, 709, 2, '[Hà Nội/Hải Phòng/Quảng Ninh] Giáo viên part-time giảng dạy stem', 'Giáo viên/Chuyên môn\n\nTừ Không yêu cầu kinh nghiệm kinh nghiệm\n\nLiên Hệ Ứng Tuyển Tại\ntuyendung@teky.edu.vn hoặc 02471096668\n\nThu nhập: 2.000.000đ - 7.000.000đ/tháng\nHạn nộp hồ sơ: 30.09.2025\nPhòng ban: Giáo viên/Chuyên môn\nThời gian làm: Partime\nKhu vực: Hà Nội, Quảng Ninh, Hải Phòng\nSố lượng: 12\n\nGửi hồ sơ ứng tuyển\n\nThông tin công việc\n\nThời gian làm việc: Đăng ký theo ca linh hoạt\nNơi làm việc:\nTeky Hội sở chính [Hà Nội]: Số B-TT01-51-53 Khu nhà ở Ngân Hà Vạn Phúc, phường Vạn Phúc, quận Hà Đông, TP Hà Nội\nTeky Hoàn Kiếm: Số 96 Hai Bà Trưng, Cửa Nam, Hoàn Kiếm, Hà Nội\nTeky Cầu Giấy: Tầng 3, Toà Nhà Thanh Chân, Số 6 Nguyễn Thị Thập Trung Hòa Nhân Chính, Quận Cầu Giấy, Hà Nội\nTeky Long Biên: Số 414 Nguyễn Văn Cừ, Bồ Đề, Long Biên, Hà Nội\nTeky Hải Phòng: 73 Điện Biên Phủ, Minh Khai, Hồng Bàng, TP Hải Phòng\nTeky Hạ Long: SH4 Times Garden, Đường 25 tháng 4, Bạch Đằng, Hạ Long, Quảng Ninh\nTeky Minh Khai: Tầng 3, số 463 Minh Khai, Vĩnh Tuy, Hai Bà Trưng, Hà Nội\nTeky Linh Đàm: Biệt thự 27, TT4A Khu Biệt Thự Tây Nam Linh Đàm, Hoàng Liệt, Hoàng Mai, Hà Nội.\nTeky Bắc Từ Liêm: LKC37, Dự án khu nhà ở thấp tầng A1TT1, Xuân Tảo\n\nBộ môn Lập trình & phát triển ứng dụng.\nTham gia giảng dạy (hoặc trợ giảng) lập trình, sử dụng các ngôn ngữ: Python, Scratch, HTML, Mobile App, JAVASCRIPT, JAVA.\nTham gia các buổi seminar, training.\n\nBộ môn Điện tử tự động & Robot.\nTham gia giảng dạy, trợ giảng đối với các môn học thuộc bộ môn điện tử – tự động hóa như: Lego Mindstorm, Arduino, Raspberry Pi...\nTham gia các buổi seminar, training.\n\nBộ môn Công nghệ 3D & Truyền thông đa phương tiện\nTham gia giảng dạy, soạn giáo án, dựng khung chương trình, trợ giảng đối với các môn học thuộc bộ môn vẽ tay 3D, In 3D, Quay phim, Làm phim, Nhiếp ảnh....\nTham gia các buổi seminar, training\n\nYêu cầu ứng viên\nĐang theo học, Tốt nghiệp Đại học các chuyên ngành Sư phạm, khoa công nghệ thông tin.\nLà giảng viên đã và đang giảng dạy tại các trường cấp 1, cấp 2 bộ môn Tin học, Công nghệ thông tin.\nĐang làm việc tại các công ty Truyền thông, Công nghệ thông tin.\nĐang là sinh viên đang theo học khoa CNTT, Điện tử – tự động, mỹ thuật,.truyền thông đa phương tiện, ......... của các trường cao đẳng, đại học liên quan.\n\nQuyền lợi được hưởng\nThu nhập trung bình từ 2 – 7 triệu/tháng (Theo bậc)\nCông việc lành mạnh, văn hoá doanh nghiệp giàu bản sắc\nCơ hội làm việc trực tiếp tham gia các dự án giáo dục mang tính quốc tế cao, có sự tham gia của các doanh nghiệp hàng đầu về giáo dục và công nghệ tại Mĩ, Hàn Quốc, Nhật Bản ...\nThường xuyên tham gia các buổi đào tạo kĩ năng chuyên môn và kiến thức sư phạm, công nghệ hàng tháng.\nĐược làm việc trong môi trường Giáo dục năng động, chuyên nghiệp, cơ sở vật chất hiện đại.\nCơ chế đặc biệt khi hoàn thành nhiệm vụ.\nGửi hồ sơ ứng tuyển', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Hà district, Quang Ninh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1623, 929, 2, 'Flutter Developer (SQLite/MySQL)', 'Responsibilities\n- Develop and maintain cross-platform mobile applications (iOS and Android) using Flutter.\n- Design, build and optimize user interfaces to ensure smooth, friendly experiences.\n- Integrate and process data from backend APIs into applications.\n- Work with SQLite or MySQL to build and optimize databases for mobile applications.\n- Analyze and fix errors, debug and improve application performance.\n- Coordinate with related departments (design, testing, product management) to ensure project quality and progress.\n- Participate in writing technical documents and application user manuals.\n\nQualifications\n- 1 year of experience developing Flutter applications and Dart language.\n- Experience with SQLite or MySQL is an advantage.\n- Good understanding of mobile application development lifecycle, build and release tools (Android Studio, Xcode...).\n- Ability to work independently and in a team.\n- Logical thinking, problem solving ability and quick learning.\n\nBenefits\n- Salary is negotiable depending on ability.\n- Good treatment. Enjoy full benefits of the Company and welfare according to labor law, pay social insurance, health insurance, unemployment insurance.\n- Consider salary increase according to ability and work efficiency.\n- Work in a dynamic, friendly and professional environment, with many opportunities for promotion and development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1624, 776, 2, 'Junior/ Middle Low-Code/No-Code Engineer', 'LOGIX TECHNOLOGY is a distinguished software services company, specializing in the provision of professional software development services, fostering strong partnerships through the establishment of offshore development centers, offshore product development, and software testing with an infrastructure-oriented approach. We excel at simplifying and enhancing offshore outsourcing, not only by delivering innovative solutions to meet our clients’ exact requirements through high-performance teams but also by significantly contributing to our clients’ success by reducing time-to-market and improving quality.\nAt LOGIX TECHNOLOGY, we are committed to delivering the highest level of professional excellence and making a significant impact in the software development sector. If you are a dedicated professional looking to join a dynamic team working with global leaders, we encourage you to explore the exciting opportunities that await you with us.\n\nJob Description\n- Review and analyze system specifications.\n- Learn basic knowledge on low-code/no-code systems and get hands-on experience on ClientTrack, UiPath, RPA related.\n- Customize and configure forms, workflows, workspaces, and dashboards in client environments.\n- Manage a queue of tickets and escalate tickets to ensure rapid resolution times.\n- Work closely with Client Managers, developers, database administrators, and subject matter experts to address client needs and proactively resolve issues.\n- Utilize SQL and the front and back end of databases to identify and resolve issues.\n- Apply critical thinking/problem-solving skills in working with clients and cross-functional teams on client support initiatives.\n\nRequired skills & experience\n- At least 02 years – experience as a low-code/no-code engineer.\n- Have experience with platform ClientTrack, Bubble, Power App, etc.\n- Excellent oral and written communication skills.\n- Have a working knowledge of programming, in program SQL.\n- Have logic developer and business sense.\n- The ability to quickly learn the Client’s platforms to effectively support clients using the application.\n- A drive to resolve complex, challenging, or escalated Issues.\n- Experience with SQL and relational databases.\n- Experience in a customer-facing role, managing issues, concerns, deadlines, and escalations.\n- Have knowledge on HMIS, Healthcare, ERP, etc… business domains is a plus.\n- Bachelor’s degree, IT background is a plus.\n- Strong analytical and solution design skills.\n- Strong technical skills to troubleshoot and resolve issues.\n- Troubleshooting experience in a technical, software, or IT role.\n- Experience in software configuration, customizations, or implementation roles preferred.\n- Strong organizational skills and attention to detail.\n\nBenefits & Perks\n- Attractive Salary & Benefits, full salary in probation.\n- Performance appraisal twice a year, 13th-month salary.\n- Healthcare and incident insurance.\n- 16 Paid Leave days / year (12 Annual Leave, 02 Summer Leave ,01 Birthday Leave & 01 Christmas Leave).\n- Company trip, annual year-end party, team building activities.\n- Diverse careers opportunities with Software Services, Software Product Development.\n- Working and growing in a value driven, international working environment and standard Agile culture with passionate and talented teams.\n- Various training on hot-trend technologies, best practices, and soft skills.\n- Free in-house entertainment facilities: football, table football, PS, badminton, trekking…coffee, and snacks (instant noodles, cookies, candies…).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1625, 930, 2, 'Web Developers (PHP/.Net)', 'Under general direction, the PHP or .NET Developer will design, develop, and produce a variety of web applications to support company and client needs.\n\n Build user interface applications and back-end databases using PHP, HTML, JavaScript and MySQL or .NET and SQL Server\n\n Participate in all phases of project lifecycle: planning, designing, developing, testing, debugging, maintaining, and updating.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1626, 931, 2, 'Backend Engineer (Java, Golang, Python)', 'Company Description\n\nCarousell Group is the leading multi-category platform for secondhand in Greater Southeast Asia on a mission to make secondhand the first choice. Founded in August 2012 in Singapore, the Group has a leading presence in seven markets under the brands Carousell, Carousell Media Group, Cho Tot, Laku6, LuxLexicon, Mudah.my, OneShift, REFASH and Revo Financial, serving tens of millions of monthly active users. Carousell is backed by leading investors including Telenor Group, Rakuten Ventures, Naver, STIC Investments, 500 Global and Peak XV Partners (formerly known as Sequoia Capital India).\n\nAs a team of passionate individuals working together to solve meaningful problems, there is so much more for you to discover in a career with Carousell. Our culture is made up of hiring, developing, and promoting people who embody our values of HEART, which is an acronym for Humility, Empathy, Accountability, Relentlessly resourceful and Teamwork. Together as an organisation, we make magic happen.\n\nAbout Cho Tot\n\nEstablished in 2012, Chotot.com is the first re-commerce platform in Vietnam pioneering classified 4.0 with more than 1 billion page views every month. On average, 9 out of 10 Vietnamese people are aware of Cho Tot when asking about selling and buying in any category. With the motto “Muốn Là Có” (“A Way to Your Wants”), we leverage technology to build a simple, efficient, and reliable platform that meets all the wants and needs in all stages of your life. There are more than 60 categories on Chotot.com, meaning whether you are looking for a house, a car, a job, a pet, or a piece of vegetable, you can find them on our site. Whether you are passing things you once loved or giving them to people in need, we are here to assist.\n\nAt Cho Tot, you will be part of our young and dynamic team in a fast-moving and fun-loving environment. You will receive opportunities to reach all the potentials you can think of in your career ladder. Cho Tot provides a competitive salary and full benefits. More importantly, we are a family within the company to support each other to learn, grow and immerse in new experiences every day. Every member of our family will be there with you on your path of passion to deliver the best online classified site to serve Vietnamese people. Being part of a bigger global organization, at Cho Tot you will also be given opportunities to collaborate with global distributed teams across the world to tackle and provide solutions for some of the most challenging problems in the emerging internet business space. Since 2019, Cho Tot is part of Carousell.\n\nJob Description\n\nCho Tot team is expanding to continuously innovate our marketplace ecosystem to better serve Vietnamese via advanced technology. We are looking for talented and passionate individuals to join our foundation software, engineering team. You will be one of the few key talents who build and run services that are used by tens of millions of Vietnamese people. You will need to tackle highly scaled distributed systems, work in a highly automated devops environment on top of many open source, CNCF software. You will be supported by our solid SRE team to really craft the software and run the product that you are proud of and other engineers admire.\n\nWhat you will do:\n\n- Solve engineering problems to enable a smart Marketplace ecosystem of products and services.\n- Design, Build, Run and improve backend services and framework of creating microservices.\n- Manage individual project priorities, deadlines, and deliverables.\n- Improve engineer efficiency with common libraries, tooling, and platform.\n\nWhat’s in it for you?\n\n- Join plenty of Sharing and Learning activities as part of our initiatives to contribute to the tech community in Vietnam\n- Get 15 days of annual leave and 5 days of sick leave per year\n- Health insurance for employee and their family members\n- Get 13th month salary and annual performance bonus\n- Participate in regular team building activities and company parties\n- Get opportunities to attend training courses abroad\n\nQualifications\n\nWhat you will need:\n\n- Experience working with one or more from the following: web application development, Unix/Linux environments, distributed systems, machine learning, networking, developing large software systems.\n- At least 3 years of experience in Golang or confident that you can pick it up in no time.\n- Solid production experience with one or more general-purpose programming languages including but not limited to C/C++, Python, Java, Javascript ES6.\n- Experience with two or more data systems but not limited to Postgres, MongoDB, Elasticsearch, Redis, Kafka, Cassandra.\n- Experience with Docker, Kubernetes.\n- Familiar with Microservices, event-driven architecture.\n- BA or MA degree in engineering, computer science, or another technical related field. Or formerly competitive programmer.\n\nAdditional Information\n\nThank you for taking your time to read our job description and thank you in advance if you decide to apply for this position. Shortlisted candidates will be contacted within 2 weeks since application, otherwise we might meet when another chance arises.\n\nBy proceeding with your application, you are adhering to our PDPA policies. In case you are interested to know more, read about our Candidates Personal Data Privacy Statement.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1627, 723, 2, 'Junior .NET Developer', 'Mô Tả Công Việc\n\n• Tham gia phân tích thiết kế hệ thống, thiết kế Database, thiết kế chi tiết\n• Tham gia lập trình, kiểm thử sản phẩm Web Application (.NET), Winform Application\n• Làm việc với ASP.NET – MVC – AngularJS…\n• Làm việc với .NET trên Winform Application\n• Cải tiến và nâng cao chất lượng dự án.\n\nQuyền Lợi\n\n• Mức thu nhập cạnh tranh theo thỏa thuận\n• “NMS care” bảo hiểm dành riêng cho nhân viên NMS.\n• Nghỉ hè: Theo chính sách của công ty ( vào tháng 5 hàng năm).\n• Có cơ hội được xem xét nâng lương 2 lần 01 năm, tùy vào kết quả công việc.\n• Môi trường làm việc hiện đại, thân thiện\n• Chính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.\n\nYêu Cầu\n\n• Kinh nghiệm thực tế từ 2 năm trở lên\n• Tốt nghiệp Đại học/Cao Đẳng hoặc trung tâm đào tạo lập trình viên ngành Công nghệ thông tin.\n• Sử dụng thành thạo ngôn ngữ lập trình ASP.NET\n• Có kiến thức về jQuery, Javascript, HTML, CSS, SQL Server\n• Hiểu biết và nắm rõ các qui tắc, khái niệm lập trình OOP\n• Kĩ năng tự học hỏi và nghiên cứu tốt\n• Tiếng anh giao tiếp khá trong công việc (Môi trường đa quốc gia)\n• Đọc hiểu nhanh tài liệu tiếng Anh chuyên ngành (phục vụ cho việc google search )\n• Nhanh nhẹn, ham học hỏi, tinh thần trách nhiệm cao, trung thực, cẩn thận.\n• Có định hướng phát triển bản thân theo tác phong làm việc Nhật Bản\n\nĐịa điểm làm việc: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình\n\nỨng Tuyển Ngay\nMs Huyền: 0969.709.429 / mail:huyenlt@nms.com.vn / skype:huyenthu.hr\n\n——————————–\n\nCông ty cổ phần Dịch vụ Di động Thế Hệ Mới (NMS)\n\n🏬 Hệ Thống Trụ Sở\n\n– Trụ sở chính NMS: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình, Hà Nội\n\n– Chi nhánh NMS Hòa Lạc: Tầng 8, Tòa nhà HTC Phú Cát, Khu công nghệ cao Hòa Lạc, Thạch Thất, Hà Nội\n\n– Chi nhánh NMS TP. Hồ Chí Minh: Lầu 3 – 385C – Nguyễn Trãi Quận 1 – TP. HCM\n\n– Chi nhánh Nhật Bản: 3F Hoshino Building, Nishi Shinjuku, Shinjuku, Tokyo\n\n☎ Điện thoại: 024.7300 8555\n\n🌎 Website: https://nms.com.vn/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1628, 932, 2, 'Back End Developer', 'Responsibilities:\n- Application Development: Design, develop, and maintain robust web applications aligned with business objectives.\n- System Architecture: Construct high-performance system architectures and optimize code for scalability and efficiency.\n- Quality Assurance: Implement comprehensive unit and integration testing strategies to ensure application reliability and performance.\n- Collaboration: Partner with product teams to translate user requirements into scalable, user-friendly solutions.\n- Incident Resolution: Contribute to post-mortem analyses and incident management processes to enhance system reliability.\n- Additional Duties: Perform other duties as assigned.\n\nRequirements:\n\n- At least 4 years of experience with Java (Smartfox Server, Photon Server) and Golang.\n- Strong technical expertise in:\n  - Databases: NoSQL, MySQL, MongoDB, Redis\n  - Messaging systems: RabbitMQ, ActiveMQ, Kafka\n  - Microservices: Design and implementation\n  - Frameworks: Spring Boot, Hibernate, WebSocket\n  - Cloud & Containerization: AWS, Docker\n  - Programming languages: Java, Golang, SQL\n  - Performance optimization: database indexing, partitioning, sharding, and concurrent programming\n- A fast learner who thrives in a dynamic start-up environment.\n- Experience with real-time and low-latency data processing architectures.\n- Hands-on experience with large-scale database design, including partitioning and sharding.\n- Able to independently research and explore new technical domains.\n- Experience managing cloud-based distributed databases.\n\n📧 Apply Now:\nPlease send your resume CV and a brief cover letter to helentran.muf@gmail.com or apply directly through My LinkedIn.\nLet’s shape the future of our online presence together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1629, 912, 2, 'Manual Tester', 'CAREERS\n\nWork With Us\n\nExplore exciting career opportunities and become part of our dynamic team.\n\nManual Tester\n\nQuantity: 02\n\nWorking Hours: 08:00 – 12:00, 13:30 – 17:30, Monday to Friday\n\nWork Location: Lot 05 – Lot 06 Area A2, Phuong Trang high-rise commercial urban complex, Nguyen Sinh Sac Street, Hoa Minh Ward, Lien Chieu District, Da Nang, Vietnam\n\nResponsibilities\n\nKey Responsibilities:\n\nCommit to contributing personal value toward the company’s and department’s common goals.\nCommit to achieving personal objectives as set.\n\nJob Responsibilities\n\nParticipate in the development of the company’s products, including receiving and analyzing project requirements from the product research and development team.\nCreate test plans, write test cases, and prepare test data for the company’s products.\nExecute software testing based on test cases, identify bugs, and document issues.\nManage and analyze test results to ensure product quality.\nReview and verify the final product before deploying production.\nProvide timely and detailed reports on the product’s progress and quality to department heads.\nCollaborate with cross-functional teams to ensure that product quality meets business requirements.\nPerform other tasks as assigned by the Board of Directors or department leaders.\n\nRequirements\n\nMinimum Qualifications:\n\nExperience: At least 2 years of experience in software testing.\nEducation: A college or university degree in Information Technology or a related field.\nTechnical Skills:\n\nProficiency in testing tools such as Charles and Postman.\nStrong experience in API and database testing.\nDeep understanding of software development processes.\nComprehensive knowledge of testing stages (Unit Test, Integration Test, System Test, Acceptance Test, etc.).\n\nSoft Skills:\n\nLogical thinking and quick understanding of business concepts.\nStrong analytical and problem-solving skills.\nAbility to work independently and collaboratively in a team environment.\nA proactive attitude, professionalism, and high responsibility.\n\nLanguage Skills: Proficiency in reading and writing English.\n\nPreferred Qualifications (Nice-to-Have)\n\nExperience in product-oriented projects, particularly in Affiliate Marketing or SaaS platforms.\nFamiliarity with Agile/Scrum software development methodologies.\nHands-on experience in deploying projects with a large user base.\nPossession of relevant Tester certifications.\nKnowledge or experience with Automation Testing is a plus.\n\nBenefits\n\nSalary: 12,000,000 VND – 25,000,000 VND (based on experience and performance).\nPerformance Reviews: Salary adjustments every 6 months based on demonstrated capability.\nEquipment: Fully equipped with necessary working devices (e.g., MacBook).\nProbation Period: Receive 85% of the official salary during the probation period.\nBonuses: 13th-month salary and additional holiday bonuses throughout the year.\nHealth Check-Ups: Annual check-ups at top-tier hospitals.\nInsurance: Full compliance with Vietnamese labor laws regarding social insurance and welfare benefits.\nLeave: 12 annual leave days and all Vietnamese public holidays.\nAllowances: Travel and lunch allowances, plus free drinks and coffee at the office mini bar.\nWork Environment: A dynamic and friendly working environment with talented colleagues.\n\nHow To Apply\n\nSubmit your CV via email to: tuyendung@permate.com\n\nSubject Line: Application for Manual Tester Position – [Your Name]', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'دا نانغ دا نانغ فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1630, 751, 2, 'Developer (.NET)', 'Company Description\n\nTechnology is our how. And people are our why. For over two decades, we have been harnessing technology to drive meaningful change.\n\nBy combining world-class engineering, industry expertise and a people-centric mindset, we consult and partner with leading brands from various industries to create dynamic platforms and intelligent digital experiences that drive innovation and transform businesses.\n\nFrom prototype to real-world impact - be part of a global shift by doing work that matters.\n\nJob Description\n\nDevelopment is the largest discipline at Endava. Our developers design, build, and release software products in multiple programming languages, frameworks, and libraries. Always collaborating with cross-functional project teams, our developers are adaptable problem-solvers with a client-oriented mindset.\n\nAs a Developer at Endava, you are responsible for implementing and delivering high-quality software products using Agile Scrum methodology. As a part of a global project, you can contribute your technical expertise and experience in order to the project succeed.\n\nResponsibilities:\n\nParticipates actively in all phases of application development lifecycle.\nRecommends and promotes IT industry standards, tools, practices (DevOps, etc.) to achieve well-engineered software products.\nProposes improvements and escalates risks/issues related to development activities.\nLearns and applies new technologies, practices, and tools as appropriate to the project.\nParticipates in internal and external tech communities, events.\nShares experience and knowledge gained from projects.\nHas responsibility for the work of others and for allocating resources.\n\nQualifications\n\nMandatory skills:\n\n2+ years of experience in backend development for commercial projects using .NET, familiar with .NET Core for building web APIs and microservices.\nUnderstanding of design principles and patterns (SOLID, Dependency Injection).\nExperience in relevant programming languages, frameworks and tools such as C#, .NET Framework, .NET Core, ASP.NET, Entity Framework, LINQ, Visual Studio, Azure Fundamentals.\nPractical experience in platform specific database systems and SQL.\nExperience with Agile methodologies (e.g., SCRUM, KANBAN)\nGood communication in English.\n\nNice to have:\n\nExperience with developing dynamic, responsive web applications using Angular or React.\nSociable, proactive, team player & fast learner.\n\nAdditional Information\n\nDiscover some of the global benefits that empower our people to become the best version of themselves:\n\nFinance:\nCompetitive salary package, share plan, company performance bonuses, value-based recognition awards, referral bonus;\nCareer Development:\nCareer coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership;\nLearning Opportunities:\nComplex projects, rotations, internal tech communities, training, certifications, coaching, online learning platforms subscriptions, pass-it-on sessions, workshops, conferences;\nWork-Life Balance:\nHybrid work and flexible working hours, employee assistance programme;\nHealth:\nGlobal internal wellbeing programme, access to wellbeing apps;\nCommunity:\nGlobal internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations.\nAnnual leave encashment;\n13th month salary;\nPremium annual health check & Extra health & accident insurance;\nWelcome kit and gift-giving frequency;\nAttractive benefits of Trade Union;\nExciting English programme.\n\nAt Endava, we’re committed to creating an open, inclusive, and respectful environment where everyone feels safe, valued, and empowered to be their best. We welcome applications from people of all backgrounds, experiences, and perspectives—because we know that inclusive teams help us deliver smarter, more innovative solutions for our customers. Hiring decisions are based on merit, skills, qualifications, and potential. If you need adjustments or support during the recruitment process, please let us know.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミン市 ホーチミン, ベトナム', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1631, 703, 2, 'QC Engineer', 'About Us\n\nKegmil is revolutionizing the way mission-critical facilities and assets are repaired and maintained via complex systems of people and processes. We are on a mission to empower millions of deskless field service professionals in Southeast Asia with technology and data to supercharge their operational efficiency and service performance. Our cloud-based, mobile-first software intelligently automates and optimizes field activities for maintenance heroes who keep our world running across industries from elevator to data center equipment servicing.\n\nWe are a curious and collaborative team that derives purpose and joy from putting our customers at the center of our innovation, helping them to transform and grow their businesses profitably. Our culture also inspires our employees to be their best in an inclusive and supportive environment. We listen to and learn from one another, take ownership and deliver on our promises with grit, resilience and speed to lead the age-old field service industry into the future.\n\nRole\n\nKegmil is in search of a QC Engineer with 2-3 years of experience, adept at both manual and automated testing, and possessing a positive attitude with a willingness to learn. As a valued member of the product-core development team, your role will involve contributing your insights and efforts to ensure the successful launch of our product, meeting and exceeding clients\' expectations.\n\nResponsibilities\n• Review requirements, specifications, and technical design documents to provide timely and insightful feedback.\n• Create detailed, comprehensive, and well-structured test cases.\n• Estimate and prioritize testing activities effectively.\n• Identify, record, meticulously document, and track bugs.\n• Conduct thorough regression testing once bugs are resolved.\n• Collaborate with internal teams, including developers and product managers, to identify system requirements and address issues.\n• Design, develop, and execute automation scripts using open-source tools (experience in this area is a plus).\n\nRequirements\n• Demonstrated work experience in software quality assurance (minimum of 2-3 years).\n• Profound knowledge of software QA methodologies, tools, and processes.\n• Proven ability to craft clear, concise, and comprehensive test cases.\n• Experience with Test Management and Bug Tracking tools.\n• Hands-on experience with both white box and black box testing.\n• Familiarity with Agile/Scrum development processes.\n• Ability to work independently or collaboratively with other QC team members.\n• Strong problem-solving and decision-making skills.\n• Proficiency in using automated testing tools (experience in this area is a plus).\n• Exposure to performance and/or security testing (experience in these areas is a plus).\n• Able to work independently and ability to control quality in a development group.\n• Product mindset.\n\nWhy join us\n• Collaborate with seasoned and highly skilled technical experts, including software architects with over a decade of experience.\n• Engage with cutting-edge technologies such as Microservices, Service Mesh, Big Data, AI/Machine Learning, and IoT.\n• Enjoy an attractive compensation package and comprehensive benefits.\n• Benefit from a flexible work schedule tailored to your needs.\n• Experience a friendly and dynamic workplace environment.\n• Access annual health check-ups and premium healthcare coverage.\n• Receive annual salary reviews based on your demonstrated abilities and contributions.\n• Participate in company outings, a year-end celebration, team-building activities, and more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1632, 933, 2, 'Senior/Middle Java', 'JOB DESCRIPTION\n- Work as software developer on the web-based application product in JAVA- related and open-source technologies\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project development with high quality.\n- Participate in all phases of the development cycle.\n- Actively join planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n- Respond to and resolve IT support requests from employees via phone, email, or service request system.\n\nREQUIRED SKILLS AND EXPERIENCE\n- Experience as software engineer in a complex, enterprise-level development projects\n- 5+ years of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend.\n- Able to analyze, design, develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using:\n- Oracle PL/SQL, MyBatis\n- Java (Spring Boot / Spring Framework)\n- JSP (JavaScript / JQuery)\n- Git (Git Runner)\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools.\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc.\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications.\n- Solid understanding of OOP, design patterns, and coding standards.\n\nCONTACT\n- Send CV to: tuyendung@gem-corp.tech\n- Hotline: +842466666100 (Recruitment Team)\n- Facebook GEM Careers: https://www.facebook.com/tuyendungGEM\n- Linkedin GEM Careers: https://www.linkedin.com/company/gem-careers-hiring/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1633, 934, 2, 'Senior/Middle Java Software Engineer', 'JOB DESCRIPTION\n- Work as software developer on the web-based application product in JAVA- related and open-source technologies\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project development with high quality.\n- Participate in all phases of the development cycle.\n- Actively join planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n- Respond to and resolve IT support requests from employees via phone, email, or service request system\n\nREQUIRED SKILLS AND EXPERIENCE\n- Good command of English (both written/verbal) is essential\n- 3+ years for middle, 5+ for senior of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend\n- Able to analyze, design, develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner)\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications\n- Solid understanding of OOP, design patterns, and coding standards\n\nPREFERRED QUALIFICATIONS\n- Experience with:\n  - AWS\n  - MS .Net / .Net Core\n  - Kubernetes\n  - React.js\n  - Nginx\n  - JUnit\n  - Jasper Report\n  - ElasticSearch & Kibana (ELK)\n  - Grafana\n  - Prometheus (monitoring/alerts)\n\nBENEFITS\n- Salary: up to 60M\n- Probation salary is 100% of official salary\n- 13th-month salary and performance review twice a year\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n- Project Bonus\n- IT Certificate allowance\n- Health Care Insurance\n- Social, health and unemployment Insurance following Government policy\n- Enjoy company summer trips and other team building activities held monthly and quarterly\n- Work five days per week with flexible check-in time\n- Professional, creative and dynamic working environment\n\nCONTACT\n- 📞 Zalo: 0778872763\n- 📧 Email: phucptn@gem-corp.tech\n- Facebook GEM Careers: https://www.facebook.com/tuyendungGEM\n- Linkedin GEM Careers: https://www.linkedin.com/company/gem-careers-hiring/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1634, 935, 2, 'Java AEM Angular', 'Job Description\n\n- Architect and implement high-quality AEM solutions in alignment with business objectives.\n- Lead a team of developers in building applications, managing software lifecycles, and providing technical guidance.\n- Oversee the integration of AEM applications with other enterprise software systems.\n- Design and develop scalable, secure, and performance-efficient solutions.\n- Ensure best practices and industry standards are followed in AEM development.\n- Conduct code reviews, mentor junior developers, and ensure software quality.\n- Collaborate with project managers, designers, and other stakeholders to ensure clear communication and effective project execution.\n- Troubleshoot and resolve complex technical issues.\n- Stay updated with new trends and technologies in the AEM landscape.\n\nRequirements\n\n- Bachelor’s or Master’s degree in Computer Science, Information Technology, or a related field.\n- Minimum of 8 years of experience in software development, with at least 5 years specializing in AEM.\n- Proven experience as an AEM Developer with strong understanding of AEM architecture and infrastructure.\n- Expertise in AEM backend and front-end development including components, templates, workflows, dialogs, and object model designs.\n- Proficient in programming languages such as Java, JavaScript, HTML, CSS, and related technologies.\n- Strong understanding of RESTful services and APIs.\n- Experience with Continuous Integration and Continuous Deployment (CI/CD) environments.\n- Excellent leadership and team management skills.\n- Strong problem-solving and communication skills.\n\nBenefits\n\n- “FPT care” health insurance provided by AON and is exclusive for FPT employees.\n- Annual Summer Vacation: follows company’s policy and starts from May every year.\n- Salary review 2 times/year or on excellent performance.\n- International, dynamic, friendly working environment.\n- Annual leave, working conditions follow Vietnam labor laws.\n- Other allowances: lunch allowance, working on-site allowance, etc.\n\nSalary\n\n- Competitive salary\n\nWorking Address\n\n- Country: Vietnam\n- Province: Hồ Chí Minh\n- District: Thủ Đức\n- Address: F-Town 2, D1 Street, Saigon High-Tech Park, Tan Phu Ward, Thu Duc City, Ho Chi Minh City\n\nWays Of Working\n\n- Full-time', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1635, 936, 2, 'VN Technology Full-stack Engineer (Platform)', 'Recruitment Background & Expected Role\n\nCADDi is on a mission to "Unleash the potential of manufacturing."\n\nWe operate "CADDi DRAWER," a cloud-based system that supports digital transformation centered on the use of drawings, which are the most essential data in the manufacturing industry.\n\nOne of the issues we are currently facing in the development of this rapidly growing product is developer productivity. The inefficiencies in the development environment have become more noticeable, and they are becoming a hindrance to the development of features and a degradation of the developer experience. As an activity to resolve these issues, the need for Platform Engineering is increasing.\n\nThere are various interpretations and approaches to Platform Engineering in the world, but here, we will be working on providing tools and infrastructure to increase the development velocity by "separating concerns."\n\nExamples of anticipated tasks (not limited to)\n\nAmong these, in this post, you will be working on the following tasks\n\n- Communication and collaboration with developers to increase the value provided\n- Development and operation of self-service tools and platforms\n- Improvement of development processes and environments, not limited to the provision of new tools\n- Besides the team we are recruiting for this time, you may be assigned to other teams depending on your experience and preferences. (In that case, we would be happy to discuss this with you at the interview.)\n- After joining the company, your role may change due to organizational growth or an individual\'s career perspective\n\nInterest And Experience Gained From This Position\n\n- The fun of integrating a complex domain into a system\n- Experience in solving difficult problems with highly motivated team members\n- Experience in contributing to the scale of a product with technical skills\n- Experience in developing products that are deployed globally\n- Experience in providing value to society through the development of products that change \n\nOrganization\n\n- The Platform Department supports engineers in all aspects of product feature development, providing QA, SRE and security expertise across teams, as well as cross-system infrastructure and processing infrastructure\n- The Platform Engineering Team is a newly established team. With the mission of "Unleash the Potential of Developers," we aim to free developers from time-consuming development errands and cognitive load so that they can focus on delivering value\n\nRequirements\n\nMUST-HAVE REQUIREMENTS\n\n- 7+ years of hands-on experience developing for web applications\n- Experience in decision-making regarding technology selection, architecture design, and construction for the entire service\n- Experience with Test-Driven Development (TDD). Experience in improving code and system quality through various mechanisms, such as automated execution of Linter, Code Analyzer, API tests, and End-to-End (E2E) tests\n- Hands-on experience with statically typed programming languages (such as TypeScript, Rust, Java/Kotlin, Go, etc)\n- Experience in development using public cloud platforms such as AWS, Google Cloud, etc\n- Fluent business communication skills in English, able to complete daily tasks in English, including text communication and meetings.（CEFR B1 or Higher level)\n- Must currently reside in Vietnam or have plans to relocate. Foreign nationals must also hold a valid Vietnam work permit or be legally eligible to work in Vietnam\n\nNice-to-have Requirements\n\n- Experience of operating container technologies such as Kubernetes\n- Experience of practicing Infrastructure-as-Code\n- Experience of designing and operating CI/CD pipelines\n- Experience of practicing platform engineering in an engineering team of over 50 people\n- Experience working with Scrum or Agile methodologies\n- Conversational-level Japanese proficiency(Japanese Language Proficiency Test N2 or above is a guideline)\n\nWE ARE LOOKING FOR THIS KIND OF PERSON\n\n- Those who can sympathize with CADDi\'s mission "Unleashing the Potential of the Manufacturing Industry"\n- Those who have a T-shaped ambition mindset to maximize their expertise by not only focusing on back-end and infrastructure, but also catching up on peripheral knowledge as needed\n- Those who are able to face essential issues and take action to solve them with a sense of ownership\n- Able to work through positive attitude and constructive discussions in fast-changing and uncertain situations\n- Able to communicate and discuss with an attitude of respect for others, taking into consideration their context and resolution\n\nPRODUCT DEVELOPING ENVIRONMENT\n\n- Front-end:TypeScript, React, Next.js\n- Backend: Rust(axum),TypeScript, Node.js (Express,Fastify,NestJS)\n- Machine Learning/Algorithms: Rust, Python, OpenCV, PyTorch,TorchServe, Elasticsearch, Vertex AI\n- Infrastructure: Google Cloud, Google Kubernetes Engine, Anthos Service Mesh, Istio, Cloudflare, Argo Workflows\n- Event Bus: Cloud Pub/Sub\n- DevOps: GitHub, GitHub Actions, ArgoCD, Kustomize, Helm, Terraform, Datadog, MixPanel, Sentry\n- Data: CloudSQL (PostgreSQL), AlloyDB, BigQuery, dbt, trocco\n- API: GraphQL, REST, gRPC\n- Authentication: Auth0\n- Development tools:GitHub Copilot, Figma, Storybook\n- Communication Tools: Slack, Discord, JIRA, Miro, Confluence\n\nRECRUITING STEPS\n\n- CV screening\n- Technical assignment (online coding test) * We place more importance on whether you can imagine that you can work together with us to develop a product, rather than on your knowledge of algorithms or the speed of your answers\n- Online English speaking test\n- Technical interview (with engineer)\n- HR casual talk *This stage does not involve selection criteria; it serves as an opportunity to align on conditions and clarify any questions regarding the selection process\n- Final interview (with CTO)\n- Offer meeting\n- Please note that, depending on the situation, additional interviews or discussions may be proposed\n- If desired, we can arrange casual interviews with employees even during the selection process. Please feel free to consult with us\n- The average time from application to offer is about one month, but if you are in a hurry, please let us know. We will do our best to adjust the schedule to fit your job search timeline\n\nBenefits\n\nAPPLICATION GUIDELINES & BENEFITS\n\n- Working style:\n- Hybrid (come to Office at least once a week)\n- Remote (depending on the case, and limited to those who can go on business trip due to Company orders)\n- Office address:\n- HCMC: 7F, Gia Loc Building, No. 27-29 Nguyen Cuu Van Street, Ward 17, Binh Thanh District, HCMC\n- Hanoi: Room 508, 5F, IDMC My Dinh, 15 Pham Hung Street, My Dinh 2 Ward, Nam Tu Liem Distrist, Hanoi\n- Employment type:\n- Official full-time employee\n- Probation period: 2 months\n- Holidays and leave:\n- Annual paid leave: 12 days\n- National holidays\n- Year-end holidays (December 31 to January 3)\n- Tet holidays\n- Others (following Labor Regulations)\n- Benefits:\n- 13th month salary\n- Salary review: twice a year\n- 100% monthly basic salary and mandatory social insurances in 2-month probation\n- Premium Health Insurance\n- Social insurance, health insurance, unemployment insurance, workers\' accident compensation insurance\n- Annual health check-up\n- Allowances such as: child-care allowance, commuting allowance, life event congratulatory gift, etc\n- Growth support such as subsidy for server fee, support for attending external training courses\n- Intensive training program (external or internal training courses, workshop etc)\n- Devices: PC and display of desired specifications\n- Awards: Company awards, every 6 month MVP awards\n- Activities: Year-end-party, team building, etc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 ホーチミン', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1636, 480, 2, 'Senior Full Stack Engineer (Strong NodeJS)', 'We are looking for a senior full stack developer with NodeJS, NestJS, and React on the Front End and Web services/API experiences to join one of the new development teams. This full-stack role prioritizes NodeJS, NestJS which is required at a senior level, and React at an advanced level.\n\nResponsibilities \n\n- Partner with Project Manager towards improving and fulfilling technical direction of product.\n- Evangelize and promote JavaScript - React.js best practices.\n- Be passionate about JavaScript - React.js, stay relevant and understand how to implement advancement for existing or new systems.\n- Design, develop, review, implement, and manage React.js application code and services for the production and pre-release environments.\n- Mentor and guide junior engineers, supporting their professional growth and development.\n- Working in a team of software engineers, product owners and UI/UX designers in creating and continuously improving end-to-end solutions.\n- Participate in Agile software development, prototyping, and code review with development teams to build scalable microservices-based products\n\nEssential Skills \n\n- Experience in architecting, developing and deploying modern architectural patterns/techniques.\n- Experience in building, integrating and operating highly distributed applications (Microservices, SOA, self-contained systems).\n- Experience in event-driven architectures, messaging patterns and Apache Kafka is a plus.\n- Solid experience in designing & developing RESTful APIs and microservices-based system.\n- Solid experience in Agile development environments.\n- Strong understanding of standard Software Engineering process and Agile methodology.\n\n- Excellent software engineering skills and solution driven way of thinking.\n- Experience with React or other declarative UI frameworks is a plus.\n- Experience in AWS or other cloud environments is a plus\n- Strong understanding of secure coding practices and application security\n- Good English skill\n\nYou should be an expert in\n\n- NodeJS/NestJS\n- Relational DB (PostgreSQL,) Mysql\n- NoSql (MongoDB, Redis…)\n- Python\n- Docker/Container\n- Restful APIs design (OpenAPI, Swagger)\n- JavaScript / TypeScript\n- PHP would be a plus.\n- ReactJS\n- RestfulAPIs\n\nBenefits\n\n- Attractive salary and benefits packages, including full social insurance on salary.\n- 100% salary during Probation Period\n- Premium Healthcare and Accident insurance coverage.\n- 14 days of leave, including 12 days of annual leave and 2 personal leave days.\n- English-speaking working environment\n- Gifts on special occasions + holidays (Tet, Full-moon festival, Birthday, Christmas etc.)\n- Employee Referral Program\n- Additional bonuses. (13th bonus, Talented retention bonus)\n- Engaging team-building activities, company trips, and year-end parties.\n- Diverse training opportunities for technical and soft skills.\n- Commitment to community development, including regular charity initiatives and blood donation drives.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1637, 820, 2, 'Middle Brse', 'MÔ TẢ CÔNG VIỆC\n\nPhân tích yêu cầu phát triển (mới và customize), thiết lập phương hướng phát triển, kiểm tra code\n\nKiểm tra kết quả phát triển (trc deploy) và kết quả áp dụng hệ thống ( sau deploy)\n\nĐối ứng các yêu cầu trích xuất/thay đổi data\n\nĐối ứng yêu cầu các service bên liên quan ở nội bộ và bên ngoài (Npay/Kpay/INCS/review(Cre-ma)/期間系(OMS, SAP, intergator member)\n\nWeekly meeting và monthly meeting (tới PM kỹ thuật)\n\nService monitorinh, đối ứng khách, đối ứng nội bộ\n\nHỗ trợ onboarding các dự án thêm mới\n\nYÊU CẦU\n\nĐã từng du học/ làm việc ở Hàn là một lợi thế.\n\nNăng lực tiếng Hàn TOPIK 5 trở lên.\n\nCó từ 3 năm kinh nghiệm làm BrSE tại các công ty công nghệ\n\nCó base IT tốt\n\nCó khả năng đọc hiểu, phân tích yêu cầu của hệ thống nhanh, chính xác\n\nTruyền đạt được yêu cầu của khách đến team phát triển và ngược lại\n\nCó khả năng verify lại kết quả của team offshore trước khi đẩy output sang cho khách (review\n\nsource code, docs...)\n\nƯu tiên ứng viên có kỹ năng xử lý giao diện tốt\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 28 tháng 6, 2025\n\nChi tiết công việc\n\nSố Lượng\n\n1\n\nĐịa Điểm\n\nHồ Chí Minh\n\nKinh Nghiệm\n\n3 năm\n\nTrình Độ\n\nMiddle\n\nHình Thức\n\nNhân viên bodyshop\n\nKỹ Năng\n\nBrse', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1638, 937, 2, 'Solution Design Engineer - CAD/BIM', 'KONE moves two billion people every day. As a global leader in the elevator and escalator industry, we employ over 60,000 driven professionals in more than 60 countries worldwide joined together by a shared purpose, to shape the future of cities. In 2023, we had annual net sales of EUR 11.0 billion.\n\nKONE has consistently been featured on Forbes list of World\'s Best Innovative Companies, World\'s Best Employers & World\'s Largest Public Companies. At KONE, we believe in teamwork and a work culture where everyone can be who they are. This is exactly what makes us strong and successful.\n\nWhy this role?\n\n• A Customer Solutions Specialist performs transactional, high-volume tasks and provides engineering documentation. The Customer Solutions Specialist is responsible for high-quality documentation and executing reviews and approval processes. This work is driven by quality and measured via service-level agreements.\n• He/she can develop a specialisation e.g. for layouts of standard products and minor local modifications, BIM modelling, conducting after-certification site surveys or becoming a key user for one of the IT tools used within CSE; such as a CAD, BIM or workflow tool.\n\nWhat will you be doing?\n\n• Preferability person with Elevator business background or equivalent talent and knowledge on construction / engineering business.\n• Proficiency in AutoCAD. Revit and BIM related software (BIM knowledge will be an advantage)\n• Performs transactional, high-volume tasks of CAD related activities.\n• Responsible for high-quality documentation and executing reviews and approval processes.\n• Ability to interpret customer tender requirement, architect drawing to match with our requirement.\n• Work is driven by quality and measured via service-level agreements lead time.\n• Collaborating with project managers, engineers, and sales teams to deliver accurate design solutions.\n• Attend customer meeting when required.\n\nAre you the one?\n\n• Bachelor degree in Engineering or related major\n• Good understanding of documentation and workflow management\n• Understanding of KONE quality management\n• Good skills in real-time co-design tools and BIM\n• Good CAD and layout skills\n• Good virtual collaboration skills\n• Basic knowledge of KONE solution-related norms and standards\n• Proficient in English communication\n• IT literacy\n• User knowledge of SAP is an asset\n• BIM and layout changes if applicable to position\n\nWhat do we offer?\n\n• Career progression in opportunities within a global organization\n• Total reward elements that engage and motivate our employees and help us make KONE a great place to work\n• Comprehensive learning and development programs covering a wide range of professional skills\n• You are surrounded by fun colleagues and a lively working environment. The best part is all leaders are great and open-minded\n\nAt KONE, we are focused on creating an innovative and collaborative working culture where we value the contribution of each individual. Employee engagement is a key focus area for us and we encourage participation and the sharing of information and ideas. Sustainability is an integral part of our culture and the daily practice. We follow ethical business practices and we seek to develop a culture of working together where co-workers trust and respect each other and good performance is recognized. In being a great place to work, we are proud to offer a range of experiences and opportunities that will help you to achieve your career and personal goals and enable you to live a healthy and balanced life.\n\nRead more on www.kone.com/careers', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1639, 938, 2, 'Full Stack .NET Engineers', 'THE OPPORTUNITY\n\nOur client, a leading U.S. provider in healthcare services, is hiring a Full Stack Developer. They specialize in independent medical assessments and support insurance carriers, law firms, third-party administrators, and government agencies by verifying claims related to automotive, disability, liability, and workers’ compensation, ensuring accurate and objective evaluations that drive fair decisions and regulatory compliance.\n\nAs a Full Stack Developer, you will design and develop software solutions across multiple projects. You’ll collaborate with cross-functional teams and the Lead Software Developer to deliver effective IT tools and strategies. This role is ideal for developers who want to make a meaningful impact by building reliable, high-quality technology in a fast-paced healthcare environment.\n\nKey Responsibilities\n\n- Design and develop software across programs, projects, and small changes\n- Collaborate with cross-functional teams to deliver business-driven IT solutions\n- Ensure timely delivery of high-quality software components\n- Participate in code reviews and troubleshooting to maintain code quality\n\nSkills, Experience & Qualification\n\n- Expert knowledge in Microsoft .NET technologies, and supporting technologies\n- Strong working knowledge of relational database design (e.g. SQL, MSSQL)\n- Experience with front-end development using JavaScript frameworks (e.g. Angular)\n- Knowledge of Software Architecture patterns and principles\n- Able to work effectively across multiple change projects or change activities simultaneously\n- Practical experience in Agile, Scrum and iterative development\n- High proficiency in English, with a critical-thinking and proactive mindset\n- Candidates with ASAP notice period are a plus\n\nASW OFFERS\n\n- A diverse, inclusive, and supportive company culture.\n- Competitive remuneration.\n- Opportunity to collaborate and work with global clients and stakeholders.\n- Medical benefits.\n- Great Paid Leave entitlements.\n- Team outings, travel opportunities, company parties/events, and other exciting activities.\n- Exposure to an international environment, working with people across Malaysia, Vietnam, the Philippines, and Australia.\n- Industry and role-related training.\n- Ongoing career opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1640, 939, 2, 'Senior Backend Developer (Java Developer) - Signing Bonus', 'Title: Senior Backend Developer (Java)\nDomain: Banking & Finance\nClient: Netherlands\n\nThis job is a full-time backend engineer. You will be joining our backend team. As is common in startup culture, an entirely flat organisational structure exists. We take end-to-end responsibility for our products and execute iteratively towards our goal! Coding, code reviews, and tech design will be your daily activities. The team faces various and often unique technical challenges, which, according to our engineers\' own words, are both stimulating and satisfying once resolved. We strive to provide an open work atmosphere so that our team members are given maximum freedom to explore, propose and employ the best ideas, methodologies, and cutting-edge technology best suited for each task.\n\nWhat are we looking for?\n- Have 8+ years of hands-on experience in backend software development\n- Experience in modern JVM, Java 8+\n- Experience in Relational Database\n- Experience in Microservices Architecture\n- Well-versed in Git/Gitlab and CD/CI concepts, tools and pipelines\n- Experience in the development of mission-critical software systems\n- Experience in designing and building performant systems\n- Experience in the banking domain is a plus.\n- Abstract thinking skills and academic level in computer science or other engineering studies\n- Experience in Workflow Engines, Kafka is a plus\n- Good verbal and written English communication skills\n- Strong team player and experienced working with teams on and across sites.\n- Experience working with Docker and Kubernetes in a production environment is a plus\n- Exposure to Virtualization / Cloud platforms such as Azure, AWS or GCP is a plus\n- Experience in language engineering is a plus.\n\nBenefits:\nSalary & Allowances:\n- Salary: Negotiable.\n- Monthly performance bonus.\n- 13th-month salary + end-of-year performance bonus.\n- Lunch allowance: 500,000 VND/month.\n- Holiday bonuses (April 30 & May 1, September 2, etc.).\n- Paid leave: 12 days of annual leave.\n- Health: Social insurance, health insurance, annual health check-up.\n- Recreation: Annual company trips and quarterly team-building activities.\n- Laptop, monitor, and necessary equipment for work.\n- Remote work: Every Wednesday + 3 additional remote days per month.\n\nCareer Growth Opportunities:\n- Long-term position with training opportunities.\n- Annual salary reviews and defined promotion pathways.\n- Diverse options for career advancement.\n- Sponsorship for advanced training and professional skill enhancement.\n- Work in an international environment (Headquarters based in the Netherlands).\n\nWorking Environment:\n- Open workspace.\n- A vibrant and dynamic work atmosphere.\n- Language classes: English, Dutch, etc.\n- Clubs: badminton, soccer, pickleball, esports, etc.\n\nLocation\n- Level 12A, Song Da Cau Giay Building, No. 18, Alley 165 Cau Giay Str, Cau Giay Dist, Hanoi\n\nWork Hours\n- Date: Monday to Friday (Remote on Wednesdays)\n- Time Options: 8:30 AM – 6:00 PM or 9:00 AM – 6:30 PM or 9:30 AM – 7:00 PM\n- Break: 1 hour 30 minutes\n\nContact\n- Zalo/ Call: 094 176 2912 (Huế)\n- Mail: haala@vitex.asia', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ハノイ首都圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1641, 940, 2, '[HN] Full Stack Engineer (Python or React)', 'Job Description:\n- Develop full-stack features for Geniee SFA/CRM service application (Sales Force Automation, Customer Relationship Management)\n- Implement new features based on business team’s requirements\n- Monitor network and system to prevent threats or system faults\n- Optimize web application for maximum speed, scalability and efficiency\n- Stay current with latest technology trends and adopt new tools/practices\n- Other tasks as assigned by supervisors\n\nJob Requirements:\nMust Have (At least ONE of the following technical requirements):\nBackend Focus:\n- At least 3 years experience in backend development using Python\n- Experience in architecture design using cloud services (AWS/GCP)\nFrontend Focus:\n- At least 3 years experience in frontend development using React and Typescript\nCommon Must Have Requirements:\n- At least 4 years experience in web application development\n- Experience in product development based on cloud computing\n- Good communication skills\n- Ability to work independently and take initiative\n- Good English communication\n\nNice to Have:\n- Experience in both frontend (React/Vue.js/AngularJS) and backend (Python) development\n- Domain knowledge in sales support systems (Sales Force Automation)\n- Experience building customer management systems (CRM/ERP)\n- Experience with large-scale data infrastructure and distributed processing\n- Experience in UI/UX development\n- Experience building product infrastructure in cloud environments\n- Agile/Scrum development experience\n- Japanese communication skills\n\nEmployment Benefits:\n- Laptop Mac Pro provided\n- Social, public health and unemployment insurance\n- PVI insurance for staff and 1 family member\n- 12 days’ annual leave + 1 birthday leave\n- Bi-annual salary review\n- Half-year bonus up to 100% monthly gross salary\n- Most valuable person/team awards per half-year\n- Annual company trip and health check\n- Club allowance up to $20/month\n\nRecruitment Submission Email: recruitment-gv@geniee.co.jp\nPlease note that only qualified candidates will be contacted.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1642, 808, 2, 'Junior AI Software Engineer', 'Responsibilities\n\nDevelopment Support:\nAssist in developing and maintaining backend systems using C# and .NET Core/Framework.\nContribute to building responsive and user-friendly interfaces with ReactJS.\nAI Feature Integration:\nWork with the team to integrate pre-trained AI/ML models into applications.\nSupport the implementation of features leveraging AI services (e.g., NLP, image recognition, chatbots).\nCode Quality and Testing:\nWrite clean, maintainable code with guidance from senior engineers.\nPerform debugging and testing of software components to ensure functionality and performance.\nCollaboration:\nCollaborate with cross-functional teams, including AI engineers and senior developers, to deliver integrated solutions.\nApply best practices for AI integration and full-stack development.\nDocumentation and Reporting:\nDocument your work, including technical details and code comments, to ensure transparency.\nRegularly update the team on progress and challenges.\n\nRequired Skills And Qualifications\n\nBachelor’s degree in Computer Science, Software Engineering, or a related field (or equivalent experience).\nStrong foundation in C# and familiarity with the .NET Core/Framework.\nBasic knowledge of ReactJS, including component-based architecture.\nUnderstanding of web development fundamentals (HTML, CSS, JavaScript).\nExposure to AI technologies.\nFamiliarity with RESTful APIs and data handling.\nA keen interest in AI, machine learning, and related fields.\n\nPreferred Skills\n\nProficiency in English, with exceptional listening, speaking, reading skills.\nInternship or project experience with AI/ML tools (e.g., TensorFlow, PyTorch).\nBasic understanding of SQL/NoSQL databases.\nFamiliarity with version control tools like Git.\nKnowledge of Agile development practices.\nEagerness to learn and adapt to new technologies.\nStrong problem-solving and analytical skills.\nEffective communication and teamwork abilities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1643, 941, 2, 'Fullstack Engineer - Node.js + Vue.js', 'We are a fast-growing SaaS company in the EduTech space, operating mainly in Singapore, Vietnam, and Malaysia. With almost 2000 schools as customers, our mission is to revolutionize early childhood education through technology and provide innovative solutions to our customers. With a team of 60 talented individuals, we are committed to transforming the way education is delivered in the Southeast Asian region and beyond.\n\nWhat you will be doing:\n\n- Develop full-stack services in Typescript for in our existing application\n- R&D novel and ingenious solutions to creating enhanced user experiences tailored to a multitude of global regions\n- Continuously enhance the app with the latest code-improving methodologies available\n- Use modern DevOps tools and automate everything with Docker and our Kubernetes clusters\n\nYour Skills And Experience\n\nMust have:\n\n- Deep expertise in Typescript, Vue and MySQL\n- Containers are first class in your apps\n- Understanding of MVC design pattern\n- Familiar with a wide range of performance optimization solutions\n- Strong understanding of vanilla front-end technologies, such as JavaScript, HTML5, and CSS3\n- Sound coding practices with tools such as git, unit testing, CI/CD, service oriented architecture\n- Linux confidence\n- Solid understanding of information security', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1644, 942, 2, 'Senior Fullstack Java + React.js Developer (Max 95M gross)', 'REMOTE JAVA FULL-STACK ENGINEER (SPRING + REACT)\n\nCompany: itworks.asia’s Client\nSalary Range: up to 95M gross/month\nYOE: 7+\nEnglish: Fluent\nWorking hours: Monday to Friday\nWorking Location: Remote\nWorking type: 100% Remote\n\nOur client is a remote-first company of 90 experienced and dedicated engineers that provide high-standard software product development services. We set very high expectations of client satisfaction for the long term.\n\nFrom small companies to big enterprises, we support them to scale their products and services.\n\nWith no fixed address, we free ourselves from the physical location to extend our abilities in supporting businesses.\n\nOur fast-growing remote working company is seeking a highly talented and experienced Senior Fullstack Engineer to join our team. In this role, you will be responsible for leading the development of software applications and systems that meet the needs of our clients.\n\nWHAT YOU’LL DO (RESPONSIBILITIES):\n\n- Provide technical leadership in the design, integration, implementation, and transition of enterprise SaaS human services system\n- Flexible design architectural approach to deliver configurability along the data creation, integrations, workflows, notifications, and data persistence\n- Understand and synthesize integration requirements, and develop recommendations based on business objectives, product roadmap, solution architecture and technical considerations\n- Contribute to the development of our platform functionality using state-of-the-art frameworks and tools\n- Specify and troubleshoot API integrations in an ecosystem of multiple systems\n- Work closely with client stakeholders, partners, product managers, creative designers, platform architect, and other software engineers\n- Constantly learn and use leading-edge technologies\n- Implement a system that will address the needs of vulnerable populations\n- Contribute to the highest security, extensibility, reusability and testing standards in system architecture and software, interface, components, data structures, and algorithms specifications\n\nWE ARE LOOKING FOR SOMEONE WITH\n\n- Experience building multi-tier web applications with Java fullstack (7-8 years of experience)\n- Strong with frontend development (ReactJS)\n- Fluent in English\n- Nice to have exp with Cursor or similar AI tool to generate code\n- Experience building microservices\n- Experience with IT security architecture and best practice\n- Experience utilizing OpenAPI standards to deliver all phases of RestFUL web services\n- Experience with ElasticSearch, ElastiCache, PostgreSQL, Redis, S3, Redshift and Apache Kafka\n- Experience leading a major IT application implementation effort\n- Ability to synthesize information to deliver optimal solutions and identify roadblocks\n- Experience working with technical and operational management, and process owners\n- Must have a strong background in software engineering principles and techniques.\n- Strong analytical and technical skills to identify critical issues, escalate them and drive them to resolution.\n- Experience in an agile software development project\n- Experience using a software version control system (e.g., Git) in a project with multiple developers committing to a shared repository\n- Experience with software testing, including test planning, integration testing and load and performance testing\n- Familiarity with an automated build and deploy pipeline\n- Bachelor’s degree in Computer Science or related field (or equivalent work experience)\n\nHELP US BUILD SOMETHING THAT MATTERS\n\nBENEFITS:\n\n- A remote working environment that allows you to work from anywhere in the world\n- Full-time insurance follow VN Labor laws\n- Work equipment support.\n- Annual bonus, performance-based bonus.\n- Monthly compensation package to help you work and live better, remotely!\n- Fully support for exams to get Certification and skills improvement training.\n- Receive 22 paid leaves on your 5th years. We encourage you to take one month off work.\n- A competitive salary and benefits package\n- Opportunities for professional development and career advancement with monthly coaching.\n- A dynamic and innovative team that values creativity and collaboration.\n\nOFFICE\n\nWe are remote-first, it means working remotely does not make you less important or boring. But people who love office still get the great office experience at:\n\n- HN Office: Cầu Giấy, Hà Nội\n- HCM Office: Quận Bình Thạnh Tp. Hồ Chí Minh\n\nWORKING TIME: From Monday to Friday\nMust work with US clients from 8PM to 11PM ( 3 hours, can be flexible with the rest 5 hours)\n\nProject information: Public Community Platform\n\nTHE HIRING PROCESS\n\n- Optional: Assessment\n- Round 1: meet for culture + technical scanning\n- Round 2: meet client (sẽ làm 4 rounds, chủ yếu là live coding trong 2 vòng đầu)\n- Round 3: meet Founder\n\nPlease note that all rounds will be conducted in English.\n\nContact: Phuong Tran | Email: info@itworks.asia | www.itworks.asia | Tel: 0777-047-369', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1645, 943, 2, 'Java Software Engineer - Vietnam', 'At Globant, we are working to make the world a better place, one step at a time. We enhance business development and enterprise solutions to prepare them for a digital future. With a diverse and talented team present in more than 30 countries, we are strategic partners to leading global companies in their business process transformation.\n\nWe seek a Java Developers who shares our passion for innovation and change. This role is critical to helping our business partners evolve and adapt to consumers\' personalized expectations in this new technological era.\n\nYou will get the chance to:\n\n- Analyze, design, and develop scalable and reliable applications using various tools, including Java technologies, to support our transaction processing systems.\n- Work with other developers and vendors to implement system modifications and support the design, coding, configuration, and addressing production issues\n- Design complex object-oriented solutions based on advanced software development practices and methodologies\n- Implement and enforce best practices in code refactoring, unit testing and various agile practices\n- Design and perform unit testing plans and project implementation in an open-source environment\n- Ability to learn technical skills quickly. Excellent troubleshooting/problem resolution skills.\n- Team player with strong communication and interpersonal skills\n- Anticipate potential technical problems and operational risks, determine and implement solutions\n\nWhat will help you succeed:\n\n- Bachelor\'s degree in Computer Science or equivalent\n- Minimum 6 years of experience in application design and development\n- Experience with Agile methodologies and practices and ability to build solutions maintaining industry best practices and security standards\n\nProven expertise in design and development using Java EE\n\n- Experience with JSP/CSS/XSLT/JavaScript/AJAX/HTML5\n- Good working knowledge of Spring /Maven/ant and familiarity working with Git, Azure pipelines or similar\n- Experience with Object-Relational Mapping (JPA2 / Hibernate) a must and the ability to create complex / efficient queries in relational databases like MySQL/SQL Server\n- Ability to engineer and fine-tune software systems for scalability and high availability (DB locking strategies, multithreading)\n- Proven experience with XML / SOA / JSON architecture\n- Experience working on caching frameworks like Hazelcast/Redis\n- Experience in unit testing, code refactoring, and SCM\n- Good knowledge of Unix/Linux and IP networks\n- Experience with OO analysis and design and end-to-end experience of a project\'s lifecycle\n- Experience in Payment Industry ( EMV, POS device management, ISO8583, NACHA format financial transactions management a plus)\n- Good at English skills, both verbal and written\n\nThis job can be filled in Hanoi/Danang or Ho Chi Minh\n\nCreate with us digital products that people love. We will bring businesses and consumers together through AI technology and creativity, driving digital transformation to impact the world positively.\n\nWe may use AI and machine learning technologies in our recruitment process. Globant is an Equal Opportunity employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, national origin, disability, veteran status, or any other characteristic protected by applicable federal, state, or local law. Globant is also committed to providing reasonable accommodations for qualified individuals with disabilities in our job application procedures. If you need assistance or an accommodation due to a disability, please let your recruiter know.\n\nFinal compensation offered is based on multiple factors such as the specific role, hiring location, as well as individual skills, experience, and qualifications. In addition to competitive salaries, we offer a comprehensive benefits package. Learn more about life at Globant here: Globant Experience Guide.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1646, 899, 2, 'Java Developer (Middle/Senior)', 'Responsibilities\n\n- Develop and maintain web applications using Java Spring Boot.\n- Collaborate directly with the development team or clients to clarify tasks and requirements, and design systems accordingly.\n- Monitor, maintain, and enhance existing operational systems.\n- Mentor less experienced team members, provide technical training, and offer support when needed.\n\nRequirements\n\n- Language: Proficient in English communication (mandatory)\n- Minimum of 4 years of experience working with Java or related frameworks.\n- Experience in system design and working with microservices architecture.\n- Strong understanding of common design patterns.\n- Experience in optimizing response times and databases; deep knowledge of RDBMS. Experience with NoSQL databases is a plus.\n- Experience in building pipeline workflows and working with CI/CD processes.\n- Strong analytical and problem-solving skills.\n- Ability to research and propose effective solutions.\n\nNice To Have\n\n- Experience in planning and managing teams is an advantage.\n- Experience working with Korean clients is a plus.\n\nCompensation & Benefits\n\nFlexible working regime and health care:\n- Flexible timekeeping (from 8:00 - 9:00 to 17:30 - 18:30) \n- Minimum 14 paid leaves per annum for all employees after probation\n- 01-day remote work per month\n- A flexitime allowance of 90-180 minutes per month for employees\n- 01 hour paid leave per day for women having children under 12 months\n- Social insurance, health insurance, unemployment insurance and MIC care insurance \n\nTransparent And Fair Benefits\n- Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n- Work performance review 2 times/ year (in April and October)\n- 13th-month salary\n- Bonus Policy: Public holidays (2/9, 30/4, 1/5, 1/1,...); Personal Performances; Excellent Team; Performance bonus in Token of the project;.. \n- Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company\n\nDynamic Environment And Open Culture\n- Year-end party, sports day, yearly company trip and quarterly team building,...with a generous budget\n- Socialize with colleagues through monthly Happy Hour \n- Monthly allowance when joining clubs: Soccer, Swimming, Yoga, Music,... \n- Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks,...\n- Flat, open and sharing culture with friendly management team; outsourcing company with product mindset \n\nStrong Learning Culture\n- Free training courses for technical and soft skills (presentation skills, communication skills, foreign language courses,...)\n- Account to log in to our online learning system, which contains thousands of valuable lectures (LMS)\n- Participate in workshops, seminars, tech talk,... with sharing from experts inside and outside the company\n- Working opportunities with technical gurus who built and operated world-class applications with millions of users.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1647, 880, 2, 'Freelance Software Developer (C#) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with C#\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1648, 929, 2, 'Flutter Developer (SQLite/MySQL)', 'Responsibilities\n- Develop and maintain cross-platform mobile applications (iOS and Android) using Flutter.\n- Design, build and optimize user interfaces to ensure smooth, friendly experiences.\n- Integrate and process data from backend APIs into applications.\n- Work with SQLite or MySQL to build and optimize databases for mobile applications.\n- Analyze and fix errors, debug and improve application performance.\n- Coordinate with related departments (design, testing, product management) to ensure project quality and progress.\n- Participate in writing technical documents and application user manuals.\n\nQualifications\n- 1 year of experience developing Flutter applications and Dart language.\n- Experience with SQLite or MySQL is an advantage.\n- Good understanding of mobile application development lifecycle, build and release tools (Android Studio, Xcode...).\n- Ability to work independently and in a team.\n- Logical thinking, problem solving ability and quick learning.\n\nBenefits\n- Salary is negotiable depending on ability.\n- Good treatment. Enjoy full benefits of the Company and welfare according to labor law, pay social insurance, health insurance, unemployment insurance.\n- Consider salary increase according to ability and work efficiency.\n- Work in a dynamic, friendly and professional environment, with many opportunities for promotion and development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1649, 743, 2, '[LTS] Developer NodeJS', 'Position : NodeJS Developer\nQuantity : 03\nType : Full-time\nLocation: 68 Nguyen Co Thach street, Ha Noi.\nJob Description\n- Participate in development projects for Web applications, Mobile Applications\n- Able to take the role of technical leader of the project, and propose technical solutions for various problems\n- Coaching project members\n- Perform design, implement coding, testing, and documentation in line with user & system requirements to deliver source code that meets the needs and release milestone\n- Perform bugs fixing, maintaining, and enhancement\nRequirement\n- At least 1 year of commercial experience with NodeJS\n- Integration of user-facing elements developed by front-end developers with server-side logic\n- Writing reusable, testable, and efficient code\n- Design and implementation of low-latency, high-availability, and performant applications\n- Experience with web applications fundamentals like React, React hooks\n- Experience with Javascript, Express, Graphql\n- Experience with MongoDB\n- Strong ability to understand existing code and fix bugs and write enhancements (without rewriting code)\n- ENGLISH is a plus\nBenefits\n- Attractive salary (up to 2000$). Performance based award.\n- Young and dynamic working environment.\n- Continuous development of hard and soft skills through work and professional trainings.\n- Opportunity to approach newest technology trends\n- Salary review 2 times/year or on excellent performance\n- Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\nCONTACT\nLTS Recruitment Department\nPhone Number: 02466607474\nEmail: rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1650, 944, 2, 'Back End Developer', '1, Vị trí tuyển dụng\n• Junior Backend: 1-2 yoe offer 18-20M\n• Middle/Senior: >=4 yoe offer 40-50M\n\n2, Mô tả công việc\n• Tham gia vào dự án phát triển với khách hàng trong và ngoài nước.\n• Tham gia các dự án liên quan đến hệ sinh thái như: ví điện tử, viễn thông, ngân hàng, quản lý hợp đồng, đấu thầu, hải quan...\n\nĐối với level Junior: \n• Thực hiện viết tài liệu thiết kế chi tiết.\n• Phát triển chức năng theo thiết kế.\n• Triển khai tính năng trên môi trường STG,UAT,PROB.\n\nĐối với level Middle/Senior:\n• Nghiên cứu công nghệ mới áp dụng vào dự án.\n• Làm việc với SA và Tech Lead để đưa ra thiết kế các module trong hệ thống.\n• Quản lý team dev (3-5 người) và review code.\n\nTrao đổi cụ thể khi phỏng vấn.\n\n3, Yêu cầu ứng viên\n• Ứng viên tốt nghiệp các trường Đại học trong nước.\n• Ứng viên có kinh nghiệm làm việc với một trong các ngôn ngữ C++, Java, Go, Python.\n\nĐối với level Junior:\n• Có kiến thức nền tảng về ngôn ngữ, nắm vững cấu trúc dữ liệu và giải thuật.\n• Có kinh nghiệm làm việc với framework.\n• Có kiến thức về CSDL như: SQL server, Oracle,...\n• Nắm vững UML.\n• Có tư duy lập trình và nắm bắt công nghệ mới nhanh.\n\nĐối với level Middle/Senior:\n• Thành thạo sử dụng framework.\n• Nắm vững các design pattern trong thiết kế hướng đối tượng.\n• Nắm vững về Kafka, Redis, các hệ quản trị cơ sở dữ liệu SQL, NoSQL.\n• Đọc hiểu và viết tốt các tài liệu thiết kế UML.\n• Có khả năng phân tích và đưa ra giải pháp xử lý tốt.\n• Làm việc với hệ điều hành Linux thành thạo.\n• Nắm vững kiến trúc dữ liệu và giải thuật, các loại giao tiếp trong hệ thống.\n• Có kinh nghiệm làm việc với CI/CD.\n• Có kinh nghiệm làm việc với kiến trúc Microservice, SOA,…\n• Nắm vững quy trình phát triển phần mềm waterfall, Agile.\n• Có kinh nghiệm lead team nhỏ, quản lý plan, task của các thành viên trong team tốt.\n• Tinh thần làm việc hăng hái, có trách nhiệm, thái độ cầu tiến trong công việc.\n• Có kiến thức các dự án viễn thông/ tài chính là lợi thế.\n\n4, Quyền lợi ứng viên\n• Chế độ thu nhập hấp dẫn.\n• Thưởng dự án và thưởng cho nhân viên xuất sắc và tập thể xuất sắc.\n• Bảo hiểm chăm sóc sức khỏe cao cấp (VISSOFT Care), bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp.\n• Được khám sức khỏe định kỳ 1 lần/1 năm.\n• Tối thiểu 12 ngày nghỉ phép có lương mỗi năm cho tất cả nhân viên chính thức.\n• Môi trường làm việc hiện đại với những đồng nghiệp trẻ trung, năng động & thân thiện và cà phê, trà, đồ uống miễn phí. Du lịch công ty hàng năm và tiệc cuối năm, team building hàng quý và ăn uống cùng nhau hàng tuần. Câu lạc bộ: chạy, bóng đá, game,…\n• Văn hóa phẳng, cởi mở và chia sẻ với đội ngũ quản lý thân thiện.\n• Thời gian làm làm việc: 8h30 - 17h30 Thứ 2 - Thứ 6.\n\n5, Hướng dẫn nộp hồ sơ:\n• CV gửi về: maint2@vissoft.vn\n• Trụ sở văn phòng: Tầng 16 – Toà Detech – Số 8 Tôn Thất Thuyết – phường Mỹ Đình 2 – Nam Từ Liêm – Hà Nội.\n• Website: https://vissoft.vn/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona capitalei Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1651, 945, 2, 'Full Stack Developer', 'About Gohub\nGohub is a travel eSIM company focused on Vietnam and APAC travelers. We are building an integrated web/app platform to help global users connect to the internet anywhere in the world using our wide range of eSIM products (a $40B market globally). eSIM is disrupting the traditional telecom industry, and we have been an early leader in this race since 2018. We launched our first eSIM products in 2023, raised USD 500,000 in seed funding, and launched the first version of Gohub eSIM app in October 2024. We are on track to scale our revenue approximately four times to USD 4M this year.\n\nWondering if Gohub is the right match? We’ve found that low ego, a growth mindset, and a clear priority for action go a long way here.\n\nHow You\'ll Make An Impact\n- Participate in all aspects of application development, including design, implementation, deployment, and maintenance\n- Take a major part in front-end and back-end development for the new version of the e-commerce website\n- Work and conduct pair programming with other developers\n- Research new technologies, new web frameworks to propose and apply for different projects\n- Handle coordination in integration projects with external partners\n- Help other teams and members to continuously improve their skills and productivity\n\nWho You Are\nMust have\n- Having 5+ years’ experience as a web developer or full-stack developer with solid hands-on experience\n- HTML, JavaScript, CSS\n- Nodejs, ReactJs, NextJs, NestJs, Mysql, Postgres\n- Amazon AWS, Redis, Docker services, Git, Github/Gitlab\n- Having at least one e-commerce website or one API integration with a third-party system in the portfolio\n- Strong project experience and methodologies (e.g., Agile, Scrum) in a business environment\n- Advanced skills in web application and database design, API implementation, and microservice development\n- Experience in technical documentation, unit testing, and integration testing\n- Strong problem-solving and troubleshooting skills, with a detail-oriented mindset\n- Good at research and communication in English\n\nNice-to-have\n- Bachelor’s Degree, preferably in IT, Computer Science, or related area\n- Knowledge of e-commerce areas\n- Data analysis skills, knowledge of UI/UX, mobile app development, React native, Flutter\n\nWhat We Offer\n- Gain meaningful, real-world experience on impactful projects\n- Opportunity to sharpen analytical, communication, and problem-solving skills\n- Potential for a full-time role upon graduation based on performance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1652, 829, 2, 'LLM Engineer', 'Về HBLAB\n\nHBLAB có gần 10 năm kinh nghiệm tại lĩnh vực CNTT & IT Outsourcing hoạt động chính tại thị trường Nhật Bản và đang đầu tư phát triển các thị trường Hàn Quốc cũng như các quốc gia nói tiếng Anh khác.\n\nVới thế mạnh trong việc phát triển hệ thống, hỗ trợ chuyển đổi số (Digital Transformation), nghiên cứu phát triển AI trong các lĩnh vực trải dài như retail, sản xuất, giáo dục… HBLAB đã và đang chinh phục được nhiều mục tiêu trên hành trình vươn tầm quốc tế. Tiêu biểu như:\n\n- Phát triển thành công hơn 300 project với tỷ lệ khách hàng hài lòng trên 95%\n- Chuẩn hóa quy trình bảo mật và đảm bảo chất lượng theo chuẩn chứng chỉ quốc tế ISO/IEC 27001:2013 và CMMI\n- Có hơn 500 nhân sự – kỹ sư chất lượng cao, khả năng đối ứng nhanh, trong đó lên đến 40% nhân sự có khả năng ngoại ngữ\n\nVới khẩu hiệu "We are stronger together", tất cả các nhân viên đều là những anh em thân thiết, những "Brothers" trong đại gia đình lớn HBLab. HBLab sẽ luôn cố gắng để không chỉ là nơi làm việc mà còn là nơi để tất cả các anh em được vui chơi, học tập và phát triển bản thân.\n\nGhé thăm HBLAB tại: \n\n- Website: https://hblab.vn/\n- Tuyển dụng HBLAB: https://hblab.vn/career/vi-tri-tuyen-dung/\n- Facebook: https://www.facebook.com/hblab.vn?locale=vi_VN\n\nMÔ TẢ CÔNG VIỆC\n\n- Lưu trữ và truy xuất dữ liệu: Lấy dữ liệu phi cấu trúc, indexing và/hoặc cấu trúc lại sau đó cho phép truy xuất.\n- Tinh chỉnh và tối ưu hóa LLMs cho các ứng dụng cụ thể, sử dụng các kỹ thuật như fine-tuning, prompt engineering, và parameter-efficient tuning.\n- Thiết kế và triển khai hệ thống RAG, Agent để tăng cường độ chính xác và cập nhật thông tin cho LLMs.\n- Kiểm tra và đánh giá các thành phần. Đo thời gian tạo phản hồi, độ trễ của từng thành phần, lỗi và chi phí.\n- Hợp tác với các nhóm phát triển sản phẩm và kỹ thuật để tích hợp hiệu quả các giải pháp LLM vào hệ thống và quy trình kinh doanh hiện có của khách hàng.\n\nYÊU CẦU\n\n- Có tối thiểu 1 năm kinh nghiệm quan đến ML/DL, ưu tiên có kinh nghiệm về NLP.\n- Có kiến thức về công nghệ và nghiên cứu LLM.\n- Làm quen với các công cụ LLM như LangChain, LLamaIndex, cơ sở dữ liệu vectơ.\n- Kỹ năng nghiên cứu, research.\n- Thành thạo tiếng Anh/tiếng Nhật là một lợi thế.\n- Có kinh nghiệm phát triển backend với Python là một lợi thế. \n\nCHẾ ĐỘ ĐÃI NGỘ\n\n- Fix 13 tháng lương\n- Thưởng performance 2 lần/năm vào tháng 6 và tháng 12\n- Review lương 2 lần/năm vào tháng 4 và tháng 10\n- Beauty care: 200.000 VND/người/tháng cho nhân viên nữ\n- Quỹ đào tạo 3.000.000 VND/người/năm\n- Thưởng chứng chỉ tiếng Nhật và các loại chứng chỉ khác theo quy định (nếu có)\n- Bảo hiểm sức khỏe cho nhân viên từ 1 năm thâm niên\n- Phụ cấp thâm niên\n- 12 ngày phép năm, BHXH/BHYT/BHTN đầy đủ theo quy định của Luật lao động\n- Nghỉ lễ Tết theo quy định Nhà nước và kèm theo thưởng cho các ngày lễ lớn trong năm: 30/4, 1/5, 2/9, Tết,…\n\nTHÔNG TIN KHÁC\n\n- Thời gian làm việc: Thứ 2 đến thứ 6 từ 8h - 17h30 (nghỉ thứ 7, chủ nhật), thời gian chấm công (check in) linh hoạt từ 7h30 - 8h30\n- Địa điểm làm việc: Tầng 2 và Tầng 21, tòa Central Point, 219 Trung Kính, Yên Hòa, Cầu Giấy, Hà Nội.\n- Quy trình tuyển dụng: CV Scanning -> Phỏng vấn (1 vòng) -> Offer & Onboarding (nếu có)\n\nHBLAB cảm ơn bạn đã quan tâm đến vị trí LLM Engineer và mong nhận được thông tin ứng tuyển từ bạn!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1653, 903, 2, 'Java Software Engineer', 'JOB DESCRIPTION \nPosition : MIDDLE JAVA DEVELOPER \nQuantity : 05 \nType : Full-time \nLocation : 5th Floor, TTC Building, No. 19 Duy Tan St., Dich Vong Hau Ward, Cau Giay Dist., Hanoi Capital, Vietnam. \nWorking location : Dist. 1, Ho Chi Minh City \n\nABOUT US \n• Astek is a global player in engineering and technology consulting, founded in France in 1988. Today, we are +7500 engineers across over 26 countries in the world. \n• With expertise in many industrial and tertiary sectors, we support our international clients in the intelligent deployment of their products and services, and in the implementation of their digital transformation. \n• Astek Vietnam is established in 2022 to increase group’s capability to support our clients’ operation around the globe, leveraging Vietnam talented engineers. \n• More information about our group: https://astekgroup.fr/ \n\nJOB DESCRIPTION & REQUIREMENTS \nResponsibilities: \n- Develop and implement Java applications. \n- Write clean, efficient, and maintainable code. \n- Troubleshoot and debug applications. \n- Collaborate with cross-functional teams to deliver high-quality solutions. \n- Maintain up-to-date knowledge of Java technologies and industry trends. \n\nKey Skills \n- Java SQL Data Modeling & Optimization \n- Clean Code & Defensive Programming \n- Tech Stack: Jakarta EE (Java EE) \n- Java backend development with Spring Boot \n- Java Persistence API (JPA) \n\nRequirements Skills and Knowledge \n• Min 3+ experience years in Java Developer \n• Strong proficiency in Java programming.\n• Experience with Java frameworks (Spring, Jakarta EE) and libraries (Hibernate). \n• Knowledge of software design patterns and principles. \n• Proven problem-solving and debugging abilities. \n• Effective communication and teamwork skills. \n• Proficiency in English communication \n\nBENEFITS \n● Attractive salary: Nego. Performance based award. \n● Young and dynamic working environment. \n● Continuous development of hard and soft skills through work and professional training. \n● Opportunity to approach newest technology trends. \n● Salary reviews 1 times/year or on excellent performance \n● Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.) \n\nCONTACT \nASTEK VIETNAM \nContact Person : Ms. Dzung Nguyen \nPhone Number : 0969988029 \nEmail : Thi-Kim-Dung.NGUYEN@astek.net \nWebsite : https://astekgroup.fr/?lang=en', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1654, 723, 2, 'Python Developer', 'MÔ TẢ CÔNG VIỆC\n\n- Tham gia vào toàn bộ vòng đời của ứng dụng, tập trung và coding và debug các dự án website và hệ thống\n- Viết API kết nối giữa các hệ thống, và phục vụ trao đổi dữ liệu với mobile & front-end\n- Thu thập và xử lí các yêu cầu thiết kế và kĩ thuật\n- Nghiên cứu và áp dụng các công nghệ mới để tối ưu hóa hiệu quả phát triển sản phẩm.\n- Phân tích yêu cầu, thiết kế hệ thống.\n- Tối ưu hiệu năng hệ thống\n\nYÊU CẦU\n\n- Từ 2 năm kinh nghiệm trở lên làm Python/Dejango hoặc Python/Odoo\n- Có kinh nghiệm hoặc kiến thức về hệ thống vận hành Linux\n- Có kiến thức Design Pattern và thiết kế hệ thống\n- Hiểu biết hoặc từng làm việc theo mô hình Agile/Scrum.\n\nQUYỀN LỢI\n\n- Mức lương cạnh tranh ( 20 – 28 triệu Gross )\n- Không áp chế độ thử việc, 100% lương, full chế độ từ ngày đi làm đầu tiên.\n- Được hưởng các chế độ đãi ngộ đặc biệt theo chính sách của NMS :\n- Chính Sách Bảo Hiểm Bảo Việt dành riêng cho nhân viên khi đi khám nội trú/ngoại trú\n- Nghỉ mát: Theo chính sách của công ty (vào tháng 5-6 hàng năm).\n- Có cơ hội tham gia các hội thảo về Bảo Mật Thông Tin trong nước và thế giới (Singapore,Mỹ, Tây Ban Nha,…).\n- Có cơ hội làm việc với các chuyên gia hàng đầu, kinh nghiệm lâu năm trong ngành Bảo Mật Thông Tin (top 100 hacker Facebook, Microsoft,…)\n\nLIÊN HỆ\nỨng viên vui lòng gửi CV theo địa chỉ:\n\nPhòng tuyển dụng\n\nCông ty Cổ phần Dịch vụ di động Thế Hệ Mới\n\n- Trụ sở chính: Tẩng 3A – Mỹ đình Plaza – 138 Trần Bình – Cầu Giấy – HN\n- Người phụ trách : Ms. Kim Anh\n- Số điện thoại : 0965577243\n- Email : anhttk@nms.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1655, 698, 2, 'Manual Tester', 'MÔ TẢ CÔNG VIỆC:\n- Tìm hiểu tài liệu yêu cầu dự án \n- Viết các tài liệu liên quan tới test (tài liệu PTYC, test viewpoint, test case, checklist, test data...) \n- Thực hiện estimate và lập kế hoạch kiểm thử \n- Thực hiện kiểm thử phần mềm bằng những phương pháp như Functional testing, Regression testing, Integration testing… tùy theo tính chất của phần mềm và giai đoạn phát triển phần mềm. \n- Report, quản lý, verify bug, tái hiện bug  \n\nYÊU CẦU CÔNG VIỆC:\n- Tốt nghiệp Đại học chuyên ngành CNTT, chuyên ngành tiếng Nhật, hoặc liên quan\n- Từ 1.5 năm kinh nghiệm tại vị trí tương đương trở lên \n- Có kinh nghiệm test web, test API\n- Có khả năng đọc hiểu tài liệu phân tích, thiết kế \n- Có khả năng sử dụng ngôn ngữ truy vấn SQL\n- Nắm vững các kiến thức cơ bản về Testing, các kỹ thuật kiểm thử\n\nYêu cầu khác:\n- Có tinh thần trách nhiệm cao trong công việc\n- Có khả năng làm việc độc lập và làm việc theo nhóm\n- Có chứng chỉ ISTB Foundation là một điểm cộng ( không bắt buộc)\n\nQUYỀN LỢI:\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe 24/24 \n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện);\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLB Dance...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm…\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín.\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1656, 740, 2, 'Fullstack Developer (ReactJS + NodeJS)', 'Job Description\n\n5+ years of experience in the analysis, design, and development of large scale software solutions with NodeJS and ReactJS.\nDeeply understand Javascript and had experience in Front-end & Back-end frameworks\nStrong understanding and experience of:\n- Knowledge well in design patterns;\n- Clean code, coding standards, and code reviews & code refactoring;\n- Unit tests, mocking libraries, code coverage;\nCan lead technical support and training.\nDetail-oriented and goal-driven person.\nHaving any of the below experience/knowledge is a plus:\n- SSO & Microservice architecture\n- GraphQL, PostgreSQL, MongoDB, ElasticSearch\n- K8s, Docker\n- System monitoring, Time Series Database (e.g. StatsD, InfluxB, Graphite…)\n- CI/CD with Gitlab, Azure DevOps, Bamboo, Bitbucket or similar tools\n- Cloud services (GCP, AWS, or Microsoft Azure…)\n\nRequirements\n\n- Degree in Computer Science or Equivalent field\n- Strong knowledge of technical solutions with experience on any one distribution platform (Application /Information /Security), including Agile and DevOps.\n- In-depth knowledge of a Distribution System\n- Proficiency in development using ReactJS, Node.JS, Frontend Web / Mobile, Unit test\n- Experience: Min 2 –5 years of experience in technical delivery\n- Good at English communication.\n- Soft-skills:\n  - Results Focused and Outcome Driven\n  - Creative Problem Solving\n  - Teamwork and Cooperation\n  - Effective Communication\n\nBenefits\n\n- Training and career development opportunities.\n- Package: 13, 14 salary months + Project bonus + KPI bonus.\n- Extra package: 16 Mil /employee/year (Bonus at: Tet, New Year, your birthday, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, …)\n- Salary review 2 times/year or on excellent performance.\n- Opportunity to approach newest technology trends; development of your career within an international Company. Building large-scale & global software products for our clients.\n- Paid annual leave: 12 days + gift for your birthday.\n- Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (PTI care premium, Company trip, Holiday, Sum-up, etc.).\n- Exciting leisure: sport and art events (football club, family day, happy hour,).\n- Working time: 8h/day (from Monday to Friday), flexible working time (Check in: 8h -9h; Check out: 17h-18h).\n- Working place: 10th Floor, CMC Creative Space, Tan Thuan EPZ, District 7, HCMC\n\n2+ years of working experience\n\n- Please send your application via email: recruitment@cmcglobal.vn\n- Years of Experience Required\n- Required Education Level\n\nBachelor’s Degree\n\n- Job Level\n\nMiddle/Senior\n\n- Work Form\n\nFull-time\n\n- Email: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1657, 197, 2, 'Backend Engineer (Go, Java)_Co-Lending Partnership', 'Become a Backend Engineer at Trusting Social and join our transformative Co-Lending partnership initiative, where you\'ll contribute to projects reshaping financial services globally and in Vietnam. Your work will involve enhancing automated credit evaluation systems to efficiently manage high volumes of applications through instant registration, approval, and decision-making processes. Furthermore, you\'ll play a key role in revolutionizing credit card experiences by facilitating instant issuance, payments, and providing numerous benefits to empower financial freedom for users.\n\nResponsibilities\n\n- Develop Scalable Web Service APIs: Build highly scalable, highly available, and fault-tolerant web service APIs designed to handle millions of transactions per day.\n- Agile & DevOps Practices: Follow Agile methodologies and DevOps practices such as CI/CD to deliver quality code rapidly to market.\n- Seamless Integrations: Create software services that integrate effortlessly and securely with banks, third-party platforms, and vendors.\n- Innovative Problem Solving: Think outside the box, innovate, experiment, and continuously improve by learning quickly from failures to provide simple yet effective solutions to complex problems.\n\nRequirements\n\nEducational Background:\n\n- Bachelor’s degree or higher in Computer Science, Engineering, or a related field.\n\nExperience\n\n- 5+ years of software development experience.\n- Solid expertise in Golang (or the confidence to learn it quickly when coming from other similar programming languages).\n\nAPI Design & Development\n\n- Proficient in designing and developing RESTful APIs and gRPC interfaces.\n- Experience building backend services optimized for high performance, scalability, and reliability.\n\nDatabase Expertise\n\n- Strong database and schema design skills for performance and scalability across both relational and NoSQL databases (e.g., MySQL, PostgreSQL, MongoDB, Redis, Elasticsearch, RocksDB).\n\nSystem Design\n\n- Deep understanding of complex system design, design patterns, data structures, algorithms, microservices, and event-driven architecture.\n- Experience with system tuning for high performance and reliability.\n\nDevOps & Tooling\n\n- Hands-on experience with CI/CD tools such as GitHub workflows and Jenkins.\n- Familiarity with Docker containers and Kubernetes.\n- Knowledge of automated testing practices, caching techniques, and version control systems like Git.\n\nNice To Have\n\n- Experience with cloud platforms (AWS, GCP, or Azure).\n- Exposure to or interest in the AI domain with a willingness to leverage AI to enhance team productivity.\n- Experience with microservice architecture is a plus.\n\nWhat We Offer\n\n- Competitive compensation package, including 13th-month salary and performance bonuses\n- Comprehensive health care coverage for you and your dependents\n- Generous leave policies, including annual leave, sick leave, and flexible work hours\n- Convenient central district 1 office location, next to a future metro station\n- Onsite lunch with multiple options, including vegetarian\n- Grab for work allowance and fully equipped workstations\n- Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n- Unlimited free coffee, tea, snacks, and fruit to keep you energized\n- An opportunity to make a social impact by helping to democratize credit access in emerging markets\n\nAbout Us\n\nWe are an AI Fintech company specializing in assessing credit profiles of consumers in emerging markets combining pioneering AI with large alternative data sources. In 2020 we reached our ambitious milestone of credit profiling 1 billion consumers spanning 4 countries - Vietnam, Indonesia, India & the Philippines - and building a platform for the wider industry and the financial services industry, in particular, to provide the "un & under" served access to credit. At the core of this initiative has been our strict and unwavering adherence to the norms of consumer data privacy and consumer data rights.\n\nBut we\'re not satisfied as we embark on the next leg of our journey to deliver 100 million credit lines to consumers in the markets where we operate. Although this goal is ambitious, we truly believe that by harnessing the power of AI & Big Data we can deliver financial access at an unprecedented scale.\n\nAs a firm, we\'re audacious problem-solvers motivated by our impact on society. We deeply espouse the values of ownership - of our actions and initiatives, integrity in all we do, and agility in execution.\n\nWe place great importance on doing what is right, what is best, and what is innovative. If you are smart, driven, and want to make a difference in the world with the most advanced and fascinating technology, come join our team. We can satisfy your desire to explore new territory and give you the runway to really make an impact.\n\nAdditional Info\n\nLearn more about us here:\n\nhttps://www.youtube.com/watch?v=inAEDGvOcL8&t=29s', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh-Stadt, Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1658, 182, 2, 'API Integration Engineer (Java/Python/Golang)', 'Primary job is to do integration work using Java/Python/Golang, REST, SOAP APIs and Identity service\nSolving complex technical and business problems and learn new technology and frameworks\nBe part of a team that will take full responsibility for the features you own\nDesign, develop, test, deploy, monitor and improve, you are responsible for the full life-cycle of your product - build it, own it\n\nRequirements\n\nMust have:\n\nA pragmatic mindset\nOutstanding problem-solving ability, eagerness to learn, and curiosity\nA few years of software development experience with one or more general-purpose programming languages\nAdaptable attitude and personality that is ready for continuous change\nCollaboration and culture fit in Agile experience will be an advantage\nThe ability to communicate effectively with business and technical teams\n\nNice to have:\n\nExperience working with API Management platforms like: WSO2 / MuleSoft / Kong - design and development of APIs, guidance on design and development best practices, define strategy for operational procedures such as version control, deployments, monitoring - is a big plus\nExperience in OAuth2 implementations using any Identity/SSO tools\nAPI\'s designing and modeling using Swagger and API Developer toolkit\nExperience in Installation and configuration of various API product features and capabilities\nGood to have knowledge on Middleware and ESB tools\nExperience working with Amazon Web Service\nExperience working with Observability platform like DataDog / NewRelic\nGood skills in English\n\nBenefits\n\nMeal and parking allowance are covered by the company\nFull benefits and salary rank during probation\nInsurances as Vietnamese labor law and premium health care for you and your family without seniority compulsory\nPerformance bonus up to 2 months\n13th month salary pro-rata\n15-day annual leave+ 3-day sick leave + 1 birthday leave + 1 Christmas leave\nSMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development\nValues-driven, international working environment, and agile culture\nOverseas travel opportunities for training and working related\nInternal Hackathons and company\'s events (team building, coffee run, blue card...)\nWork-life balance 40-hr per week from Mon to Fri', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1659, 221, 2, 'BRSE', 'We are looking for a BrSE candidate to join the project from offshore, receiving the requirements from clients, then communicating and cooperating with the Software Development/ Offshore team to develop the system and managing the development process of the software projects for clients.\n\n● Understand business processes, discussing and making clear with the customer on business requirements and translating them into system specifications.\n\n● Work under the client\'s side.\n\n● Understand the requirements and deploy them to the Offshore/ Software Development Team.\n\n● Communicate requests and inquiries between offshore and the client.\n\n● Participate in the meeting with clients and support communication.\n\n● Support understanding of the team of provided materials.\n\n● Change requirements management.\n\n● Responsible for reviewing the Offshore review report, reviewing the deliverables, and taking charge of the deliverables\' quality and deliverables.\n\nProject work scope management (including variable work scope depending on the original work scope)\n\nQualifications and Education Requirements:\n\n● 01 year work experience of BRSE role\n\n● 2+ years of hands-on system development experience, including web services or native app development.\n\n● 1+ year of experience with AWS. (Including one of the following certificates: AWS Solution Architect Associate, or AWS Developer Associate or above.)\n\n● Good at English and Fluent in Japanese (N2) in both verbal and writing skills.\n\nWhy should you apply?\n\n● Fully paid insurance coverage, premium health care, and annual health checkup\n\n● 20 days of annual leave plus 1 more day for the Anniversary Establishment Day in Oct\n\n● All benefits followed Vietnamese labor law, including a 13th-month salary\n\n● Training allowance\n\n● Annual company trip\n\n● Annual performance review\n\n● Free parking card\n\n● A laptop that fits your needs.\n\n● Sport Clubs (Football and badminton)\n\n● English Speaking Club\n\n● Free beverages\n\nWork at District 1, HCMC from Monday to Friday (9 AM to 6 PM)\n\nInterested in applying? Reach out to us at recruitment@vietlink.jp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1660, 899, 2, 'Fullstack Developer (Nodejs - Frontend)', 'Job Description\n\n- Work with development teams and product managers to ideate software solutions\n- Design client-side and server-side architecture\n- Build the front-end of applications through appealing visual design\n- Develop and manage well-functioning databases and applications\n- Write effective APIs\n- Test software to ensure responsiveness and efficiency\n- Troubleshoot, debug and upgrade software\n- Create security and data protection settings\n- Build features and applications with a mobile responsive design\n- Write technical documentation\n\nCompensation & Benefits\n\n- Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n- Work performance review 2 times/ year (in April and October);\n- Performance bonus, 13th- month salary, public holidays bonus (2/9, 30/4, 1/5, 1/1); bonus for Excellent Employee and Excellent Team;\n- Social insurance, health insurance, unemployment insurance and Bao Viet care insurance;\n- 01 hour paid leave per day for women having children under 12 months\n- 01 day remote work per month; A flexitime allowance of 90-180 minutes per month for employees\n- Minimum 14 paid leaves per annum for all employees after probation;\n- Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks;\n- Yearly company trip and year-end party, quarterly team building and weekly eating together; English - Japanese Club, Sports Clubs;\n- Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company;\n- Flat, open and sharing culture with friendly management team; outsourcing company with product mindset;\n- Training courses and working opportunities with technical gurus who built and operated world-class applications with millions of users. This might be a good chance for graduated students to learn cutting-edge technologies and how to build scalable system from scratch;\n\nRequirements\n\n- Proven experience as a Full Stack Developer or similar role\n- Strong experience with backend programming: NodeJS\n- Knowledge of at least one of front-end frameworks (e.g. ReactJS, Angular, VueJS)\n- Experience developing desktop and mobile applications\n- Familiarity with common stacks\n- Familiarity with databases (e.g. MySQL, MongoDB), web servers\n- Extensive knowledge about OOP and design patterns\n- Good at English (speaking skill) is a plus', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1661, 750, 2, 'Back End Developer (Java/ Go/ Python)', 'We are seeking a skilled and driven Backend Developer to join our team and play a pivotal role in shaping the core functionalities of our cutting-edge Platform as a Service (PaaS) solutions. As a Backend Developer, you will design, build, and optimize the server-side components of our applications, ensuring reliability, scalability, and performance.\n\nIf you thrive in solving complex problems, are passionate about backend development, and excel in creating robust APIs and services, we’d love to have you on our team!\n\nWhat You\'ll Do\n- Build Scalable Backends: Design, develop, and maintain scalable and high-performance backend systems using modern programming languages (e.g., Java, Python, or Go) and frameworks.\n- Develop APIs: Create and optimize RESTful and GraphQL APIs to enable seamless integration with frontend applications and external services.\n- Database Design & Management: Work with relational and non-relational databases (e.g., MySQL, PostgreSQL, MongoDB, Redis) to store and process data efficiently.\n- Collaborate Across Teams: Partner with frontend developers, DevOps engineers, and stakeholders to deliver end-to-end solutions.\n- Ensure Robustness: Implement secure, maintainable, and efficient code that adheres to industry standards and best practices.\n- Testing & Debugging: Perform unit, integration, and performance testing to identify and resolve bottlenecks and bugs.\n- Optimize for Performance: Monitor and improve backend performance, ensuring the platform remains fast and reliable under load.\n- Contribute to CI/CD Pipelines: Streamline and enhance continuous integration and continuous deployment pipelines to ensure smooth, reliable, and automated delivery of code changes.\n- Stay Up-to-Date: Explore and incorporate new backend technologies and methodologies to improve the platform\'s functionality and scalability.\n\nWhy Join Us?\n- Work on innovative PaaS solutions that are transforming how applications are developed and deployed.\n- Collaborate with a talented and supportive team in a dynamic, fast-paced environment.\n- Grow your skills with opportunities to learn and experiment with the latest backend technologies.\n- Competitive salary and benefits, with opportunities for professional growth and development.\n\nRequirements:\nWhat You\'ll Need\n- Proven Experience: 3+ years of experience as a Backend Developer or similar role, with a strong focus on building scalable and secure systems.\n- Technical Expertise: Proficiency in server-side programming languages such as Go, Java or Python.\n- Database Knowledge: Hands-on experience with relational databases (e.g., MySQL, PostgreSQL) and/or non-relational databases (e.g., MongoDB, Redis).\n- API Development: Strong experience designing and implementing RESTful APIs, GraphQL is a plus.\n- Performance Optimization: Familiarity with profiling tools and strategies to improve application performance.\n- Version Control: Experience with Git and collaborative development workflows.\n- CI/CD Experience: Knowledge of CI/CD pipelines and containerization technologies like Docker and orchestration tools like Kubernetes.\n- Problem-Solving Skills: A proactive mindset with a strong ability to debug, analyze, and resolve complex technical issues.\n- Communication & Collaboration: Strong communication skills and the ability to work effectively in a team-oriented environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1662, 946, 2, 'Full Stack Software Engineer (Vietnam Only)', 'Join us in revolutionizing how businesses interact with data! We\'re building a cutting-edge platform that augments Business Intelligence with Agentic AI at a $400M/year revenue Vireo from our AI tech hub in Vietnam. Imagine a chat interface that doesn\'t just fetch data, but allows users to interact with structured information intuitively, receive deep-dive analyses, and get actionable business suggestions – all powered by intelligent agents. Our ultimate vision is to replace traditional Data Analysis and BI with a smarter, more proactive AI-driven solution. If you\'re passionate about building the future of data analytics, this is your opportunity.\n\nKey Responsibilities\n\n- Architect and Scale Core Systems: Lead the design, implementation, and optimization of highly scalable, fault-tolerant backend services and non-blocking APIs using Python (FastAPI) or Java (Vert.x, Quarkus). Ensure services handle high throughput with minimal latency.\n- End-to-End Product Delivery: Drive the full lifecycle of product features—from requirements gathering and prototyping through testing, deployment, and iteration—working closely with product managers, UX designers, and DevOps.\n- Champion Asynchronous Patterns: Build and maintain event-driven, asynchronous processing pipelines (e.g., message queues, pub/sub) to support real-time data ingestion, processing, and integrations.\n- Performance & Reliability: Establish and enforce best practices for monitoring, observability, and automated testing. Identify bottlenecks and implement caching, connection pooling, backpressure, and rate-limiting strategies to sustain 99.9%+ uptime.\n- Comprehensive Service Monitoring: Design, deploy, and maintain end-to-end observability solutions using Prometheus for metrics collection and Grafana for visualization and alerting.\n- AI & RAG Applications: Architect Retrieval-Augmented Generation (RAG) solutions and intelligent agents that solve real-world problems—integrating vector stores, LLM APIs (e.g., OpenAI), and custom prompting frameworks.\n- Mentorship & Collaboration: Provide technical leadership and mentorship to mid-level engineers, foster a culture of code quality, and collaborate across cross-functional teams to drive continuous improvement.\n\nRequired Qualifications\n\n- 5+ years of software engineering experience, with a proven track record of building and operating production-grade, scalable applications.\n- Expertise in Python & FastAPI or Java (Vert.x, Quarkus): Deep familiarity with asynchronous programming (async/await in Python or non-blocking event loops in Java), concurrency models, and profiling/tuning of services.\n- API Design Mastery: Hands-on experience building RESTful, GraphQL, or gRPC APIs that support high request volumes; strong understanding of HTTP/2, WebSockets, and protocol optimizations.\n- Cloud & Infrastructure: Proficient with AWS, GCP, or Azure; containerization with Docker; orchestration using Kubernetes/Helm; Infrastructure-as-Code (Terraform, CloudFormation).\n- Data Storage & Caching: Solid background in relational (PostgreSQL, MySQL) and NoSQL (MongoDB, Redis, DynamoDB) databases; designing data schemas for performance and scalability.\n- Asynchronous Ecosystems: Experience with message brokers (Kafka, RabbitMQ, AWS SQS), task queues (Celery, AWS Lambda) or Java equivalents, and stream-processing frameworks.\n\nPreferred Qualifications\n\n- RAG & Agent Development: Practical experience implementing Retrieval-Augmented Generation pipelines, vector search (e.g., Pinecone, Weaviate), and building autonomous agents with LangChain or similar frameworks.\n- AI/ML Collaboration: Familiarity with embedding-based search, prompt engineering, chaining, and orchestration of multi-LLM workflows.\n- Observability & Security: Strong grasp of logging, tracing (OpenTelemetry), metrics (Prometheus/Grafana), and security best practices (OAuth2, JWT, encryption).\n- Leadership & Communication: Excellent verbal and written English skills; demonstrated ability to influence technical direction and collaborate effectively across teams.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1663, 820, 2, 'Senior Java Developer', 'MÔ TẢ CÔNG VIỆC\n\nCập nhật, nâng cấp các chức năng hiện có và tạo ra các chức năng mới bằng cách sử dụng thông tin chi tiết dựa trên dữ liệu.\n\nThực hiện và triển khai dự án với chất lượng cao\n\nTham gia vào tất cả các giai đoạn của quá trình phát triển.\n\nTích cực tham gia các cuộc họp lập kế hoạch.\n\nTriển khai các tính năng mới theo đặc tả nghiệp vụ.\n\nViết và thực hiện unit test, functional test và integration test\n\nReview source code cho các thành viên khác trong nhóm\n\nTự động hóa việc bảo trì phát triển\n\nPhản hồi và giải quyết các yêu cầu hỗ trợ IT từ Nhân viên qua điện thoại, email và SR\n\nYÊU CẦU\n\nCó kinh nghiệm từ 5+ năm thiết kế, triển khai và hỗ trợ bảo trì các ứng dụng dựa trên Java (Spring Framework) với Frontend (JSP)\n\nPhân tích, thiết kế và phát triển chức năng mới, tuân thủ các tiêu chuẩn được cung cấp, cũng như hỗ trợ bảo trì hoặc sửa lỗi khi cần thiết\n\nĐã làm việc trên các dự án quy mô doanh nghiệp sử dụng: Oracle P/L, MyBatis+ Java (Spring Boot / Spring Framework)+ JSP (JavaScript / JQuery)+ Git (Git Runner)\n\nThành thạo các công nghệ hoặc công cụ như Azure, AWS, Redis, v.v.\n\nKỹ năng thành thạo với các công cụ được sử dụng trong chu trình phát triển phần mềm, như DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven và các công cụ CI/CD khác\n\nKinh nghiệm với các Cơ sở dữ liệu như *Oracle, Microsoft SQL Server hoặc MySQL. Hiểu cấu trúc và có kinh nghiệm thực hành viết Query, Stored Procedures, Functions, Scheduler, Table, Index, v.v.\n\nQuen thuộc với debug và tối ưu hóa hiệu suất, cùng với hiểu biết tốt về triển khai, bảo trì và giám sát các ứng dụng Java Web phức tạp.\n\nKỹ năng phân tích và thiết kế Hướng đối tượng chắc, hiểu biết về design patterns và concepts cũng như tuân thủ theo chuẩn hóa của hệ thống.\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 31 tháng 7, 2025\n\nChi tiết công việc\n\nSố Lượng\n\n4\n\nĐịa Điểm\n\nHồ Chí Minh\n\nKinh Nghiệm\n\n4 năm\n\nTrình Độ\n\nSenior\n\nHình Thức\n\nNhân viên bodyshop\n\nKỹ Năng\n\nJava', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1664, 947, 2, 'Senior Front-End Developer', 'Senior Frontend Engineer\n\nReports To: The Senior Frontend Engineer will report to the Solution Architecture Leader\n\nJob Overview: Be part of a fast-growing team of developers to support a range of frontend tasks to build several C2C products.\n\nResponsibilities and Duties:\n- Participate in all software development activities following the Scrum process.\n- Gather and address technical and design requirements.\n- Develop highly responsive, web-based user interface components and modules using ReactJS, NextJS.\n- Design and implement responsive, efficient, and attractive user interfaces.\n- Work closely with UX/UI teams to ensure the final product meets design and user experience standards.\n- Optimize application performance for speed and scalability.\n- Contribute to technology assessment, selection, and technical decision-making.\n- Collaborate with backend teams for API and service integration.\n- Maintain and improve code quality, ensuring high maintainability and quality.\n- Provide technical guidance and mentorship to junior and mid-level engineers within the team.\n- Review AI-generated code (e.g., Cursor, Copilot, ChatGPT) to ensure quality and maintainability.\n- Investigate root causes of bugs and provide constructive feedback and coaching.\n- Contribute to technical decision-making processes within the team.\n- Promote knowledge sharing and maintain well-organized documentation across the team.\n\nCandidate Must Have:\n- High energy and a desire to work in a results-oriented, fast growth company that never lost its start-up spirit.\n- 5+ years of industry experience designing, building and shipping web projects.\n- Proficiency with asynchronous programming, ES6.\n- Proficiency with ReactJS, NextJS.\n- Strong experience with popular Linux distributions such as Ubuntu, CentOS.\n- Degree in Information Technology, Computer Science, or related field.\n- At least 5 years of experience working with HTML, CSS, and JavaScript.\n- Proficiency in modern frameworks such as React, Angular, or Vue.js.\n- Experience with RESTful APIs and JSON.\n- Solid understanding of web design principles and user experience.\n- Creative problem-solving skills and the ability to work independently as well as in a team environment.\n- Experience with micro-frontend architecture and implementation.\n- Ability to develop internal training content and facilitate skill-sharing sessions across the engineering team.\n\nPreferred Qualifications:\n- Experience with TypeScript.\n- Experience with AngularJS.\n- Have AI Coding knowledge:\n- Have hands-on experience using AI-powered coding assistants (Cursor, Copilot, Devin, or similar tools) in real-world projects.\n- Understand how to collaborate with AI agents to speed up prototyping, refactor legacy code, generate boilerplate code, and automate repetitive tasks.\n- Can provide feedback to improve prompt engineering and suggest process improvements based on experience with AI tools.\n- Understanding of Agile and Scrum development processes.\n- Experience with automated testing tools (e.g., Selenium, Jest).\n- Experience with version control tools like Git.\n\nWhy Candidate Should Apply:\n- An exciting opportunity to work in a friendly and international working environment (VietNam - Japan).\n- Performance Review Bonus.\n- Annual Health Checkup.\n- Attractive Health Care Insurance Package.\n- 14 Days Annual Leave.\n\nAbout C2C Tech Hub: We are a startup company with a mission to change the daily-life of people around the world with C2C applications. At C2C Tech Hub, there are no restrictions on nationality, gender or working style, and you have the chance to come in and help us build new products on a small, agile team. Your contribution will be felt immediately and you will be able to help us shape our products and development path.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1665, 948, 2, 'Senior Software Engineer, Full-Stack (VN)', 'QCP is Asia\'s leading digital asset partner, empowering clients to seamlessly integrate digital assets into their portfolios.\n\nWe offer a comprehensive range of solutions - from spot on/off ramping and fixed income strategies to vanilla options and bespoke exotics.\n\nDriven by the vision to be the most trusted partner in digital asset markets, we provide innovative solutions that make digital assets a core component of every portfolio, balance sheet, and treasury.\n\nSince our founding in 2017, we have witnessed the potential of digital assets to transform financial markets and the world at large. We exist at the centre of change, successfully navigating three market cycles and bridging institutional and crypto ecosystems.\n\nWe work to build trusted partnerships, putting client success and care at the heart of everything that we do.\n\nResponsibilities\n\nTo work on the design, architecture and building of enterprise systems;\nTo work on the building of tools, reports, and feeds to fulfil business requirements from the trading, operations and risk teams of the company;\nTo be responsible for software quality, efficiency, cost and operational resiliency; \nTo participate actively in cross-company technology efforts to achieve various business and/or operational goals, as the need arises;\nTo work closely with the various Heads of business lines and front office trading in the proper implementation and effective maintenance of various systems\n\nRequirements\n\nAt least 4 years of experience working in a technical role. \nBachelor\'s or postgrad from a renowned University in a related field\nAWS certification a distinct advantage\nFresh graduates welcome to apply\nIdeal candidates will possess the following skillsets\nExperience in a cloud environment. \nStrong Computer Science fundamentals\nSoftware architecture and design\nCloud infrastructure (AWS or other major cloud platforms)\nExtensive Java experience is beneficial but not a requisite (ideally including Spring Boot)\nDatabase design and management (ideally PostgreSQL)\nQueue-based systems (Ideally Kafka)\nRunning agile software development teams (Scrum, JIRA and Atlassian suite)\nTesting approach and implementation (Unit/integration testing, Functional testing)\nDevOps experience (CI/CD pipeline development, Containerised systems, Automated deployment)\n\nBenefits\n\nThe Environment We Offer\n\nAs a growing firm with a tightly-knit team, we respect and listen to all our employees. You will get the chance to make an impact by having your voice heard by everyone, including the management.\n\nOur employees enjoy a high level of autonomy at work. We focus on substance, not form - as long as you can perform, you will be recognized and rewarded. We are also dedicated to supporting our staff and ensuring they develop holistically to maximize their potential in the long- term.\n\nWe also provide flexible working arrangement as required and a casual and fun environment to boot!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1666, 941, 2, 'Senior Fullstack Engineer - Node.js + Vue.js', 'We are a fast-growing SaaS company in the EduTech space, operating mainly in Singapore, Vietnam, and Malaysia. With almost 2000 schools as customers, our mission is to revolutionize early childhood education through technology and provide innovative solutions to our customers. With a team of 60 talented individuals, we are committed to transforming the way education is delivered in the Southeast Asian region and beyond.\n\nWhat you will be doing:\n\n- Develop full-stack services in Typescript for in our existing application\n- R&D novel and ingenious solutions to creating enhanced user experiences tailored to a multitude of global regions\n- Continuously enhance the app with the latest code-improving methodologies available\n- Use modern DevOps tools and automate everything with Docker and our Kubernetes clusters\n\nYour Skills And Experience\n\nMust have:\n\n- Deep expertise in Typescript, Vue and MySQL\n- Containers are first class in your apps\n- Understanding of MVC design pattern\n- Familiar with a wide range of performance optimization solutions\n- Strong understanding of vanilla front-end technologies, such as JavaScript, HTML5, and CSS3\n- Sound coding practices with tools such as git, unit testing, CI/CD, service oriented architecture\n- Linux confidence\n- Solid understanding of information security', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1667, 824, 2, 'MOBILE DEVELOPER (React Native)', 'MOBILE DEVELOPER (REACT NATIVE)\n\nWe are looking for a talented and motivated React Native Developer to join our mobile development team. You will be responsible for developing and maintaining cross-platform mobile applications with a focus on performance, scalability, and great user experience.\n\nKey Responsibilities\n\n- Develop mobile applications using React Native, ensuring high performance and high-quality visual elements and responsiveness.\n- Work closely with product owner, designers, and backend developers to deliver high-quality features.\n- Optimize app performance and ensure smooth UI/UX across iOS and Android.\n- Write clean, modular, and testable code following industry best practices and coding standards.\n- Troubleshoot and debug issues, and deploy timely fixes.\n- Integrate third-party APIs, native modules, and platform-specific features.\n- Participate in code reviews, sprint planning, and other agile ceremonies.\n\nRequirements\n\n- 3.5+ years of experience in mobile app development.\n- Proficiency in JavaScript (ES6+); TypeScript is a plus.\n- Solid understanding of React Native architecture, React lifecycle, hooks, and navigation libraries (e.g., Wix React Native Navigation, React Navigation).\n- Experience with React Context, Redux, or other state management libraries.\n- Experience with React Native Reanimated, FlashList, or Skia.\n- Knowledge of mobile performance optimization techniques.\n- Proficiency in caching and memoization techniques to enhance application performance.\n- Familiarity with native modules integration (iOS/Android).\n- Experience working with RESTful APIs and third-party libraries, particularly with Firebase integration.\n- Experience with real-time communication using Socket.IO or similar libraries.\n- Understanding of mobile security best practices.\n- Familiarity with mobile testing tools (e.g., Jest, Detox, Appium) is a plus.\n- Proficient with version control (Git), CI/CD pipelines (e.g., Fastlane, GitHub Actions), and bug tracking tools (e.g., JIRA).\n- Good communication skills and ability to work in a collaborative environment.\n- Ability to work independently and take ownership of features from concept to deployment.\n\nBenefits\n\n- Working time: 5 days/week (Monday to Friday)\n- Opportunity for promotion and career development\n- Competitive Income\n- Attractive Bonus Policy\n- Compulsory Insurances full salary (Social Insurance, Health Insurance, Unemployment Insurance) based on the Labor Code and PVI premium health Insurance based on the Company\'s regulations\n- 11 Public holidays based on the Labor Code, 15-17 Annual leave days based on the Company\'s regulation, 5-year-employee has 1 more annual leave day\n- Company Team Building Trip every year\n- Participate in other Company activities: Sports, Family Day, Children\'s Day\n- Training sponsorship programs: Securities certificates, Soft skills, Technical skills\n- Professional and dynamic working environment.\n\nWork Place\n\nVietcap Securities Joint Stock Company\n\nFloor 15, Bitexco Financial Tower, 02 Hai Trieu Street, District 1, HCMC\n\nEmail: job@vietcap.com.vn\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Provincia di Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1668, 949, 2, 'Ruby on Rails Developer', 'Are you a passionate Ruby on Rails Developer with at least 3 years of experience? If so, we want you on our team! At Golden Owl Solutions, you’ll play a key role in creating and maintaining innovative web applications.\nYou’ll have the opportunity to ensure exceptional code quality across both back-end and front-end development. If you\'re ready to make an impact and grow in a collaborative environment, we’d love to hear from you!\n\nWhat You Can Expect\nJoin a fast-growing IT Solutions company in Southeast Asia, collaborating with global clients across various sectors such as startups in Southeast Asia, Australia, and the UK.\n100% involvement in projects with international enterprises, offering you exposure to diverse challenges and opportunities to enhance your expertise.\nBe part of a dynamic, highly skilled team focused on innovation and quality delivery.\nEnjoy a clear path for personal and professional development through on-the-job training, mentorship programs, and participation in workshops and seminars.\nOpportunities for career advancement, with the potential to take on leadership roles within a rapidly growing organization.\n\nYour Responsibilities\nWork closely with clients via Slack or WhatsApp to gather requirements and deliver quality features.\nDevelop and maintain clean, efficient Ruby on Rails code for both back-end and front-end.\nUse tools like Trello or Jira to manage tasks and track progress.\nWrite unit tests (TDD) and participate in code reviews to ensure code quality.\nCollaborate with team members to plan features, estimate timelines, and solve problems.\nFollow Git workflows for branching, pull requests, and code merging.\nMentor junior developers and support team knowledge sharing.\n\nRequirement\nMust have\n3+ years of working experience as a Ruby on Rails Developer. \nExperience with popular Rubygem like Devise, Sidekiq, Cancancan…\nGood understanding of front-end languages and technologies: JavaScripts, HTML5, CSS;\nGood understanding of relational databases such as PostgreSQL, MySQL,...;\nGood understanding of how to consume and create with RESTful APIs;\nExperience in code version control tools such as Github/ Gitlab/ Bitbucket;\nProactive to take ownership and single-handedly handle problems if required;\nGood English usage;\n\nNice to have\nExperience with CI/CD;\nExperience with deployment RoR applications;\nHands-on experience on building products from scratch;\nModern front-end frameworks (ReactJS, VueJS,...);\nGood teamwork and reliability.\n\nWhat we offer\nSemi-annual performance reviews with salary adjustments.\n12+ days of annual leave.\n13th month salary.\nLunch and parking allowances.\nProvision of Macbook for work.\nAccess to PS4 games/billiards during leisure time.\nMonthly team-building activities.\nMonthly birthday gifts for staff.\nCompany-sponsored social events and gatherings.\nRegular training and knowledge-sharing sessions.\nCompany-wide annual trip.\nPrivate health check-ups.\nOpportunity for advancement to a team leadership role based on demonstrated leadership skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1669, 676, 2, 'Full-Stack Engineer (Java + ReactJs)', 'DXC Technology is a global leader in IT services, providing transformative digital solutions that drive innovation and efficiency for our clients. We are seeking motivated Senior Fullstack Engineers (Java, ReactJs) who are passionate about applying their technical skills to develop and deliver industry-leading lending solutions for small and medium-sized businesses across Globe.\n\nYOUR JOB RESPONSIBILITIES\n• Design, develop, test, deploy, and support for application code and services that your Agile Team builds.\n• Design, build and manage continuous integration, build management and deployment scripts, systems, and any code as required.\n• Participate in Agile software development, prototyping, and code review with international development teams to build scalable microservices-based products.\n• Understand the requirements of the Product Owner and utilize this knowledge to develop applications that are consistent with this.\n• Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes and tooling.\n• Provide robust coding practices, solid unit and component test coverage, and code debugging.\n\nYOUR SKILLS & EXPERIENCE\n\nMust have\n• 5+ years of experience as a software engineer in a complex development environment.\n• Solid experience in Java 8+ and Springboot.\n• Familiar with modern front-end technologies – Webpack, Gulp, HTML5, CSS3 including accessibility standards. Experience in JavaScript ES6/TypeScript working with React.JS\n• Have experience with Postgres, MongoDB\n• Solid experience in designing & developing RESTful APIs and Microservices-based system\n• Solid experience in modern front-end build pipelines and tools (e.g. Git, Webpack, Gulp, NPM)\n• Have awareness and experience with Containers (ECS, Kubernetes, Docker) and FaaS (AWS Lambda) technologies\n• Experience working in a cross-functional team delivering using Agile methods\n• Well-versed in writing structured, well-documented, maintainable, and clean code;\n• Good understanding of modern software development practices and automation testing\n• Strong English communication skills (both verbal & written), able to communicate with business stakeholders\n\nNice-to-have\n• Experience in the Banking or Financial Services industry;\n• Experience in using front-end testing and test runners (eg. Selenium, Mocha/Chai/Jest).\n• Any additional certification or training in IT, Business, Computer Science, or related area.\n\nAt DXC Technology, we offer a dynamic and engaging work environment, providing opportunities to work on impactful projects that drive business success. If you meet the criteria and are passionate about quality engineering, we encourage you to apply and become a part of our innovative team.\n\nRecruitment fraud is a scheme in which fictitious job opportunities are offered to job seekers typically through online services, such as false websites, or through unsolicited emails claiming to be from the company. These emails may request recipients to provide personal information or to make payments as part of their illegitimate recruiting process. DXC does not make offers of employment via social media networks and DXC never asks for any money or payments from applicants at any point in the recruitment process, nor ask a job seeker to purchase IT or other equipment on our behalf. More information on employment scams is available here.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1670, 656, 2, 'Java Backend Developer', 'You will join other Developers, Manager Engineers, Test Automation Engineers, and Business Analysts. You’ll help to build key modules of our product where you’ll use and grow your experience to architect and build cloud applications, APIs and back end Java services to maintain high availability and reliability.\n\nYou’d work across the Service Team collaborating within your own squad, individual developers, and manager engineers to deliver first class banking software that provides real value to our customers and an outstanding user experience.\n\nYou will be a strong team player with good written and verbal communication skills, and a desire to participate in all aspects of the SDLC.\n\nResponsibilities include:\n• Design, build, and maintain efficient, reusable, and reliable Java services.\n• Follow our Software Development Life Cycle (based on SAFE methodology).\n• Gaining a deep understanding of our technology stack, driving our strategic plans with the ability to raise questions where necessary.\n• Supporting the deployment and progression of services from test environments through to production.\n\nApplicants must have a strong background in:\n• Java(8+), Spring Boot, Postgres\n• Agile methodologies.\n• Secure coding practices.\n• Git and/or GitHub.\n• Unit, component and integrated component testing and associated tooling.\n\nExperience with the following would be advantageous:\n• Collaboration and project management tools - especially Rally and Confluence.\n• API design using Swagger / OpenAPI\n• Automated testing frameworks and processes.\n• Cloud development experience (AWS, Azure).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1671, 950, 2, 'Full Stack Java Developer', 'Position: Full Stack Java Developer\n\nSalary Range: negotiate\n\nJOB DESCRIPTION:\n\n- Design, build, and maintain scalable and efficient backend APIs and services using modern frameworks and cloud technologies.\n- Develop and maintain web interfaces, ensuring seamless integration with backend systems.\n- Deliver customer-facing features and system improvements that directly impact user experience and business metrics.\n- Collaborate with product managers, designers, and other engineers to gather requirements and translate them into technical solutions.\n- Drive the full software development lifecycle: requirement gathering, system architecture, development, testing, deployment, and ongoing maintenance.\n- Create and maintain engineering design documents to ensure clear communication of system design and decisions.\n\nREQUIREMENTS:\n\n- From 4 years of professional experience in full stack development, with strong expertise in both backend (Java) and frontend (React.js) technologies.\n- Proficient in Java/JEE and modern frameworks including Spring Boot, Spring Security, and Spring Data.\n- Hands-on experience developing scalable web applications using React.js, with a solid understanding of modern JavaScript (ES6+), HTML5, and CSS3.\n- Familiarity with state management libraries such as Redux or Context API.\n- Strong understanding of RESTful API design, development, and integration.\n- Proficiency in using version control systems such as Git (GitHub, Bitbucket) and collaborative development workflows (PRs, code reviews).\n- Solid experience working with relational databases (PostgreSQL, MySQL) and NoSQL solutions (MongoDB); performance tuning experience is a plus.\n- Experience with containerization tools like Docker.\n- Exposure to CI/CD pipelines and DevOps tools (e.g., Jenkins, GitLab CI, GitHub Actions).\n- Skilled in AWS, GCP, Azure, and Kubernetes (K8s); experienced in designing and deploying cloud-native applications and managing containerized environments.\n- Strong problem-solving skills and the ability to troubleshoot complex technical issues across the stack.\n- Excellent communication skills in English, both verbal and written.\n- Ability to collaborate effectively in a cross-functional team and thrive in a fast-paced, agile development environment.\n- A proactive mindset with a passion for learning and applying new technologies and best practices.\n\nWorking Conditions:\n\n- Attractive salary package (negotiable) and 100% salary from probation.\n- Social insurance full salary.\n- Health Insurance provided (Premium package).\n- Additional 12 paid day-off per year (beside annual leave by law).\n- Occasional Gifts (birthday, women day, etc.).\n- Yearly learning budget.\n- Yearly Position Level Assessments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1672, 316, 2, 'PHP Developer (all genders)', 'HRS As a Company\nHRS reinvents how businesses Work, Stay and Pay. Counting more than 5.000 corporations and 40 % of Fortune 500 companies in our customer base, HRS has emerged to the most trusted platform of digital software solutions in business travel hospitality worldwide.\n\nThe HRS platform is composed of three engines that each optimize one core building block along the corporate hospitality supply chain: Intelligent Procurement, Smart Booking and Invisible Payment. Through the integration of those engines into one large data-driven platform approach, our Lodging-as-a-Service value proposition enhances satisfaction of corporate employees and travelers, delivers the highest grade of process automation for corporate stakeholders and ensures strongest compliance end-to-end.\n\nBUSINESS UNIT\nDestination Solutions is part of the globally acting HRS Group. HRS is reinventing the way businesses and governments work, stay and pay in today’s dynamic global marketplace. HRS’ advanced platform technology is extending its reach beyond hospitality to meetings, office space management, payment efficiency and crisis recovery.\n\nPOSITION\nAs an experienced Senior Software Engineer, you will work in an agile team to technologically advance our PMS (Property Management System) and implement new features for this vacation rental product and attached modules. In addition, you will actively work on the big picture of the architecture and on the API interaction of the various products in order to create a uniform overall product portfolio.\n\nThe core part of the PMS product represents a typical PHP/mySQL tech stack, but the system is evolving towards service orientation and AWS cloud technologies – a perfect moment to be at the forefront of the technological modernization of a successful product.\n\nBased on your interests, you can familiarize yourself with cloud technologies, work with modern monitoring tools or contribute to architectural discussions. You can get involved in various areas in addition to product-related software development, from security topics to the use of AI in development to the evaluation of new technologies – we are used to working closely together beyond team boundaries and training each other.\n\nCHALLENGE\n• Fullstack development of our PMS product written in PHP\n• Further feature development in PHP or serverless in AWS\n• Implementation of interfaces and APIs to other DS products\n• Strong and active member of an agile team, including Product Owner support and cross-team collaboration\n• Active part of a team of engineers with regards to defining overarching technical concepts and practices\n\nFOR THIS EXCITING MISSION YOU ARE EQUIPPED WITH...\n• Proven work experience of at least 5 years in the field of software development\n• Solid understanding of the programming language PHP and ideally also of the Symfony Framework\n• Additional knowledge in React, Node.js and Typescript/JavaScript is an advantage\n• Experience with database systems (i.e. MySQL, MongoDB)\n• Competence in AWS and serverless architectures is an advantage\n• AI based Development and Tooling Knowhow is absolutely welcome\n• Good understanding of Scrum/Agile methodologies\n• Strong communication and teamwork skills\n• High sense of responsibility and goal-oriented way of working\n• Good english skills verbal and written\n\nPERSPECTIVE\nAccess to a global network of a globally united and mutually responsible “Tribe of Intrapreneurs” that is passionately dedicated to renew the travel industry and while doing so reinvent the ways how businesses stay, work and pay.\n\nOur entrepreneurial driven environment of full ownership and execution focus offers you the playground to contribute to a greater mission, while growing personally and professionally throughout this unique journey. You will continuously learn from a radical culture of retrospectives and continuous improvement and actively contribute to making business life better, smarter and more sustainable.\n\nLOCATION, MOBILITY, INCENTIVE\n• Full salary and benefits as an official employee on probation.\n• Hybrid working model.\n• Open and flat environment, highly appreciate your idea and constantly supporting your skill development.\n• Innovative and international learning and development program, we dedicate to supporting employees’ growth and development of skills.\n• Challenging products with onsite opportunities in Europe (Germany, Australia, Poland, etc.).\n• 13th-month salary & short-term incentives: we offer incentives as defined by the company’s success in the previous year.\n• 15+ annual leaves per year.\n• Full healthcare compliance.\n• Premium healthcare for employees.\n• Gifts for every special occasion.\n• Supportive working conditions: Laptop, MS Surface Hub.\n• Free and unlimited snacks, tea, coffee, and by-choice request.\n• Premium company trip & business traveling programs and other exciting activities.\n\nNote: This role offers a hybrid work model, with flexibility to work both from home and in the office.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1673, 951, 2, 'Game Designer', 'OBJECTIVES\n\nWe are seeking an exceptional and innovative Game Designer to join our team in building, developing, and publishing multiple game portfolios. As a Game Designer, you will collaborate closely with passionate cross-functional teams to create extraordinary experiences for players worldwide\n\nWhat You Will Do\n\n- Monitor, collect, and analyze in-game player data, conduct market research to synthesize insights, and transform these insights into actionable recommendations.\n- Brainstorm & consolidate ideas from team members to propose design solutions.\n- Take a lead in a high performance team (Music, Creative, Artist, Quality Control, User Acquisition) to ensure you will deliver the game that makes users love.\n- Maintain a game roadmap, prioritizing initiatives based on business impact.\n\nQualifications\n\nTechnical skills requirements:\n- Minimum of 1-2 years of experience as a Game Designer, Product Owner for one or more mobile game products.\n- Proven expertise in game design, core loop, and monetization strategies for diverse revenue models (ads, in-app purchases, hybrid) is highly desirable.\n- Strong game analysis skills: applicants must be able to intelligently deconstruct & discuss the strengths and weaknesses of games\' design and experience.\n- Strong critical thinking and analytical skills, able to work effectively in a data-informed environment.\n- Good sense of user experience & psychology in user design.\n\nSoft skills requirements: \n- A reliable, independent, and responsible individual.\n- Demonstrates a strong interest in and understanding of technology, marketing, analytics, and data-driven solutions.\n- A proactive learner who is eager to acquire new skills and stay updated on mobile market trends.\n- Experience creating wireframes, mockups, prototypes, and user interaction diagrams.\n- Practical application of Agile methodologies.\n- Fluent in English, both written and spoken.\n- An effective communicator capable of sharing ideas, discussing projects, and providing constructive feedback.\n\nWhat We Offer\n- Competitive salary and benefit packages.\n- ESOP package for all levels.\n- Personal learning and well-being budget\n- Team-building budget\n- Lunch and parking allowance\n- Minimum 12 days of paid annual leave, plus 10 days of paid sick leave\n- 12 days working from home per year\n- Opportunity to work on exciting mobile game projects.\n- Collaborative and supportive team environment.\n- Continuous learning and growth opportunities.\n\nHow To Apply\nClick the button or contact us at mep.talents@mepplatform.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1674, 743, 2, '[LTS] Developer NodeJS', 'Position : NodeJS Developer\n\nQuantity : 03\n\nType : Full-time\n\nLocation: 68 Nguyen Co Thach street, Ha Noi.\n\nJob Description\n\n- Participate in development projects for Web applications, Mobile Applications\n- Able to take the role of technical leader of the project, and propose technical solutions for various problems\n- Coaching project members\n- Perform design, implement coding, testing, and documentation in line with user & system requirements to deliver source code that meets the needs and release milestone\n- Perform bugs fixing, maintaining, and enhancement\n\nRequirement\n\n- At least 1 year of commercial experience with NodeJS\n- Integration of user-facing elements developed by front-end developers with server-side logic\n- Writing reusable, testable, and efficient code\n- Design and implementation of low-latency, high-availability, and performant applications\n- Experience with web applications fundamentals like React, React hooks\n- Experience with Javascript, Express, Graphql\n- Experience with MongoDB\n- Strong ability to understand existing code and fix bugs and write enhancements (without rewriting code)\n- ENGLISH is plus\n\nBenefits\n\n- Attractive salary (upto 2000$). Performance based award.\n- Young and dynamic working environment.\n- Continuous development of hard and soft skills through work and professional trainings.\n- Opportunity to approach newest technology trends\n- Salary review 2 times/year or on excellent performance\n- Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\n\nCONTACT\nLTS Recruitment Department\nPhone Number : 02466607474\nEmail : rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1675, 952, 2, 'Text-to-Speech Engineer (AI Conversation Team)', 'We are seeking a TTS Engineer (Text-to-Speech) to support the development and deployment of speech technologies. This junior-level role is ideal for someone eager to gain hands-on experience in AI product development, data engineering, and speech processing. You will begin by working on data-related tasks and progressively take on more responsibility in AI model training and evaluation.\n\nAbout FPT Smart Cloud\nFPT Smart Cloud (FCI) – a member of FPT Corporation, pioneers AI & Cloud solutions in Vietnam. FCI was founded with the mission to generating an immense leap in productivity and agility in business operations.\n\nFPT Smart Cloud aims at leading the industry by focusing on building a firm technological foundation, developing diversified ecosystem products, and reaching global connectivity.\n\nCustomized to specific needs: Providing cloud-based products and solutions customized to each industry.\nAll-in-one Platform: Consolidating FPT Smart Cloud technology and diverse business solutions all in one platform. AI & Cloud services are a Unify eco-system.\nLocal market leadership: Outstanding Cloud and AI technology infrastructure and platform to help local businesses grow their products and services online.\nDeliver the future: Help customers achieve business outcomes faster by integrating world-class processes and technology.\n\nKey Responsibilities\nCoordinate and oversee speech data collection, including both manual recordings and automated online data acquisition.\nPerform data processing tasks such as cleaning, segmentation, and automatic labeling.\nConduct quality checks and validation of speech datasets.\nGradually develop automated pipelines and tools for managing and processing speech data efficiently.\nSupport training and evaluation of TTS models as experience grows.\nCollaborate with cross-functional AI teams to improve system performance and scalability.\n\nRequirements\nSolid Python programming skills.\nComfortable with Linux development environments, including command-line tools, bash scripting, and Docker.\nStrong organization and communication skills.\nIntermediate English proficiency (reading and technical communication).\n\nPreferred Qualifications (Nice To Have)\nKnowledge of audio signal processing and related techniques.\nExperience with web backend development in Python (e.g., Flask, FastAPI).\nFamiliarity with AI and machine learning concepts.\nBasic experience with JavaScript for front-end or tooling development.\n\nTop Benefits\nSalary: Competitive, pay according to ability. Negotiation during the interview.\nSocial insurance and health insurance according to labor laws.\nCreative, open-minded working environment that respects individuals.\nFPT Premium Care package.\nActivities and culture with FCI and FPT Corporation.\nStudy support package for children of FCI union.\nSponsor related courses and certifications.\n\nWorking Environment\nWorking Location:\nSite Hanoi: 7th Floor, FPT Tower, no. 10 Pham Van Bach Street, Dich Vong ward, Cau Giay district, Hanoi\nSite HCMC: 3rd floor, PJICO Tower, no. 186 Dien Bien Phu, Ward 6, District 3, HCMC.\nWorking hours:\n8h30 AM – 12h00 PM\n1h00 PM – 5h30 PM\nWorking days: Monday to Friday (weekends off).\n\nContact Person\nPham Thi Ha My (Ms.) – Talent Acquisition Team Lead\n\nEmail: Mypth3@fpt.com\n\nPhone: 0962456194\n\nFPT Smart Cloud (FCI) Co., LTD\n\nAddress: 7th Floor, FPT Tower, No. 10 Pham Van Bach, Cau Giay Dist, Hanoi\n\nWebsites: FPT Cloud | FPT AI\n\n#Text-to-speech Engineer\n\nXem thêm các vị trí nổi bật khác tại đây: https://fptsmartcloud.com/co-hoi-nghe-nghiep\n\nSend CV', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1676, 953, 2, 'Python Developer', 'LARION, a global software outsourcing partner with 2 decades deep industry expertise. We are a 100% Vietnam technology company specializing in turnkey solutions and building highly skilled development teams for companies of all size and types of business. Run by a team of successful entrepreneurs and dedicated technical experts - LARION is a unique symphony where we create a frictionless future for customers with passion, while maintaining full compliance with your needs and objectives.\n\nWhat You’ll Do \nWe are looking for a technically strong Python Developer to join our dynamic operations team. In this role, you will be the first line of support for researchers and internal users by managing and resolving issues via our JIRA service desk. You will play a key role in driving operational efficiency through automation and smart tooling, ensuring timely and effective support.\n\nThe role of the operation support engineer will thus be two-fold:\n1. To help manage the flow of issues and resolve them. For the more complex issues they can then redirect to the Devops team for their handling, but the support engineer must still keep ownership;\n2. To come up with solutions to improve the efficiency of resolving issues. This would include exploring the user of bots to automate some of the common tasks, as well as to write scripts to programmatically categorize and handle the tickets in the JIRA service desk.\n\nWhat You’ll Bring \nRequirements:\n- Solid programming skills in Python, with experience in libraries such as NumPy, Pandas, etc.\n- Familiarity with Unix/Linux environments and shell scripting.\n- Hands-on experience with SQL and relational databases.\n- Working knowledge of JIRA, Git, and monitoring tools such as Grafana.\n- Strong problem-solving mindset with a proactive attitude.\n- Ability to take ownership of issues and see them through to resolution.\n\nPreferred Qualifications:\n- Background in DevOps or operational support roles.\n- Experience with web-based technologies such as JavaScript, Node.js, Django.\n- Exposure to Machine Learning or Artificial Intelligence techniques.\n- Familiarity with Generative AI tools (e.g., ChatGPT, Gemini) for enhancing support efficiency.\n- Strong communication and coordination skills.\n\nWhy You’ll Love Working Here \nWorkplace\n- Join a young and dynamic team with awesome projects applying the latest technology.\n- Working with specialists from all over the world provides you with a fantastic opportunity to expand your skill set.\n- Culture of openness and honesty in which individuals are respected and encouraged to achieve their full potential.\n\nBenefits comprise \n- 13th month salary and attractive performance bonuses.\n- Flexible hybrid working model between working at office and working at home.\n- Premium Healthcare and Accident insurance.\n- Annual health check package.\n- Free parking and allowances: Lunch, Marriage, Newborn baby, Bereavement and others applied.\n- A spacious pantry that is fully equipped with coffee maker, fridge, microwave and more for your most comfortable lunch time.\n- A wide range of sport and social activities: Yoga, Football, Badminton, Tech clubs, etc.\n- Annual company trip and teambuilding.\n- Chance to be honored quarterly and annually with recognition awards for individuals, teams, long-term service, etc.\n- Advanced English and appropriate soft skills training to assist your career development.\n- Engaging monthly events: Happy Gathering, Mini Game, Team Birthday Celebrations, Company’s Year-end party, etc.\n- Exclusive company supporting funds to ease your personal loans of Home, Vehicle, Tuition, etc.\n\nOffice Location: QTSC1 Building, Quang Trung Software City, District 12, Ho Chi Minh City.\n\nGentle notice to our candidate about Decree No.13/2023/NĐ-CP\nAccording to Decree No.13/2023/NĐ-CP on protecting personal data, LARION would apply "Personal Data Processing Agreement" with all candidates to ensure compliance with the decree.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1677, 954, 2, 'Full-stack Engineer', 'Company Description\n\nHomebase is a real estate technology company that levers up home-ownership solutions in Southeast Asia. Our obsession to execute at speed, asymmetric access to capital, and relentless and elite talent are our unfair advantages in bringing proven, multi-billion dollar business to the region.\n\nMuch of what we do is novel and has never been done before. From structuring multi-million dollar M&A deals to building groundbreaking technology, we’re re-creating the financial, technological, and operational future of real estate.\n\nWe’re backed by leading global investors from Vietnam, Singapore, Silicon Valley etc. who believe in our vision, including Y Combinator, Goodwater Capital, Class 5 Global, VinaCapital, and Antler; and are advised by CEO’s and founders hailing from some of the world’s largest and most successful tech companies, such as Alibaba, Lazada, 99.co, PropertyGuru and Zalora.\n\nHomebase’s team hails from world-class organizations, such as Harvard, Linkedin, McKinsey, Goldman Sachs, and etc. We believe in hiring only top talents, building a young and dynamic team, and keeping the team camaraderie strong and team-size lean.\n\nOur Company Culture\n\nTo learn more about what it\'s like to work at Homebase and our culture, please see here.\n\nJob Description\n\nWe are looking for a top-level computer programmer who is comfortable with both front and backend programming. A lot of what you do will be starting from scratch. You can expect a lot of autonomy; in return, we expect you to have a strong sense of ownership and desire to help shape the future direction of the company. The developer will have a chance to work directly with the core members of our high-performing team and will have the following responsibilities:\n\n• Developing frontend and backend architectures.\n• Designing interactive sites.\n• Developing backend applications.\n• Creating servers and databases for functionality.\n• Ensuring responsiveness of applications.\n• Working alongside graphic designers for web design features.\n• Building out our proprietary home price prediction model.\n• Designing and developing APIs. \n• Meeting both technical and consumer needs.\n\nOur Requirements\n\nWe are looking for candidates who fulfill the following criteria:\n\n• Degree in Computer Science, Engineering, or related field.\n• At least 5 years of programming experience, ideally with both frontend and backend exposure.\n• Able to communicate proficiently in English.\n• Proficiency with frontend languages such as JavaScript (ReactJS, NextJS) and backend languages and frameworks: NestJS (NestJS Microservices), Typescript, ExpressJS, Eslint, TypeORM\n• Proficiency with database technology such as PGSQL and MongoDB.\n• Familiarity with ML and big data concepts.\n\nBenefits And Opportunities\n\nCandidates will have unparalleled learning opportunities for learning and accelerated career growth working in a fast-paced, hyper-growth startup environment. As a member of the team, you’ll have opportunities to:\n\n• Salary ranges from 1,500 to 3,000 USD per month based on experience and interview results; \n• 100% salary social insurance;\n• Quarterly, yearly, 13-month bonus;\n• Annual health check, company trip and other company’s activities;\n• Develop core competencies in the areas of technology and computer science;\n• Take on high-impact and ultra-challenging projects that push the technological frontier of the company;\n• Flexible/hybrid work environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1678, 955, 2, 'Software Quality Assurance Engineer', 'As a Software QA Engineer, you will ensure the delivery of high-quality software products by designing comprehensive test plans, executing testing strategies, and performing User Acceptance Testing (UAT). This role involves close collaboration with development and business teams to ensure a seamless and flawless user experience.\n\nResponsibilities:\n- Collaborate with cross-functional teams to develop comprehensive test plans and strategies that align with product requirements and business goals.\n- Analyze software requirements to identify areas for testing and create effective test cases.\n- Execute manual tests to ensure the functionality, usability, and performance of the product meets.\n- Document and report defects, ensuring clear and detailed information for the product team to address and resolve issues promptly.\n- Conduct regular regression testing to validate software changes and ensure product stability.\n- Facilitate UAT sessions with business stakeholders, ensuring that the software meets end-user expectations and business requirements.\n- Participate in product design to provide feedback that can drive improvement in user experiences.\n- Contribute to the continuous improvement of the QA process by identifying areas for enhancement and implementing best practices.\n\nWhat You’ll Bring:\n- Background in Business, Economics, Information System, or related fields.\n- We want someone who is fearless in trying new things and learning new skills, able to adapt quickly and thrive in a dynamic setting.\n- From 1-2 years of experience in Software Quality Assurance or Business Analysis, preferably in ERP systems.\n- Experience in collaborating with PO, BA, and product teams in a dynamic and fast-paced environment.\n- Strong understanding of Software Development Life Cycle (SDLC), software testing methodologies, test case development, and test execution.\n- Self-motivated with a results-driven approach and the ability to thrive in a fast-paced environment.\n- Excellent problem-solving abilities, planning & organizing, and attention to detail.\n- Ability to work independently as well as collaboratively within a team.\n- Ability to communicate effectively in English is a plus.\n\nWhat does Cleeksy offer you?\n- Attractive salary with 13th-month salary.\n- All allowances and benefits are covered by Vietnam\'s Labor Law.\n- Annual Health Check-up, mindfulness area, and massage chair for your muscles - health is the greatest wealth. The challenge of a SaaS product is business management and digital transformation for the Vietnamese market.\n- Startup environment with diverse learning opportunities on the job.\n- Friendly, supportive, skilled colleagues and serious product lovers – they\'ll have your back and help you grow.\n- Support initiatives that promote employee well-being: Stocked cafeteria with snacks, and drinks, Happy Friday with F&B, and Team building.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1679, 829, 2, 'LLM Engineer (Middle)', 'I. Mô tả công việc\n• Lưu trữ và truy xuất dữ liệu: Lấy dữ liệu phi cấu trúc, indexing và/hoặc cấu trúc lại sau đó cho phép truy xuất\n• Tinh chỉnh và tối ưu hóa LLMs cho các ứng dụng cụ thể, sử dụng các kỹ thuật như fine-tuning, prompt engineering, và parameter-efficient tuning.\n• Thiết kế và triển khai hệ thống RAG, Agent để tăng cường độ chính xác và cập nhật thông tin cho LLMs.\n• Kiểm tra và đánh giá các thành phần. Đo thời gian tạo phản hồi, độ trễ của từng thành phần, lỗi và chi phí.\n• Hợp tác với các nhóm phát triển sản phẩm và kỹ thuật để tích hợp hiệu quả các giải pháp LLM vào hệ thống và quy trình kinh doanh hiện có của khách hàng.\n\nII. Yêu cầu công việc\n• Có tối thiểu 3 năm kinh nghiệm quan đến LLM, ưu tiên có kinh nghiệm về RAG/Agent\n• Có kiến thức về công nghệ và nghiên cứu LLM\n• Làm quen với các công cụ LLM như LangChain, LLamaIndex, cơ sở dữ liệu vectơ.\n• Có kỹ năng nghiên cứu\n• Thành thạo tiếng Anh là một lợi thế\n• Có kinh nghiệm phát triển backend với Python là một lợi thế.\n\nIII. Quyền lợi chung\n• Fix 13 tháng lương\n• Thưởng performance 2 lần/năm vào tháng 6 và tháng 12\n• Review lương 2 lần/năm vào tháng 4 và tháng 10\n• Beauty care: 200.000 VND/người/tháng cho nhân viên nữ\n• Quỹ đào tạo 3.000.000 VND/người/năm\n• Thưởng chứng chỉ tiếng Nhật và các loại chứng chỉ khác theo quy định (nếu có)\n• Bảo hiểm sức khỏe PVI cho nhân viên từ 1 năm thâm niên\n• 12 ngày phép năm, BHXH/BHYT/BHTN đầy đủ theo quy định của Luật lao động\n• Nghỉ lễ Tết theo quy định Nhà nước và kèm theo thưởng cho các ngày lễ lớn trong năm: 30/4, 1/5, 2/9, Tết,…\n• Thời gian làm việc: Thứ 2 đến thứ 6 từ 8h-17h30 (nghỉ thứ 7, chủ nhật), thời gian chấm công (check in) linh hoạt từ 7h30 -8h30\n• Địa điểm làm việc: Tầng 2 và Tầng 21, tòa Central Point, 219 Trung Kính, Yên Hòa, Cầu Giấy, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1680, 956, 2, 'Android NDK Developer - UAE (Onsite) - $60K USD/Year', 'We are seeking a skilled and experienced Native Android Developer to design, develop, and optimize native modules for our iBanking application using C/C++ with the Android NDK. You will be responsible for building native libraries (.so) for integration with our iBanking Android applications (Java/Kotlin) and working closely with the mobile team to integrate the native SDK with our main iBanking application.\n\nKey Responsibilities:\n\n- Design, develop, and optimize native modules for our iBanking application using C/C++ with the Android NDK.\n- Build native libraries (.so) for integration with our iBanking Android applications (Java/Kotlin).\n- Write native code that can be built directly on rooted Android devices (using clang, gcc, or NDK standalone toolchain) for iBanking-related functionalities.\n- Debug, trace, and hook native libraries (e.g., OpenCV, FFmpeg, TensorFlow Lite, CameraX) within the iBanking context.\n- Work with camera functionality, image processing, hardware interfaces, and low-level drivers, potentially for iBanking security features or enhanced user experience.\n- Collaborate closely with the mobile team to integrate the native SDK with the main iBanking application.\n\nRequirements:\n\n- Experience with APK decompilation, especially for analyzing iBanking applications.\n- Strong understanding of Android Syscalls (user-space/kernel-space gateway).\n- Proficiency in C/C++, including memory layout, pointers, and structs.\n- Experience with Android NDK, CMake, ndk-build, and ABI filters.\n- Ability to build .so files for various architectures (arm64-v8a, armeabi-v7a, x86).\n- Experience with cross-compiling third-party libraries (e.g., OpenCV, OpenSSL, FFmpeg).\n- Proficiency in JNI handling (JNIEnv*, jobject, jstring, CallObjectMethod, FindClass, etc.).\n- Ability to write and debug C++ directly on rooted Android devices (using adb, gcc, g++, clang, make).\n- Familiarity with security considerations in iBanking applications is a plus.\n\nBenefits:\n\n- Flights: 🛫\n  - Onboarding flight ticket provided.\n  - Flight ticket to visit home country provided every 6 months.\n- Accommodation: Private apartment provided.\n- Living Expenses: 🛌 Substantial support covering approximately 80% of living costs, including food and transportation.\n- Visa & Insurance:\n  - 1-year working visa provided.\n  - Health insurance provided in accordance with labor law.\n- International Environment: Work in a diverse environment with colleagues from up to 15 different nationalities.\n\nRecruitment Process: 📝\n- HR Interview 📞\n- Technical Interview 💻\n- Background Check 🕵️‍♀️\n- Offer 💼', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1681, 957, 2, 'Mobile Engineer', 'The Mobile Developer is an essential role in Tiger Tribe with a focus on developing highly functional, fast and beautiful frontend code for our Digital Products across the entire value chain at HEINEKEN. Scalable development is key to the success of Tiger Tribe, allowing our Digital Products to be deployed all over the HEINEKEN world. Your job will be to build key front-end capabilities, work closely with designers and back-end developers, and support a mobile-first approach to digital product development.\nIn collaborating within a dynamic and growing team based in Vietnam, the Mobile Developer contributes directly to the success of the Tiger Tribe and will be directly involved in working with end users, making changes directly in collaboration with designers, users, and business Product Owners. The Mobile Developer will help to build a global community focused on Product Development and Design best practices in HEINEKEN\n\nJOB DESCRIPTION\n• Work with Global & Regional Product Owners to develop scalable, world class Digital Products loved by our customers, consumers & colleagues.\n• Drive and support the discovery of innovation opportunities across the entire HEINEKEN value chain.\n• Support in Scrum activities within the Development Team.\n• Represent Tiger Tribe on the Global stage within HEINEKEN and the industry as a thought leader for Tech Innovation.\n• Collaborate closely with Designers and Front-End Developers to improve front-end development principles for mobile applications and ensure that development teams are meeting standards.\n• Support user testing in product development, aligning closely with UX/UI design team members and specialists.\n• Support common development patterns and practices in development teams and build up a global repository of shared components.\n• Follow the branching strategy the development teams use to ensure optimal source code management.\n• Directly involved in the 3rd-level support of Digital Products developed by Tiger Tribe.\n• Work with testing and quality team members to ensure standards and best practices are introduced.\n• Contribute to rational design decisions from business and technical perspectives and clearly communicate recommendations.\n• Drive the design and development practices for modern web APIs built on Microsoft stack technologies in line with global strategy.\n\nJOB REQUIREMENT\n• At least 02 + years’ experience in software development projects\n• Technical expertise in mobile development, specifically working with React Native front-end.\n• Good understanding and experience of Agile development practices and ways of working.\n• Possess solid CSS (SASS), HTML5 skills, and pure JavaScript coding.\n• Experience in building high-performance mobile apps with high user loads/concurrency\n• Experience in publishing mobile apps on the App Store and CH Play\n• Good knowledge of building testable software, abstraction layers, and mock objects.\n• Good communication skills\n• Familiar with Toolchain activities related to DevOps and Mobile Application deployment.\n• Strong background in customer-focused technology business.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1682, 297, 2, 'Fullstack Developer (Python, ReactJS)', 'We are looking for a Fullstack Web Developer with a strong emphasis on backend development using Python and hands-on experience in AI/LLM integration. This role is ideal for someone passionate about building scalable, high-performance web systems, with deep expertise in API design, cloud infrastructure, database architecture, and modern security practices. While frontend experience with ReactJS (or similar frameworks) is required, the focus of this role is on backend engineering and delivering solutions powered by AI technologies.\n\nLocation: Ho Chi Minh, Da Nang, Hanoi\n\nWhat You\'ll Be Doing\n\n- Working on Web and Mobile products for a diverse range of clients and industries\n- Working and pair programming with other developers to build applications with Python and ReactJS\n- Designing & implementing back-end API using Python\n- Working with the Product Owner to convert business requirements into technical designs\n- Cooperating with the UI Designer to implement modern minimalist designs into production\n- Applying proven technologies and best practices to level up your technical skills: NestJS, Redux\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment\n\nRequirements\n\nMust have\n\n- 5+ years of experience in backend development using Python\n- 3+ years of experience in frontend development using ReactJS or similar frameworks (Vue, Svelte, Angular)\n- Proven expertise in designing and implementing RESTful APIs, scalable web architecture, and deploying to cloud platforms (AWS, GCP, or Azure)\n- Hands-on experience with Python for backend development; experience integrating AI/ML solutions into web applications is a strong plus\n- Strong working knowledge of relational databases and NoSQL (e.g., MySQL, PostgreSQL, SQL Server, MongoDB ...)\n- Familiarity with Extreme Programming (XP) practices such as Test-Driven Development (TDD), Continuous Integration (CI), and code refactoring\n- Familiar with event-driven tech and message brokers (Kafka, RabbitMQ...)\n- Experienced with micro services and data-intensive applications\n- Experience working within Agile/Scrum teams\n- Excellent English communication skills, both written and verbal\n\nNice to have\n\n- Experience with NodeJS and Golang \n- Experience with serverless architecture, e.g., AWS Lambda, GCP Cloud Function, etc\n- Experience with data security, performance, and scalability\n- Experience integrating LLMs (e.g., OpenAI, Hugging Face) into production applications\n\nBenefits\n\n- Three days remote every week and four full remote weeks per year\n- Gold level Health Insurance coverage from Bao Viet Insurance, a yearly complete Health Check and social insurance\n- All office benefits and full salary during probation\n- Flexible working time starting anytime up to 10 AM working Monday - Friday with no overtime and a long lunch break\n- Allowance for everything: meals, parking, petrol, along with unlimited snacks and nice coffee every day\n- Choose from a brand-new Mac or PC device\n- Salary review twice a year with opportunities for promotions and spot awards\n- 12 days annual leave per year, with all days not taken paid out in cash, plus 2 sick leave days. \n- Yearly Training Budget up to 5 million VND per staff. On top of that, Professional coaching program, buddy system, tech talks, agile sessions, and 1on1 private English classes are available\n- Yearly company trip, monthly activities, and other Celebrations for special days in the year, such as Women\'s Day, YEP, and Christmas\n- Employee-led clubs within the company; games teams, sports teams, etc\n- Modern open-space office with comfortable workspace, a PS4 games room, and chill-out areas.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1683, 496, 2, 'Senior Front-end Developer (TypeScript, ReactJS, English)', 'Job Description\n\n- Frontend development: analyze requirements and implement responsive and interactive web applications using React and modern frontend technologies (e.g., Redux, Webpack, TypeScript).\n- Collaboration and Agile practices: collaborate with other developers to integrate applications with other systems. Participate in Agile ceremonies (sprints, stand-ups) and contribute to project planning and execution.\n- Code quality and best practices: write clean and maintainable code following engineering best practices (unit testing, source control, continuous integration, design patterns, etc.). Conduct code reviews and provide feedback to peers.\n- Performance optimization: optimize web application performance (e.g., code splitting, lazy loading, caching). Conduct performance testing and tuning to ensure fast load times and smooth interactions.\n- Cross-functional collaboration: collaborate with developers, testers, marketing, product management, and customers to create new solutions, facilitate feedback, and achieve design decisions.\n- Effort estimation: estimate the level of effort during sprint planning, contribute to the technical roadmap and continuous improvement.\n- Leadership: assist other team members with design challenges and coding issues; and evaluate their performance.\n\nDesired Skills And Experience\n\n- 3+ years\' experience in front-end development and design patterns.\n- Expert knowledge of React, Redux, TypeScript, JavaScript (ES6+), HTML5, and CSS3. Experience with CSS pre-processors (Sass, Less, Stylus) and post-processors (PostCSS).\n- Hands-on skills in caching, optimizing and securing front-end applications.\n- Familiar with task runners and the build process: Webpack / Gulp.\n- Testing practices: experience with BDD and TDD.\n- Experience with large SaaS applications (preferably decoupling monoliths) and microservice architecture.\n- Familiar with source control management: Git\n- Good communication in English.\n- Problem-solving skills.\n- Communication and collaboration skills: able to work independently and in a team environment.\n\nNice-to-have skills:\n\n- Experience in back-end development (preferably with Laravel/Symfony frameworks).\n- Exposure to working with JSON.\n- OpenAPI, and Swagger.\n- Exposure to DevOps practices and AWS landscape.\n- Exposure to one or more of Solr, Redis, or Elasticsearch.\n\nWhy Ekino?\n\n- High-ownership working environment: You will take full responsibility and control of your missions contributing to the team\'s success\n- Continuous skill improvement with new technologies, challenging projects, on-the-job coaching, and training programs\n- Annual performance review & bonus: recognize your efforts and identify development/ improvement needs\n- Clear career path: define your career development with long-term vision\n- Be secured in your mind with employee’s care: private healthcare insurance package, medical check-up, support allowance...\n- Great-place-to-work activities (company trip, sport clubs...): enhance teamwork spirit and facilitate your work-life harmony \n\nThank you for your time and enthusiasm in our career opportunities.\n\nPlease kindly note that shortlisted candidates will be contacted within 3 weeks of application. Alternatively, we will reach out to you when another suitable chance arises in the future.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 11, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1684, 958, 2, 'Senior Java Software Engineer', 'ABOUT ONE MOUNT\nOne Mount is Vietnam’s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam’s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nOne Mount Real Estate (OMRE) is a property technology company that provides a comprehensive platform to help customers experience a simple and seamless home buying and selling journey. OMRE is the first company in Vietnam capable of integrating the entire real estate transaction process on a single platform, from online to in-person. In addition, OMRE owns the first home valuation product in Vietnam. Don\'t miss the opportunity to become a member in the PropTech field at One Mount Real Estate - A member company of One Mount ecosystem, a strategic partner of the leading bank in Vietnam Techcombank and the investor owns the most sought-after luxury apartments in the market, Masterise Home, Vinhomes.\n\nMAIN RESPONSIBILITIES\nWe are seeking highly skilled Senior Java Developers to enhance our product team. This presents an exceptional opportunity to be part of a prominent and innovative Vietnamese startup, One Mount Group, and contribute to the development of our cobroker platforms.\n- Writing clean & high-quality code\n- Maintain & improve running- functionality as well as design and develop new system, new feature if needed\n- Deliver end-to-end, including unit test, integration test and deployment to PROD\n- Participate in code reviews & control coding quality standards\n\nREQUIRED EXPERIENCE AND SKILLS\n- Minimum 5 years of hands-on development experience in Java (Spring Boot framework)\n- Good understanding of Data Structures and Algorithms\n- Expertise in SQL/ NoSQL Databases (MySQL, PostgreSQL, MongoDB)\n- Experience with RESTful APIs, Microservices\n- Familiarity with Redis, Kafka\n- Experience in high-performance, low-latency systems, handling large-scale data processing and real-time transactions\n- Experience with Docker/Kubernetes and Cloud Infrastructure is a plus\n- Experience with Agile or Scrum software development methodologies\n- Prior experience within the PropTech sector is highly desirable.\n\nBENEFITS AND PERKS\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check\n- Laptop, screen and other needed facilities/accounts/tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O’Reilly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n- Grow your career with opportunities across the dynamic ecosystem of Techcombank & Masterise Group.\n- Access special loan offers with competitive interest rates and flexible grace period options tailored to your financial needs.\n\nWorking Environment\n- Open & collaborative working space fosters both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms.\n- Personal lockers with QR code access.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1685, 910, 2, 'Embedded Systems Co-Founders Wanted | Innovators in IoT & Edge Computing', '🌟 About Antler:\nWe are a global early-stage investment firm that invests in startups from day zero. We provide funding, mentorship, and a global network to help you build and scale your startup. With Antler, you’ll have access to the resources you need to turn your vision into reality—whether you\'re still ideating or already started building.\n\n👩‍💼 Who are we looking for?\nNote: This ad is not for a job, but rather for the opportunity to find your co-founder and build your own VC-backed startup through a 10-week program with Antler.\n\n- Engineers with expertise in embedded systems, IoT, and real-time computing.\n- Entrepreneurs who have built low-latency, energy-efficient solutions for smart devices and industrial automation.\n- Visionaries who understand the complexities of hardware-software integration and can optimize for performance and scalability.\n- Leaders who can push the boundaries of edge AI, connectivity, and security in IoT applications.\n- Self-starters driven to launch and grow a world-class embedded systems company.\n\n📋 Details of the program:\n- The program runs for an initial 10 weeks, full-time in Ho Chi Minh City (Vietnam) and starting in 21 July 2025, where you are required to ideate and find your co-founder(s) from the cohort of 60-70 founders.\n- After two months you will present your team and business idea to the Antler Investment Committee. If accepted, you will receive a pre-seed investment of $120K USD for 12% equity, non-negotiable.\n- If you get an investment, you will continue to be part of the program for another 3 months during which Antler will work closely with you to accelerate your growth. At the end of this period, Antler arranges a demo day where we invite VCs, institutional investors, and local angel investors to help you connect with investors and raise your seed round.\n\nFor more details on what to expect 👉 https://www.linkedin.com/smart-links/AQGwMqMCzPe68Q\n\nBenefits:\n- 💵 Potential investment at the pre-seed stage\n- 🤝 Help finding your co-founder(s)\n- 👨‍🏫 Personalized coaching sessions with business experts\n- 🛫 Relocation grant of $2,000 if you\'re relocating from overseas to HCMC, Vietnam\n- 🏬 Shared office space at a premium co-working space with access to various amenities\n- 🌍 Access to a global network of start-up advisors and experts in their field\n\nSome examples of successful companies that were built as a result of Antler’s program, received pre-seed investment from Antler, and gone on to raise substantial investment are:\n- Xailient - the World’s fastest Computer Vision AI\n- BUYO - Pioneering bioplastics and material tech\n- SKYQRAFT - Affordable and safe powerline inspections with drones and AI\n- Airalo - The world’s first eSIM subscription and top-up store\n- homebase - Making home ownership accessible\n- Reebelo - Circular economy for e-devices\n\nReady to help shape the future of the world? Apply now to Antler and together we will build something truly amazing ✨', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1686, 703, 2, 'Documentation Business Analyst (AI-Assisted Knowledge Engineer)', 'About Kegmil\n\nKegmil is revolutionizing the way mission-critical assets are repaired and maintained – by transforming complex systems of people and processes into streamlined, intelligent operations. Our mission is to empower millions of deskless field service professionals across Asia’s asset-centric industries with superior technology to elevate service excellence, operational insight, and profitable growth. Our cloud-based, mobile-first, and AI-powered platform automates and optimizes every aspect of field service from job scheduling and dispatch to execution and reporting.\n\nKegmil is trusted by leading organizations across mission-critical sectors – including elevator, fire protection, data center, medical equipment, and aerospace – to build the next-generation digital backbone that unifies FSM, modular ERP, and AI agents into one seamless platform for simpler, smarter, field service.\n\nWe are a curious and collaborative team that finds purpose in solving real problems for our customers. We learn and grow together in a high-trust, inclusive culture – where ideas are heard, ownership is encouraged, and customer success is everyone’s priority.\n\nLocation: Remote - HCM\n\nDepartment: Product & Engineering\n\nReports to: VP of Product\n\nWe are looking for a Documentation Business Analyst who combines strong system thinking, business rule understanding, and AI-assisted documentation techniques to build and maintain living system knowledge across our FSM SaaS platform.\n\nThis role works at the intersection of Product, Engineering, QA, and Customer Support to ensure that complex system logic, rule engines, integration flows, and configurations are fully captured and easily referenceable for both internal and client-facing users.\n\nKey Responsibilities\n\n• Collaborate with PO, Developers, QA, and CS to extract:\n  o Business rules\n  o System configurations\n  o Rule engine logic (YAML/JSON)\n  o Integration mapping (ERP, SAP, external APIs)\n\n• Use structured templates and AI tooling to build documentation:\n  o Rule Specifications\n  o API Reference\n  o Configuration Matrix\n  o Workflow Diagrams (Mermaid.js / PlantUML)\n  o Client Help Articles\n\n• Proactively identify knowledge gaps and drive clarification sessions.\n• Maintain version-controlled documentation repository (Confluence + Git-based configs).\n• Use AI tools to assist in drafting, version comparison, consistency checking, and automated doc generation.\n• Ensure documentation remains synchronized with system releases, tenant customizations, and ongoing product evolution.\n\nRequired Qualifications\n\n• 2+ years experience as Business Analyst / System Analyst / Product Analyst in SaaS, ERP, or FSM domain.\n• Strong system thinking and ability to map complex workflows and conditional logic.\n• Comfortable reading technical configs (YAML, JSON, APIs, rule engines).\n• Experience interviewing cross-functional teams to extract undocumented logic.\n• Solid writing skills to translate technical logic into clear documentation.\n• Familiar with AI tools (ChatGPT, Claude, etc.) for writing assistance.\n• Familiar with documentation platforms (Confluence, Notion, Swagger, Git, Mermaid.js).\n\nPreferred Qualifications\n\n• Exposure to ERP systems (SAP, MS Dynamics, Frappe, etc.).\n• Experience with rule engines or configuration-driven platforms.\n• Experience in knowledge management or knowledge ops design.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1687, 702, 2, 'Senior Frontend Developer - Wallet', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nBinance platform provides a large range of different cryptocurrency services to retail users, high net vault individuals, institutions, and enterprise customers. As a platform frontend developer, you must be active in designing and building efficient web applications. You should be self-motivated, and be able to proactively push from the start to finish of each feature.\n\nResponsibilities:\n\n• Join the full life cycle of building crypto wallet platform products including requirement gathering, technical design, coding, testing, deployment, documentation, and support\n• Partner with the product manager, DevOps, QA, and teammates to get things done\n• Implement new user-facing features in our products\n• Write client-side code to create super-fast, easy-to-use, web-based applications which include website for both desktop and mobile browsers, and hybrid in-app pages\n• Optimize web applications to maximize speed and scale\n• Build libraries and frameworks that support complex web applications, speedup development efficiency, and improve code quality\n\nRequirements:\n\n• Has a Bachelor’s/Master’s degree in computer science, engineering or equivalent industry experience\n• Minimum 5 years developing production JavaScript/Typescript code and strong knowledge of React.JS\n• Understanding of state-management patterns such as Redux, Flux or similar\n• Proven track record of delivering projects with high-quality UI\n• Experience in developing responsive web sites for diverse clients from high powered desktop computers to small footprint mobile devices\n• Experience with modern front-end technologies (styled system, web-pack, etc)\n\nWhy Binance\n\n• Shape the future with the world’s leading blockchain ecosystem\n• Collaborate with world-class talent in a user-centric global organization with a flat structure\n• Tackle unique, fast-paced projects with autonomy in an innovative environment\n• Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n• Competitive salary and company benefits\n• Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1688, 370, 2, 'Software Engineer', 'FORTNA partners with the world’s leading brands to transform omnichannel and parcel distribution operations. Known world-wide for enabling companies to keep pace with digital disruption and growth objectives, we design and deliver solutions, powered by intelligent software, to optimize fast, accurate and cost-effective order fulfillment and last mile delivery. Our people, innovative approach and proprietary algorithms and tools ensure optimal operations design and material and information flow. We deliver exceptional value every day to our customers with comprehensive services and products including network strategy, distribution center operational design and implementation, material handling automated equipment, robotics and a comprehensive suite of lifecycle services.\n\nLocation: Hanoi, Vietnam\n\nPRIMARY RESPONSIBILITIES INCLUDE\nDesigning and developing high quality distributed applications of FORTNA Warehouse Execution System (WES).\nWorking with the Portfolio and Project Management Office (PPMO) by participating in project planning activities throughout the lifetime of the project.\nParticipating in Software Design Reviews with Clients, Software Project Management, Software Services and Senior Software Engineers.\nAssisting Software QA and Infrastructure Engineers in Qualifying, Deploying and Packaging WES applications and libraries, development of component and project test plans and test automation.\nMaintaining high-quality project and software design documentation.\nTraveling to Client sites to assist the Software Services Implementation Engineers in qualifying the WES/WCS installation on-site both domestically and internationally.\nHave open-minded, ready to learn and share new techniques and technologies. We’re welcome to all of your ideas and contribution to improve productivity. \n\nREQUIRED QUALIFICATIONS\nBachelor’s degree in computer science or related field.\nAt least 2 years of experience in Java/Java Core, enterprise application development, concurrent programming.\nProficiency English\nStrong knowledge of object-orientated analysis and design (OOAD).\nHave experience with at least 1 RDBMS (Oracle/Postgres/MySQL…), Message Broker, ESB, RESTful API development, Microservices.\nAble to work with Git; Docker and one of following build tools: Maven/Gradle/sbt.\nDevOps practices: CI/CD, containerization (Docker), automation (Jenkins or similar), and infrastructure-as-code (Terraform, Ansible)\nExperience with other open-source operating systems and development tools.\nExcellent oral and written communication skills and the ability to articulate to project members and stakeholders; must be a team player who works well with technical and non-technical resource.\nStrong interpersonal, organizational, time management and problem-solving skill.\n\nBeing a part of FORTNA, you are offered:\nCompetitive salary with 100% official salary during the probation period; 13th-month salary\nBao Viet Premium health-care insurance for employees and 2 dependents\nSponsored training and self-development opportunities (Java, PMP, CSM...)\n10% paid working time per week for personal development (attending soft skill courses, reading books, working on side projects, self-teaching any new IT-related concepts)\nModern facilities with Laptop Dell Precision 7670 chip i9-12950HX, Ram 64GB, SSD 512GB, RTX A2000 + 2 monitor Dell Ultrasharp U2422HE\nSupportive, international, dynamic working environment and talented, culturally diverse teams\nA large pantry full of snack, drink, and seasonal fresh fruit.\n\nTake the deal and let ‘s explore many more benefits!\n\nNOTE: We appreciate all applications; however, only shortlisted candidates will be contacted.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1689, 808, 2, 'JUNIOR AI ENGINEER', 'Your Responsibilities Will Include\n\n• Participate in the development of AI, NLP, and Big Data technologies for company products such as chatbots, search engines, and data analysis systems.\n• Collect, clean, and prepare large-scale datasets for training AI models.\n• Research and apply machine learning, deep learning, and Big Data technologies to build and enhance AI solutions.\n• Evaluate model performance and propose optimization solutions.\n• Support other team members in projects and products implementation, particularly in integrating AI with Big Data technologies.\n\nJob Requirements\nBachelor\'s degree in Computer Science, Information Technology, or a related field.\n• Solid understanding of probability and statistics, discrete mathematics, and linear algebra.\n• Knowledge of algorithms, data structures.\n• Experience with at least one framework or library (e.g., TensorFlow, PyTorch) and one programming language (Python and C# preferred).\n• Knowledge of Big Data processing tools like Hadoop and Spark, including concepts such as MapReduce and data parallelism.\n• Strong learning attitude, enthusiasm for research and a passion for exploring new AI and Big Data technologies.\n• Good communication skills and ability to work effectively in a team.\n• Good English communication.\n\nPreferred\n• Experience participating in AI, NLP, Big Data related projects.\n• Experience working with distributed databases (NoSQL) and Big Data storage solutions.\n\nWORK LOCATION\n4F Artemis, No 3 Le Trong Tan, Thanh Xuan, Hanoi\n\nBenefits\n• 5-day workweek with weekends off\n• Dynamic, professional environment with career growth opportunities\n• Social, medical, and unemployment insurance based on actual salary\n• Performance and salary review twice a year\n• Quarterly bonus opportunities based on performance\n• Potential for international onsite assignments\n• Regular team-building events and internal activities (weekly happy hour, quarterly team building events, Lunar New Year parties, etc.)\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1690, 938, 2, 'QC Engineer', 'The Opportunity\n\nOur client, ranked among Australia’s top 10 Best Workplaces, is a powerhouse in personal injury claims management, driving innovation across workers’ compensation, life insurance, and accident sectors. With over 110 years of legacy and a $140M investment in workplace safety, they’ve cultivated a cutting-edge, inclusive culture where your work directly transforms lives.\n\nAs a QC Engineer, you’ll be part of a dynamic team ensuring peak performance and flawless delivery for a large-scale system. Harness your testing expertise and analytical thinking to make a tangible difference every day. This role offers a hybrid working arrangement.\n\nKey Responsibilities\n\n- Design and execute Manual/Automation test cases with minimal support/review from the superiors.\n- Analyze clients\' requirements and expectations.\n- Solid experience in designing and implementing test cases.\n- Hands-on with the manual or automated testing tool (Selenium), and code implementation.\n- Team collaboration and communication.\n\nSkills, Experience & Qualifications\n\n- At least 3+ years in a Testing position.\n- Good experience in API Testing and/or Database Testing.\n- Experienced in Selenium, Appium and C# programming language is preferred.\n- Knowledge of testing management tools using JIRA.\n- Good English communication, and critical thinking skills with the ability to learn quickly.\n- Bachelor\'s degree in Information Technology, Computer Science, or related fields.\n\nASW Offers\n\n- We are experts in International Talent Partnering. This means that you will be a trusted member of the ASW family, and get access to our great benefits, plus you also get to work directly with one of clients.\n- In our unique English-speaking environment, you can practice and enhance your English with peers and international client teams based in either Australia, UK, US or NZ.\n- Get global access to Learning & Development programs.\n- Great work-life balance.\n- Competitive remuneration.\n- Excellent medical benefits.\n- Great Paid Leave entitlements.\n- Company parties/events, future travel opportunities, and other exciting activities.\n- Ongoing career opportunities.\n- To find out what our people say about working at ASW, visit: https://aswhiteglobal.com/careers/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1691, 689, 2, 'Sr. React Developer - Remote (Select Countries in Asia)', 'Remote Opportunity - must be based in Thailand, Indonesia, Vietnam, Philippines or Malaysia.\n\n$5,000 USD per month.\n\nFull time - permanent placement opportunity\n\nAbout the Role:\n\nWe are seeking a talented and highly motivated Senior React Developer to join our dynamic team. In this role, you will be responsible for developing and maintaining React-based applications that prioritize performance, scalability, and user experience. You’ll collaborate with backend developers to integrate APIs and services while ensuring that UI/UX designs are technically feasible. The ideal candidate has a strong background in JavaScript, React, and UI component libraries, and a passion for creating seamless and efficient web applications.\n\nKey Responsibilities:\n\n- Develop and maintain React-based applications with a focus on performance, scalability, and user experience.\n- Implement UI components and widgets using Kendo UI (or similar libraries) to create feature-rich, visually appealing interfaces.\n- Leverage Nx for efficient monorepo management and to improve development workflows.\n- Write clean, maintainable, and efficient code, adhering to best practices and coding standards.\n- Collaborate with backend developers to integrate APIs and services into the frontend.\n- Ensure the technical feasibility of UI/UX designs and optimize web applications for speed and scalability.\n\nRequired Skills and Qualifications:\n\n- Strong proficiency in JavaScript​: Deep understanding of JavaScript fundamentals\n- Solid experience with React: Expertise in developing applications with React, including knowledge of functional components, hooks, context API, and state management libraries (e.g., Redux, Zustand, or MobX).\n- Experience with RxJS: Comfortable working with reactive programming patterns, including creating observables, operators (e.g., map, mergeMap, switchMap), and understanding how they complement React workflows.\n- UI Component Libraries: Familiarity with Kendo UI or similar libraries (e.g., Material UI, Ant Design, Chakra UI) and the ability to integrate pre-built components into React applications for feature-rich UIs.\n- Performance Optimization: Ability to optimize application performance and ensure cross-browser compatibility and responsiveness.\n\nUI Techstack:\n\n- kVite with SPA mode - https://vite.dev\n- React + TypeScript - https://react.dev\n- TanStack Router - https://tanstack.com/router/latest\n- TanStack Query - https://tanstack.com/query/latest\n- TanStack Table (due to amount of tables to be used) - https://tanstack.com/table/latest\n- React Hook Form - https://www.react-hook-form.com\n- Zod - https://zod.dev\n- Radix-UI/Themes or ShadCn for components.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1692, 959, 2, 'Senior API Developer', 'Company Description\nLiftango is a global company that powers on-demand shared transport systems, helping organizations plan, launch, and scale their shared mobility programs. The company is dedicated to reducing CO2 emissions and creating sustainable connections through a unified platform. Liftango works with cities, transit agencies, private bus operators, corporates, and property developers to optimize transport systems and combat climate change.\n\nRole Description\nThis is a full-time on-site role for a Senior API Developer located in Hanoi. The Senior API Developer will be responsible for designing, developing, and maintaining APIs, integrating complex systems, ensuring data security, and collaborating with cross-functional teams to deliver high-quality solutions.\n\nKey Responsibilities:\n\n- Design, develop, and maintain robust, scalable, and secure APIs using TypeScript, with a strong preference for NestJS.\n- Define and document clear and comprehensive API specifications using tools such as OpenAPI (Swagger). Implement and champion API security best practices throughout the development lifecycle.\n- Focus on optimizing APIs for high performance, scalability, and reliability to meet the demands of various consumers.\n- Create and maintain thorough, up-to-date technical documentation for all developed APIs.\n- Develop and manage comprehensive automated testing suites to ensure API quality and stability.\n- Collaborate effectively with internal development teams and, where necessary, external third-party stakeholders to gather requirements, define integration points, and ensure seamless functionality.\n- Troubleshoot and debug applications, ensuring optimal performance and quick resolution of issues.\n- Stay current with emerging API technologies and industry best practices.\n\nRequired Qualifications:\n\n- Proven experience (e.g., 5+ years) in a Senior API Developer, Backend Developer, or a similar role, with a track record of designing and developing public or semi-public facing APIs.\n- Strong proficiency in TypeScript.\n- In-depth knowledge of API design principles, RESTful conventions, and architectural best practices.\n- Solid experience with version control systems, particularly Git, and collaborative development workflows.\n- Excellent problem-solving, analytical, and debugging skills, with a proactive approach to identifying and resolving issues.\n- Ability to work independently and manage priorities effectively in a fully remote environment.\n- Strong English communication and interpersonal skills, with the ability to articulate complex technical concepts clearly to both technical and non-technical audiences.\n- Experience in an environment where getting up to speed quickly with minimal oversight is expected.\n\nPreferred Qualifications (Nice to Have):\n\n- Significant professional experience with the NestJS framework.\n- Experience with various database technologies, including SQL (e.g., PostgreSQL, MySQL) and/or NoSQL (e.g., MongoDB) databases.\n- Familiarity with microservices architecture and distributed systems.\n- Knowledge of containerization technologies (e.g., Docker) and orchestration tools (e.g., Kubernetes). Understanding of CI/CD principles, pipelines, and associated tools.\n- Experience working effectively in an Agile development environment.\n- While deep expertise isn\'t required, a general understanding of deploying applications on cloud platforms like AWS would be beneficial.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1693, 676, 2, 'Mobile Application Developer', 'Overview:\nThe goal of the Mobile Service is to design, develop and maintain Client of mobile and microservice applications.\nAs part of this role you will be expected to provide technical leadership across all aspects of the software delivery life cycle and all applications that the mobile service supports.\nThe successful candidate will be a senior engineer with a wealth of Mobile app development experience including the ability to provide coaching and mentoring for junior developer sand will have an operations mindset to enable the buildout of robust, secure and maintainable applications.\n\nResponsibilities:\n- Management of conflicting priorities in a rapidly changing environment\n- Working with business analysts, and user experience designers to ensure requirements are clear whilst offering technical input into the requirements process\n- Working with Principal Engineers on the design for any feature or application that the mobile service supports\n- Active participation in all aspects of the software delivery life cycle and associated agile activities that the team undertake\n- Coaching and mentoring of other engineers to uplift service capability and cross-skill individuals over time\n- Continuous review, identification and improvement of engineering processes, practices and tooling\n- Perform code reviews and provide timely and constructive feedback\n- Participate in feature estimation from early ideation to delivery phases\n- Technical design and coding of all mobile applications and microservices\n- Working with a quality mindset to ensure applications are robust and appropriate code coverage is maintained and improved over time\n- Continuous technical uplift and knowledge sharing with others including presentations to internal colleagues and external meet-ups/conferences\n\nRequirements:\n- Experience across the full software delivery life cycle (planning, analysis, design, implementation, testing, deployment, and maintenance)\n- Agile software development and management methods and ability to excel within a fast-paced environment\n- A solid technical background as a Mobile engineer with Kotlin/Java or Swift/Objective-C\n- Experience working with diverse teams from development, testing, security, architecture, infrastructure to business and management\n- Experience with build management tools including continuous integration and delivery practices and tools (Gradle, Jenkins)\n- Experience with continuous test automation tooling (Perfecto, Applitools)\n- Software design and delivery with UX and accessibility front of mind\n- Experience with latest development methodologies and tooling\n- Development experience using common IDE and source systems (Android Studio, Git)\n- Writing unit and functional automation tests (Junit, Roboelectric, Espresso)\n- Release and configuration management practices including parallel development (tagging/branching strategies), managing multiple versions and third party library dependency management\n- Experience with repository artifact management (Artifactory)\n- Knowledge of code quality analysis tools (coverage, duplication, complexity, dependency analysis and standards)\n\nSoft skill:\n- Exceptionally strong written and verbal communication skills, as well as good interpersonal and organisational skills\n- Strong delivery focus with an active approach to quality\n- Working with key stakeholders and the wider mobile service team\n- Excellent analytical, troubleshooting & documentation skills\n- Able to work under pressure and self-manage tasks\n- Enthusiasm for technology and solving problems\n- Leadership qualities and skills', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1694, 880, 2, 'Freelance Software Developer (Java) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with Java\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you? \n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1695, 887, 2, 'Back End Developer (Java, Springboot, SQL)', 'LG CNS is looking for qualified Back-end developer to join the group. \n\nMission:\n1. Ensure the best possible performance, quality and responsiveness of applications on the back-end side.\n2. Stay up to date on emerging technologies.\n3. Exchange details when interviewing\n4. Manage and training members in your PART (if you were chosen as Part leader)\n\nRequirement\n[Required]\n1. Have at least 2 years of experience in JAVA (Highly preferred)\n2. Have experience developing web applications.\n3. Have Java programming experience.\n4. Developed based on Spring, Spring Boot F/W, Spring MVC...\n5. API Development (REST API)\n6. RDBMS (MySQL, PostgreSQL, Oracle) & SQL, PL/SQL\n7. Have knowledge Python language.\n8. Git, Jira, Confluence\n9. Understand and apply CI/CD\n10. Good at communicate in English at an average level (TOEIC 550 or higher)\n11. Be proactive and responsible at work.\n\n[Nice-to-have]\n1. Experience working in Kubernetes and Cloud environments (AWS, GCP)\n2. Experience in SQL optimization.\n3. Able to communicate in Korean.\n\nOpportunity\n1. Attractive salary and bonus will be discussed after going through CV & Interview\n2. Review capacity annually and adjust salary increases according to work performance.\n3. Korean language certificate bonus (TOPIK)\n4. Health care: Premium health insurance, Annual health check-up\n5. Young working environment\n6. Good career development opportunities with interesting and challenging projects.\n7. English, Korean, technical, soft skills training courses.\n8. Opportunity to learn special courses from LG CNS, new technology and security.\n9. Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n10. Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n11. Working hours: 8 hours from Monday - Friday (8:00 - 12:00 - 13:00 - 17:00)\n\nLocation\n15th Floor, Keangnam Landmark 72, Me Tri, Nam Tu Liem, Hanoi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1696, 960, 2, 'Full Stack Developer', 'As a Full-stack Developer, you will design, implement, and maintain web-based tools that help improve the efficiency of the production team. You possess practical frontend as well as backend experience. You enjoy solving problems and thrive in a transversal environment spanning the core technology teams on the project.\n\nReporting to the Associate Producer, your main and routine tasks are to:\n\n- Compile and understand IT development needs and assess their feasibility so as to best serve the development team\n- Collaborate with producers to transform user stories into features for the operation tools\n- Support the live operation functions and systems: Web-based tool creation, CI/CD, and deployment pipelines\n- Determine and correct the tools bugs identified by people from other crafts and the tools testers (and eventually the quality control team)\n- Document the work so as to transfer knowledge and enable users (from other crafts) to understand how to use the new systems and functions\n\nQualifications\n\n- Bachelor’s degree in computer science or computer engineering or equivalent\n- Minimum 5 years of experience with 4 years’ experience working in a full-stack role, developing web applications\n- Strong knowledge of HTML, CSS, DOM & REST APIs\n- Solid experience with JavaScript frameworks such as React, Vue.js, Angular\n- Solid experience with backend application development (C# .NET, Python, Node.js)\n- Experience with containerized environments (Docker, Kubernetes)\n- Experience with relational and non-relational databases (MongoDB, MySQL, ElasticSearch)\n- Familiar with modern development tools and best practices (IDEs, Git for version control, unit testing, build tools, continuous integration and deployment, monitoring)\n- Strong interpersonal and communication skills\n- Great team player\n- Proficiency in Mandarin will be a plus\n\nAdditional Information\n\nUbisoft’s 19,000 team members, working across more than 30 countries around the world, are bound by a common mission to enrich players’ lives with original and memorable gaming experiences. Their dedication and talent have brought to life many acclaimed franchises such as Assassin’s Creed, Far Cry, Watch Dogs, Just Dance, Rainbow Six, and many more to come. Ubisoft is an equal opportunity employer that believes diverse backgrounds and perspectives are key to creating worlds where both players and teams can thrive and express themselves. If you are excited about solving game-changing challenges, cutting-edge technologies, and pushing the boundaries of entertainment, we invite you to join our journey and help us create the unknown.\n\nWe are working to enrich players’ lives through unique and memorable gaming experiences and by improving the positive impacts of our games. To get there, we are creating a safer, more inclusive work environment, we are giving back to the communities where Ubisoft operates by working with local non-profit partners and by working to reduce the environmental impact of our business.\n\nUbisoft Da Nang - Where bright ideas are given a chance to shine\n\nUbisoft Da Nang is an ambitious and dynamic studio, bringing together some of the brightest international talent to create immersive worlds that serve as playgrounds for imagination, surprise, and fun.\n\nSince 2020, we’ve been uniting the best creative and engineering minds from Vietnam and beyond, with a shared goal of introducing Ubisoft’s iconic worlds to new audiences. We collaborate with highly talented teams on exciting and challenging projects displayed at an international level, whether it\'s fun and easy-to-pick mobile games or titles for consoles and PCs.\n\nWe believe in empowering our team members by fostering a collaborative, inclusive, and innovative environment. Our office, awarded Best Office Design in Vietnam by VMark 2021, reflects our commitment to creating a space that inspires creativity and promotes well-being.\n\nLocated in one of Southeast Asia\'s most effervescent tech hub, we enjoy the breathtaking views of both beaches and mountains, clean air, no traffic, and the proximity to major cities in the region.\n\nIf you\'re passionate about gaming and eager to contribute to our vision of creating the unknown, join us at Ubisoft Da Nang, where you\'ll be empowered to grow within the Ubisoft family and make your mark in the world of gaming, whether you\'re just starting your game development journey or looking to take your career to the next level!\n\nWhy it\'s great to work at Ubisoft Da Nang:\n\n- An international, professional, collaborative, modern, and creative environment\n- Attractive remuneration package\n- Performance rewards\n- Creative & endless fun projects\n- Ubisoft Connect account with access to all Ubisoft titles on PC\n- We are committed to promoting a flexible working policy, as we value in-person interaction and collaboration. Our hybrid work model includes 3 days a week in our office and the remaining 2 days working from home.\n- Premium healthcare insurance\n- UBIVERSARY for your working milestones\n- Team building, Lunar New year Celebration, Projects celebration\n- Beers and treats every Friday (yay!)\n- Staff clubs\n- Premium gym club access\n- Free in-house entertainment facilities (PS5, Nintendo Switch, Steam Deck…), coffee, tea and snack (cookies, candies…)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 다낭 다낭', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1697, 732, 2, 'Software Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nTechnologists at WorldQuant research, design, code, test and deploy projects while working collaboratively with researchers. Our environment is relaxed yet intellectually driven. We seek people who think in code and are motivated by being around like-minded people.\n\nThe Role: We are looking for exceptionally talented engineers to join our team. The team is responsible for building out a new business within WorldQuant, and this role involves software engineering on Data, Strategy, Trading, etc. You will be working with Quants very closely. Also you will have the opportunity to learn the full cycle of Quant business end to end.\n\nBuilding / improving the data layer\nBuilding the computational framework that runs our quant strategies\nWorking with Quant as pairs, provide technique support for Quants.\n\nWhat You’ll Bring\n\nTop university education. Experiences of participating ACM competitions is a plus.\nEducation degree higher then better. PhD degree is a plus.\nVery solid understanding of Data Structure and Algorithm\nCare about the conciseness and beauty of code. Already good at Python is a plus.\nExcellent communication skills (Will work with Quants closely)\n\nWhat We Offer\n\nCompetitive and attractive compensation package with clear career road-map – where you feel challenged everyday\nWe offer a strong culture of learning and development: training courses, library, speakers, share and learn events\nLearn from who sits next to you! Working in WQ you are surrounded by smart and talented people\nEmployee resources groups with strong diversity and inclusion culture\nPremium Health Insurance and Employee Assistance Program\nGenerous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\nTeam building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\nAnnual company trip and occasional global conferences – opportunity to travel and connect with our global teams\nHappy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1698, 866, 2, 'Java Developer', 'Who are we?\n\nAmaris Consulting is an independent technology consulting firm providing guidance and solutions to businesses. With more than 1,000 clients across the globe, we have been rolling out solutions in major projects for over a decade – this is made possible by an international team of 7,600 people spread across 5 continents and more than 60 countries. Our solutions focus on four different Business Lines: Information System & Digital, Telecom, Life Sciences and Engineering. We’re focused on building and nurturing a top talent community where all our team members can achieve their full potential. Amaris is your steppingstone to cross rivers of change, meet challenges and achieve all your projects with success.\n\nAt Amaris, we strive to provide our candidates with the best possible recruitment experience. We like to get to know our candidates, challenge them, and be able to give them proper feedback as quickly as possible. Here\'s what our recruitment process looks like:\n\nBrief Call: Our process typically begins with a brief virtual/phone conversation to get to know you! The objective? Learn about you, understand your motivations, and make sure we have the right job for you!\n\nInterviews (the average number of interviews is 3 - the number may vary depending on the level of seniority required for the position). During the interviews, you will meet people from our team: your line manager of course, but also other people related to your future role. We will talk in depth about you, your experience, and skills, but also about the position and what will be expected of you. Of course, you will also get to know Amaris: our culture, our roots, our teams, and your career opportunities!\n\nCase study: Depending on the position, we may ask you to take a test. This could be a role play, a technical assessment, a problem-solving scenario, etc.\n\nAs you know, every person is different and so is every role in a company. That is why we have to adapt accordingly, and the process may differ slightly at times. However, please know that we always put ourselves in the candidate\'s shoes to ensure they have the best possible experience.\n\nWe look forward to meeting you!\n\nJob Description\n\nABOUT THE JOB\n\nDevelop and maintain Java-based applications using Spring Boot and Spring MVC.\nCollaborate with cross-functional teams to design, implement, and deploy scalable solutions.\nOptimize applications for performance, reliability, and security.\nContribute to architecture decisions and system design, ensuring integration with AWS services.\nConduct code reviews and implement best practices to ensure clean and efficient code.\nDebug and resolve software defects, ensuring smooth operation and functionality.\nParticipate in all phases of the software development lifecycle, including testing and deployment.\nMentor junior developers and contribute to team knowledge sharing.\n\nAbout You\n\nBachelor\'s degree in Computer Science, Software Engineering, or other equivalent fields.\nHands-on experience in Java development, including expertise in Spring Boot and Spring MVC.\nStrong understanding of software architecture and design principles.\nKnowledge of AWS cloud services, with practical experience in integration and deployment.\nProficiency in debugging, optimization, and security best practices.\nGood English communication skills is a big plus.\nPossess excellent analytical and problem-solving skills.\nDemonstrate a strong willingness to learn and adapt to new technologies as required.\n\nWHY AMARIS?\n\nCompetitive salary and 13th-month salary.\n14+ annual leaves per year.\nPremium healthcare insurance, starting from your probation period.\nProject reviews and yearly performance appraisals.\nAnnual company trips.\nTeambuilding activities: Team lunch/dinner, events, and celebrations, sports clubs (football, yoga, badminton, etc.).\nInternational team with flexible working time + hybrid working.\nTailor-made career path.\nTechnical workshops and training courses.\nMobility: Opportunities to be on-site abroad in our offices in over 60+ countries.\n\nEqual Opportunity\n\nAmaris Consulting is proud to be an equal opportunity workplace. We are committed to promoting diversity within the workforce and creating an inclusive working environment. For this purpose, we welcome applications from all qualified candidates regardless of gender, sexual orientation, race, ethnicity, beliefs, age, marital status, disability, or other characteristics.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville et périphérie', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1699, 849, 2, 'Associate Solution Support Engineer - Business Technology Platform', 'We help the world run better \n\nAt SAP, we enable you to bring out your best. Our company culture is focused on collaboration and a shared passion to help the world run better. How? We focus every day on building the foundation for tomorrow and creating a workplace that embraces differences, values flexibility, and is aligned to our purpose-driven and future-focused work. We offer a highly collaborative, caring team environment with a strong focus on learning and development, recognition for your individual contributions, and a variety of benefit options for you to choose from.\n\nAbout SAP Labs Network And SAP Labs Vietnam\n\nSAP Labs Network is the global R&D setup where over 55,000 engineers around the world create, operate and support the most innovative enterprise solutions for SAP’s customers worldwide. SAP Labs Vietnam aims to become one of the key locations within the SAP Labs Network to support the engineering growth for SAP.\n\nWhat You Will Do\n\nAs a BTP Associate Solution Support Engineer, you will troubleshoot and solve customer issues reported through industry-leading channels within SAP Business Technology Platform (BTP). This includes engaging directly with customers, collaborating with development teams, using knowledge repositories, simulating problems, and working on customer systems to resolve complex issues. Your goal is to deliver a high-quality customer experience while developing deep technical expertise.\n\nKey Responsibilities\n- Investigate and resolve complex, real-world customer issues related to SAP BTP.\n- Deliver Core Customer Support by Solving complex customer issues in team environments (swarming) and individual-driven actions (incident solving or real-time support), in cooperation with experienced support engineers if necessary while maintaining a high level of customer satisfaction.\n- Escalate sensitive customer issues to component owner, creating an action plan and communicating it back to the customer / beneficiary.\n- Use SAP and third-party tools to diagnose issues on customer systems.\n- Create knowledge documents, tools, and processes to support our customers, and to help colleagues prevent future issues (WIKI content, Knowledge Base Articles, Guided Answers, …).\n- Participate in shift work, including weekends, as scheduled.\n- Develop product specialization in at least one product area.\n- Continuously learn and master SAP software used by industries, governments, and multinational companies.\n- Contribute to innovation projects aimed at achieving our Vision and Goals and act as a Change Leader in achieving those projects.\n\nTechnologies Supported\n- Client Server Technology \n- Security\n- Workflow / RFC / Middleware\n- Master Data Governance \n\nWhat You Bring\nEducation and Experience:\n- University degree or college diploma in Computer Science, Information Technology, Software Engineering, Business Information Systems, Engineering, Science, or Mathematics preferred (but not required). \n- 0–2 years of professional experience; new graduates are encouraged to apply.\n\nSkills And Competencies\n- Strong IT affinity and technical aptitude to troubleshoot customer issues effectively.\n- Excellent communication, collaboration, and customer service skills. Open and professional communication style.\n- High proficiency in English (spoken and written); Proficiency in Japanese is not required but would be considered a significant asset.\n- Strong analytical and problem-solving abilities.\n- Strong team player who learns and adapts quickly. Ability to thrive in a fast-paced, changing environment with a cloud-first mindset.\n- Customer-centric mindset with a passion for delivering high-quality solutions.\n\nMeet your team\nIf you’re searching for a diverse, multi-cultural team where you feel empowered, respected, and dedicated to your ideas and individual growth — you have come to the right place. Our team culture encourages and recognizes unique contributions and provides a fun, flexible, and inclusive work environment.\n\nThe new Technical Support Team at the SAP Vietnam/SAP Labs office in Ho Chi Minh City is critical to SAP\'s future success in the APAC region. We are looking for candidates who strive to make the world run better by delivering exceptional customer support and driving customer satisfaction.\n\nCareer Development and Growth\nSAP is committed to supporting your professional growth and development:\n- Career Progression: SAP provides the tools and resources to help employees grow in their careers.\n- Training: A structured development plan combining on-the-job learning and formal training ensures continuous skill development.\n- Global Exposure: Collaborate with global teams and gain exposure to diverse industries and customer environments.\n\n#SAPLabsVietnamCareers\n\nBring out your best\nSAP innovations help more than four hundred thousand customers worldwide work together more efficiently and use business insight more effectively. Originally known for leadership in enterprise resource planning (ERP) software, SAP has evolved to become a market leader in end-to-end business application software and related services for database, analytics, intelligent technologies, and experience management. As a cloud company with two hundred million users and more than one hundred thousand employees worldwide, we are purpose-driven and future-focused, with a highly collaborative team ethic and commitment to personal development. Whether connecting global industries, people, or platforms, we help ensure every challenge gets the solution it deserves. At SAP, you can bring out your best.\n\nWe win with inclusion\nSAP’s culture of inclusion, focus on health and well-being, and flexible working models help ensure that everyone – regardless of background – feels included and can run at their best. At SAP, we believe we are made stronger by the unique capabilities and qualities that each person brings to our company, and we invest in our employees to inspire confidence and help everyone realize their full potential. We ultimately believe in unleashing all talent and creating a better and more equitable world.\n\nSAP is proud to be an equal opportunity workplace and is an affirmative action employer. We are committed to the values of Equal Employment Opportunity and provide accessibility accommodations to applicants with physical and/or mental disabilities. If you are interested in applying for employment with SAP and are in need of accommodation or special assistance to navigate our website or to complete your application, please send an e-mail with your request to Recruiting Operations Team: Careers@sap.com\n\nFor SAP employees: Only permanent roles are eligible for the SAP Employee Referral Program, according to the eligibility rules set in the SAP Referral Policy. Specific conditions may apply for roles in Vocational Training.\n\nEOE AA M/F/Vet/Disability\nQualified applicants will receive consideration for employment without regard to their age, race, religion, national origin, ethnicity, age, gender (including pregnancy, childbirth, et al), sexual orientation, gender identity or expression, protected veteran status, or disability.\n\nSuccessful candidates might be required to undergo a background verification with an external vendor.\n\nRequisition ID: 424658 | Work Area: Customer Service and Support | Expected Travel: 0 - 10% | Career Status: Graduate | Employment Type: Regular Full Time | Additional Locations: .', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City i okolice', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1700, 952, 2, 'Text-to-Speech Engineer (AI Conversation Team)', 'We are seeking a TTS Engineer (Text-to-Speech) to support the development and deployment of speech technologies. This junior-level role is ideal for someone eager to gain hands-on experience in AI product development, data engineering, and speech processing. You will begin by working on data-related tasks and progressively take on more responsibility in AI model training and evaluation.\n\nAbout FPT Smart Cloud\n\nFPT Smart Cloud (FCI) – a member of FPT Corporation, pioneers AI & Cloud solutions in Vietnam. FCI was founded with the mission to generating an immense leap in productivity and agility in business operations.\n\nFPT Smart Cloud aims at leading the industry by focusing on building a firm technological foundation, developing diversified ecosystem products, and reaching global connectivity.\n\n• Customized to specific needs: Providing cloud-based products and solutions customized to each industry.\n• All-in-one Platform: Consolidating FPT Smart Cloud technology and diverse business solutions all in one platform. AI & Cloud services are a Unify eco-system.\n• Local market leadership: Outstanding Cloud and AI technology infrastructure and platform to help local businesses grow their products and services online.\n• Deliver the future: Help customers achieve business outcomes faster by integrating world-class processes and technology.\n\nKey Responsibilities\n\n• Coordinate and oversee speech data collection, including both manual recordings and automated online data acquisition.\n• Perform data processing tasks such as cleaning, segmentation, and automatic labeling.\n• Conduct quality checks and validation of speech datasets.\n• Gradually develop automated pipelines and tools for managing and processing speech data efficiently.\n• Support training and evaluation of TTS models as experience grows.\n• Collaborate with cross-functional AI teams to improve system performance and scalability.\n\nRequirements\n\n• Solid Python programming skills.\n• Comfortable with Linux development environments, including command-line tools, bash scripting, and Docker.\n• Strong organization and communication skills.\n• Intermediate English proficiency (reading and technical communication).\n\nPreferred Qualifications (Nice To Have)\n\n• Knowledge of audio signal processing and related techniques.\n• Experience with web backend development in Python (e.g., Flask, FastAPI).\n• Familiarity with AI and machine learning concepts.\n• Basic experience with JavaScript for front-end or tooling development.\n\nTop Benefits\n\n• Salary: Competitive, pay according to ability. Negotiation during the interview.\n• Social insurance and health insurance according to labor laws.\n• Creative, open-minded working environment that respects individuals.\n• FPT Premium Care package.\n• Activities and culture with FCI and FPT Corporation.\n• Study support package for children of FCI union.\n• Sponsor related courses and certifications.\n\nWorking Environment\n\n• Working Location:\n  • Site Hanoi: 7th Floor, FPT Tower, no. 10 Pham Van Bach Street, Dich Vong ward, Cau Giay district, Hanoi.\n  • Site HCMC: 3rd floor, PJICO Tower, no. 186 Dien Bien Phu, Ward 6, District 3, HCMC.\n• Working hours:\n  • 8h30 AM – 12h00 PM.\n  • 1h00 PM – 5h30 PM.\n• Working days: Monday to Friday (weekends off).\n\nContact Person\n\nPham Thi Ha My (Ms.) – Talent Acquisition Team Lead\n\nEmail: Mypth3@fpt.com\n\nPhone: 0962456194\n\nFPT Smart Cloud (FCI) Co., LTD\n\nAddress: 7th Floor, FPT Tower, No. 10 Pham Van Bach, Cau Giay Dist, Hanoi\n\nWebsites: FPT Cloud | FPT AI\n\n#Text-to-speech Engineer\n\nXem thêm các vị trí nổi bật khác tại đây: https://fptsmartcloud.com/co-hoi-nghe-nghiep\n\nSend CV', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1701, 490, 2, 'PHP Fullstack developer', 'Are you looking for an opportunity to make an impact, grow your skills and catapult your career with a growing company?\nMealSuite is looking for a Fullstack PHP developer to join our development team on our mission to revolutionize the continuum of care through our all-in-one foodservice management technology. In this role, you will be responsible for building and maintaining websites and web applications from end to end. This includes both back-end and front-end development, as well as managing databases and creating seamless user experiences. You will work closely with designers, marketing and product teams to deliver high-quality solutions for our clients. A strong eye for UX/UI and the ability to adapt to the needs of a fast-paced marketing agency or consulting environment are essential.\n\nRequirements\n\n- Strong English communication skills to collaborate with cross-functional teams to ensure design, development, and business objectives align\n- Build and develop websites and web applications from start to finish, including backend, database, and front-end components\n- Write efficient, maintainable PHP code, focusing on plain PHP with minimal framework reliance.\n- Manage back-end services, server-side logic, and databases using MySQL and PropelORM\n- Create responsive, user-friendly interfaces using HTML, CSS, JavaScript, jQuery, and Bootstrap, ensuring compatibility across browsers and devices\n- Design and maintain database schemas, manage data relationships, and optimize database queries for performance\n- Collaborate with design teams to build user-centric, visually appealing, and functional websites. Ensure seamless user experience across all platforms\n- Integrate third-party services and external APIs, enabling enhanced functionality and features for web applications\n- Identify, troubleshoot, and resolve issues in code, databases, or UI/UX\n- Refactor and optimize legacy code to improve maintainability, performance, and scalability\n- Maintain thorough and clear documentation of code and development workflows\n\nNice to Have:\n\n- Familiarity with React, Angular, or Vue.js for dynamic front-end development\n- Familiarity with PHP frameworks like Laravel is a plus\n- Experience using design tools such as Figma or similar to collaborate with design teams\n- Familiarity with JIRA or similar tools for project tracking and management\n\nBenefits\n\n- Stock options\n- Vietnam labor law contract with full benefits\n- 13th months salary\n- 1 day work remote every week\n- Up to 22 days annual leave\n- 100% probation salary\n- Unlimited access to Udemy Business online learning platform\n- Free snacks & beverages\n- Team events\n- Awesome and meaningful products', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1702, 961, 2, 'Lập Trình Viên .Net', 'Giới thiệu FiinGroup và Innovation\n\nĐược thành lập từ năm 2008, FiinGroup tự hào là đơn vị dẫn đầu trong mảng cung cấp dịch vụ thông tin tài chính, thông tin doanh nghiệp, thông tin thị trường và xếp hạng tín nghiệm thông qua các sản phẩm công nghệ. Chúng tôi tự hào là một doanh nghiệp FDI với các đối tác chiến lược nổi tiếng toàn cầu bao gồm Nikkei (công ty mẹ của Financial Times), QUICK, Ngân hàng Phát triển Châu Á (ADB) và gần đây nhất là S&P Global Ratings – Hãng Xếp hạng Tín nhiệm số một thế giới. Đồng hành cùng FiinGroup đồng nghĩa bạn được làm việc trong môi trường năng động, trẻ trung, chuyên nghiệp và luôn thay đổi không ngừng để tạo ra những chuẩn mực mới trong ngành.\n\nInnovation là bộ phận giải quyết vấn đề Công nghệ của FiinGroup, đã và đang cung cấp đầy đủ các dịch vụ phát triển phần mềm, đặc biệt là trong lĩnh vực Tài Chính. Chúng tôi tập trung vào các giải pháp hiệu quả để giải quyết được các vấn đề phức tạp của khách hàng nhằm đem lại cho họ trải nghiệm tốt nhất.\n\nMô tả công việc\n\n- Bạn sẽ được làm gì\n- Xây dựng các sản phẩm phần mềm của Công ty, bao gồm các sản phẩm về lĩnh vực chứng khoán, dữ liệu tài chính và thông tin Doanh nghiệp (FiinPro, FiinTrade, FiinGate và các sản phẩm trong quy hoạch 5 năm). Các sản phẩm hiện đang được dùng với 90% các định chế tài chính trong nước, một số định chế tài chính nước ngoài đầu tư vào Việt Nam và 50,000+ nhà đầu tư cá nhân chuyên nghiệp.\n- Xây dựng Web Services, API và các Windows Application kết nối chia sẻ dữ liệu giữa các hệ thống.\n- Tham gia vào quá trình phát triển, nâng cấp các hệ thống phần mềm của Công ty.\n\n- Bạn sẽ được học gì/ thử thách gì\n- Cơ hội được đào tạo nâng cao nghiệp vụ thường xuyên.\n- Có cơ hội tiếp cận, làm việc và đào tạo về tài chính, chứng khoán.\n\nYêu cầu\n\n- Tốt nghiệp các trường CĐ/ĐH chuyên ngành CNTT hoặc các chuyên ngành liên quan.\n- Tối thiểu 1 năm kinh nghiệm trong phát triển .NET Core và .NET 3.5+.\n- Thành thạo MS SQL Server, SQL tuning.\n- Kinh nghiệm làm việc dự án theo mô hình Agile và các công cụ liên quan như JIRA.\n- Có đam mê kỹ thuật công nghệ, có tư duy kỹ thuật tốt và có khả năng tiếp cận nhanh kiến thức mới. các sản phẩm công nghệ, giải pháp công nghệ.\n\nƯu tiên\n\n- Ứng viên có hiểu biết Redis, Memcached. Có kinh nghiệm với các website có lượng truy cập lớn, các ứng dụng realtime.\n- Ứng viên có kiến thức về HTML, XML, JavaScript, CSS, HTML 5 và CSS 3.\n- Ứng viên có kiến thức về phân tích thiết kế lập trình và quy trình phát triển phần mềm.\n- Có hiểu biết về tài chính chứng khoán là một lợi thế.\n\nChế độ\n\n- Thu nhập hàng tháng: Theo năng lực, có thể thỏa thuận. Tháng lương 13.\n- Thưởng năm theo năng lực, thưởng dự án và các mức thưởng khác theo Quy chế Thu nhập.\n- Các khoản phúc lợi: Thưởng Lễ, Tết, … bằng tiền theo Thỏa ước Lao động tập thể.\n- Chính sách BHXH, BHYT, BHTN, KPCĐ và các phúc lợi khác theo đúng quy định của Luật lao động và của Công ty.\n- 14-16 ngày phép/năm so với trung bình 12 ngày phép/năm trên thị trường.\n- Đối với Senior trở lên: Được đóng bảo hiểm Sức khỏe PVI\n- Khung giờ làm việc linh hoạt.\n- Trợ cấp các loại tùy theo đối tượng: phụ cấp điện thoại, phụ cấp gửi xe ô tô, trợ cấp kết hôn.\n\nGửi CV Email liên hệ: Talents@fiingroup.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói, Hanoi, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1703, 962, 2, 'Middle/ Senior Java Developer (English)', 'About Us:\nAt CJ OliveNetworks Vina, we drive digital transformation and innovation of space and daily life with our experience and know-how in successfully providing end-to-end IT service based on life and culture. Our mission is contributing to the growth and happiness of our employees and global community by creating customer values through ONLYONE digital experience.\n\nJob Description\n- Upgrading existing functionalities and creating new functionalities using data-driven insights.\n- Implement and delivery New Customer project development with great quality\n- Involvement in all phases of the development cycle.\n- Active participation in planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional or integration tests and perform unit testing\n- Code review for other team members\n- Automate the maintenance work with the development \n- Responding and Resolving IT support requests from Employees via phone, email, SR System.\n\nYour Skills and Experience\nMust-have\n- Experience in designing, implementing and maintenance support on Java-based (Spring Framework) backed applications with (JSP) Frontend , 5+ years\n- Analyse, design and develop new functionality adhere to the standard provided, and as well maintenance support or issue fixing if necessary\n- Worked on enterprise-scale projects using *Oracle P/L, MyBatis; Java (Spring Boot / Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner)\n- Be proficient in the technology stacks or tools such as Azure, AWS, Redis, etc.\n- Proficient skills with tools used in software development lifecycle, such as DBWeaver, Oracle SQL Developer, Eclipse, IntelliJIDEA, Git, Gradle, Maven, and other CI/CD tools\n- Experience in Database such as *Oracle, Microsoft SQL Server or My SQL. Understand structure and hands on experience in writing Query, Stored Procedures, Functions, Scheduler, Table, Index, etc.\n- Familiarity with debugging and performance tuning along with a good understanding of deploying, maintaining and monitoring complex Java Web applications.\n- Solid Object-Oriented analysis and design skills, understanding of design patterns and concepts as well as adhere or follow to the system code standardization.\n\nNice to have:\n- Able to communicate effectively, analytical with good time management, problem-solving and documentation skills.\n- Strong team player skill\n- Able to performance various Developer roles where necessary & System Support\n- Possess the capability to manage varying users of different capabilities \n- Able to multi-task, manage and undertake various projects simultaneously\n- Team player and able to work well with others\n\nWhy you\'ll love working here\n\n1. Salary and Benefit\n- Attractive salary and benefit. Competitive Basic Salary; 13th Salary; Lunch, Gasoline and Telephone allowance; Incentive Bonus and annual salary review.\n- Premium Healthcare for you, 100% covered by the company. Annual medical checking up to USD 5,000 per year.\n- Full package: Full government social, health and unemployment insurance.\n- Extra bonus per personal event such as wedding, family’s funeral, birthday, newborn baby, etc.\n- Paid leave. 12 days per year and 01 day for Company Foundation Day, long service leave.\n- Discount 40% for CJ\'s brands: CGV Cinema, Tous Les Jours, CJ Food, Meet Master, CJ Market, etc.\n\n2. Working Environment\n- Working time: Monday – Friday. We work 40 hours per week.\n- English working environment: Chance to work onsite abroad and work on challenging GDC projects. Work closely with both Vietnamese and Korean experts.\n- Internal English/ Korean Class: Fully sponsored by the Company after working time.\n- Company trip and team building, football club, dinner party every month. We love playing teamwork games.\n- Free snacks, drinks (tea, coffee, etc.).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1704, 963, 2, 'Lập trình viên PHP Laravel (Middle)', 'Mô tả công việc\n\nSử dụng ngôn ngữ lập trình PHP Laravel để thực hiện các công việc:\n\n- Tham gia nghiên cứu và ứng dụng công nghệ mới vào phát triển các dự án outsource: Thương mại điện tử, Giáo dục, CRM, NFT,... và product nội bộ\n- Nâng cấp, tối ưu hóa, cải tiến hệ thống các sản phẩm đã có\n- Phân công nhiệm vụ, hỗ trợ và review code cho các thành viên khác trong team\n- Thực hiện các nhiệm vụ theo yêu cầu của Lãnh đạo phòng\n\nYêu cầu ứng viên\n\n- Học vấn: chuyên ngành CNTT các trường Đại học, ưu tiên: HUST, VNU, PTIT,...\n- Từ 3+ năm kinh nghiệm lập trình PHP Laravel\n- Tham gia ít nhất 1-3 dự án phát triển từ đầu (không phải maintaince)\n- Có kinh nghiệm break task, sắp xếp quản lý công việc của các member Junior/Fresher trong dự án; training được cho Thực tập sinh là điểm cộng\n- Có kinh nghiệm sử dụng Linux hoặc Windows server (sử dụng/ cài đặt các loại DB và sử dụng giao diện dòng lệnh)\n- Có kiến thức nền tảng tốt về OOP, Web Development, DBMS, ORM\n- Nắm vững mô hình MVC, có hiểu biết về Database (SQL, NOSQL)\n- Hiểu rõ về các công cụ quản lý source code như git\n- Có kinh nghiệm lập trình NodeJS, VueJS, ReactJS là 1 lợi thế\n- Tư duy lập trình, xử lý issue khá - tốt\n- Có tinh thần học hỏi, cập nhật các xu hướng công nghệ mới\n- Có khả năng làm việc nhóm và độc lập\n- Có tinh thần trách nhiệm trong công việc\n- Tham gia các dự án outsource thị trường Nhật là điểm cộng\n- Ứng viên có khả năng lead team 3-5 người là điểm cộng\n- Ưu tiên ứng viên trong độ tuổi: 1995 - 2000\n\nQuyền lợi\n\n- Lương $1000 theo năng lực + thưởng dự án/KPI, các dịp lễ\n- Hỗ trợ ăn trưa, đi lại hàng tháng: 500.000 VNĐ / tháng\n- Thưởng lương thứ 13, có cơ hội sở hữu ESOP của công ty\n- Review lương 2 lần / năm hoặc khi có hiệu quả công việc xuất sắc\n- Định hướng phát triển Techlead/PM, DM, core member của công ty\n- Hỗ trợ học, thi các chứng chỉ liên quan đến chuyên môn nghiệp vụ\n- Du lịch hàng năm, teambuilding hàng tháng, happy hour hàng tuần\n- Lớp học tiếng Nhật, CLB bóng đá hàng tuần\n- Đầy đủ các quyền lợi khác theo quy định chung của công ty và pháp luật VN\n- Môi trường làm việc trẻ trung, năng động, supportive\n- Địa điểm: Tầng 4, tòa Mai Linh Đông Đô, 499 Lương Thế Vinh, HN\n- Thời gian làm việc: 08:00 AM - 05:15 PM Mon - Fri', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj a okolí', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1705, 682, 2, 'DevSecOps Engineer - Khối Công nghệ thông tin (HO25.259)', 'JOB DESCRIPTION\n- Develop and optimize DevOps/DevSecOps processes, applying automation principles to enhance IT application deployment efficiency.\n- Deploy, operate, and manage CICD/IaC solutions, containerization, and Kubernetes technologies such as GitLab, Jenkins, Nexus, Docker, ISTIO, Ansible, Rancher, etc.\n- Responsible for deployment, optimization, monitoring, and analysis of products.\n- Participate from the early stages of product development, designing non-functional components to ensure system security and support operational processes, including:\n  + Designing systems that comply with security policies and regulations.\n  + Standardizing logging, tracing, and monitoring information using tools like ELK, Prometheus, Grafana.\n\nJOB REQUIREMENT\n- Bachelor\'s degree in Information Technology, Applied Mathematics, Telecommunications, or related fields.\n- Open to freshers\n- Preference for candidates with hands-on experience in DevOps/DevSecOps at technology companies or financial organizations\n- Understanding of software development processes, familiar with Agile mindset.\n- Knowledge of database management systems, including Oracle, SQL Server, PostgreSQL, MongoDB, etc.\n- Experience in building CI/CD Pipelines, with proficiency in one or more of the following tools: Jenkins, GitLab, Nexus, Harbor, Docker, Helm, Kubernetes, Prometheus, Grafana.\n- Proficiency in English, capable of working directly with international partners.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1706, 964, 2, 'Back End Engineer (Golang, Web3)', 'Working Location: Serepok, 11th Floor, 56 Nguyen Dinh Chieu, District 1, Ho Chi Minh\n\nCDEX is a trailblazing company at the forefront of AI Automation, driving innovation and efficiency in various industries. Our mission is to harness the power of artificial intelligence to streamline and enhance business processes, enabling organizations to achieve new levels of productivity and success.\n\nAt CDEX, we specialize in developing cutting-edge AI-driven solutions that automate routine tasks, optimize workflows, and deliver actionable insights. Our team of experts leverages state-of-the-art technology to create bespoke automation tools tailored to the unique needs of each client. Founded on the principles of excellence, innovation, and customer satisfaction, CDEX is committed to delivering top-tier AI solutions that not only meet but exceed our clients\' expectations. Our dedication to continuous improvement and staying ahead of industry trends ensures that we remain a trusted partner in the ever-evolving landscape of AI Automation.\n\nJob Responsibilities:\n- Design and develop scalable Web3 backend APIs, enabling seamless interaction between backend and frontend applications and the blockchain, ensuring high availability and performance for millions of users worldwide.\n- Develop and maintain backend services for smart contract interaction, ensuring seamless integration and communication between smart contracts and the application layer.\n- Focus on creating robust APIs and middleware that facilitate secure and efficient interactions with the blockchain, handling tasks such as event listening, transaction processing, and on-chain data retrieval.\n- Specialize in smart contract lifecycle management, from writing and deploying smart contracts to conducting automated testing and security audits.\n- Ensure the reliability and security of smart contracts through rigorous validation processes, upgrades, and optimizations to support flawless execution on the blockchain.\n- Optimize blockchain data processing, implementing efficient methods for ingesting, storing, and querying on-chain data to support real-time analytics and user-facing applications.\n- Collaborate on cross-functional projects, working closely with front-end developers and product teams to integrate blockchain functionalities into user-centric applications, enhancing overall user experience.\n- Implement best practices for blockchain security, staying ahead of the latest in smart contract vulnerabilities, and employing rigorous security measures and auditing processes to safeguard all deployed contracts and back-end systems.\n- Advance our infrastructure-as-code approach, taking a hands-on role in the continuous integration and delivery pipelines, ensuring that all back-end services are scalable, reliable, and secure.\n- Drive innovation in Web3 technologies, researching and integrating new blockchain protocols and tools to keep the platform at the cutting edge of decentralized applications.\n\nRequirements:\n- At least 3+ years of experience in backend development, with a strong focus on Golang or RUST.\n- Strong understanding of blockchain architecture, smart contracts, and DeFi protocols.\n- Strong experience in Web3/crypto industry.\n- Experience with database technologies (SQL, NoSQL) and managing distributed data systems.\n- Proven experience in building and maintaining APIs, microservices, and backend infrastructure.\n- Experience with highly scalable Web API engineering.\n\nBenefits:\n- Competitive salary and performance bonuses.\n- Professional development opportunities.\n- Collaborative and innovative work environment.\n- Top-tier Equipment – MacBook Pro M4.\n- No Micromanagement – No check-in/out required, flexible as long as tasks are delivered.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1707, 848, 2, '[ELCOM Hà Nội] Kỹ sư AI (Computer Vision)', 'MÔ TẢ CÔNG VIỆC\nPhát triển, triển khai và tối ưu hóa các mô hình AI trong lĩnh vực Computer Vision, bao gồm: Object Detection, Instance/Semantic Segmentation, Image Classification và Image Generation.\nXây dựng Automation Workflow kết hợp AI Agents hỗ trợ thu thập, gán nhãn, xử lý dữ liệu, huấn luyện mô hình đến triển khai sản phẩm.\nNghiên cứu, phát triển các mô hình VLM như: InternVL, CLIP, BLIP-2 ứng dụng cho các bài toán: Image-Text Retrieval, Visual Question Answering (VQA), OCR.\nLàm việc với các framework Deep Learning phổ biến: PyTorch, TensorFlow, OpenCV, MMDetection, HuggingFace Transformers.\nỨng dụng các kỹ thuật mới như LoRA, QLoRA, Diffusion models, Zero-shot/ Few-shot learning để tối ưu hoá chi phí và hiệu quả mô hình.\nLàm việc chặt chẽ với đội ngũ sản phẩm và kỹ thuật để tích hợp AI vào backend và ứng dụng thực tế.\n\nYÊU CẦU\nTốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Khoa học Máy tính, AI hoặc các lĩnh vực liên quan.\nTối thiểu 2 năm kinh nghiệm trong lĩnh vực AI/Computer Vision.\nƯu tiên ứng viên có kinh nghiệm với Vision-Language Models, mô hình đa phương thức và Agents.\nNắm vững các thuật toán Machine Learning và Deep Learning, đặc biệt trong mảng Computer Vision.\nThành thạo một trong các ngôn ngữ lập trình: Python, C++.\nKinh nghiệm thực tế với các thư viện: PyTorch, TensorFlow, OpenCV, HuggingFace, MMDetection.\nHiểu biết sâu về các kiến trúc Transformer-based models như CLIP, BLIP-2, SAM, ViT.\nCó kinh nghiệm fine-tuning, sử dụng LoRA hoặc các kỹ thuật tối ưu trên mô hình lớn.\nCó khả năng xử lý dữ liệu đa phương thức: ảnh, video, văn bản.\nKinh nghiệm triển khai mô hình trên GPU/TPU, tối ưu hóa inference bằng ONNX, TensorRT hoặc tương đương.\n\nLÝ DO ĐỂ ĐỒNG HÀNH VỚI ELCOM\nSự Tiên Phong Trong Công Nghệ\nTham gia ứng dụng công nghệ mới vào những sản phẩm lớn, bộ giải pháp toàn diện Top đầu thị trường thuộc các lĩnh vực Chuyển đổi số, An ninh Quốc phòng, giao thông thông minh,...\nĐược tiếp cận với xu hướng công nghệ hàng đầu, phát triển giải pháp thông minh "powered by AI"\n\nMôi trường thân thiện, chia sẻ, đồng hành:\nMôi trường CNTT năng động, thân thiện, cởi mở, tôn trọng sự khác biệt và đề cao sáng tạo, được làm chủ công việc và tận hưởng thành quả đạt được. Minh bạch, thẳng thắn trao đổi thống nhất với cấp trên trong suốt quá trình làm việc và các đợt review năng lực hàng năm.\n\nNền Tảng Vững Chắc Cho Phát Triển Sự Nghiệp, Thăng Tiến, Quyền Lợi\nGói đãi ngộ cạnh tranh với mức thu nhập hấp dẫn.\nGói thưởng trực tiếp từ lợi nhuận Công ty, 6 khoản thưởng cho các ngày Lễ khác trong năm, thưởng nóng, ESOP,.. \nPhụ cấp công tác. Cấp laptop và các phương tiện/tài khoản/thẻ ĐT/công cụ cần thiết khác cho công việc\nChăm sóc sức khỏe: Bảo hiểm sức khỏe cho nhân viên và người thân với hạn mức lên tới $6000/người; khám sức khỏe định kỳ tại các bệnh viện hàng đầu.\nĐược hưởng toàn bộ các quyền lợi theo Luật lao động ban hành về chế độ tham gia bảo hiểm xã hội, nghỉ lễ, nghỉ phép năm.\nBữa trưa được phục vụ miễn phí tại văn phòng.\nCùng nhau đóng góp cho cộng đồng nhiều giá trị, có ý nghĩa sâu sắc với các chương trình từ thiện lớn của Công ty hàng năm: Trăng sáng yêu thương, Cơm có thịt,...\nCác hoạt động văn hóa, giải trí phong phú: Du lịch, teambuilding, ngày hội sinh nhật công ty tại các địa điểm du lịch, resort cao cấp, cháy hết mình tại các CLB thể thao (Zumba, bóng bàn, bóng đá, cầu lông), âm nhạc ( guitar, trống…)\nCác hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân…\nThời gian làm việc: thứ 2 đến thứ 6.\n\nĐịa điểm làm việc: Elcom Building, ngõ 15 phố Duy Tân, Cầu Giấy, HN\n\nThông tin liên hệ: Ms Linh: 086 9696 811 (zalo/viber/tele) Email: linhpt@elcom.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1708, 916, 2, 'JobAdder | Fullstack Engineer (.Net/Angular)', 'At CBTW, we are looking for your talent to strengthen and grow our community of software product engineering experts. Join a company that values you, building and growing its presence and giving you the opportunity to express your talents, share your passion and communicate your ideas.\n\nSo, would you like to join JobAdder in partnership with CBTW and become one of us in Ho Chi Minh City?\n\nHere’s all the information you need!\n\nQualifications\n\n- Deep knowledge and experience in application development with .Net C#, Net Core, MS SQL Server\n- Strong English communication skills (both verbal & written), especially in the global software development environment\n- Experience with modern javascript frameworks (Angular or React) for front-end development\n- Experience with Unit / Integration testing\n- Understanding the design, implementation and operation of distributed Microservices and APIs\n- Experience with CI/CD pipeline tools (Git, Terraform, Cypress, TeamCity, Octopus Deploy)\n- Experience with AWS or similar cloud-based\n- Be happy to coach, mentor and train less senior colleagues\n\nResponsibilities\n\nYou will be part of a cross-functional team that’s responsible for the full software development life cycle, from conception to deployment. As a senior software engineer, you will influence and support your team to champion and deliver high quality, secure and scalable software.\n\n- Design, develop, test and deploy high-quality, secure, scalable software\n- Work with team leads, developers, product managers, QA, and devOps to develop solutions that drive our business goals, make work easier for our customers and deliver good performance, scalability, and reliability.\n- Participate in and help drive the best possible ways of working for software development including Continuous Improvement, CI/CD and test automation.\n- Ensure code quality and maintainability by tackling tech debt, conducting code reviews, initiate refactoring and improve build and test systems\n- Provide continuous support and guidance to less senior colleagues through regular coaching activities and support them in fulfilling their personal development plans.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1709, 965, 2, 'Quality Assurance Tester', 'Responsibilities\n- Develop and execute test plans and test cases for feature requirements\n- Identify & report bugs with detailed information, collaborating closely with developers to ensure timely fixes\n- Provide testing estimates and participate in project planning\n- Maintain quality control procedures and documentation\n- Adapt quickly to changes in project scope or priorities, while maintaining a high level of quality\n\nRequirements\n- Bachelor of Information Technology, or relevant field \n- 1-2 years of software testing experience with both web and mobile applications\n- Experience in analyzing specification requirements, developing, performing test cases, creating testing reports. \n- Basic understanding of blockchain concepts (smart contracts, wallets, dApps)\n- Familiar with Agile/Scrum model and regression testing \n- Have win-win mindset, able to debate and contribute to make productive software \n- Flexibility and adaptability in a startup environment with shifting priorities.\n\nBenefits\n- Aura Network is collaborating with FPT Software Vietnam for handling back-office procedures so the applicant will receive all healthcare, vacation, and benefits provided by FPT Software.\n- Salary and bonus are negotiable depending on the skills and commitment of the applicant, we are very flexible.\n\nAbout Us\nPlease visit us at: https://aura.network\n\nHow to Apply\nSounds like a good fit? Send us your CV to: hr@aura.network or apply here', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1710, 674, 2, 'Tuyển Nhân Viên Blockchain Developer (DAO)', 'Mô tả công việc\nBạn Sẽ Là Một Phần Trong Nhóm Đầu Tiên Xây Dựng Nền Tảng DAO Và Các Thành Phần Web3 Tích Hợp Vào Hệ Thống Thương Mại Điện Tử\nThiết kế và phát triển smart contract (Ethereum, Polygon, Layer 2…) cho:\nQuản trị DAO (vote, proposal, reward)\nQuản lý đóng góp của cộng đồng sellers/devs (staking, incentive)\nTích hợp với hệ thống nội bộ PSA (userID ↔ walletID, roles ↔ reputation,...)\nXây dựng backend + API để giao tiếp giữa web2 (ERP/CRM) và web3 (smart contract);\nPhối hợp với team AI/Data/Product để thiết kế DAO vận hành minh bạch nhưng tối ưu hóa bằng automation;\nNghiên cứu và ứng dụng các mô hình decentralized identity (DID), tokenized reputation, on-chain/off-chain governance.\nYêu cầu công việc\nBắt Buộc\nTối thiểu 2 năm kinh nghiệm làm việc với blockchain, smart contract (Solidity, Web3 stack);\nĐã triển khai ít nhất 1-2 dự án thực tế có sử dụng contract trên testnet/mainnet;\nThành thạo Node.js hoặc Python, có kinh nghiệm tích hợp backend với smart contract (Web3.js, Ethers.js,...);\nTư duy hệ thống tốt, có khả năng phối hợp với team Product/Dev để xây DAO gắn với vận hành thực tế;\nĐọc hiểu tài liệu kỹ thuật tiếng Anh tốt, tự research, cập nhật công nghệ mới chủ động.\nƯu Tiên\nỨng viên ở mid-to-senior level hoặc Web3 builder thực chiến (dù không chính thức làm blockchain job trước đó);\nCó kinh nghiệm xây dựng DAO, ứng dụng voting logic, tokenized incentive;\nTừng làm việc với các nền tảng như: The Graph, Arbitrum/Optimism, zkSync, IPFS, ENS, WalletConnect,...\nTư duy về on-chain governance, reputation system, hoặc cross-chain integration là lợi thế rất lớn.\nTại sao bạn yêu thích làm việc tại đây\nLương: Thỏa thuận theo năng lực + thưởng theo hiệu suất;\nLương T13, T14, tăng lương hàng năm theo năng lực;\nTham gia BHXH, BHYT, BHTN theo quy định, khám sức khỏe tổng quát định kỳ;\nDu lịch 2 lần/năm, quà/thưởng lễ tết, sinh nhật, đồ ăn vặt tại văn phòng,...;\nHỗ trợ ăn trưa, gửi xe, laptop làm việc;\nTham gia các khóa học nâng cao chuyên môn.\nHình thức làm việc (chọn 1 trong 2 hình thức sau):\nOffice: T2-T6: 9:00-17:30 (nghỉ trưa 1h30p) / sáng t7 remote: 8:00-12:00\nĐịa chỉ: Tropic Garden A2 - 56 Đường số 66, Thảo Điền, Thủ Đức, HCM\nRemote: T2-T6: 8:30-17:30 (nghỉ trưa 1h30p) / sáng t7: 8:00-12:00\nCách Thức Ứng Tuyển\nGửi CV + Bảng điểm (scan/ảnh file pdf, jpeg, png) về email career@makezbright.com hoặc liên hệ Zalo: 0942 485 129 (Vy PSA).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1711, 952, 2, 'Fullstack Engineer', 'About FPT Smart Cloud\n\nFPT Smart Cloud (FCI) – a member of FPT Corporation, pioneers AI & Cloud solutions in Vietnam. FCI was founded with the mission to generating an immense leap in productivity and agility in business operations.\nFPT Smart Cloud aims at leading the industry by focusing on building a firm technological foundation, developing diversified ecosystem products, and reaching global connectivity.\n\nCustomized to specific needs: Providing cloud-based products and solutions customized to each industry.\nAll-in-one Platform: Consolidating FPT Smart Cloud technology and diverse business solutions all in one platform. AI & Cloud services are a Unify eco-system.\nLocal market leadership: Outstanding Cloud and AI technology infrastructure and platform to help local businesses grow their products and services online.\nDeliver the future: Help customers achieve business outcomes faster by integrating world-class processes and technology.\n\nJob Responsibilities\n\nWork closely with Product Owner and team leader to understand and implement business functionality.\nDesign, develop, and maintain cross-platform applications using Python and\nCollaborate with product managers, designers, and other engineers to deliver high-quality software solutions.\nWrite clean, maintainable, and efficient code. Ensure that applications perform consistently and optimally under varying amounts of load and stress.\nImplement security measures to protect sensitive information.\nTake part in review and test process (develop unit test, automation test or create test cases for system test) to ensure product quality of code and technical document.\nTroubleshoot, debug web application with a fast and accurate resolution.\nDocument development processes, code changes, and other relevant information.\n\nRequirements\n\nBachelor’s or master’s degree in computer science, Information Systems, or a related field.\nAt least 3 years of experience developer role.\nProven experience with the full software development life cycle, including design, testing, deployment, and documentation activities.\nProven experience in software development using Python.\nStrong knowledge of PyQt for developing graphical user interfaces.\nExperience in building and deploying applications on multiple platforms (Windows, Linux, macOS).\nExperienced in using git, git-flow, docker and virtual environment management tool (venv, pipenv, …). Familiarity with CI/CD pipelines.\nHave experience working under Scrum/ or other Agile frameworks is plus.\nExperienced in networking concepts and protocols (UDP, TCP, RDP).\nGood at communication and critical thinking skills\n\nTop Benefits\n\nSalary: Competitive, pay according to ability; negotiable during interview.\nSocial insurance and health insurance according to labor laws.\nCreative, open-minded working environment that respects individuals.\nCollaborate with global technology leaders and a passionate, talented team.\nFPT Premium Care package.\nActivities and culture with FCI and FPT Corporation.\nStudy support package for children of FCI union.\nSponsor related courses and certifications (recommended).\nBe part of a strategic initiative to build innovative AI solutions powered by NVIDIA technologies.\nWork in a dynamic, fast-growing environment with opportunities to shape the future of AI services in Vietnam and Japan.\n\nWorking Environment\n\nWorking Location:\nSite Hanoi: 7th Floor, FPT Tower, no. 10 Pham Van Bach Street, Dich Vong ward, Cau Giay district, Hanoi.\n\nWorking hours:\n8h30 AM – 12h00 PM\n1h00 PM – 5h30 PM\n\nWorking days: Monday to Friday (weekends off)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1712, 881, 2, 'Senior Java Software Engineer', 'Mô tả công việc\n• Tham gia xây dựng nền tảng full-stack phục vụ giao diện quản trị nội bộ (WebAdminPortal)\n• Phát triển các thành phần backend sử dụng Java, Spring Boot, triển khai logic nghiệp vụ và tích hợp với frontend qua các API RESTful.\n• Phối hợp với frontend (ReactJS) để thiết kế giao diện quản trị mượt mà, dễ sử dụng.\n• Phân tích và giải quyết các bài toán nghiệp vụ phức tạp, từ frontend đến backend.\n• Tham gia review code, tối ưu hiệu năng hệ thống, đảm bảo chất lượng sản phẩm.\n• Đóng góp ý tưởng, cải tiến về kiến trúc, luồng dữ liệu và trải nghiệm người dùng trong hệ thống quản trị.\n• Làm việc trong môi trường Agile/Scrum, phối hợp với DevOps, QA, BA trong toàn bộ vòng đời phát triển phần mềm.\n\nYêu cầu công việc\n• Tối thiểu 4 năm kinh nghiệm phát triển phần mềm, trong đó ít nhất:\n• Thành thạo Java Core, OOP, Spring Boot (MVC, Security, JPA), API design.\n• Có kinh nghiệm làm việc với ReactJS (Hooks, Redux, React Router, Axios...).\n• Nắm vững HTML, CSS, JavaScript (ES6+), TypeScript là một lợi thế.\n• Hiểu về mô hình RESTful, cơ chế xác thực (JWT, OAuth2), CORS, session/cookie.\n• Kỹ năng tốt về Git, CI/CD, làm việc trong môi trường Agile/Scrum.\n• Tư duy logic tốt, có kinh nghiệm phân tích và giải quyết bài toán nghiệp vụ từ frontend đến backend.\n\nƯu tiên:\n• Có kinh nghiệm về cấu trúc monorepo hoặc tách biệt FE/BE rõ ràng.\n• Hiểu và làm việc tốt với Docker, Kafka, Redis, hoặc PostgreSQL.\n• Từng tham gia các hệ thống lớn: e-commerce, fintech, SaaS... là lợi thế.\n• Có khả năng viết test unit (Jest, JUnit) và hiểu về TDD là điểm cộng.\n\nQuyền lợi\n1. Chế độ lương, thưởng, thu nhập:\n• Thu nhập cạnh tranh thỏa thuận theo kinh nghiệm và năng lực.\n• Lương tháng 13, Thưởng quý, Thưởng dự án, Thưởng năng suất.\n• Nghỉ mát, thưởng ngày lễ và các ngày chỉ có ở Viettel như Ngày Sáng Tạo - 1/6, 22/12, quà Tết Dương, Tết Âm tri ân Gia đình, người sinh thành (25-30 triệu/năm)\n• 16 ngày nghỉ phép/năm hưởng nguyên lương.\n• Bảo hiểm sức khỏe ABIC, bảo hiểm sức khỏe cho người thân, bảo hiểm nhân thọ,…\n• Hưởng các Chính sách đãi ngộ toàn diện của "Người Viettel"\n\n2. Cơ hội phát triển bản thân:\n• Cơ hội thăng tiến không giới hạn, trở thành quản lý của các dự án mới.\n• Được thử sức với các công nghệ mới, dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n• Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n• Cơ hội được đào tạo, trau dồi kĩ năng, chuyên môn để phát triển toàn diện.\n\n3. Môi trường làm việc:\n• Được làm việc trong Tập đoàn toàn cầu, tiên phong thực hiện sứ mệnh kiến tạo xã hội số.\n• Môi trường mở, trẻ trung, năng động, trân trọng, yêu thương, tương hỗ & lắng nghe mỗi người từ những ý tưởng nhỏ nhất.\n• Không gian làm việc xanh, mở, hiện đại.\n• Thời gian làm việc: Thứ 2 đến thứ 6.\n\nĐịa chỉ làm việc: 36A Dịch Vọng Hậu, Cầu Giấy, HN\n\nThông tin liên hệ: \n• Người liên hệ: Nguyễn Thị Hà Trang\n• Số điện thoại: 0398 195 353\n• Email: trangnth80@viettelsoftware.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1713, 899, 2, 'Software Engineer (ReactJS/NodeJS/VueJS/Fullstack)', '1.Address: \n2-7-11F, CIC Tower, No.2 Nguyen Thi Due, Yen Hoa, Cau Giay, Ha Noi.\n7F, Golden Park, No.2 Pham Van Bach, Yen Hoa, Cau Giay, Ha Noi.\n\n2.Job Requirement: \nAt Least from 3 years of professional software development experience in one of Frontend (ReactJS OR VueJS), OR Backend (NodeJS) OR FullStack (Level Middle/Senior)\nProficiency in English with strong oral and written communication skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1714, 209, 2, 'Cloud Front End Software Engineer', 'Job Responsibilities:\nAs part of the Audio Video Solution (AVS) business unit, we are seeking a technical service provider to support the AVS cloud services team in developing cloud-based user interfaces and data processing pipelines. The mission requires specialized resources to \n- Develop both the UI components and the underlying data architecture, ensuring seamless integration with Generative AI and machine learning models.\n- Designing, coding, and debugging Android applications and services for Android TV devices.\nThe UI Team will be responsible for creating modern, responsive, and AI-enhanced* interfaces for various AVS cloud services, to delivery\n- Video Soundbox Command Management Interface\n- Agent Reconfiguration Management Interface\n- Product Location Interface (IP/SSID tracking)\n- Role-Based Access Control (RBAC) & Role Creation Interface\n- Natural Language Text Management Interface (AI-based interactions)\n- Dynamic Dashboard Management (Scope-based UI)\n- Message Interface (Cloud-to-Device communication)\n- Enhanced Virtual Remote-Control Interface\n- Android Application Management Interface\n- WSSpeaker Management Interface\n\nRequired Skills and Experience:\n- Vue.js (Vue 3) / JavaScript – Frontend development with component-based architecture.\n- CSS – Creating modern, responsive UI/UX experiences.\n- Bootstrap / Vuetify – For designing mobile-first and adaptive interfaces.\n- Vite – For optimized frontend development workflows.\n\nLanguages:\n- Mandatory: Vuejs/Java Script, CSS\n- Nice to have: Generative AI* Integration – Experience with AI-powered UI enhancements.\n\nJoin us to develop industry-leading solutions that bring high-quality audio and video experiences to homes worldwide. If you are passionate about Android TV development and have a strong foundation in embedded systems, we’d love to hear from you!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1715, 615, 2, 'Java Engineer', 'As a proud member of Galaxy Holdings - Sovico Group, Galaxy Technology stands as a dynamic force in the digital realm, recognized for our prowess in talent and customizable solutions. We are dedicated to propelling businesses worldwide to new heights through cutting-edge digital, software, and IT solutions. Across diverse industries, including Aviation, EAI, Fintech, Manufacturing, Automotive, Blockchain, Medical, Health Tech, Real Estate, Hospitality, Education, and beyond, we serve as a strategic partner, empowering organizations with innovation and excellence. \n\nResponsibilities and Duties \n• Participate in projects to develop web applications. \n• Work with other project members, responsible for the implementation & code review & testing. \n• Consistently delivers high-quality services and meets customer requirements. \n• Other assignments from Leader/ Project Manager. \n• Able to estimate tasks. \n• Ensure the assigned tasks to be performed on time and with high quality. \n\nQualifications \n• Degree in Software Engineering, Information Technology or relevant. \n• From 3 years of experience in working with Java Spring boot. \n• Experienced in working with SQL. \n• Read/write design (function design or details design). \n• Having knowledge about DevOps (kubernetes, docker, aws, proxySQL). \n• Good time management, communication, and problem-solving skills. \n• Good teamwork spirit and logical thinking. \n• Proactive, well self-organized and responsible at work. \n• Able to quickly manage new technologies.\n\nWhy You\'ll Love Working Here \n• Attractive income. \n• Pay your full salary in two months of probation. \n• Review salary once per year. \n• 12 days of annual leave. \n• Year-end bonus/ performance bonus based on the business performance. \n• Social, Health and others Insurance are based on Labor Law and Health insurance PVI. \n• Activities: Company Trip, Year End Party, Sport (football, badminton, running club…), Christmas, Charity activities, … \n• Good work environment and working in a professional, friendly, well-equipped environment. \n• Chances to work in a big and global team, work directly with customers', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1716, 966, 2, 'Test Engineer', 'INNOMIZE is seeking a Test Engineer to join our growing team! INNOMIZE always raises the quality of our clients’ software throughout the entire quality lifecycle. From quality assurance assessments and advice on best practices to implementing process improvements followed by continuous test execution, we speed our clients’ products to market at the highest possible quality. As a member of the team, you will receive enthusiastic support from the Leader/Manager in your work and guidance regarding your career development.\n\nWhat You\'ll Be Doing\n\n- Execute manual tests, record results, and generate test reports.\n- Create, update, and maintain test cases for new and existing features.\n- Identify and document functionality and usability errors in the issue-tracking system.\n- Assist developers in reproducing and debugging issues.\n- Create and maintain project-related documentation.\n- Communicate issues, progress, and test status to the team and management.\n- Maintain and enhance automated test scripts; update tests as needed for bug fixes or new features.\n- Perform other testing-related duties as assigned.\n\nYour Skills And Experience\n\n- Bachelor\'s Degree in Software Engineering or related area.\n- 2 years of experience with testing software applications.\n- Strong attention to detail and critical thinking skills.\n- Clear communication (written and verbal) in English is a must.\n- Understanding of Software Development Life Cycle (SDLC).\n- Knowledge of Testing Techniques and Methodologies.\n- Familiarity with test case & bug management tools (e.g., JIRA, Confluence).\n- Basic API testing tools like Postman.\n- SQL for basic data validation.\n- Basic programming knowledge in JavaScript or TypeScript.\n\nNice To Have\n\n- Experience (or familiarity) with Puppeteer or Playwright.\n- Experience or experimentation with AWS services (e.g., Cognito, S3, Lambda).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1717, 910, 2, 'DevOps Co-Founders Wanted | Builders of Scalable Tech Infrastructure', '🌟 About Antler: We are a global early-stage investment firm that invests in startups from day zero. We provide funding, mentorship, and a global network to help you build and scale your startup. With Antler, you’ll have access to the resources you need to turn your vision into reality—whether you\'re still ideating or already started building.\n\n👩‍💼 Who are we looking for?\nNote: This ad is not for a job, but rather for the opportunity to find your co-founder and build your own VC-backed startup through a 10-week program with Antler.\n- Experts in DevOps, CI/CD, and infrastructure automation.\n- Entrepreneurs who have built and scaled cloud-native architectures for reliability and performance.\n- Visionaries who understand the challenges of software delivery at scale and can optimize development workflows.\n- Leaders who can create robust DevOps tools that empower engineering teams and accelerate software development.\n- Self-starters driven to launch and grow a world-class DevOps company.\n\n📋 Details of the program:\n- The program runs for an initial 10 weeks, full-time in Ho Chi Minh City (Vietnam) and starting on 21 July 2025, where you are required to ideate and find your co-founder(s) from the cohort of 60-70 founders.\n- After two months you will present your team and business idea to the Antler Investment Committee. If accepted, you will receive a pre-seed investment of $120K USD for 12% equity, non-negotiable.\n- If you get an investment, you will continue to be part of the program for another 3 months during which Antler will work closely with you to accelerate your growth. At the end of this period, Antler arranges a demo day where we invite VCs, institutional investors, and local angel investors to help you connect with investors and raise your seed round.\n\nFor more details on what to expect 👉 https://www.linkedin.com/smart-links/AQGwMqMCzPe68Q\n\nBenefits:\n- 💵 Potential investment at the pre-seed stage\n- 🤝 Help finding your co-founder(s)\n- 👨‍🏫 Personalized coaching sessions with business experts\n- 🛫 Relocation grant of $2,000 if you\'re relocating from overseas to HCMC, Vietnam\n- 🏬 Shared office space at a premium co-working space with access to various amenities\n- 🌍 Access to a global network of start-up advisors and experts in their field.\n\nSome examples of successful companies that were built as a result of Antler’s program, received pre-seed investment from Antler, and gone on to raise substantial investment are:\n- Xailient - the World’s fastest Computer Vision AI\n- BUYO - Pioneering bioplastics and material tech\n- SKYQRAFT - Affordable and safe powerline inspections with drones and AI\n- Airalo - The world’s first eSIM subscription and top-up store\n- homebase - Making home ownership accessible\n- Reebelo - Circular economy for e-devices.\n\nReady to help shape the future of the world? Apply now to Antler and together we will build something truly amazing ✨', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1718, 967, 2, 'Senior Fullstack Engineer', 'About Us\n\nJitera is an AI startup with the mission to "Build the Next Era of Software Development." We are revolutionizing the future of software development through generative AI. We are enhancing quality and speed across all phases of software development—from requirements definition to software design, development, testing, and operations—by implementing innovative processes powered by generative AI. We are also advancing technical developments that leverage the unique characteristics of generative AI, such as the automatic generation of system design documents from source code and automated test code generation based on requirements. Since 2019, Jitera has provided software development services and low-code products. Following the release of ChatGPT in November 2022, we anticipated the era of generative AI and pivoted our low-code product strategy. In September 2024, we launched "Jitera," our AI agent. We are experiencing rapid revenue growth with successful implementations across dozens of enterprise companies.\n\nGlobal & Fully Remote\n\nSince launching our business in 2019, Jitera has been building a borderless organization in pursuit of becoming a global leader. We have adopted a fully remote work policy as our fundamental approach. Currently, our teams span across Asia, Europe, and the United States, attracting top-tier talent from around the world. We are entering an incredibly exciting phase as we write a new chapter in history as a globally expanding company.\n\nKey Responsibilities\n\n• Design, implement, test, and release high-quality software speedy.\n• Work with other engineers, designers, and product managers to implement various features while considering maintainability, security, and performance.\n• Represent the engineering team in meetings, contributing to ideas relevant to product growth with a strong understanding of future customers and their desires.\n• Monitor and fix bugs to ensure that customers can use the application as expectedly.\n• Catch up on AI trends and utilize AI services including Jitera products to have AI-driven development.\n• Create technical documentation and communicate clearly across the product team.\n• Support team members to review, feedback, and onboard.\n\nRequirements\n\n• More than 5 years of experience in software development\n• More than 5 years of experience in React, NextJS, and TypeScript\n• Experience in server-side development with NestJS and NodeJS\n• Must have experience in using AI Agents\n• Bachelor’s degree in Computer Science, Software Engineering, or a related field (or equivalent work experience)\n• Proficient in English at a business level, demonstrating effective communication skills for professional interactions and collaborations.\n• Strong motivation to utilize AI technology to have AI-driven development.\n• Good understanding of fundamental design patterns in software design.\n• Ability to work independently.\n• Communication skills to work cooperatively in a remote team.\n• Ability to prepare a remote work environment where you can focus on your work with a stable network place.\n\nDesirable Experiences\n\n• Experience in React Native development\n• Experience in developing applications with NoCode services.\n\nTechnology Stack We Use\n\n(We don\'t expect you to have or experience all of these, but you may meet them when working on the project)\n\n• Frontend: TypeScript, React, NextJS, React Native, Styled Components, React Query and React Zustand\n• Backend: NodeJS and NestJS\n• Database: MySQL, Redis, and PostgreSQL\n• Infrastructure: AWS, Docker, Terraform, HashiCorp Vault\n• CI/CD: GitHub Actions, AWS CodePipeline\n• Project management: GitHub, Jira\n\nCompensation, Perks & Benefits\n\n• Competitive Salary\n• Health insurance allowance\n• Company-provided equipment\n• Unlimited paid time off\n• Tax payment (maximum 10% of salary)\n• Special events, off-site meetings, occasions, celebrations, and gifts.\n• Sponsorship for online classes according to your demand (Coursera, Datacamp, Udemy…)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1719, 737, 2, 'Senior Full Stack Developer (Java/ReactJS)', 'Summary \n\nJoin Aperia Solutions, a leader in SaaS solutions for the Payments and Compliance industries. Aperia is a Texas-based fintech and managed consultancy firm that creates custom SaaS applications and other software-based solutions for the payments, banking, and processing industry. Founded in 1999, Aperia offers business intelligence, risk management, compliance, and customer intelligence platforms. With offices in Dallas, Washington DC, and Vietnam, Aperia is a fast-paced, global organization that strives to improve efficiency in compliance, risk, and customer service operations. Aperia\'s clients include banks, processors, payment facilitators, merchant service providers, independent sales organizations, and government entities. A career at Aperia promises a great challenge, culture, and opportunities to forge your own path.\n\nJob Description\n\nAt Aperia, we thrive on innovation and the strength of our dynamic development team. We are currently seeking a Senior Full Stack Developer (Java/ReactJS) with a strong background in Java and J2EE who is passionate about modern technologies, cloud-native architecture, and secure, scalable systems. If you\'re eager to push boundaries and drive meaningful impact in a fast-paced fintech environment, we want to hear from you.\n\nCore Responsibilities\n\n- Full lifecycle - analysis, design, development, testing and implementation- of new or enhancements to middleware (micro) services\n- Maintain middleware modules and services with code quality standards\n- Keep applications free of security vulnerabilities in compliance with organization\'s security policies\n- Assist in troubleshooting and resolving production issues. Provide suggestions for preventative steps\n- Incorporate suggestions for improvements and enhancements where meaningful\n- May assist/lead in developing and maintaining technical documentation and store it in central locations (like Confluence, SharePoint) for accessible to team members.\n\nTechnical Skills:\n\n- 8+ years of hands-on experience in Java/J2EE development.\n- Expertise in Spring, Spring Boot, Spring Cloud, Spring Security, Spring Data, and RESTful APIs.\n- Working knowledge of RabbitMQ or similar message brokers.\n- Proficiency in Oracle PL/SQL.\n- Strong unit testing skills with JUnit.\n- Exposure to ReactJS on the frontend.\n- Experience with build tools like Maven, and artifact repositories like Nexus.\n- Familiarity with Postman for API testing and PCF (Pivotal Cloud Foundry).\n- Demonstrated experience in addressing security vulnerabilities and managing open-source dependencies.\n- Maintain high code quality using tools like SonarQube.\n- Version control and CI/CD experience using GitLab.\n- Proficient with Atlassian tools including JIRA and Confluence.\n- Solid understanding of Linux environments\n- Proficiency in English communication is required.\n\nThings that will separate you from the rest:\n\n- Experience with JIRA integration and custom workflows.\n- Familiarity with logging and monitoring tools like Splunk.\n- Ability to collaborate effectively with onshore and offshore teams.\n- Background in the finance or banking industry.\n- Strong problem-solving, debugging, and communication skills (written and verbal).\n\nJob Type\n\n- Full-Time\n\nSchedule\n\n- Monday to Friday\n\nWork Location \n\n- The Six8 Building: 24-26 Phan Dinh Giot, Tan Binh District, HCMC\n- VDB Tower: 74 Quang Trung, Hai Chau, Danang\n\nBenefits \n\n- Health insurance \n- Dental insurance\n- Paid time off\n- Parental leave\n- Childcare assistance\n\nThis job description is not intended to be all-inclusive. An employee may also perform other reasonable related business duties as assigned by their immediate supervisor or management. Principals only. \n\nRecruiters please don\'t contact this job poster. DO NOT contact us with unsolicited services or offers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1720, 739, 2, 'Developer Fullstack', 'The SOCOTEC Group offers its customers and partners missions throughout the life cycle of infrastructure and buildings to ensure compliance, extend their lifespan, improve their technical, energy and environmental performance, and thus guarantee the safety of people. Independent trusted third party and with offices in 26 countries and more than 11,300 people.\n\nSOCOTEC is a leading player in risk management and technical advice in the world. Established in Vietnam since 2018, SOCOTEC Vietnam works closely with colleagues in France, Germany, Italy, UK, USA, Spain, Netherlands and other SOCOTEC offices. For our office in Hanoi, we are looking immediately for a Technical Reporting Engineer.\n\nAs a full stack developer, you will be part of a journey to build the new generation of IoT platform. You will develop exciting solutions that change the way both Socotec Monitoring colleagues and client’s work. Integrated to our dev department, you will work in a collaborative, welcoming environment where new ideas drive technological transformation. Your responsibility includes:\n\n- Contribute to the development of the IoT platform with the latest innovation (AI, BIM, GIS)\n- Adaptive to ambiguity and willing to change in a fast-paced environment\n- Hands on experience with web development.\n\nQualifications:\n\n- Bachelor’s degree in Computer Science or related field, or equivalent practical experience\n- 3 to 5 years of experience in Fullstack development with React for frontend and Node.js for backend\n- Proficient in PostgreSQL databases system\n- AWS experience is appreciate (Lambda, Timescale, S3)\n- Familiar with controlling tool such as Git/GitHub/GitLAB\n- Good proficiency in verbal and writting in English. French or other languages are highly appreciated\n- Experience using modern collaboration tools in a highly responsive environment\n- Working as a team spirit, proactive communication, consciously curious and motivated character.\n\nAdditional Information:\n\n- Attractive salary and bonus with annual revision\n- Compulsory insurance pay as gross monthly salary\n- Flexible working time with 12 annual leave days & 15 work from home days\n- Team-building activities, Sport Clubs\n- Cooperation with colleagues around the world in a leading global group\n- Strong team spirit in an entrepreneurial environment of a growing company\n- People values, social responsibility and sustainability\n- Opportunities for self-development and career advancement\n- Internal training courses (technical, foreign language, soft skill)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đình Ba, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1721, 968, 2, 'Vibe Coder / Software Engineer', 'Tired of software development that crawls at a snail\'s pace? Frustrated by teams clinging to outdated practices while AI revolutionizes the industry? If you\'re nodding vigorously right now, we need to talk.\n\nWhile most engineering teams are cautiously dipping their toes into the AI waters, Trilogy has already dived into the deep end. We\'re not just using AI as a fancy add-on—we\'ve rebuilt our entire development ecosystem around it. From conceptualization to deployment, every step of our process harnesses AI to eliminate inefficiencies, accelerate delivery, and achieve precision that manual processes simply cannot match.\n\nAs our Vibe Coder, you\'ll transform legacy B2B solutions into sleek, cloud-native powerhouses with AI intelligence embedded throughout. You\'ll implement cutting-edge retrieval-augmented generation (RAG) systems that automatically detect and resolve defects before they become problems. Our standard? Flawless deployments. Zero downtime. No exceptions.\n\nIf you thrive on action rather than endless architectural debates, if you\'re energized by pushing technological boundaries instead of maintaining the status quo, and if you\'re ready to revolutionize software development through AI integration—we want you on our team. But fair warning: if you\'re comfortable with manual testing, resistant to automation, or prefer traditional development cycles, this position will push you far beyond your comfort zone.\n\nWhat You Will Be Doing\n\n- Harness sophisticated RAG vector stores and analysis frameworks to detect, isolate, and eliminate product defects with unprecedented efficiency\n- Orchestrate AI development agents to conceptualize, construct, and deploy breakthrough features across our cloud-native ecosystem\n- Synergize with our worldwide talent network to craft enterprise solutions that exceed industry standards\n\nWhat You Won’t Be Doing\n\n- Wrestling with Infrastructure Headaches: We\'ve streamlined our systems to minimize tedious configuration tasks, allowing your creativity to flourish on solution development\n- Death by Discussion: Our culture prioritizes productive coding over excessive meetings—expect to spend your time building, not talking about building\n\nVibe Coder / Software Engineer Key Responsibilities\n\n- Create and integrate AI-enhanced features that revolutionize service provider workflows and deliver groundbreaking tools that transform user experiences\n\nBasic Requirements\n\n- Minimum 4 years hands-on experience crafting commercial-grade software, with specific focus on production-ready server-side web applications\n- Demonstrated proficiency with GenAI coding assistants such as Github Copilot, Cursor, or v0.dev\n- Enthusiasm for incorporating GenAI tools into your daily development workflow and continuous improvement process\n\nAbout Trilogy\n\nHundreds of software businesses run on the Trilogy Business Platform. For three decades, Trilogy has been known for 3 things: Relentlessly seeking top talent, Innovating new technology, and incubating new businesses. Our technological innovation is spearheaded by a passion for simple customer-facing designs. Our incubation of new businesses ranges from entirely new moon-shot ideas to rearchitecting existing projects for today\'s modern cloud-based stack. Trilogy is a place where you can be surrounded with great people, be proud of doing great work, and grow your career by leaps and bounds.\n\nThere is so much to cover for this exciting role, and space here is limited. Hit the Apply button if you found this interesting and want to learn more. We look forward to meeting you!\n\nWorking with us\n\nThis is a full-time (40 hours per week), long-term position. The position is immediately available and requires entering into an independent contractor agreement with Crossover as a Contractor of Record. The compensation level for this role is $30 USD/hour, which equates to $60,000 USD/year assuming 40 hours per week and 50 weeks per year. The payment period is weekly. Consult www.crossover.com/help-and-faqs for more details on this topic.\n\nCrossover Job Code: LJ-3889-VN-COUNTRY-VibeCoder/Soft', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1722, 878, 2, 'Senior Full Stack Developer (HCMC/ Da Nang, Hybrid) (Visa and Relocation Package Provided)', 'About Nimble\n\nWe solve our client\'s most difficult business challenges through technology. Our company partners with the most ambitious companies around the world creating long-term impact with the work with do. If you want to grow together, work on challenging products and enjoy using the best tools and practices, Nimble is the right place for you!\n\nOur Core Values\n\n• Ownership mentality: Treat our company and our clients’ business as ours taking care of the collective interests. This, in the end, translates to personal interests achievement through our company\n• Dependable & Resilient: We go to great lengths for our clients, they can rely on us to deliver and all our team members are reliable and trustworthy and we don’t give up when we face challenges.\n• Obsession for Excellence: Our delivery quality has no parallel.\n• Courage: We must have the courage to speak up, raise our concerns in a timely manner and be able to confront the status quo with ideas by being constructive and without holding on to hard feelings.\n\nWhat You Will Do\n\n• You will be an active member or lead a team of developers in a project squad. We have a wide range of project sizes.\n• Decide which technologies are going to be used for front-end, back-end and define the overall architecture.\n• Work closely with the Product Owner to make sure the backlog is efficiently planned and occasionally assist in technical discussions with clients. Most of the client interfacing is done by the Product Owner.\n• Write clean, composable, and maintainable code as you develop world-class products for our clients.\n• Write automated tests to build and maintain the product we build for our clients.\n• Do code reviews with your squad members.\n• Learn new technologies languages like Ruby, Go, or Elixir, and techniques so that you are able to adapt to the evolving needs of our clients.\n• Knowledge sharing through team rituals.\n• Collaborate with other team members to define the internal processes and initiatives to help the company accomplish its mission. Our handbook has been written by the whole team.\n\nRequirements\n\n• Professional web development with 5+ years of experience. Experience in Ruby, JavaScript, Go is ideal (at least one of them).\n• Comfortable working both on frontend and backend.\n• At least basic experience with a modern JavaScript framework like ReactJS/Redux, VueJS or AngularJS.\n• Experience in writing automated tests for web applications.\n• Enjoy working on challenging solutions and systems.\n• Believe that building great applications is not only about delivering code that “works”, but involves thinking about reusability, maintainability, security, and performance.\n• A "Can do attitude" and a product mindset.\n• Confidence in communicating in English.\n\nWhy You\'ll Love Working Here\n\n• You’ll feel proud of every product we ship. We care deeply about quality, design, and doing things right—our name stands for excellence.\n• You’ll be surrounded by high performers. We’re a tight-knit, ambitious team that pushes each other to grow and thrive.\n• We\'re built differently. We’ve been profitable and bootstrapped since day one—no VC pressures, just smart, sustainable growth.\n• We take pride in craftsmanship. Whether it\'s code, design, or delivery, we hold ourselves to a high bar—because the little things shape the big picture.\n• Process with purpose. We follow agile principles not just in theory, but in practice. Our engineers work with clearly defined user stories, estimate using story points, and deliver iteratively in focused 1–2 week sprints.\n• Growth is part of the job. Through regular one-on-ones, structured feedback, and a clear leveling framework, we support every team member’s growth—not just in technical skills, but in communication, collaboration, and leadership.\n• Learning never stops. Access a vast library of resources like Pluralsight, PragPub, Leanpub, e-books, and more—plus a yearly education allowance to help you level up in any direction you choose.\n• We’ve got your back. From day one, you’ll get private medical insurance, social welfare coverage, and a company care fund.\n• We support your move. If you\'re joining us from abroad, we’ll take care of your visa, work permit, and provide a relocation package to help you settle in smoothly.\n• Flexibility that fits. We support a hybrid workstyle, giving you the freedom to find the right rhythm between home and office life.\n• Work with the right tools. We’ll set you up with a MacBook and a large external monitor so you can work comfortably and efficiently.\n• A workspace that works for you with our modern office in the heart of Ho Chi Minh City and Da Nang.\n• Stay fueled. Our kitchen is always stocked with drinks and snacks.\n• Take the time you need. Enjoy 26 days of paid leave a year (including public holidays), plus a sabbatical month every 3 years.\n• Celebrate your journey. From anniversary gifts to yearly company outings and spontaneous team activities, we make time for fun and appreciation.\n• ...and more perks to make work feel better.\n\nIf you are a passionate web professional looking to make a significant impact in a growing software development company, we would love to hear from you.\n\nJoin us in shaping the future with with elevating web innovation!\n\nWe keep our recruitment process practical and straightforward.\n\nTo learn more about how we work, check our handbook named Compass, Github organization, and Medium account.\n\nWant to see what we have built? Check our Dribbble and Behance accounts.\n\nWant to keep in touch with us? Follow us on Facebook, Instagram, and LinkedIn.\n\nNimble is an equal opportunity employer.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh-Stadt, Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1723, 880, 2, 'Freelance Software Developer (Java) - AI Tutor', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with Java.\n- Code review experience is a must.\n- Experience with AI projects is a plus.\n- Your level of English is advanced (C1) or above.\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines.\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge.\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments.\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio.\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1724, 808, 2, 'Junior AI QA Engineer', 'Job Description\n\n- Support Design & Execute Test Cases: Design and execute test cases for AI features, including functional testing and non-functional testing (performance, security, scalability).\n- Support AI Model Testing: Participate in testing and evaluating machine learning models, including tests for accuracy, stability, and fairness (bias).\n- Support Test & Analyze Results: Conduct system testing, identify bugs, and analyze test results to pinpoint potential issues.\n- Support Test Automation: Support the QA team in developing and maintaining basic automation test suites for AI functionalities.\n- Report Writing & Documentation: Write detailed reports on discovered bugs, store, and maintain testing documentation.\n- Ensure Data Quality: Test and evaluate the quality of input and output data for AI models, identifying and reporting potential data-related issues.\n\nRequirements\n\n- Bachelor’s Degree/Associate Degree: Relevant fields such as Information Technology, Computer Science, or related disciplines.\n- Knowledge of AI/ML: Basic knowledge of AI concepts, machine learning (ML), and Natural Language Processing (NLP) is a significant advantage.\n- Strong Analytical Skills: Ability to analyze problems, identify root causes, and propose solutions.\n- Communication Skills: Clear and effective communication skills to interact with stakeholders.\n- Experience with Tools: Familiarity with project management tools such as JIRA, performance testing tools like JMeter, LoadRunner.\n- Automation: Experience or basic knowledge of test automation (Automation Testing) using frameworks such as Selenium, Cypress is a plus.\n\nPreferred Skills\n\n- Ability to read and understand code (Python, JavaScript) to support source code testing is a plus.\n\nWork Location\n\n4F Artemis, No 3 Le Trong Tan, Thanh Xuan, Hanoi\n\nBenefits\n\n- 5-day workweek\n- Young & vibrant working environment with great career development opportunities\n- Social insurance, medical insurance, unemployment insurance, are based on actual salary\n- Yearly performance bonus (up to 2 months’ salary)\n- Regular team building events & internal activities (weekly happy hour, quarterly team building events, Lunar New Year parties, etc.)\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1725, 887, 2, 'Java Developer (Middle - Senior)', '[SW Development]\nLG CNS is looking for qualified Back-end developer \nMission:\n- Ensure the best possible performance, quality and responsiveness of applications on the back end side.\n- Stay up to date on emerging technologies.\n- Exchange details when interviewing\n- Manage and training members in your PART (if you were chosen as Part leader)\n\nRequirement\n[Required]\n- Have at least 4 years of experience in JAVA (Highly preferred)\n- Have experience developing web applications\n- Have Java programming experience\n- Developed based on Spring, Spring Boot F/W, Spring MVC...\n- API Development (REST API)\n- RDBMS (MySQL, PostgreSQL, Oracle) & SQL, PL/SQL\n- Have knowledge Python language\n- Git, Jira, Confluence\n- Understand and apply CI/CD\n- Good at communicate in English at an average level (TOEIC 550 or higher)\n- Be proactive and responsible at work.\n\n[Nice-to-have]\n- Experience working in Kubernetes and Cloud environments (AWS, GCP) \n- Experience in SQL optimization\n- Able to communicate in Korean\n\nOpportunity\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Review capacity annually and adjust salary increases according to work performance.\n- Korean language certificate bonus (TOPIK)\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8:00 - 12:00 - 13:00 - 17:00)\n\nLocation\n- 15th Floor, Keangnam Landmark 72, Me Tri, Nam Tu Liem, Hanoi\n\nHow to apply\n- Please send me your CV\n\nHiring Process\n1. Book an Interview Schedule with HR manager.\n2. 1st interview with VN Senior Leaders (Offline Interview)\n3. 2nd Interview with Kr Senior PM (Online meeting room, use English and Vietnamese to answer)\n4. If passed, negotiate salary and bonus.\n5. Confirm onboarding Date.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1726, 490, 2, 'PHP Fullstack developer', 'Are you looking for an opportunity to make an impact, grow your skills and catapult your career with a growing company?\n\nMealSuite is looking for a Fullstack PHP developer to join our development team on our mission to revolutionize the continuum of care through our all-in-one foodservice management technology. In this role, you will be responsible for building and maintaining websites and web applications from end to end. This includes both back-end and front-end development, as well as managing databases and creating seamless user experiences. You will work closely with designers, marketing and product teams to deliver high-quality solutions for our clients. A strong eye for UX/UI and the ability to adapt to the needs of a fast-paced marketing agency or consulting environment are essential.\n\nRequirements\n\n- Strong English communication skills to collaborate with cross-functional teams to ensure design, development, and business objectives align\n- Build and develop websites and web applications from start to finish, including backend, database, and front-end components\n- Write efficient, maintainable PHP code, focusing on plain PHP with minimal framework reliance.\n- Manage back-end services, server-side logic, and databases using MySQL and PropelORM\n- Create responsive, user-friendly interfaces using HTML, CSS, JavaScript, jQuery, and Bootstrap, ensuring compatibility across browsers and devices\n- Design and maintain database schemas, manage data relationships, and optimize database queries for performance\n- Collaborate with design teams to build user-centric, visually appealing, and functional websites. Ensure seamless user experience across all platforms\n- Integrate third-party services and external APIs, enabling enhanced functionality and features for web applications\n- Identify, troubleshoot, and resolve issues in code, databases, or UI/UX\n- Refactor and optimize legacy code to improve maintainability, performance, and scalability\n- Maintain thorough and clear documentation of code and development workflows\n\nNice to Have:\n\n- Familiarity with React, Angular, or Vue.js for dynamic front-end development\n- Familiarity with PHP frameworks like Laravel is a plus\n- Experience using design tools such as Figma or similar to collaborate with design teams\n- Familiarity with JIRA or similar tools for project tracking and management\n\nBenefits\n\n- Stock options\n- Vietnam labor law contract with full benefits\n- 13th months salary\n- 1 day work remote every week\n- Up to 22 days annual leave\n- 100% probation salary\n- Unlimited access to Udemy Business online learning platform\n- Free snacks & beverages\n- Team events\n- Awesome and meaningful products', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1727, 690, 2, 'System Administrator & AI Workflow Engineer', 'We are seeking a proactive System Administrator/ Operation Engineer to operate and support our AI (X-Ops) System and Gen AI projects. This role involves providing technical support to both internal users and clients, ensuring the reliability and smooth operation of AI-driven systems. You will monitor system performance using specialized tools and assist end users with technical issues related to AI.\n\nKey Responsibilities:\n\n- Operate and maintain AI (X-Ops) systems and Gen AI projects.\n- Provide technical support to internal users and external clients, addressing system-related inquiries and issues.\n- Monitor system health and performance using monitoring tools; proactively identify and resolve potential problems.\n- Collaborate with cross-functional teams to ensure system availability and optimal performance.\n- Assist users in navigating AI workflows and resolving access or functionality challenges.\n- Document technical procedures, incidents, and resolutions to maintain knowledge base.\n- Support deployment and continuous improvement of AI systems and workflows.\n\nKey Qualifications:\n\n- Up to 2 years of experience in system administration, technical support, or related IT roles.\n- Experience with system monitoring tools and troubleshooting.\n- Basic understanding or strong interest in AI technologies and workflows.\n- Excellent problem-solving skills and ability to communicate effectively with technical and non-technical users.\n- Experience supporting both internal users and external clients is a plus.\n- Ability to work independently and collaboratively in a fast-paced environment.\n\nWhy You Should Join:\n\n- Shape the internal infrastructure of a modern tech organization\n- Combine operations with AI innovation in a highly agile team\n- Work closely with business, technical, and product leadership\n- Lead initiatives that scale knowledge, reduce noise, and enable transparency\n\nApply now!\n\nDue to the high volume of applicants, only shortlisted candidates will be contacted. We apologize for this inconvenience!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミン市 3区, ベトナム', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1728, 884, 2, 'System Engineer (Automotive)', 'What you’ll do\n\n- Contribute to software development related to ADAS/AD\n- Be responsible for software specifications, architecture, and IV&V (Integration, Verification and Validation) strategy\n- Work closely with the safety team on system level requirements and safety architecture\n\nWhat you’ll need\n\n- Bachelor’s degree or above in System/Electrical/Computer/Mechanical/Software, or a related field of study.\n- Having automotive background (ADAS and autonomous driving system and sensors are preferred).\n- Excellent oral and written communication skills in English\n\nNice to Have’s\n\n– Experience with various ADAS/AD systems.\n– Familiar with automotive regulations and functional safety standards (ISO 26262).\n– Familiar with writing requirements for Automotive systems.\n– Familiar with system/software integration and validation testing.\n– Ability to multi-task in a fast-paced environment and meet tight deadlines.\n\nWhy you’ll love work here\n\n- The exciting environment of a fast-paced AI technology startup.\n- Opportunity to apply your knowledge and skills to make a real impact on the world.\n- Compensation is competitive and will consider the applicant’s current experience level.\n- Opportunity to continuously grow your knowledge and your leadership skills.\n- Opportunity to contribute, interact, share, and learn from exceptionally talented colleagues\n\nContact\n\nInterested applicants are invited to send your application to v.loantt27@vinai.io; v.hoangnm31@vinai.io', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město - metropolitní oblast', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1729, 969, 2, 'Smart Contract Developer (Rust, Solana, EVM)', 'As a Smart Contract Developer at Undercurrent Capital, you will be responsible for designing, developing, and deploying smart contracts. You will work closely with our team to create secure and efficient decentralized applications (dApps) with a focus on DeFi. This role requires a deep understanding of blockchain technology, proficiency in Rust, and the ability to bring complex Web3 projects to life.\n\nKey Responsibilities\n\nDesign, develop, and maintain smart contracts using Rust.\nLead the development of decentralized finance (DeFi) applications, including lending protocols, AMMs, yield aggregators, and more.\nConduct thorough code reviews, ensuring high standards of security and functionality to protect user assets and minimize vulnerabilities.\nCollaborate with cross-functional teams including product managers, UI/UX designers, and backend engineers to create seamless blockchain solutions.\nIdentify and fix vulnerabilities in existing smart contracts by conducting audits and performing unit and integration testing.\nTroubleshoot and debug production issues related to smart contracts.\nCreate unit and integration tests for smart contracts and optimize contract performance.\nStay up-to-date with emerging trends, protocols, and best practices in the blockchain technologies, particularly Solidity, and Rust.\n\nKey Requirements\n\nAt least 1 years of experience in blockchain development, focusing on smart contracts.\nStrong proficiency in Rust, especially for Solana.\nExperience working with EVM-compatible chains (Solidity experience is a plus).\nPrior experience in building or contributing to DeFi projects is highly preferred.\nHands-on experience in developing Web3 applications and working with blockchain APIs.\nExperience with smart contract testing frameworks and debugging tools.\nDemonstrable experience in successfully delivering smart contract projects from design to deployment.\nStrong analytical and problem-solving skills with a focus on delivering efficient and scalable solutions.\nAbility to work collaboratively in a fast-paced and dynamic environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1730, 970, 2, '[Remote_HCM] Middle Golang Developer| Non-English| up to $2000', '1. INTRODUCTION\na. About WAO Hire:\nWAO Hire company, is a collective group of tech recruiters and developers. We help fast growing companies connect with talented developers.\n\nWe take the humanized approach to hire and work with developers, because we know that\'s the best way to find the best developers for businesses.\n\n2. REQUIREMENTS\nMinimum 3 years experiences of Golang development\nExperienced in PHP frameworks Laravel to migrate project from PHP to Golang\nStrong Knowledge of SQL DB (MySQL) operation and schema design\nExperienced in websocket, microservice and Rest API,...\nExperienced in monitoring system, optimize system\nKnowledge of basic T-SQL scripting and concept ORM\nGood self-motivate and learning independent\nCan follow coding principle and well coding style\nDedicated working\n\nPlus to have:\nBetter to have experience of secondary development\nKnowledge of DB performance analysis\n\n3. WHY YOU WILL LOVE WORKING HERE?\nBeing a member of us, you will experience a youthful, flexible, and creative work environment\nCompetitive salary ($1500-$2000)\nRemote working\nWorking in a professional, friendly, well-equipped environment both with foreigners and Vietnamese.\nExtensive on job training, you will always have a chance to work with new emerging technologies.\nSocial insurance, health insurance & unemployment insurance according to Vietnam Labor Law.\n12-day annual leave per year.\n\n5. WORKING TIME: 1:00 PM - 10:00 PM from Monday to Friday\n\n6. LOCATION: Remote (HCMC)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1731, 971, 2, 'Software Engineer', 'You will be responsible for:\n- Working in full scope of hypervisor SDK development.\n- Designing, implementing the UI SDK toolkit interface on VSCode extension such as: flashing, Hypervisor Debug Bridge,...\n- Implement communication with backend driver on Linux hardware such as: UART, Ethernet, USB, I2C, SPI, ...\n- Porting OS (Linux, XEN), bootloader and debug, resolve issues on hardware.\n- Other tasks is assigned from higher manager.\n\nYour skill need to be apply:\n- 3+ years of experience SDK developing (Web, Frontend developer) production-quality using JavaScript, CSS, HTML\n- Have basic working knowledge protocol of UART, USB, Ethernet (HTTP), SPI, I2C, …\n\nNice to have:\n- Experience with the hypervisor (XEN OS)\n- Experience in developing embedded Linux kernel drivers and application.\n- Experience in microcontrollers and processors\n- Experience in CPU-base architecture, Embedded Systems, and boot loaders.\n- Experience in RTOS, FreeRTOS, Zephyr, ...\n- Have experience porting OS (Linux, FreeRTOS...) and debug OS in hardware.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1732, 972, 2, 'React Native Developer', 'Mô tả công việc\n- Tham gia phát triển và tối ưu hóa ứng dụng mobile cross-platform (iOS & Android) bằng React Native.\n- Tham gia xây dựng kiến trúc, tổ chức mã nguồn và thiết kế module phù hợp với quy mô sản phẩm.\n- Hợp tác với đội ngũ thiết kế (UI/UX) để biến bản thiết kế thành sản phẩm thực tế mượt mà, trực quan.\n- Tích hợp API, làm việc chặt chẽ với backend để xử lý dữ liệu hiệu quả và đồng bộ.\n- Viết mã sạch, dễ bảo trì, có khả năng tái sử dụng và viết test khi cần thiết.\n- Tham gia vào các buổi họp sprint, đánh giá và cải tiến quy trình làm việc.\n- Theo dõi lỗi sản phẩm, xử lý phản hồi từ người dùng và hỗ trợ bảo trì ứng dụng.\n\nYêu cầu ứng viên\n- Có từ 1 đến 3 năm kinh nghiệm với React Native.\n- Tốt nghiệp cao đẳng hoặc đại học chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm,… hoặc các chuyên ngành liên quan.\n- Thành thạo JavaScript (ES6+), nắm rõ React Hooks, Context API.\n- Có kinh nghiệm với Redux / Zustand / Recoil, hiểu nguyên tắc quản lý state hiệu quả.\n- Hiểu biết về cấu trúc dự án mobile, quản lý dependencies, build tool (Metro, Gradle, Fastlane).\n- Đã từng tích hợp REST API, WebSocket, Firebase hoặc các dịch vụ bên thứ ba.\n- Biết deploy ứng dụng lên App Store và Google Play là một lợi thế lớn.\n- Chủ động trong công việc, có tư duy giải quyết vấn đề và trách nhiệm cao.\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.\n\nĐiểm cộng nếu bạn có:\n- Kinh nghiệm với TypeScript, Expo, hoặc native module (Java/Kotlin, Swift).\n- Hiểu biết về CI/CD cho mobile app, Firebase Analytics, Crashlytics.\n- Kinh nghiệm A/B testing, performance monitoring, push notification, deep linking.\n- Có thể giao tiếp bằng tiếng Anh là một lợi thế.\n\nQuyền lợi\n- Mức lương: \n- Đối với ứng viên có 1-2 năm kinh nghiệm: 7 - 13 triệu.\n- Đối với ứng viên có 2-3 năm kinh nghiệm: 14 - 18 triệu.\n- Được đóng đầy đủ bảo hiểm y tế, bảo hiểm xã hội theo luật.\n- Review lương 1 lần/năm.\n- Thưởng các dịp lễ Tết, thưởng quý, thưởng thâm niên.\n- Quà tặng dịp sinh nhật cá nhân.\n- Cơ hội được học hỏi, làm việc với công nghệ mới.\n- Được làm việc trong một môi trường chuyên nghiệp với các đối tác nước ngoài.\n- Du lịch, teambuilding 2 - 3 lần/năm.\n- Hỗ trợ tham gia các khóa đào tạo nâng cao kiến thức và kỹ năng.\n\nĐịa điểm làm việc: Tây Mỗ, Nam Từ Liêm, Hà Nội.\n\nThời gian làm việc: 9:30 - 18:30 (Thứ 2 đến thứ 6 và làm 2 ngày thứ 7 xen kẽ trong tháng).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1733, 973, 2, 'Lead Java Developer', 'Responsibilities\n\n- Team Leadership: Lead and mentor a team of Java developers, providing guidance on best practices and coding standards.\n- Software Development: Design, develop, and maintain Java applications using modern frameworks and technologies.\n- Code Review: Conduct code reviews to ensure code quality and adherence to standards.\n- Collaboration: Work closely with product managers, UX/UI designers, and other stakeholders to gather requirements and define project scope.\n- Troubleshooting: Identify and resolve technical issues, ensuring timely delivery of solutions.\n- Documentation: Maintain comprehensive documentation of software designs, processes, and procedures.\n\nPrimary Skills\n\n- Languages: Java, SQL\n- Frameworks: SpringMVC, SpringBoot, Hibernate, Junit, Mockito\n- API Specification: RESTful, Swagger\n- Security: Java API Security (Authentication, Authorization, common security standards)\n- Databases: SQL Server, MariaDB, MySQL, PostgreSQL\n- Tools: Gradle, Maven, GIT, JIRA/Confluence\n- Cloud Knowledge: Basic knowledge of AWS Cloud and deployment.\n- Leadership: Having a few years of leading a team experience.\n\nSecondary Skills\n\n- Understanding of alternate cloud providers (AWS, GCP, etc.)\n- Familiarity with Kubernetes on a cloud provider\n- Knowledge of CI/CD tools (like Jenkins)\n\nBenefits\n\n- Base salary from 80.000.000 - 120.000.000 VND/month.\n- Hybrid working environment.\n- Full salary package insurance.\n- Performance Bonus.\n- Project bonus.\n- 13th month salary.\n- Insurance for dependents.\n- Other benefits by current laws.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1734, 489, 2, 'AI Developer Experience Lead', 'At OL Vietnam, we have worked alongside our parent company, Orange Logic LLC, to support some of the world’s largest enterprises with their digital asset management needs. Orange Logic provides a premier Digital Asset Management (DAM) platform that streamlines workflows, enhances collaboration, and ensures compliance across complex digital ecosystems, empowering any team working with digital content the ability to efficiently create, manage, and distribute their content at scale.\n\nWHAT DIFFERENTIATES ORANGE LOGIC\nWe are trusted by global leaders to work with over 100 customers, including many of the world\'s most recognized brands.\nOur business is strong and resilient, even in the face of economic challenges. During the Covid economic downturn, we did not implement layoffs or reduce compensation. Instead, we continued to grow, consistently expanding our team and adding dozens of talented members to our R&D department each year.\nYou’ll work with top engineers and team members who are passionate about building flexible, scalable, and streamlined systems that will define the future of business management.\n\nMISSION\nJob Summary: We are seeking an experienced and innovative AI Development Experience Lead, who will be responsible for leading a small team dedicated to researching, experimenting with, and integrating AI-powered tools into our software development lifecycle. You’ll identify promising trends through focused R&D, validate them with hands-on exploration, and work closely with engineering teams to drive successful adoption. This is a leadership role combining technical insight, strategic planning, and change facilitation—shaping both our practices and our culture as we evolve into an AI-augmented engineering organization.\n\nEssential Functions:\nAI R&D and Strategy\nLead R&D efforts to identify, assess, and stay ahead of AI trends, tools, and best practices that can enhance developer productivity and experience.\nDevelop and drive a strategic roadmap to prioritize and sequence high-impact AI opportunities across the engineering lifecycle.\n\nProof of Concept, Alignment, and Adoption\nPartner with engineering, product, and data science teams to run proofs of concept, pilot AI tools in real workflows, and ensure solutions are adopted and integrated effectively.\nAlign AI initiatives with cross-functional goals, ensuring solutions address genuine developer needs and organizational priorities.\n\nImpact Measurement and Continuous Improvement\nDefine, track, and communicate success metrics to measure the impact of AI adoption on team efficiency, quality, and outcomes.\nEstablish and maintain fast feedback loops with developers, using insights to continuously refine and optimize AI tool integrations.\n\nTeam Leadership and Cultural Enablement\nBuild and lead a high-impact team focused on AI-driven developer experience improvements.\nChampion a culture of experimentation and learning, encouraging teams to embrace new, AI-augmented ways of working.\n\nPROFILE\nThe most successful candidates for this role will have: \nBachelor’s or Master’s degree in Computer Science, Engineering, or a related field.\nExtensive experience in software engineering, with a deep understanding of development processes, tools, and best practices.\nProven expertise in AI and machine learning, particularly in applications related to software development.\nDemonstrated experience leading technical teams and managing projects.\nExcellent communication and interpersonal skills, with the ability to influence and inspire others.\nStrategic thinking and the ability to develop and execute technology roadmaps.\nFamiliarity with modern software development practices.\nExperience with AI tools and platforms relevant to software development.\nStrong analytical skills to measure and interpret the impact of AI initiatives.\n\nPreferred Qualifications\nExperience in change management and driving technology adoption within organizations.\nBackground in developer productivity or developer experience roles.\nContributions to the AI or software development community (e.g., publications, open-source projects…)\n\nBENEFITS\nAs a full-time employee, you are eligible for our benefits program:\nAttractive salary package and 100% Gross Salary in probation period.\n13th-month salary. \n18 days of annual leave (cashback allowed if not used) and plus 4 days for an overseas company trip.\nMultiple allowances (Lunch, Gym, Parking, Birthday/Tet/Wedding voucher... ).\nFull social, health and unemployment insurance.\nPremium healthcare insurance for you and coverage for 1 extra family member.\nMonthly team-building activities (Bowling, Go-Kart,....) and special celebrations on Autumn Festival, Halloween, Christmas, Tet, …\nMonthly happy lunch/birthday celebration and happy hours every day with free snacks, soft drinks, fruit, and coffee.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona metropolitană Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1735, 916, 2, 'CW | Principal/Senior Frontend Engineer', 'CreditorWatch is a commercial credit reporting bureau with over 60,000 customers across Australia, from sole traders through to ASX listed public companies.\n\nCreditorWatch holds the credit file of every entity in Australia and enables businesses of all sizes to access credit risk information on any entity in Australia (including sole traders, trusts and partnerships) to determine what sort of risk they represent to their business.\n\nQualifications\nExperience with Frameworks, e.g React/Redux/Angular/Typescript\nExcellent frontend skills with JavaScript ES6+, HTML5, CSS3\nExperience with Continuous integration and deployment pipelines using tools such as Jenkins, TeamCity, CircleCI etc.\nExperience with building services and RESTful APIs\nExperience with AWS services such as EC2, ElasticSearch, SQS, RDS, Lambda and S3\nMaintaining, refactoring and developing new features on top of legacy code\nIntegrating third party integrations\nExperience and knowledge of building micro services and worked with containers\nAn understanding of Domain Driven Design and bounded contexts\nWilling to do small changes in PHP if required\nGood at English skills\nBe happy to coach, mentor and train less senior colleagues\n\nResponsibilities\nYou are a good fit for us if you love coding and have a real passion for building web applications\nYou would have worked with complex projects in collaboration with other team members to create user-friendly solutions that delight your users\nYou are passionate about continuously learning and experimenting with new technologies along with mentoring junior members of the team\nYou enjoy collaborating with others inside and outside of the engineering team\nYou are motivated, passionate, and proud of your work\nYou take initiative to drive projects forward and you have the ability to articulate ideas and think critically about how to execute them.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1736, 974, 2, 'Senior Front-end Developer (ReactJS, NextJS, English required)', 'Job description 1. Frontend development: analyze requirements and implement responsive and interactive web applications using React and modern frontend technologies (e.g., Redux, Webpack, TypeScript). 2. Collaboration and Agile practices: collaborate with other developers to integrate applications with other systems. Participate in Agile ceremonies (sprints, stand-ups) and contribute to project planning and execution. 3. Code quality and best practices: write clean and maintainable code following engineering best practices (unit testing, source control, continuous integration, design patterns, etc.). Conduct code reviews and provide feedback to peers. 4. Performance optimization: optimize web application performance (e.g., code splitting, lazy loading, caching). Conduct performance testing and tuning to ensure fast load times and smooth interactions. 5. Cross-functional collaboration: collaborate with developers, testers, marketing, product management, and customers to create new solutions, facilitate feedback, and achieve design decisions. 6. Effort estimation: estimate the level of effort during sprint planning, contribute to the technical roadmap and continuous improvement. 7. Leadership: assist other team members with design challenges and coding issues; and evaluate their performance.\n\nDesired Skills and Experience 1. 4+ years’ experience in front-end development and design patterns. 2. Expert knowledge of React, Redux, TypeScript, JavaScript (ES6+), HTML5, and CSS3. Experience with CSS pre-processors (Sass, Less, Stylus) and post-processors (PostCSS). 3. Hands-on skills in caching, optimizing and securing front-end applications. 4. Familiar with task runners and the build process: Webpack / Gulp. 5. Testing practices: experience with BDD and TDD. 6. Experience with large SaaS applications (preferably decoupling monoliths) and microservice architecture. 7. Familiar with source control management: Git 8. Good communication in English. 9. Problem-solving skills. 10. Communication and collaboration skills: able to work independently and in a team environment.\n\nNice-to-have skills: 1. Experience in back-end development (preferably with Laravel/Symfony frameworks). 2. Exposure to working with JSON. 3. OpenAPI, and Swagger. 4. Exposure to DevOps practices and AWS landscape. 5. Exposure to one or more of Solr, Redis, or Elasticsearch.\n\nWhy Ekino? 1. High-ownership working environment: You will take full responsibility and control of your missions contributing to the team’s success. 2. Continuous skill improvement with new technologies, challenging projects, on-the-job coaching, and training programs. 3. Annual performance review & bonus: recognize your efforts and identify development/ improvement needs. 4. Clear career path: define your career development with long-term vision. 5. Be secured in your mind with employee’s care: private healthcare insurance package, medical check-up, support allowance… 6. Great-place-to-work activities (company trip, sport clubs…): enhance teamwork spirit and facilitate your work-life harmony.\n\nThank you for your time and enthusiasm in our career opportunities. Please kindly note that shortlisted candidates will be contacted within 3 weeks of application. Alternatively, we will reach out to you when another suitable chance arises in the future.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1737, 975, 2, 'Python Developer', '1. Mô tả công việc:\n- Phát triển Backend cho hệ thống quản trị và phân tích các chuỗi bất thường trong tổ chức.\n- Nhận yêu cầu từ BA/PO cùng tài liệu, hiểu và thực hiện phát triển Backend theo yêu cầu với tính năng mới hoặc improve các tính năng đã có\n- Phối hợp làm việc với các thành viên trong nhóm và công việc chuyên môn liên quan đến CNTT (SA, Frontend, Dev, Test...) trong quá trình hoàn thiện sản phẩm theo yêu cầu nghiệp vụ.\n- Viết Unit Test tùy theo yêu cầu tính năng\n- Mã nguồn đảm bảo chất lượng theo tiêu chuẩn phổ quát, được tự động phân tích bằng các công cụ chuyên dụng.\n\n2. Yêu cầu công việc:\n- Có từ 2-3 năm kinh nghiệm phát triển backend với Python, ưu tiên sử dụng FastAPI.\n- Hiểu rõ kiến trúc RESTful API, có kinh nghiệm với ORM (SQLAlchemy).\n- Tư duy logic tốt, có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh.\n- Có kinh nghiệm làm việc với Git, Docker.\n- Có tư duy phân tích nghiệp vụ và thiết kế luồng hệ thống.\n- Khả năng giải quyết vấn đề độc lập, đề xuất giải pháp kỹ thuật.\n- Có kinh nghiệm với CI/CD, AWS/GCP, Celery, Alembic.\n- Hiểu biết về bảo mật API, JWT, OAuth2.\n\n3. Đãi ngộ:\n- Mức lương up to 30M/tháng (Gross)\n- Thử việc full lương \n- Hưởng min 13 tháng lương/ năm, các khoản thưởng như thưởng lễ tết, chứng chỉ, giới thiệu ứng viên,.. \n- Hưởng 12 ngày phép/năm theo quy định pháp luật hiện hành\n- Review lương 2 lần/năm (tháng 6, 12)\n- Đước cấp trang thiết bị phục vụ cho công việc\n- Hưởng các chế độ bảo hiểm xã hội, y tế theo quy định pháp luật\n- Được đào tạo, thăng tiến phù hợp trong công việc\n- Được làm việc trong môi trường trẻ trung, năng động.\n- Hưởng chế độ nghỉ mát, teambuilding, các hoạt động thể thao & giải trí phong phú\n- Remote 2 ngày/tháng\n- Thời gian làm việc: 08h30 - 12h, 13h30 - 18h, Thứ 2 - Thứ 6. Nghỉ Thứ 7, CN và các ngày lễ theo quy định\n\n4. Thông tin liên hệ:\n- Email gửi CV: linhth@wanosoft.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona capitalei Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1738, 747, 2, 'Senior JAVA Engineer', 'Your responsibilities\n• Participate in innovative software development life cycle using agile methodologies\n• Adhere to the coding standards, best practices, common design patterns & principles\n• Delivery of high-quality software together with the team, including design, code, troubleshooting, tests, documentation\n• Write the technical design and detailed design for the tasks\n• Self-manage tasks as per the timelines and quality\n• Coach, supervise or lead when necessary other developers and team members\n\nYour qualifications\n• Bachelor\'s degree in computer science or equivalent\n• Good knowledge of OOP, SOLID principles, Design patterns, and data modeling\n• Able to read and write technical documents in the English language\n• Good technical, analytical, and problem-solving skills\n• Passionate, proactive, and keen to learn new technologies (or move to the mission part)\n• Experience in Java technology and ecosystem\n• Experience in SQL and database management systems\n• Knowledge of Javascript, HTML, XML, CSS\n• At least 5 years of experience in software development of this applied stack\n• Proven experience in coaching and supervising other developers and team members\n• Proven experience: Spring, SpringBoot, Hibernate, etc\n\nNice to have\n• Knowledge of the Agile methodology (Scrum).\n• Knowledge of CI/CD (Jenkins, Docker)\n• Experience and/or certifications on Amazon, Azure, and Oracle clouds.\n• Experience in Web development (Angular, ReactJS) or Windows App development\n• Experience in leading a project or a team\n• Oral communication skills in English\n\nWhy you’ll love working here\n• Professional European-based company\n• Attractive salary\n• Performance bonus of up to 4 months‘ salary\n• Opportunities for travel to Europe\n• Hybrid home/office working model\n• Flexible working time\n• Structured training & development roadmap\n• Good work-life balance\n• Premium healthcare insurance\n• Loyalty programs\n• Well-being activities\n• Annual company trips and team-building events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1739, 225, 2, 'Senior Analyst, ReactJs Engineer', 'ABOUT THE JOB\nWe are seeking motivated Senior Frontend Engineers (ReactJs) who are passionate, results-focused to take accountability for the design and delivery of Microservices that will be used by banking front end applications. You will be part of our delivery team and will be responsible for providing technical leadership throughout all phases of the software delivery life cycle as we initiate a transformation of NAB technology.\n\nYOUR JOB RESPONSIBILITIES\n- Design, develop, test, deploy, and support for application code and services that your Agile Team builds.\n- Design, build and manage continuous integration, build management and deployment scripts, systems, and any code as required.\n- Participate in Agile software development, prototyping, and code review with international development teams to build scalable microservices-based products.\n- Understand the requirements of the Product Owner and utilize this knowledge to develop applications that are consistent with this.\n- Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes and tooling.\n- Provide robust coding practices, solid unit and component test coverage, and code debugging.\n\nYOUR SKILLS & EXPERIENCE\nMust have\n- 5+ years’ experience working in Software Development​, solid experience in JavaScript ES6/TypeScript working with React.js\n- Expert in all areas of web development (HTML5, CSS3, Bootstrap, Foundation, JQuery, JSON) including accessibility and security concerns\n- Ability to design React applications using layout management\n- Ability to leverage developer tooling, and CI/CD pipelines to deploy artefacts\n- Ability to build BFF components (Java or NodeJs) – Nice to have\n- Experience in Cloud computing, especially Amazon Web Services (AWS)\n- Understanding of RESTful APIs design (GraphQL desirable) and Microservices-based systems\n- Solid experience in Agile (Scrum model) development environments\n- Well-versed in writing structured, well-documented, maintainable, and clean code\n- Strong English communication skills (both verbal & written), especially in the global software development environment\n\nNice-to-have\n- Experience in the Banking or Financial Services industry;\n- Experience in using front-end testing and test runners (eg. Selenium, Mocha/Chai/Jest).\n- Any additional certification or training in IT, Business, Computer Science, or related area.\n\nTHE BENEFITS AND PERKS\nWe appreciate and reward our colleagues who do great work every day – from excelling for our customers, to taking ownership of an issue to get it resolved. Here’s how we support our people with a range of exclusive benefits.\n\n1. Generous compensation and benefit package \n- Attractive salary\n- 20-day paid annual leave and 7-day paid sick leave\n- 13th month salary and Annual Performance Bonus\n- Premium healthcare for yourself and family members\n- Monthly allowance for team activities\n- Premium welcome kit and occasional gifts of appreciation\n- Extra benefits on your work anniversary\n\n2. Exciting career and development opportunities \n- Large scale products with modern technologies in banking domain\n- Clear roadmap for career advancement in both technical and leadership pathways\n- Access to digital learning platform such as Udemy\n- Consistent and high-quality leadership training through the Distinctive Leadership program (DLP)\n- Specialist capabilities and accreditations in key skill areas such as Cloud Engineering, Digital, Data, Security and SREs (Site reliability engineers)\n- Sponsored English course with native teachers\n- Opportunity for training in Australia\n\n3. Professional and engaging working environment \n- Hybrid working model and excellent work-life balance\n- State-of-the-art & modern Agile office\n- Food and beverages in the office pantry\n- Employee Assistance Program to improve your physical and mental health\n- Annual team activities and company events\n- A solid and talented team behind you – great people who love what they do\n\nA DIVERSE AND INCLUSIVE WORKPLACE WORKS BETTER FOR EVERYONE\nWe know that our people make us who we are. That\'s why we have built a culture of respect – where everyone feels valued and appreciated for being their true authentic selves at NAB. With our focus on inclusion and diversity, and in partnership with our Employee Resource Groups, NAB is a place where First Nations colleagues, colleagues of all genders, sexualities and ages, carers and colleagues with disability, and colleagues from all cultures, races and religions have the opportunity to thrive, connect and grow.\nWe are intent on providing an environment where you can work your way. Ask about our many flexible work options and please let us know if we can provide any adjustments throughout the recruitment process.\n\nCLOUD-FIRST \nNAB is undergoing an exciting "Cloud First" technology transformation by taking advantage of the latest tools and techniques used by leading technology and digital companies globally. But it’s not just about the Tech, we are also investing heavily in our people, so if you have an appetite to learn, grow and elevate others around you, this is the place for you!\n\nIf this excites you, let\'s have a chat over a cup of coffee!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1740, 976, 2, 'Senior Java Software Engineer', 'Responsibility\n- Designing and developing high-quality backend task.\n- Write unit test and run automation Postman script test for each API.\n- Working with the SM/PM by participating in project planning activities throughout the project\'s lifetime.\n- Write unit test and run automation Postman script test for each API.\n- Fix all compiler warnings & errors.\n- Contribute to performance optimization.\n- Participate in detail design and writing Java code base for new service.\n- Participate in system integration, testing, deployment and bug fixing.\n- Write clean, high‐quality, maintainable code with best development practices.\n- Maintaining high-quality projects and software design documentation.\n- Discussion with team members for cost-effective solution and perform peer-review\n- Have open-minded, ready to learn and share new techniques and technologies. We’re welcome to all your ideas and contribution to improve productivity\n\nQualifications\n- At least 3.5 years of experience in Java (8 or later), enterprise application development, concurrent programming.\n- Having knowledge or experience with NodeJS, Python, Kotlin, Go Lang is a plus.\n- Strong knowledge of object-orientated analysis and design (OOAD)\n- Have experience with at least 1 RDBMS (Oracle/Postgres/MySQL…), Message Broker, ESB, RESTful API development, Microservices.\n- Experienced in microservice architecture and RESTful API.\n- Experienced in Docker, K8S.\n- Familiar with microservice deployment using K8S.\n- Experienced in concurrency, asynchronous.\n- Good database knowledge, both SQL and non-SQL.\n- Have knowledge of AWS.\n- Ability to write readable and clean code.\n- Familiar with Postman test script to test API.\n- Familiar with GitLab/GitHub, Jira\n- Experienced with CI/CD.\n- Energetic and proactive, good teamwork.\n- Comfortable working with Agile methodology.\n- Logical thinking, enthusiasm, hard work, good pressure, responsible for assigned work.\n- Strong interpersonal, organizational, time management and problem-solving skills\n- Able to using English to communicate during working\n\nReasons You\'ll Enjoy Working Here\n- Annual leaves: 12 - 14 days\n- 13-month salary per year.\n- Performance checkpoint twice a year\n- Flexible, professional environment\n- Career path development support\n- During the Probation period, the targeted monthly income is equal to 100% of the targeted monthly income in the official employment period.\n- Friendly, young & dynamic working environment with many activities: birthday party, happy hours, company activities, company trips...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona capitalei Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1741, 977, 2, 'Full-stack Engineer (Mid/Senior)', 'About The Role\n\nWorking as a full stack developer at Elfie is far from just another job; it\'s the foundation of our whole development game plan. Your diverse skills, adaptability, and innovative spirit are key as we expand our health tech app on a global scale. This isn\'t just about churning out a product; we\'re leading a revolution in healthcare technology. If you\'re passionate and equipped with the comprehensive abilities of a full stack developer, then Efile is where you can genuinely make a mark on the world.\n\nWhat You Will Get\n\n🧳 Relocation Support - We handle the move, financially and practically\n💰 Permanent Global Contract - With a seriously competitive salary\n🏥 Private Healthcare - From day one\n💻 Top-Tier Tech Setup - Brand new MacBook + full onboarding kit\n🧠 Career Growth Framework - Clear, personalised, and fast-moving\n🎯 Bonus Scheme - Performance-related, quarterly paid\n🌴 14 Days PTO + Public Holidays - Real time off\n🧪 Hybrid Working - 3 days in the office per week\n🍛 Refreshments - Free Lunch and Dinner every day for you to enjoy\n\nWhat You’ll Do\n\nDevelop end-to-end solutions to concrete user-facing problems and requirements, leading design and implementation of software components, systems, and features.\nBuild, test, deploy, maintain, and improve software, specifically for mobile client and web applications, and covering both client and server implementations as well as third-party integrations.\nManage individual project priorities, deadlines, and deliverables.\nResolve challenging technical issues.\nCollaborate closely with teammates in engineering, product, design, and operations.\nHelp build a team and cultivate a culture of quality and innovation.\n\nWhat You’ll Need\n\nHave at least 5 years experience working as a Software Engineer\nMUST have experience with Typescript, Node.js and Vue.js (or willing to switch to Vue.js)\nMUST have knowledge of HTML(5), CSS(3), ES6\nExperience in Restful API, GraphQL, web-app tooling, testing & debugging.\nExperience with Google Cloud Platform and/or Amazon Web Services, and Docker containers is a plus.\nInterest and skill in UX for creating useful operational tools is a plus.\nBS degree in computer science or similar; graduate degree a plus.\nExperience working in a fast paced startup environment with quick iteration, continuous deployment, and test-driven development.\n\nWhy join Elfie\n\nWe\'re a global start-up that is mission-led, and fiercely product-driven.\n\nWe\'re building something that improves lives - and we\'re doing it with a culture of trust, freedom, and high performance.\n\nAbout Elfie\n\nElfie is the first completely free, gamified mobile app that rewards users for managing their health. Our goal? To become the world’s largest self-reported medical record platform — across all therapeutic areas.\n\nWe operate in 10+ countries today, with plans to expand into 15 by the end of 2025.\n\n📲 Try Elfie for yourself by downloading it on the App Store or Google Play\n\nWhat Now?\n\nApply today for immediate consideration! Got someone in mind? We offer a referral reward if your recommendation is hired. Contact Talent Acquisition for more info.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 1, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1742, 978, 2, 'Senior Full-Stack Developer - FinTech (Remote)', 'Location: Remote - SEA Region\nType: Full-Time Contractor\n\nAbout us: Automation Consulting Pty Ltd is an Australian-based AI and automation consultancy helping businesses streamline operations with smart, scalable solutions.\n\nAbout Our Client\nOur client is a dynamic Australian FinTech startup revolutionizing payments. Their innovative platform empowers businesses with cutting-edge payment solutions, enhancing efficiency while offering valuable rewards. Launched in 2019, they\'ve quickly become one of Australia\'s fastest growing fintech companies.\n\nRole Overview: We\'re seeking skilled and passionate full-stack developers to join our client\'s distributed team. This is a remote contract position based in Vietnam, working with an Australian development team.\n\n**IMPORTANT NOTE**: This role is specifically with our client (Australian FinTech) and NOT with Automation Consulting. The scope of work is focused on payment platform development and does NOT include any GenAI development work.\n\nTech Stack\n* Frontend: React, TypeScript, MaterialUI\n* Backend: Node.js, GraphQL, Express\n* Infrastructure: AWS, Terraform, Docker\n* Databases: PostgreSQL, MongoDB\n\nKey Responsibilities:\n• Design and implement scalable microservices\n• Build and maintain responsive web applications\n• Bug fixes and production support\n• Platform maintenance and feature enhancements\n• Mentor junior developers and provide technical guidance\n• Conduct code reviews and promote best practices\n• Collaboration with product and design teams\n\nRequirements:\n• 5+ years of full-stack web application experience or 5+ years in one or more of the key technologies\n• Strong proficiency in Node.js, TypeScript, and React\n• Experience with AWS cloud services and Terraform\n• Knowledge of PostgreSQL and/or MongoDB\n• Excellent problem-solving and analytical thinking skills\n• Strong English communication skills (both written and verbal)\n• Proven ability to work effectively in distributed teams\n• Strong organizational skills and attention to detail\n\nWhat We Offer:\n• Competitive salary.\n• Flexible working hours for work-life balance.\n• Partnership approach ("work with us, not for us").\n• Laptop provided for work purposes.\n• Contractors responsible for their own taxes and business expenses.\n• Collaborative and nurturing environment.\n• Knowledge sharing and skill enhancement opportunities.\n• Respectful and inclusive team culture.\n• Long-term opportunity with ongoing projects and growth potential.\n\nAdditional Information: This is a contract-based opportunity, not permanent employment.\n\nApplication Process\n1. Initial Interview (15 minutes)\n2. Technical interview with Engineering Team\n3. Technical Interview and Live Coding\n4. Cultural Fit Interview\n\nHow to Apply: If you’re ready to join a high-impact international team, please submit your resume and relevant project links to: support@automationconsulting.com.au.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1743, 849, 2, 'Solution Support Engineer-Business Technology Platform', 'We help the world run better\n\nAt SAP, we enable you to bring out your best. Our company culture is focused on collaboration and a shared passion to help the world run better. How? We focus every day on building the foundation for tomorrow and creating a workplace that embraces differences, values flexibility, and is aligned to our purpose-driven and future-focused work. We offer a highly collaborative, caring team environment with a strong focus on learning and development, recognition for your individual contributions, and a variety of benefit options for you to choose from.\n\nAbout SAP Labs Network And SAP Labs Vietnam\n\nSAP Labs Network is the global R&D setup where over 55,000 engineers around the world create, operate and support the most innovative enterprise solutions for SAP’s customers worldwide. SAP Labs Vietnam aims to become one of the key locations within the SAP Labs Network to support the engineering growth for SAP.\n\nMeet your team\n\nIf you’re searching for a diverse, multi-cultural team where you feel empowered, respected, and dedicated to your ideas and individual growth — you have come to the right place. Our team culture encourages and recognizes unique contributions and provides a fun, flexible, and inclusive work environment.\n\nThe new Technical Support Team at the SAP Vietnam/SAP Labs office in Ho Chi Minh City is critical to SAP\'s future success in the APAC region. We are looking for candidates who strive to make the world run better by delivering exceptional customer support and driving customer satisfaction.\n\nWhat You\'ll Do\n\nAs a BTP Solution Support Engineer, you will troubleshoot and solve customer issues reported through industry-leading channels within SAP Business Technology Platform (BTP). This includes engaging directly with customers, collaborating with development teams, using knowledge repositories, simulating problems, and working on customer systems to resolve complex issues. Your goal is to deliver a high-quality customer experience while developing deep technical expertise.\n\nKey Responsibilities\n• Investigate and resolve complex, real-world customer issues related to SAP BTP.\n• Provide technical problem-solving and debugging expertise.\n• Recommend technical solutions and develop workarounds where needed.\n• Properly document communications and actions for customer issues in SAP’s CRM system.\n• Use SAP and third-party tools to diagnose issues on customer systems.\n• Participate in shift work, including weekends, as scheduled.\n• Continuously learn and master SAP software used by industries, governments, and multinational companies.\n\nTechnologies Supported\n• UX/UI and mobile-based technologies\n• SAP FIORI\n• Gateway\n• Relational databases\n• Operating Systems\n\nWhat You Bring\n\nEducation and Experience:\n• University degree or college diploma in Computer Science, Information Technology, Software Engineering, Business Information Systems, Engineering, Science, or Mathematics preferred (but not required).\n• 2-5 years of experience in a technical role, preferably in Software support or Development.\n• Experience with an Enterprise Software company preferred.\n\nSkills And Competencies\n• Strong IT affinity and technical aptitude to troubleshoot customer issues effectively.\n• Excellent communication, collaboration, and customer service skills.\n• High proficiency in English (spoken and written).\n• Programming skills preferred.\n• Strong analytical and problem-solving abilities.\n• Open and professional communication style.\n• Strong team player who learns and adapts quickly.\n• Customer-centric mindset with a passion for delivering high-quality solutions.\n• Ability to thrive in a fast-paced, changing environment with a cloud-first mindset.\n\nCareer Development and Growth\n\nSAP is committed to supporting your professional growth and development:\n\n• Career Progression: SAP provides the tools and resources to help employees grow in their careers.\n• Training: A structured development plan combining on-the-job learning and formal training ensures continuous skill development.\n• Global Exposure: Collaborate with global teams and gain exposure to diverse industries and customer environments.\n\n#SAPLabsVietnamCareers\n\nBring out your best\n\nSAP innovations help more than four hundred thousand customers worldwide work together more efficiently and use business insight more effectively. Originally known for leadership in enterprise resource planning (ERP) software, SAP has evolved to become a market leader in end-to-end business application software and related services for database, analytics, intelligent technologies, and experience management. As a cloud company with two hundred million users and more than one hundred thousand employees worldwide, we are purpose-driven and future-focused, with a highly collaborative team ethic and commitment to personal development. Whether connecting global industries, people, or platforms, we help ensure every challenge gets the solution it deserves. At SAP, you can bring out your best.\n\nWe win with inclusion\n\nSAP’s culture of inclusion, focus on health and well-being, and flexible working models help ensure that everyone – regardless of background – feels included and can run at their best. At SAP, we believe we are made stronger by the unique capabilities and qualities that each person brings to our company, and we invest in our employees to inspire confidence and help everyone realize their full potential. We ultimately believe in unleashing all talent and creating a better and more equitable world.\n\nSAP is proud to be an equal opportunity workplace and is an affirmative action employer. We are committed to the values of Equal Employment Opportunity and provide accessibility accommodations to applicants with physical and/or mental disabilities. If you are interested in applying for employment with SAP and are in need of accommodation or special assistance to navigate our website or to complete your application, please send an e-mail with your request to Recruiting Operations Team: Careers@sap.com\n\nFor SAP employees: Only permanent roles are eligible for the SAP Employee Referral Program, according to the eligibility rules set in the SAP Referral Policy. Specific conditions may apply for roles in Vocational Training.\n\nEOE AA M/F/Vet/Disability\n\nQualified applicants will receive consideration for employment without regard to their age, race, religion, national origin, ethnicity, age, gender (including pregnancy, childbirth, et al), sexual orientation, gender identity or expression, protected veteran status, or disability.\n\nSuccessful candidates might be required to undergo a background verification with an external vendor.\n\nRequisition ID: 425757 | Work Area: Customer Service and Support | Expected Travel: 0 - 10% | Career Status: Professional | Employment Type: Regular Full Time | Additional Locations: .', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Ho-Chi-Minh-Stadt', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1744, 490, 2, 'Ruby on Rails Developer', 'Are you looking for an opportunity to make an impact, grow your skills and catapult your career with a growing company?\n\nMealSuite is looking for Backend Developers to join our development team on our mission to revolutionize the continuum of care through our all-in-one foodservice management technology.\n\nOur International Development team\'s mission is to build innovative solutions that help our customers in senior living and healthcare industries enhance the mealtime experience for their patients and residents. In an industry that is constantly evolving, MealSuite\'s software comes with a promise for continual innovation and growth with our customers. We never stop pushing boundaries and are always steering the future of our industries as innovation leaders in our space.\n\nAs part of our Development team, your mission is to stay on top of the latest releases, contribute to projects, and deliver the best quality solutions for our customers.\n\nYou will:\n\n• Design and develop new features for our best in class foodservice management software\n• Design, build and maintain efficient, reusable, and reliable Ruby code\n• Analyze client requirements to develop functional and technical software requirements\n• Maintain and troubleshoot existing application\n• Collaborates with development, QA, product and customer support teams all over the world\n• Supervise and support other junior developers in fulfilling tasks as well as improving their skills\n• Present new and innovative ideas\n• Helping team members with a collaborative spirit\n• Contributes to maintaining an open, friendly and innovative working environment for every member\n\nRequirements\n\n4+ years of overall software development experiences using Ruby and Rails framework:\n\n• Strong insight into Ruby syntax and its nuances\n• A knack for writing clean, readable Ruby code\n• Experience consuming and designing RESTful APIs\n• Solid SQL / relational database experience (Postgres is a plus)\n• Experience working with Redis and Sidekiq\n• Experience with version control (Git, GitHub)\n• Solid understanding of object-oriented programming\n• Understanding of Agile development and Scrum practices\n• A passion for helping people with a collaborative spirit\n• Ability to work as part of a team, understand the problems of other team members, and when necessary, go above and beyond the job description to work towards a broader team goal\n\nBenefits\n\n• Stock option\n• Vietnam labor law contract with full benefits\n• 1 day work remote every week\n• 18+ days annual leave\n• 100% probation salary\n• Unlimited access to online learning courses such as Udemy\n• Macbook pro provided\n• Free snacks & beverages\n• Flexible working time\n• Team events\n• Awesome and meaningful products', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1745, 979, 2, 'Senior Frontend Developer', 'About GRVT\n\nGRVT (pronounced “gravity”) is the world’s first licensed onchain exchange, where traditional banking meets decentralized innovation on one regulated, compliant, and trustless financial market place. A blockchain-based platform that is democratizing how wealth is created and shared, GRVT allows everyday people to trade, invest, and grow their wealth by providing direct access to top industry traders and investors.\n\nKey Stats\nTeam size: 50+ and growing\nSeed round funding: $14.3 million\nUsers: 40,000+ KYCed users, unprecedented for DEXs\n50+ institutional clients onboarded\n$1.2 billion monthly trading volume and growing, since launch\n\nIf you’re passionate about meaningful innovation and ready to shape the future of finance, GRVT offers the opportunity to work at the forefront of financial evolution. Join us and be part of redefining what’s possible.\n\n🔗 Website: www.grvt.io\n(https://www.grvt.io/)\n\n📄 Brochure: View Brochure\n(https://docsend.com/view/f2bd79j6xc8nkypr)\n----------------------------------------\nJob Responsibilities\nBuilding and maintaining responsive web applications using technologies like React, Next.js, Sass, and TypeScript.\nCollaborate with UX/UI designers to implement design specifications and ensure a consistent look and feel across applications.\nOptimize applications for maximum speed and scalability.\nWriting clear, organized, and effective code that follows best practices.\nTroubleshoot and debug applications to ensure optimal performance.\nKeeping up-to-date with new technologies and industry advancements to improve our development.\n\nSkills Requirement\nA Bachelor\'s degree in a relevant field like Computer Science or Software Engineering.\n2 to 4 years of experience in front-end development.\nStrong skills in React and a solid understanding of HTML, CSS, and JavaScript.\nExperience with responsive design and cross-browser compatibility.\nExperience using version control systems like Git.\n\nGood to Have\nExperience in the blockchain or related industries (not required).\nFamiliarity with Axios, GraphQL, WebSocket, RxJS, and TradingView is an advantage.\n\nSoft Skills\nExcellent communication and collaboration abilities.\nStrong ability to solve problems and pay attention to detail.\nAdaptability and willingness to learn new technologies and tools.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'APAC', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1746, 732, 2, 'Python Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nTechnologists at WorldQuant research, design, code, test and deploy projects while working collaboratively with researchers. Our environment is relaxed yet intellectually driven. We seek people who think in code and are motivated by being around like-minded people.\n\nWhat You’ll Do\n\nParticipate in designing distributed system architecture for systems and services.\nParticipate in development and maintenance of backend services in Python\nParticipate in development and maintenance of services to work with third parties such as: Spark, Kafka, Airflow, Kubernetes, etc...\nParticipate in development and maintenance of monitoring services using Prometheus, Grafana Sentry, Alerta, etc.\nCoordinate with stake holders such as pure infrastructure team, business team, etc... to resolve crossing issues.\n\nWhat You’ll Bring\n\nBachelor’s degree in computer science or related discipline or equivalent job experience\n2+ years of hands-on industry experience developing scalable and robust software applications in web environments with exposure to backend stacks\nStrong understanding of data structures, algorithms, Object Oriented Programming and Model-View-Controller web framework\nWorking knowledge of Unix/Linux environment\nExperience with microservices, caching tools, data visualization, queuing systems or large-scale distributed systems is great plus\nExperience with Spark, Kafka, K8s is also desirable\nExcellent debugging and problem-solving skills\nExcellent interpersonal skills\nFluent in spoken and written English.\n\nWhat We Offer\n\nCompetitive and attractive compensation package with clear career road-map – where you feel challenged everyday\nWe offer a strong culture of learning and development: training courses, library, speakers, share and learn events\nLearn from who sits next to you! Working in WQ you are surrounded by smart and talented people\nEmployee resources groups with strong diversity and inclusion culture\nPremium Health Insurance and Employee Assistance Program\nGenerous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\nTeam building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\nAnnual company trip and occasional global conferences – opportunity to travel and connect with our global teams\nHappy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1747, 878, 2, 'Senior Full Stack Developer (HCMC/ Da Nang, Hybrid) (Visa and Relocation Package Provided)', 'About Nimble\n\nWe solve our client\'s most difficult business challenges through technology. Our company partners with the most ambitious companies around the world creating long-term impact with the work with do. If you want to grow together, work on challenging products and enjoy using the best tools and practices, Nimble is the right place for you!\n\nOur Core Values\n\nOwnership mentality: Treat our company and our clients’ business as ours taking care of the collective interests. This, in the end, translates to personal interests achievement through our company.\nDependable & Resilient: We go to great lengths for our clients, they can rely on us to deliver and all our team members are reliable and trustworthy and we don’t give up when we face challenges.\nObsession for Excellence: Our delivery quality has no parallel.\nCourage: We must have the courage to speak up, raise our concerns in a timely manner and be able to confront the status quo with ideas by being constructive and without holding on to hard feelings.\n\nWhat You Will Do\n\nYou will be an active member or lead a team of developers in a project squad. We have a wide range of project sizes.\nDecide which technologies are going to be used for front-end, back-end and define the overall architecture.\nWork closely with the Product Owner to make sure the backlog is efficiently planned and occasionally assist in technical discussions with clients. Most of the client interfacing is done by the Product Owner.\nWrite clean, composable, and maintainable code as you develop world-class products for our clients.\nWrite automated tests to build and maintain the product we build for our clients.\nDo code reviews with your squad members.\nLearn new technologies languages like Ruby, Go, or Elixir, and techniques so that you are able to adapt to the evolving needs of our clients.\nKnowledge sharing through team rituals.\nCollaborate with other team members to define the internal processes and initiatives to help the company accomplish its mission. Our handbook has been written by the whole team.\n\nRequirements\n\nProfessional web development with 5+ years of experience. Experience in Ruby, JavaScript, Go is ideal (at least one of them).\nComfortable working both on frontend and backend.\nAt least basic experience with a modern JavaScript framework like ReactJS/Redux, VueJS or AngularJS.\nExperience in writing automated tests for web applications.\nEnjoy working on challenging solutions and systems.\nBelieve that building great applications is not only about delivering code that “works”, but involves thinking about reusability, maintainability, security, and performance.\nA "Can do attitude" and a product mindset.\nConfidence in communicating in English.\n\nWhy You\'ll Love Working Here\n\nYou’ll feel proud of every product we ship. We care deeply about quality, design, and doing things right—our name stands for excellence.\nYou’ll be surrounded by high performers. We’re a tight-knit, ambitious team that pushes each other to grow and thrive.\nWe\'re built differently. We’ve been profitable and bootstrapped since day one—no VC pressures, just smart, sustainable growth.\nWe take pride in craftsmanship. Whether it\'s code, design, or delivery, we hold ourselves to a high bar—because the little things shape the big picture.\nProcess with purpose. We follow agile principles not just in theory, but in practice. Our engineers work with clearly defined user stories, estimate using story points, and deliver iteratively in focused 1–2 week sprints.\nGrowth is part of the job. Through regular one-on-ones, structured feedback, and a clear leveling framework, we support every team member’s growth—not just in technical skills, but in communication, collaboration, and leadership.\nLearning never stops. Access a vast library of resources like Pluralsight, PragPub, Leanpub, e-books, and more—plus a yearly education allowance to help you level up in any direction you choose.\nWe’ve got your back. From day one, you’ll get private medical insurance, social welfare coverage, and a company care fund.\nWe support your move. If you\'re joining us from abroad, we’ll take care of your visa, work permit, and provide a relocation package to help you settle in smoothly.\nFlexibility that fits. We support a hybrid workstyle, giving you the freedom to find the right rhythm between home and office life.\nWork with the right tools. We’ll set you up with a MacBook and a large external monitor so you can work comfortably and efficiently.\nA workspace that works for you with our modern office in the heart of Ho Chi Minh City and Da Nang.\nStay fueled. Our kitchen is always stocked with drinks and snacks.\nTake the time you need. Enjoy 26 days of paid leave a year (including public holidays), plus a sabbatical month every 3 years.\nCelebrate your journey. From anniversary gifts to yearly company outings and spontaneous team activities, we make time for fun and appreciation.\n...and more perks to make work feel better.\n\nIf you are a passionate web professional looking to make a significant impact in a growing software development company, we would love to hear from you.\nJoin us in shaping the future with with elevating web innovation!\n\nWe keep our recruitment process practical and straightforward.\nTo learn more about how we work, check our handbook named Compass, Github organization, and Medium account.\nWant to see what we have built? Check our Dribbble and Behance accounts.\nWant to keep in touch with us? Follow us on Facebook, Instagram, and LinkedIn.\nNimble is an equal opportunity employer.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1748, 980, 2, 'Senior Frontend Engineer', 'Here at Skedulo we’re on a mission to support the 2.7 billion people in the world—and the companies that employ them—who do not work at a desk every day. Our global teams are collaborative, ambitious, innovative, and passionate about helping our customers realize their fullest potential by enabling their mobile workforces.\n\nThe Skedulo team is a tight-knit group of builders who are passionate about shaping our platform that is relied upon daily by thousands of users across the globe. We are looking for motivated, self-starters who share our values, challenge the status quo, and push the pace of innovation in order to accelerate growth. If you’re drawn to solving hard problems and want to help design software that will make a difference in people’s lives, Skedulo is for you. Visit our website to learn more about what Skedulo does and to learn more about our people and team.\n\nDescription\n\nThe Senior Frontend Engineer will be a key member of the Solution Engineering team in VN. Engineers display a solid understanding of core engineering concepts. They are focused on growing as an engineer, learning the team’s tools and current processes, as well as a strong background in Engineering best-practices like automated testing, source control, and agile planning.\n\nThey communicate well and are capable of delivering feedback to peers and their manager. When given a task with unclear requirements they know how to ask for clarification, and ensure that all assumptions are vetted before work starts to reduce the need for re-work. They understand how their work fits into the larger picture for their team, and use this to identify conflicting requirements to their team lead and project manager. Senior Frontend Engineer also works with the FE team to share best practices and provide support/guidance to junior members.\n\nResponsibilities\n\nDay to Day\n\nWork on projects with high complexity, large or strategic projects.\nWriting and reviewing code from the sprint backlog inline with front-end team best practices.\nAssisting in driving team sprint execution to ensure timelines are met without compromising on quality.\nAnticipates and communicates blockers or delays for their work (or their squads) before they require escalation.\n\nTechnical Duties\n\nConsistently writes production-ready code that is easily testable, easily understood by other engineers, and accounts for edge cases and errors.\nProvides technical advice and weighs in on technical discussions / decisions that impact their team.\nEnsures their commitments are realistic, understands their priority and urgency, and delivers upon them accordingly.\n\nCommunication & Leadership Duties\n\nCommunicate within your team in an effective, clear, concise manner in both written and verbal form on technical and non technical subjects.\nHelps their fellow team members overcome obstacles, resolve blockers, and complete work tasks.\nMentors more junior teammates in an open, respectful, flexible, and empathetic manner.\nResolving code-based defects discovering either through project work or through our technical support team.\nContributing to continual improvement of coding standards and methods used by our technical development team.\nContributing to technical documentation such as technical design and as built documents.\n\nMinimum Qualifications\n\nMust have at least 5+ years of commercial experience in Front-end web development.\nExperienced in Front end unit testing frameworks (ideally Mocha or Jest).\nExperienced in CSS Preprocessors (ideally Sass).\nMust have strong written and oral English language communication skills.\n\nDesired Skills & Experience\n\nWill have at least 3+ years’ experience developing web applications with ReactJS.\nIdeally experienced with one or more of the following: Vuejs, AngularJs.\nStrong experience in modern front-end build tools (e.g. Git, Webpack, Yarn, NPM).\nFamiliar with RESTful API, GraphQL.\nKnowledgeable in modern authorization mechanisms, such as JSON Web Token.\nBeneficial to have prior experience working with offshore and distributed teams.\nExposure to Agile development methodologies such as Scrum and Kanban.\nPrior experience with common cross functional tools in JIRA, Confluence, GitHub.\nUnderstands the importance of contributing to the CI/CD pipeline and automation.\n\nAdditional Requirements\n\nMust be authorized to work without visa sponsorship in Vietnam to be considered for this position.\nMust be willing to work in the Ho Chi Minh office at least 3 days per week (Hybrid); and reside within 35 miles of HCM.\n\nBenefits\n\nCompetitive Salary Package including 13th month bonus.\nNew Hire Stock Options.\nEmployee Referral Bonus Program.\n3 volunteer days per year.\n100% employer paid subscription to Modern Health (includes 6 coaching & 6 therapy session per year).\nA generous budget to spend on setting up your home office or WFH station.\n100% employer paid access to Udemy (Learning & Development).\nPaid Parental Leave for both carers (12 weeks).\nHybrid Work Model (3 days in the office & 2 days work from home).\nPrivate Medical Benefits (PTI Health Insurance) for employee + family.\n100% employer paid annual health check.\n7 paid sick leave days per year.\n20 paid personal leave days per year.\n12 paid public holiday days per year.\nCompany & Team Offsite Events provided.\nOur office offers open and creative workspaces with room to play, reflect, and relax.\nOur team works hard but also plays hard; we will challenge your best table tennis and PS4 skills.\nKitchen stocked with snacks & drinks.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 3, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1749, 880, 2, 'Freelance Software Developer (Python) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\nGenerate prompts that challenge AI\nDefine comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\nCorrect the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\nYou have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\nYou have at least 3 years of professional experience with Python\nCode review experience is a must\nExperience with AI projects is a plus\nYour level of English is advanced (C1) or above\nYou are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\nOur freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\nTake part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\nWork on advanced AI projects and gain valuable experience that enhances your portfolio\nInfluence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1750, 808, 2, 'Junior Software Developer - Hanoi', 'Job Description\n\nSupport senior developers and team lead to build features according to business requirements.\nWrite design documents.\nFix bugs and build feature changes as required.\nMonitor code performance and support senior developers/ team lead to optimize performance.\n\nRequirements\n\nCollege or university graduated, major in computer science or IT or equivalent.\nAt least 1 year of experience in the applying position.\nKnowledge of object-oriented programming and .NET (C#)\nProficient in using Visual Studio or Microsoft technology, HTML5, CSS3, JavaScript is an advantage.\nGood learning and research abilities\nHaving a sense of responsibility, persistence\nAble to work independently and in a team.\nBasic spoken and written English. (Good at Chinese is a big plus)\n\nWork Location\n\nArtemis, floor 4, No. 3 Le Trong Tan, Thanh Xuan, Ha Noi\n\nBenefits\n\n5-day workweek\nYoung & vibrant working environment with great career development opportunities\nSocial insurance, medical insurance, unemployment insurance, are based on actual salary\nYearly performance bonus (up to 2 months’ salary)\nRegular team building events & internal activities (weekly happy hour, quarterly team building events, festival parties, etc.)\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1751, 822, 2, 'Java/Kotlin Engineer (Senior/Principal_Banking Project)', 'Who we are?\nMoney Forward is embarking on an exciting new venture in collaboration with Sumitomo Mitsui Financial Group and Sumitomo Mitsui Banking Corporation to explore the provision of BaaS (Banking as a Service) and digital banking solutions. We are seeking a talented Backend Engineer to join our core banking team, which will be at the heart of this initiative.\n\nResponsibilities and Duties\nAs a Software Engineer in the Core Banking Team, you will leverage Mambu, a leading cloud banking platform for neobanks and challenger banks, to build one of the most reliable and agile banking systems in the industry. Our goal is to shape the future of digital banking in Japan, making it more accessible and user-friendly than ever before.\n\nAcquire domain knowledge in digital banking, including deposits, loans, clearing and settlement, basic accounting, domestic exchange, and Zengin network.\nActively engage with product owners to define requirements.\nDevelop, test, and deploy code that meets non-functional quality gates such as static code analysis, software composition analysis, SAST, and DAST, while maintaining numerical accuracy.\nDesign and build high-performance, scalable microservices centered around APIs.\nPursue test automation and continuous improvement, including API testing.\nTake responsibility for the entire software development lifecycle.\n\nMust have:\nApproximately 5 years of hands-on experience with Java or Kotlin and Spring Boot.\nPractical experience with SQL, Apache Kafka, and related technologies.\nExperience in creating and automating tests.\nHands-on experience with relational/non-relational databases, including transaction management, query optimization, and schema design.\nExperience in microservice architecture and API design with a focus on scalability, maintainability, and supportability.\nProven experience in development with sufficient domain knowledge (not necessarily in the financial industry).\nUnderstanding of CI/CD concepts and practices.\nExperience developing cloud-native applications in major cloud environments such as AWS, Azure, or GCP.\nBachelor\'s or Master\'s degree in Computer Science or a related field, or equivalent practical experience.\n\nNice to have:\nExperience working in financial institutions, particularly banks or fintech companies.\nBasic knowledge of accounting or double-entry bookkeeping.\nKnowledge of CCP and settlement mechanisms.\nExperience implementing CI/CD pipelines from development to production in the cloud.\nExperience in AI development and/or experience in using AI tools to improve development processes.\nMoney Forward recently announced our AI Strategy roadmap which focuses on improving AI-driven operational efficiencies, as well as integrating AI agents into our products to deliver better value to our users. (More information )\n\nLanguage Requirements:\nEnglish: Business level (TOEIC score of 700 or above)\n\nWho We’re Looking For\nAbility to quickly adapt to changing priorities and situations.\nA critical thinker who questions the status quo.\nExcellent communication skills with the ability to articulate ideas clearly.\nWillingness to learn necessary domain knowledge and technologies.\nUnderstanding of DevOps/DevSecOps.\n\nTechnology Stack and Tools Used\nKotlin, Spring Boot, Gradle, jOOQ, Liquibase, Kotest/JUnit, Karate/Rest Assured\nRedis, MySQL\nDocker, AWS ECS\nApache Kafka (AWS MSK)\nMambu cloud banking platform\nGitHub, Backstage, Amazon ECR\nGitHub Actions, ArgoCD, Sonar Cloud, Detekt, AeyeScan\nChatGPT, Copilot, Gemni', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City i okolice', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1752, 690, 2, 'System Administrator & AI Workflow Engineer', 'We are seeking a proactive System Administrator/ Operation Engineer to operate and support our AI (X-Ops) System and Gen AI projects. This role involves providing technical support to both internal users and clients, ensuring the reliability and smooth operation of AI-driven systems. You will monitor system performance using specialized tools and assist end users with technical issues related to AI.\n\nKey Responsibilities:\n\n- Operate and maintain AI (X-Ops) systems and Gen AI projects.\n- Provide technical support to internal users and external clients, addressing system-related inquiries and issues.\n- Monitor system health and performance using monitoring tools; proactively identify and resolve potential problems.\n- Collaborate with cross-functional teams to ensure system availability and optimal performance.\n- Assist users in navigating AI workflows and resolving access or functionality challenges.\n- Document technical procedures, incidents, and resolutions to maintain knowledge base.\n- Support deployment and continuous improvement of AI systems and workflows.\n\nKey Qualifications:\n\n- Up to 2 years of experience in system administration, technical support, or related IT roles.\n- Experience with system monitoring tools and troubleshooting.\n- Basic understanding or strong interest in AI technologies and workflows.\n- Excellent problem-solving skills and ability to communicate effectively with technical and non-technical users.\n- Experience supporting both internal users and external clients is a plus.\n- Ability to work independently and collaboratively in a fast-paced environment.\n\nWhy You Should Join:\n\n- Shape the internal infrastructure of a modern tech organization\n- Combine operations with AI innovation in a highly agile team\n- Work closely with business, technical, and product leadership\n- Lead initiatives that scale knowledge, reduce noise, and enable transparency\n\nApply now!\n\nDue to the high volume of applicants, only shortlisted candidates will be contacted. We apologize for this inconvenience!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 3, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1753, 674, 2, 'Thực tập sinh Phát triển Mã Coin (Blockchain Developer Intern)', 'Mô tả công việc\n\n- Tham gia vào quá trình thiết kế và phát triển mã coin/token trên các nền tảng blockchain phổ biến như Ethereum (ERC-20), BNB Chain (BEP-20), Solana, hoặc các blockchain khác.\n- Viết và triển khai smart contract bằng Solidity (hoặc các ngôn ngữ phù hợp khác).\n- Hỗ trợ kiểm thử, mô phỏng và tối ưu hóa mã nguồn smart contract.\n- Làm việc cùng các thành viên trong team để phát triển tính năng cho dự án như ví điện tử, DApp, staking, v.v.\n- Nghiên cứu và áp dụng các xu hướng công nghệ mới trong lĩnh vực blockchain, DeFi, Web3\n\nYêu cầu công việc\n\n- Sinh viên năm cuối hoặc mới tốt nghiệp các ngành CNTT, Khoa học Máy tính, hoặc liên quan.\n- Có kiến thức cơ bản về blockchain và smart contract.\n- Biết lập trình một trong các ngôn ngữ: Solidity, JavaScript/TypeScript, Python là lợi thế.\n- Tư duy logic tốt, ham học hỏi, có khả năng tự nghiên cứu.\n- Ưu tiên đã từng thử viết token đơn giản (ERC-20 hoặc tương đương).\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Hỗ trợ dấu mộc xác nhận thực tập, báo cáo thực tập, bài luận văn, chuyên đề, đồ án tốt nghiệp.\n- Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình.\n- Có nhân viên công ty hướng dẫn training trực tiếp truyền đạt kinh nghiệm khi làm việc thực tiễn, được áp dụng kiến thức học tại trường vào các dự án thực tế của công ty.\n- Nâng cao hồ sơ profile công việc, khi hoàn thành thực tập sẽ được công ty hỗ trợ làm người references cho TTS sau khi đi tìm việc ở các công ty khác. Làm việc được trải nghiệm trực tiếp với các lãnh đạo cấp cao của các công ty hàng tỷ đô la trên toàn cầu.\n- Thời gian làm việc linh động, không gò bó, không ép buộc, không deadline, nghỉ lễ, tết đầy đủ theo quy định nhà nước và luật lao động.\n- Hiện chưa có chính sách hỗ trợ phụ cấp thực tập.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quoc Tuan Commune, Hai Phong City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1754, 189, 2, 'Mobile Developer (Android - iOS)', 'Position Summary\n\nRole and Responsibilities\n\nJOB RESPONSIBILITIES: \n\n• Measure and maximize product quality while keeping the milestone timelines intact.\n• Should be able to narrow down the problem based on the analysis of the logs and code.\n• Ability to define a problem with well-defined scope.\n• Requirement gathering and analysis.\n• Work closely with R&D team W/W for timely completion of feature development and ensure smooth delivery to market on time.\n• Handling Market Support queries and drive critical market issues along with technical and support teams.\n• National and abroad traveling involved time to time.\n\nFOR iOS DEVELOPER\n\n• Development of App on iOS \n• Development and Maintenance of Application for iOS platform\n\nFOR ANDROID DEVELOPER\n\n• Development of App on Android OS \n• Development and Maintenance of Application for Android\n\nSkills And Qualifications\n\nGeneral requirement:\n\n• Bachelor’s degree in computer science, S/W Engineering or IT related field.\n• At least 1 years of experience in software development.\n• Good in English communication for working.\n• Mastery in problem analysis, problem resolution.\n• Fast learning skills and mindset required to quickly understand new technologies and new modules in product.\n• Ability to multi-task and manage tasks with varying priorities.\n• Tech-savvy and passionate about building products.\n• Proactive at work.\n\nFOR iOS DEVELOPER\n\nTechnical Requirement:\n\n(Mandatory)\n\n• Knowledge in Native Application on iOS, open to work with Kotlin Multiple Platform\n• Familiar with Xcode\n• Understand in Canvas on iOS, ability to make custom UI base on Canvas.\n• Knowledge in App on Samsung Galaxy Framework (One UI) or Material UI\n• Knowledge in Socket connection and BLE.\n• Knowledge & Experience of software design, development, software architect.\n\n(Optional)\n\n• Knowledge in Design Patterns.\n• Understand mobile lifecycle.\n• Familiar with Dependency Injection, Image loader libraries.\n• Ability to write unit test case, UI test case.\n• Ability to work with Canvas to create custom Image editor is a big plus.\n• Familiar with Algorithm or have high level on Coding challenge platform like Leet code, Hacker Rank is a big plus\n\nFOR ANDROID DEVELOPER\n\nTechnical Requirement:\n\n(Mandatory)\n\n• Knowledge in Native Application on Android OS and Kotlin Multiple Platform\n• Familiar with Jetpack Compose\n• Understand in Canvas on Android, ability to make custom UI base on Canvas.\n• Knowledge in App on Samsung Galaxy Framework (One UI) or Material UI\n• Knowledge in Socket connection and BLE. \n• Knowledge & Experience of software design, development, software architect. \n\n(Optional)\n\n• Knowledge in Design Patterns.\n• Understand mobile lifecycle.\n• Familiar with RoomDB, Hilt, Koin, Coin, Ktor libraries.\n• Ability to write unit test case, UI test case.\n• Ability to work with Canvas to create custom Image editor is a big plus. \n• Familiar with Algorithm or have high level on Coding challenge platform like Leet Code, Hacker Rank is a big plus.\n• Please visit Samsung membership to see Privacy Policy, which defaults according to your location. You can change Country/Language at the bottom of the page. If you are European Economic Resident, please click here.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1755, 981, 2, 'Information Technology Engineer', 'Company Description\nWe suggest you enter details here.\nRole Description\nThis is a full-time on-site role for an Information Technology Engineer located in Quận 6. The IT Engineer will be responsible for troubleshooting, providing technical support, ensuring network security, and managing networking systems.\nQualifications\n- Troubleshooting and Technical Support skills\n- Knowledge of Information Technology and Network Security\n- Experience in Networking\n- Strong problem-solving abilities and attention to detail\n- Excellent communication and teamwork skills\n- Relevant certifications such as CCNA, CompTIA, or CISSP\n- Bachelor\'s degree in Computer Science, Information Technology, or related field', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 Quận 6', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1756, 904, 2, '.Net Software DEVELOPER (SCE)', 'MiTek® is a global provider of building solutions for the residential and commercial construction industries. Utilizing software, services, engineered products, and automated manufacturing equipment, MiTek partners with clients to accelerate their genius and deliver breakthroughs in building. With a rich 60-year history and a network of 6,500 team members worldwide, MiTek pairs local expertise with global capabilities. As a Berkshire Hathaway (NYSE: BRK-A, NYSE: BRK-B) company since 2001, MiTek has a record of continuous growth and innovation. Learn more at www.mii.com. A Brief Overview Kỹ sư Phần mềm là một vị trí với nhiệm vụ bao gồm tham gia vào toàn bộ chu trình phát triển phần mềm của từng dự án hoặc sản phẩm mà mình phụ trách. Báo cáo trực tiếp cho Quản Lý Bộ Phận, Kỹ Sư Phần Mềm phải đảm bảo cung cấp dịch vụ hiệu quả và nhanh chóng nhằm đáp ứng nhu cầu và kì vọng của khách hàng và tiếp tục phát triển cùng các thành viên trong nhóm. Software Engineer is a role which involves participating in the full software development lifecycle for each project or product you are assigned. Reporting to the Manager, the Software Engineer must ensure a smooth efficient service that meets the expectations and needs of our customers and continues to grow & develop our staff. Responsibilities What You Will Do: Áp dụng các giải pháp kỹ thuật phần mềm tốt nhất nhằm đảm bảo chất lượng sản phẩm phần mềm và xây dựng một môi trường phần mềm tối ưu Theo dõi, phân tích và hoàn thiện quá trình phát triển phần mềm hiện tại, đồng thời hỗ trợ xác định phương án cải thiện phù hợp Liên lạc và tương tác với các thành viên trong nhóm nhằm đảm bảo sự tiến bộ liên tục; Trao đổi với tất cả khách hàng và các cổ đông khác nhằm cung cấp được dịch vụ chất lượng cao nhất có thể Chủ động và tích cực tham gia với tư cách là một thành viên nhóm Phát Triển Phần Mềm MiTek Vietnam, đoàn kết hướng đến mục tiêu trở thành một tổ chức vững mạnh Tham gia hỗ trợ các công việc hằng ngày của nhóm Thiết kế, lập trình, kiểm tra và gỡ rối, sử dụng công nghệ, công cụ phát triển và ngôn ngữ lập trình theo yêu cầu của dự án Cộng tác với Quản Lý Sản Phẩm, Quản Lý Chất Lượng, DevOps, Kiến Trúc Sư phần mềm và các nhóm chức năng khác trong dự án (Ví dụ: Customer experience, Sales, Marketing), để đảm bảo rằng các giải pháp hiệu quả, nhất quán và đáp ứng nhu cầu kinh doanh Làm việc trong môi trường phát triển phần mềm Agile (ví dụ: Scrum, Kanban), tham gia các cuộc họp cam kết, hồi cứu và lập kế hoạch Chuyên cần trong giờ làm việc bình thường và ngoài giờ theo yêu cầu Tham gia đánh giá các yêu cầu phần mềm Tái cấu trúc sản phẩm hiện tại Áp dụng các tiêu chuẩn phát triển sảm phẩm và đảm bảo chất lượng để đảm bảo thao tác logic và dữ liệu chương trình hiệu quả Tham gia vào quy trình thiết kế và kiểm tra thiết kế Có khả năng tự thiết kế các giải pháp chất lượng cho các tính năng nhỏ và trung bình Tiếp tục xây dựng gia đình MiTek Vietnam thông qua việc hỗ trợ khách hàng và đảm bảo cung cấp cho tất cả khách hàng dịch vụ chất lượng cao nhất Các công việc khác theo sự phân công Implement software engineering best practices to ensure the quality creation of software, and create an environment of software excellence Monitoring, analyzing and improving the current development process – and help determine appropriate strategies for positive improvement Liaising and interacting with all team members to ensure continuous improvement Communicating with all customers and other stakeholders to the highest level of quality applicable Positively and proactively participate as a member of the MiTek Vietnam Software Center, united in the pursuit of operational excellence Participate in daily activities to support the Team Design, code, test, and debug software, utilizing technologies, development tools and languages as required for the project assigned Collaborate with Product Management, Software Quality Assurance, DevOps, Architecture, and other functional teams (e.g. Customer experience, Sales, Marketing), to ensure that solutions are efficient, consistent and fulfill business needs Work in an Agile software development environment (e.g. Scrum, Kanban), participating in commitment, retrospective and planning meetings Attendance during regular work hours and overtime as required Participate in requirements reviews Refactor existing software Apply generally accepted development and quality assurance standards and techniques to assure efficient program logic and data manipulation Participate in design and design reviews Able to independently design quality solutions for small to medium features Continue to grow the MiTek Vietnam family by supporting the customers and ensuring the highest level of service is provided to all customers. Other reasonable duties as assigned Qualifications Tốt nghiệp Đại học hoặc Cao đẳng, ưu tiên chuyên ngành Khoa học máy tính hoặc Kỹ sư máy tính Có hơn 2 năm kinh nghiệm trong lĩnh vực phần mềm hoặc các lĩnh vực liên quan với kiến thức sơ lược về các quy trình và giải pháp phát triển toàn cầu. Trình độ tiếng Anh (CEFR) B1+ hoặc tương đương Có kiến thức và kinh nghiệm vững chắc về phát triển phần mềm, sử dụng các công nghệ cho dự án được giao và nhất quán với nhóm, điển hình bao gồm sử dụng các mẫu thiết kế, Thiết kế hướng đối tượng, C#, .NET Framework, Cơ sở dữ liệu SQL, C, C++ cũng như các công cụ và ngôn ngữ phát triển khác theo yêu cầu Có kinh nghiệm mạnh về Microsoft Visual Studio hoặc IDE tương đương khác Có khả năng đưa ra mục đích và hướng đi rõ ràng trong công việc Nắm bắt và truyền đạt các mục tiêu làm việc có thể đo lường Truyền đạt thông tin ngắn gọn và rõ ràng Hỗ trợ các thành viên trong nhóm trong quá trình đào tạo thực tế (hoặc khi được đào tạo) Giải quyết các vấn đề và mâu thuẫn theo hướng tích cực Tuân thủ theo các quy trình phù hợp của MiTek Việt Nam Xây dựng một môi trường làm việc trong đó các thành viên trong nhóm hỗ trợ và đoàn kết với nhau Có khả năng động viên và khuyến khích các thành viên trong nhóm đưa ra sáng kiến và đặt trọng tâm vào chất lượng Xác định các cơ hội nhằm cải thiện quá trình phát triển và cung cấp các dịch vụ Khuyến khích và hỗ trợ xây dựng một văn hóa làm việc trong đó các thành viên không ngừng phát triển Hỗ trợ các thành viên trong nhóm khi công ty có các thay đổi Có khả năng thể hiện được các giá trị cốt lõi của Công ty MiTek Việt Nam Hiểu biết sâu sắc về dịch vụ khách hàng bao gồm việc thực hiện các quy định về sự hài lòng của nhân viên. University or College degree, preferably major in Computer Science or Engineering Have 2 plus years experience within software or related industry with a cursory knowledge of global development practices and procedures. English level (CEFR) B1+ or equivalent Have solid knowledge and experience in software development utilizing technologies for the project assigned and consistent with the team typically including using design patterns, Object Oriented Design, C#, .NET Framework, SQL Database, C, C++, and other development tools and languages as required Strong experience with Microsoft Visual Studio or other equivalent IDE Be able to provide a clear purpose and direction to your sprint tasks Understand and communicate measurable performance objectives Communicate clearly and succinctly Support team members through on-the-job training (or being trained) Resolve problems and conflicts positively Conduct yourself in line with appropriate MiTek Vietnam procedures Create a supportive, inclusive environment within the team Ability to encourage and motivate staff to deliver on initiatives with a focus on quality Identify opportunities for better service delivery and development Promote and support continuous improvement culture Support team members through change processes Capability to live the MiTek Vietnam values Demonstrated internal customer service insights including the implementation of employee satisfaction charters.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 빈투안', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1757, 982, 2, 'Team Lead', 'Mục tiêu công việc\n- Team Lead chịu trách nhiệm dẫn dắt nhóm kỹ thuật, đảm bảo chất lượng kỹ thuật trong toàn bộ vòng đời phát triển phần mềm, đưa ra định hướng công nghệ, kiến trúc hệ thống, đồng thời phối hợp chặt chẽ với các bên liên quan để đảm bảo tiến độ và hiệu quả dự án.\n\nNhiệm vụ chính\n- Dẫn dắt đội ngũ kỹ sư phần mềm trong thiết kế và phát triển sản phẩm.\n- Thiết kế kiến trúc hệ thống, đảm bảo hiệu suất, bảo mật và khả năng mở rộng.\n- Review code, tối ưu hiệu năng, bảo đảm chất lượng sản phẩm.\n- Phối hợp với PM để phân tích yêu cầu và lập kế hoạch kỹ thuật.\n- Đưa ra lựa chọn công nghệ, tiêu chuẩn kỹ thuật phù hợp với định hướng sản phẩm.\n- Đào tạo, mentoring cho các thành viên trong team.\n- Quản lý rủi ro kỹ thuật, xử lý sự cố và giải quyết các vấn đề phát sinh.\n\nYêu cầu\n- Tối thiểu 2 - 4 năm kinh nghiệm phát triển phần mềm, 1–2 năm ở vai trò Team Leader.\n- Thành thạo một hoặc nhiều ngôn ngữ/lập trình: Node.js, Java, .NET, PHP, Python, v.v.\n- Có kinh nghiệm thiết kế hệ thống backend phức tạp, API, microservices, database scaling.\n- Kinh nghiệm DevOps, CI/CD, Cloud (AWS/GCP/Azure) là lợi thế.\n- Kỹ năng giao tiếp, quản lý team, tinh thần trách nhiệm cao.\n- Ưu tiên từng làm việc với các mô hình Agile/Scrum.\n\nPhúc lợi\n- Mức lương Thỏa thuận theo năng lực (~20M)\n- Chế độ lương - thưởng: Lương tháng 13\n- Chăm sóc sức khỏe: Bảo hiểm y tế \n- Nghỉ phép: 12 ngày/năm, nghỉ lễ theo lịch nhà nước \n- Chế độ đãi ngộ tốt nhất cùng đội ngũ nhân viên luôn hỗ trợ nhau hết mình, trọng dụng nhân tài \n- Có cơ hội tiếp xúc với chuyên gia trong lĩnh vực công nghệ và kinh tế. \n- Có cơ hội phát triển bản thân và thăng tiến \n- Môi trường năng động, thân thiện, tự do, thoải mái \n- Thường xuyên được tham gia team building, hoạt động nội bộ. \n- Thời gian làm việc: Từ 8h - 17h, từ Thứ 2 - Thứ 6.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1758, 788, 2, 'C++ Developer', 'CMC Global is a member of CMC Corporation with an aspiration to bring ICT products, solutions, and services of Vietnam to the international market.\nEstablished in March 2017 as a strategic move of the Corporation to enter the global stage, we are proud to be the leading company in Vietnam in providing a wide variety of comprehensive IT Solutions & Services, ranging from Traditional services to Digital Transformation, as well as Consultancy, to organizations worldwide.\n\n1. JOB DESCRIPTION\nParticipating in software development projects and applications of in-vehicle infotainment systems (Infotainment) in the field of Automotive. Self-assign tasks and fully be responsible for quality/quantity of delivered results;\nEnsure software development on time and ensure product quality;\nHandle technical problems, and report progress, and work results to management levels.\n\n2. JOB REQUIREMENTS\nMust have:\n- At least 3++ years technical experience and knowledge in C++.\n- Java/C++ programming.\n- Knowledge and experience of source code control (Git).\n- Proficient Debugging skills (reading logs, code understanding, giving solutions).\n- Having hands-on experience in using at least one version control tool such as Git, Gerrit.\n- Having hands-on experience in using JIRA, Confluence.\n\nNice to have:\n- Knowledge in Automotive domain.\n- Knowledge in Android Auto, AOSP.\n- Having hands-on experience working with ASPICE.\n\n3. WHY YOU\'LL LOVE WORKING FOR CMC GLOBAL\n- Salary: Negotiable.\n- Package: 14 salary months + Project bonus (If any).\n- Extra package: 16M/year.\n- Young and dynamic working environment.\n- Opportunity to approach newest technology trends.\n- Company’s labor policy completely pursuant to Vietnam labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.).\n\n4. CONTACT\n- Working location: Da Nang.\n- Submit CV via email: nncdang@cmcglobal.vn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1759, 935, 2, 'JP Bridge Software Engineer', 'Job Description\n\n- Developing the system of the first automotive system in Japan.\n- Requirements for technical direction, desire to do full-stack from design-code-test,\n- Customers will train to gradually become full-stack from design, coding, testing, and release.\n\nRequirements\n\n- Experienced, leading company engineers train to become full-stack system engineers.\n- JP level: N2 (Communicate with customers via calling, email)\n- Strong English (daily communication)\n- Technical required: Strong C+\n- and other technical languages\n- 3 years or more of IT experience\n\nBenefits\n\n- Be part of our hugely international environment;\n- Competitive salary package based on skills and experience.\n- Work Permit, Health Insurance and Relocation Assistance will be provided for candidates\n- Awesome social events and parties for employees\n- Great opportunity to grow career path with the company.\n- Frequent staff activities and company parties.\n\nSalary\n\n- Competitive salary\n\nWorking Address\n\n- Country: Vietnam\n- Province: Hà Nội\n- District: Thạch Thất\n- Address: Hola Park - Hoa Lac Hi-tech Park, Km 29, Thang Long Highway, Thach That District, Hanoi\n\nWays Of Working\n\n- Full-time', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1760, 432, 2, 'SYSTEM ENGINEER', 'System Engineer\n\n12025-06-30\n\nApply Now\n\nResponsibilities\n\nSaaS Management\n\n• Onboard, configure, and maintain software applications.\n• Continuously monitor and optimize the performance of SaaS applications to enhance efficiency and resolve issues\n• Provide end-user support and training on SaaS applications to enhance user productivity.\n• Monitor and control costs associated with SaaS subscriptions and services.\n• Create and maintain documentation for SaaS applications, including user guides and policies.\n• Investigate and resolve technical issues related to SaaS applications and escalate when necessary.\n• Retire outdated or unnecessary SaaS solutions.\n• Google Workspace management and configuration.\n• Handling invoices and receipts for SaaS payments.\n• Support with B2B SaaS migrations\n\nAsset Management\n\n• Maintain an inventory of all hardware and software assets, including tracking and documenting changes.\n• Procure tech equipment for new and existing staff.\n• Manage the return of tech equipment for offboarding staff.\n• Triage, arrange, and/or coordinate the repair of faulty devices where necessary.\n\nSupport\n\n• Manage and respond to IT support through the relevant channels.\n• Any other duties or responsibilities required at the discretion of your manager.\n\nSecurity and Data Privacy\n\n• Provide training on key platforms and report usage metrics.\n• Track and remediate issues reported by endpoint management and configuration software across all company-owned assets.\n• Implementing infosec requirements, and assisting the Security teams as required.\n\nRequirements\n\n• University degree in IT related field\n• 2–3+ years experience in IT support, SaaS management, or IT operations.\n• Strictly follow IT processes.\n• Experience working in a remote or distributed team environment is a plus.\n• Experience with SaaS platforms (e.g. Google Workspace, Slack, Jira, HubSpot, 1Password).\n• Strong knowledge of SaaS administration including user onboarding/offboarding, configuration, and cost management.\n• Basic troubleshooting skills for hardware and software issues.\n• Proficiency in IT support tools and ticketing systems.\n• Understanding of IT asset management best practices.\n• Ability to manage invoices, receipts, and SaaS billing documentation.\n• Comfortable with handling B2B SaaS migrations and change management.\n• Familiar with hardware troubleshooting, repair, and maintenance for server, PC, networking equipment, other IT-related equipment (telecom, mobile...).\n• Good knowledge of IT system operations, both Linux and Windows, as well as virtualization infrastructure.\n• Experienced with cloud platforms: Azure, office 365, Skype for Business, AWS...etc.\n• Have good researching skills and willingness to learn new technology.\n• Document IT Systems and make sure that the documents are up-to-date,\n• Ability to work with basic shell scripts/programming languages to improve the efficiency of the IT processes/systems\n\nNice to have\n\n• Relevant certifications (desirable but not mandatory): Google Workspace Administrator; ITIL Foundation; CompTIA A+ / Network+; Security+ or similar,\n• Have Certificates: MCSA, MCSE, LPI, CCNA, Microsoft Cloud certification, AWS certification is highly preferred,\n• Have knowledge about ISO/IEC 27001 or/and is preferred.\n\nSoft Skills\n\n• Be a problem solver with great problem-solving skills.\n• Proactive and effective self-learning skills and research.\n• Excellent English Reading and Writing skills.\n• Excellent learning and researching skills.\n• Training skill\n• Comfortable aligning with Australian time zone (7am-4pm) for work hours.\n• Ability to coordinate with teams across multiple departments and time zones.\n\nWhat We Offer\n\n• Attractive salary based on your performance.\n• Annual 13th month salary.\n• Dedication bonus will be paid once a year.\n• Premium healthcare insurance, Annual health checks up.\n• Hybrid working (1-day WFH per week).\n• Breakfast are available at office in early morning and snack in late afternoon.\n• Team building allowance.\n• Annual Company team building trip.\n• Clubs (Football, Badminton, Swimming, Chess, Music band).\n• Exclusive training programs for all staff in technical, soft skills and process.\n• English class.\n• Technical clubs.\n• Marriage allowance, having newborn baby allowance, bereavement allowance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1761, 715, 2, 'Kỹ sư Kiểm soát chất lượng', 'Nơi làm việc: Hà Nội\n\nMÔ TẢ CÔNG VIỆC:\nTriển khai công tác kiểm soát chất lượng áp dụng cho quá trình nghiên cứu/sản xuất.\nNghiên cứu các tiêu chuẩn sản phẩm, tiêu chuẩn kiểm soát do nhóm QA xây dựng. Đề xuất áp dụng các phương pháp kiểm soát chất lượng phù hợp với điều kiện nghiên cứu/sản xuất của từng sản phẩm cụ thể.\nĐánh giá và báo cáo chất lượng chuỗi cung ứng theo các quy trình, quy định đã ban hành căn cứ theo các báo cáo phân tích lỗi của Kỹ sư.\nKiểm tra và báo cáo phân tích chất lượng nguyên vật liệu đầu vào và sản phẩm đầu ra.\nYÊU CẦU:\nTốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Toán – tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\nTrình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\nCó tối thiểu 3 năm kinh nghiệm trong ngành QLCL hoặc Đo lường\nCó kiến thức về các phương pháp quản lý chất lượng tiên tiến trên thế giới và hệ thống quản lý vòng đời sản phẩm: CALS, PLM, PDM.\nCó kiến thức hệ thống về nguyên lý thống kê.\nCHẾ ĐỘ ĐÃI NGỘ:\nĐược hưởng các khoản quà, thưởng lễ tết, nghỉ mát hỗ trợ ăn trưa, điện thoại liên lạc tối thiểu 2.000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\nĐược hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\nĐược hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\nĐược trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\nCó cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\nĐược cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\nCó cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.\nMức lương cạnh tranh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1762, 702, 2, 'Binance Accelerator Program - iOS Engineer', 'Binance is the global blockchain company behind the world’s largest digital asset exchange by trading volume and users, serving a greater mission to accelerate cryptocurrency adoption and increase the freedom of money.\n\nAre you looking to be a part of the most influential company in the blockchain industry and contribute to the crypto-currency revolution that is changing the world?\n\nResponsibilities\n\n- Participate in team meetings and brainstorming sessions to foster collaboration and continuous learning.\n- Analyze and work with sophisticated code structures, ensuring technical concepts are formalized into functional, clean, and efficient code.\n- Perform small-scope refactoring to improve code quality and maintainability.\n- Contribute to the development of mobile applications, including gaining experience in submitting apps to the App Store or other platforms.\n- Read, analyze, and write technical documentation to support development tasks.\n- Work collaboratively with the team to understand and implement Software Development Lifecycle (SDLC) processes, contributing to requirements gathering, design, development, testing, and deployment phases.\n\nRequirements\n\n- Familiarity with sophisticated software development concepts and practices.\n- Experience working with mobile application development and deployment platforms.\n- Strong technical documentation skills, with the ability to translate complex concepts into clear and actionable documentation.\n- Understanding of version control systems, particularly Git.\n- Ability to contribute to code quality improvements through refactoring and adherence to best practices.\n- Knowledge of SDLC processes and experience working collaboratively across different phases of the software development lifecycle.\n\nNice to Have\n\n- Hands-on experience submitting apps to the App Store or similar platforms.\n- Exposure to team-based collaboration tools and practices, such as brainstorming sessions and cross-functional meetings.\n- Passion for learning and improving software development practices.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه هو شي مينه سيتي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1763, 983, 2, 'Senior Java Engineer(Listed Company/Hiring for 4 Roles)', 'Company Background\n\nThis is a prominent, publicly traded company headquartered in the United States, specializing in providing cutting-edge information technology services exclusively for the real estate industry. We take immense pride in our core team\'s stability, fostering a vibrant technical atmosphere, as well as cultivating a supportive team culture. We are here to welcome exceptional individuals like you to become part of our dynamic team and contribute to our collective success.\n\nRemote working culture\n\nOur company has fully embraced remote work as the norm for engineering, and we have dedicated ourselves to nurturing a strong remote working culture. We firmly believe that telecommuting offers numerous benefits, such as saving commuting time and alleviating congestion. In this way, we empower our team members with greater flexibility to strike a healthy work-life balance and enjoy more quality time with their loved ones. Additionally, we encourage our team members to explore their hobbies and discover new experiences, fostering personal growth and a broader perspective on the world. Join us to enjoy the benefits of remote work while seizing opportunities for both professional and personal development.\n\nRequirements\n\nWorking Requirements\n\n- Working Location: Anywhere in Vietnam, remote. Candidates must be either Vietnamese citizens or hold a valid work visa for Vietnam. Applications from other countries will not be considered\n- Working Hours: You are expected to work an average of 8 hours a day, allowing for flexibility and autonomy. However, it is important to allocate time for daily communication and prompt response with the team, ensuring efficient task completion\n- Job Nature: Full-time, requiring 40 hours of work per week\n- Language requirements: Fluent English for communication with international teams\n- We will provide the Macbook for work\n\nTechnical Requirements\n\n- Possesses strong logical thinking, is skilled at analyzing and solving problems, and has good communication abilities\n- Demonstrates strong English proficiency and can communicate fluently with team members and stakeholders across various regions, particularly with the US team\n- Proficient in Java with extensive experience in back-end and API development; familiar with the Java ecosystem with a deep understanding of commonly used frameworks and libraries; skilled in business modeling, with strong abilities in unit testing and integration testing\n- Solid knowledge of data structures, programming skills, engineering capabilities, and clean coding practices\n- Familiar with Docker, AWS S3, RDS, and related frameworks and components\n- Proficient in common Git commands and workflows, particularly those related to GitHub pull requests\n\nBenefits\n\nSalary and Benefits\n\n- The employment contract will be administered through a Singapore-based human resources firm. Compensation will be based on an hourly wage framework, with the default presumption of full-time employment (8 hours a day, 40 hours a week)\n- The hourly rate for this position ranges from approximately USD $13 - $25 per hour, depending entirely on the individual\'s skill level\n\nBonus Experience\n\n- Remote Working Experience: Prior experience with remote work is preferred\n- Available to work during the US Eastern Time Zone (9 pm and 5 am Vietnam Time) or at least a 5-hour overlap between 9 pm and 2 am Vietnam Time for effective collaboration across teams in different time zones\n\nRecruitment process\n\n- After receiving a recommendation from the talent pool, and if you meet our basic requirements, we will send you a written task\n- You will have 7 days to complete the task and submit it to us via a GitHub pull request. We encourage you to demonstrate your best coding practices, including task decomposition, code quality, testing, documentation, Git commits, and effective communication. This stage is crucial for assessing potential candidates\n- Our team members will conduct a thorough code review and provide internal feedback\n- Once a final decision has been made, we will notify you. If your code meets our standards, we will schedule a remote video interview in English\n- The remote video interview aims to explore your technical abilities and overall skills in greater detail, as well as discuss salary expectations\n- If you perform well in the interview and choose to join our team, you will need to sign a contract prior to starting\n\nFAQ\n\nQ: How will I be paid since the hourly rate is in USD?\n\nA: The Singapore-based resourcing company will offer you a platform that converts USD into your local currency when you choose to withdraw it. Since our salaries are paid in US dollars, the real-time exchange rate will affect the conversion to Vietnamese dong (VND).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1764, 984, 2, 'Java developer onsite HCM', 'Job Responsibilities:\n- Upgrading existing functionalities and creating new functionalities using data-driven insights.\n- Implement and deliver new customer project development with great quality.\n- Involvement in all phases of the development cycle.\n- Active participation in planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional or integration tests and perform unit testing.\n- Code review for other team members.\n- Automate the maintenance work with the development.\n- Responding and resolving IT support requests from employees via phone, email, SR system.\n\nRequired Qualifications:\n- Experience in designing, implementing, and maintenance support on Java-based (Spring Framework) backed applications with (JSP) Frontend, 3- 5+ years.\n- English good (communicate with clients)\n- Analyse, design, and develop new functionality adhering to standards provided, as well as maintenance support or issue fixing if necessary.\n- Worked on enterprise-scale projects using:\n- Oracle P/L, MyBatis\n- Java (Spring Boot / Spring Framework)\n- JSP (JavaScript / JQuery)\n- Git (Git Runner)\n- Be proficient in technology stacks or tools such as Azure, AWS, Redis, etc.\n- Proficient skills with tools used in software development lifecycle, such as DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, and other CI/CD tools.\n- Experience in databases such as Oracle, Microsoft SQL Server, or MySQL.\n- Understand structure and hands-on experience in writing Query, Stored Procedures, Functions, Scheduler, Table, Index, etc.\n- Familiarity with debugging and performance tuning along with a good understanding of deploying, maintaining, and monitoring complex Java Web applications.\n- Solid object-oriented analysis and design skills, understanding of design patterns and concepts as well as adherence to software code standardization.\n- Experience in below skills:\n- AWS\n- MS .Net / .Net Core\n- Kubernetes\n- React.js\n- Nginx\n- JUnit\n- Jasper Report\n- Elastic Search & Kibana (ELK)\n- Grafana\n- Prometheus (Monitoring/alerts)\n\nAdditional Requirement:\n- Able to communicate effectively, analytical with good time management, problem-solving and documentation skills.\n- Strong team player skill.\n- Able to perform various Developer roles where necessary & System Support.\n- Possess the capability to manage varying users of different capabilities.\n- Able to multi-task, manage and undertake various projects simultaneously.\n- Team player and able to work well with others.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1765, 985, 2, 'Senior Backend Engineer', 'Địa điểm làm việc: Hồ Chí Minh, Hà Nội\nMức lương: 2,000 – 4,000 USD\nCấp bậc: Senior (5–10 năm kinh nghiệm)\nVai trò & Kỹ năng: Backend, Phát triển phần mềm, NodeJS, TypeScript\nVai trò mong đợi\n- Thiết kế và phát triển các ứng dụng backend mạnh mẽ, có khả năng mở rộng và dễ vận hành lâu dài.\n- Hợp tác với các nhóm chức năng chéo và các bên liên quan khác để triển khai tính năng mới và cung cấp giải pháp chất lượng cao.\n- Giám sát và bảo trì các ứng dụng hiện tại, xác định và khắc phục các điểm nghẽn, lỗi, đảm bảo hiệu suất và bảo mật tối ưu.\nVí dụ nhiệm vụ (không giới hạn)\n- Trực tiếp thiết kế và phát triển hệ thống, bao gồm viết unit test và tài liệu.\n- Triển khai các tính năng và tích hợp với mã sạch, hiệu quả, tuân theo các best practices trong phát triển phần mềm.\n- Tham gia review mã nguồn và đóng góp cải tiến quy trình phát triển liên tục.\nLợi ích và kinh nghiệm đạt được khi tham gia vị trí này\n- Trải nghiệm tích hợp những lĩnh vực chuyên môn phức tạp vào hệ thống phần mềm.\n- Cơ hội giải quyết các bài toán khó với những đồng đội năng động và giỏi kỹ thuật.\n- Góp phần vào việc mở rộng sản phẩm ở quy mô toàn cầu bằng kỹ năng kỹ thuật.\n- Tham gia phát triển những sản phẩm mang lại giá trị thực tế, thay đổi ngành công nghiệp sản xuất.\nYêu cầu kỹ năng và kinh nghiệm\n- Tối thiểu 5 năm kinh nghiệm làm việc với vai trò Kỹ sư Backend.\n- Thành thạo TypeScript/NodeJS.\n- Có kinh nghiệm trong việc:\n- Xác minh công nghệ, phân tích yêu cầu, thiết kế kiến trúc, xây dựng hạ tầng cho nhóm phát triển hoặc nhiều dự án.\n- Thiết kế và phát triển hệ thống lớn, làm việc với nhiều nhóm khác nhau.\n- Phát triển theo hướng Domain-Driven Design (DDD).\n- Làm việc trong môi trường theo phương pháp Scrum/Agile.\n- Giải quyết vấn đề liên quan đến công nghệ, sản phẩm hoặc quy trình phát triển.\n- Sử dụng thành thạo Docker trong môi trường hạ tầng.\n- Tiếng Anh giao tiếp thành thạo trong môi trường kinh doanh (bao gồm viết, nhắn tin, họp).\nMôi trường công nghệ phát triển sản phẩm\n- Front-end: TypeScript, React, Next.js\n- Backend: Rust (axum), TypeScript, Node.js (Express, Fastify, NestJS)\n- Machine Learning / Thuật toán: Rust, Python, OpenCV, PyTorch, TorchServe, Elasticsearch, Vertex AI\n- Hạ tầng: Google Cloud, GKE, Anthos Service Mesh, Istio, Cloudflare, Argo Workflows\n- Event Bus: Cloud Pub/Sub\n- DevOps: GitHub, GitHub Actions, ArgoCD, Kustomize, Helm, Terraform, Datadog, MixPanel, Sentry\n- Dữ liệu: CloudSQL (PostgreSQL), AlloyDB, BigQuery, dbt, trocco\n- API: GraphQL, REST, gRPC\n- Xác thực: Auth0\n- Công cụ phát triển: GitHub Copilot, Figma, Storybook\n- Công cụ giao tiếp: Slack, Discord, JIRA, Miro, Confluence\nLý do nên ứng tuyển\nPhong cách làm việc:\n- Hybrid (đến văn phòng ít nhất 1 lần/tuần)\nChế độ nghỉ phép:\n- 12 ngày phép/năm\n- Nghỉ lễ theo quy định quốc gia\n- Nghỉ Tết, nghỉ cuối năm (31/12 đến 2/1)\n- Các chế độ khác theo Luật Lao Động\nPhúc lợi:\n- Xét tăng lương mỗi 6 tháng\n- Thưởng tháng 13\n- Chương trình ESOP (chia cổ phần cho nhân viên)\n- Lương + bảo hiểm đầy đủ trong 2 tháng thử việc\n- Bảo hiểm sức khỏe cao cấp\n- Bảo hiểm xã hội, y tế, thất nghiệp, tai nạn lao động\n- Khám sức khỏe định kỳ hàng năm\n- Chương trình đào tạo chuyên sâu (nội bộ/ngoại khóa)\n- Cung cấp thiết bị theo yêu cầu (laptop, màn hình)\n- Giải thưởng nội bộ định kỳ (MVP mỗi 6 tháng)\n- Các hoạt động nội bộ: year-end party, team building...\nƯu tiên nếu ứng viên có thêm:\n- Kinh nghiệm phát triển với ngôn ngữ có hệ thống kiểu tĩnh mạnh như Rust, Scala,...\n- Kiến thức front-end với ReactJS, Next.js\n- Kinh nghiệm thiết kế, phát triển và vận hành microservices\n- Kinh nghiệm phát triển ứng dụng web với tiêu chuẩn bảo mật cao.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1766, 986, 2, '100523 - Senior Software Engineer I', 'Join Axon and be a Force for Good.\n\nAt Axon, we’re on a mission to Protect Life. We’re explorers, pursuing society’s most critical safety and justice issues with our ecosystem of devices and cloud software. Like our products, we work better together. We connect with candor and care, seeking out diverse perspectives from our customers, communities and each other.\n\nLife at Axon is fast-paced, challenging and meaningful. Here, you’ll take ownership and drive real change. Constantly grow as you work hard for a mission that matters at a company where you matter.\n\nYour Impact \n\nDigital Evidence Management Systems are key to officer efficiency and Axon’s mobile applications, View and Capture, play critical roles in evidence acquisition. Axon View interacts with body-worn cameras to display live camera streams, or to view and tag previously-collected evidence. Axon Capture collects digital evidence (photos, videos, audio) and uploads to evidence.com for later processing.\n\nAs a senior mobile developer on our team, you will be a key part of our next generation of mobile applications. You’ll ensure our codebases interact with platform SDKs related to photos, videos, audio, file management, networking, WiFi and bluetooth. You’ll write code that interacts with custom-made devices, such as Axon Body-Worn Cameras. You’ll ensure our codebase is performant and meets the highest data privacy standards.\n\nYou are a Senior Mobile App Developer\n\nYou’ve created mobile applications for years. You know the platform inside and out and you remember how it has changed over the years. You’re familiar with key frameworks and technologies important to our applications (Networking, Bluetooth, WiFi, Photo, Video).\n\nYou drive engineering efforts to completion. You evaluate, plan, estimate, communicate and collaborate. You ramp up quickly, solve problems and resolve ambiguity. You are ready to candidly and respectfully share your wisdom and knowledge for the betterment of our team, our code and our product.\n\nYour Day-to-Day \n\nDesign, implement and maintain features within Axon View, Axon Capture, and related shared libraries.\nParticipate in Scrum ceremonies.\nCollaborate within the Scrum team to ensure we hit our sprint goals, collaborate with other groups to ensure we build and ship the “right” thing.\n\nBasic Qualifications\n\nBachelors in Computer Science\n5+ years shipping high-quality iOS applications\nStrongly competent in Swift\nStrong track record of delivering solid code on a schedule\nExperience that demonstrates learning & application of the latest native technology: Swift UI, Swift Package Manager, iOS 16 & WWDC releases\nExcellent communication\nUnited States Citizenship\n\nPreferred Qualifications\n\nSDKs: experience related to Bluetooth, WiFi, Networking, Camera (Photo/Video), Audio, File Management, connecting to and interacting with third party hardware, UI\nCI/CD: experience creating and managing automation and integration\nToolchain: Cocoapods, Swift Package Manager\nObjective-C, and Swift / Objective-C compatibility\n\nNice-to-have\n\nMonitoring & Alerting experience\n\nDon’t meet every single requirement? That\'s ok. At Axon, we Aim Far. We think big with a long-term view because we want to reinvent the world to be a safer, better place. We are also committed to building diverse teams that reflect the communities we serve.\n\nStudies have shown that women and people of color are less likely to apply to jobs unless they check every box in the job description. If you’re excited about this role and our mission to Protect Life but your experience doesn’t align perfectly with every qualification listed here, we encourage you to apply anyways. You may be just the right candidate for this or other roles.\n\nImportant Notes\n\nThe above job description is not intended as, nor should it be construed as, exhaustive of all duties, responsibilities, skills, efforts, or working conditions associated with this job. The job description may change or be supplemented at any time in accordance with business needs and conditions.\n\nSome roles may also require legal eligibility to work in a firearms environment.\n\nAxon’s mission is to Protect Life and is committed to the well-being and safety of its employees as well as Axon’s impact on the environment. All Axon employees must be aware of and committed to the appropriate environmental, health, and safety regulations, policies, and procedures. Axon employees are empowered to report safety concerns as they arise and activities potentially impacting the environment.\n\nWe are an equal opportunity employer that promotes justice, advances equity, values diversity and fosters inclusion. We’re committed to hiring the best talent — regardless of race, creed, color, ancestry, religion, sex (including pregnancy), national origin, sexual orientation, age, citizenship status, marital status, disability, gender identity, genetic information, veteran status, or any other characteristic protected by applicable laws, regulations and ordinances — and empowering all of our employees so they can do their best work. If you have a disability or special need that requires assistance or accommodation during the application or the recruiting process, please email recruitingops@axon.com. Please note that this email address is for accommodation purposes only. Axon will not respond to inquiries for other purposes.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1767, 987, 2, 'Software Engineer - Dashboard', 'PLS Pte Ltd is a dynamic company committed to delivering innovative solutions across diverse industries. Our vision is to lead globally by creating impactful solutions, while our mission is to provide exceptional value through expertise, collaboration, and creativity. We offer various services, including custom software solutions, cutting-edge technology, consulting, project management, and quality assurance. Our strengths lie in innovation, expertise, customer-centricity, and integrity. Join us to transform challenges into opportunities and drive growth together.\n\nThe Role\n\nYou Will Be Responsible For\n\n- Design, develop, and maintain web applications using C#, React.js, and MS SQL Server.\n- Collaborate with cross-functional teams to gather and analyze requirements.\n- Write clean, efficient, and well-documented code.\n- Troubleshoot and debug applications to ensure optimal performance.\n- Participate in code reviews and contribute to best practices and continuous improvement.\n\nIdeal Profile\n\n- Minimum 3 years of hands-on experience in software development with C#, React.js, and MS SQL Server.\n- Strong understanding of software development principles and design patterns.\n- Experience with REST APIs, and agile development methodologies.\n- Self-motivated, responsible, and able to work independently in a remote environment.\n- Good communication skills and a collaborative mindset.\n\nWhat\'s on Offer?\n\n- Work alongside & learn from best in class talent\n- A role that offers a breadth of learning opportunities\n- Fantastic work culture', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1768, 988, 2, 'Python Developer', 'We seek a highly skilled Python Developer with at least 2 years of experience to join our dynamic team. The successful candidate will play a crucial role in understanding, designing, and implementing Thought Machine smart contracts, focusing on Core banking processes. While prior knowledge of Core banking and Thought Machine is considered valuable, it is recognized as a "nice-to-have" qualification.\n\nWhat do you do?\nSmart Contract Development\n- Understand and contribute to the development of smart contracts, CI/CD pipeline, and deployment processes\n- Design Thought Machine smart contracts based on business requirements, ensuring accuracy and efficiency\n\nBusiness Integration\n- Collaborate with business stakeholders to understand and discuss requirements related to Finance, Credit card, and Ops processes in Core banking\n- Provide support during the development, UAT testing, and production phases, triaging issues in smart contracts\n\nPython Back-end Development\n- Leverage solid experience in Python back-end development to implement and optimize smart contract code\n\nAgile Software Delivery\n- Follow Agile software delivery frameworks to ensure efficient and iterative development processes\n\nTechnical Analysis and Implementation\n- Analyse and validate business requirements, translating them into technical specifications for smart contract development\n- Implement Vault workflows and Python smart contract code from client requirements\n\nCollaboration and Coordination\n- Collaborate with engineering teams, obtaining a deep technical understanding of Vault and the associated roadmap\n- Coordinate impact and requirements across projects, supporting client staging and development instances\n\nIssue Resolution and Post-Mortems\n- Investigate and resolve client technical queries related to smart contracts\n- Conduct post-mortems and defect management on technical issues, contributing to continuous improvement\n\nTesting and Quality Assurance\n- Participate actively in testing, release cycles, and QA processes, ensuring the reliability of smart contract implementations\n- Conduct unit testing in Python and understand CI/CD processes.\n\nWhat is required?\n- Minimum of 2 years of experience in Smart Contract Python development\n- Proficiency in Python, Starlark\n- Experience in plan management, schedule management, and unit testing in Python, with a strong grasp of CI/CD processes\n- Practical knowledge of testing principles, including unit, integration, and end-to-end testing.\n- Understanding of the CQRS pattern and practical knowledge of Git flow, Trunk, and GitHub flow branching strategies\n- Familiarity with the DevOps toolchain, including GitHub, CircleCI, Artifactory, SonarQube, etc.\n- Nice-to-have requirements:\n- Knowledge of Core banking and Thought Machine, and Smart contract version upgrades\n- Understanding of retail banking and accounting principles, including double-entry bookkeeping\n- Knowledge of how Blockchain works is a plus.\n\nWhat we can offer?\n- Attractive income in Viet Nam fintech markets\n- 20 days of annual leave, 10 days of sick leave and public holidays.\n- Full-salary paid for social insurance & Premium healthcare package\n- Modern devices provided (Macbook, mouse, monitor…)\n- Empowered to listen creative ideas, and there is no distance between bosses and employees.\n\nFinX begins to establish and bridge new fintech business in order to create a better tomorrow for Vietnamese people. Here is an inspired working environment where you will be able to access and experience cutting-edge technologies in industry and creativity.\n\nLocation: PV Gas Tower, 673 Nguyen Huu Tho, Phuoc Kien Ward, Nha Be District, HCMC, Vietnam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1769, 989, 2, 'Java Engineer', 'I. Company Information\n- MyMind is a Product company that provides Solutions, Packaged software products to solve problems of information technology systems in major classes, businesses, banking, insurance, education, and telecommunications. - Website: https://msm.com.vn\n\nII. Responsibilities\n- Implement scalable and high-performance systems and APIs.\n- Write clean, efficient, and maintainable code, following best practices and coding standards to ensure quality and reliability.\n- Work closely with different stakeholders to understand and develop applicable solutions.\n- Contribute to the design of software architecture.\n\nIII. Requirements \n- 4+ years of experience in software development.\n- Solid knowledge and good experience in design patterns and SOLID principles.\n- Good analytics and problem-solving skills.\n- Strong knowledge and experience in Java 8 or newer.\n- Experience in Java application framework (Spring, Spring Boot, Hibernate, Jupiter, Mockito, Swagger, Flyway, Liquibase,...)\n- Experience in developing applications using messaging services (Kafka, RabbitMQ, etc), caching services (Redis)\n- Good in cloud-native technology (Container, Kubernetes, serverless) and DevOps culture.\n- Experienced in distributed systems and microservices.\n- Experience in cloud AWS\n- Experienced in working with some databases: MySQL, Postgres, and MongoDB. Preferred qualifications, but not required\n- Acknowledgment or experience in SaaS.\n- Knowledge of CI/CD.\n- Acknowledgment or experience in an integration system.\n- Acknowledgment or experience in SQL tuning and data caching.\n\nIV. What’s on offer \n- 12 annual leave days alongside Vietnamese public holidays\n- Competitive Salary & Bonus\n- Lunch & Phone Allowance\n- Premium Health Care Bao Minh & Annual Health Examination\n- Yearly career/ performance evaluation\n- A flat organization (respect, teamwork, flexibility, transparency)\n- 13th salary bonus/ competitive salary\n- Great activities (Team Building, Company Trip, Monthly Event…)\n- Self-organize project team\n\nFor more information, don\'t hesitate to reach out to me on LinkedIn or via:\n☎ Zalo: (+84) 347022122\n📩 Email: giantl@msm.com.vn\n\nThank you for your consideration!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1770, 691, 2, 'Software Quality Assurance Engineer', 'What you will be doing:\n- Work with internal teams (Engineering/Product) to understand requirements and product features; also review and analyze requirements, specifications, and technical design documents, providing timely feedback\n- Develop detailed, comprehensive, and well-structured test plans and test cases\n- Prioritize, plan and execute testing activities\n- Design, develop, and execute automated tests, while also contributing to the enhancement and clear documentation of our automation framework and scripts. Actively identify, report, track, and verify software defects.\n- Perform regression tests and apply creative exploratory testing techniques to discover challenging scenarios and edge cases.\n\nWhat we need from you:\n- Good English communication skills (writing and speaking)\n- Strong understanding of software QA fundamentals, methodologies, tools, and processes.\n- Minimum 3 years of hands-on experience in software quality assurance, including developing and maintaining test automation.\n- Proven experience creating automated tests using test frameworks (e.g., Katalon Studio, Selenium Java, WebdriverIO).\n- A detail-oriented person, and motivated to proactively identify and resolve issues.\n- Willing to help your teammates, share your knowledge with them, and learn from them\n- Collaborative, adaptable, and dedicated to continuous learning and improvement, both personally and for team processes.\n\nAbout Hubble\nHubble is a leading technology company focusing on the construction and engineering industry. We are on a mission to build the world’s first autonomous construction sites by automating and trading the 4M (Man, Machine, Material, Money) resources.\n\nOur solutions help digitize all your work processes, and connect all key project stakeholders - developers, consultants, fabricators, contractors, and facility managers - onto an all-in-one platform - The Hubble Platform.\n\nBuild faster and cheaper and with the highest quality and safety standards with Hubble’s impactful technologies. Let’s transform the way we build our cities for a better tomorrow. Today. Together. For generations to come.\n\nWhat Hubble will give you:\nHubble is built by a team of talented, driven, and ambitious individuals. We do not subscribe to conventions. We do not let history and traditions dictate and limit our dreams to shape the world. We adopt the same mindset with our hiring. We are looking for the best and we want to bet on you.\n\nWho will you be working with:\nIf you connect with any of the description below, please apply immediately:\n- Purpose driven\n- Hungry, ambitions, and self-motivated\n- Meritocratic, results/performance > age/bureaucracy\n- Resourceful, independent, chart our own destiny\n- Determined, perseverance, and hard working\n- Creative, innovative, out of the box\n\nYes, the above is everyone of us at Hubble.\n\nVisit us at www.hubble.build to learn more for #bettercitiesoftomorrow.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1771, 891, 2, '[Hybrid] Fullstack Engineer (Java)', '📍Location: Tan Binh, HCMC\n\nOur client is a health-tech company specializing in corporate wellness solutions that enhance employee well-being and organizational performance. Their offerings include the platforms for managing cardiometabolic conditions, and a suite of services encompassing biometric screenings, mental health assessments, and human performance coaching.\n\nAs a Fullstack Engineer, you will work cross-functionally with other developers, designers, and product team members throughout the software development life cycle including requirements analysis and design. You will have the opportunity to participate in developing a next generation of products and offerings.\n\nKey Responsibilities:\n\n- Engage in the full software development lifecycle (SDLC) including user requirement analysis, designing and writing new software programs, testing, final deployment, and debugging new and existing products\n- Actively participate in architecture design based on stated business requirements\n- Support, maintain, and document software functionality\n- Analyze code to find causes of errors and revise programs\n- Commitment to coaching and mentoring team members\n- Participate and advance software design meetings and analyze user needs to determine technical requirements\n- Serve as a technical expert to resolve company-wide technical discussions, collaborate and include inputs from cross-functional teams (security, DevOps, data, compliance and product)\n- Identify and evaluate new technologies for implementation; discern build-vs-buy, identify and prioritize the highest ROI architectural investments\n- Work individually as well as within the team to deliver and maintain projects as well as provide product support to others\n- Work closely with other functional teams in different geographical regions to ensure successful delivery of both customer and in-house projects or solutions based on defined requirements\n- Ensure on-going development practices for consistency, reliability, performance, security, and continuity\n\nQualifications:\n\n- Bachelor’s or master’s degree in computer science, Information Systems or a related field\n- 5+ years in hands-on development of full-stack software solutions\n- Hands-on experience working in a distributed, cloud-based environment (AWS preferred or Azure) with high transaction volumes or high availability requirements (AWS RDS, SNS, SQS and Cognito experience is a plus)\n- Experience with Modern programming languages (Java, php, Python is a plus)\n- Good knowledge of JavaScript, Bootstrap, CSS and XML, familiarity with a front-end work such as React or VueJS is a big plus.\n- Good understanding in OOP, MVC, micro-service architecture concept\n- Experience with at least one Version Control System (SVN, Git) (Bitbucket is a plus)\n- Conversant in database design (MySQL)\n- Experience with container (Docker) and Orchestration (preferably Kubernetes)\n- Technical expertise in various areas of software engineering and track record of successful complex, and enterprise-scale project delivery\n- Experience in developing End to End technical Architecture and delivery of very large-scale platforms\n- Outstanding collaboration, listening, written and verbal communication skills with ability to facilitate technology strategy, requirements and architecture conversations with all stakeholders (management, business users, and technology resources)\n- Experience working with distributed teams (onshore and offshore)\n- Familiar with continuous integration and continuous delivery best practices\n- Ability to work a varied schedule in international time zones\n- Strong English communication skills, both written and verbal\n\nWhy join us?\n\n- Competitive salary with clear career growth\n- Unlimited paid leave\n- Flexible hybrid work model\n\n📩Ping us for further discussion.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh Kenti, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1772, 990, 2, 'Full Stack Developer (Python, AWS)', 'Main Tasks\n\nDesign & Development\nDevelop clean, efficient and maintainable code for backend services and occasionally frontend components\nWrite and maintain unit, component, and integration tests to ensure software reliability and functionality\nParticipate in code reviews to maintain quality standards and share knowledge across the team\nCollaboration & Teamwork\nCollaborate with developers, designers, and stakeholders to deliver well-integrated features\nSupport your team in decision-making processes and contribute to effective work organization\nDocumentation & Requirements\nCreate and maintain clear technical documentation and specifications\nHelp manage and clarify requirements for the software components you work on\nPerformance & Improvement\nOptimize the interaction between backend and frontend for performance, scalability, and security\nActively contribute to the continuous improvement of our systems and development practices\nJob Qualification\n\nStrong backend development skills with Python and experience with AWS services such as SQS, S3, Lambda / ECS\nExperience working with graph databases, ideally Neo4j\nFamiliarity with the Serverless Framework and a basic understanding of DevOps practices, including CI/CD\nComfortable working with frontend code; experience with React is helpful, Angular is our future direction. Familiarity with AWS Amplify is a plus.\nA structured, solution-oriented working style with the ability to work independently and collaboratively\nOur Benefits\n\n💪 Our fixed base salary is paid within 13 salaries and as extra, you have a 3% variable that is based on company performance\n🧑‍⚕️Private health insurance (incl. up to 2 family members)\n🛡️ Full coverage of social insurance (incl. probation period)\n🍏 Free lunch while working in the office\n🏖 Vacation: 15 days a year\n⚖️ Flexible hybrid work policy\n🗺️ Great team events\n🎁 Gifts for holidays', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 3, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1773, 880, 2, 'Freelance Software Developer (Python) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with Python\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge.\n\nBenefits\nWhy this freelance opportunity might be a great fit for you?\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Haiphong, Hai Phong City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1774, 878, 2, 'Senior Full Stack Developer (HCMC, Hybrid) (Visa and Relocation Package Provided)', 'About Nimble\n\nWe solve our client\'s most difficult business challenges through technology. Our company partners with the most ambitious companies around the world creating long-term impact with the work with do. If you want to grow together, work on challenging products and enjoy using the best tools and practices, Nimble is the right place for you!\n\nOur Core Values\n\n- Extreme Ownership: We treat our clients’ business as ours.\n- Bias for Action: Execution is everything. We act swiftly, prioritize decisive moves, and maintain a strong bias for action to deliver results.\n- Intensity: We tackle challenges with high energy and focus, delivering results through bold, committed actions.\n- Pragmatism: We prioritize practical, straightforward solutions that deliver results, creatively tackling complex challenges with determination.\n- Outcome Over Process: We always work toward impactful outcomes, driving results that matter. Processes help us repeat what works, but meaningful outcomes remain our North Star.\n- Truth Seeking: We seek truth with intellectual honesty, sharp critical thinking, and fact-driven reasoning.\n\nWhat You Will Do\n\n- You will be an active member or lead a team of developers in a project squad. We have a wide range of project sizes.\n- Decide which technologies are going to be used for front-end, back-end and define the overall architecture.\n- Work closely with the Product Owner to make sure the backlog is efficiently planned and occasionally assist in technical discussions with clients. Most of the client interfacing is done by the Product Owner.\n- Write clean, composable, and maintainable code as you develop world-class products for our clients.\n- Write automated tests to build and maintain the product we build for our clients.\n- Do code reviews with your squad members.\n- Learn new technologies languages like Ruby, Go, or Elixir, and techniques so that you are able to adapt to the evolving needs of our clients.\n- Knowledge sharing through team rituals.\n- Collaborate with other team members to define the internal processes and initiatives to help the company accomplish its mission. Our handbook has been written by the whole team.\n\nRequirements\n\n- Professional web development with 5+ years of experience. Experience in Ruby, JavaScript, Go is ideal (at least one of them).\n- Comfortable working both on frontend and backend.\n- At least basic experience with a modern JavaScript framework like ReactJS/Redux, VueJS or AngularJS.\n- Experience in writing automated tests for web applications.\n- Enjoy working on challenging solutions and systems.\n- Believe that building great applications is not only about delivering code that "works", but involves thinking about reusability, maintainability, security, and performance.\n- A "Can do attitude" and a product mindset.\n- Confidence in communicating in English.\n\nWhy You\'ll Love Working Here\n\n- You’ll feel proud of every product we ship. We care deeply about quality, design, and doing things right—our name stands for excellence.\n- You’ll be surrounded by high performers. We’re a tight-knit, ambitious team that pushes each other to grow and thrive.\n- We\'re built differently. We’ve been profitable and bootstrapped since day one—no VC pressures, just smart, sustainable growth.\n- We take pride in craftsmanship. Whether it\'s code, design, or delivery, we hold ourselves to a high bar—because the little things shape the big picture.\n- Process with purpose. We follow agile principles not just in theory, but in practice. Our engineers work with clearly defined user stories, estimate using story points, and deliver iteratively in focused 1–2 week sprints.\n- Growth is part of the job. Through regular one-on-ones, structured feedback, and a clear leveling framework, we support every team member’s growth—not just in technical skills, but in communication, collaboration, and leadership.\n- Learning never stops. Access a vast library of resources like Pluralsight, PragPub, Leanpub, e-books, and more—plus a yearly education allowance to help you level up in any direction you choose.\n- We’ve got your back. From day one, you’ll get private medical insurance, social welfare coverage, and a company care fund.\n- We support your move. If you\'re joining us from abroad, we’ll take care of your visa, work permit, and provide a relocation package to help you settle in smoothly.\n- Flexibility that fits. We support a hybrid workstyle, giving you the freedom to find the right rhythm between home and office life.\n- Work with the right tools. We’ll set you up with a MacBook and a large external monitor so you can work comfortably and efficiently.\n- A workspace that works for you with our modern office in the heart of Ho Chi Minh City and Da Nang.\n- Stay fueled. Our kitchen is always stocked with drinks and snacks.\n- Take the time you need. Enjoy 26 days of paid leave a year (including public holidays), plus a sabbatical month every 3 years.\n- Celebrate your journey. From anniversary gifts to yearly company outings and spontaneous team activities, we make time for fun and appreciation.\n- ...and more perks to make work feel better.\n\nIf you are a passionate web professional looking to make a significant impact in a growing software development company, we would love to hear from you.\n\nJoin us in shaping the future with with elevating web innovation!\n\nWe keep our recruitment process practical and straightforward.\n\nTo learn more about how we work, check our handbook named Compass, Github organization, and Medium account.\n\nWant to see what we have built? Check our Dribbble and Behance accounts.\n\nWant to keep in touch with us? Follow us on Facebook, Instagram, and LinkedIn.\n\nNimble is an equal opportunity employer.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1775, 732, 2, 'Frontend Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nTechnologists at WorldQuant research, design, code, test and deploy firmwide platforms and tooling while working collaboratively with researchers. Our environment is relaxed yet intellectually driven. We seek people who think in code and are motivated by being around like-minded people.\n\nWhat You\'ll Do\n- Develop/Maintain internal web applications on cloud and on premise \n- Write well designed, testable code by using state of the art software development practices\n- Create website layout/user interface by using standard HTML/CSS practices\n- Create and maintain software documentation\n\nWhat You’ll Bring\n- Experience in HTML, CSS, JavaScript/TypeScript\n- Demonstrated experience developing scalable and robust software web applications\n- Experience with popular JavaScript libraries and tools such as React.js, jQuery, NPM\n- Expertise in Python web frameworks such as Django, Flask and others\n- Experience with CI/CD and version control systems\n- Experience with GCP\n- Working experience with SQL databases (MySQL, PostgreSQL)\n- A solid background in Unix/Linux environment\n- Excellent debugging and problem solving skills\n- Strong knowledge and understanding of algorithm and data structures \n- Finance experience is not required\n\nWhat We Offer\n- Competitive and attractive compensation package with clear career road-map – where you feel challenged everyday\n- We offer a strong culture of learning and development: training courses, library, speakers, share and learn events\n- Learn from who sits next to you! Working in WQ you are surrounded by smart and talented people\n- Employee resources groups with strong diversity and inclusion culture\n- Premium Health Insurance and Employee Assistance Program\n- Generous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\n- Team building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\n- Annual company trip and occasional global conferences – opportunity to travel and connect with our global teams\n- Happy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1776, 822, 2, 'Senior/Principal Frontend Engineer (ReactJS/AI)', 'We are looking for a frontend engineer to lead the development of our AI Agent platform/application from the ground up. The ideal candidate has experience building complex web applications, crafting intuitive user experiences, and collaborating effectively with cross-functional teams.\n\nResponsibilities\n- Lead frontend development of the AI Agent platform or application from scratch, ensuring high performance, responsiveness, and usability\n- Design and implement complex UIs that interact seamlessly with backend APIs, real-time agent outputs, and developer toolchains\n- Collaborate with design and product teams to translate user needs and business goals into elegant, scalable interfaces\n- Introduce tools, frameworks, and development practices to improve frontend engineering efficiency and maintainability\n- Mentor and support the growth of team members by helping them deepen their frontend expertise and best practices\n- Take technical leadership across a cross-functional team—including frontend, backend, AI, and SRE engineers—and drive the overall development process\n\nRequirements\nTechnical\nMust have\n- 5+ years of experience in web development\n- 3+ years of experience with React.js and TypeScript\n- Solid understanding of:\n  - Modern frontend architecture and state management (e.g., Redux, Context API)\n  - Component-based UI development and performance optimization\n  - Frontend testing frameworks (e.g., Mocha or Jest)\n  - Browser rendering behavior and accessibility best practices\n- Experience with:\n  - Next.js and Webpack\n  - Git-based development workflows\n  - Docker and containerized development environments\n  - Monitoring and debugging with tools like Datadog, Rollbar\n  - Operating and maintaining frontend applications in production environments\n  - Agile development processes\nNice to have\n- Experience with:\n  - Integration with AI APIs (e.g., LLM-based outputs)\n  - Reading or navigating Python (FastAPI) backend code\n  - MySQL or basic relational database understanding\n- Practical knowledge in:\n  - B2B SaaS product development, especially for back office domains\n  - Collaborating with backend engineers on API design and integration\n  - Performance profiling and web vitals monitoring\n  - Infrastructure as Code (IaC) and CI/CD pipeline automation\nCommunication\n- Experience leading a project as a team lead (required for Leader position)\n- Experience mentoring or educating team members\n- Strong sense of ownership and accountability\n- Business-level English (reading & writing)\n\nOur benefits\nCaring Mental & Physical Recreation\n- Hybrid working: 2 days at the office and 3 days WFH\n- Working hour: Flexible start 8AM-9AM from Mon-Fri\n- Full salary in probation\n- Insurance: Applied from Probation period:\n  - Social Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\n  - Private health insurance & accident insurance. From Managing level: extra for family members\n- Bonus: 13th month salary\n- 16 - 24 paid days off and more\n- Paternity leave: Extra 5 days\n- Annual company trip; Quarterly team building\n- Billiards & Running club\n- Annual health check\n- Well-equipped facility: Macbook pro, additional monitor..\nCaring Career & Development\n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- External & internal training courses\n- Soft-skill workshops\n- Tech seminars\n- Monthly and biannual Recognition Awards\n- Performance & salary review: twice/year (Jun & Dec)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1777, 750, 2, 'QA Engineer (Manual & Automation)', 'Responsibilities:\n- Design and develop automated test scripts based on test cases and requirements.\n- Regularly update and maintain test scripts to ensure they remain effective with application changes.\n- Run automated tests and analyze results to ensure that software meets quality standards.\n- Identify, log, and track defects found during testing and collaborate with developers to resolve them.\n- Document test plans, test cases, and results to ensure comprehensive coverage and traceability.\n- Identify opportunities for improving the efficiency and effectiveness of the test automation process.\n- Review requirements, specifications, and technical design documents.\n- Ensure that validated deliverables meet functional and design specifications and requirements.\n- Keeping updated with new testing tools and test strategies.\n\nQualifications:\n- Bachelor\'s degree in computer science, engineering, or a related field.\n- 2+ years of hands-on experience in QE role.\n- Experience with test automation frameworks like Selenium, Playwright, Appium, or similar.\n- Experience with tools such as JMeter, Postman is preferred.\n- Experience in writing new test cases based on requirements.\n- Integration Test and developing test cases, test plan.\n- Good knowledge of software development methodologies.\n- Experience in applying test techniques on projects.\n- Write test cases and report bugs clearly.\n- Experience with Agile/Scrum development process.\n- Familiar with Bug tracker such as Jira, TestRail...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1778, 674, 2, 'Thực tập sinh Phát triển Mã Coin (Blockchain Developer Intern)', 'Mô tả công việc\n\n- Tham gia vào quá trình thiết kế và phát triển mã coin/token trên các nền tảng blockchain phổ biến như Ethereum (ERC-20), BNB Chain (BEP-20), Solana, hoặc các blockchain khác.\n- Viết và triển khai smart contract bằng Solidity (hoặc các ngôn ngữ phù hợp khác).\n- Hỗ trợ kiểm thử, mô phỏng và tối ưu hóa mã nguồn smart contract.\n- Làm việc cùng các thành viên trong team để phát triển tính năng cho dự án như ví điện tử, DApp, staking, v.v.\n- Nghiên cứu và áp dụng các xu hướng công nghệ mới trong lĩnh vực blockchain, DeFi, Web3\n\nYêu cầu công việc\n\n- Sinh viên năm cuối hoặc mới tốt nghiệp các ngành CNTT, Khoa học Máy tính, hoặc liên quan.\n- Có kiến thức cơ bản về blockchain và smart contract.\n- Biết lập trình một trong các ngôn ngữ: Solidity, JavaScript/TypeScript, Python là lợi thế.\n- Tư duy logic tốt, ham học hỏi, có khả năng tự nghiên cứu.\n- Ưu tiên đã từng thử viết token đơn giản (ERC-20 hoặc tương đương).\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Hỗ trợ dấu mộc xác nhận thực tập, báo cáo thực tập, bài luận văn, chuyên đề, đồ án tốt nghiệp.\n- Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình.\n- Có nhân viên công ty hướng dẫn training trực tiếp truyền đạt kinh nghiệm khi làm việc thực tiễn, được áp dụng kiến thức học tại trường vào các dự án thực tế của công ty.\n- Nâng cao hồ sơ profile công việc, khi hoàn thành thực tập sẽ được công ty hỗ trợ làm người references cho TTS sau khi đi tìm việc ở các công ty khác. Làm việc được trải nghiệm trực tiếp với các lãnh đạo cấp cao của các công ty hàng tỷ đô la trên toàn cầu.\n- Thời gian làm việc linh động, không gò bó, không ép buộc, không deadline, nghỉ lễ, tết đầy đủ theo quy định nhà nước và luật lao động.\n- Hiện chưa có chính sách hỗ trợ phụ cấp thực tập.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quoc Tuan Commune, Haiphong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1779, 713, 2, 'Backend Engineer', 'We are currently seeking a Backend Engineer with a minimum of 3 years of relevant experience to join our team. The successful candidate will hold a bachelor\'s or master\'s degree in computer science, Engineering or a related field. They will be responsible for developing and maintaining our backend services and ensuring the reliability and scalability of our systems.\nResponsibilities And Duties\n• Participate in the requirements analysis, high-level design, detailed design, and the preparation of technical documentation for the project.\n• Responsible for the development of core project modules, delivering technical solutions, and addressing key technical challenges.\n• Design, build, and maintain efficient, reusable, and reliable backend system code.\n• Ensure optimal performance, quality, and responsiveness of applications.\n• Identify system bottlenecks and errors, and formulate solutions. Maintain code quality, organization, and automation.\nRequirements\n• A minimum of two years of backend development experience.\n• Solid foundational knowledge of Java, with a thorough understanding of concepts such as JVM, I/O, concurrency, and multithreaded programming.\n• Proficient in SQL, with strong skills in using databases like MySQL, and a certain level of SQL optimization capability; familiarity with common NoSQL solutions such as Redis, along with an understanding of their respective advantages, disadvantages, and use cases, is preferred.\n• Possess a certain level of oral and written communication skills in English, as well as strong time management abilities.\n• Some basic knowledge of container and Kubernetes\n• Good understanding of Http and restful API.\nPreferred Qualifications\n• Experience with serverless architecture.\n• Expertise in the development, analysis, and design of high-performance systems, ensuring system stability.\n• Experience with AWS network infrastructure.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 3, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1780, 743, 2, '[LQA] Manual Fresher Tester (English)', 'Vị trí tuyển dụng\n\nSố lương\n\nLoại hình\n\nĐịa điểm làm việc\n\n: Fresher Tester có tiếng Anh\n\n: 05\n\n: Full-time\n\n: Hà Nội.\n\nMÔ TẢ CÔNG VIỆC\n\n– Tham Gia Kiểm Thử, Test Các Phần Mềm, Hệ Thống Phần Mềm Cho Các Project. Cụ Thể Hơn\n\n– Xây dựng kịch bản test, xây dựng tool test tự động cho ứng dụng: web, mobile\n\n– Thực hiện test các sản phẩm, dịch vụ theo yêu cầu.\n\n– Nghiên cứu và cập nhật các công cụ test và kiến thức mới hỗ trợ cho công việc.\n\n– Làm việc nhóm hoặc độc lập, giao tiếp với cấp trên và thành viên liên quan đến công việc test.\n\nYÊU CẦU\n\n– Tốt nghiệp các trường ĐH, cao đẳng Công nghệ thông tin, ngoại ngữ,…\n\n– Biết thiết kế, thực hiện kế hoạch kiểm thử, các trường hợp, kịch bản và quy trình kiểm thử trên các ứng dụng, phần mềm dự trên yêu cầu nghiệp vụ\n\n– Hiểu biết về kiểm thử phần mềm như (Unit Test, Integration Test, Funtional Test, System Test…)\n\n– Tiếng anh giao tiếp tốt\n\nQUYỀN LỢI\n\n– Mức lương 5 -9M, thỏa thuận theo năng lực\n\n– Được tham gia vào các dự án lớn vói các khách hang nước ngoài.\n\n– Môi trường công bằng, đảm bảo mọi người đều có thể phát huy hết khả năng của mình\n\n– Được làm việc với những cá nhân xuất sắc, có nhiều kinh nghiệm.\n\n– Lương tháng 13, thưởng lễ tết…\n\n– Quy đổi ngày phép thành tiền\n\n– Được hưởng Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n\n– Môi trường làm việc năng động, các hoạt động: Teambuilding 3 tháng 1 lần, bóng đá, du lịch hàng năm…\n\n– Khám sức khỏe định kỳ 1 năm/1 lần\n\nCONTACT\n\nLQA Recruitment Department\n\nPhone Number: 02466607474\nEmail: lqa.rec@lqa.com.vn/ rec.lqa@lqa.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1781, 723, 2, 'Python Developer', 'Mô Tả Công Việc\n\n- Thiết kế và phát triển dịch vụ API phụ trợ hiệu suất cao\n- Có kinh nghiệm làm việc với các hệ thống phân tích thống kê, bigdata, nosql, spark\n- Duy trì một cơ sở mã hóa mạnh mẽ chất lượng cao\n- Tích cực nghiên cứu và áp dụng công nghệ mới, bộ công cụ mới\n\nQuyền Lợi\n\n- Mức thu nhập lên tới 2.500 USD\n- Có cơ hội được xem xét nâng lương 2 lần 01 năm, tùy vào kết quả công việc.\n- Cơ hội được đào tạo và thăng tiến trong công việc\n- “NMS care” bảo hiểm dành riêng cho nhân viên NMS.\n- Nghỉ hè: Theo chính sách của công ty ( vào tháng 5 hàng năm).\n- Cơ hội tại chỗ tại Nhật Bản (ngắn hạn: 2-3 tháng không có tiếng Nhật; dài hạn:> 1 năm)\n- Văn hóa công ty tốt với các hoạt động trong / ngoài văn phòng giúp phát triển khả năng và khả năng sáng tạo của ứng viên\n- Môi trường làm việc hiện đại, thân thiện.\n- Chính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.\n\nYêu Cầu\n\n- Kinh nghiệm làm việc với Python trong 1-2 năm.\n- Hiểu biết tốt về asyncio, coroutine, GIL, regex, quản lý bối cảnh, ..\n- Kinh nghiệm làm việc với MySQL, MongoDB, Redis\n- Có kiến thức về OOP, RESTful, Mẫu thiết kế\n- Có kinh nghiệm làm việc với Websocket / AMQP / MQTT là ưu thế\n- Kinh nghiệm làm việc trong các dự án mô hình Agile\n- Khả năng làm việc nhóm và làm việc độc lập\n- Có thể làm việc dưới áp lực cao về thời hạn cũng như chất lượng sản phẩm\n- Khả năng làm việc tốt và chủ động trong công việc, có tinh thần trách nhiệm cao trong việc hoàn thành công việc được giao\n\nĐịa điểm làm việc: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình, Hà Nội\n\nỨng Tuyển Ngay\nMs Huyền: 0338 323 955/ 0969709429 / mail:huyenlt@nms.com.vn / skype:huyenthu.hr\n\n——————————–\n\nCông ty cổ phần Dịch vụ Di động Thế Hệ Mới (NMS)\n\n🏬 Hệ Thống Trụ Sở\n\n– Trụ sở chính NMS: Tầng 3A Mỹ Đình Plaza, 138 Trần Bình, Hà Nội\n\n– Chi nhánh NMS Hòa Lạc: Tầng 8, Tòa nhà HTC Phú Cát, Khu công nghệ cao Hòa Lạc, Thạch Thất, Hà Nội\n\n– Chi nhánh NMS TP. Hồ Chí Minh: Lầu 3 – 385C – Nguyễn Trãi Quận 1 – TP. HCM\n\n– Chi nhánh Nhật Bản: 3F Hoshino Building, Nishi Shinjuku, Shinjuku, Tokyo\n\n☎ Điện thoại: 024.7300 8555\n\n🌎 Website: https://nms.com.vn/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1782, 935, 2, 'HCM-REQ Senior NodeJS', 'Job Description\n\n- Developing and maintaining all server-side network components.\n- Ensuring optimal performance of the central database and responsiveness to front-end requests.\n- Collaborating with front-end developers on the integration of elements.\n- Designing customer-facing UI and back-end services for various business processes.\n- Developing high-performance applications by writing testable, reusable, and efficient code.\n- Implementing effective security protocols, data protection measures, and storage solutions.\n- Running diagnostic tests, repairing defects, and providing technical support.\n- Documenting Node.js processes, including database schemas, as well as preparing reports.\n- Recommending and implementing improvements to processes and technologies.\n- Keeping informed of advancements in the field of Node.js development.\n\nRequirements\n\n- Bachelor\'s degree in computer science, information science, or similar.\n- At least 5 years\' experience as a Node.js developer.\n- Extensive knowledge of JavaScript, web stacks, libraries, and frameworks.\n- Knowledge of front-end technologies such as HTML5 and CSS3.\n- Superb interpersonal, communication, and collaboration skills.\n- Exceptional analytical and problem-solving aptitude.\n- Great organizational and time management skills.\n- Availability to resolve urgent web application issues outside of business hours.\n\nBenefits\n\n- “FPT care” health insurance provided by AON and is exclusive for FPT employees.\n- Annual Summer Vacation: follows company’s policy and starts from May every year.\n- Salary review 2 times/year or on excellent performance.\n- International, dynamic, friendly working environment.\n- Annual leave, working conditions follow Vietnam labor laws.\n- Other allowances: lunch allowance, working on-site allowance, etc.\n\nMore\n\nSalary\n\nCompetitive salary.\n\nWorking Address\n\nCountry: Vietnam\n\nProvince: Hồ Chí Minh\n\nDistrict: Thủ Đức\n\nAddress: Ftown 2 - đường D1, khu công nghệ cao, Phường Tân Phú, Thành phố Thủ Đức, Thành phố Hồ Chí Minh, Việt Nam\n\nWays Of Working\n\nFull-time (0)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thu Đuc, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1783, 991, 2, 'Senior Java Developer', 'Job Title: Senior Java Developer\n\n1. What are we looking for?\n- Have 7+ years of hands-on experience in backend software development\n- Experience in modern JVM, Java 7-8+\n- Experience in Relational Database\n- Experience in Microservices Architecture\n- Well-versed in Git/Gitlab and CD/CI concepts, tools and pipelines\n- Experience in the development of mission-critical software systems\n- Experience in designing and building performant systems\n- Abstract thinking skills and academic level in computer science or other engineering studies\n- Experience in Workflow Engines, Kafka is a plus\n- Good verbal and written English communication skills\n- Strong team player and experienced working with teams on and across sites.\n- Experience working with Docker and Kubernetes in a production environment is a plus\n- Exposure to Virtualization / Cloud platforms such as Azure, AWS or GCP is a plus\n- Experience in language engineering is a plus\n\n2. Benefits:\nSalary & Allowances:\nIncome: negotiable\n- 13th-month salary + end-of-year performance bonus.\n- Lunch allowance: 500,000 VND/month.\n- Holiday bonuses (April 30 & May 1, September 2, etc.).\n- Paid leave: 12 days of annual leave.\n- Health: Social insurance, health insurance, annual health check-up.\n- Recreation: Annual company trips, and quarterly team-building activities.\n- Laptop, monitor, and necessary equipment for work.\n\nCareer Growth Opportunities:\n- Annual salary reviews and defined promotion pathways.\n- Diverse options for career advancement.\n- Sponsorship for advanced training and professional skill enhancement.\n\nWorking Environment:\n- Open workspace.\n- A vibrant and dynamic work atmosphere.\n- Language classes: English, Dutch, etc.\n- Clubs: badminton, soccer, pickleball, esports, etc.\n\n3. Work Location:\n• Location: Level 12A Song Da Building, 18/165 Cau Giay Str, Cau Giay Dist, Ha Noi,\nViet Nam\n• Work Hours: 09:00 AM - 06:30 PM from Monday to Friday, remote on Wednesdays.\n\n4. Contact\nMail: haiyendt.hr@gmail.com\nPhone: 0354.682.402 (Ms.Yen)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Bắc Từ Liêm, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1784, 781, 2, 'Chuyên Viên Phát Triển Phần Mềm (Mobile Developer)', 'Nơi làm việc\n\nHà Nội\n\nCấp Bậc\n\nNhân viên\n\nHình Thức\n\nNhân viên chính thức\n\nKinh Nghiệm\n\n3 - 5 Năm\n\nMức Lương\n\nLương thỏa thuận\n\nNgành nghề\n\nCNTT - Phần mềm\n\nHạn chót nhận hồ Sơ\n\n30/06/2025\n\nPhúc Lợi\n\n Bảo hiểm\n Du Lịch\n Thưởng\n Chăm sóc sức khỏe\n Đào tạo\n Tăng lương\n Chế độ nghỉ phép\n\nMô tả công việc\n\n Phát triển và triển khai phần mềm:\n Viết code theo yêu cầu kỹ thuật.\n Tối ưu hóa hiệu năng ứng dụng.\n Xây dựng và duy trì API.\n Phát triển tính năng mới.\n Sửa lỗi và nâng cấp hệ thống.\n Đảm bảo chất lượng Code:\n Thực hiện code review.\n Viết unit test và integration test.\n Tuân thủ coding standards.\n Tối ưu hóa mã nguồn.\n Đảm bảo security coding.\n Phân tích và thiết kế:\n Phân tích yêu cầu kỹ thuật.\n Thiết kế giải pháp phần mềm.\n Xây dựng tài liệu kỹ thuật.\n Đánh giá khả thi giải pháp.\n Hợp tác và phát triển:\n Làm việc trong nhóm Agile/Scrum.\n Phối hợp với các bộ phận liên quan.\n Chia sẻ kiến thức với đồng nghiệp.\n Mentor cho thành viên mới.\n Tham gia các buổi review sprint.\n Nghiên cứu và cải tiến:\n Cập nhật công nghệ mới.\n Đề xuất cải tiến quy trình.\n Nghiên cứu giải pháp tối ưu.\n Thử nghiệm công nghệ mới.\n Đóng góp ý tưởng sáng tạo.\n\nYêu cầu công việc\n\n Trình độ học vấn/Chứng chỉ \nTốt nghiệp đại học chuyên ngành Công nghệ thông tin, Kĩ thuật phần mềm, Hệ thống thông tin hoặc các ngành có liên quan.\n Kinh nghiệm làm việc \nTối thiểu 3-5 năm kinh nghiệm làm việc trong lĩnh vực phát triển phần mềm.\n Kiến thức/Năng lực chuyên môn/Kỹ năng \nKỹ năng lập trình Mobile: sử dụng thành thạo ngôn ngữ Swift cho IOS, Kotlin cho Android, Dart (Flutter) với cross-platform.\nTích hợp hệ thống.\nThiết kế và kiến trúc phần mềm.\nNghiên cứu công nghệ mới.\nXử lý sự cố, phân tích và giải quyết vấn đề.\nTư duy phân tích.\nTư duy sáng tạo.\nKỹ năng giao tiếp, thích ứng nhanh với môi trường. Có tư duy làm sản phẩm.\n Năng lực cốt lõi \nCó tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty (IPAM & 4C). \n\nLỢI ÍCH VÀ QUYỀN LỢI \n\nCộng đồng những người làm nghề chính trực và dấn thân phụng sự \nMôi trường làm nghề tài chính chuyên nghiệp. \nLàm việc với tinh thần làm chủ, sáng tạo và thách thức. \n Tổng thu nhập theo năng lực \nThu nhập xứng đáng theo năng lực và giá trị đóng góp. \nXem xét thay đổi thu nhập hàng năm. \n Chế độ đãi ngộ \nTham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động. \nĐược tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24. \n Tổ chức học tập và văn hóa sôi nổi\nKhông gian làm việc mở với trang thiết bị hiện đại. \nCác hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1785, 683, 2, '[HCM] Senior Software Engineer (Backend)', 'Level up your career with Garena! \n\nAt Garena, we’re on a mission to redefine gaming and digital experiences for millions of players worldwide. We’re seeking a passionate and skilled Senior Software Engineer (Backend) who thrives in a fast-paced environment to build innovative, game-changing systems. If you’re excited about creating robust and scalable platforms, working with cutting-edge tech, and solving complex problems to deliver the ultimate experience for gamers, this role is for you!\n\nJob Description\n\nWhat You’ll Do:\n\n- Code for the win: Design and develop backend services, systems, and platforms that power our gaming products and elevate the player experience. \n- Craft quality gameplay: Write clean, efficient, and maintainable code while building reusable libraries and tools. \n- Stay on the leaderboard: Analyze requirements and develop high-performance features tailored to product needs. \n- Optimize the grind: Continuously identify bottlenecks, troubleshoot issues, and improve system stability and performance. \n- Build for teamwork: Collaborate with cross-functional teams to design and implement robust features. \n- Unlock new tools: Develop supporting utilities and systems to streamline operations and enhance development efficiency.\n\nJob Requirements\n\nWhat Makes You a Pro:\n\n- Educational Background: Bachelor’s degree in Computer Science or related field.\n- Experience: 3+ years in web technologies and security, with hands-on experience in gaming-related industries a plus.\n- Technical Expertise: \n  - Solid foundation in Computer Science (data structures, algorithms, operating systems, networks, databases).\n  - Proficient in programming languages like Python, Node.js, C++, Go, or Java.\n  - Skilled in Linux environments, multi-threaded programming, and web servers (e.g., Apache, NGINX, HAProxy).\n  - Understanding of network protocols (TCP, UDP, HTTP) and experience with distributed systems.\n- Mindset & Soft Skills: \n  - Passion for gaming, innovation, and solving complex problems with code.\n  - Proactive, detail-oriented, with a “Can Do” attitude and strong multitasking abilities.\n  - Quick learner with excellent communication and team collaboration skills.\n  - Bonus: Project management experience and leadership capabilities.\n\nWhat We Offer:\n\n- Impactful & Challenging Work: Join a dynamic environment where your contributions can shape the gaming experiences of millions.\n- Opportunities for Growth: Embark on a journey of personal and professional development across various business tracks.\n- Vibrant Culture: Connect with like-minded individuals in a lively and inclusive workplace, where we work hard and play hard.\n- Autonomy: Take charge of your projects and make your mark on the gaming industry.\n- Competitive Package: Enjoy competitive salaries, modern facilities, office perks, and medical benefits.\n\nIf you’re ready to take your engineering career to the next level and contribute to unforgettable gaming experiences, apply now and let’s create the future of gaming together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1786, 992, 2, 'Senior Full Stack Developer (C# & ReactJS)', 'A Bit About Us\n\nWe\'re a world-leading smart mobility SaaS tech company with almost 2,300,000 active users. Our teams are collaborative, vibrant and fast-growing, and all team members are empowered with the freedom to influence our products and technology.\n\nAre you curious, innovative and passionate?\n\nDo you take ownership, embrace challenges, and love problem-solving? We\'re looking for a Full Stack Developer who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.\n\nYou want to\n\nDesign and develop scalable, feature-rich web applications using ReactJS and Redux\nDesign, build and maintain efficient backend applications using C#\nIntegrate frontend and backend applications while maintaining good performance\nDevelop complex SQL queries as required\nWork with UXUI designers to implement user-friendly solutions\nAnalyze reported bugs and issues, and build sustainable solutions for complex problems \nOptimize application performance by improving and restructuring at the database and API level\nIntroduce new technologies into the team based on fit and suitability to deliver a solution\nGuide junior team members and establish good coding standards within the team\nGenerate comprehensive technical documentation\n\nYou have\n\nBS Computer Science degree or equivalent industry experience\nJavaScript experience, including concepts such as asynchronous programming, closures, types and ES6\nHTML/CSS experience, including concepts like cross-browser compatibility and layout\nExperience in/with more than one of the following will be advantageous:\nMapping technologies (Google Maps, Here Maps, Leaflet)\nAgile development methodologies\nDistributed source control systems (Git)\nPerformance/analytics tools for web applications\nContinuous integration\nUnit testing, test driver development, static code analysis\nC# experience\nLinux server experience\nAbility to deep dive into the technical aspects needed for optimization of web applications\nUnderstand business requirements and how they translate into a technical approach\nCreative thinking backed by strong analytical and problem-solving skills.\nStrong teamwork, coordination, and planning, self-driven, and ability to work at pace in a dynamic organization.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ホーチミンシティ都市圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1787, 674, 2, 'Hiring Junior: AI Engineer – Machine Learning Specialist', 'Mô tả công việc\n\nKey Responsibilities\n\n- Design, develop, test, and deploy machine learning models for various applications, with a focus on natural language processing and conversational AI\n- Build and optimize chatbot systems and conversational agents to improve user experience and engagement\n- Improve the performance of existing machine learning models through continuous refinement and innovation\n- Implement and maintain scalable machine learning pipelines and infrastructure to support our growing AI capabilities\n- Stay current with the latest advancements in machine learning, deep learning, and NLP technologies\n- Conduct model training, validation, and performance evaluation to ensure models meet required accuracy and reliability standards\n- Create and maintain comprehensive documentation related to machine learning models, algorithms, and processes\n- Develop and manage A/B testing frameworks for evaluating model performance in production environments\n\nYêu cầu công việc\n\nQualifications\n\n- Experience in AI and machine learning development\n- Proven 2–3 years of experience as a Machine Learning Engineer, AI Engineer, or in a similar role, with a demonstrated track record of successful projects and impactful results\n- Good programming skills in Python and proficiency with machine learning libraries and frameworks such as TensorFlow, PyTorch, and scikit-learn\n- Proven experience with NLP libraries and tools (e.g., NLTK, spaCy, Hugging Face Transformers)\n- Experience developing and deploying chatbots or conversational AI systems\n- Hands-on experience with language models like GPT, BERT, or similar transformer-based architectures\n- Familiarity with SQL databases and API integration\n- Experience with Azure platforms and deploying models in production environments\n- Solid understanding of machine learning algorithms, deep learning architectures, and statistical methods\n- Experience with version control systems (e.g., Git) and CI/CD pipelines\n- Excellent communication skills and ability to work effectively with cross-functional teams\n\nĐể làm việc tại đây\n\nAbout KHantix\n\nKhantix is set to revolutionize the data analytics landscape. Specializing in innovative solutions using Microsoft Data Analytics services, KHantix is dedicated to building a data-native company in the AI-first era. Our focus is on harnessing the power of data to create impactful solutions that drive business success.\n\nWhy KHantix?\n\n- Innovative Environment: Work with the latest Microsoft Data Analytics services and cutting-edge technologies.\n- Growth Opportunities: Be part of a growing company with ample opportunities for professional development.\n- Collaborative Culture: Join a team that values collaboration, creativity, and continuous improvement.\n- Impactful Work: Contribute to projects that make a real difference for businesses and communities.\n\nAbout The Role\n\nWe are seeking a talented AI Engineer to join our team and lead the development, implementation, and optimization of our machine learning projects. As an AI Engineer, you will be responsible for building efficient, data-driven artificial intelligence systems that enhance our product capabilities and drive innovation. The ideal candidate will have a strong background in machine learning, data science, and software development, with expertise in conversational AI and chatbot technologies.\n\nPreferred Qualifications\n\n- Advanced knowledge of natural language processing (NLP) and conversational AI applications\n- Experience with MLOps tools and best practices for scalable model deployment and monitoring\n- Familiarity with data privacy and security regulations\n- Experience with dialog management systems and conversation flow design\n- Knowledge of real-time data processing and streaming technologies\n- Experience with reinforcement learning for conversational agents\n- Experience with chatbot analytics and performance optimization\n\nJoin Our Team\n\nAt KHantix, we are on an exciting journey to redefine data analytics. We are looking for passionate and talented individuals to join our dynamic team. If you’re driven by innovation, eager to make a difference in the world of data, and passionate about AI, machine learning, and building intelligent conversational systems, we’d love to hear from you!\n\nWhat We Offer\n\n- Competitive salary, project bonuses, 13th-month salary and other attractive incentive schemes,…\n- Comprehensive insurance policies, including personal and family health coverage\n- Opportunity to work with cutting-edge Microsoft data technologies\n- Collaborative and innovative work environment\n- Professional development opportunities in a rapidly growing company\n- Work-life balance', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1788, 831, 2, 'Senior Java Software Engineer', 'We, VINOVA (VIbrant inNOVAtors), earn respect from customers for being committed to quality, flexibility and speed. We strike to build killing products by working closely with customers, by working passionately, and by collaborating openly and disciplinary.\n\nVinova is among the Top 10 Mobile Applications Development Companies in Singapore – according to Medium.com.\n\nQualification requirements\n- At least 6 years of experience as a Java Developer\n- Understanding one of the relational databases (PostgreSQL, MySQL, Oracle, SQL Server, DB2)\n- Good communication in English\n- Degree in Computer Science or related field\n- Experience with designing database structures\n- Analytical mindset and good problem-solving skills\n- Good organizational skills\n- Ability to work both independently and as part of a team\n\nResponsibilities\n- Design, develop and test Java-based solutions using common standards and frameworks such as JPA, J2EE, Spring Boot, Spring MVC, Hibernate, …\n- Translate software requirements into working and maintainable solutions within the existing application frameworks\n- Implement the product’s lifecycle: Design, development, quality, deployment and maintenance\n- Develop and adhere to best practices for developing applications\n- Continuously contribute to team performance improvement and collaboration\n- Collaborate effectively across teams\n\nWhy you will love working here:\n- Nice and friendly working environment.\n- Competitive salary with multiple bonus scheme\n- Lots of interesting and challenging projects to work on.\n- 13th-month salary benefits\n- Chance to work onsite abroad\n- We have a fun, Silicon Valley-style startup culture that values openness, fun, and awesomeness.\n- Attractive salary and annual salary review.\n- Provide devices for work.\n- Chance to become the leader of startup culture.\n- A fun, awesome work environment with multiple exciting bonus scheme\n- Progressive and international working environment.\n- Exciting company activities.\n- Free in-house entertainment facilities (football), coffee, and snacks (instant noodles, cookies, candies…)\n\nOpportunities:\n- Direct coaching from top management\n- Chance to work overseas based on the request from the client\n- Chance to improve technical skills while working with clients on new technology, and exciting workshops, and seminars.\n- Chance to become leader of a dynamic and growing company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ダナン都市圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1789, 993, 2, 'Backend Developer (Golang/Python)', 'Về VCS\nCông ty An Ninh Mạng Viettel (Viettel Cyber Security) là đơn vị nghiên cứu, phát triển chuyên sâu các sản phẩm, dịch vụ An toàn thông tin toàn trình, đồng thời trực tiếp cung cấp sản phẩm, dịch vụ ATTT toàn trình thế hệ mới cho các tổ chức doanh nghiệp lớn trong và ngoài nước.\nLý do nên gia nhập VCS\nTham gia đội ngũ Backend tại VCS, bạn sẽ có cơ hội và thử thách như sau:\n   - Nhiều bài toán mới, khó: Scalable, High-performance, Real Time processing ...\n       + Mục tiêu xử lý 200k eps\n       + Chống tấn công ddos: 60GB/s,\n   - Được giao quyền chủ động thực hiện công việc, đề xuất các ý tưởng mới\n   - Đóng vai trò quan trọng trong việc phát triển phần mềm. Đem lại giá trị, đáp ứng kỳ vọng của khách hàng\n\nI/ Mô tả công việc\n   -  Nghiên cứu và phát triển các sản phẩm phần mềm trong lĩnh vực An ninh mạng (thực hiện giám sát và phát hiện tấn công; quản lý ATTT cho tổ chức/doanh nghiệp)\n   - Làm việc với team phát triển phần mềm tiếp nhận, phân tích và tạo ra các thiết kế/kiến trúc mới hướng đến quy mô và hiệu suất\n   - Thực hiện tối ưu về mặt kiến trúc hiệu năng cho các hệ thống lớn\n   - Nghiên cứu, áp dụng các công nghệ mới vào phát triển sản phẩm (microservice, cloud native, CI/CD)\n   - Làm việc theo mô hình Agile-Scrum\n   - Có cơ hội tham gia xử lý các bài toán mới, khó như: Scalable, High-performance, Real-time Processing...\n\nII/ Yêu cầu chuyên môn và kỹ năng\n1. Trình độ học vấn\n    - Tốt nghiệp Đại học chính quy loại Khá trở lên, chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Toán - Tin...\n\n- Tiếng Anh tương đương 550 TOEIC trở lên\n2. Kiến thức chuyên môn\n- Từ 3 năm kinh nghiệm lập trình Backend\n- Có kiến thức sâu về Golang/ Python\n- Có kiến thức về NodeJS, Java, C# hoặc các ngôn ngữ BE tương đương khác là điểm cộng\n- Có kiến thức về OOP, Microservices, Design pattern và thiết kế hệ thống.\n- Có kinh nghiệm tối ưu hệ thống hoặc tham gia phát triển dự án lớn, số lượng người dùng đáng kể. Biết sử dụng công nghệ Database (SQL, NoSQL), Redis, Message Queue (Kafka, RabbitMQ), các công cụ DevOps (Docker, Docker Compose, K8s)\n- Có khả năng viết clean & maintainable code, tập trung vào hiệu suất, có thể tái sử dụng và dễ hiểu với kiểm thử đơn vị (unit test)\n- Có định hướng rõ ràng, sẵn sàng học hỏi những điều mới và yêu thích sản phẩm\n- Tư duy logic và giải quyết vấn đề tốt, nắm bắt công nghệ nhanh\n- Hiểu biết cơ bản về khách hàng mình phục vụ\n3. Điểm cộng:\n- Kiến thức, kinh nghiệm lập trình an toàn\n- Kiến thức về network, giao thức mạng\n- Có khả năng sử dụng thành thạo các công cụ phục vụ triển khai CI/CD\n- Đã từng giải quyết một trong các bài toán sau, bao gồm nhưng không giới hạn: tối ưu performance, thiết kế hệ thống lớn, xử lý dữ liệu lớn, thuật toán, scaling, các vấn đề kĩ thuật khó\n- Nắm được cơ chế index của database, đã từng giải quyết các bài toán phân tích và tối ưu query\n- Kỹ năng thấu cảm\n- Kỹ năng hợp tác, làm việc liên bộ phận nhằm đạt được kết quả chung tốt nhất\n\nIII/ Lương thưởng và Phúc lợi\n● Lương và thưởng:\n -  Offer theo gói tổng thu nhập năm, lên tới 600 triệu gross/năm\n -  Review lương định kỳ vào tháng 3 hàng năm\n -  Giải thưởng nhân viên xuất sắc tháng/năm: 02-10 triệu đồng\n -  16 ngày nghỉ 1 năm (12 ngày nghỉ phép theo quy định Luật Lao động + 3 ngày nghỉ dưỡng+Ngày truyền thống 22/12)\n - Đóng BHXH đầy đủ theo quy định, Bảo hiểm sức khỏe và tai nạn cá nhân của MIC (Hạn mức chi trả lên đến 600 triệu/năm)\n -  Khám sức khỏe định kỳ hàng năm\n● Phát triển sự nghiệp:\n - Được tài trợ 100% đối với các chứng chỉ xếp hạng chuyên môn quốc tế chuyên sâu theo từng vị trí, Khen thưởng với CBNV đạt chứng chỉ chuyên môn quốc tế\n -  Liên tục đầu tư học liệu mới nhất, cập nhật nhất trên thị trường về lĩnh vực ATTT từ các nhà cung cấp, các học viện/uy tín hàng đầu thế giới\n -  100% cán bộ nhân viên được cấp tài khoản Elearning từ Udemy - học thỏa sức mọi lúc mọi nơi\n -  Miễn phí tham gia các chương trình chia sẻ kiến thức chuyên ngành, các hội thảo chuyên môn từ các diễn giả đầu ngành trong nước và quốc tế\n● Môi trường và văn hóa làm việc\n -  Trang phục thoải mái, tự tin thể hiện cá tính\n -  Thời gian làm việc linh hoạt (VCSer chọn giờ làm việc giữa 2 khung giờ sau 8h30-18:00 hoặc 9h00-18h30)\n -  Khu vực riêng dành cho Tập Gym, giải trí (chơi Bi-a, Pes, Bóng bàn, Café, Đọc sách...)\n -  Các CLB: Chạy, Cầu lông, Game, Bi lắc, Bơi, Sách...\n -  Tham gia các event Công ty: hoạt động Teambuilding hàng quý, Sinh nhật hàng tháng, Year End Party, nghỉ mát, ngày lễ 08/03, 20/10 (các chị em được nghỉ 1⁄2 ngày), ngày sinh nhật tập đoàn 01/06, v.v\n\nV/ Địa chỉ làm việc\nVăn phòng Hà Nội: Tầng 41, Tòa Keangnam Landmark 72, Đ. Phạm Hùng, Q. Nam Từ Liêm, Hà Nội\nThời gian làm việc: Flexible khung từ 8h30-9h đến 18h-18h30. Từ Thứ 2 - Thứ 6', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1790, 994, 2, 'Mobile Fullstack Developer', 'Tips: Provide a summary of the role, what success in the position looks like, and how this role fits into the organization overall.\n\nResponsibilities\n• 1–2 years or more of experience developing mobile apps with React Native or Flutter.\n• Proficient in JavaScript/TypeScript or Dart.\n• Experience with backend using Node.js, Express/NestJS, or PHP (Laravel), or Firebase.\n• Understand how to communicate with RESTful/GraphQL APIs.\n• Manage source code with Git.\n• Have good knowledge of database design (MySQL, PostgreSQL or NoSQL like MongoDB).\n• Understand state management (Redux, Bloc, Provider...).\n• Know how to handle push notifications, background tasks, permissions, deep linking...\n• Experienced in placing ads in apps\n\nJob requirements:\nRequired:\n• Have at least 1–2 years of experience developing mobile apps with React Native or Flutter.\n• Proficient in JavaScript/TypeScript or Dart.\n• Experience with backend using Node.js, Express/NestJS, or PHP (Laravel), or Firebase.\n• Understand how to communicate RESTful API / GraphQL.\n• Manage source code with Git.\n• Have good knowledge of database design (MySQL, PostgreSQL or NoSQL like MongoDB).\n• Understand state management (Redux, Bloc, Provider...).\n• Know how to handle push notifications, background tasks, permissions, deep linking...\n\nPriority:\n• Have deployed apps to App Store / Google Play.\n• Know CI/CD mobile apps (Fastlane, CodePush...).\n• Experience with Firebase (Authentication, Firestore, FCM...).\n• Understand security for mobile apps (JWT, OAuth2, data encryption...).\n• Basic DevOps skills: Docker, VPS, deployment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1791, 983, 2, 'Senior Java Engineer（Listed Company）', 'Company background\nThis is a prominent, publicly traded company headquartered in the United States, specializing in providing cutting-edge information technology services exclusively for the real estate industry. We take immense pride in our core team\'s stability, fostering a vibrant technical atmosphere, as well as cultivating a supportive team culture. We are here to welcome exceptional individuals like you to become part of our dynamic team and contribute to our collective success.\n\nRemote working culture\nOur company has fully embraced remote work as the norm for engineering, and we have dedicated ourselves to nurturing a strong remote working culture. We firmly believe that telecommuting offers numerous benefits, such as saving commuting time and alleviating congestion. In this way, we empower our team members with greater flexibility to strike a healthy work-life balance and enjoy more quality time with their loved ones. Additionally, we encourage our team members to explore their hobbies and discover new experiences, fostering personal growth and a broader perspective on the world. Join us to enjoy the benefits of remote work while seizing opportunities for both professional and personal development.\n\nWorking Requirements\n1. Working Location: Anywhere in Vietnam, remote. Candidates must be either Vietnamese citizens or hold a valid work visa for Vietnam. Applications from other countries will not be considered.\n2. Working Hours: You are expected to work an average of 8 hours a day, allowing for flexibility and autonomy. However, it is important to allocate time for daily communication and prompt response with the team, ensuring efficient task completion.\n3. Job Nature: Full-time, requiring 40 hours of work per week.\n4. Language requirements: Fluent English for communication with international teams.\n5. We will provide the Macbook for work.\n\nTechnical requirements\n1. Possesses strong logical thinking, is skilled at analyzing and solving problems, and has good communication abilities.\n2. Demonstrates strong English proficiency and can communicate fluently with team members and stakeholders across various regions, particularly with the US team.\n3. Proficient in Java with extensive experience in back-end and API development; familiar with the Java ecosystem with a deep understanding of commonly used frameworks and libraries; skilled in business modeling, with strong abilities in unit testing and integration testing.\n4. Solid knowledge of data structures, programming skills, engineering capabilities, and clean coding practices.\n5. Familiar with Docker, AWS S3, RDS, and related frameworks and components.\n6. Proficient in common Git commands and workflows, particularly those related to GitHub pull requests.\n\nBonus experience\n1. Remote Working Experience: Prior experience with remote work is preferred.\n2. Available to work during the US Eastern Time Zone (9 pm and 5 am Vietnam Time) or at least a 5-hour overlap between 9 pm and 2 am Vietnam Time for effective collaboration across teams in different time zones.\n3. We will provide a Macbook laptop for work after joining the company.\n4. We offer 12–20 days of bonus hours, which means you can take time off with pay.\n\nSalary and Benefits\n1. The employment contract will be administered through a Singapore-based human resources firm. Compensation will be based on an hourly wage framework, with the default presumption of full-time employment (8 hours a day, 40 hours a week).\n2. The hourly rate for this position ranges from approximately USD $13 - $25 per hour, depending entirely on the individual’s skill level.\n\nRecruitment process\n1. After receiving a recommendation from the talent pool, and if you meet our basic requirements, we will send you an interview question.\n2. You will have 7 days to complete the task and submit it to us via a GitHub pull request. We encourage you to demonstrate your best coding practices, including task decomposition, code quality, testing, documentation, Git commits, and effective communication. This stage is crucial for assessing potential candidates.\n3. Our team members will conduct a thorough code review and provide internal feedback.\n4. Once a final decision has been made, we will notify you. If your code meets our standards, we will schedule a remote video interview in English.\n5. The remote video interview aims to explore your technical abilities and overall skills in greater detail, as well as discuss salary expectations.\n6. If you perform well in the interview and choose to join our team, you will need to sign a contract prior to starting.\n\nFAQ\nQ: How will I be paid since the hourly rate is in USD?\nA: The Singapore-based resourcing company will offer you a platform that converts USD into your local currency when you choose to withdraw it. Since our salaries are paid in US dollars, the real-time exchange rate will affect the conversion to Vietnamese dong (VND).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1792, 995, 2, 'Software Engineer', 'About the job: Junior/Senior Software Engineer at Eureka Robotics\nLocation: Hanoi office, Vietnam\n\nAbout Eureka Robotics:\nEmpowered by Robotics and AI research from NTU Singapore, MIT, and the University of Tokyo, Eureka Robotics delivers robotic software and systems to automate tasks that require High Accuracy and High Agility (HA-HA).\n\nWith offices in Singapore,Vietnam, Japan, USA and distribution partners in China and the USA, Eureka Robotics prides itself on helping clients, globally, achieve vastly improved productivity, lower costs, and better safety. Common uses include Inspection, Precision Handling, 3D Picking, Assembly, or Dispensing.\n\nWant to know more about us? Visit https://www.eurekarobotics.com or follow us on https://www.linkedin.com/company/eurekarobotics.\n\nRoles:\nAs a Software Engineer, you will develop software for the Eureka Controller and Eureka Camera, offering advanced functionalities in device control, robotics, computer vision, and AI for industrial automation. Responsibilities include software design, development, testing, and production support.\n\nJob responsibilities:\n・Design, develop and maintain software in Python and C++ for low-code robotics programming, device control, computer vision and other related technologies.\n・Collaborate with product and other development teams to meet customer expectations.\n・Assist test engineers in integration and stress testing.\n・Work closely with external and internal users to troubleshoot and address issues in production.\n\nRequirements:\nFresh graduates are welcome to apply if they meet the minimum requirements.\n\nMinimum:\n・BSc degree or higher in Computer Science, Computer Engineering, Software Engineering or related fields.\n・1+ years of software development experience (including internships) or good track record of relevant achievements (e.g., competitive programming contests, Hackathons).\n・Proficiency in Python, C++ or a similar programming language. Familiarity with git and shell scripting.\n・Background in algorithmics (complexity) and mathematics (linear algebra, probability, statistics).\n・Intermediate level of English proficiency, both reading and writing.\n\nPreferred:\n・3+ years of software development experience (including internships) or strong track record of relevant achievements (e.g., competitive programming contests, Hackathons).\n・Strong proficiency in Python and C++ programming.\n・Familiarity with Qt framework.\n・Good understanding of the following topics: concurrency, containerization with docker/podman, and/or networking. (Required for middle to senior, nice to have for junior) Software engineering mindset: Testing, trade-off in code design and implementation, devops.\n・Solid background in algorithmics (proof of correctness, complexity in time and space) and mathematics (linear algebra, probability, statistics).\n・Background in robotics: robot kinematics, calibration, motion planning.\n・Background in Computer Vision and AI: deep learning frameworks, model optimization.\n・Familiarity with professional working processes (presentation, document writing, planning, time-management).\n\nBenefits:\n・Remuneration: competitive package comprising salary\n・Premium health-care package\n・14 annual leaves & 12 sick leaves per year\n・Hybrid and flexible working environment\n・Happy lunch every Friday\n・A great team behind you - great people who love what they do\n・The pleasant, enthusiastic, international work environment\n・A promising training and career path', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1793, 773, 2, 'Senior Java Software Engineer', 'Requirements\n• Multi-year (mind. 5-6 years) practical and project experience in software engineering within a business and technically complex environment\n• Must have hands-on experience on Java, Java EE and EJB\n• Good knowledge Wildfly/Spring Boot as well as SQL/PL SQL, Git, Gradle, Jenkins and Linux\n• Ideally, experience with microservices architecture\n• Understanding of agile development methodologies and DevSecOps\n• Solid knowledge of observability, logging & metric collection and the implementation of performance optimizations based on collected metrics\n• Independent, reliable, and collaborative team player\n• Fluent in English\n• Bonus: Understanding of azure & azure data fundamentals\n\nResponsibilities\n• Take technical ownership of new feature implementation, including development, testing, and operations, to deliver high-quality results\n• Support in analyzing complex problems, help managing incidents in cooperation with our people and our partners, and in developing sustainable solutions\n• Enable your teammates during sprints and facilitate continuous improvement within the team\n• Perform code reviews to maintain and improve code quality\n• Work on the continuous enhancement of our products, platforms and services\n• Joining onsite business trips, if required.\n\nBenefits\n• Free lunch at the office\n• Competitive salary & 13th salary\n• 100% probationary salary; fully compulsory insurance\n• Annual premium healthcare and 24/24 personal accident insurance\n• Additional healthcare insurance for family members\n• Annual health check-ups\n• Working from home option, one day per week\n• Flexible working hours; up to 18 days off per year\n• Loyalty bonuses (additional annual leaves, travel vouchers, salary bonus)\n• Free access to Udemy and ELSA speak\n• Free kindergarten for staff’s kids\n• Onsite/business trips in Europe, US, or Australia\n• Annual company trip\n\nAbout us\nFounded in 2008, Axon Active is a Swiss-based software development company with over 15 years of successful business. Currently, we have 600+ employees working across 80+ teams and serving over 40 clients worldwide. Our offices are strategically located in Ho Chi Minh City, Thu Duc City (Dist. 9), Da Nang, and Can Tho, each providing innovative and modern workspaces.\n\nAt Axon Active, we provide a professional and international working environment that values every team member\'s contributions. We offer numerous exciting job opportunities, along with competitive salaries and comprehensive benefits package. Additionally, each year, we send hundreds of our engineers on enriching business trips to Europe, the United States, and Australia. These opportunities not only enable our engineers to exchange cultural perspectives but also to share valuable experiences with experts from around the world.\n\nOur teams thrive on Agile methodologies, promoting individual responsibility and maximizing the potential of each member. Working at Axon Active, you will be empowered to set your own goals, self-assign your tasks, and take ownership of your work, all within a supportive environment that values work-life balance. We trust in your competence and sense of responsibility, your success is indeed our company\'s success.\n\nJoin the Axon Active Family NOW!\nJust send us your resume in English to job@axonactive.com\nIf you have further questions, feel free to contact us\nTel: +84 28 7109 1234', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh e Região', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1794, 810, 2, 'Senior Frontend Developer (ReactJS, TypeScript, English)', 'At NFQ, we focus on Scaling Business—helping companies grow, optimize, and transform through technology and strategic consulting. With 800+ experts across 8 offices, we don’t just build software; we partner with businesses to solve complex challenges, drive efficiency, and unlock new growth opportunities.\n\nUnlike traditional outsourcing, our approach goes beyond executing tasks—we advise, challenge, and co-create solutions that enable businesses to scale effectively. Whether it’s expanding into new markets, streamlining operations, or driving digital transformation, we are committed to delivering impact that lasts.\n\nWhy NFQ?\n🔹 Fairness – We treat our colleagues, clients, shareholders, and the environment with integrity and respect.\n🔹 Entrepreneurship – We think like entrepreneurs, taking smart risks and turning ideas into real impact.\n🔹 Excellence – We go beyond expectations to deliver results that truly make a difference.\n\nWe’re looking for a Senior Frontend Engineer to join DataBus, Shopware’s new event-streaming middleware. Nexus, its visual drag-and-drop workflow designer, is the frontend where merchants can seamlessly connect Shopware to any third-party solution without writing code. Built on a working MVP with React 18, Vite, and Tailwind, your team’s mission will be to transform this prototype into a production-grade application for thousands of merchants.\n\nIn this role, you will:\n- Deep-dive the current client/ and other relevant parts of the codebase in the shopware/swag-nexus repository React Flow canvas, Zustand stores, RTKQuery, Playwright tests).\n- Fully understand Shopwareʼs App System and setup Nexus as a Shopware App, focusing on the frontend implementation Ship a hardening backlog: state isolation, performance budgets, accessibility & keyboard navigation, Skeleton loading patterns.\n- Pair with backend on SSE / WebSocket log-stream UX.\n- Replace ad-hoc components with the new Nexus design system (shadcn/ui + Tailwind) if needed. Own the workflow-canvas architecture: node palette, mini-map, reversible history, snaplines.\n- Implement credential & secret management UI with inline validation.\n- Introduce feature flags and remote config for staged roll-outs.\n- Drive E2E test coverage to 90 % of critical paths Playwright).\n\nWhat will you bring:\n- 5+ years professional FE experience, 3+ years React + TypeScript in production.\n- Proven record shipping complex single-page apps (drag-and-drop, realtime data, or rich editors). Deep understanding of state-management patterns (selector memoisation, optimistic updates, cache invalidation). Performance and DX mindset: Web Vitals, bundle-splitting, dev-server tooling.\n- Accessible-first mentality WCAG 2.1 AA.\n- Familiarity with automated testing pyramid (unit > component > e2e) and CI gating.\n- Comfortable reading backend OpenAPI specs and modelling strong client typings.\n- Excellent English communication; ability to work 34 h overlap with CET.\n\nNice-to-haves \n- Experience with visual programming frameworks (e.g., Blockly, Drawflow), Canvas/WebGL or workflow automation platforms (e.g., n8n, Zapier).\n- Awareness of event-driven architectures (Kafka, NATS, Redis Streams) and Go programming.\n- Knowledge of Shopware 6 plugin/app ecosystem or other e-commerce platforms.\n- Exposure to OpenTelemetry tracing or feature-flag platforms\n\nWhy you’ll love working here:\n- 🏆 Join Vietnam’s Best IT Company – Recognized by ITViec for 7 consecutive years, including 2 successive years as the Winner. Work with some of the best minds in the industry and be part of a company that’s redefining how businesses scale through technology\n- 🌍 Career Growth & Leadership Development – Work closely with NFQ’s leadership team, gain mentorship from experienced executives, and have direct exposure to high-level strategic decisions. Your growth is limitless, as long as you’re ready to step up, opportunities will always be there for you\n- 💰 Competitive Compensation – We believe great talent deserves great rewards. Expect an attractive salary, performance-based bonuses, and a benefits package that reflects your impact. We value talent over salary budgets—exceptional contributions deserve exceptional rewards\n- ✨ And Many More Benefits to Explore! But most importantly healthy work-life balance and an environment where you can thrive—professionally and personally. Including:\n  - Laptop is provided.  \n  - Community Tech activities.  \n  - A fun & dynamic environment and freedom to be creative.  \n  - Modern office with a flexible relaxing zone.    \n  - 13th-month salary pro-rata (based on business situation/performance).  \n  - Performance review 2 times/ year.  \n  - Extra Premium Healthcare & Annual Health-check.     \n  - 15 days annual leaves.\n\nWorking time: Monday – Friday (9AM - 6PM)\nLocation:\n- Ho Chi Minh office: Unit No.PF-08 on Podium Floor, Sapphire Tower 2, 92 Nguyen Huu Canh street, Ward 22, Binh Thanh District\n- Da Nang office: 23rd Floor, G8 Golden Tower, 65 Hai Phong, Thach Thang Ward, Hai Chau District', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1795, 884, 2, 'Software Test Engineer', 'As a Software Test Engineer, you will participate in an R&D project with one of the best German car manufacturers in the world. We expect you to manage product quality throughout the entire development process, ensuring that the product is in the best possible condition when it is delivered to our customers. We are looking for individuals who are passionate about software testing and have experience in software testing, Automotive, Embedded Linux, and AUTOSAR.\n\nWhat you’ll do\n\n• Collaborate with architects and system engineers during the process of writing requirements, developing, testing, and improving the R&D product.\n• Design testing strategies and solutions, create test plans and test cases.\n• Manage defects and the defect lifecycle, work with developers and customers during the debugging process, defect resolution, fixing, and retesting.\n• Execute test cases, record defects, report defects, report progress and testing status, and provide testing reports\n\nWhat you’ll need\n\n• Bachelor’s Degree or higher in Automotive, Electrical, Communication or Computer Engineering\n• 5+ YoE (Middle level) and 8+ (Senior level) with software testing in automotive industry\n• Solid in software level testing – preferably in Automotive Embedded Linux, AUTOSAR\n• Solid in C/C++, Experience with scripting language for automation test\n• Excellent with SDLC Management Tools: Testing Management, Requirement Management, Defect Management and Source Code Management Tools\n• Experience with testing project that comply ISO26262 and ASPICE Level 2 up.\n\nNice to Have’s\n\n• Requirement Design Skill\n• Project Management Skill\n• Skilled with Hands-on coding and Software Development\n\nWhy you’ll love work here\n\n• The exciting environment of a fast-paced AI technology start-up.\n• Opportunity to apply your knowledge and skills to make a real impact on the world.\n• Continuous growth opportunities for your knowledge and leadership skills.\n• Chance to contribute, interact, share, and learn from exceptionally talented colleagues.\n\nContact\n\nInterested applicants are invited to send your application to v.loantt27@vinai.io; v.hoangnm31@vinai.io', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1796, 316, 2, 'QA Automation Engineer (all genders)', 'Hrs As a Company\n\nHRS, a pioneer in business travel, aims to elevate every stay through innovative technology. With over 50 years of experience, their digital platform, driven by ProcureTech, TravelTech, and FinTech, transforms how companies and travelers Stay, Work, and Pay.\n\nProcureTech digitally revolutionizes lodging procurement, connecting corporations and suppliers in a cutting-edge ecosystem. This enables seamless efficiency and automation, surpassing travelers\' expectations.\n\nTravelTech redefines the online lodging experience, offering personalized content from selection to check-in, ensuring an unparalleled journey for corporate travelers.\n\nIn FinTech, HRS introduces advancements like mobile banking and digital payments, turning corporate back offices into touchless lodging enablers, eliminating legacy cost barriers. The innovative 2-click book-to-pay feature streamlines interactions for travelers and hoteliers.\n\nCombining these technology propositions, HRS unlocks exponential catalyst effects. Their data-driven focus delivers value-added services and high-return network effects, creating substantial customer value.\n\nHRS\'s exponential growth since 1972 serves over 35% of the global Fortune 500 and leading hotel chains.\n\nJoin HRS to shape the future of business travel, empowered by a culture of growth and setting new industry standards worldwide.\n\nBUSINESS UNIT\n\nBUSINESS TRAVEL CLUB\n\nThe HRS Business Travel Club (BTC) is the Business Unit managing and developing the HRS E-Commerce platforms of the well-known hotel portal businesses of HRS.de and HOTEL.DE that gradually transform into much more than “just” a platform. BTC provides its members, individual business travelers and SMEs, with a distinct range of exclusive services, which shape tomorrow´s upgraded travel experience. The goal of BTC is to deliver growth as well as sustainable profitability over time by enhancing customer loyalty between the brand and its customers, enabling the Brands Repositioning in the marketplace and unlocking additional potentials via optimized supplier management. Thus, BTC and its products, plays an important role in HRS´s DACH strategy as it revolves around a disruption of the interplay between hotel and workplace supply and e-commerce and a domination of the Business Travel DACH market. Your mission is to further develop and shape the "The HRS Business Travel Club" and its solutions and make it the next innovation of the HRS Group together with a great team.\n\nPOSITION\n\nAs a QA Engineer, you will work closely with our Product and Development teams to design, develop, and execute test plans and test cases that ensure our digital products meet our high standards of quality. You will be responsible for both manual and automated testing processes, leveraging modern frameworks and monitoring tools. Your expertise will contribute to the continuous improvement of our solutions that support a dynamic, personalized travel experience and contribute to the company\'s vision of becoming the mobile travel companion for business travelers.\n\nCHALLENGE\n\nTogether With Your Team, You Will Take The Customer View First And Raise The Bar In Delivering Business Travel Solutions By\n\n- Develop and implement detailed, comprehensive, and well-structured test plans and test cases for both manual and automated testing\n- Design and implement automation test frameworks and scripts for web applications built with NextJS\n- Perform manual testing of mobile applications (Flutter) and responsive web applications across different devices and screen sizes\n- Identify, record, document thoroughly, and track bugs through to resolution\n- Perform thorough regression testing when bugs are resolved\n- Monitor application performance and analyze logs using New Relic\n- Liaise with internal teams (e.g., developers and product managers) to identify system requirements and ensure the quality of the product\n- Stay up-to-date with new testing and monitoring tools\n- Monitor debugging process results and track quality assurance metrics (e.g., defect densities and open defect counts)\n- Conduct post-release/post-implementation testing\n- Work with cross-functional teams to ensure quality throughout the software development lifecycle\n\nFOR THIS EXCITING MISSION YOU ARE EQUIPPED WITH...\n\n- 3+ years of proven hands-on QA Engineer experience with both manual and automated testing\n- Strong knowledge of software QA methodologies, tools, and processes\n- Experience in writing clear, concise, and comprehensive test plans and test cases\n- Proficiency in test automation frameworks such as Playwright or Selenium\n- Experience with manual mobile application testing across different devices and operating systems\n- Experience with responsive web design testing and cross-browser compatibility\n- Experience with NextJS applications testing and troubleshooting\n- Knowledge of log analysis and application monitoring tools, particularly New Relic\n- Experience working in an Agile/Scrum development process\n- Attention to detail and a passion for excellence\n- Good communication skills as you have to deal with numerous stakeholders\n- Ability to work in a team, fast learning, and enthusiasm for the realization of innovative products\n- Fluency in English, spoken and written', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1797, 966, 2, 'Generative AI Engineer', 'We are currently looking for a passionate and skilled AI/ML Engineer to join our team for an exciting engagement with one of our clients – TRG, a DeepTech company building high-trust AI platforms for education, compliance, and knowledge-centric domains.\n\nOur project will work with teams across Singapore, India, and the UK. They specialize in building infrastructure for interpretable, precise, and domain-aligned AI, focusing on advanced retrieval systems, knowledge grounding, agentic reasoning, and explainability in LLM environments.\n\nThis role offers a unique opportunity to work on cutting-edge research and rapid prototyping of AI systems that go beyond generic tooling, delivering real impact in sensitive and high-stakes domains.\n\nWHY JOIN THIS PROJECT?\n\nOpportunity to build inventive systems, not just maintain them.\nWork with a globally distributed, research-forward DeepTech client.\nAccess to TRG\'s interdisciplinary team of domain experts, researchers, and legal engineers.\nSupport and mentorship from INNOMIZE technical leads throughout the engagement.\n\nWhat You’ll Be Doing\n\nRapidly design and prototype GenAI workflows using LLMs, prompt chaining, and agentic frameworks.\nWork with OCR/vision/NLP models to handle multimodal inputs.\nDevelop intelligent pipelines for document understanding, retrieval, and reasoning.\nIntegrate symbolic search techniques (e.g., BM25, SPLADE) and multimodal processing tools (e.g., TrOCR, SimCLR).\nFine-tune or adapt open-source LLMs (e.g., LLaMA, Mistral, Qwen) for domain-specific tasks.\nPresent working PoCs that demonstrate performance, alignment, or reasoning traceability.\nCollaborate with non-engineers (product, legal, academic, compliance) to define goals and refine direction.\nPortray the underlying mathematics and principles of AI/ML to peers and lay persons. Transfer knowledge of understanding of AI/ML to peers and lay persons.\nDevelop data pipelines for structured/unstructured data ingestion, tagging, indexing.\nStay updated with the latest GenAI/LLM innovations and contribute to internal best practices.\nSupport infrastructure, deployment, and MLOps where needed.\n\nWhat We\' Re Looking For\n\nMust-Have\n\nBachelor\'s or Master’s degree in Computer Science, Artificial Intelligence, Data Science, or related fields.\n2+ years of experience in building GenAI or AI/ML applications.\nProficiency with Python and frameworks like LangChain, LlamaIndex, HuggingFace Transformers.\nSolid experience in prompt engineering and evaluating LLM-based systems.\nStrong understanding of information retrieval, knowledge graphs, and/or explainable search.\nDeeply curious about how humans evaluate answers, form arguments, or assess evidence.\nA fast-thinking engineer who builds to learn.\nComfortable producing “minimum viable clarity” rather than a minimum viable product.\nEnthusiastic about working with LLMs without treating them as omniscient.\nInquisitive and conscientiously investigating the latest techniques and tools.\nStrong analytical thinking, with clear and concise communication in English.\n\nNice-to-Have\n\nPrior work on assessment systems, feedback generation, or AI in education/compliance domains.\nExperience in building or evaluating explainable AI systems.\nExperience with OCR, multimodal data processing, and AI safety principles.\nFamiliarity with MLOps tools (MLflow, Airflow, W&B) and Kubernetes.\nFamiliarity with building REST APIs, containerized services (Docker), and cloud platforms (AWS/GCP/Azure).\nKnowledge of data privacy and security principles related to AI and machine learning.\n\nWORKING WITH US\n\nBenefits\n\nOur Company believes that the motivation & personality of the employees are the only shortcut to promoting the corporation and contributions to society. We will try our best to create a corporate environment where all employees can realize their dreams and goals. Featured benefits include:\n\nDynamic and comfortable working environment.\nWork-life balance 40 hours per week from Mon to Fri.\nOvertime is rarely required, you will get paid for the extra work (up to 300%).\nUpto 16-day and 2-day probation leave per year.\nAnnual performance appraisal (twice / year) and 13-month salary.\nHealth Insurance package (PVI).\nSpecial bonus on Public holidays: 1/1, 30/4&1/5, 2/9, Hung Kings\' (10/3).\nExcellent Benefits: Project bonus, Team bonus, Birthday gift, Tet gift ...\nExciting internal events: Happy hour, Company trips, Year-end Party, Team building, Sports Clubs.\nModern and cozy kitchens with plenty of free noodles, coffee/tea bars, and fresh fruits every day.\nTraining activities weekly: English, Management, Soft Skills, Technical skills, Certificate fee.\nHave opportunities to be promoted to Senior and Leader level, and be supported daily by Manager, Leader, and Senior Level.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1798, 880, 2, 'Freelance Software Developer (Java) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\nGenerate prompts that challenge AI\nDefine comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\nCorrect the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\nYou have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\nYou have at least 3 years of professional experience with Java\nCode review experience is a must\nExperience with AI projects is a plus\nYour level of English is advanced (C1) or above\nYou are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\nOur freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n\nTake part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\nWork on advanced AI projects and gain valuable experience that enhances your portfolio\nInfluence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1799, 680, 2, 'Senior Software Engineer, Backend', 'Company Description\n\nAbout Grab and Our Workplace\n\nGrab is Southeast Asia\'s leading superapp. From getting your favourite meals delivered to helping you manage your finances and getting around town hassle-free, we\'ve got your back with everything. In Grab, purpose gives us joy and habits build excellence, while harnessing the power of Technology and AI to deliver the mission of driving Southeast Asia forward by economically empowering everyone, with heart, hunger, honour, and humility.\n\nJob Description\n\nGet to Know the Team\n\nThe team is a dynamic and diverse backend team, responsible for maintaining and enhancing systems within Grab\'s Content Engines. This includes developing features for the Catalog and User-Generated Content (UGC) platforms, which are important to the delivery services in the Grab superapp\n\nGet to Know the Role \n\nBy joining the team you will get a chance to work with the best engineers in the region. You will be reporting to Software Engineering Manager II. You will create a high impact when your work reaches millions of customers. You will get a chance to work on scalable services which can process tens of millions of orders daily. Each service is carefully designed keeping in mind all the possible failures and fallback solutions to ensure we are always running to serve our customers.\n\nThe Critical Tasks You Will Perform\n\n- You will work with the product and design team to understand requirements, provide product feedback, own and implement the product from start to finish.\n- You will create and participate in technical discussions with other engineering teams.\n- You will write code that is reusable, scalable and testable. Make sure products are delivered on time and with high quality.\n- You will collaborate with QAs to make sure all product requirements are met and the deployments are stable.\n- You will review code from other team members, provide constructive feedback and aim to raise the engineering bar.\n- You will improve the codebase. Propose and set better engineering solutions for the team.\n- You will be responsible and responsive during on-call duty. Debug and troubleshoot production issues\n\nWhat Essential Skills You Will Need\n\n- You have a Bachelor in Computer Science or equivalent. Good Computer Science fundamentals in algorithms and data structures.\n- You will have at least 5+ years of experience in software engineering in a distributed systems environment\n- You have experience shipping products (like web applications or backend services) to production.\n- You can be a good coder in any language but willing to work on Golang\n- You have knowledge of cloud technologies and experience developing and deploying services on the cloud\n\nAdditional Information\n\nLife at Grab\n\nWe care about your well-being at Grab, here are some of the global benefits we offer:\n\n- We have your back with Term Life Insurance and comprehensive Medical Insurance.\n- With GrabFlex, create a benefits package that suits your needs and aspirations.\n- Celebrate moments that matter in life with loved ones through Parental and Birthday leave, and give back to your communities through Love-all-Serve-all (LASA) volunteering leave\n- We have a confidential Grabber Assistance Programme to guide and uplift you and your loved ones through life\'s challenges.\n- Balancing personal commitments and life\'s demands are made easier with our FlexWork arrangements such as differentiated hours\n\nWhat We Stand For At Grab\n\nWe are committed to building an inclusive and equitable workplace that enables diverse Grabbers to grow and perform at their best. As an equal opportunity employer, we consider all candidates fairly and equally regardless of nationality, ethnicity, religion, age, gender identity, sexual orientation, family commitments, physical and mental impairments or disabilities, and other attributes that make them unique.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1800, 808, 2, 'Junior Security Engineer', 'Job Description\n\n• Conduct penetration testing and perform code security reviews for product or project applications.\n• Build and maintain Security Information and Event Management (SIEM) systems.\n• Research cloud security technologies (Azure, AWS, GCP) and conduct cloud security audits.\n• Participate in network security maintenance, including incident analysis and investigation.\n• Explore cutting-edge security technologies, vulnerabilities, threat intelligence, and attack methods.\n\nRequirements\n\n• College or University graduated, majoring in cybersecurity, computer science, IT or equivalent\n• Proficiency in Web/API penetration testing methodologies, security code reviews, and tools (e.g., Burp Suite).\n• Familiarity with at least one programming language, such as C#, JavaScript, Python, or Java.\n• Strong interest in researching security technologies and solving challenging problems.\n• Experience with Azure or any SIEM platform (e.g., Splunk, Azure Sentinel) is an advantage.\n• Proficiency in spoken and written English.\n• Knowledge of Chinese is a plus.\n• Relevant certifications such as Offensive Security Certified Professional (OSCP), Offensive Security Web Expert (OSWE), or Certified Ethical Hacker (CEH) are a plus.\n\nWork Location\n\n4th floor, Artemis, 03 Le Trong Tan, Khuong Mai ward, Thanh Xuan district, Hanoi\n\nBenefits\n\n• 5-day workweek\n• Young & vibrant working environment with great career development opportunities\n• Social insurance, medical insurance, and unemployment insurance, are based on actual salary\n• Yearly performance bonus (up to 2 months’ salary)\n• Regular team building events & internal activities (weekly happy hour, quarterly team building events, Lunar New Year parties, etc.)\n• Having an opportunity to be trained and work with professional experts.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1801, 996, 2, 'Mid-Level Nuxt/Vue Web Developer', 'You will be working with a technology company dedicated to transforming the way food and retail businesses operate through intelligent self-service solutions. We specialize in kiosk ordering systems, point-of-sale (POS) platforms, and contactless payment experiences designed to streamline operations, reduce queue times, and enhance customer satisfaction.\n\nWith a presence in Singapore and across the region, we support businesses of all sizes — from small cafés to large restaurant chains — by providing scalable, user-friendly tools that drive efficiency and modernize the customer journey.\n\nOur mission is to empower merchants with smart, seamless, and scalable digital ordering solutions.\n\nWe are looking for a Mid-Level React Web Developer who is passionate about building responsive, intuitive, and high-performance web applications. The ideal candidate will have extensive experience in React, Laravel development and API integrations. You’ll work closely with designers, backend developers, and product managers to bring modern UIs to life using React and related technologies.\n\nKey Responsibilities\nFrontend Development\n- Develop responsive, reusable components using Nuxt/Vue, TypeScript, and Tailwind CSS (or equivalent).\n- Translate UI/UX wireframes and mockups into pixel-perfect, mobile-friendly layouts.\n- Integrate RESTful APIs and/or Laravel endpoints into dynamic frontend components.\n- Optimize for performance, accessibility, and cross-browser compatibility.\n\nCode quality & Maintenance\n- Write clean, maintainable, and well-documented code.\n- Participate in code reviews and contribute to improving development standards.\n- Debug, test, and fix UI issues across different devices and screen sizes.\n\nCollaboration & Agile\n- Collaborate with backend engineers to define API contracts and data flows.\n- Work with designers and product managers in Agile/Scrum teams to scope, estimate, and deliver features.\n- Contribute to planning and technical discussions with a proactive mindset.\n\nQualifications\n- 3–5 years of experience in frontend development using Nuxt/Vue.js.\n- Proficient in HTML5, CSS3, JavaScript (ES6+), and modern Nuxt/Vue hooks.\n- Experience with state management tools like Redux, Zustand, or Context API.\n- Familiarity with frontend testing frameworks like Jest, Nuxt/Vue Testing Library, or Cypress.\n- Hands-on experience with integrating REST or Laravel APIs.\n- Comfortable using Git, CI/CD tools, and Agile workflows (Jira, GitHub, etc.).\n- Strong understanding of mobile UI/UX design principles.\n- Familiarity with Agile methodologies and DevOps practices.\n- Ability to work in a collaborative team environment and take ownership of project deliverables.\n- Excellent problem-solving skills and attention to detail.\n- Experience with CI/CD pipelines is a plus.\n- Strong verbal and written communication skills in English.\n\nPreferred Skills\n- Experience with Next.js or server-side rendering.\n- Exposure to component libraries like Material UI, Bootstrap.\n- Knowledge of accessibility (a11y) best practices.\n- Familiarity with basic DevOps (e.g., Vercel, Netlify, AWS Amplify) or backend integration.\n- Knowledge on Laravel php.\n- Knowledge of cloud services like Firebase or AWS.\n\nSoft Skills\n- Proactive communicator who is comfortable asking questions and clarifying requirements.\n- Strong organizational and documentation skills.\n- Enthusiastic about quality and user experience.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1802, 997, 2, 'Game Experience Designer', 'Position: Game Experience Designer\n\nWorking Hours: We are asynchronous, work when you want\n\nLocation: Fully Remote\n\nSalary Range: $2,000 - $5,000 USD/month\n\nEligible Locations: Anywhere\n\nAbout Colonist\n\nWe\'re building the biggest digital board game platform on the internet. Last year, our players spent 2,466 years playing 45 million games on our Settlers of Catan alternative. We\'re a fully remote, asynchronous team spread across multiple continents, focused on crafting extremely polished digital board games that people truly love.\n\nAbout The Role\n\nAs a Game Experience Designer at Colonist, you will craft engaging, intuitive, and accessible interactions that bring our digital board game to life. You’ll design fluid animations, seamless interactions, and compelling UX that keep players immersed, leading to significant increasing in our game completion rates. Your work will directly impact millions of players, shaping how they experience strategy, competition, and fun.\n\nWhat You\'ll Do\n\n- Work closely with a dynamic, cross-functional team to drive design decisions that enhance the user experience\n- Independently create high-quality UX/UI designs that set a new standard for creativity and usability\n- Dive deep into player behavior, using data and research to refine game interactions and make every session more engaging\n- Conduct user research and interviews to gather insights, refine strategies, and implement feedback effectively\n- Leverage tools like Figma and other cutting-edge design platforms to ideate, prototype, and refine designs\n\nRequirements\n\n- 5+ years of experience as a Game Experience Designer\n- Proficiency in Figma or similar design tools\n- Strong analytical skills in player behavior and feedback interpretation\n- Extensive experience conducting user interviews and usability testing\n- Expertise in interaction and motion design, animation principles, and 2D asset implementation\n- Strong understanding of game mechanics across various genres and accessibility best practices (e.g., colorblind modes, UX clarity)\n- Solid grasp of graphic design principles and game sound design\n\nNice to Have\n\n- Familiarity with game engines (e.g., Unity, Unreal)\n- Basic scripting knowledge for prototyping (e.g., C#, JavaScript)\n\nOur Values at Colonist\n\nWe strongly adhere to these values in our team - if these resonate, then you’ll love working here!\n\nDependability\n\nWe\'re self-driven players who deliver without needing supervision. When we commit to something, we make it happen.\n\nOwnership\n\nWe take full responsibility and go beyond our roles to improve Colonist. Each of us acts like we own the company, because through our stock options, we do.\n\nClear Communication\n\nIn our remote environment, written communication is key. We\'re direct, structured, and always keep our team in the loop.\n\nEfficient Execution\n\nWe move fast and focus on impact. Instead of getting stuck on perfect solutions, we find practical ways forward and get things done.\n\nContinuous Learning\n\nWe\'re curious problem solvers who love a challenge. We constantly seek new ideas, embrace feedback, and aren\'t afraid to change our minds when we\'re wrong.\n\nCompensation\n\nBenefits and Compensation\n\n- Competitive salary paid in USD\n- Stock options (own a piece of Colonist)\n\nBenefits\n\n- Fully remote work\n- Flexible hours - Work on your own time, we’re async\n- Unlimited vacation\n- Work equipment provided\n\nGrowth\n\n- Work directly impacts 5M+ yearly active players\n- Rapid learning opportunities\n- Work with exceptional colleagues on challenging projects\n- Freedom to identify and solve problems\n- Access to all company metrics and discussions', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1803, 849, 2, 'Associate/Junior Solution Support Engineer (SAP SD/MM/FICO consultant)', 'We help the world run better\n\nAt SAP, we enable you to bring out your best. Our company culture is focused on collaboration and a shared passion to help the world run better. How? We focus every day on building the foundation for tomorrow and creating a workplace that embraces differences, values flexibility, and is aligned to our purpose-driven and future-focused work. We offer a highly collaborative, caring team environment with a strong focus on learning and development, recognition for your individual contributions, and a variety of benefit options for you to choose from.\n\nWhat You\'ll Do\n\nAs a Technical Support Engineer, you are responsible for troubleshooting and driving the resolution of SAP product related issues. This entails actively engaging with all levels within the SAP teams and maintaining consistent, up-to-date communication with customers. Your role is pivotal in ensuring that SAP products are utilized smoothly and effectively by our customers.\n\nRoles & Responsibilities\n\nTechnical Support and Problem Resolution:\n\nOffer comprehensive technical guidance and solutions to customers. Proactively troubleshoot product issues to enable the timely and seamless utilization of SAP’s products, following an efficient communication workflow. The goal is to minimize the effort required for customers to use SAP products, thereby enhancing their overall experience.\n\nKnowledge Management and Feedback:\n\nDocument solutions and best practices. This documentation serves to strengthen self-service support channels, effectively deflecting a significant volume of customer problems. Additionally, provide valuable feedback to product development teams. This feedback loop is crucial for driving continuous improvements and enhancements to the products, ensuring they better meet customer needs.\n\nCross-Functional Collaboration:\n\nCollaborate closely with various internal counterparts. By working together, the team can ensure that customer satisfaction is achieved. This collaboration involves coordinating efforts, sharing knowledge, and aligning strategies to provide a unified and high-quality service to customers.\n\nWhat You Bring\n\nFluent in oral and written English (Japanese speaking is a plus)\nBachelor’s or master’s degree (preferred in computer science or engineering)\nRole-Specific Skills: Troubleshooting, Product Thinking, Knowledge Management, Relationship Building, Generative AI Day-To-Day Practice, Critical Thinking, etc.\nProfessional Skills: Learning Agility, Emotional Intelligence, Effective Communication, Diversity Awareness, Customer Focus, Creative Thinking, Complex Problem Solving, and Collaboration.\nStrong team player who learns and adapts quickly\n\nMeet your team\n\nThe Technical Support - Private Cloud ERP team is composed of around 900 support engineers. These experts are in numerous Support Centers across the world. Through incident based and real time channels, we offer technical support to our customers, ensuring their SAP product related issues are addressed promptly and effectively.\n\nBring out your best\n\nSAP innovations help more than four hundred thousand customers worldwide work together more efficiently and use business insight more effectively. Originally known for leadership in enterprise resource planning (ERP) software, SAP has evolved to become a market leader in end-to-end business application software and related services for database, analytics, intelligent technologies, and experience management. As a cloud company with two hundred million users and more than one hundred thousand employees worldwide, we are purpose-driven and future-focused, with a highly collaborative team ethic and commitment to personal development. Whether connecting global industries, people, or platforms, we help ensure every challenge gets the solution it deserves. At SAP, you can bring out your best.\n\nWe win with inclusion\n\nSAP’s culture of inclusion, focus on health and well-being, and flexible working models help ensure that everyone – regardless of background – feels included and can run at their best. At SAP, we believe we are made stronger by the unique capabilities and qualities that each person brings to our company, and we invest in our employees to inspire confidence and help everyone realize their full potential. We ultimately believe in unleashing all talent and creating a better and more equitable world.\n\nSAP is proud to be an equal opportunity workplace and is an affirmative action employer. We are committed to the values of Equal Employment Opportunity and provide accessibility accommodations to applicants with physical and/or mental disabilities. If you are interested in applying for employment with SAP and are in need of accommodation or special assistance to navigate our website or to complete your application, please send an e-mail with your request to Recruiting Operations Team: Careers@sap.com\n\nFor SAP employees: Only permanent roles are eligible for the SAP Employee Referral Program, according to the eligibility rules set in the SAP Referral Policy. Specific conditions may apply for roles in Vocational Training.\n\nEOE AA M/F/Vet/Disability\n\nQualified applicants will receive consideration for employment without regard to their age, race, religion, national origin, ethnicity, age, gender (including pregnancy, childbirth, et al), sexual orientation, gender identity or expression, protected veteran status, or disability.\n\nSuccessful candidates might be required to undergo a background verification with an external vendor.\n\nRequisition ID: 424661 | Work Area: Customer Service and Support | Expected Travel: 0 - 10% | Career Status: Graduate | Employment Type: Regular Full Time | Additional Locations: .', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1804, 713, 2, 'Backend Engineer', 'Job Type\n\nFull-time\n\nDescription\n\nWe are currently seeking a Backend Engineer with a minimum of 3 years of relevant experience to join our team. The successful candidate will hold a bachelor\'s or master\'s degree in computer science, Engineering or a related field. They will be responsible for developing and maintaining our backend services and ensuring the reliability and scalability of our systems.\n\nResponsibilities And Duties\n\n- Participate in the requirements analysis, high-level design, detailed design, and the preparation of technical documentation for the project.\n- Responsible for the development of core project modules, delivering technical solutions, and addressing key technical challenges.\n- Design, build, and maintain efficient, reusable, and reliable backend system code.\n- Ensure optimal performance, quality, and responsiveness of applications.\n- Identify system bottlenecks and errors, and formulate solutions. Maintain code quality, organization, and automation.\n\nRequirements\n\n- A minimum of two years of backend development experience.\n- Solid foundational knowledge of Java, with a thorough understanding of concepts such as JVM, I/O, concurrency, and multithreaded programming.\n- Proficient in SQL, with strong skills in using databases like MySQL, and a certain level of SQL optimization capability; familiarity with common NoSQL solutions such as Redis, along with an understanding of their respective advantages, disadvantages, and use cases, is preferred.\n- Possess a certain level of oral and written communication skills in English, as well as strong time management abilities.\n- Some basic knowledge of container and Kubernetes\n- Good understanding of Http and restful API.\n\nPreferred Qualifications\n\n- Experience with serverless architecture.\n- Expertise in the development, analysis, and design of high-performance systems, ensuring system stability.\n- Experience with AWS network infrastructure.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Distrito 3, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1805, 998, 2, 'C/C++ Developer (All Levels)', 'Responsibilities\n- Participate in the development of the company service project.\n- Collaborate in a team environment to design, develop, and deliver reliable software solutions for customers.\n- Design, develop, document, analyze, test, integrate, debug, research, and integrate new architectural features into existing infrastructures.\n- Verify that developed product features are thoroughly implemented, meeting all specified requirements.\n- Continue to learn new technologies, introduce existing products, improve the product experience and create more value.\n\nQualifications\nEducational Background:\n- Bachelor\'s degree or higher in Computer Science, Engineering, or a related field.\nProfessional Experience:\n- At least 1 year of software development experience with a significant focus on C++/C# WPF and Windows applications.\n- Strong background in designing and developing desktop applications on the Windows platform.\nTechnical Skills:\n- Have knowledge of C++ with understanding of the standard library, STL containers, and algorithms.\n- Experience with Windows API and Windows Services.\n- Proficiency with Microsoft Visual Studio and the Windows SDK.\n- Experience with user interface design and development in Windows.\n- Knowledge of threading, sockets, and inter-process communication (IPC).\n- Familiarity with code versioning tools such as Git.\n- Experience with continuous integration and deployment environments.\nPersonal Skills:\n- Strong analytical and problem-solving skills.\n- Excellent written and verbal communication skills.\n- Ability to work independently and in a team environment.\n- Strong attention to detail and a commitment to delivering high-quality software.\n\nBenefits\nSuccessful candidates will be part of a friendly, motivated and committed talent teams in FPT Software HCM (FSOFT) with various benefits and attractive offers:\n- Successful candidates will be offered a friendly, motivated working environment.\n- Get involve in major full-cycle project with large scale and opportunities to work directly with specialists and experts in system designing in Japanese top corporations in producing medical devices.\n- “FPT care” health insurance provided by PTI and is exclusive for FPT employees.\n- Company shuttle buses provide convenient way of transportation for all employees.\n- Annual Summer Vacation: following company’s policy and starts from May every year.\n- Other allowances: transportation support by company bus, lunch allowance, working on-site allowance, etc.\n- F-Town Campus provide many facilities for FPT Software employees such as football ground, basketball & volleyball, gym center, cafeteria, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1806, 999, 2, 'PHP Developer', 'Mô tả công việc\n\n- Development & maintenance of web applications\n- Custom application, or new module, specifications\n- Familiar Open Source/ Close source application, CMS, Framework\n- Determining any functionality that the site must support and developing PHP content based on practical approved layout\n- Test compatible with popular browsers\n- Work closely with Product Manager, developers lead, designers to fully comprehend requirements of various products\n- Be willing to go onsite if needed.\n\nĐại học', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1807, 911, 2, 'Flutter Developer', '★ MÔ TẢ CÔNG VIỆC: Dưới sự hướng dẫn, bạn sẽ thực hành:\n\n- Thiết kế, phát triển website, ứng dụng\n- Viết các đoạn code chính xác, rõ ràng, chú trọng đến khả năng mở rộng và hiệu suất\n- Phối hợp cùng UI/UX Designer và QA\n\n★ Yêu Cầu\n\n- Nắm vững khái niệm cơ bản về hệ điều hành di động (Android/iOS), vòng đời ứng dụng\n- và các thành phần chính của hệ điều hành, các nguyên lý cơ bản về UI/UX\n- Hiểu các cấu trúc dữ liệu cơ bản như mảng, danh sách liên kết.\n- Nắm các thuật toán cơ bản như sắp xếp (Bubble Sort, Insertion Sort), tìm kiếm tuần tự.\n- Hiểu biết về các mô hình phát triển phần mềm cơ bản như Waterfall, Agile.\n- Phát triển ứng dụng đơn giản với Flutter, sử dụng các widget cơ bản và cấu trúc điều\n- hướng đơn giản.\n- Làm quen với việc tích hợp các Native Modules cơ bản trong Flutter\n- Sử dụng các plugin Flutter có sẵn từ pub.dev để tích hợp các tính năng cơ bản của hệ\n- điều hành.\n- Thực hiện các yêu cầu API cơ bản, sử dụng thư viện HTTP đơn giản\n- Áp dụng các kỹ thuật cơ bản như nén hình ảnh, tối ưu hóa luồng tải dữ liệu.\n- Viết được Unit Test đơn giản bằng flutter_test.\n- Xác định và sửa lỗi đơn giản trong mã nguồn với sự hướng dẫn.\n- Sử dụng các kỹ thuật debug cơ bản để tìm nguyên nhân vấn đề.\n- Sử dụng các công cụ như Git và CI/CD để xây dựng và triển khai ứng dụng di động ở\n- mức độ cơ bản.\n- Có khả năng tham gia thảo luận nhóm, lắng nghe và đưa ra ý kiến cơ bản.\n- Đảm bảo hoàn thành công việc được giao đúng hạn với sự hướng dẫn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ダナン直轄市 ハイチャウ区', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1808, 740, 2, 'C++ Developer (Automotive)', 'Job Description\n\nParticipating in software development projects and applications of in-vehicle infotainment systems (Infotainment) in the field of Automotive.\nSelf-assign tasks and fully be responsible for quality/quantity of delivered results;\nEnsure software development on time and ensure product quality;\nHandle technical problems, and report progress, and work results to management levels.\n\nRequirements\n\nMust have:\nAt least 3++ years technical experience and knowledge in C++;\nJava/C++ programming; \nKnowledge and experience of source code control (Git); \nProficient Debugging skills (reading logs, code understanding, giving solutions); \nProficient English communication skills (both verbal and non-verbal); \nHaving hands-on experience in using at least one version control tool such as Git, Gerrit; \nHaving hands-on experience in using JIRA, Confluence. \n\nNice to have:\nKnowledge in Automotive domain;  \nKnowledge in Android Auto, AOSP; \nHaving hands-on experience working with ASPICE.\n\nBenefits\n\nPackage: Package 14 salary months based on KPI + Extra package: 16M/year\nFull benefit with social insurance.\nAnnual health check and CMC care insurance under the company’s responsibility.\nYoung and dynamic working environment.\nOpportunity to approach the newest technology trends.\nExciting leisure: sports and art events (football club, family day…)\nThe company’s labor policy is entirely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trips, holidays, etc.)\n\n3+ years of experience\n\nBachelor’s Degree\n\nJob Level\n\nMiddle/Senior\n\nWork Form\n\nFull-time\n\nEmail: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1809, 715, 2, 'Kỹ sư Phát triển phần mềm (Backend)', 'Mô tả công việc\nPhát triển Platform cho các thiết bị IoT (Camera AI, Tracking device, Health-care, Vessel Monitoring System, Smart-home, Smart-city...)\nPhát triển các sản phẩm, tiện ích từ các device IoT phục vụ cho các nhu cầu của cuộc sống.\nPhát triển các giao thức truyền nhận dữ liệu, tối ưu băng thông, mã hóa E2E, đảm bảo an toàn cho dữ liệu thiết bị, hệ thống & khách hàng.\nXây dựng các hệ thống large scale cho hàng trăm triệu thiết bị IoT kết nối.\nXây dựng các hệ thống realtime xử lý, phân tích video thông minh bằng AI.\nXây dựng các hệ thống quản trị, giám sát, xử lý và khai phá dữ liệu Big data.\nNghiên cứu, cập nhật các công nghệ mới trong lĩnh vực large scale applications, microservice, bigdata, security, container, virtual network...\nYêu cầu công việc\nTốt nghiệp Đại học chuyên ngành CNTT hoặc chuyên ngành liên quan.\nTrình độ tiếng anh tối thiểu tương đương 550 điểm Toeic.\nCó kiến thức cơ bản về thiết kế, phát triển phần mềm (kỹ thuật lập trình, cấu trúc dữ liệu, design patterns, cơ sơ dữ liệu, hệ điều hành, kiến trúc máy tính, xử lý song song, mô hình OOP, MVC, mạng máy tính ...).\nSử dụng thành thạo một loại ngôn ngữ lập trình cho hệ thống (Python/Java/C++/ Golang...).\nSử dụng thành thạo một loại cơ sở dữ liệu SQL (MySQL/PSQL,/MsSQL/Oracle,..) hoặc NoSQL (MongoDB/Cassandra/Hbase/Hadoop/Spark...).\nCó kinh nghiệm phát triển một trong các ứng dụng backend như Restful API, Web services, gRPC, tcp socket, websocket.\nCó kiến thức về ngôn ngữ lập trình web (HTML, Javascript, JQuery, CSS, Bootstrap...)\n Quyền lợi\nThu nhập thoả thuận dựa trên năng lực ứng viên.\n13 tháng lương, package 2000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\nĐược hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\nĐược hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\nĐược trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\nCó cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\nĐược cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\nCó cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1810, 1000, 2, 'HO - Data Engineering Expert (HR Domain)', 'Job Summary:\nWe are seeking a skilled and experienced Data Engineering Expert to design, build and manage scalable data pipelines and infrastructure. As a Data Engineering Expert, you will collaborate with data scientists, analysts and other related stakeholders to ensure data quality and availability to support business insights, reporting platforms and decision-making.\n\nKey responsibilities:\n• Data Pipeline Development: Design, construct, install and maintain scalable data pipelines and systems.\n• Data Integration: Strategically obtain and integrate data from various sources (databases, APIs, 3rd party platforms) into centralized systems.\n• Data Modelling: Create and optimize data models for structured and unstructured data.\n• ETL/ELT Processes: Design, build and maintain optimized data pipelines and ETL solutions as business support tools in providing analysis and real time analytics platform for critical decision-making.\n• Data Quality and Governance: Ensure high data quality, implement data validation rules to keep operations running at high performance.\n• Data Compliance and Security: Ensure data infrastructure complies with Government Decrees and Bank regulations.\n• Performance Optimization: Monitor and improve performance of data infrastructure and queries.\n• Documentation: Maintain documentation of data pipelines, systems and processes.\n• Collaboration: Work closely with data scientists and business stakeholders to understand data needs and deliver solutions.\n\nRequired skills and Qualifications\n• Bachelor‘s or Master’s degree in Computer Science, Computer Engineering or related field.\n• Strong programming skills in Python, Scala\n• Proficient in SQL and database management systems\n• Familiar with big data frameworks, e.g., Hadoop, Spark\n• Knowledge of data modelling, schema design and data governance best practices\n• Experience with workflow orchestration tools, e.g., Airflow, Luigi\n• Understanding of machine learning processes and tools\n\nSuccess Characteristics\n• Strong problem-solving skill and attention to detail\n• Effective communication and collaboration abilities\n• Ability to work in fast-paced environments\n• Straight-forward and integrity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1811, 182, 2, 'Analytics Engineer', 'About This Role:\n\nWe are seeking a passionate Analytics Engineer to join our mission of revolutionizing financial services and freeing people from complexity. You will act as a bridge between our business needs and data infrastructure, helping all team members properly and efficiently use data in their processes. This role is crucial for maintaining our customer-centric, data-driven culture that challenges traditional banking.\n\nKey Responsibilities:\n- Data Infrastructure & Modeling\n- Design, build, and maintain ETL/ELT pipelines to transform raw data into "analytics-friendly" formats\n- Develop core datasets that serve as canonical sources of truth across the organization\n- Implement data governance practices and ensure data quality standards\n- Optimize data architecture to support rapid business growth and scaling\n- Business Partnership & Strategic Analysis\n- Collaborate directly with business stakeholders to understand their needs and translate them into technical solutions\n- Conduct deep-dive analyses on customer behavior and product performance\n- Drive data-driven decision making across all business domains\n- Analytics & Insights\n- Develop statistical models, hypothesis testing, and A/B testing frameworks\n- Create and maintain automated dashboards and KPI metrics\n- Team Development & Knowledge Sharing\n- Act as a data literacy multiplier, helping colleagues improve their analytical capabilities\n- Document and promote data best practices across squads\n- Spend 20% of time on strategic company-wide data integration projects\n\nRequirements\n\nTechnical Skills:\n- Programming: Strong SQL expertise including complex queries, CTEs, window functions, and optimization\n- Languages: Proficiency in Python or PySpark for data manipulation and analysis\n- Statistics: Solid foundation in statistical analysis, hypothesis testing, and experimental design\n- Data Visualization: Experience with BI tools (Looker preferred, Tableau, or similar)\n- Experience with Databricks\n- Business & Financial Services\n- 2+ years experience in financial services, fintech, or banking environment\n- Understanding of credit risk, lending products, and regulatory requirements\n- Knowledge of GDPR and data governance\n- Experience with customer lifecycle analytics and retention strategies\n- Core Competencies\n- Business Judgment: Ability to make strategic and operational decisions using data\n- Problem-Solving: Tackle complex problems involving business, regulatory, and operational variables\n- Communication: Exceptional ability to influence stakeholders and present data convincingly\n- Collaboration: Experience working cross-functionally with non-technical teams\n- Preferred Qualifications\n- Bachelor\'s degree in Mathematics, Statistics, Economics, Computer Science, or related quantitative field\n- Experience with big data technologies and cloud platforms\n- Machine learning and AI knowledge\n- Previous experience in high-growth startup environments\n- Familiarity with data modeling using statistical algorithms\n- Experience building automated testing and monitoring systems\n\nBenefits\n\n- Meal and parking allowance are covered by the company\n- Full benefits and salary rank during probation\n- Insurances as Vietnamese labor law and premium health care for you and your family without seniority compulsory\n- Performance bonus up to 2 months\n- 13th month salary pro-rata\n- 15-day annual leave+ 3-day sick leave + 1 birthday leave + 1 Christmas leave\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development\n- Values-driven, international working environment, and agile culture\n- Overseas travel opportunities for training and working related\n- Internal Hackathons and company\'s events (team building, coffee run, blue card...)\n- Work-life balance 40-hr per week from Mon to Fri', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1812, 1001, 2, 'Fullstack TypeScript Developer', 'Working location: Ho Chi Minh City\nSalary range: USD 2,500 – 5,000 gross\n\nRESPONSIBILITIES\n- Join a financially stable, fast-growing company trusted by the world\'s leading legal teams.\n- Collaborate with a team of passionate, driven individuals committed to success.\n- Have a direct influence on shaping our products, processes, and the future of LegalTech.\n- Tackle large-scale, complex projects while enjoying a flexible work environment.\n- Enjoy competitive benefits and perks designed to help you thrive.\n- Advance your career with a clear framework and be part of a team that truly cares about your growth.\n\nREQUIREMENTS\n- Solid & practical grasp of software engineering principles and best practices.\n- 6+ years of experience.\n- Proficiency in JavaScript/Typescript, Node.js, React.js, and any associated frameworks.\n- Exceptional problem-solving abilities with a practical approach.\n- Excellent communication and interpersonal skills.\n- Bonus: Experience with AI or machine learning development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1813, 1002, 2, 'Backend Engineer', 'We are seeking a skilled Backend Engineer to join our team. As a Backend Engineer, you will be responsible for developing and maintaining web applications using .NET Core. You will collaborate with cross-functional teams to design, develop, and deliver high-quality software solutions.\n\nResponsibilities:\n- Develop and maintain web applications using .NET Core\n- Collaborate with product owners, designers, and other developers to understand requirements and translate them into technical specifications\n- Design and implement user interfaces using modern web development tools and techniques\n- Write clean, maintainable, and efficient code\n- Perform code reviews and ensure adherence to coding standards\n- Troubleshoot and debug issues in existing applications\n- Optimize applications for maximum performance and scalability\n- Stay up-to-date with emerging technologies and industry trends\n- Contribute to the continuous improvement of development processes and best practices\n\nRequirements:\n- Bachelor\'s degree in Computer Science, Engineering, or a related field\n- At least 4 years’ experience\n- Proven experience as a Backend Engineer with expertise in .NET Core\n- Experience with responsive web design and mobile-first development\n- Experience with version control systems like Git, Azure Devops\n- Prior familiarity with POS domain is preferred.\n- Excellent problem-solving and analytical skills\n- Ability to work independently and in a team environment.\n- Strong communication skills\n\nPreferred Qualifications:\n- Experience with cloud platforms such as AWS or Azure\n- Familiarity with containerization technologies like Docker\n- Knowledge of relational databases and SQL, NoSQL (Firebase, Firestore)\n- Experience with unit testing and test-driven development (TDD)\n- Experience with DevOps principles and CI/CD pipelines.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1814, 783, 2, 'Senior Java Software Engineer', 'Company Description\n\nKMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines:\n\nKMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions.\nKMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality.\nKMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors.\n\nJob Description\n\n- Perform hands-on coding and code review as other peer developers as needed\n- Understand the requirements of the customer or business and utilize this knowledge to develop applications that are consistent with this;\n- Design, develop, review, implement, maintain and manage continuous integration, build management and deployment scripts, systems, and any code as required;\n- Write unit tests and run through all the test cases for assigned tasks and ensure all cases are tested and passed before release for testing.\n- Participate in Agile/Scrum activities: daily standup, demo session, retrospective, estimate, and planning, etc.\n- Provide mentoring/training for junior members if any\n- Perform other tasks assigned by the Line Manager.\n\nQualifications\n\nGeneral requirements:\n- At least an upper-intermediate skill level of English\n- Likely having 3+ years of experience (flexible depending on how fast your learning and technical developing capabilities are)\n- Able to obtain deep knowledge of the project’s technologies\n- Able to work independently with minimal guidance\n- Able to self-learn and quickly adapt to new technologies\n- Familiar with the Agile development methodologies (Scrum, XP, Kanban)\n\nTechnical requirements:\n- Proficient in Java, Java core to develop enterprise web-based applications\n- Strong experience with web-based technologies: Spring (Spring Core, Spring MVC, Spring Security, Spring Data, Spring Boot) and ORM (JPA, Hibernate)\n- Strong experience with OO designs and design patterns\n- Good experience with unit testing: JUnit, mock\n- Experience with writing efficient SQL queries\n- Experience with Web Services (REST, etc.).\n\nNice to have:\n- Experience with HTML/ CSS/ SCSS/ JavaScript/ Bootstrap and one of following JavaScript frameworks: ReactJS, Angular, VueJS, KnockoutJS\n- Experience in microservices and cloud environment (Azure/AWS/GCP)\n\nAdditional Information\n\n- Working in one of the Best Places to Work in Vietnam, Top 10 ITC Company in Vietnam\n- Flexible working model: Flexible time & Hybrid working from Ho Chi Minh or Da Nang city or working remotely from any location in Vietnam\n- Attractive Salary & Benefits, full salary in probation, social insurance on full gross salary\n- Performance appraisal twice a year, 13th-month salary and performance bonus\n- Premium healthcare insurance for you and your loved ones\n- 18+ paid leave days/year\n- Diverse careers opportunities with Software Services, Software Product Development\n- Working and growing in a values driven, international working environment and standard Agile culture with passionate and talented teams\n- Onsite opportunities: short-term and long-term assignments in U.S\n- Various training on hot-trend technologies, best practices and soft skills\n- Company trip, big annual year-end party every year, team building, etc.\n- Fitness & sport activities: football, tennis, table-tennis, badminton, yoga, swimming…\n- Joining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,…\n- Free in-house entertainment facilities (football, ping pong, gym…), coffee, and snacks (instant noodles, cookies, candies…)\n\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1815, 1003, 2, 'Backend Engineer (Go, Java)_Co-Lending Partnership', 'Become a Backend Engineer at Trusting Social and join our transformative Co-Lending partnership initiative, where you\'ll contribute to projects reshaping financial services globally and in Vietnam. Your work will involve enhancing automated credit evaluation systems to efficiently manage high volumes of applications through instant registration, approval, and decision-making processes. Furthermore, you\'ll play a key role in revolutionizing credit card experiences by facilitating instant issuance, payments, and providing numerous benefits to empower financial freedom for users.\n\nResponsibilities\n\n• Develop Scalable Web Service APIs: Build highly scalable, highly available, and fault-tolerant web service APIs designed to handle millions of transactions per day.\n• Agile & DevOps Practices: Follow Agile methodologies and DevOps practices such as CI/CD to deliver quality code rapidly to market.\n• Seamless Integrations: Create software services that integrate effortlessly and securely with banks, third-party platforms, and vendors.\n• Innovative Problem Solving: Think outside the box, innovate, experiment, and continuously improve by learning quickly from failures to provide simple yet effective solutions to complex problems.\n\nRequirements\nEducational Background:\n\n• Bachelor’s degree or higher in Computer Science, Engineering, or a related field.\n\nExperience:\n\n• 5+ years of software development experience.\n• Solid expertise in Golang (or the confidence to learn it quickly when coming from other similar programming languages).\n\nAPI Design & Development:\n\n• Proficient in designing and developing RESTful APIs and gRPC interfaces.\n• Experience building backend services optimized for high performance, scalability, and reliability.\n\nDatabase Expertise:\n\n• Strong database and schema design skills for performance and scalability across both relational and NoSQL databases (e.g., MySQL, PostgreSQL, MongoDB, Redis, Elasticsearch, RocksDB).\n\nSystem Design:\n\n• Deep understanding of complex system design, design patterns, data structures, algorithms, microservices, and event-driven architecture.\n• Experience with system tuning for high performance and reliability.\n\nDevOps & Tooling:\n\n• Hands-on experience with CI/CD tools such as GitHub workflows and Jenkins.\n• Familiarity with Docker containers and Kubernetes.\n• Knowledge of automated testing practices, caching techniques, and version control systems like Git.\n\nNice to Have:\n\n• Experience with cloud platforms (AWS, GCP, or Azure).\n• Exposure to or interest in the AI domain with a willingness to leverage AI to enhance team productivity.\n• Experience with microservice architecture is a plus.\n\nWhat We Offer\n\n• Competitive compensation package, including 13th-month salary and performance bonuses\n• Comprehensive health care coverage for you and your dependents\n• Generous leave policies, including annual leave, sick leave, and flexible work hours\n• Convenient central district 1 office location, next to a future metro station\n• Onsite lunch with multiple options, including vegetarian\n• Grab for work allowance and fully equipped workstations\n• Fun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\n• Unlimited free coffee, tea, snacks, and fruit to keep you energized\n• An opportunity to make a social impact by helping to democratize credit access in emerging markets\n\nAbout Us\n\nWe are an AI Fintech company specializing in assessing credit profiles of consumers in emerging markets combining pioneering AI with large alternative data sources. In 2020 we reached our ambitious milestone of credit profiling 1 billion consumers spanning 4 countries - Vietnam, Indonesia, India & the Philippines - and building a platform for the wider industry and the financial services industry, in particular, to provide the "un & under" served access to credit. At the core of this initiative has been our strict and unwavering adherence to the norms of consumer data privacy and consumer data rights.\n\nBut we\'re not satisfied as we embark on the next leg of our journey to deliver 100 million credit lines to consumers in the markets where we operate. Although this goal is ambitious, we truly believe that by harnessing the power of AI & Big Data we can deliver financial access at an unprecedented scale.\n\nAs a firm, we\'re audacious problem-solvers motivated by our impact on society. We deeply espouse the values of ownership - of our actions and initiatives, integrity in all we do, and agility in execution.\n\nWe place great importance on doing what is right, what is best, and what is innovative. If you are smart, driven, and want to make a difference in the world with the most advanced and fascinating technology, come join our team. We can satisfy your desire to explore new territory and give you the runway to really make an impact.\n\nAdditional Info\n\nLearn more about us here:\n\nhttps://www.youtube.com/watch?v=inAEDGvOcL8&t=29s', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1816, 225, 2, 'Mid/Senior/ Lead Java Engineer', 'We are seeking motivated Senior/Middle Java Engineers who are passionate, results focused to take accountability for the delivery of Microservices that will be used by banking front end applications. You will be part of our delivery team and will be responsible for providing technical expertise throughout all phases of the software delivery life cycle as we initiate a transformation of NAB technology.\n\nAt NAB, we believe success comes from our people. We\'re committed to supporting your talent and skills through your career, as you help us build a culture that affects change for our customers and for the community too.\n\nJOB RESPONSIBILITIES\nDesign, develop, review, implement, and manage Java applications and services for the production and pre-release environments;\nDesign, develop, review, implement, and manage continuous integration, build management and deployment scripts, systems, and any code as required;\nParticipate in Agile software development, prototyping, and code review with international development teams to build scalable microservices-based products and APIs using Java technologies on AWS Cloud architecture;\nFully understand the requirements of the customer or business and utilize this knowledge to develop applications that are consistent with this;\nWork with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and tooling;\nProvide robust coding practices, solid unit/component test coverage, and debugging code.\nMentor, provide technical direction and engineering leadership for a team of engineers\n\nYOUR SKILLS AND EXPERIENCE\nMust have\n4+ years of experience as a software engineer in a complex development environment.\nSolid experience in Java 8+ and Springboot.\nGood English communication skills (both verbal & written), especially in the global software development environment.\nExperience in designing & developing RESTful APIs and microservices-based systems.\nExperience with distributed, event-driven systems and using messaging protocols. Messaging middleware such as Apache Kafka is preferred.\nExperience in Cloud computing (AWS, Azure, etc).\n\nNice-to-have\nExperience in Containers (ECS, Kubernetes, Docker) and FaaS (AWS Lambda) technologies.\nExperience in modern CI/CD pipelines and tools (e.g. Git, Ansible, Jenkins, NPM, Gradle).\nExperience in the Bank\n\nTHE BENEFITS AND PERKS  \nWe appreciate and reward our colleagues who do great work every day – from excelling for our customers, to taking ownership of an issue to get it resolved. Here’s how we support our people with a range of exclusive benefits. \n\n1. Generous compensation and benefit package \nAttractive salary \n20-day paid annual leave and 7-day paid sick leave \n13th month salary and Annual Performance Bonus \nPremium healthcare for yourself and family members \nMonthly allowance for team activities \nPremium welcome kit and occasional gifts of appreciation \nExtra benefits on your work anniversary \n\n2. Exciting career and development opportunities \nLarge scale products with modern technologies in banking domain \nClear roadmap for career advancement in both technical and leadership pathways \nAccess to digital learning platform such as Udemy \nConsistent and high-quality leadership training through the Distinctive Leadership program (DLP) \nSpecialist capabilities and accreditations in key skill areas such as Cloud Engineering, Digital, Data, Security and SREs (Site reliability engineers) \nSponsored English course with native teachers \nOpportunity for training in Australia \n\n3. Professional and engaging working environment \nHybrid working model and excellent work-life balance \nState-of-the-art & modern Agile office \nFood and beverages in the office pantry \nEmployee Assistance Program to improve your physical and mental health \nAnnual team activities and company events \nA solid and talented team behind you – great people who love what they do \n\nA DIVERSE AND INCLUSIVE WORKPLACE WORKS BETTER FOR EVERYONE \nWe know that our people make us who we are. That\'s why we have built a culture of respect – where everyone feels valued and appreciated for being their true authentic selves at NAB. With our focus on inclusion and diversity, and in partnership with our Employee Resource Groups, NAB is a place where First Nations colleagues, colleagues of all genders, sexualities and ages, carers and colleagues with disability, and colleagues from all cultures, races and religions have the opportunity to thrive, connect and grow. \n\nWe are intent on providing an environment where you can work your way. Ask about our many flexible work options and please let us know if we can provide any adjustments throughout the recruitment process. \n\nCLOUD-FIRST \nNAB is undergoing an exciting "Cloud First" technology transformation by taking advantage of the latest tools and techniques used by leading technology and digital companies globally. But it’s not just about the Tech, we are also investing heavily in our people, so if you have an appetite to learn, grow and elevate others around you, this is the place for you! \n\nIf this excites you, let\'s have a chat over a cup of coffee!\n\nIt\'s more than just a career at NAB!\nWe believe in people with people and dreams, and we want you to achieve your aspirations. More than just a career, NAB Vietnam offers you a flexibility to balance your work - life, the opportunity to grow as professionals, people and a complete set of well-being offerings. If you have an appetite to learn, grow and elevate others around you, this is the place for you.\n\nIT\'S MORE THAN MONEY\nWe naturally also provide a very competitive remuneration package but a career with us is about a lot more than money. We believe in people with ideas and dreams, and we want you to achieve your aspirations. We will work together to deliver exceptional products and outcomes that push the limits of our own aspirations. Our passion for creating value and exceeding our customers\' expectations means we are constantly striving to redefine our standards of excellence. You will have our backing to develop and our encouragement to explore, realize and reach your full potential.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1817, 934, 2, 'Senior Java Software Engineer', 'Job Responsibilities:**\n• Upgrade existing functionalities and create new ones using data-driven insights.\n• Implement and deliver new customer project development with high quality.\n• Participate in all phases of the development cycle.\n• Actively join planning meetings.\n• Implement new features by business specifications.\n• Write unit, functional, and integration tests, and perform unit testing.\n• Conduct code reviews for other team members.\n• Automate maintenance work through development.\n• Respond to and resolve IT support requests from employees via phone, email, or service request system.\n\nRequired Qualifications:**\n• 3+ years (for middle, 5+ for senior) of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend.\n• Able to analyze, design, develop new functionalities, and provide maintenance or issue fixes.\n• Experience in enterprise-scale projects using:\n• Oracle PL/SQL, MyBatis\n• Java (Spring Boot / Spring Framework)\n• JSP (JavaScript / JQuery)\n• Git (Git Runner)\n• Proficient in tools/technologies: Azure, AWS, Redis.\n• Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools.\n• Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc.\n• Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications.\n• Solid understanding of OOP, design patterns, and coding standards.\n\nPreferred Qualifications:**\nExperience with:\n• AWS\n• MS .Net / .Net Core\n• Kubernetes\n• React.js\n• Nginx\n• JUnit\n• Jasper Report\n• ElasticSearch & Kibana (ELK)\n• Grafana\n• Prometheus (monitoring/alerts)\n\nAdditional Requirements:**\n• Strong communication, analytical, time management, problem-solving, and documentation skills.\n• Strong team player.\n• Able to take on multiple developer/system support roles.\n• Capable of managing users of various technical levels.\n• Able to multitask and handle multiple projects simultaneously.\n• Collaborative and team-oriented.\n\nLương up to 60M\nSố lượng 04: (2 middle 2 senior)\nyêu cầu onsite: 1-2 tuần đầu ở khách hàng sau đó working tại VP của GEM \nPhỏng vấn 3 vòng: technical + english -> khách hàng phỏng vấn -> client phỏng vấn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona capitalei Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1818, 1004, 2, 'Senior Fullstack Engineer (NodeJS, React) - Hybrid', 'Company Description\nSaola Labs is a blockchain development company based in Ho Chi Minh City, Vietnam, with expertise in DeFi, Tokenization, and Web3 Payment. Founded by product & finance leaders from Apple, Stably, and Infina, Saola Labs has launched projects directly with blockchain foundations like Ripple, Harmony, and VeChain. The company is dedicated to reshaping the global economy through blockchain technology.\n\nRole Description\nThis is a full-time hybrid role for a Senior Fullstack Engineer (NodeJS, React) at Saola Labs. The engineer will be responsible for back-end and front-end web development, software development, and full-stack development. The role is located in Ho Chi Minh City, Vietnam, with flexibility for remote work.\n\nQualifications\n- Bachelor\'s degree in Computer Science or related field.\n- MUST communicate English well (write, read, speak and listen).\n- Proficiency in backend technologies such as Node.js and NestJS, with a strong command of TypeScript.\n- Expertise in frontend frameworks like Next.js, Tailwind CSS, and TypeScript.\n- Passionate about blockchain technologies and DeFi protocols.\n- Familiarity with Redis for caching and session management.\n- Knowledge of Docker and Kubernetes for containerization and orchestration.\n- Experience with blockchain technologies including Solidity, Rust, Hardhat, Truffle, and Cryptography.\n- Proficiency in DevOps tools and platforms such as AWS, GCP, Azure, Terraform, Jenkins, and GitHub Actions.\n- Understanding of microservices architecture and RESTful API design.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1819, 385, 2, 'Senior Software Engineer', 'Take the clearer route to smart career growth. At clearer.io, we’re reimagining eCommerce by enhancing search, discovery, and customer engagement through a standout suite of innovative apps. Our mission is straightforward yet powerful: to empower our partners with solutions that streamline their operations, foster customer trust, and drive sustainable growth. We’re not just about technology - we’re about making eCommerce smarter, simpler, and more impactful, delivering solutions that inspire confidence and create real results.\nWith fresh investment and rapid growth, this is the perfect time to join our journey. When you become part of clearer.io, you step into a role where your work truly matters. Here, you’ll have the opportunity to own your projects, drive outcomes, and make an impact within a supportive, diverse team of professionals dedicated to customer success. We value clarity, results, and a customer-centric approach that keeps us focused on delivering real value to our partners every step of the way.\nIf you’re ready to cut through the clutter and focus on what really matters in a dynamic eCommerce landscape, clearer.io is the place to grow, lead, and shape the future of online retail. Join us, and be part of a team that’s committed to making eCommerce clearer, more efficient, and more rewarding for everyone.\nYour Impact:\nAs a Senior Software Engineer, you will be a technical leader, driving the design and development of major features and systems for our cloud-based SaaS platform. You will architect complex solutions, mentor and coach other engineers, and collaborate with product leadership to shape our technical roadmap. This role offers a significant opportunity to influence the direction of our technology and the growth of our engineering team. This position is located in Vietnam and fully remote.\nWhat You’ll Do:\n- Lead the design and development of major features and systems for cloud-based SaaS applications.\n- Architect and implement complex, scalable, and highly available solutions.\n- Drive technical decisions and provide technical leadership across multiple teams.\n- Mentor and coach other engineers, fostering a culture of technical excellence.\n- Collaborate with product management and other stakeholders to define product roadmaps and technical strategy.\n- Identify and mitigate technical risks and dependencies.\n- Proactively identify and address performance bottlenecks, security vulnerabilities, and scalability challenges.\n- Evangelize best practices and contribute to the development of engineering standards.\n- Evaluate and recommend new technologies and architectural patterns.\n- Lead incident response and resolution for critical production issues.\nWhat You’ll Bring:\n- Typically requires a minimum of 5 years of related experience with a Bachelor’s degree in Computer Science, Engineering, or equivalent.\n- Experience with e-commerce and with specific experience of Shopify a plus!\n- Expert-level proficiency in at least one frontend framework (React preferred or Angular/Vue) and experience with advanced UI concepts.\n- Expert-level proficiency in at least one backend language (Node.js preferred or PHP/Python/Go) and experience with microservices architecture.\n- Deep understanding of software architecture principles and design patterns.\n- Proven experience designing and building large-scale, distributed systems.\n- Extensive experience with cloud platforms (e.g., AWS, Azure, GCP) and cloud-native technologies (e.g., Kubernetes, Docker).\n- Strong experience with DevOps practices and tools.\n- Excellent communication, collaboration, and leadership skills.\n- Proven ability to mentor and guide other engineers.\n- Experience with performance tuning, security hardening, and system monitoring.\n- Experience leading and influencing technical direction within a team or organization.\n- Proficient in English.\nQualities:\nWhat other characteristics do we look for? Leadership for sure. But what does that mean? Well, some of the attributes we appreciate include:\n- Inquisitiveness\n- Having pride in one’s work\n- Tenacity: trying to work it out but knowing when to ask for help\n- Follow-thru and dependability\n- A strong belief in the team’s success\n- Most importantly, friendly/kind/a good teammate\n- Demonstrable examples of leading individuals/teams driving architectural direction, establishing best-practices and patterns\nWhy Clearer.io?\n- Customers at the heart: We make our customers the stars of our show and help them thrive. When they grow, so do we. We obsess over their needs so we can dream big on their behalf.\n- Purposeful progress: We harness our ingenuity to keep leveling up and growing stronger. We take initiative, think boldly, and don’t settle for the status quo. Every risk teaches us something new.\n- Endless innovation: We take action, refine our work, and drive meaningful growth for each other and our customers. Humble in our pursuit, we continuously seek to improve. We ask ‘How can we help?’ striving always to make a meaningful\n- Always open: With transparency we simplify the complex, collaborate globally and empower everyone. We believe openness in our communication - with customers, partners, and team members - is essential for building strong relationships.\nClear Benefits:\n- 100% Remote Culture: Work from anywhere that brings you happiness.\n- Performance-based Year-End Bonus: Recognizing and rewarding your individual contributions.\n- Wellness Allowance: Support for classes promoting physical and mental health.\n- Time Off: 20 days/year, in addition to Vietnam holidays.\n- MacBook Provided.\n- Collaborative Events: Offline meet-ups, monthly gatherings, year-end party, and company trips.\n- Continuous Learning: Technical and general workshops, online resources.\n- Health and Wellness Benefits: Generali Health Care, annual check-up.\n- International Exposure: Enhance expertise and English communication skills.\nBe a part of Clearer.io—where your expertise fuels real change in eCommerce. Come and join us- it’s clear we’re the place to be!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1820, 822, 2, 'Java/Kotlin Engineer (Senior/Principal_Banking Project)', 'Java/Kotlin Engineer (Senior/Principal_Banking Project)\n\nUrgent\n\nHo Chi Minh\n\nTech/Engineer\n\nWho we are?\n\nMoney Forward is embarking on an exciting new venture in collaboration with Sumitomo Mitsui Financial Group and Sumitomo Mitsui Banking Corporation to explore the provision of BaaS (Banking as a Service) and digital banking solutions. We are seeking a talented Backend Engineer to join our core banking team, which will be at the heart of this initiative.\n\nResponsibilities And Duties\n\nAs a Software Engineer in the Core Banking Team, you will leverage Mambu, a leading cloud banking platform for neobanks and challenger banks, to build one of the most reliable and agile banking systems in the industry. Our goal is to shape the future of digital banking in Japan, making it more accessible and user-friendly than ever before.\n\n• Acquire domain knowledge in digital banking, including deposits, loans, clearing and settlement, basic accounting, domestic exchange, and Zengin network.\n• Actively engage with product owners to define requirements.\n• Develop, test, and deploy code that meets non-functional quality gates such as static code analysis, software composition analysis, SAST, and DAST, while maintaining numerical accuracy.\n• Design and build high-performance, scalable microservices centered around APIs.\n• Pursue test automation and continuous improvement, including API testing.\n• Take responsibility for the entire software development lifecycle.\n\nMust have\n\n• Approximately 5 years of hands-on experience with Java or Kotlin and Spring Boot.\n• Practical experience with SQL, Apache Kafka, and related technologies.\n• Experience in creating and automating tests.\n• Hands-on experience with relational/non-relational databases, including transaction management, query optimization, and schema design.\n• Experience in microservice architecture and API design with a focus on scalability, maintainability, and supportability.\n• Proven experience in development with sufficient domain knowledge (not necessarily in the financial industry).\n• Understanding of CI/CD concepts and practices.\n• Experience developing cloud-native applications in major cloud environments such as AWS, Azure, or GCP.\n• Bachelor\'s or Master\'s degree in Computer Science or a related field, or equivalent practical experience.\n\nNice to have\n\n• Experience working in financial institutions, particularly banks or fintech companies.\n• Basic knowledge of accounting or double-entry bookkeeping.\n• Knowledge of CCP and settlement mechanisms.\n• Experience implementing CI/CD pipelines from development to production in the cloud.\n• Experience in AI development and/or experience in using AI tools to improve development processes. Money Forward recently announced our AI Strategy roadmap which focuses on improving AI-driven operational efficiencies, as well as integrating AI agents into our products to deliver better value to our users.\n\nLanguage Requirements\n\n• English: Business level (TOEIC score of 700 or above)\n\nWho We’re Looking For\n\n• Ability to quickly adapt to changing priorities and situations.\n• A critical thinker who questions the status quo.\n• Excellent communication skills with the ability to articulate ideas clearly.\n• Willingness to learn necessary domain knowledge and technologies.\n• Understanding of DevOps/DevSecOps.\n\nTechnology Stack and Tools Used\n\n• Kotlin, Spring Boot, Gradle, jOOQ, Liquibase, Kotest/JUnit, Karate/Rest Assured\n• Redis, MySQL\n• Docker, AWS ECS\n• Apache Kafka (AWS MSK)\n• Mambu cloud banking platform\n• GitHub, Backstage, Amazon ECR\n• GitHub Actions, ArgoCD, Sonar Cloud, Detekt, AeyeScan\n• ChatGPT, Copilot, Gemni\n\nOur benefits\n\nCaring Mental & Physical Recreation\n\n• Hybrid working: 2 days at the office and 3 days WFH\n• Working hour: Flexible start 8AM-9AM from Mon-Fri\n• Full salary in probation\n• Insurance: Applied from Probation period:\n• Social Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\n• Private health insurance & accident insurance. From Managing level: extra for family members\n• Bonus: 13th month salary\n• 16 - 24 paid days off and more\n• Paternity leave: Extra 5 days\n• Annual company trip; Quarterly team building\n• Billiards & Running club\n• Annual health check\n• Well-equipped facility: Macbook pro, additional monitor,\n\nCaring Career & Development\n\n• Clear Career path\n• Foreign language & International technology-related certifications sponsoring\n• External & internal training courses\n• Soft-skill workshops\n• Tech seminars\n• Monthly and biannual Recognition Awards\n• Performance & salary review: twice/year (Jun & Dec)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1821, 366, 2, 'Mid/Senior Backend Engineer (Java) - Weverse', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nWe are looking for Backend Engineer.\n\nYour daily task:\n\n- Developing Weverse services (https://weverse.io/)\n- Participating in code reviews and architecture design\n- Proactive, can-do attitude and strong commitment\n\nYour background:\n\n- 5+ years of experience developing and maintaining high availability, high traffic systems\n- Experience or strong knowledge of one of the databases: PostgreSQL, MySQL, Oracle, MongoDB\n- Deep knowledge and experience in applying design patterns\n- Understanding & experience in data structure, algorithm, distributed systems\n- Open-minded, honest, and have a positive attitude toward people\n- Good at communication skills in general and English skills in particular\n\nIt\'s a big plus if you:\n\n- Have experience in Java Spring-Framework\n- Have experience in HBase, Cassandra, ClickHouse, Druid, Hazelcast, Hadoop, ELK-stack, docker, k8s\n- Have experience in distributed systems\n- Have experience in architecture design for handling massive traffic\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Zona metropolitană Ho Chi Minh City', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1822, 977, 2, 'Mobile Flutter Developer (Mid/Senior)', 'About The Role\n\nWe’re looking for experienced and passionate Mobile Front-End developers (Senior and Mid levels) interested in joining an early-stage venture to help the team scale our health tech application (+web) across the world.\n\nWhat You Will Get\n\n🧳 Relocation Support - We handle the move, financially and practically\n💰 Permanent Global Contract - With a seriously competitive salary\n🏥 Private Healthcare - From day one\n💻 Top-Tier Tech Setup - Brand new MacBook + full onboarding kit\n🧠 Career Growth Framework - Clear, personalised, and fast-moving\n🎯 Bonus Scheme - Performance-related, quarterly paid\n🌴 14 Days PTO + Public Holidays - Real time off\n🧪 Hybrid Working - 3 days in the office per week\n🍛 Refreshments - Free Lunch and Dinner every day for you to enjoy\n\nWhat You’ll Do\n\nSupport the entire application lifecycle (concept, design, test, release and support)\nProduce fully functional mobile applications writing clean code\nGather specific requirements and suggest solutions\nTroubleshoot and debug to optimize performance\nWork with Product development team to plan new features\nEnsure new application meet quality standards\nStay up-to-date with new technology trends.\n\nWhat You’ll Need\n\nMUST have at least 5 years of experience in Flutter (Dart)\nMUST experience with either Android OR IOS Native experience.\nDemonstrable portfolio of released applications on the App store or the Android market\nExperience with integrating mobile application to Firestore/Firebase is a plus\nFamiliarity with OOP design principles\nExcellent analytical skills with a good problem-solving attitude\nAbility to perform in a team environment\nBSc degree in Computer Science or relevant field\n4+ years of relevant industry experience for mid-level, 8+ for senior level.\n\nWhy join Elfie\n\nWe\'re a global start-up that is mission-led, and fiercely product-driven.\n\nWe\'re building something that improves lives - and we\'re doing it with a culture of trust, freedom, and high performance.\n\nAbout Elfie\n\nElfie is the first completely free, gamified mobile app that rewards users for managing their health. Our goal? To become the world’s largest self-reported medical record platform — across all therapeutic areas.\n\nWe operate in 10+ countries today, with plans to expand into 15 by the end of 2025.\n\n📲 Try Elfie for yourself by downloading it on the App Store or Google Play\n\nWhat Now?\n\nApply today for immediate consideration! Got someone in mind? We offer a referral reward if your recommendation is hired. Contact Talent Acquisition for more info.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 Quận 1', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1823, 1005, 2, 'Software Engineer', 'Job purpose: Do offshore projects and development projects for Customers from Design to delivery phase\n\nResponsibilities\n- Develop quality software and web applications\n- Programming, Database, Operating System skill.\n- Full skill in Software Development Project methodology: UI design, program design, documentation, coding, testing, bug fixing\n- Documentation / Reporting skill in English\n- To keep good relationships with team members.\n\nQualifications\n- Bachelor\'s degree or equivalent experience in Computer Science or related field\n- Experience working with Java is required. (at least 4 years and current are working with Java)\n- Proficient in using Java web frameworks such as Spring MVC, Spring Boot or Hibernate.\n- Strong knowledge of HTML, CSS and JavaScript.\n- Proficient in using one of the FE frameworks (Vue, React, Angular,..) to develop interactive user interfaces.\n- Experience working with message queue systems (ActiveMQ, Kafka,..) to process queued messages.\n- Experience working with relational database management systems RDBMS (SQL server, PostgreSQL) and NoSQL (Cassandra, MongoDB.)\n- Have knowledge and experience with Linux.\n- Desired personal qualities: Good teamwork and good communication in Vietnamese, English, New technical update\n- Progress management skill, documentation skill and review skill are required.\n- Self-awareness and confidence\n- Sense of responsibility, result-oriented and deadline commitment.\n- Ready for Short time Onsite Support /Over sea biz trip if company request.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Nam Từ Liêm, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1824, 702, 2, 'Data Scientist（LLM）', 'Binance is the leading global blockchain ecosystem and cryptocurrency infrastructure provider whose suite of financial products includes the world’s largest digital-asset exchange.\n\nOur mission is to accelerate cryptocurrency adoption and increase the freedom of money.\n\nIf you’re looking for a fast-paced, mission-driven organization where opportunities to learn and excel are endless, then Binance is the place for you.\n\nResponsibilities:\n\n- Conduct research on cutting-edge LLM technologies, including but not limited to: large language models and fine-tuning techniques, retrieval-augmented generation (RAG), prompt engineering, and knowledge-grounded dialogue systems.\n- Enhance overall performance for foundation models, encompassing data acquisition, model evaluation, SFT, reward modeling, and reinforcement learning.\n- Explore new downstream products with AI and AI agent technologies at their core for Binance products.\n- Stay up-to-date with the latest academic and industrial advancements in AI, LLMs, etc.\n\nQualifications:\n\n- Master’s or PhD in Software Development, Computer Science, Computer Engineering, or a related technical discipline.\n- At least 3-5 years of relevant industry experience in developing Machine Learning models at scale from inception to business impact\n- Research experience in LLMs, multi-modal understanding, vision and language, and other related topics.\n- Highly competent in algorithms and programming; strong coding skills in Python, C/C++, etc.\n\nPreferred Qualifications\n\n- Experience in NLP and LLM technologies.\n- Publications in top-tier venues, such as KDD, CVPR, NeurIPS, ICLR, ICML, EMNLP, ACL, ECCV, ICCV, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1825, 880, 2, 'Freelance Software Developer (Java) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with Java\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\nWhy this freelance opportunity might be a great fit for you?\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Haiphong, Haiphong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1826, 808, 2, 'SOFTWARE ENGINEER', 'Job Description\n\n- Participate in design, development, and implementation of software features according to business requirements.\n- Write and maintain comprehensive design documents.\n- Debug, troubleshoot, and resolve complex software defects and production issues.\n- Monitor code performance, identify bottlenecks, and implement optimizations.\n- Collaborate with cross-functional teams, including product managers, designers, and QA engineers, to deliver high-quality software.\n\nRequirements\n\n- College or university graduated, major in computer science or IT or equivalent.\n- 3+ years of post-graduation work experience as a Software Engineer.\n- Extensive experience in backend development using either .NET (C#) or Java.\n- Experience with front-end technologies such as HTML5, CSS3, JavaScript, and modern JavaScript frameworks (e.g., React, Angular, Vue.js).\n- Knowledge of setting up, maintaining, and monitoring Azure services such as Virtual Machine, Manage Disk, Azure SQL, Load Balancer, Application Gateway, etc. is a plus.\n- Ability to work independently and effectively in a team environment.\n- Good English communication skills, with the ability to communicate smoothly with customers.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1827, 1006, 2, 'Developers: Frontend, Backend and Full-Stack', 'About Us\nColonial Surety Company is an insurance company licensed for business in every state, listed by the U.S. Treasury as an approved surety, and rated “A Excellent” by A.M. Best Company. Our distinct, digital product platform has recently expanded to include important liability coverages for small and mid-size businesses.\nFounded in 1930, we use our experience—plus technology—to give busy people and businesses easy, affordable and digital access to a growing portfolio of bond and insurance products. We have an ambitious vision for impact and growth—and invite a diversity of motivated achievers to come, learn, work, create, grow—and succeed—with Colonial.\n\nPosition Summary\nWe’re creating—on a fast track! Our Developers will dive right to the action, with web and application development that elevates every product line across the company as we pursue ambitious growth. The candidate will be a member of a cross-functional team that includes other developers and product experts from across the organization. This is a great opportunity for highly motivated, self-directed developers who thrive on tight time frames and use their analytical prowess and top-notch interpersonal skills to deliver stellar results.\n\nJob Functions, Essential Duties, And Responsibilities\n- Design, maintain and tune high performance code.\n- Apply appropriate approach, best-practice and correct separation of presentation code from business logic.\n- Implement and support build processes and test environments.\n- Provide project and task estimates.\n\nFrontend\n- Determine optimal front-end development direction based on project requirements\n- Turn interface designs into functional themed components\n- Design, develop and implement shared design components with other designers and developers to use across Colonial’s digital product portfolio\n\nBackend\n- Responsible for developing, enhancing, modifying and/or maintaining applications.\n- Deeply understand requirements and expertly handle Analysis, Design, Coding, Testing and Quality processes.\n\nExperience, Skills, Knowledge Requirements\n- Bachelor’s degree preferred but not required.\n- 5+ years of progressive, hands-on development experience on multiple stacks and a commitment to quality design and clean code.\n- Familiarity with on-site and off-shore delivery model.\n- Full Software Development Life Cycle (SDLC) Experience and experience with 3rd party software integration on both the server-side and client-side.\n- Experience with headless, decoupled CMS architecture.\n- Skilled at interfacing with RESTful APIs, including a solid understanding of API architecture.\n- Demonstrated knowledge of client-side/backend performance analysis and optimization techniques.\n- Desire to set and meet aggressive goals and ability to work in a fast-paced environment with a risk management mindset.\n- Stellar organizational, analytic and communication skills, and the ability to methodically solve problems across teams.\n- An energetic, agile-minded, optimistic, pragmatic and collegial team-player.\n- Excellent at English reading comprehension (MUST)\n- Excellent at English communication\n\nFrontend\n- Experience with a preprocessor (gulp, grunt)\n- Minimum 2+ years of front-end focused web development including mobile-first development and familiarity with cross-browser compatibility\n- Experience with Angular\n- Experience with a modern JavaScript client-side framework (Angular 9+, React, React native)\n- Experience with one of open source CMS (WP, Drupal, Expression Engine, etc)\n\nBackend\n- Experience with Microservices and Spring boot\n- Experience with one scripting/programming language (Java EE/Core, PHP, Ruby)\n- Experience with CI/CD pipeline and automation (Kubernetes and Docker)\n- Experience with relational databases, SQL and ORM technologies (SQL Server, Postgresql)\n- Experience with data pipeline and ML/AI are plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1828, 839, 2, 'Full-Stack Developer (NodeJS, ReactJS)', 'About us: Founded in 2020, Var Meta has 80+ engineers heavily focused on blockchain, virtual reality/augmented reality technologies and AI. We work with customers from different parts of the globe like Hong Kong, Japan, Singapore, US to help them build products like Crypto Trading Platform, Launchpad, Securities Tokenization Offerings, eWallets, and NFT Marketplace, etc. We are trusted by global brands like Ubisoft, Hedera, Aptos.  About this opportunity: We\'re looking for a Full-Stack Developer to join our team with NodeJS & ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc. who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.  You will: Working with Product Owners to convert business requirements into technical designs. Working and pair programming with other developers to build applications with Node.JS and ReactJS. Design and develop scalable front-end solutions using ReactJS Build and maintain robust back-end systems with NodeJS Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment. Collaborate with cross-functional teams to define, design, and ship new features Ensure code quality, security, and performance optimization  Your Skills and Experience: Knowledge of responsive design techniques and front-end optimization methods. At least 4 years of experience as a Full-Stack Developer (Node.js & React.js). Strong proficiency in front-end technologies, particularly React. Expertise in back-end development using Node.js. Hands-on experience with Web3 integration. Solid understanding of smart contract development and deployment. Good command of English (both verbal and written). Knowledge of cryptography and blockchain is a plus.  Why You\'ll Love Working Here: Build World class product(s): We love to solve complex problems and learn new things. Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region. Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills. Enjoy competitive salary, bonus according to work performance 13th Salary Assistance with operational tools and equipment. Health insurance program for employees provided by PVI. Annual health check-up from Medlatec Clinic Participate in social insurance after becoming an official employee Salary review twice a year. It means we are pushing each other to be better everyday. Flexible working hours, freestyle attire  Perks You\'ll Enjoy: Working in a young, super talented, and supportive team environment Technical, English certificate bonus Day-off: 12 days/year and Vietnam holidays Happy Hour, Football club, English club, and many exciting activities Company trip/ team building/ Year End Party Free coffee, snacks, and drinks  Contact HR Var Meta via: Email: hr@var-meta.com Fanpage: https://www.facebook.com/profile.php?id=61558234221306', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Région métropolitaine de Hanoï', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1829, 720, 2, 'Senior Fullstack Engineer (AWS)', '💼 Senior Fullstack Developer – Cloud Application Project | SCC Vietnam\n\n📍 Ho Chi Minh City, Vietnam | 💻 Hybrid/Remote-friendly\n\n🚀 Join a European tech leader driving cloud innovation in Post Office systems\n\n⸻\n\n🔍 About the Role\n\nWe’re looking for a Senior Fullstack Developer to join our Vietnam-based team, working on a large-scale cloud-based system for Post Office (UK). You will lead a team of developers, collaborate with Architects & Product Owners, and deliver robust, scalable, and secure software solutions.\n\nThis is a senior role ideal for someone ready to own the codebase, remove blockers, and bridge technical conversations between devs and architects.\n\n⸻\n\n🧠 What You’ll Do\n• Lead the technical delivery of cloud-native applications.\n• Design, build, and maintain high-performing services (serverless/microservices).\n• Collaborate closely with cross-functional Scrum teams across Vietnam, UK, and France.\n• Implement DevOps best practices, CI/CD pipelines.\n• Champion code quality, documentation, and innovation.\n• Troubleshoot and resolve production-level issues.\n• Stay updated on AI, Data, and emerging cloud tech (yes, we love Co-pilot too).\n• Promote a culture of continuous improvement and mentoring.\n\n⸻\n\n🧰 Your Skills & Experience\n✅ Must-have:\n• 5+ years’ experience in software development, preferably in cloud environments.\n• Strong experience with Python, TypeScript, or C#.\n• Cloud platform knowledge (AWS, Azure, or GCP) – certification is a plus.\n• Experience with Agile/Scrum, Git, and DevOps practices.\n• Excellent problem-solving, team leadership, and communication skills.\n• Good English – verbal & written – for daily work with UK team.\n\n🪄 Nice-to-have:\n• Experience with AI/ML concepts, Data Analytics, Data Warehouse.\n• Familiarity with Webdriver.io or Selenium for automation testing.\n• Experience with Power BI or cloud dashboards is a bonus.\n\n⸻\n\n👥 Who You’ll Work With\n• Report to VN/UK Technical Architect.\n• Cross-site collaboration with UK, Romania, and France tech teams.\n\n⸻\n\n🌍 About SCC Vietnam\n\nSCC (Specialist Computer Centres) is a UK-based IT leader operating in over 50 countries with 2,500+ enterprise customers. In Vietnam, we build critical software systems, infrastructure support, and digital transformation services for our UK & French clients.\n\n⸻\n\n🎁 What We Offer\n• Competitive salary, performance bonus & 13th-month salary.\n• Premium healthcare (includes dependents), annual health check.\n• Hybrid working policy & international exposure.\n• Travel insurance, annual trip, training & certifications support.\n\n⸻\n\n🚀 Ready to join a team that builds systems powering the UK’s national infrastructure?', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1830, 998, 2, 'C/C++ Developer (All Levels)', 'Responsibilities\n- Participate in the development of the company service project.\n- Collaborate in a team environment to design, develop, and deliver reliable software solutions for customers.\n- Design, develop, document, analyze, test, integrate, debug, research, and integrate new architectural features into existing infrastructures.\n- Verify that developed product features are thoroughly implemented, meeting all specified requirements.\n- Continue to learn new technologies, introduce existing products, improve the product experience and create more value.\n\nQualifications\nEducational Background:\n- Bachelor\'s degree or higher in Computer Science, Engineering, or a related field.\n\nProfessional Experience:\n- At least 1 year of software development experience with a significant focus on C++/C# WPF and Windows applications.\n- Strong background in designing and developing desktop applications on the Windows platform.\n\nTechnical Skills:\n- Have knowledge of C++ with understanding of the standard library, STL containers, and algorithms.\n- Experience with Windows API and Windows Services.\n- Proficiency with Microsoft Visual Studio and the Windows SDK.\n- Experience with user interface design and development in Windows.\n- Knowledge of threading, sockets, and inter-process communication (IPC).\n- Familiarity with code versioning tools such as Git.\n- Experience with continuous integration and deployment environments.\n\nPersonal Skills:\n- Strong analytical and problem-solving skills.\n- Excellent written and verbal communication skills.\n- Ability to work independently and in a team environment.\n- Strong attention to detail and a commitment to delivering high-quality software.\n\nBenefits\nSuccessful candidates will be part of a friendly, motivated and committed talent teams in FPT Software HCM (FSOFT) with various benefits and attractive offers:\n- Successful candidates will be offered a friendly, motivated working environment.\n- Get involve in major full-cycle project with large scale and opportunities to work directly with specialists and experts in system designing in Japanese top corporations in producing medical devices.\n- “FPT care” health insurance provided by PTI and is exclusive for FPT employees.\n- Company shuttle buses provide convenient way of transportation for all employees.\n- Annual Summer Vacation: following company’s policy and starts from May every year.\n- Other allowances: transportation support by company bus, lunch allowance, working on-site allowance, etc.\n- F-Town Campus provide many facilities for FPT Software employees such as football ground, basketball & volleyball, gym center, cafeteria, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1831, 1007, 2, 'PHP Developer', 'Job Description\n- Analyze requirements and propose technical solutions.\n- Write detailed specifications and develop high-quality applications.\n- Troubleshoot, test, and maintain the core product software and databases to ensure strong optimization and functionality.\n- Contribute to all phases of the development lifecycle.\n- Develop and deploy new features to facilitate related procedures and tools if necessary.\n- Report to the Team Leader.\n\nJob Requirement\n- At least 2 years of working experience in the same position.\n- Proven software development experience in PHP frameworks.\n- Have experience in front-end including HTML, CSS, JavaScript, AJAX, etc.\n- Have experience with Symfony, Drupal, and Yii framework.\n- Good knowledge of MySQL data stored procedures, version control tools, and database optimization experience.\n- Mastering Source Control (SVN/Git).\n- Good English reading and writing skills.\n- Careful, highly organized, and self-learning attitude.\n\n** If your work experience and skill set match this role, we\'ll contact you to schedule the interview in the next 7 working days.\n\nOur Benefits and Perks\n- Attractive salary commensurate with your expected salary and working experience.\n- Full pay during the probation period.\n- The total contribution to social insurance is based on the Net salary.\n- 13th-month salary.\n- 14 days of annual leave.\n- Company bonus.\n- Annual health check-ups.\n- Monthly parties.\n- Quarterly team outing budget.\n- Yearly company trip.\n- Employee gifts for special occasions, such as celebrations and birthdays.\n- Premium healthcare (PTI).\n\nWorking time:\n- From Monday to Friday\n- Ho Chi Minh office (08:30 AM – 05:30 PM)\n- Can Tho office: (08:00 AM – 05:00 PM)\n\nCompany Address\n- Ho Chi Minh Office:\nUnit B1-B3-B4, 16th Floor, International Plaza Building\nNo. 343, Pham Ngu Lao Street, Pham Ngu Lao Ward, District 1, Ho Chi Minh City\n\n- Can Tho Office:\n1st Floor, STS Tower, No. 11B, Hoa Binh Avenue, Tan An Ward, Ninh Kieu District, Can Tho City', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1832, 1008, 2, 'Kỹ sư phần mềm', 'Mô tả công việc\n\nLập trình phần mềm cho khách hàng Nhật.\n\nCÁC DỰ ÁN CÔNG TY ĐANG THỰC HIỆN :\n\n1. Phát triển Web app về Crowdfunding (Kêu gọi vốn cộng đồng) bằng Java sử dụng tại thị trường Nhật Bản\n\n2. Dự án R&D nghiên cứu tính năng mới cho các công cụ tương tác theo thời gian thực, có sử dụng công nghệ Google Drive Realtime API, Realtime API discon, Realtime Database, Cloud Firestore,...\n\n3. ‎Dự án phát triển website quản lý và phân tích doanh thu của chuỗi cửa hàng bán lẻ tại Nhật Bản\n\n4. ‎Dự án ứng dụng công nghệ blockchain cho web app về crowdfunding\n\n5. Dự án phát triển website hotel booking online sử dụng SPA (Single Page Application), công nghệ AI và IoT để check-in tự động, nhằm giảm chi phí quản lý và tăng trải nghiệm người dùng,...\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1833, 1009, 2, 'Node.js Backend Developer', 'Hạn nộp hồ sơ: 30/06/2025\nỨng tuyển ngay\nMức lương\nThỏa thuận\nSố lượng tuyển\n3 người\nHình thức làm việc\nToàn thời gian\nCấp bậc\nNhân viên\nKinh nghiệm\n3 năm\nGiới tính\nKhông yêu cầu\nĐịa chỉ làm việc\nHồ Chí Minh: Cao ốc Hoàng Việt, 34 Hoàng Việt, Phường 4, Quận Tân Bình, Thành phố Hồ Chí Minh.\n\nJob Description\n- Design, develop, improve, and maintain core and new software components and frameworks\n- Contribute to technical designs, discussions, system architecture and implementation\n- Identify and learn about new programming/development technologies, techniques, tools, and trends\n- Participate in design and code reviews\n- Apply industry best-practice software standards and technology\n- Work closely with other developers to support frontend modules that delight our users\n- Supporting QA during testing, and oversight during implementation into production\n\nJob Requirements\n- Minimum 2 years of experience in programming; 1 year in Node.js\n- Prior experience using React.js\n- Familiar with Linux Development Environment\n- Non blocking IO, websocket, cluster process\n\nBenefits\n- Negotiable Salary + Lunch allowance\n- 13th- month salary, salary review once/year, Tet gifts, birthdays, Mar 8, Jun 1, Oct 20, …\n- Full insurance regime according to regulations such as social insurance, unemployment insurance, and health insurance\n- PVI insurance\n- Travel, team building activities, year-end party, …\n- Dynamic working environment, professional\n\nLOCATION & TIME\n- Location: 9th floor, 34 Hoang Viet, Ward 4, Tan Binh District, Ho Chi Minh\n- Time: Monday – Friday: 8:00 – 17:00, Saturday: 8:00 – 12:00\nHạn nộp hồ sơ: 2025-06-30 00:00:00\nỨng tuyển ngay', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Phố Cao Lãnh, Tỉnh Đồng Tháp, Việt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1834, 707, 2, 'DevOps Engineer (Junior/Middle)', 'Job Description\n\nDesign and manage Kubernetes Helm charts and CI/CD pipelines for secure, scalable rollouts.\nOperate and secure Linux-based infrastructure\nManage PostgreSQL\nDesign, implement, and manage cloud infrastructure on platforms such as AWS\nDevelop and maintain robust CI/CD pipelines using tools like Jenkins, GitLab CI/CD, GitHub Actions, AWS Codebuild, AWS CodePipeline\nAutomate infrastructure deployments using Infrastructure as Code (IaC) tools such as Terraform\nImplement comprehensive monitoring, logging, and alerting solutions using tools such as ELK\nProactively identify technical gaps in existing solution designs, conduct research and development to propose improvements, and take the lead in executing and implementing the recommended solutions.\nEnsure systems adhere to security best practices, perform security assessments, and apply patches proactively.\n\nJob Requirements\n\nMUST HAVE:\n\nAt least 2 years of experience in DevOps roles, especially in international software projects\nExperience with public cloud platforms: AWS\nExperience with following languages: powershell script, bash script\nFamiliarity with databases and messaging systems: PostgreSQL\nExperience with Docker, Kubernetes or another container based system\nExperience with IaC tools: Terraform\nExperience with logging system Kibana\nExperience with Jenkins or similar tools\nFamiliarity with networking concepts (TCP/IP , DNS, firewalls, load balancers)\nMUST be good at verbal/non verbal English\n\nNice To Have\n\nExperience with one of the following tools: Ansible, Team City, Github Action\nWilling to work over the weekend to when production server have issues\nExperience to migrate on-premise system into cloud\n\nBenefits\n\nCompetitive Salary and Brilliant Health Benefits\n\nAttractive salary (13th-month salary, salary review twice/year) and project bonus\nBonus programs for candidate referral, technical article writing\nInterest-free loan support for personal plan \nAllowance for sickness, maternity, paternity and periodic health examination\nPVI health care program \nThe staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\nA professional English-speaking working environment with Agile – Scrum model\nHybrid Working Model: Flexible working time and WFH support. \nSurrounded with friendly, open-minded, young and supportive colleagues \nAnnual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\nSponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\nSponsor fee for joining any technical training sessions and courses.\nFree English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1835, 1010, 2, '【教育事業】SREエンジニア', '職務内容\n\nスマートフォン・パソコンで様々な授業を受けることができる教育サービス「ZEN Study」および付随する管理システムのインフラ構築・運用を担当していただきます。\n\nサービスの紹介\n\n私たちは、未来の「当たり前」の教育をつくるため、生徒・学生や教職員の「学ぶ」「教える」体験の最大化を日々目指しています。\n\n日本発の本格的なオンライン大学「ZEN大学」や、2万名を超え日本最大の生徒数であるネットの高校「N高等学校・S高等学校・R高等学校」と連携し、ネットの時代に合わせた教育関連のサービスを開発・運営しています。\n\nZEN Study（旧: N予備校）\n\nひとつで学習が完結するオールインワン学習アプリです。\n\n主に次のような機能を提供しています。\n\nリアルタイムに先生や仲間の生徒とコミュニケーションを取ることで理解を深める「ライブ授業」\n自分のペースで学習を進めることができて一目で進捗率がわかる「教材」\n学習者同士の教え合いの場「フォーラム」\n\n※「N予備校」は2024年8月末に「ZEN Study」にリニューアルしました\n\nZEN Compass\n\n学習者を導く先生方などが利用するコーチング支援Webサービスです。\n\nLMS(Learning Management System)として学習状況を見ることができるだけではなく、より学習者を効率的に支援できるように、さまざまな指標で先生方を支えます。\n\n募集背景\n\n私たちSREチームは、ZEN Studyおよび付随する管理システムのインフラ設計・構築とその提供に責任を持ち、運用業務に取り組んでいます。\n\nN高等学校・S高等学校・R高等学校の拡大、またZEN大学の開学に伴い、ZEN Studyの利用ユーザは年々増加しています。\n\n大勢の学生が同時に利用しても快適に学習をおこなえるサービス環境の提供、また障害を起こさない・万が一の際の復旧が容易になるインフラ設計等\n\nサービスの安定提供に向けて、一緒に新たな施策の導入や課題解決をしていけるエンジニアを募集します。\n\n業務内容\n\nアプリケーションのアップデートに起因する既存サービス環境への設定変更の他、新規サービス用の新環境構築など、インフラ構築・運用業務に幅広く関わっていただきます。\n\nご担当いただく業務例\n\nインフラ設計・構築\n\nアプリケーションチームに要件のヒアリング・提案\n要件をもとに、構築作業\n\n障害対応\n\nサービスで発生したエラーについて、インフラに起因すると思われる事象についての調査対応\n\n運用改善\n\n運用の負荷軽減を目的とした監視改善\n手運用削減のための自動化導入\n\n開発環境\n\n使用言語/ライブラリ\n\nPython\n\ntf\n\nPublic Cloud\n\nAWS EC2, EKS, S3, RDS, Elasticsearch, Lambda…\n\nGCP BigQuery, Cloud Functions, Cloud Storage…\n\n使用ツール\n\nGitHub\n\nGoogle Meet\n\nSlack, Google Workspace, JIRA, Confluence\n\n関連リンク\n\nエンジニア採用説明資料\n\nhttps://speakerdeck.com/nnndev/for-engineers?\n\n開発者ブログ\n\nhttps://blog.nnn.dev/entry/2021/06/17/110000\n\nZEN Study\n\nhttps://www.nnn.ed.nico/\n\nN高等学校・S高等学校・R高等学校プロジェクト採用\n\nhttps://www.nnn.ed.nico/recruit/\n\nZEN大学\n\nhttps://zen.ac.jp/\n\n必須要件\n\nterraform（または同等のIaCツール）を用いたインフラの運用・保守経験\nAWSまたはGCP、その他Public Cloud上でのインフラ運用経験が3年以上、または相当する経験がある\nDocker, Kubernetes 等のコンテナ技術を利用したアプリケーションの構築・運用経験\n\n歓迎要件\n\nWebアプリケーション実装の経験（フロントエンド・サーバーサイド問わず）\n大規模なWebアプリケーションのインフラの運用・保守経験\n障害発生時の調査・復旧対応の経験\nプロジェクトマネジメントの経験\nステークホルダーとの要件調整\n3人以上のチームでのリーダー経験\n2ヶ月以上の期間にわたるプロジェクトの計画と進捗管理\n\n求める人物像\n\n「未来の当たり前の教育をつくる」という教育事業の理念に共感していただける方\n一緒に働く仲間やステークホルダーに敬意を持ち、相手の感情を理解したコミュニケーションをとれる方\n新しい技術やマネジメントスキルの習得などに意欲を持ち、自己の成長に積極的な方\n\n職種 / 募集ポジション 【教育事業】SREエンジニア\n雇用形態 正社員\n給与 応相談 前職を考慮し、当社基準により決定いたします。\n昇給：年2回（6月・12月）本人の能力・役割に基づいて評価\n賞与：年2回（6月・12月）本人の成果に基づいて支給 ※ご入社時期、個人の評価、会社の業績により夏季賞与・冬季賞与額が変動いたします。\n※退職金は前払い退職金制度\n勤務地\n\n104-0061 東京都中央区銀座四丁目12-15 歌舞伎座タワー 地図で確認\n\n勤務形態 裁量労働制（1日8時間のみなし労働)\n休日休暇 完全週休2日制（土・日）、祝日（※超会議に伴う営業日変更あり） ・年次有給休暇（入社日に5日、入社日の3ヶ月後に15日付与） ・記念日休暇 ・年末年始休暇（12/29～1/3） ・リフレッシュ休暇（年度ごとに2日間付与） ・特別（慶弔）休暇\n手当・制度 ・テレワーク手当 ※テレワーク対象となる社員（条件有り）に対し、月額2万円を支給 ・通勤交通費手当（上限月額50,000円） ※テレワーク対象者は原則支給しない ただし、業務指示における出社時の交通費は会社が認める範囲で別途支給 ・育児手当（上限月額50,000円） ※扶養の子の保育料の半額を支給 ・役職手当（役職に応じて支給） ・資格取得手当制度 ・サブスク手当（対象のサブスクを契約している場合、月額2千円を支給）\n福利厚生 ・各種社会保険完備（関東ITソフトウェア健康保険組合） ・確定拠出年金制度 ・財形貯蓄制度 ・社員持株会制度 ・社内カウンセリング制度 ・同好会 ・健康保険組合各種サービス ・社員限定美容室\n選考プロセス 書類選考後、2回の面接を想定しています。 ※1次面接までに当社が指定する適性検査を受検いただきます。 ※全てオンライン面接となります。 ※選考の過程でコードテストを実施する可能性があります。\n会社情報 会社名 株式会社ドワンゴ 代表者 代表取締役社長 夏野 剛 事業内容 ネットワークエンタテインメントコンテンツ及びシステムの企画、開発、運用、サポート、コンサルティング 設立 1997年8月6日 資本金 1億円（2019年3月29日現在） 所在地 〒104-0061 東京都中央区銀座4-12-15 歌舞伎座タワー 親会社 株式会社KADOKAWA 子会社 株式会社バンタン 株式会社スパイク・チュンソフト Spike Chunsoft, Inc. 株式会社バーチャルキャスト 株式会社カスタムキャスト 株式会社GeeXPlus 株式会社PUBLUS.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 12, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1836, 740, 2, 'Fullstack NodeJS/ Python+ReactJS/Golang+ReactJS', 'Job description:\n❖ GUI development by utilization of new front-end technologies \n❖ Troubleshooting end user issues and automated processes \n❖ Develop and maintain backend API \n❖ Perform unit testing \n❖ Analyze errors and developing potential solutions \n❖ Consulting with managerial, engineering, and technical personnel to clarify program intent, identify problems and suggest/implement changes \n❖ Conducting trial runs of software application updates, and fixes, to ensure desired functionality \n❖ Independently creating software development documents (SRSes, design documents, etc.) \n❖ Developing and demonstrating knowledge of related systems \n❖ Willingness to contribute ideas to the troubleshooting and resolution of application issues in a timely manner \n❖ Pro-actively looking for the best solution to achieve the most efficient performance the systems \n❖ Interacting with all stakeholders as required \n❖ Adhoc duties as required.\n\nRequest:\n1, FullStack\n- Google ADK\n- Workato Exp\n- Python, Golang & React Exp\n- Building MCP Servers\n- Basic ML\n \n2, BE (Golang)\n- Hexagonal Architecture\n- RabbitMQ\n- Postgres DB\n- Redis\n- Excelize Dynamic Writing\n- GraphQL & REST\n \n3, BE (Python w Golang)\n- Flask Framework (Creating UI as well)\n- REST\n- Embed PowerBI and Looker Dashboard\n- MSSQL and Postgres Functions + Stored Procedures\n- Message Queue, Caching and Docker Management\nBenefit: \n- Salary 4x M VND \n- Package 14 salary months based on KPI \n- Extra package upto 16M/ year \n- Young and dynamic working environment. \n- Continuous development of hard and soft skills through work and \n- Exciting leisure: sport and art events (football club, family day...) \n- Company\'s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\nContact details: \nEmail: ltthanh6@cmcglobal.vn\nZalo: 0902254369', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1837, 1003, 2, 'Backend Engineer (Python) - AGI', 'We are looking for Software Engineers to join our cutting-edge Artificial General Intelligence (AGI) project. If you are passionate about AGI, have a strong background in Python (Go, Java,...) and excel at problem-solving, critical thinking, and self-learning, we invite you to apply for this exciting opportunity.\n\nResponsibilities\n\nCollaborate with engineering teams to design, develop, and deploy business critical solutions.\nStay continuously informed about the latest advancements and trends in the AGI field.\nWrite clean, maintainable, and efficient code to implement new features and functionalities.\nResearch and adopt new techniques and methodologies to solve complex problems, utilizing critical thinking and analytical skills.\nProactively identify and address complex issues related to task management, load balancing, and system scalability.\nShare knowledge through peer-to-peer collaboration, conduct code reviews, provide technical guidance, and mentor junior team members as needed.\n\nRequirements\n\nBachelor’s degree or higher in Computer Science, Engineering, or a related field.\nOver 3 years of experience in software engineering.\nProficiency in backend development in an object-oriented language. Proficiency in either Python, Golang, Node.js or C# and the willingness to learn another.\nFamiliarity with distributed task management systems and job queues like Celery, Faktory, BullMQ or others.\nExperience in full-stack engineering is highly desirable and willingness to work with tools like HTMX, jQuery or React.\nGood understanding of relational databases, locks, indexes and transactions. Strong SQL skills.\nDemonstrated ability to quickly learn and adapt to new technologies and programming languages.\nExcellent problem-solving skills, with a strong understanding of algorithms and data structures.\nFamiliarity with best practices in the software development life cycle, including version control, code reviews, and testing frameworks.\nAbility to work effectively both independently and collaboratively within a team environment.\nFamiliarity with writing unit tests.\n\nIf you believe you have what it takes to excel in this role and contribute to the development of AGI solutions, please submit your resume and any relevant code samples or project links. We look forward to reviewing your application and exploring the possibility of welcoming you to our team.\n\nWhat We Offer\n\nJoin our team and enjoy:\n\nCompetitive compensation package, including 13th-month salary and performance bonuses\nComprehensive health care coverage for you and your dependents\nGenerous leave policies, including annual leave, sick leave, and flexible work hours\nConvenient central district 1 office location, next to a future metro station\nOnsite lunch with multiple options, including vegetarian\nGrab for work allowance and fully equipped workstations\nFun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\nUnlimited free coffee, tea, snacks, and fruit to keep you energized\nAn opportunity to make a social impact by helping to democratize credit access in emerging markets\n\nAbout Us\n\nWe are an AI Fintech company specializing in assessing credit profiles of consumers in emerging markets combining pioneering AI with large alternative data sources. In 2020 we reached our ambitious milestone of credit profiling 1 billion consumers spanning 4 countries - Vietnam, Indonesia, India & the Philippines - and building a platform for the wider industry and the financial services industry, in particular, to provide the "un & under" served access to credit. At the core of this initiative has been our strict and unwavering adherence to the norms of consumer data privacy and consumer data rights.\n\nBut we\'re not satisfied as we embark on the next leg of our journey to deliver 100 million credit lines to consumers in the markets where we operate. Although this goal is ambitious, we truly believe that by harnessing the power of AI & Big Data we can deliver financial access at an unprecedented scale.\n\nAs a firm, we\'re audacious problem-solvers motivated by our impact on society. We deeply espouse the values of ownership - of our actions and initiatives, integrity in all we do, and agility in execution.\n\nWe place great importance on doing what is right, what is best, and what is innovative. If you are smart, driven, and want to make a difference in the world with the most advanced and fascinating technology, come join our team. We can satisfy your desire to explore new territory and give you the runway to really make an impact.\n\nAdditional Info\n\nLearn more about us here:\n\nhttps://www.youtube.com/watch?v=inAEDGvOcL8&t=29s', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1838, 264, 2, 'AI Engineer', 'Our company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n\n- Design, develop, and deploy AI models using machine learning (ML), deep learning, and natural language processing (NLP) techniques.\n- Collaborate with cross-functional teams to understand business requirements and translate them into AI solutions.\n- Collect, preprocess, and analyze large datasets to train and evaluate models.\n- Optimize and fine-tune algorithms for performance and scalability.\n- Integrate AI models into existing applications or develop new AI-powered systems.\n- Monitor and maintain AI systems in production to ensure reliability and accuracy.\n\nWhat you’ll bring\n\n- Bachelor’s or Master’s degree in Computer Science, Engineering, Mathematics\n- Proven experience in building and deploying machine learning or deep learning models.\n- Proficiency in Python and ML libraries such as TensorFlow, PyTorch, Scikit-learn, etc.\n- Familiarity with cloud platforms (AWS, GCP, Azure) and ML services.\n- Experience with data processing tools (e.g., Pandas, NumPy, SQL).\n- Understanding of algorithms, data structures, and software development best practices.\n- Strong analytical, problem-solving, and communication skills.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion\n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville et périphérie', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1839, 1011, 2, 'Senior Java Software Engineer', 'Job Requirements:\n\nParticipate in software development projects with clients using Java.\nUnderstand requirements, analyze projects, and perform coding tasks.\nWork onsite at the client’s office in District 7, combined with hybrid working.\nRequired Skills:\n\n4–6 years of experience working with Java, Spring MVC, Spring Boot, etc.\nKnowledge and hands-on experience with MongoDB.\nProficient in SQL, PL/SQL for Oracle database programming.\nAbility to read and understand English.\nWhy You Should Work at Tinh Van:\n\n• 24/7 health insurance (MIC Care).\n• 13++ months of salary per year.\n• Performance and salary review twice a year.\n• Salary based on capability: from 25M to 30M VND depending on the candidate\'s level + allowances.\n• Income: 13th-month salary + project bonuses up to 2 months’ salary, Tet and holiday bonuses.\n• Salary review twice a year: once periodically and once based on performance and contribution.\n• Days off: Saturdays, Sundays, and a minimum of 12 annual leave days, in accordance with current labor laws.\n• Participation in social insurance, health insurance, and unemployment insurance as per legal regulations.\n• 24/7 healthcare insurance (MIC Care) after 24 months of employment.\n• Access to company clubs: football, badminton, and more.\n• Participation in exciting company events: annual vacations, quarterly team buildings, company birthday, year-end gala, etc.\n• Supportive welfare policies: health visits, maternity, condolences, congratulations, birthdays for both employees and family members.\nSpecial Benefits:\n\n• 50% support for external course fees; 100% support for IT certification exam fees and soft skill courses.\n• Immediate one-level salary raise upon certification acquisition; bonuses from 3 to 10 million VND upon certification completion.\n• Opportunities to work and receive training in Japan or Singapore for candidates with Japanese or English proficiency.\n• Young, dynamic working environment that fosters personal growth and career development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1840, 1012, 2, 'SQL developer', 'Established in 2019, Jaish Global has rapidly evolved into a distinguished solution provider in the cybersecurity space and SI integrator in Digital Transformation using Machine Learning & Artificial Intelligence. Jaish Global Consultancy is an Umbrella company certified by ISO 9001:2015 and ISO 27001. Our unwavering focus on quality and innovative niche technology solutions creates a true edge. Our commitment to excellence has positioned us as a trusted technology-driven organization, safeguarding customer businesses from the ever-evolving landscape of cyber threats and creating business values in customers\' enterprise portfolios using our AI tools and services. We never stop pushing the boundaries of what is possible. We are always learning, growing, and re-skilling in Technology solutions and process mapping to stay at the forefront of the industry. Our dynamic culture reflects our drive to be the best. We are providing the services to our customers keeping in view to -> Quick response to change and support for enterprise agility aligned with the business strategy -> Organizational transformation, adopting new trends in business and technology -> Organizational change to support Digital Transformation -> Organizational and operating model changes to improve efficiency and effectiveness -> Lower business operation costs Improved business productivity -> Extending the effective reach of the enterprise (e.g., through digital capability)\n\nThe Role\n\nRole Overview\n\nWe are seeking a skilled and enthusiastic SQL Developer to join our growing data team. In this role, you will be responsible for designing, developing, and maintaining databases and data solutions. The ideal candidate will have a strong understanding of SQL and database principles, with a proven track record of optimizing database performance and ensuring data integrity.\n\nResponsibilities\n\n- Design, develop, and implement database solutions, including tables, views, stored procedures, and functions.\n- Write complex SQL queries to retrieve, manipulate, and analyze data.\n- Optimize database performance for speed and efficiency.\n- Ensure data quality, accuracy, and consistency.\n- Troubleshoot and resolve database issues.\n- Collaborate with developers, analysts, and other stakeholders to understand data requirements.\n- Create and maintain database documentation.\n- Participate in database design and code reviews.\n- Stay up-to-date with the latest SQL Server features and database technologies.\n- Develop ETL processes to move data between databases.\n\nIdeal Profile\n\nQualifications\n\n- Bachelor\'s degree in Computer Science, Information Systems, or a related field.\n- 2-3 years of experience as a SQL Developer.\n- Strong proficiency in SQL (e.g., T-SQL, PL/SQL).\n- Experience with database management systems such as SQL Server, MySQL, or Oracle.\n- Understanding of database design principles and normalization.\n- Experience with query optimization and performance tuning.\n- Knowledge of data warehousing concepts.\n- Excellent analytical and problem-solving skills.\n- Strong communication and collaboration skills.\n- Ability to work independently and as part of a team.\n\nPreferred Skills\n\n- Knowledge of database administration tasks.\n- Familiarity with cloud-based database services (e.g., Azure SQL Database, Amazon RDS, Snowflake).\n- Experience with data visualization tools (e.g., Power BI, Tableau).\n- Knowledge of scripting languages (e.g., Python, PowerShell).\n\nWhat\'s on Offer?\n\n- Fantastic work culture', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1841, 998, 2, 'Full Stack Engineer - Python Angular/Reactjs (Senior, English)', 'Role: Senior Fullstack Developer – Good English – Location Hanoi\n\nJob Description\n- Design, develop, and maintain web applications using Python/ Go (Django/FastAPI/Flask) for the backend and Angular/ ReactJS for the frontend.\n- Architect scalable, high-performance, and secure systems.\n- Work with SQL databases (PostgreSQL/MySQL) and NoSQL databases (MongoDB, Redis).\n- Integrate APIs, process large-scale data, and optimize system performance.\n- Mentor and guide the development team, conduct code reviews, and ensure software quality.\n- Collaborate with BA, UI/UX, and QA teams to deliver optimal solutions.\n- Deploy and manage applications on cloud platforms (AWS, Azure, GCP).\n\nRequirements\n- 04 years of experience in fullstack development with Python and ReactJS/Angular.\n- Strong expertise in backend development using Django, FastAPI, or Flask.\n- Proficiency in frontend development using Angular (RxJS, NgRx, TypeScript).\n- Experience with RESTful API design, GraphQL, and microservices architecture.\n- Solid knowledge of cloud services (AWS, Azure, or GCP).\n- Familiarity with DevOps practices, CI/CD pipelines, Docker, and Kubernetes.\n- Strong problem-solving skills and ability to lead a technical team.\n- Excellent communication skills in English.\n\nPreferred Qualifications\n- Experience in AI/ML integration.\n- Knowledge of container orchestration and serverless computing.\n- Previous experience in fintech, e-commerce, or enterprise software development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1842, 1013, 2, 'Sr Front-End React JS Software Developer / Engineer | 100% Remote | SaaS | Construction Tech', 'export function getReactJSEngineer (you: Candidate){ let skills = ["ADVANCED_REACT", "ADVANCED_SQL"]; let work_interests = ["BIG_DATA", "TELEMATICS", "APIS", "OTHER"]; let company_type = ["USA_STARTUP", "REMOTE_WORK"]; let url = ["https://www.getclue.com"]; if (you.have(skills) && you.want(work_interests) && you.like(company_type)) { you.seePostAndContact(url); if (you.areHired()){ you.monthlySalaryFrom(3000, "USD"); return true; } } }; Senior Front-End React JS Software Developer / Engineer for a Heavily-backed Construction Tech startup revolutionizing Construction - 100% REMOTE ROLE We’re transforming the efficiency of the $20 trillion construction market. We’re looking for an exceptional developer to continue building our front-end and work alongside our front end and full stack developers. This role is 100% remote but you will need to be available at least for a few hours in US Eastern or Pacific time zones every day during kick offs. Clue uses data and AI to provide actionable insights that construction companies use to integrate, automate and optimize their operations. Our software is used by dozens of the US largest construction firms, we\'re growing rapidly, and we\'re backed by one of the world’s largest construction organizations. We are now looking for an excellent React.JS developer to help us build our web console and platform. The ideal candidate is someone who is passionate about building reliable, performant and scalable website using React.js components. We want an amazing React.js Developer to join our back-end development team. Your mission is to … → To build our front end web console, mostly in React. You will integrate our internal APIs use by our existing mobile and web apps. → Work alongside our back end developers implementing algorithms, analyzing our clients’ telematics data to generate the relevant insights. → Use a wide range of AWS services, including Lambda serverless instances, Redshift, and more. You fit to us if … → You have 3+ years of experience in React and Front-end development. Could be in communication and collaboration tools (e.g., social networks, communications, VOIP etc.) SaaS, enterprise software, business analysis or data hardware or machinery related. → You are intimately familiar with React, Javascript, Linux, Rest APIs, AWS and SQL. You ideally some experience with frontend coding. → You have a track record of building stable, performant infrastructure.. → You have worked at a startup and a fast-moving, sometimes hectic but always fun environment. Construction: the $20 trillion market looking for a clue The numbers are staggering. Construction is one of the world’s largest industries. 10% of the world’s GDP goes into construction. It’s also one of the most inefficient industries in the world. While almost all other industries became more efficient, construction became more inefficient. Since 1945, US productivity in manufacturing, retail, and agriculture has grown by as much as 1,500 percent, but productivity in construction has barely increased at all. This is about to change. Construction companies are finally waking up. They are spending more on IT than ever before. The amount of venture capital investment into construction startups jumped 4x in the last year alone, passing $2bn. To sum it up: Construction is one of the world’s biggest and least efficient industries yet to be disrupted. It is an open field, a wide blue ocean for the best entrepreneurs, startups and investors. The time to get into this market is now. Our hiring process: simple and fast. Please use the Apply function on our recruitment website and attach your CV. We typically give you our response within 48 hours. We prefer to have a video interview within a week after your application. Location: Fully Remote Start date: Immediate Compensation: The salary for this role is dependent on location and seniority. We aim to pay in the top 10% of salary range. We also offer a home office allowance, compute and internet allowance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1843, 778, 2, 'Back End Developer', 'Backend Developer\nLocation: Hanoi Office: Level 13-17, Leadvisors Tower, 643 Pham Van Dong Street, Hanoi\nLevel: Middle, Senior\n\nDUTIES & RESPONSIBILITIES\n- Design, develop, and deploy server-side banking applications and services using Go programming language.\n- Collaborate with cross-functional teams, including but not limited to, software architects, product managers, and frontend developers to understand project requirements and translate them into efficient and scalable backend solutions.\n- Write clean, reusable, efficient, secure and well tested code following industry best practices and coding standards.\n- Participate in code reviews to ensure code quality, maintainability, and adherence to established coding guidelines.\n- Troubleshoot and debug production issues, propose and implement solutions to ensure smooth and uninterrupted system operations.\n- Stay up to date with the latest trends and advancements in backend development and propose innovative ideas to improve the overall system architecture and performance.\n\nJOB REQUIREMENTS:\n- From 3 years of experience working as Backend Developer\n- Bachelor’s degree in computer science, Software Engineering, or a related field.\n- Experience in developing backend application using modern programming languages such as Java, Kotlin, Python, NodeJS. It’s a big plus point if you have prior experience with Go.\n- Experience with microservices architecture exposing RESTful, gPRC or messages based APIs\n- Excellent problem-solving skills and the ability to analyze and resolve complex technical issues.\n- Working proficiency in English, both verbal and writing.\n\nNice to have:\n- Experience in developing scalable batch/workflow processing applications using technologies like Temporal and Apache Airflow.\n- Understanding of the importance of secure codes, especially in the context of banking and finance.\n- Familiarity with Cloud, Docker, Kubernetes, CI/CD and other modern technologies such as Logging and Monitoring.\n- Experience with automation testing (e.g. unit test, integration test and load test) and performance optimization.\n- Experience mentoring junior/mid-level software engineers.\n\nWHY YOU SHOULD JOIN US\n- Hybrid working environment.\n- Collaborating with one of Top 4 largest banking of Australia\n- 18 paid leaves/year (12 annual leaves and 6 personal leaves)\n- Insurance plan based on full salary + 13th month salary + Performance bonus.\n- Meal allowance of 730,000 VND/month\n- 100% full salary and benefits as an official employee from the 1st day of working\n- Medical benefit for employee and family\n- Working in a fast-paced, flexible, and multinational working environment. Chance to travel onsite (in 49 countries)\n- Free snacks, refreshment, and parking\n- Internal training (Technical & Functional & English)\n- Working time: From Mondays to Fridays', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1844, 848, 2, 'AI Engineer (Computer Vision)', 'MÔ TẢ CÔNG VIỆC\n\n·         Phát triển, triển khai và tối ưu hóa các mô hình AI trong lĩnh vực Computer Vision, bao gồm: Object Detection, Instance/Semantic Segmentation, Image Classification và Image Generation.\n·         Xây dựng Automation Workflow kết hợp AI Agents hỗ trợ thu thập, gán nhãn, xử lý dữ liệu, huấn luyện mô hình đến triển khai sản phẩm.\n·         Nghiên cứu, phát triển các mô hình VLM như: InternVL, CLIP, BLIP-2 ứng dụng cho các bài toán: Image-Text Retrieval, Visual Question Answering (VQA), OCR.\n·         Làm việc với các framework Deep Learning phổ biến: PyTorch, TensorFlow, OpenCV, MMDetection, HuggingFace Transformers.\n·         Ứng dụng các kỹ thuật mới như LoRA, QLoRA, Diffusion models, Zero-shot/ Few-shot learning để tối ưu hoá chi phí và hiệu quả mô hình.\n·         Làm việc chặt chẽ với đội ngũ sản phẩm và kỹ thuật để tích hợp AI vào backend và ứng dụng thực tế.\n\n2.YÊU CẦU\n\n·         Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Khoa học Máy tính, AI hoặc các lĩnh vực liên quan.\n·         Tối thiểu 2 năm kinh nghiệm trong lĩnh vực AI/Computer Vision.\n·         Ưu tiên ứng viên có kinh nghiệm với Vision-Language Models, mô hình đa phương thức và Agents.\n·         Nắm vững các thuật toán Machine Learning và Deep Learning, đặc biệt trong mảng Computer Vision.\n·         Thành thạo một trong các ngôn ngữ lập trình: Python, C++.\n·         Kinh nghiệm thực tế với các thư viện: PyTorch, TensorFlow, OpenCV, HuggingFace, MMDetection.\n·         Hiểu biết sâu về các kiến trúc Transformer-based models như CLIP, BLIP-2, SAM, ViT.\n·         Có kinh nghiệm fine-tuning, sử dụng LoRA hoặc các kỹ thuật tối ưu trên mô hình lớn.\n·         Có khả năng xử lý dữ liệu đa phương thức: ảnh, video, văn bản.\n·         Kinh nghiệm triển khai mô hình trên GPU/TPU, tối ưu hóa inference bằng ONNX, TensorRT hoặc tương đương.\n\nLÝ DO ĐỂ ĐỒNG HÀNH VỚI ELCOM\n\nVới truyền thống 29 năm hình thành phát triển, Elcom chắc chắn sẽ là nơi làm việc khiến bạn an tâm gắn bó lâu dài, với:\n\nSự tiên phong trong công nghệ:\n·         Tham gia ứng dụng công nghệ mới vào những sản phẩm lớn, bộ giải pháp toàn diện Top đầu thị trường thuộc các lĩnh vực An ninh Quốc phòng, giao thông thông minh,...\n·         Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng với hệ thống career path (phát triển theo hướng chuyên gia hoặc hướng quản lý).\n\nMôi trường thân thiện, chia sẻ, đồng hành:\n·         Môi trường làm việc thân thiện, cởi mở, tôn trọng sự khác biệt và đề cao sáng tạo, Elcomers được tự do phát triển các ý tưởng tiến bộ, cải tiến công việc.\n·         Đào tạo và phát triển liên tục với nhiều chương trình huấn luyện chuyên nghiệp, Manager hỗ trợ sát sao, nhiệt tình.\n·         Kết nối tài năng: tập trung phát triển những con người có chung lý tưởng, mục tiêu, cùng trao giá trị và nhận thành công\n\nNền tảng vững chắc cho phát triển sự nghiệp, thăng tiến, quyền lợi:\n·         Gói đãi ngộ cạnh tranh với mức thu nhập hấp dẫn cùng chính sách review performance 2 lần/năm.\n·         Chính sách thưởng hấp dẫn trực tiếp từ lợi nhuận Công ty, thưởng nóng theo thành tích, 6 khoản thưởng cho các ngày Lễ khác trong năm.\n·         Chăm sóc sức khỏe toàn diện với gói Bảo hiểm sức khỏe Elcom care được thiết kế riêng cho CBNV.\n·         Khám sức khỏe thường niên tại bệnh viện hàng đầu cả nước.\n·         Được hưởng toàn bộ các quyền lợi theo Luật lao động ban hành về chế độ tham gia bảo hiểm xã hội, nghỉ lễ, nghỉ phép năm.\n·         Bữa trưa được phục vụ miễn phí tại văn phòng.\n·         Các hoạt động văn hóa, giải trí phong phú: Du lịch, teambuilding, ngày hội sinh nhật công ty tại các địa điểm du lịch, resort cao cấp, cháy hết mình tại các CLB theo sở thích (Zumba, bóng bàn, bóng đá, cầu lông).\n·         Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân...\n·         Thời gian làm việc: thứ 2 đến thứ 6.\n\nĐịa điểm làm việc: Elcom Building, ngõ 15 phố Duy Tân, Cầu Giấy, HN.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1845, 326, 2, 'Senior Frontend Engineer (ReactJS)', 'YOUR NEW ROLE CODE LEAP\n\nWe are looking for a Senior Frontend Engineer to join our expert team in Ho Chi Minh City. This role is perfect for team players with a strong interest in developing their international career - not just as a coder but as a product builder.\n\nYOUR EXCITING TASKS\n\n• Design, build the frontend services for our client’s product and bring it to the next level\n• Write high-quality, optimized and reusable code\n• Review the code and provide feedback on possible problems\n• Optimize the application for maximum speed and scalability\n• Analyze, debug, and fix complex bugs\n• Work with an international team based in Vietnam and Germany\n• Write comprehensive technical documents\n\nYOUR PROFILE AND YOUR PERSONALITY\n\n• At least 4 years of experience developing and designing web solutions in dynamic environments\n• Strong knowledge of JavaScript, TypeScript, ReactJS, RESTful APIs, Websocket\n• Experience with UI libraries such as Tailwind, MUI, Ant Design, Element Plus\n• Experience in SCSS, LESS, and styled components\n• Experience with state management tools like Redux, etc\n• Familiarity with OpenAPI (Swagger) and API platforms like Postman\n• Experience with remote logging Sentry\n• Experience with HTTP clients such as fetch, axios, etc\n• Experience with both client-side rendering and server-side rendering\n• Experience writing unit tests (Rendering test and logic test)\n• Hands-on experience with reading and understanding technical documents\n• You understand and know how to prioritize your tasks with a problem-solving mindset\n• You don\'t take things personally and are comfortable with ambiguity and rapid changes common in early-stage product development\n• You don\'t wait for others to tell you what you need to do but proactively reach out to people, communicate, ask for help, and get things done\n• You are proficient in communicating in the English language\n\nNice to have\n\n• Have experience working with web hosting platforms such as on-premise, AWS, Azure,.. \n• Experience with Functional programming using fp-ts, Effect-TS\n• Familiar with deployment pipeline for front-end\n\nBenefits Await You At Code Leap\n\n• Competitive salary and beneﬁts\n• Year-end bonus (13th-month salary)\n• Generous annual leave of up to 18 days\n• Enjoy a stress-free and comfortable commute to and from work with our Grab Services sponsor\n• Enjoy an endless selection of delicious refreshments, including gourmet coffee, beverages, snacks, and fresh fruits, all complimentary\n• Focused on individual development:\n  • Unlimited access to Udemy and other recommendation courses\n  • Sponsored Professional certificates such as AWS, PMI, Scrum Master, etc\n  • Sharing session every Friday, come along with lunch provided by CODE LEAP \n  • 1-on-1 coaching with experienced professionals\n• Flexible work policy, which provides flexible hours to accommodate personal schedules and commitments\n• Dynamic, fun, and agile environment, perfect for sharing and creativity\n• Open-minded, kind & humble colleagues\n\nCONTACT\n\nInterested? Let’s talk!\n\nPlease reach out and contact us now with your latest CV as well as a little description of yourself at jobs@codeleap.de.\n\nAbout Us\n\nWith our expert teams spread across two continents, CODE LEAP provides innovative software solutions for venture-backed companies and leading enterprise businesses in Germany. Our teams in Germany and Ho Chi Minh City (Vietnam) work hand in hand to develop state-of-the-art solutions of the highest quality.\n\nBecause collaborating with the right people is the secret to our successful growth.\n\nWe future-proof organizations - be part of it!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1846, 1014, 2, 'Full Stack Developer', 'Bạn là Developer đam mê công nghệ, yêu thích sáng tạo và mong muốn phát triển các sản phẩm IoT trong nông nghiệp thông minh?  👉 Đây là cơ hội dành cho bạn!\n\n📍 Địa điểm: Lô 12, BT1, X2 Bắc Linh Đàm, Hoàng Liệt, Hoàng Mai, Hà Nội\n\n🕒 Thời gian làm việc: Linh hoạt, từ Thứ 2 đến Thứ 6\n\n💼 Vị trí: Fullstack Developer (Python, ReactJS/Flutter, Embedded C)\n\n🔍 Yêu cầu chuyên môn:\n✔ Tốt nghiệp ĐH chuyên ngành Điện, Điện tử Viễn thông, CNTT, Khoa học Máy tính,...\n✔ ≥ 3 năm kinh nghiệm với Python (FastAPI, Django, Flask), ReactJS/Flutter, lập trình C trên hệ thống nhúng\n✔ Thành thạo: UI Responsive, OOP, Design Patterns\n✔ Kiến thức vững về: RESTful APIs, MQTT, Bluetooth/NFC (lợi thế)\n✔ Có kinh nghiệm với Cassandra, PostgreSQL, Linux & ARM Toolchain\n✔ Sử dụng thành thạo Git, tư duy logic tốt, hiểu cấu trúc dữ liệu & giải thuật\n✔ Ưu tiên ứng viên có hiểu biết về IoT, STM32, sơ đồ mạch, Altium/OrCAD\n\n🎁 Chế độ & Cơ hội tại MED-AID:\n💰 Lương không giới hạn theo năng lực + thưởng theo hiệu suất\n🧑‍💻 Môi trường công nghệ năng động, phát triển sản phẩm thực tế\n📈 Cơ hội làm việc với đối tác Mỹ, đi công tác nước ngoài\n🎯 Đầy đủ chế độ phúc lợi theo luật lao động\n⌛ Thời gian làm việc linh hoạt, chỉ từ Thứ 2 – Thứ 6\n\n📩 Ứng tuyển ngay qua:\n📞 Zalo/Phone: 0914.385.679 (Ms. Hằng)\n📧 Email: hang.vu@med-aid.com\n\n👉 Follow Med-Aid để cập nhật các vị trí hấp dẫn khác trong lĩnh vực nông nghiệp thông minh – IoT – hệ thống nhúng!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1847, 1015, 2, 'Fullstack Developer', 'Key Responsibilities\n● Design, develop, and maintain scalable web applications across frontend and backend.\n● Collaborate closely with the Tech Lead and team members to deliver robust and maintainable solutions.\n● Participate in code reviews, debugging, and performance optimization.\n● Ensure proper integration between frontend and backend systems.\n● Write clean, well-documented, and testable code that aligns with project requirements.\n● Communicate effectively in English within the team and with stakeholders.\n\nRequirements\n● 5–6 years of experience as a Full-stack Developer.\n● Have experiences in Golang.\n● Proficiency in frontend development with React (NextJS) or Vue (NuxtJS).\n● Solid backend development experience using Java, NodeJS, or PHP.\n● Strong understanding of web architecture, RESTful APIs, and modern development best practices.\n● Experience working in Agile environments is a plus.\n● Able to read and write documentation in English confidently.\n● Strong problem-solving skills and team collaboration mindset.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1848, 711, 2, 'Bridge Software Engineer (in Vietnam)', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business with a bold vision of our world’s potential. We’re people-centric and here to power good. Every day, we future-proof urban spaces, conserve natural resources, protect rainforests, and save lives. This is a world where innovation, technology, and deep expertise come together to take our company and customers from what’s now to what’s next. We make it happen through the power of acceleration.\n\nImagine the sheer breadth of talent it takes to bring a better tomorrow closer to today. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally as important to us.\n\nThe team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in Japan, India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n\nRequirements\n\nThe Bridge Software Engineer who will manage projects or work closely with Project Manager to monitor and control the project; and work closely with the team to understand the project’s insights. This role needs to communicate with Japanese clients for requirements, issue clarifications to make sure that there is no gap in the understanding between customer and project team including the followings:\n\n- Analyze and transfer requirements to project team.\n- Verify and develop design documents.\n- Control inbound and outbound project’s materials.\n- Develop and perform test cases to verify the deliverables.\n- Understand the clients and maintain a good business relationship with them.\n\nWhat You’ll Bring\n\n- Bachelor’s degree with a major in software development, information technology or related fields.\n- Japanese language proficiency equivalent to JLPT N2 or higher is required.\n- At least 3 years of working experience in BrSE position, hands-on experience of writing technical document in Japanese, giving presentations, and working directly with Japanese customers.\n- Have software development skills (design, coding, test, etc.), and good programming skill/knowledge of Full-stack development (Java, React, Angular, CICD..).\n- Have knowledge UI/UX Figma is an advantage.\n- Good at requirement analysis, critical thinking and problem-solving skills.\n- Well-organized, creative, and capable of performing multiple tasks simultaneously.\n- Proficiency in English is a plus.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1849, 1016, 2, 'Lead Java Developer', 'YOUR JOB RESPONSIBILITIES\n- Provide hands-on leadership to the design, development, and deployment of technical solutions; \n- Collaborate with other NAB’s technology leaders towards improving and fulfilling the NAB technical direction; \n- Evangelizing and promoting Java best practices; \n- Lead and conduct training to empower engineers on sufficient programming skills; \n- Design, develop, review, implement, and manage Java application code and services for the production and pre-release environments; \n- Participate in Agile software development, prototyping, and code review with international development teams to build scalable microservices-based products and APIs using Java technologies on AWS cloud architecture; \n- Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and toolings; \n- Provide robust coding practices, solid unit/component test coverage, and debugging code.\n\nYOUR SKILLS & EXPERIENCE\nMust have\n- Experience as a Lead Java designer/developer in a complex, enterprise-level development environment; \n- Experience with distributed, event-driven systems and using messaging protocols. Messaging middleware such as IBM MQ, Apache Kafka preferred.\n- Build and automation tools (Ant, Gradle (Kotlin DSL/Groovy), Jenkins, Python/Jython, Artifactory, Terraform, SonarQube).\n- Experience with the following also strongly preferred: Java 8+, J2EE, MDB[DLP(7] , Spring Boot, RDBMS (ideally Postgres, MySQL), Webservices (REST/SOAP), Apache Camel, Docker, SCM (Git), BDD (JBehave/Cucumber), & Unit Testing (Junit, Mockito, JMockit).\n- Established network and platform (*nix) skills, Cloud hosting (AWS preferred)\n- Experience in the entire application stack; from network, security, through platform OS to application code, including cloud hosting, but an over-riding desire to write code.\n- Well-versed in writing structured, well-documented, maintainable, and clean code; \n- Excellence in problem-solving and analytical skills; \n- Experience in leading and coaching at least one software engineering team on multiple projects; \n- Strong communication skills with the ability to deal with stakeholders (both users and product owners)\n\nNice-to-have\n- Experience in the Banking or Financial Services industry;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1850, 1017, 2, 'Sr. Software Engineer (Front-End)', 'Senior Software Engineer- Vietnam\n\nCompany Introduction\n\nOur mission is to enable every organization to be climate conscious and positive with the world’s best climate software and data products. Persefoni is creating an all-in-one platform that allows organizations to measure, analyze, and reduce their Enterprise Carbon Footprint. Our goal is to provide our customers unprecedented visibility and insights into the impact their organization has on the environment. Leveraging the latest breakthroughs in data science and software, our technology will empower teams and leaders to mobilize their organizations to continuously improve their greenhouse gas emissions metrics.\n\nAbout The Role (What You Will Get To Do)\n\nAs a Senior Software Engineer you will be an integral member of the Software Engineering Department and be partly responsible for building both our product and our web marketing development projects. Successful candidates should have a minimum of five years of recent professional programming experience at positions requiring the skills listed below with an emphasis on React and Typescript. Our project entails implementing our pre-approved development targets and developing a robust and reusable code framework to deliver a variety of new features across our product lines according to our preferred architecture design and best practices.\n\nResponsibilities (What We Expect)\n- Plays a key role in setting medium-to-long term strategy for business-impacting projects. \n- Identifies new opportunities proactively and advocates for and implements improvements to the current state of projects — potentially having broader business impact across teams or products. \n- Questions the status quo to generate and implement ideas that drive our products and tools forward. \n- Identifies and supports areas of growth for their teammates that take into account their skills, backgrounds and working styles. \n- Actively level up less-experienced members of their team by helping them with their craft, providing guidance, and setting a good example. \n- Builds relationships and drives collaboration across teams to produce positive outcomes. \n- Share information proactively so that the right people are informed and aligned. \n- Conducts critical conversations with various team peers and leaders. \n- Effectively and quickly debugs cross-module issues, and investigates where bugs might lie due to their deep knowledge of the libraries, platforms, and systems. \n- Gives quality feedback on designs developed by teammates, asking probing and insightful questions to solidify choices and surface erroneous assumptions. \n- Confirms that best practices are being followed during code review processes. \n\nQualifications (What You Bring To The Role)\n- Multiple years of experience with the end-to-end life cycle of Agile software development. Including the technical analysis of requirements, development of the software, troubleshooting, and implementing PR and QA feedback. Experience with Agile process management systems such as JIRA. Collaborating via standard agile ceremonies. \n- Familiarity with our targeted development frameworks including React, NextJS, Typescript, Atomic Design principles, and functional component-based programming. \n- Proficiency with React features such as hooks, context, HOC, state management, and data fetching. \n- Proficiency with dynamic styling in Javascript (styled-jsx and other css in JS options). \n- Proficiency with code debugging and uncovering performance issues utilizing developer tooling. \n- Proficiency in asynchronous programming patterns. \n- Proficiency with Git / BitBucket, Git-flow branch management. \n- Experience with GraphQL. \n- Experience authoring and maintaining tests written in Jest, React Testing Library and Playwright. \n- Experience implementing Storybook component stories. \n- Experience with authoring Docker containers is also a plus. \n- Experience with using Figma, or similar tools, for extracting design guidance. \n- Thorough understanding of user experience and application security practices. \n- Appreciation for clean, well documented code, and attention to detail. \n- Proactive communication across and within the team. \n- Experience building applications at scale by leveraging patterns like code splitting and dynamic imports. \n\nHow You\'ll Know You’re on the Right Track\n\n- Within your first day, you should have been able to clone the repository and install the necessary tooling to build and run our projects locally. You should have also been introduced to the engineering leadership and the development team members. \n- Within your first week, you will be familiarizing yourself with the code base and assisting in coordinating work on development tickets as requested. \n- Within your first month, you should be successfully operating with the development team, organizing work tickets to achieve product goals, submitting PRs, providing feedback on team member PRs, and advancing your assigned projects with your contributions. \n- Within your first year, you should be contributing to the software engineering team by providing your personal insights as to how to improve our processes and architectures. \n\nJob Type:\n\nFull-time position located in Vietnam governed by Vietnam labour regulations, with the Persefoni entity being established in Vietnam.\n\nInterview Process\n\n- Step 1: Initial screen with talent acquisition\n- Step 2: Technical Interview\n- Step 3: Interview with Vietnam Country Director\n- Step 4: Interview with Engineering Leadership team\n- Step 5: Offer extended\n- Step 6: Background check and onboarding\n\nPersefoni is an Equal Opportunity employer\n\nOne of our company Core Values is \'Equality\' which emphasizes our commitment to value and respect people and organizations of all backgrounds. We proudly bring this to life by fostering a culture of innovation, creativity, diversity of thought, and inclusion.\n\nWe strive for each of our team members to be able to show up for work every day as their genuine selves. Similar to the reverence given to Earth’s biodiversity, we recognize the vast potential that exists when all of the facets of diversity within our team are appreciated and illuminated. This policy extends to all aspects of our employment practices.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1851, 940, 2, '[HN] Japan AI - Full Stack Developer (Next.js)', 'Job description \n\nDesign, develop, and maintain AI-powered applications and systems from end-to-end, including the front-end user interface, back-end services, and integration with AI models/large language models (LLMs)\nWork collaboratively with backend/frontend/AI engineers and PdMs to design and develop a robust and flexible frontend/backend for a powerful AI chat service and user data integration systems.\nConstruct reporting system in Google GCP\nBuild new features, bug fixes, and suggest projects that will improve product and infrastructure.\nWrite sustainable, high-quality, high-performance code\nSuggest and implement projects that enhance product performance and user experience.\nCollaborate with cross-functional teams to define, design, and ship new features.\nEnsure the performance, quality, and responsiveness of applications.\nContinuously discover, evaluate, and implement new technologies to maximize development efficiency.\n\nJob requirements: \n\nMust have: \nBachelor’s degree or higher in Information Technology\nA minimum of 3 years of full stack experience\nConfident in JavaScript, TypeScript, including DOM manipulation, JavaScript object model\nHave experience with Next.js\nConfident in backend programming languages and frameworks (Node.js, tRPC preferred)\nExpertise in SQL databases (MySQL, PostgreSQL, MongoDB…)\nProficiency in English, with the ability to communicate effectively in a team setting\nStay on track with latest AI trends, using AI tools in development from a user’s perspective.\nSelf-motivated development style\nStrong teamwork capabilities\n\nNice-to-have: \nExperience with cloud computing platforms, such as Google Cloud Platform (GCP).\nExperience with containerization and orchestration technologies (e.g., Docker, Kubernetes)\nExperience in backend development using Python\nFamiliarity with popular Python\'s libraries\nUnderstanding of React.js and its core principles.\nExperience with React-admin\nExperience with System Design\n\nWorking time: 9:00 AM - 6:00 PM (1-hour lunch break) from Monday to Friday\n\nEmployment Package: \nSalary: Negotiable\nLaptop Mac pro provided\nSocial, public health and unemployment insurance as defined in the Labor Code\nPVI insurance for staff and 1 family member\n12 days’ annual leave and 1 birthday leave\nSalary review: twice per financial year\nHalf-year bonus: up to 100% of monthly gross salary\nMost valuable person/team awards per half-year\nAnnual company trip, annual health check\nClub allowance, chance to join club activities with cost bearing up to $20/month\n\nResume submission:\nrecruitment-gv@geniee.co.jp\n\nPlease note that only qualified candidates will be contacted', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1852, 822, 2, 'Senior Backend Engineer (Java)', 'Senior Backend Engineer (Java)\n\nUrgent\n\nHo Chi Minh\n\nTech/Engineer\n\nAbout Us\n\nAt Money Forward, we\'re on a mission to make financial management simple and accessible for everyone. Our innovative fintech solutions have transformed how millions of people and businesses handle their finances.\n\nOur Flagship Products\n\nMoney Forward ME - A smart personal finance app that automates budgeting and expense tracking\nMoney Forward Cloud - Comprehensive business management tools that streamline operations\n\nWhat makes our platform special? Our cutting-edge Account Aggregation technology securely connects with financial institutions to give users a complete, real-time view of their financial life - all in one place.\n\nThe Role And Your Impact\n\nWe\'re looking for a passionate Senior Java Backend Engineer to join our dedicated engineering team who builds the backbone of Money Forward\'s data ecosystem.\n\nYou\'ll be working on mission-critical systems that collect, process, and deliver financial data to millions of users. Every line of code you write will directly impact how our users understand and manage their finances.\n\nWhat Makes This Role Exciting\n\nWork on complex, large-scale financial data systems\nCollaborate with a diverse, international team\nSolve challenging technical problems with real-world impact\nShape the future of fintech in Southeast Asia\n\nYour Growth Journey\n\nStart as a Backend Engineer on our PAG team, then:\n\nDeepen expertise in financial systems and large-scale architecture\nLead projects and mentor new team members\nExplore opportunities across 20+ projects within Money Forward\nAdvance your career with clear engineering progression paths\n\nYour Responsibilities\n\nBuild & enhance the services and APIs where users can get aggregated data through Money Forward solutions\nCollaborate closely with product teams to deliver features users love\nOptimize performance and scalability of high-traffic financial systems\nMentor and learn from talented engineers with diverse backgrounds\nDrive improvements in development processes and system architecture\n\nOur Requirements\n\nMust-have:\n\n3+ years of Java development experience with web services\nExperience in API design experience (REST APIs, microservices architecture)\nExperience in code collaboration skills using GitHub or similar platforms\nExperience in SQL knowledge for database interactions\nProblem-solving mindset and passion for clean, maintainable code\n\nNice-to-have\n\nAWS cloud experience\nGolang development background\nKafka messaging experience\nMonitoring tools experience (Datadog, Rollbar)\n\nOur Technical Stacks\n\nBackend: Java (Jersey, Guice, jOOQ), MySQL\nInfrastructure: AWS, Docker, Nginx, Consul\nTools: GitHub, ArgoCD, Jenkins, Terraform\nMonitoring: DataDog, Rollbar, Sentry\n\nOur benefits\n\nCaring Mental & Physical Recreation\n\nHybrid working: 2 days at the office and 3 days WFH\nWorking hour: Flexible start 8AM-9AM from Mon-Fri\nFull salary in probation\nInsurance: Applied from Probation period:\nSocial Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\nPrivate health insurance & accident insurance. From Managing level: extra for family members\nBonus: 13th month salary\n16 - 24 paid days off and more\nPaternity leave: Extra 5 days\nAnnual company trip; Quarterly team building\nBilliards & Running club\nAnnual health check\nWell-equipped facility: Macbook pro, additional monitor,\n\nCaring Career & Development\n\nClear Career path\nForeign language & International technology-related certifications sponsoring\nExternal & internal training courses\nSoft-skill workshops\nTech seminars\nMonthly and biannual Recognition Awards\nPerformance & salary review: twice/year (Jun & Dec)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1853, 442, 2, 'Intermediate Backend Engineer', 'Who We Are\n\nEmployment Hero is on a mission to make employment easier and more valuable for everyone. Our Employment Operating System brings hiring, HR, payroll and benefits into an all-in-one solution.\n\nSince our inception in 2014, we\'ve scaled to a $2 billion valuation and gained a presence in 6 countries globally - Australia, New Zealand, Singapore, Malaysia, the UK and Canada. We now service over 300,000 businesses and more than 2 million employees.\n\nThe EH Way\n\nAt Employment Hero, we\'re proud of our unique DNA, which we call The EH Way.\n\nWe are Mission First - everything we do (from what we work on, to how we allocate capital and where we focus) is driven by our Mission\nWe are Remote First - we champion a remote environment with a preference for asynchronous communication and a high degree of autonomy \nWe are AI First - we are committed to using AI to accelerate our mission; AI is not just a tool, it\'s a fundamental part of how we operate, innovate, and scale\nWe are Apolitical - we do not take a position on political or social topics, unless it relates to our Mission\nWe Live by Our Values - we role model our values 100% of the time\nWe Expect High Performance - we set a high standard and we\'re not satisfied with being average\n\nThis role \n\nAs one of our Backend Engineers, you\'ll be accountable for building and deploying the innovative features that change our customers\' lives every day. From our trailblazing AI hiring tool to our fully automated payroll solution, every component of our Employment Operating System is carefully designed to disrupt the employment industry for the better, improving the lives of business owners and entrepreneurs everywhere.\n\nOur world-class Product and Engineering teams delivered almost 1,000 new features last year. As one of our Senior Engineers, you\'ll play a vital role in the continued acceleration of our product strategy.\n\nThis will include\n\nDriving your squad to develop critical features for our customers. We primarily develop our applications using Ruby. If you\'re not familiar with Ruby, no worries—we offer training to ensure you\'re equipped with the necessary skills \nCollaborating closely with our global team of designers, product managers and UX specialists to gather requirements and translate them into technical solutions \nWriting automated tests for your production codes \nDeveloping and maintaining key components of web applications \nConducting testing and code reviews for both yourself and your colleagues \nMentoring the Junior Engineers within your squad\n\nWho You Are\n\nTo thrive at Employment Hero, you\'ll need to embody The EH Way - operating with focus, agility, and an obsession with impact. For this role, you\'ll also bring\n\nOver 4 years of experience in Software Development, with a focus on Server-side and RESTful API Development and integration\nProficiency in OOP languages such as Python, Java, PHP, etc., is highly desirable, with the expectation that you are willing to learn Ruby upon joining our team\nDemonstrated experience implementing, maintaining and deploying full-stack web technologies\nStrong skills in Object-Oriented Programming (OOP)\nStrong understanding of standard Software Engineering processes, Testing, and Agile methodology\nA team player that always puts colleagues ahead of yourself and has a highly adaptable and versatile approach to work\nYou are passionate about learning and sharing your knowledge, and not afraid to challenge your peers, but also welcome being challenged\nYou have experience in mentoring team mates, or even leading an Engineering squad\nEnglish language abilities, both written and verbal - you\'ll be working with people across the world, including from Australia\n\nWhat We Can Offer\n\nAt Employment Hero, we don\'t just talk about a better way to work - we live it. Joining Employment Hero means\n\nYou will work remotely, with the flexibility to own your time and impact\nYou will access cutting-edge tools to amplify your work, knowledge and outputs \nYou\'ll surround yourself with ambitious, outcome-driven colleagues who challenge you to do the best work of your life\nYou\'ll own ESOP (employee share options) in one of the world\'s fastest-growing tech companies \nYou\'ll also have access to a wide range of benefits that includes - a very generous paternity leave policy, subsidised egg freezing (so you can make the choice that\'s right for you, on your terms), a WFH office expense budget, and outstanding learning & development opportunities \n\nAt Employment Hero, we are committed to safeguarding the privacy of your application data. To understand how we do so, you can read our Applicant Privacy Policy \nhere\n\nEmployment Hero celebrates diverse perspectives and experiences, we invite people of all backgrounds and identities to apply for this position.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1854, 880, 2, 'Freelance Software Developer (C++) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with C++\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge.\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1855, 797, 2, 'Software Engineer', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.  The Position We are looking for a Software Engineer who will focus on extending and maintaining a unique, exciting secure network access solution. The Software Engineer works across software and hardware, you will oversee the development of solutions to be used on-premises and in Cloud.  What You Will Be Doing Design, implement, and test OPSWAT MetaDefender products built on C++ and C# (.NET Core) for both Windows and Linux environments. Build and develop an automation test framework using Python to ensure product quality and reliability. Interact with data, including files, documents, images, etc., at both binary and structural levels. Enrich features for existing software modules (back-end engines) which process millions of files daily, ensuring high performance and scalability.  What We Need From You Experience C/C+, C#, Objective-c Experience using, creating, and maintaining REST APIs Experience developing on multiple platforms (e.g.: Linux, Windows, mobile) Software Design experience Experience with agile development, rapid release cycles, and implementing customer-oriented solutions. Experience with Git, BitBucket, Jira, Confluence, TeamCity (or the equivalent  It Would be Nice if You Had Reasonable understanding of OWASP Top 10, common vulnerabilities and exploitations. Pre-intermediate / intermediate English Level.  OPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws. Recruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1856, 1007, 2, 'PHP Developer', 'Job Description\n- Analyze requirements and propose technical solutions.\n- Write detailed specifications and develop high-quality applications.\n- Troubleshoot, test, and maintain the core product software and databases to ensure strong optimization and functionality.\n- Contribute to all phases of the development lifecycle.\n- Develop and deploy new features to facilitate related procedures and tools if necessary.\n- Report to the Team Leader.\n\nJob Requirement\n- At least 2 years of working experience in the same position.\n- Proven software development experience in PHP frameworks.\n- Have experience in front-end including HTML, CSS, JavaScript, AJAX, etc.\n- Have experience with Symfony, Drupal, and Yii framework.\n- Good knowledge of MySQL data stored procedures, version control tools, and database optimization experience.\n- Mastering Source Control (SVN/Git).\n- Good English reading and writing skills.\n- Careful, highly organized, and self-learning attitude.\n\n** If your work experience and skill set match this role, we\'ll contact you to schedule the interview in the next 7 working days.\n\nOur Benefits and Perks\n- Attractive salary commensurate with your expected salary and working experience.\n- Full pay during the probation period.\n- The total contribution to social insurance is based on the Net salary.\n- 13th-month salary.\n- 14 days of annual leave.\n- Company bonus.\n- Annual health check-ups.\n- Monthly parties.\n- Quarterly team outing budget.\n- Yearly company trip.\n- Employee gifts for special occasions, such as celebrations and birthdays.\n- Premium healthcare (PTI).\n\nWorking time:\n- From Monday to Friday\n- Ho Chi Minh office (08:30 AM – 05:30 PM)\n- Can Tho office: (08:00 AM – 05:00 PM)\n\nCompany Address\n- Ho Chi Minh Office:\nUnit B1-B3-B4, 16th Floor, International Plaza Building\nNo. 343, Pham Ngu Lao Street, Pham Ngu Lao Ward, District 1, Ho Chi Minh City\n\n- Can Tho Office:\n1st Floor, STS Tower, No. 11B, Hoa Binh Avenue, Tan An Ward, Ninh Kieu District, Can Tho City', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1857, 816, 2, 'Senior PHP Developers (Laravel/ MySQL)', 'Mô tả công việc\n\n・Phát triển hệ thống ứng dụng theo xu hướng công nghệ 4.0 (AI , Bigdata , Block Chain , Machine learning)\n\n・Phát triển hệ thống thương mại điện tử .\n\nKhông yêu cầu', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1858, 714, 2, 'Odoo Developer', 'Responsibilities\n\n- Develop and customize Odoo modules to meet the specific needs of our business.\n- Work with cross-functional teams to gather requirements and translate them into technical specifications.\n- Integrate Odoo with third-party applications and APIs.\n- Maintain and improve existing Odoo applications.\n- Troubleshoot and resolve issues related to Odoo applications.\n- Participate in the full software development lifecycle, including planning, development, testing, and deployment.\n- Write clean, maintainable, and efficient code.\n- Provide technical support and training to end-users.\n- Use charts and mockups to analyze requirements.\n\nRequirements\n\n- Strong knowledge of Python programming.\n- Understanding of business processes such as Sales, Purchase, Inventory, Accounting, and HR.\n- Excellent communication and teamwork skills.\n\nNice To Have\n\n- Architecture and design.\n- Cloud (Azure, AWS).\n- React.\n\nBenefits\n\n- Social and unemployment insurance coverage as per Vietnamese Labor Law; Bao Viet Insurance.\n- Annual leave entitlement in accordance with Vietnamese Labor Law.\n- 13th-month salary and annual salary review.\n- Bonuses for public holidays.\n- Monthly team-party activities.\n- Skill development through e-learning, workshops, and more.\n- Office perks including fruit, tea, and coffee, birthday gifts, and access to books.\n- Access to a PlayStation 5 gaming console in the office.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1859, 1018, 2, 'Quality Control Engineer', 'You Will\n\n- Live on the cutting edge of our development cycle, testing and improving mobile app features and interactions between mobile apps and management systems\n- Build a scalable mobile test automation framework together with the development team at the beginning of the project\n- Run through regression tests with multiple screen resolution and landscape as well as refine test plans to help capture and report bugs before they reach the customer\n- Document issues using bug tracking software (Familiar with Asana/Jira is a plus)\n- Assist in system test execution manually running smoke tests\n- Write and debug automated test scripts\n- Develop test plans and test cases for mobile products\n- Familiar with automated API tests to test product is a huge advantage\n- Be flexible and able to adapt strategy to changing business requirements\n- Contribute to peer review of product designs, documentation and support strategies, with the goal of improving reliability and supportability', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1860, 715, 2, 'Kỹ sư Phần mềm ứng dụng', 'Nơi làm việc: Hà Nội\n\nMÔ TẢ CÔNG VIỆC:\n- Thiết kế và phát triển phần mềm điều khiển bay và điều khiển payload.\n- Xây dựng hệ thống quản lý và bảo dưỡng thiết bị trong tổ hợp UAV.\n- Xây dựng các tài liệu thiết kế mức cao, tài liệu thiết kế chi tiết và test case cho phần mềm.\n- Nghiên cứu và phát triển các phần mềm thu nhận và phân tích, xử lý dữ liệu giữa các thiết bị trên máy bay và trạm điều khiển mặt đất.\n\nYÊU CẦU:\n- Tốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: ĐTVT, Tự động hóa, CNTT, Kỹ thuật hàng không,...hoặc các chuyên ngành kỹ thuật khác liên quan.\n- Trình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\n- Có hiểu biết và kinh nghiệm trong các lĩnh vực: thiết kế và phát triển phần mềm điều khiển bay và điều khiển camera cho các thiết bị trên mặt đất và trên máy bay.\n- Có tối thiểu 1 năm kinh nghiệm trong lĩnh vực phát triển phần mềm.\n- Có kinh nghiệm trong việc thiết kế và phát triển phần mềm theo quy trình phát triển sản phẩm.\n- Có kinh nghiệm thiết kế và chế tạo phần mềm điều khiển mặt đất cho các thiết bị bay là một lợi thế.\n- Thành thạo các ngôn ngữ lập trình C/C++, C#, mSQL.\n- Có đam mê nghiên cứu và muốn làm việc trong môi trường chuyên nghiệp.\n- Tư duy sáng tạo, chủ động trong công việc, có kỹ năng làm việc nhóm, lập kế hoạch.\n\nQUYỀN LỢI\n- Được hưởng các khoản quà, thưởng lễ tết, nghỉ mát hỗ trợ ăn trưa, điện thoại liên lạc tối thiểu 2.000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\n- Được hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\n- Được hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\n- Được trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\n- Có cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\n- Được cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\n- Có cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1861, 700, 2, 'Lập trình viên PHP (Magento)', 'Mô tả công việc\n\n- Tham gia lập trình và phát triển các dự án xây dựng Website sử dụng ngôn ngữ lập trình PHP với các framework như: Magento, Wordpress, Yii, Laravel...\n- Xây dựng các tính năng hỗ trợ cho website thương mại điện tử\n- Tham gia định hướng chiến lược phát triển sản phẩm\n\nĐại học', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1862, 986, 2, 'Backend Software Engineer II', 'Join Axon and be a Force for Good. At Axon, we’re on a mission to Protect Life. We’re explorers, pursuing society’s most critical safety and justice issues with our ecosystem of devices and cloud software. Like our products, we work better together. We connect with candor and care, seeking out diverse perspectives from our customers, communities and each other.\n\nLife at Axon is fast-paced, challenging and meaningful. Here, you’ll take ownership and drive real change. Constantly grow as you work hard for a mission that matters at a company where you matter.\n\nYour Impact\nAs one of the software engineers on the team, you will make key design decisions that will shape this product. You’ll create and maintain the data integration, management, and analytics platform alongside Axon’s newest public safety technology products. This platform will offer law enforcement administrators and crime analysts flexible access to key crime data, decision support, state and federal crime reports, and criminal investigation insights.\n\nAxon has led the global effort to protect life and through electric weapons, body cameras, a number of real-time sensors, public safety software products and AI tools. Axon is uniquely positioned to tie together every aspect of an incident in order to help law enforcement agencies better prepare for what might happen, respond efficiently and effectively, deliver justice, ensure the well being of their officers, and increase the safety of their communities. Working together with our customers and product teams, you will build the foundation for Axon’s outcome-oriented data efforts.\n\nWhat You’ll Do\nLocation: Hybrid, HCMC office\nDirect Reports\n- Participating in code reviews and architecture design meetings.\n- Owning and driving end-to-end features with Product and Design.\n- Ensuring that your code hits a high bar for quality and performance.\n- Partner with internal teams and agencies to make public safety data accessible and actionable.\n- Influence peers, advise senior leaders, coach and mentor junior team members.\n- Facilitate cross-team collaboration among engineers and contribute to the broader community of Axon engineers.\n\nWhat You Bring\n- Bachelor\'s Degree in Computer Science, Engineering, or related field.\n- Highly technical with 5+ years of experience developing and maintaining end-to-end, high availability, high throughput web-scale data systems.\n- Backend experience in managed languages such as Java, Scala, Go, C#, Python or similar.\n- Demonstrated ability to make tough technical decisions based on requirements, constraints, and trade-offs.\n- You follow the latest in software engineering and open source technologies, and can intuit the fine line between promising new practice and overhyped fad.\n- Industry experience working with SQL or NoSQL data stores.\n- Good Linux/Unix/Mac experience.\n- You love delighting end users and hunger for novel challenges.\n\nBenefits that Benefit You\n- Medical and Dental Insurance\n- Vision Insurance\n- Robust Paid Time Off policy\n- Bonuses\n- Lunch allowance\n- Cell phone stipend\n- Free LinkedIn Learning account\n- Access to 24/7 online emotional and mental support\n- Gym membership\n- Free parking\n- Stocked fridges and pantries - free coffee, cold beverages, snacks\n- Annual Company Outing Trip\n- Monthly team social activities\n\nDon’t meet every single requirement? That\'s ok. At Axon, we Aim Far. We think big with a long-term view because we want to reinvent the world to be a safer, better place. We are also committed to building diverse teams that reflect the communities we serve.\n\nStudies have shown that women and people of color are less likely to apply to jobs unless they check every box in the job description. If you’re excited about this role and our mission to Protect Life but your experience doesn’t align perfectly with every qualification listed here, we encourage you to apply anyways. You may be just the right candidate for this or other roles.\n\nImportant Notes\nThe above job description is not intended as, nor should it be construed as, exhaustive of all duties, responsibilities, skills, efforts, or working conditions associated with this job. The job description may change or be supplemented at any time in accordance with business needs and conditions.\nSome roles may also require legal eligibility to work in a firearms environment.\nAxon’s mission is to Protect Life and is committed to the well-being and safety of its employees as well as Axon’s impact on the environment. All Axon employees must be aware of and committed to the appropriate environmental, health, and safety regulations, policies, and procedures. Axon employees are empowered to report safety concerns as they arise and activities potentially impacting the environment.\nWe are an equal opportunity employer that promotes justice, advances equity, values diversity and fosters inclusion. We’re committed to hiring the best talent — regardless of race, creed, color, ancestry, religion, sex (including pregnancy), national origin, sexual orientation, age, citizenship status, marital status, disability, gender identity, genetic information, veteran status, or any other characteristic protected by applicable laws, regulations and ordinances — and empowering all of our employees so they can do their best work. If you have a disability or special need that requires assistance or accommodation during the application or the recruiting process, please email recruitingops@axon.com. Please note that this email address is for accommodation purposes only. Axon will not respond to inquiries for other purposes.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1863, 740, 2, 'DevOps Engineer (Cloud)', 'Job Description\n\n- Can perform the job independently\n- Participate in 24/7 on-call rotation for after-hour issues\n- Handle tasks independently\n- Make standard changes\n- Review/approve standard changes\n- Document Process\n\nRequirements\n\nTech Skills:\n\n- Terraform (Read / Write)\n- Terragrunt (Read / Write)\n- Helm (Read / Write)\n- Service Mesh – (Implement / Manage)\n- AWS Landing Zones (Implement / Manage)\n- AWS EKS – (Deploy / Operate)\n- API Gateway – (Implement / Manage)\n- Amazon MQ (RabbitMQ) – (Implement / Manage )\n- RDS / DMS – (Deploy / Manage)\n- AWS Organisations / SCPs / Backup & Tagging Policies (Implement / Manage)\n- AWS Account Factory, Account Factory for Terraform (Implement /Manage)\n- AWS Networking ( Implement / Manage)\n- AWS IAM Identity Center (Implement / Manage)\n\nCertifications\n\n- AWS Certified Solution Architect Professional (Required)\n- AWS Certified Advanced Networking Speciality (Required)\n- AWS Certified Security Speciality (Required)\n- CKA – Certified Kubernetes Administrator (Required)\n- HashiCorp Certified: Terraform Associate (Preferred)\n\nJob Benefits\n\n- Training and career development opportunities.\n- Package: 13, 14 salary months + Project bonus + Extra package: 16 Mil /employee/year (Bonus at: Tet, New Year, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, …)\n- Opportunity to approach newest technology trends; development of your career within an international Company\n- Building large-scale & global software products for our clients.\n- Onsite opportunities: short-term and long-term assignments in US, Europe, Asia.\n- Paid annual leave: 12 days (12 vacation days)\n- Salary reviews 2 times/year or on excellent performance\n- Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (AON care premium, Company trip, Holiday, Sum-up, etc)\n- Working time: 8h/day (from Monday to Friday)\n- Working place: Tan Bình District, HCMC\n\n4+ years\n\n- Please send your application via email: recruitment@cmcglobal.vn\n- Years of Experience Required\n- Required Education Level\n\nBachelor’s Degree\n\n- Job Level:\n\nSenior\n\n- Work Form:\n\nFull-time\n\n- Email: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1864, 674, 2, 'Full-Stack Software Engineer', 'Mô tả công việc\n\nPhát triển và triển khai các ứng dụng Web phục vụ các sản phẩm dữ liệu lớn (Big Data) của ngân hàng.\n\nXây dựng API và tích hợp hệ thống phục vụ dữ liệu và mô hình với hiệu năng cao.\n\nPhối hợp với các đơn vị nghiệp vụ (Business Units), nhà phân tích nghiệp vụ (BA), kỹ sư dữ liệu (Data Engineer) và nhà khoa học dữ liệu (Data Scientist) để xác định yêu cầu, thiết kế, triển khai và kiểm thử sản phẩm.\n\nYêu cầu công việc\n\nTốt nghiệp Đại học trở lên chuyên ngành Công nghệ thông tin, Khoa học máy tính, Kỹ thuật phần mềm hoặc các ngành liên quan.\n\nCó kinh nghiệm từ 02 năm trở lên ở vị trí tương đương.\n\nThành thạo các ngôn ngữ và framework:\n\nBackend (BE): Java (Spring Boot), Python (Fast API, Flask)\n\nFrontend (FE): HTML, CSS, JavaScript – Angular\n\nDatabase (DB): Oracle, PostgreSQL, MongoDB, Redis\n\nCó kinh nghiệm sử dụng công nghệ và công cụ sau:\n\nKafka, RabbitMQ, Kubernetes (K8s), WebSocket, gRPC; ELK Stack (Elasticsearch, Logstash, Kibana); OAuth2, OIDC, SSO Authentication mechanisms.\n\nCó kinh nghiệm thiết kế sản phẩm trên Figma, hiểu biết về UI/UX và state management trong Single Page Applications (SPA).\n\nƯu tiên ứng viên có kinh nghiệm về network, thiết kế hệ thống phần mềm hoặc kiến trúc giải pháp.\n\nTại sao bạn yêu thích làm việc tại đây:\n\n- Thu nhập : Thoã Thuận\n- Bảo hiểm\n- Du Lịch\n- Phụ cấp\n- Du lịch nước ngoài\n- Phụ cấp thâm niên\n- Công tác phí\n- Tăng lương\n- Chăm sóc sức khỏe\n- Thưởng\n- Chế độ nghỉ phép\n- Chế độ tập thể dục', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1865, 732, 2, 'C++ Engineer (Core Development)', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nJob Responsibilities Include, But Not Limited To The Followings\n- Transforming a wide range of structured and unstructured data into standardized outputs for quantitative analysis and financial engineering.\n- Overseeing the integration of new technologies and initiatives into data standards and structures.\n- Enhancing data quality & integrity by developing validation tools to measure the effectiveness of data enrichment.\n- Assessing system performance and making recommendations for software, and data storage improvements.\n- Developing the utility tools that can further automate the software development, testing and deployment workflow.\n\nWhat You’ll Bring\n- Strong academic background – minimum of a bachelor’s degree in a technical or quantitative field.\n- Demonstrated ability to implement data engineering pipelines and real-time applications in C++ (python is a plus).\n- Proficiency with C++ based tools like STL, object oriented programming in C++ is a must.\n- Experience with Linux/Unix shell and Git is a must.\n- Proficiency with python based tools like Jupyter notebook, coding standards like pep8 is a plus.\n- Good knowledge of data structures and algorithms is mandatory.\n- Experience in Data Engineer or similar roles is a big plus.\n- Good command of English. Proactive demeanor and strong communication skills within a global team environment is a plus.\n- Excellent software development skills: ability to convert rough overall use-cases to a working codebase.\n- Motivated by a deep curiosity and passion to learn is a plus.\n\nWhat We Offer\n- Competitive and attractive compensation package with clear career road-map – where you feel challenged everyday.\n- We offer a strong culture of learning and development: training courses, library, speakers, share and learn events.\n- Learn from who sits next to you! Working in WQ you are surrounded by smart and talented people.\n- Employee resources groups with strong diversity and inclusion culture.\n- Premium Health Insurance and Employee Assistance Program.\n- Generous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family.\n- Team building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\n- Annual company trip and occasional global conferences – opportunity to travel and connect with our global teams.\n- Happy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1866, 1019, 2, 'Nhân viên QA', 'Mô tả công việc\n\n- Trực tiếp giám sát các hoạt động của bếp để đánh giá tình hình theo từng công đoạn: Tiếp nhận, sơ chế, chế biến, chia thực phẩm, vận chuyển, vệ sinh...\n- Trực tiếp giám sát các hoạt động của bếp theo tiêu chuẩn VSATTP và qui trình phòng ngừa.\n- Kiểm tra chất lượng thực phẩm đầu vào qua bộ test (khi được yêu cầu)\n- Kiểm tra và lập biên bản các hạng mục lỗi, có xác nhận của Quản lý/Bếp chính và nhà cung cấp để làm căn cứ phạt theo quy định.\n- Đưa ra các lỗi hàng ngày cho Quản lý và Bếp chính để có phương án và thời gian khắc phục.\n- Gửi báo cáo tình hình hàng ngày và hàng tuần (vào chiều thứ 6 từ email của công ty) kèm với biện pháp khắc phục đã thực hiện. Những vấn đề còn tồn đọng, phương hướng và thời gian giải quyết.\n- Trao đổi với Quản lý bếp các hạng mục yêu cầu từ Khách hàng và từ Ban Giám sát/Ban Giám đốc quan tâm\n- Huấn luyện, đào tạo nhân viên bếp về VSATTP\n- Lập danh mục tài liệu liên quan đến mảng VSATTP của Công ty, thường xuyên cập nhật các quy định mới của pháp luật liên quan đến hoạt động của Công ty, quản lý các tài liệu này.\n- Lập quy trình, quy định, biểu mẫu liên quan đến hoạt động của bếp.\n- Quản lý các dụng cụ, mẫu test thử\n- Kiểm soát hạn sử dụng của sẩn phẩm, tem nhãn, bao bì, quy cách đóng gói của các sản phẩm...\n- Nắm rõ bộ hồ sơ nhà cung cấp. Phối hợp với Phòng mua theo dõi bộ hồ sơ của nhà cung cấp theo đúng yêu cầu và còn hiệu lực. Yêu cầu nhà cung c ấp nộp các giấy tờ liên quan khi sắp hết hạn.\n- Theo dõi thời gian hiệu lực của Bảo hiểm suất ăn, đề xuất mua mới khi đến hạn.\n- Các công tác liên quan đến vệ sinh môi trường tại cơ sở: Diệt côn trùng, tiếp đoàn kiểm tra, thanh tra, thẩm định ....\n- Tiếp đón các đoàn kiểm tra VSATTP: Đầu mối chuẩn bị hồ sơ, giấy tờ khi có đoàn kiểm tra, giám sát Bếp tuân thủ quy định của Công ty để đón đoàn.\n- Thực hiện những công việc khác theo yêu cầu của Trưởng phòng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1867, 778, 2, 'Python Developer', 'Job: Backend Lead (Python, React.JS/Next.JS)\nLocation: HCMC\n\nKey Responsibilities:\n- Lead the technical direction of projects by selecting appropriate technology stacks, defining software architecture, and establishing technical standards.\n- Collaborate closely with the Solution Architect to ensure alignment with overall system architecture.\n- Oversee the quality of code produced by the engineering team, conduct thorough code reviews, and enforce best practices to maintain high standards in software development.\n- Provide mentorship to team members, fostering the development of their technical skills. Offer guidance on complex technical issues and support the growth of the engineering team.\n- Serve as the go-to expert for resolving complex technical problems, including troubleshooting and debugging challenging issues.\n- Work closely with product managers, designers, and other teams to ensure technical solutions align with business objectives.\n- Communicate technical concepts to non-technical stakeholders, bridging the gap between engineering and other departments.\n\nQualifications:\n- Deep understanding of software architecture, design patterns, and scalable systems.\n- Demonstrated ability to lead and mentor engineering teams.\n- Track record in guiding technical direction and fostering collaboration.\n- Strong analytical skills for diagnosing complex issues.\n- Excellent interpersonal and communication abilities.\n- Strong expertise in Python, TypeScript, and JavaScript (Node.JS).\n- Experience with modern frontend frameworks (React.JS, Next.JS) and backend development patterns.\n- Experience with Playwright, ViTest, and Storybook.\n- Familiarity with CI/CD pipelines and containerization tools.\n- Proficient in English\n\nBENEFITS\n- 18 paid leaves per year (including 12 annual leaves + 6 personal leaves).\n- Insurance plan based on full salary + 13th salary + Performance Bonus.\n- 100% full salary in probation period.\n- Medical Benefit (Personal) and Family based on levels.\n- Working in a fast paced, flexible, and multinational working environment. Chance to travel onsite (in 49 countries).\n- Internal Training (Technical & Functional). Scope of English Training.\n- Working from Mondays to Fridays.\n\n*** Note: We highly appreciate your interest in this position of HCL Vietnam. After reviewing all applications, only qualified candidates will be contacted for the next steps within 15 days from date of submission.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1868, 1020, 2, 'AngularJS Developer', 'In addition to having a good knowledge of best practice software development, you will be required to:\n\n- Code and debug applications in various software languages;\n- Maintain and update Code Libraries;\n- Ensure all code and documentation complies to company and industry standards;\n- Support, maintain and document software functionality;\n- Implement performance tuning, improvement, balancing, usability, and automation of company systems.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1869, 916, 2, 'Shd | Senior Fullstack Engineer (Java/ ReactJS) - HCM VN', 'Our client is a video streaming platform owned by the Saudi government, operating across the Middle East, North Africa, and various global locations. Launched in London in 1991, it relocated its headquarters to Dubai in 2002.\n\nQualifications\n\nStrong experience in backend development with over 5 years of expertise in Java.\nSolid experience in JavaScript, with expertise in ReactJS, Redux and related libraries.\nSolid skills in software architecture and design.\nExcellent technical documentation abilities.\nStrong English communication skills (both verbal and written), particularly in global software development environments.\nExperience working in offshore software consulting environments.\nPrevious exposure to video streaming platforms is a significant advantage, though not mandatory.\n\nResponsibilities\nAs a Senior Fullstack Engineer, you will be responsible for:\n\nRefactoring and standardization of existing systems.\nDocumentation and alignment with governance and security standards.\nAuto-updating libraries and integrations with GCP.\nWriting clean, well-tested code that adheres to platform architecture and best practices.\nProvide continuous support and guidance to less senior colleagues through regular coaching activities and support them in fulfilling their personal development plans.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1870, 1021, 2, 'Back End Engineer (Vietnam-based)', 'Pollen Tech Pte Ltd is seeking a Mid-level Backend Developer to join our team. The successful candidate will work with a cutting-edge B2B marketplace for buying and selling excess inventory sustainably, and contribute to the company\'s goal of achieving a zero-waste world. Pollen Tech automates bulk transactions for overstock and near-expiry inventory, provides sustainability analytics, and offers pricing intelligence to help customers liquidate potential business waste. In 2024, Pollen Tech helped customers to ship over 400,000 KG of excess inventory to more than 20 countries. As a Back-end Developer, you will be an integral part of the team responsible for maintaining and developing Pollen Tech\'s platform.\n\nLocation: HCM City, Vietnam\nArrangement: Remote Working\nOptional Hiring Locations: Singapore, Kuala Lumpur (MY), Jakarta (ID), Bangalore (IN)\nType: Full-time (with Probation period)\nWorking Schedule: Monday - Friday, 9 AM to 6 PM (GMT +8)\n\nPollen Career: careers.pollen.tech/34721\n\nResponsibilities:\n- Collaborate with cross-functional teams to troubleshoot and resolve technical challenges\n- Design, develop, and maintain backend services, including RESTful APIs and microservices\n- Write clean, maintainable, and well-documented code following industry best practices\n- Develop and maintain automated tests to ensure code quality and support regression testing\n- Optimize server-side logic and distributed systems for performance, reliability, and scalability\n- Participate in peer code reviews and propose improvements to enhance codebase quality\n- Monitor, profile, and resolve performance bottlenecks in production environments\n- Contribute to continuous improvement of engineering processes and tools\n\nBackground:\n- Bachelor’s degree in Computer Science, Software Engineering, or a related field\n\nQualification:\n- 3–5 years of professional experience in backend development\n- Background in VC-backed startups, ideally in e-commerce industries with high adaptability skills in a fast-paced environment\n- Strong proficiency in Node.js (4+ years) is a must and experience with Python; familiarity with Java or Ruby is a plus\n- Hands-on experience with FastAPI, Docker, PostgreSQL, Redis, and Celery\n- Solid understanding of RESTful API design and microservices architecture\n- Experience with SQL and NoSQL database design, optimization, and management\n- Strong foundation in system design, computer science fundamentals, and web architecture\n- Experience with AWS and other cloud platforms; understanding of core cloud-native technologies\n- Proficient in containerization technologies like Docker and Kubernetes\n- Familiarity with source control (Git) and setting up/maintaining CI/CD pipelines\n- Exposure to frontend technologies (e.g., JavaScript) for cross-functional collaboration\n- Proven experience building secure, high-performance web applications\n- Fluent English communication (written and verbal)\n\nPersonal Qualities:\n- Strong problem-solving skills with high attention to detail, and a growth mindset\n- Strong team collaboration skills - team player with clear communication and collaboration skills\n- Ability to work independently and take initiative in a fast-paced environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1871, 1022, 2, 'Kỹ sư Kiểm thử phần mềm', '- Khối CNTT - Tổng công ty (TCT) Viễn Thông Viettel (Viettel Telecom) đang tìm kiếm các ứng viên cho vị trí kỹ sư kiểm thử với vai trò đảm bảo chất lượng phần mềm thông qua kiểm thử thủ công và kiểm thử tự động. Trách nhiệm của vị trí này là tìm ra và thông báo các lỗi cho nhóm phát triển đảm bảo sản phẩm triển khai hoạt động chính xác và đáp ứng được yêu cầu của khách hàng.\n- Bạn sẽ được làm việc trong một trong những môi trường phát triển phần mềm chuyên nghiệp nhất tại Việt Nam. Quy trình sản xuất chuẩn quốc tế, sử dụng các công nghệ, công cụ quản lý và kiểm thử tự động mới nhất. \n- Với quy mô sản xuất hơn 60 hệ thống product ở khắp các Business Domain, quy mô dự án lên tới 100 người. Đây chính là môi trường đào tạo hoàn hảo nhất cho các bạn muốn nâng cao kinh nghiệm, phát triển trong lĩnh vực đảm bảo chất lượng hệ thống.\n- Được hỗ trợ đào tạo liên tục các mảng chuyên môn, nghiệp vụ cho các vị trí: kiểm thử thủ công, kiểm thử tự động\n- Được hỗ trợ thi chứng chỉ quốc tế (ISTQB, Oracle, Agile…).\n- Có cơ hội phát triển lên các vị trí trưởng nhóm kiểm thử, kỹ sư nghiệp vụ hệ thống, kỹ sư giải pháp hệ thống.\nMô tả công việc:\n• Xem xét và phân tích tài liệu đặc tả hệ thống\n• Thiết kế và viết testcase (kiểm thử thủ công), script (kiểm thử tự động)\n• Thực hiện kiểm thử chức năng (thủ công và tự động), ghi lại và thông báo các lỗi tìm được, phân tích kết quả\n• Thực hiện kiểm thử phi chức năng: kiểm thử bảo mật, kiểm thử hiệu năng…\n• Thực hiện nghiệm thu khách hàng và đào tạo người dùng\n• Viết báo cáo test\n• Viết hướng dẫn sử dụng\n• Thông báo với trưởng nhóm kiểm thử, quản trị dự án về trạng thái của hệ thống, các vấn đề trong tiến trình kiểm thử\nYêu cầu:\nChúng tôi yêu cầu các kỹ năng:\n• Tốt nghiệp các trường đại học chuyên ngành CNTT, ĐTVT loại Khá trở lên, Toeic 550 trở lên hoặc tương đương\n• Ưu tiên các ứng viên có chứng chỉ quốc tế về kiểm thử. VD: ISTQB Advanced, ISTQB Foundation…\n• Có kinh nghiệm ở vị trí kiểm thử ít nhất 1 năm\n• Có kiến thức tốt về các loại hình kiểm thử (chức năng và phi chức năng), các kỹ thuật kiểm thử (các kỹ thuật kiểm thử hộp đen, hộp trắng…), các level của kiểm thử (kiểm thử đơn vị, kiểm thử tích hợp, kiểm thử hệ thống, kiểm thử chắp nhận).\n• Có kiến thức tốt về quy trình phát triển phần mềm, quy trình kiểm thử và công việc trách nhiệm của kiểm thử trong dự án.\n• Có kiến thức về ngôn ngữ truy vấn cơ sở dữ liệu: SQL, My SQL… Khả năng sử dụng ở mức khá.\n• Có khả năng tư duy nhậy bén, nắm bắt và phân tích vấn đề từ nhiều góc độ khác nhau. Có khả năng tư vấn lại các vấn đề liên quan đến sản phẩm cho đội dự án.\n• Khả năng giao tiếp và trình bầy vấn đề tốt, phối hợp nhóm tốt\n• Cẩn thận, tỉ mỉ\n• Khả năng chịu áp lực cao\nỨng viên có các kỹ năng sau sẽ là lợi thế:\n• Ưu tiên ứng viên có kinh nghiệm về kiểm thử hiệu năng và sử dụng thành thạo 1 trong các công cụ kiểm thử hiệu năng như Jmeter, LoadRunner…\n• Ưu tiên ứng viên có kinh nghiệm về kiểm thử tự động và sử dụng thành thạo 1 trong các công cụ kiểm thử tự động như Selenium, Appium…', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1872, 1023, 2, 'Backend Developer Supervisor', 'Thu nhập: 28,000,000 — 40,000,000 VNĐ\n\nĐịa điểm: Hà Nội, Số 54, Lê Thanh Nghị, phường Bách Khoa, quận Hai Bà Trưng, Hà Nội\n\nPhòng ban: IT\n\nHạn nộp hồ sơ: 28/02 — 30/06/2025\n\nỨng tuyển vị trí này\n\nChia sẻ: Facebook Google', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1873, 776, 2, 'Middle QC Engineer (Manual Tester, Global Project)', 'LOGIX TECHNOLOGY is a distinguished software services company, specializing in the provision of professional software development services, fostering strong partnerships through the establishment of offshore development centers, offshore product development, and software testing with an infrastructure-oriented approach. We excel at simplifying and enhancing offshore outsourcing, not only by delivering innovative solutions to meet our clients’ exact requirements through high-performance teams but also by significantly contributing to our clients’ success by reducing time-to-market and improving quality.\n\nAt LOGIX TECHNOLOGY, we are committed to delivering the highest level of professional excellence and making a significant impact in the software development sector. If you are a dedicated professional looking to join a dynamic team working with global leaders, we encourage you to explore the exciting opportunities that await you with us.\n\nJob Description\n\n- Be responsible for ensuring the quality of mission-critical, cloud-based software systems.\n- Work directly with software engineers and product managers, through all phases of the software development process to provide feedback on the functionality, reliability, usability, and efficiency of the software.\n- Evaluate current processes and implement improvements that will result in increased quality.\n- Can quickly learn our products inside and out, understand user flows; and partner’s product for edge cases.\n- Can collaborate well. Communication is key in this position. You will be working closely with other departments on a regular basis to ensure we continuously improve our ability to ship high-caliber solutions to our customers.\n- Generate and execute test cases and test plans.\n- Perform exploratory testing.\n- Troubleshoot issues to find root causes and suggest potential fixes.\n- Learn the designated client’s application and become familiar with health and human services to better understand the workflows and represent users in the development process.\n\nRequired Skills & Experience\n\n- 3+ years of experience in software testing, QA, or a similar role.\n- Proficient in SQL; able to write queries to validate backend data and support testing.\n- Strong logical reasoning and analytical thinking.\n- Proven ability to learn new systems and business domains quickly.\n- Good written and verbal English communication skills (clear documentation and discussion are essential).\n- Experience working in Agile teams, collaborating respectfully and effectively.\n- Strong sense of ownership and attention to detail.\n\nPreferred Qualifications\n\n- Background in IT, Computer Science, or related technical field.\n- Basic knowledge of JavaScript, HTML/CSS, or regular expressions is a plus.\n- Experience in healthcare, case management, or government-related software domains is an advantage.\n\nBenefits & Perks\n\n- Attractive Salary & Benefits, full salary in probation.\n- Performance appraisal twice a year, 13th-month salary.\n- Healthcare and incident insurance.\n- 16 Paid Leave days/ year (12 Annual Leave, 02 Summer Leave, 01 Birthday Leave & 01 Christmas Leave).\n- Diverse careers opportunities with Software Services, Software Product Development.\n- Working and growing in a value driven, international working environment and standard Agile culture with passionate and talented teams.\n- Various training on hot-trend technologies, best practices, and soft skills.\n- Company trip, big annual year-end party every year, team building, etc.\n- Free in-house entertainment facilities: football, table football, PS, badminton, trekking…coffee, and snacks (instant noodles, cookies, candies…).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1874, 1024, 2, 'Java Software Engineer (Middle)', 'Rabiloo is a provider of IT consulting and software development services such as website, mobile app, mobile game development; business performance support system and management system solution. We have been collaborating with companies from many countries around the world such as the US, Japan, France, Singapore,...\n\nWe are looking for: Java Developer (Fullstack).\n\nI. JOB DESCRIPTION\n- Participate in full software development process;\n- Maintain, modify products after releasing;\n- Research new technologies to develop products to meet the company\'s business strategy;\n- Fulfill other tasks assigned by managers.\n\nII. REQUIREMENTS\n- At least three-year experience of software development;\n- Good English communication (must-have), having English certifications is an advantage;\n- Firm grasp of computer science (OOP programming, Data Structures & Algorithm);\n- Proficiency in Java Spring boot/Hibernate;\n- Knowledge of distributed systems and asynchronous architectures;\n- Experience with one of the frontend frameworks (React, Vue.js, or Angular) is an advantage, or a strong willingness to learn.\n- Keen problem-solving and trouble-shooting abilities.\n\nIII. BENEFITS\nMonthly income: Up to 35,000,000 VND.\n\nProfessional and innovative work environment:\n- Energetic colleagues who value knowledge-sharing;\n- Strong learning culture with a desire for knowledge accumulation.\n\nPersonal development support:\n- Mentorship in career development;\n- Sponsored training programs.\n\nEmployee-Centric benefits:\n- Year-end bonus and holiday bonuses;\n- Paid leave from the probation period, with the option to receive the salary if not used;\n- Health check once a year and advanced healthcare program;\n- Women\'s care policy: Late arrivals/early departures three times a month, maternity leave with a bonus equivalent to one month\'s salary;\n- Drinks and snacks provided at the office;\n- Support for educational activities, knowledge sharing, and cultural exchanges (Rabitalk, sport clubs: football, table tennis, badminton, etc);\n- Annual trips and quarterly team-building activities;\n- Benefit policy for employee\'s family.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1875, 1025, 2, 'Senior Java Developer', 'We are looking for a Senior Java Developer to expand our Development team in Hanoi, Vietnam.\n\nOutpost24 empowers organizations to achieve cyber resilience with a complete range of continuous threat exposure management (CTEM) solutions. Our cloud platform unifies asset discovery and management, automates security testing, and quantifies risk in business context. Executives and security teams around the world trust Outpost24 to identify the attack surface and prioritize the most important security issues to accelerate risk reduction. Founded in 2001, Outpost24 is headquartered in Sweden, with additional offices in the US, the UK, the Netherlands, Belgium, Denmark, France, Spain and Vietnam.\n\nAs a Senior Java Developer, You Will\n\nYou will be part of one of development teams developing high quality tools for our product platform. You will be part of solving the challenges, we are working with. You will also help us integrate new technology that can improve our product or smarter deployment set. Further you will have a huge impact on the product feature set and implementation. If you want to make a difference, have an impact and develop by having highly skilled people around you - this could be the opportunity for you!\n\nWhat You Will Do\n\n- Develop high quality code that is scalable, maintainable and secure.\n- Be creative to help find solutions to business requirements.\n- Constantly seek ways and technologies to improve our quality and performance.\n- Work in a development team to deliver a high-quality product in an agile work environment.\n- Be part of developing next generation security products.\n- Make a difference for the team.\n\nRequirements And Qualifications\n\n- At a minimum, you should have a bachelor’s degree in Software Development or equivalent.\n- Have solid understanding of the full software development life cycle.\n- Have at least five (05) years’ experiences with Java development tech stack and willingness to learn other programming languages.\n- Experience in SQL (PostgreSQL, SQLite, etc.)\n- Experience in working with Linux\n- Experience in any of the following is an advantage:\n  - Python and Bash\n  - Scalable and high availability systems (Kubernetes, Kafka, containers, ELK etc.)\n  - Webservices\n  - Microservice architecture\n- Willing to work and migrate with legacy systems.\n- Have excellent and analytical problem-solving skills.\n- Have ability to learn quickly and manage yourself independently.\n- Have strong verbal and written communication skills in English.\n- Experienced in leading a development team is an advantage.\n\nBut what\'s in it for you?\n\nIn Return For Your Efforts, We Can Offer You\n\n- A competitive salary package and 100% salary during probation period.\n- An annual salary review and 13th month salary.\n- The chance to work with experienced software engineers worldwide at market leading, innovative Scandinavian SaaS company looking to accelerate growth.\n- Flexible working hours from Monday-Friday, no overtime.\n- A modern working environment with fun colleagues and challenging tasks.\n- A Scandinavian work culture: creativity, innovation, and work-life balance.\n- Premium healthcare and & accident insurance: the best healthcare plan cover for employees and their children.\n\nAnd so much more!\n\nDon’t fulfil all the criteria? Studies have shown that women and people of color are less likely to apply to job openings unless they fulfil every single requirement. At Outpost24, we\'re dedicated to building a diverse and inclusive workplace, where attitude, values and willingness to learn are valued above all. So, if you\'re excited about this role but your professional experiences don\'t completely align with what we\'re looking for, we encourage you to apply anyway!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1876, 264, 2, 'Senior Java Full-Stack Developer(Onsite Q7)', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business with a bold vision of our world’s potential. We’re people-centric and here to power good. Every day, we future-proof urban spaces, conserve natural resources, protect rainforests, and save lives. This is a world where innovation, technology, and deep expertise come together to take our company and customers from what’s now to what’s next. We make it happen through the power of acceleration.\n\nImagine the sheer breadth of talent it takes to bring a better tomorrow closer to today. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally as important to us.\n\nThe role\n\nSenior Full-Stack (Onsite in Q7, HCM)\n\n• 5 Years + experiences in similar roles.\n• Intermediate or upper skills on Oracle/MongoDB and Java Spring boot, microservice, React web app\n\nHard skills: Oracle, SQL, MongoDB\n\n• Plus: microservice, AKS, Jenkins, GIT, Fortify, Snyk Code, Sonar Queue\n• Write high quality source code to program complete applications within deadlines.\n• Perform unit and integration testing before launch.\n• Conduct functional and non-functional testing.\n• Troubleshoot and debug applications.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1877, 940, 2, '[HN] Japan AI - Back End Developer (Node.js)', 'Job description:\n- Participate in AI Chat-related development\n- Develop a Chatbot system based on OpenAI\n- Work collaboratively with frontend/AI engineers and PdMs to design and develop a robust and flexible backend for a powerful AI chat service and user data integration systems.\n- Construct reporting system in Google GCP\n- Build new features, bug fixes, and suggest projects that will improve product and infrastructure.\n- Write sustainable, high-quality, high-performance code\n- Suggest and implement projects that enhance product performance and user experience.\n- Collaborate with cross-functional teams to define, design, and ship new features.\n- Ensure the performance, quality, and responsiveness of applications.\n- Continuously discover, evaluate, and implement new technologies to maximize development efficiency.\n\nJob requirements:\n\nMust have:\n- Bachelor’s degree in Information Technology, Computer science, Data Science, or a related field\n- Around 3 years of backend development experience or equivalent skills, with a strong background in TypeScript and Node.js\n- Familiarity with RESTful APIs and Git, proven ability to write Restful APIs using Next.js, Express.js, or other relevant frameworks\n- Strong knowledge of data structures and algorithms\n- Expertise in SQL databases (mySQL, PostgreSQL, MongoDB…) and NoSQL databases\n- Experience with unit testing and integration testing\n- Proficiency in English, with the ability to communicate effectively in a team setting\n- Stay on track with latest AI trends, using AI tools in development from a user’s perspective.\n\nNice-to-have:\n- Experience with both TypeScript and Python\n- Proficiency in Python libraries and frameworks relevant to AI development\n- Familiarity with containerization and orchestration technologies (e.g., Docker, Kubernetes)\n- Experience with cloud computing platforms, such as Google Cloud Platform (GCP).\n- Experience with front-end development technologies (e.g., React, NextJS)\n- Experience with high availability, high-scale, and performance systems\n- Self-motivated development style\n- Strong teamwork capabilities\n\nWorking time: 9:00 AM - 6:00 PM (1-hour lunch break) from Monday to Friday\n\nEmployment Package:\n- Salary: Negotiable\n- Laptop Mac pro provided\n- Social, public health and unemployment insurance as defined in the Labor Code\n- PVI insurance for staff and 1 family member\n- 12 days’ annual leave and 1 birthday leave\n- Salary review: twice per financial year\n- Half-year bonus: up to 100% of monthly gross salary\n- Most valuable person/team awards per half-year\n- Annual company trip, annual health check\n- Club Allowance, chance to join club activities with cost bearing up to $20/month\n\nResume submission:\nrecruitment-gv@geniee.co.jp\nPlease note that only qualified candidates will be contacted.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1878, 450, 2, 'Senior Software Engineer - Frontend', 'Our Journey\n\nShopBack began in 2014 as a late-night spark of inspiration between Henry and Joel — not just to build a Cashback platform, but to reimagine how brands and consumers connect. As former advertisers, they understood the limitations of traditional marketing, and saw an opportunity to deliver more value on both sides. That idea quickly turned into action, with the first prototype built during a 24-hour sprint. Today, ShopBack serves over 50 million users across 13 markets, partners with 20,000+ merchants, and powers over half a million transactions daily. We\'re building The World’s Most Rewarding Way to Shop — and looking for bold, driven individuals to join us.\n\nAbout The Role\n\nWe are seeking team members who strive to solve hard problems, take pride in delivering world-class products, and are strong team players.\n\nYou are someone who wants to see the impact of your work making a difference every day. You find passion in the craft and are constantly seeking improvement and better ways to solve tough problems.\n\nYour Adventure Ahead\n\n- Contribute to the ideation, technical design, implementation, and testing of product features that empower our business and deliver impact to our customers.\n- Produce high-quality software following good architecture and design principles that are scalable.\n- Design and deliver well-thought-out user interfaces with a strong sense of the overall user experience.\n- Collaborate with the team to define the future of the ShopBack experience.\n- Strong mentoring skills with the ability to provide technical guidance and review code.\n\nEssentials To Succeed\n\n- 4+ years of experience building and designing delightful user experiences as a frontend engineer.\n- Strong knowledge of HTML, CSS, and JavaScript.\n- Understanding of good software design principles and have applied principles to professional work.\n- Hands-on experience working with ReactJS (Preferred) and ecosystem.\n- Have knowledge in Test Driven Development (TDD), CI/CD.\n- Familiarity with RESTful APIs and TypeScript.\n- Ability to work effectively in a fast-paced, complex technical environment with high adaptability and flexibility.\n\nShopBackers\' DNA\n\n- Grit - We tackle all challenges head-on, working together to solve problems and achieve success.\n- Hunger - We value hard work, and having relentless drive.\n- Speed - We move fast and have a bias for action, all to deliver maximum impact.\n- Impact - We focus on results, always aiming for the best possible outcomes and timelines.\n- Growth - We embrace a growth mindset, constantly striving to learn, improve, and excel in our roles.\n\nExclusively for ShopBackers\n\n- Career progression paths and opportunities to take on greater challenges that help you realise your ambitions.\n- Be part of a winning team on a journey to global scale.\n- Competitive compensation based on your performance.\n- Candid, open, and collaborative culture where feedback is valued, for everyone to grow and improve every day.\n- Work-From-Anywhere benefit to enable you to thrive personally and professionally.\n\nShopBack is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. We do not discriminate on the basis of race, color, religion, sexual orientation, national origin, age, disability, genetic information, veteran status, or any other protected status under applicable laws. Join our team and help us make a difference!\n\nWe are committed to protecting your data and ensuring fairness in our recruitment process. As part of this process, we use AI tools to assist with tasks such as application screening and candidate matching. These tools are designed to enhance efficiency and reduce bias, and their use complies with applicable data protection laws and our commitment to fair employment practices. Your personal data will be processed securely and transparently, and final hiring decisions are always made by our recruitment team, not by automated systems. If you have any questions about how your data is used, or wish to exercise any of your rights including the right to such processing, please contact us at dpo@shopback.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'منطقة مدينة هو تشي منه الحضرية', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1879, 837, 2, 'AI Resident (Engineering)', 'Qualcomm Vietnam Company Limited, Hanoi Branch Office\n\nJob Area\nInterns Group, Interns Group > AI Resident\n\nQualcomm Overview\nQualcomm is a company of inventors that unlocked 5G ushering in an age of rapid acceleration in connectivity and new possibilities that will transform industries, create jobs, and enrich lives. But this is just the beginning. It takes inventive minds with diverse skills, backgrounds, and cultures to transform 5Gs potential into world-changing technologies and products. This is the Invention Age - and this is where you come in.\n\nGeneral Summary\nThe Qualcomm® AI Residency Program is a distinguished training ground for exceptional AI talent. It identifies and cultivates top young minds, shaping them into world-class AI experts and future industry leaders.\n\nQualcomm is opening applications for Engineering Residency Batch 1.\n\nAbout the Engineering Residency Program (ERP) (12 months): Residents will address practical AI engineering challenges in domains such as efficient AI, embedded engineering, and agentic AI. Engineering residents will develop robust engineering capabilities and engage in research rotations to become versatile, inquisitive AI engineers.\n\nEligibility & Qualifications\n- Final-year students or recent graduates in Computer Science (or cognate fields) from Vietnamese or international universities.\n- Minimum GPA: 3.2/4.0 or 8.0/10 or equivalent.\n- Strong, self-driven interest in research and ability to learn complex technical material.\n- Exceptional aptitude in mathematics and coding. Preference given to candidates with demonstrated abilities (e.g., research experience, competitions, GitHub repos, AI coursework).\n- Familiarity with Python and AI frameworks like TensorFlow, PyTorch, or Keras\n- Competent English language skills in reading, writing, and speaking. Specialized technical English communication training will be provided.\n- Corporate internship experience is a plus.\n\nKey Responsibilities\n- Collaborate with cross-functional teams to design, build, and deploy AI solutions for various applications.\n- Assist in data preparation, model training, and algorithm selection under the guidance of engineer mentors.\n- Conduct experiments and tests to evaluate the performance of AI models and optimize them for production.\n- Write clean and maintainable code that supports the development and deployment of AI systems.\n- Stay updated with the latest AI trends and technologies to bring innovative ideas to the team.\n\nSelection Process\nThe Qualcomm AI Residency Program employs a rigorous multi-stage selection process. The standard procedure includes the following rounds:\n- Application\n- Screening\n- Portfolio review\n- Coding interview\n- Video presentation\n- Technical interview\n\nA fast-track application is available for academically outstanding students who have demonstrated exceptional achievements, such as winning high prizes in International Olympiads in Mathematics, Informatics, or prestigious international programming competitions like ACM-ICPC. Applicants eligible for the fast-track process will be contacted separately.\n\nATTENTION: Your application must include the following documents:\n- Resume\n- Academic transcript\n- Academic diploma (if already graduated)\n- A letter of recommendation is optional but strongly encouraged.\n\nPlease combine all documents into a single PDF file and upload it with your application. Incomplete applications may not be considered.\n\nFor applicants in their final year of undergraduate study, a provisional graduation certificate is acceptable in place of the diploma.\n\nApplicants: Qualcomm is an equal opportunity employer. If you are an individual with a disability and need an accommodation during the application/hiring process, rest assured that Qualcomm is committed to providing an accessible process. You may e-mail myhr.support@qualcomm.com or call Qualcomm\'s toll-free number found here. Upon request, Qualcomm will provide reasonable accommodations to support individuals with disabilities to be able to participate in the hiring process. Qualcomm is also committed to making our workplace accessible for individuals with disabilities.\n\nQualcomm expects its employees to abide by all applicable policies and procedures, including but not limited to security and other requirements regarding protection of Company confidential information and other confidential and/or proprietary information, to the extent those requirements are permissible under applicable law.\n\nTo all Staffing and Recruiting Agencies: Our Careers Site is only for individuals seeking a job at Qualcomm. Staffing and recruiting agencies and individuals being represented by an agency are not authorized to use this site or to submit profiles, applications or resumes, and any such submissions will be considered unsolicited. Qualcomm does not accept unsolicited resumes or applications from agencies. Please do not forward resumes to our jobs alias, Qualcomm employees or any other company location. Qualcomm is not responsible for any fees related to unsolicited resumes/applications.\n\nIf you would like more information about this role, please contact Qualcomm Careers.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1880, 1026, 2, '(Senior) Java Developer (Integration)', 'CEVA Logistics provides global supply chain solutions to connect people, products and providers all around the world. Present in 170 countries and with more than 110,000 employees spread over 1,500 sites, we are well on our way to achieving our vision: to be a Top 5 global 3PL.\n\nWe believe that our employees are the key to our success. We want to engage and empower our diverse, global team to co-create value with our customers through our solutions in contract logistics and air, ocean, ground, and finished vehicle transport. That is why CEVA Logistics offers a dynamic and exceptional work environment that fosters personal growth, innovation, and continuous improvement.\n\nCESA Vietnam was founded in 2018; CESA started as a development center in Vietnam, then now became a technology company of CEVA Logistic, specializing in Microsoft .Net technologies (ASP.Net MVC, API, Azure,...), ESB platform (Webmethods, Java...) and delivers projects using Agile methodology.\n\nWorking with us, you’ll have the opportunity to develop your skills and career in an exciting workplace in touch with an international and innovative environment.\n\nDARE TO GROW! Join CESA Vietnam / CEVA Logistics, and you will be part of a team that values imagination, encourages boldness and exemplarity, and is committed to excellence in everything we do. Join us in our mission to shape the future of global logistics as we become a global leader in the logistics industry. As we continue growing at a fast pace, will you “Dare to Grow” with us?\n\nMain tasks and activities\n- Responsible in designing, implementing, and maintaining integrations between applications/systems (internal applications within CEVA or external applications from numerous trading partners), ensuring smooth data flow and communication\n- Design, develop, review, test, and manage underlaying integration frameworks and components that are being used by other integration teams\n- Responsible for mentoring, reviewing code and helping other team members with technical issues\n- Ensure maintenance and management of developed solutions\n- Participate to common daily/weekly meeting with project teams based in Paris or India.\n- Realize daily and weekly activity reporting using Group tools\n\nEducational background\n- Graduate in computer science or related fields\n\nTechnical skills\n- For Middle level: 3+ years of experience as a software engineer in a complex development environment.\n- For Senior level: 5+ years of experience as a software engineer in a complex development environment.\n- Solid experience in Java programming language\n- Experience in designing & developing RESTful APIs\n- Experience with unit testing and integration testing\n\nAdvantageous to have:\n- Domain knowledge and experience in Transport and Logistics is a plus\n- Experience in working as enterprise application integration engineer before\n- Hands-on experience with any messaging system/service such as RabbitMQ, Kafka, Google Cloud Pub/Sub, etc.\n- Experience with any Cloud platforms (Microsoft Azure, AWS, GCP, etc.)\n\nLanguage\n- Good communication in English (written and spoken)\n\nSoft skills\n- Have good logical and critical thinking \n- Having passion for technology and a continuous learning mindset\n- Good problem-solving and analytical skills\n- Good team player and positive attitude\n\nPay range: up to $2000\n\nOffice: Etown 2, 364 Cong Hoa, ward 13, Tan Binh Dist, Ho Chi Minh City, Vietnam\n\nBenefits\n- Being a pioneer in contributing to team development with a long-term vision\n- High-ownership working environment: You will take full responsibility and control of your missions contributing to the team\'s success in a daily collaboration with Paris teams\n- Continuous skill improvement with new technologies, challenging projects, on-the-job coaching, knowledge exchange with technical experts, and training programs (locally and in Paris)\n- Annual performance review: recognize your efforts and identify development/ improvement needs\n- Be secure in your mind with employee care: private healthcare insurance package, medical check-ups, allowance support...\n- Great-place-to-work activities (company trips, sport clubs...): enhance teamwork spirit and facilitate your work-life balance\n- Opportunity to participate in global events (Hackathon, Seminar, Innovation Factory...)\n\nCESA Vietnam/ CEVA Logistics is proud to be an equal opportunity work place and an affirmative action employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, gender, gender identity or expression, sexual orientation, national origin, genetics, disability, age, veteran status or any other characteristic. We are an Equal Opportunity Employer of Minorities, Females, Protected Veterans, and Individual with Disabilities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tân Bình, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1881, 880, 2, 'Freelance Software Developer (Python) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields. \n- You have at least 3 years of professional experience with Python\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you? \n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1882, 816, 2, 'Senior PHP Developers (Laravel/ MySQL)', 'Mô tả công việc\n\n・Phát triển hệ thống ứng dụng theo xu hướng công nghệ 4.0 (AI , Bigdata , Block Chain , Machine learning)\n\n・Phát triển hệ thống thương mại điện tử .\n\nKhông yêu cầu', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1883, 767, 2, 'Unity Game Developer - MINTROCKET', 'Mô tả công việc\n\nDevelop game content using the Unity engine\nDevelop tools necessary for game production and collaboration\n\nYêu cầu công việc\n\nQualifications\n\nExperience in game development using the Unity engine\n\nGeneral Competencies\n\nPassion and dedication for game development\nAbility to read, write, and communicate in English\nPositive mindset and proactive communication skills\nStrong sense of responsibility for assigned tasks\nLogical thinking and creative problem-solving skills\n\nJob-Specific Skills\n\nProficiency in C# programming\nUnderstanding of 2D/3D programming\nKnowledge and implementation of data structures and algorithms\n\nPreferred Qualifications\n\nUnderstanding of game physics and mathematics\nExperience in client profiling and optimization', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1884, 674, 2, 'Thực tập sinh Phát triển Mã Coin (Blockchain Developer Intern)', 'Mô tả công việc\n\n- Tham gia vào quá trình thiết kế và phát triển mã coin/token trên các nền tảng blockchain phổ biến như Ethereum (ERC-20), BNB Chain (BEP-20), Solana, hoặc các blockchain khác.\n- Viết và triển khai smart contract bằng Solidity (hoặc các ngôn ngữ phù hợp khác).\n- Hỗ trợ kiểm thử, mô phỏng và tối ưu hóa mã nguồn smart contract.\n- Làm việc cùng các thành viên trong team để phát triển tính năng cho dự án như ví điện tử, DApp, staking, v.v.\n- Nghiên cứu và áp dụng các xu hướng công nghệ mới trong lĩnh vực blockchain, DeFi, Web3\n\nYêu cầu công việc\n\n- Sinh viên năm cuối hoặc mới tốt nghiệp các ngành CNTT, Khoa học Máy tính, hoặc liên quan.\n- Có kiến thức cơ bản về blockchain và smart contract.\n- Biết lập trình một trong các ngôn ngữ: Solidity, JavaScript/TypeScript, Python là lợi thế.\n- Tư duy logic tốt, ham học hỏi, có khả năng tự nghiên cứu.\n- Ưu tiên đã từng thử viết token đơn giản (ERC-20 hoặc tương đương)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 하이퐁 Quoc Tuan Commune', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1885, 1027, 2, 'C++ Developer', 'Innotech is looking for a C++ Developer to join our team and contribute to software development projects in industrial systems and device control. You will:  - Analyze requirements and implement C++-based solutions.  - Prepare basic technical documentation and collaborate with the team to clarify system architecture and development approach.  - Write code, debug, and work on performance improvements.  - Collaborate closely with the team and proactively suggest technical or process improvements.  - Preparing technical documentation and outlining system architecture in collaboration with with stakeholders (such as PM, clients).   Requirements:  - Bachelor\'s degree in Computer Science, Computer Engineering, Electrical Engineering, or related fields.  - At least 1 year of experience with C++ development.  - Solid understanding of data structures, algorithms, multi-threading, and concurrency.  - Familiarity with version control tools (Git, SVN).  - Ability to read and understand technical documents in English.  - Dedicated, responsible, and eager to learn.   Nice to have:  - Experience working on both Windows and Linux platforms.  - Background in embedded systems, robotics, or hardware/device integration.  - Familiarity with Jenkins, CI/CD, or automation tools.  - Experience with EtherCAT, driver development, or semiconductor-related software is a plus.   Why Innotech?  - 13th-month salary calculated based on actual working time at INNOTECH.  - PVI Healthcare Insurance for all employees.  - PVI Healthcare Insurance for family.  - Moon cake, Tet Gift.  - Quarterly/project kickoff team-building budget.  - Monthly birthday parties with cake.  - High-resolution laptop and monitor provided for work.  - Performance bonus plan.  - Employee referral bonus: 2,000,000 – 10,000,000 VND (depending on level/role).  - Annual company trips / Football club / Climbing club / Year-end party.  - Learning and certification support.  - Value-oriented, international working environment with a flexible culture.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1886, 1028, 2, 'Nhân viên Kiểm thử phần mềm (Tester) Mới', 'MetaServ\n\nHà Nội\n\nUp to 14.000.000 VND\n\nMô tả công việc\n\n- Phân tích, đọc hiểu các tài liệu yêu cầu, tài liệu đặc tả và các tài liệu thiết kế của dự án.\n- Viết test case, chuẩn bị dữ liệu test và thực thi test để đảm bảo sản phẩm hoạt động đúng theo yêu cầu.\n- Thực hiện các công việc khác dưới sự phân công của leader và PM.\n\nYêu cầu công việc\n\n- Từ 01 năm nghiệm trong kiểm thử phần mềm.\n- Nắm được kiến thức kiểm thử và quy trình phát triển phần mềm.\n- Có khả năng định nghĩa trạng thái hoạt động lý tưởng của hệ thống, xác định phương pháp kiểm thử và công cụ sử dụng.\n- Có thể lên kế hoạch kiểm thử, chạy test và lưu log.\n- Có kinh nghiệm làm việc với quy trình Agile (SCRUM).\n- Kỹ năng làm việc/giao tiếp với các bên liên quan, cẩn thận, tích cực.\n\nQuyền lợi\n\n- Thưởng hằng năm tương xứng với năng lực làm việc.\n- BHXH gần full lương, hưởng thêm Bảo hiểm tai nạn PVI 100% và gói BH sức khỏe theo thâm niên.\n- Được tài trợ chi phí tham gia các khóa đào tạo nâng cao năng lực.\n- Chế độ OT rõ ràng, ting ting các ngày lễ/tết, hiếu hỉ, sinh nhật, khám sức khỏe định kỳ 1 lần/năm.\n- Môi trường trẻ trung, chuyên nghiệp, đồng nghiệp thân thiện, sẵn sàng hỗ trợ.\n- Du lịch, CLB bóng đá, cầu lông, tennis… và các hoạt động khác được tổ chức thường xuyên.\n\nNộp đơn\n\nYêu cầu kinh nghiệm\n\n01 năm kinh nghiệm\n\nTrình độ học vấn\n\nĐại học/Cao đẳng\n\nCấp bậc nghề nghiệp\n\nNhân viên\n\nHình thức làm việc\n\nToàn thời gian\n\nLiên hệ\n\nPhòng Nhân sự\n\n- Email: tuyendung@dts.com.vn\n- SĐT: 024 3942 6568 (Ext: 340)\n\nHoặc 028 3933 6666 (Ext: 645)\n\nTin tuyển dụng liên quan\n\nMetaServ Mới\n\nĐịa điểm: Hà Nội\n\nNgày hết hạn: 30.06.2025\n\nChi tiết\n\nXem thêm', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1887, 1029, 2, 'Computer Vision Engineer', 'Aimesoft là nơi quy tụ những chuyên gia ứng dụng AI nhằm giải quyết những vấn đề thực tiễn. Sứ mệnh của Aimesoft là đồng hành trong đời sống con người thông qua các ứng dụng trí tuệ nhân tạo đa thể thức chân thực và sống động. Tài sản lớn nhất của Aimesoft là đội ngũ hơn 50 chuyên gia và kĩ sư nghiên cứu với nền tảng lập trình vững chắc và kinh nghiệm thực chiến các dự án “khó nhằn”. Dưới dự dẫn dắt của TS. Nguyễn Tuấn Đức (CEO) và cố vấn của các chuyên gia đến từ Đại học Tokyo, Nhật Bản, Aimesoft đang có những bước chuyển mình mạnh mẽ nhằm khẳng định vị trí số 1 về cung cấp giải pháp ứng dụng Trí tuệ nhân tạo.\n\nHiện tại, Aimesoft đang tìm kiếm các Computer Vision Engineer (từ 1 năm kinh nghiệm) và nhiều vị trí khác để tham gia vào đội ngũ kĩ sư tài năng của chúng tôi tại văn phòng Hà Nội.\n\nMô tả công việc:\nVới vai trò Kĩ sư phần mềm Xử lý ảnh tại Aimesoft, bạn sẽ trực tiếp nghiên cứu và phát triển các phần mềm ứng dụng công nghệ xử lý ảnh, nhận dạng ảnh (Image processing/Image recognition).\n\nYêu cầu:\n- Thành thạo ngôn ngữ lập trình Python và đã từng sử dụng các framework như TensorFlow, PyTorch, Keras,...\n- Có ít nhất 1 năm kinh nghiệm tham gia vào các dựa án liên quan đến Học Máy (Machine Learning) và xử lý ảnh.\n- Có kĩ năng lập trình C/C++ là một điểm cộng.\n- Ưu tiên có các giải thưởng Tin/toán học hoặc bài báo khoa học trong các hội thảo về Xử lý ảnh, Nhận dạng ảnh.\n- Có khả năng đọc hiểu tài liệu tiếng Anh, tiếng Anh giao tiếp tốt là một lợi thế.\n\nQuyền lợi:\n- Thưởng Tết và lương tháng 13.\n- Bảo hiểm, chương trình khám sức khỏe.\n- Review thường xuyên, liên tục để tăng lương dựa trên thành tích thực tế.\n- Bạn được đảm bảo xây dựng lộ trình phát triển sự nghiệp và kỹ năng ngay tại công ty, review liên tục để cập nhật tiến độ phát triển và điều chỉnh khi cần.\n- Được đào tạo, training với các khóa đào tạo miễn phí của công ty bởi các giảng viên, chuyên gia hàng đầu.\n- Tham gia teambuilding, du lịch hằng năm.\n- Thời gian làm việc từ thứ 2 - thứ 6 (8h30 -18h00). Không OT.\n\nEmail: huechi@aimesoft.com\nMobile: 0986 828 032\nAddress: 10F, Viet A Tower, 9 Duy Tan Street, Cau Giay, Hanoi, Vietnam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1888, 582, 2, 'Senior PHP Developer (6 months)', 'Location: District 3, HCMC\nWorking hours: 9am – 6pm Mon-Fri (Onsite)\n\nCompany Overview \nSGH Asia is a leading technology solutions provider specializing in digital transformation, offering services such as software development, IT support, business process outsourcing, and data digitalization.\n\nWe are looking for a Senior PHP Developer to join us and work on our client’s projects using cutting-edge technologies.\n\nAs a backend developer, you’ll be responsible for ensuring system performance, security, and stability, developing backend APIs for product features, and collaborating effectively with cross-functional teams.\n\nResponsibilities\n- Work closely with Product Manager to understand requirements and features\n- Design, develop, deploy, and maintain backend services and microservice frameworks\n- Manage priorities, meet deadlines, and ensure high-quality deliverables\n- Build and maintain shared libraries to boost engineering efficiency\n- Deliver scalable, robust technical solutions for new features\n- Own the full lifecycle of services, from development to maintenance\n- Collaborate actively and foster a positive team environment\n- Debug and resolve issues to ensure service reliability\n- Drive technical improvements and innovation\n- Identify and reduce technical debt to maintain code quality.\n\nMust-have Qualifications\n- 4+ years of experience with PHP\n- Strong in API/backend development with relational & NoSQL databases\n- Familiar with CI/CD, Docker, and Kubernetes\n- Solid understanding of data structures and algorithms\n- Experience with gRPC, RESTful, and GraphQL APIs\n- Proficient in Git/GitLab for version control\n- Worked with at least two data systems: Postgres, MongoDB, MySQL, Elasticsearch, Redis, Kafka, TimescaleDB\n- Good grasp of scalable application design principles.\n\nNice-to-have Qualifications\n- Knowledge of authentication/authorization across systems\n- Familiarity with Golang or Python\n- Basic front-end skills: JavaScript, HTML5, CSS3\n- Experience with microservices and event-driven architectures\n- Skilled in benchmarking and performance tuning\n- Experience with tracing, monitoring (Grafana), and log management (ELK stack)\n- Proficiency in writing unit tests and integration tests to ensure the reliability and correctness of backend services.\n\nWe’re excited to meet talented individuals who are passionate about building great products—come join our team!\n\nPlease send your CV to careers@sgh.asia', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1889, 857, 2, 'React Native Developer', 'bTaskee is looking for an extremely impressive person to fill the role of Middle React Native Developer, building high-performance mobile applications, optimizing micro-frontend integration, and collaborating with teams to enhance user experiences.\n\nResponsibilities And Duties\n- Develop and maintain cross-platform mobile applications (iOS & Android) using React Native\n- Collaborate with Backend, UI/UX teams to design, optimize, and enhance app performance.\n- Ensure the quality, scalability, and security of mobile applications.\n- Troubleshoot issues and improve app functionality based on user feedback and team requirements.\n- Stay up-to-date with new technologies and industry trends.\n- Familiarity with version control (Git) and mobile debugging tools.\n- Attention to detail and a passion for creating great user experiences. Comfortable using AI coding assistants\n\nQualifications And Skills\nMust to Have\n- Bachelor’s Degree in Software Engineer/Information Technology or IT-related major;\n- Have 2+ years of experience in mobile application development, specifically with React Native;\n- Proven experience building and deploying complex applications using Re.Pack, Module Federation, or similar tools;\n- Deep understanding of JavaScript, TypeScript, and modern frontend development.\n- Proficiency with state management solutions (Redux, MobX) and native development tools (Xcode, Android Studio);\n- Strong experience in performance optimization, debugging, and deploying to app stores;\n- Have a personal laptop.\n\nNice to have\n- Experience with micro-frontend architectures in production environments;\n- Knowledge of containerization and orchestration (Docker, Kubernetes).\n\nWhy You\'ll Love Working Here\n- Professional Development: Upgrade your skills and ignite your career;\n- Collaborative Atmosphere: Everyone works together to execute the mission;\n- Team Spirit: Caring for our people and bonding together are musts for us;\n- Dynamic Growth: Our teams are scaling up quickly. There’s no better time than now to come on board;\n\nAt bTaskee, we don’t just work – we thrive with top-notch benefits!\n- Competitive Salary – Rewarded based on your experience and skills;\n- Annual Performance Review – Unlock growth opportunities every year;\n- KPI-Based Salary – Earn what you deserve through your contributions;\n- 13th-Month Bonus – Rewarded based on both your performance and the company’s success;\n- BYOD Support – Get an allowance while enjoying the flexibility of using your own laptop;\n- Comprehensive Healthcare – Regular check-ups & a premium health package;\n- SHUI Compliance – Contributions aligned with legal regulations;\n- Generous Leave Policy – Enjoy 12–16 annual leave days per year;\n- Celebration Perks – Special benefits for birthdays, weddings, childbirth, and more;\n- Engaging Workplace – Activities & exciting team-building events;\n- Advance Home Care Benefit – Get a monthly bTaskee package, freeing up your time for learning, relaxation, and self-care.\n\n🚀 Join us and thrive in a workplace that values both your growth and well-being!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 12, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1890, 216, 2, 'Senior Game Developer (Freelancer/Remote)', 'Design and develop the “View” component of the game portal, ensuring responsiveness, scalability, and seamless integration within an MVC/MVVM architecture.\nDevelop core game logic and mechanics tailored to marketing objectives, keeping the games lightweight and optimized for mobile browsers.\nBuild interactive widgets (e.g., buttons, leaderboards, timers) that overlay directly on video streams, enabling real-time player interaction.\nCollaborate on game engine selection (Unity or Unreal Engine) and apply knowledge of rendering pipelines, asset handling, and scripting.\nOptimize browser-based games for mobile-first experiences, ensuring high performance and compatibility with modern browsers like Chrome and Safari.\n\nJob Requirement\nStrong understanding of MVC/MVVM design patterns, especially in relation to view-layer development in game portals.\nHands-on experience with Unity or Unreal Engine. Familiarity with WebGL, HTML5, or JavaScript-based game development is a significant advantage.\nExperience integrating games into video streams and working with widget overlays.\nExpertise in mobile-first development: low latency, high responsiveness, and optimized performance on mobile browsers.\nProficiency with Git, CI/CD workflows, and cross-browser debugging\nFluent in English communication.\n\nBenefit\nSalary: Negotiate.\nPackage: At least 13 months/ year. Review periodically following company policy.\nBonus: Tet bonus, project bonus, holiday bonus, HR referral bonus...\nSeniority allowance (working time from 2 years or more).\nParticipate in learning and training activities inside and outside the company, accumulate learning points, develop G-Points on the company\'s management system.\n2 days of per week and 12 leave days per year.\nClubs and many cultural - sports - art activities sponsored or supported by the company (For example: Football, table tennis, badminton, swimming, music, English, games... )\nEnsure health: Periodic health check, support to buy high quality health insurance...\nJoin the Rikkei Care Health Insurance Plan.\nMental comfort: Playing music on demand every day, happy hour, team building activities...\n\nApply: maint9@rikkeisoft.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj a okolí', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1891, 1030, 2, 'Magento Developer (e-commerce)', 'Company Summary\n\nThis digital team operates within a larger group structure and is focused on delivering top-tier e-commerce experiences. By continuously innovating and optimizing their digital platform, the team aims to provide seamless online shopping journeys. They are seeking a passionate and technically skilled Magento Developer to help elevate their e-commerce solutions and enhance the customer experience.\n\nResponsibilities\n\n- Collaborate with cross-functional teams to develop, maintain, and enhance a Magento-based e-commerce platform.\n- Customize and configure Magento 2 to align with business goals and requirements.\n- Create custom modules and extensions to improve store functionality and user interaction.\n- Work with UX/UI designers to implement visually compelling and responsive web interfaces.\n- Integrate third-party systems, APIs, and plugins to support and enhance site features.\n- Diagnose and fix technical issues, ensuring stable and error-free functionality.\n- Optimize the site for speed, security, and performance.\n- Conduct thorough code reviews to ensure quality, maintainability, and best practices.\n- Keep current with Magento trends, platform updates, and industry standards.\n- Contribute to gathering technical requirements and provide expert input on development strategies.\n- Offer mentorship and guidance to junior developers.\n- Work with stakeholders to implement new features and continually improve the platform.\n\nRequirements And Benefits\n\n- Bachelors degree in Computer Science, Information Technology, or related discipline, or equivalent experience.\n- Demonstrated experience in Magento development with a portfolio of successful projects.\n- Expertise in Magento 2, including module development and theming.\n- Strong proficiency in PHP, MySQL, HTML, CSS, JavaScript, and AJAX.\n- Experience using version control systems like Git and familiarity with deployment workflows.\n- Understanding of e-commerce best practices, payment gateway integrations, and PCI compliance.\n- Awareness of SEO principles.\n- Strong troubleshooting and problem-solving skills.\n- Excellent team collaboration and communication abilities.\n- Self-driven with the ability to work independently.\n- Magento certifications are a plus.\n\nPreferred Skills:\n\n- Experience with alternative e-commerce platforms or CMSs (e.g., Shopify, WooCommerce).\n- Knowledge of website performance optimization.\n- Familiarity with DevOps tools and cloud platforms (e.g., AWS, Azure).\n- Exposure to Agile or Scrum development practices.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1892, 715, 2, 'Kỹ sư Phát triển giao thức Streaming', 'Nơi làm việc: Hà Nội/Tp.Hồ Chí Minh\n\nMÔ TẢ CÔNG VIỆC:\nNhiệm vụ: Thiết kế và phát triển giao thức streaming video&amp;audio cho nền tảng camera và các ứng dụng lên quan đến media streaming, đảm bảo chất lượng video&amp;audio tốt nhất, độ trễ thấp, độ ổn định cao.\nYÊU CẦU:\nTốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Toán – tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\nTrình độ tiếng Anh tương đương 550 điểm Toeic trở lên.\nThành thạo C/C++, có kỹ năng lập trình cho multithreading\nCó kinh nghiệm trong lĩnh vực phát triển protocol đặc biệt media streaming protocol.\nThành thạo áp dụng các design pattern cho lập trình C và C++.\nHiểu biết sâu về giao thức:\nThành thạo lập trình networking protocols, bao gồm TCP/IP, UDP, WebSockets, Protobuf, HTTP/2, …\nCó kinh nghiệm về các giao thức streaming: ICE/STUN/TURN, P2P communication, WebRTC, RTSP/RTP/RTCP, SRTP, SRT, SCTP, HLS,…\nCó kiến thức về các giao thức ARQ, Congestion Control,…\nHiểu biết về xử lý, nén và streaming video &amp; audio\nCó kiến thức về mã hóa và bảo mật (encryption, end-to-end encryption)\nCó kiến thức và kỹ năng về benchmark các giao thức truyền thông\nCó kiến thức và kỹ năng về phát triển các unittest nói chung và cho giao thức truyền thông nói riêng.\nCó kinh nghiệm làm việc với các open-source player để tích hợp và thử nghiệm giao thức streaming với các player.\n\nƯu Tiên\nThạc sỹ, Tiến sỹ các chuyên ngành liên quan đã có quá trình nghiên cứu tại các quốc gia phát triển trên thế giới.\nỨng viên đã có kinh nghiệm đảm nhận vị trí tương đương tại các công ty, tổ chức uy tín trong nước hoặc thế giới.\nCHẾ ĐỘ ĐÃI NGỘ:\nĐược hưởng các khoản quà, thưởng lễ tết, nghỉ mát hỗ trợ ăn trưa, điện thoại liên lạc tối thiểu 2.000$/năm và các chế độ thưởng theo dự án, mức độ thành công của các sản phẩm nghiên cứu.\nĐược hưởng 12 ngày nghỉ phép và 15 ngày nghỉ hưởng nguyên lương gồm 11 ngày nghỉ lễ tết, 3 ngày nghỉ mát và 1 ngày sáng tạo hàng năm.\nĐược hưởng các chế độ BHXH, BHYT và BHTN theo Quy định và chế độ bảo hiểm riêng của Tập Đoàn Viettel.\nĐược trực tiếp tham gia quá trình nghiên cứu, thiết kế và chế tạo các sản phẩm công nghệ cao trong lĩnh vực công nghiệp quốc phòng; các sản phẩm có định hướng nghiên cứu dài hạn.\nCó cơ hội được làm việc cùng với nhiều chuyên gia, đối tác nước ngoài, tham gia các hội nghị khoa học quốc tế trong các lĩnh vực công nghiệp quốc phòng.\nĐược cử đi đào tạo, nâng cao trình độ chuyên môn và kỹ năng phục vụ công việc trong và ngoài nước.\nCó cơ hội chuyển Quân nhân chuyên nghiệp/ Sỹ quan thuộc Bộ quốc phòng Việt Nam.\nMức lương cạnh tranh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1893, 1031, 2, 'Dev Backend C#', 'Dev Backend C#\nSalary: 2500$-3500$\n\nJOB DESCRIPTION:\n- Programming backend systems to store data/documents, integrating with other backend systems;\n- Read and understand business analysis documents, coordinate with the business analysis team to participate in the consulting process, choose solutions and technical design;\n- Participate in internal research activities to improve technological capacity, develop new products to serve future markets/projects;\n- Work and develop products according to Agile/Scrum.\n\nJOB REQUIREMENTS: \n- Enthusiastic and loves technology\n- Good communication ability.\n- Have 2 years of experience using at least one back-end programming language (Java, C#, NodeJS, Ruby,...)\n- Have experience with one of the following databases: MySQL, Oracle, DB2, Postgres - Trained if no experience & ensure enough background knowledge\n- Skilled in CMS and Python programming language\n\nBENEFITS\n- Salary depending on experience and working capacity, salary increase and good benefits.\n- Year-end bonus + Holiday/Tet bonus + birthday bonus + unexpected bonus for completing tasks well\n- Work in a dynamic, creative and interesting international environment.\n- Participate in training courses and professional training, management skills to develop, participate in team building activities and events of the Company\n- Provided with working equipment and allowance for food and accommodation.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1894, 182, 2, 'Senior Backend Engineer (Microservice, AWS)', 'About our Team:\n\nOur team is responsible for creating a brand new suite of digital financial platforms and apps that are highly reliable and scalable, using modern engineering practices. You will be joining a project with talented software engineers in our Digital Bank Build team, who are responsible for designing, building, and maintaining the new digital banking platform and its customer channels. As part of the team, you will implement software features, participate in technical designs, and write tests to ensure high-quality product delivery. Our teams operate in Scrum and DevOps models.\n\nWe\'re looking for top engineers! During the interview process, we will assess your coding and design skills to evaluate your experience and depth of knowledge. Don\'t worry, our interview process will be engaging!\n\nResponsibilities:\n\nAs a Backend Engineer, you will work on specific problem domains, designing, developing, and deploying backend services with a focus on scalability, high availability, and low latency.\n\n- Drive the efficient delivery of change through analysis, definition, and documentation of requirements, while identifying potential solutions using agile delivery frameworks.\n- Solve complex technical and business problems and learn new technologies and frameworks.\n- Be part of a team that takes full responsibility for the features you own\n- Design, develop, test, deploy, monitor, and improve - you are responsible for the full lifecycle of your product.\n\nRequirements\n\nYou will be a perfect match if your profile ticks some of the items below:\n\nMust-have:\n\n- A pragmatic mindset\n- Outstanding problem-solving ability, eagerness to learn, and curiosity\n- +5 years of software development experience with one or more general-purpose programming languages (e.g., Java, Python, etc.)\n- Strong database and schema design skills for large-scale applications\n- Adaptable attitude and personality, ready for continuous change\n- Collaboration and culture fit in an Agile environment\n- Good English skills\n\nNice to have:\n\n- Experience developing distributed systems using microservices architecture, serverless architecture, and event-driven architecture. Experience with Java, Spring Boot, Kafka, Redis, Python (e.g., Django, Flask, FastAPI), or similar technologies is a plus\n- Experience with AWS, Ansible, Packer, Docker, and Kubernetes is a significant plus\n- Experience with automated testing frameworks\n- Strong English listening and speaking skills\n- Experience working in the banking and financial domain\n\nBenefits\n\n- Meal and parking allowance are covered by the company\n- Full benefits and salary rank during probation\n- Insurances as Vietnamese labor law and premium health care for you and your family without seniority compulsory\n- Performance bonus up to 2 months\n- 13th month salary pro-rata\n- 15-day annual leave+ 3-day sick leave + 1 birthday leave + 1 Christmas leave\n- SMART goals and clear career opportunities (technical seminar, conference, and career talk) - we focus on your development\n- Values-driven, international working environment, and agile culture\n- Overseas travel opportunities for training and working related\n- Internal Hackathons and company\'s events (team building, coffee run, blue card...)\n- Work-life balance 40-hr per week from Mon to Fri', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1895, 778, 2, 'Embedded Software Engineer', 'We highly appreciate your interest in this position of HCLTECH Vietnam. After reviewing all applications, only qualified candidates will be contacted for the next steps within 15 days from date of submission.\n\nABOUT HCLTECH VIETNAM COMPANY LIMITED\nHCLTECH Vietnam Company Limited belongs to HCLTech.\nHCLTech is a global technology company, home to more than 223,400 people across 60 countries,\ndelivering industry-leading capabilities centered around digital, engineering, cloud, and AI, powered by a broad portfolio of technology services and products. We work with clients across all major verticals, providing industry solutions for Financial Services, Manufacturing, Life Sciences and Healthcare, Technology and Services, Telecom and Media, Retail and CPG, and Public Services. Consolidated revenues as of 12 months ending June 2023 totaled $12.8 billion. To learn how we can supercharge progress for you, visit https://www.hcltech.com/.\n\nJob Title: Embedded Software Engineer (Engine Management System Software) \nLocation: 28bis Mac Dinh Chi street, Dakao Ward, District 1, HCMC\n\nJob Description\nWe are looking for a skilled Embedded Software Engineer to design and implement new systems and features, as well as modify and maintain existing systems (Engine Management System Software) for adaptation to business and/or technology changes. The Software Engineer engages directly with Customer, development teams, technical delivery teams and HW system teams to ensure the successful design, development, and delivery of technology-based solutions.\nTo be successful as a Software Engineer, you should be able to drive the software change and release management processes, assisting with the overall maturity of the software development lifecycle. Ultimately, a top-notch Software Engineer will ensure that software deliverables comply with quality standards and are completed on time.\n\nDUTY & RESPONSIBILITIES:\n- Analysis requirements from customer/internal stakeholders.\n- Design/propose technical solution to satisfy requirements.\n- Realize software design by modifying base software.\n- Do configuration for CAN communication based on customer requirement.\n- Handle sending/receiving data to/from CAN bus from/to other components in Software.\n- Calculate/Convert data for different purposes.\n- Monitor CAN network behavior and transmission of messages/signals on CAN bus.\n- Perform testing to verify software.\n- Development and maintenance of simulation/automation for testing purposes\n\nQUALIFICATIONS:\n- More than 5 YOE in Embedded Automotive Development\n- Experienced in leading team\n- English Ability to write and read technical documents, basic communication\n- C language Ability to write and read C code masterfully\n- Embedded Have knowledge about Automotive Embedded System & Application\n- AUTOSAR Have basic knowledge about AUTOSAR\n- CAN Protocol Have awareness about CAN protocol and its application in automotive\n- Logical Thinking Smart/Creative Thinking is one of the most important\n- Braking System Have basic awareness about Braking System in Vehicle\n\nBENEFITS \n- Insurance plan based on full salary + 13th salary + Performance Bonus.\n- 100% full salary from the 1st day of working and during WFH.\n- Medical Benefit (Bao Viet Insurance package) for Employee and Family.\n- Working in a fast paced, flexible, and multinational working environment. Chance to travel onsite (in 54 countries).\n- Internal Training (Technical & Functional). Scope of English Training.\n- 18 paid leaves per year (including 12 annual leaves + 6 personal leaves).\n\nFor support and more information, please contact: \nMai Huynh\nPhone/Zalo: +84 911045533\nEmail: tien_tran@hcltech.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1896, 1032, 2, 'Senior Frontend Developer', 'Who We Are\nHello Health Group is a leading digital health company in Asia. Our goal is to lead Asia in the creation of healthcare knowledge, making World Class trustworthy health information accessible and useful; empowering us all to live happier and healthier lives. Founded in July 2015, we have successfully launched in 9 markets across Asia. Our mission is to support over 100 million people in Asia monthly by providing them easy and fast access to trustworthy, relevant and engaging health content.\n\nYour Challenges\n- Responsible for creation of all coded Front-end deliverables\n- Responsible for mentorship and guidance to technical team members in all project activities on multiple small to medium sized projects or one large project\n- Able to shift between a creative and a technical focus depending on the project need and/or the type of project\n- Identifies new opportunities for the client. Develops innovative ideas.\n- Participates in developing supporting proposal materials for projects\n- Participates in scoping and planning work\n- Write technical documentation (admin guides), white papers, and presentations, contribute to determining internal processes\n- Be a thought leader in the Front-end technologies and space.\n\nWho We Want\n- At least 5+ years of experience in Front-End hand-coding, React, Next.js\n- In-depth knowledge of JavaScript, CSS, HTML, and front-end languages.\n- Knowledge of REACT tools including Typescript, Webpack, Enzyme, Redux, and Flux.\n- Experience with SonarQube, ESLint, Prettier, and other static code analysis tools to maintain code quality.\n- Understanding of clean code principles, SOLID principles, and design patterns.\n- Knowledge of accessibility, security best practices, and performance optimization techniques.\n- Ability to write clean, maintainable, and well-documented code.\n- Good project management and collaboration skills.\n- Experience developing accessible websites (Section 508, W3C WAI Guidelines, etc.)\n- Experiences for Search Engine Optimization is a plus\n\nWhat We Offer\nWe are passionate individuals who are driven to succeed. Our work culture is characterized by strong team spirit, high degrees of openness and innovation, and strong collaboration across fields. We love the freedom of an entrepreneurial company and are looking for like-minded, ambitious professionals who have a desire to build something new and actively support our young company in its growth to greatness.\n\nYou will love working here!\n- Competitive remuneration package\n- Professional and open working environment—culturally integrating the best of Western and Southeast Asian cultures to make the best of each and ensure we build an energetic, commercial, and fun working atmosphere.\n\nDo you think you’ve got what it takes? Apply now!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1897, 923, 2, '[HN] AI ENGINEER - COMPUTER VISION', '[HN] AI Engineer - Computer Vision\n\nC-Camera là sản phẩm camera ứng dụng AI, giúp hỗ trợ giám sát và phân tích hình ảnh thông minh. Giải pháp được triển khai trong nhiều lĩnh vực như giáo dục, y tế, giao thông và khu vực công cộng; giúp nâng cao hiệu quả quản lý và đảm bảo an ninh một cách linh hoạt, hiện đại.\n\nMô Tả Công Việc\n\n• Tham gia phát triển các mô hình AI theo sự phân công của Trưởng bộ phận và Leader\n• Tham gia phát triển hệ thống Camera AI phục vụ các bài toán nhận diện, định danh người và các bài toán xử lý hình ảnh khác.\n• Tham gia trực kĩ thuật vận hành các dịch vụ CMC TS đang cung cấp, giải quyết sự cố do vận hành, deploy code cùng với MLOps.\n• Lên kế hoạch bảo trì, nâng cấp các dịch vụ Computer vision về quy mô cũng như tính sẵn sàng của dịch vụ.\n• Tham gia triển khai trực tiếp giải pháp của CMC TS cho khách hàng trong một số trường hợp đặc biệt được yêu cầu.\n\nYêu Cầu Chuyên Môn\n\n• Tốt nghiệp chuyên ngành liên quan: Công nghệ thông tin, điện tử viễn thông, tự động hóa, khoa học máy tính.\n• Có từ 5 năm kinh nghiệm về xây dựng AI Model và Finetune Model.\n• Có kinh nghiệm thực tế về lập trình AI trên các thiết bị Mainboard như Jetson Devices, Raspberry Pi.\n• Làm việc thành thạo với các giao thức TCP/IP, MQTT, HTTP…\n• Đọc, hiểu tài liệu kỹ thuật tốt.\n• Chủ động, sáng tạo, nhiệt tình và có trách nhiệm trong công việc.\n• Có khả năng lắng nghe, kiên trì học hỏi, cẩn thận và tỉ mỉ\n• Sẵn sàng làm việc ngoài giờ trong những giai đoạn dự án cao điểm (không thường xuyên)\n• Có khả năng làm việc độc lập và làm việc theo nhóm.\n\nƯu Tiên (nice To Have)\n\n• Đã từng tham gia phát triển Face Detection và Face Recognition\n• Có kinh nghiệm phát triển đa dạng mô hình về Computer Vision\n• Có kinh nghiệm về việc đưa model AI xuống Mobile Devices\n• Có kiến thức về lập trình AI trên các dòng chip ARM, Hisilicon, Rockchip\n\nQUYỀN LỢI ỨNG VIÊN\n\nThu Nhập\n\n• Lương tháng cạnh tranh tùy vào năng lực\n• Thu nhập lên tới 15 tháng lương/năm (bao gồm lương và thưởng KPI cá nhân)\n• Thưởng năng suất cộng thêm theo kết quả kinh doanh Công ty\n• Gói phúc lợi Lễ, Tết, Sinh nhật Tập đoàn 9 triệu/năm\n• Xét tăng lương định kỳ 1 lần/năm. Hoặc tăng lương đột xuất theo thành tích cá nhân\n\nĐÀO TẠO VÀ PHÁT TRIỂN\n\n• Đài thọ 100% chi phí tham gia các khóa học, thi chứng chỉ CNTT Quốc tế.\n• Chính sách phát triển, thăng tiến theo Career Path có lộ trình với từng vị trí, từng phòng ban.\n• Cơ hội tiếp cận với các công nghệ mới nhất: Cloud, Big Data...\n• Cơ hội làm việc trong Công ty là Top 1 đối tác tư vấn và cung cấp, triển khai giải pháp Chuyển đổi số, Bảo mật, Cloud cho tổ chức và doanh nghiệp tại Việt Nam\n\nĐÃI NGỘ VÀ VĂN HÓA\n\n• Thời gian làm việc: Thứ Hai – Thứ Sáu; Nghỉ thứ 7 & Chủ Nhật.\n• Nghỉ phép: 12 ngày/ năm + 1 ngày nghỉ hưởng lương vào dịp sinh nhật bản thân CBNV\n• Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n• Chế độ bảo hiểm nâng cao: CMC Care\n• Chế độ đãi ngộ thai sản nâng cao dành cho nhân viên nữ\n• Du lịch hàng năm 1 tuần, teambuilding/dã ngoại định kì 2 lần/năm\n• Tham gia các Câu lạc bộ của Công ty và các chương trình trải nghiệm nhân viên đa dạng và phong phú\n• Môi trường làm việc sáng tạo, đổi mới dựa trên 5 giá trị cốt lõi là 5C (C-Speed, Creativity, Commitment, Customer Centricity, Positive Thinking &“Can-do” Attitude).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1898, 326, 2, 'Android Engineer (Kotlin)', 'YOUR NEW ROLE CODE LEAP\n\nWe are looking for an Android Engineer (Kotlin) to join our expert team in Ho Chi Minh City. This role is perfect for team players with a strong interest in developing their international career - not just as a coder, but as a product builder.\n\nYOUR EXCITING TASKS\n\n- Build enterprise-grade Android mobile applications tailored for the German B2B market and continuously improve them to bring products to the next level.\n- Translate UI/UX designs and technical documentation into high-quality, functional code while meeting project deadlines.\n- Produce optimized, reusable, and maintainable code following Android development best practices.\n- Work closely with UI/UX designers, iOS developers, backend engineers, and project managers to ensure smooth development and timely delivery.\n- Focus on performance, scalability, and responsiveness to deliver a seamless user experience.\n- Analyze, identify, and fix complex bugs to deliver reliable and robust solutions.\n- Review code, provide constructive feedback, and identify potential issues to maintain code quality and consistency.\n- Actively share ideas, propose improvements, and provide technical solutions to enhance product quality and performance.\n\nYOUR PROFILE AND YOUR PERSONALITY\n\n- 3–5 years of hands-on experience in Native Android development.\n- Deep understanding of UI/UX best practices for Android.\n- Experience with RESTful APIs and third-party libraries, along with experience working with databases and local storage.\n- Knowledge of reactive programming patterns and experience with libraries such as Kotlin Coroutines.\n- Familiarity with Android architecture patterns (e.g., MVVM, MVP) and a strong grasp of modular and clean architecture principles.\n- Experience with CI/CD practices, test automation, and performance profiling.\n- Experience with analytics and logging tools, such as Datadog, Firebase, or similar, to monitor app performance and user behavior.\n- Experience with Android Jetpack components and libraries, including Navigation, LiveData, and ViewModel.\n- Knowledge of privacy and security best practices in Android application development.\n- Familiarity with cloud platforms and services such as AWS or Firebase for app integration\n- You understand and know how to prioritize your tasks with a problem-solving mindset.\n- You don\'t take things personally and are comfortable with ambiguity and rapid changes common in early-stage product development.\n- You don\'t wait for others to tell you what you need to do but proactively reach out to people, communicate, ask for help, and get things done.\n- You are proficient in communicating in the English language.\n\nNice to have:\n\n- Android Automotive, Android Auto\n- Experience in cross-platform development using Flutter or React-native.\n- Experience in an Audio application domain\n\nBenefits Await You At Code Leap\n\n- Competitive salary and beneﬁts\n- Year-end bonus (13th-month salary)\n- Generous annual leave of up to 18 days\n- Enjoy a stress-free and comfortable commute to and from work with our Grab Services sponsor\n- Enjoy an endless selection of delicious refreshments, including gourmet coffee, beverages, snacks, and fresh fruits, all complimentary\n- Focused on individual development:\n  - Unlimited access to Udemy and other recommendation courses\n  - Sponsored Professional certificates such as AWS, PMI, Scrum Master, etc\n  - Sharing session every Friday, come along with lunch provided by CODE LEAP\n  - 1-on-1 coaching with experienced professionals\n- Flexible work policy, which provides flexible hours to accommodate personal schedules and commitments\n- Dynamic, fun, and agile environment, perfect for sharing and creativity\n- Open-minded, kind & humble colleagues\n\nCONTACT\n\nPlease reach out and contact us now with your latest CV as well as a little description of yourself at jobs@codeleap.de.\n\nAbout Us\n\nWith our expert teams spread across two continents, CODE LEAP provides innovative software solutions for venture-backed companies and leading enterprise businesses in Germany. Our teams in Germany and Ho Chi Minh City (Vietnam) work hand in hand to develop state-of-the-art solutions of the highest quality.\n\nBecause collaborating with the right people is the secret to our successful growth.\n\nWe future-proof organizations - be part of it!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1899, 1033, 2, 'Game Designer', 'Địa điểm làm việc: Phòng 401 – 402, số 23 Duy Tân, Dịch Vọng Hậu, Cầu Giấy, Hà Nội.\nThời gian làm việc: 09h00 - 18h00 từ Thứ 2 - Thứ 6, không OT.\n\nDescribe:\n- Lên ý tưởng, thiết kế và tạo tài liệu chi tiết kịch bản game.\n- Cùng làm việc với các bộ phận trong dự án để đảm bảo tiến độ và chất - lượng cho sự phát triển các tính năng và event cho các game.\n- Theo dõi chỉ số, phân tích và đưa ra các action phù hợp giai đoạn dự án.\n- Xây dựng game story phù hợp với mục tiêu sản phẩm.\n\nRequirement:\n- Chúng mình đang tìm kiếm 2 vị trí Game Designer cho 2 dòng Game RPG và Puzzle. Tối thiểu 6 tháng- 1 năm kinh nghiệm, có sản phẩm GDD hoặc sản phẩm đã lên store. Dòng Game Midcore/RPG và Hybrid/Casual\n- Có hiểu biết về các yếu tố khi thiết kế game như Fun factors, User motivation, core lopp, progression..\n- Ưu tiên ứng viên có hiểu biết về phân tích dữ liệu và economic, monetization trong Game IAP\n- Có kinh nghiệm phát triển tối thiểu 1 tựa Game RPG hoặc 1 tựa Game Puzzle là một lợi thế\n- Yêu thích chơi game, mong muốn phát triển sự nghiệp trong ngành game\n- Ham học hỏi, có tư duy phát triển, cải tiến công việc\n- Cởi mở, chủ động giao tiếp, tương tác và kết hợp công việc với đồng đội.\n\nBenefits:\n- Lương: Salary upto $1000 + Thương dự án. Thử việc hưởng 100% lương. Phụ cấp ăn trưa, gửi xe\n- Nghỉ phép hưởng nguyên lương 12 ngày/ năm.\n- Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.\n- Cung cấp trang thiết bị đầy đủ để phục vụ công việc\n- Thưởng cuối năm (T13,14,15…) theo doanh thu của công ty và nhiều hình thức thưởng hấp dẫn khác (Thưởng ý tưởng, nhân viên xuất sắc, thưởng dự án, thưởng sinh nhật, thích là thưởng ...)\n- Văn hóa cho phép phát huy tối đa khả năng và tính sáng tạo của nhân sự\n- Được tham gia các buổi đào tạo, training, workshop nâng cao năng lực, kiến thức, cơ hội phát triển, tăng cấp bậc thường niên.\n- Các chuyến du lịch, teambuilding hấp dẫn hàng tháng, hàng năm trong hoặc ngoài nước.\n\nCác bạn quan tâm vui lòng gửi CV ứng tuyển\nEmail: tuyendung@gameestudio.com - Tiêu đề [Họ tên - Vị trí ứng tuyển]\nHotline/zalo:0867624995 (Ms.Ngọc Nguyễn)\nWebsite: https://gameestudio.com/\nFanpage: https://www.facebook.com/gameeglobal/\nLinkedin: https://www.linkedin.com/company/gamee-studio/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1900, 1026, 2, 'Data Engineer (Talend)', 'CEVA Logistics provides global supply chain solutions to connect people, products and providers all around the world. Present in 170 countries and with more than 110,000 employees spread over 1,500 sites, we are well on our way to achieving our vision: to be a Top 5 global 3PL.\n\nWe believe that our employees are the key to our success. We want to engage and empower our diverse, global team to co-create value with our customers through our solutions in contract logistics and air, ocean, ground, and finished vehicle transport. That is why CEVA Logistics offers a dynamic and exceptional work environment that fosters personal growth, innovation, and continuous improvement.\n\nCESA Vietnam was founded in 2018; CESA started as a development center in Vietnam, then now became a technology company of CEVA Logistic, specializing in Microsoft .Net technologies (ASP.Net MVC, API, Azure,...), ESB platform (Webmethods, Java...) and delivers projects using Agile methodology.\n\nWorking with us, you’ll have the opportunity to develop your skills and career in an exciting workplace in touch with an international and innovative environment.\n\nDARE TO GROW! Join CESA Vietnam / CEVA Logistics, and you will be part of a team that values imagination, encourages boldness and exemplarity, and is committed to excellence in everything we do. Join us in our mission to shape the future of global logistics as we become a global leader in the logistics industry. As we continue growing at a fast pace, will you “Dare to Grow” with us?\n\nMain tasks and activities:\nThe Talend developer participates in designing and developing, implementing data integration solutions with Talend platform, which addresses data’s needs and monitors data flow smoothly. \n\nThe main duties will include but not be limited to:\n- Design, develop, test, and implement data integration solutions to ensure high quality, performance, and scalability.\n- Understand data integration requirements to create and maintain technical solutions for all development and integration processes.\n- Perform unit testing and system testing to identify and address any issues early.\n- Troubleshoot and resolve defects and performance bottlenecks.\n- Optimize data integration workflows for maximum efficiency and minimal processing time.\n- Collaborate with cross-functional teams to ensure seamless data flow and integration across systems.\n\nReporting line\n- Report to leader and manager in Vietnam and France.\n\nEducational background\n- Graduate in Computer Science, Information Technology, or a related field.\n\nTechnical skills\n- Strong understanding of data integration concepts and ETL processes\n- Develop and maintain robust ETL (Extract, Transform, Load) pipelines to process data from various sources, ensuring high-quality, consistent, and accurate data.\n- Have experience in any of data integration tools such as Talend, SSIS, IBM DataStage, Oracle ODI, etc.\n- Good understanding and hand-on experience in SQL or NoSQL databases.\n- Familiar with different data formats and protocols (e.g., CSV, JSON, XML, REST, SOAP).\n- Good understanding and familiar with source version control.\n\nAdvantageous to have:\n- Familiar with data warehousing concepts and tools.\n- Experience with Big Data & Cloud integration (e.g., AWS, Azure, Google Cloud).\n- Relevant certifications in Talend or data integration technologies.\n\nSoft skills\n- Have good logical and analytical thinking with attention to detail.\n- Strong problem-solving skills \n- Reliable and comfortable to collaborate in team \n- Strong learning capabilities both for technical and functional aspects\n\nLanguage\n- Proficiency in English (written and spoken)\n\nPay range: up to $2000\n\nOffice: Etown 2, 364 Cong Hoa, ward 13, Tan Binh Dist, Ho Chi Minh City, Vietnam\n\nBenefits\n- Being a pioneer in contributing to team development with a long-term vision\n- High-ownership working environment: You will take full responsibility and control of your missions, contributing to the team\'s success in a daily collaboration with Paris teams\n- Continuous skill improvement with new technologies, challenging projects, on-the-job coaching, knowledge exchange with technical experts, and training programs (locally and in Paris)\n- Annual performance review: recognize your efforts and identify development/ improvement needs\n- Be secure in your mind with employee care: private healthcare insurance package, medical check-ups, allowance support...\n- Great-place-to-work activities (company trips, sport clubs...): enhance teamwork spirit and facilitate your work-life balance\n- Opportunity to participate in global events (Hackathon, Seminar, Innovation Factory...)\n\nCESA Vietnam/ CEVA Logistics is proud to be an equal opportunity work place and an affirmative action employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, gender, gender identity or expression, sexual orientation, national origin, genetics, disability, age, veteran status or any other characteristic. We are an Equal Opportunity Employer of Minorities, Females, Protected Veterans, and Individual with Disabilities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Tân Bình, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1901, 702, 2, 'Senior Java Engineer (Recommendation & Search)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nDive into the world of AI-powered, data-driven innovation with our Big Data team at Binance! We\'re transforming massive datasets into actionable insights, enhancing personalized experiences, ensuring regulatory compliance, and supporting global operations. If you\'re passionate about shaping the future of AI and analytics, join us and make a significant impact with forward-thinking solutions.\n\nIf you’re looking for a fast-paced, mission-driven organization where opportunities to learn and excel are endless, then Binance is the place for you.\n\nResponsibilities\n\nDesign and develop microservices architecture using Java Spring Boot, ensuring system performance, scalability, and reliability. Implement and manage microservices components such as service discovery, configuration management, and load balancing with Spring Cloud. Analyze, process, and explore data using big data technologies. Optimize and manage data storage and retrieval systems like ES/HBase ensuring efficient data handling. Work closely with business stakeholders to understand requirements and deliver data solutions that align with business goals. Monitor, troubleshoot, and improve backend services to ensure smooth operation. Participate in the full development lifecycle, including requirements gathering, system design, coding, testing, and deployment. Maintain and enhance existing backend services, ensuring code quality and performance. Collaborate with cross-functional teams to integrate data solutions into existing applications.\n\nRequirements\n\nBachelor\'s or Master’s degree in Computer Science, Engineering, or a related field. 8 years of professional experience in Java development, with a minimum of 3 years focused on Spring Boot microservices. Expertise in designing and implementing Java Spring-based microservices architecture, with experience in Spring Cloud. Hands-on experience with data development and big data technologies, including Hive, Spark and Flink Familiar with and proficient in using components such as Apollo Configuration Center, Kafka Message Middleware, Xxl Job Scheduler, Pinpoint Link Tracking, and Prometheus Monitoring. Proficient in optimizing and managing large-scale databases and data processing workflows. Strong problem-solving skills, with a proven ability to troubleshoot and optimize backend services. Excellent communication and teamwork skills, with the ability to work in a cross-functional environment. Experience with CI/CD pipelines, such as Jenkins or GitLab CI, is a plus. Knowledge of cloud services like AWS or is a plus. Strong knowledge of financial or blockchain business models and processes, is a plus.\n\nWhy Binance\n\nShape the future with the world’s leading blockchain ecosystem Collaborate with world-class talent in a user-centric global organization with a flat structure Tackle unique, fast-paced projects with autonomy in an innovative environment Thrive in a results-driven workplace with opportunities for career growth and continuous learning Competitive salary and company benefits Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team) Binance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1902, 820, 2, 'Senior Java Developer', 'MÔ TẢ CÔNG VIỆC\n\nPhát triển và maintain các hệ thống của KH trên mô hình Spring MVC, Spring boot\n\nHiểu biết về hệ quản trị dữ liệu: Oralce và Posgres.\n\nPhát triển các task do PM/Team lead assign.\n\nCó kỹ năng làm tài liệu: DB Design, API design, Screen design, basic design.\n\nTeamwork tốt.\n\nNice too have : kinh nghiệm về cloud, deploy\n\nSẵn sàng OT nếu cần.\n\nYÊU CẦU\n\nCó thể làm basic design - detail design - DB design cho hệ thống\n\nCó kinh nghiệm làm việc với các service của AWS: SES, Lambda, monitor log cloud watch, xử lý file trên cloud, ...\n\nCó kinh nghiệm làm việc với Elastic Search\n\nCó kinh nghiệm làm việc với Rabbit and queue, redis\n\nCó kinh nghiệm review tối ưu performance cho source code - tuning SQL\n\nCó hiểu biết clean code, biết ứng dụng vào review.\n\nĐã từng sử dụng các plugin phục vụ check - review code: Spotbug - check style\n\nCó hiểu biết về unit test (Junit) và perfomance test (Jmetter) -› Biết cách triển khai cho team.\n\nCó hiểu biết về CICD (jenkins - docker - git pipeline)\n\nCó thể tự đưa ra GitFlow cho dự án và vận hành nó.\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 28 tháng 6, 2025\n\nChi tiết công việc\n\nSố Lượng\n\n1\n\nĐịa Điểm\n\nHà Nội\n\nKinh Nghiệm\n\n4 năm\n\nTrình Độ\n\nSenior\n\nHình Thức\n\nToàn thời gian\n\nKỹ Năng\n\nJava', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1903, 297, 2, 'Fullstack Developer (Python, ReactJS)', 'We are looking for a Fullstack Web Developer with a strong emphasis on backend development using Python and hands-on experience in AI/LLM integration. This role is ideal for someone passionate about building scalable, high-performance web systems, with deep expertise in API design, cloud infrastructure, database architecture, and modern security practices. While frontend experience with ReactJS (or similar frameworks) is required, the focus of this role is on backend engineering and delivering solutions powered by AI technologies.\n\nLocation: Ho Chi Minh, Da Nang, Hanoi\n\nWhat You\'ll Be Doing\n\n- Working on Web and Mobile products for a diverse range of clients and industries\n- Working and pair programming with other developers to build applications with Python and ReactJS\n- Designing & implementing back-end API using Python\n- Working with the Product Owner to convert business requirements into technical designs\n- Cooperating with the UI Designer to implement modern minimalist designs into production\n- Applying proven technologies and best practices to level up your technical skills: NestJS, Redux\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment\n\nRequirements\n\nMust have\n\n- 5+ years of experience in backend development using Python\n- 3+ years of experience in frontend development using ReactJS or similar frameworks (Vue, Svelte, Angular)\n- Proven expertise in designing and implementing RESTful APIs, scalable web architecture, and deploying to cloud platforms (AWS, GCP, or Azure)\n- Hands-on experience with Python for backend development; experience integrating AI/ML solutions into web applications is a strong plus\n- Strong working knowledge of relational databases and NoSQL (e.g., MySQL, PostgreSQL, SQL Server, MongoDB ...)\n- Familiarity with Extreme Programming (XP) practices such as Test-Driven Development (TDD), Continuous Integration (CI), and code refactoring\n- Familiar with event-driven tech and message brokers (Kafka, RabbitMQ...)\n- Experienced with micro services and data-intensive applications\n- Experience working within Agile/Scrum teams\n- Excellent English communication skills, both written and verbal\n\nNice to have\n\n- Experience with NodeJS and Golang \n- Experience with serverless architecture, e.g., AWS Lambda, GCP Cloud Function, etc\n- Experience with data security, performance, and scalability\n- Experience integrating LLMs (e.g., OpenAI, Hugging Face) into production applications\n\nBenefits\n\n- Three days remote every week and four full remote weeks per year\n- Gold level Health Insurance coverage from Bao Viet Insurance, a yearly complete Health Check and social insurance\n- All office benefits and full salary during probation\n- Flexible working time starting anytime up to 10 AM working Monday - Friday with no overtime and a long lunch break\n- Allowance for everything: meals, parking, petrol, along with unlimited snacks and nice coffee every day\n- Choose from a brand-new Mac or PC device\n- Salary review twice a year with opportunities for promotions and spot awards\n- 12 days annual leave per year, with all days not taken paid out in cash, plus 2 sick leave days.\n- Yearly Training Budget up to 5 million VND per staff. On top of that, Professional coaching program, buddy system, tech talks, agile sessions, and 1on1 private English classes are available\n- Yearly company trip, monthly activities, and other Celebrations for special days in the year, such as Women\'s Day, YEP, and Christmas\n- Employee-led clubs within the company; games teams, sports teams, etc\n- Modern open-space office with comfortable workspace, a PS4 games room, and chill-out areas', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1904, 274, 2, 'Automation QC Engineer (Junior / Middle)', 'Key Contributions\nUnderstand the product & testing process to implement all testing activities effectively\nWork on daily assignments\nDesign, develop, and maintain automated test scripts and test frameworks\nIdentify, document, and track bugs; work closely with developers to resolve issues\nParticipate in code and test case reviews to ensure high quality and adherence to standards\nContinuously improve test coverage, automation, and overall QA processes\nSupport test documentation: create and maintain test plans, test cases, and test reports\nAssist with integration testing, system testing, and regression testing\nContribute to the full circle of development to successfully deliver output\nHandle other testing-relevant tasks assigned by the leader\n\nKey Ingredients for Success\nBachelor’s Degree in Computer Science / Information Technology / Software Development or related fields\n\nMust have:\n2-5 years of experience in Automation Testing for Web/Mobile Applications/Devices\nSolid programming skills and knowledge of data structures, proficient in at least one language in Java/C/C++/C#, familiar with commonly used automation testing frameworks\nFamiliar with at least one database in MySQL/SQL Server/PostgreSQL/Oracle\nUnderstand the industry trends of software testing and be familiar with common software testing methodologies. Have a deep understanding of design patterns, microservice architecture, etc\nGood/Fluent English communication is mandatory\nHigh competence in end-user mindset, problem solving and stakeholder management\n\nLife at Floating Cube Studios\nWe are a multinational, product-driven company specializing in proprietary POS solutions — developing in-house and delivering directly to our worldwide customers.\n\nBenefits\nRecognition & Rewards:\n13th-month salary\nLoyalty Bonus programs\nBiannual Performance and Salary review\nComprehensive Insurance Coverage:\nFull government public insurance contributions based on gross salary\nPremium health insurance\nAnnual health check\nClear career development and growth structure; Training sessions and Learning workshops\n14 days of annual leave and one additional day of leave for every year of service\nLaptop/MacBook and top-notch facilities are provided based on each role\nAgile/Scrum-based internal workflows for efficient and collaborative development\nCompany trips, parties and regular team-building activities; Weekly happy hour, coffee, snacks, and board games\nOverseas travel opportunities based on the individual performance and policies for each evaluation period\n\nWorking Environment & Culture\nInternational Workplace: English-speaking environment\nPositive and Open-Minded Culture: Engineers are encouraged to propose innovative solutions that enhance productivity and code quality\n1-on-1 Mentorship: Monthly coffee sessions with managers offer personalized feedback, goal setting, and career development opportunities\nFlexible Working Hours: Promote work-life balance and individual productivity', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1905, 958, 2, 'AI Engineer', 'ABOUT ONE MOUNT\nOne Mount is Vietnam’s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam’s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nMAIN RESPONSIBILITIES\nWe are seeking highly skilled AI Engineers to enhance our product team. This position focuses on developing and implementing AI and data solutions within the real estate domain.\n\nBuild Data Pipelines: You\'ll directly build pipelines for collecting, processing, and standardizing real estate data (listings, transactions, legal documents, images, maps, etc.).\nDevelop Automated Valuation Models (AVM): Develop real estate valuation models based on big data.\nOptimize Search & Recommendation Engines: Enhance search and product recommendation tools using Recommender Systems and NLP (Natural Language Processing) algorithms.\nIntegrate AI into Products: Collaborate with software architects, GIS, backend, and product teams to integrate AI models into real-world products.\nImplement & Improve ML Ops: Deploy, monitor, and continuously improve machine learning models in a production environment (ML Ops).\n\nREQUIRED EXPERIENCE AND SKILLS\nGraduated with a degree in Computer Science, Mathematics, AI, or equivalent fields.\nMinimum of 2 years of practical experience in deploying ML/AI models.\nProficient in Python and related libraries: Pandas, Scikit-learn, XGBoost, PyTorch/TensorFlow.\nExperienced with ETL systems, crawling, and big data processing.\nFamiliar with database systems: SQL & NoSQL (PostgreSQL, MongoDB, Elastic, BigQuery...).\nExperience API-izing models and deploying machine learning models to the Cloud (GCP/AWS preferred).\nExperience in PropTech, FinTech, AdTech platforms or data-driven products.\nExperience processing digital map data (Geospatial, GIS, Google Maps, Mapbox...).\nKnowledge of real estate, finance, investment, or online user behavior.\nLogical thinking, ability to work in a fast-paced environment, and not afraid to experiment.\n\nBENEFITS AND PERKS\nSalary & Allowances\n13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\nLunch allowance: 730.000 VND/month\nSpecial occasion bonus: 2.500.000VND/year\nAnnual leaves: Up to 20 days/year (based on levels)\nHealth: Social insurance, premium health insurance, yearly health check\nLaptop, screen and other needed facilities/accounts/tools for work\nCareer Growth\nYearly salary review and promotion\nDiverse career path: Management or Expert and functions rotation opportunity\nFree learning sources in Udemy, Coursera, O’Reilly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\nRecognition and awards at team and organizational levels.\nGrow your career with opportunities across the dynamic ecosystem of Techcombank & Masterise Group.\nAccess special loan offers with competitive interest rates and flexible grace period options tailored to your financial needs.\nWorking Environment\nOpen & collaborative working space fosters both individual focus and teamwork activities\nYoung, dynamic, and collaborative working atmosphere\nUnwind zones: gaming, table tennis, yoga, gyms, bath rooms.\nPersonal lockers with QR code access.\nQuarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1906, 1034, 2, 'Blockchain Security Technical Support Engineer', 'At Crypto.com, our dedication to user security is led by our highly experienced Security Team. Comprising an international roster of seasoned cybersecurity experts, our team leads the company\'s Security, Privacy, and Security Compliance endeavors. \n\nThe team includes holders of international patents for technologies integrated in our security architecture. Under the stewardship of a distinguished CISO recognized by the Forbes Technology Council and among the Global Top 100 CISOs, our team has consistently championed industry standards, acquiring certifications like ISO27001, ISO27701, ISO22301, PCI:DSS 3.2.1 (Level 1), NIST Tier 4, and SOC 2 Type II, in addition to the MPI License from Singapore MAS. Our Chief Information Security Officer reports directly to the CEO, underscoring the prioritization of security in our organization\'s hierarchy. \n\nOur Security Team not only places great emphasis on credentials and expertise but also deeply values hands-on experience, rapid cognition, and dynamic learning. The challenges in the world of crypto are ever-evolving, and as such, our team prides itself on quick adaptability and robust teamwork, ensuring that we stay ahead of potential threats and always safeguard our user base.\n\nWe are looking for someone who is enthusiastic about Web3 and blockchain technology. The individual must have hands-on experience in writing smart contracts (DApps) and ideally experience staking on various blockchain networks. The individual will be the go-to person by the wider crypto.com team as an the in the blockchain network. It is a norm in our industry, new blockchains being created/introduced on a weekly basis, the individual is expected to research and understand technically how the new blockchain works and the various features for wallet integration.  \n\nThe roles will require individuals to have a strong knowledge of blockchain from a practical usage perspective specifically in the smart contract (DApps) and staking. In the early phase, the individual will spend more time supporting the Solana ecosystem but it will be expanded to others like Cronos/Cronos zkEVM.  \n\nResponsibilities\nUnderstand DApss and ability to deploy/maintain/monitor smart contracts in Solana/EVM\nDevelop an understanding of all supported blockchain and an in-depth knowledge of a select few blockchains\nResearch on new blockchain supported by the organization\nStay up to date with software upgrades and other critical blockchain changes\nShare (verbal/written) blockchain/DApps knowledge with internal teams including Engineers, DevOps, Sales, Product Manager and Customer Success team\nTroubleshoot and triage blockchain specific alerts and issues\n\nRequirements\nStrong client service in a fast paced, high pressure, and dynamic environments\nPast job experiences in supporting applications in 24/7 environment\nGood knowledge of blockchain and its ecosystem and how protocols  interact with each other and DApss\nHands-on experience in running blockchain nodes, writing smart contracts (DApps), staking, governance, bridges\nKnowledge in programming languages such as Rust, Solidity, Javascript, Node.js, Python\nExperience owning technical documentation\nAttention to detail with an analytical mindset\nAdaptive to varying work condition\nGood communication skills in English both written and verbal\n\nLife @ Crypto.com\nEmpowered to think big. Try new opportunities while working with a talented, ambitious and supportive team.\nTransformational and proactive working environment. Elevate employees to find thoughtful and innovative solutions.\nGrowth from within. We help to develop new skill-sets that would impact the shaping of your personal and professional growth.\nWork Culture. Our colleagues are some of the best in the industry; we are all here to help and support one another.\nOne cohesive team. Engage stakeholders to achieve our ultimate goal - Cryptocurrency in every wallet.  \n\nAre you ready to kickstart your future with us?  \n\nBenefits\nCompetitive salary  \nMedical insurance package with extended coverage to dependents  \nAttractive annual leave entitlement including: birthday, work anniversary\nWork Flexibility Adoption. Flexi-work hour and hybrid or remote set-up\nAspire career alternatives through us. Our internal mobility program can offer employees a diverse scope.  \nWork Perks: crypto.com visa card provided upon joining  \nOur Crypto.com benefits packages vary depending on region requirements, you can learn more from our talent acquisition team.\n\nAbout Crypto.com:\nFounded in 2016, Crypto.com serves more than 80 million customers and is the world\'s fastest growing global cryptocurrency platform. Our vision is simple: Cryptocurrency in Every Wallet™. Built on a foundation of security, privacy, and compliance, Crypto.com is committed to accelerating the adoption of cryptocurrency through innovation and empowering the next generation of builders, creators, and entrepreneurs to develop a fairer and more equitable digital ecosystem.\n\nCrypto.com is an equal opportunities employer and we are committed to creating an environment where opportunities are presented to everyone in a fair and transparent way. Crypto.com values diversity and inclusion, seeking candidates with a variety of backgrounds, perspectives, and skills that complement and strengthen our team.\n\nPersonal data provided by applicants will be used for recruitment purposes only.\nPlease note that only shortlisted candidates will be contacted.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1907, 370, 2, 'Software Engineer (C#)', 'FORTNA partners with the world’s leading brands to transform omnichannel and parcel distribution operations. Known world-wide for enabling companies to keep pace with digital disruption and growth objectives, we design and deliver solutions, powered by intelligent software, to optimize fast, accurate and cost-effective order fulfillment and last mile delivery. Our people, innovative approach and proprietary algorithms and tools ensure optimal operations design and material and information flow. We deliver exceptional value every day to our customers with comprehensive services and products including network strategy, distribution center operational design and implementation, material handling automated equipment, robotics and a comprehensive suite of lifecycle services.\n\nAt FORTNA, we believe in fostering a workplace that isn\'t just a job but a movement – a collective effort to redefine success and transform challenges into opportunities. "Join the Movement" encapsulates our commitment to a workplace culture that thrives on collaboration, celebrates diversity, and empowers every individual to contribute to something greater than themselves. Our Team. Our Passion. Our Approach.\n\nAs a Software Engineer at FORTNA, you will join our Engineering Application Development Team—a multidisciplinary group of professionals based in Vietnam, The Netherlands, and the United States. This team is responsible for managing, supporting, and developing innovative engineering applications used internally at FORTNA. Among these is Emulate3D, a 3D design tool used to design automated transport systems for the Parcel and D&F industries. This tool is constantly evolving to meet the growing needs of the business.\n\nPrimary Responsibilities\n\n- Develop advanced, configurable 3D models within the Emulate3D platform, utilizing C# programming in Visual Studio.\n- Interpret engineering data and translate it into programmable engineering rules to enhance application functionality.\n- Design and develop software tools that extend the Emulate3D platform, including:\n    - Building intuitive and responsive user interfaces using WPF.\n    - Interacting with SQL databases for data management.\n    - Creating seamless integrations and interfaces with other software applications.\n- Provide ongoing user support.\n- Collaborate with a small, dynamic software development team consisting of mechanical and software engineers based in The Netherlands and Vietnam.\n- Work closely with the product owner and business representatives to refine designs and align development efforts with business needs.\n\nRequired Qualifications\n\n- Bachelor’s degree in mechanical engineering, Computer Science, or a related field.\n- A minimum of 3 years of professional experience in a technical or software-oriented organization.\n- Strong interest in both engineering and programming.\n- Extensive programming experience, with a preference for proficiency in C#.\n- Familiarity with version control systems such as Git.\n- Proficiency in English, with excellent oral and written communication skills.\n- Strong interpersonal, organizational, time management and problem-solving skills.\n- Flexibility to occasionally work shifted hours, particularly during the initial training period.\n- Previous experience with Emulate3D is welcome, but not required.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1908, 767, 2, 'Unity Game Developer - MINTROCKET', 'Mô tả công việc\n\n- Develop game content using the Unity engine\n- Develop tools necessary for game production and collaboration\n\nYêu cầu công việc\n\nQualifications\n\n- Experience in game development using the Unity engine\n\nGeneral Competencies\n\n- Passion and dedication for game development\n- Ability to read, write, and communicate in English\n- Positive mindset and proactive communication skills\n- Strong sense of responsibility for assigned tasks\n- Logical thinking and creative problem-solving skills\n\nJob-Specific Skills\n\n- Proficiency in C# programming\n- Understanding of 2D/3D programming\n- Knowledge and implementation of data structures and algorithms\n\nPreferred Qualifications\n\n- Understanding of game physics and mathematics\n- Experience in client profiling and optimization', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 7, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1909, 767, 2, 'MMORPG Server Developer (Games)', 'Job Description ( Mô Tả Công Việc)\n\n- Development of MMORPG game servers\n- Development of game service operation environments and tool\n\nGeneral Competencies ( Yêu cầu năng lực chung)\n\n- Passion and dedication to game development\n- Positive attitude and proactive communication skills\n- Strong sense of responsibility for assigned tasks\n- Logical thinking and creative problem-solving abilities\n\nJob-Specific Skills (Kỹ năng chuyên môn cho công việc)\n\n- Understanding and implementation of object-oriented programming\n- Understanding and implementation of multithreaded programming\n- Understanding and implementation of network programming\n- Database schema design and procedure implementation skills\n- Understanding and implementation of various data structures and algorithms\n\nPreferred Qualifications (Kỹ Năng Ưu Tiên)\n\n- Experience in online game server development\n- Experience using commercial server engines\n- Experience in development within Linux environments', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 7, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1910, 702, 2, 'Binance Accelarator Program - Devops Engineer', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nAbout Binance Accelerator Program\n\nBinance Accelerator Program is a concise fixed-term program designed for Early Career Talent to have an immersive experience in the rapidly expanding Web3 space. You will be given the opportunity to experience life at Binance and understand what goes on behind the scenes of the worlds’ leading blockchain ecosystem. Alongside your job, there will also be a focus on networking and development, which will expand your professional network and build transferable skills to propel you forward in your career. Learn about BAP Program HERE\n\nWho May Apply\n\nCurrent university students and recent graduates\n\nWe are seeking a DevOps intern to support our real-time data streaming needs. The ideal candidate will have basic knowledge of Apache Kafka and a keen interest in building and maintaining operation pipelines. This role will involve working with senior engineers to ensure our Kafka infrastructure is robust and efficient\n\nResponsibilities:\n- Assist in the installation, configuration, and maintenance of Kafka clusters.\n- Monitor Kafka performance metrics and troubleshoot issues.\n- Support the development and maintenance of Kafka-based data pipelines.\n- Work with development teams to integrate Kafka into applications.\n- Help maintain documentation for Kafka configurations and procedures.\n- Participate in debugging and resolving Kafka-related problems.\n- Stay informed about Kafka updates and industry best practices.\n\nRequirements:\n- Basic understanding of Apache Kafka and its components (brokers, topics, producers, consumers).\n- Familiarity with distributed systems and real-time data processing concepts.\n- Basic knowledge of Linux operating systems and scripting languages.\n- Understanding of network protocols and data serialization formats (e.g., Avro, JSON).\n- Strong analytical and troubleshooting skills.\n- Good communication skills and ability to collaborate effectively with team members.\n- Eagerness to learn and grow in the field of data streaming and messaging systems.\n\nWhy Binance\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1911, 895, 2, 'Chuyên viên Quản trị hệ thống phần mềm', 'Mô tả công việc\n\nTriển khai, vận hành hệ thống ứng dụng phần mềm core giao dịch chứng khoán và các hệ thống phần mềm khác;\nPhân tích nhu cầu và tư vấn khai thác dữ liệu tới các đơn vị/bộ phận nghiệp vụ; chuyển hóa các yêu cầu nghiệp vụ thành các yêu cầu về dữ liệu, hệ thống và xây dựng công cụ hỗ trợ khai thác dữ liệu; phối hợp với các đơn vị phát triển, đưa ra kiến trúc khai thác dữ liệu để cung cấp sản phẩm phù hợp cho đơn vị/bộ phận nghiệp vụ;\nNghiên cứu, đề xuất, ứng dụng các giải pháp CNTT trong quản lý doanh nghiệp;\nHỗ trợ các phòng ban nghiệp vụ trong các công việc liên quan tới CNTT.\n\nYêu Cầu Công Việc\n\nTrình độ:\nTốt nghiệp Đại học trở lên chuyên ngành liên quan tới Công nghệ thông tin;\nTrình độ ngoại ngữ: đọc hiểu tiếng Anh chuyên ngành.\n\nKinh nghiệm:\nCó kinh nghiệm tối thiểu 02 năm;\nCó kinh nghiệm cài đặt, quản trị, cấu hình, tinh chỉnh ứng dụng phần mềm;\nCó kiến thức về hệ thống Linux/Unix, CSDL: Oracle. SQL Server hoặc PostgreSQL;\nƯu tiên: ứng viên làm việc với vai trò vận hành hệ thống phần mềm/khai thác dữ liệu trong các công ty công nghệ/và trong lĩnh vực tài chính và có kinh nghiệm triển khai, vận hành OpenShift/K8S/Docker.\n\nNăng lực/Kỹ năng:\nCó lỹ năng làm việc nhóm;\nCó khả năng tư duy và kỹ năng về hệ thống, phân tích thiết kế tốt.\n\nChế Độ Lương Và Đãi Ngộ\n\nChế độ lương và đãi ngộ:\nMức lương: Thỏa thuận, cạnh tranh trên thị trường và được hưởng thu nhập tăng thêm theo kết quả hoạt động kinh doanh của Công ty, xứng đáng với năng lực, kinh nghiệm và hiệu quả công việc;\nĐược hưởng các khoản phụ cấp ăn trưa, trách nhiệm công việc,…;\nĐược hưởng đầy đủ chế độ BHXH, BHYT và các chế độ phúc lợi khác theo quy định;\nĐược hưởng gói Bảo hiểm chăm sóc sức khỏe và hỗ trợ y tế cho CBNV và tham gia bảo hiểm cho người thân;\nCó nhiều cơ hội thăng tiến; Được tạo điều kiện tối đa để phát huy hết khả năng;\nMôi trường làm việc văn minh, chuyên nghiệp.\n\nHồ Sơ Bao Gồm\n\nHồ sơ bao gồm:\nMẫu Thông tin ứng viên đăng tải tại website: http://tuyendung.vcbs.com.vn mục Cơ hội nghề nghiệp, trong đó nêu rõ kinh nghiệm công tác và quá trình đào tạo;\nVCBS ưu tiên ứng viên gửi hồ sơ sớm; VCBS có thể kết thúc việc tuyển dụng trước hạn khi đã tìm được ứng viên phù hợp.\nLiên hệ: Cán bộ phụ trách tuyển dụng Ms. Hoàng Hán, SĐT: 0243.936.6990 máy lẻ 827.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Trần Hưng Đạo, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1912, 189, 2, 'AI Engineer', 'Position Summary\n\nRole and Responsibilities\n\n- Research, design and apply machine learning for auto defect analysis and issues detection.\n- Improve auto ecosystem with intelligent auto testing solution.\n- Data analysis and find out the issue, analyze production defect in real market.\n- Ensures completion of all documentation required for production introduction.\n- Use GitHub for source code repository and Jira for task tracking.\n\nSkills And Qualifications\n\n- Bachelor\'s or Master\'s Degree in Computer Science, Computer Engineering, relevant technical field, or equivalent practical experience.\n- 2+ years of experience with Python, SQL/NoSQL, Linux, Docker, AI\n- Good in English communication for working.\n- Ability to work on multiple tasks concurrently.\n- Self-motivated with a strong desire to learn.\n- Solid decision-making skills and judgment – can be depended upon to meet goals, foresee and avert problems.\n- Python programming experience.\n- Solid scripting skills (i.e., shell scripts, Python).\n- Familiarity in relevant machine learning frameworks and packages such as Tensorflow and PyTorch.\n- Thorough understanding of NLP techniques for text representation and modeling\n- Strong understanding SLQ/NoSQL, Docker.\n- Familiar with graph, data display & analysis.\n- Please visit Samsung membership to see Privacy Policy, which defaults according to your location. You can change Country/Language at the bottom of the page. If you are European Economic Resident, please click here.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1913, 1035, 2, 'Middle Java Developer', '• Qualification:\n• University Graduate, major in Information Technology.\n• Experience\n• IT technical analysis and programming: at least 3 years.\n• Knowledge:\n• Good knowledge of an objective oriented language (Java)\n• Good knowledge of web/application containers (Apache Tomcat, Jboss AS, IBM WebSphere ...)\n• Good experience on SOAP, RESTful Web Services.\n• Good skill at MS SQL Server programming (stored procedure, function, job, trigger, view).\n• Good skill in database design, database management, particularly MS SQL.\n• Solid understanding of the software development life cycle\n• Working knowledge of HTML5, CSS3, and Javascript a plus\n• Skills:\n• Programming skill.\n• Communication skill.\n• Analysis skill.\n• Team work spirit.\n\n• Accountabilities:\n• Analyze the business specs then prepare technical specs and develop the new systems or enhance existing system for supporting business needs.\n• Support the team leader on technical analysis to provide the best technical solution as well as support colleagues for solving technical issues to complete the assigned projects / tasks on timely manner.\n• Investigate and answer daily enquiries on systems functional as well as problem encountered in order to resolve it in timely manner.\n• In charge of unit test on enhancements / new development under responsibility to ensure developed modules are matched with business requirements.\n• Assist users/team leader on building test scripts to cover all test cases.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1914, 743, 2, '[LQA] React Native Developer', 'Position: React Native Developer\n\nQuantity: 01\n\nType: Full-time\n\nLocation: 68 Nguyen Co Thach street, Ha Noi.\n\nDescription:\n- Design and build a mobile application using React Native\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Work on bug fixing and improving application performance\n- Continuously discover, evaluate, and implement new technologies to maximize development efficiency\n\nRequirements:\n- At least 2-3 years of experience with React Native\n- Knowledge of JS frameworks (Node.js, React.js/AngularJS)\n- Experience working with remote data via REST and JSON\n- Experienced working with third-party libraries and APIs\n- Experience with GIT\n- Native Android or iPhone development experience is a plus\n- Knowledge and experience about cloud environment (AWS, GCP) is a plus\n- Good English is a plus\n\nBenefits:\n- Attractive salary. Performance based award. to be discussed.\n- Young and dynamic working environment.\n- Chance to experience the sale process in an IT company.\n- Chance of learning in the professional environment.\n- Chance of working directly with clients and improve skills.\n- Salary review 2 times/year or on excellent performance.\n- Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\n\nCONTACT:\nLQA Recruitment Department\n\nPhone Number: 02466607474\nEmail: lqa.rec@lqa.com.vn/ hr@lqa.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói, Hanoi, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1915, 707, 2, 'Junior/Middle Manual QC Engineer', 'JOB DESCRIPTION\n\n- Working directly with the client, develop team: Weekly status report, discuss / clear requirement with Product Owner, Develop team\n- Creating and maintaining test cases\n- Executing test cases\n- Reporting and verifying issues\n\nJOB REQUIREMENTS\n\nMUST HAVE\n\n- At least 2 years of experience in manual testing\n- Having solid knowledge of test case design techniques and testing strategies\n- Experience with test case management tools: Zephyr, Qase\n- Experience with API testing\n- Good at English communication\n\nNICE TO HAVE\n\n- Experience API test with Postman scripts\n\nBENEFITS\n\nCompetitive Salary and Brilliant Health Benefits\n\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan \n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program \n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support. \n- Surrounded with friendly, open-minded, young and supportive colleagues \n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Da Nang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1916, 757, 2, '[HN] Software Engineer (Full-stack,Middle)', 'Mô tả công việc\n\nAbout Us\n\nBase.vn is a B2B SaaS (Software-as-a-Service) Company providing technology management solutions for SMEs enterprises.\n\nBase will bring to your business the smartest, most modern technology products, based on three main components: Data & Artificial Intelligence (Data & AI), Interaction (Interaction), and Platform platform (Open Platform). And imagination knows no bounds: With whatever application you have or need, Base can help you integrate into a common platform. With a strong belief in young Vietnamese engineers, we are looking for talented Software Engineer for the Platform Team to pursue Base’s mission together: Build great enterprise software for Asia.\n\nWhat You Do\n\nFrom the beginning, you will be guided by Senior Engineer or Team Lead to:\n\n- Understand the products we‘re passionately building and know what to improve yourself to build them better in the future\n- Understand and respect all the working principles\n- Efficiently work with all the materials\n- Get your very first products - “Starter Project" done, reviewed, and improved\n\nThen, you will join a full-cycle buildup apps/features in our platform:\n\n- Analyze product & Planning\n- Design Database\n- Develop & Test\n- Demo & Launch\n- Maintain & Update new features\n\nWho You Are\n\nWe‘re looking for talented Software Engineers to join our team with below traits:\n\n- Solid knowledge in Algorithms & Data structures\n- Strong knowledge and experience in using any programming language (PHP/Javascript is an advantage)\n- Knowledge or experience in using Restful API, MySQL, HTML5, CSS3, Javascript, jQuery, AJAX, JSON\n- Understanding of performance optimization or experience in real applications in production, serving large amounts of users and data - is an advantage\n- Desire to participate in building the product "B2B SaaS - Make in Vietnam"\n\nSpecial Benefits\n\nWHAT YOU CAN GET\n\n- Attractive salary package up to 2000$ plus bonus based on performance\n- Flexible evaluation of salary increase (1-2 times/year) commensurate with work results\n- Opportunity to receive ESOP shares (employee stock ownership plan) for outstanding contributors\n- High performance computer and screen\n- Team building, vacation in a year, and other engagement activities\n- Other benefits as prescribed by the Labor Law\n\nPersonal Development\n\n- Fast-track career: Join a full cycle of building real products for market and continuously grow with the scalability of products.\n- Unlimited learning opportunities: Enhance your expertise through a comprehensive training program, guidelines from mentors, buddies, and product development challenges.\n- Visible values & impacts: Build world-class and high-performance products that solve pain points for millions of enterprises.\n- Talented colleagues: Work with a team of enthusiastic and professional Product Builders who have already built a highly large-scale system serving 60+ millions of pageviews, hundreds of thousands users each month, and 9000+ enterprises; and graduated from top universities in Vietnam & the world (Stanford, UCLA, HUST, etc.).\n\nGET READY TO BE OUR SOFTWARE ENGINEER!\n\n- Round 1: CV Application & Online Test (Algorithms & Data Structures, Programming Language)\n- Round 2: Interview\n\nAddress Office: 16th floor, HUD Building, 37 Le Van Luong, Thanh Xuan, Hanoi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1917, 1036, 2, 'Solution Android Engineer', 'The Software Engineer collaborates with colleagues to define requirements for software solutions and tools aimed at device’ configuration and management, analyzes such requirements, develops the software that realize them and the automatic tests that verify such functionalities.\n\nHe / she participates in design reviews, evaluates new application components and upgrades, writes recommendations on risk mitigation, understands, and recognizes quality software architecture and contributes to its definition, manages Android application’s maintenance, evaluates possible improvement of the software designs.\n\nThere may be also a collaboration with application engineers, field service engineers, technical support engineers and commercial teams to solve technical issues or to address new business needs.\n\nMain Responsibilities\n\nTo discuss with team requests for new features or software modules to be developed \nTo define and document functional requirements of needed developments \nTo develop and debug software applications, mainly using Kotlin, Android development tools \nTo apply software engineering and programming best practices \nTo analyze, understand and refactor existing source code \nTo have experience in SW optimization and event-based programming \nTo be familiar with Agile SW development \n\nTechnical Skills\n\nGood knowledge of the Android ecosystem\nProficiency in Kotlin, Android development tools and best practices (e.g. MVVM, JetPack, Android Studio, Gradle, …)\nGood knowledge of testing best practices (eg. MVVM, JetPack, Android Studio, Gradles,..)\nFamiliarity with RESTful APIs and JSON \nBasic knowledge about database \nUnderstanding of Object Oriented Program (OOP) patterns and concepts \nFamiliarity with different designs and architectural patterns \nIn-depth knowledge of code versioning tools such as Git \nUnderstanding of CI/CD process \nGood knowledge of Kotlins/Java SE for Linux and Window is plus\nDevelopement experience with Web UI, web application, cloud service are plus \n\nSoft Skills\n\nAnticipate needs and potential technical issues and roadblocks in the development phase; shows initiative, ownership, and commitment; sustains a consistent, high level of productivity. \nGood at understanding and resolving issues and opportunities, evaluating them from different perspectives. Customer oriented; looks for solutions to augment customer or supplier’s satisfaction. \nInterpersonal abilities, ability to work with a team, attention to details, flexibility, and creativity, proactive, project management skills, capability to work in a dynamic international team and in a complex environment, problem solving attitude, open minded. \n\nCompany Background\n\nDatalogic is a global technology leader in the automatic data capture and factory automation markets, specialized in the designing and production of barcode readers, mobile computers, sensors for detection, measurement and safety, RFID, vision and laser marking systems.\n\nDatalogic can boast over 50 years of history, during which it has achieved unique results: approximately 1.200 patents in multiple jurisdictions; 11 research centers and development (in Italy, USA, China and Vietnam); thousands of prestigious partners and customers deployed over five continents. The company has grown constantly over the years, thanks to the dedication with which customer needs have always been at the heart of the quality of its products and to the considerable investments in Research & Development, supported by a management capable of looking to the future.\n\nToday, Datalogic Group has approximately 3,000 employees worldwide, distributed in 29 offices, with 11 manufacturing and repair facilities in the USA, Hungary, Slovakia, Italy, China, Vietnam and Australia. Datalogic S.p.A. is listed on the STAR segment of the Italian Stock Exchange since 2001 as DAL.MI. In 2022, the Datalogic Group made significant strides and concluded the year by generating revenue of approximately €655 million. The Group is headquartered in Bologna, Italy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'โฮจิมินห์, นครโฮจิมินห์, เวียดนาม', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1918, 1037, 2, 'AI/ML Engineer (Automation & Computer Vision)', 'Key Responsibilities\n\n- Develop and deploy AI agents and Computer Vision models to automate repetitive tasks, monitor production processes, and reduce human intervention in workflows.\n- Design and implement AI solutions for automating data entry, document processing, reporting, and operational workflows, as well as integrating these solutions with existing IT systems, ERP, and business applications.\n- Develop AI-driven systems for quality control in manufacturing (e.g., fabric quality inspection, defect detection, and assembly tracking) by applying Deep Learning for image analysis.\n- Integrate image recognition systems to track materials and products using cameras or sensors, optimizing production processes in collaboration with robotic systems.\n- Collaborate with cross-functional teams, including IT, manufacturing, and management, to identify automation opportunities, enhance cost-efficiency, and improve workflows.\n- Stay up-to-date with advancements in AI, machine learning, and Computer Vision technologies, and apply them to optimize automation and intelligent systems.\n- Optimize AI models for scalability, security, cost-efficiency, and deploy them in real-world production and operational environments.\n\nRequirements\n\n- Bachelor’s Degree in Computer Science, AI, Software Engineering, or a related majors.\n- Strong programming skills in Python (TensorFlow, PyTorch, OpenCV, LangChain) and experience with RPA tools (UiPath, Power Automate, Automation Anywhere).\n- Minimum 2 years of hands-on experience in AI/ML, particularly in automation and Computer Vision.\n- Strong knowledge of Deep Learning algorithms (CNN, YOLO, Faster R-CNN) for image recognition and analysis.\n- Good understanding about Business process.\n- Familiarity with AI-driven automation systems, cloud services (AWS, Azure, GCP), and IT security/compliance.\n- Experience with edge computing, machine vision, or AI on embedded devices is a plus.\n- Basic English communication.\n- Strong problem-solving skills, particularly with a focus on cost reduction, efficiency improvements, and real-time image processing.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Binh Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1919, 992, 2, 'Frontend Developer (Mid - Senior)', 'Company Overview\n\nCartrack, a subsidiary of Karooooo Ltd. (listed on NASDAQ as KARO), is a global leader in mobility solutions, specializing in real-time data analytics, fleet management, and vehicle tracking. With over 2.3 million active subscribers across more than 23 countries, Cartracks mission is to drive efficiency and connectivity for vehicle fleets worldwide, making transportation smarter and more sustainable.\n\nAs a pioneer in the telematics industry, Cartrack provides a comprehensive Software-as-a-Service (SaaS) platform that delivers critical insights to businesses, enabling them to optimize their operations, reduce costs, and enhance safety. The platform is trusted by small to large enterprises across various industries, including logistics, insurance, and automotive, for its reliability, scalability, and robust performance.\n\nAt Cartrack, we are not just offering a job; we are offering the opportunity to be part of a mission-driven company that is transforming the way fleets operate globally. Our commitment to innovation, customer satisfaction, and sustainability is reflected in our continuous growth and strong financial performance, as we expand our footprint in key regions like Southeast Asia, Europe, and Africa.\n\nJoin us at Cartrack and be part of a dynamic team that is shaping the future of connected mobility, ensuring that fleets around the world are more efficient, safe, and connected.\n\nProfile\n\nWe are seeking an experienced Front-end Developer who has worked on multiple large-scale projects. This individual should have a proven track record of being a strong individual contributor within a team environment and work independently to deliver high quality code at a fast pace.\n\nThe candidate should excel in dynamic and demanding environments, adeptly managing various priorities, and balancing them with efficiency and focus. The ideal candidate will be outspoken, a strong communicator, and decisive, with the ability to articulate their ideas clearly to both technical and non-technical stakeholders.\n\nRole\n\nThis role requires an individual who is technically sound and can work with minimal guidance to produce results. You will have to collaborate with colleagues from the product team, UI/UX designers, back-end developers, and the quality assurance team to understand an execute on requirements.\n\nThe role will give you the ability to see the material impact of your work on thousands of clients around the world. If you are someone that thrives working in a fast-paced environment and likes being independent, then this is for you!\n\nMust have\n\n- Bachelor\'s degree in Computer Science or equivalent industry experience\n- ReactJS: Strong expertise in ReactJS, capable of building robust and easy-to-use front-end applications. 4+ years of hands-on\n- Typescript: Experience of writing code in Typescript.\n- HTML/CSS: Experience in styling applications for multiple browsers.\n- Git: Expertise in using Git for version control. Understand branching, merging, and collaborative workflows.\n\nNice to have\n\n- Mapping Technologies: Experience integrating with or embedding technologies like Google Maps, Here Maps or Leaflet\n- PHP: Familiar with writing server-side code with PHP\n- SQL: Able to write SQL queries\n- Containerization: Experience in managing applications that are run using a containerization technology like Docker and orchestration technologies like Kubernetes\n- Linux: Proficiency in Linux environment, including scripting and system management\n- Continuous Integration: Familiar with CI/CD pipelines and associated tools like GitLab CI', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1920, 326, 2, 'QA Engineer  (Automation)', 'YOUR NEW ROLE CODE LEAP\n\nWe are looking for a QA Engineer (Automation) to join our expert team in Ho Chi Minh City. This position starts with a focus on practical testing and quickly expands into a broader QA role, especially for candidates with product and development experience.\n\nYOUR EXCITING TASKS\n\n- Perform E2E tests via the UI, simulating various user actions to ensure comprehensive functionality and stability\n- Test individual front-end components, ensuring they behave as expected within the overall UI\n- Develop and maintain automated UI tests using Playwright, ensuring the tests stay effective and aligned with the evolving platform\n- Work closely with developers to integrate test coverage into the development cycle and ensure defects are tracked and resolved efficiently\n- Log and track defects using tools like Jira, analyzing root causes and ensuring quick resolutions\n- Maintain and update test documentation and test data sets to ensure consistency and repeatability\n- Contribute to the improvement of testing processes, such as optimizing test scripts and suggesting new tools for better testing efficiency\n\nYOUR PROFILE AND YOUR PERSONALITY\n\n- At least 2 years of experience in software testing\n- Hands-on experience with React (for understanding UI behavior and components in the context of testing)\n- Strong expertise in Playwright for UI test automation\n- Solid experience in front-end testing and validating that UI components work as expected\n- Knowledge of UI testing frameworks (e.g., Playwright, Cypress) and best practices for automation\n- Experience with manual testing of the UI for real-world usability and user experience validation\n- Familiarity with defect tracking tools like Jira\n- You understand and know how to prioritize your tasks with a problem-solving mindset\n- You don\'t take things personally and are comfortable with ambiguity and rapid changes common in early-stage product development\n- You don\'t wait for others to tell you what you need to do but proactively reach out to people, communicate, ask for help, and get things done\n- You feel comfortable communicating in the English language\n\nNice to have\n\n- Experience transitioning from development to QA\n- Experience with eCommerce/ERP platforms (e.g., Shopify, Magento, JTL, etc.)\n- Have a development background is a plus\n\nBenefits Await You At Code Leap\n\n- Competitive salary and beneﬁts\n- Year-end bonus (13th-month salary)\n- Generous annual leave of up to 18 days\n- Enjoy a stress-free and comfortable commute to and from work with our Grab Services sponsor\n- Enjoy an endless selection of delicious refreshments, including gourmet coffee, beverages, snacks, and fresh fruits, all complimentary\n- Focused on individual development:\n  - Unlimited access to Udemy and other recommended courses\n  - Sponsored Professional certificates such as ISTQB, ASQ, CSTE, CAST, etc.\n  - Sharing session every Friday, come along with lunch provided by CODE LEAP\n  - 1-on-1 coaching with experienced professionals\n- Flexible work policy, which provides flexible hours to accommodate personal schedules and commitments\n- Premium AI Assistant tools are provided to support your work\n- Dynamic, fun, and agile environment, perfect for sharing and creativity\n- Open-minded, kind & humble colleagues\n\nCONTACT\n\nPlease reach out and contact us now with your latest CV as well as a little description of yourself at jobs@codeleap.de.\n\nAbout Us\n\nWith our expert teams spread across two continents, CODE LEAP provides innovative software solutions for venture-backed companies and leading enterprise businesses in Germany. Our teams in Germany and Ho Chi Minh City (Vietnam) work hand in hand to develop state-of-the-art solutions of the highest quality.\n\nBecause collaborating with the right people is the secret to our successful growth.\n\nWe future-proof organizations - be part of it!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Tsji Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1921, 783, 2, 'Senior Java Software Engineer', 'Company Description\n\nKMS Technology was established in 2009 as a U.S.-based software services company. With development centers in Vietnam and Mexico, we have been trusted globally for the superlative quality of our software consulting & development services, technology solutions, and engineers\' expertise. We pride ourselves on creating brilliant solutions for our clients by leveraging deep expertise, advanced technologies, and delivery excellence for a shared success where everyone can reach their fullest potential. With three Business Lines:\n\n• KMS Software: Leverage software domain expertise to help clients make better business decisions in technology platforms, increase speed-to-market, and gain critical development support through innovative technology solutions. \n• KMS Solutions: Empower BFSI businesses to embrace the digital finance revolution and expedite clients’ journey towards complete digitalization, technology consulting, data analytics, software development, and software quality. \n• KMS Healthcare: Build transformative next-gen technologies to solve healthcare’s most challenging problems, providing innovative tools and expertise to providers, payers, life sciences, and medical technology vendors.\n\nJob Description\n\n• Perform hands-on coding and code review as other peer developers as needed\n• Understand the requirements of the customer or business and utilize this knowledge to develop applications that are consistent with this;\n• Design, develop, review, implement, maintain and manage continuous integration, build management and deployment scripts, systems, and any code as required;\n• Write unit tests and run through all the test cases for assigned tasks and ensure all cases are tested and passed before release for testing. \n• Participate in Agile/Scrum activities: daily standup, demo session, retrospective, estimate, and planning, etc\n• Provide mentoring/training for junior members if any\n• Perform other tasks assigned by the Line Manager.\n\nQualifications\n\nGeneral requirements:\n\n• At least an upper-intermediate skill level of English\n• Likely having 3+ years of experience (flexible depending on how fast your learning and technical developing capabilities are)\n• Able to obtain deep knowledge of the project’s technologies\n• Able to work independently with minimal guidance\n• Able to self-learn and quickly adapt to new technologies\n• Familiar with the Agile development methodologies (Scrum, XP, Kanban)\n\nTechnical requirements:\n\n• Proficient in Java, Java core to develop enterprise web-based applications\n• Strong experience with web-based technologies: Spring (Spring Core, Spring MVC, Spring Security, Spring Data, Spring Boot) and ORM (JPA, Hibernate)\n• Strong experience with OO designs and design patterns\n• Good experience with unit testing: JUnit, mock\n• Experience with writing efficient SQL queries\n• Experience with Web Services (REST, etc.). \n\nNice to have:\n\n• Experience with HTML/ CSS/ SCSS/ JavaScript/ Bootstrap and one of following JavaScript frameworks: ReactJS, Angular, VueJS, KnockoutJS\n• Experience in microservices and cloud environment (Azure/AWS/GCP)\n\nAdditional Information\n\n• Working in one of the Best Places to Work in Vietnam, Top 10 ITC Company in Vietnam\n• Flexible working model: Flexible time & Hybrid working from Ho Chi Minh or Da Nang city or working remotely from any location in Vietnam\n• Attractive Salary & Benefits, full salary in probation, social insurance on full gross salary\n• Performance appraisal twice a year, 13th-month salary and performance bonus \n• Premium healthcare insurance for you and your loved ones\n• 18+ paid leave days/year\n• Diverse careers opportunities with Software Services, Software Product Development\n• Working and growing in a values driven, international working environment and standard Agile culture with passionate and talented teams\n• Onsite opportunities: short-term and long-term assignments in U.S\n• Various training on hot-trend technologies, best practices and soft skills\n• Company trip, big annual year-end party every year, team building, etc. \n• Fitness & sport activities: football, tennis, table-tennis, badminton, yoga, swimming…\n• Joining community development activities: 1% Pledge, charity every quarter, blood donation, public seminars, career orientation talks,…\n• Free in-house entertainment facilities (football, ping pong, gym…), coffee, and snacks (instant noodles, cookies, candies…)\n\nAnd much more, join us and let yourself explore other fantastic things!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1922, 1038, 2, 'Application Engineer - Remote', 'Vault Cloud is the national leader of providing highly secure and scalable sovereign cloud capability to the Australian Government, National Intelligence Community and Critical Infrastructure sector. We pioneered the development of Australia’s only sovereign, hyperscale cloud with security at its core, being one of the first cloud organisations to be Australian Signals Directorate (ASD) certified and we continue to drive innovation, delivering First of a Kind capability across the sector.\n\nAs we continue to lead in technological advancements, Vault is now entering a defining phase of growth with a strategic $22.5 million investment from the National Reconstruction Fund Corporation (NRFC). This investment will scale Vault\'s SECRET Cloud and introduce new services such as the AUKUS cloud capability, directly addressing Australia\'s strategic national security demands. Vault is now positioned to not only strengthen its existing relationships with federal and state government agencies, but also strengthen its relationships with private sector businesses requiring secure cloud storage.To support this growth, we are bolstering our capability by adding numerous key roles that are integral to our future success. This is an opportunity to join us at the forefront of a once-in-a-generation technological advancement whilst at the same time securing the nation against ever-increasing threats.\n\nDue to Vault’s commitment to innovation and high-governance product development, we are looking for an Application Engineer role to join our Delivery team to support the company\'s expansion. This role is integral to developing and maintaining our custom billing system using Ruby on Rails, contributing to the new ELK (Elasticsearch, Logstash, Kibana) stack, enhancing identity systems with FreeIPA, and utilizing GitLab for CI/CD. This is a remote role and is a unique opportunity to be at the forefront of developing and integrating cutting-edge cloud products that protect some of Australia’s most critical data.\n\nYou will be responsible for:\n- System Development & Maintenance: Ensure the design, development, and upkeep of high-quality, scalable systems.\n- Collaboration & Communication: Work cross-functionally to translate business needs into technical solutions.\n- Development Lifecycle & Quality: Engage in Vault’s SDLC, leveraging DevOps practices and maintaining coding standards.\n- Product & Release Planning: Contribute to backlog management, resource planning, and efficient product delivery.\n- Technical Leadership: Stay ahead of industry trends, drive innovation, and optimize system design.\n\nTo be successful you will be able to demonstrate with:\n- Proficiency in Ruby on Rails for application development.\n- Experience in system design and architecture, ensuring scalable and efficient solutions.\n- Familiarity with GitLab administration and CI/CD pipeline management.\n- Ability to contribute across multiple technical domains, including hardware, software, and systems development.\n- Adaptability and rapid prototyping skills, enabling quick proof-of-concept development for new technologies or approaches.\n- A passion for technology and security\n- Flexibility to enjoy and thrive within a fast-paced, agile, and expanding scale-up environment\n\nWhat’s in it for you?\n- Be at the forefront of cyberwarfare, the greatest technology challenge of our generation\n- Up to 10% of time dedicated to learning & development\n- 5 days of bonus leave per year\n- Company paid parental leave\n- A diverse culture where we celebrate our people and their unique, individual perspectives\n\nYou will collaborate to provide secure and professional cloud services to a broad range of users. Join us now and become part of the future of secure cloud services and provide a significant contribution to our nation\'s success.\n\nGet to know us at\nhttps://vaultcloud.com.au/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1923, 366, 2, 'Senior Backend Engineer (Java) - GSaaS', 'About NAVER Corp and NAVER Vietnam:\nNAVER Corp\n\nNAVER Corp is South Korea’s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia’s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\nLearn more about us: https://navercorp.vn/\n\nWe are looking for a Backend Engineer (Java) for GSaaS project.\n\nYour daily tasks:\n- Responsible for developing and maintaining the server-side components using the Java programming language\n- Write and maintain technical documentation, including system architecture and API specifications\n- Take a look at NAVER WORKS services HERE\n\nYour background:\n- 4+ years of work experience on related work\n- Bachelor\'s degree or above in Computer Science or related field\n- Good Java basic skills, experience with multi-threaded programming, IO, JVM garbage collection\n- Experience with Java performance tuning and find and resolve troubleshoot experience with Spring, Spring MVC, Spring Boot, MyBatis, MySQL, High Availability, High Concurrency Related Technologies\n- Experience with Linux basic command, independently complete project deployment, troubleshooting\n- Open-minded, honest and have a positive attitude towards people\n- Good at communication skills in general and English skills in particular\n\nIt\'s a big plus if you:\n- Experience with big data projects, Kafka & Hbase.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n- A work-life balance: Hybrid working model with modern city-center offices, 14 days of annual leave (increasing yearly) and an additional day off for your birthday.\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1924, 1039, 2, 'Chuyên viên Quản trị hệ thống Corebanking', 'THÔNG BÁO\n\nVề việc tuyển dụng nhân sự theo vị trí tại các đơn vị Khối CNTT&NHS\nNgân Hàng TMCP Đầu Tư Và Phát Triển Việt Nam (BIDV) Trân Trọng Thông Báo Tuyển Dụng Nhân Sự Theo Vị Trí Tại Các Đơn Vị Khối Công Nghệ Thông Tin & Ngân Hàng Số Như Sau\n\n- Số lượng, vị trí tuyển dụng, mô tả công việc, yêu cầu đối với vị trí tuyển dụng: chi tiết tại Phụ lục kèm theo Tải về \n\n(*) Địa điểm làm việc: Trụ sở chính BIDV, Tháp A Vincom, 191 Bà Triệu, Hai Bà Trưng, Hà Nội.\n\n- Quy trình tuyển dụng: Qua 02 vòng: sơ loại hồ sơ và phỏng vấn trực tiếp. Trường hợp cần thiết sẽ yêu cầu làm bài test (nghiệp vụ, tiếng Anh) để kiểm tra thêm năng lực của ứng viên.\n- Quyền lợi:\n- Được hưởng lương, thưởng và các cơ chế khuyến khích theo thỏa thuận và theo quy định của Ngân hàng TMCP Đầu tư và Phát triển Việt Nam. Đặc biệt, đối với nhiều vị trí công nghệ thông tin khan hiếm, hàm lượng CNTT cao được hưởng mức thu nhập tăng thêm từ 10% -20% so với mức thu nhập theo quy định chung. Ngoài ra, còn có các chế độ đãi ngộ đặc thù khác ngoài lương, như: khuyến khích tham gia/thưởng dự án, cho vay phục vụ đời sống, hỗ trợ cước viễn thông,..\n- Làm việc trong môi trường chuyên nghiệp, năng động và cơ hội thăng tiến luôn thường trực.\n- Được đào tạo cơ bản và chuyên sâu về chuyên môn nghiệp vụ.\n- Chế độ phúc lợi hấp dẫn:\n- Thực hiện đầy đủ các chế độ bảo hiểm phúc lợi theo quy định của pháp luật: bảo hiểm xã hội, nghỉ phép, khám sức khỏe định kỳ hằng năm…\n- Bên cạnh đó, BIDV luôn duy trì và phát triển các chế độ phúc lợi nội bộ khác đối với cán bộ nhân viên: bảo hiểm sức khỏe, bảo hiểm hưu trí, du lịch – nghỉ dưỡng – team building, các phúc lợi hiếu hỷ, tiền mừng sinh nhật…\n- Yêu cầu về hồ sơ dự tuyển:\n- Phiếu đăng ký dự tuyển có dán ảnh (Mẫu 01 – Phiếu đăng ký dự tuyển Tải về ).\n- File scan các văn bằng, chứng chỉ gốc: Bằng tốt nghiệp Thạc sỹ/Đại học, bảng điểm các năm học có xác nhận của trường; các chứng chỉ về thành tích học tập (nếu có); Chứng chỉ ngoại ngữ.\n- File scan các giấy tờ chứng minh kinh nghiệm công tác: Hợp đồng lao động, Quyết định tuyển dụng, Quyết định phân công công tác, Quyết định xếp lương, sổ Bảo hiểm xã hội hoặc các giấy tờ thay thế khác (nếu có); xác nhận của đơn vị đã công tác, các quyết định tham gia dự án, bản phân công công việc…\n- File ảnh 4x6 của ứng viên.\n\nỨng viên scan Phiếu đăng ký dự tuyển (Mẫu 01 có dán ảnh) và các văn bằng, chứng chỉ liên quan thành 01 file dạng .pdf và đặt tên file theo cú pháp: Mã vị trí_họ tên ứng viên.\n\nVí dụ: Ứng viên tên là Nguyễn Văn B ứng tuyển vị trí Chuyên viên Phát triển phần mềm tại Trung tâm Phát triển Ngân hàng số (mã NHS01). Ứng viên đặt tên file pdf là NHS01_Nguyễn Văn B.\n\n- Thời gian, cách thức nộp hồ sơ:\n- Thời gian: từ ngày 18/11/2024 đến khi BIDV thu đủ số lượng hồ sơ/tuyển dụng đủ số lượng theo nhu cầu.\n- Cách thức nộp hồ sơ:\n\nỨng viên nộp hồ sơ trực tuyến tại website tuyển dụng của BIDV (https://tuyendung.bidv.com.vn/) hoặc nộp hồ sơ qua website tuyển dụng của Topdev (https://topdev.vn/).\n\n- LƯU Ý CHUNG: \n- Mỗi thí sinh ngoài hệ thống chỉ nộp hồ sơ 01 lần tại trang https://tuyendung.bidv.com.vn/ hoặc https://topdev.vn/ , không nộp đồng thời vào cả 02 trang tuyển dụng.\n- Mỗi thí sinh (gồm cả nội bộ và ngoài hệ thống) chỉ nộp hồ sơ vào 01 vị trí và vào 01 đơn vị.\n- Thí sinh hoàn toàn chịu trách nhiệm về tính chính xác và trung thực của hồ sơ. Trường hợp BIDV phát hiện hồ sơ đăng ký của thí sinh không chính xác, trung thực, kết quả thi tuyển của thí sinh sẽ bị hủy bỏ.\n- Hội đồng tuyển dụng chỉ liên lạc với các ứng viên đạt yêu cầu tại các vòng thi.\n\nTrong quá trình nộp hồ sơ trên website https://tuyendung.bidv.com.vn/, nếu có vướng mắc về kỹ thuật, ứng viên gửi email đề nghị hỗ trợ vào địa chỉ tuyendung.TCNS@bidv.com.vn (Lưu ý đặt tên tiêu đề email là: Đề nghị hỗ trợ nộp hồ sơ Khối CNTT&NHS).\nNgân hàng TMCP Đầu tư và Phát triển Việt Nam trân trọng thông báo./.\n\nPHỤ LỤC: MÔ TẢ CÔNG VIỆC, TIÊU CHUẨN TUYỂN DỤNG ỨNG VIÊN NGOÀI HỆ THỐNG\n–\nBAN QUẢN LÝ VÀ PHÁT TRIỂN CORE BANKING\n\nI. SỐ LƯỢNG, VỊ TRÍ TUYỂN DỤNG:\n\nMã vị trí\nTên vị trí tuyển dụng\nSố lượng tuyển dụng\nNguồn tuyển dụng\nMức lương\nCBS01\nChuyên viên Phát triển ứng dụng\n09\nNgoài hệ thống BIDV\nTheo thỏa thuận\nCBS02\nChuyên viên Phát triển Core Banking\n06\nNgoài hệ thống BIDV\nTheo thỏa thuận\nCBS03\nChuyên viên Phát triển API và Tích hợp\n09\nNgoài hệ thống BIDV\nTheo thỏa thuận\nCBS04\nChuyên viên Kiểm thử tự động (QC automation)\n04\nNgoài hệ thống BIDV\nTheo thỏa thuận\nCBS05\nChuyên viên Thiết kế giao diện và trải nghiệm (UI/UX)\n02\nNgoài hệ thống BIDV\nTheo thỏa thuận\nCBS06\nChuyên viên Quản trị dữ liệu\n04\nTrong/Ngoài hệ thống BIDV\nTheo thỏa thuận\nCBS07\nChuyên viên đảm bảo chất lượng (QA)\n01\nTrong/Ngoài hệ thống BIDV\nTheo thỏa thuận\n\nTổng Cộng\n\n35\n\nII. Mô Tả Công Việc\n\n- Chuyên viên Phát triển ứng dụng – Mã vị trí CBS01 (số lượng 09)\n- Thực hiện lập trình, tham gia khảo sát, phân tích thiết kế các yêu cầu phát triển phần mềm trên các ứng dụng kênh tác nghiệp của BIDV.\n- Cộng tác với các thành viên của nhóm nghiệp vụ, kỹ thuật khác, với các backend developers, designers nhằm xây dựng và tối ưu chức năng, tăng cường tính ổn định, hiệu năng, bảo mật của hệ thống.\n- Xác định, thực hiện và chia sẻ các giải pháp kỹ thuật, xây dựng các tài liệu phát triển phần mềm theo quy trình.\n- Nghiên cứu, đề xuất áp dụng và triển khai, tham mưu, tư vấn cho lãnh đạo các giải pháp nhằm tối ưu hoạt động đối với các ứng dụng kênh tác nghiệp của Core Banking.\n- Nghiên cứu và ứng dụng các công nghệ mới áp dụng cho công tác lập trình phát triển ứng dụng, các xu thế công nghệ và nghiệp vụ liên quan đến các kênh giao dịch và tác nghiệp của các hệ thống Core Banking trên thị trường.\n\n- Chuyên viên Phát triển Core Banking – Mã vị trí CBS02 (số lượng 06)\n- Thực hiện các nhiệm vụ phát triển phần mềm trên Core Banking của BIDV: tham gia khảo sát, phân tích thiết kế, trực tiếp lập trình các functions / procedures / triggers trên CSDL của Core Banking nhằm xây dựng, cải tiến, bảo trì các tính năng và module của hệ thống Core Banking theo yêu cầu của BIDV.\n- Xử lý các lỗi kỹ thuật, khắc phục sự cố liên quan đến hệ thống Core Banking kịp thời và hiệu quả\n- Xây dựng các chức năng trong Corebanking nhằm tích hợp với các hệ thống bên ngoài core.\n- Cộng tác với các thành viên của nhóm nghiệp vụ hoặc kỹ thuật khác nhằm tối ưu chức năng, tăng cường tính ổn định, hiệu năng, bảo mật của hệ thống.\n- Đề xuất và phát triển các giải pháp công nghệ mới nhằm nâng cao hiệu quả vận hành của hệ thống Core Banking.\n- Tham gia vào các dự án nâng cấp hệ thống, cập nhật phiên bản mới và đảm bảo tính tương thích của hệ thống\n- Tìm hiểu và áp dụng các công nghệ mới, xu hướng phát triển phần mềm để cải thiện hệ thống.\n\n- Chuyên viên Phát triển API và Tích hợp – Mã vị trí CBS03 (số lượng 09)\n- Phát triển các dịch vụ tích hợp, kiểm soát, chuẩn hóa và tối ưu các API phục vụ các hệ thống tích hợp. Tham gia đánh giá, khảo sát và đề xuất giải pháp cho các ứng dụng có yêu cầu tích hợp vào corebanking.\n- Xây dựng và cung cấp các API tích hợp với các hệ thống back-end của cho các nhóm phát triển phần mềm, các đối tác hợp tác phát triển, các dự án.\n- Đầu mối thực hiện nâng cấp, bảo trì hệ thống tác nghiệp tại quầy: đáp ứng các nghiệp vụ phát sinh trong thực tế, tối ưu hiệu năng và chủ động đề xuất/ thực hiện các giải pháp để mang tới trải nghiệm tốt nhất cho người dùng.\n- Phối hợp cùng các nhóm BA-QC/các đơn vị nghiệp vụ để nghiên cứu, khảo sát các nhu cầu của khách hàng về dịch vụ kết nối, tích hợp qua các api để chủ động phát triển các dịch vụ mới.\n- Tham gia nghiên cứu các kiến trúc, công nghệ mới liên quan đến việc phát triển dịch vụ, tư vấn cho lãnh đạo về xu hướng phát triển công nghệ liên quan đến các mô hình tích hợp…\n- Cộng tác với các thành viên của nhóm nghiệp vụ hoặc kỹ thuật khác nhằm tối ưu chức năng, tăng cường tính ổn định, hiệu năng, bảo mật của hệ thống.\n- Đề xuất và phát triển các giải pháp công nghệ mới nhằm nâng cao hiệu quả vận hành của hệ thống Core Banking.\n- Tham gia vào các dự án nâng cấp hệ thống, cập nhật phiên bản mới và đảm bảo tính tương thích của hệ thống\n- Tìm hiểu và áp dụng các công nghệ mới, xu hướng phát triển phần mềm để cải thiện hệ thống.\n\n- Chuyên viên Kiểm thử tự động (QC automation) – Mã vị trí CBS04 (số lượng 04)\n- Thiết kế, phát triển, thường xuyên kiểm tra, bảo trì các kịch bản kiểm thử tự động (Automation Test Scripts) cho các dự án phần mềm, đảm bảo tính toàn vẹn và hiệu quả của kiểm thử.\n- Làm việc với các công cụ kiểm thử tự động để thực hiện các kịch bản kiểm thử trên các môi trường khác nhau (Web, WinForm, API...).\n- Thiết lập môi trường kiểm thử và tích hợp với hệ thống CI/CD, đảm bảo kiểm thử tự động được thực hiện liên tục và chính xác trong quá trình phát triển phần mềm.\n- Phát triển framework kiểm thử tự động phù hợp với từng dự án, đồng thời tối ưu và mở rộng khả năng của framework để hỗ trợ các yêu cầu mới.\n- Phối hợp cùng các nhóm liên quan để thực hiện performance testing.\n- Đánh giá, phân tích kết quả kiểm thử từ hệ thống tự động, phát hiện lỗi, lập báo cáo và phối hợp với đội ngũ phát triển để khắc phục các vấn đề được phát hiện.\n- Phối hợp với đội ngũ phát triển, các nhóm BA để hiểu rõ yêu cầu, tính năng và định hướng phát triển của sản phẩm, từ đó xây dựng kịch bản kiểm thử chính xác và toàn diện.\n\n- Chuyên viên Thiết kế giao diện và trải nghiệm (UI/UX) – Mã vị trí CBS05 (số lượng 02)\n- Dựa trên yêu cầu, mô tả của các nhóm nghiệp vụ, BA, thiết kế các bản phác thảo sơ bộ (wireframe) và nguyên mẫu (prototype) tương tác, minh họa các tính năng và giao diện của sản phẩm.\n- Thiết kế các thành phần giao diện trực quan, bao gồm các yếu tố như màu sắc, font chữ, icon, bố cục... Đảm bảo giao diện thân thiện, nhất quán và phù hợp với nhận diện thương hiệu của BIDV.\n- Phối hợp với các nhóm nghiệp vụ, BA nhằm thu thập thông tin về nhu cầu, thói quen và hành vi của người dùng thông qua các phương pháp như khảo sát, phỏng vấn, phân tích dữ liệu, từ đó hiểu rõ để thiết kế đáp ứng đúng mục tiêu và yêu cầu.\n- Xây dựng các luồng trải nghiệm (user flow) và hành trình người dùng (user journey), giúp tối ưu hóa sự tiện lợi và trải nghiệm tổng thể của người dùng khi tương tác với sản phẩm.\n- Thực hiện kiểm thử với người dùng, thu thập phản hồi từ các bên liên quan và người dùng cuối để đánh giá hiệu quả của thiết kế. Điều chỉnh và tối ưu hóa thiết kế dựa trên dữ liệu và phản hồi thực tế.\n- Cộng tác với nhóm phát triển, các nhóm BA&QC để đảm bảo sản phẩm cuối cùng phản ánh đúng ý tưởng thiết kế và mang lại trải nghiệm tốt nhất cho người dùng.\n- Theo dõi và áp dụng các xu hướng thiết kế UI/UX hiện đại để cải thiện chất lượng sản phẩm.\n\n- Chuyên viên Quản trị dữ liệu – Mã vị trí CBS06 (số lượng 04)\n- Thực hiện công tác quản trị các hệ thống phần mềm ứng dụng tại Core Banking theo phạm vi được phân công.\n- Đầu mối xây dựng, triển khai phần mềm ứng theo phạm vi được phân công.\n- Đầu mối rà soát, quy hoạch, tối ưu hệ thống định kỳ hoặc đột xuất hệ thống ứng dụng được phân công.\n- Tham gia công tác kiểm tra, nghiệm thu, xác nhận các nội dung liên quan đến kỹ thuật đối với các bản cập nhật hệ thống, các thay đổi về tham số, dữ liệu.\n- Hỗ trợ xử lý các yêu cầu kỹ thuật chuyển tiếp từ Chi nhánh/Ban/TT HSC.\n- Tham gia công tác kiểm tra, nghiệm thu, xác nhận các nội dung liên quan đến kỹ thuật đối với các bản cập nhật hệ thống, các thay đổi về tham số, dữ liệu.\n- Thực hiện giám sát, phát hiện và cảnh báo sớm các lỗi phát sinh hoặc các vấn đề tiềm ẩn rủi ro đối với hoạt động của hệ thống Core Banking theo phân công dựa trên quy trình được cung cấp.\n- Xây dựng các quy trình quản trị, vận hành, xử lý sự cố liên quan tới hệ thống phần mềm ứng dụng, xây dựng, triển khai các dự án, kế hoạch mua sắm liên quan tới Phần mềm ứng dụng, tham gia các dự án quan trọng của BIDV về CNTT;\n\n- Chuyên viên Đảm bảo chất lượng (QA) - Mã vị trí CBS07 (số lượng 01)\n- Xây dựng quy trình phát triển phù hợp với yêu cầu của từng dự án.\n- Xây dựng hệ thống tiêu chuẩn quản lý chất lượng, bao gồm: sổ tay chất lượng, quy định, quy trình hệ thống quản lý chất lượng, các quy trình - hướng dẫn công việc cụ thể, các biểu mẫu quản lý chất lượng …\n- Giám sát, kiểm tra đội phát triển tuân thủ theo đúng quy trình phát triển\n- Phát hiện các lỗi sai sót trong quy trình thực hiện, để từ đó có biện pháp xử lý kịp thời, phối hợp với các bên liên quan để tìm cách khắc phục\n- Thực hiện tổng hợp, báo cáo tiến độ, chất lượng và các vướng mắc của các nhóm phát triển lên các Cấp quản lý/ Quản trị', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1925, 936, 2, 'VN Technology Full-stack Engineer (Platform)', 'Recruitment Background & Expected Role\n\nCADDi is on a mission to "Unleash the potential of manufacturing."\n\nWe operate "CADDi DRAWER," a cloud-based system that supports digital transformation centered on the use of drawings, which are the most essential data in the manufacturing industry.\n\nOne of the issues we are currently facing in the development of this rapidly growing product is developer productivity. The inefficiencies in the development environment have become more noticeable, and they are becoming a hindrance to the development of features and a degradation of the developer experience. As an activity to resolve these issues, the need for Platform Engineering is increasing.\n\nThere are various interpretations and approaches to Platform Engineering in the world, but here, we will be working on providing tools and infrastructure to increase the development velocity by "separating concerns."\n\nExamples of anticipated tasks (not limited to)\n\nAmong these, in this post, you will be working on the following tasks\n\n- Communication and collaboration with developers to increase the value provided\n- Development and operation of self-service tools and platforms\n- Improvement of development processes and environments, not limited to the provision of new tools\n- Besides the team we are recruiting for this time, you may be assigned to other teams depending on your experience and preferences. (In that case, we would be happy to discuss this with you at the interview.)\n- After joining the company, your role may change due to organizational growth or an individual\'s career perspective\n\nInterest And Experience Gained From This Position\n\n- The fun of integrating a complex domain into a system\n- Experience in solving difficult problems with highly motivated team members\n- Experience in contributing to the scale of a product with technical skills\n- Experience in developing products that are deployed globally\n- Experience in providing value to society through the development of products that change\n\nOrganization\n\n- The Platform Department supports engineers in all aspects of product feature development, providing QA, SRE and security expertise across teams, as well as cross-system infrastructure and processing infrastructure\n- The Platform Engineering Team is a newly established team. With the mission of "Unleash the Potential of Developers," we aim to free developers from time-consuming development errands and cognitive load so that they can focus on delivering value\n\nREQUIREMENTS\n\nMUST-HAVE REQUIREMENTS\n\n- 7+ years of hands-on experience developing for web applications\n- Experience in decision-making regarding technology selection, architecture design, and construction for the entire service\n- Experience with Test-Driven Development (TDD). Experience in improving code and system quality through various mechanisms, such as automated execution of Linter, Code Analyzer, API tests, and End-to-End (E2E) tests\n- Hands-on experience with statically typed programming languages (such as TypeScript, Rust, Java/Kotlin, Go, etc)\n- Experience in development using public cloud platforms such as AWS, Google Cloud, etc\n- Fluent business communication skills in English, able to complete daily tasks in English, including text communication and meetings.（CEFR B1 or Higher level)\n- Must currently reside in Vietnam or have plans to relocate. Foreign nationals must also hold a valid Vietnam work permit or be legally eligible to work in Vietnam\n\nNice-to-have Requirements\n\n- Experience of operating container technologies such as Kubernetes\n- Experience of practicing Infrastructure-as-Code\n- Experience of designing and operating CI/CD pipelines\n- Experience of practicing platform engineering in an engineering team of over 50 people\n- Experience working with Scrum or Agile methodologies\n- Conversational-level Japanese proficiency(Japanese Language Proficiency Test N2 or above is a guideline)\n\nWE ARE LOOKING FOR THIS KIND OF PERSON\n\n- Those who can sympathize with CADDi\'s mission "Unleashing the Potential of the Manufacturing Industry"\n- Those who have a T-shaped ambition mindset to maximize their expertise by not only focusing on back-end and infrastructure, but also catching up on peripheral knowledge as needed\n- Those who are able to face essential issues and take action to solve them with a sense of ownership\n- Able to work through positive attitude and constructive discussions in fast-changing and uncertain situations\n- Able to communicate and discuss with an attitude of respect for others, taking into consideration their context and resolution\n\nPRODUCT DEVELOPING ENVIRONMENT\n\n- Front-end: TypeScript, React, Next.js\n- Backend: Rust(axum), TypeScript, Node.js (Express, Fastify, NestJS)\n- Machine Learning/Algorithms: Rust, Python, OpenCV, PyTorch, TorchServe, Elasticsearch, Vertex AI\n- Infrastructure: Google Cloud, Google Kubernetes Engine, Anthos Service Mesh, Istio, Cloudflare, Argo Workflows\n- Event Bus: Cloud Pub/Sub\n- DevOps: GitHub, GitHub Actions, ArgoCD, Kustomize, Helm, Terraform, Datadog, MixPanel, Sentry\n- Data: CloudSQL (PostgreSQL), AlloyDB, BigQuery, dbt, trocco\n- API: GraphQL, REST, gRPC\n- Authentication: Auth0\n- Development tools: GitHub Copilot, Figma, Storybook\n- Communication Tools: Slack, Discord, JIRA, Miro, Confluence\n\nRECRUITING STEPS\n\n- CV screening\n- Technical assignment (online coding test) * We place more importance on whether you can imagine that you can work together with us to develop a product, rather than on your knowledge of algorithms or the speed of your answers\n- Online English speaking test\n- Technical interview (with engineer)\n- HR casual talk *This stage does not involve selection criteria; it serves as an opportunity to align on conditions and clarify any questions regarding the selection process\n- Final interview (with CTO)\n- Offer meeting\n- Please note that, depending on the situation, additional interviews or discussions may be proposed\n- If desired, we can arrange casual interviews with employees even during the selection process. Please feel free to consult with us\n- The average time from application to offer is about one month, but if you are in a hurry, please let us know. We will do our best to adjust the schedule to fit your job search timeline\n\nBenefits\n\nAPPLICATION GUIDELINES & BENEFITS\n\n- Working style:\n- Hybrid (come to Office at least once a week)\n- Remote (depending on the case, and limited to those who can go on business trip due to Company orders)\n- Office address:\n- HCMC: 7F, Gia Loc Building, No. 27-29 Nguyen Cuu Van Street, Ward 17, Binh Thanh District, HCMC\n- Hanoi: Room 508, 5F, IDMC My Dinh, 15 Pham Hung Street, My Dinh 2 Ward, Nam Tu Liem Distrist, Hanoi\n- Employment type:\n- Official full-time employee\n- Probation period: 2 months\n- Holidays and leave:\n- Annual paid leave: 12 days\n- National holidays\n- Year-end holidays (December 31 to January 3)\n- Tet holidays\n- Others (following Labor Regulations)\n- Benefits:\n- 13th month salary\n- Salary review: twice a year\n- 100% monthly basic salary and mandatory social insurances in 2-month probation\n- Premium Health Insurance\n- Social insurance, health insurance, unemployment insurance, workers\' accident compensation insurance\n- Annual health check-up\n- Allowances such as: child-care allowance, commuting allowance, life event congratulatory gift, etc\n- Growth support such as subsidy for server fee, support for attending external training courses\n- Intensive training program (external or internal training courses, workshop etc)\n- Devices: PC and display of desired specifications\n- Awards: Company awards, every 6 month MVP awards\n- Activities: Year-end-party, team building, etc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1926, 711, 2, 'Senior Java Full-Stack Developer(Onsite Q7)', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business with a bold vision of our world’s potential. We’re people-centric and here to power good. Every day, we future-proof urban spaces, conserve natural resources, protect rainforests, and save lives. This is a world where innovation, technology, and deep expertise come together to take our company and customers from what’s now to what’s next. We make it happen through the power of acceleration.\n\nImagine the sheer breadth of talent it takes to bring a better tomorrow closer to today. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally as important to us.\n\nThe role\n\nSenior Full-Stack (Onsite in Q7, HCM)\n\n- 5 Years + experiences in similar roles.\n- Intermediate or upper skills on Oracle/MongoDB and Java Spring boot, microservice, React web app\nHard skills: Oracle, SQL, MongoDB\n- Plus: microservice, AKS, Jenkins, GIT, Fortify, Snyk Code, Sonar Queue\n- Write high quality source code to program complete applications within deadlines.\n- Perform unit and integration testing before launch.\n- Conduct functional and non-functional testing.\n- Troubleshoot and debug applications.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1927, 900, 2, 'Senior Java Developer', 'I. Key Accountabilities:\n\nA. Software Development\n• Responsible for ensuring that the bank\'s digital platforms work well by managing back end site databases, performance issues, security and that the server, application and database communicate with each other.\n• Responsible for collaborating with business tribes to understand the needs and technical requirements before building a web application.\n• Responsible for the server-side web application logic and integration with front-end codes\n• Collaborate with Front End Developers to design more functional and cohesive codes to enhance user experience.\n• Responsible for driving the application lifecycle with a key focus in coding and debugging of web applications based on feedback from testers and users.\n• Compile and analyze data, process and codes to troubleshoot problems and identify areas for improvement.\n\nB. Software Documentation\n• Work closely with tribe and squad members to translate business requirements into technical design documents.\n• Review and implement technical requirement documents by coding flowcharts, layouts, diagrams, charts, code comments and guides for the program.\n\nII. Requirements:\n\nA. Domain Expertise\n• 4+ years of relevant experience in software development in Finance - Banking domain\n• Solid foundation in Java programming.\n• Experience in development on ESB, API platforms, and Kafka platforms.\n• Understanding of SOAP and RESTful services, with knowledge of message standards such as JSON and XML.\n• Basic knowledge of databases such as Oracle, MS SQL, etc.\n• Experience using tools such as FTP, SSH, and XML editors.\n• Familiarity with CI/CD toolchains: Git, Jenkins, Maven, Nexus, etc.\n• Possess ESB/API certifications from Oracle/IBM/TIBCO, Mulesoft, etc.\n• Experience in programming with XQuery and XSLT.\n• Experience in AWS (bonus point)\n\nB. Agile / Digital Experience\n• Understands Agile principles, practices and Scrum methodologies.\n• Experience working in Agile teams to support digital transformation projects.\n\nC. Qualifications\n• Bachelor\'s degree in computer science, software engineering or information technology\n\nD. Personal Attributes\n• Passionate about technology and excited about the impact of emerging / disruptive technologies\n• Ownership mindset with a focus on getting things fixed, not simply discovered\n• A self-starter who thrives in an environment that fosters entrepreneurial thinking and innovation\n• Believes in the non-hierarchical culture of collaboration, transparency and trust across the team\n\nIII. Working location: HO Techcombank - Hanoi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ハノイ首都圏', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1928, 887, 2, 'Front End Flutter Developer', 'LG CNS is a leading IT service provider from South Korea, specializing in digital transformation, cloud, AI, and smart factory solutions. At LG CNS Vietnam Build Center, we develop global-scale digital products and systems, working closely with international teams. We are expanding rapidly and looking for talented developers to join our journey.\n\nDevelop cross-platform mobile applications using Flutter (Android/iOS).\nCollaborate closely with UI/UX designers and back-end developers to deliver a seamless user experience.\nIntegrate mobile applications with back-end APIs.\nWrite clean, maintainable, and scalable code following best practices.\nEnsure the performance, quality, and responsiveness of applications.\nDebug, optimize, and improve existing mobile applications.\nParticipate in code reviews, knowledge sharing, and agile development processes.\nStay updated with the latest trends and technologies in mobile development.\n\nRequirement\n\n[Required]\n\n3 years + of experience in mobile development using Flutter.\nSolid understanding of mobile application architecture and responsive UI design.\nFamiliar with state management solutions (Provider, Riverpod, Bloc, etc.).\nGood understanding of RESTful APIs integration.\nExperience with version control tools (Git).\nAbility to work collaboratively in a team environment.\nIntermediate English skills (for documentation reading and basic communication).\n\n[Preferred]\n\nExperience with native mobile development (Android/Kotlin, iOS/Swift) is a plus.\nFamiliar with CI/CD pipelines for mobile applications.\nKnowledge of mobile application deployment processes to App Store and Google Play.\nUnderstanding of AWS Mobile services or Firebase is an advantage.\n\nOpportunity\n\nAttractive salary and bonus will be discussed after going through CV & Interview.\nTopik allowance.\nReview capacity annually and adjust salary increases according to work performance.\nHealth care: Premium health insurance, Annual health check-up.\nYoung working environment.\nGood career development opportunities with interesting and challenging projects.\nEnglish, Korean, technical, soft skills training courses.\nOpportunity to learn special courses from LG CNS, new technology and security.\nGifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.).\nOutdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\nWorking hours: 8 hours from Monday - Friday (8 hours/day).\n\nLocation\n\nOnsite 15th Floor, Keangnam Landmark 72, Me Tri, Nam Tu Liem, Hanoi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Région métropolitaine de Hanoï', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1929, 943, 2, 'Full-stack Developer (VueJS + PHP) - Vietnam', 'At Globant, we are working to make the world a better place, one step at a time. We enhance business development and enterprise solutions to prepare them for a digital future. With a diverse and talented team present in more than 30 countries, we are strategic partners to leading global companies in their business process transformation.\n\nWe seek a Full-stack Developer (VueJS + PHP) - Senior Level who shares our passion for innovation and change. This role is critical to helping our business partners evolve and adapt to consumers\' personalized expectations in this new technological era.\n\nYou will get the chance to:\n\n- In accordance with company coding conventions, approved designs and design standards, perform appropriate coding, code reviews, debugging, bug fixing, code testing and unit testing, and other related supplementary activities.\n- Participate in the creation/update of technical documentation (e.g. Requirements Document, Functional Design, Interaction Design, Technical Design, etc.)\n- Communicate in a clear and structured manner with clients, peers, and managers\n- Follow agreed-upon team or project processes and procedures, including reporting to superiors on the status of project/release/task efforts and key issues.\n- Diagnose software, system, and hardware failures that impact deployment\n- Provide production support when needed.\n\nWhat will help you success:\n\n- 6+ years of Vue.js, PHP and JavaScript development experience\n- Strong knowledge of object-oriented programming and software design patterns\n- Solid understanding of MySQL and database optimization techniques\n- Experience with unit testing frameworks (e.g., PHPUnit)\n- Familiarity with web application security standards\n- Proficiency with version control systems like Git\n- Strong problem-solving skills and attention to quality\n- Ability to work independently and in a collaborative team\n- Proficient in English (written and spoken)\n\nThis job can be filled in Hanoi/Danang or Ho Chi Minh.\n\nCreate with us digital products that people love. We will bring businesses and consumers together through AI technology and creativity, driving digital transformation to impact the world positively.\n\nAt Globant, we believe in fostering a diverse and inclusive workplace where everyone feels valued and respected. We are an Equal Opportunity Employer committed to creating a thriving and inclusive environment for all employees and candidates, regardless of race, color, religion, sex, sexual orientation, gender identity, national origin, age, disability, veteran status, or any other legally protected characteristic. If you need any assistance or accommodations due to a disability, please let us know by applying through our Career Site or contacting your assigned recruiter.\n\nWe may use AI and machine learning technologies in our recruitment process. Compensation is determined based on skills, qualifications, experience, and location. In addition to competitive salaries, we offer a comprehensive benefits package. Learn more about our commitment to diversity and inclusion and Globant’s Benefits.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1930, 739, 2, 'Developer Fullstack', 'Company Description\n\nThe SOCOTEC Group offers its customers and partners missions throughout the life cycle of infrastructure and buildings to ensure compliance, extend their lifespan, improve their technical, energy and environmental performance, and thus guarantee the safety of people. Independent trusted third party and with offices in 26 countries and more than 11,300 people.\n\nSOCOTEC is a leading player in risk management and technical advice in the world. Established in Vietnam since 2018, SOCOTEC Vietnam works closely with colleagues in France, Germany, Italy, UK, USA, Spain, Netherlands and other SOCOTEC offices. For our office in Hanoi, we are looking immediately for a Technical Reporting Engineer\n\nQualifications\n\n• Strong analytical skills, ability to translate requirements into functional code.\n• Experience of development in Java (Or Similar Object Orientated Language)\n• Experience of development in Javascript\n• Knowledge of SQL scripting/querying, Database design & development\n• Good problem solving abilities\n• Good knowledge of network, OS and wider infrastructure supporting business solutions\n• Knowledge Angular Front End/ Spring Platform/ REST and Web API’s/MSSQL/TSQL/Docker/ Kafka or similar Service Bus technology is preferred\n\nAdditional Information\n\n• Attractive salary and bonus with annual revision\n• Compulsory insurance pay as gross monthly salary\n• Flexible working time with 12 annual leave days & 15 work from home days\n• Team-building activities, Sport Clubs\n• Cooperation with colleagues around the world in a leading global group\n• Strong team spirit in an entrepreneurial environment of a growing company\n• People values, social responsibility and sustainability\n• Opportunities for self-development and career advancement\n• Internal training courses (technical, foreign language, soft skill)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Đình Ba فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1931, 822, 2, '[Cloud BI] Senior/Principal Frontend Engineer (ReactJS)', 'Join our innovative team as a Senior Frontend Engineer and take a key role in shaping the user experience of our BI application. You’ll be responsible for designing and building responsive, high-performance, and intuitive web interfaces for our user-facing applications. This is a unique opportunity to create modern, elegant solutions while collaborating closely with talented backend, data, and QA engineers to deliver robust and impactful products in the data and AI domain.\n\nResponsibilities:\n- Frontend Architecture & Development: Design, implement, test, and optimize modern frontend applications using cutting-edge web technologies.\n- User-Centric Design: Collaborate with product managers and designers to create user-friendly, accessible, and visually compelling interfaces that align with business goals.\n- Testing & Quality Assurance: Develop and maintain comprehensive unit, integration, and end-to-end test suites using tools such as Jest, React Testing Library, Cypress, and Playwright to ensure reliability and robustness.\n- API Integration: Build seamless and efficient interactions between the frontend and backend APIs, ensuring responsive, real-time, and secure experiences, including robust authentication and authorization mechanisms.\n- Performance Optimization: Monitor, profile, and enhance frontend performance to ensure a smooth and consistent experience for users.\n- Code Quality: Write clean, maintainable, and well-tested code that adheres to engineering best practices and team standards.\n- Cross-functional Collaboration:\n  - Partner with backend engineers to define and refine API contracts.\n  - Work with QA engineers to ensure UI testability and overall product quality.\n  - Collaborate with data engineers to integrate frontend data visualizations and analytics.\n- Mentorship: Share knowledge, review code, and mentor junior frontend engineers to help them grow in their roles.\n\nRequirements:\nTechnical Skills:\nMust Have:\n- 5+ years of professional experience in frontend web development.\n- 3+ years of hands-on experience with React.js and TypeScript.\n- Deep understanding of component-based architecture and modern state management (e.g., Redux, Context API).\n- Web Performance Optimization Techniques, especially concerning the efficient rendering of numerous and complex data visualizations.\n- Cross-browser compatibility and accessibility best practices.\n- Web security fundamentals (e.g., XSS, CSRF, injection attacks) relevant to frontend development.\n- Experience with modern build tools (e.g., Vite, Turbo, Webpack).\n- Exposure to data visualization libraries (e.g., D3.js, Chart.js).\n- Experience consuming and integrating GraphQL-based or RESTful APIs.\n- CI/CD pipelines and Git-based workflows.\n- Docker and containerized development environments.\n- Agile development processes.\n\nNice To Have:\n- Experience with server-side rendering (SSR).\n- Advanced experience in data integration from multiple backend services.\n- Familiarity with backend development or reading backend code (e.g., Golang, Python).\n- Familiarity with cloud platforms (e.g., AWS) and frontend monitoring tools (e.g., Datadog, Sentry).\n\nCommunication:\n- Strong collaboration skills with experience working in cross-functional engineering teams.\n- Experience mentoring or supporting the growth of other frontend developers.\n- High sense of ownership, accountability, and proactive problem-solving mindset.\n- Business-level English proficiency (reading and writing required).\n\nOur benefits:\nCaring Mental & Physical Recreation:\n- Hybrid working: 2 days at the office and 3 days WFH.\n- Working hour: Flexible start 8AM-9AM from Mon-Fri.\n- Full salary in probation.\n- Insurance: Applied from Probation period: Social Insurance, Health Insurance, Unemployment Insurance.\n- Bonus: 13th month salary.\n- 16 - 24 paid days off and more.\n- Paternity leave: Extra 5 days.\n- Annual company trip; Quarterly team building.\n- Billiards & Running club.\n- Annual health check.\n- Well-equipped facility: Macbook pro, additional monitor.\n\nCaring Career & Development:\n- Clear Career path.\n- Foreign language & International technology-related certifications sponsoring.\n- External & internal training courses.\n- Soft-skill workshops.\n- Tech seminars.\n- Monthly and biannual Recognition Awards.\n- Performance & salary review: twice/year (Jun & Dec).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1932, 442, 2, 'Intermediate Backend Software Engineer (.NET)', 'Who We Are\n\nEmployment Hero is on a mission to make employment easier and more valuable for everyone. Our Employment Operating System brings hiring, HR, payroll and benefits into an all-in-one solution.\n\nSince our inception in 2014, we\'ve scaled to a $2 billion valuation and gained a presence in 6 countries globally - Australia, New Zealand, Singapore, Malaysia, the UK and Canada. We now service over 300,000 businesses and more than 2 million employees.\n\nThe EH Way\n\nAt Employment Hero, we\'re proud of our unique DNA, which we call The EH Way.\n\nWe are Mission First - everything we do (from what we work on, to how we allocate capital and where we focus) is driven by our Mission\nWe are Remote First - we champion a remote environment with a preference for asynchronous communication and a high degree of autonomy \nWe are AI First - we are committed to using AI to accelerate our mission; AI is not just a tool, it\'s a fundamental part of how we operate, innovate, and scale\nWe are Apolitical - we do not take a position on political or social topics, unless it relates to our Mission\nWe Live by Our Values - we role model our values 100% of the time\nWe Expect High Performance - we set a high standard and we\'re not satisfied with being average\n\nAbout The Role\n\nOur Partnerships and Payroll team are growing. We\'re looking for an amazing Intermediate Software Development Engineer (.Net) to join us as we scale our products and features and take on interesting technical challenges.\n\nThis role will help us continue the development and modernising of our Payroll system as we look to continue to expand into new regions.\n\nYou\'ll be able to learn from our cross-functional teams, including working with geographically distributed teams. You\'ll accelerate your career quickly, in a fully remote, flexible and casual environment.\n\nAs our Software Development Engineer, you\'ll look after {\n\nEnd-to-end development for new and current cloud-based applications, from working on the technology roadmap with Product Owners, designing solutions with your squad, new feature development, through to production, improving/optimising and maintenance\nDebug and perform root cause analysis for application issues\nTake initiative in recommending improvements to the development processes\nProactively identify application pain points and suggest mitigation strategies\nPerform peer reviews of code changes\nPerform testing of new features/enhancements/bug fixes\nMaintain documentation and help articles for new/updated features\nProvide training sessions for the support team for new features\nWork closely with business stakeholders within an agile environment\n\nRequirements\n\nTo excel in this role, you should possess the following qualifications:\n\nExtensive experience as a .NET Software Development Engineer\nExperience with C#, ASP.NET MVC, .NET Core\nExperience in SQL Server\nKnowledge of the following (or similar) frameworks:\nExperience in NHibernate (or similar persistence or ORM framework such as Microsoft Entity Framework or Dapper)\nExperience in NUnit / XUnit (unit testing)\nExperience in Castle Windsor (or similar dependency injection/IoC framework, such as Autofaq or Ninject)\nExperience with agile methodologies and test-driven development techniques\n\nNice to have skills / experiences (not required, but advantageous)\n\nExperience in Knockout, VueJS, ReactJS (or similar JavaScript MVVM framework)\nExperience in AWS Cloud environments\nExperience in the Payroll domain\n\nWhat We Can Offer\n\nAt Employment Hero, we don\'t just talk about a better way to work - we live it. Joining Employment Hero means\n\nYou will work remotely, with the flexibility to own your time and impact\nYou will access cutting-edge tools to amplify your work, knowledge and outputs\nYou\'ll surround yourself with ambitious, outcome-driven colleagues who challenge you to do the best work of your life\nYou\'ll own ESOP (employee share options) in one of the world\'s fastest-growing tech companies\nYou\'ll also have access to a wide range of benefits that includes - a very generous paternity leave policy, subsidised egg freezing (so you can make the choice that\'s right for you, on your terms), a WFH office expense budget, and outstanding learning & development opportunities\nAt Employment Hero, we are committed to safeguarding the privacy of your application data. To understand how we do so, you can read our Applicant Privacy Policy here. Employment Hero celebrates diverse perspectives and experiences, we invite people of all backgrounds and identities to apply for this position.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1933, 527, 2, 'Analytics Engineer - BI & Planning', 'The Analytics Engineer will work closely with Functional BI teams and business users to understand the data logic and workflow, then architect and build solutions to automate the data flow and manual tasks.\n\n- Automation\n- Partner closely with stakeholders across business units and Functional BI teams to understand their challenges and translate requirements into technical solutions\n- Drive process automation by developing intelligent tools for eKYC processing, tax validation, and other critical business operations\n- Data Engineering\n- Build robust data foundations by designing and implementing scalable ETL processes that seamlessly extract, transform, and load data from our internal platforms\n- Architect data pipelines that integrate smoothly with existing systems and power automated workflows across the business\n- Optimize data infrastructure including local tables, data models, and data mart architecture for peak performance and reliability\n- Analytics Modelling Implementation and Maintenance\n- Implement and maintain predictive analytics and automated data processing solutions\n- Write SQL queries and Python code that support features engineering and EDA in complex datasets\n- Data Quality and Governance\n- Maintain code quality through disciplined source control practices, branch management, and collaborative code reviews\n- Ensure system reliability by monitoring, troubleshooting, and optimizing data pipeline performance\n\nRequirements\n\n- Bachelor’s degree in Computer Science, Software Engineering, or related field\n- 2+ years of experience in data engineer role or similar role\n- Strong SQL skills with experience writing complex queries for data extraction and transformation\n- Strong proficiency in Python for developing automation solutions, and experiencing using libraries for data processing, API integration, and system automation\n- Experienced with ETL processes and data pipeline development in various databases and data pipeline development\n- Able to communicate complex business or technical information effectively\n- Strong camaraderie, analytical skills, problem-solving solving and solution-oriented mindset, especially when issues arise\n- Take initiative and show flexibility in a fast-paced environment\n- Experience with AI/ML implementation in business processes\n- Data engineer certification (e.g., IBM Certified Data Engineer) is a plus\n- Experience in RPAframework\n- Background in e-commerce industries', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Tsji Minhstad, Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1934, 767, 2, 'MMORPG Server Developer (Games)', 'Job Description ( Mô Tả Công Việc)\n\n• Development of MMORPG game servers\n• Development of game service operation environments and tool\n\nGeneral Competencies ( Yêu cầu năng lực chung)\n\n• Passion and dedication to game development\n• Positive attitude and proactive communication skills\n• Strong sense of responsibility for assigned tasks\n• Logical thinking and creative problem-solving abilities\n\nJob-Specific Skills (Kỹ năng chuyên môn cho công việc)\n\n• Understanding and implementation of object-oriented programming\n• Understanding and implementation of multithreaded programming\n• Understanding and implementation of network programming\n• Database schema design and procedure implementation skills\n• Understanding and implementation of various data structures and algorithms\n\nPreferred Qualifications (Kỹ Năng Ưu Tiên)\n\n• Experience in online game server development\n• Experience using commercial server engines\n• Experience in development within Linux environments', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه Quận 7 فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1935, 1040, 2, 'C/C++ Developer', 'CHI TIẾT CÔNG VIỆC\n• Tham gia phát triển ứng dụng FPT Play trên nền tảng Set-Top-Box\n• Làm việc theo mô hình Agile/Scrum.\n• Sử dụng git để quản lý code, sử dụng Jira/Confluence để quản lý task và tài liệu.\n• Kiến trúc, review code, tối ưu để tăng trải nghiệm.\n• Phân tích, đánh giá và lập kế hoạch phát triển, trao đổi nhóm, để đưa ra các nhiệm vụ cần thực thi liên quan.\n• Cập nhật xu hướng phát triển công nghệ mới để áp dụng vào dự án.\n• Tích hợp các giải pháp: DRM ,Watermarking, AI, ...\n• Làm các dự án khác theo sự phân công của quản lý đơn vị.\n\nYÊU CẦU CÔNG VIỆC\n• Thành thạo C/C++, hiểu cơ bản về quản lý bộ nhớ, đa luồng.\n• Có kinh nghiệm phát triển phần mềm trên Linux.\n• Có kiến thức căn bản về media playback (video/audio), các giao thức HTTP, socket, và streaming (HLS, DASH).\n• Sử dụng được các công cụ debug như: gdb, logcat, valgrind.\n• Làm việc nhóm tốt, giao tiếp rõ ràng, chủ động.\n• Biết đọc tài liệu kỹ thuật, tư duy hệ thống, có khả năng tự tìm hiểu và debug.\n• Từng làm UI với DirectFB hoặc thư viện đồ họa nền framebuffer là lợi thế.\n• Ưu tiên có hiểu biết về FFmpeg, GStreamer, tối ưu playback\n\nQUYỀN LỢI\n• Gói thu nhập năm tương xứng với năng lực (13 tháng lương, nghỉ mát...)\n• Làm việc trong môi trường năng động, chuyên nghiệp có nhiều cơ hội thăng tiến\n• Cung cấp trang thiết bị đầy đủ để phục vụ công việc\n• Văn hóa doanh nghiệp đa dạng, phong phú; các hoạt động tri ân, chăm lo đời sống tinh thần Cán bộ nhân viên và người thân, Teambuilding, Ngày hội văn hóa, các Câu lạc bộ...\n• Tham gia đầy đủ các chế độ theo Luật lao động hiện hành (BHXH, BHYT, BHTN, ngày phép)\n• Khám sức khỏe định kỳ, nghỉ hè hàng năm; Gói bảo hiểm sức khỏe chuyên biệt FPT Care\n• Được tham gia các khóa đào tạo, nâng cao nghiệp vụ thường xuyên\n• Hưởng các gói ưu đãi cước khi sử dụng dịch vụ của FPT Play.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1936, 709, 2, '[HÀ NỘI/HẢI PHÒNG/BÌNH DƯƠNG] GIÁO VIÊN FULLTIME CÔNG NGHỆ & STEM', 'Giáo viên/Chuyên môn\nTừ 1 năm kinh nghiệm\n\nLiên Hệ Ứng Tuyển Tại\ntuyendung@teky.edu.vn hoặc 02471096668\n\nThu nhập: 8.000.000 - 12.000.000 đồng/tháng\nHạn nộp hồ sơ: 31.10.2024\nPhòng ban: Giáo viên/Chuyên môn\nThời gian làm: Fulltime\nKhu vực: Hà Nội, Bình Dương, Quảng Ninh, Hải Phòng\nSố lượng: 20\n\nGửi hồ sơ ứng tuyển\n\nThông tin công việc\nThời gian làm việc: Đăng kí theo ca lịnh hoạt (Ca sáng: 8h00-12h00; Ca chiều: 13h00-17h00; Ca tối: 17h00-21h00. Làm việc 44h/tuần tương đương 11ca/tuần (Nghỉ 1,5 ngày/tuần)\nNơi làm việc:\n- Teky Hà Đông: Số B-TT01-51-53 Khu nhà ở Ngân Hà Vạn Phúc, phường Vạn Phúc, quận Hà Đông, TP Hà Nội\n- Teky Hoàn Kiếm: Số 96 Hai Bà Trưng, Cửa Nam, Hoàn Kiếm, Hà Nội\n- Teky Cầu Giấy: Tầng 3, Toà Nhà Thanh Chân, Số 6 Nguyễn Thị Thập Trung Hòa Nhân Chính, Quận Cầu Giấy, Hà Nội\n- Teky Long Biên: Số 414 Nguyễn Văn Cừ, Bồ Đề, Long Biên, Hà Nội\n- Teky Hải Phòng: 73 Điện Biên Phủ, Minh Khai, Hồng Bàng, TP Hải Phòng\n- Teky Hạ Long: SH4 Times Garden, Đường 25 tháng 4, Bạch Đằng, Hạ Long, Quảng Ninh\n- Teky Bình Dương: 422 đại lộ Bình Dương, Phường Hiệp Thành, Thành Phố Thủ Dầu 1, Bình Dương\n- Teky Minh Khai: Tầng 3, số 463 Minh Khai, Vĩnh Tuy, Hai Bà Trưng, Hà Nội\n- Teky Linh Đàm: Biệt thự 27, TT4A Khu Biệt Thự Tây Nam Linh Đàm, Hoàng Liệt, Hoàng Mai, Hà Nội.\n- Teky Bắc Từ Liêm: LKC37, Dự án khu nhà ở thấp tầng A1TT1, Xuân Tảo\n\nMÔ TẢ CÔNG VIỆC\n- Tham gia giảng dạy hoặc trợ giảng đối với các Bộ môn Lập trình (ngôn ngữ: Python, Scratch, HTML, CSS, PHP, Java,…..) hoặc Điện tử – tự động hóa (Arduino, Raspberry Pi, Lego, v.v..) hoặc Bộ môn Truyền thông đa phương tiện, mỹ thuật, thiết kế đồ hoạ, 3D Max, quay phim, chụp hình.\n- Tham gia hoạt động nghiên cứu và phát triển giáo trình, giáo án giảng dạy, bài tập; xây dựng hệ thống học liệu theo sổ tay phương pháp giảng dạy của Teky được phát triển trên cơ sở chuẩn đào tạo khoa học máy tính và mô hình STEM của Mỹ.\n- Tham gia công tác phát triển nguồn lực thuộc tổ/bộ môn phụ trách, bao gồm xây dựng đội ngũ, đào tạo huấn luyện giảng viên/trợ giảng cộng tác.\n- Báo cáo quá trình giảng dạy, trực tiếp đánh giá khả năng tiếp thu của học sinh và kết quả học tập cuối cùng, nhằm đưa ra phương án điều chỉnh, nâng cấp giáo trình.\n- Có trách nhiệm tham gia tư vấn về bộ môn học cho phụ huynh; Xây dựng và phát triển quan hệ với phụ huynh nhằm duy trì việc học tập của học sinh tại học viện.\n- Tham gia các hoạt động sự kiện ngày hội trải nghiệm công nghệ, workshop cho phụ huynh, học sinh.\n- Thực hiện các yêu cầu khác của Khối đào tạo chuyên môn.\n\nYÊU CẦU CÔNG VIỆC\n- Tốt nghiệp cao đẳng/ đại học/cao học khoa Công nghệ thông tin, khoa học máy tính, điện tử, sư phạm Toán/Tin/Vật Lý, kiến trúc, thiết kế, mỹ thuật.\n- Ưu tiên có kinh nghiệm làm lập trình viên hoặc giảng dạy một trong các ngôn ngữ lập trình sau: PHP, PYTHON, JAVA, JAVASCRIPT, HTML, CSS, SCRATCH.\n- Ưu tiên có kinh nghiệm tối thiểu 1 năm giảng dạy về 3D, mỹ thuật, mầm non.\n- Ưu tiên có kinh nghiệm tối thiểu 1 năm giảng dạy về arduino, raspberry, điện tử.\n- Kỹ năng truyền đạt, khả năng giao tiếp tốt, tự tin trước đám đông.\n- Yêu trẻ, hiểu tâm lý trẻ và yêu thích công việc giảng dạy.\n- Cẩn thận, thái độ làm việc nghiêm túc.\n- Ưu tiên ứng viên có khả năng đọc hiểu tài liệu tiếng Anh.\n- Có hiểu biết về STEAM là một lợi thế.\n\nVẬY VỀ VỚI TEKY THẦY CÔ SẼ CÓ GÌ?\n- Mức lương khởi điểm: 8.000.000đ – 12.000.000đ/tháng. Lương thưởng thỏa thuận theo năng lực, có thể trao đổi trực tiếp trong buổi phỏng vấn.\n- Được hưởng đầy đủ các chế độ theo quy định của nhà nước (BHXH, BHYT, BHTN).\n- Tham gia môi trường văn hoá năng động, trẻ trung, cơ sở vật chất hiện đại; kết hợp giữa hai lĩnh vực công nghệ và giáo dục; đóng góp giá trị cho xã hội.\n- Được đào tạo nâng cao về phương pháp giảng dạy STEM theo chuẩn Mỹ.\n- Được tìm hiểu và tiếp cận giáo trình, giáo án, chương trình giảng dạy chuyên nghiệp. Cơ hội làm việc trực tiếp tham gia các dự án giáo dục mang tính quốc tế cao, có sự tham gia của các doanh nghiệp hàng đầu về giáo dục và công nghệ tại Mĩ, Hàn Quốc, Nhật Bản.\n- Được tham gia vào các hoạt động đào tạo, workshop từ chuyên gia trong lĩnh vực, trong nước và quốc tế.\n- Được đi du lịch ít nhất 1 lần 1 năm, liên tục tham gia Teambuilding.\n- Hưởng các chế độ khác ngoài lương theo định kỳ hoặc không định kỳ.\n\nThông Tin Liên Hệ\n- Email nhận CV ứng tuyển: tuyendung@teky.edu.vn\n- Email ghi rõ: Địa điểm làm việc_Tên vị trí ứng tuyển_Họ và tên\n\nGửi hồ sơ ứng tuyển.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Huyện Hải Hà, Quang Ninh, Viet Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1937, 685, 2, 'AI Developer (Vietnam)', 'As an AI Developer, you will design, develop and implement AI-enhanced applications. You will analyze data sets to identify patterns, create frameworks and develop predictive algorithmic models to deliver intelligent systems that are capable of performing tasks that usually require human cognition in order to solve complex business problems and for faster business processing.\n\nSpecifically, you are expected to:\n\n- Design, develop, optimize, and implement AI systems to meet business requirements.\n- Monitor the performance of deployed scalable AI models and frameworks, making necessary adjustments or updates to improve accuracy and reliability, and address any issues or bugs that arise during the system\'s operation.\n- Collaborate with cross-functional teams to analyze the business needs and define problems to identify the goals and requirements of AI systems.\n- Work closely with the development team to ensure seamless AI development and integration, and define APIs and protocols for communication between AI systems and external services.\n- Document AI models and infrastructure, processes, and practices for reference, and present progress to the leadership team and stakeholders.\n- Implement strong data security and privacy measures for data handled in AI applications.\n- Stay current with emerging AI research and technologies, and initiate innovative solutions & improvements to advance our AI capabilities.\n- Conduct training and share knowledge & expertise in AI to the team.\n\nYour profile:\n\n- Bachelors degree in Computer Science, IT, Data Science, or any related field.\n- 2 years of experience with AI development, Natural Language Processing, and Large Language Models.\n- Proven track record of deploying AI models in production.\n- Proficiency in programming languages such as Python, JavaScript, or C++.\n- Knowledge of SQL and NoSQL databases.\n- Experience with machine learning frameworks and libraries (TensorFlow, Keras, PyTorch, Scikit-learn).\n- Familiarity with machine learning models & algorithms, cloud computing platforms (AWS, Microsoft Azure, Google Cloud Platform), containerization (Docker, Kubernetes), deep learning and concepts of Natural Language Processing (NLP) and/or Natural Language Generation (NLG).\n- Eagerness to learn and continuously expand knowledge in emerging fields.\n- Has strong interpersonal and communication skills with a willingness to collaborate with different teams.\n\nOthers:\n\n- This is for a hybrid work setup.\n- Successful completion of background check and NBI clearance will be required.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Ho-Chi-Minh-Stadt', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1938, 899, 2, 'Junior AWS Devops', 'Job Description\n\n- Manage networking protocols (TCP/IP, HTTP, SOCKET) and use Linux command line and bash scripts for automation.\n- Build and deploy applications using Dockerfile and docker-compose.\n- Work with Kubernetes (k8s) and Helm charts for container orchestration and deployment.\n- Design and manage infrastructure on AWS (EKS, ECS, Lambda, RDS, Elasticache, CloudWatch).\n- Use Terraform to build and manage AWS infrastructure, customizing modules for reuse.\n- Automate configuration tasks using Ansible.\n- Develop and maintain CI/CD pipelines for build, test, and deployment.\n- Update and customize CI/CD pipelines as necessary.\n- Write code in at least one programming language (Python, Node.js, Java, Go, Rust).\n- Troubleshoot and resolve technical issues quickly.\n- Experiment with and test new technologies to improve system performance.\n\nJob Requirements\n\n- 1+ year in the relevant domain or technology and proficient in English.\n- Strong knowledge of TCP/IP, HTTP, and SOCKET.\n- Proficient in using the Linux command line and writing bash scripts.\n- Strong skills in using Dockerfile and docker-compose for building applications.\n- At least 6 months of experience working with Kubernetes (k8s) and Helm charts.\n- Experience building infrastructure on AWS services (EKS, ECS, Lambda, RDS, Elasticache, CloudWatch).\n- Experience using Terraform to build infrastructure on AWS (in real-world projects).\n- Experience customizing Terraform modules for AWS services for reuse.\n- Proficiency in using Ansible (a plus).\n- Experience building complete CI/CD pipelines for build/test/deploy of new source code.\n- If only involved in operations, must understand and have experience in updating/customizing pipelines.\n- Proficiency in at least one programming language (Python, Node.js, Java, Go, Rust, etc.).\n- Quick problem-solving abilities and a passion for experimenting with new technologies.\n\nCompensation & Benefits\n🎯Flexible working regime and health care:\n\n- Flexible timekeeping (from 8:00 - 9:00 to 17:30 - 18:30) \n- Minimum 14 paid leaves per annum for all employees after probation\n- 01-day remote work per month\n- A flexitime allowance of 90-180 minutes per month for employees\n- 01 hour paid leave per day for women having children under 12 months\n- Social insurance, health insurance, unemployment insurance and MIC care insurance \n\n🎯Transparent And Fair Benefits\n\n- Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n- Work performance review 2 times/ year (in April and October)\n- 13th-month salary\n- Bonus Policy: Public holidays (2/9, 30/4, 1/5, 1/1,...); Personal Performances; Excellent Team; Performance bonus in Token of the project;.. \n- Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company\n\n🎯Dynamic Environment And Open Culture\n\n- Year-end party, sports day, yearly company trip and quarterly team building,...with a generous budget\n- Socialize with colleagues through monthly Happy Hour \n- Monthly allowance when joining clubs: Soccer, Swimming, Yoga, Music,... \n- Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks,...\n- Flat, open and sharing culture with friendly management team; outsourcing company with product mindset \n\n🎯Strong Learning Culture\n\n- Free training courses for technical and soft skills (presentation skills, communication skills, foreign language courses,...)\n- Account to log in to our online learning system, which contains thousands of valuable lectures (LMS)\n- Participate in workshops, seminars, tech talk,... with sharing from experts inside and outside the company\n- Working opportunities with technical gurus who built and operated world-class applications with millions of users.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1939, 856, 2, 'C/C++ Software Engineer', 'Life‘s good with LG!\nLGEDV conducts core R&D activities, and various product reliability tests in support of our business. With the key missions of offering an environment that enables colleagues to demonstrate their capabilities, focus on their work and create value & delivering the “invaluable” office operation services & solutions that contributes to a company’s business success.\n\nDESCRIPTION\n(1) As a member of LGEDV VHA Team (Home Appliance & Air Solutions), your roles & responsibilities will be as follows:\n• Work with the local engineering team, product managers, and program managers at VHA and remote locations (Korea) to build and ship embedded system applications.\n• Design software module, implement, test & release according to agile process.\n• Expected engineering output in the form of source code, engineering documentation, test results, release note.\n• Provide work result with high quality and high performing (embedded system applications C/C++ based)\n• Senior level engineers are required to perform code reviews of fellow or junior team members.\n• Support leadership team (PM, PL and cross functional leaders) for the successful outcome of engineering projects.\n(2) As a member of LGEDV VSD Team (Automotive), you will be responsible for researching and developing applications for Car Infotainment, AVN (Audio Video Navigation) system, Clusters and Telematics as below:\n• Develop automotive products and technologies (included HMI Applications, HMI frameworks, Protocols to interface with HMI framework and middleware …);\n• Responsible for software delivery to head quarter;\n• Generate reports, communicate with local managements and head quarter\n\nJOB REQUIREMENTS\n*Bachelor degree in Information Technology, Computer Science, Computer Engineering, Electrical Engineering, Telecommunication Engineering, Mathematics, Mechanics and Informatics or equivalent.\n\n(1) For Home Appliances - Air Solutions projects:\n• Experience in embedded software development using C/C++\n• Minimum 2 years of experienced working with MCU (UART, SPI, I2C, ADC/DAC, PWM, Timer, Interrupt...) or RTOS (BSP, HAL driver, task scheduling, multiple process, kernel/user space, RPC, IPC... ).\n• Fluent Git, experience with Application Life Cycle Management tool (e.g., Jira, CodeBeamer, Polarion, etc.)\n• Experience with wireless chipsets, particularly WiFi (preferred Bluetooth/Zigbee experience as well).\n• Good knowledge about OS\n• Good knowledge about OOP, Data Structure, Algorithms, Design Patterns, TDD, Unit Test, MISRA/Static\n• Good knowledge about UI framework, UI components, and Atomic Design\n• Good written and oral communication skill in English\n• Experienced with Agile (Scrum/Kanban/SAFe) working methods is preferred\n\n(2) For Automotive projects:\n• Software development experience in C++ programming;\n• Having good knowledge with OOP, OOAD (Object-Oriented Analysis and Design);\n• Having hands-on experience to use JIRA, GIT and Gerrit;\n• Having hands-on experiences in developing large software systems;\n• These skills would be considered as an advantage but not the must:\n• Experiences related to multi-thread, multi-process programming;\n• Having hands-on experiences to use and implement design patterns (MVC, Singleton, Observers);\n• Experiences related to develop application using Qt/QML;\n• Experiences related to design and develop GUI frameworks, front-end applications;\n• Ability to effectively present information to top management, public groups, and/or board of directors.\n\nWHAT WE OFFER\n• Hybrid working & Flexible working time\n• Attractive and competitive salary package (negotiable upon the interview);\n• Total remuneration package: UP TO 16th salary. Annual salary review;\n• Monthly transportation allowance\n• Support for lunch and other allowances (Coding Expert, Technical leader, phone...)\n• Paid 100% of social insurance during probation\n• Premium health care & accident insurance;\n• Support fee to get TOEIC & Technical certifications;\n• On-site & training opportunities in Korea, the US, UK, France, etc.;\n• Company trips, sporty clubs (Zumba, football, ping-pong, badminton,...);\n• Monthly budget for team building activities, etc.\n• 20 full paid for days off (annual leave & additional company holidays)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Région métropolitaine de Hanoï', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1940, 915, 2, 'Full Stack Developer (React/Node.js)', 'About us\nFounded in 2014, Eastgate Software is a software development company that builds custom business solutions and applications. We are proud of our high-qualified staff who has more than 20 years of experience in software development including web, mobile and desktop applications.\nWe put quality and customer satisfactions at the top priority in every project we carry. Therefore, our German and US senior experts offer local consultancy for European and US clients.\nAs a member of Eastgate, you will be emerged in a professional and flexible environment where you have opportunities to express your own ideas and improve your skill set through many interesting full-cycle projects.\nYour responsibilities:\nDesign, developing new programs, products, or features by analyzing the raw requirement.\nCollaborating with the back-end developers and other team members to establish objectives and design more functional, cohesive codes to enhance the user experience.\nThe ideal candidate:\nBachelor’s degree or higher in Computer Science, Information Technology or equivalent\nAt least 3 years of experience with the following areas: NodeJS, Expressor PHP,...\nAt least 1 year of experience with Javascript SPA lib/framework: Vue, React, Angular\nGood English\nSolid understanding and experience with database MySQL, PostgreSQL, Mongo DB\nStrong experience with RESTful API, JavaScript, HTML, Bootstrap.\nStrong experience with Git and knowledge of Linux-Have basic knowledge of data structure and good at algorithms-Able to use Docker, Kubernetes... is a plus\nKnowledge of VPS, domain, AWS is a plus\nWrite high-quality, clean, simple, and maintainable code, can apply design pattern and understand SOLID, DRY ... principles\nStrong analytical skills, with excellent problem-solving abilities\nGood mindset, willingness to learn and able to pick up new technology or new concepts fast\nWhy you’ll love working at Eastgate:\nAttractive salary and bonus package\nEastgate Software is a Global Fortune 500 Preferred Vendor, so you will have an opportunity to work with many IT Experts around Europe and USA\nBe emerged in a professional and motivating environment where you have opportunities to express your ideas and improve your skill set through many interesting full-cycle projects\nFlexible working time: 9:30 a.m. to 6:30 p.m., Monday to Friday, No Overtime (Only 8 working hours)\nPerformance review and appropriate gratification: twice a year\n13th month salary + Project Bonus + 02 probationary months with full salary\nExtra health check package per year\n16 paid leave days/year (add an extra day each year and a maximum 20 days for annual leave)\nFree snacks, video gaming & movie nights, team social and sports activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1941, 1041, 2, 'Android Engineer', 'Our mission is to become the global standard for addressing. Street addresses weren’t designed for 2025. They aren’t accurate enough to specify building entrances, and they don’t exist for parks, rural areas and many parts of the world. This makes it hard to find places and causes problems and inefficiencies on a global scale.\n\nThat’s why we created what3words. We divided the world into 3m squares and gave each square a unique combination of three words. It’s the easiest way to find and share precise locations.\n\nOver the last year, what3words has been used in 193 countries, and our monthly active users continue to grow at an impressive pace. Our tech is used by emergency services, delivery companies, eCommerce businesses, ride-hailing apps and NGOs, and is integrated into the navigation systems of millions of cars around the world.\n\nRole:\n\nThe role is for an Android developer to work on our core app used by millions. We’re scaling our existing engineering, product and sales team in Ho Chi Minh City so it’s a very exciting time to join if you want to have an impact. You’ll be designing, building and scaling our mobile apps and working with engineers and product specialists in London. You’ll be working to deliver our product roadmap, choosing technologies and delivering features. The job will be working closely with the QA, UX and product teams as well, helping to iteratively develop new features and will be based out of Ho Chi Minh City, Vietnam\n\nYou:\n\nYou should have experience working in a startup environment or high impact environment, delivering apps on Android, working with a range of technologies, be able to pick up new skills quickly.\n\nResponsibilities:\n• Build and maintain features on our core app\n• Collaborate with our other mobile and front end engineers to make a consolidated portfolio of products\n• Deliver features end to end from inception and design through implementation and deployment and testing\n• Stay up to date on the latest technologies and trends in Android development\n• Develop reusable Kotlin Multiplatform Mobile (KMM) components intended for integration within native Android application\n\nEssential Skills:\n• 3+ years Kotlin development in Android Studio or similar\n• Design and build advanced Android applications using Kotlin and Jetpack Compose\n• Create modular and business logic components using Kotlin Multiplatform (KMM), with the ability to collaborate or support minimal iOS integration when needed\n• Understand and work with MVVM or MVI architectural patterns as applied within existing projects\n• Extensive end-to-end experience developing mobile apps, from interpreting UX designs to working with product teams on recursive feedback and analytics/testing\n• Experience building and distributing components for third parties\n• Maintain and contribute to internal libraries and tools, distributing them via Gradle/Maven\n• Write clean, testable, and scalable code using best practices for unit and UI testing (JUnit, Espresso)\n\nDesirable Skills:\n• Ci/CD experience (CircleCI+Argo a plus)\n• C++/NDK/JNI experience\n• Using RESTful web APIs\n• wearOS, Android Auto would be a plus\n• iOS experience would be a plus\n\nYou will have:\n• Excellent communication skills in both spoken and written English\n• The ability to talk to techies and non-techies in suitable language\n• A passion for development and staying current with technology trends\n• The ability to work both independently and with others\n• A focus on high quality software engineering work and attention to detail\n• The ability to work in a fast-paced, deadline-driven environment\n\nExtra credit if you:\n• Like maps and location based services and know what a GIS is (we love maps)\n• Are able to understand the business context of what you’re doing – understand the value your work creates. \n• Enjoy learning new skills in scripting languages and how to use those to showcase our products\n\nThe office\n\nThe role is based in our centrally located HCMC office. While you can work from the office five days a week if preferred, our Engineering team can choose to work up to two days a week from home. We also offer a six-week remote-work allowance; for up to six weeks a year, you can work from anywhere in the world (as long as you’ve got great WiFi and are happy to work with your main office timezone).\n\nEquality, Diversity And Inclusion At What3words\n\nOur mission is to help everyone talk about everywhere, and we believe diverse perspectives make for a better company and better products too. We strongly encourage applications from underrepresented groups and are committed to diversity, equity and inclusion in our hiring processes and company culture.\n\nBenefits\n\nWe offer the following benefits to all permanent employees of what3words:\n• Competitive salary\n• Flexible working\n• 6 week remote working (work from anywhere) policy\n• 25 days holiday: plus the option to buy more!\n• Share options\n• Pension\n• Private health and dental insurance\n• Life insurance\n• Wellbeing Days\n• Yulife perks and rewards\n• Generous parental leave policies\n• Family friendly policies\n• Employee Assistance Programme (EAP)\n• Lunch & learn sessions\n• Office perks; free breakfast, snacks & regular team lunches\n• Sports and hobbies clubs', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1942, 986, 2, 'Senior Backend/Fullstack Software Engineer I', 'Join Axon and be a Force for Good.\n\nAt Axon, we’re on a mission to Protect Life. We’re explorers, pursuing society’s most critical safety and justice issues with our ecosystem of devices and cloud software. Like our products, we work better together. We connect with candor and care, seeking out diverse perspectives from our customers, communities and each other.\n\nLife at Axon is fast-paced, challenging and meaningful. Here, you’ll take ownership and drive real change. Constantly grow as you work hard for a mission that matters at a company where you matter.\n\nYour Impact\n\nAs a Full Stack Engineer on the Axon Records, you will contribute directly to our customer’s productivity by building and launching innovative features in Productivity, specifically to Transcription system with AI models (LLMs, STTs and others). You will partner with other engineers to design highly available and scalable systems in a fast paced development environment. Your work will help to transform the future of public safety around the world.\n\nSound exciting? We think so too. Apply now to join a team that\'s turning this vision into a reality.\n\nWhat You’ll Do\n\nLocation: Hybrid working in our HCMC office\n\nWork with other world-class Engineers, Product Managers and Product Designers to design new features in the next generation of AI era and our Record Management System\nImplement and launch new features to our customers\nGather system and user metrics to improve existing features\nMentor junior developers on the team\n\nWhat You Bring\n\nA customer-obsessed developer with 5+ years of experience in launching and operating complex applications\nStrong experience building services in Go, Java, Scala\nExperience with HTML5, CSS, Javascript, and component-based frameworks like ReactJS is a plus\nExperience with working designers, customers to design UI/UX in an user-oriented interface is a plus\nExperience with databases, such as MySQL or AzureSQL is a plus\nExperience with Kafka/AMQ/Azure Service Bus or messaging queue is a plus\nExperience with Azure Cloud is a plus\n\nBenefits that Benefit You\n\nMedical and Dental Insurance and cover your family up to 3 members\nVision Insurance\nRobust Paid Time Off policy\nBonuses\nLunch allowance\nCell phone stipend\nFree LinkedIn Learning/Udemy account\nAccess to 24/7 online emotional and mental support\nGym membership\nFree parking\nStocked fridges and pantries - free coffee, cold beverages, snacks\nAnnual Company Outing Trip\nMonthly team social activities\n\nDon’t meet every single requirement? That\'s ok. At Axon, we Aim Far. We think big with a long-term view because we want to reinvent the world to be a safer, better place. We are also committed to building diverse teams that reflect the communities we serve.\n\nStudies have shown that women and people of color are less likely to apply to jobs unless they check every box in the job description. If you’re excited about this role and our mission to Protect Life but your experience doesn’t align perfectly with every qualification listed here, we encourage you to apply anyways. You may be just the right candidate for this or other roles.\n\nImportant Notes\n\nThe above job description is not intended as, nor should it be construed as, exhaustive of all duties, responsibilities, skills, efforts, or working conditions associated with this job. The job description may change or be supplemented at any time in accordance with business needs and conditions.\n\nSome roles may also require legal eligibility to work in a firearms environment.\n\nAxon’s mission is to Protect Life and is committed to the well-being and safety of its employees as well as Axon’s impact on the environment. All Axon employees must be aware of and committed to the appropriate environmental, health, and safety regulations, policies, and procedures. Axon employees are empowered to report safety concerns as they arise and activities potentially impacting the environment.\n\nWe are an equal opportunity employer that promotes justice, advances equity, values diversity and fosters inclusion. We’re committed to hiring the best talent — regardless of race, creed, color, ancestry, religion, sex (including pregnancy), national origin, sexual orientation, age, citizenship status, marital status, disability, gender identity, genetic information, veteran status, or any other characteristic protected by applicable laws, regulations and ordinances — and empowering all of our employees so they can do their best work. If you have a disability or special need that requires assistance or accommodation during the application or the recruiting process, please email recruitingops@axon.com. Please note that this email address is for accommodation purposes only. Axon will not respond to inquiries for other purposes.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1943, 681, 2, '[HN] Automation test - English Fluency', 'WHAT WE DO:  \nParticipate in testing and automation test of diverse software and systems across a wide range of domains  \nDevelop automation test scripts and utilize appropriate testing tools for mobile and web applications  \nBased on predefined test scenarios, execute testing of software/ hardware components and identify defects  \nManage and conduct in-depth analysis of test results  \nPrepare detailed test reports, procedural documentation, and user guides  \nWHO YOU ARE:  \nMinimum 3 years of experience in automation test  \nA comprehensive understanding of software testing methodologies, automation testing tools, and software testing processes  \nExpertise and experience in designing and developing automation testing frameworks utilizing tools such as Appium, Selenium, Katalon, etc  \nProficient in automation testing and script writing with any object-oriented programming language  \nProficient in at least one of the following programming languages: Java, C#, Python, Flutter, etc  \nA strong command of database technologies (SQL, MySQL, etc.)  \nExperienced using automation testing with TestRail  \nFluent in English: excellent communication, reading comprehension, analysis and writing skills  \nExperienced in Agile development methodologies  \nExperienced working with clients from the US, Europe, Singapore, etc  \nBENEFITS AND PERKS:  \nProfessional, open-minded, and creative environment:  \nWork with colleagues who embrace ideas to change the society.  \nRespect different perspectives within a team  \nStrong learning culture that promotes individual development  \nThe culture of taking risks to experience and thrive  \nFocus on individual development  \nBe consulted, accompanied, and supported in career development with the career path system (developing in expertise or management direction) that has been studied and tested for many years  \nBe oriented for individual, group, and organizational goals  \nBe empowered  \nBe supported to define a 3-month or 6-month goal (Goal Define Support)  \nGet access to company Learning Hub online library with various courses provided by Udemy, LinkedIn,…  \nSpecial care for employees  \nSalary: Negotiable + competitive allowance (lunch, living allowance, beauty care, Japanese and IT certificates, etc.)  \n13th-month salary bonus  \nPerformance review: Twice/a year  \nHybrid working policy; flexible check-in, check-out  \nComprehensive health insurance Sun* Care  \nSeniority Allowance  \nWomen care allowance: Women’s physiological leave: 2.5 hours/month; Postpartum leave for female employees with under 1-year-old children: 1 hour/day  \nPolicies supporting learning activities, knowledge sharing, and cultural exchange (Technology Seminar – Tech Expert, Club: Reading, Japanese, Music Club, …)  \nAnnual company trip and quarterly team-building activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi i okolice', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1944, 702, 2, 'QA Engineer (Java Coding)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nResponsibilities\n\n- Work closely with team members (developers, product manager, customer support and partners) to develop, test and deliver high quality products\n- Create detailed, comprehensive and well-structured test plans and test cases\n- Prevent, collect, analyse and track product defects\n- Design, develop and execute Automation scripts\n- Hands-on Manual investigation and reproduction of functional Backend software issues\n- Root cause analysis of existing test script failures, product issues\n- Identification of current test script deficiencies and candidates for additional scripted coverage\n- Investigatory testing of unreleased features including defining requirements, behavior and impact\n- Documentation and design of candidate test scenarios for the above\n\nRequirements\n\n- Competence in designing, writing and executing comprehensive testing plans and test cases\n- Equipped with Manual Testing and Automation Testing experience [60% Manual, 40% Automation]\n- Strong knowledge of Backend Testing, Auto frameworks and design processes. \n- White Box testing experience\n- Solid knowledge of SQL, Hands on solid coding / writing script capability (Java preferred)\n- Experience in functional testing for web. Mobile applications is a big plus\n- Proficient in conducting root cause analysis to identify and address underlying issues impacting software quality\n- Proficient in English & Chinese for cross team collaboration efficiency \n- Bonus: Prior knowledge in the Funding/Blockchain related domain \n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1945, 943, 2, '.Net Software Engineer - Vietnam', 'At Globant, we are working to make the world a better place, one step at a time. We enhance business development and enterprise solutions to prepare them for a digital future. With a diverse and talented team present in more than 30 countries, we are strategic partners to leading global companies in their business process transformation.\n\nWe seek a .Net Developers who shares our passion for innovation and change. This role is critical to helping our business partners evolve and adapt to consumers\' personalized expectations in this new technological era.\n\nYou will get the chance to:\n\n- Develop and provide support for features in an existing Microsoft-based system while striving to improve performance and availability\n- Work with fellow developers and database administrators to design, implement and maintain working programs\n- Perform appropriate tests of applications to ensure programs fulfill agreed-upon requirements\n- Document and deploy developed programs\n- Mentor fellow junior developers to help them learn and grow\n- Provide training and technical support as needed to other team members\n- Any other tasks as assigned\n\nWhat will help you succeed:\n\n- Bachelor’s degree in Computer Science or relevant field\n- 4+ years’ experience in complex development environments\n- Deliver high-quality, testable software and services\n- Strong knowledge of software design practices, including modularity, object-oriented design pattern\n- Result-driven, detail-oriented individuals guided by principles and best practices thrive in a fast-paced, iterative development environment\n- Experience working in an Agile environment with a great understanding of Continuous Integration practices\n- Strong understanding of modern software architecture (N-tier, Clean Architecture)\n- Strong knowledge of the Microsoft development technology and tools: C#, ASP.Net Core, ASP.Net MVC, .Net 6+, Visual Studio 2022, Git, etc\n- Hands-on experience with Web technologies, modern UI frameworks (e.g. React), and UI/UX principles.\n\nHands-on experience using test frameworks (i.e., NUnit, xUnit, etc.)\n\n- Excellent understanding of relational database concepts.(SQL Server, MySql, Postgresql)\n- Experience in designing secure applications and awareness of security implications from design to the implementation phase of a project\n- Experience with performance analysis, profiling, and optimization\n- High initiative, self-motivation, and drive to exceed expectations.\n- Ability to work independently as well as in a team-based environment\n- Good at English skills.\n\nThis job can be filled in Hanoi/Danang or Ho Chi Minh.\n\nCreate with us digital products that people love. We will bring businesses and consumers together through AI technology and creativity, driving digital transformation to impact the world positively.\n\nWe may use AI and machine learning technologies in our recruitment process. Globant is an Equal Opportunity employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, national origin, disability, veteran status, or any other characteristic protected by applicable federal, state, or local law. Globant is also committed to providing reasonable accommodations for qualified individuals with disabilities in our job application procedures. If you need assistance or an accommodation due to a disability, please let your recruiter know.\n\nFinal compensation offered is based on multiple factors such as the specific role, hiring location, as well as individual skills, experience, and qualifications. In addition to competitive salaries, we offer a comprehensive benefits package. Learn more about life at Globant here: Globant Experience Guide.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1946, 490, 2, 'Intermediate/Senior Manual Tester', 'Are you looking for an opportunity to make an impact, grow your skills and catapult your career with a growing company?\n\nMealSuite is looking for Manual Tester to join our development team on our mission to revolutionize the continuum of care through our all-in-one foodservice management technology.\n\nOur International Development team works around the clock building innovative solutions that help our customers in senior living and healthcare industries enhance the mealtime experience for their patients and residents. In an industry that is constantly evolving, MealSuite\'s software comes with a promise for continual innovation and growth with our customers. We never stop pushing boundaries and are always steering the future of our industries as innovation leaders in our space.\n\nAs part of our QA team, your mission is to stay on top of the latest releases, contribute to projects, and deliver the best quality solutions for our customers.\n\nRequirements\n\n3+ years of overall proven software testing experience, focusing on web and mobile application\nUnderstanding of SDLC, STLC and Agile methodologies\nGood understanding of Jira, confluence and Testrail\nAbility to understand requirements and extract test cases\nPrior experience working in an Agile product development environment\nExperience liaising with development, product owners, and other business stakeholders\nExceptional communication skills, both written and oral; strong interpersonal and organizational skills\nThe ability to adapt quickly to changing priorities and unforeseen requests\nExcellent problem-solving, analytical, and time-management skills to prioritize and meet deadlines\nResults oriented, focused on customer and team success as opposed to individual success\nMust be able to work flexible hours\n\nBenefits\n\nStock options\nVietnam labor law contract with full benefits\n13th months salary\n1 day work remote every week\nUp to 22 days annual leave\n100% probation salary\nUnlimited access to Udemy Business online learning platform\nFree snacks & beverages\nTeam events\nAwesome and meaningful products', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1947, 1042, 2, '2025 – People – Process Automation Specialist – Bangkok-based (Relocation Provided)', 'About Agoda\n\nAgoda is an online travel booking platform for accommodations, flights, and more. We build and deploy cutting-edge technology that connects travelers with a global network of 4.7M hotels and holiday properties worldwide, plus flights, activities, and more. Based in Asia and part of Booking Holdings, our 7,100+ employees representing 95+ nationalities in 27 markets foster a work environment rich in diversity, creativity, and collaboration. We innovate through a culture of experimentation and ownership, enhancing the ability for our customers to experience the world.\n\nOur Purpose – Bridging the World Through Travel\n\nWe believe travel allows people to enjoy, learn and experience more of the amazing world we live in. It brings individuals and cultures closer together, fostering empathy, understanding and happiness.\n\nWe are a skillful, driven and diverse team from across the globe, united by a passion to make an impact. Harnessing our innovative technologies and strong partnerships, we aim to make travel easy and rewarding for everyone.\n\nAbout The Team\n\nThe People Team is dedicated to finding top talent worldwide and fostering an open, collaborative workplace. We prioritize diversity, equal opportunity, and employee growth through onboarding support, learning programs, and exceptional benefits, ensuring our team stays strong, healthy, and happy. As drivers of positive change, we play a vital role in shaping the Agoda experience.\n\nThe Opportunity\n\nAs an Automation Specialist in People Data and Automation team (PDA), you will be instrumental in designing, building, and maintaining scalable automation solutions. With 3+ years of experience, you’ll help create opportunities to upskill our workforce and focus on delivering strategic initiatives by streamlining processes and driving efficiency.\n\nThis is a Bangkok Based Position; relocation support will be provided for international hires.\n\nIn This Role, You’ll Get To\n- Process Analysis: Conduct thorough analysis of existing business processes to identify opportunities for automation.\n- Develop Automation: Design, develop, implement, and test automation solutions to ensure alignment with business objectives, technical requirements, and quality standards, while driving operational excellence through continuous improvement and adherence to best practices.\n\nWhat You’ll Need To Succeed\n- Proficient in Python for building automation scripts\n- Experience with Power Platforms (e.g., Power Automate flow/desktop, Power Apps)\n- Understanding of databases, SQL, APIs, and system integrations\n- Excellent problem-solving and analytical skills to analyze business processes and identify automation opportunities.\n\nIt’s Great If You Have\n- Experience with Generative AI platforms\n- Experience with OCR tools.\n\nEqual Opportunity Employer\n\nAt Agoda, we pride ourselves on being a company represented by people of all different backgrounds and orientations. We prioritize attracting diverse talent and cultivating an inclusive environment that encourages collaboration and innovation. Employment at Agoda is based solely on a person’s merit and qualifications. We are committed to providing equal employment opportunity regardless of sex, age, race, color, national origin, religion, marital status, pregnancy, sexual orientation, gender identity, disability, citizenship, veteran or military status, and other legally protected characteristics.\n\nWe will keep your application on file so that we can consider you for future vacancies and you can always ask to have your details removed from the file. For more details please read our privacy policy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1948, 1043, 2, 'Senior Java developer-Upto 60M', 'Job Title: Java developer\nThe job description:\n\nWe seek a passionate and skilled Java Backend Developer to join our team. The ideal candidate will have strong backend development experience and a solid understanding of cloud infrastructure, particularly AWS. You will work closely with cross-functional teams to build scalable and reliable backend systems.\nJob descriptions will be discussed during the interview for details.\n\nYour Skills and Experience:\n\nProficient in English\nBachelor’s or master’s degree in engineering, Computer Science, Software Engineering or equivalent discipline.\n5+ years of hands-on development experience, primarily using Java.\nExperience and knowledge of databases – both relational and NoSQL.\nWorking knowledge of Java, Spring, Hibernate, REST, XML, JSON, Message Queues, databases – both relational and non-relational.\nWorking knowledge of distributed messaging and streaming platforms, such as Apache Kafka Streams as well as dealing with unbounded data.\nComprehensive understanding of software systems, including the compiler/JVM/garbage collection, distributed systems, optimizers and compilers.\nProficiency with MongoDB or other NoSQL databases.\nUnderstanding of the TCP stack and MQTT/HTTP based protocols.\nKnowledge and hands-on experience in docker development and deployments such as Kubernetes.\nKnowledge of AWS\nKnowledge of CI/CD based workflow\n\nBenefits:\n\nSalary: Negotiable\nAttractive salary and bonus based on performance.\nFull benefits for employees according to the Vietnam Labor Laws: social and health insurance\nAn international, professional, young but innovative and dynamic environment working closely with international experts and joining conferences and workshops on exciting new technologies.\nHolidays based on Vietnamese labor law + paid vacations\nCompany trip, Team Building\n\nContact:\n\nBlueOC Tech\n\nAddress:\n\n12 Floor, Technopark tower, Vinhomes Ocean Park, Gia Lam, Hanoi\n7 Floor, HL Tower, Duy Tân, Cau Giay, Ha Noi\n\nEmail: hr@blueoc.vn\nFanpage: https://www.facebook.com/BlueOC.tech/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1949, 832, 2, '[Hybrid] AI Engineer - LLM', 'Job Description:\nAs an AI Engineer, you will be responsible for developing and implementing AI models and algorithms, building machine learning pipelines, and integrating AI solutions into an AI highlight detection system. The research focuses on the recent Large Language Model and Vision Language Model. You will collaborate with cross-functional teams to identify business problems and develop AI solutions that meet business requirements.\n\nResponsibilities:\n- Fine-tune LLM and VLM with Llama 2, Gemma.\n- Develop and implement AI models and algorithms.\n- Integrate AI solutions into existing systems.\n- Collaborate with cross-functional teams to identify business problems and develop AI solutions that meet business requirements.\n- Research, evaluate and propose new AI technologies and trends.\n- Continuously learn and keep up with the latest AI trends and technologies.\n- Communicate technical concepts to non-technical stakeholders.\n\nRequirements:\n- Bachelor\'s or Master\'s degree in computer science, artificial intelligence, machine learning, or a related field.\n- 2-4 years of experience in developing AI solutions in a professional setting.\n- Proven experience in developing and implementing AI models and algorithms.\n- Experience with LLM, VLM, Langchain, RAG.\n- Experience in prompting engineering.\n- Experience with processing audio signal.\n- Familiarity with data preprocessing and data augmentation techniques for AI models.\n- Excellent problem-solving and analytical skills.\n- Strong collaboration and communication skills.\n\nBenefits:\n- Hybrid working: 1-2 work from home days/week.\n- 100% salary during probation period.\n- Performance Bonus: 13th-month salary if achieving performance.\n- 2 times salary review/year.\n- Expand your skills and career with continuous learning opportunities and real development support.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1950, 977, 2, 'Full-stack Engineer (Mid/Senior)', 'About The Role\nWorking as a full stack developer at Elfie is far from just another job; it\'s the foundation of our whole development game plan. Your diverse skills, adaptability, and innovative spirit are key as we expand our health tech app on a global scale. This isn\'t just about churning out a product; we\'re leading a revolution in healthcare technology. If you\'re passionate and equipped with the comprehensive abilities of a full stack developer, then Efile is where you can genuinely make a mark on the world.\n\nWhat you will get\n🧳 Relocation Support - We handle the move, financially and practically\n💰 Permanent Global Contract - With a seriously competitive salary\n🏥 Private Healthcare - From day one\n💻 Top-Tier Tech Setup - Brand new MacBook + full onboarding kit\n🧠 Career Growth Framework - Clear, personalised, and fast-moving\n🎯 Bonus Scheme - Performance-related, quarterly paid\n🌴 14 Days PTO + Public Holidays - Real time off\n🧪 Hybrid Working - 3 days in the office per week\n🍛 Refreshments - Free Lunch and Dinner every day for you to enjoy\n\nWhat You’ll Do\nDevelop end-to-end solutions to concrete user-facing problems and requirements, leading design and implementation of software components, systems, and features.\nBuild, test, deploy, maintain, and improve software, specifically for mobile client and web applications, and covering both client and server implementations as well as third-party integrations.\nManage individual project priorities, deadlines, and deliverables.\nResolve challenging technical issues.\nCollaborate closely with teammates in engineering, product, design, and operations.\nHelp build a team and cultivate a culture of quality and innovation.\n\nWhat You’ll Need\nHave at least 5 years experience working as a Software Engineer\nMUST have experience with Typescript, Node.js and Vue.js (or willing to switch to Vue.js)\nMUST have knowledge of HTML(5), CSS(3), ES6\nExperience in Restful API, GraphQL, web-app tooling, testing & debugging.\nExperience with Google Cloud Platform and/or Amazon Web Services, and Docker containers is a plus.\nInterest and skill in UX for creating useful operational tools is a plus.\nBS degree in computer science or similar; graduate degree a plus.\nExperience working in a fast paced startup environment with quick iteration, continuous deployment, and test-driven development.\n\nWhy join Elfie\nWe\'re a global start-up that is mission-led, and fiercely product-driven.\nWe\'re building something that improves lives - and we\'re doing it with a culture of trust, freedom, and high performance.\n\nAbout Elfie\nElfie is the first completely free, gamified mobile app that rewards users for managing their health. Our goal? To become the world’s largest self-reported medical record platform — across all therapeutic areas.\nWe operate in 10+ countries today, with plans to expand into 15 by the end of 2025.\n📲 Try Elfie for yourself by downloading it on the App Store or Google Play\nWhat Now?\nApply today for immediate consideration! Got someone in mind? We offer a referral reward if your recommendation is hired. Contact Talent Acquisition for more info.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1951, 910, 2, 'ML Ops Co-Founders Wanted | Experts in Machine Learning Infrastructure & Automation', '🌟 About Antler:\nWe are a global early-stage investment firm that invests in startups from day zero. We provide funding, mentorship, and a global network to help you build and scale your startup. With Antler, you’ll have access to the resources you need to turn your vision into reality—whether you\'re still ideating or already started building.\n\n👩‍💼 Who are we looking for?\nNote: This ad is not for a job, but rather for the opportunity to find your co-founder and build your own VC-backed startup through a 10-week program with Antler.\n- Engineers and data scientists with expertise in building and deploying scalable machine learning pipelines.\n- Innovators who have experience optimizing ML workflows, from data ingestion to model deployment and monitoring.\n- Visionaries who understand the challenges of operationalizing AI and can create robust MLOps platforms for real-world applications.\n- Leaders who thrive in high-performance environments, integrating cutting-edge AI advancements with practical deployment strategies.\n- Self-starters driven to launch and grow a world-class MLOps company\n\n📋 Details of the program:\n- The program runs for an initial 10 weeks, full-time in Ho Chi Minh City (Vietnam) and starting on 21 July 2025, where you are required to ideate and find your co-founder(s) from the cohort of 60-70 founders.\n- After two months you will present your team and business idea to the Antler Investment Committee. If accepted, you will receive a pre-seed investment of $120K USD for 12% equity, non-negotiable.\n- If you get an investment, you will continue to be part of the program for another 3 months during which Antler will work closely with you to accelerate your growth. At the end of this period, Antler arranges a demo day where we invite VCs, institutional investors, and local angel investors to help you connect with investors and raise your seed round.\n\nFor more details on what to expect 👉 https://www.linkedin.com/smart-links/AQGwMqMCzPe68Q\n\nBenefits:\n- 💵 Potential investment at the pre-seed stage\n- 🤝 Help finding your co-founder(s)\n- 👨‍🏫 Personalized coaching sessions with business experts\n- 🛫 Relocation grant of $2,000 if you\'re relocating from overseas to HCMC, Vietnam\n- 🏬 Shared office space at a premium co-working space with access to various amenities\n- 🌍 Access to a global network of start-up advisors and experts in their field\n\nSome examples of successful companies that were built as a result of Antler’s program, received pre-seed investment from Antler, and gone on to raise substantial investment are:\n- Xailient - the World’s fastest Computer Vision AI\n- BUYO - Pioneering bioplastics and material tech\n- SKYQRAFT - Affordable and safe powerline inspections with drones and AI\n- Airalo - The world’s first eSIM subscription and top-up store\n- homebase - Making home ownership accessible\n- Reebelo - Circular economy for e-devices\n\nReady to help shape the future of the world? Apply now to Antler and together we will build something truly amazing ✨', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1952, 882, 2, 'Senior Java Developer', 'Responsibilities\n- Collaborate with solution architects and product owners to refine technical requirements and translate them into solid system designs.\n- Write clean, efficient, and well-documented Java code, following best practices, design principles, and code standards.\n- Develop and maintain backend systems using Java (Java 8+), Spring Boot, Hibernate, and modern Java frameworks.\n- Build robust RESTful APIs and ensure seamless integration with front-end applications and third-party services.\n- Conduct thorough code reviews, mentor junior developers, and promote knowledge sharing within the team.\n- Debug complex issues and provide reliable, long-term solutions.\n- Continuously optimize system performance, scalability, and security.\n- Participate in all stages of the software development lifecycle: planning, design, development, testing, deployment, and maintenance.\n- Take part in Agile processes (Scrum/Kanban), including sprint planning, daily stand-ups, and retrospectives.\n\nRequirements\nMust have\n- Bachelor’s degree in Computer Science, Software Engineering, or related fields.\n- Minimum 5 years of Java backend development experience, including 2+ years at senior level.\n- Proficiency in Java 8+, Spring Boot, and Hibernate/JPA.\n- Experience building and integrating RESTful APIs and microservices.\n- Strong grasp of OOP, design patterns, and clean coding practices.\n- Solid SQL skills with relational databases (e.g., PostgreSQL, MySQL); familiarity with NoSQL is a plus.\n- Proficient in version control tools like Git, and experience with CI/CD pipelines.\n- Strong communication skills and the ability to work in a collaborative Agile environment.\n- Fluent in English (written and spoken).\n\nNice to have\n- Experience with Docker, Kubernetes, or similar container tools.\n- Exposure to cloud platforms (AWS, Azure, GCP).\n- Knowledge of message brokers like Kafka, RabbitMQ.\n- Certifications in Java or related technologies (OCP, OCM).\n- Familiarity with front-end technologies (React, Angular) is a plus.\n\nCore Competencies\n- System Design Thinking: Ability to architect scalable, maintainable backend systems and microservices with long-term extensibility in mind.\n- Performance Tuning & JVM Mastery: Deep knowledge of JVM internals, garbage collection, memory management, and performance optimization.\n- Clean Code Advocate: Commitment to writing modular, testable, and maintainable code following SOLID principles and industry best practices.\n- Leadership & Mentorship: Proven ability to guide junior developers through code reviews, technical coaching, and shared ownership of code quality.\n- Business-Driven Development: Strong product mindset with the ability to translate business problems into practical and impactful software solutions.\n\nBenefits\n- Salary: Negotiation (range: 25- 50M)\n- Join a global team and work directly with many talents around the world.\n- Opportunities for onsite work in Japan, Singapore, Australia, and many other countries.\n- Work and grow in a dynamic, creative, and professional environment.\n- Healthcare: Premium Health Insurance TECHVIFY Care\n- 13 months’ salary per year.\n- Annual salary evaluation.\n- Sponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1953, 720, 2, 'Full Stack Engineer (AWS)', '🌐 [HIRING] Fullstack Engineer – Cloud Application (Post Office Project)\n\n📍 Ho Chi Minh City | Hybrid | International Project\n🖥️ Cloud-native • Cross-functional team • Agile Scrum\n\n🏢 About SCC & the Project\n\nSCC – Specialist Computer Centres – is Europe’s leading IT services provider, running mission-critical systems for 2,500+ clients across 50 countries. Our Vietnam team supports key projects for the UK & French markets.\n\nWe are hiring a Full-stack Developer to work on a major cloud-based system for Post Office UK – building secure, scalable applications in a cross-site Agile team with experts from Vietnam, UK, France, and Romania.\n\n💼 Job Scope\n\nAs a core member of our Agile delivery team, you will:\n• Build and maintain modern, cloud-native applications and services (serverless, microservices).\n• Ensure system reliability, scalability, and performance.\n• Collaborate with architects, product owners, testers, and developers to deliver each sprint.\n• Apply security best practices and handle production issue troubleshooting.\n• Explore and apply new trends in cloud and software architecture.\n• Write and maintain clear technical documentation.\n\n🧠 What You Bring\n\nMust-have:\n• 3+ years of experience in software development.\n• Proficient in Python, TypeScript, or C#.\n• Knowledge of at least one major cloud platform (AWS, Azure, or GCP).\n• Strong problem-solving mindset, attention to detail, and code quality standards.\n• Effective communication in English (verbal & written) – international teamwork.\n• Agile/Scrum team experience, preferably in global setups.\n\nNice-to-have:\n• Knowledge of AI/ML, Data Analytics, or Data Warehousing.\n• Experience using Power BI for building reports.\n• Familiarity with automation testing tools like Webdriver.io or Selenium.\n\n👥 Team & Reporting\n• Work closely with VN & UK Technical Leads.\n• Collaborate with international teams (UK, France, Romania).\n\n🎁 Why You’ll Love Working at SCC\n• Competitive salary + 13th-month pay + performance bonus.\n• Premium health care (includes dependents).\n• Hybrid working, international exposure, English-speaking environment.\n• Annual leave, sick leave, paid insurance, yearly health check.\n• Travel opportunities & per diem for onsite trips.\n\n🚀 Join us if you want to:\n• Work on a large-scale UK national project.\n• Collaborate with international tech teams.\n• Be part of a team that builds reliable, secure, and smart cloud applications.\n\n📩 Apply now and let’s build future-ready systems together.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1954, 1044, 2, 'Software Engineer II, TransferConnect', 'Nice to Meet You! We are Ascenda\n\nAscenda provides the rewards infrastructure for leading financial services brands across the world. Our clients include the world\'s largest banks, top tier card issuers and fintechs who utilise our rewards infrastructure to power their earn & burn rewards programs. These include American Express, CapitalOne, HSBC, Brex, Virgin Money, SMBC, ICBC, Bradesco, ANZ, HDFC and Top 10 financial services brands in many other countries. With a best-in-class technology suite and the world\'s broadest rewards content marketplace, we are the engine behind winning premium rewards propositions for financial services all around the globe. Our clients are spread across continents, and we serve over 1 billion customers globally. No matter where you are in the world, you\'ll recognize our footprint! We believe that nothing should stand in the way of companies who strive to drive growth via compelling and effortless rewards propositions that their customers love. Welcome to the future of customer growth. Join us as we shape the future of rewards in financial services!\n\nAbout Transfer Connect\n\nTransferConnect is our platform to convert loyalty points to airline miles and hotel points. We work with most of the premium hotel and airline programs around the world to enable these transfers. Hundreds of companies, from the world\'s largest banks to the most ambitious fintechs, use TransferConnect to process and handle customer points each and fulfillments; making it a core part of our business and significant revenue driver. Our mission is to maximize the value and utility that our millions of members can gain from their rewards while maintaining the highest standards of system reliability.\n\nAbout The Role\n\nWe\'re looking for someone who\'s excited to jump in and get your hands dirty with our team members to help us deliver the largest most scalable set of transfer APIs for our clients globally. We\'ll build the next generation of loyalty currency services such as cashback & carbon credits together. Your work will enable new types of businesses to run on our platform, at greater scale, while maintaining an extremely high bar for reliability, usability and operations.\n\nWhat You’ll Be Doing\n- Contribute to building and enhancing Ascenda’s products and services, helping scale them to support our growing client base.\n- Deliver high-quality, reliable, and maintainable code across backend systems.\n- Participate in the design and development of APIs and backend services with guidance from senior engineers.\n- Take ownership of well-scoped problems, collaborating with cross-functional teams (e.g. Project, Product, Partnerships) to understand requirements and build robust solutions.\n- Participate in technical discussions, code reviews, and ongoing improvement of engineering best practices.\n- Learn and grow in both domain knowledge and technical breadth, with mentorship and support from more experienced teammates.\n- Contribute to client integrations and support technical implementations as part of a delivery squad.\n\nWhat We\'re Looking For\n- Solid technical foundation and experience in building backend systems, ideally with some exposure to distributed systems, cloud environments, and database design.\n- Familiarity with Ruby (or strong interest to learn), and sound understanding of software engineering fundamentals.\n- Strong communication and collaboration skills, with an eagerness to work closely with engineers and non-engineers alike.\n- 2–5 years of relevant software development experience.\n- A growth mindset and eagerness to take on new challenges.\n- Desire to contribute to a strong engineering culture, and an interest in mentoring peers as you grow.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1955, 442, 2, 'Intermediate Software Engineer', 'Who We Are\n\nEmployment Hero is on a mission to make employment easier and more valuable for everyone. Our Employment Operating System brings hiring, HR, payroll and benefits into an all-in-one solution.\n\nSince our inception in 2014, we\'ve scaled to a $2 billion valuation and gained a presence in 6 countries globally - Australia, New Zealand, Singapore, Malaysia, the UK and Canada. We now service over 300,000 businesses and more than 2 million employees.\n\nThe EH Way\n\nAt Employment Hero, we\'re proud of our unique DNA, which we call The EH Way.\n\n- We are Mission First - everything we do (from what we work on, to how we allocate capital and where we focus) is driven by our Mission\n- We are Remote First - we champion a remote environment with a preference for asynchronous communication and a high degree of autonomy \n- We are AI First - we are committed to using AI to accelerate our mission; AI is not just a tool, it\'s a fundamental part of how we operate, innovate, and scale\n- We are Apolitical - we do not take a position on political or social topics, unless it relates to our Mission\n- We Live by Our Values - we role model our values 100% of the time\n- We Expect High Performance - we set a high standard and we\'re not satisfied with being average\n\nThis role \n\nAs one of our Senior Backend Engineers, you\'ll be accountable for building and deploying the innovative features that change our customers\' lives every day. From our trailblazing AI hiring tool to our fully automated payroll solution, every component of our Employment Operating System is carefully designed to disrupt the employment industry for the better, improving the lives of business owners and entrepreneurs everywhere.\n\nOur world-class Product and Engineering teams delivered almost 1,000 new features last year. As one of our Senior Engineers, you\'ll play a vital role in the continued acceleration of our product strategy.\n\nThis will include\n\n- Driving your squad to develop critical features for our customers. We primarily develop our applications using Ruby. If you\'re not familiar with Ruby, no worries—we offer training to ensure you\'re equipped with the necessary skills \n- Collaborating closely with our global team of designers, product managers and UX specialists to gather requirements and translate them into technical solutions \n- Writing automated tests for your production codes \n- Developing and maintaining key components of web applications \n- Conducting testing and code reviews for both yourself and your colleagues \n- Mentoring the Junior Engineers within your squad\n\nWho You Are\n\nTo thrive at Employment Hero, you\'ll need to embody The EH Way - operating with focus, agility, and an obsession with impact. For this role, you\'ll also bring\n\n- Over 4 years of experience in Software Development, with a focus on Server-side and RESTful API Development and integration\n- Proficiency in OOP languages such as Python, Java, PHP, etc., is highly desirable, with the expectation that you are willing to learn Ruby upon joining our team\n- Demonstrated experience implementing, maintaining and deploying full-stack web technologies\n- Strong skills in Object-Oriented Programming (OOP)\n- Strong understanding of standard Software Engineering processes, Testing, and Agile methodology\n- A team player that always puts colleagues ahead of yourself and has a highly adaptable and versatile approach to work\n- You are passionate about learning and sharing your knowledge, and not afraid to challenge your peers, but also welcome being challenged\n- You have experience in mentoring team mates, or even leading an Engineering squad\n- English language abilities, both written and verbal - you\'ll be working with people across the world, including from Australia\n\nWhat We Can Offer\n\nAt Employment Hero, we don\'t just talk about a better way to work - we live it. Joining Employment Hero means\n\n- You will work remotely, with the flexibility to own your time and impact\n- You will access cutting-edge tools to amplify your work, knowledge and outputs \n- You\'ll surround yourself with ambitious, outcome-driven colleagues who challenge you to do the best work of your life\n- You\'ll own ESOP (employee share options) in one of the world\'s fastest-growing tech companies \n- You\'ll also have access to a wide range of benefits that includes - a very generous paternity leave policy, subsidised egg freezing (so you can make the choice that\'s right for you, on your terms), a WFH office expense budget, and outstanding learning & development opportunities \n\nAt Employment Hero, we are committed to safeguarding the privacy of your application data. To understand how we do so, you can read our Applicant Privacy Policy \nhere\n\nEmployment Hero celebrates diverse perspectives and experiences, we invite people of all backgrounds and identities to apply for this position.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1956, 1045, 2, '[HCM] Fullstack developer (NodeJS)', 'What you will do:\nAt least 3 years of experience working as a full-stack developer\nPlan, organize and develop user-facing features for the components in our dynamic platform;\nDevelop and maintain web applications using NextJS or ReactJS on the front end and Node.js with NestJS on the backend, all written in TypeScript.\nWork with other members to develop and integrate new features including other third-party systems and plugins into our platform;\nEvaluate and identify new technologies for implementation and incorporation;\nCommunicate with our business and product heads to understand clients’ requirements;\nRespond and follow up to incorporate feedback and draw new insights;\nPrioritize tasks to meet multiple deadlines;\nIdentify and correct bottlenecks and fix bugs.\n\nCore skills:\nExperience in backend technology of Node.js, especially in NestJS framework\nExperience with Web Front-end (HTML/CSS/JS), ReactJS and extensive knowledge of NextJS framework.\nStrong proficiency in TypeScript programming language\nExperience with TypeORM and familiarity with PostgresSQL database, along with solid relational database skills (SQL, etc.)\nExperience with non-relational databases (MongoDB, Redis, Cassandra, etc.)\nExcellent at coding (the code is well documented and compliant with good practices) and testing (Unit Test, Integration Test, User Acceptance Test, Automation Regression Test.)\nExperience about RESTful API\nKnowledge about Programing Principles, Design Pattern, Clean Architecture, etc;\nWilling to learn new technology, product mind-set.\nGood at English (writing and speaking)\n\nAdvantages\nProficiency in using Docker for containerization.\nUnderstanding of cloud computing platforms\nExperience in building and managing CI/CD pipelines.\nUnderstanding of Domain-Driven Design (DDD) and its application in software development.\nFamiliar with working in an Agile environment\nHave good teamwork skills.\nHave an open mindset.\n\nBenefit\n05 working days/week (From Monday to Friday), applying flexible working hours\n2 days of remotely WFH per week (based on team\'s decision)\nLunch + Gasoline + Coffee Allowance\nHealth, Social and Unemployment Insurance (based on gross-based salary, according to Labor Code) and PVI Health Insurance\n13th-month salary and Performance bonus\nAnnual salary review\n12 days annual leave plus extra 02 days company leave\nCompany trips, sponsored team building, monthly Happy Hour, Sport Clubs (Soccer, Badminton, Pingpong, Yoga) and other joyful events;\nA culture of relentless learning with free courses in specialized skills, soft skills, and English;\nYearly health-checkup;\nSeniority benefits: allowance & PVI Health Insurances for family members\nTechnical-certificate bonus\nJapanese-certificate bonus\nEmployee Referral Incentive', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1957, 797, 2, 'Software Engineer II', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.\n\nThe Position\n\nWe are looking the Middle-Senior Software Engineer for hands-on C++ developing to join our growing R&D team. The candidate will work in a talented team to build OPSWAT\'s famous products as world\'s advanced next generation cyber security platforms.\n\nWhat You Will Be Doing:\n- Research, design, develop and implement OPSWAT products using C++ in Windows, Linux and MacOS environment.\n- Provide inputs for documentation of new or existing programs.\n- Partner with Scrum team members on delivering Sprint commitments.\n- Collaborate with Product Management on product requirements.\n- Participate in receiving and giving peer code reviews.\n\nWhat We Need from You:\n- Strong command of C++ and at least one scripting language.\n- Windows/ Linux development experience.\n- Good data structure and algorithm design skills.\n- Good object-oriented design & programming skills.\n- Good coding and debugging skills.\n- Excellent verbal and written communication skills.\n- Must be self-motivated and have a proven ability to work well in a fast-paced team, environment.\n\nIt Would Be Nice If You Had:\n- Experience with DBMS like SQL, MongoDB....\n- Experience working with MacOS environment.\n- Experience with Agile / Scrum working environment.\n- Experience with Git, Bitbucket, Jira, Confluence, TeamCity.\n\nOPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws.\n\nRecruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Și Min, Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1958, 877, 2, 'Back End Developer (Java)', 'We are seeking a Java Backend Developer to join the IT team at Masan Group. This role focuses on developing and maintaining backend systems to support internal operations and business applications across the Group.\n\nKey Responsibilities:\n\n- Analyze business requirements and convert them into functional and technical specifications.\n- Design and implement backend components and services for internal applications.\n- Ensure system design meets non-functional requirements such as performance, security, and scalability.\n- Build and maintain APIs, including integration with other systems.\n- Set up and manage environments for development, testing, and deployment.\n- Work collaboratively in Agile/Scrum teams across business and technical stakeholders.\n- Support continuous improvement by investigating alternatives and technologies.\n\nRequirements\n\nMust-have:\n- Bachelor’s degree in Computer Science, Information Technology, or a related field.\n- Minimum 4 years of experience in backend development using Java and relevant frameworks (Spring Boot, etc.).\n- Familiar with backend architecture, microservices, and RESTful API design.\n- Experience working with databases such as PostgreSQL, MS SQL Server, or MongoDB.\n- Ability to work independently and take ownership of assigned modules.\n- Good problem-solving, communication, and teamwork skills.\n\nNice-to-have:\n- Experience with .NET/.NET Core is a strong plus.\n- Basic knowledge of frontend development (HTML, CSS, JavaScript, ReactJS or React Native) is an advantage.\n- Experience working in enterprise environments or e-commerce systems is preferred.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1959, 1046, 2, 'Software Engineer (Frontend - Pluto Connect)', 'Company Overview\n\nPluto is a modern financial operating system for global businesses. We combine global payments infrastructure with intelligent workflow automation to provide businesses with unparalleled insights, control, and automation over their spending.\n\nPluto is a venture-capital funded startup backed by top-tier Silicon Valley investors and built by folks from some of the best technology institutions in the world -- Google, Shopify, Square, Uber, PayPal, Cash App, Digital Ocean, Y Combinator, and more\n\nWe are reinventing corporate finance for the modern age and are solving challenging problems in the B2B payments space. With a stronghold in Dubai and sights set on expansion, we\'re now looking for a seasoned frontend engineer to help shape our next chapter\n\nJob Role\n\nAs a Frontend Engineer, you will be developing cutting-edge web applications and libraries for Pluto Connect - our modern embedded spend management platform for banks and financial institutions. This role involves collaborating with high-performing cross-functional teams and external stakeholders to build and ship high-impact integration projects.\n\nKey Responsibilities\n- Develop and maintain complex software applications using React, Typescript, and GraphQL\n- Lead the development lifecycle of features and work streams from design to deployment\n- Collaborate with product managers, designers, and backend engineers to deliver world-class products\n- Become a voracious problem solver who can tackle difficult issues on tight timelines, manage cross-functional dependencies and set an exemplary bar for engineering within the organization\n- Write and maintain clean, maintainable and testable code, leveraging design patterns and architecture where appropriate\n- Participate in code reviews, pair-programming sessions and provide constructive feedback to peers\n- Develop a strong understanding of the domain and bring a deep product and design mindset while building solutions\n\nCandidate Profile\n- Bachelor’s or Master’s degree in Computer Science, Software Engineering or related field\n- Strong fundamentals in computer science, algorithms and data structures\n- 3+ years of experience in software development\n- Experienced in React and Typescript, familiar with GraphQL\n- Strong understanding of web fundamentals, web performance, software design patterns and architecture\n- Experience with modern front-end development tools and frameworks\n- Excellent problem-solving and analytical skills\n- Excellent communication and collaboration skills\n- Experience working with nimble, cross-functional teams with high shipping velocity\n\nOur Tech Stack\n- Frontend: React, TypeScript, GraphQL\n- Backend: Kotlin, GraphQL, Temporal\n- Database: Postgres\n- Infrastructure: AWS, Azure, Kubernetes, Terraform\n- Observability: Datadog, Cloudwatch, Lightstep\n\nOur Values\nAt Pluto, we live by the following core values:\n- Work like a lion, not like a cow 🦁\n- Directly Responsible Individuals (DRI): We empower team members with autonomy to own their projects and outcomes fully, fostering a culture of accountability, clarity and outsized impact. As the DRI you are the driver of success for your projects — proactively identifying, communicating and mitigating risks and resolving blockers to ensure success.\n- Clear Communication: At Pluto, we emphasize clear, transparent communication as fundamental to our success. We strive for clarity, succinctness and transparency in all interactions, ensuring that every message is articulated clearly and understood universally across our teams. This commitment to clarity reduces misunderstandings and fosters a more productive environment especially for distributed teams.\n- Systems Thinking & First Principles Reasoning: We love to deconstruct problems and innovate from the ground up. By understanding complex systems and questioning assumptions, we are able to develop creative solutions to difficult problems.\n- Fact-centric: We are intentional about questioning our assumptions, and bringing the facts to focus by diving into the data, quick-fire experimentation & swift prototyping. We make room for varied perspectives & calibrate our goals with metrics that track our progress, and accurately reflect reality.\n\nBenefits\n- Competitive compensation & stock options so you have skin in the game\n- Remote-first work environment\n- We\'ll ship you a new MacBook\n- Monthly fitness benefit\n- Home-office budget\n- Discretionary learning budget', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1960, 1040, 2, 'C/C++ Developer', 'CHI TIẾT CÔNG VIỆC\n- Tham gia phát triển ứng dụng FPT Play trên nền tảng Set-Top-Box\n- Làm việc theo mô hình Agile/Scrum.\n- Sử dụng git để quản lý code, sử dụng Jira/Confluence để quản lý task và tài liệu.\n- Kiến trúc, review code, tối ưu để tăng trải nghiệm.\n- Phân tích, đánh giá và lập kế hoạch phát triển, trao đổi nhóm, để đưa ra các nhiệm vụ cần thực thi liên quan.\n- Cập nhật xu hướng phát triển công nghệ mới để áp dụng vào dự án.\n- Tích hợp các giải pháp: DRM ,Watermarking, AI, ...\n- Làm các dự án khác theo sự phân công của quản lý đơn vị.\n\nYÊU CẦU CÔNG VIỆC\n- Thành thạo C/C++, hiểu cơ bản về quản lý bộ nhớ, đa luồng.\n- Có kinh nghiệm phát triển phần mềm trên Linux.\n- Có kiến thức căn bản về media playback (video/audio), các giao thức HTTP, socket, và streaming (HLS, DASH).\n- Sử dụng được các công cụ debug như: gdb, logcat, valgrind.\n- Làm việc nhóm tốt, giao tiếp rõ ràng, chủ động.\n- Biết đọc tài liệu kỹ thuật, tư duy hệ thống, có khả năng tự tìm hiểu và debug.\n- Từng làm UI với DirectFB hoặc thư viện đồ họa nền framebuffer là lợi thế.\n- Ưu tiên có hiểu biết về FFmpeg, GStreamer, tối ưu playback\n\nQUYỀN LỢI\n- Gói thu nhập năm tương xứng với năng lực (13 tháng lương, nghỉ mát...)\n- Làm việc trong môi trường năng động, chuyên nghiệp có nhiều cơ hội thăng tiến\n- Cung cấp trang thiết bị đầy đủ để phục vụ công việc\n- Văn hóa doanh nghiệp đa dạng, phong phú; các hoạt động tri ân, chăm lo đời sống tinh thần Cán bộ nhân viên và người thân, Teambuilding, Ngày hội văn hóa, các Câu lạc bộ...\n- Tham gia đầy đủ các chế độ theo Luật lao động hiện hành (BHXH, BHYT, BHTN, ngày phép)\n- Khám sức khỏe định kỳ, nghỉ hè hàng năm; Gói bảo hiểm sức khỏe chuyên biệt FPT Care\n- Được tham gia các khóa đào tạo, nâng cao nghiệp vụ thường xuyên\n- Hưởng các gói ưu đãi cước khi sử dụng dịch vụ của FPT Play', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1961, 750, 2, 'Analytics Engineer', 'Description\n- Participate in creating risk metrics, building dashboards by data visualization tools to monitor & identify abnormal user activities, app usage and fraudulent attempts (e.g., promotion abuse, card payment fraud, account take over, etc.);\n- Do exploratory data analysis to deep-dive into cases of suspicious abuse or fraud (e.g., app & device info, installation and registration behavior, payment transaction details, etc.) and abnormal activities to find out fraudster or abuser behaviors;\n- Work closely with Risk Strategy team, Data Science team, Product team on analyzing and tracking impact & effectiveness of risk rules/policies/products/solutions (coverage, false-positive, drop-off rate of challenge) and propose actionable insights & plans to enhance them;\n- Follow up the efficiency of your recommendations & adapt to different conditions;\n- Work closely with Risk Data Platform team to ensure accurate and high-quality data is collected and analyzed on a consistent basis;\n- Support to establish & develop post-mortem analysis and reporting for multiple aspects of Risk management including but not limited to promo campaigns, payment, wallet risks\n\nRequirement\n- Ability to think critically, analyze and solve problems with a strong attention to detail;\n- Being able to understand and represent business and user needs, distilling insights to set strong road map that meet short and long-term needs;\n- Good organizational and communication skills;\n- Experience in SQL and NoSQL query (e.g., MySQL, MongoDB); master in Python or Excel is a plus.\n- Experience in BI tools (e.g., Tableau) and big data computation (i.e., by using computation engine such as Spark) is a plus.\n- Ability to work well in a fast-paced environment;\n- Ability to manage multiple tasks and deadlines.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1962, 787, 2, 'Go Programmer', 'About Us:\nSFVN Investment Corporation stands as an entity within the Straits Financial Group with its headquarters centered in Singapore and subsidiaries extending across the United States, China, Indonesia, and Dubai. As a well-established player in the financial industry, we specialize in offering a comprehensive range of brokerage services and actively participate in financial derivatives trading.\n\nWe are looking for a Go (Golang) programmer to create new software application systems as well as maintaining existing software applications used in the firm. This is a technical hands-on role. The primary focus for this position is application development, understanding and gathering of user requirements.\n\nResponsibilities:\n- Understand and gather requirements from users requirements for application system development.\n- Develop and maintain PHP dynamic websites based on business requirements\n- Develop and maintain in-house enterprise applications like out of office system, CRM, etc using Go\n- Design, setup, configure and maintain Databases using Postgres or MySQL for use with Go web applications.\n- Design UI/UX and develop interactive and dynamic websites based on business requirements.\n- Maintain existing application systems and websites used by Straits Financial Group.\n- Maintain alignment with Straits Financial Group IT policies and procedures.\n\nCandidate Skills/Requirements:\n- Minimum 3 years’ application development experience ideally full stack development experience.\n- Strong knowledge and experience in Website development is desirable. Including but not limited to HTML5, CSS, Go, PHP, Laravel, etc.\n- Strong knowledge and experience in database design and development is desirable.\n- Ability to pick up new programming languages for application development.\n- Self-motivated, high level of dependability, organization, attention to detail, strong communication and problem solving skills required. Candidate must be able to efficiently multi-task in a fast-paced and challenging environment\n- Strong team player.\n- Python coding and knowledge on Robotic Process Automation tools is a plus.\n- Background and working knowledge of IT Compliance and cybersecurity is a plus\n- Working knowledge of commodity futures trading platforms is a plus\n- Good at English is preferred.\n\nBenefits:\n- Competitive salary\n- Health insurance, social insurance, unemployment insurance\n- Travel and team building activities in accordance with the company\'s guidelines and policies\n- Work in an international environment, utilizing English for seamless interaction with professional departments from diverse countries\n- Working environment: Dynamic, fair competition\n- Working time: 8:00 AM - 5:00 PM, Monday to Friday\n- Probationary period: 2 months\n\nLocation:\nSaigon Pearl Villas, Nguyễn Hữu Cảnh, Phường 22, Bình Thạnh, Thành phố Hồ Chí Minh, Việt Nam', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1963, 740, 2, 'Android Developer (Automotive)', 'Job Description\n\n- Design, develop, code, test, and debug mobile base applications \n- Analyze and optimize application code for efficiency and performance \n- Packaging apps for development to Apps stores \n- Resolve issues or conflicts\n\nRequirements\n\n- Must have: \n  - 3+ years of experience\n  - C/C++ (Intermediate) \n  - Having knowledge of Android Platform architecture \n  - Having hands-on experience working with ASPICE \n  - Having knowledges in Multi-threading, Multi-processing \n  - Having hands-on experience in using at least one version control tool such as Git, Gerrit. \n  - Having hands-on experience in using JIRA, Confluence. \n  - Good English reading, writing (at least TOEIC 600) \n\n- Nice to have:\n  - Having Android native development experience \n  - Having experience working with IPC in Android \n  - Having experience working (i.e., setting/simulating) with CAN signal \n  - Having hands-on experience working with ASPICE\n\nSoftskills\n\n- Results-oriented, Team player, able to Multi-task and work effectively in a fast-paced dynamic environment.\n- Ability to communicate with technical and non-technical stakeholders\n- Ability to work in the highly flexible work environment\n- English is a must\n\nBenefits\n\n- Package: Package 14 salary months based on KPI + Extra package: 16M/year\n- Full benefit with social insurance.\n- Annual health check and CMC care insurance under the company’s\n- Young and dynamic working environment.\n- Opportunity to approach the newest technology trends\n- Exciting leisure: sports and art events (football club, family day…)\n- The company’s labor policy is entirely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trips, holidays, etc.)\n\n3+ years of experience\n\n- Please send your application via email: recruitment@cmcglobal.vn\n- Years of Experience Required\n- Required Education Level\n\nBachelor’s Degree\n\n- Job Level\n\nMiddle/Senior\n\n- Work Form\n\nFull-time\n\n- Email: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1964, 276, 2, 'iOS Engineer', 'ABOUT THE ROLE: We are seeking a highly skilled iOS Engineer to join our dynamic team. The primary purpose of this role is to design, develop, and maintain applications for Apple\'s iOS platform. The successful candidate will collaborate with cross-functional teams to define, design, and ship new features, ensuring the performance, quality, and responsiveness of applications. This role reports to the Mobile Development Manager and plays a crucial part in contributing to the success of our organization by delivering high-quality mobile applications.\n\nWhat to do\n- Design and build advanced applications for the iOS platform\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Ensure the performance, quality, and responsiveness of applications\n- Identify and correct bottlenecks and fix bugs\n- Help maintain code quality, organization, and automatization\n- Continuously discover, evaluate, and implement new technologies to maximize development efficiency\n\nWhat you should have\n- Minimum of 4 years of hands-on experience in native iOS development.\n- Proven experience with SwiftUI in at least 2 projects.\n- Minimum of 6 months of experience working with or studying Flutter.\n- Strong communication skills and ability to work effectively within a team.\n- Proficiency in English communication is a strong advantage.\n- Experience with writing Unit Tests is a plus.\n- Familiarity with modular architecture is considered a plus\n\nWhat we offer\n- Competitive Salary – Deserved Rewards\n  - Attractive salary, aligned with your skills and contributions.\n  - Salary review twice a year to recognize your dedication.\n  - Generous year-end bonus, based on individual performance.\n- Comprehensive Healthcare – We Care About You\n  - Premium health insurance package for extra protection.\n  - Annual health check-ups at top-tier hospitals.\n  - Ergonomic chairs to protect your health.\n  - Access to mindfulness courses for your mental well-being.\n- Modern & Innovative Work Environment\n  - Equipped with MacBook/Laptop & the latest technology to enhance productivity.\n  - Dedicated office floors with 6 levels for various projects.\n- Personal Development – Unlimited Growth Opportunities\n  - Sponsored international certification exams, supporting professional advancement.\n  - Specialized training courses & soft skills development to enhance expertise.\n  - Flat organizational structure, enabling direct collaboration with leaders and fostering creativity and innovation.\n  - Transparent and well-defined career advancement opportunities.\n- Agile Mindset – People-Centric Growth\n  - Open, flexible, and supportive work culture, driving collective success.\n  - Stronger team connections, creating a dynamic and efficient workplace.\n- Work Hard – Play Hard\n  - Exciting activities: Open Talks, IT Seminars, Team Building, Project Trips, Sports Day, Year-End Parties…\n  - Diverse entertainment: PlayStation, Friday Happy Hours, Mindfulness-related activities…\n- Flexible Working Hours\n  - Monday - Friday: 8:00 AM - 11:30 AM | 1:00 PM - 5:30 PM.\n\nJoin TechTus, where we work HAPPILY to achieve our DREAMS together! \n\nABOUT US\nMynavi TechTus Vietnam (formerly known as NAL Solutions) is a technology company headquartered in Da Nang, Vietnam, specializing in software development and consulting for the Japanese market. Since its establishment in 2015, the company has steadily built a reputation as a trusted offshore software development partner in Japan, serving over 200 clients and delivering more than 300 projects of various sizes.\n\nIn March 2025, NALS officially changed its name to Mynavi TechTus Vietnam after becoming a subsidiary of the Mynavi Corporation (Japan) in 2022, aiming to grow into a global software development and consulting company.\n\nThe name "TechTus” holds layered meanings:\n- Tech + Auctus (Latin for “growth”) – expressing a strong commitment to technological development.\n- Tech To Us – reflecting its role as a key technical hub within the Mynavi Group.\nAdditionally, "TECH” represents the company’s four core values:\n- T – Transparency\n- E – Empathy\n- C – Customer Success\n- H – Harmony\nWith the mission “We make wow, we make smiles”, the company is committed to continuous innovation and delivering exceptional value to customers, partners, and employees alike.\n\n𝐌𝐲𝐧𝐚𝐯𝐢 𝐓𝐞𝐜𝐡𝐓𝐮𝐬 𝐕𝐢𝐞𝐭𝐧𝐚𝐦\nHQ: 49A Phan Boi Chau Street, Da Nang City\nBranch 1: SH26, Manor Crown Urban Area – 62 To Huu Street, Hue City\nBranch 2: 8th Floor, HMC Tower, 193 Dinh Tien Hoang Street, District 1, Ho Chi Minh City\nEmail: talents@mynavitechtus.com\nWebsite: mynavitechtus.com\nLinkedin: https://www.linkedin.com/company/74557362\nFanpage: https://www.facebook.com/mynavitechtusvietnam', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Đà Nẵng, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1965, 307, 2, 'Embedded AI Engineer', 'Company Overview\n\nAt Motorola Solutions, we believe that everything starts with our people. We’re a global close-knit community, united by the relentless pursuit to help keep people safer everywhere. Our critical communications, video security and command center technologies support public safety agencies and enterprises alike, enabling the coordination that’s critical for safer communities, safer schools, safer hospitals and safer businesses. Connect with a career that matters, and help us build a safer future.\n\nDepartment Overview\n\nR&D\n\nJob Description\n\n- Deploy AI model to multiple platforms and edge devices\n- Develop application on Linux system\n- Manage and optimize multi-platform deployments\n- Research, Develop, and use various AI Models and Algorithms\n\nBasic Requirements\n\n- Bachelor\'s or Master’s degree in Computer Science or a related field\n- Experience in C/C++, Python, and/or CUDA, experience with edge device deployment is preferred (TensorRT, TFlite, ONNX, etc)\n- Experience in developing applications on Linux Systems\n- Experience with AI frameworks (e.g., TensorFlow, PyTorch) for model development.\n- Experience or knowledge in deploying AI models on chips\n- Good at written and verbal communication in English languages\n\nTravel Requirements\n\nNone\n\nRelocation Provided\n\nNone\n\nPosition Type\n\nExperienced\n\nReferral Payment Plan\n\nYes\n\nEEO Statement\n\nMotorola Solutions is an Equal Opportunity Employer. All qualified applicants will receive consideration for employment without regard to race, color, religion or belief, sex, sexual orientation, gender identity, national origin, disability, veteran status or any other legally-protected characteristic.\n\nWe are proud of our people-first and community-focused culture, empowering every Motorolan to be their most authentic self and to do their best work to deliver on the promise of a safer world. If you’d like to join our team but feel that you don’t quite meet all of the preferred skills, we’d still love to hear why you think you’d be a great addition to our team.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thu Đuc, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1966, 1047, 2, 'CNC Programmer', 'Nhận bản vẽ hoặc mô hình 3D từ Trưởng phòng. \nSử dụng phầm mềm hỗ trợ, dựng mô hình 3D (nếu chưa có mô hình 3D), lên phương án gia công, tên hành lập trình gia công chi tiết.\nXuất và kiểm tra chương trình, làm bảng hướng dẫn cho nhân viên vận hành máy gá đặt gia công chi tiết.\nSửa chữa cải tiến chương trình gia công nâng cao năng suất, chất lượng cho quá trình sản xuất.\nTính toán kích thước phôi, lên phương án gia công chi tết phù hợp với máy móc thiết bị của nhà máy và đảm bảo độ cứng vững, đạt chất lượng về dung sai hình học, dung sai kích thước của chi tiết sau gia công.\nQuyết định phương án gia công phù hợp với chi tiết khó, dung sai kích thước cao.\nXuất chương trình, làm bảng quy trình gia công và các thiết bị máy móc trong quá trình gia công để hướng đẫn nhân viên vận hành máy trong quá trình gia công.\nXác định tìm nguyên nhân và khắc phục các sai sót trong chương trình gia công khi gây lỗi sản phẩm trong quá trình gia công.\nNghiên cứu, cải tiến phương án gia công, chương trình gia công để rút ngắn thời gian gia công, nâng cao năng suất, hiệu quả công việc của nhà máy trong quá trình sản xuất.\nCác công việc khác theo yêu cầu của cấp trên.\n\nYêu cầu công việc:\nTốt nghiệp cao đẳng trở lên chuyên ngành cơ khí\nCó ít nhất 3-10 năm kinh nghiệm lập trình phay CNC 5 trục trở lên.\nĐọc hiểu tốt bản vẽ cơ khí, lên được phương án gia công chi tiết sản phẩm trên máy CNC\nCó kiến thức tốt về công cụ dụng cụ cắt và máy móc thiết bị trong ngành gia công cơ khí.\nĐọc hiểu tốt bản vẽ kỹ thuật, xây dựng được mô hình 3D các sản phẩm trên phẩm mềm chuyên dụng\nHiểu rõ về công cụ gia công, đồ gá, máy móc thiết bị và những tiêu chuẩn kỹ thuật của bản vẽ về cơ khí chế tạo máy.\nSiêng năng, chịu khó, cầu tiến, cẩn thận trong công việc\n\nKỹ năng\n(Bắt buộc) Sử dụng thành thạo phần mềm hỗ trợ lập trình CNC gia công chi tiết CATIA và phần mềm mô phỏng gia công Vericut\nCó kinh nghiệm vận hành và set up máy CNC để hiểu rõ về quá trình gia công\nSử dụng vi tính văn phòng.\nĐọc hiểu được tài liệu kỹ thuật Tiếng Anh.\nKinh nghiệm về sofware ESPRIT là lợi thế \n\nPhúc lợi: \nĐóng BHXH đầy đủ sau thử việc\nBảo hiểm tai nạn 24/7\nThưởng các ngày lễ Tết', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1967, 674, 2, 'QC ENGINEER (AUTOMATION)', 'Mô tả công việc\n\n- Ước tính, lập kế hoạch, viết Test case và thực hiện các hoạt động thử nghiệm.\n- Phân tích và theo dõi kết quả test, báo cáo kết quả test và fix bug.\n- Tham gia lập kế hoạch cho từng sprint, phân tích yêu cầu và đưa ra đề nghị hợp lý.\n- Cùng Team tạo ra các sản phẩm theo đúng yêu cầu và mong muốn của khách hàng.\n- Đảm bảo dự án tuân theo các tiêu chuẩn, quy trình phát triển phần mềm do phòng QA thiết lập.\n\nYêu cầu công việc\n\n- Có hiểu biết cơ bản về kiểm thử phần mềm (Fresher hoặc Junior ~ 1–2 năm kinh nghiệm).\n- Bắt buộc có kinh nghiệm về Automation test.\n- Tỉ mỉ, trách nhiệm, thái độ tích cực, làm việc nhóm tốt.\n- Có kiến thức về lĩnh vực logistics là một lợi thế lớn.\n\nTại sao bạn yêu thích làm việc tại đây\n\n- Có bếp ăn (hỗ trợ chi phí ăn trưa), gửi xe miễn phí.\n- Văn hóa năng động, sáng tạo, Áp dụng mô hình phát triển phần mềm theo Agile, Scrum.\n- Nhiều hoạt động nội bộ: team building, sinh nhật, tiệc cuối năm..., đào tạo phát triển chuyên môn.\n- Môi trường trẻ trung, năng động, được khuyến khích Kaizen, nâng cấp bản thân (công ty hỗ trợ chi phí/nguồn lực/điều kiện học tập).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1968, 998, 2, 'Full Stack Engineer', 'Job Summary:\nWe are seeking a talented and motivated Fullstack Developer with strong expertise in Node.js and React.js to join our development team. You will be responsible for designing, developing, and maintaining scalable web applications, working across both front-end and back-end components.\n\nProject domain : Heathcare (US Customer)\nWhat attracts you to this role/project ?\n- Prestige & Impact: Work with the world’s top health tech companies\n- Learning: Deep-dive into US healthcare data, AI, analytics\n- Growth: Stable, long-term projects with career path guidance\n- Global Collaboration: Cross-region team exposure (Vietnam, India, LATAM, US)\n- Onsite Possibility: For top-performing engineers\n\nKey Responsibilities:\n- Develop and maintain robust, scalable web applications using React.js on the front end and Node.js on the back end.\n- Collaborate with UI/UX designers, product managers, and other developers to deliver high-quality features.\n- Build and integrate RESTful APIs and third-party services.\n- Write clean, maintainable, and efficient code following best practices.\n- Participate in code reviews, testing, and debugging.\n- Optimize applications for maximum speed and scalability.\n- Ensure application security and data protection.\n\nRequired Skills & Qualifications:\n- Strong proficiency in JavaScript, Node.js, and React.js.\n- At least 4 year experience\n- Experience with Express.js or similar Node.js frameworks.\n- Solid understanding of HTML5, CSS3, and modern front-end development practices.\n- Familiarity with RESTful APIs and JSON.\n- Experience with version control systems like Git.\n- Knowledge of databases (SQL or NoSQL such as MongoDB, PostgreSQL, etc.).\n- Understanding of unit testing and automated testing frameworks.\n\nPreferred Qualifications:\n- Experience with TypeScript.\n- Familiarity with CI/CD pipelines and DevOps practices.\n- Exposure to cloud platforms such as AWS, Azure, or GCP.\n- Knowledge of containerization (Docker, Kubernetes).\n\nBenefits:\n- Attractive Salary Package based on your competence plus Annual Bonus and Project Performance Bonus (Range upto 65M)\n- “FPT care” health insurance provided by AON and is exclusive for FPT employees\n- Excellent cost-free learning opportunities: Udemy Premium account, English class, sponsor for taking certification such as PMP, AWS, etc.\n- Annual leave according to Labor Law and Company Policy\n- Annual Summer Vacation support from 1 Million VND to 6 Million VND and up to 3 days off work\n- 13th-month Salary\n- Salary review according to Company Policy\n- International, professional, dynamic and friendly working environment and culture\n\nCONTACTS\nContact Person: Hai Nam ( 0339402772 )\nEmail: NamNH144@fpt.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1969, 1048, 2, 'Senior Full Stack Engineer (Typescript, ReactJs, NodeJs)', 'What we\'re looking for\nA passionate builder with a mission to democratize home ownership.\nAn ambitious software artisan with a motivation to grow high and aim big with your career.\nAn excellent engineer with an itch for details and a drive to build great user-centric products.\n\nAbout us\nRingkas is helping to democratize home ownership for Indonesia that facilitates access to financing to help home seekers become home owners. Ringkas is built by passionate founders from Google, Amazon, Dell with backgrounds in tech whom have scaled product and digital businesses worldwide. We are backed by VCs, and several prominent angel investors who have built FinTech platforms for millions of people in Indonesia and the US.\nOur vision is to Democratize home ownership and make it accessible for everyone. Our mission is making homeownership simpler, faster and accessible for all. We believe homeownership should be fast, transparent, and low-cost for all. Home and Mortgage finance has operated through traditional opaque systems for years. We are redefining the homeownership process from the ground up and end to end. We’re using technology to make it faster and more efficient, through trusted partners and people to help make a seamless customer experience.\n\nRoles And Responsibilities\nBuilding a fintech product with technologies spanning from back-end, front-end and related DevOps tasks.\nProvide consultations for Product Managers & other stake holders with your experience & technical adepts to ensure we have the right approach, a good solution and a nice execution.\nCoaching & mentoring your other team members with your skills & experience.\nDoing code review for other team members, ensuring only good code can get into the repository, and push to continue raising our standard.\nHaving good ownership & responsibility for your work.\n\nRequirements\nExcellent analytical and problem-solving skills.\nAt least 3+ years of solid work experience with TypeScript and ReactJS or NodeJS.\nAt least 2 year of experience with designing complex database schema with SQL.\nAt least 2 year of experience with building software on cloud (either AWS, GCP or Azure, etc.).\nExperience in resolving issues related to technology, product, or development process.\nExperience in back-end development and operation of web applications using NodeJS, Postgres, Sequelize, Typescript.\nExperience in front-end development using React.\nExperience designing, developing, and operating Microservices.\nUnderstanding of product development cycles, design thinking.\nExcellent English communication will help you grow much faster in our multi-culture organization.\n\nHighly valued, but not required\nExperience working with Scrum or Agile methodologies.\nExperience with building software on AWS, AWS Lambda, Serverless framework.\nExperience with GraphQL, Hasura, Apollo, Redis, IaaC.\n\nBenefits\nCompetitive compensation.\n13th Month Salary.\nWork from home 1 day/week.\nMonitor provided by the company.\nCompany sponsorship for personal laptop $1,400 or BYOD (bring your own device) option with bonus $1,400.\nPrivate Health Insurance.\n100% Insurance According To Labor Law.\n14 Days Paid Annual Leave.\nGifts on holidays, parking, wedding & newborn baby allowance.\nOffice facilities: Coffee maker, snacks & drinks.\nMonthly Cursor license $40.\nHappy hour, Team bonding, Company trip.\nOpportunities for onsite trips to Indonesia.\nMulticultural, English-speaking, challenging but fun environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1970, 1049, 2, 'Senior Software Engineer (Python/Java)', 'Position: Senior Backend Engineer\n\nKey Responsibilities:\n- Collaborate on domain-specific challenges by designing, building, and deploying backend services optimized for performance, scalability, and reliability.\n- Contribute to change delivery by analyzing, defining, and documenting technical requirements and identifying appropriate solutions using agile methodologies.\n- Tackle complex technical and business issues while staying updated with modern technologies and tools.\n- Take full ownership of assigned features, including design, development, testing, deployment, monitoring, and continuous improvement.\n\nIdeal Candidate Profile:\n\nRequired:\n- 5+ years of experience in backend or full-stack development using general-purpose languages such as Java or Python.\n- Solid understanding of database design and architecture for large-scale systems.\n- Strong interpersonal skills and ability to thrive in agile teams.\n- Proficiency in English.\n\nPreferred:\n- Familiarity with microservices, serverless, or event-driven architectures. Experience with technologies such as Spring Boot, Kafka, Redis, or Python frameworks (Flask, Django, FastAPI) is advantageous.\n- Exposure to cloud platforms and tools like AWS, Docker, Kubernetes, Ansible, and Packer.\n- Experience with automated testing practices and tools.\n\nPerks & Benefits:\n- Meal and transportation allowances.\n- Full salary and benefits during the probationary period.\n- Health insurance coverage aligned with labor regulations, plus premium healthcare support for both you and your family.\n- Annual performance bonus of up to 2 months’ salary and a pro-rata 13th-month salary.\n- Generous leave policy: 15 annual leave days, 3 sick days, 1 birthday leave, and 1 additional holiday leave.\n- Clear career development opportunities, including access to technical workshops, conferences, and growth talks.\n- Supportive, agile working environment with a strong team culture.\n- Occasional opportunities for international training or work-related travel.\n- Internal tech events and team activities (hackathons, team building, casual gatherings).\n- Standard 40-hour workweek (Monday to Friday), promoting work-life balance.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1971, 844, 2, 'Kỹ thuật viên, Chương trình vận hành bền vững (Mảng Sản xuất sản phẩm điện tử)', 'Please visit this Google Careers posting for the English-translated version of this role.\n\nMinimum qualifications:\n\n- Bằng cử nhân hoặc kinh nghiệm thực tế tương đương.\n- 1 năm kinh nghiệm quản lý chương trình.\n- Kinh nghiệm quản lý các chương trình trong môi trường kỹ thuật.\n\nPreferred qualifications:\n\n- Tối thiểu 3 năm kinh nghiệm làm Kỹ thuật viên — Hỗ trợ trong Chương trình vận hành bền vững (trong mảng sản xuất sản phẩm điện tử)\n- Có kinh nghiệm làm việc và xử lý các vấn đề kỹ thuật cho các đối tác sản xuất thiết bị gốc (OEM) quốc tế\n- Có kinh nghiệm xử lý các vấn đề kỹ thuật trong phòng ban liên ngành để đạt được các mục tiêu đề ra cho sản phẩm mới, bao gồm cả chất lượng, lợi nhuận và chi phí\n- Có khả năng hỗ trợ và đề xuất giải pháp cho các nhóm đa chức năng\n- Có khả năng tham gia các cuộc trò chuyện về kỹ thuật bằng tiếng Anh và tiếng Quan Thoại một cách lưu loát\n\nAbout The Job\n\nMột vấn đề chỉ thực sự được giải quyết khi không còn ai gặp vướng mắc. Đó là lý do nhân viên của Google xây dựng những sản phẩm tạo ra cơ hội cho mọi người, bất kể là họ sinh sống tại địa phương hay ở bên kia Địa Cầu. Trong vai trò Quản lý chương trình tại Google, bạn sẽ dẫn dắt từ đầu đến cuối các dự án phức tạp và đa lĩnh vực — làm việc với các bên liên quan để dự trù yêu cầu, quản lý lịch biểu dự án, phát hiện rủi ro và trao đổi rõ ràng với các đối tác liên chức năng trong công ty. Thường thì các dự án sẽ trải rộng qua nhiều văn phòng, múi giờ và bán cầu. Công việc của bạn là điều phối các bên liên quan và giúp họ luôn nắm được tiến độ và thời hạn.\n\nSứ mệnh của Google là hệ thống hoá thông tin từ khắp nơi trên thế giới, giúp những thông tin đó trở nên hữu ích và dễ dàng tiếp cận trên toàn cầu. Nhóm Thiết bị và dịch vụ của chúng tôi kết hợp những điểm ưu việt nhất có trong AI của Google, Phần mềm và Phần cứng, nhằm mang lại trải nghiệm hữu ích về mọi mặt cho người dùng. Chúng tôi nghiên cứu, thiết kế và phát triển các công nghệ cùng phần cứng mới để người dùng có thể tương tác với công nghệ điện toán một cách nhanh chóng, mạnh mẽ và liền mạch hơn. Dù là tìm kiếm những cách mới để nắm bắt và cảm nhận thế giới xung quanh, cải tiến các yếu tố hình thức hay cải thiện phương pháp tương tác, mục tiêu mà nhóm Thiết bị và dịch vụ của chúng tôi hướng đến là làm cho cuộc sống của mọi người trở nên tốt đẹp hơn thông qua công nghệ.\n\nResponsibilities\n\n- Hỗ trợ thúc đẩy tiến độ vận hành trong nhà máy bằng cách tận dụng tài nguyên của đối tác cũng như hỗ trợ hiệu suất và cải tiến liên tục từ khi sản xuất cho đến Hết vòng đời sản phẩm (EOL).\n- Làm việc với đối tác OEM (Nhà sản xuất thiết bị gốc) theo chỉ đạo của cấp trên để hỗ trợ họ đảm bảo đạt hoặc vượt mục tiêu hiệu suất về Năng suất toàn quy trình, Chi phí phế liệu, Chất lượng, Thời gian hoàn thành và Công suất.\n- Hỗ trợ cấp trên trao đổi thông tin và giảm thiểu rủi ro vận hành, đồng thời phối hợp chặt chẽ với OEM để giải quyết các vấn đề liên quan đến việc triển khai dây chuyền, kiểm định, nguồn cung nguyên vật liệu và chất lượng. Hỗ trợ đảm bảo năng lực sản xuất dựa trên dự báo theo quý và theo tuần.\n- Hỗ trợ cấp trên chuẩn bị kế hoạch trao đổi với các bộ phận vận hành liên chức năng và hoạch định nhu cầu, điều chỉnh kế hoạch cho phù hợp với thay đổi cần thiết theo chỉ đạo.\n- Phối hợp với OEM và các nhóm Vận hành để ưu tiên giao hàng hoặc đơn hàng quan trọng; và hỗ trợ để đảm bảo đơn hàng được vận chuyển theo đúng lịch.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1972, 297, 2, 'Fullstack Developer (NodeJS,ReactJS - Middle/Senior Level)', 'We are looking for a full-stack web developer to join our team with NodeJS/ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc.\nLocation: Ho Chi Minh, Da Nang, Hanoi\n\nWhat You\'ll Be Doing\n- Working on Web and Mobile products for a diverse range of clients and industries\n- Working and pair programming with other developers to build applications with Python/Node.js and ReactJS\n- Designing & implementing back-end API using Python/Node.JS\n- Working with Product Owner to convert business requirements into technical designs\n- Cooperating with UI Designer to implement modern minimalist designs into production\n- Applying proven technologies and best practices to level up your technical skills: NestJS, Redux\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment\n\nRequirements\nMust have\n- Require a minimum of 4 years of experience with Node.JS\n- Require a minimum of 2 years of experience with ReactJS or similar such as Svelte, VueJS, AngularJS\n- Require relevant knowledge of relational database systems such as MySQL, PostgreSQL, and SQL Server\n- Experience with Extreme Programming methodologies such as Test-Driven Development, Refactoring, and Continuous Integration\n- Experience with Agile Process and Scrum Methodologies\n- Excellent written and verbal communication skills in English\n\nNice to have\n- Experience with serverless architecture, eg AWS Lambda, GCP Cloud Function, etc\n- Experience with security, performance, scalability\n- Experience with NoSQL, Message Queue\n- Experience with Infrastructure as Code (IaC) tools such as Terraform, Ansible, or CloudFormation\n\nBenefits\n- Three days remote every week and four full remote weeks per year\n- Gold level Health Insurance coverage from Bao Viet Insurance, a yearly complete Health Check and social insurance\n- All office benefits and full salary during probation\n- Flexible working time starting anytime up to 10 AM working Monday - Friday with no overtime and a long lunch break\n- Allowance for everything: meals, parking, petrol, along with unlimited snacks and nice coffee every day\n- Choose from a brand-new Mac or PC device\n- Salary review twice a year with opportunities for promotions and spot awards\n- 12 days annual leave per year, with all days not taken paid out in cash, plus 2 sick leave days.\n- Yearly Training Budget up to 5 million VND per staff. On top of that, Professional coaching program, buddy system, tech talks, agile sessions, and 1on1 private English classes are available\n- Yearly company trip, monthly activities, and other Celebrations for special days in the year, such as Women\'s Day, YEP, and Christmas\n- Employee-led clubs within the company; games teams, sports teams, etc\n- Modern open-space office with comfortable workspace, a PS4 games room, and chill-out areas.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1973, 1050, 2, 'Senior Fullstack Developer - Odoo', 'Mô Tả Công Việc\n- Phát triển các hệ thống phần mềm dành cho doanh nghiệp như CRM, HRM, IoT, MES... dựa trên nền tảng Odoo.\n- Tham gia toàn diện vào vòng đời phát triển phần mềm: từ khảo sát yêu cầu, thiết kế giải pháp hệ thống, phát triển tính năng, kiểm thử cho đến bảo trì sau triển khai.\n- Tùy biến và xây dựng các mô-đun Odoo đảm bảo đúng nghiệp vụ, tối ưu về hiệu suất và khả năng mở rộng cho tương lai.\n- Thiết kế, phát triển API (REST/XML-RPC) để tích hợp Odoo với ứng dụng di động, thiết bị IoT và các nền tảng bên ngoài.\n- Làm việc chủ yếu với cơ sở dữ liệu PostgreSQL; có hiểu biết về các hệ quản trị khác là một lợi thế.\n- Xây dựng mã nguồn có thể tái sử dụng, phát triển thư viện dùng chung nội bộ và chuẩn hóa quy trình lập trình dự án.\n- Chủ động tìm hiểu, cập nhật công nghệ mới nhằm cải tiến chất lượng phần mềm và tối ưu hóa các quy trình DevOps, CI/CD.\n\nYêu cầu ứng viên\n- Ít nhất 3 năm làm việc với Odoo.\n- Có kinh nghiệm làm việc với PostgreSQL, hiểu về indexing, optimization, data modeling.\n- Hiểu cơ bản về HTML, CSS, JavaScript; biết tùy chỉnh giao diện Odoo là lợi thế.\n- Từng triển khai hệ thống Odoo trên môi trường AWS/Cloud.\n- Có kinh nghiệm thiết kế API tích hợp giữa Odoo và hệ thống bên ngoài.\n- Ưu tiên: Có hiểu biết hoặc từng làm việc với IoT, hệ thống streaming, Biết DevOps, CI/CD, Docker là điểm cộng lớn.\n- Kỹ năng làm việc nhóm tốt, chủ động và linh hoạt trong môi trường Agile/Scrum.\n\nQuyền lợi\n- Mức lương cạnh tranh, thỏa thuận theo kinh nghiệm/năng lực;\n- Thời gian làm việc: Thứ Hai – Thứ Sáu, thời gian làm việc linh hoạt;\n- Thử việc hưởng 100% lương, được trang bị công cụ làm việc theo chính sách của công ty;\n- Môi trường làm việc trẻ trung, năng động, tài năng;\n- Được đánh giá review lương định kì 6 tháng/lần;\n- Thưởng ngày Lễ/Tết, thưởng KPI, thưởng dự án;\n- Được khám sức khỏe định kỳ;\n- Du lịch/nghỉ mát cùng công ty hàng năm;\n- Các chế độ khác theo quy định của pháp luật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1974, 1051, 2, 'Senior Java Developer', 'Senior Java Software Developer\n\nLocation: Ho Chi Minh City\n\nWorkplace Type: Onsite\n\nKey Responsibilities\n\n- Work as a software developer on web-based application products using Java and related open-source technologies\n- Upgrade existing functionalities and create new ones using data-driven insights\n- Implement and deliver new customer project developments with high quality\n- Participate in all phases of the development cycle, including planning meetings\n- Implement new features according to business specifications\n- Write unit/functional/integration tests and perform unit testing\n- Conduct code reviews for other team members\n- Automate maintenance work through development\n- Respond to and resolve IT support requests from employees via phone, email, or service request system\n\nRequired Skills & Qualifications\n\n- Good command of English (both written/verbal) is essential\n- 5+ years of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend\n- Ability to analyze, design, and develop new functionalities, and provide maintenance or issue fixes\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner)\n- Proficient in tools/technologies: Azure, AWS, Redis\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools\n- Database experience in Oracle, MS SQL Server, or MySQL - with strong SQL, stored procedures, functions, schedulers, etc\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications\n- Solid understanding of OOP, design patterns, and coding standards\n\nAdditional Information\n\nPreferred Qualifications:\n\n- Experience with AWS\n- Experience with MS .Net / .Net Core\n- Experience with Kubernetes\n- Experience with React.js\n- Experience with Nginx\n- Experience with JUnit\n- Experience with Jasper Report\n- Experience with ElasticSearch & Kibana (ELK)\n- Experience with Grafana\n- Experience with Prometheus (monitoring/alerts)\n\nBenefits:\n\n- Salary: Up to 60M VND\n- Probation salary is 100% of official salary\n- 13th-month salary and performance review twice a year\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n- Project Bonus\n- IT Certificate allowance\n- Health Care Insurance\n- Social, health, and unemployment Insurance following Government policy\n- Enjoy company summer trips and other team-building activities held monthly and quarterly\n- Work five days per week with flexible check-in time\n- Professional, creative, and dynamic working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1975, 950, 2, 'Kỹ sư IE', 'Vị trí: Kỹ sư IE\n\nĐịa điểm làm việc: Bắc Giang\n\nMức lương: 15-25 triệu\n\nMÔ TẢ CÔNG VIỆC:\n- Lên layout và quy hoạch bố cục nhà xưởng.\n- Quy hoạch sản lượng, tiêu chuẩn công việc nhằm nâng cao hiệu quả trong sản xuất.\n- Xem xét tổng thể và sắp xếp các dự án set up dây chuyền nhà xưởng, phân bổ thứ cấp.\n- Tối ưu hoá hệ thống OEE\n- Các công việc liên quan khác.\n\nYÊU CẦU CÔNG VIỆC\n- Tốt nghiệp Cao đẳng/ Đại học trở lên.\n- 25-40 tuổi\n- Có 2 năm kinh nghiệm trở lên ở vị trí kỹ sư IE trong môi trường sản xuất điện tử\n- Tiếng Trung sử dụng tốt trong công việc.\n\nChế độ:\n- Thời gian làm việc: 8h00-17h00 Thứ 2- Thứ 7\n- 13 tháng lương, 12 ngày nghỉ phép/ năm, BHXH đóng 70% tổng lương\n- Thưởng cuối năm 2-5 tháng lương theo hiệu quả công việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bac Mé, Ha Giang, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1976, 702, 2, 'Principle/Lead Engineer (Java) - Growth Tech', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nJoin the Exchange Service team at Binance, the world\'s leading cryptocurrency exchange serving over 250M+ registered users across 100+ countries. As dedicated software engineers, we are responsible for developing and maintaining the core trading platform, ensuring seamless and efficient operations. Our work solidifies Binance as the preferred choice for crypto enthusiasts worldwide.\n\nResponsibilities\n\n- Development and implementation of financial and marketing products.\n- Work closely with the Marketing department with the goal of increasing our global user base.\n- Build large scale software system, which can impact daily life of millions of customers.\n- Communicate effectively with product managers, designing and implementing product features.\n- Performance tuning, online incidents troubleshooting, and system refactoring.\n- Write high-quality, clean, and maintainable code using engineering best practices.\n- Supervise and mentor junior developers on the team.\n\nRequirements\n\n- 10+ years of software development experience with full lifecycle of project development for Java Applications.\n- Strong skills in Core Java, server-side Java technologies, and Spring frameworks.\n- Extensive experience in software design, architecture, development integration.\n- Solid knowledge of event processing models, multi-threading, enterprise integration pattern, Web Service and REST.\n- Bonus for degrees in: Computer Science, Computer Engineering, or Software Engineering.\n\nAdditional Preferred Skills\n\n- Proficient in spring cloud and micro-service design.\n- Working experience on backend system of large internet company.\n- Performance tuning experience on JVM, SQL, RPC, etc.\n- Experience creating React-based UIs.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem.\n- Collaborate with world-class talent in a user-centric global organization with a flat structure.\n- Tackle unique, fast-paced projects with autonomy in an innovative environment.\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning.\n- Competitive salary and company benefits.\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team).\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1977, 1052, 2, 'Mobile Application Developer (Hybrid, HCMC)', 'Avensys is a reputed global IT professional services company headquartered in Singapore. Our service spectrum includes enterprise solution consulting, business intelligence, business process automation and managed services. Given our decade of success we have evolved to become one of the top trusted providers in Singapore and service a client base across banking and financial services, insurance, information technology, healthcare, retail and supply chain.\n\nJob Responsibilities \n\nGeneral skills: \n\nExceptionally strong written and verbal communication skills, as well as good interpersonal and organisational skills\nStrong delivery focus with an active approach to quality\nWorking with key stakeholders and the wider mobile service team\nExcellent analytical, troubleshooting & documentation skills\nAdept to work under pressure and self-manage tasks\nEnthusiasm for technology and solving problems\nLeadership qualities and skills\n\nEssential technical knowledge, experience and attributes: \n\nExperience across the full software delivery life cycle (planning, analysis, design, implementation, testing, deployment, and maintenance)\nAgile software development and management methods and ability to excel within a fast-paced environment\nA solid technical background as a Mobile engineer with seasoned React Native experience and Kotlin/Java or Swift/Objective-C\nExperience working with diverse teams from development, testing, security, architecture, infrastructure to business and management\nExperience with build management tools including continuous integration and delivery practices and tools (Gradle, Jenkins)\nExperience with continuous test automation tooling (Perfecto, Applitools)\nSoftware design and delivery with UX and accessibility front of mind\nExperience with latest development methodologies and tooling\nDevelopment experience using common IDE and source systems (Android Studio, Git)\nWriting unit and functional automation tests (Junit, Roboelectric, Espresso)\nRelease and configuration management practices including parallel development (tagging/branching strategies), managing multiple versions and third party library dependency management\nExperience with repository artifact management (Artifactory)\nKnowledge of code quality analysis tools (coverage, duplication, complexity, dependency analysis and standards)\n\nDesirable technical knowledge, experience and attributes: \n\nExperience working as an engineer within one or more alternate mobile application development technologies (Kotlin/Java, Objective-C/Swift, React Native)\nExperience working as an engineer within one or more backend technologies, RESTful JSON APIs and microservices\nExperience with Query Languages for APIs (GraphQL)\nExperience with cloud-based technologies and managed services (AWS)\n\nTo submit your application, please apply online or email your UPDATED CV in Microsoft Word format to joycetrieu@aven-sys.com. Your interest will be treated with strict confidentiality.\n\nCONSULTANT DETAILS:\nConsultant Name : Joyce Trieu\nAvensys Consulting Pte Ltd\n\nPrivacy Statement: Data collected will be used for recruitment purposes only. Personal data provided will be used strictly in accordance with the relevant data protection law and Avensys\' privacy policy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1978, 856, 2, 'Software Engineer - Integration Build (Embedded, C, C++, Python)', 'DESCRIPTION\nAs member of Software Engineering Team, your main responsibilities will depend on the job position for which you qualify:\n\n(1) Software Engineer - Integration Build (OpenSource system, C, C++, Python):\nOperation and maintenance of (CI/CD/)CT pipeline based on Jenkins, BlackDuck Hub, Scancode and In-house system(VOSC)\n(Yocto, Android, etc) Extending application and optimization of build-based Open Source Scan\nOSS package verification and optimization\n\n(2) Software Engineer - Integration Build (C, C++, Python):\nDesign & set up an initial build environment for a new project and provide/maintain an environment for developers to build.\nImprovements to the Build System and developer development environment.\nEstablish a configuration management policy(Code quality and Code Review System) in close collaboration with other department, and set up and operate various tools that can help improvements Code quality and SW stabilize.\n\nREQUIREMENTS\nJob requirements will depend on the position you qualify for:\n\n(1) Software Engineer - Integration Build (OpenSource system, C, C++, Python):\nUnderstanding of open source licenses (e.g., GPL, MIT, Apache)\nExperience in Yocto Build System, Android Build System\nExperience in Git, Jenkins, BlackDuck Hub, Fosslight scanner\nExcellent skills in Python, Shell scripts and Linux System\nGit & Gerrit experience (comfortable using code review and source code repository management)\nKnowledge in containerization technologies such as Docker\n\n(2) Software Engineer - Integration Build (C, C++, Python):\nExperience in Embedded Linux system\nFluency in C, C++, Java, Kotlin, Python, Shell scripting, Make. CMake.\nHaving hands-on experiences in using version control tool such as Git, gerrit(comfortable using code review and source code repository management);\nKnowledge in containerization technologies such as Docker, VM', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1979, 878, 2, 'Senior Full Stack Developer (Da Nang, Hybrid) (Visa and Relocation Package Provided)', 'About Nimble\n\nWe solve our client\'s most difficult business challenges through technology. Our company partners with the most ambitious companies around the world creating long-term impact with the work with do. If you want to grow together, work on challenging products and enjoy using the best tools and practices, Nimble is the right place for you!\n\nOur Core Values\n\n- Extreme Ownership: We treat our clients’ business as ours.\n- Bias for Action: Execution is everything. We act swiftly, prioritize decisive moves, and maintain a strong bias for action to deliver results.\n- Intensity: We tackle challenges with high energy and focus, delivering results through bold, committed actions.\n- Pragmatism: We prioritize practical, straightforward solutions that deliver results, creatively tackling complex challenges with determination.\n- Outcome Over Process: We always work toward impactful outcomes, driving results that matter. Processes help us repeat what works, but meaningful outcomes remain our North Star.\n- Truth Seeking: We seek truth with intellectual honesty, sharp critical thinking, and fact-driven reasoning.\n\nWhat You Will Do\n\n- You will be an active member or lead a team of developers in a project squad. We have a wide range of project sizes.\n- Decide which technologies are going to be used for front-end, back-end and define the overall architecture.\n- Work closely with the Product Owner to make sure the backlog is efficiently planned and occasionally assist in technical discussions with clients. Most of the client interfacing is done by the Product Owner.\n- Write clean, composable, and maintainable code as you develop world-class products for our clients.\n- Write automated tests to build and maintain the product we build for our clients.\n- Do code reviews with your squad members.\n- Learn new technologies languages like Ruby, Go, or Elixir, and techniques so that you are able to adapt to the evolving needs of our clients.\n- Knowledge sharing through team rituals.\n- Collaborate with other team members to define the internal processes and initiatives to help the company accomplish its mission. Our handbook has been written by the whole team.\n\nJob Requirements\n\n- Professional web development with 5+ years of experience. Experience in Ruby, JavaScript, Go or PHP is ideal (at least one of them).\n- Comfortable working both on frontend and backend.\n- At least basic experience with a modern JavaScript framework like ReactJS/Redux, VueJS or AngularJS.\n- Experience in writing automated tests for web applications.\n- Enjoy working on challenging solutions and systems.\n- Believe that building great applications is not only about delivering code that “works”, but involves thinking about reusability, maintainability, security, and performance.\n- A \'Can do attitude\' and a product mindset.\n- Confidence in communicating in English.\n\nWhy You\'ll Love Working Here\n\n- You’ll feel proud of every product we ship. We care deeply about quality, design, and doing things right—our name stands for excellence.\n- You’ll be surrounded by high performers. We’re a tight-knit, ambitious team that pushes each other to grow and thrive.\n- We\'re built differently. We’ve been profitable and bootstrapped since day one—no VC pressures, just smart, sustainable growth.\n- We take pride in craftsmanship. Whether it\'s code, design, or delivery, we hold ourselves to a high bar—because the little things shape the big picture.\n- Process with purpose. We follow agile principles not just in theory, but in practice. Our engineers work with clearly defined user stories, estimate using story points, and deliver iteratively in focused 1–2 week sprints.\n- Growth is part of the job. Through regular one-on-ones, structured feedback, and a clear leveling framework, we support every team member’s growth—not just in technical skills, but in communication, collaboration, and leadership.\n- Learning never stops. Access a vast library of resources like Pluralsight, PragPub, Leanpub, e-books, and more—plus a yearly education allowance to help you level up in any direction you choose.\n- We’ve got your back. From day one, you’ll get private medical insurance, social welfare coverage, and a company care fund.\n- We support your move. If you\'re joining us from abroad, we’ll take care of your visa, work permit, and provide a relocation package to help you settle in smoothly.\n- Flexibility that fits. We support a hybrid workstyle, giving you the freedom to find the right rhythm between home and office life.\n- Work with the right tools. We’ll set you up with a MacBook and a large external monitor so you can work comfortably and efficiently.\n- A workspace that works for you with our modern office in the heart of Ho Chi Minh City and Da Nang.\n- Stay fueled. Our kitchen is always stocked with drinks and snacks.\n- Take the time you need. Enjoy 26 days of paid leave a year (including public holidays), plus a sabbatical month every 3 years.\n- Celebrate your journey. From anniversary gifts to yearly company outings and spontaneous team activities, we make time for fun and appreciation.\n- ...and more perks to make work feel better.\n\nIf you are a passionate web professional looking to make a significant impact in a growing software development company, we would love to hear from you.\n\nJoin us in shaping the future with with elevating web innovation!\n\nWe keep our recruitment process practical and straightforward.\n\nTo learn more about how we work, check our handbook named Compass, Github organization, and Medium account.\n\nWant to see what we have built? Check our Dribbble and Behance accounts.\n\nWant to keep in touch with us? Follow us on Facebook, Instagram, and LinkedIn.\n\nNimble is an equal opportunity employer.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1980, 822, 2, 'Principal Backend Engineer (Java Springboot/Kotlin)', 'Principal Backend Engineer (Java Springboot/Kotlin)\n\nUrgent\n\nHo Chi Minh\n\nTech/Engineer\n\nTOP 3 REASONS TO JOIN US\n\nPerks you will love: Hybrid woring; 16 - 24 paid days off; Top modern & sufficient devices\nSolid global business: No.1 market - 13.7 million B2C users in Japan; 140,000+ paying business customers; Listed in the prime market of Tokyo Stock Exchange\nHub of growth support: Fintech industry; Tailored L&D programs for individual growth\n\nJob Description\n\nWe\'re building Saas products and services and there are certainly a lot of things to do. As part of the team, you’ll encounter both technical and business challenges on a daily basis. Below are some examples that we believe you will find interesting.\n\nTech Challenges\n\nPerformance optimization (slow DB queries, High latency API,...)\nMicroservice design (domain driven design, decoupling service,...)\nAsync processing\nService logging & monitoring\n\nBusiness Challenges\n\nLarge enterprise support with thousands of record\nPay as you go charging\nDomain boundary context\n\nResponsibilities\n\nDevelop BtoB applications having a massive amount of data from scratch\nDesign a complex architecture that includes API linkage to external systems\nQuickly fix system failures or abnormalities by monitoring or notifications\nImprove CI/CD for the delivery of a product\nIntroduce tools, systems and cultures for efficient development\nDevelop fundamental skills of team members\nLead the development team of 7+ members with Agile/scrum methodologies and processes\nMust have a positive attitude towards learning and working on Ruby on Rails applications. Currently, most of our applications are developed by Ruby on Rails, and we have started to replace Ruby on Rails with Kotlin. However, we still have a significant amount of Ruby on Rails code.\n\nRequirements\n\nWe are looking for below roles: \nPrincipal Java Engineer (8+ years of total experience in Java) \nOur requirements: \n\nMust Have:\nHaving experience in Java/Kotlin development with detail mentioned above\nHaving experience in operation of an application on a production environment\nExperience to develop B2B applications\nExperience in improving application performance\nExperience with Agile development\nHaving a strong product mindset \nContainer-based development (Docker, docker-compose, Kubernetes) experience\nWriting comprehensive and maintainable test code\nExperience using, designing, and building GraphQL Web Service APIs\nExtensive experience with Spring framework: Spring Boot, Spring Data, Spring Security, Spring Batch, Spring Cloud\nKnowledge of Domain Driven Development and Onion Architecture \nStrong knowledge of sql (MySQL) and no-sql design/optimization and ORM \nExperience with Microservices\n3+ years experience in leading a team of 7+ engineers to build, deliver and operate projects successfully, fostering a collaborative and high-performance culture.\nStrong sense of ownership\nExcellent English verbal communication skills\nHave ability to build and review technical architecture, have the ability to provide solutions for technical problems and train junior members in the team.\n\nNice to Have:\nExperience with Terraform (IaC).\nExperience with scrum master role.\nExperience working in a multi-cultural environment.\nBuild and maintain application infrastructure built on AWS\n\nOur benefits\n\nCaring Mental & Physical Recreation\n\nHybrid working: 2 days at the office and 3 days WFH\nWorking hour: Flexible start 8AM-9AM from Mon-Fri\nFull salary in probation\nInsurance: Applied from Probation period:\nSocial Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\nPrivate health insurance & accident insurance. From Managing level: extra for family members\nBonus: 13th month salary\n16 - 24 paid days off and more\nPaternity leave: Extra 5 days\nAnnual company trip; Quarterly team building\nBilliards & Running club\nAnnual health check\nWell-equipped facility: Macbook pro, additional monitor,\n\nCaring Career & Development\n\nClear Career path\nForeign language & International technology-related certifications sponsoring\nExternal & internal training courses\nSoft-skill workshops\nTech seminars\nMonthly and biannual Recognition Awards\nPerformance & salary review: twice/year (Jun & Dec)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه هو شي مينه سيتي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1981, 532, 2, 'QA Automation Engineer – JavaScript/TypeScript | Tester, QA/QC', 'About the Role:\nSunbytes is actively seeking a highly skilled QA Automation Engineer to play a pivotal role dedicated exclusively to our distinguished Dutch client in the ever-evolving field of IoT security. Picture yourself joining a team of exceptionally talented individuals from Europe and Asia, collaborating seamlessly with our client in the Netherlands to deliver trailblazing software solutions in the dynamic IoT security industry.\nAs a QA Automation Engineer, you won\'t just be part of a team; you\'ll be instrumental in crafting innovative products that not only meet but exceed the expectations of our clients. Collaborate with a team of highly proficient software engineers to create solutions that add substantial value. The allure doesn’t end there – success in this role opens the door to a long-term position, offering an exceptional opportunity to grow in tandem with the escalating success of our client.\n\nResponsibilities\n- Collaborate with cross-functional teams to ensure the quality of software applications.\n- Conduct API and UI testing to verify functionality, reliability, and user-friendliness.\n- Develop and execute comprehensive manual test cases; promptly report and track identified issues.\n- Implement automated tests using Typescript (and Jest) to enhance software efficiency and accuracy.\n- Utilize industry-standard frameworks for API automation testing.\n- Leverage Jira Xray for effective test resources management and collaboration within the testing competence center.\n- Knowledge of SQL for data analysis would be a nice addition.\n\nJob Requirements\n- Minimum of 3 years of experience in testing and quality assurance.\n- Proficiency in Typescript (or JavaScript) for developing automated tests.\n- Strong experience in API automation testing (Postman or Swagger).\n- Knowledge of Selenium for automated web browser testing is a good addition.\n- Highly motivated with a proactive approach to problem-solving.\n- Excellent communication and collaboration skills.\n- Ability to work independently and as part of a team.\n- Strong organizational skills and attention to detail.\n\nWhat can you expect from us\n- A young, challenging and friendly environment with a free dress code\n- A competitive salary, and individual career path planning.\n- 16 days annual leave (18 after 2 years of employment);\n- 3 sick days per year;\n- 4 creative days per year where you can explore new techniques and possibilities;\n- A yearly company trip;\n- 13th month salary;\n- Premium Health Insurance 24/7.\n- Cover Social Insurance as local law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1982, 958, 2, 'Senior/Lead Frontend Developer (ReactJS)', 'ABOUT ONE MOUNT\nOne Mount is Vietnam\'s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam\'s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nOne Mount Real Estate (OMRE) is a property technology company that provides a comprehensive platform to help customers experience a simple and seamless home buying and selling journey. OMRE is the first company in Vietnam capable of integrating the entire real estate transaction process on a single platform, from online to in-person. In addition, OMRE owns the first home valuation product in Vietnam. Don\'t miss the opportunity to become a member in PropTech field at One Mount Real Estate - A member company of One Mount ecosystem, a strategic partner of the leading bank in Vietnam Techcombank and the investor owns the most sought-after luxury apartments in the market, Masterise Home, Vinhomes.\n\nMAIN RESPONSIBILITIES:\n- Work with Product Managers and Designers to implement and design the next generation of products\n- Build, and write unit test for new features\n- Partner with backend teams to help shape API endpoints\n- Work with UX teams to deliver important functionality to our flagship application\n- Be a key member of a team of front end engineers\n- Maintain excellent coding standards and practices\n- Training for Fresher/Junior developer\n- Design, develop, review, implement, and manage ReactJS application code for the production\n- Understand the requirements of the business and utilize this knowledge to develop applications that are consistent with this\n- Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and tooling\n\nREQUIRED EXPERIENCE AND SKILLS:\n- +5 years of experience working in Software Development\n- Previous experience working as a ReactJS developer\n- Strong Javascript/Typescript skills (ES6) and ReactJS\n- Strong knowledge of development based on REST API.\n- Solid experience in all areas of web development (HTML5, CSS3, JSON) including accessibility, SEO and security concerns\n- Experience in SSR/SSG React-based frameworks like as NextJS. Good knowledge about NextJS is big plus\n- Experience in modern data-fetching library of reactjs: React Query, or SWR (nice to have)\n- Familiarity with utility-first CSS framework as Tailwind, and CSS module\n- Solid experience in modern front-end build pipelines and tools (e.g. Git, Webpack, Gulp, NPM)\n- Knowledge of testing frameworks likes Jest, React Testing Library, MSW, faker…\n- Excellent in problem-solving and analytical skills (must)\n- Experience with clean code, SOLID, and Design pattern (Prototype, container/presentational, observer, module, High order component, render props…)\n- Good experience in Agile (Scrum model) development environments (must)\n- Experience in monorepo and micro frontend is plus\n\nBENEFITS AND PERKS\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check\n- Laptop, screen and other needed facilities/accounts/tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'Reilly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n- Grow your career with opportunities across the dynamic ecosystem of Techcombank & Masterise Group.\n- Access special loan offers with competitive interest rates and flexible grace period options tailored to your financial needs.\n\nWorking Environment\n- Open & collaborative working space fosters both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms.\n- Personal lockers with QR code access.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1983, 808, 2, 'Junior QA Engineer - Hanoi', 'Job Description\n\n- Participate in the requirements discovery, testing of the software product.\n- Using Waterfall model and Agile model in projects.\n- Build and execute test cases.\n- Use testing techniques such as black box testing, functional testing and regression testing\n\nRequirements\n\n- Senior college or university student.\n- Able to work full-time.\n- Careful, good logical thinking, passionate about experimenting.\n- Have a sense of responsibility, persistence.\n- Able to work under pressure, hardworking, proactive, and responsible.\n- Good communication skills\n- Proficiency in English is required, including speaking, listening, reading, and writing.\n- Having certification in testing courses is an advantage.\n\nAny personal data you share with us during the application process will be processed strictly in compliance with applicable data protection laws and our Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1984, 1053, 2, 'Frontend Developer', 'We are seeking a skilled Frontend Developer to join our dynamic team. The ideal candidate will have a strong background in QML and C++, with hands-on experience in CMake and Docker. This role requires excellent communication skills and a proactive approach to problem-solving onsite.\n\nLocation: Sydney\n\nKey Responsibilities:\nDevelop and maintain user interfaces using QML and C++.\nConfigure and manage build systems using CMake.\nUtilize Docker for containerization and deployment processes.\nCollaborate with cross-functional teams to define and resolve integration issues.\nDiagnose and resolve technical issues efficiently.\nParticipate in code reviews and contribute to best practices.\n\nQualifications:\n5+ years of professional software development experience.\nProficient in QML and C++ programming.\nExperience with CMake build system.\nFamiliarity with Docker and containerization concepts.\nStrong problem-solving skills and attention to detail.\nExcellent verbal and written communication skills.\nAbility to work collaboratively in a team environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1985, 797, 2, 'Software Engineer (C++)', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.\n\nThe Position:\n\nWe are looking for hands-on C++ Developers to join our growing R&D and Product Engineering team. The candidate will work in a talented team to build OPSWAT\'s famous MetaDefender product as world\'s advanced next generation cyber security platforms.\n\nWhat You Will Be Doing:\n\n- Design, develop, implement and test OPSWAT MetaDefender product using C++ in Windows and/ or Linux environment.\n- Provide inputs for documentation of new or existing programs.\n- Partner with Scrum team members on delivering Sprint commitments.\n- Collaborate with Product Management on product requirements.\n- Participate in receiving and giving peer code reviews.\n\nWhat We Need from You:\n\n- Strong command of C++.\n- Windows/ Linux development experience.\n- Experience with Qt framework.\n- Experience with DBMS like SQLite, PostgreSQL, etc.\n- Excellent object-oriented design & programming skills in multi-threaded applications.\n- Good coding and debugging skills.\n- Excellent verbal and written communication skills.\n- Must be self-motivated and have a proven ability to work well in a fast-paced team environment.\n\nIt Would Be Nice If You Had:\n\n- Experience designing/interfacing with applications with REST API.\n- Experience with Agile / Scrum working environment.\n- Experience with Git, Bitbucket, Jira, Confluence, TeamCity.\n\nOPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws.\n\nRecruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1986, 750, 2, 'Analytics Engineer', 'Description\n• Participate in creating risk metrics, building dashboards by data visualization tools to monitor & identify abnormal user activities, app usage and fraudulent attempts (e.g., promotion abuse, card payment fraud, account take over, etc.);\n• Do exploratory data analysis to deep-dive into cases of suspicious abuse or fraud (e.g., app & device info, installation and registration behavior, payment transaction details, etc.) and abnormal activities to find out fraudster or abuser behaviors;\n• Work closely with Risk Strategy team, Data Science team, Product team on analyzing and tracking impact & effectiveness of risk rules/policies/products/solutions (coverage, false-positive, drop-off rate of challenge) and propose actionable insights & plans to enhance them;\n• Follow up the efficiency of your recommendations & adapt to different conditions;\n• Work closely with Risk Data Platform team to ensure accurate and high-quality data is collected and analyzed on a consistent basis;\n• Support to establish & develop post-mortem analysis and reporting for multiple aspects of Risk management including but not limited to promo campaigns, payment, wallet risks\nRequirement\n• Ability to think critically, analyze and solve problems with a strong attention to detail;\n• Being able to understand and represent business and user needs, distilling insights to set strong road map that meet short and long-term needs;\n• Good organizational and communication skills;\n• Experience in SQL and NoSQL query (e.g., MySQL, MongoDB); master in Python or Excel is a plus.\n• Experience in BI tools (e.g., Tableau) and big data computation (i.e., by using computation engine such as Spark) is a plus.\n• Ability to work well in a fast-paced environment;\n• Ability to manage multiple tasks and deadlines.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1987, 1054, 2, '(All Level) Embedded Linux Engineer', '1. INTRODUCTION\nFounded in 2010, Ban Vien Corporation has embarked on an inspiring journey, evolving into a trusted technology partner that has left an indelible mark in the realm of software development and embedded system development. Today, our influence extends both domestically and internationally, showcasing our commitment to driving digital transformation. At Ban Vien, we relentlessly pursue innovation across diverse industries like Edutech, Fintech, Retail, Automotive, Smart IoT, and Logistics. Our comprehensive services span Digital Consulting, R&D, Software Development, and Dedicated Development Centers. This global expansion includes valued clients and esteemed partners in the United States, Germany, Japan, Singapore, China, Hong Kong, Thailand, Malaysia, and Vietnam.\n\n2. JOB DESCRIPTION\nRZ/G1 VLP/ VLP64 Maintenance\nEvery 03 months, update CIP kernel (4.4.x, 4.4.x-RT, 5.10.x, 5.10.x-RT) to G1, G2 series.\nDisclose the package to GitHub public.\nUpdate HMI/QtHMI demo, sample apps, Application Development Package if impacted by CIP kernel update.\nSystem Integration, Technical review, Answer customer technical questions.\nUpstream/Backport bug-fixes.\n\nRZ/G2L BSP Development\nPort u-boot, CIP kernel (4.19.x, 4.19.x-RT, 5.10.x, 5.10.x-RT), Drivers (New, A2M, Zeus, V3U, etc. based), Basic libs(cip-core), ECC to G2L series and V2L.\nLow power mode.\nIntegrate MMP, GStreamers, Qt.\nDisclose the package to GitHub public.\nSystem Integration (Yocto 3.1), Technical review, Answer customer technical questions.\nUpstream/Backport bug-fixes.\n\nRZ/G VLP Automation/Tool\nIT for BSP drivers, ST, LTP, Khronos Conformance Test, Qt test, Web-Platform-Testing, Draw Elements Quality Program (dEQP), Performance test for HTML5.\nBenchmark.\nBuild Automation CI/CD/Test env (LAVA, R-Car Automation Test env based, etc.).\nDeeply analyze Web-Platform-Testing failed cases.\n\nRZ/A Linux and RZ/G RTOS platform support\nAnswer technical questions from RZ/A Linux customers.\nPorting drivers to RZ/A3UL on CA55.\nInvestigate, Design, Code, and Test some drivers of FreeRTOS env on CR7 of G2M.\nInvestigate, Design, Code, and Test some drivers of FreeRTOS env on Cortex M33 of G2L.\nOpenAMP verification on Multi-OS (Linux, FreeRTOS) environment.\n\n3. REQUIREMENTS\nAt least 1 year of experience at the same field.\nBachelor’s Degree or above in Electronic Engineering, Telecommunication, Computer Science, Computer Engineering, Automation, Information Technology or equivalent.\nStrong proficiency with C/C++.\nExperience with firmware/driver programming/debugging.\nProficiency with Linux OS, FreeRTOS, Linux kernel.\nFamiliar with BSP.\nFamiliar with Scripting language, Multimedia frameworks & Audio/Video codec, Graphics libraries and Image processing, HW manual & Schematics reading.\nCapable of reading and understanding MCU/SOC hardware manual.\nLeading skill, Teamwork skill, Investigation skill, Self-control.\nWeb-Platform (HTML5, Firefox, Gecko).\nFluent in both written and spoken English.\n\n4. COMPANY BENEFITS\n13th Salary + Performance Bonus.\nPass probation Bonus.\nPremium healthcare insurance benefits (PVI Insurance package) and family medical benefit (based on the level of experience).\nProvide the famous e-learning platform-Udemy, to encourage continuous learning to adapt to the T-shape model.\nFlexible working time: only 8 hours required as continual working-time at the office.\nAnnual leave up to 17 days: 12 days paid leave + 5 days’ sick leave.\nProfessional and Personal Development Training Programs.\n4 Stars standard company trip in summer and a big annual Year-End-Party.\nCoffee and snacks provided.\nHoliday celebrations and parties for team members and family.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1988, 1018, 2, 'Manual Test Engineer', 'Kyanon Digital is a Vietnam-based tech powerhouse. We deliver world-class solutions to clients across the globe. At Kyanon Digital, we offer end-to-end solutions that encompass every facet of the digital landscape. With the slogan: “Digital Impact that Matters”, this has guided our team of over 300 employees for over 12 years, creating many positive changes for large clients in various industries.\n\nAs a Quality Control Engineer (Manual), you will play a crucial role in ensuring software quality by executing comprehensive manual testing processes, identifying defects, and verifying that products meet established standards. This position collaborates with development teams to enhance product reliability, contributing to the company’s goal of delivering user-friendly and dependable software solutions.\n\nHow You Can Contribute\nDesign and execute comprehensive test plans and test cases for software applications;\nConduct functional, regression, and performance testing to identify defects and ensure high-quality deliverables;\nCollaborate with developers and BA to understand system requirements and clarify specifications;\nAnalyze testing results and report on the quality metrics of software releases;\nIdentify, document, and track defects in defect management systems;\nAssist in the development of quality standards and best practices for software development and testing.\n\nWhat You Need To Maximize Your Contribution\nMinimum 3 years of experience in a Quality Assurance or Quality Control role;\nStrong technical skills: Web/Mobile Testing, UI Testing, API testing;\nHands-on experience with System Testing, Integration Testing, Acceptance Testing;\nStrong knowledge of QC methodologies, tools, and processes;\nExcellent analytical and problem-solving skills;\nStrong communication and collaboration skills;\nAbility to interact and communicate with clients;\nUnderstanding of Agile and experience working in Agile-driven environments;\nGood mindset of analyzing requirements & preventing high issues before releasing product;\nKnowledge or experience in Performance testing, Security testing & Automation Testing are huge plus;\nAbility to communicate in English with good written skills.\n\nWhy you’ll love working here\nCompetitive remuneration package and salary review twice a year\nBecome a world-class engineer, able to directly work opportunities with big worldwide retailers\nGain experience by working with large-scale projects \nLatest technologies\nFree training courses, webinars, seminars packages\nFlexible working time (Monday – Friday)\nFlexible annual leave schedule\nReferral bonus program\nNo suit, no tie, no “office”. The office is your second home \n12 days annual leave (1 paid day of annual leave for each month)\nOther paid leave such as holidays; marriage; birth; marriage of children; funeral following Labor law and company regulations\n13th-month salary pro-rata (based on the business situation)\nHealth check annually\nSocial/health/unemployment insurance.\n\nPlease send your CV to thu.ngl@kyanon.digital\n\nWe appreciate your interest in career opportunities at Kyanon Digital. For those candidates whose skills don’t perfectly match the current role, we’ll keep your profiles in our talent pool and may contact you for future opportunities. Shortlisted candidates will hear from us within 5 to 10 business days.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1989, 1055, 2, 'Senior C# Developer (WinForms, .NET framework)', 'MÔ TẢ CÔNG VIỆC\nLập trình phần mềm vận hành các thiết bị trong nhà máy sản xuất chip bán dẫn như cánh tay robot, chamber… Giao tiếp với PLC, thiết bị trường để thu thập dữ liệu từ cảm biến…\nTham gia phân tích yêu cầu, triển khai, hướng dẫn nhóm phát triển. Báo cáo công việc với cấp trên.\nThời gian làm việc: 08:30 – 17:30 (thứ 2 – thứ 6).\n\nYÊU CẦU KỸ THUẬT:\nCó từ 5 năm kinh nghiệm trở lên trong Software Developer.\nCó từ 3 năm kinh nghiệm trở lên trong phát triển ứng dụng C# (WinForms, .NET framework)\nCó từ 1 năm kinh nghiệm quản lý nhóm từ 2 thành viên trở lên.\nCó kiến thức vững chắc về C# và OOP. Có kinh nghiệm hỗ trợ kỹ thuật, review source code.\nCó kinh nghiệm về lập trình multi-thread và multi-process.\nCó kinh nghiệm trong lập trình giao tiếp bằng TCP/IP socket, truyền thông công nghiệp như RS-232 …\nSử dụng thành thạo Visual Studio 2015/2017/2019.\nCó kỹ năng làm việc độc lập và làm việc nhóm tốt.\nCó kỹ năng phân tích, tư duy logic và giải quyết vấn đề tốt.\n\nYÊU CẦU BỔ SUNG (LỢI THẾ):\nĐiểm cộng nếu thành thạo C/C++, WPF.\nCó kinh nghiệm lập trình giao tiếp với PLC (Mitsubishi, Omron…)\nCó kinh nghiệm về Unit Test và System Test.\nCó kinh nghiệm về tối ưu hóa source-code, re-factoring source code.\nCó kinh nghiệm làm việc cho khách hàng/thị trường/doanh nghiệp\nCó kinh nghiệm sử dụng các công cụ: Gitlab, Redmine\nTiếng Anh: đọc và hiểu các tài liệu kỹ thuật\n\nMỨC LƯƠNG\nLương thỏa thuận theo năng lực:\nSenior: Từ 26,000,000 VND (GROSS)\nBonus: thưởng lương tháng 13 (từ 1 tháng lương trở lên)\nXét tăng lương hàng năm.\n\nQUYỀN LỢI SỨC KHỎE\nĐược hưởng đầy đủ chế độ, phúc lợi theo Luật Lao Động\nĐược hưởng gói Bảo Hiểm sức khỏe Bảo Việt với mức quyền lợi cao. (sau 6 tháng kể từ ngày ký HĐLĐ chính thức)\nKhám sức khỏe định kỳ tại bệnh viện uy tín.\n\nCHẾ ĐỘ ĐÃI NGỘ KHÁC\nTham gia tour du lịch cao cấp hàng năm.\nPhụ cấp ăn trưa, phụ cấp xăng và gửi xe miễn phí.\nĐược tổ chức sinh nhật, các bữa tiệc vào dịp lễ đặc biệt (Giáng sinh, Tất niên, Trung thu, ….)\nQuà tết, Trung thu, ….\n\nCƠ HỘI PHÁT TRIỂN\nĐược làm việc, trao đổi với các kỹ sư giỏi ở Nhật Bản.\nCơ hội thăng tiến và Onsite ở Nhật Bản.\n\nMÔI TRƯỜNG LÀM VIỆC\nTrang bị đầy đủ thiết bị phục vụ cho công việc.\nLuôn được đồng nghiệp hỗ trợ, tư vấn, đào tạo trong công việc để phát triển hơn.\nMôi trường năng động, vui vẻ gắn kết nhau.\nCoffee, bánh kẹo, thiết bị tiện nghi luôn sẵn sàng cho mọi nhu cầu.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1990, 674, 2, 'Unity Developer', 'Mô tả công việc\nThree Eyes Studio - Game Studio mới mở được hậu thuẫn mạnh mẽ bởi Appota Group. Chúng mình chiêu mộ những Key Member sáng giá đầu tiên về với team vô cùng nhiệt huyết.\n\nMÔ TẢ CÔNG VIỆC:\nLập Trình Viên Game Unity Sẽ Chịu Trách Nhiệm Phát Triển Các Game 2D Sử Dụng Corgi Engine, Tích Hợp Công Cụ AI Để Tối Ưu Hóa Quy Trình Lập Trình, Và Đảm Bảo Chất Lượng Sản Phẩm Đáp Ứng Yêu Cầu Thị Trường. Nhiệm Vụ Cụ Thể\nPhát triển gameplay:\n- Lập trình các cơ chế gameplay như chuyển động nhân vật, hệ thống va chạm, vật lý 2D, và các tính năng đặc trưng (nhảy, tấn công, tương tác môi trường) sử dụng Corgi Engine.\n- Tận dụng các thành phần có sẵn trong Corgi Engine (Character Controller, Level Manager, Animator) để xây dựng hệ thống game hiệu quả.\n- Tích hợp các tính năng AI để nâng cao trải nghiệm người chơi.\nSử dụng công cụ AI:\n- Sử dụng các công cụ AI hỗ trợ lập trình như GitHub Copilot, Tabnine, ChatGPT để tăng tốc độ viết code, tự động hóa các tác vụ lặp lại, và đề xuất giải pháp tối ưu.\n- Áp dụng AI để debug nhanh, phân tích lỗi, hoặc sinh mã nguồn cơ bản.\n- Nghiên cứu và tích hợp các công cụ AI vào pipeline phát triển.\nTối ưu hóa hiệu suất:\n- Đảm bảo game chạy mượt mà trên các nền tảng mục tiêu (mobile, PC), đặc biệt là thiết bị cấu hình thấp.\n- Tối ưu hóa tài nguyên như sprite, texture, và animation, kết hợp với công cụ AI để phân tích hiệu suất và đề xuất cải tiến.\nHợp tác nhóm:\n- Làm việc với Game Designer, Artist, và Tester để triển khai các tính năng theo Game Design Document (GDD).\n- Phối hợp với đội ngũ để tích hợp âm thanh, UI, và hiệu ứng hình ảnh.\n- Báo cáo tiến độ dự án bằng tiếng Anh (nếu làm việc với đối tác quốc tế).\nBảo trì và nâng cấp:\n- Sửa lỗi (bug fixing) và cải tiến tính năng dựa trên phản hồi từ QA hoặc người chơi.\n- Cập nhật game để tương thích với phiên bản Unity mới hoặc các nền tảng phát hành (Google Play, App Store, Steam).\nĐóng góp ý tưởng:\n- Đề xuất cải tiến gameplay hoặc tính năng mới, sử dụng công cụ AI để phân tích xu hướng thị trường game hoặc sở thích người chơi.\n- Tham gia nghiên cứu các plugin Unity hoặc công nghệ mới để nâng cao chất lượng dự án.\n\nYêu cầu công việc\nKỹ năng chuyên môn:\n- Thành thạo Unity Engine và lập trình C#.\n- Kinh nghiệm thực tế với Corgi Engine, bao gồm thiết lập nhân vật, level, và các hệ thống gameplay 2D.\n- Biết sử dụng công cụ AI hỗ trợ lập trình (GitHub Copilot, Tabnine, hoặc các AI coding tool) để tăng năng suất và tối ưu hóa mã nguồn.\n- Hiểu các khái niệm lập trình hướng đối tượng (OOP), design pattern, và thuật toán cơ bản.\n- Kỹ năng tối ưu hóa game 2D (performance, memory management).\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh (Unity, Corgi Engine documentation).\nKinh nghiệm:\n- Tối thiểu 2 năm kinh nghiệm phát triển game với Unity, đã sử dụng Corgi Engine hoặc các framework tương tự.\n- Đã tham gia ít nhất 1-2 dự án game hoàn chỉnh, có sản phẩm phát hành trên store (Google Play, App Store, Steam) là lợi thế.\n- Kinh nghiệm sử dụng công cụ AI để hỗ trợ lập trình, debug, hoặc phân tích dự án là một điểm cộng lớn.\nKỹ năng mềm:\n- Tư duy logic, khả năng giải quyết vấn đề nhanh chóng.\n- Chủ động, chịu được áp lực deadline, và có trách nhiệm với công việc.\n- Kỹ năng làm việc nhóm tốt, giao tiếp hiệu quả với các bộ phận liên quan.\n- Đam mê lập trình game, sẵn sàng học hỏi công nghệ mới, đặc biệt là AI.\nƯu tiên:\n- Có kinh nghiệm với các plugin Unity như DOTween, TextMeshPro, hoặc công cụ animation (Spine, Animator).\n- Hiểu biết về shader, particle system, hoặc công cụ thiết kế (Photoshop, Aseprite).\n- Đã làm việc với các công ty game tại Việt Nam hoặc các studio quốc tế.\n- Có kinh nghiệm tích hợp AI vào game (AI cho NPC, pathfinding, hoặc phân tích dữ liệu người chơi).\n\nTại sao bạn yêu thích làm việc tại đây\nPhúc lợi tài chính minh bạch và toàn diện\n- Lương + Thưởng profit hấp dẫn\n- Chính sách xét điều chỉnh tăng lương 6 tháng/lần (Đánh giá theo hiệu xuất, kết quả công việc và năng lực)\n- Ghi nhận sự đóng góp thông qua các khoản thưởng phong phú, hấp dẫn góp phần gia tăng thu nhập của nhân viên: Thưởng các ngày lễ 30/4-01/05, 02/09, Tết dương lịch, thưởng dự án, thưởng KPI, hiệu suất công việc hàng tháng, thưởng quý và lương tháng 13…\n- Được hưởng các mức Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n- Gói chăm sóc sức khỏe định kỳ hằng năm tại các Bệnh viện Đại học Y Hà Nội và Saigon Healthcare.\nChú trọng phát triển năng lực mỗi cá nhân\n- Chính sách hỗ trợ khuyến khích học tập, khen thưởng dành cho nhân viên đạt chứng chỉ đào tạo.\n- Được đào tạo và phát triển theo khung năng lực và lộ trình nghề nghiệp của từng vị trí thông qua các khóa đào tạo miễn phí trên hệ thống đào tạo trực tuyến E-learning Appota, các khoá học hàng đầu của Coursera, Udemy.\n- Được tham gia các Workshop, Master talk, CEO talk chia sẻ kiến thức và kinh nghiệm từ các chuyên gia trong và ngoài Công ty.\n- Có lộ trình thăng tiến rõ ràng. Chính sách luân chuyển công việc linh hoạt và cởi mở nhằm thúc đẩy nhân viên khám phá sức mạnh tiềm năng của bản thân và thử thách với những cơ hội mới.\nVăn hóa làm việc độc đáo\n- Tại Appota, mỗi nhân viên sẽ được làm việc mình thích, thích việc mình làm với văn hóa "No Boss Just Leader" cùng 7 giá trị cốt lõi IAPPOTA.\n- Mỗi cá nhân được trao quyền chủ động trong mọi việc, phát huy các thế mạnh, phá bỏ khuôn mẫu và sáng tạo theo phong cách riêng.\n- Được dẫn dắt, định hướng bởi định hướng bởi đội ngũ BOD có tầm với kim chỉ nam tập trung vào phát triển giá trị con người và tinh thần startup mạnh mẽ.\n- Môi trường trẻ trung, năng động và sáng tạo, nơi mọi ý tưởng táo bạo được đón nhận.\nTrải nghiệm sự chăm sóc tinh thần tận tâm và chu đáo\n- Được chăm sóc tỉ mỉ từ những bữa ăn sáng, ăn chiều miễn phí với chi phí 2.000.000/người/tháng và tận hưởng không gian cafe hiện đại dành riêng cho nhân viên.\n- Được trải nghiệm các hoạt động gắn kết đa dạng: Các hoạt động team building, chương trình Friday Frenzy, Đại tiệc sinh nhật công ty kết hợp du lịch hàng năm lên tới 10.000.000/người/năm, hội Chợ Tết độc lạ và các hoạt động thể thao thường niên khác, …\n- Được thỏa sức tham gia các câu lạc bộ đa sắc màu: CLB Yoga, Bóng đá, Game Esports, Cầu lông, Zumba…\nThời gian làm việc\n- Từ 8h30 - 18h00 từ thứ 2 đến thứ 6\n- Từ 8h30 - 16h00 thứ 7 (Mỗi tháng đi làm 2 thứ 7)\nĐịa Điểm Làm Việc\n- Tòa LE Building, Số 11, Ngõ 71, Phố Láng Hạ, Phường Thành Công, Quận Ba Đình, Thành phố Hà Nội, Việt Nam.\nKhám Phá Văn Hoá Appota Tại\n- Website: Appota.com\n- Fanpage: https://www.facebook.com/appotacareers\n- Tiktok: https://www.tiktok.com/@appotagroup\n- Youtube: https://www.youtube.com/@Appota', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1991, 992, 2, 'Senior C# Developer', 'A Bit About Us\n\nWe\'re a world-leading smart mobility SaaS tech company with almost 2,000,000 subscribers across 23 countries. Our teams are collaborative, vibrant, and fast-growing, and all team members are empowered with the freedom to influence our products and technology.\n\nAre you curious, innovative and passionate?\n\nDo you take ownership, embrace challenges, and love problem-solving?\n\nWe\'re looking for a Software Developer (C#) who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.\n\nYou want to\n\n- Design and develop scalable desktop solutions and Windows services for global use\n- Write high-quality code that adheres to coding standards and is performant\n- Create and modify functions, stored procedures, and triggers in PostgreSQL\n- Experience in Javascript OR Docker is a MUST.\n- Be independent and take full responsibility for the development of modules/features\n- Work with UX/UI designers to implement user-friendly solutions\n- Introduce new technologies into the team based on fit and suitability to deliver a solution\n- Be able to deep dive into the technical aspects needed for application optimization\n\nYou have\n\n- Bachelor\'s Computer Science degree or equivalent industry experience\n- Extensive experience in programming with C# (.Net Framework 4 and above)\n- Strong experience in working with Relational Databases, experience in PostgreSQL a plus\n- Experience in consuming and feeding Web APIs (SOAP / REST)\n- Strong understanding of SQL\n- Strong knowledge and understanding of SOLID principles and design patterns\n- Experience using source control technologies such as Git and SVN.\n\nExperience In/with Any Of The Following Is a Plus\n\n- Mapping technologies such as Google Maps/OpenStreetMap Agile development methodologies\n- Performance/analytics tools for desktop applications and services\n- Continuous integration software such as TeamCity Unit testing, test-driven development, static code analysis', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Área metropolitana de Ciudad Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1992, 264, 2, 'Data Engineer', 'Our company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n\nDesign, build, and manage scalable and efficient ETL/ELT pipelines.\n\nDevelop and maintain data architectures (e.g., databases, data lakes, data warehouses).\n\nWork with structured and unstructured data from multiple sources.\n\nOptimize data delivery and ensure data quality, security, and governance.\n\nCollaborate with data scientists, analysts, and other stakeholders to understand data needs.\n\nWhat you’ll bring\n\nBachelor’s degree in Computer Science, Engineering, or a related field.\n\nStrong experience with SQL and relational databases (e.g., PostgreSQL, MySQL).\n\nProficiency in data processing frameworks and languages (e.g., Python, Spark, Scala).\n\nExperience with cloud platforms (e.g., AWS, GCP, Azure) and services (e.g., S3, Redshift, BigQuery).\n\nKnowledge of data warehousing concepts and tools (e.g., Snowflake, Databricks, DBT).\n\nFamiliarity with data orchestration tools (e.g., Airflow, Luigi).\n\nFluent in English communication\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion\n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow we look after you\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 Củ Chi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1993, 1001, 2, 'Fullstack TypeScript Developer', 'Working location: Ho Chi Minh City\nSalary range: USD 2,500 – 5,000 gross \n\nRESPONSIBILITIES\n- Join a financially stable, fast-growing company trusted by the world\'s leading legal teams.\n- Collaborate with a team of passionate, driven individuals committed to success.\n- Have a direct influence on shaping our products, processes, and the future of LegalTech.\n- Tackle large-scale, complex projects while enjoying a flexible work environment.\n- Enjoy competitive benefits and perks designed to help you thrive.\n- Advance your career with a clear framework and be part of a team that truly cares about your growth.\n\nREQUIREMENTS\n- Solid & practical grasp of software engineering principles and best practices.\n- 6+ years of experience.\n- Proficiency in JavaScript/Typescript, Node.js, React.js, and any associated frameworks.\n- Exceptional problem-solving abilities with a practical approach.\n- Excellent communication and interpersonal skills.\n- Bonus: Experience with AI or machine learning development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1994, 721, 2, 'Application Developer', 'Keyloop bridges the gap between dealers, manufacturers, technology suppliers and car buyers. We empower car dealers and manufacturers to fully embrace digital transformation. How? By creating innovative technology that makes selling cars better for our customers, and buying and owning cars better for theirs. We use cutting-edge technology to link our clients’ systems, departments and sites. We provide an open technology platform that’s shaping the industry for the future. We use data to help clients become more efficient, increase profitability and give more customers an amazing experience. Want to be part of it?\n\nRole Summary\n\nAs an Application Developer 3 at Keyloop, you will design, develop, and maintain scalable integrations using Boomi\'s AtomSphere platform. You will work closely with business analysts, solution architects, and cross-functional teams to ensure data flows seamlessly and reliably across systems and processes.\n\nKey Responsibilities\n- Collaborate with Business Analysts and Solution Architects to define and refine integration requirements and technical specifications.\n- Design and implement end-to-end integration workflows using Boomi, focusing on reliability, scalability, and performance.\n- Monitor and maintain existing Boomi processes, troubleshooting and resolving issues as they arise.\n- Develop reusable components and templates for consistent integration practices.\n- Create comprehensive documentation for integration solutions, including data mappings, error handling, and process flows.\n- Participate in code reviews and provide constructive feedback on design and development approaches.\n- Support UAT, deployments, and post-release monitoring for integration-related features.\n- Mentor junior developers in integration principles and Boomi best practices.\n- Coordinate cross-functional dependencies for data exchange and interface alignment.\n- Recommend and implement process improvements and contribute to team standards.\n\nEssential Skills & Qualifications\n- 3+ years of hands-on experience with Dell Boomi AtomSphere, including process design, connectors, mapping, and error handling.\n- Strong understanding of integration patterns, data transformation, and API design (REST/SOAP).\n- Experience working with ERP, CRM, or DMS systems and integrating them via Boomi.\n- Familiarity with data formats such as XML, JSON, and flat files.\n- Strong debugging and problem-solving skills in an integration context.\n- Experience with Boomi deployment management, version control (Git), and CI/CD practices.\n- Strong written and verbal communication skills, with the ability to collaborate effectively across global teams.\n- Comfortable working in an Agile/Scrum environment.\n\nPreferred Experience\n- Familiarity with FFLib (FinancialForce Library) or equivalent enterprise design patterns in integration-heavy Salesforce environments.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1995, 1056, 2, 'Senior Java Software Engineer', 'Company Description\nWe suggest you enter details here\n\nRole Description\nThis is a full-time on-site role located in Hanoi for a Senior Java Software Engineer at VETC - Vietnam Electronic Toll Collection. The role involves tasks such as software development, working with programming using the Spring Framework, and Java development.\n\nQualifications\n• Mastery of Software Development, Programming, and Java skills\n• Experience with DDD and the Spring Framework\n• Strong problem-solving and analytical skills\n• Ability to work in a team and independently\n• Bachelor\'s degree in Computer Science or related field\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1996, 828, 2, 'Software Engineer(C/C++, Golang)', 'Welfare\n\n- Attractive remuneration with competitive income and 6 months/year salaries/ efficient production and business.\n- A welfare package of $2000 per year including Tet bonus, holiday bonus and resort.\n- Being a colleague of a team of leading technology experts in fields such as: DPI, BigData, Machine Learning, AI, Data Mining, Speech Recognition, Virtual Assistant…\n- Improve capacity through intensive training courses, study support and professional certification exams.\n- Consider raising the minimum salary once a year. Access to attractive promotion opportunities.\n- 12 days holiday, 12 vacation days and 3 annual vacation days.\n- Always enjoy to the fullest full benefits of social insurance, health insurance, unemployment insurance and statutory leave and sick leave after signing the labor contract.\n- Join the comprehensive health care MIC insurance package.\n- Relax, spark creativity with Happy Time every day, modern workspace.\n- Enjoy a delicious lunch, selected by nutritionists.\n- Working in key projects of the Group with large system scale.\n- Experience the multiculturalism when working with Viettel\'s personnel in more than 10 countries.\n\nJob Descriptions\n\nParticipate in building BigData processing systems for the entire telecommunications network.\n\nParticipate in building large systems that can handle millions of requests per second, using technologies , the latest architecture.\n\nParticipate in building control protocols for network devices operating on the network.\n\nBuilding services for connection between networks and system components.\n\nJob requirements\n\nGeneral Requirements\n\nGraduated from a regular university with good grade or higher, majoring in accordance with the position.\n\nHaving experience of 02 years or more (accepting the whole process of experience work while undergrad).\n\nTOEIC 550/990.\n\nRequired Requirements\n\nFluency in one of the C/C++/Golang languages.\n\nSkill in SQL is an advantage.\n\nKafka, Hadoop is a plus. So.\n\nAbility to optimize code, find errors and handle errors.\n\nKnowledge of data structures and algorithms.\n\nYes knowledge of software architectures.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1997, 1057, 2, 'Call Center Developer', 'Job description\n- Các dự án cần sự xây dựng backend hỗ trợ (kết nối đối tác) hoặc các dự án đã có sẵn nhân sự front-end; đòi hỏi nhân sự chuyên trách phát triển back-endPhát triển các nội dung xử lý phía back-end theo yêu cầu dự án\n- Phát triển API kết nối với front-end hay đối tác\n- Đảm bảo các tiêu chuẩn bảo mật và mã hóa\n- Tuân thủ quy trình/quy định của Athena\n\nYour skills and experience\n- Có ít nhất 1 năm kinh nghiệm trong lĩnh vực phát triển sản phẩm ở vị trí backend\n- Đã từng tham gia ít nhất 2-3 dự án trong đó đảm nhiệm việc phát triển back-end; hoặc 2 dự án lớn (có 5 người tham gia trở lên.\n- Thành thạo với ngôn ngữ lập trình C (bắt buộc), Lua Script( bắt buộc), Nodejs\n- Đã làm việc và sử dụng mã nguồn các tổng đài freeswitch, kamalio\n- Hiểu và làm việc với giao thức SIP, SIPS\n- Có kinh nghiệm về PL/SQL \n- Có kinh nghiệm phát triển API Web Services\n- Thành thạo, xử lý tốt Multithread (Xử lý tối thiểu 1000-2000 giao dịch cùng lúc), Multi-processing, cơ chế Hash table, cơ chế xử lý file.\n- Có kinh nghiệm về các tiêu chuẩn bảo mật\n- Thành thạo việc thiết kế CSDL trên DB Mongodb, MYSQL …\n- Có kinh nghiệm làm việc với các hệ điều hành Enterprise Linux, HP-UX\n- Có kinh nghiệm về GIT, Jira;\n- Có kinh nghiệm với các quy tắc thiết kế OOP;\n- Có hiểu biết về Docker và Microservices, DevOps\n- Có hiểu biết vẽ MQ, cache...\n- Có hiểu biết về mockup API\n- Thành thạo việc xây dựng các tài liệu đặc tả kỹ thuật (Technical Specification Document), bao gồm: ERD, Database schema, swagger APIs,…\n- Có khả năng đọc hiểu tài liệu tiếng Anh', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1998, 903, 2, 'Frontend Developer', 'Position : FRONTEND DEVELOPER \nQuantity : 01\nType : Full-time\nLocation : 5th Floor, TTC Building, No. 19 Duy Tan St., Dich Vong Hau Ward, Cau Giay Dist., Hanoi Capital, Vietnam.\n\nABOUT US\n• Astek is a global player in engineering and technology consulting, founded in France in 1988. Today, we are +7500 engineers across over 22 countries in the world.\n• With expertise in many industrial and tertiary sectors, we support our international clients in the intelligent deployment of their products and services, and in the implementation of their digital transformation.\n• Astek Vietnam is established in 2022 to increase group’s capability to support our clients’ operation around the globe, leveraging Vietnam talented engineers.\n• More information about our group: https://astekgroup.fr/\n\nJOB DESCRIPTION & REQUIREMENTS\nKey Responsibilities:\n• Coordinate with system managers and product owners to propose practical solutions for service requests\n• Handle service requests, minor change requests, and L1 support for business users\n• Ensure compliance with cybersecurity regulations, including Vulnerability Assessment and Penetration Testing (VAPT) and Privileged Access Management (PAM) on a regularly basis.\n• Develop responsive, high-performance web and mobile applications using React JS, React Native, and Next.JS\n• Proficient with state management solutions with Redux and integration with GraphQL APIs.\n• Collaborate with designers or based on Product Owner feedback implement UI/UX designs with CSS and modern styling practices.\n• Build and maintain unit and integration tests using Jest and React Testing Library.\n• Implement secure authentication/authorization flows with AWS Cognito and JWT\n• Develop event-driven architectures and back task processing with SQS and Event Bridge.\n• Ensure security best practices across frontend and backend systems.\n\nRequirements Skills and Knowledge:\n• Ability to work effectively with cross-functional teams and manage multiple projects simultaneously.\n• Ability to create and maintain detailed documentation, ensuring clarity and consistency across all projects.\n• Proficient with Javascript, Typescript \n• Proficient with AWS services including AWS S3, Cloudfront, Cognito\n• Number year exp: Min 4 experience years for FE Developer\n• Proficiency in English is required.\n• Knowledge of standardized IT takeover/handover processes\n• Strong problem-solving skills and the ability to propose practical solutions.\n\nBonus skills/qualities:\n• Familiar with mobile development with Flutter and Dart\n• Knowledge of cybersecurity best practices and experience with end-to-end VAPT process.\n\nBENEFITS\n• Attractive salary: Nego. Performance based award.\n• Young and dynamic working environment.\n• Continuous development of hard and soft skills through work and professional training.\n• Opportunity to approach newest technology trends.\n• Salary reviews 1 times/year or on excellent performance\n• Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\n\nCONTACT\nASTEK VIETNAM\n• Contact Person: Mrs. Dzung Nguyen\n• Phone Number: 0969988029\n• Email: Thi-Kim-Dung.NGUYEN@astek.net\n• Website:https://astekgroup.fr/?lang=en', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(1999, 751, 2, 'Senior Developer (Java)', 'Company Description\n\nTechnology is our how. And people are our why. For over two decades, we have been harnessing technology to drive meaningful change.\n\nBy combining world-class engineering, industry expertise and a people-centric mindset, we consult and partner with leading brands from various industries to create dynamic platforms and intelligent digital experiences that drive innovation and transform businesses.\n\nFrom prototype to real-world impact - be part of a global shift by doing work that matters.\n\nJob Description\n\nDevelopment is the largest discipline at Endava. Our developers design, build, and release software products in multiple programming languages, frameworks, and libraries. Always collaborating with cross-functional project teams, our developers are adaptable problem-solvers with a client-oriented mindset.\n\nAs a Senior Developer (Java) at Endava, you are responsible for implementing and delivering high-quality software products using Agile Scrum methodology. As a part of a global project, you can contribute your technical expertise and experience in order to the project succeed.\n\nResponsibilities:\n\n- Designs, estimates, and implements technical solutions for medium/high complexity applications.\n- Participates actively in all phases of the application development lifecycle.\n- Collaborates with various project stakeholders to provide support for clarifying requirements, processes, architecture, and priorities.\n- Recommends and promotes IT industry standards, tools, and practices (DevOps, etc.) to achieve well-engineered software products.\n- Proposes improvements and escalates risks/issues related to development activities.\n- Participates in the review of the work done by development team members.\n- Learns and applies new technologies, practices, and tools as appropriate to the project.\n- Participates in internal and external tech communities, events, etc.\n- Shares experience and knowledge gained from projects.\n\nQualifications\n\n- 6+ years of experience in Java Back-end development.\n- Strong understanding of different common programming paradigms (OOP, Functional, etc.).\n- Strong familiarity with design/architectural patterns and clean code principles (e.g., SOLID, GoF, MVVM).\n- Proficient in relevant programming languages, frameworks, and tools such as Java, IntelliJ IDEA, Spring, Hibernate, Maven, Gradle. Nice to have:\nKotlin.\n- Practical experience in platform-specific database systems and SQL.\n- Good understanding of version control systems like Git or similar.\n- Solid experience with testing and mocking frameworks.\n- Familiar with common communication protocols and standards such as HTTP, REST, JSON, TCP/IP, and others.\n- Experience with Agile methodologies (e.g., SCRUM, KANBAN).\n- Knowledge of CI/CD tools and practices.\n- Good problem-solving skills and analytical thinking.\n- Excellent communication and teamwork abilities.\n- Upper English proficiency.\n\nAdditional Information\n\nDiscover some of the global benefits that empower our people to become the best version of themselves:\n\n- Finance:\nCompetitive salary package, share plan, company performance bonuses, value-based recognition awards, referral bonus; \n- Career Development:\nCareer coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership;\n- Learning Opportunities:\nComplex projects, rotations, internal tech communities, training, certifications, coaching, online learning platforms subscriptions, pass-it-on sessions, workshops, conferences;\n- Work-Life Balance:\nHybrid work and flexible working hours, employee assistance programme;\n- Health:\nGlobal internal wellbeing programme, access to wellbeing apps;\n- Community:\nGlobal internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations.\n- Annual leave encashment;\n- 13th month salary;\n- Premium annual health check & Extra health & accident insurance;\n- Welcome kit and gift-giving frequency;\n- Attractive benefits of Trade Union;\n- Exciting English programme.\n\nAt Endava, we’re committed to creating an open, inclusive, and respectful environment where everyone feels safe, valued, and empowered to be their best. We welcome applications from people of all backgrounds, experiences, and perspectives—because we know that inclusive teams help us deliver smarter, more innovative solutions for our customers. Hiring decisions are based on merit, skills, qualifications, and potential. If you need adjustments or support during the recruitment process, please let us know.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2000, 702, 2, 'Senior Computer Vision Engineer (LLM)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nWe are looking for an experienced and enthusiastic Senior Computer Vision Engineer to join our pioneering team. The ideal candidate will have a deep understanding of computer vision technologies and large language models (LLMs), paired with a strong background in coding with Python and PyTorch/Tensorflow. This position requires someone with both the academic foundation and practical experience to drive our advanced computer vision projects.\n\nResponsibilities\n\n- Develop and deploy computer vision models that enhance our product offerings.\n- Utilize Python and PyTorch to design and implement scalable, efficient code.\n- Collaborate with cross-functional teams to integrate computer vision solutions into existing systems.\n- Stay ahead of industry trends and bring novel insights to guide our technological strategies.\n- Participate in code reviews, providing constructive feedback to peers.\n- Lead research and development projects, facilitating the translation of these projects into practical applications.\n- Mentor junior engineers and contribute to a collaborative team culture.\n\nQualifications\n\n- A minimum of a Master’s degree in Computer Science, Electrical Engineering, or a related field.\n- Extensive experience in computer vision and LLMs.\n- Proven proficiency in coding with Python and PyTorch.\n- Experience with KYC pipeline, document analysis, or OCR processes is a significant advantage.\n- A publication record in top-tier conferences or journals in computer vision is a plus.\n- Strong analytical and problem-solving skills.\n- Ability to work independently and as part of a team.\n- Excellent verbal and written communication skills. The capacity to manage multiple projects and adapt in a fast-paced environment.\n\nWorking at Binance\n\n- Be a part of the world’s leading blockchain ecosystem that continues to grow and offers excellent career development opportunities\n- Work alongside diverse, world-class talent in an environment where learning and growth opportunities are endless\n- Tackle fast-paced, challenging and unique projects\n- Work in a truly global organization, with international teams and a flat organizational structure\n- Competitive salary and benefits\n- Flexible working hours, remote-first, and casual work attire\n\nLearn more about how Binancians embody the organization’s core values, creating a unified culture that enables collaboration, excellence, and growth.\n\nApply today to be a part of the Web3 revolution!\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2001, 899, 2, 'Nodejs Developer', 'You will work as a NodeJS developer to build products for foreigner customers.\nUnderstand the design documents and implement them properly.\nIntegration of user-facing elements developed by front-end developers with server side logic\nWriting reusable, testable, and efficient code\nDesign and implementation of low-latency, high-availability, and performant applications\nImplementation of security and data protection\nIntegration of data storage solutions\nWrite unit test\nWork directly with client to clarify requirement\n\nCompensation & Benefits\n\nSaturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\nWork performance review 2 times/ year (in April and October);\nPerformance bonus, 13th- month salary, public holidays bonus (2/9, 30/4, 1/5, 1/1); bonus for Excellent Employee and Excellent Team;\nSocial insurance, health insurance, unemployment insurance and Bao Viet care insurance;\n01 hour paid leave per day for women having children under 12 months\nMinimum 14 paid leaves per annum for all employees after probation;\nNice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks;\nYearly company trip and year-end party, quarterly team building and weekly eating together; English - Japanese Club, Sports Clubs;\nMen’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company;\nFlat, open and sharing culture with friendly management team; outsourcing company with product mindset;\nTraining courses and working opportunities with technical gurus who built and operated world-class applications with millions of users. This might be a good chance for graduated students to learn cutting-edge technologies and how to build scalable system from scratch;\n\nRequirements\n\nAt least 2 years of experience with NodeJS developer\nBachelor degree or up majoring in software engineering, computer science.\nExtensive knowledge about OOP and design patterns.\nFamiliar with NodeJS and/or related frameworks such as Hapi, Express.\nHaving Typescript is a plus\nGood at English (speaking skill)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2002, 1058, 2, 'Senior Software Engineer', 'At Amplify, we’re building the future of the creator economy. We’re creating a tool to revolutionise how creators and brands connect and collaborate. Our mission is to simplify campaign management, provide actionable insights, and unlock new opportunities for creators and brands alike.\n\nWe’re looking for a talented Engineer to join our team and play a key role in developing the Minimum Viable Product (MVP) for our creator shortlisting and campaign management tool.\n\nAbout the Role:\nAs an Engineer, you’ll work alongside our product team and external partners to bring our vision to life. You’ll be instrumental in building the core features of our product.\n\nKey Responsibilities:\n• MVP Development: Build and implement features.\n• Technical Collaboration: Collaborate with product managers and designers to transform wireframes and mockups into functional code.\n• Backend & Frontend Development: Contribute to both backend systems and frontend interfaces to ensure a seamless user experience.\n• Data Integration: Help integrate AI-driven insights and data to improve creator discovery and campaign tracking.\n• Scalability: Write clean, scalable, and maintainable code to support future iterations of the product.\n• Problem-Solving: Identify and resolve technical challenges to ensure timely delivery of the MVP.\n\nWhat We’re Looking For:\n• Experience: 3+ years in software engineering, with experience developing web applications or MVPs.\n• Technical Skills:\n• Proficiency in backend and frontend technologies (e.g., Python, JavaScript, React, Vue, or similar frameworks).\n• Experience with APIs and database management.\n• AI Interest: Basic understanding of AI/ML tools or enthusiasm for integrating AI into products.\n• Creator Economy Enthusiasm: A strong interest in the creator economy, including platforms like TikTok, Instagram, and YouTube.\n• Team Player: Excellent collaboration skills with a focus on delivering results in a team environment.\n• Startup Mindset: Comfortable in a dynamic environment, with a proactive approach to problem-solving.\n\nWhat We Offer:\n• A chance to work on a high-impact project in the rapidly growing creator economy.\n• Opportunities for professional growth and learning in a supportive team.\n• Competitive salary and benefits.\n• Flexible work arrangements, including remote options.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2003, 948, 2, 'Senior Software Engineer (VN)', 'Primrose Capital Management is a quantitative digital asset management company with an expertise in trading emerging and frontier markets. Our heritage and experience stems from being a first mover in digital asset derivatives and decades spent at some of the world\'s most renowned quantitative hedge funds. Opportunities in this space are often complex and multifaceted. We believe that the diversity of our people, along with data and technology as the linchpin of all we do, are key to navigating this sphere. Responsibilities:\nLead the design, architecture, and development of enterprise-level systems\nDevelop tools, reports, and data feeds to meet the business needs of the trading, operations, and risk teams\nEnsure software quality, performance, cost-efficiency, and operational resilience\nActively contribute to cross-company technology initiatives to support business and operational objectives\nCollaborate with business leaders and front-office trading teams to effectively implement and maintain systems\nWork closely with the local technology team in Vietnam to deliver high-quality technology solutions that support Primrose\'s business functions\nEnsure thorough and up-to-date documentation for all systems and processes\nProvide mentorship and share expertise with junior team members\n\nRequirements:\n6+ years of experience as a software engineer, with a strong focus on backend development\nBachelor\'s or postgrad degree from a renowned University in Computer Science, Information Technology, or a related field.\nExperienced in working with a variety of technologies in a fast-paced, dynamic environment\nProven experience in software design and architecture, with work on cloud infrastructure, like AWS or other cloud platforms\nIn-depth knowledge of Java; experience with Spring Boot is a plus\nSolid experience with messaging queue systems, such as Kafka\nGood knowledge of database design and management; experience with PostgreSQL is a plus\nExperience in writing and implementing unit, integration, and functional tests\nWell-versed in DevOps practices; ability to set up CI/CD pipelines, containerization, and automated deployment\nGood English communication skills\nAWS certification is a plus\n\nBenefits:\nThe Environment We Offer\nAs a growing firm with a tightly-knit team, we respect and listen to all our employees. You will get the chance to make an impact by having your voice heard by everyone, including the management.\nOur employees enjoy a high level of autonomy at work. We focus on substance, not form - as long as you can perform, you will be recognized and rewarded. We are also dedicated to supporting our staff and ensuring they develop holistically to maximize their potential in the long-term.\nWe also provide flexible working arrangement as required and a casual and fun environment to boot!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2004, 1059, 2, 'GAME DEVELOPER (MIDDLE)', 'VỀ CHÚNG TÔI\nArcher Studio, thành lập năm 2022 bởi những chuyên gia game giàu kinh nghiệm, chuyên tâm tạo ra các tựa game mid-core và hybrid casual chất lượng cao cho thị trường quốc tế. Sứ mệnh của chúng tôi là mang đến những trải nghiệm giải trí sáng tạo và đầy cảm hứng.\nVới tầm nhìn vươn tầm khu vực, chúng tôi đề cao giá trị Đam Mê - Sáng Tạo - Chuyên Nghiệp - Cống Hiến. Đội ngũ gần 60 thành viên tài năng, đa chuyên môn của Archer Studio chính là động lực để chúng tôi không ngừng đổi mới và chinh phục những thử thách mới.\nKhám phá thêm tại: https://archergame.mobi\n\nBẠN SẼ LÀM GÌ TẠI ARCHER STUDIO?\nVới vai trò Game Developer, bạn sẽ chịu trách nhiệm dẫn dắt kỹ thuật, đồng hành cùng team phát triển những sản phẩm game chất lượng cao cho thị trường quốc tế.\n- Phát triển và tối ưu các tính năng game trên Unity, tập trung vào thể loại 2D.\n- Xây dựng và phát triển game cho công ty(tập trung chủ yếu 2D).\n\nCHÂN DUNG ĐỒNG ĐỘI CHÚNG TÔI TÌM KIẾM\n- Tối thiểu 3 năm kinh nghiệm phát triển game bằng Unity và C#.\n- Thành thạo Unity cho phát triển game 2D.\n- Kiến thức về cấu trúc dữ liệu và giải thuật tốt.\n- Hiểu về các Design Pattern dùng trong phát triển game.\n- Hiểu và áp dụng nguyên tắc SOLID trong lập trình.\n- Thành thạo dựng các UI trong Unity.\n- Biết sử dụng các plugin bên thứ 3 phục vụ trong quá trình làm việc: Dotween, Odin Inspector and Serializer.\n- Biết cách sử sụng các hệ thống về AI Behavior trong game như Behavior Tree, Pathfinding, và Navigation.\n- Thành thạo sử dụng Git trong quản lý source code và làm việc nhóm.\n- Đã từng tích hợp các tính năng IAP, Ads và Analytics cho game.\n- Có hiểu biết về các hệ thống quản lý asset trong game như AssetBundle, Addressable.\n\nNice to have:\n- Từng làm các game dạng Idle.\n- Biết cách xử lý, tối ưu về performance và dung lượng cho game.\n- Đã từng làm việc trong môi trường Agile/Scrum.\n\nVÌ SAO BẠN NÊN CHỌN ARCHER STUDIO?\nTại Archer Studio, chúng tôi không chỉ mang đến một công việc, mà còn là một hành trình phát triển sự nghiệp đầy hứng khởi:\n- Mức lương CẠNH TRANH, không giới hạn, phản ánh đúng năng lực và kinh nghiệm của bạn.\n- Thử việc 100% lương chính thức.\n- Phát triển không ngừng:\n  - Review năng lực 2 lần/năm, lộ trình thăng tiến rõ ràng.\n  - Khuyến khích học tập và nâng cao chuyên môn với chế độ hỗ trợ đào tạo.\n- Làm việc cùng đội ngũ nhân sự tinh nhuệ, giàu kinh nghiệm, sẵn sàng chia sẻ và cùng bạn tạo ra những sản phẩm chất lượng quốc tế.\n- An tâm cống hiến:\n  - Đóng BHXH, BHYT, BHTN đầy đủ.\n  - Thưởng tháng 13 và các dịp lễ tết (Tết dương lịch, 30/4-1/5, 2/9, 8/3, 20/10...).\n  - Quà tặng cho các sự kiện cá nhân: sinh nhật, hiếu hỉ, sinh con, Tết thiếu nhi, Trung thu.\n  - Hỗ trợ khi ốm đau nằm viện.\n  - Khám sức khỏe định kỳ hàng năm.\n- Môi trường làm việc lý tưởng:\n  - Thời gian làm việc: từ 8h30 - 18h00, nghỉ trưa từ 12h đến 13h30, từ Thứ 2 đến Thứ 6.\n  - Trang bị đầy đủ: Máy tính và thiết bị cấu hình cao.\n  - Nạp năng lượng mỗi ngày: Bữa trưa miễn phí, trà, cà phê, bánh kẹo thả ga tại văn phòng.\n  - Năng động, sáng tạo, thân thiện và cởi mở, nơi mọi ý tưởng đều được lắng nghe và trân trọng.\n  - Gắn kết đội ngũ: Du lịch và các hoạt động teambuilding "chất phát ngất". Công ty có quỹ teambuilding riêng cho mỗi team để gắn kết mọi người hàng quý.\n\nBẠN ĐÃ SẴN SÀNG CHO BƯỚC TIẾN TIẾP THEO TRONG SỰ NGHIỆP CÙNG ARCHER STUDIO?\nArcher Studio rất mong được làm quen và khám phá tài năng của bạn. Hãy gửi ngay CV ấn tượng nhất của bạn về cho chúng tôi qua email: hr@archergame.mobi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2005, 822, 2, 'Principal Frontend Engineer (ReactJS/NextJS)', 'We are seeking a Principal Frontend Engineer to spearhead the development and operation of "Money Forward Cloud Box," our cloud file storage solution designed to enhance back-office efficiency. In this role, you will work closely with Product Managers and Designers to build scalable systems ready for large-scale traffic, optimize both User Experience and Developer Experience, boost team productivity, and mentor junior-middle engineers. Your responsibilities will be broad and impactful. The primary focus will be on frontend development using Next.js, however, you may also contribute partially to server-side development involving Ruby on Rails. We enthusiastically welcome applications from motivated individuals passionate about creating outstanding products.\n\nResponsibilities\n- Develop and Deliver products with high responsibility, availability, scalability, security, and maintainability.\n- Work with a product manager, a designer, and backend engineers to implement product features.\n- Provide technical direction and validate technical solutions to ensure quality and scalability in React & Next.js development.\n- Resolve any technical issues, risks, and challenges, escalating as necessary and providing solutions.\n- Contribute to create a sophisticated development team, applying Agile/Scrum methodologies to deliver projects successfully.\n- Support the growth of junior to mid-level engineers through hands-on teaching and coaching, thereby maximizing the team\'s output.\n\nRequirements\nMust-Have Skills:\n- 6+ years of experience in web development with React, with at least 3+ years of experience in web development with Next.js.\n- 3+ years of experience leading a team of 4+ engineers to successfully build, deliver, and operate projects while fostering a collaborative and high-performance culture using Agile methodologies.\n- Strong understanding of JavaScript/HTML/CSS fundamentals.\n- Comprehensive knowledge of web security best practices.\n- Familiarity with RESTful APIs and backend integration.\n- Experience with frontend testing frameworks (Jest, Mocha, etc…)\n- Experience in designing system architecture.\n- Experience in designing and maintaining UI components (Storybook, Visual Regression Test, etc…)\n- Familiarity with CI/CD pipelines and Docker.\n- Strong product mindset with a solid sense of ownership and accountability.\n- Excellent verbal communication skills in English.\n\nNice-to-Have Skills\n- Hands-on expertise in application performance monitoring and optimization.\n- Experience in designing and building backend applications, especially using Ruby on Rails.\n- Previous experience working in a multi-cultural environment.\n- Knowledge of automation testing and end-to-end testing frameworks.\n\nTech Stack\n- Fronted: TypeScript, Next.js\n- Backend: Ruby, Ruby on Rails, Golang\n- Infrastructure: AWS, Terraform, Kubernetes, Kafka\n- Repositories: GitHub\n- Project management: Asana, Jira\n- Monitoring: Datadog, Rollbar\n- CI/CD: CircleCI, ArgoCD, GitHub Actions\n- Analytics: BigQuery, Google Analytics\n- Communication Tools: Zoom, Slack, Figma, Miro\n\nOur benefits\nCaring Mental & Physical Recreation\n- Hybrid working: 2 days at the office and 3 days WFH\n- Working hour: Flexible start 8AM-9AM from Mon-Fri\n- Full salary in probation\n- Insurance: Applied from Probation period:\n  - Social Insurance, Health Insurance, Unemployment Insurance (on 100% salary)\n  - Private health insurance & accident insurance. From Managing level: extra for family members\n- Bonus: 13th month salary\n- 16 - 24 paid days off and more\n- Paternity leave: Extra 5 days\n- Annual company trip; Quarterly team building\n- Billiards & Running club\n- Annual health check\n- Well-equipped facility: Macbook pro, additional monitor,\n\nCaring Career & Development\n- Clear Career path\n- Foreign language & International technology-related certifications sponsoring\n- External & internal training courses\n- Soft-skill workshops\n- Tech seminars\n- Monthly and biannual Recognition Awards\n- Performance & salary review: twice/year (Jun & Dec)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2006, 316, 2, 'Fullstack Engineer Java/React (all genders)', 'HRS, a pioneer in business travel, aims to elevate every stay through innovative technology. With over 50 years of experience, their digital platform, driven by ProcureTech, TravelTech, and FinTech, transforms how companies and travelers Stay, Work, and Pay.\nProcureTech digitally revolutionizes lodging procurement, connecting corporations and suppliers in a cutting-edge ecosystem. This enables seamless efficiency and automation, surpassing travelers\' expectations.\nTravelTech redefines the online lodging experience, offering personalized content from selection to check-in, ensuring an unparalleled journey for corporate travelers.\nIn FinTech, HRS introduces advancements like mobile banking and digital payments, turning corporate back offices into touchless lodging enablers, eliminating legacy cost barriers. The innovative 2-click book-to-pay feature streamlines interactions for travelers and hoteliers.\nCombining these technology propositions, HRS unlocks exponential catalyst effects. Their data-driven focus delivers value-added services and high-return network effects, creating substantial customer value.\nHRS\'s exponential growth since 1972 serves over 35% of the global Fortune 500 and leading hotel chains.\nJoin HRS to shape the future of business travel, empowered by a culture of growth and setting new industry standards worldwide.\n\nBUSINESS UNIT\nTravelTech enables travelers to search and book hotel and meeting room content via modern SAAS booking portals and APIs. Our mission is to provide high quality content and an outstanding user experience to the traveler on the one side and compliance and cost savings for the cooperate travel programs on the other side.\n\nPOSITION\nWe are looking for a Full Stack Engineer React (all genders) who loves to build top notch SAAS application delivering an outstanding user experience for Travelers, Meeting Planners and Hotel Partners.\n\nCHALLENGE\n- Implement full stack applications in JavaScript/Typescript (React) and Java (Spring Boot)\n- Ensure quality of code is kept on a high level\n- Develop, implement and improve application architecture based on AWS Cloud\n- Support the Product Owner, Product Manager, and UX Designer with requirement engineering\n- Collaborate across teams with regards to overarching technical concepts and practices\n- Stabilize, perform improvement and refactor service layer and data model\n- You work on one of our core systems and implement our extranet application, used by thousands of clients to create and manage their assets, content and data.\n\nFOR THIS EXCITING MISSION YOU ARE EQUIPPED WITH...\n- Strong experience in JavaScript/Typescript, HTML/CSS, ReactJS\n- Proficient in building and maintaining dynamic and interactive frontend elements\n- Willingness to contribute to UI design improvements with attention to detail\n- Nice to know about deploying applications at scale with techniques like Infrastructure as Code, Canary or Blue­ Green Deployments\n- Nice to know about AWS Amplify for building and deploying frontend applications\n- Good knowledge of flexible layout, making mobile terminal responsive layout, and solving screen adaptation problems\n- Good understanding of SCRUM/Agile methodologies\n- UI/UX Design experience with Figma or similar tools is a plus\n- Fluency in English, spoken and written.\n\nPERSPECTIVE\nAccess to a global network of a globally united and mutually responsible "Tribe of Intrapreneurs" that is passionately dedicated to renew the travel industry and while doing so reinvent the ways how businesses stay, work and pay.\nOur entrepreneurial driven environment of full ownership and execution focus offers you the playground to contribute to a greater mission, while growing personally and professionally throughout this unique journey. You will continuously learn from a radical culture of retrospectives and continuous improvement and actively contribute to making business life better, smarter and more sustainable.\n\nLOCATION, MOBILITY, INCENTIVE\nThe attractive remuneration is in line with the market and, in addition to a fixed monthly salary, all necessary work equipment and mobility, will also include an annual or multi-year bonus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh-Stadt, Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2007, 880, 2, 'Freelance Software Developer (Ruby) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with Ruby\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2008, 732, 2, 'Full Stack Engineer', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nThe Role: Our group is looking for a seasoned full stack developer to work on important internal services which are critical to the firm. As a full stack developer, you will have the opportunity to advance the architecture and develop complex frontend views to ensure optimal user experiences.\n\nDevelop/Maintain internal web applications on cloud and on premise\nCreate/Present API design specifications\nWrite well designed, tested code\nCreate and maintain software documentation\n\nWhat You’ll Bring\n\nExpertise in Python web frameworks such as FastAPI, Flask, Django and others\nExperience in HTML, CSS, JavaScript/TypeScript\nDemonstrated experience in developing scalable and robust software web applications\nExperience with popular JavaScript libraries and tools such as React.js, jQuery, NPM\nWorking experience with SQL databases (PostgreSQL , MySQL)\nA solid background in Unix/Linux environment\nExperience with CI/CD\nExperience with Docker and containerized application\nExcellent debugging and problem solving\nExperience with Kubernetes or distributed systems is a plus\nExperience with GCP is a plus\n\nWhat We Offer\n\nCompetitive and attractive compensation package with clear career road-map – where you feel challenged everyday\nWe offer a strong culture of learning and development: training courses, library, speakers, share and learn events\nLearn from who sits next to you! Working in WQ you are surrounded by smart and talented people\nEmployee resources groups with strong diversity and inclusion culture\nPremium Health Insurance and Employee Assistance Program\nGenerous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family\nTeam building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\nAnnual company trip and occasional global conferences – opportunity to travel and connect with our global teams\nHappy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2009, 442, 2, 'Senior Software Engineer', 'Who We Are\n\nEmployment Hero is on a mission to make employment easier and more valuable for everyone. Our Employment Operating System brings hiring, HR, payroll and benefits into an all-in-one solution.\n\nSince our inception in 2014, we\'ve scaled to a $2 billion valuation and gained a presence in 6 countries globally - Australia, New Zealand, Singapore, Malaysia, the UK and Canada. We now service over 300,000 businesses and more than 2 million employees.\n\nThe EH Way\n\nAt Employment Hero, we\'re proud of our unique DNA, which we call The EH Way.\n\n- We are Mission First - everything we do (from what we work on, to how we allocate capital and where we focus) is driven by our Mission\n- We are Remote First - we champion a remote environment with a preference for asynchronous communication and a high degree of autonomy \n- We are AI First - we are committed to using AI to accelerate our mission; AI is not just a tool, it\'s a fundamental part of how we operate, innovate, and scale\n- We are Apolitical - we do not take a position on political or social topics, unless it relates to our Mission\n- We Live by Our Values - we role model our values 100% of the time\n- We Expect High Performance - we set a high standard and we\'re not satisfied with being average\n\nThis role \n\nAs one of our Senior Backend Engineers, you\'ll be accountable for building and deploying the innovative features that change our customers\' lives every day. From our trailblazing AI hiring tool to our fully automated payroll solution, every component of our Employment Operating System is carefully designed to disrupt the employment industry for the better, improving the lives of business owners and entrepreneurs everywhere.\n\nOur world-class Product and Engineering teams delivered almost 1,000 new features last year. As one of our Senior Engineers, you\'ll play a vital role in the continued acceleration of our product strategy.\n\nThis will include\n\n- Driving your squad to develop critical features for our customers. We primarily develop our applications using Ruby. If you\'re not familiar with Ruby, no worries—we offer training to ensure you\'re equipped with the necessary skills \n- Collaborating closely with our global team of designers, product managers and UX specialists to gather requirements and translate them into technical solutions \n- Writing automated tests for your production codes \n- Developing and maintaining key components of web applications \n- Conducting testing and code reviews for both yourself and your colleagues \n- Mentoring the Junior Engineers within your squad\n\nWho You Are\n\nTo thrive at Employment Hero, you\'ll need to embody The EH Way - operating with focus, agility, and an obsession with impact. For this role, you\'ll also bring\n\n- You are a highly skilled, senior-level Software Development Engineer (our Senior Engineers typically have 6+ years of experience in Software Development, but we grade based on technical expertise over years of experience)\n- In previous roles, you\'ve focused on Server-side and RESTful API Development and integration\n- You\'re proficient in at least one OOP language, such as Python, Java, PHP, etc. We\'ll upskill you in Ruby when you join\n- You have proven experience implementing, maintaining and deploying full-stack web technologies\n- You have a strong understanding of best practice software engineering processes, testing, and Agile methodology\n- A team player that always puts colleagues ahead of yourself and has a highly adaptable and versatile approach to work\n- You have good verbal and written English skills \n- You\'re passionate about learning, sharing your knowledge, and mentoring team mates\n- Experience is important, but for us the biggest measure of success is people who can live and breathe our EH Way of working. Show us what you can bring to the table, and we\'ll empower you to let your talents shine\n\nWhat We Can Offer\n\nAt Employment Hero, we don\'t just talk about a better way to work - we live it. Joining Employment Hero means\n\n- You will work remotely, with the flexibility to own your time and impact\n- You will access cutting-edge tools to amplify your work, knowledge and outputs \n- You\'ll surround yourself with ambitious, outcome-driven colleagues who challenge you to do the best work of your life\n- You\'ll own ESOP (employee share options) in one of the world\'s fastest-growing tech companies \n- You\'ll also have access to a wide range of benefits that includes - a very generous paternity leave policy, subsidised egg freezing (so you can make the choice that\'s right for you, on your terms), a WFH office expense budget, and outstanding learning & development opportunities \n\nAt Employment Hero, we are committed to safeguarding the privacy of your application data. To understand how we do so, you can read our Applicant Privacy Policy here\n\nEmployment Hero celebrates diverse perspectives and experiences, we invite people of all backgrounds and identities to apply for this position.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2010, 797, 2, 'Associate QA Engineer', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.\n\nThe Position \n\nThe position will play an important role in assuring quality of OPSWAT cyber security technologies and products at the highest level. As a member of the team, you will be involved in every stage of the software development life cycle.\n\nWhat You Will Be Doing\n- Responsible for both manual and automated test. \n- Analyze/review product requirements. \n- Write/review detailed test cases and perform testing based on requirements. \n- Perform different types of testing: API testing, functional testing, integration testing, usability testing, compatibility testing, performance testing, security testing, regression testing, … \n- Utilize and improve the existing test framework to implement automated tests. \n- Handle support escalation such as creating reproducible bug reports or help troubleshoot. \n- Report/manage defects. \n\nWhat We Need From You\n- Experience in software testing with a good QA mindset. \n- Experience in testing software on different Operating Systems (Windows, Linux...) and Browsers. \n- Experience in writing automation using any scripting languages (bash shell, powershell, python, ...), any programming languages such as Java, C/C++, C#… \n- Familiar with working in Agile team. \n- Good at written English communication. \n\nIt Would Be Nice If You Have \n- Good at verbal English communication. \n- Familiar with JIRA, TeamCity, Git. \n- Experience in leading a QA team. \n- System and/or network administration skills (MCP and/or LPI certificates are welcomed). \n- Cyber security domain experience, including file security, device security, network security etc... \n\nOPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws.\n\nRecruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2011, 1060, 2, 'Full Stack AI Engineer', 'Company Description\nRenesas is one of the top global semiconductor companies in the world. We strive to develop a safer, healthier, greener, and smarter world, and our goal is to make every endpoint intelligent by offering product solutions in the automotive, industrial, infrastructure and IoT markets. Our robust product portfolio includes world-leading MCUs, SoCs, analog and power products, plus Winning Combination solutions that curate these complementary products. We are a key supplier to the world’s leading manufacturers of electronics you rely on every day; you may not see our products, but they are all around you. \n\nRenesas employs roughly 21,000 people in more than 30 countries worldwide. As a global team, our employees actively embody the Renesas Culture, our guiding principles based on five key elements: Transparent, Agile, Global, Innovative, and Entrepreneurial. Renesas believes in, and has a commitment to, diversity and inclusion, with initiatives and a leadership team dedicated to its resources and values. At Renesas, we want to build a sustainable future where technology helps make our lives easier. Join us and build your future by being part of what’s next in electronics and the world.\n\nAbout this role\nAs a Full Stack AI Engineer, you will develop the user interfaces for and manage the full lifecycles of AI/ML application experiences.\n\nAbout our team\nOur global AI, Data & Analytics Division at Renesas is experiencing an increasing demand for AI and Generative AI (LLM) based solutions. Working closely with our business partners, we deliver AI solutions to help drive value for Renesas at a global enterprise scale. We are seeking passionate candidates that will thrive as part of a global team of technologists that love empowering customers, collaborating with teammates, and using the latest AI and Data technologies.\n\nJob Description\n- Develop and maintain full stack AI/ML applications using Databricks tools and frameworks\n- Build and enhance user interfaces and experiences for AI solutions, including front-end and back-end systems and deploying complete applications\n- Collaborate with data scientists and AI/ML engineers, and domain experts on cross-functional projects using Databricks Workspaces\n- Keep up to date with the latest developments and trends in AI/ML applications and Databricks technologies\n\nQualifications\n- Bachelor\'s degree or higher in computer science, engineering, or a related field\n- Experience with web development frameworks and tools, such as React, Angular, Bootstrap, etc. for AI applications\n- Proficient in Python, SQL, HTML, CSS, JavaScript, Node.js or other programming languages for full stack AI/ML development\n- Familiarity with Databricks products and services\n- Have working knowledge of CI/CD\n- Effective communication, documentation, and white-boarding skills\n- Passionate about creating innovative and impactful AI/ML solutions\n\nAdditional Information\nStrongly Preferred\n- Databricks Certifications\n- Experience in developing and deploying full stack AI/ML applications using Databricks products and services\n- Knowledge of AI/ML frameworks and libraries, such as TensorFlow, PyTorch, Scikit-learn, etc.\n- Working knowledge of at least one major cloud ecosystem (Azure, AWS, or GCP); Azure is preferred\n- Knowledge in LLM use cases such as RAG\n- Experience working with a geographically distributed and cross-functional team including systems integrators and third-party companies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2012, 1054, 2, '(All Level) Embedded Linux Engineer', '1. INTRODUCTION\nFounded in 2010, Ban Vien Corporation has embarked on an inspiring journey, evolving into a trusted technology partner that has left an indelible mark in the realm of software development and embedded system development. Today, our influence extends both domestically and internationally, showcasing our commitment to driving digital transformation. At Ban Vien, we relentlessly pursue innovation across diverse industries like Edutech, Fintech, Retail, Automotive, Smart IoT, and Logistics. Our comprehensive services span Digital Consulting, R&D, Software Development, and Dedicated Development Centers. This global expansion includes valued clients and esteemed partners in the United States, Germany, Japan, Singapore, China, Hong Kong, Thailand, Malaysia, and Vietnam.\n\n2. JOB DESCRIPTION\nRZ/G1 VLP/ VLP64 Maintenance\nEvery 03 months, update CIP kernel (4.4.x, 4.4.x-RT, 5.10.x, 5.10.x-RT) to G1, G2 series.\nDisclose the package to GitHub public.\nUpdate HMI/QtHMI demo, sample apps, Application Development Package if impacted by CIP kernel update.\nSystem Integration, Technical review, Answer customer technical questions.\nUpstream/Backport bug-fixes.\n\nRZ/G2L BSP Development\nPort u-boot, CIP kernel (4.19.x, 4.19.x-RT, 5.10.x, 5.10.x-RT), Drivers (New, A2M, Zeus, V3U, etc. based), Basic libs(cip-core), ECC to G2L series and V2L.\nLow power mode.\nIntegrate MMP, GStreamers, Qt.\nDisclose the package to GitHub public.\nSystem Integration (Yocto 3.1), Technical review, Answer customer technical questions.\nUpstream/Backport bug-fixes.\n\nRZ/G VLP Automation/Tool\nIT for BSP drivers, ST, LTP, Khronos Conformance Test, Qt test, Web-Platform-Testing, Draw Elements Quality Program (dEQP), Performance test for HTML5.\nBenchmark.\nBuild Automation CI/CD/Test env (LAVA, R-Car Automation Test env based, etc.).\nDeeply analyze Web-Platform-Testing failed cases.\n\nRZ/A Linux and RZ/G RTOS platform support\nAnswer technical questions from RZ/A Linux customers.\nPorting drivers to RZ/A3UL on CA55.\nInvestigate, Design, Code, and Test some drivers of FreeRTOS env on CR7 of G2M.\nInvestigate, Design, Code, and Test some drivers of FreeRTOS env on Cortex M33 of G2L.\nOpenAMP verification on Multi-OS (Linux, FreeRTOS) environment.\n\n3. REQUIREMENTS\nAt least 1 year of experience at the same field.\nBachelor’s Degree or above in Electronic Engineering, Telecommunication, Computer Science, Computer Engineering, Automation, Information Technology or equivalent.\nStrong proficiency with C/C++.\nExperience with firmware/driver programming/debugging.\nProficiency with Linux OS, FreeRTOS, Linux kernel.\nFamiliar with BSP.\nFamiliar with Scripting language, Multimedia frameworks & Audio/Video codec, Graphics libraries and Image processing, HW manual & Schematics reading.\nCapable of reading and understanding MCU/SOC hardware manual.\nLeading skill, Teamwork skill, Investigation skill, Self-control.\nWeb-Platform (HTML5, Firefox, Gecko).\nFluent in both written and spoken English.\n\n4. COMPANY BENEFITS\n13th Salary + Performance Bonus.\nPass probation Bonus.\nPremium healthcare insurance benefits (PVI Insurance package) and family medical benefit (based on the level of experience).\nProvide the famous e-learning platform-Udemy, to encourage continuous learning to adapt to the T-shape model.\nFlexible working time: only 8 hours required as continual working-time at the office.\nAnnual leave up to 17 days: 12 days paid leave + 5 days’ sick leave.\nProfessional and Personal Development Training Programs.\n4 Stars standard company trip in summer and a big annual Year-End-Party.\nCoffee and snacks provided.\nHoliday celebrations and parties for team members and family.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2013, 814, 2, '[iKame Games] Unity Game Developer', 'Location: Hà Nội\n\nSalary: Up to $2000\n\nExpiration date: 30/06/2025\n\nMÔ TẢ CÔNG VIỆC\n\n- Project Manager của sản phẩm mình phát triển: \n- Xây dựng và phát triển các dự án Game mobile trên nền tảng Unity cho Android và iOS. \n- Phối hợp trực tiếp với các thành viên Product (GD, Artist, Tester, Animator,...) và bộ phận Marketing (UA), Business Intelligent, Monetize để phát triển, vận hành và tối ưu sản phẩm. \n- Tò mò, thích học hỏi để nghiên cứu công nghệ mới nhằm cải thiện và nâng cao Game Quality (ANR, Crash, Ingame Metrics, Performance....). \n- Theo dõi và bám sát hằng ngày sự thay đổi của các chỉ số vận hành sản phẩm: Retention, Impressions, Engagemnet Time, ARPU...\n- Cùng team phân tích, nghiên cứu thị trường nhằm đánh giá, chủ động đưa ra ý kiến, tìm kiếm idea game tiềm năng trên Android & IOS.\n- Sáng tạo ý tưởng, đưa ra giải pháp tối ưu hóa cho các tính năng mới trong sản phẩm/ trong cách làm.\n- Tham gia quá trình xây dựng team dev; chia sẻ và cùng phát triển chuyên môn các bạn dev của công ty.\n\nYÊU CẦU CÔNG VIỆC\n\n- Đối với TTS - Fresher: Tối thiểu 6 tháng hiểu biết về Unity; hiểu biết về UI Canvas, Physic, Particle System, Optimization;... và ưu tiên đã có sản phẩm.\n- Đối với Junior trở lên: Thành thạo C# & Unity. \n- Biết Mirror hoặc Photon là một lợi thế. \n- Có nền tảng tư duy thuật toán, cấu trúc giải thuật, tư duy logic tốt. \n- Yêu thích làm game và chơi game. \n- Khả năng tư duy và sáng tạo tốt. \n- Có trách nhiệm cao trong công việc, thái độ cầu tiến và thích thử thách công nghệ khó, ham học hỏi công nghệ mới. \n- Có khả năng đọc hiểu tài liệu bằng Tiếng Anh là một lợi thế.\n\nQUYỀN LỢI\n\n- Mức lương lên tới 50.000.000VNĐ theo level, review lương 2 lần/năm\n- Thưởng LINH HOẠT & HẤP DẪN: Thưởng Lễ, Thưởng Tết dương tháng lương 13, Thưởng nóng, Thưởng hiệu quả kinh doanh 6 tháng/ lần N tháng lương theo doanh thu sản phẩm và theo mức độ đóng góp vào dự án\n- Trợ cấp ăn trưa 1 triệu đồng/ tháng\n- Cơ hội tham gia và xây dựng dự án game casual hướng tới CHẤT LƯỢNG và GHI DẤU ẤN – cơ hội phát triển và cơ hội thăng\n- Được học hỏi, được thử sai, được đưa ý kiến để rèn luyện bản thân và trau dồi kinh nghiệm thực chiến với việc hỗ trợ 30-100% chi phí các khóa học mọi kỹ năng\n- Môi trường thân thiện, trẻ trung, hiện đại, văn phòng đẹp xịn xò view cửa kính toàn thành phố\n- Con người là số 1 - bạn sẽ được quan tâm từ trang thiết bị làm việc, bữa ăn xế chiều, tới chỗ ngủ, từ tủ đầy đồ ăn vặt tới bàn bia, bi-lắc, PS4 xả não, thư viện cho những tâm hồn yêu thích đọc sách\n- Các chế độ đãi ngộ khác như khám sức khỏe, teambuilding, du lịch... đều được đảm bảo\n- Giờ làm việc 8:30 - 18:00 từ thứ 2 tới thứ 6; ưu tiên sự linh hoạt và chủ động quản trị hiệu suất; cân bằng cuộc sống - công việc\n- Còn gì nữa? Hãy cùng chúng mình khám phá và cùng xây dựng văn hóa iKame để phát triển từng cá nhân nhé!\n\nCÁCH THỨC ỨNG TUYỂN\n\n💌 Ứng viên gửi CV về email: recruitment@ikameglobal.com\n\n➡️Hotline: 0246 281 6688 | HR Department\n\n➡️Head Office: Tầng 9 & 10 tòa Peak View, số 36 Hoàng Cầu, Ô Chợ Dừa, Đống Đa, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2014, 723, 2, 'Tuyển dụng kỹ sư trực hệ thống CNTT mạng Vietnamobile', 'Mô tả công việc: – Theo dõi hệ thống: xem xét các thông tin từ phần mềm giám sát để có các thông số và cảnh báo của toàn hệ thống. – Kiểm tra hệ thống: tiến hành kiểm tra và ghi nhận hiện trạng – Khắc phục sự cố: dựa trên các thông báo lỗi nhận được, phối hợp với các đối tác cung cấp để xử lí. – Giám sát và phân tích chất lượng, hiệu suất hệ thống. – Thực hiện báo cáo chất lượng, hiệu suất sử dụng hệ thống theo định kỳ. – Xử lý các sự cố về kỹ thuật khi có yêu cầu. – Tham gia trực ca hệ thống 24/7. – Nơi làm việc: Tầng 8, tòa nhà HTC, Km27+300, khu CNC Phú Cát, Hà Nội – Số lượng: 05\n\nYêu cầu: – Tốt nghiệp cao đằng, đại học chuyên ngành CNTT và ĐTVT. Có thể tuyển cả SV mới ra trường nếu đáp ứng được yêu cầu. – Có kiến thức cơ bản về Network, về các hệ điều hành Window, Linux và Database, ưu tiên có 1 trong các chứng chỉ trên. – Chịu được áp lực công việc, có tinh thần học hỏi, cầu tiến và làm việc theo nhóm tốt. – Trình độ tiếng anh tương đương TOEIC 450.\n\nQuyền lợi: – Được làm việc trong môi trường chuyên nghiệp, tiếp cận các hệ thống CNTT & VT tiên tiến nhất. – Mức lương và thưởng hấp dẫn sẽ thỏa thuận khi phỏng vấn. – Được kí hợp đồng lao động và đóng BHXH, BHYT theo quy định của nhà nước. – Có xe đưa đón từ HN.\n\nCách thức ứng tuyển: Ứng viên quan tâm điền thông tin tại đây: https://goo.gl/forms/sWtWjVYn94bos3mv1 Hoặc gửi mail ứng tuyển tới: Ms. Thêm: thempt@nms.com.vn Mọi thắc mắc vui lòng liên hệ: Phòng HCNS – Ms. Thêm: 0473008555 – 0982 901 255\n\nThời hạn nhận hồ sơ: 30/12/2017. Ưu tiên hồ sơ nộp sớm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2015, 743, 2, 'Microsevices Developer', 'Position : Microsevices Developer \nQuantity : 05\nType : Full-time\nLocation : 68 Nguyen Co Thach street, Ha Noi.\nAbout Us\nLTS (Lotus Technology Service) is an outsourcing company, established in 2017, We are specialized in Web development, Mobile Phone development and AI Development, our main clients are from Japan and US \nWe are now looking for good candidates for vacancies below as followings\nJob Description\nParticipate in development projects for Application \nPerform implement coding, testing and documentation in line with user & system requirements to deliver source code that meet the needs and release milestone \nPerform bugs fixing, maintaining, enhancement \nAble to take the role technical leader of project, propose technical solution for various problems \nREQUIREMENT\nAt least 3+ years of working as developers \nWindows Form, .NET Framework 4.7.2, C#, and associate technologies. \nExperience using Source Control Systems (Git preferred) or simil \nSynfusion PDF for .NET, \nSynfusion Winform Component, \nSQL Server, Experience developing with Entity Framework \nNice To Have\nExperience developing MVC and Web API applications \nExperience with front end technologies: AngularJS/ \nMono Framework(for MacOS build) \nLanguage: English (plus) \nBENEFIT\nAttractive salary Up to 25M. Performance based award. \nYoung and dynamic working environment. \nContinuous development of hard and soft skills through work and professional trainings. \nOpportunity to approach newest technology trends \nSalary review 2 times/year or on excellent performance \nCompany’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.) \nCONTACT\nLTS Recruitment Department\nPhone Number : 02466607474\nEmail : rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói, Hanoi, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2016, 860, 2, 'Back End Developer Crypto/Blockchain domain', 'Mô tả công việc: \n- Phát triển, tối ưu và bảo trì hệ thống backend của công ty.\n- Xây dựng các sản phẩm theo định hướng của công ty. Phát triển triển các ứng dụng theo mô hình microservice có tính mở rộng và ổn định cao.\n- Tham gia đóng góp ý kiến, phát triển các ý tưởng thành thực tế.\n\nYêu cầu:\n- Tốt nghiệp đại học chính quy chuyên ngành: CNTT, Khoa học máy tính, Toán – tin\n- Tối thiểu ít nhất 1 năm làm việc với vai trò Backend sử dụng Golang hoặc Rust.\n- Sẵn sàng học và làm việc với các ngôn ngữ mới.\n- Có kinh nghiệm làm việc với mô hình MicroService và các giao thức liên quan như HTTP/HTTP2, gRPC, AMQP … \n- Sử dụng tốt Linux, công nghệ container như Docker.\n- Thành thạo sử dụng CSDL Postgre, MongoDb, Redis …\n- Khả năng giao tiếp tốt, hòa đồng, làm việc trong môi trường năng động và cường độ áp lực công việc cao.\n- Có khả năng tư duy logic, giải quyết vấn đề tốt.\n- Đọc hiểu tài liệu tiếng anh, tổng hợp viết báo cáo nếu có yêu cầu.\n- Hiểu biết về blockchain hoặc đã từng tham gia dự án blockchain là điểm cộng.\n- Đam mê học hỏi và khả năng tự nghiên cứu công nghệ mới.\n\nQuyền lợi: \n- Lương từ 15tr - 30tr, thỏa thuận theo năng lực.\n- Thưởng theo kết quả kinh doanh, thưởng nóng cho những đóng góp vượt trội\n- Tháng lương 13, thưởng Lễ tết\n- Được đào tạo các kỹ năng chuyên môn cao.\n- Làm việc từ Thứ 2 - Thứ 6 hàng tuần (7,5h/ ngày).\n- Du lịch, khám sức khỏe hàng năm, Team Building hàng quý.\n- Gửi xe miễn phí, đồ ăn nhẹ Teabreak hàng ngày miễn phí.\n\nĐịa chỉ:\nTầng 6 toà Golden Field số 24 Nguyễn Cơ Thạch, Nam Từ Liêm, HN', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2017, 1061, 2, '[R&D] Technical Documentation Engineer', 'Bosch first started in Vietnam with a representative office in 1994. Bosch has its main office in Ho Chi Minh City, with branch offices in Hanoi and Da Nang, and a Powertrain Solutions plant in the Dong Nai province to manufacture push belt for continuously variable transmissions (CVT) in automobiles. In addition, Bosch operates a software and engineering solutions from product engineering, tool development & automation as well as testing & validation solutions (Bosch Global Software Technologies Vietnam).\n\nIn July 2014, Bosch set up a new Automotive R&D Center, located in Ho Chi Minh City. The continuous growth of this Centre is in line with Bosch’s strategy in Vietnam, which aims at becoming a manufacturing and R&D hub in the Southeast Asian region. Currently four products are available: connectors, push belt, fuel supply, and diagnosis module (tank leakage).\n\nFor further information, please visit our website: www.bosch.com.vn\n\nJob Description\n\n1. Analyse legal regulations & standards of countries worldwide and derive technical requirements - including documentation in databases in technical topic areas such as vehicle safety, exhaust treatment, emissions, on-board diagnosis, safety, security, materials, data protection, fuel consumptions/energy consumption, EMC, reliability, vibration or others.\n\n2. Understand automotive and non-automotive products, systems, SW and services in order to identify relevant regulations, as well as derive requirements and conduct product evaluation.\n\n3. Understand and apply legal structure know-how of countries in regulation research. Apply understanding of legal and technical content of regulations to document in databases and to derive requirements.\n\n4. Collaborate with local and international teams to close potential gaps in working processes and methods.\n\n5. Improve efficiency in daily work by applying programming / coding in daily work or improving processes / methods.\n\n6. Other tasks as assigned by manager.\n\nQualifications\n\n1. Educational background\n\nBachelor or above in STEM fields, Technical English\n\n2. Working experience\n\n1-3 years of experience in product development or applied research\nFresh graduates with previous research experiences are welcome\n\n3. Traits and Skills\n\nAnalytical skills\nExcellent technical English reading and writing ability\nPrecision in work and good time management\nExcellent communication with different internal and external stakeholders\nWillingness to take responsibility and initiative\nLearning and adaptability\nGood knowledge about mechanical, automotive engineering, SW, Systems, and components, as well as new technology trends\nProgramming skill is an advantage', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 2, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2018, 778, 2, 'Back End Developer', 'HCL Vietnam is seeking a highly skilled and motivated Senior Software Engineer to join our team and work closely with our esteemed customer, a prominent banking company. As a Backend Golang Developer, you will play a crucial role in designing, developing, and maintaining robust, scalable, and secure backend systems to meet the customer\'s specific needs.\n\nJOB DUTIES:\n\n- Collaborate with cross-functional teams, including software architects, product managers, and frontend developers, to understand project requirements and translate them into efficient and scalable backend solutions.\n- Design, develop, and deploy server-side applications and services using Golang programming language.\n- Write clean, reusable, and efficient code following industry best practices and coding standards.\n- Implement secure authentication and authorization mechanisms to ensure data privacy and protection.\n- Optimize application performance and scalability through efficient data retrieval, caching, and storage techniques.\n- Collaborate with the database team to design and optimize database schemas and queries for optimal performance.\n- Participate in code reviews to ensure code quality, maintainability, and adherence to established coding guidelines.\n- Troubleshoot and debug production issues, propose and implement solutions to ensure smooth and uninterrupted system operations.\n- Stay up to date with the latest trends and advancements in backend development and propose innovative ideas to improve the overall system architecture and performance.\n\nREQUIREMENTS:\n\n- Bachelor’s degree in computer science, Software Engineering, or a related field.\n- Proven 6 years of experience working as a Backend Developer.\n- Strong knowledge and understanding of server-side development concepts, patterns, and best practices.\n- Proficient in programming languages such as Java, Node.JS, Python, Golang and its ecosystem, with a solid understanding of core language concepts and standard library.\n- Experience with developing RESTful APIs and microservices architectures.\n- Familiarity with database systems such as PostgreSQL, MySQL, or MongoDB.\n- Knowledge of containerization technologies like Docker and container orchestration platforms like Kubernetes is a plus.\n- Familiarity with DevOps practices and tools for continuous integration and deployment is a plus.\n- Ability to work effectively both independently and in a team-oriented, collaborative environment.\n- Excellent problem-solving skills and the ability to analyze and resolve complex technical issues.\n- Strong communication skills, with the ability to effectively communicate technical concepts to both technical and non-technical stakeholders.\n\nBENEFIT\n\n- Insurance plan based on full salary + 13th salary + Performance Bonus.\n- Attractive salary package\n- 100% full salary in probation period.\n- Meal allowance 730,000 VND/month\n- Personal medical benefit (24/7 Bao Viet Insurance package) and family medical benefit (based on level of experience).\n- 18 leaves per year (including 12 annual leaves, 6 personal leaves and not including public holidays).\n- Working in a fast paced, flexible, and multinational working environment. Chance to travel onsite (in 60 countries).\n- HCL Technologies has been named by Forbes as being ranked number 30 of The World’s Best Employers for 2020, honoring HCL among the top global employers in the world.\n- Internal Training (Technical & Functional). Scope of English Training.\n\n*** Note: We highly appreciate your interest in this position of HCL Vietnam. After reviewing all applications, only qualified candidates will be contacted for the next steps within 15 days from date of submission.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2019, 675, 2, 'Tester', 'Sapo là công ty Công nghệ. Với khả năng và hướng đi rõ ràng, Sapo nhanh chóng khẳng định được vị trí hàng đầu trong việc xây dựng nền tảng công nghệ hỗ trợ lĩnh vực bán lẻ và TMĐT. Với hơn 230.000 khách hàng trên toàn quốc tin tưởng sử dụng, Sapo đang là doanh nghiệp có nền tảng quản lý và bán hàng đa kênh từ Online đến Offline được sử dụng nhiều nhất tại Việt Nam.\n\nĐội ngũ nhân viên Sapo hiện có hơn 1000 nhân sự có trình độ chuyên môn cao, luôn làm việc với tất cả sự nhiệt huyết và sức sáng tạo của tuổi trẻ đã xây dựng nên 1 văn hoá vô cùng trẻ trung và năng động. Đến với Sapo, bạn sẽ được trải nghiệm môi trường tuyệt vời, với chế độ đãi ngộ xứng đáng và đạt được thành công vượt mong đợi!\n\nMô tả công việc\n\nTham gia xây dựng yêu cầu, lên kế hoạch và thực hiện kiểm thử phần mềm thương mại điện tử\nĐọc hiểu các tài liệu proposal, specs, tham gia làm rõ yêu cầu\nLập các bộ tài liệu test, thực hiện test sản phần\nNghiên cứu cập nhật các công cụ test, kiến thức test mới , đề xuất cải tiến quy trình test\nMột số công việc khác theo yêu cầu\n\nYêu cầu công việc\n\nCó ít nhất 1 năm kinh nghiệm test web/app\nCó kinh nghiệm sử dụng các công cụ test và quản lý lỗi\nCó kiến thức về Restful API, Có kinh nghiệm sử dụng 1 số công cụ để test API\nCẩn thận tỉ mỉ, tư duy logic nhanh, làm việc nhóm\nCó kinh nghiệm kiểm thử các sản phẩm AI là 1 lợi thế\nCó kinh nghiệm xử lý dữ liệu là một lợi thế\nCó kinh nghiệm về cơ sở dữ liệu là một lợi thế\nĐọc hiểu tài liệu tiếng anh\nTốt nghiệp đại học/cao đẳng trở lên\n\nQuyền lợi\n\n- Lương/thưởng hấp dẫn theo quy định của công ty\n- Review lương theo năng lực\n- Được làm việc trong môi trường chuyên nghiệp, trẻ trung, năng động.\n- Chế độ BHXH, BHYT theo luật Lao động, ngoài ra được tham gia chương trình bảo hiểm Sapo Care\n- Được tham gia các khoá đào tạo từ các chuyên gia hàng đầu về thương mại điện tử, marketing online, phần mềm .\n\nLiên hệ\n\nĐể tìm hiểu thêm chi tiết, vui lòng liên hệ:\n\n- SĐT: 0913 198910 (Ms. Linh)\n- Email: tuyendung@sapo.vn\n- Website công ty: https://www.sapo.vn/\n- Fanpage TD: https://www.facebook.com/tuyendungsapo/\n- Zalo OA: Tuyển Dụng Sapo\n- Địa chỉ văn phòng: Tòa Ladeco, 266 Đội Cấn, Ba Đình, Hà Nội\n\nỨng tuyển vị trí: Tester\n\nClick để tải lên CV của bạn\n\nBạn có thể tải CV mẫu tại đây', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2020, 728, 2, 'Frontend Engineer (Chinese-speaking) - 4K NET', 'Our client is a leading global company specializing in creating engaging, high-quality online entertainment experiences for a diverse audience. Join a passionate and talented team as they continue to expand and enhance our portfolio of entertainment.\n\nResponsibilities\nWe are a growing software development company focused on delivering high-performance, user-centric web platforms for clients in the online entertainment industries, particularly across Asia. Our team specializes in developing responsive, scalable frontend solutions tailored for high-traffic environments. As part of our continued growth, we’re looking for an experienced Frontend React Engineer to help us build and optimize next-generation web platforms for our clients.\n\nDesign and implement responsive frontends using React.js and modern JavaScript/TypeScript frameworks\nCollaborate with cross-functional teams including product managers, designers, and backend engineers to deliver seamless user experiences\nDevelop reusable components and frontend architecture to support scalability and maintainability\nIntegrate with APIs, third-party services, and real-time data systems\nOptimize web performance, accessibility, and compatibility across devices and browsers\nDebug and resolve frontend issues, ensuring a stable user experience\nMaintain awareness of emerging trends in web technologies and apply best practices in development\n\nQualifications\n3+ years of frontend development experience with a strong focus on React.js and component-based architecture\nProficiency in JavaScript, TypeScript, HTML5, CSS3, and RESTful API integration\nDemonstrated experience building modern web applications for digital platforms or online services with complex user flows\nUnderstanding of frontend session handling, dynamic content rendering, and platform integrations\nStrong attention to performance, responsive design, and user experience\nFluent in Chinese (Mandarin) – both written and spoken, to support localization and collaboration with regional stakeholders\nAbility to work independently and within a local team structure\n\nPreferred Qualifications\nExperience with server-side rendering frameworks (e.g., Next.js)\nKnowledge of analytics, event tracking, and performance monitoring tools\nUnderstanding of multi-market deployment and localization practices\n\nWorking hours & Location\nWorking hours: From 9 AM - 6 PM, Monday to Friday.\nLocation: \n-Binh Thanh District, HCMC\n-Duy Tan, Cau Giay, HN\n-Hai Chau, Da Nang\n\nCompensation and Benefits:\nSalary up to 4000 USD Net\nMacBook or high-end laptop for working.\nAttractive salary and annual salary review.\nWorking in a professional, friendly, well-equipped environment both with foreigners and Vietnamese.\n12 days annual leave per year.\n13th-month salary.\nEnjoy diversified activities:  Free snacks, Weekly and Monthly Team-building, Company trips, Play Games (PlayStation, Board games), and Play Sports (Football, Badminton...).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2021, 681, 2, 'Data Engineer (English Fluency)', 'WHAT WE DO\nAt Sun Asterisk, we build cutting-edge, high-performance systems to tackle complex challenges. As a developer, you will:\n\nDesign, build, and maintain ETL/ELT data pipelines using Python.\nIntegrate various data sources into a centralized data warehouse on Amazon Redshift.\nWork with the in-house team and CTO to define data models and deliver analytical datasets.\nOptimize data ingestion and transformation processes for performance and scalability.\nCollaborate with BI engineers and product stakeholders to support reporting and dashboards using AWS QuickSight.\nEnsure data quality, governance, and pipeline observability.\n\nWHO YOU ARE\n#Experience Requirements\nMandatory Skills\n5+ years of experience as a Data Engineer.\nStrong programming skills in Python for data transformation and scripting.\nExperience with AWS Redshift and understanding of modern Data Warehousing principles.\nFamiliarity with SQL performance tuning, partitioning, and query optimization.\nHands-on experience in building and maintaining ETL/ELT pipelines (Airflow is a plus).\nExperience integrating with third-party APIs, databases, or card transaction systems is a big plus.\nGood communication skills in English, with the ability to work with distributed teams.\nWillingness to attend occasional evening meetings (Vietnam time) for alignment with U.S./India team.\n\nDesired Skills\nExperience with AWS QuickSight for building dashboards and BI reporting.\n\n#Skill requirements\nExcellent English communication skills\nOutstanding teamwork abilities\nProven ability to prioritize and allocate work\nSharp critical thinking and logical reasoning\nEffective problem-solving skills\n\n#Attitude Requirements\nCustomer-centric mindset\nAdaptability to change\nCommitment to continuous learning and growth\n\nBENEFITS AND PERKS\nProfessional, open-minded, and creative environment:\nWork with colleagues who embrace ideas to change the society\nRespect different perspectives within a team\nStrong learning culture that promotes individual development\nThe culture of taking risks to experience and thrive\nFocus on individual development\nBe consulted, accompanied, and supported in career development with the career path system (developing in expertise or management direction) that has been studied and tested for many years.\nBe oriented for individual, group, and organizational goals\nBe empowered\nBe supported to define a 3-month or 6-month goal (Goal Define Support)\nGet access to company Learning Hub online library with various courses provided by Udemy, LinkedIn,…\nSpecial care for employees\nSalary: Negotiable + competitive allowance (lunch, living allowance, beauty care, Japanese and IT certificates, etc.)\n13th-month salary bonus\nPerformance review: Twice/a year\nHybrid working policy; flexible check-in, check-out\nComprehensive health insurance Sun* Care\nSeniority Allowance\nWomen care allowance: Women’s physiological leave: 2.5 hours/month; Postpartum leave for female employees with under 1-year-old children: 1 hour/day\nPolicies supporting learning activities, knowledge sharing, and cultural exchange (Technology Seminar – Tech Expert, Club: Reading, Japanese, Music Club, …)\nAnnual company trip and quarterly team-building activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2022, 1062, 2, 'Bridge System Engineer (HN)', '1. Mô tả công việc\nQuản lý yêu cầu phát triển:\n- Đọc hiểu các tài liệu mô tả yêu cầu khách hàng cung cấp\n- Thực hiện Q&A với khách hàng để xác nhận những yêu cầu chưa rõ ràng\n- Cập nhật lại mô tả yêu cầu phát triển bằng tiếng Việt cho đội ngũ phát triển ( Có thể phối hợp với team comtor để triển khai)\nĐầu mối liên lạc với khách hàng:\n- Phản hồi tức thời khách hàng qua các công cụ như là mail, skype, chatwork, slack\n- Truyền tải những yêu cầu xác nhận của đội ngũ phát triển với khách hàng\n- Truyền tải những thông điệp có liên quan đến việc triển khai dự án với BOD hoặc đội ngũ phát triển\nQuản lý tiến độ dự án \n- Quản lý tiến độ dự án bằng Backlog, WBS, Jira, Release Burndown Chart,...\n- Cập nhật tiến độ dự án định kỳ (hàng tuần,...)\n- Báo cáo tiến độ dự án trong họp dự án toàn công ty\n\n2. Yêu cầu\nKiến thức\n- Có ít nhất 3 năm kinh nghiệm triển khai dự án PHP, Mobile, Java.. cho khách hàng Nhật Bản\n- Hiểu biết về văn hoá, ngôn ngữ, phong cách làm việc của người Nhật \nKỹ năng\n- Tiếng Nhật N2 trở lên, có khả năng để đọc hiểu yêu cầu: 仕様書 機能設計 書, DB設計書,ERD書 và trao đổi trực tiếp với khách hàng\n- HoRenSo hiểu và áp dụng thực tế tốt\n- Quản lý dự án: cập nhật tiến độ, điều chỉnh nguồn lực (nhân lực, tài lực,…) để dự án triển khai suôn sẻ.\n\n3. Quyền lợi được hưởng\nChế độ đãi ngộ:\n- Lương thỏa thuận theo năng lực, upto $2500\n- Nghỉ thứ 7, chủ nhật + ngày lễ, tết + 12 ngày phép/năm, đóng bảo hiểm đầy đủ\n- Xét tăng lương 2 lần/năm, có năng lực sẽ được xét ngay tại thời điểm yêu cầu\n- Lương tháng 13, thưởng dự án tham gia, thưởng các dịp lễ, tết; thưởng giới thiệu nhân sự\n- Khám sức khỏe 1 lần/năm\nVăn hóa và Môi trường làm việc:\n- Môi trường trẻ trung, năng động, thoải mái, tạo điều kiện để cá nhân phát triển năng lực nhất có thể\n- Tham gia các hoạt động thể thao nâng cao sức khỏe, teambuilding du lịch 1 lần/năm; liên hoan dự án,...\n- Góc pantry free trà, cafe,...\nĐào tạo và cơ hội thăng tiến:\n- Công ty tổ chức đào tạo toàn công ty 1 lần/tháng nhằm nâng cao kỹ năng mềm và hiểu biết xã hội\n- Tham gia các khóa đào tạo nội và ngoại nâng cao chuyên môn\n- Cơ hội phát triển lên Division Manager\n- Được học hỏi nhiều kinh nghiệm về Kỹ thuật, quy trình, kỹ năng mềm từ người đi trước\n- Làm việc trực tiếp với CEO, CTO, học hỏi tư duy về quản lý và kỹ năng chuyên môn\n- Định hướng phát triển sự nghiệp theo Career Path của công ty.\n\nThời gian làm việc: 8h00-17h15 (nghỉ trưa 12h-13h15), từ thứ Hai đến thứ Sáu.\nĐịa chỉ làm việc: 61 Ngụy Như Kon Tum (tòa nhà Comatce), Thanh Xuân, Hà Nội.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2023, 952, 2, 'Tester (FCD Team)', 'FPT Smart Cloud is hiring a Tester for the FCD Team to ensure the quality and reliability of AI-powered software products. You will design and execute test plans, collaborate with developers and product teams, and contribute to automated testing frameworks. This role is ideal for detail-oriented professionals who thrive in fast-paced, innovative environments.\n\nAbout FPT Smart Cloud\n\nFPT Smart Cloud (FCI) – a member of FPT Corporation, pioneers AI & Cloud solutions in Vietnam. FCI was founded with the mission to generating an immense leap in productivity and agility in business operations.\n\nFPT Smart Cloud aims at leading the industry by focusing on building a firm technological foundation, developing diversified ecosystem products, and reaching global connectivity.\n\n- Customized to specific needs: Providing cloud-based products and solutions customized to each industry.\n- All-in-one Platform: Consolidating FPT Smart Cloud technology and diverse business solutions all in one platform. AI & Cloud services are a Unify eco-system.\n- Local market leadership: Outstanding Cloud and AI technology infrastructure and platform to help local businesses grow their products and services online.\n- Deliver the future: Help customers achieve business outcomes faster by integrating world-class processes and technology.\n\nKey Responsibilities\n\n- Design, develop and maintain automated test scripts for regression, functional and performance testing using tools like Playwright.selenium, Jest, JMeter,…\n- Integrate automated tests into the CI/CD pipeline to ensure continuous testing\n- Regularly review and optimize test automation frameworks and tools to improve efficiency.\n- Proficient in programming languages like Javascript.java Typescript to write automated testing scripts.\n- Analyze system requirements and design documents to understand business and process.\n- Write test cases and perform functional testing, UI testing, and integration testing on Web and API.\n- Use tools like Postman to test APIs (GET, POST, PUT, DELETE)…\n\nRequirements\n\n- Bachelor’s degree in Computer Science, Information Technology, or a related field.\n- At least 2 years of experience in software testing, with a strong focus on test automation (manual testing experience is also valued).\n- Experience working with cloud platforms such as AWS is a plus.\n- Solid understanding of Agile/Scrum methodologies and QA best practices.\n- Good analytical and problem-solving skills, with attention to detail.\n- Strong communication and collaboration skills to work effectively in cross-functional teams.\n\nTop Benefits\n\n- Salary: Competitive, pay according to ability. Negotiation during the interview.\n- Social insurance and health insurance according to labor laws.\n- Creative, open-minded working environment that respects individuals\n- FPT Premium Care package\n- Activities and culture with FCI and FPT Corporation\n- Study support package for children of FCI union\n- Sponsor related courses and certifications\n\nWorking Environment\n\n- Working Location: Site Hanoi: 7th Floor, FPT Tower, no. 10 Pham Van Bach Street, Dich Vong ward, Cau Giay district, Hanoi.\n- Working hours: 8h30 AM – 12h00 PM, 1h00 PM – 5h30 PM\n- Working days: Monday to Friday (weekends off)\n\nContact Person\n\nPham Thi Ha My (Ms.) – Talent Acquisition Team Lead\n\nEmail: Mypth3@fpt.com\n\nPhone: 0962456194\n\nFPT Smart Cloud (FCI) Co., LTD\n\nAddress: 7th Floor, FPT Tower, No. 10 Pham Van Bach, Cau Giay Dist, Hanoi\n\nWebsites: FPT Cloud | FPT AI\n\n#Tester\n\nXem thêm các vị trí nổi bật khác tại đây: https://fptsmartcloud.com/co-hoi-nghe-nghiep\n\nSend CV', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2024, 1063, 2, 'Cloud Engineer/SRE', 'Position: Cloud Engineer/Site Reliability Engineer\nWe are looking for a skilled Infrastructure Engineer with strong experience in Python, Bash scripting, and deploying cloud infrastructure on AWS or GCP. You will be responsible for automating deployments, managing infrastructure as code, and supporting scalable, secure environments.\n\nKey Responsibilities:\n- Automate infrastructure provisioning using Python and shell scripting.\n- Deploy and manage services on AWS or GCP.\n- Design and maintain CI/CD pipelines, space-lift\n- Ensure system reliability, performance, and security.\n\nRequirements:\n- Proficient in Python and Bash scripting.\n- Hands-on experience with AWS or GCP services.\n- Familiar with infrastructure as code tools (e.g., Terraform, CloudFormation).\n- Knowledge of Docker, Kubernetes, and CI/CD tools (e.g., GitLab CI, Jenkins).\n- Comfortable working in Linux/Ubuntu environments.\n\nBenefits/Opportunity\n- Working in an international, dynamic and professional environment with many opportunities to develop career.\n- Having opportunities of being trained oversea and working directly with oversea customer\n- A stable and rewarding position where your long-term commitment will be highly valued.\n- Technical & Soft skills internal training courses\n- Many company activities (Sport and music festival, TMA Futsal league …) are held aunnually.\n- Competitive salary and bonus.\n- Total Health Care Insurance\n- Loan Fund & Team Building Fund\n\nWorking location: TMA Tower, Quang Trung Software City, District 12, Ho Chi Minh City (Office 6)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2025, 1064, 2, 'Ruby on Rails Developer (Junior/Middle)', 'Oivan is seeking a full-time passionate Ruby on Rails Developer (Junior/Middle) to join our growing Ho Chi Minh City and Danang teams.\n\nWe offer the unique opportunity to work and improve your skills with a diverse and geographically distributed team of technology and business experts around the world. We have offices in Helsinki (Finland), Khon Kaen (Thailand), Bangkok (Thailand), Abu Dhabi (UAE), Riyadh (KSA) and Vietnam.\n\nOur project team uses the Scrum framework via Scrum.org certified Professional Scrum Masters.\n\nWe have flexible hours and hybrid work options with open culture and Nordic management style. Our Nordic spirit and values drive the way we work always.\n\nWhat You Have\n\nMust have \n\n2+ years of experience in the IT field \nBe able to work Saudi Arabia hours (13:00 – 21:00, Sunday to Thursday) \nStrong written and verbal communication skills in English. \nStrong based knowledge in Object-oriented programming. \nBackend experience using Ruby on Rails \nExperience with REST/RESTFUL, JSONAPI \nGood knowledge about Web development \nExperience with SQL databases \nExperience with Git, Git-flow \n\nNice to have \n\nFront-end experience such as Angular, Bootstrap, SCSS \nExperience with other programming languages (Golang, Dart/Flutter, Typescript) \nExperience with Microservices, Kafka, Redis... \nPassion for backend technologies, eagerness to learn new languages and frameworks \n\nWhat We Offer\n\nHybrid work \nMacBook Pro, screen protector, mouse, and headphones \nPremium insurance \nCompany paid team lunch weekly \nTravel opportunity to Oivan international locations and client sites \nInternational team and work opportunities overseas. \nUnlimited premium snacks/healthy food, coffee, and drinks at the office \nSelf-study time and company-sponsored opportunities for development (+2 hours per week) \n15 days annual leave \n10 days of paid paternity leave when having a baby. \n15 sick leaves \nAnnual health checkup \n13th Month Salary.\n\nWho We Are\n\nOivan creates and operates human-centric digital services for our clients worldwide. With offices in Finland, UAE, Thailand, Vietnam and Saudi Arabia, our international team executes a diverse array of projects.\n\nOur international team of digitalization experts manages digital services’ full lifecycle, from design and development to operations and analytics. We are building a fast-growing, transparent, fairness in our teams along with our core values: Responsibility, Fellowship and Reliability. Our commitment to our core Nordic values is reflected in the benefits we offer our workforce.\n\nIf you want to work in a cool environment offering flexibility and attractive benefits, being in the same team with driven and talented geeks, then Oivan is your place!\n\nJoin us now and let us see your talent!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2026, 958, 2, 'Senior Flutter Developer', 'ABOUT ONE MOUNT\nOne Mount is Vietnam\'s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam\'s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nOne Mount Real Estate (OMRE) is a property technology company that provides a comprehensive platform to help customers experience a simple and seamless home buying and selling journey. OMRE is the first company in Vietnam capable of integrating the entire real estate transaction process on a single platform, from online to in-person. In addition, OMRE owns the first home valuation product in Vietnam. Don\'t miss the opportunity to become a member in PropTech field at One Mount Real Estate - A member company of One Mount ecosystem, a strategic partner of the leading bank in Vietnam Techcombank and the investor owns the most sought-after luxury apartments in the market, Masterise Home, Vinhomes.\n\nMAIN RESPONSIBILITIES:\nWe are looking for experienced Senior Mobile Developers (Flutter) to join our high-powered experienced product team who follow agile development principles, and who value well-designed software, creative thinking and thrive on solving the un-solvable. You will be working on technology spanning mobile communications (voice, messaging, email), and fintech/payments all underpinned by strong security and privacy principles.\nThis is a fantastic opportunity to work at a well-established and leading start-up in Vietnam as One Mount Group and you will be part of OMRE - OneHousing team - focusing on building the most complete and trusted platform for buying and selling a home in Vietnam\nResponsibilities\n- Develop quality software and web applications\n- Analyze and maintain existing software applications\n- Design highly scalable, testable code\n- Discover and fix programming bugs\n\nREQUIRED EXPERIENCE AND SKILLS:\n- Bachelor\'s degree or equivalent experience in Computer Science or related field\n- Desire to work in a startup environment, able to self-manage and work remotely.\n- Minimum 5 years of hands-on experience in building and deploying mobile applications using Flutter (Android and/or iOS platforms).\n- Proven experience integrating with third-party libraries, SDKs, and APIs.\n- Working knowledge of the general mobile landscape, architectures, trends, and emerging technologies.\n- Solid understanding of the full mobile development life cycle, including automated testing and building.\n- Experience working in an agile development process.\n- Proficiency with version control (Git) and experience with CI/CD pipelines, ideally using tools such as GitHub Actions, Jenkins, or similar.\n- Write clear, maintainable and testable code that you are proud of.\n- Having published one or more apps to the Google Play Store or Apple App Store is a strong plus.\n\nBENEFITS AND PERKS\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check\n- Laptop, screen and other needed facilities/accounts/tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'Reilly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n- Grow your career with opportunities across the dynamic ecosystem of Techcombank & Masterise Group.\n- Access special loan offers with competitive interest rates and flexible grace period options tailored to your financial needs.\n\nWorking Environment\n- Open & collaborative working space fosters both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms.\n- Personal lockers with QR code access.\n- Quarterly/yearly teambuilding & engaged internal events.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2027, 977, 2, 'Sr. Back-end Developer', 'About The Role\nWe’re looking for a seasoned and passionate engineer interested in joining our early-stage venture as full-time backend developer. In this role, you will build and maintain our product’s backend services, APIs, and deployment, for our global health tech mobile platform.\nIf you are reading this and are internally thinking "that ticks all of my boxes, when can I start?", we want to hear from you, today!\n\nWhat you will get\n- 🧳 Relocation Support - We handle the move, financially and practically\n- 💰 Permanent Global Contract - With a seriously competitive salary\n- 🏥 Private Healthcare - From day one\n- 💻 Top-Tier Tech Setup - Brand new MacBook + full onboarding kit\n- 🧠 Career Growth Framework - Clear, personalised, and fast-moving\n- 🎯 Bonus Scheme - Performance-related, quarterly paid\n- 🌴 14 Days PTO + Public Holidays - Real time off\n- 🧪 Hybrid Working - 3 days in the office per week\n- 🍛 Refreshments - Free Lunch and Dinner every day for you to enjoy\n\nWhat You’ll Do\n- Contribute on a daily basis to the codebase with attention to detail and high quality.\n- Develop solutions to concrete user-facing problems, design and implementation of large software components, systems, and features.\n- Build, test, deploy, maintain, and improve software, specifically APIs used by our native mobile client applications.\n- Being autonomous on managing his/her own project priorities, deadlines, and deliverables.\n- Resolve challenging technical issues.\n- Collaborate closely with teammates and help grow their abilities through technical contributions and mentorship.\n- Contribute to a culture of quality and innovation for our engineering team and across the company.\n\nWhat You’ll Need\n- 8+ years of relevant industry experience\n- Extensive experience in NodeJS, TypeScript a plus.\n- Mastering at least 1 NodeJS framework(Express, MEAN, Hapi, etc...)\n- Experience with a noSQL datastore and data modelling.\n- Experience with DevOps and cloud infrastructure – AWS or GCP – and docker. Familiarity with Google Cloud Platform services are a big plus.\n- Experience in software debugging.\n- Ability to code review and provide feedback on the work of other developers.\n- Experience working in a fast-paced startup environment with quick iteration, continuous deployment, and test-driven development;\n- Excellent communication skills in English (professional and personal fluency); Vietnamese is a plus.\n- Positive attitude and willingness to roll up sleeves and dig deep to achieve goals;\n- Strong bias for action - you know we have a lot to deliver and you can help us get there.\n\nWhy join Elfie\nWe\'re a global start-up that is mission-led, and fiercely product-driven.\nWe\'re building something that improves lives - and we\'re doing it with a culture of trust, freedom, and high performance.\n\nAbout Elfie\nElfie is the first completely free, gamified mobile app that rewards users for managing their health. Our goal? To become the world’s largest self-reported medical record platform — across all therapeutic areas.\nWe operate in 10+ countries today, with plans to expand into 15 by the end of 2025.\n\n📲 Try Elfie for yourself by downloading it on the App Store or Google Play.\n\nWhat Now?\nApply today for immediate consideration! Got someone in mind? We offer a referral reward if your recommendation is hired. Contact Talent Acquisition for more info.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2028, 1065, 2, '[BGSV] Woman Leadership in Tech', '🎯 Company Information\nBosch Global Software Technologies Vietnam Company Limited (BGSV) is 100% owned subsidiary of Robert Bosch GmbH. BGSV has started its operations from 19th October, 2010 at e-Town2 in HCMC. This engineering development center will be engaged in developing embedded systems and software, mechanical design and simulation, and will provide IT (SAP Consulting, JAVA Development….) and Business Services (Finance and accounting, Economics, Purchasing, Logistics, Translations Japanese-English-Japanese, Information Security ) solutions to the Bosch group of companies globally.\n\n🔥 Ignite your Impact: Woman Leadership in Tech 🔥\nAre you a woman in tech looking to lead, inspire, and grow? Or perhaps you\'re passionate about fostering diversity and elevating woman leadership in engineering and software development? Let’s connect!\nAt Bosch, we\'re not just building cutting-edge technologies—we’re building the future of leadership, and we believe woman will be at the forefront of that transformation. We’re empowering and promoting woman in leadership roles in Engineering and Software Development.\nWe’re reaching out to ambitious, driven, and purpose-led woman in tech - and their allies - who are ready to shape what comes next. This is more than an opportunity - it’s a call to connect, grow, and lead!\n\n🤝 We\'re especially excited to engage with professionals who:\n- Inspire and develop teams with a focus on collaboration, diversity, and inclusion\n- Drive business growth by turning technical expertise into regional strategies\n- Lead software projects from planning to delivery, with excellence and impact\n- Stay hands-on and future-focused through emerging tech and product evolution\n- Collaborate effortlessly with cross-functional stakeholders to align on big goals\n- Champion process improvement to boost engineering excellence and team performance\n\nWhether you’re stepping into leadership or already creating waves, we’d love to build something meaningful with you. Let’s create a space to share insights, lift each other up, and lead the tech industry forward—together.\n\n🎯 What\'s in it for you\n- Mentorship & Coaching from inspiring woman leaders\n- Networking Opportunities with like-minded professionals\n- Access to Exclusive Resources designed to grow your leadership capacity\n- Thought Leadership Events, workshops, and webinars\n- Real Conversations about navigating and thriving in today’s workplace\n\n🌈 Why Bosch\nBecause we don\'t just follow trends, we create them.\nBecause together we turn ideas into reality, working every day to make the world of tomorrow a better place.\nAt Bosch, you’ll discover:\n- A company named one of Vietnam’s Best Places to Work\n- A global, innovation-driven environment\n- A workplace that supports technical excellence & personal well-being\n- An unwavering commitment to mentorship, growth & inclusion.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2029, 225, 2, 'Lead/Consultant ReactJS Engineer (Hanoi)', 'We are seeking passionate, results focused Senior/Consultant ReactJS Engineers to take accountability for the design and delivery of NABs transformed digital platforms. You will be part of our delivery team and will be responsible for providing technical contribution throughout all phases of the software delivery life cycle as we initiate a transformation of NAB technology.\n\nYour Job Responsibilities\n\n1. Design, develop, review, implement, and manage ReactJS application code and services for the production and pre-release environments;\n2. Design, develop, review, implement, and manage continuous integration, build management and deployment scripts, systems, and any code as required;\n3. Participate in Agile software development, prototyping, and code review with international development teams to build scalable Microservices-based products;\n4. Understand the requirements of the customer or business and utilize this knowledge to develop applications that are consistent with this;\n5. Work with delivery teams to achieve success through development using CI/CD and DevOps practices, processes, and tooling;\n6. Provide robust coding practices, solid unit/component test coverage, and debugging code.\n\nYour Experience & Qualifications\n\nMust have:\n1. +5 years’ experience working in Software Development​.\n2. Solid experience in JavaScript ES6/TypeScript working with ReactJS and nice to have React Native experience or NodeJS experience\n3. Solid experience in all areas of web development (HTML5, CSS3, Bootstrap, Foundation, JQuery, JSON) including accessibility and security concerns\n4. Solid experience in modern front-end build pipelines and tools (e.g. Git, Webpack, Gulp, NPM)\n5. Experience in using front-end testing and test runners (eg. Mocha/Chai/Jest).\n6. Good experience in Agile (Scrum model) development environments\n7. Well-versed in writing structured, well-documented, maintainable, and clean code\n8. Excellent in problem-solving and analytical skills\n9. Good English communication skills (both verbal & written), especially in the global software development environment.\n\nShould have:\n1. Experience in Cloud computing such as Amazon Web Services (AWS), Google Cloud Platforms (GCP), or Azure Microsoft\n2. Experience in setting up, using, or configuring CI/CD pipelines and tools (e.g. Git, Ansible, Jenkins, Gulp, NPM, Gradle..)\n3. Understanding of RESTful APIs design (GraphQL desirable) and Microservices-based systems\n\nThe benefits and perks: \n1. Very competitive remuneration package\n2. Generous private family healthcare for yourself and two family members\n3. A solid team behind you - great people who love what they do\n4. The pleasant, enthusiastic, international work environment\n5. Opportunity for traveling & training in Australia\n6. A brand new & state of the art Agile office\n7. Latest technologies, flexible working hours\n8. A promising training and career path\n9. Fun team activities & outing\n10. English learning with native English teachers', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2030, 751, 2, 'Senior Fullstack Developer (.NET + React)', 'Company Description\n\nTechnology is our how. And people are our why. For over two decades, we have been harnessing technology to drive meaningful change.\n\nBy combining world-class engineering, industry expertise and a people-centric mindset, we consult and partner with leading brands from various industries to create dynamic platforms and intelligent digital experiences that drive innovation and transform businesses.\n\nFrom prototype to real-world impact - be part of a global shift by doing work that matters.\n\nJob Description\n\nDevelopment is the largest discipline at Endava. Our developers design, build, and release software products in multiple programming languages, frameworks, and libraries. Always collaborating with cross-functional project teams, our developers are adaptable problem-solvers with a client-oriented mindset.\n\nAs a Senior Developer at Endava, you are responsible for implementing and delivering high-quality software products using Agile Scrum methodology. As a part of a global project, you can contribute your technical expertise and experience in order to the project succeed.\n\nQualifications\n\nResponsibilities:\n\nYou will be challenged to work alongside passionate individuals, who always strive to continuously improve and who share the same vision on what "done" work signifies.\nYou will be a member of a team that interacts frequently with the client and the team members from other locations.\nYou will work in an agile environment, closely with the business team in order to understand what the product is supposed to do and what its key features are.\nYou will be involved in both supporting the team to build a product that brings value to our client and in verifying that the product works as expected.\nAs a Developer on the team, you will be implementing requirements using the best technical solutions available. In order to implement the best solutions, you will need to be well informed of the latest technologies and trends in front-end development.\nYou will solve complex technical problems that other team members may encounter, be an integral part of a Scrum team.\nYou will be exposed to a variety of challenges, from technical solutions and design to improving service delivery from an end-to-end perspective.\nParticipates in the review of the work done by development team members.\nLearns and applies new technologies, practices, and tools as appropriate to the project.\n\nMandatory skills:\n\nAt least 5+ years of experience in fullstack development, with proficiency in React for frontend and strong expertise in C# and Entity Framework for backend development.\nGood understanding of UX best-practices.\nExperience using GitHub to manage code and tasks.\nUnit/integration testing.\nFollow design principles & patterns (Atomic, SOLID, dependency injection), quality standards.\nGood communication in English, client facing skills.\nAbility to independently manage tasks and drive projects forward.\nStrong skills in learning and retaining domain knowledge to enhance project efficiency.\nCapable of making progress even with imperfect or partial knowledge of requirements, demonstrating adaptability and problem-solving skills.\nGood communication in English.\n\nDesired skills:\n\nExperience with Redux, TanStack Query, or Styled Components for frontend enhancements.\nKnowledge of .NET Core Minimal APIs and Microsoft SQL Server for backend.\nFamiliarity with Python is a plus.\nAgile processes knowledge and experience\nTime management skills, embracing change.\nAbility to coach others.\n\nAdditional Information\n\nDiscover some of the global benefits that empower our people to become the best version of themselves:\n\nFinance:\nCompetitive salary package, share plan, value-based recognition awards, referral bonus;\nCareer Development:\nCareer coaching, global career opportunities, non-linear career paths, internal development programmes for management and technical leadership;\nLearning Opportunities:\nComplex projects, rotations, internal tech communities, training, certifications, coaching, online learning platforms subscriptions, pass-it-on sessions, workshops, conferences;\nWork-Life Balance:\nHybrid work and flexible working hours, employee assistance programme;\nHealth:\nGlobal internal wellbeing programme, access to wellbeing apps;\nCommunity:\nGlobal internal tech communities, hobby clubs and interest groups, inclusion and diversity programmes, events and celebrations.\nAnnual leave encashment;\n13th month salary;\nPremium annual health check & Extra health & accident insurance;\nWelcome kit and gift-giving frequency;\nAttractive benefits of Trade Union;\nExciting English programme.\n\nAt Endava, we’re committed to creating an open, inclusive, and respectful environment where everyone feels safe, valued, and empowered to be their best. We welcome applications from people of all backgrounds, experiences, and perspectives—because we know that inclusive teams help us deliver smarter, more innovative solutions for our customers. Hiring decisions are based on merit, skills, qualifications, and potential. If you need adjustments or support during the recruitment process, please let us know.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2031, 1066, 2, '[ONSITE PROJECT] .NET DEVELOPER', 'AHT TECH là công ty đa quốc gia cung cấp giải pháp tư vấn công nghệ toàn diện tập trung vào ngành Thương mại và Trải nghiệm Số hàng đầu Việt Nam. Thành lập từ 2007, chúng tôi hiện có nhiều chi nhánh và văn phòng đại diện ở Việt Nam, Malaysia, Thái Lan, Nhật Bản, Mỹ, Đức, Singaprore & Úc. Tự hào là môi trường làm việc năng động có nhiều cơ hội phát triển, hiện tại AHT Tech đã trở thành mái nhà của hơn 400 nhân sự trên khắp thế giới.\n\nChúng tôi hy vọng bạn sẽ gia nhập AHT Tech để cùng làm việc và gắn bó lâu dài, góp phần vào sự phát triển của công ty và cũng kỳ vọng bạn sẽ trở thành những thành viên trụ cột của công ty trong tương lai.\n\nMÔ TẢ CÔNG VIỆC\n- Phát triển và bảo trì các ứng dụng Web sử dụng C# .NET\n- Tham gia vào quá trình thiết kế, xây dựng và tối ưu hóa hệ thống Web App\n- Làm việc với cơ sở dữ liệu SQL Server\n- Phối hợp với các thành viên trong nhóm để đảm bảo tiến độ và chất lượng dự án\n- Xử lý lỗi, tối ưu hiệu suất và cải thiện trải nghiệm người dùng\n- Thực hiện các công việc khác theo yêu cầu của Manager\n\nYÊU CẦU CÔNG VIỆC\n- Tốt nghiệp Đại học chuyên ngành CNTT/Hệ thống thông tin quản lý hoặc các chuyên ngành khác liên quan\n- Có kinh nghiệm tối thiểu 3 năm về lập trình các ngôn ngữ bằng C# .Net, .NetCore, JavaScript. Lập trình Web API, MVC\n- Thành thạo với cơ sở dữ liệu Oracle\n- Kỹ năng tốt về HTML5, CSS, Restful, Json\n- Kỹ năng tốt về thiết kế giao diện responsive\n- Kỹ năng làm việc độc lập và theo nhóm tốt.\n- Kỹ năng tư duy logic và giải quyết vấn đề tốt.\n- Kỹ năng viết tài liệu tốt\n- Có kinh nghiệm làm việc với SVN\n- Có kinh nghiệm sử dụng tool Profiler .NET\n\nQUYỀN LỢI CỦA BẠN\nBạn sẽ được\n- Mức lương cạnh tranh theo năng lực\n- Review performance theo lộ trình công ty 2 lần/năm\n- Được tư vấn, định hướng về career-path rõ ràng\n- Tham gia các chương trình đào tạo nội bộ nâng cao năng lực tại công ty\n- Môi trường làm việc cởi mở, trẻ trung, thân thiện, nhiều cơ hội thăng tiến trong công việc, cùng học hỏi với đồng nghiệp trẻ trung, tài năng\n- Thời gian làm việc: 8h30-18h, Thứ 2 - Thứ 6 (Theo lịch làm việc khách hàng)\n\nCùng với chế độ\n- Hưởng đầy đủ các chế độ BHXH, BHYT, BHTN cho CBNV theo quy định của Pháp luật\n- Khám sức khỏe định kỳ 1 lần/năm tại các bệnh viện quốc tế\n- 12 ngày nghỉ phép nguyên lương/năm và 1 ngày nghỉ phép sinh nhật\n- Tham gia nhiều hoạt động được tổ chức trong năm: New Year/Year End Party, Company trip, Sinh nhật công ty, Happy hour,...\n- Tham gia nhiều hoạt động thiện nguyện, hoạt động tập thể sáng tạo, các giải phong trào nội bộ (Giải games, giải chạy, đá bóng, cầu lông,...)\n- Có cơ hội training nội bộ nâng cao kỹ năng chuyên môn, kỹ năng mềm và ngoại ngữ (Anh/Nhật/...)\n- Có cơ hội học và thi các chứng chỉ chuyên môn do công ty tài trợ\n\nĐỊA ĐIỂM LÀM VIỆC\nVăn phòng đối tác (Onsite): Dịch Vọng Hậu, Cầu Giấy, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoj a okolí', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2032, 899, 2, 'Manual Tester', 'We are looking for a thorough Software Tester. You will ensure that newly developed products are ready to perform and result in repeat clientele.\n\n- Design independent test cases for each newly developed application.\n- Provide feedback to developers about automated testing strategies, design fixes, and patches.\n- Perform system load tests for new products.\n- Manage and train apprentices, junior testers, and new testers\n- Work with other quality technicians to document the quality processes for replication in other locations.\n- Manage testing projects during each phase, according to the Software Development Life Cycle (SDLC).\n- Make improvements to functionality, design, and usability of new products.\n\nRequirements\n- Min 3 years of experience as a Software Tester.\n- Solid understanding of the software development lifecycle.\n- Hands-on experience with functional testing, integration testing, regression testing, mobile testing, big data testing, cross platform testing, component testing, security testing, performance testing, UI/UX testing, A/B testing.\n- Experiences with test Wechat Mini Program\n- Fluent in English (Speaking skill)\n\nCompensation & Benefits\n🎯Flexible working regime and health care:\n- Flexible timekeeping (from 8:00 - 9:00 to 17:30 - 18:30) \n- Minimum 14 paid leaves per annum for all employees after probation\n- 01-day remote work per month\n- A flexitime allowance of 90-180 minutes per month for employees\n- 01 hour paid leave per day for women having children under 12 months\n- Social insurance, health insurance, unemployment insurance and MIC care insurance \n\n🎯Transparent And Fair Benefits\n- Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n- Work performance review 2 times/ year (in April and October)\n- 13th-month salary\n- Bonus Policy: Public holidays (2/9, 30/4, 1/5, 1/1,...); Personal Performances; Excellent Team; Performance bonus in Token of the project;.. \n- Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company\n\n🎯Dynamic Environment And Open Culture\n- Year-end party, sports day, yearly company trip and quarterly team building,...with a generous budget\n- Socialize with colleagues through monthly Happy Hour \n- Monthly allowance when joining clubs: Soccer, Swimming, Yoga, Music,... \n- Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks,...\n- Flat, open and sharing culture with friendly management team; outsourcing company with product mindset \n\n🎯Strong Learning Culture\n- Free training courses for technical and soft skills (presentation skills, communication skills, foreign language courses,...)\n- Account to log in to our online learning system, which contains thousands of valuable lectures (LMS)\n- Participate in workshops, seminars, tech talk,... with sharing from experts inside and outside the company\n- Working opportunities with technical gurus who built and operated world-class applications with millions of users.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2033, 1067, 2, 'Bridge & Lead Software Engineer (Cloud & Client App)', 'FUJIFILM Business Innovation is strengthening the development of cloud service and software to transform to a solution services company. As many of the projects are large-scale and require development using the latest technology, you can improve your skills and realize great results upon completion of the project.\n\nObjective: Development and maintenance of some cloud services or software. Some of its modules will be implemented as a FUJIFILM Business Innovation common cloud service platform.\n\nJob Responsibilities: The responsibility of the Bridge & Lead Software Engineer is to summarize tasks of engineers and lead the project (Technical lead) and take the bridge software engineer between the Vietnamese team & Japanese development department side.\n\nJob Description:\n- You will be developing and maintaining cloud service-related software or windows application software that operates MFP (Multi-function printer) data handling or IT devices (e.g. PC, Server, Mobile, …) management as a cloud service platform.\n- Debugging and evaluation for MFP related cloud service or software will be conducted using either actual devices or simulators.\n- The ultimate role of a Bridge & Lead Software Engineer is to build high-quality, correctly functioning software in compliance with coding standards.\n- Lead the development planning, operation, and quality assurance of the project.\n\nYour Skills and Experience:\n- Work Experience: At least 3 years of management experience as lead & bridge software engineer in software development and at least 5 years of experience of software engineer.\n- Language Proficiency: Japanese language proficiency at least N2 level or higher, and English intermediate - spoken, listening, and written. Working experience with Japanese clients will be preferable.\n- Ability to actively communicate and collaborate with colleagues and supervisors.\n- Having the motivation to work for a long period (10 years or more), as a founding member of the company.\n\nEducation/Academic Qualifications:\n- Bachelor’s degree in computer science, or a related field, or equivalent experience.\n- Relevant technology certifications.\n\nWhy You\'ll Love Working Here:\nTop 3 reasons to join us:\n1. Become a Founding Member of a new Software Development Center in Vietnam to be established by one of the leading MFP manufacturing companies in Japan. Founding members have opportunity to join software development training in Japan.\n2. A job that offers long-term stable growth opportunities.\n3. Working at FUJIFILM Business Innovation Vietnam, you can find your life and work fulfilling at an ‘interesting’ company.\n\nWhy FUJIFILM Business Innovation Vietnam:\nAt FUJIFILM Business Innovation, we aim to be a company with a good balance of all three attributes:\n- We, FUJIFILM Business Innovation build a ‘strong’ company delivers excellent products and services that satisfy customers and are able to reward its shareholders continuously.\n- FUJIFILM Business Innovation is a ‘kind’ company to contribute to local and global communities in terms of environmental conservation, ethical behavior, and social contribution.\n- Working at FUJIFILM Business Innovation, you can find your life and work fulfilling at an ‘interesting’ company with professional training courses and working environment.\n\nPrivacy: \nPersonal data provided to FUJIFILM Business Innovation Vietnam will be collected and used to consider potential future employment opportunity with us. By applying for this position, you agree that you have read, fully understood and agree with respective FUJIFILM Business Innovation Vietnam\'s Privacy Policy - Privacy Policy | FUJIFILM Business Innovation | Vietnam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Distrito Thu Duc, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2034, 552, 2, 'Back End Developer', 'Jitsu is a Silicon Valley based company which provides e-commerce and traditional businesses with a logistics service to deliver their products directly to customers’ doorsteps within a day, without the typical cost and complexity of expedited shipping. Our proprietary technology and processes provide scalable same-day and next-day delivery services to some of the world’s fastest growing brands. Jitsu’s services are live in eight major metropolitan areas with many more on the way.\n\nWe are looking for Senior Backend Engineers with expertise in Java, working in our Hanoi office.\n\nWhat you will do:\n1. Backend Development:\n- Design, develop, and maintain high-performance, scalable backend systems using Java, Golang, or Rust.\n- Ensure system reliability and distributed performance to support growing business demands.\n\n2. Optimization & Scalability:\n- Solve complex combinatorial optimization problems using effective algorithms and local search techniques.\n- Identify and optimize performance bottlenecks in backend services and distributed systems.\n\n3. System Integration:\n- Work with both SQL and NoSQL databases to design efficient and reliable data storage solutions.\n- Integrate and manage message brokers like RabbitMQ or Kafka for asynchronous communication.\n\n4. Caching Strategy:\n- Apply distributed caching systems and caching policies to improve system latency and scalability.\n\n5. Existing Code Understanding:\n- Quickly comprehend and enhance existing codebases with a focus on maintainability and scalability.\n\n6. Business Acumen & Collaboration:\n- Translate complex business requirements into scalable and practical technical solutions.\n- Work closely with cross-functional teams (PMs, FE devs, QA) and clearly communicate both technical and business considerations.\n\nWhat you will need:\n1. Technical Expertise:\n- Strong experience in Java or familiarity with Golang or Rust is a plus.\n- Proficient in backend system design, distributed architecture, and working with SQL/NoSQL databases.\n- Familiar with distributed caching systems and message brokers (e.g., Kafka, RabbitMQ).\n\n2. Optimization & Problem Solving:\n- Solid understanding of combinatorial optimization and local search techniques.\n- Proven ability to analyze and solve complex technical problems at scale.\n\n3. System Design & Code Review:\n- Experience in designing scalable distributed systems and conducting high-quality code reviews.\n\n4. Adaptability:\n- Comfortable with legacy systems and progressively improving large, complex codebases.\n\n5. Communication:\n- Strong communication skills, with the ability to explain technical concepts clearly to both technical and non-technical audiences.\n\n6. Preferred Experience:\n- 5+ years as a backend engineer or similar role.\n- Hands-on experience with high-performance, large-scale distributed systems.\n\nThe Opportunity:\n- Become a key part of the core global team that architects and develops Jitsu’s logistics and operations systems, which orchestrate the delivery of millions of shipments per year\n- Drive innovation and performance improvements in our operations technologies (sortation, routing, fleet management, order management)\n- Drive improvements in our system architecture, performance, quality, and reliability\n- Contribute to team development standards, conventions, and processes\n- Collaborate with peers in product management, transportation, operations, and client success to develop new features and applications\n- Be part of a well-funded, fast-growing company tackling complex and relevant challenges\n- A lot of chances to learn about new technologies\n\nWhy Jitsu:\n- Flexible working hours, Monday to Friday\n- 100% salary in probation\n- 100% salary social insurance contribution\n- Premium health care insurance for you (we\'re using Bao Viet insurance)\n- 12 days of Annual leave + 05 days of Sick leaves covered by the Company + 12 days working remote per year\n- 13th month salary upon company\'s performance and your working time of the year\n- Competitive compensation\n- Macbook pro + extra monitor + other devices needed\n- A lot of engagement activities: Happy team lunch, Monthly birthday party, Summer trip, Year-end Party,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2035, 910, 2, 'Chief AI Engineer & Startup Founder | June Cohort', '🌟 About Antler:\nWe are a global early-stage investment firm that invests in startups from day zero. We provide funding, mentorship, and a global network to help you build and scale your startup. With Antler, you’ll have access to the resources you need to turn your vision into reality—whether you\'re still ideating or already building an existing startup.\n\n👩‍💼 Who are we looking for?\nNote: This ad is not for a job, but rather for the opportunity to build your own VC-backed startup through a 10-week program with Antler.\nExperts in machine learning, deep learning, and artificial intelligence with a passion for solving complex problems.\nIndividuals who have developed and scaled AI-driven products from the ground up.\nTechnically skilled professionals who excel at communicating complex ideas and leading cross-functional teams.\nPeople who stay ahead of the curve, leveraging cutting-edge AI technologies to create groundbreaking solutions.\nSelf-starters and is driven to launch and grow a world-class AI-powered company.\n\n📋 Details of the program:\nThe program runs for an initial 10 weeks, full-time in Ho Chi Minh City (Vietnam) and starting on 21 July 2025, where you are required to ideate and find your co-founder(s) from the cohort of 60-70 founders.\nAfter two months you will present your team and business idea to the Antler Investment Committee. If accepted, you will receive a pre-seed investment of $120K USD for 12% equity, non-negotiable.\nIf you get an investment, you will continue to be part of the program for another 3 months during which Antler will work closely with you to accelerate your growth. At the end of this period, Antler arranges a demo day where we invite VCs, institutional investors, and local angel investors to help you connect with investors and raise your seed round.\n\nFor more details on what to expect 👉 https://www.linkedin.com/smart-links/AQGwMqMCzPe68Q \n\nBenefits:\n💵 Potential investment at the pre-seed stage\n🤝 Help finding your co-founder(s)\n👨‍🏫 Personalized coaching sessions with business experts\n🛫 Relocation grant of $2,000 if you\'re relocating from overseas to HCMC, Vietnam\n🏬 Shared office space at a premium co-working space with access to various amenities\n🌍 Access to a global network of start-up advisors and experts in their field\n\nSome examples of successful companies that were built as a result of Antler’s program, received pre-seed investment from Antler, and gone on to raise substantial investment are:\nXailient - the World’s fastest Computer Vision AI\nBUYO - Pioneering bioplastics and material tech\nSKYQRAFT - Affordable and safe powerline inspections with drones and AI\nAiralo - The world’s first eSIM subscription and top-up store\nhomebase - Making home ownership accessible\nReebelo - Circular economy for e-devices\n\nReady to help shape the future of the world? Apply now to Antler and together we will build something truly amazing ✨', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2036, 797, 2, 'Software Engineer (C++)', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.\n\nThe Position:\nWe are looking for hands-on C++ Developers to join our growing R&D and Product Engineering team. The candidate will work in a talented team to build OPSWAT\'s famous MetaDefender product as world\'s advanced next generation cyber security platforms.\n\nWhat You Will Be Doing:\n- Design, develop, implement and test OPSWAT MetaDefender product using C++ in Windows and/ or Linux environment. \n- Provide inputs for documentation of new or existing programs. \n- Partner with Scrum team members on delivering Sprint commitments. \n- Collaborate with Product Management on product requirements. \n- Participate in receiving and giving peer code reviews.\n\nWhat We Need from You:\n- Strong command of C++. \n- Windows/ Linux development experience. \n- Experience with Qt framework. \n- Experience with DBMS like SQLite, PostgreSQL, etc. \n- Excellent object-oriented design & programming skills in multi-threaded applications. \n- Good coding and debugging skills. \n- Excellent verbal and written communication skills. \n- Must be self-motivated and have a proven ability to work well in a fast-paced team. environment.\n\nIt Would Be Nice If You Had:\n- Experience designing/interfacing with applications with REST API. \n- Experience with Agile / Scrum working environment. \n- Experience with Git, Bitbucket, Jira, Confluence, TeamCity. \n\nOPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws.\nRecruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2037, 880, 2, 'Freelance Software Developer (Golang) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Generate prompts that challenge AI\n- Define comprehensive scoring criteria to evaluate the accuracy of the AI\'s answers\n- Correct the model\'s responses based on your domain-specific knowledge\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields.\n- You have at least 3 years of professional experience with Golang\n- Code review experience is a must\n- Experience with AI projects is a plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2038, 814, 2, '[iKame Games] Unity Game Developer', 'Location: Hà Nội\nSalary: Up to $2000\nExpiration date: 30/06/2025\nMÔ TẢ CÔNG VIỆC\n- Project Manager của sản phẩm mình phát triển:\n- Xây dựng và phát triển các dự án Game mobile trên nền tảng Unity cho Android và iOS.\n- Phối hợp trực tiếp với các thành viên Product (GD, Artist, Tester, Animator,...) và bộ phận Marketing (UA), Business Intelligent, Monetize để phát triển, vận hành và tối ưu sản phẩm.\n- Tò mò, thích học hỏi để nghiên cứu công nghệ mới nhằm cải thiện và nâng cao Game Quality (ANR, Crash, Ingame Metrics, Performance....).\n- Theo dõi và bám sát hằng ngày sự thay đổi của các chỉ số vận hành sản phẩm: Retention, Impressions, Engagemnet Time, ARPU...\n- Cùng team phân tích, nghiên cứu thị trường nhằm đánh giá, chủ động đưa ra ý kiến, tìm kiếm idea game tiềm năng trên Android & iOS.\n- Sáng tạo ý tưởng, đưa ra giải pháp tối ưu hóa cho các tính năng mới trong sản phẩm/ trong cách làm.\n- Tham gia quá trình xây dựng team dev; chia sẻ và cùng phát triển chuyên môn các bạn dev của công ty.\nYÊU CẦU CÔNG VIỆC\n- Đối với TTS - Fresher: Tối thiểu 6 tháng hiểu biết về Unity; hiểu biết về UI Canvas, Physic, Particle System, Optimization;... và ưu tiên đã có sản phẩm.\n- Đối với Junior trở lên: Thành thạo C# & Unity.\n- Biết Mirror hoặc Photon là một lợi thế.\n- Có nền tảng tư duy thuật toán, cấu trúc giải thuật, tư duy logic tốt.\n- Yêu thích làm game và chơi game.\n- Khả năng tư duy và sáng tạo tốt.\n- Có trách nhiệm cao trong công việc, thái độ cầu tiến và thích thử thách công nghệ khó, ham học hỏi công nghệ mới.\n- Có khả năng đọc hiểu tài liệu bằng Tiếng Anh là một lợi thế.\nQUYỀN LỢI\n- Mức lương lên tới 50.000.000VNĐ theo level, review lương 2 lần/năm\n- Thưởng LINH HOẠT & HẤP DẪN: Thưởng Lễ, Thưởng Tết dương tháng lương 13, Thưởng nóng, Thưởng hiệu quả kinh doanh 6 tháng/ lần N tháng lương theo doanh thu sản phẩm và theo mức độ đóng góp vào dự án\n- Trợ cấp ăn trưa 1 triệu đồng/ tháng\n- Cơ hội tham gia và xây dựng dự án game casual hướng tới CHẤT LƯỢNG và GHI DẤU ẤN – cơ hội phát triển và cơ hội thăng\n- Được học hỏi, được thử sai, được đưa ý kiến để rèn luyện bản thân và trau dồi kinh nghiệm thực chiến với việc hỗ trợ 30-100% chi phí các khóa học mọi kỹ năng\n- Môi trường thân thiện, trẻ trung, hiện đại, văn phòng đẹp xịn xò view cửa kính toàn thành phố\n- Con người là số 1 - bạn sẽ được quan tâm từ trang thiết bị làm việc, bữa ăn xế chiều, tới chỗ ngủ, từ tủ đầy đồ ăn vặt tới bàn bia, bi-lắc, PS4 xả não, thư viện cho những tâm hồn yêu thích đọc sách\n- Các chế độ đãi ngộ khác như khám sức khỏe, teambuilding, du lịch... đều được đảm bảo\n- Giờ làm việc 8:30 - 18:00 từ thứ 2 tới thứ 6; ưu tiên sự linh hoạt và chủ động quản trị hiệu suất; cân bằng cuộc sống - công việc\n- Còn gì nữa? Hãy cùng chúng mình khám phá và cùng xây dựng văn hóa iKame để phát triển từng cá nhân nhé!\nCÁCH THỨC ỨNG TUYỂN\n💌 Ứng viên gửi CV về email: recruitment@ikameglobal.com\n➡️Hotline: 0246 281 6688 | HR Department\n➡️Head Office: Tầng 9 & 10 tòa Peak View, số 36 Hoàng Cầu, Ô Chợ Dừa, Đống Đa, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2039, 711, 2, 'Data Engineer', 'Our company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n\nDesign, build, and manage scalable and efficient ETL/ELT pipelines.\n\nDevelop and maintain data architectures (e.g., databases, data lakes, data warehouses).\n\nWork with structured and unstructured data from multiple sources.\n\nOptimize data delivery and ensure data quality, security, and governance.\n\nCollaborate with data scientists, analysts, and other stakeholders to understand data needs.\n\nWhat you’ll bring\n\nBachelor’s degree in Computer Science, Engineering, or a related field.\n\nStrong experience with SQL and relational databases (e.g., PostgreSQL, MySQL).\n\nProficiency in data processing frameworks and languages (e.g., Python, Spark, Scala).\n\nExperience with cloud platforms (e.g., AWS, GCP, Azure) and services (e.g., S3, Redshift, BigQuery).\n\nKnowledge of data warehousing concepts and tools (e.g., Snowflake, Databricks, DBT).\n\nFamiliarity with data orchestration tools (e.g., Airflow, Luigi).\n\nFluent in English communication\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion\n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow we look after you\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2040, 1054, 2, 'Embedded Linux Engineer', '1. INTRODUCTION\nFounded in 2010, Ban Vien Corporation has embarked on an inspiring journey, evolving into a trusted technology partner that has left an indelible mark in the realm of software development and embedded system development. Today, our influence extends both domestically and internationally, showcasing our commitment to driving digital transformation. At Ban Vien, we relentlessly pursue innovation across diverse industries like Edutech, Fintech, Retail, Automotive, Smart IoT, and Logistics. Our comprehensive services span Digital Consulting, R&D, Software Development, and Dedicated Development Centers. This global expansion includes valued clients and esteemed partners in the United States, Germany, Japan, Singapore, China, Hong Kong, Thailand, Malaysia, and Vietnam.\n\n2. REQUIREMENTS\n• Bachelor’s Degree or above in Electronic Engineering, Telecommunication, Computer Science, Computer Engineering, Automation, Information Technology or equivalent.\n• Strong proficiency with C/C++.\n• Experience with firmware/driver programming/debugging.\n• Proficiency with Linux OS, FreeRTOS, Linux kernel.\n• Familiar with BSP.\n• Familiar with Scripting language, Multimedia frameworks & Audio/Video codec, Graphics libraries and Image processing, HW manual & Schematics reading.\n• Capable of reading and understanding MCU/SOC hardware manual.\n• Leading skill, Teamwork skill, Investigation skill, Self-control.\n• Web-Platform (HTML5, Firefox, Gecko).\n\n3. COMPANY BENEFITS\n• 13th Salary + Performance Bonus.\n• Pass probation Bonus.\n• Premium healthcare insurance benefits (PVI Insurance package) and family medical benefit (based on the level of experience).\n• Provide the famous e-learning platform-Udemy, to encourage continuous learning to adapt to the T-shape model.\n• Flexible working time: only 8 hours required as continual working-time at the office.\n• Annual leave up to 17 days: 12 days paid leave + 5 days’ sick leave.\n• Professional and Personal Development Training Programs.\n• 4 Stars standard company trip in summer and a big annual Year-End-Party.\n• Coffee and snacks provided.\n• Holiday celebrations and parties for team members and family.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2041, 1068, 2, 'AI Engineer', '[Hà Đông] Theta Universe Media tuyển dụng AI Engineer\n\nMô tả công việc:\n- Nghiên cứu và đề xuất công cụ AI\n- Thử nghiệm và đóng gói giải pháp AI\n- Theo dõi và đảm bảo tiến độ ứng dụng AI\n- Đóng gói và triển khai sản phẩm AI cho khách hàng\n- Báo cáo và đánh giá\n\nYêu cầu:\n- Tốt nghiệp đại học ngành Công nghệ thông tin, Khoa học máy tính...\n- Có kinh nghiệm làm việc với các công cụ và giải pháp AI\n- Ưu tiên có kinh nghiệm làm việc trong các dự án triển khai AI là một lợi thế\n- Kỹ năng nghiên cứu và phân tích tốt, khả năng đề xuất giải pháp công nghệ sáng tạo.\n\nQuyền lợi:\n- Lương: 15 - 25 triệu tùy năng lực\n- Thời gian làm việc: Full-time, từ Thứ 2 - Thứ 6, thứ 7 nghỉ cách tuần.\n- Địa điểm: Tòa GTC, Galaxy 6, Tố Hữu, Hà Đông, Hà Nội\n\nCách thức ứng tuyển\nGửi CV về email: hr@thetamedia.com.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Đông district, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2042, 1069, 2, '[HCM] Fullstack Laravel | Negotiable', '1. RESPONSIBILITY\nYour responsibilities:\n- Analyze requirements, come up with adequate technical design, and maintain technical documentation\n- Write clean and maintainable code using engineering best practices\n- Conduct code reviews\n- Follow, improve, and enforce coding standards\n- Write unit tests and interact regularly with testers to prevent regression issues\n- Provide estimates for development effort\n- Actively suggest a plan of action to improve the overall quality\n- Research new technologies and existing libraries\n\n2. REQUIREMENTS\n- Minimum 3 years of experience as full-stack developer  \n- Solid skills in PHP Web (Laravel, Codeigniter, Zend,...l) and MVC framework\n- Experience with HTML, CSS, Angular/VueJS/ReactJS, Bootstrap, tailwind\n- Knowledge of relational database management systems such as MySQL, PostgreSQL…\n- Knowledge of architecture, design patterns & best practices\n- Experience with three.js\n- Experience with Docker & K8S\n- Multi-tasking, collaboration, presentation, strategic & tactical thinking, and research & development skills\n\n3. WHY YOU WILL LOVE WORKING HERE?\nBeing a member of us, you will experience a youthful, flexible, and creative work environment\n- Competitive salary \n- Annual salary review\n- 13th month salary\n- 12-day annual leave per year\n- Working in a professional, friendly, well-equipped environment both with foreigners and Vietnamese\n- Extensive on job training, you will always have a chance to work with new emerging technologies\n\n4. INTERVIEW PROCESS: Only 1 round: Interview with client\n\n5. WORKING TIME: Onsite from Monday to Friday (9AM - 6PM) & Remote on Saturday (9AM - 12PM)\n\n6. LOCATION:  Tan Binh District, Ho Chi Minh City', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2043, 923, 2, '[HÀ NỘI] .NET DEVELOPER', '[Hà Nội] .Net Developer\n\nMÔ TẢ CÔNG VIỆC\n\n- Tham gia trực tiếp Phát triển sản phẩm :\n- Phát triển hệ thống phần mềm Hợp đồng điện tử và quản lý ký số\n- Phát triển web backend/fontend liên quan tới sản phẩm\n- Phát triển API phục vụ xây dựng Mobile Apps và tích hợp hệ thống\n- Tham gia viết các tài liệu cấu trúc phục vụ phát triển phần mềm\n- Kiểm tra, đánh giá chất lượng phần mềm sau khi lập trình, đảm bảo phần mềm ổn định, không có lỗi sảy ra khi phát hành\n- Triển khai\n- Nhận yêu cầu, thiết kế và xử lý công việc được giao bởi PM/BA dự án\n- Đảm bảo các dự án hoàn thành đúng tiến độ và đạt chất lượng cao\n- Làm việc và hỗ trợ trực tiếp với các Team sản phẩm, Mobile Developer, CSKH, Khối Vận hành,…\n- Tham gia tư vấn, giải đáp kỹ thuật trong quá trình chào sản phẩm\n- Hướng dẫn hỗ trợ khách hàng level kỹ thuật, hệ thống\n\nYÊU CẦU CÔNG VIỆC\n\n- Có 2- 3 năm kinh nghiệm lập trình với công nghệ như ASP.Net,.Netcore, MVC, Entity Framework, LinQ, Restful API, WCF\n- Có kiến thức về Javascript, XML/HTML/CSS, Ajax, jQuery, React, Angular, Vue\n- Hệ quản trị CSDL MS SQL Server, Mongo DB, PostgreSQL\n- Có kiến thức về kiến trúc MicroService, Containers/Docker\n- Đam mê công việc, sự sáng tạo và đổi mới\n- Kỷ năng giải quyết vấn đề linh hoạt, sẵn sàng phá bỏ các rào cản, tích cực tìm kiếm các giải pháp thay thế để đạt mục tiêu cần có\n- Tinh tần hợp tác, chủ động, nhiệt tình, hòa đồng trong công việc, làm việc tốt theo nhóm\n- Có tinh thần trách nhiệm cao. Cầu thị, tự tin, quyết đoán.\n\nQUYỀN LỢI ỨNG VIÊN\n\nTHU NHẬP\n\n- Lương tháng thỏa thuận theo năng lực ứng viên\n- Thưởng KPIs năm từ 1-2 tháng lương/năm\n- Gói phúc lợi tiền mặt hơn 9 triệu/năm vào các dịp Lễ, Tết, Sinh nhật Tập đoàn...\n- Xét tăng lương theo năng lực và kết quả công việc định kỳ 1 lần/năm. Hoặc tăng lương đột xuất theo hiệu quả công việc.\n\nCHẾ ĐỘ ĐÀO TẠO VÀ PHÁT TRIỂN\n\n- Đài thọ 100% chi phí tham gia các khóa học, thi chứng chỉ CNTT Quốc tế.\n- Chính sách phát triển, thăng tiến theo Career Path phù hợp với từng vị trí, từng phòng ban.\n- Cơ hội tiếp cận với các công nghệ mới nhất: Cloud, Big data...\n- Cơ hội làm việc trong Công ty là Top 1 đối tác tư vấn và cung cấp, triển khai giải pháp Chuyển đổi số, Bảo mật, Cloud cho tổ chức và doanh nghiệp tại Việt Nam\n\nBẢO HIỂM VÀ CHÍNH SÁCH ĐÃI NGỘ\n\n- Thời gian làm việc: Thứ Hai – Thứ Sáu; Nghỉ thứ 7 & Chủ Nhật.\n- Nghỉ phép: 12 ngày/ năm + 1 ngày nghỉ hưởng lương vào dịp sinh nhật bản thân CBNV\n- Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo quy định Nhà nước\n- Chế độ bảo hiểm nâng cao: CMC Care\n- Chế độ đãi ngộ thai sản nâng cao dành cho nhân viên nữ\n- Du lịch hàng năm 1 tuần, teambuilding/dã ngoại định kì 2 lần/năm\n- Tham gia các Câu lạc bộ của Công ty và các chương trình trải nghiệm nhân viên đa dạng và phong phú\n- Được trang bị laptop/thiết bị công nghệ trong quá trình làm việc.\n- Môi trường làm việc trẻ trung, chuyên nghiệp\n\nNộp đơn ứng tuyển công việc này', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2044, 814, 2, '[iKame Apps] iOS Developer', 'Location: Hà Nội\n\nSalary: Up to $1500\n\nExpiration date: 30/06/2025\n\nMÔ TẢ CÔNG VIỆC\n\n- Project Manager của sản phẩm chính mình phát triển.\n- Xây dựng và phát triển các dự án của công ty trong lĩnh vực tiện ích, giải trí.\n- Phối hợp trực tiếp với các thành viên Product (Tester, UI/UX, PO...) và bộ phận Marketing (UA), Business Intelligent, Monetize để phát triển, vận hành và tối ưu sản phẩm.\n- Được sử dụng các công nghệ mới nhất trong lĩnh vực lập trình: Swift UI, asyn await, combine ...\n- Biết sử dụng UIKit là một điểm cộng\n- Đánh giá, phân tích, nâng cấp và tối ưu mã nguồn trong quá trình phát triển.\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai.\n- Tham gia phân tích, đánh giá tiềm năng thị trường, tối ưu các chỉ số để cải thiện Marketing cho sản phẩm.\n- Sáng tạo ý tưởng, đưa ra giải pháp tối ưu hóa cho các tính năng trong sản phẩm/ trong cách làm nhằm cải thiện chất lượng sản phẩm và trải nghiệm người dùng.\n- Tham gia quá trình xây dựng team dev; chia sẻ và cùng phát triển chuyên môn các bạn dev của công ty.\n\nYÊU CẦU CÔNG VIỆC\n\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan\n- Yêu cầu có đam mê lập trình\n- Kinh nghiệm lập trình iOS với Swift và sử dụng Xcode.\n- Hiểu biết về design patterns\n- Hiểu biết về cơ sở dữ liệu (Realm, CoreData).\n- Kinh nghiệm sử dụng Combine, async/await, và protocols.\n- Nắm vững vòng đời ứng dụng, quản lý bộ nhớ và xử lý Memory leak.\n- Sử dụng thành thạo Git.\n- Kỹ năng giải quyết vấn đề, tư duy phản biện và khả năng làm việc độc lập cũng như nhóm.\n- Có khả năng đọc hiểu tiếng Anh.\n\nJunior IOS Developer\n\n- 2+ năm kinh nghiệm phát triển ứng dụng iOS.\n- Có đam mê công nghệ, sẵn sàng học hỏi.\n- Chủ động, có trách nhiệm trong công việc.\n\nMiddle + Senior iOS Developer:\n\n- 4+ năm kinh nghiệm phát triển ứng dụng iOS.\n- Kinh nghiệm review và maintain code, xử lý bug, crash, quản lý đa luồng.\n- Khả năng estimate công việc\n- Kinh nghiệm hỗ trợ và mentor các thành viên trong nhóm.\n- Điểm cộng: Có kinh nghiệm publish ứng dụng lên App Store.\n\nQUYỀN LỢI\n\n- Mức lương upto 1500$ ; Review lương 2 lần/ năm\n- Thưởng HẤP DẪN: Thưởng hiệu quả kinh doanh theo 2 quý/ lần + Thưởng tháng lương thứ 13 + Thưởng Lễ\n- Được đào tạo và tham gia xây dựng và phát triển sản phẩm đa dạng thể loại hướng tới CHẤT LƯỢNG & GHI DẤU ẤN – cơ hội phát triển và thăng tiến rộng mở\n- Cơ hội được học hỏi, được thử sai, được đưa ý kiến để rèn luyện bản thân và trau dồi kinh nghiệm thực chiến với việc hỗ trợ 30-100% chi phí các khóa học mọi kỹ năng\n- Môi trường thân thiện, hiện đại, văn phòng đẹp xịn xò view toàn thành phố\n- Văn hóa Sharing mạnh mẽ, luôn có sự support từ team và cập nhật những công nghệ mới nhất.\n- Quỹ CLB thể thao: Bóng đá; cầu lông...\n- Con người là số 1 - bạn sẽ được quan tâm từ thiết bị làm việc, bữa ăn xế chiều, tới chỗ ngủ, từ tủ đầy đồ ăn vặt tới PS4 xả não, thư viện cho những tâm hồn yêu thích đọc sách...\n- Các chế độ đãi ngộ khác như Trợ cấp ăn trưa 1 triệu đồng/tháng, Gói khám sức khỏe cao cấp, Teambuilding thường xuyên, Du lịch dài ngày..\n- Giờ làm việc 8:30 - 18:00 từ thứ 2 tới thứ 6; ưu tiên sự linh hoạt và chủ động quản trị hiệu suất\n\nCÁCH THỨC ỨNG TUYỂN\n\n💌 Ứng viên gửi CV về email: recruitment@ikameglobal.com\n\n➡️Hotline: 024 6662 5287 | HR Department\n\n➡️Head Office: Tầng 9 & 10 tòa Peak View, số 36 Hoàng Cầu, Ô Chợ Dừa, Đống Đa, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2045, 282, 2, 'Mobile Developer', 'Mô tả công việc:\n- Thiết kế kiến trúc và lập trình phát triển module/sản phẩm mới hoạt động ổn định\n- Tham gia phát triển, đề xuất giải pháp kỹ thuật các dự án lập trình ứng dụng App trên nền tảng mobile\n- Nghiên cứu và ứng dụng các công nghệ mới và ứng dụng vào quá trình phát triển sản phẩm, viết tài liệu mô tả\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của cấp trên\n- Góp phần xây dựng công ty, tham gia định hướng chiến lược và phát triển sản phẩm\n- Đánh giá các chức năng khi nhận được yêu cầu từ các nhóm\n- Báo cáo kết quả làm việc với Ban lãnh đạo và Quản lý trực tiếp.\nYêu cầu công việc:\n- Có từ 2 năm kinh nghiệm Flutter (Ưu tiên biết Native Android hoặc IOS)\n- Có kinh nhiệm submit/publish app trên store (PlayStore và AppStore).\n- Có kinh nghiệm tạo plugin, package, module.\n- Có kinh nhiệm tích hợp SDK vào các app khác.\n- Có kinh nghiệm về UI/UX và xử lý các animation.\n- Có kinh nghiệm về Chopper, Dio, Retrofit, Go Route là một lợi thế.\n- Có kinh nghiệm về Flutter generate assets, text, color…\n- Có kỹ năng làm việc với các dự án sử dụng quản lý mã nguồn Git.\n- Có hiểu biết về CI/CD là một lợi thế.\n- Có kinh nghiệm về tối ưu performance cho ứng dụng.\n- Có khả năng phân tích yêu cầu và làm việc nhóm.\n- Đã từng làm trong lĩnh vực tài chính/ngân hàng là một lợi thế.\nChế độ đãi ngộ:\n- Lương thỏa thuận theo năng lực\n- Trợ cấp ăn trưa bằng coupon (giá trị 40k/ngày) tại canteen vé gửi xe máy miễn phí.\n- Thường xuyên tổ chức các giải thưởng cho cá nhân/team xuất sắc.\n- Thưởng cuối năm (theo tình hình kinh doanh của công ty và kết quả công việc)\n- Review lương 1-2 lần/năm\n- Chế độ khác: BHXH, BHYT, BHTN theo luật lao động. Bảo hiểm sức khỏe PVI (cấp Lead trở lên, hỗ trợ mua kèm người nhà)\n- Du lịch khám phá các vùng đất mới, Teambuilding gắn kết đội ngũ 2 lần/năm cùng toàn thể CBNV công ty\n- Khám sức khỏe định kỳ, Đào tạo và các chương trình văn hóa nội bộ v.v…\n- Nghỉ phép 12 ngày/năm\n- Thời gian làm việc: Thứ 2 – thứ 6 (9h – 18h00) và 2-3 sáng thứ 7 cách tuần (remote)\n- Ngoài ra công ty còn có các CLB chăm lo sức khỏe thể chất tinh thần cho CBNV: bóng đá, bơi, cầu lông, bi-a, đạp xe,…\nĐịa chỉ làm việc: 19 Tố Hữu, Trung Văn, Nam Từ Liêm, Hà Nội', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2046, 1070, 2, 'AI ENGINEER (3Y+, BH FULL LƯƠNG, UPTO 40M)', 'Mô tả công việc\n- Nghiên cứu, xác minh và báo cáo các công nghệ mới như đảm bảo chất lượng AI\n- Phát triển các công nghệ mới liên quan đến chất lượng phần mềm, triển khai trong các tool, v.v.\n- Triển khai và cải tiến các thuật toán và mô hình theo yêu cầu ứng dụng trong thực tế\n- Cộng tác với các kỹ sư phần mềm để tích hợp các mô hình máy học vào hệ thống sản xuất, đảm bảo khả năng mở rộng, độ tin cậy và hiệu suất\n- Sử dụng/tối ưu hóa các mô hình ngôn ngữ lớn như GPT (Generative Pre-training Transformer) cho các trường hợp sử dụng cụ thể trong Kiểm thử phần mềm\n- Nghiệp vụ phát triển nghiên cứu liên quan đến test, phát triển và thiết kế hệ thống cùng với sự hợp tác của bộ phận R&D của khách hàng phía Nhật Bản (nghiên cứu ứng dụng)\n- Giải quyết các bài toán về Machine Learning, Deep Learning, Big Data khác\n- Các công việc liên quan khác theo yêu cầu của trưởng bộ phận\n\nYêu cầu ứng viên\n- Trên 3 năm kinh nghiệm trong lĩnh vực AI, Machine Learning, Deep Learning, từng tham gia phát triển các mô hình học sâu phục vụ các bài toán trong AI\n- Đã làm việc trên nhiều nền tảng học sâu phổ biến như TensorFlow, Keras, Caffe, PyTorch, v.v.\n- Từng tham gia ít nhất 01 dự án hoặc đề tài R&D liên quan đến AI hoặc các ứng dụng học máy chuyên sâu\n- Thành thạo các ngôn ngữ lập trình như Python, C/C++, có khả năng xử lý các bài toán phức tạp, tối ưu hóa hiệu năng hệ thống.\n- Có kinh nghiệm xây dựng, huấn luyện và triển khai các mô hình LLM (Large Language Models) cho các ứng dụng xử lý ngôn ngữ tự nhiên (NLP), đặc biệt là các hệ thống sinh văn bản, truy vấn ngữ nghĩa, và trợ chuyện thông minh\n- Thành thạo trong việc phát triển và tối ưu hóa các mô hình RAG (Retrieval-Augmented Generation), phục vụ cho các hệ thống AI đàm thoại, chatbot nội bộ, và tìm kiếm ngữ nghĩa tăng cường.\n- Có hiểu biết sâu về các kỹ thuật OCR (Optical Character Recognition), từng triển khai các pipeline trích xuất văn bản từ hình ảnh tài liệu đa ngôn ngữ, tích hợp với các mô hình NLP để phân tích và xử lý văn bản\n- Tuân thủ nghiêm ngặt các tiêu chuẩn lập trình như PEP8 đối với Python, đảm bảo mã nguồn rõ ràng, dễ bảo trì và có khả năng mở rộng\n- Có khả năng đóng gói, triển khai, tích hợp AI model vào các sản phẩm thực tế\n- Thành thạo các công cụ quản lý mã nguồn như Git, SVN, có kinh nghiệm làm việc nhóm theo mô hình Agile/Scrum, đồng thời có khả năng làm việc độc lập và chủ động giải quyết vấn đề\n\nQuyền lợi\n1. Lương và Phúc Lợi\n- Rank lương upto 40M Gross\n- Thời gian làm việc 5 ngày/ tuần, checkin linh hoạt từ 7h30 đến 8h30 (Nghỉ Thứ 7, Chủ Nhật). Nghỉ trưa 1 tiếng, từ 12h00 đến 13h00\n- Thử việc 120% lương\n- Tham gia đầy đủ Bảo hiểm tuân thủ theo Luật Lao động hiện hành (Đóng full lương)\n- Bảo hiểm sức khỏe\n- Hỗ trợ ăn trưa\n- Khám sức khỏe định kỳ hàng năm\n- Tối thiểu 13 tháng lương 1 năm, và các khoản thưởng vào các ngày lễ khác\n- Thưởng giới thiệu ứng viên 20M – 40M/1 người tùy từng thời điểm\n- Thưởng bằng cấp 5-20M/1 lần\n- Thưởng lễ tết 1M/1 lần\n- Tiền ma chay, hiếu hỉ 2M/1 người\n- Đánh giá tăng lương 2 lần/năm\n- Tham gia các sự kiện ngoại khóa, hoạt động Team Building, Workshop, tiệc sinh nhật hàng tháng,...Du lịch 1 lần/năm trong nước hoặc nước ngoài\n2. Cơ hội nghề nghiệp\n- Làm việc, học hỏi và phát triển cùng đồng nghiệp là những kỹ sư trẻ tài năng, đam mê và có lý tưởng lớn\n- Được tham gia các chương trình training về kỹ năng công nghệ và kỹ năng mềm, phương pháp làm việc\n- Được tư vấn và chia sẻ về phát triển năng lực và nghề nghiệp bản thân\n- Có nhiều cơ hội đi onsite làm việc tại Nhật \n3. Môi trường làm việc\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, công bằng\n- Có cơ hội thăng tiến lên các vị trí Leader, quản lý\n- Tinh thần làm việc nhóm tốt, hỗ trợ nhiệt tình từ đồng nghiệp\n- Tham gia các khóa học training tiếng Nhật, kỹ năng mềm, kiến thức kỹ thuật\n- Tham gia các Club Game, Bóng đá, Tiếng Nhật\n- Có cơ hội làm việc và đào tạo tại Nhật Bản\n\nĐịa điểm làm việc & Thông tin công ty\nHà Nội: Tầng 23 & Tầng 26 tòa nhà Handico Phạm Hùng, Mễ Trì, Nam Từ Liêm\nFacebook: Veriserve Viet Nam Careers\n\nThời gian làm việc\nThứ 2 - Thứ 6 (Từ 08:00 đến 17:00)\n\nProcess tuyển dụng\nRound 1 - OFFLINE: Trao đổi về chuyên môn\nRound 2 - OFFLINE: Trao đổi về văn hóa & định hướng công việc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2047, 1071, 2, 'Backend Engineer', 'About Us!\nWinter Wolf is one of the teams within IEC Games, which was established in 2015. Over the years, we have built and developed our brand, producing high-quality products that have been downloaded by tens of millions of users worldwide.\nOur achievements so far, are as follows:\nIn 2020, IEC Games ranked among the top six ANZSEA publishers in terms of downloads.\nIn December 2020, our game studio ranked twentieth in the world in terms of download volume in the United States.\nIn 2021, Water Sort Puzzle achieved eighth place on the Top Games of 2021 chart on the App Store, in the Top Free Charts category.\nWe are seeking individuals to join our team with the goal of creating innovative products and achieving commensurate income with the effort you invest.\nJOB DESCRIPTION\nCollaborate with other departments in the team to understand, develop, and maintain tools that support and automate team workflows;\nDevelop and maintain tools that connect and integrate third-party tools and services into the team\'s work system;\nBuild a well-organized and maintainable codebase that can be expanded and integrated in the future;\nAnalyze code, requirements, risks, and stability of the system.\nQUALIFICATIONS\nDeep experience and knowledge of JavaScript and Node.JS;\nExperience with Google Cloud, Amazon Web Service, or similar products/services is a plus;\nExperience with Google Apps Script, Google Sheets, Docker, Bash script, Discord Bot, Facebook Graph API, Google API is a plus;\nCan read and write in English; Prefer English skills equivalent to IELTS 6.0 or above;\nBeing diligent, progressive, and responsible for work;\nHaving passion for games, especially mobile games is a plus.\nMINIMUM BENEFITS\nSalary negotiations, up to 1.500 USD;\nFixed end-of-year bonus: 2 (two) months of salary;\nAnnual business efficiency bonus: based on product revenue, paid from 1 month to n months of salary (unlimited), depending on contribution and project role;\nPerformance and salary review conducted twice a year;\nLunch and parking allowances provided;\nSubsidy for IELTS certification exam fee;\nSubsidy for professional and job-related courses and training;\nAnnual subsidy of 10.000.000 VND for sport and fitness (i.e gym, dance, swimming, etc.);\nSponsorship for driving license study and exam fees;\nAnnual domestic and international travel opportunities;\nAnnual team-building activities with the team;\nWorking in a young, dynamic, and modern work environment;\nWorking 5 days per week, from Monday to Friday; days off on Saturday and Sunday;\nFull insurance benefits according to the Labor Law regulations.\nAPPLY NOW!\nPlease submit your CV and demo products (if any) to the email address hr@ieccorp.vn.\nEmail subject should be: Your Full Name - Backend Engineer Application', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi i okolice', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2048, 1072, 2, 'Windows Desktop Developer', 'Job Description\n\n- Create a Desktop Application for a Home Trading System using JavaScript integrated with C++.\n- Collaborate closely with a remote team to understand and clarify tasks and requirements.\n- Design and implement new features, involving requirement analysis and system design, according to user needs.\n- Address and resolve bugs or issues identified during integration testing, user acceptance testing, and maintenance testing, coordinating with backend developers and testers as needed.\n- Manage time and resources effectively using WBS/Redmine.\n- Prepare daily progress reports on task completion.\n- Write clean, high-quality, elegant, maintainable, and testable code.\n- Maintaining technical documents up-to-date.\n- This role offers exposure to all phases of diverse projects, various aspects of software engineering, and opportunities for professional development.\n\nRequirements:\n\n- Bachelor\'s Degree in Computer Science, Information Technology, or a related field.\n- Able to communicate in English, with technical interview questions conducted in English.\n- Possess at least 4 years of hands-on experience in JavaScript development.\n- Solid grasp of object-oriented programming and design patterns such as MVC and MVVM.\n- Skilled in writing clean and easily understandable code.\n- Experienced with version control systems like SVN and familiar with issue-tracking tools such as Redmine.\n- Proficient in Agile methodologies, with a thorough understanding of Agile development principles.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2049, 778, 2, 'Cross-Platform Mobile Developer (React Native) - Generative AI Project', '** Note:** We highly appreciate your interest in this position of HCLTech Vietnam. After reviewing all applications, only qualified candidates will be contacted for the next steps within 15 days from the date of submission.\n\nABOUT HCL VIETNAM COMPANY LIMITED\n\nHCL Vietnam Company Limited belongs to HCLTech which is a global technology company, home to 220,000+ people across 60 countries, delivering industry-leading capabilities centered around digital, engineering and cloud, powered by a broad portfolio of technology services and products. We work with clients across all major verticals, providing industry solutions for Financial Services, Manufacturing, Life Sciences and Healthcare, Technology and Services, Telecom and Media, Retail and CPG, and Public Services. Consolidated revenues as of 12 months ending Mar 31, 2025, totaled $13.8 billion.\n\nDUTIES AND RESPONSIBILITIES\n\n*** About the Role:\nWe are seeking a highly skilled React Native Mobile Developer to join our dynamic team in building a cutting-edge Generative AI-powered banking application. The ideal candidate will have expertise in developing high-performance cross-platform mobile applications and integrating AI/ML solutions to deliver an innovative, secure, and user-friendly banking experience.\n\n*** Key Responsibilities:\n- Design, develop, and maintain cross-platform mobile applications using React Native for iOS and Android.\n- Implement secure and scalable APIs to interact with banking services and AI functionalities.\n- Work closely with UX/UI designers to ensure a seamless and intuitive user experience.\n- Optimize application performance and ensure responsiveness on various devices.\n- Ensure compliance with banking security and data privacy regulations (e.g., PCI-DSS, GDPR).\n- Perform unit and integration testing to ensure app stability and reliability.\n- Monitor application performance and troubleshoot issues as they arise.\n- Stay up to date with React Native, AI advancements, and FinTech industry trends.\n\nJOB REQUIREMENTS\n\nYou are not expected to have 100% of these skills. At HCLTech, a growth mindset is at the heart of our culture, so if you have most of these things in your toolbox, we would love to hear from you!!!\n\n*** Required Skills & Qualifications:\n- 6+ years of experience in React Native mobile application development.\n- Strong knowledge of JavaScript (ES6+), TypeScript, Redux, and React hooks.\n- Experience with mobile UI/UX design principles and responsive design.\n- Familiarity with RESTful APIs, WebSockets.\n- Hands-on experience in working with GenAI is a plus.\n- Knowledge of secure coding practices and mobile app security.\n- Experience with CI/CD pipelines for mobile applications.\n- Experience working in Agile/Scrum development environments.\n- Expert in React Native, capable of building complex mobile experiences across both iOS and Android, including advanced animations.\n- Familiar with Mobile DevOps, able to set up CI/CD pipelines and manage app signing and deployment processes.\n- Strong computer science foundation to handle architectural and performance considerations.\n- Must have at least one app published on the App Store / GooglePlay references or links to be provided.\n\nSALARY AND BENEFITS\n- Salary: Completely feel free to tell us your expected number!!!\n- 18 paid leaves/year (12 annual leaves and 6 personal leaves)\n- Insurance plan based on full salary + 13th month salary + Performance bonus\n- Meal allowance of 730,000 VND/month\n- 100% full salary and benefits as an official employee from the 1st day of working\n- Medical benefit for employee and family\n- Working in a fast-paced, flexible, and multinational working environment. Chance to travel onsite (in 59 countries)\n- Free snacks, refreshment, and parking\n- Internal training (Technical & Functional & English)\n\nContact:\nEmail: mai.huynh@hcltech.com\nPhone/Zalo: +84931 583 594', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2050, 1073, 2, 'VA 5359 - Drupal Developer (All Level)- Upto $1800', 'Job Purpose\n\nWe are searching for Drupal Developers: from Junior, Mid-level to Seniors who knows Drupal inside and out. Those candidates will have good or exceptional programming skills, problem-solving abilities, and a strong work ethic.\n\nJob Responsibilities\n\n- Custom programming and web application development for Drupal\n- Testing, maintenance, and troubleshooting of existing company sites\n- Contributing ideas and efforts towards internal projects and working as part of a team to find solutions on various problems\n\nRequired Skills/competencies\n\n- Minimum 1 year working experience for Junior level and 5 years for Senior level with Drupal 8,9 (proven record via worked projects)\n- Strong knowledge of PHP to develop web-based applications\n- Solid experience with MySQL and writing efficient SQL queries for reporting\n- Good experience with unit testing\n- Good at JavaScript skills\n- Having experience of any JavaScript front-end framework\n- Good knowledge of Git, GitFlow\n- Experienced third-party system connection: payment gateway, shipping …\n- Write optimized SQL queries, interact on big data\n- Ability to self-learn and adapt to new technologies quickly\n- Ability to both collaborate with team members and to work independently\n- Results-oriented, reliable, able to work under pressure\n\nPreferred Skills\n\n- Comfortable working without routine supervision.\n- A desire to remain technically capable and an expert in current technologies.\n- Excellent personal organization and ability to prioritize and carry out multiple tasks.\n- Proven experience in leading and managing the delivery of system/software development projects in a structured environment.\n- Experience in a variety of software development approaches and methodologies including Agile (Scrum)\n\nRemuneration\n\n- Negotiable salary dependent on experience and qualifications. (upto 1800$)\n- Annual salary review\n- Annual leave, and working conditions follow Vietnam labor laws.\n- International, dynamic, friendly working environment\n- Support for learning and certificate examination\n- Annual vacation: follows company’s policy every year\n- Opportunity to build a long-term relationships with colleagues via multiple projects\n- Working time: Monday - Friday 9 AM - 6 PM\n\nPlace of work\n\nHanoi Office - Icon 4\n\nNumber of vacancies\n\n1\n\nIf you are interested in the role above, please send a copy of your CV and a short cover letter to vietnamhr@intergreat.com.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2051, 675, 2, 'Fullstack Developer (Middle/ Senior)', 'Sapo là công ty Công nghệ. Với khả năng và hướng đi rõ ràng, Sapo nhanh chóng khẳng định được vị trí hàng đầu trong việc xây dựng nền tảng công nghệ hỗ trợ lĩnh vực bán lẻ và TMĐT. Với hơn 230.000 khách hàng trên toàn quốc tin tưởng sử dụng, Sapo đang là doanh nghiệp có nền tảng quản lý và bán hàng đa kênh từ Online đến Offline được sử dụng nhiều nhất tại Việt Nam.\n\nĐội ngũ nhân viên Sapo hiện có hơn 1000 nhân sự có trình độ chuyên môn cao, luôn làm việc với tất cả sự nhiệt huyết và sức sáng tạo của tuổi trẻ đã xây dựng nên 1 văn hoá vô cùng trẻ trung và năng động. Đến với Sapo, bạn sẽ được trải nghiệm môi trường tuyệt vời, với chế độ đãi ngộ xứng đáng và đạt được thành công vượt mong đợi!\n\nMô tả công việc\n\nSử dụng Java phát triển các service sử dụng REST API (Java Spring Boot) trong hệ thống kiến trúc Microservices\n\nLập trình frontend cho các dự án phát triển sản phẩm\n\nTham gia phát triển nền tảng quản lý & bán hàng trên hệ thống Sapo: quản lý bán hàng, quản lý kho, quy trình hoàn tất đơn hàng, phát triển các kênh bán hàng POS, Web, Marketplace, Social…\n\nTham gia phân tích nghiệp vụ, đảm bảo chất lượng, tiến độ công việc và trải nghiệm người dùng (hiệu năng, tính dễ sử dụng, cũng như mức độ ổn định của sản phẩm).\n\nTriển khai các hạng mục công việc theo nhiệm vụ được giao. Tham gia & kiểm soát các hạng mục phát triển tính năng mới, cải tiến tính năng cũ nhằm đảm bảo chất lượng và khả năng mở rộng.\n\nPhối hợp với team nghiên cứu và ứng dụng các công nghệ mới để triển khai tính năng mới, đồng thời cải tiến liên tục các hạng mục đã ra mắt nhằm tối ưu hiệu năng & duy trì ổn định sản phẩm.\n\nYêu cầu công việc\n\nTốt nghiệp chuyên ngành Công nghệ thông tin và các chuyên ngành liên quan khác.\n\nCó từ 2 năm kinh nghiệm trở lên lập trình Java Full Stack\n\nSử dụng thành thạo Git hoặc SVN.\n\nHiểu biết các Framework: Spring, Hibernate.\n\nCó hiểu biết tốt về Design pattern, OOP, REST API.\n\nCó kinh nghiệm & hiểu biết về xây dựng hệ thống Microservice.\n\nCó tư duy logic tốt, khả năng tự tìm hiểu & giải quyết vấn đề tốt\n\nCó kiến thức về cơ sở dữ liệu quan hệ Mariadb, MySQL.\n\nƯu tiên có kinh nghiệm về Domain Driven Design, NoSQL (Redis, MongoDB), các hệ thống Message Queue (Kafka, RabbitMQ).\n\nChủ động trong công việc, có tinh thần trách nhiệm cao.\n\nChủ động phối hợp với thành viên trong team để giải quyết vấn đề, thực hiện mục tiêu.\n\nƯu tiên có kinh nghiệm vận hành hệ thống AWS là 1 lợi thế.\n\nQuyền lợi\n\n- Lương/thưởng hấp dẫn theo quy định của công ty\n- Xét tăng lương định kỳ hàng năm\n- Môi trường làm việc trẻ trung, sáng tạo\n- Chế độ BHXH, BHYT theo luật Lao động, ngoài ra được tham gia chương trình bảo hiểm Sapo Care\n- Được tham gia các khoá đào tạo từ các chuyên gia hàng đầu về thương mại điện tử, marketing online, phần mềm ...\n\nLiên hệ\n\nĐể tìm hiểu thêm chi tiết, vui lòng liên hệ:\n\n- SĐT: 0913 198 910 (Ms Linh)\n- Email: tuyendung@sapo.vn\n- Website công ty: https://www.sapo.vn/\n- Fanpage TD: https://www.facebook.com/tuyendungsapo/\n- Zalo OA: Tuyển Dụng Sapo\n- Địa chỉ văn phòng: Tòa Ladeco, số 266 Đội Cấn, Ba Đình, Hà Nội\n\nỨng tuyển vị trí: Fullstack Developer (Middle/ Senior)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2052, 916, 2, 'MT | Senior Fullstack Engineer (NodeJS/Typescript preferred)', 'Qualifications:\n- Good at English communication\n- 5+ years of software engineering experience\n- Expertise in TypeScript/JavaScript, React, and front-end development; proficiency in full-stack development with at least one server-side language (NodeJS preferred).\n- Hands-on experience with AWS.\n- Experienced in Continuous Delivery practices (CI, TBD, etc.)\n- Hands-on experience of testing methodologies (e.g., TDD, BDD, mocking) or a willingness to develop further in this area\n- Experience using automation tools to build robust, automated build/release/deploy processes (e.g. GitHub Actions)\n- Experience leveraging modern software design patterns (e.g., SOLID, Strategy/Observer/Facade, hexagonal architecture) and both object-oriented and functional programming.\n- Experience using, building, and running containers locally and exposure to concepts pertaining to container orchestration in a production environment (e.g. ECS, EKS/Kubernetes, docker-compose)\n- Commitment to continuous learning and staying up to date with software engineering trends.\n- Experience in designing team and service interfaces, leveraging contracts and specifications (OpenAPI / Swagger) to driver discussions and designs.\n- Proven ability to work successfully in and with a remote, global team.\n\nResponsibilities:\n- Develop, support, and maintain software applications using best practices across a range of technologies ensuring high-quality, maintainable, efficient, tested, and scalable code.\n- Provide input into the target state architecture for the platform.\n- With their peers, develop a robust, automated, and modern CICD practice within the team.\n- Developing high-quality solutions collaboratively with the team and appropriate members throughout the engineering function using a mix of front-end (web and mobile) and back-end technologies.\n- Working incrementally towards delivery of the platform. Collaborating closely with Product using customer data and insights to drive the solutions.\n- Establishing strong quality and automation practices and processes.\n- Working closely with our Platform teams to implement software leveraging our internal platforms, tools, frameworks, and infrastructure where appropriate.\n- Collaborating closely with product owners, delivery leads, and business analysts to break down, estimate, and deliver business requirements.\n- Contributing to the improvement of software development lifecycle processes.\n- Participate in and, at times, facilitate Engineering Dojos driving a culture of Engineering Excellence.\n- Provide continuous support and guidance to less senior colleagues through regular coaching activities and support them in fulfilling their personal development plans.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2053, 702, 2, 'Senior Frontend Engineer - KYC Saas', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nWe are looking for a Senior Frontend Engineer to join our team responsible for building and maintaining the KYC platform. Join us and play a part in building the future of finance.\n\nResponsibilities\n\n- Implement new user-facing features in Binance’s products \n- Write client-side code to create super-fast, easy-to-use, web-based applications which include website for both desktop and mobile browsers, and hybrid in-app pages.\n- Optimize web applications to maximize speed and scale.\n- Build libraries and frameworks that support complex web applications, speedup development efficiency and improve code quality.\n- Work with stakeholders to define and prioritize technical requirements.\n- Strong ownership and self-motivation. able to push things happen and get things done independently\n\nRequirements\n\n- 5+ years of production experience with JavaScript, and strong expertise in React.\n- Proficient in state-management patterns such as Redux, Flux, or similar, with a solid understanding of their implementation.\n- Proven track record of delivering high-quality UI with a focus on user experience and performance.\n- Solid understanding of responsive design principles, and experience in developing cross-platform web applications optimized for both desktop and mobile devices.\n- Experience with modern frontend technologies and tools like TypeScript, styled system, webpack, and related build tools.\n- Familiarity with libraries such as react-query, zod, zustand, or similar tools to improve development efficiency and manage state.\n- Expertise in writing unit, integration, and end-to-end tests using frameworks like Jest, Mocha, Cypress, etc., and debugging complex frontend issues with tools like Chrome DevTools.\n- Expertise in Git, GitHub/GitLab, and understanding branching strategies (Git Flow, etc.) for large teams.\n- Ability to work independently with minimal supervision, and demonstrate leadership within the team when necessary.\n- Bachelor’s degree in Computer Science/Engineering, or equivalent industry experience.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho-Chi-Minh-Stadt, Ho-Chi-Minh Stadt, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2054, 1051, 2, 'Python Back-end Developer', 'Qode is proud to partner with a fast-growing, product-driven tech company to hire a Mid/Senior Backend Engineer. This is a great opportunity for a skilled backend engineer who\'s passionate about building scalable systems and eager to work alongside cross-functional teams in a dynamic and professional environment.\n\nAbout The Role\n\nYou\'ll play a critical role in designing and maintaining the backbone of the platform — scalable, high-performance backend systems and APIs. You\'ll collaborate closely with frontend developers, DevOps engineers, and product managers, while also mentoring junior team members and helping shape the system\'s technical direction.\n\nWhat You\'ll Do\n\n- Develop and maintain robust backend services and APIs using Python\n- Collaborate with frontend engineers to integrate server-side logic with user-facing elements\n- Optimize systems for performance and scalability, ensuring they can support high traffic and large datasets\n- Ensure application security and compliance with industry standards\n- Write clean, maintainable, well-documented code aligned with best practices\n- Conduct code reviews and provide mentorship to junior developers\n- Partner with DevOps to streamline CI/CD and ensure smooth service deployment\n- Troubleshoot and debug complex backend issues\n- Contribute to architectural decisions and strategic technical planning\n- Stay current on industry trends and apply relevant innovations to enhance the platform\n\nYour Experience & Skillset\n\n- Bachelor\'s degree in Computer Science or equivalent professional experience\n- Solid foundation in data structures, algorithms, and software architecture\n- Proficiency in Python; experience with Django and Celery preferred\n- Familiarity with both relational (PostgreSQL, MySQL) and NoSQL databases (MongoDB, Redis)\n- Experience with cloud platforms (AWS, GCP, Azure) and containerization (Docker, Kubernetes)\n- Strong problem-solving abilities and a proactive mindset\n- Excellent collaboration and communication skills\n\nWhy You\'ll Love This Role\n\n- Professional workspace: Structured internal processes, and access to top-tier devices for testing (Mac, iPhone, Android, etc.)\n- Growth opportunities: Clear career development plans with performance reviews and salary discussions every 6 months\n- Full-stack exposure: Hands-on experience with both backend and frontend technologies\n- Work-life balance: 1 WFH day/week and generous time off (12+ paid leave days per year, public holidays included)\n- Health & perks: Premium health insurance and lunch allowance\n- Rewarding culture: 13-month salary, performance bonuses, and regular team bonding activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2055, 975, 2, 'Python Developer', '1. Mô tả công việc:\n- Phát triển Backend cho hệ thống quản trị và phân tích các chuỗi bất thường trong tổ chức.\n- Nhận yêu cầu từ BA/PO cùng tài liệu, hiểu và thực hiện phát triển Backend theo yêu cầu với tính năng mới hoặc improve các tính năng đã có\n- Phối hợp làm việc với các thành viên trong nhóm và công việc chuyên môn liên quan đến CNTT (SA, Frontend, Dev, Test...) trong quá trình hoàn thiện sản phẩm theo yêu cầu nghiệp vụ.\n- Viết Unit Test tùy theo yêu cầu tính năng\n- Mã nguồn đảm bảo chất lượng theo tiêu chuẩn phổ quát, được tự động phân tích bằng các công cụ chuyên dụng.\n\n2. Yêu cầu công việc:\n- Có từ 2-3 năm kinh nghiệm phát triển backend với Python, ưu tiên sử dụng FastAPI.\n- Hiểu rõ kiến trúc RESTful API, có kinh nghiệm với ORM (SQLAlchemy).\n- Tư duy logic tốt, có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh.\n- Có kinh nghiệm làm việc với Git, Docker.\n- Có tư duy phân tích nghiệp vụ và thiết kế luồng hệ thống.\n- Khả năng giải quyết vấn đề độc lập, đề xuất giải pháp kỹ thuật.\n- Có kinh nghiệm với CI/CD, AWS/GCP, Celery, Alembic.\n- Hiểu biết về bảo mật API, JWT, OAuth2.\n\n3. Đãi ngộ:\n- Mức lương up to 30M/tháng (Gross)\n- Thử việc full lương \n- Hưởng min 13 tháng lương/ năm, các khoản thưởng như thưởng lễ tết, chứng chỉ, giới thiệu ứng viên,..\n- Hưởng 12 ngày phép/năm theo quy định pháp luật hiện hành\n- Review lương 2 lần/năm (tháng 6, 12)\n- Đước cấp trang thiết bị phục vụ cho công việc\n- Hưởng các chế độ bảo hiểm xã hội, y tế theo quy định pháp luật\n- Được đào tạo, thăng tiến phù hợp trong công việc\n- Được làm việc trong môi trường trẻ trung, năng động.\n- Hưởng chế độ nghỉ mát, teambuilding, các hoạt động thể thao & giải trí phong phú\n- Remote 2 ngày/tháng\n- Thời gian làm việc: 08h30 - 12h, 13h30 - 18h, Thứ 2 - Thứ 6. Nghỉ Thứ 7, CN và các ngày lễ theo quy định\n\n4. Thông tin liên hệ:\n- Email gửi CV: linhnt@wanosoft.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2056, 264, 2, 'Bridge Software Engineer (in Vietnam)', 'Our Company\nWe’re Hitachi Digital Services, a global digital solutions and transformation business with a bold vision of our world’s potential. We’re people-centric and here to power good. Every day, we future-proof urban spaces, conserve natural resources, protect rainforests, and save lives. This is a world where innovation, technology, and deep expertise come together to take our company and customers from what’s now to what’s next. We make it happen through the power of acceleration.\n\nImagine the sheer breadth of talent it takes to bring a better tomorrow closer to today. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally as important to us.\n\nThe team\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in Japan, India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nRequirements\nThe Bridge Software Engineer who will manage projects or work closely with Project Manager to monitor and control the project; and work closely with the team to understand the project’s insights. This role needs to communicate with Japanese clients for requirements, issue clarifications to make sure that there is no gap in the understanding between customer and project team including the followings:\n- Analyze and transfer requirements to project team.\n- Verify and develop design documents.\n- Control inbound and outbound project’s materials.\n- Develop and perform test cases to verify the deliverables.\n- Understand the clients and maintain a good business relationship with them.\n\nWhat You’ll Bring\n- Bachelor’s degree with a major in software development, information technology or related fields.\n- Japanese language proficiency equivalent to JLPT N2 or higher is required.\n- At least 3 years of working experience in BrSE position, hands-on experience of writing technical document in Japanese, giving presentations, and working directly with Japanese customers.\n- Have software development skills (design, coding, test, etc.), and good programming skill/knowledge of Full-stack development (Java, React, Angular, CICD..).\n- Have knowledge UI/UX Figma is an advantage.\n- Good at requirement analysis, critical thinking and problem-solving skills.\n- Well-organized, creative, and capable of performing multiple tasks simultaneously.\n- Proficiency in English is a plus.\n\nAbout Us\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Şi Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2057, 1036, 2, 'Software Testing Engineer', 'We are seeking an experienced Testing Software Engineer with a minimum of 4+ years of experience in software testing and quality assurance. In this role, you will be responsible for designing, developing, and executing test plans and automated test suites for a range of software applications and systems. You will play a key role in ensuring that our software products meet the highest quality standards and perform as expected:\n\n- Collaborate to test projects, including planning, progress tracking, and test coverage analysis.\n- Monitors project status, test coverage, and test case/defect quality. Analyzes project cost, efficiency, and risks.\n- Collaborates with development team to define test requirements, cases, and timelines.\n- Collaborate with development teams to understand requirements and resolve testing issues.\n- Conducts and oversees various testing types (functional, regression, performance).\n- Analyzes test results and drives continuous improvement of testing processes.\n- Provides weekly project updates and reports, including achievements, issues, and risks.\n\nTECHNICAL SKILLS:\n\n- Experience in software testing, with a focus on automatic identification products.\n- Proficient in Agile development methodologies (Scrum, Kanban) and experience working in Agile teams.\n- Proficient in test management tools such as Jira, JAZZ IBM, and experience with other Agile project management tools.\n- Experience in test automation frameworks such as Robot Framework and Test Complete...\n- Experience in developing and maintaining automated test scripts using [e.g., Python, Java…].\n- Strong analytical and problem-solving skills: Ability to identify and troubleshoot complex technical issues.\n\nSOFT SKILLS:\n\n- Ability to effectively prioritize tasks and meet deadlines.\n- Excellent communication skills: Ability to clearly articulate technical issues to both technical and non-technical stakeholders.\n- Eagerness for new technologies and innovation: A passion for staying up to date with the latest testing trends and technologies in the Auto ID industry.\n\nEXPERIENCES & EDUCATION:\n\n- 4+ years of experience in automation testing SW\n- Background: Telecommunication Engineering, Computers Science and Electronic, Information Technology or related major\n- Nice to have: ISTQB Foundation certificates, Agile Foundation certificates, API Testing specialist certificates.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město - metropolitní oblast', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2058, 1074, 2, 'Senior Java Software Engineer', 'Position:               SENIOR JAVA SOFTWARE ENGINEER\nDepartment:       Engineering\nStatus:                     Fulltime        \nUpdate:                   2025\nWork location:       TT03A-13, Mo Lao New Urban, Mo Lao Sub-district, Ha Dong District, Hanoi City         \n\nOur Company\nzen8labs is a global technology consultancy founded in 2019 by our talented founders - coming from prestigious backgrounds such as Google, Facebook, and Planday... We specialize in three main areas - customer experience design, enterprise modernization, and digital transformation. Despite the short period of time, zen8labs’ portfolio of previous successes includes big names, from Vietnam corporates such as Vingroup to worldwide businesses such as Invitae (US), ClinikNote (Australia), and WebProof (Denmark)... Joining zen8labs not only allows a solid exposure to technology management but also grants the opportunity to learn from some of the best people that the industry can offer and expand one’s delivery capability.\nLearn more about zen8labs at: https://www.zen8labs.com/      \n\nReporting\nThe Senior Java Software Engineer reports directly to Project Manager and Head of Engineering.\n\nDuties and Responsibilities\nThe Senior Java Software Engineer is responsible for tasks in the following areas:  \n- Collaborate with cross-functional teams to gather and build requirements, develop technical solutions to complex business problems.\n- Maintain, extend, and implement new features following the requirements of the project.\n- Model both familiar and novel business domains.\n- Design and implement robust, security, maintainable, extendable and performant web applications.\n- Coordinate with cross-functional team, Project Manager and Customers to deliver high-quality outcomes.\n- Builds efficient working relationships with engineering team and project teams, striving to learn and gain broader technical understanding.\n- Participate in code reviews and provide constructive feedback to other developers.\n- Provide mentorship and guidance for more junior members.\n- Follow other tasks assigned by management.\n\nQualifications/ Experience Requirements:\n- Minimum 3 years of experience on web development.\n- Proficient with Java (Core Java or Spring Boot).\n- Proficient with API design, system design, software architecture.\n- Extensive knowledge of OOP, SOLID principles, design patterns.\n- Strong technical, analytical, and problem-solving skills.\n- Proficient with PostgreSQL/ MySQL/Oracle database.\n- Experienced with NoSQL database.\n- Experienced with microservices.\n- Degree in computer science or similar is required.\n\nNice to have\n- Experienced with DevOps, AWS cloud infrastructure, Kubernetes.\n- Experienced with financial systems or projects is a big plus.\n- Proficient with communication in English is a plus.\n- Understand Scrum/Agile development model.\n- Experienced with ReactJS or Angular framework.\n\nWhat we offer\n- Salary and bonus\n- Attractive salary;\n- 100% salary on probation;\n- Performance review twice a year, based on job outcomes;\n- 13 months salary and bonus assessment yearly;\n- Working time: Flexible working hours and location from Mondays to Fridays.\n- Unlimited paid leave annually;\n- Insurance, health care, and extra benefits\n- Premium PTI health care insurance;\n- Special health benefits (50% discount on medical examination fee​, 10% discount on ultrasound and procedure fees​, 5% on medicine) at 2 Clinics, including:\nVivision - 514 Bạch Mai\nPhụ Sản 1 - 329 Bạch Mai\n- An annual medical check-up;\n- Annual company trip and holiday party and other benefits according to company policy;\n- Free lunch at the office; drinks and snacks at the pantry;\n- MacBook and external monitor provided for work;\n- Working environment and development\n- Working environment: fast-moving, young, dynamic, no-walls environment.\n- Sports activities: football, exercise break.\n- Training: soft skills and technical skills training.\n- Others: free coffee/tea/cookies, parking fee, year-end party, etc…\nJoin our team to become part of an amazing group of tech talents!\nIf you are interested in this vacancy, please send your application or contact us directly via:\nEmail: hr@zen8labs.com\nMobile/Zalo: 0962019986 (Ms. Hien)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2059, 977, 2, 'Mobile Flutter Developer (Mid/Senior)', 'About The Role\nWe’re looking for experienced and passionate Mobile Front-End developers (Senior and Mid levels) interested in joining an early-stage venture to help the team scale our health tech application (+web) across the world.\nWhat you will get\n🧳 Relocation Support - We handle the move, financially and practically\n💰 Permanent Global Contract - With a seriously competitive salary\n🏥 Private Healthcare - From day one\n💻 Top-Tier Tech Setup - Brand new MacBook + full onboarding kit\n🧠 Career Growth Framework - Clear, personalised, and fast-moving\n🎯 Bonus Scheme - Performance-related, quarterly paid\n🌴 14 Days PTO + Public Holidays - Real time off\n🧪 Hybrid Working - 3 days in the office per week\n🍛 Refreshments - Free Lunch and Dinner every day for you to enjoy\nWhat You’ll Do\nSupport the entire application lifecycle (concept, design, test, release and support)\nProduce fully functional mobile applications writing clean code\nGather specific requirements and suggest solutions\nTroubleshoot and debug to optimize performance\nWork with Product development team to plan new features\nEnsure new application meet quality standards\nStay up-to-date with new technology trends.\nWhat You’ll Need\nMUST have at least 5 years of experience in Flutter (Dart)\nMUST experience with either Android OR IOS Native experience.\nDemonstrable portfolio of released applications on the App store or the Android market\nExperience with integrating mobile application to Firestore/Firebase is a plus\nFamiliarity with OOP design principles\nExcellent analytical skills with a good problem-solving attitude\nAbility to perform in a team environment\nBSc degree in Computer Science or relevant field\n4+ years of relevant industry experience for mid-level, 8+ for senior level.\nWhy join Elfie\nWe\'re a global start-up that is mission-led, and fiercely product-driven.\nWe\'re building something that improves lives - and we\'re doing it with a culture of trust, freedom, and high performance.\nAbout Elfie\nElfie is the first completely free, gamified mobile app that rewards users for managing their health. Our goal? To become the world’s largest self-reported medical record platform — across all therapeutic areas.\nWe operate in 10+ countries today, with plans to expand into 15 by the end of 2025.\n📲 Try Elfie for yourself by downloading it on the App Store or Google Play\nWhat Now?\nApply today for immediate consideration! Got someone in mind? We offer a referral reward if your recommendation is hired. Contact Talent Acquisition for more info.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2060, 1075, 2, 'Senior Java Software Engineer', 'About the Role:​\nWe are seeking a highly skilled and motivated ​Backend Java Developer​ to join our growing engineering team. You will play a key role in designing, developing, and maintaining robust, scalable, and secure backend systems and APIs that power our core applications. ​\n\nKey Responsibilities:​\n• Design,develop, and maintain our systems and APIs using Java.\n• Build microservices-based architectures using technologies such as Spring Boot, Spring Cloud, and Docker.\n• Collaborate with our team of developers to ensure that our backend systems are scalable, high-performance, and secure.\n• Write high-quality, maintainable, and testable code.\n• Debug and troubleshoot issues in our backend systems.\n• Work with our DevOps team to deploy and manage our backend systems in the cloud (cloud experience is a plus).​\n\nRequired Qualifications & Experience:​\n• Bachelor\'sdegree in Computer Science, Computer Engineering, or a related field.\n• At least 5 years of experience in Java backend development.\n• Experience with building microservices-based architectures using Docker and Kubernetes.\n• Familiarity with cloud platforms such as AWS, HuaWei, or Google Cloud (cloud experience is a plus).\n• Strong proficiency in Java and related frameworks, such as Spring Boot, Spring Cloud, Hibernate, or Struts.\n• Experiencewith agile development methodologies.\n• Excellent problem-solving skills and ability to debug and troubleshoot complex issues.\n• Strong written and verbal communication skills\n• Experienced with RDBMS like MYSQL / PG / Oracle\n• Familiarity with NO-SQL DB like Mongodb / Redis​\n\nEnjoy the freedom of ​remote work​ while being part of a ​dynamic team​. We foster a ​collaborative and supportive culture.Plus, we offer a ​competitive salary and benefits package​ tailored to your needs.\n\nReady to redefine your career possibilities?​\n👉 Apply Now! ​We\'d love to hear from you!​ 🚀', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2061, 1076, 2, 'Senior Frontend Developer (ReactJS)', 'Title: Senior Frontend Developer (ReactJS)\nDomain: Banking & Finance\nClient: Netherlands\n\n1. Qualifications:\n- 7-8 years of experience in front-end development.\n- Proficient English communication skills, equivalent to an IELTS score of 6.0 or higher.\n- Team-building capability with experience in leading development teams.\n- 5+ years of experience working with ReactJS, NextJS, Redux, Redux Saga, Redux Thunk, with a strong focus on ReactJS expertise.\n- Proficient in JavaScript, TypeScript, HTML5, CSS3, SASS or LESS, and TypeScript.\n- Experience with one or more UI libraries such as Bootstrap, Tailwind, AntDesign, Material UI.\n- Familiarity with design tools such as Figma and Photoshop.\n- Proven experience in handling real-time data updates and optimizing performance across web, responsive web, and mobile platforms.\n- Front-end performance optimization experience, including improving Google Page Speed.\n- Experience with React Native is a plus.\n- Extensive experience in improving user experience (UX).\n- Mobile development experience with React Native, including building and optimizing cross-platform applications.\n- Experience with React Native performance optimization, including handling animations, memory management, and reducing app size.\n- Familiarity with native modules and third-party integrations in React Native.\n- Experience in the banking domain.\n- Product development experience is an advantage.\n- Strong qualities of perseverance, attention to detail, and responsibility.\n\n2. Benefits:\nSalary & Allowances:\n- Salary: Negotiable.\n- Monthly performance bonus.\n- 13th-month salary + end-of-year performance bonus.\n- Lunch allowance: 500,000 VND/month.\n- Holiday bonuses (April 30 & May 1, September 2, etc.).\n- Paid leave: 12 days of annual leave.\n- Health: Social insurance, health insurance, annual health check-up.\n- Recreation: Annual company trips and quarterly team-building activities.\n- Laptop, monitor, and necessary equipment for work.\n- Remote work: Every Wednesday + 3 additional remote days per month.\n\nCareer Growth Opportunities:\n- Long-term position with training opportunities.\n- Annual salary reviews and defined promotion pathways.\n- Diverse options for career advancement.\n- Sponsorship for advanced training and professional skill enhancement.\n- Work in an international environment (Headquarters based in the Netherlands).\n\nWorking Environment:\n- Open workspace.\n- A vibrant and dynamic work atmosphere.\n- Language classes: English, Dutch, etc.\n- Clubs: badminton, soccer, pickleball, esports, etc.\n\n3. Location\nLevel 12A, Song Da Cau Giay Building, No. 18, Alley 165 Cau Giay Str, Cau Giay Dist, Hanoi\n\n4. Work Hours\n- Date: Monday to Friday (Remote on Wednesdays)\n- Time Options: 8:30 AM – 6:00 PM or 9:00 AM – 6:30 PM or 9:30 AM – 7:00 PM\n- Break: 1 hour 30 minutes\n\n5. Contact\n- Zalo/ Call: 0354.682.402 - Yen Dang\n- Mail: haiyendt.hr@gmail.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2062, 1077, 2, 'Staff', 'We are a leading company in the wireless broadband communications industry looking for talented professionals with a winning attitude.\n\nJob Description\n\n- 分析產品測試不良, 加強debug & improve test system的能力, 進而提升良率.\n- 進行維護測試環境/治具, 進而降低異常發生&重測率.\n- 依據DFM/C-flow & review process / FPYR, 讓新產品如期順利導入.\n- 協助執行流程優化&標準化, 以及工作流程持續改善, 進而達到製程穩定.\n- 透過團隊合作, 順利完成任務.\n\nEducation\n\nWork Experience\n\nLanguage', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ha Nam, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2063, 880, 2, 'Freelance Software Developer (Python-Rust) - AI Trainer', 'At Mindrift, innovation meets opportunity. We believe in using the power of collective intelligence to ethically shape the future of AI.\n\nWhat We Do\n\nThe Mindrift platform connects specialists with AI projects from major tech innovators. Our mission is to unlock the potential of Generative AI by tapping into real-world expertise from across the globe.\n\nAbout The Role\n\nGenAI models are improving very quickly, and one of our goals is to make them capable of addressing specialized questions and achieving complex reasoning skills. If you join the platform as an AI Tutor in Coding, you\'ll have the opportunity to collaborate on these projects.\n\nAlthough every project is unique, you might typically:\n\n- Analyze and understand existing code in Python or C/C++ \n- Migrate logic to idiomatic, safe Rust while preserving functionality \n- Adapt or port the test suite and ensure behavioral equivalence \n- Document migration steps and technical decisions\n\nHow To Get Started\n\nSimply apply to this post, qualify, and get the chance to contribute to projects aligned with your skills, on your own schedule. From creating training prompts to refining model responses, you\'ll help shape the future of AI while ensuring technology benefits everyone.\n\nRequirements\n\n- You have a Bachelor\'s or Master\'s degree in Software Development, Computer Science, or other related fields. \n- You have at least 3 years of professional experience with Python and 1+ year of hands-on experience with Rust\n- You are experienced with PyO3/maturin for Python-Rust interoperability as well as with automated testing (unit/integration) and benchmarking\n- You bring knowledge of Docker, Kubernetes, and CI/CD for hybrid Python-Rust apps\n- You demonstrate solid understanding of systems programming (memory management, concurrency)\n- Prompt engineering experience is a strong plus\n- Your level of English is advanced (C1) or above\n- You are ready to learn new methods, able to switch between tasks and topics quickly and sometimes work with challenging, complex guidelines\n- Our freelance role is fully remote so, you just need a laptop, internet connection, time available and enthusiasm to take on a challenge\n\nBenefits\n\nWhy this freelance opportunity might be a great fit for you?\n\n- Take part in a part-time, remote, freelance project that fits around your primary professional or academic commitments\n- Work on advanced AI projects and gain valuable experience that enhances your portfolio\n- Influence how future AI models understand and communicate in your field of expertise', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2064, 711, 2, 'Data Engineer', 'Our company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n\nDesign, build, and manage scalable and efficient ETL/ELT pipelines.\n\nDevelop and maintain data architectures (e.g., databases, data lakes, data warehouses).\n\nWork with structured and unstructured data from multiple sources.\n\nOptimize data delivery and ensure data quality, security, and governance.\n\nCollaborate with data scientists, analysts, and other stakeholders to understand data needs.\n\nWhat you’ll bring\n\nBachelor’s degree in Computer Science, Engineering, or a related field.\n\nStrong experience with SQL and relational databases (e.g., PostgreSQL, MySQL).\n\nProficiency in data processing frameworks and languages (e.g., Python, Spark, Scala).\n\nExperience with cloud platforms (e.g., AWS, GCP, Azure) and services (e.g., S3, Redshift, BigQuery).\n\nKnowledge of data warehousing concepts and tools (e.g., Snowflake, Databricks, DBT).\n\nFamiliarity with data orchestration tools (e.g., Airflow, Luigi).\n\nFluent in English communication\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion\n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow we look after you\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2065, 857, 2, 'Chuyên viên lập trình Golang', 'bTaskee › Tuyển dụng › CHUYÊN VIÊN LẬP TRÌNH GOLANG\n\nCHUYÊN VIÊN LẬP TRÌNH GOLANG\n\n- Tp. Hồ Chí Minh \n\nJob Descriptions\n- Write clean, high-quality, well-tested and maintainable code; build common libraries\n- Take part in planning, development, and maintenance of the web and apps supporting our services\n- Develop and support software including applications, database integration, interfaces, and new functionality enhancements\n- Design and implement features that support and improve the availability, scalability, latency, and efficiency of products using Golang\n- Design database schema\n- Understand the products thoroughly, constantly optimize the products, identify and fix problems, improve stability and user experiences\n\nJob Requirements\n- 2+ years of Golang experience\n- Experience in writing unit & e2e tests\n- Experience with SQL, NoSQL, Caching, MongoDB\n- Experience with RESTful API, Web, Microservices\n- Experience with Docker, Kubernetes\n- Experience with Cloud Infrastructure, CI/CD\n- Good knowledge of OOP, Design Pattern, Data Structure, Algorithm\n\nBenefits\n- Competitive salary depending on skills and capabilities\n- Bonus 13th month salary\n- All the employee’s benefits required by the Government\n- 12 annual leaves per year and other leaves/public holidays in accordance with the Labor Law of Vietnam', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2066, 1078, 2, 'Game Designer', 'A. RESPONSIBILITIES: \n- Design and balance game system, in-game economy, difficulty progression and user progression and more.\n- Research and analyze references in the market to understand the trend of game systems. Moreover, propose new ideas for features and systems based on the study of references.\n- Make sure to write all of the game design documents very clean and organized in order to facilitate the communication between multidisciplinary departments and professions.\n- Collaborate process with PM, artists, engineers to transform game concepts to high quality products with strong player engagement, retention and monetization.\n\nB. REQUIREMENTS:\nExperience:\n- Portfolio is needed.\n- Be aware and play games from various genres.\n- 2 - 3 years of experience in a Game Designer position, with at least 1 product successfully completed and released to the market;\n- Solid knowledge of casual game mechanics, game flow, and UI/UX design.\n\nGame Balancing Expertise:\n- Experience in game balancing, including in-game economies, difficulty progression, and user progression.\n\nReleased Products:\n- Published at least 2 or more completed/released products in the market, including RPG games, Hero Collection Turn-based RPGs, Idle RPGs, and Tower Defense games;\n- Experience in updating features and balancing according to the project plan.\n\nKnowledge and Skills:\n- Strong understanding of game mechanics, game flow, and UI/UX design;\n- Proficient communication skills, both verbal and written;\n- Strong proficiency in Microsoft Office tools, especially Excel and PowerPoint;\n- Analytical and statistical skills with attention to detail.\n\nPassion and Commitment:\n- Passionate about making and playing mobile games;\n- Responsible and diligent in all work tasks.\n- Language Skills:\n- Fluent in English.\n\nC. BENEFITS:\n- Opportunities to work with international and experienced talents.\n- Opportunities to attend international conferences.\n- Professional working environment\n- Team building and company trips.\n- Attractive compensation and benefits.\n- Annual health check-up.\n- 15 Annual Leave.\n- Meal allowance.\n- Free parking fee.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2067, 1079, 2, 'Generative AI Engineer', 'AI Agent Workflow Developer / Integration Engineer – Ho Chi Minh City\n\nFull-time · On\n\nBuild the brains behind Australia’s leading AI-powered strata management business.\n\nMore Than Strata just approved a bold tech roadmap: slash manual data-entry 50 %, auto-solve tickets, and email a smart digest to managers every morning. We need a TypeScript/Python engineer who lives for n8n flows & LangChain/LangGraph agents to make it real.\n\nYou will\n\nDesign a multi-agent chain that ingests Zendesk + PropertyIQ data and spits out the 08:00 “Daily Digest” email and our Committee Status reports (priority #1).\nWire up n8n flows that archive docs to Box (priority #2).\nInstrument everything with logging, OpenTelemetry & token-cost dashboards.\nLater: build a Customer/Supplier-Payment Bot that closes 80 % of “Where’s my money?” tickets on its own.\n\nYou bring\n\n3+ yrs API-heavy dev; strong JS/TS (Node) plus Python for LLM work.\nHands-on n8n or Node-RED AND real LangChain/LangGraph experiments.\nDocker, GitHub Actions, basic cloud (Azure/AWS) deployment chops.\nKeen eye for prompt design, function calls, token cost control.\nExcellent English – you’ll pair daily with Sydney product owners.\n\nWhat’s in it for you?\n\nAUD $2 000-2500 month base\nModern District 3 office\nYou ship workflows that the Managing Director measures – deliver and you unlock more projects, and fast career progression to Automation Architect.\n\nReady to code the workflows that power our growth?\n\nSend GitHub/portfolio + brief English note on an LLM project you’ve built.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه Phường Thảo Điền فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2068, 1069, 2, 'Middle Golang Developer | Upto $2000', '1. INTRODUCTION\na. About WAO Hire:\nWAO Hire company, is a collective group of tech recruiters and developers. We help fast growing companies connect with talented developers. \nWe take the humanized approach to hire and work with developers, because we know that\'s the best way to find the best developers for businesses.\n\n2. REQUIREMENTS\n- Minimum 3 years experiences of Golang development\n- Experienced in PHP frameworks Laravel to migrate project from PHP to Golang\n- Strong Knowledge of SQL DB (MySQL) operation and schema design\n- Experienced in websocket, microservice and Rest API,...\n- Experienced in mointoring system, optimize system\n- Knowledge of basic T-SQL scripting and concept ORM\n- Good self-motivate and learning independent\n- Can follow coding principle and well coding style\n- Dedicated working\n\nPlus to have:\n- Better to have experience of secondary development\n- Knowledge of DB performance analysis\n\n3. WHY YOU WILL LOVE WORKING HERE?\nBeing a member of us, you will experience a youthful, flexible, and creative work environment\n- Competitive salary ($1500-$2000)\n- Remote working\n- Working in a professional, friendly, well-equipped environment both with foreigners and Vietnamese.\n- Extensive on job training, you will always have a chance to work with new emerging technologies.\n- Social insurance, health insurance & unemployment insurance according to Vietnam Labor Law.\n- 12-day annual leave per year.\n\n5. WORKING TIME: 1:00 PM - 10:00PM from Monday to Friday\n\n6. LOCATION: Remote (HCMC)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2069, 740, 2, 'Angular Developer', 'Job Description\n\nWeb Application Development\n\n- Design and develop web applications using AngularJS and related front-end technologies\n- Build high-quality, responsive front-end interfaces aligned with UX/UI design principles\n- Develop reusable components and front-end libraries\n\nCode Integration and Backend Development\n\n- Integrate front-end UI with backend services and APIs\n- Collaborate with backend developers to ensure seamless integration\n\nQuality Assurance\n\n- Ensure the performance, quality, and responsiveness of applications\n- Conduct code reviews and integration testing\n- Implement and manage UI automation testing using Selenium and Playwright\n\nCollaboration and Agile Development\n\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Participate in agile development practices, including sprints, stand-ups, and retrospectives.\n\nRequirements\n\n- Bachelor’s degree in Computer Science, Information Technology, or related field\n- 5 years of experience in software development with a focus on AngularJS and front-end technologies\n- Experience with UI automation testing using Selenium, Playwright, or similar tools\n- Proficient in HTML, CSS, and JavaScript\n- Experience with CSS pre-processors like Sass or Less\n- Understanding of RESTful APIs, GraphQL and experience in integrating them with front-end applications\n- Familiarity with version control tools like Git\n- Experience with front-end build tools such as Webpack, Gulp, or Grunt\n- Fluent English communication\n\nBenefits\n\n- Training and career development opportunities.\n- Opportunity to approach newest technology trends; development of your career within an international Company\n- Building large-scale & global software products for our clients.\n- Onsite opportunities: short-term and long-term assignments in US, Europe, Asia.\n- Package: Project KPI bonus + Extra package: 16 Mil /employee/year (Bonus at: New Year, CMC Corp’s birthday, 2/9 and gifts,…)\n- Salary review 2 times/year or on excellent performance\n- Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (AON care premium, Company trip, Holiday, etc)\n- Working time: Monday – Friday, 8.00am/9.00am – 5.00pm/6.00pm\n\nPlease send your application via email: recruitment@cmcglobal.vn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2070, 432, 2, 'Senior ReactJS Engineer - Work in Da Nang', 'Job Description\n\n• Work on a large-scale software product in the front-end web application development project using ReactJS.\n• Work in collaborative teams with Singaporean client and building quality code. Help the team to champion software quality and engender technical vision and ensure clients are satisfied.\n• Be problem solvers, think through hard problems and work with amazing people to make the reality of the solution.\n• Practice agile software development and be a great team player.\n• Learn something new every day, work on your great innovative idea with a team to apply to the project.\n\nResponsibilities\n\nMust have:\n\n• At least 04 years experience in HTML5/CSS3 and JavaScript ES6, Javascript Modular, and OOP in JavaScript\n• Comfortable with ReactJS and keep up with the latest version to build the new application from scratch.\n• Know various asynchronous JavaScript programming patterns, React hooks, especially best practices of using Redux, Store, State Management, Context and Redux Middlewares and performance optimization.\n• Work well with Jira or TeamCity, Scrum\n• Experience working with GraphQL & Micro-Frontend architecture\n• Experience with CI/CD pipelines and implementing Unit Tests to ensure code quality and reliability\n\nNice To Have\n\n• Experience in React Native is a plus.\n\nSoft-skills\n\n• Be a problem solver with great problem-solving skills.\n• Proactive and effective self-learning skills and research.\n• Ability to work independently\n• Good in English Reading and Writing skills.\n• Effective verbal English skills in video conference and face to face communication.\n\nBenefits & Perks\n\nCompensation & rewards\n\n• Attractive and competitive performance-based compensation package\n• Generous year-end 13th-month bonus\n• Loyalty and annual dedication rewards\n\nTime off & flexibility\n\n• 12 annual leave days, 11 public holidays, 1 Christmas day off and 5 sick leave days\n• Flexible check-in time, 1-day remote work per week, and the freedom to work from any of our offices in Da Nang, Hue, or Ha Noi\n\nHealth & well-being\n\n• Comprehensive healthcare package with premium insurance and annual health check-ups\n\nTeam engagement\n\n• Team-building allowance and annual company trips for a fun and connected workplace\n• Sports & hobby clubs with football, badminton, biking, running, chess, or music band groups\n\nPersonal development\n\n• Continuous learning & development with exclusive technical & soft skills training, English classes, and technical clubs\n• Annual budget for the professional development plan, with a focus on the budget allocated for learning and certification exams.\n\nLife event support\n\n• Financial aid for marriage, newborns, and bereavement to support you through every stage of life\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه هو شي مينه سيتي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2071, 1080, 2, 'Senior Frontend Engineer (Angular) - Remote', 'Our international client is a leading cloud-based document security and data room software provider that enables customers to control, protect, and track important documents after sharing them. Companies use this platform to protect confidential information for fundraising and due diligence, secure intellectual property, and protect sensitive communications.\n\nGlobal Reach: Used in 138 countries worldwide\nUser Base: Over 600,000 users globally\nPartnership: InApps Technology serves as the technology development partner.\n\nWe are seeking a skilled Senior Frontend Engineer to join our team developing this cutting-edge document security platform. In this role, you will be responsible for developing and maintaining high-quality, scalable Angular applications while ensuring optimal performance and seamless integration with backend services.\n\nYou should have a strong grasp of Angular, TypeScript, state management, UI libraries like Ant Design, and security best practices. Writing clean, maintainable, and testable code is a key part of this role, along with implementing unit tests using Jasmine, Karma, or Jest.\n\nKey Responsibilities:\nDevelop & maintain Angular applications for the document security platform\nIntegrate Ant Design and other UI libraries\nWrite clean, maintainable, and testable code\nImplement unit tests using Jasmine, Karma, or Jest\nWork independently & ensure high code quality\nOptimize performance and ensure cross-browser compatibility\nCollaborate with backend developers & designers\n\nJob Requirement\nGood communication skills in English\n3-5 years of experience in Angular (v14+)\nProficiency in TypeScript and State Management using Angular services\nExperience in Security best practices (CORS, XSS, CSRF)\nExperience integrating Ant Design, Material UI, or PrimeNG\nExperience with Tailwind CSS for styling components\nExperience in code refactoring in conjunction with unit testing\nStrong knowledge of unit testing (Jasmine, Karma, Jest)\nAbility to work independently & deliver production-ready code\nFamiliarity with RESTful APIs and WebSocket for frontend/backend integration\n\nPreferred:\nExperience with CI/CD pipelines\nExperience in mobile application development\nExperience with Angular SSR & performance optimization\nFamiliarity with Storybook & component documentation\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2072, 1072, 2, 'Project Leader cum Bridge Software Engineer', 'JOB RESPONSIBILITIES:\n- Develop and manage multiple projects, including mobile and web applications.\n- Lead and manage software and system development projects, ensuring successful delivery within given timeframes and budgets.\n- Collaborate with stakeholders to gather and analyze the project scope and objectives, translating them into actionable plans for the development team.\n- Monitor project progress, identify potential risks or issues, and proactively implement mitigation strategies to ensure project success.\n- Provide technical expertise and guidance to the development team, assisting with complex problem-solving and ensuring high-quality deliverables.\n- Manage customer expectations and provide advice or propose new features or functions.\n- Measure, establish, and manage project schedules and work plans to ensure all parties meet project requirements, deadlines, budgets, and goals.\n- Act as a bridge between the engineering team and management, providing technical advice and reporting any issues to the CTO or CEO.\n\nJOB REQUIREMENTS:\nMust have:\n- Bachelor\'s degree or higher in software engineering, computer science, or a relevant field.\n- Minimum of 5 years of experience in the IT industry, with at least 3 years in a Project Leader/Manager cum Bridge Software Engineer role.\n- Proficiency in Japanese at least N2 level or equivalent.\n- Strong technical skills in software or system engineering, with expertise in relevant programming languages, platforms, and tools related to web applications or mobile applications.\n- Experience managing a team with at least 3 members or experience as a PM assistant.\n\nNice to have:\n- Intermediate proficiency in English.\n- Have ability to manage multiple projects simultaneously.\n- Have logical thinking skills to understand complex business systems.\n- Have strong problem-solving and decision-making abilities with a logical and analytical mindset.\n- Have PMP certification.\n\nBENEFITS:\n- Flexible working hours (8:30 AM - 9:30 AM + 8 hours from Monday to Friday).\n- Hybrid Working Time.\n- Attractive Salary.\n- Year-end reward (based on company regulations and business situation).\n- Premium Health Care (applied for full-fledged employees).\n- Annual Performance and Salary Review.\n- 15 annual leave days a year.\n- Laptop provided.\n- Mandatory insurance: based on company regulations, the probationary period is excluded.\n- Happy Hour, Company Trip, Year End Party, Events, etc.\n- Modern office and a great working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2073, 899, 2, 'Vuejs developer', 'Job Description\n\n- Design and develop innovative web applications that draw the user’s attention\n- Write reusable, effective, and scalable JavaScript code\n- Build modular and reusable components and libraries\n- Implement front-end components with progressive Vue.js framework\n- Translate the client’s technical specifications into code\n- Test, update and optimize the application for performance and security\n\nJob Requirements\n\n- Bachelor’s/Master’s degree in computer science, information technology, engineering, or anything specific degree that you prefer\n- At least 2-3+ years of experience in Vue.js and object-oriented programming\n- Proficiency in JavaScript language, including its syntax and features\n- Strong understanding of the Vue.js framework and its core principles\n- Familiarity with the Vue.js ecosystem\n- Working experience with HTML5 and CSS3\n- Knowledge of server-side rendering\n- Ability to write efficient, secure, clean, and scalable JavaScript code\n- Familiarity with automated JavaScript testing\n- Knowledge of modern development tools, like Git\n- Strong collaboration and communication skills\n- Experience in consuming and designing RESTful APIs\n- Good at English (speaking skill)\n\nCompensation & Benefits\n\n🎯Flexible working regime and health care:\n\n- Flexible timekeeping (from 8:00 - 9:00 to 17:30 - 18:30) \n- Minimum 14 paid leaves per annum for all employees after probation\n- 01-day remote work per month\n- A flexitime allowance of 90-180 minutes per month for employees\n- 01 hour paid leave per day for women having children under 12 months\n- Social insurance, health insurance, unemployment insurance and MIC care insurance \n\n🎯Transparent And Fair Benefits\n\n- Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n- Work performance review 2 times/ year (in April and October)\n- 13th-month salary\n- Bonus Policy: Public holidays (2/9, 30/4, 1/5, 1/1,...); Personal Performances; Excellent Team; Performance bonus in Token of the project;.. \n- Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company\n\n🎯Dynamic Environment And Open Culture\n\n- Year-end party, sports day, yearly company trip and quarterly team building,...with a generous budget\n- Socialize with colleagues through monthly Happy Hour \n- Monthly allowance when joining clubs: Soccer, Swimming, Yoga, Music,... \n- Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks,...\n- Flat, open and sharing culture with friendly management team; outsourcing company with product mindset \n\n🎯Strong Learning Culture\n\n- Free training courses for technical and soft skills (presentation skills, communication skills, foreign language courses,...)\n- Account to log in to our online learning system, which contains thousands of valuable lectures (LMS)\n- Participate in workshops, seminars, tech talk,... with sharing from experts inside and outside the company\n- Working opportunities with technical gurus who built and operated world-class applications with millions of users.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2074, 1081, 2, 'Engineer', 'Join Our Team at NetRayTech!\n\nPosition: Engineer\nExperience: 2+ years in engineering or technical support\nLocation: [Hangzhou, Hanoi,Jakarta, Bangkok, Manila, Kuala Lumpur, HCMC, or Remote]\nSalary: $1,500 - $2,000 monthly + Incentives + Bonus\n\nAre you a skilled engineer with a passion for technology and problem-solving? NetRayTech is expanding, and we\'re looking for a talented Engineer to partner with our Sales team in delivering exceptional solutions to our clients!\n\nAbout Us\nAt NetRayTech, we specialize in innovative technology solutions and prioritize customer satisfaction above all. Our commitment to excellence has made us an industry leader, and we’re excited to welcome driven professionals to join our journey!\n\nWhat You’ll Do:\n- Collaborate with the Sales team to develop and implement technology solutions for clients.\n- Provide technical expertise and support throughout the sales process.\n- Design and configure solutions tailored to client needs, ensuring smooth implementation.\n- Troubleshoot and resolve any technical issues in a timely manner.\n- Conduct market research to identify the latest technical advancements and trends.\n\nWhat We Offer:\n- Competitive salary range of $1,500 - $2,000/month based on experience.\n- Incentive programs to reward your performance.\n- Quarterly bonuses to recognize your hard work and technical contributions.\n- A collaborative, supportive environment where innovation thrives.\n\nQualifications:\n- Minimum of 2 years of experience in engineering or technical support, preferably in the tech industry.\n- Strong problem-solving skills and technical knowledge.\n- Ability to explain complex technical details to both technical and non-technical clients.\n- Excellent communication and interpersonal skills.\n- Self-motivated and proactive in staying updated with the latest technologies.\n- Familiarity with warehouse operations and workflow is a strong advantage.\n\nReady to make an impact in the tech industry?\nIf you’re eager to partner with a growing sales team and deliver top-notch solutions, we’d love to hear from you! Please send your resume and cover letter to hr@netraytech.com.\nBe a part of NetRayTech and help us shape the future of technology solutions! 🌟', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2075, 606, 2, 'Senior Machine Learning Engineer', 'Responsibilities\n\n1. Xây dựng, triển khai:\n- Xây dựng, vận hành các components trong MLOps platform / Develop and operate components within the MLOps platform.\n- Phối hợp cùng data scientist để xây dựng, vận hành Feature Store / Partner with data scientists to build and operate Feature Store.\n- Phối hợp cùng các đơn vị liên quan để thực hiện phát triển dữ liệu mới cho trung tâm AIC, phục vụ phát triển use-case mới / Collaborate with relevant units to develop/acquire new data sources for AIC to facilitate developing new use-case.\n- Hỗ trợ thực hiện kiểm định mô hình / Support the validation of machine learning models.\n- Hỗ trợ xây dựng kiến trúc triển khai cho use-case. Tận dụng Cloud Services và nền tảng dữ liệu lớn để tái cấu trúc và tối ưu hóa code trong môi trường tích hợp / Develop deployment architecture for machine learning model, leverage on premise and cloud based big data platforms to refactor and optimize code for production.\n- Xây dựng các pipelines phục vụ tự động hóa đóng gói và triển khai mô hình / Automate data and machine learning engineering processes.\n- Theo dõi chất lượng mô hình sau triển khai; hỗ trợ cải thiện chất lượng mô hình / Monitor model quality post-deployment; support initiatives to improve model quality.\n\n2. Nghiên cứu và học hỏi các kỹ thuật phân tích nâng cao mới\n- Nghiên cứu các phương pháp hiện đại trong học máy/AI (machine learning/AI) / Conduct research on modern methods for machine learning/AI and engineering.\n- Chủ động phân tích và khai thác các nguồn dữ liệu hiện có/mới để hỗ trợ các phân tích mang lại hiệu quả/tác động cao hơn / Proactively analyze and utilize existing/new data sources to support more impactful analyses.\n\n3. Phối hợp với các Đơn vị trong VPBtrong các bài toán phân tích nâng cao\n- Phối hợp với các trung tâm/phòng ban khác trong EDA cũng như các Đơn vị K để hiểu rõ nghiệp vụ, từ đó hỗ trợ họ khai thác/ứng dụng học máy hiệu quả hơn / Working with other centers/departments in EDA as well as Business Units to understand business problems to support them in better utilizing machine learning.\n- Hỗ trợ các trung tâm/phòng ban khác trong việc cung cấp/thực hiện các phân tích dự đoán và mô tả khi cần thiết / Support other centers/departments in providing predictive and prescriptive analyses when needed.\n\n4. Đào tạo\n- Đào tạo các thành viên khác trong nhóm EDA về học máy / Training other EDA team members on machine learning.\n\nQualifications\n\n1. Trình độ Học vấn\n- Đại học hoặc cao hơn chuyên nghành toán, thống kê, kinh tế, ngân hàng hoặc các chuyên nghành phân tích dữ liệu / Bachelor’s degree in mathematics, Statistics, Engineering, Computer Science or other Quantitative discipline.\n\n2. Kiến thức/ Chuyên môn Có Liên Quan\n- Thành thạo với SQL và chuyển đổi dữ liệu / Familiar with SQL and experience with data transformation.\n- Thành thạo ngôn ngữ phân tích dữ liệu Python hoặc R / Strong proficiency in at least one programming language Python/R.\n- Thành thạo công nghệ dữ liệu lớn, tính toán phân tán, phát triển phần mềm và trực quan hóa, học máy/AI, bao gồm Hadoop và Spark / Proficiency in big data technologies, distributed computing, software and visualization development, machine learning/AI tech stack including Hadoop and Spark.\n\n3. Các Kinh nghiệm Liên quan\n- Tối thiểu 3-5 năm làm việc trong lĩnh vực phân tích dữ liệu, mô hình học máy, làm việc với dữ liệu lớn / Min 4-5 years of solid experience in data science, machine learning or big data engineering.\n- Dày dạn kinh nghiệm thực hiện triển khai mô hình học máy lên môi trường production / Strong hands-on experiences in deploying machine learning model to production.\n- Có kinh nghiệm làm việc với môi trường cloud / Hands-on experience with cloud platforms.\n- Có kinh nghiệm diễn giải dữ liệu, làm việc với các mô hình thống kê, dự báo, các thuật toán học máy, các kỹ thuật phân tích nâng cao / Related experiences in interpreting/exploring data, working with statistical models, forecasting, machine learning algorithms, and advanced analytical techniques.\n- Các mảng kinh nghiệm liên quan đến phân tích, khám phá dữ liệu / Data mining related fields area.\n- Các công việc liên quan đến xây dựng mô hình dự báo / Predictive modelling related jobs.\n- Các mảng kinh nghiệm liên quan kĩ sư dữ liệu lớn, kĩ sư phát triển phần mềm / Big data engineering and software development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2076, 820, 2, 'Senior C++ Developer', 'MÔ TẢ CÔNG VIỆC\n\nThiết kế, lập trình và tối ưu các thuật toán xử lý ảnh và thị giác máy tính bằng C++: lọc nhiễu, trích xuất đặc trưng, đo kích thước, phát hiện lỗi, căn chỉnh 2D/3D,...\n\nPhối hợp chặt chẽ với kỹ sư quang học và phần cứng để cải thiện chất lượng hình ảnh thu được và hiệu suất hệ thống.\n\nPhân tích và xử lý các vấn đề liên quan đến chất lượng ảnh, ánh sáng, ống kính, cảm biến, hiệu chuẩn,...\n\nTích hợp các thư viện xử lý ảnh như OpenCV, Halcon, Pylon hoặc tương đương.\n\nNghiên cứu và thử nghiệm các thuật toán mới để giải quyết các bài toán thị giác phức tạp.\n\nTối ưu hiệu năng xử lý thời gian thực (trên CPU/GPU).\n\nHướng dẫn và hỗ trợ các thành viên junior, đảm bảo chất lượng mã nguồn qua review và tài liệu.\n\nYÊU CẦU\n\nTốt nghiệp đại học hoặc cao hơn chuyên ngành Công nghệ Thông tin, Điện tử Viễn thông, Tự động hoá hoặc các ngành liên quan.\n\nTừ 5 năm kinh nghiệm phát triển C++ cho các dự án liên quan đến xử lý ảnh/thị giác máy tính.\n\nNắm vững các thuật toán xử lý ảnh và sử dụng thành thạo ít nhất một thư viện như OpenCV, Halcon,...\n\nHiểu biết tốt về quang học cơ bản: hệ thống ống kính, ánh sáng, tiêu cự, trường sâu (DOF), cảm biến,...\n\nKỹ năng giải quyết vấn đề và debug tốt ở cả phần mềm và phần cứng hình ảnh.\n\nCó kinh nghiệm thực tế với hệ thống camera công nghiệp, thiết bị thị giác.\n\nGiao tiếp tốt, làm việc độc lập và phối hợp nhóm hiệu quả.\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định ky kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 30 tháng 6, 2025\n\nChi tiết công việc\n\nSố Lượng\n\n2\n\nĐịa Điểm\n\nHà Nội\n\nKinh Nghiệm\n\nTrên 5 năm\n\nTrình Độ\n\nSenior\n\nHình Thức\n\nToàn thời gian\n\nKỹ Năng\n\nC++', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2077, 1082, 2, 'Data (Python) Engineer', 'Company Overview:\niScale Solutions specializes in providing top-tier software engineering talent to clients worldwide. We are currently seeking Senior Data Engineer (ELT) and you will work as part of our team in Vietnam, with a close bond with the APAC regional team. This role design and optimize scalable, high-performance ETL pipelines using advanced Python and SQL. This is a fully remote role offering flexibility in work hours and location.\nResponsibilities:\n- Develop and maintain data pipelines to extract, transform, and load large datasets efficiently using Python and SQL\n- Ensure efficient data processing and storage across sources using PostgreSQL, Oracle, and more.\n- Tune SQL and Python code for performance, reliability, and maintainability.\n- Implement robust error handling, logging, and monitoring.\n- Collaborate cross-functionally to integrate and manage diverse data sources. \nRequirements\n- 5+ years in Data Engineering with expert-level Python and SQL skills. \n- Proven track record in building scalable ETL pipelines and working with large datasets. \n- Strong grasp of query optimization, database performance tuning, and data modeling. \n- Hands-on experience with cloud platforms (Azure, AWS, or GCP). \n- Self-starter with solid problem-solving skills\nNice to have:\n- Familiarity with GraphQL is a plus.\n- Experience with GCP Services such as BigQuery, GCP Storage, and Bigtable is a plus.\nBenefits\n- Competitive salary and benefits package.\n- Opportunity to work on a cutting-edge fintech project with a leading client.\n- Collaborative and dynamic work environment.\n- Professional development opportunities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2078, 839, 2, '[VARMETA ĐÀ NẴNG] FULLSTACK DEVELOPER - SENIOR', 'ABOUT US: Founded in 2020, Var Meta has 80+ engineers heavily focused on blockchain, virtual reality/augmented reality technologies and AI. We work with customers from different parts of the globe like Hong Kong, Japan, Singapore, US to help them build products like Crypto Trading Platforms, Launchpad, Securities Tokenization Offerings, eWallets, and NFT Marketplace, etc. We are trusted by global brands like Ubisoft, Hedera, Apto.\n\nABOUT THIS OPPORTUNITY: We\'re looking for a Full-Stack Developer to join our team with NodeJS & ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc. who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.\n\nYOU WILL:\n● Working with Product Owners to convert business requirements into technical designs.\n● Working and pair programming with other developers to build applications with Node.JS and ReactJS.\n● Design and develop scalable front-end solutions using ReactJS.\n● Build and maintain robust back-end systems with NodeJS.\n● Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n● Collaborate with cross-functional teams to define, design, and ship new features.\n● Ensure code quality, security, and performance optimization.\n\nYOUR SKILLS & EXPERIENCES:\n● Knowledge of responsive design techniques and front-end optimization methods.\n● At least 3 years of experience as a Full-Stack Developer (Node.js & React.js).\n● Strong proficiency in front-end technologies, particularly React.\n● Expertise in back-end development using Node.js.\n● Hands-on experience with Web3 integration.\n● Solid understanding of smart contract development and deployment.\n● Good command of English (both verbal and written).\n● Knowledge of cryptography and blockchain is a plus.\n\nWHY YOU\'LL LOVE WORKING HERE:\n● Build World class product(s): We love to solve complex problems and learn new things.\n● Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n● Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n● Enjoy competitive salary, bonus according to work performance.\n● 13th Salary.\n● Assistance with operational tools and equipment.\n● Health insurance program for employees provided by PVI.\n● Annual health check-up from Medlatec Clinic.\n● Participate in social insurance after becoming an official employee.\n● Salary review twice a year. It means we are pushing each other to be better everyday.\n● Flexible working hours, freestyle attire.\n\nPERKS YOU\'LL ENJOY:\n● Working in a young, super talented, and supportive team environment.\n● Technical, English certificate bonus.\n● Day-off: 12 days/year and Vietnam holidays.\n● Happy Hour, Football club, English club, and many exciting activities.\n● Company trip/ team building/ Year End Party.\n● Free coffee, snacks, and drinks.\n\nCONTACT HR VARMETA VIA:\n● Email: hr@var-meta.com\n● Fanpage: https://www.facebook.com/profile.php?id=61558234221306', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2079, 1083, 2, '[Remote - Offer 70M VND] Fullstack JS Developer - AI Native', 'We are a fast-growing, remote-first technology company transforming back-office operations for micro SMEs through innovative software, AI, and a commitment to outstanding customer experiences. As a Fullstack AI-Native Engineer, you’ll drive the creation of scalable, AI-powered solutions to revolutionize our tech landscape, enhancing efficiency, innovation, and user satisfaction. Collaborating with data scientists, product managers, designers, and DevOps teams, you’ll build robust systems with seamless AI integration, setting new standards for reliability and excellence.\n\nWe are looking for a high-quality, architecture-minded engineer who combines strong technical fundamentals with the smart use of AI tools, a focus on system reliability, and a deeply collaborative mindset. They take ownership of code quality and system stability, always striving to level up both their own work and their team’s performance.\n\nKEY OUTCOMES:\n\nDeliver High-Quality Code: Consistently submit well-documented, maintainable code with high test coverage (>80%) through PRs, following team standards and best practices.\nApply Strong Fundamentals: Design and build features applying solid software architecture (e.g., SOLID, clean architecture), efficient database design, and API best practices.\nLeverage AI Tools Effectively: Use AI coding assistants to speed up development (e.g., boilerplate, test writing, debugging) without sacrificing code quality. Share effective prompts and techniques\nContribute to System Stability: Maintain production rollback rates below 2% by enforcing thorough testing, leveraging CI/CD, and following DevOps best practices.\nEngage in Collaborative Development: Actively join code reviews, provide constructive feedback, and respond positively to feedback to boost team velocity and knowledge sharing.\n\nREQUIREMENTS\n\nExperience: 5+ years as a Fullstack Engineer, AI Specialist, or similar, with a strong track record of deploying scalable, AI-integrated applications.\nFrontend & Backend Skills: Proficient in VueJS/React and NodeJS (TypeScript), with experience building modular, reusable, and resilient microservices.\nDatabase & Architecture: Skilled in MongoDB/Supabase, REST/RPC, and designing systems aligned with Clean/Hexagonal architecture, SOLID principles, ACID compliance, and idempotency.\nAI Expertise: Experienced in AI ecosystems like LangChain and LlamaIndex, with hands-on skills in prompt engineering, RAG, and curiosity about specialized hardware like Groq.\nQuality Commitment: Dedicated to high testing standards, secure coding, and detailed documentation for AI pipelines to ensure reliable performance.\nCommunication: Strong communicator, adept at collaborating with Agile teams and connecting product, UX, data science, and engineering to drive AI initiatives.\nCloud & DevOps: Knowledgeable in AWS/GCP, serverless/PaaS solutions, and Kubernetes deployments, with a focus on MLOps and AI model lifecycle best practices.\nVersatility: Comfortable working independently or collaboratively, pushing projects from concept to production while inspiring your team.\n\nBENEFITS\n\nA remote working environment that allows you to work from anywhere in the world\nFull-time insurance follow VN Labor laws\nWork equipment support.\nAnnual bonus, performance-based bonus.\nMonthly compensation package to help you work and live better, remotely!\nFully support for exams to get Certification and skills improvement training.\nReceive 22 paid leaves on your 5th years. We encourage you to take one month off work.\nA competitive salary and benefits package\nOpportunities for professional development and career advancement with monthly coaching.\nA dynamic and innovative team that values creativity and collaboration.\n\nWORKING TIME: From Monday to Friday (8 hours/ day – VN time) - Sing client\n***Will not accept candidates who want to find second job\n\nTHE HIRING PROCESS\n\nR1: Live code + technical interview \nR2: Meet client (3 rounds)\nTake Home Assessment (Estimated time: 2 hours)\nCase study interview (~90 minutes)\nCareer Deep Dive/Behavioral fit interview (~60 minutes)\nR3: meet Founder + Offer\n\nPlease note that all rounds will be conducted in English. Ensure a stable internet connection, use a Laptop/PC with the camera on, and enable screen sharing.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2080, 690, 2, 'Quality Control Engineer (Tester)', 'Company Overview:\nTechX is a pioneer in delivering cutting-edge solutions that empower businesses to thrive in today’s digital landscape. With a strong focus on Cloud Transformation (AWS), Data Modernization, and Generative AI, we bring unparalleled expertise to drive innovation, efficiency, and growth for our clients. We specialize in banking and financial services, retail, manufacturing, and transportation, delivering impactful solutions that address industry-specific challenges & significant market changes.\n\nDescription:\nAs a Quality Control Engineer at TechX, you act as a critical filter, preventing low-quality products from reaching the market. Their efforts ensure a smooth and positive experience for end users.\n\nKey Responsibilities:\n1. Planning and Strategizing: Design and implement testing strategies, outlining how different aspects of a product will be evaluated. They also define the quality requirements a product must meet.\n2. Test Creation and Automation: Create test cases that simulate real-world usage scenarios to identify potential bugs and malfunctions. Automate repetitive tests to improve efficiency.\n3. Execution and Analysis: Execute tests and analyze the results to pinpoint defects and glitches.\n4. Reporting and Collaboration: Document bugs and issues in detail, working closely with developers to address identified problems effectively.\n5. Process Improvement: Continuously evaluate and refine the testing process, looking for ways to make it more efficient and comprehensive.\n6. Bug Validation and Supports: Maintain good bug response SLA and validate customer-submitted bugs.\n\nKey Qualifications:\n1. Testing Techniques: Knowledge in various testing techniques and methodologies.\n2. Strong in API Testing (Postman) and UI Testing.\n3. Test Planning and Strategy: Ability to develop comprehensive test plans, test cases, and test scripts. Experience in creating test strategies that cover all aspects of the software development lifecycle. Understanding of risk-based testing to prioritize testing efforts effectively.\n4. Bug Tracking and Reporting: Proficiency in using bug-tracking systems like Jira, Bugzilla, or similar tools. Ability to accurately report defects with clear steps to reproduce and necessary information for developers.\n5. Test Automation: Strong in Javascript, Playwright. Strong skills in test automation, including scripting and framework development. Experience in implementing and maintaining automated test suites for regression testing. Knowledge of continuous integration and continuous deployment (CI/CD) pipelines for automated testing (not mandatory).\n6. Communication and Collaboration: Excellent communication skills to interact effectively with cross-functional teams, including developers, product managers, and stakeholders. A collaborative approach to working closely with developers to identify, reproduce, and resolve issues.\n7. Analytical and Problem-Solving Skills: Strong analytical skills to identify root causes of defects and provide insights for process improvement. Ability to troubleshoot issues and make recommendations for corrective actions.\n\nWhat We Offer:\n1. Innovative Environment: A dynamic and collaborative work environment where innovation is encouraged.\n2. Professional Growth: Opportunities for professional growth and development through continuous learning and exposure to cutting-edge technologies.\n3. Competitive Package: Competitive salary and benefits package.\n4. Impactful Work: The chance to work on cutting-edge projects with industry-leading clients, making a tangible impact on their business success.\n\nApply now and join our mission to transform data into meaningful business outcomes!\n\nDue to the high volume of applicants, only shortlisted candidates will be contacted. We apologize for this inconvenience!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'District 3, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2081, 916, 2, 'Backend Techlead (Java/Golang/PHP)', 'About CBTW\n\nCBTW is a global independent tech consultancy group. With a team of more than 3,000 talented tech specialists on the ground in over 35 cities across Europe, the USA, Asia, Australia, and Africa, we serve clients of all sizes. We believe collaboration betters our world. Our unique open ecosystem model allows us to deliver end-to-end tech solutions\n\nAbout Our Partner\n\nOur partner is a SaaS workforce management company designed to simplify employee scheduling, time and attendance tracking, and task management for businesses. The company has helped employers across all industries in 70+ countries optimize their workforce and improve operational efficiency.\n\nAbout BOT Model\n\nOur BOT model provides a long-term solution for successfully delivering your product roadmap without outsourcing your software development. In just a few weeks, we can set up dedicated software development teams in Vietnam which will be steadily integrated into your organization and can eventually be fully transferred.\n\nQualifications\n\n3+ years experience as a Lead software engineer on high-performing, architecturally complex consumer products\nMastery of Golang, Java or PHP would be highly advantageous\nAbility to identify the technical problems to be solved within the context of their respective team/project/squad\nBreaks down problems to impactful milestones and drives the execution, collaborating and aligning with their peers\nCan perform advanced debugging and profiling (performance optimization), both within the domain and across services\nSME for a discipline/domain. Broad holistic understanding of the overall architecture and underlying systems\nAble to apply critical thinking that satisfies the business needs when proposing technical solutions\nProficient in database development, web development, windows development, source code control, configuration management and deployment\nExperience in Agile development environments\nGood verbal English communication skills, especially in the global software development environment\n\nResponsibilities\n\nAs a Technical Lead, you will lead the build of key technical projects that further the company’s products and platforms. In turn, you’ll progress our company mission of improving our customers’ business productivity, wage compliance, and employee satisfaction.\n\nYou will work closely with your peers, product, design, and leadership to build amazing products and features, delivering services and products to millions of users and businesses from small & medium enterprises.\n\nYou wake up every morning knowing with confidence that the work you do, from the user-facing experiences to the backend APIs are being used to power the livelihood of millions of users worldwide.\n\nMake technical decisions and deliver technical solutions. Use hands-on technical expertise to drive solutions for a range of challenges. You will be writing code in this role.\n\nUphold a high bar of engineering standards and coordinate with Infrastructure and Quality.\n\nCollaborate with Product and Design to discover and estimate solution options to key strategic initiatives.\n\nAccountability for delivering technical solutions within estimated timeframes.\n\nOperate in a get-things-done, value-demonstrating, iterative manner.\n\nInfluence and problem-solve with Sr, Mid and Jr. engineers to deliver high-quality outcomes. This role may not have direct reports, but your leadership and mentorship will be key to driving the squads to successful outcomes.\n\nDistribute work to Sr, Mid and Jr. engineers.\n\nForm a key member of the technical leadership team, driving standards, ways of working and platform decision-making.\n\nThis role is a player-coach.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2082, 822, 2, 'Senior Hybrid QA/QC Engineer (Manual, Automation)', 'We are looking for a QA/QC Engineer with solid testing and interpersonal skills. Candidates joining in Money Forward Vietnam will participate in a joyful, high competent and English speaking team to enhance quality for the company\'s products which are serving millions of users.\n\nResponsibilities\n- Analyze product requirement and clarify if any questions\n- Design test cases with in-depth understanding of requirements and testing techniques\n- Perform testing activities from start to delivery of tasks and tracking status of found defects\n- Participate in agile team to develop our high quality products\n- Enhance working process and share best practices to others\n- Initialize new ideas and contribute to develop QA/QC department\n- Support, review and provide necessary trainings to teammates\n\nJOB REQUIREMENT\n- 5+ years of experience in web testing\n- Good English communication and documentation skills\n- Solid skills and knowledge of testing processes and techniques\n- Experience in test automation with any frameworks, any programming languages\n- Experience in API testing with Postman or other tools\n- Experience in working in cross functional or agile teams\n- Familiar with issue and test management tools like Jira, TestRail…\n- Great interest in testing, open minded and able to self-motivated\n- Experience in performance testing or security testing is a plus\n- ISTQB or equivalent testing certificate is a plus.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2083, 1084, 2, 'Founding Tech Lead / Fullstack Engineer (AI Job Simulation Platform)', '🚫 This is not a job post.\n✅ This is a call for a builder who wants to own something from day zero.\n\nWe are NOT looking for someone who’s not looking for a job—but looking for builder who are excited about building a company. You won\'t just code. You’ll co-own. This is your shot to be the tech brain behind something big.\n\nLocation: HCMC or Remote-first if you are not based out of HCMC (Vietnam/Southeast Asia preferred)\nType: Full-time | Founding team | Equity+\nStart Date: ASAP\n\nABOUT EDTRONAUT\n\nEdtronaut is reimagining how people learn and break into the workforce—starting by learning AI through building real AI agents. Our mission is to close the gap between learning and earning with AI-powered job simulations that help learners build portfolios and eventually job matching, not just through "e-learning" (watch videos) or the traditional form of education which only provide knowledge not building skills.\n\nOne of the initial simulation track would be Building an AI Agent.\n(Think: AI-powered, modular, no-code builder that lets learners prototype and launch AI agents and solutions across job functions—from marketing assistants to automation bots, etc.)\nWe’re early but moving fast. This is the 0 to 1 moment—and we’re looking for a builder who are excited to build things and own the tech workstreams.\n\nTHE ROLE: FOUNDING TECH LEAD - FULLSTACK ENGINEER\nAs our Founding Tech Lead, you won’t just code—you’ll architect, ship, and iterate the core platform. You’ll be our go-to person for all things tech while working closely with the Founder/CEO and Product team to translate the job simulation vision into an interactive, scalable, AI-integrated platform.\n\nYou’ll be supported by a lean team of intern-level engineers (AI, frontend/backend), which means you must be highly hands-on—this is not an oversight or purely "management" role, it’s a builder\'s role.\n\nWHAT YOU WILL BUILD & LEAD\nA. MVP PLATFORM FROM SCRATCH:\nWeb app with AI Agent simulation builder (drag-drop interface or form-based schema builder)\nAI ML/LLM integration to execute agent tasks\nRole-based scenario simulation & sandbox environment\nAgent publishing & learner portfolio pages\n\nB. TECH STACK OWNERSHIP:\nArchitect a lean, scalable, modular stack (likely: React/Next.js, Node.js, Mongo/PostgreSQL, Vercel/AWS)\nBuild fast, ship often—optimize for feedback loops\n\nC. AI API INTERGRATION:\nOwn prompt flow, token usage optimization, and fallback logic using OpenAI/Anthropic\nFuture phases: LangChain, Pinecone, vector search, fine-tuned agents\n\nD. MENTOR & MANAGEMENT INTERN ENGINEERS:\nGuide junior teammates (AI engineers, frontend/back-end interns)\nPair-program, code review, and help unblock their workstreams\n\nC. COLLABORATE CROSS FUNCTIONALLY:\nWith product, UX, marketing, and curriculum teams to align user journey and tech feasibility\nCo-own roadmap with founder, contribute to product evolution and architectural decisions\n\nIDEAL CANDIDATE PROFILE\nYou’ll thrive in this role if you are:\nA hands-on builder who loves turning ideas into working products, fast\nStartup-minded: bias for action, scrappy problem-solver, loves the chaos of early stage\nFullstack-capable: confident in both frontend and backend (React + Node)\nCurious about AI and excited by its real-world potential—not just theory\nComfortable wearing many hats: from DevOps to LLM prompt tinkering\n\nTECH SKILLS WE ARE LOOKING FOR\n5–7+ years in software engineering with fullstack experience\nStrong in React.js / Next.js, Node.js, Express, MongoDB/PostgreSQL\nSolid understanding of REST APIs, data modeling, secure auth (JWT/OAuth)\nExperience integrating AI/LLM APIs (OpenAI, LangChain, etc.)\nFamiliarity with deployment tools: Vercel, Netlify, Heroku, or AWS\nBonus: interest or experience in building internal tools, LMS, or simulation platforms\n\nBONUS BUT NOR REQUIRED\nExperience working with interns/junior engineers\nExperience in EdTech, upskilling, or simulation-based platforms\nFamiliarity with AI evaluation, vector databases, or chatbot frameworks\nBasic understanding of UX/UI workflows and front-end optimization\n\nWHY THIS ROLE IS SPECIAL\nBuilder’s Dream: You\'re not maintaining legacy systems—you’ll build the entire product from 0.\nFounding Impact: Your code is the company. Everything users see and touch is yours.\nOwnership & Autonomy: You own tech strategy. Suggest tools. Define the roadmap.\nBacked by a Visionary Team: Led by a founder with global startup experience (Lazada, VinShop/One Mount Group) and global headquarter executive (Nestle, Unilever, Beiersdorf, Danone) with experience across US, Europe (Germany, France) and Asia (Singapore, Vietnam) and a clear roadmap, and top-tier university/investor networks.\nMission-Driven Product: You’ll help people break into new careers in AI, one simulation at a time.\n\nCOMPENSATION\nEquity: Significant equity option as part of the founding team\nStipend/Salary: Negotiable based on commitment and contribution\nFuture upside as we raise funding and gain traction\n\nHOW TO APPLY:\nSend us:\nYour GitHub/portfolio and LinkedIn\nA short message: "Why this? Why now?"\nBonus: Show us something you’ve built, shipped, or broken.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2084, 1085, 2, 'Senior Software Developer', 'About Us\n\nFor more than 65 years, Simpson Strong-Tie has focused on creating structural products that help people build safer and stronger homes and buildings. Considered a leader in structural systems research, testing and innovation, Simpson Strong-Tie is one of the largest suppliers of structural building products in the world where we value all members and the creativity that individuals can bring to the workplace.\n\nAs one of subsidiaries of Simpson Strong-Tie group, Simpson Strong-Tie Vietnam is a 100% foreign invested company from the US and established in 2012 to provide No-Equal Engineering Services not only in constructions engineering, mechanical engineering but also software solutions. We work as a team, grow together with quality and customer-focused mindset, collaborative spirit in order to achieve the organizational goals.\n\nBE A MAKER\n\nAt Simpson Strong-Tie, we\'ve built a workplace where people are connected and engaged in creative thinking from day one throughout their careers.\n\nWhen you think of the best a family has to offer — support, collaboration and respect — that\'s what we value at Simpson Strong-Tie. When there\'s a win, we\'ll cheer you on. When there\'s a snag, coworkers step in to help you out. Working on solutions together is just the way we do things here, and that creates an atmosphere that often feels like home.\n\nAt Simpson Strong-Tie, you\'ll find talented, passionate, dedicated, humble and genuinely kind people who are all connected by our shared mission — to provide solutions that help people design and build safer, stronger structures.\n\nIt\'s this mission and our strong people-focused values that have made Simpson Strong-Tie a unique place to work for more than 60 years — a place where you can connect, create and build your career. We invite you to learn more about our culture and why our employees are our most loyal customers.\n\nYOU\n\nYou want to be a key member of a strong team of creators who take pride in their work and support one another. As a Front-end Developer, you will be responsible for collaborating with the team to build a variety of Simpson Strong-Tie digital products, leveraging your valuable skills and competence, and contributing to the growth of the organization. You’ll focus on delivering intuitive, efficient, and innovative solutions that address business needs, helping drive progress forward. Your impact will be recognized, and if career growth is important to you, we not only know how to support your development—we\'re passionate about it.\n\nWhat You’ll Be Doing\n\nFront-end Development\n- Develop, test, and maintain highly performant and scalable code using modern front-end frameworks.\n- Build reusable and modular components and libraries for future use.\n- Ensure that the web applications are responsive, fast, and optimized for various devices and browsers.\n- Write and maintain high-quality, clean, and well-documented code that follows best practices in JavaScript/TypeScript, HTML, and CSS/SASS.\n\nArchitecture & Design\n- Lead the design and development of complex front-end applications, ensuring scalability and performance.\n- Collaborate with backend engineers to ensure seamless integration between the front-end and backend systems via REST APIs or WebSockets.\n- Influence the architecture and design decisions of the product, including component structure, state management, and data flow.\n\nPerformance Optimization\n- Optimize application performance by leveraging techniques such as lazy loading, code splitting, and asset optimization.\n- Use tools like Lighthouse and Chrome DevTools to monitor and improve front-end performance metrics like render time, and load time.\n\nCross-Functional Collaboration\n- Collaborate with multiple product teams to implement design artifacts held in Figma and similar tools into finished static resources for incorporation into Simpson Strong-Tie’s digital products.\n- Collaborate with product managers to define and implement product features and improvements.\n- Lead technical discussions with backend engineers, designers, and other stakeholders to build cohesive and efficient systems.\n- Partner with other teams across the organization to weigh in on project priorities, project estimation, and risk identification for roadmap projects.\n- Contribute to multiple releases across Simpson Strong-Tie’s digital product portfolio.\n\nMentorship & Code Reviews\n- Mentor Interns, Engineer and Associate Senior Engineer, and providing guidance on best practices, architectural decisions, and professional growth.\n- Perform regular code reviews to ensure high-quality code and provide constructive feedback.\n- Lead efforts to establish and enforce coding standards and best practices across the team.\n\nTesting & Quality Assurance\n- Ensure high code quality through the implementation of unit tests, integration tests, and end-to-end (E2E) testing using frameworks.\n- Participate in bug triaging and resolve technical issues quickly and efficiently.\n\nContinuous Improvement\n- Drive continuous improvement in front-end development processes, tools, and frameworks.\n- Stay up to date with emerging trends and best practices in front-end development and bring innovative ideas to the team.\n- Work with the DevOps team to integrate front-end applications into CI/CD pipelines and ensure seamless deployment.\n\nDesired Skills And Experience\nIf you can do everything listed above, you’ve got what it takes. Perhaps some of the following would be helpful too:\n- At least 5 years of overall software development experience, with an emphasis on web applications and front-end technologies.\n- Strong proficiency in a modern front-end framework such as React, Angular, Next, or Lightning Web Components.\n- Strong proficiency in HTML, SCSS/SASS/CSS, Javascript/Typescript.\n- Strong understanding of RESTful APIs, and real-time web technologies (e.g., WebSockets).\n- Experience with front-end build tools (e.g., Webpack, Vite, Babel, ESLint, Prettier).\n- Proficient with version control system such as GIT.\n- Proficient with JIRA and Confluence.\n- Excellent organizational and communication skills.\n- Fluent English communication skills (both verbal and non-verbal).\n- Understand and design for non-functional concerns such as performance, cost optimization, maintainability, developer experience, and responsive design.\n- Comfortable working across multiple product areas, building relationships, and connecting different workstreams into a unified system for all.\n- Familiarity with state management patterns and libraries.\n- Familiarity with cross-browser compatibility issues and ways to work around them.\n- Familiarity with web security principles and experience with front-end security vulnerabilities (e.g., XSS, CSRF).\n- Familiarity with Figma, design systems, knowledge of frameworks/tooling such as atomic design principles, design tokens, and semantic naming.\n- Familiarity with Agile/Scrum methodology.\n- Helpful if some experience with a form of SVG framework: D3, Highcharts, ReactCharts.\n- Helpful if some experience with web rendering engines like BabylonJS.\n- Exposure to cloud-based architectures like Azure.\n\nHere Is What We Offer\n- Attractive salary with 100% SHUI applied salary during probation.\n- 13th month salary, Performance Bonus, Salary review annually.\n- Opportunity to be on site in the USA.\n- Chance to collaborate and work with our global stakeholders.\n- We provide employee training & development to enhance skills set and competencies.\n- Internal training: Udemy, Pluralsight, and other online training course; TechTalk sharing within Software Development Division.\n- External training: Leadership, English, Soft Skills, ….\n- Premium health care program for you + one of your beloved ones, Annual medical check-up.\n- 14 vacation days + 1 Christmas day per year.\n- Benefits for special holidays (Birthday, Marriage, Women’s Day, Tet Holidays, Mid-Autumn, New born babies, International Children ‘s Day…).\n- Social Activities, Sports Clubs and Team-building events such as Company trip, Year-End party,… are carried out on a regular basis.\n- Young, friendly, quality and result oriented working environment under team-work spirit.\n- Modern working conditions and entertainment facilities at office with snacks, tea and coffee all the time.\n- Compliance fully to Vietnam Labor Code.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2085, 1077, 2, '工程師', 'We are a leading company in the wireless broadband communications industry looking for talented professionals with a winning attitude.\n\nJob Description\n\n- 分析產品測試不良, 加強debug & improve test system的能力, 進而提升良率.\n- 進行維護測試環境/治具, 進而降低異常發生&重測率.\n- 依據DFM/C-flow & review process / FPYR, 讓新產品如期順利導入.\n- 協助執行流程優化&標準化, 以及工作流程持續改善, 進而達到製程穩定.\n- 透過團隊合作, 順利完成任務.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ha Nam, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2086, 264, 2, 'Process Quality Assurance', 'Our Company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business with a bold vision of our world’s potential. We’re people-centric and here to power good. Every day, we future-proof urban spaces, conserve natural resources, protect rainforests, and save lives. This is a world where innovation, technology, and deep expertise come together to take our company and customers from what’s now to what’s next. We make it happen through the power of acceleration.\n\nImagine the sheer breadth of talent it takes to bring a better tomorrow closer to today. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally as important to us.\n\nThe Role\n\n- Define, customize the software development process in the projects based on the company process.\n- Monitor process compliance\n- Periodically perform process audit and product audit.\n- Prepare QA reports and send to Managers or clients as needed.\n- Consult client, Project managers, other members for process, templates, checklists.\n- Maintain QMS satisfying ISO 9001 requirement, CMMi.\n- Provide Senior Leadership Team project status report and process compliance periodically.\n- Collaborate with delivery team and VietNam QA Team to ensure the quality of project and process compliance periodically.\n- Train employees for the process, related tools and techniques.\n\nWhat You\'ll Bring\n\n- Bachelor’s degree in computer science, Information Technology or relevant major.\n- More than 2 years experiences of software development process, quality assurance (QA) or similar role.\n- Knowledge of QA process audit, product audit, statistic, quality report and analysis.\n- Knowledge of QA system development and implementation.\n- Knowledge of ISO 9001, CMMi.\n- Excellent cooperation and communication skills.\n- Responsible and proactive.\n- Ability to work independently.\n- Proficiency in English.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Phường Chí Minh, Hai Duong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2087, 732, 2, 'C++ Engineer (Operations)', 'WorldQuant develops and deploys systematic financial strategies across a broad range of asset classes and global markets. We seek to produce high-quality predictive signals (alphas) through our proprietary research platform to employ financial strategies focused on market inefficiencies. Our teams work collaboratively to drive the production of alphas and financial strategies – the foundation of a balanced, global investment platform.\n\nWorldQuant is built on a culture that pairs academic sensibility with accountability for results. Employees are encouraged to think openly about problems, balancing intellectualism and practicality. Excellent ideas come from anyone, anywhere. Employees are encouraged to challenge conventional thinking and possess an attitude of continuous improvement.\n\nOur goal is to hire the best and the brightest. We value intellectual horsepower first and foremost, and people who demonstrate an outstanding talent. There is no roadmap to future success, so we need people who can help us build it.\n\nJob Responsibilities Include, But Not Limited To The Following\n- Troubleshooting a wide range of structured and unstructured data used for quantitative analysis and financial engineering.\n- Ensure data quality throughout pipeline in both content and execution.\n- Solving problems in both usage and development of data nodes.\n- Frequent interactions with clients to understand their requirements and suggest solutions for issues reported.\n- Developing the utility tools that can further automate the operational troubleshooting and ongoing support.\n\nWhat You’ll Bring\n- Strong academic background – minimum of a bachelor’s degree in a technical or quantitative field.\n- Good knowledge of data structures and algorithms.\n- Proficiency with C++ based tools like STL, object oriented programming in C++ is a must.\n- Excellent command of English. Proactive demeanor and strong communication skills within a global team environment is a must.\n- Experience with Linux/Unix shell and Git is a must.\n- Experience with Data Engineer or similar roles is a big plus.\n- Proficiency with python based tools like Jupyter notebook, coding standards like pep8 is a plus.\n- Demonstrated ability to implement data science pipelines and real-time applications in C++ (python is a plus).\n- Experience with GDB, PDB is a plus.\n- Exceptional analytical & problem solving abilities, with a strong attention to detail.\n- Self-motivated and able to work independently with minimal direction.\n\nWhat We Offer\n- Competitive and attractive compensation package with clear career road-map – where you feel challenged everyday.\n- We offer a strong culture of learning and development: training courses, library, speakers, share and learn events.\n- Learn from who sits next to you! Working in WQ you are surrounded by smart and talented people.\n- Employee resources groups with strong diversity and inclusion culture.\n- Premium Health Insurance and Employee Assistance Program.\n- Generous time-off policy, re-creation sabbatical leave (based on tenure), Trade Union benefits for staff and family.\n- Team building activities every month: Local engagement events, monthly team lunch – Employee clubs: football, ping-pong, badminton, yoga, running, PS5, movies, etc.\n- Annual company trip and occasional global conferences – opportunity to travel and connect with our global teams.\n- Happy-hour with tea break, snacks and meals every day in the office!\n\nBy submitting this application, you acknowledge and consent to terms of the WorldQuant Privacy Policy. The privacy policy offers an explanation of how and why your data will be collected, how it will be used and disclosed, how it will be retained and secured, and what legal rights are associated with that data (including the rights of access, correction, and deletion). The policy also describes legal and contractual limitations on these rights. The specific rights and obligations of individuals living and working in different areas may vary by jurisdiction.\n\nCopyright © 2025 WorldQuant, LLC. All Rights Reserved.\n\nWorldQuant is an equal opportunity employer and does not discriminate in hiring on the basis of race, color, creed, religion, sex, sexual orientation or preference, age, marital status, citizenship, national origin, disability, military status, genetic predisposition or carrier status, or any other protected characteristic as established by applicable law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 Hanoi 하노이', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2088, 936, 2, 'VN Technology Principal Backend Engineer', 'Recruitment Background\n\nCADDi is on a mission to "Unleash the potential of manufacturing."\n\nWe operate "CADDi DRAWER," a cloud-based system that supports digital transformation centered on the use of drawings, which are the most essential data in the manufacturing industry.\n\nWe are looking for someone who can lead the technology selection and architectural decision-making processes in rapidly expanding services and organizations. The ideal candidate will also be responsible for building backend applications with a strong emphasis on sustainable operability. Additionally, this position requires the ability of developing and formulating technology strategies that align with business goals, while providing technical leadership to the development team in this position.\n\nExpected Role\n\n- Lead technology selection and architecture decisions for a rapidly expanding service and organization\n- Build back-end applications with sustainable operational viability in mind\n- Planning and formulation of technology strategy aligned with business strategy and technical lead of development organization\n\nExamples of anticipated tasks (not limited to)\n\n- Leading system requirements definition and domain modeling\n- Designing architecture of backend systems\n- Hand on the design and development of the system, including unit test & documentation\n- Implement features & integration with clean, efficient code, following best practices for software development\n- Participate in code reviews and contribute to the continuous improvement of the development process\n\nInterest And Experience Gained From This Position\n\n- The fun of integrating a complex domain into a system\n- Experience in solving difficult problems with highly motivated team members\n- Experience in contributing to the scale of a product with technical skills\n- Experience in developing products that are deployed globally\n- Experience in providing value to society through the development of products that change\n\nRequirements\n\nMUST-HAVE REQUIREMENTS\n\nFor this position, the following are strongly requested.\n\n- 8+ years of hands-on experience developing backend systems for web application\n- Experience with technology verification, requirements analysis, architecture design, and infrastructure construction for development teams or multiple projects\n- Experience in resolving issues related to technology, product, or development process\n- Experience in back-end development and operation of web applications using statically typed languages & framework\n- Proficiency in developing within a Docker native infrastructure environment\n- Fluent business communication skills in English, ability to complete daily tasks in English, including text communication and meetings.（CEFR B1 or Higher level)\n- Must currently reside in Vietnam or have plans to relocate. Foreign nationals must also hold a valid Vietnam work permit or be legally eligible to work in Vietnam\n\nNice-to-have Requirements\n\n- Experience in design and development of large systems across multiple teams\n- Experience in development based on domain-driven design\n- Experience working with Scrum or Agile methodologies\n- Experience developing in languages with strong statically typed and functional elements such as Rust, Scala, etc\n- Knowledge of front-end development, libraries & framework such as Reactjs, Next.js is a plus\n- Experience designing, developing, and operating microservices\n- Experience developing security-conscious web applications\n- Business level Japanese proficiency\n\nWE ARE LOOKING FOR THIS KIND OF PERSON\n\n- Those who can sympathize with CADDi\'s mission "Unleashing the Potential of the Manufacturing Industry"\n- Those who have a T-shaped ambition mindset to maximize their expertise by not only focusing on back-end and infrastructure, but also catching up on peripheral knowledge as needed\n- Those who are able to face essential issues and take action to solve them with a sense of ownership\n- Able to work through positive attitude and constructive discussions in fast-changing and uncertain situations\n- Able to communicate and discuss with an attitude of respect for others, taking into consideration their context and resolution\n\nPRODUCT DEVELOPING ENVIRONMENT\n\n- Front-end:TypeScript, React, Next.js\n- Backend: Rust(axum),TypeScript, Node.js (Express, Fastify, NestJS)\n- Machine Learning/Algorithms: Rust, Python, OpenCV, PyTorch, TorchServe, Elasticsearch, Vertex AI\n- Infrastructure: Google Cloud, Google Kubernetes Engine, Anthos Service Mesh, Istio, Cloudflare, Argo Workflows\n- Event Bus: Cloud Pub/Sub\n- DevOps: GitHub, GitHub Actions, ArgoCD, Kustomize, Helm, Terraform, Datadog, MixPanel, Sentry\n- Data: CloudSQL (PostgreSQL), AlloyDB, BigQuery, dbt, trocco\n- API: GraphQL, REST, gRPC\n- Authentication: Auth0\n- Development tools:GitHub Copilot, Figma, Storybook\n- Communication Tools: Slack, Discord, JIRA, Miro, Confluence\n\nRECRUITING STEPS\n\n- CV screening\n- Technical assignment (online coding test) * We place more importance on whether you can imagine that you can work together with us to develop a product, rather than on your knowledge of algorithms or the speed of your answers\n- Online English speaking test\n- Technical interview (with engineer)\n- HR casual talk *This stage does not involve selection criteria; it serves as an opportunity to align on conditions and clarify any questions regarding the selection process\n- Final interview (with CTO)\n- Offer meeting\n- Please note that, depending on the situation, additional interviews or discussions may be proposed\n- If desired, we can arrange casual interviews with employees even during the selection process. Please feel free to consult with us\n- The average time from application to offer is about one month, but if you are in a hurry, please let us know. We will do our best to adjust the schedule to fit your job search timeline\n\nBenefits\n\nAPPLICATION GUIDELINES & BENEFITS\n\n- Working style:\n- Hybrid (come to Office at least once a week)\n- Remote (depending on the case, and limited to those who can go on business trip due to Company orders)\n- Office address:\n- HCMC: 7F, Gia Loc Building, No. 27-29 Nguyen Cuu Van Street, Ward 17, Binh Thanh District, HCMC\n- Hanoi: Room 508, 5F, IDMC My Dinh, 15 Pham Hung Street, My Dinh 2 Ward, Nam Tu Liem Distrist, Hanoi\n- Employment type:\n- Official full-time employee\n- Probation period: 2 months\n- Holidays and leave:\n- Annual paid leave: 12 days\n- National holidays\n- Year-end holidays (December 31 to January 2)\n- Tet holidays\n- Others (following Labor Regulations)\n- Benefits:\n- 13th month salary\n- Salary review: twice a year\n- 100% monthly basic salary and mandatory social insurances in 2-month probation\n- Premium Health Insurance\n- Social insurance, health insurance, unemployment insurance, workers\' accident compensation insurance\n- Annual health check-up\n- Allowances such as: child-care allowance, commuting allowance, life event congratulatory gift, etc\n- Growth support such as subsidy for server fee, support for attending external training courses\n- Intensive training program (external or internal training courses, workshop etc)\n- Devices: PC and display of desired specifications\n- Awards: Company awards, every 6 month MVP awards\n- Activities: Year-end-party, team building, etc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2089, 1086, 2, 'Games Engineer', 'Location: [Hanoi or Remote] A minimum of 3 hours daily overlap with Pacific Time is required.\nJob Type: [Full-time / Contract / Hybrid]\nExperience Level: 6+ Years\n\nResponsibilities:\n- Improve and maintain client\'s game catalog.\n- Collaborate with team members to troubleshoot and resolve production issues.\n- Improve and simplify projects where possible.\n- Optimize games for performance.\n- Participate in code reviews and contribute to technical documentation.\n\nTech Stack:\n- Languages & Frameworks: JavaScript, TypeScript\n- Graphics: WebGL, OpenGL, Shaders\n- Tooling: npm, yarn\n- Development & CI/CD: Git, GitHub, GitHub Actions\n\nQualifications (Desired)\n- Strong software engineering skills emphasizing correctness and quality–do the right thing.\n- Background in games or graphics\n- Detail-oriented with a focus on clean, maintainable systems.\n- Excellent written English communication\n\nAI Requirements\n- Strong AI prompting skills for both coding and communication with the team\n- Experience with the latest models and what applications they are helpful for (coding, communication, translation)\n- Passion for exploring and utilizing AI-driven development methods to achieve superior technical outcomes and efficiency\n\nApplication:\n- Interested candidates, please send your resume and a brief introduction to info@dataxpower.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2090, 857, 2, 'Chuyên viên lập trình Golang', 'bTaskee › Tuyển dụng › CHUYÊN VIÊN LẬP TRÌNH GOLANG\n\nCHUYÊN VIÊN LẬP TRÌNH GOLANG\n\nJob Descriptions\n- Write clean, high-quality, well-tested and maintainable code; build common libraries\n- Take part in planning, development, and maintenance of the web and apps supporting our services\n- Develop and support software including applications, database integration, interfaces, and new functionality enhancements\n- Design and implement features that support and improve the availability, scalability, latency, and efficiency of products using Golang\n- Design database schema\n- Understand the products thoroughly, constantly optimize the products, identify and fix problems, improve stability and user experiences\n\nJob Requirements\n- 2+ years of Golang experience\n- Experience in writing unit & e2e tests\n- Experience with SQL, NoSQL, Caching, MongoDB\n- Experience with RESTful API, Web, Microservices\n- Experience with Docker, Kubernetes\n- Experience with Cloud Infrastructure, CI/CD\n- Good knowledge of OOP, Design Pattern, Data Structure, Algorithm\n\nBenefits\n- Competitive salary depending on skills and capabilities\n- Bonus 13th month salary\n- All the employee’s benefits required by the Government\n- 12 annual leaves per year and other leaves/public holidays in accordance with the Labor Law of Vietnam', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2091, 702, 2, 'Binance Accelerator Program - Quality Assurance Engineer, Risk', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nAbout Binance Accelerator Program\n\nBinance Accelerator Program is a concise fixed-term program designed for Early Career Talent to have an immersive experience in the rapidly expanding Web3 space. You will be given the opportunity to experience life at Binance and understand what goes on behind the scenes of the worlds’ leading blockchain ecosystem. Alongside your job, there will also be a focus on networking and development, which will expand your professional network and build transferable skills to propel you forward in your career. Learn about BAP Program HERE .\n\nWho May Apply\n\nCurrent university students and recent graduates.\n\nResponsibilities\n\n- Collaborate closely with team members to develop, test, and deliver high-quality products.\n- Understand business scenarios and technical designs to create comprehensive and effective test cases.\n- Contribute to test automation using existing frameworks or develop scripts to improve testing efficiency.\n- Execute test plans and identify issues through manual and automated testing.\n- Track defects through resolution and actively participate in project activities to ensure timely delivery.\n- Understand project dependencies and contribute to risk mitigation strategies.\n\nRequirements\n\n-  Currently pursuing an undergraduate degree in Computer Science, Engineering, or a related field.\n- Proficient in at least one programming language such as Java, Python, or JavaScript.\n- Familiarity with Linux, basic database operations, or cloud services.\n- Strong analytical and problem-solving skills.\n- Effective verbal and written communication abilities.\n- High attention to detail and a strong sense of responsibility.\n- Self-motivated and proactive, with the ability to work effectively in a team environment.\n- Previous experience in software development or testing is a plus.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Cidade de Ho Chi Minh, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2092, 743, 2, 'Software Developer (WPF)', 'Position : .NET developer\nQuantity : 01\nType : Full-time\nLocation : 68 Nguyen Co Thach street, Ha Noi.\nAbout Us\n• LTS (Lotus Technology Service) is an outsourcing company, established in 2017, We are specialized in Web development, Mobile Phone development and AI Development, our main clients are from Japan and US \n• We are now looking for good candidates for vacancies below as followings \n\nWebsite: https://lotus-ts.com/\n\nJob Description\n• Participate in development projects for WPF application \n• Able to take the role technical leader of project, propose technical solution for various problems \n• Coaching project members \n• Perform design, implement coding, testing and documentation in line with user & system requirements to deliver source code that meet the needs and release milestone \n• Perform bugs fixing, maintaining, enhancement\n\nREQUIREMENT\n• At least 1+ years of working as developers \n• Experience developing WPF/winform applications \n• .NET frameworks, C#, and associate technologies. \n• Experience using Source Control Systems (Git preferred) or similar \n• Có kinh nghiệm phát triển các plug-in cho phần mềm Autodesk Revit là một lợi thế \n• Có hiểu biết về nghiệp vụ xây dựng là một lợi thế. \n• Proficiency in English is an advantage\n\nBENEFIT\n• Attractive salary Up to 2000$. Performance based award. \n• Young and dynamic working environment. \n• Continuous development of hard and soft skills through work and professional trainings. \n• Opportunity to approach newest technology trends \n• Salary review 2 times/year or on excellent performance \n• Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)\n\nCONTACT\nLTS Recruitment Department\nContact Person: Ms Hoa\nPhone Number: 036.220.7660\nEmail: hoann1@ltsgroup.tech\nSkype: Peony.vn\nWebsite: https://career.lotus-qa.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2093, 1087, 2, '.NET Engineer', 'ABOUT SIOUX\nSioux Group was founded in 1996 and is headquartered in the Netherlands. With over 1100 engineers, Sioux supports the R&D activities of leading high-tech companies. Sioux aims to add value to its clients and build innovative solutions that contribute to a smarter, safer, healthier, and more sustainable society. At Sioux, we strive for a Culture of Excellence and grow our employees with challenging projects.\nAs a Software Engineer at Sioux, you’ll have:\nChallenging projects: work with global clients who are giant tech corporations to build complex high-tech software\nGrowing opportunity: Work with experts from around the world with a quality mindset\nA Sincere, Open, and Fair culture\nWE ARE LOOKING FOR SOFTWARE ENGINEER IN DANANG/HCM TO JOIN US!\nYour job will comprise:\nParticipate in the requirements analysis process\nCollaborate with your team lead/software architect to produce software design and architecture\nWrite clean, scalable code using .NET programming languages\nRefactor and improve the existing code base\nTest and deploy applications and systems\nDevelop documentation throughout the software development life cycle\nJob requirements\nQUALIFICATIONS\nTechnical:\nBachelor in Information Technology or Computer Science or related fields\nIdeally, a background in the semiconductor, analytical, or medical domain\nGood knowledge and practical skills in clean code, software design\nHave solid years of experience in C# .NET (from 3 years+)\nExperience with Windows Form, WPF, or WinUI3 (Desktop App build) is a significant advantage\nSoft skills:\nGood English skills, working directly with international clients\nGood sense of teamwork, high responsibility & commitment\nStrong logical thinking, proactive and open-minded\nPassionate about and eager to develop skills through projects in equipment, semiconductors, and related fields\nWHAT DO WE OFFER FOR YOU?\nCompensation & Benefits\nAttractive salary\n13th-month salary depending on the employee’s length of service\nProject Bonus (twice per year)\nSocial Insurance is based on government regulations\nFull salary during probation\nSalary reviews: 1 time/year & Promotion opportunities: 2 times /year\nWorking hours & Leave\nFlexible working hours working Monday – Friday, no OT\nHybrid working policy\n19 leave days per year, for every 3 work years, +1 day to annual leave\nWell-being\nSioux Care Package: Each employee is eligible for an assigned package (based on grade and length of service) up to VND 30,000,000/ employee/ year for well-being benefits, including Premium insurance for employee and family, Annual Health Check, Personal Development, Children’s Education, Support subscription & WFH Equipment\nTraining & Development\nCompany-sponsored training: soft skills/ technical skills/ hot-trend technologies/ best practices/English etc\nOnsite opportunities: long-term or short-term at other Sioux offices and client’s destination overseas (where applicable)\nWork anniversary bonus\n1st anniversary = 1 million\n3rd anniversary = 3 million\n5th anniversary = 10 million\n10th anniversary = 20 million\nSocial activities\nDiverse company culture activities: Company trip, Annual Year End Party, Quarterly party, Company outings, Team building, Lunch & Learn Company anniversary, Family day, X-Mas party, Mid-Autumn, Snack Friday, Food and Snack in the fridge, etc\nSports activities: Football & Badminton club\nCharity social responsibility activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2094, 1088, 2, 'System Engineer (Data Center)', 'Company Description\nFPT Telecom International Co., LTD is Vietnam\'s leading IT infrastructure and managed services provider. Established in 2008 as a member company of FPT Telecom, we offer reliable services to help businesses compete effectively and grow successfully. Our customers, including startups, enterprises, and government agencies, trust us to optimize costs, increase agility, and innovate faster.\n\nRole Description\n- Install, manage, operate & monitor server systems in the Data Center.\n- Research and study the features and technical aspects of hardware, software, and solutions from various vendors related to the system (Server, Storage, Microsoft, Linux, Cloud, Monitoring, Security, etc.).\n- Manage & operate the company\'s application and service systems.\n- Coordinate with the software unit to plan, develop & upgrade applications and services.\n- Build tools for system monitoring and troubleshooting.\n- Participate in projects, build solution packages, and provide consulting, design–deployment – maintenance, and warranty services for IT systems to deliver to organizations and enterprises.\n\nQualifications\n- Bachelor’s degree in IT, Telecommunications, or equivalent.\n- Experience as a system & data center engineer.\n- Proficiency in Linux operating systems (CentOS, Ubuntu, Debian, RedHat, etc.) & Windows.\n- Ability to use at least one programming language: Bash, Python, PHP, etc.\n- Knowledge and experience with networking (Cisco, Juniper), storage systems (NAS, SAN, CEPH, etc.), and virtualization technologies such as VMware vSAN, KVM, and OpenStack.\n- Experience in troubleshooting and resolving issues related to server hardware & Linux application systems.\n- Knowledge of CI/CD, Docker, Kubernetes, Cloud (AWS, Azure, GCP), and orchestration tools is advantageous.\n- Foreign language skills: Ability to communicate & read technical documents in English or Chinese related to the assigned tasks.\n\nBenefits:\n- Competitive salary based on skills and experience\n- Annual company trips and vacations.\n- Social insurance according to labor laws. 100% free FPT Care insurance for employees.\n- Annual health check-ups.\n- 50% discount on FPT Internet and TV services.\n- Participation in professional training courses to enhance skills and expertise.\n- Financial support for participation in courses and international IT certification exams (up to 100%).\n- Salary review based on performance and work results once a year, with the possibility of an exceptional raise based on outstanding achievements.\n\nLocation:\nFPT Building, L29B-31B-33B, Tan Thuan Street, Tan Thuan EPZ., District 7, Ho Chi Minh City.\n\nContact Points:\n- PIC: Huỳnh Vũ (Mr.)\n- Phone (Zalo): 0868 664 649\n- Mail: VuHT25@fpt.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2095, 1089, 2, 'Senior Software Engineer', 'What We Are Looking For\n\nWe are looking for a highly motivated Technical Engineer with expertise in software development, cloud platforms, and DevOps technologies. The ideal candidate will play a key role in designing, building, and maintaining our platform infrastructure, ensuring high availability, scalability, and performance. This role will involve working with Google Cloud, Kubernetes, Golang development, Elastic databases, and various automation tools to support the continuous evolution of our technical ecosystem.\n\nWho We Are\n\nAt Timebeat, we are at the cutting edge of precision time synchronisation technology, delivering world-class solutions in hardware, software, advisory services, and cloud hosting. Our start-up is built on a foundation of innovation, expertise, and an unwavering commitment to excellence. In a short period, we have achieved exceptional growth, attracted key investment, and built a team of some of the brightest technical minds in the industry. We are ambitious, forward-thinking, and on a mission to set new standards in time synchronisation technology.\n\nKey Responsibilities:\n\n• Software Development: Develop and maintain software solutions using Golang and other relevant technologies.\n• Cloud Infrastructure: Design, implement, and manage cloud-based services primarily on Google Cloud Platform (GCP).\n• Database Management: Optimise and manage Elastic databases to ensure high performance and reliability.\n• Monitoring & Observability: Implement and maintain monitoring solutions using Grafana and other tools to track system performance and health.\n• Containerization & Orchestration: Deploy and manage applications using Kubernetes and containerised environments.\n• Automation & Configuration Management: Utilise Ansible and other DevOps tools to automate workflows and infrastructure management.\n• Security & Compliance: Ensure system security, compliance, and best practices across all technical implementations.\n• Collaboration: Work closely with cross-functional teams, including developers, product managers, and operations teams, to deliver seamless solutions.\n• Incident Management: Troubleshoot and resolve technical issues, ensuring minimal downtime and optimal system performance.\n\nSkills Required\n\nTo succeed in this role, ideally, you should bring:\n\n• Proven experience in Golang development and ability to write clean, maintainable code.\n• Strong knowledge of Google Cloud Platform (GCP) services and infrastructure.\n• Hands-on experience with Elastic databases and optimising search and analytics operations.\n• Proficiency in Grafana for system monitoring and performance visualisation.\n• Expertise in Kubernetes and containerised application deployment.\n• Experience with Ansible and other automation tools for configuration management and infrastructure as code.\n• Understanding of CI/CD pipelines and DevOps best practices.\n• Familiarity with networking, security, and Linux system administration.\n• Strong problem-solving skills and ability to work in a fast-paced, collaborative environment.\n• Excellent communication and documentation skills.\n\nWhat The Team Offers\n\n• The chance to work alongside some of the brightest minds in time synchronisation technology.\n• A high-energy, fast-paced start-up environment with significant opportunities for career progression.\n• Hands-on mentorship, training, and support to help you develop into a leader.\n• The opportunity to contribute directly to the company’s rapid growth and expansion into new markets.\n• Exposure to ground-breaking technology and a chance to make an impact in industries where precision timing is critical.\n• At Timebeat, we believe that great companies are built by great people. If you have the drive, passion, and creativity to thrive in a dynamic, high-growth environment, we want to hear from you. Join us and help shape the future of time synchronisation technology.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2096, 723, 2, 'Tuyển dụng vị trí Software Tester', 'Địa điểm làm việc: Công ty Cổ phần Dịch vụ Di động Thế Hệ Mới (NMS) – Tầng 3A, tòa nhà Mỹ Đình Plaza, 138 Trần Bình, Nam Từ Liêm, Hà Nội.\n\nSố lượng: 01\n\nVị trí: Kiểm thử phần mềm\n\nMÔ TẢ CÔNG VIỆC\n\n– Tạo test case, test report cho dự án phần mềm.\n\n– Tiến hành kiểm thử, báo cáo lỗi.\n\n– Viết tài liệu sử dụng cho dự án\n\nYÊU CẦU\n\n– Tốt nghiệp cao đẳng hoặc đại học ngành CNTT.\n\n– Đã có kinh nghiệm 01 năm trở lên.\n\n– Ưu tiên ứng viên có kinh nghiệm với hệ điều hành Linux, Unix\n\n– Sử dụng thành thạo MS Office.\n\n– Ưu tiên ứng viên có khả năng sử dụng tiếng Anh đọc và viết.\n\n– Ưu tiên ứng viên có khả năng sử dụng các công cụ để thực hiện test.\n\nQUYỀN LỢI\n\n– Lương hấp dẫn, thưởng theo năng lực.\n\n– Chính sách thưởng theo kết quả làm việc, thưởng ngày lễ, thưởng thành tích tháng…\n\n– Cơ hội được tự xây dựng đội ngũ mới, trải nghiệm và thử thách với yêu cầu công việc của khách hàng quốc tế\n\n– Cơ hội thăng tiến và phát triển bản thân lên các vị trí quản lý\n\nThông Tin Liên Hệ\n\nGửi CV qua email: thempt@nms.com.vn\n\nLiên hệ phòng HCNS – Ms.Thêm 0473008555 – 0982 901 255', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2097, 1090, 2, '[HCM] Middle/Senior Manual QA (Agile, QA QC)', 'We are seeking a skilled QA Engineer to join our team. This role supports testing across Windows applications, mobile apps, devices, or web, with a focus on a Windows-based video capture application integrated with a cloud service. You will work independently, applying your Windows testing experience to ensure quality based on requirements. You’ll collaborate with developers and stakeholders to deliver reliable software, leveraging your expertise without needing detailed “how-to” training.\n\n1.Responsibilities:\n- Develop and execute test plans and cases, performing functional, regression, integration, performance, and exploratory testing.\n- Identify, document, and track defects in tools like Jira, collaborating with developers and QA peers to resolve issues.\n- Work with cross-functional teams to define requirements and participate in Agile/Scrum ceremonies (sprint planning, stand-ups, retrospectives).\n- Track quality metrics and provide concise reports on test results, coverage, and system quality.\n- Manage task priorities, recommend trade-offs when needed, and contribute to improving QA processes and tools.\n\n2.Requirements:\n- 3-5 years of experience in software testing or quality assurance, preferably on Windows platforms.\n- In-depth knowledge of the Windows operating system and proficiency with its tools (e.g., Event Viewer, CMD/PowerShell, Resource/Performance Monitor).\n- Basic understanding of networking concepts and troubleshooting (e.g., private vs. public networks, NAT, firewalls, ping, tracert, IPv4).\n- Expertise in manual testing with a strong grasp of testing methodologies, including functional, regression, and performance testing.\n- Good at written and verbal communication skills in English.\n- Familiarity with Software Development Life Cycle (SDLC) and Agile methodologies, along with tools like Jira.\n- Strong analytical mindset and problem-solving abilities.\n\n3.Why you will love working at Yoong:\n- Competitive salary with a 13th-month bonus and performance incentives.\n- Provision of a new Macbook Pro.\n- Overtime compensation.\n- Monday to Friday work schedule, plus 12 annual leave days and 11 public holidays.\n- Opportunity to enhance English skills through interaction with international clients and products.\n- Regular performance-based salary reviews.\n- Monthly team-building activities.\n- Company trips.\n- Comprehensive employee insurance prescribed by law.\n- Annual health check-ups.\n- Access to personal development courses, including both technical and non-technical programs.\n- Hands-on experience with advanced technologies.\n- Complimentary snacks, coffee, tea, and cakes.\n\n4.Working Location:\nETOWN CENTRAL BUILDING, 07 - 11 Doan Van Bo Street, District 4, HCMC.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 4, Ho Și Min, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2098, 1091, 2, 'Quality Assurance Lead', 'Job Summary:\nWe are looking for Senior QA Lead to join our growing team. You will be responsible for ensuring the quality and reliability of our web and mobile applications while working closely with developers, product managers, and stakeholders in an Agile environment.\nThis role requires strong analytical skills, test case design expertise, and the ability to work independently while taking ownership of quality assurance.\n\nKey Responsibilities:\n1. Test Strategy & Planning:\nDefine, create, and maintain comprehensive test plans for web and mobile applications.\nDevelop structured test case scenarios (positive, negative, boundary, exception) using appropriate techniques (e.g., decision tables, state transition, equivalence partitioning).\nEnsure that all test plans align with both Agile and Waterfall methodologies, depending on project requirements.\nIdentify gaps in product requirements during grooming sessions and proactively suggest improvements.\n\n2. Testing Execution & Defect Management:\nPerform functional, regression, security, and integration testing for web and mobile applications.\nDetect and log defects using Jira or similar tools, track issues to resolution, and ensure proper communication with stakeholders.\nConduct exploratory and usability testing to identify edge cases and potential user experience issues.\nWork closely with developers and product managers to ensure timely bug fixes and incident handling.\n\n3. Specialized QA Focus Areas (Based on Team Placement)\nCamp A (User & Communication):\nStrong focus on authentication, authorization, access control, and security vulnerabilities.\nAbility to create robust integration test plans that ensure smooth interactions between security components.\nWork well under high-pressure environments and manage tight deadlines while maintaining high quality.\nAlways innovating and proposing new solutions to improve security, reliability, and efficiency in testing processes.\n\nCamp B (Scheduling / Lesson):\nStrong focus on data integrity, data migration, and database testing.\nExperience with large-scale data management, data quality validation, and API interactions.\nAbility to analyze data flows across systems, ensuring data consistency and accuracy across multiple platforms.\nUsability testing.\n\nCamp C (Order):\nStrong accounting knowledge and ability to validate financial calculations, reconciliation, and compliance requirements.\nExpertise in decision table testing and structured test case design based on Japanese quality standards.\nEnsure accuracy and compliance in financial transactions, detecting anomalies in calculations, invoicing, and transactions.\n\n4. Test Automation & CI/CD (Mandatory):\nStrong foundation in automation testing with the ability to write and maintain automated test scripts.\nHands-on experience with test automation frameworks such as Playwright, Robot Framework, or similar.\nAPI automation experience is required, with proficiency in Postman or Karate.\nAbility to integrate automated tests into CI/CD pipelines (GitHub Actions, GitLab, Bitbucket, or similar).\nStrong scripting skills in JavaScript, Python for automation purposes.\n\nRequirements:\nMust-Have:\n5+ years in QA and 2+ years at the same role with management experience.\nProven experience in automation testing using Playwright, Robot Framework, or similar.\nStrong test case design skills using industry-standard techniques (decision tables, equivalence partitioning, boundary value analysis, state transition).\nExperience with API automation using Postman, Karate, or similar tools.\nHands-on experience with SQL for validating and verifying backend data.\nStrong analytical skills to break down requirements, identify missing scenarios, and suggest test coverage improvements.\nExperience with defect tracking tools like Jira and test management tools like TestRail or Qase.\nProactive ownership mindset - able to work independently and take full responsibility for QA efforts in the team.\nEnglish proficiency (Intermediate or above, TOEIC > 650) - able to communicate effectively in an international team.\nAutomation skills (Playwright, TestCafe, or other frameworks).\n\nNice to Have (Highly Preferred):\nSalesforce or ERP system experience.\nHands-on experience with API testing using Postman/Karate.\nExperience in performance testing.\nPrefer to have the ISTQB certificate.\nExperience in onboarding automation within the team or teaching it to the team.\n\nBenefits when working with us:\nAn opportunity to grow in a fast-developing education technology.\nProbation: 2 months (100% full-time salary).\n13th-month & performance bonus.\nTeam party celebration fee support.\nCompany health check every year.\nFull social insurance and private Bao Viet healthcare insurance.\n14 days paid leave annually.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2099, 1092, 2, 'Chuyên viên/Chuyên viên Cấp cao/Chuyên gia Kiểm thử Phần mềm - Phòng Phân tích Nghiệp vụ - Khối Công nghệ', 'Mã công việc: 177 Độ tuổi: 25 - 35 Số năm kinh nghiệm: 01 Thời gian làm việc: Toàn thời gian Địa điểm: Hà Nội Ngày hết hạn: 30/11/2024 Giới tính: Nam/Nữ Trình độ ứng viên: Cử nhân\n\nNhiệm Vụ Chính\n\n- Xây dựng kế hoạch kiểm thử (test plan), thiết kế kịch bản kiểm thử (test case) theo tài liệu mô tả, phân tích yêu cầu;\n- Thực hiện kiểm thử các ứng dụng;\n- Quản lý, phân tích và theo dõi kết quả kiểm thử, báo cáo kết quả kiểm thử, đảm bảo chất lượng phần mềm trước khi đưa lên Production;\n- Phối hợp và hỗ trợ bộ phận nghiệp vụ, người sử dụng cuối xây dựng kế hoạch, kịch bản kiểm thử từ người sử dụng (UAT);\n- Hỗ trợ người sử dụng cuối thực hiện kiểm thử UAT, ghi nhận các lỗi phát sinh; phối hợp phân tích nghiệp vụ và kỹ thuật viên lập trình điều chỉnh hệ thống,\n- Viết tài liệu hướng dẫn sử dụng cho người dùng cuối;\n- Hỗ trợ sau golive (hỗ trợ người dùng cuối ở mức level 2);\n- Phối hợp với lập trình viên để phân tích lỗi và sửa lỗi;\n- Thực hiện các công việc được giao bởi cấp quản lý trực tiếp.\n\nYêu Cầu\n\n- Tốt nghiệp Đại học, chuyên ngành đào tạo: Công nghệ Thông tin, Toán tin, Ngân hàng - Tài chính…;\n- Có kiến thức tổng quan về ngân hàng và am hiểu nghiệp vụ ngân hàng;\n- Có chứng chỉ đào tạo về kiểm thử là 1 lợi thế;\n- Ưu tiên ứng viên có kinh nghiệm kiểm thử với các hệ thống core thẻ, core-banking, internet banking, mobile banking…;\n- Có năng lực tổ chức, triển khai công việc công việc;\n- Kỹ năng giao tiếp: Kỹ năng đàm phán thương lượng;\n- Tinh thần trách nhiệm cao và khả năng điều hành công việc tốt.\n\nEMAIL NHẬN HỒ SƠ: Tuyendung@ncb-bank.vn.\n\nTIÊU ĐỀ EMAIL: Địa điểm - Vị trí ứng tuyển - Họ và tên.\n\nỨng tuyển', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2100, 707, 2, 'Manual QC Engineer (Middle)', 'Job Description\n\n- Communicate to project stakeholders (managers, client and team) to analyse, clarify requirements\n- Develop test plan for the system\n- Define test cases or develop automation scripts for assigned features \n- Execute test process with created test cases on assigned features\n- Create reports with details on found issues\n- Contribute ideas to optimize working processes\n\nJob Requirements\n\nMUST HAVE\n\n- At least 2 years of experience in web and mobile app testing.\n- Having solid knowledge of test cases design techniques and testing strategies\n- Good at English communication\n- Experience in test Web Services, API using tools like Postman\n\nNICE TO HAVE\n\n- Experience in using SQL\n- Experience API test with Postman scripts\n- Experience in domains: Healthcare, FinTech, Fleet Management\n\nBenefits\n\nCompetitive Salary and Brilliant Health Benefits\n\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan \n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program \n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support.\n- Surrounded with friendly, open-minded, young and supportive colleagues \n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2101, 182, 2, 'Senior Java API Engineer', 'About our Team:\n\nOur team is responsible for creating a brand of new digital financial platforms and apps that are highly reliable and scalable using modern engineering practices. You will be joining a project which talented software engineers in our Digital Bank Build team who is responsible for designing, building, and maintaining the new digital banking platform and the customer channels. As part of the team, you will be responsible for implementing software features, involve in technical designs, and writing tests to ensure the high-quality delivery of the product. The teams operate in Scrum and DevOps models.\n\nWe\'re looking for top engineers out there! During the interview process, we will test your coding and design skills to assess your experience and depth of knowledge. Don\'t worry our interview process will be fun!\n\nResponsibilities:\n\n- As a backend engineer, you will be working within a specific problem where you will design, develop, and deploy backend services with a focus on scalability, high availability, and low latency\n- Drive the efficient delivery of change through analysis, definition, and documentation of requirements whilst identifying potential solutions using agile delivery frameworks\n- Solve complex technical and business problems and learn new technology and frameworks\n- Be part of a team that will take full responsibility for the features you own\n- Design, develop, test, deploy, monitor, and improve, you are responsible for the full life-cycle of your product - build it, own it\n\nRequirements\n\nYou will be a perfect match if your profile ticks some below items:\n\nMust-have:\n\n- A pragmatic mindset\n- Outstanding problem-solving ability, eagerness to learn, and curiosity\n- A few years of software development experience with one or more general-purpose programming languages\n- Strong database and schema design for large-scale applications\n- Adaptable attitude and personality that is ready for continuous change\n- Collaboration and culture fit in the Agile experience will be an advantage\n- Good English skills\n\nNice to have:\n\n- Experience in developing distributed systems on top of micro-services architecture, event-driven architecture using Java, Spring and Spring boot, Kafka, Redis, etc. is a big plus\n- Experience in AWS, Ansible, Packer, Docker, Rancher, and K8s is a big plus\n- Experienced in automated testing frameworks is a plus\n- Good English listening and speaking is a big plus\n- Experience working in the banking and the financial domain is a plus\n\nBenefits\n\n- Meal and parking allowance are covered by the company\n- Full benefits and salary rank during probation\n- Insurances such as Vietnamese labor law and premium health care for you and your family\n- Learning and Development: Access to SMART goals, technical seminars, conferences, career talks, and overseas training to accelerate your career advancement and ensure continuous growth.\n- Values-driven, international working environment and agile culture\n- Overseas travel opportunities for training and working related\n- Internal Hackathons and company\'s events (team building, coffee run, blue card...)\n- 13th-month salary and performance bonus\n- 15-day annual + 3-day sick leave per year from the company\n- Work-life balance 40-hr per week from Mon to Fri', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 ホーチミン', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2102, 1093, 2, 'Senior Front-end Developer', 'We’re a growing startup building a platform that provides B2B services in the gaming industry. Our focus is on developing innovative gaming solutions for the regulated market. Backed by a Dubai-based conglomerate, our goal is to become a leader in the iGaming space, competing with established companies like Evolution, Playtech, and Pragmatic Play.\n\nHeadquartered in Singapore, we have development offices in Vietnam and are expanding into Thailand and Europe. With plans to go public in the next two years, we’re excited to share the opportunities that are driving our growth.\n\nRESPONSIBILITIES: \n\n- Design, develop, and implement user-facing features using ReactJS and NextJS.\n- Optimize web applications for performance, scalability, and cross-browser compatibility.\n- Lead the implementation of Server-Side Rendering (SSR) and Client-Side Rendering (CSR) for complex features.\n- Ensure clean, maintainable, and scalable code through adherence to industry standards and peer code reviews.\n- Debug and resolve performance bottlenecks using tools like Sentry, Kong logs, and Cloudflare.\n- Translate wireframes and prototypes into high-quality, responsive, and accessible code.\n- Collaborate with UI/UX designers to deliver user-centric and consistent experiences.\n\nSystem Integration & Maintenance\n\n- Work closely with backend teams to integrate APIs seamlessly into the frontend.\n- Participate in deployment processes and ensure system stability through efficient debugging and issue resolution.\n\nCross-Functional Collaboration\n\n- Collaborate with stakeholders to analyze requirements and break them into actionable technical tasks.\n- Work with cross-functional teams (backend, QA, DevOps) to ensure the successful delivery of projects.\n\nQUALIFICATIONS:\n\nMUST TO HAVE:\n\n- Education: Bachelor’s degree in Information Technology, Computer Science, or related fields.\n- 5+ years of experience in frontend development with strong expertise in ReactJS, NextJS, and modern JavaScript.\n- Proficient in state management tools like Redux, Recoil, or similar libraries.\n- Hands-on experience in building responsive, cross-browser-compatible, and accessible web applications.\n- Hands-on experience with Node.js to develop APIs and optimize SSR logic.\n- Familiarity with modern frontend tools and workflows (e.g., Webpack, Vite, Git).\n- Basic understanding of AWS S3, Cloudflare, or similar tools for asset delivery.\n- Capable of translating business requirements into technical solutions.\n- English proficiency\n\nNICE TO HAVE\n\n- Strong problem-solving skills.\n- Familiarity with Agile/Scrum\n- Preferred Skills (but not required):\n- Has knowledge of design, and coding principles (e.g.: clean code, DRY/KISS, SOLID)\n- Has knowledge of Postgres, KAFKA, Elasticsearch, S3/Minio\n- Knowledge of testing frameworks like Jest, React Testing Library.\n- Familiarity with CI/CD pipelines for frontend applications.\n- Experience with Online Games is a plus.\n\nWE OFFER:\n\n- Recognition from the business translated into a competitive salary and a supportive attitude.\n- A healthy mix of a startup-like culture, which enables us to try new approaches and technologies and remain on the edge of technological development and enterprise, with stability and supporting functions to help you focus on your job. \n- Health insurance, contemporary office environment, tech conference attendance, training, hackathons, and other benefits and perks.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2103, 1094, 2, 'QA Engineer', 'Gamota là một trong những nhà phát hành game mobile hàng đầu tại thị trường Việt Nam với hơn 35 triệu khách hàng, hơn 10 năm kinh nghiệm và hơn 150 tựa game đã ra mắt. Xây dựng môi trường làm việc trẻ trung, năng động với tinh thần làm việc chủ động, nhiệt huyết với tinh thần sáng tạo cao.\n\nHiện tại Gamota đang tìm kiếm CORE TALENT cho vị trí "QA Engineer" :\n\nMÔ TẢ CÔNG VIỆC:\n- Xây dựng và triển khai các công cụ kiểm thử tự động hóa để cải thiện quy trình QA.\n- Kiểm tra API và debug các vấn đề liên quan đến request/response.\n- Viết và quản lý test case, thực thi các ca kiểm thử thủ công và tự động.\n- Thực hiện kiểm thử chất lượng sản phẩm game mobile, đảm bảo đáp ứng yêu cầu và tiêu chuẩn kỹ thuật.\n- Sử dụng các công cụ giám sát, phân tích log và thiết bị kiểm thử (như AWS Device Farm) để đảm bảo tính ổn định và đa dạng thiết bị.\n- Phối hợp chặt chẽ với các nhóm business và tech để hiểu rõ yêu cầu, đưa ra phương án kiểm thử phù hợp.\n- Tham gia phân tích và review code khi cần thiết, hỗ trợ phát hiện và báo cáo lỗi chi tiết.\n- Học hỏi và áp dụng các công nghệ mới nhằm nâng cao hiệu quả kiểm thử. Đảm bảo tài liệu kiểm thử được cập nhật và quản lý chặt chẽ trên các công cụ như Git, Jira.\n\nYÊU CẦU:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc lĩnh vực liên quan.\n- Kiến thức lập trình: Hiểu biết cơ bản để có thể đọc hiểu các tham số request/response của API.\n- Có kinh nghiệm triển khai automation test cho sản phẩm là 1 lợi thế.\n- Kiến thức QA: Viết testcase, API Testing, khả năng làm việc với các phần mềm detect các request gửi lên từ Web,Mobile như: Charles Proxy...\n- AWS Device Farm: Có kinh nghiệm sử dụng AWS Device Farm hoặc các nền tảng kiểm thử tương tự.\n- Kỹ năng phân tích: Khả năng đọc hiểu code, phân tích yêu cầu, và làm việc với các tài liệu kỹ thuật.\n- Kỹ năng giao tiếp: Làm việc hiệu quả với các nhóm liên phòng ban (business, tech, QA).\n- Có kinh nghiệm với các công cụ quản lý như Git, Jira, và các hệ thống giám sát (Prometheus, Grafana) là một lợi thế.\n- Đam mê với ngành game và tinh thần học hỏi không ngừng.\n\nQUYỀN LỢI:\nPhúc lợi tài chính minh bạch và toàn diện:\n- Chính sách xét điều chỉnh tăng lương 6 tháng/lần (Đánh giá theo hiệu xuất, kết quả công việc và năng lực)\n- Ghi nhận sự đóng góp thông qua các khoản thưởng phong phú, hấp dẫn góp phần gia tăng thu nhập của nhân viên: Thưởng các ngày lễ 30/4-01/05, 02/09, Tết dương lịch, thưởng dự án, thưởng KPI, hiệu suất công việc hàng tháng, thưởng quý và lương tháng 13…\n- Được hưởng các mức Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n- Gói chăm sóc sức khỏe định kỳ hằng năm tại các Bệnh viện Đại học Y Hà Nội và Saigon Healthcare.\n\nChú trọng phát triển năng lực mỗi cá nhân:\n- Chính sách hỗ trợ khuyến khích học tập, khen thưởng dành cho nhân viên đạt chứng chỉ đào tạo.\n- Được đào tạo và phát triển theo khung năng lực và lộ trình nghề nghiệp của từng vị trí thông qua các khóa đào tạo miễn phí trên hệ thống đào tạo trực tuyến E-learning Appota, các khoá học hàng đầu của Coursera, Udemy.\n- Được tham gia các Workshop, Master talk, CEO talk chia sẻ kiến thức và kinh nghiệm từ các chuyên gia trong và ngoài Công ty.\n- Có lộ trình thăng tiến rõ ràng. Chính sách luân chuyển công việc linh hoạt và cởi mở nhằm thúc đẩy nhân viên khám phá sức mạnh tiềm năng của bản thân và thử thách với những cơ hội mới.\n\nVăn hóa làm việc độc đáo:\n- Tại Appota, mỗi nhân viên sẽ được làm việc mình thích, thích việc mình làm với văn hóa "No Boss Just Leader" cùng 7 giá trị cốt lõi IAPPOTA.\n- Mỗi cá nhân được trao quyền chủ động trong mọi việc, phát huy các thế mạnh, phá bỏ khuôn mẫu và sáng tạo theo phong cách riêng.\n- Được dẫn dắt, định hướng bởi định hướng bởi đội ngũ BOD có tầm với kim chỉ nam tập trung vào phát triển giá trị con người và tinh thần startup mạnh mẽ.\n- Môi trường trẻ trung, năng động và sáng tạo, nơi mọi ý tưởng táo bạo được đón nhận.\n\nTrải nghiệm sự chăm sóc tinh thần tận tâm và chu đáo:\n- Được chăm sóc tỉ mỉ từ những bữa ăn sáng, ăn chiều miễn phí với chi phí 2.000.000/người/tháng và tận hưởng không gian cafe hiện đại dành riêng cho nhân viên.\n- Được trải nghiệm các hoạt động gắn kết đa dạng: Các hoạt động team building, chương trình Friday Frenzy, Đại tiệc sinh nhật công ty kết hợp du lịch hàng năm lên tới 10.000.000/người/năm, hội Chợ Tết độc lạ và các hoạt động thể thao thường niên khác, …\n- Được thỏa sức tham gia các câu lạc bộ đa sắc màu: CLB Yoga, Bóng đá, Game Esports, Cầu lông, Zumba…\n\nĐịa điểm làm việc:\n- Tòa LE Building, Số 11, Ngõ 71, Phố Láng Hạ, Phường Thành Công, Quận Ba Đình, Thành phố Hà Nội, Việt Nam.\n\nKhám phá văn hoá Appota tại:\n- Website: Appota.com\n- Fanpage: https://www.facebook.com/appotacareers\n- Tiktok: https://www.tiktok.com/@appotagroup\n- Youtube: https://www.youtube.com/@Appota.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2104, 1095, 2, 'Senior Software Development Engineer (VN)', 'At AT Dawn Technologies, our culture is built around openness, innovation, and excellence. We foster an open environment where ideas flow freely, every voice is valued, and innovation thrives. With a relentless focus on customer success, we align our efforts to deliver transformative solutions that truly make a difference. Agility and adaptability are in our DNA, enabling us to respond swiftly to change and stay ahead in the dynamic tech landscape. Collaboration and teamwork form the backbone of our approach—our technologists and thinkers work hand-in-hand, breaking silos to deliver exceptional results. We champion continuous learning and development, encouraging everyone to explore, experiment, and grow both personally and professionally. With an extremely lean hierarchy, we empower individuals to take ownership, drive decisions, and contribute meaningfully. At AT Dawn, we’re not just building solutions; we’re creating a community of innovators united by a shared passion for excellence and customer-centric impact.\n\nJob Overview\n\nWe are looking for a highly skilled Senior Software Development Engineer with strong experience in Java-based backend development and working knowledge of Python. You will play a key role in designing, developing, and maintaining scalable backend systems that power our core products. This is an opportunity to help build first-in-class platforms for LLM based applications and agentic frameworks and is a real opportunity to develop a first-in-class platform. This position is ideal for someone who enjoys solving complex problems, working with distributed systems, and collaborating across teams to deliver high-performance software. You will be client facing.\n\nResponsibilities\n- Design, implement, and maintain scalable, reliable backend services using Java (Spring Boot / Micronaut / etc.)\n- Collaborate with front-end engineers, product managers, and DevOps to deliver end-to-end solutions\n- Integrate and interact with databases (SQL and NoSQL), messaging queues, and 3rd-party APIs\n- Write clean, efficient, and testable code in both Java and Python\n- Contribute to the design of system architecture and make decisions on tech stack and frameworks\n- Optimize performance of microservices, conduct code reviews, and maintain high code quality\n- Participate in Agile development processes, sprint planning, and retrospectives\n- Troubleshoot and debug production issues as needed\n- Implement security best practices to ensure data integrity and protection\n- Stay up-to-date with the latest industry trends, technologies, and best practices\n- Mentor junior developers and contribute to team knowledge sharing.\n\nRequired Qualifications\n- 5 to 8 years of professional experience in backend development with Java\n- Solid experience with frameworks like Spring Boot, Hibernate, or similar\n- Experience building scalable platforms for millions of users dealing with high concurrency, low latency and ultra-reliable service\n- Proficiency in Python for scripting, automation, or service development\n- Strong understanding of RESTful API design, microservices architecture, and asynchronous processing\n- Experience with relational databases (e.g., PostgreSQL, MySQL) and NoSQL (e.g., MongoDB, Redis)\n- Familiarity with CI/CD pipelines, Docker, and cloud platforms (AWS, GCP, or Azure)\n- Strong problem-solving and debugging skills\n- Excellent communication and collaboration skills\n- Experience with logging, monitoring, and observability tools like Prometheus, Grafana, or ELK stack\n- Cloud development experience primarily focused on AWS but equivalent experience Azure and GCP experience may be substituted.\n\nNice To Have\n- Experience with Kubernetes, Kafka\n- Knowledge of DevOps practices and infrastructure as code (Terraform, Ansible, etc.)\n- Background in data processing pipelines or machine learning integrations\n- Previous experience in high-traffic, distributed systems\n- Familiarity with LangChain, LangGraph, Semantic Kernel, or RAG pipeline concepts\n- Experience with GraphQL and gRPC for efficient API communication\n- Exposure to AI/ML-driven backend services and automation.\n\nHow To Apply\nWe want to ensure that all our applicants have a fair and equal chance so we\'re using an online coding assessment. This minimizes bias in our process so along with your resumé, please be prepared to complete a short online pre‑screen technical assessment (~ 45 minutes, one sitting). Your results will accompany your application and help us move quickly to the interview stage. Start by clicking here: https://app.testgorilla.com/s/kx45zsh4.\n\nBenefits Of Working For At Dawn Technologies\nAt Dawn Technologies is more than just a place to work—it\'s a place where your career and personal growth come to life. We believe in unlocking the full potential of our employees by providing them with incredible opportunities to:\n- Create a Lasting Impact: Your work will directly contribute to solving meaningful challenges and shaping the future of technology.\n- Learn and Grow: Whether professionally or personally, we offer countless opportunities for learning, skill development, and career progression.\n- Experience a Thriving Culture: Join a team that’s as innovative as it is supportive, fostering an environment of collaboration, diversity, and inclusion.\n- Be Your Whole Self: At AT Dawn, you are encouraged to bring your unique perspectives, passions, and talents to the table.\n\nBest-in-Class Pay And Perks\n- Competitive, Performance-Based Compensation: We offer an attractive, market-leading salary and bonus structure, ensuring that our employees are rewarded for their hard work and commitment.\n- Job Opportunities with Impact: Work on complex, high-impact projects that challenge your skills and inspire creativity. The problems you\'ll solve are at the cutting edge of the tech world, offering immense growth potential.\n- Fully Remote, Globally Connected: Enjoy the freedom of working from anywhere, with the flexibility to manage your schedule while still feeling connected to a global team.\n- Comprehensive Benefits Package: We provide extensive healthcare coverage—medical, dental, and vision plans—tailored to fit your needs. We also offer mental health support and wellness programs to ensure you stay at your best, both at work and in life.\n- Generous Paid Time Off & Flexible Leave: Take the time you need to recharge, with ample vacation days and leave allowances.\n- Retirement Planning: Secure your future with options like CPF, EPF, and company-matched 401(k) plans, because we care about your long-term well-being.\n- Learning & Development Opportunities: Whether through formal courses or learning on the job, we invest in your continuous growth.\n- Additional Perks: From team-building activities to performance bonuses and more, we go the extra mile to make sure our employees feel valued and supported.\n\nOUR STORY\nThe tech space is crowded, but most solutions feel like they’re cut from the same cloth—missing the mark on what businesses truly need. Organizations are chasing innovation, but too often, it comes at the expense of flexibility, independence, and real technological depth. At AT Dawn Technologies, we’re a niche startup laser-focused on delivering specialized tech solutions in Gen AI, Data Engineering, and Backend Systems. What sets us apart is our commitment to technologists—the creators, problem-solvers, and innovators who bring true value to transformation. We don’t just build solutions; we help ambitious organizations redefine their potential while staying lean, agile, and impactful.\n\nWe are committed to building an inclusive, innovative, and diverse workforce where everyone can thrive. We are proud to be an equal opportunity employer and strongly believe in creating a welcoming environment for all employees, regardless of race, gender, background, or identity. Join us at AT Dawn Technologies and unlock your potential in a place where work meets opportunity, growth, and greatness!\n\nSkills: rag, semantic kernel, hibernate, restful api design, langgraph, observability, microservices, monitoring, langchain, sql, aws, spring boot, asynchronous processing, azure, ci/cd, docker, java, python, logging, gcp, microservices architecture, nosql', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quy Nhon, Binh Dinh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2105, 676, 2, 'Bridge Software Engineer (BrSE)', 'Role Summary\nWe are seeking a highly skilled Bridge Software Engineer (BrSE) to act as the key communication link between Japanese clients and local development teams. The role involves translating business requirements into technical solutions, ensuring seamless collaboration, and delivering high-quality projects on time.\n\nJob Responsibilities\n\nCommunication Management:\n- Serve as the primary liaison between Japanese clients and development teams, ensuring clear and effective communication.\n- Translate client requirements into actionable tasks for development teams.\n- Provide regular updates to stakeholders regarding project progress and challenges.\n\nProject Coordination:\n- Define project scope, timelines, and deliverables in collaboration with project managers.\n- Monitor and manage project schedules, ensuring adherence to deadlines and quality standards.\n- Identify and mitigate risks throughout the project lifecycle.\n\nSystem Design and Development Support:\n- Create, review, and manage system design documents, including both basic and detailed designs.\n- Support the technical team in implementing client requirements, ensuring alignment with project goals.\n\nTesting and Quality Assurance:\n- Plan and oversee testing activities, including Unit Testing, Integration Testing, and Stress Testing.\n- Ensure deliverables meet quality standards and align with client expectations.\n\nTechnical Leadership:\n- Utilize tools such as Jira, Backlog, and Git for task management and version control.\n- Provide hands-on support in programming languages like Java, .NET (WPF), or SQL Server as needed.\n- Address and resolve technical challenges efficiently.\n\nDomain Expertise (Preferred):\n- Offer insights into Banking/Finance domains, such as Risk Management or Financial Derivatives.\n- Leverage expertise in frameworks like Basel Capital Accord, LCR, NSFR, or IRRBB.\n\nContinuous Improvement:\n- Proactively identify process improvements to enhance project efficiency and quality.\n- Stay updated with industry trends and emerging technologies to drive innovation.\n\nJob Requirements\n- Bachelor\'s degree in Computer Science, Information Systems, or a related field.\n- Japanese language skills equivalent to N1 level are mandatory.\n- Minimum 5 years of experience as a Bridge Software Engineer (BrSE) or in a related role.\n- Technical Skills:\n  - Strong understanding of system design and documentation.\n  - Hands-on experience in at least one programming language (e.g., Java, .NET, or SQL Server).\n  - Proficiency in tools like Jira, Backlog, and Git for project and task management.\n- Project Management Skills:\n  - Familiarity with Agile and Waterfall methodologies.\n  - Experience in testing processes, including Unit Testing, Integration Testing, and Stress Testing.\n- Preferred Skills (Optional):\n  - Background in Banking/Financial domains, including Credit Risk Management, Market Risk Management, or Liquidity Risk Management.\n  - Knowledge of specialized financial frameworks, such as Basel Accord, IRRBB, LCR, or NSFR.\n\nAbout DXC Technology\nDXC Technology (NYSE: DXC) is the world’s leading independent, end-to-end IT services company, helping clients harness the power of innovation to thrive on change. Created by the merger of CSC and the Enterprise Services business of Hewlett Packard Enterprise, DXC Technology serves nearly 6,000 private and public sector clients across 70 countries. The company’s technology independence, global talent and extensive partner alliance combine to deliver powerful next-generation IT services and solutions. DXC Technology is recognized among the best corporate citizens globally. For more information, visit www.dxc.technology.\n\nPlease note the above statements describe the general nature and level of work only. They are not a complete list of all required responsibilities, duties and skills. Other duties may be added, or this description amended at any time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2106, 1096, 2, 'Software engineer', 'We offer you an Ocean of Possibilities. Join our family.\n\nAbout Us\n\nDamen Song Cam Shipyard is engineering, outfitting, commissioning and delivering various Damen standard ship types. Basic designs and most components are delivered to DSCS by Damen Shipyards Gorinchem. DSCS will complete the detailed design, and production information, which will be used during the assembly of the vessels.\n\nThe commissioning and seas trials department is a part of the Production department of Damen Song Cam Shipyard. This department is responsible for the verification and start-up of ship systems to secure good operation of all installations on board as well as the lay-up activities of delivered ships\n\nThe role\n\nDevelopment of AMCS software on board of Damen vessels and ship control systems so that they meet the required expectations.\n\nKey accountabilities\n\nAs a Software Engineer Your Tasks Are The Following\n\nShip AMCS Completion & development\n\n• Developing and testing the software systems on board;\n• Creation of graphic screen layout and handling for human interfaces;\n• Keep communications & discussions with Workboats Technology team to complete & develop HMI software;\n• Responsible for commissioning of the automation systems delivered, such as conducting start-up according to procedure, performing required tests, performing acceptance testing with presence of Customer & approval societies;\n• Support & complete the relevant works relating to Commissioning & Trials;\n• Support to update some kinds of software on board;\n• Support Service activities when required.\n\nSkills & Experience\n\nTo be successful in this role you bring:\n\n• You have a bachelor’s degree, preferably in Web development;\n• With 2-3 years of relevant work experience;\n• Knowledge of one or more of these programming languages;\n• Knowledge and interest in automation products are a plus;\n• Excellent oral and written communication skills in English.\n\nWhat we offer\n\nHere At Damen, We Realize Supporting And Managing Many Talented Individuals Is Of Great Essence. We Understand That The Key To Success Is To Find The Right Person For The Right Job. That’s Why We Continually Invest In Your Development. Damen Offers You\n\n• a dynamic international working environment focusing on technology and innovation; \n• a competitive salary; \n• holiday bonus, Tet bonus, quarter bonus; \n• monthly fuel allowance; \n• 24/7 insurance + health insurance for employee and spouse; \n• social insurance; \n• business trip allowance (if any); \n• continuous focus on professional and personal development through training programs.\n\nOther\n\nDamen Song Cam does not approve of a commercial, contractor and/or agency acquisition or commercial use of this advertisement. Proposing candidates without invitation is not appreciated and will not be considered.\n\nRecruiter\n\nTran Duc Vuong (Trần Đức Vượng)\n\nEmail\n\nvuong.tran.duc@damen.com\n\nPlease apply through the Apply Button. Due to GDPR reasons we cannot accept applications by email.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Haiphong, Haiphong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2107, 820, 2, 'Senior Java Developer', 'MÔ TẢ CÔNG VIỆC\nđóng vai trò tech lead cho team backend, chịu trách nhiệm thiết kế hệ thống\ngiải quyết các bài toán khó cho hệ thống\nquản lý team backend, training đào tạo, dẫn dắt member\nYÊU CẦU\ntrên 5 năm kinh nghiệm phát triển java backend (spring boot)\ntừng đảm nhiệm vị trí tech lead or leader trong team\ncó kinh nghiệm dựng base source code backend\ncó kinh nghiệm làm micro service\nthiết kế dc kiến trúc hệ thống\nkiến thức DB vững chắc\ncó kinh nghiệm AWS là lợi thế\ntừng làm các dòng dự án cho thị trường JP là lợi thế\ncó kinh nghiệm tạo các document cho dự án như api design, db\nĐÃI NGỘ\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\nĐược khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\nNgày hết hạn: 30 tháng 6, 2025\nChi tiết công việc\nSố Lượng\n1\nĐịa Điểm\nHà Nội\nKinh Nghiệm\nTrên 5 năm\nTrình Độ\nSenior\nHình Thức\nToàn thời gian\nKỹ Năng\nJava', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2108, 856, 2, 'Hanoi - Manual Test Engineer (Automotive domain, English)', 'LG Electronics Development Vietnam (LGEDV) produces high-quality in-car infotainment systems that deliver both information and entertainment on-the-go for many of the world’s biggest automobile brands.\n\nLGEDV conducts core R&D activities, and various product reliability tests in support of our vehicle component business. With the key missions of offering an environment that enables colleagues to demonstrate their capabilities, focus on their work and create value & delivering the “invaluable” office operation services & solutions that contributes to a company’s business success.\n\n📌 Roles & Responsibility\nAs member of Software Validation team, you will be responsible for testing software for Automotive domain as below:\n- Software testing for in-vehicle Infotainment applications including Cluster, AVN-audio video navigation and Telematics;\n- Analyze project requirements, design / execute / update test cases & test scripts;\n- Report, track, and monitor defects in the defect tracking system;\n- Escalate testing risks and issues.\n- Setup test environment; execute automation test scripts and ensure about automation test result reliability.\n- Log, verify & manage defects on defect tracking system\n\nWhat you get:\n- Involve in a fast-growing field with the newest technology trends;\n- Dive in learning & training courses of technical and soft skills conducted by professional mentors;\n- Enjoy competitive benefits package in motivating environment with great team and engaging leader.\n\n📌 Qualifications & Requirements\n- Bachelor\'s degree in Information Technology, Computer Science, Computer Engineering, Electronics Engineering, Telecommunication Engineering or equivalent; ect.\n- From 1 year of experience in software testing (automotive domain is preferred);\n- Ability to understand English documents specialized in IT field, and basic communication skills;\n- Good logical thinking and teamwork; Automotive (especially IVI: In Vehicle Infotainment) and ASPICE experience is a plus.\n\n📌 Benefits\n- HYBRID WORKING: Employees can split time between working in the office and working from home;\n- 5 working days/week: Mon – Fri with FLEXIBLE WORKING TIME;\n- Total remuneration package: UP TO 16.5 MONTHS OF SALARY;\n- Support for lunch and other ALLOWANCES (Coding Expert, Technical leader, phone...);\n- Annual salary review;\n- 12 days of annual leave & ADDITIONAL 8 DAYS OF COMPANY HOLIDAYS;\n- Premium health care & accident insurance;\n- Support fee to get TOEIC & technical certifications (ISTQB, Agile Scrum...);\n- On-site & training opportunities abroad;\n- Company trip, sporty clubs (zumba, football, pingpong, badminton,...);\n- Monthly budget for team activities, etc.;\n- LG Gram.\n\n📍 Office: 17F - 21F Office Lobby, Lotte Mall West Lake, 272 Vo Chi Cong, Tay Ho, Hanoi.\n\nNote: We\'ll only contact candidates whose CVs pass our initial screening. If you don\'t hear from us, we hope to connect regarding other opportunities in the future.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2109, 828, 2, 'Fullstack Developer', 'Welfare\n\n• Attractive remuneration with competitive income and 6 months/year salaries/ efficient production and business.\n• A welfare package of $2000 per year including Tet bonus, holiday bonus and resort.\n• Being a colleague of a team of leading technology experts in fields such as: DPI, BigData, Machine Learning, AI, Data Mining, Speech Recognition, Virtual Assistant…\n• Improve capacity through intensive training courses, study support and professional certification exams.\n• Consider raising the minimum salary once a year. Access to attractive promotion opportunities.\n• 12 days holiday, 12 vacation days and 3 annual vacation days.\n• Always enjoy to the fullest full benefits of social insurance, health insurance, unemployment insurance and statutory leave and sick leave after signing the labor contract.\n• Join the comprehensive health care MIC insurance package.\n• Relax, spark creativity with Happy Time every day, modern workspace.\n• Enjoy a delicious lunch, selected by nutritionists.\n• Working in key projects of the Group with large system scale.\n• Experience the multiculturalism when working with Viettel\'s personnel in more than 10 countries.\n\nJob Descriptions\n\nParticipate in requirements research, analysis – design, and construction of Web-based products.\nParticipate in the process of researching and optimizing products according to customer requirements products.\nResearch and apply new technologies to projects.\nBuild efficient, scalable, highly available features.\nImplement and maintain the project.\n\nJob requirements\n\nGraduated from Regular University with Good or better, majoring in Information Technology, Electronics and Telecommunications, Management Information Systems, Computer Science... in the IT sector.\nHaving 2 years of experience or more (accepting the whole process of working experience while not graduating).\nEnglish equivalent to TOEIC 550/990 (Not required). degree when recruiting input).\nProficient in Python programming with 2 years of experience.\nFluent in one of the frameworks: Flask, Django.\nFluent in working with SQL (Mysql, PostgreSQL), NoSQL (Mongo).\nExperience in Bootstrap, Web API, MVC models, MVVM.\nExperienced Experience working with ReactJS\n\nPreferred\n\nJava programming experience.\nExperience in using LessCSS, SassCSS.\nFluent in HTML5, CSS3, Java Script, JQuery, AJAX, XML.\nFluent in one of the following technologies: AngularJS, VueJS, NodeJS.\nExperience in using LessCSS, SassCSS.\nExperience in Agile/Scrum software development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2110, 941, 2, 'Senior Fullstack Engineer - Node.js + Vue.js', 'We are a fast-growing SaaS company in the EduTech space, operating mainly in Singapore, Vietnam, and Malaysia. With almost 2000 schools as customers, our mission is to revolutionize early childhood education through technology and provide innovative solutions to our customers. With a team of 60 talented individuals, we are committed to transforming the way education is delivered in the Southeast Asian region and beyond.\n\nWhat you will be doing:\n\n- Develop full-stack services in Typescript for in our existing application\n- R&D novel and ingenious solutions to creating enhanced user experiences tailored to a multitude of global regions\n- Continuously enhance the app with the latest code-improving methodologies available\n- Use modern DevOps tools and automate everything with Docker and our Kubernetes clusters\n\nYour Skills And Experience\n\nMust have:\n\n- Deep expertise in Typescript, Vue and MySQL\n- Containers are first class in your apps\n- Understanding of MVC design pattern\n- Familiar with a wide range of performance optimization solutions\n- Strong understanding of vanilla front-end technologies, such as JavaScript, HTML5, and CSS3\n- Sound coding practices with tools such as git, unit testing, CI/CD, service oriented architecture\n- Linux confidence\n- Solid understanding of information security', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2111, 988, 2, 'Manual QC Engineer', 'FinX aims to build a digital bank that will deliver on the promise of simplicity, technological advancement, superior customer products & services.\nAs a Manual QC, you will take part in building an exciting, greenfield digital banking product, which will positively impact the day-to-day lives of millions of people.\nResponsibilities:\n- Test planning.\n- Professional analysis and clarification of project issues, good Q&A with planner/product owner.\n- Implement checklists, test cases, test procedures, test reports, and defect log,…\n- Manage and execute tests according to plan, including providing test results based on test status, and test reports.\n- Coordinate with other internal development teams to complete the job well.\n- Complete tasks assigned on the schedule.\nQualification and Requirements:\n- Degree in Computer Software or related fields.\n- 2+ year experience in software testing, including functional and regression testing.\n- Experience in Windows, iOS, and mobile apps.\n- Experience working with software development lifecycle tools, such as Jira, DevOps Azure, and Zephyr (test case management).\n- Experience with user acceptance and user experience testing.\n- Experience in bug verification testing.\n- Experience in banking product is huge plus.\nWhat we can offer?\n- Attractive income in Viet Nam fintech markets\n- 20 days of annual leave, 10 days of sick leave and public holidays.\n- Devices provided (Macbook, mouse, monitor…)\n- Frequent team bonding and company activities/ events.\n- Work in a newly innovated office and open working space.\n- Empowered to listen to creative ideas, and there is no distance between bosses and employees.\nFinX begins to establish and bridge new fintech businesses in order to create a better tomorrow for Vietnamese people. Here is an inspired working environment where you will be able to access and experience cutting-edge technologies in industry and creativity.\nLocation: PV Gas Tower, 673 Nguyen Huu Tho, Phuoc Kien Ward, Nha Be District, HCMC, Vietnam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2112, 926, 2, 'Senior Java Software Engineer-Upto 60M', 'Join the Company’s software development projects in the education domain for a Canadian client. We seek a passionate and skilled Java Backend Developer to join our team. The ideal candidate will have strong backend development experience and a solid understanding of cloud infrastructure, particularly AWS. You will work closely with cross-functional teams to build scalable and reliable backend systems.\n\nYour Skills and Experience:\n- Proficient in English\n- Bachelor’s or master’s degree in engineering, Computer Science, Software Engineering or equivalent discipline.\n- 5+ years of hands-on development experience, primarily using Java.\n- Experience and knowledge of databases – both relational and NoSQL.\n- Working knowledge of Java, Spring, Hibernate, REST, XML, JSON, Message Queues, databases – both relational and non-relational.\n- Working knowledge of distributed messaging and streaming platforms, such as Apache Kafka Streams as well as dealing with unbounded data.\n- Comprehensive understanding of software systems, including the compiler/JVM/garbage collection, distributed systems, optimizers and compilers.\n- Proficiency with MongoDB or other NoSQL databases.\n- Understanding of the TCP stack and MQTT/HTTP based protocols.\n- Knowledge and hands-on experience in docker development and deployments such as Kubernetes.\n- Knowledge of AWS\n- Knowledge of CI/CD based workflow\n\nBenefits:\n- Salary: Negotiable\n- Attractive salary and bonus based on performance.\n- Full benefits for employees according to the Vietnam Labor Laws: social and health insurance\n- An international, professional, young but innovative and dynamic environment working closely with international experts and joining conferences and workshops on exciting new technologies.\n- Holidays based on Vietnamese labor law + paid vacations\n- Company trip, Team Building\n\nContact:\nSETA international Viet Nam\nAdd: HL Tower, 82 Duy Tan, Ha Noi\nEmail: hr@setacinq.vn\nWebsite: https://www.seta-international.com/\nFanpage: https://www.facebook.com/SETA.International.careers/\nLinkedin: https://www.linkedin.com/company/seta-international-careers/', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2113, 891, 2, 'Remote Fullstack Engineer (Nodejs)', 'About Us\nWe’re a fast-growing international fintech startup on a mission to make entrepreneurship simpler. By combining cutting-edge SaaS technology with expert human support, we help thousands of businesses eliminate administrative headaches—freeing them to focus on what really matters.\nOur solution streamlines accounting, bookkeeping, and compliance, delivering real-time service with precision and speed. With over 500 team members across the globe, we’re scaling quickly and looking for passionate individuals who are excited to tackle complex challenges and make an impact.\nThe Role: Full Stack Engineer (React + Node.js)\nWhat You’ll Do:\n✨ Turn concepts, designs, and business requirements into scalable, maintainable, high-quality code using React and Node.js.\n✨ Build and maintain reusable components and libraries to ensure consistency and efficiency.\n✨ Optimize both frontend and backend systems for speed, scalability, and reliability.\n✨ Design and develop secure, efficient APIs for seamless data communication.\n✨ Champion full-stack best practices, including modular design, error handling, and performance tuning.\n✨ Write robust unit, integration, and end-to-end tests to ensure smooth and reliable deployments.\n✨ Prioritize security and privacy across the tech stack—handling authentication, encryption, and data protection.\n✨ Contribute to improving DevOps practices and CI/CD pipelines for streamlined deployments and monitoring.\n✨ Collaborate cross-functionally with designers, product managers, and engineers to ship features efficiently.\n✨ Stay current with emerging technologies to continuously improve development workflows and system architecture.\nWhat We’re Looking For:\n✅ 5+ years of full-stack development experience, with strong expertise in React (with hooks) and Node.js (Koa or Express).\n✅ Proficient in JavaScript and TypeScript.\n✅ Hands-on experience building scalable RESTful and WebSocket APIs with a focus on performance and security.\n✅ Solid understanding of database systems, especially PostgreSQL, including schema design and query optimization.\n✅ Strong background in frontend performance techniques such as code splitting, caching, and lazy loading.\n✅ Deep understanding of authentication and security (OAuth, JWT, API protection).\n✅ Experience with cloud platforms (preferably AWS), including services like Lambda, RDS, S3, and API Gateway.\n✅ Familiarity with CI/CD processes, Docker, and modern DevOps workflows.\n✅ Excellent problem-solving and debugging skills.\n✅ A growth mindset and eagerness to contribute to a strong, collaborative engineering culture.\nPerks & Benefits:\n🌍 Competitive salary in a fast-growing global team\n🌍 Cross-cultural working environment to broaden your professional horizons\n🌍 Annual budget for continuous professional development\n🌍 Mental health leave\n🌍 Flexible and hybrid working arrangements\nEqual Opportunity\nWe are committed to building an inclusive environment for all. We welcome applicants from all backgrounds, and we do not discriminate based on race, religion, gender, age, sexual orientation, disability, or any other legally protected status.\nIf you have any accessibility needs during the application or interview process, please let us know—we’re here to support you.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2114, 879, 2, 'Senior Front End Engineer', 'Headquartered in Singapore, Ant International powers the future of global commerce with digital innovation for everyone and every business to thrive. In close collaboration with partners, we support merchants of all sizes worldwide to realize their growth aspirations through a comprehensive range of tech-driven digital payment and financial services solutions. Ant International is the international business unit of Ant Group, the owner and operator of Alipay.\n\nPosition Description\n1. Responsible front-end development for company\'s web products.\n2. Collaborate closely with cross-functional teams to create products with exceptional user experience.\n3. Research emerging technologies and mentor junior developers.\n\nJob Requirements\n1. 3+ years of web front-end development experience with solid fundamentals in JavaScript (ES6+), CSS3, and HTML5.\n2. Practical experience in Mobile Web performance optimization and deep understanding of front-end engineering.\n3. Proficient in at least one MVVM framework (Vue/React/Angular).\n4. Familiar with at least one non-front-end language (Node.js/Java/Ruby/Objective-C, etc.).\n5. Tool enthusiast with demonstrated ability to leverage tools for problem-solving and efficiency improvement.\n6. Strong analytical skills, passion for knowledge sharing, and curiosity for new technologies.\n7. Preferred qualifications: Active open-source contributor (GitHub 100+ stars), fluent English communication skills.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2115, 797, 2, 'Software Engineer (Python/C++)', 'OPSWAT, a global leader in IT, OT, and ICS critical infrastructure cybersecurity, delivers an end-to-end platform that gives public and private sector organizations and enterprises the critical advantage needed to protect their complex networks, secure their devices, and ensure compliance. Over the last 20 years our commitment to innovative technology has earned the trust of more than 1,700 organizations, governments, and institutions globally, solidifying our role in protecting the world’s critical infrastructure and securing our way of life.\n\nThe Position\n\nWe are looking for an engineer to develop the Industrial Firewall and IPS and Firewall Management Platform that provide real-time protection for industrial automation assets and endpoint devices.\n\nWhat You Will Be Doing\n\n-Development:\n  - Design and develop robust firewall software components.\n  - Implement and optimize firewall rules and policies to enhance security and performance.\n-Collaboration and Feature Development:\n  - Collaborate with cross-functional teams to define, design, and ship new features.\n-Quality Assurance:\n  - Ensure performance, quality, and responsiveness of applications.\n  - Identify and correct bottlenecks, fix bugs, and help maintain code quality.\n-Maintenance and Improvement:\n  - Help maintain code quality, organization, and automation.\n  - Continuously seek opportunities to improve existing processes and systems.\n\nWhat We Need From You\n\n-Technical Skills:\n  - Strong proficiency in Python/C++.\n  - Experience using Redis.\n  - Experience with RESTful API design and implementation.\n  - Familiarity with Linux/Unix systems and shell scripting.\n-Network and Security:\n  - Familiarity with network protocols and their functionalities.\n  - Understanding firewall concepts and technologies.\n  - Experience with network protocols and security best practices.\n  - Understanding of security best practices and standards (e.g., OWASP, NIST).\n  - Strong logical thinking and problem-solving skills.\n\nIt Would be Nice if You Had\n\n-Frontend Development:\n  - Experience with HTML/CSS, Bootstrap, jQuery, and other frontend technologies.\n  - Experience in frontend development using React and related technologies (Redux, Hooks, etc.).\n-Technologies and Tools:\n  - Familiarity with containerization technologies (e.g., Docker, Kubernetes).\n  - Understanding of DevOps tools and practices.\n-Performance and Testing:\n  - Experience with performance tuning and optimization of network applications.\n  - Experience with automated testing frameworks and practices.\n\nOPSWAT is an equal opportunity employer. We celebrate diversity and are committed to providing an environment where equal employment opportunities are extended to all employees and applicants, free of discrimination and harassment of any type. All employment decisions are based on individual qualifications, job requirements, and business needs without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other category protected by federal, state, or local laws.\n\nRecruiting Agencies: we do not accept unsolicited resumes from third party agencies for any of our open positions. To submit resumes for our jobs, there must be a recruiting contract approved by our legal team and endorsed by both parties. We are currently not accepting additional 3rd party agencies at this time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 호치민 호치민', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2116, 702, 2, 'Binance Accelerator Program - Quality Assurance Engineer, Risk', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nAbout Binance Accelerator Program\n\nBinance Accelerator Program is a concise fixed-term program designed for Early Career Talent to have an immersive experience in the rapidly expanding Web3 space. You will be given the opportunity to experience life at Binance and understand what goes on behind the scenes of the worlds’ leading blockchain ecosystem. Alongside your job, there will also be a focus on networking and development, which will expand your professional network and build transferable skills to propel you forward in your career. Learn about BAP Program HERE.\n\nWho May Apply\n\nCurrent university students and recent graduates.\n\nResponsibilities\n- Collaborate closely with team members to develop, test, and deliver high-quality products.\n- Understand business scenarios and technical designs to create comprehensive and effective test cases.\n- Contribute to test automation using existing frameworks or develop scripts to improve testing efficiency.\n- Execute test plans and identify issues through manual and automated testing.\n- Track defects through resolution and actively participate in project activities to ensure timely delivery.\n- Understand project dependencies and contribute to risk mitigation strategies.\n\nRequirements\n- Currently pursuing an undergraduate degree in Computer Science, Engineering, or a related field.\n- Proficient in at least one programming language such as Java, Python, or JavaScript.\n- Familiarity with Linux, basic database operations, or cloud services.\n- Strong analytical and problem-solving skills.\n- Effective verbal and written communication abilities.\n- High attention to detail and a strong sense of responsibility.\n- Self-motivated and proactive, with the ability to work effectively in a team environment.\n- Previous experience in software development or testing is a plus.\n\nWhy Binance\n- Shape the future with the world’s leading blockchain ecosystem.\n- Collaborate with world-class talent in a user-centric global organization with a flat structure.\n- Tackle unique, fast-paced projects with autonomy in an innovative environment.\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning.\n- Competitive salary and company benefits.\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team).\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'مدينة هو تشي مينه هو شي مينه سيتي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2117, 674, 2, 'Python Technology Development', 'Mô tả công việc\n\n- Develop Bots as Automation Services for fields such as E-commerce, Human Capital - HR, Financial Capital - Finance, Trading, Blockchain, Legal, Real Estate\n- Find and research to reuse APIs available from open-source tools to build applications as web services that will be hosted on the server.\n- Find and research available open-source tools, configure tools for integration into large company tools.\n- Server management and maintenance, server operation process design, Ubuntu server usage and backup planning.\n- Maintain and develop the code of the enterprise cryptocurrency unit.\n\nYêu cầu công việc\n\n- Qualification: 2nd year student to bachelor\'s degree graduate in related fields such as information technology, math - informatics...\n- Have basic knowledge of programming languages, especially Python, know how to use the Ubuntu operating system, have in-depth knowledge of the entire web application development process (design, development, deployment)\n- Good analytical and time management skills, logical thinking and algorithms\n- Be proactive in work, have a sense of responsibility, have a spirit of teamwork, have the ability to research new jobs, and carry out requests from superiors.\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quoc Tuan Commune, Haiphong, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2118, 758, 2, 'Software Engineer C++', 'MiTek’s Component Manufacturing division is seeking a dynamic and passionate Software Engineer to help pioneer industry changing solutions for the residential construction industry. This position will be part of a team working on a 3D BIM solution for single or multi-family modeling, design, and estimating. Be part of a high-performing and collaborative team that is focused on innovation and engaging MiTek customers, while creating powerful software.\n\nRole, Responsibilities & Typical Activities\n- Code, enhance, test, and debug 3D CAD/Engineering desktop software using C++, C, and C#.\n- Contribute to large, breakthrough enhancements in our CAD/BIM platform. Efforts require refactoring existing logic, feasibility analysis, and creating new enhancements.\n- Collaborate with business analysts, testing, and other development teams to ensure solutions are efficient, consistent, and fulfill business needs.\n- Perform design and analysis on efforts before starting development.\n- Author technical documents for software architecture or design as required.\n- Participate in design reviews, code reviews, and collaborative requirements reviews.\n- Apply generally accepted programming standards and techniques to ensure efficient performance and data manipulation.\n- Attendance during regular work hours and overtime as required.\n- Collaborate with multiple global teams to contribute to a large-scale project.\n\nRequired Qualifications:\n- Bachelor of Science degree in Computer Science or related field. Additionally, equivalent work experience may be substituted for the degree requirement.\n- 3+ years of experience designing, developing, and deploying enterprise applications in global environments.\n- 2+ years of hands-on experience with C++ application development.\n- Experienced with desktop application development.\n- Knowledge of data structures and strong understanding of object-oriented principles.\n- Comfortable digging into large, unfamiliar codebases to diagnose, debug, and resolve critical issues.\n- Familiarity with Azure DevOps for project management and source control.\n- Must possess excellent verbal and written communication skills in English and the ability to communicate in both technical and business terms. (English level B2 - CEFR or equivalent)\n\nPreferred Qualifications:\n- Understanding of mathematical concepts involving algebra and geometry\n- Understanding of SCRUM and Agile principles to collaborate effectively in a team environment.\n\nBenefit:\n- Extremely competitive salary.\n- 13th month & productivity Bonus.\n- Yearly salary review.\n- Healthcare insurance package.\n- 24/24 Personal accident insurance.\n- State-of-the-art office environment.\n- Yearly outing.\n- Detailed induction, training and on-going career development.\n- Opportunity for overseas training and travel.\n- English training programs.\n- 5-day week.\n- Flexible start-times.\n- Free lunch.\n- Free parking.\n- Full Social Club including gym, yoga, football, badminton, swimming.\n\n+ Type of working: At MiTek office\n+ Working location: A5 Building, E-Office Park, Sang Tao Street, Tan Thuan EPZ, Tan Thuan Dong ward, District 7, HCMC\n+ Website: MiTek Vietnam\n+ Application send to tram.ngo@mii.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2119, 1054, 2, '(All Level) Embedded Linux/ Firmware/Software Engineer', '1. INTRODUCTION  Founded in 2010, Ban Vien Corporation has embarked on an inspiring journey, evolving into a trusted technology partner that has left an indelible mark in the realm of software development and embedded system development. Today, our influence extends both domestically and internationally, showcasing our commitment to driving digital transformation. At Ban Vien, we relentlessly pursue innovation across diverse industries like Edutech, Fintech, Retail, Automotive, Smart IoT, and Logistics. Our comprehensive services span Digital Consulting, R&D, Software Development, and Dedicated Development Centers. This global expansion includes valued clients and esteemed partners in the United States, Germany, Japan, Singapore, China, Hong Kong, Thailand, Malaysia, and Vietnam.\n\n2. JOB DESCRIPTION  As an Embedded Software Engineer, you will participate in the end-to-end development of embedded systems, including firmware, drivers, and low-level system software. You will have the opportunity to work with a variety of hardware platforms, operating systems, and development environments, depending on the project scope.\nKey Responsibilities:\n- Develop and maintain embedded software for microcontrollers and SoCs.\n- Design, implement, and debug low-level drivers and firmware (u-boot, Linux kernel, RTOS, etc.).\n- Perform system integration and validation testing.\n- Analyze hardware schematics and technical documentation.\n- Participate in full software development life cycle: requirement analysis, design, implementation, testing, and maintenance.\n- Contribute to BSP development, kernel customization, bootloaders, and hardware abstraction layers.\n- Provide technical support, documentation, and respond to customer inquiries.\n- (For senior levels) Lead feature development, technical reviews, mentoring, and project planning.\n\n3. REQUIREMENTS  Must Have:\n- Bachelor’s Degree or higher in Electronic Engineering, Telecommunication, Computer Science, Automation, or related fields.\n- Minimum 1 year of professional experience in embedded development.\n- Strong proficiency in C/C++ programming for embedded systems.\n- Hands-on experience with microcontrollers (e.g., STM32, ESP32, NXP, i.MX) and SoCs.\n- Solid understanding of hardware interfaces and communication protocols: SPI, I2C, UART, CAN, Ethernet, etc.\n- Experience with Embedded Linux or RTOS (e.g., FreeRTOS, OSEK, TOCK).\n- Familiar with bootloader, secure boot, memory management, and low-level hardware control.\n- Ability to read hardware manuals, schematics, and technical specifications.\nNice to Have:\n- Experience with Yocto Project, CIP Kernel, or BSP porting.\n- Scripting languages: Python, Bash, Perl, etc.\n- Familiarity with version control (Git, SVN), and configuration management tools.\n- Knowledge of multimedia frameworks, codecs, Qt, Web-Platform testing.\n- Exposure to AUTOSAR, CMMI, or A-SPICE environments.\n- CI/CD automation (e.g., LAVA, Jenkins).\n- Good problem-solving, teamwork, and communication skills.\n- Proficiency in English (written and verbal).\n\n4. COMPANY BENEFITS  You deserve the best when working with Ban Vien\n- Fast-track career growth with many exciting projects.\n- Onsite opportunities abroad: USA, Japan, Singapore.\n- Premium healthcare & wellness in yound, dynamic and inclusive environment.\n- Reward Policies and Recognition Programs: Quarterly Performance Assessment & Profile Capturing, 13th salary and project bonus.\n- Professional learning & development and training program opportunities.\n- Flexible working time.\n- Ban Vien Plus+:  🌟 4-star Company Trip – 3 days for employees & families. 🎉 Annual Thank You Event – Celebration & awards. 💎 Exclusive Point System – Total rewards. 🎁 Special Gift Sets – For every occasion.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2120, 711, 2, 'AI Engineer', 'Our company\n\nWe’re Hitachi Digital Services, a global digital solutions and transformation business. Our expertise, innovation and technology unlocks potential – we take theme park fans on magical rides, conserve natural resources, protect rainforests, and save lives. We automate, modernize, optimize, and accelerate. Our people are trusted transformers, with deep engineering expertise, focused on a sustainable future for all.\n\nImagine the sheer breadth of talent it takes to inspire the future. We don’t expect you to ‘fit’ every requirement – your life experience, character, perspective, and passion for achieving great things in the world are equally important to us.\n\nMeet our Team\n\nHitachi Digital Services Vietnam is part of a 300 strong global delivery network, supporting Hitachi Digital Services around the globe. Our employees collaborate with teams in India, Portugal, and the US, servicing customers worldwide and working on a huge variety of projects. From cloud migration to digital modernization and advanced analytics, offering operational excellence, agile delivery, and plenty of energy to work on huge transformation projects for our customers.\n\nThe role\n\n- Design, develop, and deploy AI models using machine learning (ML), deep learning, and natural language processing (NLP) techniques.\n- Collaborate with cross-functional teams to understand business requirements and translate them into AI solutions.\n- Collect, preprocess, and analyze large datasets to train and evaluate models.\n- Optimize and fine-tune algorithms for performance and scalability.\n- Integrate AI models into existing applications or develop new AI-powered systems.\n- Monitor and maintain AI systems in production to ensure reliability and accuracy.\n\nWhat you’ll bring\n\n- Bachelor’s or Master’s degree in Computer Science, Engineering, Mathematics\n- Proven experience in building and deploying machine learning or deep learning models.\n- Proficiency in Python and ML libraries such as TensorFlow, PyTorch, Scikit-learn, etc.\n- Familiarity with cloud platforms (AWS, GCP, Azure) and ML services.\n- Experience with data processing tools (e.g., Pandas, NumPy, SQL).\n- Understanding of algorithms, data structures, and software development best practices.\n- Strong analytical, problem-solving, and communication skills.\n\nAbout Us\n\nWe’re a global, team of innovators. Together, we harness engineering excellence and passion to co-create meaningful solutions to complex challenges. We turn organizations into data-driven leaders that can make a positive impact on their industries and society. If you believe that innovation can bring a better tomorrow closer to today, this is the place for you.\n\nChampioning diversity, equity, and inclusion \n\nDiversity, equity, and inclusion (DEI) are integral to our culture and identity. Diverse thinking, a commitment to allyship, and a culture of empowerment help us achieve powerful results. We want you to be you, with all the ideas, lived experience, and fresh perspective that brings. We support your uniqueness and encourage people from all backgrounds to apply and realize their full potential as part of our team.\n\nHow We Look After You\n\nWe help take care of your today and tomorrow with industry-leading benefits, support, and services that look after your holistic health and wellbeing. We’re also champions of life balance and offer flexible arrangements that work for you (role and location dependent). We’re always looking for new ways of working that bring out our best, which leads to unexpected ideas. So here, you’ll experience a sense of belonging, and discover autonomy, freedom, and ownership as you work alongside talented people you enjoy sharing knowledge with.\n\nWe’re proud to say we’re an equal opportunity employer and welcome all applicants for employment without attention to race, colour, religion, sex, sexual orientation, gender identity, national origin, veteran, age, disability status or any other protected characteristic. Should you need reasonable accommodations during the recruitment process, please let us know so that we can do our best to set you up for success.\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nang, Da Nang, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2121, 1087, 2, '.NET Engineer (open for expats)', 'ABOUT SIOUX\nSioux Group was founded in 1996 and is headquartered in the Netherlands. With over 1100 engineers, Sioux supports the R&D activities of leading high-tech companies. Sioux aims to add value to its clients and build innovative solutions that contribute to a smarter, safer, healthier, and more sustainable society. At Sioux, we strive for a Culture of Excellence and grow our employees with challenging projects.\n\nAs a Software Engineer at Sioux, you’ll have:\nChallenging projects: work with global clients who are giant tech corporations to build complex high-tech software\nGrowing opportunity: Work with experts from around the world with a quality mindset\nA Sincere, Open, and Fair culture\n\nWE ARE LOOKING FOR SOFTWARE ENGINEER IN DANANG/HCM TO JOIN US!\nYour job will comprise:\nParticipate in the requirements analysis process\nCollaborate with your team lead/software architect to produce software design and architecture\nWrite clean, scalable code using .NET programming languages\nRefactor and improve the existing code base\nTest and deploy applications and systems\nDevelop documentation throughout the software development life cycle\n\nJob requirements\nQUALIFICATIONS\nTechnical:\nBachelor in Information Technology or Computer Science or related fields\nIdeally, a background in the semiconductor, analytical, or medical domain\nGood knowledge and practical skills in clean code, software design\nHave solid year experience in C# .NET\nExperience with Windows Form, WPF, or WinUI3 is a significant advantage\nSoft skills:\nGood English skills, working directly with international clients\nGood sense of teamwork, high responsibility & commitment\nStrong logical thinking, proactive and open-minded\nPassionate about and eager to develop skills through projects in equipment, semiconductors, and related fields\n\nWHAT DO WE OFFER FOR YOU?\nCompensation & Benefits\nAttractive salary\n13th-month salary depending on the employee’s length of service\nProject Bonus (twice per year)\nSocial Insurance is based on government regulations\nFull salary during probation\nSalary reviews: 1 time/year & Promotion opportunities: 2 times/year\n\nWorking hours & Leave\nFlexible working hours working Monday – Friday, no OT\nHybrid working policy\n19 leave days per year, for every 3 work years, +1 day to annual leave\n\nWell-being\nSioux Care Package: Each employee is eligible for an assigned package (based on grade and length of service) up to VND 30,000,000/ employee/ year for well-being benefits, including Premium insurance for employee and family, Annual Health Check, Personal Development, Children’s Education, Support subscription & WFH Equipment\n\nTraining & Development\nCompany-sponsored training: soft skills/ technical skills/ hot-trend technologies/ best practices/English etc\nOnsite opportunities: long-term or short-term at other Sioux offices and client’s destination overseas (where applicable)\n\nWork anniversary bonus\n1st anniversary = 1 million\n3rd anniversary = 3 million\n5th anniversary = 10 million\n10th anniversary = 20 million\n\nSocial activities\nDiverse company culture activities: Company trip, Annual Year End Party, Quarterly party, Company outings, Team building, Lunch & Learn Company anniversary, Family day, X-Mas party, Mid-Autumn, Snack Friday, Food and Snack in the fridge, etc\nSports activities: Football & Badminton club\nCharity social responsibility activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2122, 707, 2, 'Python Developer (Middle/Senior)', 'Job Description\n\n- Work closely with our clients to develop product and configure the application to their business environment\n- Work within a team & communicate effectively across teams\n- Deal with technical challenges, programing tasks while managing client expectations and building long-term customer relations\n- Implement assigned tasks from client/manager\n\nJob Requirements\n\nMUST HAVE SKILLS:\n\n- From 3 years of experience in Python\n- Experience with any Python Web Framework: Django/FastAPI/Flask\n- Experience working with Jinja2\n- Experience with Python ORM: SQLAlchemy, Pydantic\n- Experience working with Docker, Git, Git flow, CI/CD\n- Experience with Unit Test, Intergration Test\n- Experience with Scaling and Building Stable Systems\n- Have knowledge with Caching, DB, DB design\n- Good at English\n\nNICE TO HAVE\n\n- Experience with AI/ML/DL, especially ChatGPT and OpenAI... integration\n- Experience with Data Engineer, Big Data/ ETL/ Airflow\n- Experience working with micro-service projects\n- Experience with NoSQL (MongoDB/DynamoDB), Vector Database (OpenSearch, Qdrant...)\n- Experience with cloud services: AWS/Azure/GCP\n\nSkills Tags: Python, Django, DB\n\nBenefits\n\nCompetitive Salary and Brilliant Health Benefits\n\n- Attractive salary (13th-month salary, salary review twice/year) and project bonus\n- Bonus programs for candidate referral, technical article writing\n- Interest-free loan support for personal plan \n- Allowance for sickness, maternity, paternity and periodic health examination\n- PVI health care program \n- The staff of the quarter and year reward\n\nProgressive and Fun Working Environment\n\n- A professional English-speaking working environment with Agile – Scrum model\n- Hybrid Working Model: Flexible working time and WFH support. \n- Surrounded with friendly, open-minded, young and supportive colleagues \n- Annual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\n\n- Sponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\n- Sponsor fee for joining any technical training sessions and courses.\n- Free English workshops\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2123, 203, 2, '[HCM] Middle/Senior QC Engineer', 'Job Description\n\nWork closely with multiple stakeholders such as the business team, product managers, and engineers to sync up product features and troubleshoot issues.\nWork with project developers, business analysts, and customer support teams to ensure software solutions meet our user expectations.\nDevelop software test cases, based on consumer specifications and requirements.\nPerform root cause analysis on defects found to identify and mitigate project risks.\nConduct exploratory and usability testing to locate bugs before the software is introduced into production.\nExecute comprehensive testing against the software, ensuring all features function as designed and intended.\nContribute to the continuous improvement of software testing methodologies and develop standard operating procedures (SOPs), if necessary.\nPerform functional and user scenario tests on iOS/Android mobile and Web platforms.\nCommunicate with the technical and reproduce issues for the debug plan.\nWork closely with the project team to understand user requirements and review issues.\nCoordinate testing activities with other members.\nEnsure UAT is delivered with approved quality and timeline.\n\nJob requirement\n\n3+ years of experience with software testing.\nExperience in developing test cases, test plans, and execution tests (functional testing, non-functional testing).\nKnowledge of computer architecture and tools for manual & auto testing, unit testing, integration testing, functional testing, and bug-tracking systems.\nGood communication skills, who can convert business feedback into technical requirements and vice versa.\nExperience in web, and mobile applications.\nAbility to multitask in a dynamic, fast-paced environment.\nHaving enthusiasm and passion at work, having a responsibility to ensure product quality.\nGood at research, problem-solving, and troubleshooting ability.\nExperience in APIs(Postman), database, and backend testing.\nExperience in automation test and performance testing is a plus.\nHaving ISTQB certification is a plus.\n\nWhy you\'ll love working here\n\nAhamove is the number 1 on-demand logistics company in Vietnam, the place to give you access to current and first-class technologies, as well as connect the e-commerce and payment platforms of millions of users.\n\nAt Ahamove, the sense of ownership is put on the top and the team is supported to complete your work, as well as supported and made favorable conditions for learning and self-improvement.\nAn open and honest culture where people are valued, treated fairly, trusted, and empowered.\nDisruptive innovations.\nPeople-oriented philosophy of doing business.\nYour footprint on the regional on-demand market.\nSharp, motivated colleagues in a fun office environment.\n\nBenefit\n\nGrab/Be for work: 1M/month.\nLaptop & PVI insurance.\nWorking 5 days/week.\nCompetitive salaries and benefits according to experience and education level.\nAnd more.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2124, 723, 2, 'Manual Test', 'MÔ TẢ CÔNG VIỆC \n\n- Lên kế hoạch kiểm thử sản phẩm giải pháp\n- Xây dựng Test design, Test scenarios, Test cases, Test script cho sản phẩm\n- Thực hiện kiểm thử chức năng, kiểm thử tích hợp, kiểm thử hệ thống, kiểm thử tự động và kiểm thử hiệu năng\n- Lập các báo cáo kiểm thử và Hướng dẫn sử dụng sản phẩm\n- Hỗ trợ triển khai và đào tạo khách hàng.\n- Thời gian làm việc: 9h00 – 18h30, Từ thứ 2 – thứ 6 và thứ 7 đầu tiên của tháng\n\nYÊU CẦU \n\n- Tốt nghiệp ĐH chuyên ngành CNTT, ATTT, ĐTVT,….\n- Có tối thiểu 2 năm kinh nghiệm kiểm thử phần mềm, có kinh nghiệm Test API\n- Am hiểu về Hệ điều hành, có kiến thức lập trình cơ bản, nắm vững Hệ CSDL SQL và NoSQL (MongoDB, Elasticsearch, Casandra…).\n- Nắm vững quy trình phát triển phần mềm và quy trình/kiến thức kiểm thử phần mềm (ưu tiên ứng viên đã làm việc trong mô hình Agile Scrum và có chứng chỉ ISTQB)\n- Tư duy tổng quan về hệ thống, có khả năng lên phương án, xây dựng khung test.\n- Tiếng anh cơ bản.\n\nQUYỀN LỢI \n\n- Mức thu nhập cạnh tranh: upto 20M, Thỏa thuận theo năng lực\n- Môi trường làm việc hiện đại, thân thiện.\n- “NMS care” bảo hiểm dành riêng cho nhân viên NMS.\n- Nghỉ mát: Theo chính sách của công ty (vào tháng 5-6 hàng năm).\n- Review lương hàng năm, tùy vào kết quả công việc.\n- Chính sách cho người lao động tuân theo “Bộ luật lao động” tại Việt Nam.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2125, 743, 2, '[LTS] Kỹ Sư Cầu Nối (BrSE)', 'Vị trí tuyển dụng : Kỹ Sư Cầu Nối\nSố lương : 01\nLoại hình : Fulltime\nĐịa điểm làm việc : Nguyễn Cơ Thạch – Hà Nội\nMô tả công việc\n\n- Là cầu nối giữa khách hàng Nhật Bản và đội dự án Offshore ở Việt Nam, đại diện cho đội dự án ở Việt Nam với khách hàng Nhật và đại diện cho khách hàng Nhật với đội dự án Offshore.\n- Làm việc trực tiếp với khách hàng, làm rõ và nắm chắc các yêu cầu của khách hàng về mọi khía cạnh (technical và nontechnical) và truyền đạt cho đội dự án ở Việt Nam.\n- Làm việc với Project Manager và đội dự án để báo cáo cho khách tình trạng của dự án ở tất cả các khâu trong quá trình dự án.\n- Hợp tác với các Managers/Leaders để giải quyết các vấn đề liên quan (vấn đề kỹ thuật, yêu cầu thay đổi, các vấn đề trong khâu vận hành, yêu cầu điều tra, yêu cầu của khách hàng).\n\nYêu cầu ứng viên\n\n- Tốt nghiệp CĐ/ĐH chuyên ngành CNTT hoặc các chuyên ngành liên quan.\n- Tiếng Nhật tối thiểu từ N2 trở lên, giao tiếp tốt, có thể làm việc trực tiếp với khách hàng Nhật.\n- Ưu tiên người có background về IT, có kinh nghiệm làm dự án IT.\n- Có tư duy & khả năng giao tiếp tốt, kỹ năng phân tích và giải quyết vấn đề tốt.\n- Có khả năng chịu áp lực và làm việc ở hiệu suất cao.\n- Ưu tiên những bạn trẻ, có tinh thần học hỏi và mong muốn trưởng thành sớm.\n- UV đã có kinh nghiệm làm việc tại Nhật là lợi thế.\n\nQuyền lợi được hưởng\n\n- Lương: tối thiểu 13 tháng lương. Thưởng các dịp lễ tết, dự án, cá nhân có thành tích tốt.\n- Kỳ review lương 2 lần/năm...\n- Có cơ hội hoàn thiện và phát triển kĩ năng của bản thân.\n- Có quyền lợi về bảo hiểm y tế, bảo hiểm xã hội, Thuế TNCN theo đúng quy định của nhà nước.\n- Môi trường làm việc: Thân thiện, năng động và có cơ hội/lộ trình thăng tiến rõ ràng.\n- Hoạt động teambuilding, Summer holiday, Year-end party,…\n- Kiểm tra sức khỏe một năm một lần.\n\nCONTACT\n\nLTS Recruitment Department\n- Phone Number: 02466607474\n- Email: rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi ها نوي فيتنام', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2126, 702, 2, 'Blockchain Security Engineer (Smart Contract Auditing)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nResponsibilities\n\n- Conduct security audits on smart contracts, wallets and blockchains, and write high-quality audit reports\n- Develop automated scanning and monitoring tools for smart contracts, wallets and blockchains\n- Utilize scanning tools to detect vulnerabilities in online contracts and promptly issue risk warnings\n- Conduct post-mortem analysis on various hacking incidents, examining the causes, processes, prevention, correction and basic fund tracing\n- Proactively identify on-chain risks, monitor and model emerging on-chain attack vector trends, and possess a solid understanding of on-chain security risks such as fraud and phishing\n- Demonstrate a strong understanding of EVM and non-EVM blockchains and layer 2 solutions, and be familiar with DeFi design patterns\n- Perform a review analysis on newly disclosed vulnerabilities for smart contracts and summarize the root cause behind the exploits for early detection in the future\n- Demonstrate good understanding of cryptography and Security solutions which is utilized under blockchain products\n- Conduct Pen Testing and reviews for blockchain products and provide high quality feedback\n\nRequirements\n\n- Currently enrolled or holding a bachelor\'s degree (or higher) in Computer Science or a related field\n- Proficient in programming languages, such as Solidity, Rust, Go among others which are currently engaged with the Blockchain field\n- Basic understanding of common Smart Contract security vulnerabilities, Current incidents, Wallet Security and Simulation testing\n- Basic understanding of blockchain and smart contract principles, experienced with reading Blockchain explorers and creating scripts to track and scan data. Well versed with the different types of hacks on wallets and blockchain, including smart contracts, and its common attack vectors\n- Well versed with the different types of libraries and security associated with it\n- Familiar with smart contract development testing cycle, pen testing cycle, transaction analysis, and other tools\n- Experienced in using VSCode, Git, or other version control applications\n- Proficient in Python, Go, Rust or another object-oriented programming language\n- Fundamental knowledge of code analysis and program debugging\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem\n- Collaborate with world-class talent in a user-centric global organization with a flat structure\n- Tackle unique, fast-paced projects with autonomy in an innovative environment\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning\n- Competitive salary and company benefits\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team)\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thành Pho Ho Chí Minh, Ho Chi Minh-Ville, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2127, 1088, 2, 'System Engineer', 'Mô tả công việc\n\n- Làm việc trực tiếp với các đối tác để đánh giá và lựa chọn mô hình hệ thống phù hợp với yêu cầu của sản phẩm.\n- Phân tích yêu cầu kỹ thuật, lựa chọn công nghệ và xây dựng kiến trúc hệ thống cho các sản phẩm của công ty.\n- Vận hành hệ thống, đề xuất các giải pháp cải tiến cho sản phẩm dịch vụ.\n- Cài đặt, triển khai, hoặc tự xây dựng các công cụ để tăng hiệu quả công việc\n- Nghiên cứu và cập nhật các công nghệ mới, đề xuất các sáng kiến cải tiến hệ thống phù hợp với xu hướng công nghệ hiện đại.\n\nYêu cầu ứng viên\n\n- Có ít nhất 3 năm kinh nghiệm ở vị trí System Engineer.\n- Ưu tiên ứng viên có kinh nghiệm hệ thống như Contact Center, AI, Cloud.\n- Đam mê công nghệ, thường xuyên cập nhật và tìm hiểu các xu hướng công nghệ mới.\n- Có kiến thức sâu và hiểu rõ quy trình phát triển phần mềm cũng như kiến trúc hệ thống.\n- Giao tiếp tốt bằng tiếng Anh, đặc biệt là trong môi trường làm việc chuyên nghiệp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận 7, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2128, 197, 2, 'Senior Backend Engineer (Go/Java) - EVO', 'Join Trusting Social as a Backend Engineer to develop the EVO Platform, a groundbreaking solution that revolutionizes credit card experiences with instant issuance, instant payments, and numerous benefits, empowering financial freedom for users.\n\nResponsibilities\n\nDevelop Scalable Web Service APIs: Build highly scalable, highly available, and fault-tolerant web service APIs designed to handle millions of transactions per day.\nAgile & DevOps Practices: Follow Agile methodologies and DevOps practices such as CI/CD to deliver quality code rapidly to market.\nSeamless Integrations: Create software services that integrate effortlessly and securely with banks, third-party platforms, and vendors.\nInnovative Problem Solving: Think outside the box, innovate, experiment, and continuously improve by learning quickly from failures to provide simple yet effective solutions to complex problems.\n\nRequirements\nEducational Background:\nBachelor’s degree or higher in Computer Science, Engineering, or a related field.\n\nExperience\n5+ years of software development experience.\nSolid expertise in Golang (or the confidence to learn it quickly when coming from other similar programming languages).\n\nAPI Design & Development\nProficient in designing and developing RESTful APIs and gRPC interfaces.\nExperience building backend services optimized for high performance, scalability, and reliability.\n\nDatabase Expertise\nStrong database and schema design skills for performance and scalability across both relational and NoSQL databases (e.g., MySQL, PostgreSQL, MongoDB, Redis, Elasticsearch, RocksDB).\n\nSystem Design\nDeep understanding of complex system design, design patterns, data structures, algorithms, microservices, and event-driven architecture.\nExperience with system tuning for high performance and reliability.\n\nDevOps & Tooling\nHands-on experience with CI/CD tools such as GitHub workflows and Jenkins.\nFamiliarity with Docker containers and Kubernetes.\nKnowledge of automated testing practices, caching techniques, and version control systems like Git.\n\nNice To Have\nExperience with cloud platforms (AWS, GCP, or Azure).\nExposure to or interest in the AI domain with a willingness to leverage AI to enhance team productivity.\nExperience with microservice architecture is a plus.\n\nWhat We Offer\nJoin our team and enjoy:\nCompetitive compensation package, including 13th-month salary and performance bonuses\nComprehensive health care coverage for you and your dependents\nGenerous leave policies, including annual leave, sick leave, and flexible work hours\nConvenient central district 1 office location, next to a future metro station\nOnsite lunch with multiple options, including vegetarian\nGrab for work allowance and fully equipped workstations\nFun and engaging team building activities, sponsored sports clubs, and happy hour every Thursday\nUnlimited free coffee, tea, snacks, and fruit to keep you energized\nAn opportunity to make a social impact by helping to democratize credit access in emerging markets\n\nAbout Us\nWe are an AI Fintech company specializing in assessing credit profiles of consumers in emerging markets combining pioneering AI with large alternative data sources. In 2020 we reached our ambitious milestone of credit profiling 1 billion consumers spanning 4 countries - Vietnam, Indonesia, India & the Philippines - and building a platform for the wider industry and the financial services industry, in particular, to provide the "un & under" served access to credit. At the core of this initiative has been our strict and unwavering adherence to the norms of consumer data privacy and consumer data rights.\n\nBut we\'re not satisfied as we embark on the next leg of our journey to deliver 100 million credit lines to consumers in the markets where we operate. Although this goal is ambitious, we truly believe that by harnessing the power of AI & Big Data we can deliver financial access at an unprecedented scale.\n\nAs a firm, we\'re audacious problem-solvers motivated by our impact on society. We deeply espouse the values of ownership - of our actions and initiatives, integrity in all we do, and agility in execution.\n\nWe place great importance on doing what is right, what is best, and what is innovative. If you are smart, driven, and want to make a difference in the world with the most advanced and fascinating technology, come join our team. We can satisfy your desire to explore new territory and give you the runway to really make an impact.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2129, 1097, 2, 'C/C++ Engineers (HN - Hybrid)', 'AXON Networks delivers a robust AI-driven, analytics-based orchestration platform and a wide portfolio of next-gen high-speed routers that leverage the newest Wi-Fi technologies. Together, these technologies give ISPs the ability to manage and troubleshoot their networks in real time, and to deliver an outstanding customer experience.\n\nAXON Networks is a trusted strategic partner for its customers, helping them evaluate their current technologies and business models, and creating and executing strategies that enable them to innovate faster, accelerate their digital transformations, and strengthen their relationships with consumers.\n\nAXON Networks is headquartered in Irvine, CA USA with Asia HQ in Singapore and also operating in Denmark, Spain and Vietnam.\n\nResponsibilities\n\nWe are looking for a talented individual with solid C/C++ programming, IP networking protocol knowledge and Linux Development experience. Come join our team in Vietnam!\n\n- Design, Develop and debug the software framework and components\n- Lead software architecture discussion and design on advanced residential gateway and IoT platform\n- Analysis and troubleshooting critical issues reported from QA and external customers.\n\nRequirements\n\n- B.Sc./M.S. Degree in Computer Science, Software or Electrical Engineering or equivalent.\n- At least 5 years of C/C++ programming experience\n- Strong Linux development experience\n- Strong IP networking knowledge and hands-on experience\n- Proficiency in English - spoken and written.\n- Proven ability to collaborate with multi-disciplinary teams\n\nCompetitive Advantage If You Have Experience With\n\n- Wi-Fi 11b/g/n/ac/ax and other wireless protocols, including low power HAN, Bluetooth and LTE\n- Network security knowledge\n- OpenWRT framework\n- ADSL/VDSL technology\n- SDN/OpenFow/NFV/Open vSwitch, SaaS techniques and related open source project\n- Agile/Scrum Background\n\nBenefits\n\n- Competitive remuneration package\n- TET bonus, Health insurance\n- Annual leave + Medical leave\n- Family care leave + Birthday leave\n- Flexi time, hybrid work\n- Monthly teambuilding activity\n\nJoin AXON Networks!\n\naxon-networks.com\n\naxon-networks.hire.trakstar.com', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2130, 676, 2, 'Bridge Software Engineer (BrSE)', 'Role Summary\nWe are seeking a highly skilled Bridge Software Engineer (BrSE) to act as the key communication link between Japanese clients and local development teams. The role involves translating business requirements into technical solutions, ensuring seamless collaboration, and delivering high-quality projects on time.\n\nJob Responsibilities\n\nCommunication Management:\n- Serve as the primary liaison between Japanese clients and development teams, ensuring clear and effective communication.\n- Translate client requirements into actionable tasks for development teams.\n- Provide regular updates to stakeholders regarding project progress and challenges.\n\nProject Coordination:\n- Define project scope, timelines, and deliverables in collaboration with project managers.\n- Monitor and manage project schedules, ensuring adherence to deadlines and quality standards.\n- Identify and mitigate risks throughout the project lifecycle.\n\nSystem Design and Development Support:\n- Create, review, and manage system design documents, including both basic and detailed designs.\n- Support the technical team in implementing client requirements, ensuring alignment with project goals.\n\nTesting and Quality Assurance:\n- Plan and oversee testing activities, including Unit Testing, Integration Testing, and Stress Testing.\n- Ensure deliverables meet quality standards and align with client expectations.\n\nTechnical Leadership:\n- Utilize tools such as Jira, Backlog, and Git for task management and version control.\n- Provide hands-on support in programming languages like Java, .NET (WPF), or SQL Server as needed.\n- Address and resolve technical challenges efficiently.\n\nDomain Expertise (Preferred):\n- Offer insights into Banking/Finance domains, such as Risk Management or Financial Derivatives.\n- Leverage expertise in frameworks like Basel Capital Accord, LCR, NSFR, or IRRBB.\n\nContinuous Improvement:\n- Proactively identify process improvements to enhance project efficiency and quality.\n- Stay updated with industry trends and emerging technologies to drive innovation.\n\nJob Requirements\n- Bachelor\'s degree in Computer Science, Information Systems, or a related field.\n- Japanese language skills equivalent to N1 level are mandatory.\n- Minimum 2 years of experience as a Bridge Software Engineer (BrSE) or in a related role.\n\nTechnical Skills:\n- Strong understanding of system design and documentation.\n- Hands-on experience in at least one programming language (e.g., Java, .NET, or SQL Server).\n- Proficiency in tools like Jira, Backlog, and Git for project and task management.\n\nProject Management Skills:\n- Familiarity with Agile and Waterfall methodologies.\n- Experience in testing processes, including Unit Testing, Integration Testing, and Stress Testing.\n\nPreferred Skills (Optional):\n- Background in Banking/Financial domains, including Credit Risk Management, Market Risk Management, or Liquidity Risk Management.\n- Knowledge of specialized financial frameworks, such as Basel Accord, IRRBB, LCR, or NSFR.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2131, 1051, 2, 'Senior Java Developer', 'Job Description\n\n• Work as software developer on the web-based application product in JAVA- related and open-source technologies\n• Develop applications based on graphical layout designs that follow the strict requirements\n• Take ownership and accountability for production service, including fix on fail, problem investigation, root cause determination, and resolution\n• Participate in and provide quality assurance activities, including code reviews, white-box testing, test coverage for own work and team outcome\n• Accountable for continuously discovering, evaluating and implementing new technologies/processes to optimize development efficiency or improve product quality\n• Establish estimation, proposing development solutions with customers\n• Continuously research and implement new technologies to maximize development efficiency\n\nRequired Skills And Experience\n\n• Good command of English (both written/verbal) is essential\n• At least 5 years of experience in software & back-end development technologies in general\n• At least 1 year of experience with Finance + eCommerce Proven hands-on experience on Java ecosystem, Spring boot, Microservices, SQL, NoSQL: MongoDB, .. \n• Experience in designing & developing RESTful APIs and microservices-based system; Strong knowledge of writing secured codes and good understanding of design patterns\n• Working knowledge of Scala/Spark/Kafka or any functional programming languages is a very BIG plus\n• Experienced in developing and deploying microservices with Cloud based technologies (AWS, Kubernetes, Docker...)\n• Experience in agile scrum-based development process\n• Experience with unit test\n\nDesired Skills\n\n• Experience as software engineer in a complex, enterprise-level development projects\n• Establish software development patterns and best practices via examples and shipping code\n• Develop architectures that are inherently secure, robust, scalable, modular, API-centric and global\n• Collaborate with business team to develop and clarify requirements to enable development of technical solutions\n• Provide executive level support for initiatives, particularly as related to re-use, funding requirements and areas of risk\n• Multi-tasking ability essential to handle multiple priorities with minimal direction from management\n\nBenefits\n\n• Salary: up to 65M\n• Probation salary is 100% of official salary\n• 13th-month salary and performance review twice a year\n• Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n• Project Bonus\n• IT Certificate allowance\n• Health Care Insurance\n• Social, health and unemployment Insurance following Government policy\n• Enjoy company summer trips and other team building activities held monthly and quarterly\n• Work five days per week with flexible check-in time\n• Professional, creative and dynamic working environment', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2132, 209, 2, 'Android Application', 'Develop Automotive In-Vechile Infotainment system for the next generation luxury vehicles based on latest version of Google Android Automotive. Joining the project, you will have chance to facing with cutting-edge technology such as connected-car, hypervisor.\n\nJOB Specification \n- Minimum 3 years of experience developing Kotlin on Android.\n- Good knowledge in Kotlin and Android development environment: Activity, Fragment, Service, Customize View UI Layout, Animation (Property, View, Drawable), Jetpack Architecture component.\n- Have experience with design patterns like MVC, MVP, MVVM.\n- Experience with designing layouts to support multiple screen sizes and densities and handling localization support.\n- Experience with version control tools like SVN and GIT.\n- Android application development tools and environments (Android Studio).\n\nNice-to-Have Skills:\n- Having knowledge of Android AOSP and Android Automotive\n- Having knowledge of SOLID, Design patterns\n- Having knowledge and experience with Agile Software Development frameworks.\n- Experience with performance and memory optimization.\n- Familiarity with Inter Process Communication (IPC) to connect between processes in Android.\n\nBENEFITS\n- Competitive salary. Bonus based on performance. \n- Young and dynamic working environment. \n- Continuous development of hard and soft skills through work and professional trainings.\n- Opportunity to approach newest technology trends\n- Exciting leisure: sport and art events (football club, family day...)\n- Company\'s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2133, 927, 2, 'Lead App Frontend Developer', 'Job Summary\nWe are partnering with a leading foreign bank is looking for a Lead App Frontend Developer to drive the development of high-performance, secure, and scalable applications. You’ll play a key role in shaping frontend architecture, leading technical direction, and collaborating closely with cross-functional teams to deliver exceptional digital experiences.\n\nResponsibilities\n1. Lead the development of high-quality, impactful, and scalable products and systems to achieve business goals.\n2. Requirement for Android :\n- Kotlin, Java programming languages\n- MVVM architecture pattern\n- Coroutines for asynchronous programming\n- HTTP client implementation\n- Compose UI framework\n- Unit testing and UI testing\n- Google Play Store policy compliance\n3. Requirement for iOS :\n- Swift programming language\n- MVVM architecture pattern\n- HTTP client implementation\n- SwiftUI framework\n- Unit testing and UI testing\n- Apple App Store policy compliance\n4. Collaborate closely with engineering managers and engineers across multiple platforms and domains.\n5. Support to recruit, develop, and retain exceptional engineering talent who excel in innovative, user-focused, fast-paced environments.\n6. Establish and maintain high engineering standards for your team regarding quality practices, delivery speed, architecture, design, and code quality, with clear measurable goals.\n\nRequirements\n- Bachelor\'s degree or higher in Computer Science or related field.\n- Familiarity with mobile frameworks.\n- Familiarity with Swift/Objective-C; Kotlin/Java.\n- Familiarity with version control tools (e.g., Git)\n- Good understanding of web standards and best practice.\n- Has team collaboration awareness, able to work cooperatively with team members. Experience in Scrum is a plus.\n- Good communication skills and logical thinking/judgment abilities.\n- Fluent in English or is willing to learn multiple languages including Chinese to effectively communicate with the team.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City Metropolitan Area', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2134, 1017, 2, 'Backend Engineer: Platform API - Vietnam', 'Backend Engineer: Platform API - Vietnam\n\nCompany Introduction\n\nOur mission is to enable every organization to be climate conscious and positive with the world’s best climate software and data products. Persefoni is creating an all-in-one platform that allows organizations to measure, analyze, and reduce their Enterprise Carbon Footprint. Our goal is to provide our customers unprecedented visibility and insights into the impact their organization has on the environment. Leveraging the latest breakthroughs in data science and software, our technology will empower teams and leaders to mobilize their organizations to continuously improve their greenhouse gas emissions metrics.\n\nAbout The Role (What You Will Get To Do)\n\nThe Backend Engineer will be a key member to assist in building out our web services and backend persistence layer. Successful candidates should have a minimum of three years of recent professional programming in positions requiring the skills listed below with an emphasis on Golang, SQL and data modeling development. Our project entails implementing our pre-approved development targets and developing a robust and reusable code framework to deliver a variety of new features across our product lines according to our preferred architecture design and best practices. Our backend stack is a combination of Golang, Redis, MySQL, and Snowflake while following the Clean Architecture Design pattern. APIs are documented and managed using the Open API framework and maintained in ReadMe. All development work is managed via JIRA tracked sprints, Github trunk-based management, and infrastructure is managed in AWS with monitoring in Datadog.\n\nResponsibilities (What We Expect)\n• Collaborate on the design of data models, technical architecture, data flows, schemas, and API contracts. \n• Relay updates on existing work via Jira ticket status, push well documented pull requests for features, and collaborate through review and comments on your fellow developer pull requests. \n• Building scalable and robust APIs within Go following the Clean Architecture Design pattern and API best practices around security and scaling. \n• Write/Update Open API documentation to document new/existing APIs. \n• Write/Update unit and integration tests to ensure adequate test coverage of our code base.\n\nQualifications (What You Bring To The Role)\n• At least 3+ years experience professionally programming in Go. \n• At least 3+ years of experience specifically building back-end systems. \n• At least 3 years of experience writing SQL against normalized data structures. \n• Proficiency with code debugging and uncovering performance issues utilizing developer tooling. \n• Proficiency writing unit and integration tests. \n• Proficiency in English language is highly preferred.\n\nHow You\'ll Know You’re on the Right Track\n• Within your first day, you should have been able to clone the repository and install the necessary tooling to build and run our projects locally. \n• Within your first week, you will be familiarizing yourself with the code base and coordinating work on development tickets as requested. \n• Within your first month, you should be successfully operating within the development team, submitting PRs, providing feedback on team member PRs, and advancing your assigned projects with your contributions. \n• Within your first year, you should be contributing to the data and software engineering teams to provide your personal insights as to how to improve our processes and architectures.\n\nJob Type:\n\nFull-time position located in Vietnam governed by Vietnam labour regulations, with the Persefoni entity being established in Vietnam.\n\nInterview Process\n• Step 1: Initial screen with talent acquisition\n• Step 2: Technical Interview\n• Step 3: Interview with Vietnam Country Director\n• Step 4: Interview with Engineering Leadership team\n• Step 5: Offer extended\n• Step 6: Background check and onboarding\n\nPersefoni is an Equal Opportunity employer\n\nWe are committed to valuing and respecting people and organizations of all backgrounds. We proudly bring this to life by fostering a culture of innovation, creativity, diversity of thought, and inclusion.\n\nWe strive for each of our team members to be able to show up for work every day as their genuine selves. Similar to the reverence given to Earth’s biodiversity, we recognize the vast potential that exists when all of the facets of diversity within our team are appreciated and illuminated. This policy extends to all aspects of our employment practices.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Či Minovo Město, Ho Či Minovo Město, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2135, 299, 2, 'Java Techlead', 'Company Description\nEstablished in 2012, VMO Holdings (VMO) is a leading provider of professional IT services with a team of 1,200 employees, operating 6 offices in Vietnam and 5 international branches in Japan, Thailand & Singapore. In 2025, VMO officially became a member of the Alten Group, a global leader in Engineering and IT Services with a presence in 30 countries.\n\nCompleting the VMO ecosystem and focusing on core values in all VMO activities will be the basis for us to confidently empower and trust the next generation. Each member of VMO should always set new goals for themselves, change their mindset, develop themselves and their organization to join VMO in conquering all challenges and developing sustainably in the future.\n\nRole Description\nThis is a full-time on-site role for a Java Techlead located in the Hanoi Capital Region. Responsibilities include:\n• Lead the design, development, and deployment of scalable Java-based applications and microservices.\n• Provide technical guidance, enforce coding standards, and mentor development team members.\n• Collaborate with cross-functional teams to ensure high-quality delivery aligned with business goals.\n\nQualifications\n• Must have excellent communication\n• Strong academic background or relevant work experience\n• Must have 1+ years track record of leading small engineering teams\n• Must have 6+ years of experience with Java & Advanced knowledge of\n• Springboot framework\n• Must have 3+ years exposure to Docker, Kubernetes, Helm Charts, GitHub\n• Actions\n• Good attitude and accountable\n• Great English communication\n\nATTRACTIVE REWARDING POLICY AND WORK-LIFE BALANCE\n• Salary of up to 70.000.000 VND gross (Negotiable)\n• Review salary 1-2 times/year, with the possibility of an unexpected salary rise based on capacity an infinite number of times per year\n• Policy for 13th-Month Salary Bonus and Holiday Bonuses According to Company Regulations.\n• Holiday travel mode (package 5-7 million/person), team building,...\n• Full participation in social insurance, as well as a yearly health checkup at a\nreputable hospital.\n• Comprehensive visit policy for personnel and relatives: birthday, marriage,\nchildbirth, illness, etc.\n• The football club, cycling car, badminton, ... are just a few of the sports and\ncultural activities available.\n• Allowance for classes and training awards: Learning Star of the Month,\nA chance to be the face of the year\'s study, the royalties\n\nWorking time: 8.30 am – 5.30 pm from Monday to Friday\nLocation: IDMC Building, 18 Ton That Thuyet, Hanoi or TTC Building, 19 Duy Tan, Hanoi', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Metropolregion Hanoi', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2136, 744, 2, 'Generative AI Engineer', 'ActiveFence is the leading tool stack for Trust & Safety teams, worldwide. By relying on ActiveFence’s end-to-end solution, Trust & Safety teams – of all sizes – can keep users safe from the widest spectrum of online harms, unwanted content, and malicious behavior, including child safety, disinformation, fraud, hate speech, terror, nudity, and more.\n\nUsing cutting-edge AI and a team of world-class subject-matter experts to continuously collect, analyze, and contextualize data, ActiveFence ensures that in an ever-changing world, customers are always two steps ahead of bad actors. As a result, Trust & Safety teams can be proactive and provide maximum protection to users across a multitude of abuse areas, in 70+ languages.\n\nBacked by leading Silicon Valley investors such as CRV and Norwest, ActiveFence has raised $100M to date; employs 300 people worldwide, and has contributed to the online safety of billions of users across the globe.\n\nAbout the Role:\nWe are looking for a highly skilled and proactive Generative AI Engineer to join our team for maternity leave cover, with the possibility of transitioning into a full-time role. This position is ideal for an analytical problem-solver who thrives in dynamic environments and can seamlessly integrate technical expertise with business acumen to deliver impactful solutions.\n\nResponsibilities:\nCollaborate with cross-functional teams to translate business needs into actionable data strategies and scalable solutions.\nDesign and implement end-to-end data workflows to address complex challenges with a focus on maintainability and scalability.\nExtract and enrich information from diverse data sources, including structured, unstructured, and image-based content, to support violation labeling and classification.\nDevelop and maintain a threat taxonomy that includes categories, keyword patterns, and severity scoring to enable accurate downstream tagging.\nApply best practices in data storage and architecture, including Spark-based ingestion into Delta Lake with appropriate schema design, partitioning, validation, error handling, deduplication, and monitoring.\nDeliver clean, robust, well-documented, and testable Python code for:\nProcess automation\nWeb scraping and API-driven data collection (including text, image, audio, and video etc.)\nScalable pipelines for data processing, enrichment, and storage using the Spark ecosystem.\n\nResponsibilities:\nProven experience solving complex problems and delivering end-to-end solutions in data-driven environments.\nHands-on experience in Python & SQL programming.\nSolid experience with PySpark, Delta Lake, and scalable schema design for big data workflows.\nFamiliarity with structured data formats (JSON, CSV) and experience in data validation and transformation pipelines.\nAbility to write clean, well-documented, and maintainable code, with clear setup and execution instructions.\nStrong attention to detail, with the ability to work independently and deliver under tight deadlines.\nAdvantage: experience working with threat intelligence, cybersecurity data, or other security-related datasets.\n\nIf you are a forward-thinking data professional who can quickly adapt, innovate, and deliver, we invite you to join our team for this exciting opportunity. Apply today to make an impact!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '베트남 Hanoi 하노이', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2137, 366, 2, 'Senior Backend Engineer (Java) - GSaaS', 'About NAVER Corp and NAVER Vietnam:\n\nNAVER Corp\n\nNAVER Corp is South Korea\'s leading technology company, best known for the NAVER search engine, LINE messenger (200M+ users), SNOW app, and NAVER WEBTOON. In 2018, NAVER was ranked 9th most innovative company globally by Forbes and listed in Fortune\'s top 6 Future 50.\n\nNAVER Vietnam\n\nIn 2021, NAVER expanded into Vietnam to tap into the country\'s growing Information Technology market by initially partnering with two leading universities in Hanoi. Later that year, the NAVER Vietnam Development Center (NVDC) was established in two major cities: Ho Chi Minh City and Hanoi.\n\nWith rapid growth, NAVER Vietnam is currently delivering a range of large-scale services, including NAVER Financial (Npay), NAVER Clip, Weverse, NAVER WORKS, and other Global NAVER platforms. Upholding the core values of "Autonomy – Challenge – Teamwork", the company is committed to becoming one of Asia\'s most advanced development centers.\n\nIn both 2023 and 2025, NAVER Vietnam was honored as the Best IT Company in Viet Nam by ITViec.com — a remarkable milestone that reflects its rapid growth and innovation.\n\nLearn more about us: https://navercorp.vn/\n\nWe are looking for a Backend Engineer (Java) for GSaaS project.\n\nYour daily tasks:\n\n- Responsible for developing and maintaining the server-side components using the Java programming language.\n- Write and maintain technical documentation, including system architecture and API specifications.\n- Take a look at NAVER WORKS services HERE\n\nYour background:\n\n- 4+ years of work experience on related work;\n- Bachelor\'s degree or above in Computer Science or related field;\n- Good Java basic skills, experience with multi-threaded programming, IO, JVM garbage collection;\n- Experience with Java performance tuning and find and resolve troubleshoot experience with Spring, Spring MVC, Spring Boot, MyBatis, MySQL, High Availability, High Concurrency Related Technologies;\n- Experience with Linux basic command, independently complete project deployment, troubleshooting;\n- Open-minded, honest and have a positive attitude towards people;\n- Good at communication skills in general and English skills in particular.\n\nIt\'s a big plus if you:\n\n- Experience with big data projects, Kafka & Hbase.\n\nFrom solid welfare programs to autonomy over working time and place, we create the culture in which we work. By joining NAVER VIETNAM, you will be involved in:\n\n- Competitive income package: Comprehensive package with full salary insurance, 13th month salary, annual performance appraisals, and incentive bonuses.\n- Learning and development opportunities: Monthly book allowance and an annual budget for online/offline courses (Udemy, Coursera, etc.) in tech, languages, and soft skills,...\n- Protecting and enhancing healthcare plan for you and your family: Premium insurance for employees and 2 family members, plus annual health check-ups.\n- Employee\'s engagement activities: Respectful, engaging culture with monthly team budgets, social clubs, and celebration gifts.\n- Working environment: Driven by "Autonomy – Challenge – Teamwork" values, with talented colleagues, supportive leaders, and modern devices supported such as Macbook Pro 14, Macbook Air 14, Dell 7450 Ultra 7,...\n- Dedication bonus: Recognizing your commitment and contributions with special bonuses and benefits at key work milestones.\n- Other benefits: Home office setup allowance, happy hours, attractive referral bonus, and more!\n\nBy applying to NAVER Vietnam, the candidate declares that the information provided is true and correct. The candidate also agrees to allow NAVER Vietnam to proceed with the provided information, any dishonesty may render for refusal of this application.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, '호치민 지역', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2138, 1098, 2, 'AI/ML Engineer', 'Overview\n\nBuild and deploy advanced AI solutions, focusing on GenAI and integration with SAP data on cloud platform (e.g: AWS, Azure, GCP).\n\nKey Responsibilities:\n- Build and deploy ML/GenAI solutions such as document Q&A, copilots, embeddings, forecasting, and recommendation systems, chatbot using SAP data\n- Develop retraining pipelines and integrate with data from SAP modules\n- Design and implement custom RAG (Retrieval Augmented Generation) solutions for SAP data\n- Research and apply new techniques in ML and GenAI combined with the SAP ecosystem\n- Collaborate on use case delivery and model evaluation based on SAP\n\nRequirements:\n- Minimum 3 years of experience in AI/ML field\n- Experience with modern frameworks such as PyTorch, TensorFlow, or JAX\n- Experience working with GenAI models, especially LLMs and vector embeddings\n- Understanding of prompt engineering, RAG, and LLM fine-tuning\n- Knowledge of Frontier models (GPT-4.x, Claude, Llama, Mistral) and open-source models\n- Experience integrating AI with SAP systems is a significant advantage\n\nTechnical Skills:\n- ML/Deep Learning: PyTorch, TensorFlow, Hugging Face Transformers\n- SAP AI Foundation: SAP AI Core, SAP AI Launchpad, SAP AI Business Services\n- SAP Data Intelligence: Pipelines for ML workflows\n- GenAI: LangChain, LlamaIndex, OpenAI API, Vertex AI\n- SAP HANA Machine Learning: PAL, APL, and integrated ML libraries\n- Programming languages: Python, R\n- MLOps: Weight & Biases, MLflow, Kubeflow, SAP AI Business Services\n- Vector databases: Pinecone, Weaviate, FAISS, Chroma\n- SAP BTP AI Services: Document Information Extraction, Business Entity Recognition\n\nBenefits:\n- Competitive base salary and KPI bonus.\n- Attractive bonus program according to Company’s regulation.\n- 100% of gross offer during probation period.\n- Join full of insurance benefits as prescribed by Vietnamese Labor law after signing labor contract.\n- Young, dynamic, professional working environment with its own corporate culture.\n- Annually summer trip, teambuilding and company events.\n- CMC Healthcare programs.\n- 5 working days per week, from Monday – Friday.\n- Opportunity to self-development training, encourage creativity and innovation\n- A team of leaders and managers who value talent, helping employees maximize their capacity.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanói y alrededores', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2139, 1099, 2, 'Senior Back End Developer', 'We’re building a modern no-code/low-code platform from the ground up—designed for speed, extensibility, and enterprise-grade security. With deep integration of large language models (LLMs), a powerful business rules engine, and full auditability, our platform is engineered for the next generation of intelligent automation.\n\nThis is your opportunity to join the founding engineering team. Our leadership team previously built and exited a company valued at over $650M—now, we’re taking everything we’ve learned and aiming even higher.\n\nYour Role\nAs a Lead Back-End Java Engineer, you’ll help architect and build the foundation of our platform. You’ll have a critical voice in key technical decisions and the chance to shape the product from day one.\n\nWe’re looking for engineers who take pride in clean code, system resilience, and technical ownership—and who enjoy working alongside others who feel the same.\n\nWhat You’ll Do\n- Design and develop scalable, high-performance back-end services and APIs using Java (Spring)\n- Lead the development of fault-tolerant, secure, and modular systems\n- Build and maintain containerized applications using Docker and Kubernetes\n- Collaborate with front-end and DevOps teams to ensure seamless delivery\n- Influence architectural decisions and long-term infrastructure strategy\n\nWhat You Bring\n- 2+ years of professional Java experience (Spring framework preferred)\n- Strong understanding of Docker, Kubernetes, and cloud-native development\n- Familiarity with PostgreSQL and modern data modeling\n- Experience building distributed systems and optimizing backend performance\n- A solid academic background in Computer Science, Mathematics, or a related field\n\nWhy Join Us\n- Remote-first, full-time role with flexible working hours\n- Competitive compensation, stock options, and three weeks of paid leave\n- Ownership of key decisions and features in a fast-moving, engineering-led company\n- Profit-sharing once we go to market\n- Opportunity to build something meaningful that lasts—with a team that values craft and integrity\n\nWe’re looking for senior engineers who want to solve real problems, take end-to-end ownership, and build technology that empowers others.\n\nReady to Build Something New?\nSend your resume to hello@findfolks.tech. We’d love to hear from you.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2140, 442, 2, 'Intermediate Full-Stack Software Engineer', 'Who We Are\n\nEmployment Hero is on a mission to make employment easier and more valuable for everyone. Our Employment Operating System brings hiring, HR, payroll and benefits into an all-in-one solution.\n\nSince our inception in 2014, we\'ve scaled to a $2 billion valuation and gained a presence in 6 countries globally - Australia, New Zealand, Singapore, Malaysia, the UK and Canada. We now service over 300,000 businesses and more than 2 million employees.\n\nThe EH Way\n\nAt Employment Hero, we\'re proud of our unique DNA, which we call The EH Way.\n\nWe are Mission First - everything we do (from what we work on, to how we allocate capital and where we focus) is driven by our Mission\nWe are Remote First - we champion a remote environment with a preference for asynchronous communication and a high degree of autonomy\nWe are AI First - we are committed to using AI to accelerate our mission; AI is not just a tool, it\'s a fundamental part of how we operate, innovate, and scale\nWe are Apolitical - we do not take a position on political or social topics, unless it relates to our Mission\nWe Live by Our Values - we role model our values 100% of the time\nWe Expect High Performance - we set a high standard and we\'re not satisfied with being average\n\nThis role\n\nAs one of our Intermediate Full-Stack Engineers, you\'ll be accountable for building and deploying the innovative features that change our customers\' lives every day. From our trailblazing AI hiring tool to our fully automated payroll solution, every component of our Employment Operating System is carefully designed to disrupt the employment industry for the better, improving the lives of business owners and entrepreneurs everywhere.\n\nOur world-class Product and Engineering teams delivered almost 1,000 new features last year. As one of our Senior Engineers, you\'ll play a vital role in the continued acceleration of our product strategy.\n\nThis will include\n\nDriving your squad to develop critical features for our customers. We primarily develop our applications using Ruby. If you\'re not familiar with Ruby, no worries—we offer training to ensure you\'re equipped with the necessary skills.\nCollaborating closely with our global team of designers, product managers and UX specialists to gather requirements and translate them into technical solutions.\nWriting automated tests for your production codes.\nDeveloping and maintaining key components of web applications.\nConducting testing and code reviews for both yourself and your colleagues.\nMentoring the Junior Engineers within your squad.\n\nWho You Are\n\nTo thrive at Employment Hero, you\'ll need to embody The EH Way - operating with focus, agility, and an obsession with impact. For this role, you\'ll also bring\n\nOver 4 years of experience in Software Development, with a focus on Server-side and RESTful API Development and integration.\nProficiency in OOP languages such as Python, Java, PHP, etc., is highly desirable, with the expectation that you are willing to learn Ruby upon joining our team.\nYou are proficient in ReactJS (or a similar modern Frontend framework) and have experience building scalable, maintainable UI components.\nDemonstrated experience implementing, maintaining and deploying full-stack web technologies.\nStrong skills in Object-Oriented Programming (OOP).\nStrong understanding of standard Software Engineering processes, Testing, and Agile methodology.\nA team player who always puts colleagues ahead of yourself and has a highly adaptable and versatile approach to work.\nYou are passionate about learning and sharing your knowledge, and not afraid to challenge your peers, but also welcome being challenged.\nYou have experience in mentoring teammates, or even leading an Engineering squad.\nEnglish language abilities, both written and verbal - you\'ll be working with people across the world, including from Australia.\n\nWhat We Can Offer\n\nAt Employment Hero, we don\'t just talk about a better way to work - we live it. Joining Employment Hero means\n\nYou will work remotely, with the flexibility to own your time and impact.\nYou will access cutting-edge tools to amplify your work, knowledge and outputs.\nYou\'ll surround yourself with ambitious, outcome-driven colleagues who challenge you to do the best work of your life.\nYou\'ll own ESOP (employee share options) in one of the world\'s fastest-growing tech companies.\nYou\'ll also have access to a wide range of benefits that includes - a very generous paternity leave policy, subsidised egg freezing (so you can make the choice that\'s right for you, on your terms), a WFH office expense budget, and outstanding learning & development opportunities.\n\nAt Employment Hero, we are committed to safeguarding the privacy of your application data. To understand how we do so, you can read our Applicant Privacy Policy here.\n\nEmployment Hero celebrates diverse perspectives and experiences, we invite people of all backgrounds and identities to apply for this position.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2141, 532, 2, 'Senior Frontend Developer', 'About Sunbytes\n\nSunbytes is a leading Tech & Talent Solutions company known for innovative and scalable solutions. We focus on achieving goals for our partners and team members, delivering high-quality products and services, and fostering a supportive, challenging work environment. Our diverse team shares a common purpose, making Sunbytes a great place to work. We offer comprehensive long-term partnerships, including recruitment, dedicated worldwide talents, and custom software development, tailored to meet client needs.\n\nAbout the Role:\n\nSunbytes is currently seeking a highly skilled Senior Frontend Developer on behalf of our prominent client. This full-time position is based in Dong Da, Hanoi, Vietnam. You will be a key contributor to a global engineering team, playing a pivotal role in delivering high-quality solutions using modern technologies and agile methodologies.\n\nKey Responsibilities\n\n- Apply modern software development practices and agile methodologies to build robust applications.\n- Write clean, well-structured, scalable, and efficient code, including comprehensive automated tests.\n- Actively participate in all agile ceremonies, including sprint planning, daily stand-ups, and review meetings.\n- Deliver high-quality technical solutions that are aligned with business objectives and user needs.\n- Contribute to technical decision-making processes and architectural discussions.\n- Support in tracking and addressing technical debt to ensure long-term code health.\n- Continuously research and evaluate new technologies, libraries, frameworks, and tools to drive innovation.\n- Mentor and share knowledge with team members to foster skill development.\n- Embody core values: trust, respect, adaptability, and commitment in all interactions.\n\nAdditional Responsibilities\n\n- Collaborate closely with cross-functional teams throughout the design and development phases to uphold UI architectural standards.\n- Partner with UX/UI designers to craft a modern, intuitive, and highly user-friendly interface layer.\n- Build proof-of-concept prototypes for advanced features and innovative designs.\n\nRequirements\n\nTechnical skills:\n\n- 5+ years of professional experience with leading frontend frameworks such as React, Svelte, Vue.js, or similar modern JavaScript frameworks.\n- Expert-level command of HTML, CSS, and JavaScript/TypeScript.\n- Strong understanding of software development methods, principles, and practices.\n- Hands-on experience using Git in a professional, collaborative environment.\n- Proven ability to diagnose, prevent, and resolve performance and optimization issues in web applications.\n\nSoft Skills\n\n- Fluent in English, both written and verbal.\n- Strong team collaboration skills to work effectively in a diverse team setting.\n- Excellent analytical and problem-solving skills with a keen eye for detail.\n\nBenefits\n\n- A highly competitive salary package with 100% salary during the probation period.\n- Annual salary review and a 13th-month salary bonus.\n- Comprehensive premium accident and healthcare insurance covering employees and their children.\n- Flexible working hours (Monday to Friday) with no overtime.\n- A work culture that promotes creativity, innovation, and work-life balance.\n- An engaging work environment with engaging colleagues and meaningful work.\n- Opportunity to work with experienced engineers at a leading SaaS company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2142, 674, 2, 'Python Technology Development', 'Mô tả công việc\n\n- Develop Bots as Automation Services for fields such as E-commerce, Human Capital - HR, Financial Capital - Finance, Trading, Blockchain, Legal, Real Estate\n- Find and research to reuse APIs available from open-source tools to build applications as web services that will be hosted on the server.\n- Find and research available open-source tools, configure tools for integration into large company tools.\n- Server management and maintenance, server operation process design, Ubuntu server usage and backup planning.\n- Maintain and develop the code of the enterprise cryptocurrency unit.\n\nYêu cầu công việc\n\n- Qualification: 2nd year student to bachelor\'s degree graduate in related fields such as information technology, math - informatics...\n- Have basic knowledge of programming languages, especially Python, know how to use the Ubuntu operating system, have in-depth knowledge of the entire web application development process (design, development, deployment)\n- Good analytical and time management skills, logical thinking and algorithms\n- Be proactive in work, have a sense of responsibility, have a spirit of teamwork, have the ability to research new jobs, and carry out requests from superiors.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quoc Tuan Commune, Hajfong, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2143, 743, 2, '[LTS] PHP – WordPress Developer', 'General Information\n\nPosition: PHP – WordPress Developer\n\nWorking place: Hanoi\n\nSalary: Negotiation\n\nDescription\n\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Work on bug fixing and improving application performance\n- Continuously discover, evaluate, and implement new technologies to maximize development efficiency\n\nRequirements\n\n- Strong experience with WordPress, particularly with multisite and custom plugin development.\n- Familiarity with headless WordPress architecture and GraphQL.\n- Familiarity with Gatsby and Apollo clients for building front-end applications.\n- Strong understanding of PHP and experience with modern PHP development practices.\n- Experience with database management and optimization. Especially wp multisite vs single sites.\n- Strong debugging skills and the ability to troubleshoot issues across different layers of the stack.\n- Strong problem-solving skills and the ability to work independently\n- Ability to refactor and organize existing codebase, implement best practices, and remove duplicate code\n- Nice to have English\n\n#PHP\n\n- Strong understanding of modern PHP development practices and coding patterns.\n- Experience using Composer dependency management.\n- Strong ability to write clean, readable, type-safe, and maintainable code.\n- Strong ability to understand, debug, and refactor existing code.\n\n#WordPress\n\n- Strong understanding of WordPress development practices and coding patterns.\n- Strong understanding of the WordPress lifecycle and hooks.\n- Experience working on WordPress plugins.\n- Experience working with WordPress REST API or WPGraphQL.\n\nBenefits\n\n- Attractive salary. Performance-based award. Range up to 1k5$\n- Young and dynamic working environment.\n- Continuous development of hard and soft skills through work and professional training.\n- Opportunity to approach the newest technology trends\n- Salary review 2 times/year or on an excellent performance\n- Company’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc.\n\nCONTACT\n\n**LTS Recruitment Department**\n\n- Phone Number: 02466607474\n- Email: rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2144, 893, 2, 'Lead Software Engineer (Growth Team)', 'About Us\n\nWati is the world\'s leading WhatsApp-first conversational growth platform, empowering businesses to build deeper customer relationships and accelerate revenue growth.\n\nTrusted and loved by over 14,000 customers across 100+ countries, Wati has established itself as the premier choice for businesses leveraging WhatsApp and other messaging channels to connect with customers on their platform of choice.\n\nIn a world where real-time interactions drive growth, Wati\'s story is all about business growth through conversations. At Wati, we believe that every conversation matters, whether it\'s engaging a first-time prospect, nurturing a qualified lead, or deepening relationships with loyal clients. We transform these conversations into opportunities for building relationships, and strong relationships lead to increased revenue.\n\nOur Platform\n\nThe AI-native platform simplifies complex business operations by bringing all customer interactions under one intelligent roof. Designed for scalability and ease of use, our solution delivers a measurable ROI while adapting to businesses of all sizes, from emerging startups to established enterprises.\n\nOur Backing & Partnerships\n\nWati is proudly backed by world-class investors including Tiger Global, Sequoia Capital, DST Global, and Shopify. As a Premium-tier Partner of Meta, Google, and WhatsApp, we maintain the highest standards of integration and platform excellence.\n\nAs Wati continues to scale rapidly, we\'re looking for a hands-on and experienced Lead Software Engineer to join our engineering team in Ho Chi Minh. This role is ideal for someone with a strong back-end background, leadership capabilities, and a passion for building high-quality systems. As a Team Lead, you will contribute directly to the codebase, drive system design, and guide the team to deliver scalable and maintainable solutions.\n\nKey Responsibilities:\n\nLead by example with hands-on coding, primarily on back-end services. \nDesign robust, scalable, and secure systems and architecture. \nManage and prioritize tasks effectively for the team. \nGuide and mentor engineers to support their growth and ensure code quality. \nCollaborate with cross-functional teams to align technical solutions with business needs. \nReview code, suggest improvements, and enforce best practices. \nWork independently with minimal supervision while maintaining alignment with team goals.\n\nRequirements\n\nStrong experience in back-end development with languages such as Golang, C#, or JavaScript. \nGood understanding of front-end technologies is a plus. \nProven ability to design systems, break down complex tasks, and manage team workflow. \nExperience working across different languages and tech stacks. \nStrong problem-solving and decision-making skills. \nFamiliarity with Google Cloud Platform (GCP) is a plus. \nExcellent communication and collaboration abilities. \nCompetitive English communication skills (written and verbal). \nPrior experience in a leadership or senior engineering role. \nLocated in or willing to work in Ho Chi Minh City (Hybrid setup).\n\nWhat makes you stand out:\n\nExperience with cloud platforms (e.g., AWS, GCP, Azure). \nFamiliarity with CI/CD, Docker, Kubernetes. \nUnderstanding of Agile/Scrum methodologies.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Wietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2145, 857, 2, 'Chuyên viên lập trình Mobile - React Native', 'bTaskee › Tuyển dụng › CHUYÊN VIÊN LẬP TRÌNH MOBILE REACT NATIVE\n\nCHUYÊN VIÊN LẬP TRÌNH MOBILE REACT NATIVE\n\n- Tp. Hồ Chí Minh\n\nJob Descriptions\n- Participate in designing, building and deploying mobile apps on iOS and Android platforms using React Native framework\n- Write e2e Tests using detox.\n- Optimize native APIs for solid integration with Android and iOS platforms\n- Optimize and upgrade the source code continuously to ensure quality, stability and safety\n- Showcase a strong sense of code ownership, code quality, and possess the ability to be involved in the entire Software development life cycle.\n\nJob Requirements\n- 2+ years experience in working with React Native\n- Good knowledge of React Native and its libraries.\n- Strong proficiency in JavaScript/TypeScript\n- Experience with Git, git-flow model, code review.\n- Familiar with Test driven development, unit & e2e tests.\n- Have a strong background in programming (OOP principles, design patterns, algorithm & data structure)\n- Experience in mobile and server communication using TCP/IP, Websocket, WebService and JSON/XML\n- DevOps mindset with experience with automated deployments through common CI/CD principles and technologies (Infrastructure as Code, managing staging/production environments)\n\nBenefits\n- Competitive salary depending on skills and capabilities\n- Bonus 13th month salary\n- All the employee’s benefits required by the Government\n- 12 annual leaves per year and other leaves/public holidays in accordance with the Labor Law of Vietnam', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン市 ホーチミン', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2146, 800, 2, '(Senior) Software Engineer, Android', 'As a member of the Android Platform Team, your primary responsibility will be to develop and maintain core Android systems, with a particular emphasis on technical know-how and in-depth algorithmic comprehension.\n\nResponsibilities\n\n- Design, develop, and optimize high-performance Android platform components and core functionalities with minimal reliance on third-party libraries;\n- Solve complex technical challenges using strong algorithmic and analytical skills, ensuring seamless performance and scalability;\n- Explore continuously and integrate new technologies to enhance Zalo’s Android platform efficiency;\n- Collaborate with cross-functional teams, including Product and Design to implement and refine product features with a platform-first mindset.\n\nQualifications\n\n- At least 2 years of experience in Software development with a strong focus on core system architecture;\n- Proficiency in Java and a deep understanding of the Android SDK;\n- Strong knowledge of algorithms, data structures and OOP;\n- Hands-on experience with memory management, multithreading and concurrency;\n- Experience in performance optimization for Android applications is highly desirable;\n- A proactive, open-minded approach with a strong sense of ownership and eagerness to learn and grow.\n\nNice to have\n\n- C++ knowledge is a plus, especially for low-level system development;\n- Familiarity with the core functionality of cross-platform frameworks like Flutter or React Native is a plus;\n- Strong research skills with the ability to quickly adapt to various technologies beyond just mobile development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2147, 786, 2, '【教育事業】品質保証エンジニア', '職務内容\nスマートフォン・パソコンで様々な授業を受けることができる教育サービス「ZEN Study」および付随する管理システムの品質管理業務全般を担当していただきます。\n\n＜サービスの紹介＞\n私たちは、未来の「当たり前」の教育をつくるため、生徒・学生や教職員の「学ぶ」「教える」体験の最大化を日々目指しています。\n\n日本発の本格的なオンライン大学「ZEN大学」や、2万名を超え日本最大の生徒数であるネットの高校「N高等学校・S高等学校・R高等学校」と連携し、ネットの時代に合わせた教育関連のサービスを開発・運営しています。\n\n【ZEN Study（旧: N予備校）】\nひとつで学習が完結するオールインワン学習アプリです。\n\n主に次のような機能を提供しています。\n\n・リアルタイムに先生や仲間の生徒とコミュニケーションを取ることで理解を深める「ライブ授業」\n\n・自分のペースで学習を進めることができて一目で進捗率がわかる「教材」\n\n・学習者同士の教え合いの場「フォーラム」\n\n※「N予備校」は2024年8月末に「ZEN Study」にリニューアルしました\n\n【ZEN Compass】\n学習者を導く先生方などが利用するコーチング支援Webサービスです。\n\nLMS(Learning Management System)として学習状況を見ることができるだけではなく、より学習者を効率的に支援できるように、さまざまな指標で先生方を支えます。\n\n＜募集背景＞\n日々、生徒はZEN Studyを使って学習を行ない、先生は学校管理システムを使って生徒へ指導しています。\n\n生徒や先生の皆さんに安定した学習環境や管理システムを提供し続けるため、品質向上を進めています。\n\n既存サービスや今後新規開発予定のサービスの品質保証に携わることができるチャンスです。\n\n高品質な学習環境を提供するために、自ら考え実行することができる熱意のある方を募集いたします。\n\n＜業務内容＞\n\n・ZEN Studyまたは角川ドワンゴ学園を支える管理システムのテスト計画、設計、動作確認項目書作成、実施および管理\n\n・スマホアプリやWebサービスの定常的な動作確認\n\nチームとして以下も推進していきたいと考えています。\n\n・既存、新規サービスへの品質保証強化\n\n・上流工程からの介入\n\n・定常的な品質改善活動\n\n・テスト自動化の可能性を検討\n\n・その他、品質向上のためにできること\n\n『ZEN Study』や『ZEN Compass』などの各サービス、または複数サービスにまたがった品質保証担当を担っていただきます。\n\n＜開発環境＞\n□ 使用ツール\n\n・コミュニケーション: Slack, Google Meet\n\n・ドキュメント: JIRA, Confluence, G Suite\n\n・デザイン: Figma, Miro\n\n・分析: GA360, Sentry\n\n＜関連リンク＞\n□エンジニア採用説明資料\nhttps://speakerdeck.com/nnndev/for-engineers?\n\n□開発者ブログ\nhttps://blog.nnn.dev/entry/2021/06/17/110000\n\n□ ZEN Study\nhttps://www.nnn.ed.nico/\n\n□ N高等学校・S高等学校・R高等学校プロジェクト採用\nhttps://www.nnn.ed.nico/recruit/\n\n□ ZEN大学\nhttps://zen.ac.jp\n\n必須要件\n\n・PC Web/Android/iOSの品質保証に習熟していること（デバイスの特性に応じた品質保証ができること）\n\n・テスト計画、設計、実施など一連のテスト工程を管理・実施した経験\n\n・エンジニアやデザイナーなど他職種のチームとの折衝経験\n\n歓迎要件\n\n・QAチームマネジメント経験\n\n・テスト自動化経験（selenium、Appium、その他自動化ツールを用いて品質保証業務を主体的に効率化した経験）\n\n・リモートワークの経験\n\n職種 / 募集ポジション 【教育事業】品質保証エンジニア\n雇用形態 正社員\n給与 応相談 前職を考慮し、当社基準により決定いたします。\n昇給：年2回（6月・12月）本人の能力・役割に基づいて評価\n賞与：年2回（6月・12月）本人の成果に基づいて支給\n※ご入社時期、個人の評価、会社の業績により夏季賞与・冬季賞与額が変動いたします。\n※退職金は前払い退職金制度\n勤務地\n104-0061 東京都中央区銀座四丁目12-15 歌舞伎座タワー\n勤務形態 裁量労働制（1日8時間のみなし労働)\n休日休暇 完全週休2日制（土・日）、祝日（※超会議に伴う営業日変更あり）\n・年次有給休暇（入社日に5日、入社日の3ヶ月後に15日付与）\n・記念日休暇\n・年末年始休暇（12/29～1/3）\n・リフレッシュ休暇（年度ごとに2日間付与）\n・特別（慶弔）休暇\n手当・制度\n・テレワーク手当\n※テレワーク対象となる社員（条件有り）に対し、月額2万円を支給\n・通勤交通費手当（上限月額50,000円）\n※テレワーク対象者は原則支給しない\nただし、業務指示における出社時の交通費は会社が認める範囲で別途支給\n・育児手当（上限月額50,000円）\n※扶養の子の保育料の半額を支給\n・役職手当（役職に応じて支給）\n・資格取得手当制度\n・サブスク手当（対象のサブスクを契約している場合、月額2千円を支給）\n福利厚生\n・各種社会保険完備（関東ITソフトウェア健康保険組合）\n・確定拠出年金制度\n・財形貯蓄制度\n・社員持株会制度\n・社内カウンセリング制度\n・同好会\n・健康保険組合各種サービス\n・社員限定美容室\n選考プロセス\n書類選考後、2回の面接を想定しています。\n※1次面接までに当社が指定する適性検査を受検いただきます。\n※全てオンライン面接となります。\n※選考の過程でコードテストを実施する可能性があります。\n会社情報\n会社名 株式会社ドワンゴ\n代表者 代表取締役社長 夏野 剛\n事業内容 ネットワークエンタテインメントコンテンツ及びシステムの企画、開発、運用、サポート、コンサルティング\n設立 1997年8月6日\n資本金 1億円（2019年3月29日現在）\n所在地 〒104-0061 東京都中央区銀座4-12-15 歌舞伎座タワー\n親会社 株式会社KADOKAWA\n子会社 株式会社バンタン 株式会社スパイク・チュンソフト Spike Chunsoft, Inc. 株式会社バーチャルキャスト 株式会社カスタムキャスト 株式会社GeeXPlus 株式会社PUBLUS', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'ベトナム ホーチミン 12区', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2148, 1100, 2, 'iOS Developer', 'Mô tả công việc\n\n- Phát triển các sản phẩm của công ty trên nền tảng iOS (Phần mềm quản trị doanh nghiệp)\n- Tìm hiểu, nghiên cứu các công nghệ mới theo định hướng phát triển của công ty\n\nYêu cầu công việc\n\n• Độ tuổi: 22 – 28.\n• Tốt nghiệp CĐ, ĐH chuyên ngành CNTT, kĩ thuật phần mềm... hoặc tốt nghiệp các trường đào tạo lập trình viên Quốc Tế (NIIT, Aptech) trở lên.\n• Tối thiểu 1.5 năm kinh nghiệm lập trình iOS.\n• Hiểu biết sâu về OOP, cấu trúc dữ liệu & giải thuật.\n• Sử dụng thành thạo các công cụ lập trình như Xcode.\n• Thành thạo một trong các ngôn ngữ Objective-C/Swift.\n• Thành thạo ngôn ngữ flutter là một lợi thế.\n• Nắm vững các UI control, layout và animation trong iOS, có khả năng customize và tối ưu giao diện.\n• Có kinh nghiệm lập trình giao tiếp giữa mobile và server qua các giao thức TCP/IP, HTTP, nắm vững XML, Json.\n• Có hiểu biết về các kiến trúc phát triển di động: MVP, MVVM, Clean Architechture,…\n• Sử dụng thành thạo các công cụ quản lý source code (git), quản lý dự án (Jira).\n\nQuyền lợi\n\nTiên phong công nghệ, uy tín\n\n- MISA là doanh nghiệp CNTT xuất sắc nhất khu vực Châu Á - Châu Đại Dương. Tiên phong xuất khẩu giải pháp SaaS\n- TOP đầu doanh nghiệp CNTT tăng trưởng liên tục với quy mô nhân sự tăng 20%/năm, doanh thu tăng 15%/năm\n- Hội tụ 3000 nhân tài cùng khát vọng đưa sản phẩm công nghệ “Make In Vietnam” vươn tầm quốc tế\n- Xây dựng niềm tin với 350.000 khách hàng là đơn vị HCSN, doanh nghiệp, 2.5 triệu khách hàng cá nhân tại Việt Nam và 22 quốc gia\n- Hơn 100 giải thưởng trong ngành CNTT trong nước và quốc tế\n\nNền tảng vững chắc cho phát triển sự nghiệp, thăng tiến, quyền lợi\n\n- Lương cứng cạnh tranh. Thưởng năng suất dựa trên kết quả công việc từ 2 tháng lương.\n- Đánh giá review lương 2 lần/năm, thưởng sáng kiến...\n- Huấn luyện “Hổ tướng”: chương trình đào tạo quản lý tài năng, bệ phóng trở thành Chiến tướng tinh nhuệ\n- Giải thưởng “Gấu vàng": nơi tôn vinh những tài năng xuất sắc nhất\n- Gói chăm sóc sức khỏe toàn diện tại Medlatec, cháy hết mình tại các CLB theo sở thích, chương trình teambuilding, du lịch định kỳ\n\nMôi trường thân thiện, chia sẻ, đồng hành\n\n- Kết nối tài năng: tập trung phát triển những con người có chung lý tưởng, mục tiêu, cùng trao giá trị và nhận thành công\n- Tư duy đột phá: môi trường tôn trọng sự khác biệt và đề cao sáng tạo, MISA-er được tự do phát triển các ý tưởng tiến bộ, cải tiến công việc\n- Công nghệ cao: trang bị máy tính làm việc, tối ưu hiệu suất công việc bằng ứng dụng công nghệ, phần mềm tự động (AMIS, Jira, Power BI, AI Marketing,...)\n- Nơi làm việc hạnh phúc: MISA mong muốn tạo một môi trường làm việc để bạn luôn cảm thấy hạnh phúc', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Bắc Từ Liêm, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2149, 513, 2, 'Back-End & DevOps Developer (XR Interactive App)', 'About The Role\nWe are building an emotionally intelligent XR application that blends immersive tech with affective AI. We’re looking for a mid-to-senior level Back-end & DevOps Developer to build robust backend systems and streamline our DevOps practices to support rapid experimentation and high reliability.\n\nDuties & Responsibilities\n\nCore Development & Integration\n- Participate in full software development life cycle, from feasibility analysis to implementation and deployment.\n- Design, implement and maintain microservices.\n- Integrate third-party APIs and internal services in a secure and scalable way.\n- Contribute to the technical design and documentation of new solutions.\n- Troubleshoot system issues and identify opportunities for improvement.\n\nDevOps & Infrastructure \n- CI/CD Pipeline Management: Develop, implement, and maintain continuous integration/continuous deployment (CI/CD) pipelines to automate build, test, and deployment processes.\n- Infrastructure as Code: Utilize Infrastructure as Code (IaC) practices to manage, provision, and scale production environments efficiently.\n- Containerization & Orchestration: Oversee container orchestration (e.g., Docker, Kubernetes) to ensure reliable deployment and scaling of microservices.\n- Performance Monitoring: Implement and manage monitoring and logging solutions to optimize system performance and ensure high availability. Familiar with logging and tracking solutions like SigNoz or Grafana.\n- Collaboration: Work closely with cross-functional teams to integrate DevOps best practices, streamline deployments, and improve operational resilience.\n\nIT Duties\n- Infrastructure & Support: Collaborate with IT teams to ensure the proper configuration, maintenance, and security of internal systems and networks.\n- System Troubleshooting: Provide support for hardware and software issues affecting development and production environments.\n- Compliance & Security: Ensure adherence to IT policies and security guidelines across server operations and data management.\n- Monitoring & Maintenance: Assist in the monitoring of system health, coordinating with IT support to minimize downtime.\n\nQualifications & Skills\n- Programming Languages:  Python, Go, C#, JavaScript, SQL, TypeScript, Unix Shell\n- Database Technologies: Experience with PostgreSQL, Redis. Experience with columnar database (Snowflake, Clickhouse) is a plus.\n- API Frameworks: Experience with REST & RPC API frameworks (e.g., FastAPI, Flask, Protocol Buffer)\n- Cloud Providers:  AWS, Google Cloud\n- Containerization: Proficiency with Docker, Kubernetes\n- Development Practices: Test-driven development (TDD) and domain-driven design (DDD)\n- CI/CD & Tooling: Familiarity with Jenkins, GitHub Actions, or similar tools\n- Workflow: Experience with Agile development (e.g., Scrum, Kanban)\n- Self-driven and proactive mindset\n- Clear communication, especially in async and remote settings\n- Ability to balance technical quality with pragmatic delivery\n\nNice To Have\n- Working experiences with Unity, C# are a strong plus.\n- Familiar with CI/CD shipping Android and IOS Applications from Unity\n\nAdditional Information\nDomain: games and interactive apps\nMain stack: Unity, Unity Polispatial, Unity Cloud \nDevices: Apple Vision Pro and other VR/XR headsets \n\nHow To Apply\nPlease send your application to joinus@bootloader.studio', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2150, 274, 2, '(Junior/Middle/Senior) Android Kotlin Engineer', 'As an Android Software Engineer, you will work on building scalable, high-performance applications with a focus on performance optimization and clean architecture.\n\nImplement Android (Kotlin) and Flutter components of our SaaS product\nDrive the entire mobile software lifecycle, from prototyping to commercialization and post-launch support\nBuild clean, well-tested, and maintainable code that aligns with our cross-platform architecture and performance goals\nParticipate in design reviews, code reviews, and contribute to cross-functional discussions and continuous improvement\nPartner with Product, Design, and Backend teams to deliver quality Android applications\n\nFor Senior:\nPropose architecture and design reviews to ensure high standards in software quality\nSet a high technical standard for the team through code and design reviews\nEnhance engineering processes, including sprint planning, stand-ups, and long-term planning\nMentor junior/middle engineers, foster growth, and technical skill development within the team\n\nYour Skills and Experience\nBachelor’s Degree in Computer Science / Information Technology / Software Development or related fields\n\nMust have:\n1+ year of experience in Kotlin and Flutter cross-platform technologies\nHands-on experience in independently completing or participating in large-scale Android projects\nGood understanding of framework principles, and practical experience in performance optimization for low-end device models, including but not limited to startup, memory, network, etc\nUnderstand Jetpack components, familiar with annotation frameworks, and have practical experience\nGood/Fluent English communication is mandatory\n\nNice to have:\nPractical experience in catering apps, with architecture ability preferred\nExperience with hardware knowledge reserves and practical experience (including but not limited to printers, external card machines, USB/Bluetooth communication) is preferred\n\nWhy You\'ll Love Working Here\nWe are a multinational, product-driven company specializing in proprietary POS solutions — developing in-house and delivering directly to our worldwide customers.\n\nBenefits\nRecognition & Rewards:\n13th-month salary\nLoyalty Bonus programs\nBiannual Performance and Salary review\nComprehensive Insurance Coverage:\nFull government public insurance contributions based on gross salary\nPremium health insurance\nAnnual health check\nClear career development and growth structure; Training sessions and Learning workshops\n14 days of annual leave and one additional day of leave for every year of service\nLaptop/MacBook and top-notch facilities are provided based on each role\nAgile/Scrum-based internal workflows for efficient and collaborative development\nCompany trips, parties and regular team-building activities; Weekly happy hour, coffee, snacks, and board games\nOverseas travel opportunities based on the individual performance and policies for each evaluation period\n\nWorking Environment & Culture\nInternational Workplace: English-speaking environment\nPositive and Open-Minded Culture: Engineers are encouraged to propose innovative solutions that enhance productivity and code quality\n1-on-1 Mentorship: Monthly coffee sessions with managers offer personalized feedback, goal setting, and career development opportunities\nFlexible Working Hours: Promote work-life balance and individual productivity', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minhstad en omgeving', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2151, 1101, 2, 'Senior Software Developer Level 2', 'SEADEV is a product company that delivers effective, affordable sales and digital marketing solutions to our clients. We measure our success not only in terms of profit, but also in terms of global spiritual impact. As a company, we seek to care for our team members and bring transformation to lives in our community. Over the next 10 years we are laser focused on achieving our targets of growing our business 10-fold, supporting over 500 jobs in 10 developing markets, while positively transforming the communities we work within by giving financially and volunteering our time.\n\nJob Overview\n\nThe Senior Software Developer Level 2 will join the ShedPro (https://shedpro.co) team and report directly to the Product Manager. ShedPro has been the main focus for Seadev over the past three years, with a mission to develop cutting-edge sales and lead generation products (including 3D Configurator for Sheds & Carports, Sales-Focused Website and Google Ads Management) catered specifically to shed builders, manufacturers, and dealers in the North American market.\n\nAs the Senior Software Developer Level 2, you will play a vital role in crafting the next generation of our products, from designing and implementing new features to refining existing functionalities. Collaborating closely with cross-functional teams, you\'ll ensure our solutions meet top standards. With a focus on problem-solving and innovation, you\'ll drive our projects forward, shaping the future of ShedPro\'s offerings.\n\nRequirements\n\n- Minimum 5 - 7 years of working experience as a software developer, software architect, or similar.\n- Strong proficiency in JavaScript/TypeScript and Node.js\n- Knowledge of multiple front-end (e.g. HTML/CSS, JavaScript) and server-side (e.g. PHP, Node.js) languages\n- Experience with the Git version control system\n- Familiar with Agile software development practices\n- Solid understanding of RESTful API design principles\n- Experience with ReactJS/Laravel & WordPress\n- Experience in cloud solution development with AWSs\n- Fluent in English skills (writing, speaking, listening, reading)\n- Experience working with international clients directly\n- Experience in writing unit tests is a plus\n- Understanding and experience working with 3D models or Babylon.js is a plus\n\nBenefits\n\n- Bonus: 13th Salary, Work anniversary bonus, Referral bonus, Commission for bringing new project\n- Gifts: Birthday gifts for employees and their children, Wedding anniversary gift, Tet\'s gift, Baby shower, Women\'s day, Children\'s day\n- Healthcare: Private Health Insurance & Annual Health Checkup\n- Performance & Salary Review: Annual assessments to ensure fair and equal pay based on performance results\n- Vietnam Social Security: Contribution from probation period.\n- Healthy Food & Snacks: FREE daily snack and Friday lunch\n- Team building events and holidays: Company retreat, Family Day, Thanksgiving, Christmas, Year End party\n- 17 days off per year: 10 days of annual leave, 5 sick days, 2 Christmas days, and other public holidays as per regulations\n- Haft Friday off in 03 months of summer: Enjoy longer weekends, recharge, and soak up the summer sun\n- Learning & Development: Weekly training & inspirational talks at our Social Forum and English classes\n- Sport activities: Badminton & football', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnã', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2152, 1102, 2, 'Back End Developer', 'Mô tả công việc: \n· Phát triển các hệ thống Back end chạy trên Cloud (AWS), Nodejs (Nestjs), làm việc tốt với các loại CSDL chính (SQL, No-SQL);\n· Tham gia vào toàn bộ vòng đời của ứng dụng, tập trung và coding và debug các dự án website và hệ thống IoT, hệ thống nhà máy thông minh, thương mại điện tử;\n· Viết API kết nối giữa các hệ thống, và phục vụ trao đổi dữ liệu với mobile & front-end;\n· Xây dựng code có thể sử dụng lại và các thư viện để thuận tiện cho việc sử dụng trong tương lai, kinh nghiệm làm micro service là lợi thế;\n· Thu thập và xử lí các yêu cầu thiết kế và kĩ thuật;\n· Tham gia vào quá trình phân tích và thiết kế hệ thống;\n· Nghiên cứu và áp dụng các công nghệ mới để tối ưu hóa hiệu quả phát triển sản phẩm;\n· Đảm bảo sản phẩm làm ra cần phải chạy đúng nghiệp vụ và tốc độ xử lý cũng phải tối ưu cho lượng người dùng và thiết bị kết nối lớn.\nYêu cầu: \n· Kinh nghiệm ở vị trí tương đương từ 3 năm;\n· Kinh nghiệm phát triển dịch vụ serverless (Lambda), hướng microservice;\n· Ưu tiên kinh nghiệm IoT Core, Media Streaming, OTT, Push Notification;\n· Nắm rõ toàn bộ quá trình phát triển web (thiết kế, phát triển và thực thi);\n· Có hiểu biết cơ bản về cơ sở dữ liệu và hệ thống: MySQL, MongoDB hay PostgreSQL;\n· Có kiến thức về lập trình hướng đối tượng;\n· Khả năng làm việc tốt trong môi trường tốc độ cao, quy trình quản lý Agile.\nTính chất công việc: Full time\nĐịa chỉ làm việc: Thanh Liệt - Hà Nội\nQuyền lợi: \n· Mức lương cạnh tranh, thỏa thuận theo năng lực;\n· Thử việc hưởng 100% lương;\n· Thời gian làm việc linh hoạt từ T2-T6;\n· Môi trường làm việc trẻ trung, năng động, tài năng;\n· Mức lương cạnh tranh, Review tăng lương 2 lần/năm;\n· Thưởng ngày Lễ/Tết, thưởng hiệu suất công việc, thưởng dự án theo tháng;\n· Ăn chơi du lịch theo tháng + các hoạt động team building;\n· Có cơ hội được đào tạo phát triển và thăng tiến.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2153, 1087, 2, '[HCM/DN] Embedded Linux Kernel Engineer (open for expats)', 'ABOUT SIOUX\nSioux Group was founded in 1996 and is headquartered in the Netherlands. With over 1100 engineers, Sioux supports the R&D activities of leading high-tech companies. Sioux aims to add value to its clients and build innovative solutions that contribute to a smarter, safer, healthier, and more sustainable society. At Sioux, we strive for a Culture of Excellence and grow our employees with challenging projects.\n\nAs a Software Engineer at Sioux, you’ll have:\n- Challenging projects: work with global clients who are giant tech corporations to build complex high-tech software\n- Growing opportunity: Work with experts from around the world with a quality mindset\n- A Sincere, Open, and Fair culture\n\nWE ARE LOOKING FOR EMBEDDED LINUX KERNEL ENGINEER IN DANANG/HCM TO JOIN US!\n\nYour job will comprise:\n- Responsible for the upgrade, maintenance, and iteration of embedded Linux system kernels.\n- Optimize embedded Linux drivers to improve compatibility with various external audio/video devices.\n- Maintain the security architecture of embedded Linux systems, including Secure Boot, Trusted Execution Environment (TEE), and encryption mechanisms.\n\nJob requirements\n\nQUALIFICATIONS:\n- Technical:\n- Bachelor\'s degree or higher in Computer Science, Electronics, or related fields, with 4 years of hands-on embedded software development experience in products\n- Proficient in embedded Linux kernel development, familiar with Linux commands, kernel, drivers, and file systems\n- Experienced in embedded Linux cross-compilation and Buildroot. Experience with Rockchip platforms is a plus\n- Familiar with display technologies in embedded Linux (Weston, X11)\n- Knowledgeable in embedded security technologies (Secure Boot, TrustZone)\n- Proficient in Git, Jira, and Agile development methodologies\n\n- Soft skills:\n- Strong verbal and written English communication skills\n- Logical thinking, passionate about technology, and a strong team player\n- Open minded and proactive\n\nWHAT DO WE OFFER FOR YOU?\n\nCompensation & Benefits\n- Attractive salary\n- 13th-month salary depending on the employee’s length of service\n- Project Bonus (twice per year)\n- Social Insurance is based on government regulations\n- Full salary during probation\n\nWorking hours & Leave\n- Flexible working hours working Monday – Friday, no OT\n- Hybrid working policy\n- 19 leave days per year, for every 3 work years, +1 day to annual leave\n\nWell-being\n- Sioux Care Package: Each employee is eligible for an assigned package (based on grade and length of service) up to VND 30,000,000/ employee/ year for well-being benefits, including Premium insurance for employee and family, Annual Health Check, Personal Development, Children’s Education, Support subscription & WFH Equipment\n\nTraining & Development\n- Company-sponsored training: soft skills/ technical skills/ hot-trend technologies/ best practices/English etc\n- Onsite opportunities: long-term or short-term at other Sioux offices and client’s destination overseas (where applicable)\n\nWork anniversary bonus\n- 1st anniversary = 1 million\n- 3rd anniversary = 3 million\n- 5th anniversary = 10 million\n- 10th anniversary = 20 million\n\nSocial activities\n- Diverse company culture activities: Company trip, Annual Year End Party, Quarterly party, Company outings, Team building, Lunch & Learn Company anniversary, Family day, X-Mas party, Mid-Autumn, Snack Friday, Food and Snack in the fridge, etc\n- Sports activities: Football & Badminton club\n- Charity social responsibility activities', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2154, 707, 2, 'Senior Java Developer', 'JOB DESCRIPTION\n\nDesign, build and maintain APIs, services\nDebug production issues across services and multiple levels of the stack\nWork with engineers across the company to build delightful features that span various parts of the system\nCollaborate with our business, product, and operations teams to understand and solve our users’ pain points\n\nJOB REQUIREMENTS\n\nMUST HAVE SKILLS\n\nYou have 5+ years of software development experience\nYou have strong software development experience using Java\nYou have experience in Spring MVC, Spring Boot, Hibernate, building Restful\nKnowledge of Cloud services such as AWS or Azure\nExperience with Micro Services\nExperience with Docker, GitHub Actions, Terraform\nExperience with PostgreSQL and Redis\nStrong AI: Copilot, Claude, MCP, N8N...\nStrong English communication (speaking)\n\nBENEFITS\n\nCompetitive Salary and Brilliant Health Benefits\nAttractive salary (13th-month salary, salary review twice/year) and project bonus\nBonus programs for candidate referral, technical article writing\nInterest-free loan support for personal plan \nAllowance for sickness, maternity, paternity and periodic health examination\nPVI health care program \nThe staff of the quarter and year reward\nProgressive and Fun Working Environment\n\nA professional English-speaking working environment with Agile – Scrum model\nHybrid Working Model: Flexible working time and WFH support. \nSurrounded with friendly, open-minded, young and supportive colleagues \nAnnual company trip and regular team-building parties, party celebration (Christmas, Birthday, Mid-autumn,...), Sports clubs (football, badminton, swimming …)\n\nValuable Training\nSponsor examination fee for professional certificates (AWS, Azure, IELTS, PMP, Scrum Master,...)\nSponsor fee for joining any technical training sessions and courses.\nFree English workshops', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2155, 1103, 2, 'Nhân viên kỹ thuật - PT Staff', 'Mô tả công việc\n\n- Quản lý máy móc trên dây chuyền, sáng tạo, thiết kế sản phẩm\n- Quản lí ca sản xuất, quản lí công nhân trên dây chuyền\n- Kiểm soát chất lượng sản phẩm đầu ra\n- Sửa chữa và bảo dưỡng hệ thống máy móc hiện đại, chất lượng cao\n- Đưa ra những ý tưởng cải tiến cho công việc\n- Lập các báo cáo liên quan\n- Am Hiểu về Camera Module\n- Hiểu rõ về máy SMT.\n- Ưu tiên ứng viên có kinh nghiệm trong lĩnh vự lắp ráp Camera\n- Ưu tiên ứng viên biết tiếng Anh, Tiếng Hàn\n- Có thể đi làm ca\n\nCao đẳng', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanói, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2156, 899, 2, 'Python Developer', 'As a Python developer, you will lead and participate in development projects for our products, and be involved in all development-related aspects of our technical operations and infrastructure.\n\n• Be able to identify the requirement and propose a good alternative solution to client requirements;\n• Design and develop web (new module development, customisation);\n• Develop applications/features that affect every working day.\n\nCompensation & Benefits\n\n• Saturday & Sunday OFF, Overtime pay is 150%, 200%, 300% as per labor law;\n• Work performance review 2 times/ year (in April and October);\n• Performance bonus, 13th- month salary, public holidays bonus (2/9, 30/4, 1/5, 1/1); bonus for Excellent Employee and Excellent Team;\n• Social insurance, health insurance, unemployment insurance and Bao Viet care insurance;\n• 01 hour paid leave per day for women having children under 12 months;\n• 01 day remote work per month; A flexitime allowance of 90-180 minutes per month for employees\n• Minimum 14 paid leaves per annum for all employees after probation;\n• Nice & modern working space with young, dynamic & friendly colleagues and free coffee, tea, drinks;\n• Yearly company trip and year-end party, quarterly team building and weekly eating together; English - Japanese Club, Sports Clubs;\n• Men’s Day, Women’s Day, Children’s Day, Mid-Autumn Festival and other benefits under the provisions of the company;\n• Flat, open and sharing culture with friendly management team; outsourcing company with product mindset;\n• Training courses and working opportunities with technical gurus who built and operated world-class applications with millions of users. This might be a good chance for graduated students to learn cutting-edge technologies and how to build scalable system from scratch;\n\nRequirements\nMust have:\n\n• At least 3-4 years of experience with Python (framework: Flash, django, fastapi)\n• Experience with AI, MML\n• Strong knowledge of Python and programming concepts, especially Django/fastapi/flask\n• Knowledge of Linux flavoured operating system;\n• Good knowledge of PostgreSQL;\n• Interest in computer data structures;\n• Good at English \n\nNice To Have\n\n• Having experience working with rental and leasing systems for instances, GPUs, writing engine managers... is a plus\n• Experience with AI projects is a plus', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Quận Cầu Giấy, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2157, 1104, 2, 'Senior Java Developer', 'Location: Ho Chi Minh City\nWorkplace Type: Onsite\nKey Responsibilities\n- Work as a software developer on web-based application products using Java and related open-source technologies.\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project developments with high quality.\n- Participate in all phases of the development cycle, including planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n- Respond to and resolve IT support requests from employees via phone, email, or service request system.\n\nRequired Skills & Qualifications\n- Good command of English (both written/verbal) is essential.\n- 4+ years of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend.\n- Ability to analyze, design, and develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner).\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools.\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc.\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications.\n- Solid understanding of OOP, design patterns, and coding standards.\n\nPreferred Qualifications:\n- Experience with AWS.\n- Experience with MS .Net / .Net Core.\n- Experience with Kubernetes.\n- Experience with React.js.\n- Experience with Nginx.\n- Experience with JUnit.\n- Experience with Jasper Report.\n- Experience with ElasticSearch & Kibana (ELK).\n- Experience with Grafana.\n- Experience with Prometheus (monitoring/alerts).\n\nBenefits:\n- Salary: Up to 60M VND\n- Probation salary is 100% of official salary.\n- 13th-month salary and performance review twice a year.\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year).\n- Project Bonus.\n- IT Certificate allowance.\n- Health Care Insurance.\n- Social, health, and unemployment Insurance following Government policy.\n- Enjoy company summer trips and other team-building activities held monthly and quarterly.\n- Work five days per week with flexible check-in time.\n- Professional, creative, and dynamic working environment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2158, 1105, 2, 'BrSE (Base Tech/ Non Tech)', 'Công ty TNHH AZOOM VIETNAM INC. được thành lập ngày 27/8/2019 với 100% vốn đầu tư từ Nhật Bản. Với tiềm lực kinh tế mạnh mẽ cùng công nghệ đột phá, Azoom Japan hiện đang là một trong những công ty hàng đầu trong lĩnh vực kinh doanh dịch vụ bất động sản với tiêu chí “Biến bất động sản nhàn rỗi trên thế giới trở thành bất động sản hoạt động.”\n\nAZoom Japan hiện đang là một trong những công ty hàng đầu về kinh doanh dịch vụ bất động sản, và là một trong những công ty uy tín đã được lên sàn chứng khoán IPO của TOKYO, với doanh thu tăng và ổn định.\n\nVới vai trò BrSE, bạn sẽ là cầu nối giữa các phòng ban liên quan tại công ty mẹ tại Nhật và đội ngũ kỹ sư phần mềm tại Việt Nam.\n\nMÔ TẢ CÔNG VIỆC\n- Tiến hành nghiên cứu, phân tích yêu cầu kinh doanh và đảm bảo các thành viên trong nhóm hiểu rõ nền tảng, mục tiêu và các vấn đề kinh doanh cần được giải quyết.\n- Tham gia vào cuộc họp với các phòng ban liên quan phía Nhật Bản, nắm chắc các yêu cầu và thiết kế hệ thống rồi truyền đạt cho đội dự án ở Việt Nam.\n- Hợp tác với các Managers/Leaders để giải quyết các vấn đề liên quan (vấn đề kỹ thuật, yêu cầu thay đổi, các vấn đề trong khâu vận hành, yêu cầu điều tra, yêu cầu của khách hàng).\n- Tạo tài liệu kỹ thuật liên quan.\n\nYÊU CẦU\n- Tiếng nhật tương đương N2 trở lên, thành thạo 4 kỹ năng nghe, nói, đọc, viết.\n- Có ít nhất 01 năm kinh nghiệm BrSE.\n- Có kinh nghiệm làm việc trực tiếp với các phòng ban kinh doanh.\n- Có kinh nghiệm phân tích nghiệp vụ dự án, phân tích yêu cầu, viết tài liệu liên quan đến kỹ thuật; quy trình.\n- Trách nhiệm cao trong công việc.\n- Kỹ năng làm việc độc lập cũng như làm việc nhóm tốt.\n- Cẩn thận, tỉ mỉ, chi tiết trong công việc.\n\nQUYỀN LỢI\n- Thử việc nhận full lương, đóng BHXH full lương.\n- Thưởng tháng lương thứ 13.\n- Xét tăng lương 2 lần/năm.\n- Trợ cấp ăn trưa, tiếng Nhật lên đến 5 triệu/tháng.\n- Trợ cấp chức vụ (Leader) lên đến 6 triệu/tháng.\n- Cấp Macbook kèm server riêng.\n- Làm việc giờ hành chính, không có OT.\n- Chế độ xin nghỉ - làm bù linh hoạt.\n- Khám sức khỏe hàng năm tại bệnh viện uy tín.\n- Du lịch hàng năm, team building hàng tháng.\n- Hưởng đầy đủ các quyền lợi khác theo quy định chung của công ty và pháp luật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi Capital Region', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2159, 820, 2, 'Middle C# Developer', 'MÔ TẢ CÔNG VIỆC\n\nPhát triển ứng dụng mô phỏng tương tác 3D bằng Unity (C#).\n\nMô hình hóa logic vận hành, quy trình hoạt động của thiết bị/máy móc.\n\nTích hợp animation, UI, input (touch/controller) và các phản hồi tương tác.\n\nTối ưu hiệu suất và trải nghiệm người dùng cho các nền tảng như PC, VR hoặc màn hình cảm ứng công nghiệp.\n\nTham gia kiểm thử, tối ưu memory, hiệu năng và hiệu chỉnh mô phỏng theo phản hồi thực tế.\n\nYÊU CẦU\n\nThành thạo C#, tư duy lập trình hướng đối tượng (OOP) và các mẫu thiết kế phần mềm (Design Patterns).\n\nCó kinh nghiệm quản lý memory, xử lý animation, input, UI, v.v.\n\nKỹ năng debug và tối ưu hiệu suất ứng dụng bằng công cụ Unity Profiler, theo dõi GC, memory leak.\n\nKinh nghiệm phát triển ứng dụng mô phỏng hoặc game logic cao.\n\nKỹ năng làm việc với asset 3D (FBX, prefabs), Animator, Timeline.\n\nKhả năng đọc hiểu tài liệu tiếng Anh tốt.\n\nTư duy logic, phân tích và giải quyết vấn đề tốt.\n\nKỹ năng làm việc nhóm tốt, chủ động trong công việc, tinh thần trách nhiệm cao.\n\nBiết sử dụng Git để quản lý mã nguồn.\n\nĐÃI NGỘ\n\nTối thiểu 13 tháng lương 1 năm - chưa tính các khoản thưởng khác trong quá trình làm việc như thưởng theo KPI hiệu quả công việc, thưởng dự án và thưởng theo doanh thu.\n\nĐược khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật quy định\n\nHưởng chế độ nghỉ mát, teambuilding 4 lần/ 1 năm, và các hoạt động thể thao, giải trí phong phú bao gồm: các CLB Bơi, Yoga, Zumba, Kendo, yêu cầu bài hát qua radio nội bộ.\n\n02 nhân viên xuất sắc nhất năm sẽ được thưởng một chuyến du lịch miễn phí đến các quốc gia như Nhật Bản, Đài Loan, Singapore..v.v.\n\nCơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐược đào tạo tiếng Nhật miễn phí tại công ty.\n\nCơ hội được đào tạo để nâng cao nghiệp vụ chuyên môn. Cơ hội hỗ trợ thi các chứng chỉ về Cloud, AWS, PMF, PMP.\n\nGiờ làm việc: từ 8h30 đến 17h30, từ thứ Hai đến thứ Sáu hàng tuần.\n\nNgày hết hạn: 19 tháng 6, 2025\n\nChi tiết công việc\n\nSố Lượng\n\n1\n\nĐịa Điểm\n\nHà Nội\n\nKinh Nghiệm\n\n3 năm\n\nTrình Độ\n\nMiddle\n\nHình Thức\n\nToàn thời gian\n\nKỹ Năng\n\nC#', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2160, 1077, 2, 'MNM343 IE 实习生', 'We are a leading company in the wireless broadband communications industry looking for talented professionals with a winning attitude.\n\nJob Description\n\n- 依秒表法量測產線作業工時, 符合作業現況, 並作為合理排站及ECRS依據.\n- 修改&控管發行量產機種SOP與標準文件及產線作業一致, 作為OP作業動作依據.\n- 修改試產SOP,滿足機種試產需求.\n- 設置SFCS /Oracle Routing及異常處理., 滿足生產需求.\n- 製作機種第一次試產的SOP, 滿足機種試產需求.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ha Nam, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2161, 909, 2, 'L2 Software Support Engineer', 'We are Ataccama, and we are on a mission to power a better future with data. Our product enables both technical and less technical ‘data people’ across their organizations to create high-quality, governed, safe, and reusable data products. It’s what made us a Leader in the Gartner Magic Quadrant® for Data Quality Solutions™, and what inspired Bain Capital Tech Opportunities to invest in our future growth.\n\nOur vision is to be the leading AI-powered cloud data management company and to do that, we’re making Ataccama a great place to work and grow. Our people are located across the globe. They succeed by collaborating as a team and thrive in our company culture defined by these core values:\n\nChallenging Fun\nONE Team\nCustomer Centric\nCandid and Caring\nAim High\n\nDo you like figuring out the best solutions to customer’s challenges? Do you have a passion for technology and solving technically complex issues? Interested in the data management field? You will be the first point of contact for our clients and will work across our internal support and product teams to ensure their success with, and enjoyment of, our products. If you have logical problem solving abilities, a can-do, helpful attitude, and are a life-long learner, join us!\n\nAtaccama Support is an international team of talented and friendly people located in Toronto, Prague, Sofia and Hanoi, who thrive in a fast-paced environment and are always willing to go the extra mile. Ataccama Service and Support is rated 4.5 out of 5 on Gartner Peer Insights Reviews, and we’re proud of what we do. Join Ataccama, the Leader in the 2025 Gartner Magic Quadrant® for Augmented Data Quality Solutions™ for a 4th consecutive time.\n\nYour Challenge:\n- Assist Ataccama customers in solving technical issues.\n- Represent Ataccama through daily communications with customers via JIRA and Zoom to resolve Support Tickets.\n- Solve advanced analytic issues related to Ataccama products and their integration with supported third-party software.\n- Answer how-to questions, and suggest workarounds.\n- Continuously expand your knowledge of Ataccama products and related third-party software, including but not limited to database management systems, identity and access management providers, and web application servers.\n- Leverage the knowledge you gain and contribute to our documentation and knowledge base.\n- Analyze support requests and escalate product bugs to product management.\n- Work in close collaboration with a variety of teams within the company.\n- Manage your day and prioritize tasks on your own.\n\nIs This You?\n- You have 3+ years of experience in a customer-facing technical support role.\n- You demonstrate excellent interpersonal skills, with the ability to collaborate effectively with customers and internal teams.\n- You have knowledge in SQL and relational databases; Linux shell commands.\n- Your English is excellent, both written and spoken.\n- You have algorithmic thinking and a troubleshooting mindset.\n- You have a strong sense of ownership and organizational skills.\n- You can work under pressure and manage multiple tasks effectively.\n- Have you worked with Java applications before? If so, are you familiar with how Java shows errors when something goes wrong?\n- Have you seen or handled Java error messages or exceptions? Some examples of exceptions are NullPointerException, IOException, IllegalStateException.\n\nOur Tech Stack:\n- Any Backend: Java, Spring Boot, Kotlin, GraphQL, Python, jOOQ\n- Big data: Spark, Redshift, Snowflake\n- Frontend: TypeScript, React/Vue, Apollo, Nx, MobX, Styled Components\n- Storage: Postgres, Elastic, Minio\n- Infrastructure: GitLab CI/CD, Kubernetes, AWS, Azure\n\nYou Are Familiar With:\n- Java, GraphQL\n- Any APIs (SOAP / REST / JSON)\n- Spark, Redshift, Snowflake, Databricks\n- PostgreSQL, Elastic, MiniO\n- XML, XSLT\n- GitLab CI/CD, Kubernetes, AWS, Azure\n- General networking knowledge\n- Integration with SSO\n\nWork equipment:\n- Company laptop\n\nPerks & Benefits:\n- Full compensation during the probation period\n- 13th salary\n- 15 days of vacation\n- Premium Healthcare\n- Online company language courses\n- Conference tickets to the best industry events of the year\n- Online courses & company access to Udemy to hone your skills.\n- While we highly value cooperation with all our business partners, we don’t accept unsolicited resumes from any sources other than directly from a candidate. We reserve the right not to pay any fee for sending an unsolicited offer containing the details or resume of a job candidate, even if the relevant candidate is employed by our company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoi, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2162, 1051, 2, 'Backend DevOps Lead (AWS)', 'Our client (a fast-growing digital banking group) is seeking a highly skilled and motivated DevOps Lead with a strong background in software development, expertise in AWS Cloud, and a solid understanding of the banking domain. A crucial part of the role is championing and leading infrastructure as code. You will be responsible for implementing tools and processes that enable rapid software development and deployment.\n\nYour mission is to embrace continuous integration/deployment in a delivery pipeline that will perform automated quality checks, deploy cloud infrastructure quickly, and provide operational tooling and metrics that development teams can consume. To succeed, you will have a blend of development experience and operational experience that provides a good understanding of the developers you are working with while balancing critical systems uptime.\n\nYour responsibilities:\n\n- Collaborate with cross-functional teams to gather requirements and design scalable and maintainable software solutions\n- Build integration solutions for seamless communication between microservices, APIs, and third-party systems\n- Contribute to developing continuous delivery, automation frameworks, and pipelines to create an excellent experience for developers and customers\n- Optimize database interactions and ensure data integrity across distributed systems\n- Develop and enforce best practices for messaging, integration, and data pipeline architectures\n- Identify and develop opportunities to improve our processes and tools for automation\n- Learn new skills and help foster a continuous delivery and cloud-first mindset\n\nRequirements\n\n- 7+ years of experience in backend development using Python or Java, with 2+ years in a lead role\n- Proficient in Apache Kafka, including Kafka Connect, Schema Registry, etc\n- Expertise in building and deploying microservice and event-driven architecture, distributed systems, event sourcing, CQRS patterns, etc. \n- Experience using AWS foundation services (VPC, ECS, Lambda, RDS, SNS, SQS, Eventbridge, etc..)\n- Hands-on experience with tools like Kafka Connectors, Debezium, etc. \n- Solid experience with application integration patterns, RESTful APIs, and messaging protocols\n- Able to do hands-on, deep-dive details and work closely with team members to troubleshoot and optimize our platform\n- Able to design scalability systems as well as multi-country patterns for our platform\n- Knowledge of one or more AWS CloudFormation/Terraform/CDK for infrastructure provisioning\n- An automation mindset with the ability to develop tooling to improve the efficiency of repeatable tasks, reliability, and performance\n- Understanding cloud change management practices with an awareness of compliance and security standards\n- Good skills in English and the ability to communicate and coordinate effectively with business partners and technical teams\n- Demonstrate good logical thinking and problem-solving skills\n- Be curious and have a self-learning attitude\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ciudad Ho Chi Minh, Ciudad Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2163, 348, 2, 'Senior Software Engineer, TrueTest (JavaScript, NodeJS)', 'Founded in 2016, Katalon is the leading provider of a modern, comprehensive quality management platform. Katalon Platform enables quality assurance, DevOps, and software teams of any size to deliver world-class customer experiences faster, easier, and more efficiently.\n\nSince its first launch, Katalon has experienced tremendous growth, serving more than 30,000 teams around the globe, many of which are in the Fortune Global 500, such as PwC, KPMG, Abbott, etc. Katalon is recognized as a top automation tool by prestigious review sites, such as G2, Gartner, Capterra, and IT Central Station.\n\nAbout Position\n\nKatalon TrueTest is an AI-augmented test automation solution that automatically discovers, models, generates, and maintains user-journey test cases. TrueTest provides a streamlined test generation process, saving time and improving testing efficiency. As a Senior Software Engineer, you will play a critical role in developing and enhancing our flagship test automation tool, following the responsibilities of:\n\n- Collaborate with the product manager and team to develop and enhance the product\'s new features in addition to utilizing Generative AI technology\n- Perform detailed technical analysis and design to break down the feature based on the high-level design and business requirements\n- Develop and review code that meets the development standards for code style, design patterns, readability, and maintainability and integrates best practices for scaling\n- Work with peer engineers to grow the technical accountability of the system to ensure release product quality, security, and performance\n- Utilize Code Pilot to increase development efficiency and quality by automating repetitive tasks and identifying potential bugs or issues early on\n- Identify areas for improvement within the existing codebase and suggest solutions to improve.\n- Identify and contribute to internal engineering working groups to define and build internal libraries, tools, and frameworks for reusability and centralize practices across\n- Diagnose and troubleshoot issues to support customer requests.\n- Support automation QAs and product specialists to maintain the demo system and write scripts using new Katalon features, to test applications\n\nRequirements\n\n- Expertise in JavaScript (ES6+) and Node.js\n- Hands-on experience with automation tools or recorders (such as Playwright, Selenium, or similar), especially in recording user flows, generating scripts, and working with CSS/XPath locators\n- Experience implementing agent or user tracking/analytics systems (e.g., similar to Google Analytics), including event collection, processing, and reporting\n- Strong skills in modular code structure, including experience organizing large projects for scalability and maintainability\n- Ability to configure and optimize build tools, especially Vite, including advanced configuration, plugin integration, and performance tuning\n- Working knowledge of automated testing frameworks (e.g., Playwright, Jest, Mocha), and writing reliable, maintainable test scripts\n- Understanding of CSS selectors, locators, and DOM structure, with the ability to troubleshoot and optimize selectors for automation or analytics\n- Commitment to engineering best practices: automated testing, code reviews, version control, and continuous integration\n- Strong problem-solving and communication skills, with a focus on collaboration and mentoring\n- Ability to work effectively in cross-functional teams in a fast-paced environment\n\nBenefits\n\nAt Katalon, we bring together self-starting, open-minded, and talented people while actively promoting a transparent and growth-enabling working environment. But don\'t just take our word for it. Take a better look below!\n\n- Competitive Pay & Bonuses: We believe in rewarding great work! You\'ll receive an attractive salary package plus performance bonuses to help you meet your financial goals\n- Your Health & Happiness Matter: Take care of yourself with our comprehensive health coverage, flexible work options, and generous time off. We understand that life happens outside of work too!\n- Location-Tailored Benefits: Enjoy a complete benefits package designed specifically for your country, giving you the best coverage where you live\n- Everything You Need to Succeed: Work with top-of-the-line equipment and enjoy modern facilities, plus helpful allowances to support your work setup\n- A Place Where You Belong: Join our worldwide family where we celebrate what makes each of us unique. Here, everyone has a voice and equal opportunities to shine\n- Room to Grow & Thrive: Your success is our success! We foster a trust-based culture where you can develop your skills, take on new challenges, and be recognized for your achievements\n\nKatalon is proud to be an equal-opportunity employer. We care about our people and celebrate our differences. We want to work with talented, collaborative, and innovative people. We do not discriminate in hiring or any employment decision based on race, color, religion, national origin, age, sex (including pregnancy, childbirth, or related medical conditions), marital status, ancestry, physical or mental disability, genetic information, veteran status, gender identity or expression, sexual orientation, or other characteristics protected by law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2164, 702, 2, 'Senior Backend Engineer (Java)', 'Binance is a leading global blockchain ecosystem behind the world’s largest cryptocurrency exchange by trading volume and registered users. We are trusted by over 250 million people in 100+ countries for our industry-leading security, user fund transparency, trading engine speed, deep liquidity, and an unmatched portfolio of digital-asset products. Binance offerings range from trading and finance to education, research, payments, institutional services, Web3 features, and more. We leverage the power of digital assets and blockchain to build an inclusive financial ecosystem to advance the freedom of money and improve financial access for people around the world.\n\nResponsibilities\n\n- Design and develop microservices architecture using Java Spring Boot, ensuring system performance, scalability, and reliability.\n- Implement and manage microservices components such as service discovery, configuration management, and load balancing with Spring Cloud.\n- Analyze, process, and explore data using big data technologies.\n- Optimize and manage data storage and retrieval systems, ensuring efficient data handling.\n- Build large scale software systems, which can impact daily life of millions of customers.\n- Upgrade underlying Infra/arch.\n- Performance tuning, online incidents troubleshooting, and system refactoring.\n- Write high-quality, clean, and maintainable code using engineering best practices.\n\nRequirements\n\n- At least 7 years experience in Java development, proficient in Netty and WebSocket framework.\n- Experience in mainstream database storage engines, index principles and partition and table schemes, with performance tuning practical cases.\n- Enthusiastic about technology, with stringent requirements for code quality and development standards.\n- Proficient in English & Chinese for efficient communication with international stakeholders.\n\nNice to Have\n\n- Bonus: Proficient in AI applications.\n- Bonus: Familiar with database index structure principles.\n- Bonus: Familiar with Rust/Golang and other languages, with cross-language development ability.\n- Bonus: Experience in multi-million level message push project in finance/e-commerce.\n\nWhy Binance\n\n- Shape the future with the world’s leading blockchain ecosystem.\n- Collaborate with world-class talent in a user-centric global organization with a flat structure.\n- Tackle unique, fast-paced projects with autonomy in an innovative environment.\n- Thrive in a results-driven workplace with opportunities for career growth and continuous learning.\n- Competitive salary and company benefits.\n- Work-from-home arrangement (the arrangement may vary depending on the work nature of the business team).\n\nBinance is committed to being an equal opportunity employer. We believe that having a diverse workforce is fundamental to our success.\n\nBy submitting a job application, you confirm that you have read and agree to our Candidate Privacy Notice.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2165, 1106, 2, 'Senior Java Software Engineer', '■The Job Duties\nYou will work as a Lead Java Developer to join our projects for Japanese clients/other countries.\n• Read and understand technical specification and conduct the implementation\n• Clarify requirements from clients\n• Perform unit testing to ensure the system run correctly with design documents\n• Investigate the issue and give the optimized solution\n• Review source code and design documents\n• Workflow improvement and execution\n• Willing to work as Team Leader and conduct training members\n\n■Required Skills and Experience:\nKey Qualifications:\n• Have 4+ years working as Java Developer (web)\n• Have experience in Team Leader or mentor members\n• Proficient in Java (Springboot), Linux, Tomcat, Apache HTTP Server\n• Experience in HTML, CSS, JavaScript\n• Have a good skill of problem-solving\n• Have experience work in Agile/Scrum process\n• Strong skills in team leadership and client relationship (plus point)\n\nBonus Points:\n• Experience and can be working with several projects\n• Move forward without being afraid of challenges.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2166, 1107, 2, 'Engineer/Senior Engineer, Frontend - Blockchain Applications', 'Hex Trust is a fully-licensed and insured digital asset custodian. Led by veteran banking technologists and award-winning financial services experts, Hex Trust has built Hex Safe, a proprietary bank-grade platform that delivers solutions for digital asset protocols, foundations, financial institutions, and the Web3 ecosystem. Hex Trust has offices in Singapore, Hong Kong, Dubai, Italy, and Vietnam.\n\nPosition Summary\n\nWe are seeking suitable candidates for Senior Front-End Developer roles responsible for the development of Web-based front ends for Blockchain and Digital Asset related applications such as Wallets, DApps and Crypto Currency Trading applications. You will be working closely with our UX designers, Product Managers and the Front and Backend development teams. This role offers an opportunity to learn DApps development and progression to Front End Team Lead role.\n\nDuties & Responsibilities\n\n- Development of web based front end applications for Blockchain, Digital Assets, and DApps;\n- Working closely with UX Designer to ensure optimal implementation of User Interfaces;\n- Mentor and lead other Front End developers;\n\nRequirements\n\n- 5+ years\' experience in Web front-end development for complex applications;\n- Technologies: React JS, Vite, JavaScript, CSS, HTML and TypeScript knowledge and experience;\n- Familiar with state management frameworks, e.g. Redux, Zustand;\n- Node JS backend experience;\n- Ability to work collaboratively with team members;\n- Attention to detail, with the ability to work independently in an ambiguous and often fast-paced environment;\n- Good planning, coordination and communication skills;\n- Interest in blockchain, cryptocurrencies, trading and security.\n\nCandidates who do not tick all the boxes are still encouraged to apply, those with less experience will still be considered for the position but with an adjustment to the level of seniority.\n\nBenefits\n\nAs one of the leading Web3 innovators, Hex Trust offers a front-row seat in the ever-changing blockchain & crypto industry. We genuinely believe that people are our greatest asset, and invest heavily so they\'re best prepared to support our mission to unlock ownership in decentralized markets! You will be joining a company that is always committed to creating a supportive & inclusive environment that promotes personal and professional growth that furthers your success and drives innovation, collaboration, and passion in the blockchain space.\n\nAt Hex Trust, we are proud of our H.E.X. culture:\n\n- Heart\n- Empowerment\n- Xcellence\n\nJoin us at Hex Trust and not only can you look forward to working with blockchain professionals to build the decentralized future, but also:\n\n- Competitive Salaries & Bonuses\n- Generous Amounts of Paid Time Off (incl. leave for Birthdays, Work Anniversary, and Mental Health etc.)\n- Access to Corporate Discounts and exclusive Employer Perks\n- Medical & Retirement Plans\n- Professional Learning and Development Opportunities\n- Elevate your work using cutting-edge technology\n- Fun & friendly office spaces in Hong Kong, Singapore, Dubai and Vietnam\n- Regular company & social events', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh City, Ho Chi Minh City, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2167, 882, 2, 'Senior AI Engineer', 'Responsibilities\nDesign and develop conversational AI agents using OpenAI GPT models and RAG frameworks\nImplement single and multi-agent collaboration models with clear task decomposition and orchestration\nIntegrate external knowledge bases, APIs, and enterprise systems into chatbot workflows\nDevelop and manage Deep Search pipelines for improved information retrieval\nCreate and maintain Text-to-SQL and MCP connectors to translate natural language to database or service queries\nBuild scalable backend services to support real-time chatbot interaction\nCollaborate with UX/UI designers, product owners, and QA teams to deliver end-to-end solutions\nContinuously evaluate new AI tools, frameworks, and best practices to improve our chatbot capabilities\n\nRequirements\n3-5 years of experience as a software engineer, understanding of software project life cycle\nProficiency with Python (preferred) or Node.js, including API development\n2 years of experience building AI chatbots or agent-based applications (must have live or portfolio projects)\nStrong experience with OpenAI API, LangChain, LlamaIndex, or similar LLM frameworks\nExperience implementing RAG (Retrieval-Augmented Generation) pipelines\nHands-on knowledge of Agent / Multi-Agent frameworks (LangGraph, CrewAI, AutoGen, etc.)\nExperience integrating with external systems via Text-to-SQL, REST APIs, or custom protocols (MCP)\nKnowledge of Vector DBs (e.g., Pinecone, Weaviate, FAISS, ChromaDB)\nUnderstanding of prompt engineering and context window optimization\nFamiliarity with MLOps or LLMOps is a plus\nExcellent problem-solving, debugging, and collaboration skills\n\nPreferred Qualifications\nExperience working in Agile/Scrum environments\nFamiliarity with cloud platforms (Azure, AWS, GCP)\nExposure to CI/CD pipelines for AI deployment\nDemonstrated ability to work independently and drive projects forward\n\nBenefits\nSalary: Negotiation\nJoin a global team and work directly with many talents around the world.\nOpportunities for onsite work in Japan, Singapore, Australia, and many other countries.\nWork and grow in a dynamic, creative, and professional environment.\nHealthcare: Premium Health Insurance TECHVIFY Care\n13 months’ salary per year.\nAnnual salary evaluation.\nSponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.\n\nLocation:\nHa Noi: HUDTOWER Building, 37 Le Van Luong Str, Thanh Xuan Dist, Hanoi, Vietnam\nDa Nang: Ricco Building, 363 Nguyen Huu Tho Str, Cam Le Dist, Da Nang City, Vietnam​', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Da Nang, Da Nang, Vietnam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2168, 743, 2, '[LTS] PHP – WordPress Developer', 'General Information\n\nPosition: PHP – WordPress Developer\nWorking place: Hanoi\nSalary: Negotiation\n\nDescription\nCollaborate with cross-functional teams to define, design, and ship new features\nWork on bug fixing and improving application performance\nContinuously discover, evaluate, and implement new technologies to maximize development efficiency\n\nRequirements\nStrong experience with WordPress, particularly with multisite and custom plugin development.\nFamiliarity with headless WordPress architecture and GraphQL.\nFamiliarity with Gatsby and Apollo clients for building front-end applications.\nStrong understanding of PHP and experience with modern PHP development practices.\nExperience with database management and optimization. Especially wp multisite vs single sites.\nStrong debugging skills and the ability to troubleshoot issues across different layers of the stack.\nStrong problem-solving skills and the ability to work independently\nAbility to refactor and organize existing codebase, implement best practices, and remove duplicate code\nNice to have English\n\n#PHP\nStrong understanding of modern PHP development practices and coding patterns.\nExperience using Composer dependency management.\nStrong ability to write clean, readable, type-safe, and maintainable code.\nStrong ability to understand, debug, and refactor existing code.\n\n#WordPress\nStrong understanding of WordPress development practices and coding patterns.\nStrong understanding of the WordPress lifecycle and hooks.\nExperience working on WordPress plugins.\nExperience working with WordPress REST API or WPGraphQL.\n\nBenefits\nAttractive salary. Performance-based award. Range up to 1k5$\nYoung and dynamic working environment.\nContinuous development of hard and soft skills through work and professional training.\nOpportunity to approach the newest technology trends\nSalary review 2 times/year or on an excellent performance\nCompany’s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Holiday, etc\n\nCONTACT\nLTS Recruitment Department\nPhone Number: 02466607474\nEmail: rec@ltsgroup.tech', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hanoï, Hanoï, Viêt Nam', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2169, 1108, 2, 'Fullstack Developer (App, Web, AI)', '[Tuyển dụng lập trình viên IT cho thị trường Việt Nam]\nORBRO, một công ty startup IT đang trên đà phát triển nhanh chóng, đang tuyển dụng lập trình viên App, Web, Server và AI! \nChúng tôi là một đội ngũ luôn sẵn sàng đối mặt với thử thách, phá vỡ các khuôn mẫu truyền thống để phát triển công nghệ tiên tiến và mở ra những thị trường mới. Hiện tại, chúng tôi đang tuyển dụng 10 thành viên đầu tiên để gia nhập đội ngũ tại Việt Nam, nhằm mở rộng và vươn ra thị trường toàn cầu. Chúng tôi mong muốn tìm kiếm những tài năng nhiệt huyết, sẵn sàng cùng nghiên cứu và quảng bá để khai phá tương lai.\nORBRO là một công ty IT ứng dụng các công nghệ tiên tiến như thuật toán đa dạng, công nghệ camera AI, dựa trên nền tảng công nghệ theo dõi vị trí. Chúng tôi tự hào sở hữu: \n• Văn hóa tổ chức linh hoạt và cấu trúc ra quyết định nhanh chóng.\n• Môi trường khuyến khích mỗi cá nhân tự chủ trong nghiên cứu và phát triển.\n• Văn hóa không sợ thất bại, đề cao sự học hỏi liên tục và tinh thần thử thách.\nNếu bạn là người muốn hiện thực hóa ý tưởng của mình trong một môi trường tự do, hãy đồng hành cùng chúng tôi!\n\nChúng tôi đang tìm kiếm những ứng viên như sau:\n• Người thích giải quyết vấn đề và không ngại thử thách mới.\n• Người có thể thích nghi và phát triển trong môi trường thay đổi nhanh chóng.\n• Người không chỉ thực hiện công việc một cách đơn thuần mà còn tích cực đề xuất và thực hiện các ý tưởng mới.\n\nNhiệm vụ chính cho từng vị trí như sau:\nLập trình ứng dụng:\n• Phát triển và bảo trì ứng dụng Flutter (Android, iOS).\n• Tối ưu hóa UI/UX và cải thiện trải nghiệm người dùng.\n• Cải thiện và tối ưu hóa hiệu suất, tích hợp module native.\n• Xử lý dữ liệu và tích hợp mạng.\n\nLập trình web:\n• Phát triển và bảo trì website và dịch vụ dựa trên React/TypeScript.\n• Tối ưu hóa công cụ tìm kiếm (SEO) và tối ưu hóa hiệu suất.\n• Phát triển frontend.\n\nLập trình AI:\n• Phát triển hệ thống nhận diện và theo dõi đối tượng dựa trên AI.\n• Nghiên cứu và tối ưu hóa mô hình thị giác máy tính và máy học.\n• Huấn luyện và cải thiện hiệu suất mô hình học sâu (sử dụng TensorFlow, PyTorch, v.v.).\n• Phát triển công nghệ phân tích và xử lý hình ảnh thời gian thực.\n• Nghiên cứu và phát triển thuật toán hậu xử lý (bộ lọc Kalman).\n\nYêu cầu ứng viên\n• Người có đam mê học hỏi công nghệ mới.\n• Người có khả năng hợp tác và giao tiếp xuất sắc.\n• Có bằng cử nhân trở lên trong lĩnh vực liên quan hoặc kinh nghiệm tương đương.\n• Có ít nhất 2 năm kinh nghiệm thực tế trong lĩnh vực liên quan (ứng viên mới tốt nghiệp vẫn có thể ứng tuyển).\n• Ưu tiên người sử dụng tiếng Anh hoặc tiếng Hàn.\n\nQuyền lợi\n• Lương: Thỏa thuận.\n• Tham gia các hoạt động Team Building.\n• Hỗ trợ thiết bị laptop khi cần thiết.\n• Môi trường làm việc trẻ trung năng động, chuyên nghiệp, kích thích sự sáng tạo.\n• Các chế độ khác theo đúng quy định pháp luật.\n\nĐịa điểm làm việc\n- Hà Nội: Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2170, 1109, 2, 'Trưởng Bộ Phận ERP', '-Nghiên cứu, thiết kế và phát triển hệ thống ERP cho công ty\n-Kết nối các bộ phận để phát triển và ứng dụng phần mềm vào thực tế\n-Lập kế hoạch phát triển phần mềm quản trị doanh nghiệp theo yêu cầu\n-Phân tích đánh giá tính hiệu quả của hệ thống\n-Báo cáo tiến độ và tình trạng công việc cho người quản lý trực tiếp.\n-Quản lý đội ngũ nhân viên bộ phận\n-Hỗ trợ, bảo trì hệ thống trong quá trình vận hành.\n\n-Yêu cầu ứng viên\n-Tốt nghiệp đại học chuyên ngành CNTT hoặc tương đương\n-Kiến thức về quy trình phát triển, vận hành phần mềm.\n-Quản lý yêu cầu người dùng, đào tạo và hướng dẫn\n-Giao tiếp, trình bày, tâm huyết, chuyên nghiệp\n-Kinh nghiệm làm các dự án ERP tối thiểu 3 năm, vị trí quản lý 2 năm\n\n-Quyền lợi\n-Lương: Thỏa thuận (22 đến 30 triệu) \n-Có thưởng theo từng dự án khi hoàn thành mỗi giai đoạn.\n-Có thưởng dài hạn theo lợi nhuận phát sinh của mỗi sản phẩm mà cá nhân có tham gia theo tỷ lệ tương ứng với đóng góp.\n-Xét điều chỉnh lương 02 lần/năm.\n-Các chế độ bảo hiểm xã hội và bảo hiểm y tế theo Luật Lao Động.\n-Được ăn trưa miễn phí, được tham gia hoạt động tập thể do Công Đoàn tổ chức.\n-Chế độ phúc lợi (Nghỉ mát, sinh nhật, cưới hỏi).\n\n-Địa điểm làm việc\n- Hà Nội: Lô 14 nguyễn Cảnh Dị, Hoàng Mai, Hoàng Mai\n\n-Thời gian làm việc\n-Thứ 2 - Thứ 6 (từ 08:00 đến 17:45)\n\n-Cách thức ứng tuyển\n-Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2171, 1110, 2, 'Kỹ Sư Phát Triển Phần Mềm (Làm Việc Tại Nhật) - Không Yêu Cầu Kinh Nghiệm', 'Mô tả công việc:\n- Tham gia phát triển, thiết kế, lập trình các tính năng mới theo yêu cầu của dự án.\n- Nghiên cứu, áp dụng các công nghệ mới để nâng cao hiệu suất và chất lượng phần mềm.\n- Phối hợp với các bộ phận khác để đảm bảo tính chính xác và hoàn thiện của sản phẩm.\n- Thực hiện các công việc khác khi được giao.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học các chuyên ngành liên quan đến Công nghệ thông tin, Khoa học máy tính, Kỹ thuật phần mềm hoặc các ngành liên quan,…\n- Chấp nhận chưa có kinh nghiệm thực tế (được đào tạo trong quá trình làm việc).\n- Có định hướng phát triển lâu dài với công việc.\n- Chăm chỉ, cẩn thận, làm việc trên tinh thần trách nhiệm cao.\n- Người ham học hỏi, đam mê công việc.\n\nQuyền lợi:\n- Thời gian làm việc: 8:00 - 17:00.\n- Nghỉ thứ 7, chủ nhật và nghỉ theo lịch công ty.\n- Tổng số ngày nghỉ 121 ngày/năm.\n- Trợ cấp toàn bộ chi phí đi lại, trợ cấp nhà ở lên đến 20000 yên, trợ cấp chuyên cần, trợ cấp chức vụ, ngoài giờ,...\n- Đầy đủ các chế độ bảo hiểm, tăng lương, thưởng dự án,...\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 24 Ấp Bắc, Phường 13, Tân Bình.\n- Nước Ngoài.\n- Đà Nẵng: 220 Nguyễn Tri Phương, Thạc Gián, Thanh Khê.\n- Hà Nội: 128A Hồ Tùng Mậu, Phường Mai Dịch, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Tân Bình, Nước Ngoài, Đà Nẵng, Thanh Khê, Hà Nội, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2172, 209, 2, 'RTOS Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\nRESPONSIBILITIES\nAs a Smart Meter Software Development Engineer, you will work on critical projects in developing software for smart meter systems using FreeRTOS. You will play an instrumental role in two primary projects:\n• AT Command Development: Designing, implementing, and testing AT command capabilities to support smart meter functionalities and communication interfaces.\n• DLMS Protocol Implementation: Developing and optimizing software modules for DLMS (Device Language Message Specification) protocol to ensure secure and efficient data exchange in smart meter systems.\nAdditional responsibilities include:\n•    Integrating and optimizing FreeRTOS for smart meter applications, focusing on real-time performance and resource efficiency.\n•    Troubleshooting, debugging, and maintaining high-performance, scalable code for smart meters.\n•    Collaborating with cross-functional teams to align software functionalities with hardware capabilities and project requirements.\n•    Documenting software architecture and processes to support smooth project management and ensure high standards.\nYêu cầu ứng viên\n•    Operating System: Strong expertise in FreeRTOS for real-time, embedded applications.\n•    Platform: STM32\n•    AT Command Parser: Experience in developing and parsing AT commands.\n•    DLMS Protocol: Solid understanding and experience with the DLMS protocol for secure data exchange in smart metering.\nLanguages\n•    C/C++\nQuyền lợi\n•    Salary range: $2000 - $3500 \n•    FPT Care insurance plan tailored for FPT employees\n•    Attractive annual summer vacation allowance\n•    Sponsored training courses for personal growth and up to 100% coverage for certification costs\n•    Global and inclusive workplace with monthly cross-cultural events\n•    International exposure and career growth across global locations\n•    Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\nĐịa điểm làm việc\n- Hà Nội: FPT Building, 17 Duy Tân Str., Cầu Giấy District, Hanoi, Cầu Giấy\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2173, 165, 2, 'Frontend Developer (HTML/CSS/JS)', 'About KiotViet:\nKiotViet aims to extend the significant power of technology to every business model in Vietnam and Southeast Asia through our simple and effective solutions. We are committed to creating efficient, convenient products for micro, small, and medium-sized businesses. Over the past 13 years, with a current team of over 1500 people at KiotViet, we recognize that our members are the foundation of KiotViet and a launchpad for achieving a better KiotViet in the future. KiotViet is dedicated to creating a work environment that fosters shared success and responsibilities.\nKiotviet is Vietnam’s largest POS provider, with over 200,000 merchants across various industries. We are expanding into other South-east Asian countries with our POS offerings and are expanding our product portfolio with new offerings in the fintech space.\nWhat you will do:\n- Convert designs from Figma/PSD to HTML/CSS\n- Maintain and develop UI components\n- Ensure responsive design across all devices\n- Collaborate with team to deliver quality products\n\nEXPERIENCE REQUIREMENTS:\n- Bachelor\'s degree in Computer Science/IT/Design or equivalent\n- 4+ years of Frontend Development experience\nREQUIRED SKILLS:\n- Proficient in HTML5, CSS3, JavaScript\n- Experience with SASS/SCSS\n- Knowledge of Bootstrap or Tailwind CSS\n- Ability to convert responsive designs from Figma/PSD\n- Basic understanding of Angular & TypeScript\n- Proficient with Git version control\nPREFERRED:\n- Experience with AI coding tools (Cursor, GitHub Copilot, Claude...)\n- Web performance optimization knowledge\n- Understanding of web accessibility standards\nSOFT SKILLS:\n- Attention to detail in UI implementation\n- Strong communication with design & development teams\n- Self-motivated and continuous learner\n- Ability to work independently\n\nQuyền lợi:\n- Top salary range in the market (willing to negotiate)\n- Compensation, pay a 13th month salary depending on employee’s performance;\n- Performance bonus (up to 2-month salary)\n- Social – Health – Insurance paid fully. Healthcare: Annual health check-up, Premium Health Insurance ( from level senior according to the company\'s regulations)\n- Advantageous and yield benefits, other benefits such as holiday vacations, benefits for employee’s relatives;\n- Unlimited chance of being promoted based on employee’s performance.\n\nĐịa điểm làm việc:\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2 đến thứ 6. Làm việc 8 tiếng/ngày và checkin linh hoạt trong khung từ 08h - 09h\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2174, 1111, 2, 'Web Developer (Pass Phỏng Vấn, Đi Làm Luôn)', 'Mô tả công việc\n- Xây dựng, thiết kế Website trên nền tảng mã nguồn WordPress.\n- Sử dụng công cụ Elementor để  thiết kế và chỉnh sửa giao diện web.\n- Phối hợp và hỗ trợ bộ phận Design của Công ty để tối ưu giao diện Website.\n- Quản lý và bảo trì website.\n- Các công việc chuyên môn khác theo yêu cầu của Trưởng bộ phận.\n\nYêu cầu ứng viên\n- Tốt nghiệp các ngành Thiết kế, Công nghệ thông tin hoặc đã có ít nhất 1 năm kinh nghiệm thiết kế Website Wordpress.\n- Biết sử dụng Figma để thiết kế giao diện.\n- Am hiểu về các tiêu chuẩn thiết kế giao diện và trải nghiệm người dùng.\n- Hiểu biết tối ưu hóa website với công cụ tìm kiếm.\n- Nhạy bén trong việc cập nhật các xu hướng công nghệ mới.\n- Ưu tiên ứng viên có kiến thức về HTML/CSS.\n- Có sản phẩm đính kèm CV.\n\nQuyền lợi\n- Lương CB: 10 – 15tr + Thưởng. (Có thể cao hơn tùy năng lực)\n- Được đề xuất review ngay khi đạt hiệu quả tốt trong công việc.\n- Không giới hạn cơ hội phát triển và thăng tiến lên các vị trí cấp cao.\n- Được đào tạo nâng cao năng lực chuyên môn.\n- Môi trường năng động, không bị gò bó bởi luật lệ, trang phục tùy sở thích.\n- Khu vực Pantry trang bị sẵn đồ uống, đồ ăn nhẹ.\n- 12 ngày nghỉ phép có lương trong năm.\n- Các chế độ theo Luật lao động hiện hành: Bảo hiểm xã hội,… và các phúc lợi: 20/10, sinh nhật, lễ tết,…. theo quy định của công ty.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 3, Lô (5+6+7+23+24+25) Ô C2-NO, tòa nhà văn phòng KĐT Nam Trung Yên, Đường Mạc Thái Tông, Phường Trung Hòa, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)\n- Từ tháng 5 - tháng 10: làm việc từ thứ 2 - thứ 7\n- Từ tháng 11 - tháng 4 năm sau: làm việc từ thứ 2 - thứ 6\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2175, 1112, 2, 'Lập Trình Viên Wordpress', 'Mô tả công việc\n- Chuyển đổi thiết kế sang website WordPress hoàn chỉnh (HTML, PHP, ACF, Elementor/Divi/Astra/Gurtenberg,…).\n- Tích hợp các plugin và API của bên thứ ba.\n- Sửa lỗi, nâng cấp và bảo trì website định kỳ.\n- Tối ưu hóa hiệu suất và bảo mật WordPress.\n- Các công việc khác liên quan đến website WordPress.\n\nYêu cầu ứng viên\n- Có kinh nghiệm HTML, CSS, JS.\n- Tối thiểu 1 năm kinh nghiệm làm việc thực tế với Wordpress (ACF , Divi, Elementor,...).\n- Đọc hiểu tài liệu tiếng anh và có khả năng làm việc trực tiếp với người nước ngoài.\n- Biết Angular và React JS là lợi thế lớn.\n- Biết xây dựng mobile apps là lợi thế.\n\nQuyền lợi\n- Chế độ đãi ngộ tốt.\n- Được cấp máy tính bàn để làm việc.\n- Thưởng lễ , Tết theo kết quả hoạt động công ty.\n- Chế độ BHXH theo quy định.\n\nĐịa điểm làm việc\n- Nghệ An: Trường Thi, TP Vinh.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nghệ An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2176, 1113, 2, 'IT Manager', 'Mô tả công việc:\n- Develop, maintain, and optimize internal software systems to support operations at AEON Fantasy entertainment centers.\n- Participate in requirements analysis, system design, coding, and testing of software applications.\n- Support the rollout of new software at branches and ensure stable system performance.\n- Work closely with various departments (Operations, Sales, HR, etc.) to gather requirements and provide technical support.\n- Ensure security, performance, and scalability of software systems.\n- Install POS systems, game card readers; troubleshoot errors or coordinate with Speed, Semnox, or IM Link to resolve software and hardware issues; set up product pricing, game machine pricing, promotion programs, etc.\n- Review, negotiate, and sign annual maintenance contracts for systems.\n- Perform other IT-related tasks as assigned by the Board of Directors.\n\nYêu cầu ứng viên:\n- Bachelor\'s degree in Information Technology or a related field.\n- 5–7 years of experience in software development (candidates with experience in internal systems or retail systems are preferred).\n- Proficient in at least one of the following programming languages: Java, C#, PHP, Python, or JavaScript.\n- Experience working with databases such as MySQL, SQL Server, or equivalent.\n- Preferably experienced in developing software on web platforms (ReactJS, VueJS, etc.) or mobile platforms (Android/iOS).\n- Knowledge of MVC architecture, RESTful APIs, Git, and Agile/Scrum methodology is an advantage.\n- Strong teamwork and communication skills.\n- Proactive, responsible, detail-oriented, and eager to learn.\n\nQuyền lợi:\n- Working from Monday to Friday.\n- Contribute social insurance at 100%. \n- A dynamic, youthful, and international working environment.\n- Opportunities for career advancement.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 36 Bùi Thị Xuân, Quận 1.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2177, 1114, 2, 'ReactJS Technical Leader', 'Mô tả công việc:\n- Quản lý Team FE, hướng dẫn và hỗ trợ chuyên môn cho các thành viên trong nhóm.\n- Định hướng, phân tích và thiết kế kiến trúc hệ thống, đảm bảo hệ thống bền vững, an toàn thông tin, hiệu suất cao, dễ bảo trì, nâng cấp và mở rộng.\n- Tham gia phát triển các hệ thống sản phẩm, dịch vụ của công ty: Phát triển các Module của sản phẩm/dịch vụ; Phối hợp với BA, Tester fix bug, update module; Merge code.\n- Thống nhất các mục tiêu, sản phẩm cũng như đưa ra phương án kỹ thuật của dự án.\n- Xử lý các vấn đề kỹ thuật phát sinh trong quá trình phát triển.\n\nYêu cầu ứng viên:\n- Tốt nghiệp ĐH trở lên chuyên ngành Công nghệ thông tin; Kỹ thuật phần mềm, Hệ thống thông tin, ...hoặc các ngành tương đương.\n- Trên 5 năm kinh nghiệm phát triển React JS, trong đó ít nhất 1 năm đảm nhận vai trò Technical Leader.\n- Có kinh nghiệm phát triển web sử dụng các framework React JS.\n- Từng tham gia các hệ thống về Tài chính/Chứng khoán/Ngân hàng,…\n\nChuyên môn kỹ thuật:\n- Thành thạo React JS, JavaScript/TypeScript, HTML5, CSS3 và hệ sinh thái (hoặc các library/framework có concept tương tự: React Native, Vue, Ember,...).\n- Có kinh nghiệm với các công cụ frontend như Webpack, Babel, ESLint và các framework kiểm thử (Jest, React Testing Library).\n- Kinh nghiệm với CI/CD, Git và các nền tảng đám mây (AWS, Azure) là một điểm cộng.\n\nKỹ năng quản lý và giao tiếp:\n- Có khả năng quản lý và hướng dẫn các nhóm kỹ thuật, tạo dựng môi trường làm việc hợp tác và hiệu quả.\n\nKỹ năng mềm:\n- Kỹ năng giải quyết vấn đề tốt và chủ động trong việc nhận diện và khắc phục các thách thức kỹ thuật.\n- Nhận thức văn hóa và khả năng thích nghi để làm việc hiệu quả với các bên liên quan.\n- Kỹ năng tổ chức tốt, chú ý đến chi tiết và quản lý thời gian hiệu quả.\n\nQuyền lợi:\n- Lương: upto 32M\n- Được hưởng chế độ ưu đãi về lương, thưởng theo năng lực, hiệu quả công việc, kết quả sản xuất kinh doanh chung công ty.\n- Tháng lương thứ 13 tùy theo thời gian làm việc tương ứng.\n- Tham gia đầy đủ các chế độ bảo hiểm (BHXH, BHYT, BHTN...)\n- Thưởng theo dự án, thưởng CBNV xuất sắc, ngoài ra còn có các khoản trợ cấp hàng tháng như sau :\n  + Trợ cấp đi lại\n  + Trợ cấp ăn trưa\n  + Du lịch hằng năm trong, ngoài nước\n- Thời gian làm việc: từ thứ 2 đến thứ 6 và 2 sáng thứ 7 trong tháng.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 14, Center Building Hapulico Số 85 Vũ Trọng Phụng, Thanh Xuân, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:15 đến 17:30)\n- 2 Sáng thứ 7/tháng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2178, 1115, 2, 'Backend Developer (Golang)', 'Mô tả công việc\n- Build high-performance, scalable backend components using Golang.\n- Design, implement, and optimize database solutions with PostgreSQL, ensuring data integrity and high performance.\n- Develop and maintain GraphQL APIs to support data-driven applications.\n- Deploy and manage containerized applications using Kubernetes, ensuring stability and high availability.\n- Set up and maintain CI/CD pipelines to automate testing, deployment, and integration processes.\n- Collaborate with cross-functional teams to define, design, and develop new features.\n- Participate in code reviews to maintain code quality and share knowledge within the team.\n\nYêu cầu ứng viên\n- Require 2-3 years of experience in Golang\n- Strong proficiency in Golang with experience in building scalable server-side applications.\n- Proficiency in PostgreSQL, including writing complex queries, optimizing performance, and database design.\n- Hands-on experience with Kubernetes for deploying and managing containerized applications.\n- Experience developing and maintaining GraphQL APIs.\n- Familiarity with CI/CD tools and practices.\n- Familiarity with version control systems such as Git.\n- Understanding of microservices architecture and RESTful API design.\n- Experience with cloud platforms like AWS, Google Cloud, or Azure is a plus.\n- Excellent problem-solving skills and a proactive attitude.\n- Strong communication skills and the ability to work effectively in a collaborative environment.\n\nQuyền lợi\n- Competitive salary upto 25,000,000 VND. 100% salary during probation\n- Reference bonus, End year bonus,...\n- Daily lunch support\n- Friendly and open working environment\n- IELTS/ TOEIC Certificate Support.\n- Team-building activities: 1-2 company trips/year\n- Career development opportunities\n- Tea-break\n\nĐịa điểm làm việc\n- Hà Nội: Số 9 Duy Tân, Dịch Vọng Hậu, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2179, 1116, 2, 'Kỹ Sư PLC_Không Yêu Cầu Kinh Nghiệm', 'Mô tả công việc\n- Mô phỏng, lập trình, chạy thử hệ thống tự động hóa tích hợp PLC siemens, robot công nghiệp ABB và các thiết bị tiên tiến tại nhà máy sản suất ô tô Vinfast.\n- Phụ trách kỹ thuật chính cho các vấn đề điện điều khiển & PLC trong dây chuyền sản xuất hàng ngày\n- Điều tra lỗi, phân tích nguyên nhân gốc rễ và hành động khắc phục cho phần điện điều khiển và PLC\n- Trình bày các vấn đề kỹ thuật cho Kỹ sư trưởng PLC & Điện/quản lý công trường và đảm bảo trình bày chính xác cho các bên liên quan.\n- Tham gia vào công việc cải tiến/cải tạo hệ thống điện và điều khiển, tiến hành hiệu chuẩn, thử nghiệm và gỡ lỗi\n- Phối hợp với kỹ sư OSS Robot & Cơ khí, nhân viên vận hành khách hàng và các bên liên quan chức năng khác trong công việc hàng ngày.\n\nYêu cầu ứng viên\n- Có từng tiếp xúc qua về Siemens, ngoài ra sẽ được đào tạo để nắm bắt công việc.\n- Tốt nghiệp đại học, các chuyên nghành tự động hóa, cơ điện tử,…\n- Nhiệt tình, chăm chỉ.\n- Biết tiếng anh là 1 lợi thế.\n\nQuyền lợi\n- Thưởng lương tháng 13 và đánh giá thưởng KPI hàng năm.\n- Lương cơ bản thương lượng theo năng lực.\n- Trợ cấp dự án, trợ cấp công tác theo từng dự án và khả năng đáp ứng công việc.\n- Hỗ trợ chỗ ở, ăn trưa, xăng xe đi lại làm việc\n- Đóng bảo hiểm xã hội đầy đủ.\n- Du lịch hằng năm theo chế độ công ty.\n\nĐịa điểm làm việc\n- Hà Tĩnh: Tx Kỳ Anh\n- Hải Phòng: Cát Hải.\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Tĩnh, Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2180, 1117, 2, 'Senior Backend Developer (NestJS / FastAPI)', 'Mô tả công việc:\n- Thiết kế kiến trúc hệ thống backend, đảm bảo hiệu năng và khả năng mở rộng\n- Lãnh đạo kỹ thuật, định hướng công nghệ trong team backend\n- Xây dựng và duy trì API sử dụng NestJS và FastAPI\n- Review code, mentor các thành viên junior/intern.\n- Thiết lập các tiêu chuẩn kỹ thuật: coding convention, CI/CD, testing.\n- Tối ưu hoá hệ thống, đảm bảo tính bảo mật, khả năng chịu tải cao.\n- Phối hợp với team DevOps để triển khai, giám sát và vận hành hệ thống.\n\nYêu cầu ứng viên:\n- Kinh nghiệm sâu rộng với NestJS và FastAPI\n- Từng thiết kế hoặc vận hành hệ thống lớn hoặc microservices\n- Thành thạo mô hình thiết kế phần mềm (OOP, SOLID, Clean Architecture, DDD)\n- Kinh nghiệm CI/CD, Docker, git workflow\n- Thành thạo các kỹ thuật tối ưu DB (PostgreSQL/MongoDB)\n- Hiểu biết về bảo mật hệ thống (SQL Injection, XSS, CSRF...)\n- Kỹ năng leadership: mentor, review code, ra quyết định kỹ thuật\n- Biết sử dụng Celery, RabbitMQ, hoặc Redis Queue cho các tác vụ bất đồng bộ.\n\nƯu tiên:\n- Có kinh nghiệm với hệ thống đa tenant, realtime, event-driven.\n- Thành thạo Kubernetes, hệ thống giám sát Prometheus/Grafana.\n- Kinh nghiệm xử lý hàng triệu request mỗi ngày là điểm cộng lớn.\n\nQuyền lợi:\n- Phúc lợi:\n    - Thưởng các ngày lễ: Sinh nhật, Hiếu hỉ, Trung thu, 30/4, 8/3, 20/10, 2/9... tuỳ tình hình kinh doanh công ty\n    - Teambuilding, Tết tây, Tết ta,... Tuỳ hình hình kinh doanh\n    - Tăng lương định kỳ tháng 4 hằng năm.\n- Phụ cấp khác:\n    - Các chế độ bảo hiểm đầy đủ theo quy định pháp luật\n    - Cung cấp thiết bị nơi làm việc\n    - Ngày nghỉ: 12 ngày /năm\n\nĐịa điểm làm việc:\n- Thừa Thiên Huế: Tầng 6, số 2 Lê Quý Đôn, Tòa nhà Vietinbank, Phú Hội, Huế., TP Huế \n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2181, 1118, 2, 'Java Developer', 'Mô tả công việc\n- Chịu trách nhiệm nghiên cứu & phát triển backend sử dụng ngôn ngữ/công nghệ: Java, MySQL, Redis, Memcached, Kafka, ElasticSearch, Docker, K8S,...\n- Thiết kế/lập trình các module, thiết kế giao tiếp cho hệ thống tải lớn hàng trăm triệu người dùng (sử dụng cả Java).\n- Nghiên cứu sử dụng, chỉnh sửa các open source về VoIP, streaming phổ biến.\n- Chi tiết sẽ trao đổi cụ thể khi phỏng vấn.\n\nGiới thiệu về Công ty:\n- Stringee là công ty công nghệ cung cấp nền tảng quản trị doanh nghiệp hợp nhất – Cogover, giúp số hóa toàn diện hoạt động quản trị và vận hành doanh nghiệp. Cogover ứng dụng công nghệ No-code/Low-code và AI, cho phép doanh nghiệp tự xây dựng và tùy chỉnh hệ thống qua thao tác kéo - thả và cấu hình đơn giản, mà không cần lập trình.\n- Hiện tại, Stringee cung cấp 3 bộ sản phẩm chính:\n  - Quản trị khách hàng: CRM, Service, CDP\n  - Quản trị nội bộ: HRM, Recruit, Marketing, Process, Site, Finance\n  - Số hóa giao tiếp: Communication APIs\n- Với hơn 3,000 doanh nghiệp sử dụng, 70 triệu người dùng cuối, và nhiều khách hàng lớn như Viettel, Mobifone, VNDIRECT, Techcombank, TPBank,... Stringee là một trong những nền tảng số Make in Vietnam tiên phong trong chuyển đổi số.\n- Stringee từng đạt giải Nhân tài Đất Việt 2018, Top 10 Sao Khuê 2023, và được Bộ TT&TT công nhận là Nền tảng số xuất sắc Make in Vietnam.\n\nYêu cầu ứng viên\n- Thành thạo Java.\n- Nắm rất vững lập trình hướng đối tượng, Design Pattern.\n- Có kinh nghiệm về unit test và integration test.\n- Hiểu về lập trình đa luồng, non-blocking IO, xử lý bất đồng bộ,...\n- Đã từng làm việc với Socket, TCP/IP, các thư viện như SpringBoot, Netty, Apache MINA là lợi thế.\n- Đã từng làm việc với RabbitMQ, ActiveMQ, Kafka, Docker, K8S,... là lợi thế.\n- Có khả năng làm việc với Linux.\n\nQuyền lợi\n- Lương từ 1000 - 2500 USD (phụ thuộc vào năng lực và kinh nghiệm của bạn, chúng tôi không bao giờ đãi ngộ thấp hơn khả năng của bạn).\n- Thưởng theo hiệu quả công việc (hoàn thành milestone, deadline, ...), thưởng năm, các dịp lễ tết.\n- Môi trường trẻ, năng động, sáng tạo, hỗ trợ tối đa sự phát triển và công việc của nhân viên.\n- Được đào tạo để thường xuyên nâng cao nghiệp vụ. Cơ hội được học hỏi, làm việc với công nghệ mới.\n- Môi trường chuyên nghiệp với các đối tác nước ngoài.\n- Đóng bảo hiểm và các chế độ khác theo Luật lao động; khám sức khoẻ định kỳ hàng năm.\n- Tham gia các câu lạc bộ thể thao: bóng đá, chạy bộ,...\n- Tham dự các buổi đi chơi, dã ngoại, nghỉ mát,... \n\nĐịa điểm làm việc\n- Hà Nội: Tầng 19, Leadvisors Tower, 643 Phạm Văn Đồng, Cổ Nhuế, Bắc Từ Liêm\n\nThời gian làm việc\n- 8h30 – 17h45 từ thứ 2 đến thứ 6 và ngày thứ 7 đầu tiên của tháng (mỗi tháng chỉ làm 1 ngày thứ 7)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2182, 1119, 2, 'Mobile App (Flutter)', 'Mô tả công việc\n- Tham gia vào quá trình phát triển ứng dụng di động sử dụng Flutter framework\n- Thiết kế và triển khai giao diện người dùng ứng dụng dựa trên yêu cầu từ đội thiết kế UI/UX\n- Tối ưu hóa hiệu suất và đảm bảo sự tương thích đa nền tảng\n- Đảm bảo chất lượng mã nguồn trong quá trình phát triển.\n- Sử dụng công cụ test để đảm bảo chất lượng code  \n- Làm việc chặt chẽ với các thành viên khác trong nhóm phát triển, bao gồm thiết kế UI/UX, quản lý dự án và nhóm phát triển backend\n- Nghiên cứu và ứng dụng công nghệ mới  \n- Quản lý tiến độ và báo cáo hàng ngày\n- Thực hiện các nhiệm vụ được các cấp quản lý giao cho  \nYêu cầu ứng viên\n1. Học vấn:\n- Tốt nghiệp cử nhân Đại học Công nghệ, ĐH Bách Khoa, Bưu chính Viễn thông...các chuyên ngành có liên quan\n2. Kinh nghiệm:\n- Tối thiểu 01 năm kinh nghiệm làm việc với Flutter\n- Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực chứng khoán, ngân hàng\n3. Kỹ năng\n- Thành thạo Flutter và Dart\n- Hiểu biết về React là một lợi thế\n- Có khả năng build, customize các dự án mobile app\n4. Khả năng\n- Sáng tạo, tiếp thu công nghệ mới nhanh.  \n- Chịu được áp lực công việc, kiên trì và có tinh thần giải quyết khó khăn.  \n- Nhiệt tình, nhanh nhẹn, hoạt bát và có trách nhiệm với công việc.  \n- Có tinh thần cầu tiến, chủ động trong công việc.  \nQuyền lợi\n- Mức lương và phụ cấp:\nThỏa thuận theo năng lực và kinh nghiệm thực tế. Khung lương (20 - 30tr)\nPhụ cấp ăn trưa (40k/ngày công thực tế)\nPhụ cấp gửi xe (300k/tháng)\nPhụ cấp đi lại, xăng xe, điện thoại (tùy thuộc vào từng vị trí)\n- Thưởng:\nThưởng quý/năm (tùy theo tình hình kinh doanh của Công ty)\nThưởng lễ tết, cuối năm\nThưởng tháng lương 13 +++...\n- Phúc lợi:\nTham gia BHXH, BHSK\nTeambuildings, HappyFridays, du lịch nghỉ dưỡng\n- Cơ hội thăng tiến:\nĐược làm việc đúng chuyên môn/sở trường (làm chủ công việc). Hợp tác với cộng sự/quản lý nhiều kinh nghiệm trong lĩnh vực\nĐược đào tạo trực tiếp nâng cao/bổ sung kiến thức ngành nghề\nĐánh giá năng lực, xét tăng lương/thưởng theo quy định của Công ty\n- Môi trường làm việc:\nNăng động/ trẻ trung và nhiệt huyết\nĐịnh hướng làm việc hybrid\nĐược trang bị các trang thiết bị/công cụ phù hợp với từng vị trí công việc\nLàm việc từ thứ 2 đến thứ 6 (nghỉ thứ 7 và chủ nhật)\n\nĐịa điểm làm việc\n- Hà Nội: 17 Tông Đản, Hoàn Kiếm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2183, 1120, 2, 'Lập Trình Web App ( .Net, C#)', '- Xây dựng các ứng dụng trên nền tảng web bằng React và Dotnet/NodeJs/PHP\n- Tham gia công đoạn tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu công nghệ khi được phân công\n- Thực hiện công việc theo yêu cầu từ quả lý\n\nYêu cầu ứng viên\n- Thành thạo HTML/CSS\n- Có kinh nghiệm xây dựng web bằng React\n- Có khả năng xây dựng API bằng một trong những ngôn ngữ lập trình C sharp, php, java, js (node js), python...\n- Thành thạo các câu lệnh truy vấn SQL\n- Am hiểu về dotnet là một lợi thế\n\nQuyền lợi\n- Mức lương cơ bản từ 10 - 20 triệu tùy theo năng lực và vị trí công việc:\n  10 - 12 triệu với kinh nghiệm 1-2 năm.\n  12- 20 triệu với kinh nghiệm trên 2+ năm.\n- Sẽ được trao đổi mức lương cụ thể khi phỏng vấn.\n- Được tổ chức sinh nhât, nghỉ lễ, nghỉ phép và hưởng quyền lợi theo Luật lao động.\n- Đồng nghiệp và môi trường làm việc năng động\n- Cơ hội được học tập và đào tạo nội bộ về các kỹ năng trong công việc.\n\nĐịa điểm làm việc\n- Nghệ An: Tầng 22 Handico 30 Quang Trung, TP Vinh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 07:45 đến 17:00)\n- Thứ 7 luân phiên nghỉ/làm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nghệ An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2184, 1121, 2, 'Lập Trình Viên .Net', '1. Tham gia vào các hoạt động phát triển phần mềm.\n2. Xây dựng các ứng dụng trên nền tảng Web và Net.\n3. Làm việc trong môi trường công ty Nhật Bản.\n\nYêu cầu ứng viên:\n1) Có kinh nghiệm lập trình trên .NET Framework (C#, ASP.NET)\n2) Hiểu các cơ sở dữ liệu MySql , SQL Server.\n3) Hiểu HTML5, CSS3, JavaScript, jQuery ,bootstrap.\n4) Hiểu biết về các mô hình lập trình OOP, MVC, Web API.\n5) Biết tiếng Nhật là 1 lợi thế.\n6) Hoan nghênh các ứng viên nữ gia nhập công ty.\n\nQuyền lợi:\n- Thưởng lương tháng 13 hàng năm.\n- Thu nhập thoả đáng theo năng lực.\n- Môi trường làm việc thoải mái, năng động.\n- Thời gian làm việc từ T2-T6 (8h-17h), nghỉ T7 và CN.\n- Hưởng đầy đủ các chế độ BHXH + BHYT + các chế độ phúc lợi khác.\n- Công việc ổn định, lâu dài.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 281 Nguyễn Thiện Thuật, Phường 01, Quận 3\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2185, 1122, 2, 'Java Technical Lead', 'Mô tả công việc\n- Work as senior software developer on the web-based application product in JAVA- related and open-source technologies\n- Develop applications based on graphical layout designs that follow the strict requirements\n- Take ownership and accountability for production service, including fix on fail, problem investigation, root cause determination, and resolution\n- Participate in and provide quality assurance activities, including code reviews, white-box testing, test coverage for own work and team outcome\n- Accountable for continuously discovering, evaluating and implementing new technologies/processes to optimize development efficiency or improve product quality\n- Establish estimation, proposing development solutions with customers\n- Foster collaboration across technical teams through mentoring and expert guidance as required to develop the most cost-effective solutions\n- Continuously research and implement new technologies to maximize development efficiency\n\nYêu cầu ứng viên\n- At least 5 years of experience in software & back-end development technologies in general\n- Proven hands-on experience on Java ecosystem, Spring boot, Microservices, SQL, NoSQL: MongoDB, Cassandra…\n- Experience in designing & developing RESTful APIs and microservices-based systems.\n- Strong knowledge of writing secured codes and good understanding of design patterns\n- Experienced in developing and deploying microservices with Cloud based technologies (AWS, Kubernetes, Docker…)\n- Experience in agile scrum-based development process\n\nKỹ năng cần có\n- RESTful APIs\n- Version Control (git)\n- Java (core Java, Advanced Java)\n- Spring Framework (spring Boot, Spring Mvc, Spring Data)\n- Databases (sql, Nosql)\n\nQuyền lợi\n- Probation salary is 100% of official salary\n- 13th-month salary and performance review twice a year\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n- Project Bonuses\n- Employee’s professional certification and training allowances subject to company regulations\n- Health Care Insurance\n- Annual Health Assessment\n- Social, health and unemployment Insurance following Government policy\n- Enjoy company summer trips and other team building activities held monthly and quarterly\n- Work five days per week with flexible check in time\n- Professional, creative and dynamic working environment\n\nĐịa điểm làm việc\n- Hà Nội: Tòa The Nine, Số 9 Phạm Văn Đồng, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2186, 1123, 2, 'Power Platform Developer (PowerApps)', 'Mô tả công việc:\n- Develop and Design: Build custom applications, workflows, and solutions using Microsoft PowerApps, Power Automate, and Power BI.\n- Integration: Connect PowerApps with various data sources such as SharePoint, SQL Server, Dataverse, Azure, and third-party APIs.\n- Requirement Gathering: Collaborate with stakeholders to understand business needs and translate them into technical requirements.\n- Automation: Implement process automation solutions using Power Automate (Flow) to streamline business operations.\n- Customization: Customize apps with PowerApps formulas, Canvas Apps, Model-Driven Apps, and Portals.\n- Testing and Deployment: Perform thorough testing, debugging, and deployment of Power Platform solutions.\n- Documentation: Create and maintain comprehensive technical documentation, including workflows, processes, and troubleshooting guides.\n- Training and Support: Provide end-user training and support for deployed applications and solutions.\n- Best Practices: Stay updated with Power Platform features and ensure adherence to development best practices and governance.\n\nYêu cầu ứng viên:\n- Technical Expertise:\n  - Proficiency in Microsoft PowerApps, Power Automate, and Power BI.\n  - Experience with Canvas Apps, Model-Driven Apps, and Dataverse.\n  - Strong understanding of relational databases and data modeling.\n  - Knowledge of Azure services and API integration is a plus.\n- Development Skills:\n  - Hands-on experience with JavaScript, HTML, CSS, and JSON.\n  - Familiarity with Microsoft 365 ecosystem, including SharePoint, Teams, and Dynamics 365.\n- Experience:\n  - 2 years of experience in developing PowerApps solutions (e.g., Canvas Apps, Model-Driven Apps).\n  - Knowledge of RPA (Robotic Process Automation) is a plus.\n\nQuyền lợi:\n- Salary: Negotation\n- Join a global team and work directly with many talents around the world.\n- Opportunities for onsite work in Japan, Singapore, Australia, and many other countries.\n- Work and grow in a dynamic, creative, and professional environment.\n- Healthcare: Premium Health Insurance TECHVIFY Care\n- 13 months’ salary per year.\n- Annual salary evaluation.\n- Sponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.\n\nĐịa điểm làm việc:\n- Hà Nội: HUD Tower, Lê Văn Lương, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2187, 418, 2, 'Kỹ Sư Phát Triển Phần Mềm', 'Mô tả công việc:\n- Phát triển phần mềm cho các khách hàng (ERP, Cổng thanh toán điện tử, hệ thống xác thực)\n- Nghiên cứu, phát triển các công nghệ, giải pháp cho các sản phẩm của công ty: Phát triển phần mềm, đề xuất ứng dụng công nghệ mới, tích hợp hệ thống\n- Tìm hiểu về công nghệ mới theo yêu cầu công việc.\n- Phân tích, thiết kế hệ thống, làm tài liệu thiết kế chi tiết.\n\nYêu cầu ứng viên:\n- Thành thạo lập trình Java, có kinh nghiệm tốt với Spring Boot\n- Kinh nghiệm với Hibernate là lợi thế\n- Có hiểu biết về Restful Api.\n- Hiểu biết về lập trình hướng đối tượng, đa luồng.\n- Làm việc thành thạo với ít nhất một trong các CSDL dạng SQL và NoSQL.\n- Sử dụng thành thạo Git hoặc các phần mềm tương tự.\n- Sử dụng thành thạo với ít nhất 1 công cụ test API, vd: Postman.\n- Có kinh nghiệm phát triển dự án sử dụng JWT.\n- Có kinh nghiệm phát triển dự án theo mô hình MVC.\n- Có kinh nghiệm phát triển dự án sử dụng GRPC là một lợi thế.\n- Có kiến thức về Strut là một lợi thế.\n- Có kiến thức về Time series DB như Apache Druid là một lợi thế.\n- Khả năng tự học các ngôn ngữ công nghệ mới là một lợi thế lớn.\n- Kinh nghiệm từ 2 năm trở lên.\n- Trình độ Đại học.\n- Ưu tiên có kinh nghiệm ở các dự án lớn.\n\nQuyền lợi:\n- Thu nhập upto 30tr + thưởng dự án.\n- Được tham gia bảo hiểm theo quy định của pháp luật.\n- Tham gia công đoàn và hưởng các chính sách, quyền lợi công đoàn.\n- Khám sức khỏe định kỳ.\n- Chế độ sinh nhật, hiếu, hỷ, lễ tết,... đầy đủ theo quy định của Tập đoàn.\n- Du lịch, nghỉ mát hàng năm cho CBNV.\n- Được đào tạo nâng cao kiến thức, kỹ năng chuyên môn thường xuyên.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 3, BT 10, KĐT Xa La, Hà Đông.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2188, 1124, 2, 'Java Developer', 'Mô tả công việc\n- Designing, developing, and maintaining Java applications\n- Performing technical analysis to identify solutions and creating technical documentation\n- Developing functionalities for applications/systems\n- Writing APIs, Unit Tests, and optimizing performance for APIs and databases\n- Participating in database design to meet customer requirements\n- Designing high-level and low-level solutions for products\n- Participating in project supervision to ensure technical quality and coding standards\n- Being responsible for mentoring team members on coding and technology, and guiding the development of features based on design and architecture documentation\n- Exploring core technologies and company technologies\n- Researching and exploring new technologies such as K8S, Microservices, Cloud Native,…\n\nYêu cầu ứng viên\n- A minimum of 3 years of experience in software development, with a strong preference for candidates with a background in Finance, Banking, or Insurance sectors\n- Being proficient in object-oriented programming with Java, RESTful API, WebSocket, and Microservice\n- Possessing a solid understanding of the software development process (preferring candidates with experience in Scrum/Agile/Kanban)\n- Demonstrating strong knowledge of OOP, OOA/D, and design patterns such as GoF, Dependency Injection, IoC, SOLID, etc\n- Having experience in multi-threading, synchronous, and asynchronous processing\n- Being capable of conducting in-depth research and problem-solving\n- Possessing good knowledge of databases (RDBMS, NoSQL), ORM, and persistence frameworks\n- Being capable of performing code review, code standardization, and ensuring adherence to coding conventions\n- Having experience working with Microservices architecture, Layered architecture, SOA, and Distributed Systems\n- Having experience with Docker, Docker Swarm, and Kubernetes is an advantage\n- Having experience with streaming/messaging frameworks like MQTT, RabbitMQ, and Kafka is a plus\n\nQuyền lợi\n- Attractive salary, suitable for working capacity\n- Review performance twice a year ( In working process, Candidate can be reviewed continuously before the term if the job is successfully completed)\n- Devices provided (Laptop, PC, mouse, monitor…)\n- Working hours: HN, Vinh: 8:30 - 17:30, HCM: 9:00 - 18:00, 5 days/ week\n- Enjoying good remuneration of company when becoming an employee: social insurance, PTI insurance, annual company trip,…\n- Recognition and rewards based on your performance\n- High promotion opportunity\n- Good career path development\n- Creative, modern and open working place\n- Continuous and professional training to fully develop your potential\n\nĐịa điểm làm việc\n- Hà Nội: Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2189, 1125, 2, 'Lập Trình Viên Backend', 'Mô tả công việc:\n1. Tham gia phát triển và duy trì hệ thống back-end cho các dự án phần mềm hỗ trợ đầu tư chứng khoán, đào tạo trực tuyến và các lĩnh vực khác mà công ty đang mở rộng.\n2. Thiết kế, xây dựng và tối ưu hóa các API bảo đảm tính ổn định, hiệu suất và bảo mật.\n3. Thu thập dữ liệu tự động từ các nguồn, chuẩn hóa và lưu trữ dữ liệu. \n4. Phối hợp với nhóm front-end, QA, PM... trong quá trình phát triển và triển khai dự án.\n5. Tham gia nghiên cứu, cập nhật các xu hướng công nghệ mới và ứng dụng vào sản phẩm.\n\nYêu cầu ứng viên:\n1. Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các ngành liên quan; hoặc tốt nghiệp đại học ngành khác nhưng có tối thiểu 2 năm kinh nghiệm lập trình back-end.\n2. Thành thạo ít nhất một ngôn ngữ/lộ trình back-end (Java, Node.js, Python, .NET, PHP, v.v.).\n3. Có kinh nghiệm làm việc với cơ sở dữ liệu (SQL hoặc NoSQL).\n4. Biết sử dụng các công cụ lập trình AI, biết sử dụng các cơ sở dữ liệu phi truyền thống như Neo4j là lợi thế.\n5. Ưu tiên ứng viên đã có kinh nghiệm tham gia dự án thực tế, đặc biệt là các dự án có yếu tố AI.\n6. Tinh thần cầu tiến, có khả năng học hỏi nhanh và làm việc nhóm tốt.\n\nQuyền lợi:\n1. Được làm việc trong các dự án sáng tạo, có hàm lượng công nghệ cao, tiếp cận nhiều thách thức thú vị.\n2. Có cơ hội nâng cao chuyên môn, kỹ năng nghiệp vụ và thăng tiến trong công việc.\n3. Mức lương cạnh tranh, thưởng theo hiệu quả công việc và đóng góp.\n4. Môi trường làm việc thân thiện, khuyến khích sự chủ động và sáng tạo.\n5. Tham gia đầy đủ các chế độ bảo hiểm và các phúc lợi khác theo quy định công ty.\n\nĐịa điểm làm việc:\n- Hà Nội: 37 Lê Văn Thiêm Phường Nhân Chính, Thanh Xuân\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n8h-17h, T7 ngày lẻ\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2190, 1126, 2, 'Nhân Viên Lập Trình', 'Mô tả công việc:\n- Nghiên cứu, cải tiến sản phẩm phần mềm hiện có của Công ty.\n- Xây dựng sản phẩm theo đơn đặt hàng của Khách hàng.\n- Triển khai và hướng dẫn và hỗ trợ Khách hàng sử dụng phần mềm.\n- Giờ làm việc là 8h30-12h, 13h30-17h30 từ thứ 2 – thứ 6, Thứ 7 làm buổi sáng.\n- Công việc cụ thể sẽ trao đổi rõ hơn lúc phỏng vấn.\n\nYêu cầu ứng viên:\n1. Tốt nghiệp đại học/cao đẳng chuyên ngành công nghệ thông tin;\n2. Sử dụng thành thạo các ngôn ngữ lập trình .NET C#, VB.NET. Ưu tiên biết cả hai;\n3. Có kinh nghiệm làm việc với MS SQL và tối ưu truy vấn;\n4. Có kiến thức về phân tích thiết kế lập trình và quy trình phát triển phần mềm;\n5. Có khả năng nghiên cứu và nắm bắt các công nghệ mới;\n6. Khả năng tiếng anh đọc hiểu tốt, giao tiếp căn bản;\n7. Ưu tiên các ứng viên có thể đi công tác thường xuyên.\n\nQuyền lợi:\n- Đội ngũ lãnh đạo, quản lý đầy tài năng và nhiệt huyết, luôn trọng dụng nhân tài.\n- Môi trường làm việc năng động, chuyên nghiệp.\n- Lương thưởng xứng đáng theo năng lực.\n- Hưởng đầy đủ BHXH và các chế độ chính sách khác theo quy định của Bộ Luật lao động và công ty;\n- Được nghỉ 15 (mười lăm) ngày phép vẫn hưởng nguyên lương.\n- Thưởng cuối năm, thưởng dự án, thưởng hiệu suất,.. theo thành tích công việc;\n- Môi trường trẻ trung, năng động: Teambuilding hàng năm, Du lịch kỉ niệm ngày thành lập công ty, Year End Party, hoạt động vui chơi, giải trí hấp dẫn khác.\n- Được tham gia các khóa đào tạo kỹ năng, đào tạo nâng cao chuyên môn đáp ứng nhu cầu công việc.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Số 34 Đường Võ Thị Đặng, Phường Tân Phong TP HCM (Số cũ : Số 34 đường 32, P. Tân Phong, Quận 7\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nThứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2191, 186, 2, 'Lập Trình Viên Server. Thu Nhập Upto 40M', 'Mô tả công việc\nThiết kế và triển khai các hệ thống phía máy chủ hiệu năng cao bằng ngôn ngữ C trên môi trường Unix/Linux, áp dụng cụ thể cho nền tảng Kiwoom.\n• Tích hợp CSDL & Giao tiếp liên tiến trình:\nSử dụng CISAM, giao tiếp liên tiến trình (IPC) và bộ nhớ dùng chung (Shared Memory) để xử lý dữ liệu hiệu quả và điều phối tiến trình mượt mà.\n• Hợp tác với các nhóm từ xa:\nLàm việc chặt chẽ với các nhóm làm việc từ xa để làm rõ yêu cầu, thống nhất nhiệm vụ phát triển và đảm bảo truyền đạt thông tin hiệu quả giữa các nhóm.\n• Phân tích yêu cầu & thiết kế tính năng:\nTham gia phân tích yêu cầu người dùng và thiết kế kiến trúc hệ thống, đóng góp vào việc phát triển các tính năng mới.\n• Xử lý lỗi và sự cố:\nPhân tích và khắc phục lỗi trong quá trình kiểm thử tích hợp, kiểm thử chấp nhận người dùng (UAT) và kiểm thử bảo trì, đảm bảo độ ổn định và hiệu suất hệ thống.\n• Quản lý dự án:\nQuản lý thời gian và nguồn lực hiệu quả dựa trên Cấu trúc phân rã công việc (WBS) để đảm bảo tiến độ và chất lượng dự án.\n\nYêu cầu ứng viên\n• Bắt buộc ứng viên sử dụng được : .NET (C#)\n• Bắt buộc có kinh nghiệm sử dụng công cụ Git, và có hiểu biết về CI/CD\n• Kinh nghiệm: từ 5 năm trở lên\n• Yêu cầu: Có portfolio, đính kèm mã nguồn (code)\n• Trong quá trình phỏng vấn:\n  + Có thể có bài thi tự luận về Design Pattern\n+ Kèm bài kiểm tra lập trình (coding test) ( nhằm đánh giá cả tư duy lập trình lẫn khả năng thiết kế phần mềm.) \n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận. Mức lương cao, có thể thoả thuận theo năng lực của ứng viên\n• 1 năm tăng lương/lần\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước)\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm , Tiêm phòng HPV, cúm,...\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes Gardenia Hàm Nghi, Nam Từ Liêm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2192, 1127, 2, 'Giáo Viên 3D Unity Game Part Time', 'Mô tả công việc:\n- Tham gia giảng dạy khóa đào tạo Unity Game Developer theo nội dung và lộ trình của Green Academy.\n- Thiết kế slide và giáo trình giảng dạy cho các buổi học. (Có thể tham khảo sử dụng giáo trình hiện tại của trung tâm).\n- Hướng dẫn học viên làm đồ án cuối khóa, đảm bảo chất lượng đầu ra của học viên.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học / Cao đẳng chuyên ngành liên quan đến Công Nghệ Thông Tin.\n- Đã và đang làm việc trong lĩnh vực phát triển Game với UNITY từ 3-4 năm.\n- Có kinh nghiệm và kiến thức liên quan đến xây dựng các thể loại game 2D & 3D.\n- Khả năng thuyết trình, truyền đạt kiến thức và nghiên cứu giảng dạy là một lợi thế.\n- Có tinh thần trách nhiệm cao với công việc.\n\nQuyền lợi:\n- Lương giờ dạy: 220-250k/h.\n- Giảng dạy và làm việc trong môi trường chuyên nghiệp mang văn hóa Việt – Hàn.\n- Thời gian dạy được sắp xếp linh động theo lịch.\n- Hỗ trợ củng cố kiến thức chuyên môn và nghiệp vụ liên quan trước khi nhận lớp.\n- Hợp đồng Lao động theo đúng quy định của Luật lao động Việt Nam.\n- Được cung cấp đầy đủ các trang thiết bị giảng dạy hiện đại và tiện nghi theo đúng tiêu chuẩn của Green Academy Hàn Quốc.\n- Hỗ trợ chi phí giữ xe tại trung tâm.\n\nĐịa điểm làm việc:\n- Hà Nội: 201 Trường Chinh, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2193, 1128, 2, 'Fullstack Developer (Java + Reactjs)', 'Mô tả công việc\nPhát triển, tối ưu và bảo trì hệ thống web cho khách hàng Nhật Bản với Java (Spring Boot) ở backend & React ở frontend.\nTham gia toàn bộ SDLC: phân tích yêu cầu, thiết kế, coding, code-review, CI/CD và triển khai trên AWS.\nĐề xuất giải pháp kỹ thuật, nâng cao hiệu năng (multithread, concurrency), đảm bảo bảo mật và chất lượng mã.\nMentor thành viên junior, phối hợp chặt chẽ với PM và khách hàng.\n\nYêu cầu ứng viên\n- Học vấn: Tốt nghiệp Đại học chuyên ngành CNTT hoặc liên quan.\n- Kinh nghiệm: 4 năm Java/Spring & 2 năm React; từng đảm nhiệm vai trò full-stack.\n- Java: OOP, Clean Code, Design Patterns; thuần thục Collection vs Stream, multithread/async; logging; đọc/ghi & migration dữ liệu DynamoDB.\n- DynamoDB: phân biệt và dùng đúng Query vs Scan, lấy dữ liệu bulk, thiết kế & sử dụng GSI hiệu quả.\n- React: quản lý state toàn cục với useContext hook, hiểu kiến trúc component, tối ưu render.\n- AWS: SSH vào EC2, xuất log, phát hiện & xử lý overload/instance die; kiến thức Auto-Scaling, CloudWatch là lợi thế.\n- Khác:\n  + MySQL hoặc NoSQL (MongoDB)\n  + Thành thạo Git\n  + Tư duy giải thuật tốt, tự học nhanh\n  + Giao tiếp tiếng Nhật (N3+) là điểm cộng.\n\nQuyền lợi\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng kinh doanh cuối năm + thưởng dự án, thưởng các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe 24/24;\n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện);\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày;\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành;\n- Miễn phí đồ uống tại khu ăn uống của công ty;\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan;\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLUB Dance;...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm;...\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4 CT1, Tòa C14 Bắc Hà, Đường Tố Hữu, Phường Trung Văn, Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2194, 1129, 2, 'Game Developer', 'Tại Nexar, các Developer là trái tim của các dự án, nhân sự sẽ làm việc và phối hợp với tất cả các team để tạo ra những trải nghiệm mới mẻ, những dòng game độc đáo, những sản phẩm chất lượng. Vì thế, chúng tôi đánh giá cao những Developer có chuyên môn tổng quát, có thể làm việc trên nhiều lĩnh vực khác nhau trong quá trình phát triển trò chơi. Bên cạnh đó, bạn sẽ là người suy nghĩ chiến lược, sẵn sàng đưa ra các quyết định khôn ngoan dựa trên các mục tiêu rõ ràng.\n\nTrách nhiệm\n- Phối hợp cùng các thành viên bộ phận khác lên kế hoạch, xây dựng và phát triển game bằng Unity engine.\n- Sửa lỗi, cải thiện tính năng, nâng cao hiệu suất của games.\n- Tham gia đóng góp ý tưởng, nội dung để tối ưu hóa sản phẩm.\n\nYêu cầu ứng viên\n- Đam mê tuyệt đối và mong muốn phát triển chuyên sâu với công việc phát triển trò chơi.\n- Có hiểu biết về C++, nền tảng về kiến trúc máy tính, lập trình đồ họa máy tính, tốt nghiệp các trường đại học chuyên ngành CNTT là một lợi thế.\n- Có kiến thức về thuật toán và cấu trúc dữ liệu, đọc hiểu tiếng Anh, thành thạo ngôn ngữ lập trình C#.\n- Có ít nhất 1 năm kinh nghiệm phát triển game với Unity.\n- Khả năng tư duy logic, phát triển, sáng tạo và cải tiến trong công việc.\n- Ham học hỏi, tự chủ, trách nhiệm trong công việc.\n- Ưu tiên các ứng viên có mong muốn phát triển theo hướng khai phá, nghiên cứu kỹ thuật, công nghệ để áp dụng vào phát triển sản phẩm, tạo lợi thế cạnh tranh trên thị trường.\n\nQuyền lợi\n- Văn hoá làm việc tự chủ, linh hoạt trong việc nghỉ phép và giờ giấc. Trách nhiệm và sự hiệu quả trong công việc là điều chúng tôi quan tâm hơn.\n- Môi trường năng động và chuyên nghiệp thuận lợi cho mục tiêu phát triển sự nghiệp bền vững cũng như nâng cao năng lực chuyên môn.\n- Luôn có những người bạn buddy và mentor giàu kinh nghiệm, sẵn sàng hỗ trợ và dẫn dắt bạn.\n- Mức lương offer: $500 - $1500 Tùy theo kiến thức, kinh nghiệm và tiềm năng phát triển của bạn.\n- Chia sẻ lợi nhuận theo dự án không giới hạn, không tỉ lệ thuận với kiến thức hay kinh nghiệm, nó sẽ phụ thuộc phong độ và sự đóng góp của bạn trong việc tạo ra giá trị cho công ty.\n\nĐịa điểm làm việc\n- Hà Nội: Tháp Thiên Niên Kỷ, Số 4 Quang Trung, Quang Trung, Hà Đông\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2195, 1130, 2, 'Mobile Developer (Middle/Senior) - IOS/Android', 'Mô tả công việc: Tham gia vào toàn bộ vòng đời phát triển sản phẩm, từ lên ý tưởng, thiết kế, phát triển đến triển khai và bảo trì ứng dụng di động trên cả hai nền tảng iOS và Android. Phối hợp trực tiếp với Development Lead để nhận định, lên kế hoạch và triển khai các tác vụ công việc hàng ngày. Tối ưu hiệu năng (performance) và trải nghiệm người dùng (UX/UI) cho ứng dụng, đảm bảo khả năng đáp ứng lượng truy cập lớn (2 triệu MAU). Xây dựng và triển khai các tính năng mới, đồng thời cải tiến các tính năng hiện có dựa trên phản hồi của người dùng và phân tích dữ liệu. Nghiên cứu, đề xuất và áp dụng các giải pháp kỹ thuật, công nghệ mới để giải quyết các thách thức về quy mô và hiệu năng của sản phẩm. Phối hợp chặt chẽ với Product Manager, UI/UX Designer và các thành viên khác trong team để định hướng và thực thi roadmap sản phẩm. Chủ động học hỏi, nâng cao kiến thức chuyên môn và có cơ hội chia sẻ, hướng dẫn các thành viên junior trong đội ngũ. Yêu cầu ứng viên: Tốt nghiệp đại học chuyên ngành CNTT hoặc chuyên ngành liên quan. Từ 3-5 năm kinh nghiệm làm việc chuyên nghiệp trong lĩnh vực phát triển ứng dụng di động. Thành thạo ít nhất một trong hai ngôn ngữ lập trình và nền tảng: Swift cho phát triển iOS, Kotlin cho phát triển Android. Có kinh nghiệm làm việc với các ứng dụng có quy mô lớn, lượng người dùng cao và hiểu biết về các thách thức liên quan. Hiểu biết sâu sắc về tối ưu hiệu năng (performance optimization) và quản lý bộ nhớ (memory management) trên nền tảng di động. Có tư duy sản phẩm tốt, khả năng phân tích và giải quyết vấn đề kỹ thuật một cách hiệu quả. Tinh thần trách nhiệm cao, chủ động trong công việc, có khả năng làm việc độc lập và phối hợp nhóm tốt. Quyền lợi: Chế độ lương, thưởng, thu nhập: Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án, Lương tháng 13, Đánh giá, xét tăng lương 1 lần/năm theo năng lực. Chế độ phúc lợi: Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước, Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn, Tham gia BHXH sau thử việc, 12 ngày phép năm, Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ, Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết... Cơ hội phát triển bản thân: Lộ trình phát triển sự nghiệp rõ ràng với cơ hội thăng tiến lên vị trí Development Lead, Làm việc trực tiếp với sản phẩm công nghệ có tác động lớn, phục vụ hơn 2 triệu người dùng, Đối mặt và giải quyết các bài toán kỹ thuật thách thức ở quy mô lớn, Đóng góp trực tiếp vào việc định hình và phát triển sản phẩm giáo dục hàng đầu thị trường Việt Nam, Môi trường làm việc trẻ trung, năng động, chuyên nghiệp tại một công ty công nghệ Việt Nam, nơi khuyến khích sự đổi mới và sáng tạo, Cơ hội liên tục học hỏi, tiếp xúc với các công nghệ mới và các chuyên gia trong ngành, Mức lương cạnh tranh theo năng lực và kinh nghiệm, cùng các chế độ phúc lợi hấp dẫn (thưởng, bảo hiểm, team building, v.v), Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện, Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp, Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân. Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6, Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2196, 1131, 2, 'Software Engineer', 'Mô tả công việc\n- Phát triển, kiểm thử và sửa lỗi phần mềm theo yêu cầu.\n- Bảo trì, nâng cấp để đảm bảo hiệu năng hệ thống.\n- Đề xuất các giải pháp kỹ thuật nhằm đáp ứng yêu cầu nghiệp vụ.\n- Tham gia thiết kế hệ thống phần mềm.\n- Cung cấp tài liệu kỹ thuật đầy đủ trong quá trình phát triển.\n- Phối hợp với các bộ phận liên quan để đảm bảo tiến độ dự án.\n\nYêu cầu ứng viên\n- Tốt nghiệp ngành CNTT, Kỹ thuật máy tính hoặc tương đương.\n- Tối thiểu 5 năm kinh nghiệm làm việc với Java, đặc biệt các framework như Spring Boot, Spring MVC, Spring Data,...\n- Thành thạo cơ sở dữ liệu SQL và NoSQL, có khả năng tối ưu truy vấn và thiết kế DB hiệu quả.\nƯu tiên:\n- Kinh nghiệm trong lĩnh vực tài chính – ngân hàng.\n- Có kinh nghiệm làm việc với nền tảng đa kênh (Omni-channel)\n\nQuyền lợi\n- Lương tháng 13\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop…. \n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm\n- Làm việc với tác đối tác lớn\n- Review tăng lương định kỳ hàng năm (1 lần / năm)\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Quận 4\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 4', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2197, 1132, 2, 'Backend Technical Leader', 'Mô tả công việc:\n- Lãnh đạo đội ngũ phát triển Backend Game Server, đảm bảo chất lượng và tiến độ công việc\n- Thiết kế và phát triển các tính năng hệ thống, API và dịch vụ liên quan đến game server\n- Đảm bảo hiệu suất và khả năng mở rộng của hệ thống backend để hỗ trợ người chơi đồng thời\n- Phối hợp với đội Client Dev và các bộ phận khác để giải quyết vấn đề và tối ưu hệ thống\n- Phát triển và duy trì các giải pháp xử lý dữ liệu lớn và thời gian thực cho game\n- Tích hợp các dịch vụ phân tích dữ liệu và tối ưu hóa quá trình thu thập, xử lý và phân tích dữ liệu người dùng để cung cấp insights cho game và các bộ phận liên quan\n\nYêu cầu ứng viên:\n- Thành thạo Java, Node JS, đặc biệt trong môi trường phát triển Game Server\n- Kinh nghiệm làm việc với các dịch vụ cloud như AWS, GCP hoặc Azure\n- Kiến thức sâu về thiết kế hệ thống phân tán, microservices và quản lý dữ liệu lớn\n- Kinh nghiệm với các công nghệ như Docker, Kubernetes, CI/CD, và các công cụ quản lý container\n- Kinh nghiệm làm việc với các database NoSQL (MongoDB, Cassandra, Redis, v.v.) và SQL (MySQL, PostgreSQL)\n- Kinh nghiệm làm việc với các hệ thống phân tích và logging (ELK stack, Prometheus, Grafana, v.v.)\n- Khả năng lãnh đạo, giải quyết vấn đề và khả năng giao tiếp tốt\n- Kinh nghiệm phát triển các hệ thống có khả năng mở rộng và chịu tải lớn\n- Kỹ năng làm việc độc lập và quản lý đội ngũ, giúp đội phát triển trong môi trường agile\n\nQuyền lợi:\n- Lương: 35.000.000 - 50.000.000 VNĐ/tháng (Tùy level)\n- Thưởng các ngày nghỉ lễ, thưởng lương tháng 13; thưởng tết (1-5 tháng lương)\n- Review lương 2 lần/năm\n- Phụ cấp ăn trưa, thuê trọ, đi lại\n- Xét duyệt thưởng tour du lịch 6 tháng/lần\n- Văn hóa công ty: đọc sách, tập thể dục hàng ngày\n- Làm việc trong môi trường trẻ trung, thân thiện và hướng đến việc phát triển con người\n- Chế độ BHXH, BHYT, BHTN theo luật lao động\n- Trang bị thiết bị hiện đại, laptop, màn hình lớn\n- Du lịch hàng năm, tham gia liên hoan hàng tháng\n- Đồ ăn nhẹ /đồ uống miễn phí\n- Tham gia vào CLB Bóng đá của công ty hàng tuần\n- Quyền lợi dành cho thành viên: Từ > 01 năm được khám sức khỏe tổng quát 1 năm/lần; Từ > 03 năm được cấp vốn mua nhà, mua xe......\n- Thời gian làm việc: Thứ 2 – Thứ 6 + 01 thứ 7 Creative day; nghỉ 03 thứ 7 và 4 chủ nhật (8h30 - 18h, nghỉ trưa 1h30p)\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa The Nine, số 9 Phạm Văn Đồng, Mai Dịc, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Thêm 01 thứ 7 trong tháng (Có hoặc không)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2198, 1133, 2, 'Vận Hành Máy CNC', 'Mô tả công việc\n- Nhận bản vẽ, các yêu cầu sản phẩm.\n- Đọc kỹ các thông số kỹ thuật chi tiết của bản vẽ.\n- Chuẩn bị và lắp đặt các dụng cụ trước khi chạy máy.\n- Kiểm tra chương trình gia công, kích thước các chi tiết theo đúng yêu cầu bản vẽ.\n- Vận hành máy CNC để mộc ráp hoặc lên PU.\n- Cân chỉnh máy thao tác gá đặt phôi.\n- Phối hợp với kỹ thuật và các bộ phận liên quan để đưa ra giải pháp tốt nhất để tăng năng suất.\n- Chịu trách nhiệm về chỉ tiêu được giao hàng ngày.\n\nCác nhiệm vụ khác được giao bởi Tổ trưởng.\n\nYêu cầu ứng viên\n- Kiến thức chuyên ngành: Có kiến thức về việc vận hành và sữa chữa máy CNC.\n- Kinh nghiệm làm việc: trên 2 năm ở vị trí tương đương, ưu tiên ngành gỗ/nội thất.\n- Kỹ năng: Làm việc đội nhóm, biết đọc bản vẽ kỹ thuật.\n- Anh ngữ đọc hiểu hồ sơ, tài liệu.\n- Nơi làm việc: Quận 12.\n- Tuổi từ 25 – 35.\n\nQuyền lợi\n- Lương: Thỏa thuận theo năng lực.\n- Môi trường làm việc năng động, cởi mở, thân thiện.\n- Công việc ổn định, lâu dài.\n- Được hưởng các chế độ bảo hiểm theo quy định của nhà nước.\n- Thu nhập xứng đáng với năng lực và sự cống hiến.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: TL 15, Thạnh Lộc, Q12, Quận 12.\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2199, 1134, 2, 'Frontend Developer', 'Mô tả công việc\n- Phát triển ứng dụng tài chính trên nền tảng Web/Mobile.\n- Nghiên cứu các xu hướng công nghệ và kỹ thuật mới, đặc biệt là trong ngành công nghệ tài chính.\n- Phối hợp chặt chẽ với các chức năng khác để điều tra các vấn đề và sửa lỗi.\n- Cộng tác với các thành viên khác để thu thập yêu cầu và phát triển các tính năng mới.\n- Đảm bảo chất lượng mã nguồn và nâng cao hiệu suất ứng dụng.\n- Tối ưu hoá mã nguồn, đánh giá mã nguồn và kiểm tra đơn vị theo chỉ dẫn của quản lý dự án.\n\nYêu cầu ứng viên\n1. Trình độ học vấn: Tốt nghiệp Cao đẳng trở lên, chuyên ngành Khoa học máy tính, Công nghệ thông tin, Toán – Tin học.\n2. Kinh nghiệm:\n- Có ít nhất 3 năm kinh nghiệm làm việc trong lĩnh vực phần mềm.\n- Có kinh nghiệm trong ngành Tài chính tiêu dùng, Bảo hiểm, Ngân hàng là lợi thế.\n- Có kinh nghiệm phát triển ứng dụng Mobile (Cross-Platform) là lợi thế.\n\n3. Kỹ năng:\n- Sử dụng thành thạo các công nghệ/công cụ: TypeScript/JavaScript, ES6, Redux, ReactJS, Redux, Redux-Saga, Hooks.\n- Có kiến thức về cấu trúc dữ liệu & thuật toán, OOP, quản lý bộ nhớ, mẫu thiết kế, SOLID.\n- Sử dụng thành thạo công cụ kiểm thử: CucumberJS., Jest/Mocha/Chai/Selenium.\n- Am hiểu phương pháp Agile (làm việc trong Scrum) sử dụng Jira/Gitlab/Trello.\n- Lợi thế: Flutter.\n\nQuyền lợi\n- Thử việc 100% mức lương;\n- Ký Hợp đồng Lao động chính thức;\n- Chế độ Bảo hiểm xã hội, Bảo hiểm thất nghiệp, Bảo hiểm y tế theo quy định Nhà nước sau 2 tháng thử việc;\n- Bảo hiểm tai nạn 24/24;\n- Khám sức khỏe định kỳ;\n- Được tham gia khóa đào tạo chuyên môn;\n- 16 ngày phép/năm;\n- Lương tháng 13, thưởng và phụ cấp tùy theo từng vị trí.\n\nĐịa điểm làm việc\n- Hồ Chí Minh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2200, 1135, 2, 'Android App Developer', 'Mô tả công việc:\n- Tham gia phát triển các ứng dụng di động Android sử dụng Kotlin\n- Nghiên cứu và ứng dụng các công nghệ mới trong phát triển ứng dụng di động\n- Làm việc với các bộ phận khác trong công ty để đảm bảo tiến độ và chất lượng sản phẩm\n\nYêu cầu ứng viên:\n- Có ít nhất 3 năm kinh nghiệm lập trình android bằng ngôn ngữ Kotlin.\n- Có kinh nghiệm phát triển ứng dụng IAA & IAP\n- Nắm vững kiến thức về Android, OOP, Kotlin, Java và các kiến thức về lập trình di động\n- Nắm vững mô hình phát triển ứng dụng android (MVVM, MVC, ...)\n- Sử dụng thành thạo git version control\n- Có kinh nghiệm làm việc với các công nghệ khác như REST API, JSON, SQL,...\n- Có khả năng làm việc độc lập và làm việc nhóm tốt\n- Có khả năng học hỏi và tiếp thu kiến thức mới nhanh\n- Đọc hiểu tiếng anh ở mức tốt, giao tiếp ở mức cơ bản\n- Nắm được các nguyên lý thiết kế trong OOP & Design Pattern là 1 lợi thế\n\nQuyền lợi:\n- Lương: thỏa thuận\n- Thưởng theo hiệu quả công việc\n- Bảo hiểm PVI theo cấp bậc\n- Môi trường làm việc trẻ trung, năng động, chuyên nghiệp\n- Cơ hội được đào tạo và phát triển bản thân\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa nhà Sun Square, Lê Đức Thọ, Mỹ Đình, Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2201, 1136, 2, 'Lập Trình Mobile (React Native)', 'Mô tả công việc:\n- Phát triển và bảo trì các ứng dụng di động trên nền tảng iOS và Android.\n- Thiết kế, xây dựng và triển khai các tính năng mới cho ứng dụng.\n- Viết code sạch, hiệu quả và dễ bảo trì.\n- Thực hiện kiểm thử và gỡ lỗi ứng dụng.\n- Cải thiện hiệu năng và trải nghiệm người dùng của ứng dụng.\n- Hợp tác với các thành viên khác trong nhóm để hoàn thành dự án.\n- Tham gia vào quá trình lên kế hoạch và ước lượng thời gian cho các dự án.\n- Đóng góp ý tưởng và giải pháp để cải thiện chất lượng sản phẩm.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm phát triển ứng dụng di động.\n- Thành thạo React Native, JavaScript, TypeScript. Ưu tiên biết Java Kotlin Object C, Swift.\n- Hiểu biết về kiến trúc ứng dụng di động và các nguyên tắc thiết kế.\n- Có kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu (SQL, NoSQL).\n- Có kinh nghiệm sử dụng các hệ thống quản lý phiên bản như Git.\n- Quen thuộc với các phương pháp Agile (Scrum, Kanban).\n\nQuyền lợi:\n- Mức lương 12 triệu - 20 triệu + thưởng tháng 13 + thưởng dự án.\n- Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n- Cơ hội được làm việc với các công nghệ mới.\n- Được đào tạo và phát triển kỹ năng chuyên môn.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế theo quy định của pháp luật.\n- Thưởng các ngày lễ, tết và các hoạt động team building thường xuyên.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2202, 1137, 2, 'Fullstack Developer (Node/Next) Level Middle/Senior', 'Mô tả công việc:\n- Tham gia vào các dự án phát triển ứng dụng Web;\n- Có khả năng đảm nhận vai trò kỹ thuật leader trong dự án, đề xuất giải pháp kỹ thuật cho các vấn đề phát sinh;\n- Thực hiện thiết kế, lập trình, kiểm thử và viết tài liệu theo yêu cầu hệ thống để đảm bảo chất lượng mã nguồn và đáp ứng các mốc phát hành sản phẩm;\n- Sửa lỗi, bảo trì và nâng cấp hệ thống theo yêu cầu.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành có liên quan\n- Có từ 3 - 5 năm kinh nghiệm làm việc với NodeJS/NextJS;\n- Thành thạo công nghệ ReactJS và NodeJS;\n- Vững kiến thức JavaScript, TypeScript và HTML/CSS; hiểu rõ các nguyên tắc cơ bản, nâng cao và các thực hành tốt nhất trong phát triển ứng dụng phía server và client;\n- Kiến thức tốt về thuật toán và cấu trúc dữ liệu;\n- Sẵn sàng tìm hiểu và xử lý các vấn đề liên quan đến hiệu năng, lỗi đa luồng và tối ưu hệ thống.\n\nQuyền lợi:\n- Mức lương (gross): lên đến 30 triệu hoặc lên đến 40 triệu đối với level Senior (thoả thuận khi phỏng vấn);\n- Thưởng tháng 13, thưởng thâm niên, thưởng hàng quý, thưởng chia lợi nhuận;\n- 12 ngày nghỉ phép năm;\n- Xét tăng lương theo hiệu suất vào tháng 6 và tháng 12;\n- Thưởng các dịp lễ như 30/4 - 1/5, 2/9, Tết Dương lịch,...;\n- Tổ chức sinh nhật, tặng quà vào các dịp như Tết Nguyên Đán, Quốc tế Phụ nữ (8/3, 20/10), Trung Thu, Tết Thiếu nhi (1/6), và nhiều dịp khác;\n- Miễn phí trà, đồ ăn nhẹ, cà phê tại văn phòng; hỗ trợ phí gửi xe;\n- Được trang bị đầy đủ thiết bị và công cụ phục vụ công việc hiệu quả;\n- Tham gia vào các hoạt động sôi nổi của công ty: tiệc hàng quý, du lịch thường niên, team building/cắm trại hàng quý, tiệc tất niên và nhiều hoạt động khác.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa MD Complex, 68 Nguyễn Cơ Thạch, Mỹ Đình 1, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2203, 1138, 2, 'Kỹ Thuật Viên Vận Hành Máy CNC Thu Nhập 8.000.000 - 13.000.000', 'Vận hành máy CNC phục vụ sản xuất các sản phẩm nội thất gỗ theo kế hoạch.\nLập trình, cài đặt và điều chỉnh thông số máy CNC theo yêu cầu bản vẽ kỹ thuật.\nKiểm tra và giám sát chất lượng sản phẩm sau khi gia công, đảm bảo đúng tiêu chuẩn.\nThực hiện bảo trì, bảo dưỡng máy móc định kỳ để đảm bảo hoạt động ổn định.\nPhối hợp với bộ phận thiết kế/kỹ thuật nhằm tối ưu hóa quy trình sản xuất.\nTuân thủ nghiêm ngặt các quy định về an toàn lao động trong quá trình làm việc.\n\nYêu cầu ứng viên:\nCó kinh nghiệm làm việc trong lĩnh vực cơ khí, cơ điện tử, hoặc ngành chế biến gỗ.\nTối thiểu 1 năm kinh nghiệm vận hành máy CNC trong sản xuất công nghiệp.\nĐọc hiểu bản vẽ kỹ thuật cơ bản (2D, 3D).\nHiểu biết về vật liệu gỗ, các dòng máy CNC và công nghệ gia công gỗ.\nCó tinh thần trách nhiệm, kỹ luật cao và khả năng làm việc nhóm tốt.\n\nQuyền lợi:\nMức lương: 8-13tr, Thỏa thuận theo năng lực và kinh nghiệm.\nĐược tham gia đầy đủ BHXH, BHYT, BHTN theo quy định pháp luật.\nThưởng lễ, Tết, và các chế độ phúc lợi khác theo quy định công ty.\nĐược đào tạo nâng cao tay nghề và cập nhật công nghệ mới.\nMôi trường làm việc chuyên nghiệp, thân thiện, cơ hội phát triển rõ ràng.\n\nĐịa điểm làm việc:\nĐịa điểm làm việc tại nhà máy: CN11 - KCN Nguyên Khê, Đông Anh\nPhỏng vấn tại nhà máy hoặc văn phòng: số 4 Dịch Vọng Hậu- Cầu GIấy - HN\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2204, 1139, 2, 'Flutter Developer (Từ 06 Tháng Kinh Nghiệm) - Offer Upto $1000', 'Mô tả công việc:\n- Phát triển ứng dụng di động sử dụng Flutter theo phân sự phân công của Team Leader.\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động.\n- Phát triển các ứng dụng một cách linh hoạt, có cấu trúc tốt, mã nguồn và thư viện có thể tái sử dụng trong tương lai.\n- Tối ưu hoá hiệu suất và đảm bảo ứng dụng tương thích trên cả Android và iOS.\n- Lập trình các module tính năng theo bản phân tích thiết kế.\n\nYêu cầu ứng viên:\n- Có từ 6 tháng kinh nghiệm phát triển ứng dụng bằng Flutter.\n- Thành thạo ít nhất một trong các state management (Provider. Bloc, GetX,...).\n- Hiểu biết tốt về các UI components & customization/animation, thiết kế giao diện người dùng cho nhiều loại thiết bị có màn hình khác nhau.\n- Có tư duy logic tốt, có khả năng phân tích và giải quyết vấn đề.\n- Hiểu biết Design Pattern, SOLID.\n- Có kiến thức tốt về Data Structures & Algorithm.\n- Có kinh nghiệm tối ưu performance, memory cho ứng dụng.\n- Có kinh nghiệm tích hợp Firebase, Admob, Subscription và In-App Purchases là một lợi thế.\n- Ưu tiên ứng viên có kinh nghiệm về native (Swift hoặc Kotlin/ Java).\n- Có kỹ năng làm việc nhóm, làm việc độc lập, có khả năng tự học hỏi và cập nhật các công nghệ mới.\n- Có đam mê phát triển sản phẩm product.\n\nQuyền lợi:\n- Offer upto 1000$ + trợ cấp ăn trưa + trợ cấp đi lại.\n- Tháng lương 13.\n- Thưởng Tết Âm Lịch từ 01 - 05 tháng lương.\n- Thưởng các ngày lễ: 30/04, 01/05, 02/09, Tết Dương, 08/03, 20/10,... áp dụng cho tất cả nhân sự (chính thức, thử việc, thực tập sinh).\n- Thử việc tối đa 02 tháng 100% lương, có phép trong thời gian thử việc.\n- Được cung cấp hoàn toàn trang thiết bị phù hợp với vị trí công việc.\n- Review hiệu suất & lương thưởng định kỳ 2 lần/năm (tháng 1 & tháng 7).\n- Bảo hiểm, nghỉ lễ, phúc lợi đầy đủ theo quy định pháp luật, được cung cấp các gói khám sức khỏe định kỳ khi trở thành nhân viên chính thức.\n- Startup năng động, tinh thần sáng tạo và nhiệt huyết.\n- Được đào tạo 1-1 bởi leader giàu kinh nghiệm từng làm tại công ty Tech lớn.\n- Cơ hội phát triển và tham gia vào các sản phẩm có hàng triệu - chục triệu người dùng trên toàn cầu.\n- Miễn phí trà, cafe, nước ngọt tại Pantry.\n- Có cơ hội tham gia rất nhiều các CLB do công ty tổ chức và tài trợ: Bóng đá, bóng bàn, Bi-a, Board game, Chạy bộ, cầu lông....\n- Khu vực vui chơi với Bàn Bi-a siêu xịn, bàn bóng bàn, PS4 và nhiều bộ môn hấp dẫn khác.\n- Team building/du lịch mỗi 3 tháng – Công ty tài trợ 100% chi phí.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4 Tòa Garden Hill, số 99 Trần Bình, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n- Thứ 7 (từ 08:30 đến 12:00).\n- 2 buổi sáng Thứ 7 cách tuần: 8h30 - 12h00.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2205, 1140, 2, 'Nhân Viên Kỹ Thuật Ra File CNC Gỗ Công Nghiệp', 'Mô tả công việc\n• Tiếp nhận bản vẽ thiết kế, triển khai bản vẽ chi tiết 2D/3D từ bộ phận thiết kế.\n• Vẽ file cắt CNC (gỗ) bằng phần mềm Sketchup.\n• Thực hiện bóc tách khối lượng, lập dự trù vật tư.\n• Chịu trách nhiệm giao file cho nhân viên chạy CNC (file cắt, bản vẽ kỹ thuật, tem dán...)\n• Kiểm tra chất lượng sản phẩm cắt CNC.\n• Thực hiện các yêu cầu khác có liên quan do cấp trên giao\nYêu cầu ứng viên\n• Sử dụng thành thạo phần mềm thiết kế Sketchup, Autocad,...nắm vững kết cấu các hạng mục nội thất chính như tủ - kệ trưng bày...\n• Có khả năng đọc hiểu bản vẽ.\n• Cẩn thận, nghiêm túc và có trách nhiệm với công việc.\n• Có kinh nghiệm ít nhất 2 năm tại các công ty sản xuất đồ nội thất.\nQuyền lợi\n• Chế độ BHXH, BHTN, BHYT đầy đủ theo quy định pháp luật.\n• Được học hỏi nâng cao trình độ chuyên môn.\n• Nghỉ lễ, tết theo quy định pháp luật.\n• Thưởng lễ, tết và các chế độ phúc lợi khác.\n• Có công tác phí.\n• Tăng lương theo năng lực.\nĐịa điểm làm việc\n• Bắc Ninh: Tầng 2 Chung cư Cường Thịnh, Lê Thái Tổ, TP Bắc Ninh.\nThời gian làm việc\n• Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\nCách thức ứng tuyển\n• Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2206, 1141, 2, 'Flutter Developer', 'Mô tả công việc\n- Thiết kế, phát triển và tối ưu hiệu suất ứng dụng trên nền tảng Android / iOS. Chủ yếu là Flutter.\n- Cùng team lên ý tưởng và giải pháp cho các tính năng mới của ứng dụng ;\n- Sửa lỗi và cải thiện tính năng, hiệu suất sản phẩm ;\n- Phối hợp với các thành viên trong team để vận hành và tối ưu hoá sản phẩm ;\n- Nghiên cứu công nghệ mới, phù hợp với chiến lược sản phẩm ;\n- Chi tiết công việc sẽ trao đổi thêm khi phỏng vấn.\n\nYêu cầu ứng viên\n- Thành thạo lập trình hướng đối tượng (OOP), cấu trúc dữ liệu, giải thuật và thiết kế giao diện người dùng (UI/UX).\n- Có ít nhất 2 năm kinh nghiệm làm việc với API dạng RESTful.\n- Sử dụng thành thạo hệ thống quản lý mã nguồn Git.\n- Kỹ năng phân tích, tư duy giải quyết vấn đề tốt.\n- Tinh thần trách nhiệm cao, chủ động và khả năng làm việc nhóm hiệu quả.\n- Có khả năng tự học hỏi, cập nhật công nghệ mới và kỷ luật bản thân.\n\nQuyền lợi\n- Mức lương: Up to 20 triệu/tháng, tùy năng lực.\n- Làm việc cùng team kỹ sư trẻ, tài năng, đam mê công nghệ.\n- Cơ hội tiếp cận công nghệ mới.\n- Chế độ đầy đủ: BHXH, sinh nhật, thưởng Tết (tháng lương thứ 13), du lịch hàng năm.\n- Tham gia hoạt động thể thao như bóng đá hàng tuần.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 3, Tòa Tháp Đông, Chung cư Học viện Quốc Phòng, Xuân La, Tây Hồ\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n- Nghỉ thứ 7 cách tuần.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2207, 1142, 2, 'Fresher .NET (VB.NET)', '• Developing projects for Japanese, English and domestic customers\n• Creating Backend components with C#, Net core, MVC (Frontend: ReactJS, Backend: VB.NET/C#)\n• Integrating data storage solutions\n• Maintaining and troubleshooting existing web applications\n• Optimize our web applications for maximum speed\n• Participating in all works in the software development process, including requirements inquiry, analysis, design, research new technology ...\n• Contributing ideas to leaders and customers to improve products or work processes\n• Solving issues, executing work according to plan, report work progress for direct management (PM)\n• Detailed information about the project\'s profession will be discussed in the interview.\n\n• Bachelor’s degree in Computer Science Engineering or other related courses.\n• At least 6 months experience working with .Net, C#\n• Experience working with SQL databases, ability to write complex queries and optimize them\n• Proficiency with code versioning tools including Git, Github, SVN\n• Strong knowledge of front-end technologies including HTML5, JavaScript, and CSS3\n• Good problem-solving skills\n• Willing to work hard and learn new technologies\n• Having Japanese (equivalent to N3) or English is an advantage.\n\n• Competitive salary package and specific benefits. You\'ll get a bonus of a half month salary If you are on board before October 1st\n• TET bonus from up to 4-month salary according to seniority, work results, and business situation of the company.\n• The company pays (32%) the costs of social insurance, health insurance, and unemployment insurance for its employees.\n• Performance review twice a year\n• Annual holiday: 12 annual leave and Corporate Birthday 11/27\n• Working in a dynamic and professional environment with many promotion opportunities.\n• Receive benefits according to seniority\n• Being trained in foreign languages, sponsored to learn certificates to improve professional skills and soft skills.\n• Lots of opportunities to go to Onsite at SPLUS JAPAN (for staff with Japanese proficiency from N3 and above)\n• Sports activities: Football\n• Annual company trip, team building, birthdays for employees in the month, and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas ...).\n• Time working: Monday – Friday (9:00 – 18:00).\n\n- Hồ Chí Minh: Tòa nhà HaDo Airport, 2 Hồng Hà, phường 2, Tân Bình\n\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2208, 1143, 2, 'Lập Trình Viên ReactJS ( 2 Năm Kinh Nghiệm)', 'Mô tả công việc:\n- Phát triển và Xây dựng các hệ thống web sử dụng ReactJS.\n- Tối ưu hóa hiệu suất và đảm bảo tính tương thích trên các thiết bị và trình duyệt khác nhau\n- Tham gia vào quá trình phân tích yêu cầu, thiết kế và lập kế hoạch dự án.\n- Làm việc với các thành viên khác trong nhóm phát triển để hoàn thành các dự án đúng tiến độ.\n- Cập nhật kiến thức và kỹ năng về các công nghệ mới và xu hướng trong ngành.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Ít nhất 2 năm kinh nghiệm làm việc với ReactJS.\n- Hiểu biết sâu về TypeScript, JavaScript, HTML5, CSS3.\n- Kinh nghiệm làm việc với Redux và Redux Toolkit.\n- Kiến thức về RESTful API và WebSocket.\n- Kỹ năng làm việc với Git và các công cụ quản lý mã nguồn.\n- Khả năng làm việc độc lập và trong môi trường nhóm.\n- Kỹ năng giao tiếp tốt, chủ động và tinh thần trách nhiệm cao.\n- Có tư duy phân tích tốt để cùng team giải quyết các vấn đề trong công việc.\n\nQuyền lợi:\n- Mức lương từ: 15-30 triệu/tháng tùy theo năng lực\n- Thưởng dự án theo hiệu quả công việc.\n- Môi trường làm việc trẻ trung, chuyên nghiệp và sáng tạo.\n- Cơ hội tham gia vào các dự án lớn của công ty trong lĩnh vực Elearning.\n- Chế độ bảo hiểm và các phúc lợi khác theo quy định của công ty.\n\nĐịa điểm làm việc:\n- Hà Nội: Khu văn phòng Trường mầm non Thành Đông, khu đô thị mới Phùng Khoang, phường Trung Văn, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2209, 1144, 2, 'Frontend Leader', '- Thiết kế kiến trúc frontend sử dụng NextJS, Typescript, xây dựng theo component-based và tách biệt UI/logic theo chuẩn industry.\n- Quản lý tiến độ, phân công task, theo dõi và hỗ trợ team frontend xử lý task và bugs.\n- Phát triển UI sử dụng Tailwind CSS/Ant Design, đảm bảo tính tái sử dụng và maintainable.\n- Review source code, đảm bảo chuẩn coding convention và performance (SSR/CSR, lazy loading, hydration).\n- Tối ưu SEO, performance và trải nghiệm người dùng.\n- Tích hợp frontend với các API backend qua RESTful API, đảm bảo bảo mật với JWT, API key, xử lý timeout và fallback.\n- Hướng dẫn frontend developers về kiến trúc NextJS, phân tách logic UI/state, tích hợp hiệu quả với backend và external services.\n- Phối hợp với team backend để đảm bảo tính nhất quán của UI/UX và logic nghiệp vụ.\n- Đề xuất giải pháp UI nâng cao để cải thiện hiệu suất và khả năng mở rộng, sử dụng caching strategy phù hợp.\n\nYêu cầu ứng viên\n------------------------------------\nKỹ năng chuyên môn\n- 4+ năm kinh nghiệm về ReactJS, TypeScript, và Next.js.\n- Hiểu rõ về bất đồng bộ trong JavaScript, React Hooks, và đặc biệt là các phương pháp tốt nhất khi sử dụng Redux, quản lý Store, State, Context API, Redux Middleware và tối ưu hóa hiệu suất.\n- Thành thạo kỹ thuật tối ưu SEO cho SPA/SSR (Server-Side Rendering, Head management...).\n- Có kinh nghiệm nâng cao hiệu suất và trải nghiệm người dùng: lazy loading, code splitting, UI responsiveness.\n- Hiểu rõ các nguyên tắc bảo mật phía frontend: XSS, CSRF, input sanitization...\n- Kỹ năng clean code, tối ưu UI/UX, và phát triển component theo hướng tái sử dụng.\n\nKỹ năng quản lý\n- 2+ năm kinh nghiệm trong vai trò team lead hoặc technical lead frontend.\n- Khả năng định hướng kiến trúc frontend, đảm bảo khả năng mở rộng và tích hợp hiệu quả với backend qua REST API / GraphQL.\n- Có kinh nghiệm review code, kiểm soát chất lượng source code và áp dụng tiêu chuẩn coding.\n- Khả năng giao tiếp và phối hợp hiệu quả với UI/UX, backend và quản lý sản phẩm.\n- Kỹ năng giải quyết vấn đề tốt.\n\nQuyền lợi\n------------------------------------\n– Thu nhập upto 45M\n– Thử việc 2 tháng hưởng 100% lương\n– Tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật lao động\n– Tham gia bảo hiểm VBI\n– Review lương 2 lần/năm\n– Lương tháng 13, thưởng lễ, Tết, Tang lễ, Sinh nhật,...\n– Hỗ trợ chi phí thi chứng chỉ theo quy định của công ty\n– Phụ cấp khi nhận chứng chỉ\n– Phụ cấp gửi xe\n– Phụ cấp thâm niên, thưởng dự án xuất sắc\n– Du lịch hằng năm theo chính sách của công ty\n– Khám sức khỏe định kỳ hằng năm\n– Cơ hội thăng tiến rõ ràng\n– Cơ hội làm việc tại các nước đối tác: Nhật Bản, Hàn Quốc, Singapore, Úc\n\nĐịa điểm làm việc\n------------------------------------\n- Hồ Chí Minh: 10F Mekong Tower, 235 Cong Hoa, Ward 13, Tân Bình\n\nThời gian làm việc\n------------------------------------\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n------------------------------------\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2210, 1128, 2, 'C++ Developer (Junior)', 'Mô tả công việc\n- Tham gia vào phát triển các dự án với vai trò junior hoặc middle từ giai đoạn Basic Design, Detail Design, Development, Release.\n- Thiết kế kiến trúc tổng thể hệ thống, Database, phát triển các chức năng đồng thời support các thành viên trong team.\n- Tham gia vs PM lập kế hoạch và hỗ trợ quản lý dự án.\n- Làm các công việc khác theo sự phân công của quản lý( Research new Technologies, Support team…)\n\nYêu cầu ứng viên\n- Có kinh nghiệm làm việc với C++ trong các dự án phát triển phần mềm. Ưu tiên có kinh nghiệm với Visual C++ (VC++).\n- Có kiến thức nền tảng tốt về OOP, Web Development, DBMS, ORM, Design Pattern.\n- Có kiến thức nền tảng tốt OOP và các nguyên tắc thiết kế phần mềm, Design Pattern.\n- Kỹ năng đọc hiểu và phân tích tài liệu kỹ thuật tốt, đặc biệt là các tài liệu liên quan đến hệ thống phần mềm.\n- Kỹ năng giao tiếp và làm việc nhóm tốt, có khả năng phối hợp với các bộ phận khác.\n  Ưu tiên:\n- Biết tiếng nhật hoặc đã từng làm trong các công ty outsourcing cho Nhật.\n- Tư duy logic tốt\n  Yêu cầu khác:\n- Có tinh thần trách nhiệm cao trong công việc;\n- Có khả năng làm việc độc lập và làm việc theo nhóm;\n- Có khả năng sử dụng tiếng Anh/tiếng Nhật là lợi thế.\n\nQuyền lợi\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe cao cấp 24/24;\n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện);\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày;\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành.\n- Miễn phí đồ uống tại khu ăn uống của công ty;\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan;\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLB Dance...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm….\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín.\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa\n\nĐịa điểm làm việc\n - Hà Nội: Tầng 4 CT1, Tòa C14 Bắc Hà, Đường Tố Hữu, Phường Trung Văn, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2211, 1145, 2, 'Nhân Viên Lập Trình Ứng Dụng', 'Mô tả công việc\nCó kinh nghiệm phát triển và triển khai ứng dụng trên nền tảng .NET.\nCó kiến thức về Build cross-platform: Electronjs.\nBiết ứng dụng AI trong lĩnh vực lập trình ứng dụng.\nCó kinh nghiệm hỗ trợ/ tư vấn giải pháp phần mềm cho đơn vị/tổ chức.\nBiết sử dụng sử dụng công cụ DevExpress, Material Design UI, WinUI, WPF UI.\nĐã từng tham gia phát triển phần mềm trong lĩnh vực giáo dục là một lợi thế.\n\nYêu cầu ứng viên\nỨng viên có từ 2 năm kinh nghiệm trở lên.\nTốt nghiệp Đại học trở lên thuộc chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm, Khoa học máy tính hoặc chuyên ngành có liên quan.\n\nQuyền lợi\nLương theo thỏa thuận.\nĐược ký hợp đồng chính thức sau thời gian thử việc và có chế độ tham gia BHXH, BHYT, BHTN… đầy đủ.\nĐược thưởng dịp Lễ, Tết.\n\nĐịa điểm làm việc\n- Cần Thơ: 168, Nguyễn Văn Cừ (nối dài), Ninh Kiều.\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 07:30 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cần Thơ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2212, 1146, 2, 'Senior Back-End Developer - Lĩnh Vực Edtech - Mức Lương Up To 40M', 'Chúng tôi đang tìm kiếm ứng viên nhiệt huyết và đam mê công việc để gia nhập đội ngũ nhân viên trẻ tuổi và tài năng của  công ty FSEL với yêu cầu như sau:\nTham gia phát triển các sản phẩm phục vụ cho hàng trăm nghìn khách hàng về các dịch vụ học trực tuyến E-learning.\nXây dựng và tối ưu sản phẩm đáp ứng hàng trăm nghìn người sử dụng đồng thời.\nTham gia nghiên cứu và ứng dụng các công nghệ mới vào sản phẩm: Big Data, …\nPhối hợp cùng đội ngũ BA phân tích, thiết kế, đưa ra giải pháp để phát triển phần mềm đáp ứng đúng, đủ, tiện các yêu cầu của người dùng cuối.\nTham gia tất cả các giai đoạn phát triển phần mềm được yêu cầu từ lập kế hoạch, ước tính, thiết kế và phát triển việc thực hiện.\nTham gia vào các quy trình Agile như Scrum hoặc Kanban.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật phần mềm hoặc các ngành liên quan.\nCó từ 4 năm kinh nghiệm lập trình thực tế với .NET, đặc biệt là .NET Core hoặc ASP.NET MVC/Web API.\nThành thạo C#, .NET Framework, .NET Core, ASP.NET (Core), MVC, Web API, Entity Framework (Core) và SQL Server.\nCó kinh nghiệm thiết kế phần mềm và xây dựng kiến trúc hệ thống.\nLàm việc tốt với các hệ quản trị cơ sở dữ liệu SQL/NoSQL như: MS SQL, MySQL, PostgreSQL, MongoDB.\nƯu tiên ứng viên quen thuộc với các công nghệ front-end như React, Angular hoặc VueJS.\nHiểu biết vững về lập trình hướng đối tượng (OOP), các mẫu thiết kế (design patterns), nguyên lý SOLID, và kiến trúc phần mềm sạch (clean architecture).\nCó kinh nghiệm làm việc với nền tảng cloud như Azure hoặc AWS.\nHiểu và áp dụng được quy trình CI/CD, DevOps, và công nghệ container như Docker, Kubernetes.\nCó kinh nghiệm làm việc trong môi trường phát triển phần mềm theo mô hình Agile/Scrum.\nKỹ năng giải quyết vấn đề và giao tiếp tốt.\n\nQuyền lợi:\nMức lương (gross): up to 40 triệu/tháng.\nThưởng sinh nhật, thưởng các dịp Lễ, Tết trong năm.\nChế độ BHXH, BHYT, BHTN đầy đủ ngay sau khi ký HĐ chính thức.\nKhám sức khoẻ định kỳ hàng năm.\nTrang bị máy tính hiện đại phục vụ công việc.\nQuỹ Team Building lên tới 2.400.000 VNĐ/người/năm.\nDu lịch nghỉ dưỡng hàng năm.\nTrà chiều với bánh, hoa quả và đồ ăn vặt miễn phí hàng tuần.\nCơ hội tiếp cận với các doanh nghiệp, dự án lớn, xu hướng công nghệ và nền tảng mới nhất.\nĐược tham gia các lớp đào tạo, khóa học chuyên môn để phát triển kỹ năng.\nLàm việc trong môi trường chuyên nghiệp, năng động, trẻ trung & trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc.\nHọc tiếng Anh hoàn toàn miễn phí & ưu đãi học phí cho người thân.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2213, 1147, 2, 'Middle Java Software Engineer', 'We are seeking a skilled Middle Java Software Engineer to join our team for a healthcare project based in the US. The successful candidate will contribute to the development of scalable software solutions using Java technologies, with a focus on system design and cloud-based architectures. This role requires technical expertise and effective collaboration within the team to deliver high-quality applications that meet the standards of the US healthcare industry.\n\nKey Responsibilities\n\nDesign, develop, and maintain applications using Java 8+ and Spring Boot, ensuring scalability through robust system architecture for a US-based healthcare project.\nBuild and implement RESTful APIs within a microservices framework to support healthcare-related functionalities.\nUtilize containerization technologies such as Docker and Kubernetes (K8S) for deployment and orchestration.\nWork with SQL (e.g., MySQL) and NoSQL (e.g., MongoDB) databases to optimize data management, ensuring compliance with healthcare data standards.\nIntegrate messaging systems like Kafka to support distributed systems in a healthcare context.\nApply system design principles to architect reliable and maintainable solutions tailored to healthcare requirements.\nLeverage AWS services (e.g., S3, RDS, CloudWatch) for cloud-based application development and deployment, ensuring secure and efficient handling of sensitive healthcare data.\nUse Git for version control and collaborative development within the team.\nParticipate in Agile/Scrum processes, including code reviews, to ensure team alignment and quality deliverables for the healthcare project.\nCommunicate effectively with team members to foster collaboration and project success.\n\nRequired Skills and Qualifications\n\nAt least 3 years of professional experience in software development with Java.\nStrong proficiency in Java 8+, Spring Boot, and Spring Framework.\nExperience with microservices architecture and RESTful API development.\nKnowledge of system design and architecture principles for scalable applications.\nFamiliarity with containerization (Docker) and orchestration (Kubernetes).\nProficiency in SQL and NoSQL databases (e.g., MySQL, MongoDB).\nExperience with messaging systems like Kafka and distributed systems.\nExperience in AWS (e.g., S3, RDS, CloudWatch) for cloud-based solutions.\nProficiency in Git for version control.\nAbility to work effectively within an Agile/Scrum environment.\n\nPreferred Qualifications\n\nStrong English communication skills, both verbal and written, for effective team collaboration, especially given the project’s US-based context.\nFamiliarity with CI/CD tools such as Jenkins or GitLab CI.\nExposure to caching mechanisms (e.g., Redis).\nExperience or familiarity with healthcare industry standards and regulations (e.g., HIPAA compliance) is a plus.\n\nJoin a dedicated team working on a meaningful US-based healthcare project, where your contributions will directly impact the improvement of healthcare services. We offer a collaborative and innovative work environment that values your growth and well-being. You will have the opportunity to work with cutting-edge technologies, including cloud platforms and modern Java frameworks, while gaining exposure to the US healthcare sector. We provide competitive compensation, comprehensive health benefits, and flexible working arrangements to support a healthy work-life balance. Additionally, our company is committed to continuous learning, offering access to training programs, certifications, and mentorship opportunities to help you advance your career. Be part of a team that values diversity, fosters creativity, and celebrates success together.\n\n- Địa điểm làm việc: Hồ Chí Minh: 123 đường N3B, Global City, Quận 2\n- Thời gian làm việc: Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2214, 1148, 2, 'Fullstack Engineer (Typescipt/English Fluency)', 'At Sun Asterisk, we build cutting-edge, high-performance systems to tackle complex challenges. As a developer, you will:\n\n- Develop frontend and backend features using React, Next.js, and tRPC.\n- Build responsive UI components and seamless user experiences for AI tool creation.\n- Design and implement backend business logic and API layers with tRPC.\n- Integrate and optimize database queries using Prisma and Kysely.\n- Collaborate with Product and AI teams to ensure feature completeness and performance. Ensure quality via code reviews, testing (unit/integration), and observability.\n\nExperience Requirements\nMandatory Skills:\n\n- 3+ years of experience as a Full Stack or Frontend/Backend Engineer.\n- Proficiency with TypeScript and React.\n- Experience building apps with Next.js (preferably using App Router).\n- Solid backend experience with tRPC or similar RPC/GraphQL APIs.\n- Familiarity with PostgreSQL and query performance optimization.\n- Experience using Prisma, Kysely, or any modern query builders.\n- Good communication skills, team-oriented, and comfortable in startup-paced environments.\n\nDesired Skills:\n\n- Familiarity with AI tools or LLM-powered platforms.\n- Experience with Neon PostgreSQL or serverless databases.\n- Experience with Tailwind CSS, Zod, Vercel, or PlanetScale.\n- Understanding of Edge Functions or Serverless API patterns.\n\nSkill requirements\n\n- Excellent English communication skills\n- Outstanding teamwork abilities\n- Proven ability to prioritize and allocate work\n- Sharp critical thinking and logical reasoning\n- Effective problem-solving skills\n\nAttitude Requirements\n\n- Customer-centric mindset\n- Adaptability to change\n- Commitment to continuous learning and growth.\n\nProfessional, open-minded, and creative environment:\n\n- Work with colleagues who embrace ideas to change the society\n- Respect different perspectives within a team\n- Strong learning culture that promotes individual development\n- The culture of taking risks to experience and thrive\n\nFocus on individual development:\n\n- Be consulted, accompanied, and supported in career development with the career path system (developing in expertise or management direction) that has been studied and tested for many years.\n- Be oriented for individual, group, and organizational goals\n- Be empowered\n- Be supported to define a 3-month or 6-month goal (Goal Define Support)\n- Get access to company Learning Hub online library with various courses provided by Udemy, LinkedIn,…\n\nSpecial care for employees:\n\n- Salary: Negotiable + competitive allowance (lunch, living allowance, beauty care, Japanese and IT certificates, etc.)\n- 13th-month salary bonus\n- Performance review: Twice/a year\n- Hybrid working policy; flexible check-in, check-out\n- Comprehensive health insurance Sun Care\n- Seniority Allowance\n- Women care allowance: Women’s physiological leave: 2.5 hours/month; Postpartum leave for female employees with under 1-year-old children: 1 hour/day\n- Policies supporting learning activities, knowledge sharing, and cultural exchange (Technology Seminar – Tech Expert, Club: Reading, Japanese, Music Club, …)\n- Annual company trip and quarterly team-building activities.\n\n- Hà Nội: Tầng 13, Keangnam Landmark Tower 72, Nam Từ Liêm\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2215, 1149, 2, 'React Native Developer', 'Mô tả công việc:\n- Tham gia phát triển và tối ưu hóa ứng dụng mobile cross-platform (iOS & Android) bằng React Native.\n- Tham gia xây dựng kiến trúc, tổ chức mã nguồn và thiết kế module phù hợp với quy mô sản phẩm.\n- Hợp tác với đội ngũ thiết kế (UI/UX) để biến bản thiết kế thành sản phẩm thực tế mượt mà, trực quan.\n- Tích hợp API, làm việc chặt chẽ với backend để xử lý dữ liệu hiệu quả và đồng bộ.\n- Viết mã sạch, dễ bảo trì, có khả năng tái sử dụng và viết test khi cần thiết.\n- Tham gia vào các buổi họp sprint, đánh giá và cải tiến quy trình làm việc.\n- Theo dõi lỗi sản phẩm, xử lý phản hồi từ người dùng và hỗ trợ bảo trì ứng dụng.\n\nYêu cầu ứng viên:\n- CÓ TỪ 1 ĐẾN 3 NĂM KINH NGHIỆM LÀM VIỆC VỚI REACT NATIVE.\n- Đã tốt nghiệp hoặc đang chờ bằng cao đẳng/đại học.\n- Thành thạo JavaScript (ES6+), nắm rõ React Hooks, Context API.\n- Có kinh nghiệm với Redux / Zustand / Recoil, hiểu nguyên tắc quản lý state hiệu quả.\n- Hiểu biết tốt về cấu trúc dự án mobile, quản lý dependencies, build tool (Metro, Gradle, Fastlane).\n- Đã từng tích hợp REST API, WebSocket, Firebase hoặc các dịch vụ bên thứ ba.\n- Biết deploy ứng dụng lên App Store và Google Play (là một lợi thế lớn).\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.\n- Chủ động trong công việc, có tư duy giải quyết vấn đề và trách nhiệm cao.\nĐiểm cộng nếu bạn có:\n- Kinh nghiệm với TypeScript, Expo, hoặc native module (Java/Kotlin, Swift).\n- Hiểu biết về CI/CD cho mobile app, Firebase Analytics, Crashlytics.\n- Kinh nghiệm A/B testing, performance monitoring, push notification, deep linking.\n- Có khả năng giao tiếp tiếng Anh là một lợi thế.\n\nQuyền lợi:\n- Mức lương:\n  - Đối với ứng viên có từ 1 đến 2 năm kinh nghiệm: 7 - 13 triệu.\n  - Đối với ứng viên có từ 2 đến 3 năm kinh nghiệm: 14 - 18 triệu.\n- Đóng bảo hiểm y tế, bảo hiểm xã hội.\n- Review lương 1 năm/lần.\n- Thưởng các dịp lễ Tết, thưởng quý, thưởng thâm niên.\n- Quà tặng dịp sinh nhật cá nhân.\n- Cơ hội được học hỏi, làm việc với công nghệ mới.\n- Được làm việc trong một môi trường chuyên nghiệp với các đối tác nước ngoài.\n- Du lịch, teambuilding 2-3 lần/năm.\n- Hỗ trợ tham gia các khóa đào tạo nâng cao kiến thức và kỹ năng.\n\nĐịa điểm làm việc:\n- Hà Nội: Tây Mỗ, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:30 đến 18:30)\n- Đi làm 2 ngày thứ 7 trong tháng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2216, 1150, 2, 'Backend (Python, NodeJS)', 'Mô tả công việc:\n- Thiết kế và triển khai các hệ thống backend cho các ứng dụng AI.\n- Xây dựng APIs để hỗ trợ tương tác từ frontend với các hệ thống backend.\n- Tối ưu hiệu suất, tính bảo mật và khả năng mở rộng của hệ thống cho các trường hợp sử dụng có tải cao.\n- Tham gia vào quá trình phân tích yêu cầu và lập kế hoạch phát triển sản phẩm.\n\nYêu cầu ứng viên:\n- Có ít nhất 3 năm làm việc thực tế với Backend.\n- Thành thạo các ngôn ngữ Python (FastAPI) và Node.js.\n- Thành thạo về RESTful API và các giao thức.\n- Thành thạo về mô hình như MVC.\n- Có kiến thức về Docker, Linux terminal, Bash.\n- Có kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu như Mongodb, PostgreSQL.\n\nƯu tiên (yêu cầu không bắt buộc):\n- Hiểu biết về các kỹ thuật server push và giả server push.\n- Hiểu biết về reverse proxy, load balancer, zero downtime deployment.\n- Có kiến thức về LLM, RAG, Agent và có khả năng sử dụng CI/CD tools, Docker, Kubernetes là lợi thế.\n\nQuyền lợi:\n- Lương từ 17 triệu - 25 triệu.\n- Thưởng: thưởng năng suất, thưởng ngày lễ, tháng 13.\n- Review năng lực định kỳ 6 tháng/lần.\n- Trà, cà phê free, tham gia nghỉ mát, hoạt động team building của công ty.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Hỗ trợ tối đa các thiết bị phục vụ công việc.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 2, Sàn dịch vụ thương mại tòa nhà CT2D, VOV Mễ Trì, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n- Sáng thứ 7 (8h-12h).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2217, 1151, 2, 'Lập Trình Viên (Tiếng Nhật N3 Trở Lên)', 'Mô tả công việc:\n・Triển khai tính năng mới đúng theo lịch trình\n・Điều tra và sửa lỗi\n・Điều tra các câu hỏi nhận được từ user\n・Upload các chính sách định kỳ trong bảo trì\n\nYêu cầu ứng viên:\n・Nộp CV tiếng Nhật\n・Giao tiếp được tiếng Nhật (từ N3 trở lên)\n・Có thể lập trình bằng ngôn ngữ C hoặc C++\n・Biết thêm về Objective-C, Java, MySQL, HTML5, JavaScript, Unity là một điểm cộng\n・Có thể tự suy nghĩ và hành động độc lập\n・Có thể nỗ lực trong công việc với tinh thần trách nhiệm cao mà không từ bỏ giữa chừng\n・Người không bị bó buộc bởi những khái niệm cố định mà có thể linh hoạt đối ứng với bất kỳ thay đổi nào\n・Người có hứng thú đến nhiều lĩnh vực khác nhau và có thể chủ động tiếp thu kiến ​​thức và thông tin một cách tích cực\n\nQuyền lợi:\n1. Hàng năm sẽ chi trả lương thưởng vào trước Tết. Được quyết định dựa theo đánh giá và thành quả của cá nhân so với thành tích kinh doanh của công ty. Lấy cả mức độ đạt được mục tiêu và mức độ cống hiến của cá nhân làm đối tượng đánh giá và cung cấp môi trường mà mọi người có thể làm việc với động lực cao hơn.\n2. Ngày nghỉ căn cứ theo luật Lao động và kỳ nghỉ hè theo luật Công ty. Ở công ty chúng tôi, không chỉ có ngày nghỉ dựa theo luật Lao động như ma chay hiếu hỉ, nghỉ thai sản, nghỉ nuôi con nhỏ v.v. mà còn có kỳ nghỉ hè, nhằm thúc đẩy cách làm việc chú trọng tới sự cân bằng giữa công việc và cuộc sống để nhân viên có thể sảng khoái cả về thể chất lẫn tinh thần.\n3. Tham gia bảo hiểm xã hội, bảo hiểm y tế và khám sức khỏe mỗi năm một lần. Thực hiện khám sức khỏe mỗi năm một lần để hỗ trợ sức khỏe cho người lao động.\n4. Sự kiện: Tổ chức Tiệc tất niên vào cuối năm. Sẽ tổ chức Tiệc tất niên mỗi năm một lần để làm sâu sắc thêm sự gắn bó giữa các nhân viên.\n5. Chi trả trợ cấp chứng chỉ năng lực tiếng Nhật tùy theo bằng cấp JLPT・BJT.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 48 Huỳnh Mẫn Đạt, Phường 19, Bình Thạnh.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2218, 1152, 2, 'Senior Java Developer', 'Mô tả công việc:  - Xây dựng và phát triển sản phẩm mới, tập trung vào các giải pháp đột phá trong lĩnh vực Chính phủ, Doanh nghiệp, Ngân hàng.  - Hợp tác chặt chẽ với đội ngũ Phân tích nghiệp vụ (BA) để thiết kế và triển khai các tính năng tối ưu.  - Phát triển, bảo trì các tính năng mới và cải tiến sản phẩm hiện có.  - Viết code sạch, hiệu quả, dễ bảo trì theo tiêu chuẩn cao.  - Tham gia thảo luận, đề xuất và triển khai các giải pháp kỹ thuật.  - Nghiên cứu, ứng dụng các công nghệ mới, phối hợp hiệu quả với đội ngũ dự án.  Yêu cầu ứng viên:  - Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin hoặc có chứng chỉ tương đương.  - Thành thạo Java core, spring và lập trình hướng đối tượng (OOP).  - Ưu tiên ứng viên có thêm kinh nghiệm với Vuejs và các framework hiện đại.  - Am hiểu về lập trình, thuật toán và thiết kế hệ thống.  - Có kiến thức tốt về server, database và tối ưu hệ thống.  - Tinh thần trách nhiệm cao, làm việc được dưới áp lực lớn, cầu tiến, nhiệt huyết trong công việc.  - Kỹ năng tổ chức, làm việc nhóm tốt, chủ động giải quyết vấn đề.  - Có tư duy sáng tạo, khả năng tự học và tiếp cận tài liệu tiếng Anh hiệu quả.  Quyền lợi:  - Thời gian làm việc: Thứ 2 - Thứ 6 (8h30 – 18h00), có thể làm thêm 2 thứ 7/tháng khi cần.  - Mức lương hấp dẫn: 20.000.000 - 50.000.000 VND/tháng, cùng thưởng dự án, hiệu suất và lương tháng 13.  - Chế độ bảo hiểm và nghỉ phép đầy đủ theo Luật Lao động.  - Cơ hội làm việc onsite tại Nhật Bản, Hàn Quốc.  - Môi trường trẻ trung, năng động, lộ trình thăng tiến rõ ràng.  - Tham gia các hoạt động: team building, du lịch thường niên và các sự kiện ngoại khóa.  - Xét tăng lương 2 lần/năm dựa trên năng lực.  - Đào tạo chuyên sâu về kỹ thuật, tiếp cận công nghệ 4.0 tiên tiến.  - Lộ trình phát triển nghề nghiệp chuyên nghiệp, lâu dài và ổn định.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Nam Từ Liêm', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2219, 1153, 2, 'Thực Tập Sinh', 'Mô tả công việc\n- Thiết kế và phát triển hệ thống dữ liệu phù hợp với nhu cầu kinh doanh.\n- Phát triển các thuật toán để chuyển đổi dữ liệu thành thông tin hữu ích, có thể thực hiện được.\n- Xây dựng, thử nghiệm và bảo trì các pipeline cơ sở dữ liệu.\n- Lấy, thêm, sửa đổi dữ liệu theo yêu cầu.\n- Có kỹ năng phối hợp với quản lý để hiểu các mục tiêu của công ty.\n- Phát triển các phương pháp xác thực dữ liệu và các công cụ phân tích dữ liệu.\n- Đảm bảo tuân thủ các chính sách quản trị và bảo mật dữ liệu.\n- Sử dụng các công cụ Business Intelligence để visualize dữ liệu.\n\nYêu cầu ứng viên\n- Sinh viên cuối năm 3, năm 4 hoặc sinh viên mới tốt nghiệp của các trường có chuyên ngành CNTT, điện tử viễn thông\n- Có kinh nghiệm làm việc về các hệ thống Big data\n- Có kinh nghiệm coding SQL và một trong những ngôn ngữ sau NoSQL, Python, Java, R, and Scala\n- Có kinh nghiệm về thiết kế Data-warehouse, xử lý dữ liệu phân tán, xử lý dữ liệu lớn (Hadoop, Spark, MongoDB, and Kafka…)\n- Có kiến thức về Relational and non-relational databases.\n- Có kinh nghiệm build ETL hay các data pipeline (Airflow…).\n- Có kinh nghiệm viết các script tự động hoá các tác vụ bằng SQL hay Python …\n- Có kiến thức về Data Security\n- Tư duy tốt, có khả năng nghiên cứu, đánh giá và cập nhật công nghệ mới.\n- Tiếng anh đọc hiểu tài liệu Kỹ thuật.\n- Kỹ năng giao tiếp bằng lời nói và bằng văn bản tốt. Tự tin với kỹ năng làm việc nhóm.\n- Có kiến thức về Cloud (Azure, GCP, AWS) là một lợi thế.\n- Có kiến thức về Machine Learning là một lợi thế\n- Có thể sử dụng tiếng Anh, tiếng Nhật là một lợi thế\n- Có thể đi làm ít nhất 8 buổi hoặc 3 ngày full/tuần\n\nQuyền lợi\nChế độ làm việc:\n- Môi trường làm việc trẻ trung, với nhiều cộng sự tài năng.\n- Thời gian làm việc thoải mái: Thứ 2 – Thứ 6, flexible check in.\n- Có chế độ làm việc Remote cho các nhân viên xuất sắc.\n- Nghỉ phép đặc biệt cho nữ: 1 ngày/ tháng.\nQuyền lợi:\n- Mức lương cạnh tranh tương xứng với năng lực.( Đối với TTS sẽ có lương hỗ trợ và có thể trao đổi trong quá trình phỏng vấn)\n- Xét tăng lương/thăng chức 2 lần/năm (Tháng 06 và tháng 12)\n- Tổng thu nhập lên đến 14 tháng lương/năm.\n- Được tham gia BHXH, BHYT, BHTN và các chế độ theo quy định của luật Lao động.\n- Khám sức khỏe định kỳ 1 lần/năm tại các bệnh viện hàng đầu Việt Nam.\n- Cơ hội đi onsite tại Nhật Bản.\n- Tham gia Team Building, party, dã ngoại, thể thao, du lịch công ty.\nPhát triển năng lực cá nhân:\n- Văn hóa học tập mạnh mẽ và thúc đẩy phát triển.\n- Hỗ trợ các khoá học nâng cao nghiệp vụ chuyên môn trên Udemy, Coursera.\n- Tham gia các khóa đào tạo nội bộ về kiến thức chuyên môn, ngoại ngữ và các kỹ năng khác.\n- Hỗ trợ học phí, thưởng nóng khi đỗ các chứng chỉ IT, ngoại ngữ (Tiếng Nhật, Anh)\n- Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp.\n- Cơ hội tham gia nhiều dự án đa dạng với các khách hàng hàng đầu Nhật Bản.\n- Cơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 11, Tòa nhà Hồ Gươm Plaza, Trần Phú, Hà Đông\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2220, 1154, 2, 'Front-End Developer', 'Mô tả công việc:\n- Phát triển giao diện người dùng cho website thương mại điện tử, đảm bảo tính thân thiện và dễ sử dụng cho khách hàng B2B, B2C và B2B2C.\n- Xây dựng và duy trì mã nguồn cho phần front-end của trang web, sử dụng các framework hiện đại như React, Vue.js hoặc Angular.\n- Tối ưu hóa trải nghiệm người dùng (UI/UX), đảm bảo website hoạt động mượt mà trên nhiều thiết bị và trình duyệt khác nhau.\n- Thực hiện các báo cáo được giao.\n- Thực hiện những nhiệm vụ khác được giao bởi cấp Quản lý trực tiếp và Ban Giám đốc.\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng/đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính, hoặc các ngành liên quan.\n- Có 2-3 năm kinh nghiệm phát triển front-end với các framework React, Vue.js, hoặc Angular.\n- Thành thạo HTML, CSS, JavaScript và các công cụ build front-end như Webpack, Babel.\n- Hiểu biết về phát triển responsive và tối ưu hóa hiệu suất website.\n- Có kinh nghiệm làm việc với RESTful API và các công cụ kiểm thử front-end.\n- Kỹ năng giao tiếp tốt, có khả năng trình bày kết quả phân tích cho các bên liên quan.\n- Tin học văn phòng tốt.\n- Có khả năng ra quyết định và có khả năng phân tích tốt.\n- Có khả năng làm việc độc lập, làm việc theo nhóm và khả năng chịu áp lực cao.\n\nQuyền lợi:\n- Môi trường làm việc hiện đại, chuyên nghiệp, năng động, thân thiện, nhiều điều kiện học hỏi và thăng tiến.\n- Thời gian làm việc: 7h45 đến 16h45, từ thứ 2 - thứ 7.\n- Lương Thỏa thuận theo năng lực.\n- Lương tháng 13, lương thâm niên quy định Công ty.\n- Được hỗ trợ cơm trưa.\n- Thưởng chuyên cần 800.000 đồng/tháng.\n- Được hưởng các chế độ dành cho người lao động theo quy định pháp luật hiện hành (nghỉ phép, lễ, tết,...).\n- Được hưởng các chính sách phúc lợi theo quy định của Công ty: sinh nhật cá nhân, cưới hỏi, thăm hỏi ốm đau, du lịch nghỉ mát, khám sức khỏe định kỳ hằng năm.\n- Tham gia đầy đủ BHYT, BHXH, BHTN theo quy định và các quyền lợi khác theo quy định của luật lao động.\n- Công ty có chính sách đầu tư đào tạo và nâng cao kỹ năng nhân sự nắm giữ vị trí quản lý trong tương lai.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 200 Nguyễn Văn Bá, P. Trường Thọ, Thủ Đức.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 07:45 đến 16:45).\n- 7:45 - 16:45 Từ Thứ Hai - Thứ Bảy (Nghỉ 2 ngày Thứ 7/tháng).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2221, 1155, 2, 'Nhân Viên Kỹ Thuật', 'Mô tả công việc:\n- Vận hành, lập trình máy in 3D\n- Hỗ trợ khách hàng sử dụng máy\n- Hỗ trợ xử lý mẫu in 3D\n\nYêu cầu ứng viên:\n- Nam, từ 21 đến 30 tuổi\n- Tốt nghiệp trung cấp, cao đẳng, đại học các ngành cơ khí, kỹ thuật, điện.\n- 1 năm kinh nghiệm\n\nQuyền lợi:\n- Lương cố định từ 8 triệu đến 15 triệu tùy theo năng lực + hoa hồng lắp ráp máy hỗ trợ KH\n- Thu nhập từ 10-20 triệu (chăm chỉ siêng năng hỗ trợ ngoài cho KH)\n- Ăn ca: 25.000đ/xuất\n- Thưởng lễ, tết + Tháng lương thứ 13 + BHXH\n- Du lịch, nghỉ mát, tham gia các sự kiện nội bộ của công ty\n- Thời gian làm việc: Làm việc 8h/Ngày đến 17h, từ thứ 2 đến hết thứ 6 và 2 ngày thứ 7 trong tháng. Nghỉ lễ tết theo quy định của nhà nước.\n- Được đào tạo, tăng lương hàng năm theo năng lực.\n- Môi trường làm việc chuyên nghiệp, trẻ trung năng động, đồng nghiệp thân thiện, cơ hội thăng tiến ở vị trí nhóm trưởng, trưởng phòng đối với các ứng viên có năng lực và định hướng gắn bó.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2222, 1156, 2, 'React Native Developer Leader', 'Dẫn dắt và quản lý nhóm phát triển React Native để xây dựng các ứng dụng di động phục vụ khách hàng của Bank.\nThiết kế và phát triển kiến trúc ứng dụng React Native, đảm bảo hiệu suất, bảo mật và khả năng mở rộng.\nXây dựng và triển khai API, tích hợp với hệ thống ngân hàng và các đối tác bên ngoài.\nĐịnh hướng và tối ưu codebase, áp dụng Clean Architecture và các phương pháp phát triển hiện đại.\nĐảm bảo chất lượng mã nguồn thông qua code review, unit test và CI/CD.\nPhối hợp với các phòng ban liên quan như BA, PO, UI/UX để hiểu yêu cầu và đưa ra giải pháp phù hợp.\nHướng dẫn và đào tạo các thành viên trong nhóm, đảm bảo đội ngũ phát triển vững mạnh.\nBáo cáo tiến độ công việc và đề xuất giải pháp kỹ thuật với quản lý dự án\n\nYêu cầu ứng viên:\nTừ 4 năm kinh nghiệm làm việc với React Native.\nĐã có kinh nghiệm leader tối thiểu 1 năm.\nĐã tham gia phát triển ứng dụng Web/App (1-3 dự án lớn 100 Man-month): Mobile banking, Internet Banking, app giao dịch chứng khoán, trái phiếu, ví điện tử, ví doanh nghiệp, fintech, Marketing Automation, CRM, Ecommerce.\nKiến thức Công nghệ: Hiểu biết sâu sắc về các công nghệ phát triển ứng dụng, ngôn ngữ lập trình, cơ sở dữ liệu, và các công cụ phát triển phổ biến.\n\nQuyền lợi:\nLương khởi điểm từ 30M - 40M.\nLàm việc từ thứ 2 đến thứ 6.\nHưởng các chế độ, phúc lợi như: Thưởng lễ, thưởng Tết, lương tháng 13.\nTổ chức sinh nhật cho nhân viên.\nTổ chức teambuilding, du lịch hàng năm.\nKhám sức khỏe cho nhân viên hàng năm.\nReview lương hàng năm.\nBảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\nMôi trường làm việc trẻ và năng động, tôn trọng phát triển cá nhân, công bằng và luôn khuyến khích sáng tạo để tạo nên những giá trị "awesome" cho công ty & cho thế giới.\nCác thành viên công ty thân thiện cởi mở, chia sẻ, giúp đỡ nhau vượt qua mọi khó khăn trong công việc và đời sống.\n\nĐịa điểm làm việc:\nHồ Chí Minh: 45 Đ. Nguyễn Hữu Thọ, Phước Kiển, Nhà Bè.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2223, 1143, 2, 'Lập Trình Viên Java (3 Năm Kinh Nghiệm)', 'Mô tả công việc:\n- Tham gia xây dựng, phát triển và tối ưu hệ thống quản trị đại học, Hệ thống Elearning.\n- Tham gia vào toàn bộ vòng đời phát triển phần mềm: phân tích, thiết kế, lập trình, kiểm thử, triển khai và bảo trì.\n- Đề xuất, triển khai các giải pháp cải thiện hiệu năng hệ thống và nâng cao trải nghiệm người dùng (UI/UX).\n\nYêu cầu ứng viên:\n- Tối thiểu 3 năm kinh nghiệm làm việc với Java Core, Spring MVC hoặc Spring Boot.\n- Có kinh nghiệm thực tế với các công nghệ:\n  - Hibernate, RESTful API, Microservices\n  - Docker/Kubernetes, JUnit\n  - Cơ sở dữ liệu: MySQL, PostgreSQL, MongoDB\n  - JavaScript, HTML, CSS\n- Nắm vững lập trình hướng đối tượng (OOP), thành thạo design patterns, có tư duy hệ thống và khả năng giải quyết các bài toán kỹ thuật phức tạp.\n- Có tư duy tối ưu hệ thống: chú trọng đến hiệu năng, khả năng mở rộng và dễ bảo trì.\n- Tự chủ, chủ động, có tinh thần học hỏi và trách nhiệm cao trong công việc.\n\nQuyền lợi:\n- Mức lương từ: 20-35 triệu/tháng tùy theo năng lực\n- Thưởng performance, dự án\n- Có cơ hội thăng tiến và hỗ trợ học tập công nghệ mới.\n- Được hưởng đầy đủ các chế độ đãi ngộ với người lao động theo Luật lao động Việt Nam.\n- Chế độ đãi ngộ: Được tham gia BHXH và các hưởng các chế độ khác theo quy định của Nhà nước.\n- Thưởng tháng 13, du lịch hàng năm, có cơ hội thăng tiến.\n- Môi trường trẻ trung, năng động.\n\nĐịa điểm làm việc:\n- Hà Nội: Khu văn phòng, Trường mầm non Thành Đông, đường Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2224, 1157, 2, 'Team Leader', 'Mô tả công việc\nTeam Leadership:\nLead, manage, and mentor a team of Odoo developers and implementers. Provide guidance and support to team members in day-to-day tasks and career development. Foster a collaborative and productive team environment.\nProject Management:\nPlan and oversee the successful implementation of Odoo projects, ensuring they are delivered on time, within scope, and budget. Coordinate with cross-functional teams to define project requirements and deliverables. Maintain regular communication with stakeholders to ensure alignment with business goals.\nOdoo Development & Customization:\nLead the customization and configuration of Odoo modules to meet business requirements. Oversee the integration of Odoo with other systems or third-party applications. Troubleshoot and resolve any technical issues related to Odoo implementation.\nTraining & Documentation:\nDevelop and maintain training materials for end-users and new team members. Conduct training sessions to ensure users are proficient in Odoo functionality. Document Odoo system architecture, processes, and customizations.\nQuality Assurance & Continuous Improvement:\nMonitor the performance and functionality of Odoo and recommend improvements or enhancements. Ensure that all customizations and updates comply with best practices and quality standards. Stay up to date with new Odoo releases and evaluate their potential to improve business processes.\n\nYêu cầu ứng viên\nExperience:\nProven experience in leading an Odoo development team or managing ERP implementation projects (3+ years). In-depth knowledge of Odoo’s modules, including but not limited to Sales, Inventory, Accounting, CRM, and HR. Hands-on experience in Odoo customization, configuration, and module development.\nTechnical Skills:\nProficient in Python, XML, JavaScript, and PostgreSQL (commonly used in Odoo development). Experience with Odoo integration with other systems or external APIs. Strong understanding of object-oriented programming (OOP) principles.\nManagement Skills:\nStrong leadership, interpersonal, and communication skills. Ability to manage multiple projects and teams effectively. Strong problem-solving and critical-thinking abilities.\nEducational Qualifications:\nBachelor\'s degree in Computer Science, Information Technology, Business Administration, or a related field. Odoo certifications are a plus (Odoo Developer, Odoo Functional Consultant, etc.).\nAdditional Skills:\nFamiliarity with Agile/Scrum project management methodologies. Ability to work in a fast-paced environment and manage changing priorities.\n\nQuyền lợi\nSalary and Bonus:\nSalary: Negotiable based on ability.\nBonuses: 13th-month bonus. Bonus based on the company’s business performance. Insurance: Full insurance coverage based on the salary. Travel: The company organizes an annual trip for employees. Benefits: Free pantry. Internal events: team building, monthly birthdays, International Women\'s Day, International Men\'s Day, etc. Gifts for Mid-Autumn Festival, birthdays, etc. Career Opportunities: Opportunity for onsite work in Japan (short-term or long-term). Opportunity to share ideas, listen, and develop your career according to personal aspirations. Clear career advancement path. Working Hours: Monday to Friday, from 8:30 AM to 5:30 PM (flexible by 30 minutes).\n\nĐịa điểm làm việc\nHà Nội: Tầng 29, tòa nhà Handico Tower, KĐTM Mễ Trì Hạ, Đường Phạm Hùng, Phường Mễ Trì Thành phố Hà Nội, Việt Nam., Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2225, 1158, 2, 'Software Engineer – Data Engineering', 'Mô tả công việc\n- Develop and maintain database scripts, functions, stored procedures to support application development.\n- Assist Developers/Testers with database activities.\n- Process the client’s requests, feedback and fix the bugs.\n- Tune SQL queries and troubleshoot performance issues.\n- Attend all regular meetings of the assigned project.\n\nYêu cầu ứng viên\n- Has 1+ years of experience.\n- Good at English speaking/writing skills; can confidently discuss with clients about technical approaches or issues in detail;\n- Familiar with at least one of well-known RDBMS such as SQL Server, Oracle, PostgreSQL, MySQL\n- SQL Development – ability to write and troubleshoot SQL Code and design (stored procedures, functions, tables, views, triggers, indexes, constraints)\n- Knowledge of ETL, Data migration process\n- Ability to work independently with good self-motivation and minimal supervision.\n- Can handle the communication related to the work assignments.\n- Other nice-to-have skills: Knowledge of Data warehouse/Business Intelligence concept\n\nQuyền lợi\n- Performance bonus\n- Hybrid Working Model\n- Social – Health – Insurance paid fully\n- Healthcare: Annual health check-up, Premium Health Insurance\n- Annual leaves: 14 days\n- Clubs program: Football, Badminton, Swimming, Tennis, Rock, Yoga...\n- Training courses: Technical skills – Soft skills – English\n\nĐịa điểm làm việc\n- Hà Nội: HiTC Building, 239 Xuân Thủy, Cầu Giấy\n- Hồ Chí Minh: Etown Tower, 364 Cong Hoa Street, Ward 13, Tân Bình\n- Đà Nẵng: 36 Tran Quoc Toan Street, Hải Châu\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 2 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2226, 1159, 2, 'Fullstack Developer (Junior)', 'We are looking for web engineers to join our team with NodeJS and TypeScript  (JavaScript) experience with a strong background in API design, databases, performance,  scalability, security, SPA, etc. This position will work directly with customers (using English) in  Singapore and their partners in Europe to build a game marketplace &amp; Crypto Trading Platform  up from scratch.\nYou will:\nWorking with Product Owners to convert business requirements into technical designs. \nWorking and pair programming with other developers to build applications with Node.JS  and ReactJS. \nDesigning &amp; implementing back-end API using NodeJS. \nApplying proven technologies and best practices to level up your technical skills:  NestJS, Redux. \nLearning new languages and frameworks to improve yourself and stay current in an  ever-changing environment.\nYour Skills and Experience:\nExperience on ReactJS, NodeJS is a requirement.\nExperience in design patterns. \nExperience in MySQL, MongoDB, Redis administration. \nGood English communication (writing, reading, speaking, and listening) is a plus. \nKnowledge of solidity is a plus. \nKnowledge of cryptography and blockchain is a plus.\nWhy You\'ll Love Working Here:\nBuild World class product(s): We love to solve complex problems and learn new things.\nCollaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\nLearning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills. \nEnjoy competitive salary, bonus according to work performance\n13th Salary\nAssistance with operational tools and equipment.\nHealth insurance program up to 100 million VND/year for employees provided by PVI.\nAnnual health check-up from Medlatec Clinic\nParticipate in social insurance after becoming an official employee\nSalary review twice a year. It means we are pushing each other to be better everyday.\nFlexible working hours, freestyle attire\nPerks You\'ll Enjoy:\nWorking in a young, super talented, and supportive team environment\nTechnical, English certificate bonus \nDay-off: 12 days/year and Vietnam holidays\nHappy Hour, Football club, English club, and many exciting activities\nCompany trip/ team building/ Year End Party\nĐịa điểm làm việc\n- Đà Nẵng: 68 Xô Viết Nghệ Tĩnh, Cẩm Lệ\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2227, 209, 2, 'Senior Full-Stack Engineering Manager', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 33,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWHY JOIN?\n• This is a mission critical role as our organization shifts toward multiple full-stack, cross-functional teams that are responsible for end-to-end delivery. You’ll play a key part in shaping the future of our engineering and automation culture enabling the transformation of a high-growth company offering products our customers need during a moment that shapes the future for those they love most. Every day you’ll tackle complex challenges working with the latest technologies on cloud-native platforms—all within an inclusive, collaborative environment where each team member is empowered by mission, committed to protection, and dedicated to creating legacies.\n• The Senior Full-Stack Engineering Manager should be well versed in a range of technologies including .NET/C#, Azure SQL (MSSQL), and Vue.js. The role also affords the opportunity to influence how we scale our test automation practices using frameworks like Gherkin. The ideal candidate is someone who is adept at guiding junior engineers, working with key stakeholders, and is comfortable partnering with cross functional teams  Additionally, the role requires a fundamental understanding of system design and architecture with an emphasis on quality, performance and high availability high throughput distributed systems.\n\nJOB OVERVIEW\n• We are seeking a talented Senior Full-Stack Engineering Manager to support our partnership with FPT. This role requires a combination of skills, not only building robust applications but also serving as a liaison and mentor working with across multiple engineering teams on a wide range of initiatives. In this capacity, you will be guiding one or more newly formed engineering teams responsible for making contributions across our technology stack – from building modern UI components to developing secure APIs and ensuring the reliability of our systems through automation-first testing.\n\nRESPONSIBILITIES\nLeading one or more teams of Full Stack Engineers focused on:\n• Full-Stack Development\n• Designing and developing scalable REST APIs and services using .NET/C#.\n• Building modern, responsive UI components using JavaScript, Vue.js or Angular.js.\n• Writing performant, maintainable SQL queries and stored procedures.\n• Collaborating with product and design to implement intuitive user experiences.\n• Automation-Driven Quality\n• Contributing to and expanding our automation-first testing approach using Gherkin, SpecFlow, Playwright, or similar tools.\n• Defining and maintaining automated test suites across UI, API, and integration layers.\n• Participating in test planning and reviews to ensure high coverage and confidence.\n• DevOps & Observability\n• Supporting CI/CD pipelines and advocating for shift-left practices.\n• Implementing and improving monitoring and alerting of deployed services.\n• Participating in root cause analysis and post-incident reviews.\n• Collaboration & Delivery\n• Contributing to team ceremonies, planning, and team retrospectives.\n• Promoting engineering best practices and continuous improvement.\n• Working cross-functionally to remove blockers and accelerate delivery.\n\nYêu cầu ứng viên\nBasic Qualifications\n• Demonstratable experience leading one or more teams of 3-5 engineers\n• A history of working effectively with stakeholders across different teams (Data, DevOps, UI/UX)\n• Strong oral and written English language communication skills\n• Significant experience in software engineering with full-stack development exposure.\n• Proficiency in .NET/C#, JavaScript, and MSSQL.\n• Prior experience developing modern web UIs, REST APIs, and database-backed applications.\n• Experience with Azure DevOps for source control, CI/CD pipelines, and release management.\n• Experience with CI/CD tools, Git, and agile methodologies.\n• Previous hands-on experience with test automation frameworks and writing meaningful automated tests.\n\nPreferred Qualifications\n• Exposure to Azure cloud services and containerized deployments (AKS/Kubernetes).\n• Experience with BDD frameworks like Gherkin or SpecFlow.\n• Familiarity with observability tools and infrastructure monitoring.\n• Strong communication and mentoring skills.\n\nQuyền lợi\n• Attractive Salary Package based on your competence plus Annual Bonus and Project Performance Bonus.\n• Signing bonus up to 20M onboard before 02/07/2025\n• Annual Summer Vacation support from 700 hundred VND to 4 Million VND and up to 3 days off work.\n• 13th-month Salary.\n• Salary review according to Company Policy.\n• Annual leave according to Labor Law and Company Policy.\n• “FPT care” health insurance provided by Petrolimex (PJICO) and is exclusive for FPT employees: 57M – 160M.\n• 20% discount on school fee if your sons/daughters join FPT School.\n• Excellent cost-free learning opportunities: Udemy/ELSA PRO accounts for every employee & Udacity accounts for Managers, English/Japanese/Korean classes, sponsorship for taking certification such as PMP, AWS, etc.\n• International, professional, dynamic and friendly working environment and culture.\n• Be part of a team in an international world-class company and exchange knowledge with technology specialists and experts from the world’s leading companies.\n• Frequent staff activities and company parties;\n• Awesome social events and parties for employees.\n• Etc.\n\nSpecial offer for senior level:\n• Relocating package: Up to 100M (for senior candidates from Hanoi/HCM.C to Da Nang City).\n• Loan support: 4% interest rate (1 – 2 Billion VND package).\n\nĐịa điểm làm việc\n- Đà Nẵng: Tòa Nhà FPT Complex, Ðường Nam Kỳ Khởi Nghĩa, Phường Hoà Hải TP.Ðà Nẵng, Ngũ Hành Sơn\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2228, 1160, 2, 'Backend Developer', 'We are seeking a skilled Backend Developer to join our team and contribute to the development of an exciting new project. You will work on building robust and scalable backend systems using Node.js, MySQL, and Prisma, while also supporting the monitoring and maintenance of our game infrastructure. This role requires a solid understanding of backend development and basic DevOps practices to ensure smooth deployment and operation of our services.\n\n- Design, develop, and maintain backend services for a new platform using Node.js, MySQL, and Prisma.\n- Implement APIs and integrate with frontend systems to deliver seamless user experiences.\n- Build and maintain a secure API gateway to facilitate communication between game clients and servers, ensuring protection against hack/cheat attempts.\n- Collaborate with the team to integrate WebSocket-based communication for real-time features.\n- Monitor and maintain game infrastructure, including servers running Node.js, Nginx, Redis, Grafana, and Docker.\n- Assist with basic DevOps tasks, such as configuring load balancers (Nginx), caching systems (Redis), and monitoring tools (Grafana).\n- Ensure system scalability, security, and performance through best practices in development and deployment.\n- Troubleshoot and resolve issues related to backend services and infrastructure.\n\n**Requirements**\n- Proven experience in backend development with Node.js and Express.js.\n- Strong knowledge of MySQL for designing and managing relational databases.\n- Hands-on experience with Prisma as an ORM for efficient database operations.\n- Familiarity with WebSocket for real-time communication between clients and servers.\n- Basic understanding of DevOps practices, including:\n  + Configuring and managing Nginx as a load balancer.\n  + Using Redis for caching to optimize performance and prevent client-side cheating.\n  + Monitoring infrastructure with Grafana.\n  + Deploying and managing applications using Docker.\n- Experience with API development and securing communication channels to prevent unauthorized access.\n- Understanding of game backend logic to mitigate hack/cheat vulnerabilities.\n- Ability to work with deeplinks and user authentication via headers or URL parameters.\n- Strong problem-solving skills and attention to detail.\n- Excellent communication and collaboration skills to work with cross-functional teams.\n\n**Preferred Qualifications**\n- Experience with game development or supporting game server infrastructure.\n- Familiarity with microservices architecture and API gateway implementation.\n- Knowledge of security best practices for protecting sensitive user data.\n- Prior experience working with cloud-based or on-premise server infrastructure.\n\n**Benefits**\n- Work on exciting game-related projects with opportunities to contribute to both development and infrastructure.\n- Collaborate in a dynamic environment with opportunities for growth and learning.\n- Competitive salary and benefits package.\n\n**Working Location**\n- Hồ Chí Minh: Tân Bình.\n\n**Working Time**\n- Monday - Friday (from 09:00 to 18:00).\n\n**Application Method**\n- Candidates apply online by clicking **Apply Now** below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Tân Bình', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2229, 1161, 2, 'C++/C# Developer (Remote)', 'We are looking for talented C++/C# developers to join our dynamic team in Vietnam. If you have experience with C++/C# programing and have a passion for front-end or back-end development, we want to hear from you. Excellent communication in English is a must.\n\nResponsibilities:\nFront-End Development:\n- Design and develop user interfaces using MFC (for C++) or WPF (for C#).\n- Ensure the UI is responsive, user-friendly, and adheres to design specifications.\nBack-End Development:\n- Develop back-end logic and integrate with front-end components.\n- Ensure robust, scalable, and secure application architecture.\nApplication Development:\n- Write clean, maintainable, and efficient code in C++ or C#.\n- Debug, test, and fix issues in the application codebase.\n- Participate in code reviews and adhere to coding standards.\nCollaboration and Communication:\n- Work closely with other developers, designers to gather and understand requirements.\n- Participate in agile development processes, including sprint planning, stand-up meetings, and retrospectives.\n- Document development processes, code changes, and other relevant information.\n\nQualifications:\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field (or equivalent experience).\n- Fluency in English is a must.\n- Proficiency in C++ or C# programming\n- Strong knowledge of algorithms, data structures, and object-oriented programming.\n- Experience with MVC and MVVM software architecture patterns.\n- Familiarity with version control systems, including Git and SVN.\nPreferred Qualifications:\n- Strong knowledge of spatial data structures, computational geometry, and linear algebra.\n- Experient with Qt\n- Proficiency in Python\n- Proficiency in DevEpxress/EyeShot\n- Knowledge of MFC (Microsoft Foundation Classes) and WPF (Windows Presentation Foundation)\n\nBenefits:\n- Salary up to 2200$/month\n- Collaborate with diverse teams and influence technical decisions that align with business goals.\n- Flexible working style\n- Working remotely\n- Working directly with Canadian developers using mordern technologies\n- Holidays bonus and 13 months salary\n- Salary increase every year based on performance\n- National holidays', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hải Phòng, Đà Nẵng, Hồ Chí Minh, Cần Thơ, Bình Dương, Bắc Ninh, Đồng Nai, Hưng Yên, Hải Dương, Bà Rịa-Vũng Tàu, An Giang, Bắc Giang, Bình Định, Bình Phước, Khánh Hoà, Ninh Thuận, Lâm Đồng, Quảng Ninh, Vĩnh Phúc, Lào Cai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2230, 1162, 2, 'Kỹ Sư Lập Trình Ứng Dụng Phần Cứng', 'Mô tả công việc\n- Nghiên cứu và phát triển sản phẩm thiết bị giám sát hành trình\n- Phân tích, đánh giá và lập kế hoạch công việc triển khai theo các yêu cầu chức năng (một phần hoặc toàn bộ 1 sản phẩm) và viết tài liệu nghiệp vụ\n- Kế thừa và ứng dụng mã nguồn sẵn có lên các nền tảng phần cứng khác nhau (Porting)\n- Phân tích, Triển khai thư viện hoặc tích hợp thư viện cho các thiết bị ngoại vi khác nhau và viết tài liệu\n- Xây dựng các công cụ vận hành, phân tích và gỡ lỗi cho sản phẩm\n- Xác minh các sự cố liên quan tới chức năng của sản phẩm và đưa ra giải pháp xử lý\n- Thực hiện triển khai công việc theo hướng dẫn và báo cáo định kỳ của cấp trên\n\nYêu cầu ứng viên\n- Nam 23-35 tuổi không yêu cầu kinh nghiệm\n- Tốt nghiệp hệ đào tạo chính quy Cử nhân, Kỹ sư chuyên ngành Điện, Điện Tử viễn thông, Tự động hóa …\n- Trình độ ngoại ngữ: Đọc/Viết tài liệu Tiếng Anh - Tin học văn phòng cơ bản (Word, excel,…)\n- Kỹ năng: Sử dụng ngôn ngữ lập trình C/C++, Java trong phát triển ứng dụng trên các phần cứng sử dụng hệ điều hành Android, BSP Linux; Làm việc với design patents; Hiểu biết về xử lý đồng bộ/Bất đồng bộ, giao tiếp giữa các Process, multi-threading; Đọc hiểu và thích nghi tốt với sự thay đổi về SDK/Framework/driver/libraries của các nền tảng khác nhau…..\n- Yêu cầu chuyên môn:\n+ Có hiểu biết cơ bản về Network Topology cho Live streaming, audio/Photo/video codec, video container và các giao thức về media streaming;\n+ Có hiểu biết về hệ thống giám sát hành trình tích hợp Camera ghi hình DASHCAM, đầu ghi Mobile Digital Video Recorder (MDVR) của Gotrack.\n+ Có hiểu biết về thành phần cấu tạo, chức năng và vận hành của các thiết bị DASHCAM, MDVR…\n- Ưu tiên: Đã tham gia nghiên cứu, phát triển và chế tạo sản phẩm được triển khai thực tế. Hoặc đã tham gia bảo trì, nâng cấp liên tục một sản phẩm trong thời gian dài; Được đào tạo từ các môi trường như FPT, Đại học Bách Khoa Hà Nội, Đại học Quốc Gia Hà Nội, Sư phạm kỹ thuật …\n\nQuyền lợi\n- Mức lương 16.000.000đ - 20.000.000đ, phù hợp với năng lực và kinh nghiệm\n- Được đóng BHXH, BHYT, BHTN theo quy định của pháp luật\n- Chế độ nghỉ phép, nghỉ lễ theo quy định\n- Được xét tăng lương 2 lần/năm, xét tăng lương thâm niên vào cuối năm, thưởng lễ tết, sinh nhật,...\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội học hỏi và phát triển kỹ năng với các công nghệ mới nhất trong lĩnh vực nhúng\n- Được tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn\n- Tham gia các hoạt động team building, du lịch hàng năm\n- Được trang bị đầy đủ các thiết bị, công cụ cần thiết cho công việc\n\nĐịa điểm làm việc\n- Hà Nội: Lô B13, Khu đấu giá Vạn Phúc, Lê Văn Tám, Vạn Phúc, Hà Đông\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:15 đến 17:30)\n- Các buổi sáng thứ 7 hoặc 2 thứ 7 trong tháng\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2231, 1163, 2, 'Senior Front-End Developer (React, NextJS)', 'Unstatic là một startup công nghệ "made in Vietnam" ra đời từ 2016, tập trung nâng cao năng suất cá nhân toàn cầu. Sản phẩm đầu tay Habitify là ứng dụng theo dõi thói quen thành công, được Apple vinh danh nhiều lần trên App Store với các danh hiệu như "App of The Day" và "New App We Love". Việc được Apple chủ động quảng bá tới 13 lần là một minh chứng rõ ràng cho chất lượng của ứng dụng. Hiện tại có hơn 2 triệu người dùng quốc tế, khẳng định vị thế sản phẩm Việt trên thị trường cạnh tranh như Mỹ, Nhật, Hàn. \nĐằng sau Habitify là một đội ngũ người Việt trẻ trung, sáng tạo, luôn khao khát đưa sản phẩm "made in Vietnam" ra thế giới bằng con đường chất lượng thực sự. Từng dòng code, từng tính năng đều được tạo ra với sự chỉn chu, tâm huyết và tinh thần làm chủ – điều giúp Habitify luôn theo sát những đổi mới công nghệ và mang lại trải nghiệm tốt nhất cho người dùng. \nVới chúng mình, Unstatic không chỉ là nơi làm việc – mà còn là nơi để bạn góp phần tạo ra điều có ý nghĩa cho hàng triệu người. Nếu bạn đang tìm kiếm một môi trường để phát triển, thử thách bản thân, và để lại dấu ấn cá nhân trong một sản phẩm và có giá trị toàn cầu – Unstatic sẵn sàng đồng hành cùng bạn. \n1. Nhiệm vụ\n- Phân tích yêu cầu tổng quan và tính năng cụ thể của ứng dụng.\n- Phân tích thiết kế giao diện, xác định và triển khai tương tác người dùng phù hợp, đảm bảo tính khả thi và khả dụng của công nghệ đối với yêu cầu và thiết kế.\n- Thiết kế và phát triển các ứng dụng web có độ phản hồi cao, đáp ứng các yêu cầu về tối ưu hóa dung lượng, thời gian tải/nạp/chạy (parse/load/run-time) và khả năng mở rộng, tái ứng dụng cao.\n- Thiết kế và triển khai các mô hình phát triển dự án dựa trên hệ sinh thái ReactJS (library và các third party framework).\n- Liên tục thay đổi cách tiếp cận và triển khai ý tưởng.\nYêu cầu ứng viên\n- Từ 3-4 năm kinh nghiệm với ReactJS và hệ sinh thái (hoặc các library/framework có concept tương tự: React Native, Vue, Ember,...).\n- Nắm vững sâu về Web stack: HTML5, CSS3, Javascript và Web APIs.\n- Có hiểu biết về Cross-Browser Compatibility và Polyfills.\n- Nắm vững các khái niệm cơ bản về NodeJS và các development suite liên quan (NPM/Yarn, Task runners, Dev server,...).\n- Nắm vững kiến trúc, cơ chế vận hành và mục tiêu đầu ra của Single Page App hoặc Server-side Rendering.\n- Nắm vững các design principles và có khả năng xây dựng Responsive UI với CSS, Styled-components, CSS-in-JS,...\n- Nắm vững các Web bundler và build tools: Webpack, Parcel,...cùng với các optimization configs.\n- Nắm vững các development tools: Devtools, Chrome Extensions, ESLint, Husky,...\n- Hiểu rõ cơ chế làm việc Git Flow cũng như issue-based management.\n- Các yêu cầu kỹ thuật mang tính lợi thế: UI/UX design, Node APIs, Static webpage/Vanilla web solutions, Low level CSS Utilities, Popular UI Kit, ảo hóa với Docker, docker-compose, CI/CD (GitHub Actions, Gitlab CI,...),...\nQuyền lợi\n- Mức lương và phúc lợi:\n  - Mức lương NET cực kì cạnh tranh, từ 30.000.000 - 40.000.000 triệu/tháng\n  - Thử việc nhận 100% lương\n  - Lương tháng 13, thưởng lễ, tết, thâm niên.\n  - Review lương 1 lần/năm.\n  - Bảo hiểm y tế, bảo hiểm xã hội, bảo hiểm sức khỏe cá nhân (PTI)\n  - Hỗ trợ ăn trưa 500.000 VND/tháng.\n- Các quyền lợi khác:\n  - Miễn phí gửi xe, snacks & drinks tại văn phòng.\n  - Du lịch công ty, team building, sinh nhật.\n  - Hoạt động Well-being 1 tháng/lần (các hoạt động chăm sóc sức khỏe thể chất và tinh thần).\n  - Happy Lunch vào Trưa thứ 4, Teabreak vào chiều Thứ 3 hoặc chiều Thứ 5 hàng tuần.\n  - Các chế độ khác theo đúng Luật lao động hiện hành.\n- Môi trường làm việc:\n  - Môi trường product trẻ trung năng động, sáng tạo cao.\n  - Sản phẩm xây dựng ra cho khách hàng quốc tế 100%, hiện có hơn 1.5 triệu người sử dụng trên toàn cầu.\n- Thời gian làm việc:\n  - Chấm công/làm việc linh hoạt từ 08h00 - 09h30, miễn đủ 8 tiếng, đảm bảo hiệu suất và tiến độ công việc\n  - Làm việc từ thứ 2 đến thứ 6 hàng tuần, nghỉ trưa từ 12h00 - 13h30, thứ 4 nghỉ trưa từ 12h00 - 14h00.\nĐịa điểm làm việc\n- Hà Nội: Tầng 19, Ladeco Building, 266 Đội Cấn, Liễu Giai, Ba Đình\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 00:00 đến 00:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2232, 1164, 2, 'AI Backend Developer', 'We are seeking an experienced AI Backend Developer with over 5 years of experience in designing, implementing, and optimizing AI-driven backend systems. The ideal candidate will have deep expertise in LangChain, RAG pipeline implementation, and search technologies (OpenSearch/Elasticsearch), along with experience in chatbot/playground development. Knowledge of AI agents, tools, and RAG optimization is a plus. Design and implement LangChain-based workflows for AI applications.\nDevelop and optimize Retrieval-Augmented Generation (RAG) pipelines.\nIntegrate OpenSearch/Elasticsearch for semantic/hybrid search.\nBuild and maintain chatbot/playground environments (e.g., Streamlit, Gradio, custom UIs).\nFine-tune vector search, hybrid search, and relevance ranking.\nOptimize indexing/query performance for low-latency AI responses.\nWork with embeddings (OpenAI, Hugging Face, or custom models).\nDevelop scalable APIs (FastAPI, Flask, or similar).\nCollaborate on frontend-backend integration (Ember.js or other JavaScript frameworks).\nUse build tools (Ant, Maven, Gradle) for deployment automation.\nEnsure CI/CD pipelines are efficient and reliable.\nWork in Agile/Scrum environments, participating in sprints, standups, and retrospectives.\nCollaborate with frontend engineers, data scientists, and product teams.\n\nYêu cầu ứng viên: 5+ years of backend development (Python preferred). Strong experience with LangChain for LLM orchestration. Hands-on experience with OpenSearch/Elasticsearch (indexing, querying, optimization). Proven track record in RAG pipeline implementation. Experience in developing chatbots or AI playgrounds (e.g., Gradio, Streamlit, custom UIs). Familiarity with LLM APIs (OpenAI, Anthropic, Mistral, etc.). Knowledge of AI agents & tools (AutoGPT, BabyAGI, multi-agent systems). Experience in RAG optimization & evaluation (metrics like precision, answer relevance). Familiarity with vector databases (Pinecone, Weaviate, Milvus). Understanding of NLP techniques (text processing, embeddings, fine-tuning). Experience with both external and embedded databases. Understanding fundamental design principles behind a scalable application. Creating database schemas that represent and support business processes. Implementing automated testing platforms and unit tests. Proficient understanding of code versioning tools, such as Git. Ability to clearly communicate with both technical and non-technical team members.\n\nOther Requirements: Experience with Agile Scrum. Experience with Ember or other JavaScript.\n\nQuyền lợi: What differentiates MEGAZONE from other software companies in Vietnam: The attractive salary (Negotiation). 2-month probation period with 100% salary. Full salary insurance coverage after the probation period. Participation in the PVI health insurance package, and annual health check-ups. 13th-month salary, birthday bonus, New Year bonus, Mid-Autumn Festival gifts, March 8th and October 20th gifts, etc. Performance evaluation and regular salary increases. Welfare for personal events, childbirth, and other benefits as per labor regulations and company welfare policies. Dynamic and youthful work environment conducive to personal growth and development.\n\nĐịa điểm làm việc: - Hà Nội: 27th Floor, East Tower, Lotte Center Hanoi, 54 Lieu Giai, Ba Đình.\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:30 đến 17:30). Flexible working hours may apply depending on project (e.g., 1:00 PM – 9:00 PM).\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2233, 1165, 2, 'Nhân Viên Lập Trình Front-End', 'Mô tả công việc:\n- Phối hợp với đội nhóm để phân tích yêu cầu của dự án, xây dựng kiến trúc và tổng hợp thành tài liệu.\n- Chịu trách nhiệm phát triển, tối ưu và duy trì hệ thống Frontend cho ứng dụng web.\n- Trao đổi với quản lý dự án và tiến hành phân tích thiết kế và triển khai các giải pháp để có thể tạo giao diện tối ưu về UI/UX. Tạo ra các component có thể tái sử dụng trong quá trình thực hiện dự án.\n- Đánh giá yêu cầu xây dựng (đánh giá được hết tất cả các trường hợp, hiểu bản chất của vấn đề), sửa đổi tính năng.\n- Xử lý lỗi phát sinh trong quá trình vận hành.\n- Tìm kiếm các phương án tối ưu nhằm nâng cao giải pháp, hiệu suất cho quá trình phát triển sản phẩm.\n- Nghiên cứu, cập nhật các xu hướng, công nghệ liên quan đến phát triển sản phẩm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học/cao đẳng các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin...\n- Độ tuổi từ 23-30 tuổi.\n- Tối thiểu 1 - 3 năm kinh nghiệm phát triển ứng dụng frontend sử dụng ReactJS, VueJS, Angular.\n- Thành thạo HTML, CSS (SCSS, Tailwind, …), JavaScript.\n- Có kinh nghiệm với quản lý state phức tạp (Redux, Zustand, Vuex, Pinia), hiểu rõ luồng dữ liệu trong một SPA.\n- Thành thạo sử dụng AI trong công việc.\n- Thành thạo tích hợp nhiều loại API (REST/GraphQL/…) và hiểu rõ cách xử lý dữ liệu bất đồng bộ.\n- Có tư duy tối ưu giao diện: responsive, cross-browser, thân thiện với SEO (có kinh nghiệm SSR với Nuxt.js/Next.js là điểm cộng lớn).\n- Có khả năng đọc hiểu tiếng Anh & sử dụng tốt công cụ tìm kiếm để giải quyết vấn đề.\n- Có ý thức lập trình viết code theo cấu trúc, theo tài liệu, dễ dàng nâng cấp (clean code).\n- Kỹ năng giải quyết tốt và khả năng làm việc độc lập cũng như làm việc nhóm.\n- Có khả năng giao tiếp và hợp tác cùng các đội nhóm khác.\n- Chủ động, trung thực và có ý thức cầu tiến.\n\nQuyền lợi:\n- Thời gian làm việc: 8h00 - 17h00 Từ thứ 2 đến thứ 6, được nghỉ T7&amp;CN.\n- Cơ hội huấn luyện: Cơ hội tham gia các chương trình đào tạo trong nước và nước ngoài, đặc biệt dành cho lập trình viên.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, hòa đồng.\n- Thu nhập theo năng lực và hiệu quả công việc.\n- Đảm bảo đầy đủ quyền lợi của người lao động theo quy định của Nhà nước.\n- Khám sức khỏe định kỳ hàng năm và tham gia thêm gói bảo hiểm chăm sóc sức khỏe BIC.\n- Tham gia các hoạt động teambuilding, bonding, CLB đá bóng hàng tuần tại Công ty.\n- Phụ cấp khác: Phụ cấp cơm trưa, gửi xe, sinh nhật, công tác phí và các phụ cấp khác cho người lao động.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 614 Điện Biên Phủ, Quận 10.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 10', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2234, 1166, 2, 'Java Developer (Middle/Senior)', 'Mô tả công việc\n- Work in a team of engineers to implement backend services in the platform\n- Build service definitions, OpenAPI specifications, SDKs, and documentation for other developers that consume these services\n- Integrate with other services and data sources using APIs, messaging systems, databases\n- Collaborate with the DevOps team on microservices design, containerization, and automated deployments\n- Build automated test suites to ensure these services are reliable and performant\n\nYêu cầu ứng viên\n- such as Spring Boot\n- Project experience around web service design and RESTful APIs\n- Expertise with the OpenAPI Specification (Swagger), RESTful APIs, and related tools such as Postman, cURL, and HTTPie\n- Experience integrating with 3rd party services and databases such as Redis, message queues, MongoDB, and ElasticSearch\n- Agile/SCRUM methodology experience\n- English is a must\n- Prefer Senior/Leader candidates\n\nQuyền lợi\n- Salary: Negotiable\n- Performance review: 2 times/year\n- 14th-month salary bonus\n- KPI bonus based on project and performance\n- Extra package: 16 Mil /employee/year (Bonus at Tet, New Year, your birthday, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, ...)\n- Opportunity to work in a professional, modern, and dynamic environment, take part in international projects\n- Opportunity to get on-job training and promotion\n- An excellent corporate culture with in/out of office activities that help to develop staffs ability and creativity\n- CMC health care and social insurance\n- Onsite opportunities: short-term and long-term assignments in US, EU,... (members of GEU/US).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2235, 1167, 2, 'Kỹ Sư Tự Động Hoá', 'I. Kiểm tra hiệu chỉnh, cải tiến máy móc thiết bị tự động hóa\n- Cài đặt, lập trình, hiệu chỉnh, hướng dẫn vận hành các máy móc tự động hóa.\n- Thiết kế, tính toán chọn các thiết bị cho hệ thống tự động hóa.\n- Lập trình PLC và thiết kế HMI cho các thiết bị, dây chuyền tự động hóa.\n- Lập trình máy tính PC, lập trình vision, robot cho các máy, dây chuyền tự động.\n- Lắp đặt biến tần, thiết bị, ứng dụng tự động hóa.\n- Đề xuất cải tiến áp dụng tự động hóa vào trong quá trình sản xuất.\n\nII. Quản lý quy trình công nghệ sản xuất, giảm giá thành sản phẩm\n- Thiết kế layout khu vực sản xuất, phù hợp với nhu cầu thực tế sản xuất sản phẩm\n- Đề xuất và/hoặc thực hiện các dự án giảm giá thành linh kiện.\n- Thiết kế quy trình công nghệ sản xuất, tiếp nhận chuyển giao thiết bị từ bên ngoài về Nhà máy.\n- Đề xuất đầu tư mới trang thiết bị máy móc, công cụ, dụng cụ tăng năng suất, tăng chất lượng, giảm người.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học/ cao đẳng chuyên ngành điện, tự động hóa, điều khiển\n- Có từ 03 năm kinh nghiệm lập trình PLC tại các công ty FDI, các công ty chế tạo máy.\n- Có khả năng lập trình PLC, HMI: Mitsubishi, Siemens, Yaskawa, Inovance\n- Có khả năng làm việc với động cơ Servo, Stepping motor, robo cylinder\n- Có khả năng quản lý công việc, làm việc nhóm, làm việc độc lập\n- Tổng hợp báo cáo\n- Ngoại ngữ Tiếng Anh hoặc Tiếng Nhật\n\nQuyền lợi\n- Lương thỏa thuận theo kinh nghiệm\n- Phụ cấp cha mẹ đẻ từ 70 tuổi trở lên: 400,000 đồng/ bố hoặc mẹ/tháng\n- Thưởng ngày Tết Dương lịch, Tết Nguyên đán, Lễ Quốc Khánh, Thưởng đột xuất theo Nội quy lao động, qui chế khen thưởng và Quy chế tài chính của Công ty.\n- Phúc lợi cho con: Thưởng học sinh giỏi, xuất sắc, tết Thiếu nhi, trung thu...\n- Phúc lợi thăm hỏi: Hôn nhân, sinh nhật, ốm đau, tang gia ...\n- Nghỉ mát hàng năm 100% do Công ty tổ chức và đài thọ\n- Hỗ trợ 30%- 40% - 50% khi mua sắm các sản phẩm Kangaroo\n- Và các phúc lợi khác theo qui định trong cơ chế Chính sách nhân viên cùng nhau phát triển của Tập đoàn.\n\nĐịa điểm làm việc\n- Hưng Yên: Cụm CN Tân Tiến - Tân Tiến - Văn Giang, Văn Giang\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hưng Yên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2236, 1168, 2, 'Nhân Viên Điện Tự Động Hóa', 'Mô tả công việc:\n- Chịu trách nhiệm phát triển các dự án tự động hóa trong dây chuyền sản xuất.\n- Thiết kế và chuẩn bị dụng cụ, khuôn mẫu, đồ gá và thiết bị bán tự động phục vụ sản xuất.\n- Quản lý và xử lý các tài liệu, hồ sơ liên quan đến kỹ thuật.\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng trở lên chuyên ngành kỹ thuật hoặc công nghệ, ưu tiên ngành điện hoặc điện tử.\n- Tối thiểu 2 năm kinh nghiệm trong vai trò kỹ sư bảo trì, phát triển máy móc tự động.\n- Giao tiếp tiếng Anh cơ bản.\n- Hiểu biết sâu về các thiết bị tự động hóa như PLC, Servo, bộ điều khiển, cảm biến, robot và linh kiện điện.\n- Ưu tiên ứng viên có kinh nghiệm:\n  - Tham gia lắp ráp máy móc tự động\n  - Xử lý lỗi hệ thống tự động\n  - Lập trình và vận hành PLC (đặc biệt là Mitsubishi, Omron, Keyence)\n  - Có kinh nghiệm triển khai các hệ thống phục vụ Công nghiệp 4.0 – IOT.\n  - Có kinh nghiệm thiết kế, phát triển đồ gá/khuôn/dụng cụ bán tự động cho dây chuyền sản xuất.\n  - Có kỹ năng quản lý, giám sát tiến độ phát triển dự án kỹ thuật mới.\n  - Kỹ năng giải quyết vấn đề\n  - Kỹ năng làm việc nhóm\n  - Kỹ năng giao tiếp hiệu quả\n\nQuyền lợi:\n- Miễn phí ăn ca tại nhà máy\n- Miễn phí bảo hiểm sức khỏe và bảo hiểm rủi ro 24/7\n- Được hỗ trợ tiền đóng BHXH, BHYT, BHTN trong 2 tháng thử việc trả trực tiếp vào lương\n- Miễn phí khám sức khỏe đầu vào, được khám sức khỏe định kỳ hàng năm\n- Có xe đưa đón nhân viên từ Hà Nội và TP Hòa Bình\n- Môi trường làm việc hoà đồng, được đào tạo nâng cao kỹ năng, chuyên môn nghiệp vụ\n- Sau thử việc được tham gia BHXH, BHYT, BHTN theo qui định\n- Cơ hội thăng tiến nhanh\n- Thưởng tháng 13, xem xét tăng lương hàng năm\n- 14 ngày phép/năm\n- Hưởng 100% lương khi thử việc\n\nĐịa điểm làm việc:\n- Hoà Bình: Lô 20 đường số 1, KCN Lương Sơn, Hòa Bình, Lương Sơn\n- Hà Nội: Xuân Mai, Chương Mỹ\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 16:30)\nThứ 7 (từ 08:00 đến 12:00)\n2 sáng thứ 7\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hoà Bình, Lương Sơn, Hà Nội, Chương Mỹ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2237, 1169, 2, 'Nhà Phát Triển Phần Mềm', '1. Design and Development\n● Build, test, and maintain highly scalable Java applications.\n● Collaborate with cross-functional teams to translate business requirements into technical solutions.\n2. System Architecture\n● Contribute to the design and architecture of software solutions, ensuring best practices and optimal performance.\n● Conduct code reviews and provide guidance on coding standards and design patterns.\n3. Quality Assurance & Risk Management\n● Troubleshoot, debug, and optimize applications for maximum speed and scalability.\n● Resolve technical challenges and identify opportunities for continuous improvement.\n4. Collaboration and Mentoring\n● Work closely with product managers, designers, and other engineers to deliver high-quality features.\n● Mentor and guide junior engineers, fostering a culture of knowledge sharing and continuous learning.\n5. Continuous Improvement\n● Stay updated on emerging technologies and apply them to improve existing systems.\n● Lead and contribute to technical discussions, ensuring the team follows Agile practices.\n\n++ Must have:\n● 2 years of hands-on experience in Java development, with a strong grasp of Java 8 features (e.g., streams, lambdas).\n● Proficiency in frameworks like Spring Boot, Hibernate, or JPA.\n● Experience with RESTful APIs and microservices architecture.\n● Familiarity with relational databases (e.g., MySQL, PostgreSQL) and NoSQL databases (e.g., MongoDB).\n● Proficient in building tools like Maven or Gradle, and version control systems like Git.\n● Strong problem-solving and analytical abilities.\n● Knowledge of CI/CD pipelines and DevOps practices.\n● Experience with messaging systems such as Kafka or RabbitMQ.\n● Good at English.\n\n++ Nice to have:\n● Prior experience with data engineering tasks, such as building ETL pipelines, handling large datasets, or designing data storage solutions.\n● Hands-on experience with cloud platforms like AWS, Azure, or GCP.\n● Familiarity with containerization technologies like Docker and orchestration tools like Kubernetes.\n● Understanding of front-end technologies (e.g., Angular, React) is a plus.\n\n• Competitive salary, performance bonus.\n• Social insurance, health insurance, unemployment insurance according to the law.\n• Clear career advancement and development opportunities.\n• Dynamic, professional and friendly working environment.\n• Professional and technical skills training.\n• Participate in team building activities, annual vacations.\n• Holiday bonuses according to company regulations.\n\n- Hồ Chí Minh: Số 74 đường 101, Phường Thạnh Mỹ Lợi, Thủ Đức.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Thủ Đức', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2238, 1170, 2, 'Fullstack Developer (PHP)', 'Mô tả công việc\n- Tham gia phát triển, bảo trì và tối ưu hệ thống web application sử dụng PHP với CodeIgniter 3 hoặc Laravel.\n- Thiết kế, xây dựng và tích hợp các API theo chuẩn RESTful.\n- Làm việc với hệ quản trị cơ sở dữ liệu MySQL hoặc PostgreSQL.\n- Phối hợp với team để phát triển giao diện người dùng bằng HTML, CSS, JavaScript, jQuery, Ajax.\n- Tham gia phân tích và thiết kế hệ thống theo mô hình MVC, áp dụng các nguyên lý lập trình hướng đối tượng OOP và ORM.\n- Tham gia họp Scrum hàng ngày, báo cáo tiến độ công việc và phối hợp theo quy trình Agile/Scrum.\n- Sử dụng Git để quản lý source code và phối hợp công việc với team.\n- Áp dụng Design Pattern trong thiết kế và phát triển hệ thống.\n- Làm việc độc lập hoặc theo nhóm với tinh thần trách nhiệm cao.\n\nYêu cầu ứng viên\nYêu cầu:\n- Thành thạo PHP, đặc biệt là framework CodeIgniter 3 hoặc Laravel.\n- Có kinh nghiệm làm việc với MySQL / PostgreSQL.\n- Nắm vững mô hình MVC, ORM, RESTful API, lập trình hướng đối tượng OOP.\n- Có kinh nghiệm với HTML, CSS, JavaScript, jQuery, Ajax.\n- Sử dụng thành thạo Git (Git Flow, GitHub/GitLab/Bitbucket).\n- Có hiểu biết và vận dụng được các mẫu thiết kế phần mềm (Design Pattern).\n- Có kinh nghiệm làm việc theo quy trình Agile/Scrum.\n- Có khả năng tự học, làm việc độc lập, tinh thần trách nhiệm và chủ động cao trong công việc.\n\nƯu tiên ứng viên:\n- Có kiến thức hoặc kinh nghiệm với ReactJS, NextJS.\n- Đã từng làm việc trong môi trường phát triển sản phẩm (product company).\n- Hiểu biết và từng tham gia phát triển các sản phẩm ERP, HRM, CRM – có kinh nghiệm xử lý quy trình nghiệp vụ trong các hệ thống này.\n\nQuyền lợi\n- Thu nhập từ 14.000.000 - 25.000.000 VNĐ/tháng\n- Bữa trưa miễn phí tại công ty\n- Được hưởng đầy đủ các chế độ theo quy định của pháp luật (BHYT, BHXH, BHTN) và các chế độ phúc lợi theo nội quy, quy chế của Công ty (tham quan, nghỉ mát, lương thưởng, nghỉ lễ Tết,...)\n- Xét tăng lương định kỳ hàng năm\n- Được làm việc trong Môi trường năng động, chuyên nghiệp và thân thiện, có nhiều cơ hội thăng tiến và phát triển nghề nghiệp\n\nĐịa điểm làm việc\n- Hà Nội: 59 Xuân Diệu, Tây Hồ, Tây Hồ\n\nThời gian làm việc\n- Từ T2- sáng T7, chọn thời gian làm: 9h-18h/8h-17h\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2239, 1171, 2, 'IOS Developer (Junior Level)', '-Key Responsibilities :\n- Develop high-quality iOS applications that are ready to be published in Tier-1 countries.\n- Collaborate with cross-functional teams, including designers, product managers, and backend developers, to ensure the best user experience.\n- Write clean, well-documented, and maintainable code.\n- Stay up to date with the latest trends and best practices in iOS development.\n- Assist in testing and debugging applications.\n\n-Requirements :\n- University degree in Computer Science, Software Engineering, or a related field.\n- Minimum of 1 year of experience in iOS development.\n- Proficiency in Swift.\n- Experience with UIKit, SwiftUI, Core Data, Realm.\n- Familiarity or experience with CoreImage, CoreML, AR/VR is a plus.\n- Familiar with version control systems such as Git.\n- Experience working with REST APIs.\n- Strong problem-solving and analytical skills.\n- Ability to work in a fast-paced environment\n\n-Benefits :\n- Competitive negotiable salary\n- Full benefits package (Health care insurance, Life Insurance, Social Insurance etc.)\n- Supportive team environment that values collaboration and growth\n- Company trips, Happy lunch (twice a month), Milk-tea fund...\n\n- Đà Nẵng: Astraler Technology Co. Ltd - 6th Floor - Viet Nam Post Building - 271 Nguyen Van Linh street, Vinh Trung ward, Thanh Khe District, Danang, Thanh Khê\n\n- Working Hours: 8:00 AM – 5:30 PM, Monday to Friday\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2240, 1172, 2, 'Game Developer ( Cocos Creator )', 'Mô tả công việc\n- Designing and implementing code that is fit for purpose, scalable, human-readable, and in line with industry best practice.\n- Quality control of the entire product lifecycle by testing intuitiveness, user experience, and debugging where necessary.\n- Communicating with clients to understand their business goals and objectives, and interpreting that into the required changes to the platform where necessary.\n- Liaising with other developers, designers, and system administrators to identify new features and create relevant prototypes for new product ideas.\n- Deploying production code.\n- Communicating the effectiveness of emerging technologies to decision-makers.\n- Working on full production cycles from brainstorming and rapid prototyping to developing fully fledged systems and fine-tuning mechanics, as well as stress testing and bug fixing.\n- Developing innovative gameplay, AI, physics, UI, vehicles, weapons, and character controls.\n- Solving technical problems with simple, efficient, and creative code.\n- Helping ship game projects across multiple platforms on Web, iOS and Android.\n- Providing feedback and advice to junior team members.\n- Other tasks assigned by Line Manager.\n\nYêu cầu ứng viên\n- 4+ years of experience with game engines such as Cocos Creator, Cocos 2d-x, Unity, Pixi, Defold, Godot...\n- Experience working with native Android and iOS is a big plus.\n- History of working within rapid prototyping environments, such as game jams.\n- Passion for video games, films, and other creative mediums.\n- Knowing how to use git to collaborate with other teammates, understanding and applying Git Standards is a must.\n- Experience with remote config, dynamic assets loading.\n- Have knowledge of optimizing games.\n- Ability to build and maintain positive working relationships with teammates.\n- Excellent attention to detail and willingness to learn new software/processes.\n- Flexibility on working hours if required in the light of ad-hoc business demands.\n- Able to use initiative and remain self-motivated.\n- Able to work calmly and effectively under pressure.\n- Maintaining confidentiality/discretion where required.\n\nQuyền lợi\n- A competitive salary package that fits your skills, experiences, and contributions.\n- Holiday and New Year bonus.\n- Provision of necessary working equipment\n- A professional, dynamic, and inclusive working environment.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 292 Ung Văn Khiêm Phường 25, Bình Thạnh\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2241, 583, 2, 'Java Developer', 'Mô tả công việc\n- Investigate technical issues reported by customers, troubleshoot, propose recommendations / workarounds to resolve the issues.\n- Lead customer troubleshooting calls when being requested.\n- Assist in creating and updating technical documentation, FAQs, and self-service resources to improve customer self-support.\n- Gather insights from recurring customer feedback, issues and collaborating with Product Engineering team to prioritize fixes and feature enhancements.\n\nYêu cầu ứng viên\n- A Bachelor\'s degree in Computer Science, Engineering, or a related technical field.\n- 5+ years of experience in software development.\n- Proficiency in analyzing and debugging software systems, including reading logs and investigating backend workflows.\n- Excellent verbal and written communication skills in English.\n- Hands-on experience with Java.\n- Strong problem-solving, analytical, and organizational skills with a detail-oriented mindset.\n- Experience supporting customers is a plus.\n\nQuyền lợi\n- Free snack-drink, coffee, weekly happy hour, monthly birthday party\n- Working time: Monday – Friday | 9am - 6pm to some extent flexible working hours Friendly, professional and open working environment\n- Opportunities to improve English skills within an international team – English is an official language\n- You will become a key member of WATA TECH as we are growing faster and bigger now\n- Skills up plan with Tech talk, soft skill talk, English club, working process training\n- Company trip yearly\n- Friendly, professional and open working environment\n\nĐịa điểm làm việc\n- Hồ Chí Minh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2242, 1173, 2, 'Kỹ Sư Phần Mềm (Mạnh NodeJs, Làm Được Cả ReactJs)', 'Mô tả công việc:\n- Tham gia vào các dự án phát triển phần mềm cho khách hàng Nhật Bản, sử dụng công nghệ JavaScript như VueJS, ReactJS, Angular và NodeJS.\n- Đề xuất các giải pháp kỹ thuật và xu hướng công nghệ mới nhằm nâng cao chất lượng sản phẩm.\n- Phối hợp chặt chẽ với nhóm thiết kế và lập trình để xây dựng sản phẩm tối ưu.\n- Thực hiện các nhiệm vụ khác theo sự phân công của cấp trên.\n\nYêu cầu ứng viên:\n- Có ít nhất 01 năm kinh nghiệm lập trình JavaScript cho cả FE và BE.\n- Thành thạo HTML, CSS và sử dụng thành thạo các framework/library phổ biến như ReactJS, VueJS (FE) và NodeJS (BE).\n- Nắm vững kiến thức nền tảng về lập trình, lập trình hướng đối tượng (OOP) và hệ quản trị cơ sở dữ liệu (DBMS).\n- Tư duy hệ thống và logic tốt, khả năng học hỏi nhanh, chủ động đề xuất giải pháp và xử lý vấn đề hiệu quả.\n\nQuyền lợi:\n- Mức lương: Upto 24M, có thể thỏa thuận theo năng lực của ứng viên.\n- Nói KHÔNG với chậm lương, nợ lương.\n- Review lương 02 lần/năm.\n- Lương tháng 13, tháng lương 14 và các khoản bonus.\n- Thưởng các ngày lễ: 30/4, 2/9, Tết Dương Lịch. Quà sinh nhật công ty, quà sinh nhật cá nhân,…\n- Hưởng 15 ngày phép/năm.\n- Tham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động Việt Nam.\n- Khám sức khỏe định kì tại các bệnh viện uy tín (Hồng Ngọc, Thu Cúc, …).\n- Du lịch hè 1-2 lần/năm, trợ cấp team-building cá nhân định kỳ hàng quý.\n- Đọc sách miễn phí tại thư viện sách của Công ty.\n- Hưởng mọi quyền lợi hỗ trợ các chứng chỉ ngoại ngữ và chứng chỉ nghiệp vụ chuyên ngành như:\n  Chứng chỉ tiếng Nhật, chứng chỉ AWS, ISTQB…\n- Tham gia các khóa học thay đổi mindset từ Học viện Agile miễn phí.\n- Thời gian làm việc: Từ 8h00 đến 17h00, nghỉ Thứ Bảy và Chủ Nhật.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 22, tháp B, tòa nhà Sông Đà (HH4), Đường Phạm Hùng, Phường Mỹ Đình 1, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2243, 1174, 2, 'Nhân Viên Vận Hành Máy CNC', 'Mô tả công việc\n- Vận hành máy phay CNC: Đọc bản vẽ, chuẩn bị dụng cụ cắt, căn chỉnh máy, lập trình…\n- Kiểm tra và ghi chép kết quả đo vào biểu đo (bản vẽ).\n- Tổng kết số lượng thành phẩm.\n- Vệ sinh khu vực làm việc.\n- Các công việc khác có liên quan.\n\nYêu cầu ứng viên\n- Tốt nghiệp Trung cấp/ Cao đẳng cơ khí.\n- Có kinh nghiệm vận hành máy CNC (Phay), lập trình 2D, 3D.\n- Ưu tiên biết sử dụng phần mềm Cimatrol\n- Ưu tiên có kinh nghiệm tại các công ty sản xuất, cơ khí.\n- Có tinh thần trách nhiệm cao, cẩn thận và tỉ mỉ trong công việc.\n- Khả năng giải quyết vấn đề và tư duy logic tốt.\n\nQuyền lợi\n- Mức lương đàm phán theo kinh nghiệm, trình độ.\n- Phụ cấp 1.000.000 VNĐ/ tháng\n- Thưởng chuyên cần 500.000 VNĐ\n- Trợ cấp chuyên môn sau 6 tháng làm việc.\n- Review tăng lương 1 lần/năm\n- Cấp phát đồng phục khi làm việc chính thức tại Công ty.\n- Hỗ trợ cơm trưa, bữa phụ đầy đủ.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật định.\n- Thưởng các ngày lễ, tết theo quy định của công ty.\n- Cơ hội được đào tạo và nâng cao nghiệp vụ.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.\n- Môi trường làm việc an toàn, thoải mái.\n\nĐịa điểm làm việc\n- Hà Nội: Việt Hùng, Đông Anh\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 \n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2244, 1173, 2, 'Blockchain Developer (Có Kinh Nghiệm Frontend)', 'Mô tả công việc:\n- Tham gia phát triển Frontend của ứng dụng Web hiện đại, giàu tương tác với yêu cầu cao về chất lượng và độ tin cậy\n- Viết chương trình, lập kế hoạch, thiết kế module chức năng, xây dựng công cụ cài đặt, viết thử nghiệm\n- Sử dụng một trong số các thư viện hoặc framework: VueJS / ReactJS / Angular,...\n- Phát triển các tính năng mới cho sản phẩm theo yêu cầu\n- Thực hiện các nhiệm vụ được giao từ cấp quản lý trực tiếp\n- Tham gia phát triển các dự án liên quan đến Blockchain với các chain mới hoặc các sản phẩm research của công ty\n\nYêu cầu ứng viên:\n- Từ 2 năm kinh nghiệm làm Frontend Developer thành thạo một trong các js framework sau: Angular, Vue JS, React JS, Electro JS, Ember JS,.. (Ưu tiên ReactJS, VueJS)\n- Có ít nhất 6 tháng kinh nghiệm làm việc với Web3 và Blockchain.\n- Nắm vững kiến thức lập trình cơ bản, lập trình hướng đối tượng\n- Thao tác với các hệ quản trị cơ sở dữ liệu\n- Nắm vững mô hình web MVC, MVVM\n\nQuyền lợi:\n- Mức lương: upto 20M\n- Định kỳ review lương 6 tháng/1 lần\n- Lương tháng 13 và các khoản thưởng bonus khác\n- Thưởng các ngày lễ: 30/4, 2/9, Tết Dương Lịch. Quà sinh nhật công ty, quà sinh nhật cá nhân\n- Hưởng 15 ngày phép/năm.\n- Tham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động Việt Nam\n- Khám sức khỏe định kì tại các bệnh viện uy tín (Hồng Ngọc, Thu Cúc, Vinmec...)\n- Du lịch hè 1-2 lần/năm, team building định kỳ hàng quý\n- Đọc sách miễn phí tại thư viện sách của Công ty\n- Hưởng mọi quyền lợi hỗ trợ các chứng chỉ ngoại ngữ và chứng chỉ nghiệp vụ chuyên ngành như: Chứng chỉ tiếng Nhật, chứng chỉ AWS, ISTQB...\n\nĐịa điểm làm việc:\n- Hà Nội: 22F Tháp B, Tòa HH4 Sông Đà, Phạm Hùng, Mỹ Đình 1, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2245, 1175, 2, 'Lập Trình Viên C, C++', '• Làm việc tại Kobe Nhật Bản\n• Đối tượng: Nhận ứng viên từ Việt Nam sang Nhật hoặc đang sinh sống và làm việc tại Nhật\n• Lập trình bằng ngôn ngữ C, C++\n• Phân tích, thiết kế, lập trình và fix bug. \n• Thực hiện kiểm tra chất lượng sản phẩm đầu ra của dự án trước khi deliver cho khách hàng.\n• Thực hiện unit test theo nhu cầu dự án\n• Báo cáo hàng ngày với TBP\n• Hỗ trợ team cùng phát triển\n• Cập nhật tiến độ công việc hàng ngày vào tool quản lý dự án\n• Thực hiện đúng quy trình phát triển phần mềm\n\nYêu cầu ứng viên\n• Có kinh nghiệm code C, C++ từ 3 năm trở lên.\n• Tiếng Anh giao tiếp tốt hoặc tiếng Nhật N3+.\n• Có ý thức trách nhiệm cao.\n• Có khả năng đàm phán, thuyết phục, đề xuất ý kiến và giải pháp\n• Có khả năng tạo các tài liệu mô tả yêu cầu\n• Có khả năng giao tiếp, làm việc nhóm, khả năng giao tiếp với khách hàng.\n• Tích cực, chủ động, yêu thích việc quản lý dự án và dám đương đầu với thách thức\n\nQuyền lợi\nLương up to 550Man/năm\nNgồi làm việc trực tiếp tại công ty khách hàng bên Nhật.\nMôi trường làm việc chuyên nghiệp, ổn định lâu dài.\nNghỉ lễ theo ngày lễ của Nhật, và các chế độ theo công ty khách hàng Nhật.\nTham gia tất cả các chế độ BHXH, BHYT và chế độ đãi ngộ khác.\nXét tăng lương 1 năm 1 lần.\nLương OT: theo thời gian OT.\nCác loại lương thưởng khác.\nHỗ trợ nhà ở: 3 man/tháng.\nVé máy bay về Việt Nam: 8 man/năm.\nHỗ trợ chi phí đi lại: Theo thực tế.\nChi phí tham gia khoá học chuyên môn: Được công ty hỗ trợ.\nQuà lễ, Tết, party, du lịch công ty hàng năm.\nHỗ trợ gia hạn visa tại Nhật.\nĐỗi với ứng viên từ Việt Nam snag Nhật: Hỗ trợ toàn bộ chi phí sang Nhật\n\nĐịa điểm làm việc\n- Nhật Bản\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nhật Bản', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2246, 1141, 2, 'Lập Trình Viên Backend', 'Mô tả công việc\n- Lập trình web (backend) bằng PHP, trên framework do công ty tự phát triển hơn 17 năm, gồm các nhóm ứng dụng chính: Website doanh nghiệp, trường học, Portal bộ ban ngành, TMĐT, ERP,….\n- Quản lý source code bằng SVN.\n- Quản lý công việc bằng công cụ quản trị dự án nội bộ.\n- Làm việc với bộ phận kiểm thử và phát triển sản phẩm để tối ưu, sửa lỗi, phát triển chức năng mới.\n- Code theo các tiêu chuẩn ATTT, hiệu năng của tập đoàn Viettel.\n\nYêu cầu ứng viên\n- Tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán tin... hoặc chuyên ngành khác có liên quan\n- Từ một năm kinh nghiệm ở vị trí tương đương\n- Có kiến thức cơ bản về lập trình WEB (PHP / HTML / CSS / JAVASCRIPT).\n- Hiểu biết về MVC Framework\n- Có kiến thức về các hệ quản trị cơ sở dữ liệu, nhất là NoSQL (MongoDB), Solr, nếu chưa biết sẽ được đào tạo.\n- Đảm bảo nghiêm túc giờ giấc theo giờ hành chính.\n\nQuyền lợi\n- Thu nhập lên tới 20M/tháng, 2-6 tháng xét tăng lương 1 lần\n- Chính sách phát triển bản thân phù hợp với từng vị trí. Có cơ hội tiếp cận với các công nghệ mới nhất.\n- Sau 2 tháng thử việc sẽ được cân nhắc lên nhân viên chính thức, hưởng đầy đủ quyền lợi về BHXH\n- Nghỉ phép: 12 ngày/ năm\n- Thưởng lương tháng 13\n- Môi trường làm việc năng động, sáng tạo với đội ngũ CBNV đầy nhiệt huyết. Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding, sự kiện công ty, tiệc mặn ngọt.\n\nĐịa điểm làm việc\n- Hà Nội: Xuân La, Tây Hồ\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:30)\nnghỉ thứ 7 cách tuần\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Tây Hồ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2247, 15, 2, 'Lập Trình Viên Fullstack', 'Weldcom tuyển 03 chuyên viên lập trình, làm việc tại trụ sở chính số 285A Ngô Gia Tự, Long Biên, Hà Nội.\n\nChi tiết công việc: Lập trình các ứng dụng phần mềm phục vụ cho hoạt động sản xuất, kinh doanh của Công ty trên các nền tảng web, windows form. Cụ thể:\n- Phối hợp với các bộ phận khác để đưa ra ý tưởng cho các mẫu thiết kế phần mềm, ứng dụng mới.\n- Xây dựng phần mềm, ứng dụng mới bằng các ngôn ngữ lập trình thích hợp.\n- Phát triển và xây dựng các tính năng mới cho phần mềm.\n- Nâng cấp phần mềm và các hệ thống để đảm bảo tính bảo mật và hiệu quả hơn.\n- Phối hợp với nhóm Service Desk để viết tài liệu hướng dẫn sử dụng.\n- Kiểm tra và bảo trì các chương trình, ứng dụng định kỳ, tiến hành sửa lỗi khi có vấn đề xảy ra.\n- Triển khai và giới thiệu sản phẩm phần mềm tới khách hàng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp từ đại học chuyên ngành công nghệ thông tin, phần mềm.\n- Sử dụng một số ngôn ngữ lập trình:.NET/C#, Java, Python, Web Service.\n- Có kiến thức về SQL, MSSQL.\n- Lập trình với hệ CSDL: MSSQL, MySQL, Postgres, Oracle.\n- Thành thạo HTML, CSS, Bootstrap, Javascript, Jquery (Ưu tiên sử dụng ReactJs).\n- Kinh nghiệm sử dụng GIT như GitHub/GitLab, Docker container.\n- Có khả năng phân tích, tổng hợp dữ liệu ở các nguồn dữ liệu khác nhau.\n- Kỹ năng làm việc độc lập, làm việc nhóm tốt.\n- Hoạt bát, siêng năng, trung thực, chịu áp lực công việc.\n- Ưu tiên có kinh nghiệm triển khai các giải pháp phần mềm quản trị doanh nghiệp đặc biệt các doanh nghiệp có yếu tố sản xuất, xây dựng các phần mềm, thiết kế database, big data.\n\nQUYỀN LỢI ĐƯỢC HƯỞNG:\n- Thu nhập 15 - 30 triệu (Gồm Lương + phụ cấp + thưởng).\n- Được tham gia chính sách phát triển nhân sự ưu việt: được cấp quỹ đào tạo hàng năm để chủ động tham gia các khóa học ngoài, được tham gia chương trình đào tạo inhouse.\n- Bảo hiểm xã hội đóng trên 100% lương.\n- Các chế độ phép năm, lễ tết,... theo đúng 100% quy định của pháp luật lao động.\n- Được làm việc trong một môi trường coi trọng người lao động, văn hóa doanh nghiệp rõ nét. - Các chế độ phúc lợi đầy đủ. - Làm việc 5,5 ngày / tuần, nghỉ chiều thứ 7 và ngày chủ nhật.\n\nĐịa điểm làm việc:\n- Hà Nội: 285A Ngô Gia Tự, Long Biên, Long Biên.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2248, 1176, 2, 'C Developer', 'Mô tả công việc\n- Tham gia phát triển phần mềm cho trạm phát sóng 4G, 5G.\n- Phân tích thiết kế và vẽ call flow cho các luồng tính năng được giao phát triển mới.\n- Tìm hiểu, nghiên cứu về mạng viễn thông 5G.\n- Viết các tài liệu phân tích yêu cầu, tài liệu thiết kế SDD.\n- Kiểm thử chất lượng, hiệu năng phần mềm theo yêu cầu.\n\nYêu cầu ứng viên\n- Tốt nghiệp hệ chính quy các Trường Đại học, chuyên ngành đào tạo: Công nghệ thông tin, Điện tử Viễn thông, Tự động hóa..\n- Có từ 1 năm kinh nghiệm vị trí tương đương.\n- Tư duy, kỹ năng lập trình tốt, nắm vững các kiến thức nền tảng về lập trình C.\n- Có kiến thức về các cấu trúc dữ liệu và giải thuật cơ bản.\n- Nắm vững kiến thức về hệ điều hành.\n- Chấp nhận ứng viên sắp hoặc mới tốt nghiệp với điều kiện bắt buộc: tốt nghiệp loại Khá trở lên (CPA > 3.0) các trường Đại học;\n- Ưu tiên các ứng viên có kiến thức cơ bản về mạng viễn thông 4G, 5G\n- Ưu tiên các ứng viên có kinh nghiệm lập trình đa luồng, đa tiến trình, lập trình mạng ở tầng giao vận hoặc thấp hơn.\n- Ưu tiên các ứng viên có kinh nghiệm lập trình và debug trên hệ điều hành linux.\n\nQuyền lợi\n- Chế độ lương hấp dẫn 15 – 25M/tháng;\n- Xét lương hàng năm,  lương tháng 13, thưởng kinh doanh dựa trên kết quả công việc và hiệu quả hoạt động của công ty;\n- Bảo hiểm chăm sóc sức khỏe cao cấp, bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp;\n- Được khám sức khỏe định kỳ 1 lần/1 năm;\n- 01 giờ nghỉ phép có lương mỗi ngày cho phụ nữ có con dưới 12 tháng;\n- Môi trường làm việc hiện đại với những đồng nghiệp trẻ trung, năng động & thân thiện ;\n- Du lịch công ty hàng năm và tiệc cuối năm, team building hàng quý và ăn uống cùng nhau hàng tuần. Câu lạc bộ: chạy, bóng đá, game,...\n- Thời gian làm làm việc: 8h30 - 17h30 Thứ 2 - Thứ 6\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Detech, số 8 Tôn Thất Thuyết, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2249, 1177, 2, 'Lập Trình Viên Python', 'Mô tả công việc\n- Tham gia trực tiếp vào các dự án phát triển và triển khai hệ thống Odoo cho các doanh nghiệp.\n- Phụ trách thiết kế chi tiết, lập trình, unit test, xử lý lỗi của chương trình sử dụng ngôn ngữ lập trình Python trên framework Odoo.\n- Tham gia xây dựng các giải pháp, viết phần mềm, lập trình các module theo yêu cầu công việc.\n- Thiết kế, phát triển và bảo trì các ứng dụng Python theo kiến trúc Micro-services.\n- Phát triển các API Services với Python.\n- Mở rộng, cải thiện và sửa lỗi phần mềm hiện có.\n- Lập kế hoạch và thực hiện bảo trì các phần mềm theo kế hoạch lập ra.\n- Thực hiện các công việc khác theo sự phân công của Trưởng phòng.\n\nYêu cầu ứng viên\n- Tốt nghiệp các trường đại học, cao đẳng liên quan đến CNTT, có kiến thức cơ bản với lập trình tốt, đam mê công nghệ.\n- Có kiến thức, kinh nghiệm về: lập trình python, đã từng code framework Odoo là lợi thế.\n- Lập trình hướng đối tượng (OOP).\n- Lập trình trên các hệ quản trị cơ sở dữ liệu có cấu trúc MariaDB, PostgresDB, đã từng làm việc với MongoDB, HBase hoặc các NoSQL.\n- Kỹ năng tư duy logic.\n- Kỹ năng ứng dụng công nghệ thông tin.\n- Kỹ năng lập kế hoạch và triển khai công việc.\n- Kỹ năng xử lý tình huống.\n- Cẩn thận, chi tiết, nhiệt tình, trung thực.\n- Đam mê công nghệ thông tin\n- Bảo mật thông tin.\n- Có tinh thần trách nhiệm.\n\nQuyền lợi\n- Tham gia BHXH, BHYT, BHTN\n- Đánh giá xét lương thâm niên hàng năm\n- Khám sức khỏe định kỳ 1-2 lần/ năm tùy theo vị trí công việc\n- Thưởng các ngày lễ tết, thưởng cuối năm theo tình hình kinh doanh\n- Tham gia tổ chức công đoàn, được quan tâm thăm hỏi ốm đau, hiếu hỉ\n- Tham quan, nghỉ mát hàng năm theo chính sách công ty\n- CBNV được hưởng các chính sách chế độ khám chữa bệnh của hệ thống\n- Làm việc trong môi trường năng động, chuyên nghiệp và có cơ hội thăng tiến cao.\n\nĐịa điểm làm việc\n- Hà Nội: 444 Hoàng Hoa Thám, Tây Hồ\n\nThời gian làm việc\n- Thứ 2 - Thứ 6: 08h00 - 18h00\n- Thứ 7: 8h00 - 15h00  (làm 2 thứ 7 cách tuần)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2250, 1166, 2, 'Fresher Software Engineer (Java, .NET, NodeJS)', 'Tham gia chương trình đào tạo kỹ sư lập trình và tham gia thực tập tại các dự án quan trọng của CMC Global, cụ thể: \nĐào tạo về chuyên môn lập trình và quy trình phát triển phần mềm, quản lý dự án theo chuẩn quốc tế CMMi, có điều kiện phát triển kỹ năng mềm và ngoại ngữ; \nĐược hướng dẫn và hỗ trợ bởi các mentor là Technical Lead hoặc chuyên gia công nghệ của CMC Global; \nCơ hội tham gia vào các dự án lớn hoặc onsite tại các Công ty của CMC Global tại nước ngoài. \nĐịa điểm đào tạo & thực tập: Hà Nội \n\nYêu cầu ứng viên\nLà sinh viên đã/sắp tốt nghiệp chuyên ngành Công nghệ thông tin, Toán tin, Khoa học máy tính, Kỹ thuật phần mềm,... \nNắm vững kiến thức cơ bản trong các ngôn ngữ/nền tảng sau:\n(BE) Java/NodeJS/Python/Golang\n(FE) HTML, CSS, JS\nƯu tiên ứng viên có khả năng giao tiếp tiếng Anh tốt (tương đương IELTS 6.0 trở lên,  TOEIC 650 trở lên); và GPA: 7/10 hoặc 3/4 \nCó thể tham gia đào tạo/làm việc Full-time từ thứ 2 - thứ 6 \nHam học hỏi, nhiệt huyết\n\nQuyền lợi\nCó hỗ trợ thu nhập trong thời gian đào tạo. \nSau khi ký HĐLĐ chính thức, mức lương 7 - 11 triệu/ tháng tuỳ thuộc vào kết quả đào tạo và khả năng đáp ứng yêu cầu công việc\nMôi trường làm việc năng động, trẻ trung và đầy sáng tạo \n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà CMC Tower, Phố Duy Tân, Cầu Giấy \n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2251, 1178, 2, 'Thực Tập Sinh - Tư Vấn Triển Khai Phần Mềm (Nhận Việc Ngay)', '(Lĩnh vực Phần mềm, Website, app)\nTư vấn về bố cục, màu sắc, chức năng của trang Website\nLàm việc với khách hàng để xây dựng phương án thiết kế web, app\nLập kế hoạch và xây dựng timeline thiết kế website, app cho team\nHoàn thiện demo giao diện website,app cho khách hàng (sẽ được training, hướng dẫn cụ thể)\nKiểm tra lại web trước khi gửi khách hàng ( đặc tả và test web, app).\nNghiệm thu và hướng dẫn sử dụng.\n\n- Thực Tập Sinh fultime, mới ra trường.\n- Hiểu biết về công nghệ thông tin.\n- Biết làm giao diện web, tester là lợi thế.\n\n- Được hỗ trợ, đào tạo kỹ năng công việc , có thu nhập.\n- Tham gia vào các hoạt động tâp thể, du lịch, teambuilding\n- Hỗ trợ lương (4-10 tr) tùy năng lực.\n\n- Hồ Chí Minh: Lầu 1, tòa nhà SaigonTel, CVPM Quang Trung, Quận 12\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:00 đến 12:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 12', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2252, 1179, 2, 'Fullstack Developer', ' Về dự án C-Agent\nC-Agent là nền tảng quản lý tri thức và ứng dụng GenAI dành cho doanh nghiệp Việt Nam. Sản phẩm giúp doanh nghiệp xây dựng hệ tri thức nội bộ, tự động hóa trả lời câu hỏi từ người dùng, kết nối đa nguồn dữ liệu (Google Drive, Notion, GitHub, API...) và tạo quy trình workflow linh hoạt.\nMục tiêu vai trò\nBạn sẽ tham gia xây dựng và phát triển toàn diện sản phẩm C-Agent, tập trung vào phát triển hệ thống backend chịu tải lớn (API, xử lý dữ liệu, tích hợp AI) và đảm bảo frontend hoạt động hiệu quả, trực quan cho người dùng.\n \nTrách nhiệm chính\n- Thiết kế và phát triển các API hiệu suất cao (RESTful, gRPC) phục vụ AI và ứng dụng web\n- Xây dựng các module backend phức tạp (authentication, authorization, rate limiting, logging, etc.)\n- Tích hợp hệ thống với các dịch vụ AI/LLM và luồng xử lý dữ liệu lớn\n- Làm việc cùng AI Engineer, Product Manager, BA để hiểu yêu cầu nghiệp vụ và xây dựng giải pháp phù hợp\n- Tham gia phát triển frontend (React/Next.js), đảm bảo tính năng và giao diện đồng bộ với backend\n- Đóng góp vào việc tối ưu kiến trúc hệ thống, cải tiến hiệu năng, và nâng cao chất lượng codebase\n\nYêu cầu ứng viên\nYêu cầu bắt buộc\nBackend (Ưu tiên chính):\n- Thành thạo Node.js (NestJS, Express), có thể tối ưu backend cho hệ thống chịu tải lớn\n- Hiểu rõ về kiến trúc Microservices, thiết kế API, xử lý concurrent requests\n- Kinh nghiệm làm việc với cơ sở dữ liệu SQL (PostgreSQL, MySQL) và NoSQL (MongoDB, Elasticsearch)\n- Hiểu về queue systems như Kafka, RabbitMQ, hoặc Redis Pub/Sub\n- Có kinh nghiệm xử lý auth (JWT, OAuth2) và bảo mật API\n \nFrontend (Nắm vững):\n- Kinh nghiệm làm việc với React/Next.js hoặc Vue.js\n- Hiểu cách tối ưu hiệu suất frontend (lazy loading, SSR, caching)\nHệ thống & triển khai:\n- Biết làm việc với Docker, Kubernetes là lợi thế\n- Hiểu CI/CD pipeline, testing (unit/integration test)\n\nQuyền lợi\n-Thu nhập: Lương thỏa thuận theo năng lực, gói thu nhập 13-14 tháng lương/năm.\n- Phúc lợi tiền mặt hơn 9 triệu/năm vào các dịp lễ, tết, sinh nhật tập đoàn.\n- Xét tăng lương định kỳ hằng năm.\n- Bảo hiểm xã hội đầy đủ và bảo hiểm sức khỏe CMC Care.\n- Nghỉ phép: 12 ngày/năm + 1 ngày nghỉ hưởng lương dịp sinh nhật.\n- Đào tạo chuyên môn, tài trợ 100% chi phí học và thi chứng chỉ CNTT quốc tế.\n- Cung cấp laptop/thiết bị công nghệ phục vụ công việc.\n- Môi trường trẻ trung, năng động, chuyên nghiệp.\n- Tham gia team building và các hoạt động văn hóa doanh nghiệp.\n- Nghỉ cuối tuần: Thứ 7 & Chủ Nhật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2253, 1180, 2, 'Kỹ Sư Lập Trình', 'Mô tả công việc:\n- Chèn chương trình vào thiết bị\n- Cải tiến chương trình có sẵn để phù hợp với yêu cầu công nghệ.\n- Lên bom list dự toán thiết bị, điều khiển theo từng máy\n- Viết chương trình PC/Vison\n- Chỉnh sửa lỗi máy khi vận hành phát sinh lỗi liên quan đến phần cứng và phần mềm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp CĐ – ĐH chuyên ngành điều khiển - tự động hóa,…\n- Kinh nghiệm 3 năm trở lên\n- Có kinh nghiệm viết và chỉnh sửa chương trình PC\n- Có Kinh nghiệm viết chương trình C++, C# để điều khiển PC và PLC\n- Có khả năng lập trình với ít nhất một trong các ngôn ngữ sau: Python, Java, C++/C, PC/Vision\n- Có kiến thức về các linh kiện hoặc hệ thống điện của máy tự động trong nhà máy sản xuất điện tử.\n- Có kinh nghiệm làm lập trình cho các công ty sản xuất điện tử.\n\nQuyền lợi:\n- Công ty có xe đưa đón miễn phí HN-VP\n- Đóng BHXH ngay từ tháng thử việc\n- Tặng quà các dịp lễ tết, Lương T13, các chế độ phúc lợi khác\n\nĐịa điểm làm việc:\n- Vĩnh Phúc: Công ty TNHH Cammsys Việt Nam, KCN Bá Thiện 1, Bình Xuyên, Bình Xuyên\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vĩnh Phúc', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2254, 1181, 2, 'Nhân Viên Lập Trình Nhúng', 'Mô tả công việc\n- Tham gia phát triển phần mềm điều khiển và quản lý oạt động của vệ tinh cỡ nhỏ\n- Thiết kế và lập trình phần mềm nhúng cho hệ thống OBC (On-Board Computer)\n- Giao tiếp với các cảm biến và module ngoại vi (IMU, GPS, camera, transceiver RF, v.v.)\n- Phát triển giao thức liên lạc giữa các module nội bộ (I2C, SPI, UART) và truyền thông mặt đất\n- Tối ưu hóa hiệu suất, bộ nhớ, và mức tiêu thụ năng lượng cho phần mềm nhúng\n- Viết tài liệu kỹ thuật và hỗ trợ thử nghiệm tích hợp hệ thống (SIT) và kiểm tra môi trường (TVAC, Vibration…)\n- Trao đổi chi tiết hơn khi phỏng vấn.\nYêu cầu ứng viên\n- Tốt nghiệp Đại học chính quy loại Khá trở lên các chuyên ngành Kỹ thuật như Công nghệ thông tin, Hàng không Vũ trụ, Khoa học máy tính, Toán – tin, Điện tử viễn thông,..  \n- Trình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\n- Hiểu về hệ thống nhúng, có kinh nghiệm lập trình C/C++ cho vi điều khiển (ARM, STM32, ATmega, ESP32, v.v.)\n- Có khả năng đọc hiểu sơ đồ mạch điện và datasheet thiết bị  \n- Thành thạo các giao thức truyền thông phổ biến (I2C, SPI, UART,…)\n- Có khả năng sử dụng MATLAB/Simulink để mô phỏng và thiết kế thuật toán điều khiển nhúng (control systems, signal processing, code generation)\n- Ưu tiên: \n- Tiếng Anh có thể làm việc được với chuyên gia nước ngoài\n- Có kinh nghiệm làm việc với RTOS hoặc các hệ điều hành nhúng\n- Có hiểu biết về hệ thống định thời (watchdog, scheduler, RTC, low-power modes…)\n- Biết sử dụng công cụ mô phỏng và kiểm thử phần mềm nhúng\n- Kỹ năng debug tốt trên phần cứng thật (oscilloscope, logic analyzer…)Tiếng Anh tốt (có thể trao đổi, tham gia đào tạo, học tập với chuyên gia nước ngoài)\nQuyền lợi\n- Lương: hấp dẫn, tăng lương theo thâm niên công tác.\n- Thu Nhập lên Tới 30 triệu\n- Thưởng: có nhiều đợt thưởng trong năm. Thưởng lễ 30-4, thưởng ngày truyền thống, thưởng 6 tháng đầu năm, thưởng ngày thành lập công ty, thưởng Tết Dương, thưởng Tết âm (thưởng năm) và các giải thưởng cá nhân khác: Tiên tiến, xuất sắc, tiềm năng, có cố gắng....\n- Hỗ trợ tiền ăn trưa tại căng tin công ty.\n- Có chế độ chăm sóc y tế cho nhân viên và gia đình, du lịch 1 năm/1 lần (trong nước hoặc nước ngoài) và tham gia các hoạt động vui chơi giải trí khác (sinh nhật công ty, sinh nhật các thành viên...)\n- Có cơ hội được làm việc với đối tác nước ngoài, công tác và đào tạo ở nước ngoài\n- Các chế độ BHXH, nghỉ thứ 7, chủ nhật, chế độ phép đầy đủ theo quy định \nĐịa điểm làm việc\n- Hà Nội: Số 37 Phố Thi Sách, Hai Bà Trưng\n- Hà Nội: 15 Trần Xuân Soạn, Hai Bà Trưng.\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2255, 1182, 2, 'Java Developer', 'Mô tả công việc:\n- Phát triển các tính năng mới theo yêu cầu của hệ thống cho khách hàng\n- Trao đổi, làm rõ yêu cầu với BA\n- Thực hiện fix bug được phát hiện trong quá trình phát triển và triển khai.\n\nYêu cầu ứng viên:\n- Ít nhất 1 năm kinh nghiệm phát triển ứng dụng phần mềm bằng ngôn ngữ Java\n- Có kiến thức về OOP, Design Pattern\n- Có kinh nghiệm làm việc với: Spring Framework, Hibernate, JPA\n- Thành thạo một trong các hệ quản trị CSDL quan hệ: Oralce, MySQL\n- Có kinh nghiệm làm việc với các công cụ: Git, maven\n- Năng động, sáng tạo, có khả năng tự nghiên cứu\n- Ưu tiên ứng viên có chứng chỉ quốc tế của Oracle về phát triển ứng dụng Java: Java SE, Java EE\n\nQuyền lợi:\n- Lương tháng 13 \n- Nghỉ phép, nghỉ lễ, Bảo hiểm xã hội, bảo hiểm y tế theo luật lao động\n- Thời gian làm việc: Thứ 2-Thứ 6, từ 8h30-18h00\n\nĐịa điểm làm việc:\n- Hà Nội: 15 hồ xuân hương, Hai Bà Trưng\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2256, 1183, 2, 'Senior Full-Stack Developer', 'Mô tả công việc:\n- Phân tích, thiết kế, xây dựng và duy trì các ứng dụng công nghệ thông tin phục vụ khách hàng và nội bộ.\n- Phát triển các mô-đun mới trên hệ thống có sẵn (POS, ERP) hoặc API trung gian.\n- Tích hợp hệ thống ERP/POS với các dịch vụ bên ngoài thông qua API (payment, FoodApp, e-invoice, Zalo OA...).\n- Phối hợp với Web Developer/Designer để xây dựng giao diện người dùng.\n- Viết tài liệu kỹ thuật và hướng dẫn sử dụng nội bộ.\n- Quản lý source code (Git), tham gia đánh giá code, triển khai môi trường staging/production.\n- Vận hành và đảm bảo hệ thống công nghệ thông tin luôn online để đáp ứng yêu cầu kinh doanh.\n\nYêu cầu ứng viên:\n- Kinh nghiệm từ 2 năm trở lên trong vai trò Full-stack Developer.\n- Thành thạo Python (ưu tiên có kinh nghiệm với Odoo) hoặc Node.js.\n- Thành thạo JavaScript/HTML/CSS, và một framework như React hoặc Angular.\n- Có kinh nghiệm tích hợp API RESTful, OAuth.\n- Hiểu biết cơ bản về CSDL PostgreSQL hoặc MySQL.\n- Kỹ năng phân tích hệ thống, làm việc độc lập và theo nhóm.\n- Ưu tiên nếu từng làm trong ngành bán lẻ/F&B hoặc startup.\n\nQuyền lợi:\n- Được hưởng các chế độ BHXH, thưởng lễ, tết, thưởng lương tháng 13.\n- Được làm trong môi trường trẻ, năng động.\n- Được tham gia các hoạt động đoàn thể của Công ty: Teambuilding, thăm quan, du lịch...\n- Mua sản phẩm với giá ưu đãi.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 38 Hoa Mai, Phú Nhuận\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2257, 1184, 2, 'Senior Java (Backend Developer)', 'Mô tả công việc:\n- Làm việc với những dự án sản phẩm công nghệ của công ty và đối tác.\n- Phân tích giải pháp, xác định các yêu cầu về hệ thống, tính năng của sản phẩm.\n- Lập kế hoạch, xây dựng phương án, công cụ code đối với từng sản phẩm.\n- Báo cáo thường xuyên về kết quả làm việc với nhóm và cấp trên.\n- Quản lý chất lượng sản phẩm đạt đúng yêu cầu đề ra.\n\nYêu cầu ứng viên:\n- Có từ 3 năm kinh nghiệm trở lên trong việc phát triển Web Service.\n- Nắm vững kiến thức và có kinh nghiệm làm việc với Java core, JavaEE, Spring MVC/ Boots, Hibernate.\n- Hiểu rõ về SQL và NOSQL.\n- Đã làm qua các dự án với mô hình Microservice, MVC.\n- Có kiến thức chuyên sâu về OOP và Design pattern.\n- Có kinh nghiệm liên quan đến vấn đề performance và security của hệ thống.\n- Có kiến thức về unit test, integration test,...\n- Biết qua HTML5, CSS3, JS, có kinh nghiệm với ReactJS là một điểm cộng.\n- Thành thạo các câu lệnh và cách quản lý source repository trên GIT, có kinh nghiệm review code là một lợi thế.\n- Có kiến thức về quy trình phát triển phần mềm.\n- Chấp nhận những thử thách mới và không ngại khó.\n- Có khả năng lãnh đạo và mong muốn trở thành Leader, Manager.\n\nQuyền lợi:\n- Chính sách bảo hiểm xã hội, bảo hiểm y tế theo quy định của Nhà nước.\n- Bảo hiểm sức khỏe PVI sau 01 năm làm việc.\n- Môi trường làm việc trẻ trung, năng động, thân thiện.\n- Cơ hội làm việc onsite tại Nhật Bản.\n- Thường xuyên tổ chức các seminar do chính nhân viên công ty thực hiện, tạo điều kiện nghiên cứu, trao đổi, phát triển.\n- Được hướng dẫn tận tình, tạo nhiều cơ hội phát triển, thăng tiến trong công việc.\n- Hỗ trợ tiền nhà ở trong bán kính 2km.\n- Hỗ trợ chi phí gửi xe và các tiện ích khác.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Vinhome Grand Park, Nguyễn Xiển, Phường Long Thạnh Mỹ, Quận 9\n- Hồ Chí Minh: Charmingtin La Pointe, 181 Cao Thắng, Phường 12 0, Quận 10\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 9, Quận 10', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2258, 756, 2, 'Chương Trình Tuyển Dụng Và Đào Tạo Fresher Android Developer', 'Apero TechTrek là chương trình đào tạo Kỹ sư phần mềm Android dành cho các bạn sinh viên tài năng trong ngành công nghệ thông tin. Chương trình được thiết kế với các module đào tạo kiến thức chuyên ngành từ cơ bản đến chuyên sâu; kỹ năng ứng dụng kiến thức vào vận hành dự án thực tế. Trong chương trình, học viên sẽ được đào tạo dưới sự hướng dẫn và cố vấn trực tiếp bởi các Trưởng phòng và các chuyên gia Phát triển Phần mềm tại Apero Technologies Group.\n- Đào tạo có lương, được hưởng các cơ chế đãi ngộ như nhân sự Apero.\n- Review tăng lương sau khi kết thúc khóa đào tạo (6 tháng)\n- Được hướng dẫn trực tiếp bởi các Trưởng phòng và các chuyên gia Phát triển sản phẩm dày dạn kinh nghiệm phát triển hệ sinh thái các sản phẩm với hơn 500M lượt tải và hơn 100M người dùng hàng tháng.\n- Có cơ hội trở thành nhân viên chính thức sau 1 tháng đào tạo tập trung và tham gia thực chiến trực tiếp vào các Global Project.\n- Tham gia dự án thực tế quy mô lớn, với hàm lượng công nghệ cao, giúp nâng cao kỹ năng chuyên môn, tư duy sáng tạo, và làm quen với quy trình phát triển phần mềm chuyên nghiệp.\n\nMÔ TẢ CÔNG VIỆC\nTrở thành Fresher Android Developer sau 6 tháng đào tạo với lộ trình:\n\nGIA NHẬP APERO:\nTổng quát: Hòa nhập với môi trường Apero và những kiến thức cơ bản về android\n\nĐÀO TẠO TẬP TRUNG ( Trong 1 tháng)\n- Nắm vững ngôn ngữ lập trình Kotlin\n- Nắm vững cách thiết kế giao diện trong Jetpack Compose\n- Nắm vững quy trình quản lý phiên bản và quản lý dự án với Git/Github\n- Ứng dụng AI trong lập trình\n- Tạo ra một ứng dụng hoàn chỉnh\n\nTRẢI NGHIỆM DỰ ÁN THỰC TẾ (5 tháng tiếp theo, các bạn sẽ được làm:)\n- Tạo ra các thành phần giao diện phức tạp\n- Ứng dụng một số Design Pattern quan trọng\n- Ứng dụng mô hình kiến trúc MVI Architecture\n- Thúc đẩy kỹ năng làm việc nhóm\n- Ứng dụng AI Agent nâng cao, giúp làm việc và học hỏi hiệu quả\n- Được phát triển các dự án thực tế, mang lại doanh thu cho công ty.\n\nYÊU CẦU ỨNG VIÊN\n- Sinh viên năm cuối hoặc đã tốt nghiệp Đại học dưới 1 năm, chuyên ngành về Công nghệ Thông tin.\n- Có thể làm toàn thời gian.\n- Sở hữu kiến thức nền tảng công nghệ vững thể hiện qua kết quả học tập, giải thưởng, dự án thực tế...\n- Khả năng tự học và chủ động cao trong công việc.\n\nQUYỀN LỢI\n- Đào tạo có lương, được hưởng các cơ chế đãi ngộ như nhân sự Apero.\n- Review tăng lương sau khi kết thúc khóa đào tạo (6 tháng).\n- Được hướng dẫn trực tiếp bởi các Trưởng phòng và các chuyên gia Phát triển sản phẩm dày dạn kinh nghiệm phát triển hệ sinh thái các sản phẩm với hơn 500M lượt tải và hơn 100M người dùng hàng tháng.\n- Có cơ hội trở thành nhân viên chính thức sau 1 tháng đào tạo tập trung và tham gia thực chiến trực tiếp vào các Global Project.\n- Tham gia dự án thực tế quy mô lớn, với hàm lượng công nghệ cao, giúp nâng cao kỹ năng chuyên môn, tư duy sáng tạo, và làm quen với quy trình phát triển phần mềm chuyên nghiệp.\n\nĐỊA ĐIỂM LÀM VIỆC\n- Hà Nội: Tòa Taisei Square, 289 Khuất Duy Tiến, Cầu Giấy, Cầu Giấy.\n\nTHỜI GIAN LÀM VIỆC\n- 8:30 - 18:00, nghỉ trưa 1h30’, làm việc từ Thứ 2 - Thứ 6.\n\nCÁCH THỨC ỨNG TUYỂN\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2259, 1185, 2, 'C++ Developer', 'Mô tả công việc\n- Design, develop, and maintain high-performance C++ applications.\n- Collaborate with cross-functional teams to define, design, and ship new features.\n- Optimize existing code for performance and scalability.\n- Conduct code reviews and provide constructive feedback to team members.\n- Troubleshoot and debug applications to ensure optimal functionality.\n- Stay updated with the latest industry trends and technologies related to C++ development.\n- Mentor junior developers and assist in their professional growth.\n\nYêu cầu ứng viên\n- Proven experience as a C++ Developer, with a strong portfolio of projects.\n- Work independently (acquired another piece of software written in C++ which he is now selling to his clients)\n- In-depth knowledge of C++ programming language and its standard libraries.\n- Experience with software development methodologies such as Agile or Scrum.\n- Familiarity with version control systems, preferably Git.\n- Strong problem-solving skills and the ability to work independently.\n- Excellent communication and teamwork skills.\n- English: Fluent (at least upper-intermediate level)\n- Start date: ASAP\n- Location: Remote Dedicated Fulltime (Not prefer 2nd Job)\n- Working hours: GTM+7\n\nQuyền lợi\n- 35.000.000 - 50.000.000đ/tháng\n- Working in one of the Best Places to Work in Vietnam\n- Building large-scale & global software products\n- Working & growing with Passionate & Talented Team\n- Diverse careers opportunities with Software Outsourcing, Software Product Development, IT Solutions & Consulting\n- Attractive Salary and Benefits\n- Two performance appraisals every year and performance bonus\n- Onsite opportunities: short-term and long-term assignments in North American (U.S, Canada), Europe, Asia.\n- Flexible working time\n\nĐịa điểm làm việc\n- Hồ Chí Minh\n- Hà Nội\n- Bình Dương\n- Đà Nẵng\n- Thừa Thiên Huế\n- Hải Phòng\n- Bắc Ninh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 14:00 đến 23:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh & 6 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2260, 1186, 2, 'PHP Developer (CodeIgniter 4, Laravel)', 'Mô tả công việc:\n- Phát triển các sản phẩm về thanh toán chuyển khoản ngân hàng và thẻ\n- Làm việc và tích hợp API với các ngân hàng và đối tác chiến lược.\n- Phát triển plugin, SDK cho các hệ thống khác sử dụng.\n- Thực hiện các công việc được giao theo sự phân công của cấp trên.\n\nYêu cầu ứng viên:\n- Nam từ 23 tuổi - Đã tốt nghiệp (Đại học, Cao đẳng).\n- Có từ 2 năm kinh nghiệm trở lên ở vị trí tương đương.\n- Ưu tiên ứng viên đã từng làm việc với ngân hàng và cổng thanh toán.\n- Thành thạo framework PHP: CodeIgniter 4, Laravel.\n- Thành thạo với CSDL MySQL, Bootstrap, jQuery.\n- Ưu tiên ứng viên có khả năng sử dụng AI để tăng hiệu năng làm việc.\n- Ưu tiên ứng viên có kinh nghiệm viết test case thành thạo.\n- Có khả năng phát triển ứng dụng PHP không cần dùng framework, nắm rõ cú pháp PHP cơ bản.\n- Có khả năng làm việc độc lập, tinh thần trách nhiệm cao.\n\nQuyền lợi:\n- Thu nhập từ 17 đến 25 triệu/tháng bao gồm lương cứng + OT (nếu có).\n- Review tăng lương định kỳ theo năng lực và kết quả làm việc.\n- Thưởng 4 ngày Lễ, Lương tháng 13, thưởng cuối năm, du lịch hàng năm.\n- Hỗ trợ khám sức khỏe định kỳ, thưởng sinh nhật, cưới hỏi, điện thoại và nhiều phúc lợi khác theo level.\n- Chế độ BHYT, BHXH, BHTN theo quy định pháp luật.\n- Môi trường làm việc trẻ trung, năng động và sáng tạo.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 168 - 170 Đường số 2, Vạn Phúc City, P. Hiệp Bình Phước, Thủ Đức.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2261, 209, 2, 'Sap Abap Developer', 'Offshore or onsite ABAP development for implementation/ roll-out/ development/ AMS projects\nReview functional specification (FS) and suggest appropriate technical solution\nWrite technical specification (TS) based on FS\nStrictly adhere to development guidelines for ABAP development\nConduct peer review to guarantee adherence to guidelines and templates\nWrite Unit Test Specification (UTS) and perform Unit Testing (UT)\nRecommend end-to-end technical solutions to improve business processes\nArticulate and manage consultation sessions with functional consultants and end-users\nManage, keep track and follow up on assigned tasks promptly, and escalate countermeasures to supervisor\nWork independently and proactively\nStrong commitment to deliver solutions on time\nFollow documentation processes and guidelines\nMaintain high development quality\nMaintain strong working relationship with peers from all locations\nEnsure proper documentation and provide knowledge transfer to support members\n\nYêu cầu ứng viên\nMandatory:\nỨng viên ngồi ở mọi size: HN, HCM, DN, Nha Trang…\nAt least 4+ years of experience in ABAP and object oriented programming\nExperience in RICEF development in ABAP language (Reports, Interfaces, Conversions, Enhancements, Forms)\nExperience in both Procedural and Object Oriented Programing\nExperience in ECC 6.0 and S/4HANA for at least one of the following modules: FICO/ MM/ SD/ PP/ PM/ HCM\nIn-depth understanding of the Software Development Life Cycle (SDLC)\nDetail-oriented with strong organizational skills\nWork well with minimal supervision and able to deliver results under pressure\nAble to work in a fast-paced and team-oriented environment\nGood English Speaking or Good Japanese is a must\n\nOthers:\nExperience with OData Gateway, CDS View, SAP BTP, CPI, Fiori, Adobe Forms, BW/BO, PI/PO, SAP Workflows and performance tuning is a plus\nSAP Global Certification is a plus\n\nQuyền lợi\n• Competitive salary, Commensurate with your position and contribution\n• " FPT care" health insurance providaed by AON and is exclusive for FPT employees.\n• Annual Summer Vacation: follows company\'s policy and starts from May every year\n• International, dynamic, friendly working environment\n• Annual leave, working conditions follow Vietnam labor laws.\n• Other allowances: lunch allowance, working on-site allowance, etc\n\nĐịa điểm làm việc\n- Đà Nẵng\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2262, 1130, 2, 'Thực Tập Sinh IT - Không Yêu Cầu Kinh Nghiệm', 'Chương trình được thiết kế với định hướng giúp thực tập sinh phát triển toàn diện về kỹ năng, tư duy và kinh nghiệm thực tế trong lĩnh vực lập trình. Thông qua môi trường học tập chuyên nghiệp, sự dẫn dắt từ các mentor giàu kinh nghiệm và cơ hội tham gia các dự án thực tế, eUp Group mong muốn:\n\n- Mang lại trải nghiệm học tập và làm việc thực tế, giúp sinh viên tự tin hơn khi bước vào thị trường lao động\n- Khơi dậy và khai thác tối đa sự sáng tạo, chủ động của các bạn trẻ ngay từ những bước đầu sự nghiệp\n- Cung cấp nền tảng kỹ thuật vững chắc để tham gia phát triển các sản phẩm công nghệ có giá trị\n- Đồng hành cùng những thực tập sinh xuất sắc nhất và mở ra cơ hội trở thành nhân sự chính thức tại eUp Group và trực tiếp được phát triển sản phẩm mới có giá trị.\n- Thời gian: Tháng 6/2025\n- Thời lượng: 2 buổi/tuần (có mặt tại văn phòng)\n- Lộ trình chi tiết theo mô hình bootcamp kéo dài 3-4 tháng\n- Tài liệu về coding best practices cho các ngôn ngữ lập trình liên quan\n- Hình thức: fulltime hoặc part-time\n\nYêu cầu ứng viên:\n- Sinh viên năm 3,4 của các trường: Đại học Bách Khoa Hà Nội, Đại học Công nghệ, Đại học Bưu chính viễn thông,...\n- Theo học chuyên ngành Công nghệ thông tin (GPA: từ 3.2 trở lên)\n- Có mong muốn trau dồi kiến thức vững chắc về lập trình (Fullstack) và tìm kiếm cơ hội phát triển sự nghiệp theo hướng IT\n- Có kiến thức về thuật toán và có khả năng giải thuật tốt\n- Có thể đăng ký tham gia fulltime/parttime, thời gian linh hoạt.\n\nQuyền lợi:\n- Có hỗ trợ dấu thực tập và có hỗ trợ tài chính cho thực tập sinh tham gia vào dự án thực tế tại eUp\n- Cơ hội tham gia vào các dự án thực tế: eUp sẽ thiết kế các dự án thực tế có giá trị cho đội ngũ thực tập sinh tham gia để phát triển kỹ năng và đánh giá năng lực\n- Được đào tạo bởi chuyên gia đầu ngành Công nghệ thông tin\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Làm việc tại trường product đi sâu chuyên môn về mobile app, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác marketing, sales, chăm sóc khách hàng và khách hàng\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng\n\nĐịa điểm làm việc:\n- Hà Nội: 315 Trường Chinh, Thanh Xuân\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2263, 1187, 2, 'Frontend Developer (VueJS) Middle', 'Mô tả công việc\n- Support for development using UI Dev.\n- Skills with Vue.js, Javascript, Typescript, HTML, css,…\n- Experienced of Lego Enterprise framework and OPUS.\n- Interpreting, analyzing and implementing client’s requests.  \n- Performing quality verification including code review, code inspection, performance test, etc…\n\nYêu cầu ứng viên\n- At least 3 years of frontend experience, with strong expertise in Vue.js\n- Work to match the web standard and accessibility of what web designers design.\n- Creating and editing websites through web design work and coding. \n- Creating and editing websites through web design work and coding. \n- Experience developing pages using vue.js on mobile devices (Android, IOS – Hybrid app).\n- Developers are required to have skills in testing and code review.\n\nQuyền lợi\n- Salary: Negotiate.\n- Package: At least 13 months/ year. Review periodically following company policy.\n- Bonus: Tet bonus, project bonus, holiday bonus, HR referral bonus...\n- Seniority allowance (working time from 2 years or more).\n- Participate in learning and training activities inside and outside the company, accumulate learning points, develop G-Points on the company\'s management system.\n- 2 days of per week and 12 leave days per year.\n- Clubs and many cultural - sports - art activities sponsored or supported by the company (For example: Football, table tennis, badminton, swimming, music, English, games... )\n- Ensure health: Periodic health check, support to buy high quality health insurance...\n- Join the Rikkei Care Health Insurance Plan.\n- Mental comfort: Playing music on demand every day, happy hour, team building activities...\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Đăng ký linh hoạt 8:00 - 9:00 đến 17:00 - 18:00 từ Thứ 2 - Thứ 6\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2264, 1188, 2, 'Lập Trình Viên Phần Mềm DEV PHP', '- Develop, customize and maintain modules on Vtiger CRM systems.\n- Design and deploy features and integrations within the Vtiger CRM system, including APIs and other software solutions.\n- Collaborate with internal teams to analyze and implement technical solutions related to customer data management.\n- Ensure data accuracy and integrity within the system.\n- Provide technical support and troubleshoot issues related to the system.\n- Create and maintain documentation related to CRM system architecture, configuration and customization with high security.\n\nYêu cầu ứng viên:\n- Có từ 3 năm kinh nghiệm ở vị trí tương đương, từ 27 tuổi trở lên.\n- Stay up-to-date with CRM software industry trends and best practices.\n- Technologies used: PHP, JavaScript, Smarty, MySQL, Nodejs, Jquery, SocketIO, Webhook, API, Git…\n\nQuyền lợi:\n- Thu nhập: Lương cứng (từ 10 triệu) + các loại phụ cấp: ăn trưa, di chuyển, điện thoại…\n- Tham gia các hoạt động vui chơi, du lịch của công ty theo tuần, quý, năm.\n- BHYT, BHXH, phép năm… đầy đủ theo đúng quy định.\n- Thưởng tháng T13, thưởng các dịp Lễ - Tết theo chính sách của Công ty.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Ree Tower, Quận 4.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2265, 1189, 2, 'Java Developer (4 Năm Kinh Nghiệm)', 'Mô tả công việc:\n- Phát triển phần mềm, thực hiện kiểm thử nội bộ, viết tài liệu kỹ thuật và triển khai ứng dụng trên các môi trường khác nhau\n- Phân tích nguyên nhân sự cố, tối ưu từ người dùng hoặc các ứng dụng tích hợp của đối tác, đề xuất phương án xử lý tối ưu.\n- Tham gia phân tích, thiết kế và đưa ra giải pháp kỹ thuật dựa trên tài liệu yêu cầu nghiệp vụ.\n- Xác định và rà soát các vấn đề thường xuyên phát sinh lỗi, xây dựng phương án khắc phục triệt để và giám sát thực thi.\n- Phối hợp với các thành viên trong đội dự án (BA, QA, DevOps, Product Owner,...) để hoàn thiện sản phẩm.\n- Nghiên cứu nâng cấp bản thân để cập nhật các công nghệ, thiết kế mới.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học trở lên chuyên ngành Khoa học Máy tính/ Công nghệ thông tin hoặc tương đương\n- Từ 4 năm lập trình Java/Spring Boot, đã từng triển khai 2-3 dự án\n- Thuần thục Java Core: OOP, multi-threading, collections, exception handling\n- Spring Boot: Dependency Injection, Bean Lifecycle, Configuration\n- JPA: Entity Mapping, Query Performance, Transaction Management\n- Có kinh nghiệm áp dụng Design Pattern & Principle cơ bản: SOLID, Factory, Singleton, Strategy, Repository\n- Kinh nghiệm làm bảo mật, Spring Security: Authentication, Authorization, JWT, OAuth2\n- SQL & Database: Indexing, Query Optimization, ACID, Transaction\n- Phát triển và vận hành các hệ thống với tải cao: caching, loadbalance, Parallel Processing, Monitoring and Performance Tuning, Scalability, Testing and Benchmarking\n- Kinh nghiệm làm việc hoặc có kiến thức trong môi trường áp dụng DevOp. Hiểu rõ các khái niệm quan trọng như CICD, infrastructure as code, Containerization, orchestration.\n\nQuyền lợi:\n- Gói thu nhập đến 16 tháng lương/ năm\n- Xét tăng lương theo năng lực và kết quả công việc định kỳ 1 lần/ năm hoặc tăng lương đột xuất theo hiệu quả công việc\n- Chế độ Bảo hiểm sức khỏe cho bản thân và người nhà\n- Nghỉ thứ Bảy, Chủ nhật hàng tuần\n- Du lịch, Teambuilding/ dã ngoại định kỳ hàng năm\n- Chế độ mừng sinh con, quà nhân ngày Lễ/ Tết, quà ngày truyền thống và các chế độ phúc lợi khác\n- Tham gia các khóa đào tạo chuyên môn, nâng cao kỹ năng thực hiện công việc, kỹ năng mềm và thi các chứng chỉ CNTT Quốc tế miễn phí tại Công ty\n- Được tham gia các chương trình đào tạo trước khi bắt đầu công việc và trong quá trình làm việc theo yêu cầu công việc\n- Chính sách phát triển, thăng tiến có lộ trình theo từng vị trí, từng phòng ban.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2266, 1131, 2, 'Junior Dev', 'Mô tả công việc:\n- Phát triển và triển khai các phần mềm, giải pháp AI Automation để tự động hóa quy trình trong doanh nghiệp\n- Nghiên cứu và tích hợp các giải pháp AI Automation vào quy trình làm việc của doanh nghiệp\n- Tham gia các dự án tự động hóa quy trình doanh nghiệp bằng các nền tảng Low-code/No-code như: Power Automate, Power Apps (Microsoft), Oracle Apex và các nền tảng tự động hóa khác theo yêu cầu\n- Tích hợp dữ liệu từ các hệ thống như KiotViet, Google Analytics, Facebook Ads, Shoppe, Tiktok Shop, Misa, Bravo…. và các nền tảng khác thông qua API.\n- Xây dựng các pipeline dữ liệu tự động, đảm bảo thu thập và đồng bộ hóa dữ liệu một cách chính xác và liên tục.\n- Phối hợp với các bộ phận liên quan để xác định yêu cầu và triển khai giải pháp.\n- Báo cáo định kỳ về tiến độ và kết quả công việc.\n\nYêu cầu ứng viên:\n- Đã tốt nghiệp công nghệ thông tin hoặc chuyên ngành kỹ thuật liên quan\n- Có 6 tháng kinh nghiệm trở lên trong lập trình hoặc phát triển giải pháp tự động hóa.\n- Thành thạo ít nhất một ngôn ngữ lập trình như Python, Java, Node.js, hoặc JavaScript.\n- Kinh nghiệm làm việc với API từ các nền tảng như KiotViet, Google Analytics, Facebook Ads….\n- Hiểu biết về công cụ Low-code/No-code như Power Automate, Power Apps, Oracle Apex là một lợi thế lớn\n- Kỹ năng làm việc với cơ sở dữ liệu như Oracle, SQL Server, MySQL, PostgreSQL, hoặc MongoDB.\n- Đọc hiểu tài liệu kỹ thuật tiếng Anh là một lợi thế.\n- Có khả năng tìm kiếm, nghiên cứu và nắm bắt công nghệ mới.\n- Chủ động trong công việc.\n\nQuyền lợi:\n- Lương + Thưởng cuối năm, thưởng dự án, 13 tháng lương\n- Cung cấp Laptop/ PC\n- Được đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- Ngoài ra, thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Phụ cấp gửi xe; ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Phụ cấp cơm trưa, bảo hiểm sức khỏe, khám sức khỏe định kỳ 1 lần/năm, du lịch nghỉ mát 1 lần/ năm.\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động\n- Nghỉ Thứ 7, Chủ nhật, 12 ngày phép/ năm\n- Tổ chức teambuilding.\n- Tổ chức tham quan, nghỉ mát.\n- Cung cấp đồ ăn nhẹ, trà và cà phê miễn phí.\n- Cơ hội thăng tiến vào các vị trí quản lý công nghệ cấp cao đối với những thành viên xuất sắc.\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Tổ chức sinh nhật, team lunch, ...\n- Review lương 1 năm / 1 lần.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2267, 1190, 2, 'Chief Technology Officer', 'Mô tả công việc\n- Theo dõi các xu hướng công nghệ mới (AI, Blockchain, Cloud, DevOps…) và chủ động đánh giá, lựa chọn, xây dựng & triển khai các giải pháp công nghệ phù hợp với định hướng phát triển của công ty.\n- Định hướng và xây dựng lộ trình ứng dụng các công nghệ mới (đặc biệt là AI) vào từng khâu của quy trình phát triển và vận hành, nhằm tối ưu hiệu suất, tăng năng suất lao động và nâng cao chất lượng sản phẩm/dịch vụ.\n- Thiết lập và quản lý ngân sách công nghệ ở cả cấp công ty và dự án, kiểm soát chi phí đầu tư và vận hành, đảm bảo sử dụng nguồn lực hiệu quả và tối ưu hóa giá trị mang lại cho doanh nghiệp.\n- Xây dựng, triển khai và giám sát các chính sách, quy trình bảo mật hệ thống, đảm bảo tuân thủ nghiêm ngặt các tiêu chuẩn quốc tế về an toàn thông tin (ví dụ: ISO 27001, GDPR…) và liên tục cập nhật phù hợp với quy định mới.\n- Chủ động giám sát, đánh giá và quản trị các rủi ro công nghệ. Xây dựng, cập nhật và triển khai kịch bản ứng phó sự cố nhằm đảm bảo hệ thống vận hành liên tục, hạn chế tối đa rủi ro và thiệt hại cho doanh nghiệp.\n- Làm việc chặt chẽ với khách hàng để hiểu rõ nhu cầu của họ, đồng thời cung cấp tư vấn kỹ thuật chuyên sâu và giải pháp phù hợp, đảm bảo các giải pháp đề xuất đáp ứng mục tiêu kinh doanh cũng như yêu cầu kỹ thuật của khách hàng.\n- Dẫn dắt việc thiết kế và xây dựng kiến trúc cho các hệ thống và ứng dụng phức tạp.\n- Đảm bảo toàn bộ tài liệu kỹ thuật được cập nhật đầy đủ và chính xác.\n- Dẫn dắt và cố vấn cho đội ngũ công nghệ, xây dựng văn hóa đổi mới sáng tạo và không ngừng cải tiến.\n- Tham gia tuyển dụng, đào tạo và giữ chân các nhân tài kỹ thuật tại công ty.\n\nYêu cầu ứng viên\n- Có kinh nghiệm đảm nhiệm vai trò CTO hoặc vị trí lãnh đạo công nghệ cấp cao, ưu tiên trong các công ty chuyên về gia công phần mềm (IT outsourcing).\n- Nền tảng vững chắc về thiết kế hệ thống, kiến trúc và phát triển phần mềm.\n- Có khả năng nhận diện, đánh giá, quản trị và xây dựng kịch bản phòng ngừa, ứng phó rủi ro công nghệ. Tư vấn giải pháp kỹ thuật cho khách hàng và đảm bảo kết quả triển khai đạt chất lượng cao.\n- Có kinh nghiệm quản lý dự án và dẫn dắt các nhóm đa chức năng.\n- Kinh nghiệm xây dựng, phát triển đội ngũ kỹ thuật, khả năng truyền cảm hứng, giải quyết xung đột và giữ chân nhân tài.\n- Có kinh nghiệm thực chiến xử lý sự cố sản xuất, đảm bảo hệ thống hoạt động liên tục.\n- Kỹ năng giải quyết vấn đề xuất sắc và tư duy chủ động trong việc xử lý thách thức.\n- Am hiểu các xu hướng công nghệ mới nhất và các thông lệ tốt nhất trong ngành CNTT. Từ đó, định hướng và triển khai roadmap công nghệ và chuyển đổi số, đặc biệt là các chiến lược ứng dụng AI để nâng cao hiệu suất sản xuất.\n- Kỹ năng giao tiếp và ứng xử xuất sắc, thông thạo tiếng Anh.\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật hoặc lĩnh vực liên quan; có bằng MBA hoặc các văn bằng sau đại học liên quan là một lợi thế.\n\nQuyền lợi\n- Mức lương: Upto 4000$\n- Được đánh giá và xét tăng lương hàng năm theo năng lực và hiệu quả công việc.\n- Thưởng: Thưởng ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch, …) Thưởng theo hiệu quả công việc, kết quả doanh thu\n- Tổng thu nhập: Từ 14 -15 tháng lương/năm.\n- Môi trường làm việc: Nghỉ thứ 7, Chủ nhật, nghỉ Lễ/Tết và nghỉ phép theo Quy định của Pháp luật hiện hành.\n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty.\n- Khám sức khỏe định kỳ 1 năm/1 lần. Bảo hiểm sức khoẻ AMELA CARE ở chương trình cao nhất.\n- Quỹ học tập 3.000.000+/ người/ năm hỗ trợ chi phí thi chứng chỉ, tham gia khoá học.\n- Môi trường trẻ trung, năng động, thẳng thắn trao đổi và chia sẻ, thúc đẩy sự sáng tạo và phát triển.\n- Được tham gia các Câu lạc bộ của Công ty: CLB Bóng đá, Bilac …\n- Được tham gia các hoạt động tập thể sôi động của công ty: Nghỉ mát hàng năm, Teambuilding hàng quý, Gala cuối năm…\n- Cơ hội phát triển: Được sử dụng các nguồn lực của công ty (nhân sự, tài chính) để phục vụ cho việc nghiên cứu và phát triển công nghệ.\n- Được đề xuất hoặc tham gia vào các dự án hoặc business mới của công ty trong tương lai.\n- Được hưởng stock option theo cống hiến.\n- Tham gia vai trò chính trong việc tư vấn, xây dựng dự án từ giai đoạn đầu tiên.\n- Tham gia nhiều chương trình đào tạo công nghệ, phương pháp làm việc.\n- Được tham gia các chương trình đào tạo đa dạng và có nhiều cơ hội thăng tiến.\n- Cơ hội đi công tác tại Nhật Bản.\n\nĐịa điểm làm việc\n- Hà Nội: Tháp A Keangnam, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2268, 1191, 2, 'Backend Developer', 'Mô tả công việc\n- Phát triển, bảo trì và tối ưu hệ thống backend sử dụng Node.js và PHP (tùy dự án).\n- Thiết kế, phát triển và bảo trì hệ thống backend cho các ứng dụng web.\n- Xây dựng và tối ưu RESTful API / GraphQL để kết nối với frontend và các dịch vụ khác.\n- Làm việc với cơ sở dữ liệu (SQL / NoSQL) để lưu trữ, truy xuất và xử lý dữ liệu hiệu quả.\n- Tối ưu hóa hiệu suất và bảo mật của hệ thống backend.\n- Phối hợp chặt chẽ với frontend, QA, UI/UX, DevOps để đảm bảo chất lượng sản phẩm.\n- Tham gia phân tích yêu cầu, thiết kế kiến trúc hệ thống và đánh giá giải pháp kỹ thuật.\n- Viết tài liệu kỹ thuật, unit test và tham gia review code.\nYêu cầu ứng viên\n- Bắt buộc:\n  - GHI RÕ ĐỊA ĐIỂM MONG MUÔN LÀM VIỆC TRÊN CV ỨNG TUYỂN\n  - Có kinh nghiệm phát triển backend với một trong các ngôn ngữ: Node.js (Express.js/NestJS) và/hoặc PHP (Laravel/Lumen/Symfony), Python, Go,...\n  - Thành thạo xử lý API, phân quyền, xác thực (JWT, OAuth2,...).\n  - Làm việc tốt với cơ sở dữ liệu quan hệ (MySQL) và/hoặc NoSQL (MongoDB).\n  - Có tư duy OOP, MVC, hiểu nguyên lý thiết kế phần mềm (SOLID, DRY,...).\n  - Hiểu biết về bảo mật backend: SQL Injection, XSS, CSRF,...\n  - Biết sử dụng Git, Docker, và công cụ quản lý mã nguồn.\n- Ưu tiên (không bắt buộc):\n  - Đã làm việc với các framework như Express.js, Django, Spring Boot, Laravel,...\n  - Có kiến thức về authentication (JWT, OAuth2), bảo mật web (OWASP, CSRF, XSS,...) và tối ưu hiệu suất backend.\n  - Kinh nghiệm với message queue (RabbitMQ, Kafka), caching (Redis, Memcached).\n  - Biết triển khai CI/CD hoặc từng làm việc với các nền tảng cloud (AWS, GCP, Azure).\n- Trình độ:\n  - Tốt nghiệp Đại học/Cao đẳng ngành CNTT, Khoa học máy tính hoặc tương đương.\n  - Hoặc có kinh nghiệm thực tế qua dự án cá nhân hoặc freelance.\nQuyền lợi\n- Thu nhập: 15 triệu – 25 triệu/tháng\n- Đóng đầy đủ BHXH theo quy định của pháp luật\n- Thưởng các ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch, ...)\n- Nghỉ Lễ/Tết, 12 ngày phép/năm và nghỉ phép theo Quy định của Pháp luật hiện hành.\n- Các chế độ phúc lợi khác theo quy định của Công ty;\n- Cung cấp thiết bị làm việc.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp trẻ trung, năng động, tích cực\n- Được lựa chọn địa điểm làm việc:\n  - Địa điểm 1: V1- A02 Khu đô thị mới An Hưng, Dương Nội, Hà Đông, Hà Nội\n  - Địa điểm 2: TechnoPark Tower, xã Đa Tốn, Gia Lâm, Hà Nội (ưu tiên làm việc tại đây)\nĐịa điểm làm việc\n- Hà Nội: V1- A02 Khu đô thị mới An Hưng, Dương Nội, Hà Đông\n- Hà Nội: TechnoPark Tower, xã Đa Tốn, Gia Lâm\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2269, 1192, 2, 'Nhân Viên Lập Trình Gia Công Phay CNC', 'Mô tả công việc\n- Setup máy phay Cnc gia công sản phẩm mẫu \n- Lập trình Phay cnc gia công sản phẩm \n- Làm setup sheet cho sản phẩm phay\n- Tạo quy trình công nghệ cho sản phẩm phay\n- Tạo các tài liệu kỹ thuật\n- Có khả năng hướng dẫn đào tạo nhân lực cho phòng kỹ thuật\n- Báo cáo công việc hằng tuần (ngày) qua mail\n\nYêu cầu ứng viên\n- Sử dụng thành thạo máy phay CNC hệ điều hành Fanuc\n- Sử dụng thành thạo phần mềm: MasterCam2020 và có kiến thức về phần mềm thiết kế Soliwork  hoặc Inventor \n\nQuyền lợi\n- Mức lương được thỏa thuận theo năng lực từ 12-18 triệu (lương chưa bao gồm phụ cấp tăng ca)\n- Môi trường làm việc chuyên nghiệp, hỗ trợ, có lộ trình phát triển rõ ràng\n- Cơ hội tham gia công tác hội nghị triển lãm ở các nước Nhật, Mỹ, Hàn, Châu âu hằng năm\n- Thưởng lương tháng 13\n- Công ty hỗ trợ cơm trưa\n- BHXH- BHYT- BHTN, nghỉ lễ, tết, phép năm đầy đủ theo luật lao động\n- Bảo hiểm tai nạn 24h\n- Tổ chức đi du lịch 2 năm / 1 lần\n- Quà khi sinh nhật, kết hôn, sinh con, ...\n- Xét tăng lương định kỳ 1 lần/năm theo năng lực\n- Thưởng các ngày lễ, tết, lương tháng 13\n- Môi trường làm việc thân thiện, năng động và chuyên nghiệp\n\nĐịa điểm làm việc\n- Bình Dương: 144/46 Khu phố 2, Phường Đông Hòa, Thị xã Dĩ An, Dĩ An\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2270, 1193, 2, 'Home Trading System Developer (Frontend - JavaScript)', 'Mô tả công việc:\n- Develop a Trading Desktop Application using JavaScript on an internal platform built with C++.\n- Work directly with remote team to clarify tasks and requirements.\n- Develop new features based on the user requirements. (analyzing requirements and system design).\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance (need to communicate with backend developers and testers).\n- Managing time and resources based on the WBS.\n- Compile a weekly-report about the progress of tasks.\n- Perform self-learning about a domain knowledge, write a report and conduct a seminar about it.\n- Write high-quality, clean, elegant, maintainable, and testable code.\n- Maintaining technical documents up-to-date Mentor junior developers and conduct technical training when needed.\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n\nYêu cầu ứng viên:\nSkill Required:\n- Minimum 3 years experience on developing with Javascript.\n- Strong understanding of object-oriented programming and design pattern (MVC, MVVM).\n- Ability to write clean, easy to understand code.\n- Familiarity with version control systems, such as SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n- Strong problem-solving and analytical skills.\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Able to communicate in English, written and spoken (processed by English interview).\n- Strong communication skills and teamwork, international experience is preferred.\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nGive Reference:\n- Over 1 year of experience in developing securities solutions, including a PC-based trading platform – HTS(Home Trading System).\n- Experience on developing with MFC C++.\n- Experience on working with oversea team.\n\nMission:\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the Kiwoom Framework for Kiwoom Indonesia, Finansia(in Thailand), and so on.\n\nQuyền lợi:\n- Competitive salary, salary review once a year.\n- 13th month salary and Annual Performance Bonus.\n- Full SHUI as Vietnamese Law.\n- PVI - Premium Private Medical Insurance and annual health check.\n- 15-day annual leave, Christmas leave and 30-mins menstrual leave for women.\n- MVP and Shining star awards at the end of year.\n- Global and professional working environment.\n- Company trip, YEP and monthly gathering time.\n- Gifts on special occasion and fully stocked snack corner.\n- Sponsored training courses and book purchase quarterly.\n- Be well-equipped with new working equipment.\n\nSPECIAL OFFER:\n- Providing training and education experience in Korea with Korean Finance/IT expert.\n- Providing opportunities to work and support in IT/Finance fields overseas.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tầng 14, tòa nhà AP, 518B Điện Biên Phủ, Phường 21, Bình Thạnh.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2271, 1194, 2, 'Java Developer (Junior)', 'Mô tả công việc\n- Tham gia các dự án phát triển và triển khai các giải pháp cho công ty và đối tác\n- Tham gia và hoàn thành đúng yêu cầu các dự án được giao.\n- Thực hiện đúng chế độ lập kế hoạch và báo cáo công việc theo quy định.\n- Thực hiện công việc khác theo chỉ đạo và yêu cầu của người quản lý trực tiếp.\n\nYêu cầu ứng viên\n- Trình độ: Tốt nghiệp ĐH chuyên ngành công nghệ thông tin\n- Kinh nghiệm làm việc: \n+ Có kinh nghiệm tham gia các dự án phát triển trên nền tảng Java\n+ Có khả năng phân tích yêu cầu nghiệp vụ để phát triển chức năng hệ thống\n+ Có kinh nghiệm sử dụng framework như: Spring, Hibernate...\n+ Có kinh nghiệm với Angular JS, React Js ...\n+ Có kiến thức về cơ sở dữ liệu như: Oracle, MySQL, MongoDB,...\n- Kỹ năng:  \n+ Khả năng giao tiếp, truyền đạt tốt\n+ Kỹ năng làm việc nhóm và làm việc độc lập\n+ Kỹ năng tổ chức và quản lý thời gian\n+ Khả năng làm việc dưới áp lực\n- Thái độ:  Chăm chỉ, nhiệt tình, hòa đồng và có trách nhiệm trong công việc.\n- Trách nhiệm đảm bảo an toàn thông tin: Tuân thủ các quy định, quy chế về an toàn thông tin của Công ty\n\nQuyền lợi\n- Mức lương: 8-20tr\n- Lương tháng thứ 13, thưởng lễ tết, thưởng hiệu quả kinh doanh theo quy định và theo kết quả kinh doanh của Công ty\n- Chế độ bảo hiểm xã hội đầy đủ theo quy định của pháp luật.\n- Tham gia các chương trình Teambuilding khác tại công ty\n- Tham gia các chương trình Sinh nhật, Noel, Year and Party...\n\nĐịa điểm làm việc\n- Hà Nội: 80 Duy Tân, Cầu Giấy\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2272, 1195, 2, 'Full Stack Developer (Node.Js/ReactJs/VueJs)', 'Mô tả công việc:\n- Tham gia phát triển, bảo trì và tối ưu các dự án phần mềm (web/app) của công ty trên cả frontend và backend.\n- Thiết kế, xây dựng và triển khai các tính năng mới theo yêu cầu nghiệp vụ.\n- Phối hợp với các thành viên trong team để xây dựng giải pháp tổng thể, đảm bảo chất lượng sản phẩm.\n- Tham gia phân tích, thiết kế hệ thống, review code, kiểm thử và triển khai sản phẩm.\n- Khắc phục các lỗi, tối ưu hiệu suất hệ thống và đề xuất cải tiến sản phẩm.\n- Thực hiện các công việc khác theo yêu cầu của cấp trên.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành CNTT\n- Có ít nhất 2 năm kinh nghiệm làm Fullstack Developer.\n- Thành thạo ít nhất một ngôn ngữ lập trình backend (Node.js /C#/Python...).\n- Thành thạo ít nhất một framework frontend hiện đại (ReactJS/VueJS/Angular...).\n- Có kinh nghiệm làm việc với cơ sở dữ liệu quan hệ (MySQL/PostgreSQL/MSSQL) và/hoặc NoSQL (Redis...).\n- Hiểu biết về API (RESTful API, WebSocket), authentication/authorization (JWT, OAuth2...).\n- Có kinh nghiệm với Git và quy trình CI/CD cơ bản.\n- Kỹ năng phân tích, giải quyết vấn đề tốt, tư duy logic, cẩn thận trong công việc.\n- Chủ động, trách nhiệm, tinh thần học hỏi và làm việc nhóm tốt.\n- Ưu tiên có kiến thức và kinh nghiệm công nghệ MessageQueue (MQ, Kafka, Rabbit, ActiveMQ..), Microservice; kinh nghiệm về nền tảng Cloud như AWS Cloud, Google Cloud là một lợi thế;  \n- Ưu tiên có kiến thức và kinh nghiệm triển khai về K8s, Docker là một lợi thế;\n\nQuyền lợi:\n1. Lương thưởng cạnh tranh trên thị trường (theo thỏa thuận)\n2. Thời gian làm việc từ 8:30-17:30 các ngày từ thứ 2-6.\n3. Được tham gia đầy đủ các chế độ bảo hiểm theo pháp luật.\n4. Chế độ nghỉ phép 15 ngày/năm.\n5. Chế độ khám sức khỏe định kỳ hàng năm.\n6. Chế độ bảo hiểm nâng cao.\n7. Môi trường làm việc hấp dẫn, có cơ hội học hỏi, thăng tiến cao.\n8. Chế độ nghỉ mát/teambuilding hằng năm\n9. Môi trường làm việc năng động, trẻ trung, nhiều hoạt động gắn kết\n\nĐịa điểm làm việc:\n- Hà Nội: 11 Cửa Bắc, Ba Đình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2273, 209, 2, 'Low-Code Developer', '- We are looking for an enthusiastic and eager Junior Salesforce/Outsystems/Servicenow Developer to join our growing team.\n- This is an excellent opportunity for individuals with a foundational understanding of software development principles who are keen to learn and build applications using the low-code platform.\n- You will work alongside experienced developers, contributing to the development and maintenance of our applications while gaining valuable hands-on experience.\n\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- Basic understanding of software development concepts and methodologies.\n- Familiarity with web technologies such as HTML, CSS, and JavaScript is a plus.\n- Basic knowledge of relational databases and SQL.\n- Strong logical thinking and problem-solving skills.\n- Eagerness to learn and work with the Salesforce/Outsystems/Servicenow platform.\n- Good communication and teamwork skills.\n- Strong analytical and problem-solving skills.\n- Fluency in English (both written and verbal).\n\n- Attractive income package as negotiation.\n- Global and inclusive workplace with monthly cross-cultural events.\n- International exposure and career growth across global locations.\n- Work-life balance benefits supporting employee well-being.\n- Private health insurance with optional family coverage.\n- Summer vacation allowance.\n- Sponsored training courses for personal growth.\n- Comprehensive relocation package.\n\n- Hồ Chí Minh: Lô E3 Đ. Võ Chí Công, Quận 9.\n\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 9', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2274, 1196, 2, 'Thực Tập Sinh IT, Lập Trình Frontend', 'Mô tả công việc:\n- Phối hợp cùng các chuyên gia và giảng viên để chuyển đổi tài liệu học thuật thành bài giảng số, khóa học và các bài kiểm tra tương tác.\n- Sử dụng các công cụ do công ty cung cấp để xây dựng nội dung học tập tương tác, đa phương tiện (video, hình ảnh, âm thanh, game giáo dục) và ứng dụng trên nền tảng web, di động, thiết bị thông minh, bảng thông minh…\n- Sử dụng công cụ tương tác, kéo thả đối tượng để phát triển các game giáo dục, các mô phỏng, thí nghiệm cho các môn Toán, Lý, Hoá, Sinh, Địa, Sử, Ngoại Ngữ…\n- Làm việc và trao đổi cùng đội nhóm để tối ưu hóa hiệu năng và nâng cao trải nghiệm người dùng.\n- Thực hiện các công việc khác theo phân công của công ty.\n\nThực tập sinh sẽ được hướng dẫn và đào tạo bài bản theo một trong hai roadmap tùy chọn:\n- Content Creator: Chuyên xây dựng nội dung bài giảng số, không yêu cầu kỹ năng lập trình sâu.\n- Component Creator: Tham gia lập trình, phát triển ứng dụng và các nội dung tương tác phức tạp hơn (yêu cầu kiến thức và kỹ năng lập trình).\n\nYêu cầu ứng viên:\n- Sinh viên năm 3, 4 đang trong thời gian thực tập hoặc đang chờ bằng; Sinh viên mới ra trường, sinh viên năm cuối Cao đẳng, Đại học chuyên ngành Công nghệ thông tin (phần mềm, thiết kế, lập trình)... hoặc các ngành có liên quan.\n- Có kiến thức cơ bản về lập trình, biết sử dụng một ngôn ngữ lập trình là một lợi thế.\n- Có kiến thức nền tảng về khả năng lập trình OPP.\n- Có tư duy logic tốt.\n- Đam mê học hỏi, chủ động trong công việc, có tinh thần làm việc nhóm tốt.\n\nQuyền lợi:\n- Cơ hội học hỏi, phát triển kỹ năng, làm việc với đội ngũ chuyên gia và có thể được giữ lại làm nhân viên chính thức sau kỳ thực tập.\n- Hỗ trợ: 3 triệu/tháng (bao gồm ăn trưa).\n- Hỗ trợ dấu thực tập.\n- Có khả năng lên chính thức sau 3 tháng thực tập.\n- Nhân viên chính thức được review lương 2 lần/năm + các chế độ phúc lợi hấp dẫn.\n- Được tham gia phát triển Product phục vụ số lượng hàng triệu user.\n- Được ứng dụng các công nghệ mới nhất và là xu hướng hiện tại (AI, IoT, Thiết bị thông minh).\n- Môi trường làm việc startup năng động, thân thiện, chuyên nghiệp.\n- Tạo điều kiện học hỏi phát triển bản thân và các kỹ năng mềm.\n- Lương tháng 13 + thưởng.\n- Đóng BHXH ngay khi ký Hợp đồng lao động.\n\nĐịa điểm làm việc:\n- Hà Nội: Khu Ngoại Giao Đoàn, Xuân Tảo, Bắc Từ Liêm, Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2275, 1197, 2, 'Nodejs Developer', 'Mô tả công việc:\n- Code and test backend services in NodeJS.\n- Design, implement, and/or use RESTful web services Building scalable microservices-based system.\n- Understand the needs of the customer or business and utilize this knowledge to develop applications that are consistent with the specific needs and requests of the customer.\n- Participate in agile software development, prototyping, and code reviews with a small team of developers.\n\nYêu cầu ứng viên:\n- From 3 years of NodeJS experience Experienced in Agile/Scrum development environment\n- Ability to write structured, well-documented and maintainable code\n- Strong background in NodeJS (ES6) Practically experienced with REST APIs design and implementation\n- Expert knowledge of developing projects based on NodeJS and Express framework\n- Practically experienced with MongoDB, Redis and PostgreSQL Solid professional experience in using NodeJS unit testing frameworks (Jest, Mocha, etc.)\n- Good problem-solving and analytical skills English communication\n\n[Nice to have]\n- Experience with AWS services (e.g., S3, ECS, Lambda).\n- Experience with message queuing systems (e.g., Kafka, SQS)\n- Knowledge of containerization and orchestration (e.g., Docker, ECS).\n- Understanding of microservices architecture.\n- Familiarity with authentication and authorization mechanisms (e.g., OAuth, JWT).\n\nQuyền lợi:\n- Very attractive salary with a 13th-month salary\n- Performance bonus based on effort and output\n- Monitor, laptop... will be provided\n- A professional working environment with Agile–Scrum\n- PVI health care program\n- Sports clubs (football, badminton...)\n- Team-building activities, company trip every year\n- Enjoy Relax and beautiful Pantry in the company\n- Periodic health examination\n- Annual sponsored retreat trip\n- PTO / Sick leave\n- Weekly happy dinner, party celebration (Christmas, Birthday,...)\n\nĐịa điểm làm việc:\n- Đà Nẵng: 36 Tran Quoc Toan, Hải Châu\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2276, 1198, 2, 'Mobile Developer Intern (IOS/Android/Flutter)', 'Mô tả công việc\n- Assist in coding basic features of the stock trading application under the guidance of senior developers.\n- Integrate APIs from the backend to display stock data (e.g., stock prices, charts).\n- Perform testing of the application on iOS/Android devices to identify UI or functional issues.\n- Assist in fixing minor bugs as assigned.\n- Update the application’s UI based on designs from the UX/UI team.\n- Prepare simple technical documentation (e.g., API descriptions, setup guides).\n- Explore new technologies related to mobile development (Flutter, NFC, app security) and suggest improvements.\n- Attend team meetings to contribute ideas and learn from team members.\nYêu cầu ứng viên\n- Bachelor’s degree (or final-year student) in Information Technology or a related field.\n- Familiarity with mobile programming languages such as Swift (iOS), Kotlin/Java (Android), or Flutter/Dart (cross-platform).\n- Basic understanding of Object-Oriented Programming (OOP) and data structures.\n- Basic knowledge of RESTful APIs and how to integrate them with applications.\n- Experience using Git for source code management (GitHub, GitLab).\n- Familiarity with UI design tools such as Figma or Adobe XD.\n- Intermediate English language skills (written and verbal).\nQuyền lợi\n- Full-time internship allowance: 2.000000 VND/month and parking fee support: 400.000 VND/month.\n- Participate in company training programs (professional skills, communication skills).\n- Support for internship certification stamping (if required).\n- Opportunity to join team-building activities, internal events, and other company recreational activities.\n- Dynamic and professional working environment, with opportunities to work and learn about investment knowledge directly from industry experts in the securities sector.\nĐịa điểm làm việc\n- Hồ Chí Minh: Tầng 21, Phú Mỹ Hưng Tower, 08 Hoàng Văn Thái, Phường Tân Phú, Quận 7\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2277, 1199, 2, 'Junior Backend Java Developer', 'Mô tả công việc\n• Tham gia thiết kế và triển khai các ứng dụng hiệu năng cao bằng Microservice phục vụ cho các nhu cầu kinh doanh của Ngân hàng như: khách hàng, tài khoản, vay vốn, tiết kiệm, chuyển tiền, thanh toán hóa đơn, ví điện tử, gửi tin nhắn...\n• Quản lý, phát triển dịch vụ tích hợp với các hệ thống core như: T24, WAY4, BPM, CRM, CIC...\n• Tham gia phát triển API trên API Gateway phục vụ tích hợp với các đối tác trong nước và quốc tế.\n• Làm việc onsite tại bank.\nYêu cầu ứng viên\nKiến thức:\n- Tốt nghiệp Đại học trở lên chuyên ngành CNTT hoặc các ngành tương đương hoặc có các chứng chỉ tương đương được công nhận bởi các tổ chức uy tín\nKinh nghiệm:\n-  2 năm kinh nghiệm  làm việc thực tế tại các tổ chức CNTT\n-  Nắm rõ quy trình xây dựng và triển khai phần mềm\n-  Sử dụng thành thạo Java core, có kinh nghiệm phát triển trên framework Spring Boot.\n-  Có hiểu biết về cơ sở dữ liệu: SQL, noSQL\n-  Có hiểu biết về việc sử dụng các công cụ quản trị như: Jija, Git,...\nƯu tiên:\n-  Ưu tiên kinh nghiệm làm việc trong lĩnh vực tài chính / ngân hàng\n-  Ưu tiên ứng viên có kinh nghiệm về phát triển ứng dụng theo dạng Cloud Native như: Microservice, CICD, DepOps, Containerization...\n-  Ưu tiên Nhân sự đã từng tham gia triển khai các dự án theo mô hình Agile/Scrum\n-  Ưu tiên nhân sự có kinh nghiệm về xử lý bất đồng bộ, xử lý đa nhiệm, event sourcing, có kinh nghiệm về các hệ thống Message Queue (Kafka, RabbitMQ), có hiểu biết về xử lý cache, job.\nNgoại ngữ:\n- Có khả năng đọc viết tiếng Anh (cơ bản) nghe nói (nếu có thể).\n- Ưu tiên ứng viên có chứng chỉ Tiếng Anh quốc tế (TOEICS 450 trở lên hoặc tương đương)\nYêu cầu khác:\n- Kỹ năng giao tiếp và làm việc nhóm tốt\n- Sẵn sàng làm việc ngoài giờ hành chính\n- Tinh thần trách nhiệm, ham học hỏi\n---Ưu tiên nộp hồ sơ sớm---\nQuyền lợi\n- Thời gian làm việc 5 ngày/tuần (từ thứ Hai đến thứ Sáu).\n- Cơ hội thăng tiến, phát triển nghề nghiệp công bằng.\n- Thu nhập hấp dẫn, cạnh tranh.\n- Được hưởng chế độ BHXH, BHYT, BHTN.\n- Được tham gia các chương trình đào tạo, huấn luyện của Công ty.\n- Môi trường làm việc chuyên nghiệp, thân thiện, năng động.\n- Thu nhập: 15 - 28 triệu (Tùy theo năng lực)\nĐịa điểm làm việc\n- Hà Nội: Lê Văn Lương, Cầu Giấy\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2278, 1200, 2, 'Middle Flutter', 'Mô tả công việc\nTham gia các dự án phát triển ứng dụng di động (cả iOS và Android), trực tiếp phát triển và hỗ trợ các thành viên trong nhóm gồm 03 - 06 thành viên. Tham gia phân tích nghiệp vụ, đề xuất giải pháp, phương án triển khai nhằm cải tiến, nâng cao hiệu quả của các dự án. Phối hợp cùng các nhà cung cấp triển khai các giải pháp Công nghệ. Nghiên cứu, thử nghiệm áp dụng các xu hướng công nghệ mới.\n\nYêu cầu ứng viên\nKinh nghiệm tối thiếu 02 năm kinh nghiệm phát triển ứng dụng di động. Kiến thức và kỹ năng lập trình: Thành thạo ngôn ngữ lập trình Dart và framework Flutter2 hoặc Native. Có kiến thức về lập trình hướng đối tượng, cấu trúc dữ liệu và giải thuật. Kinh nghiệm làm việc: Có kinh nghiệm làm việc với các hệ điều hành di động (Android/iOS), vòng đời ứng dụng và các thành phần chính của hệ điều hành. Kinh nghiệm tích hợp với các hệ thống Firebase (Push notification, analytics, authentication), OneSignal. Có kinh nghiệm đưa ứng dụng lên Apple Store và Play Store. Kinh nghiệm làm việc với RESTful API và các công cụ quản lý phiên bản như Git.\n\nQuyền lợi\nMức lương thoả thuận. Thời gian làm việc: 8h00-17h30, nghỉ trưa 1,5h (12h – 13h30) từ thứ 2 - thứ 6. 13 tháng lương + thưởng lễ tết; xét tăng lương hàng năm. Du lịch hàng năm, team building hàng tháng/quý. Bảo hiểm xã hội, BHYT theo quy định của Nhà nước. Gói bảo hiểm sức khỏe. Khám sức khoẻ định kỳ hàng năm. Môi trường flat trẻ trung, thoải mái. Cơ hội tham gia dự án tiềm năng, thử thách nhưng không kém phần thú vị.\n\nĐịa điểm làm việc\nHà Nội: Lê Đức Thọ, Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2279, 72, 2, 'Python Developer', 'Mô tả công việc\n- Phát triển và cung cấp sản phẩm chất lượng cao với đầy đủ tính năng bằng cách tuân thủ các quy trình và tiêu chuẩn của phương pháp Agile.\n- Tham gia vào việc lập kế hoạch về năng lực dịch vụ và nhu cầu, phân tích hiệu suất sản phẩm phần mềm, điều chỉnh và tối ưu hóa.\n- Lên kế hoạch và triển khai đào tạo nâng cao trình độ, mindset cho fresher – junior.\n- Nghiên cứu các giải pháp Công nghệ trên thị trường để áp dụng vào dự án hoặc sản phẩm mới.\n- Báo cáo tiến độ, kết quả công việc của cá nhân.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học Công nghệ thông tin/Khoa học máy tính/Hệ thống thông tin quản lý/Viễn thông.\n- Ít nhất 3 năm kinh nghiệm làm việc với Python.\n\n1, Kỹ năng chuyên môn:\n- Thành thạo HTTP, Web services, OAuth2, Restful APIs.\n- Thành thạo ít nhất một framework web như Django, Flask, FastAPI, Starlette...\n- Thành thạo áp dụng design patterns vào thực tế\n- Có kinh nghiệm về microservices architecture, event-driven programming paradigm.\n- Có kinh nghiệm làm việc với các framework như Celery, Dramatiq, Confluent Kafka, Pika, Kombu...\n- Có kinh nghiệm làm việc với hệ thống database như PostgreSQL, MongoDB, ELK stack, tối ưu hóa truy vấn cơ sở dữ liệu.\n- Hiểu biết về hệ thống message queue systems, distributed systems và các kỹ thuật liên quan (scaling, load balancing, sharding, replication)\n- Có kinh nghiệm đánh giá, đo kiểm hiệu năng sản phẩm, tối ưu hóa code, truy vấn cơ sở dữ liệu, cache, xử lý đồng thời (concurrency), song song (parallel)\n\n2, Kỹ năng mềm:\n- Kỹ năng làm việc nhóm và làm việc độc lập tốt.\n- Chủ động, nhiệt tình và trách nhiệm với công việc, có khả năng làm việc độc lập và thúc đẩy các dự án của riêng mình.\n- Chịu được áp lực về mặt thời gian và sẵn sàng OT khi dự án cần.\n- Ham học hỏi, nghiên cứu, có tinh thần sáng tạo.\n\nƯU TIÊN ỨNG VIÊN:\n- Có kinh nghiệm triển khai vận hành với nền tảng containerization (Docker, Kubernetes), hệ điều hành Unix/Linux\n- Có kinh nghiệm thiết lập monitoring, observability với Prometheus, Grafana, ELK,...\n- Thành thạo các công cụ đo kiểm và tối ưu hiệu suất hệ thống (profiling, benchmarking, tracing, logging).\n- Có kinh nghiệm sử dụng và tích hợp AI vào ứng dụng web như chatbot AI, tự động hóa quy trình xử lý dữ liệu, gợi ý nội dung, tìm kiếm thông minh, phân tích dữ liệu người dùng.\n- Có kinh nghiệm thiết kế kiến trúc hệ thống, đảm bảo tính mở rộng, hiệu suất và khả năng bảo trì lâu dài.\n\nQuyền lợi\n- Mức lương từ 35 - 45 triệu/tháng\n- Gói thu nhập năm tương xứng với năng lực (13 tháng lương, nghỉ mát...).\n- Cơ hội làm việc và phát triển tại FPT, Công ty tiên phong chuyển đổi số và dẫn đầu về tư vấn, cung cấp, triển khai các dịch vụ, giải pháp công nghệ - viễn thông.\n- Được đào tạo nghiệp vụ và kỹ năng liên tục, được tham gia các chương trình huấn luyện chuyên nghiệp.\n- Môi trường làm việc công bằng, minh bạch, thân thiện, cởi mở, năng động và trẻ trung\n- Cơ sở vật chất, công cụ làm việc hiện đại, tiện nghi, ứng dụng công nghệ, chuyển đổi số toàn trình.\n- Văn hóa doanh nghiệp đa dạng, phong phú; các hoạt động tri ân, chăm lo đời sống tinh thần Cán bộ nhân viên và người thân, Teambuilding, Ngày hội văn hóa, các Câu lạc bộ, Nghỉ hè,....\n- Tham gia đầy đủ các chế độ theo Luật lao động hiện hành (BHXH, BHYT, BHTN, ngày phép); Khám sức khỏe định kỳ, nghỉ hè hàng năm; Gói bảo hiểm sức khỏe chuyên biệt FPT Care (ngân sách >65 triệu/năm/cán bộ nhân viên dành cho việc khám và chữa bệnh Nội, Ngoại trú.)\n\nĐịa điểm làm việc\n- Hà Nội: FPT tower, số 10 Phạm Văn Bạch, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2280, 1201, 2, 'Lập Trình Backend', '• Phát triển ứng dụng desktop đa nền tảng sử dụng Node.js và SQLite.\n• Thiết kế kiến trúc phần mềm hiệu năng cao, tối ưu bộ nhớ và CPU cho các tác vụ nặng.\n• Thực thi giải pháp caching, xử lý đồng thời và bảo trì hệ thống lâu dài.\n• Quản lý luồng xử lý, ngăn chặn memory leak, nâng cao độ ổn định ứng dụng.\n• Phối hợp với team để triển khai giao diện người dùng và backend tích hợp.\n• Ưu tiên ứng viên đã từng làm việc với Electron.js.\n\n- Thời gian làm việc:\n+ Từ Thứ hai đến Thứ Sáu: Từ 8h00’ đến 17h30’\n+ Thứ Bảy : Từ 8h00’ đến 12h00’\n+ Trưa nghỉ từ 12h00\' đến 13h30\'\n\n• Tối thiểu 2 năm kinh nghiệm với Node.js trong môi trường sản phẩm thực tế.\n• Hiểu rõ mô hình bất đồng bộ: Callback, Promise, Async/Await.\n• Có kinh nghiệm với SQLite, hiểu ORM và ưu tiên biết TypeORM.\n• Có hiểu biết về caching (in-memory hoặc disk), tối ưu CPU usage.\n• Biết phát hiện và xử lý memory leak, hiểu lifecycle trong Node.js.\n• Có tư duy về thiết kế ứng dụng high performance: phân luồng, chia module, reuse tài nguyên.\n• Biết sử dụng Git, đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.\n\n- Lương:15.000.000 – 20.000.000\n- Phỏng vấn 1 vòng duy nhất.\n- Lộ trình thăng tiến lên Sublead, Leader\n- Review lương 2 lần /năm, thưởng nóng hàng tuần, hàng tháng, hàng năm khi đạt thành tích xuất sắc cá nhân hay đội nhóm.\n- Thưởng tháng lương thứ 13, bảo hiểm, chế độ du lịch hàng năm theo chương trình của công ty.\n- Được khám sức khỏe định kỳ tại bệnh viện đa khoa Quốc tế. Được hỗ trợ 50 -100% chi phí sau bảo hiểm nếu không may phải nằm viện\n\n- Hà Nội: Tầng 4, tòa nhà Stellar Garden số 35 Lê Văn Thiêm, Thanh Xuân Trung, Thanh Xuân\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 (từ 08:00 đến 12:00)\nNghỉ giữa ca: 12h00 - 13h30\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2281, 1202, 2, 'JAVA/ .NET Fresher Developers', 'Mô tả công việc\n- Tham gia vào các dự án phát triển phần mềm outsource cho khách hàng (Nhật Bản)\n- Tham gia lập trình, kiểm thử sản phẩm theo từng dự án của khách hàng (Nhật Bản)\n- Sẽ được đào tạo thêm trong quá trình thử việc.\n\nYêu cầu ứng viên\n- Tốt nghiệp các trường Đại học, Cao đẳng các ngành liên quan đến CNTT,...\n- Lập trình với Java Web như:  Java Core, JSP Servlet, Struts, Spring MVC, Spring Boot, ...\n- Lập trình với .NET (Web) như:  ASP.NET, MVC, Entity Framework, LINQ, ...\n- Lập trình với .NET (Winform) như: C# .NET, VB.NET, ...\n- Đã làm việc với:  HTML, CSS, Javascript, JQuery, Bootstrap,...\n- Đã từng làm với ít nhất một Database: SQL Server, MySQL, Oracle...\n- Đọc hiểu nhanh tài liệu tiếng Anh chuyên ngành.\n- Nhanh nhẹn, ham học hỏi, tinh thần trách nhiệm cao, trung thực, cẩn thận.\n- Biết tiếng Nhật là một lợi thế.\n- Ứng viên có kiến thức sau là một lợi thế:  Angular, React, Vue.js , Jquery, Framework của ngôn ngữ JAVA/ .NET, Sử dụng được tool quản lý source code: Git, SVN..\n\nQuyền lợi\n- Cơ hội onsite FUJINET JAPAN với ứng viên biết tiếng Nhật.\n- Tham gia khóa đào tạo dành cho nhân viên mới, làm quen với môi trường làm việc cũng như trang bị kỹ năng cần thiết cho công việc.\n- Tham gia miễn phí  các khóa đào tạo kỹ năng mềm, đào tạo chuyên sâu về kiến thức chuyên ngành cũng như các buổi giới thiệu công nghệ mới tại công ty.\n- Tăng lương 6 tháng/lần.\n- Lương tháng 13, thưởng các ngày lễ, sinh nhật,...\n- Phụ cấp đi lại (phụ thuộc vào khoảng cách từ nhà đến công ty).\n- Khám sức khỏe 1 năm / lần, Du lịch Công ty 1 năm 1 lần.\n- Được học Tiếng Nhật miễn phí (N5 – N1) trong giờ hành chính, nhận phụ cấp khi có Bằng.\n- Thời gian thử việc tối đa 2 tháng.\n- Thời gian làm việc : 5 ngày / tuần (giờ bắt đầu làm việc linh động từ 7:00-9:00)\n- Thời gian làm việc tại nhà (WFH) linh động hơn 50 ngày/năm.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Toà nhà Waseco (Khu C - Tầng 9), Số 10 Phổ Quang, P2, Tân Bình.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:15).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2282, 1163, 2, 'Middle/Senior IOS Developer', 'Mô tả công việc\n- Tham gia vào quá trình phân tích, thiết kế và phát triển các tính năng của ứng dụng.\n- Phối hợp với các team liên quan để triển khai và hiện thực hóa các yêu cầu sản phẩm.\n- Đề xuất và nghiên cứu các giải pháp, xu hướng công nghệ mới nhằm nâng cao chất lượng và hiệu suất sản phẩm.\n- Đảm bảo ứng dụng hoạt động ổn định, mượt mà và tối ưu hóa trải nghiệm người dùng.\nYêu cầu ứng viên\n- Tối thiểu từ 3 năm kinh nghiệm trong ngành lập trình cho Apple Devices.\n- Thành thạo ngôn ngữ lập trình Swift và các công nghệ liên quan: Concurrency, GCD, UIKit, SwiftUI.\n- Hiểu rõ mô hình server-client.\n- Có kinh nghiệm làm việc với RESTful. Có hiểu biết về GraphQL là lợi thế.\n- Có kinh nghiệm làm việc với các mô hình kiến trúc phổ biến như MVC, MVVM.\n- Có kinh nghiệm làm sản phẩm đáp ứng các yêu cầu cao về UI/UX, có hiểu biết về UI/UX là lợi thế.\n- Có kinh nghiệm làm việc với SQLite, Realm.\n- Có tư duy logic về data structures, algorithms.\n- Có khả năng debug tốt, nắm bắt vấn đề nhanh,hiểu biết về clean code, SOLID, design pattern là một lợi thế.\n- Có khả năng đọc hiểu nhanh, nắm bắt công nghệ mới là một lợi thế.\n- Đã từng tham gia phát triển ứng dụng đáp ứng lượng user sử dụng lớn là một lợi thế.\nQuyền lợi\nMức lương và phúc lợi hấp dẫn:\n- Mức lương NET upto 35.000.000đ/tháng (Middle) và upto 45.000.000đ/tháng (Senior).\n- Thử việc nhận 100% lương.\n- Lương tháng 13, thưởng lễ, Tết, thâm niên.\n- Review lương hàng năm.\n- Bảo hiểm y tế, bảo hiểm xã hội, bảo hiểm sức khỏe cá nhân (PTI).\n- Hỗ trợ ăn trưa 500.000 VND/tháng.\nCác quyền lợi khác:\n- Miễn phí gửi xe, snacks & drinks tại văn phòng.\n- Du lịch công ty, team building, sinh nhật.\n- Hoạt động Well-being 1 tháng/lần (các hoạt động chăm sóc sức khỏe thể chất và tinh thần).\n- Happy Lunch vào Trưa thứ 4, Teabreak vào chiều Thứ 3 hoặc chiều Thứ 5 hàng tuần.\n- Các chế độ khác theo đúng Luật lao động hiện hành.\nMôi trường làm việc:\n- Môi trường product trẻ trung năng động, sáng tạo cao.\n- Sản phẩm xây dựng ra cho khách hàng quốc tế 100%, hiện có hơn 1.5 triệu người sử dụng trên toàn cầu.\nThời gian làm việc:\n- Chấm công/làm việc linh hoạt từ 08h00 - 09h30, miễn đủ 8 tiếng, đảm bảo hiệu suất và tiến độ công việc\n- Làm việc từ thứ 2 đến thứ 6 hàng tuần, nghỉ trưa từ 12h00 - 13h30, thứ 4 nghỉ trưa từ 12h00 - 14h00.\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2283, 1203, 2, 'Nhân Viên Lập Trình', 'Mô tả công việc\n- Tham gia các dự án phát triển các dự án Website, thương mại điện tử;\n- Nghiên cứu các công nghệ mới, hỗ trợ phát triển, khắc phục lỗi hệ thống;\n- Xây dựng và chỉnh sửa các module, tính năng theo yêu cầu;\n- Các công việc khác theo phân công của cấp trên.\n\nYêu cầu ứng viên\n- Có kiến thức về codegym \n- Có kinh nghiệm lập trình Backend sử dụng java;\n- Có kinh nghiệm lập trình Front end (web) trên nền tảng Spring framework;\n- Ưu tiên người có kinh nghiệm về một trong các nền tảng Spring framework, Angular, AngularJs, React;\n- Có khả năng sử dụng query cơ bản trên MySQL, Oracle;\n- Có khả năng sử dụng Shell Script và câu lệnh cơ bản trên Linux.\n- Cẩn thận, kiên nhẫn, đam mê lập trình và sẵn sàng học hỏi các công nghệ mới.\n- Chịu được áp lực công việc.\n- Có kỹ năng phân tích và giải quyết vấn đề, có khả năng làm việc độc lập và theo nhóm.\n\nQuyền lợi\n- Mức lương cạnh tranh: 10 – 20M.\n- Con đường sự nghiệp vững vàng, môi trường làm việc năng động, nhanh nhẹn.\n- Được đào tạo theo định hướng công việc của Công ty và nhu cầu đề xuất cá nhân.\n- Thưởng KPI, Thưởng dự án, Thưởng hiệu quả công việc, thưởng cuối năm tháng 13+++…\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc.\n- Được hưởng BHXH, BHYT, BHTN theo chế độ nhà nước ban hành.\n- Khám sức khỏe định kỳ 1 năm/1 lần.\n- Được tham gia các hoạt động thể dục thể thao như: Bóng đá, cầu lông,…\n- Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding thường xuyên.\n- Làm việc từ thứ 2 đến thứ 6, nghỉ thứ 7 và CN;\n- 12 ngày phép/năm và các ngày nghỉ lễ - tết theo quy định;\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2284, 1204, 2, 'Trưởng Phòng Công Nghệ', 'Mô tả công việc\n- Đánh giá, tư vấn và đưa ra giải pháp công nghệ phù hợp cho quá trình nâng cấp từ monolithic sang microservices.\n- Thiết kế và phát triển các API, tích hợp hệ thống hiện có và các bên thứ ba.\n- Quản lý vòng đời phát triển phần mềm (SDLC), ứng dụng CI/CD để nâng cao hiệu quả phát triển khai thác.\n- Hiểu biết Ứng dụng AI để quản lý và tối ưu hiệu suất, bảo mật và khả năng mở rộng của hệ thống.\n- Kết hợp các bộ phận để đảm bảo hệ thống hoạt động ổn định và đáp ứng yêu cầu nghiệp vụ.\n- Xây dựng và hướng dẫn đội ngũ kỹ thuật về các công nghệ mới.\n- Nghiên cứu các công nghệ mới áp dụng vào dự án.\n- Phát triển các tính năng mới cho sản phẩm theo yêu cầu của khách hàng.\n- Tham gia vào việc phát triển, nâng cấp, cập nhật các sản phẩm (web, ứng dụng, phần mềm) của khách hàng, kiểm tra bảo đảm chất lượng dự án.\n- Xây dựng và quản lý team 5-7 người\n- Chi tiết trao đổi khi phỏng vấn\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học, cao đẳng chuyên ngành IT,\n- Kinh nghiệm: 3-5 năm kinh nghiệm phát triển phần mềm, trong đó ít nhất 2 năm ở vị trí Techlead hoặc tương đương.\nKiến trúc: Có kinh nghiệm chuyển đổi hoặc làm việc với microservice, kiến ​​trúc hướng sự kiện.\n- Cơ sở dữ liệu: Có kinh nghiệm MariaDB hoặc các hệ thống quản trị cơ sở dữ liệu (RDBMS). Hiểu biết về NoSQL là lợi thế.\n- API & Tích hợp: Kinh nghiệm làm việc với RESTful API, GraphQL, tích hợp với bên ngoài hệ thống.\n- Cloud & DevOps: Có kinh nghiệm về Docker, Kubernetes, CI/CD, nền tảng Cloud (AWS/GCP/Azure).\n- Bảo mật: Nắm vững các hệ thống bảo mật tiêu chuẩn, xác thực & ủy quyền (OAuth2, Keycloak, OpenID).\n- Frontend: Kinh nghiệm với Vue.js hoặc framework frontend hiện đại là lợi thế.\n- Khả năng lãnh đạo: Kinh nghiệm quản lý đội ngũ kỹ thuật, hướng dẫn và đào tạo thành viên.\n- Ưu tiên: Ứng viên có kinh nghiệm trong công việc hệ thống dịch vụ công; chính phủ điện tử hoặc các mô-đun dự án lớn.\n- Có kinh nghiệm ứng dụng, sử dụng AI\n- Có kinh nghiệm làm việc trong các dự án theo mô hình Agile\nƯu tiên: Giao tiếp tốt (nói/viết) bằng tiếng Anh.\n\nQuyền lợi\n- Mức lương : Lương cứng cạnh tranh + thưởng dự án ( tùy năng lực), trao đổi khi phỏng vấn.\n- Thu nhập : 25.000.000đ – 40.000.000đ + thưởng dự án.\n- Các chế độ khác theo quy định của Công ty.\n\nĐịa điểm làm việc\n- Hà Nội: BT4 đường Bùi Xuân Phái, Phường Mỹ Đình 2, Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2285, 1205, 2, 'Kỹ Sư Cầu Nối', 'Là một Công ty hoạt động trong lĩnh vực Y tế số, chúng tôi coi nhân sự là trung tâm của mọi hành động. Ominext đang nỗ lực xây dựng một môi trường sống hạnh phúc, chú trọng tới phát triển chuyên môn và chăm sóc sức khỏe cho từng Cán bộ nhân viên, người thân của họ! Gia nhập Ominext ngay hôm nay để tận hưởng các ưu đãi đặc quyền dành riêng cho người Omi.\n\nVới vai trò là Kỹ sư cầu nối, ứng viên sẽ thực hiện các công việc:\n- Tham gia phát triển dự án Procurement cho khách hàng Nhật Bản.\n- Nghiên cứu, hiểu sâu hệ thống khách hàng, nắm chắc nội dung dự án (nhận tài liệu mô tả, họp spec cùng khách) thực hiện trao đổi Q&A trực tiếp với khách hàng truyền đạt thông tin về team Offshore tại Việt Nam.\n- Phối hợp với đội dự án tại Việt Nam giám sát tiến độ thực hiện dự án, quản lý chất lượng sản phẩm đầu ra của dự án trước khi bàn giao cho khách hàng.\n\nYêu cầu ứng viên:\n- Tiếng Nhật sử dụng thành thạo (trình độ tương đương N2 trở lên).\n- Có từ 3 năm kinh nghiệm SE/BrSE.\n- Có kinh nghiệm code C#, VB.NET là lợi thế lớn.\n- Áp dụng các quy trình Agile/Scrum là lợi thế.\n- Kỹ năng quản lý team và giao tiếp đa quốc gia hiệu quả là lợi thế.\n- Có kinh nghiệm xác định yêu cầu, thiết kế và xây dựng hệ thống (basic design/detail design) là lợi thế lớn.\n- Ưu tiên ứng viên có kinh nghiệm làm các hệ thống liên quan đến warehouse, logistic.\n- Quản lý tiến độ, quản lý rủi ro tốt là 1 lợi thế.\n- Chủ động, tư duy tích cực và có tinh thần trách nhiệm cao với công việc.\n\nĐịa điểm làm việc: Okayama, tại location khách hàng.\n\nQuyền lợi:\n- Môi trường làm việc lý tưởng, được tôn trọng:\n    - Dự án lâu dài, ổn định, tiềm năng phát triển mở rộng rất lớn.\n    - Đội ngũ Quản lý kinh nghiệm dày dạn, có lý tưởng lớn sẵn sàng chia sẻ, đồng hành, là những con người nhiệt huyết, tài năng, tận tâm và đặc biệt chuyên môn sâu rộng (chuyên gia trong lĩnh vực của mình). Được làm việc trực tiếp với CEO và đội ngũ Solution Consultant trong lĩnh vực IT Healthcare.\n    - Đội ngũ chuyên gia với các chứng chỉ hàng đầu về y tế số như chứng chỉ Medical Health Care Certifications, chứng chỉ HL7,... Ominext tự hào khi có nhân sự là người đầu tiên tại Việt Nam đạt chứng chỉ HL7 FHIR.\n    - Cùng với sứ mệnh tiên phong kiến tạo hệ sinh thái Y tế số, tái định vị thương hiệu, OmiGroup khẳng định tinh thần, nhiệt huyết, sẵn sàng đóng góp vì mục tiêu chăm sóc sức khỏe con người và xã hội.\n- Tập trung hỗ trợ sự phát triển cá nhân:\n    - Cơ hội làm việc tại công ty dẫn đầu Việt Nam về IT Healthcare, là thành viên nước ngoài duy nhất tại JAHIS - Hiệp hội Công nghiệp Hệ thống Thông tin Y tế Nhật Bản.\n    - Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng với hệ thống career path (phát triển theo hướng chuyên gia hoặc hướng quản lý) đã được nghiên cứu, thử nghiệm trong nhiều năm.\n    - Cơ hội tham gia nhiều dự án đa dạng, team size từ 10MM - 150MM.\n    - Cơ hội về Việt Nam mở business riêng.\n- Quan tâm đặc biệt tới nhân viên:\n    - Mức lương thưởng: Hấp dẫn, cạnh tranh với thị trường.\n    - Hỗ trợ xin visa (cho ứng viên ở Việt Nam), đổi visa (cho ứng viên tại Nhật Bản).\n    - Tài trợ vé máy bay khứ hồi về Việt Nam thăm gia đình dành cho nhân viên có thâm niên công tác từ 1 năm trở lên.\n    - Hỗ trợ tiền nhà (tối đa 30.000 Yên/tháng), chi phí đi lại (tối đa 20.000 Yên/tháng).\n    - Một số phúc lợi xã hội như: Rèn luyện sức khỏe, trau dồi kiến thức, học tập nâng cao phục vụ công việc (mua sách vở, tập gym, thể thao, …) (tối đa 10.000 Yên/tháng).\n    - Được đóng BHXH, BHYT, BHTN theo quy định của chính phủ Nhật Bản.\n    - Khám sức khỏe định kỳ 1 năm/lần cho nhân viên thâm niên từ 6 tháng.\n\nĐịa điểm làm việc: Nhật Bản.\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 09:30 đến 18:30).\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nhật Bản', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2286, 363, 2, 'IT System & Solution Leader/ Leader Hệ Thống & Giải Pháp CNTT', '1. Tiếp nhận và quản trị hệ thống giải pháp/phần mềm Công ty đã phát triển\n2. Cập nhật, đánh giá và đề xuất cải tiến giải pháp/phần mềm\n3. Tham gia thiết kế, phát triển module/sản phẩm mới \n4. Theo dõi, giám sát hoạt động hệ thống, phần mềm, phát hiện và xử lý sự cố kịp thời\n5. Xử lý các sự cố liên quan đến hệ thống mạng LAN/WAN, database, server\n6. Đánh giá, tối ưu hiệu năng ứng dụng và hệ thống backend\n7. Hỗ trợ team dev trong việc troubleshoot, debug và tối ưu code\n8. Nghiên cứu công nghệ mới và đề xuất cải tiến hệ thống\n9. Phân tích luồng nghiệp vụ, đề xuất giải pháp kỹ thuật phù hợp\n10. Thực hiện demo, triển khai setup hệ thống cho đối tác, khách hàng khi có yêu cầu\n11. Tư vấn, triển khai các giải pháp công nghệ, sản phẩm phục vụ chiến lược chuyển đổi số, số hóa quy trình hoạt động của công ty\n12. Nghiên cứu, đề xuất các sáng kiến cải tiến hạ tầng, hệ thống CNTT nhằm nâng cao năng suất, hiệu quả.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT, Kỹ thuật phần mềm hoặc lĩnh vực liên quan.\n- Có ít nhất 03 năm kinh nghiệm ở vị trí quản trị hệ thống, hạ tầng, hỗ trợ người dùng.\n- Có ít nhất 01 năm kinh nghiệm team leader ngành CNTT.\n- Kinh nghiệm quản trị Windows Server, Active Directory, email server, cloud service cơ bản (Google Workspace, Office 365, AWS/Azure cơ bản).\n- Khả năng xử lý sự cố hệ thống, phần mềm, mạng, hỗ trợ người dùng hiệu quả.\n- Kỹ năng giao tiếp, phối hợp nhóm, hỗ trợ người dùng tốt.\n- Có kinh nghiệm triển khai, demo giải pháp CNTT cho khách hàng/đối tác là một lợi thế.\n- Am hiểu các giải pháp bảo mật, firewall, VPN, NAS, backup, DRP.\n- Tư duy chủ động, ham học hỏi công nghệ mới, sẵn sàng nghiên cứu các giải pháp chuyển đổi số.\n- Sẵn sàng đi công tác khi có yêu cầu.\n\nQuyền lợi\n- Mức lương cạnh tranh (tùy theo năng lực).\n- Tham gia đầy đủ chế độ BHXH, BHYT, BHTN theo quy định.\n- Môi trường làm việc chuyên nghiệp, năng động, nhiều cơ hội phát triển nghề nghiệp.\n- Cơ hội tham gia các dự án công nghệ mới, giải pháp chuyển đổi số tiên tiến.\n- Được đào tạo, nâng cao kiến thức về hệ thống, giải pháp, kỹ năng mềm.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 120 Nguyễn Minh Hoàng, Phường 12, Tân Bình\n\nThời gian làm việc\n- Từ Thứ 2 đến sáng Thứ 7 hàng tuần.\n- Thời gian: 8h đến 17h.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2287, 1206, 2, 'Nhân Viên IT', 'Mô tả công việc:\nTham gia phát triển dự án phần mềm của công ty, xây dựng các chức năng\n- Xây dựng hệ thống API, liên kết dữ liệu.\n- Code chức năng tuỳ biến theo yêu cầu.\n- Fix bug, chỉnh sửa theo yêu cầu của cấp trên.\n- Nghiên cứu các tính năng và công nghệ mới\n- Phát triển hệ thống CRM quản lý dự án, đơn hàng, khách hàng, nhân viên\n\nYêu cầu ứng viên:\n- Thành thạo ngôn ngữ lập trình PHP, có kinh nghiệm sâu một trong các framework như Laravel\n- Thành thạo HTML/CSS/Javascript/jQuery\n- Thành thạo ít nhất 1 library/framework để phát triển front-end: Bootstrap, Angular, VueJS, ReactJS,...\n- Thành thạo việc xây dựng và sử dụng web service (XML, JSON)\n- Có kinh nghiệm về API Restful\n- Có kinh nghiệm sử dụng ít nhất 1 hệ quản trị cơ sở dữ liệu MySQL, Postgresql, Oracle, Microsoft SQL Server, MongoDB\n- Có kinh nghiệm quản lý dự án, có khả năng làm việc độc lập, làm việc theo đội/nhóm. có khả năng lập kế hoạch trong công việc.\n- Nắm vững các kiến thức về Github\n- Có kinh nghiệm triển khai phần mềm theo kiến trúc micro-services\n- Yêu cầu có tối thiểu 1 năm kinh nghiệm ở vị trí tương đương.\n- Giao tiếp tốt, nhiệt huyết, có trách nhiệm với công việc.\n\nQuyền lợi:\n- Môi trường làm việc thân thiện, năng động, sôi nổi và vui vẻ.\n- Chế độ nghỉ phép 12 ngày, nghỉ lễ đầy đủ; được cấp phát đầy đủ công cụ dụng cụ làm việc.\n- Được hưởng các chế độ phúc lợi như BHXH, sinh nhật, du lịch hằng năm,...\n- Thưởng vào các dịp lễ, tết, thưởng cá nhân đối với các nhân viên xuất sắc,...\n- Chính sách tăng lương hàng năm.\n\nĐịa điểm làm việc:\n- Bình Định: 76 Cần Vương, Phường Nguyễn Văn Cừ, Thành phố Quy Nhơn, TP Quy Nhơn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Định', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2288, 1207, 2, 'Drupal Developer - Từ 3 Năm Kinh Nghiệm - Up To 35 Triệu/Tháng', 'Mô tả công việc\n- Tham gia vào các dự án làm việc với dự án và các đối tác từ Nhật Bản.\n- Xây dựng website sử dụng Drupal, API server sử dụng PHP hoặc các framework liên quan.\n- Tham gia vào dự án xây dựng product riêng của công ty.\n\nYêu cầu ứng viên\n【KỸ NĂNG CẦN THIẾT】\n- Hiểu biết về PHP core. Có kinh nghiệm 3 năm trở lên sử dụng ngôn ngữ PHP trong công việc.\n- Có khả năng làm việc với MYSQL, Bootstrap, JavaScript, HTML, CSS, jQuery...\n- Có 3 năm kinh nghiệm trở lên với framework Drupal\n- Có 2 năm kinh nghiệm trở lên làm việc với Gitlab, github hoặc Bitbucket.\n- Có khả năng viết unit test, document\n- Có tư duy lập trình hướng đối tượng MVC, đọc hiểu tiếng anh tốt để phục vụ cho công việc.\n\n【KỸ NĂNG MONG MUỐN】\n- Có kiến thức liên quan đến Performance của MySQL Statement và Query.\n- Có kinh nghiệm với framework PHP khác là 1 lợi thế như: Laravel, Wordpress, Cakephp, EC-CUBE, Yii...\n- Có kiến thức về Linux, Windows OS.\n- Những ứng viên có kinh nghiệm sử dụng Docker để phát triển.\n- Có kiến thức về UML.\n- Ưu tiên những ứng viên sẵn sàng va chạm - thử thách với những công nghệ mới.\n- Ưu tiên những ứng viên luôn nỗ lực hết mình trong mọi hoàn cảnh và đưa ra những ý kiến đóng góp để phát triển công việc.\n- Có kiến thức về Cloud Server: AWS, GCP, Azure... là một lợi thế\n- Có kiến thức về Around Security là một lợi thế\n\nQuyền lợi\n- Lương: Từ 20 - 35 triệu tùy theo năng lực.\n- Thử việc lên đến 100% lương\n- Phụ cấp cơm trưa và gửi xe hàng tháng\n- Cung cấp đầy đủ thiết bị phục vụ công việc\n- Nghỉ thứ 7, chủ nhật\n- Đóng BHXH sau khi thử việc, hưởng các chế độ phúc lợi theo luật lao động Việt Nam\n- Đánh giá xét tăng lương: 2 lần/năm\n- Lương tháng 13 + thưởng dự án theo quý tùy vào tình hình kinh doanh của công ty\n- Được tham gia các Câu lạc bộ dưới sự tài trợ chính thức của Công ty: CLB Bóng đá, - Lớp tiếng Nhật, tham gia các bữa tiệc sinh nhật, team building hàng quý, company trip hàng năm\n- Cơ hội thăng tiến cao, cơ hội rất lớn để trở thành key member của công ty.\n- Cơ hội đi công tác và làm việc tại Nhật Bản nếu đáp ứng được năng lực tốt.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4, Toà nhà H10, số 2 ngõ 475 Nguyễn Trãi, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2289, 1208, 2, 'Java Fullstack (Thu Nhập Đến 25 Triệu)', '- Xây dựng, phát triển phần mềm/ứng dụng\n• Tiếp nhận yêu cầu về chức năng, nội dung của phần mềm/ứng dụng. Tham gia phân tích, thiết kế chi tiết các chức năng được giao\n• Trực tiếp xây dựng, phát triển phần mềm/ứng dụng theo tài liệu thiết kế và framework đã được thông qua theo phân công của trưởng nhóm/PM dự án\n• Làm Unit Test, tiếp nhận ý kiến của bộ phận kiểm thử, liên quan khác để điều chỉnh, bổ sung đến khi phần mềm/ứng dụng được hoàn thiện\n• Giám sát và kiểm tra hệ thống và các thành phần liên quan để phát hiện các sự cố tiềm ẩn, đưa ra giải pháp kịp thời để ngăn chặn và xử lý. Tối ưu hệ thống.\n• Xây dựng các tài liệu dự án theo phân công của Trưởng nhóm/PM dự án\n- Sửa chữa, nâng cấp, bảo trì phần mềm\n- Tích hợp, triển khai phần mềm/ứng dụng\n- Các công việc khác\n\nYêu cầu ứng viên\n- Tốt nghiệp CĐ/ĐH\n• Tối thiểu 2 năm kinh nghiệm phát triển thực tế với Java và các framework (Spring Framework, Spring Boot)\n• Kiến thức tốt về Cấu trúc Dữ liệu và Thuật toán; Chuyên môn về Cơ sở dữ liệu SQL / NoSQL (Oracle, MongoDB); Kinh nghiệm với các API RESTful, Microservices\n• Tối thiểu 2 năm kinh nghiệm làm việc với framework JS/UI – Angular\n• Kinh nghiệm với Typescript, HTML, CSS; Hiểu biết tốt về các thực tiễn tốt nhất về UX.\n- Tuổi:  dưới 40 tuổi\n- Làm theo dự án\n\nQuyền lợi\n• Teambuilding 1 năm nhiều lần\n• Nghỉ thứ 7, CN, đóng BHXH ngay sau khi là cán bộ chính thức\n• Công ty đóng toàn bộ BHXH, BHYT, BHTN, thuế TNCN\n\nĐịa điểm làm việc\n- Hà Nội: CT2 Tràng An Complex, số 1 Phùng Chí Kiên, Nghĩa Đô, Cầu Giấy, Cầu Giấy\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2290, 1209, 2, 'Lập Trình Viên - Hệ Thống Bán Hàng', 'Mô tả công việc\n- Tham gia xây dựng, phát triển hoặc chỉnh sửa hệ thống phần mềm bán hàng (POS, quản lý đơn hàng, CRM, kho, v.v.)\n- Phối hợp với các bộ phận nghiệp vụ để thu thập yêu cầu và đề xuất giải pháp phần mềm phù hợp\n- Thực hiện lập trình, kiểm thử, triển khai và bảo trì hệ thống nội bộ\n- Tích hợp hệ thống với các phần mềm liên quan (kế toán, kho, thương mại điện tử, cổng thanh toán...)\n- Viết tài liệu kỹ thuật, tài liệu hướng dẫn người dùng\n- Hỗ trợ kỹ thuật và xử lý lỗi phần mềm cho nhân viên các bộ phận sử dụng hệ thống\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành Công Nghệ Thông Tin\n- Có kinh nghiệm từ 2 - 3 năm ở vị trí tương đương tại các công ty ở lĩnh vực Bán lẻ (F&B), siêu thị, cửa hàng tiện lợi....\n- Ứng viên có thể giao tiếp tiếng Trung là điểm cộng\n- Có khả năng làm việc nhóm và làm việc độc lập\n\nQuyền lợi\n- Lương: Thỏa thuận\n- Thưởng tháng 13\n- Hưởng chế độ BHXH , BHYT theo quy định nhà nước\n- Làm việc trong môi trường thân thiện và có cơ hội thăng tiến cao\n- Được xét duyệt review thăng tiến, tăng lương định kỳ\n- Các quyền lợi khác trao đổi chi tiết lúc phỏng vấn\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 22 Trần Huy Liệu, P. 11, Phú Nhuận\n\nThời gian làm việc\n- Từ Thứ 2- Thứ 6 ( 8h30-17h30), T7 (8h30-16h30) và T7 làm cách tuần', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2291, 1210, 2, 'Lập Trình Viên Java', 'Mô tả công việc\n- Phân tích yêu cầu và phát triển các tính năng backend: Core, API… cho các dự án của Công ty.\n- Kết nối với các nền tảng e-Commerce (Amazon, Ebay, Etsy, Shopify, Woo Commerce …).\n- Nghiên cứu và áp dụng công nghệ mới phục vụ nhu cầu phát triển hệ thống của Công ty.\n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm lập trình bằng ngôn ngữ Java sử dụng framework Spring Boot.\n- Nắm vững kiến thức về OOP, Design Pattern, giao tiếp mạng, multi-threading, schedule...\n- Có kinh nghiệm sử dụng ít nhất 1 hệ quản trị cơ sở dữ liệu MySQL, PostgreSQL, Oracle.\n- Nắm chắc kiến thức về thiết kế, chuẩn hóa, tối ưu Database và câu lệnh SQL.\n- Có kinh nghiệm về hệ điều hành Linux.\n- Có kinh nghiệm làm việc với NoSQL, hệ thống Cluster, Caching, MQ, Webhook là một lợi thế.\n- Sử dụng tốt Git.\n- Tư duy logic rõ ràng, rành mạch, khả năng xử lý vấn đề phức tạp.\n- Đề cao tính chủ động và trách nhiệm trong công việc, ý thức chất lượng sản phẩm tốt, chịu được áp lực công việc.\n- Đam mê tìm tòi nghiên cứu học hỏi công nghệ mới, phát triển bản thân.\n- Đọc viết tiếng Anh khá là một lợi thế.\n\nQuyền lợi\n- Lương trả theo năng lực: range lương 18.000.000 => 25.000.000 + thưởng (thỏa thuận theo năng lực khi phỏng vấn).\n- Môi trường trẻ trung với nhiều chế độ đãi ngộ lý tưởng: thưởng lễ tết, lương tháng thứ 13, thưởng theo dự án, thưởng mềm theo hiệu quả công việc, xét tăng lương hàng năm.\n- Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n- Chế độ nghỉ mát, du lịch trong nước hoặc nước ngoài từ 1-2 lần/năm.\n- Phụ cấp ăn trưa, gửi xe, công tác phí…\n- Đồng nghiệp Mỹ/Việt Nam thân thiện, trẻ trung 9x, môi trường làm việc thoải mái.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 1 toà nhà Sông Đà 9, số 2 Nguyễn Hoàng, Phường Mỹ Đình 2, Nam Từ Liêm, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2292, 1122, 2, '[Hybrid] Java Developer (EN Fluent)', 'Mô tả công việc\n- Work as software developer on the web-based application product in JAVA- related and open-source technologies\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project development with high quality.\n- Participate in all phases of the development cycle.\n- Actively join planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n- Respond to and resolve IT support requests from employees via phone, email, or service request system.\n\nYêu cầu ứng viên\n- Good command of English (both written/verbal) is essential.\n- 5+ years of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend.\n- Able to analyze, design, develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner).\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools.\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc.\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications.\n- Solid understanding of OOP, design patterns, and coding standards.\n- PREFERRED QUALIFICATIONS\n- Experience with: \n  - MS .Net / .Net Core\n  - Kubernetes\n  - React.js\n  - Nginx\n  - JUnit\n  - Jasper Report\n  - ElasticSearch & Kibana (ELK)\n  - Grafana\n  - Prometheus (monitoring/alerts)\n\nQuyền lợi\n- Probation salary is 100% of official salary.\n- 13th-month salary and performance review twice a year.\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year).\n- Project Bonus.\n- IT Certificate allowance.\n- Health Care Insurance Social, health and unemployment Insurance following Government policy.\n- Enjoy company summer trips and other team building activities held monthly and quarterly.\n- Work five days per week with flexible check-in time.\n- Professional, creative and dynamic working environment.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa The Nine, số 9 Phạm Văn Đồng, Mai Dịch, Cầu Giấy.\n- Hồ Chí Minh: Điện Biên Phủ, Bình Thạnh.\n\nThời gian làm việc\n- Check in-out linh hoạt.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2293, 1142, 2, 'Middle/Senior C/C++ Developer', 'Mô tả công việc:\n- Developing new functions.\n- Maintaining existing functions of semiconductor manufacturing processing systems\n- Control robotic arms, sensors, grinder, wafer, … in chip manufacturing machines\n- Host software project team daily/weekly/monthly project meeting;\n- Ensure software delivery on time and quality according to customer requirement.\n- Maintain good communication with cross-function teams to ensure all software development activity meet project strategy.\n- Make reports and communicate with Operation Manager.\n\nYêu cầu ứng viên:\n- Minimum of 3 years of professional experience in C++ development.\n- Language: C++, Modern C++11/14/17, Singleton/Prototype/Factory/Design pattern.\n- Good basic knowledge, good logical thinking\n- Related skills: HTTP, Websocket, Restful APIs, etherCat\n- OS: Windows 10/Windows 11, Linux/Debian/Ubuntu\n- Have skills in manipulating and managing Package Format and using linux command.\n- IDE: Visual Studio 2019/Vscode\n- Framework: MFC, Boost\n- Database: Postgres/sqlite\n- SOFT SKILLS:\n- Experience working directly with English/Japanese speaking customers.\n- Reporting skills: Ability to convey information in an easy-to-understand and accurate way, while listening to feedback from others.\n- Teamwork ability: Ability to work in a multi-employee, multi-project environment and share information effectively.\n- Problem solving skills.\n- Progressive spirit: Always looking for ways to improve and learn new skills.\n- Sense of responsibility: Ensure work is completed on time and ensure product quality.\n\nQuyền lợi:\n- Working in a dynamic and professional environment with many opportunities for advancement.\n- The company provides equipment such as LAPTOP, Phones to serve the working needs of all employees.\n- The company pays all costs of social insurance, health insurance, and unemployment insurance for employees.\n- Join Health and Accident Insurance package 24/7 (according to seniority). Enjoy benefits according to seniority.\n- Being trained in foreign languages, and sponsored to study certificates to improve professional skills and soft skills.\n- Opportunity to go Onsite at SPLUS JAPAN (requires Japanese level of N3 or higher)\n- Performance evaluation: 2 times/year\n- Clubs: Football, Music, …\n- Annual company trip, quarterly teambuilding, employee birthdays in the month, and special events of the year (8/3, 20/10, Mid-Autumn Festival, Christmas…)\n- Annual leave: 12 vacation days, 11 holidays a year.\n- Company trip, quarterly teambuilding, birthdays for employees in the month and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas …)\n- Annual holiday: 12 days of annual leave\n- TET bonus fund (1-3 months’ salary) according to the results of the work and the business situation of the company.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tòa nhà HaDo Airport, 2 Hồng Hà, phường 2, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2294, 1211, 2, 'Game Developer Fresher', 'Mô tả công việc\n- Chuyển thể các thiết kế của Game Artist và Game Designer thành các chức năng của game.\n- Thiết kế, xây dựng và duy trì Code hiệu quả, có thể tái sử dụng và mở rộng.\n- Đảm bảo hiệu suất, chất lượng và khả năng đáp ứng tốt nhất có thể của các game.\n- Xác định và xử lý các lỗi được phát hiện.\n- Xây dựng các phương pháp, công cụ nhằm nâng cao hiệu suất làm việc cho các thành viên trong dự án.\nYêu cầu ứng viên\n- Kinh nghiệm tham gia phát triển game 2D hoặc 3D, sử dụng Unity 2D, 3D là lợi thế.\n- Có kiến thức sâu về C# là lợi thế.\n- Có khả năng nắm bắt công nghệ mới tốt, đam mê và quyết tâm theo nghề.\n- Khả năng diễn đạt, trình bày rõ ràng, dễ hiểu, làm việc việc nhóm tốt.\n- Ứng viên đã có kinh nghiệm từ 6 tháng trở lên tại vị trí tương đương hoặc công việc tương tự là một lợi thế.\n- Có tinh thần trách nhiệm, quản lý tốt deadline và khả năng làm việc nhóm tốt.\nQuyền lợi\n- Thử việc 100% lương.\n- Thu nhập 14 - 18 tháng lương/năm.\n- Xét tăng lương định kỳ 1 lần/năm.\n- Được tham gia BHXH, BHTN, BHYT, gói chăm sóc sức khỏe của Bảo hiểm Bảo Việt, gói bảo hiểm Falcon Care của công ty.\n- Được hỗ trợ vay vốn mua nhà lãi 0% bằng Quỹ phúc lợi của công ty.\n- Hưởng 12 ngày phép/năm.\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Hỗ trợ cơm trưa, tea-break,...\n- Du lịch, team building: 3 lần/năm.\n- Môi trường làm việc vô cùng sáng tạo, năng động, được thoải mái chơi các trò chơi tại công ty: bida, PS, board game,...\n- Thời gian làm việc: 8:15 - 17:45 (7,5 giờ/ngày; thứ Hai - thứ Sáu)\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Rivera Park, 69 Đ. Vũ Trọng Phụng, Thanh Xuân\nThời gian làm việc\n- 8:15 - 17:45 (7,5 giờ/ngày; thứ Hai - thứ Sáu)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2295, 1212, 2, 'Chief Technology Officer ( Ứng Dụng SAAS)', 'Mô tả công việc\nTechnology Leadership\n● Build and implement a long-term technology vision aligned with business strategy\n● Develop a detailed technical roadmap with specific measurable milestones\n● Evaluate and recommend emerging technologies suitable for the US market\n● Represent the company at technology events and build technical credibility in the industry\n\nProduct Development & Engineering\n● Design scalable architecture for CRM and AI platforms that meet US market requirements\n● Implement end-to-end development workflow (CI/CD, automated testing, monitoring)\n● Direct product deployment strategy, ensuring technical quality and meeting user needs\n● Optimize system performance, ensuring scalability and readiness for growth\n● Develop and deploy enterprise-grade solutions (CRM, AI, data pipelines)\n\nTeam Development\n● Build and scale the engineering team from 2 to 10+ people\n● Establish engineering culture and operational excellence\n● Recruit and mentor high-potential engineers\n● Create an innovation-driven and continuous learning environment\n\nBudget & Resource Management\n● Effectively manage technology budgets, ensuring investment in priority areas\n● Efficiently allocate resources between parallel projects and ensure return on investment (ROI)\n● Evaluate and select technology partners, vendors, and external solutions\n● Develop strategic partnerships with leading technology companies\n\nYêu cầu ứng viên\nRequirements/Yêu cầu:\nTechnical Expertise\n● Age: 35-50\n● Minimum 4+ years in senior management (CTO, VP Engineering)\n● US Market Experience: Experience implementing SaaS in the US market (requirement)\n● Tech Stack Proficiency: Angular, Java, AWS, Microservices architecture\n● AI/ML Experience: Experience deploying production-grade AI/ML solutions with real-world data\n● CRM Knowledge: Experience with enterprise CRM systems (Salesforce, Hubspot)\n● Cloud Expertise: Advanced AWS architecture and optimization practices\n● Technical Breadth: Experience with web/mobile, backend systems, data pipelines\n● Real-time Systems: Experience with real-time/near real-time systems (advantage)\n\nBudget & Resource Management\n● Experience managing technology budgets of $200,000+\n● Ability to optimize operational costs on AWS and cloud services\n● Experience efficiently allocating resources across multiple parallel projects\n● Ability to build business cases and ROI calculations for technology investments\n● Knowledge of procurement processes and negotiation with software/hardware vendors\n\nLeadership Competencies\n● Ability to communicate complex technical vision and lead teams to execute\n● Excellent technical team management skills, experience building and leading teams of 10+ people\n● Ability to balance long-term technical goals with short-term business needs\n● Strategic thinking and data-driven decision making\n● Experience working in startup/high-growth environments is an advantage\n\nQualifications\n● Bachelor\'s degree or higher in Computer Science, Software Engineering or related fields\n● MBA or management certifications are a plus\n● Fluent in English (listening, speaking, reading, writing)\n● Experience working with US clients/partners\n● Excellent communication skills, ability to present complex ideas to diverse audiences\n● Strong time management, organizational, and problem-solving skills\n\nOthers:\n● Still passionate about coding\n● Developed Saas application on Amazon Web Service platform & launched to the market. (Priority given to candidates who have worked in CRM, Marketing domain)\n● Developed AI for Saas application.\n● Recruited and managed a team of >10 people.\n\nManagement responsibility/ Trách nhiệm báo cáo:\n- Make daily reports/weekly/monthly.\n- Perform periodic and irregular work reports at the request of the direct management and the Board of Directors.\n\nRelationships/ Mối Quan hệ:\nInternal: Closely associated with departments in the Company.\nExternal: Ability to build and develop good relationships.\n\nProblems/Giải quyết vấn đề:\n- Directly deal with arising arising in the assigned work.\n- Report and ask for timely direction of the direct management or The Board of Directors in case of arising is beyond the ability and authority to make personal decisions.\n\nAuthority/Quyền hạn:\n- Working time: 5 days/week (Monday to Friday)\n- Compulsory Insurances full salary (Social Insurance, Health Insurance, Unemployment Insurance) based on the Labor Code.\n- Performance bonuses: Quarterly and annual bonuses based on KPIs\n- Comprehensive insurance: Premium health insurance package for you and your family\n- Company Team Building Trip every year.\n- Professional and dynamic working environment.\n\nInterview Process\n- Round 1: Preliminary interview with HR (30 minutes)\n- Round 2: Technical discussion with CEO and senior leadership (1-2 hours)\n- Round 3: Vision and technology strategy presentation with CEO and senior leadership\n\nAccountability/Trách nhiệm khác:\n- Sense of responsibility and ability to withstand high pressure at work.\n- Good moral character.\n- Honesty, work in compliance with good discipline.\n- Professional working attitude.\n- Make efforts to learn more new knowledge.\n\nQuyền lợi\nWorking conditions/Điều kiện làm việc:\n- A dynamic, professional, friendly working environment with many opportunities for learning and advancement.\n- Receive training to improve qualifications according to the requirements of the job position.\n\nPerformance indicators/Đánh giá & nhận xét:\nEvaluation of the working process as well as work efficiency will be considered on a yearly basis.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 56 đường số 6, phường Bình Trưng Tây, Thủ Đức\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 07:30 đến 16:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2296, 1213, 2, 'Kỹ Sư Lập Trình C', 'Tham gia từ giai đoạn thiết kế đến triển khai sản phẩm của siêu dự án phát triển phần mềm CAD cho khách hàng Nhật Bản. Dự án phần mềm kiến trúc, xây dựng cho khách hàng Nhật Bản là dự án lớn của tập đoàn DTS Japan (top 10 tập đoàn CNTT tại Nhật Bản), với nhiều modules phần mềm khác nhau, từ Windows App, Web App, iOS App… Phát triển Plugin cho revit và các ứng dụng CAD khác theo đơn đặt hàng của khách hàng Nhật. Được đào tạo: chuyên sâu về C#, C/C++ và các kiến thức, kỹ năng cần thiết cho phát triển các sản phẩm cho CAD. Làm việc trong môi trường chuyên nghiệp, tuân thủ quy trình phát triển phần mềm chuẩn PMS của DTS Japan; Hợp tác làm việc với các Leaders, Project Manager xuất sắc với hàng chục năm kinh nghiệm tại các công ty phần mềm lớn nhất ở Nhật Bản và Việt Nam với các quy trình quản lý dự án bài bản, chuyên nghiệp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2297, 1214, 2, 'Chuyên Gia/CVCC Hỗ Trợ Phát Triển Ứng Dụng', 'Mô tả công việc\n- Lập trình và phát triển các hệ thống và ứng dụng của Công ty Tài chính.\n- Phát triển hoặc phối hợp với các nhà cung cấp để phát triển và triển khai các giải pháp công nghệ thông tin.\n- Quản lý và phát triển các dịch vụ tích hợp với các hệ thống cốt lõi như: T24,LOS,CRM,CIC,...\n- Duy trì hoạt động các phần mềm trong phạm vi quản lý.\n- Nghiên cứu, thử nghiệm, triển khai và ứng dụng các xu hướng công nghệ mới trong phát triển: GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL...\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học trở lên các chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Phần mềm\n- Có ít nhất 3 năm với việc phát triển các dự án thực tế trong quá trình đi làm\n- Có khả năng hiểu và giao tiếp Tiếng anh cơ bản\n- Thành thạo ít nhất 01 ngôn ngữ BackEnd: Java, NodeJS,.. và các framwork kèm theo như SpringBoot, SpringCloud, SpringSecurity, NestJs, Express,.. và 1 trong các framework FrontEnd (ví dụ: Next,Angularjs, ReactJS).\n- Có kinh nghiệm về SOLID, Design Pattern, Microservices, Monolithic Architecture, ... là một lợi thế.\n- Ưu tiên có kinh nghiệm về CI/CD, nền tảng ghi logs, nền tảng giám sát\n- Quen thuộc với các frameworks kiểm thử như Vitest và Jest\n- Nắm vững kiến thức khoa học máy tính (lập trình OOP, Cấu trúc dữ liệu & Thuật toán)\n- Hiểu biết về JPA/ORM, Hibernate, ..Sử dụng các công nghệ như Kafka, Elasticsearch, Redis, Cassandra, .v.v. là một lợi thế.\n- Có kỹ năng lập trình tốt như: phân tích và đưa ra giải pháp để giải quyết vấn đề.\n- Thành thạo ít nhất một trong các loại cơ sở dữ liệu sau: Oracle, SQL server, PostgreSQL, Mongodb...\n- Có thể sử dụng asynchronous(JS) hoặc multithread(Java) để cải thiện năng suất.\n- Có kiến thức Linux OS, Docker hoặc kinh nghiệm  DevOps với Kubernetes, Terraform, v.v. là một lợi thế.\n- Có kinh nghiệm phát triển và sử dụng công nghệ đám mây(GCP, AWS) là một lợi thế.\n- Có kinh nghiệm trong lĩnh vực ngân hàng, tài chính là một lợi thế.\n- Có khả năng dẫn dắt, đào tạo thành viên nhóm và bổ sung các kỹ năng như kiểm thử, quản lý dự án, v.v. là một lợi thế.\n\nQuyền lợi\n- 2 tháng thử việc 100% lương.\n- Phụ cấp ăn trưa.\n- Hưởng đầy đủ các chế độ đãi ngộ theo quy định của pháp luật: BHYT, BHXH, BHTN\n- Khám sức khỏe định kỳ hàng năm, chương trình Bảo hiểm sức khỏe cao cấp (PVI) theo cấp bậc và thâm niên.\n- Tối thiểu 13 tháng lương, thưởng theo kết quả kinh doanh, thưởng các dịp đặc biệt, các ngày lễ lớn.\n- Được tham gia các chương trình đào tạo để nâng cao nghiệp vụ.\n\nĐịa điểm làm việc\n- Hà Nội: số 03 Đặng Thái Thân, Hoàn Kiếm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2298, 1215, 2, 'Material Developer Staff', 'Mô tả công việc:\n1. Nghiên cứu & Phát triển nguyên phụ liệu:\nNghiên cứu và phát triển các loại nguyên phụ liệu mới phù hợp với tiêu chuẩn chất lượng, tính thẩm mỹ và yêu cầu về môi trường. Cải tiến các nguyên phụ liệu hiện có để nâng cao hiệu suất và tối ưu chi phí. Cập nhật xu hướng thị trường, công nghệ và tiêu chuẩn ngành.\n2. Tìm kiếm & Làm việc với nhà cung cấp:\nTìm kiếm, đánh giá và làm việc với các nhà cung cấp nguyên phụ liệu. Đàm phán giá cả, thời gian giao hàng và các điều khoản hợp tác. Đảm bảo nguyên phụ liệu tuân thủ các quy định về môi trường và pháp luật.\n3. Kiểm tra & Đảm bảo chất lượng nguyên phụ liệu:\nPhối hợp với bộ phận Kiểm soát chất lượng để kiểm tra độ bền, màu sắc và hiệu suất của nguyên phụ liệu. Làm việc với bộ phận Sản xuất để đảm bảo nguyên phụ liệu phù hợp với quy trình sản xuất. Xử lý các vấn đề liên quan đến chất lượng và đề xuất giải pháp cải tiến.\n4. Phối hợp với các bộ phận liên quan:\nLàm việc với các bộ phận R&D, Sản xuất, Thu mua và Thiết kế để lựa chọn nguyên phụ liệu phù hợp. Trao đổi với khách hàng, đối tác về tiêu chuẩn nguyên phụ liệu và phê duyệt sản phẩm.\nYêu cầu ứng viên:\n- Tốt nghiệp đại học/ cao đẳng chuyên ngành Kỹ thuật Dệt may, hoặc các ngành liên quan.\n- Ít nhất 2 năm kinh nghiệm trong lĩnh vực phát triển nguyên phụ liệu, tìm nguồn cung ứng hoặc sản xuất dệt may.\n- Kiến thức về vải, vật liệu tổng hợp và xu hướng bền vững.\n- Kỹ năng phân tích, giải quyết vấn đề và đàm phán.\n- Tỉ mỉ, chú ý đến chi tiết và am hiểu các tiêu chuẩn chất lượng.\n- Giao tiếp tốt bằng tiếng Anh (biết tiếng Hàn là một lợi thế).\nThu nhập:\n- Thu nhập khi đạt 100% KPI: Thoả thuận.\n- Thu nhập tính theo tỷ lệ đạt KPI.\n- Lương cứng: 10 - 15 triệu VND.\n- Lương cứng không phụ thuộc doanh số.\nQuyền lợi:\n- Lương thưởng cạnh tranh, 14 ngày phép năm.\n- BHXH, BHYT, BHTN theo quy định pháp luật.\n- Cơ hội đào tạo và phát triển nghề nghiệp.\n- Môi trường làm việc chuyên nghiệp, năng động.\nĐịa điểm làm việc:\n- Đồng Nai: Đường số 3, KCN Amata, Long Bình, Biên Hoà.\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 07:30 đến 17:00).\n- Thứ 7 (từ 07:30 đến 12:00).\nCách thức ứng tuyển:', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2299, 1216, 2, 'IT Developer/ASP.NET/Kỹ Sư Công Nghệ Thông Tin', 'Mô tả công việc\n- Design, develop, and maintain MES systems tailored for SMT production lines.\n- Collaborate with manufacturing engineers and production staff to gather system requirements.\n- Develop both backend logic and front-end interfaces using ASP.NET and modern web technologies.\n- Integrate MES with various production equipment and databases.\n- Develop middleware applications using WPF or Windows Forms.\n- Ensure system reliability, scalability, and maintainability.\n- Troubleshoot and resolve issues in existing MES applications.\n- Write documentation for system features and provide technical support when needed.\n\nYêu cầu ứng viên\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- At least 2.5 years of hands-on experience with ASP.NET development (Web Forms or MVC).\n- Experience working with HTML, CSS, JavaScript, and Bootstrap for UI development.\n- Experience with relational databases such as SQL Server or Oracle.\n- Familiarity with manufacturing environments, preferably in SMT or electronics industries.\n- Strong problem-solving skills and the ability to work independently or as part of a team.\n- Basic communication skills in English.\n- Preferred experience with MES systems or industrial automation systems.\n- Familiarity with integration protocols (e.g., SECSGEM, Serial) is a plus.\n- Knowledge of version control tools (e.g., Git) and CI/CD pipelines.\n\nQuyền lợi\n- 100% social insurance contribution based on the basic salary.\n- Lunch and phone allowance according to company regulations.\n- Full participation in insurance as regulated by law.\n- Training and development opportunities.\n- Professional, dynamic, and supportive working environment.\n- Annual health check and company trip.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 1, tòa nhà Intracom số 82 Dịch Vọng Hậu, Cầu Giấy.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2300, 1217, 2, 'Fullstack Developer', 'Mô tả công việc\n- Collaborate with the software development team to define project scopes and scales.\n- Design robust software architectures to meet project requirements.\n- Implement efficient data structures, design patterns, and scalable web services.\n- Build and maintain internal software tools, troubleshoot issues, and optimize performance.\n\nYêu cầu ứng viên\nQualifications and Skills:\n- Bachelor’s degree in Computer Engineering or Computer Science.\n- Proven 5+ years experience as a Full-Stack Engineer with a successful project portfolio.\n- Proficiency in front-end (HTML5, CSS, JavaScript, JQuery) and back-end (Java, Golang, Python, Rails, Ruby, .NET, PHP) languages.\n- Strong troubleshooting skills, familiarity with popular JavaScript frameworks, excellent communication, and project management abilities.\n\nDesired Skills, Traits, and Qualities:\n- Previous experience with cloud-based services and EDA applications.\n- Track record of delivering high-quality Full-Stack solutions in fast-paced environments.\n- Passion for ensuring scalability, reliability, and security of cloud-based services.\n- Ability to thrive in collaborative environments, adapt to evolving technologies, and communicate effectively.\n\nQuyền lợi\n- Flexible work arrangements and remote work opportunities.\n- Competitive salary.\n- Performance-based bonuses/ 13th month salary.\n- Comprehensive health, dental, and vision insurance plans.\n- Professional development and training programs.\n- Paid time off and company holidays.\n- Refer friends to open jobs and receive a cash bonus for every successful referral you make.\n\nĐịa điểm làm việc\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2301, 1218, 2, 'Frontend Developer', 'Mô tả công việc:\n- Use best practices and technologies to develop large SPAs for various users and platforms\n- Ensure high-quality, performant, and reusable code.\n- Perform benchmarking, performance, and security analysis.\n- Work closely with the backend teams and product design team to iterate quickly on new features and experiments.\n- Lead and manage a team of 2 - 4 engineers.\n\nYêu cầu ứng viên:\n- 3+ years of experience programming with JavaScript, ReactJS, HTML, and CSS.\n- Previous product company experience.\n- Be able to write clean, performance-centric, reusable, and understandable code with unit tests.\n- Experience in responsive web and mobile-first applications.\n- Experience in CSS frameworks and tools (like SASS, LESS, and Bootstrap).\n- Understanding REST APIs, and client-server communication.\n- Good command of English.\n\nQuyền lợi:\n- Hybrid working model: Enjoy 2 work-from-home days per week while fostering a collaborative environment to achieve outstanding results together.\n- 21++ paid leave days per year: Besides national holidays, annual sick leaves, and paid leaves, we have a paid leave called Got It Day for every month that doesn’t have any national holiday.\n- Amazing team: Work with the smartest and most hard-working people you’ve ever met. Our team is from Google, Meta, Apple, Amazon, and other best companies in Vietnam.\n- Competitive compensation package: Attractive salary and optional stock options. There is no upper limit on how much you can earn. It’s all based on your performance and contributions.\n- Best working environment: Coffee shop-like open office space, kitchen full of snacks and drinks, West Lake view bar, PlayStation, pool table, etc.\n- Gadgets for work: MacBook, external displays. Everything you need for your job is fully provided.\n- Training and personal development: Tuition and textbook reimbursement for approved work-related courses; free video training programs from Udacity, Udemy, and The Great Courses Plus; company library with the newest technology and business books.\n- Flexible working hours: Enjoy flexibility without strict timekeeping; our core working hours are from 10 AM to 5:30 PM (Monday to Friday).\n- Free daily lunches and dinners: Enjoy fresh meals of your choice delivered straight to the office.\n- Others: Office happy hours, team outings, participating in self-organized clubs like sports, games, algorithms, piano, etc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2302, 1219, 2, 'Thực Tập Sinh Lập Trình Viên', 'Mô tả công việc:\n- Phân tích yêu cầu và thiết kế hệ thống phần mềm.\n- Phát triển và bảo trì các ứng dụng web và mobile.\n- Viết code sạch, hiệu quả và dễ bảo trì.\n- Thực hiện các bài test đơn vị và tích hợp.\n- Cộng tác với các thành viên khác trong nhóm để hoàn thành dự án.\n- Tham gia vào các cuộc họp và thảo luận về kỹ thuật.\n- Học hỏi và cập nhật kiến thức công nghệ mới.\n- Có khả năng làm việc độc lập và làm việc nhóm.\n- Có khả năng giải quyết vấn đề và đưa ra các giải pháp hiệu quả.\n- Có tinh thần trách nhiệm cao và cam kết với công việc.\n\nYêu cầu ứng viên:\n- Có kiến thức cơ bản về các ngôn ngữ lập trình như Java, Python, PHP, Ruby on Rails, Node.js, React, Angular, Vue.js, ... (ít nhất 1 ngôn ngữ backend và 1 ngôn ngữ frontend). Và các cơ sở dữ liệu như MySQL, PostgreSQL, MongoDB, ...\n- Có kiến thức về các framework và thư viện phổ biến, kiến trúc phần mềm, thiết kế mô hình dữ liệu.\n- Có khả năng làm việc độc lập và làm việc nhóm.\n- Có khả năng giải quyết vấn đề và đưa ra các giải pháp hiệu quả.\n- Có tinh thần trách nhiệm cao và cam kết với công việc.\n- Có khả năng giao tiếp tốt và làm việc hiệu quả trong môi trường năng động.\n- Có khả năng đọc hiểu tài liệu tiếng Anh (hoặc tiếng Nhật thì càng tốt).\n\nQuyền lợi:\n- Được làm việc trong môi trường năng động và chuyên nghiệp.\n- Được đào tạo và phát triển kỹ năng chuyên môn.\n- Được hưởng các chế độ phúc lợi tốt theo quy định của pháp luật.\n- Có cơ hội thăng tiến và phát triển nghề nghiệp.\n- Được tham gia các hoạt động team building và các hoạt động ngoại khác.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 25/1 Cửu Long Phường 2, Tân Bình.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2303, 1220, 2, 'Lead Python Fullstack', 'Mô tả công việc\n- Lập trình phát triển và nâng cấp các ứng dụng trên web\n- Tham gia vào phân tích và xây dựng các module mới\n- Nâng cấp và hiệu chỉnh các module, các hệ thống có sẵn của công ty\n- Tối ưu hóa/refactoring code cho các module/services.\n- Thúc đẩy áp dụng mạnh mẽ các phương pháp mới nhất về kỹ thuật, triển khai các quy trình và công cụ tự động (code reviews, code quality, CI/CD to monitoring)\n- Thiết kế và triển khai các ứng dụng và dịch vụ đáp ứng yêu cầu người dùng.\n- Hợp tác với các nhà phát triển giao diện người dùng để tích hợp các yếu tố giao diện người dùng với logic phía máy chủ.\n- Tham gia vào các buổi xem xét, đánh giá mã nguồn và đóng góp các ý kiến thiết thực cho dự án.\n- Cập nhật các xu hướng công nghệ mới và các tiến bộ công nghệ.\n- Khả năng học hỏi và chuyển đổi ngôn ngữ lập trình nhanh theo yêu cầu của công việc là một lời thế.\n- quản lý đội nhóm\n\nYêu cầu ứng viên\n- Có từ 3 năm kinh nghiệm với ngôn ngữ lập trình Python\n- Có thể làm full stack là lợi thế lớn.\n- Có kinh nghiệm trong một các framework Python (Django, Flask hoặc Pyramid)\n- Hiểu biết về các công nghệ giao diện người dùng\n- Có kinh nghiệm làm việc với Reactjs\n- Có kinh nghiệm về cơ sở dữ liệu MariaDB hoặc MySQL, Postgres\n- Kiến thức về các công cụ quản lý phiên bản mã nguồn như Github, bitbucket, gitlab,.. \n- Kỹ năng giải quyết vấn đề tốt.\n- Kỹ năng giao tiếp và làm việc nhóm tốt.\n- Bằng Cử nhân/Cử nhân Khoa học Máy tính, Kỹ thuật hoặc lĩnh vực liên quan.\n- Có kinh nghiệm làm việc với các ngôn ngữ và framework như PHP, .Net, Go, ReactJS... là một lợi thế.\n- Có kinh nghiệm tham gia lập trình và xử lý các tính năng liên quan đến dịch vụ về VAS hoặc Education là 1 lợi thế.\n\nQuyền lợi\n- Mức lương 22.000.000 - 32.000.000 gross\n- Giờ làm việc linh hoạt \n- Cơ hội phát triển nghề nghiệp và thăng tiến.\n- Môi trường làm việc thân thiện và hợp tác.\n- Phụ cấp ăn trưa.\n- Thưởng cuối năm: Dựa trên hiệu suất của công ty.\n\nĐịa điểm làm việc\n- Hà Nội: Số 6, Nguyễn Thị Thập, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2304, 1159, 2, '[ĐN/HN] Web3 Frontend Developer (Middle/Senior)', 'Mô tả công việc\n- Develop and maintain responsive, interactive user interfaces using ReactJS\n- Integrate decentralized Web3 wallets such as MetaMask and WalletConnect into frontend applications\n- Design seamless and intuitive user experiences for blockchain transactions\n- Build scalable and reusable React components using TypeScript for maintainable codebases\n- Implement efficient state management across applications using Redux or Zustand\n- Integrate frontend interfaces with robust backend API endpoints for dynamic data handling\n- Write and maintain comprehensive unit and integration tests to ensure code quality\n- Optimize frontend performance and continuously improve the overall user experience\n- Ensure cross-browser and cross-device compatibility for consistent application behavior\n\nYêu cầu ứng viên\n- Expertise in building web applications using ReactJs\n- Advanced programming skills in TypeScript\n- Solid understanding of Web3 wallet interactions\n- Experience with modern state management libraries\n- Strong proficiency in responsive design\n- Knowledge of blockchain transaction flows\n- Strong testing skills with Jest and React Testing Library\n- Technical Stack: React, TypeScript Web3.js/ethers.js, Redux/Zustand, Tailwind CSS, Jest, React Testing Library, Vite/Next.js\n- Good English communication (writing, reading, speaking, and listening) is a plus.\n\nQuyền lợi\n- Build World class product(s): We love to solve complex problems and learn new things.\n- Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n- Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n- Enjoy competitive salary, bonus according to work performance\n- Assistance with operational tools and equipment.\n- Flexible working hours, freestyle attire\n- Perks You\'ll Enjoy:\n- Working in a young, super talented, and supportive team environment\n- Technical, English certificate bonus\n- Day-off: 12 days/year and Vietnam holidays\n- Happy Hour, Football club, English club, and many exciting activities\n- Company trip/ team building/ Year End Party\n- Free coffee, snacks, and drinks\n\nĐịa điểm làm việc\n- Đà Nẵng: 68 Xô Viết Nghệ Tĩnh, Hải Châu\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2305, 1154, 2, 'Back-End Developer', 'Phát triển và duy trì hệ thống back-end cho các trang web và ứng dụng web, đảm bảo khả năng mở rộng, bảo mật, và hiệu suất cao. Viết mã nguồn (coding) theo chuẩn kỹ thuật, đảm bảo mã dễ đọc, dễ bảo trì và tối ưu hóa. Sử dụng các framework và ngôn ngữ lập trình back-end như:\n+ Node.js với Express.js hoặc NestJS\n+ Java với Spring Boot\n+ Python với Django hoặc Flask\n+ PHP với Laravel hoặc Symfony\n+ Ruby on Rails\nTích hợp hệ thống API: Thiết kế, phát triển và duy trì các API (RESTful, GraphQL) để kết nối các dịch vụ front-end và back-end, cũng như tích hợp với các hệ thống bên ngoài (thanh toán, dịch vụ giao hàng, các bên thứ ba khác).\nThiết kế và quản lý cơ sở dữ liệu: Xây dựng và tối ưu hóa cơ sở dữ liệu (SQL và NoSQL) cho các trang web lớn, đảm bảo khả năng mở rộng, tốc độ truy vấn và tính toàn vẹn của dữ liệu.\n+ SQL: MySQL, PostgreSQL\n+ NoSQL: MongoDB, Redis\nXây dựng hệ thống xử lý và quản lý phiên truy cập người dùng: Xây dựng các cơ chế xác thực, phân quyền (OAuth2, JWT), bảo mật thông tin người dùng, xử lý phiên đăng nhập và tối ưu hóa trải nghiệm người dùng.\nXử lý hiệu suất hệ thống: Tối ưu hóa hiệu suất tải trang, thời gian phản hồi máy chủ, quản lý bộ nhớ cache (Redis, Memcached) và sử dụng các công cụ phân tích hiệu suất để phát hiện và giải quyết các vấn đề về hiệu suất.\nĐảm bảo bảo mật cho website: Áp dụng các kỹ thuật bảo mật như mã hóa dữ liệu, bảo vệ chống lại các cuộc tấn công phổ biến (SQL Injection, XSS, CSRF), và xử lý các vấn đề liên quan đến bảo mật web.\nThực hiện các báo cáo được giao.\nThực hiện những nhiệm vụ khác được giao bởi cấp Quản lý trực tiếp và Ban Giám đốc.\nYêu cầu ứng viên\nTốt nghiệp cao đẳng/đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan.\nCó ít nhất 3 năm kinh nghiệm phát triển back-end với Spring Boot, Node.js hoặc framework tương tự.\nKiến thức sâu về RESTful API, bảo mật ứng dụng và cơ sở dữ liệu (PostgreSQL, MySQL).\nKinh nghiệm làm việc với các framework và ngôn ngữ lập trình back-end phổ biến như:\n+ Node.js (Express.js, NestJS)\n+ Java (Spring Boot)\n+ Python (Django, Flask)\n+ PHP (Laravel, Symfony)\n+ Ruby on Rails\nHiểu biết về kiến trúc microservices và tích hợp hệ thống bên ngoài (MES, CRM).\nKinh nghiệm làm việc với cloud platforms như AWS, GCP hoặc Azure là lợi thế.\nKhả năng giao tiếp và làm việc nhóm tốt, có khả năng giải thích vấn đề kỹ thuật cho các thành viên không chuyên.\nKhả năng quản lý thời gian và làm việc với các deadline chặt chẽ.\nTư duy giải quyết vấn đề sáng tạo, linh hoạt.\nQuyền lợi\nMôi trường làm việc hiện đại, chuyên nghiệp, năng động, thân thiện, nhiều điều kiện, học hỏi và thăng tiến.\nThời gian làm việc: 7h45 đến 16h45, từ thứ 2 - thứ 7.\nLương Thỏa thuận theo năng lực.\nLương tháng 13, lương thâm niên quy định Công ty.\nĐược hỗ trợ cơm trưa.\nThưởng chuyên cần 800.000 đồng/tháng.\nĐược hưởng các chế độ dành cho người lao động theo quy định pháp luật hiện hành (nghỉ phép, lễ, tết,…).\nĐược hưởng các chính sách phúc lợi theo quy định của Công ty: sinh nhật cá nhân, cưới hỏi, thăm hỏi ốm đau, du lịch nghỉ mát, khám sức khỏe định kỳ hằng năm.\nTham gia đầy đủ BHYT, BHXH, BHTN theo quy định và các quyền lợi khác theo quy định của luật lao động.\nCông ty có chính sách đầu tư đào tạo và nâng cao kỹ năng nhân sự nắm giữ vị trí quản lý trong tương lai.\nĐịa điểm làm việc\n- Hồ Chí Minh: 200 Nguyễn Văn Bá, P. Trường Thọ, Thủ Đức.\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 07:45 đến 16:45).\n7:45 - 16:45 Từ Thứ Hai - Thứ Bảy (Nghỉ 2 ngày Thứ 7/tháng).\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2306, 1221, 2, 'Front-End Developer', 'Mô tả công việc:\n- Tham gia phát triển các dự án phần mềm cho khách hàng Nhật Bản;\n- Phối hợp xử lý sự cố, khắc phục lỗi trong quá trình phát triển và vận hành hệ thống;\n- Xây dựng giao diện website dựa trên bản thiết kế từ Figma, đảm bảo đúng yêu cầu UI/UX;\n- Phát triển các ứng dụng hiệu suất cao, có khả năng mở rộng (scalable) và dễ dàng cải tiến trong tương lai.\n\nYêu cầu ứng viên:\n- Tối thiểu 3 năm kinh nghiệm lập trình phát triển Web;\n- Trong đó có ít nhất 2 năm kinh nghiệm chuyên sâu với ReactJS và Next.js;\n- Hiểu rõ Server-Side Rendering (SSR), Static Site Generation (SSG), Incremental Static Regeneration (ISR) và tối ưu hóa hiệu suất của ứng dụng Next.js;\n- Thành thạo ReactJS và công nghệ liên quan: JavaScript/TypeScript ES6+; Hooks, Context API, Redux, Redux Thunk, Redux Saga...\n- Có kinh nghiệm làm việc với ít nhất một trong các UI Framework/Library phổ biến như Material UI, Ant Design, Tailwind CSS, Bootstrap, Chakra UI...\n- Có khả năng thiết kế và xây dựng các components/modules có thể tái sử dụng (reusable components/modules) chất lượng cao;\n- Thành thạo làm việc với RESTful API và sử dụng Axios để gọi API;\n- Có khả năng phối hợp chặt chẽ với đội ngũ Backend để tích hợp API và triển khai các tính năng, đặc biệt là trong các dự án có kiến trúc server-side rendering hoặc fullstack với Next.js;\n- Hiểu rõ về clean code, coding convention và các nguyên tắc thiết kế phần mềm;\n- Có kinh nghiệm trong việc tối ưu hóa hiệu suất và nâng cao chất lượng source code;\n- Nắm vững các kỹ thuật debug trong môi trường Frontend;\n- Có kinh nghiệm làm việc với Git và các Git Workflow phổ biến như Git Flow, GitHub Flow, đặc biệt trong các dự án lớn.\n\nQuyền lợi:\n- Mức lương up to 24,000,000 VND/tháng (chưa bao gồm thưởng dự án, thưởng lễ tết, và các khoản thưởng khác...);\n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Nghỉ thứ 7, Chủ nhật + Nghỉ phép theo Quy định của Pháp luật hiện hành;\n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty;\n- Khám sức khỏe định kỳ 1 năm/1 lần;\n- Bảo hiểm chăm sóc sức khỏe 24/24 ( PVI Care);\n- Tham gia các Câu lạc bộ văn hóa, thể thao trong công ty: CLB Bóng đá, CLB Game…\n- Tham gia các hoạt động tập thể sôi động theo tháng/quý/năm: Nghỉ mát hàng năm, Teambuilding, Gala cuối năm…\n\nĐặc biệt:\n- Được hỗ trợ 100% chi phí tham gia các khóa học kỹ năng mềm, các khóa đào tạo chuyên môn, luyện thi các chứng chỉ uy tín trong và ngoài nước và khen thưởng khi đạt chứng chỉ chuyên môn;\n- Học tập không giới hạn qua tài khoản học trực tuyến Udemy;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật;\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 17, 18, 19 Tòa Central Point, 219 Trung Kính, Cầu Giấy.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2307, 1222, 2, 'Kỹ Thuật Viên Lập Trình CAD-CAM & Vận Hành Máy CNC', 'Mô tả công việc\n- Nhận file thiết kế khuôn, jig, chi tiết máy từ bộ phận thiết kế, kiểm tra độ chính xác, độ phù hợp của các thiết kế và thực hiện đề xuất/ điều chỉnh nếu cần thiết;\n- Trên cơ sở thiết kế tiến hành bóc tách vật tư, linh kiện và thực hiện lập trình chương trình gia công CNC trên các phần mềm chuyên dụng;\n- Trực tiếp setup, đứng máy vận hành & theo dõi quá trình máy chạy, điều chỉnh chương trình ngay khi phát hiện sự cố, đảm bảo quá trình vận hành máy an toàn và chính xác, thời gian gia công tối ưu;\n- Thực hiện các công việc khác theo sự phân công của cấp trên.\n\nYêu cầu ứng viên\n- Tốt nghiệp Trung cấp trở lên chuyên ngành Cơ khí, Cơ điện tử, Cơ khí chế tạo, Công nghệ kĩ thuật cơ khí,...và các chuyên ngành có liên quan;\n- Đọc hiểu bản vẽ cơ khí;\n- Sử dụng các phần mềm lập trình CAM, phần mềm thiết kế CAD 2D, 3D như SolidCAM, MasterCAM, Siemens NX;\n- Có kinh nghiệm lập trình CAD/CAM và vận hành máy phay CNC. Có khả năng lập trình đường chạy dao/chọn dao phù hợp với từng thiết kế đảm bảo sự chính xác khi gia công và tối ưu hóa thời gian gia công;\n- Có khả năng vận hành các dòng máy phay CNC sử dụng hệ điều hành Fanuc, Mitsubishi như Doosan, Makino, Fanuc Robodilll;\n- Có trách nhiệm, chịu khó, chủ động cải tiến trong công việc;\n- Đã làm việc trong các nhà máy áp dụng tiêu chuẩn 5S, ISO là một lợi thế;\n- Ứng viên có kinh nghiệm lập trình chương trình gia công cho các dòng máy cắt dây, xung điện như Sodick, CHMER là một lợi thế;\n- Ưu tiên ứng viên người địa phương, ở gần nhà máy tại Khu công nghiệp Yên Phong; có khả năng đi làm theo ca.\n\nQuyền lợi\n- Mức lương khởi điểm sau khi tiếp nhận chính thức từ 7.500.000 đến 15.000.000 đồng (Có thể thỏa thuận với trường hợp ứng viên vượt trội về năng lực/kinh nghiệm);\n- Môi trường làm việc an toàn, chuyên nghiệp, thân thiện (áp dụng hệ thống Quản lý chất lượng/ Quản lý môi trường theo tiêu chuẩn ISO 9001/ ISO 14001 và phương pháp 5S, Kaizen);\n- Cơ hội được đào tạo chuyên môn, kỹ năng làm việc; nhiều cơ hội phát triển, thăng tiến;\n- Được đóng BHXH, BHYT, ngày nghỉ phép năm theo quy định;\n- Được hưởng các chế độ phúc lợi; thưởng các dịp Lễ, Tết theo quy định của Công ty; thưởng sáng kiến, thưởng nhân viên của năm;\n- Được tham gia các hoạt động do Công ty tổ chức: du lịch, teambuilding...;\n- Được cấp phát đồng phục làm việc theo tiêu chuẩn Công ty;\n- Khám sức khỏe định kỳ tại các cơ sở bệnh viện uy tín; phụ cấp ăn trưa tại Nhà máy và một số phụ cấp khác theo quy định của Công ty.\n\nĐịa điểm làm việc\n- Bắc Ninh: Khu Công nghiệp Yên Phong, Xã Long Châu, Yên Phong\n\nThời gian làm việc\n- Làm ca\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2308, 165, 2, '.NET Developer (Senior)', 'Về KiotViet:\nSản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ.\n\nVới hơn 13 năm và trên 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm.\n\nBạn sẽ làm gì\n- Phát triển và nâng cấp sản phẩm KiotViet KAT với chất lượng cao;\n- Phối hợp với các phòng ban liên quan trong phân tích nghiệp vụ, thiết kế giải pháp và triển khai sản phẩm;\n- Xây dựng và tối ưu hóa các chức năng cho hệ thống có số lượng người dùng lớn;\n- Phân tích, thiết kế và giải quyết các vấn đề kỹ thuật phức tạp về hiệu suất và nghiệp vụ;\n- Nghiên cứu, đánh giá và áp dụng công nghệ mới để cải tiến sản phẩm;\n- Tham gia code review, hướng dẫn và mentoring cho các thành viên cấp dưới trong team;\n- Triển khai và duy trì hệ thống monitoring, logging để đảm bảo tính ổn định và hiệu suất;\n- Xây dựng tài liệu kỹ thuật và quy trình phát triển.\n\nYêu cầu ứng viên\n1. Học vấn và kinh nghiệm\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc các ngành liên quan;\n- Tối thiểu 5 năm kinh nghiệm phát triển phần mềm với công nghệ .NET, NET Core.\n\n2. Yêu cầu kỹ thuật\n- Thành thạo C#, .NET Core, ASP.NET / ASP.NET Core và các framework liên quan;\n- Kinh nghiệm sâu với các ORM như Entity Framework, Dapper và tối ưu hóa truy vấn.;\n- Hiểu biết sâu về RESTful API, API Gateway và kiến trúc Microservices;\n- Thành thạo làm việc với các CSDL SQL và NoSQL (MS SQL, PostgreSQL, MongoDB):\n  - Thiết kế schema và mô hình dữ liệu hiệu quả\n  - Viết và tối ưu hóa query phức tạp\n  - Troubleshooting vấn đề hiệu suất database\n- Kinh nghiệm phát triển hệ thống phân tán với message queue (RabbitMQ, Kafka)\n- Thành thạo với caching strategies (Redis) và công nghệ realtime (MQTT, Websocket)\n- Áp dụng tốt SOLID principles, Clean Code, Design Patterns và thực hành TDD;\n- Kinh nghiệm phát triển, triển khai và vận hành hệ thống có tải cao (high load)\n- Kỹ năng debugging, profiling và troubleshooting nâng cao;\n- Kinh nghiệm sử dụng các công cụ monitoring và logging như Grafana, ELK Stack, APM, Open Telemetry;\n- Kinh nghiệm với CI/CD và container orchestration (Docker, Kubernetes) là lợi thế;\n- Có kinh nghiệm sử dụng AI coding tools và assistants (Cursor, GitHub Copilot, Claude, v.v.) để nâng cao hiệu suất trong phát triển phần mềm là một lợi thế.\n\n3. Kỹ năng mềm\n- Tư duy phân tích và giải quyết vấn đề logic;\n- Khả năng học hỏi công nghệ mới nhanh chóng;\n- Kỹ năng giao tiếp và làm việc nhóm hiệu quả;\n- Chủ động, có trách nhiệm và tự quản lý công việc tốt;\n- Kỹ năng quản lý thời gian và ưu tiên công việc hiệu quả;\n- Khả năng mentoring và hỗ trợ phát triển các thành viên junior.\n\nQuyền lợi\n- Mức lương khởi điểm đứng đầu thị trường, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm;\n- Làm việc từ Thứ 2 – Thứ 6, giờ làm việc linh hoạt;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\n- Chăm sóc sức khỏe: Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\n- Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc\n- Thứ 2 - Sáng thứ 7: 8h00-17h30 hoặc 9h00-18h30, giờ làm việc linh hoạt đủ 8h/ngày.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2309, 1223, 2, 'Senior .NET Developer', 'Mô tả công việc:\n- Tham gia nghiên cứu, thiết kế, xây dựng, phát triển và triển khai hệ thống Công nghệ Thông tin cho Tài chính, Ngân hàng.\n- Tham gia xây dựng ý tưởng, tham gia thiết kế sản phẩm, giải pháp.\n- Xây dựng tài liệu kỹ thuật sản phẩm, dự án.\n- Tham gia xây dựng tài liệu đào tạo, tham gia đào tạo và hỗ trợ người sử dụng.\n- Bảo trì, nâng cấp hệ thống cho sản phẩm, dự án.\n- Hợp tác với các bộ phận khác trong quá trình thực hiện dự án.\n- Tham gia cải tiến quy trình phát triển sản phẩm, dự án.\n- Các công việc phát sinh khác theo yêu cầu kỹ thuật dự án.\n- Báo cáo kết quả công việc, thời gian làm việc phù hợp với quy định Công ty.\n\nYêu cầu ứng viên:\n- Chuyên ngành đào tạo: Tốt nghiệp Đại học chuyên ngành CNTT hoặc tương đương.\n- Kinh nghiệm làm việc, kiến thức chuyên môn và kỹ thuật:\n  + Từ 03 năm - 08 năm kinh nghiệm xây dựng và phát triển dự án trong lĩnh vực CNTT.\n  + Kinh nghiệm thiết kế hệ thống, thiết kế cơ sở dữ liệu, Design Pattern.\n  + Kinh nghiệm lập trình ứng dụng với Angular, .Net.\n  + Kinh nghiệm làm việc với một trong các hệ thống CSDL như: Oracle, MS SQL Server, PostgreSQL …\n- Ưu tiên ứng viên có kinh nghiệm và kiến thức chuyên môn sau:\n  + Kinh nghiệm xây dựng các ứng dụng trên nền tảng Cloud Native / kiến trúc Microservice.\n  + Kinh nghiệm triển khai các ứng dụng trên Container / Docker cho môi trường Windows & Linux.\n  + Kinh nghiệm và hiểu biết về các yêu cầu bảo mật trên môi trường Cloud.\n  + Quen thuộc với Continuous Integration / Continuous Deployment.\n  + Tiếng Anh giao tiếp, đọc hiểu tốt.\n  + Khả năng làm việc độc lập và chịu áp lực trong môi trường nhịp độ cao.\n  + Kỹ năng phân tích, phản biện, tư duy logic và giải quyết vấn đề tốt.\n  + Đã tham gia xây dựng, phát triển, triển khai các giải pháp liên quan trong lĩnh vực CNTT cho ngành Tài chính, Ngân hàng là một lợi thế lớn.\n\nQuyền lợi:\n- Phúc lợi và chế độ đãi ngộ:\n  + Lương thỏa thuận: cạnh tranh với thị trường ở vị trí công việc.\n  + Thưởng theo kết quả kinh doanh, thưởng các dịp đặc biệt, các ngày lễ lớn.\n  + Xét tăng lương hàng năm theo thành tích đóng góp. Được xem xét ngay khi bạn là một nhân viên xuất sắc mà không cần chờ tới đánh giá định kỳ.\n  + Điều kiện làm việc linh hoạt.\n  + 12 ngày phép/năm + phép thâm niên.\n  + Môi trường sáng tạo, năng động, cởi mở.\n  + Hoạt động gắn kết, du lịch, team building … thường xuyên theo năm.\n  + Chương trình Bảo hiểm sức khỏe cao cấp theo cấp bậc và thâm niên.\n  + Cơ hội thăng tiến lên vị trí Quản lý.\n  + Hưởng đầy đủ các chế độ đãi ngộ khác theo quy định của pháp luật.\n  + Thời gian làm việc: Sáng: 8h00-12h00 (từ thứ 2 - thứ 6).\n- Môi trường làm việc:\n  + Môi trường làm việc năng động, cởi mở.\n  + Cơ hội thăng tiến, phát triển sự nghiệp.\n  + Ghi nhận sáng kiến, tôn trọng sự khác biệt.\n  + Cơ hội tham gia vào các dự án công nghệ tài chính lớn.\n\nĐịa điểm làm việc:\n- Hà Nội: 74 Khúc Thừa Dụ, Dịch Vọng, Cầu Giấy.\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 18:00).\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2310, 1156, 2, 'Leader React Native', '- Thiết kế và phát triển hệ thống front-end (giao diện người dùng) cho sản phẩm, dịch vụ Ngân hàng số được phát triển, cụ thể: \n- Phát triển ứng dụng mobile app cho React Native. \n- LEAD TEAM \n- Nhận bàn giao các file thiết kế, graphic asset từ UIUX designer, mô tả chức năng, hệ thống từ BA BU và BA IT. \n- Phối hợp với Kỹ sư DevOps và Kỹ sư Back-end quy trình khác, phát triển toàn bộ hệ thống ứng dụng. \n- Tham gia quản trị kiến trúc tổng thể của giải pháp. \n- Tuân thủ các tiêu chuẩn tích hợp APIS (ie Open Api, Oauth2 etc). \n- Thực hiện phát triển theo các tiêu chí an toàn bảo mật cao nhất. \n- Tích hợp chức năng theo dõi ứng dụng cho các use case phân tích (firebase analytics, Facebook Pixel, Google Analytics ...)\n - Xây dựng chiến lược kiểm thử ứng dụng cho phần mềm mình phụ trách unit test, SIT, regression test, application test, UI test, performance test, security test, đảm bảo an toàn chất lượng ứng dụng. \n- Đảm bảo ứng dụng làm việc tốt trên thiết bị, hệ điều hành, trình duyệt khác nhau (99% coverage). \n- Phát hành ứng dụng trên app store.\n\n- Có từ 1 năm kinh nghiệm vị trí Lead React Native.\n- Đã tham gia phát triển ít nhất 1-2 dự án lớn (quy mô từ 100 Man-month) trong các lĩnh vực: Mobile Banking, Internet Banking, Giao dịch chứng khoán/trái phiếu, Ví điện tử, Fintech, CRM, Ecommerce... \n- Có kiến thức sâu về: \n+ JavaScript, TypeScript, React Native, Redux, Context API. \n+ Các công cụ quản lý state management và tối ưu hiệu suất. \n+ Tích hợp API và xử lý authentication (OAuth2, JWT). \n+ Công cụ CI/CD, Fastlane, Git, Docker là lợi thế. - Ưu tiên ứng viên có kinh nghiệm: \n+ Phát hành và tối ưu ứng dụng trên App Store/Google Play. \n+ Xử lý performance tuning và memory management trên ứng dụng React Native. \n+ Làm việc với GraphQL, WebSocket.\n\n- Mức lương hấp dẫn, phù hợp với năng lực ( Thời gian làm việc: T2-T6)\n- Thưởng lễ tết, thưởng tháng lương thứ \n- 13 Hỗ trợ gửi xe hàng tháng \n- Có cơ hội trở thành “Gương mặt xuất sắc” của Công ty nếu hoàn thành xuất sắc \nnhiệm vụ; \n- Hưởng đầy đủ các chính sách và chế độ như: BHYT, BHXH, BHTN, . theo đúng quy định của Bộ Luật Lao động và của Công ty; \n- Tham gia các hoạt động nghỉ mát, team building \n- Làm việc trong môi trường cởi mở, năng động, khuyến khích sự sáng tạo.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2311, 1199, 2, 'Java Backend Developer', '- Phát triển các tính năng của hệ thống quản lý, kiểm soát các nghiệp vụ nội bộ ngân hàng bao gồm: mua sắm, ngân sách, tài sản, thanh quyết toán chi tiêu nội bộ, quản lý nhân sự ... \n- Tham gia vào các công đoạn: kiến trúc hệ thống, thiết kế chức năng, lập trình, unit test, viết tài liệu chức năng, tối ưu performance… \n- Lập trình hệ thống các ứng dụng trên nền Java Core, Java Spring Boot và các hệ thống Middleware trên nền tảng java \n- Viết code và Unit test theo mô hình phát triển DevOps CI/CD \n- Tối ưu performance các xử lý giải thuật \n- Tham gia tìm hiểu các công nghệ, kỹ thuật mới.\n\nYêu cầu ứng viên\n\nKiến thức:\n- Tốt nghiệp Đại học trở lên chuyên ngành CNTT hoặc các ngành tương đương \n\nKinh nghiệm:\n-  2 năm kinh nghiệm làm việc thực tế tại các tổ chức CNTT\n-  Nắm rõ quy trình xây dựng và triển khai phần mềm\n-  Sử dụng thành thạo Java core, có kinh nghiệm phát triển trên framework Spring Boot.\n-  Có hiểu biết về cơ sở dữ liệu: SQL, noSQL\n-  Có hiểu biết về việc sử dụng các công cụ quản trị như: Jija, Git,...\n\nƯu tiên:\n-  Ưu tiên ứng viên có kinh nghiệm về phát triển ứng dụng theo dạng Cloud Native như: Microservice, CICD, DepOps, Containerization...\n-  Ưu tiên Nhân sự đã từng tham gia triển khai các dự án theo mô hình Agile/Scrum\n-  Ưu tiên nhân sự có kinh nghiệm về xử lý bất đồng bộ, xử lý đa nhiệm, event sourcing, có kinh nghiệm về các hệ thống Message Queue (Kafka, RabbitMQ), có hiểu biết về xử lý cache, job.\n\nNgoại ngữ:\n- Có khả năng đọc viết tiếng Anh (cơ bản) nghe nói (nếu có thể).\n\nYêu cầu khác:\n- Kỹ năng giao tiếp và làm việc nhóm tốt\n- Sẵn sàng làm việc ngoài giờ hành chính\n- Tinh thần trách nhiệm, ham học hỏi\n\n---Ưu tiên nộp hồ sơ sớm---\n\nQuyền lợi\n\n- Thời gian làm việc 5 ngày/tuần (từ thứ Hai đến thứ Sáu).\n- Cơ hội thăng tiến, phát triển nghề nghiệp công bằng.\n- Thu nhập hấp dẫn, cạnh tranh.\n- Được hưởng chế độ BHXH, BHYT, BHTN và thưởng các ngày lễ tết theo quy định.\n- Được tham gia các chương trình đào tạo, huấn luyện của Công ty.\n- Môi trường làm việc chuyên nghiệp, thân thiện, năng động.\n- Thu nhập: 15 - 28 triệu (Tùy theo năng lực)\n\nĐịa điểm làm việc\n\n- Hà Nội: Lê Văn Lương, Cầu Giấy\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2312, 1224, 2, 'Nhân Viên Developer Objective C', 'Mô tả công việc:\n- Tham gia phát triển và duy trì các ứng dụng iOS bằng Objective-C.\n- Tối ưu hiệu suất, sửa lỗi và cải tiến trải nghiệm người dùng.\n- Triển khai game/app lên Apple Store.\n- Cập nhật công nghệ mới, đề xuất cải tiến quy trình phát triển.\n- Có khả năng làm việc độc lập và chủ động.\n- Ưu tiên ứng viên có kinh nghiệm với Unity hoặc Cocos Creator.\n\nYêu cầu ứng viên:\n- Có khả năng làm việc độc lập.\n- Có từ 1–3 năm kinh nghiệm lập trình iOS bằng Objective-C.\n- Thành thạo Xcode, UIKit, CoreData, CoreAnimation, RESTful API.\n- Đã từng làm việc với các thư viện/framework phổ biến trên iOS.\n- Có kinh nghiệm đưa game/app lên Apple Store.\n- Hiểu biết về kiến trúc MVC, MVVM và các Design Patterns trong iOS.\n- Có kinh nghiệm với Unity, Cocos Creator là lợi thế lớn.\n- Biết Swift là một điểm cộng.\n\nQuyền lợi:\n- Mức lương: 10tr-20tr\n- Thời gian làm việc: 8h-17h30( từ thứ 2- sáng thứ 7)\n- Cơ hội phát triển sự nghiệp, tham gia các dự án lớn.\n- Làm việc trong môi trường chuyên nghiệp, trẻ trung.\n- Được đào tạo, cập nhật công nghệ mới liên tục.\n\nĐịa điểm làm việc:\n- Hà Nội: Hà Đông\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n- Thứ 2- Thứ 6: 8h-17h30\n- Thứ 7: 8h-12h\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Đông, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2313, 1225, 2, 'Middle/Senior Fullstack Developer (PHP/Laravel)', 'Mô tả công việc:\n● Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng.\n● Tham gia phát triển các công đoạn phân tích yêu cầu, Detail Design, Coding, viết tài liệu API, Unit Test.\n● Sử dụng ngôn ngữ PHP và các framework như Laravel, Cake...\n● Xây dựng giao diện và backend của các hệ thống sử dụng PHP.\n\nYêu cầu ứng viên:\n● Kinh nghiệm 2 năm trở lên về một trong các PHP framework: Laravel, CodeIgniter, Symfony (Ưu tiên Laravel)... \n● Kỹ năng tư duy logic và thuật toán tốt, phân tích và giải quyết vấn đề, khả năng tự học, tự tìm hiểu.\n● Có tinh thần trách nhiệm cao (với công việc, với khách hàng, với thành viên của Team và với chính mình)\n● Có kinh nghiệm tối ưu thiết kế, truy vấn CSDL (Mysql, Mongodb)\n● Có kỹ năng làm việc độc lập, giải quyết vấn đề, kỹ năng giao tiếp\n● Thành thạo 1 framework FE (VueJs, ReactJs...)\n● Thành thạo các công cụ quản lý source code (Github, Gitlab...)\n● Ưu tiên có kinh nghiệm sử dụng Docker, Linux\n● Ưu tiên có kinh nghiệm về Golang.\n\nQuyền lợi:\n● Mức lương khởi điểm hấp dẫn tùy thuộc năng lực và kinh nghiệm làm việc. (Up to 40M)\n● Định kỳ review 6 tháng/1 lần theo năng lực.\n● Lương thưởng các ngày lễ, thưởng tháng 13. Ngoài ra còn thưởng thêm dự án tùy thuộc vào thành tích đóng góp cho dự án...\n● Được hưởng đầy đủ các chế độ của công ty: thưởng thành tích công việc hàng tháng, sinh nhật, teambuilding, nghỉ mát, gala.\n● Có lộ trình thăng tiến, phát triển theo năng lực rõ ràng.\n● Tham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động VN.\n● Thời gian làm việc: Từ 8h00 đến 17h00 (nghỉ Thứ 7, Chủ Nhật).\n\nĐịa điểm làm việc:\n- Hà Nội: FLC Landmark Tower Ngõ 60 Dương Khuê, Mỹ Đình, Nam Từ Liêm, Cầu Giấy.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2314, 1130, 2, 'Flutter Developer (Junior)', 'Mô tả công việc\n- Phân tích yêu cầu và thiết kế kiến trúc ứng dụng đa nền tảng.\n- Phát triển mã nguồn bằng ngôn ngữ Dart sử dụng Flutter.\n- Tối ưu hóa hiệu suất và đảm bảo ứng dụng tương thích trên cả iOS và Android.\n- Thực hiện công việc kiểm thử và đảm bảo chất lượng, sửa lỗi và cải tiến ứng dụng dựa trên phản hồi người dùng.\n- Làm việc chặt chẽ với các đội ngũ thiết kế, sản phẩm và backend.\n- Viết tài liệu kỹ thuật và comment mã nguồn.\n- Quản lý mã nguồn bằng các công cụ như Git, đảm bảo quy trình làm việc chuẩn và hiệu quả.\n- Tham gia họp dự án, báo cáo tiến độ và đề xuất giải pháp kỹ thuật khi cần thiết.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học ngành CNTT, ưu tiên ngành Công nghệ thông tin, Khoa học máy tính, Trí tuệ nhân tạo, hoặc các ngành liên quan.\n- Có 1 - 3 năm kinh nghiệm phát triển ứng dụng Flutter.\n- Thành thạo Dart và framework Flutter.\n- Kinh nghiệm với các công cụ phát triển Flutter như Android Studio, VS Code.\n- Hiểu biết về thiết kế UI/UX đa nền tảng.\n- Kinh nghiệm làm việc với API và dịch vụ backend.\n- Có kỹ năng giao tiếp và thuyết trình tốt, có khả năng làm việc nhóm tốt\n- Có kỹ năng giải quyết vấn đề, xử lý tình huống tốt\n- Có kỹ năng quản lý thời gian, sắp xếp công việc tốt\n- Có khả năng làm việc độc lập và làm việc nhóm tốt\n- Tận tâm, cầu thị có trách nhiệm, chủ động và tích cực trong công việc\n- Thái độ tốt,lắng nghe, phản hồi tích cực, đổi mới và phát triển.\n\nQuyền lợi\n1. Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án\n- Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm theo năng lực.\n\n2. Chế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n- Tham gia BHXH sau thử việc, 12 ngày phép năm.\n- Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ.\n- Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết...\n- Học miễn phí các sản phẩm ngôn ngữ của công ty.\n\n3. Cơ hội phát triển bản thân\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Môi trường product đi sâu chuyên môn về sản phẩm, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác marketing, sales, chăm sóc khách hàng và khách hàng.\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp.\n- Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6.\n\nĐịa điểm làm việc\n- Hà Nội: 315 Trường Chinh, Thanh Xuân.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2315, 1226, 2, 'Playable Ads Developer (Junior Up)', 'Mô tả công việc\n- Nghiên cứu kịch bản và xây dựng kế hoạch sản xuất Playable Ads trên các nền tảng như Facebook, Google, Unity Ads,...\n- Tham gia thiết kế, lập trình và tối ưu playable với hiệu suất nhẹ, tương thích cao\n- Phối hợp cùng team Marketing, Creative để đảm bảo playable đáp ứng đúng mục tiêu chiến dịch\n- Phân tích dữ liệu A/B testing để đánh giá hiệu quả quảng cáo và đề xuất cải tiến\n- Tìm hiểu, cập nhật xu hướng thiết kế/motion/code trong lĩnh vực quảng cáo tương tác và game marketing\n\nYêu cầu ứng viên\nKnowledge:\n- Tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán-Tin hoặc các lĩnh vực kỹ thuật liên quan\n- Tối thiểu 1 năm kinh nghiệm làm việc ở vị trí tương đương (Unity, Playable Ads)\n- Hiểu rõ quy trình phát triển sản phẩm Playable Ads, hành vi người dùng trong môi trường tương tác ngắn\n- Nắm vững lập trình hướng đối tượng, vòng đời sản phẩm và tối ưu hóa hiệu suất \n\nSkills\n- Thành thạo lập trình gameplay, UI tương tác và các animation logic đơn giản\n- Biết debug nhanh, tối ưu CPU/memory usage, quản lý asset nhẹ, dùng hiệu quả\n- Có tư duy hệ thống: viết code có cấu trúc tốt, dễ mở rộng và tái sử dụng\n- Ưu tiên nếu có khả năng xây dựng template, thư viện nội bộ hoặc tool hỗ trợ production\n\nAttitude\n- Chủ động, cầu tiến và có trách nhiệm cao với chất lượng sản phẩm đầu ra\n- Không ngại thử nghiệm, chỉnh sửa nhanh theo vòng lặp A/B testing\n- Có đam mê với game, hứng thú với sản phẩm mang tính tương tác cao, đo lường hiệu suất\n- Mong muốn phát triển lâu dài trong lĩnh vực Performance Creative/Game Tech\n\nQuyền lợi\nTHU NHẬP\n- Mức lương: Up to $800\n- Nhận 100% lương cứng, tăng lương theo quy định của công ty\n- Phụ cấp ăn trưa nhân viên chính thức: 1.000.000 VNĐ/tháng\n- Thu nhập dựa theo kết quả và hiệu suất công việc\n\nCƠ HỘI PHÁT TRIỂN\n- Mở rộng, nâng cao kiến thức và kỹ năng chuyên môn\n- Trải nghiệm thực chiến tại các dự án toàn cầu đang chạy\n- Có lộ trình phát triển sự nghiệp được cá nhân hóa rõ ràng\n\nMÔI TRƯỜNG LÀM VIỆC\n- Trải nghiệm môi trường quốc tế năng động, chuyên nghiệp\n- Hưởng 100% đãi ngộ chăm sóc đời sống hàng ngày\n\nCHÍNH SÁCH PHÚC LỢI\n- Công ty đóng đầy đủ các loại Bảo hiểm theo quy định của pháp luật (BHXH, BHYT, BH thất nghiệp,..)\n- Được khám sức khỏe tổng quát định kì miễn phí tại bệnh viện: Hồng Ngọc, Thu Cúc, Vinmec.\n- Chế độ cưới hỏi/đám hiếu, quà ngày Lễ/ Tết và các chế độ phúc lợi khác.\n- Thưởng Tết dương, 8/3, 30/4-1/5, Trung thu, giữa năm, 2/9, 20/10, Giáng sinh.\n- Chia sẻ thành quả liên tục, không giới hạn dựa trên performance.\n- Thời gian làm việc hành chính:\n- Từ Thứ 2 - Thứ 6. Nghỉ Thứ 7, Chủ Nhật\n- Sáng: 8:30 - 12:00, Chiều: 13:00 - 18:00, Nghỉ giữa chiều 15:00 - 15:30\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 10 - The West Tower - 265 Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2316, 1187, 2, 'Senior Operation Engineer', 'As an Operation Engineer at Rikkeisoft, you will be responsible for operating and managing a variety of systems and applications deployed as services. You will ensure stable service delivery through proactive monitoring, system inspections, and collaboration with development and overseas teams.\n\nKey Responsibilities:\n- Manage and respond to service requests (SR) via Jira.\n- Monitor system performance and health to ensure stability and availability.\n- Perform DevOps-based deployments for web, app, and hybrid platforms.\n- Conduct regular preventive maintenance (PM) activities to mitigate service disruptions.\n- Oversee operations across Cloud, Application, and DBaaS platforms (monitoring only; no direct incident resolution required).\n- Handle database operations on cloud platforms.\n- Prepare and submit operation reports summarizing key outcomes and improvement points.\n- Collaborate with the team in Seoul regarding operational processes and updates.\n- Analyze application logs and system behavior to identify improvement areas.\n\nQualifications:\n- Bachelor\'s degree in Software Engineering, Information Technology, or related fields.\n- Certifications in Software Engineering, IT Operations, or relevant areas are a plus.\n\nExperience & Skills:\n- Hands-on experience in system operations and synchronization management.\n- Strong understanding and practical skills in cloud infrastructure (e.g., Kubernetes, Helm, Docker).\n- Familiarity with monitoring and logging systems (e.g., PLG stack).\n- Experience with DevOps tools such as Git, Jenkins.\n- Proficiency in working with databases, especially PostgreSQL.\n- Programming knowledge in Java (Spring Framework, Spring Boot, Spring Security), Node.js, and Vue.js.\n- Experience with application log analysis and issue diagnosis.\n- Understanding of Linux-based environments.\n- Familiarity with authentication and authorization protocols such as OAuth2 and OIDC.\n- Knowledge of message queue systems, particularly RabbitMQ.\n\nPreferred Skills:\n- Ability to collaborate effectively in a bilingual (English/Korean) environment.\n- Experience working in cross-functional teams across regions.\n- Proactive mindset and strong problem-solving skills.\n\nSalary: Negotiate.\nPackage: At least 13 months/ year. Review periodically following company policy.\nBonus: Tet bonus, project bonus, holiday bonus, HR referral bonus...\nSeniority allowance (working time from 2 years or more).\nParticipate in learning and training activities inside and outside the company, accumulate learning points, develop G-Points on the company\'s management system.\n2 days of per week and 12 leave days per year.\nClubs and many cultural - sports - art activities sponsored or supported by the company (For example: Football, table tennis, badminton, swimming, music, English, games... ).\nEnsure health: Periodic health check, support to buy high quality health insurance...\nJoin the Rikkei Care Health Insurance Plan.\nMental comfort: Playing music on demand every day, happy hour, team building activities...\n\nWorking location:\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy.\n\nWorking time:\n- Monday - Friday (from 08:00 to 17:00)\n- Flexible registration from 08:00 - 09:00 to 17:00 - 18:00 from Monday - Friday.\n\nApplication method:\nCandidates apply online by clicking on "Apply" below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2317, 1227, 2, 'Kỹ Sư AI (Junior)', 'Mô tả công việc:\n- Phát triển mô hình AI/ML: Tham gia vào việc thiết kế, xây dựng và thử nghiệm các mô hình Machine Learning (ML) và Deep Learning (DL) dưới sự hướng dẫn của các kỹ sư cấp cao.\n- Xây dựng và ứng dụng LLM: Hỗ trợ triển khai và tối ưu hóa các mô hình ngôn ngữ lớn (LLM) trong các dự án liên quan đến xử lý ngôn ngữ tự nhiên (NLP).\n- Phân tích dữ liệu: Tham gia vào các giai đoạn tiền xử lý dữ liệu, phân tích dữ liệu để hỗ trợ phát triển các giải pháp AI.\n- Nghiên cứu và phát triển: Học hỏi, nghiên cứu các công nghệ mới trong lĩnh vực AI/ML, và áp dụng vào các dự án thực tế.\n- Hợp tác nhóm: Làm việc chặt chẽ với các nhóm kỹ thuật và sản phẩm để phát triển và triển khai các giải pháp AI.\n\nYêu cầu ứng viên:\n- Bằng cấp: Tốt nghiệp đại học hoặc sắp tốt nghiệp chuyên ngành Khoa học Máy tính, Công nghệ Thông tin, Toán Tin hoặc các ngành liên quan.\n- Kinh nghiệm: 1-2 năm kinh nghiệm trong phát triển AI/ML là một lợi thế, nhưng không bắt buộc. Chấp nhận sinh viên mới ra trường có kiến thức nền tảng vững chắc về AI/ML.\n- Kỹ năng: Thành thạo một ngôn ngữ lập trình như Python, R, hoặc Java.\n- Khả năng sử dụng Tiếng Anh giao tiếp thành thạo (IELTS 6.5 trở lên).\n- Hiểu biết về các framework ML/DL như TensorFlow, PyTorch, Keras là một lợi thế.\n- Có kiến thức cơ bản về xử lý và phân tích dữ liệu.\n- Tinh thần học hỏi, có khả năng làm việc nhóm và chịu được áp lực công việc.\n- Ưu tiên: Ứng viên đã từng thực hiện các dự án liên quan đến AI/ML trong quá trình học tập hoặc thực tập. Ưu tiên các bạn có thành tích giải thưởng quốc gia, đại học.\n\nQuyền lợi:\n1. Cơ hội thăng tiến\n   - Đến với UPP Global Technology, ứng viên có cơ hội được:\n   - Làm việc trong môi trường trẻ, minh bạch với cơ hội thăng tiến rõ ràng.\n   - Được tạo điều kiện tối đa để phát triển năng lực cá nhân, tập thể và năng suất làm việc.\n\n2. Lương thưởng\n   - Lương thỏa thuận theo năng lực up to 20M. Nhận 100% lương trong quá trình thử việc.\n   - Lương tháng 13, định kỳ đánh giá hiệu quả công việc hàng năm. Thưởng khi có thành tích xuất sắc.\n   - Chăm sóc sức khỏe định kỳ hàng năm.\n   - Ngoài các gói bảo hiểm cơ bản theo quy định của Luật Lao Động, bạn còn được tham gia gói bảo hiểm sức khỏe của PTI sau thời gian thử việc.\n   - Được cấp laptop, máy tính làm việc.\n   - Tiền lương làm thêm giờ theo quy định của nhà nước.\n   - Cách thức ứng tuyển: Ứng viên gửi 1 bản CV Tiếng Anh kèm link các dự án đã làm.\n   - Ngày làm việc: Làm việc từ T2-T6; nghỉ T7, CN, Lễ Tết.\n   - Thời gian làm việc linh hoạt: 8 tiếng/ngày, trong khoảng 8h00 - 10h00 và kết thúc trong khoảng 17h00 đến 19h00.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2318, 1228, 2, 'Business Developer - Project', 'Job Overview\nWe are seeking a dynamic and experienced Business Developer - Northern Project to lead and grow our project sales in the Northern region of Vietnam. The role focuses on residential and hospitality segments, with the responsibility to establish key business relationships, promote the brand, identify new opportunities, and support project execution.\nChúng tôi đang tìm kiếm một ứng viên năng động và giàu kinh nghiệm cho vị trí Nhân viên Kinh doanh Dự án khu vực miền Bắc, tập trung vào phân khúc nhà ở và khách sạn. Ứng viên sẽ chịu trách nhiệm phát triển kinh doanh, xây dựng mối quan hệ chiến lược, quảng bá thương hiệu, tìm kiếm cơ hội mới và phối hợp thực hiện dự án.\n\nKey Responsibilities / Trách nhiệm chính\n- Develop and expand the project sales channels in the Northern region (including residential & hospitality sectors)/Phát triển và mở rộng kênh bán hàng dự án tại khu vực miền Bắc (bao gồm nhà ở và khách sạn).\n- Build strong relationships with developers, construction companies, and industry stakeholders through direct visits/Thiết lập và duy trì mạng lưới quan hệ chặt chẽ với các chủ đầu tư, công ty xây dựng và đối tác trong lĩnh vực dự án thông qua việc gặp gỡ trực tiếp.\n- Promote brand and product portfolio to architects and interior designers/Quảng bá thương hiệu và danh mục sản phẩm đến các kiến trúc sư, nhà thiết kế nội thất.\n- Identify and pursue new project opportunities/Tìm kiếm và phát triển các cơ hội kinh doanh mới.\n- Coordinate with internal departments (sales support, technical, logistics) to ensure smooth project execution/Phối hợp với các bộ phận nội bộ (hỗ trợ kinh doanh, kỹ thuật, logistics) để đảm bảo dự án được triển khai hiệu quả.\n- Develop long-term strategies for project business growth/Xây dựng chiến lược phát triển dài hạn cho kinh doanh dự án.\n- Conduct market research and provide updates on project trends in the residential and hospitality sectors/Nghiên cứu thị trường và cập nhật xu hướng dự án trong lĩnh vực nhà ở và khách sạn ảnh hưởng đến định hướng phát triển của công ty.\n- Prepare weekly and monthly reports to the Head of Hanoi Office/Lập báo cáo hàng tuần/hàng tháng cho Trưởng Văn phòng Hà Nội.\n\nYêu cầu ứng viên\n- University degree (preferably in Architecture, Construction, or Technology)/Tốt nghiệp đại học (ưu tiên chuyên ngành Kiến trúc, Xây dựng hoặc Công nghệ).\n- At least 5 years of experience in project sales or business development/Tối thiểu 5 năm kinh nghiệm trong lĩnh vực kinh doanh dự án hoặc phát triển kinh doanh.\n- Proven track record and existing network with decision-makers in the project business/Có kinh nghiệm và mạng lưới quan hệ với các nhà ra quyết định trong lĩnh vực dự án.\n- Excellent communication and presentation skills in both Vietnamese and English/Kỹ năng giao tiếp và thuyết trình xuất sắc bằng cả tiếng Việt và tiếng Anh.\n- Professional, persuasive, and service-oriented personality/Tác phong chuyên nghiệp, thuyết phục và có tinh thần phục vụ khách hàng.\n- Self-motivated, eager to learn, and proactive in work/Chủ động, cầu tiến và có tinh thần học hỏi.\n- Strong problem-solving and leadership skills are an advantage/Khả năng giải quyết vấn đề và tố chất lãnh đạo là lợi thế.\n- Proficient in Microsoft Office and digital tools/Thành thạo các ứng dụng văn phòng và công cụ kỹ thuật số.\n- Willingness to travel for business/Sẵn sàng đi công tác khi cần thiết.\n- Able to work independently and in team settings/Có khả năng làm việc độc lập cũng như phối hợp nhóm hiệu quả.\n\nThu nhập\n- Thu nhập khi đạt 100% KPI:  Thoả thuận\n- Thu nhập tính theo tỷ lệ đạt KPI\n- Lương cứng:  20 - 30 triệu VND \n- Lương cứng không phụ thuộc doanh số\n\nQuyền lợi\n- 5-day work week (Saturday & Sunday off)/Làm việc 5 ngày/tuần, nghỉ Thứ Bảy & Chủ Nhật.\n- 12 annual leave days/12 ngày nghỉ phép năm theo quy định.\n- 4 paid sick leave days per year/4 ngày nghỉ bệnh nguyên lương mỗi năm.\n- 13th month salary bonus/Lương tháng 13.\n- Full social insurance based on actual salary/Đóng BHXH, BHYT, BHTN trên lương thực tế.\n- MIC personal health insurance package/Gói bảo hiểm sức khỏe cá nhân MIC.\n- After completing 1 year of service, the company will provide an additional MIC personal health insurance package for the employee\'s spouse and children/ Sau khi hoàn thành 1 năm làm việc, công ty sẽ mua thêm gói bảo hiểm sức khỏe cá nhân MIC dành cho vợ/chồng và con của nhân viên.\n- Annual premium health check/ Gói khám sức khỏe định kỳ cao cấp.\n- Annual company trip & monthly team-building activities/Du lịch công ty hằng năm & team building hàng tháng.\n- Training & development opportunities/Cơ hội tham gia các khóa đào tạo chuyên môn và kỹ năng.\n- Annual performance & salary review / Đánh giá hiệu suất và xét tăng lương hàng năm.\n- Professional & friendly work environment/ Môi trường làm việc chuyên nghiệp, thân thiện và gắn kết.\n- Holiday bonuses (New Year, Labor Day, National Day)/Thưởng các dịp lễ lớn: Tết Dương lịch, 1/5, 2/9.\n- Provide phone and transportation support for customer engagement.\nCung cấp điện thoại và phương tiện hỗ trợ cho việc tiếp xúc khách hàng.\n\nĐịa điểm làm việc\n- Hà Nội: Hanoi Rep. office- Trang An complex, No.1 Phùng Chí Kiên, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2319, 1229, 2, 'Backend Developer', 'Lập trình viên Backend (Backend Developer) chịu trách nhiệm xây dựng, phát triển và duy trì các thành phần phía server của ứng dụng web, mobile hoặc hệ thống phần mềm. Công việc chính của BE Developer là xử lý logic nghiệp vụ, truy xuất cơ sở dữ liệu, quản lý API và tối ưu hóa hiệu suất hệ thống.\n\nNhiệm vụ chính\n- Thiết kế và phát triển API: Xây dựng các API RESTful hoặc GraphQL để phục vụ dữ liệu cho frontend và các hệ thống khác.\n- Quản lý cơ sở dữ liệu: Thiết kế, tối ưu truy vấn SQL (PostgreSQL, MySQL, SQL Server) hoặc NoSQL (MongoDB, Firebase, Redis).\n- Xây dựng hệ thống xử lý dữ liệu: Tối ưu logic nghiệp vụ, thực hiện các tác vụ batch, xử lý hàng đợi (queue) bằng Redis, RabbitMQ, BullMQ.\n- Quản lý bảo mật và phân quyền: Xử lý xác thực người dùng (JWT, OAuth, OpenID Connect), bảo vệ dữ liệu và chống các cuộc tấn công như SQL Injection, XSS, CSRF.\n- Tích hợp API với các hệ thống khác: Làm việc với các hệ thống thanh toán (PayPal, Stripe, VNPAY), email (SendGrid, Mailgun), SMS (Zalo ZNS),...\n- Quản lý hiệu suất và tối ưu hệ thống: Caching (Redis, Memcached), load balancing, tối ưu tốc độ truy vấn, giảm độ trễ API.\n- Triển khai và vận hành hệ thống: Sử dụng Docker, Kubernetes, CI/CD (GitHub Actions, GitLab CI).\n- Xử lý lỗi và gỡ lỗi: Phân tích log, debugging hệ thống, xử lý lỗi runtime.\n- Ứng dụng AI hỗ trợ trong coding: code completion, debug, refactor, unit test…\n\nTrách nhiệm\n- Đảm bảo chất lượng mã nguồn: Viết code sạch, dễ bảo trì, tuân thủ các tiêu chuẩn lập trình và best practices.\n- Thực hiện theo quy trình Agile/Scrum: Tham gia họp sprint planning, daily stand-up, review, và retrospective để đảm bảo tiến độ và chất lượng sản phẩm.\n- Nghiên cứu và áp dụng công nghệ mới: Cập nhật xu hướng công nghệ, đề xuất giải pháp cải tiến hiệu suất và tối ưu hệ thống.\n- Xử lý sự cố kỹ thuật và bảo trì hệ thống: Giám sát, phát hiện lỗi, tối ưu hiệu suất và đảm bảo hệ thống vận hành ổn định.\n\nPhối hợp với các thành viên trong nhóm: Làm việc chặt chẽ với frontend, QA, product owner để phát triển và triển khai sản phẩm hiệu quả.\n\nYêu cầu ứng viên\nChúng tôi cần những người tài năng để thảo luận, định hướng giải pháp, giải quyết vấn đề, tập trung vào khách hàng và tin rằng bất kỳ thử thách nào cũng có thể được thu nhỏ với tư duy, công cụ và thái độ đúng đắn. Chúng tôi đang tìm kiếm:\n\n1. Trình Độ & Kinh Nghiệm\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Phần mềm, Khoa học Máy tính hoặc lĩnh vực liên quan.\n- Tối thiểu 3 năm kinh nghiệm làm Backend Developer với một trong các ngôn ngữ sau:\n  - Node.js (NestJS, ExpressJS)\n  - C# (.NET Core 5+)\n  - Có kinh nghiệm xây dựng và triển khai hệ thống Microservices.\n\n2. Kiến Thức & Kỹ Năng Kỹ Thuật\n- Thành thạo Docker, Linux, Git, CI/CD.\n- Hiểu và triển khai tốt RESTful API, WebSocket, tối ưu hiệu suất API.\n- Kinh nghiệm làm việc với cơ sở dữ liệu SQL & NoSQL, bao gồm:\n  - PostgreSQL, MySQL, MongoDB\n  - Viết và tối ưu truy vấn, cải thiện hiệu suất database.\n- Tích hợp hệ thống bên thứ ba: Firebase, cổng giao hàng, cổng thanh toán (Stripe, PayPal, VNPAY).\n- Có kinh nghiệm xử lý Task Scheduler, Background Job, Queue Processing (BullMQ, RabbitMQ, Kafka).\n- Ưu tiên ứng viên có kinh nghiệm làm việc trên nền tảng SaaS.\n- Khả năng thiết kế và đề xuất giải pháp kiến trúc hệ thống phù hợp với yêu cầu dự án.\n- Lợi thế nếu có kinh nghiệm với Python (Flask, Django).\n\n3. Hiểu Biết Về Bảo Mật & Quy Trình Phát Triển\n- Nắm vững các tiêu chuẩn bảo mật API & bảo vệ dữ liệu (JWT, OAuth2, OWASP Top 10).\n- Có hiểu biết về quy trình phát triển phần mềm Agile/Scrum, tham gia Sprint Planning, Daily Standup, Code Review.\n\n3.2. Kỹ năng mềm\n- Khả năng tự học nhanh và thích nghi với công nghệ mới, sẵn sàng cập nhật xu hướng.\n- Chủ động trong công việc, có tinh thần trách nhiệm cao, cam kết với tiến độ và chất lượng.\n- Kỹ năng làm việc nhóm tốt, sẵn sàng hỗ trợ đồng đội để đạt mục tiêu chung.\n- Đam mê công nghệ, linh hoạt trong việc tiếp cận và sử dụng các công cụ, framework mới.\n\nQuyền lợi\n- Thu nhập cạnh tranh, tùy thuộc vào kinh nghiệm và khả năng\n- Chế độ chính sách lương, thưởng, BHXH, BHYT, BHTN,... đầy đủ.\n- Có cơ hội trở thành một trong những vị trí key của Công ty\n- Môi trường làm việc trẻ trung, năng động và chuyên nghiệp\n- Được đào tạo kỹ năng, công nghệ mới Chuyển đổi số, AI,.. \n- Được huấn luyện đào tạo phát triển năng lực (Kiến thức, kỹ năng, thái độ, thói quen) và định hướng phát triển sự nghiệp để thành công.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tòa nhà SBI, Đường 03, CVPM Quang Trung, P. Tân Chánh Hiệp, Quận 12\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (8h00 -17h00)\n- Thứ 7 (8h00 -12h00) - Online\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2320, 1230, 2, 'Senior FE (70% Angular + 30% ReactJS)', 'Mô tả công việc:\n- Build UI components for maximum performance and reusability\n- Participate in code reviews and contribute to team knowledge sharing.\n- Troubleshoot and debug applications.\n- Stay up-to-date with the latest industry trends and technologies.\n- Go onsite\n\nYêu cầu ứng viên:\n- At least 4-5 years of experience in web development technologies & have in-depth knowledge of Angular 2+, Reactjs, Javascript.\n- Familiarity with state management libraries (such as NgRx)\n- Ability to present the problem easy to understand, always ready to support the team\n- Knowledge of RESTful APIs and web services.\n- Experience with GIT source control, Agile process\n- Strong problem-solving skills and attention to detail.\n- Good communication and teamwork skills.\n- Eagerness to learn and adapt to new technologies.\n- Experience working with Taiga UI and micro-frontend is an advantage\n\nQuyền lợi:\n- Attractive remuneration package (competitive salary, bonus)\n- Salary review twice a year\n- Social Insurance, Health insurance, Unemployment insurance in accordance with Vietnam Labor Law\n- 12 Annual Leaves & 10 Sick Leaves per year;\n- Flexible training programs\n- Very good working environment with 3 core values: Collaboration as methodology & Behave like family; Compete by high quality\n- Company trip, Monthly happy hour and other interesting activities\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 3 Cenxspace, Tòa Nhà Dolphin 28 Trần Bình, Mĩ Đình 2, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2321, 1144, 2, 'Fullstack Developer', 'Mô tả công việc:\n- Lập trình Frontend, Backend cho các dự án sản phẩm của Công ty và khách hàng.\n- Thiết kế và triển khai phần mềm đáp ứng các yêu cầu kinh doanh và công nghệ của khách hàng.\n- Quản lý và giám sát các nhân viên cấp dưới trong dự án phát triển phần mềm, đảm bảo các nhân viên hoàn thành công việc đúng tiến độ và đạt được chất lượng mong đợi.\n- Đưa ra các giải pháp về phần mềm đảm bảo hiệu suất và tính ổn định của hệ thống.\n- Đảm bảo chất lượng và hiệu suất của sản phẩm đạt được tiêu chuẩn và yêu cầu của khách hàng.\n- Tư vấn và đề xuất giải pháp công nghệ thông tin mới nhất để giúp công ty phát triển bền vững và cạnh tranh trong thị trường.\n- Tìm kiếm và áp dụng công nghệ mới nhất, đưa ra đánh giá và áp dụng chúng vào các dự án để tối ưu hóa hiệu suất và tính ổn định của hệ thống.\n\nYêu cầu ứng viên:\n- Tổt nghiệp các trường ĐH, CĐ chuyên ngành CNTT, Khoa học máy tính hoặc chuyên ngành có liên quan.\n- Ít nhất 4 năm kinh nghiệm ở vị trí tường đương trở lên.\n- Thành thạo ít nhất 2 trong các ngôn ngữ sau:\n  - Backend: C#, Java, Python, Ruby(RoR), PHP, Golang, NodeJS\n  - Frontend: Java script (ReactJS/VueJS/AngularJS/...).\n- Có kinh nghiệm quản lý team 2 member trở lên.\n- Hiểu biết và có kinh nghiệm thiết kế, triển khai, cài đặt cloud service (AWS, Azure, ...), micro servive.\n- Có các chứng chỉ phát triển phần mềm liên quan.\n- Tiếng anh giao tiếp tốt.\n\nQuyền lợi:\n- Thu nhập Upto 40M.\n- Thử việc 2 tháng full 100% lương.\n- Tham gia BHXH, BHYT, BHTN theo quy định luật lao động.\n- Tham gia BH sức khoẻ VBI.\n- Review lương 2 lần/năm.\n- Lương tháng 13, thưởng các dịp Lễ, Tết, Hiếu hỉ, Sinh nhật,...\n- Hỗ trợ chi phí thì chứng chỉ JLPT, ISTQB, AWS,...\n- Phụ cấp chi phí gửi xe.\n- Phụ cấp thâm niên, thưởng project xuất sắc.\n- Quỷ cầu lông, bóng đá hằng tuần.\n- Du lịch, nghỉ dưỡng hằng năm theo chính sách của công ty.\n- Khám sức khỏe định kỳ hàng năm.\n- Cơ hội thăng tiến rõ ràng.\n- Cơ hội đến các nước đối tác làm việc: Nhật Bản, Hàn Quốc, Singapore, Úc.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lầu 10 Mekong Tower, 235 Cộng Hoà, Phường 13, Tân Bình.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2322, 1231, 2, 'Nhân Viên Lập Trình Và Vận Hành Máy CNC', 'Mô tả công việc\n+ Lập trình, xuất chương trình vận hành máy tiện CNC\n+ Theo dõi quá trình máy chạy, sửa chương trình ngay khi phát hiện sự cố, đảm bảo thời gian chạy máy CNC\n+ Tối ưu quy trình công nghệ, đạt hiệu quả về thời gian gia công, chất lượng gia công, chế độ cắt, dụng cụ cắt gọt\n+ Báo cáo định mức thời gian hoàn thành một công đoạn\n+ Báo cáo khi Ban Giám đốc yêu cầu\n\nYêu cầu ứng viên\n+ Tốt nghiệp các ngành nghề kỹ thuật, cơ khí, chế tạo máy, cắt gọt kim loại\n+ Thành thạo lập trình tiện CNC\n+ Thành thạo phần mềm Mastercam\n+ Đọc hiểu bản vẽ gia công\n\nQuyền lợi\n+ Lương thỏa thuận theo kinh nghiệm và năng lực \n+ Lương tháng 13, thưởng lễ tết theo hiệu quả kinh doanh\n+ Chế độ BHXH, BHYT, BHTN theo quy định (công ty đóng 100%)\n+ Cơm trưa văn phòng (25.000 đồng/ ngày)\n+ Tăng ca theo Quy định của Nhà nước. Tiền ăn ca đêm 15.000 đồng/đêm (17h-20h)\n+ Cấp phát đồng phục, thiết bị phục vụ cho công việc tương ứng 750.000đ/năm\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 260/16 Tô Ngọc Vân, Linh Đông, Thủ Đức, Thủ Đức\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 07:30 đến 16:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2323, 1232, 2, 'Cocos Developer', 'Mô tả công việc\n- Lập trình game trên nền tảng Cocos Creator.\n- Làm việc với git, hiểu và sử dụng tốt git flow.\n- Tham gia phát triển các dự án game hướng tới thị trường global\n- Phối hợp với các thành viên trong team để vận hành và tối ưu hoá sản phẩm\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc chuyên ngành liên quan\n- Kinh nghiệm làm việc với git, hiểu và sử dụng tốt git flow.\n- Có kiến thức & kinh nghiệm làm việc với Cocos Creator.\n- Có sản phẩm trên store là 1 lợi thế lớn\n- Hiểu rõ OOP\n- Đam mê, yêu thích làm game, khả năng tư duy, sáng tạo tốt\n- Có khả năng thiết kế cấu trúc có thể mở rộng và có tính bảo trì tốt\nQuyền lợi\n- Thưởng kinh doanh trực tiếp bằng % (Profit Share) tính theo đóng góp của ứng viên vào các dự án đã tham gia.\n- Thưởng các ngày lễ: 30/04, 01/05, 02/09, Tết Dương Lịch.\n- Quà các ngày lễ: 08/03, 20/10, Trung Thu, Tết Âm Lịch. \n- Review tăng lương linh hoạt không giới hạn. Phụ thuộc vào tiềm năng, khả năng và mức độ đóng góp của ứng viên.\n- BHXH, BHYT, BHTN, 12 ngày nghỉ phép/năm. Nếu không dùng hết sẽ được chuyển sang năm tiếp theo.\n- Du lịch, Team building tối thiểu 2 lần/năm. \n- Tổ chức sinh nhật hàng tháng. Happy Time (đồ ăn,đồ uống,hoa quả và các trò chơi nội bộ) 2 lần/tuần.\n- Khu pantry gồm cafe, trà, đồ uống miến phí.\n- Khu giải trí gồm Bàn Bi-a, PS, Board Game...\n- Khu nội bộ gồm các phòng ngủ đẩy đủ trang thiết bị giành cho nhân sự cần ở lại công ty.\n- Trải nhiệm các hoạt động văn hóa doanh nghiệp chỉ có ở GPLAY.\n- Được cung cấp đầy đủ trang thiết bị, máy móc để làm việc.\n- Cơ hội học hỏi và tham gia xây dựng các dự án game chất lượng, phát triển long-term.\n- Cơ hội được đào tạo chuyên môn, phát triển tư duy và tầm nhìn bởi đội ngũ Leader có nhiều năm kinh nghiệm trong ngành.\n- Có cơ hội thăng tiến lên các vị trí Manager, Leader.\n- Môi trường thân thiện, trẻ trung, hiện đại, không giới hạn.\nĐịa điểm làm việc\n- Hà Nội: 53 Triều Khúc, Thanh Xuân\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- không chấm công khi làm việc\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2324, 1233, 2, 'Junior Mobile Developer (React Native)', '- Tham gia phát triển trong các dự án với ngôn ngữ JAVASCRIPT.\n- Xây dựng ứng dụng trên mobile với framework REACT NATIVE.\n- Xây dựng components, thư viện, APIs có thể tái sử dụng cho REACT NATIVE, ANDROID, IOS.\n- Xây dựng các quy trình kiểm thử phần mềm (Unit Tests, UI Tests, Integration Tests & End-To-End Tests).\n- Tương tác dữ liệu với APIs được đội BACKEND cung cấp.\n- Phát triển kỹ năng thiết kế UI/UX.\n- Có định hướng nghề nghiệp rõ ràng về soft skills lẫn hard skill.\n\n- 1 năm kinh nghiệm, mạnh mảng IOS và tốt nghiệp ngành liên quan.\n- Hiểu biết về HTML, CSS, JAVASCRIPT ES6, Có kiến thức về REACTJS, REACT NATIVE (Functional Programming, Hooks).\n- Sử dụng Xcode hoặc Android Studio và các công cụ hỗ trợ: Simulator, Instrument.\n- Sử dụng tốt trên môi trường phát triển Linux & macOS.\n- Có kinh nghiệm sử dụng TYPESCRIPT, REDUX, MOBX.\n- Có kiến thức về RESTful APIs.\n- Có khả năng thiết kế giao diện.\n- Hiểu biết về nguyên tắc SOLID (Single Responsibility Principle).\n- Hiểu biết về quy trình kiểm thử phần mềm.\n- Đã từng sử dụng Android (Java/Kotlin) hoặc iOS (Swift).\n- Đã sử dụng qua các công cụ như GITHUB, JIRA, BITBUCKET, TRELLO.\n\n- Thời gian làm việc linh động: 5 ngày/tuần (thứ 2 – thứ 6) ; 8h30 – 17h30 ; nghỉ trưa 1,5 tiếng.\n- 12 ngày phép năm, 4 ngày phép đột xuất + nghỉ lễ, tết.\n- Thử việc: 60 ngày.\n- Tham gia đầy đủ BHXH, BHYT, BHTN theo quy định.\n- Khám sức khỏe định kỳ hằng năm.\n- Cung cấp thiết bị làm việc.\n- Được tham gia các buổi training nội bộ nhằm nâng cao kiến thức.\n- Môi trường làm việc năng động, trẻ trung, thoải mái.\n- Team building, tiệc ăn uống, giải trí hằng tháng, year-end party, v.v...\n- Quà, thưởng: Sinh nhật, lễ tết, trung thu, giáng sinh, v.v….', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2325, 1234, 2, 'Trưởng Nhóm Development (Mobile)', 'Quản lý nhóm phát triển ứng dụng di động, đảm bảo tiến độ, chất lượng dự án và đóng góp vào chiến lược công nghệ của công ty.\nNHIỆM VỤ CHÍNH:\nPhân công, giám sát công việc và hỗ trợ đội ngũ phát triển.\nThiết kế, xây dựng và tối ưu ứng dụng di động (iOS, Android).\nĐảm bảo chất lượng code và trải nghiệm người dùng.\nBáo cáo tiến độ và phối hợp với các bộ phận liên quan.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học chuyên ngành CNTT, Khoa học Máy tính, hoặc tương đương.\nTối thiểu 3 năm kinh nghiệm phát triển ứng dụng di động và 1-2 năm ở vai trò quản lý nhóm.\nThành thạo lập trình native (Swift/Objective-C, Kotlin/Java) và/hoặc cross-platform (React Native, Flutter).\nHiểu biết sâu về API RESTful, giao tiếp dữ liệu và cơ sở dữ liệu (SQLite, Realm, Firebase).\nKỹ năng code review, quản lý dự án và sử dụng các công cụ như Git, Jira.\nƯu tiên biết sử dụng Lark và thành thạo các công cụ AI để tối ưu và nâng cao hiệu suất công việc.\nKỹ năng lãnh đạo và giải quyết vấn đề tốt.\n\nQuyền lợi:\nMức lương: Thỏa thuận theo năng lực (Upto 40tr/th)\nLàm việc trong môi trường chuyên nghiệp, năng động và thân thiện, phát triển với tốc độ rất cao, cơ hội thăng tiến cao, Chế độ đãi ngộ rất tốt, thu nhập với lương thưởng hấp dẫn. Môi trường trẻ năng động.\nĐược hưởng đầy đủ các chế độ theo Luật Lao động Việt Nam (BHXH, BHYT…)\nCác chế độ phúc lợi khác: Thưởng các ngày lễ Tết, sinh nhật, cưới xin,...Tham quan, nghỉ mát. Thưởng tết tháng thứ 13,...\nCông ty cung cấp điện thoại bàn, máy tính, hỗ trợ phí gửi xe tại tòa nhà.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Mipec 229 Tây Sơn, Đống Đa\n\nThời gian làm việc:\nTừ Thứ 2 đến Thứ 6: 08:00 đến 17:00\nThứ 7: 08:00 đến 12:00\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2326, 1235, 2, 'Kỹ Sư Cơ Khí', 'Mô tả công việc:\n- Thiết kế và lập trình các chương trình điều khiển cho máy móc, thiết bị tự động hóa trong lĩnh vực cơ khí.\n- Phát triển và tối ưu hóa các thuật toán điều khiển, đảm bảo hiệu suất và độ chính xác cao.\n- Lập trình và tích hợp các thiết bị ngoại vi (sensor, actuator) vào hệ thống điều khiển.\n- Viết tài liệu kỹ thuật, hướng dẫn sử dụng cho các chương trình đã lập trình.\n- Hỗ trợ kỹ thuật cho quá trình sản xuất, bảo trì và sửa chữa máy móc.\n- Cập nhật và nâng cấp các hệ thống điều khiển hiện có.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Cơ khí, Tự động hóa, Điện tử viễn thông hoặc các chuyên ngành liên quan.\n- Không yêu cầu kinh nghiệm.\n- Có kiến thức cơ bản về điện tử, cơ khí và lập trình.\n- Có khả năng đọc hiểu bản vẽ kỹ thuật.\n- Khả năng làm việc độc lập và làm việc nhóm.\n- Cẩn thận, tỉ mỉ, chịu được áp lực công việc.\n- Kỹ năng giao tiếp tốt và khả năng giải quyết vấn đề.\n\nQuyền lợi:\n- Mức lương cạnh tranh, tương xứng với năng lực và kinh nghiệm.\n- Chế độ bảo hiểm đầy đủ theo luật lao động.\n- Được tham gia các khóa đào tạo nâng cao nghiệp vụ.\n- Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.\n- Thưởng các ngày lễ, tết và các hoạt động team building.\n\nĐịa điểm làm việc:\n- Hải Phòng: An Đồng - An Dương, An Dương\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 07:30 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2327, 1236, 2, 'Nhân Viên Lập Trình Máy Phay CNC', 'Mô tả công việc\n- Xây dựng và hoàn thiện quy trình công nghệ gia công, trang thiết bị, đồ gá, dao cụ và các thiết bị phụ trợ phục vụ cho việc gia công các sản phẩm cơ khí của Công ty.\n- Học hỏi và làm quen với các phần mềm lập trình máy móc, ngôn ngữ lập trình, và các quy trình sản xuất.\n- Vận hành máy phay CNC: Đọc bản vẽ, chuẩn bị dụng cụ cắt, chỉnh sửa chương trình...\n- Tham gia vào quá trình cải tiến và tối ưu hóa quy trình sản xuất.\n- Tuân thủ các quy định về an toàn lao động và bảo vệ môi trường.\n- Thực hiện các công việc khác theo sự phân công của cấp trên.\n\nYêu cầu ứng viên\n- Tốt nghiệp trung cấp, cao đẳng hoặc đại học chuyên ngành kỹ thuật (Cơ khí, cơ khí chế tạo, cắt gọt kim loại, kỹ thuật cơ khí...).\n- Có kinh nghiệm từ 1 năm trong lĩnh vực lập trình máy móc là một lợi thế.\n- Nắm vững kiến thức cơ bản về phay CNC, gia công cắt gọt kim loại.\n- Khả năng làm việc độc lập và làm việc nhóm tốt.\n- Có tinh thần trách nhiệm cao, cẩn thận, tỉ mỉ.\n- Khả năng học hỏi nhanh, tiếp thu kiến thức mới.\n- Có khả năng đọc hiểu tài liệu kỹ thuật, đọc hiểu bản vẽ 2D.\n- Có thể làm việc theo ca.\n\nQuyền lợi\n- Mức lương cạnh tranh, phù hợp với năng lực và kinh nghiệm.\n- Được đóng bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật.\n- Được tham gia các chương trình đào tạo, nâng cao nghiệp vụ.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Có cơ hội thăng tiến trong công việc.\n- Được hưởng các chế độ phúc lợi khác theo quy định của công ty.\n\nĐịa điểm làm việc\n- Hà Nội: gần Khu Công Nghiệp Ngọc Hồi, xã Liên Ninh, Thanh Trì.\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 06:00 đến 14:30)\n- Thứ 2 - Thứ 7 (từ 14:00 đến 22:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2328, 1237, 2, 'Senior Developer', 'Mô tả công việc\n- Tuân thủ các tiêu chuẩn lập trình, xây dựng mã nguồn chất lượng cao, dễ bảo trì.\n- Luôn duy trì động lực và cập nhật các xu hướng, công nghệ mới nhất trong lĩnh vực phát triển web.\n- Hướng dẫn và hỗ trợ các thành viên cấp dưới nâng cao kỹ năng, đảm bảo đạt được hiệu suất và năng lực phù hợp với mục tiêu dự án.\n- Tích cực tham gia các hoạt động chia sẻ kiến thức và cải tiến quy trình làm việc liên tục.\n\nYêu cầu ứng viên\n[Bắt buộc]\n- Tối thiểu 2 năm kinh nghiệm thiết kế và tối ưu các hệ thống hiệu suất cao.\n- Hiểu rõ và vận dụng tốt các mô hình lập trình hướng đối tượng (OOP) và lập trình hàm (Functional Programming).\n- Thành thạo ít nhất một trong các ngôn ngữ lập trình như: Java, Scala, Python, TypeScript.\n- Có kinh nghiệm làm việc với các frontend framework như: React, Vue hoặc Angular; và giao tiếp với RESTful hoặc GraphQL APIs.\n- Nắm vững quy trình phát triển phần mềm theo phương pháp Agile/Scrum.\n- Có hiểu biết về ít nhất một trong các nền tảng đám mây như AWS, GCP hoặc Azure.\n[Không bắt buộc]\n- Có kinh nghiệm lập trình với Scala là một lợi thế.\n- Đã từng sử dụng các công cụ hỗ trợ lập trình bằng AI như GitHub Copilot, Cursor AI hoặc Windsurf AI.\n- Có kinh nghiệm thiết kế, tối ưu truy vấn và truy cập cơ sở dữ liệu.\n- Thành thạo kỹ thuật viết kiểm thử (Test-Driven Development - TDD) và thiết kế testcase.\n- Khả năng giao tiếp hoặc đọc hiểu tiếng Nhật là một điểm cộng.\n\nQuyền lợi\n- Mức lương đến 1500$\n- Chế độ làm việc linh hoạt Flexible time (7:30 AM - 06:30PM). VD: Check in 7:30 có thể check out 16:30.\n- Địa điểm làm việc: làm việc tại văn phòng Hà Nội\n- Tăng lương và thưởng 2 lần/năm\n- Bảo hiểm sức khỏe Bảo Việt, khám sức khỏe hàng năm ở bệnh viện uy tín\n- Du lịch Công ty, các câu lạc bộ bóng đá, bơi, gym ...\n\nĐịa điểm làm việc\n- Hà Nội: Discovery Complex, 302 Cầu Giấy, Dịch Vọng, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2329, 1157, 2, 'Junior Dev Odoo', '- Tham gia trực tiếp vào team dự án phát triển và triển khai hệ thống Odoo nội bộ và cho các khách hàng\n- Công việc cụ thể:\n+ Phụ trách thiết kế chi tiết, lập trình, unit test, xử lý lỗi của chương trình sử dụng ngôn ngữ lập trình Python trên framework Odoo.\n+ Kết hợp với BA, Tester, Operator và các bên liên quan để xây dựng hệ thống cho khách hàng, giải quyết các nhu cầu chuyển đổi số, phục vụ sự phát triển kinh doanh của khách hàng.\n+ Thực hiện coding, lập trình các module, fix bugs,.. theo yêu cầu công việc\n+ Ưu tiên ứng viên có kinh nghiệm làm modul HRM, kho, kế toán.\n+ Các công việc khác được giao bởi Project Manager và Group Leader.\n\n– Thành thạo ngôn ngữ Python. Có từ 2 năm kinh nghiệm làm việc với framework Odoo\n– Có mong muốn theo làm Odoo lâu dài.\n– Có kiến thức và kỹ năng lập trình database; ưu tiên thành thạo PostgreSQL\n– Đọc hiểu tiếng Anh tốt\n– Ưu tiên:\n+ Tổt nghiệp chuyên ngành công nghệ thông tin các trường:  Đại học Bách khoa Hà Nội, Học viện Kỹ thuật quân sự, Đại học Công nghệ — ĐHQGHN, Học viện Kỹ thuật Mật mã, …..\n+ Đã có kinh nghiệm làm việc với các hệ thống phần mềm mã nguồn mở\n+ Có khả năng hiểu business logic, tìm tòi hướng giải quyết các vấn đề mới\n+ Có kinh nghiệm về cài đặt và sử dụng Linux , apache\n+ Có kinh nghiệm customize module/report; xử lý đọc/ghi file Excel\n+ Có khả năng quản lý và đào tạo cho những thành viên khác.\n\nLương: Thỏa thuận theo năng lực.\nThưởng:\nThưởng tháng 13.\nThưởng dựa trên kết quả kinh doanh của công ty.\nBảo hiểm: Đóng bảo hiểm đầy đủ theo mức lương.\nDu lịch: Công ty tổ chức một chuyến du lịch mỗi năm.\nPhúc lợi:\nQuầy pantry miễn phí.\nCác sự kiện nội bộ: team building, sinh nhật hàng tháng, ngày Quốc tế Phụ nữ, ngày Quốc tế Nam giới,...\nQuà tặng nhân dịp Trung Thu, sinh nhật,...\nCơ hội nghề nghiệp:\nCơ hội đi onsite tại Nhật Bản (ngắn hạn hoặc dài hạn).\nCơ hội chia sẻ ý tưởng, lắng nghe và phát triển nghề nghiệp theo mong muốn cá nhân.\nLộ trình thăng tiến rõ ràng.\nThời gian làm việc:\nTừ thứ 2 đến thứ 6, từ 8h30 đến 17h30 (có thể linh hoạt thời gian vào 30 phút).\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 29, tòa nhà Handico Tower, KĐTM Mễ Trì Hạ, Đường Phạm Hùng, Phường Mễ Trì Thành phố Hà Nội, Việt Nam., Nam Từ Liêm.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2330, 1238, 2, 'Nhân Viên Software Developer (Dev)', 'Mô tả công việc\n1. Phát triển Backend:\n- Thiết kế, phát triển và duy trì các dịch vụ phụ trợ bằng Laravel và ecosystem của Laravel.\n- Tối ưu hóa truy vấn cơ sở dữ liệu để đảm bảo hiệu suất và khả năng mở rộng của hệ thống.\n- Triển khai và duy trì API RESTful cho giao diện người dùng và tích hợp của bên thứ ba.\n- Đảm bảo các biện pháp bảo mật tốt nhất được tuân thủ trong hoạt động API và cơ sở dữ liệu.\n\n2. Phát triển Frontend: \n- Xây dựng và duy trì các tính năng hướng tới người dùng bằng VueJS (Vue 3).\n- Làm việc chặt chẽ với các nhà thiết kế UI/UX để tạo ra các thành phần giao diện có thể tái sử dụng và mở rộng quy mô.\n\n3. Các công việc khác:\n- Làm việc chặt chẽ với nhóm nghiệp vụ để chuyển đổi các yêu cầu thành các giải pháp kỹ thuật.\n- Viết code sạch, hiệu quả và dễ bảo trì theo các chuẩn ISO đưa ra.\n- Thực hiện đánh giá mã và đóng góp vào việc cải thiện quy trình phát triển.\n- Cập nhật những xu hướng mới nhất về Laravel, VueJS và các công nghệ liên quan.\n\nYêu cầu ứng viên\n- Trình độ chuyên môn: Tốt nghiệp đại học trở lên\n- Có ít nhất 2 năm kinh nghiệm làm việc với Laravel, VueJs trong môi trường sản xuất.\n- Kinh nghiệm với VueJS (Vue 2 hoặc Vue 3), bao gồm phát triển dựa trên thành phần.\n- Thành thạo MySQL/PostgreSQL, bao gồm tối ưu hóa truy vấn và thiết kế cơ sở dữ liệu.\n- Kinh nghiệm xây dựng và tích hợp API RESTful.\n- Quen thuộc với Git và làm việc trong môi trường phát triển cộng tác.\n- Bằng Cử nhân (hoặc cao hơn) chuyên ngành CNTT hoặc các lĩnh vực liên quan, ưu tiên ứng viên đến từ các trường đại học hàng đầu.\n\nQuyền lợi\n- Tiền lương: thoả thuận khi phỏng vấn\n- Phụ cấp ăn trưa\n- Được làm việc trong môi trường năng động, hiện đại. \n- Tạo điều kiện học hỏi và nâng cao khả năng chuyên môn.\n- Được hưởng các chế độ BHXH, BHYT, BHTN, tham quan, nghỉ phép, thưởng năng suất, nghỉ các ngày lễ theo quy định của Luật lao động hiện hành.\n\nĐịa điểm làm việc\n- Hà Nội: Bệnh viện Đa Khoa Phương Đông, Số 9, Phố Viên, Cổ Nhuế 2, Bắc Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2331, 389, 2, 'Senior Developer', 'Mô tả công việc\n- Quản lý DEV Team, hướng dẫn và hỗ trợ chuyên môn cho các thành viên trong nhóm.\n- Định hướng, phân tích và thiết kế kiến trúc hệ thống, đảm bảo hệ thống bền vững, an toàn thông tin, hiệu suất cao, dễ bảo trì, nâng cấp và mở rộng.\n- Lập trình Java core/Java web, API trên nền core framework của công ty hoặc các framework khác tùy sản phẩm, dự án.\n- Tham gia phát triển các hệ thống sản phẩm, dịch vụ của công ty: Phát triển các Module của sản phẩm/dịch vụ; Phối hợp với BA, Tester fix bug, update module; Merge code.\n- Thống nhất các mục tiêu, sản phẩm cũng như đưa ra phương án kỹ thuật của dự án.\n- Xử lý các vấn đề kỹ thuật phát sinh trong quá trình phát triển.\n- Các công việc khác theo yêu cầu của Trưởng bộ phận IT.\n\nYêu cầu ứng viên\n- Tốt nghiệp ĐH trở lên chuyên ngành Công nghệ thông tin; Kỹ thuật phần mềm, Hệ thống thông tin, ...hoặc các ngành tương đương.\n- Có từ 5 năm kinh nghiệm trở lên tham gia dự án thực tế, trong đó có ít nhất 2 năm kinh nghiệm Leader.\n- Thành thạo ngôn ngữ lập trình Java; Database: Oracle; Operating System: CentOS\n- Hiểu biết về SQL Language\n- Có kinh nghiệm lập trình Backend (server side), API\n- Có kinh nghiệm lập trình xử lý file PDF, xử lý ảnh.\n- Có thể đọc hiểu tài liệu kỹ thuật bằng tiếng anh.\n\nQuyền lợi\n- Thu nhập: từ 30 đến 35 triệu/tháng, thỏa thuận phù hợp với năng lực ứng viên.\n- Chế độ bảo hiểm, phúc lợi theo quy định của pháp luật và chính sách công ty.\n- Thưởng hằng năm, thưởng lễ tết, thưởng nóng cho những thành tích nổi bật.\n- Tham gia đầy đủ BHXH và các chế độ theo quy định của Bộ Luật lao động.\n- Chế độ du xuân, nghỉ mát cùng Công ty. Các hoạt động gắn kết nội bộ.\n- Môi trường làm việc từ Lãnh đạo đến nhân viên đều rất trẻ trung, năng động.\n- Cơ hội phát triển sự nghiệp bền vững và đề cao các giá trị Văn hóa doanh nghiệp.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 5, Toà nhà ACCI, Số 210 Lê Trọng Tấn, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7: 8h00 - 12h00\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Thanh Xuân', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2332, 1239, 2, 'Chief Developer/Software Architect–ERP Software', 'Mô tả công việc\n- Explore, Define, and review technical solutions (.JavaEE, Hibernate/JPA, JSF, PrimeFaces, Postgresql database)\n- Present and discuss technical solutions with directors\n- Working in a team of Chief Developers to support modification development for junior Devs\n- Support the team to create a proposal for a new scope of projects/modies\n- Communicate directly with 3rd vendor supporter\n- Support the team to handle production technical issues: debugging, performance, workload, security...\n- Explore, research, propose, and implement new technology\n\nYêu cầu ứng viên\n- Proven experience in a Chief Dev or leadership role, preferably within an IT company, especially the ERP product\n- Ability to analyze complex technical issues and provide innovative solutions\n- Strong background in system design, architecture, and development\n- Knowledge of the latest technology trends and best practices in the IT industry\n- Strong problem-solving skills and a proactive approach to addressing challenges\n- Excellent communication and interpersonal skills, with fluency in English\n- Integrity and passion for code quality and improvement, passion for sharing knowledge to build a quality Developer team\n- Ability to maintain a high level of confidentiality and manage the security risk\n\nQuyền lợi\n- Salary: Negotiate\n- Monthly salary 13+14\n- To be paid insurance according to the provisions of labor law (social insurance, health insurance, unemployment insurance)\n- Health insurance and medical checking package for manager level\n- Increase salary 2 times/ year\n- To celebrate birthday, participate in teambuilding activities, annual travel\n- Holidays and New Year holidays as prescribed by law\n- Company holidays, including: 14 days off, 10 days off sick, 01 Christmas day, 0.5 international women\'s day, 0.5 Vietnamese women\'s day... \n- Fruits every Thursday and free cake, tea, coffee,...  \n\nĐịa điểm làm việc\n- Hà Nội: Tầng 25, tháp C, tòa nhà Central Point số 219 Phố Trung Kính, Phường Yên Hòa, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2333, 1240, 2, 'Nhân Viên IT ( Thiết Kế Và Hoàn Thiện Store Shopify) - Thu Nhập 20 Triệu +++', 'Mô tả công việc:\nThiết kế và hoàn thiện store Shopify bao gồm:\nTrang chủ, trang sản phẩm, trang bộ sưu tập, trang add to cart, tối ưu hóa trang checkout,\nCài đặt và sử dụng các app trên shopify như bootsale, upsale, klaviyo,\nTối ưu hóa tốc độ load trang, khả năng chuyển đổi... \nAm hiểu sử dụng các công cụ xây dựng website, cũng như cài đặt và cấu hình các ứng dụng cơ bản trên Shopify.\n\nYêu cầu ứng viên:\nFrontend, backend thành thạo.\nThành thạo JavaScript/TypeScript\nHiểu biết sâu sắc về RESTful API và dịch vụ web\nCó kỹ năng thiết kế wireframe, layout website.\nƯu tiên các ứng viên chưa lập gia đình để đảm bảo sự tập trung cao và khả năng phát triển không gián đoạn.\nCó khả năng sử dụng tiếng Anh tốt, đặc biệt trong đọc hiểu tài liệu.\nLàm việc chăm chỉ và chủ động.\n\nQuyền lợi:\nThời gian làm việc: 8h - 17h30 từ Thứ Hai đến Sáng Thứ Bảy, nghỉ trưa từ 12h - 14h\nMức lương: 9.000.000 - 20.000.000/tháng\nThưởng tháng lương thứ 13\nThưởng vào các dịp Lễ, Tết,…\nNhân sự làm việc chính thức có 12 ngày nghỉ phép/năm\nChế độ bảo hiểm theo Luật lao động quy định.\nTeambuilding, nghỉ mát, du lịch hàng năm\nChế độ sinh nhật, hiếu hỉ, thai sản vv... theo quy định pháp luật và hỗ trợ thêm từ Công ty.\n\nĐịa điểm làm việc:\nHà Nội: 34/521 Nguyễn Trãi, Thanh Xuân, Thanh Xuân\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nSáng thứ 7\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2334, 1241, 2, 'Chuyên Viên Lập Trình Backend (PHP)', 'Mô tả công việc:\n- Tham gia phát triển, bảo trì và tối ưu hoá các hệ thống website, ứng dụng web sử dụng ngôn ngữ PHP\n- Làm việc với các framework phổ biến như Laravel, Symfony, Codelgniter,...\n- Thiết kế và triển khai các API, tích hợp với hệ thống bên thứ ba\n- Tham gia phân tích yêu cầu, đề xuất giải pháp kỹ thuật phù hợp\n- Phối hợp với các team khác (Frontend, QA, UI/UX) để đảm bảo chất lượng sản phẩm\n- Tham gia review code và cải tiến quy trình phát triển phần mềm.\n\nYêu cầu ứng viên:\n- Kinh nghiệm: Có từ 2 năm kinh nghiệm.\n- Kiến thức:\n  - Có kiến thức về cơ sở dữ liệu.\n  - Có kiến thức về ngôn ngữ lập trình PHP.\n  - Có kiến thức về tìm kiếm trong lập trình.\n  - Có kiến thức về lập trình hướng đối tượng.\n- Kỹ năng/khả năng:\n  - Có kỹ năng code các ngôn ngữ backend (ưu tiên PHP).\n  - Có kinh nghiệm trong việc xây dựng hệ thống, xây dựng server.\n  - Có khả năng tư duy và thiết kế database.\n  - Có khả năng viết API.\n\nQuyền lợi:\n- Chế độ đãi ngộ:\n  - Mức lương: cạnh tranh hấp dẫn (sẵn sàng offer cao khi đủ năng lực) + Phụ cấp (Ăn ca: 700.000 VNĐ/tháng; Gửi xe: 120.000 VNĐ/tháng; trợ cấp máy tính cá nhân (nếu có): 300.000 VNĐ/tháng).\n  - Chính sách thưởng: Thưởng Lễ, Tết, sinh nhật + thưởng dự án + thưởng thâm niên + Lương tháng 13 + các thưởng khác theo quy định Công ty tại thời điểm hiện hành.\n  - Làm việc trong môi trường trẻ trung, năng động, coi trọng năng lực và khả năng sáng tạo.\n  - Thường xuyên tổ chức các hoạt động mini game, chương trình các ngày Lễ, Tết, sinh nhật, tham gia hoạt động Teambuilding của công ty...\n- Đào tạo – Phát triển:\n  - Cơ hội tiếp cận và học hỏi công nghệ tiên tiến, công nghệ mới.\n  - Được công ty tạo điều kiện và hỗ trợ khi tham gia các khóa đào tạo, phát triển năng lực.\n  - Có cơ hội làm những việc thách thức, phát huy hết khả năng bản thân.\n  - Tham gia các sản phẩm công nghệ mới theo kế hoạch phát triển của công ty.\n- Chăm sóc sức khỏe, đời sống:\n  - Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n  - Được tặng quà, thăm hỏi nhân các dịp: sinh nhật, cưới hỏi, hiếu hỉ, ốm đau...\n  - Có thể tham gia các câu lạc bộ thể thao: đá bóng, tập yoga, thể dục cải thiện sức khoẻ...\n\nĐịa điểm làm việc:\n- Hà Nội: 97-99 Láng Hạ, Đống Đa.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00).\n- Checkin linh hoạt từ 7.30-9.00 am.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2335, 1221, 2, 'Golang Developer', 'Mô tả công việc\n- Tham gia phát triển hệ thống backend sử dụng Golang cho các dự án IT phần mềm;\n- Tham gia các công đoạn phát triển phần mềm: tìm hiểu yêu cầu, phân tích, thiết kế...;\n- Phối hợp làm việc cùng đội ngũ có chuyên môn cao;\n- Cùng bộ phận tham gia nghiên cứu & phát triển các sản phẩm Web sử dụng ngôn ngữ/công nghệ khác như PHP(Basic / Laravel / CodeIgniter / Yii2), JavaScript/Vuejs (NuxtJS) / ReactJS (NextJS), NodeJS(NestJS), Python (Flask), PosgreSQL, MongoDB, Redis, Docker, Serverless, Kubernetes, AWS (ECS / EKS), Kafka, Elasticsearch...;\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của team leader;\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của quản lý trực tiếp.\n\nYêu cầu ứng viên\n- Có ít nhất 3 năm kinh nghiệm phát triển dự án với Golang;\n- Nắm vững kiến thức về phát triển Back-end;\n- Tư duy logic tốt về cấu trúc dữ liệu và giải thuật và thuật toán;\n- Có kinh nghiệm làm việc với Docker;\n- Có kinh nghiệm với MySQL hoặc PostgreSQL, thiết kế cơ sở dữ liệu, tối ưu hóa câu truy vấn;\n- Có kinh nghiệm làm việc chuyên sâu với git, git flow và github flow;\n- Có kinh nghiệm về UnitTest;\n- Có kinh nghiệm deploy dự án lên môi trường test, staging hoặc production cho khách hàng.\n\nƯu tiên ứng viên (không bắt buộc):\n- Có kinh nghiệm làm việc với cloud: AWS là 1 lợi thế;\n- Có kinh nghiệm với các framework Frontend, như VueJS, ReactJS, Angular… là một lợi thế;\n- Có kiến thức và tư duy tốt, sáng tạo và đam mê công nghệ, kiên trì và khả năng tự học tốt;\n- Có khả năng làm việc teamwork tốt cũng như làm việc độc lập, có kinh nghiệm làm việc trong các dự án theo mô hình Agile/Scrum là lợi thế.\n\nQuyền lợi\n- Mức lương up to 30,000,000 VND/tháng (chưa bao gồm thưởng dự án, thưởng lễ tết, và các khoản thưởng khác...);\n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Nghỉ thứ 7, Chủ nhật + Nghỉ phép theo Quy định của Pháp luật hiện hành;\n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty;\n- Khám sức khỏe định kỳ 1 năm/1 lần;\n- Bảo hiểm chăm sóc sức khỏe 24/24 ( PVI Care);\n- Tham gia các Câu lạc bộ văn hóa, thể thao trong công ty: CLB Bóng đá, CLB Game…\n- Tham gia các hoạt động tập thể sôi động theo tháng/quý/năm: Nghỉ mát hàng năm, Teambuilding, Gala cuối năm…\n\nĐặc biệt\n- Được hỗ trợ 100% chi phí tham gia các khóa học kỹ năng mềm, các khóa đào tạo chuyên môn, luyện thi các chứng chỉ uy tín trong và ngoài nước và khen thưởng khi đạt chứng chỉ chuyên môn;\n- Học tập không giới hạn qua tài khoản học trực tuyến Udemy;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật;\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 17, 18, 19 Tòa Central Point, 219 Trung Kính, Cầu Giấy\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2336, 74, 2, 'Senior Frontend Developer', 'Phạm vi công việc\n- Thiết kế và triển khai các chức năng của sản phẩm phụ trách sử dụng VueJS/ReactJS\n- Triển khai giao diện người dùng (UI) và cải thiện trải nghiệm người dùng (UX) phù hợp với hoạt động kinh doanh của khách hàng nhằm thúc đẩy chuyển đổi số (DX)\n- Xác định yêu cầu và xây dựng tài liệu đặc tả phối hợp với quản lý sản phẩm và nhà thiết kế\n- Rà soát thiết kế và lập trình của các kỹ sư khác\nMôi trường phát triển\n- Lập trình: TypeScript/HTML/CSS\n- Khung: VueJS, NuxtJS, ReactJS, NextJS\n- Cơ sở hạ tầng: AWS/GCP\n- CI/CD: Circle CI/Bitrise/GitHub Actions\n- Công cụ kiến ​​thức: Confluence/esa\n- VCS: GitHub\n- Khác: Slack/Jira/Trello\n\nYêu cầu ứng viên\nPhải có:\n- Thấu hiểu sứ mệnh và giá trị của Nodo\n- Hơn 4 năm kinh nghiệm trong vai trò phát triển phần mềm: Lập trình viên Frontend\n- Kinh nghiệm với ngôn ngữ TypeScript\n- Kinh nghiệm với các framework frontend (VueJS, ReactJS, v.v.)\n- Kiến thức và khả năng giải thích các nguyên lý vận hành web và sự khác biệt giữa các trình duyệt\n- Kiến thức cơ bản về bảo mật ứng dụng web\n- Kỹ năng phát triển và vận hành sử dụng các framework khác nhau\nƯu tiên:\n- Kiến thức về Java/Python\n- Kinh nghiệm phát triển các front-end microservices\n- Kinh nghiệm phát hiện và giải quyết sự cố từ nhật ký\n- Kinh nghiệm quyết định và triển khai chính sách kỹ thuật của nhóm với vai trò trưởng nhóm kỹ thuật\n- Kinh nghiệm sử dụng và hiểu các thư viện và framework\n- Kinh nghiệm phát hành và đóng góp vào OSS (Open Source Software)\n\nQuyền lợi\n- Mức lương 25 - 35 triệu tùy theo năng lực\n- Cơ hội thăng tiến rõ ràng trong môi trường làm việc năng động\n- Được tham gia các khóa học nâng cao kỹ năng chuyên môn\n- Chế độ bảo hiểm đầy đủ theo quy định của pháp luật\n- Thưởng theo hiệu quả công việc và các dịp lễ tết\n- Được tham gia các hoạt động team building, du lịch hàng năm\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Văn hóa phẳng, cởi mở và chia sẻ với đội ngũ quản lý thân thiện\n\nĐịa điểm làm việc\n- Hà Nội: Showroom Audi - Số 8 Phạm Hùng - Phường Mễ Trì, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2337, 1157, 2, 'Thực Tập Sinh DEV', '- Thực tập sinh sẽ được đào tạo và hướng dẫn để có thể nắm bắt được quy trình làm việc. Tham gia on-job training tại các dự án thực tế của công ty. Sau quá trình thực tập sẽ được xét lên nhân viên chính thức.\n- Công ty có đa dạng các dự án sử dụng đa dạng các loại ngôn ngữ, công nghệ. Thực tập sinh có thể được bố trí tham gia dự án phù hợp đúng theo nguyện vọng và định hướng cá nhân. Các dự án được tham gia là các dự án phát triển phần mềm của công ty, bao gồm: các dự án outsource web app, các dự án công nghệ mới Cloud (AWS/Azure), các dự án về nghiên cứu dữ liệu (Data Science sử dụng AI&amp; BI), các dự án product của công ty. Domain chủ yếu về nghiệp vụ tài chính ngân hàng, quản trị doanh nghiệp,...\n- Tham gia vào quá trình xây dựng phát triển, triển khai sản phẩm tới khách hàng Nhật Bản và Việt Nam.\n- Tham gia thiết kế chi tiết, lập trình, unit test, xử lý lỗi của chương trình với các công nghệ và các ngôn ngữ lập trình đa dạng.\n\n- Yêu cầu bắt buộc:\n+ Đang học hoặc Tốt nghiệp chuyên ngành công nghệ thông tin các trường:  Đại học Bách khoa Hà Nội, Học viện Kỹ thuật quân sự, Đại học Công nghệ — ĐHQGHN, Học viện Kỹ thuật Mật mã, …..\n• Có thể làm fulltime, nếu part-time yêu cầu tối thiểu đi làm được 5 buổi (sáng hoặc chiều) trên tuần.\n• Có mong muốn được làm, chịu khó học hỏi, và có định hướng phát triển sâu về kỹ thuật.\n• Có thể đọc hiểu tài liệu kỹ thuật bằng tiếng Anh.\n- Các yêu cầu ưu tiên:\n• Ưu tiên cho các ứng viên từng có kinh nghiệm internship, hoặc kinh nghiệm làm việc thực tế, làm các dự án cá nhân, có cái nhìn tổng quan về các hệ thống.\n• Có khả năng hiểu business logic, có kỹ năng phân tích và giải quyết vấn đề.\n\n- Được đào tạo, hướng dẫn bởi các Technical Leader siêu giỏi và có tâm (Các anh chị Leader đa số đều độ tuổi 8x, đầu 9x và có từ 5 đến trên 10 năm kinh nghiệm)\n- Trợ cấp hàng tháng: 5 triệu VND (gross)\n- Các chế độ khác:\nCơ hội lên chính thức sau quá trình thực tập. Lộ trình thăng tiến rõ ràng.\nCó cơ hội đi onsite tại Nhật Bản (ngắn hạn/dài hạn) cho các ứng viên biết tiếng Nhật.\nĐược chia sẻ, lắng nghe và tạo điều kiện phát triển theo đúng mong muốn.\n- Thời gian làm việc T2 – T6. Giờ làm việc linh hoạt\n- Bạn được tạo điều kiện luân chuyển công việc (theo nguyện vọng và tình hình dự án) và thử thách bản thân ở nhiều mảng công việc với tính chất khác nhau.\n\n- Hà Nội: Tầng 29, tòa nhà Handico Tower, KĐTM Mễ Trì Hạ, Đường Phạm Hùng, Phường Mễ Trì Thành phố Hà Nội, Việt Nam, Nam Từ Liêm, Nam Từ Liêm\n\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2338, 1176, 2, 'Senior Java Developer', 'Mô tả công việc\n- Tham gia phân tích yêu cầu của khách hàng\n- Đưa ra thiết kế chi tiết để xử lý nghiệp vụ theo thiết kế kiến trúc của hệ thống\n- Quản lý team dev (5-7 người) và review code.\n- Làm việc với SA và Tech Lead để đưa ra thiết kế một số module trong hệ thống\n- Xây dựng code base và đảm bảo team phát triển theo đúng thiết kế\nYêu cầu ứng viên\n- Nắm vững ngôn ngữ lập trình Java, Spring Framework và ORM Framework\n- Nắm vững các design pattern trong thiết kế hướng đối tượng\n- Nắm vững spring boot và ORM framework\n- Nắm vững về Kafka, Redis, các hệ quản trị cơ sở dữ liệu SQL, NoSQL\n- Đọc hiểu và viết tốt các tài liệu thiết kế UML\n- Có khả năng phân tích và đưa ra giải pháp xử lý tốt\n- Làm việc với hệ điều hành Linux thành thạo.\n- Nắm vững kiến trúc dữ liệu và giải thuật, các loại giao tiếp trong hệ thống\n- Có kinh nghiệm làm việc với CI/CD.\n- Có kinh nghiệm làm việc với kiến trúc Microservice, SOA,...\n- Nắm vững quy trình phát triển phần mềm waterfall, Agile\n- Có kinh nghiệm lead team nhỏ, quản lý plan, task của các thành viên trong team tốt.\n- Có kinh nghiệm thiết kế hệ thống, thiết kế database cho toàn bộ hệ thống là lợi thế\nQuyền lợi\n- Chế độ lương hấp dẫn upto 45M\n- Lương tháng 13, tiền thưởng cho nhân viên xuất sắc và tập thể xuất sắc\n- Bảo hiểm chăm sóc sức khỏe cao cấp, bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp\n- Được khám sức khỏe định kỳ 1 lần/1 năm\n- Tối thiểu 12 ngày nghỉ phép có lương mỗi năm cho tất cả nhân viên chính thức\n- Môi trường làm việc hiện đại với những đồng nghiệp trẻ trung, năng động & thân thiện và cà phê, trà, đồ uống miễn phí\n- Du lịch công ty hàng năm và tiệc cuối năm, team building hàng quý và ăn uống cùng nhau hàng tuần. Câu lạc bộ: chạy, bóng đá, game,...\n- Văn hóa phẳng, cởi mở và chia sẻ với đội ngũ quản lý thân thiện\n- Thời gian làm làm việc: 8h30 - 17h30 Thứ 2 - Thứ 6\nĐịa điểm làm việc\n- Hà Nội: Tòa Detech, số 8 Tôn Thất Thuyết, Nam Từ Liêm\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2339, 1187, 2, 'Senior Backend Developer', 'Mô tả công việc\n- Phát triển và duy trì các ứng dụng web fullstack, sử dụng Java hoặc Python cho backend.\n- Thiết kế, xây dựng và tích hợp RESTful API để giao tiếp giữa các dịch vụ.\n- Xây dựng giao diện người dùng tương tác tốt với các frontend framework như ReactJS, Angular hoặc VueJS.\n- Quản lý cơ sở dữ liệu quan hệ và/hoặc NoSQL như: MySQL, PostgreSQL, MongoDB, Redis.\n- Đóng gói ứng dụng bằng Docker để đảm bảo môi trường phát triển và triển khai nhất quán.\n- Thiết lập và giám sát hệ thống với các công cụ logging & alerting hiện đại.\n- Làm việc theo mô hình Agile/Scrum, sử dụng các công cụ quản lý như JIRA.\n- Phối hợp chặt chẽ với các team BA, QA, DevOps, khách hàng để đảm bảo chất lượng và tiến độ dự án.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành Công nghệ thông tin hoặc lĩnh vực liên quan.\n- Từ 5 năm kinh nghiệm kinh nghiệm lập trình, trong đó thời gian gần nhất có kinh nghiệm làm việc với Java, Python.\n- Có kinh nghiệm làm việc với Javascript\n- Có kiến thức vững với: RESTful API, microservices, authentication/authorization.\n- Kinh nghiệm làm việc với cơ sở dữ liệu quan hệ và/hoặc NoSQL.\n- Thành thạo Git, viết unit test, triển khai bằng CI/CD pipelines.\n- Kỹ năng giao tiếp và làm việc nhóm tốt.\n\nĐIỂM CỘNG / ƯU TIÊN\n- Có kinh nghiệm làm việc với dự án outsource, đặc biệt là khách hàng Hàn Quốc.\n- Chủ động, tinh thần trách nhiệm cao.\n- Ưu tiên ứng viên có khả năng giao tiếp tiếng Anh cơ bản trở lên.\n\nQuyền lợi\n1. Thu nhập hấp dẫn:\n- Tối thiểu 13 tháng lương/năm.\n- Đánh giá tăng lương 2 lần/năm.\n- Thưởng hiệu quả công việc hàng tháng, thưởng dự án, thưởng ngày lễ, thưởng Tết,…\n- Phụ cấp thâm niên tối thiểu 6tr/năm.\n- Trợ cấp thai sản cho nhân viên nữ ngoài bảo hiểm xã hội.\n\n2. Chăm sóc sức khỏe:\n- Khám sức khỏe định kỳ hằng năm tại các trung tâm y tế chất lượng cao.\n- Chương trình bảo hiểm sức khỏe toàn diện Rikkei Care.\n\n3. Phát triển sự nghiệp:\n- Tham gia các chương trình đào tạo được tổ chức thường xuyên bởi các chuyên gia trong và ngoài nước.\n- Công ty tài trợ chi phí thi các chứng chỉ quốc tế.\n- Thưởng thành tích khi đạt các chứng chỉ ngoại ngữ.\n- Cơ hội làm việc tại Nhật, Mỹ, Hàn và nhiều quốc gia khác trên thế giới,…\n\n4. Môi trường năng động, tích cực:\n- Thời gian làm việc linh động, nghỉ thứ 7 + chủ nhật hàng tuần.\n- 12 ngày phép/năm + 1 ngày nghỉ du lịch.\n- Chế độ team building hàng quý, du lịch hàng năm.\n- Tham gia các giải đấu thể thao indoor, outdoor, e-sport,…\n- Tham gia các Câu lạc bộ bóng đá, bóng bàn, cầu lông, bơi lội, âm nhạc, tiếng Anh,…\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Đăng ký linh hoạt 8:00 - 9:00 đến 17:00 - 18:00 từ Thứ 2 - Thứ 6.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2340, 756, 2, 'Junior Android Developer', 'Mô tả công việc\n- Phát triển ứng dụng, module ứng dụng Android theo phân phối của Team Leader.\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động theo phân phối của team leader.\n- Phối hợp với Mid Level/ Senior Developer thực hành code review.\n- Phối hợp với các team liên quan vận hành dự án theo quy trình.\n- Tham gia hướng dẫn, đào tạo member mới.\n- Được phép tự do nghiên cứu công nghệ mới, đề xuất ý tưởng đóng góp vào dự án.\n\nYêu cầu ứng viên\n- Có tối thiểu 1 năm kinh nghiệm Android (Java/Kotlin)\n- Nắm được khái niệm Android cơ bản (Activity/Service/View System, Resource, Storage, Thread Handling).\n- Có kinh nghiệm sử dụng Jetpack Component, Coroutine/Rx.\n- Đã từng sử dụng một trong các mô hình kiến trúc MVP, MVVM.\n- Hiểu biết Design Pattern là một lợi thế.\n- Có khả năng dựng module độc lập là một lợi thế.\n- Am hiểu Agile Scrum là một lợi thế.\n- Đam mê, chủ động công việc, có kỹ năng làm việc nhóm, làm việc độc lập.\n- Đam mê phát triển sản phẩm.\n- Có kỹ năng làm việc nhóm/ theo quy trình là một lợi thế.\n\nQuyền lợi\n- Mức lương 12.000.000 - 28.000.000 VNĐ.\n- Xét tăng lương 1 lần/năm. Lương tháng 13\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN.\n- Các gói bảo hiểm ngoài BHXH: Bảo hiểm PTI, khám sức khỏe định kỳ hàng năm.\n- Văn hóa làm việc GenZ,môi trường làm việc trẻ trung, sáng tạo, Dám nghĩ - dám làm, trà đá, bàn tròn, ném đá sếp, áp dụng triệt để văn hóa 6K startup, TSB3C.\n- Thực chiến cùng quản lý, chuyên gia từ các tập đoàn lớn: Topica, VNG, Samsung,...\n- Du lịch hàng năm, team building, tea break hàng tuần.\n\nĐịa điểm làm việc\n- Đà Nẵng: Hải Châu.\n\nThời gian làm việc\n- 8:00 - 17:30, nghỉ trưa 1h30’, làm việc từ T2-T6.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2341, 1164, 2, 'Full-Stack Java Developer', 'Mô tả công việc\n- Translate application user stories into functional applications\n- Design, build, and maintain efficient, reusable, and reliable Java code\n- Ensure the best possible performance, quality, and responsiveness of the applications\n- Identify bottlenecks and bugs, and devise solutions to these problems\n- Maintain code quality, organization, and automatization\n- Write and maintain high-quality unit tests\n- Perform code review Adhere to the acceptance criteria and the Definition of Done\n\nYêu cầu ứng viên\n- Have at least 5 years of experience in a Java Developer.\n- Proficient in Java/JEE and Spring framework, with a good knowledge of its ecosystems\n- Strong understanding of object-oriented programming\n- Familiar with various design and architectural patterns\n- Skill for writing reusable Java libraries\n- Knowledge of concurrency patterns in Java\n- Familiarity with concepts of MVC, JDBC, and RESTful\n- Proficiency with SQL, Hibernate, JPA\n- Experience with both external and embedded databases\n- Understanding fundamental design principles behind a scalable application\n- Creating database schemas that represent and support business processes\n- Implementing automated testing platforms and unit tests\n- Proficient understanding of code versioning tools, such as Git\n- Ability to clearly communicate with both technical and non-technical team members\n\nOther Requirements:\n- Experience with Agile Scrum\n- Experience with Ember or other JavaScript\n- Familiarity with build tools such as Ant, Maven, and Gradle\n\nQuyền lợi\n- The attractive salary (Negotiation)\n- 2-month probation period with 100% salary.\n- Full salary insurance coverage after the probation period.\n- Participation in the PVI health insurance package and annual health check-ups.\n- 13th-month salary, birthday bonus, New Year bonus, Mid-Autumn Festival gifts, March 8th and October 20th gifts, etc.\n- Performance evaluation and regular salary increases.\n- Welfare for personal events, childbirth, and other benefits as per labor regulations and company welfare policies.\n- Dynamic and youthful work environment conducive to personal growth and development\n\nĐịa điểm làm việc\n- Hà Nội: 27th Floor, East Tower, Lotte Center Hanoi, 54 Lieu Giai, Ba Đình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Flexible working hours may apply depending on project (e.g., 1:00 PM – 9:00 PM)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2342, 1146, 2, 'Thực Tập Sinh Back-End / Intern Back-End (.NET)', 'Mô tả công việc:\n- Lập trình các chức năng được giao theo tài liệu giải pháp chi tiết.\n- Tham gia phát triển các dự án về web, xây dựng các chức năng frontend của website, web application.\n- Thực hiện thiết kế, coding, testing các module\n- Tùy chỉnh và nâng cấp hệ thống đáp ứng yêu cầu của khách hàng.\n- Tham gia phát triển các module backend của ứng dụng.\n- Nghiên cứu, tìm hiểu các công nghệ mới để áp dụng cải thiện sản phẩm.\n\nYêu cầu ứng viên:\n- Đang là sinh viên năm cuối hoặc đã tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán tin... hoặc chuyên ngành khác có liên quan\n- Kiến thức tốt về HTML, CSS, JavaScript là một lợi thế\n- Kiến thức tốt về HTML/CSS, AJAX và các thư viện / framework liên quan\n- Có kinh nghiệm làm việc với RESTful API\n- Có tư duy logic - thuật toán tốt, yêu thích công việc lập trình\n- Có thái độ cầu tiến, khả năng học hỏi, chủ động, trách nhiệm trong công việc\n- Tinh thần làm việc theo đội nhóm tốt\n- Có máy tính cá nhân.\n\nQuyền lợi:\n- Cơ hội nhận mức hỗ trợ thực tập 3.000.000 VND/tháng từ tháng thứ 2\n- Được đào tạo phát triển bản thân, nâng cao các kỹ năng và chuyên môn nghề nghiệp\n- Làm việc tại môi trường chuyên nghiệp, năng động, trẻ trung và trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc\n- Được tham gia các lớp đào tạo, khóa học về chuyên môn, kỹ năng\n- Cơ hội tiếp cận với những doanh nghiệp, dự án lớn, những xu hướng công nghệ/nền tảng mới nhất, thỏa sức sáng tạo phát triển bản thân\n- Sau 1-2 tháng thực tập sẽ có đánh giá kết quả của Leader và được xem xét nâng lên thử việc và ký hợp đồng lao động.\n- Tham gia các chuyến du lịch, teambuilding.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2343, 1242, 2, 'Back End Python Developer (Python, AWS)', 'LG CNS is a leading IT service provider, delivering innovative solutions in AI, cloud computing, big data, and smart factory automation. Our Vietnam Build Center is expanding, and we are looking for talented Python Developers to join our growing team. Develop, optimize, and maintain scalable Python applications. Collaborate with cross-functional teams to design, develop, and deploy software solutions. Write clean, efficient, and well-documented code following best practices. Debug and troubleshoot issues to ensure application stability and performance. Work with databases, APIs, and third-party libraries to build robust applications. Participate in code reviews, design discussions, and Agile development processes.\n\n[Required]\n3+ years of experience in Python development.\nBachelor\'s degree\nProficiency in Python frameworks such as Fast API\nExperience in working with ORM such as SlqAlchemy, JPA\nExperience working with DB Configuration Management such as Alembic, Flyway\nExperience in debugging in Kubernetes, Docker/Container, Cloud (AWS) environment\nExperience in AWS Cognito/AWS S3/AWS SES/AWS Lambda\nStrong problem-solving and analytical skills.\nGood communication skills and the ability to work in a team environment.\n\n[Preferred]\nExperience with Resource optimization\nExperience in solving complex problems with Application and Cloud resource\nExperience in Digital Marketing domain\n\nAttractive salary and bonus will be discussed after going through CV & Interview\nTopik allowance\nReview capacity annually and adjust salary increases according to work performance.\nHealth care: Premium health insurance, Annual health check-up\nYoung working environment\nGood career development opportunities with interesting and challenging projects.\nEnglish, Korean, technical, soft skills training courses.\nOpportunity to learn special courses from LG CNS, new technology and security.\nGifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\nOutdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\nWorking hours: 8 hours from Monday - Friday (8 hours/day)\n\n- Hà Nội: Tầng 15, Keangnam Landmark 72, Nam Từ Liêm\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2344, 165, 2, 'Frontend Developer', 'Về KiotViet:\nSản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ.\nVới hơn 13 năm và trên 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm.\n\nBạn sẽ làm gì\n- Phát triển và bảo trì ứng dụng web sử dụng framework Angular;\n- Tạo các single-page application interactive và hiệu suất cao;\n- Implement logic ứng dụng theo system specifications;\n- Tích hợp RESTful API services với ứng dụng frontend;\n- Debug và fix các vấn đề để đảm bảo performance tối ưu của ứng dụng;\n- Optimize ứng dụng để đạt tốc độ và tính năng tối đa;\n- Cộng tác với các thành viên team để định nghĩa, thiết kế và triển khai tính năng mới;\n- Tham gia code reviews và duy trì code quality;\n- Cập nhật kiến thức về những phát triển mới nhất của Angular và best practices;\n- Viết documentation cho code và quy trình phát triển.\n\nYêu cầu ứng viên\n1. Học vấn và kinh nghiệm\n- Tốt nghiệp đại học chuyên ngành Khoa học Máy tính, CNTT hoặc các ngành liên quan;\n- Tối thiểu 4 năm kinh nghiệm phát triển ứng dụng web với Angular.\n\n2. Yêu cầu kỹ thuật\n- Thành thạo Angular (version 9+) và TypeScript;\n- Hiểu biết sâu về RxJS và các pattern lập trình bất đồng bộ;\n- Kinh nghiệm với Angular Material hoặc các thư viện UI component khác;\n- Hiểu biết về các giải pháp state management (NgRx, NGXS, Akita)\n- Kiến thức cơ bản về HTML và CSS cho phát triển component;\n- Hiểu biết về RESTful APIs và kinh nghiệm tích hợp với backend services;\n- Có kinh nghiệm hoặc hiểu biết về các công nghệ storage ở local như LocalStorage, IndexedDB, SQLite, WebDB;\n- Có kinh nghiệm hoặc hiểu biết về PWA / Offline First Application;\n- Có kinh nghiệm hoặc hiểu biết về Web worker, Service worker;\n- Có kinh nghiệm hoặc biết về các công cụ phát triển desktop app cross-platform như Electron;\n- Kinh nghiệm với unit testing sử dụng Jasmine, Karma hoặc Jest;\n- Thành thạo với Angular CLI và các build tools;\n- Hiểu biết về software architectures cho ứng dụng frontend;\n- Kinh nghiệm với hệ thống version control (Git) và quy trình phát triển collaborative;\n- Kiến thức về kỹ thuật tối ưu hóa performance ứng dụng web;\n- Kinh nghiệm với công cụ và quy trình CI/CD là một lợi thế;\n- Có kinh nghiệm sử dụng AI coding tools và assistants (Cursor, GitHub Copilot, Claude, v.v.) để nâng cao productivity trong phát triển là một lợi thế.\n\n3. Kỹ năng mềm\n- Khả năng problem-solving mạnh mẽ và chú ý đến chi tiết;\n- Kỹ năng giao tiếp tốt và khả năng giải thích các khái niệm kỹ thuật;\n- Là team player với kinh nghiệm làm việc trong môi trường collaborative;\n- Khả năng quản lý time hiệu quả và đáp ứng deadlines;\n- Tính thích ứng và sẵn sàng học hỏi công nghệ mới;\n- Self-motivated với khả năng làm việc độc lập khi cần thiết.\n\nQuyền lợi\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả làm việc lên đến 2 tháng lương;\n- Làm việc từ Thứ 2 – Thứ 6, giờ làm việc linh hoạt;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...);\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\n- Chăm sóc sức khỏe : Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\n- Làm việc trong môi trường trẻ trung, năng động;\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc\nThứ 2 - Sáng thứ 7: 8h00-17h30 hoặc 9h00-18h30, giờ làm việc linh hoạt đủ 8h/ngày.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2345, 1243, 2, 'Middle Fullstack Developer', 'Mô tả công việc:\n- Phát triển và bảo trì các ứng dụng web sử dụng PHP (ưu tiên Laravel).\n- Thiết kế và xây dựng APIs, tích hợp frontend-backend.\n- Viết code sạch, có thể mở rộng và dễ bảo trì.\n- Tham gia code review, kiểm thử, triển khai và cải tiến hiệu năng hệ thống.\n- Làm việc cùng team để phân tích yêu cầu và đưa ra giải pháp kỹ thuật phù hợp.\n- (Nếu có thể) hỗ trợ xử lý các module sử dụng Ruby on Rails/Java/.Net.\n\nYêu cầu ứng viên:\n- Tối thiểu 4 năm kinh nghiệm phát triển web ở vị trí Fullstack.\n- Thành thạo PHP, đặc biệt là các framework phổ biến như Laravel.\n- Có kinh nghiệm với HTML, CSS, JavaScript (ưu tiên có kinh nghiệm với Vue.js hoặc React).\n- Biết sử dụng MySQL, PostgreSQL hoặc các hệ quản trị cơ sở dữ liệu tương tự.\n- Đã làm việc với Ruby on Rails/Java/.Net là một lợi thế.\n- Có kinh nghiệm sử dụng Git, làm việc nhóm theo mô hình Agile/Scrum.\n- Có tinh thần học hỏi, chủ động và khả năng làm việc độc lập tốt.\n- Có kinh nghiệm tận dụng các tools AI hỗ trợ công việc.\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh.\n\nƯu tiên thêm nếu có:\n- Đã làm việc với Docker, CI/CD, hoặc các dịch vụ cloud (AWS, GCP…).\n- Biết tiếng Nhật là một điểm cộng.\n\nQuyền lợi:\n- Up to 15 tháng lương/năm khi tham gia dự án.\n- Hỗ trợ cơm ca 500,000/tháng cho nhân viên chính thức.\n- Thưởng thâm niên cho nhân viên có từ 03 năm và 06 năm làm việc liên tục tại Rikai.\n- Chế độ thưởng lễ, Tết, sinh nhật, báo hỷ... cho từng cá nhân.\n- Bảo hiểm sức khoẻ cao cấp cho nhân viên chính thức làm việc từ 06 tháng.\n- Chính sách rèn luyện thể thao cho CBNV.\n- Team building theo quý - Company trip mỗi năm.\n- Happy Hour mỗi tháng với nhiều phần quà hấp dẫn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2346, 1244, 2, 'Bridge Software Engineer', 'Mô tả công việc:\n- Hiểu và truyền đạt chính xác các yêu cầu, đặc tả của dự án cho team\n- Họp, thảo luận với khách hàng trực tiếp hoặc thông qua call/chat/email\n- Quản lý dự án/team để đảm bảo dự án release đúng tiến độ\n- Kiểm tra (test) dự án để đảm bảo chất lượng trước khi release\n- Chi tiết công việc sẽ được thảo luận khi phỏng vấn\n\nYêu cầu ứng viên:\n- Tốt nghiệp các trường đại học chuyên ngành CNTT/Toán Tin\n- Ít nhất 1 năm kinh nghiệm phát triển các hệ thống web dùng PHP\n- Có kinh nghiệm và am hiểu về các giai đoạn phát triển phần mềm (từ khâu nhận yêu cầu)\n- Ít nhất 1 năm kinh nghiệm làm BrSE cho các dự án phần mềm với khách hàng Nhật\n- Tiếng Nhật giao tiếp lưu loát, từ N2 trở lên; từng du học hoặc làm làm việc tại Nhật\n- Có kỹ năng tự tìm hiểu kỹ thuật, công nghệ mới\n- Yêu thích văn hoá Nhật Bản và có mong muốn làm việc lâu dài tại Nhật Bản\n- Làm việc cẩn thận với tinh thần trách nhiệm cao\n\nQuyền lợi:\n- Môi trường làm việc năng động, thân thiện\n- Được trang bị máy Macbook Pro và màn hình LCD\n- Lương tháng 13, du lịch công ty hàng năm, khám sức khỏe định kỳ và các hoạt động thể thao\n- Thử việc 100% lương\n- Phụ cấp tiền gửi xe, sinh nhật...\n- Ghi chú: Bộ phận HR chỉ liên lạc những CV đạt yêu cầu để mời phỏng vấn\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 103A-105-107 Nguyễn Thông, Phường 9, Quận 3\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2347, 1245, 2, 'Nhân Viên Kỹ Thuật Điện', '- Lập trình PLC, HMI\n- Thiết kế và lắp đặt tủ điện\n- Ưu tiên biết Sửa chưa mạch điện tử, biết về máy CNC, máy In Công nghiệp\n- Kiểm tra phát hiện hỏng hóc của máy và thiết bị công nghiệp tại cơ sở, nhà máy của khách hàng.\n- Nghiệm thu, chạy thử thiết bị sau sửa chữa theo sự phân công. \n- Bảo hành – bảo trì và chăm sóc khách hàng về các vấn đề kỹ thuật\n- Thực hiện các công việc khác theo sự phân công, hướng dẫn của cấp trên\n\n- Cần cù, chịu khó, tính kỷ luật tốt và có chí cầu tiến.\n- Tốt nghiệp trung cấp, cao đẳng, đại học về chuyên ngành điện là một lợi thế.\n- Có kinh nghiệm về lập trình PCL - HMI, servo, lắp đặt tủ điện công nghiệp\n- Thái độ hơn trình độ, luôn nỗ lực trong công việc.\n- Độ tuổi: 24-38 tuổi\n\n- Mức lương: 10.000.000-30.000.000 VNĐ \n- Được đào tạo kỹ năng về công việc.\n- Thưởng vào dịp Lễ, Tết.\n- Được hưởng các chế độ theo đúng quy định của pháp luật hiện hành: BHXH, BHYT, BHTN...và các chế độ đãi ngộ khác của Công ty.\n- Môi trường làm việc năng động, sáng tạo.\n\n- Hải Dương: 207 Nguyễn Lương Bằng, TP Hải Dương\n\nThời gian làm việc: Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2348, 1246, 2, 'Python Developer', 'The project improves and optimizes data processing performance.\n- Develop and implement new features and functionalities within the existing system.\n- Collaborate effectively with cross-functional teams to ensure successful project delivery\n- Troubleshoot and debug issues related to application performance and functionality.\n\nYêu cầu ứng viên\n- University degree in IT, Computer Science, or related experiences.\n- Good understanding of SQL, Oracle DB and Python.\n- As a fast and eager learner, you enjoy digging into new technologies.\n- Good communication skill\n- Having self-management mindset\n- Having ability to work independently\n\nQuyền lợi\n- Salary negotiable\n- 100% salary during 2-month probation\n- Full-salary insurance starting right from probation period\n- 3 times bonus per year\n- 5 working days per week with flexible check-in\n- Health check once per year\n- Health care insurance package\n- Attractive training budget for each employee per year for personal training & Premium Udemy\n- Online Learning Account\n- Oversea training opportunities\n- Numerous internal activities: team bonding, team training,...\n- Gifts for each employee on 30/4,1/5; 2/9....(in cash)\n- Bonus for employee having Korean certificates or Software Test certificate\n\nĐịa điểm làm việc\n- Hà Nội: Tòa PVI, Số 1 Phạm Văn Bạch, Yên Hòa, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Monday-Friday with flexible check-in time\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2349, 1247, 2, 'Chuyên Viên Phát Triển Phần Mềm', '• Tham gia phát triển lập trình phần mềm ứng dụng mới theo yêu cầu nghiệp vụ\n• Tham gia nghiên cứu, đánh giá, và áp dụng các giải pháp công nghệ mới\n• Bảo trì, nâng cấp, cập nhật, sửa lỗi các hệ thống phần mềm ứng dụng hiện có\n\nJob description:\n• Participate in the development of new system applications, based on business requirements\n• Participate in research, evaluation, and application of new technology solutions\n• Maintain, upgrade, update, fix errors of existing application systems and software\n\n• Sử dụng thành thạo ngôn ngữ lập trình: Java, Python\n• Lập trình thành thạo với hệ CSDL: MySQL, Oracle (Oracle là lợi thế)\n• Thành thạo HTML, CSS, Bootstrap, Javascript, Jquery\n• Kinh nghiệm sử dụng GIT như GitHub/GitLab, Docker container là một lợi thế\n• Tốt nghiệp đại học trở lên, ưu tiên ứng viên tốt nghiệp chuyên ngành Công nghệ thông tin\n• Thành thạo tiếng Anh giao tiếp, đọc viết tốt\n• Có tối thiểu 2 năm kinh nghiệm đảm nhiệm vị trí Chuyên viên Phát triển phần mềm\n• Có kĩ năng giao tiếp tốt, chủ động, chăm chỉ và cầu tiến trong công việc\n• Có kĩ năng làm việc theo nhóm\n• Có kĩ năng tư duy logic, xử lý tình huống nhanh, hiệu quả\n• Có kĩ năng phân tích và đánh giá yêu cầu\n\nBenefits:\n• Receive attractive income & benefits, competitive in the market\n• Enjoy social insurance, health insurance, health insurance according to the Company\'s regulations\n• Enjoy annual leave, public holidays in accordance with the law\n• Enjoy lunch allowance\n• Participate in annual vacation, travel, teambuilding, sports tournaments, and cultural activities\n• Work in a professional, dynamic and effective environment\n• Participate in regular professional training courses to help improve technical expertise and personal skills\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 10&11 tòa Discovery Complex, 302 Cầu Giấy, P. Dịch Vọng, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2350, 1248, 2, 'Business Analyst', 'Mô tả công việc\n+ Hỗ trợ KH sử dụng phần mềm\n+ Trao đổi với KH để làm rõ nhu cầu về tính năng của phần mềm \n+ Chuẩn bị tài liệu đặc tả tính năng, flowchart, mockup để làm việc với team kỹ thuật\n+ Nghiên cứu thị trường, nhu cầu KH \n+ Làm việc nhóm cùng các phòng ban khác và một số công việc cụ thể được giao\n\nYêu cầu ứng viên\n+ Ưu tiên ứng viên ngành Kinh tế, Công nghệ thông tin;\n+ Giao tiếp tiếng anh tốt;\n+ Ham học hỏi, chăm chỉ, có đam mê với ngành công nghệ, thương mại điện tử.\n\nQuyền lợi\n- Các chế độ BHXH, BHYT đầy đủ theo quy định của luật lao động.\n- Lương thưởng theo năng lực của mỗi cá nhân (mức lương có thể deal thêm khi tham gia phỏng vấn), tháng lương thứ 13.\n- Phụ cấp ăn trưa và phí gửi xe.\n- Được hưởng nhiều chế độ đãi ngộ khác theo chính sách của Công ty.\n- Tham gia các sự kiện, workshop của công ty, chế độ du lịch hàng năm, sinh nhật hàng tháng.\n- Môi trường làm việc trẻ, thân thiện, chuyên nghiệp.\n- Được cung cấp máy tính làm việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2351, 1249, 2, 'Senior .NET Developer (AI)', 'Mô tả công việc:\n- Design, develop, and maintain APIs using .NET Core and C# within a microservices architecture to support logistics, warehouse, and inventory processes.\n- Work with PostgreSQL databases and write efficient SQL queries \n- Set up and optimize CI/CD pipelines to automate application deployment.\n- Use Docker to package, deploy, and manage applications in containerized environments.\n- Occasionally contribute to user interface (UI) development using frontend technologies (as needed).\n- Optimize backend system performance, ensuring stability and scalability.\n- Collaborate with the team to analyze requirements, design solutions, and implement new features.\n- Ensure code quality through testing, code reviews, and adherence to coding standards.\n\nYêu cầu ứng viên:\n- At least 3-4 years of experience in developing applications using .NET Core and C#.\n- Proficient in SQL and experienced with PostgreSQL or other relational databases\n- Integrate AI models and APIs into existing systems to enhance functionality.\n- Stay updated on emerging technologies, particularly in AI and software development\n- Preferred Qualifications: Experience with AI-driven development tools\n- Knowledge of microservices architecture and designing distributed systems.\n- Experience with CI/CD tools (e.g., GitLab CI, Jenkins) and automated deployment processes.\n- Proficient in using Docker for packaging and deploying applications.\n- Familiarity with RESTful API architecture, design, and implementation.\n- Experience with Golang is a plus.\n- Basic understanding of frontend development (HTML, CSS, JavaScript).\n- Strong problem-solving skills, with the ability to work independently and collaborate effectively in a team.\n- Experience in logistics, warehouse, or inventory management domains is a plus.\n- Logical thinking, attention to detail, and a strong sense of responsibility for work quality.\n\nQuyền lợi:\n- Competitive salary and benefits\n- Attractive 13th month salary and performance bonus\n- Annual performance review for salary raise and promotion\n- Premium private insurance (PTI Insurance) with discount for family members\n- Annual health check\n- 12 days of annual leave\n- Company trips and team buildings\n- Gifts on special occasion: individual/company birthday, Tet and Holidays\n- Internal activities, sport and social clubs\n- Opportunity to train both technical and soft skills to develop your career path.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 02nd Floor, FPT Tan Thuan 2, Tan Thuan Processing Zone - No. 8, Tan Thuan Dong, District 7, Quận 7.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2352, 1250, 2, 'Technical Leader', 'Mô tả công việc:\n- Lead & Build: Develop and mentor a high-performing engineering team, driving talent growth and performance excellence.\n- Design & Architect: Create robust, scalable, and secure systems to support business expansion.\n- Ensure Code Excellence: Enforce best practices, conduct thorough code reviews, and optimize system performance.\n- Innovate & Optimize: Continuously enhance system reliability, automation, and scalability.\n- Collaborate & Align: Partner with cross-functional teams to build impactful solutions.\n- Monitor & Maintain: Oversee system health, troubleshoot critical issues, and ensure seamless operations.\n\nYêu cầu ứng viên:\n- Technical Expertise:\n  * 6+ years of experience in software development, with at least 2+ years as a Tech Lead.\n  * Strong experience in Frontend (React, Vue, Angular) & Backend (Node.js, Java, Python, Go).\n  * Deep knowledge of cloud infrastructure (AWS/GCP), DevOps, CI/CD, and microservices.\n  * Experience with high-traffic systems, real-time processing, and database optimization (PostgreSQL, MongoDB, Redis).\n- Leadership & Problem-Solving:\n  * Strong critical thinking & analytical skills to tackle complex technical challenges.\n  * Passion for mentorship & team development.\n- Business Mindset:\n  * Ability to align tech solutions with business goals and drive impact.\n  * Understanding of product lifecycle & agile methodologies.\n\nQuyền lợi:\n- Attractive compensation package\n- Monthly bonus (up to 2 months bonus/year in total)\n- 100% salary on your probation period\n- 13th-month salary\n- Performance review conducted 2 times/ year\n- Hybrid working model (flexibility between home & office)\n- Personal branding & industry exposure: Contribute to Vexere’s tech blog, publish posts on Medium, and participate in open-source projects & tech talks.\n- Attractive stock option for hard-core developers/leads\n- Exclusive Vexere travel benefits: Up to 30% discount for you & your family on bus tickets.\n- Annual leave: 12 days + additional leave every 3 years (can be converted to salary).\n- Vibrant and dynamic working environment with a friendly and supportive team, ready to share knowledge and assist each other.\n- Company trips, team-building events, year-end parties, and training programs.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 384 Hoàng Diệu, Quận 4\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Thứ 7 (từ 09:00 đến 12:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2353, 1251, 2, 'Trưởng Nhóm Kinh Doanh & Phát Triển Phần Mềm', 'Mô tả công việc:\n- Xây dựng và triển khai chiến lược, mô hình kinh doanh cho từng sản phẩm Số của Công ty.\n- Phân tích thị trường và nhu cầu khách hàng và để kịp thời đề xuất các cơ hội hợp tác.\n- Quản lý vòng đời sản phẩm: từ ý tưởng, xây dựng, thử nghiệm, ra mắt và cải tiến.\n- Làm việc với team sản phẩm để đề xuất, định hướng phát triển hoặc cải thiện các sản phẩm của Cty trên cơ sở hiểu biết insight khách hàng và thị trường.\n- Phối hợp với team marketing/ dự án để lên ý tưởng và thực thi các chương trình nhằm thu hút khách hàng.\n- Xây dựng mối quan hệ với đối tác, khách hàng chiến lược. Là cầu nối giữa khách hàng và team nội bộ sao cho thông tin được thông suốt.\n- Cùng với team Dự án, nghiên cứu hiệu quả của sản phẩm/dịch vụ để kịp thời điều chỉnh, cải tiến cho phù hợp.\n- Quản lý, đào tạo và phát triển đội ngũ kinh doanh, đảm bảo đạt KPI và mục tiêu đã đề ra.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Kinh doanh, Quản trị, Công nghệ thông tin hoặc các ngành liên quan.\n- Tối thiểu 3 năm kinh nghiệm ở vị trí quản lý kinh doanh hoặc phát triển sản phẩm, ưu tiên trong lĩnh vực công nghệ.\n- Hiểu biết sâu về mô hình kinh doanh SaaS, sản phẩm số, nhà mạng hoặc phần mềm là một lợi thế.\n- Kỹ năng phân tích thị trường, xây dựng chiến lược và quản lý dự án tốt.\n- Có khả năng làm việc đa nhiệm và phối hợp liên phòng ban hiệu quả.\n- Kỹ năng lãnh đạo, giao tiếp và đàm phán tốt.\n- Tư duy sáng tạo, nhạy bén với xu hướng công nghệ và hành vi người dùng.\n\nThu nhập:\n- Thu nhập khi đạt 100% KPI: 21 - 23 triệu VND.\n- Thu nhập tính theo tỷ lệ đạt KPI.\n- Lương cứng phụ thuộc vào doanh số.\n\nQuyền lợi:\n- Được tiếp cận với các công nghệ tiên phong trong lĩnh vực CNTT. Được tiếp làm việc với nhiều đối tác lớn trong nước và quốc tế.\n- Thu nhập: Lương từ 21.000.000 - 23.000.000 VND/tháng + KPI.\n- Thưởng tối thiểu tháng lương thứ 13.\n- BHXH, BHYT, BHTN theo pháp luật hiện hành.\n- Môi trường làm việc trẻ trung, năng động, phát huy khả năng sáng tạo và lợi thế của bản thân.\n- Đội ngũ nhân viên trẻ, năng động, đầy nhiệt huyết, sẵn sàng hỗ trợ nhau trong công việc.\n- Làm việc từ 8:30 đến 17:30, từ thứ 2 – thứ 6.\n\nĐịa điểm làm việc:\n- Hà Nội: 96 Hoàng Ngân, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2354, 1252, 2, 'Nhân Viên Kỹ Thuật Cơ Khí', '- Nhận bản vẽ, lập chương trình trên máy CNC (máy tiện, máy phay), lên gá, gia công, kiểm tra kích thước.\n- Kiểm tra các chương trình, chạy thử nghiệm trước khi chạy chính thức trên máy và tiến hành gia công các sản phẩm\n- Thực hiện việc thay đổi các dụng cụ cắt gọt dùng trong gia công cơ khí chính xác\n- Thực hiện những công việc khác do lãnh đạo sắp xếp.\n\nYêu cầu ứng viên:\n- Tốt nghiệp trung cấp chuyên ngành cơ khí.\n- Có kinh nghiệm 3 năm trở lên.\n- Có khả năng làm việc độc lập.\n- Đọc hiểu bản vẽ cơ khí.\n\nQuyền lợi:\n- Mức lương: tùy theo năng lực của ứng viên\n- Xét nâng lương định kỳ theo thâm niên.\n- Thưởng trung thu.\n- Thưởng doanh số (nếu đạt doanh thu).\n- Thưởng tháng 13 theo tổng lương (không bao gồm tiền chuyên cần, giao thông, nhà ở).\n- Trợ cấp hiếu hỷ từ 600,000 đến 900,000 đồng.\n- Phép năm từ 12 đến 14 ngày/năm (tùy bộ phận)\n- Tham gia BHXH, BHYT, BHTN theo tổng lương (không bao gồm tiền chuyên cần, giao thông, nhà ở).\n\nĐịa điểm làm việc:\n- Đồng Nai: KCN Nhơn Trạch 3, Nhơn Trạch\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2355, 1146, 2, 'Junior Back-End (.Net) - Lĩnh Vực Edtech - Mức Lương Up To 15M', 'Mô tả công việc:\n- Tham gia phát triển hệ thống học trực tuyến trên nền tảng .NET (.NET Framework, .NET Core) phục vụ hàng trăm nghìn người dùng.\n- Xây dựng API và xử lý nghiệp vụ phía server, đảm bảo hiệu năng và độ ổn định cao.\n- Tối ưu hệ thống để đáp ứng nhu cầu sử dụng đồng thời lớn, cải thiện tốc độ và khả năng mở rộng.\n- Phối hợp với team BA, Front-end và QA để phân tích yêu cầu, thiết kế giải pháp và triển khai tính năng mới.\n- Nghiên cứu – ứng dụng công nghệ mới, hỗ trợ phân tích dữ liệu người dùng, áp dụng Big Data, caching, tối ưu cơ sở dữ liệu...\n- Tham gia quy trình Agile/Scrum, đóng góp ý tưởng cải tiến liên tục sản phẩm và quy trình làm việc.\n\nYêu cầu ứng viên:\n- Có ít nhất 1 năm kinh nghiệm trong các dự án .NET.\n- Có kinh nghiệm công nghệ dữ liệu nâng cao của Microsoft: ADO.NET, .NET Core, ASP.NET (Core), MVC, Entity Framework (Core), Linq, SQL Server.\n- Có khả năng triển khai & tối ưu hóa các công nghệ .NET Server-side thành thạo.\n- Có kinh nghiệm thiết kế các API RESTful với ASP.NET.\n- Rất tốt trong việc hiểu và áp dụng các Mẫu thiết kế / Nguyên tắc thiết kế.\n- Thành thạo trong việc duyệt mã, tái cấu trúc mã.\n- Có kiến ​​thức cơ bản về HTML, CSS, JavaScript là một lợi thế.\n- Có kinh nghiệm làm việc trong môi trường Phát triển phần mềm Agile / Scrums.\n\nQuyền lợi:\n- Mức lương (gross): up to 15 triệu/tháng.\n- Thưởng sinh nhật, thưởng các dịp Lễ, Tết trong năm.\n- Chế độ BHXH, BHYT, BHTN đầy đủ ngay sau khi ký HĐ chính thức.\n- Khám sức khoẻ định kỳ hàng năm.\n- Trang bị máy tính hiện đại phục vụ công việc.\n- Quỹ Team Building lên tới 2.400.000 VNĐ/người/năm.\n- Du lịch nghỉ dưỡng hàng năm.\n- Trà chiều với bánh, hoa quả và đồ ăn vặt miễn phí hàng tuần.\n- Cơ hội tiếp cận với các doanh nghiệp, dự án lớn, xu hướng công nghệ và nền tảng mới nhất.\n- Được tham gia các lớp đào tạo, khóa học chuyên môn để phát triển kỹ năng.\n- Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung & trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc.\n- Học tiếng Anh hoàn toàn miễn phí & ưu đãi học phí cho người thân.\n\nĐịa điểm làm việc:\n- Hà Nội: 35 Lạc Trung, Hai Bà Trưng.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:20).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2356, 1253, 2, 'IOS Developer', 'Tham gia phát triển tính năng, bảo trì và tối ưu hiệu suất ứng dụng mobile trên nền tảng iOS và React Native.\nPhối hợp với team UI/UX, PO, Backend,... triển khai chức năng đảm bảo các yêu cầu về chất lượng, tiến độ dự án.\nXây dựng code clean, tối ưu và có khả năng mở rộng.\nHỗ trợ phát hiện và khắc phục lỗi trong quá trình vận hành ứng dụng.\n\nYêu cầu ứng viên:\nCó ít nhất 2-3 năm kinh nghiệm lập trình với iOS với Swift & React Native, mô hình MVVM.\nCó kinh nghiệm hoặc có định hướng lập trình với React native.\nCó kinh nghiệm xây dựng các ứng dụng sử dụng client server và sử dụng RESTFUL API.\nCó kinh nghiệm làm việc với multi-module project, mô hình Clean Architecture là một lợi thế.\nCó kinh nghiệm làm việc với command-line tools, viết bash scripting, xây dựng quy trình CI/CD là một lợi thế.\nCó kinh nghiệm làm việc với các dự án Product về Thương mại điện tử, có khả năng phát triển tính năng, tối ưu hệ thống, thiết kế cấu trúc hệ thống là 1 lợi thế.\nCó khả năng sử dụng công cụ quản lý mã nguồn Git và một trong các công cụ quản lý công việc Jira/Trello.\nCó khả năng làm việc động lập tự sắp xếp và quản lý công việc.\n\nQuyền lợi:\nLương/thưởng hấp dẫn theo quy định của công ty.\nXét tăng lương định kỳ hàng năm.\nMôi trường làm việc trẻ trung, sáng tạo.\nChế độ BHXH, BHYT theo luật Lao động, ngoài ra được tham gia chương trình bảo hiểm Sapo Care.\nĐược tham gia các khoá đào tạo từ các chuyên gia hàng đầu về thương mại điện tử, marketing online, phần mềm.\n\nĐịa điểm làm việc:\nHà Nội: Tòa Ladeco 266 Đội Cấn, Ba Đình.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2357, 1254, 2, 'Senior Java Developer', 'Với sự tham gia của AI vào việc phát triển phần mềm, công việc của developer sẽ thay đổi rất nhanh trong thời gian ngắn tới đây. Developer không còn phát triển các tính năng theo yêu cầu khách hàng nữa, mà phải có khả năng thiết kế các giải pháp, ứng dụng AI/công cụ và các dịch vụ khác (như DevOps, ITSM, Cloud,…) để deliver được giá trị cho khách hàng.\nĐi cùng với xu hướng này, BiPlus tìm kiếm các thành viên hiểu được sự thay đổi này và mong muốn học hỏi để dẫn dắt và nắm bắt các cơ hội mới.\n\nYêu cầu cụ thể:\n- Tham gia phân tích yêu cầu khách hàng, xây dựng và tư vấn giải pháp cho khách hàng\n- Triển khai các giải pháp, bao gồm việc phát triển (coding) và triển khai các dịch vụ khác đáp ứng nhu cầu khách hàng.\n- Tham gia các hoạt động chia sẻ tri thức và cải tiến liên tục.\n\nYêu cầu ứng viên:\n- Bạn là developer có từ 4 năm kinh nghiệm lập trình với ngôn ngữ Java.\n- Tiếng Anh giao tiếp thành thạo, tự tin làm việc với cộng sự nước ngoài.\n- Có chứng chỉ hoặc được đào tạo về AI, Cloud, Data, DevOps.\n- Thành thạo các công cụ trong quản lý phát triển phần mềm (Jira, Git,…)\n- Có kinh nghiệm và khả năng thiết kế giải pháp.\n- Có khả năng ứng dụng AI hiệu qủa trong công việc.\n- Có kinh nghiệm về triển khai các dịch vụ về DevOps, ITSM,… là một lợi thế\n- Hiểu biết về Agile/Scrum.\n- Có động lực học và kỹ năng tự học tốt, yêu thích và sẵn sàng học hỏi cái mới.\n- Sẵn sàng làm các mảng công việc mới như tư vấn, triển khai các dịch vụ cho khách hàng thay vì tập trung vào coding.\n\nQuyền lợi:\n- Mức lương khởi điểm: 35 – 50 triệu.\n- Thưởng quý, thưởng cuối năm (1-3 tháng lương).\n- Ngày phép hàng năm, ngày phép thâm niên, ngày phép tháng sinh nhật.\n- Đánh giá năng suất và xét tăng lương 1 lần/năm.\n- Tài trợ 100% phí thi các chứng chỉ quốc tế; phụ cấp chứng chỉ chuyên môn.\n- Được đào tạo, huấn luyện để có thể làm tốt công việc\n- Khám sức khỏe định kỳ; BHXH, nghỉ lễ theo quy định.\n- Tham gia vào các dự án hiệu năng cao, số lượng dữ liệu lớn và tập khách hàng lớn. Được làm việc trên các hệ thống lớn với các bài toán công nghệ phức tạp.\n- Tham gia vào nhóm phát triển Scrum tự chủ, linh hoạt và năng suất cao theo mô hình Agile/Scrum.\n- Môi trường làm việc trẻ, năng động, vui vẻ, hạnh phúc với các hoạt động văn hóa sôi động như retreat, picnic, team building, happy event, BiPlus radio, …\n- Được làm nhiều, được thử nhiều và được sai, học thực chiến trong công việc.\n- Liên tục phát triển năng lực thông qua các hoạt động học tập (company learning hour, team learning hour, club), đào tạo, mentoring, coaching,…\n- Được phản hồi thường xuyên liên tục và huấn luyện để phát triển năng lực và đạt hiệu suất công việc ngày càng cao (CFRs- Conversation – Feedback – Recognition tháng và 6 tháng).\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa nhà Bảo Anh, Số 85, Trần Thái Tông, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2358, 1255, 2, 'Mobile Developer (IOS)', 'Mô tả công việc:\n- Tham gia phân tích, thiết kế luồng phát triển của ứng dụng dựa vào yêu cầu của khách hàng\n- Đánh giá, phân tích, nâng cấp và tối ưu mã nguồn trong quá trình phát triển\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai\n- Tham gia đưa ra những ý tưởng, giải pháp mới cải thiện công việc.\n\nYêu cầu ứng viên:\n- Có kinh nghiệm phát triển ứng dụng di động bằng iOS (Swift/Objective-c)\n- Biết sử dụng Git để quản lý mã nguồn\n- Có kinh nghiệm test, debug và tối ưu hiệu năng cho ứng dụng\n- Có kinh nghiệm làm việc, quản lý nhóm sử dụng Agile/Scrum.\n- Có hiểu biết về Design Pattern, Coding convention, cấu trúc dữ liệu và giải thuật, OOP\n- Có hiểu biết về phát triển ứng dụng di động bằng Cross-platform là 1 lợi thế (React Native, Flutter)\n- Có sản phẩm trên chợ ứng dụng CH Play, App Store là một lợi thế\n- Có tinh thần trách nhiệm, học hỏi và cầu tiến trong công việc\n\nQuyền lợi:\n- Mức lương: thỏa thuận theo năng lực\n- Làm việc T2 - T6 (từ 08h30 – 18h00, nghỉ trưa 1,5 tiếng), T7 làm việc tại nhà các buổi sáng cách tuần\n- Tài trợ các hoạt động thể dục thể thao, trợ cấp gửi xe, liên hoan, trà bánh, trái cây hàng tuần,...\n- Lương Tháng 13, Thưởng hiệu quả kinh doanh cuối năm\n- BHXH, BHYT, BHTN đầy đủ cho nhân viên theo quy định của pháp luật\n- Xét tăng lương 06 tháng/lần\n- Tổ chức dã ngoại, Teambuilding, picnic công ty hàng năm.\n- Thưởng lễ, tết, sinh nhật,...\n- Nghỉ phép 12 ngày/năm, làm việc đủ 3 năm tăng 01 ngày phép.\n\nĐịa điểm làm việc:\n- Đồng Tháp: Tầng 3, PG2-15 & PG2-15A, Nguyễn Đình Chiểu, P1, TP Cao Lãnh\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Thứ 7 làm các buổi sáng cách tuần, làm việc tại nhà\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Tháp', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2359, 574, 2, 'MIDDLE Blockchain Developer', 'Chúng tôi đang tìm kiếm một Middle - Senior Blockchain Developer tài năng để gia nhập đội ngũ phát triển của HOLA TECH. Vị trí này đóng vai trò quan trọng trong việc xây dựng và phát triển các giải pháp blockchain tiên tiến, góp phần định hình tương lai của công nghệ phân tán. Nếu bạn có kinh nghiệm sâu về smart contract, DeFi, DApps và các nền tảng blockchain hàng đầu, đây là cơ hội tuyệt vời để bạn phát huy năng lực và phát triển sự nghiệp.\n\nYêu cầu ứng viên\n- Có trên 3 năm kinh nghiệm làm việc thực tế trong lĩnh vực phát triển blockchain.\n- Kinh nghiệm sâu sắc với việc phát triển Smart Contract, các ứng dụng DeFi và DApp phức tạp.\n- Có kinh nghiệm làm việc tốt trên các nền tảng blockchain phổ biến như Solana và EVM (Ethereum Virtual Machine - bao gồm Ethereum, BSC, Polygon, v.v.).\n- Sở hữu kỹ năng giải quyết vấn đề mạnh mẽ và tư duy hệ thống tốt, có khả năng phân tích và xử lý các vấn đề kỹ thuật phức tạp.\n- Có kinh nghiệm làm việc trong môi trường phát triển phần mềm sử dụng quy trình Agile/Scrum.\n- Thành thạo ít nhất một trong các ngôn ngữ/công nghệ liên quan như Node.js, React.js và có kinh nghiệm làm việc với Docker và thư viện/SDK Web3.\n\nQuyền lợi\n- Được hưởng đầy đủ các chế độ phúc lợi theo quy định của pháp luật: Đóng BHXH, BHYT.\n- Lương tháng 13 và các khoản thưởng hấp dẫn dựa trên hiệu quả công việc, thưởng đầu và cuối dự án.\n- Tham gia các hoạt động team building, du lịch, sự kiện công ty thường xuyên.\n- Làm việc trong môi trường trẻ trung, năng động, khuyến khích sáng tạo và phát triển cá nhân.\n- Cơ hội phát triển kỹ năng giao tiếp trực tiếp với khách hàng, mở rộng mạng lưới quan hệ.\n- Được tạo điều kiện để phát triển toàn diện các kỹ năng mềm, kỹ năng quản lý và kỹ năng lãnh đạo thông qua các dự án và hoạt động đào tạo nội bộ/bên ngoài.\n\nĐịa điểm làm việc\n- Hà Nội: tòa ecolife, 58 Tố Hữu, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2360, 1256, 2, 'Java Developer', 'Mô tả công việc:\n- Phát triển dịch vụ web bằng JAVA, Front-end sử dụng HTML, CSS, JavaScript, Jquery,..  \n- Sử dụng Spring Boot, Framework, mô hình MVC  \n- Tham gia phát triển, đề xuất giải pháp kỹ thuật cho các dự án  \n- Phát triển các hệ thống mới và nâng cấp các hệ thống đã có  \n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của Leader  \n\nYêu cầu ứng viên:\n- Trình độ đại học, cao đẳng chuyên ngành CNTT hoặc các chứng chỉ tương đương trở lên  \n- Từ 02 năm kinh nghiệm về phát triển dịch vụ web với JAVA framework, yêu thích việc lập trình bằng ngôn ngữ JAVA  \n- Có kiến thức về design patterns và unit test (Junit, TestNG, NUnit)  \n- Nắm vững về HTML, CSS, JavaScript, Jquery là một điểm cộng (các ngôn ngữ khác, nếu không thành thạo sẽ được đào tạo)  \n- Khả năng tự nghiên cứu, phân tích và giải quyết vấn đề  \n- Có khả năng tư duy logic và lập trình  \n- Khả năng làm việc độc lập hoặc theo nhóm  \n- Sẵn sàng học hỏi các công nghệ mới cần thiết cho công việc  \n- Có kiến thức về Spring/Spring Boot, MySQL, Oracle,...  \n\nQuyền lợi:\n- Mức lương: 30 triệu, tùy theo năng lực  \n- Thử việc lên đến 100% lương  \n- Phụ cấp cơm trưa và vé gửi xe hàng tháng  \n- Cung cấp đầy đủ các thiết bị phục vụ cho công việc  \n- Nghỉ thứ 7, chủ nhật  \n- Đóng BHXH sau khi thử việc và hưởng các chế độ phúc lợi theo luật lao động Việt Nam  \n- Đánh giá xét tăng lương 2 lần/năm  \n- Hưởng lương tháng 13  \n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Thạnh, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2361, 1257, 2, 'Japanese Engineer', 'We are seeking a highly skilled Japanese Engineer to join our Vietnam-based development teams in a Senior Engineer/Tech Lead capacity. This role is pivotal in facilitating seamless collaboration between Japanese clients and the Vietnamese development team. The successful candidate will drive project execution, ensure the delivery of high-quality solutions, and contribute to the growth of a dynamic, cross-cultural development environment. What to do: Join actual projects as a Tech Lead, working closely with the Vietnam engineering team. Provide technical mentorship, guidance, and drive decision-making within the project. Identify challenges that are hard to detect from Japan side and propose process and quality improvements. Introduce tools and methodologies to improve development efficiency. Design and execute training plans to upskill local engineers. Personal Requirements: Age Range: Late 20s to early 40s (Flexible). Candidates should be adaptable and open to integrating into local life. Career Orientation: Motivated to build a long-term career abroad, gain hands-on IT experience, and grow in a global working environment. Personality Traits: Positive, open-minded, and collaborative. Must be respectful of diverse perspectives and capable of working effectively in multicultural teams. Language Skills: Proficiency in English (equivalent to TOEIC 700 or above) or fluent Vietnamese is required. Skills Requirements: IT Experience: 7+ YoE in web or mobile application development (at least one specific technology stack). 7+ YoE working in cloud environments (AWS, Azure, or GCP). Hands-on experience with DevOps practices (CI/CD, Docker, etc.). Strong communication and cultural adaptability. Desire to grow in a global, cross-cultural environment. Nice to have: Experience with cutting-edge technologies such as AI or Web3.0. Familiarity with modern engineering practices in a cross-border team setting. Negotiation Skills: Capable of facilitating agreements and aligning expectations between clients and engineering teams. Technical Knowledge: Basic understanding of web application architecture, databases, and IT infrastructure. Business Understanding: Ability to comprehend client business models, operational structures, and key challenges. Competitive Salary – Deserved Rewards: Attractive salary, aligned with your skills and contributions. Salary review twice a year to recognize your dedication. Generous year-end bonus, based on individual performance. Comprehensive Healthcare – We Care About You: Premium health insurance package for extra protection. Annual health check-ups at top-tier hospitals. 20 days of annual leave, ensuring a healthy work-life balance. Modern & Innovative Work Environment: Equipped with MacBook/Laptop & the latest technology to enhance productivity. Modern office design with open spaces, fostering creativity and collaboration. Personal Development – Unlimited Growth Opportunities: Sponsored international certification exams, supporting professional advancement. Specialized training courses & soft skills development to enhance expertise. Flat organizational structure, enabling direct collaboration with leaders and fostering creativity and innovation. Agile Mindset – People-Centric Growth: Open, flexible, and supportive work culture, driving collective success. Stronger team connections, creating a dynamic and efficient workplace. Work Hard – Play Hard: Exciting activities: Open Talks, IT Seminars, Team Building, Project Trips, Sports Day, Year-End Parties… Diverse entertainment: PlayStation, Friday Happy Hours, Mindfulness-related activities… Flexible Working Hours: Monday - Friday: 8:00 AM - 11:30 AM | 1:00 PM - 5:30 PM.\nJoin TechTus, where we work HAPPILY to achieve our DREAMS together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2362, 1131, 2, '.Net Engineer', 'Mô tả công việc:\n- Phát triển và bảo trì các ứng dụng Web sử dụng C# và ASP.NET MVC.\n- Tham gia vào quá trình thiết kế, xây dựng và tối ưu hóa hệ thống Web App.\n- Làm việc với cơ sở dữ liệu SQL Server.\n- Phối hợp với các thành viên trong nhóm để đảm bảo tiến độ và chất lượng dự án.\n- Xử lý lỗi, tối ưu hiệu suất và cải thiện trải nghiệm người dùng.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm, trong đó có 1 năm phát triển Web App bằng C#.\n- Thành thạo ASP.NET MVC, ưu tiên ứng viên chuyên về phát triển Web.\n- Có kinh nghiệm làm việc với SQL Server, Entity Framework.\n- Biết sử dụng HTML, CSS, JavaScript, jQuery là lợi thế.\n- Có tư duy logic, kỹ năng giải quyết vấn đề tốt.\n- Chủ động, có trách nhiệm với công việc.\n\nQuyền lợi:\n- Mức lương cạnh tranh,\n- Lương tháng 13\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop….\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n\nĐịa điểm làm việc:\n- Hà Nội: Dịch Vọng Hậu, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 00:00 đến 00:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2363, 1242, 2, 'Backend Java Developer (Springboot, SQL, Eclipse RCP)', 'We are looking for a skilled and detail-oriented Back End Developer to join our growing development team.  \n\n- Design, develop, test, and maintain server-side applications using Spring Boot.\n- Develop and maintain features in Eclipse RCP-based applications.\n- Write clean, maintainable, and optimized SQL queries for data manipulation and retrieval.\n- Ensure application performance, uptime, and scalability through well-structured code and optimization.\n- Troubleshoot and resolve technical issues in existing applications.\n\n[Required]\n\n- Bachelor’s degree in computer science, Software Engineering, or a related field.\n- 3+ years of experience in Java back-end development.\n- Strong hands-on experience with Spring Boot and Java core.\n- Proficiency in writing and optimizing SQL queries (MySQL, PostgreSQL, or similar).\n- Experience with Eclipse RCP or willingness to learn and work in a desktop-based framework.\n- Familiarity with RESTful APIs and microservices architecture.\n- Strong problem-solving skills and debugging capabilities.\n- Good communication skills in English (reading and writing).\n\n[Nice to have]\n\n- Experience with CI/CD tools and DevOps practices.\n- Knowledge of containerization (Docker, Kubernetes).\n- Familiarity with Agile/Scrum methodologies.\n- Understanding of secure coding practices.\n\n**Quyền lợi**\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Topik allowance\n- Review capacity annually and adjust salary increases according to work performance.\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8 hours/day)\n\n**Địa điểm làm việc**\n- Hà Nội: Tầng 15, Keangnam Landmark 72, Nam Từ Liêm\n\n**Thời gian làm việc**\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\n**Cách thức ứng tuyển**\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2364, 1258, 2, 'FullStack (NodeJS, ReactJS)', 'Tham gia lập trình, vận hành, tối ưu các sản phẩm của công ty.\nTối ưu hóa hiệu suất và bảo mật của các ứng dụng Web.\nXác định và giải quyết các vấn đề liên quan đến ứng dụng Web.\nTham gia vào các quá trình kiểm soát chất lượng cho sản phẩm.\nCác công việc khác theo sự phân công của Quản lý trực tiếp.\nChi tiết trao đổi qua cuộc phỏng vấn.\nThời gian làm việc: Từ thứ 2 đến hết sáng thứ 7, nghỉ chiều thứ Bảy và các ngày Chủ nhật.\n+ Sáng: từ 8h30 – 12h00.\n+ Chiều: từ 13h30 – 18h00.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin, hoặc tương đương\n- Kinh nghiệm: từ 2 năm ở vị trí tương đương.\n- Thành thạo quy trình phát triển phần mềm, từ tiếp nhận yêu cầu, lựa chọn công cụ, ngôn ngữ, thiết kế CSDL, xây dựng frontend, backend, triển khai lên hệ thống server thật.\n- Thành thạo ngôn ngữ lập trình Javascript, CSS, HTML và một framework xây dựng frontend như ReactJS hoặc Angular, biết cách xây dựng website responsive chạy trên mobile.\n- Thành thạo một framework xây dựng backend như NodeJS Express, ngôn ngữ SQL, biết cách sử dụng ORM và vận hành hệ quản trị CSDL như MySQL hoặc Postgres.\n- Biết sử dụng các API và thiết kế API để tương tác với các dịch vụ của khách hàng.\n- Biết đọc tài liệu bằng tiếng anh.\n- Biết phát triển ứng dụng mobile (ReactNative) là một lợi thế.\n- Kỹ năng làm việc độc lập và làm việc nhóm tốt để giải quyết các vấn đề liên quan đến sản phẩm.\n\nQuyền lợi:\n- Mức lương: thỏa thuận\n- Phụ cấp ăn trưa.\n- Được hưởng các chế độ BHXH, BHYT, BHTN và các phúc lợi khác theo quy định của Luật lao động và của Công ty\n- Được đi du lịch và tham gia các hoạt động vui chơi, giải trí khác do công ty tổ chức hàng hàng năm.\n- Được đào tạo bài bản, chuyên sâu nâng cao nghiệp vụ chuyên môn và kỹ năng mềm.\n- Được làm việc trong môi trường chuyên nghiệp, năng động, sáng tạo.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 5 tòa nhà Sannam, 78 Duy Tân, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n- Thứ 7 (từ 08:30 đến 12:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2365, 1207, 2, 'Visual Basic Developer', '- Tham gia phát triển, bảo trì và nâng cấp các dự án sử dụng VB6, VB.NET.\n- Phân tích yêu cầu nghiệp vụ, đề xuất giải pháp kỹ thuật phù hợp.\n- Phối hợp với các bộ phận liên quan trong quá trình triển khai và vận hành hệ thống.\n- Thực hiện kiểm thử, sửa lỗi và cải tiến theo phản hồi người dùng.\n- Tham gia vào các dự án tích hợp với hệ thống viết bằng các ngôn ngữ khác như JAVA, PHP (nếu có kinh nghiệm liên quan).\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của Leader.\n\nYêu cầu ứng viên:\n- Trình độ đại học, cao đẳng chuyên ngành CNTT hoặc các chứng chỉ tương đương trở lên\n- Tối thiểu 2 năm kinh nghiệm làm việc với VB6 và VB.NET.\n- Ưu tiên ứng viên kinh nghiệm với Java, PHP, đặc biệt là trong các dự án tích hợp đa nền tảng.\n- Có ít nhất 2 năm kinh nghiệm làm việc với Oracle, SQL, hoặc các hệ quản trị cơ sở dữ liệu khác.\n- Biết sử dụng công cụ quản lý phiên bản mã nguồn như Git, SVN.\n- Có khả năng phân tích nghiệp vụ, tư duy logic tốt.\n- Có khả năng làm việc độc lập cũng như làm việc nhóm hiệu quả.\n- Ứng viên từng làm dự án với khách hàng Nhật là một lợi thế\n\nQuyền lợi:\n- Mức lương: từ 20-50 triệu/tháng, tùy theo kinh nghiệm.\n- Thử việc lên đến 100% lương\n- Phụ cấp cơm trưa và vé gửi xe hàng tháng\n- Cung cấp đầy đủ các thiết bị phục vụ cho công việc\n- Nghỉ thứ 7, chủ nhật\n- Đóng BHXH sau khi thử việc, hưởng các chế độ phúc lợi theo luật lao động Việt Nam\n- Đánh giá xét tăng lương 2 lần/năm\n- Hưởng lương tháng 13\n- Được tham gia các Câu lạc bộ dưới sự tài trợ chính thức của Công ty: CLB Bóng đá, tham gia các bữa tiệc sinh nhật, team building hàng quý, company trip hàng năm,...\n- Cơ hội thăng tiến cao, cơ hội rất lớn để trở thành key member của công ty.\n- Cơ hội đi công tác và làm việc tại Nhật Bản nếu đáp ứng được năng lực tốt.\n- Môi trường trẻ trung, năng động, chuyên nghiệp theo tiêu chuẩn chất lượng Nhật Bản.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4 Tòa nhà H10, số 2 ngõ 475 Nguyễn Trãi, Thanh Xuân\n- Hồ Chí Minh: 25/7 Nguyễn Bỉnh Khiêm, Phường Bến Nghé, Quận 1\n- Đà Nẵng: 88 An Hải Đông 1, An Hải Đông, Sơn Trà\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 2 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2366, 72, 2, 'Python Developer Leader', '• Phát triển và duy trì ứng dụng phần mềm sử dụng Python (Django), bao gồm thiết kế, lập trình, thử nghiệm và triển khai theo định hướng công ty.\n• Tham gia phát triển và xây dựng dự án FPT Medicare.\n• Tham gia vào toàn bộ vòng đời phát triển phần mềm, từ phân tích yêu cầu đến triển khai sản phẩm, phát triển tính năng mới, tối ưu hóa perfomance và bảo mật nền tảng, đảm bảo hệ thống hoạt động ổn định, tin cậy.\n• Xây dựng và tối ưu hóa các API, microservices và hệ thống.\n• Hỗ trợ phát triển các API và các dịch vụ microservices để tích hợp với các nền tảng đối tác.\n• Làm việc với các công nghệ liên quan đến xử lý dữ liệu và trí tuệ nhân tạo.\n• Hỗ trợ việc tích hợp các hệ thống phần mềm khác nhau.\n• Tham gia vào quá trình đánh giá và lựa chọn công nghệ phù hợp cho dự án.\n• Phối hợp với các thành viên trong nhóm và các bộ phận liên quan để đảm bảo dự án được thực hiện hiệu quả.\n• Thực hiện các công việc khác theo yêu cầu của Trưởng bộ phận.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2367, 1259, 2, 'Front-End Developer', 'Mô tả công việc\nPhát triển giao diện website/app bằng HTML, CSS, JavaScript và các framework như ReactJS, VueJS,...\nTối ưu hóa giao diện cho các thiết bị khác nhau và hiệu suất tải trang.\nKết nối API từ back-end để hiển thị dữ liệu trên giao diện người dùng.\nTham gia đóng góp ý tưởng, cải tiến sản phẩm và trải nghiệm người dùng.\nSửa lỗi và bảo trì giao diện theo yêu cầu.\n\nYêu cầu ứng viên\nHiểu biết về HTML5, CSS3, Responsive Web Design, và các công cụ build front-end (Webpack, Vite, Babel,...).\nBiết sử dụng Git để quản lý source code.\nCó tư duy logic tốt, khả năng làm việc nhóm và chủ động trong công việc.\nƯu tiên ứng viên từng làm việc với RESTful API, Axios, Tailwind CSS hoặc Ant Design.\nHam học hỏi, sẵn sàng tiếp nhận công nghệ mới.\n\nQuyền lợi\n- Môi trường sáng tạo, năng động, đề cao cá tính và ý tưởng thiết kế\n- Được hỗ trợ công cụ làm việc máy tính, tai nghe,...\n- Được đánh giá và xét tăng lương định kỳ\n- Đầy đủ chế độ BHXH, nghỉ lễ/tết theo quy định\n\nĐịa điểm làm việc\n- Thái Nguyên: Tổ 1, phường Phố Cò, thành phố Sông Công, TP Sông Công\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2368, 1260, 2, 'Frontend Website Engineer - Middle', '- Phát triển giao diện website hiện đại, responsive bằng một trong các thư viện/framework như React, Vue.js hoặc tương đương.\n- Tối ưu hóa UI/UX, đảm bảo tương thích với đa trình duyệt và thiết bị.\n- Tích hợp API từ backend, xử lý dữ liệu và trạng thái ứng dụng hiệu quả.\n- Tham gia review code, viết unit test, đóng góp ý tưởng cải thiện kiến trúc frontend.\n- Làm việc chặt chẽ với các team thiết kế, backend và QA để triển khai tính năng.\n(Nếu có năng lực): Hỗ trợ hoặc tham gia vào một số phần việc backend.\n\n- Có từ 4 năm kinh nghiệm lập trình website, trong đó ít nhất 2 năm phát triển frontend bằng React, Vue.js, Angular,.. \n- Có kinh nghiệm thiết kế kiến trúc frontend, tổ chức component theo hướng modular, reusable.\n- Biết làm việc với các thư viện quản lý trạng thái (Redux, Pinia, Zustand, Vuex,...) và routing.\n- Có tư duy tối ưu performance frontend (lazy loading, code splitting, SSR là lợi thế).\n- Ưu tiên ứng viên có kiến thức/kinh nghiệm về Three.js, từng tham gia phát triển fullstack hoặc có hiểu biết về kiến trúc backend/API/database.\n\n- Lương thỏa thuận theo năng lực (thỏa thuận)\n- Thưởng theo hiệu quả, hiệu suất công việc và kết quả kinh doanh của công ty.\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định nhà nước.\n- Được đào tạo và có lộ trình phát triển nghề nghiệp rõ ràng.\n- Cơ hội thăng tiến lên các vị trí cao hơn trong phòng nhân sự hoặc các vị trí cao hơn tùy theo năng lực.\n- Môi trường làm việc chuyên nghiệp, thân thiện, năng động.\n\n- Hà Nội: N7-25 Ngõ 59 Láng Hạ,Thành Công, Ba Đình, Ba Đình \n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2369, 1191, 2, 'Frontend Developer', 'Tham gia phát triển giao diện người dùng cho các ứng dụng web theo yêu cầu của dự án.\nPhối hợp với Backend Developer, UI/UX Designer và các bộ phận khác để xây dựng sản phẩm có trải nghiệm người dùng tốt.\nTối ưu hiệu suất, tốc độ tải trang và khả năng tương thích trình duyệt.\nĐảm bảo chất lượng mã nguồn, tuân thủ tiêu chuẩn lập trình và quy trình CI/CD.\nNghiên cứu và áp dụng các công nghệ mới để nâng cao chất lượng sản phẩm.\n\nYêu cầu ứng viên\n\nBắt buộc:\nGHI RÕ ĐỊA ĐIỂM MONG MUỐN LÀM VIỆC TRÊN CV \nCó kinh nghiệm với một hoặc nhiều framework hiện đại như ReactJS, VueJS, Angular,...\nThành thạo HTML5, CSS3, JavaScript (ES6+).\nBiết sử dụng RESTful API và xử lý dữ liệu JSON.\nHiểu biết cơ bản về Git và quy trình làm việc với Git (pull request, merge, conflict resolution,...).\nCó kinh nghiệm với responsive design, cross-browser compatibility.\nKỹ năng giải quyết vấn đề, tư duy logic và teamwork tốt.\n\nƯu tiên (không bắt buộc):\nCó kinh nghiệm với TypeScript, Next.js, Tailwind CSS, hoặc SASS/SCSS.\nBiết sử dụng công cụ quản lý trạng thái như Redux, Pinia, Zustand,...\nHiểu biết về SEO, tối ưu hiệu suất frontend (Lighthouse, Core Web Vitals).\nCó kinh nghiệm làm việc theo mô hình Agile/Scrum.\n\nTrình độ:\nTốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT, Khoa học máy tính hoặc các ngành liên quan.\nHoặc có kỹ năng tương đương được chứng minh qua dự án cá nhân/thực tế.\n\nQuyền lợi\n\nThu nhập:  15 triệu – 25 triệu/tháng\nĐóng đầy đủ BHXH theo quy định của pháp luật \nThưởng các ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch, ...)\nNghỉ Lễ/Tết, 12 ngày phép/năm và nghỉ phép theo Quy định của Pháp luật hiện hành.\nCác chế độ phúc lợi khác theo quy định của Công ty;\nCung cấp thiết bị làm việc. \nMôi trường làm việc chuyên nghiệp, đồng nghiệp trẻ trung, năng động, tích cực\n\nĐược lựa chọn địa điểm làm việc:\nĐịa điểm 1: V1- A02 Khu đô thị mới An Hưng, Dương Nội, Hà Đông, Hà Nội\nĐịa điểm 2: TechnoPark Tower, xã Đa Tốn, Gia Lâm, Hà Nội (ưu tiên làm việc tại đây)\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2370, 1172, 2, 'Unity Developer', 'Responsibilities:\n- Designing and implementing code that is fit for purpose, scalable, human-readable, and in line with industry best practice.\n- Quality control of the entire product lifecycle by testing intuitiveness, user experience, and debugging where necessary.\n- Communicating with clients to understand their business goals and objectives, and interpreting that into the required changes to the platform where necessary.\n- Liaising with other developers, designers, and system administrators to identify new features and create relevant prototypes for new product ideas.\n- Deploying production code.\n- Communicating the effectiveness of emerging technologies to decision-makers.\n- Working on full production cycles from brainstorming and rapid prototyping to developing fully fledged systems and fine-tuning mechanics, as well as stress testing and bug fixing.\n- Developing innovative gameplay, AI, physics, UI, vehicles, weapons, and character controls.\n- Solving technical problems with simple, efficient, and creative code.\n- Helping ship game projects across multiple platforms on Web, iOS and Android.\n- Providing feedback and advice to junior team members.\n- Other tasks assigned by Line Manager.\n\nRequirements:\n- 4+ years of experience with game engines such as Unity, Pixi, Defold, Godot...\n- Experience working with native Android and iOS is a big plus.\n- History of working within rapid prototyping environments, such as game jams.\n- Passion for video games, films, and other creative mediums.\n- Knowing how to use git to collaborate with other teammates, understanding and applying Git Standards is a must.\n- Experience with remote config, dynamic assets loading.\n- Have knowledge of optimizing games.\n- Ability to build and maintain positive working relationships with teammates.\n- Excellent attention to detail and willingness to learn new software/processes.\n- Flexibility on working hours if required in the light of ad-hoc business demands.\n- Able to use initiative and remain self-motivated.\n- Able to work calmly and effectively under pressure.\n- Maintaining confidentiality/discretion where required.\n\nWhat we offer:\n- A competitive salary package that fits your skills, experiences, and contributions.\n- Holiday and New Year bonus.\n- Provision of necessary working equipment.\n- A professional, dynamic, and inclusive working environment.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 292 Ung Văn Khiêm, Bình Thạnh\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2371, 1261, 2, 'Backend Developer', '- Tham gia vào quá trình phân tích yêu cầu, thiết kế hệ thống và xây dựng các API, microservice\n- Xây dựng các giải pháp backend mạnh mẽ, có khả năng mở rộng và bảo trì cao cho các ứng dụng web và mobile của công ty\n- Tối ưu hóa hiệu suất hệ thống, đảm bảo tính ổn định và bảo mật của dữ liệu\n- Nghiên cứu và áp dụng các công nghệ mới để cải thiện quy trình phát triển và chất lượng sản phẩm\n- Phối hợp với các thành viên khác trong team (Front-end, DevOps, QA) để đảm bảo dự án được hoàn thành đúng tiến độ và đạt chất lượng cao\n- Viết unit test, integration test để đảm bảo chất lượng code\n- Tham gia vào quá trình code review để đảm bảo code được viết theo chuẩn và dễ bảo trì\n\n- Có ít nhất 3 năm kinh nghiệm làm việc với vai trò Backend Developer\n- Có kinh nghiệm làm việc với một trong các ngôn ngữ lập trình backend như: Java, Python, Node.js, Go\n- Có kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu như: MySQL, PostgreSQL, MongoDB\n- Có kinh nghiệm làm việc với các framework backend như: Spring, Django, Express.js\n- Có kinh nghiệm làm việc với các công nghệ như: Docker, Kubernetes, AWS, Google Cloud, Azure\n- Có kiến thức vững chắc về các design pattern, clean code, SOLID principles\n- Có khả năng làm việc độc lập và làm việc nhóm tốt\n- Có khả năng giải quyết vấn đề và tư duy logic tốt\n- Có khả năng đọc hiểu tài liệu tiếng Anh chuyên ngành\n\n- Làm việc tại công ty hàng đầu Việt Nam, luôn không ngừng phát triển với nhiều cơ hội thăng tiến bản thân.\n- Được đào tạo chuyên nghiệp, hoàn toàn miễn phí trước khi làm việc.\n- Môi trường làm việc trẻ, năng động và thân thiện.\n- Tham gia đầy đủ các chế độ BHYT, BHXH, BHTN.\n- Thu nhập hấp dẫn, phù hợp năng lực bản thân.\n- Lương tháng 13 và thưởng theo hiệu quả kinh doanh.\n- Khám sức khỏe định kỳ.\n- Thường xuyên tổ chức các chương trình hội thao, hội diễn văn nghệ, tân niên, tất niên…\n\n- Hồ Chí Minh: Tòa nhà 678, số 67 Hoàng Văn Thái, phường Tân Phú, Quận 7\n\nThời gian làm việc: Thứ 2 - Chủ nhật (từ 08:30 đến 18:00)\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2372, 1262, 2, 'Lập Trình Viên C# /.Net (WPF, WinForms)', 'Mô tả công việc\n- Lập trình phát triển ứng dụng Desktop Application sử dụng C#/.NET (WPF, WinForms);\n- Xây dựng các module chính như:\n- Giao diện tương tác (Dashboard, Data Visualization)\n- Tích hợp API với hệ thống khác\n- Xử lý dữ liệu (Data Processing, AI Integration)\n- Quản lý và tối ưu hệ thống lưu trữ dữ liệu\n- Kết nối với hệ thống AI, xử lý dữ liệu bằng Web API, gRPC hoặc Message Queue (Kafka, RabbitMQ);\n- Triển khai mô hình MVVM, Clean Architecture để tối ưu tổ chức code;\n- Phát triển các module sản phẩm theo yêu cầu của dự án;\n- Làm việc theo sự phân công của Trưởng nhóm / Quản lý dự án, phối hợp giữa các nhóm để phát triển sản phẩm;\n- Làm việc và phát triển sản phẩm theo Agile/Scrum.\n\nYêu cầu ứng viên\n- Tốt nghiệp ĐH/CĐ chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan;\n- Có tối thiểu 2 – 3 năm kinh nghiệm lập trình C# .NET;\n- Thành thạo WPF, WinForms để phát triển ứng dụng Desktop;\n- Có kinh nghiệm làm việc với SQL Server, PostgreSQL hoặc NoSQL (MongoDB, Redis, Elasticsearch);\n- Hiểu biết về cấu trúc dữ liệu, thuật toán, lập trình hướng đối tượng (OOP);\n- Có kinh nghiệm làm việc với RESTful API, WebSockets hoặc gRPC;\n- Có kinh nghiệm tối ưu hiệu suất, đa luồng, xử lý dữ liệu lớn;\n- Tinh thần hợp tác và làm việc tốt.\n\nQuyền lợi\n- Thu nhập: Cạnh tranh\n- Thưởng: 2 lần/ năm, thưởng các ngày lễ, review lương định kỳ hàng năm;\n- Môi trường làm việc năng động, thân thiện, chuyên nghiệp;\n- Teambuilding, khám sức khỏe hàng năm\n- Tạo điều kiện học hỏi phát triển bản thân và các kỹ năng sống;\n- Được cấp máy tính, công cụ để làm việc;\n- Du lịch 1-2 lần/năm và hưởng các quyền lợi khác theo luật lao động;\n- Tham gia các câu lạc bộ free: Đá bóng, cầu lông,...\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 16-VP2, Tòa nhà Sun Square, số 21 lê Đức Thọ, Phường Mỹ Đình 2., Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Linh hoạt thời gian làm việc, yêu cầu bắt buộc lên công ty tối thiểu 2 buổi/tuần hoặc 4 buổi sáng/chiều trong tuần.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2373, 1263, 2, 'Thực Tập Sinh Lập Trình SAP Front-End', 'Mô tả công việc:\n- Lập trình Front-end cho các hệ thống SAP ERP – hệ thống quản trị nguồn lực doanh nghiệp.\n- Tích hợp các hệ thống thông tin, hệ thống phần mềm trong các doanh nghiệp, công ty lớn.\n\nYêu cầu ứng viên:\n- Là sinh viên năm cuối Đại học đang đi thực tập hoặc sắp ra trường.\n- Có kinh nghiệm ít nhất một trong các ngôn ngữ lập trình Front-end như: Javascript, Typescript…\n- Có kinh nghiệm ít nhất 1 Framework như: React.js, Vue.js, Angular….\n- Có tư duy lập trình tốt, nhất là tư duy lập trình Front-end.\n- Có tinh thần ham học hỏi, cầu tiến, chăm chỉ, có trách nhiệm với công việc mình làm.\n- Có khả năng học hỏi công nghệ, ngôn ngữ lập trình mới.\n\nQuyền lợi:\n1. Chế độ đãi ngộ:\n- Có hỗ trợ phụ cấp thực tập đối với thực tập sinh.\n- Sau thực tập được review và ký Hợp đồng chính thức với công ty.\n- Phụ cấp onsite, phụ cấp tăng ca, thưởng dự án, thưởng vượt chỉ tiêu, thưởng tháng lương thứ 13, thưởng lợi nhuận kinh doanh,...\n- Được hưởng các quyền lợi theo Luật Lao động, Nội quy và Quy chế Công ty: tham gia BHXH, BHYT, BHTN theo quy định, phụ cấp thai sản, cưới hỏi, sinh nhật...\n- Định kỳ xét tăng lương và review chuyên môn.\n- Được hỗ trợ các thiết bị, công cụ cần thiết cho thực hiện công việc.\n- Trợ cấp chứng chỉ liên quan đến vị trí công việc.\n\n2. Cơ hội phát triển bản thân:\n- Làm việc với đội ngũ kỹ sư, nhân viên năng động.\n- Được lắng nghe, tôn trọng ý kiến, quan điểm cá nhân để trao đổi thẳng thắn, chia sẻ cùng phát triển.\n- Được lãnh đạo giàu kinh nghiệm đào tạo và định hướng con đường nghề nghiệp rõ ràng.\n- Được cử tham gia các khóa đào tạo mới, đào tạo nâng cao phù hợp với năng lực và nguyện vọng.\n- Được ghi nhận những đóng góp, nỗ lực kịp thời, chính xác.\n- Được tham gia học hoặc thi các chứng chỉ liên quan với chế độ hỗ trợ về chính sách từ Công ty.\n\n3. Đời sống tinh thần:\n- Môi trường làm việc chuyên nghiệp, thân thiện, cởi mở.\n- Tham gia các hoạt động về trau dồi ngôn ngữ (tiếng Anh).\n- Tham gia các cuộc thi nội bộ của Công ty về văn hóa theo quý.\n- Các thành viên trong công ty gần gũi, gắn bó, quan tâm, giúp đỡ nhau cùng phát triển.\n- Được tham gia các hoạt động teambuilding theo tháng, quý, du lịch hàng năm.\n- Công ty luôn động viên và tạo điều kiện tốt nhất cho toàn thể nhân viên.\n- Công ty tổ chức các buổi sinh nhật cho nhân viên hàng tháng, tổ chức thưởng và kỉ niệm những ngày lễ tết trong năm.\n- Hoạt động văn hóa thể thao đa dạng: câu lạc bộ bóng đá, ....\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 1, Tòa nhà HL, số 6/82 đường Duy Tân, phường Dịch Vọng Hậu, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2374, 1264, 2, 'Kỹ Sư Lập Trình Machine Vision', '- Lập trình xử lý ảnh, AI deep learning cho các ứng dụng kiểm tra lỗi sản phẩm, đọc mã vạch QR, Datamatrix, Barcode ... , nhận diện kí tự và tích hợp với robot để định vị trí sản phẩm để robot gắp đặt.\n- Setup Camera Vision , lựa chọn camera, lens, đèn phù hợp để thu được hình ảnh tốt nhất và lên cấu hình vision cho từng bài toán.\n- Lập trình thiết kế phần mềm máy tính, visual studio C++, C#, SQLServer,...\n- Lập trình quản lý hệ thống nhà máy, server truyền thông công nghiệp, lưu trữ truy xuất dữ liệu.\n\nYêu cầu ứng viên:\n- Kinh nghiệm: Ứng viên Fresher/ mới ra trường/ đang chờ bằng/ dưới 1 năm kinh nghiệm (Có nhận thực tập sinh)\n- Đối với ứng viên Fresher khu vực Hồ Chí Minh yêu cầu đào tạo, làm việc tại trụ sở chính Hà Nội tối thiểu 06 tháng.\n- Học vấn: Tốt nghiệp Đại học trở lên các trường kỹ thuật (Bách khoa, công nghiệp, học viện kỹ thuật quân sự, Giao thông vận tải và các trường kỹ thuật khác)\n- Ưu tiên biết lập trình Python, C++ trên nền tảng ROS. Các ứng dụng liên quan tới Web-Base, Database, IOT.\n- Có khả năng làm việc độc lập và làm việc theo nhóm tốt.\n- Chịu được áp lực công việc, ham học hỏi, đam mê kỹ thuật.\n\nQuyền lợi:\n- Chế độ đãi ngộ:\n- Thu nhập từ 9.000.000đ - 15.000.000đ++/tháng. Performance review 2 lần/năm và đột xuất;\n- Thưởng sinh nhật, lễ, tết, quý, tháng lương 13,...;\n- Công tác: Công tác phí, Phụ cấp ăn, xe Công ty đưa đón,..;\n- Chế độ phép linh hoạt 1 ngày/tháng áp dụng từ khi thử việc.\n\n- Chế độ sức khỏe cho nhân viên:\n- Chế độ BHXH theo cấp bậc và thâm niên công tác;\n- Tài trợ 100% thẻ BHSK Bảo Việt cho NLĐ và con đầu tiên, 70% cho con thứ 2,... khám tại tất cả các BV Công và Quốc tế;\n- Khám sức khỏe định kỳ 01 lần/năm tại Bệnh viện dịch vụ 5 sao.\n\n- Tiện ích văn phòng:\n- Không gian làm việc đầy đủ tiện nghi (văn phòng làm việc xanh, tủ lạnh, lò vi sóng..; siêu thị, nhà hàng, bể bơi, gym, bi-a, hair salon, trường mầm non ngay bên cạnh)\n- Cơm văn phòng tự chọn.\n\n- Đào tạo:\n- Đào tạo nội bộ, đào tạo ngoài kiến thức chuyên môn, kỹ năng... phục vụ công việc.\n\n- Các hoạt động sôi nổi:\n- Du xuân, du lịch hè, family day 3 lần/năm;\n- Cấp quỹ Entertainment 100k/người/tháng theo team/phòng ban;\n- Tổ chức sinh nhật cho CBNV định kỳ 01 lần/tháng;\n- Câu lạc bộ, giải bóng đá, bóng bàn, cầu lông, bi-a, esport,...\n\nThời gian làm việc: Từ T2 - hết thứ 6, thứ 7 làm việc/ nghỉ cách tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 2 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2375, 1265, 2, 'Java Backend', 'Mô tả công việc\n- Xây dựng các module lõi cho nền tảng Logistics thế hệ mới của ViettelPost. \n- Tối ưu hóa các nghiệp vụ, thuật toán, kiến trúc để nâng cao chất lượng sản phẩm.  \n- Làm việc trực tiếp với các đội nghiệp vụ để thực thi sản phẩm theo đúng yêu cầu. Tư vấn ngược lại cho đội nghiệp vụ để thông minh hóa quy trình.  \n- Xây dựng các sản phẩm mới phục vụ hàng triệu người dùng của ViettelPost.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học các chuyên ngành CNTT, Khoa học máy tính,... Ưu tiên ứng viên tốt nghiệp các trường Bách Khoa, Học viện kỹ thuật quân sự, Học viện Bưu chính, ĐH Công nghệ-ĐH Quốc gia Hà Nội, Đại học FPT hoặc các trường ĐH quốc tế.\n- Level Senior yêu cầu có 4++ năm kinh nghiệm phát triển phần mềm trở lên với ngôn ngữ JAVA, có kinh nghiệm với các framework như Spring, Quarkus, ZK.\n- Level Junior yêu cầu có 2++ năm kinh nghiệm phát triển phần mềm trở lên với ngôn ngữ JAVA, có kinh nghiệm với các framework như Spring, Quarkus, ZK.\n- Có kinh nghiệm làm việc với một trong các Database Oracle, MariaDB, Postgre, MongoDB, Redis, ElasticSearch.\n- Có kinh nghiệm làm việc với một trong các hệ thống Message Queue (Kafka, RabbitMQ, MQTT).\n- Có hiểu biết về thiết kế hệ thống, design pattern, OOP là một lợi thế.\n- Sử dụng thành thạo các công cụ quản lý code như SVN, Github.\n- Có kiến thức triển khai cơ bản hệ thống trên hệ điều hành Linux.\n- Có khả năng làm việc độc lập và làm việc nhóm, chịu được áp lực cao.\n- Có khả năng tư duy logic và nghiên cứu công nghệ mới.\n- Có khả năng đọc hiểu tài liệu tiếng Anh chuyên ngành.\n\nQuyền lợi\n1. Chế độ về lương thưởng, thu nhập\n• Mức lương 15M - 20M với Junior, 20M - 35M với Middle, 35M - 55M với Senior\n• Có chế độ hỗ trợ tiền điện thoại và ăn trưa, nghỉ mát hàng năm; kèm theo là các khoản thưởng vào các dịp lễ lớn (30/4, 1/5, 2/9, ngày thành lập Tập đoàn, Tổng Công ty, Tết Dương/ Âm).\n2. Chương trình chăm sóc sức khỏe\n• Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và các gói bảo hiểm sức khỏe khác.\n• Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n• Phụ nữ có con nhỏ dưới 1 tuổi sẽ được nghỉ thêm 1h/ngày.\n3. Đào tạo, phát triển\n• Hàng tuần, công ty tổ chức buổi Seminar trao đổi, chia sẻ về các công nghệ mới nhất; là cơ hội để các thành viên học hỏi lẫn nhau.\n• Được tham gia các khóa học bổ ích từ các diễn giả Quốc tế tại Học viện Viettel.\n• Có cơ hội thăng tiến trong nghề nghiệp.\n4. Hoạt động tập thể hấp dẫn, phong phú\n• Tham gia vào hoạt động \'Happy Time" vào chiều thứ 6 hàng tuần cùng với chương trình sinh nhật tháng. \n• Chương trình teambuilding, văn hóa, du lịch nghỉ mát hấp dẫn và đa dạng.\n• Các hoạt động thể dục thể thao cùng các giải đấu được Tập đoàn tổ chức.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Viettel Post, số 2 ngõ 15 Duy Tân, Cầu Giấy.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2376, 1266, 2, 'Software Developer (JLPT N3)', 'Toshiba Software Development (Vietnam), công ty trực thuộc & được đầu tư 100% bởi Toshiba Japan. Chúng tôi đang tìm kiếm những kỹ sư phát triển phần mềm có mong muốn & quyết tâm được phát triển thành Kĩ sư cầu nối (BrSe) chuyên nghiệp. Khi bạn gia nhập vị trí Software Engineer (JLPT N3), công việc của bạn sẽ bao gồm: \n- Được đào tạo bài bản để trở thành Kĩ sư cầu nối chuyên nghiệp \n- Tham gia vào dự án với vai trò tổng hợp domain dự án, truyền tải cho team dự án \n- Đóng vai trò là cầu nối trong giao tiếp, đề xuất với khách hàng về tất cả các vấn đề liên quan đến dự án \n\nYêu cầu ứng viên:\n- Đã tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm, Khoa học máy tính, Toán tin, Điện tử viễn thông…\n- Có ít nhất 3 năm kinh nghiệm làm việc trong phát triển phần mềm với 1 trong các công nghệ bất kỳ, như Java, JS, C++, .Net, Python…\n- Có tiếng Nhật JLPT từ N3. Có khả năng giao tiếp được với khách hàng \n- Mong muốn được phát triển theo hướng BrSe \n\nQuyền lợi:\n- Ứng viên sẽ được hưởng trọn quyền lợi như 1 thành viên của tập đoàn Toshiba, bao gồm:\n- Mức lương cạnh tranh. Thỏa thuận theo năng lực. Up to 1500$ \n- Package lương up to 15 tháng/năm (bao gồm 2 lần thưởng Incentive/ năm, 1 lần thưởng Bonus)\n- Review lương hàng năm \n- Trợ cấp tiếng Nhật hấp dẫn, cạnh tranh top 1 trên thị trường\n- Bảo hiểm 100% lương, hưởng trọn quyền lợi, an tâm làm việc \n- Quy trình làm việc bài bản, chuyên nghiệp. Cơ hội làm việc với nhiều Seniors, Leaders trong ngành.\n- Nhiều cơ hội onsite tại Nhật\n\nĐịa điểm làm việc: \n- Hà Nội: VIT TOWER, 519 KIM MÃ, PHƯỜNG NGỌC KHÁNH, Ba Đình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2377, 1205, 2, 'Lập Trình Viên C++', 'Là một Công ty hoạt động trong lĩnh vực Y tế số, chúng tôi coi nhân sự là trung tâm của mọi hành động. Ominext đang nỗ lực xây dựng một môi trường sống hạnh phúc, chú trọng tới phát triển chuyên môn và chăm sóc sức khỏe cho từng Cán bộ nhân viên, người thân của họ! Gia nhập Ominext ngay hôm nay để tận hưởng các ưu đãi đặc quyền dành riêng cho người Omi.\n\nVới vai trò là Lập trình viên C++, ứng viên sẽ thực hiện các công việc:\n- Cùng team dự án tìm hiểu phân tích yêu cầu, nghiên cứu công nghệ và review source code những sản phẩm trên nền tảng công nghệ C++.\n- Phát triển và bảo trì ứng dụng sử dụng C++ Builder.\n- Thiết kế giao diện người dùng cho ứng dụng.\n- Tối ưu hóa mã nguồn để đảm bảo hiệu suất tốt nhất.\n- Thực hiện kiểm tra và gỡ lỗi (debug) ứng dụng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ thông tin hoặc chuyên ngành liên quan.\n- Có tối thiểu 2 năm kinh nghiệm làm việc với C++\n- Thành thạo lập trình hướng đối tượng (OOP) và các nguyên lý thiết kế phần mềm.\n- Ưu tiên ứng viên có kinh nghiệm lập trình với C++ và C++ Builder  hoặc tương đương (ví dụ như WinForm, Java Swing, ...)\n- Có kinh nghiệm làm việc với SQL Server, MySQL, ...\n- Ưu tiên ứng viên có kinh nghiệm làm việc với VCL\n- Kỹ năng phân tích và giải quyết vấn đề tốt.\n- Khả năng làm việc độc lập và theo nhóm.\n- Có khả năng gỡ lỗi (debug).\n\nQuyền lợi:\n- Môi trường làm việc lý tưởng, được tôn trọng:\n    - Được làm việc trong một môi trường đạt được tiêu chuẩn cao về sự hài lòng của nhân viên.\n    - Thời gian làm việc thoải mái: Thứ 2 – Thứ 6, flexible check in (Linh hoạt 8h/ngày, check in tiêu chuẩn 8h-8h45).\n    - Chính sách làm việc remote linh hoạt 2 ngày/tháng. Áp dụng ngay từ thời gian thử việc.\n    - Chính sách đăng ký OT linh hoạt: OT remote và OT offline.\n    - Chính sách Your times: nghỉ có hưởng lương lên tới 12 ngày trong năm và các ngày nghỉ lễ theo luật Lao động.\n    - Văn phòng làm việc với không gian mở, khu pantry miễn phí đồ uống.)\n    - No Dresscode: trang phục đi làm lịch sự, thoải mái, tôn trọng cá nhân.\n- Tập trung hỗ trợ sự phát triển cá nhân:\n    - Mentor 1-1, sát sao tận tình.\n    - Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng với hệ thống career path (phát triển theo hướng chuyên gia hoặc hướng quản lý) đã được nghiên cứu, thử nghiệm trong nhiều năm.\n    - Tham gia khóa học tiếng Nhật, tiếng Anh miễn phí.\n    - Cơ hội tham gia nhiều dự án đa dạng, team size từ 10MM - 150MM.\n    - Quy trình phát triển phần mềm chặt chẽ, theo các mô hình: Agile, Scrum, Waterfall.\n    - Cơ hội thăng tiến lên các vị trí quản lý như: Team Leader, Techlead,...\n- Quan tâm đặc biệt tới nhân viên:\n    - Mức lương: Hấp dẫn, cạnh tranh với thị trường.\n    - Thưởng hiệu quả sản xuất kinh doanh 2 lần/năm. Thưởng nóng, thưởng lễ tết, lương tháng 13.\n    - Xét tăng lương/thăng chức 2 lần/năm.\n    - Trợ cấp tiếng Nhật 12 tháng liên tục lên tới 5.000.000 VNĐ/ tháng.\n    - Hỗ trợ 100% chi phí thi chứng chỉ CNTT theo chính sách công ty.\n    - Chế độ chăm sóc phụ nữ: nghỉ có hưởng lương 1h/ngày nghỉ sau sinh cho nhân viên nữ có con dưới 12 tháng.\n    - Bảo hiểm chăm sóc sức khỏe cao cấp miễn phí dành riêng cho Omizen Care.\n    - Tủ thuốc miễn phí chăm sóc sức khỏe cá nhân tại Văn phòng làm việc.\n    - Khám sức khỏe thường niên tại phòng khám, bệnh viện hàng đầu Việt Nam cùng các chế độ BHXH theo quy định của nhà nước.\n    - Được tham gia các CLB để nâng cao sức khỏe, tinh thần: CLB bóng đá, CLB cầu lông, CLB bóng bàn,...\n    - Du lịch thường niên, hoạt động team building hàng quý/năm.\n\nĐịa điểm làm việc: Tòa nhà 6th Element, khu đô thị Tây Hồ Tây, quận Tây Hồ, Hà Nội\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2378, 1267, 2, 'Kỹ Thuật Viên Lập Trình CNC', 'Lập trình gia công cho loại máy CNC: máy cưa, máy cắt dây, máy tiện, máy phay, máy xung điện, máy khoan-taro, máy khắc laser\nTiếp nhận các bản vẽ từ bộ phận thiết kế.\nTiến hành kiểm tra, bóc tách bản vẽ thiết kế.\nSử dụng phần mềm chuyên dụng thực hiện lập trình gia công các chi tiết, đảm bảo phù hợp với các thông số kỹ thuật của máy CNC.\nXuất bản vẽ và gửi lên trưởng bộ phận kiểm tra.\n\nYêu cầu ứng viên\n- Sức khỏe tốt\n- Nhanh nhẹn, cẩn thận, kiên nhẫn, tỉ mỉ\n- Yêu thích các loại máy móc cơ khí\n- Sử dụng ít nhất một phần mềm lập trình CNC\n- Có kinh nghiệm làm việc với nhiều loại máy CNC là một lợi thế.\n- Sẵn sàng làm thêm giờ theo yêu cầu.\n- Sẵn sàng đi công tác theo yêu cầu.\n\nQuyền lợi\n- Thỏa sức học hỏi về các kỹ năng lập trình máy CNC, gia tăng cơ hội phát triển nghề nghiệp tại công ty hoặc các doanh nghiệp lớn khác. Đến với QCM bạn sẽ lập trình được tất cả các dạng chi tiết 2D, 3D, 4D, 5D, đáp ứng được công việc tại bất kỳ công ty nào khác, vì QCM chúng tôi sản xuất đầy đủ các chủng loại sản phẩm, có đầy đủ các loại máy móc phù hợp từ đơn giản đến hiện đại.\n- Lương cơ bản 6-15tr/1 tháng tùy theo năng lực, trình độ. Thưởng tết 1-1.5 tháng lương tùy theo hiệu quả công việc, thưởng ngày lễ chiến thắng, ngày lễ quốc khánh, du lịch hàng năm.\n- BHYT, BHXH, BHTN theo quy định của nhà nước\n- Phụ cấp chuyên cần 400k/1 tháng, phụ cấp đi lại 150k/1 tháng, phụ cấp nhà trọ 300k/1 tháng, miễn phí ăn ca, ăn trưa theo chính sách của công ty.\n- Được đào tạo vận hành, sử dụng máy móc thiết bị hỗ trợ, đào tạo nâng cao kỹ năng gá đặt, cài đặt, đào tạo lập trình máy đối với các nhân viên mong muốn học nâng cao.\n- Môi trường làm việc năng động, cơ hội nâng cao kỹ năng, kiến thức, kinh nghiệm thông qua các dự án sản xuất đa dạng các loại máy móc thiết bị công nghiệp, dân dụng, y tế,…\n\nĐịa điểm làm việc\n- Hà Nội: 57-LÊ HỮU TỰU-NGUYÊN KHÊ, Đông Anh\n- Hà Nội: Sóc Sơn\n- Bắc Giang\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2379, 1268, 2, 'Embedded Systems Developer', 'Mô tả công việc\n- Phát triển các hệ thống phần mềm hệ thống cho cho các dòng máy điện, điện lạnh thông minh, IoT;\n- Tham gia vào phân tích yêu cầu, thiết kế kiến trúc hệ thống, thiết kế phần mềm nhúng;\n- Phát triển firmware thiết bị, phần mềm nhúng;\n- Thu thập và xử lí các yêu cầu thiết kế và kĩ thuật;\n- Nghiên cứu và áp dụng các công nghệ mới để tối ưu hóa hiệu quả phát triển sản phẩm;\n- Đảm bảo sản phẩm làm ra cần phải chạy đúng nghiệp vụ và tốc độ xử lý cũng phải tối ưu cho lượng người dùng và thiết bị kết nối lớn.\n\nYêu cầu ứng viên\n- Có kiến thức về lập trình hướng đối tượng;\n- Tốt nghiệp Cao đẳng/ Đại học chuyên ngành Điện, Tự động hóa, Điện tử, Cơ tin... \n- Kinh nghiệm ở vị trí lập trình nhúng 5-6 năm\n- Ưu tiên có kinh nghiệm lập trình nhúng cho các thiết bị điện tử, điện lạnh, gia dụng hoặc vi điều khiển, ESP MCU, Arduino, Mediatek, Qualcomm;\n- Ưu tiên kinh nghiệm với AWS IoTCore, MQTT, Media Streaming, FOTA, Voice Recognition;\n- Nắm vững và sử dụng thành thạo C/C++ và Shell. Có khả năng lập trình Python là lợi thế;\n- Có kiến thức và kinh nghiệm làm việc với Linux kernel, Drivers;\n- Có khả năng làm việc độc lập và làm việc nhóm.\n- Khả năng làm việc tốt trong môi trường tốc độ cao, quy trình quản lý Agile.\n\nQuyền lợi\n- Mức lương cạnh tranh thỏa thuận theo năng lực.\n- Thử việc hưởng 100% lương\n- Thời gian làm việc linh hoạt từ T2-T6\n- Môi trường làm việc trẻ trung, năng động, tài năng\n- Mức lương cạnh tranh, Review tăng lương 2 lần/năm\n- Thưởng ngày Lễ/Tết, hiệu suất công việc, thưởng dự án theo tháng\n- Ăn chơi du lịch theo tháng + các hoạt động team building\n- Có cơ hội được đào tạo phát triển và thăng tiến.\n\nĐịa điểm làm việc\nHà Nội: Số 9A Thanh Liệt, Thanh Trì\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nTừ Thứ 2 đến Sáng Thứ 6 và 2 thứ 7 trong tháng.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2380, 1269, 2, 'Lập Trình Android (Mobile Dev)', 'Mô tả công việc:\n1. Tham gia xây dựng và triển khai ứng dụng Mobile/Tablet (Flutter)\n2. Nghiên cứu giải pháp và triển khai giải pháp theo yêu cầu của từng sản phẩm\n3. Tối ưu và nâng cấp mã nguồn để đảm bảo hiệu quả, ổn định và an toàn, có hiệu suất cao và thân thiện với người dùng.\n4. Tìm giải pháp, lên kế hoạch ý tưởng giải quyết các tính năng mới hoặc các vấn đề người dùng gặp phải\n5. Tham gia, đề xuất các phương án tối ưu trải nghiệm người dùng cho ứng dụng/ Launcher.\n\nYêu cầu ứng viên:\n- Có kinh nghiệm lập trình Flutter từ 2 năm trở lên.\n- Thành thạo làm việc với Git.\n- Có kiến thức về OOP, giải thuật, design pattern.\n- Nắm được các mô hình MVP, MVVM.\n- Có kinh nghiệm lập trình các ứng dụng Android, lập trình cross-platform.\n\nQuyền lợi:\n- Thưởng cuối năm thưởng hiệu quả công việc...\n- Thưởng các ngày lễ, Tết; sinh nhật, thưởng sáng kiến...\n- Môi trường làm việc trẻ, năng động. Môi trường làm việc ổn định, lâu dài, cơ hội học hỏi các công nghệ mới nhất, cơ hội trưởng thành, tiến thân.\n- Du lịch, khám sức khỏe định kỳ.\n- Các khoản phụ cấp khác: Phụ cấp ăn trưa, gửi xe, công tác...\n- Đóng BHXH, BHYT, BHTN.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 9, tòa Viwaseen, 48 Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 7 làm việc luân phiên.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2381, 1270, 2, 'Odoo Developer', 'Mô tả công việc\n- Lập trình viên Python trên nền tảng Odoo\n- Tham gia phát triển, bảo trì, triển khai phần mềm quản trị doanh nghiệp cung cấp cho khách hàng vừa và nhỏ\n- Dựa trên nền tảng Odoo phát triển các công cụ quản trị cho doanh nghiệp như: Quản lý kho, quản lý sản xuất, quản lý nhân sự, quản lý dự án, quản lý khách hàng (CRM), thương mại điện tử,...\n- Phối hợp với thành viên nhóm dự án, nhóm BA, kiểm thử và khách hàng triển khai dự án\n- Xây dựng kế hoạch công việc, báo cáo, đánh giá công việc của cá nhân, đóng góp các sáng kiến nâng cao chất lượng, năng suất công việc\n\nYêu cầu ứng viên\n- Có từ 2 năm kinh nghiệm Developer và tiếp xúc/làm việc với Odoo/OpenERP\n- Có khả năng làm việc với phần mềm quản lý mã nguồn (VD: Github, Gitlab,...)\n- Có kiến thức và kỹ năng lập trình database; ưu tiên thành thạo PostgreSQL\n- Ưu tiên ứng viên có khả năng làm việc với Linux\n\nQuyền lợi\n- Mức lương cạnh tranh thị trường, theo năng lực;\n- Phụ cấp ăn trưa;\n- Cơ hội thăng tiến cao;\n- Môi trường làm việc năng động,trẻ trung, bứt phá;\n- Xét tăng lương hàng năm;\n- Chế độ sinh nhật, cưới hỏi, ốm đau, ...;\n- Thưởng tháng- quý, thưởng nóng, thưởng dự án, thưởng Lễ/Tết, tháng Lương thứ 13 ...;\n- Chế độ du lịch hàng năm;\n- Chế độ mua hàng ưu đãi cho CBNV, miễn phí khu vui chơi cho con em CBNV;\n- Được tham gia các khóa đào tạo nội bộ để nâng cao chuyên môn;\n- Được tham gia BHYT, BHXH và các chế độ phúc lợi khác theo quy định của nhà sách\n\nĐịa điểm làm việc\n- Hà Nội: Số 424 Nguyễn Trãi, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6: 8h - 17h\nThứ 7: 8h - 12h\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2382, 1207, 2, 'Java Developer - 2 Năm Kinh Nghiệm', 'Mô tả công việc:\n- Phát triển dịch vụ web bằng JAVA, Front-end sử dụng HTML, CSS, JavaScript, Jquery,..  \n- Sử dụng Spring Boot, Framework, mô hình MVC  \n- Tham gia phát triển, đề xuất giải pháp kỹ thuật cho các dự án  \n- Phát triển các hệ thống mới và nâng cấp các hệ thống đã có  \n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của Leader  \n\nYêu cầu ứng viên:\n- Trình độ đại học, cao đẳng chuyên ngành CNTT hoặc các chứng chỉ tương đương trở lên  \n- Từ 02 năm kinh nghiệm về phát triển dịch vụ web với JAVA framework, yêu thích việc lập trình bằng ngôn ngữ JAVA  \n- Có kiến thức về design patterns và unit test (Junit, TestNG, NUnit)  \n- Nắm vững về HTML, CSS, JavaScript, Jquery là một điểm cộng (các ngôn ngữ khác, nếu không thành thạo sẽ được đào tạo)  \n- Khả năng tự nghiên cứu, phân tích và giải quyết vấn đề  \n- Có khả năng tư duy logic và lập trình  \n- Khả năng làm việc độc lập hoặc theo nhóm  \n- Sẵn sàng học hỏi các công nghệ mới cần thiết cho công việc  \n- Có kiến thức về Spring/Spring Boot, MySQL, Oracle,...  \n- Có tiếng Nhật là một lợi thế  \n\nQuyền lợi:\n- Mức lương: 15 - 45 triệu, tùy theo năng lực  \n- Thử việc lên đến 100% lương  \n- Phụ cấp cơm trưa và vé gửi xe hàng tháng  \n- Cung cấp đầy đủ các thiết bị phục vụ cho công việc  \n- Nghỉ thứ 7, chủ nhật  \n- Đóng BHXH sau khi thử việc và hưởng các chế độ phúc lợi theo luật lao động Việt Nam  \n- Đánh giá xét tăng lương 2 lần/năm  \n- Hưởng lương tháng 13  \n- Được tham gia các Câu lạc bộ dưới sự tài trợ chính thức của Công ty: CLB Bóng đá, Lớp tiếng Nhật,...  \n- Được ham gia các bữa tiệc sinh nhật, team building hàng quý, company trip hàng năm,...  \n- Cơ hội thăng tiến cao, cơ hội rất lớn để trở thành key member của công ty.  \n- Môi trường trẻ trung, năng động, chuyên nghiệp theo tiêu chuẩn chất lượng Nhật Bản.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 1, Hà Nội, Thanh Xuân, Đà Nẵng, Sơn Trà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2383, 1271, 2, 'Fullstack Developer', '1. Thiết kế, phát triển, triển khai và tối ưu hệ thống phần mềm\n- Phân tích yêu cầu, vấn đề và rủi ro có thể phát sinh trong quá trình thực hiện yêu cầu.\n- Thiết kế tổng thể hệ thống, các module thành phần, các chức năng chi tiết\n- Lập trình phát triển, bảo trì các chức năng hệ thống phía backend.\n- Triển khai và tích hợp các thành phần hệ thống phía backend và frontend\n- Tối ưu các thành phần hệ thống phía backend: code, database.\n- Triển khai và vận hành ứng dụng trên docker, k8s...\n- Tham gia xây dựng pipeline thu thập, xử lý và phân tích dữ liệu từ các thiết bị network, server trong Data center.\n- Xây dựng thuật toán giúp tối ưu cho việc xuất kho, điều chuyển hàng hoá phục vụ xây lắp công trình, trạm..\n\n2. Hợp tác và chia sẻ\n- Hợp tác với các thành viên trong dự án để thiết kế API phù hợp với yêu cầu của tính năng.\n- Chia sẻ kiến thức, công nghệ với các thành viên trong nhóm.\n- Review code giữa các thành viên trong dự án và code của đối tác\n\nYêu cầu ứng viên\n1. Yêu cầu chuyên môn tối thiểu\n- Hiểu biết cơ bản về mạng máy tính, các giao thức mạng máy tính: UDP, TCP/IP, HTTP\n- Hiểu biết và sử dụng Git để quản lý phiên bản.\n- Có tư duy xác định và giải quyết vấn đề.\n- Có kinh nghiệm làm việc với Nodejs và các framework: NestJS(TypeORM, Queue, Cache)\n- Có kinh nghiệm code frontend (VueJS, Reactsj)\n- Có kinh nghiệm làm việc với CSDL (Oracle, MySQL/MariaDB, PostgreSQL, Elasticsearch) bao gồm phát triển, viết các truy vấn phức tạp, tối ưu CSDL, SQL\n- Hiểu biết về docker\n- Có kinh nghiệm làm việc với redis để tối ưu hiệu năng\n\nYêu cầu chuyên môn mở rộng\n- Thông thạo nhiều ngôn ngữ lập trình là một lợi thế.\n- Có kinh nghiệm sử dụng hệ điều hành Linux là một lợi thế.\n- Có hiểu biết về REST, RESTful API. Có kinh nghiệm thiết kế và cài đặt RESTful API là một lợi thế.\n- Có hiểu biết về containerization với Docker, container orchestration với Kubernetes là một lợi thế.\n- Có hiểu biết, kinh nghiệm xử lý và phân tích dữ liệu là một lợi thế.\n- Có khả năng tự nghiên cứu về thuật toán để đề xuất hướng giải quyết hoặc trực tiếp triển khai vào sản phẩm là một lợi thế.\n- Có khả năng nghiên cứu về các kiến trúc, nền tảng phù hợp xây dựng hệ thống linh hoạt, dễ mở rộng là một lợi thế.\n\n2.Trình độ học vấn\n- Tốt nghiệp đại học chính quy chuyên ngành: công nghệ thông tin (Information Technology), khoa học máy tính (Computer Science), kỹ nghệ phần mềm (Software Engineer) hoặc tương đương.\n- Yêu cầu tiếng Anh: TOEIC IIG 550 hoặc tương đương.\n- Đã từng tham gia và đạt giải trong các kỳ thi cấp quốc gia, quốc tế như HSG quốc gia, olympic sinh viên, ACM/ICPC,...; tham gia nghiên cứu khoa học, tham gia hoạt động cộng đồng như mã nguồn mở, CLB lập trình; tham gia các cuộc thi lập trình, hackathon... là một lợi thế.\n- Có chứng chỉ chuyên môn được công nhận bởi các tổ chức uy tín là một lợi thế.\n\nQuyền lợi\n- Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn\n- Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel\n- Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm\n- Cơ hội tiếp xúc với các dự án lớn, mới mẻ & tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam\n- Cơ hội thăng tiến rõ ràng với nhiều cấp bậc\n- Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn\n- Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời.\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người\n- Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,...\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày\n- Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng\n\nĐịa điểm làm việc\n- Hà Nội\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2384, 1164, 2, 'Frontend Developer', 'The Front-End Developer is responsible to write software applications from design specifications; Plans, executes and documents unit tests; Reports status and issues; Documents detailed designs; Accountable for unit test leakage; Contributes to system architecture and design decisions.\n\nDevelop and maintain websites and real-time front-end systems across multiple platforms: PC, Mobile, Tablet.\nOptimize website performance, ensure standardization and SEO best practices, and help build the company\'s brand image.\nConvert UI/UX design files (PSD, Figma, XD, etc.) into responsive and modern HTML/CSS interfaces.\nWrite clean, well-documented, and tested JavaScript/TypeScript, HTML, and CSS code.\nIntegrate with RESTful APIs and collaborate closely with UI/UX designers, backend developers, and team members.\nEnsure cross-browser and cross-device compatibility for all front-end features.\nParticipate in improving workflows and sharing knowledge with the team.\n\nYêu cầu ứng viên:\n\nBachelor’s degree in Computer Science, Software Engineering, or related field.\nHave at least 5 years of experience in a Front-end Developer.\nProficient in HTML5, CSS3, JavaScript (TypeScript is a plus).\nSolid understanding of at least one modern front-end framework: ReactJS (with Redux), VueJS (with Vuex), or AngularJS (with NgRx, Akita, etc.).\nProficient in using state management tools (e.g., Redux for React, Vuex for Vue, NgRx for Angular) to handle complex application state.\nGood grasp of OOP and basic Design Patterns.\nExperience handling cross-browser compatibility issues.\nFamiliar with RESTful APIs and integrating data from backend services.\nExperience with Git and modern build tools (Webpack, Babel, etc.) is a plus.\nKnowledge of task management tools (Jira, Trello, Asana, etc.) is a plus.\nCreative thinker with strong problem-solving skills and a proactive, responsible attitude.\nAble to work independently and as part of a team.\nGood reading and writing skills in English.\n\nQuyền lợi:\n\nThe attractive salary (Negotiation).\n2-month probation period with 100% salary.\nFull salary insurance coverage after the probation period.\nParticipation in the PVI health insurance package, and annual health check-ups.\n13th-month salary, birthday bonus, New Year bonus, Mid-Autumn Festival gifts, March 8th and October 20th gifts, etc.\nPerformance evaluation and regular salary increases.\nWelfare for personal events, childbirth, and other benefits as per labor regulations and company welfare policies.\nDynamic and youthful work environment conducive to personal growth and development.\n\nĐịa điểm làm việc:\nHà Nội: 27th Floor, East Tower, Lotte Center Hanoi, 54 Lieu Giai, Ba Đình.\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:30 đến 17:30) Flexible working hours may apply depending on project (e.g., 1:00 PM – 9:00 PM).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2385, 399, 2, 'Giám Đốc Khối Công Nghệ Thông Tin', '1. Lập kế hoạch và chiến lược công nghệ:\n- Xây dựng và triển khai chiến lược công nghệ thông tin phù hợp với mục tiêu phát triển của công ty.\n- Đánh giá và đề xuất các công nghệ mới nhằm nâng cao hiệu quả hoạt động kinh doanh.\n- Tìm hiểu các công nghệ mới nhất và lên chiến lược áp dụng cho hệ thống hiện tại.\n\n2. Đảm bảo an ninh thông tin:\n- Thiết lập và duy trì các chính sách bảo mật thông tin, đảm bảo an toàn cho dữ liệu và hệ thống của công ty.\n- Phối hợp với các bộ phận liên quan để quản lý rủi ro và xử lý các sự cố an ninh thông tin kịp thời.\n\n3. Quản lý phát triển phần mềm:\n- Giữ vai trò đầu mối tổ chức, điều phối và tham gia vào việc thiết kế, phát triển và triển khai các ứng dụng phục vụ cho giao dịch chứng khoán và quản lý tài sản.\n- Đảm bảo các sản phẩm phần mềm được phát triển đúng tiến độ, chất lượng và đáp ứng yêu cầu của người dùng.\n\n4. Quản lý hạ tầng công nghệ:\n- Giám sát hạ tầng CNTT, hệ thống giao dịch chứng khoán, đảm bảo hệ thống hoạt động ổn định, bảo mật và có khả năng mở rộng.\n- Kiểm tra, rà soát và tối ưu data-center để đảm bảo môi trường Core chứng khoán trên Production hoạt động liên tục, hạn chế downtime.\n- Giám sát và quản lý các dự án công nghệ thông tin, bao gồm việc triển khai các giải pháp phần mềm và hạ tầng.\n- Giám sát việc quản lý mạng nội bộ, hệ thống máy chủ, tài nguyên CNTT và bảo mật thông tin.\n\n5. Đào tạo và phát triển nhân sự:\n- Xây dựng và phát triển đội ngũ nhân viên công nghệ thông tin, tổ chức các khóa đào tạo nâng cao kỹ năng cho nhân viên.\n- Khuyến khích văn hóa đổi mới và sáng tạo trong đội ngũ.\n\nCông nghệ ABS đang sử dụng\n- Kiến trúc: Microservices\n- Ngôn ngữ lập trình: Java, Spring Boot, NodeJS, React, Flutter\n- Message broker: Kafka, RabbitMQ, ActiveMQ\n- Cơ sở dữ liệu: Oracle, Redis, Postgres, MongoDB\n- Công nghệ xử lý realtime: Apache Flink, Kafka\n- Công nghệ triển khai vận hành: Docker, VMWare, Jenkins, Ansible, ElasticSearch, Elastic APM, WSO2 API Manager\n\nYêu cầu ứng viên\n- Kinh nghiệm: Trên 10 năm kinh nghiệm, trong đó tối thiểu 03 năm kinh nghiệm ở vị trí tương đương.\n- Trách nhiệm, trung thực, nhiệt huyết, tư duy thiết kế hệ thống xuất sắc.\n\nQuyền lợi\n- Thu nhập hấp dẫn\n- Lương cạnh tranh, thưởng KPI hấp dẫn. Review lương hàng năm\n- Lương tháng 13 và thưởng các ngày Lễ tết, phụ cấp ăn trưa, gửi xe miễn phí\n- Chương trình mua cổ phiếu Công ty với giá ưu đãi dành riêng cho CBNV trong Công ty\n- BH sức khỏe cá nhân chuyên biệt và Khám sức khỏe tại các cơ sở uy tín\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, công ty đang trên đà tăng trưởng mạnh mẽ\n- Thời gian làm việc: thứ 2 đến thứ 6\n\nĐịa điểm làm việc\n- Hà Nội: 36 Hoàng Cầu, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2386, 1272, 2, 'Java Developer', 'Mô tả công việc:\n- Tham gia phân tích yêu cầu, thiết kế và phát triển hệ thống backend sử dụng Java (Spring Boot, Spring MVC, Hibernate).\n- Phát triển các API RESTful phục vụ frontend hoặc tích hợp với hệ thống khác theo kiến trúc microservices.\n- Thiết kế và triển khai các service sử dụng Redis, Kafka, RabitMQ … để caching hoặc xử lý bất đồng bộ (pub/sub, queue).\n- Làm việc với cơ sở dữ liệu quan hệ như MariaDB, PostgreSQL, Oracle … bao gồm thiết kế schema, viết stored procedures, tối ưu truy vấn.\n- Tích hợp và triển khai hệ thống trên môi trường Linux, Windows server, sử dụng Docker, Git, CI/CD pipelines.\n- Tham gia xây dựng, vận hành các hệ thống sử dụng Spring Boot, Spring MVC, Spring Cloud, Config Server, Service Discovery (Eureka/Consul), Gateway, Hystrix, v.v.\n- Phối hợp với BA, frontend, tester trong quá trình phát triển, kiểm thử và fix bugs.\n- Viết tài liệu kỹ thuật: mô tả API, tài liệu cấu hình triển khai, hướng dẫn sử dụng.\n- Hỗ trợ triển khai, bảo trì, vận hành các hệ thống đã phát triển.\n- Tham gia review code, đề xuất cải tiến hiệu năng, kiến trúc hệ thống.\n- Các công việc khác theo phân công của quản lý.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm, Hệ thống thông tin hoặc các ngành liên quan.\n- Có từ 2 năm kinh nghiệm trở lên.\n- Có kiến thức nền tảng tốt về Java Core, Java Web, lập trình hướng đối tượng (OOP).\n- Có kinh nghiệm phát triển, triển khai hệ thống theo kiến trúc microservices.\n- Thành thạo SQL, hiểu biết cơ bản về các hệ quản trị cơ sở dữ liệu như Oracle, MySQL, PostgreSQL.\n- Hiểu và từng làm việc với một số message broker như Kafka, RabbitMQ là lợi thế.\n- Có kiến thức về các công nghệ frontend căn bản như HTML/XHTML, CSS, JavaScript, AJAX, XML, Web Services.\n- Hiểu biết và từng làm việc trên môi trường Linux.\n- Thành thạo sử dụng hệ thống quản lý mã nguồn như Git, SVN.\n- Ưu tiên có hiểu biết hoặc kinh nghiệm với Spring Security, OAuth2, JWT.\n- Có kinh nghiệm xây dựng RESTful API, viết unit test bằng JUnit, Mockito… là lợi thế.\n\nQuyền lợi:\n- Mức lương UPTO 30 triệu, thỏa thuận theo năng lực ứng viên.\n- Thưởng dịp tết (tết dương và tết âm), dịp lễ (30/04-1/5; 2/9; Trung thu…) sinh nhật, hiếu hỷ…\n- Được tài trợ, tham gia các khóa đào tạo kỹ năng, chuyên môn hàng năm, thi lấy chứng chỉ để phục vụ cho công việc.\n- Review đánh giá tăng lương hàng năm.\n- Nghỉ phép 12 ngày/năm, nghỉ ốm/nghỉ chế độ thai sản/hiếu hỷ… theo luật lao động.\n- Làm việc tại công ty quy mô lớn, quy trình làm việc chuyên nghiệp, được khuyến khích sáng tạo và phát triển các ý tưởng mới.\n- Môi trường trẻ, năng động, chuyên nghiệp, sếp trẻ tâm lý, đồng nghiệp thân thiện, văn hóa trao đổi thẳng thắn, cởi mở trên tinh thần hỗ trợ cùng phát triển.\n- Dự án lớn áp dụng các công nghệ tiên tiến nhiều cơ hội thăng tiến và phát triển.\n- Cung cấp đầy đủ trang thiết bị làm việc.\n- Được hưởng đầy đủ các chế độ BHYT, BHXH, BHTN.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4, Tòa The Garden Hill, 99 Trần Bìn, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2387, 209, 2, 'Senior React Native Good English', 'Mô tả công việc\n- Build pixel-perfect, buttery smooth UIs across both mobile platforms.\n- Leverage native APIs for deep integrations with both platforms.\n- Diagnose and fix bugs and performance bottlenecks for performance that feels native.\n- Reach out to the open source community to encourage and help implement mission-critical software fixes—React Native moves fast and often breaks things.\n- Maintain code and write automated tests to ensure the product is of the highest quality.\n- Transition existing React web apps to React Native.\n\nYêu cầu ứng viên\nMust have:\n- 5+ years of professional experience working with React Native.\n- Experience working with Swift, Objective C, and Java a plus but not required.\n- Meaningful experience working on large, complex systems.\n- Ability to take extreme ownership over your work. Every day is a challenge to ensure you are performing to the expectations you and your team have agreed upon, both in regards to estimates and to general process.\n- Ability to identify with the goals of FullStack clients, and dedicate yourself to delivering on the commitments you and your team make to them.\n- An understanding of React Native best practices and a commitment to following them.\n- Ability to work through new and difficult React Native issues and contribute to libraries as needed.\n- Ability to create and maintain continuous integration and delivery of React Native applications.\n- A positive mindset and can-do attitude.\n- Forensic attention to detail.\n- Good English.\nNice to have:\n- Full-stack engineer with React and Node.js experience\n- Experience with at CSS preprocessors\n- Experience with Databases such as MongoDB or PostgreSQL.\n\nQuyền lợi\n- “FPT care” health insurance provided by AON and is exclusive for FPT employees.\n- Annual Summer Vacation: follows company’s policy and starts from May every year.\n- Salary review time/year or on excellent performance.\n- International, dynamic, friendly working environment.\n- Annual leave, working conditions follow Vietnam labor laws.\n- Other allowances: lunch allowance, working on-site allowance, etc.\n\nĐịa điểm làm việc\n- Đà Nẵng\n- Đồng Nai\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng, Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2388, 1273, 2, 'React Native Developer', 'Mô tả công việc\n・Tham gia xây dựng và phát triển các tính năng mới cho các ứng dụng mobile trên nền tảng React Native, Flutter\n・Nâng cấp các phần mềm hiện có\n・Bảo trì các hệ thống đã triển khai\n・Tham gia nghiên cứu công nghệ mới đáp ứng yêu cầu dự án\n・Các công việc được giao từ quản lý trực tiếp.\n\nYêu cầu ứng viên\n・Tốt nghiệp chuyên ngành CNTT hoặc có liên quan\n・Có ít nhất 03 năm kinh nghiệm làm việc về React-Native, Redux, Flutter\n・Có kinh nghiệm làm việc với Restful API, Firebase, Redux, Socket, Push Notification, Reanimated\n・Có kiến thức về IOS và Android. Đã từng tham gia, giải quyết các vấn đề liên quan native ios, android\n・Cẩn thận, kiên nhẫn và có khả năng nghiên cứu công nghệ mới đáp ứng yêu cầu dự án\n・Biết ReactJS, SpringBoot là một lợi thế\n・Có mong muốn gắn bó lâu dài\n\nQuyền lợi\n・Mức lương hấp dẫn: Up to 35.000.000VND\n・Có cơ hội đi công tác Nhật Bản, trải nghiệm thực tế nghiệp vụ phía khách hàng\n・Được tham dự các chương trình, hỗ trợ trong việc định hướng phát triển nghề nghiệp\n・Thưởng lương tháng 13, thưởng Lễ - Tết, sinh nhật, thưởng kinh doanh tùy vào hoạt động của công ty\n・Được khám sức khỏe định kỳ, nghỉ mát hàng năm, hoạt động team building\n・Được hưởng bảo hiểm theo chế độ nhà nước ban hành\n・Môi trường làm việc chuyên nghiệp, trẻ trung và thân thiện\n\nĐịa điểm làm việc\n- Hà Nội: Tòa ICON4, số 243A Đê La Thành, Láng Thượng, Đống Đa\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2389, 1274, 2, 'Java Developer', 'Mô tả công việc\nPhát triển, tối ưu và bảo trì các hệ thống backend sử dụng Java Spring Boot.\nThiết kế và triển khai các API phục vụ frontend và mobile app.\nTham gia phân tích yêu cầu và đề xuất giải pháp kỹ thuật.\nTối ưu hiệu suất hệ thống, xử lý lỗi và các tình huống bất thường.\nLàm việc với Redis, Kafka trong các hệ thống realtime, phân tán là một lợi thế lớn.\nPhối hợp với các thành viên team BA, QA, DevOps để đảm bảo chất lượng và tiến độ dự án.\n\nYêu cầu ứng viên\nCó trên 3 năm kinh nghiệm phát triển ứng dụng backend với Java Spring Boot.\nThành thạo RESTful API, OOP, và mô hình MVC.\nKinh nghiệm với cơ sở dữ liệu quan hệ (MySQL, PostgreSQL) và NoSQL là điểm cộng.\nƯu tiên có kinh nghiệm làm việc với:\nRedis (caching, pub/sub...)\nApache Kafka (message broker, event-driven architecture)\nNắm vững Git và quy trình làm việc Agile/Scrum.\nTinh thần học hỏi, chủ động và trách nhiệm trong công việc.\nTốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các lĩnh vực liên quan.\nƯu Tên nhận việc luôn.\n\nQuyền lợi\nMức lương cạnh tranh: up to 25M gross, review 2 lần/năm.\nLộ trình thăng tiến rõ ràng, hỗ trợ phát triển kỹ năng chuyên sâu.\nMôi trường làm việc năng động, thân thiện, có cơ hội học hỏi từ các dự án thực tế.\nTham gia BHXH, BHYT, các hoạt động teambuilding, du lịch cùng công ty.\nThời gian làm việc: Thứ 2 – Thứ 6, nghỉ T7 & CN.\n\nĐịa điểm làm việc\n- Hà Nội: Số 1 Trần Hữu Dực, Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2390, 227, 2, '.NET Backend Engineer (Senior), StoreFront ECommerce Platform', 'ABOUT THE ROLE\nJoin our Technology Innovations Center of Excellence (CoE) at Crossian, a fast-growing startup that achieved a milestone of $100M in 2024. In this dynamic role, you\'ll check in daily with your team to stay aligned on project goals and collaborate across our ecosystem with an Agile mindset infused with a unicorn-worthy startup culture.\n\nWHAT YOU WILL DO\n- Participate in Technical Specification & Test Cases in the Agile/Scrum development process\n- Develop clean, scalable code using .NET Core in Micro-service Architecture & Cloud-native\n- Develop backend Data-storage & Data-flows with Postgres, ES, Kafka and various Cloud data toolsets\n- Test and deploy system (micro-)services & (micro-)apps on AWS EKS/Kubernetes with Docker toolset\n- Improve existing system: revising, updating, refactoring and debugging code\n- Monitor and optimize system performance, addressing any issues as they arise.\n- Develop documentation throughout the software development life cycle (SDLC)\n- Serve as an expert on the system and provide technical support to other Internal teams.\n\nWHAT WE ARE LOOKING FOR\n- Bachelor’s degree in computer programming, computer science, or a related field\n- At least 3+ years of development experience\n- Proficient in backend technologies: C#, .NET, .NET Core, ASP.NET Core, Entity Framework Core, LINQ\n- Proficient in Relational database modeling & design with Postgres/MSSQL\n- Knowledge of Microservices, Clean-code, Clean-Architecture & SOLID principles\n- Having experience in Message Queues with Kafka/RabbitMQ\n- Having experience with Docker, Kubernetes\n- Understanding of Agile/Scrum methodologies\n- English Professional working proficiency\n\nPreferred (but not required)\n- Document DB modeling & design with Elasticsearch\n- Object Storages with AWS S3\n- Messaging with Sendgrid, Twilio, AWS SNS,...\n- Having experience in Cloud Native Computing\n- DevOps, SysOps in AWS and Git CI/CD experience\n\nWHAT YOU CAN EXPECT\nWhy Join Us?\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\n\nExceptional Compensation\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total annual compensation $55,000, reflecting your expertise and contribution.\n- Full salary during probation & Guaranteed 13th month salary\n- 12 days work-from-home & 12 days of paid annual leave, plus seniority paid leave\n- Global health insurance package for yourself and direct family members, plus annual health checkup\n\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\n\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\n\nIn addition to development tasks, you’ll collaborate closely with other CoEs to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.\n\nĐịa điểm làm việc\n- Hà Nội: 65 Ngô Thì Nhậm, Hai Bà Trưng\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2391, 1222, 2, 'Kỹ Sư Thiết Kế Lập Trình CNC', '- Bóc tách chi tiết phần gia công cho từng bản vẽ, lên quy trình công nghệ, tính toán phương án gia công;\n- Sử dụng phần mềm chuyên dụng thực hiện lập trình gia công các chi tiết, sản phẩm đảm bảo phù hợp với các thông số kỹ thuật của máy CNC;\n- Sử dụng 1 trong các phần mềm vẽ 3D (NX, Solidword, Mastercam...) để thiết kế đồ gá, jig gá phục vụ sản xuất;\n- Kịp thời chỉnh sửa bản vẽ lập trình khi phát hiện sai sót;\n- Thực hiện các công việc khác theo sự phân công của cấp Quản lý.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học; ưu tiên các chuyên ngành kỹ thuật: Cơ khí, Cơ điện tử, Tự động hóa và các chuyên ngành có liên quan;\n- Có ít nhất 1 năm về thiết kế, lập trình máy CNC trở lên; am hiểu IATF & kinh nghiệm về ngành ô tô là 1 lợi thế;\n- Sử dụng tiếng Anh trong công việc là một lợi thế;\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, JIH, ... chuyên về sản xuất nhôm định hình;\n- Có trách nhiệm, chịu khó, chủ động, cải tiến trong công việc.\n\nQuyền lợi:\n- Mức thu nhập khởi điểm sau khi tiếp nhận chính thức từ khoảng 13 triệu đến 20 triệu đồng (Có thể thỏa thuận với trường hợp ứng viên vượt trội về năng lực/kinh nghiệm);\n- Lương tháng 13 + thưởng hiệu quả kinh doanh sản xuất, thưởng Lễ, Tết...;\n- Môi trường làm việc an toàn, chuyên nghiệp, thân thiện (áp dụng hệ thống Quản lý chất lượng/ Quản lý môi trường theo tiêu chuẩn ISO 9001/ ISO 14001/ IATF 16949 và phương pháp 5S, Kaizen);\n- Cơ hội được đào tạo chuyên môn, kỹ năng làm việc; nhiều cơ hội phát triển, thăng tiến;\n- Được đóng BHXH, BHYT, ngày nghỉ phép năm theo quy định;\n- Được hưởng các chế độ phúc lợi; thưởng các dịp Lễ, Tết theo quy định của Công ty; thưởng sáng kiến, thưởng nhân viên của năm...;\n- Được tham gia các hoạt động do Công ty tổ chức: du lịch, teambuilding...;\n- Được cấp phát đồng phục làm việc theo tiêu chuẩn Công ty;\n- Khám sức khỏe định kì tại các cơ sở uy tín;\n- Phụ cấp ăn trưa tại Nhà máy và một số phụ cấp khác theo quy định của Công ty;\n- Công ty có xe đưa đón nhân viên theo tuyến Hà Nội - Bắc Ninh và Bắc Giang – Bắc Ninh.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2392, 1173, 2, 'Technical Leader', 'Mô tả công việc\nTiên phong nghiên cứu và ứng dụng các công nghệ, kỹ thuật mới nhằm nâng cao năng lực kỹ thuật của đội ngũ và chất lượng sản phẩm.\nPhân tích yêu cầu dự án, từ đó đưa ra các tư vấn, đề xuất, đánh giá và triển khai giải pháp kỹ thuật phù hợp cho khách hàng và đội dự án.\nXây dựng công cụ, hệ thống và giải pháp kỹ thuật nhằm tối ưu hiệu suất làm việc và nâng cao chất lượng đầu ra.\nMentor, hỗ trợ và định hướng thành viên trong việc giải quyết các vấn đề kỹ thuật trong dự án.\nTham gia tuyển dụng, đào tạo nhân sự mới và tổ chức các chương trình nâng cao kỹ năng kỹ thuật cho các thành viên trong team.\nTư vấn và định hướng kỹ thuật, xây dựng lộ trình phát triển cá nhân cho các thành viên; đồng hành và hỗ trợ trong quá trình phát triển đó.\nChia sẻ kiến thức, tổ chức các buổi chia sẻ công nghệ nội bộ, lan tỏa văn hóa học hỏi và phát triển liên tục trong team.\n\nYêu cầu ứng viên\nCó kinh nghiệm phân tích và thiết kế hệ thống, bao gồm thiết kế cơ sở dữ liệu (DB Design), thiết kế tổng thể và chi tiết (Basic Design, Detail Design), sử dụng các công cụ và phương pháp như UML.\nThành thạo các best practices trong lập trình như Clean Code, Design Patterns và các kiến trúc hệ thống nền tảng.\nCó kinh nghiệm lập trình full-stack với một trong các ngôn ngữ như JavaScript hoặc PHP.\nKỹ năng tổ chức và lãnh đạo tốt, từng đảm nhiệm vai trò quản lý và dẫn dắt nhóm phát triển phần mềm.\nAm hiểu về server, hệ thống cloud (là một lợi thế).\nCó khả năng tổ chức, sắp xếp công việc một cách khoa học và chịu được áp lực cao trong công việc.\nKỹ năng giao tiếp tốt, có tinh thần chia sẻ, yêu thích việc lan tỏa kiến thức tới đồng nghiệp.\nTư duy logic tốt, có khả năng phân tích và giải quyết vấn đề một cách hiệu quả.\n\nQuyền lợi\nMức lương: Upto 50TR\nNói KHÔNG với chậm lương, nợ lương.\nReview lương 02 lần/năm\nTối thiểu 13 tháng lương, thưởng theo hiệu quả công việc) và các khoản hỗ trợ khác\nThưởng các ngày lễ: 30/4, 2/9, Tết Dương Lịch. Quà sinh nhật công ty, quà sinh nhật cá nhân,...\nHưởng 15 ngày nghỉ phép nguyên lương/năm\nTham gia miễn phí các khóa học đạo tạo nội bộ do công ty thiết kế, tổ chức.\nTham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động Việt Nam\nKhám sức khỏe định kì tại các bệnh viện uy tín (Hồng Ngọc, Thu Cúc, ...)\nDu lịch hè 1-2 lần/năm, trợ cấp team-building cá nhân định kỳ hàng quý\nĐọc sách miễn phí tại thư viện sách của Công ty\nThời gian làm việc: Từ 8h00 đến 17h00, nghỉ Thứ Bảy và Chủ Nhật\n\nĐịa điểm làm việc\nHà Nội: Tầng 22, tháp B, tòa nhà Sông Đà (HH4), Đường Phạm Hùng, Phường Mỹ Đình 1, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2393, 1275, 2, 'Nhân Viên IT', '1. Manage and maintain the company\'s network systems, servers, computers, and peripheral devices. 2. Support and administer Odoo software, troubleshoot issues, and optimize its usage. 3. Install, configure, and troubleshoot hardware, office software, and operating systems. 4. Ensure system security, perform data backup, and restore data when necessary. 5. Assist and guide employees in using computers and office software effectively. 6. Manage printers, cameras, and other office equipment. 7. Perform other tasks as assigned by superiors.\n\nYêu cầu ứng viên\n\n- Graduated from College or University in Information Technology, Computer Networks, or related fields. - At least 2 year of experience in IT hardware; experience in managing Odoo software is a plus. - Proficient in troubleshooting hardware, software issues, and network security. - Able to read and understand technical documents in English and communicate at a basic level. - Male candidates preferred; proactive, responsible, and disciplined. - Strong teamwork and independent working skills; ethical and self-motivated. - Responsible for all IT-related tasks in the company.\n\nQuyền lợi\n\n1. Opportunity for high development for individuals who are truly capable of working in accordance with the support of the company. 2. Ensure compliance with the regulations of the State: social insurance, health insurance, 13th month salary.\n\nĐịa điểm làm việc\n\n- Bình Dương: Lô E2, KCN Đồng An, Bình Hòa, Thuận An.\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00). Monday to Friday and alternative Saturday (during 2-month probation, full Saturday is required).\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2394, 485, 2, 'Frontend Developer (ReactJS/NextJS)', 'Mô tả công việc\n- Xây dựng, phát triển và tối ưu giao diện người dùng (ưu tiên ứng viên mạnh ReactJS, NextJS).\n- Thiết kế và phát triển hệ thống base frontend, xây dựng thư viện component và module có khả năng tái sử dụng.\n- Phát triển các tính năng như đăng nhập, đăng ký, quản lý tài khoản, trình phát video, quản lý thông tin, tích hợp thanh toán online (momo, vnpay),...\n- Phối hợp chặt chẽ với backend team để tích hợp API, đảm bảo tính đồng bộ và ổn định cho hệ thống.\n- Debug, khắc phục lỗi, tối ưu hiệu năng và đảm bảo chất lượng thông qua kiểm thử kỹ lưỡng.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc liên quan.\n- Có kinh nghiệm phát triển frontend từ 3 năm trở lên (ReactJS và NextJS).\n- Thành thạo:\n  + ƯU TIÊN CÓ THỂ ĐI LÀM NGAY SAU KHI NHẬN ĐƯỢC OFFER.\n  + ReactJS: Hooks, React Hook Form + Yup, Redux/Zustand/Context API/React Query, React-dnd (drag-drop), Axios/fetch, TailwindCSS, upload file, xử lý JWT...\n  + NextJS: App Router hoặc SSR/SSG (getServerSideProps), dynamic routing, middleware auth, lazy loading, Next Image, SEO tối ưu\n  + JavaScript/TypeScript (ES6+), HTML5, CSS3.\n  + Xây dựng giao diện responsive.\n- Có khả năng thiết kế và xây dựng các components/modules có thể tái sử dụng chất lượng cao.\n- Có khả năng làm việc độc lập, xây dựng được nền tảng base cho website, tối ưu hiệu năng.\n- Có khả năng tự chủ động cập nhật công nghệ mới nhanh và có trách nhiệm cao.\n- Có kinh nghiệm với Video.js, HLS.js hoặc công nghệ trình phát video tương tự.\n- Biết về WebRTC, CDN tối ưu hóa streaming video.\n- Hiểu biết về bảo mật frontend và tối ưu hiệu năng.\n- Kinh nghiệm xây dựng dashboard/admin panel.\n\nQuyền lợi\n- Lương 16-22 triệu.\n- Thưởng tháng 13, theo kết quả kinh doanh.\n- 14 ngày nghỉ phép 1 năm (sinh nhật, lễ giáng sinh).\n- Bảo hiểm xã hội, sinh nhật, hiếu hỉ, quà tặng lễ tết.\n- Làm việc linh hoạt giờ giấc.\n- Trà chiều mỗi ngày.\n- Review lương định kỳ 2 lần/năm (tùy theo năng lực).\n- Môi trường làm việc năng động.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 37 Cao Lỗ Phường 4, Quận 8\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nToàn thời gian nhưng linh động và thoải mái\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2395, 1276, 2, 'Nhân Viên Lập Trình PHP', 'Mô tả công việc\n- Phát triển và bảo trì hệ thống backend bằng PHP và Laravel.\n- Thiết kế, tối ưu cơ sở dữ liệu và API phục vụ frontend.\n- Hỗ trợ và phối hợp với đội frontend để xây dựng các tính năng mới.\n- Tối ưu hiệu suất hệ thống, xử lý lỗi và nâng cao bảo mật.\n\nYêu cầu ứng viên\n- Giới tính: Nam\n- Bằng cấp: Đại Học\n- Thành thạo PHP, HTML, CSS, JavaScript, jQuery, Bootstrap.\n- Ít nhất 2 năm kinh nghiệm làm việc với Laravel.\n- Có kinh nghiệm làm việc với cơ sở dữ liệu MySQL hoặc PostgreSQL.\n- Hiểu biết về RESTful API, WebSocket là một lợi thế.\n- Có kinh nghiệm làm việc với dữ liệu lớn, biết phân tích hệ thống.\n- Có kinh nghiệm làm việc với các hệ thống bán hàng, CRM là một lợi thế.\n- Khả năng làm việc nhóm tốt, tư duy logic và giải quyết vấn đề.\n\nQuyền lợi\n- Mức lương khởi điểm hấp dẫn (từ 15.000.000 đến 25.000.000 VND) đàm phán theo năng lực và mong muốn của ứng viên.\n- Thưởng định kỳ và xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc.\n- Được tham gia 2 gói bảo hiểm: BHXH, BHYT, BHTN theo quy định pháp luật.\n- Bảo hiểm chăm sóc sức khỏe cho cá nhân và người thân (OWS Care).\n- Được khám sức khỏe định kỳ hàng năm.\n- Có cơ hội tiếp xúc, học hỏi những công nghệ tiên tiến qua các dự án mới của công ty.\n- Được hưởng đầy đủ các chế độ phúc lợi khác như: thưởng dự án, thưởng lễ Tết, liên hoan, sinh nhật, teambuilding, nghỉ mát, gala.\n- Weekly Techtalks trao đổi, chia sẻ về các công nghệ mới nhất; là cơ hội để các thành viên học hỏi lẫn nhau.\n\nĐịa điểm làm việc\n- Hà Nội: 14 Nguyễn Cảnh Dị, Đại Kim, Hoàng Mai, Hoàng Mai.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2396, 1250, 2, 'Senior Fullstack Developer (ReactJs + NodeJs)', 'OUR TECH STACK:\n\nBackend:\n- Node.js, ExpressJs\n- RabbitMQ / Kafka / MSSQL / PostgreSQL / Redis / Elasticsearch\n- Docker / Kubernetes / Jenkins\n\nFrontend:\n- React.js / React Native\n- ES6 / Typescript\n- Redux / Redux-Saga / Hooks\n\nRESPONSIBILITIES:\n- Design, code, and review scalable, maintainable software solutions that align with business and system architecture.\n- Identify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\n- Collaborate across squads (frontend, backend, QA…) to share knowledge, align on best practices, and mentor junior team members.\n- Take ownership of features or systems; lead projects or squads when needed, ensuring delivery quality and guiding technical direction.\n\nYêu cầu ứng viên:\n\nMust-Have:\n- Proactive problem-solver with a bias toward action and ownership. Quick to pick up new frameworks, libraries, and tooling as the stack evolves.\n- At least 4 years of real-world experience in software development.\n- Familiarity with macOS or Linux for development and deployment tasks.\n- Hands-on experience or working knowledge in our core stack is required; full expertise in one side (FE or BE) is acceptable:\n- Backend: Node.js, PostgreSQL, Redis, Elasticsearch.\n- Frontend: React.js, Redux, Redux-Saga, Reselect, React Hooks.\n- Commitment to code quality: Strong experience in code reviews.\n- Familiarity with unit testing best practices.\n- Growth mindset: Ready to grow rapidly as the company scales several times a year.\n\nNice-to-Have (Plus):\n- Deep understanding of Webpack, including code splitting, asset optimization, and custom configurations.\n- Strong foundation in computer science: Data structures, algorithms, design patterns.\n- Experience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\n- Familiarity with microservices architecture.\n\nQuyền lợi\n\n- Competitive Compensation & Bonuses\n- Attractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n- 100% salary during the probation period.\n- 13th-month salary to ensure financial stability.\n- Performance reviews twice a year with opportunities for salary adjustments.\n- Flexible Work & Growth Opportunities\n- Hybrid working model: Work from home or at the office as needed.\n- Work alongside top CTOs, architects, and tech leaders at Vexere.\n- Build your public profile through: Publishing articles on Medium & Vexere Techblog under your name.\n- Contributing to Open Source projects managed by Vexere.\n- Speaking at tech talks and industry events.\n- Attractive stock options for dedicated developers and team leads.\n\nExclusive Employee Perks\n\n- Up to 30% discount on bus tickets for Vexere employees and their families.\n- 12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\n- Vibrant and dynamic work environment with a friendly, supportive team.\n- Training sessions on negotiation, communication, work management, interpersonal skills, and software technology.\n- Exciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: 384 Hoang Dieu, Ward 6, Quận 4\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2- Thứ 6, Sáng thứ 7\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2397, 1277, 2, 'Fullstack Engineer', 'Mô tả công việc:\n- Phát triển và duy trì ứng dụng web bằng ReactJS, NextJS và NodeJS.\n- Hợp tác với product team và backend để phát triển sản phẩm đầu tư hiệu quả và dễ sử dụng.\n- Xây dựng hệ thống web có khả năng mở rộng, bảo mật và hoạt động ổn định trên hạ tầng AWS.\n- Tối ưu hóa hiệu năng, bảo mật và trải nghiệm người dùng.\n- Viết mã chất lượng, tài liệu đầy đủ, tham gia code review và chia sẻ kiến thức trong nhóm.\n- Làm việc trong môi trường Agile, cải tiến sản phẩm liên tục.\n\nYêu cầu ứng viên:\n- Ít nhất 5 năm kinh nghiệm phát triển phần mềm, đặc biệt với ReactJS, NextJS, NodeJS.\n- Kinh nghiệm làm việc với AWS (EC2, S3, Lambda, RDS, API Gateway).\n- Ưu tiên có hiểu biết về các API tài chính/đầu tư.\n- Nắm rõ các nguyên tắc bảo mật trong môi trường fintech.\n- Tư duy logic tốt, chủ động, đam mê với công nghệ tài chính.\n\nQuyền lợi:\n- Làm việc cùng đội ngũ xây dựng nền tảng công nghệ đầu tư thế hệ mới.\n- Thu nhập cạnh tranh và thưởng theo hiệu quả công việc.\n- Môi trường linh hoạt, cởi mở và hỗ trợ sáng tạo.\n- Cơ hội phát triển năng lực kỹ thuật và vai trò quản lý.\n- Văn hóa đồng đội, học hỏi và phát triển liên tục.\n\nĐịa điểm làm việc:\n- Hà Nội: Trung tâm đổi mới sáng tạo quốc gia, tòa NIC, số 6, ngõ 7 Tôn Thất Thuyết, Dịch Vọng, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Thứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2398, 1278, 2, 'Backend Developer', 'Mô tả công việc\nProject information:\nDevelop a large scalable website to provide Cloud Hosting service across Asia based on microservices architecture and AWS services.\nDevelop web apps for Cloud Hosting management systems.\nDevelop other management systems based on our core services\nProject\'s tools & technologies:\nNodeJS\nNestJS\nDevOps CI/CD\nAgile, GitLab\nDocker\nAWS\nPostgreSQL, MySQL, MongoDB, Redis Angular\n\nYêu cầu ứng viên\nYour Skills and Experience:\nAt least 3 years of experience.\nDemonstrated design and programming skills using NodeJS, Typescript, JSON, Web Services\nExperience with databases (MySQL, MongoDB)\nExcellent experience in designing and implementing database systems with integrity, scalability, performance, reliability, security in mind\nHuge plus if you are/have:\nExcellent fullstack developer\nExperience with Nest.js\nExcellent understanding of backend development best practices and standards\nImpeccable leadership skills and able to drive solutions\nExcellent understanding of CI/CD\nExcellent experience designing and developing backend microservices\n\nQuyền lợi\nBenefits as below:\nAttractive salary\nA professional and friendly working environment\nLaptop + LCD for working\n13th-month salary\nPerformance bonus\nPrivate Healthcare insurance\nBonus for all holidays\nAnnual company trip\nAnnual leave: 12 days per year\nTechnical training\nSnack and beverage daily, monthly team dinner\nYear end party\nBonus and leaves for wedding/funeral/newborn baby/sickness\nReferral bonus\n\nĐịa điểm làm việc\n- Cần Thơ: Ninh Kiều\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cần Thơ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2399, 68, 2, 'Frontend Developer', 'Mô tả công việc\n- Use best practices and technologies to develop large SPAs for various users and platforms.\n- Ensure high-quality, performant, and reusable code.\n- Perform benchmarking, performance, and security analysis.\n- Work closely with the backend teams and product design team to iterate quickly on new features and experiments.\n- Accurately translate user and business needs into functional front-end code.\n- Drive the efficient delivery of change through analysis, definition, and documentation of requirements whilst identifying potential solutions using agile delivery frameworks.\n- Solve complex technical and business problems and learn new technology and frameworks.\n- Be part of a team that will take full responsibility for the features you own.\n- Design, develop, test, deploy, monitor, and improve; you are responsible for the entire lifecycle of your product – build it, own it.\n\nYêu cầu ứng viên\nMust Have:\n- 3++ years of experience programming with HTML, CSS, JavaScript, ReactJS.\n- Experience in responsive web and mobile-first applications.\n- Experience with ReactJS, and its ecosystem (Hooks, Context, Redux, Redux Saga, State Management libraries...)\n- Familiar with CSS Frameworks like Material UI, TailwindCSS, Ant Design,...\n- Familiarity with RESTful APIs and asynchronous request handling for partial page updates.\n- Be able to write clean, performance-centric, reusable, and understandable code with unit tests.\n- Familiarity with browser testing and debugging.\n- Hands-on experience with Git.\n- Be structured, solution-oriented, own quality mindset, good problem-solving skills, eagerness to learn, and curiosity.\n- Have good communication skills, have experience with technical coaching and mentoring work.\n- Good command of English (Listening, Reading, Writing).\n\nNice to Have:\n- Previous product company experience.\n- Experience in building mobile application by React Native.\n- Familiar with Agile development methods, especially Scrum.\n- Familiarity with ECMAScript 6, TypeScript.\n- Experience in building JavaScript SDKs, Web Widgets, and unit testing.\n- Expertise in web optimization, security, and user behavior tracking.\n- Experienced in unit tests, automated test frameworks is a plus.\n- Experience with micro-frontend is a plus.\n- Good understanding on how browser rendering works and provide various frontend rendering optimization strategies.\n- Familiarity with UI/UX design principles.\n- Awareness of best practices in UI/UX design and development to ensure optimal user experience.\n\nQuyền lợi\n- Salary for Position 3P: 20M+++ VND/month;\n- Bonus for Position 4:\n- End-of-year bonus (depending on the company\'s business performance at the time;\n- Benefits: Welfare package of 10,500,000 VND/year, Employee welfare policies.\n- Performance bonuses for creativity, achievements, and other types of rewards;\n- Social Insurance and other regimes according to regulations;\n- Participating in training courses according to your requirements;\n- Working in a professional, creative and open-minded environment with many job advancement opportunities;\n- Working time: From 8:45 AM to 6:00 PM, Monday to Friday, at the office. On alternating Saturdays, work is flexible and can be done either remotely or on-site.\n- Working place: 15th floor, Ngoc Khanh Plaza Building - No.1 Pham Huy Thong, Ngoc Khanh Ward, Ba Dinh District, Hanoi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2400, 1279, 2, 'Lập Trình Viên Python', 'Mô tả công việc: Giao tiếp trao đổi với khách hàng bằng tiếng anh để nắm rõ yêu cầu. Thực hiện công việc sử dụng ngôn ngữ Python, HTML/CSS, MongoDB. Hỗ trợ khách hàng trong việc triển khai và tối ưu hóa ứng dụng.\n\nYêu cầu ứng viên: Tốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT hoặc các ngành liên quan. Có kiến thức/kinh nghiệm Python (Jinja2) trên 6 tháng. HTML/CSS cơ bản. Có kiến thức/kinh nghiệm làm việc với low code. Có ít nhất 1-4 năm kinh nghiệm làm việc trong lĩnh vực cấu hình ứng dụng, triển khai hệ thống. Tiếng Anh giao tiếp thành thạo (bắt buộc). Kỹ năng giao tiếp, thuyết trình và đào tạo tốt. Có khả năng làm việc độc lập và theo nhóm. Ưu tiên ứng viên có kinh nghiệm làm việc với khách hàng quốc tế.\n\nQuyền lợi: Được đào tạo bài bản về sản phẩm và kỹ năng chuyên môn. Làm việc trực tiếp với khách hàng tại nhiều quốc gia khác nhau, cơ hội đi onliste Philippines/Hong Kong mỗi tháng từ 3-5 ngày nếu có yêu cầu từ khách hàng. Mức lương hấp dẫn, có bonus khi kết thúc hợp đồng. Cơ hội làm việc trong môi trường chuyên nghiệp, năng động và quốc tế. Hỗ trợ chi phí đi lại, ăn ở trong thời gian công tác nước ngoài. Các chế độ phúc lợi khác theo quy định của công ty.\n\nThông tin thêm: Ứng viên sẽ được đào tạo 2 tháng tại Hồ Chí Minh trước khi bắt đầu công tác nước ngoài. Công ty sẽ hỗ trợ xin visa du lịch cho ứng viên (không yêu cầu visa lao động).\n\nĐịa điểm làm việc: Hồ Chí Minh: Phước Long B, Thủ Đức.\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2401, 1280, 2, 'Lập Trình Viên Backend / Backend Developer', 'Mô tả công việc\n- Xây dựng hệ thống backend cho game thể loại Fantasy và hệ thống Livestreaming.\n- Xây dựng tài liệu thiết kế, tài liệu kiến trúc của sản phẩm.\n- Đề xuất các giải pháp công nghệ, công cụ áp dụng trong phát triển sản phẩm.\n- Phối hợp cùng các thành viên trong nhóm trong quy trình phân tích thiết kế, review code và support các member khác.\n- Phân tích yêu cầu dự án, lên kế hoạch phát triển sản phẩm.\n- Nghiên cứu và ứng dụng các công nghệ, công cụ mới, đặc biệt là các công cụ hỗ trợ phát triển bằng AI, để tối ưu hóa quy trình làm việc và nâng cao chất lượng sản phẩm.\n- Báo cáo tiến độ công việc cho PO/PM.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT.\n- Có ít nhất 3 năm kinh nghiệm làm việc với Javascript/Typescript hoặc Python.\n- Nắm vững các kiến thức về Network, giao tiếp giữa Client và Server.\n- Hiểu biết sâu về tích hợp API, GraphQL, WebSocket và cách ứng dụng nó trong các ứng dụng real time.\n- Thành thạo cấu trúc dữ liệu và cơ sở dữ liệu: MySQL/MongoDB/PostgreSQL.\n- Kinh nghiệm trong việc phân tích yêu cầu và đưa ra giải pháp kỹ thuật.\n- Có khả năng thực hiện code review và đảm bảo chất lượng phần mềm (QA/QC).\n- Kỹ năng phối hợp làm việc với BA, Tester, PM/PO, QA và Khách Hàng.\n- Ðã từng thiết kế hoặc tham gia thiết kế ứng dụng/sản phẩm CNTT.\n- Có kiến thức về bảo mật phần mềm và tối ưu hóa hiệu suất ứng dụng.\n- Có tinh thần lãnh đạo bản thân (trách nhiệm, trung thực, học hỏi liên tục).\n- Ưu tiên ứng viên có kiến thức về Microservices, Docker, K8s, DevOps, GitOps.\n\nQuyền lợi\n- Mức lương thương lượng theo kinh nghiệm, lên đến 45,000,000 VND Gross/tháng.\n- Các chế độ khác theo đúng quy định pháp luật.\n- Xét tăng lương hàng năm.\n- 12 ngày phép/ năm và các ngày nghỉ lễ theo quy định.\n- Cơ hội tham gia dự án tiềm năng với khả năng phát triển lâu dài.\n- Môi trường làm việc linh hoạt, hỗ trợ học hỏi và tiếp cận công nghệ hiện đại.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 15, tòa nhà văn phòng Discovery Complex, 302 Cầu Giấy, P.Quan Hoa, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2402, 237, 2, 'Fullstack Dev', 'ICORP là công ty đang có nhiều sản phẩm phục vụ doanh nghiệp như: Hoá đơn điện tử, Chữ ký số, Phần mềm kê khai bảo hiểm xã hội (ivan), Hợp đồng điện tử,....\n\n- Tham gia lập trình, vận hành, tối ưu các sản phẩm của công ty.\n- Thiết kế các tương tác của người dùng trên các trang web.\n- Tích hợp với các dịch vụ của đối tác, đề xuất và phát triển các tính năng mới...thể hiện kỹ năng và sự sáng tạo của mình\n- Thực hiện các công việc khác từ cấp trên\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin, hoặc tương đương.\n- Kinh nghiệm: từ 3 năm ở vị trí tương đương.\n- Thành thạo quy trình phát triển phần mềm, từ tiếp nhận yêu cầu, lựa chọn công cụ, ngôn ngữ, thiết kế CSDL, xây dựng frontend, backend, triển khai lên hệ thống server thật.\n- Thành thạo ngôn ngữ lập trình Javascript, CSS, HTML và một framework xây dựng frontend như ReactJS hoặc Angular, biết cách xây dựng website responsive chạy trên mobile.\n- Thành thạo một framework xây dựng backend như NodeJS Express, ngôn ngữ SQL, biết cách sử dụng ORM và vận hành hệ quản trị CSDL như MySQL hoặc Postgres.\n- Biết sử dụng các API và thiết kế API để tương tác với các dịch vụ của khách hàng.\n- Biết đọc tài liệu bằng tiếng anh.\n- Biết phát triển ứng dụng mobile (ReactNative) là một lợi thế.\n- Kỹ năng làm việc độc lập và làm việc nhóm tốt để giải quyết các vấn đề liên quan đến sản phẩm.\n\nQuyền lợi:\n- Mức lương: Thỏa thuận theo năng lực.\n- Môi trường thoải mái, năng động linh hoạt, phát huy đối đa năng lực.\n- Chế độ bảo hiểm: BHXH, BHYT, BHTN đầy đủ theo quy định của nhà nước.\n- Thưởng đa dạng: Thưởng tháng 13, thưởng Lễ/Tết, thưởng kinh Doanh cuối năm, nhân viên xuất sắc, thâm niên,....\n- Thời gian làm việc: Từ thứ 2 – hết sáng thứ 7; 8h30 -18h00.\n- Tham gia các hoạt động: Sự kiện, hội nghị, hội thảo về Công nghệ...\n- Hoạt động du lịch, nghỉ mát.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 5, tòa nhà SanNam, 78 Duy Tân, Cầu Giấy, Cầu Giấy.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2403, 1261, 2, 'DEV-OPS ENGINEER', 'Mô tả công việc\n- Thiết kế, triển khai và bảo trì các pipeline CI / CD cho các ứng dụng của chúng tôi, bao gồm triển khai tự động, kiểm thử tự động và quản lý mã nguồn.\n- Xây dựng và bảo trì hệ thống và cơ sở hạ tầng bằng cách sử dụng các công nghệ mới nhất như Kubernetes, Docker, GitOps và Ansible.\n- Triển khai và quản lý ứng dụng trên các nền tảng đám mây như AWS, GCP hoặc Azure.\n- Phát triển các kịch bản tự động hóa và tiêu chuẩn hóa các quy trình triển khai và vận hành.\n- Hỗ trợ nhóm phát triển trong việc triển khai và cung cấp hỗ trợ cho các ứng dụng\n- Giám sát và quản lý hiệu suất của các hệ thống và cơ sở hạ tầng\n- Liên tục cải thiện và nâng cao chất lượng và độ tin cậy của các hệ thống và cơ sở hạ tầng\nYêu cầu ứng viên\n- Kinh nghiệm về thiết kế, triển khai và bảo trì các đường ống CI / CD và quản lý các ứng dụng trên các nền tảng đám mây.\n- Kinh nghiệm với các công nghệ như Kubernetes, Docker, GitOps và Ansible.\n- Hiểu biết về các nền tảng đám mây như AWS, GCP hoặc Azure.\n- Kinh nghiệm về quản lý cơ sở hạ tầng và hệ thống lớn, đảm bảo độ tin cậy và hiệu suất cao.\n- Kỹ năng giao tiếp và làm việc nhóm tốt\n- Kinh nghiệm trong lĩnh vực phát triển phần mềm hoặc quản trị hệ thống.\n- Kỹ năng lập trình với một hoặc nhiều ngôn ngữ như Python, Java, hoặc Go.\n- Kinh nghiệm với các công cụ quản lý mã nguồn như Git và các nền tảng như GitHub hoặc GitLab.\n- Hiểu biết về các cơ chế bảo mật và kiểm soát truy cập, đảm bảo an toàn cho hệ thống và ứng dụng.\n- Sẵn sàng học hỏi và áp dụng các công nghệ mới nhất để cải thiện hiệu suất và độ tin cậy của hệ thống và ứng dụng.\n- Năng động, sáng tạo và có tư duy logic tốt.\n- Tiếng Anh đọc và viết tốt để có thể đọc tài liệu, tương tác.\nQuyền lợi\n- Làm việc tại công ty hàng đầu Việt Nam, luôn không ngừng phát triển với nhiều cơ hội thăng tiến bản thân.\n- Được đào tạo chuyên nghiệp, hoàn toàn miễn phí trước khi làm việc.\n- Môi trường làm việc trẻ, năng động và thân thiện.\n- Tham gia đầy đủ các chế độ BHYT, BHXH, BHTN.\n- Thu nhập hấp dẫn, phù hợp năng lực bản thân.\n- Lương tháng 13 và thưởng theo hiệu quả kinh doanh.\n- Khám sức khỏe định kỳ.\n- Thường xuyên tổ chức các chương trình hội thao, hội diễn văn nghệ, tân niên, tất niên…\nĐịa điểm làm việc\n- Hồ Chí Minh: 67 Hoàng Văn Thái, Quận 7\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2404, 1281, 2, 'Nhân Viên Lập Trình Máy CNC', '- Nhận bản vẽ và lên kế hoạch gia công\n- Làm chương trình cho máy CNC hoạt động.\n- Kiểm tra chất lượng đầu ra sản phẩm\n- Báo cáo các vấn đề liên quan trong quá trình làm việc\n- Thời gian làm việc: chuyên làm ngày. Hoặc làm theo ca\n- Bóc Tác bản vẽ, kê phôi gia công\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học, Cao đẳng, Trung cấp chuyên ngành cơ khí chế tạo.\n- Hiểu biết ngôn ngữ lập trình máy CNC.\n- Có kinh nghiệm lập trình máy CNC từ 1 năm trở lên.\n- Bắt buộc sử dụng thành thạo 1 trong các phần mềm CAM.\n- Ưu tiên người đã có kinh nghiệm làm việc ở các công ty sản xuất jig, đồ gá, Khuôn mẫu\n\nQuyền lợi\n- Lương cơ bản: Từ 10- 12 triệu.\n- Được tham gia bảo hiểm theo quy định của Pháp luật.\n- Thưởng và các chế độ khác theo Luật lao động và quy định của công ty.\n- Chế độ nghỉ mát hàng năm;\n- Môi trường làm việc chuyên nghiệp, thân thiện;\n- Có cơ hội thăng tiến\n- Giờ làm việc: 8:00 – 17:00 thứ 2 đến thứ 7\n\nĐịa điểm làm việc\n- Bắc Ninh: KCN Visip, Từ Sơn\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2405, 1282, 2, 'Lập Trình Viên Fullstack Developer', 'Mô tả công việc:\n- Lập trình và tích hợp (front-end và back-end);\n- Viết tài liệu mô tả chức năng phần mềm;\n- Xử lý phản hồi từ người dùng;\n- Nghiên cứu tối ưu hóa sản phẩm, dịch vụ đã phát triển;\n- Bảo trì và hỗ trợ các vấn đề liên quan đến chuyên môn.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành khác am hiểu về Lập trình;\n- Có khả năng research tài liệu và đọc tài liệu.\n- Có kinh nghiệm và sản phẩm là một lợi thế;\n- Có khả năng phân tích, sáng tạo, chịu được áp lực công việc; có tinh thần học hỏi, hợp tác trong công việc;\n- Làm việc ổn định tại Hà Nội\n\nFront-end:\n- Có kinh nghiệm lập trình Web Front-end sử dụng Angular/ReactJS/VueJS. sử dụng thành thạo Typescript, ES6, CSS3, HTML5, Node.js, NPM\n- Có kinh nghiệm phát triển và tích hợp RESTful APIs,\n- Kiến thức về UI/UX, Hiểu biết về Responsive Design và các kĩ thuật tối ưu hóa giao diện,\n- Đã từng dùng các liberary Ui như Boostrap, Antd design, Material, Argon, Jquery…vv\n- Làm quen với Redux, React Hook Form, NextJS, Thư viện thử nghiệm React\n\nBack-end:\n- Có kỹ năng lập trình về .NET Core (C#, ASP.NET Core), RESTful APIs, SOAP; EF Core\n- Có kinh nghiệm với các công cụ build hiện đại (Docker, CI/CD,...).\n- Kinh nghiệm với các công cụ quản lý mã nguồn như Git.\n- Database: SQL Server, Oracle, PostgreSQL;\n\nQuyền lợi:\n- Mức lương: từ 17 triệu - 25 triệu tùy theo năng lực và kinh nghiệm. Xét tăng lương định kỳ hàng năm hoặc trước hạn theo tình hình đánh giá;\n- Được hưởng các chế độ BHYT, BHXH theo quy định của nhà nước; các chính sách phúc lợi của Công ty: Phép năm; Lương thưởng; Quà tết, thưởng lễ; Du lịch...\n- Làm việc trong môi trường chuyên nghiệp, trẻ trung, năng động, hòa đồng, phát huy tối đa khả năng chủ động sáng tạo của nhân viên;\n- Được trang bị đầy đủ trang thiết bị phục vụ công việc;\n- Được trau dồi kỹ năng về nghiệp vụ và kỹ năng mềm;\n- Được tham gia, đóng góp vào các dự án phát triển có quy mô lớn, lâu dài;\n- Thưởng theo thành tích làm việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2406, 1131, 2, 'Nhân Viên Triển Khai Phần Mềm ERP', 'Mô tả công việc\n- Triển khai kho dữ liệu tích hợp với nguồn ERP cho khách hàng/doanh nghiệp nội bộ: phân tích nghiệp vụ, cấu hình hệ thống, hỗ trợ đào tạo và vận hành.\n- Trích xuất và xử lý dữ liệu từ hệ thống ERP để phục vụ mục đích báo cáo, phân tích, hoặc chuyển đổi hệ thống.\n- Phối hợp với team Data để chuẩn hóa dữ liệu, đồng bộ về hệ thống lưu trữ tập trung (Data Warehouse).\n- Tham gia vào các dự án dữ liệu cho khách hàng:\n  - Làm việc với dữ liệu tài chính, bán hàng, vận hành,... từ các hệ thống ERP\n  - Viết truy vấn SQL, làm sạch dữ liệu, xử lý ETL\n  - Học và áp dụng các công cụ như Airflow, dbt, BigQuery, v.v.\n  - Học và thực hành các kỹ thuật data engineering thông qua mentor nội bộ và dự án thực tế.\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Hệ thống thông tin, CNTT, Kinh tế, hoặc tương đương.\n- Có kiến thức cơ bản về quy trình nghiệp vụ doanh nghiệp (kế toán, mua bán, tồn kho…) \n- Đã từng làm việc với hệ thống ERP, phần mềm kế toán, hoặc có kinh nghiệm xử lý dữ liệu là lợi thế.\n- Biết SQL cơ bản, có tư duy logic, phân tích dữ liệu tốt.\n- Chủ động học hỏi, có định hướng rõ ràng trở thành Data Engineer trong thời gian ngắn.\nQuyền lợi\n- Mức lương cạnh tranh,\n- Lương tháng 13\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop….\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Khám sức khỏe định kỳ 1 lần/năm\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm\n- Làm việc với tác đối tác lớn\n- Review tăng lương định kỳ hàng năm\nĐịa điểm làm việc\n- Hà Nội: 19-21 Vũ Trọng Phụng, Thanh Xuân\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 00:00 đến 00:00)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2407, 1142, 2, 'Kotlin Developer (Fresher)', 'Develop and integrate Kotlin Multiplatform modules targeting Android and iOS\nDesign and implement clean, maintainable architectures (MVVM / Clean Architecture)\nBuild lightweight back-end services using Ktor\nManage database interactions with SQLDelight (or equivalent)\nLeverage Kotlin Coroutines & Flow for asynchronous processing\nConfigure and customize Compose Multiplatform (themes, navigation, multiplatform previews)\nCollaborate with mobile teams to share common code and handle native interop\n\nMust-Have Qualifications\nHands-on experience with Kotlin (Android development is a plus)\nSolid understanding of Kotlin Coroutines, Flow, and MVVM/Clean Architecture\nProficient in Ktor and SQLDelight (or similar frameworks)\nFamiliarity with code-sharing patterns in Kotlin Multiplatform (KMP)\nPractical knowledge of Compose Multiplatform (themes, navigation, previews)\n\nPreferred Skills\nExperience with Swift or native iOS development\nPrior exposure to deploying KMP projects in production or personal side-projects\nWorking knowledge of dependency injection and serialization libraries (e.g., Koin, Kotlinx.Serialization, Kermit)\nCI/CD pipeline setup and testing (unit tests, integration tests)\nNative interop expertise (expect/actual in KMP or Swift/Objective-C bridges)\nFamiliarity with Flutter or React ecosystems\n\n• Competitive salary package and specific benefits. You\'ll get a bonus of a half month salary If you are on board before October 1st\n• TET bonus from up to 4-month salary according to seniority, work results, and business situation of the company.\n• The company pays (32%) the costs of social insurance, health insurance, and unemployment insurance for its employees.\n• Performance review twice a year\n• Annual holiday: 12 annual leave and Corporate Birthday 11/27\n• Working in a dynamic and professional environment with many promotion opportunities.\n• Receive benefits according to seniority\n• Being trained in foreign languages, sponsored to learn certificates to improve professional skills and soft skills.\n• Lots of opportunities to go to Onsite at SPLUS JAPAN (for staff with Japanese proficiency from N3 and above)\n• Sports activities: Football\n• Annual company trip, team building, birthdays for employees in the month, and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas ...).\n• Time working: Monday – Friday (9:00 – 18:00).\n\n- Hồ Chí Minh: Tòa nhà HaDo Airport, 2 Hồng Hà, phường 2, Tân Bình\n\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2408, 1283, 2, 'Nhân Viên Lập Trình CNC - Phần Mềm Creo', '• Tiếp nhận bản vẽ, file chi tiết 3D, lập trình các chi tiết khuôn theo kế hoạch gia công hàng tháng, đảm bảo đúng kế hoạch gia công của tổ CNC.\n• Phụ trách lập trình cho các máy phay CNC đúng theo file 3D và bản vẽ thiết kế khuôn.\n• Kiểm soát quy trình và chương trình gia công để đảm bảo đúng tiến độ, tiêu chuẩn về kích thước, số lượng các chi tiết cần gia công trên máy CNC.\n• Phối hợp với Tổ trưởng và KTV. CNC kiểm soát quá trình gia công, kiểm tra kỹ thuật các khuôn được gia công.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2409, 556, 2, 'Backend Developer - Onsite', 'Mô tả công việc\n- Phát triển và nâng cấp hệ thống Website, WebApp theo yêu cầu khách hàng.\n- Phát triển các giải pháp về ERP(Enterprise Resource Planning), PLM (Product Lifecycle Management) cho các khách hàng là các công ty lớn ở Nhật.\n- Các giải pháp về tự động hóa công nghiệp, thông minh, quản lý và điều khiển hệ thống,dây chuyền sản xuất thông qua giao diện người dùng.\n- Địa điểm làm việc: Nagoya (Nhật Bản)\n- Nhận ứng viên ở cả Hà Nội , Đà Nẵng, Hồ Chí Minh.\n\nYêu cầu ứng viên\n- Tiếng Nhật tương đương với N3 trở lên (bắt buộc, nếu chưa có bằng thì yêu cầu trình độ giao tiếp tương đương level N3).\n- Tối thiểu 3 năm kinh nghiệm Web Developer (Backend).\n- Biết ít nhất về 1 front-end framework (Reactjs, ...).\n- Thành thạo ít nhất 1 trong các ngôn ngữ C#, JS, PHP.\n- Có tư duy về kiến trúc hệ thống web, có khả năng tối ưu tốc độ, số lượng users, request.\n\nQuyền lợi\n- Tham gia các khóa đào tạo tiếng Nhật miễn phí, giúp nâng cao kỹ năng giao tiếp và làm việc hiệu quả hơn.\n- Làm việc cùng các kỹ sư cao cấp về AI, Embedded, nâng cao chuyên môn và mở rộng kiến thức công nghệ.\n- Mức lương từ 320-500 man/1 năm.\n- Nghỉ thứ 7 và CN;\n- Có 3 đợt nghỉ dài trong năm (mỗi đợt khoảng 9-11 ngày nghỉ);\n- Xét tăng lương 1 lần/ năm, Thưởng 2 lần/năm;\n- BHXH, y tế đầy đủ;\n- Khám sức khỏe hàng năm;\n- Có trợ cấp nhà ở, đi lại, vợ, con;\n- Có kí túc xá cho các bạn độc thân;\n- Team building theo quý, du lịch hàng năm, và rất nhiều các hoạt động vui chơi khác.\n- Cơ hội thăng tiến rõ ràng, phát triển sự nghiệp lâu dài tại Nhật Bản.\n\nĐịa điểm làm việc\n- Nhật Bản\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nhật Bản', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2410, 1284, 2, 'Lập Trình Viên PHP', 'Mô tả công việc: Tham gia phân tích yêu cầu, đề xuất giải pháp và xây dựng kiến trúc kỹ thuật cho các dự án phần mềm. Tham gia xuyên suốt quá trình phát triển sản phẩm: lập trình, kiểm thử, tối ưu hiệu năng và sửa lỗi. Báo cáo tiến độ công việc, đề xuất các cải tiến để nâng cao chất lượng dự án. Hỗ trợ quản lý, tổng hợp và báo cáo công việc đội nhóm khi cần thiết.\n\nYêu cầu ứng viên: Tối thiểu 2 năm kinh nghiệm lập trình Backend với PHP và framework Laravel. Có kinh nghiệm lập trình Frontend với VueJS, Bootstrap, jQuery. Thành thạo xử lý và làm việc với các định dạng dữ liệu JSON, XML, SOAP. Có kinh nghiệm với hệ quản trị cơ sở dữ liệu MySQL; ưu tiên ứng viên có hiểu biết về NoSQL, Cache. Ưu tiên ứng viên có kiến thức hoặc kinh nghiệm làm việc với Node.js. Ưu tiên ứng viên có khả năng làm Full Stack, từng tham gia các dự án theo mô hình Agile/Scrum. Có hiểu biết về hệ điều hành Linux, cấu hình máy chủ Nginx là một lợi thế. Có tinh thần trách nhiệm cao, chủ động trong công việc. Tư duy logic tốt, có khả năng phân tích và giải quyết vấn đề hiệu quả.\n\nQuyền lợi: Nghỉ phép, nghỉ lễ theo Luật lao động Việt Nam. Xét tăng lương hàng năm theo năng lực. Tham gia BHXH, BHYT, du lịch, teambuilding theo chính sách Công ty. Chế độ phúc lợi Lễ, Tết và thưởng theo quy định của Công ty. Thưởng tháng lương thứ 13 và thưởng doanh số theo quý và năm. Cơ hội thăng tiến nếu có thành tích làm việc tốt. Môi trường làm việc năng động, thân thiện, khuyến khích nhân viên phát triển và đóng góp ý kiến. Được đào tạo kỹ năng và định hướng phát triển nghề nghiệp.\n\nĐịa điểm làm việc: - Hà Nội: Tòa nhà Suced, số 108 đường Nguyễn Hoàng, Mỹ Đình 2, Nam Từ Liêm.\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:30 đến 17:30). Nghỉ Thứ Bảy, Chủ Nhật.\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2411, 1150, 2, 'ReactJs (Desktop App) Developer', 'Mô tả công việc:\n- Thiết kế phần mềm hoạt động trên nền tảng desktop (windows, linux).\n- Phát triển phần mềm cho hệ thống AI và robot tự động hoá (phần mềm đòi hỏi hoạt động chính xác, ổn định, thân thiện với người dùng, tương tác thời gian thực, bảo mật).\n- Làm việc nhóm, phối hợp phát triển với team Backend khác để tạo ra những sản phẩm hoàn thiện, đồng bộ nhất.\n\nYêu cầu ứng viên:\n- Tối thiểu 1 năm kinh nghiệm thực chiến trong việc xây dựng giao diện người dùng (UI) bằng ReactJS.\n- Sẽ là một lợi thế lớn nếu bạn có kiến thức hoặc đã từng làm việc với:\n  + Electron.js: Để đóng gói ứng dụng web thành ứng dụng desktop đa nền tảng.\n  + Three.js (hoặc các thư viện đồ họa 3D tương tự): Để hiển thị và tương tác với mô hình robot 3D.\n  + URDF, STL: Các định dạng phổ biến để mô tả và hiển thị robot.\n- Luôn chủ động tìm tòi, không ngừng học hỏi để nắm bắt các công nghệ và giải pháp mới.\n\nQuyền lợi:\n- Mức lương: từ 10 - 15 triệu/tháng\n- Thưởng: Thưởng hiệu quả công việc, ngày lễ tết, tháng lương thứ 13,...\n- Review năng lực định kỳ 01 năm/lần\n- Môi trường làm việc thoải mái, sáng tạo, năng động\n- Du lịch, nghỉ mát, team building,... hằng năm\n- Được cung cấp trang thiết bị làm việc hiện đại. Case xịn + 2 màn hình, server và các tài nguyên liên quan phục vụ công việc.\n- Nghỉ phép hưởng nguyên lương 12 ngày/năm.\n- Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 2, Sàn dịch vụ thương mại tòa nhà CT2D, VOV Mễ Trì,, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Sáng thứ 7 ( 8h-12h)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2412, 1285, 2, 'Giảng Viên Công Nghệ Thông Tin', 'Mô tả công việc:\n- Giảng dạy các môn học thuộc chuyên ngành CNTT và Ứng dụng phần mềm (Các môn học về lập trình: Java, C, C#, Javascript, PHP, Python, Android,…; các nền tảng: NodeJS, ReactJS, Angular, Laravel, Unity 2D, Spring MVC, Spring Boot,... và các môn Tin học cơ bản: CSDL, Quản trị website, Cài đặt và bảo trì phần mềm/cứng, Thiết lập và quản trị hệ thống mạng, Quản trị server,...)\n- Tham gia các hoạt động phát triển chuyên môn, xây dựng chương trình học, hướng dẫn đồ án tốt nghiệp, coi thi, chấm thi,...\n- Phối hợp tổ chức các hoạt động ngoại khóa cho sinh viên bộ môn (Workshop, Seminar, Talkshow,...)\n- Thực hiện các công việc liên quan khác theo phân công của Bộ môn.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học trở lên các chuyên ngành thuộc khối Công nghệ thông tin (Khoa học máy tính, Kĩ thuật phần mềm, Hệ thống thông tin, Điện tử - Viễn thông,...)\n- Có kiến thức chuyên môn tốt, am hiểu hoặc thông thạo một trong những lĩnh vực sau: Ngôn ngữ lập trình (Java, C#, Javascript, PHP, Python, HTML CSS, Android,…); các nền tảng (NodeJS, ReactJS, Angular, Laravel,...); CSDL (các hệ quản trị CSDL) hoặc quản trị hệ thống mạng (kiến trúc mạng, windows server, tường lửa, bảo mật,...)\n- Ưu tiên ứng viên có kinh nghiệm làm việc trong dự án thực tế hoặc từng tham gia giảng dạy về CNTT\n- Ưu tiên ứng viên có kĩ năng sư phạm, tư duy sáng tạo, cởi mở\n- Ưu tiên ứng viên có chứng chỉ nghiệp vụ sư phạm hoặc có kinh nghiệm về lập trình hoặc triển khai các các dự án CNTT.\n\nQuyền lợi:\n- Môi trường làm việc năng động, chuyên nghiệp\n- Có mức thu nhập hấp dẫn\n- Có cơ hội tham gia các lớp học, hoạt động đào tạo nâng cao trình độ.\n\nĐịa điểm làm việc:\n- Bà Rịa-Vũng Tàu: FPT PolySchool - 762 Cách Mạng Tháng 8, Phường Long Toàn, TP Bà Rịa.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bà Rịa-Vũng Tàu', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2413, 1286, 2, 'Unity Developer', 'Chúng tôi đang tìm kiếm một Unity Developer tài năng và đam mê game để gia nhập đội ngũ phát triển sản phẩm game của chúng tôi. Bạn sẽ làm việc trực tiếp với các đội ngũ thiết kế (GD), PO, Artist để phát triển các game Puzzle trên thị trường toàn cầu.\n\nTRÁCH NHIỆM VÀ CÔNG VIỆC CỦA BẠN LÀ:\n- Lập trình các tính năng trong game với Code rõ ràng, dễ đọc, tuân thủ quy chuẩn và hướng dẫn của nhóm phát triển.\n- Thực hiện công việc theo kế hoạch theo chu kỳ, đảm bảo tiến độ hoàn thành từng phần công việc trong thời gian quy định.\n- Hoàn thành mục tiêu công việc trong thời gian 2 tuần cho mỗi chu kỳ phát triển, với mục tiêu tiến bộ đều đặn trong quá trình xây dựng dự án.\n- Đảm bảo chất lượng công việc trong suốt quá trình phát triển và hoàn thiện sản phẩm.\n- Phối hợp hiệu quả với các thành viên trong nhóm để đạt được kết quả tốt nhất.\n- Đảm bảo chất lượng trò chơi, từ các khía cạnh kỹ thuật đến trải nghiệm người chơi.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành CNTT, kỹ thuật phần mềm hoặc các ngành liên quan.\n- Có 1 năm kinh nghiệm trở lên phát triển game với Unity\n- Có khả năng đưa ra hướng giải quyết nhanh, nhất là về thuật toán.\n- Thành thạo lập trình C# và hiểu biết sâu sắc về các tính năng của Unity.\n- Kinh nghiệm trong việc phát triển game cho các nền tảng mobile (iOS, Android).\n- Kiến thức về tối ưu hóa hiệu suất game và các kỹ thuật giảm tải tài nguyên.\n- Kinh nghiệm làm việc với các công cụ quản lý mã nguồn như Git.\n- Kỹ năng làm việc nhóm và giao tiếp hiệu quả.\n\nQuyền lợi:\n- Môi trường năng động, tinh gọn, hiệu quả với tầm nhìn và kế hoạch dài hạn.\n- Thưởng bonus theo sản phẩm.\n- Lương cạnh tranh theo thị trường.\n- Thời gian làm việc 7,5 giờ/ ngày, từ thứ 2 đến thứ 6.\n- Không gian pantry thoải mái gồm: cafe, nước giải khát, bánh kẹo, thức ăn nhẹ.\n- Thư giãn tại văn phòng cùng board game, bida và bi lắc...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2414, 1287, 2, 'Frontend Developer', '• Tham gia phát triển các sản phẩm phục vụ cho nền tảng thương mại điện tử Shopify.com.\n• Tham gia nghiên cứu và ứng dụng các công nghệ mới vào sản phẩm.\n• Phối hợp cùng đội ngũ BA phân tích, thiết kế, đưa ra giải pháp để phát triển sản phẩm.\n\n• Ưu tiên ứng viên đã từng làm việc trên Shopify.\n• Có ít nhất 01 kinh nghiệm làm việc với ReactJS, Hooks, Redux, Fetch/ Axios, Functional Programing.\n• Sử dụng thành thạo JavaScript ES5/ES6+, HTML5, CSS3 , Bootstrap 3/4, Webpack.\n• Có kinh nghiệm làm việc với APIs.\n• Hiểu biết về thiết kế giao diện và các công nghệ phát triển web hiện đại.\n• Sử dụng thành thạo GIT, công cụ AI và các phần mềm liên quan phục vụ công việc lập trình.\n\n• Thu nhập lên đến 20.000.000 VND, hoặc thỏa thuận theo năng lực của ứng viên (Không giới hạn).\n• Thưởng khi hoàn thành tốt dự án, thưởng cuối năm.\n• Môi trường làm việc năng động, trẻ trung, chuyên nghiệp.\n• Đóng BHXH ngay sau khi kết thúc 01 tháng thử việc.\n• Có 12 ngày nghỉ phép/năm.\n• Thưởng lễ, tết, sinh nhật, du lịch, nghỉ mát hàng năm và các chế độ đãi ngộ theo quy định.\n• Được đào tạo để nâng cao chuyên môn nghiệp vụ.\n• Thời gian làm việc: Sáng 8h30 - 12h, Chiều 13h30 - 18h từ thứ 2 - thứ 6\n• Địa chỉ làm việc: Tầng 8 Tòa nhà Hội nhà báo Việt Nam, Dương Đình Nghệ, Yên Hòa, Cầu Giấy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2415, 1288, 2, 'Junior Java Developer', 'Mô tả công việc\n- Hệ sinh thái phần mềm của Softdreams đang có hơn 300.000 doanh nghiệp sử dụng tại Việt Nam và có tốc độ tăng trưởng top 1 cả nước.\n- Xây dựng ứng dụng Saas bán hàng (EasyPOS), Kế toán (EasyBooks), Chữ ký số (EasyCA). Các ứng dụng đều hướng đến việc cung cấp giải pháp phần mềm Saas mạnh mẽ, cho 5 triệu người dùng cá nhân, hộ kinh doanh, doanh nghiệp.\n- Tham gia nghiên cứu, phát triển các ứng dụng, hệ thống dựa trên công nghệ Big Data.\n- Có cơ hội tham gia trong các công việc thiết kế kiến trúc hệ thống, tối ưu hệ thống Microservice/CSDL.\n- Tham gia phát triển trong nhiều thành phần ở kiến trúc tổng thể của hệ thống phần mềm ( Frontend - Angular/ Backend/ Services).\n- Phát triển phần mềm theo mô hình Agile, áp dụng cả Kanban và Scrum.\n\nYêu cầu ứng viên\n- Kinh nghiệm: Có ít nhất 2 năm kinh nghiệm về Java/Angular.\n- Có kiến thức vững chắc về truy vấn với CSDL (SQL hoặc NoSQL). Ứng viên có kinh nghiệm về SQL Server và MongoDB là lợi thế.\n- Rất ưu tiên ứng viên có tư duy nền tảng tốt và sẵn sàng tham gia vào các bài toán tối ưu lớn.\n- Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực tương đương (PM bán hàng/PM kế toán/ERP).\n- Có kinh nghiệm làm việc nhóm theo mô hình Agile.\n\nQuyền lợi\n- Thu nhập: 12,000,000-20,000,000/tháng + trợ cấp (700-900k/tháng)\n- Môi trường công nghệ trẻ, có cơ hội đề xuất, phát triển ý tưởng & thăng tiến cao\n- Xét tăng lương 2 lần/năm, thưởng tháng lương 13,14; thưởng lễ tết, sinh nhật\n- Được học hỏi: SDS tạo điều kiện cho mọi người rèn luyện ở mọi lúc mọi nơi, đồng hành và thúc đẩy phát triển cá nhân từ đồng nghiệp và quản lý giàu kinh nghiệm\n- Được thử sức trong một môi trường làm việc trẻ trung, cởi mở với chính sách đãi ngộ tốt\n- Du lịch hằng năm với địa điểm hấp dẫn, thường xuyên tổ chức các hoạt động team building gắn kết cộng đồng, các hoạt động vui chơi giải trí cho nhân viên.\n- Tham gia chương trình hàng tháng, các buổi liên hoan, sinh nhật hàng tháng, tiệc noel, tất niên,…\n- Được tham gia BHXH, BHYT, BHTN, chế độ nghỉ phép theo luật hiện hành.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2416, 38, 2, 'Tech Lead (.Net)', 'Mô tả công việc\n- Phát triển, kiểm thử và triển khai các ứng dụng phần mềm sử dụng C# và nền tảng .NET\n- Phối hợp với quản lý sản phẩm và kỹ sư phần mềm để thu thập và phân tích yêu cầu\n- Thiết kế, lập trình và gỡ lỗi ứng dụng, đảm bảo khả năng mở rộng, hiệu suất và khả năng bảo trì\n- Tham gia đánh giá mã nguồn và duy trì chất lượng mã theo các tiêu chuẩn lập trình\n- Chẩn đoán và xử lý các sự cố kỹ thuật ở cấp độ ứng dụng/cấu hình/mã nguồn\n- Kiểm thử phần mềm đã phát triển để đảm bảo đáp ứng yêu cầu về dữ liệu, logic và chức năng\n- Tích hợp các API và thư viện bên thứ ba để nâng cao chức năng ứng dụng\n- Khắc phục lỗi và các sự cố phần mềm một cách kịp thời\n- Cập nhật kiến thức về các công nghệ .NET mới nhất và các phương pháp thực hành tốt\n- Đảm bảo tài liệu kỹ thuật được cập nhật đầy đủ và chính xác\n\nYêu cầu ứng viên\n- Có kinh nghiệm tối thiểu 2 năm ở vị trí tương đương\n- Tốt nghiệp đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật phần mềm hoặc các ngành liên quan\n- Có kiến thức vững về nền tảng ASP.NET\n- Có kinh nghiệm trong toàn bộ vòng đời phát triển phần mềm: từ phân tích yêu cầu đến thiết kế, lập trình, kiểm thử và triển khai\n- Có kinh nghiệm làm việc ở vị trí Lập trình viên .NET hoặc vai trò tương tự\n- Thành thạo C# và nền tảng .NET\n- Có kinh nghiệm phát triển với ASP.NET, MVC và Web API\n- Thành thạo HTML, Java Script/JQuery, CSS, Bootstrap…\n- Hiểu biết và có kinh nghiệm làm việc với SQL Server, Oracle \n- Nắm vững các nguyên lý lập trình hướng đối tượng (OOP)\n- Kỹ năng giải quyết vấn đề tốt và có khả năng làm việc độc lập\n\nQuyền lợi\n- Thu nhập: 30M - 35M\n- Thời gian làm việc: Thứ 2 – Thứ 6. Nghỉ Thứ 7, Chủ nhật.\n- Nghỉ phép, nghỉ Lễ Tết, đóng BHXH, BHYT, BHTN theo quy định của Luật lao động\n- Review lương định kỳ 1 lần/năm hoặc tùy theo kết quả thực hiện công việc\n- Khám sức khỏe định kỳ tại bệnh viện tiêu chuẩn quốc tế\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 8, tòa nhà Ladeco, số 266 Đội Cấn,Phường Liễu Giai, Ba Đình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2417, 1289, 2, 'Media Player Developer', 'Mô tả công việc\n- Phát triển Media Player tối ưu hóa cho các sản phẩm của THINKWARE\n- Áp dụng và bảo trì Media Player đã phát triển trên các nền tảng Android / iOS / Windows PC / Mac PC.\n\nYêu cầu ứng viên\n- Kinh nghiệm: Không yêu cầu. Đối với ứng viên mới ra trường hoặc có kinh nghiệm dưới 1 năm, phỏng vấn sẽ dựa trên những kiến thức đã học ở trường.\n- Yêu cầu bắt buộc:\n  - Chuyên ngành Kỹ thuật hoặc Khoa học Máy tính\n  - Có kiến thức hoặc kinh nghiệm lập trình với ngôn ngữ C/C++\n  - Có kiến thức về Hệ điều hành (O/S)\n  - Bắt buộc ghi rõ các môn học liên quan đã hoàn thành tại đại học trong hồ sơ xin việc\n- Ưu tiên:\n  - Có kiến thức hoặc kinh nghiệm phát triển với FFmpeg\n  - Có kiến thức hoặc kinh nghiệm phát triển với DirectX / OpenGL\n  - Có kiến thức hoặc kinh nghiệm về giao thức RTP / RTSP\n  - Có kiến thức hoặc kinh nghiệm về giao thức mạng (TCP/IP)\n  - Có kiến thức hoặc kinh nghiệm với HFS (HTTP File Server) \n\nQuyền lợi\n- Lương tháng 13.\n- Môi trường làm việc năng động, thoải mái, sáng tạo.\n- Review lương hàng năm theo năng lực.\n- Khám sức khỏe tổng quát định kỳ.\n- Cung cấp thiết bị làm việc (laptop + màn hình to).\n- Snack bar đầy ấp đồ ăn.\n- Company trip, party hàng tháng, happy hours.\n- Cơ hội training tại nước ngoài.\n- Lớp học ngoại ngữ.\n- Hỗ trợ chi phí khóa học đào tạo kỹ năng.\n- Đóng BHXH, BHYT, BHTN đầy đủ theo chế độ của Nhà nước.\n- 12 phép năm / nghỉ lễ theo chế độ Nhà nước.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2418, 1271, 2, 'Kỹ Sư Phát Triển Phần Mềm', '- Lập trình mã nguồn nghiệp vụ theo yêu cầu người dùng, yêu cầu hệ thống, thiết kế chi tiết ở mức tính năng.\n- Lập trình giao diện theo thiết kế giao diện có sẵn.\n- Phối hợp các thành viên khác trong nhóm tích hợp các tính năng hệ thống.\n- Phối hợp với bộ phận quản lý chất lượng đảm bảo chất lượng hệ thống.\n\n- Tốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Toán – tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\n- Trình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\n- Có tối thiểu 02 năm kinh nghiệm liên quan đến vị trí ứng tuyển.\n- Sử dụng tốt ít nhất 1 ngôn ngữ lập trình (C/C++/Java/Golang/Android/iOS).\n- Có kiến thức nền tảng về công nghệ thông tin, ngôn ngữ mô hình hóa UML; quy trình phát triển phần mềm và toàn bộ vòng đời ứng dụng; mạng máy tính (các loại mạng, kiến trúc mạng, lập trình mạng, giao thức); ngôn ngữ truy vấn dữ liệu SQL, làm việc với hệ quản trị cơ sở dữ liệu, cấu trúc dữ liệu và giải thuật.\n\n- Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn\n- Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel\n- Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm\n- Cơ hội tiếp xúc với các dự án lớn, mới mẻ & tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam\n- Cơ hội thăng tiến rõ ràng với nhiều cấp bậc\n- Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn\n- Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời.\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người\n- Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,...\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày\n- Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng\n\n- Hà Nội: Tòa nhà Viettel, Số 380 Lạc Long Quân, Tây Hồ\n- Hà Nội: Tòa nhà Keangnam Landmark 72 tầng, Phạm Hùng, Nam Từ Liêm\n- Hà Nội: Tòa nhà Viettel, Khu Công nghệ cao Láng Hòa Lạc, Thạch Thất\n- Hồ Chí Minh: Tòa nhà Viettel, số 285 Cách Mạng Tháng 8, Phường 12, Quận 10\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2419, 1248, 2, 'Flutter Dev', 'Mô tả công việc\n- Tham gia trực tiếp các sản phẩm công ty đang phát triển và các phần mềm hỗ trợ quản lý nội bộ trong công ty\n- Chịu trách nhiệm phát triển các chức năng và đảm bảo chất lượng sản phẩm.\n- Tham gia phát triển dự án công ty do team phát triển từ đầu,\n- Kết hợp với các thành viên trong team cùng phát triển bản thân.\n\nYêu cầu ứng viên\n- Tìm hiểu và nghiên cứu các công nghệ mới.\n- Ham học hỏi, có thể tự làm việc độc lập\n- Ưu tiên có kiến thức với Javascript/ Flutter\n- Gắn link source code thực tế đã làm trước đó\n- Ưu tiên có kinh nghiệm với Reactjs/ Nextjs\n- Ưu tiên có kinh nghiệm làm việc với RestFul Api\n- Đã làm việc với chatbot hoặc AI là 1 lợi thế\n\nQuyền lợi\n- Vị trí Intern với mức lương hỗ trợ tối thiểu 8.000.000đ\n- Cung cấp thiết bị cho công việc: Macbook Pro, màn hình Dell 2k 24-27"\n- Các chế độ BHXH, BHYT đầy đủ theo quy định của luật lao động.\n- Lương thưởng theo năng lực của mỗi cá nhân, tháng lương thứ 13.\n- Phụ cấp ăn trưa và phí gửi xe.\n- Được hưởng nhiều chế độ đãi ngộ khác theo chính sách của Công ty.\n- Tham gia các sự kiện, workshop của công ty, chế độ du lịch hàng năm, sinh nhật hàng quý.\n- Môi trường làm việc trẻ, thân thiện, chuyên nghiệp\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 12A, tòa A3 Ecolife Capitol, số 58 Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 18:00)\nNghỉ 2 thứ 7 luân phiên trong 1 tháng, nghỉ chủ nhật, lễ tết\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2420, 1290, 2, 'Front End Developer', 'Chúng tôi đang tìm kiếm một Vue.js Developer đầy nhiệt huyết và tiềm năng để tham gia vào đội ngũ phát triển của chúng tôi. Bạn sẽ có cơ hội làm việc trên các ứng dụng web hiện đại, thân thiện với người dùng và sử dụng framework Vue.js. Đồng hành cùng các lập trình viên cấp cao, bạn sẽ xây dựng những giao diện hiệu quả, mở rộng và hấp dẫn.\n\nPhát triển và duy trì các ứng dụng web sử dụng Vue.js và các công nghệ liên quan.\nPhối hợp với đội ngũ thiết kế, quản lý sản phẩm và lập trình viên backend để tạo ra trải nghiệm người dùng mượt mà.\nViết mã sạch, dễ bảo trì và hiệu quả.\nGỡ lỗi và giải quyết các vấn đề nhằm đảm bảo hiệu suất và trải nghiệm người dùng tối ưu.\nTham gia review mã nguồn và đóng góp cải thiện tiêu chuẩn nhóm.\nCập nhật kiến thức về các xu hướng và thực tiễn tốt nhất trong Vue.js và phát triển frontend.\n\nYêu cầu ứng viên\nKỹ năng chuyên môn\nThành thạo Vue.js, Vue Router và Vuex (hoặc Pinia).\nKinh nghiệm chuyên sâu với HTML5, CSS3, JavaScript (ES6+), và TypeScript.\nHiểu biết sâu về tích hợp API, WebSocket, GraphQL, hoặc các dịch vụ tương tự.\nKinh nghiệm với các công cụ quản lý mã nguồn như Git và quy trình CI/CD.\nSử dụng thành thạo các framework UI như AntDesignVue, Vuetify, Tailwind CSS hoặc BootstrapVue.\nHiểu biết về kiến trúc microservices và Docker là một lợi thế.\nKỹ năng giải quyết vấn đề và phân tích tốt.\nSẵn sàng học hỏi và thích nghi với các công nghệ, công cụ mới.\nCó khả năng làm việc độc lập cũng như làm việc nhóm.\nKỹ năng giao tiếp tốt và thái độ chủ động trong công việc.\nTinh thần chủ động, sẵn sàng đón nhận thử thách và học hỏi công nghệ mới.\nƯu tiên (không bắt buộc)\nCó kinh nghiệm với các thư viện giao diện người dùng như Ant Design.\nKiến thức về các framework kiểm thử như Jest hoặc Cypress.\n\nQuyền lợi\nLương thỏa thuận cạnh tranh theo năng lực\nThưởng lễ tết, bonus cuối năm\nBảo hiểm sức khỏe, BHXH đầy đủ theo luật lao động\nĐược đào tạo trực tiếp nâng cao/bổ sung các kiến thức về ngành nghề\nĐánh giá năng lực, xét tăng lương/thưởng theo quy định của Công ty\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Tasco, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2421, 1291, 2, 'Middle Mobile Developer (Lập Trình Viên Mobile)', 'Làm việc với các công nghệ hiện đại, tham gia vào các dự án phát triển hệ thống quy mô lớn, ứng dụng công nghệ AI và kiến trúc Microservice.\n\n1. Mô tả công việc:\n\n· Phát triển và bảo trì các ứng dụng di động sử dụng React Native.\n· Tham gia xây dựng các API backend bằng Java Spring Boot và Python khi cần thiết.\n· Làm việc với kiến trúc hệ thống Microservice, triển khai bằng Docker Swarm, tích hợp với Nginx, Cloud Config, và Cloud Gateway.\n· Tích hợp các module AI, OCR, và các tác tử thông minh (AI Agent) vào ứng dụng.\n· Thiết kế, tối ưu hóa truy vấn và xử lý dữ liệu từ các hệ quản trị cơ sở dữ liệu: MS SQL, Oracle, MongoDB, MariaDB, MySQL, Elasticsearch, Redis.\n· Phối hợp với các thành viên trong nhóm phát triển, tester, và quản lý dự án để đảm bảo chất lượng và tiến độ dự án.\n\n· Từ 2-4 năm kinh nghiệm phát triển ứng dụng di động bằng React Native.\n· Có kinh nghiệm làm việc với ít nhất một trong các ngôn ngữ backend: Java Spring Boot, Python.\n· Có hiểu biết hoặc kinh nghiệm triển khai hệ thống theo mô hình Microservice.\n· Ưu tiên ứng viên có kinh nghiệm làm việc với Docker Swarm, Cloud Config, Cloud Gateway.\n· Khả năng làm việc độc lập, chủ động, có tư duy logic tốt và tinh thần học hỏi.\n· Ưu tiên ứng viên tốt nghiệp các trường: Đại học Bách Khoa, Đại học Khoa Học Tự Nhiên, Học Viện Bưu Chính Viễn Thông hoặc các trường kỹ thuật uy tín khác.\n\n· Mức lương cạnh tranh, xét tăng lương định kỳ.\n· Môi trường làm việc chuyên nghiệp, năng động, nhiều cơ hội học hỏi và phát triển.\n· Tham gia các dự án thực tế, được tiếp cận công nghệ hiện đại, AI, kiến trúc Microservice.\n· Chế độ BHXH, BHYT đầy đủ, nghỉ phép năm, lương tháng 13, thưởng sản xuất kinh doanh, khám sức khỏe định kỳ, team building.\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2422, 1292, 2, 'Lập Trình Web', 'Tham gia phát triển và bảo trì hệ thống backend (Laravel/NodeJS/Python...) Viết các công cụ nội bộ hỗ trợ quy trình làm việc: xử lý dữ liệu, tự động hóa thao tác, tạo báo cáo,... Làm việc với cơ sở dữ liệu (MySQL, MongoDB...) và thiết kế API Có kiến thức cơ bản về lập trình backend: PHP (Laravel), NodeJS hoặc Python Biết cách làm việc với cơ sở dữ liệu và logic xử lý dữ liệu Có đam mê phát triển hệ thống và thích xây dựng các tool hỗ trợ công việc Có kinh nghiệm thực tế là một lợi thế, chỉ cần có năng lực và tư duy lập trình tốt Có tinh thần chịu khó học hỏi, trách nhiệm trong công việc. Có thể chuyển đổi giữa frontend + backend là 1 lợi thế. Làm việc với git. Tốt nghiệp Cao đẳng, Đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành liên quan. Có làm qua PHP, Laravel Kỹ năng lập trình tốt với: PHP, MySQL, Javascript, HTML, CSS. Có kiến thức với MySQL và REST API. Đồng phục, điện thoại, công cụ dụng cụ làm việc... Được đào tạo kỹ năng mềm, kiến thức chuyên môn Lương tháng 13, 12 ngày phép... Thưởng đóng góp sáng kiến, ý tưởng mới trong công việc Thưởng thâm niên 3 năm, 5 năm, 10 năm. Chính sách phúc lợi cưới hỏi, ốm đau, thai sản Quà trong các dịp Tết, Trung thu, sinh nhật Cơm canh trưa, mì gói, trứng, chà bông... BHXH, BHYT, BHTN, BH 24/24, Bảo hiểm cao cấp Tiêm ngừa Cúm..... Khám sức khỏe định kỳ Phòng tập GYM miễn phí Du lịch hàng năm trong/ngoài nước Hạn nộp hồ sơ: 26/06/2025. Địa điểm làm việc: Hồ Chí Minh: 245B Trần Quang Khải, Phường Tân Định, Quận 1 Thời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:45) Thứ 7 (từ 08:00 đến 16:00) Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2423, 1293, 2, 'Mobile Developer', 'Mô tả công việc: Phát triển sản phẩm: Sử dụng React Native để phát triển và cải tiến sản phẩm của công ty. Phát triển và bảo trì ứng dụng: Thiết kế, xây dựng các tính năng mới và bảo trì, tối ưu các tính năng hiện có cho ứng dụng trên nền tảng di động (iOS và Android). Nghiên cứu và ứng dụng công nghệ: Tìm hiểu, nghiên cứu và áp dụng các công nghệ mã nguồn mở vào dự án nhằm nâng cao hiệu quả và tính linh hoạt của sản phẩm. Quy trình phát triển phần mềm: Tham gia vào các công đoạn phân tích yêu cầu, thiết kế chi tiết (Detail Design), coding và viết tài liệu kỹ thuật. Hợp tác nhóm: Làm việc chặt chẽ với các thành viên trong nhóm và các phòng ban liên quan để đảm bảo chất lượng và tiến độ của dự án. Yêu cầu ứng viên: Kỹ năng cần có: Kinh nghiệm: Có kinh nghiệm phát triển ứng dụng di động với React Native; ưu tiên ứng viên có kinh nghiệm trên cả iOS và Android. Kỹ năng lập trình: Thành thạo JavaScript, ES6+ và hiểu biết vững về React Native. Kiến thức API: Nắm vững kiến thức về RESTful API và các kỹ thuật tích hợp backend. Kỹ năng phân tích: Có khả năng phân tích yêu cầu, giải quyết vấn đề và tối ưu hóa hiệu năng ứng dụng. Tinh thần học hỏi: Luôn chủ động cập nhật các công nghệ mới và sẵn sàng thử nghiệm các giải pháp sáng tạo. Kỹ năng giao tiếp: Có khả năng làm việc nhóm tốt và giao tiếp hiệu quả với các bộ phận liên quan. Kỹ năng ưu tiên: Có kinh nghiệm làm Product phần mềm quản lý nội bộ doanh nghiệp, thương mại điện tử, CRM. Ưu tiên ứng viên thích làm product, tư duy làm sản phẩm cao, hướng tới người dùng cuối. Ưu tiên ứng viên có trình độ tiếng Anh tốt. Quyền lợi: Thu nhập hấp dẫn: Upto 25 Triệu KPI. Được cung cấp đầy đủ trang thiết bị làm việc hiện đại. Đóng BHXH, BHYT theo Quy định của Nhà nước. Lộ trình thăng tiến rõ ràng và sếp luôn quan tâm nâng cao năng lực chuyên môn. Được tham gia các khóa đào tạo nâng cao năng lực cá nhân, khóa kỹ năng mềm. Được hưởng chính sách phúc lợi theo Quy định của Công ty: thưởng lễ, Tết, du lịch định kỳ, Thưởng. Địa điểm làm việc: Hà Nội: Số 69 Tố Hữu, Vạn Phúc, Hà Đông. Thời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:30). Thứ 7 (từ 08:00 đến 12:00). Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2424, 1193, 2, 'Server Developer (C Language)', 'Mô tả công việc\n- Develop server-side systems using Unix/Linux C programming within the Kiwoom platform, utilizing CISAM, IPC, and Shared Memory\n- Collaborate directly with remote teams to clarify tasks and requirements\n- Analyze user requirements and participate in system design to develop new features\n- Investigate and resolve reported issues and bugs during integration testing, user acceptance testing, and maintenance testing\n- Manage time and resources effectively based on the Work Breakdown Structure (WBS)\n- Compile weekly progress reports detailing task status and developments\n- Engage in continuous self-learning to acquire domain knowledge, prepare reports, and conduct seminars to share insights\n- Write high-quality, clean, maintainable, and testable code following best practices.\n- Ensure technical documentation is accurate and up-to-date\n- Gain hands-on experience in all stages of diverse projects, covering various aspects of software engineering and fostering your professional growth.\n\nYêu cầu ứng viên\nEducation & Experience\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Minimum 3 years of professional experience in C language.\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nTechnical skills\n- Experience with C language focus in: CISAM, IPC, Shared Memory.\n- Prior experience with Korean stock market systems is a significant advantage.\n- Familiarity with version control systems, such as Git or SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n\nSoft Skills & Communication\n- Able to communicate in English, written and spoken (processed by English interview).\n- Strong communication skills and teamwork, international experience is preferred.\n- Strong problem-solving and analytical skills.\n\nGive Reference\n- Over 1 year of experience in developing securities solutions under channel server side.\n- Experience on working with oversea team.\n- Develop and maintain the Channel Server for the Korean stock market system.\n- Providing training and education experience in Korea with Korean Finance/IT expert.\n\nSPECIAL OFFER\n- Providing opportunities to work and support in IT/Finance fields overseas.\n\nQuyền lợi\nIncome & Achievement\n- Competitive salary, salary review once a year.\n- 13thmonth salary and Annual Performance Bonus.\n- MVP and Shining star awards at the end of year.\n- Global and professional working environment.\n\nWorkplace Happiness\n- Full SHUI as Vietnamese Law.\n- Premium Private Medical Insurance PVI and annual health check.\n- 15-day annual leave, Christmas leave and 30-min menstrual leave for women.\n- Company trip, YEP and monthly gathering time.\n- Gifts on special occasion and fully stocked snack corner.\n- Sponsored training courses and book purchase quarterly.\n- Be well-equipped with new working equipment.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2425, 1159, 2, 'Fullstack Developer (Senior)', 'About this opportunity: We\'re looking for a Full-Stack Developer to join our team with NodeJS & ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc. who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.\n\nYou will:\n- Working with Product Owners to convert business requirements into technical designs.\n- Working and pair programming with other developers to build applications with Node.JS and ReactJS.\n- Design and develop scalable front-end solutions using ReactJS\n- Build and maintain robust back-end systems with NodeJS\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Ensure code quality, security, and performance optimization.\n\nYour Skills and Experience:\n- Knowledge of responsive design techniques and front-end optimization methods.\n- At least 3 years of experience as a Full-Stack Developer (Node.js & React.js).\n- Strong proficiency in front-end technologies, particularly React.\n- Expertise in back-end development using Node.js.\n- Hands-on experience with Web3 integration.\n- Solid understanding of smart contract development and deployment.\n- Good command of English (both verbal and written).\n- Knowledge of cryptography and blockchain is a plus.\n\nWhy You\'ll Love Working Here:\n- Build World class product(s): We love to solve complex problems and learn new things.\n- Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n- Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n- Enjoy competitive salary, bonus according to work performance\n- 13th Salary\n- Assistance with operational tools and equipment.\n- Health insurance program up to 100 million VND/year for employees provided by PVI.\n- Annual health check-up from Medlatec Clinic\n- Participate in social insurance after becoming an official employee\n- Salary review twice a year. It means we are pushing each other to be better everyday.\n- Flexible working hours, freestyle attire\n\nPerks You\'ll Enjoy:\n- Working in a young, super talented, and supportive team environment\n- Technical, English certificate bonus\n- Day-off: 12 days/year and Vietnam holidays\n- Happy Hour, Football club, English club, and many exciting activities\n- Company trip/ team building/ Year End Party\n- Free coffee, snacks, and drinks\n\nĐịa điểm làm việc:\n- Đà Nẵng: 68 Xô Viết Nghệ Tĩnh, Cẩm Lệ\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2426, 1128, 2, 'Winform Developer', 'Mô tả công việc:\n- Tham gia các dự án sử dụng ngôn ngữ lập trình Winform (VB/C# .NET),...\n- Phân tích thiết kế, lập trình và viết UT cho các chức năng của các hệ thống nghiệp vụ.\n- Nghiên cứu công nghệ thích hợp để giải quyết vấn đề\n- Làm các công việc khác theo sự phân công của quản lý (nghiên cứu công nghệ mới, quản lý và hỗ trợ đội phát triển dự án,...)\n\nYêu cầu ứng viên:\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan\n- Có từ 1-2 năm kinh nghiệm làm việc với C# .NET.\n- Có kinh nghiệm phát triển ứng dụng WPF và Console App\n- Có kinh nghiệm làm việc với Entity Framework/Dapper\n- Có thể làm việc tốt với các hệ quản trị cơ sở dữ liệu thông dụng như: MySQL, SQL Server\n- Hiểu biết về PowerShell, có khả năng viết và triển khai các script tự động hóa\n- Ưu tiên ứng viên có kiến thức về VBA\n\nƯu tiên:\n- Thành thạo các công cụ quản lý source code (Git, SVN...), quản lý task (Jira)\n- Có tiếng Nhật hoặc có kinh nghiệm làm việc với khách hàng Nhật\n- Tư duy logic tốt\n- Có kiến thức tốt về quy trình phát triển phần mềm\n- Có khả năng viết UnitTest\n\nYêu cầu khác:\n- Kỹ năng phân tích và giải quyết vấn đề tốt.\n- Có tinh thần học hỏi, cầu tiến và khả năng làm việc nhóm hiệu quả\n- Khả năng tiếng anh đọc hiểu tài liệu\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng dự án + thưởng kinh doanh cuối năm, thưởng Tết và các dịp lễ...;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe 24/24;\n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện);\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày;\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành.\n- Miễn phí đồ uống tại khu ăn uống của công ty;\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan;\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game,...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm....\n\nĐặc biệt:\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín.\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4 CT1, Tòa C14 Bắc Hà, Đường Tố Hữu, Phường Trung Văn, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2427, 1294, 2, 'Nhân Viên Lập Trình Cnc', '+Sử dụng các phần mềm để tạo chương trình gia công sản phẩm.\n+Set up hàng mẫu dựa trên các loại máy phay CNC\n+ Giải quyết và khắc phục các sự cố kỹ thuật của sản phẩm trong quá trình sản xuất\n+Thiết kế, chế tạo gia công cho sản phẩm mẫu\n+ Vận hành máy phay CNC\n\nYêu cầu ứng viên:\n- Tốt nghiệp  chuyên ngành chuyên ngành Cơ khí, Cơ khí chế tạo máy,hoặc các ngành liên quan.\n- Ít nhất 2 năm kinh nghiệm lập trình máy móc tự động hóa..\n- Kỹ năng giải quyết vấn đề và tư duy logic tốt.\n- Khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Có tinh thần trách nhiệm cao và chủ động trong công việc.\n- Đọc hiểu bản vẽ cơ khí , bản vẽ kỹ thuật tốt\n- Kinh nghiệm với các hệ thống SCADA là một lợi thế.\n\nQuyền lợi:\n- Mức lương cạnh tranh tùy thuộc vào kinh nghiệm và năng lực.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế theo luật lao động.\n- Thưởng các ngày lễ, tết và thưởng hiệu quả công việc.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.\n- Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n- Được tham gia các khóa đào tạo nâng cao nghiệp vụ.\n\nĐịa điểm làm việc:\n- Bắc Giang: KCN Hoà Phú - Hiệp Hoà, Hiệp Hoà\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n- Tăng ca khi có yêu cầu của khách hàng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2428, 1117, 2, 'Junior Backend Developer (NestJS / FastAPI)', 'Mô tả công việc:\n- Thiết kế, phát triển và tối ưu hệ thống backend sử dụng NestJS (Node.js) và FastAPI (Python)\n- Làm việc với các hệ quản trị cơ sở dữ liệu như PostgreSQL, MongoDB, v.v.\n- Thiết kế và phát triển API phục vụ frontend hoặc ứng dụng mobile\n- Triển khai, bảo trì, giám sát hệ thống backend theo hướng microservice\n- Viết tài liệu kỹ thuật, API document (Swagger, Postman...)\n- Phối hợp chặt chẽ với frontend, QA, và DevOps để đảm bảo chất lượng hệ thống\n\nYêu cầu ứng viên:\n- Thành thạo NestJS (Node.js) và FastAPI (Python)\n- Hiểu rõ nguyên lý hoạt động RESTful API, WebSocket\n- Có kinh nghiệm làm việc với PostgreSQL hoặc MongoDB\n- Biết cách triển khai API bảo mật với JWT, OAuth2\n- Nắm vững kiến thức về OOP, SOLID, Clean Architecture\n- Có kinh nghiệm làm việc với Docker, Git\n- Biết sử dụng Postman hoặc Swagger để kiểm thử API\nƯu tiên:\n- Có kinh nghiệm triển khai hệ thống trên AWS, GCP, Vercel, hoặc DigitalOcean\n- Biết sử dụng Celery, RabbitMQ, hoặc Redis Queue cho các tác vụ bất đồng bộ\n- Có kinh nghiệm làm việc với hệ thống microservice\n- Biết sử dụng các công cụ giám sát như Prometheus, Grafana, hoặc Sentry\n- Có kinh nghiệm CI/CD (GitHub Actions, GitLab CI...)\n\nQuyền lợi:\n- Thưởng các ngày lễ, Tết, sinh nhật, teambuilding... tuỳ tình hình kinh doanh công ty;\n- Tăng lương định kỳ hằng năm;\n- Các chế độ bảo hiểm đầy đủ theo quy định pháp luật;\n- Cung cấp thiết bị làm việc.\n\nĐịa điểm làm việc:\n- Thừa Thiên Huế: Tầng 06 Tòa nhà Vietin, số 02 Lê Quý Đôn, Phường Phú Hội, Huế., TP Huế\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2429, 1295, 2, 'Chuyên Gia Phát Triển Ứng Dụng Ngân Hàng Số (.NET)', 'Mô tả công việc:\n- Tham gia việc phân tích, đánh giá các yêu cầu nghiệp vụ ngân hàng trên các kênh ngân hàng điện tử, ngân hàng số dành cho KHCN và KHDN, Branch Teller.\n- Tham gia phát triển, cải tiến và duy trì các ứng dụng kênh ngân hàng điện tử, ngân hàng số dành cho KHCN và KHDN, Branch Teller.\n- Đảm bảo tích hợp liền mạch giữa các ứng dụng kênh ngân hàng điện tử, ngân hàng số và các hệ thống công nghệ hiện có của ngân hàng.\n- Tham gia phối hợp hỗ trợ các đơn vị vận hành giám sát hoạt động và khắc phục các vấn đề phát sinh của các hệ thống trên kênh số khi có yêu cầu bao gồm: Internet Banking, Mobile Banking.\n- Tham gia hỗ trợ level 2 cho các sản phẩm, dịch vụ trên kênh số nhằm phục vụ khách hàng nội bộ (CallCenter, Card Center, Chi nhánh/Phòng giao dịch) và khách hàng bên ngoài thông qua các kênh như Service Desk, email, điện thoại,...\n- Tham gia các dự án số hóa của Ngân hàng và khối CNTT.\n- Theo dõi xu hướng và phát triển trong lĩnh vực ngân hàng điện tử, ngân hàng số, đề xuất các phương án cải tiến và áp dụng các giải pháp sáng tạo để nâng cao trải nghiệm khách hàng.\n- Thực hiện các nhiệm vụ khác theo phân công của cấp quản lý.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học trở lên các chuyên ngành phù hợp như CNTT/Điện tử viễn thông hoặc các chuyên ngành có liên quan đến CNTT.\n- Tối thiểu 3 năm kinh nghiệm trong lĩnh vực phát triển ứng dụng ngân hàng số, tài chính số hoặc các lĩnh vực liên quan (lập trình Java/ .NET, J2EE/Web service/JMS, Oracle Database, My SQL, Postgre SQL).\n- Có kinh nghiệm về tích hợp hệ thống qua ESB (Enterprise Service Bus) sử dụng EIP (Enterprise Integration Patterns).\n- Có kinh nghiệm về microservices, CI/CD\n- Có kinh nghiệm về các công cụ giám sát như ELK, Splunk, Prometheus, Grafana.\n- Sử dụng thành thạo các IDE phát triển và các tool quản lý source code, quản lý công việc. (CI/CD: Jenkin, GIT, ANT);\n- Nắm vững các design pattern thông dụng, các kiến thức về cấu trúc dữ liệu và giải thuật, lập trình hướng đối tượng,...\n- Đã từng làm việc trong lĩnh vực ngân hàng, có kiến thức về nghiệp vụ và hệ thống thông tin ngân hàng là lợi thế.\n- Kỹ năng Tiếng Anh đọc hiểu tài liệu kỹ thuật.\n\nƯu tiên các ứng viên:\n- Ham học hỏi tìm tòi sáng tạo cái mới.\n- Có hiểu biết về nghiệp vụ tài chính ngân hàng.\n- Đã từng triển khai sản phẩm lên AWS, Azuse.\n- Có kinh nghiệm làm việc theo mô hình Agile/ Scrum/ Waterfall.\n\nQuyền lợi:\n- Chế độ phúc lợi:\n  - Lương và phụ cấp.\n  - Lương nhân viên PG Bank được áp dụng từ việc khảo sát mức lương thực tế của ngành và thị trường. Khung lương được xây dựng cho 9 cấp/ bậc của công việc, dải lương rộng cho phép thu hút được những ứng viên tiềm năng và đảm bảo trả mức lương cạnh tranh cao cho mọi vị trí. Ngoài chế độ lương cạnh tranh, nhân viên PG Bank còn được hưởng rất nhiều chế độ phụ cấp khác theo đặc thù công việc như phụ cấp điện thoại, phụ cấp ăn trưa, phụ cấp đi lại ... , chế độ tham quan nghỉ mát hàng năm, tặng quà cho CBNV nhân dịp sinh nhật, thăm hỏi ốm đau, kết hôn, hỗ trợ thai sản.\n  - Chế độ khen thưởng: PG Bank có chế độ đãi ngộ nhân viên xứng đáng với năng lực và đóng góp của từng cá nhân. Về cơ bản, PG Bank có chế độ thưởng như sau:\n    + Thưởng theo kết quả kinh doanh.\n    + Thưởng hoàn thành công việc.\n    + Thưởng cho tập thể, cá nhân tiêu biểu trong năm.\n    + Thưởng đột xuất cho tập thể, cá nhân hoàn thành xuất sắc nhiệm vụ, có sáng kiến, đóng góp có giá trị cho Ngân hàng, thưởng do hoàn thành vượt mức kế hoạch được giao.\n    + Thưởng cho toàn bộ CBNV ngân hàng trong các dịp lễ tết.\n  - Chế độ bảo hiểm:\n    Tất cả nhân viên chính thức của PG Bank đều được tham gia Bảo hiểm xã hội, Bảo hiểm y tế và bảo hiểm thất nghiệp theo đúng quy định của Luật lao động hiện hành. Ngoài ra, tất cả nhân viên chính thức của PG Bank đều được mua thêm bảo hiểm Pijico, một gói bảo hiểm rất ưu việt giúp thanh toán các chi phí y tế như tiền thuốc, tiền viện phí... khi khám chữa bệnh tại các bệnh viện tốt nhất tại địa phương.\n\n- Đào tạo và phát triển nguồn nhân lực:\n  Công tác đào tạo và phát triển nguồn nhân lực luôn được chú trọng và phát triển tại PG Bank. Với mục tiêu xây dựng nguồn nhân lực có năng lực và tính chuyên nghiệp cao đáp ứng chiến lược phát triển nhanh và bền vững của Ngân hàng, chuẩn bị nhân sự kế nhiệm cấp điều hành cho Ngân hàng, PG Bank thường xuyên tổ chức cho nhân viên tham dự các khóa đào tạo trong và ngoài nước, các khóa đào tạo của NHNN, Hiệp hội ngân hàng, các tổ chức đào tạo có uy tín khác nhằm nâng cao trình độ chuyên môn, nâng cao kỹ năng làm việc hiệu quả và các kỹ năng quản lý, lãnh đạo trong từng giai đoạn, vị trí công tác.\n\n- Cơ hội thăng tiến:\n  Tại PG Bank, nhân viên được làm việc trong môi trường cạnh tranh lành mạnh, rất nhiều cơ hội phát triển, thăng tiến đang chờ đón các bạn.\n\nĐịa điểm làm việc:\n- Hà Nội: 79 Dịch Vọng Hậu, Cầu Giấy.\n\nCách thức ứng tuyển:\n  Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2430, 1296, 2, 'Fullstack Developer Intern (Hỗ Trợ 4M-5M)', 'Mô tả công việc:\n- Phát triển sản phẩm phần mềm theo định hướng của công ty trên nền tảng Shopify.\n- Hỗ trợ khách hàng cài đặt, sử dụng sản phẩm.\n- Fix lỗi và cập nhật sản phẩm liên tục đáp ứng nhu cầu của khách hàng.\n- Phát triển và vận hành sản phẩm trên hệ thống cloud AWS.\n- Làm việc với những công nghệ mới nhất React JS, GraphQL, Node JS, React Native.\n\nYêu cầu ứng viên:\n- Sinh viên năm 3,4 ngành CNTT các trường Đại học (UET, HUST, PTIT, FPT, HAUI, HANU,…) tại Hà Nội;\n- Đã từng có kinh nghiệm thực tập 3 tháng tại các Công ty Công nghệ hoặc có dự án cá nhân sử dụng tech stack tương ứng;\n- Có khả năng sử dụng 1 ngôn ngữ lập trình bất kỳ (PHP, Java, JS…) và có hiểu biết căn bản về lập trình web, Javascript, relational database (MySQL). Ưu tiên ứng viên có kinh nghiệm Reactjs, GraphQL, Node JS. Đặc biệt, có hiểu biết về React Native là lợi thế lớn;\n- Tiếng anh cơ bản đọc, hiểu tốt;\n- Tư duy logic tốt, có kỹ năng giải quyết vấn đề và làm việc trong môi trường áp lực cao.\n- Yêu thích làm việc với nền tảng thương mại điện tử.\n- Sẵn sàng được đầu với nhiều thử thách, chịu khó dành nhiều thời gian nghiên cứu và giải quyết vấn đề khi được yêu cầu.\n- Khả năng làm việc độc lập hoặc làm việc nhóm, tự chủ động giải quyết các vấn đề trong công việc theo đúng tiến độ và hướng dẫn.\n- Thẳng thắn trao đổi, có trách nhiệm với công việc, tôn trọng đồng nghiệp.\n\nQuyền lợi:\n- Nhận lương hỗ trợ thực tập: 4M – 5M/ tháng\n- Được offer trở thành nhân viên chính thức nếu hoàn thành tốt 2 tháng thực tập với mức lương khởi điểm lên tới 12 triệu/tháng\n- Được tham gia vào phát triển 1 Super App trên Shopify, phát triển kĩ năng sử dụng React JS, NodeJS, React Native. Được làm việc và support nhiệt tình bởi các Senior Shopify Developer\n- Thời gian làm việc 5 ngày/tuần, từ 8h30 đến 17h45. Không khuyến khích OT.\n- Làm việc tại một trong những công ty Magento hàng đầu tại Việt Nam, là đối tác Technology Partner của Magento và Solution Provider cho nhiều khách hàng Magento Enterprise trên thế giới (100% khách hàng nước ngoài).\n- Có cơ hội phát triển kỹ năng thuyết trình, huấn luyện đào tạo qua các buổi chia sẻ, training nội bộ.\n- Nhiều phúc lợi hấp dẫn: 13.5 ngày nghỉ phép/năm (12 ngày nghỉ phép theo quy định và 1.5 ngày nghỉ phép du lịch hàng năm), bảo hiểm, hiếu hỉ, quà sinh nhật, thưởng thâm niên và các phúc lợi khác theo quy định của pháp luật.\n- Môi trường làm việc trẻ trung (95% là 9x), làm hết sức, chơi hết mình. Văn phòng làm việc tiện nghi. Free trà, cafe và có tủ đồ uống.\n- Tham gia các chương trình team building, dã ngoại, sinh nhật thành viên, du lịch, từ thiện… do BSS tổ chức thường xuyên.\n- Tham gia các CLB chạy, đá bóng, boardgame, văn nghệ… sau giờ làm việc.\n- Nghỉ hằng năm và các phúc lợi khác theo quy định của pháp luật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2431, 1224, 2, 'Thực Tập Sinh', 'Mô tả công việc:\n- Phát triển game 2D/3D trên nền tảng Unity\n- Tham gia các dự án về game. Dev bằng Unity và các phần mềm lập trình khác.\n- Phối hợp với các thành viên trong team để hoàn thiện và tối ưu game: animation, UI, UX...\n- Đóng góp ý tưởng nội dung công việc.\n\nYêu cầu ứng viên:\n- Sinh viên năm cuối hoặc vừa tốt nghiệp chuyên ngành CNTT ở các trường Đại học; trung tâm IT\n- Có sản phẩm game demo\n- Đã từng làm ít nhất 1-2 minigames dev bằng Unity (cho cá nhân hoặc công ty). Gửi kèm sản phẩm game hoặc game demo trong cv ứng tuyển.\n- Có kiến thức về C#, Java…\n- Yêu thích và đam mê lập trình phần mềm, quan tâm tới lập trình game di động;\n- Tư duy logic tốt\n- Ưu tiên có kinh nghiệm làm với Unity\n- Đã từng tham gia dự án trên iOS/Android/HTML5 là một lợi thế.\n- Kỹ năng phân tích và giải quyết vấn đề tốt\n- Có khả năng làm việc nhóm cũng như độc lập.\n\nQuyền lợi:\n- Lương: 2tr-3tr\n- Thời gian làm việc: 8h-17h30( từ thứ 2- sáng thứ 7)\n- Được đào tạo về lập trình game 2D/3D trên điện thoại di động và cách thức vận dụng vào dự án cụ thể, nắm vững kiến thức tổng quát trong lập trình game\n- Cơ hội tiếp cận và học hỏi công nghệ tiên tiến trong môi trường làm việc đa quốc gia năng động, trẻ trung, chuyên nghiệp\n- Chương trình đào tạo bài bản, chuyên nghiệp\n- Cơ hội trở thành nhân viên chính thức bất cứ thời gian nào trong quá trình thực tập.\n\nĐịa điểm làm việc:\n- Hà Nội: Hà Đông\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n- Thứ 2- Thứ 6: 8h-17h30\n- Thứ 7: 8h-12h\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2432, 1297, 2, 'Curriculum Developer', 'Mô tả công việc\n- Nghiên cứu, phát triển chương trình đào tạo mảng Coding (các khóa học lập trình, Global Developer; Computer Science, Blockchain, v.v) cho đối tượng sinh viên và người đi làm.\n- Điều phối workload và ra đề bài cho các CTV/chuyên gia ở các lĩnh vực đào tạo, đảm bảo nội dung bám sát với mô hình đào tạo của Trường học công nghệ MindX.\n- Nghiên cứu thị trường, đảm bảo việc phát triển bộ học liệu, đề test, mô hình đào tạo đáp ứng đúng nhu cầu thực tiễn, tiến độ và budget được giao.\n- Điều phối workload của các cộng tác viên, báo cáo và đề xuất định hướng phát triển sản phẩm với với R&D Team Lead.\n- Phối hợp với các phòng ban nội bộ (Marketing, Projects, Teaching, CXO, v.v) để thu nhận feedback và cải tiến chất lượng đào tạo (bao gồm học liệu, thiết kế trải nghiệm và phương pháp truyền đạt).\n\nYêu cầu ứng viên\n- Đã có kinh nghiệm trong lĩnh vực phát triển phần mềm, ưu tiên thành thạo trong lĩnh vực phát triển các ứng dụng Web, Mobile, Làm việc với các hệ thống dữ liệu.\n- Tốt nghiệp các chuyên ngành liên quan đến công nghệ thông tin: Khoa học máy tính, Cơ điện tử, Điện tử viễn thông, Toán tin ứng dụng.\n- Khả năng nghiên cứu, đọc hiểu tiếng Anh khá.\n- Chủ động và có trách nhiệm trong công việc, có kỹ năng giải quyết vấn đề.\n- Có kinh nghiệm giảng dạy hoặc R&D trong lĩnh vực giáo dục-công nghệ là một điểm cộng.\n- Kỹ năng giao tiếp, trình bày vấn đề mạch lạc, lập luận logic, rõ ràng.\n- Kỹ năng tư duy phản biện, hỏi lại khi chưa rõ đề bài, sẵn sàng chất vấn người quản lý trực tiếp và đưa ra quan điểm, đề xuất của mình.\n\nQuyền lợi\n- Lương cứng: 10,000,000 VND - 15,000,000 VND (tùy năng lực) + thưởng theo cơ chế.\n- Chế độ nghỉ phép, nghỉ lễ Tết, tham gia BHXH theo quy định của Nhà Nước.\n- Môi trường làm việc trẻ năng động, khuyến khích sự sáng tạo và tư duy làm chủ công việc.\n- Văn phòng hiện đại, không gian thoáng, có phòng nghỉ trưa, có hỗ trợ chi phí gửi xe.\n- Hỗ trợ tài khoản trên các platform học tập: Udemy, Coursera, EdX, etc.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 5, 71 Nguyễn Chí Thanh, Đống Đa.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2433, 1298, 2, 'Senior Java', 'Mô tả công việc:\n- Phát triển ứng dụng website sử dụng Java Spring Boot để quản trị dữ liệu, quản lý kết nối, tích hợp và phát triển API phục vụ hệ thống.\n- Đảm bảo hiệu suất, chất lượng và khả năng đáp ứng tốt nhất có thể của các ứng dụng ở phía Back-end.\n- Có kinh nghiệm làm việc với bảng biểu, dữ liệu từ SuperSet, Data Engineer và Data Analyst làm một lợi thế.\n\nYêu cầu ứng viên:\n- Trên 5 năm kinh nghiệm phát triển ứng dụng với Java, Spring Boot, Spring Boot RESTful Services, Spring Security, Spring Data JPA.\n- Database: Kỹ năng làm việc với các cơ sở dữ liệu quan hệ như SQL Server, PostgreSQL, MySQL, hoặc Oracle.\n- Kinh nghiệm với các công cụ ORM (Object Relational Mapping) như Hibernate để quản lý và truy xuất dữ liệu trong ứng dụng.\n- Front-end Skills: Kỹ năng cơ bản với các công nghệ front-end như HTML, CSS, JavaScript (React hoặc Vue).\n- Hiểu và áp dụng CI/CD.\n\nYêu cầu các kỹ năng khác:\n- DevOps và CI/CD.\n- Docker, Kubernetes hoặc Jenkins.\n- OAuth và Bảo mật ứng dụng: Kiến thức về OAuth 2.0, JWT, và các tiêu chuẩn bảo mật ứng dụng web khác để đảm bảo bảo mật cho ứng dụng.\n- Có kinh nghiệm làm việc với bảng biểu, dữ liệu từ SuperSet, Data Engineer và Data Analyst làm một lợi thế.\n\nQuyền lợi:\n- Lương: 30.000.000 - 40.000.000.\n- Thưởng dự án/thưởng kinh doanh: từ 1 – 5 tháng lương.\n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30.\n- Nghỉ phép: 12 ngày/năm.\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN, Bảo hiểm Bảo Việt cho 100% cán bộ sau thời gian thử việc.\n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n- Các hoạt động giao lưu bóng đá, golf, văn nghệ...\n- Đào tạo chuyên sâu theo yêu cầu công việc.\n- Được tham gia các dự án lớn triển khai toàn quốc.\n- Được tiếp cận các kỹ thuật, công nghệ hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2434, 1299, 2, 'Mobile Developer', 'We are looking for an experienced Mobile App Developer to join our team. As a Mobile App Developer, you will be responsible for the development and maintenance of high-quality mobile applications. You will collaborate with cross-functional teams to define, design, and ship new features and functionality.\n- Develop and maintain high-quality mobile applications for iOS and Android platforms.\n- Collaborate with cross-functional teams to define, design, and ship new features and functionality.\n- Identify and fix bugs, and improve application performance.\n- Conduct thorough testing of mobile applications to ensure high quality and user satisfaction.\n- Stay up-to-date with emerging trends and technologies in mobile development.\n- Participate in code reviews and contribute to a positive and collaborative team culture.\n\n- 1 years of experience in mobile application development, with a strong portfolio of applications developed.\n- Strong experience in Swift/Objective-C or Java/Kotlin programming languages.\n- Proficiency in using popular mobile app development frameworks such as React Native.\n- Understanding of RESTful APIs, JSON, and other web technologies.\n- Experience with version control systems such as Git or SVN.\n- Excellent problem-solving skills and attention to detail.\n- Ability to work independently and in a team environment.\n- Good communication and interpersonal skills.\n- Intermediate or higher graduation\n\n- Opportunity to work with an experienced team and gain valuable experience in testing across various platforms.\n- Performance-based bonuses twice a year.\n- Training on the Scrum framework and how to write effective test cases.\n- Opportunities for professional growth and improvement of skills.\n- Work in an open, friendly, and professional environment.\n- Enrollment in life insurance and premium health insurance plans after a period of long-term commitment to our company.\n\n- Khánh Hoà: Công ty WIDOSOFT, 23 Thái Nguyên, Phước Tân, Nha Trang, TP Nha Trang\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khánh Hoà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2435, 1300, 2, 'Senior Tester', 'Mô tả công việc\n- Review and clarify customer and business requirements.\nCollaborate closely with the development team to develop, maintain, and execute manual test cases.\nWork with business/requirement analysts to write and execute operational test scenarios.\n- Perform exploratory testing to detect potential issues not covered by formal test cases.\n- Report, track, and monitor bugs in the defect tracking system.\n- Update and maintain test documentation, including test plans, test cases, and test reports.\n- Estimate effort and time required for testing activities.\n\nYêu cầu ứng viên\n- At least 4 years of experience as a QA/QC or tester in software development projects.\n- Strong experience in writing test cases using black-box testing techniques.\n- Solid understanding of software development and testing processes.\n- Good knowledge of SQL and data modeling.\n- Strong analytical skills and a detail-oriented, structured working approach.\n- Ability to work independently as well as collaboratively within a team.\n- Able to understand spoken and written English in a working environment.\n- Familiarity with testing methodologies and tools.\n\nQuyền lợi\n- Performance bonus\n- 23 annual leave days per year (Annual/Birthday/Sick/Christmas/mental world leave)\n- 05 cub care leave days\n- 04 training leave days\n- 100% full of income in Probation\n- 100% Full of social insurance\n- Join Football, Ping-pong, Foosball, Clubs\n- Spring & Summer & Birthday Teambuilding trip\n- Free snacks & beverages\n- Private health insurance package: Golden Card of AON insurance\n- Team building activities\n- Highly talented and dynamic team\n- Travel opportunities\n\nĐịa điểm làm việc\n- Hà Nội: 165 Bà Triệu, Lê Đại Hành, Hai Bà Trưng\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n8:00 - 17:00\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2436, 1171, 2, 'Android Developer (Junior Level)', '-Key Responsibilities :\nDevelop and maintain Android applications using Java or Kotlin.\nWrite clean, well-documented, and testable code.\nCollaborate with the team to design, implement, and test new features.\nTroubleshoot and fix bugs.\nEnsure application performance, quality, and user experience.\nStay up-to-date with the latest Android technologies and best practices.\n\n-Requirements:\nUniversity graduate with computer science, software, application programming related major.\nGood background knowledge about Design pattern, Data structures and Algorithms.\nGood for logical thinking and problem-solving.\nAbility to self-learn and adapt to new technologies quickly.\nBeing able to use English for work.\nExperience in native Android development with Java/Kotlin.\nKnowledge of Android SDK, different versions of Android, and how to deal with different screen sizes.\nUnderstanding of Object Oriental Programming, Data Structures & Algorithms.\nExperience with REST/SOAP-based web services, AJAX and JSON.\nExperience with source code control systems such as SVN, CVS or Git.\nGood familiarity with third-party libraries and APIs, such as OKHTTP, RxJava, Firebase, Coroutine.\nKnowledge of security and experience in writing secure and efficient codes.\nExperience in implementing & maintaining Android Continuous Integration and Deployment process.\n\n-Benefits:\nCompetitive negotiable salary\nFull benefits package (Health care insurance, Life Insurance, Social Insurance etc.)\nSupportive team environment that values collaboration and growth\nCompany trips, Happy lunch (twice a month), Milk-tea fund...\n\n- Đà Nẵng: Astraler Technology Co. Ltd - 6th Floor - Viet Nam Post Building - 271 Nguyen Van Linh street, Vinh Trung ward, Thanh Khe District, Danang, Thanh Khê\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nWorking Hours: 8:00 AM – 5:30 PM, Monday to Friday\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2437, 1301, 2, 'Trưởng Phòng Gia Công CNC', '- Tổ chức sắp xếp công việc gia công đảm bảo : Tiến độ, chất lượng, hiệu suất, chi phí.\n- Phối hợp với kỹ thuật lập trình & NVVH kiểm soát quá trình gia công đạt yêu cầu.\n- Quản lý, đào tạo và phát triển năng lực chuyên môn cho nhân sự trong bộ phận.\n- Quản lý và sử dụng máy móc, thiết bị, công cụ & vật tư tiêu hao cho tối ưu hiệu quả.\n- Thực hiện các công việc khác khi được cấp trên yêu cầu.\n\nYêu cầu ứng viên:\n- Tốt nghiệp THPT trở lên, nhanh nhẹn, nhiệt tình trong công việc;\n- Trung thực, trách nhiệm, hòa đồng & kỷ luật tốt;\n- Đọc tốt bản vẽ kỹ thuật, Lập trình 2D+3D. Sử dụng thành thạo phần mềm CAD/CAM , Solidworks\n- Có kinh nghiệm quản lý gia công CNC.\n- Có kinh nghiệm gia công các sản phẩm chi tiết máy cho khách hàng Nhật, Hàn.\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, Hass\n\nQuyền lợi:\n- Có cơ hội phát triển tương lai tại công ty.\n- Làm việc trong môi trường năng động, chuyên nghiệp; \n- Cung cấp trang thiết bị đầy đủ để phục vụ công việc;\n- Thưởng các dịp Quốc tế Lao động 1/5, Quốc khánh 2/9, Tết dương lịch, Thưởng Tết theo quy định của công ty\n- Được đóng đẩy đủ BHXH, BHYT, BHTN;\n- Đi du lịch nghỉ mát hàng năm; \n- Tham gia các hoạt động văn hoá thể thao (bóng đá, chạy...);\n- Hỗ trợ ăn cơm trưa tại Công ty;\n- Hỗ trợ tiền điện thoại, công tác phí khi đi gặp Khách Hàng, đi công tác;\n- Nghỉ chủ nhật và 1 thứ 7 trong tháng.\n- Hỗ trợ 400,000VND tiền chuyên cần nếu đi làm đủ số ngày làm việc của tháng.\n\nĐịa điểm làm việc:\n- Hà Nội: Lô 5 +6 KCN Lai Xá, Xã Kim Chung, Hoài Đức\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nNghỉ các chủ nhật và 1 thứ 7 cuối tháng\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2438, 1146, 2, 'Mobile Flutter Developer (Junior) - Lĩnh Vực Edtech - Up To 15M', 'Mô tả công việc\n- Trực tiếp tham gia phát triển các dự án phần mềm trọng điểm của công ty về lĩnh vực giáo dục và các lĩnh vực khác\n- Tham gia phân tích, thiết kế luồng phát triển của ứng dụng di động dựa vào yêu cầu của khách hàng, công ty.\n- Tham gia phát triển ứng dụng di động trên nền tảng Flutter.\n- Đánh giá, phân tích, nâng cấp và tối ưu mã nguồn trong quá trình phát triển.\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai.\n- Tham gia đưa ra những ý tưởng, giải pháp mới cải thiện công việc cũng như góp phần tăng doanh thu cho công ty.\n\nYêu cầu ứng viên\n- Có kinh nghiệm lập trình Flutter/ Dart.\n- Nắm vững các khái niệm lập trình hướng đối tượng OOP, State Management.\n- Có kinh nghiệm về xử lý UI/ UX và các animation.\n- Có kinh nghiệm làm theo thiết kế từ Figma.\n- Có kinh nghiệm sử dụng Git (Gitlab/ Bitbucket/ Azure Devops).\n- Có kinh nghiệm xử lý với Bloc, Provider hoặc GetX.\n- Ưu tiên đã có sản phẩm/ dự án thực tế bằng Flutter.\n- Ưu tiên biết sử dụng thành thạo XCode để build ứng dụng.\n- Có kinh nghiệm trong việc launching sản phẩm lên App Store hoặc Google Play.\n- Có kinh nghiệm sử dụng và triển khai các thư viện như: Google Firebase,\n- Có hiểu biết REST APIs, quen thuộc với tất cả các kiến trúc hiện đại (MVP, MVVM, Redux, ...).\n\nQuyền lợi\n- Mức lương (gross): up to 15 triệu/tháng\n- Thưởng sinh nhật, thưởng các dịp Lễ, Tết trong năm\n- Chế độ BHXH, BHYT, BHTN đầy đủ ngay sau khi ký HĐ chính thức\n- Khám sức khoẻ định kỳ hàng năm\n- Trang bị máy tính hiện đại phục vụ công việc\n- Quỹ Team Building lên tới 2.400.000 VNĐ/người/năm\n- Du lịch nghỉ dưỡng hàng năm\n- Trà chiều với bánh, hoa quả và đồ ăn vặt miễn phí hàng tuần\n- Cơ hội tiếp cận với các doanh nghiệp, dự án lớn, xu hướng công nghệ và nền tảng mới nhất\n- Được tham gia các lớp đào tạo, khóa học chuyên môn để phát triển kỹ năng\n- Lộ trình thăng tiến lên Middle/Senior/Leader rõ ràng.\n- Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung & trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc\n- Học tiếng Anh hoàn toàn miễn phí & ưu đãi học phí cho người thân.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2439, 1246, 2, 'Software Internship', 'Chương trình tuyển dụng và đào tạo tài năng trẻ khối ngành Công nghệ thông tin từ một trong những Công ty hàng đầu lĩnh vực IT toàn cầu đã quay trở lại!!!\nLỘ TRÌNH TUYỂN DỤNG:\nVòng 1: Đơn đăng ký (01/06 - 22/06)\nVòng 2: Phỏng vấn (02/07)\nVòng 3: Đào tạo và thi tuyển (14/07 - 05/09)\nVòng 4: Kí hợp đồng chính thức và training on job (09/2025)\n\n• Là sinh viên năm cuối hoặc đã tốt nghiệp Đại học chưa quá 02 năm, ưu tiên các chuyên ngành Công nghệ thông tin hoặc các chương trình đào tạo liên quan đến lập trình và kỹ thuật phần mềm\n• Có định hướng trở thành lập trình viên, mong muốn phát triển lâu dài trong lĩnh vực công nghệ phần mềm\n• Có thể làm việc fulltime khi tham gia chương trình\n• Nắm vững kiến thức nền tảng về cấu trúc dữ liệu, thuật toán và thành thạo ít nhất một ngôn ngữ lập trình (Java, C++, Python,...)\n• Thái độ cầu tiến, ham học hỏi, năng động và sẵn sàng thử thách\n\n• Mức trợ cấp cực kì hấp dẫn trong thời gian đào tạo\n• Cơ hội trở thành nhân viên chính thức sau 08 tuần đào tạo, với mức thu nhập cùng đãi ngộ vượt trội, lên đến 17 tháng lương/ năm\n• Lộ trình đào tạo và phát triển toàn diện được dẫn dắt bởi đội ngũ mentor giàu kinh nghiệm\n• Cơ hội tham gia các dự án quy mô quốc tế, phát triển, vận hành các hệ thống phần mềm của Tập đoàn Samsung trên toàn cầu, với đa dạng các lĩnh vực: điện tử, điện toán đám mây, trí tuệ nhân tạo, nhà máy thông minh, logistics,...\n• Khai phá tiềm năng với các khóa đào tạo chuyên sâu về chuyên môn, khóa học theo nguyện vọng cá nhân\n• Môi trường đa văn hóa, năng động, sáng tạo và tràn đầy nhiệt huyết\n• Địa điểm làm việc: Văn phòng Samsung SDS Vietnam tại Hà Nội, tòa PVI, Số 1 Phạm Văn Bạch, Yên Hòa, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nMonday-Friday with flexible check-in time\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2440, 209, 2, 'Senior Workato Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\nJOB OVERVIEW\n• We are looking for a Senior Workato Developer to design, build, and maintain enterprise-grade automation and integration workflows using the Workato platform. The ideal candidate will have hands-on experience in automating complex business processes, connecting APIs, and developing reusable components to scale automation across departments and systems.\nRESPONSIBILITIES\n• Design and develop robust integrations and automation using Workato recipes, connectors, and Workato SDK.\n• Collaborate with business analysts and stakeholders to translate requirements into scalable solutions.\n• Create custom connectors and adapters using Workato SDK when required.\n• Monitor, maintain, and optimize integrations for performance, error handling, and scalability.\n• Integrate systems such as Salesforce, NetSuite, SAP, Workday, ServiceNow, Slack, Microsoft 365, databases, and custom APIs.\n• Implement Workato best practices, governance models, and reusable components (lookup tables, recipes, environments).\n• Maintain documentation, recipes version control, and change management processes.\n• Provide mentorship and support to junior automation developers and ensure code quality.\nYêu cầu ứng viên\n• Bachelor’s degree in Computer Science, Engineering, Information Systems, or related field.\n• 5+ years of experience in integration development, with at least 2+ years on Workato.\nStrong expertise with:\n• Workato Recipes, Triggers, Actions, Lookup Tables, and Formula mode\n• Workato SDK for creating custom connectors (Node.js, HTTP, JSON, etc.)\n• REST/SOAP APIs and webhooks\n• OAuth2, JWT, and other authentication methods\n• Experience with scripting languages (JavaScript, Python) to support advanced logic.\n• Familiarity with relational databases (SQL), file systems (CSV/XML/JSON), and cloud storage.\n• Proficient in API testing tools (Postman, Swagger, etc.).\n• Understanding of common business applications: ERP, CRM, HRIS, ITSM, etc.\n• Strong debugging, logging, and error-handling practices.\n• Workato certifications (e.g., Workato Automation Pro II/III, Workato Integration Specialist).\n• Experience with other iPaaS platforms (MuleSoft, Boomi, Zapier, Tray.io) is a plus.\n• Experience in industries like healthcare, insurance, finance, or e-commerce with domain-specific integration challenges.\n• Understanding of secure data practices, PII protection, HIPAA or GDPR compliance (as applicable).\n• Familiarity with CI/CD pipelines, Git, and Agile delivery methodologies.\nQuyền lợi\n• Attractive salary. Performance based award.\n• Go onsite in Singapore.\n• FPT Care insurance plan tailored for FPT employees\n• Attractive annual summer vacation allowance\n• Sponsored training courses for personal growth and up to 100% coverage for certification costs\n• Global and inclusive workplace with monthly cross-cultural events\n• International exposure and career growth across global locations\n• Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\nĐịa điểm làm việc\n- Hà Nội: FPT Building, 17 Duy Tân Str., Cầu Giấy District, Hanoi, Cầu Giấy\n- Nước Ngoài\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Nước Ngoài', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2441, 1302, 2, 'Junior Salesforce Developer', 'Mô tả công việc:\n- Work closely with customers, business analysts, and architects to understand requirements and translate them into technical designs\n- Develop custom Salesforce components using Apex, LWC, Visualforce, SOQL, and Flow\n- Customize standard and custom objects, workflows, approval processes, and validation rules\n- Implement Salesforce integration with external systems via REST/SOAP APIs, middleware, or third-party connectors\n- Participate in technical planning, estimation, and code reviews\n- Ensure solutions follow Salesforce best practices and comply with security and performance requirements\n- Support data migration, sandbox deployment, and production rollout.\n\nYêu cầu ứng viên:\n- Basic understanding and some hands-on experience with Salesforce development.\n- Familiarity with Apex, LWC, Flow Builder, and Salesforce DX.\n- Exposure to Sales Cloud, Service Cloud, or other Salesforce modules.\n- Good understanding of Salesforce platform architecture, security, and governor limits.\n- Familiarity with or exposure to Salesforce integrations with external systems (REST/SOAP APIs, middleware)\n- Familiarity with CI/CD tools for Salesforce (Gearset, Copado, Jenkins, etc.)\n- Experience with Agile/Scrum methodologies\n- Good communication skills and a collaborative mindset.\n- A strong desire to learn and grow within the Salesforce ecosystem.\n\nCertifications:\n- Preferred: Salesforce Platform Developer I\n- Nice to have: Platform Developer II, Sales Cloud Consultant, Service Cloud Consultant, JavaScript Developer I, Sharing & Visibility Designer, Integration Architect\n- Bonus: Application Architect, System Architect (part of CTA path), Admin or Advanced Admin\n\nPreferred Qualifications:\n- Experience working with public sector clients or in regulated environments\n- Prior experience in Salesforce Community Cloud / Experience Cloud\n- Knowledge of Data Loader, SOQL, and deployment tools\n- Background in JavaScript, HTML/CSS for LWC components\n- Familiarity with Salesforce AppExchange packages.\n\nQuyền lợi:\n- 5-day workweek\n- Young & vibrant working environment with great career development opportunities\n- Social insurance, medical insurance, unemployment insurance, are based on actual salary.\n- Yearly performance bonus (up to 2 months’ salary)\n- Regular team building events & internal activities (weekly happy hour, quarterly team building events, festival parties, etc.)\n\nĐịa điểm làm việc:\n- Hà Nội: 4th floor, Artemis Building, 3 Le Trong Tan Street, Khuong Mai Ward, Thanh Xuân\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2442, 1303, 2, 'Fresher .NET/JS/CSS', 'Mô tả công việc:\n- Tham gia nghiên cứu, phát triển sản phẩm phần mềm trong lĩnh vực Ngân hàng và Tài chính: Digital Banking.\n- Tìm hiểu tài liệu: Nghiệp vụ, yêu cầu và thiết kế của dự án tham gia.\n- Code các chức năng, module được phân công.\n- Phối hợp với team Test để kiểm tra lỗi, fix bug và hoàn thiện chức năng, sản phẩm.\n- Hỗ trợ khách hàng sau triển khai: Tiếp nhận yêu cầu, kiểm tra lỗi, sửa lỗi dữ liệu, sửa lỗi phát sinh trong quá trình khách hàng vận hành và sử dụng sản phẩm.\n- Các công việc khác theo phân công để đảm bảo cùng team hoàn thành dự án, công việc được giao.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, lập trình phần mềm.\n- Không yêu cầu kinh nghiệm, sinh viên mới tốt nghiệp được khuyến khích ứng tuyển. Ưu tiên ứng viên đã có kinh nghiệm thực tập.\n- Có kiến thức tổng quan về quy trình phát triển phần mềm và triển khai phần mềm. Tư duy lập trình hướng đối tượng.\n- Thành thạo ít nhất một ngôn ngữ lập trình backend về .Net/JS/CSS.\n- Có kiến thức cơ bản về cơ sở dữ liệu quan hệ SQL Server.\n- Hiểu biết về các hệ thống quản lý Jira, Microsoft Teams.\n- Khả năng làm việc độc lập và làm việc nhóm tốt.\n- Có khả năng học hỏi nhanh và thích ứng với công nghệ mới.\n- Kỹ năng giải quyết vấn đề và tư duy logic tốt.\n- Thành thạo đọc hiểu và viết tài liệu tiếng Anh chuyên ngành.\n\nQuyền lợi:\n- Mức lương cạnh tranh và hấp dẫn, tùy thuộc vào kinh nghiệm và năng lực.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Được đào tạo và phát triển chuyên môn thường xuyên.\n- Cơ hội thăng tiến và phát triển nghề nghiệp rõ ràng.\n- Các chế độ phúc lợi đầy đủ theo luật lao động (BHXH, BHYT, BHTN).\n- Tham gia các hoạt động team building, nghỉ mát hàng năm.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 3 - AB - Imperia Garden, 203 Nguyễn Huy Tưởng, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2443, 1134, 2, 'Senior Backend Developer', 'Mô tả công việc:\n- Programming and developing company systems and applications.\n- Manage and develop integration services with core systems and other providers.\n- Manage and develop APIs on API Gateway to serve integration with partners.\n- Research, test, and apply new technology trends to development.\n- Maintain the operation of products and services within the scope of management.\n- Participate in business analysis, propose solutions and implementation plans to improve and increase the efficiency of projects during the working process.\n\nYêu cầu ứng viên:\n- College Graduate, major: Computer Science, IT.\n- At least 3 years’ experience working in software industry.\n- Plus/Optional: experience in consumer finance, insurance, banking industry.\n- SOLID  Computer Science fundamentals.\n- Experience in design patterns, database, micro-service, optimization.\n- Backend stack:  Java 8+(Must)/C/C#, NodeJS(must), Python, Lambda.\n- DB: Relational databases (must), NoSql, Redis.\n- Knowledge of Data Structure & Algorithms, OOP, Memory Management,  Design Patterns, SOLID.\n- Testing: CucumberJS, Jest, Mocha, Chai, Selenium – at least one.\n- Agile methodology (working in Scrum) using Gitlab/Jira.\n- Linux OS.\n- Plus/Optional: Docker(MUST), CI/CD,  Kubernetes, DevSecOps, Cloud AWS, Google Cloud, Message Queue, Kafka, Git flow.\n\nQuyền lợi:\n- Probation with 100% salary;\n- Official labor contract;\n- Social insurance, unemployment insurance, and health insurance;\n- 24/7 accident insurance;\n- Regular Medical Checkups;\n- Professional training courses;\n- 16 days leave /year;\n- 13th month salary, bonus and allowance.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2444, 1242, 2, 'Korean Bridge Software Engineer - Kỹ Sư Cầu Nối', 'Mô tả công việc: - Bridge in communication with Korean clients on all project-related matters - Analyze, clarify, and transfer client’s requests and requirements to project team members. - Control all project’s materials. - Manage or work closely with Delivery team/ sales team to monitor and control project. - Perform testing if needed. Yêu cầu ứng viên: [Required] - Bachelor\'s Degree - From 1 year of experience translating/interpreting in the IT field - Strong written and verbal communication skills in Korean - TOPIK 5 or higher - Strong written and reading in English (TOEIC 650) - Self-motivated and eager to learn (in business domain, software engineering, language). - High responsibility and teamwork spirit. [Nice to have] - Project management/BA/Tester experience. Quyền lợi: - Attractive salary and bonus will be discussed after going through CV & Interview - Review capacity annually and adjust salary increases according to work performance. - Health care: Premium health insurance, Annual health check-up - Young working environment - Good career development opportunities with interesting and challenging projects. - English, Korean, technical, soft skills training courses. - Opportunity to learn special courses from LG CNS, new technology and security. - Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.) - Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc. - Working hours: 8 hours from Monday - Friday (8:00 - 12:00 - 13:00 - 17:00)\n\nĐịa điểm làm việc: - Hà Nội: Tầng 15, Keangnam Landmark 72, Nam Từ Liêm\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm \'Ứng tuyển\' ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2445, 1117, 2, 'Backend Intern (NestJS / FastAPI)', 'Mô tả công việc\n- Tham gia vào dự án thật dưới sự hướng dẫn của mentor\n- Học và thực hành phát triển API sử dụng NestJS và FastAPI\n- Viết tài liệu kỹ thuật, unit test cho các module được giao.\n- Hỗ trợ fix bug, nâng cấp tính năng backend.\n- Học cách làm việc nhóm.\n\nYêu cầu ứng viên\n- Sinh viên năm 3 trở lên ngành CNTT hoặc liên quan\n- Đã từng làm project thực hành hoặc đồ án sử dụng Node.js hoặc Python\n- Biết sử dụng Git, REST API, database cơ bản (PostgreSQL/MongoDB).\n- Tư duy logic tốt, ham học hỏi, cầu tiến.\n- Ưu tiên:\n  - Từng thử qua NestJS, FastAPI là lợi thế lớn\n  - Có tinh thần tự học và khả năng đọc hiểu tài liệu tiếng Anh\n\nQuyền lợi\n- Hưởng mức hỗ trợ xứng đáng theo năng lực;\n- Được đào tạo bài bản, đầy đủ trước khi bắt đầu và trong suốt quá trình làm việc;\n- Được xem xét trở thành nhân viên chính thức sau quá trình học việc, thực tập tại công ty;\n- Có cơ hội làm việc trong môi trường chuyên nghiệp, trẻ trung và năng động.\n\nĐịa điểm làm việc\n- Thừa Thiên Huế: Tầng 6, số 2 Lê Quý Đôn, Tòa nhà Vietinbank, Phú Hội, Huế., TP Huế\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Internship', '2025-10-07 20:59:18.149534'),
	(2446, 1304, 2, 'Middle Backend Developer (Java)', 'Mô tả công việc\n- In charge of programming, error checking & reporting to line manager.\n- Participate in big Banking, Finance & Insurance projects.\n- Participate in developing projects using Java & other technologies.\n- Solutions:\n  - Banking and Finance.\n  - Insurance.\n  - Cross industries: (Paperless; CheckinPro; BPM Hub; Napas ACH; CIC Host to Host; DMS; eP2P; eInvoice; Agency Portal; LDMS products; eRecruitment; ConstructionEMS).\n- Work closely with Developers and PMs/Directors.\n- Solving issues and developing workarounds and alternative solutions.\n- Overseeing deployments and new releases.\n- Supporting training and motivating team members.\n\nYêu cầu ứng viên\n- Bachelor/ college’s degree in Computer Science, Information Technology or equivalent.\n- Knowledge/experience in Finance, Banking & Enterprise.\n- 3+ years of experience in Java development on Linux/Windows platform.\n- Experience in Java frameworks: Spring (Spring MVC, Spring Boot, Spring Security), Hibernate.\n- Experience in Web Service (RESTful, SOAP) and knowledge in queue processing (Active MQ, IBM MQ).\n- Experience in Java Application Servers, Database Servers.\n- Proficient in version control systems: Git, SVN.\n- Good knowledge of an objective oriented language (Java)\n- Good knowledge of web/application containers (Apache Tomcat, JBoss, IBM WebSphere ...) and web/application deployment.\n- Good skill at MS SQL Server programming (stored procedure, function, job, trigger, view).\n- Good skill in database design, database management, particularly MS SQL.\n- Solid understanding of the software development life cycle, Agile Scrum.\n- Working knowledge of HTML5, CSS3, React, Flutter, and JavaScript a plus.\n- Ability to work in a team and work independently.\n- Flexible, dynamic attitude and reliable.\n\nQuyền lợi\n- Competitive salary and benefits.\n- Working time: 8:00AM - 05:30PM, Monday – Friday.\n- 12 days of annual leave + 3 days of sick leave + 1 day of birthday per year.\n- Participated in social insurance, unemployment insurance, health insurance and full policies according to the labor law.\n- 13th month salary & bonus policies, allowances at the Company.\n- UNIT-Care health care insurance by level.\n- Salary increases according to company regulations or unexpected salary raise in case of outstanding ability.\n- Professional and dynamic working environment, unlimited promotion opportunities.\n- Opportunity to participate in many large projects in Vietnam & abroad.\n- Work on the latest technology platform.\n- Join in company trip, teambuilding & community activities.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 374 Võ Văn Tần, phường 5, Quận 3\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2447, 1305, 2, 'Nhân Viên Wordpress Developer', 'Mô tả công việc:\n•Tham gia xây dựng hệ thống website \n• Lập trình Web dựa trên mã nguồn WordPress.\n• Có kinh nghiệm về UI/UX\n• Xây dựng, chỉnh sửa hoặc bổ sung các tính năng cho Plugin của WordPress.\n• Nắm rõ đầu việc được phân bổ và báo cáo tiến độ cho quản lý.\n\nYêu cầu ứng viên:\n• Có kinh nghiệm tối thiểu 6 tháng làm việc, tham gia vào các dự án WordPress.\n• Bằng cấp: Không yêu cầu, quan trọng là năng lực.\n• Thành thạo lập trình PHP, có kiến thức về HTML/CSS, MySQL, JavaScript…\n• Đặc biệt am hiểu về mã nguồn WordPress (cài đặt, chỉnh sửa Theme, Plugin, Function,...).\n• Có đam mê với lập trình Web.\n• Ưu tiên ứng viên có khả năng Tiếng Anh và có kiến thức về SEO.\n\nQuyền lợi:\n• Mức Lương 8-11 triệu + Thưởng theo kết quả kinh doanh.\n• Được hưởng các chính sách phúc lợi, chế độ BHXH, BHYT, BHTN theo quy định\n• Đề xuất tăng lương 6 tháng 1 lần.\n• Du lịch nghỉ dưỡng, teambuilding 1 năm 2 lần \n• Văn phòng sạch sẽ, view đỉnh.\n• Môi trường làm việc năng động, trẻ trung, chuyên nghiệp, chủ yếu là GENZ.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 10, tòa BIDV 157 Cầu diễn, Bắc từ liêm, Bắc Từ Liêm.\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nThứ 7 được về sớm.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2448, 1306, 2, 'Full Stack Developer', 'Mô tả công việc\n- Lập trình các tính năng cho phần mềm ERP và các dịch vụ liên quan nằm trong hệ sinh thái chung của GOLAZY.\n- Tham gia xây dựng các component trong hệ sinh thái sản phẩm dựa trên nền tảng Core của GOLAZY phát triển.\n- Tham gia phân tích, hợp tác với các nhóm phát triển để xây dựng các nghiệp vụ trong sản phẩm khi được yêu cầu.\n- Tìm hiểu các công nghệ, tích hợp mới được giao để đưa vào áp dụng cho phần mềm khi phát sinh kế hoạch cập nhật sản phẩm theo yêu cầu.\n- Làm việc & phát triển bản thân trong các phòng kỹ thuật, tham gia vào hoạt động xây dựng các gói tính năng mới, bảo trì và tối ưu các tính năng cũ theo mô hình Agile Scrum.\n\nYêu cầu ứng viên\n- Tối thiểu một năm kinh nghiệm với vị trí Fullstack Developer hoặc tối thiểu một năm kinh nghiệm với vị trí Frontend/Backend Developer và có định hướng phát triển trở thành Fullstack Developer.\n- Hiểu và lập trình RESTful API, Background Job, PHP-Laravel\n- Kỹ năng: PHP, MySQL, Laravel, NextJS, VueJS, Docker, Design pattern\n- Có kinh nghiệm làm việc, thiết kế CSDL quan hệ như MySQL, Postgresql\n- Có kỹ năng xử lý vấn đề, tối ưu hóa, refactor, debug\n- Có kinh nghiệm làm việc theo phương pháp Agile/Scrum và sử dụng các công cụ hỗ trợ như KanBan, Gantt Chart, Project Manager, Git.\n- Có kỹ năng giao tiếp tốt, làm việc nhóm hiệu quả và có tinh thần học hỏi cao.\n- Chăm chỉ, đam mê lập trình, ham học hỏi kiến thức, công nghệ mới\n- Ưu tiên ứng viên đã từng làm việc trong môi trường product với các sản phẩm SaaS, ERP, HRM, CRM; hiểu rõ quy trình phát triển các sản phẩm này. Đặc biệt những hiểu biết về các phần mềm Base, 1Office, Zoho, Jira, Asana, VtigerCRM … là một lợi thế.\n\nQuyền lợi\n- Mức lương: Upto 20m++\n- Cơ hội tiếp cận với các công nghệ mới\n- Môi trường làm việc trẻ, năng động, đa văn hóa\n- Thưởng lương tháng 13\n- Review lương tối thiểu 2 lần/năm theo năng lực và đóng góp\n- Đóng BHXH đầy đủ theo quy định nhà nước.\n\nĐịa điểm làm việc\n- Hà Nội: Số nhà 76 đường 23 Khu đô thị thành phố Giao lưu, Bắc Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Thứ 7 (từ 09:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2449, 1307, 2, 'Mobile App Developer (React Native)', 'Mô tả công việc: \n- Phát triển ứng dụng mobile app cho người dùng app.\n- Tư vấn, phân tích, thiết kế.\n- Phát triển, kiểm thử, sửa lỗi.\n- Vận hành và bảo trì hệ thống.\n- Thực hiện đúng quy trình phát triển phần mềm.\n- Các công việc khác theo phân công của quản lý.\n\nYêu cầu ứng viên: \n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin các trường HUST, UET, PTIT.\n- Có từ 1 năm kinh nghiệm ở vị trí tương đương.\n- Có kinh nghiệm phát triển ứng dụng mobile app sử dụng lập trình React Native.\n- Có kinh nghiệm thiết kế UI/UX.\n- Có hiểu biết về kiến trúc ứng dụng IoT trong smart home, smart building phục vụ phát triển app cho hệ thống.\n- Sáng tạo, nhanh nhẹn, trung thực.\n- Sử dụng tiếng Anh tốt là một lợi thế.\n\nQuyền lợi: \n- Lương/thưởng theo chế độ của công ty.\n- Thưởng upto 3 tháng lương/năm.\n- Môi trường chuyên nghiệp, năng động, thân thiện, cơ hội thăng tiến.\n- Chế độ BHYT, BHXH theo Luật Lao động.\n- Khám sức khỏe định kỳ hàng năm.\n- Tham gia các hoạt động, sự kiện của công ty.\n- Tham gia các khóa đào tạo trong và ngoài nước.\n- Thời gian làm việc: Thứ 2 đến hết sáng thứ 7 (8h30-12h00; 13h00-17h30).\n\nĐịa điểm làm việc: \n- Hà Nội: Tầng 2, Tòa N09B2 Thành Thái, Cầu Giấy.\n\nCách thức ứng tuyển: \n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2450, 1183, 2, 'Web Developer', 'Mô tả công việc\n- Tham gia xây dựng giao diện web responsive (desktop, mobile).\n- Phát triển frontend cho các ứng dụng nội bộ và tương tác với API backend.\n- Tham gia tối ưu hiệu suất website, SEO cơ bản (với landing page).\n- Hỗ trợ cập nhật nội dung và thiết kế các form/flow/tool đơn giản phục vụ các chiến dịch marketing, chăm sóc khách hàng.\n- Viết tài liệu kỹ thuật và hướng dẫn sử dụng nội bộ.\n- Kiểm thử giao diện trên nhiều trình duyệt và thiết.\n- Quản lý source code (Git), tham gia đánh giá code, triển khai môi trường staging/production.\n\nYêu cầu ứng viên\n- Có từ 1 năm kinh nghiệm trong vai trò Web Developer.\n- Biết HTML5, CSS3, JavaScript thuần và ít nhất 1 frontend framework (React, Angular...).\n- Có khả năng làm việc với REST API, hiểu được cách gửi – nhận dữ liệu.\n- Cẩn thận, logic, có trách nhiệm với code và UI.\n- Có kinh nghiệm làm việc với hệ thống loyalty, CRM hoặc các site e-commerce là một lợi thế.\n- Biết về thiết kế giao diện (Figma, Canva, Photoshop) là điểm cộng.\n- Ưu tiên nếu từng làm trong ngành bán lẻ/F&B hoặc startup.\n\nQuyền lợi\n- Được hưởng các chế độ BHXH, thưởng lễ, tết, thưởng lương tháng 13.\n- Được làm trong môi trường trẻ, năng động.\n- Được tham gia các hoạt động đoàn thể của Công ty: Teambuilding, thăm quan, du lịch...\n- Mua sản phẩm với giá ưu đãi.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 38 Hoa Mai, Phú Nhuận\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2451, 1308, 2, 'Nhân Viên Lập Trình', '- Tham gia các dự án phát triển các dự án Website, thương mại điện tử;\n- Nghiên cứu các công nghệ mới, hỗ trợ phát triển, khắc phục lỗi hệ thống;\n- Xây dựng và chỉnh sửa các module, tính năng theo yêu cầu;\n- Các công việc khác theo phân công của cấp trên.\n\nYêu cầu ứng viên:\n- Có kiến thức về codegym\n- Có kinh nghiệm lập trình Backend sử dụng java;\n- Có kinh nghiệm lập trình Front end (web) trên nền tảng Spring framework;\n- Ưu tiên người có kinh nghiệm về một trong các nền tảng Spring framework, Angular, AngularJs, React;\n- Có khả năng sử dụng query cơ bản trên MySQL, Oracle;\n- Có khả năng sử dụng Shell Script và câu lệnh cơ bản trên Linux.\n- Cẩn thận, kiên nhẫn, đam mê lập trình và sẵn sàng học hỏi các công nghệ mới.\n- Chịu được áp lực công việc.\n- Có kỹ năng phân tích và giải quyết vấn đề, có khả năng làm việc độc lập và theo nhóm.\n\nQuyền lợi:\n- Mức lương cạnh tranh: 10 – 20M.\n- Con đường sự nghiệp vững vàng, môi trường làm việc năng động, nhanh nhẹn.\n- Được đào tạo theo định hướng công việc của Công ty và nhu cầu đề xuất cá nhân.\n- Thưởng KPI, Thưởng dự án, Thưởng hiệu quả công việc, thưởng cuối năm tháng 13+++…\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc.\n- Được hưởng BHXH, BHYT, BHTN theo chế độ nhà nước ban hành.\n- Khám sức khỏe định kỳ 1 năm/1 lần.\n- Được tham gia các hoạt động thể dục thể thao như: Bóng đá, cầu lông,…\n- Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding thường xuyên.\n- Làm việc từ thứ 2 đến thứ 6, nghỉ thứ 7 và CN;\n- 12 ngày phép/năm và các ngày nghỉ lễ - tết theo quy định;\n\nĐịa điểm làm việc:\n- Hà Nội: 118/6 Nguyễn Khánh Toàn, Cầu Giấy\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nThứ 7 làm 1 ngày đầu tiên của tháng\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2452, 1309, 2, 'Nhân Viên Lập Trình Tự Động Hóa', 'Mô tả công việc\n- Thực hiện các công việc kỹ thuật liên quan đến sản xuất và lắp ráp các sản phẩm cơ khí.\n- Đọc và hiểu bản vẽ kỹ thuật, sơ đồ lắp ráp.\n- Sử dụng các dụng cụ, máy móc cơ khí để gia công, chế tạo sản phẩm.\n- Kiểm tra chất lượng sản phẩm trước khi bàn giao.\n- Tuân thủ các quy trình an toàn lao động trong quá trình làm việc.\n- Thực hiện các nhiệm vụ khác được phân công bởi quản lý.\n\nYêu cầu ứng viên\n- Không yêu cầu kinh nghiệm.\n- Có kiến thức cơ bản về vật liệu, công nghệ gia công cơ khí.\n- Có khả năng sử dụng các dụng cụ, máy móc cơ khí cơ bản.\n- Khả năng đọc hiểu bản vẽ kỹ thuật.\n- Cẩn thận, tỉ mỉ, có trách nhiệm trong công việc.\n- Khả năng làm việc nhóm và tuân thủ kỷ luật.\n- Sức khỏe tốt, có thể làm việc trong môi trường nhà xưởng.\n\nQuyền lợi\n- Thu nhập từ 15 tới 18 triệu / tháng\n- Được đóng bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật.\n- Có chế độ nghỉ phép, nghỉ lễ, tết theo quy định.\n- Môi trường làm việc năng động, chuyên nghiệp.\n- Cơ hội được đào tạo, nâng cao tay nghề.\n- Thưởng các ngày lễ, tết, thưởng hiệu quả công việc.\n\nĐịa điểm làm việc\n- Bắc Giang: Tổ dân phố Phúc Long, Phường Tăng Tiến, Việt Yên\n\nThời gian làm việc\n- Thứ 2 - Chủ nhật (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2453, 1310, 2, 'Lập Trình Viên', 'Mô tả công việc\n- Sử dụng thành thạo phần mềm Mastercam để lập trình gia công cho máy CNC (Phay/ Tiện).\n- Phân tích bản vẽ kỹ thuật, đọc hiểu yêu cầu kỹ thuật từ bộ phận thiết kế.\n- Thiết kế đường chạy dao, chọn dụng cụ cắt và thông số gia công tối ưu.\n- Mô phỏng chương trình, kiểm tra lỗi va chạm, đảm bảo an toàn và độ chính xác trước khi chuyển sang sản xuất.\n- Phối hợp với bộ phận vận hành máy để hiệu chỉnh chương trình khi cần thiết.\n- Cải tiến chương trình nhằm tăng năng suất, giảm thời gian gia công và hao mòn dao cụ.\n- Chế tạo đồ gá và công cụ hỗ trợ gia công khi gặp những chi tiết phức tạp.\n- Quản lý và lưu trữ dữ liệu chương trình, bản vẽ, tài liệu kỹ thuật có liên quan.\n- Hỗ trợ đào tạo và hướng dẫn kỹ thuật cho nhân viên vận hành máy (nếu cần).\n- Thực hiện các công việc khác theo sự phân công của quản lý.\n\nYêu cầu ứng viên\n- Tốt nghiệp Trung cấp, Cao đẳng, Đại học chuyên ngành Cơ khí chế tạo máy, Cơ điện tử hoặc tương đương.\n- Kinh nghiệm: Tối thiểu 2 năm kinh nghiệm lập trình Mastercam (ưu tiên ứng viên từng làm trong lĩnh vực gia công khuôn mẫu, chi tiết cơ khí chính xác).\n- Thành thạo phần mềm Mastercam (phiên bản X8 trở lên), biết sử dụng thêm các phần mềm hỗ trợ như SolidWorks, AutoCAD là lợi thế.\n- Có kiến thức tốt về công nghệ cắt gọt kim loại, vật liệu gia công, dụng cụ và thông số cắt.\n- Đọc hiểu bản vẽ kỹ thuật cơ khí tiêu chuẩn ISO/JIS.\n\nQuyền lợi\n- Thu nhập hấp dẫn: Lên đến 18.000.000 triệu/tháng\n- Thời gian làm việc: từ Thứ 2 đến Thứ 6 (7h30-16h30); Thứ 7 làm luân phiên.\n- Được hỗ trợ cơm trưa tại văn phòng\n- Thưởng lương tháng 13, lễ tết, thưởng đột xuất, quà thiếu nhi 1/6,...\n- Được hưởng các chính sách phúc lợi: khám sức khỏe định kỳ hằng năm, sinh nhật cá nhân, hiếu hỉ, Team-building hằng năm và các hoạt động tập thể... do công ty tổ chức.\n- Tham gia đầy đủ BHXH, BHYT, BHTN, BH tai nạn 24/24 và BHSK.\n- Lương cạnh tranh theo năng lực và được xét tăng lương mỗi năm 1 lần (dựa trên kết quả hoạt động kinh doanh của cty).\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Lô IV-19 (KCN Tân Bình) Đường Tây Thạnh, Phường Tây Thạnh, Tân Phú\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 07:30 đến 16:30)\n- Nghỉ thứ 7 cách tuần\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2454, 1311, 2, 'Mobile App Developer', '- Phân tích yêu cầu và thiết kế kiến trúc ứng dụng đa nền tảng.\n- Phát triển mã nguồn bằng ngôn ngữ Dart (sử dụng Flutter), JavaScript (sử dụng React Native).\n- Tối ưu hóa hiệu suất và đảm bảo ứng dụng tương thích trên IOS/Android.\n- Tham gia họp dự án, báo cáo tiến độ và đề xuất giải pháp kỹ thuật khi cần thiết.\n- Cập nhật các xu hướng và công nghệ mới trong lĩnh vực phát triển ứng dụng di động.\n- Áp dụng các công nghệ tiên tiến để cải thiện chất lượng và hiệu suất của ứng dụng.\n\n- Tốt nghiệp Đại học ngành Công nghệ thông tin chuyên ngành phát triển ứng dụng di động.\n- Có 1-3 năm kinh nghiệm phát triển ứng dụng IOS/Android bằng Flutter hoặc React Native (ưu tiên ứng viên có kinh nghiệm về project tương tự).\n- Hiểu biết về thiết kế UI/UX đa nền tảng.\n- Kinh nghiệm làm việc với API và dịch vụ backend.\n- Biết tiếng Anh, sử dụng tiếng Anh trong công việc (Toiec 650 trở lên, Ielts 5.0 trở lên).\n- Có kỹ năng quản lý thời gian, sắp xếp công việc, làm việc độc lập và hợp tác tốt với đội nhóm.\n- Tận tâm, cầu thị có trách nhiệm, chủ động và tích cực trong công việc.\n- Thái độ tốt, lắng nghe, phản hồi tích cực, đổi mới và phát triển.\n\n- Thu nhập: 15.000.000 - 18.000.000 vnđ/tháng (lương cơ bản 10 - 15tr/tháng, được deal theo năng lực và kinh nghiệm làm việc).\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp\n- Văn hóa tích cực, tinh thần đồng đội, lắng nghe, chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện qua các khoá học do công ty hỗ trợ.\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn, cơ hội phát triển trong thị trường nước ngoài, được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Các phúc lợi khác (du lịch, sinh nhật, thưởng lễ tết, BHXH, phép năm,…) theo quy định của pháp luật.\n\n- Đà Nẵng: 14 Bình Minh 3, Hải Châu\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Lịch làm từ thứ 2 đến thứ 7 (làm xen kẽ 2 thứ 7/tháng)\n- Sáng: 8h00-11h30\n- Chiều: 13h30-17h30\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2455, 1193, 2, 'Web Developer', 'Mô tả công việc\n- Develop and maintain Web apps using Java Spring Boot.\n- Work directly with remote team to clarify tasks and requirements.\n- Develop new features based on the user requirements (analyzing requirements and system design).\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance.\n- Managing time and resources based on the WBS.\n- Write high-quality, clean, elegant, maintainable, and testable code.\n- Maintaining technical documents up-to-date.\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the Kiwoom Framework for Kiwoom Indonesia, Finansia(in Thailand), and so on.\n\nYêu cầu ứng viên\n- Education & Technical skills\n  - Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n  - At least 3 years of relevant experience in Java development, Spring Framework and SQL.\n  - Experience and knowledge in markup language, including HTML, CSS.\n  - Experience with frontend JavaScript.\n- Soft Skills & Communication\n  - Able to communicate in English, written and spoken.\n  - Strong problem-solving and analytical skills.\n  - Strong communication skills and teamwork, international experience is preferred.\n- Nice to have\n  - Understand of API design and implementation.\n  - Ability to write clean, easy to understand code.\n  - Familiarity with version control systems, such as Git or SVN.\n  - Familiarity with issues tracking tools, such as Redmine.\n  - Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nQuyền lợi\n- Income & Achievement\n  - Competitive salary, salary review once a year\n  - 13th month salary and Annual Performance Bonus\n  - MVP and Shining star awards at the end of year\n  - Global and professional working environment\n- Workplace Happiness\n  - Full SHUI as Vietnamese Law\n  - Premium Private Medical Insurance PVI and annual health check\n  - 15-day annual leave\n  - 01-day Christmas off and 90-min menstrual leave for women\n  - Company trip, YEP and monthly gathering time\n  - Gifts on special occasion and fully stocked snack corner\n  - Sponsored training courses and book purchase quarterly\n  - Be well-equipped with new working equipment\n- SPECIAL OFFER\n  - Providing training and education experience in Korea with Korean Finance/IT expert\n  - Providing opportunities to work and support in IT/Finance fields overseas\n\nHIRING PROCESS:\nThe interview will be conducted at our office in Ho Chi Minh city.\nRound 1:\n- Step 1: Live coding test\n- Step 2: Interview with part team leader (upon passing coding test)\n- Step 3: Interview with Director\n\nRound 2: Final interview with Head Office in Korea\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tầng 14, tòa nhà AP, 518B Điện Biên Phủ, Phường 21, Bình Thạnh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2456, 1312, 2, 'Kỹ Sư Phát Triển Phần Mềm', 'Mô tả công việc:\n- Tham gia và được đào tạo trong quá trình nghiên cứu phát triển sản phẩm điện tử trên ô tô\n- Phát triển MCU/AP Bootloader\n- Thiết kế AUTOSAR và MCU SW\n- Phát triển Embedded linux/RTOS BSD/middleware\n- Phát triển PC Tools điều khiển simulator (CAN/Ethernet)\n- Sử dụng ứng dụng auto process (CMMI, ISO26262, A-spice) software\n- Phối hợp với các thành viên trong dự án để đảm bảo dự án thành công và đúng tiến độ.\n- Nghiên cứu và áp dụng các công nghệ mới.\n\nYêu cầu ứng viên:\nBắt buộc:\n- Tốt nghiệp đại học các chuyên ngành CNTT, Kỹ thuật Điện-Điện tử, Kỹ thuật Cơ điện tử, Kỹ thuật Điều khiển và tự động hoá\n- Thành thạo ngôn ngữ lập trình C/C++\n- Có kinh nghiệm lập trình cho các dòng vi điều khiển 8, 16, 32 bit.\n- Giao tiếp thành thạo tiếng Anh, đọc hiểu các tài liệu chuyên ngành\n\nƯu tiên:\n- Có kinh nghiệm lập trình với ngôn ngữ C#\n- Có kinh nghiệm phát triển giao thức CAN/Ethernet trên tầng ứng dụng\n- Có kinh nghiệm phát triển UI/QT\n- Có kinh nghiệm phát triển bộ điều khiển xe ô tô (ECU) software.\n- Có khả năng phát triển PC Tools điều khiển simulator (CAN/Ethernet) là một lợi thế.\n- Có khả năng tiếp thu và vận dụng công nghệ mới.\n- Cởi mở trong giao tiếp, sẵn sàng tiếp nhận góp ý từ người khác.\n- Khả năng làm việc nhóm và độc lập.\n- Trung thực, có tinh thần trách nhiệm cao, khả năng chịu áp lực công việc tốt.\n\nQuyền lợi:\n- Được hưởng đầy đủ mọi chế độ quyền lợi của người lao động theo đúng quy định của Pháp luật\n- Lương: Thỏa thuận (cạnh tranh hấp dẫn)\n- Được tham gia BHXH, BHYT, BHTN ngay sau khi ký hợp đồng lao động (trong cả thời gian thử việc)\n- Môi trường làm việc chuyên nghiệp, mức thu nhập thỏa đáng và cơ hội phát triển nghề nghiệp\n- Được tăng lương, thưởng theo hiệu quả công việc.\n- Ngoài mức lương thương lượng xứng đáng với khả năng của ứng viên, trong quá trình ứng viên làm việc tại Công ty sẽ được đánh giá năng lực thực tế và có chế độ đãi ngộ xứng đáng với các nỗ lực và đóng góp cho Công ty.\n- Có xe đưa đón CBCNV Hà Nội – Ninh Bình hàng ngày.\n\nĐịa điểm làm việc:\n- Ninh Bình: Lô CN1 KCN Phúc Sơn, phường Ninh Sơn, TP Ninh Bình\n- Nam Định\n- Thanh Hoá\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ninh Bình', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2457, 1313, 2, 'Lập Trình Viên AWS', 'We are seeking a highly skilled and experienced AWS Monitoring & Operation Specialist to oversee system operations, monitor infrastructure health, and ensure optimal performance and security. This role involves working within a customer-provided environment to deliver high-quality support and continuous improvement.\n\nKey Responsibilities:\n\nSystem Monitoring & Alert Management\n- Continuously monitor system health using tools such as Amazon CloudWatch, Prometheus, Zabbix, etc.\n- Respond promptly to alerts and incident notifications.\n- Investigate root causes and execute recovery actions.\n- Recommend and implement preventive measures to avoid recurrence.\n\nPerformance Optimization\n- Analyze system performance and resource utilization across EKS clusters, Aurora PostgreSQL databases, and OpenSearch node.\n- Propose and implement tuning strategies to enhance performance and optimize costs.\n\nBackup & Restoration\n- Perform and verify scheduled system backups.\n- Ensure reliable and timely recovery procedures in the event of system failures or incidents.\n\nAccount & Security Management\n- Manage user accounts, roles, and permissions.\n- Conduct access reviews, vulnerability assessments, and security audits.\n- Define, implement, and enforce security policies and standards.\n\nSystem Maintenance\n- Apply operating system and middleware updates as required.\n- Deploy security patches and perform batch update activities in a timely manner.\n\nTechnical Support & Consultation\n- Provide technical guidance and troubleshooting support to internal teams.\n- Contribute to the development and maintenance of operational documentation and best practices.\n\nRequired Skills & Qualifications:\n\nTechnical Skills:\n- Experience with AWS services (EC2, S3, RDS, IAM, CloudWatch, Lambda and especially EKS, Aurora PostgreSQL, and OpenSearch)\n- Experience with AWS CLI, SDKs, and Infrastructure as Code (e.g., CloudFormation, Terraform).\n- Strong Linux/Unix/Windows system administration skills.\n- Scripting and automation experience (e.g., Bash, Python, Ansible).\n- Knowledge of AWS security best practices, access control, and vulnerability scanning.\n- Experience with backup strategies and disaster recovery planning.\n\nSoft Skills:\n- Strong analytical and problem-solving skills.\n- Effective communication and documentation abilities in English.\n- Japanese communication and documentation skills are a plus.\n- Capable of working both independently and as part of a team.\n- Proactive and customer-focused mindset with a commitment to delivering quality support.\n\nExperience Requirements:\n- Hands-on experience in AWS system operations or cloud infrastructure management.\n- Track record in managing production environments with high availability and security requirements.\n- Experience in incident response, root cause analysis, and implementing preventive measures.\n- Experience in cost optimization and performance tuning in AWS environments.\n- Experience working in IT service management environments is a plus.\n- Experience supporting enterprise clients or working in a managed services environment is highly desirable.\n\nPreferred Qualifications:\n- AWS certifications (e.g., AWS Certified SysOps Administrator, Solutions Architect).\n- Experience with DevOps tools and CI/CD pipelines.\n- Familiarity with compliance standards (e.g., ITIL, ISO 27001, SOC 2, GDPR).\n\nBenefits:\n- Global working environment, Flexible working time.\n- 13 month salary bonus & performance bonus, review performance once a year.\n- Annual leave: 16 days per year\n- Full Insurances followed Vietnamese Labor Law.\n- Annual health check, Company Healthcare\n- Working equipment provided by the Company.\n- Allowance: Certificate, Language, Lunch, Transportation, Teambuilding.\n- Bonuses, Gifts for Holidays, Birthday party, Company trip.\n- Employee engagement activities.\n- Various Training Program and Interesting Team Building Activities.\n- Working time: Full-time (Mon-Fri) / Flexible check in from 7AM-9AM\n\nWorking Address:\n- Đà Nẵng: 06 Trần Phú, Hải Châu\n\nWorking Time:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nHow to Apply:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2458, 1314, 2, 'Senior .Net Developer', '1. Nội dung công việc\n- Xây dựng các ứng dụng phục vụ công việc tại Công ty bao gồm xây dựng và nâng cấp các phần mềm cho dự án nội bộ và các dự án phát triển đối tác.\n- Xây dựng phát triển hệ thống backend.\n- Tham dự vào các dự án Core và các dự án tái cấu trúc khác.\n- Triển khai và đào tạo cho các bộ phận liên quan trong Công ty.\n- Chịu trách nhiệm về tiến độ và kết quả công việc được giao.\n- Thực hiện các công việc khác theo yêu cầu của cấp trên.\n\n2. Thời gian làm việc: Từ 08h30 - 17h30, từ thứ 2 - thứ 6.\n\n3. Địa điểm làm việc: Tòa nhà G-Group, 5 Nguyễn Thị Duệ, Yên Hòa, Cầu Giấy, Hà Nội.\n\nYêu cầu ứng viên:\n- Tối thiểu tốt nghiệp Cao đẳng hoặc Chứng chỉ chuyên ngành CNTT.\n- Có ít nhất 3 năm kinh nghiệm phát triển trên môi trường .NET Core, ASP.NET MVC, C#.\n- Thành thạo HTML/CSS/Javascript.\n- Ưu tiên Có kinh nghiệm làm việc với một trong các ngôn ngữ kịch bản jQuery, Angular, Vue JS, ReactJs.\n- Có kiến thức về Design Pattern.\n- Có kinh nghiệm lập trình với các hệ cơ sở dữ liệu SQL Server, MySQL.\n- Có kinh nghiệm tối ưu code.\n- Có kinh nghiệm về nghiệp vụ ngân hàng tài chính là lợi thế.\n- Có khả năng phân tích và xử lý yêu cầu nghiệp vụ.\n- Kỹ năng sắp xếp công việc và quản lý thời gian hiệu quả.\n- Đề cao trách nhiệm trong công việc, ý thức chất lượng sản phẩm tốt.\n- Đam mê tìm tòi nghiên cứu học hỏi công nghệ mới, phát triển bản thân.\n- Ưu tiên ứng viên có thể đọc hiểu tài liệu tiếng Anh.\n- Hiểu biết và mong muốn làm việc trong một môi trường phát triển Agile, chuyên nghiệp.\n\nQuyền lợi:\n1. Chế độ chính sách:\n- Lương thưởng cạnh tranh trên thị trường.\n- Thưởng cuối năm + thưởng Lễ/Tết + thưởng sinh nhật + thưởng đột xuất khi hoàn thành tốt nhiệm vụ.\n- 12 ngày phép năm + phép thâm niên.\n- BHXH + chế độ bảo hiểm đặc biệt dành cho nhân viên (F88 Care).\n- Cơ hội tham gia gắn kết với tập thể thông qua các hoạt động văn hóa sôi động: Teambuilding, Tất niên, 8/3, 20/10, Giáng sinh...\n\n2. Môi trường làm việc:\n- Cơ hội làm việc tại Công ty Fintech về dịch vụ tài chính.\n- Được làm việc trong môi trường trẻ năng động, luôn coi Công nghệ thông tin là yếu tố trọng tâm để phát triển.\n- Áp dụng mô hình phát triển phần mềm theo Agile, Scrum.\n- Môi trường làm việc cởi mở và năng động với các giá trị cốt lõi sâu sắc truyền cảm hứng làm việc đến nhân viên.\n- Khuyến khích trao đổi ý tưởng, đề cao sự sáng tạo trong công việc.\n\n3. Cơ hội phát triển:\n- F88 cam kết cho bạn nền tảng vững chắc để học hỏi và phát triển.\n- Tham gia đào tạo bài bản, chuyên nghiệp từ Học viện F88.\n- Sẵn sàng trao quyền, cơ hội đột phá cho nhân viên.\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\nĐịa điểm làm việc: Hà Nội: 5 Nguyễn Thị Duệ, Cầu Giấy.\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2459, 1315, 2, 'Devops Engineer', 'Mô tả công việc\n1. Xây dựng & duy trì hạ tầng hiện tại\nCI/CD Pipeline: Thiết lập và duy trì các pipeline tự động hóa quy trình phát triển phần mềm, bao gồm GitHub Actions, GitLab CI, Jenkins, v.v.\nMôi trường triển khai: Quản lý và cấu hình môi trường staging và production, đảm bảo quá trình auto-deploy diễn ra an toàn và hiệu quả.\nCloud Infrastructure: Quản lý và tối ưu hóa hạ tầng trên các nền tảng cloud như AWS, bao gồm việc triển khai, giám sát và tối ưu hóa chi phí\n\n2. Giám sát & phản ứng nhanh với hệ thống\nMonitoring & Alerting: Thiết lập hệ thống giám sát với các công cụ như Prometheus, Grafana, Sentry, ELK Stack để theo dõi hiệu suất và phát hiện sớm sự cố.\nIncident Response: Phân tích và xử lý sự cố kịp thời, thực hiện root-cause analysis và cải tiến quy trình để giảm thiểu rủi ro trong tương lai.\n\n3. Bảo mật & ổn định\nQuản lý Secrets: Sử dụng các công cụ như Vault, AWS Secrets Manager để quản lý và bảo vệ thông tin nhạy cảm.\nAccess Control: Cấu hình và duy trì các chính sách bảo mật như security groups, tường lửa, Single Sign-On (SSO) để đảm bảo an toàn cho hệ thống.\n\n4. Tối ưu hệ thống\nHiệu suất & Chi phí: Theo dõi và phân tích hiệu suất hệ thống, đề xuất và triển khai các giải pháp tối ưu hóa để cải thiện hiệu suất và giảm thiểu chi phí vận hành.\nScalability: Làm việc chặt chẽ với các nhóm kỹ thuật để thiết kế và triển khai các kiến trúc hạ tầng có thể mở rộng (scale up, scale out) theo nhu cầu phát triển của công ty.\n\n5. Tự độ hoá & Infrastructure as Code (IaC)\nIaC: Sử dụng các công cụ như Terraform, Pulumi để tự động hóa việc triển khai và quản lý hạ tầng.\nDocumentation: Viết và duy trì tài liệu chi tiết về hạ tầng, quy trình triển khai và các best practices để đảm bảo tính nhất quán và dễ dàng bảo trì.\n\nYêu cầu ứng viên\nKinh nghiệm & Kiến thức\nKinh nghiệm: Có từ 2-3 năm kinh nghiệm thực tế trong lĩnh vực DevOps.\nCI/CD: Thành thạo trong việc thiết lập và duy trì các pipeline CI/CD, bao gồm việc tích hợp và triển khai tự động.\nCloud Platforms: Kinh nghiệm làm việc với ít nhất 1 trong các nền tảng cloud như AWS, GCP hoặc Azure.\nContainerization: Kinh nghiệm với Docker và Kubernetes, bao gồm việc triển khai và quản lý container trong môi trường sản xuất.\nScripting: Kỹ năng lập trình với ít nhất một ngôn ngữ như Bash, Python hoặc Go để tự động hoá các tác vụ và quy trình.\nNetworking: Kiến thức cơ bản về mạng, bao gồm DNS, VPN, firewall và các giao thức mạng phổ biến.\n\nKỹ năng bổ sung\nIaC: Kinh nghiệm với các công cụ Infrastructure as Code như Terraform hoặc Pulumi.\nMonitoring Tools: Kinh nghiệm với các công cụ giám sát như Prometheus, Grafana, Sentry hoặc ELK Stack.\nSecurity: Hiểu biết về các best practices bảo mật trong DevOps, bao gồm việc quản lý secrets, cấu hình quyền truy cập và bảo vệ hệ thống khỏi các mối đe doạ.\n\nTư duy & phẩm chất\nTư duy hệ thống: Khả năng phân tích và thiết kế các hệ thống phức tạp, đảm bảo tính ổn định và hiệu suất cao.\nChủ động & Trách nhiệm: Có khả năng làm việc độc lập, chủ động đề xuất giải pháp và chịu trách nhiệm với công việc của mình.\nKhả năng làm việc nhóm: Kỹ năng giao tiếp tiếp, có khả năng phối hợp hiệu quản với các nhóm kỹ thuật và không kỹ thuật trong công ty.\n\nQuyền lợi\nMức lương: 20.000.000 - 30.000.000\nMôi trường làm việc năng động: Làm việc trong một đội ngũ trẻ, năng động, với cơ hội học hỏi và phát triển nghề nghiệp\nSản phẩm có tầm ảnh hưởng: Tham gia phát triển các sản phẩm công nghệ giáo dục có ảnh hưởng sâu rộng tại Việt Nam.\nChế độ đãi ngộ hấp dẫn: Mức lương cạnh tranh, cùng các phúc lợi đầy đủ và môi trường làm việc linh hoạt.\n\nĐịa điểm làm việc\n- Hà Nội: Đường Đỗ Đức Dục, Mễ Trì, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2460, 1316, 2, 'Mobile Developer (Flutter)', 'Mô tả công việc:\n- Phân tích yêu cầu nghiệp vụ, tư vấn giải pháp kỹ thuật cho các sản phẩm mobile app.\n- Thiết kế kiến trúc tổng thể, luồng xử lý và giao diện người dùng cho ứng dụng mobile.\n- Trực tiếp tham gia phát triển, tối ưu hóa và tích hợp ứng dụng mobile với hệ thống backend và bên thứ 3.\n- Hướng dẫn, đào tạo và hỗ trợ kỹ thuật cho các thành viên trong team mobile.\n- Xây dựng và duy trì văn hóa làm việc tích cực, chuyên nghiệp trong nhóm phát triển mobile.\n- Thúc đẩy tinh thần làm việc nhóm, kết nối các thành viên, truyền cảm hứng và tạo động lực phát triển cá nhân cho từng thành viên.\n- Tham gia cùng cấp quản lý trong việc xây dựng lộ trình phát triển đội ngũ, phân bổ công việc, đánh giá hiệu suất và định hướng phát triển năng lực nhân sự.\n\nYêu cầu ứng viên:\n- Từ 3 năm kinh nghiệm phát triển ứng dụng mobile (iOS/Android).\n- Ưu tiên từng có kinh nghiệm lead dự án, lead team\n- Thành thạo ngôn ngữ Dart và framework Flutter.\n- Có kinh nghiệm với các ngôn ngữ native: Java/Kotlin (Android), Swift/Objective-C (iOS).\n- Hiểu rõ kiến trúc mobile app, các pattern thiết kế như MVVM, BLoC, Clean Architecture…\n- Sử dụng thành thạo GetX hoặc các công cụ quản lý state phổ biến.\n- Kinh nghiệm tích hợp RESTful API, xử lý dữ liệu định dạng JSON/XML.\n- Kỹ năng tối ưu hóa hiệu suất, quản lý bộ nhớ và xử lý sự cố mobile app.\n- Có kiến thức về thiết kế giao diện người dùng (UI/UX) là lợi thế.\n- Có kinh nghiệm triển khai được app lên các nền tảng apple store, google play\n- Có khả năng review code, khả năng mentor, đào tạo thành viên.\n\nQuyền lợi:\n- Thu nhập: Thỏa thuận theo năng lực.\n- Thưởng hiệu quả kinh doanh theo quy định và theo kết quả kinh doanh của công ty.\n- Bảo hiểm sức khỏe và Chương trình Khám sức khỏe định kỳ hàng năm chất lượng cao.\n- Các hoạt động văn hóa định kì như: Ngày lễ, Sinh nhật Công ty; … Du lịch, team building 2-3 lần/năm.\n- Các chế độ theo quy định của pháp luật (BHYT, BHXH, BHTN) và các chế độ phúc lợi theo nội quy, quy chế của Công ty (tham quan, nghỉ mát, lương thưởng, nghỉ Tết lễ, …)\n- Môi trường làm việc chuyên nghiệp, lắng nghe, tôn trọng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2461, 1217, 2, 'Software Engineer – Theia IDE Development For RISC-V', 'Mô tả công việc:\n- Develop and maintain core features of the Theia-based IDE, ensuring a seamless and productive developer experience.\n- Integrate and optimize RISC-V and ARM toolchains (GCC/LLVM) within the IDE, enabling efficient compilation and debugging workflows.\n- Implement and enhance debugging capabilities for RISC-V and ARM using GDB/LLDB, providing advanced features such as real-time system monitoring and multi-core debugging.\n- Design and develop Theia extensions and plugins to support specialized embedded development needs, including tracing, profiling, and hardware-specific interactions.\n- Enable seamless debugging of embedded targets deployed on the cloud, leveraging Theia\'s extensibility to integrate with cloud platforms.\n- Collaborate with cross-functional teams to gather requirements, design solutions, and ensure the IDE meets the evolving needs of embedded developers.\n- Contribute to the development and maintenance of a comprehensive suite of documentation and tutorials to support users.\n\nYêu cầu ứng viên:\n- Bachelor’s degree in Computer Science, Software Engineering, or a related field.\n- Proficiency in TypeScript/JavaScript and experience with web-based development.\n- Familiarity with Theia framework or other web-based IDEs is a plus.\n- Knowledge of embedded systems and development (RISC-V or ARM) is a plus.\n- Familiarity with C/C++ and debugging tools (GDB/LLDB) is a plus.\n- Eagerness to learn and a proactive attitude.\n- Focus on web-based applications and cloud technologies.\n- Strong expertise in TypeScript/JavaScript, modern web frameworks (e.g., React), and Electron framework.\n- Experience with cloud platforms and an understanding of cloud-based development workflows.\n- Familiarity with Theia framework and experience or a strong interest in developing Theia extensions or plugins.\n- A willingness to learn and embrace the challenges of embedded systems development, including familiarity with C/C++ and debugging tools (GDB/LLDB).\n- Ability to lead technical discussions, mentor junior engineers, and contribute to the development of a cutting-edge IDE.\n- Hands-on experience with Agile/Scrum, code reviews, and continuous integration.\n\nQuyền lợi:\n- Cutting-Edge Projects: Work with the latest technology trends in the RISC-V and ARM ecosystem.\n- Professional Growth: Opportunities for professional development, including mentorship, training, and career advancement.\n- Collaborative Environment: A dynamic and friendly team culture that thrives on innovation.\n- Competitive Compensation: Industry-leading salary, benefits, and bonuses based on experience and contribution.\n- Performance-based bonuses/ 13th month salary.\n- A powerful workspace:\n  - MacBook Pro with 64GB RAM and 1TB SSD for smooth development.\n  - 34-inch external display for enhanced productivity and a better workflow experience.\n  - Access to the latest tools, resources, and a supportive team environment.\n- Refer friends to open jobs and receive a cash bonus for every successful referral you make.\n\nĐịa điểm làm việc:\n- Hà Nội\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2462, 1317, 2, 'Unity Developer', 'Mô tả công việc\n- Chịu trách nhiệm xây dựng hệ thống và phát triển các dự án mobile game bằng Unity trên Android, iOS (dòng game hyper-casual, puzzle)\n- Chịu trách nhiệm tích hợp các hệ thống SDK, MMP, Ads, Tracking cho các dự án game.\n- Tham gia đóng góp xây dựng, cải tiến ý tưởng sản phẩm game để tăng trải nghiệm người dùng, hoàn thiện sản phẩm tốt nhất.\n- Kết hợp với các bộ phận Artist, Marketing, Game Design để sản xuất các game mobile chất lượng và hữu ích đến người dùng\n- Phối hợp với các thành viên trong team để xây dựng game\n\nYêu cầu ứng viên\n- Có ít nhất 3 năm kinh nghiệm lập trình game di động, ít nhất 2 năm trên nền tảng Unity\n- Nắm vững kiến thức về OOP, SOLID và các nguyên tắc trong lập trình;\n- Kinh nghiệm áp dụng các thuật toán, design patterns để giải quyết vấn đề;\n- Kiến thức về tối ưu assets, cache, memory;\n- Có kinh nghiệm build, xử lý tích hợp SDK, MMP, các định dạng quảng cáo;\n- Nắm vững các thành phần trong Unity và thành thạo C#;\n- Có kinh nghiệm trong việc tối ưu app size, memory, fps, anr, crashes;\n- Tư duy tốt, rành mạch, tập trung vào giải pháp;\n- Có khả năng làm việc độc lập và đội nhóm tốt, tính cách hòa đồng;\n- Chịu được áp lực trong công việc, ưu tiên các ứng viên mong muốn trở thành người dẫn dắt.\n\nQuyền lợi\n- Mức lương: 20tr -30tr++ (thỏa thuận theo năng lực); xét tăng lương định kỳ 2 lần/năm;\n- Nghỉ các chủ nhật và 2 thứ 7/tháng.\n- Thưởng lễ tết, thưởng hiệu quả kinh doanh hàng năm.\n- Được tham gia đầy đủ BHXH/ BHYT/ BHTN theo quy định của luật lao động.\n- Làm việc theo quy trình chuyên nghiệp.\n- Du lịch ít nhất 2 lần/năm, cơ hội du lịch nước ngoài; nhiều hoạt động thể thao/ Teambuilding/ Gala trong năm.\n- Được tham gia các chương trình đào tạo nâng cao năng lực, phát triển bản thân.\n- Cơ hội được làm việc trong môi trường chuyên nghiệp, nhân sự trẻ, năng động.\n- Có cơ hội thăng tiến lên các vị trí Lead, C-Level.\n\nĐịa điểm làm việc\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)\n- Làm 2 thứ 7 cách tuần\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2463, 227, 2, 'Senior Frontend Engineer (React/NextJS), StoreFront ECommerce Platform', 'ABOUT THE ROLE\n\nJoin our Technology Innovations Center of Excellence (CoE) at Crossian, a fast-growing startup that achieved a milestone of $100M in 2024. In this dynamic role, you\'ll check in daily with your team to stay aligned on project goals and collaborate across our ecosystem with an Agile mindset infused with a unicorn-worthy startup culture.\n\nWe are building a cutting-edge Global eCommerce Platform, offering end-to-end solutions for:\n\nStorefront: Designing customizable and scalable online store systems that provide seamless shopping experiences and support dynamic business growth.\n\nAds Manager: Integrating and optimizing advertising tools across platforms like Facebook, Google and more, enabling businesses to launch, track, and analyze marketing campaigns efficiently.\n\nMarketing Insights & CRM: Turning raw data from marketing campaigns, transactions, and user behavior into actionable insights to enhance customer engagement and drive smarter decision-making.\n\nWHAT YOU WILL DO\n\nFrontend Development & Optimization\n\nDesign, develop, and implement user-facing features using ReactJS and NextJS.\n\nOptimize web applications for performance, scalability, and cross-browser compatibility.\n\nLead the implementation of Server-Side Rendering (SSR) and Client-Side Rendering (CSR) for complex features.\n\nEnsure clean, maintainable, and scalable code through adherence to industry standards and peer code reviews.\n\nDebug and resolve performance bottlenecks using tools like Sentry, Kong logs, and Cloudflare.\n\nTranslate wireframes and prototypes into high-quality, responsive, and accessible code.\n\nCollaborate with UI/UX designers to deliver user-centric and consistent experiences.\n\nSystem Integration & Maintenance\n\nWork closely with backend teams to integrate APIs seamlessly into the frontend.\n\nParticipate in deployment processes and ensure system stability through efficient debugging and issue resolution.\n\nCross-Functional Collaboration\n\nCollaborate with stakeholders to analyze requirements and break them into actionable technical tasks.\n\nWork with cross-functional teams (backend, QA, DevOps) to ensure the successful delivery of projects.\n\nKnowledge Sharing & Continuous Improvement\n\nShare knowledge with team members and provide guidance on frontend best practices.\n\nProactively suggest improvements to workflows, tools, and code quality to enhance team productivity and product quality.\n\nWHAT WE ARE LOOKING FOR\n\nEducation: Bachelor’s degree in Information Technology, Computer Science, or related fields.\n\nExperience\n\n3-6 years of experience in frontend development with strong expertise in ReactJS, NextJS, and modern JavaScript.\n\nProficient in state management tools like Redux, Recoil, or similar libraries.\n\nHands-on experience in building responsive, cross-browser-compatible, and accessible web applications.\n\nHands-on experience with Node.js to develop APIs and optimize SSR logic.\n\nFamiliarity with modern frontend tools and workflows (e.g., Webpack, Vite, Git).\n\nBasic understanding of AWS S3, Cloudflare, or similar tools for asset delivery.\n\nCapable of translating business requirements into technical solutions.\n\nEnglish proficiency\n\nSoft Skills:\n\nStrong problem-solving skills.\n\nFamiliarity with Agile/Scrum\n\nPreferred Skills (but not required):\n\nHas knowledge of design, and coding principles (e.g.: clean code, DRY/KISS, SOLID)\n\nHas knowledge of Postgres, KAFKA, Elasticsearch, S3/Minio\n\nKnowledge of testing frameworks like Jest, React Testing Library.\n\nFamiliarity with CI/CD pipelines for frontend applications.\n\nExperience with eCommerce platforms is a plus.\n\nWHAT YOU CAN EXPECT\n\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\n\nExceptional Total Compensation Package\n\nUp to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n\nTotal annual compensation $55,000, reflecting your expertise and contribution.\n\nFull salary during probation & Guaranteed 13th month salary\n\n12 days work-from-home & 12 days of paid annual leave, plus seniority paid leave\n\nGlobal health insurance package for yourself and direct family members, plus annual health checkup\n\nGrowth Opportunities\n\nHands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n\nClear career advancement pathways and access to continuous professional development programs.\n\nGlobal Vision\n\nContribute to projects that redefine how brands connect with consumers globally.\n\nOpportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\n\nIn addition to development tasks, you’ll collaborate closely with other CoEs to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.\n\nĐịa điểm làm việc\n\n- Hà Nội: 65 Ngô Thì Nhậm, Hai Bà Trưng\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2464, 1318, 2, 'Middle Fullstack Developer', 'Mô tả công việc:\n- Frontend UI/UX design and development using Vue.js and Nuxt.js\n- Backend API design and development using Node.js, Express, and MySQL\n- Design and development of payment systems and point management systems\n- Implementation of wallet integration and token issuance utilizing blockchain technology\n- System infrastructure setup and management using AWS and Docker\n- Collaboration with Japanese development teams to promote agile development processes\n- Improvement of code quality, refactoring, and performance optimization\n\nYêu cầu ứng viên:\n- Native Vietnamese speaker\n- Experience with Node.js, JavaScript, and TypeScript\n- Experience in frontend design, development, and operation using Vue.js, Nuxt.js, etc.\n- Experience in backend development using Express and MySQL\n- Development and operational experience with AWS\n- Experience in Agile system development\n- Experience developing payment or point management systems\n- Experience developing high-traffic websites, large scale\n- Experience with SQL tuning/optimization\n\nQuyền lợi:\n- Phép năm: 18 ngày nghỉ/năm\n- Hỗ trợ ăn trưa\n- Bảo hiểm xã hội toàn lương\n- Phụ cấp công tác\n- Lương tháng 13\n- Thưởng hiệu quả công việc: Tùy chọn cổ phiếu và ưu đãi\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 29 Nguyễn Bá Lân, Thảo Điền, Thủ Đức\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Thủ Đức', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2465, 1298, 2, 'FullStack Developer (.NET+React+MongoDB/Postgres)', 'Mô tả công việc\n- Phát triển giao diện người dùng hiện đại, responsive bằng ReactJS.\n- Thiết kế và xây dựng các dịch vụ web/API sử dụng .NET Core.\n- Thiết kế và tối ưu cơ sở dữ liệu PostgreSQL, MongoDB.\n- Tích hợp và tối ưu hệ thống tìm kiếm sử dụng ElasticSearch.\n- Xây dựng kiến trúc phần mềm chất lượng, dễ mở rộng.\n- Viết tài liệu kỹ thuật và hỗ trợ kiểm thử phần mềm.\n- Đóng góp ý tưởng cải tiến kỹ thuật và quy trình làm việc.\n\nYêu cầu ứng viên\n- Tốt nghiệp ngành CNTT, Khoa học máy tính hoặc tương đương.\n- Tối thiểu 2 năm kinh nghiệm với ReactJS và .NET Core.\n- Có kinh nghiệm làm việc với ElasticSearch để xây dựng tính năng tìm kiếm, lọc dữ liệu nâng cao.\n- Thành thạo làm việc với PostgreSQL và/hoặc MongoDB.\n- Có kiến thức tốt về RESTful APIs, JSON, Entity Framework, LINQ.\n- Sử dụng thành thạo Git, biết làm việc theo mô hình Agile/Scrum.\n\nQuyền lợi\n- Lương: 20.000.000 - 35.000.000\n- Thưởng dự án/thưởng kinh doanh: từ 1 – 5 tháng lương\n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30.\n- Nghỉ phép: 12 ngày/năm\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN, Bảo hiểm Bảo Việt cho 100% cán bộ sau thời gian thử việc.\n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n- Các hoạt động giao lưu bóng đá, golf, văn nghệ...\n- Đào tạo chuyên sâu theo yêu cầu công việc\n- Được tham gia các dự án lớn triển khai toàn quốc\n- Được tiếp cận các kỹ thuật, công nghệ hiện đại... \n\nĐịa điểm làm việc\n- Hà Nội: Tầng 22 tòa nhà Viwaseen, số 48 Tố Hữu, Trung Văn, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2466, 1319, 2, 'Kỹ Sư Lập Trình Hệ Thống', 'Mô tả công việc:\n- Tham gia nghiên cứu và phát triển các sản phẩm, giải pháp công nghệ trong lĩnh vực An ninh – Quốc phòng, đặc biệt liên quan đến hệ thống điều khiển, giám sát, và truyền dẫn tín hiệu.\n- Nghiên cứu và phát triển các giải pháp truyền tải video real-time, phục vụ các các giải pháp thông tin liên lạc, giám sát hoặc hỗ trợ tác chiến.\n- Tham gia nghiên cứu, cập nhật xu hướng công nghệ mới và đề xuất ứng dụng thực tiễn vào sản phẩm của công ty.\n- Tham gia triển khai và tích hợp các hệ thống CNTT phục vụ cho hoạt động vận hành của công ty, và trong hệ thống sản phẩm/giải pháp của công ty.\n\nYêu cầu ứng viên:\n- Thành thạo một hoặc nhiều ngôn ngữ backend: Python (FastAPI, Flask), Golang, hoặc Node.js.\n- Có kinh nghiệm với các công nghệ truyền video real-time: FFmpeg, GStreamer, WebRTC, RTSP, HLS, DASH...\n- Hiểu và từng làm việc với các giao thức truyền tải video: UDP multicast, TCP streaming, RTP/RTSP, WebSocket.\n- Thành thạo môi trường Linux-based, có kinh nghiệm vận hành ứng dụng với Docker/container, theo dõi và tối ưu tài nguyên hệ thống.\n- Có kinh nghiệm với cơ sở dữ liệu: PostgreSQL, Redis, TimescaleDB, hoặc tương đương.\n- Ưu tiên:\n  - Từng làm việc với hệ thống encoder/decoder, camera IP, media gateway, hoặc giải pháp nén/tối ưu hóa truyền dẫn video.\n  - Có kinh nghiệm phân tích hiệu năng hệ thống, xử lý đa luồng, tối ưu độ trễ thấp (low-latency) và quản lý dữ liệu thời gian thực.\n  - Tư duy hệ thống tốt, có khả năng phối hợp chặt chẽ với các nhóm nhúng, AI, frontend và thiết bị.\n\nQuyền lợi:\n- Mức lương cạnh tranh, thưởng theo dự án và năng lực.\n- Công ty đóng 100% BHXH ngay khi ký HĐLĐ chính thức.\n- Cơ hội làm việc trong lĩnh vực công nghệ cao phục vụ Quốc phòng – An ninh.\n- Tham gia các khóa đào tạo chuyên môn sâu (nhúng, FPGA, truyền dẫn…).\n- Cơ hội phát triển thành trưởng nhóm kỹ thuật theo lộ trình.\n- Tham gia các khóa Đào tạo trong và ngoài nước nâng cao nghiệp vụ chuyên môn.\n- Thưởng tháng 13, 14 thưởng các ngày lễ, tết,…\n- Phụ cấp ăn trưa 40.000 VNĐ/ngày.\n- Khám sức khỏe định kỳ, teambuiding, du lịch, các sự kiện nội bộ.…\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Zodiac, ngõ 19 Duy Tân, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2467, 1131, 2, 'Dev Fullstack', '1. Thiết kế, phát triển, triển khai và tối ưu hệ thống phần mềm:\n- Phân tích yêu cầu, vấn đề và rủi ro có thể phát sinh trong quá trình thực hiện yêu cầu.\n- Thiết kế tổng thể hệ thống, các module thành phần, các chức năng chi tiết\n- Lập trình phát triển, bảo trì các chức năng hệ thống phía backend.\n- Triển khai và tích hợp các thành phần hệ thống phía backend và frontend\n- Tối ưu các thành phần hệ thống phía backend: code, database.\n- Triển khai và vận hành ứng dụng trên docker, k8s...\n- Tham gia xây dựng pipeline thu thập, xử lý và phân tích dữ liệu từ các thiết bị network, server trong Data center.\n- Xây dựng thuật toán giúp tối ưu cho việc xuất kho, điều chuyển hàng hoá phục vụ xây lắp công trình, trạm.\n\n2. Hợp tác và chia sẻ\n- Hợp tác với các thành viên trong dự án để thiết kế API phù hợp với yêu cầu của tính năng.\n- Chia sẻ kiến thức, công nghệ với các thành viên trong nhóm.\n- Review code giữa các thành viên trong dự án và code của đối tác.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm Fullstack. \n- Hiểu rõ về API RESTful, tích hợp frontend-backend, và các best practice trong phát triển web hiện đại.\n- Kiến thức vững chắc về lập trình hướng đối tượng (OOP), kiến trúc MVC, và các mẫu thiết kế phần mềm.\n- Tư duy logic, khả năng phân tích và giải quyết vấn đề hiệu quả.\n- Tính cách cẩn thận, siêng năng, chịu khó, và có thể theo đuổi các nhiệm vụ dài hạn một cách kiên trì.\n- Thành thạo công cụ quản lý mã nguồn (Git) và theo dõi công việc (Jira, Trello...).\n- Có kinh nghiệm hoặc hiểu biết về quy trình CI/CD, DevOps.\n\nQuyền lợi:\n- Mức lương cạnh tranh, 13 tháng lương\n- Cung cấp Laptop/ PC\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Nghỉ Thứ 7, Chủ nhật, 12 ngày phép/ năm\n- Phụ cấp gửi xe; ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Phụ cấp cơm trưa, bảo hiểm sức khỏe, khám sức khỏe định kỳ 1 lần/năm, du lịch nghỉ mát 1 lần/ năm.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, ...\n- Cơ hội thăng tiến vào các vị trí quản lý công nghệ cấp cao đối với những thành viên xuất sắc\n- Review tăng lương định kỳ hàng năm.\n\nĐịa điểm làm việc:\n- Hà Nội: 19-21 Vũ Trọng Phụng, Thanh Xuân Trung, Thanh Xuân\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2468, 1320, 2, 'Lập Trình CNC', '- Thiết lập quy trình công nghệ, lập trình gia công các sản phẩm cơ khí trên máy gia công CNC (phay, tiện CNC)\n- Quản lý, kiểm soát chất lượng trong quá trình gia công\n- Thực hiện các công việc khác khi có yêu cầu.\n- Chi tiết công việc sẽ trao đổi khi phỏng vấn.\n\n- Nam trong độ tuổi lao động, sức khỏe tốt.\n- Cẩn thận, tỉ mỉ, trung thực, chịu được áp lực trong công việc.\n- Kỹ năng: thành thạo phần mềm NX, Visi, autocad\n- Ưu tiên ứng viên có thể đi làm luôn sau phỏng vấn, có kinh nghiệm trong vị trí ứng tuyển từ 01 năm trở lên\n\n+ Được hưởng toàn bộ các chế độ, quyền lợi của công ty.\n+ Làm việc ca hành chính , tăng ca theo yêu cầu công việc\n+ Mức lương thỏa thuận theo năng lực.\n+ Chế độ lương tháng thứ 13, tăng lương, thưởng hàng năm.\n+ Đóng BHXH, BHYT, BHTN,... trên tổng lương\n\nPhụ cấp: Ăn trưa, Xăng xe\n\nĐược cấp Điện thoại, Máy tính.\n\nQuyền lợi: Bảo hiểm full lương, Phụ cấp thâm niên, Thưởng tháng 13, Bảo hiểm xã hội, Du lịch hàng năm, Thưởng hiệu quả làm việc\n\nĐịa điểm làm việc - Thái Nguyên: KCN Điềm Thụy, Phú Bình\n\nThời gian làm việc: Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2469, 1321, 2, 'Nhân Viên Lập Trình Web', 'Mô tả công việc:\n- Lập trình website bằng PHP, sử dụng các framework phổ biến như Laravel, CodeIgniter hoặc CMS như WordPress.\n- Chuyển đổi thiết kế Figma thành mã nguồn HTML/CSS, kết hợp với các framework Frontend (Bootstrap, Tailwind, v.v.). - Có khả năng thiết kế giao diện website trên Figma hoặc sử dụng Figma thành thạo là một lợi thế.\n- Tích hợp API, tối ưu hiệu suất website, đảm bảo tốc độ tải trang nhanh, bảo mật tốt.\n- Hỗ trợ kỹ thuật, chỉnh sửa, nâng cấp website theo yêu cầu của khách hàng.\n\nYêu cầu ứng viên:\n- Thành thạo Figma, có tư duy thiết kế UI/UX tốt.\n- Có kinh nghiệm làm việc với HTML, CSS, JavaScript (jQuery, Vue.js là lợi thế).\n- Thành thạo lập trình PHP & MySQL, ưu tiên biết sử dụng Laravel, CodeIgniter.\n- Am hiểu về WordPress là một lợi thế lớn.\n- Có tư duy logic, khả năng giải quyết vấn đề kỹ thuật nhanh chóng.\n- Có kinh nghiệm tối ưu website (SEO, bảo mật, tốc độ tải trang) là điểm cộng.\n\nQuyền lợi:\n- Thu nhập từ 10 - 20 triệu/tháng (Lương cứng + thưởng theo dự án).\n- Cơ hội nâng cao chuyên môn với các dự án thực tế, làm việc với công nghệ tiên tiến.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, hỗ trợ lẫn nhau.\n- Tham gia các dự án lớn, hợp tác cùng đối tác Google, Lark, Microsoft.\n- Chế độ đãi ngộ đầy đủ: BHXH, nghỉ phép, lương tháng 13, thưởng lễ Tết.\n- Địa điểm làm việc: Văn phòng Vinaweb - Hải Phòng.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 07:30 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2470, 1322, 2, 'Product Developer', 'Mô tả công việc\n- Managing the entire product line life cycle from strategic planning to tactical activities.\n- Specifying market requirements for current and future products by conducting market research and gathering insights from customers and non-customers.\n- Driving solution development across teams by aligning market requirements, product contracts, and positioning strategies.\n- Demonstrating high-level critical thinking in cross-functional process analysis and problem resolution for both new and existing products.\n- Analyzing potential partnerships and collaborations that could benefit product development.\n- Coordinating and building strong working relationships with internal teams, including IT, Sales, Marketing, Product Development, and Operations.\n- Leading the development, approval, training, and communication of new products and product changes, ensuring all internal teams are aware of customer, operational, system, and process impacts.\n- Developing and conducting specialized training programs for newly launched products, enhancing awareness and application of relevant knowledge.\n- Monitoring internal processes for efficiency and effectiveness before and after product launches or changes.\n- Providing support for other departmental projects as needed.\n\nYêu cầu ứng viên\n- Bachelor’s degree or diploma in Business, Tourism, Business Administration, or a related field (preferred)\n- Good communication skills in English.\n- Proficient in Microsoft Office (Word, Excel, Outlook, PowerPoint)\n- At least 1 year of experience as a Product Developer in Travel companies.\n\nQuyền lợi\n- Salary: Negotiable based on experience and competency.\n- Benefits: Free parking and lunch allowance.\n- Insurance: Social insurance (BHXH) and health card.\n- Work Location: Prime location at Hanoi Tower – 49 Hai Bà Trưng, Hoàn Kiếm, Hanoi.\n- Career Growth: Opportunities for professional development within the Group.\n- Travel & Activities: Chance to travel to various destinations and participate in corporate activities.\n- Working Schedule: Monday to Friday, weekends off (Saturday & Sunday). On Fridays, employees leave 2 hours earlier.\n- Remote Work Policy: Online working mode available for employees living far from the office.\n\nĐịa điểm làm việc\n- Hà Nội: Tháp Hà Nội, 49 Hai Bà Trưng, Hoàn Kiếm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2471, 1226, 2, 'Unity Developer', 'Mô tả công việc:\n- Participate in developing Game projects (Casual/Puzzle) on the Unity platform\n- Coordinate and discuss with team members to build, complete and optimize the game\n- Contribute ideas and content to improve product quality\n- Job details will be discussed specifically if the CV meets the requirements.\n\nYêu cầu ứng viên:\n**Knowledge:**\n- Graduated from University majoring in IT or related fields \n- Good programming thinking, proficient in C# programming language \n- Have at least 4-6 months of experience working with Unity; know how to work with XCode and Android Studio.\n\n**Skill:**\n- Proficient in Unity, especially experienced in handling issues such as: Animation, Effect, Particle, optimization \n- Skilled in planning Game development, able to work under high pressure \n- Good teamwork and good independent work.\n\n**Attitude:**\n- Ability to work in a customer-centric and team-oriented environment, detail-oriented \n- Positive, proactive, responsible in work, and have passion for Games\n- Diligent, eager to learn, enthusiastic, with a strong growth mindset and a passion for self-development\n- Commitment to long-term engagement with the company\n- Quick adaptability to work, able to handle pressure\n- Ability to work in a fast-paced environment.\n\nQuyền lợi:\n**INCOME**\n- Salary: Upto 15M/month\n- Receive 100% of fixed salary, salary increase according to company regulations\n- Official employee lunch allowance: 1,000,000 VND/month\n- Income based on results and work performance\n\n**DEVELOPMENT OPPORTUNITIES**\n- Expand and improve professional knowledge and skills\n- Real-life experience at global projects\n- Have a clear, personalized career development roadmap\n\n**WORKING ENVIRONMENT**\n- Experience a dynamic, professional international environment\n- Enjoy 100% daily life care benefits\n\n**WELFARE POLICY**\n- The company pays all types of insurance according to the provisions of law (social insurance, health insurance, unemployment insurance, etc.)\n- Free periodic general health check-ups at hospitals: Hong Ngoc, Thu Cuc, Vinmec.\n- Wedding/filial piety benefits, holiday/New Year gifts and other benefits.\n- New Year bonus, March 8, April 30 - May 1, Mid-Autumn Festival, mid-year, September 2, October 20, Christmas.\n- Share achievements continuously, without limits based on performance.\n- Working hours:\nFrom Monday - Friday. Closed Saturday, Sunday\nMorning: 8:30 - 12:00, Afternoon: 13:00 - 18:00, tea-break 15:00 - 15:30.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 10 - The West Tower - 265 Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm **Ứng tuyển** ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2472, 1323, 2, 'Front-End Developer (Chuyên VueJS)', 'Mô tả công việc:\n- Tham gia vào các quy trình: viết tài liệu, phân tích yêu cầu, thiết kế giao diện, triển khai, code review, kiểm thử đơn vị (Unit testing) và vận hành sản phẩm.\n- Đảm bảo giao diện tải nhanh và hoạt động mượt mà trên nhiều nền tảng khác nhau.\n- Xử lý sự cố phần mềm giao diện và gỡ lỗi mã nguồn ứng dụng.\n- Cập nhật và duy trì giao diện người dùng khi có yêu cầu hoặc theo nhu cầu vận hành.\n- Phối hợp với các thành viên khác trong nhóm phát triển để đảm bảo sự đồng bộ và tương thích giữa các thành phần của ứng dụng.\n- Đào tạo, hỗ trợ và tạo động lực cho các thành viên trong nhóm.\n- Nghiên cứu và phát triển công nghệ mới liên quan đến dự án.\n\nYêu cầu ứng viên:\n- Ưu tiên ứng viên có bằng Cử nhân các ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan.\n- Tối thiểu 01 năm kinh nghiệm phát triển dịch vụ Web.\n- Có kinh nghiệm tham gia đầy đủ các giai đoạn trong vòng đời phát triển dự án từ con số 0.\n- Có kinh nghiệm làm việc với TypeScript, NextJS, NuxtJS.\n- Có tinh thần học hỏi, sẵn sàng chuyển đổi ngôn ngữ lập trình từ ReactJS sang VueJS hoặc ngược lại.\n- Ưu tiên ứng viên biết tiếng Trung.\n\nQuyền lợi:\n- Lương thỏa thuận theo năng lực (từ 20 - 30 triệu/tháng).\n- Được tham gia bảo hiểm xã hội khi trở thành nhân viên chính thức.\n- Cung cấp trang thiết bị làm việc.\n- Off chủ nhật và các ngày lễ theo quy định nhà nước.\n- Các phúc lợi khác trao đổi khi phỏng vấn.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tầng 2 thương mại , Tháp A thuộc chung cư the CBD - 125 Đồng Văn Cống, phường Thạnh Mỹ Lợi, Thủ Đức.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2473, 1324, 2, 'Kỹ Sư Lập Trình Máy CNC (Citizen Cincom L20) - Thu Nhập Từ 30 Đến 50 Triệu VNĐ/Tháng', 'Mô tả công việc:\n- Lập trình gia công chi tiết phức tạp trên máy tiện tự động Citizen Cincom L20 (hệ điều khiển Mitsubishi M70/M700/M850)\n- Viết và hiệu chỉnh chương trình G-code (bao gồm tiện, phay, khoan nghiêng, có trục phụ, dao sống...)\n- Tối ưu đường chạy dao, lựa chọn thông số cắt phù hợp để giảm thời gian chu kỳ và đảm bảo độ chính xác cao\n- Setup dao, định nghĩa zero offset, cấu hình dao sống và cấu hình trục\n- Kết hợp bộ phận thiết kế CAD/CAM để chuyển đổi từ Fusion 360, Mastercam, hoặc bản vẽ kỹ thuật sang mã NC\n- Chạy thử sản phẩm đầu tiên, tinh chỉnh và phê duyệt (first part approval)\n- Theo dõi, cải tiến quy trình khi thay đổi vật liệu hoặc dao cụ\n- Quản lý, backup dữ liệu chương trình và thông tin máy\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng/đại học chuyên ngành Cơ khí, Chế tạo máy, Cắt gọt kim loại, Cơ điện tử\n- Kinh nghiệm tối thiểu 1 năm lập trình máy Cincom (L12, L20, L32...)\n- Thành thạo lập trình tay G-code, đọc hiểu bản vẽ kỹ thuật\n- Ưu tiên ứng viên biết sử dụng CAM (Fusion 360, Mastercam, Esprit...)\n- Có kiến thức về LFV, phay nghiêng (B-axis), dao whirling, tiện vật liệu khó như titanium là lợi thế lớn\n- Tư duy logic, cẩn thận, làm việc nhóm tốt, chịu được áp lực cao\n\nQuyền lợi:\n- Thu nhập: 30 – 50 triệu VNĐ/tháng\n- Phụ cấp kỹ thuật\n- Thưởng theo hiệu suất làm việc\n- Tăng lương theo năng lực\n- Môi trường làm việc sạch sẽ, hiện đại theo tiêu chuẩn y tế – xuất khẩu\n- Được đào tạo chuyên sâu về vận hành và lập trình máy CNC\n- Có cơ hội phát triển lên vị trí kỹ thuật viên lập trình hoặc quản lý nhóm kỹ thuật\n- Đầy đủ chế độ BHXH, BHYT, nghỉ lễ/tết theo quy định nhà nước\n- Hỗ trợ đồng phục, cơm trưa và các điều kiện làm việc tốt\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 170 Nam Kỳ Khởi Nghĩa, P. Võ Thị Sáu, Quận 3\n- Hồ Chí Minh: Khu Công Nghệ Cao, Quận 9\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2474, 1325, 2, 'Junior PHP Developer', 'Mô tả công việc\n- Tham gia phát triển các sản phẩm phần mềm cho thị trường Nhật Bản\n- Phát triển các product của công ty\n- Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng Nhật.\n- Tham gia phát triển các công đoạn phân tích yêu cầu, Detail Design, Coding, viết tài liệu API, Unit Test.\n- Làm việc theo yêu cầu của quản lý trực.\n\nYêu cầu ứng viên\n- Có từ 1 năm kinh nghiệm làm việc liên tục với PHP trong các dự án thực tế\n- Có kinh nghiệm làm việc với một trong các Framework: Laravel, CakePHP\n- Hiểu biết về Mysql (có kinh nghiệm làm việc với database với số lượng bản ghi lớn là một lợi thế)\n- Có hiểu biết hoặc có kinh nghiệm HTML, CSS, Javascript, jQuery\n- Nắm vững OOP, mô hình MVC\n- Sử dụng công cụ quản lý phiên bản GIT, SVN\n- Ưu tiên Có kinh nghiệm lập trình Vue JS\n- Ưu tiên Có hiểu biết và sử dụng Linux, Amazon (AWS ecosystem).\n\nQuyền lợi\n- Thu nhập: 12.000.000đ - 20.000.000đ Net/ tháng (nego)\n- Thử việc 2 tháng (85% lương)\n- Cố định 13 tháng lương Net/ năm\n- Thưởng (lễ tết, sinh nhật…)\n- Quy đổi phép thành tiền\n- Được tham gia vào các dự án lớn trong hệ thống chứng khoán, ngân hàng\n- Môi trường công bằng, đảm bảo mọi người đều có thể phát huy hết khả năng của mình\n- Được làm việc với những cá nhân xuất sắc, có nhiều kinh nghiệm.\n- Được hưởng Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n- Teambuilding 3 tháng 1 lần\n- Khám sức khỏe định kỳ 1 năm/1 lần\n- Chế độ du lịch hàng năm\n- Tea Break free (Trà, Cafe, bánh…)\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Peakview, 36 Hoàng Cầu, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- (Thêm thông tin)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2475, 1304, 2, 'Database Developer (Mid Level)', 'Mô tả công việc\n- Join Workshop with customers to grasp requirements.\n- Work with business analysts to understand requirements.\n- Design & implement database handling: create table, write store procedure / function / view/ trigger... with database management systems (e.g., Oracle, SQL Server, MySQL, PostgreSQL...)\n- Experience with data modeling and normalization\n- Experience with database security\n- Monitor database performance\n- Troubleshoot database problems\n- Present the database structure to the project\'s IT team handle data migration (handling of putting old data into system).\n- Experience with NoSQL database\n- Support DEV about related issues.\n\nYêu cầu ứng viên\n- Required Skills\n  - 3 years experience as Database Developer.\n  - Ability to learn quickly new technologies.\n  - Able to work both independently and as part of a team.\n  - Ability to effectively prioritize and execute tasks in a high-pressure environment.\n  - Ability to openly present her/his own ideas.\n  - Good understanding at software development processes.\n  - Excellent logical thinking ability.\n- Education\n  - Bachelor Degree in Computer Science/ Information Technology or equivalent;\n- Language skills:\n  - Vietnamese - Fluent Native\n  - English Language Skills\n\nQuyền lợi\n- Competitive salary and benefits\n- Working time: 8:30AM - 05:30PM, Monday – Friday;\n- 12 days of annual leave + 3 days of sick leave + 1 day of birthday per year\n- Participated in social insurance, unemployment insurance, health insurance and full policies according to the labor law;\n- 13th month salary & bonus policies, allowances at the Company;\n- UNIT-Care health care insurance by level;\n- Salary increases according to company regulations or unexpected salary raise in case of outstanding ability;\n- Professional and dynamic working environment, unlimited promotion opportunities;\n- Opportunity to participate in many large projects in Vietnam & abroad;\n- Work on the latest technology platform;\n- Join in company trip, teambuilding & community activities.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 374 Võ Văn Tần, phường 5, Quận 3\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2476, 1326, 2, 'Kỹ Sư Thiết Kế Phần Mềm', 'Mô tả công việc\n- Thiết kế, cải tiến và phát triển các hệ thống quản lý dữ liệu cho nhà kho như WMS, MCS, ...\n- Cải tiến và phát triển các mã nguồn để tích hợp các phần mềm quản lý dữ liệu vào hệ thống WMS.\n- Thiết kế, quản lý và tối ưu hóa cơ sở dữ liệu để lưu trữ và truy xuất thông tin hiệu quả trong các phần mềm quản lý dữ liệu\n- Phát triển và duy trì các phần mềm điều khiển và giám sát các mô hình và hệ thống tự động hóa.\n- Nghiên cứu, tối ưu và phát triển các thuật toán ứng với các phần mềm điều khiển các mô hình tự động hóa.\n- Tư vấn kỹ thuật, thiết kế giải pháp quản lý dữ liệu trong lĩnh vực quản lý kho bãi.\n- Lên kế hoạch thiết kế, thực hiện và triển khai dự án\n\nYêu cầu ứng viên\nYêu cầu trình độ: \n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin. (Ưu tiên loại Giỏi)\n\nYêu cầu kỹ năng: \n- Sử dụng thành thạo các phần mềm:\n  + Hệ quản trị cơ sở dữ liệu như: MySQL, Mycrosoft SQL Server, PostgreSQL, ....\n  + Công cụ phát triển phần mềm như: Visual Studio, Eclipse, ...\n- Sử dụng thành thạo các ngôn ngữ lập trình như: C#, Python, Java, JavaScript, SQL, ...\n\nƯu tiên:\n- Có kinh nghiệm hoặc từng thiết kế phần mềm quản lí như: WMS, WCS, RSC, hệ thống IoT, ...\n- Hiểu biết về kết cấu hạ tầng mạng để đảm bảo kết nối liên tục và an toàn\n- Có nền tảng về Scan dữ liệu hay thu thập dữ liệu như: Barcode, QRcode, RFID, ...\n\nYêu cầu kinh nghiệm:\n- Có kinh nghiệm thiết kế phần mềm quản lý dữ liệu từ 5 năm trở lên.\n\nYêu cầu khác:\n- Chăm chỉ, nhiệt tình trong công việc, có thể làm việc trong môi trường áp lực cao.\n- Đam mê nghiên cứu, thiết kế, hoạt động R&D, có tinh thần cầu tiến, ham học hỏi.\n- Có thể đi công tác tùy theo yêu cầu của công việc.\n\nQuyền lợi\n- Mức lương: 12-20 triệu/tháng\n- Hưởng lương tháng thứ 13, thưởng Lễ-Tết\n- Được đóng bảo hiểm theo quy định của Luật Lao động\n- Được làm việc trong môi trường chuyên nghiệp, năng động, có cơ hội học hỏi kinh nghiệm và phát triển bản thân\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Trịnh Thị Miếng, Thới Tam Thôn, Hóc Môn\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Hóc Môn', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2477, 1327, 2, 'Product Developer (Merchandiser)', 'Mô tả công việc\n- Maintains accuracy of technical specification packs for each product, including BOM and measurements.\n- Tracks prototypes and samples for development, marketing, and sales needs. Ensures every stage is on time per the published timeline.\n- Manage end-to-end product development, from timeline adherence, material sourcing, costing through to production handover.\n- Be the voice of Product Development cross functionally communicating product status, costing and suggesting process improvement where possible.\n- Build and maintain material library for products in line with design needs and category vision.\n- Work hand in hand with QA, Production, Sourcing, Packaging, Design team and other necessary teams ensuring product cycle deadlines are met and product standards are upheld.\n- Source new suppliers based on category growth and needs.\n- Facilitate day-to-day communications with existing suppliers and manufacturers focusing on in building strong and trusted relationships with overseas partners.\n- Responsible for the main sketches and drawings of each product.\n- Sketch out the design spec sheets by Adobe Illustrator.\n- Make packaging instructions.\n- Participate in meetings to discuss designs and line development, and present and review line and concepts regularly.\n\nYêu cầu ứng viên\n- Good verbal and written communication skills in English\n- Minimum 1 years’ experience in backpack or at factory\n- Proficiency in Adobe Illustrator is mandatory.\n- Can work under high pressure, hard-working and honestly.\n- Communication skills: considering work in teams, a great communicator needed\n- Must be able to learn and collaborate with other members.\n\nQuyền lợi\n- Working days: 5 days/week, from Monday to Friday\n- Working time: 7:30 – 16:30\n- Full pay social insurance\n- Paid Leave: Follow VN Labor Law.\n- Have 13th-month salary and other benefits follow the company’s policy\n- Allowance: daily meal allowance on working days.\n- Company’s Library for all employees with collections of books.\n- Top-level All-Free Pantry\n- Annual or Seasonal Outdoor Activity with employees\n- Participating other annual events\n- Free Learning Courses to develop working skills (photoshop / MS office / etc)\n- Loyalty Program\n  - Private Health Insurance to all employees and employees’ families (According to the length of service)\n  - Annual employee gifts\n  - Senior staff benefits\n  - Oversea trip opportunities (Korea, Japan, US, EU / etc)\n  - Others\n- Basic Annual leave: 15 days/ year\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 385 Cộng Hòa, Phường 13,, Tân Bình\n\nThời gian làm việc\n- Từ Thứ 2 đến Thứ 6\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2478, 1271, 2, 'Product Management Trainee - Quản Lý Sản Phẩm MT', 'Chương trình Viettel Future Changemakers kéo dài 18 tháng, dự kiến triển khai từ tháng 08/2025 – 01/2027, chia làm 02 giai đoạn:\n- Giai đoạn 1 (1 tháng): Trại huấn luyện tập trung - Được đào tạo tập trung bởi nhiều chuyên gia của Viettel và các Tập đoàn công nghệ lớn thế giới\n+ Tổng quan về Quản lý sản phẩm\n+ Kiến thức về Lập chiến lược sản phẩm (Ideas & User needs, Competitive & Market Analysis, Customer Development)\n+ Kiến thức về Thiết kế và phát triển sản phẩm\n+ Kiến thức về Marketing & Ra mắt sản phẩm\n+ Các kỹ năng cần thiết về Quản lý sản phẩm\n- Giai đoạn 2 (17 tháng): Thực tập tại các dự án trọng điểm thuộc đơn vị\n+ Tập sự viên được tham gia các dự án, công việc tại các phòng ban liên quan để hiểu rõ về 03 khía cạnh của Quản lý sản phẩm (1) Kinh doanh (2) Công nghệ (3) Khách hàng.\n+ Mentor là người có chuyên môn cao trong lĩnh vực sẽ hướng dẫn tập sự viên\n+ Management coach là cán bộ quản lý có kỹ năng lãnh đạo tốt sẽ tư vấn cho tập sự viên\n+ Tham gia lên ý tưởng cho các sản phẩm trọng điểm của Viettel và tham gia cuộc thi “The Changemakers” với cơ hội nhận thưởng lên đến 30 triệu/ đồng và được trình bày đề xuất trước Ban Tổng Giám đốc Tập đoàn.\n- Các hoạt động kết nối: Tham gia nhiều hoạt động kết nối tài năng, cán bộ quản lý tại Viettel.\n\nYêu cầu ứng viên\n- Ứng viên bên trong và bên ngoài Viettel tốt nghiệp đại học loại Giỏi trở lên các ngành Công nghệ thông tin, Khoa học máy tính, Quản trị kinh doanh, Tài chính ngân hàng, Marketing, Kinh tế và các ngành tương đương; hoặc đạt các thưởng quốc gia/quốc tế trong các lĩnh vực liên quan; hoặc có thành tích xuất sắc khi tham gia các dự án lớn trong lĩnh vực liên quan.\n- Ưu tiên ứng viên có 02 năm kinh nghiệm làm Marketing, Product Owner, Phân tích nghiệp vụ, Phát triển phần mềm cho các sản phẩm công nghệ.\n- Tiếng Anh tối thiểu 700 điểm TOEIC hoặc tương đương (Chấp nhận điểm thi trên E-learning bài TOEIC đầy đủ và các chứng chỉ quốc tế tương đương).\n- Hình thức thi: Vòng 1 - IQ, Tiếng Anh Toeic, Vòng 2: Online test, Vòng 3: Assessment day tại Hà Nội, Vòng 4: Phỏng vấn hội đồng\n- Địa điểm: Hà Nội (Đối với ứng viên khác khu vực Hà Nội sẽ được tài trợ máy bay 02 chiều nếu trúng tuyển và tham gia đầy đủ chương trình).\n\nQuyền lợi\n- 30-47 triệu/tháng\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Các hoạt động kết nối: Tham gia nhiều hoạt động kết nối tài năng, cán bộ quản lý tại Viettel.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2479, 1328, 2, 'Solution Architect', 'Company Introduction\nDigiEx Group is a rapidly growing technology company based in Vietnam, with a mission to build a technology ecosystem and digital talent-hub in the country to be enabling global Tech companies to find the right resources to drive their digital transformation initiatives.\n\nWe offer a range of innovative solutions to help businesses transform digitally, including digital talent services, custom software development, cloud migration and management, and emerging tech R&D. Our tailored solutions are designed to meet the unique needs of each client, and our experienced team works closely with businesses to ensure their success in the rapidly evolving digital landscape.\n\nJob description\nWe are seeking a seasoned Solution Architect to lead the design and implementation of robust, scalable, and secure software solutions. This role demands a strategic thinker with a deep understanding of technology trends and the ability to align technical solutions with business objectives.\n\nYour responsibilities:\nArchitectural Leadership: Design and oversee the implementation of comprehensive software architectures that meet business requirements and align with industry best practices. Stakeholder Collaboration: Engage with clients, project managers, and development teams to gather requirements and translate them into technical solutions.\nTechnology Evaluation: Assess emerging technologies and platforms to determine their applicability to our solutions and recommend adoption where beneficial.\nQuality Assurance: Ensure solutions meet performance, scalability, and security standards, conducting regular reviews and audits.\nDocumentation: Create and maintain detailed architectural documentation, including design specifications and integration plans.\nMentorship: Provide guidance and mentorship to development teams, fostering a culture of continuous learning and improvement.\nRisk Management: Identify potential risks in proposed solutions and develop mitigation strategies to address them proactively.\n\nYêu cầu ứng viên\nEducational Background: Bachelor\'s or Master\'s degree in Computer Science, Information Technology, or a related field.\nExperience: Minimum of 5 years in software development, with at least 2 years in a solution architecture role.\nTechnical Proficiency:\nExpertise in designing and implementing solutions using cloud platforms such as AWS, Azure, or Google Cloud.\nProficient in microservices architecture, RESTful APIs, and containerization technologies like Docker and Kubernetes.\nFamiliarity with programming languages such as Java, PHP, or JavaScript.\nCertifications: Relevant certifications (e.g., TOGAF, AWS Certified Solutions Architect) are highly desirable. Soft Skills:\nStrong analytical, problem-solving, and communication skills (both verbal and written). Ability to work collaboratively in cross-functional teams.\nExcellent leadership, team-building, and interpersonal communication skills.\nDemonstrated experience mentoring engineers or leading technical teams.\nFluent in English (spoken and written) and strong presentation skills.\nExperience working in startup or fast-growth environments.\nPrior involvement in technical hiring, building development processes, or setting team standards.\nTakes ownership beyond individual projects.\nDemonstrates business acumen alongside technical depth.\nIs passionate about building technology-driven teams that scale.\nHas a strong sense of responsibility in shaping technical culture and company direction.\nThis role is strategically positioned for transition into a CTO role in the near future.\n\nQuyền lợi\nFlexible working hours, a dynamic, innovative, and friendly environment\nAttractive income package as negotiation\nGreat opportunity to grow career path, personal development, and challenging projects\nDevelop a global career path by providing many pieces of training (Technical & Soft skills)\nHave a chance to work directly with the CTO/CEO of many Startups around the world\nWe have a strong remote workforce & global culture with team members from different countries.\n\nĐịa điểm làm việc\nHồ Chí Minh: Floor 8th, QTSC Building 1, Quang Trung Software Park, 14th Street, Tan Chanh Hiep Ward, District 12, Quận 12\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2480, 1329, 2, 'Nhân Viên Lập Trình CNC Khuôn', 'Mô tả công việc\n- Tiếp nhận bản vẽ từ bộ phận thiết kế\n- Tiến hành các thao tác lập trình sử dụng phận mềm NX hoặc các phần mềm tương tự để lập trình gia công các chi tiết khuôn\n- Tách điện cực, điện xung\n- Xuất bản vẽ chương trình\n- Xuất bản vẽ điện cực xung\n- Hỗ trợ chương trình cho tổ vận hành trong quá trình vận hành máy\n\nYêu cầu ứng viên\n- Kinh nghiệm 2 năm trở lên về lập trình CNC \n- Sử dụng thành thạo phần mềm NX\n- Đọc hiểu bản vẽ kỹ thuật\nCó thể làm việc độc lập, chịu được áp lực công việc\n\nQuyền lợi\n-Thử việc nhận 100% lương\n- Mức lương hấp dẫn thỏa thuận theo năng lực \n- Hưởng đầy đủ các chế độ theo quy định của nhà nước: PHÉP NĂM, BHXH, BHYT…\n- Nâng lương hàng năm\n\nĐịa điểm làm việc\n- Bắc Ninh: Cạnh Golden Park, Quế Võ\n- Bắc Ninh: Gần Cầu Ngà, Quế Võ\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nTăng ca theo yêu cầu công việc, sự sắp xếp của quản lý\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2481, 1330, 2, 'Backend Developer', 'Job description\n\nResponsibility\n- The Senior Software Engineer is responsible to write software programs from design specifications\n- Determining requirements and providing project estimates and timelines and high level architecture design\n- Implement task lists, estimate deliver assignments as functional specifications, quality standards and project schedules.\n- Reports status and issues\n- Documents detailed designs\n- Contributes to system architecture and design decisions.\n- Perform other tasks assigned by the Product Owner, Project Manager & Technical Manager to figure out user’s needs, problems, expectations to contribute ideas & solution as well as to resolve them\n\nMust have\n- Good knowledge of OOP, SOLID principles\n- 3+ years experienced in NodeJS, NestJS (static module, dynamic module)\n- 2+ year experienced Postgresql / MongoDB\n- Creative thinking and good at problem solving\n- Strong knowledge of web service development (RESTful)\n- Excellent communication, motivational, and interpersonal skills.\n\nNice to have\n- Having experiences mentoring and leading teams\n- Knowledge of cloud services – especially Google Cloud\n- Good knowledge of Docker Engine and K8S, cloud deployment, security\n\nQuyền lợi\n- Fixed salary negotiable based on competency + bonuses.\n- 13th-month salary and performance-based bonuses.\n- Bonuses according to company policies, including holiday, Tet, and company event bonuses.\n- Comfortable, dynamic, and friendly working environment with high promotion opportunities.\n- 12 annual leave days + birthday leave; leave days increase based on internal level and years of service.\n- Full social insurance (BHXH), health insurance (BHYT), and participation in the company’s labor union.\n- Benefits for personal events such as birthdays, weddings, illness, and maternity leave.\n- Regular salary reviews based on company policies.\n- Uniforms and gifts for company events.\n- Clear career advancement path with comprehensive training and maximum support in work.\n\nĐịa điểm làm việc\n- Hà Nội: 219 Trung Kính, Yên Hòa, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2482, 1331, 2, 'Nhân Viên Lập Trình Máy CNC', '• Lập trình gia công máy CNC bằng phần mềm MasterCam, ….\n• Lập phương án gia công chi tiết, gia công đồ gá\n• Theo dõi quản lý sản phẩm đảm bảo tiến độ và chất lượng.\n• Thực hiện các công việc cấp trên giao.\n\n• Yêu cầu bằng cấp: tốt nghiệp trung cấp trở lên\n• Có ít nhất 1 năm kinh nghiệm đứng máy và lập trình CNC biết sử dụng các phần mềm cơ khí Auto CAD, MasterCam.\n• Am hiểu về 1 trong các công nghệ gia công cắt gọt kim loại như Tiện, Phay CNC, mài, xung điện cắt dây.\n\n- Ký HĐLĐ, tham gia BHXH đầy đủ sau thử việc;\n- Thời gian làm việc: Từ thứ 2 đến thứ 7;\n- Phụ cấp cơm trưa, Phụ cấp cơm tăng ca, Hưởng đầy đủ các chế độ theo đúng quy định của nhà nước;\n- Môi trường làm việc ổn định, lâu dài.\n- Du lịch định kỳ hàng năm\n- Lương thưởng cuối năm\n\n- Hồ Chí Minh: 113/13 Đường số 11, Linh Xuân, Thủ Đức, Thủ Đức\n\nThời gian làm việc: Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2483, 770, 2, 'Java Developer (Middle)', 'Mô tả công việc\n- Tham gia phát triển các dự án Hệ sinh thái Tài chính số (Viettel Money, Mobile Money, ví cá nhân, ví doanh nghiệp, ...). Cung cấp sản phẩm ứng dụng thanh toán và chuyển tiền với số lượng giao dịch rất lớn, đòi hỏi hiệu năng xử lý cao\n- Xây dựng các hệ thống Tài chính điện tử cho các thị trường nước ngoài mà Viettel đầu tư\n- Tham gia làm rõ nghiệp vụ, thiết kế giải pháp, phát triển nâng cấp hệ thống theo yêu cầu\n- Tham gia review thiết kế, review code, tối ưu hệ thống đáp ứng lưu lượng truy cập cao\n- Nghiên cứu áp dụng công nghệ mới nâng cao chất lượng, tối ưu nguồn lực phát triển.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học loại Khá trở lên, chuyên ngành Công nghệ thông tin, Kỹ sư phần mềm. Đặc biệt ưu tiên các trường Học viện Công nghệ Bưu chính Viễn thông, Đại học Bách khoa Hà Nội, …\n- Tiếng Anh tương đương 550+ TOEIC\n- Ưu tiên ứng viên có từ 02 năm kinh nghiệm Java trở lên\n- Thành thạo Java Core, các framework Java như EE, Spring, Struts, Hibernate ... và một số design pattern thông dụng\n- Tư duy về thiết kế hướng đối tượng và nắm vững kiến thức về cấu trúc dữ liệu và giải thuật, lập trình hướng đối tượng ...\n- Thành thạo SQL, PLSQL, có kiến thức về các hệ quản trị cơ sở dữ liệu Oracle/MySQL, noSQL, có khả năng tối ưu CSDL\n- Ưu tiên có hiểu biết về nghiệp vụ tài chính, có kinh nghiệm về microservices, ham học hỏi tìm tòi sáng tạo cái mới\n- Ưu tiên ứng viên có khả năng ứng dụng công cụ AI để hỗ trợ phân tích, lập trình, viết tài liệu hoặc tối ưu quy trình làm việc.\n- Có kinh nghiệm hoặc có nghiên cứu đến việc tích hợp AI vào sản phẩm, dịch vụ là một lợi thế.\n\nQuyền lợi\n- Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn\n- Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel\n- Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm\n- Cơ hội tiếp xúc với các dự án lớn, mới mẻ & tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam\n- Cơ hội thăng tiến rõ ràng với nhiều cấp bậc\n- Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn\n- Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời.\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người\n- Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,…\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày\n- Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Keangnam, Phạm Hùng, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2484, 1332, 2, 'Fullstack Web Developer (Python/Reactjs)', '• Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng Nhật, Âu, Mỹ.\n• Hợp tác và trao đổi công việc với Team Member, Team Leader.\n• Tham gia phát triển các công đoạn phân tích yêu cầu, Coding, viết tài liệu API, Unit Test sử dụng Python và React.JS\n• Tham gia thiết kế cơ sở dữ liệu, thiết kế kiến trúc dự án.\n• Có thể đảm nhận các công việc phát triển cả backend, frontend.\n\n• Có kiến thức nền tảng tốt về lập trình (OOP, cấu trúc dữ liệu và giải thuật…).\n• Có kiến thức nền tảng tốt về cơ sở dữ liệu quan hệ (thiết kế, sử dụng…).\n• Có kiến thức nền tảng tốt về hệ điều hành linux, cấu hình, triển khai web server.\n• Từ 2 năm kinh nghiệm lập trình sử dụng ngôn ngữ Python trên các FrameWork như Django, FastAPI...\n• Từ 1 năm kinh nghiệm lập trình Frontend sử dụng HTML/CSS/Javascript, TypeScript trên các framework như Reactjs, Vuejs…\n• Có kinh nghiệm lập trình trên môi trường cloud đặc biệt là AWS (Ec2, lambda…) là điểm cộng\n• Có khả năng tìm hiểu, thích ứng tốt với công nghệ mới.\n• Có kinh nghiệm đảm nhiệm các vị trí project team leader là điểm cộng.\n• Nhiệt tình, teamwork tốt, sẵn sàng học hỏi các công nghệ mới để đáp ứng công việc.\n• Có tư duy hệ thống, tư duy logic tốt, có khả năng đề xuất vấn đề và giải quyết vấn đề.\n\n• Mức lương: thỏa thuận.\n• Được xây dựng lộ trình và hỗ trợ phát triển trở thành keymember, team leader.\n• Review lương hằng năm, lương tháng 13 theo hiệu quả kinh doanh của công ty.\n• Tham gia BHXH, BHYT, BHTN đầy đủ theo Luật lao động.\n• Nghỉ phép 12 ngày/năm.\n• Hưởng mọi quyền lợi nghỉ Lễ Tết kèm theo thưởng ngày Lễ/Tết trong năm.\n• Trợ cấp đối với nhân sự có thâm niên.\n• Team building định kỳ hàng Quý, du lịch 1 lần/năm.\n• Thời gian làm việc: 08:00 đến 17:00 từ Thứ Hai đến thứ Sáu.\n• Môi trường làm việc thoải mái, trẻ trung, năng động, có nhiều cơ hội thăng tiến và phát triển bản thân.\n\n- Hà Nội: Tầng 6, số 12 Mễ Trì Hạ, phường Mễ Trì, Nam Từ Liêm.\n\n• Thời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2485, 1333, 2, 'Oracle Developer', 'Mô tả công việc\n- Tiếp nhận yêu cầu phát triển từ BA, các đơn vị nghiệp vụ thuộc mảng đơn vị phụ trách, từ các đội nhóm phát triển khác, đánh giá, lên kế hoạch phát triển trên các hệ thống của đơn vị phụ trách (Oracle, OFSAA, CostPerform, Payroll,...) tích hợp dữ liệu, báo cáo, dashboard và thực thi quy hoạch, thiết kế và phát triển;\n- Phát triển tích hợp dữ liệu, báo cáo, Dashboard sử dụng các giải pháp dữ liệu trên các công cụ như: ETL Pentaho, ODI, Oracle BI, Tableau,...;\n- Hỗ trợ xử lý các vấn đề kỹ thuật phát sinh trong quá trình vận hành các hệ thống, dịch vụ\n- Tham gia vào các công đoạn: kiến trúc hệ thống, thiết kế chức năng, lập trình, unit test, viết tài liệu chức năng, tối ưu performance...\n- Lập trình hệ thống các ứng dụng trên nền SQL/PLSQL, Java  và các hệ thống Middleware trên nền tảng của Oracle hay java\n- Tối ưu performance các xử lý giải thuật\n- Tham gia tìm hiểu các công nghệ, kỹ thuật mới.\n\nYêu cầu ứng viên\n- Kiến thức:\n  - Tốt nghiệp Đại học trở lên chuyên ngành CNTT hoặc các ngành tương đương hoặc có các chứng chỉ tương đương được công nhận bởi các tổ chức uy tín\n\n- Kinh nghiệm:\n  - Có trên 2 năm kinh nghiệm làm Oracle\n  - Thành thạo một trong các ngôn ngữ lập trình: SQL/PLSQL, NoSQL, Java, Python\n  - Tư duy/khả năng lập trình tốt và có kỹ năng phân tích hệ thống\n  - Có khả năng phát triển trên ít nhất 1 công cụ ETL hoặc báo cáo (Pentaho, ODI, GG, Oracle BI, Tableau,...)\n  - Có khả năng phát triển ít nhất trên 1 trong các nền tảng: Oracle, OFSAA, Apex, Java Spring, Apache Nifi Air Flow,...\n  - Nắm rõ các quy chuẩn về quy trình xây dựng và triển khai một phần mềm\n  - Ưu tiên:\n    + Có kiến thức làm việc với các công cụ ETL; Công cụ báo cáo BI: Oracle BI, Tableau...;\n    + Có hiểu biết phương pháp làm việc như Agile, phương pháp luận triển khai AIM, CDM trên các nền tảng Oracle\n    + Có kinh nghiệm phát triển, nền tảng kiến trúc OFSAA tối thiểu 2 năm (đặc biệt các module: AML, Fraud, ALM, ICAAP)\n    + Có hiểu biết về lĩnh vực ngân hàng\n    + Đã triển khai và phát triển các ứng dụng, mô hình xử lý dữ liệu trong hệ sinh thái dữ liệu lớn (Big Data)\n    + Ứng viên có kinh nghiệm về xử lý bất đồng bộ, xử lý đa nhiệm, và xử lý dữ liệu theo thời gian thực (near real time), data streaming trên các nền tảng Oracle, Kafka Streams,...phục vụ nhu cầu khai thác dữ liệu theo thời gian thực\n\n- Ngoại ngữ:\n  - Có khả năng đọc viết tiếng Anh (cơ bản) nghe nói (nếu có thể).\n  - Ưu tiên ứng viên có chứng chỉ Tiếng Anh quốc tế (TOEIC 450 trở lên hoặc tương đương)\n\n- Yêu cầu khác:\n  - Kỹ năng giao tiếp và làm việc nhóm tốt\n  - Sẵn sàng làm việc ngoài giờ hành chính\n  - Tinh thần trách nhiệm\n  - Trung thực, tin cậy, cẩn trọng\n\nQuyền lợi\n- Lương thỏa thuận theo năng lực\n- Tối thiểu 13 tháng lương/năm.\n- Thử việc nhận 100% lương\n- Xét tăng lương 1-2 lần/năm.\n- Thưởng: Thưởng Tết, thưởng giới thiệu nhân sự...\n- Văn phòng làm việc chuyên nghiệp hạng A.\n- Môi trường làm việc thân thiện và có tính tương hỗ cao, ổn định lâu dài.\n- Có nhiều cơ hội được đào tạo, làm việc nâng cao trình độ và cơ hội thăng tiến.\n- Có nhiều hoạt động bổ trợ tinh thần, du lịch...\n- Có cơ hội làm việc tại nước ngoài.\n\nĐịa điểm làm việc\n- Hà Nội: 18 Lê Văn Lương, Trung Hòa, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2486, 20, 2, 'Senior Backend Engineer', 'One Mount is Vietnam’s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam’s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nWe are seeking highly skilled Senior Java Developers to enhance our product team. This presents an exceptional opportunity to be part of a prominent and innovative Vietnamese startup, One Mount Group, and contribute to the development of our cobroker platforms.\n\nResponsibilities\n- Writing clean & high-quality code\n- Maintain & improve running- functionality as well as design and develop new system, new feature if needed\n- Deliver end-to-end, including unit test, integration test and deployment to PROD\n- Participate in code reviews & control coding quality standards\n\nQualifications\n- Minimum 5 years of hands-on development experience in Java (Spring Boot framework)\n- Good understanding of Data Structures and Algorithms\n- Expertise in SQL/ NoSQL Databases (MySQL, PostgreSQL, MongoDB)\n- Experience with RESTful APIs, Microservices\n- Familiarity with Redis, Kafka\n- Experience in high-performance, low-latency systems, handling large-scale data processing and real-time transactions\n- Experience with Docker/Kubernetes and Cloud Infrastructure is a plus\n- Experience with Agile or Scrum software development methodologies\n- Familiarity with the financial, banking, or payment gateway domain or PropTech sector is highly desirable.\n\nBenefit and Perks\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check\n- Laptop, screen and other needed facilities/ accounts/ tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'relly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n\nWorking Environment\n- Open & collaborative working space foster both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms, sleep corner.\n- Quarterly/yearly teambuilding & engaged internal events.\n\nĐịa điểm làm việc\n- Hà Nội: Tower 2 - Times City, 458 Minh Khai Street, Hai Ba Trung District, Hanoi, Hai Bà Trưng\n\nThời gian làm việc\n- Thứ 2 (từ 09:00 đến 18:00)\n- Thứ 7 (từ 09:00 đến 13:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2487, 1334, 2, 'Lập Trình Máy CNC', 'Mô tả công việc:\n- Tiếp nhận các bản vẽ từ bộ phận thiết kế.\n- Sử dụng phần mềm thực hiện lập trình gia công các chi tiết, đảm bảo phù hợp với các thông số kỹ thuật của máy CNC.\n- Phối hợp bộ phận chạy máy theo dõi, kiểm soát quá trình gia công, đảm bảo các chi tiết được gia công đạt chất lượng và tiến độ theo yêu cầu.\nYêu cầu ứng viên:\n- Nam từ 25-40 tuổi\n- Có kinh nghiệm lập trình ít nhất 6 tháng (ưu tiên đã làm về mảng khuôn mẫu)\n- Thành thạo phần mềm: NX, Mastercam, Cimatron\n- Chăm chỉ, chịu khó, ham học hỏi, sức khỏe tốt, có trách nhiệm trong công việc.\nQuyền lợi:\n- Lương khởi điểm: 10.000.000 – 15.000.000 đồng/ tháng (thỏa thuận khi PV)\n- Phụ cấp: ăn ca tại công ty.\n- Được đóng đầy đủ các loại BHXH, BHYT, BHTN, … theo Luật lao động.\n- Thưởng tháng lương thứ 13, thưởng thâm niên, thưởng các ngày Lễ, Tết, trung thu, sinh nhật, gia đình vợ con ốm đau, hiếu hỷ, trả phép bằng tiền...\nĐịa điểm làm việc:\n- Hà Nội: Số 12 ngõ 253 Thúy Lĩnh, Lĩnh Nam, Hoàng Mai\nThời gian làm việc:\n- Thứ 2 - Chủ nhật (từ 08:00 đến 17:00)\n- Thứ 3 - Thứ 7 (từ 13:00 đến 22:20)\n- Ca 1: 8h00- 17h20; Ca 2: 13h00-22h20\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2488, 1335, 2, 'NET Developer Thu Nhập Hấp Dẫn', 'Mô tả công việc:\n- Phát triển và bảo trì các ứng dụng Web sử dụng C# và ASP.NET MVC.\n- Tham gia vào quá trình thiết kế, xây dựng và tối ưu hóa hệ thống Web App.\n- Làm việc với cơ sở dữ liệu SQL Server.\n- Phối hợp với các thành viên trong nhóm để đảm bảo tiến độ và chất lượng dự án.\n- Xử lý lỗi, tối ưu hiệu suất và cải thiện trải nghiệm người dùng.\n\nYêu cầu ứng viên:\n- Tối thiểu 3 năm kinh nghiệm, trong đó có 1 năm phát triển Web App bằng C#.\n- Thành thạo ASP.NET MVC, ưu tiên ứng viên chuyên về phát triển Web.\n- Có kinh nghiệm làm việc với SQL Server, Entity Framework.\n- Biết sử dụng HTML, CSS, JavaScript, jQuery là lợi thế.\n- Có tư duy logic, kỹ năng giải quyết vấn đề tốt.\n- Chủ động, có trách nhiệm với công việc.\n\nQuyền lợi:\n- Chế độ thưởng theo quý, năm; tiền quà các ngày Lễ, Tết, ngày thành lập Tập đoàn; hỗ trợ chi phí nghỉ dưỡng hằng năm...\n- Hưởng Bảo hiểm Xã hội, Bảo hiểm Y tế theo quy định của Luật Lao động và công ty.\n- Làm việc trong môi trường chuyên nghiệp, sáng tạo, cạnh tranh, phát triển, năng động có nhiều cơ hội thăng tiến.\n- Cơ hội học tập, nghiên cứu, làm việc trong nước và các nước trên thế giới.\n- Cơ hội tiếp cận với nhiều công nghệ mới.\n- Cơ hội thăng tiến, phát triển bản thân.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 112, Đường Chùa võ, Khu đô thị Dương Nội, Hà Đông.\n- Hà Nội: Hoàng Cầu, Đống Đa.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n- Thứ 7 (từ 08:00 đến 12:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2489, 1336, 2, 'Kỹ Sư Lập Trình CNC', 'Tóm tắt công việc: Chúng tôi đang tìm kiếm một Kỹ sư Lập trình CNC có kỹ năng và sự tỉ mỉ để phát triển và tối ưu hóa các chương trình gia công CNC nhằm hỗ trợ quy trình gia công chính xác. Ứng viên lý tưởng sẽ làm việc chặt chẽ với các bộ phận sản xuất, kỹ thuật và chất lượng để đảm bảo các chi tiết được gia công đạt yêu cầu về thiết kế và tiêu chuẩn chất lượng.\n\nNhiệm vụ chính:\n1. Lập trình máy CNC bằng phần mềm CAM (ví dụ: Mastercam, NX, Fusion 360) dựa trên bản vẽ kỹ thuật 2D/3D hoặc mô hình CAD.\n2. Lựa chọn dao cụ, thông số cắt và chiến lược gia công phù hợp để sản xuất hiệu quả.\n3. Mô phỏng, kiểm tra và xác nhận chương trình CNC để đảm bảo an toàn, chính xác và hiệu quả.\n4. Tối ưu hóa chu trình gia công để giảm thời gian, tăng tuổi thọ dao cụ và đảm bảo chất lượng sản phẩm.\n5. Hỗ trợ việc setup và xử lý sự cố của máy CNC trong quá trình chạy chương trình lần đầu.\n6. Phối hợp với kỹ sư thiết kế để đánh giá khả năng gia công của sản phẩm và đề xuất các điều chỉnh nếu cần thiết.\n7. Quản lý và lưu trữ hệ thống chương trình CNC và tài liệu liên quan một cách khoa học.\n\nYêu cầu ứng viên:\n1. Tốt nghiệp Cao đẳng hoặc Đại học chuyên ngành Cơ khí, Kỹ thuật sản xuất hoặc lĩnh vực liên quan.\n2. Có ít nhất 5 năm kinh nghiệm lập trình CNC trong môi trường sản xuất chính xác. Hiểu rõ về mã G-code, M-code và vận hành máy CNC (phay, tiện, máy nhiều trục).\n3. Thành thạo phần mềm CAD/CAM (ví dụ: Mastercam, Siemens NX, Fusion 360, SolidCAM).\n4. Đọc hiểu tốt bản vẽ kỹ thuật, ký hiệu GD&T và mô hình 3D.\n5. Hiểu biết về các loại vật liệu gia công như thép, nhôm, nhựa,...\n\nQuyền lợi:\n1. Lương cạnh tranh theo năng lực.\n2. Đóng Bảo hiểm full lương.\n3. Gói bảo hiểm PVIcare.\n4. Tháng lương thứ 13.\n5. Thưởng hiệu suất.\n6. Xe đưa đón từ Hà Nội - Thái Nguyên, Bắc Ninh - Thái Nguyên.\n7. Làm thứ 7 luân phiên.\n\nĐịa điểm làm việc:\n- Thái Nguyên: Lô CN1-1. KCN Sông Công II, Xã Tân Quang, Sông Công, TP Sông Công.\n- Bắc Ninh.\n- Hà Nội.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\nLàm thứ 7 luân phiên.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2490, 1337, 2, 'Senior Android Developer (Mini CTO)', 'Sonix là một nền tảng ứng dụng nhạc chuông di động thông minh, hướng đến việc cá nhân hóa trải nghiệm âm thanh trên điện thoại di động theo phong cách trẻ trung, hiện đại và giàu tính giải trí. Dự án tập trung vào khai thác các nội dung âm thanh độc quyền, xu hướng viral, nhạc hot và tích hợp công nghệ AI để đề xuất nhạc chuông phù hợp với cá tính, thói quen và cảm xúc người dùng.\n\nDự án Sonix sẽ được triển khai và vận hành bởi một công ty con chuyên trách, có cơ cấu quản lý riêng, độc lập về mặt vận hành, công nghệ và sản phẩm. TP Entertainment – với vai trò là nhà đầu tư chiến lược sẽ đóng góp nguồn lực tài chính, kinh nghiệm trong lĩnh vực Mobile App, đồng thời hỗ trợ định hướng phát triển thị trường và chiến lược thương hiệu cho Sonix.\n\nVị trí Mini CTO sẽ là lãnh đạo cao nhất về công nghệ trong công ty con phát triển ứng dụng Sonix:\n\nMÔ TẢ CÔNG VIỆC\nPhát triển và vận hành hệ thống:\n- Phát triển ứng dụng mobile trên nền tảng Android (Kotlin), bao gồm cả phía Client và Backend.\n- Quản lý và tối ưu hiệu suất hệ thống, xử lý các sự cố kỹ thuật như crash, ANR, đảm bảo độ ổn định cao cho sản phẩm.\n- Quản lý chất lượng kỹ thuật của source code và quy trình release sản phẩm.\n\nTư vấn và xây dựng giải pháp kỹ thuật:\n- Đưa ra giải pháp kỹ thuật toàn diện cho PM và đội ngũ kỹ thuật, bao gồm cả kiến trúc Client, Backend và System.\n- Tham gia định hướng, đánh giá và phê duyệt các giải pháp công nghệ quan trọng.\n\nQuản lý đội ngũ và tiến độ công việc\n- Quản lý nhóm Developers, QA, và làm việc chặt chẽ với các bộ phận Backend/System.\n- Điều phối công việc, theo dõi tiến độ và báo cáo trực tiếp với PM.\n- Đảm bảo tiến độ và chất lượng sản phẩm qua từng giai đoạn phát triển.\n\nĐào tạo và phát triển nhân sự\nĐánh giá và kiểm thử sản phẩm\n- Trực tiếp test sản phẩm trước khi release, đảm bảo các tiêu chuẩn về nghiệp vụ và trải nghiệm người dùng.\n- Đưa ra đề xuất cải tiến dựa trên hành vi người dùng, chỉ số vận hành và chiến lược sản phẩm.\n\n1. Kiến thức bắt buộc:\n- Từ 2 năm kinh nghiệm ở vị trí tương đương, open kinh nghiệm cho level Senior Dev trở lên.\n- Thành thạo ngôn ngữ lập trình Kotlin (Android) ở mức master.\n- Am hiểu về software design pattern, hệ quản trị cơ sở dữ liệu MySQL, lập trình full-stack (Java, Python, Shell).\n- Kinh nghiệm vận hành hệ thống CI/CD, phân tích log, tối ưu hệ thống backend.\n- Hiểu biết về UI/UX, hành vi trải nghiệm người dùng (CX) và các yếu tố tác động đến Retention.\n- Thành thạo trong việc tích hợp và vận hành Admob Mediation, MAX Mediation, quản lý Adapter và đảm bảo tuân thủ chính sách quảng cáo.\n- Thành thạo trong việc theo dõi, đánh giá các chỉ số sản phẩm như Crash, ANR, CTR, Retention, Install/Remove app,...\n- Biết cách sử dụng các công cụ phân tích dữ liệu như Power BI, thực hiện truy vấn, phân tích dữ liệu chuyên sâu phục vụ cải tiến sản phẩm.\n– Nắm vững nghiệp vụ ứng dụng, đặc biệt là các nghiệp vụ Monetization và hành vi người dùng. \n\nKiến thức nâng cao (lợi thế):\n- Có hiểu biết về hệ thống là một lợi thế.\n- Hiểu biết về các hình thức quảng cáo, quy trình load/show quảng cáo tuần tự, tối ưu hiệu suất quảng cáo.\n\n2. Kỹ năng\n- Lãnh đạo (Leadership): Tư duy chiến lược, khả năng đánh giá nhân sự, lập kế hoạch, truyền động lực, coaching và xây dựng văn hóa nhóm.\n- Giải quyết vấn đề: Problem solving, Design thinking.\n- Giao tiếp & làm việc nhóm, lắng nghe và truyền đạt thông tin.\n- Học hỏi và tự học tốt; tổ chức và quản lý thời gian.\n\n3.Tố chất\n- Tư duy logic\n- Tư duy hệ thống\n- Tỉ mỉ, cẩn thận\n\nQuyền lợi\n- Thử việc 02 tháng hưởng 100% mức lương chính thức.\n- Có cơ hội trở thành nhân viên chính thức và được tiếp cận các công cụ tốt nhất thị trường.\n- Thu nhập không giới hạn: Lương cứng + thưởng KPI, thưởng dự án, lương tháng 13, thưởng Tết,\n- Thu nhập lên tới 15-16 tháng lương/năm.\n- Thưởng và review lương 2 lần/năm.\n- Khám sức khỏe định kỳ hàng năm.\n- Trợ cấp tiền ăn trưa khi là nhân viên thử việc.\n- Du lịch hàng năm, dã ngoại hàng quý 4 lần/năm, được hỗ trợ du lịch cùng người thân.\n- Hưởng đầy đủ các chế độ bảo hiểm theo quy định của nhà nước khi là nhân viên chính thức.\n\nThời gian làm việc:\n8:30 – 18:00 (nghỉ trưa 1 tiếng 30′, giải lao 30′) \n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2491, 1338, 2, 'Blockchain Developer', 'Mô tả công việc\n- Phát triển và bảo trì giao diện người dùng (UI) cho các ứng dụng DeFi và Crypto trên nền tảng di động (iOS và Android), tích hợp với blockchain (Ethereum, Solana, v.v.).\n- Thiết kế và triển khai các tính năng frontend di động tương tác với smart contract (ví dụ: AMM, staking, lending, NFT).\n- Tối ưu hóa App Listing và App Store Optimization (ASO) cho ứng dụng di động trên App Store và Google Play, bao gồm metadata, từ khóa, hình ảnh và nội dung quảng bá.\n- Phối hợp với đội ngũ backend và blockchain để tích hợp API và dịch vụ on-chain vào ứng dụng di động.\n- Phân tích dữ liệu ASO (tỷ lệ tải, đánh giá, xếp hạng) và đề xuất cải tiến để tăng khả năng hiển thị ứng dụng trên các kho ứng dụng.\n- Đảm bảo giao diện di động thân thiện với người dùng, tuân thủ chính sách của App Store/Google Play và tối ưu hiệu suất trên các thiết bị di động.\n\nYêu cầu ứng viên\n- Tối thiểu 2 năm kinh nghiệm phát triển ứng dụng di động, ưu tiên trong các dự án blockchain/DeFi.\n- Thành thạo các ngôn ngữ và công cụ lập trình di động:\n  - Android: Kotlin, Java, C/C++ (NDK), Dart (Flutter là một lợi thế).\n  - iOS: Swift, Objective-C, React Native (JS) là một lợi thế.\n- Kinh nghiệm tích hợp frontend di động với blockchain qua Web3.js, Ethers.js, hoặc Solana Web3.js.\n- Hiểu biết về smart contract (Solidity, Rust) và các giao thức DeFi (Uniswap, Aave, v.v.).\n- Kiến thức về ASO, bao gồm tối ưu hóa từ khóa, mô tả ứng dụng, và phân tích hiệu suất qua các công cụ như App Annie, Sensor Tower.\n- Thành thạo công cụ phát triển di động: Xcode, Swift Package Manager, Android Studio.\n- Ưu tiên: Kinh nghiệm phát triển ứng dụng di động đa nền tảng (React Native, Flutter) và tích hợp blockchain trên mobile.\n- Có khả năng đọc hiểu tài liệu tiếng Anh.\n\nQuyền lợi\n- Thu nhập cạnh tranh, thưởng dựa trên hiệu quả công việc.\n- Tham gia dự án blockchain thực chiến, ảnh hưởng trực tiếp đến thiết kế và vận hành ứng dụng di động.\n- Môi trường làm việc chuyên nghiệp, cởi mở, khuyến khích sáng tạo và đổi mới.\n- Cơ hội tiếp cận các công nghệ blockchain và công nghệ di động tiên tiến nhất.\n- Đồ ăn vặt, snack giữa giờ thoải mái; hoạt động gắn kết như ăn lẩu Haidilao hàng tháng.\n- Thời gian làm việc linh hoạt: 9h00 - 17h30 (Thứ 2 đến Thứ 6).\n- Công ty chi trả chi phí gửi xe tại tòa nhà.\n\nĐịa điểm làm việc\n- Hà Nội: Cầu Giấy\n- Hà Nội: Thanh Xuân\n- Hà Nội: Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2492, 1339, 2, 'Lập Trình Viên C++ FullStack (3+ Năm Kinh Nghiệm)', 'Mô tả công việc:\n- Tham gia phát triển và duy trì hệ thống phần mềm sử dụng ngôn ngữ C++, theo mô hình Full Stack.\n- Quản lý phân chia công việc cho các thành viên trong team.\n- Thiết kế, xây dựng và tối ưu hóa cơ sở dữ liệu với Entity Framework.\n- Kết hợp phát triển ứng dụng giao diện Flutter khi cần thiết (mobile hoặc desktop).\n- Áp dụng Design Pattern vào kiến trúc phần mềm để đảm bảo hệ thống ổn định, dễ bảo trì.\n- Phối hợp với team QA, UI/UX để triển khai tính năng mới và sửa lỗi.\n- Viết tài liệu kỹ thuật cho sản phẩm.\n\nYêu cầu ứng viên:\n- Có từ 3–5 năm kinh nghiệm làm việc với C++ Full Stack.\n- Thành thạo Entity Framework, có khả năng thiết kế và tối ưu hệ thống cơ sở dữ liệu.\n- Có hiểu biết hoặc đã từng làm việc với Flutter là một lợi thế lớn.\n- Nắm vững các Design Pattern phổ biến (MVC, Singleton, Observer, Factory...).\n- Có kỹ năng phân tích yêu cầu, tư duy logic tốt, có tinh thần học hỏi và cầu tiến.\n- Ưu tiên ứng viên có khả năng làm việc độc lập và tinh thần teamwork tốt.\n\nQuyền lợi:\n- Mức lương cạnh tranh: từ 14.000.000 đến 20.000.000 VNĐ/tháng, tùy theo năng lực và kinh nghiệm.\n- Xét tăng lương định kỳ và thưởng theo hiệu suất công việc.\n- Cơ hội tham gia vào các dự án lớn, quy mô thực tế với khách hàng trong và ngoài nước.\n- Làm việc trong môi trường công nghệ chuyên nghiệp, năng động, hỗ trợ phát triển cá nhân.\n- Tham gia BHXH, BHYT đầy đủ, cùng các chế độ phúc lợi khác (teambuilding, nghỉ lễ, quà sinh nhật).\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 331 Trần Xuân Soạn, Phường Tân Kiểng, Quận 7.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2493, 1340, 2, 'Kỹ Sư Lập Trình PC Control', 'Mô tả công việc:\n- Development of automation equipment PC control\n- More details to be discussed during interview\n- Working in HAI PHONG office.\n- Collaborate with hardware and software teams to integrate and optimize PC-based control systems for automated machinery.\n\nYêu cầu ứng viên:\n- Experience in operating PC machine\n- C#, C++ available\n- Fluent in English, able to abroad business trip\n- Graduated from Electrical & Electronics, Automation, IT related majors\n- Accept new students graduate.\n\nQuyền lợi:\n- Nghỉ 2 T7, 4 Chủ Nhật\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội học hỏi và phát triển kỹ năng trong lĩnh vực công nghệ và sản xuất\n- Được đào tạo về quy trình sản xuất và các công nghệ mới trong ngành\n- Chế độ bảo hiểm, phúc lợi đầy đủ theo quy định của pháp luật\n- Lương thưởng cạnh tranh, đánh giá năng lực định kỳ để tăng lương\n- Các chế độ phúc lợi: du lịch hằng năm, teambuilding, sinh nhật, lễ tết\n- Được tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn.\n\nĐịa điểm làm việc:\n- Hải Phòng: Thửa đất B31 thuộc Lô CN4, KCN An Dương, Phường Hồng Phong, An Dương.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2494, 1264, 2, 'Kỹ Sư Lập Trình PLC - Thiết Kế Điện', 'Mô tả công việc:\n- Lập kế hoạch dự án, lên giải pháp, danh mục vật tư các thiết bị điện, lập bản vẽ đấu nối điện layout thiết bị, sử dụng phần mềm Eplan và Cad.\n- Lập trình PLC, HMI, Lập trình Robot 2-4-6 trục (Mitsubishi, Keyence, Omron, ABB, UR robot ...) và các thiết bị tự động hóa để điều khiển máy móc trong công nghiệp.\n- Lập trình điều khiển step motor, servo motor, Inverter và các thiết bị chuyển đổi Analog-Digital, các loại cảm biến và khí nén thủy lực...\n- Lập trình truyền thông công nghiệp RS485, RS232, Ethernet TCP/IP, Modbus,...\n\nYêu cầu ứng viên:\n- Học vấn : Tốt nghiệp Đại học trở lên các trường kỹ thuật ( Bách khoa, công nghiệp, học viện kỹ thuật quân sự, Giao thông vận tải và các trường kỹ thuật khác)\n- Biết lập trình các dòng PLC Mitsubishi, Keyence. Điều khiển các thiết bị công nghiệp.\n- Biết sử dụng Biến tần, Servo và các thiết bị điều khiển động cơ khác.\n- Hiểu biết về các loại truyền thông công nghiệp..\n- Có khả năng làm việc độc lập và làm việc theo nhóm tốt\n- Chịu được áp lực công việc, ham học hỏi, đam mê kỹ thuật.\n- Chấp nhận ra Hà Nội đào tạo từ 9 - 12 tháng.\n\nQuyền lợi:\n- Chế độ đãi ngộ:\n- Thu nhập từ 9.000.000đ - 15.000.000đ++/tháng. Performance review 2 lần/năm và đột xuất;\n- Thưởng sinh nhật, lễ, tết, quý, tháng lương 13,...;\n- Công tác: Công tác phí, Phụ cấp ăn, xe Công ty đưa đón,..;\n- Chế độ phép linh hoạt 1 ngày/tháng áp dụng từ khi thử việc.\n\n- Chế độ sức khỏe cho nhân viên:\n- Chế độ BHXH theo cấp bậc và thâm niên công tác;\n- Tài trợ 100% thẻ BHSK Bảo Việt cho NLĐ và con đầu tiên, 70% cho con thứ 2,... khám tại tất cả các BV Công và Quốc tế;\n- Khám sức khỏe định kỳ 01 lần/năm tại Bệnh viện dịch vụ 5 sao.\n\n- Tiện ích văn phòng:\n- Không gian làm việc đầy đủ tiện nghi (văn phòng làm việc xanh, tủ lạnh, lò vi sóng..; siêu thị, nhà hàng, bể bơi, gym, bi-a, hair salon, trường mầm non ngay bên cạnh)\n- Cơm văn phòng tự chọn.\n\n- Đào tạo:\n- Đào tạo nội bộ, đào tạo ngoài kiến thức chuyên môn, kỹ năng... phục vụ công việc.\n\n- Các hoạt động sôi nổi:\n- Du xuân, du lịch hè, family day 3 lần/năm;\n- Cấp quỹ Entertainment 100k/người/tháng theo team/phòng ban;\n- Tổ chức sinh nhật cho CBNV định kỳ 01 lần/tháng;\n- Câu lạc bộ, giải bóng đá, bóng bàn, cầu lông, bi-a, esport,...\n\nThời gian làm việc: Từ T2 - hết thứ 6, thứ 7 làm việc/ nghỉ cách tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2495, 272, 2, 'Tech Lead (Backend Developer)', 'Mô tả công việc\n- Phối hợp, hỗ trợ cùng với Technical Lead trong việc tiếp nhận đầu bài từ Business Analyst/ Business Solution nhằm đánh giá, phân tích tính khả thi việc triển khai sản phẩm\n- Phối hợp, tham gia cùng với Technical Lead trong việc thiết kế giải pháp phần mềm, giải pháp tích hợp API, Module/Layer, Data storage\n- Phát triển các sản phẩm phần mềm theo giải pháp, công nghệ do Technical Lead đưa ra (Nghiệp vụ phức tạp nhất; Độ khó sản phẩm cao nhất; Phạm vi ảnh hưởng và độ rủi ro cao nhất)\n- Triển khai các giải pháp bảo mật theo quy định\n- Đánh giá yêu cầu xây dựng (đánh giá được hết tất cả các trường hợp, hiểu bản chất của vấn đề), sửa đổi tính năng\n- Xử lý lỗi phát sinh trong quá trình vận hành\n- Tổ chức chia sẻ/đào tạo chuyên môn nghiệp vụ/ Biz Domain trong mảng công việc phụ trách\n- Tìm kiếm các phương án tối ưu nhằm nâng cao giải pháp, hiệu suất cho quá trình phát triển sản phẩm\n- Nghiên cứu, cập nhật các xu hướng, công nghệ liên quan đến phát triển sản phẩm\n\nYêu cầu ứng viên\n1. Kinh nghiệm làm việc\n- Có tối thiểu từ 5 năm kinh nghiệm phát triển backend sử dụng ngôn ngữ Java.\n- Có kinh nghiệm làm việc với các hệ quản trị dữ liệu quan hệ như MySQL/PostgreSQL và Search Engine như Solr/ElasticSearch...\n- Có kinh nghiệm viết Unit test, Integration test.\n- Ưu tiên có kinh nghiệm: Spring Cloud, Spring Security, Redis, Kafka, CICD ...\n- Có kinh nghiệm triển khai, phát triển phần mềm bằng Agile/ Scrum.\n\n2. Kiến thức/Năng lực chuyên môn/Kỹ năng\n- Có khả năng phân tích, sắp xếp và triển khai công việc theo thứ tự ưu tiên.\n- Có kỹ năng giao tiếp và làm việc nhóm tốt.\n- Có đam mê và định hướng lâu dài với nghề lập trình\n- Cần phải có hiểu biết về khoa học máy tính\n- Cần phải có hiểu biết vững chắc về các nguyên tắc cơ bản của JDK 8+, Spring boot 2.x+, Spring framework 5+.\n- Yêu cầu kiến thức và kỹ năng: API RESTful, Microservice architecture, Distributed transaction, Code management (GitHub/JIRA....)\n- Kiến thức về các ngôn ngữ lập trình: Đây là nền tảng cơ bản của lập trình. Một lập trình viên cần biết ít nhất một ngôn ngữ lập trình để có thể viết mã.\n- Kiến thức về các cấu trúc dữ liệu và thuật toán: Đây là những kiến thức cần thiết để viết mã hiệu quả và hiệu suất.\n- Kiến thức về các framework và thư viện: Các framework và thư viện cung cấp các tính năng và chức năng sẵn có, giúp lập trình viên tiết kiệm thời gian và công sức.\n- Kiến thức về cơ sở dữ liệu: Cơ sở dữ liệu lưu trữ dữ liệu của một ứng dụng hoặc trang web. Lập trình viên cần có kiến thức về cách truy cập và quản lý dữ liệu trong cơ sở dữ liệu.\n- Kiến thức về kiến trúc web: Kiến trúc web là cách thức các trang web và ứng dụng được thiết kế và xây dựng. Lập trình viên cần có kiến thức về cách thiết kế và xây dựng các trang web và ứng dụng có thể mở rộng và bảo mật.\n- Kiến thức về bảo mật: Bảo mật là một vấn đề quan trọng đối với các ứng dụng và trang web. Lập trình viên cần có kiến thức về cách bảo vệ các ứng dụng và trang web khỏi các cuộc tấn công bảo mật.\n\n3. Năng lực cốt lõi\n- Có tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty (IPAM & 4C)\n\nQuyền lợi\n1. Cộng đồng những người làm nghề chính trực và dấn thân phụng sự \n- Môi trường làm nghề tài chính chuyên nghiệp.\n- Làm việc với tinh thần làm chủ, sáng tạo và thách thức.\n\n2. Tổng thu nhập theo năng lực\n- Thu nhập xứng đáng theo năng lực và giá trị đóng góp.\n- Xem xét thay đổi thu nhập hàng năm.\n\n3. Chế độ đãi ngộ\n- Tham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động.\n- Được tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24.\n\n4. Tổ chức học tập và văn hóa sôi nổi\n- Không gian làm việc mở với trang thiết bị hiện đại.\n- Các hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.\n\nĐịa điểm làm việc\n- Hà Nội: 43 Lê Văn Lương, Thanh Xuân\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2496, 1341, 2, 'Chuyên Viên Cao Cấp Ngân Hàng Số (Web,App)', 'Mô tả công việc\n- Tham gia xây dựng các quy trình, hướng dẫn về nghiệp vụ của Đơn vị.\n- Báo cáo và tham gia khắc phục rủi ro của đơn vị trong quá trình vận hành, phối hợp với các đơn vị liên quan để đưa ra các phương pháp đo lường và giảm thiểu rủi ro.\n- Thực hiện các công việc theo đúng các chính sách, quy định, quy trình, hướng dẫn nội bộ,… và cam kết chất lượng dịch vụ (SLAs).\n- Chịu trách nhiệm thực hiện thiết kế, phát triển tích hợp, hỗ trợ cấp độ 3 và vận hành cấp độ 3 các nền tảng và công nghệ ngân hàng số và các hệ thống có liên quan.\n- Tham gia trao đổi cùng BA, RM,… và đề xuất phương án thực hiện các yêu cầu phát triển đảm bảo hiệu quả nhất.\n- Trực tiếp thực hiện và phối hợp với các bộ phận khác trong các dự án có các thành phần liên quan đến nền tảng và công nghệ ngân hàng số và các hệ thống có liên quan trong các dự án công nghệ của Khối.\n- Thực hiện các công việc khác có liên quan theo yêu cầu của các cấp quản lý.\n\nYêu cầu ứng viên\n- Có khả năng lập trình với một trong các ngôn ngữ sau: Android: Kotlin || Java; iOS Swift; Flutter.\n- Java: Am hiểu framework Springboot; Hiểu biết về các chuẩn message JSON và các cơ sở dữ liệu Oracle, SQL, Redis … là 1 một lợi thế; Có kiến thức triển khai và cấu hình Webserver: Tomcat; GraphQL; Apollo Server.\n- Angular: Nắm vững HTML/CSS, JavaScript; Có kiến thức triển khai và cấu hình. Webserver: Nginx; Có kinh nghiệm sử dụng theme Metronic là lợi thế.\n\nQuyền lợi\n- Thu nhập hấp dẫn cùng gói phúc lợi toàn diện.\n- Hệ thống các khóa đào tạo phát triển bản thân tương ứng từng vị trí công việc.\n- Lộ trình thăng tiến rõ ràng.\n- Trải nghiệm các hoạt động văn hóa tổ chức đặc sắc.\n\nĐịa điểm làm việc\n- Hà Nội: Số 25 Trần Hưng Đạo, Hoàn Kiếm, Hoàn Kiếm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2497, 1342, 2, 'Lập Trình Viên Fullstack Developer (Thu Nhập Từ 20tr - 25tr)', '1/ Phân tích nhu cầu và lập kế hoạch triển khai\n- Tiếp nhận và làm rõ yêu cầu từ các phòng ban liên quan đến các hệ thống nghiệp vụ như CRM, HRM, ERP, POS,.. và các website bán hàng.\n- Phối hợp với các phòng ban để phân tích quy trình vận hành, xác định nhu cầu thực tế và đưa ra giải pháp công nghệ phù hợp.\n- Lập kế hoạch triển khai, xác định mốc thời gian và đề xuất tài nguyên kỹ thuật cần thiết.\n\n2/ Thiết kế kiến trúc và lập trình hệ thống\n- Thiết kế chi tiết các giải pháp công nghệ theo yêu cầu nghiệp vụ đã thống nhất, bao gồm tích hợp dịch vụ bên ngoài (thanh toán trực tuyến, đăng nhập qua bên thứ ba,...).\n- Lựa chọn và triển khai công nghệ phù hợp (ngôn ngữ lập trình, framework, cơ sở dữ liệu...) đảm bảo hệ thống vận hành hiệu quả, bảo mật, dễ bảo trì và tương thích đa nền tảng.\n- Thực hiện lập trình và kiểm thử nội bộ theo kịch bản giả lập tình huống thực tế trong vận hành.\n- Phối hợp với người dùng để kiểm tra tính ổn định, ghi nhận phản hồi và hiệu chỉnh phần mềm khi cần thiết.\n\n3/ Bảo trì, nâng cấp và hỗ trợ vận hành\n- Xử lý lỗi kỹ thuật phát sinh trong quá trình sử dụng: lỗi logic, giao diện, thao tác người dùng...\n- Cập nhật, nâng cấp tính năng và giao diện theo yêu cầu nghiệp vụ từ các bộ phận chuyên môn.\n- Theo dõi, đánh giá hiệu năng hệ thống và đề xuất phương án tối ưu hóa định kỳ.\n\nYêu cầu ứng viên:\n1/ Kinh nghiệm: Tối thiểu 2 năm làm việc tại vị trí tương đương trong các công ty hoạt động trong lĩnh vực thương mại, bán lẻ, chuỗi cửa hàng, hoặc sàn thương mại điện tử.\n\n2/ Kỹ năng Front-End:\n- Thành thạo các ngôn ngữ và framework phát triển giao diện người dùng như Vue.js, React, HTML5, CSS3, Bootstrap hoặc các CSS framework tương tự.\n- Có tư duy thiết kế giao diện tối ưu trải nghiệm người dùng (UX/UI).\n\n3/ Kỹ năng Back-End:\n- Thành thạo ít nhất một trong các ngôn ngữ lập trình server-side như Node.js, Python, PHP,...\n- Có kinh nghiệm xây dựng RESTful API, xử lý nghiệp vụ phức tạp, bảo mật và tối ưu hiệu suất hệ thống.\n\n4/ Ưu tiên (Điểm cộng):\n- Có kinh nghiệm triển khai hệ thống theo kiến trúc Microservices, bao gồm phân tách dịch vụ, giao tiếp nội bộ qua message queue, và đảm bảo tính mở rộng linh hoạt.\n- Từng xử lý các bài toán dữ liệu lớn (big data), bao gồm lưu trữ, phân tích, và đồng bộ dữ liệu trên quy mô nhiều hệ thống.\n- Đã triển khai hoặc tham gia vào các dự án có yêu cầu cân bằng tải, tối ưu hiệu suất hệ thống và xử lý lượng người dùng lớn cùng lúc.\n- Thiết kế và giao diện: Có kiến thức và khả năng sử dụng các phần mềm thiết kế như Adobe Photoshop, Sketch, hoặc công cụ tương đương để làm việc với UI/UX designer (nếu có).\n- Cơ sở dữ liệu: Nắm vững kiến thức về SQL và có khả năng thiết kế, tối ưu hóa cơ sở dữ liệu quan hệ.\n- Công cụ phát triển: Sử dụng thành thạo các công cụ quản lý mã nguồn như Git, SVN (ưu tiên ứng viên có kinh nghiệm với Git workflow chuyên nghiệp).\n\n5/ Kỹ năng mềm:\n- Khả năng quản lý thời gian, làm việc nhóm hiệu quả và giao tiếp tốt với các bộ phận liên quan.\n- Kỹ năng tư duy phân tích và giải quyết vấn đề linh hoạt trong môi trường làm việc thực tế.\n- Có tinh thần tự học và cập nhật công nghệ mới.\n\nQuyền lợi:\n- Thu nhập: dao động 20.000.000 - 25.000.000 (Lương cơ bản +Thưởng)\n- Chính sách lương thưởng đầy đủ, rõ ràng. \n- Thưởng cuối năm theo kết quả kinh doanh.\n- Đóng BHXH, BHYT theo quy định Nhà nước.\n- Tham gia du lịch công ty kết hợp các hoạt động xây dựng đội nhóm.\n- Mua hàng nội bộ với chính sách ưu đãi hàng tháng.\n- Nhận quà vào ngày sinh nhật theo chính sách cho từng cấp bậc.\n- Hoạt động ngoại khóa thường xuyên vào mỗi thứ 5 hàng tuần, bao gồm: bóng đá, cầu lông, chạy bộ...\n- Làm việc trong môi trường hoà đồng, không rào chắn, quản lý công việc bằng hệ thống và được tiếp nhận đầy đủ hướng dẫn từ đồng nghiệp và quản lý cấp trên.\n- Thường xuyên tổ chức những lớp đào tạo kiến thức sản phẩm, PCCC, sử dụng hệ thống công nghệ để quản lý kho hàng...với mong muốn bạn phát triển cùng MIA.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 117 - 119 Bạch Đằng, Phường 15, Bình Thạnh.\n\nThời gian làm việc:\n- Thứ 2 – thứ 6: 8h – 17h / Thứ 7: làm 2 ngày, nghỉ 2 ngày.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2498, 1343, 2, 'Fullstack Developer (Reactjs & PHP) - Tối Thiểu 2 Năm Kinh Nghiệm', 'Mô tả công việc\n- Develop apps for e-commerce platforms Shopify/ WooCommerce.\n- Deliver high-quality products on schedule.\n- Communicating and reporting work progress to the manager.\n- Collaborate with the team to enhance/add features to the apps based on personal insights.\n- Supporting colleagues in completing the product together.\n\nYêu cầu ứng viên\n- FE: Proficient in ReactJS.\n- BE: Proficient in PHP - Laravel.\n- At least 2 years of practical project experience with the mentioned technologies.\n- Proficient in using Git.\n- Solid understanding of MySQL or NoSQL databases.\n- Experience with front-end technologies: HTML, CSS, JavaScript frameworks (jQuery, Vue.js, Bootstrap)\n- Knowledge Shopify, Shopify theme, liquid,...\n- Proactive and efficient\n\nQuyền lợi\n- Competitive salary (negotiable based on experience);\n- Working from Monday - Friday, 8 AM- 5 PM, no OT;\n- Performance bonus, 13th- month salary, public holidays bonus (30/4, 1/5, 2/9, 1/1); bonus for\n- Excellent Employee and Excellent Team;\n- Comprehensive insurance package including social, health, unemployment, and Bao Viet care insurance;\n- Work performance review 2 times/year (in May and November);\n- 01 hour paid leave per day for women having children under 12 months;\n- Annual health check;\n- 12 - 18 days full paid leave/year;\n- A Learning budget up to 25 million VND per\n- Yearly company trip and year-end party, quarterly team building and Sports Clubs;\n- Men’s Day, Women’s Day, Mid-Autumn Festival and other benefits under the provisions of the company;\n- Working in a product development environment, owning the product in charge, participating in the process of bringing ideas, improving product innovation\n- Nice working space with young, dynamic & friendly colleagues and free coffee, tea, and drinks.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2499, 1344, 2, 'Mobile Developer (React Native)', 'Mô tả công việc\n- Thiết kế, phát triển và duy trì ứng dụng di động đa nền tảng (iOS & Android) bằng React Native (bao gồm tích hợp Native code nếu cần).\n- Phối hợp chặt chẽ với đội ngũ sản phẩm, thiết kế và backend để mang lại trải nghiệm mượt mà, thân thiện và bảo mật cho người dùng.\n- Tối ưu hiệu suất ứng dụng, giao diện người dùng (UI/UX) và đảm bảo tính ổn định khi xử lý dữ liệu chuyển động và hệ thống phần thưởng.\n- Viết mã sạch, có cấu trúc rõ ràng và dễ bảo trì; tham gia đánh giá mã (code review) cùng đội ngũ kỹ thuật.\n- Góp phần cải tiến liên tục sản phẩm dựa trên phản hồi từ người dùng và số liệu hành vi sử dụng.\nĐóng góp ý tưởng phát triển các tính năng như hệ thống quy đổi phần thưởng, ví tiền số, hệ thống leaderboard…\n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm phát triển phần mềm, trong đó có kinh nghiệm vững với React Native.\n- Đã từng phát triển và đưa ứng dụng lên App Store và Google Play.\n- Hiểu rõ kiến trúc ứng dụng di động, quản lý trạng thái, tối ưu hiệu năng, và đảm bảo an toàn bảo mật dữ liệu người dùng.\n- Ưu tiên ứng viên có kinh nghiệm tích hợp thiết bị đo bước chân (Google Fit, Apple HealthKit) và/hoặc ứng dụng liên quan tới tiền mã hóa, phần thưởng token, hệ thống ví tiền số. Hoặc ưu tiên có kinh nghiệm tích hợp các eKYC, Cổng thanh toán, Social Login, Tracking, Analytics, Marketing Tool,…\n- Có tư duy sản phẩm tốt, chủ động đề xuất cải tiến và làm việc theo mô hình Agile/Scrum.\n\nQuyền lợi\n- Mức thu nhập 23-30 triệu gross, thỏa thuận khi phỏng vấn.\n- Cơ hội phát triển, khẳng định chính mình và thăng tiến cực lớn, trở thành nhà quản lý chỉ sau 2 - 3 năm.\n- Văn phòng đẹp nhất, sáng tạo và thân thiện với môi trường do chính những thế hệ trẻ của Apec kiến tạo nên.\n- Hoạt động nội bộ (du lịch, team building,...).\n- Thưởng lễ tết, thưởng quý, thưởng cuối năm, lương tháng thứ 13+++\n\nCó cơ hội được tham gia một số dự án đã và đang phát triển của p.CNTT:\n- Hệ thống giao dịch thị trường chứng khoán trái phiếu, website bảng giá, Mobile App giao dịch cho nhà đầu tư.\n- Vận hành, phát triển các website công ty, các dự án.\n- Hệ thống ERP cho tập đoàn (Quản trị nhân sự, tuyển dụng, tính lương, giao việc, dự án).\n- Các ứng dụng quản trị, giao dịch khác trong tập đoàn: Bất động sản, nội thất, trái phiếu...\n- Đang phát triển hệ thống quản lý chuỗi khách sạn SmartHotel tích hợp eKYC, Payment, hệ thống quản lý kho phòng: Channel Manager, CRM, Loyalty, Booking.\n- Vận hành, phát triển hệ thống tài chính độc nhất tại Việt Nam và hệ thống giao dịch chứng khoán hiện đại bậc nhất Việt Nam.\n- Và nhiều dự án khác.\n\nĐịa điểm làm việc\n- Hà Nội: 117 Trần Duy Hưng, Trung Hòa, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:50).\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:20).\n- 2 ca làm việc được lựa chọn.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2500, 1345, 2, 'Senior Android Kotlin (English)', 'REMOTE JOB- WFH\n\n- Work closely with Product Managers, technical stakeholders, to craft, design and propose mobile solutions, and agile delivery plans.\n- Lead and manage the mobile application team in delivering the product features according to plan, using agile delivery methodology\n- Develop Android applications. Design, develop and optimize the performance of Mobile Apps products.\n- Participate in all stages of the software development process, including: requirements analysis, design, research new technologies...\n- Participate in contributing ideas with leaders and customers to improve products or work processes.\n- Solve issues, perform tasks according to plan, report work progress to the Line Manager Job.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 3 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2501, 186, 2, 'Technical Artist (Generalist)', '• Lập kế hoạch dự án và thời gian thực hiện nhằm đáp ứng các mục tiêu của khách hàng/người dùng.\n• Lập kế hoạch dự án và thời gian thực hiện phù hợp với các mục tiêu của bộ phận CNTT, đặc biệt về bảo mật và tuân thủ quy định.\n• Phối hợp với nhóm quản trị mạng và máy chủ để điều chỉnh các thay đổi, đánh giá tác động và xây dựng kế hoạch dự phòng cho từng dự án hoặc thay đổi trong tổ chức trên toàn cầu.\n• Nắm rõ các tiêu chuẩn CNTT toàn cầu để đảm bảo các kế hoạch và mục tiêu được thảo luận đầy đủ trong nội bộ nhóm CNTT, từ đó đảm bảo tính tuân thủ và tránh lạc hậu.\n• Tổ chức các cuộc họp nội bộ định kỳ trong phạm vi toàn cầu với đội ngũ CNTT để đảm bảo sự phối hợp hiệu quả giữa các khu vực và làm việc từ xa thuận lợi.\n• Quản lý kế hoạch dự án và cung cấp các cập nhật thường xuyên bao gồm tiến độ dự án, hiệu suất tài chính và quản lý nguồn lực.\n• Đảm bảo tuân thủ quy trình vận hành chuẩn (SOP) trong suốt quá trình thực hiện dự án.\n• Hỗ trợ các trưởng bộ phận hoặc nhóm trưởng CNTT nhằm đảm bảo không có rủi ro hay sự cố ảnh hưởng đến dự án và đạt được các mục tiêu đã đề ra.\n\nYêu cầu ứng viên:\n• Bắt buộc có khả năng lập trình Shader cho Unity (có thể dùng ShaderLab thay thế)\n• Bắt buộc có hiểu biết sâu rộng về toàn bộ các công cụ dùng trong quy trình phát triển game\n• Có khả năng thiết lập ánh sáng (light rigging)\n• Bắt buộc có kỹ năng quản lý chất lượng và tối ưu hóa tài nguyên (asset)\n• Có thể thiết kế toàn bộ pipeline xử lý asset\n• Kinh nghiệm: Tối thiểu 10 năm (có thể cân nhắc từ 8 năm trở lên)\n• Yêu cầu: Có portfolio (hồ sơ năng lực)\n• Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi:\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận. Mức lương cao, có thể thoả thuận theo năng lực của ứng viên.\n• 1 năm tăng lương/lần.\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty.\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước).\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm, Tiêm phòng HPV, cúm,....', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2502, 71, 2, 'Junior IOS Developer (Upto 1000$)', 'Mô tả công việc: Tham gia phát triển các ứng dụng liên quan đến tài chính trên iOS. Tham gia cài đặt, viết unit test, review mã nguồn của các thành viên trong team. Nghiên cứu và ứng dụng các công nghệ mới vào phát triển sản phẩm. Hỗ trợ deploy trên môi trường Development, Stagging, Production. Làm việc với các đối tác tại nhiều quốc gia trên thế giới như Singapore, Nhật Bản, Hongkong... để trao đổi về dự án. Báo cáo kết quả công việc cho PM.\n\nVề dự án POEMS: Tiếp nối lịch sử 30 năm thành công của Poems, siêu ứng dụng lớn nhất về tài chính ở Singapore - Poems 3.0 là trải nghiệm giao dịch tiên tiến, thích ứng mọi lúc mọi nơi với tham vọng trở thành app tài chính hàng đầu thế giới, tập trung vào nhiều loại giao dịch bao gồm: Stocks/Equities/Shares, ETF, CFD, Future/Forex, kết nối với 26 sàn giao dịch lớn nhất trên thế giới và thậm chí bao gồm cả mạng xã hội cho các traders.\nDự án có sự tham gia của khoảng 100 kỹ sư công nghệ trên thế giới đến từ Singapore, Hong Kong, Ấn Độ, Nhật Bản, Việt Nam với 3 giai đoạn trong năm nay và dự kiến sẽ phát triển thêm các giai đoạn với các chức năng và cải tiến mới vào năm tới để mang đến trải nghiệm ứng dụng tốt nhất.\n\nYêu cầu ứng viên: MUST HAVE: Tốt nghiệp Đại học/Cao đẳng chuyên ngành liên quan. Có từ 1 năm kinh nghiệm phát triển app iOS (Swift/SwiftUI). Có hiểu biết về mô hình kiến trúc lập trình MVP/MVVM. Có kinh nghiệm làm việc với RXSwift, SnapKit là lợi thế. Có tư duy logic, sử dụng thuật toán tốt. Tiếng Anh giao tiếp là một lợi thế. Có khả năng học hỏi công nghệ mới. Có kinh nghiệm làm việc với các hệ thống tài chính là một điểm cộng. Có kinh nghiệm về UI/UX là một điểm cộng.\nNICE TO HAVE: Thích làm việc với các hệ thống lớn trong mảng tài chính. Có kinh nghiệm điều phối team là một lợi thế.\n\nQuyền lợi: INCOME: Mức lương đàm phán theo năng lực ứng viên, cạnh tranh với thị trường, upto 1000$. Đánh giá kết quả công việc hằng năm. Nhiều cơ hội tăng thu nhập từ 50-80%/năm. Thưởng lương tháng 13: 1 tháng lương. Thưởng dự án theo quý. Thưởng hiệu quả kinh doanh: Theo kết quả hoạt động kinh doanh hằng năm của công ty. Được cấp thẻ bảo hiểm sức khỏe được thiết kế riêng cho TDTers. Với các nhân sự ở level Manager trở lên, có package benefit riêng.\nCAREER PATH IMPROVEMENT: Khi trở thành 1 TDTer, bạn sẽ có cơ hội phát triển bản thân với tốc độ gấp 2-3 lần thị trường, với nhiều cơ hội và thách thức như: Được tham gia full-cycle vào quy trình phát triển các sản phẩm Tài chính phức tạp, kết hợp nhiều nghiệp vụ khó. Làm việc với những dự án chuyên sâu trong lĩnh vực công nghệ tài chính liên quan Quantitative Trading, HFT, ultra very low latency. Được thử sức với nhiều ngôn ngữ lập trình, nhiều framework khác nhau. Được làm việc trong môi trường quốc tế: Sử dụng tiếng Anh hàng ngày, trao đổi với team CNTT của nhiều nước khác nhau, onsite dài ngày/ngắn ngày tại nước ngoài... Được tham gia vào các chương trình đào tạo dài hạn dành cho Core-team theo định hướng phát triển của từng vị trí và từng người. Được thử thách với các vị trí Senior/Teamlead/Project Manager.\n\nCOMPANY ACTIVITIES: Văn phòng thiết kế theo phong cách Co-working, có nhiều tiện ích giải trí như: Máy pha cafe, máy chạy bộ, bàn bóng bàn...; khu ăn uống với đồ ăn, đồ uống miễn phí; phòng tắm nóng lạnh, máy giặt.. Được trang bị các thiết bị hiện đại như Laptop cấu hình cao, Macbook... Được tham gia các câu lạc bộ theo sở thích như: CLB bóng đá, CLB chạy, CLB trading chứng khoán/ forex/crypto vui vẻ, các giải game... Được đài thọ 100% chi phí tham gia các chuyến du lịch cùng công ty: Summer Holiday, Year End Party. Được tặng quà, tham gia các sự kiện trong các dịp 1/6, Trung Thu, 8/3, 20/10...\n\nĐịa điểm làm việc: - Hà Nội: Tầng 5, Tòa nhà PVI số 1 Phạm Văn Bạch, P. Yên Hòa, Cầu Giấy\nThời gian làm việc: 08h30 – 17h30, Thứ 2 – Thứ 6. Nghỉ Thứ 7, CN và các ngày lễ theo quy định.\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2503, 1346, 2, 'Embedded Software/Android Driver Developer', 'We are looking for a skilled and proactive Embedded Software Engineer or Android Driver Developer to join our team. The ideal candidate will have hands-on experience in embedded systems or Android driver development, with solid knowledge of Linux systems and scripting. You will work closely with R&D teams to support product testing, debugging, and production processes.\n- Working Location: Thai Nguyen factory\n- Qty: 5 (including one Team Lead)\n\n- Develop and maintain embedded software or Android device drivers.\n- Analyze and debug system issues using various Android and Linux logs (e.g., logcat, kernel logs, UART).\n- Write and execute automation scripts using Shell, Python, or batch scripting.\n- Support production line testing and initial fault analysis.\n- Collaborate with R&D teams to assist in debugging, stress testing, and performance verification.\n- Contribute to continuous improvements in development and testing workflows.\n\n- Experience in embedded software development or Android driver development.\n- Familiarity with Linux systems and common Linux commands.\n- Experience with automation scripting using Shell, Python, or Batch scripts.\n- Proficiency in capturing and analyzing Android system logs (logcat, kernel logs, UART, etc.).\n- Understanding of production line testing processes and ability to perform basic issue analysis.\n- Ability to communicate in either Mandarin Chinese or English for daily work.\n\n- Thái Nguyên: KCN Yên Bình, phường Hồng Tiến, TP. Phổ Yên, TP Thái Nguyên\n\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2504, 1347, 2, 'Unity Developer', 'Mô tả công việc\n- Implement and improve a variety of fast and efficient core software using Unity.\n- Maintain and build code using C# for all assigned work streams.\n- Provide architectural oversight across the entire application.\n- Collaborate to devise optimal engineering solutions to technical challenges.\n\nYêu cầu ứng viên\n- At least 2 years of experience in Unity.\n- Proficient with the .NET framework and its memory management.\n- Experience in performance optimization.\n- Passion for video games!\n\nDesirable Pluses\n- Experience with multiplayer gameplay systems, network replication, core engine, or tool development.\n- Experience with iOS/Android/PC platforms is a plus.\n- Knowledge of native languages (Objective-C, Swift for iOS, Java, Kotlin for Android, JavaScript for WebGL) is a plus.\n- Have a product published on Play Store or App Store.\n\nQuyền lợi\n- Annual performance bonus\n- Annual salary review\n- 16 annual leave days\n- Health care insurance & Health check\n- Birthday gift, Tet\'s gift\n- Company trip\n- Lunch allowance\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 384/9-9A Nam Ky Khoi Nghia Street, Vo Thi Sau Ward,, Quận 3\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 3', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2505, 1144, 2, 'Senior Back-End Developer', 'Mô tả công việc\n- Phân tích, thiết kế và phát triển hệ thống backend sử dụng Python, FastAPI, theo kiến trúc Clean Architecture.\n- Thiết kế và triển khai hệ thống ETL, batch sử dụng Databricks Job.\n- Xây dựng và tối ưu các API chuẩn REST, sử dụng SQLAlchemy/Pydantic/Alembic để quản lý schema và model.\n- Quản lý tiến độ, phân công task, hỗ trợ kỹ thuật cho team backend.\n- Triển khai các API xác thực bằng API Key rotation, quản lý quyền truy cập.\n- Tích hợp ElasticSearch làm công cụ tìm kiếm.\n- Hướng dẫn và đào tạo thành viên team backend (code convention, kiến trúc, review code).\n- Thiết lập và vận hành môi trường CI/CD.\n- Phân tích hành vi người dùng và log truy cập sử dụng BigQuery, Looker Studio, Google Analytics.\n- Tối ưu performance backend, xử lý rollback, blue-green/canary deployment khi release ứng dụng.\n- Phối hợp chặt chẽ với các bên liên quan: frontend, data engineer, infra, QA để đảm bảo luồng phát triển liền mạch.\n\nYêu cầu ứng viên\nKỹ năng chuyên môn\n- 5+ năm kinh nghiệm lập trình với Python, thành thạo FastAPI,\n- Có kinh nghiệm xây dựng hệ thống với hiệu năng cao, hiểu rõ kiến trúc microservices.\n- Có kinh nghiệm tích hợp và tối ưu hóa Elasticsearch cho hệ thống tìm kiếm và phân tích dữ liệu.\n- Thành thạo thiết kế kiến trúc và tối ưu cơ sở dữ liệu phục vụ hiệu suất và khả năng mở rộng.\n- Hiểu biết rõ và cách áp dụng design patterns.\n- Có kinh nghiệm triển khai, giám sát và vận hành hệ thống trên các cloud như GCP / Azure / AWS.\n- Nắm vững các nguyên tắc Bảo mật & An toàn hệ thống, đảm bảo an toàn dữ liệu và phòng chống tấn công phổ biến (OWASP, v.v.).\n- Tối ưu hiệu suất hệ thống: caching, queue, async processing.\n- Có kinh nghiệm xây dựng và duy trì quy trình CI/CD, triển khai chuẩn hóa và tự động hóa môi trường DevOps.\n\nKỹ năng quản lý\n- Có 3+ năm kinh nghiệm vai trò leader dẫn dắt nhóm kỹ thuật.\n- Có khả năng review code, hướng dẫn kỹ thuật, kiểm soát chất lượng thông qua quy trình Agile/Scrum.\n- Khả năng định hướng kiến trúc hệ thống, phân chia công việc hợp lý và tối ưu năng lực thành viên trong nhóm.\n- Kỹ năng giao tiếp tốt, có khả năng truyền đạt ý tưởng rõ ràng và thuyết phục.\n- Có kinh nghiệm phối hợp hiệu quả giữa các nhóm chức năng (FE, QA, DevOps...).\n\nQuyền lợi\n– Thu nhập upto 45M. \n– Thử việc 2 tháng hưởng 100% lương\n– Tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật lao động\n– Tham gia bảo hiểm VBI\n– Review lương 2 lần/năm\n– Lương tháng 13, thưởng lễ, Tết, Tang lễ, Sinh nhật,...\n– Hỗ trợ chi phí thi chứng chỉ theo quy định của công ty\n– Phụ cấp khi nhận chứng chỉ\n– Phụ cấp gửi xe\n– Phụ cấp thâm niên, thưởng dự án xuất sắc\n– Du lịch hằng năm theo chính sách của công ty\n– Khám sức khỏe định kỳ hằng năm\n– Cơ hội thăng tiến rõ ràng\n– Cơ hội làm việc tại các nước đối tác: Nhật Bản, Hàn Quốc, Singapore, Úc\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 10F Mekong Tower, 235 Cong Hoa, Ward 13, Tân Bình\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2506, 1348, 2, 'Lập Trình Viên Developer [Junior Level]', 'Mô tả công việc:\nMột số nội dung công việc chính:\n- Trực tiếp phát triển phần mềm iDentalsoft theo team Dev hiện tại,\n- Phụ trách Coding, R&D, cải tiến Features có sẵn,...\n- Nghiên cứu viết tool và migrate database cho khách hàng mới,\n- Nghiên cứu & phát triển tính năng mới cho phần mềm iDentalsoft\n- Cải tiến & nâng cao hiệu quả phần mềm iDS\n- Nghiên cứu & cải tiến công nghệ để phát triển sản phẩm trên nền tảng Web Cloud, Window và cả Mobile\n- Nghiên cứu phát triển thêm nhiều tính năng khác cho phần mềm iDS\n\nVề iDentalsoft:\niDentalsoft là đơn vị tiên phong phát triển phần mềm iDentalsoft được sử dụng rộng rãi trong ngành công nghệ Nha khoa tại Hoa Kỳ. iDentalsoft là phần mềm Cloud Base, giúp bác sĩ dễ dàng quản lý và vận hành văn phòng nha khoa của mình một cách chuyên nghiệp, đơn giản, nhanh chóng và thuận tiện. Đó là lý do iDentalsoft được giới bác sĩ nha khoa Hòa Kỳ và nhiều nước khác; như Châu Âu, Châu Phi, Hàn Quốc, Việt Nam; tuyệt đối tin tưởng & sử dụng.\niDentalsoft tọa lạc tại Milpitas, bang California, Hoa Kỳ và chúng tôi có công ty thành viên đặt tại Thành phố Hồ Chí Minh, Việt Nam. Tham gia vào iDentalsoft, bạn có cơ hội học hỏi, trải nghiệm và thỏa sức sáng tạo trên con đường phát triển nghề nghiệp của bạn.\n\nYêu cầu ứng viên:\nKỹ thuật:\n- Có kiến thức về Java, C# (Chính)\n- Có kiến thức về OOB, MySQL\n- Có kỹ năng research\n- Có kỹ năng phân tích, ham học hỏi, làm việc độc lập\n- Có kỷ luật, có khả năng đảm bảo deadline\n\nCơ bản:\n- Tốt nghiệp đại học, cao đẳng chuyên ngành Software, IT, Engineer\n- Chấp nhận người mới ra trường. Có kinh nghiệm 1-2 năm càng tốt\n- Chấp nhận bằng cấp tất cả các trường ĐH, CĐ\n\nQuyền lợi:\n- Được hưởng Lương xứng đáng với năng lực\n- Lương rất cạnh tranh\n- Chế độ nâng lương hàng năm và nâng lương đột xuất (đối với cá nhân xuất sắc)\n- Có lương tháng 13 hàng năm\n- Có chế độ thưởng đột xuất\n- Được hưởng Bảo hiểm y tế và bảo hiểm xã hội theo quy định\n- Được đi du lịch hàng năm\n- Công ty có tổ chức Team Building thường xuyên\n- Môi trường làm việc tự do, năng động, theo hiệu quả công việc\n- Có cơ hội học hỏi và phát triển bản thân\n- Đồng nghiệp vui tính, hỗ trợ lẫn nhau\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lầu 6, 15/28 Đoàn Như Hài, Phường 13, Quận 4\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 19:00 đến 06:00)\nLàm Ca đêm full time, Mỗi ca 8 tiếng; Ca 1 từ 7pm đến 3am, Ca 2 từ 10pm đến 6am\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2507, 1250, 2, 'Junior Mid Fullstack Developer (ReactJS + NodeJS)', 'OUR TECH STACK:\nBackend:\nNode.js / ExpressJs\nRabbitMQ / Kafka / MSSQL\nDocker / Kubernetes / Jenkins\nFrontend:\nReactJS/ NextJs\nES6 / Webpack\nRedux / Redux-Saga / Reselect / Hooks\n\nRESPONSIBILITIES:\n- Design, code, and review scalable, maintainable software solutions that align with business and system architecture.\n- Identify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\n- Collaborate across squads (frontend, backend, QA…) to share knowledge, align on best practices, and mentor junior team members\n- Take ownership of features or systems; lead projects or squads when needed, ensuring delivery quality and guiding technical direction.\n\nYêu cầu ứng viên\nMust-Have:\n- Proactive problem-solver with a bias toward action and ownership.\n- Quick to pick up new frameworks, libraries, and tooling as the stack evolves..\n- At least 2 years of real-world experience in software development.\n- Familiarity with macOS or Linux for development and deployment tasks.\n- Hands-on experience or working knowledge in our core stack is required; full expertise in one side (FE or BE) is acceptable:\n	- Backend: Node.js, PostgreSQL, Redis, Elasticsearch.\n	- Frontend: React.js, Redux, Redux-Saga, Reselect, React Hooks.\n\nCommitment to code quality:\n- Strong experience in code reviews.\n- Familiarity with unit testing best practices.\n- Growth mindset: Ready to grow rapidly as the company scales several times a year.\n\nNice-to-Have (Plus):\n- Deep understanding of Webpack, including code splitting, asset optimization, and custom configurations.\n- Strong foundation in computer science: Data structures, algorithms, design patterns.\n- Experience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\n- Familiarity with microservices architecture.\n\nQuyền lợi\n- Competitive Compensation & Bonuses\n	- Attractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n	- 100% salary during the probation period.\n	- 13th-month salary to ensure financial stability.\n	- Performance reviews twice a year with opportunities for salary adjustments.\n- Flexible Work & Growth Opportunities\n	- Hybrid working model: Work from home or at the office as needed.\n	- Work alongside top CTOs, architects, and tech leaders at Vexere.\n	- Build your public profile through:\n		- Publishing articles on Medium & Vexere Techblog under your name.\n		- Contributing to Open Source projects managed by Vexere.\n		- Speaking at tech talks and industry events.\n	- Attractive stock options for dedicated developers and team leads.\n- Exclusive Employee Perks\n	- Up to 30% discount on bus tickets for Vexere employees and their families.\n	- 12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\n	- Vibrant and dynamic work environment with a friendly, supportive team.\n	- Training sessions on negotiation, communication, work management, interpersonal skills, and software technology.\n	- Exciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 384 Hoang Dieu, Ward 6, Quận 4\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2- Thứ 6, Sáng thứ 7\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2508, 1349, 2, 'Kỹ Sư Lập Trình Nhúng - Điện Tử Công Suất', 'Mô tả công việc\n- Phát triển firmware cho các dòng sản phẩm gia dụng như: Bếp từ, điều hòa, bình nóng lạnh, máy lọc nước, …\n- Tham gia vào phân tích yêu cầu, thiết kế kiến trúc hệ thống, thiết kế phần mềm nhúng;\n- Thu thập và xử lí các yêu cầu thiết kế và kĩ thuật;\n- Nghiên cứu và áp dụng các công nghệ mới để tối ưu hóa hiệu quả phát triển sản phẩm\n\nYêu cầu ứng viên\n- Tốt nghiệp cao đẳng, đại học chuyên ngành Kỹ thuật điện tử, Tự động hóa, Cơ điện tử hoặc liên quan\n- Có kinh nghiệm từ 3 năm trong vị trí lập trình nhúng liên quan đến:\n  + Điều khiển động cơ, đo và điều khiển nhiệt độ sử dụng thuật toán PID\n  + Nắm chắc việc sử dụng các ngoại vi phần cứng như: SPI, I2C, USART, TIMER, PWM, ADC, INTERRUPT, …\n  + Nắm chắc việc sử dụng các nền tảng phần nhúng như: RTOS, MODBUS RTU, CRC, …\n  + Đã từng làm một hoặc nhiều các dự án chế tạo máy, thiết bị điều khiển công nghiệp, ROBOT, AGV, DATALOGGER; các dự án chế tạo sản phẩm, thiết bị điện gia dụng như bếp từ, điều hòa, …\n  + Đã có sản phẩm ra thị trường là lợi thế\n- Kỹ năng đọc hiểu tài liệu tiếng Anh tốt trong lĩnh vực chuyên môn\n- Có kỹ năng đọc hiểu tài liệu thiết kế nguyên lý phần cứng\n- Thành thạo nền tảng GIT trong quản lý phiên bản phần mềm là một lợi thế.\n- Thành thạo các công cụ soạn thảo văn bản, bảng tính, báo cáo, …\n- Có khả năng giao tiếp, hòa đồng và làm việc nhóm tốt\n- Có tinh thần làm việc tận tâm, quyết liệt và trách nhiệm.\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực. Đánh giá tăng lương 2 lần/năm\n- Thử việc hưởng 100% lương \n- Thời gian làm việc linh hoạt từ T2-T6 \n- Môi trường làm việc trẻ trung, năng động\n- Thưởng ngày Lễ/Tết, thưởng KPI, thưởng dự án theo tháng \n- Có cơ hội được đào tạo phát triển và thăng tiến.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Thanh Trì', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2509, 1182, 2, 'Frontend Developer', '● Chịu trách nhiệm phát triển các sản phẩm Web sử dụng ngôn ngữ/công nghệ: React/JavaScript, WebSocket,...\n● Chuyển đổi thiết kế thành các các giao diện UI/UX thân thiện với người dùng.\n● Onsite theo yêu cầu công việc.\n\nYêu cầu ứng viên\n● Ít nhất 1 năm kinh nghiệm làm việc với ReactJS trong môi trường phát triển web.\n● Thành thạo JavaScript, jQuery, Bootstrap, CSS, HTML5\n● Có kinh nghiệm phát triển và tích hợp RESTful API, WebSocket, ...\n● Có kinh nghiệm làm việc với các công cụ: Git, Jira\n● Năng động, sáng tạo, có khả năng tự nghiên cứu\n\nQuyền lợi\n● Lương tháng 13 \n● Nghỉ phép, nghỉ lễ, Bảo hiểm xã hội, bảo hiểm y tế theo luật lao động\n● Thời gian làm việc: Thứ 2-Thứ 6, từ 8h30-18h00\n- Hà Nội: 15 Hồ Xuân Hương, Hai Bà Trưng\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2510, 1350, 2, 'Senior Backend Developer', 'Mô tả công việc\n1. Backend Development & Microservices\n- Design, develop, and optimize high-performance REST/GraphQL APIs and microservices.\n- Build backend services using NodeJS (MERN Stack) and Golang (Nice to have).\n- Enhance system performance and scalability.\n\n2. Technology & Architecture\n- Work with distributed systems and microservices architecture.\n- Deploy applications on cloud platforms.\n- Integrate AI/ML solutions into the system.\n- Proficient in containerization using Docker and Kubernetes.\n\n3. DevOps & CI/CD\n- Develop and maintain CI/CD pipelines using GitLab.\n- Apply best practices in DevOps.\n- Monitor and optimize the development workflow.\n\nYêu cầu ứng viên\n1. Technical Experience\n- At least 5+ years of experience in backend development with NodeJS (MERN Stack) and Golang.\n- Strong experience in designing RESTful APIs and microservices.\n- Proficiency in working with PostgreSQL, MongoDB, and Redis.\n- Experience in database design for large-scale systems.\n\n2. Technical Skills\n- In-depth understanding of distributed systems and microservices architecture.\n- Proficiency in Docker, Kubernetes, and cloud platforms (AWS, GCP).\n- Strong knowledge of data structures and algorithms.\n- Proficient in Git and source code management tools.\n- Ability to apply AI in enhancing development speed and quality.\n\n3. Soft Skills\n- Strong analytical and problem-solving skills.\n- Effective teamwork and collaboration.\n- Proactive in learning new technologies.\n- High sense of responsibility and passion for software development.\n\nQuyền lợi\n- Competitive salary commensurate with experience.\n- Flexible working hours to support work-life balance and productivity.\n- Opportunity to work in a dynamic startup environment with a passionate and talented team.\n- Chance to make a significant impact on the growth and success of innovative products in the D2C industry.\n- Collaborative culture that values creativity, diversity, and continuous learning.\n- Career growth and skill development opportunities.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 24 Huỳnh Khương Ninh, Đa Kao, Quận 1\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2511, 1200, 2, 'Middle Frontend', '- Thiết kế và phát triển các mô-đun và thành phần frontend có thể tái sử dụng, tạo thành nền tảng cho các ứng dụng của chúng tôi.\n- Lập kiến trúc và triển khai các giải pháp frontend có thể mở rộng bằng cách sử dụng các framework JavaScript hiện đại.\n- Đưa ra các quyết định kỹ thuật cho kiến trúc frontend và thiết lập các tiêu chuẩn mã hóa.\n- Tạo mã code hiệu quả, dễ bảo trì và tối ưu hiệu suất.\n- Xây dựng và duy trì các thư viện thành phần UI cốt lõi để sử dụng trên toàn công ty.\n- Dẫn dắt việc triển khai các tính năng frontend phức tạp và đảm bảo chất lượng mã.\n- Làm việc chặt chẽ với đội ngũ thiết kế và backend của chúng tôi để tạo ra giao diện người dùng liền mạch.\n- Học hỏi và áp dụng các tiêu chuẩn phát triển và thực tiễn tốt nhất của Nhật Bản thông qua sự hướng dẫn trực tiếp.\n- Tham gia trong quy trình phát triển linh hoạt của chúng tôi từ lập kế hoạch kiến trúc đến kiểm tra.\n\n• Ít nhất 3 năm kinh nghiệm phát triển front-end chuyên nghiệp\n• Kinh nghiệm sâu rộng với Next.js và TypeScript\n• Thành thạo Tailwind CSS và có kinh nghiệm xây dựng UI component tùy chỉnh\n• Có kinh nghiệm triển khai giải pháp xác thực người dùng, ưu tiên Auth.js\n• Hiểu biết về quy trình CI/CD và kinh nghiệm làm việc với Azure DevOps.\n\nMức lương 18.000.000 - 32.000.000\nThời gian làm việc: 8h00-17h30, nghỉ trưa 1,5h (12h – 13h30) từ thứ 2 - thứ 6\n13 tháng lương + thưởng lễ tết; xét tăng lương hàng năm\nDu lịch hàng năm, team building hàng tháng/quý\nBảo hiểm xã hội, BHYT theo quy định của Nhà nước\nGói bảo hiểm sức khỏe\nKhám sức khoẻ định kỳ hàng năm\nMôi trường flat trẻ trung, thoải mái\nCơ hội tham gia dự án tiềm năng, thử thách nhưng không kém phần thú vị.\n\n- Hà Nội: Hoàng Mai\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2512, 1123, 2, 'Fullstack Developer (NodeJS/Python + ReactJS)', 'Mô tả công việc:\nCollaborate with cross-functional teams to design and implement technical solutions\nParticipate in architecture discussions, code reviews, and system design\nEnsure high performance, scalability, and security of applications\nWork directly with clients and project managers in English to clarify requirements and provide updates\nTroubleshoot and debug issues across the full stack\nMentor junior engineers and contribute to team best practices\n\nYêu cầu ứng viên:\nAt least 3 years of experience in fullstack development\nProficient in ReactJS and one of the following backend stacks:\n- NodeJS (Express/NestJS)\n- Python (Django/FastAPI/Flask)\nSolid understanding of RESTful APIs, modern JavaScript, and database systems (SQL/NoSQL)\nFamiliar with Git, CI/CD, Docker, and cloud services (AWS/GCP/Azure)\nGood command of spoken and written English (comfortable joining calls and writing technical documents)\nExperience working in Agile/Scrum teams\n\nQuyền lợi:\nJoin a global team and work directly with many talents around the world.\nWorking & growing with a passionate, young, and talented team.\nPremium Health Insurance TECHVIFY Care.\nSalary: Up to 40.000.000 VND (Gross)\n13 months’ salary per year.\nEvaluate salary annually.\nSponsor and encourage staff to study courses by covering tuition fee, such as Udemy, Coursera.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Thành Đông, ngõ 19 Tố Hữu, Nam Từ Liêm\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2513, 1351, 2, 'Fullstack Developer (Senior)', 'Mô tả công việc:\n- Thiết kế và tư vấn giải pháp kỹ thuật: Phối hợp với team Data để đưa ra kiến trúc công nghệ phù hợp cho các sản phẩm dữ liệu, API, dashboard và các ứng dụng phục vụ khách hàng.\n- Phát triển hệ thống backend & frontend hiện đại: Xây dựng API linh hoạt, bảo mật, hiệu suất cao với Node.js (Express/NestJS), hướng đến kiến trúc mở rộng và dễ tích hợp dữ liệu lớn. Phát triển frontend bằng Next.js (React) với giao diện tối ưu SEO, tốc độ cao, thân thiện người dùng và đa nền tảng.\n- Giám sát và tối ưu vận hành hệ thống: Đảm bảo hệ thống hoạt động ổn định, khả năng xử lý dữ liệu lớn, hiệu suất cao và sẵn sàng mở rộng theo nhu cầu thực tế.\n- Dẫn dắt và phát triển đội kỹ thuật: Phân công công việc, mentoring, đảm bảo chất lượng kỹ thuật, gắn kết team, xây dựng văn hóa học tập và đổi mới trong nhóm.\n- Chủ động tham gia phát triển và mở rộng sản phẩm dữ liệu và định hình công nghệ: thiết kế kiến trúc và chiến lược công nghệ cho nền tảng dữ liệu mở rộng, bao gồm tích hợp dữ liệu đa nguồn, phát triển hệ thống phân tích tự phục vụ, API thương mại hóa và báo cáo thông minh.\n\nYêu cầu ứng viên:\nYêu cầu bắt buộc:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan.\n- Tối thiểu 4 năm kinh nghiệm phát triển hệ thống web với JavaScript, thành thạo cả Node.js (Express hoặc NestJS) và Next.js (React).\n- Có kinh nghiệm xây dựng kiến trúc hệ thống fullstack JavaScript, tích hợp frontend/backend qua REST API hoặc GraphQL.\n- Thành thạo kiến thức về SSR/SSG, bảo mật ứng dụng web, tối ưu hiệu suất frontend/backend và xử lý dữ liệu lớn.\n- Ưu tiên ứng viên đã làm việc với PostgreSQL, MongoDB, Redis, RabbitMQ, Docker, hoặc các nền tảng cloud như AWS, GCP, Vercel.\n- Có kinh nghiệm thiết lập hoặc cải tiến quy trình CI/CD, tự động hóa kiểm thử, đảm bảo chất lượng mã nguồn.\n\nKỹ năng lãnh đạo và tư duy sản phẩm:\n- Từng quản lý nhóm kỹ thuật; biết cách thúc đẩy tinh thần đội nhóm, hỗ trợ kỹ thuật và truyền cảm hứng đổi mới.\n- Tư duy hệ thống, logic tốt, có khả năng chuyển hóa yêu cầu kinh doanh thành giải pháp kỹ thuật thực tế và hiệu quả.\n- Giao tiếp tốt, biết cách phối hợp liên phòng ban và giải thích giải pháp kỹ thuật cho team không chuyên.\n\nQuyền lợi:\n- Lộ trình phát triển rõ ràng: Cơ hội trở thành Tech Lead / Engineering Manager trong tương lai gần nếu thể hiện tốt.\n- Môi trường cởi mở, team trẻ trung, dễ triển khai ý tưởng mới, chủ động xây dựng quy trình phù hợp.\n- Mức lương cạnh tranh, thưởng theo dự án, đầy đủ chế độ bảo hiểm, nghỉ phép, lương tháng 13.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tòa nhà Jamona Heights, 210 Bùi Văn Ba, Quận 7\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Thứ 7 (từ 08:30 đến 12:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2514, 1119, 2, 'Senior BackEnd (Spring Boot)', 'Mô tả công việc\n- Phát triển và duy trì các ứng dụng Java sử dụng Spring Boot:\n  - Thiết kế, phát triển và duy trì các hệ thống ứng dụng web và dịch vụ backend sử dụng Java và Spring Boot phục vụ cho các giao dịch chứng khoán, quản lý tài khoản và các công cụ hỗ trợ khác.\n  - Lập trình các chức năng liên quan đến giao dịch, xử lý dữ liệu tài chính, báo cáo và các dịch vụ khác trong môi trường chứng khoán.\n  - Đảm bảo các ứng dụng hoạt động ổn định, hiệu suất cao và bảo mật.\n- Tích hợp và phát triển API:\n  - Thiết kế và phát triển các API RESTful sử dụng Spring Boot để kết nối các hệ thống giao dịch, ứng dụng web và cơ sở dữ liệu.\n  - Tích hợp các hệ thống bên ngoài (ví dụ: API của các sàn chứng khoán, ngân hàng) vào hệ thống công ty, đảm bảo tính chính xác và bảo mật khi truyền nhận dữ liệu.\n- Quản lý cơ sở dữ liệu:\n  - Thiết kế và tối ưu hóa các câu lệnh SQL, thao tác với cơ sở dữ liệu quan hệ (MySQL, PostgreSQL, Oracle v.v.) hoặc NoSQL (MongoDB, Cassandra) để lưu trữ và truy xuất dữ liệu hiệu quả.\n  - Thực hiện các nghiệp vụ quản lý giao dịch chứng khoán và dữ liệu tài khoản, đảm bảo tính nhất quán và an toàn của dữ liệu.\n- Kiểm thử và đảm bảo chất lượng phần mềm:\n  - Thực hiện kiểm thử unit, tích hợp và đảm bảo chất lượng mã nguồn phần mềm.\n  - Phối hợp với nhóm kiểm thử để đảm bảo phần mềm được kiểm tra kỹ lưỡng trước khi triển khai.\n- Tối ưu hóa hiệu suất và bảo mật:\n  - Tối ưu hóa hiệu suất hệ thống để xử lý lượng giao dịch lớn trong môi trường chứng khoán.\n  - Áp dụng các biện pháp bảo mật, mã hóa và các kỹ thuật bảo vệ dữ liệu nhằm đảm bảo hệ thống và giao dịch an toàn.\n- Cập nhật và duy trì tài liệu kỹ thuật:\n  - Cập nhật và duy trì tài liệu kỹ thuật cho các ứng dụng và API phát triển.\n  - Đảm bảo các tài liệu dễ hiểu và có thể được sử dụng lại cho các dự án sau.\n- Tham gia vào quá trình phát triển phần mềm:\n  - Tham gia vào các cuộc họp Scrum, giúp giải quyết các vấn đề kỹ thuật và tham gia vào quá trình lên kế hoạch và thiết kế hệ thống.\n  - Cập nhật tiến độ công việc và báo cáo cho các bên liên quan theo yêu cầu.\n\nYêu cầu ứng viên\n- Trình độ học vấn: Tốt nghiệp Đại học trở lên, chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan.\n- Kinh nghiệm:\n  - Ít nhất 3 năm kinh nghiệm phát triển phần mềm với Java, đặc biệt là với Spring Boot.\n  - Kinh nghiệm làm việc với các ứng dụng web và dịch vụ backend trong môi trường chứng khoán, tài chính hoặc ngân hàng là một lợi thế.\n  - Kinh nghiệm với các công cụ quản lý mã nguồn (Git, GitHub, Bitbucket, v.v.).\n  - Kinh nghiệm làm việc với cơ sở dữ liệu SQL (MySQL, PostgreSQL) và NoSQL (MongoDB, Cassandra).\n  - Kinh nghiệm làm việc với các công cụ CI/CD (Jenkins, GitLab CI, v.v.) và containerization (Docker, Kubernetes) là một lợi thế.\n- Kiến thức:\n  - Kiến thức vững về Java, Spring Boot, Spring Security, Hibernate, và các công nghệ liên quan.\n  - Hiểu biết về các nguyên lý thiết kế phần mềm, RESTful API, microservices và các công cụ liên quan.\n  - Hiểu biết về quy trình phát triển phần mềm Agile và Scrum.\n  - Kiến thức về ngành chứng khoán và các quy trình giao dịch chứng khoán sẽ là lợi thế.\n- Kỹ năng:\n  - Kỹ năng lập trình Java xuất sắc và khả năng viết mã sạch, dễ bảo trì.\n  - Kỹ năng phân tích và giải quyết vấn đề tốt, có khả năng tối ưu hóa mã và hệ thống.\n  - Kỹ năng giao tiếp và làm việc nhóm hiệu quả.\n  - Kỹ năng tư duy logic, phân tích và thiết kế hệ thống.\n\nQuyền lợi\n1. Mức lương và phụ cấp:\n- Thỏa thuận theo năng lực và kinh nghiệm thực tế. Khung lương (25 - 35tr)\n- Phụ cấp ăn trưa (40k/ngày công thực tế)\n- Phụ cấp gửi xe (300k/tháng)\n- Phụ cấp đi lại, xăng xe, điện thoại (tùy thuộc vào từng vị trí)\n\n2. Thưởng:\n- Thưởng quý/năm (tùy theo tình hình kinh doanh của Công ty)\n- Thưởng lễ tết, cuối năm\n- Thưởng tháng lương 13 +++…\n\n3. Phúc lợi:\n- Tham gia BHXH, BHSK\n- Teambuildings, HappyFridays, du lịch nghỉ dưỡng\n\n4. Cơ hội thăng tiến:\n- Được làm việc đúng chuyên môn/sở trường (làm chủ công việc). Hợp tác với cộng sự/quản lý nhiều kinh nghiệm trong lĩnh vực\n- Được đào tạo trực tiếp nâng cao/bổ sung kiến thức ngành nghề\n- Đánh giá năng lực, xét tăng lương/thưởng theo quy định của Công ty\n\n5. Môi trường làm việc:\n- Năng động/ trẻ trung và nhiệt huyết\n- Định hướng làm việc hybrid\n- Được trang bị các trang thiết bị/công cụ phù hợp với từng vị trí công việc\n- Làm việc từ thứ 2 đến thứ 6 (nghỉ thứ 7 và chủ nhật)\n\nĐịa điểm làm việc\n- Hà Nội: 17 Tông Đản, Hoàn Kiếm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2515, 1352, 2, 'Full-Stack Developer (.Net, ReactJs)', 'VỀ AWING\nAWING dẫn đầu trong lĩnh vực tiếp thị di động, chuyên về quảng cáo qua Wi-Fi thông qua tư vấn chiến lược truyền thông thương hiệu cho doanh nghiệp, quảng cáo và triển khai hạ tầng Wi-Fi miễn phí tốc độ cao tại các địa điểm cao cấp trên toàn quốc. Để mở rộng phạm vi dịch vụ, AWING đã tích hợp phần mềm quản lý chiến dịch AWING Campaign Management (ACM) tự phát triển với các triển khai Wi-Fi miễn phí khác, tạo ra một mạng lưới quảng cáo rộng lớn phục vụ khách hàng trung và cao cấp. Ngoài việc cung cấp Wi-Fi miễn phí tốc độ cao, AWING còn mang đến những tiện ích giúp người dùng có trải nghiệm thân thiện nhất với các hệ thống bản đồ số phát triển trong các trung tâm mua sắm. Chất lượng và tiện ích thực tiễn của hệ thống AWING giúp quá trình quảng cáo và truyền tải thông điệp thương hiệu đến người tiêu dùng trở nên dễ dàng và hiệu quả hơn.\nTrong năm 2024, AWING nhận được khoản đầu tư lớn từ NTT e-Asia (Công ty trực thuộc Tập đoàn viễn thông NTT), chính thức trở thành đối tác kinh doanh chiến lược, hỗ trợ AWING mở rộng sang thị trường trong khu vực ASEAN. Với sự hợp tác này, AWING sẽ được tiếp cận với hỗ trợ công nghệ và các sáng kiến phát triển thị trường từ NTT e-Asia, đảm bảo rằng AWING có đầy đủ nguồn lực và chuyên môn cần thiết để phát triển mạnh mẽ trong thị trường ASEAN đầy cạnh tranh.\nBẠN HÃY VỀ VỚI AWING\nVới chiến lược mở rộng kinh doanh sang các nước trong khu vực, AWING đang có những bước tiến lớn trong việc mở rộng nhân sự cũng như thị trường sang các nước ASEAN. Đây là cơ hội tuyệt vời để bạn gia nhập công ty và trở thành một phần của giai đoạn phát triển thú vị này. Khi gia nhập bạn sẽ có cơ hội học hỏi và phát triển nhanh chóng, tận dụng nhiều cơ hội thăng tiến trong sự nghiệp lên các vị trí quản lý cấp cao. AWING hiện có phúc lợi cạnh tranh, môi trường làm việc năng động và cam kết phát triển chuyên môn, những điều này giúp cho công ty trở thành nơi lý tưởng để bạn xây dựng sự nghiệp vững chắc.\nCHI TIẾT CÔNG VIỆC\n- Tham gia vào quy trình phân tích, thiết kế và phát triển các sản phẩm phần mềm của công ty.\n- Phối hợp chặt chẽ với đội ngũ backend & frontend để tích hợp giao diện người dùng với các API.\n- Tối ưu hóa hiệu suất hệ thống nhằm đảm bảo tốc độ truy cập cao và tiết kiệm tài nguyên.\n- Nghiên cứu và áp dụng các công nghệ mới nhằm cải tiến và nâng cao chất lượng sản phẩm.\n- Xây dựng và duy trì cơ sở dữ liệu, đảm bảo tính bảo mật và hiệu suất.\n- Viết và duy trì tài liệu kỹ thuật và tài liệu hướng dẫn sử dụng.\n- Thực hiện kiểm thử và gỡ lỗi (debug) để đảm bảo sản phẩm hoạt động ổn định và không có lỗi.\n- Hỗ trợ và giải quyết các vấn đề kỹ thuật phát sinh trong quá trình vận hành sản phẩm.\n- Đóng góp ý tưởng và giải pháp để cải tiến quy trình phát triển và tối ưu hóa hệ thống.\nYêu cầu ứng viên\n- Tốt nghiệp đại học hoặc cao đẳng chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Có ít nhất 3 năm kinh nghiệm làm việc với Backend (sử dụng .NET Core, C#).\n- Có ít nhất 1 năm kinh nghiệm làm việc với Frontend (sử dụng ReactJS, TypeScript).\n- Kiến thức vững chắc về SQL và hệ quản trị cơ sở dữ liệu quan hệ (RDBMS) như MySQL.\n- Kinh nghiệm làm việc với Apache Kafka hoặc bất kỳ giải pháp Message Queue nào.\n- Có kinh nghiệm trong thiết kế và phát triển các ứng dụng có độ sẵn sàng cao, khả năng mở rộng, hiệu suất cao và độ trễ thấp.\n- Tư duy sản phẩm tốt, khả năng phân tích và giải quyết vấn đề hiệu quả.\nQuyền lợi\n- Lương thỏa thuận lên đến 2500 USD/tháng.\n- Lương tháng 13, thưởng quý theo kết quả kinh doanh.\n- Xét tăng lương hàng năm theo thành tích đóng góp.\n- Điều kiện làm việc linh hoạt.\n- Môi trường sáng tạo, năng động.\n- Thường xuyên tổ chức du lịch, team building.\n- Cơ hội thăng tiến lên vị trí Leader, Manager.\n- Chính sách thưởng cổ phần cho Key member, có đóng góp quan trọng cho công ty.\n- Phụ cấp ăn trưa.\n- Hưởng đầy đủ các chế độ đãi ngộ theo quy định của pháp luật.\nĐịa điểm làm việc\n- Hà Nội: King Building, Số 7 P. Chùa Bộc, Kim Liên, Đống Đa, Đống Đa.\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:30).\n- Break time: 1.30h.\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2516, 1184, 2, 'Bridge Software Engineer', 'Mô tả công việc:\n❖ Bridge Software Engineer:\n- Là cầu nối giữa đội phát triển ở Việt Nam và khách hàng Nhật Bản.\n- Phân tích, trao đổi yêu cầu nghiệp vụ và kỹ thuật với khách hàng.\n- Kiểm soát tiến độ, quản lý dự án và báo cáo công việc định kỳ với khách hàng.\n- Kiểm tra chất lượng đầu ra của sản phẩm trước khi bàn giao.\n\n❖ Collaboration and Mentorship:\n- Làm việc chặt chẽ với các đội nhóm đa chức năng, bao gồm product managers, designers, và engineers để đáp ứng các mục tiêu kinh doanh.\n- Cố vấn cho các kỹ sư cấp dưới và thúc đẩy văn hóa học tập, đổi mới trong đội nhóm.\n\n❖ Optimization and Innovation:\n- Giám sát hiệu suất hệ thống, tối ưu hóa để cải thiện khả năng mở rộng và hiệu quả.\n- Theo dõi các xu hướng công nghệ mới và đưa ra các đề xuất cải tiến.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Khoa học Máy tính, Kỹ thuật hoặc lĩnh vực liên quan.\n- Ít nhất 5 năm kinh nghiệm phát triển phần mềm, bao gồm ... năm ở vai trò lãnh đạo, ... năm kinh nghiệm ở vị trí BrSE, tập trung vào các nền tảng như SaaS, PaaS hoặc IaaS.\n- Tiếng Nhật (JLPT N2 trở lên), tiếng Anh giao tiếp tốt là lợi thế.\n- Thành thạo cả công nghệ front-end và back-end, bao gồm nhưng không giới hạn ở:\n1. Front-end: HTML/CSS, JavaScript (React, Angular), CSS preprocessors (Sass, Less)\n2. Back-end: Java, Golang, Python.\n3. Databases: SQL (MySQL, PostgreSQL), NoSQL (MongoDB, Redis)\n- Có kinh nghiệm với các nền tảng đám mây (AWS, Azure, Google Cloud) và công cụ CI/CD (Jenkins, Docker).\n- Hiểu biết sâu sắc về các mẫu thiết kế phần mềm, cấu trúc dữ liệu và thuật toán.\n- Quen thuộc với phương pháp Agile/Scrum và các công cụ quản lý dự án (Jira, Trello).\n\nNice to have (ưu tiên):\n- Chứng chỉ về quản lý dự án hoặc công nghệ đám mây (ví dụ: PMP, AWS),\n- Sở hữu chứng chỉ Scrum là một lợi thế.\n- Hiểu biết về văn hóa làm việc của người Nhật; có kinh nghiệm trong môi trường gia công phần mềm hoặc Agile/Scrum.\n- Kỹ năng cố vấn và cộng tác tốt trong đội nhóm.\n\nQuyền lợi:\n- Chính sách bảo hiểm xã hội, bảo hiểm y tế theo quy định của Nhà nước. Bảo hiểm sức khỏe PVI sau 01 năm làm việc.\n- Môi trường làm việc trẻ trung, năng động, thân thiện.\n- Cơ hội làm việc onsite tại Nhật Bản.\n- Thường xuyên tổ chức các seminar do chính nhân viên công ty thực hiện, tạo điều kiện nghiên cứu, trao đổi, phát triển.\n- Hỗ trợ tiền nhà ở trong bán kính 2km.\n- Hỗ trợ chi phí gửi xe và các tiện ích khác.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 181 Cao Thắng, Phường 12 0, Quận 10\n- Hồ Chí Minh: Vinhome Grand Park, Nguyễn Xiển, Phường Long Thạnh Mỹ, Quận 9\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2517, 1120, 2, 'Nhân Viên Mobile App Developer (React Native)', 'Mô tả công việc\n- Tham gia phát triển và xây dựng các sản phẩm dựa trên nền React Native.\n- Tìm hiểu công nghệ, xây dựng mới và phát triển tính năng hiện tại của các dự án.\n- Nâng cấp, phát triển thêm tính năng theo yêu cầu khách hàng\n- Quản lý và bảo trì các ứng dụng đảm bảo chất lượng.\n- Hỗ trợ, sửa lỗi trong quá trình triển khai.\n- Đảm bảo tiến độ, chất lượng công việc và báo cáo thường xuyên tới quản lý.\n- Thực hiện một số công việc khác khi có yêu cầu của cấp trên.\n\nYêu cầu ứng viên\n- Thành thạo lập trình mobile app cross-platform trên React Native framework\n- Nắm vững kiến thức lập trình trên mobile\n- Có kinh nghiệm chuyên phát triển trên Android (ưu tiên) hoặc iOS là một lợi thế\n- Có kinh nghiệm phát triển mobile app trên các nền tảng cross-platform (Ionic/Native script) khác là một lợi thế\n- Kinh nghiệm phát triển App với React Native tối thiểu từ 1-2 năm.\n- Có kinh nghiệm lập trình giao tiếp giữa mobile với server qua các giao thức TCP/IP, Firebase, Websocket, WebService và JSON/XML\n- Nhiệt tình trong công việc và chủ động trao đổi, học hỏi\n\nQuyền lợi\n- Mức lương cơ bản từ 8 - 20 triệu tùy theo năng lực và vị trí công việc.\n- Được tổ chức sinh nhật, nghỉ lễ, nghỉ phép và hưởng quyền lợi theo Luật lao động.\n- Đồng nghiệp và môi trường làm việc năng động\n- Cơ hội được học tập và đào tạo nội bộ về các kỹ năng trong công việc.\n\nĐịa điểm làm việc\n- Nghệ An: Tầng 22 Handico 30 Quang Trung, TP Vinh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 07:45 đến 17:00)\n- Thứ 7 luân phiên nghỉ/ làm\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nghệ An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2518, 1353, 2, 'Nhân Viên Vận Hành Máy CNC', '- Đọc bản vẽ, lập chương trình gia công, vận hành các máy phay CNC.\n- Bảo dưỡng và bảo trì máy móc.\n- Làm việc theo sự chỉ đạo của cấp trên\n- Chi tiết sẽ trao đổi cụ thể khi phỏng vấn.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Cao đẳng trở lên nghành kỹ thuật\n- Có ít nhất 3 năm kinh nghiệm sử dụng máy gia công phay CNC  và biết lập trình gia công.\n- Biết đọc bản vẽ kĩ thuật, Autocad\n\nQuyền lợi:\n- Lương từ 9.000.000 - 12.000.000VND tùy vào kinh nghiệm làm việc.\n- Làm việc giờ hành chính.\n- Một năm 12 ngày phép năm, một tháng công ty được nghỉ 1 ngày thứ bảy hoặc 2 ngày tùy từng tháng.\n- Được làm việc trong môi trường chuyên nghiệp, thân thiện, có cơ hội thăng tiến trong công việc.\n- Được hưởng các ngày nghỉ tết, ngày lễ, tăng lương hằng năm, thưởng lương tháng thứ 13.\n- Được hưởng các quyền lợi theo quy định của Luật lao động và BHXH.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2519, 1354, 2, 'Lập Trình Ứng Dụng', 'Mô tả công việc\n- Lập trình, triển khai và bảo trì / vận hành các ứng dụng Websitres, di động, hệ thống phần mềm ERP... dựa trên phân tích thiết kế\n- Cập nhật và bố trí nội dung trên các ứng dụng Websites, di động, hệ thống phần mềm ERP cũng như các yêu cầu khác liên quan đến lập trình\n- Trực tiếp làm việc với người dùng chính để tiếp nhận yêu cầu phát triển chức năng và cài đặt những tính năng mới cho các ứng dụng\n- Hỗ trợ người sử dụng khắc phục lỗi của ứng dụng liên quan đến code của phần mềm theo quy trình hoạt động của Phòng IT\n- Lập trình hoặc phát triển các ứng dụng khác theo yêu cầu thực tế từ Công ty\n- Thực hiện một số công việc phát sinh khác theo phân công từ Quản lý trực tiếp trong từng thời điểm.\n\nYêu cầu ứng viên\n- Nam / Nữ có sức khỏe tốt, ngoại hình cân đối và dễ nhìn\n- Tốt nghiệp Cao đẳng trở lên chuyên ngành CNTT phần mềm\n- Kinh nghiệm 2 năm trở lên tại vị trí tương đương, ưu tiên biết ngôn ngữ lập trình C#\n- Có kiến thức về thiết kế Cơ sở dữ liệu, SQL Reporting Service (SSRS) trên môi trường Microsoft SQL Server\n- Có kiến thức cơ bản về HTML / HTML5 / CSS, MVC3, Webservices, Javascript (JQuery, JSON)\n- Kỹ năng phân tích, xử lý vấn đề trên hệ thống\n- Năng động, khéo léo và khả năng chịu được áp lực công việc cao.\n\nQuyền lợi\n- Thử việc: 02 tháng (100% Lương)\n- Lương cạnh tranh theo năng lực\n- Lương tháng 13 và Thưởng cuối năm theo hiệu quả công việc và kết quả kinh doanh Công ty\n- Tham gia BHXH và Bảo hiểm Sức khỏe theo chính sách Công ty\n- Khám sức khỏe định kỳ, hoạt động Team Building, du lịch hàng năm.\n\nChế độ và phúc lợi khác mang đến nhiều quyền lợi hữu ích cho nhân viên\nChính sách Đào tạo mang đến cơ hội trải nghiệm và phát triển nghề nghiệp\nThời gian làm việc: từ thứ 2 đến thứ 6 hàng tuần\nNghỉ chế độ, Phép năm, các ngày Lễ / Tết theo quy định.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 12 Nguyễn Hiền, Phường 4, Quận 3\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2520, 1355, 2, 'Kỹ Sư Lập Trình Thiết Bị Đo Lường & JIG TEST', 'Mô tả công việc\n- Phát triển phần mềm giao tiếp với các thiết bị đo lường, kiểm tra chất lượng sản phẩm (ATE, DAQ, PLC, đồng hồ đo điện, cảm biến...).\n- Thiết kế, lắp đặt và vận hành hệ thống jig test phục vụ sản xuất, R&D hoặc kiểm tra end-of-line.\n- Tham gia vào quá trình tích hợp phần mềm, phần cứng và xây dựng các giải pháp tự động hóa kiểm tra.\n- Phối hợp với các bộ phận liên quan để làm rõ yêu cầu kỹ thuật, hỗ trợ khắc phục sự cố, bảo trì thiết bị đo lường và jig test.\n- Đào tạo, chuyển giao công nghệ cho đội vận hành và kỹ thuật viên.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học các ngành: Tự động hóa, Điện - Điện tử, Cơ điện tử, Công nghệ thông tin hoặc các ngành liên quan.\n- Có kinh nghiệm lập trình giao tiếp với các thiết bị đo lường qua các giao thức như RS232/485, LAN, USB, GPIB, CAN, Modbus, v.v.\n- Thành thạo một trong các ngôn ngữ lập trình: Python, C#, C++, LabVIEW, hoặc tương đương.\nCó hiểu biết về thiết kế mạch điện, hệ thống điều khiển, cảm biến, actuator, và các hệ thống đo lường.\n- Ưu tiên ứng viên có kinh nghiệm thực tế trong việc xây dựng jig test, hệ thống kiểm tra tự động, hoặc từng làm việc trong môi trường sản xuất công nghiệp.\n- Kỹ năng giải quyết vấn đề, tư duy logic và khả năng làm việc độc lập/tập thể tốt.\n- Đọc hiểu tài liệu tiếng Anh kỹ thuật.\n\nQuyền lợi\n- Thu nhập hấp dẫn, thưởng theo hiệu quả công việc.\n- Môi trường làm việc năng động, chuyên nghiệp, cơ hội phát triển và thăng tiến.\n- Được đào tạo, tham gia các dự án lớn cùng các chuyên gia đầu ngành.\n- Chế độ bảo hiểm, phúc lợi đầy đủ theo quy định.\n\nĐịa điểm làm việc\n- Hà Nội: Trung Kính, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Từ thứ 2 đến thứ 6\nNghỉ thứ 7 - Chủ nhật.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2521, 1150, 2, 'Frontend Developer', 'Mô tả công việc:\n- Tham gia quá trình thiết kế, phát triển giao diện cho các sản phẩm của công ty (chủ yếu Web based).\n- Xây dựng, phát triển và tối ưu các chức năng của sản phẩm.\n- Sáng tạo, đề xuất các cải tiến mới trong quá trình phát triển product.\n\nYêu cầu ứng viên:\n- Có ít nhất 2 năm làm việc thực tế với Front-end (Trong đó ít nhất hơn 1 năm làm Reactjs, biết Nextjs là điểm cộng).\n- Thành thạo JavaScript (ES6+), HTML, CSS.\n- Kinh nghiệm thao tác DOM và xử lý sự kiện trình duyệt.\n- Có khả năng làm việc độc lập, xây dựng được nền tảng base cho app.\n- Hiểu biết về các kỹ thuật server push và giả server push.\n- Biết sử dụng các công cụ AI để hỗ trợ code.\n\nQuyền lợi:\n- Lương từ 15 triệu - 25 triệu.\n- Thưởng: thưởng năng suất, thưởng ngày lễ, tháng 13, …\n- Review năng lực định kỳ 6 tháng/ lần.\n- Trà, cà phê free, tham gia nghỉ mát, hoạt động team building của công ty.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Hỗ trợ tối đa các thiết bị phục vụ công việc.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 2, Sàn dịch vụ thương mại tòa nhà CT2D, VOV Mễ Trì,, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Sáng thứ 7 ( 8h-12h)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2522, 1356, 2, 'Kỹ Thuật Viên Lập Trình & Vận Hành Máy CNC', 'Mô tả công việc:\nKiểm tra chương trình và Setup máy CNC. Vận hành máy CNC: Đọc bản vẽ, chuẩn bị dụng cụ cắt, chỉnh sửa chương trình...\nTham gia vào quá trình cải tiến và tối ưu hóa quy trình sản xuất.\nGiám sát quá trình gia công, đảm bảo sản phẩm đúng kích thước, không lỗi kỹ thuật.\nBáo cáo và phối hợp với bộ phận kỹ thuật nếu phát sinh lỗi, đề xuất phương án xử lý.\nThực hiện bảo dưỡng định kỳ theo hướng dẫn.\nLàm việc chặt chẽ với bộ phận lập trình, QC, kho vật tư để đảm bảo tiến độ và chất lượng sản phẩm.\nGhi chép báo cáo sản xuất hàng ngày, đề xuất cải tiến nếu có.\nTuân thủ các quy định về an toàn lao động và bảo vệ môi trường.\nThực hiện các công việc khác theo sự phân công của cấp trên.\n\nYêu cầu ứng viên:\nTuổi: 25-36, Ưu tiên ứng viên có kinh nghiệm tối thiểu 1 năm trở lên, có tư duy tốt về công nghệ sản xuất tối ưu.\nTốt nghiệp Cao đẳng, Đại học chuyên ngành Cơ khí, Tự động hóa hoặc các chuyên ngành liên quan.\nCó kiến thức cơ bản về thiết kế kỹ thuật, đọc hiểu bản vẽ kỹ thuật.\nThành thạo phần mềm AutoCad, Thiết kế 3D SolidWorks, Lập trình CNC bằng Mastercam, Thành thạo G-code. Khả năng làm việc độc lập và làm việc nhóm tốt.\nCẩn thận, tỉ mỉ, chịu được áp lực công việc.\nKhả năng giao tiếp tốt, có tinh thần trách nhiệm cao.\nNắm vững các nguyên lý cơ bản về cơ khí, vật liệu.\nCó thể làm việc theo ca, tăng ca, ca kíp.\n\nQuyền lợi:\nMức lương : 12-25 triệu, deal năng lực và kinh nghiệm.\nChế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật.\nThưởng các ngày lễ, tết, thưởng hiệu quả công việc.\nCơ hội được đào tạo, nâng cao nghiệp vụ chuyên môn.\nMôi trường làm việc năng động, chuyên nghiệp, thân thiện.\nCơ hội thăng tiến lên Quản lý sản xuất.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 6 lô 5, KCN Lai Xá, Xã Kim Chung, Hoài Đức\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2523, 1357, 2, 'Nhân Viên Lập Trình Máy Phay CNC _ Thu Nhập Up To 20M++ _ Đi Làm Ngay Tại Hoàng Mai - HN', 'Mô tả công việc:\n- Lập trình cho các mã hàng sản xuất theo kế hoạch sản xuất\n- Giảm tỉ lệ lỗi phát sinh trong khi lập trình bao gồm: các lỗi mới phát sinh trong khi lập trình, các lỗi lặp lại trong khi lập trình.\n- Setup các nguyên công chạy các mã hàng trên các máy\n- Giảm tỉ lệ lỗi phát sinh trong quá trình setup trên các máy, bao gồm: Tỉ lệ lỗi NG phải bỏ hàng khi setup hàng lượt đầu do lập trình, tỉ lệ lỗi NG phải bỏ hàng khi setup hàng lượt đầu do gá đặt và xét dao, xét phôi.\n- Tổng hợp và lập báo cáo tỉ lệ lỗi các mã hàng và báo cáo hàng tuần cho cấp trên.\n- Cải tiến lập trình giúp giảm thời gian gia công và nâng cao tính ổn định khi sản xuất hàng loạt.\n\nYêu cầu ứng viên:\n- Kỹ năng sử dụng thời gian hiệu quả;\n- Tư duy logic, nhạy bén, sáng tạo.\n- Trung thực, thẳng thắn, nhiệt tình công tác;\n- Nam giới, từ 25 tuổi trở lên.\n- Tốt nghiệp Trung cấp trở lên chuyên ngành kỹ thuật hoặc các chuyên ngành liên quan.\n- Ít nhất 1 năm kinh nghiệm ở vị trí tương đương.\n\nQuyền lợi:\n1. Lương & Thưởng\n- Mức lương cạnh tranh, phù hợp với năng lượng và kinh nghiệm\n- Thưởng theo hiệu suất làm việc, lễ, tết, lương tháng 13.\n- Tăng lương định kỳ \n2. Chế độ Bảo hiểm & Phúc Lợi Xã Hội\n- Chế độ nghỉ thai sản, nghỉ nghỉ, nghỉ phép có lương theo quy định\n3. Môi Trường Làm Việc\n- Môi trường làm việc chuyên nghiệp, năng động, có tiến bộ.\n- Công cụ hỗ trợ hiện tại\n- Văn hóa doanh nghiệp thân thiện, tôn trọng và gắn kết.\n4. Đào Tạo & Phát Triển Nghề Nghiệp\n- Tham gia các khóa đào tạo kỹ năng, chuyên môn\n- Hỗ trợ học phí, nâng cao trình độ \n5. Các Phúc Lợi Khác\n- Du lịch, teambuilding hàng năm.\n- Hỗ trợ ăn trưa\n- Các hoạt động nội bộ như sinh nhật, quà tặng, liên hoan.\n\nĐịa điểm làm việc:\n- Hà Nội: 481 Tam Trinh, Hoàng Văn Thụ, Hoàng Mai, Hoàng Mai\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2524, 1280, 2, 'AI Engineer', '● Xây dựng pipeline xử lý dữ liệu từ các nguồn như livestream, video, text, audio,...\n● Triển khai các thuật toán AI/ML cho các bài toán như:\n- Natural Language Processing (NLP)\n- Computer Vision (CV)\n- Speech-to-Text / Voice Analysis\n- Recommendation Systems\n● Kết hợp AI với các hệ thống backend / API nội bộ để phục vụ nhu cầu thực tế.\n● Nghiên cứu và ứng dụng các mô hình AI mã nguồn mở (open-source), pre-trained models, fine-tuning phù hợp với dữ liệu của công ty.\n● Làm việc chặt chẽ với các team Backend, Game, Data Analyst để tích hợp AI vào sản phẩm.\n\nYêu cầu ứng viên\nBẮT BUỘC:\n● Tốt nghiệp chuyên ngành CNTT, Khoa học dữ liệu, Toán tin, hoặc tương đương.\n● Thành thạo ít nhất 1 ngôn ngữ lập trình dùng trong AI/ML (Python, PyTorch, TensorFlow,...)\n● Có kinh nghiệm với ít nhất 1 nhóm bài toán AI (NLP / CV / Voice / Recommendation)\n● Có tư duy triển khai thực tế: biết cách chuyển mô hình AI thành sản phẩm sử dụng được.\n● Biết cách xử lý dữ liệu, huấn luyện và đánh giá mô hình ML.\nƯU TIÊN:\n● Từng làm việc trong startup hoặc môi trường agile, tốc độ nhanh.\n● Đã triển khai AI lên sản phẩm thực tế (API, hệ thống backend, dịch vụ cloud,...)\n● Có hiểu biết về LLMs, inference optimization (ONNX, quantization, etc.)\n\nQuyền lợi\n● Mức lương cạnh tranh, thỏa thuận trong quá trình phỏng vấn\n● Làm việc trong môi trường sáng tạo, startup công nghệ, có ứng dụng AI thực tế.\n● Cơ hội tiếp cận mô hình LLM, hệ thống AI mới nhất.\n● Được thử nghiệm và triển khai các ý tưởng AI mới trong các sản phẩm đa dạng.\n● Lương thưởng cạnh tranh, cơ hội tăng trưởng cao theo năng lực.\n● Tham gia team từ giai đoạn đầu, có thể phát triển lên Lead / Architect.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 15, tòa nhà văn phòng Discovery Complex, 302 Cầu Giấy, P.Dịch Vọng Hậu, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2525, 1358, 2, 'Middle Frontend Developer', 'Chúng tôi đang tìm kiếm một Middle Frontend Developer có định hướng phát triển thành Fullstack Developer, để đồng hành trong hành trình xây dựng các sản phẩm thương mại điện tử quy mô lớn, chịu tải cao, tập trung vào hành trình trải nghiệm khách hàng và khai thác AI để nâng cao hiệu quả phát triển.\n\nBạn sẽ làm việc trong một môi trường đề cao đổi mới sáng tạo, tinh thần tự học và ứng dụng công nghệ mới nhằm tạo ra các giải pháp thông minh, tối ưu cho người dùng và doanh nghiệp.\n\nTrách nhiệm chính\n\n           •          Phát triển và tối ưu hóa giao diện người dùng (SPA/PWA) trên nền tảng thương mại điện tử hiệu suất cao.\n\n           •          Kết hợp cùng backend team để thiết kế và xây dựng API hiệu quả, bảo mật.\n\n           •          Áp dụng các công nghệ AI (như ChatGPT, AI assistant, code suggestion tools) vào quy trình phát triển sản phẩm và tự động hóa.\n\n           •          Tham gia cải tiến hiệu suất, SEO, trải nghiệm người dùng dựa trên Customer Journey thực tế.\n\n           •          Tích hợp và vận hành các dịch vụ AWS: S3, CloudFront, Cognito, Lambda, v.v.\n\n           •          Viết mã chất lượng cao, dễ đọc, dễ bảo trì.\n\n           •          Đề xuất các cải tiến kỹ thuật mới, thử nghiệm các giải pháp sáng tạo để nâng cao hiệu quả sản phẩm và quy trình.\n\nYêu cầu ứng viên\n\n           •          2–4 năm kinh nghiệm với React.js, Next.js, hoặc Vue.js.\n\n           •          Có định hướng hoặc kinh nghiệm với backend như Node.js, NestJS, hoặc RESTful APIs.\n\n           •          Thành thạo HTML5, CSS3, JavaScript (ES6+), TypeScript.\n\n           •          Kinh nghiệm thực tế với AWS: S3, Lambda, CloudFront, Cognito, RDS/DynamoDB.\n\n           •          Đã từng tham gia phát triển hệ thống eCommerce quy mô lớn (100.000+ người dùng).\n\n           •          Am hiểu UX/UI, hành trình khách hàng, tracking (GA4, Mixpanel…).\n\n           •          Có kinh nghiệm sử dụng các công cụ AI hỗ trợ lập trình (ChatGPT, GitHub Copilot, v.v.).\n\n           •          Tư duy sản phẩm và tinh thần cầu tiến, không ngừng học hỏi cái mới.\n\n           •          Sử dụng tốt Git và có kinh nghiệm làm việc theo mô hình Agile/Scrum.\n\nQuyền lợi\n\nAttractive salary, commensurate with capacity.\n13th month salary bonus, achievement bonus: 14-15 months, monthly/quarterly/yearly business bonus, Tet holiday bonus.\nRice allowance and other allowances (according to the nature of the job)\nAnnual health check-ups\nSocial insurance; 24/24 accident insurance\nLeave regime for employees from 12-14 days/year\nTraining and career development programs.\nProfessional working environment.\nCollective activities: Team Building, Family Festival, Arts, Sports Club, Vacation...\nCommunity activities: Gifts on the occasion of 8/3, 20/10, International Children\'s Day 1/6, Mid-Autumn Festival.....\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: 170E Phan Đăng Lưu, Phú Nhuận\n\nThời gian làm việc\n\nThứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2526, 1250, 2, 'Senior Fullstack Developer', 'OUR TECH STACK:\nBackend:\nNode.js / ExpressJs\nRabbitMQ / Kafka / MSSQL\nDocker / Kubernetes / Jenkins\nFrontend:\nReactJS/ NextJs\nES6 / Webpack\nRedux / Redux-Saga / Reselect / Hooks\nRESPONSIBILITIES:\nDesign, code, and review scalable, maintainable software solutions that align with business and system architecture.\nIdentify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\nCollaborate across squads (frontend, backend, QA…) to share knowledge, align on best practices, and mentor junior team members\nTake ownership of features or systems; lead projects or squads when needed, ensuring delivery quality and guiding technical direction.\n\nMust-Have:\nProactive problem-solver with a bias toward action and ownership.\nQuick to pick up new frameworks, libraries, and tooling as the stack evolves..\nAt least 4 years of real-world experience in software development.\nFamiliarity with macOS or Linux for development and deployment tasks.\nHands-on experience or working knowledge in our core stack is required; full expertise in one side (FE or BE) is acceptable:\nBackend: Node.js, PostgreSQL, Redis, Elasticsearch.\nFrontend: React.js, Redux, Redux-Saga, Reselect, React Hooks.\nCommitment to code quality:\nStrong experience in code reviews.\nFamiliarity with unit testing best practices.\nGrowth mindset: Ready to grow rapidly as the company scales several times a year.\nNice-to-Have (Plus):\nDeep understanding of Webpack, including code splitting, asset optimization, and custom configurations.\nStrong foundation in computer science: Data structures, algorithms, design patterns.\nExperience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\nFamiliarity with microservices architecture.\n\nCompetitive Compensation & Bonuses\nAttractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n100% salary during the probation period.\n13th-month salary to ensure financial stability.\nPerformance reviews twice a year with opportunities for salary adjustments.\nFlexible Work & Growth Opportunities\nHybrid working model: Work from home or at the office as needed.\nWork alongside top CTOs, architects, and tech leaders at Vexere.\nBuild your public profile through:\nPublishing articles on Medium & Vexere Techblog under your name.\nContributing to Open Source projects managed by Vexere.\nSpeaking at tech talks and industry events.\nAttractive stock options for dedicated developers and team leads.\nExclusive Employee Perks\nUp to 30% discount on bus tickets for Vexere employees and their families.\n12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\nVibrant and dynamic work environment with a friendly, supportive team.\nTraining sessions on negotiation, communication, work management, interpersonal skills, and software technology.\nExciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 384 Hoàng Diệu, Quận 4\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nThứ 7 (từ 09:00 đến 12:00)\nThứ 2- Thứ 6, Sáng thứ 7\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2527, 1359, 2, 'Lập Trình Viên Senior Fullstack (Mạnh Về System) Dự Án Fintech', 'Mô tả công việc:\n- Thiết kế, phát triển và duy trì các dịch vụ backend mạnh mẽ sử dụng Java (Spring Boot) và Node.js (Express.js, SocketCluster, v.v.).\n- Xây dựng và duy trì các hệ thống microservices có khả năng mở rộng và hệ thống giao tiếp thời gian thực.\n- Lập trình Frontend, sử dụng ReactJS/NextJS để mang lại trải nghiệm liền mạch cho người dùng.\n- Tối ưu hiệu suất hệ thống và đảm bảo độ sẵn sàng, độ tin cậy và khả năng mở rộng cao cho các dịch vụ Backend.\n- Hợp tác với đội ngũ DevOps để quản lý các ứng dụng container hóa sử dụng Docker, Kafka và Nginx.\n- Thực hiện thiết kế cơ sở dữ liệu, triển khai và tinh chỉnh hiệu năng trên các hệ quản trị MySQL, MongoDB và Redis.\n- Tham gia các cuộc thảo luận kiến trúc, đánh giá mã nguồn và tư vấn giải pháp cùng các nhóm chức năng chéo.\n- Đảm bảo các tiêu chuẩn tốt nhất về chất lượng mã nguồn, bảo mật và khả năng bảo trì.\n- Đóng vai trò cầu nối kỹ thuật giữa các nhóm và hướng dẫn các lập trình viên cấp dưới.\n\nYêu cầu ứng viên:\nKinh nghiệm và Kỹ năng:\n- Trên 4 năm kinh nghiệm phát triển backend với Java (Spring Boot).\n- Kỹ năng lập trình hướng đối tượng (OOP) vững chắc.\n- Có kinh nghiệm thực tế với Node.js, bao gồm Express.js và các framework thời gian thực như SocketCluster.\n- Ít nhất 2 năm kinh nghiệm với ReactJS và NextJS.\n- Thành thạo trong việc làm việc với cơ sở dữ liệu MySQL, MongoDB và Redis.\n- Hiểu biết chuyên sâu về kiến trúc microservices.\n- Có kinh nghiệm làm việc với Docker, Kafka và Nginx trong môi trường sản xuất thực tế.\n- Tư duy logic và phân tích mạnh mẽ; có kinh nghiệm trong thiết kế hệ thống và kiến trúc phần mềm.\n- Có kinh nghiệm tối ưu hiệu suất ứng dụng và xử lý hệ thống có lưu lượng truy cập cao.\n- Tinh thần trách nhiệm cao; có khả năng làm việc độc lập hoặc dẫn dắt một nhóm nhỏ.\n- Kiến thức trong lĩnh vực chứng khoán tài chính là một điểm cộng.\n\nQuyền lợi:\n- Mức lương và thưởng hấp dẫn\n- 12 ngày nghỉ phép năm\n- Được tham gia đầy đủ bảo hiểm xã hội và bảo hiểm y tế theo quy định của nhà nước\n- Các khoản phụ cấp hấp dẫn (thưởng onsite, gửi xe, sinh nhật, happy hours, v.v.)\n- Xét duyệt tăng lương hàng năm dựa trên hiệu suất và đóng góp của nhân viên\n- Các câu lạc bộ thể thao: chạy bộ, bóng bàn, bóng đá, v.v.\n- Môi trường làm việc thực sự cởi mở. Mọi người đều được tôn trọng và bạn có quyền tự do theo đuổi cũng như đạt được mục tiêu của mình\n- Các quyền lợi khác theo quy định của Bộ luật Lao động Việt Nam\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 3C Tôn Đức Thắng, phường Bến Nghé, Quận 1\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2528, 1184, 2, 'Bridge Software Engineer - Remote', '❖ Bridge Software Engineer:\nLà cầu nối giữa đội phát triển ở Việt Nam và khách hàng Nhật Bản.\nPhân tích, trao đổi yêu cầu nghiệp vụ và kỹ thuật với khách hàng.\nKiểm soát tiến độ, quản lý dự án và báo cáo công việc định kỳ với khách hàng.\nKiểm tra chất lượng đầu ra của sản phẩm trước khi bàn giao.\n\n❖ Collaboration and Mentorship:\nLàm việc chặt chẽ với các đội nhóm đa chức năng, bao gồm product managers, designers, và engineers để đáp ứng các mục tiêu kinh doanh.\nCố vấn cho các kỹ sư cấp dưới và thúc đẩy văn hóa học tập, đổi mới trong đội nhóm.\n\n❖ Optimization and Innovation:\nGiám sát hiệu suất hệ thống, tối ưu hóa để cải thiện khả năng mở rộng và hiệu quả.\nTheo dõi các xu hướng công nghệ mới và đưa ra các đề xuất cải tiến.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học chuyên ngành Khoa học Máy tính, Kỹ thuật hoặc lĩnh vực liên quan.\nÍt nhất 5 năm kinh nghiệm phát triển phần mềm, bao gồm ... năm ở vai trò lãnh đạo, ... năm kinh nghiệm ở vị trí BrSE, tập trung vào các nền tảng như SaaS, PaaS hoặc IaaS.\nTiếng Nhật (JLPT N2 trở lên), tiếng Anh giao tiếp tốt là lợi thế.\nThành thạo cả công nghệ front-end và back-end, bao gồm nhưng không giới hạn ở:\n1. Front-end: HTML/CSS, JavaScript (React, Angular), CSS preprocessors (Sass, Less)\n2. Back-end: Java, Golang, Python.\n3. Databases: SQL (MySQL, PostgreSQL), NoSQL (MongoDB, Redis)\nCó kinh nghiệm với các nền tảng đám mây (AWS, Azure, Google Cloud) và công cụ CI/CD (Jenkins, Docker).\nHiểu biết sâu sắc về các mẫu thiết kế phần mềm, cấu trúc dữ liệu và thuật toán.\nQuen thuộc với phương pháp Agile/Scrum và các công cụ quản lý dự án (Jira, Trello).\n\nNice to have (ưu tiên):\nChứng chỉ về quản lý dự án hoặc công nghệ đám mây (ví dụ: PMP, AWS),\nSở hữu chứng chỉ Scrum là một lợi thế.\nHiểu biết về văn hóa làm việc của người Nhật; có kinh nghiệm trong môi trường gia công phần mềm hoặc Agile/Scrum.\nKỹ năng cố vấn và cộng tác tốt trong đội nhóm\n\nQuyền lợi:\n-Chính sách bảo hiểm xã hội, bảo hiểm y tế theo quy định của Nhà nước. \n-Bảo hiểm sức khỏe PVI sau 01 năm làm việc\n-Môi trường làm việc trẻ trung, năng động, thân thiện.\n-Cơ hội làm việc onsite tại Nhật Bản.\n-Thường xuyên tổ chức các seminar do chính nhân viên công ty thực hiện, tạo điều kiện nghiên cứu, trao đổi, phát triển.\n-Hỗ trợ tiền nhà ở trong bán kính 2km.\n-Hỗ trợ chi phí gửi xe và các tiện ích khác.\n\nĐịa điểm làm việc:\n- Đà Nẵng\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2529, 1360, 2, 'Lập Trình Viên Backend (Senior)', 'Mô tả công việc\n- Phát triển và bảo trì hệ thống backend sử dụng .NET Core / ASP.NET Core.\n- Thiết kế kiến trúc hệ thống, phát triển RESTful APIs phục vụ frontend/mobile.\n- Tối ưu hiệu năng, bảo mật và khả năng mở rộng của hệ thống.\n- Tham gia phân tích yêu cầu nghiệp vụ, thiết kế hệ thống và giải pháp kỹ thuật.\n- Thực hiện code review, hướng dẫn và hỗ trợ các thành viên junior.\n- Viết unit tests, tích hợp CI/CD, và tham gia kiểm thử hệ thống.\n- Phối hợp với các team khác (BA, DevOps, QA, Frontend, Mobile) trong toàn bộ SDLC.\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc tương đương.\n- Tối thiểu 4–6 năm kinh nghiệm phát triển phần mềm backend bằng .NET Core.\n- Có kinh nghiệm làm việc với SQL Server, PostgreSQL hoặc các hệ quản trị CSDL quan hệ.\n- Hiểu biết tốt về Clean Architecture, SOLID principles, DDD, Design Patterns.\n- Có kinh nghiệm làm việc với Redis, RabbitMQ/Kafka, hoặc các hệ thống message queue.\n- Hiểu và áp dụng tốt các nguyên tắc bảo mật API (JWT, OAuth2) và kiểm soát session.\n- Có kinh nghiệm với các công cụ CI/CD (Azure DevOps, GitLab CI, Jenkins…).\n- Thành thạo Git, quy trình phát triển theo Agile/Scrum.\nƯu tiên:\n- Có kinh nghiệm với microservices, Docker, Kubernetes là lợi thế.\n- Đã từng làm việc với các công nghệ như SignalR, gRPC, hoặc GraphQL.\n- Biết các công cụ giám sát như Prometheus, Grafana, ELK Stack.\nQuyền lợi\n- Lương thỏa thuận theo kinh nghiệm và năng lực.\n- KPI tương ứng với 5 tháng lương thực nhận.\n- Tháng lương thứ 13.\n- Thưởng dự án theo các dự án tham gia.\n- Đặc biệt chia cổ tức cho cán bộ nhân viên theo lợi nhuận của công ty.\n- Tham gia các khóa đào tạo kỹ năng mềm phục vụ cho công việc.\n- Thưởng các dịp lễ, Tết và team building hàng năm.\n- Xét duyệt tăng lương 2 lần/năm.\n- Được hưởng đầy đủ BHXH, BHYT và BHTN theo luật lao động Việt Nam hiện hành.\n- Được làm việc trong một môi trường trẻ trung, năng động cùng với các chuyên gia hàng đầu trong nhiều lĩnh vực của công ty để học hỏi và phát triển hàng ngày.\n- Cơ hội làm việc với các tập đoàn lớn: Tham gia các dự án lớn, làm việc với các khách hàng và đối tác uy tín trong ngành công nghệ trong và ngoài nước.\nĐịa điểm làm việc:\nTòa nhà N03-T3, Khu Ngoại Giao Đoàn, Phường Xuân Tảo, Quận Bắc Từ Liêm, Hà Nội.\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2530, 1207, 2, 'IT Project Manager (Có Base Developer)', 'Mô tả công việc\n- Tham gia công việc quản lý các dự án làm việc với đối tác Nhật Bản.\n- Xây dựng quy trình làm việc, quy trình phát triển phần mềm, quy trình quản lý chất lượng phần mềm trong công ty.\n- Tham gia vào quản trị dự án xây dựng sản phẩm riêng của công ty.\n- Tiến hành estimate, quản lí tiến độ, quản lí rủi ro dự án.\n- Phỏng vấn, đánh giá năng lực, phân công công việc của các kĩ sư trong dự án.\n- Báo cáo tiến độ dự án, đánh giá nhân sự, đề xuất giải pháp với ban giám đốc.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học các chuyên ngành liên quan như: Công nghệ phần mềm, hệ thống thông tin, quản lý dự án phần mềm...\n- Có kỹ năng lập trình trên 3 năm kinh nghiệm, hiểu biết sâu về ít nhất một trong các ngôn ngữ lập trình như: PHP, JAVA, C/C++, Swift...\n- Đã có kinh nghiệm quản lý dự án với team size từ 5 người trở lên.\n- Đã có ít nhất 2 năm kinh nghiệm phát triển ứng dụng trên smartphone (ios/android).\n- Có kinh nghiệm 3 năm trở lên ở vị trí quản lý dự án hoặc tương đương.\n- Có kiến thức và kinh nghiệm về Linux Cloud Server: AWS, GCP, Azure,v.v\n- Có kiến thức sử dụng UML thiết kế hệ thống phần mềm, thiết kế CSDL quan hệ.\n- Đã có ít nhất 3 năm kinh nghiệm làm việc với GIT hoặc Bitbucket.\n- Kỹ năng quản lý con người để tối ưu hiệu suất công việc.\n- Có kinh nghiệm viết Unit testing, viết document.\n- Có tư duy lập trình hướng đối tượng MVC, đọc hiểu tiếng anh tốt để phục vụ cho công việc.\n- Có kiến thức liên quan đến Performance của MySQL Statement và Query\n- Ưu tiên ứng viên có kinh nghiệm sử dụng Docker để phát triển dự án, có kiến thức về Bảo mật và tối ưu\n\nQuyền lợi\n- Mức lương: up to 60 triệu, tùy theo kinh nghiệm.\n- Thử việc lên đến 100% lương chính thức\n- Được cung cấp thiết bị làm việc\n- Phụ cấp cơm trưa và gửi xe hàng tháng\n- Nghỉ thứ 7, chủ nhật\n- Đóng BHXH sau khi thử việc, hưởng các chế độ phúc lợi theo luật lao động Việt Nam\n- Điều chỉnh lương: 2 lần/năm, Lương tháng 13 + thưởng dự án theo quý tùy vào tình hình kinh doanh của công ty.\n- Du lịch 1 năm 1 lần, Team building theo quý, các hoạt động vui chơi giải trí khác như: bóng bàn, bóng đá,...\n- Có cơ hội đi công tác và làm việc tại Nhật Bản nếu đáp ứng được năng lực tốt.\n- Được làm việc trong môi trường trẻ trung, năng động, chuyên nghiệp theo tiêu chuẩn chất lượng Nhật Bản.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4 Tòa nhà H10, số 2 ngõ 475 Nguyễn Trãi, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2531, 1193, 2, 'Mobile Developer', 'Headquarter: Daoukiwoom Group\nIndustry: Finance & Trading\n- Develop Mobile Stock Trading app using JavaScript under the Kiwoom platform\n- Work directly with remote team to clarify tasks and requirements\n- Develop new features based on the user requirements (analyzing requirements and system design)\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance\n- Managing time and resources based on the WBS\n- Compile a weekly-report about the progress of tasks\n- Perform self-learning about a domain knowledge, write a report and conduct a seminar about it\n- Write high-quality, clean, elegant, maintainable, and testable code\n- Maintaining technical documents up-to-date\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the KiwoomFramework for KiwoomIndonesia, Finansia (in Thailand), and so on.\n\nYêu cầu ứng viên\nEducation & Experience\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Minimum 3 years of professional experience in mobile app development using JavaScript or iOS/Android native.\n- Experience and knowledge in markup language, including HTML, CSS is a must.\n- Ability to write clean, easy to understand code.\n- Familiarity with version control systems, such as Git or SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n- Solid understanding of the full mobile development life cycle\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nSoft Skills & Communication\n- Strong problem-solving and analytical skills.\n- Able to communicate in English, written and spoken.\n- Strong communication skills and teamwork, international experience is preferred.\n\nNice to have:\n- Over 1 year of experience in developing securities solutions, including a smartphone-based trading platform utilizing the Mobile Trading System (MTS)\n- Proficient in utilizing the Mobile development Framework (Ionic, PhoneGap, React, Vue, Nexacro)\n- Experience on working with oversea team.\n\nQuyền lợi\nIncome & Achievement \n- Competitive salary, salary review once a year\n- 13th month salary and Annual Performance Bonus\n- MVP and Shining star awards at the end of year\n- Global and professional working environment\n\nWorkplace Happiness \n- Full SHUI as Vietnamese Law\n- Premium Private Medical Insurance PVI and annual health check\n- 15-day annual leave, Christmas leave and 30-min menstrual leave for women\n- Company trip, YEP and monthly gathering time\n- Gifts on special occasion and fully stocked snack corner\n- Sponsored training courses and book purchase quarterly\n- Be well-equipped with new working equipment\n\nSpecial Offer\n- Providing training and education experience in Korea with Korean Finance/IT expert\n- Providing opportunities to work and support in IT/Finance fields overseas.\n\nHIRING PROCESS: The interview will be conducted at our office in Ho Chi Minh city.\nRound 1:\n- Step 1: Live coding test\n- Step 2: Interview with part team leader (upon passing coding test)\n- Step 3: Interview with Director\n\nRound 2: Final interview with Head Office in Korea\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tầng 14, tòa nhà AP, 518B Điện Biên Phủ, Phường 21, Bình Thạnh\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2532, 1361, 2, 'Game Developer', 'Mô tả công việc\n- Phát triển các game casual, hypercasual, midscore, … trên nền tảng Cocos\n- Cập nhật, nâng cấp các tính năng mới cho danh sách game của công ty\n- Tối ưu hiệu quả các game của công ty\n- Phát triển các game trên nền tảng Android, IOS, Facebook, …\n- Các công việc khác theo sự phân công của quản lý trực tiếp\n\nYêu cầu ứng viên\nTechnical Skill :\n- Có kinh nghiệm kinh nghiệm trên 1 năm lập trình Mobile (Chấp nhận đào tạo các bạn đã có từ 6 tháng).\n- Kiến thức và kinh nghiệm về ngôn ngữ JavaScript/TypeScripC\n- Yêu thích và đam mê lập trình, lập trình game\n- Kiến thức và kinh nghiệm về cocos creator. Chấp nhận đào tạo cho ứng viên có kinh nghiệm về ngôn ngữ khác như Unity, React, …\n- Có kinh nghiệm về Native là lợi thế\n- Đã có sản phẩm trên store Android hoặc iOS hoặc có thêm kiến thức cocos 2js là lợi thế. Hoặc tham gia phát triển sản phẩm đó là lợi thế\n\nSoft skill:\n- Có tinh thần trách nhiệm cao trong công việc.\n- Có khả năng làm việc độc lập hoặc theo nhóm, xử ký vấn đề tốt.\n- Có khả năng tiếp thu kiến thức mới tốt.\n- Năng động, cởi mở, có khả năng chịu áp lực công việc lớn.\n\nQuyền lợi\n- Mức thu nhập cạnh tranh, đánh giá hiệu suất định kỳ 2 lần / năm.\n- Tổng thu nhập trung bình 13 – 15 tháng lương/năm. Thưởng các ngày lễ, Tết (Tết dương lịch, Quốc khánh, 30/04, Trung thu, Tết thiếu nhi, Sinh nhật, …)\n- Môi trường trẻ trung, thân thiện, cởi mở, đề cao phát triển cá nhân.\n- Cung cấp bữa trưa, đồ uống, trái cây miễn phí tại văn phòng.\n- Du lịch hàng năm (1-3 lần), khám sức khỏe định kỳ, các câu lạc bộ thể thao nội bộ: Bi-a, Bi-lăc, chạy bộ, ...\n- Đóng BHXH, BHYT, BHTN đầy đủ sau 2 tháng thử việc.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4, tòa Green Park Tower, Lô 33, ngõ 6 Dương Đình Nghệ, phường Yên Hòa TP Hà Nội, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2533, 209, 2, 'Special Projects Engineer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\nRESPONSIBILITIES\n• Contribute to a wide range of initiatives, including:\n• Integration, automation, and customization of enterprise systems such as Salesforce, NetSuite, Airtable, Jira, and CLM.\n• Application development using Python, Java, React, and SQL.\n• DevOps and infrastructure management using GCP, Argo CD, Terraform, and GitHub.\n• Designing and maintaining data pipelines for orchestration, ingestion, and analytics.\n• Operate effectively in a fast-paced, high-ambiguity environment with shifting priorities and evolving scopes.\n• Collaborate cross-functionally to solve complex and undefined problems.\n• Maintain high standards while delivering rapid iterations.\n• Embrace a culture of continuous learning, feedback, and improvement.\nREQUIREMENTS\n• Require robust expertise in Salesforce and NetSuite.\nTechnical proficiency in:\n• Enterprise Platforms: Airtable, Jira, CLM systems\n• Programming Languages: Python, Java, SQL, JavaScript (React)\n• DevOps & Infrastructure: Google Cloud Platform (GCP), Argo CD, Terraform, GitHub\n• Data Engineering: Data orchestration, ingestion, and analytics pipelines\n• Demonstrated ability to learn quickly and work independently.\n• Comfortable with ambiguity and shifting priorities.\n• A "builder" mindset with a bias toward rapid prototyping and iteration.\n• Excellent problem-solving skills in both technical and strategic contexts.\n• Systems-oriented thinking, intellectual curiosity, and a strong sense of ownership.\n• Experience working across multiple technical domains and disciplines.\n• Strong communication and collaboration skills suited to a high-performance, innovation-driven culture.\nQuyền lợi\n• Attractive Salary Package based on your competence plus Annual Bonus and Project Performance Bonus.\n• Signing bonus up to 20M onboard before 02/07/2025\n• Annual Summer Vacation support from 700 hundred VND to 4 Million VND and up to 3 days off work.\n• 13th-month Salary.\n• Salary review according to Company Policy.\n• Annual leave according to Labor Law and Company Policy.\n• "FPT care" health insurance provided by Petrolimex (PJICO) and is exclusive for FPT employees: 57M – 160M.\n• 20% discount on school fee if your sons/daughters join FPT School.\n• Excellent cost-free learning opportunities: Udemy/ELSA PRO accounts for every employee & Udacity accounts for Managers, English/Japanese/Korean classes, sponsorship for taking certification such as PMP, AWS, etc.\n• International, professional, dynamic and friendly working environment and culture.\n• Be part of a team in an international world-class company and exchange knowledge with technology specialists and experts from the world’s leading companies.\n• Frequent staff activities and company parties;\n• Awesome social events and parties for employees.\n• Etc.\nSpecial offer for senior level:\n• Relocating package: Up to 100M (for senior candidates from Hanoi/HCM.C to Da Nang City).\n• Loan support: 4% interest rate (1 – 2 Billion VND package).\nĐịa điểm làm việc\n- Đà Nẵng: Tòa Nhà FPT Complex, Ðường Nam Kỳ Khởi Nghĩa, Phường Hoà Hải TP.Ðà Nẵng, Ngũ Hành Sơn\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2534, 1272, 2, 'Front-End Developer', 'Mô tả công việc:\n- Phối hợp với team backend, thiết kế, QA để đảm bảo chất lượng và tiến độ sản phẩm. Khởi tạo project, thiết lập các base cơ bản.\n- Tham gia phát triển các sản phẩm và chịu trách nhiệm phát triển về Front End cho các ứng dụng nền Web và di động với HTML/CSS, JavaScript, sử dụng các framework/thư viện như Angular / VueJS / ReactJS, Bootstrap.\n- Phân tích, xem xét, phản hồi cho các yêu cầu và thiết kế sản phẩm. Viết các tài liệu chức năng được yêu cầu.\n- Cắt giao diện website từ file thiết kế photoshop (PSD) sang HTML5/CSS3 & Javascript theo chuẩn W3C.\n- Đề xuất và triển khai các best practices, coding standard cho team frontend. Hướng dẫn, hỗ trợ đồng đội trong quá trình phát triển sản phẩm.\n- Tối ưu hiệu suất ứng dụng, bao gồm cải thiện tốc độ tải trang (lazy loading, code splitting), tối ưu re-render, tối ưu Web Vitals (LCP, FID, CLS).\n- Áp dụng các kỹ thuật bảo mật frontend để ngăn chặn các cuộc tấn công phổ biến như XSS, CSRF.\n- Tích hợp quy trình CI/CD, viết unit test (Jest, Testing Library) để đảm bảo chất lượng code.\n\nYêu cầu ứng viên:\n- Tốt nghiệp ĐH, CD chuyên ngành Công nghệ thông tin; Kĩ thuật phần mềm, Hệ thống thông tin, hoặc các ngành tương đương.\n- Có từ 2 năm kinh nghiệm trở lên.\n- Có kinh nghiệm lập trình trong Frontend development với Angular hoặc VueJS (HTML5/ CSS3 /JavaScript), làm việc với Restful API, Websocket.\n- Có kinh nghiệm thiết kế kiến trúc frontend cho các dự án lớn, xây dựng component library có thể tái sử dụng.\n- Có kinh nghiệm làm việc với các thư viện quản lý state nâng cao như Redux, Zustand (React) hoặc NgRx (Angular).\n- Kinh nghiệm tối ưu hiệu suất frontend, bao gồm code splitting, lazy loading, SSR (Server-side rendering) với Next.js hoặc Angular Universal.\n- Ưu tiên các ứng viên có kinh nghiệm sử dụng các JavaScript Libraries/Frameworks khác nhau (Angular, VueJS, ReactJS), các Frontend Developer Tools (Webpack, npm, bower, grunt). \n- Chủ động và có tinh thần trách nhiệm cao trong công việc.\n- Sử dụng thành thạo Git, hiểu biết về quy trình làm việc Git Flow.\n- Kinh nghiệm với công cụ quản lý task như Jira, công cụ design như Figma.\n\nQuyền lợi:\n- Mức lương UPTO 25 triệu, thỏa thuận theo năng lực ứng viên.\n- Thưởng dịp tết (tết dương và tết âm), dịp lễ (30/04-1/5; 2/9; Trung thu…) sinh nhật, hiếu hỷ.\n- Được tài trợ, tham gia các khóa đào tạo kỹ năng, chuyên môn hàng năm, thi lấy chứng chỉ để phục vụ cho công việc.\n- Review đánh giá tăng lương hàng năm.\n- Nghỉ phép 12 ngày/năm, nghỉ ốm/nghỉ chế độ thai sản/hiếu hỷ theo luật lao động.\n- Làm việc tại công ty quy mô lớn, quy trình làm việc chuyên nghiệp, được khuyến khích sáng tạo và phát triển các ý tưởng mới.\n- Môi trường trẻ, năng động, chuyên nghiệp, sếp trẻ tâm lý, đồng nghiệp thân thiện, văn hóa trao đổi thẳng thắn, cởi mở trên tinh thần hỗ trợ cùng phát triển.\n- Dự án lớn áp dụng các công nghệ tiên tiến nhiều cơ hội thăng tiến và phát triển.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4, Tòa The Garden Hill, 99 Trần Bìn, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2535, 1362, 2, 'Backend Developer (Java, Spring Boot)', 'Miwa Tech đang tìm kiếm Backend Developer (ưu tiên ứng viên có kinh nghiệm Full-stack), am hiểu chuyên sâu Java (Spring Boot), có khả năng triển khai hệ thống backend phức tạp và phối hợp hiệu quả với frontend team.\nTrách nhiệm chính:\n• Phát triển và tối ưu hệ thống backend với Java 17+, Spring Boot (Spring Data, Security, Hibernate)\n• Thiết kế và triển khai RESTful APIs, tối ưu truy vấn và cấu trúc cơ sở dữ liệu PostgreSQL\n• Viết Unit Test (JUnit, Mockito) và Integration Test với Spring Test\n• Phối hợp chặt chẽ với frontend team (React, TypeScript) để triển khai sản phẩm hiệu quả\n• Hỗ trợ vận hành hệ thống trên Google Cloud (nếu có)\n\nYêu cầu ứng viên\nBắt buộc:\n• Ít nhất 3 năm kinh nghiệm lập trình backend với Java (Spring Boot)\n• Tư duy hệ thống tốt, khả năng xử lý lỗi và tối ưu kiến trúc backend\n• Thành thạo thiết kế API, thao tác với PostgreSQL và viết test cho backend\n• Kinh nghiệm sử dụng Git, Maven, CI/CD\n\nFrontend (bonus):\n• Có kinh nghiệm hoặc hiểu biết về React, TypeScript, MUI\n• Có khả năng teamwork hiệu quả với frontend developer\n\nƯu tiên:\n• Từng làm việc với GCP (Cloud SQL, Cloud Run, Cloud Storage)\n• Biết sử dụng Docker, Terraform hoặc GraphQL\n\nQuyền lợi\n• Lương cạnh tranh, thỏa thuận theo năng lực\n• Môi trường trẻ trung, đa văn hóa, đề cao sáng tạo và chủ động\n• Cơ hội tham gia dự án lớn trong môi trường quốc tế chuyên nghiệp\n• Đào tạo chuyên sâu, cập nhật công nghệ mới liên tục\n• Thưởng dự án, lễ Tết, chế độ BHXH đầy đủ theo luật định\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Sunrise City North, 27 Nguyễn Hữu Thọ, P. Tân Hưng, Quận 7\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2536, 1363, 2, 'Java Developer', 'Mô tả công việc:\n- Phát triển sản phẩm phần mềm trên nền tảng Java Strust….cho các đối tượng khác nhau\n- Tham gia vào các giai đoạn của dự án: Phân tích, thiết kế, lập trình, bảo trì phần mềm\n- Lập trình các module theo thiết kế và công việc được phân công\n- Tài liệu hóa các đặc tả thiết kế và chức năng.\n\nYêu cầu ứng viên:\n- Từ 2 năm kinh nghiệm trở lên làm việc với các framework: Springboot, Hibernate, RESTAPI\n- Kinh nghiệm làm việc với Backend, API\n- Có kĩ năng phân tích yêu cầu\n- Có thể review code, phân tích lỗi và đề xuất các giải pháp cho các module phần mềm đơn giản\n- Có kỹ năng phân tích hệ thống vả thiết kế cơ bản. Có thể tham gia làm thiết kế chi tiết dựa trên đặc tả yêu cầu (SRS) và thiết kế kiến trúc (SAD).\n\nQuyền lợi:\n- Lương thỏa thuận (upto 25tr)\n- Được cung cấp đầy đủ thiết bị làm việc\n- Thưởng hiệu quả công việc, thưởng dự án\n- Teambuilding 2 lần/năm\n- Tham gia đầy đủ BHXH: BHTN, BHYT, BHTS…\n- Tham gia các hoạt động chung của công ty: Du lịch, 20/10, ngày nam giới, trung thu, giáng sinh, ngày nam giới.....\n- Được thử thách trong dự án lớn, có cơ hội khẳng định bản thân và phát triển sự nghiệp\n- Môi trường làm việc chân thành, cởi mở, gắn bó giúp đỡ nhau cùng phát triển.\n\nĐịa điểm làm việc:\n- Hà Nội: 25 Trần Hưng Đạo, Hoàn Kiếm, Hoàn Kiếm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2537, 1364, 2, 'Senior Software Engineer', 'Mô tả công việc\n- Tiếp nhận và đánh giá hệ thống phần mềm hiện tại (được phát triển bởi đối tác bên ngoài) để đảm bảo phù hợp với quy trình và nhu cầu vận hành nội bộ.\n- Thực hiện điều chỉnh, cải tiến kiến trúc hệ thống, mã nguồn và dữ liệu theo định hướng phát triển lâu dài của công ty.\n- Xây dựng và chuẩn hóa tài liệu kỹ thuật, quy trình triển khai, quản lý source code và vận hành hệ thống.\n- Đầu mối kỹ thuật, phối hợp với các phòng ban để tiếp nhận phản hồi và đề xuất giải pháp cải tiến hệ thống.\n- Trực tiếp sửa chữa hoặc hỗ trợ team xử lý các thay đổi, lỗi phát sinh, tối ưu hiệu suất hệ thống bằng các công nghệ: ReactJS, NestJS, NextJS.\n- Quản lý, vận hành cơ sở dữ liệu SQL / NoSQL, giám sát hệ thống server và bảo mật trên nền tảng Linux.\n- Thực hiện các nghiệp vụ liên quan hệ thống mạng, email, máy tính, server, phần mềm nội bộ.\n- Thực hiện các nhiệm vụ khác được cấp trên phân công.\n\nYêu cầu ứng viên\n- Có tối thiểu 5 năm kinh nghiệm trong lĩnh vực phát triển phần mềm, trong đó ít nhất 2 năm kinh nghiệm ở vai trò Lead/Tech Lead.\n- Thành thạo ReactJS, NestJS, NextJS – có khả năng đọc hiểu, phân tích và refactor mã nguồn đã có sẵn.\n- Có kinh nghiệm thực tế với cơ sở dữ liệu SQL và NoSQL (ví dụ: MySQL, PostgreSQL, MongoDB...).\n- Có hiểu biết và kinh nghiệm triển khai/vận hành trên môi trường Linux server.\n- Tư duy hệ thống tốt, có khả năng đánh giá kiến trúc phần mềm, đề xuất giải pháp cải tiến phù hợp với thực tế doanh nghiệp.\n- Có khả năng quản lý công việc, tổ chức tài liệu, quy trình, và xây dựng tiêu chuẩn kỹ thuật nội bộ.\n- Giao tiếp Tiếng Anh.\n\nQuyền lợi\n- Thu nhập: Cạnh tranh theo năng lực\n- 05 ngày làm việc/tuần với 8h/ngày\n- 100% lương trong thời gian thử viêc.\n- Xét lương hàng năm\n- 12 ngày phép năm + 01 ngày nghỉ lễ công ty + 0.5 ngày nghỉ sinh nhật\n- Được tham gia đóng BHXH, BHYT theo quy định của nhà nước\n- Môi trường làm việc trẻ trung, năng động\n- Hoạt động team building, du lịch…\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 5 Lotte Mall Võ Chí Công, Tây Hồ\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2538, 1344, 2, 'Senior Backend Developer', 'Mô tả công việc:\n- Thiết kế kiến trúc hệ thống backend hiệu quả, linh hoạt và dễ mở rộng.\n- Viết code clean, có thể kiểm thử, hiệu quả và bảo trì tốt.\n- Định hướng kỹ thuật, code review, và hỗ trợ thành viên trong team backend.\n- Phối hợp với các team frontend, mobile, sản phẩm và QA để đảm bảo tiến độ và chất lượng dự án.\n- Đưa ra các quyết định kỹ thuật quan trọng, định hướng công nghệ phù hợp cho dự án.\n- Quản lý, phân chia công việc và theo dõi tiến độ của nhóm backend.\n- Đào tạo, mentoring và phát triển năng lực cho các thành viên junior.\n- Hỗ trợ, xử lý kỹ thuật trong quá trình bàn giao, sử dụng.\n- Đảm bảo hiệu suất, bảo mật và độ tin cậy của hệ thống backend.\n\nYêu cầu ứng viên:\n- Hiểu về quy trình phát triển phần mềm theo mô hình Agile Scrum.\n- Có từ hơn 4 năm kinh nghiệm phát triển backend, ưu tiên sử dụng một trong các ngôn ngữ: C#, Java, Python, NodeJS.\n- Hiểu biết sâu về kiến trúc microservices, RESTful API, WebSocket, GraphQL.\n- Thành thạo với cơ sở dữ liệu quan hệ (MySQL/PostgreSQL) và NoSQL (MongoDB/Redis).\n- Kinh nghiệm với CI/CD, Docker, Kubernetes, và các hệ thống triển khai thực tế.\n- Có hiểu biết tốt về các vấn đề liên quan đến bảo mật hệ thống backend.\n- Kinh nghiệm tối ưu hóa hiệu suất hệ thống và xử lý tải lớn là một lợi thế.\n- Lĩnh vực làm việc: ưu tiên ứng viên đã làm việc tại các công ty phần mềm giải pháp cho khách sạn, thương mại điện tử, ERP\n- Có khả năng học hỏi nhanh, luôn cập nhật các nghiệp vụ liên quan tới du lịch, khách sạn, tài chính là lợi thế.\n- Có kinh nghiệm dẫn dắt team từ 3–5 người trở lên là lợi thế.\n- Kỹ năng giao tiếp rõ ràng, truyền đạt ý tưởng mạch lạc với cả team kỹ thuật lẫn non-tech.\n- Có khả năng phân tích và ra quyết định kỹ thuật nhanh, chính xác.\n- Tư duy logic, trách nhiệm cao, chủ động và cầu tiến trong công việc.\n\nQuyền lợi:\n- Mức thu nhập 28-33 triệu gross, thỏa thuận khi phỏng vấn.\n- Cơ hội phát triển, khẳng định chính mình và thăng tiến cực lớn, trở thành nhà quản lý chỉ sau 2 - 3 năm\n- Văn phòng đẹp nhất, sáng tạo và thân thiện với môi trường do chính những thế hệ trẻ của Apec kiến tạo nên\n- Hoạt động nội bộ (du lịch, team building,...)\nThưởng lễ tết, thưởng quý, thưởng cuối năm, lương tháng thứ 13+++\n- Có cơ hội được tham gia một số dự án đã và đang phát triển của p.CNTT:\n- Hệ thống giao dịch thị trường chứng khoán trái phiếu, website bảng giá, Mobile App giao dịch cho nhà đầu tư.\n- Vận hành, phát triển các website công ty, các dự án.\n- Hệ thống ERP cho tập đoàn (Quản trị nhân sự, tuyển dụng, tính lương, giao việc, dự án).\n- Các ứng dụng quản trị, giao dịch khác trong tập đoàn: Bất động sản, nội thất, trái phiếu...\n- Hệ thống quản lý chuỗi khách sạn SmartHotel tích hợp eKYC, Payment, hệ thống quản lý kho phòng: Channel Manager, CRM, Loyalty, Booking.\n- Vận hành, phát triển hệ thống tài chính độc nhất tại Việt Nam và hệ thống giao dịch chứng khoán hiện đại bậc nhất Việt Nam.\n- Và nhiều dự án khác \n\nĐịa điểm làm việc:\n- Hà Nội: 117 Trần Duy Hưng, Trung Hòa, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:50)\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:20)\n- 2 ca làm việc được lựa chọn.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2539, 1365, 2, 'Thực Tập Sinh Lập Trình', 'Mô tả công việc\nBackend - NestJS hoặc .NET C#\n-Biết 1 backend framework là lợi thế (NestJS, ASP.NET Core...)\n-Hiểu mô hình REST API, HTTP method, status code\n-Có tư duy xử lý logic nghiệp vụ, thao tác database, tổ chức code rõ ràng\n\nFrontend Web - ReactJS\n-Biết ReactJS hoặc từng làm giao diện bằng HTML/CSS/JS\n-Có gu thẩm mỹ, hiểu cơ bản về UI/UX, bố cục layout hợp lý\n-Biết gọi API, xử lý dữ liệu là điểm cộng\n\nFrontend Mobile - React Native\n-Biết React Native cơ bản, hiểu layout đa nền tảng (Android/iOS)\n-Biết debug, test trên thiết bị thật hoặc giả lập\n-Không yêu cầu publish Store, chỉ cần từng làm app thử\n\nƯu tiên: Ứng viên có sử dụng thiết bị Mac (Macbook/iMac) để hỗ trợ nhóm build/test iOS. Vui lòng ghi rõ trong CV nếu có\n\nYêu cầu ứng viên\nYêu cầu bắt buộc - Ưu tiên ứng viên có nền tảng tốt và tư duy rõ ràng\n-Tư duy lập trình tốt: biết phân tích bài toán, viết code rõ ràng, có logic, biết debug đúng cách.\n-Có kiến thức cơ bản và nghiêm túc với ngành lập trình:\n-Biến, kiểu dữ liệu, hàm, vòng lặp, đệ quy, con trỏ, tham trị/tham chiếu\n-Cấu trúc dữ liệu & giải thuật: mảng, danh sách, stack, queue, hash map, sắp xếp, độ phức tạp Big-O\n-Cơ sở dữ liệu - SQL & T-SQL: SELECT, JOIN, GROUP BY, index, stored procedure, trigger, transaction\n-Kiến thức hệ thống & mạng: mô hình OSI, HTTP/HTTPS, request-response, status code...\n-Sử dụng Git: commit, branch, pull, merge cơ bản\n-Có khả năng đọc hiểu tài liệu tiếng Anh kỹ thuật\n-Tinh thần học hỏi nghiêm túc, chủ động cải thiện sau mỗi lần review\n\nƯu tiên (không bắt buộc):\n-Đã làm đồ án chỉn chu (có GitHub càng tốt)\n-Từng tham gia cuộc thi lập trình, giải thuật, hoặc sự kiện công nghệ\n-Có sản phẩm cá nhân nhỏ, project nhóm hoặc freelance thật\n\nQuyền lợi\nHỗ trợ thực tập: 1.500.000đ/tháng\n-Lộ trình thực tập 4-6 tháng giúp đủ thời gian làm quen quy trình, phát triển kỹ năng, và sẵn sàng chuyển lên thử việc/chính thức\n-Khi được đánh giá lên chính thức: Ký hợp đồng lao động và được tham gia đầy đủ chế độ BHXH, BHYT, thuế TNCN theo quy định\n-Được hướng dẫn bài bản bởi senior, thực chiến với sản phẩm thật\n-Không chấm công cứng - chỉ cần đảm bảo tiến độ và tinh thần nghiêm túc\n-Tham gia các hoạt động nội bộ: meeting, onboarding, happy hour\n-Cung cấp thư xác nhận thực tập, dấu mộc công ty nếu cần cho nhà trường\n-Không gian làm việc yên tĩnh, đầu tư chỉn chu\n-Cơ hội phát triển và mở rộng vai trò nếu mong muốn\n-Ưu tiên tham gia dự án công ty hoặc đào tạo chéo nếu có mong muốn học thêm\nĐịa điểm làm việc\n- Hồ Chí Minh: 86/11 Ngô Chí Quốc, P. Bình Chiểu, Thủ Đức\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 09:00 đến 18:00)\nThứ 2 – Thứ 7: 09:00 – 18:00 (nghỉ trưa 1 tiếng)\nLưu ý: Thứ 7 có thể linh hoạt thời gian.\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2540, 1268, 2, 'Senior Full Stack Developer - Odoo', 'Mô tả công việc\n- Phát triển các hệ thống phần mềm dành cho doanh nghiệp như CRM, HRM, IoT, MES... dựa trên nền tảng Odoo.\n- Tham gia toàn diện vào vòng đời phát triển phần mềm: từ khảo sát yêu cầu, thiết kế giải pháp hệ thống, phát triển tính năng, kiểm thử cho đến bảo trì sau triển khai.\n- Tùy biến và xây dựng các mô-đun Odoo đảm bảo đúng nghiệp vụ, tối ưu về hiệu suất và khả năng mở rộng cho tương lai.\n- Thiết kế, phát triển API (REST/XML-RPC) để tích hợp Odoo với ứng dụng di động, thiết bị IoT và các nền tảng bên ngoài.\n- Làm việc chủ yếu với cơ sở dữ liệu PostgreSQL; có hiểu biết về các hệ quản trị khác là một lợi thế.\n- Đảm bảo hệ thống vận hành ổn định trên môi trường điện toán đám mây (ưu tiên AWS), tối ưu hiệu năng để phục vụ lượng lớn người dùng và thiết bị.\n- Xây dựng mã nguồn có thể tái sử dụng, phát triển thư viện dùng chung nội bộ và chuẩn hóa quy trình lập trình dự án.\n- Chủ động tìm hiểu, cập nhật công nghệ mới nhằm cải tiến chất lượng phần mềm và tối ưu hóa các quy trình DevOps, CI/CD.\n\nYêu cầu ứng viên\n- Ít nhất 3 năm làm việc với Odoo.\n- Có kinh nghiệm làm việc với PostgreSQL, hiểu về indexing, optimization, data modeling.\n- Hiểu cơ bản về HTML, CSS, JavaScript; biết tùy chỉnh giao diện Odoo là lợi thế.\n- Từng triển khai hệ thống Odoo trên môi trường AWS/Cloud.\n- Có kinh nghiệm thiết kế API tích hợp giữa Odoo và hệ thống bên ngoài.\n- Ưu tiên: Có hiểu biết hoặc từng làm việc với IoT, hệ thống streaming, Biết DevOps, CI/CD, Docker là điểm cộng lớn.\n- Kỹ năng làm việc nhóm tốt, chủ động và linh hoạt trong môi trường Agile/Scrum.\n\nQuyền lợi\n- Mức lương cạnh tranh, thỏa thuận theo kinh nghiệm/năng lực;\n- Thời gian làm việc: Thứ Hai – Thứ Sáu, thời gian làm việc linh hoạt;\n- Thử việc hưởng 100% lương, được trang bị công cụ làm việc theo chính sách của công ty;\n- Môi trường làm việc trẻ trung, năng động, tài năng;\n- Được đánh giá review lương định kì 6 tháng/lần;\n- Thưởng ngày Lễ/Tết, thưởng KPI, thưởng dự án;\n- Được khám sức khỏe định kỳ;\n- Du lịch/nghỉ mát cùng công ty hàng năm;\n- Các chế độ khác theo quy định của pháp luật.\n\nĐịa điểm làm việc\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Từ Thứ 2 đến Sáng Thứ 7\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2541, 1366, 2, 'Java Developer Lead', 'Mô tả công việc\n- Phát triển, triển khai và duy trì các ứng dụng web sử dụng Java và các framework liên quan.\n- Tham gia vào quá trình thiết kế, phát triển và kiểm thử các thành phần của ứng dụng.\n- Hợp tác với nhóm phát triển và các bên liên quan để thu thập yêu cầu và đưa ra giải pháp.\n- Sử dụng và quản lý mã nguồn thông qua Git.\n- Đảm bảo hiệu suất và duy trì sự hoạt động của các hệ thống.\n- Tham gia đào tạo, hướng dẫn đội ngũ Fresher\n- Quản lý và đảm bảo hiệu quả công việc của team backend\n- Thực hiện các công việc theo yêu cầu của Manager\n\nYêu cầu ứng viên\n- Có ít nhất 4 năm kinh nghiệm làm việc với Java\n- Có kinh nghiệm xây dựng ứng dụng với Springboot\n- Có tư duy giải thuật tốt, hiểu biết về ORM, RESTful, OOP\n- Có kinh nghiệm làm việc với SQL (MySQL, PostgreSQL...): thiết kế, truy vấn, tối ưu....\n- Sẵn sàng học hỏi và đáp ứng nhanh các yêu cầu của dự án.\n- Có kinh nghiệm làm việc với Git, Maven, Redis.\n- Nắm chắc trong xử lý Caching, Queue\n- Có kinh nghiệm phát triển các dự án phần mềm về tài chính, bảo hiểm, ngân hàng là một lợi thế.\n- Có khả năng quản lý công việc, quản lý thời gian tốt, Tiếng Anh cơ bản trở lên.\n- Kinh nghiệm làm việc nhóm, quản lý đội nhóm\n- Ưu tiên sử dụng Laptop cá nhân (có trợ cấp)\n\nTốt nếu có:\n- Có kinh nghiệm về bảo mật dữ liệu (OAuth2, OIDC, OWASP, SAST, DAST,...), kinh nghiệm về Modern protocol (MQTT, WebSocket, RPC,...).\n- Có kinh nghiệm về xử lý tối ưu xử lý dữ liệu, dữ liệu lớn.\n- Có kinh nghiệm với Logging (ELK) và Monitoring (Grafana, Prometheus).\n- Có kinh nghiệm trong việc nâng cao hiệu suất ứng dụng (Performance test - JMeter, Profilers).\n- Có kinh nghiệm làm việc với các dịch vụ Cloud (AWS, Azure)\n- Có kinh nghiệm với các công cụ CI/CD (GitlabCI, ArgoCD...) và triển khai (Docker, K8s).\n- Có hiểu biết về các API Gateway (KONG API...).\n\nQuyền lợi\n- Mức lương cạnh tranh thỏa thuận theo năng lực và kinh nghiệm, upto 35M (Middle - Senior)\n- Review hiệu quả công việc: 1-2 lần/1 năm.\n- Môi trường trẻ, năng động, có nhiều cơ hội phát triển bản thân.\n- Được đào tạo về kỹ năng công nghệ, các kỹ năng mềm, các kỹ năng quản lý dự án,...\n- Nghỉ Thứ 7, Chủ nhật, 12 ngày phép/năm\n- Khám sức khỏe định kỳ 1 năm 1 lần\n- Các hoạt động thể thao, văn hóa đa dạng: CLB đá bóng, cầu lông,...\n- Hưởng đầy đủ các chế độ theo quy định pháp luật (BHXH, BHYT, BHTN) và công ty (nghỉ mát, team building, sinh nhật,...)\n- Địa chỉ công ty: Gần Đại học Công nghiệp Hà Nội\n\nĐịa điểm làm việc\n- Hà Nội: Số 92 Liền kề 22, KĐT Vân Canh, Hoài Đức\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:45)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2542, 1298, 2, 'Lập Trình Viên .NET', 'Mô tả công việc:\n- Tham gia vào giai đoạn thiết kế phần mềm\n- Lập trình, phát triển các phần mềm trên nền Webform APS.NET (C#), ADO.NET Entity Framework, .NET Core, Bootstrap CSS framework, MVC4 / 5, MVVM, WCF, WebAPI, Angular, ReactJS, NextJS, Micro Service\n- Sử dụng thành thạo các công cụ: Visual Studio.NET, IIS, MS SQL Server, Oracle Database, Crystal Report, Visual Studio Code\n- Có khả năng thiết kế cơ sở dữ liệu\n- Phát triển các báo cáo sử dụng Crystal Report, Microsoft Report, T-SQL, PL/SQL\n- Cài đặt, triển khai phần mềm trên môi trường của khách hàng. Hiểu biết về kiến trúc hệ thống.\n- Tham gia hỗ trợ tổ chức đào tạo, hỗ trợ người dùng trong quá trình chạy UAT và vận hành.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm lập trình trên .NET.\n- Ưu tiên ứng viên có kinh nghiệm với .Net Core, ReactJS, NextJS.\n- Trình độ Đại học chuyên ngành CNTT hoặc tương đương.\n- Có kinh nghiệm làm theo phương thức agile scrum and waterfall.\n- Ưu tiên ứng viên có kinh nghiệm làm việc theo quy trình CMMI.\n\nQuyền lợi:\n- Lương: 12.000.000 - 25.000.000 (tùy theo level).\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30.\n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Nghỉ phép: 12 ngày/năm.\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN cho 100% cán bộ sau thời gian thử việc.\n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Thu nhập: lương tháng 13; thưởng theo dự án, thưởng theo kết quả kinh doanh và mức độ đóng góp; thưởng theo năng lực và mức độ hoàn thành công việc của từng thành viên – đánh giá hàng tháng và trả thưởng theo quý; thưởng các ngày lễ lớn.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n- Các hoạt động giao lưu bóng đá, golf, văn nghệ...\n- Chính sách đào tạo về chuyên môn, nghiệp vụ và kỹ năng cho nhân viên. Hỗ trợ 100% kinh phí học và thi các chứng chỉ chuyên môn.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 22 tòa nhà Viwaseen, số 48 Tố Hữu, Trung Văn, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2543, 72, 2, 'Flutter Developer Leader', 'Mô tả công việc\nPhát triển ứng dụng:\n- Chịu trách nhiệm phát triển các tính năng mới và duy trì ứng dụng FPT Medicare/ HiFPT hiện có trên nền tảng iOS và Android bằng Flutter.\n- Tham gia vào việc thiết kế kiến trúc ứng dụng, đảm bảo tính ổn định, khả năng mở rộng và hiệu năng cao.\n- Viết code chất lượng cao, dễ đọc, dễ bảo trì và tuân thủ các tiêu chuẩn coding của công ty.\n\nNghiên cứu và áp dụng công nghệ:\n- Nghiên cứu, thử nghiệm và áp dụng các công nghệ mới nhất liên quan vào dự án.\n- Đề xuất các giải pháp kỹ thuật sáng tạo để giải quyết các vấn đề phức tạp trong quá trình phát triển.\n\nTích hợp và kiểm thử:\n- Tích hợp các thư viện, SDK của bên thứ ba (ví dụ: SDK camera, SDK IoT) vào ứng dụng.\n- Thực hiện kiểm thử đơn vị (unit test), kiểm thử tích hợp (integration test) và kiểm thử giao diện người dùng (UI test) để đảm bảo chất lượng sản phẩm.\n- Phối hợp với bộ phận kiểm thử (QA) để xác định và sửa lỗi.\n\nHợp tác và giao tiếp:\n- Quản lý tasks công việc, làm việc chặt chẽ với các thành viên khác trong nhóm (designer, product manager, backend developer) để đảm bảo dự án được hoàn thành đúng thời hạn và đạt chất lượng cao.\n- Tham gia vào các buổi họp nhóm để chia sẻ kiến thức, kinh nghiệm và đưa ra các giải pháp.\n- Báo cáo tiến độ công việc thường xuyên cho cấp trên.\n- Thực hiện các nhiệm vụ khác theo yêu cầu của cấp trên, phù hợp với năng lực và kinh nghiệm.\n\nYêu cầu ứng viên\n- Học vấn: Tốt nghiệp Đại học trở lên chuyên ngành Khoa học máy tính, Kỹ thuật phần mềm hoặc các ngành liên quan.\n- Kinh nghiệm: Ít nhất 03 năm kinh nghiệm phát triển ứng dụng di động bằng Flutter.\n- Am hiểu phát triển ứng dụng iOS bằng Swift/Objective C.\n- Ưu tiên ứng viên có kinh nghiệm triển khai và quản lý 1 nhóm nhỏ nhân sự Mobile Dev.\n- Kỹ năng chuyên môn: Sử dụng thành thạo Flutter framework.\n- Am hiểu về Swift/ Objective C.\n- Hiểu sâu về các widget, layout, animation, state management trong Flutter.\n- Có kinh nghiệm xây dựng UI/UX phức tạp và tùy biến giao diện theo yêu cầu.\n- Kiến trúc và Design Patterns:\n- Có tư duy logic tốt, hiểu biết về cấu trúc dữ liệu, thuật toán, design pattern (ví dụ: Singleton, Factory, Observer, MVVM, BLoC).\n- Nắm vững các nguyên tắc Clean Architecture, MVVM, SOLID principles.\n- Có khả năng tổ chức code rõ ràng, dễ đọc, dễ bảo trì và có khả năng tái sử dụng cao.\n- Có kinh nghiệm kết nối client-server sử dụng các giao thức webservice, MQTT, RESTful, JSON, REST API.\n- Có kinh nghiệm làm việc với push notification (Firebase Cloud Messaging), maps (Google Maps, Mapbox), multimedia (video, audio), WebRTC.\n- Biết tích hợp các dịch vụ của Google (Firebase, Google Analytics, Google Play Services), Facebook (Facebook Login, Facebook SDK).\n- Thành thạo về Material Design, custom layout là một lợi thế.\n- Biết sử dụng các công cụ hỗ trợ lập trình: Git (Github, Gitlab, Bitbucket), IDE (Android Studio, VS Code).\n- Có kinh nghiệm làm việc với quy trình Agile/Scrum.\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh chuyên ngành.\n- Có tinh thần học hỏi, chủ động nghiên cứu và cập nhật các công nghệ mới.\n- Kỹ năng giao tiếp tốt, có khả năng trình bày ý tưởng rõ ràng và thuyết phục.\n- Có khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Nhiệt tình, trách nhiệm cao trong công việc và có khả năng chịu áp lực tốt.\n\nQuyền lợi\n- Gói thu nhập cạnh tranh, hấp dẫn, tương xứng với năng lực và kinh nghiệm.\n- Thưởng lương tháng 13, thưởng hiệu suất làm việc, thưởng nghỉ mát.\n- Đầy đủ các chế độ bảo hiểm theo luật lao động Việt Nam (Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp).\n- Chính sách phúc lợi đa dạng: Chăm sóc sức khỏe định kỳ hàng năm, gói bảo hiểm sức khỏe chuyên biệt FPT Care (khám chữa bệnh miễn phí tại tất cả các bệnh viện).\n- Các hoạt động tri ân, chăm lo đời sống tinh thần cho CBNV và người thân.\n- Chế độ nghỉ phép năm, nghỉ lễ theo quy định.\n- Được tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn và kỹ năng mềm. Nhiều cơ hội phát triển và thăng tiến trong công việc.\n- Môi trường làm việc thân thiện, cởi mở, năng động, sáng tạo và chuyên nghiệp.\n- Đồng nghiệp nhiệt tình, sẵn sàng hỗ trợ.\n- Cơ sở vật chất và công cụ làm việc hiện đại, tiện nghi.\n- Văn hóa doanh nghiệp đặc sắc, sinh động bậc nhất với nhiều hoạt động hấp dẫn: Tân binh, Teambuilding, Hội diễn Sao Chổi, Sinh nhật công ty, các sự kiện ngày lễ...\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Quận 7\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2544, 1131, 2, 'SQL Developer (Oracle – Middle/Senior)', 'Mô tả công việc:\n- Phát triển và tối ưu các truy vấn SQL, stored procedures, packages trên Oracle.\n- Thực hiện ETL, xử lý dữ liệu lớn phục vụ báo cáo và phân tích.\n- Phối hợp với các bộ phận liên quan (BA, Dev, Data) để triển khai giải pháp dữ liệu.\n- Đảm bảo hiệu năng, tính toàn vẹn và bảo mật dữ liệu.\n- Tham gia review code, chia sẻ kinh nghiệm (đối với ứng viên senior).\n\nYêu cầu ứng viên:\n- Có từ 3 năm kinh nghiệm trở lên trong vai trò SQL Developer, làm việc với Oracle PL/SQL.\n- Thành thạo viết và tối ưu các truy vấn SQL phức tạp.\n- Có hiểu biết về kiến trúc cơ sở dữ liệu Oracle, indexing, performance tuning.\n- Có kinh nghiệm xử lý dữ liệu lớn và các quy trình ETL.\n- Tư duy logic, kỹ năng phân tích và giải quyết vấn đề tốt.\n- Có tinh thần học hỏi, chủ động trong công việc.\n\nQuyền lợi:\n- Mức lương cạnh tranh.\n- Lương tháng 13.\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop.\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN).\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau.\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật.\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc.\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban.\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến.\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm.\n- Làm việc với tác đối tác lớn.\n- Review tăng lương định kỳ hàng năm (1 lần / năm).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2545, 1367, 2, 'Backend Developer (.Net/NodeJS)', '• Phát triển và tối ưu hóa hệ thống backend cho các ứng dụng web, mobile; • Xây dựng APl, đảm bảo hiệu suất và bảo mật; • Làm việc với cơ sở dữ liệu SQL/ NoSQL, tối ưu truy vấn; • Hỗ trợ triển khai và vận hành hệ thống; • Phối hợp với team Frontend, QA, BA để đảm bảo yêu cầu và chất lượng sản phẩm; • Nghiên cứu, áp dụng công nghệ mới vào dự án.\n\n• Kinh nghiệm: Tối thiểu 1 năm lĩnh vực lập trình; • Trình độ tiếng Anh: Toeic > 600; • Kỹ năng: Thành thạo NET hoặc Node.js, có tinh thần chủ động, trách nhiệm cao; • Kinh nghiệm dự án: Ưu tiên ứng viên đã tham gia các dự án từ 5 thành viên trở lên; • Kiến thức bổ trợ: Ưu tiên hiểu biết về Cloud, Security, Network (thông qua dự án thực tế hoặc chứng chỉ), sử dụng Al tools trong công việc.\n\nMức lương: 10-18M; • Thưởng hiệu quả công việc; • Các chế độ ngày phép, BHXH, BHYT, BHTN… theo quy định của pháp luật lao động hiện hành; • Cơ hội được học hỏi, làm việc với công nghệ mới; • Hỗ trợ tham gia các khóa đào tạo nâng cao kiến thức và kỹ năng; • Môi trường làm việc năng động, nhiều thử thách và cơ hội thăng tiến; • Tham gia các hoạt động teambuilding.\n\nĐịa điểm làm việc: - Hà Nội\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2546, 1368, 2, 'PHP Developer', 'Mô tả công việc\n- Tham gia vào quá trình phát triển sản phẩm cho khách hàng, bao gồm từ các công đoạn research, làm requirement, design, coding, test, operation.\n- Loại hình dự án: Các hệ thống web-application (sử dụng ngôn ngữ PHP NodeJS,...).\n- Kỹ thuật sử dụng: MySQL, PHP Laravel, AWS.\n\nYêu cầu ứng viên\nKỹ năng bắt buộc:\n- Có từ 04 năm kinh nghiệm trở lên với ngôn ngữ PHP (Laravel).\n- Thành thạo RDB hoặc NoSQL (MongoDB).\n- Thao tác tốt với HTML, CSS, JavaScript, Bootstrap, JSON, XML,...\n- Có kiến thức và khả năng làm việc với công nghệ Frontend (NextJS).\n- Có kinh nghiệm làm việc với Cloud như AWS, Azuze, GCP.\nTốt hơn nếu có:\n- Có kinh nghiệm thiết kế hệ thống theo Microservices là một lợi thế.\n- Có kinh nghiệm về DevOps, CI-CD.\n- Có kinh nghiệm xử lý các bài toán liên quan tới Real time services.\n\nKỹ năng khác:\n- Chủ động trong công việc, chủ động trong giao tiếp và raise vấn đề khi cần thiết.\n- Có khả năng tự học, có khả năng phát hiện vấn đề và đưa ra phương án giải quyết.\n- Có khả năng training member.\n- Có khả năng leadership, có ý thức trách nhiệm cao, có tinh thần làm việc teamwork.\n- Có kinh nghiệm outsource cho khách hàng Nhật.\n\nQuyền lợi\nCơ hội phát triển\n- Làm việc, học hỏi và phát triển cùng đồng nghiệp là những kỹ sư trẻ tài năng, đam mê và có lý tưởng lớn.\n- Được tham gia các chương trình training về kỹ năng công nghệ và kỹ năng mềm, phương pháp làm việc (Agile, Scrum...).\n- Được tư vấn và chia sẻ về phát triển năng lực và nghề nghiệp bản thân.\nChế độ đãi ngộ\n- Lương: Thỏa thuận theo năng lực.\n- Thưởng: Lên đến 15 tháng lương/năm, bao gồm:\n  - Bonus cố định: 01 tháng lương (tương ứng với thời gian làm việc trong kỳ đánh giá).\n  - Performance Bonus (Dựa theo kết quả; Performance review): 2 lần/năm.\n  - Thưởng tổng kết doanh thu năm, thưởng nhân viên tiêu biểu tháng.\n- Du lịch năm, team building tháng (200k/người), tổ chức sinh nhật tháng, Trung thu,...\n- Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n- Khám sức khỏe định kỳ hàng năm tại bệnh viện uy tín.\n- Văn phòng rộng rãi, trang thiết bị hiện đại, môi trường làm việc mở.\n\nĐịa điểm làm việc\n- Đà Nẵng: 130 Nguyễn Tư Giản, Mỹ An, Ngũ Hành Sơn, Ngũ Hành Sơn.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2547, 165, 2, '.NET Developer (Product Team)', 'Mô tả công việc\n- Đóng góp vào việc phát triển sản phẩm KiotViet KAT;\n- Làm việc với các thành viên team và phòng ban khác trong việc triển khai yêu cầu nghiệp vụ;\n- Phát triển và bảo trì các tính năng back-end và front-end cho hệ thống nhiều người dùng;\n- Debug và fix các vấn đề kỹ thuật trong codebase hiện có;\n- Tham gia vào việc tối ưu hóa code để cải thiện performance hệ thống;\n- Hỗ trợ triển khai công nghệ và giải pháp mới vào sản phẩm;\n- Viết code clean, dễ bảo trì theo tiêu chuẩn của team;\n- Tham gia vào các hoạt động testing và quality assurance;\n- Viết documentation cho code và quy trình phát triển.\n\nYêu cầu ứng viên\n1. Học vấn và kinh nghiệm\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc các ngành liên quan;\n- Từ 3 năm kinh nghiệm phát triển phần mềm với công nghệ .NET.\n2. Yêu cầu kỹ thuật\n- Có kiến thức làm việc với C#, .NET Core, ASP.NET / ASP.NET Core;\n- Kinh nghiệm với các ORM như Entity Framework hoặc Dapper;\n- Hiểu biết về khái niệm và triển khai RESTful API;\n- Kinh nghiệm làm việc với database SQL (MS SQL, PostgreSQL):\n- Viết query cơ bản\n- Hiểu biết về thiết kế database schema\n- Tối ưu hóa performance cơ bản\n- Làm quen với hệ thống message queue (RabbitMQ, Kafka)\n- Kiến thức cơ bản về cơ chế caching (Redis)\n- Hiểu biết về coding best practices và design patterns;\n- Kinh nghiệm với unit testing và công cụ debugging;\n- Kiến thức cơ bản về công cụ monitoring và logging;\n- Quen thuộc với hệ thống version control (Git)\n- Có kinh nghiệm sử dụng AI coding tools và assistants (Cursor, GitHub Copilot, Claude, v.v.) để nâng cao hiệu suất trong phát triển phần mềm là một lợi thế.\n3. Kỹ năng mềm\n- Tư duy logic và khả năng giải quyết vấn đề;\n- Mong muốn học hỏi công nghệ và concepts mới;\n- Kỹ năng giao tiếp tốt;\n- Khả năng làm việc hiệu quả trong môi trường team;\n- Kỹ năng quản lý thời gian và tổ chức;\n- Có khả năng tiếp thu tốt.\n\nQuyền lợi\n- Mức lương khởi điểm đứng đầu thị trường, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm;\n- Làm việc từ Thứ 2 – Thứ 6, giờ làm việc linh hoạt;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\n- Chăm sóc sức khỏe: Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\n- Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2 đến thứ 6. Làm việc 8 tiếng/ngày và checkin linh hoạt trong khung từ 08h - 09h\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2548, 1226, 2, 'Unity Developer (Casual/Puzzle) - Junior/Middle', '- Participate in developing Game projects (Casual/Puzzle) on the Unity platform\n- Coordinate and discuss with team members to build, complete and optimize the game\n- Contribute ideas and content to improve product quality\n- Job details will be discussed specifically if the CV meets the requirements.\n\nYêu cầu ứng viên\nKnowledge:\n- Graduated from University majoring in IT or related fields\n- Good programming thinking, proficient in C# programming language\n- Have at least 1 year of experience working with Unity; know how to work with XCode and Android Studio\n\nSkill:\n- Proficient in Unity, especially experienced in handling issues such as: Animation, Effect, Particle, optimization\n- Skilled in planning Game development, able to work under high pressure\n- Good teamwork and independent work.\n\nAttitude:\n- Ability to work in a customer-centric and team-oriented environment, detail-oriented\n- Positive, proactive, responsible in work, and have passion for Games\n- Diligent, eager to learn, enthusiastic, with a strong growth mindset and a passion for self-development\n- Commitment to long-term engagement with the company\n- Quick adaptability to work, able to handle pressure\n- Ability to work in a fast-paced environment.\n\nQuyền lợi\nINCOME\n- Salary: Up to $1500\n- Opportunities for professional development and growth.\n- Receive 100% of fixed salary, salary increase according to company regulations\n- Official employee lunch allowance: 1,000,000 VND/month\n- Income based on results and work performance\n\nDEVELOPMENT OPPORTUNITIES\n- Expand and improve professional knowledge and skills\n- Real-life experience at global projects\n- Have a clear, personalized career development roadmap\n\nWORKING ENVIRONMENT\n- Experience a dynamic, professional international environment\n- Enjoy 100% daily life care benefits\n\nWELFARE POLICY\n- The company pays all types of insurance according to the provisions of law (social insurance, health insurance, unemployment insurance, etc.)\n- Free periodic general health check-ups at hospitals: Hong Ngoc, Thu Cuc, Vinmec.\n- Wedding/filial piety benefits, holiday/New Year gifts and other benefits.\n- New Year bonus, March 8, April 30 - May 1, Mid-Autumn Festival, mid-year, September 2, October 20, Christmas.\n- Share achievements continuously, without limits based on performance.\n- Working hours:\nFrom Monday - Friday. Closed Saturday, Sunday\nMorning: 8:30 - 12:00, Afternoon: 13:00 - 18:00, tea-break 15:00 - 15:30.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2549, 1369, 2, 'Lập Trình Viên BackEnd PHP/Laravel', 'Mô tả công việc:\n- Phát triển và bảo trì hệ thống backend bằng PHP và Laravel.\n- Thiết kế, tối ưu cơ sở dữ liệu và API phục vụ frontend.\n- Hỗ trợ và phối hợp với đội frontend để xây dựng các tính năng mới.\n- Tối ưu hiệu suất hệ thống, xử lý lỗi và nâng cao bảo mật.\nYêu cầu ứng viên:\n- Thành thạo PHP, HTML, CSS, JavaScript, jQuery, Bootstrap.\n- Ít nhất 2 năm kinh nghiệm làm việc với Laravel.\n- Có kinh nghiệm làm việc với cơ sở dữ liệu MySQL hoặc PostgreSQL.\n- Hiểu biết về RESTful API, WebSocket là một lợi thế.\n- Có kinh nghiệm làm việc với dữ liệu lớn, biết phân tích hệ thống.\n- Có kinh nghiệm làm việc với các hệ thống bán hàng, CRM là một lợi thế.\n- Khả năng làm việc nhóm tốt, tư duy logic và giải quyết vấn đề.\nQuyền lợi:\n- Phụ Cấp ăn trưa\n- Hỗ trợ thiết bị làm việc\n- BHXH/BHYT theo quy định của nhà nước\n- Thưởng cuối năm theo tình hình kinh doanh của công ty\n- Môi trường làm việc năng động thân thiện\n- Đồng nghiệp vui vẻ hoà đồng\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lầu 3, 3A, Phổ Quang, Phường 02, Tân Bình, Tân Bình\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Thứ 7 (từ 09:00 đến 17:00)\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2550, 165, 2, '.NET Developer', '1. Nhiệm vụ chính:\n- Tham gia cùng team thiết kế và làm rõ yêu cầu tính năng người dùng theo mô hình ATDD\n- Xây dựng chức năng của sản phẩm bao gồm back-end và front-end cho hệ thống, đảm bảo chất lượng code cũng như yêu cầu nghiệp vụ và hiệu năng hệ thống.\n- Giải quyết các vấn đề khó về tối ưu hệ thống cũng như nghiệp vụ người dùng.\n- Nghiên cứu các giải pháp, công nghệ mới để cải tiến sản phẩm.\n- Làm việc cùng các vai trò khác trong feature team để đạt mục tiêu chung của sản phẩm.\n\n2. Cơ hội phát triển:\n- Làm việc với hệ thống hàng triệu user, với một lượng lớn giao dịch và truy vấn.\n- Công nghệ đa dạng và hệ thống code base lớn, bạn có cơ hội rèn dũa / training nâng cao kỹ năng software craftsmanship để đảm bảo chất lượng, hiệu suất tốt, trải nghiệm người dùng và khả năng tái sử dụng tốt hơn.\n- Cùng với các bài toán về kỹ thuật cũng như sản phẩm thử thách và thú vị, cũng là cơ hội để phát triển tư duy giải quyết vấn đề và thiết kế hệ thống tốt hơn, theo cách đơn giản và tinh tế nhất có thể.\n- Career path rõ ràng cho lộ trình phát triển và trưởng thành của thành viên.\n\n1. Học vấn, kiến thức và trình độ chuyên môn: Tốt nghiệp đại học chuyên ngành CNTT\n2. Kinh nghiệm:\n- Có kinh nghiệm với Asp.net MVC, Web API\n- Có năng lực kinh nghiệm làm việc với design pattern, clean code.\n3. Những kỹ năng cần thiết cho công việc\n- Có kỹ năng C#.NET 4.0/4.5, OOP, Design Pattern, IoC\n- Có kiến thức nền tảng và kinh nghiệm về:: JQuery, Typescript, HTML5/CSS3, HTML/XHTML/XML,CSS, Bootstrap, IIS\n- Có hiểu biết về các công nghệ Redis, Realtime\n- Có hiểu biết Database, SQL Server, Queue Messaging, Front end framework (Angular, React)…\n- Có khả năng học hỏi nhanh, tích cực và chủ động trong công việc. Khả năng làm việc độc lập và làm việc nhóm tốt.\n\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả lên đến 3 tháng lương/năm.\n- Thưởng dự án, thưởng quý;\n- Làm việc từ Thứ 2 – Thứ 6, ca làm việc linh hoạt;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc.Lộ trình phát triển công việc rõ ràng;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...);\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, du lịch hàng năm;\n- Làm việc trong môi trường trẻ trung, năng động\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nChấm công linh hoạt từ 8:00-9:00 đến 17:30-18:30\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2551, 1370, 2, 'Middle IOS Developer', 'Never settle, think bigger. Vulcan Labs is a leading mobile application development company based in Ho Chi Minh City, Vietnam, with flexibility for some remote work. Since 2017, we have published over 30 game and mobile applications with several hundred thousand Daily Active Users and over 10 million downloads combined. Our products on iOS App Store and Android include Camera Translator: Translate+, Face Story - AI Photo Editor, and TV Cast & Screen Mirroring. We welcome individuals from diverse backgrounds to join our team and embrace challenges in a fast-changing industry.\nAs an iOS Developer in our team, you will:\n- Do research to turn ideas into products on the iOS platform.\n- Implement designs and prototypes to build world-class applications on the IOS platform to deliver the best market products.\n- Study new APIs and frameworks with regard to the capability to apply for market products.\n\nMust have:\n- Strong background in computer science.\n- Concurrency and networking management in iOS.\n- Strong knowledge of Programming algorithms and data structures\n- Strong knowledge of project architectures like MVVM or VIPER\n- Having experience in iOS Applications (at least 3 years).\n- Deep knowledge of the latest trends in software engineering best practices – code reviews, code quality, CI/CD, monitoring, multi-threading, and memory management.\n\nGood to have experience on:\n- RxSwift, Combine.\n- Firebase, Google Cloud platform.\n- SwiftPM, CocoaPods, Carthage.\n- StoreKit, StoreKit2\n- Realm, SQLite.\n\nWhy do you love working here?\n- SALARY & BONUS: Additionally to the 13th-month salary, you will have an attractive remuneration package including KPI bonuses and hot rewards for each project. \n- BEING A GREAT CULTURE: You will participate in the development team of top chart applications globally at a cool office with young and friendly talents with a global approach.\n- CHALLENGE YOURSELF: You have an opportunity to work with cutting-edge technology: Virtual Reality, Augmented Reality, and Artificial Intelligence, and challenge your career path.\n- NO BARRIERS: You are independent to give ideas and design innovative products to serve millions of global users and products will stand on top of technological trends.\n- OTHER BENEFITS: We have so many events such as company trips, team building, birthday parties, year-end parties, and team bonding every month.\n\nĐịa điểm làm việc: Hồ Chí Minh: 11 13 15 Đ. Số 7, An Lợi Đông, Quận 2\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2552, 1271, 2, 'Senior Java Developer', 'Mô tả công việc:\n- Tham gia phát triển các dự án mảng Tài chính số (Viettel Pay, ví cá nhân, ví doanh nghiệp, ...). Cung cấp sản phẩm ứng dụng thanh toán và chuyển tiền với số lượng giao dịch rất lớn, đòi hỏi hiệu năng xử lý cao\n- Tham gia làm rõ nghiệp vụ, thiết kế giải pháp, phát triển nâng cấp hệ thống theo yêu cầu\n- Tham gia review thiết kế, review code, tối ưu hệ thống đáp ứng lưu lượng truy cập cao\n- Nghiên cứu áp dụng công nghệ mới nâng cao chất lượng, tối ưu nguồn lực phát triển\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học loại Khá trở lên, chuyên ngành Công nghệ thông tin, Kỹ sư phần mềm. Đặc biệt ưu tiên các trường Học viện Công nghệ Bưu chính Viễn thông, Đại học Bách khoa Hà Nội, ...\n- Tiếng Anh tương đương 650+ TOEIC\n- Ít nhất 05 năm kinh nghiệm phát triển các sản phẩm/dự án xây dựng bằng ngôn ngữ Java\n- Thành thạo Java Core, các framework Java như EE, Spring, Struts, Hibernate ... và một số design pattern thông dụng\n- Tư duy về thiết kế hướng đối tượng và nắm vững kiến thức về cấu trúc dữ liệu và giải thuật, lập trình hướng đối tượng ...\n- Thành thạo SQL, PLSQL, có kiến thức về các hệ quản trị cơ sở dữ liệu Oracle/MySQL, noSQL, có khả năng tối ưu CSDL\n- Ưu tiên có hiểu biết về nghiệp vụ tài chính, có kinh nghiệm về microservices, ham học hỏi tìm tòi sáng tạo cái mới\n\nQuyền lợi:\n- Thời gian làm việc: 8h00 - 17h30 từ thứ 2 tới thứ 6\n- Địa điểm làm việc: Làm việc tại tòa nhà văn phòng hạng A cao nhất Thủ đô – Keangnam Landmark 72, Phạm Hùng, Nam Từ Liêm, Hà Nội\n- Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn\n- Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel\n- Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm\n- Cơ hội tiếp xúc với các dự án lớn, mới mẻ & tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam\n- Cơ hội thăng tiến rõ ràng với nhiều cấp bậc\n- Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn\n- Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời.\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người\n- Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,...\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày\n- Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2553, 1160, 2, 'Junior AI Agent Developer', 'We\'re looking for a Junior AI Agent Developer interested in exploring and building intelligent agents powered by AI. This role involves hands-on research, prototyping, and implementation of AI-driven agents, with direct mentorship from experienced team members. You\'ll grow your AI skills and contribute directly to meaningful projects.\n\n- Research and experiment with AI-driven agents using popular frameworks and tools such as LangChain, Hugging Face, and OpenAI APIs.\n- Build and prototype intelligent agents capable of basic autonomous interactions.\n- Collaborate with senior team members and engineers to integrate AI agents into Bitcover’s products.\n- Document experiments, findings, and technical solutions clearly.\n- Stay current with AI trends and proactively suggest new ideas and approaches.\n\n**Yêu cầu ứng viên**\n*Required*\n- Bachelor\'s degree or final-year student in Computer Science, Data Science, AI, or related field.\n- Good programming skills in Python.\n- Basic knowledge of Machine Learning fundamentals, Natural Language Processing, and conversational AI.\n- Experience from personal projects, internships, or academic coursework involving AI or software development.\n- Strong willingness to learn and adapt quickly.\n*Preferred*\n- Experience with cloud platforms (AWS, Azure, Google Cloud) is a plus but not required.\n- Familiarity with vector databases (Pinecone, Chroma, Weaviate) and embedding techniques.\n- Prior participation in hackathons, coding contests, or AI-related competitions.\n*Ideal Characteristics*\n- Curious and passionate about emerging AI technologies.\n- Self-motivated, proactive, and eager for growth opportunities.\n- Adaptable, resourceful, and comfortable working in a startup environment.\n- Good communication and collaboration skills.\n\n**Quyền lợi**\n- Opportunity to build hands-on experience in AI development.\n- Direct mentorship from senior team members.\n- Flexible working conditions (Hybrid/Remote options).\n- Dynamic and innovative startup environment.\n\n**Địa điểm làm việc**\n- Hồ Chí Minh: Tân Bình\n\n**Thời gian làm việc**\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\n**Cách thức ứng tuyển**\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Tân Bình', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2554, 1337, 2, 'Java BackEnd Developer', 'Mô tả công việc:\n- Phát triển, tối ưu các chức năng hệ thống backend theo sự phân công và định hướng từ PM hoặc Leader.\n- Tham gia phân tích nghiệp vụ, phân rã chức năng, phân tích hệ thống, kiểm thử logic và trải nghiệm, sửa lỗi, triển khai hệ thống.\n- Chịu trách nhiệm về chất lượng và hiệu quả code của các module được giao. Đảm bảo sản phẩm backend ổn định, hiệu suất tốt và dễ bảo trì.\n- Hợp tác chặt chẽ với các team liên quan (FE, QA, BA, DevOps...) để đảm bảo tiến độ và chất lượng sản phẩm.\n- Tham gia vào quy trình kiểm thử, fix bugs, triển khai và bảo trì hệ thống.\n- Chủ động tìm hiểu nghiệp vụ và tham gia đề xuất cải tiến sản phẩm.\n- Hỗ trợ các thành viên junior khi cần và có thể review code nếu được giao.\n- Báo cáo tiến độ, vấn đề, kết quả công việc đến quản lý trực tiếp.\n- Trải nghiệm sản phẩm định kỳ để hiểu hành vi người dùng, từ đó đưa ra các đề xuất cải tiến.\n\nYêu cầu ứng viên:\n1. Kiến thức bắt buộc:\n- Có tối thiểu 02 năm kinh nghiệm tương đương.\n- Thành thạo ngôn ngữ lập trình Java và lập trình hướng đối tượng (OOP).\n- Có kinh nghiệm làm việc với hệ quản trị cơ sở dữ liệu RDBMS, NoSQL, có khả năng viết, tối ưu truy vấn, phân tích dữ liệu.\n- Có hiểu biết về các Framework Spring Boot, Vert.x, Microservice.\n- Hiểu rõ mô hình backend MVC và các khái niệm RESTful API.\n- Có kinh nghiệm triển khai hệ thống trên môi trường production, biết cách vận hành và giám sát hệ thống.\n- Có khả năng sử dụng AI trong lập trình.\n\nKiến thức nâng cao (lợi thế):\n- Biết sử dụng các ngôn ngữ lập trình khác: PHP, Python, Shell-script, Jenkin, HAProxy.\n- Kỹ năng làm việc theo quy trình JIRA, Agile, SCRUM.\n- Có hiểu biết về UI/UX, hành vi người dùng là một điểm cộng.\n\n2. Kỹ năng:\n- Problem solving: Có khả năng phân tích vấn đề, tìm giải pháp kỹ thuật phù hợp.\n- Design thinking: Có tư duy xây dựng giải pháp tối ưu, hướng đến trải nghiệm người dùng.\n- Giao tiếp, làm việc nhóm, lắng nghe và truyền đạt thông tin.\n- Học hỏi và tự học tốt; Tổ chức và quản lý thời gian.\n\n3. Tố chất:\n- Tư duy logic.\n- Tư duy hệ thống.\n- Tỉ mỉ, cẩn thận.\n\nQuyền lợi:\n3 Lý do bạn chọn TP Entertainment:\n1 là bạn có cơ hội phát triển bản thân thần tốc:\n- Môi trường TP Entertainment luôn phát huy hết điểm mạnh và khả năng sáng tạo của bạn, nhờ đó bạn có cơ hội được tỏa sáng.\n- Được làm việc và hướng dẫn trực tiếp bởi Leader giàu kinh nghiệm.\n2 là bạn có cơ hội tăng thu nhập không giới hạn:\n- Những đóng góp của bạn luôn được công ty ghi nhận rõ ràng nhờ đó thu nhập của bạn được cải thiện nhanh chóng và không giới hạn.\n3 là môi trường làm việc lý tưởng:\n- Văn hóa công ty đậm đà sâu sắc với 4 giá trị cốt lõi: Hiệu quả, sáng tạo, lấy khách hàng là trung tâm, nhân văn.\n- Làm việc tại công ty công nghệ hàng đầu về Mobile app với môi trường trẻ trung, năng động, thân thiện, sáng tạo.\n- Du lịch hàng năm, dã ngoại hàng quý cùng người thân (4 lần/năm).\n- Ngoài ra bạn được hưởng các chính sách đãi ngộ của công ty như:\n- Trợ cấp ăn trưa (Khi trở thành thân viên thử việc).\n- Hưởng đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định của nhà nước (Khi là nhân viên chính thức).\n- Khám sức khỏe định kỳ hàng năm.\n- Trà chiều, hoa quả, sữa bánh.\n- Tham gia các hoạt động vui chơi thể thao hàng ngày tại công ty.\n- Thử việc 02 tháng hưởng 100% mức lương chính thức.\n- Review lương 2 lần/năm.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 2 tháp A, Toà nhà Rivera Park, 69 Vũ Trọng Phụng, P. Thanh Xuân Trung, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2555, 1371, 2, 'Android Developer', 'Mô tả công việc\n- Tham gia thực hiện thiết kế, xây dựng và triển khai ứng dụng android mobile\n- Nghiên cứu tìm hiểu những công nghệ mới nhất, giải pháp tốt nhất cho sản phẩm và người dùng\n- Phát triển các ứng dụng trên nền tảng Android, cải thiện tốc độ, hiệu quả và mở rộng ứng dụng\n\nYêu cầu ứng viên\n- Biết sử dụng Jira, Github, Bitbucket\n- Kiến thức cơ bản và tư duy về Kotlin, lập trình Android, lập trình hướng đối tượng\n- Có kinh nghiệm làm việc với Kotlin là lợi thế lớn.\n- Có kinh nghiệm với Thread, Handler, Rxjava, Coroutines, and scheduling techniques\n- Có kinh nghiệm với Android patterns as MVP, MVVM, Clean architecture, Android Architecture\n- Hiểu biết về CI/CD là điểm cộng, Firebase (FCM / Cloud Storage / Realtime Database).\n\nQuyền lợi\n- Lương NET hàng tháng + thưởng (Thưởng quý, thưởng dự án)\n- Lương thỏa thuận theo năng lực, đảm bảo cạnh tranh với thị trường.\n- Thưởng hiệu suất theo quý, năm, thưởng mặc định tháng 13. Lương tháng 14 theo hiệu quả kinh doanh\n- Review lương 2 lần/năm\n- Môi trường làm việc trẻ trung, năng động, nhiều cơ hội thăng tiến.\n- Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty\n- Cấp thiết bị làm việc (tại công ty hoặc tại nhà tuỳ yêu cầu của nhân sự).\n- Tham gia các sự kiện lớn trong và ngoài nước do các đối tác: Google, Facebook, Tiktok... tổ chức\n- Du lịch, Teambuilding, Sự kiện, Khám sức khỏe thường niên 100% ngân sách công ty chi trả (Không bắt buộc tham gia).\n- Thiết bị giải trí đa dạng tại văn phòng: Bida, Bóng bàn, PS5, Gameboard...\n- Quà tặng các dịp lễ, tết, hoặc các dịp kỷ niệm năm làm việc, sinh nhật...\n- Pantry đầy đủ hoa quả, bánh kẹo, đồ uống, trà, cafe,... free.\n\nĐịa điểm làm việc\n- Thừa Thiên Huế\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:15 đến 17:45)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2556, 1142, 2, 'Intern/Fresher .NET (Willing To Work With Forguncy)', 'We are looking for passionate and proactive Intern Developers to join our dynamic team. You will participate in real-world projects, receive mentorship from senior developers, and gain hands-on experience with web development technologies.\n\nFamiliar with VB.NET (experience is a big plus).\nWilling to learn and work with Forguncy (we will provide training).\nAble to write and understand JavaScript.\nSolid understanding of Databases: creating databases/tables, writing/editing SQL queries, and optimizing SQL performance.\nBasic knowledge of web development concepts (client-server, HTML/CSS/JS, etc.).\nKnowing Japanese is a plus (not mandatory).\nEagerness to learn, good teamwork, and problem-solving attitude.\n\nWorking in a dynamic and professional environment with many opportunities for advancement. The company provides equipment such as LAPTOP, Phones to serve the working needs of all employees. The company pays all costs of social insurance, health insurance, and unemployment insurance for employees. Join Health and Accident Insurance package 24/7 (according to seniority). Enjoy benefits according to seniority. Being trained in foreign languages, and sponsored to study certificates to improve professional skills and soft skills. Opportunity to go Onsite at SPLUS JAPAN (requires Japanese level of N3 or higher). Performance evaluation: 2 times/year. Clubs: Football, Music, ... Annual company trip, quarterly teambuilding, employee birthdays in the month, and special events of the year (8/3, 20/10, Mid-Autumn Festival, Christmas...). Annual leave: 12 vacation days, 11 holidays a year. Company trip, quarterly teambuilding, birthdays for employees in the month and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas ...). Annual holiday: 12 days of annual leave. TET bonus fund (1-3 months’ salary) according to the results of the work and the business situation of the company.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Internship', '2025-10-07 20:59:18.149534'),
	(2557, 1372, 2, 'Kỹ Sư ME (Tiếng Trung)', 'Mô tả công việc:\n- Vận hành, bảo dưỡng, gỡ lỗi máy móc\n- Đưa ra các phương án cải tiến chất lượng sản phẩm\n\n- Các dòng máy trong công ty : \n+ Máy CNC: FANUC, OUKELANG\n+ Máy đột dập AOTU\n+ Máy PVD, máy làm sạch hydrocacbon, mạ và xử lý bề mặt kim loại\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng trở lên\n- Kinh nghiệm 2 năm trở lên trong lĩnh vực gia công kim loại\n- Giao tiếp tiếng Trung\n\nQuyền lợi:\n- Công ty mới thành lập, tuyển cán bộ nguồn, có nhiều cơ hội phát triển \n- Mức lương thỏa thuận, ĐẢM BẢO HẤP DẪN theo năng lực, ưu tiên ứng viên có thể đi làm sớm\n- Hưởng đầy đủ các chính sách phúc lợi theo quyền lợi nhân sự chính thức: BHYT, BHXH, nghỉ phép năm và các thưởng khác nếu có\n\nĐịa điểm làm việc:\n- Bắc Ninh: KCN Yên Phong 2C, Yên Phong\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nỨng viên có thể tăng ca hoặc làm ca đêm\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2558, 165, 2, 'Lập Trình Viên .Net - Senior', 'Tham gia phát triển sản phẩm phần mềm quản lý bán hàng Kiotviet;\nPhối hợp các phòng ban khác trong phân tích nghiệp vụ, phát triển và triển khai sản phẩm;\nXây dựng chức năng của sản phẩm cho hệ thống tầm 300K người sử dụng;\nGiải quyết các vấn đề khó về tối ưu hệ thống cũng như nghiệp vụ người dùng;\nNghiên cứu các giải pháp, công nghệ mới để cải tiến sản phẩm;\nTối ưu hóa hiệu suất hệ thống và xử lý các vấn đề kỹ thuật phức tạp;\nTham gia vào quá trình code review và mentoring các thành viên có level thấp hơn trong team;\nThực hiện các công việc liên quan khác được giao.\n\nYêu cầu ứng viên\nHọc vấn, kiến thức và trình độ chuyên môn:\nTốt nghiệp đại học chuyên ngành CNTT.\nKinh nghiệm:\nCó ít nhất 3 năm kinh nghiệm ở vị trí tương đương là lợi thế;\nNhững kỹ năng cần thiết cho công việc;\nYêu cầu kỹ thuật:\nCó ít nhất 3 năm kinh nghiệm phát triển phần mềm sử dụng công nghệ .NET, NET Core;\nThành thạo C#, .NET Core, ASP.NET và các framework liên quan;\nKinh nghiệm làm việc với các ORM như Entity Framework, Entity Framework Core, Dapper;\nHiểu biết sâu về RESTful API và kiến trúc microservices;\nKinh nghiệm làm việc với cơ sở dữ liệu MSSQL và MongoDB;\nKinh nghiệm với hệ thống messaging như RabbitMQ, Kafka;\nHiểu biết về caching (Redis) và công nghệ realtime (MQTT, Websocket)\nThực hành tốt về Coding Principles, Clean Code, Design Patterns và Unit Testing;\nCó kinh nghiệm làm việc với hệ thống có tải cao là một lợi thế;\nCó các kỹ năng debugging và troubleshooting: phân tích giải quyết các vấn đề kỹ thuật;\nCó kinh nghiệm sử dụng các công cụ monitoring và logging như Grafana, ELK, APM, OpenTelemetry;\nKỹ năng mềm:\nKhả năng học hỏi nhanh và tư duy giải quyết vấn đề tốt;\nKỹ năng làm việc nhóm và giao tiếp hiệu quả;\nChủ động, có trách nhiệm và khả năng làm việc độc lập;\nKỹ năng quản lý thời gian và ưu tiên công việc hiệu quả;\nKhả năng mentoring và hướng dẫn các thành viên level thấp hơn;\nQuan hệ công việc ( Bên trong công ty, bên ngoài công ty).\n\nQuyền lợi\nMức lương khởi điểm đứng đầu thị trường, tương xứng với năng lực và kinh nghiệm làm việc;\nThưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm;\nLàm việc từ Thứ 2 – Thứ 6, giờ làm việc linh hoạt;\nĐược hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\nThưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\nChăm sóc sức khỏe: Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\nLàm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\nĐược cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\nCơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 18:30)\nGiờ check in checkout link hoạt từ 8:00-9:00 đến 17:30-18:30\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2559, 1373, 2, 'Kỹ Sư Lập Trình Đứng Máy Phay CNC', 'Mô tả công việc\n- Lập trình gia công trên phần mềm CAM (Mastercam, NX, Powermill, hoặc phần mềm khác tùy theo yêu cầu).\n- Vận hành, cài đặt, chỉnh sửa chương trình gia công trên máy CNC (phay, tiện).\n- Đọc và hiểu bản vẽ kỹ thuật, bóc tách yêu cầu gia công, lựa chọn dao cụ và phương pháp gia công tối ưu.\n- Kiểm tra, đánh giá chất lượng sản phẩm sau gia công, điều chỉnh chương trình hoặc gá đặt nếu cần.\n- Bảo trì, bảo dưỡng định kỳ máy CNC, đảm bảo máy hoạt động ổn định.\n- Hỗ trợ các bộ phận liên quan trong việc cải tiến quy trình gia công nhằm nâng cao năng suất, chất lượng sản phẩm.\n- Thực hiện các công việc khác theo yêu cầu của cấp trên.\n\nYêu cầu ứng viên\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Cơ khí, Chế tạo máy, Cơ điện tử hoặc liên quan.\n- Có kinh nghiệm từ 1-3 năm lập trình, vận hành máy CNC (chấp nhận ứng viên có ít kinh nghiệm nhưng có nền tảng tốt).\n- Thành thạo phần mềm lập trình CAM (Mastercam, NX, Powermill...) và phần mềm thiết kế CAD (SolidWorks, AutoCAD...).\n- Hiểu biết về các loại vật liệu gia công (nhôm, thép, inox, nhựa kỹ thuật…).\n- Kỹ năng đọc bản vẽ kỹ thuật, sử dụng các dụng cụ đo cơ khí chính xác (thước cặp, panme, đồng hồ so…).\n- Có tinh thần trách nhiệm, cẩn thận, chủ động trong công việc.\n- Ưu tiên ứng viên có kinh nghiệm làm việc trong ngành gia công cơ khí chính xác.\n\nQuyền lợi\n- Lương: Thoả thuận theo năng lực, có thưởng theo hiệu suất công việc.\n- Thời gian tăng ca được tính phụ cấp tăng ca, công ty chi trả tiền ăn trưa và ăn ca.\n- Được làm việc trong môi trường chuyên nghiệp, có cơ hội học hỏi và phát triển.\n- Được đào tạo nâng cao kỹ năng lập trình, vận hành máy CNC.\n- Hưởng đầy đủ chế độ theo quy định của công ty và pháp luật: BHXH, BHYT, BHTN.\n- Thưởng các ngày lễ, tết, lương tháng 13.\n\nĐịa điểm làm việc\n- Hà Nội: CN1, Minh Khai, Bắc Từ Liêm, Bắc Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:20)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2560, 1211, 2, 'Unity Developer Intern', 'Mô tả công việc:\n- Tham gia vào các dự án game của công ty.\n- Chuyển thể các thiết kế của Game Artist và Game Design thành các chức năng của game.\n- Thiết kế, xây dựng và duy trì Code hiệu quả, có thể tái sử dụng và đáng tin cậy.\n- Làm việc theo hướng dẫn và phân công của leader.\nYêu cầu ứng viên:\n- Sinh viên năm thứ 4 - 5 các trường đại học chính quy ngành Công nghệ thông tin hoặc tương đương\n- Yêu cầu đi làm tối thiểu 8 buổi/tuần.\n- Có kinh nghiệm lập trình C#.\n- Tư duy logic tốt, ham học hỏi và sẵn sàng trải nghiệm những thử thách mới\n- Ưu tiên có kinh nghiệm về Unity, hoặc đã nghiên cứu về Unity.\nQuyền lợi:\n- Cơ hội lên chính thức sau thực tập.\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Hỗ trợ cơm trưa, tea-break,...\n- Hỗ trợ đóng dấu thực tập.\n- Du lịch, team building: 3 lần/năm.\n- Môi trường làm việc vô cùng sáng tạo, năng động, được thoải mái chơi các trò chơi tại công ty: bida, PS, board game,...\n- Thời gian làm việc: 8:15 - 17:45 (7,5 giờ/ngày; thứ Hai - thứ Sáu)\nĐịa điểm làm việc:\n- Hà Nội: Tòa nhà Rivera Park, 69 Đ. Vũ Trọng Phụng, Thanh Xuân.\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:45).\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2561, 1374, 2, 'Kỹ Sư Lập Trình Nhúng Vi Điều Khiển', '• Phát triển phần mềm nhúng sử dụng các nền tảng vi xử lý của Microchip, ST, NXP …\n• Tham gia vào tất cả các giai đoạn phát triển phần mềm từ phân tích yêu cầu, thiết kế, triển khai, kiểm tra hệ thống;\n• Thực hiện các công việc được quản lý phân công.\n\n• Tốt nghiệp Đại học loại Khá trở lên các chuyên ngành Cơ điện tử, Điện tử - Viễn thông, Điện - tự động hóa, CNTT, Kỹ thuật máy tính;\n• Tốt nghiệp Đại học loại Khá trở lên các chuyên ngành Cơ điện tử, Điện tử - Viễn thông, Điện - tự động hóa, CNTT, Kỹ thuật máy tính;\n• Tiếng Anh: TOEIC từ 550 trở lên hoặc tương đương;\n• Kỹ năng:\n- Thành thạo C/C++; có kiến thức về các ngôn ngữ C#/Python là một lợi thế;\n- Hiểu biết về các giao thức truyền thông (I2C, SPI, UART);\n- Kinh nghiệm làm việc với các vi điều khiển và vi xử lý;\n- Hiểu biết về kiến trúc ARM, SoC, ...\n- Quản lý mã nguồn: Sử dụng Git để quản lý và phối hợp công việc;\n- Debugging: Sử dụng các công cụ như GDB, các công cụ phân tích bộ nhớ;\n- Kỹ năng làm việc nhóm và giao tiếp hiệu quả;\n\n+ Thu nhập hấp dẫn, xứng đáng với năng lực, thưởng theo hiệu quả công việc.\n+ Được làm việc trong Công ty sản xuất hàng đầu Việt nam với quy mô lớn (1.000 người); có bề dày lịch sử và văn hóa truyền thống với 2 lần được Đảng + Nhà nước phong tặng “Anh hùng lực lượng vũ trang nhân dân”.\n+ Có cơ hội được đào tạo nâng cao nghiệp vụ thường xuyên. Được cung cấp các trang thiết bị hiện đại cần thiết để nâng cao hiệu quả làm việc.\n+ Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.\n+ Được làm việc trong môi trường năng động, hiệu quả, nhiều hoạt động văn hóa sôi nổi quan tâm đến đời sống tinh thần của nhân viên và nhiều cơ hội để phát triển nghề nghiệp cho bản thân.\n\n- Hà Nội: An Khánh, Hoài Đức\n- Hà Nội: Khu CNC Hòa Lạc, Thạch Thất\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 đầu tiên của tháng\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hoài Đức, Thạch Thất', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2562, 1288, 2, '.NET Dev (C#,ASP.Net MVC,SQL)', 'Mô tả công việc\n- Tham gia phát triển và tối ưu hệ thống phần mềm EasyInvoice trên nền tảng .NET MVC.\n- Phối hợp với các bộ phận BA, Tester, UI/UX để phân tích yêu cầu và triển khai tính năng mới.\n- Xây dựng, cải tiến các module như: chấm công, tính lương, hợp đồng điện tử, bảo hiểm xã hội, KPI...\n- Xử lý dữ liệu lớn, tối ưu truy vấn SQL và hiệu năng hệ thống.\n- Tham gia cải tiến kiến trúc theo hướng dịch vụ (Service-Oriented), tích hợp với Redis, RabbitMQ.\n- Làm việc theo mô hình Agile/Scrum, đảm bảo tiến độ và chất lượng phần mềm.\n\nYêu cầu ứng viên\n- Kinh nghiệm: từ 6 tháng - 1 năm kinh nghiệm .Net\n- Có kiến thức về HTML/CSS và JS.\n- Có tư duy tốt về thiết kế và phát triển hệ thống\n- Có phát triển hệ thống hướng dịch vụ là một lợi thế\n- Có kinh nghiệm về thiết kế, turning, giám sát SQL-Server.\nTech Stack\n- .NET MVC 5\n- Entity Framework\n- Web API, JSON\n- JQuery, JavaScript, HTML5/CSS3.\n- Đã làm việc với Redis, RabbitMQ, Windows Service là một lợi thế.\n- Đã làm việc với một framework ORM.\n\nQuyền lợi\n- Lương từ 8 - 15 triệu/tháng + trợ cấp\n- Có cơ hội thăng tiến cao, xét tăng lương 2 lần/năm\n- Làm việc tại Doanh nghiệp với sứ mệnh phụng sự xã hội, mang lại các sản phẩm, dịch vụ nhằm thay đổi năng suất cho các doanh nghiệp\n- Văn hóa trao đổi thẳng thắn, hỗ trợ tận tình; Sếp trẻ tâm lý, đồng nghiệp thân thiện\n- Làm việc trong môi trường chuyên nghiệp, năng động, nhiều cơ hội học tập, phát triển, và được hưởng đãi ngộ phù hợp với năng lực.\n- Lộ trình thăng tiến rõ ràng, có cơ hội trở thành nhân tố quan trọng và chủ chốt của công ty\n- Được hưởng các chế độ phúc lợi của công ty: thưởng lễ tết, nghỉ mát hàng năm, ...\n- Được hưởng hỗ trợ từ quỹ Công đoàn cơ sở: ốm đau, hiếu hỉ, sinh nhật, ...\n- Có cơ hội tham gia các khóa đào tạo, huấn luyện chuyên môn.\n- Du lịch công ty hàng năm.\n- Tham gia các hoạt động văn nghệ, thể thao cùng công ty: sinh nhật tháng, quý, ngày quốc tế phụ nữ, teabreak hang tuần, ..\n- Các chế độ BHXH, BHYT, nghỉ phép full lương theo quy định nhà nước.\n- Hỗ trợ các công cụ dụng cụ cần thiết để đáp ứng công việc.\n\nĐịa điểm làm việc\n- Hà Nội: Trụ sở chính: Nhà khách ATS, số 8 Phạm Hùng, Phường Mễ Trì, Nam Từ Liêm\n- Hà Nội: Cầu Giấy\n- Hồ Chí Minh: số H56, Phường Tân Thới Nhất, Đường Dương Thị Giang, Quận 12\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2563, 1359, 2, 'Lập Trình Viên Fullstack (Angular, Laravel, PHP)', 'Mô tả công việc\n- Tham gia bảo trì, tối ưu hóa hiệu năng và phát triển mở rộng hệ thống hiện có sử dụng Laravel và Angular.\n- Phối hợp với BA (Chuyên viên phân tích nghiệp vụ) và khách hàng để phân tích yêu cầu nâng cấp hệ thống.\n- Phát triển tính năng mới hoặc cải tiến các chức năng hiện tại theo yêu cầu và thiết kế kỹ thuật.\n- Làm việc chặt chẽ với các nhóm kiểm thử chất lượng (QC), DevOps và các nhóm phát triển khác để đảm bảo chất lượng mã nguồn, tính ổn định của hệ thống và tiến độ triển khai.\n- Tham gia sửa lỗi, đảm bảo hệ thống hoạt động ổn định trên môi trường thực tế.\n- Viết mã nguồn sạch sẽ, dễ bảo trì, và dễ kiểm thử theo các tiêu chuẩn và best practices hiện hành.\n- Góp phần vào các buổi thảo luận kỹ thuật, review mã nguồn, và định hướng kiến trúc hệ thống.\n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm làm việc với Laravel (PHP) và Angular (Angular.io).\n- Hiểu rõ về API RESTful, tích hợp frontend-backend, và các best practice trong phát triển web hiện đại.\n- Kiến thức vững chắc về lập trình hướng đối tượng (OOP), kiến trúc MVC, và các mẫu thiết kế phần mềm.\n- Tư duy logic, khả năng phân tích và giải quyết vấn đề hiệu quả.\n- Tính cách cẩn thận, siêng năng, chịu khó, và có thể theo đuổi các nhiệm vụ dài hạn một cách kiên trì.\n- Kỹ năng giao tiếp tốt, có thể phối hợp làm việc nhóm hiệu quả.\n- Ưu tiên (nice to have)\n- Có kinh nghiệm hoặc có khả năng đọc hiểu hệ thống backend Java, đặc biệt là Spring Boot.\n- Từng làm việc với hệ thống quy mô lớn, có lượng truy cập cao.\n- Thành thạo công cụ quản lý mã nguồn (Git) và theo dõi công việc (Jira, Trello...).\n- Có kinh nghiệm hoặc hiểu biết về quy trình CI/CD, DevOps.\n\nQuyền lợi\n- Mức lương và thưởng hấp dẫn\n- 12 ngày nghỉ phép năm\n- Được tham gia đầy đủ bảo hiểm xã hội và bảo hiểm y tế theo quy định của nhà nước\n- Các khoản phụ cấp hấp dẫn (thưởng onsite, gửi xe, sinh nhật, happy hours, v.v.)\n- Xét duyệt tăng lương hàng năm dựa trên hiệu suất và đóng góp của nhân viên\n- Môi trường làm việc thực sự cởi mở. Mọi người đều được tôn trọng và bạn có quyền tự do theo đuổi cũng như đạt được mục tiêu của mình\n- Các quyền lợi khác theo quy định của Bộ luật Lao động Việt Nam\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Capital Place 29 đường Liễu Giai, Ngọc Khánh, Ba Đình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2564, 1375, 2, 'Nhân Viên Lập Trình Phay, Tiện', '1. Mục tiêu công việc\nXây dựng, hiệu chỉnh chương trình gia công CNC chính xác cho các chi tiết cơ khí trên máy phay và tiện CNC, đảm bảo năng suất, chất lượng và an toàn.\n\n2. Nhiệm vụ chính\n- Lập trình gia công CNC cho máy phay và tiện theo bản vẽ kỹ thuật.\n- Xác định nguyên công gia công, chọn dao cụ, tốc độ cắt và chế độ cắt phù hợp.\n- Thiết lập quy trình gia công tối ưu, phối hợp với kỹ thuật vận hành để kiểm tra chương trình và hiệu chỉnh nếu cần.\n- Mô phỏng quá trình gia công trên phần mềm để phát hiện lỗi và cải thiện năng suất.\n- Hỗ trợ vận hành khi chạy thử chương trình mới, khắc phục lỗi chương trình thực tế.\n- Lưu trữ, quản lý và cập nhật hệ thống chương trình CNC theo mã sản phẩm.\n- Đảm bảo các yếu tố an toàn, tuân thủ quy trình vận hành và bảo mật dữ liệu lập trình.\n\n- Yêu cầu ứng viên\n- Trình độ học vấn: Cao đẳng hoặc Đại học chuyên ngành Cơ khí chế tạo, Cắt gọt kim loại, Tự động hóa, hoặc tương đương.\n- Kinh nghiệm:\n  - Tối thiểu 1–2 năm kinh nghiệm lập trình máy CNC.\n  - Ưu tiên ứng viên có kinh nghiệm lập trình đa trục hoặc gia công chi tiết phức tạp.\n- Kiến thức và kỹ năng:\n  - Am hiểu các loại dao cụ, vật liệu gia công, phương pháp gá đặt.\n  - Đọc hiểu bản vẽ kỹ thuật (2D, 3D), tiêu chuẩn dung sai, kỹ thuật đo lường.\n  - Kỹ năng làm việc nhóm, phối hợp với tổ vận hành và kỹ thuật.\n- Tư duy logic, cẩn thận, và chủ động trong công việc.\n\n- Quyền lợi\n- Mức lương: thỏa thuận theo năng lực.\n- Phụ cấp: Cơm trưa, xăng xe, chuyên cần, tăng ca.\n- Thưởng: Tháng 13, hiệu suất, sáng kiến (nếu có).\n- Chế độ: BHXH, BHYT, BHTN đầy đủ, nghỉ phép, nghỉ lễ.\n- Có cơ hội đào tạo nâng cao tay nghề, tham gia vào các dự án lớn.\n- Môi trường làm việc an toàn, chuyên nghiệp và ổn định lâu dài.\n- Có khu ở lại sạch sẽ nếu nhà xa.\n\n- Địa điểm làm việc\n- Hồ Chí Minh: 228/13/3 Nguyễn Thị Lắng, Ấp Phú Lợi, Xã Tân Phú Trung, Củ Chi.\n\n- Thời gian làm việc\nThứ 2 - Thứ 7 (từ 07:30 đến 17:00).\n\n- Cách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2565, 1376, 2, 'Mid-Level ReactJS Developer', 'Mô tả công việc:\n- Tham gia nghiên cứu và phát triển sản phẩm LMS, CRM, CMS\n- Làm việc theo sự phân công của Leader\n- Phối hợp giữa các nhóm để phát triển dự án\n- Tham gia các công đoạn tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu các dự án Web - Application\n- Thiết kế và triển khai API RESTful và tích hợp với các dịch vụ của bên thứ ba (VNPay, Facebook ads, Google ads...)\n\nYêu cầu ứng viên:\n- Thành thạo HTML/CSS.\n- Xử lý thành thạo React Hook, Redux, Redux toolkit.\n- Có kiến thức về Responsive Design.\n- Có kiến thức về CSR, SSR, Websocket.\n- Sử dụng các thư viện component (e.g. Material UI).\n- Hiểu về CSS Frameworks (e.g. Tailwind CSS) và Preprocessors (e.g. Sass, SCSS).\n- Làm việc hiệu quả với các công cụ quản lý version (e.g. gitlab).\n- Có kiến thức về RestAPI, WebSocket.\n- Thành thạo git, Github, Gitlab\n- Tư duy logic tốt.\n\nQuyền lợi:\n- Luôn được hướng dẫn tư duy Logic nghiệp vụ\n- Xét lương tối thiểu 1 năm 1 lần và không dưới 10%\n- Ngày nghỉ: 12 Ngày phép trong năm + Các ngày Lễ/ Tết, Thưởng tháng 13, Tham gia BHXH, Team building\n- Các buổi training chuyên sâu kỹ thuật/ kỹ năng mềm định kỳ\n- Các giải thể thao điện tử định kỳ\n- Hoạt động bóng đá mỗi thứ 5 hàng tuần\n- Team Building tối thiểu 1 lần/năm\n- Làm việc tại một môi trường thoải mái về đồng phục nhưng chuẩn mực về thái độ\n- Cạnh tranh tại đấu trường Mona E-Sport với các môn thể thao HOT như Counter Strike, PES, Fifa... cùng nhiều giải thưởng hấp dẫn\n- Hoạt động thể thao, nâng cao sức khỏe thông qua những trận banh siêu kinh điển mỗi tuần\n- Leader luôn tạo điều kiện học hỏi và phát triển thông qua các buổi Seminar, giúp nâng cao tay nghề, tư duy làm việc chuyên nghiệp\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 1073/23 Cách Mạng Tháng 8, Phường 7, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2566, 1377, 2, 'Lập Trình Viên Fresher (Tiếng Nhật)', 'Mô tả công việc:\n- Tham gia các dự án của công ty theo sự hướng dẫn của quản lý.\n- Phát triển phần mềm theo tài liệu được cung cấp.\n- Báo cáo tiến độ, chủ động đưa phương án xử lý khi gặp vấn đề & báo cáo với quản lý trực tiếp.\n- Tìm hiểu công nghệ mới để hỗ trợ dự án nếu cần.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học trong và ngoài nước chuyên ngành công nghệ thông tin hoặc các ngành liên quan.\n- Bắt buộc: trình độ tiếng Nhật N2 hoặc tương đương trở lên, có thể giao tiếp bằng tiếng Nhật.\n- Kinh nghiệm: không yêu cầu kinh nghiệm, chấp nhận các sinh viên mới hoặc chuẩn bị ra trường.\n- Nắm chắc kiến thức về lập trình một trong các ngôn ngữ thông dụng như .NET, JAVA, Python,...\n- Năng động, sáng tạo, có khả năng tự nghiên cứu. Có tinh thần trách nhiệm và khả năng làm việc độc lập & làm việc nhóm.\n\nQuyền lợi:\n- Thu nhập: Thỏa thuận theo năng lực, up to 15 triệu.\n- Xét tăng lương 1 lần/năm, mức thu nhập gia tăng theo năng suất và hiệu quả công việc, đóng góp thực tế vào dự án của công ty.\n- Thưởng cuối năm, thưởng sinh nhật và thưởng các ngày lễ khác.\n- Lộ trình thăng tiến rõ ràng và làm việc với các chuyên gia Nhật Bản (có cơ hội được làm việc onsite tại Nhật).\n- Được tham gia vào các buổi đào tạo, seminar hàng tháng để nâng cao kỹ năng công việc và cùng nhau chia sẻ: knowledge base, working experience, lessons learned, best practices...\n- Các chế độ theo quy định của pháp luật và phúc lợi đãi ngộ của công ty: BHXH, hiếu hỉ, ốm đau...\n- Chế độ lương làm thêm giờ (OT) theo đúng quy định của pháp luật.\n- Được tham gia vào các hoạt động teambuilding, du lịch thường niên, sinh nhật,...\n- Tham gia vào câu lạc bộ thể thao: cầu lông, bóng đá,...\n- Thời gian làm việc: từ thứ 2 đến thứ 6 (Nghỉ thứ 7, CN).\n- Môi trường làm việc trẻ và năng động, tôn trọng phát triển cá nhân, công bằng và luôn khuyến khích sáng tạo để phát huy tối đa năng lực.\n\nĐịa điểm làm việc:\n- Hà Nội: 48 Tố Hữu, Nam Từ Liêm, Trung Văn, Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2567, 1304, 2, 'Fullstack Developer', 'Mô tả công việc\n- Analyze the business specs then prepare technical specs and develop the new systems or enhance existing system for supporting business needs.\n- Support the team leader on technical analysis to provide the best technical solution as well as support colleagues for solving technical issues to complete the assigned projects / tasks on timely manner.\n- Investigate and answer daily inquiries on systems functional as well as problem encountered in order to resolve it in timely manner.\n- In charge of unit test on enhancements/ new development under responsibility to ensure developed modules are matched with business requirements.\n- Assist users/team leader on building test scripts to cover all test cases.\n\nYêu cầu ứng viên\n- IT technical analysis and programming: at least 3 years.\n- Good knowledge of an objective oriented language Java.\n- Good knowledge of web/application containers (Apache Tomcat, Jboss AS, IBM WebSphere …) and web/application deployment.\n- Good experience on SOAP and RESTful Web Services.\n- Good skill at MS SQL Server programming (stored procedure, function, job, trigger, view).\n- Good skill in database design, database management, particularly MS SQL.\n- Solid understanding of the software development life cycle, Agile Scrum.\n- Working knowledge of HTML5, CSS3, React, Flutter, and JavaScript a plus.\n\nQuyền lợi\n- Competitive salary and benefits.\n- Working time: 8:00AM - 05:30PM, Monday – Friday.\n- 12 days of annual leave + 3 days of sick leave + 1 day of birthday per year.\n- Participated in social insurance, unemployment insurance, health insurance and full policies according to the labor law.\n- 13th month salary & bonus policies, allowances at the Company.\n- UNIT-Care health care insurance by level.\n- Salary increases according to company regulations or unexpected salary raise in case of outstanding ability.\n- Professional and dynamic working environment, unlimited promotion opportunities.\n- Opportunity to participate in many large projects in Vietnam & abroad.\n- Work on the latest technology platform.\n- Join in company trip, teambuilding & community activities.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2568, 1282, 2, 'Nhân Viên Lập Trình .Net', 'Mô tả công việc\n- Lập trình và tích hợp (front-end và back-end);\n- Viết tài liệu mô tả chức năng phần mềm;\n- Xử lý phản hồi từ người dùng;\n- Nghiên cứu tối ưu hóa sản phẩm, dịch vụ đã phát triển; \n- Bảo trì và hỗ trợ các vấn đề liên quan đến chuyên môn.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành khác am hiểu về Lập trình\n- Có ít nhất 1 năm kinh nghiệm lập trình sử dụng công nghệ .NET Core (C#, ASP.NET Core, EF Core, LinQ, Restful API, WCF, SOAP)\n- Có kiến thức về Javascript, Typescript, HTML5/CSS3, Ajax, jQuery, React, Angular, Vue\n- Có kinh nghiệm với các công cụ build hiện đại (Docker, CI/CD,...).\n- Kinh nghiệm với các công cụ quản lý mã nguồn như Git, Gitlab\n- Database: SQL Server, Oracle, PostgreSQL;\n- Có khả năng research tài liệu và đọc tài liệu.\n- Có kinh nghiệm và sản phẩm là một lợi thế;\n- Có khả năng phân tích, sáng tạo, chịu được áp lực công việc; có tinh thần học hỏi, hợp tác trong công việc;\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực và kinh nghiệm. Xét tăng lương định kỳ hàng năm hoặc trước hạn theo tình hình đánh giá;\n- Được hưởng các chế độ BHYT, BHXH theo quy định của nhà nước; các chính sách phúc lợi của Công ty: Phép năm; Lương thưởng; Quà tết, thưởng lễ; Du lịch...\n- Làm việc trong môi trường chuyên nghiệp, trẻ trung, năng động, hòa đồng, phát huy tối đa khả năng chủ động sáng tạo của nhân viên;\n- Được trang bị đầy đủ trang thiết bị phục vụ công việc;\n- Được trau dồi kỹ năng về nghiệp vụ và kỹ năng mềm;\n- Được tham gia, đóng góp vào các dự án phát triển có quy mô lớn, lâu dài;\n- Thưởng theo thành tích làm việc.\n\nĐịa điểm làm việc\n- Hà Nội: 101 Láng Hạ, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2569, 1378, 2, 'Lead Software Engineer (Java/.Net)', '1. Lead the development of high-quality, impactful, and scalable products and systems to achieve business goals.\n2. Conduct system analysis, architecture design, and develop technical solutions based on project requirements, while producing corresponding technical documentation.\n3. Develop software applications using Java or .NET technologies.\n4. Collaborate closely with engineering managers and engineers across multiple platforms and domains.\n5. Support to recruit, develop, and retain exceptional engineering talent who excel in innovative, user-focused, fast-paced environments.\n6. Establish and maintain high engineering standards for your team regarding quality practices, delivery speed, architecture, design, and code quality, with clear measurable goals.\n7. Contribute to the improvement and scaling of the engineering organization by mentoring engineers, sharing technical knowledge, industry best practices, and leadership skills.\n\nYêu cầu ứng viên:\n1. Familiarity with J2EE or .Net.\n2. Familiarity with RDBMS (PostgreSQL, Oracle, MSSQL).\n3. Have experience with developing on Cloud Platform (GCP, AWS, Azure).\n4. Familiarity with Git, Docker, Kubernetes is a plus.\n5. Strong analytical and problem-solving skills.\nSoft skills:\n1. Has team collaboration awareness, able to work cooperatively with team members. Experience in Scrum is a plus.\n2. Good communication skills (English and Vietnamese) and logical thinking/judgment abilities.\n3. Proactive and self-motivated to learn.\n4. Possesses or is willing to learn multiple languages (Chinese) to effectively communicate with the team.\n\nQuyền lợi:\nFull social benefits in accordance with the company and the Vietnam Law.\nPremium health care & accident insurance.\nFriendly working environment with strong startup culture.\nTeam building, Company trip, Year-end party, etc.\n40 flexible working hours per week from Monday to Friday.\nSalary review at least one time per year based on employee\'s performance and contribution.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2570, 1379, 2, 'Lập Trình Viên', 'Mô tả công việc\n- Lead và bảo trì các dịch vụ dựa trên AI \n- Thiết kế, quản lý phát triển frontend và backend \n- Thiết kế giải pháp AI và định hướng kỹ thuật\n- Xây dựng và quản lý mạng nội bộ (Intranet) công ty\n- Thiết kế và phát triển hệ thống chat nội bộ\n\nQUY TRÌNH PHỎNG VẤN : Phỏng vấn từ xa và thông báo kết quả nhanh chóng\n\nYêu cầu ứng viên\n- Kinh nghiệm từ 3-5 năm trở lên\n- Có đam mê sâu sắc và kinh nghiệm thực tế với AI (mô hình AI, ChatGPT, Midjourney, Stable Diffusion, v.v.)\n- Hiểu biết tổng quát về phát triển web và ứng dụng (có thể sử dụng HTML, CSS, JavaScript, Python, v.v.)\n- Đã từng xây dựng hệ thống intranet và chat nội bộ\n- Có khả năng sử dụng đa dạng các ngôn ngữ lập trình chính (Java, C#, Ruby, v.v.)\n\nƯU TIÊN:\n- Thành thạo các framework như React, Node.js, Next.js\n- Có kinh nghiệm làm việc với các nền tảng đám mây (AWS, Azure, Google Cloud)\n- Đã từng dẫn dắt các dự án mã nguồn mở\n\nQuyền lợi\n- Mức lương: Thỏa thuận theo năng lực (25tr/tháng trở lên)\n- Chi trả bảo hiểm đầy đủ theo chính sách nhà nước.\n- Phụ cấp ăn trưa+ bonus % hoa hồng Video\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 19B Đường số 30, Phường An Khánh, Thủ Đức\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2571, 165, 2, 'Flutter Developer', 'Về KiotViet:\nSản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ.\nVới hơn 13 năm và hơn 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm.\nBạn sẽ làm gì:\n- Phát triển app Phần mềm quản lý bán hàng KiotViet trên nền tảng Flutter Cross-Platform (Android/iOS)\n- Phối hợp với team phát triển các tính năng mới theo Agile/Scrum\n- Thực hiện các nhiệm vụ khác liên quan đảm bảo tiến độ dự án\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng, đại học; ưu tiên tốt nghiệp chuyên ngành CNTT hoặc chuyên ngành liên quan\n- Có từ 3 năm kinh nghiệm với Mobile, trong đó  kinh nghiệm Flutter từ 2 năm, native từ 01 năm\n- Bạn có kiến thức về MVP, MVVM, hiểu biết về Clean Architecture là một lợi thế\n- Bạn có kiến thức Bloc + Cubit (optional), Domain driven design\n- Ưu tiên có kinh nghiệm coding tool (AI coding tool: Cursor/ Github copilot/ Windsurf)\n- Có tinh thần học hỏi, chủ động trong công việc và có kỹ năng quản lý sắp xếp công việc và thời gian tốt\n\nQuyền lợi:\n- Mức lương khởi điểm cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả làm việc lên đến 2 tháng lương, Thưởng cuối năm;\n- Làm việc từ Thứ 2 – Thứ 6, checkin linh hoạt trong khung từ 08h-09h\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\n- Chăm sóc sức khoẻ : Khám sức khoẻ định kỳ hàng năm, Bảo hiểm sức khoẻ cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\n- Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc:\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm, Hoàn Kiếm\n\nThời gian làm việc:\nThứ 2 - Thứ 6, làm việc 8 tiếng/ngày và checkin linh hoạt trong khung 8h-9h\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2572, 220, 2, 'Chuyên Viên Phát Triển Phần Mềm', '- Tham gia phân tích, thiết kế, phát triển và bảo trì các hệ thống phần mềm phục vụ lĩnh vực y tế như: HIS, LIS, RIS, EMR/EHR, Quản lý bệnh viện,...;\n- Tích hợp với các hệ thống phụ trợ và các bên thứ 3;\n- Tối ưu hiệu năng, bảo mật và độ tin cậy của hệ thống phần mềm;\n- Vá lỗi, xây dựng và nâng cấp các module theo yêu cầu nghiệp vụ;\n- Cập nhật các công nghệ mới phục vụ cho việc cải tiến phần mềm và đáp ứng các yêu cầu quản lý Y tế số;\n- Thực hiện các công việc khác theo phân công của Quản lý trực tiếp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2573, 1380, 2, 'Unity Developer (Sub Leader)', 'Mô tả công việc\n\n・Develop and deploy 3D Unity apps on Mobile, PC, and supported devices.\n・Build and optimize applications on devices.\n・Coordinate directly with members (GD, Artist, Tester,...) to ensure outstanding product quality.\n・Fix bugs, improve features, optimize App performance on devices (tracking, rendering, interaction and UI/UX).\n・ Participate in detail design and basic design for features/modules.\n・ Write and update technical documents.\n・ Analyze business requirements, propose appropriate technical solutions.\n・Mentoring and guiding Junior/Fresher members in the team.\n\nYêu cầu ứng viên\n\n■Requirements:\n- At least 3 years of experience in developing Unity engine\n- Proficiency in Unity 3D programming, Csharp or C++ or C\n- Mastery of OOP, Design Patterns, data structures, algorithms and software architecture design\n- Know how to optimize 2d/3d apps in terms of capacity, RAM, CPU, Resources.\n- Experience working with:\nAnimation of Unity\nShader/Shader Graph, AssetBundles...\nUnderstanding of Particle System/3D modeling/Lighting/Texturing\nAbility to work with all aspects of application development including UI, animation...\nAbility to write maintainable code, focusing on performance, reusability and ease of understanding.\n\n■Preferred Skills:\n- Candidates with experience in team management\n- Ability to research, learn and apply AI technology\n- Candidates can communicate in English or Japanese\n\nQuyền lợi\n\n・Probation: 1 month (100% full-time salary).\n・Full payment social insurance\n・Laptop or desktop for working (2 monitor)\n・13th-month salary\n・Company Courses, seminars (tech, software, study sessions) or online courses\n・Loyal allowance (from 1 year working)\n・Leader/Manager and Skill allowance\n・Salary based on ability (skill, contribution, result)\n・Review twice a year (January/July)\n・Clear carrer path: management, specialists\n・Medical examination\n・Bao Viet Premium Healthcare Insurance Package\n・New tech challenge\n・Full allowance (parking lot, commuting, lunch)\n・12 days Annual Leaves per annum (each 5 years will +1)\n・Welfare: learning allowance, monthly party, company training...\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: 15A Nguyễn Trung Trực, phường 5, Bình Thạnh\n\nThời gian làm việc\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2574, 1381, 2, 'Kỹ Sư IT Fullstack Từ 2 Năm Kinh Nghiệm', '- Phát triển và bảo trì hệ thống quản lý nhà kho/xe tự hành cho cả ứng dụng web và desktop.\n- Xây dựng các dashboard và công cụ trực quan hóa để theo dõi trạng thái kho, vị trí xe tự hành và hoạt động vận hành theo thời gian thực.\n- Thiết kế các tính năng để kết nối giao diện với dữ liệu backend, đảm bảo luồng thông tin mượt mà.\n- Quản lý và tối ưu cơ sở dữ liệu để lưu trữ, truy xuất thông tin hiệu quả.\n- Đảm bảo hệ thống vận hành ổn định, an toàn và dễ dàng mở rộng.\n- Làm việc với đội UI/UX và kỹ sư hệ thống để tạo ra sản phẩm đáp ứng nhu cầu thực tế.\n- Kiểm thử, sửa lỗi và đề xuất cải tiến dựa trên phản hồi từ người dùng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp từ Đại học trở lên chuyên ngành Công nghệ thông tin, kỹ thuật phần mềm, khoa học máy tính...\n- Từ 2 năm làm việc tại các công ty/tập đoàn kinh doanh IT Outsourcing/IT Product.\n- Nắm rõ và sâu về các kiến thức cơ bản: HTML, CSS, OOP, DI... Có hiểu biết về một số design pattern, cơ sở đồ họa...\n- Thành thạo ngôn ngữ lập trình Java hoặc JavaScript.\n- Có kinh nghiệm làm việc phát triển desktop app với các công nghệ như: Java Swing, JavaFX, ElectronJs...\n- Có kinh nghiệm làm việc với một trong các frontend framework: Angular, React/NextJs, Vue.\n- Có kinh nghiệm làm việc với một số thư viện editor như JhotDraw, GoJs, JointJs...\n- Có kinh nghiệm vận hành sản phẩm IT on premise/cloud, có hiểu biết và làm việc với Docker và các tool CI/CD (Jenkins, CircleCI...) là một lợi thế.\n- Có hiểu biết cơ bản về kiểm thử phần mềm.\n- Có kinh nghiệm làm việc với một số nền tảng cung cấp dịch vụ đám mây: AWS, MS Azure... là một lợi thế\n- Có kinh nghiệm làm việc với các sản phẩm IoT là một lợi thế.\n- Có khả năng đọc hiểu các tài liệu tiếng Anh chuyên ngành.\n- Các kỹ năng giải quyết vấn đề, làm việc nhóm, nghiên cứu...\n\nQuyền lợi:\n- Thử việc: 60 ngày, được hưởng 85% lương cứng;\n- Hỗ trợ ăn trưa 30.000 đồng/ngày.\n- Đóng BHXH, BHYT, nghỉ phép hưởng lương theo quy định của Luật;\n- Chế độ phúc lợi: thưởng Lễ Tết, thưởng dự án, lương thứ 13, review lương 01 năm/lần hoặc đột xuất theo đề xuất và năng lực của nhân sự;\n- Chế độ du lịch, teambuilding hàng năm;\n- Được thử sức trong một môi trường làm việc trẻ trung, năng động với chính sách đãi ngộ tốt, có nhiều cơ hội nâng cao năng lực bản thân và tăng thêm thu nhập.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2575, 1165, 2, 'Nhân Viên Lập Trình Back-End', 'Mô tả công việc\n- Phối hợp với đội nhóm để phân tích yêu cầu của dự án, xây dựng kiến trúc và tổng hợp thành tài liệu.\n- Chịu trách nhiệm phát triển, tối ưu và duy trì hệ thống backend cho ứng dụng (Android, iOS, web).\n- Tối ưu hóa hệ thống cơ sở dữ liệu (SQL), giải quyết các vấn đề về hiệu năng và scalability.\n- Triển khai các giải pháp bảo mật theo quy định\n- Đánh giá yêu cầu xây dựng (đánh giá được hết tất cả các trường hợp, hiểu bản chất của vấn đề), sửa đổi tính năng.\n- Xử lý lỗi phát sinh trong quá trình vận hành\n- Tìm kiếm các phương án tối ưu nhằm nâng cao giải pháp, hiệu suất cho quá trình phát triển sản phẩm\n- Nghiên cứu, cập nhật các xu hướng, công nghệ liên quan đến phát triển sản phẩm.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học/cao đẳng các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin...\n- Độ tuổi từ 23-30 tuổi.\n- Tối thiểu 1 - 3 năm kinh nghiệm phát triển ứng dụng backend sử dụng Node.js.\n- Thành thạo Node.js và các framework phổ biến như Express, NestJS.\n- Kinh nghiệm với các công cụ quản lý cơ sở dữ liệu như MySQL, PostgreSQL, Microsoft SQL.\n- Thành thạo sử dụng AI trong công việc.\n- Hiểu biết về thiết kế API RESTful.\n- Có khả năng đọc hiểu tiếng Anh & sử dụng tốt công cụ tìm kiếm để giải quyết vấn đề.\n- Kiến thức về bảo mật web và các phương pháp bảo vệ ứng dụng.\n- Có ý thức lập trình viết code theo cấu trúc, theo tài liệu, dễ dàng nâng cấp (clean code).\n- Kỹ năng giải quyết tốt và khả năng làm việc độc lập cũng như làm việc nhóm.\n- Có khả năng giao tiếp và hợp tác cùng các đội nhóm khác.\n- Chủ động, trung thực và có ý thức cầu tiến.\n\nQuyền lợi\n- Thời gian làm việc: 8h00 - 17h00 Từ thứ 2 đến thứ 6, được nghỉ T7&CN\n- Cơ hội huấn luyện: Cơ hội tham gia các chương trình đào tạo trong nước và nước ngoài, đặc biệt dành cho lập trình viên.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, hòa đồng\n- Thu nhập theo năng lực và hiệu quả công việc.\n- Đảm bảo đầy đủ quyền lợi của người lao động theo quy định của Nhà nước.\n- Khám sức khỏe định kỳ hàng năm và tham gia thêm gói bảo hiểm chăm sóc sức khỏe BIC\n- Tham gia các hoạt động teambuilding, bonding, CLB đá bóng hàng tuần tại Công ty.\n- Phụ cấp khác: Phụ cấp cơm trưa, gửi xe, sinh nhật, công tác phí và các phụ cấp khác cho người lao động.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 614 Điện Biên Phủ, Quận 10\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2576, 1259, 2, 'Mobile Developer', 'Mô tả công việc:\nPhát triển và duy trì các ứng dụng di động trên nền tảng Android cho khách hàng.\nThiết kế giao diện người dùng thân thiện, tương thích nhiều thiết bị và phiên bản Android.\nTích hợp API, tối ưu hóa hiệu năng, thực hiện kiểm thử và đảm bảo chất lượng ứng dụng.\nTriển khai ứng dụng lên Google Play Store và hỗ trợ bảo trì sau phát hành.\nHợp tác chặt chẽ với đội nhóm (developer, designer, tester) để hoàn thành các yêu cầu dự án.\n\nYêu cầu ứng viên:\nTối thiểu 1 Kinh nghiệm với Android Developer: Kotlin/Java, MVVM, Jetpack, Material Design\nKinh nghiệm tích hợp RESTful API, xử lý dữ liệu an toàn và tối ưu hiệu năng ứng dụng.\nThành thạo Git, GitFlow và có kinh nghiệm với CI/CD là một lợi thế.\nHiểu biết về kiểm thử (Espresso, JUnit) và các mô hình phát triển phần mềm (Agile, Scrum).\nĐã từng phát triển ít nhất 1 ứng dụng hoàn chỉnh và triển khai lên Google Play Store (ưu tiên có portfolio).\nKỹ năng làm việc nhóm tốt, tư duy logic, chủ động, thông minh, chăm chỉ, trung thực.\n\nQuyền lợi:\nChế độ phúc lợi xã hội như: BHYT, BHXH,... theo quy định của luật Lao động\nHưởng chế độ phúc lợi hấp dẫn: Du lịch, sinh nhật, các hoạt động team building và các chế độ khác theo quy định của Công ty.\nĐược làm việc trong môi trường trẻ trung, năng động, có cơ hội phát triển nghề nghiệp phù hợp với năng lực và định hướng nghề nghiệp.\nĐược cấp máy tính và các thiết bị phục vụ công việc.\n\nĐịa điểm làm việc:\n- Thái Nguyên: Tổ 1, phường Phố Cò, thành phố Sông Công, TP Sông Công.\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên, TP Sông Công', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2577, 1382, 2, 'Lập Trình Viên C# WPF', 'Mô tả công việc\n- Phát triển ứng dụng desktop sử dụng .NET Framework / .NET Core với WPF và XAML\n- Tối ưu hiệu suất ứng dụng, trải nghiệm người dùng và khả năng mở rộng\n- Tham gia phân tích kỹ thuật, thiết kế hệ thống và cải thiện mã nguồn\n- Sửa lỗi, bảo trì và nâng cấp các sản phẩm phần mềm hiện có\n\nYêu cầu ứng viên\nBắt buộc:\n- Tốt nghiệp chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan\n- Từ 2–5 năm kinh nghiệm thực tế với C#, WPF và XAML\n- Hiểu rõ kiến trúc MVVM, Lập trình hướng đối tượng (OOP), nguyên lý SOLID và các Design Pattern\n- Thành thạo Git, Visual Studio, GitHub/GitLab\n- Có kinh nghiệm làm việc trong môi trường Agile/Scrum\n- Tư duy logic, chủ động, có khả năng tự học và cập nhật công nghệ mới\n\nƯu tiên có:\n- Hiểu biết về DevExpress, Telerik hoặc các bộ công cụ giao diện người dùng khác\n- Kinh nghiệm làm việc với RESTful API, CI/CD pipelines\n- Có khả năng giao tiếp tiếng Anh cơ bản hoặc đọc hiểu tài liệu kỹ thuật tốt\n\nQuyền lợi\n- Mức lương & thưởng: Thỏa thuận theo năng lực.\n- Thưởng tháng 13 và thưởng theo kết quả công việc.\n- Chế độ bảo hiểm và phúc lợi theo quy định của Bộ luật Lao động.\n- Cơ hội đào tạo chuyên môn nhằm nâng cao kỹ năng nghiệp vụ và chuyên môn kỹ thuật.\n- Môi trường làm việc hiện đại, năng động, thân thiện và cởi mở, khuyến khích sáng tạo và phát triển cá nhân.\n- Các hoạt động gắn kết nhân viên như team building, du lịch hàng năm, sự kiện nội bộ định kỳ.\n- Tham gia các câu lạc bộ thể thao như cầu lông, bóng đá,...\n- Thời gian làm việc: Từ 8:00 đến 17:00, từ thứ Hai đến thứ Sáu (nghỉ Thứ Bảy và Chủ Nhật).\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Công viên phần mềm Quang Trung, Quận 12\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2578, 209, 2, 'ReactJS Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\nRESPONSIBILITIES\n• Leading the development of high-impact features\n• Architecting scalable, efficient React.js solutions\n• Collaborating with cross-functional teams and stakeholders\n• Ensuring the highest standards of code quality and performance\n• Identifying and addressing technical issues proactively\n• Innovating and implementing best practices in React.js development\n• Participating in strategic planning and decision-making\n• Driving continuous improvement in development processes\n• Mentoring and providing guidance to junior team members\n\nYêu cầu ứng viên\n• Extensive experience with React.js and JavaScript\n• Experience with dynamic rendering\n• Proven track record in architecting complex UI solutions\n• Expertise in front-end build tools and pipelines\n• In-depth knowledge of RESTful APIs and integration\n• Familiarity with security best practices\n• Experience with performance optimization techniques\n• Ability to work effectively in Agile and with cross-functional teams\n• Strong leadership, communication, and problem-solving skills\n• Previous mentoring or leadership experience is a plus\n• A degree in software engineering, information technology, or a related field\n\nQuyền lợi\n• FPT Care insurance plan tailored for FPT employees\n• Relocation Policy up to 100 Million VND for the candidate who is willing to relocate to Nha Trang City.\n• Attractive annual summer vacation allowance\n• Sponsored training courses for personal growth and up to 100% coverage for certification costs\n• Global and inclusive workplace with monthly cross-cultural events\n• International exposure and career growth across global locations\n• Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\n\nĐịa điểm làm việc\n- Khánh Hoà: VCN Tower, Số 2 Đường Tố Hữu, Khu đô thị Phước Hải, Thành phố Nha Trang, TP Nha Trang\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khánh Hoà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2579, 1332, 2, 'Fullstack Developer', '• Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng Nhật, Âu, Mỹ.\n• Hợp tác và trao đổi công việc với Team Member, Team Leader.\n• Xây dựng, tối ưu RESTful API, GraphQL, đảm bảo hiệu suất và khả năng mở rộng.\n• Phát triển frontend với React.js, tối ưu UI/UX, đảm bảo hiệu suất trên trình duyệt.\n• Quản lý và tối ưu cơ sở dữ liệu (MySQL, PostgreSQL, MongoDB.\n• Hỗ trợ, hướng dẫn các thành viên trong nhóm phát triển.\n• Có kiến thức nền tảng tốt về lập trình (OOP, cấu trúc dữ liệu và giải thuật…).\n• Có kiến thức nền tảng tốt về cơ sở dữ liệu quan hệ (thiết kế, sử dụng…).\n• Có kiến thức nền tảng tốt về hệ điều hành linux, cấu hình, triển khai web server.\n• Từ 3 năm kinh nghiệm lập trình sử dụng ngôn ngữ PHP trên các FrameWork như Laravel, Cake....\n• Từ 3 năm kinh nghiệm lập trình Frontend sử dụng HTML/CSS/Javascript, TypeScript trên các framework như Reactjs, Vuejs…\n• Có trên 1 năm lập trình trên môi trường cloud đặc biệt là AWS (Ec2, lambda…).\n• Có khả năng tìm hiểu, thích ứng tốt với công nghệ mới.\n• Có kinh nghiệm đảm nhiệm các vị trí project team leader là điểm cộng.\n• Nhiệt tình, teamwork tốt, sẵn sàng học hỏi các công nghệ mới để đáp ứng công việc.\n• Có tư duy hệ thống, tư duy logic tốt, có khả năng đề xuất vấn đề và giải quyết vấn đề.\n• Mức lương: thỏa thuận.\n• Được xây dựng lộ trình và hỗ trợ phát triển trở thành keymember, team leader.\n• Review lương hằng năm, lương tháng 13 theo hiệu quả kinh doanh của công ty.\n• Tham gia BHXH, BHYT, BHTN đầy đủ theo Luật lao động.\n• Nghỉ phép 12 ngày/năm.\n• Hưởng mọi quyền lợi nghỉ Lễ Tết kèm theo thưởng ngày Lễ/Tết trong năm.\n• Trợ cấp đối với nhân sự có thâm niên.\n• Team building định kỳ hàng Quý, du lịch 1 lần/năm.\n• Thời gian làm việc: 08:00 đến 17:00 từ Thứ Hai đến thứ Sáu.\n• Môi trường làm việc thoải mái, trẻ trung, năng động, có nhiều cơ hội thăng tiến và phát triển bản thân.\n- Hà Nội: Tầng 6, số 12 Mễ Trì Hạ, phường Mễ Trì, Nam Từ Liêm\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2580, 1108, 2, 'Backend Developer', 'ORBRO, một công ty startup IT đang trên đà phát triển nhanh chóng, chúng tôi đang tuyển dụng lập trình viên backend!\nORBRO là một đội ngũ luôn sẵn sàng đối mặt với thử thách, phá vỡ các khuôn mẫu truyền thống để phát triển công nghệ tiên tiến và mở ra những thị trường mới. Hiện tại, chúng tôi đang tuyển dụng 10 thành viên đầu tiên để gia nhập đội ngũ tại Việt Nam, nhằm mở rộng và vươn ra thị trường toàn cầu. Chúng tôi mong muốn tìm kiếm những tài năng nhiệt huyết, sẵn sàng cùng nghiên cứu và quảng bá để khai phá tương lai.\n\nCông ty chúng tôi đang phát triển các hệ thống server và backend cho các thiết bị dựa trên AIoT và Embedded. Lập trình viên sẽ đảm nhận toàn bộ quá trình phát triển backend, từ các lightweight server tích hợp trong sản phẩm đến việc liên kết với cloud, bao gồm thiết kế và tối ưu hóa hệ thống, quản lý luồng dữ liệu và tăng cường bảo mật.\n\nNhiệm vụ chính\n• Thiết kế và triển khai kiến trúc server tối ưu cho môi trường AIoT và Embedded.\n• Thiết kế, tối ưu hóa database để thu thập, xử lý và lưu trữ dữ liệu.\n• Phát triển hệ thống dựa trên multi-thread/multi-process cho xử lý và streaming video thời gian thực.\n• Thiết kế, triển khai và tăng cường bảo mật cho server API dựa trên REST API, WebSocket.\n• Xây dựng, vận hành và bảo trì server trên môi trường cloud như AWS.\n• Tối ưu hóa hiệu suất và lightweight server (tối ưu hóa bộ nhớ/CPU, cải thiện latency).\n\nYêu cầu ứng viên\nKỹ năng cần thiết\n• Kinh nghiệm thiết kế và tối ưu hóa kiến trúc server.\n• Hiểu biết về lập trình multi-thread, multi-process.\n• Kinh nghiệm thiết kế và vận hành database như MySQL, PostgreSQL, MongoDB.\n• Kinh nghiệm phát triển server REST API và WebSocket.\n• Kinh nghiệm về tăng cường bảo mật và xử lý xác thực.\n\nƯu tiên\n• Kinh nghiệm phát triển server AIoT, Embedded.\n• Kinh nghiệm xây dựng dịch vụ dựa trên nền tảng cloud như AWS.\n• Kinh nghiệm phát triển hệ thống xử lý video thời gian thực (Streaming, Encoding, Decoding, v.v.).\n• Kinh nghiệm với nhiều ngôn ngữ lập trình khác nhau như C/C++, Python, Node.js.\n\nQuyền lợi\n• Lương: Thỏa thuận.\n• Tham gia các hoạt động Team Building.\n• Hỗ trợ thiết bị laptop khi cần thiết.\n• Môi trường làm việc trẻ trung năng động, chuyên nghiệp, kích thích sự sáng tạo.\n• Các chế độ khác theo đúng quy định pháp luật.\n\nĐịa điểm làm việc\n- Hà Nội: Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2581, 1383, 2, 'Nhân Viên Lập Trình Máy, Khuôn Ép Nhựa', 'Mô tả công việc\n- Lập trình trên phần mềm NX\n- Xây dựng và tối ưu hóa các thuật toán điều khiển cho máy móc, đảm bảo hiệu quả và độ chính xác cao.\n- Thử nghiệm và gỡ lỗi các chương trình điều khiển, đảm bảo hoạt động ổn định của máy móc.\n\nYêu cầu ứng viên\n- Tốt nghiệp trung cấp trở lên\n- Ít nhất 1 năm kinh nghiệm lập trình điều khiển máy móc, lập trình trên phần mềm NX\n- Hiểu biết về các hệ thống điều khiển tự động, cảm biến, và bộ truyền động.\n- Khả năng đọc hiểu bản vẽ kỹ thuật và tài liệu kỹ thuật.\n- Kỹ năng phân tích, giải quyết vấn đề và làm việc độc lập.\n- Kỹ năng làm việc nhóm và giao tiếp tốt.\n- Khả năng chịu áp lực công việc cao.\n- Biết tiếng Trung là lợi thế\n\nQuyền lợi\n- Mức lương cạnh tranh, phù hợp với năng lực và kinh nghiệm.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế theo quy định của pháp luật.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Cơ hội học hỏi và phát triển nghề nghiệp.\n- Các chế độ phúc lợi khác (nếu có).\n\nĐịa điểm làm việc\n- Hải Dương: KCN Phúc Điền, Cẩm Giàng\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2582, 1384, 2, 'Senior Backend Developer', 'Mô tả công việc:\n- Tham gia phát triển các thành phần backend sử dụng NodeJS cho hệ thống trading (crypto/stock/forex…).\n- Xây dựng và tối ưu API (RESTful/GraphQL) real-time, phục vụ truyền dữ liệu giao dịch, lệnh mua bán, cập nhật giá, khớp lệnh.\n- Thiết kế, xây dựng và quản lý hệ thống microservice đảm bảo khả năng mở rộng, độ tin cậy cao, latency thấp.\n- Tối ưu hiệu năng cho các module quan trọng: quản lý lệnh, sổ lệnh (order book), xử lý signal (tín hiệu giá), đồng bộ dữ liệu liên tục.\n- Tích hợp và đảm bảo an toàn khi làm việc với các bên thứ ba: sàn giao dịch, ngân hàng, ví, data feed (Websocket, REST API).\n- Triển khai, giám sát, nâng cấp hệ thống trên môi trường Docker, Kubernetes.\n- Phối hợp với team DevOps, Frontend, Data, QA để phân tích, thiết kế, triển khai và kiểm thử tính năng mới.\n- Đảm bảo code chất lượng, bảo mật, thực hiện unit test, integration test và tối ưu hóa hệ thống.\n- Xử lý sự cố hệ thống (incident, outage) nhanh chóng, đặc biệt là trong thời gian cao điểm giao dịch.\n- Nghiên cứu, đề xuất các giải pháp công nghệ mới phục vụ yêu cầu giao dịch real-time, big data, machine learning (nếu có).\n- Tham gia phân tích và nâng cấp kiến trúc để hệ thống sẵn sàng chịu tải lớn, mở rộng thị trường hoặc sản phẩm mới.\n\nYêu cầu ứng viên:\n- Từ 3 năm kinh nghiệm trở lên với Java production.\n- Có vai trò thiết kế, kiến trúc, bảo trì hệ thống trading real-time xuyên suốt (order book, matching engine, event sourcing…).\n- Thành thạo websocket, xử lý event, anti-pattern, đồng bộ hóa, thời gian thực (pub/sub, message queue).\n- Có kỹ năng tối ưu hiệu năng, scale service hệ thống trading chịu tải lớn, latency thấp (cực kỳ quan trọng).\n- Biết kiểm thử, phân tích log, xử lý sự cố production.\n- Thực chiến với Docker, Kubernetes, cloud (AWS, GCP…) là ưu thế.\n- Kinh nghiệm xây dựng hệ thống fault-tolerant, high-availability.\n- Có kiến thức sâu rộng về bảo mật hệ thống (đặc thù tài chính/trading) là ưu thế.\n- Có khả năng mentoring, review code, đề xuất giải pháp.\n\nQuyền lợi:\n- Thỏa thuận lương theo năng lực, upto 50M Gross.\n- 100% lương trong thời gian thử việc.\n- Xét tăng lương 1 lần/năm.\n- Thưởng tháng lương 13, thưởng hiệu suất, thưởng Lễ Tết, thưởng sinh nhật,...\n- Bảo hiểm xã hội, Bảo hiểm Y tế, Bảo hiểm thất nghiệp khi trở thành nhân sự chính thức.\n- Chế độ ốm đau, hiếu hỉ, khuyến khích tài năng trẻ,...\n- Môi trường trẻ trung năng động và đầy nhiệt huyết.\n- Thời gian làm việc linh hoạt.\n- Được đào tạo 1-1 với Quản lý hoặc Senior.\n- Du lịch nghỉ mát hàng năm, nhiều hoạt động teambuilding.\n- Hỗ trợ hoạt động CLB như Cầu lông, Yoga, Đá bóng, Bơi-Đạp-Chạy,...\n\nĐịa điểm làm việc:\n- Hà Nội: 106 Hoàng Quốc Việt, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2583, 1385, 2, 'Chuyên Viên Lập Trình', 'Mô tả công việc:\n- Tham gia phát triển các dự án từ Thiết kế cơ bản, Thiết kế chi tiết, Phát triển đến Triển khai.\n- Lập trình WinForm, Ứng dụng di động, Web, thiết kế báo cáo tích hợp SAP ECC (SAP Crystal Report), quản lý, chỉnh sửa, bảo trì và phát triển phần mềm liên quan đến sản xuất và IoT.\n- Thiết kế và phát triển Web API cho ứng dụng Mobile App, Web App.\n- Lập trình chức năng mới hoặc nâng cấp và chỉnh sửa tính năng hiện có (SAP/MES/HR/Web…).\n- Hỗ trợ và xử lý các vấn đề liên quan đến hệ thống ERP (SAP ECC/IRS).\n- Hỗ trợ Trưởng phòng IT trong việc tư vấn, thiết kế, triển khai, giám sát, hỗ trợ và đào tạo liên quan đến phát triển, nâng cấp và tối ưu phần mềm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- 5 năm kinh nghiệm tại vị trí tương đương (trong đó có ít nhất 3 năm kinh nghiệm làm việc với PHP/Python/.NET và quản lý dự án có từ 3 lập trình viên trở lên).\n- Thành thạo tiếng Anh trong việc đọc và hiểu tài liệu chuyên ngành.\n- Thành thạo Git, HTML, CSS, JavaScript (JQuery,...), Bootstrap, JSON, XML.\n- Kiến thức vững chắc về API (Application Programming Interface); cơ sở dữ liệu (SQL, PostgreSQL, DB2); ngôn ngữ lập trình (C++, C#, .NET, Java, Ruby on Rails, v.v.); lập trình hướng đối tượng (OOP) và mô hình kiến trúc 3 tầng.\n- Có kinh nghiệm hỗ trợ hệ thống SAP, phát triển báo cáo mới, phát triển Web với framework (ReactJS, NextJS, Spring MVC).\n- Ưu tiên ứng viên có kinh nghiệm sử dụng Restful API, DB2, SQL, HTML5, CSS3, JavaScript, jQuery, AJAX, JSON và kinh nghiệm phân tích thiết kế cơ sở dữ liệu & prototype.\n- Có kinh nghiệm quản lý dự án phần mềm và triển khai phần mềm sản xuất (IOT & MES) là một lợi thế.\n\nQuyền lợi:\n- Xe đưa đón TP.HCM – Biên Hòa\n- Laptop, tiền xăng xe, tiền điện thoại phục vụ công việc\n- 16 ngày phép có hưởng lương trong 1 năm\n- Bảo hiểm chăm sóc sức khỏe MSIG & Bảo hiểm tai nạn\n- Chế độ work from home & giờ làm việc linh hoạt\n- Thưởng chuyên cần và năng suất chất lượng hàng tháng\n- Lương tháng 13 & Thưởng bonus\n- Tham quan du lịch và teambuilding hàng năm\n- Quà nhân dịp sinh nhật, lễ, Tết,…\n\nĐịa điểm làm việc:\n- Đồng Nai: 231-237 KCN Amata, Biên Hòa, Biên Hoà\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 07:30 đến 16:15)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2584, 157, 2, 'Kỹ Sư Lập Trình Embedded/IoT (C/C++/C#, Python)', 'Mô tả công việc:\nKỹ Sư Lập Trình Embedded/IoT (C/C++/C#, Python)\n- Phát triển các hệ thống Embedded, AIoT như: hệ thống điều khiển cho ô tô, camera thông minh, Robot công nghiệp, thiết bị y tế ...\n- Lập trình cho các thiết bị edge devices (như Raspberry Pi, ESP32, Jetson Nano, Rockchip) và tính toán tại cloud (như AWS)\n- Tham gia vào các quá trình từ thiết kế, phát triển, kiểm thử đến triển khai hệ thống phần cứng và phần mềm\n- Tiếp cận, nghiên cứu, ứng dụng các công nghệ mới về AI, Edge Computing, IoT, FPGA\n- Xây dựng tài liệu báo cáo, quản lý dự án\nYêu cầu ứng viên:\n- Có kinh nghiệm lập trình ngôn ngữ C/C++/C#, Python tối thiểu 03 năm và khả năng học hỏi nhanh\n- Tiếng Nhật từ N2 trở lên, với tư duy lập trình tốt và năng lực làm việc độc lập\n- Có kinh nghiệm lập trình với ít nhất một loại thuộc MCU, SoC hay SoM như: Renesas RL78, Rasp Pi, ESP32, Jetson Nano, Rockchip, ...\nLợi thế:\n- Có hiểu biết về Embedded Linux, Android, CS+, ESP-IDF, ...\n- Có kinh nghiệm lập trình device driver\n- Có hiểu biết tốt về văn hóa làm việc theo phong cách Nhật Bản\n- Có tinh thần làm việc nhóm, năng động, có khả năng làm việc dưới áp lực cao\nQuyền lợi:\n- Lương thỏa thuận theo năng lực, đảm bảo cạnh tranh, up to 650 Man, làm việc tại Tokyo\n- Hưởng đầy đầy đủ chế độ nghỉ lễ, chế độ bảo hiểm y tế và bảo hiểm lao động theo quy định\n- Làm việc trong môi trường năng động, thân thiện, khuyến khích ý tưởng sáng tạo, có cơ hội thăng tiến cao\n- Chính sách thưởng theo kỳ và hỗ trợ nhà ở, đi lại\n- Team building, seminar chuyên môn\nĐịa điểm làm việc:\n- Nhật Bản\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nhật Bản', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2585, 1125, 2, 'Lập Trình Viên Frontend', 'Mô tả công việc\n- Phát triển giao diện người dùng (UI/UX) cho các sản phẩm/phần mềm của công ty liên quan đến đầu tư chứng khoán, đào tạo trực tuyến, v.v.\n- Chuyển đổi thiết kế (wireframes, mockups) thành các tính năng, trang web, ứng dụng web có tính tương tác cao, mượt mà và hiệu năng tốt.\n- Tích hợp giao diện front-end với back-end thông qua API.\n- Ứng dụng các công cụ lập trình AI để tối ưu trải nghiệm hoặc giao diện người dùng khi cần.\n- Phối hợp chặt chẽ với team thiết kế (designer), back-end, QA để đảm bảo chất lượng sản phẩm.\n- Nghiên cứu và đề xuất các công nghệ, framework front-end phù hợp với xu hướng mới.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các ngành liên quan; hoặc tốt nghiệp đại học ngành khác nhưng có tối thiểu 2 năm kinh nghiệm lập trình front-end.\n- Thành thạo các ngôn ngữ và công nghệ front-end: HTML, CSS, JavaScript (Ưu tiên biết thêm các framework như React, Angular hoặc Vue).\n- Có kinh nghiệm về responsive design, đảm bảo sản phẩm chạy tốt trên đa nền tảng, đa thiết bị.\n- Biết sử dụng các công cụ lập trình AI hoặc đã làm qua các dự án có ứng dụng AI là lợi thế.\n- Ưu tiên ứng viên đã tham gia dự án thực tế, có khả năng tối ưu hiệu năng và trải nghiệm người dùng.\n- Tinh thần học hỏi cao, tư duy logic, làm việc nhóm hiệu quả.\n\nQuyền lợi\n- Cơ hội tham gia vào các dự án công nghệ và sản phẩm sáng tạo, đa lĩnh vực.\n- Lương cạnh tranh, thưởng theo năng lực và đóng góp.\n- Môi trường làm việc trẻ trung, chuyên nghiệp, khuyến khích tư duy đổi mới và tự do sáng tạo.\n- Cơ hội phát triển nghề nghiệp, nâng cao kỹ năng chuyên môn và quản lý.\n- Tham gia đầy đủ bảo hiểm và các chế độ phúc lợi khác.\n\nĐịa điểm làm việc\n- Hà Nội: 37 Lê Văn Thiêm Phường Nhân Chính, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- 8h-17h, T7 ngày lẻ\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2586, 1386, 2, 'Backend Engineer', 'MỤC ĐÍCH CỦA VỊ TRÍ NÀY:\n- Tham gia thiết kế, xây dựng và triển khai các hệ thống back-end cho nền tảng Vinbase\n- Tham gia thiết kế, xây dựng và bàn giao các dự án phát triển Trợ lý ảo triển khai trên nền tảng Vinbase\n\nTRÁCH NHIỆM CỦA VỊ TRÍ NÀY:\n- Thiết kế giải pháp và triển khai các hệ thống, sản phẩm AI, Machine learning có khả năng co giãn, luôn luôn sẵn sàng và có khả năng chịu lỗi.\n- Phát triển sản phẩm phần mềm có khả năng tích hợp hiệu quả và an toàn đến các nền tảng và đối tác bên thứ 3.\n- Tham gia và tuân thủ các quy trình phát triển phần mềm linh hoạt, thực hành DevOps, CICD để phát triển và triển khai phần mềm với tốc độ cao nhất.\n- Hướng dẫn các thành viên ít kinh nghiệm hơn, chủ động đóng góp và thực hiện các ý tưởng để cải thiện chất lượng sản phẩm, hiệu suất làm việc của nhóm và môi trường làm việc trong công ty.\n- Các công việc khác theo phân công của cấp trên.\n\nHỌC VẤN:\n- Tốt nghiệp Đại học trở lên trong chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc tương đương.\n- Xếp loại bằng từ Khá trở lên.\n\nKINH NGHIỆM:\n- Trên 2 năm làm việc trong lĩnh vực phát triển phần mềm.\n- Trên 1 năm kinh nghiệm thiết kế và phát triển các hệ thống back-end sử dụng kiến trúc Microservice sử dụng Python/Golang.\n- Có kinh nghiệm làm việc với các loại cơ sở dữ liệu quan hệ và NoSQL.\n- Có kinh nghiệm viết kiểm thử tự động, có kinh nghiệm sử dụng Jenkins, CICD, Docker, Kubenetes, có kinh nghiệm sử dụng các phương pháp caching, queue, pubsub.\n- Nắm được kiến thức cơ bản về cấu trúc dữ liệu, thiết kế hướng đối tượng, design pattern.\n- Có kinh nghiệm làm việc sâu về hệ thống, dữ liệu và thuật toán.\n- Có hiểu biết về các giao thức kết nối, API như RESTful, Websocket, GRP.\n\nNĂNG LỰC CHUYÊN MÔN:\n- Thành thạo 1 trong các ngôn ngữ lập trình Python/Golang.\n- Thiết kế, tối ưu và quản lý dữ liệu bằng các hệ quản trị như MySQL, PostgreSQL hoặc MongoDB.\n- Xây dựng kiến trúc phần mềm vững chắc, đảm bảo hiệu suất, khả năng mở rộng và tính ổn định của hệ thống.\n- Áp dụng các nguyên tắc OOP (Object-Oriented Programming) để xây dựng mã nguồn sạch, dễ mở rộng và bảo trì, tối ưu hóa cấu trúc hệ thống phần mềm.\n\nYÊU CẦU KHÁC:\n- Kỹ năng mềm: Tư duy giải quyết vấn đề, Khả năng làm việc nhóm, Khả năng truyền đạt giao tiếp.\n- Kỹ năng máy tính: Sử dụng tốt Linux, Windows, MacOS, Word, Excel.\n- Ngoại ngữ: Tiếng Anh khá.\n\nĐIỂM CỘNG/ƯU TIÊN ỨNG VIÊN:\n- Có kinh nghiệm làm việc với các nền tảng cloud như AWS, Azure hay GCP.\n- Có hiểu biết về các nền tảng và công nghệ học máy như TensorFlow hay PyTorch.\n\nPHÚC LỢI:\n- Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của Luật Lao động (BHXH, BHYT, BHTN) và được Công ty mua Bảo hiểm sức khỏe cá nhân theo cấp bậc vị trí, khám sức khỏe định kỳ tại Bệnh viện và Trung tâm khám sức khỏe uy tín trên toàn quốc.\n- Được hưởng chế độ ưu đãi khi sử dụng các dịch vụ như: Ưu đãi học phí (Vinschool), khám chữa bệnh (Vinmec), nghỉ dưỡng (Vinpearl), mua xe (VinFast), … theo chế độ của Tập đoàn.\n- 12 ngày nghỉ phép năm, nghỉ các ngày lễ, Tết theo quy định của pháp luật.\n- Được cấp máy tính xách tay, trang thiết bị làm việc khác phù hợp với yêu cầu công việc.\n- Phụ cấp ăn trưa hàng tháng.\n- Canteen rộng rãi, trang bị đầy đủ các thiết bị cần thiết như máy pha cà phê, tủ lạnh, lò vi sóng, các loại trà và cà phê hạt được bổ sung hàng ngày.\n- Chương trình chăm sóc sức khỏe tinh thần cho CBNV.\n- Tham gia các hoạt động nội bộ, hoạt động teambuilding, du lịch hàng năm của công ty. \n\nCƠ HỘI PHÁT TRIỂN:\n- Cơ hội làm việc trong môi trường chuyên nghiệp, công nghệ dẫn đầu về AI, quy tụ hơn 100 nhà khoa học, chuyên gia, kỹ sư đến từ các trường đại học hàng đầu thế giới và Việt Nam như: ĐH Yale (Mỹ), ĐH Johns Hopkins (Mỹ), ĐH Illinois (Mỹ), ĐH Toulouse (Pháp), ĐH Cambridge (Anh Quốc), Đại học Bách Khoa, Đại học Công nghệ – Đại học Quốc gia, …\n- Được xây dựng kế hoạch phát triển cá nhân.\n- Được tài trợ các khóa học miễn phí trên Coursera, tham gia các khóa học chuyên môn, kỹ năng mềm, quản lý,… phù hợp với yêu cầu công việc và nhu cầu phát triển của mỗi cá nhân.\n- Được hỗ trợ một phần chi phí thi các chứng chỉ chuyên môn phục vụ công việc.\n\nMÔI TRƯỜNG LÀM VIỆC:\n- Văn phòng hiện đại, tiện nghi, trẻ trung và chuyên nghiệp.\n- Tham gia không giới hạn các câu lạc bộ: cộng đồng đọc sách, CLB cầu lông, bóng bàn, bóng đá (công ty hỗ trợ một phần chi phí cho các hoạt động của CLB).\n- Môi trường làm việc cởi mở, khuyến khích CBNV đóng góp ý kiến, sáng kiến, ý tưởng.\n\nĐịa điểm làm việc: Tầng 9, tòa nhà Century, Times City, 458 Minh Khai, Hai Bà Trưng\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2587, 1387, 2, 'Frontend Developer (Shopify, Thành Thạo HTML.CSS,JS, Lương Từ 12-20 Triệu)', 'Mô tả công việc\n- Làm việc với các template theo chuẩn Shopify liquid theo design để xây dựng và phát triển các tính năng hỗ trợ bán hàng thông qua các template sử dụng ngôn ngữ Shopify liquid, javascript, css, html.\n- Xây dựng template cho dự án app page builder.\n- Fix bug phát sinh từ các template khi đưa tới người dùng thật.\n- Tương tác liên tục 2 chiều với team và cấp trên để đảm bảo hoàn thành công việc theo tiêu chí chất lượng cao.\nYêu cầu ứng viên\n- Tối thiểu 2 năm kinh nghiệm làm việc với Theme của Shopify hoặc làm việc với các Page builder cho Shopify (là lợi thế).\n- Có kỹ năng chuyên môn cao về Shopify Liquid, Javascript, CSS, HTML.\n- Yêu cầu cao về sự cẩn thận, tỉ mỉ và trách nhiệm với công việc.\n- Có kinh nghiệm dẫn dắt, hướng dẫn, hỗ trợ phát triển các thành viên trong nhóm là một lợi thế.\nQuyền lợi\n- Mức lương: 12 - 20M (tùy theo năng lực).\n- Thưởng quý, thưởng lương tháng thứ 13. Xem xét tăng lương 2 lần/năm.\n- Có lộ trình thăng tiến và được các dev nhiều kinh nghiệm đào tạo nâng cao trình độ.\n- Được tham gia những dự án mới giải quyết những vấn đề thực tế của khách hàng.\n- Được đóng bảo hiểm sau khi ký hợp đồng chính thức.\n- Môi trường làm việc trẻ trung thân thiện, đa số ở độ tuổi 9x, 2k.\n- Các phúc lợi khác: hỗ trợ tiền ăn trưa, tiền gửi xe, sinh nhật, du lịch hàng năm.\nĐịa điểm làm việc\n- Hà Nội: Tầng 6, Số 68 Khúc Thừa Dụ, Dịch Vọng, Cầu Giấy, Cầu Giấy.\nThời gian làm việc\n- Thời gian làm việc từ 8h-17h15 từ thứ 2-6 (nghỉ thứ 7, CN).\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2588, 1223, 2, 'Senior Developer - Team Lead', 'Chúng tôi đang tìm kiếm Senior Developer giàu kinh nghiệm để tham gia vào đội ngũ phát triển của TechPlus. Vị trí này sẽ chịu trách nhiệm nghiên cứu, thiết kế và phát triển các hệ thống công nghệ cho lĩnh vực Tài chính – Ngân hàng, bao gồm Core Banking, Virtual Account Management (VAM) và các nền tảng tài chính số.\nBạn sẽ làm việc chặt chẽ với Product Owner, Business Analyst, và các nhóm liên quan để xây dựng ý tưởng, thiết kế giải pháp và triển khai các sản phẩm/dự án. Đồng thời, bạn sẽ chịu trách nhiệm duy trì tài liệu kỹ thuật, hỗ trợ đào tạo và hướng dẫn người dùng khi cần thiết.\nBên cạnh vai trò phát triển phần mềm, bạn cũng sẽ tham gia vào việc bảo trì, nâng cấp hệ thống, tối ưu hiệu suất, cải thiện quy trình phát triển, đảm bảo chất lượng sản phẩm/dự án, và hỗ trợ các nhóm khác trong quá trình triển khai.\nCụ thể:\n- Tham gia nghiên cứu, thiết kế, xây dựng, phát triển và triển khai hệ thống Công nghệ Thông tin cho Tài chính, Ngân hàng.\n- Tham gia xây dựng ý tưởng, tham gia thiết kế sản phẩm, giải pháp.\n- Xây dựng tài liệu kỹ thuật sản phẩm, dự án.\n- Tham gia xây dựng tài liệu đào tạo, tham gia đào tạo và hỗ trợ người sử dụng.\n- Bảo trì, nâng cấp hệ thống cho sản phẩm, dự án.\n- Hợp tác với các bộ phận khác trong quá trình thực hiện dự án.\n- Tham gia cải tiến quy trình phát triển sản phẩm, dự án.\n- Các công việc phát sinh khác theo yêu cầu kỹ thuật dự án.\n- Báo cáo kết quả công việc, thời gian làm việc phù hợp với quy định Công ty.\n\nYêu cầu ứng viên\n- Chuyên ngành đào tạo: Tốt nghiệp Đại học chuyên ngành CNTT hoặc tương đương.\n- Kinh nghiệm làm việc: \n    - Từ 03 - 08 năm kinh nghiệm xây dựng và phát triển dự án trong lĩnh vực CNTT. \n    - Đã tham gia xây dựng, phát triển, triển khai các giải pháp liên quan trong lĩnh vực CNTT cho ngành Tài chính, Ngân hàng là một lợi thế.\n- Kiến thức chuyên môn và kỹ thuật:\n    - Kinh nghiệm thiết kế hệ thống, thiết kế cơ sở dữ liệu, Design Pattern.\n    - Kinh nghiệm lập trình ứng dụng với .Net Framework, Java và các ngôn ngữ lập trình phổ dụng khác.\n    - Kinh nghiệm làm việc với một trong các hệ thống CSDL như: Oracle, MS SQL Server, MySQL, PostgreSQL …\n    - Kinh nghiệm xây dựng các ứng dụng trên nền tảng Cloud Native / kiến trúc Microservice.\n    - Kinh nghiệm triển khai các ứng dụng trên Container / Docker cho môi trường Windows & Linux\n    - Kinh nghiệm và hiểu biết về các yêu cầu bảo mật trên môi trường Cloud.\n    - Quen thuộc với Continuous Integration / Continuous Deployment.\n    - Tiếng Anh giao tiếp, đọc hiểu tốt. \n    - Khả năng làm việc độc lập và chịu áp lực trong môi trường nhịp độ cao.\n    - Kỹ năng phân tích, phản biện, tư duy logic và giải quyết vấn đề tốt.\n\nQuyền lợi\nMôi trường làm việc:\n- Đội ngũ trẻ trung, năng động, luôn khuyến khích sáng tạo.\n- Văn phòng hiện đại, đầy đủ tiện nghi.\n- Cơ hội tham gia vào các dự án công nghệ tài chính lớn, có tầm ảnh hưởng lên tới hàng chục triệu người dùng.\n- Cơ hội phát triển bản thân thông qua các buổi đào tạo và workshop định kỳ.\n- Được trực tiếp đào tạo về các kỹ năng Marketing, thị trường và sản phẩm bởi các chuyên gia trong ngành\n\nPhúc lợi và chế độ đãi ngộ:\n- Thu nhập và Phụ cấp: cạnh tranh với thị trường ở vị trí công việc.\n- Được cung cấp thiết bị phục vụ công việc theo chính sách của Công ty.\n- Đóng BHXH đầy đủ theo quy định nhà nước\n- Quyền lợi Bảo hiểm sức khỏe tự nguyện (PVI Care hoặc tương đương) theo chính sách của Công ty.\n- Thưởng các ngày lễ tết: Theo quy định chung của Công ty.\n- Chế độ tăng lương hấp dẫn: thù lao và thưởng cho nhân viên dựa trên hiệu suất làm việc và đóng góp cá nhân. Được xem xét ngay khi bạn là một nhân viên xuất sắc mà không cần chờ tới đánh giá định kỳ.\n- Nghỉ phép: 12 ngày/ năm và phép thâm niên.\n- Chế độ du lịch: 1 năm /1 lần, chương trình teambuilding được tổ chức thường niên.\n- Các chế độ khác: theo Luật Lao động Việt Nam – theo Nội quy lao động và Quy định tài chính của Công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2589, 165, 2, 'Lập Trình Viên Flutter', 'Về KiotViet:\nSản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ.\nVới hơn 13 năm và trên 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm.\n\nBạn sẽ làm gì:\n- Phát triển các dự án phần mềm công ty trên nền tảng Flutter Cross-Platform (Android/iOS)\n- Thực hiện các nhiệm vụ khác liên quan đảm bảo tiến độ dự án\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học ưu tiên chuyên ngành CNTT hoặc chuyên ngành liên quan;\n- Có kinh nghiệm Flutter từ 4 năm trở lên;\n- Thành thạo state management (Provider, Riverpod, Bloc…).\n- Hiểu biết hoặc đã từng làm việc với kiến trúc MVVM, Clean Architecture.\n- Có kinh nghiệm làm việc với: REST API, Firebase, Isar.\n- Native Android (Kotlin/Java) và/hoặc iOS (Swift/Obj-C) và custom plugin.\n- Nắm rõ Push notification, background tasks, deep link, crash tracking.\n- Biết viết unit test là lợi thế.\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm.\n- Làm việc từ Thứ 2 – Thứ 6, làm việc 8h/ngày và checkin linh hoạt từ 8h-9h;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\n- Chăm sóc sức khoẻ: Khám sức khoẻ định kỳ hàng năm, Bảo hiểm sức khoẻ cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\n- Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2590, 1253, 2, 'Fullstack Developer (Java/ReactJS)', 'Mô tả công việc\n- Sử dụng Java phát triển các service sử dụng REST API (Java Spring Boot) trong hệ thống kiến trúc Microservices\n- Lập trình frontend cho các dự án phát triển sản phẩm\n- Tham gia phát triển nền tảng quản lý & bán hàng trên hệ thống Sapo: quản lý bán hàng, quản lý kho, quy trình hoàn tất đơn hàng, phát triển các kênh bán hàng POS, Web, Marketplace, Social...\n- Tham gia phân tích nghiệp vụ, đảm bảo chất lượng, tiến độ công việc và trải nghiệm người dùng (hiệu năng, tính dễ sử dụng, cũng như mức độ ổn định của sản phẩm).\n- Triển khai các hạng mục công việc theo nhiệm vụ được giao. Tham gia & kiểm soát các hạng mục phát triển tính năng mới, cải tiến tính năng cũ nhằm đảm bảo chất lượng và khả năng mở rộng.\n- Phối hợp với team nghiên cứu và ứng dụng các công nghệ mới để triển khai tính năng mới, đồng thời cải tiến liên tục các hạng mục đã ra mắt nhằm tối ưu hiệu năng & duy trì ổn định sản phẩm.\n\nYêu cầu ứng viên\n- Tốt nghiệp chuyên ngành Công nghệ thông tin và các chuyên ngành liên quan khác.\n- Có từ 2 năm kinh nghiệm trở lên lập trình Java Full Stack (Backend Java Springboot + Frontend) \n- Sử dụng thành thạo Git hoặc SVN.\n- Hiểu biết các Framework: Spring, Hibernate.\n- Có hiểu biết tốt về Design pattern, OOP, REST API.\n- Có kinh nghiệm & hiểu biết về xây dựng hệ thống Microservice.\n- Có tư duy logic tốt, khả năng tự tìm hiểu & giải quyết vấn đề tốt\n- Có kiến thức về cơ sở dữ liệu quan hệ Mariadb, MySQL.\n- Ưu tiên có kinh nghiệm về Domain Driven Design, NoSQL (Redis, MongoDB), các hệ thống Message Queue (Kafka, RabbitMQ).\n- Chủ động trong công việc, có tinh thần trách nhiệm cao.\n- Chủ động phối hợp với thành viên trong team để giải quyết vấn đề, thực hiện mục tiêu.\n- Ưu tiên có kinh nghiệm vận hành hệ thống AWS là 1 lợi thế.\n\nQuyền lợi\n- Thu nhập cạnh tranh cùng chính sách thưởng rõ ràng, minh bạch theo hiệu quả công việc, thỏa thuận theo năng lực của UV\n- Xét duyệt tăng lương định kỳ hằng năm, ghi nhận sự nỗ lực và đóng góp của bạn\n- Môi trường làm việc trẻ trung, năng động, khuyến khích sáng tạo và chủ động phát triển\n- Được đóng đầy đủ BHXH, BHYT theo quy định của pháp luật; đồng thời tham gia chương trình chăm sóc sức khỏe toàn diện Sapo Care\n- Cơ hội đào tạo chuyên sâu với các chuyên gia hàng đầu trong lĩnh vực thương mại điện tử, marketing online, phần mềm, giúp bạn phát triển toàn diện về kỹ năng và kiến thức\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 6, Tòa Ladeco 266 Đội Cấn, Ba Đình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Nghỉ trưa 1h30\'\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Ba Đình', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2591, 1122, 2, 'Senior Java Developer (EN Fluent)', 'Mô tả công việc\n● Work as software developer on the web-based application product in JAVA- related and open-source technologies \n● Develop applications based on graphical layout designs that follow the strict requirements \n● Take ownership and accountability for production service, including fix on fail, problem investigation, root cause determination, and resolution \n● Participate in and provide quality assurance activities, including code reviews, white-box testing, test coverage for own work and team outcome \n● Accountable for continuously discovering, evaluating and implementing new technologies/processes to optimize development efficiency or improve product quality \n● Establish estimation, proposing development solutions with customers \n● Continuously research and implement new technologies to maximize development efficiency \n\nYêu cầu ứng viên\n● Good command of English (both written/verbal) is essential \n● At least 5 years of experience in software & back-end development technologies in general \n● At least 1 year of experience with Finance + eCommerce \n● Proven hands-on experience on Java ecosystem, Spring boot, Microservices, SQL, NoSQL: MongoDB, … \n● Experience in designing & developing RESTful APIs and microservices-based system; \n● Strong knowledge of writing secured codes and good understanding of design patterns \n● Working knowledge of Scala/Spark/Kafka or any functional programming languages is a very BIG plus \n● Experienced in developing and deploying microservices with Cloud based technologies (AWS, Kubernetes, Docker…) \n● Experience in agile scrum-based development process \n● Experience with unit test \n\nDESIRED SKILLS \n● Experience as software engineer in a complex, enterprise-level development projects \n● Establish software development patterns and best practices via examples and shipping code \n● Develop architectures that are inherently secure, robust, scalable, modular, API-centric and global. \n● Collaborate with business team to develop and clarify requirements to enable development of technical solutions \n● Provide executive level support for initiatives, particularly as related to re-use, funding requirements and areas of risk \n● Multi-tasking ability essential to handle multiple priorities with minimal direction from management \n\nQuyền lợi\n- Probation salary is 100% of official salary; \n- 13th-month salary and performance review twice a year; \n- Bonus for special occasions each year (Labor Day, National Day, Solar New Year, Lunar New Year); \n- Enjoy company summer trip and other team building activities held  monthly and quarterly; \n- IT Certificate allowance as regulated; \n- Social, health and unemployment Insurance following Government policy; \n- Health Care Insurance; \n- Have chances to gain knowledge on the latest waves of blockchain, AI, Big Data; Professional, creative and dynamic working environment; \n- Work five days per week with flexible check-in time.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh, Cầu Giấy, Bình Thạnh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2592, 1298, 2, 'Lập Trình Viên Java', 'Mô tả công việc\n- Tham gia vào quá trình phân tích yêu cầu, thiết kế, phát triển và triển khai các ứng dụng phần mềm cho các hệ thống của ngân hàng.\n- Theo dõi hiệu suất hệ thống, phát hiện và khắc phục các lỗi phát sinh.\n- Làm việc chặt chẽ với các thành viên khác trong nhóm và các bộ phận liên quan của ngân hàng.\n- Xây dựng Tài liệu kỹ thuật, tài liệu đào tạo, hướng dẫn theo quy trình của dự án và theo yêu cầu của đơn vị.\n- Thực hiện các công việc khác theo sự phân công của quản lý dự án.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học hệ chính quy chuyên ngành Công nghệ Thông tin, Toán tin, Điện tử Viễn thông hoặc tương đương;\n- Thành thạo ngôn ngữ lập trình Java, Spring Boot, Angular, React JS, Strust, Jsp, Javascript, Ajax, Jquery, HTML, CSS ...\n- Thành thạo cơ sở dữ liệu Oracle, MS SQL, Postgre SQL\n- Có kiến thức về Monolithic, Micro-Service, ...\n- Có kiến thức về DevOps, CI/CD;\n- Có kinh nghiệm phát triển Restful API sử dụng ngôn ngữ Java;\n- Có kinh nghiệm sử dụng git như Git, GitLab, Docker container;\n- Có kinh nghiệm trong việc phát triền FrontEnd, BackEnd API;\n- Có kinh nghiệm (tối thiểu 02 năm) và nắm vững về Java Spring Boot\n- Có kinh nghiệm ( tối thiểu 02 năm) làm việc Frontend Angular\n- Có kinh nghiệm (tối thiểu 01 năm) làm việc trên cơ sở dữ liệu PostgreSQL\n- Có kinh nghiệm phát triển trên nền tảng BPM (ví dụ IBM, Camunda )\n- Có khả năng tối ưu xử lý truy vấn dữ liệu lớn, sử dụng caching.\n\nƯu tiên:\n- Ưu tiên ứng viên có kinh nghiệm, hiểu biết về dịch vụ tài chính ngân hàng\n- Ưu tiên ứng viên đã từng làm với một trong các hệ thống như Loan Original System, Trade Finance, Supply Chain Finance, Credit Scoring\n- Có kỹ năng giao tiếp, thuyết trình tốt;\n- Có khả năng làm việc độc lập và theo nhóm tốt;\n- Có khả năng nghe, nói, đọc, viết bằng tiếng Anh;\n- Nhiệt tình, đam mê học hỏi, chịu được áp lực và thử thách.\n\nQuyền lợi\n- Lương: 20.000.000đ – 30.000.000đ\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30.\n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Làm việc onsite tại ngân hàng số 1 Việt Nam, trực tiếp tham gia vào các dự án tiên phong về chuyển đổi số.\n- Nghỉ phép: 12 ngày/năm\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN cho 100% cán bộ sau thời gian thử việc.\n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Thu nhập: lương tháng 13; thưởng theo dự án, thưởng theo kết quả kinh doanh và mức độ đóng góp; thưởng theo năng lực và mức độ hoàn thành công việc của từng thành viên – đánh giá hàng tháng và trả thưởng theo quý; thưởng các ngày lễ lớn.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 22 tòa nhà Viwaseen, số 48 Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2593, 486, 2, 'Game Server Developer - Middle - Senior', 'Mô tả công việc\n- Phát triển server-side cho game mobile mới trên iOS/Android\n- Client sử dụng Unity\n- Sử dụng PHP (CodeIgniter) & Node.js\n- Thiết kế API, database, logic hệ thống\n- Thực hiện các công việc khác theo yêu cầu\n\nYêu cầu ứng viên\n- Trên 3 năm kinh nghiệm phát triển game server-side\n- Thành thạo thiết kế hệ thống server-side\n- Có tư duy logic và khả năng giải quyết vấn đề tốt\n- Chỉ nhận CV tiếng Anh\n\nƯu Tiên:\n- Kinh nghiệm phát triển game bằng Unity\n- Kinh nghiệm MMO & real-time game (Node.js)\n- Kỹ năng lãnh đạo & giao tiếp tiếng Anh cơ bản\n\nCông nghệ sử dụng:\n- Ngôn ngữ: PHP (CodeIgniter), Unity (C++), Node.js\n- Database: MySQL, MongoDB\n- Tool khác: Redis\n\nQuyền lợi\n- Thưởng tháng thứ 13\n- Thưởng nhân viên chuyên cần mỗi tháng\n- Tiền mừng sinh nhật, mừng cưới, mừng sinh em bé...\n- Tổ chức Event, Party, quà mừng v.v vào các dịp lễ\n- Quầy Pantry với đồ ăn nhẹ phong phú. Đặc biệt Happy Friday mỗi tuần\n- Review lương định kỳ mỗi năm\n- Môi trường làm việc chuyên nghiệp, cởi mở, hòa đồng và thân thiện\n- Khám sức khỏe định kỳ mỗi năm tại bệnh viện của Nhật.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Bình Thạnh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2594, 1315, 2, 'Full Stack Engineer', '1. Phát triển sản phẩm Fullstack (Frontend + Backend)\nThiết kế, xây dựng, tối ưu và bảo trì các tính năng cho cả frontend và backend của sản phẩm (web/app).\nTham gia thiết kế kiến trúc hệ thống mới theo chuẩn scalable, maintainable và thực hiện refactor các hệ thống cũ khi cần thiết.\nTham gia toàn bộ vòng đời phát triển phần mềm: từ thiết kế -> phát triển -> kiểm thử -> triển khai -> vận hành và tối ưu hoá hiệu suất.\n\n2. Đóng vai trò cố vấn kỹ thuật\nMentor, hướng dẫn và hỗ trợ các lập trình viên junior/mid-level trong quá trình làm việc.\nCode review, đảm bảo tiêu chuẩn coding convention và chất lượng kỹ thuật chung của dự án.\nĐề xuất, đánh giá và triển khai công nghệ, kiến trúc mới phù hợp với từng giai đoạn phát triển sản phẩm.\n\n3. Phối hợp chặt chẽ với các bộ phận liên quan\nLàm việc cùng Product Owner và Designer để phân tích yêu cầu, đề xuất giải pháp kỹ thuật khả thi, tối ưu hóa UX/UI.\nHợp tác với DevOps Engineer để xây dựng, tối ưu hóa quy trình CI/CD và hệ thống deployment.\nĐóng góp ý kiến từ góc độ kỹ thuật nhằm cải tiến sản phẩm và hỗ trợ định hướng phát triển tính năng trong tương lai.\n\nYêu cầu ứng viên\nKỹ năng chuyên môn:\n- Có từ 1-5 năm kinh nghiệm thực chiến phát triển ứng dụng web với ReactJS + NodeJS hoặc các công nghệ tương đương.\n- Đã từng lead team: có kinh nghiệm phân chia công việc, định hướng kỹ thuật, hỗ trợ thành viên và đảm bảo tiến độ dự án.\n- Nắm vững kiến trúc phần mềm, thiết kế và triển khai RESTful API, cơ chế authentication/authorization, tối ưu hóa caching và quản lý state cho ứng dụng lớn.\n- Có hiểu biết sâu về hệ quản trị cơ sở dữ liệu (SQL hoặc NoSQL), thành thạo kỹ năng indexing và tối ưu hoá truy vấn để cải thiện hiệu suất hệ thống.\n- Có kinh nghiệm viết test đầy đủ (unit test, integration test) bằng các công cụ như Jest, Mocha, Chai hoặc tương đương.\n- Am hiểu quy trình phát triển phần mềm hiện đại: Agile/Scrum, Git flow, code review, CI/CD pipelines.\n- Kiến thức nền tảng vững chắc về microservices architecture và serverless applications (AWS Lambda, API Gateway, v.v.).\n\nKỹ năng bổ sung (plus):\n- Từng làm việc tại các startup hoặc team Agile nhỏ, quen với môi trường năng động, yêu cầu tự quản lý công việc và chịu trách nhiệm toàn diện từ thiết kế đến vận hành sản phẩm.\n- Hiểu và áp dụng thành thạo các quy trình DevOps, bao gồm CI/CD pipelines, containerization (Docker), và tự động hóa triển khai trên các nền tảng cloud như AWS.\n- Có hiểu biết và kinh nghiệm thực tiễn về bảo mật hệ thống (XSS, CSRF, SQL Injection, bảo mật API) và tối ưu hiệu suất hệ thống.\n\nQuyền lợi\n- Thu nhập 15 - 30 triệu\n- Được tạo điều kiện thuận lợi để liên tục học hỏi, nâng cao kỹ năng chuyên môn và trực tiếp tham gia các dự án thực tế đầy thử thách.\n- Cơ hội thăng tiến rõ ràng: nếu thể hiện tốt về kỹ thuật, tinh thần chủ động và khả năng làm việc nhóm, bạn có thể phát triển thành Project Manager hoặc Tech Lead trong lộ trình sự nghiệp của công ty.\n- Môi trường làm việc đề cao hiệu quả: linh hoạt về giờ giấc và vị trí làm việc, tập trung vào kết quả và chất lượng công việc, không nặng hình thức hay máy móc quy trình. Khuyến khích sự chủ động, sáng tạo và đề xuất giải pháp mới trong quá trình làm việc.\n- Tham gia phát triển sản phẩm công nghệ giáo dục có ảnh hưởng sâu rộng tại Việt Nam, đóng góp trực tiếp vào việc nâng cao trải nghiệm học tập và thay đổi cách tiếp cận giáo dục cho hàng triệu người học.\n- Cơ hội được làm việc trong môi trường hướng tới sản phẩm lâu dài, ưu tiên chất lượng kỹ thuật, với tầm nhìn phát triển bài bản và bền vững.\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes Westpoint, Đỗ Đức Dục, Mễ Trì, Nam Từ Liêm, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n- Thứ 7 (từ 08:30 đến 12:00).\n\nCách thức ứng tuyển', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2595, 1388, 2, 'Thực Tập Sinh Lập Trình (FE/BE)', '-Tham gia đào tạo trong vòng từ 2 - 3 tháng theo lộ trình của công ty.\n-Được đào tạo kiến thức chuyên môn và kỹ năng mềm để phục vụ công việc.\n-Hoàn thành dự án training cá nhân theo yêu cầu của công ty.\n-Tham gia training on job qua các dự án phát triển phần mềm với khách hàng.\n\nMust have\n- Sinh viên năm 3 trở lên, chuyên ngành CNTT, khoa học máy tính hoặc các chuyên ngành liên quan; hoặc có chứng chỉ tham gia các khóa học lập trình.\n- Thời gian thực tập tối thiểu 5 buổi/tuần.\n- Có máy tính cá nhân.\n- Chủ động, ham học hỏi, chăm chỉ, tư duy tốt.\n\nNice to have\n- Đã từng thực tập vị trí tương đương là một lợi thế;\n- Ưu tiên ứng viên có dự án cá nhân.\n- Có hiểu biết về các mô hình MVC, MVVM\n- Ưu tiên ứng viên đã từng làm việc với các ngôn ngữ lập trình như: NodeJS, PHP, ReactJS.\n- Ưu tiên ứng viên đã từng làm việc với các database như MySQL, PostgreSQL, MongoDB\n\n-Được training on job, tham gia trực tiếp vào các dự án thực tế của công ty ngay trong thời gian đào tạo.\n-Được hỗ trợ thủ tục dấu đỏ, giấy xác nhận thực tập.\n-Được đào tạo kỹ năng lập trình web, mobile để lựa chọn ngôn ngữ lập trình phù hợp.\n-Thử sức với các dự án hấp dẫn trong và ngoài nước.\n-Được làm việc trong môi trường cởi mở, năng động.\n-Cơ hội trở thành nhân viên chính thức sau khi hoàn thành khóa đào tạo.\n-Lộ trình: thực tập (tối thiểu 3 tháng) -> Thử việc (2 tháng) -> Nhân viên chính thức.\nQuyền lợi sau khi ký hợp đồng chính thức:\n-Mức lương khởi điểm hấp dẫn, tương xứng với năng lực làm việc.\n-Vé xe hàng tháng tại công ty.\n-Được hưởng đầy đủ các chế độ bảo hiểm, bảo hiểm y tế theo luật Việt Nam và quy định của công ty.\n-Công ty cung cấp đầy đủ thiết bị máy tính để làm việc.\n-Đánh giá tăng lương định kỳ từ 6 tháng/lần (tháng 3 và tháng 9).\n-Tối thiểu 13 tháng lương, thưởng định kỳ ngày lễ 30/4, 2/9,...\n-Hoạt động thể thao, câu lạc bộ bóng đá được công ty hỗ trợ.\n-Khám sức khỏe định kỳ 1 năm/1 lần.\n-Nghỉ thứ 7, chủ nhật + 12 ngày phép/năm.\n-Thời gian làm việc từ đủ 3 năm sẽ được cộng thêm 1 ngày phép vào các năm tiếp theo.\n-Nghỉ ngày lễ Tết, 30/4, giỗ tổ Hùng Vương, Tết dương lịch,...\n-Team building hàng tháng, du lịch hàng năm, sinh nhật hàng tháng cho nhân viên.\n-Môi trường làm việc thoải mái theo phong cách Âu Mỹ (Western Style) với chế độ môi trường vui vẻ, thoải mái;\n-Được làm việc với thời gian linh hoạt từ T2 – T6 (9h – 18h), nghỉ trưa 1h30p.\n-Cơ hội học hỏi và phát triển năng lực bản thân thông qua những dự án thực tế.\n\n- Hà Nội: Số 20A, phố Huy Du, P.Cầu Diễn, Nam Từ Liêm\n\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2596, 1229, 2, 'Frontend Developer', 'Mô tả công việc\n- Tham gia phát triển giao diện người dùng cho các ứng dụng web trên nền tảng ASP.NET và Blazor.\n- Phối hợp với team Backend để tích hợp API, xử lý dữ liệu và tối ưu trải nghiệm người dùng.\n- Đảm bảo hiệu năng, khả năng phản hồi và khả năng mở rộng của giao diện người dùng.\n- Tham gia vào quy trình phân tích, thiết kế và đề xuất giải pháp kỹ thuật cho sản phẩm.\n- Tối ưu code, review code, viết unit test và đảm bảo tuân thủ coding standards của dự án\n\nYêu cầu ứng viên\n- Có kinh nghiệm từ 3 năm phát triển frontend sử dụng ASP.NET (Razor/Blazor).\n- Hiểu rõ về C#, .NET Core, Entity Framework, WebAssembly là một lợi thế.\n- Thành thạo HTML5, CSS3, JavaScript, Bootstrap hoặc các UI framework tương tự.\n- Có kinh nghiệm làm việc với RESTful API.\n- Tư duy logic tốt, khả năng giải quyết vấn đề và chủ động trong công việc.\n- Ưu tiên ứng viên từng làm việc trong môi trường Agile/Scrum.\n- Tinh thần, thái độ làm việc hợp tác\n- Có tổ chức và tinh thần tích cực thúc đẩy team\n- Chú trọng vào kết quả công việc\n- Có đam mê, không e ngại công cụ và công nghệ mới.\n\nQuyền lợi\n- Mức lương hấp dẫn, review định kỳ 2 lần/năm.\n- Làm việc trong môi trường công nghệ hiện đại, chuyên nghiệp.\n- Thưởng theo hiệu suất và các chính sách phúc lợi cạnh tranh.\n- Tham gia các dự án đa dạng về công nghệ, cơ hội phát triển lên vị trí Leader hoặc Fullstack Developer.\n- Được đào tạo nâng cao kỹ năng lập trình, soft skills và các công nghệ mới.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tòa nhà SBI, Đường 03, CVPM Quang Trung, P. Tân Chánh Hiệp, Quận 12\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2 - Thứ 6 ( 8h00 -17h00)\nThứ 7 (8h00 - 12h) - Làm online\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2597, 1131, 2, 'Backend Developer', '-Thiết kế và phát triển: Xây dựng kiến trúc backend và các API hỗ trợ cho các ứng dụng và dịch vụ frontend.\n- Phát triển tính năng: Tham gia phát triển các tính năng mới của hệ thống backend và cải tiến các chức năng hiện có theo yêu cầu của dự án.\n- Tối ưu hóa mã nguồn: Cải thiện hiệu suất mã nguồn và đảm bảo hệ thống hoạt động ổn định.\n- Tích hợp hệ thống: Làm việc với nhóm frontend và QA để tích hợp các dịch vụ backend với các hệ thống frontend và đảm bảo tính đồng nhất.\n- Bảo trì hệ thống: Hỗ trợ giám sát và khắc phục các sự cố kỹ thuật để đảm bảo tính ổn định và hiệu quả của hệ thống backend.\n- Quản lý cơ sở dữ liệu: Thiết kế và tối ưu hóa cơ sở dữ liệu, xử lý dữ liệu lớn và đảm bảo tính toàn vẹn của dữ liệu.\n\nYêu cầu ứng viên\n- Tốt nghiệp Cao đẳng trở lên chuyên ngành Công nghệ thông tin, Điện tử viễn thông hoặc tương đương.\n- Kinh nghiệm: 2-4 năm kinh nghiệm phát triển backend với các công nghệ và frameworks như Java, Python, Node.js hoặc tương đương.\n- Kỹ năng lập trình: Thành thạo một hoặc nhiều ngôn ngữ backend (Java, Python, Node.js, Go, v.v.), có kinh nghiệm làm việc với API RESTful.\n- Cơ sở dữ liệu: Hiểu biết về các hệ quản trị cơ sở dữ liệu JAVA, SQL và NoSQL như MySQL, PostgreSQL, MongoDB, v.v.\n- Kiến thức về kiến trúc hệ thống: Có kiến thức cơ bản về microservices và các mô hình thiết kế hệ thống backend.\n- Công nghệ DevOps: Có kinh nghiệm cơ bản với các công cụ CI/CD, Docker hoặc các công nghệ tương tự là một lợi thế.\n- Bảo mật: Có hiểu biết cơ bản về bảo mật dữ liệu và bảo mật API.\n- Kỹ năng mềm: Kỹ năng làm việc nhóm tốt, cởi mở trong giao tiếp và chủ động học hỏi.\n\nQuyền lợi\n- Mức lương cạnh tranh,\n- Lương tháng 13\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop….\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Làm việc thứ 2 đến sáng Thứ 7\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Khám sức khỏe định kỳ 1 lần/năm\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm\n- Làm việc với tác đối tác lớn\n- Review tăng lương định kỳ hàng năm (1 lần / năm)\n\nĐịa điểm làm việc\n- Hà Nội: 19 Vũ Trọng Phụng, Thanh Xuân, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2598, 1389, 2, 'Frontend Developer', 'Mô tả công việc:\n- Phát triển giao diện người dùng cho các ứng dụng web hướng đến thị trường Hàn Quốc.\n- Tham gia vào các dự án sử dụng công nghệ Vue3, DevExtreme, Ant Design, TypeScript, GraphQL, REST API, Node.js.\n- Thiết kế và hiện thực các UI/UX hiện đại, thân thiện và hiệu quả.\n- Hợp tác với team backend, designer và QA để đảm bảo chất lượng sản phẩm.\n- Có thể tham gia các dự án mobile sử dụng React Native (nếu có).\n- Tự nghiên cứu công nghệ mới, cải tiến quy trình phát triển và đề xuất giải pháp kỹ thuật phù hợp.\n\nYêu cầu ứng viên:\n- CHỈ TUYỂN ỨNG VIÊN ĐÃ CÓ KINH NGHIỆM LÀM VIỆC ÍT NHẤT 1 HOẶC 2 DỰ ÁN VỚI VUE3 HOẶC NẮM CHẮC KIẾN THỨC VUE2.\n- Tối thiểu 4 năm kinh nghiệm làm việc với frontend, ưu tiên với Vue3.\n- Thành thạo TypeScript, HTML, CSS/SCSS.\n- Có kinh nghiệm làm việc với các thư viện UI như DevExtreme, Ant Design...\n- Hiểu biết tốt về kiến trúc SPA, quản lý state, tối ưu performance frontend.\n- Biết sử dụng GraphQL, REST API.\n- Có kiến thức cơ bản về Node.js là một lợi thế.\n- Có khả năng tự nghiên cứu, tìm kiếm và giải quyết vấn đề độc lập.\n- Chủ động, trách nhiệm trong công việc. Ham học hỏi, có tinh thần cầu tiến.\n- Biết ứng dụng AI (như ChatGPT, Copilot...) vào công việc để tăng hiệu quả là một lợi thế.\n\nQuyền lợi:\n- Làm việc với các dự án thực tế cho khách hàng Hàn Quốc.\n- Môi trường làm việc chuyên nghiệp, cởi mở, đề cao tinh thần chủ động.\n- Lương thưởng cạnh tranh theo năng lực.\n- Review định kỳ, cơ hội phát triển lên các vị trí team lead, kỹ thuật chuyên sâu.\n- Phụ cấp nếu có các loại bằng hoặc chứng chỉ.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 3 - A24 Ngõ 385 Hoàng Quốc Việt, Phường Nghĩa Tân, Cầu Giấy.\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 07:30 đến 16:30).\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2599, 1301, 2, 'Kỹ Thuật Viên Lập Trình Và Vận Hành Máy CNC', '- Xây dựng bản vẽ, quy trình công nghệ để gia công chi tiết.\n- Tối ưu quy trình công nghệ, đạt hiệu quả gia công về thời gian, chất lượng, tối ưu dụng cụ cắt gọt.\n- Thực hiện lập trình & xuất chương trình và gia công.\n- Điều chỉnh, sửa chương trình ngay khi phát hiện sự cố, đảm bảo thời gian chạy máy CNC.\n- Định mức thời gian hoàn thành mỗi công đoạn gia công: Phay, Tiện.\n- Thực hiện các công việc khác khi được cấp trên yêu cầu.\n\nYêu cầu ứng viên:\n- Tốt nghiệp trung cấp trở lên, nhanh nhẹn, nhiệt tình trong công việc;\n- Đọc tốt bản vẽ kỹ thuật, Lập trình 2D+3D. Sử dụng thành thạo phần mềm CAD/CAM.\n- Có kinh nghiệm ít nhất 1 năm về thiết kế, lập trình máy CNC; 2 năm vận hành máy CNC.\n- Có đam mê với nghề kỹ thuật.\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, Hass.\n\nQuyền lợi:\n- Có cơ hội phát triển nghề nghiệp tại công ty.\n- Làm việc trong môi trường năng động, chuyên nghiệp;\n- Cung cấp đồng phục, trang thiết bị đầy đủ để phục vụ công việc;\n- Thưởng các dịp Quốc tế Lao động 1/5, Quốc khánh 2/9, Tết dương lịch, Thưởng Tết theo quy định của công ty.\n- Được đóng đầy đủ BHXH, BHYT, BHTN;\n- Đi du lịch nghỉ mát hàng năm;\n- Tham gia các hoạt động văn hóa thể thao (bóng đá, chạy...);\n- Hỗ trợ ăn cơm trưa tại Công ty;\n- Hỗ trợ tiền điện thoại, công tác phí khi đi gặp Khách Hàng, đi công tác;\n- Nghỉ Chủ nhật và 1 thứ 7 trong tháng.\n\nĐịa điểm làm việc:\n- Hà Nội: Lô 5 +6 KCN Lai Xá, Xã Kim Chung, Hoài Đức.\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nNghỉ Chủ nhật và 1 thứ 7 trong tháng.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2600, 1390, 2, 'Java Developer', 'Mô tả công việc:\n- Develop minor and simple components or modules of the products\n- Use common development tools such as compilers, debuggers, profiling tools and source control system as prescribed by the engineering standards.\n- Participate in the meetings, training programs.\n- Report to Leader and Line Manager.\n\nYêu cầu ứng viên:\n- Graduated from College or University majoring in Information Technology, Computer Science, Computer Engineering or any other IT-related fields\n- 5+ years experience as Java EE Developer (HTML/JavaScript/CSS, Spring Framework/Spring Boot, JPA or Hibernate, ANSI SQL or PostgreSQL) or equivalent backend tech stack\n- Good design documentation is required.\n- Strong problem-solving skill, with a logical, analytical and approach to work.\n\nQuyền lợi:\n- Hybrid working mode\n- Salary will be based on agreement, with full salary during probation.\n- Social insurance based on full salary.\n- Once-yearly bonuses and annual salary review.\n- Premium health care insurance coverage for staff and family.\n- Regular health check-ups.\n- 36+ days of paid leave per year\n\nĐịa điểm làm việc:\n- Hà Nội: HITC Building - 239 Xuân Thủy, Dịch Vọng Hậu, Cầu Giấy\n- Hồ Chí Minh: 8th floor, Saigon Trade Center, 37 Ton Duc Thang Street, Ben Nghe Ward, Quận 1\n- Đà Nẵng: 11th Floor - Vietinbank Building, 36 Tran Quoc Toan Street, Hai Chau Ward, Hải Châu\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy, Hồ Chí Minh, Quận 1, Đà Nẵng, Hải Châu', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2601, 1391, 2, 'Lập Trình Viên .NET', '1. Tham gia xây dựng, phát triển các dự án phần mềm mới của công ty \n2. Bảo trì, nâng cấp, cập nhật các dự án phần mềm hiện có \n3. Hỗ trợ vận hành, tìm hiểu nhu cầu và phản hồi từ người sử dụng để đề xuất các cập nhật, nâng cấp hoặc xây mới cần thiết \n4. Chủ động ước lượng và kiểm soát công việc đã nhận \n5. Tham gia nghiên cứu và trình bày các công nghệ mới \n6. Báo cáo và thực hiện các công việc theo yêu cầu của quản lý\n\nYêu cầu ứng viên\n1. Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin hoặc tương đương \n2. Có ít nhất 1 năm kinh nghiệm với ASP.NET, MVC5, ASP.NET Core, C++/C#, Web API, RESTful API \n3. Có kinh nghiệm lập trình với hệ CSDL: SQL server, MySQL, và 1 số No-SQL: Elasticsearch, Redis \n4. Thành thạo HTML, CSS, Bootstrap, Javascript, Jquery. Đã làm việc với Angular hoặc ReactJS \n5. Có kinh nghiệm làm việc với Kafka, RabbitMQ là một lợi thế. \n6. Làm việc nhóm hiệu quả với công cụ Git, Gitflow hoặc TortoiseSVN \n7. Tiếng Anh giao tiếp, đọc viết tốt \n8. Có khả năng giao tiếp tốt, chủ động, trung thực, năng động, khả năng làm việc nhóm tốt. Có trách nhiệm cao, và chịu được áp lực công việc \n9. Có khả năng học hỏi nhanh, thích tìm hiểu và thực hiện các công việc mới\n\nQuyền lợi\nLương: up to 20.000.000 (thương lượng)\nNgày nghỉ lễ theo quy định của Nhà nước\nThời gian làm việc 8:30 đến 17:30 từ thứ 2 đến thứ 6, thứ 7 cách tuần (nghỉ trưa 1h30)\nTham gia bảo hiểm xã hội đầy đủ cho nhân viên trên tổng lương. Ngoài ra có thêm gói bảo hiểm sức khỏe mở rộng và hỗ trợ gói tập sức khỏe cho nhân viên\nReview lương: 2 lần/ năm, thưởng hè + thưởng Tết...\nDu lịch công ty, teambuilding, tiệc sinh nhật hàng tháng và các phúc lợi khác\n\nĐịa điểm làm việc\n- Hà Nội: Bằng Liệt, Hoàng Mai\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 18:00)\nThứ 7 cách tuần\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2602, 397, 2, 'Senior Software Engineer', 'MỤC TIÊU CÔNG VIỆC: Thiết kế và phát triển các ứng dụng Java hiệu suất cao cho hệ thống LOS/CRM, đóng góp vào toàn bộ vòng đời phát triển phần mềm và cung cấp các giải pháp phần mềm có thể mở rộng và chất lượng cao.\nNHIỆM VỤ, TRÁCH NHIỆM CHÍNH:\nCộng tác với các đơn vị nghiệp vụ, bao gồm kiến trúc sư phần mềm, quản lý sản phẩm, các đơn vị kinh doanh, thiết kế để phát triển các ứng dụng Java.\nThiết kế và triển khai ứng dụng bằng ngôn ngữ Java hiệu quả và đáng tin cậy, đảm bảo hiệu suất và bảo mật.\nThực hiện đánh giá mã nguồn để duy trì chất lượng và tuân theo các tiêu chuẩn mã hóa.\nGỡ lỗi, khắc phục sự cố và giải quyết các nhược điểm và sự cố phần mềm, đảm bảo độ tin cậy của ứng dụng.\nTham gia phân tích yêu cầu và thảo luận thiết kế phần mềm để đề xuất các giải pháp sáng tạo.\nPhát triển và duy trì tài liệu kỹ thuật để tham khảo và báo cáo.\nCập nhật thông tin về xu hướng công nghệ liên quan đến Java, các cách thực hành tốt nhất và tiêu chuẩn ngành.\nXác định tầm nhìn kỹ thuật cho việc phát triển phần mềm, phù hợp với mục tiêu kinh doanh và thực tiễn tốt nhất của ngành.\nCộng tác với các nhà phát triển khác để xây dựng các giải pháp phần mềm có thể mở rộng và hiệu quả.\nGóp phần vào toàn bộ vòng đời phát triển phần mềm, từ khái niệm và thiết kế đến thử nghiệm, triển khai và hỗ trợ.\nYêu cầu ứng viên: Bằng cử nhân về Khoa học máy tính, Kỹ thuật phần mềm hoặc lĩnh vực liên quan trở lên. Đã có kinh nghiệm tương đương trong vai trò kỹ sư cao cấp phát triển phần mềm với ngôn ngữ Java, ưu tiên nếu có thêm kinh nghiệm phát triển phần mềm với ngôn ngữ PHP. Ưu tiên am hiểu lĩnh vực tài chính ngân hàng, hệ thống LOS. Thông thạo các nguyên tắc phát triển phần mềm, lập trình hướng đối tượng và các cách thực hành tốt nhất của Java.\nKỹ năng thiết kế cơ sở dữ liệu và SQL (ví dụ: MySQL, PostgreSQL, Oracle).\nKỹ năng phát triển ứng dụng web (HTML, CSS, JavaScript).\nThành thạo quy trình kiểm thử, gỡ lỗi và khắc phục sự cố phần mềm.\nKỹ năng về các công nghệ container hóa và điều phối quy trình (ví dụ: Docker, Kubernetes).\nThành thạo hệ thống kiểm soát phiên bản (ví dụ: Git).\nThành thạo về BPMN, DMN, lược đồ cơ sở dữ liệu, giao thức truyền thông hệ thống như HTTP, Restful API, Dịch vụ web. Có kinh nghiệm với các nền tảng và dịch vụ đám mây (ví dụ: AWS, Azure) là một lợi thế. Khả năng làm việc theo nhóm / tổ chức. Khả năng làm việc hiệu quả trong sự thay đổi. Khả năng lập kế hoạch và tổ chức. Kỹ năng giải quyết vấn đề.\nQuyền lợi: LÝ DO ĐỒNG HÀNH CÙNG SHBFINANCE: Môi trường làm việc chuyên nghiệp, cởi mở. Thời gian làm việc từ thứ 2 – thứ 6, nghỉ trưa 1h30’ (40h/tuần). Chế độ làm việc Hybrid working từ 1 -  2 ngày làm việc từ xa/ tuần. Đồng nghiệp thân thiện, cởi mở với tư duy đề cao sự phát triển của mỗi cá nhân; Văn phòng làm việc với không gian mở, rộng rãi, được cung cấp đầy đủ các trang thiết bị để phục vụ cho công việc. Quan tâm đặc biệt đến nhân viên: Gói đãi ngộ cạnh tranh cùng chính sách nâng lương theo định kỳ. Tổng thu nhập TB 14 tháng lương/năm; Hỗ trợ ăn trưa lên tới 1.200.000 VND/tháng; Hỗ trợ gửi xe 200.000 VND/ tháng. Nghỉ hưởng lương ngày sinh nhật + quà sinh nhật. Quyền lợi chăm sóc sức khỏe đặc quyền bảo hiểm sức khỏe toàn diện SHBFC Care; Khám sức khỏe thường niên tại bệnh viện hàng đầu Việt Nam; Du lịch thường niên, hoạt động team building năm. Tập trung hỗ trợ sự phát triển cá nhân: Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng các cấp quản lý tài năng, giàu kinh nghiệm; Cơ hội tham gia các dự án lớn, đối tác quốc tế, đi đầu trong lĩnh vực tài chính tiêu dùng; Chính sách hỗ trợ các hoạt động học tập, nâng cao trình độ ngoại ngữ, trao đổi, chia sẻ kiến thức, giao lưu văn hóa (Training, Seminar...). Địa điểm làm việc: - Hà Nội: 52 Lê Đại Hành, Hai Bà Trưng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2603, 1144, 2, 'Middle Ruby On Rails', 'Mô tả công việc\n- Participate in the development and maintenance of web applications based on Ruby on Rails.\n- Participating in requirements analysis, building solutions, developing software according to requirements customer demand.\n- Research and learn the features to provide customers with comprehensive solutions.\n\nYêu cầu ứng viên\n- At least 3 year of experience programming in Ruby on Rails.\n- Knowledge of SQL & NoSQL database systems.\n- Strong knowledge of Web (HTML, CSS, Javascript) and OOP.\n- Good use of source code management tools: SVN, GIT.\n- Experience in project development according to Agile/Scrum model.\n- Promote responsibility in work, good product quality awareness.\n- Passion for research, learning new technologies, self-development.\n- English level B1 or higher\n\nQuyền lợi\n- Income upto 25M\n- 2-month probation with 100% salary\n- Participate in social insurance, health insurance, unemployment insurance according to the provisions of the labor law\n- Salary review twice a year\n- Receive 13th month salary, bonuses for holidays, New Year, weddings, birthdays, etc.\n- Support for certification exam costs according to the company\'s regulations.\n- Participate in VBI insurance\n- Parking allowance\n- Seniority allowance, excellent project bonus\n- Annual travel and vacation according to the company\'s policy\n- Annual health check-up\n- Clear promotion opportunities\n- Opportunities to work in partner countries: Japan, Korea, Singapore, Australia...\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 10F Mekong Tower, 235 Cong Hoa, Ward 13, Tân Bình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2604, 1392, 2, 'Nhân Viên IT Phần Mềm', 'Mô tả công việc:\n- Xây dựng các hệ thống, công cụ dùng để quản lý, tối ưu hóa công việc trong nội bộ Công ty theo yêu cầu từ Công ty mẹ.\n- Cải tiến web nội bộ của công ty, thực hiện các yêu cầu nội bộ.\n- Đào tạo các thao tác liên quan đến hệ thống quản lý nội bộ cho nhân viên trong công ty.\n\nYêu cầu ứng viên:\n- Có từ 2 năm kinh nghiệm liên quan.\n- Sử dụng thành thạo một trong các hệ quản trị cơ sở dữ liệu MS SQL Server, Postgre SQL, Oracle...\n- Có kiến thức chuyên môn về: OOP, Database & Code Design, .Net, Entity Framework, Javascript, Jquery, Typescript, Angular, Bootstrap.\n- Thành thạo một trong các công cụ quản lý mã nguồn: GIT, SVN ...Có tư duy tốt về UI/UX.\n- Khả năng nắm bắt, nghiên cứu công nghệ mới nhanh.\n- Tư duy lập trình tốt, đam mê và mong muốn học hỏi trong lĩnh vực IT.\n- Có kỹ năng đọc hiểu tài liệu thiết kế phần mềm.\n- Có khả năng giải quyết vấn đề độc lập cao.\n- Có hiểu biết về kiểm thử phần mềm (Unit Test, Integration Test) là một lợi thế.\n- Có thể giao tiếp Tiếng Anh cơ bản. Biết tiếng Nhật là một lợi thế.\n- Ưu tiên ứng viên có kinh nghiệm lập trình App Mobile.\n\nQuyền lợi:\n- Cơ hội công việc:\n  - Thường xuyên được tham gia các buổi đào tạo của Công ty và bộ phận, qua đó nâng cao được kiến thức và kỹ năng công việc của bản thân.\n  - Có cơ hội sử dụng các phần mềm và thiết bị hiện đại.\n  - Thông qua mối liên hệ với các cơ sở trên toàn cầu của Công ty và công tác nước ngoài có thể mở rộng hiểu biết ra thế giới.\n\n- Lợi ích và các chế độ phúc lợi xã hội:\n  - Được tham gia BHXH, BHYT, BHTN, bảo hiểm 24/7 và các chế độ khác theo luật định.\n  - Thời gian làm việc: Từ 8:00-17:00, nghỉ 03 thứ Bảy & các Chủ nhật trong tháng, nghỉ lễ Tết theo quy định Luật Lao động.\n  - Có phụ cấp đi lại (600,000VNĐ/tháng)/ xe công ty đưa đón, ăn trưa tại Công ty.\n  - Tổ chức tiệc sinh nhật, Free Lunch hằng tháng, thường xuyên tổ chức các hoạt động giao lưu cho nhân viên.\n  - Du lịch hằng năm, thưởng 2 lần/năm.\n\nĐịa điểm làm việc:\n- Hải Phòng: Số 02 đường số 09 Khu Công nghiệp VSIP, Thủy Nguyên.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n- Làm việc từ thứ 2 đến thứ 6 và 1 thứ 7/ tháng.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2605, 272, 2, 'Fullstack Developer', 'Mô tả công việc\n- Thiết kế, phát triển, nâng cấp, bảo trì các dự án với công nghệ Java/ Angular/ ReatJS.\n- Đảm bảo hiệu suất, chất lượng, khả năng đáp ứng tốt nhất của hệ thống.\n- Tương tác với bộ phận kinh doanh, vận hành để hiểu nhu cầu của người sử dụng hệ thống.\n\nYêu cầu ứng viên\n1. Trình độ học vấn/Chứng chỉ\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Hệ thống thông tin hoặc các lĩnh vực liên quan.\n2. Kinh nghiệm làm việc\n- Có từ 2 năm kinh nghiệm trở lên trong lĩnh vực phân tích, thiết kế, phát triển, mô tả tài liệu, triển khai và thử nghiệm các hệ thống phần mềm với các công nghệ Java/ Angular/ ReactJS.\n3. Kiến thức/Kỹ năng/Năng lực chuyên môn\n- Có kinh nghiệm thực hiện các mẫu thiết kế Java EE như MVC, Singleton, Session Facade, DAO.\n- Kinh nghiệm trong lập trình đa luồng, collections, IO, mạng, JSP/Servlets và JDBC.\n- Có kinh nghiệm trong Spring Framework như Spring Boot, Spring MVC, Spring JDBC/Data, Spring Security.\n- Có kinh nghiệm cấu hình và triển khai ứng dụng trên nền tảng máy chủ Tomcat 7.0+.\n- Kinh nghiệm tốt với hệ quản trị dữ liệu quan hệ (RDBMS MySQL, PostgreSQL) và kỹ thuật ORM (JPA2, Hibernate).\n- Có kinh nghiệm trong phát triển Angular 12+ hoặc ReactJS 15+.\n- Có kinh nghiệm thiết kế giao diện frontend sử dụng HMTL5, JSP, CSS, JavaScript, jQuery và Ajax.\n- Có kiến thức về XML Suite of Technologies XML (XSL) và REST/JSON.\n- Có khả năng thiết kế, viết Stored procedure, Function, tunning database với MySQL.\n- Kinh nghiệm với các công cụ xây dựng và triển khai bao gồm Maven, logging và debugging bằng Log4j, Unit và Integration test sử dụng JUnit.\n- Có kiến thức về phát triển ứng dụng sử dụng Software Development Life Cycle SDLC bằng cách sử dụng các phương pháp khác nhau như Agile/Scrum.\n- Có khả năng phân tích tốt, lập kế hoạch chiến lược tốt và kỹ năng giao tiếp. Có động lực cao, nhiệt tình và tự tạo cảm hứng.\n- Có kinh nghiệm với Angular Progressive Web App (PWA).\n- Có kinh nghiệm với Angular Mobile App with Ionic, Capacitor hoặc React Native.\n- Có kinh nghiệm lập trình Asp .NET Core.\n- Có kinh nghiệm với Oracle, MS SQL Server.\n4. Năng lực cốt lõi\n- Có tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty (IPAM & 4C) \n\nQuyền lợi\n1. Cộng đồng những người làm nghề chính trực và dấn thân phụng sự \n- Môi trường làm nghề tài chính chuyên nghiệp.\n- Làm việc với tinh thần làm chủ, sáng tạo và thách thức. \n2. Tổng thu nhập theo năng lực\n- Thu nhập xứng đáng theo năng lực và giá trị đóng góp.\n- Xem xét thay đổi thu nhập hàng năm.  \n3. Chế độ đãi ngộ\n- Tham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động.\n- Được tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24. \n4. Tổ chức học tập và văn hóa sôi nổi\n- Không gian làm việc mở với trang thiết bị hiện đại. \n- Các hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2606, 1393, 2, 'Kỹ Sư Giải Pháp Phần Mềm Tích Hợp', 'Mô tả công việc\n\n- Giới thiệu các giải pháp về phần mềm tích hợp như API Management, MQ, Event Streaming, ESB… với khách hàng chủ yếu trong lĩnh vực Tài chính, Ngân hàng.\n- Phối hợp cùng các bạn kỹ sư Amigo, hãng, đối tác thực hiện demo, PoC tính năng sản phẩm, làm thầu, triển khai các dự án về giải pháp phần mềm tích hợp.\n- Nghiên cứu các giải pháp, công nghệ theo định hướng của công ty.\n- Các công việc khác theo yêu cầu.\n\nYêu cầu ứng viên\n\n- Tốt nghiệp ĐH chuyên ngành CNTT hoặc tương đương.\n- Có khả năng tư duy và giải quyết vấn đề độc lập.\n- Ham học hỏi, sẵn sàng nghiên cứu công nghệ mới.\n- Có mong muốn phát triển thành Solution Architecture trong tương lai.\n- Tiếng Anh giao tiếp cơ bản, đọc viết tốt.\n- Từ 1 năm kinh nghiệm làm việc trong lĩnh vực CNTT (kể từ khi tốt nghiệp).\n- Thành thạo ngôn ngữ lập trình Java và khả năng lập trình Restful API.\n- Có kiến thức cơ bản về Cơ sở dữ liệu quan hệ.\n\nƯu tiên:\n- Có kinh nghiệm làm việc với các chuẩn giao thức kết nối Socket, Http, Jms, FTP.\n- Có kiến thức chuyên sâu về Cơ sở dữ liệu quan hệ và NoSQL.\n- Sử dụng thành thạo các công cụ test API như Postman...\n- Có kinh nghiệm triển khai các dự án tích hợp sử dụng API hoặc Message Queue.\n- Có kinh nghiệm triển khai về một trong các giải pháp tích hợp/middleware như WebSphere Application Server, WebSphere MQ, API Management, ESB, Kafka...\n- Am hiểu về kiến trúc Microservice.\n- Am hiểu về kiến trúc J2EE.\n- Hiểu biết về các công cụ CI/CD.\n- Hiểu biết về các nền tảng container Docker/Kubernetes (K8S) hoặc OpenShift.\n\nQuyền lợi\n\n- Trở thành thành viên AMIGO bạn không chỉ được đảm bảo đầy đủ các chế độ phúc lợi BHXH, BHYT, BHTN, ngày nghỉ phép, lễ tết đầy đủ và trọn vẹn mà còn được hưởng chính sách Thu nhập và Đãi ngộ cạnh tranh trên thị trường, được làm việc trong môi trường chuyên nghiệp với những đồng nghiệp trẻ trung, nhiệt huyết, luôn đoàn kết, yêu thương và chia sẻ để mỗi ngày làm việc là một ngày hạnh phúc vì được cống hiến và phát triển.\n- Thu nhập tháng: Lương tháng + Thưởng KPI (20% lương tháng).\n- Gói thu nhập lên đến 17 tháng/năm. Đặc biệt đối với nhân viên Kinh doanh bạn còn có thêm Lương mềm theo Quý, Thưởng kinh doanh cuối năm ...\n- Các hoạt động khen thưởng định kỳ (tháng/quý/chương trình/ thành tích đặc biệt) như: “Man of the month”, “Ngôi sao sáng tạo”, Nhân viên/ team/ bộ phận/ phòng ban xuất sắc; Thưởng khi hoàn thành các khóa đào tạo/chứng chỉ chuyên môn... theo quy chế của công ty.\n- Bảo hiểm sức khỏe toàn diện hàng năm.\n- Thưởng các dịp Lễ, Tết, Sinh nhật...\n- Chế độ nghỉ mát/ Innovation/ Teambuilding hàng năm.\n- Gói Khám sức khỏe định kỳ lên đến 2.500.000 VNĐ/người/năm.\n- Định hướng phát triển nghề nghiệp với chương trình đào tạo chuyên môn và hỗ trợ thi các chứng chỉ quốc tế.\n- Định hướng công việc để trở thành Solution Architecture hàng đầu trong lĩnh vực cung cấp và triển khai các giải pháp tích hợp cho các khách hàng trong lĩnh vực Ngân hàng-Tài chính.\n\nĐịa điểm làm việc\n\n- Hà Nội: tầng 10, tòa nhà Indochina Plaza, số 241 Xuân Thủy, Cầu Giấy.\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2607, 1394, 2, 'Lập Trình Viên Java', 'Mô tả công việc:\n- Tiếp nhận yêu cầu từ quản trị dự án và lãnh đạo công ty.\n- Tham gia thiết kế, triển khai các dịch vụ/giải pháp của dự án.\n- Chịu trách nhiệm đảm bảo kiến trúc hệ thống và xử lý các vấn đề kỹ thuật của các dự án.\n- Để xuất các giải pháp công nghệ, công cụ áp dụng trong phát triển sản phẩm.\n- Chịu trách nhiệm chính về các công nghệ mới, hỗ trợ kỹ thuật cho các thành viên trong nhóm.\n- Hỗ trợ, đào tạo và nâng cao năng lực chuyên môn cho các thành viên.\n\nYêu cầu ứng viên:\n- Có ít nhất 4 năm kinh nghiệm với Java Spring\n- Có kiến thức về kiến trúc code tốt: OOP, Design Pattern, Design Principle, nắm vững Java Core\n- Ham tìm hiểu, có thể đọc được tài liệu kỹ thuật bằng tiếng Anh\n- Chính trực, nghiêm túc trong công việc\n- Ưu tiên đã có kinh nghiệm với AWS, VueJS/ReactJS\n\nQuyền lợi:\n- Chế độ đãi ngộ: Mức lương upto 45M\n- Nghỉ thứ 7, chủ nhật + ngày lễ, tết + 12 ngày phép/năm\n- Xét tăng lương 2 lần/năm vào tháng 1 và tháng 7, có năng lực sẽ được xét ngay tại thời điểm yêu cầu\n- Lương tháng 13, thưởng dự án, thưởng các dịp lễ, tết; thưởng giới thiệu nhân sự\n- Remote 2 ngày/tháng và trong một số trường hợp đặc biệt\n- Văn hóa và Môi trường làm việc: Môi trường trẻ trung, năng động, thoải mái, tạo điều kiện để cá nhân phát triển năng lực nhất có thể\n- Tham gia các hoạt động thể thao nâng cao sức khỏe, teambuilding, dã ngoại, nghỉ mát.\n- Free trà, cà phê..\n- Đào tạo và cơ hội thăng tiến: Công ty tổ chức buổi chia sẻ toàn công ty 1 lần/tháng nhằm nâng cao kỹ năng mềm và hiểu biết xã hội\n- Cơ hội phát triển lên Team leader\n- Được học hỏi nhiều kinh nghiệm về Kỹ thuật, quy trình, kỹ năng mềm từ người đi trước\n- Làm việc trực tiếp với CEO học hỏi tư duy về quản lý và kỹ năng chuyên môn\n- Được định hướng phát triển sự nghiệp theo Career Path của công ty.\n\nĐịa điểm làm việc:\n- Hà Nội: 61 Ngụy Như - Kon Tum, phường Nhân Chính, Thanh Xuân\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:15)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2608, 1395, 2, 'Database Developer', '● Tham gia phát triển các hệ thống web cho Ngân Hàng\n● Thực hiện các công việc được phân công:\n- Tham gia thiết kế/xây dựng các kho dữ liệu, mô hình dữ liệu (DataMart) và khai thác dữ liệu.\n- Phát triển các báo cáo quản trị\n● Tuân thủ các chính sách, quy trình, quy định, tiêu chuẩn về An toàn CNTT\n● Thực hiện các nhiệm vụ khác do Ban Lãnh đạo Khối CNTT giao\n● Nghiên cứu và cập nhật các kiến thức mới hỗ trợ cho công việc\n● Làm việc nhóm hoặc độc lập, giao tiếp với cấp trên và thành viên liên quan đến công việc\n\nYêu cầu ứng viên:\n● Có tối thiểu 3 năm kinh nghiệm (đặc biệt trong các dự án ngân hàng)\n● Có kiến thức tốt về quản trị ứng dụng trên nhiều nền tảng công nghệ\n● Có kiến thức về cơ sở dữ liệu: Oracle, SQL\n● Thành thạo sử dụng các công cụ: Confluent, MinIO, Kafka, Iceberg, Dremio GoldenGate\n● Có kiến thức về PL/SQL, Oracle Function, Procedure, Package\n● Có kiến thức về Oracle BI, Oracle warehouse builder, SAP Business Object, Power BI, Tabular, Python, Kapka. Pentaho là lợi thế\n\nQuyền lợi:\n● Làm việc từ thứ 2 đến thứ 6\n● Offer: 23,000,000VNĐ - 30,000,000VNĐ Net/ tháng\n● Không cần thử việc, ký luôn hợp đồng chính thức và đóng bảo hiểm từ tháng đầu nhận việc\n● Cố định 13 tháng lương Net/ năm\n● Được tham gia vào các dự án lớn của Ngân hàng\n● Có lộ trình phát triển, thăng tiến rõ ràng đánh giá theo level nhân sự từ member => key member => Teamlead\n● Thưởng lễ tết; Quy đổi phép thành tiền/ cộng dồn phép\n● Có cơ hội tiếp cận và học hỏi công nghệ mới\n● Môi trường công bằng, đảm bảo mọi người đều có thể phát huy hết khả năng của mình\n● Được làm việc với những cá nhân xuất sắc, có nhiều kinh nghiệm.\n● Được hưởng Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n● Khám sức khỏe định kỳ 1 năm/1 lần\n● Chế độ du lịch hàng năm', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2609, 1130, 2, 'Middle Mobile Developer (IOS/Flutter)', 'Mô tả công việc\n- Thiết kế, xây dựng và tối ưu kiến trúc hệ thống mobile (IOS hoặc Flutter).\n- Refactor toàn bộ codebase cũ để nâng cao tính maintainable, scalability và performance.\n- Tối ưu hiệu suất, giảm thiểu lỗi, nâng cao trải nghiệm người dùng.\n- Xây dựng các mô-đun core, SDK tái sử dụng cho hệ sinh thái sản phẩm học tập.\n- Làm việc chặt chẽ với Product Manager, Design, Backend để định hướng chức năng và trải nghiệm của sản phẩm.\n- Góp phần vào roadmap sản phẩm mobile, đảm bảo tiến độ & chất lượng kỹ thuật.\n- Đề xuất công nghệ, framework, quy trình phù hợp cho từng giai đoạn phát triển.\n- Hỗ trợ kỹ thuật và mentoring cho các bạn Developer trong team mobile.\n- Xây dựng quy chuẩn coding, review code, đào tạo kỹ năng phát triển sản phẩm mobile.\n- Định hướng phát triển cá nhân, thúc đẩy tinh thần làm việc nhóm.\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc liên quan.\n- Có 3-5 năm kinh nghiệm phát triển mobile. Thành thạo một hoặc nhiều nền tảng:Swift (iOS) hoặc Flutter (Dart)\n- Kinh nghiệm thiết kế kiến trúc app (MVVM, Clean Architecture), quản lý module, xử lý hiệu năng & nợ kỹ thuật.\n- Có ít nhất 2 năm kinh nghiệm làm việc trong công ty product.\n- Hiểu sâu về testing, CI/CD, deployment mobile.\n- Ưu tiên có kinh nghiệm quản lý team, làm việc với team size từ 5 người trở lên là một điểm cộng\n- Kinh nghiệm làm việc với sản phẩm lớn có hàng trăm ngàn đến hàng triệu người dùng.\n- Tư duy sản phẩm và kỹ năng làm việc đa chức năng với các team (Design, PM, Marketing,...).\n- Kinh nghiệm quản lý team kỹ thuật hoặc định hướng trở thành Head of Mobile trong tương lai gần.\n- Đã làm việc trong môi trường startup hoặc product-first.\n- Kỹ năng trình bày, giao tiếp tốt và khả năng tự học mạnh.\nQuyền lợi\n1. Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm theo năng lực.\n2. Chế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn\n- Tham gia BHXH sau thử việc, 12 ngày phép năm.\n- Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ.\n- Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết...\n- Học miễn phí các sản phẩm ngôn ngữ của công ty.\n3. Cơ hội phát triển bản thân\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Môi trường product đi sâu chuyên môn về mobile app, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác marketing, sales, chăm sóc khách hàng và khách hàng\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp\n- Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6\nĐịa điểm làm việc\n- Hà Nội: 315 Trường Chinh, Thanh Xuân\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2610, 165, 2, 'Flutter Developer', 'Về KiotViet: Sản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ. Với 15 năm và hơn 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm. Bạn sẽ làm gì: - Phát triển các dự án phần mềm công ty trên nền tảng Flutter Cross-Platform (Android/iOS) - Thực hiện các nhiệm vụ khác liên quan đảm bảo tiến độ dự án Yêu cầu ứng viên - Tốt nghiệp đại học ưu tiên chuyên ngành CNTT hoặc chuyên ngành liên quan; - Có kinh nghiệm Flutter từ 2 năm trở lên; - Thành thạo state management (Provider, Riverpod, Bloc...). - Hiểu biết hoặc đã từng làm việc với kiến trúc MVVM, Clean Architecture. - Có kinh nghiệm làm việc với: REST API, Firebase, Isar. - Native Android (Kotlin/Java) và/hoặc iOS (Swift/Obj-C) và custom plugin. - Nắm rõ Push notification, background tasks, deep link, crash tracking. - Biết viết unit test là lợi thế. Quyền lợi - Mức lương khởi điểm hấp dẫn, tương xứng với năng lực và kinh nghiệm làm việc; - Thưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm. - Làm việc từ Thứ 2 – Thứ 6, làm việc 8h/ngày và checkin linh hoạt từ 8h-9h; - Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...) - Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm; - Chăm sóc sức khoẻ: Khám sức khoẻ định kỳ hàng năm, Bảo hiểm sức khoẻ cao cấp dành cho Level 3-3 trở lên theo quy định của công ty; - Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi; - Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại; - Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng. Địa điểm làm việc - Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm Thời gian làm việc - Thứ 2 - thứ 6 có ca làm việc linh hoạt từ 8h00-9h00 đến 17h30-18h30, làm đủ 8 tiếng. Cách thức ứng tuyển Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2611, 1396, 2, 'Chuyên Viên Lập Trình', 'About this Role:\nWe are seeking a skilled JavaScript Developer with a solid background in cloud-based application development in GCP, specifically using Google Developer tools. The ideal candidate has a strong understanding and use of Google API library, OAuth vs JWT authentication mechanisms, and hands-on experience with ReactJS preferred but other frameworks (Angular, Vue) are acceptable.\nIf you\'re passionate about building scalable web apps and have delivered impactful projects, we’d love to meet you!\n\nKey Responsibilities:\n- Design and develop front-end and/or back-end components using JavaScript and a modern framework, preferably ReactJS other frameworks (Angular, Vue, etc.) are acceptable\n- Integrate third-party and internal RESTful APIs and ensure secure, scalable data flow\n- Work with Google Cloud and Developer tools (such as Firebase, Cloud Functions, Cloud Storage, etc.) to build cloud-native applications\n- Implement and integrate applications using OAuth and JWT-based authentication flows\n- Collaborate with cross-functional teams to define and ship new features\n- Debug and optimize existing applications for speed, scalability, and usability\n- Maintain clear documentation for all development work and project progress\n\nKey Requirements:\n- 2 years of professional JavaScript development experience\n- Proficient in at least one JavaScript framework (e.g., React, Angular, Vue)\n- Strong experience working with Google Cloud Platform (GCP) and Google Developer tools and services\n- Solid experience with RESTful APIs integration\n- Clear understanding of OAuth vs JWT – use cases, flows, and security implications\n- Must be able to communicate effectively in English and Vietnamese\n- Familiar with Git, CI/CD, and agile workflows\n- Strong problem-solving and interpersonal skills\n- Immediate availability is a strong plus\n\nBenefits:\n- Work on cutting-edge, cloud-native applications\n- Collaborative, international team environment\n- Fast-paced learning and direct product impact\n- Competitive compensation\n\nWork location: Hà Nội: Nguyễn Chí Thanh, Đống Đa\nWorking hours: Monday - Friday (from 08:30 to 18:00)\nApplication method: Candidates submit their online application by clicking the "Apply" button below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2612, 1397, 2, 'Lập Trình Viên .NET', 'Mô tả công việc:\n- Tiếp nhận thông tin dự án\n- Khảo sát, phân tích, thiết kế hệ thống dự án\n- Lập trình ứng dụng cho dự án\n- Triển khai ứng dụng sau khi xây dựng xong\n- Tham gia nghiên cứu và trình bày các công nghệ mới liên quan đến các dự án của công ty.\n- Hỗ trợ, đào tạo các thành viên trong nhóm lập trình\n\nYêu cầu ứng viên:\n- Thành thạo .NET, ngôn ngữ lập trình C#.\n- Sử dụng thành thạo SQL Server.\n- Có khả năng phân tích thiết kế hệ thống, thiết kế database.\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin.\n- Ưu tiên các ứng viên đã có kinh nghiệm tham gia lập trình, triển khai các dự án về phần mềm quản trị doanh nghiệp.\n- Có tính cách cẩn thận, tỉ mỉ, tư duy logic nhanh, có kỹ năng làm việc nhóm tốt, có trách nhiệm trong công việc.\n- Có khả năng làm việc độc lập.\n\nQuyền lợi:\n- Môi trường làm việc thoải mái, năng động, thời gian làm việc (8h-17h, trưa nghỉ 1h)\n- Phép năm theo quy định của pháp luật. Đầy đủ các chế độ về BHXH, BHYT, BHTN. Chế độ khám sức khỏe hàng năm.\n- Review lương hàng năm theo năng lực làm việc\n- Du lịch hàng năm, tổng kết cuối năm, liên hoan kỷ niệm sinh nhật công ty...\n- Thưởng lễ tết (thưởng 2/9, tết dương lịch, tết lao động, tết âm lịch)\n\nĐịa điểm làm việc:\n- Thái Nguyên: 434 Bắc Kạn, phường Hoàng Văn Thụ, TP Thái Nguyên\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2613, 1398, 2, 'Python Developer', 'Mô tả công việc:\n- Tham gia thiết kế và phát triển API cho các ứng dụng quản lý nhân sự HRM\n- Xây dựng và tối ưu hóa các API, Microservices\n- Nghiên cứu, học hỏi các công nghệ mới phục vụ nhu cầu dự án\n- Thực hiện các công việc khác theo yêu cầu của quản lý sản phẩm\n\nYêu cầu ứng viên:\n- Tốt nghiệp các trường chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin ..\n- Có ít nhất 2 năm kinh nghiệm & thành thạo ngôn ngữ lập trình Python.\n- Có ít nhất 1 năm với một trong các framework Python như: FastAPI, Flask, Django...\n- Có kinh nghiệm làm việc với các hệ cơ sở dữ liệu: PostgreSQL, MongoDB, MySQL...\n- Có kinh nghiệm làm việc với hệ thống message queue như Celery, Redis Queue\n- Hiểu biết về các kiến trúc phát triển phần mềm: Microservices, Monolithic\n- Thành thạo công cụ quản lý mã nguồn Git. Viết tài liệu cho API\n- Sử dụng các công cụ như JIRA, Clickup hoặc Redmine để quản lý công việc\n- Đam mê, chủ động trong công việc, có kỹ năng làm việc nhóm và làm việc độc lập\n- Có khả năng quản lý, sắp xếp, điều phối và đốc thúc công việc\n- Có khả năng đọc hiểu các tài liệu bằng tiếng Anh\n- Ưu tiên các ứng viên trẻ từ 2000\n\nQuyền lợi:\n- Mức lương thỏa thuận, được trả theo năng lực thực tế\n- Được tham gia vào môi trường văn hóa năng động, chuyên nghiệp\n- Hưởng đầy đủ các chế độ theo Luật Lao Động: Nghỉ lễ, tết, phép năm, hiếu, hỷ...\n- Tham gia BHXH - BHYT - BHTN theo quy định của Nhà nước, bảo hiểm tai nạn UIC, bảo hiểm sức khỏe PTI\n- Được chăm sóc tiếp sức với tủ thức ăn đầy ắp vào cuối tháng\n- Được cấp phát Laptop, đồng phục thực hiện công việc\n- Có lộ trình thăng tiến rõ ràng\n\nĐịa điểm làm việc:\n- Hà Nội: 106 Hoàng Quốc Việt, Nghĩa Đô, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2614, 1399, 2, 'Lập Trình Viên', '1. Phát triển và bảo trì mã nguồn:\nXây dựng, phát triển giao diện người dùng và các trang web sử dụng HTML/CSS.\nTạo các chức năng tương tác trên trang web bằng JavaScript.\nPhát triển và triển khai ứng dụng web với PHP.\nXây dựng và tối ưu hóa các ứng dụng hoặc phần mềm nhúng sử dụng C/C++.\nLập trình và triển khai các ứng dụng sử dụng ngôn ngữ Python.\n\n2. Chịu trách nhiệm về framework:\nQuản lý, phát triển và bảo trì các ứng dụng sử dụng framework Django.\nThiết kế, xây dựng và tối ưu hóa các mô-đun và API trong Django để đáp ứng yêu cầu dự án.\n\n3. Kiểm tra và sửa lỗi:\nThực hiện kiểm tra mã nguồn để phát hiện và khắc phục lỗi.\nĐảm bảo các sản phẩm phần mềm hoạt động ổn định và hiệu quả.\nHoàn thành nhiệm vụ được cấp trên giao.\n\nYêu cầu ứng viên:\nThành thạo các ngôn ngữ lập trình: HTML/CSS; Javascript; PHP; C/C++; Python.\nThành thạo framework: Django.\nTrình độ nghe, nói, đọc tiếng Trung ở mức trung bình.\nỨng viên có năng lực tốt, mức lương có thể thương lượng thêm.\n\nQuyền lợi:\nĐược hưởng đầy đủ chế độ phúc lợi theo Luật Lao động Việt Nam và được hưởng lương làm thêm giờ.\nCó thưởng tết.\nTham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp.\nNghỉ phép năm và nghỉ Lễ, Tết theo quy định.\nĐược đào tạo kỹ năng chuyên môn.\nMiễn phí bữa ăn tại nơi làm việc.\nCông việc ổn định, lâu dài.\n\nĐịa điểm làm việc:\nBắc Giang: Lô CN-02, Khu công nghiệp Hòa Phú, xã Mai Đình, huyện Hiệp Hòa, Hiệp Hoà.\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2615, 1400, 2, 'C#.NET Leader', 'Mô tả công việc:\n・Participate in building the company\'s own product and outsource projects\n・Cooperate with other teams on all phases of project development\n・Contribute to system architecture and design decisions\n・Deliver good quality code\n・Be able to self-study on new technologies\n・Be dynamic and proactive\n\nYêu cầu ứng viên:\n1. Basic Skills:\n・ Someone who takes initiative and can work proactively.\n・Has a positive attitude and forward-thinking mindset.\n・ Enjoys creating new things with a pioneering mindset.\n・Willingness to learn new technologies.\n・Strong communication skills and the ability to collaborate effectively with a team.\n・Able to communicate in English.\n\n2. Technical Skills And Experiences (Required)\n・Proficient in C# with advanced features such as LINQ, Delegates, Events, and Lambda Expressions.\n・Strong understanding of .NET Framework features, especially Windows Forms (WinForms), WPF (Windows Presentation Foundation), and UWP (Universal Windows Platform), depending on the application\'s requirements.\n・Experience in handling Exceptions, Debugging, and Unit Testing.\n・Experience with Entity Framework or ADO.NET to connect applications to databases, perform queries, and manipulate data.\n\n3. Technical Skills and Experience (Preferred Qualifications)\n・Has experience working with Japanese clients, markets, or companies.\n・Experienced in source code optimization, refactoring, and code review.\n・Believes that building excellent applications requires more than just delivering “working” code — it must also consider reusability, maintainability, security, and performance.\n\nQuyền lợi:\n・Salary review:  Once a year\n・Commuting allowance\n・Annual paid leave  (Granted collectively in April), public holidays are in accordance with labor laws.\n・Company trips\n・Regular health check-ups: Once a year\n・Participation in regular sports activities such (badminton,bowling ,vvv): Once a month\n・Company parties and other internal events\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Bình Thạnh\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2616, 1401, 2, 'Lập Trình Viên Fullstack (ReactJS + NodeJS + SQL + AI)', 'Mô tả công việc\nPhát triển, triển khai và bảo trì các ứng dụng web sử dụng ReactJS và NodeJS.\nThiết kế API và xử lý logic backend, tương tác với SQL Server và Oracle.\nTối ưu hóa hiệu năng và bảo mật hệ thống.\nTham gia tích hợp các mô hình hoặc API AI (OpenAI, HuggingFace, nội bộ…) vào hệ thống hiện có.\nLàm việc với đội thiết kế, PM và các bộ phận liên quan để hoàn thành sản phẩm end-to-end.\nHỗ trợ triển khai hệ thống (CI/CD, môi trường staging/production).\n\nYêu cầu ứng viên\nBắt buộc:\nTốt nghiệp hệ Đại học trở lên các ngành liên IT / Lập trình / …\nThành thạo ReactJS (Hooks, Router, State Management…).\nThành thạo NodeJS, đặc biệt với ExpressJS hoặc NestJS là một lợi thế.\nCó kinh nghiệm làm việc với SQL Server hoặc Oracle, biết viết và tối ưu câu truy vấn SQL.\nCó thể đảm nhiệm độc lập toàn bộ quy trình phát triển ứng dụng fullstack.\nCó hiểu biết hoặc từng làm việc với các ứng dụng tích hợp AI, như:\nGọi API AI (ChatGPT/OpenAI, Google AI, v.v.)\nXử lý dữ liệu, nhúng vector, hệ thống hỏi đáp, phân tích văn bản hoặc hình ảnh\n\nƯu tiên:\nCó sản phẩm cá nhân hoặc dự án thực tế tích hợp AI.\nCó tư duy hệ thống, hiểu về kiến trúc microservice là một lợi thế.\nKinh nghiệm xử lý authentication (JWT, OAuth2...).\nKinh nghiệm bảo mật\nBiết sử dụng Docker, CI/CD.\nĐọc hiểu tài liệu tiếng Anh tốt.\n\nQuyền lợi\nThu nhập từ 13,000,000 - 15,000,000 vnđ (Có thỏa thuận theo năng lực của ứng viên)\nLương cơ bản (Trả đủ 100% ngay tháng đầu tiên nhận việc).\nHỗ trợ xe đưa rước từ HCM đến Biên Hòa\nĐóng các khoản BẢO HIỂM ngay sau khi nhận việc.\nCó cơ hội thăng cấp bậc.\nKhám bệnh định kỳ theo quy định 1 năm 1 lần.\nNghỉ Thứ Bảy và Chủ nhật và các ngày lễ tết theo quy định.\nCó 12 ngày nghỉ phép hưởng lương hàng năm.\nLương tháng 13 theo quy định của công ty.\nXét duyệt tăng lương hàng năm.\nCác quyền lợi và chế độ khác theo Bộ luật lao động Việt Nam.\n\nĐịa điểm làm việc\n- Đồng Nai: KCN Biên Hòa 2, Biên Hoà\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 07:30 đến 17:30)\n\nCách thức ứng tuyển\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2617, 1402, 2, 'Tech Lead (Java)', 'Mô tả công việc:\n- Tham gia phát triển sản phẩm theo yêu cầu của khách hàng theo Java\n- Đảm bảo chất lượng code, các vấn đề về hiệu năng và bảo mật\n- Quản lý công việc của team, phân công công việc, nghiệm thu và Báo cáo kết quả.\n- Đưa ra giải pháp kỹ thuật, nghiên cứu các công nghệ mới áp dụng vào dự án.\n- Một số công việc khác theo chỉ đạo của cấp trên.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật phần mềm hoặc các ngành liên quan.\n- Ít nhất 3 năm kinh nghiệm làm lập trình viên Java, trong đó ít nhất 1 năm ở vị trí quản lý hoặc lãnh đạo nhóm.\n- Kinh nghiệm vững về Java, Spring Framework, Hibernate, RESTful APIs, Maven, và các công nghệ Java khác.\n- Kinh nghiệm làm việc với các cơ sở dữ liệu quan hệ như MySQL, PostgreSQL hoặc các hệ thống NoSQL.\n- Có kiến thức về các công cụ quản lý mã nguồn như Git, và quy trình phát triển Agile/Scrum.\n- Khả năng lãnh đạo và truyền cảm hứng cho đội ngũ, với kỹ năng giao tiếp tốt và khả năng giải quyết vấn đề hiệu quả.\n- Có khả năng làm việc dưới áp lực và quản lý thời gian hiệu quả.\n- Tiếng Anh đọc hiểu tài liệu kỹ thuật là một lợi thế.\n\nQuyền lợi:\n- Chế độ đãi ngộ:\n- Lương thỏa thuận theo năng lực thực tế của ứng viên, Review performance: 1 lần/ năm.\n- Trợ cấp đi lại, trợ cấp học phí các chứng chỉ IT, trợ cấp OT, trợ cấp onsite khi đi tham gia dự án thuê ngoài;\n- Thưởng lễ tết (theo quy định và tình hình thực tế của công ty); lương tháng thứ 13, thưởng nhân viên xuất sắc quý, năm;\n- Chế độ chăm sóc nữ giới: Nghỉ sinh lý phụ nữ: 1 ngày/ tháng. Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ ngày.\n\n- Chế độ chăm sóc sức khỏe cho nhân viên:\n- Bảo hiểm y tế, bảo hiểm thất nghiệp, bảo hiểm xã hội theo quy định của Luật Lao động;\n- Khám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín (ĐH Y, BV 103, Thu cúc, Medlatec,..v..v.)\n\n- Văn phòng làm việc tiện ích:\n- Miễn phí trà, cà phê tại khu vực ăn uống của công ty;\n- Máy pha cà phê tiện ích tại văn phòng;\n- Đồ ăn nhẹ cho team OT.\n\n- Các hoạt động sôi nổi:\n- Hoạt động team building kết nối đội nhóm hàng quý;\n- Party cuối thứ 6 hàng tuần;\n- Các CLB thể thao: bóng đá, cầu lông, bilac, game,..v..v; thể dục nhẹ nhàng sau giờ ngủ trưa;\n- Chương trình radio phát nhạc, confession theo yêu cầu;\n- Hoạt động du lịch thường niên và các sự kiện lớn trong công ty;\n- Seminar về kiến thức chuyên môn, ngoại ngữ và các kỹ năng khác.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2618, 186, 2, 'Lập Trình Viên Client. Thu Nhập Upto 40M', '• Xây dựng và duy trì quan hệ đối tác với các đối tác chiến lược, phụ trách nghiên cứu, phát triển Games/App\n• Mở rộng mạng lưới đối tác bằng cách tiếp cận với các đối tác khu vực, toàn cầu\n• Trao đổi thông tin, đàm phán điều kiện hợp tác\n• Xây dựng và phát triển về hình ảnh của sản phẩm và công ty\n\nYêu cầu ứng viên\n• Bắt buộc ứng viên sử dụng được Unity\n• Thành thạo C# và có thể sử dụng JavaScript\n• Bắt buộc có kinh nghiệm sử dụng công cụ Git, và có hiểu biết về CI/CD\n• Kinh nghiệm: từ 5 năm trở lên\n• Yêu cầu: Có portfolio kèm mã nguồn (code đính kèm để có thể đánh giá kĩ năng thực tế)\n• Trong quá trình phỏng vấn:\n  + Có thể có bài thi viết tự luận về design pattern\n  + Kèm theo bài kiểm tra lập trình (coding test)\n\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận.\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước)\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm , Tiêm phòng HPV, cúm,...\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes Gardenia Hàm Nghi, Nam Từ Liêm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2619, 1403, 2, 'Kỹ Sư Phần Mềm / Software Engineer', '1. Hỗ trợ hiện trường và bảo trì phần mềm thiết bị bán dẫn\n- Cài đặt, bảo trì và xử lý sự cố phần mềm thiết bị bán dẫn\n- Thu thập và phân tích yêu cầu từ khách hàng (VoC)\n- Thăm trực tiếp khách hàng trong và ngoài nước, hỗ trợ kỹ thuật (Toàn cầu: Mỹ, Đài Loan, Hàn Quốc, Nhật Bản)\n- Phân tích log phần mềm thiết bị bán dẫn\n2. Test chức năng phần mềm\n- Viết và tiếp nhận các trường hợp test (Test Case)\n- Test mô phỏng\n- Viết báo cáo test và đưa ra các điểm cần cải tiến\n- Bảo trì phần mềm điều khiển thiết bị\n3. Phát triển chức năng phần mềm\n- Phát triển và gỡ lỗi chức năng phần mềm theo đơn vị/khối \n- Phát triển driver truyền thông\n- Thiết kế và hiện thực giao diện người dùng (GUI)\n\nYêu cầu ứng viên\n- Từ 0 đến 5 năm lĩnh vực có liên quan, hoặc tốt nghiệp Đại học chuyên ngành\n- Am hiểu chương trình C++, C#\n- Tiếng Anh hoặc tiếng Hàn đọc hiểu trong công việc \n- Sẵn sàng tham gia đào tạo, công tác nước ngoài (Hàn, Mỹ, Nhật, Đài Loan,...)\n\nQuyền lợi\n- Thời gian làm việc: từ thứ 2 đến thứ 6 (5 ngày/ tuần)\n- Môi trường làm việc năng động, chuyên nghiệp, với nhiều cơ hội phát triển\n- Thử việc hưởng 100% lương, thường không phát sinh OT (nếu phát sinh sẽ chi trả theo Luật Lao động)\n- Team-building, company trip\n- Lương, thưởng, xét tăng lương hàng năm\n- Đào tạo nước tại Hàn Quốc và phụ cấp đào tạo\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Charmvit Tower, 117 Trần Duy Hưng, Cầu Giấy\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2620, 1374, 2, 'Kỹ Sư Lập Trình Nhúng Linux, Android', '- Phát triển các thiết bị đầu cuối thông minh (Smart phone, Tablet), thiết bị IoT, thiết bị xử lý trí tuệ nhân tạo tại biên dựa trên các nền tảng của Qualcomm, NXP…;\n• Porting hệ điều hành Android, Linux, RTOS cho các nền tảng phần cứng của Qualcomm, NXP;\n• Phối hợp với bộ phận phần cứng để debug, bring up thiết bị;\n• Tham gia vào tất cả các giai đoạn phát triển phần mềm từ phân tích yêu cầu, thiết kế, triển khai, kiểm tra hệ thống;\n• Thực hiện các công việc được quản lý phân công;\n\nYêu cầu ứng viên:\n• Tốt nghiệp Đại học loại Khá trở lên các chuyên ngành Cơ điện tử, Điện tử - Viễn thông, Điện - tự động hóa, CNTT, Kỹ thuật máy tính;\n• Tiếng Anh: TOEIC từ 550 trở lên hoặc tương đương;\n• Kiến thức nền tảng\n  - Hệ điều hành Linux: \n  + Hiểu biết về cấu trúc và hoạt động của Linux;\n  + Quản lý hệ thống, cấu hình, và sử dụng các công cụ dòng lệnh.\n  - Hệ điều hành Android:\n  + Kiến thức về hệ điều hành Android, từ phiên bản cơ bản đến các phiên bản mới nhất;\n  + Hiểu biết về Android SDK và NDK.\n  - Kỹ năng lập trình: Thành thạo C/C++; có kiến thức về các ngôn ngữ Java/Kotlin/Python là một lợi thế;\n  - Kỹ năng phát triển phần mềm\n  + Quản lý mã nguồn: Sử dụng Git để quản lý và phối hợp công việc.\n  + Phát triển phần mềm nhúng: Hiểu biết về các giao thức truyền thông (I2C, SPI, UART); Kinh nghiệm làm việc với các vi điều khiển và vi xử lý.\n  + Hiểu biết về kiến trúc ARM, x86, SoC, ...\n  + Debugging: Sử dụng các công cụ như GDB, các công cụ phân tích bộ nhớ khác.\n• Kỹ năng mềm: \n• Kỹ năng làm việc nhóm và giao tiếp hiệu quả\n\nQuyền lợi:\n+ Thu nhập hấp dẫn, xứng đáng với năng lực, thưởng theo hiệu quả công việc.\n+ Được làm việc trong Công ty sản xuất hàng đầu Việt nam với quy mô lớn (1.000 người); có bề dày lịch sử và văn hóa truyền thống với 2 lần được Đảng + Nhà nước phong tặng “Anh hùng lực lượng vũ trang nhân dân”.\n+ Có cơ hội được đào tạo nâng cao nghiệp vụ thường xuyên. Được cung cấp các trang thiết bị hiện đại cần thiết để nâng cao hiệu quả làm việc.\n+ Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.\n+ Được làm việc trong môi trường năng động, hiệu quả, nhiều hoạt động văn hóa sôi nổi quan tâm đến đời sống tinh thần của nhân viên và nhiều cơ hội để phát triển nghề nghiệp cho bản thân.\n\nĐịa điểm làm việc:\n- Hà Nội: An Khánh, Hoài Đức\n- Hà Nội: Khu CNC Hòa Lạc, Thạch Thất\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 đầu tiên của tháng\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hoài Đức, Thạch Thất', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2621, 1404, 2, 'Developer (BA)', 'Mô tả công việc\n1. Hỗ trợ vận hành và giám sát hệ thống:\n- Vận hành, giám sát và đảm bảo hoạt động ổn định của các hệ thống quản lý chuỗi nhà thuốc, hệ thống quản lý kênh phân phối DMS, hệ thống kế toán.\n- Vận hành và bảo trì hệ thống website của công ty, đảm bảo truy cập ổn định và kịp thời xử lý các lỗi phát sinh.\n- Hỗ trợ người dùng nội bộ khi gặp các vấn đề liên quan đến hệ thống và công nghệ.\n- Là đầu mối trao đổi, phối hợp trong Ban Công nghệ và các đối tác phát triển để khắc phục sự cố, nâng cấp hệ thống.\n\n2. Vai trò BA (Business Analyst):\n- Thu thập và phân tích yêu cầu từ các phòng ban và người dùng nội bộ.\n- Xây dựng tài liệu yêu cầu nghiệp vụ (BRD) chuyển đối tác để phát triển các tính năng mới hoặc tự phát triển trong Ban Công nghệ.\n- Theo dõi tiến độ triển khai và hỗ trợ trong quá trình phát triển, kiểm tra và bàn giao tính năng mới.\n\n3. Tham gia phát triển tính năng:\n- Sử dụng Python để thu thập, xử lý dữ liệu từ các hệ thống thông qua API.\n- Sử dụng các nền tảng Javascript (như React) tham gia xây dựng hệ thống BI portal.\n- Phối hợp trong Ban công nghệ để phát triển hoặc nâng cấp các tính năng mới theo yêu cầu.\n\n4. Kiểm thử và đảm bảo chất lượng hệ thống:\n- Thực hiện test và kiểm thử các tính năng, đảm bảo chất lượng, tính ổn định của hệ thống trước khi bàn giao cho người dùng trong công ty.\n- Ghi nhận, báo cáo lỗi và theo dõi quá trình khắc phục, cải tiến tính năng từ đối tác hoặc Ban công nghệ.\n\n5. Nghiên cứu và ứng dụng công nghệ mới:\n- Thường xuyên ứng dụng các công cụ AI như ChatGPT, Gemini vào công việc để nâng cao hiệu quả vận hành và phân tích.\n- Luôn sẵn sàng học hỏi và cập nhật công nghệ mới để cải tiến và tối ưu hóa.\n\nYêu cầu ứng viên\n1. Kinh nghiệm và kỹ năng:\n- Tối thiểu 3-4 năm kinh nghiệm trong vai trò Developer/BA.\n- Có khả năng lập trình với Python để thu thập, xử lý dữ liệu.\n- Có khả năng lập trình nền tảng Javascript (như React)\n- Có khả năng test, kiểm thử và đảm bảo chất lượng hệ thống.\n- Hiểu biết về vận hành hệ thống website và các nền tảng hỗ trợ người dùng nội bộ.\n\n2. Kiến thức chuyên môn:\n- Có kinh nghiệm hoặc hiểu biết về các hệ thống như:\n  - Hệ thống bán hàng\n  - Hệ thống DMS (Hệ thống quản lý kênh phân phối)\n  - Hệ thống kế toán\n- Ưu tiên ứng viên có kinh nghiệm vận hành hoặc phát triển các hệ thống này.\n\n3. Kỹ năng mềm:\n- Kỹ năng thu thập, phân tích yêu cầu từ người dùng và các phòng ban.\n- Cẩn thận, tỉ mỉ và có tư duy logic trong xử lý vấn đề.\n- Kỹ năng giao tiếp tốt, khả năng hỗ trợ và đào tạo người dùng nội bộ hiệu quả.\n- Nhanh nhẹn, linh hoạt và sẵn sàng học hỏi.\n\n4. Ưu tiên:\n- Khả năng thích ứng nhanh với công nghệ mới và môi trường làm việc năng động.\n- Có kinh nghiệm triển khai ERP là một lợi thế.\n\nQuyền lợi\n- Mức lương: Cạnh tranh theo năng lực.\n- Được đào tạo và tiếp cận các công nghệ mới nhất.\n- Môi trường làm việc chuyên nghiệp, trực thuộc Ban Công nghệ\n- Đầy đủ các chế độ phúc lợi: BHXH, BHYT, nghỉ phép năm và các chính sách khác của công ty.\n\nĐịa điểm làm việc\n- Hà Nội\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2622, 1405, 2, 'Nhân Viên Lập Trình CNC (Gỗ)', 'Mô tả công việc:\n- Bóc tách bản vẽ 3D sang 2D và lập trình máy CNC\n- Thiết lập Quy trình SX và B.O.M\n- Lập tiêu chuẩn SX cho các công đoạn SX (file cad), theo dõi và cập nhật khi có thay đổi\n- Báo cáo (mẫu, PP, tuần)\n- Lập các hướng dẫn làm việc cho các công đoạn\n- Các công việc liên quan khác do quản lý giao\n\nYêu cầu ứng viên:\n- Kinh nghiệm từ 2 năm trở lên\n- Thành thạo phần mềm autocad 2D, 3D\n- Biết sử dụng các công cụ Microsoft (Excel, Word, Outlook..) để thực hiện các yêu cầu về báo cáo, lập kế hoạch\n- Tăng ca theo yêu cầu công việc\n- Ý thức kỷ luật, trách nhiệm.\n\nQuyền lợi:\n- Mức lương tùy năng lực: 11.000.000 - 13.000.000 đồng/tháng, chưa bao gồm tăng ca.\n- Thử việc: 02 tháng\n- Thời gian làm việc: 8h00 – 17h00 (Nghỉ Chủ Nhật hàng tuần)\n- Làm việc tại Nhà máy Bình Dương: số 3/35 Đường Bình Chuẩn 34, KP. Bình Phước B, P. Bình Chuẩn, Thuận An, Bình Dương\n- Cơ hội làm việc môi trường năng động và Đào tạo, học hỏi, nâng cao kiến thức chuyên môn\n- Thưởng các dịp lễ/tết (Tết Dương lịch, 30/4, 2/9); Thưởng cuối năm, thưởng tết Nguyên đán..\n- Đóng BHXH đầy đủ, du lịch hàng năm, khám sức khỏe định kỳ, các chế độ thăm hỏi, phép năm, phúc lợi khác..\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2623, 1406, 2, 'Software Engineer', '- Receive and take over the WMS system source code from the current development team.\n- Analyze system architecture, understand backend, frontend, database components, and API connections.\n- Modify, maintain, or develop new features based on user requests.\n- Work closely with internal departments to gather requirements, analyze feasibility, and implement technical solutions.\n- Ensure system stability, perform data backups, monitor logs, and resolve technical issues.\n- Write technical documents and user manuals, and standardize operational procedures.\n- Participate in periodic meetings to report system status, propose improvements, and identify risks.\n- Identify causes of issues (system, software, user access, etc.).\n- Advise employees on appropriate actions.\n- Provide guidance on all company-supported applications.\n- Develop processes, regulations, and guidelines for system operation and administration, related to business functions.\n- Compile and report on expenses as requested by the Head of Department.\n- Manage and archive assigned related documents.\n- Perform other tasks assigned by the Head of Department.\n\nYêu cầu ứng viên\n- Bachelor’s degree in Computer Science, Information Technology, or related fields.\n- At least 3 years of hands-on experience in software development and system maintenance.\n- Proficient in at least one backend programming language PHP, C# (Java/Python), with basic frontend skills (HTML/CSS/JavaScript; React is a plus).\n- Experienced with relational database systems (SQL Server, MySQL, or equivalent).\n- Strong system thinking: ability to understand data flows, logic, and module interconnections.\n- Good communication skills with internal users to collect requirements and deliver effective solutions.\n- Experience in enterprise software maintenance projects is an advantage.\n\nQuyền lợi\n- Thưởng theo hiệu suất công việc\n- Đóng bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm tai nạn theo quy định nhà nước\n- Tham gia Company trip/Company Outing\n\nĐịa điểm làm việc\n- Bình Dương: Lot G7, Road 06, Song Than 2 IDZ, Di An Ward, Di An City, Binh Duong Province, Dĩ An\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2624, 1219, 2, 'Fulltime IOS', 'Mô tả công việc\n- Phát triển và duy trì các ứng dụng iOS chất lượng cao trên nền tảng Swift/Objective-C.\n- Tham gia vào toàn bộ vòng đời phát triển ứng dụng: từ phân tích yêu cầu, thiết kế, coding, testing đến triển khai và bảo trì.\n- Phối hợp chặt chẽ với team UI/UX, backend và các bộ phận liên quan để đảm bảo tính ổn định và trải nghiệm người dùng tối ưu.\n- Tối ưu hiệu suất và khả năng mở rộng của ứng dụng.\n- Sửa lỗi và cải tiến sản phẩm hiện tại theo phản hồi của người dùng và yêu cầu kinh doanh.\n- Cập nhật công nghệ mới và đề xuất áp dụng vào dự án.\nYêu cầu ứng viên\n- Ưu tiên có kinh nghiệm phát triển ứng dụng iOS.\n- Thành thạo Swift, có hiểu biết về Objective-C là lợi thế.\n- Có kinh nghiệm làm việc với UIKit, CoreData, CoreAnimation, RESTful APIs, JSON, Push Notification...\n- Hiểu rõ về mô hình MVC/MVVM, quản lý bộ nhớ, vòng đời ứng dụng iOS.\n- Biết sử dụng Git và làm việc trong môi trường CI/CD.\n- Có kinh nghiệm sử dụng CocoaPods, Swift Package Manager.\n- Tư duy logic tốt, chủ động trong công việc, có trách nhiệm và tinh thần học hỏi.\nQuyền lợi\n- Mức lương cạnh tranh, thưởng theo kết quả công việc.\n- Môi trường làm việc chuyên nghiệp, thân thiện và sáng tạo.\n- Cơ hội học hỏi và phát triển trong các dự án quốc tế.\n- Bảo hiểm y tế, bảo hiểm xã hội và các phúc lợi khác theo quy định của công ty.\n- Cơ hội tham gia các khóa đào tạo, nâng cao kỹ năng chuyên môn.\nĐịa điểm làm việc\n- Hồ Chí Minh: 25/1 Cửu Long Phường 2, Tân Bình\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2625, 756, 2, 'Junior IOS Developer (Thu Nhập Từ 12 - 25 Triệu)', 'Mô tả công việc\n- Phát triển ứng dụng, module ứng dụng iOS theo phân phối của Team Leader\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động theo phân phối của team leader.\n- Phối hợp với Mid Level/Senior Developer thực hành code review\n- Phối hợp với các team liên quan vận hành dự án theo quy trình.\n- Được tự do nghiên cứu công nghệ mới và đề xuất ý tưởng sáng tạo để nâng cao chất lượng dự án\n\nYêu cầu ứng viên\n- Có kinh nghiệm lập trình iOS 1-2 năm\n- Nắm được khái niệm iOS cơ bản (UI Kit, Resource, Storage, Network Handling)\n- Đã từng sử dụng một trong các kiến trúc MVP, MVVM\n- Hiểu biết Design Pattern là một lợi thế\n- Có khả năng dựng module độc lập là một lợi thế\n- Am hiểu Agile Scrum là một lợi thế\n- Đam mê, chủ động công việc, có kỹ năng làm việc nhóm, làm việc độc lập.\n- Có kỹ năng làm việc nhóm/theo quy trình là một lợi thế\n\nQuyền lợi\n- Mức lương hấp dẫn từ 12.000000 - 25.000.000VNĐ.\n- Cơ chế đãi ngộ tập trung vào phát triển nhân tài và xây dựng theo concept gia tốc: Nhân sự Top đầu tăng lương gấp 6 lần nhân sự Top dưới.\n- Thưởng 3-5 tháng lương 1 năm với nhân sự Top đầu.\n- Bổ nhiệm ngay khi có chiến công đặc biệt.\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN.\n- Các gói bảo hiểm ngoài BHXH: Bảo hiểm PTI, khám sức khỏe định kỳ hàng năm.\n- Văn hóa làm việc GenZ,môi trường làm việc trẻ trung, sáng tạo, Dám nghĩ - dám làm, trà đá, bàn tròn, ném đá sếp, áp dụng triệt để văn hóa 6K startup, TSB3C.\n- Du lịch hàng năm, team building, tea break hàng tuần.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Taisei 289 Khuất Duy Tiến, Trung Hòa, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc\n- 8:30 - 18:00, nghỉ trưa 1h30’, làm việc từ Thứ 2 - Thứ 6.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2626, 1407, 2, 'Nhân Viên Phát Triển Kinh Doanh', 'Phát triển kinh doanh B2B:\n- Tìm kiếm, tiếp cận và thiết lập mối quan hệ với các doanh nghiệp có nhu cầu tổ chức giải chạy nội bộ hoặc sự kiện truyền thông thể thao.\n- Tư vấn, xây dựng proposal và thương thảo hợp đồng với khách hàng.\nTriển khai dự án:\n- Phối hợp cùng các bộ phận nội bộ (thiết kế, kỹ thuật, vận hành, truyền thông) để đảm bảo tiến độ và chất lượng dịch vụ theo cam kết với khách hàng.\n- Theo dõi kết quả thực hiện, tổng hợp báo cáo và đề xuất cải tiến dịch vụ.\nQuản lý đối tác cộng đồng:\n- Phát triển hệ thống đại lý và nhóm chạy nhằm mở rộng thị trường phân phối sản phẩm sự kiện.\n- Hỗ trợ kỹ thuật, hướng dẫn và xử lý các vấn đề phát sinh trong quá trình bán hàng và vận hành.\nTư vấn sản phẩm bổ trợ:\n- Giới thiệu và tư vấn các sản phẩm đi kèm như áo chạy, huy chương, túi đeo, bình nước,... cho doanh nghiệp và đối tác tổ chức sự kiện.\nDuy trì & phát triển mối quan hệ khách hàng:\n- Chăm sóc khách hàng hiện tại, xây dựng kế hoạch upsell và duy trì hợp tác dài hạn.\n- Phân tích dữ liệu khách hàng để đề xuất các chương trình phù hợp theo thời điểm và mục tiêu truyền thông của đối tác.\n\nYêu cầu ứng viên:\n- Có laptop cá nhân\n- Ưu tiên ứng viên có đam mê thể thao, chạy bộ, fitness hoặc từng tham gia tổ chức các hoạt động cộng đồng\n- Biết Tiếng Anh là một lợi thế\n- Tốt nghiệp đại học chuyên ngành Quản trị Kinh doanh, Marketing, Kinh tế, Truyền thông hoặc các ngành liên quan\n- Tối thiểu 01 năm kinh nghiệm tại vị trí Business Development, Sales, Account hoặc tương đương, ưu tiên ứng viên từng làm trong lĩnh vực sự kiện, thể thao, truyền thông, agency\n- Có khả năng giao tiếp tốt, tư duy dịch vụ, kỹ năng đàm phán và xử lý tình huống linh hoạt\n- Thành thạo tin học văn phòng, biết sử dụng phần mềm CRM là lợi thế\n- Có khả năng làm việc độc lập, chủ động, định hướng mục tiêu và chịu được áp lực về doanh số\n- Siêng năng, nhiệt tình ham học hỏi, nhanh nhẹn, trung thực\n- Có khả năng tư duy đổi mới, chính xác và làm việc đúng đắn\n- Có khả năng làm ngoài giờ khi cần thiết\n- Gắn bó với công ty lâu dài\n\nThu nhập:\n- Thu nhập khi đạt 100% KPI: 15 - 30 triệu VND\n- Thu nhập tính theo tỷ lệ đạt KPI\n- Lương cứng: 10 - 20 triệu VND \n- Lương cứng không phụ thuộc doanh số\n\nQuyền lợi:\n- Tổng thu nhập: từ 10 - 30 triệu (lương cứng + hoa hồng doanh số rõ ràng, hấp dẫn)\n- Thưởng theo hiệu suất KPI, theo năm và các dự án đặc biệt\n- Thưởng lễ / tết theo quy định của Luật lao động\n- Tăng lương theo năng lực/ định kỳ của công ty\n- Tham gia miễn phí các sự kiện thể thao do iRace tổ chức\n- Môi trường năng động, khuyến khích sáng tạo và đề xuất\n- Hưởng đầy đủ chế độ BHXH, BHYT, BHTN và các chế độ khác theo luật Lao Động\n- Được đào tạo chuyên sâu về ngành thể thao và kỹ năng làm việc thực chiến\n- Có nhiều cơ hội phát triển sự nghiệp và thăng tiến\n- Được tham gia các hoạt động teambuilding, dã ngoại với team & công ty...\n- Hưởng các chính sách phúc lợi khác theo quy định của công ty\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Sảnh B1, Sarica, Đường N7, KĐT Sala, P. An Lợi Đông, Thủ Đức\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)\n- Nghỉ trưa: 12g - 13g30\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2627, 1408, 2, 'Chuyên Viên Lập Trình (Middle Developer)', 'Mô tả công việc\n- Phát triển các phần mềm theo yêu cầu của Tập đoàn\n- Vận hành, bảo trì, tối ưu, xử lý lỗi với các phần mềm đang chạy của Tập đoàn\n- Tích hợp phần mềm trong phạm vi quản lý với các hệ thống khi có yêu cầu\n- Nhận các yêu cầu và phân tích nghiệp vụ trong phạm vi hệ thống mình phụ trách\n- Thực hiện Kế hoạch định kỳ của bộ phận theo phân công\n- Thực hiện các công việc khác theo chỉ đạo của cấp trên\n\nYêu cầu ứng viên\n- Trình độ học vấn: Từ Cao đẳng trở lên.\n- Chuyên ngành ưu tiên: Công nghệ thông tin.\n- Kỹ năng: Tin học văn phòng thành thạo.\n- Kinh nghiệm liên quan:\n  + Có kinh nghiệm lập trình PHP, Python, React, Node js tối thiểu 2-3 năm trở lên.\n  + Có kinh nghiệm thiết kế, quản lý một trong các CSDL như MySQL, MSSQL, Oracle, Postgres từ 2 năm trở lên.\n  + Có kinh nghiệm lập trình Python.\n  + Có kinh nghiệm xây dựng các hệ thống Data warehouse/datalake và báo cáo quản trị.\n  + Có khả năng code cơ bản 1 số phần về AI như speech to text hoặc nhận diện khuôn mặt (yêu cầu mức độ cơ bản).\n\nThu nhập\n- Thu nhập khi đạt 100% KPI: 20 - 25 triệu VND\n- Thu nhập tính theo tỷ lệ đạt KPI\n- Lương cứng: 20 - 25 triệu VND\n- Lương cứng phụ thuộc vào doanh số\n\nQuyền lợi\n- Laptop\n- Chế độ bảo hiểm\n- Du Lịch\n- Phụ cấp\n- Du lịch nước ngoài\n- Đồng phục\n- Chế độ thưởng\n- Chăm sóc sức khỏe\n- Đào tạo\n- Tăng lương\n- Công tác phí\n- Phụ cấp thâm niên\n- Nghỉ phép năm\n\nĐịa điểm làm việc\n- Hà Nội: Số 11 ngõ 41 Thái Hà, phường Trung Liệt, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2628, 1409, 2, 'Fresher Fullstack Developer (English Fluent)', 'Mô tả công việc:\n- Tham gia đào tạo lý thuyết và on job training từ 3 tháng để học về lập trình Fullstack (Javascript) từ cơ bản đến nâng cao\n- Tham gia vào các dự án lớn của công ty và của khách hàng quốc tế với domain đa dạng\n- Các công việc khác được giao bởi quản lý trực tiếp\n\nYêu cầu ứng viên:\n- Sinh viên năm cuối hoặc đã tốt nghiệp trong lĩnh vực Công nghệ thông tin hoặc các ngành liên quan.\n- Tiếng Anh tốt, đặc biệt là kĩ năng giao tiếp\n- Nắm rõ cơ bản lập trình (Cơ sở dữ liệu, cấu trúc database), javascript, HTML, CSS\n- Nắm cơ bản lập trình hướng đối tượng\n- Có các project lập trình web\n- Good to have: đã từng làm react, nextjs, python, nodejs\n\nQuyền lợi:\n- Nhận trợ cấp bằng tiền mặt hàng tháng theo năng lực lên \n- Được tham gia làm các dự án lớn và đa dạng của các khách hàng quốc tế.\n- Cơ hội trở thành nhân viên sau khi hoành thành chương trình đào tạo.\n- Có cơ hội đi onsite tại Châu Âu, Úc, Singapore, Nhật Bản khi trở thành nhân viên.\n- Được làm trong môi trường Văn hóa chuyên nghiệp, trẻ trung và năng động.\n- Trải nghiệm công nghệ mới nhất về Thương mại điện tử.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Handico, đường Phạm Hùng, Nam Từ Liêm\n- Đà Nẵng: Tòa nhà G8 Golden, 65 Hải Phòng, phường Thạch Thang, Hải Châu\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:15)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2629, 1410, 2, 'Senior Fullstack Developer', 'GSV DTech (trực thuộc GSV Group) là công ty công nghệ ra đời với sứ mệnh đồng hành cùng ngành y tế Việt Nam trên hành trình chuyển đổi số toàn diện. Chúng tôi phát triển các giải pháp ứng dụng trí tuệ nhân tạo (AI), dữ liệu lớn (Big Data) và nền tảng số hiện đại – nhằm giải quyết các vấn đề cốt lõi trong quản lý và vận hành hệ thống y tế.\n\nChúng tôi đang cần tìm kiếm Senior Fullstack Developer với nhiệm vụ cụ thể:\n- Tham gia xây dựng, phát triển các dự án phần mềm mới của công ty\n- Bảo trì, nâng cấp, cập nhật các dự án phần mềm hiện có\n- Hỗ trợ vận hành, tìm hiểu nhu cầu và phản hồi từ người sử dụng để đề xuất các cập nhật, nâng cấp hoặc xây mới cần thiết\n- Chủ động ước lượng và kiểm soát công việc đã nhận\n- Tham gia nghiên cứu và trình bày các công nghệ mới\n- Báo cáo và thực hiện các công việc theo yêu cầu của quản lý\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin hoặc tương đương\n- Có ít nhất 4 năm kinh nghiệm với ASP.NET Core, C#, Web API\n- Thành thạo lập trình với hệ CSDL: SQL server hoặc MySQL\n- Bắt buộc thành thạo HTML, CSS, Jquery, Angular hoặc ReactJS\n- Ưu tiên có kinh nghiệm làm việc với RabbitMQ\n- Ưu tiên có kinh nghiệm phát triển các sản phẩm Product, các sản phẩm phần mềm "Software As a Service"\n- Ưu tiên ứng viên có kinh nghiệm phát triển các sản phẩm phần mềm về Y tế\n- Có khả năng giao tiếp tốt, chủ động, trung thực, năng động, khả năng làm việc nhóm tốt. Có trách nhiệm cao, và chịu được áp lực công việc\n- Có khả năng học hỏi nhanh, thích tìm hiểu và thực hiện các công việc mới\n\nQuyền lợi:\n- Thu nhập upto 35 triệu\n- Phụ cấp ăn trưa 35k/ngày\n- Nghỉ 2 ngày/tuần và các ngày lễ tết theo quy định của nhà nước, 12 ngày nghỉ phép\n- Môi trường làm việc chuyên nghiệp, năng động, thân thiện, ổn định\n- Tham gia BHXH theo quy định\n- Được khám sức khỏe hàng năm tại bệnh viện ĐH Y Hà Nội\n- Thưởng quý, năm, thưởng xếp loại nhân viên hàng năm, tháng lương 13, thưởng các ngày lễ, tết và các chế độ khác......\n- Được sử dụng dịch vụ của phòng khám, mua sản phẩm của công ty với giá ưu đãi nhân viên\n- Tham gia nhiều hoạt động của công ty: teambuilding, tất niên, du xuân, du lịch nước ngoài đặc biệt 5 năm/lần, kỷ niệm các ngày lễ, ...\n\nĐịa điểm làm việc:\n- Hà Nội: No 17 Ô 29 Lk 17, Khu đất dịch vụ, La khê, Hà Đông\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Trưa nghỉ 1,5h\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Đông, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2630, 1411, 2, 'PHP Backend Developer (Lavarel,Cake PHP,DB Design)', '■ Thông tin công ty:\nCông ty khách hàng của Lampart là 1 Công ty Start-up Nhật Bản hoạt động trong lĩnh vực in ấn đang tìm kiếm ứng viên đảm nhận công việc phát triển website thương mại điện tử của Công ty. \nChi tiết sẽ được trao đổi cụ thể trong quá trình phỏng vấn.\n■ Mô tả công việc:\n・Tham gia phát triển và triển khai các tính năng mới hệ thống back-end của Website\n・Bảo trì hệ thống Website để nâng cao khả năng phát triển của trang.\n・Các công việc liên quan theo phân công của quản lý.\n\n1. Yêu cầu chung:\n- Tối thiểu 2 năm kinh nghiệm lập trình web sử dụng ngôn ngữ lập trình PHP, trong đó: \n・Có ít nhất 2 năm kinh nghiệm về PHP Framework như: Lavarel, CakePHP \n・Có ít nhất 2 năm kinh nghiệm về database: MySQL hoặc PostgreSQL và có thể thiết kế Database\n- Có thể đọc hiểu tài liệu kỹ thuật bằng tiếng Anh (ví dụ: tài liệu tham khảo PHP v.v.) \n- Kỹ năng giao tiếp tốt: có khả năng lắng nghe, diễn đạt, hiểu & phản hồi thông tin bằng lời nói một cách hiệu quả. \n- Làm việc nhóm tốt, hòa đồng và giúp đỡ người khác trong công việc \n- Có trách nhiệm cao. \n- Có kỹ năng Quản lý công việc hiệu quả \n- Có khả năng làm việc dưới áp lực cao \n\n2. Lợi thế ứng tuyển:\n- Thành thạo HTML5, CSS3 và JavaScript (bao gồm cả JS Framework) \n- Có kinh nghiệm thiết lập môi trường phát triển với Docker. \n- Có kinh nghiệm sử dụng GitHub để quản lý mã nguồn.\n\n■ Quyền lợi:\n・ Công ty trang bị Laptop/ Monitor.\n・ BHXH full lương.\n・ Đánh giá lương, thưởng hàng năm.\n・ Khám sức khỏe định kỳ.\n・ Du lịch Công ty.\n・ Phụ cấp tăng ca.\n・ Phụ cấp thâm niên.\n・ Nghỉ phép năm.\n\n■ Địa điểm làm việc:\n- Hồ Chí Minh: Lầu 12, An Phú Plaza 117-119 Lý Chính Thắng, Phường Võ Thị Sáu, Quận 3\n\n■ Thời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\n■ Cách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2631, 209, 2, 'Fresher Fullstack Developer (.Net Và Angular)', 'Mô tả công việc\nTham gia chương trình Đào tạo chuyên sâu trong vòng 4 tháng về C#/.Net và Angular để chuẩn bị các kiến thức và hoàn thiện kỹ năng trước khi tham gia vào dự án, với các nội dung bao gồm:\no Kiến thức về Database: Mô hình quan hệ thực thể (ERM). Hệ quản trị cơ sở dữ liệu Microsoft SQL Server - hiểu và làm việc với truy vấn SQL: T-SQL Statements, Advanced DML, SQL Join, Index, View., sử dụng các đối tượng nâng cao Database Objects: Transactions, Stored Procedure, User Defined Function, Trigger.\no Lập trình .NET (C#): Lập trình C#: Variable/Constant, Data Type, Control of Flow...Lập trình hướng đối tượng với C# (OOP), LINQ. Sử dụng Collections/Generics, kết nối cơ sở dữ liệu (ADO.NET), làm việc với Winforms. Làm việc với IO, Exception và lập trình Concurrency. NET Technologies Web App: ASP.NET MVC và Thiết kế web với HTML, CSS, JS, jQuery, AJAX. Sử dụng Entity Framework\no Lập trình Frontend: HTML/CSS, Bootstrap, ES6, TypeScript, Angular Framework\no Phát triển phần mềm theo quy trình chuyên nghiệp: Hiểu các bước thực hiện dự án, bao gồm thiết kế ứng dụng, làm GUI, thiết kế code, Thực hiện Code Review (using StyleCop, FXCop), Unit Test (Nunit), kiểm tra chất lượng dự án. Luyện tập kỹ năng code trong dự án với các chuyên gia công nghệ & lập trình viên nhiều năm kinh nghiệm.\n\nYêu cầu ứng viên\no Là sinh viên đã/sắp tốt nghiệp chuyên ngành Công nghệ thông tin, Toán tin, Khoa học máy tính, Kỹ thuật phần mềm, Điện tử viễn thông... hoặc các chuyên ngành có liên quan, có GPA > 3.0\no Nắm vững kiến thức cơ bản về Lập trình hướng đối tượng, C#/.Net, HTML/CSS, JavaScript\no Có khả năng giao tiếp tiếng Anh tốt\no Có thể tham gia đào tạo/làm việc Full-time từ thứ 2 - thứ 6.\no Ham học hỏi, máu lửa, nhiệt huyết, sẵn sàng chinh chiến đối đầu với thử thách khó khăn tại các dự án phần mềm lớn. Tuân thủ kỷ luật & có trách nhiệm với công việc.\n\nQuyền lợi\no Sau quá trình đào tạo, bạn có cơ hội được ký hợp đồng chính thức với FPT Software. Tham gia làm việc tại các dự án với mức thu nhập hấp dẫn tương xứng với kỹ năng và kinh nghiệm của bạn, trung bình từ 12.000.000 VNĐ - 15.000.000 VNĐ/tháng. Được đào tạo thêm các kiến thức về các công nghệ mới như: Cloud (AWS/ Azure...), DevOps; Frontend (Angular/ ReactJS...); Hưởng các chính sách như: Hỗ trợ thi các chứng chỉ chuyên nghiệp quốc tế (OCA/PMP...), hỗ trợ mua nhà, bảo hiểm FPT care...\no Cơ hội tham gia và trở thành trở thành “key member” trong các siêu dự án của FPT Software trong các lĩnh vực: Thương mại điện tử, Vận tải Logistic, Hàng không, Chăm sóc sức khỏe... với công nghệ hiện đại về Mobile/Web ...và đội ngũ chuyên gia giàu kinh nghiệm\no Cơ hội phát triển bản thân và làm việc cùng các chuyên gia giỏi nhất của FPT Software và khách hàng lớn đến từ Mỹ, Pháp, Singapore, Nhật Bản...\no Tiếp cận với những công nghệ tiên tiến hàng đầu về Web, phát triển kỹ năng mềm & định hướng nghề nghiệp, tư vấn bí quyết thành công từ các chuyên gia.\no Trải nghiệm văn hóa đặc trưng, môi trường làm việc hiện đại bậc nhất Việt Nam tại các Campus của FPT Software\n\nĐịa điểm làm việc\n- Hà Nội: FPT Building, 17 Duy Tân Str., Cầu Giấy District, Hanoi,, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2632, 1412, 2, 'Fullstack NodeJS Developer', '- Participate in the entire application lifecycle, focusing on coding and debugging\n- Write clean code to develop functional web applications\n- Troubleshoot and debug applications\n- Manage cutting-edge technologies to improve legacy applications\n- Gather and address technical and design requirements\n- Provide training and support to internal teams\n- Build reusable code and libraries for future use\n- Liaise with developers, designers and system administrators to identify new features\n- Follow emerging technologies.\n\n- Proven work experience as a fullstack developer and at least five year of experience in an equivalent position.\n- An in-depth understanding of the entire web development process (design, development, and deployment).\n- Hands-on experience with programming languages such as Nodejs.\n- Familiarity with front-end languages (e.g., HTML, JavaScript, and CSS).\n- Strong teamwork skills with a problem-solving attitude.\n- Bachelor\'s degree in Computer Science or a relevant field.\n- Preference will be given to candidates with experience in the ecommerce field.\n\n- Salary up to 45 millions VND\n- Holiday and Tet bonuses according to Vietnamese regulations.\n- Review your salary once a year.\n- Young, friendly and professional teamwork environment.\n- Join company trips, other activities for members\n\n- Hồ Chí Minh: 281/15 Bình Lợi, Phường 13, Bình Thạnh\n\nThứ 2 - Thứ 7 (từ 08:30 đến 17:30)\nThứ 2 - Thứ 6: 8:30 - 17:30\nThứ 7: 8:30 - 12:30\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2633, 1413, 2, 'Chuyên Viên Phát Triển Phần Mềm', 'Mô tả công việc\nXây dựng nhiệm vụ, xây dựng kế hoạch đưa phần mềm vào hoạt động và nghiệm thu:\n- Đề xuất điều chỉnh mục tiêu, mục đích yêu cầu\n- Đề xuất ký kết hợp đồng, phụ lục, thỏa thuận, nghiệm thu\n- Đánh giá test sản phẩm về công năng\n- Bổ sung tính năng và đưa phần mềm vào sử dụng \n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm trở lên về quản trị thiết kế phần mềm, phát triển phần mềm\n- Tốt nghiệp Đại học chính quy chuyên ngành Công nghệ thông tin, kỹ thuật phần mềm\n- Tuổi: 27-40\n\nQuyền lợi\n- Mức lương: 15 - 17 triệu\n- Được hưởng đầy đủ các chế độ phúc lợi xã hội như BHXH, nghỉ phép theo quy định; nghỉ mát hàng năm...\n- Làm việc trong môi trường chuyên nghiệp, năng động, nhiều cơ hội khẳng định bản thân và thăng tiến\n\nĐịa điểm làm việc\n- Hà Nội: Số 170 Ngọc Khán, Ba Đình\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 09:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2634, 1414, 2, 'Lập Trình Viên IOS (Swift, Objective-C)', 'Mô tả công việc\n+ Xây dựng các ứng dụng Mobile liên quan đến các mảng Tài chính, Ngân hàng, Ví điện tử, hệ sinh thái (Các dịch vụ đặt vé, mua sắm, du lịch, giải trí...) trên nền tảng IOS.\n+ Xây dựng các ứng dụng liên quan đến các phần tiện ích Ecommerce\n+ Nghiên cứu, tìm kiếm giải pháp về việc áp dụng các tính năng của thiết bị di động vào mảng tài chính, Ngân hàng, Viễn thông.\n+ Duy trì, hỗ trợ, nâng cấp các ứng dụng dịch vụ đã phát triển của Công ty\n+ Phát triển mới, nâng cấp ứng dụng cho các ngân hàng trong giai đoạn sắp tới.\n\nYêu cầu ứng viên\n+ Tốt nghiệp Đại học hoặc Cao đẳng chuyên ngành Công nghệ thông tin, Công nghệ phần mềm,… hoặc Trường đào tạo lập trình viên Quốc Tế (NIIT, Aptech) trở lên.\n+ Có hiểu biết về kiến trúc công nghệ, ứng dụng và mô hình phát triển cho nền tảng hệ điều hành IOS\n+ Kiến thức cơ bản và tư duy về Objective-C, Swift, lập trình IOS, lập trình hướng đối tượng.\n+ Ưu tiên ứng viên có hiểu biết công nghệ liên quan đến nền tảng thiết bị di động khác.\n+ Ưu tiên ứng viên có ứng dụng demo trên Appstore\n+ Có kinh nghiệm làm việc với SVN/GIT\n+ Chịu khó tìm tòi và nghiêm túc trong công việc.\n+ Chủ động trong công việc cũng như tìm hiểu công nghệ mới.\n+ Có trách nhiệm cao với công việc, gắn bó lâu dài với công ty.\n\nQuyền lợi\n1. Chế độ lương & thưởng hấp dẫn:\nMức lương thỏa thuận theo năng lực, đánh giá năng lực hàng năm\nChế độ thưởng phong phú và hấp dẫn (Theo quy định và chính sách công ty)\nHỗ trợ ăn sáng miễn phí\nHỗ trợ ăn trưa: 50.000đ/ngày\nHỗ trợ gửi xe, xăng xe, điện thoại (tùy vị trí)\nHỗ trợ trang điểm cho CBNV nữ\nQuà tặng các ngày lễ trong năm\n\n2. Bảo hiểm & chăm sóc sức khỏe toàn diện:\nBHXH, BHYT, BHTN theo pháp luật hiện hành\nGói bảo hiểm sức khỏe cao cấp 24/7 mua cho nhân viên & người thân nhân viên\nKhám sức khỏe định kỳ hàng năm\n\n3. Môi trường làm việc hiện đại:\nCung cấp máy tính & thiết bị làm việc hiện đại\nVăn phòng làm việc hiện đại, thiết bị làm việc Hi- tech\nKhông gian ăn nhẹ miễn phí (nước uống, trà cafe, hoa quả, sữa chua)\n\n4. Phát triển nghề nghiệp:\nCơ hội tiếp cận với những công nghệ mới, những dự án quy mô lớn\nLàm việc cùng đội ngũ hơn 2000 nhân sự tài năng, có chuyên môn giỏi, dày dạn kinh nghiệm, tư duy chia sẻ\nĐược tài trợ kinh phí tham gia các chương trình đào tạo nâng cao năng lực\nCông ty thành lập gần 20 năm với các sản phẩm & dịch vụ đã được khẳng định vị thế trên thị trường.\n\n5. Hoạt động ngoại khóa phong phú:\nVăn hóa công ty đặc sắc với nhiều hoạt động đoàn thể được quan tâm đầu tư: Team building, Nghỉ mát (trong nước và nước ngoài), 20/10, Year End Party, hoạt động thiện nguyện,…\nCác câu lạc bộ: CLB Cầu lông, CLB Bóng đá, CLB Yoga, CLB Điền kinh, CLB Bơi\n\nChúng tôi sẽ liên hệ qua điện thoại với những CV phù hợp trong vòng 7 ngày làm việc kể từ ngày ứng tuyển.\nLưu ý: Công ty đang tuyển tại 2 văn phòng Hà Nội và Tp. Hồ Chí Minh, ứng viên vui lòng ghi rõ địa chỉ trên CV.\n\nĐịa điểm làm việc\n- Hà Nội: 22 Láng Hạ, Đống Đa\n- Hồ Chí Minh: Tầng 12, tòa nhà Minh Long, số 17 Bà Huyện Thanh Quan, P. Võ Thị Sáu, Quận 3\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2635, 1138, 2, 'Nhân Viên Thiết Kế - Lập Trình File CNC', 'Thiết kế và lập trình file điều khiển cho máy CNC (máy cắt, đục, khắc gỗ, v.v.).\nĐọc hiểu và triển khai bản vẽ kỹ thuật 2D, 3D.\nLập trình G-code phục vụ sản xuất trên máy CNC.\nPhối hợp với các bộ phận liên quan để tối ưu hóa quy trình gia công.\nKiểm tra, chỉnh sửa và đảm bảo độ chính xác của file lập trình trước khi sản xuất.\n\nYêu cầu ứng viên:\nTốt nghiệp Trung cấp/Cao đẳng trở lên các ngành: Cơ khí, Thiết kế kỹ thuật, Chế biến gỗ, hoặc chuyên ngành liên quan.\nThành thạo các phần mềm thiết kế và lập trình CNC: AutoCAD, ArtCAM, MasterCAM, SketchUp,...\nCó ít nhất 1 năm kinh nghiệm thiết kế và lập trình file CNC (ưu tiên ngành gỗ).\nHiểu biết về quy trình vận hành máy CNC và các phương pháp gia công gỗ.\nTỉ mỉ, cẩn thận, có tư duy logic và tinh thần cải tiến.\n\nQuyền lợi:\nMức lương:  8-13tr, Thỏa thuận theo năng lực và kinh nghiệm.\nĐược tham gia đầy đủ BHXH, BHYT, BHTN theo quy định pháp luật.\nThưởng lễ, Tết, và các chế độ phúc lợi khác theo quy định công ty.\nĐược đào tạo nâng cao tay nghề và cập nhật công nghệ mới.\nMôi trường làm việc chuyên nghiệp, thân thiện, cơ hội phát triển rõ ràng.\n\nĐịa điểm làm việc:\nĐịa điểm làm việc tại nhà máy: CN11 - KCN Nguyên Khê, Đông Anh.\nPhỏng vấn tại nhà máy hoặc văn phòng: số 4 Dịch Vọng Hậu- Cầu GIấy - HN.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2636, 1381, 2, 'Kỹ Sư Phần Mềm', 'Mô tả công việc\n1. Kiến trúc hệ thống\n- Thiết kế kiến trúc phần mềm cho nền tảng điều phối AGV/AMR/xe nâng – có thể triển khai dạng cloud-based hoặc hybrid (cloud + on-premises).\n- Định nghĩa các tầng hệ thống: giao tiếp thiết bị (robotics control), xử lý nghiệp vụ (business logic), quản lý luồng hàng hóa (cargo workflows), tích hợp hệ thống (WMS/ERP), giao diện người dùng và APIs.\n- Lựa chọn công nghệ phù hợp (frameworks, message brokers, protocol layers, containerization...) đảm bảo khả năng mở rộng, hiệu năng và bảo mật.\n\n2. Quản lý nhóm IT\n- Quản lý nhóm IT, tổ chức và phân công công việc, kiểm soát tiến độ và chất lượng dự án.\n- Hướng dẫn và hỗ trợ kỹ thuật cho thành viên nhóm, xây dựng môi trường làm việc hiệu quả, học hỏi liên tục.\n\n3. Triển khai và tích hợp hệ thống\n- Thiết kế và xây dựng các module điều phối AGV/AMR dựa trên bản đồ nhà kho, thuật toán định tuyến, tránh va chạm và tối ưu nhiệm vụ.\n- Phát triển các cổng kết nối (connectors) với hệ thống WMS, ERP, PLCs và các thiết bị nhà kho khác qua REST, MQTT, OPC UA hoặc các giao thức tùy chỉnh.\n- Phối hợp với nhóm phần cứng và vận hành để kiểm thử và triển khai hệ thống tại thực địa (on-site deployment).\n\n4. Bảo trì và phát triển lâu dài\n- Thiết lập hệ thống giám sát, log, cảnh báo và cập nhật (CI/CD, observability tools).\n- Góp phần xây dựng lộ trình sản phẩm (product roadmap) và đề xuất cải tiến kiến trúc.\n\nYêu cầu ứng viên\n- Tối thiểu 5 năm kinh nghiệm phát triển phần mềm, trong đó có ít nhất 2 năm làm kiến trúc sư phần mềm hoặc team leader.\n- Có kinh nghiệm thiết kế hệ thống phân tán, sử dụng microservices, message queues (Kafka, RabbitMQ), container orchestration (Kubernetes).\n- Thành thạo một hoặc nhiều ngôn ngữ: Python, C++, Java, Go, Node.js.\n- Hiểu biết về giao tiếp với thiết bị IoT/robotics qua MQTT, WebSocket, ROS/ROS2 là lợi thế lớn.\n- Kinh nghiệm tích hợp với WMS/ERP, đặc biệt là SAP, Oracle, Odoo hoặc các hệ thống công nghiệp.\n\nQuyền lợi\n- Thu nhập: thỏa thuận và phụ cấp ăn trưa 30.000 đồng/ngày.\n- Thử việc: 60 ngày, được hưởng 85% lương cứng; \n- Đóng BHXH, BHYT, nghỉ phép hưởng lương theo quy định của Luật; \n- Chế độ phúc lợi: thưởng Lễ Tết, thưởng dự án, lương thứ 13, review lương 01 năm/lần hoặc đột xuất theo đề xuất và năng lực của nhân sự;\n- Chế độ du lịch, teambuilding hàng năm; \n- Được thử sức trong một môi trường làm việc trẻ trung, năng động với chính sách đãi ngộ tốt, có nhiều cơ hội nâng cao năng lực bản thân và tăng thêm thu nhập.\n\nĐịa điểm làm việc\n- Hà Nội: Cụm Công nghiệp Ngọc Hồi, Thanh Trì\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 2 - thứ 6 hàng tuần và 02 ngày thứ 7/tháng.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2637, 1415, 2, 'Web Developer', 'Làm việc cho Công Ty Cổ Phần Công Nghệ Khí Tượng Thủy Văn Và Môi Trường Dicom - Trực thuộc Hệ sinh thái của Tập Đoàn Dicom.\n- Tham gia phát triển và triển khai các phần mềm, ứng dụng web-based trong lĩnh vực Hàng không trong nước và nước ngoài.\n- Tham gia đầy đủ quá trình phát triển phần mềm từ phân tích yêu cầu, thiết kế hệ thống, thiết kế CSDL, lập trình đến kiểm thử chất lượng phần mềm.\n- Xây dựng giải pháp kỹ thuật, lựa chọn công nghệ để phát triển các sản phẩm phần mềm phù hợp với yêu cầu của các dự án và nhu cầu của khách hàng.\n- Viết thuyết minh dự án, các quy trình nghiệm thu, tài liệu mô tả sản phẩm và hướng dẫn sử dụng.\n- Phối hợp với các thành viên trong các dự án để tích hợp, triển khai, nghiệm thu toàn hệ thống. \n- Thực hiện các công việc khác trong phòng khi được yêu cầu.\n\nYêu cầu ứng viên:\n- Trình độ học vấn: Tốt nghiệp đại học chuyên ngành Công nghệ thông tin.\n- Thành thạo PHP, HTML, Javascript, CSS, jQuery.\n- Có kinh nghiệm sử dụng ít nhất 1 hệ quản trị cơ sở dữ liệu MySQL hoặc PostgreSQL.\n- Có kinh nghiệm sử dụng và phát triển hệ thống WebGIS mã nguồn mở: Geoserver.\n- Có tư duy logic, phân tích yêu cầu và giải quyết vấn đề.\n- Biết sử dụng các công cụ như Jira, Git, Figma...\n- Tiếng Anh đọc hiểu tài liệu, viết email.\n- Có kinh nghiệm ít nhất 1 library/framework để phát triển front-end: Typescript, VueJS, ReactJS,... là một lợi thế.\n- Ưu tiên ứng viên tốt nghiệp loại giỏi ở các trường top đầu VN về công nghệ hoặc đã từng thi quốc gia về các môn tự nhiên.\n- Có khả năng tìm kiếm, nghiên cứu tài liệu bằng tiếng Anh là một lợi thế\n- Kỹ năng làm việc nhóm tốt, tinh thần học hỏi và sẵn sàng tiếp nhận công nghệ mới.\n\nQuyền lợi:\n- Mức lương thỏa thuận: hấp dẫn theo năng lực.\n- Đóng BHXH sau 2 tháng thử việc thành công.\n- Thưởng 6 tháng, thưởng cuối năm.\n- Thời gian làm việc từ thứ 2 - thứ 6 (nghỉ thứ 7, chủ nhật).\n- Du lịch, khám sức khỏe hàng năm.\n- Thưởng lễ tết, sinh nhật, ốm đau, hiếu hỉ.\n- Môi trường làm việc chuyên nghiệp, thân thiện.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2638, 1416, 2, 'Kỹ Sư Phần Mềm Ứng Dụng Desktop', '1. Thiết kế phần mềm\n- Tham gia nghiên cứu/phát triển các phần mềm tích hợp của công ty trên hệ điều hành Windows/Linux\n- Nghiên cứu các công nghệ mới ứng dụng vào sản phẩm và dự án của công ty\n\n2. Các công việc khác\n- Phối hợp với các bộ phận liên quan để hoàn thành phần mềm và tham gia vào quá trình phát triển phần mềm\n- Thực hiện đào tạo nội bộ về phần mềm phát triển\n- Thực hiện báo cáo công việc theo định kỳ hoặc theo yêu cầu phát sinh\n- Thực hiện nhiệm vụ khác theo sự chỉ đạo của Trưởng/Phó phòng và Ban Lãnh đạo Công ty\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học loại Khá trở lên các chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm hoặc các chuyên ngành khác có liên quan\n- Ưu tiên thành thạo Java, Javascript, ...\n- Có khả năng làm việc độc lập và làm việc nhóm\n- Kỹ năng giao tiếp & truyền đạt thông tin tốt\n- Kỹ năng giải quyết vấn đề và tư duy logic\n- Sử dụng thành thạo tiếng Anh 4 kỹ năng: TOEIC 550 trở lên hoặc tương đương\n- Sử dụng thành thạo các phần mềm Office như Microsoft Word, Excel, Power Point...\n\nƯU TIÊN\n- Có kinh nghiệm về các kết nối mạng, giao tiếp phần cứng (như LAN, RS232/485,...)\n- Có kinh nghiệm làm việc với các dữ liệu bản đồ\n- Có khả năng làm việc độc lập và nhóm, ham học hỏi, kỷ luật tốt\n- Nhiệt huyết, chủ động, sáng tạo trong công việc, có khả năng chịu áp lực công việc cao\n- Có đam mê nghiên cứu và muốn làm việc trong môi trường chuyên nghiệp\n- Các ứng viên đã có nhiều năm kinh nghiệm tại vị trí tương đương với vị trí ứng tuyển\n- Các ứng viên tham gia và đạt các giải thưởng tại các cuộc thi cấp quốc gia, quốc tế\n- Các ứng viên đã có thời gian đào tạo, làm việc tại nước ngoài hoặc làm việc trong môi trường công ty nước ngoài\n\nQuyền lợi\n- Mức lương thỏa thuận\n- Lương tháng 13 + thưởng Performance theo quy định của công ty\n- Thưởng các dịp Lễ, Tết trong năm\n- Được nghỉ 12 ngày phép/ năm\n- Được tham gia BHXH, BHYT, BHTN theo quy định của Pháp luật\n- Được tham dự các khóa đào tạo nội bộ và khóa bồi dưỡng của ngành theo yêu cầu công việc\n- Được cử đi học, tham gia các khóa đào tạo nâng cao chuyên môn với chuyên gia trong nước và quốc tế\n- Được tham gia các hoạt động tập thể cùng công ty như: Du lịch, Team Building, New Year Party, các ngày Lễ trong năm,...\n- Được làm việc trong môi trường thân thiện, chuyên nghiệp \n- Cơ hội thăng tiến rõ ràng\n- Gửi xe miễn phí\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 6 tòa Detech Tower - Số 8, Tôn Thất Thuyết, Mỹ Đình 2, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2639, 1417, 2, 'Middle Frontend Developer', 'We\'re seeking an experienced Frontend Developer (Middle level) to lead and contribute to the development of our core frontend modules. As part of our international team, you\'ll have the unique opportunity to work directly with leading Japanese developers and shape the architecture of our web applications.\n\n- Design and develop reusable frontend modules and components that form the foundation of our applications\n- Architect and implement scalable frontend solutions using modern JavaScript frameworks\n- Drive technical decisions for frontend architecture and establish coding standards\n- Create efficient, maintainable, and performance-optimized code\n- Build and maintain core UI component libraries for company-wide use\n- Lead the implementation of complex frontend features and ensure code quality\n- Work closely with our design and backend teams to create seamless user interfaces\n- Learn and apply Japanese development standards and best practices through direct mentorship\n- Participate in our agile development process from architecture planning to testing\n\nYêu cầu ứng viên:\n\n- Minimum 3+ years of professional frontend development experience\n- Strong command of JavaScript and TypeScript\n- English communication skills (TOEIC 700 or equivalent)\n- Advanced experience with:\n    - Vue.js ecosystem and state management\n    - Modern frontend architecture patterns\n    - Component-based development\n    - HTML5/CSS3 best practices\n    - Git version control\n    - Test-Driven Development\n    - SEO optimization techniques\n    - Modern UI component libraries\n- Experience in building and maintaining large-scale applications\n- Personal Qualities:\n    - Strong technical leadership and decision-making abilities\n    - Passionate about creating maintainable, scalable code\n    - Self-motivated problem solver\n    - Team player with excellent collaboration skills\n\nQuyền lợi:\n\n- Work-Life Balance\n    - Hybrid work model (2-3 days remote per week)\n    - Flexible hours (9-6 or 10-7)\n    - Business casual environment\n    - New laptop/PC provided\n- Compensation & Benefits\n    - Competitive base salary matching your experience level - 13th month bonus\n    - Full insurance coverage\n    - Paid time off as per labor law\n    - Free lunch, snacks & beverages\n- Growth & Development\n    - Direct mentorship from Japanese tech experts\n    - Modern workspace fostering open communication\n    - Flat organizational structure\n    - Chance to work on real, impactful products\n    - Be part of an innovative Japanese tech startup\n\nJoin a Japanese tech startup at the forefront of Web3 and crypto, offering a holistic learning experience beyond programming. Join us in building impactful digital solutions while growing your career in a supportive, international environment!\n\nĐịa điểm làm việc:\n\n- Hà Nội: Duy Tân, Cầu Giấy\n\nCách thức ứng tuyển:\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2640, 1418, 2, 'Nhân Viên Lập Trình Vận Hành Máy CNC - Thu Nhập Hấp Dẫn Lên Đến 15 Triệu', '– Tiếp nhận bản vẽ kỹ thuật từ bộ phận kỹ thuật hoặc quản lý trực tiếp.\n– Lập trình gia công chi tiết trên phần mềm CAM (VD: HyperMill, MasterCAM...)(lập trình)\n– Mô phỏng kiểm tra đường chạy dao trước khi xuất chương trình.\n– Chuẩn bị dao cụ, gá kẹp, setup phôi đúng theo hướng dẫn.\n– Thiết lập máy CNC: gốc tọa độ, offset dao, kiểm tra chương trình (vận hành).\n– Chạy chương trình gia công, giám sát trong quá trình cắt.\n– Phối hợp với kỹ thuật và lập trình khi có lỗi phát sinh để xử lý kịp thời.\n\nYêu cầu ứng viên\n1. Trình độ học vấn:\n + Tốt nghiệp Trung cấp, Cao đẳng ngành Cơ khí, Cắt gọt kim loại, hoặc các ngành liên quan.\n2. Kỹ năng chuyên môn:\n + Biết phần mềm CAM (ưu tiên biết HyperMill, MasterCAM,......................).\n + Hiểu biết về công nghệ cắt gọt kim loại, vật liệu, dao cụ.\n + Biết cách tính toán và tối ưu hóa thông số cắt.\n + Có khả năng đọc hiểu bản vẽ kỹ thuật (2D, 3D).\n + Có kinh nghiệm xử lý lỗi trong quá trình lập trình và vận hành.\n3. Kinh nghiệm:\n + Có kinh nghiệm lập trình máy phay CNC (3 trục trở lên).\n + Ưu tiên ứng viên từng làm trong lĩnh vực gia công cơ khí chính xác, khuôn mẫu, chi tiết máy phức tạp.\n4. Phẩm chất cá nhân:\n + Tư duy logic, cẩn thận, có tinh thần trách nhiệm cao.\n + Chủ động trong công việc và phối hợp tốt với các bộ phận khác.\n + Sẵn sàng học hỏi và cải tiến liên tục.\n + Độ tuổi yêu cầu: dưới 35 tuổi\n\nQuyền lợi\n– Lương: 8,000,000 - 15,000,000 triệu theo năng lực + phụ cấp trách nhiệm.\n– Làm việc theo giờ hành chính hoặc theo ca (nếu có).\n– BHXH, BHYT, BHTN đầy đủ sau khi ký HĐLĐ chính thức.\n– Môi trường làm việc chuyên nghiệp, nhiều cơ hội phát triển.\n\nĐịa điểm làm việc\n- Hà Nội: Lô 05/9B KCN Hoàng Mai,, Hoàng Mai\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2641, 1419, 2, 'Nhân Viên Lập Trình CNC', '- Lập trình cho máy CNC\n- Kiểm tra chi tiết gia công\n- Khai báo và kiểm soát Job\n- Báo giá chi tiết sửa chữa, thay thế\n- Liên hệ với nhà cung cấp nguyên vật liệu, dụng cụ.\nCông việc chi tiết trao đổi trong buổi phỏng vấn\n\nĐịa chỉ làm việc: Số 55 Ích Thạnh, phường Trường Thạnh, Tp. Thủ Đức\n\nYêu cầu ứng viên\n- Nam, Tốt nghiệp Cao đẳng chuyên ngành kỹ thuật\n- Yêu cầu 1 năm kinh nghiệm trở lên, Sử dụng thành thạo phần mềm PTC CREO\n- Kỹ năng làm việc độc lập và theo nhóm tốt, Chịu được áp lực công việc.\n- Thành thạo vi tính văn phòng: Word, Excel, Outlook,...\n\nQuyền lợi\n- Bao cơm trưa, phụ cấp cơm tăng ca\n- Cấp phát đồng phục\n- Tham gia BHXH, BHYT, BHTN 24/24 sau quá trình thử việc\n- Nghỉ lễ, Tết,... thưởng lễ, Tết\n- Lương tháng 13, thưởng ngân sách\n- Du lịch, tất niên, khám sức khỏe định kì, review lương 1 lần/năm\n- Chế độ sinh nhật, hiếu hỉ, con học giỏi, ...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh & 2 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2642, 1201, 2, 'Lập Trình Backend', 'Mô tả công việc:\n• Phát triển ứng dụng desktop đa nền tảng sử dụng Node.js và SQLite.\n• Thiết kế kiến trúc phần mềm hiệu năng cao, tối ưu bộ nhớ và CPU cho các tác vụ nặng.\n• Thực thi giải pháp caching, xử lý đồng thời và bảo trì hệ thống lâu dài.\n• Quản lý luồng xử lý, ngăn chặn memory leak, nâng cao độ ổn định ứng dụng.\n• Phối hợp với team để triển khai giao diện người dùng và backend tích hợp.\n• Ưu tiên ứng viên đã từng làm việc với Electron.js.\n\nThời gian làm việc:\n+ Từ Thứ hai đến Thứ Sáu: Từ 8h00’ đến 17h30’\n+ Thứ Bảy : Từ 8h00’ đến 12h00’  \n+ Trưa nghỉ từ 12h00\' đến 13h30\'\n\nYêu cầu ứng viên:\n• Tối thiểu 2 năm kinh nghiệm với Node.js trong môi trường sản phẩm thực tế.\n• Hiểu rõ mô hình bất đồng bộ: Callback, Promise, Async/Await.\n• Có kinh nghiệm với SQLite, hiểu ORM và ưu tiên biết TypeORM.\n• Có hiểu biết về caching (in-memory hoặc disk), tối ưu CPU usage.\n• Biết phát hiện và xử lý memory leak, hiểu lifecycle trong Node.js.\n• Có tư duy về thiết kế ứng dụng high performance: phân luồng, chia module, reuse tài nguyên.\n• Biết sử dụng Git, đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.\n\nQuyền lợi:\n- Lương:15.000.000 – 20.000.000\n- Phỏng vấn 1 vòng duy nhất.\n- Lộ trình thăng tiến lên Sublead, Leader\n- Review lương 2 lần /năm, thưởng nóng hàng tuần, hàng tháng, hàng năm khi đạt thành tích xuất sắc cá nhân hay đội nhóm.\n- Thưởng tháng lương thứ 13, bảo hiểm, chế độ du lịch hàng năm theo chương trình của công ty.\n- Được khám sức khỏe định kỳ tại bệnh viện đa khoa Quốc tế. Được hỗ trợ 50 -100% chi phí sau bảo hiểm nếu không may phải nằm viện.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4, tòa nhà Stellar Garden số 35 Lê Văn Thiêm, Thanh Xuân Trung, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2643, 594, 2, 'Team Leader, Back-End Developer (Golang)', '- Design, develop, and maintain robust and scalable backend systems using Golang.\n- Collaborate with front-end developers and other team members to integrate user-facing elements with server-side logic.\n- Optimize applications for maximum speed and scalability.\n- Implement security and data protection measures.\n- Develop and manage well-functioning databases and applications.\n- Write clean, maintainable, and efficient code.\n- Troubleshoot, debug, and upgrade existing software.\n- Conduct code reviews and provide constructive feedback to peers.\n- Document development processes, architecture, and standard components.\n\n- 1+ years Golang experience in production use case.\n- Knowledge/Experience of SQL and common relational database systems such as PostgreSQL and MySQL.\n- Experience in Microservice Architecture.\n- Excellent problem-solving skills and attention to detail.\n- Basic English communication required.\n- Preferred Qualifications:\n  + Knowledge/Experience of the following datastore: Redis, TimescaleDB\n  + Experience golang web framework like Mux or Gin.\n  + Knowledge/Experience in HTML, VUE\n\n- Salary: Negotiated based on ability during interview.\n- Performance review once a year for salary increase consideration.\n- Friendly and professional team working environment.\n- Many opportunities to learn and develop personal skills.\n\n- Hồ Chí Minh: 364 Bến Vân Đồn, Quận 4\n\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2644, 1420, 2, 'Fresher Fullstack Developer (Fluent English)', 'Mô tả công việc\n● Được đào tạo lý thuyết và on job training từ 3 tháng về lập trình Javascript (ReactJS, NodeJS..)\n● Được làm việc với Restful API, GraphQL API\n● Được tham gia làm các dự án thương mại điện tử của các khách hàng quốc tế.\n\nYêu cầu ứng viên\n● Sinh viên năm cuối hoặc đã tốt nghiệp trong lĩnh vực Công nghệ thông tin hoặc các ngành liên quan. \n● Hoặc những ai yêu thích lập trình đã từng viết Code, có tư duy logic tốt, khả năng tự học tốt, Có kiến thức về cấu trúc dữ liệu và giải thuật. \n● Có thể tham gia thực tập fulltime. \n● Tiếng Anh giao tiếp tốt (bắt buộc)\n\nQuyền lợi\n● Nhận trợ cấp bằng tiền mặt hàng tháng theo năng lực lên tới 6.000.000 VND.\n● Cơ hội trở thành nhân viên sau khi hoàn thành chương trình đào tạo. \n● Có cơ hội đi onsite tại Châu Âu, Úc, Singapore, Nhật Bản khi trở thành nhân viên. \n● Được làm trong môi trường Văn hóa chuyên nghiệp, trẻ trung và năng động. \n● Trải nghiệm công nghệ mới nhất về Thương mại điện tử. \n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Handico, đường Phạm Hùng, phường Mễ Trì, Nam Từ Liêm\n- Đà Nẵng: Tầng 6, Tòa nhà G8 Golden, 65 Hải Phòng, phường Thạch Thang, Hải Châu\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:15) \n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2645, 1421, 2, 'Chuyên Viên Phát Triển Phần Mềm', 'Xây dựng nhiệm vụ, xây dựng kế hoạch đưa phần mềm vào hoạt động và nghiệm thu:\n- Đề xuất điều chỉnh mục tiêu, mục đích yêu cầu\n- Đề xuất ký kết hợp đồng, phụ lục, thỏa thuận, nghiệm thu\n- Đánh giá test sản phẩm về công năng\n- Bổ sung tính năng và đưa phần mềm vào sử dụng\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chính quy chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan\n- Có kiến thức cơ bản về lập trình, cơ sở dữ liệu và phát triển phần mềm\n- Hiểu biết về quy trình phát triển phần mềm và các phương pháp quản lý dự án\n- Có khả năng tư duy logic và giải quyết vấn đề tốt\n- Kỹ năng giao tiếp và làm việc nhóm hiệu quả\n- Có kiến thức cơ bản về quản lý dự án là một lợi thế\n- Sẵn sàng học hỏi và cập nhật các công nghệ mới trong lĩnh vực bất động sản và xây dựng\n\nQuyền lợi:\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội học hỏi và phát triển kỹ năng trong lĩnh vực công nghệ thông tin và bất động sản\n- Được đào tạo về quy trình, nghiệp vụ chuyên môn và kỹ năng mềm\n- Chế độ lương thưởng cạnh tranh, đánh giá năng lực định kỳ để tăng lương\n- Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của pháp luật\n- Tham gia các hoạt động team building, du lịch nghỉ mát hàng năm\n- Môi trường làm việc trẻ trung, cơ hội thăng tiến rõ ràng\n\nĐịa điểm làm việc:\n- Hà Nội: 170 Ngọc Khánh, Ba Đình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 7: 9h -12h\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2646, 1422, 2, 'Project Manager (Ngành Game)', 'Mô tả công việc: \nQuản lý sản phẩm: \n- Lựa chọn chiến lược tiếp cận và dẫn dắt sự thành công của sản phẩm\n- Phân tích dữ liệu người dùng và thị trường để đưa ra quyết định sản phẩm phù hợp\n- Đảm bảo chất lượng sản phẩm thông qua phản hồi người dùng và cải tiến liên tục\n\nQuản lý dự án:\n- Lập kế hoạch, phân công công việc, kiểm soát tiến độ và xử lý rủi ro dự án\n- Điều phối nguồn lực trong dự án (GD, Art, Dev) để đảm bảo triển khai hiệu quả\n- Phối hợp các bộ phận liên quan để đảm bảo đúng tiến độ và chất lượng đầu ra\n\nYêu cầu ứng viên:\n- Có ít nhất 2 năm kinh nghiệm PM hoặc PO, có game thành công là 1 lợi thế\n- Có khả năng tổ chức và lên kế hoạch chi tiết, làm việc tốt được với team cross-functional\n- Có kỹ năng giao tiếp, quản lý thời gian, quản lý con người, giải quyết vấn đề tốt\n- Có kỹ năng phân tích và cải tiến sản phẩm tốt\n- Có khả năng đánh giá game và các mô hình kinh doanh game\n- Trung thực và thẳng thắn, trách nhiệm, giao tiếp tốt, tư duy tốt\n\nQuyền lợi:\n- Thu nhập hàng tháng hấp dẫn, cạnh tranh, mức lương cứng upto 30M.\n- Hỗ trợ bảo hiểm sức khỏe PVI khi lên chính thức.\n- Thưởng cố định tháng lương 13 và chia sẻ lợi nhuận theo hiệu suất (tổng thu nhập lên tới 14 – 20 tháng lương/ năm).\n- Chính sách học tập hàng năm với mục tiêu phát triển, bồi dưỡng nhân viên từ 5M-20M/cá nhân.\n- Các hệ thống ghi nhận liên tục, vinh danh, khen thưởng trong quý và cuối quý, cuối năm thúc đẩy môi trường làm việc.\n- Các phúc lợi tốt và chăm sóc nhân viên đặc biệt: du lịch 2 lần/năm, team bonding mỗi quý, hỗ trợ chi phí khám sức khỏe định kỳ 1 lần/năm, sinh nhật, quà lễ Tết,...\n- Môi trường làm việc tiện nghi hơn 1000m2, cung cấp trang thiết bị hiện đại.\n\nĐịa điểm làm việc:\n- Hà Nội: 37 Lê Văn Lương, Thanh Xuân\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2647, 1423, 2, 'Lập Trình Viên PHP', 'Lập trình website bằng CMS Wordpress dựa trên yêu cầu hoặc thiết kế có sẵn.\nLập trình plugin tính năng theo yêu cầu phát sinh.\nPhát triển các tính năng mới và cải tiến các tính năng của website.\nChỉnh sửa các lỗi liên quan tới giao diện, chức năng website.\nKiểm tra và khắc phục khi website bị hack, nhiễm mã độc.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học, Cao đẳng chuyên ngành công nghệ thông tin.\nCó từ 02 năm kinh nghiệm phát triển website trên nền tảng WordPress, ngôn ngữ PHP\nThành thạo HTML/Javascript/jQuery/CSS/AJAX, CMS WordPress.\nCó kiến thức hệ quản trị cơ sở dữ liệu MySql là một lợi thế.\nƯu tiên có kinh nghiệm tiếp xúc và làm việc với các nền tảng thiết kế website (PHP framework như laravel, codeigniter; các CMS wordpress, joomla,..)\nTư duy logic và khả năng Research tốt.\n\nQuyền lợi:\nCơ hội thăng tiến, gắn bó và làm việc lâu dài tại công ty.\nMôi trường làm việc năng động, cơ hội phát triển nghề nghiệp.\nĐược hưởng đầy đủ các chế độ dành cho người lao động theo quy định pháp luật hiện hành (BHYT, BHXH, BHTN…) Thưởng tháng lương thứ 13, 12 ngày phép năm, thưởng Lễ/tết (theo quy định công ty), lương thưởng bảo hiểm trả/đóng đúng hạn, thưởng cuối năm, thưởng Nhân viên xuất sắc, thưởng thâm niên…\nTham gia và tận hưởng các hoạt động, sự kiện nội bộ, Team Building, du lịch, … của công ty.\n\nĐịa điểm làm việc:\nBình Dương: 4/567 Tổ 10, khu phố Hoà Lân 1, phường Thuận Giao, Thuận An.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:00 đến 11:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2648, 244, 2, 'Software Developer (E-Commerce & AI Integration) - 2 EXP', '1. Thiết kế và xây dựng hệ thống sàn thương mại điện tử\n2. Phát triển hệ thống Affiliate (tiếp thị liên kết)\n3. Tích hợp AI:\n- Gợi ý sản phẩm (recommender system)\n- Chatbot hỗ trợ khách hàng\n- Phân tích hành vi người dùng\n- Tự động tối ưu hóa quảng cáo/sản phẩm\n4. Vận hành và bảo trì hệ thống:\n- Quản lý cơ sở dữ liệu\n- Giám sát hiệu suất, bảo mật\n- Tối ưu trải nghiệm người dùng\n\nYêu cầu ứng viên\n- Thành thạo ngôn ngữ lập trình Web (JavaScript/TypeScript, Python, PHP,...)\n- Hiểu kiến trúc hệ thống thương mại điện tử\n- Có kinh nghiệm với các mô hình Affiliate\n- Biết sử dụng hoặc tích hợp AI (OpenAI API, TensorFlow, hoặc thư viện ML cơ bản)\n- Hiểu về bảo mật, phân quyền người dùng\n- Có kinh nghiệm tích hợp cổng thanh toán.\n- Làm việc tại khu vực Quận 3.\n\nQuyền lợi\n- Lương có kinh nghiệm từ 2 năm trở lên Junior / Fresher+ ( 12-20 Triệu )/ Lương thỏa thuận cho những trường hợp có kinh nghiệm đặc biệt.\n- Thù lao và phụ cấp theo chính sách chung của công ty.\n- Thù lao đặc thù theo tiến độ công việc.\n- Thưởng lễ, Tết, tháng lương thứ 13 đầy đủ.\n- Đóng bảo hiểm và các chế độ theo luật lao động sau khi ký hợp đồng chính thức.\n- Nghỉ lễ, Tết theo quy định.\n- Môi trường làm việc chuyên nghiệp, có khả năng định tâm, phát triển bản thân.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 213 Điện Biên Phủ, Phường Võ Thị Sáu, Quận 3\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2649, 155, 2, 'Tư Vấn Phát Triển Phần Mềm Website', 'Mô tả công việc:\nKhai thác thông tin khách hàng thông qua data công ty cung cấp kết hợp tìm kiếm thêm (có leader đồng hành cùng). Thiết lập cuộc gọi, tư vấn, giới thiệu sản phẩm và dịch vụ cho khách hàng. Đàm phán, thương lượng, thực hiện các thủ tục ký kết hợp đồng với khách hàng. Xây dựng, duy trì mối quan hệ tốt với khách hàng. Chăm sóc khách hàng trong quá trình sử dụng sản phẩm để đạt hiệu quả sử dụng tốt nhất và tư vấn nâng cấp sản phẩm. Cung cấp thông tin về nhu cầu hành vi, phản hồi của khách hàng cho bộ phận liên quan. Tham gia đóng góp thông tin để phát triển, cải tiến sản phẩm.\n\nYêu cầu ứng viên:\nGiọng nói dễ nghe, tự tin. Kỹ năng giao tiếp qua điện thoại tốt. Nhiệt tình, vui vẻ hỗ trợ khách hàng. Kinh nghiệm được đào tạo.\n\nThu nhập:\nThu nhập khi đạt 100% KPI: 10 - 15 triệu VND. Thu nhập tính theo tỷ lệ đạt KPI. Lương cứng phụ thuộc vào doanh số.\n\nQuyền lợi:\nĐược hưởng các chế độ, phúc lợi theo quy định của Luật lao động. Được hỗ trợ, đào tạo kỹ năng công việc. Xét tăng tiến khi có thành tích tốt. Tham gia vào các hoạt động tập thể, du lịch, team building.\n\nĐịa điểm làm việc:\nHồ Chí Minh: Toà nhà Saigon Tel, Khu Phần mềm Quang Trung, Quận 12.\nHồ Chí Minh: Gò Vấp.\nHồ Chí Minh: Củ Chi.\nHồ Chí Minh: Hóc Môn.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\nsáng thứ 7 08:00 - 12:00.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2650, 1424, 2, 'Unity Developer', 'Mô tả công việc\n- Lập trình game online - multiplayer trên nền tảng Unity.\n- Phát triển các dự án game với hạ tầng kĩ thuật cho hàng triệu User.\n- Môi trường Agile - trẻ năng động, linh hoạt.\n- Có cơ hội phát triển thành Full-Stack Developer.\n\nYêu cầu ứng viên\n- Kinh nghiệm làm việc với Unity tối thiểu 2 năm.\n- Nắm chắc cấu trúc dữ liệu giải thuật và các thuật toán phổ biến.\n- Nắm chắc lập trình hướng đối tượng và các design pattern phổ biến.\n- Hiểu và sử dụng tốt Git Flow.\n- Có khả năng đọc hiểu tiếng Anh.\n- Có tinh thần trách nhiệm; Chịu áp lực cao trong công việc\n- Làm việc độc lập, làm việc nhóm tốt.\n- Cởi mở, sẵn sàng học tập, chia sẻ công nghệ mới.\n- Thích chơi game, có kiến thức về game là lợi thế.\n- Có sản phẩm/dự án thành công của cá nhân hoặc công ty là lợi thế.\n\nQuyền lợi\n- Lương thỏa thuận tùy theo năng lực.\n- Review liên tục công việc, lương thưởng.\n- Được tham gia các chương trình đào tạo nâng cao năng lực, phát triển bản thân;\n- Có cơ hội thăng tiến lên các vị trí trưởng nhóm, quản lý.\n- Môi trường Agile - Năng động, Linh hoạt. Phát huy tối đa khả năng và tính sáng tạo của nhân tài.\n- Team building hàng quý, du lịch hàng năm trong hoặc ngoài nước.\n- Hưởng tất cả các chế độ bảo hiểm xã hội, y tế theo quy định của nhà nước, khám sức khỏe định kỳ hàng năm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2651, 1242, 2, 'Senior C Language Developer', 'We are looking for a Senior C Language Developer to join our LG CNS Vietnam Build Center. You will be working on high-performance system-level development with deep integration into network protocols and testing environments. The ideal candidate is a strong C programmer with high-level understanding of networking, packet analysis, and testing frameworks.\n\n- Design, implement, and optimize software modules in pure C for embedded or system-level applications.\n- Develop and maintain network-related features, including TCP/UDP stack handling.\n- Analyze and debug network traffic using tools like TCPDump, Wireshark, etc.\n- Integrate and apply testing frameworks/tools to validate and ensure code stability and performance.\n- Work closely with global teams (Korea HQ) to gather requirements, align on architecture and deployment strategy.\n- Review and maintain high standards of code quality, documentation, and security.\n- Participate in performance tuning and issue resolution in production-like environments.\n\nYêu cầu ứng viên:\n- Bachelor’s degree or higher in Computer Science, Software Engineering, or related field.\n- 5+ years of experience in C programming in Linux/Unix environments.\n- Strong experience in network programming, including TCP/IP, UDP, socket programming.\n- High-level understanding of TCPDump, Wireshark, and general packet analysis techniques.\n- Experience with unit testing frameworks (e.g. CMocka, Unity) or custom test environments.\n- Good debugging skills using GDB, Valgrind, or similar tools.\n- Familiarity with multi-threaded programming, memory management, and performance optimization.\n- Effective communication skills in English (Korean is a plus).\n\nQuyền lợi:\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Topik allowance\n- Review capacity annually and adjust salary increases according to work performance.\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8 hours/day)\n\nĐịa điểm làm việc:\n- Hà Nội: Onsite 15th Floor, Keangnam Landmark 72, Me Tri, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2652, 1425, 2, 'Back End Developer', 'Mô tả công việc\n- Transforming User Stories: You will take application user stories and translate them into functional applications. This process involves understanding user requirements and ensuring that the final product aligns with their expectations.\n- Designing and Building Components: You will design, build, and maintain reusable and testable components that are crucial for the application’s architecture. Your focus on reusability will help streamline development processes and enhance overall efficiency.\n- API Development: You will be responsible for building APIs that adhere to microservices principles. This includes ensuring that the APIs are scalable, maintainable, and designed for optimal performance.\n- Performance and Quality Assurance: Ensuring the performance, quality, and responsiveness of applications will be a key part of your role. You will employ best practices and methodologies to monitor and improve application performance.\n- Identifying and Fixing Issues: You will actively identify bottlenecks and bugs within the application. Your problem-solving skills will be essential in implementing effective fixes and enhancements to improve the user experience.\n- Maintaining Code Quality: You will help uphold the highest standards of code quality, organization, and automation. This includes participating in code reviews, advocating for best practices, and contributing to a culture of continuous improvement.\n\nYêu cầu ứng viên\n- Languages: Proficiency in Java and SQL is essential for developing robust back-end applications and managing database interactions effectively.\n- Frameworks: Experience with frameworks such as SpringMVC and SpringBoot is crucial for building scalable web applications. Familiarity with Hibernate for ORM (Object-Relational Mapping) will enhance your ability to manage database operations. Knowledge of JUnit and Mockito is important for testing and ensuring code quality.\n- API Specification: Understanding RESTful API design and documentation using Swagger is necessary for creating and maintaining APIs that are both efficient and user-friendly. Security: A strong grasp of Java API security principles, including authentication and authorization, along with common security standards, is vital to protect applications from vulnerabilities.\n- Databases: Proficiency in working with various database systems, including SQL Server, MariaDB, MySQL, and PostgreSQL, will enable you to manage data effectively and ensure seamless integration with applications.\n- Tools: Familiarity with build tools like Gradle and Maven, along with version control systems such as GIT, is essential for managing project dependencies and collaborating with team members. Experience with project management tools like JIRA and Confluence will facilitate effective task tracking and documentation.\n- Cloud Knowledge: Basic knowledge of AWS Cloud and deployment processes is important for leveraging cloud services to enhance application scalability and performance.\n\nQuyền lợi\n- Base Salary: The monthly base salary ranges from 55 million to 80 million VND, depending on experience and qualifications.\n- Hybrid Working Environment: Enjoy the flexibility of a hybrid working model, allowing you to work both remotely and in the office.\n- Full Salary Package Insurance: Comprehensive insurance coverage that includes full salary package insurance, ensuring your financial security.\n- Performance Bonus: Eligibility for performance bonuses based on individual and team contributions, rewarding your hard work and dedication.\n- Project Bonus: Additional bonuses tied to project success, providing incentives for achieving project milestones.\n- 13th Month Salary: Receive a 13th-month salary as a standard practice, enhancing your annual earnings.\n- Insurance for Dependents: Coverage options are available for dependents, ensuring that your family is also protected.\n- Other Benefits: Additional benefits in accordance with current laws, which may include health and wellness programs, professional development opportunities, and more.\n\nĐịa điểm làm việc\n- Hà Nội\n\nThời gian làm việc\n- Từ thứ 2 đến thứ 6, làm việc onsite 2-3 ngày/tuần.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2653, 1360, 2, 'Lập Trình Viên Backend (Python/AI/Microservices)', 'Mô tả công việc:\n- Xây dựng API và microservices: Thiết kế, triển khai và duy trì API hiệu suất cao.\n- Phát triển hệ thống backend: Xây dựng các giải pháp backend mạnh mẽ và tối ưu.\n- Tích hợp với hệ thống khác: Làm việc cùng các nhóm Frontend và AI để đảm bảo tích hợp hiệu quả.\n- Quản lý dữ liệu và bảo mật: Đảm bảo hệ thống có tính bảo mật và hiệu suất cao.\n- Hỗ trợ phát triển AI: Tham gia vào các dự án liên quan đến chatbot, NLP, machine learning, deep learning, computer vision.\n\nYêu cầu ứng viên:\n- Kinh nghiệm Python: Ít nhất 1 năm kinh nghiệm lập trình với Python trong phát triển backend.\n- Kinh nghiệm API: Thành thạo trong việc xây dựng API trên RESTful API, GraphQL và kiểm thử API trên Postman.\n- Microservices: Có hiểu biết về microservices và các công cụ như Docker, Kubernetes.\n- Machine Learning/AI: Có kinh nghiệm về NLP, Chatbot, Computer vision, Machine learning, Deep learning là lợi thế.\n- Cơ sở dữ liệu: Kinh nghiệm làm việc với ChromaDB, PostgreSQL, NoSQL (Qdrant, MongoDB, Redis...).\n- Cloud Services: Có hiểu biết về các cloud như AWS, Google Cloud, Azure hoặc triển khai On-premises.\n- Code Quality: Nắm vững các best practices về clean code, reusable code, và unit testing.\n\nƯu tiên:\n- Kinh nghiệm thực tế triển khai các giải pháp AI solutions như đọc tài liệu từ các định dạng .doc, .pdf, .xls..., đọc hình ảnh (image2text), hoặc đọc âm thanh (audio2text).\n- Kinh nghiệm làm việc với CI/CD, Jenkins, Travis CI.\n- Hiểu biết về Agile, Scrum, DevOps.\n\nQuyền lợi:\n- Lương thỏa thuận theo kinh nghiệm và năng lực.\n- KPI tương ứng với 5 tháng lương thực nhận.\n- Tháng lương thứ 13.\n- Thưởng dự án theo các dự án tham gia.\n- Đặc biệt chia cổ tức cho cán bộ nhân viên theo lợi nhuận của công ty.\n- Tham gia các khóa đào tạo kỹ năng mềm phục vụ cho công việc.\n- Thưởng các dịp lễ, Tết và team building hàng năm.\n- Xét duyệt tăng lương 2 lần/năm.\n- Được hưởng đầy đủ BHXH, BHYT và BHTN theo luật lao động Việt Nam hiện hành.\n- Được làm việc trong một môi trường trẻ trung, năng động cùng với các chuyên gia hàng đầu trong nhiều lĩnh vực của công ty để học hỏi và phát triển hàng ngày.\n- Cơ hội làm việc với các tập đoàn lớn: Tham gia các dự án lớn, làm việc với các khách hàng và đối tác uy tín trong ngành công nghệ trong và ngoài nước.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa nhà N03-T3, Khu Ngoại Giao Đoàn, Phường Xuân Tảo, Bắc Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2654, 1426, 2, 'AI Developer', '1. Giới thiệu công việc\nChúng tôi đang tìm kiếm một Chuyên gia AI có kinh nghiệm chuyên sâu trong lĩnh vực xử lý hình ảnh, đặc biệt là các ứng dụng làm đẹp, thay đổi khuôn mặt, kiểu tóc và trang phục bằng công nghệ AI. Bạn sẽ tham gia phát triển các sản phẩm sáng tạo hướng tới người sử dụng cuối, tập trung vào việc cá nhân hóa hình ảnh theo thời gian thực.\n\n2. Trách nhiệm chính\n• Thiết kế, huấn luyện và tối ưu các mô hình AI cho các tác vụ như:\n• Làm đẹp khuôn mặt (skin retouching, makeup synthesis)\n• Biến đổi khuôn mặt (face swap, age progression/regression)\n• Thay đổi kiểu tóc, trang phục bằng AI (hair segmentation, virtual try-on)\n• Xử lý và cải thiện chất lượng ảnh (denoising, super-resolution, background removal…)\n• Phối hợp với đội ngũ sản phẩm và thiết kế để xây dựng giải pháp có thể triển khai trên thiết bị di động hoặc nền tảng web.\n• Tối ưu hiệu suất mô hình để đạt thời gian phản hồi nhanh và tiêu tốn ít tài nguyên.\n• Nghiên cứu và tích hợp các công nghệ AI mới nhất (GAN, diffusion, NeRF…).\n\nYêu cầu ứng viên\n• Có từ 2 năm kinh nghiệm trong lĩnh vực Computer Vision hoặc AI/Deep Learning.\n• Có kinh nghiệm về các kiến trúc mô hình như GAN, UNet, Transformer, Diffusion Models.\n• Có kinh nghiệm xử lý dữ liệu ảnh và xây dựng pipeline huấn luyện mô hình.\n• Ưu tiên ứng viên đã từng làm việc với các dự án như:\n• Face beautification app\n• Virtual try-on / makeup app\n• 3D face modeling hoặc image-based rendering\n\nQuyền lợi\n- Được lựa chọn làm remote linh hoạt thời gian hoặc fulltime tại văn phòng\n- Thu nhập hấp dẫn, deal theo năng lực, fix 13 tháng lương\n- Thưởng tiền mặt và quà tặng vào các dịp lễ tết,… theo chính sách của công ty.\n- Ăn trưa tại công ty.\n- Cung cấp đầy đủ máy tính, thiết bị làm việc hiện đại, cấu hình cao.\n- 12 ngày phép/năm.\n- Được hỗ trợ chi phí tham gia các khóa học nâng cao chuyên môn theo định hướng của công ty.\n- Các hoạt động team building, các event chăm lo đời sống tinh thần của nhân viên như sinh nhật, liên hoan hàng tháng,... \n- Môi trường làm việc trẻ trung, năng động, đề cao và tôn trọng ý kiến cá nhân, ý tưởng sáng tạo nhằm nâng cao năng suất và hiệu quả công việc.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Golden Palace, Mễ Trì, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2655, 1427, 2, 'Lập Trình Viên .NET', 'Mô tả công việc\n- Tham gia thiết kế, phát triển, kiểm thử và bảo trì các ứng dụng sử dụng nền tảng .NET (C#, ASP.NET MVC, .NET Core/8).\n- Áp dụng các nguyên tắc lập trình hướng đối tượng (OOP), các mẫu thiết kế (Design Patterns) và nguyên tắc SOLID để xây dựng mã nguồn chất lượng cao, dễ bảo trì.\n- Thiết kế và tối ưu hóa cấu trúc cơ sở dữ liệu sử dụng Microsoft SQL Server, bao gồm viết truy vấn SQL, stored procedures, triggers và views để đảm bảo hiệu suất và tính toàn vẹn dữ liệu.\n- Phân tích yêu cầu, thiết kế kiến trúc hệ thống, và tham gia thảo luận để đưa ra các giải pháp kỹ thuật hiệu quả.\n- Xử lý, gỡ lỗi và khắc phục các vấn đề kỹ thuật trong môi trường production.\n- Phối hợp với các nhóm liên quan (BA, QA,) để đảm bảo chất lượng sản phẩm phần mềm.\n- Soạn thảo và cập nhật tài liệu kỹ thuật, bao gồm tài liệu thiết kế và hướng dẫn sử dụng.\n- Ứng dụng các công nghệ AI/ML để hỗ trợ phát triển sản phẩm (lợi thế).\n- Có kinh nghiệm sử dụng n8n để tự động hóa quy trình là một điểm cộng.\n\nYêu cầu ứng viên\n- Tốt nghiệp chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan.\n- Có ít nhất 2 năm kinh nghiệm phát triển phần mềm với .NET Framework/.NET Core, bao gồm C#, ASP.NET MVC, và Web API.\n- Thành thạo Microsoft SQL Server, có kinh nghiệm thiết kế cơ sở dữ liệu, tối ưu hóa truy vấn SQL, viết stored procedures và tối ưu hiệu suất.\n- Hiểu biết sâu về các nguyên tắc OOP, Design Patterns (ví dụ: Singleton, Factory, Repository) và áp dụng nguyên tắc SOLID trong phát triển phần mềm.\n- Ưu tiên ứng viên có kinh nghiệm với các công nghệ front-end: HTML, CSS, JavaScript, jQuery.\n- Thành thạo sử dụng hệ thống quản lý mã nguồn như Git hoặc SVN.\n- Kỹ năng phân tích, giải quyết vấn đề và tư duy logic tốt.\n- Khả năng giao tiếp, làm việc nhóm hiệu quả và thích nghi với môi trường làm việc năng động.\n\nQuyền lợi\n- Lương và thu nhập: 15.000.000 – 20.000.000\n- Được hưởng đầy đủ các quyền lợi về BHXH, BHYT theo luật lao động, và Bảo hiểm Tai nạn 24/7\n- Thưởng lễ tết, du lịch nghỉ mát hàng năm, trải nghiệm nội bộ\n- Môi trường làm việc chuyên nghiệp, ổn định, thân thiện và năng động\n- Được xem xét đánh giá năng lực. Lương tháng 13 và xét tăng lương 6 tháng/lần.\n- Cơ hội phát triển cao trong nghề nghiệp, phát triển khả năng của bản thân\n- Các hoạt động tập thể: CLB Thể thao, Team Building...\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 12A Núi Thành, Phường 13, Tân Bình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)\n- Sáng thứ 7: từ 08:30-12:00\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2656, 1428, 2, 'Nhân Viên Lập Trình  C#', '- Lập trình chương trình C# điều khiển Máy tự động tích hợp I/O card, motion card (Ajinextek, ADLINK, Advandtech) và các thiết bị khác.\n- Có kinh nghiệm lập trình truyền thông công nghiệp RS485, RS232, Ethernet TCP/IP, Modbus...\n- Có kinh nghiệm lập trình liên quan tới hệ thống MES, GMES, CIM\n- Làm việc với các loại máy Handler, Tester Machine\n- Có kiến thức về các linh kiện, thiết bị hệ thống điện của máy tự động\n- Cải tiến chương trình có sẵn để phù hợp với yêu cầu công nghệ.\n- Chỉnh sửa lỗi máy khi vận hành phát sinh lỗi liên quan đến phần cứng và phần mềm.\n- Có khả năng đi setup máy tại các nhà máy của Samsung\n\nYêu cầu ứng viên:\n- Có kiến thức cơ bản về lập trình C#. Đã setup máy tự động hóa của Samsung \n- Hiểu biết về các nguyên tắc phát triển phần mềm và quy trình phát triển phần mềm\n- Có khả năng học hỏi nhanh và thích nghi với công nghệ mới\n- Kỹ năng phân tích và giải quyết vấn đề tốt\n- Có kiến thức cơ bản về cơ sở dữ liệu và SQL\n- Khả năng làm việc độc lập và làm việc nhóm hiệu quả\n- Tinh thần trách nhiệm cao, chủ động trong công việc\n- Có hiểu biết cơ bản về lĩnh vực tự động hóa là một lợi thế\n\nQuyền lợi:\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội học hỏi và phát triển kỹ năng trong lĩnh vực tự động hóa và phát triển phần mềm\n- Được đào tạo và hướng dẫn bởi các chuyên gia có kinh nghiệm trong ngành\n- Lương thưởng cạnh tranh, phù hợp với năng lực\n- Được tham gia đầy đủ các chế độ bảo hiểm theo quy định của pháp luật\n- Chế độ nghỉ phép, nghỉ lễ theo quy định\n- Cơ hội thăng tiến rõ ràng dựa trên năng lực và đóng góp\n\nĐịa điểm làm việc:\n- Bắc Ninh: CÔNG TY TNHH KNK VINA, Lô CN5B-2, KCN QUẾ VÕ III, PHƯỜNG VIỆT HÙNG, THỊ XÃ QUẾ VÕ, TP Bắc Ninh\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2657, 1312, 2, 'Nhân Viên IT', 'Mô tả công việc:\n- Thiết lập hệ thống MES (Manufacturing Execution System) phù hợp với đặc thù sản xuất.\n- Kiểm tra lỗi, cập nhật phần mềm vá bảo mật và đảm bảo hệ thống hoạt động ổn định. Xử lý các vấn đề kỹ thuật phát sinh trong quá trình vận hành.\n- Thu thập, phân tích dữ liệu thời gian thực từ máy móc và quy trình sản xuất. đảm bảo tính toàn vẹn của dữ liệu để hỗ trợ ra quyết định\n- Phân tích hiệu suất SQL\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc chuyên ngành khác có liên quan\n- Quản trị cơ sở dữ liệu Microsoft SQL Server ít nhất 2 năm\n- Kiến thức cơ bản về Java để tùy chỉnh hệ thống.\n- Hiểu về nguyên lý hoạt động của MES tích hợp với ERP.\n\nQuyền lợi:\n- Được hưởng đầy đủ mọi chế độ quyền lợi của người lao động theo đúng quy định của Pháp luật\n- Lương: Thỏa thuận\n- Được tham gia BHXH, BHYT, BHTN ngay từ khi thử việc\n- Môi trường làm việc chuyên nghiệp, mức thu nhập thỏa đáng và cơ hội phát triển nghề nghiệp\n- Đánh giá xét tăng lương hàng năm theo chính sách của công ty.\n\nĐịa điểm làm việc:\n- Ninh Bình: Lô CN1, KCP Phúc Sơn, phường Ninh Sơn, TP Hoa Lư, TP Ninh Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ninh Bình, TP Ninh Bình', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2658, 209, 2, 'SAP BTP CAP Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n• Design, develop, and support application solutions focusing on SAP BTP Development.\n• Design and develop data models, queries, and custom services.\n• Develop applications using SAP Cloud Application Programming Model (CAP) on SAP BTP (Node.js/Java).\n• Develop Fiori Elements / SAPUI5 applications integrated with backend services.\n• Develop custom extensions for S/4HANA or other SAP solutions on BTP.\n• Implement and manage application security (roles, authentication, authorization) using XSUAA.\n• Perform debugging and troubleshooting of applications (Logs / Traces).\n• Work with business users to identify process improvement opportunities.\n• Collaborate with team members to perform code reviews and ensure coding best practices.\n\nYêu cầu ứng viên\nRequired Skills:\n• Experience in developing full-stack apps using SAP Business Application Studio (BAS) or Visual Studio Code.\n• Strong experience in SAP CAP Model using Node.js/Java.\n• Experience in Core Data Services (CDS) modeling and consumption.\n• Experience in developing Fiori Elements / SAPUI5 apps (OData V2 & V4).\n• Familiarity with SAP BTP services (App Router, Destination, XSUAA, Cloud Foundry environment).\n• Experience with Multi-Target Application (MTA) deployment on Cloud Foundry.\n• Experience working with SQL Script, designing tables, and managing data loads on HANA Cloud.\n• Basic understanding of Cloud Foundry & DB Security concepts (Roles, Privileges).\n• English communication is required.\n\nPreferred Skills:\n• Knowledge of SAP S/4HANA and SAP API (OData, REST APIs).\n• Experience with CI/CD pipelines on SAP BTP.\n• Familiarity with SAP Event Mesh, SAP Workflow Management is a plus.\n• Experience in code review and mentoring junior developers is a plus.\n• Experience integrating third-party services via SAP Integration Suite is a plus.\n\nQuyền lợi\n• Be part of our hugely international environment; we are currently working for Global projects, where you can have many opportunities to working overseas.\n• Attractive Salary Package based on your competence plus Annual Bonus and Project Performance Bonus.\n• Annual Summer Vacation support from 700 hundred VND to 4 Million VND and up to 3 days off work.\n• 13th-month Salary.\n• Salary review according to Company Policy.\n• Annual leave according to Labor Law and Company Policy.\n• “FPT care” health insurance provided by Petrolimex (PJICO) and is exclusive for FPT employees: 57M – 160M.\n• 20% discount on school fee if your sons/daughters join FPT School.\n• Excellent cost-free learning opportunities: Udemy/ELSA PRO accounts for every employee & Udacity accounts for Managers, English/Japanese/Korean classes, sponsorship for taking certification such as PMP, AWS, etc.\n• International, professional, dynamic and friendly working environment and culture.\n• Be part of a team in an international world-class company and exchange knowledge with technology specialists and experts from the world’s leading companies.\n• Frequent staff activities and company parties;\n• Awesome social events and parties for employees.\n• Etc.\n\nSpecial offer for senior level:\n• Relocating package: Up to 100M (for senior candidates from Hanoi/HCM.C to Da Nang City).\n• Loan support: 4% interest rate (1 – 2 Billion VND package).\n\nĐịa điểm làm việc\n- Đà Nẵng: Tòa Nhà FPT Complex, Ðường Nam Kỳ Khởi Nghĩa, Phường Hoà Hải TP.Ðà Nẵng, Ngũ Hành Sơn\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2659, 1134, 2, 'Coding Quality Review Team Lead', 'Mô tả công việc:\n- Thực hiện kiểm tra mã nguồn kỹ lưỡng cho các yêu cầu hợp nhất (pull/merge requests) trước khi đóng gói và triển khai.\n- Đảm bảo mã tuân thủ theo các tiêu chuẩn coding, nguyên tắc thiết kế và kiến trúc hệ thống.\n- Phát hiện lỗi logic, bug tiềm ẩn và các khoản nợ kỹ thuật trong mã nguồn.\n- Phối hợp với lập trình viên để đưa ra phản hồi mang tính xây dựng và hướng dẫn cải tiến.\n- Kiểm tra mức độ bao phủ và hiệu quả của các test case tự động (unit test, integration test).\n- Đảm bảo mã đáp ứng các yêu cầu về bảo mật, khả năng mở rộng và bảo trì.\n- Giám sát kết quả phân tích mã tĩnh và thực thi các chính sách kiểm duyệt (VD: SonarQube, ESLint).\n- Phối hợp với nhóm DevOps để đảm bảo mã đã sẵn sàng cho giai đoạn build, đóng gói và triển khai.\n- Ghi lại quy trình kiểm tra mã và đóng góp vào việc xây dựng các chuẩn mực chất lượng mã và DevOps.\n\nYêu cầu ứng viên:\n1. Trình độ học vấn: Bằng cử nhân về Kỹ thuật Máy tính, CNTT hoặc ngành tương đương\n2. Kinh nghiệm:\nTối thiểu có 03 năm phát triển phần mềm, DevOps hoặc vai trò kiểm duyệt mã\nCó kinh nghiệm trong lĩnh vực tài chính tiêu dùng, ngân hàng là một lợi thế.\n3. Kỹ năng:\nThành thạo ít nhất một ngôn ngữ lập trình (ví dụ: JavaScript, Python, Java, Go).\nCó kiến thức về hệ thống CI/CD (ví dụ: Jenkins, GitLab CI, GitHub Actions, Azure DevOps).\nKinh nghiệm sử dụng Git và các nền tảng như GitHub, GitLab, SonarQube, ESLint, Checkmarx,...\nHiểu rõ về nguyên tắc lập trình an toàn và các công cụ phân tích mã tĩnh.\n4. Yêu cầu khác:\nKỹ năng tư duy logic và chú ý đến chi tiết.\nKỹ năng giao tiếp và làm việc nhóm tốt.\n\nQuyền lợi:\n- Thử việc 100% mức lương;\n- Ký Hợp đồng Lao động chính thức;\n- Chế độ Bảo hiểm xã hội, Bảo hiểm thất nghiệp, Bảo hiểm y tế theo quy định Nhà nước sau 2 tháng thử việc;\n- Bảo hiểm tai nạn 24/24;\n- Khám sức khỏe định kỳ;\n- Được tham gia khóa đào tạo chuyên môn;\n- 16 ngày phép/năm;\n- Lương tháng 13, thưởng và phụ cấp tùy theo từng vị trí.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2660, 72, 2, 'Android Developer (Kotlin)', '✓ Phát triển, duy trì và cải tiến mã nguồn Kotlin dùng chung cho cả nền tảng Android và IOS, đảm bảo tích hợp mượt và hiệu quả trên cả hai hệ sinh thái. ✓ Thực hiện đánh giá kỹ lưỡng mã nguồn để đảm bảo chất lượng và triển khai hiệu quả với Kotlin Multiplatform, tuân thủ các phương pháp tốt nhất về tính duy trì và khả năng mở rộng. ✓ Tối ưu hóa mã Kotlin dùng chung, tận dụng thế mạnh riêng của từng nền tảng và duy trì mã nguồn thống nhất. ✓ Kiến trúc, review code, tối ưu để tăng trải nghiệm. ✓ Phân tích, đánh giá, lập kế hoạch phát triển, trao đổi nhóm để đưa ra nhiệm vụ cần thực thi liên quan. ✓ Cập nhật xu hướng phát triển công nghệ mới để áp dụng vào dự án. Yêu cầu ứng viên: ✓ Tốt nghiệp đại học chuyên ngành CNTT loại khá trở lên. ✓ Tối thiểu 3 - 5 năm kinh nghiệm phát triển Android với Kotlin và có kinh nghiệm với Swift/Objective-C trong phát triển IOS là một lợi thế. ✓ Thành thạo Jetpack Compose, Coroutines và Flow. ✓ Kỹ năng làm việc nhóm và giải quyết vấn đề tốt. Ưu tiên: ✓ Biết Swift/Objective C hoặc từng làm việc với ứng dụng native iOS. ✓ Có kinh nghiệm tích hợp Google Maps, Mapbox, multimedia (audio/video), hoặc WebRTC. ✓ Kinh nghiệm kết nối và xử lý dữ liệu với các thiết bị IoT qua BLE hoặc WiFi. ✓ Hiểu và áp dụng tốt Material Design, custom layout. ✓ Từng tham gia dự án theo mô hình Agile/Scrum thực tế. ✓ Kỹ năng mềm: lãnh đạo nhóm, giao tiếp, làm việc nhóm, giải quyết vấn đề. ✓ Kinh nghiệm quản lý đội nhóm. Quyền lợi: ✓ Gói thu nhập cạnh tranh. ✓ Đầy đủ các chế độ theo luật lao động hiện hành. ✓ Chính sách phúc lợi theo quy định của Công ty đa dạng: Chăm sóc sức khỏe định kì hàng năm; Gói bảo hiểm sức khỏe chuyên biệt (FPT Care – Khám chữa bệnh miễn phí tại tất cả các bệnh viện); Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân ... ✓ Môi trường làm việc thân thiện, cởi mở. ✓ Cơ sở vật chất và công cụ làm việc hiện đại, tiện nghi. ✓ ​Nhiều cơ hội phát triển và thăng tiến. ✓ Văn hóa Doanh nghiệp đặc sắc, sinh động bậc nhất với nhiều các hoạt động hấp dẫn: tân binh, teambuilding, thi trạng, hội làng, hội diễn Sao Chổi, sinh nhật FPT, ngày 08/03, ngày 11/11... ✓ Hưởng các gói ưu đãi cước khi sử dụng dịch vụ của FPT Telecom. ✓ Ghi chú: FPT Telecom không thu bất kỳ chi phí nào của Ứng viên, Sinh viên trong quá trình tuyển dụng, thực tập. Địa điểm làm việc: - Hồ Chí Minh: Lô L.29B-31B-33B đường Tân Thuận, Khu chế xuất Tân Thuận, phường Tân Thuận Đông, Quận 7. Thời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:30). Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2661, 1429, 2, 'Senior Rust Developer', 'About Us\nWe’re building next-generation decentralized infrastructure to power applications at the edge of connectivity and compute. Our platform enables contributors to share bandwidth, compute, and storage – creating a trust-minimized, permissionless network backbone for the future of the internet.\nWe’re looking for a Senior Rust Developer with deep understanding of networking concepts and a passion for low-level systems programming. You\'ll be a core contributor to our protocol stack, working on high-performance services, peer-to-peer systems, and distributed runtime environments.\n\nLocation: Remote / Hybrid\nType: Full-time\nExperience Level: Senior\nSalary: Competitive, with equity options available\n\nWhat You\'ll Do\n- Architect and implement performant network protocols, proxies, and overlay services in Rust.\n- Build P2P systems, NAT traversal techniques (e.g., STUN, TURN, hole punching), and custom messaging layers.\n- Contribute to our edge runtime, handling bandwidth-sharing, node discovery, and transport layer logic.\n- Develop and maintain safe, efficient async systems using tokio, async-std, or similar frameworks.\n- Collaborate with distributed systems engineers, cryptographers, and DevOps on protocol design and deployment strategy.\n- Mentor junior developers and participate in architecture reviews and code audits.\n\nYêu cầu ứng viên\n- Strong understanding of networking concepts: TCP/UDP, DNS, TLS, WebRTC, gRPC, NAT, Anycast, etc.\n- Experience with asynchronous programming and concurrency patterns in Rust.\n- Deep knowledge of systems-level concepts like memory management, multithreading, and I/O performance.\n- Experience building distributed or peer-to-peer systems.\n- Proficient in debugging, profiling, and performance tuning.\n\nQuyền lợi\n- Gross Salary: $1300-$2000\n- Paid social insurance premiums, project bonuses, monthly and quarterly bonuses for employees, other benefits, and holiday bonuses.\n- Working in a dynamic environment with many interesting projects, developing and applying the latest technologies.\n- Fast growing company with many opportunities for growth and advancement\n- Supported internal courses/training to improve professional skills.\n- Other benefits: periodic team building, annual travel, vacation...\n- Many activities: weekly football club, year-round football tournament, table tennis, ...\n\nBonus Points For\n- Experience with VPNs, proxies, or custom overlay networks\n- Experience with edge computing, IoT, or embedded systems.\n- Understanding of libp2p, QUIC, Noise protocol, or similar stacks.\n\nWhy Join Us\n- Work on cutting-edge decentralized infrastructure with real-world impact.\n- Join a tight-knit, high-caliber team pushing boundaries of distributed tech.\n- Token incentives and equity for long-term contributors.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 105 Cô Giang, Quận 1\n\nThời gian làm việc\n- Thứ 2 đến thứ 7 cách tuần, 8h30-18h, nghỉ trưa 1h30m\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2662, 1430, 2, 'Fullstack Developer (NodeJS/PHP/Python) - Upto 40 Tr', 'Mô tả công việc:\n- Tham gia phát triển các dự án Web của khách hàng.\n- Tham gia phân tích yêu cầu, thiết kế hệ thống, thiết kế Database, phát triển các chức năng.\n- Thực hiện công việc theo mô hình Agile/ Scrum, lập kế hoạch, thực hiện, kiểm soát và báo cáo công việc theo từng Sprint.\n- Hỗ trợ đào tạo, chia sẻ kiến thức, review code cho các thành viên trong team.\n- Tham gia build team, quản lý team (nếu đã có kinh nghiệm).\n- Nghiên cứu và định hướng các công nghệ mới áp dụng vào dự án.\n\nYêu cầu ứng viên:\n- Tốt nghiệp CĐ/ĐH chuyên ngành CNTT hoặc có liên quan.\n- Ít nhất 3 năm kinh nghiệm Backend (NodeJS/PHP/Python) và 2 năm Frontend (VueJS/ReactJS/Angular)\n- Thao tác tốt với HTML/ CSS/ jQuery/ AJAX/...\n- Có kiến thức nền tảng tốt về OOP, Coding Convention, Architecture Patterns (MVC, MVP, MVVM).\n- Hiểu biết về Restful API, Design Pattern,...\n- Có kinh nghiệm thiết kế và xây dựng cơ sở dữ liệu với SQL/ NoSQL.\n- Có khả năng tư duy, học hỏi nhanh; chủ động trong công việc; làm việc độc lập và làm việc nhóm tốt.\n- Ứng dụng AI trong công việc.\n\nLợi thế (không bắt buộc):\n- Ưu tiên ứng viên đã làm trong các dự án theo mô hình Agile/ Scrum.\n- Có kinh nghiệm team leader là lợi thế.\n- Có các chứng chỉ ngoại ngữ/ chuyên môn như IELTS, JLPT, AWS, PSM,... là lợi thế.\n\nQuyền lợi:\n- Mức lương: 20.000.000 - 40.000.000 VND (thỏa thuận theo từng level).\n- Thưởng cuối năm theo hiệu suất làm việc và tình hình kinh doanh của công ty.\n- Thưởng hoặc quà tặng các dịp lễ, sinh nhật.\n- Review tăng lương 6 tháng/lần.\n- Hỗ trợ 100% học phí và lệ phí thi các chứng chỉ chuyên môn.\n- Gói khám sức khỏe định kỳ hàng năm; đóng bảo hiểm (BHXH, BHYT, BHTN) và các chế độ khác đầy đủ theo quy định của Luật lao động (chế độ nghỉ phép, lương làm thêm giờ...).\n- Cơ hội thăng tiến cao trở thành Team Leader, Techlead, PM.\n- Được hỗ trợ nâng cao kiến thức, kỹ năng thông qua các hoạt động: Seminar; CLB chuyên môn; Các khóa đào tạo từ học viện uy tín,...\n- Hỗ trợ định hướng lộ trình phát triển bản thân, định hướng mục tiêu cá nhân (OKR, 1on1 với mentor nhiều kinh nghiệm).\n- Luôn tạo môi trường làm việc IT thoải mái, năng động và đặc biệt hỗ trợ nhau trong công việc.\n- Tham gia các hoạt động tập thể của công ty: Team building, du lịch, CLB bóng đá, happy hour hàng tháng...\n- Cung cấp đầy đủ thiết bị làm việc; Free trà, cafe,...\n\nĐịa chỉ văn phòng mới: Tòa nhà NHS Trung Văn, Tố Hữu, Nam Từ Liêm, Hà Nội (từ 01/08/2025)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2663, 529, 2, 'Junior Frontend Developer (Fulltime)', 'Mô tả công việc:\n- Tham gia thiết kế, xây dựng nền tảng học tập cho trung tâm đào tạo IELTS IZONE. Phụ trách phát triển các dự án EdTech tại IZONE.\n- Xây dựng các tính năng cho giao diện người dùng tuân theo các tiêu chuẩn thiết kế, đảm bảo khả năng bảo trì và mở rộng.\n- Bảo trì và hoàn thiện các vấn đề còn tồn đọng và đề xuất cải thiện.\n- Thu thập ý kiến phản hồi và xây dựng các hướng giải quyết cho người sử dụng và khách hàng để cải tiến và nâng cao chất lượng dự án.\n- Là cầu nối giữa việc việc thiết kế và xây dựng mã nguồn, phối hợp giữa các bên để đem tới cho người dùng sản phẩm tốt nhất.\n\nNội dung TECH liên quan:\n- React kết hợp với CSS framework Tailwind.\n- Quản lý data model với MobX\n- Java, Postgres và Redis ở Backend\n- Git\n- Design system với các thư viện React UI Component\n- Prosemirror-based content editor\n\nYêu cầu ứng viên:\n- Có trên 1 năm kinh nghiệm làm việc ở vị trí Frontend Engineer\n- Có kiến thức chuyên môn về HTML, CSS và JavaScript & Typescript\n- Có kinh nghiệm chuyên môn về framework web ReactJS\n- Nắm vững các khái niệm cốt lõi về web và trình duyệt (ví dụ: cách trình duyệt phân tích cú pháp HTML và xây dựng một trang web)\n- Có kiến thức, hiểu biết sâu và kinh nghiệm làm việc với design system.\n- Có thể phân tích bug và đề xuất giải pháp cho các module phần mềm từ cơ bản đến phức tạp\n\nQuyền lợi:\n- Thu nhập: 12.500.000 - 15.000.000 VNĐ /tháng\n- Cung cấp trang thiết bị làm việc\n- Review lương định kỳ, tháng lương thứ 13 cho nhân sự\n- Nghỉ phép 12 ngày/năm\n- Đóng BHXH đầy đủ\n- Môi trường startup năng động, chuyên nghiệp, tư duy mở, không giới hạn các việc đề xuất, phát triển ý tưởng.\n- Học miễn phí các khoá học IELTS tại trung tâm.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 4 ngõ 95 Hoàng Cầu, Đống Đa\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2664, 1431, 2, 'Lập Trình Viên PHP', 'Mô tả công việc\n● Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng \n● Làm việc onsite Nhật tùy theo yêu cầu khách hàng.\n● Hợp tác và trao đổi công việc với Team Member, Team Leader.\n● Tham gia phát triển các công đoạn phân tích yêu cầu, Detail Design, Coding, viết tài liệu API, Unit Test.\n● Sử dụng ngôn ngữ PHP và các framework như Laravel, Yii2, ...\n● Báo cáo hàng ngày, hàng tuần cho PM và các member khác theo mô hình Agile.\n● Quản lý Tranning member\n\nYêu cầu ứng viên\n- Từ 3 năm kinh nghiệm sử dụng Framework Laravel, 1 năm kinh nghiệm teamleader\n- Có kinh nghiệm làm việc với MySQL, SQL.\n- Hiểu biết mô hình MVC Framework, ORM, RESTful, OOP.\n- Có kinh nghiệm làm việc với HTML/CSS/Javascript (jQuery/Ajax/JSON), Bootstrap,...\n- Có kiến thức về cloud, AWS\n- Viết code rõ ràng, dễ hiểu, dễ bảo trì, tuân thủ chặt chẽ coding convention.\n- Sử dụng tốt Git, SVN.\n- Có kinh nghiệm làm việc với NoSQL, MongoDB.\n- Hiểu biết và sử dụng Design Pattern.\n- Có kinh nghiệm phân tích yêu cầu, thiết kế hệ thống web.\n- Có kinh nghiệm thiết kế cơ sở dữ liệu quan hệ, tối ưu hoá SQL query.\n- Có tinh thần ham học hỏi, làm việc độc lập và tư duy lập trình tốt.\n\nQuyền lợi\n1. Thời gian và môi trường làm việc\n- Thời gian làm việc linh động 5 ngày/tuần từ 8h00 -17h30 hoặc 8h30 - 18h00 (nghỉ Thứ 7, Chủ Nhật).\n- Môi trường làm việc chuyên nghiệp, năng động, công bằng, đồng nghiệp dễ thương.\n- Tôn trọng ý kiến cá nhân, đề cao sự sáng tạo.\n- Văn phòng làm việc rộng rãi, trang phục tự do thoải mái.\n- Tham gia các câu lạc bộ: Tiếng Nhật, tiếng Anh, bóng đá, game,...\n\n2. Lương và Phúc Lợi\n- Đánh giá tăng lương 2 lần/năm,mức tăng lên đến 30%/lần.\n- Thu nhập năm 13 - 15 tháng lương (tối thiểu 13 tháng lương, tùy theo kết quả có thể lên đến 15 tháng lương).\n- Thưởng: 2 lần/năm, ngoài ra có thưởng nhân viên xuất sắc, thưởng Tết, thưởng giới thiệu nhân sự,...\n- Trợ cấp ăn trưa: 30.000/ngày, gửi xe, tiếng Nhật, tiếng Anh, chứng chỉ IT, trợ cấp chức vụ.\n- Nghỉ phép 12 ngày/năm, nghỉ ngày lễ kỷ niệm của gia đình: 1 ngày/năm, làm việc từ 6 tháng được tăng thêm ngày nghỉ phép.\n- Chế độ chăm sóc phụ nữ: nghỉ sinh lý 0.5 ngày/tháng.\n- Du lịch 1 lần/năm trong nước hoặc nước ngoài.\n- Tham gia các hoạt động Team Building thường xuyên như: Tiệc sinh nhật, Happy Lunch, Workshop,...\n- Khám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín.\n- Được cung cấp thiết bị phục vụ công việc: MacBook, iPad,...\n- Tham gia đầy đủ Bảo hiểm tuân thủ theo Luật Lao động hiện hành.\n\n3. Cơ hội phát triển, thăng tiến\n- Được training từ chuyên gia công nghệ người Nhật giàu kinh nghiệm.\n- Có nhiều hoạt động nâng cao chuyên môn (Seminar, Workshop, Techtalk,...)\n- Có cơ hội thăng tiến lên các vị trí Manager.\n- Có cơ hội làm việc và đào tạo tại Nhật Bản.\n\nĐịa điểm làm việc\n- Hà Nội\n- Hà Nội: Tòa Nhà Việt, số 1 Thái Hà, Đống Đa\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2665, 1432, 2, 'Lập Trình Viên', '1. Thiết kế giải pháp\n- Làm việc với các phòng ban để thiết kế giải pháp phần mềm nhằm giảm khối lượng công việc, tăng hiệu quả hoạt động.\n- Áp dụng công nghệ mới và framework mới vào thiết kế giải pháp để tạo ra giải pháp tốt và linh hoạt để thích ứng với các thay đổi kinh doanh.\n2. Phát triển phần mềm\n- Phát triển ứng dụng phần mềm để phù hợp với yêu cầu hoạt động và hướng dẫn của cấp trên.\n- Cập nhật tất cả các vấn đề, lỗi, tính năng mới, yêu cầu cải tiến vào hệ thống bàn dịch vụ, cập nhật nhật ký công việc hàng ngày, đẩy mã nguồn vào phần mềm JIRA.\n- Tìm nguyên nhân gốc và khắc phục, trình lên cấp trên nếu không thể giải quyết hoặc khắc phục trong SLA.\n- Giám sát danh sách nhiệm vụ và hoàn thành trong thời gian cam kết\n- Hợp tác với team quản lý dự án, team vận hành để làm bài kiểm tra và UAT cho ứng dụng.\n- Thực hiện, đào tạo cho người dùng cuối.\n3. Các công việc khác theo sự phân công từ cấp trên.\n\nYêu cầu ứng viên\n- Tốt nghiệp Cao đẳng/ Đại học với chuyên ngành CNTT, viễn thông, khoa học máy tính hoặc các ngành nghề khác có liên quan.\n- Ít nhất 1 năm kinh nghiệm tại vị trí tương tự.\n- Tiếng Anh trình độ trung cấp.\n\nQuyền lợi\n- Lương cạnh tranh + phụ cấp xăng xe.\n- Bảo hiểm xã hội & bảo hiểm tai nạn lao động 8/24.\n- Lương tháng 13 hàng năm.\n- Du lịch hàng năm, teambuilding, khám sức khỏe.\n- Môi trường làm việc chuyên nghiệp với nhiều cơ hội đào tạo & phát triển.\n\nĐịa điểm làm việc\n- Hà Nội: Xuân Thủy, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n- Thứ 7 (từ 08:00 đến 12:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2666, 1433, 2, 'Blockchain Developer (Có Xe Đưa Đón)', 'Mô tả công việc\nNghiên cứu sâu về các giao thức blockchain hiện tại, các mô hình đồng thuận, kiến trúc hệ thống và các tiêu chuẩn về ANTT liên quan tới blockchain.\nPhát triển và đề xuất các tiêu chuẩn kỹ thuật, giao thức và quy trình nhằm tối ưu hóa khả năng mở rộng, bảo mật và khả năng tương tác giữa các blockchain.\nPhân tích các xu hướng công nghệ blockchain, đặc biệt là các tiêu chuẩn quốc tế như ERC (Ethereum Request for Comments), BIP (Bitcoin Improvement Proposals), ISO/TC 307...\nViết báo cáo nghiên cứu, whitepaper và tài liệu kỹ thuật nhằm chia sẻ kiến thức và định hướng công nghệ.\nĐánh giá và kiểm định các giải pháp blockchain để đảm bảo tuân thủ các tiêu chuẩn và đề xuất cải tiến phù hợp.\nPhối hợp với các nhóm phát triển, đối tác công nghệ để triển khai các giải pháp theo tiêu chuẩn nghiên cứu được đề xuất.\n\nYêu cầu ứng viên\nTốt nghiệp đại học trở lên trong các lĩnh vực liên quan đến Khoa học máy tính, Mật mã học, Kỹ thuật phần mềm hoặc tương đương.\nCó kinh nghiệm làm việc trong lĩnh vực blockchain ít nhất 2 năm, đặc biệt là nghiên cứu về tiêu chuẩn và giao thức.\nKiến thức vững chắc về các thuật toán đồng thuận (PoW, PoS, DPoS, PBFT...), smart contract, tokenomics và các hệ thống phi tập trung.\nHiểu biết sâu về các tiêu chuẩn blockchain phổ biến như ERC, BIP, ISO/TC 307, W3C Blockchain.\nCó kinh nghiệm nghiên cứu và viết báo cáo khoa học, tài liệu kỹ thuật hoặc whitepaper.\nThành thạo ít nhất một trong các ngôn ngữ lập trình liên quan đến blockchain như Solidity, Rust, Go, hoặc Python.\nCó khả năng làm việc độc lập và phối hợp tốt với các nhóm nghiên cứu, cộng đồng blockchain.\nKỹ năng giao tiếp, thuyết trình và truyền đạt ý tưởng rõ ràng.\nƯu tiên có bằng cấp hoặc chứng chỉ liên quan đến blockchain, mật mã học hoặc an ninh mạng.\nƯu tiên Kinh nghiệm làm việc với các tổ chức như Ethereum Foundation, Hyperledger, ISO, hoặc các tổ chức tiêu chuẩn hóa blockchain khác.\n\nQuyền lợi\nMức lương: Thỏa thuận, tùy theo năng lực. \nThưởng quý, Thưởng Năm \nĐược xét tăng lương 02 lần/ 01 năm.\nĐược nghỉ thứ bảy và chủ nhật.\nĐược đào tạo về các nội dung chuyên môn.\nChế độ nghỉ mát hàng năm, khám sức khỏe hàng năm.\nCác hoạt động gắn kết khác: Thank-you party; Team building, Sinh nhật Công ty; Du lịch...\nĐược đóng bảo hiểm y tế, bảo hiểm xã hội và các chế độ phúc lợi khác.\nĐược hưởng chế độ chăm sóc sức khỏe cao cấp PTI.\nĐược vận hành, sử dụng các trang thiết bị hiện đại.\nMôi trường làm việc thân thiện, trẻ trung, chia sẻ, kết nối.\n\nĐịa điểm làm việc\n- Hưng Yên: Trung Hòa, Yên Mỹ\n- Hà Nội: Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hưng Yên, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2667, 1200, 2, 'Middle Fullstack Developer', 'Mô tả công việc\nPhát triển sản phẩm phần mềm sử dụng BE: Java spring, ReactJS, Bootstrap, Javascript,... FE: Angular cho các đối tượng khách hàng khác nhau.\nĐược tham gia sâu vào các giai đoạn của một dự án như: phân tích, thiết kế, lập trình, kiểm thử, bảo trì phần mềm\nLập trình các module theo thiết kế và theo công việc được phân công trong dự án tham gia\n\nYêu cầu ứng viên\nKinh nghiệm tối thiểu 02 năm kinh nghiệm lập trình\n\n1. Kiến thức về Angular, ZK:\nThành thạo Angular, ZK, hiểu rõ các concepts như components, directives, services, modules, và pipes.\nKinh nghiệm làm việc với Angular CLI để xây dựng và quản lý ứng dụng.\nKinh nghiệm với Angular Routing, Forms (Reactive và Template-driven), và Dependency Injection.\nKiến thức vũng về TypeScript, bao gồm typing, interfaces, generics và decorators.\nThành thạo HTML5 và CSS3, khả năng xây dựng giao diện responsive.\nKinh nghiệm với JavaScript, ES6+ và các khái niệm như closures, promises, async/await.\n\n2. Frontend Tools:\nKinh nghiệm sử dụng các công cụ build như Webpack, NPM, và các package manager.\nQuen thuộc với Git và quản lý mã nguồn.\n\n3. Java:\nThành thạo OOP, exception handling, collections, streams & lambda.\nHiểu về multithreading và concurrency.\n\n4. Spring Boot:\nBiết cách sử dụng Spring Boot để phát triển ứng dụng nhanh chóng.\nThành thạo Spring Data JPA, Spring Security, và Spring RESTful APIs.\n\n5. Oracle, MariaDB\nKinh nghiệm SQL, PL/SQL, và thiết kế cơ sở dữ liệu.\nQuen với công cụ như Oracle SQL Developer và tối ưu hóa truy vấn.\n\nQuyền lợi\nMức lương up to 30M.\nThời gian làm việc: 8h00-17h30, nghỉ trưa 1,5h (12h – 13h30) từ thứ 2 - thứ 6\n13 tháng lương + thưởng lễ tết; xét tăng lương hàng năm\nDu lịch hàng năm, team building hàng tháng/quý\nBảo hiểm xã hội, BHYT theo quy định của Nhà nước\nGói bảo hiểm sức khỏe\nKhám sức khoẻ định kỳ hàng năm\nMôi trường flat trẻ trung, thoải mái\nCơ hội tham gia dự án tiềm năng, thử thách nhưng không kém phần thú vị.\n\nĐịa điểm làm việc\n- Hà Nội: Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2668, 1282, 2, 'Nhân Viên Lập Trình Mobile', 'Mô tả công việc\n- Xây dựng và lập kế hoạch phát triển các ứng dụng trên mobile (Android,IOS) theo định hướng của Công ty;\n- Phát triển ứng dụng mobile trên nền tảng (Android, IOS);\n- Cập nhật phản hồi từ người dùng, xử lý lỗi phát sinh;\n- Bảo trì và hỗ trợ các vấn đề liên quan đến chuyên môn;\n- Nghiên cứu tối ưu hóa sản phẩm, dịch vụ đã phát triển, cải thiện trải nghiệm của người dùng;\n- Thực hiện các công việc khác theo chỉ đạo và phân công của Trưởng bộ phận và BLĐ.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành khác am hiểu lập trình;\n- Có kỹ năng lập trình Mobile bằng Flutter; React Native hoặc tương đương;\n- Có khả năng phân tích, sáng tạo, chịu áp lực công việc, có tinh thần học hỏi, tận tâm trong công việc;\n- Đã có kinh nghiệm chủ trì hoặc tham gia phát triển ứng dụng Mobibe tối thiểu 1 năm;\n- Làm việc ổn định tại Hà Nội.\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực và kinh nghiệm;\n- Được hưởng các chế độ BHYT, BHXH theo quy định của Nhà nước; Các chính sách phúc lợi của Công ty;\n- Làm việc trong môi trường năng động, chuyên nghiệp, bình đẳng, phát huy tính sáng tạo của nhân viên;\n- Được trang bị đầy đủ trang thiết bị làm việc;\n- Được trau dồi kỹ năng về chuyên môn và nghiệp vụ;\n- Được tham gia, đóng góp vào các dự án phát triển của Công ty;\n- Thưởng theo thành tích làm việc.\n\nĐịa điểm làm việc\n- Hà Nội: 101 Láng Hạ, Đống Đa.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30);\n- Thứ 7 (từ 08:00 đến 12:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2669, 1434, 2, 'Kĩ Sư Tích Hợp - DotNet Developer', 'Mô tả công việc:\n- Chịu trách nhiệm Lập trình phần mềm, các module tích hợp dựa trên các sản phẩm, giải pháp, nền tảng lõi nhằm đáp ứng đầy đủ và tổng quan cho các yêu cầu cụ thể của khách hàng doanh nghiệp.\n- Tham gia vào các công đoạn khác của Tích hợp hệ thống Phần mềm từ Thiết kế, kiến trúc phần mềm, kiến trúc tích hợp; Phân tích thông tin, yêu cầu; Phát hiện và sửa lỗi phần mềm; Kiểm thử và tối ưu phần mềm.\n- Tham gia xây dựng, soạn thảo và trình bày các giải pháp (solution), đề xuất (proposal), bài thuyết trình (presentation), chứng minh giải pháp (POC) phù hợp đáp ứng các yêu cầu cụ thể của khách hàng và các gói thầu được giao.\n- Chịu trách nhiệm tư vấn thiết kế và triển khai các giải pháp về Tích hợp hệ thống (System Integration) cho khách hàng doanh nghiệp và tổ chức viễn thông\n- Đánh giá, Tích hợp & Tối ưu các thành phần phù hợp vào hệ thống tổng thể đáp ứng cho các yêu cầu vận hành và quản lý của khách hàng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính,...\n- Tối thiểu 02 năm kinh nghiệm về phát triển phần mềm.\n- Yêu cầu ngôn ngữ: C#, ASP.NET, MVC, .NET framework , Entity Framework, OOP.\n- Hiểu biết về python/nodejs là lợi thế\n- Yêu cầu kiến thức về JavaScript, CSS, HTML, bootstrap, Ext.js.\n- Xây dựng Web Service và tích hợp API.\n- Kinh nghiệm về làm việc với API, SOAP, Rest.\n- Kinh nghiệm về sử dụng ứng dụng quản lý source: git, bitbucket .....\n- Kinh nghiệm với SQL và / hoặc cơ sở dữ liệu quan hệ / hoặc cơ sở dữ liệu NoSQL là một lợi thế.\n\nQuyền lợi:\n- Thời gian làm việc: 08h00-17h00 (từ thứ 2- thứ 6)\n- Phúc lợi: chế độ lương hấp dẫn,chế độ phúc lợi khác theo Luật lao động và chính sách của công ty.\n- Được tham gia đầy đủ BHXH theo quy định nhà nước và gói bảo hiểm sức khỏe cho nhân viên.\n- Cấp Laptop làm việc.\n- Du lịch hàng năm, các hoạt động nội bộ mỗi tháng.\n\nĐịa điểm làm việc:\n- Hà Nội: 9 Đào Duy Anh, Đống Đa\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2670, 1435, 2, 'Flutter Developer', 'Mô tả công việc\n- Phát triển, tối ưu ứng dụng mobile sử dụng Flutter, ngôn ngữ Dart.\n- Tham gia vào toàn bộ quy trình phát triển phần mềm: từ phân tích yêu cầu, thiết kế, coding, testing đến triển khai.\n- Cộng tác với các nhóm thiết kế UI/UX, Backend, QC để đảm bảo chất lượng sản phẩm.\n- Thường xuyên cập nhật công nghệ mới, tối ưu hiệu suất ứng dụng.\n\nYêu cầu ứng viên\n- Có thể đi onsite Hà Nội 2-3 tháng đầu của dự án.\n- Tiếng Anh cơ bản: đọc hiểu, giao tiếp chuyên ngành.\n- Từ 2 năm kinh nghiệm lập trình Mobile Flutter trở lên.\n- Hiểu biết về Lifecycle của ứng dụng Flutter và Performance Optimization.\n- Thành thạo Dart và các kiến trúc lập trình (MVC, MVVM, MVP, Clean Architecture).\n- Có kinh nghiệm làm việc với REST API, Firebase và State management (Provider/ Bloc/ GetX).\n- Kinh nghiệm áp dụng AI vào công việc.\n- Kinh nghiệm làm việc với Firebase, Google map, Payment, Notification.\n- Kinh nghiệm làm việc với Layer Architecture.\n- Kinh nghiệm làm việc với Repository Pattern.\n- Kinh nghiệm làm việc với Git, CI/CD, phương pháp phát triển Agile/Scrum.\n- Kinh nghiệm về security với app mobile là lợi thế: Mã hóa dữ liệu, Bảo mật API Key, Secure Store, xác thực OAuth2, JWT.\n- Kinh nghiệm lập trình công nghệ Native (Swift/ Kotlin/ Java/ Objective-C) là lợi thế.\n- Kinh nghiệm lập trình Frontend web (ReactJS, VueJS, Angular CLI) là lợi thế.\n- Kinh nghiệm lập trình Backend (Node.js, Firebase, C#, Java) là lợi thế.\n- Có ứng dụng thực tế đã triển khai trên Apple Store/ Google Play là lợi thế.\n- Kỹ năng làm việc nhóm, chủ động trong công việc.\n\nQuyền lợi\n- Mức lương: thương lượng phù hợp với năng lực ứng viên.\n- Thu nhập năm: 13 tháng lương.\n- Thưởng dự án: theo định kỳ/ theo năng lực cá nhân.\n- Thưởng Lễ, Tết, sinh nhật công ty...\n- Review lương định kỳ 1 lần/năm. Có định hướng career path rõ ràng.\n- Khám sức khỏe định kỳ hàng năm và được đóng BHXH, BHYT, BHTN đầy đủ theo luật lao động.\n- Các events: Company Trip hàng năm, Team building hàng quý, Happy Hour hàng tháng, Halloween, Christmas, Family Day…\n- Làm việc môi trường năng động. Tiếp cận với nhiều công nghệ mới, luôn được hỗ trợ nhiệt tình.\n\nĐịa điểm làm việc\n- Thừa Thiên Huế: Tầng 8, tòa nhà HCC, 72 Phạm Văn Đồng, TP Huế.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\n- Vui lòng liên hệ theo thông tin phía trên.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2671, 1213, 2, 'Kỹ Sư Lập Trình', '- Tham gia giai đoạn triển khai sản phẩm của siêu dự án phần mềm CAD – dự án lớn của tập đoàn DTS Japan, với nhiều modules phần mềm khác nhau, từ Windows App, Web App, iOS App…\n- Tuân thủ quy trình phát triển phần mềm chuẩn PMS của DTS Japan\n\n- Ứng viên có kinh nghiệm từ 6 tháng đến dưới 2 năm kinh nghiệm về ngôn ngữ phát triển phần mềm ứng dụng\n- Ưu tiên ứng viên có kiến thức về xử lý đồ họa 3D, 2D; có kinh nghiệm làm dự án liên quan đến phần mềm CAD, đồ họa\n- Ưu tiên ứng viên biết tiếng Nhật và có kinh nghiệm làm việc cho công ty/ dự án Nhật\n\nChế độ đãi ngộ\nLương thỏa thuận theo năng lực thực tế của ứng viên. Performance review: 1 lần/năm.\nTrợ cấp đi lại, trợ cấp ăn trưa, trợ cấp tiếng Nhật, trợ cấp onsite khi tham gia dự án bên khách hàng…\nThưởng Lễ Tết, tháng lương thứ 13, thưởng nhân viên xuất sắc quý, năm, nhân viên xuất sắc năm đi du lịch Nhật Bản\nNghỉ theo lịch công ty, nghỉ theo lịch khách hàng Nhật, (ngoài các ngày nghỉ theo quy định, 1 năm có thêm 2 đợt nghỉ dài)\nNghỉ tham gia Ngày hội khai giảng cùng con\nChế độ chăm sóc sức khỏe cho nhân viên\n\nBảo hiểm y tế, bảo hiểm xã hội, bảo hiểm thất nghiệp theo quy định của Luật lao động\nBảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên làm việc trên 1 năm\nKhám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín (Bệnh viện Thu Cúc, bệnh viện Medlatec…)\nVăn phòng làm việc tiện ích: Miễn phí trà, có máy pha coffee tại khu vực ăn uống của công ty\n\nCác hoạt động sôi nổi\nHoạt động team building kết nối đội nhóm hàng quý\nCác CLB thể thao: bóng đá, bi lắc…\nHoạt động du lịch, team building thường niên và các sự kiện lớn trong công ty\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 3 - Tòa nhà Ladeco 266 Đội Cấn, Ba Đình\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2672, 1436, 2, 'Data Integration Engineer / ETL Developer', 'Mô tả công việc:\n- Thiết kế, cấu hình và bảo trì flow Asteria Warp để tự động hóa quá trình lấy – biến đổi – xuất dữ liệu giữa nhiều nguồn như DB, FTP/SFTP, API, file CSV/Excel…\n- Tối ưu hiệu năng, giám sát vận hành, xử lý sự cố và đề xuất cải tiến cho các luồng tích hợp dữ liệu.\n- Phân tích yêu cầu nghiệp vụ, lập tài liệu thiết kế, test case, hướng dẫn vận hành; tham gia review chéo bảo đảm chất lượng.\n- Phối hợp chặt chẽ với PM/BrSE và QA để hoàn thành mục tiêu dự án đúng tiến độ và tiêu chuẩn khách hàng Nhật Bản.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Công nghệ Thông tin hoặc tương đương.\n- Kinh nghiệm thực tế với Asteria Warp (hoặc công cụ ETL/low-code tương đương).\n- Kiến thức nền tảng về cơ sở dữ liệu và SQL; kinh nghiệm Oracle hoặc PostgreSQL là lợi thế.\n- Có khả năng lập tài liệu kỹ thuật, tuân thủ quy trình phát triển phần mềm.\n- Tư duy logic, chủ động học hỏi, đam mê công nghệ tích hợp dữ liệu.\n- Tiếng Nhật (N3 trở lên) là điểm cộng lớn.\n- Biết C# /.NET là một lợi thế.\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc; \n- Thu nhập: 13 tháng lương/năm + thưởng kinh doanh cuối năm + thưởng dự án, thưởng các dịp lễ…; \n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc; \n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty; \n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30); \n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành; \n- Bảo hiểm chăm sóc sức khỏe 24/24; \n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội; \n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện); \n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày; \n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành;\n- Miễn phí đồ uống tại khu ăn uống của công ty; \n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan; \n- Phụ cấp thâm niên; phụ cấp chức vụ; \n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLUB Dance;...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm;...\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2673, 1437, 2, 'Project Manager JLPT N2', '● Quản lý dự án theo sự sắp xếp của đơn vị\n● Đảm nhiệm các công việc về quản lý dự án: lập kế hoạch, theo dõi tiến độ, quản lý chất lượng, quản lý yêu cầu.\n● Kiểm soát và xử lý các sự cố, phát sinh, rủi ro và thay đổi trong dự án.\n● Dự trù và quản lý chi phí của các hạng mục công việc (nếu cần)\n● Là người chịu trách nhiệm cao nhất về tiến độ, chất lượng dự án với phía onsite và khách hàng.\n● Đảm nhiệm việc quản lý nguồn lực của dự án: tạo động lực, định hướng phát triển và đánh giá chất lượng công việc của các thành viên trong dự án.\n● Là đầu mối làm việc trực tiếp với onsiter, khách hàng và các phòng ban liên quan.\n● Hỗ trợ, hướng dẫn, training các thành viên trong dự án về mặt quy trình, nghiệp vụ, ...\n● Hướng dẫn đội nhóm trở thành một cross-function & self-organize team.\n● Hướng dẫn team tập chung vào việc phát triển các function để đảm bảo đáp ứng được Definition of Done\n● Giải quyết, tháo gỡ các vấn đề cản trở đến công việc của team.\n● Tham gia vào các hoạt động training, seminar trong đơn vị & tổ chức\n\n● Từ 2 năm kinh nghiệm lập trình với bất kỳ ngôn ngữ nào\n● Có kinh nghiệm quản lý dự án > 3 năm (team size 5-10 members)\n● Hiểu rõ và thực hành tốt về quản lý dự án (quản lý yêu cầu, nguồn lực, công việc, thời gian, chi phí, liên lạc,...)\n● Khả năng phân tích, nhìn nhận vấn đề bao quát, kỹ năng mềm tốt.\n● Hiểu rõ và thành thạo vận dụng Scrum trong dự án phần mềm.\n● Kỹ năng giải quyết vấn, kỹ năng giao tiếp tốt.\n● Tiếng nhật N2 hoặc tương đương (giao tiếp tốt)\n● Có kinh nghiệm làm việc trong lĩnh vực IT outsourcing, đã làm việc với khách hàng Nhật.\n● Năng động, chủ động trong công việc.\n● Sẵn sàng thử thách ở vị trí, dự án mới\n\n- Mức lương: upto 2500$ - Fix 13+ tháng lương/ năm, chưa tính các khoản thưởng khác (thưởng KPI, thưởng dự án và thưởng doanh thu).\n- Được học tiếng Nhật, tiếng Hàn, tiếng Anh miễn phí tại công ty.\n- Khám sức khỏe định kỳ các bệnh viện lớn\n- Bảo hiểm chăm sóc sức khỏe PVI\n- Các hoạt động team building hàng quý và company trip 1 lần/năm\n- Được tham gia các câu lạc bộ như Bơi, Chạy, Zumba, Yoga,...\n- Và nhiều các đãi ngộ hấp dẫn khác.\n- Làm việc trong môi trường trẻ trung, năng động, cơ hội thăng tiến cao, phát huy toàn bộ tính sáng tạo và năng lực\n- Thời gian làm việc: 8h30 - 17h30 – Thứ Hai đến Thứ Sáu (nghỉ thứ 7, chủ nhật)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2674, 1187, 2, 'Middle/Senior Fullstack (Java, Python & Frontend) Developer', 'Mô tả công việc\n- Phát triển và duy trì các ứng dụng web với kiến trúc fullstack, sử dụng Java hoặc Python cho backend và các framework hiện đại cho frontend.\n- Thiết kế và xây dựng các RESTful API để giao tiếp giữa các dịch vụ.\n- Xây dựng giao diện người dùng động và phản hồi tốt bằng các framework như ReactJS, Angular hoặc VueJS.\n- Quản lý cơ sở dữ liệu quan hệ và/hoặc NoSQL (MySQL, PostgreSQL, MongoDB, Redis).\n- Đóng gói ứng dụng bằng Docker để đảm bảo môi trường phát triển và triển khai nhất quán.\n- Thiết lập và giám sát tình trạng hệ thống bằng các công cụ logging và alerting hiện đại.\n- Làm việc trong môi trường Agile/Scrum với các công cụ quản lý dự án như JIRA.\n- Phối hợp chặt chẽ với các team khác (BA, QA, DevOps, khách hàng...) để đảm bảo chất lượng và tiến độ sản phẩm.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học, cao đẳng chuyên nghành Công nghệ thông tin, hoặc các chuyên ngành liên quan\n- Có từ 3–6 năm kinh nghiệm phát triển phần mềm, trong đó ít nhất 2 năm kinh nghiệm với Java hoặc Python.\n- Thành thạo một trong các kết hợp công nghệ sau:\n+ Java (Spring Boot, v.v) + Frontend (ReactJS / Angular / Vue)\n+ Java + Python (Flask / FastAPI / Django)\n+ Python + Frontend (ReactJS / Angular / Vue)\n- Hiểu rõ về RESTful API, kiến trúc microservices, authentication/authorization.\n- Có kinh nghiệm làm việc với cơ sở dữ liệu quan hệ (MySQL, PostgreSQL) và/hoặc NoSQL (MongoDB, Redis).\n- Có kỹ năng viết unit test, sử dụng Git, CI/CD.\n- Kỹ năng giao tiếp và làm việc nhóm tốt.\n\nƯu tiên:\n- Có kinh nghiệm làm việc trong các dự án outsource hoặc khách hàng Hàn Quốc.\n- Có kinh nghiệm với DevOps (Docker, Kubernetes) là một lợi thế.\n- Kỹ năng làm việc nhóm tốt, chủ động và tinh thần trách nhiệm cao.\n- Ưu tiên ứng viên có khả năng giao tiếp tiếng Anh cơ bản trở lên.\n\nQuyền lợi\n- Mức lương: Thỏa thuận theo năng lực khi phỏng vấn.\n- Chế độ phúc lợi:\n+ Lương tháng 13+ và xét tăng lương 2 lần/năm.\n+ Thưởng theo dự án, thưởng lễ/tết, thưởng giới thiệu nhân sự, thưởng hiệu quả công việc...\n+ Phụ cấp thâm niên từ 2 năm làm việc.\n+ Tham gia các hoạt động đào tạo nội bộ và bên ngoài, phát triển lộ trình nghề nghiệp rõ ràng.\n+ Nghỉ thứ 7, Chủ nhật và 12 ngày phép/năm.\n+ Tham gia các câu lạc bộ thể thao – văn hóa – nghệ thuật do công ty tài trợ (bóng đá, cầu lông, bơi lội, âm nhạc, game, tiếng Anh...).\n+ Chăm sóc sức khỏe: Khám sức khỏe định kỳ, bảo hiểm sức khỏe chất lượng cao Rikkei Care.\n+ Văn hoá thoải mái: Âm nhạc hàng ngày, trái cây tươi, team building thường xuyên, du lịch trong và ngoài nước.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy\n\nThời gian làm việc\nĐăng ký linh hoạt 8:00 - 9:00 đến 17:00 - 18:00 từ Thứ 2 - Thứ 6\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2675, 1438, 2, 'Senior PHP Fullstack (Mạnh Laravel, DevOps, Aws, Trên 5 Năm Kinh Nghiệm)', 'Mô tả công việc:\n- Tham gia thiết kế, phát triển và hoàn thiện trang web, phần mềm của Cty với đối tác;\n- Tham mưu, tư vấn, làm cầu nối để phát triển, hoàn thiện app Androi và IOS của Cty với đối tác;\n- Tham gia phát triển phần định vị lên IOS, hiện thời chỉ dung được với Androi hoặc tham mưu, tư vấn để làm việc với đối tác;\n- Tham mưu, tư vấn để phát triển phần mềm mua hàng, ghi âm điện thoại hiện cty đang sử dụng;\n- Tham mưu, tư vấn trong việc số hóa các công việc mà TCT đang thực hiện;\n- Làm các công việc theo yêu cầu của Ban Giám đốc;\n- Làm việc và hỗ trợ trực tiếp với các Team sản phẩm, Mobile Developer, CSKH, Quản lý kho sản xuất...\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành công nghệ thông tin, khoa học máy tính, kỹ thuật máy tính hoặc một lĩnh vực tương tự\n- Có ít nhất 7 năm kinh nghiệm làm các dự án PHP, sử dụng thành thạo một trong các framework PHP (Laravel, WordPress, CakePHP, Zend, CodeIgniter)\n- Sử dụng thành thạo ít nhất từ Laravel 10\n- Có ít nhất 5 năm kinh nghiệm về DevOps và AWS\n- Hiểu biết sâu về ngôn ngữ PHP hoặc JS, OOP.\n- Đã từng làm việc/hiểu biết về API RestFul.\n- Có kinh nghiệm làm việc với một trong các hệ quản trị CSDL như MySQL, Maria DB, MongoDB.\n- Cẩn thận, kiên nhẫn, đam mê lập trình và sẵn sàng học hỏi các công nghệ mới.\n- Chịu được áp lực công việc.\n- Có kỹ năng phân tích và giải quyết vấn đề.\n- Ưu tiên CV ứng tuyển bằng tiếng Anh.\n\nQuyền lợi:\n- Thu nhập: 30 – 35 triệu/ tháng (theo năng lực từng ứng viên) + 700k phụ cấp ăn trưa/ tháng\n- Phúc lợi: BHXH, Thưởng lễ tết/ dự án, Sinh nhật, Du lịch hàng năm.\n- Làm việc trong môi trường giáo dục - công nghệ năng động.\n- Cơ hội phát triển kỹ năng sư phạm, quản lý nhóm.\n\nĐịa điểm làm việc:\n- Hà Nội: 357 Nguyễn Khang, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2676, 1439, 2, 'Kỹ Thuật Viên Gia Công Máy CNC (Máy Phay/Máy Tiện)', 'Mô tả công việc:\n- Đọc và hiểu bản vẽ gia công chi tiết.\n- Sử dụng các dụng cụ đo kiểm, dụng cụ gá đặt ....\n- Lập trình chương trình trên máy gia công CNC (máy tiện, máy phay, máy cắt,...)\n- Vận hành máy Tiện CNC (Okuma, Miyano, Tsugami, Moriseikii, Mazaktroll...) hoặc máy Phay CNC (Okuma, Brother, Victor-taichung...)\n- Thay đổi các mã hàng, thay đổi căn chỉnh dụng cụ cắt gọt....\n- Kiểm soát chất lượng sản phẩm, xử lí sự cố lỗi phát sinh trong các công đoạn gia công\n- Các công việc khác liên quan đến kỹ thuật gia công CNC\n- Tham gia các nhóm cải tiến 6S, TPM...\n\nYêu cầu ứng viên:\n- Tốt nghiệp CĐ hoặc ĐH chuyên ngành cơ khí chế tạo máy\n- Sử dụng phần mềm gia công & thiết kế 2D, 3D\n- Ưu tiên kinh nghiệm, về thiết kế và lập trình gia công máy phay, máy tiện CNC, có thể vận hành máy gia công phay, tiện CNC (OKUMA, MAZAK, TROLL, BROTHER, TSUGAMI...)\n- Đáp ứng yêu cầu làm ca trong sản xuất (3 ca)\n- Thật thà, cẩn thận, có tinh thần trách nhiệm cao trong công việc\n\nQuyền lợi:\n- Tham gia BHXH, BHYT theo đúng quy định.\n- Được hưởng chế độ bảo hiểm tai nạn 24h ngay khi được ký kết HĐLĐ chính thức.\n- Thưởng các dịp lễ tết, thưởng lương tháng 13, thưởng hiệu suất làm việc (hệ số lên tới 4,5 tháng lương cơ bản)\n- Ăn trưa tại nhà máy.\n- Môi trường làm việc thân thiện, năng động.\n\nĐịa điểm làm việc:\n- Bắc Ninh: Số 14, đường 8, khu công nghiệp, đô thị và dịch vụ VSIP Bắc Ninh, Phường Phù Chẩn, Từ Sơn\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:15 đến 17:00)\n- Làm 3 ca, Và 2 thứ 7 luân phiên.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2677, 1440, 2, 'Kỹ Sư Thiết Kế Máy', '- Nghiên cứu, thiết kế giải pháp máy tự động, dây chuyền sản xuất tự động kết hợp các máy chấn, đột, dập....\n- Hỗ trợ kinh doanh giải quyết các yêu cầu của Khách hàng về mặt kỹ thuật thiết bị và giải pháp.\n- Thiết kế 3D, bóc tách bản vẽ 2D, lập danh mục vật tư tiêu chuẩn chế tạo các máy tự động công nghiệp.\n- Tính toán, phân tích, mô phỏng tính khả thi của ý tưởng, thuyết trình ý tưởng của dự án.\n- Đặt hàng, hỗ trợ lắp ráp, tham gia nghiệm thu máy, hướng dẫn đào tạo vận hành, hoàn thiện hồ sơ thiết kế.\n- Quản lý dự án và triển khai dự án.\n- Thực hiện các công việc khác theo sự phân công của trưởng phòng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2678, 1441, 2, 'Lập Trình Viên Mobile', 'Mô tả công việc\n- Xây dựng các giải pháp ứng dụng mobile với nền tảng Flutter, đảm bảo hiệu suất cao và trải nghiệm người dùng tối ưu\n- Nghiên cứu các dự án theo định hướng phát triển của công ty.\n- Đảm bảo chất lượng mã nguồn, thực hiện code review và hướng dẫn đội ngũ\n- Theo dõi và báo cáo tiến độ của dự án đối với các bên liên quan, đưa ra biện pháp khi có rủi ro hoặc thay đổi không mong muốn.\n- Theo dõi xu hướng công nghệ mới và đề xuất cách tích hợp chúng vào dự án.\n- Lập kế hoạch phát triển sản phẩm và báo cáo tiến độ cho ban lãnh đạo\n- Thực hiện các công việc khác theo chỉ đạo của Ban Giám đốc.\n\nYêu cầu ứng viên\n- Trình độ học vấn: Đại học trở lên.\n- Trình độ chuyên môn: CNTT, Lập trình hoặc ngành nghề tương đương.\n- Chuyên sâu về công nghệ Flutter và Dart\n- Thành thạo các ngôn ngữ lập trình: Dart, Java/Kotlin (Android), Swift (iOS)\n- Kinh nghiệm: Có ít nhất 03 năm kinh nghiệm tại vị trí tương đương. Kinh nghiệm làm việc với các nền tảng phát triển ứng dụng di động.\n- Hiểu biết sâu về kiến trúc ứng dụng, design pattern\n- Kỹ năng giao tiếp tốt, nhạy bén, phân tích, đánh giá, có kỹ năng thuyết phục và kỹ năng đàm phán, giải quyết xung đột tốt.\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực\n- Lương tháng 13 + Thưởng KPI\n- Chính sách hiếu hỉ\n- Kiểm tra sức khỏe thường niên\n- Team building / du lịch hàng năm\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Số 2A Đường số 5, An Phú, Thủ Đức\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 16:45)\n- Thứ 7 (từ 09:00 đến 12:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2679, 1335, 2, 'Lập Trình Viên Data Engineer - Thu Nhập Hấp Dẫn Upto 60tr', '- Cung cấp nhân sự Xây dựng, thiết kế các luồng dữ liệu từ khâu tổng hợp số liệu từ Corebanking T24, ETL về Datawarehouse, đến việc chuyển giao cho các vị trí phân tích dữ liệu, khoa học dữ liệu\n- Nhân sự Xây dựng, thiết kế các luồng dữ liệu từ khâu tổng hợp số liệu từ Corebanking T24, ETL về Datawarehouse, đến việc chuyển giao cho các vị trí phân tích dữ liệu, khoa học dữ liệu\n- Nhân sự Phát triển, sửa đổi các báo cáo quản trị, báo cáo tuân thủ\nYêu cầu ứng viên:\n- Thành thạo ngôn ngữ SQL \n- Thành thạo sử dụng các công cụ : Confluent, MinIO, Kafka, Iceberg, Dremio, GoldenGate\n- Hiểu biết sâu về kiến trúc dữ liệu corebanking T24\n- Có kiến thức về cơ sở dữ liệu: Oracle, SQL.\n- Có kiến thức về PL/SQL. Oracle Function, Procedure, Package.\n- Có kiến thức về SAP Business Object là lợi thế\nQuyền lợi:\n- Chế độ thưởng theo quý, năm; tiền quà các ngày Lễ, Tết, ngày thành lập Tập đoàn; hỗ trợ chi phí nghỉ dưỡng hằng năm...\n- Hưởng Bảo hiểm Xã hội, Bảo hiểm Y tế theo quy định của Luật Lao động và công ty\n- Làm việc trong môi trường chuyên nghiệp, sáng tạo, cạnh tranh, phát triển, năng động có nhiều cơ hội thăng tiến.\n- Cơ hội học tập, nghiên cứu, làm việc trong nước và các nước trên thế giới.\n- Cơ hội tiếp cận với nhiều công nghệ mới.\n- Cơ hội thăng tiến, phát triển bản thân\nĐịa điểm làm việc:\n- Hà Nội: Số 112,Đường Chùa võ,Khu đô thị Dương Nội, Hà Đông\n- Hà Nội: Hoàng Cầu, Đống Đa\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n- Thứ 7 (từ 08:00 đến 12:00)\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hà Đông, Đống Đa', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2680, 1254, 2, 'Java Developer', 'Mô tả công việc\n- Tham gia phát triển các hệ thống phần mềm, gồm: \n- Phân tích yêu cầu khách hàng và xây dựng tài liệu giải pháp.\n- Tham gia phát triển và sửa lỗi các tính năng.\n- Đóng góp vào các hoạt động chia sẻ tri thức và cải tiến liên tục.\n\nYêu cầu ứng viên\n- Có từ 3 năm kinh nghiệm trở lên lập trình với Java.\n- Hiểu biết và có kinh nghiệm làm việc với một trong số nền tảng Java Core, EE, Spring, Struts, Hibernate\n- Yêu cầu có kinh nghiệm về Microservices.\n- Ưu tiên có kinh nghiệm tham gia các dự án tích hợp AWS, Cloud.\n- Có kinh nghiệm làm việc với SQL, PLSQL, có kiến thức về một trong các hệ quản trị cơ sở dữ liệu Oracle/MySQL.\n- Tiếng anh giao tiếp tốt.\n- Kỹ năng giao tiếp, giải quyết vấn đề, kỹ năng làm việc nhóm tốt, luôn sẵn sàng hỗ trợ các thành viên khác trong dự án.\n- Chịu được áp lực cao trong công việc, có khả năng làm việc độc lập, chủ động giải quyết vấn đề để hoàn thành nhiệm vụ.\n- Cam kết, ham học hỏi.\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực.\n- Thưởng cuối năm (1-3 tháng lương).\n- Nghỉ phép hàng năm, ngày phép thâm niên, ngày phép tháng sinh nhật.\n- Đánh giá năng suất và xét tăng lương 1 lần/ năm.\n- Tài trợ 100% phí thi các chứng chỉ quốc tế; phụ cấp chứng chỉ chuyên môn.\n- Khám sức khoẻ định kỳ, BHXH, nghỉ lễ theo qui định.\n- Tham gia vào nhóm phát triển Scrum tự chủ, linh hoạt và năng suất cao theo mô hình Agile/Scrum.\n- Môi trường làm việc trẻ, năng động, vui vẻ, hạnh phúc với các hoạt động văn hóa sôi động như retreat, picnic, team building, happy event, BiPlus radio, ...\n- Được làm nhiều, được thử nhiều và được sai, học thực chiến trong công việc\n- Liên tục phát triển năng lực thông qua các hoạt động học tập (company learning hour, team learning hour, club), đào tạo, mentoring, coaching,... Được phản hồi thường xuyên liên tục và huấn luyện để phát triển năng lực và đạt hiệu suất công việc ngày càng cao (CFRs- Conversation - Feedback - Recognition tháng và 6 tháng).\n\nĐịa điểm làm việc\n- Hà Nội: Số 85 - Trần Thái Tông, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2681, 1442, 2, 'Lập Trình Viên VueJS', '• Tham gia phát triển phần mềm cho các Tập đoàn khách sạn, resort hàng đầu tại Nhật Bản.\n• Teamwork, họp bàn, phát triển sản phẩm cùng với đội ngũ phía Nhật Bản.\n• Maintain code hiện tại và phát triển các chức năng mới.\n• Báo cáo công việc với cấp trên.\n• Từ một năm kinh nghiệm lập trình VueJs/Angular\n• Thuần thục CSS/SCSS, HTML, Javascript, TypeScript\n• Có kinh nghiệm về UX, UI, State Management, Functional Programming là một lợi thế.\n• Có kinh nghiệm làm việc với Web Application, API, DataBase.\n• Hiểu rõ authentication, RESTful API, Git, Virtual Machine và quy trình phát triển phần mềm\n• Có kiến thức cơ bản, kinh nghiệm về các dịch vụ AWS, Microservices, Docker, Kubernetes và cơ sở hạ tầng đám mây (Cloud Infrastructure)\n• Thời gian làm việc: Từ thứ 2 đến thứ 6, nghỉ Thứ 7 & Chủ Nhật. Đặc biệt bạn có thể tự chủ động giờ bắt đầu làm việc (đến trước 9h sáng), đến sớm về sớm. Miễn đảm bảo đủ 8 tiếng/ngày và tiến độ dự án.\n• Kết hợp linh hoạt giữa làm tại văn phòng và remote\n• Mức lương cạnh tranh (tùy theo kỹ năng và kinh nghiệm)\n• Review tăng lương hàng năm\n• Thưởng Tết, quà sinh nhật, Trung thu, 30/4, 2/9, 8/3, 20/10...\n• Trợ cấp ăn trưa, cung cấp cung cấp trà, cà phê, trợ cấp đi lại, trợ cấp ngoại ngữ v.v..\n• Thanh toán OT theo quy định của luật lao động\n• Có cơ hội đi onsite tại Tokyo hoặc Okinawa ngắn và dài hạn\n• Bảo hiểm full lương\n• Ngày phép: 12 ngày/năm và tăng dần theo thời gian làm việc\n• Du lịch công ty hàng năm\n• Khám sức khỏe định kỳ 01 lần/năm tại BV Quốc tế\n• Hoạt động giải trí và Team Building phong phú (Câu lạc bộ bóng đá, chạy bộ, đạp xe, PES...)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2682, 1400, 2, 'C# .NET Developer', 'Mô tả công việc\n・Participate in building the company\'s own product and outsource projects\n・Cooperate with other teams on all phases of project development\n・Contribute to system architecture and design decisions\n・Deliver good quality code\n・Be able to self-study on new technologies\n・Be dynamic and proactive\n\nYêu cầu ứng viên\n1. Basic Skills:\n・ CV with person photo\n・ Someone who takes initiative and can work proactively.\n・Has a positive attitude and forward-thinking mindset.\n・ Enjoys creating new things with a pioneering mindset.\n・Willingness to learn new technologies.\n・Strong communication skills and the ability to collaborate effectively with a team.\n・Able to communicate in English.\n\n2. Technical Skills And Experiences (Required)\n・Experience participating in and developing multiple projects as a programmer.\n・Proficient in at least one programming language.\n\n2.2 Technical Skill And Experience:\n・Has experience working with Japanese clients, markets, or companies.\n・Holds IT-related certifications.\n\nQuyền lợi\n・Salary review:  Once a year \n・Commuting allowance\n・Annual paid leave  (Granted collectively in April), public holidays are in accordance with labor laws.\n・Company trips\n・Regular health check-ups: Once a year \n・Participation in regular sports activities such (badminton,bowling ,vvv) : Once a month \n・Company parties and other internal events\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Bình Thạnh\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Bình Thạnh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2683, 1443, 2, 'Thực Tập Sinh Lập Trình Phần Mềm', '- Thực tập nghiên cứu, phát triển các hệ thống phần mềm ứng dụng công nghệ cao, kỹ thuật hiện đại.\n- Tham gia quá trình phân tích, thiết kế cho một sản phẩm cụ thể.\n- Làm việc theo sự phân công của người quản lý, phối hợp giữa các nhóm để phát triển sản phẩm hoàn chỉnh.\n\nYêu cầu ứng viên\n- Sinh viên năm 3 trở lên chuyên ngành: CNTT, Điện tử viễn thông, Khoa học máy tính, Toán tin ứng dụng và các chuyên ngành kỹ thuật khác liên quan.\n- Có thành tích học tập đạt loại Khá trở lên tại thời điểm xét duyệt\n- Có kiến thức cơ bản về lập trình front-end: HTML5, CSS3, Javascript\n- Ưu tiên các ứng viên đã biết về ReactJS, VueJS\n- Có kiến thức cơ bản về lập trình back-end: .NET Core, Python, NodeJS, Java\n- Ưu tiên các ứng viên đã biết về .NET Core WebAPI, .Net Core EF\n- Có khả năng đọc hiểu tài liệu tiếng Anh tốt.  \n\nQuyền lợi\n- Được đào tạo về lập trình chuyên nghiệp bởi những chuyên gia công nghệ hàng đầu trong lĩnh vực CNTT\n- Được học nghiệp vụ các sản phẩm CNTT ứng dụng\n- Được hưởng trợ cấp thực tập sau quá trình đào tạo nếu có khả năng tham gia các dự án thực tế của công ty\n- Được thực tập tại môi trường chuyên nghiệp, năng động, văn hóa hiện đại\n- Được tham gia học tập, nghiên cứu và phát triển các ứng dụng trên nền tảng công nghệ chuyên ngành GIS, AI/ML, OCR, OMR...\n- Được học hỏi về phát triển ứng dụng mobile hybrid app trên Flutter\n- Ưu tiên xem xét cho những cơ hội Tuyển dụng chính thức sau khi ra trường\n\nĐịa điểm làm việc\n- Hà Nội: Liền kề 6B-27 C17 Khu Đô thị Mỗ Lao, Phường Mộ Lao Thành phố Hà Nội, Việt Nam, Hà Đông\n\nThời gian làm việc\nT2-T6: 9h-12h; 13h-18h\nT7: 9h-12h\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2684, 1444, 2, 'User Acquisition Marketing Game', '• Quảng bá game mobile ra thị trường toàn cầu (ưu tiên Việt Nam, Trung Quốc).\n• Nghiên cứu thị trường, phân tích đối thủ và hành vi người chơi.\n• Phối hợp với team sản phẩm lên chiến lược marketing.\n• Chuẩn bị nội dung, thiết lập quảng cáo Facebook, Google.\n• Thiết lập và tối ưu quảng cáo trên Facebook, Google, Tiktok.\n• Theo dõi và tối ưu quảng cáo hàng ngày.\n• Đóng góp ý tưởng và cập nhật nội dung quảng cáo.\n• Phân tích và báo cáo dữ liệu theo tuần/ tháng.\n• Thực hiện hoạt động mở rộng thị trường.\n• Thực hiện các công việc khác theo yêu cầu quản lý.\n\nYêu cầu ứng viên:\n• Có kinh nghiệm trong lĩnh vực Marketing Game từ 1 năm trở lên Có kiến thức chung về Marketing và Business, dự án Game.\n• Chuyên môn vững về Advertising Facebook, Google, Tiktok, Apple Search và tư duy về Marketing User Acquistion.\n• Hiểu các chỉ số về CPL, CPI, CPM, CPC, CPA, ROAS.\n• Có đam mê về game.\n• Năng động, nhiệt tình, nhẫn nại, chấp nhận thử thách.\n• Có khả năng xử lý vấn đề khi gặp sự cố hoặc đối thủ cạnh tranh cùng thời điểm.\n• Khả năng đọc/ dịch tiếng Anh.\n\nQuyền lợi:\n• Mức lương: 15 – 25 triệu VNĐ\n• Thử việc: 2 tháng, trong thời gian thử việc mỗi tháng được nghỉ phép 1 ngày.\n• Thưởng hiệu suất, thưởng cuối năm, quà tặng dịp lễ – Tết, quà sinh nhật...\n• Có 12 ngày nghỉ phép có lương mỗi năm.\n• Có thể đăng ký tham gia các khóa đào tạo nâng cao kỹ năng và năng lực.\n• Công ty hỗ trợ bữa trưa.\n• Tham gia đầy đủ bảo hiểm y tế, bảo hiểm xã hội theo quy định.\n• Miễn phí đồ ăn nhẹ, nước uống; sử dụng không gian nghỉ ngơi miễn phí.\n• Thường xuyên tổ chức các hoạt động team building.\n• Cơ hội thăng tiến 2 lần mỗi năm.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: LK2-L10, Khu Biệt Thự Green Star, Số 600 Nguyễn Lương Bằng, Phường Phú Mỹ, Quận 7.\n\nThời gian làm việc:\nThời gian làm việc: Thứ 2 đến Thứ 6, nghỉ Thứ Bảy và Chủ Nhật (không làm thêm giờ).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2685, 1445, 2, 'Senior Fullstack Developer', 'Mô tả công việc\n- Thiết kế, phát triển và tối ưu Backend (Java Spring Boot, MongoDB) và Frontend (Angular) cho các hệ thống phần mềm doanh nghiệp.\n- Xây dựng RESTful APIs, WebSocket, đảm bảo hiệu năng, bảo mật và khả năng mở rộng.\n- Thiết kế kiến trúc hệ thống Microservices, tích hợp với các dịch vụ bên ngoài và hệ thống nội bộ.\n- Làm việc với MongoDB và MariaDB, tối ưu truy vấn dữ liệu và quản lý cơ sở dữ liệu NoSQL và SQL.\n- Thực hiện code review, Unit Test, hỗ trợ SIT/UAT, fix bug và tối ưu hiệu năng hệ thống.\n- Phối hợp với BA, UI/UX, DevOps, QA để triển khai dự án đúng tiến độ và chất lượng.\n- Nghiên cứu và áp dụng các công nghệ mới vào hệ thống.\n- Hướng dẫn, đào tạo đội ngũ Developer trong nhóm.\n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm lập trình với Java Spring Boot.\n- Thành thạo Angular, có kinh nghiệm phát triển giao diện frontend theo kiến trúc component.\n- Thành thạo Spring Boot, Spring MVC, Spring Security, Hibernate, Maven.\n- Có kinh nghiệm làm việc với MongoDB và MariaDB.\n- Hiểu sâu về Microservices Architecture, Event-Driven Architecture (EDA), SOA.\n- Có kinh nghiệm triển khai trên Cloud, sử dụng Docker, Kubernetes.\n- Thành thạo Git, CI/CD, có kinh nghiệm với Agile/Scrum.\n- Có kinh nghiệm với OAuth 2.0, OpenID Connect, JWT.\n- Có kinh nghiệm tối ưu hệ thống và xử lý scalability.\n- Kinh nghiệm làm việc với Kafka, RabbitMQ hoặc các hệ thống Message Queue khác.\n\nQuyền lợi\n- Thu nhập 15-30 triệu (thỏa thuận theo năng lực và kinh nghiệm làm việc thực tế)\n- Lương tháng 13, thưởng theo kết quả kinh doanh hàng năm.\n- Hưởng các chính sách, chế độ bảo hiểm theo đúng quy định của Luật lao động Việt Nam.\n- Tham gia các hoạt động gắn kết nội bộ hằng quý, hằng năm, hay các dịp lễ tết, du lịch, sinh nhật, team building,...\n- Được định hướng nghề nghiệp và có lộ trình thăng tiến.\n- Được tham gia các khóa đào tạo theo chương trình huấn luyện của Công ty.\n- Được đào tạo bài bản về sản phẩm và kiến thức kinh doanh, kỹ năng chuyên môn.\n- Môi trường làm việc trẻ, năng động, chuyên nghiệp, khuyến khích sự phát triển của từng nhân viên.\n\nĐịa điểm làm việc\n- Hà Nội: BT01-7 KĐT An Hưng, Dương Nội, Hà Đông\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Đông, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2686, 1446, 2, 'Lập Trình Viên C#, .NET', 'Mô tả công việc\n- Lập trình, tùy biến phần mềm\n- Tham gia phân tích và phát triển hệ thống ERP\n- Tư duy logic tốt, biết định hướng khách hàng, định hướng kết quả, cẩn thận và tỉ mỉ trong công việc\n\nYêu cầu ứng viên\n- Kỹ năng tư duy logic và thuật toán tốt.\n- Yêu thích lập trình, có khả tự giải quyết vấn đề và tìm hiểu kiến thức.\n- Ưu tiên hiểu biết khái niệm căn bản về lập trình\n- Chịu được áp lực trong công việc và tinh thần trách nhiệm cao.\n\nQuyền lợi\n- Được công ty đào tạo miễn phí trong khoảng thời gian 3 đến 6 tháng.\n- Lương thỏa thuận.\n- Thưởng tháng lương 13, các dịp lễ.\n- Hộ trợ tiền ăn trưa: 55,000 VND/ngày.\n- Trợ cấp sinh nhật: 1.000.0000 vnđ\n- Hỗ trợ tiền khám chữa bệnh\n- Hỗ trợ nuôi con nhỏ: 50USD/ tháng.\n- Trợ cấp đi dự án 150$ / tháng\n- Chế độ BHXH theo quy định của pháp luật.\n\nĐịa điểm làm việc\n- Đà Nẵng\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2687, 1242, 2, 'Front End Developer', 'Mô tả công việc:\n- Design, develop, and maintain user interfaces for web applications.\n- Collaborate with UX/UI Designers to ensure intuitive and user-friendly interfaces.\n- Integrate APIs and back-end services to deliver full features.\n- Optimize interface performance (loading speed, cross-device compatibility).\n- Write clean, reusable, and maintainable code.\n- Analyze and troubleshoot front-end issues.\n- Stay updated and apply the latest technologies and frameworks.\n\nYêu cầu ứng viên:\n[Required]\n- Have at least 3 years of experience (Prioritize high experience)\n- Experienced web / mobile application development\n- Can develop HTML, CSS, Javascript, jQuery\n- Can develop based on React.js or Vue.js, Vuex\n- Experienced with collaboration tools like Git, Jira and Confluence\n- Understand and use CI/CD\n- English speaking on average (or TOEIC on 550)\n\n[Preferred]\n- Understand Back-end\n- Use Typescript\n- Experienced with Node.js\n- Experienced with javascript charts (Echarts, Chart.js, d3js, etc.)\n- Experience using Tailwind, MUI\n- OAuth development experience\n- Korean communication\n- Team management experience.\n\nQuyền lợi:\n- Attractive salary and bonus will be discussed after going through CV & Interview.\n- Review capacity annually and adjust salary increases according to work performance.\n- Korean language certificate bonus (TOPIK).\n- Health care: Premium health insurance, Annual health check-up.\n- Young working environment, flexible working hours.\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.).\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 15, Keangnam Landmark 72, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2688, 1359, 2, 'Fullstack Developer', 'Mô tả công việc\n- Thiết kế, phát triển và duy trì hệ thống fullstack với:\n- Frontend: Sử dụng Angular (v12–v16) là chính, có thể làm việc với ReactJS hoặc React Native cho các sản phẩm web/mobile.\n- Backend: Làm việc với Java Spring Boot, kiến trúc Microservices, xử lý nghiệp vụ phức tạp, tích hợp hệ thống tài chính.\n- Làm việc chặt chẽ với các bộ phận liên quan như BA, PO, QA để đảm bảo sản phẩm đúng yêu cầu và chất lượng cao.\n- Tham gia thiết kế kiến trúc hệ thống, đánh giá giải pháp kỹ thuật, tối ưu hiệu năng và độ ổn định.\n- Quản lý nhóm phát triển: phân công công việc, theo dõi tiến độ, review code, hỗ trợ giải quyết vấn đề kỹ thuật.\n\nYêu cầu ứng viên\n- Frontend\n- Thành thạo Angular từ version 12 và 16, nắm vững kiến thức Front-end, có thể viết mới dựa theo design figma và tích hợp API từ backend, tối ưu hiệu năng web/app\n- Có kinh nghiệm với ReactJS hoặc React Native là một lợi thế lớn.\n- Backend\n- Thành thạo Java Spring Boot, có kinh nghiệm xây dựng microservices, làm việc với các hệ thống phân tán, RESTful APIs, message queues (Kafka, RabbitMQ).\n- Hiểu biết về database (Oracle và PostgreSQL) và caching (Redis).\n- Team Leadership\n- Có kinh nghiệm quản lý nhóm từ 3–10 người, có khả năng mentoring, định hướng kỹ thuật, xây dựng văn hóa nhóm tích cực.\n- Kỹ năng giao tiếp tốt, phối hợp hiệu quả với các phòng ban và quản lý cấp cao.\n- Domain\n- Ưu tiên lớn cho ứng viên đã từng tham gia các dự án trong lĩnh vực tài chính, fintech, ngân hàng, ví điện tử, hoặc chứng khoán.\n- Ngoại ngữ:\n- Có thể trình bày, giao tiếp, báo cáo bằng Tiếng Anh\n\nQuyền lợi\n- Mức lương và thưởng hấp dẫn\n- 12 ngày nghỉ phép năm\n- Được tham gia đầy đủ bảo hiểm xã hội và bảo hiểm y tế theo quy định của nhà nước\n- Các khoản phụ cấp hấp dẫn (thưởng onsite, gửi xe, sinh nhật, happy hours, v.v.)\n- Xét duyệt tăng lương hàng năm dựa trên hiệu suất và đóng góp của nhân viên\n- Môi trường làm việc thực sự cởi mở. Mọi người đều được tôn trọng và bạn có quyền tự do theo đuổi cũng như đạt được mục tiêu của mình\n- Các quyền lợi khác theo quy định của Bộ luật Lao động Việt Nam\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 91 Pateur, đường Bến Nghé, Quận 1\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2689, 1447, 2, 'Embedded Software Engineer', 'ABOUT THE JOB\n- Design and implement embedded software for appliances\n- Analyze and review software requirement specifications\n- Develop unit and integration test cases based on requirements\n- Execute tests, retests, and regression tests on embedded systems\n- Debug software issues and perform root cause analysis\n- Conduct code reviews and maintain high coding standards\n- Document and archive software and test artifacts\n- Create and manage bug reports and monitor defect resolutions\n- Identify and apply suitable tools for testing automation and CI/CD\n- Collaborate with cross-functional teams and stakeholders\n\nABOUT YOU\n- Academic background: Degree in Software Engineering, Computer Science, or Electrical Engineering\n- For Embedded Tester: 3+ years of experience with software testing for embedded systems and testing tools (Python, Pytest, Git, Jira, Confluence, Polarion, Teamcenter, Artifactory, PyCharm, Enterprise Architect)\n- For Embedded Developer: 3+ years of experience with embedded software development and C++\n- Strong knowledge of embedded Linux and system architecture\n- Familiarity with UML for software design\n- Hands-on experience with CI/CD tools: Jenkins, GitHub\n- Good communication skills in English\n- You have an ability to synthesize complex information and work collaboratively in an agile environment\n\nWHY AMARIS?\n- Competitive salary and 13th-month salary\n- 14+ annual leaves per year\n- Premium healthcare insurance, starting from your probation period\n- Project reviews and yearly performance appraisals\n- Annual company trips\n- Teambuilding activities: Team lunch/dinner, events, and celebrations, sports clubs (football, yoga, badminton, etc.)\n- International team with flexible working time\n- Tailor-made career path\n- Technical workshops and training courses\n- Mobility: Opportunities to be on-site abroad in our offices in over 60+ countries\n\nEqual Opportunity\n\nAmaris Consulting is proud to be an equal opportunity workplace. We are committed to promoting diversity within the workforce and creating an inclusive working environment. For this purpose, we welcome applications from all qualified candidates regardless of gender, sexual orientation, race, ethnicity, beliefs, age, marital status, disability, or other characteristics.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2690, 1448, 2, 'Senior Mobile Developer', 'Mô tả công việc:\n- Phát triển ứng dụng di động bằng React Native hoặc ứng dụng web trên ReactJS/NextJS dựa trên các yêu cầu kỹ thuật và thiết kế đã được phê duyệt.\n- Phối hợp với các nhóm khác như UI/UX, QC, và BE để đảm bảo ứng dụng được phát triển một cách toàn diện.\n- Tham gia phân tích, thiết kế luồng phát triển của ứng dụng di động hoặc ứng dụng web dựa vào yêu cầu của sản phẩm.\n- Đánh giá, phân tích, nâng cấp và tối ưu mã nguồn trong quá trình phát triển.\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai.\n- Tham gia đưa ra những ý tưởng, giải pháp mới cải thiện công việc.\n- Support team xử lý những vấn đề khó phát sinh trong quá trình phát triển giải pháp.\n- Thực hiện các công việc do trưởng bộ phận, quản trị dự án giao trong phạm vi công việc.\n\nYêu cầu ứng viên:\n- Có ít nhất 4 năm kinh nghiệm hoặc tham gia các dự án Moblie, đặc biệt là React Native.\n- Kinh nghiệm phát triển super app là một lợi thế.\n- Có kiến ​​thức về HTML và CSS, Javascript, Bootstrap, Redux, Material UI.\n- Kinh nghiệm về React Native, ReactJs, NextJS, Kotlin hoặc Swift.\n- Kinh nghiệm xử lý Restful API, sử dụng các thư viện của bên thứ ba.\n- Kiến thức về OOP, thiết kế hệ thống, cấu trúc thuật toán và tối ưu hóa hiệu suất ứng dụng React Native.\n- Hiểu biết về cơ chế xác thực và ủy quyền, chẳng hạn như JWT, OAuth hoặc xác thực dựa trên phiên.\n- Hiểu biết về các nguyên tắc phát triển không đồng bộ và bảo mật dữ liệu.\n- Kiến thức về Firebase hoặc Onesignal.\n- Khả năng đóng góp và xây dựng các cải tiến UI/UX.\n- Kinh nghiệm trong ngành thanh toán là một lợi thế.\n- Kinh nghiệm làm việc theo phương pháp Agile/Scrum và sử dụng các công cụ quản lý dự án như JIRA hoặc Trello.\n- Hiểu biết về các nguyên tắc bảo mật ứng dụng và kinh nghiệm triển khai các giải pháp bảo mật.\n- Khả năng giao tiếp rõ ràng và hiệu quả, cả bằng văn bản lẫn nói, với các bên liên quan kỹ thuật và phi kỹ thuật.\n- Có tinh thần học hỏi không ngừng và khả năng thích nghi với các công nghệ mới nhanh chóng.\n- Chủ động, sáng tạo, nhiệt tình, trách nhiệm trong công việc.\n- Có khả năng phân tích, tư duy logic và giải quyết vấn đề.\n- Sẵn sàng làm thêm giờ hoặc onsite khi có yêu cầu.\n\nQuyền lợi:\n- Mức lương cạnh tranh theo đúng năng lực: từ 30,000,000 đến 40,000,000 VND/tháng.\n- Môi trường làm việc thân thiện, năng động, có cơ hội phát triển bản thân và thăng tiến lên vị trí team leader, quản lý.\n- Cơ hội tiếp cận với các công nghệ mới, làm việc trong môi trường startup/công nghệ năng động.\n- Ghi nhận thành tích, tăng lương và thưởng kịp thời.\n- Chế độ bảo hiểm đầy đủ, nghỉ phép theo quy định.\n- Thưởng Lễ Tết, 30/4; 1/5; 2/9… (theo tình hình hoạt động thực tế của Công ty).\n- Sinh nhật, ốm đau, sinh con, ma chay, hiếu hỉ theo mức quy định của Công ty.\n- Teambuilding, nghỉ mát….. (theo tình hình hoạt động thực tế của Công ty).\n- Được tham gia các khóa đào tạo do công ty tổ chức: kĩ năng mềm, nâng cao trình độ chuyên môn….\n- ……….', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2691, 1449, 2, 'Lập Trình Viên Từ N3 (Visa Nhanh)', 'Mô tả công việc\nPhát triển ứng dụng kinh doanh cho các ngành khác nhau như tài chính, truyền thông, sản xuất, phân phối, chăm sóc y tế và vận tải\nPhát triển các phần mềm ứng dụng nội bộ\nLập trình trong các dự án gia công phần mềm cho khách hàng Nhật Bản sử dụng ngôn ngữ chính là Java hoặc C#...\nTham gia các giai đoạn phát triển phần mềm khác tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu công nghệ khi được phân công\n\nYêu cầu ứng viên\nTrình độ tiếng Nhật: N3, giao tiếp tốt, có thể làm việc trực tiếp với khách hàng\nCó trên một năm kinh nghiệm trong ngành lập trình\nThông thạo một số ngôn ngữ lập trình như C#, Java, Javascript, PLSQL\nCó thể ở Nhật trên ba năm, có khả năng chịu được áp lực\nTuyển thẳng sang Nhật làm sau khi làm thủ tục xin visa\n\nQuyền lợi\nThời gian làm việc: 08:45-17:30, nghỉ 60 phút(Làm bảy tiếng 45 phút)\nTăng ca trung bình 11 tiếng/tháng\nTổng ngày nghỉ 123 ngày/năm\nNghỉ thứ bảy, chủ nhật, các ngày nghỉ lễ của Nhật\nMức lương: 400-600 Vạn  yên/năm\nTrợ cấp chức vụ 14,000-70,000 yên\nTrợ cấp chủ hộ gia đình 8,000-100,000 yên\nTrợ cấp nếu có người phụ thuộc 20,000 yên\nTrợ cấp con nhỏ 1 con 10,000 yên; 2 con 15,000 yên\nTrợ cấp độc thân phải nuôi dưỡng ông bà, bố mẹ 7,000 yên\nHỗ trợ vé máy bay sang Nhật\nHỗ trợ làm thủ tục xin visa\nCấp cho nhân viên máy tính, Mirosoft365 để có thể làm ở nhà\nCác chế độ bảo hiểm theo quy định của luật lao động Nhật Bản\n\nĐịa điểm làm việc\n- Nước Ngoài\n- Hà Nội: Đống Đa\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nước Ngoài, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2692, 1319, 2, 'Kỹ Sư Lập Trình Nhúng', 'Mô tả công việc\n- Tham gia phát triển và tối ưu firmware cho các thiết bị nhúng thuộc lĩnh vực An ninh Quốc phòng (vệ tinh, truyền thông vô tuyến, radar…).\n- Tham gia nghiên cứu áp dụng/cập nhật công nghệ mới cho các sản phẩm.\n- Tham gia khảo sát, đánh giá các sản phẩm thương mại, và đề xuất phương án nội địa hóa/phát triển sản phẩm tương đương.\n- Thiết kế và triển khai các module phần mềm điều khiển thiết bị phần cứng (MCU, FPGA, RF, cảm biến, truyền thông...).\n- Tích hợp và kiểm thử hệ thống nhúng: truyền nhận dữ liệu, giao tiếp UART, SPI, I2C, CAN, RS485, Ethernet...\n- Đánh giá linh kiện và phối hợp cùng nhóm thiết kế phần cứng để tối ưu giải pháp sản xuất nội địa.\n\nYêu cầu ứng viên\n1.Trình độ & Kinh nghiệm\n- Tốt nghiệp đại học các ngành: Công nghệ thông tin, Khoa học máy tính, Điện – Điện tử, Tự động hóa, Viễn thông… hoặc chuyên ngành liên quan.\n- Có tối thiểu 02 năm kinh nghiệm lập trình hệ thống nhúng (firmware/hệ điều hành nhúng).\n\n2. Kỹ năng & chuyên môn\n- Thành thạo ít nhất một trong các ngôn ngữ lập trình: C/C++, Python, Shell Script.\n- Có kinh nghiệm làm việc với các nền tảng MCU (STM32, ESP32, NXP…), hoặc SoC, RTOS (FreeRTOS, Zephyr…).\n- Hiểu biết tốt về cấu trúc hệ thống nhúng, lập trình giao tiếp ngoại vi (SPI, I2C, UART…).\n- Ưu tiên ứng viên có kinh nghiệm làm việc với thiết bị trong các hệ thống: vệ tinh, truyền thông VHF/UHF, radar, tín hiệu số….\n\n3. Tư duy & năng lực khác\n- Tư duy logic, chủ động giải quyết vấn đề.\n- Có khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Sử dụng tốt tài liệu kỹ thuật tiếng Anh.\n\nQuyền lợi\n- Mức lương cạnh tranh, thưởng theo dự án và năng lực.\n- Công ty đóng 100% BHXH ngay khi ký HĐLĐ chính thức.\n- Cơ hội làm việc trong lĩnh vực công nghệ cao phục vụ Quốc phòng – An ninh.\n- Tham gia các khóa đào tạo chuyên môn sâu (nhúng, FPGA, truyền dẫn…).\n- Cơ hội phát triển thành trưởng nhóm kỹ thuật theo lộ trình.\n- Tham gia các khóa Đào tạo trong và ngoài nước nâng cao nghiệp vụ chuyên môn.\n- Thưởng tháng 13, 14 thưởng các ngày lễ, tết,…\n- Phụ cấp ăn trưa 40.000 VNĐ/ngày.\n- Khám sức khỏe định kỳ, teambuilding, du lịch, các sự kiện nội bộ.…\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Zodiac, ngõ 19 Duy Tân, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2693, 1274, 2, 'ReactJS Developer', 'Mô tả công việc:\n- Tham gia phát triển giao diện người dùng (UI) cho các sản phẩm web hiện đại sử dụng ReactJS, TypeScript, Next.js.\n- Xây dựng giao diện responsive, tối ưu hiệu suất và thân thiện với người dùng bằng Tailwind CSS và Ant Design (Antd).\n- Phối hợp chặt chẽ với team thiết kế, backend và QA để triển khai các tính năng mới.\n- Tối ưu trải nghiệm người dùng và hiệu suất ứng dụng web.\n- Đóng góp ý tưởng cải thiện sản phẩm, quy trình làm việc, chất lượng code.\n- Tham gia review code, chia sẻ kiến thức với team.\n\nYêu cầu ứng viên:\n- Thành thạo TypeScript, có khả năng áp dụng vào dự án thực tế.\n- Kinh nghiệm phát triển giao diện với React.js.\n- Sử dụng thành thạo Next.js (ưu tiên ứng viên đã làm việc với cả App Router và Pages Router).\n- Có gu thẩm mỹ tốt và khả năng xây dựng giao diện hiện đại, đẹp mắt với Tailwind CSS.\n- Thành thạo Ant Design: biết tùy chỉnh và sử dụng hiệu quả các component.\n- Biết sử dụng Git, nắm vững các thao tác cơ bản và làm việc nhóm trên Git.\n- Tư duy sản phẩm tốt, chủ động trong công việc.\n- Kỹ năng làm việc độc lập và phối hợp nhóm hiệu quả.\n\nQuyền lợi:\n- Môi trường làm việc trẻ, năng động, đồng nghiệp thân thiện.\n- Được tham gia các dự án thực tế với quy mô lớn, công nghệ mới.\n- Thời gian làm việc linh hoạt (có thể remote tùy chính sách).\n- Review lương định kỳ 2 lần/năm, thưởng hiệu suất.\n- Được cấp thiết bị làm việc (laptop, màn hình… nếu onsite).\n- Các chế độ BHXH, nghỉ phép, team building đầy đủ theo luật.\n\nĐịa điểm làm việc:\nHà Nội: Hoàng Quốc Việt, Cầu Giấy.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2694, 209, 2, 'Java Developer', 'We are looking for an enthusiastic and eager Java Developer to join our growing team. This is an excellent opportunity for individuals with a foundational understanding of software development principles who are keen to learn and build applications using the low-code platform. You will work alongside experienced developers, contributing to the development and maintenance of our applications while gaining valuable hands-on experience.\n\nYêu cầu ứng viên:\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field  \n- Basic understanding of software development concepts and methodologies.  \n- Possesses knowledge and experience in Java programming\n- Strong logical thinking and problem-solving skills.  \n- Good communication and teamwork skills.  \n- Strong analytical and problem-solving skills.  \n- Fluency in English \n\nQuyền lợi:\n- Attractive income package as negotiation\n- Global and inclusive workplace with monthly cross-cultural events\n- International exposure and career growth across global locations\n- Work-life balance benefits supporting employee well-being\n- Private health insurance with optional family coverage\n- Summer vacation allowance\n- Sponsored training courses for personal growth\n- Comprehensive relocation package\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lô E3 Đ. Võ Chí Công, Quận 9\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2695, 1450, 2, 'Blockchain Backend Developer', 'Mô tả công việc\n- Design and implement RESTful APIs\n- Build and deploy performant modern web applications in Golang, Rust, Nodejs, ...\n- Build a high-performance and optimized backend system to meet large volumes of traffic.\n- Architect efficient and scalable backend systems\n- Write unit, functional and end-to-end tests\n- Write high-quality code (Go, Rust, NodeJS) that communicates with upstream backend services via HTTP/GRPC APIs\n- Identify and resolve performance and scalability issues\n- Participate in code reviews\n- Participate in research on optimal solutions, and system security; contribute ideas on technology and products\n\nYêu cầu ứng viên\nMust have:\n- At least 1 year of server-side programming (Experience level)\n- Understand CS fundamentals (algorithms and data structures, operating systems, networks, databases, etc)\n- Familiar with common network protocols (TCP, UDP, HTTP) and network programming;\n- Good knowledge of both RDB and NoSQL.\n- Familiar with Linux development environments and multi-threaded programming;\n- Familiar with Version Control System (GIT)\n- Proficiency in at least one programming languages – Golang, Rust, Nodejs\n\nNice to have:\n- Having worked with Blockchain, Cryptocurrencies, and/or high-access responsive systems is a big plus\n- Building data lake and analytics skills (Metabase, Dune, BigQuery, Data Studio)\n- Knowledge of information safety and security is an advantage.\n- Strong problem-solving, interpersonal, and communication skills\n- Experience in Docker/Kubernetes and Cloud Infrastructure is a plus\n- Able to work with a team as well as independently.\n- Have spirit, responsibility, and initiative in work.\n\nQuyền lợi\nDevelopment opportunities:\n- Working in an environment with talented engineers who have experience in developing products in the field of Fintech, Blockchain, Cryptocurrencies.\n- Take a key role in building the project from the very beginning;\n- Technical and professional training throughout the working process.\n\nRemuneration:\n- Earn up to $2000, 13th-month bonus, performance bonus according to the company\'s business situation.\n- Flexible working hours: 9:00-18:30 Monday-Friday, 1h30-minute lunch break\n- Labor contract and all benefits prescribed by the state (pay social insurance, health insurance, unemployment insurance);\n- 16 days leave, 4 days sick leave with full salary;\n- PVI Healthcare Insurance;\n- Annual health check at a reputable hospital;\n- Equipment for work;\n- Daily lunch, happy hour every Thursday, and monthly team outing;\n- Chillax office with gym, swimming pool, free snacks & drink all day;\n- Travel - vacation at least once a year at domestic and international 5-star resorts.\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes West Point, Pham Hung Street, Me Tri Ward, Nam Tu Liem, Ha Noi, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2696, 1451, 2, 'Nhân Viên Phần Mềm', 'Mô tả công việc\n+ Triển khai, vận hành, xử lý lỗi, sự cố,... và các phần mềm ứng dụng khác trong công ty.\n+ Lập trình các phần mềm ứng dụng theo nhu cầu hoạt động sản xuất kinh doanh của Công ty.\n+ Hỗ trợ lắp đặt thiết bị, vận hành, hướng dẫn sử dụng các phần mềm ứng dụng trong công ty.\n\nYêu cầu ứng viên\n- Trình độ chuyên môn: Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin\n- Hiểu biết về: phần mềm quản lý doanh nghiệp ERP\n- Ngoại ngữ: ưu tiên ngoại ngữ lưu loát là lợi thế\n- Tin học: trình độ A hoặc các chứng chỉ tương đương trở lên\n- Kinh nghiệm: ít nhất 1 năm kinh nghiệm ở vị trí tương đương.\n- Tuổi: không quá 35 tuổi.\n- Sức khỏe: tốt, đáp ứng được yêu cầu sức khỏe đầu vào của công ty\n- Tính cách: sáng tạo, linh hoạt\n\nQuyền lợi\n- Mức lương: Lương cạnh tranh + thưởng theo kết quả kinh doanh, tùy thuộc vào năng lực của từng ứng viên\n- Hỗ trợ tiền nhà cho các ứng viên chấp nhận điều động đi công tác xa.\n- Được đào tạo trong thời gian thử việc và các đào tạo thực tế trong khi làm việc theo chương trình đào tạo hàng năm của công ty.\n- Được trang bị đồng phục và các công cụ, thiết bị hỗ trợ để phục vụ cho quá trình làm việc\n- Được đóng BHXH, BHYT, BHTN theo quy định của Nhà nước.\n- Mua bảo hiểm tai nạn 24 giờ ngay khi làm việc\n- Được hưởng các khoản phụ cấp theo quy định của Nhà nước và các phụ cấp khác theo quy định của công ty.\n- Thưởng tháng lương thứ 13 (theo thực tế tháng làm việc trong năm)\n- Được khen thưởng đột xuất cho các sáng kiến, cải tiến kỹ thuật mang lại hiệu quả cao cho hoạt động sản xuất kinh doanh.\n- Các chính sách thưởng khác theo quy định của công ty, thưởng các ngày lễ trong năm và theo thực tế tháng làm việc của thời gian xét thưởng.\n- Các phúc lợi liên quan: du lịch, quà sinh nhật ....\n\nĐịa điểm làm việc\n- Đồng Tháp: Số 346, đường Nguyễn Huệ, Phường Mỹ Phú, TP Cao Lãnh\n- Hồ Chí Minh: 37, Thành Thái, Quận 10\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Tháp, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2697, 1452, 2, 'Kỹ Sư Lập Trình Firmware', '- Lập trình Firmware cho các ứng dụng nhúng, IoT sử dụng STM32, Nordic chip, ESP32, Rasp Pi, Jetson và các OS development kit.\n- Xây dựng hệ thống quản lý các thiết bị, xây dựng API, IoT Cloud...\n- Kết hợp với bộ phận phát triển Hardware và Software để hoàn thành dự án.\n\nYêu cầu ứng viên:\n- Trình độ: tốt nghiệp Đại học chuyên ngành Điện - Điện tử.\n- Kinh nghiệm: 2 năm kinh nghiệm.\n- Có hiểu biết sâu về các ứng dụng IoT, hệ thống nhúng, làm việc nhiều về OS (Linux, Yocto).\n- Có kinh nghiệm thiết kế PCB, kinh nghiệm test mạch là một lợi thế.\n- Có kinh nghiệm lập trình Python, build custom OS cho các dev kit như Rasp Pi, Orange, Jetson...\n- Làm việc nhiều với các chuẩn giao tiếp không dây: Wifi, BLE, Lora/LoraWAN, Zigbee...\n- Khả năng làm việc độc lập, chịu khó tìm tòi, nghiên cứu.\n\nQuyền lợi:\n- Được làm việc trong môi trường trẻ trung và năng động\n- Đóng BHXH, BHYT theo quy định nhà nước.\n- Thời gian làm việc linh động.\n- Có thể làm việc online hoặc offline.\n- Được đào tạo và làm việc với nhiều loại dự án khác nhau để nâng cao năng lực bản thân, làm việc và tiếp xúc với khách hàng nước ngoài.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Khu đô thị Vạn Phúc, Thủ Đức\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Khung thời gian làm việc trong ngày có thể linh động sắp xếp, tùy vào yêu cầu từng dự án.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2698, 1179, 2, 'Net Developer', '1/ Tham gia trực tiếp Phát triển sản phẩm :\nPhát triển hệ thống phần mềm Hợp đồng điện tử và quản lý ký số\nPhát triển web backend/fontend liên quan tới sản phẩm\nPhát triển API phục vụ xây dựng Mobile Apps và tích hợp hệ thống\nTham gia viết các tài liệu cấu trúc phục vụ phát triển phần mềm\nKiểm tra, đánh giá chất lượng phần mềm sau khi lập trình, đảm bảo phần mềm ổn định, không có lỗi sảy ra khi phát hành\n\n2/ Triển khai\nNhận yêu cầu, thiết kế và xử lý công việc được giao bởi PM/BA dự án\nĐảm bảo các dự án hoàn thành đúng tiến độ và đạt chất lượng cao\nLàm việc và hỗ trợ trực tiếp với các Team sản phẩm, Mobile Developer, CSKH, Khối Vận hành,…\nTham gia tư vấn, giải đáp kỹ thuật trong quá trình chào sản phẩm\nHướng dẫn hỗ trợ khách hàng level kỹ thuật, hệ thống\n\nYêu cầu ứng viên\nCó 3  năm kinh nghiệm lập trình với công nghệ như ASP.Net,.Netcore, MVC, Entity Framework, LinQ, Restful API, WCF\nCó kiến thức về Javascript, XML/HTML/CSS, Ajax, jQuery, React, Angular, Vue\nHệ quản trị CSDL MS SQL Server, Mongo DB, PostgreSQL\nCó kiến thức về kiến trúc MicroService, Containers/Docker\nĐam mê công việc, sự sáng tạo và đổi mới\nKỹ năng giải quyết vấn đề linh hoạt, sẵn sàng phá bỏ các rào cản, tích cực tìm kiếm các giải pháp thay thế để đạt mục tiêu cần có\nTinh tần hợp tác, chủ động, nhiệt tình, hòa đồng trong công việc, làm việc tốt theo nhóm\nCó tinh thần trách nhiệm cao. Cầu thị, tự tin, quyết đoán.\n\nQuyền lợi\nQUYỀN LỢI ỨNG VIÊN\nTHU NHẬP\nLương tháng thỏa thuận theo năng lực ứng viên\nThưởng KPIs năm từ upto 2 tháng lương/năm\nGói phúc lợi tiền mặt hơn 9 triệu/năm vào các dịp Lễ, Tết, Sinh nhật Tập đoàn...\nXét tăng lương theo năng lực và kết quả công việc định kỳ 1 lần/năm. Hoặc tăng lương đột xuất theo hiệu quả công việc.\n\nCHẾ ĐỘ ĐÀO TẠO VÀ PHÁT TRIỂN\nĐài thọ 100% chi phí tham gia các khóa học, thi chứng chỉ CNTT Quốc tế.\nChính sách phát triển, thăng tiến theo Career Path phù hợp với từng vị trí, từng phòng ban.\nCơ hội tiếp cận với các công nghệ mới nhất: Cloud, Big data...\nCơ hội làm việc trong Công ty là Top 1 đối tác tư vấn và cung cấp, triển khai giải pháp Chuyển đổi số, Bảo mật, Cloud cho tổ chức và doanh nghiệp tại Việt Nam\n\nBẢO HIỂM VÀ CHÍNH SÁCH ĐÃI NGỘ\nThời gian làm việc: Thứ Hai – Thứ Sáu; Nghỉ thứ 7 & Chủ Nhật.\nNghỉ phép: 12 ngày/ năm + 1 ngày nghỉ hưởng lương vào dịp sinh nhật bản thân CBNV\nBảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo quy định Nhà nước\nChế độ bảo hiểm nâng cao: CMC Care\nChế độ đãi ngộ thai sản nâng cao dành cho nhân viên nữ\nDu lịch hàng năm 1 tuần, teambuilding/dã ngoại định kì 2 lần/năm\nTham gia các Câu lạc bộ của Công ty và các chương trình trải nghiệm nhân viên đa dạng và phong phú\nĐược trang bị laptop/thiết bị công nghệ trong quá trình làm việc.\nMôi trường làm việc trẻ trung, chuyên nghiệp\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 16, Tòa nhà CMC, 11 Duy Tân, P. Dịch Vọng Hậu, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2699, 1448, 2, 'Leader Java Backend', 'Mô tả công việc:\n- Tham gia thiết kế, kiến trúc và phát triển hệ thống backend cho sàn giao dịch P2P crypto.\n- Xây dựng các module core: quản lý người dùng, ví điện tử, xử lý đơn hàng P2P, escrow (giao dịch ký quỹ), hệ thống reward, settlement, KYC/AML...\n- Phát triển và tối ưu các API RESTful phục vụ frontend/web app và tích hợp hệ thống với bên thứ ba như Fireblocks, Chainalysis, dịch vụ blockchain node...\n- Đảm bảo các tiêu chuẩn bảo mật, hiệu năng và khả năng mở rộng (scalability) của hệ thống.\n- Định hướng kỹ thuật, mentor các thành viên junior trong team.\n- Tham gia review code, thiết kế kỹ thuật, chuẩn hóa coding convention và CI/CD pipeline.\n- Theo dõi hệ thống production, xử lý sự cố, log, giám sát hiệu suất (monitoring, alerting).\n- Cập nhật và áp dụng các công nghệ, giải pháp mới trong lĩnh vực Web3, crypto, blockchain.\n- Phản hồi nhanh chóng và hiệu quả đối về các vấn đề kỹ thuật phát sinh trong quá trình phát triển và sau khi sản phẩm được triển khai.\n- Phối hợp với các nhóm khác như UI/UX, QC, và DevOps để đảm bảo ứng dụng được phát triển một cách toàn diện.\n\nYêu cầu ứng viên:\n- Tối thiểu 4–5 năm kinh nghiệm phát triển hệ thống Backend với Java, trong đó ít nhất 2 năm kinh nghiệm làm hệ thống sàn giao dịch tập trung hoặc P2P crypto.\n- Thành thạo Java JDK 17, Spring Boots, Spring Cloud, Redis, Message Bus: Kafka/RabbitMQ, MySQL/PostgreSQL, MongoDB.\n- Hiểu sâu về các mô hình thiết kế phần mềm (Design Patterns), kiến trúc microservices và event-driven architecture.\n- Kinh nghiệm xử lý giao dịch tài chính, đảm bảo tính nhất quán dữ liệu (consistency), độ trễ thấp (low latency) và độ an toàn cao (security-first).\n- Có kiến thức về blockchain, ví crypto, smart contract, bảo mật trong Web3 là lợi thế lớn;\n- Thành thạo thiết kế API, thiết kế hệ thống, kiến ​​trúc phần mềm.\n- Thành thạo Clean Code và SOLID.\n- Khả năng thiết kế và tối ưu hóa cơ sở dữ liệu SQL và NoSQL.\n- Kinh nghiệm làm việc theo phương pháp Agile/Scrum và sử dụng các công cụ quản lý dự án như JIRA hoặc Trello.\n- Hiểu biết về các nguyên tắc bảo mật ứng dụng và kinh nghiệm triển khai các giải pháp bảo mật.\n- Khả năng giao tiếp rõ ràng và hiệu quả, cả bằng văn bản lẫn nói, với các bên liên quan kỹ thuật và phi kỹ thuật.\n- Có tinh thần học hỏi không ngừng và khả năng thích nghi với các công nghệ mới nhanh chóng.\n- Chủ động, sáng tạo, nhiệt tình, trách nhiệm trong công việc.\n- Có khả năng phân tích, tư duy logic và giải quyết vấn đề.\n\nSẵn sàng làm thêm giờ hoặc onsite khi có yêu cầu.\n\nQuyền lợi:\n- Mức lương cạnh tranh theo đúng năng lực.\n- Môi trường làm việc thân thiện, năng động, có cơ hội phát triển bản thân và thăng tiến.\n- Cơ hội tiếp cận với các công nghệ mới, làm việc trong môi trường công nghệ năng động.\n- Tham gia vào các dự án thú vị và thử thách trong lĩnh vực mới như blockchain/web3/fintech.\n- Chế độ bảo hiểm đầy đủ, nghỉ phép theo quy định.\n- Thưởng Lễ Tết, 30/4; 1/ 5; 2/9…. (theo tình hình hoạt động thực tế của Công ty).\n- Sinh nhật, ốm đau, sinh con, ma chay, hiếu hỉ theo mức quy định của Công ty.\n- Teambuilding, nghỉ mát….. (theo tình hình hoạt động thực tế của Công ty).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2700, 1453, 2, 'Nhân Viên Lập Trình PLC', 'Mô tả công việc\n- Sữa chữa các thiết bị ,Đấu nối sữa chữa phần điện, lắp ráp máy móc, line sản xuất...\n- Lập trình PLC (Mitsu, Omron, Siemen, ...)\n- Khảo sát hệ thống, thu thập thông tin hệ thống.\n- Những yêu cầu khác từ cấp trên.\n- Chi tiết trao đổi khi phỏng vấn.\n\nYêu cầu ứng viên\n- Tốt nghiệp Trung cấp, Cao đẳng/ Đại học chuyên ngành điện, tự động hóa….\n- Có kinh nghiệm trên 1 năm ở vị trí tương đương.\n- Am hiểu các thiết bị điện.\n- Biết lập trình PLC (Mitsu, Omron, Siemen, ...).\n- Biết đấu nối, sửa chữa, lắp ráp tủ điện.\n- Có kiến thức về tự động hóa.\n- Có thể làm ca.\n\nQuyền lợi\n- LƯƠNG THỎA THUẬN KHI PHỎNG VẤN.\n- Thời gian làm việc từ T2-T7.\n- Nghỉ 1 ngày/ tháng nguyên lương.\n- Được đóng bảo hiểm theo quy định của nhà nước.\n- Lương tháng thứ 13.\n- Thưởng tết, thưởng các ngày lễ, các ngày đặc biệt của công ty.\n- Làm việc trong môi trường chuyên nghiệp.\n- Luôn có cơ hội thăng tiến trong công việc nghề nghiệp.\n- Phỏng vấn và đi làm ngay nếu đạt yêu cầu.\n- Công việc ổn định và lâu dài.\n\nĐịa điểm làm việc\n- Bắc Ninh: Lô J5, KCN Hoàn Sơn, Tân Hồng, Từ Sơn, Từ Sơn.\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2701, 1454, 2, 'Lập Trình Viên NodeJS', 'Mô tả công việc:\n- Phát triển sản phẩm về lĩnh vực giáo dục của công ty\n- Xây dựng tính năng mới và tối ưu hiệu suất, bảo mật của Fronted\n- Làm việc cùng các thành viên khác để xây dựng và phát triển sản phẩm\n\nYêu cầu ứng viên:\n- Có kiến thức nền tảng về Javascript\n- Có kinh nghiệm làm việc với NodeJS và ExpressJS\n- Có kiến thức về Cơ Sở Dữ liệu MongoDB hoặc MySQL\n- Có kiến thức về Git\n- Có kỹ năng làm việc độc lập và làm việc nhóm\n- Sẵn sàng học hỏi và làm việc với công nghệ mới\n- Có kỹ năng về Tiếng Anh là một lợi thế\n\nQuyền lợi:\n- Mức lương khởi điểm: 7.000.000 VNĐ - 11.000.000 VNĐ/ tháng\n- Hỗ trợ máy tính làm việc\n- Xét tăng lương hàng năm, thưởng (các dịp lễ Tết, ...) phụ cấp theo quy chế công ty\n- Hưởng các quyền lợi theo quy định của Nhà nước (đóng BHYT, BHXH)\n- Được hưởng các chế độ phúc lợi theo quy định công ty: sinh nhật, ốm đau, hiếu hỉ\n- Nghỉ phép 12 ngày/ năm, lễ, Tết theo quy định Nhà nước\n- Tham gia các hoạt động Company Trip mỗi năm\n- Tham gia các hoạt động - sự kiện của công ty\n- Tự do trong trang phục, không bắt buộc mặc phong cách công sở\n- Môi trường trẻ trung, văn hóa cởi mở, thoải mái, chuyên nghiệp trong công việc\n- Được đào tạo và tạo điều kiện bồi dưỡng nâng cao chuyên môn', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Tĩnh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2702, 1384, 2, 'Backend Developer (C#/.NET) (Domain Fintech)', 'Mô tả công việc:\n- Tham gia phát triển các dự án về giao dịch ngoại hối cho các ngân hàng và hệ thống CCS/IRS.\n- Tham gia vào toàn bộ vòng đời của sản phẩm bao gồm thiết kế database, định nghĩa interface, coding, triển khai dịch vụ lên các môi trường được cấp phát.\n- Tham gia phát triển các module backend của ứng dụng, cùng nghiên cứu, tìm giải pháp cho các yêu cầu mới.\n- Nghiên cứu, tìm hiểu các công nghệ mới để áp dụng cải thiện sản phẩm.\n\nYêu cầu ứng viên:\n- Tối thiểu 03 năm kinh nghiệm.\n- Có kiến thức xây dựng RESTful APIs.\n- Có kinh nghiệm với các dự án phần mềm sử dụng .NET, .NET Core.\n- Có kinh nghiệm làm việc, triển khai dự án với message broker (RabbitMQ).\n- Có hiểu biết và có kinh nghiệm với MySQL, SQL Server/Oracle, Redis, có kiến thức vững chắc về thiết kế Database.\n- Có kinh nghiệm làm việc trên môi trường Linux, Docker.\n- Có hiểu biết về tài chính, giao dịch ngoại hối là một lợi thế.\n\nQuyền lợi:\n- Thỏa thuận lương theo năng lực, upto 35M Net.\n- 100% lương trong thời gian thử việc.\n- Xét tăng lương 2 lần/năm.\n- Thưởng tháng lương 13, thưởng hiệu suất, thưởng Lễ Tết, thưởng sinh nhật,...\n- Bảo hiểm xã hội, Bảo hiểm Y tế, Bảo hiểm thất nghiệp khi trở thành nhân sự chính thức.\n- Chế độ ốm đau, hiếu hỉ, khuyến khích tài năng trẻ,...\n- Môi trường trẻ trung năng động và đầy nhiệt huyết.\n- Thời gian làm việc linh hoạt.\n- Được đào tạo 1-1 với Quản lý hoặc Senior.\n- Du lịch nghỉ mát hàng năm, nhiều hoạt động teambuilding.\n- Hỗ trợ hoạt động CLB như Cầu lông, Yoga, Đá bóng, Bơi-Đạp-Chạy,...\n\nĐịa điểm làm việc:\n- Hà Nội: 106 Hoàng Quốc Việt, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2703, 1455, 2, 'Kỹ Sư Lập Trình Khuôn', 'Mô tả công việc:Thiết kế và gia công khuôn cối, đồ gá trên máy gia công.Sửa chữa khuôn máy khi gặp sự cố.Phụ trách thiết kế sản phẩm khuôn mẫu đáp ứng kịp thời nhu cầu sản xuất.Quản lý bản vẽ khuôn mẫu, triển khai bản vẽ.Kiểm tra chất lượng sản phẩm khuôn mẫu.Lập các bản vẽ 2D, 3D cho sản phẩm mới.Sản xuất và đánh giá sản phẩm mẫu.Thiết kế khuôn mẫu và các chi tiết kỹ thuật.Sửa chữa bảo dưỡng duy trì hệ thống khuôn, đồ gá trong toàn nhà máy.Kiểm soát máy móc trang thiết bị theo bộ quy trình quản lý thiết bị.Thực hiện các công việc theo yêu cầu của người quản lý.Đào tạo, hướng dẫn kỹ thuật và vận hành khuôn cho các bộ phận liên quan.Quản lý hồ sơ thiết bị khuôn mẫu, đồ gá.Các công việc khác theo sự phân công của trưởng phòng kỹ thuật.Yêu cầu ứng viên:Tốt nghiệp chuyên ngành cơ khí, cơ điện tử.Kinh nghiệm: Trên 3 năm kinh nghiệm liên quan đến vị trí Kỹ thuật khuôn.Thành thạo AutoCad, phần mềm 3D (Solidwork or inventer).Ưu tiên ứng viên có khả năng sử dụng và vận hành thành thạo các máy công cụ như khoan, bào, vận hành máy hàn và cắt gọt kim loại và vận hành cài đặt máy CNC...Khả năng làm việc dưới áp lực cao.Tư duy logic tốt.Khả năng giao tiếp, đàm phán tốt.Ưu tiên ứng viên ở Hưng Yên.Quyền lợi:Lương thỏa thuận theo năng lực từ 14-17 triệu/tháng chưa kể tăng ca.Đóng BHXH đầy đủ.Du xuân đầu năm, nghỉ mát hàng năm.Tổng thưởng Quý và thưởng Tết lên đến 3-4 tháng lương.Địa điểm làm việc:Hưng Yên: KCN Yên Mỹ 1, Tân Lập, Yên Mỹ, Yên Mỹ.Thời gian làm việc:Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).Nghỉ 01 thứ 7 và 04 chủ nhật.Cách thức ứng tuyển:Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hưng Yên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2704, 1456, 2, 'Frontend Developer', 'Mô tả công việc\n- Phối hợp với các team UI/UX, PO, Backend dev,...để triển khai các tính năng trên sản phẩm đảm bảo yêu cầu về chất lượng, tiến độ của các dự án theo các tiêu chuẩn thiết kế, tiêu chuẩn mã nguồn, bảo mật và hiệu năng cao cho hệ thống.\n- Xây dựng và triển khai hệ thống website builder - dạng kéo thả\n  - Email builder (hỗ trợ hiển thị tốt trên Outlook)\n  - Landing Page builder\n  - Popup builder\n  - Contact form\n- Thực hiện Unit Test. Hỗ trợ kiểm thử SIT/UAT, sửa lỗi và nghiệm thu chức năng.\n- Cập nhật và áp dụng các công nghệ mới nhằm cải thiện chất lượng sản phẩm.\n\nYêu cầu ứng viên\n- Có ít nhất 2 năm kinh nghiệm làm việc với Angular, Typescript, HTML5, CSS3, RxJS, và các kỹ thuật xử lý bất đồng bộ.\n- Pixel Perfect: Xử lý chi tiết trong việc chuyển từ Figma qua HTML, CSS.\n- Hiểu rõ về kiến trúc Single Page Applications, RESTful API.\n- Có kinh nghiệm xử lý HTML/CSS template email hiển thị trên Outlook\n- Có kinh nghiệm làm việc với các sản phẩm Builder (dạng kéo, thả) là một lợi thế\n- Có kỹ năng phân tích, giải quyết vấn đề, tối ưu hóa, chủ động và luôn tìm hiểu trước khi đặt vấn đề\n- Sử dụng thành thạo các IDE phát triển và công cụ quản lý mã nguồn (Git)\n- Có hiểu biết về Backbone JS là một lợi thế\n- Hiểu biết và có kinh nghiệm thực tế với DevOps, CI/CD là một lợi thế\n- Có hiểu biết, kinh nghệm về SAFe 6.0 là một lợi thế\n- Có mindset UI/UX tốt là một lợi thế.\n\nQuyền lợi\nPhúc lợi tài chính minh bạch và xứng đáng\n- Mức lương: 15M - 25M\n- Thử việc 100% lương chính thức\n- Package 13 tháng lương cố định/năm\n- Lộ trình đánh giá năng lực và điều chỉnh thu nhập 1 – 2 lần/năm (tuỳ cấp độ nhân viên).\n\nTrải nghiệm sự trân trọng và săn sóc đặc biệt qua các chế độ phúc lợi độc đáo\n- Chính sách đào tạo lên tới 20 triệu/năm\n- Chế độ chăm sóc sức khỏe: Bảo hiểm sức khỏe hàng năm cho Nhân viên và người thân; khám sức khỏe định kỳ 1 lần/năm.\n- Chế độ thai sản đặc biệt: 20 triệu/1 Nhân viên nữ sinh con.\n- 12 ngày phép/năm, nhân viên làm việc từ năm thứ 5 trở lên mỗi 5 năm được tăng thêm 01 ngày phép.\n- Mỗi nhân viên sẽ được nghỉ hưởng nguyên lương 0,5 ngày vào ngày sinh nhật của mình.\n- Chính sách CLB thể thao (bóng đá, cầu lông, bơi lội, chạy bộ...): 3 triệu/1 CLB/tháng.\n- Quỹ hoạt động giao lưu, gắn kết Team định kỳ hàng quý.\n- Chế độ thăm hỏi ốm đau, hiếu, hỉ, quà mừng con CBNV chào đời.\n- Cung cấp đầy đủ trang thiết bị làm việc.\n\nThời gian làm việc\n- Từ Thứ 2 đến Thứ 6 hàng tuần và 1 ngày thứ 7 đầu tháng\n- Thời gian trong ngày: 9h00 - 18h00.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa HL, số 6 ngõ 82 Duy Tân, Dịch Vọng Hậu, Cầu Giấy, Cầu Giấy.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2705, 1123, 2, 'Java Developer', 'Mô tả công việc:\n- Develop and maintain backend systems and services in Java.\n- Collaborate with frontend developers and other team members to design and implement robust solutions.\n- Write clean, scalable, and efficient code while adhering to best practices.\n- Troubleshoot and debug applications to ensure optimal performance.\n- Participate in code reviews and contribute to the continuous improvement of development processes.\n\nYêu cầu ứng viên:\n- Bachelor’s degree in Computer Science, Software Engineering, or a related field.\n- 3 years of experience in Java development with a solid understanding of backend technologies.\n- Familiarity with frameworks such as Spring or Hibernate.\n- Strong problem-solving skills and the ability to work independently and as part of a team.\n- Good English communication skills, both written and verbal.\n\nQuyền lợi:\n- Salary: Negotiation\n- Join a global team and work directly with many talents around the world.\n- Opportunities for onsite work in Japan, Singapore, Australia, and many other countries.\n- Work and grow in a dynamic, creative, and professional environment.\n- Healthcare: Premium Health Insurance TECHVIFY Care\n- 13 months’ salary per year.\n- Annual salary evaluation.\n- Sponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 9, tháp A, tòa HUDTOWER, số 37 Lê Văn Lương, Phường Nhân Chính, Thanh Xuân\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2706, 1395, 2, 'Net Developer', 'Mô tả công việc\n● Tham gia phát triển các hệ thống web cho Ngân Hàng\n● Tham gia phát triển, nâng cấp và bảo trì các hệ thống phần mềm nội bộ và sản phẩm dịch vụ ngân hàng sử dụng nền tảng .NET Framework / .NET Core.\n● Thực hiện lập trình các sản phẩm, dịch vụ theo yêu cầu\n● Nghiên cứu và cập nhật các kiến thức mới hỗ trợ cho công việc\n● Làm việc nhóm hoặc độc lập, giao tiếp với cấp trên và thành viên liên quan đến công việc\n\nYêu cầu ứng viên\n● Tốt nghiệp đại học chuyên ngành CNTT, Khoa học máy tính, hoặc các ngành liên quan.\n● Có tối thiểu 2 năm kinh nghiệm trong lĩnh vực phát triển ứng dụng ngân hàng số, tài chính số hoặc các lĩnh vực liên quan (lập trình .NET, Restful API, Oracle Database)\n● Thành thạo lập trình Web với ASP.NET MVC, Web API.\n● Hiểu biết tốt về HTML, CSS, JavaScript, jQuery, có kinh nghiệm làm việc với các framework front-end là lợi thế.\n● Có kinh nghiệm làm việc với SQL Server, viết stored procedures, trigger, tối ưu câu truy vấn.\n● Hiểu biết về mô hình client-server, kiến trúc đa tầng và nguyên lý OOP\n\nQuyền lợi\n● Làm việc từ thứ 2 đến thứ 6, nghỉ thứ 7 và CN\n● Offer: 18,000,000VNĐ - 28,000,000VNĐ Net/ tháng.\n● Không cần thử việc, ký luôn hợp đồng chính thức và đóng bảo hiểm từ tháng đầu nhận việc.\n● Cố định 13 tháng lương Net/ năm.\n● Được tham gia vào các dự án lớn của Ngân hàng.\n● Có lộ trình phát triển, thăng tiến rõ ràng đánh giá theo level nhân sự từ member => key member => Teamlead.\n● Thưởng lễ tết; Quy đổi phép thành tiền/ cộng dồn phép.\n● Có cơ hội tiếp cận và học hỏi công nghệ mới.\n● Môi trường công bằng, đảm bảo mọi người đều có thể phát huy hết khả năng của mình.\n● Được làm việc với những cá nhân xuất sắc, có nhiều kinh nghiệm.\n● Được hưởng Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n● Teambuilding 3 tháng 1 lần; Bóng đá 2 trận/1 tuần.\n● Khám sức khỏe định kỳ 1 năm/1 lần.\n● Chế độ du lịch hàng năm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2707, 1146, 2, 'Lập Trình Viên BAck-End', 'Chúng tôi đang tìm kiếm ứng viên nhiệt huyết và đam mê công việc để gia nhập đội ngũ nhân viên trẻ tuổi và tài năng của  công ty FSEL với yêu cầu như sau:\n\n● Tham gia phát triển các sản phẩm phục vụ cho hàng trăm nghìn khách hàng về các dịch vụ học trực tuyến E-learning\n● Xây dựng và tối ưu sản phẩm đáp ứng hàng trăm nghìn người sử dụng đồng thời\n● Tham gia nghiên cứu và ứng dụng các công nghệ mới vào sản phẩm: Blockchain, AI, Machine Learning, BigData, RPA, …\n● Phối hợp cùng đội ngũ BA phân tích, thiết kế, đưa ra giải pháp để phát triển phần mềm đáp ứng đúng, đủ, tiện các yêu cầu của người dùng cuối\n● Tham gia tất cả các giai đoạn phát triển phần mềm được yêu cầu từ lập kế hoạch, ước tính, thiết kế và phát triển việc thực hiện.\n● Tham gia vào các quy trình Agile như Scrum hoặc Kanban.\n\nYêu cầu ứng viên:\n• Tốt nghiệp đại học các chuyên ngành Khoa học máy tính hoặc Công nghệ thông tin.\n• Có ít nhất 3 năm kinh nghiệm trong các dự án .NET.\n• Có kinh nghiệm công nghệ dữ liệu nâng cao của Microsoft: ADO.NET, .NET Core, ASP.NET (Core), MVC, Entity Framework (Core), Linq, SQL Server.\n• Có khả năng triển khai & tối ưu hóa các công nghệ .NET Server-side thành thạo.\n• Có kinh nghiệm thiết kế các API RESTful với ASP.NET.\n• Rất tốt trong việc hiểu và áp dụng các Mẫu thiết kế / Nguyên tắc thiết kế.\n• Thành thạo trong việc duyệt mã, tái cấu trúc mã.\n• Có kiến ​​thức cơ bản về HTML, CSS, JavaScript. Có kinh nghiệm về bất kỳ JavaScript nào, ví dụ: Angular, React, Vue\n• Kiến thức cơ bản về công nghệ cloud, v.d. Azure, AWS.\n• Có kinh nghiệm làm việc trong môi trường Phát triển phần mềm Agile / Scrums.\n• Có thái độ tốt về tự kiểm tra và tự học.\n\nQuyền lợi:\n• Mức lương (gross): up to 30 triệu/tháng\n• Thưởng sinh nhật, thưởng các dịp Lễ, Tết trong năm\n• Chế độ BHXH, BHYT, BHTN đầy đủ ngay sau khi ký HĐ chính thức\n• Khám sức khoẻ định kỳ hàng năm\n• Trang bị máy tính hiện đại phục vụ công việc\n• Quỹ Team Building lên tới 2.400.000 VNĐ/người/năm\n• Du lịch nghỉ dưỡng hàng năm\n• Trà chiều với bánh, hoa quả và đồ ăn vặt miễn phí hàng tuần\n• Cơ hội tiếp cận với các doanh nghiệp, dự án lớn, xu hướng công nghệ và nền tảng mới nhất\n• Được tham gia các lớp đào tạo, khóa học chuyên môn để phát triển kỹ năng\n• Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung & trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc\n• Học tiếng Anh hoàn toàn miễn phí & ưu đãi học phí cho người thân.\n\nĐịa điểm làm việc:\n- Hà Nội: 35 Lạc Trung, Hai Bà Trưng\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:20)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2708, 1457, 2, 'Flutter Developer', '- Phát triển ứng dụng ecomerce liên quan đến việc mua bán các sản phẩm về giáo dục như sách, bút và khoá học online.\n- Phát triển ứng dụng về Elearning cho phép học tập online Maintain, fixbug và có khả năng research các công nghệ mới.\n- Viết các unit test.\n- Tham gia brainstorm phát triển các tính năng sản phẩm hoặc các sản phẩm mới cùng product owner.\n- Trao đổi và phân tích các yêu cầu cùng team lead.\n- Thực hiện việc phát triển dự án theo mô hình Agile.\n- Có thể làm hybrid hoặc lên văn phòng, quan trọng là công việc hiệu quả.\n\nYêu cầu ứng viên:\n- Có kinh nghiệm ít nhất từ 2-3 năm về Flutter.\n- Có ít nhất 1 dự án đã làm trong thực tế, đặc biệt đã làm về ecommerce là 1 lợi thế.\n- Có khả năng nghiên cứu và ứng dụng các công nghệ mới.\n- Có kĩ năng Problem soving tốt.\n- Có khả năng làm việc độc lập.\n- Thành thạo sử dụng git.\n- Có kinh nghiệm tham gia các dự án quản trị theo phương thức Agile.\n- Có thể làm fullstack hoặc có kinh nghiệm làm backend là 1 lợi thế.\n\nQuyền lợi:\n- Đóng đầy đủ bảo hiểm.\n- Có lương tháng 13.\n- Nếu làm tốt trở thành core-team có thể thưởng tiếp hoa hồng theo doanh thu.\n- Được đánh giá tăng lương 1 lần/năm hoặc khi có thành tích đặc biệt.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 8, ngõ 25 Nguyễn Chánh, Cầu Giấy.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2709, 111, 2, 'Front End Developer', '• Phát triển và duy trì ứng dụng mobile/web sử dụng Flutter.\n• Tham gia thiết kế UI/UX, tối ưu hiệu năng và trải nghiệm người dùng.\n• Phối hợp với team backend để xây dựng API tích hợp hệ thống.\n• Có thể đảm nhận các tác vụ backend đơn giản (Node.js/NestJS) nếu cần.\n• Viết unit test, xử lý bug và cải tiến sản phẩm theo feedback người dùng.\n• Tham gia góp ý và cải thiện quy trình phát triển.\n\nYêu cầu ứng viên:\n• Tối thiểu 1 năm kinh nghiệm phát triển Flutter (iOS, Android, Web).\n• Tốt nghiệp Đại học chuyên nghành KTPM, CNTT, HTTT, CNPM, KHMT của các trường UIT, Bách khoa, KHTN, BCVT, SPKT.\n• Nắm chắc kiến thức nền, thuật toán và giải thuật.\n• Thành thạo Dart và tư duy OOP tốt.\n• Hiểu vững cấu trúc Flutter: Widget tree, lifecycle, state management (BLoC).\n• Thiết kế UI tương thích nhiều thiết bị và độ phân giải (responsive, theme, animation,..)\n• Hiểu biết về tích hợp RESTful API, Routing, Navigation, Notification, Local Database.\n• Có kiến thức hoặc kinh nghiệm làm việc với Node.js/NestJS là một lợi thế.\n• Biết làm việc với Firebase, Firestore, hoặc các cloud service là điểm cộng.\n• Có tư duy sản phẩm, chủ động và ham học hỏi.\n\nQuyền lợi:\n• Lương: 10.000.000 - 15.000.000 VND/tháng.\n• Môi trường làm việc trẻ, năng động.\n• Làm việc với sản phẩm thật, có lượng người dùng lớn.\n• Được training hoặc phát triển kỹ năng backend nếu mong muốn.\n• Hỗ trợ thiết bị làm việc (Mac mini, màn hình).\n• Review lương 6 tháng 1 lần\n• Được đóng BHXH, BHYT, BHTN theo quy định của nhà nước sau 2 tháng thử việc\n• Trả lương đều đặn từ 1-10 hàng tháng. Không nợ lương + thưởng của nhân viên.\n• Thưởng tháng 13 + thưởng nhân viên xuất sắc cuối năm.\n• Tham gia chơi thể thao với công ty hàng tuần.\n• Team building và du lịch hàng năm.\n• Phúc lợi tăng theo sự phát triển của Công ty\n• Các chế độ khác: Theo Luật lao động Việt Nam, theo nội quy lao động và Quy định tài chính của công ty.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Nhà A, Khu công nghệ Phần mềm ĐHQG TPHCM, KP 6, Phường Linh Trung, Thủ Đức.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2710, 1458, 2, 'Automation & System Developer', 'Chúng tôi đang xây một hệ thống bán hàng tự động – vận hành từ A đến Z mà không cần phụ thuộc vào ads. Để làm được điều đó, bạn sẽ: \n- Thiết kế và triển khai các workflow automation sử dụng n8n self-host. \n- Scrape và thu thập dữ liệu trend/ngách từ nhiều nguồn (Google Trends, Redbubble, TikTok…). \n- Kết hợp AI (LLM, image generation, mockup automation…) để tạo nội dung đăng tải đa kênh. \n- Phối hợp với team marketing để đẩy sản phẩm ra TikTok, IG, Pinterest, Reddit, v.v. \n- Đo lường hiệu suất nội dung, trigger tái đăng hoặc chạy ads tự động khi đạt ngưỡng. \n- Tự động hoá toàn bộ quy trình “phát hiện → thiết kế → đăng → theo dõi → tối ưu”.\n\nYêu cầu ứng viên: \n1. Kỹ năng chuyên môn bắt buộc: \n- Thành thạo Python: xử lý request, API, scraping, automation, session/cookie/proxy… \n- Sử dụng thành thạo n8n self-hosted (hoặc tương đương như Airflow, Make). \n- Có kinh nghiệm với Selenium, Requests, Playwright, xử lý anti-bot logic. \n- Biết cách tích hợp & gọi API từ các nền tảng như OpenAI, Google Gemini, Stable Diffusion. \n- Biết dùng FFMPEG, Flux.1, hoặc tương đương để tạo mockup video chuyên nghiệp. \n- Có hiểu biết về REST API, OAuth, webhook, retry logic, xử lý lỗi hệ thống. \n\n2. Tư duy & mindset: \n- Yêu thích xây hệ thống, tối ưu workflow, thích tự động hóa mọi thứ. \n- Chủ động học hỏi, tự test, tự debug, không cần ai nhắc việc. \n- Có growth hacker, thích thử – đo – lặp lại – scale. \n\nPHÙ HỢP VỚI ỨNG VIÊN: \n- Muốn thấy thứ mình code ra chạy thật, tạo ra tiền thật, trong hệ thống thật. \n- Muốn làm việc với đội ngũ yêu automation, yêu AI, yêu công nghệ để apply vào cuộc sống. \n- Vui vẻ, cởi mở, thích trao đổi thẳng thắn và làm việc teamwork thực chiến.\n\nQuyền lợi: \n- Mức lương cạnh tranh theo năng lực + lộ trình tăng lương rõ ràng. \n- Làm việc trực tiếp với founder có tư duy sản phẩm và hệ thống mạnh. \n- Có quyền xây dựng hệ thống từ đầu, được công nhận là builder chứ không phải người làm thuê. \n- Làm việc trong môi trường đề cao việc học hỏi, đổi mới và ứng dụng AI.\n\nĐịa điểm làm việc: \n- Hồ Chí Minh: 128 Phan Xích Long, P. 7, Phú Nhuận.\n\nThời gian làm việc: \n- Thời gian làm việc từ 9:00 - 18:00, từ thứ 2 đến thứ 7 (thứ 7 làm việc cách tuần). \n\nCách thức ứng tuyển: \n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2711, 1314, 2, 'Java Developer', 'A. MÔ TẢ CÔNG VIỆC:\n1. Nội dung chi tiết:\n- Phân tích yêu cầu, thiết kế hệ thống (sẽ được hướng dẫn) và phát triển front-end/ back-end cho các dự án với dữ liệu lớn, tích hợp đối tác và product của Công ty (ưu tiên Back-end)\n- Thu thập dữ liệu, triển khai hệ thống xử lý, phân tích dữ liệu lớn hàng chục triệu khách hàng đồng thời\n- Phát triển các phần mềm để thúc đẩy kinh doanh cho Công ty\n- Xây dựng hệ thống Core của Công ty\n- Tham gia tối ưu và tái kiến trúc lại hệ thống hiện tại\n- Thực hiện các công việc khác theo sự phân công của Quản lý\n\n2. Thời gian làm việc: 08h30 - 17h30 (Thứ Hai - Thứ Sáu; nghỉ Thứ Bảy + Chủ nhật)\n\n3. Địa điểm làm việc: Tòa nhà G-Group, 5 Nguyễn Thị Duệ, Cầu Giấy, Hà Nội\n\nYêu cầu ứng viên\n- Tối thiểu 04 năm kinh nghiệm lập trình front-end và back-end với ngôn ngữ Java\n- Từng làm ít nhất 1 dự án trong lĩnh vực tài chính (ưu tiên liên quan tới luồng nghiệp vụ cho vay)\n- Nắm vững kiến thức về OOP, Design Pattern, Microservice, SOA ....\n- Có khả năng thiết kế, tối ưu database (Mysql, NoSQL, SQL Sever)\n- Có kinh nghiệm triển khai dự án dùng dịch vụ AWS là một lợi thế\n- Có kinh nghiệm triển khai dự án dùng Camunda là một lợi thế\n- Đề cao trách nhiệm trong công việc, ý thức chất lượng sản phẩm tốt\n- Đam mê tìm tòi nghiên cứu học hỏi công nghệ mới, phát triển bản thân\n\nƯu tiên:\n- Có kinh nghiệm xây dựng các ứng dụng Java với các framework nổi tiếng: Spring, Hibernate, DGS...\n- Có kinh nghiệm làm việc với các kỹ thuật của AWS…\n- Có kinh nghiệm về phát triển search engine hoặc đã từng sử dụng Solr, ElaticSearch để xây dựng\n- Có kinh nghiệm về xử lý tối ưu xử lý dữ liệu, dữ liệu lớn\n- Có kinh nghiệm làm việc với Mifosx hoặc nền tảng Fineract Platform\n- Yêu thích công nghệ mới và có khả năng nắm bắt công nghệ mới nhanh\n\nQuyền lợi\n1. Chế độ chính sách:\n- Lương thưởng cạnh tranh trên thị trường, phản ánh đúng năng lực thực tế.\n- Thưởng cuối năm + thưởng Lễ/Tết + thưởng sinh nhật + thưởng đột xuất khi hoàn thành tốt nhiệm vụ\n- 12 ngày phép năm + phép thâm niên\n- BHXH + chế độ bảo hiểm đặc biệt dành cho nhân viên (F88 Care)\n- Tham gia thường xuyên các hoạt động gắn kết với tập thể như: Teambuilding, Tất niên, 8/3, 20/10, Giáng sinh…\n\n2. Môi trường làm việc:\n- Cơ hội làm việc tại Công ty Fintech hàng đầu về dịch vụ tài chính\n- Được làm việc trong môi trường trẻ năng động, luôn coi Công nghệ thông tin là yếu tố trọng tâm để phát triển\n- Áp dụng mô hình phát triển phần mềm theo Agile, Scrum\n- Môi trường làm việc cởi mở và năng động với các giá trị cốt lõi sâu sắc truyền cảm hứng làm việc đến nhân viên\n- Khuyến khích trao đổi ý tưởng, đề cao sự sáng tạo trong công việc\n\n3. Cơ hội phát triển:\n- F88 cam kết cho bạn nền tảng vững chắc để học hỏi và phát triển\n- Tham gia đào tạo bài bản, chuyên nghiệp từ Học viện F88\n- Sẵn sàng trao quyền, cơ hội đột phá cho nhân viên\n\nĐịa điểm làm việc\n- Hà Nội: 5 Nguyễn Thị Duệ, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2712, 1204, 2, 'Developer Leader', 'Mô tả công việc:\n- Tham gia vào phát triển các dự án với vai trò Team Leader từ giai đoạn Basic Design, Detail Design, Development, Release;\n- Thiết kế kiến trúc tổng thể hệ thống, Database, phát triển các chức năng đồng thời support các thành viên trong team;\n- Quản lý, lập kế hoạch, review công việc của các thành viên trong team;\n- Transfer lại cho Team về giải pháp, kiến trúc hệ thống;\n- Support các thành viên trong team xử lý những vấn đề khó phát sinh trong quá trình phát triển;\n- Tham gia với PM lập kế hoạch và hỗ trợ quản lý dự án;\n- Làm các công việc khác theo sự phân công của quản lý( Research new Technologies, Support team...).\n\nYêu cầu ứng viên:\n- 5-7 năm kinh nghiệm ở vị trí tương đương.\n- Tốt nghiệp khoa CNTT từ các trường đại học, Cao Đẳng\n- Có kinh nghiệm tối ưu hiệu năng cho những ứng dụng thực tế trên production, phục vụ lượng lớn người dùng và dữ liệu;\n- Sẵn sàng học hỏi và phát triển những ngôn ngữ mới \n- Có kinh nghiệm phát triển phần mềm trên nền công nghệ Java, và các framework như JSP, Servlet, Spring, Hibernet, Struts, ...\n- Có kinh nghiệm phát triển Portlet trên Liferay;\n- Ưu tiên những ứng cử viên có kinh nghiệm cài đặt, quản trị hệ điều hành Linux/Unix, hiểu biết hoặc có kinh nghiệm với các sản phẩm phần mềm mở sau: Alfresco, jBPM/Activiti, Pentaho, jBOSS, Postgre, ...\n- Tiếng Anh giao tiếp nghe nói tốt\n\nQuyền lợi:\n- Thưởng tháng lương 13.\n- Chế độ nghỉ phép 12 ngày/năm nghỉ lễ, phép theo quy định.\n- Làm việc từ thứ 2 đến thứ 6 hàng tuần nghỉ thứ 7 & CN.\n- Làm việc trong môi trường chuyên nghiệp, thân thiện và hòa đồng với cơ hội thăng tiến lớn.\n- Luôn được đào tạo chuyên môn, học hỏi liên tục các công nghệ mới mang tính thực tế cao và tham gia các dự án lớn.\n- Lương thưởng hấp dẫn theo năng lực\n- Hưởng thêm trợ cấp ăn trưa, và đi lại nếu có.\n- Hưởng các chế độ BHXH, BHYT, BHTN và nghỉ phép theo luật định khi ký Hợp đồng lao động.\n- Hưởng các chế độ phúc lợi như nghỉ mát, ngoại khóa, các sự kiện hàng quý/năm, các phần quà các ngày lễ, tết…\n\nĐịa điểm làm việc:\n- Hà Nội: Đường 2.2 Gamuda, Trần Phú, Hoàng Mai\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- nghỉ trưa 1,5h\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2713, 1459, 2, 'Management Trainee Digital Channel Program - 1Y560', 'Giới thiệu về chương trình Management Trainee tại MSB:\nLà ngân hàng đầu tiên tại Việt Nam triển khai chương trình Management Trainee (Quản trị viên Tài năng), qua 07 mùa từ 2011, MSB tự hào mang đến bệ phóng sự nghiệp lý tưởng cho sinh viên mới tốt nghiệp. Chương trình đã đào tạo thành công nhiều lãnh đạo cấp cao hiện tại của MSB.\n\nTại MSB, bạn sẽ được tham gia chương trình đào tạo bài bản, chuyên sâu với lộ trình phát triển rõ ràng qua 04 kỳ luân chuyển tại nhiều phòng ban trong 24 tháng, giúp bạn khám phá tiềm năng và tích lũy kinh nghiệm toàn diện. Bạn sẽ được hướng dẫn bởi lãnh đạo cấp trung, lãnh đạo cấp cao và nhận được chế độ đãi ngộ hấp dẫn, từ đó xây dựng sự nghiệp vững chắc cho bản thân.\n\nGiới thiệu về Digital Channel Program:\nChương trình xây dựng nền tảng giao dịch số Internet Banking/Mobile Banking đẳng cấp dành cho Khách hàng của Ngân hàng Bán lẻ/Ngân hàng Doanh nghiệp. Đóng vai trò là động lực tăng trưởng cho thu hút khách hàng mới và thúc đẩy chuyển đổi giao dịch từ chi nhánh sang kênh online.\n\nDigital Channel đặt ra mục tiêu xây dựng nền tảng kỹ thuật số hàng đầu cho ngân hàng:\n• Đáp ứng tính ổn định, khả năng mở rộng và đảm bảo tính tin cậy cho toàn bộ hoạt động kinh doanh.\n• Triển khai nền tảng chung cho ứng dụng di động (Mobile banking), ngân hàng trực tuyến (internet banking) và các ứng dụng trực tuyến khác cho RB & EB.\n• Digital Channel hướng đến trải nghiệm người dùng trực quan, liền mạch ứng dụng trong việc thu hút và giữ chân khách hàng, bán hàng và phục vụ khách hàng, liên tục bàn giao các sản phẩm thông qua DevSecOps.\n• Cho phép khách hàng tự phục vụ mọi lúc, mọi nơi.\n• Chương trình dự định sẽ chia làm 03 giai đoạn chính: Giai đoạn thiết kế, Giai đoạn triển khai phát triển và Giai đoạn mở rộng.\n\nYêu cầu ứng viên:\n• Tốt nghiệp chuyên ngành Tài chính – Ngân hàng hoặc các ngành liên quan.\n• Ưu tiên ứng viên có kiến thức hoặc bằng cấp bổ trợ về Công nghệ Thông tin, Agile, hoặc Design Thinking.\n• Có tư duy đổi mới, khả năng quan sát và xây dựng hành trình khách hàng hiệu quả.\n• Yêu thích sáng tạo, có định hướng phát triển trong môi trường công nghệ và kinh doanh số.\n\nQuyền lợi:\n• Lộ trình 24 tháng với 4 vòng luân chuyển tại các phòng ban trọng điểm.\n• Nhận mức lương khởi điểm hoàn toàn khác biệt, kí hợp đồng lao động chính thức và chế độ đãi ngộ hấp dẫn top ngành Ngân hàng.\n• Trải nghiệm thực tiễn tại các dự án chuyển đổi chiến lược.\n• Đào tạo chuyên sâu theo chương trình đào tạo được thiết kế riêng & Đồng hành bởi các mentor là lãnh đạo cấp cao.\n• Cơ hội "fast-track" trở thành lãnh đạo trong 02 năm.\n\nĐịa điểm làm việc:\n- Hà Nội\n- Hồ Chí Minh\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2714, 209, 2, 'Java Engineer Good English', 'Mô tả công việc:\n- Develop, and implement scalable and efficient Backend solutions using Java and Spring Boot.\n- Collaborate with cross-functional teams to understand project requirements and translate them into Backend functionalities.\n- Optimize code, integrate design patterns, and ensure high performance, reliability, and security of Backend systems.\n- Work with relational databases, write efficient SQL queries, and maintain data models.\n- Implement RESTful APIs with authentication, error handling, and versioning.\n- Perform unit testing, code reviews, and maintain code quality.\n- Collaborate with Frontend developers to integrate Frontend components with Backend services.\n- Debug and resolve issues reported by users or identified through testing and monitoring.\n- Stay updated with emerging technologies and industry trends in Backend development.\n- Support system integration according to the data interface specification.\n- Support SIT, UAT, non-functional test, etc.\n- Prepare technical related materials for the architecture, security, service transition and PCQA.\n- Performing requirement analyses.\n- Developing high-quality and detailed designs.\n- Conducting unit testing using automated unit test frameworks.\n- Identifying risk and conducting mitigation action planning.\n- Conducting configuration of your own work.\n- Reviewing the work of other developers and providing feedback.\n\nYêu cầu ứng viên:\n- Strong experience in Backend development using Java and Spring Boot 5 years +.\n- Proficiency in Hibernate or other ORM frameworks.\n- Familiarity with relational databases, writing efficient SQL queries, and optimizing database performance.\n- Knowledge of RESTful API design principles and advance.\n- Familiarity with unit testing, code reviews, and DevOps tools (e.g.: Git, Jenkins, Artifactory, SonarQube, Kubernetes and cluster management / administration etc.).\n- Excellent teamwork and communication skills to manage the team.\n- Problem-solving abilities and attention to detail.\n- Experience with cloud platforms and containerization technologies (AWS, Azure and Private Cloud).\n- API Gateways – AWS, Azure, APIGEE.\n- Familiarity with Agile development methodologies is preferred.\n- Develop and test the solution according to the system design and integration.\n- Support SIT, UAT, integration test, non-functional test, etc.\n- Backend technical skills including Java, Springboot, Hibernate, SQL DB, Swagger, Light4J.\n- Infrastructure orchestration and initialization scripts to automate creation of complex virtual environments.\n\nQuyền lợi:\n- “FPT care” health insurance for FPT employees.\n- Annual Summer Vacation: follows company’s policy and starts from May every year.\n- Salary review 1 times/year or on excellent performance.\n- International, dynamic, friendly working environment.\n- Annual leave, working conditions follow Vietnam labor laws.\n- Other allowances: lunch allowance, working on-site allowance, etc.\n\nĐịa điểm làm việc:\n- Đà Nẵng\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Remote hoặc Hybrid. Tuyển dụng cả 3 miền HN, HCM, DN.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2715, 1350, 2, 'Frontend Developer', 'Mô tả công việc:\n- Build and maintain complex user interfaces using React and React Native.\n- Translate design mockups and wireframes into high-quality code.\n- Ensure responsive and adaptive design for cross-platform compatibility (web and mobile).\n- Optimize components for maximum performance across a wide range of devices and browsers.\n- Address performance bottlenecks and ensure the app runs smoothly.\n- Implement state management using tools like Redux, MobX, or Context API.\n- Manage application state efficiently in large-scale applications.\n- Work with backend developers to integrate RESTful or GraphQL APIs.\n- Handle asynchronous data flow with tools like Axios, Fetch, or Apollo Client.\n- Conduct code reviews and ensure coding standards and best practices.\n- Mentor junior developers and assist with technical problem-solving.\n- Write unit, integration, and end-to-end tests using tools like Jest, Enzyme, or Cypress.\n- Debug and fix production issues efficiently.\n- Collaborate closely with UX/UI designers, backend developers, and product managers to ensure the frontend aligns with user needs and technical requirements.\n- Participate in agile processes like sprint planning, standups, and retrospectives.\n- Manage codebase using Git for version control.\n- Participate in the CI/CD pipeline and handle code deployments for web and mobile apps.\n- Stay up-to-date with the latest trends in React, React Native, and frontend technologies.\n- Evaluate and integrate new libraries and tools to improve development processes.\n- Ensure web applications are accessible to all users, including those with disabilities (ARIA standards).\n- Implement SEO best practices for React applications.\n\nYêu cầu ứng viên:\n- A higher education degree in Computer Science or equivalent knowledge acquired through professional experience.\n- Minimum of 5 years of experience in software development, with a strong focus on browser-based user interfaces.\n- Proficiency in HTML, CSS, JavaScript (ES6+), and frontend frameworks (React, Vue.js, or Angular).\n- Experience with responsive design, cross-browser compatibility, and web performance optimization.\n- Familiarity with state management (Redux, Vuex) and API integration.\n- Knowledge of Git, CI/CD pipelines, and Agile methodologies.\n- Strong problem-solving skills and attention to detail.\n\nQuyền lợi:\n- Competitive salary commensurate with experience.\n- Flexible working hours to support work-life balance and productivity.\n- Opportunity to work in a dynamic startup environment with a passionate and talented team.\n- Chance to make a significant impact on the growth and success of innovative products in the D2C industry.\n- Collaborative culture that values creativity, diversity, and continuous learning.\n- Career growth and skill development opportunities.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Huỳnh Khương Ninh, Quận 1\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2716, 1460, 2, 'Junior Frontend Developer', 'Mô tả công việc: Tham gia phát triển nền tảng quản trị giáo dục: Xây dựng và nâng cấp các ứng dụng web, di động (iOS, Android) và/hoặc desktop (Windows, macOS) nhằm cải thiện trải nghiệm học tập và tối ưu hóa quy trình vận hành. Thiết kế và xây dựng giao diện người dùng (UI): Phát triển các tính năng giao diện thân thiện, tuân thủ tiêu chuẩn thiết kế, đảm bảo khả năng bảo trì, mở rộng và tương thích đa nền tảng. Bảo trì và tối ưu hóa hệ thống: Xử lý các lỗi kỹ thuật, cải thiện hiệu suất và đề xuất các giải pháp nâng cao chất lượng sản phẩm. Thu thập và phân tích phản hồi: Làm việc với người dùng và khách hàng để thu thập ý kiến, từ đó đề xuất và triển khai các giải pháp cải tiến nhằm nâng cao trải nghiệm người dùng. Yêu cầu ứng viên: Kỹ thuật:  React/React Native: Thành thạo các khái niệm cốt lõi của React (component, state, props, hooks) và/hoặc React Native để phát triển giao diện web hoặc di động. HTML, CSS, JavaScript/TypeScript: Nắm vững các công nghệ frontend cơ bản, có khả năng xây dựng giao diện responsive và tối ưu trải nghiệm người dùng. Flutter/Dart: Có kinh nghiệm phát triển ứng dụng di động hoặc desktop với Flutter, bao gồm xây dựng giao diện (Widgets) và quản lý trạng thái (Provider, Riverpod, hoặc Bloc), là một lợi thế lớn. Git: Thành thạo sử dụng Git (GitHub, GitLab, Bitbucket) để quản lý mã nguồn và làm việc nhóm. Kiến thức nền tảng: Hiểu rõ các khái niệm cốt lõi về phát triển web (DOM, event handling) và ứng dụng di động/desktop (vòng đời ứng dụng, quản lý tài nguyên). Phân tích và xử lý lỗi: Có khả năng phân tích, phát hiện và đề xuất giải pháp cho các vấn đề kỹ thuật từ cơ bản đến phức tạp trong các module phần mềm. Kinh nghiệm: Tối thiểu 1 năm kinh nghiệm ở vị trí Frontend Engineer hoặc tương đương, đã tham gia phát triển ứng dụng thực tế sử dụng React/React Native. Có kinh nghiệm với Flutter (đặc biệt là ứng dụng desktop) là một lợi thế, nhưng không bắt buộc. Có ít nhất 1-2 dự án thực tế (cá nhân, thực tập, hoặc đồ án) thể hiện kỹ năng phát triển frontend, ưu tiên nếu đã publish hoặc có mã nguồn trên GitHub. Ưu tiên: Có kinh nghiệm tích hợp API (REST, GraphQL). Hiểu biết về UI/UX và sử dụng công cụ thiết kế như Figma để phối hợp với đội ngũ thiết kế. Có kinh nghiệm viết unit test hoặc integration test để đảm bảo chất lượng mã nguồn. Có kinh nghiệm với cơ sở dữ liệu (SQL Server, hoặc NoSQL) là một lợi thế. Quyền lợi: Lương từ 20 – 50 triệu/tháng tùy kinh nghiệm và năng lực. Nâng cao kỹ năng chuyên sâu về React/React Native và cơ hội học hỏi Flutter để phát triển ứng dụng đa nền tảng. Phát triển lên các vị trí như Middle/Senior Frontend Developer hoặc chuyển hướng sang vai trò Full-stack Developer. Tham gia các dự án đa dạng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2717, 1227, 2, 'Salesforce Developer', 'We are seeking a Salesforce Developer to join our team to help design, build and maintain custom solutions on the Salesforce platform. The ideal candidate will have experience in developing complex solutions using Apex, Visualforce, LWC and Aura components. Your role & responsibilities:\nAnalyze business and map with standards Salesforce function.\nDevelop, implement, and maintain custom solutions on the Salesforce platform.\nDesign and build custom objects, fields, formulas, validation rules, workflows, and reports.\nWrite Apex classes, triggers, and Visualforce pages to support business requirements.\nDevelop and maintain integrations with external systems.\nCollaborate with the team to ensure solutions meet business requirements and are delivered on time.\nMentor and support junior team members as needed.\n\nYour skills & qualifications:\nMust Have:\nBachelor’s degree in computer science, Information Systems, Business administration or related field\n1+ years experience in Salesforce.\nGood written and verbal communication skills (English - IELT 6.5)\nNice to have:\nThe Salesforce Certified Platform Developer 1, Developer 2 is a plus.\nThe Salesforce Certified Administrator is a plus.\nExperience working on Salesforce application development, Salesforce Administrator, and experience related to SalesCloud CRM.\nExperience with Salesforce configuration and custom development\nExperience with REST and SOAP APIs\nGood understanding of Salesforce security model and data architecture\nExperience with ERP\nExperience working with Marketing Cloud is a plus.\nBe creative and good at user experiences.\nExcellent communication skills.\nA commitment to quality and a thorough approach to work.\nGood teamwork and reliability.\nDrive and enthusiasm with the ability to manage and co-ordinate multiple projects.\nStrong experience with Apex, Visualforce LWC or Aura components\nKnowledge of Agile software development methodologies\n\n• Competitive & attractive salary (up to 20M).\n• Working time:  8h30 – 17h30 from Mon to Friday\n• 13th, 14th, 15th - month salary, upgrading salary 1 times/year or when you have excellent achievement.\n• Profit bonus and Performance bonus plan.\n• Birthday party / Welcome party / Year-end party / Holidays.\n• Provide devices; monitors for working.\n• Team building activities including annual company trips, parties, and other attractive HR benefits.\n• Various training on trending technologies, best practices, and soft skills.\n• Supportive, fun and flexible work environment that values innovation, creativity and new ideas.\n• Enjoy the benefits of social insurance, health insurance and other benefits under the labor law.\n\n- Hà Nội: Tòa web3, Số 15 Ngõ 4 Duy Tân, Dịch Vọng Hậu, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2718, 1461, 2, 'Web Developer', 'Mô tả công việc:\n- Tìm hiểu phân tích yêu cầu người dùng, thiết kế giao diện web\n- Lập trình, xây dựng website\n- Tham gia lập trình và phát triển thiết kế chi tiết theo các thành phần chức năng\n- Tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu công nghệ công nghệ mới, đưa ra giải pháp áp dụng vào sản phẩm dịch vụ của công ty\n- Tham gia rà soát các yêu cầu thay đổi liên quan đến hoạt động kinh doanh của công ty\n- Tham gia vào quá trình phân tích và thiết kế hệ thống\n- Thu thập và xử lí các yêu cầu thiết kế và kĩ thuật;\n- Tối ưu và nâng cấp mã nguồn để cải tiến hiệu quả, tăng độ ổn định và bảo mật\n- Duy trì và phát triển các website, code và cấu trúc dữ liệu có sẵn của công ty\n- Hoàn thành các công việc khác được cấp trên giao\n- Hỗ trợ các công việc liên quan IT Helpdesk: Cài đặt và cấu hình phần cứng, phần mềm, mạng máy tính, line điện thoại, ứng dụng cho các end user. Lắp ráp, cài đặt các thiết bị máy tính, máy in, camera. Thực hiện sửa chữa các phần cứng kịp thời và nâng cấp phần cứng/mềm theo yêu cầu...\n\nYêu cầu ứng viên:\n- Có kinh nghiệm lập trình viết code, sử dụng thành thạo một trong các Front end & Back end Development, framework như Flask, Django, Big Data Dev ...\n- Có kinh nghiệm làm việc trên hệ điều hành Linux(Ubuntu), Window...\n- Có kiến thức lập trình OOP, design pattern.\n- Có hiểu biết về cơ sở dữ liệu và hệ thống: MySQL, MongoDB hay PostgreSQL – Biết sử dụng công cụ quản lý mã nguồn: Git, Jira, SVN...\n- Khả năng làm việc nhóm, giao tiếp tốt.\n- Kỹ năng giải quyết vấn đề nhanh chóng và hiệu quả.\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc các lĩnh vực liên quan.\n\nQuyền lợi:\n- Mức lương thỏa thuận được deal theo năng lực.\n- Tham gia các chế độ theo quy định của công ty và nhà nước: BHXH, BHYT, BHTN...\n- Lương tháng 13, thưởng theo hiệu quả làm việc.\n- Phụ cấp cơm trưa.\n- Được làm trong môi trường năng động và trẻ trung.\n\nĐịa điểm làm việc:\n- Đà Nẵng: Số 109 đường 30 tháng 4, Phường Hòa Cường Bắc, Hải Châu.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2719, 1462, 2, 'Back-End Developer', 'Mô tả công việc:\n- Thiết kế, phát triển, vận hành và tối ưu hệ thống Back-End phục vụ:\n  + Sản xuất (quản lý vật tư, nesting AI, CNC, ... )\n  + Kinh doanh (Shopify, Amazon, website, thương mại điện tử, đơn hàng, quảng cáo, marketing, ... )\n  + DVKH & CRM (chatbot AI, hệ thống phản hồi, CS automation, ... )\n  + Báo cáo dữ liệu & phân tích BI (Power BI, Dashboard nội bộ, ... )\n- Xây dựng kiến trúc hệ thống: đảm bảo khả năng mở rộng, ổn định, bảo mật và hiệu suất cao (API, Microservices, background jobs, real-time pipelines, ... ).\n- Tích hợp với hệ thống bên ngoài: Shopify API, Amazon API, CRM, dịch vụ đám mây, ... \n- Xây dựng, triển khai và vận hành CI/CD pipelines, logging, monitoring, alerting, fault-tolerant recovery, xử lý sự cố sản phẩm (production troubleshooting), ... \n- Tham gia phân tích yêu cầu nghiệp vụ từ các phòng ban (sản xuất, kinh doanh, marketing, AI, ... ) và hiện thực hóa bằng giải pháp kỹ thuật.\n- Phối hợp chặt chẽ với Front-End Developer, Data Engineer, AI Engineer, ... để xây dựng sản phẩm công nghệ hiệu quả, dễ mở rộng.\n- Làm việc trực tiếp với CTO & CEO để triển khai giải pháp toàn diện, thực chiến và có tác động thực tế.\n- Góp phần xây dựng tài liệu kỹ thuật, tiêu chuẩn codebase và văn hóa công nghệ nội bộ.\n- Làm các công việc khác theo yêu cầu từ cấp trên (nếu có).\n\nYêu cầu ứng viên:\n- Học vấn & nền tảng:\n  + Tốt nghiệp Đại học loại Khá – Giỏi trở lên, chuyên ngành CNTT, Khoa học máy tính, Kỹ thuật phần mềm, Toán – Tin hoặc các ngành liên quan.\n  + Ưu tiên có giải thưởng học thuật, học bổng, hoặc tham gia các cuộc thi về công nghệ (Olympic Toán – Tin học, Hackathon, Competition, ... ).\n- Kỹ năng & kinh nghiệm:\n  + Có tối thiểu 3 năm kinh nghiệm làm Back-End Developer.\n  + Thành thạo ít nhất một trong các ngôn ngữ sau: Node.js, C, C++, Python, Go, Java – ưu tiên Node.js & Python.\n  + Kiến thức vững chắc về: RESTful API, GraphQL APIs, Webhook, Microservices, Pub/Sub, Message Queue (RabbitMQ, Kafka), ... \n  + Thành thạo: PostgreSQL, MongoDB, Redis. Biết tối ưu query, schema, indexing.\n  + Thành thạo: FastAPI, Flask, Django, ... \n  + Triển khai thành thạo: CI/CD (GitHub Actions, GitLab CI, ... ), Docker, Git, môi trường Linux.\n  + Biết cách xử lý lỗi production, log tracing, performance tuning.\n  + Có kinh nghiệm thực tế với các nền tảng thương mại điện tử: Shopify, Amazon, ... \n  + Đã từng làm việc trong các dự án vừa – lớn, yêu cầu uptime cao.\n  + Có kiến thức hoặc từng làm việc cùng team AI, hiểu quy trình train/deploy AI models.\n  + Có GitHub nổi bật, blog kỹ thuật, dự án side project là điểm cộng.\n  + Chủ động, có trách nhiệm cao, tư duy phản biện, không chỉ “nhận task – làm task” mà còn đề xuất giải pháp – tối ưu hệ thống.\n  + Tư duy hệ thống, có khả năng thiết kế giải pháp toàn diện, phù hợp với bài toán thực tế doanh nghiệp.\n  + Giao tiếp rõ ràng, teamwork tốt, biết diễn đạt kỹ thuật theo ngôn ngữ kinh doanh.\n  + Thích nghi nhanh, chịu được môi trường thay đổi liên tục, không ổn định, chịu áp lực tốt, làm việc tốt trong môi trường startup – nơi chưa có sẵn mọi thứ.\n  + Biết cân bằng giữa “đúng kỹ thuật” và “đủ để vận hành hiệu quả”.\n  + Có tinh thần học hỏi, cầu thị, dám thử – dám sửa, sẵn sàng học công nghệ mới nếu cần.\n  + Có kỹ năng giải quyết vấn đề và tư duy logic tốt.\n  + Có khả năng tổ chức công việc và quản lý thời gian hiệu quả.\n\nQuyền lợi:\n- Lương cạnh tranh theo năng lực, có thưởng dự án rõ ràng.\n- Chế độ phúc lợi theo Luật lao động và chính sách của công ty.\n- Được tham gia đầy đủ BHXH theo quy định nhà nước và gói bảo hiểm sức khỏe cho nhân viên.\n- Du lịch hàng năm, các hoạt động nội bộ mỗi tháng.\n- Được giao nhiệm vụ trực tiếp từ CTO & CEO – tạo ảnh hưởng thật lên vận hành doanh nghiệp.\n- Tham gia các dự án AI, automation, thương mại điện tử, sản xuất thông minh.\n- Môi trường startup Mỹ – sáng tạo, chuyên nghiệp, minh bạch.\n- Làm việc từ xa hoặc tại văn phòng – linh hoạt theo năng lực.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 88 Nguyễn Gia Trí, Bình Thạnh.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 17:30).\n- Thứ 7 (từ 09:00 đến 12:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.\n', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2720, 1241, 2, 'Chuyên Viên Lập Trình', 'Mô tả công việc\n- Phát triển và tối ưu hóa giao diện người dùng bằng Angular\n- Phối hợp với Designer để đảm bảo UI/UX theo đúng bản vẽ thiết kế (Figma, Zeplin...)\n- Viết mã sạch, tối ưu, dễ bảo trì và có tính mở rộng cao\n- Phối hợp với Tester để fix bug và hoàn thiện chức năng\n- Tham gia code review, đóng góp ý kiến kỹ thuật và cải tiến UI/UX\n- Đảm bảo hiệu suất, bảo mật và tương thích trình duyệt / thiết bị\n\nYêu cầu ứng viên\n- Trình độ học vấn: Tốt nghiệp Đại học/ Cao đẳng chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Thiết kế phần mềm hoặc liên quan.\n- Kinh nghiệm: Tối thiểu 2 năm kinh nghiệm lập trình Frontend, trong đó ít nhất 1 năm sử dụng Angular.\n- Kiến thức:\n   - Thành thạo Angular (từ version 9 trở lên), hiểu rõ các concepts: component, module, service, routing, reactive forms, RxJS...\n   - Hiểu biết tốt về HTML5, CSS3, SASS/SCSS, JavaScript/TypeScript.\n   - Có kiến thức cơ bản về UI/UX, responsive web design, RESTful API.\n   - Ưu tiên biết thêm ReactJS, VueJS, hoặc framework frontend khác.\n   - Ưu tiên có kinh nghiệm làm việc với Git, CI/CD, quản lý source code.\n- Khả năng:\n   - Kỹ năng debug, tối ưu mã nguồn, tối ưu tốc độ tải trang.\n   - Kỹ năng đọc tài liệu kỹ thuật và phối hợp nhóm tốt.\n   - Khả năng tự học nhanh, nắm bắt công nghệ mới.\n   - Kỹ năng viết mã sạch, dễ maintain, tuân thủ guideline.\n- Yêu cầu khác:\n   - Ưu tiên ứng viên có sản phẩm demo / GitHub repo / đã từng làm dự án thực tế.\n   - Có khả năng sử dụng công cụ quản lý dự án: Jira, GitLab, hoặc tương đương.\n\nQuyền lợi\n- Chế độ đãi ngộ\n   - Mức lương: cạnh tranh hấp dẫn (sẵn sàng offer cao khi đủ năng lực) + Phụ cấp (Ăn ca: 700.000 VNĐ/tháng; Gửi xe: 120.000 VNĐ/tháng; trợ cấp máy tính cá nhân (nếu có): 300.000 VNĐ/tháng).\n   - Chính sách thưởng: Thưởng Lễ, Tết, sinh nhật + thưởng dự án + thưởng thâm niên + Lương tháng 13 + các thưởng khác theo quy định Công ty tại thời điểm hiện hành.\n   - Làm việc trong môi trường trẻ trung, năng động, coi trọng năng lực và khả năng sáng tạo.\n   - Thường xuyên tổ chức các hoạt động mini game, chương trình các ngày Lễ, Tết, sinh nhật, tham gia hoạt động Teambuilding của công ty.\n- Đào tạo – Phát triển\n   - Cơ hội tiếp cận và học hỏi công nghệ tiên tiến, công nghệ mới.\n   - Được công ty tạo điều kiện và hỗ trợ khi tham gia các khóa đào tạo, phát triển năng lực.\n   - Có cơ hội làm những việc thách thức, phát huy hết khả năng bản thân.\n   - Tham gia các sản phẩm công nghệ mới theo kế hoạch phát triển của công ty.\n- Chăm sóc sức khỏe, đời sống\n   - Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n   - Được tặng quà, thăm hỏi nhân các dịp: sinh nhật, cưới hỏi, hiếu hỉ, ốm đau...\n   - Có thể tham gia các câu lạc bộ thể thao: đá bóng, tập yoga, thể dục cải thiện sức khoẻ... \n\nĐịa điểm làm việc\nHà Nội: 97-99 Láng Hạ, Đống Đa\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 18:00)\nCheckin linh hoạt từ 7.30-9.00 am\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2721, 1463, 2, 'Senior Frontend Developer', 'Mô tả công việc:\n- Developing web-based applications (ReactJS, NextJs, Javascript pure- no library)\n- Develop and optimize front end UI to ensure the application is rendered consistently in cross-browser environments\n- Ensure UI/UX of developed pages and software with near pixel-perfect design;\n- Cooperate to connect front end software development with expert backend team\n- Solution consulting, designing, building to create optimal software products, in accordance with the needs of customers.\n- Work as assigned by the team leader / project manager, supporting team members to develop products.\n\nYêu cầu ứng viên:\n- Minimum 04 year experience working with React JS (Senior Level)\n- Proficient in JavaScript and deep understanding of how the browser works.\n- Build reusable components/modules for static websites with responsive design;\n- Excellent skills with HTML, CSS.\n- Friendly with bootstrap\n- Experience with: API, RESTFUL, JSON, XSS, CSRF, sync vs. async, promise2\n- Experience in debugging and optimizing code for application performance through the tools.\n- Teamwork skill\n\nQuyền lợi:\n- Our team members are awesome, fun, and most of all, super talented!\n- 13-month salary per year\n- Exposure to international design industry standards!\n- Bonus for birthday : 500K\n- Monthly company party.\n- Company trip.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tầng 3 Toà nhà RedHomes, B82 Bạch Đằng, Phường 2 Thành phố Hồ Chí Minh, Việt Nam, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2722, 1338, 2, 'Blockchain Developer', 'Mô tả công việc:\n- Phát triển và bảo trì giao diện người dùng (UI) cho các ứng dụng DeFi và Crypto trên nền tảng di động (iOS và Android), tích hợp với blockchain (Ethereum, Solana, v.v.).\n- Thiết kế và triển khai các tính năng frontend di động tương tác với smart contract (ví dụ: AMM, staking, lending, NFT).\n- Tối ưu hóa App Listing và App Store Optimization (ASO) cho ứng dụng di động trên App Store và Google Play, bao gồm metadata, từ khóa, hình ảnh và nội dung quảng bá.\n- Phối hợp với đội ngũ backend và blockchain để tích hợp API và dịch vụ on-chain vào ứng dụng di động.\n- Phân tích dữ liệu ASO (tỷ lệ tải, đánh giá, xếp hạng) và đề xuất cải tiến để tăng khả năng hiển thị ứng dụng trên các kho ứng dụng.\n- Đảm bảo giao diện di động thân thiện với người dùng, tuân thủ chính sách của App Store/Google Play và tối ưu hiệu suất trên các thiết bị di động.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm phát triển ứng dụng di động, ưu tiên trong các dự án blockchain/DeFi.\n- Thành thạo các ngôn ngữ và công cụ lập trình di động:\n  - Android: Kotlin, Java, C/C++ (NDK), Dart (Flutter là một lợi thế).\n  - iOS: Swift, Objective-C, React Native (JS) là một lợi thế.\n- Kinh nghiệm tích hợp frontend di động với blockchain qua Web3.js, Ethers.js, hoặc Solana Web3.js.\n- Hiểu biết về smart contract (Solidity, Rust) và các giao thức DeFi (Uniswap, Aave, v.v.).\n- Kiến thức về ASO, bao gồm tối ưu hóa từ khóa, mô tả ứng dụng, và phân tích hiệu suất qua các công cụ như App Annie, Sensor Tower.\n- Thành thạo công cụ phát triển di động: Xcode, Swift Package Manager, Android Studio.\n- Ưu tiên: Kinh nghiệm phát triển ứng dụng di động đa nền tảng (React Native, Flutter) và tích hợp blockchain trên mobile.\n- Có khả năng đọc hiểu tài liệu tiếng Anh.\n\nQuyền lợi:\n- Thu nhập cạnh tranh, thưởng dựa trên hiệu quả công việc.\n- Tham gia dự án blockchain thực chiến, ảnh hưởng trực tiếp đến thiết kế và vận hành ứng dụng di động.\n- Môi trường làm việc chuyên nghiệp, cởi mở, khuyến khích sáng tạo và đổi mới.\n- Cơ hội tiếp cận các công nghệ blockchain và công nghệ di động tiên tiến nhất.\n- Đồ ăn vặt, snack giữa giờ thoải mái; hoạt động gắn kết như ăn lẩu Haidilao hàng tháng.\n- Thời gian làm việc linh hoạt: 9h00 - 17h30 (Thứ 2 đến Thứ 6).\n- Công ty chi trả chi phí gửi xe tại tòa nhà.\n\nĐịa điểm làm việc:\n- Hà Nội: Cầu Giấy\n- Hà Nội: Thanh Xuân\n- Hà Nội: Nam Từ Liêm', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2723, 1254, 2, 'Trợ Lý Điều Hành Phát Triển Phần Mềm', 'Mô tả công việc\n• Theo dõi, cập nhật, tổng hợp và chịu trách nhiệm về số liệu sản xuất của toàn công ty, quản lý các dashboard thuộc phạm vi trách nhiệm của mình.\n• Điều phối việc lên kế hoạch sản xuất theo Sprint cho toàn công ty và đảm bảo điều kiện sản xuất cho các team.\n• Rà soát, đối soát và chịu trách nhiệm chốt số liệu nghiệm thu với khách hàng và ký kết các biên bản nghiệm thu.\n• Theo dõi, đôn đốc các nhóm sản xuất thực hiện đúng các lịch bàn giao cho khách hàng, cảnh báo các bộ phận liên quan nếu phát hiện trở ngại, rủi ro hoặc các thay đổi có thể gây ảnh hưởng tới cam kết với khách hàng.\n• Phân tích, báo cáo các dữ liệu về hiệu quả sản xuất (năng suất, sản lượng, lãi lỗ…), cảnh báo và đề xuất biện pháp nâng cao hiệu quả sản xuất, chủ trì thảo luận và triển khai các giải pháp cải tiến với các bên liên quan.\n• Sắp xếp, quản lý các lịch họp của các nhóm trong toàn công ty.\n• Tuân thủ các quy tắc và quy định an toàn thông tin, chịu trách nhiệm đảm bảo an toàn đối với các dữ liệu, thông tin được giao phụ trách.\n• Các công việc khác theo sự phân công của team lead.\n\nYêu cầu ứng viên\n• Tốt nghiệp đại học trở lên các chuyên ngành về Công nghệ thông tin hoặc Kinh tế, Quản trị kinh doanh, Ngoại thương, Luật.\n• Có kinh nghiệm làm việc trong ngành Công nghệ thông tin là lợi thế.\n• Kiến thức nền tảng về quản lý sản xuất.\n• Tổng hợp và phân tích số liệu.\n• Kỹ năng giao tiếp tốt.\n• Tư duy phản biện (critical thinking) và tư duy hệ thống (system thinking).\n• Có khả năng đa nhiệm, làm nhiều đầu việc, giao tiếp với nhiều đầu mối cùng lúc.\n• Có khả năng chịu được áp lực cao, có kỹ năng xử lý tình huống tốt.\n• Tiếng Anh nghe nói đọc viết.\n• Ưu tiên ứng viên đã từng làm việc theo mô hình Scrum.\n\nQuyền lợi\n• Mức lương thỏa thuận theo năng lực.\n• Thưởng quý, thưởng cuối năm (1-3 tháng lương).\n• Ngày phép hàng năm, ngày phép thâm niên, ngày phép tháng sinh nhật.\n• Đánh giá năng suất và xét tăng lương 1 lần/năm.\n• Tài trợ 100% phí thi các chứng chỉ quốc tế; phụ cấp chứng chỉ chuyên môn.\n• Được đào tạo, huấn luyện để có thể làm tốt công việc\n• Khám sức khỏe định kỳ; BHXH, nghỉ lễ theo quy định.\n• Tham gia vào các dự án hiệu năng cao, số lượng dữ liệu lớn và tập khách hàng lớn. Được làm việc trên các hệ thống lớn với các bài toán công nghệ phức tạp.\n• Tham gia vào nhóm phát triển Scrum tự chủ, linh hoạt và năng suất cao theo mô hình Agile/Scrum.\n• Môi trường làm việc trẻ, năng động, vui vẻ, hạnh phúc với các hoạt động văn hóa sôi động như retreat, picnic, team building, happy event, BiPlus radio, …\n• Được làm nhiều, được thử nhiều và được sai, học thực chiến trong công việc.\n• Liên tục phát triển năng lực thông qua các hoạt động học tập (company learning hour, team learning hour, club), đào tạo, mentoring, coaching,…\n• Được phản hồi thường xuyên liên tục và huấn luyện để phát triển năng lực và đạt hiệu suất công việc ngày càng cao (CFRs- Conversation – Feedback – Recognition tháng và 6 tháng).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2724, 209, 2, 'Java Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n• Develop, and implement scalable and efficient Backend solutions using Java and Spring Boot.\n• Collaborate with cross-functional teams to understand project requirements and translate them into Backend functionalities.\n• Optimize code, integrate design patterns, and ensure high performance, reliability, and security of Backend systems.\n• Work with relational databases, write efficient SQL queries, and maintain data models.\n• Implement RESTful APIs with authentication, error handling, and versioning.\n• Perform unit testing, code reviews, and maintain code quality.\n• Collaborate with Frontend developers to integrate Frontend components with Backend services.\n• Debug and resolve issues reported by users or identified through testing and monitoring.\n• Stay updated with emerging technologies and industry trends in Backend development.\n• Support system integration according to the data interface specification,\n• Support SIT, UAT, non-functional test, etc.\n• Prepare technical related materials for the architecture, security, service transition and PCQA\n• Performing requirement analyses.\n• Developing high-quality and detailed designs.\n• Conducting unit testing using automated unit test frameworks.\n• Identifying risk and conducting mitigation action planning.\n• Conducting configuration of your own work.\n• Reviewing the work of other developers and providing feedback.\n• Using coding standards and best practices to ensure quality.\n\nYêu cầu ứng viên\n• Strong experience in Backend development using Java and Spring Boot 7 years +\n• Proficiency in Hibernate or other ORM frameworks.\n• Familiarity with relational databases, writing efficient SQL queries, and optimizing database performance.\n• Knowledge of RESTful API design principles and advance.\n• Familiarity with unit testing, code reviews, and DevOps tools (e.g.: Git, Jenkins, Artifactory, SonarQube, Kubernetes and cluster management / administration etc.).\n• Excellent teamwork and communication skills to manage the team.\n• Problem-solving abilities and attention to detail.\n• Experience with cloud platforms and containerization technologies (AWS, Azure and Private Cloud).\n• API Gateways – AWS, Azure, APIGEE.\n• Familiarity with Agile development methodologies is preferred.\n• Develop and test the solution according to the system design and integration\n• Support SIT, UAT, integration test, non-functional test, etc.\n• Backend technical skills including Java, Springboot, Hibernate, SQL DB, Swagger, Light4J\n• Infrastructure orchestration and initialization scripts to automate creation of complex virtual environments\n\nQuyền lợi\n• FPT Care insurance plan tailored for FPT employees\n• Relocation Policy up to 100 Million VND for the candidate who is willing to relocate to Nha Trang City.\n• Attractive annual summer vacation allowance\n• Sponsored training courses for personal growth and up to 100% coverage for certification costs\n• Global and inclusive workplace with monthly cross-cultural events\n• International exposure and career growth across global locations\n• Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\n\nĐịa điểm làm việc\n- Khánh Hoà: VCN Tower, Số 2 Đường Tố Hữu, Khu đô thị Phước Hải, Thành phố Nha Trang, TP Nha Trang\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khánh Hoà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2725, 1448, 2, 'PHP Backend Developer', 'Mô tả công việc:\n- Phát triển, tối ưu và bảo trì các ứng dụng web sử dụng PHP & MySQL.\n- Thiết kế và xây dựng kiến trúc hệ thống hiệu suất cao, có khả năng mở rộng.\n- Phối hợp với các team khác (Frontend, DevOps, QA) để triển khai dự án.\n- Tối ưu truy vấn database, đảm bảo hiệu suất và bảo mật hệ thống.\n- Nghiên cứu và áp dụng công nghệ mới để cải thiện chất lượng sản phẩm. …\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Kinh nghiệm: Ít nhất 2 năm kinh nghiệm làm việc với PHP (Laravel/Symfony/CodeIgniter/Yii2 hoặc thuần PHP) và MySQL.\n- Có kinh nghiệm tham gia các dự án thực tế, từ giai đoạn phân tích đến triển khai.\n- Đã từng xây dựng hoặc tham gia phát triển hệ thống lớn, ứng dụng high-performance.\n- Kỹ năng chuyên môn: Thành thạo PHP, MySQL, RESTful API.\n- Hiểu biết về database optimization, indexing, caching (Redis/Memcached).\n- Có kiến thức về microservices, hệ thống phân tán là một lợi thế.\n- Quen thuộc với Docker, Git, CI/CD.\n- Khả năng phân tích, giải quyết vấn đề và làm việc độc lập. Ưu tiên: Làm việc thành thạo với framework Yii2 là 1 lợi thế.\n\nQuyền lợi:\n- Mức lương cạnh tranh theo đúng năng lực.\n- Môi trường làm việc thân thiện, năng động, có cơ hội phát triển bản thân và thăng tiến lên vị trí team leader, quản lý.\n- Cơ hội tiếp cận với các công nghệ mới, làm việc trong môi trường startup/công nghệ năng động\n- Ghi nhận thành tích, tăng lương và thưởng kịp thời.\n- Chế độ bảo hiểm đầy đủ, nghỉ phép theo quy định\n- Thưởng Lễ Tết, 30/4; 1/ 5; 2/9…. (theo tình hình hoạt động thực tế của Công ty)\n- Sinh nhật, ốm đau, sinh con, ma chay, hiếu hỉ theo mức quy định của Công ty.\n- Teambuilding, nghỉ mát….. (theo tình hình hoạt động thực tế của Công ty)\n- Được tham gia các khóa đào tạo do công ty tổ chức: kĩ năng mềm, nâng cao trình độ chuyên môn… \n\nĐịa điểm làm việc:\n- Hà Nội: 34 Nguyễn Khánh Toàn, Quan Hoa, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Thứ 7 làm việc luân phiên theo tuần\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2726, 237, 2, 'Lập Trình Viên NodeJS - Từ 2 Năm Kinh Nghiệm', 'Mô tả công việc:\n- Tham gia lập trình, vận hành, tối ưu các sản phẩm của công ty.\n- Thiết kế và triển khai các ứng dụng Web động bằng các ngôn ngữ lập trình như Java, Javascript...\n- Tối ưu hóa hiệu suất và bảo mật của các ứng dụng Web.\n- Xác định và giải quyết các vấn đề liên quan đến ứng dụng Web.\n- Tham gia vào các quá trình kiểm soát chất lượng cho sản phẩm.\n- Các công việc khác theo sự phân công của Quản lý trực tiếp.\n- Chi tiết trao đổi qua cuộc phỏng vấn.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành CNTT\n- Kinh nghiệm tối thiểu 02 năm ở vị trí tương đương.\n- Thành thạo quy trình phát triển phần mềm, từ tiếp nhận yêu cầu, lựa chọn công cụ, ngôn ngữ, thiết kế CSDL, xây dựng frontend, backend, triển khai lên hệ thống server thật.\n- Thành thạo ngôn ngữ lập trình Javascript, CSS, HTML và một framework xây dựng frontend như ReactJS hoặc Angular, biết cách xây dựng website responsive chạy trên mobile.\n- Thành thạo một framework xây dựng backend như NodeJS Express, ngôn ngữ SQL, biết cách sử dụng ORM và vận hành hệ quản trị CSDL như MySQL hoặc Postgres.\n- Biết sử dụng các API và thiết kế API để tương tác với các dịch vụ của khách hàng.\n- Biết đọc tài liệu bằng tiếng anh.\n- Biết phát triển ứng dụng mobile (ReactNative) là một lợi thế.\n\nQuyền lợi:\n- Thu nhập: thỏa thuận.\n- Thời gian làm việc: Nghỉ chiều thứ Bảy và các ngày Chủ nhật trong tuần\n  + Sáng: từ 8h30 – 12h00.\n  + Chiều: từ 13h30 – 18h00.\n- Nghỉ phép năm, chế độ BHXH, BHYT, BHTN theo quy định của nhà nước.\n- Thưởng Lễ, Tết, du lịch hàng năm.\n- Môi trường làm việc trẻ và năng động, tôn trọng phát triển cá nhân, công bằng và luôn khuyến khích sáng tạo để phát huy tối đa năng lực.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 5, tòa nhà SanNam, 78 Duy Tân, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Thứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2727, 1464, 2, 'Kỹ Sư Phần Mềm', 'Mô tả công việc\n- Hoàn thành quản lý lập kế hoạch, lập trình, thử nghiệm và gỡ lỗi phần mềm theo yêu cầu của kế hoạch dự án\n- Hiểu rõ ngôn ngữ lập trình C# và python, hiểu rõ quy trình thử nghiệm 3C và phát triển phần mềm tự động, đồng thời thành thạo các giao thức phần cứng khác nhau\n- Hiểu biết các giao thức điều khiển như mqtt, TCP/IP, modbus TCP, điều khiển cổng nối tiếp, v.v\n- Hiểu biết các công cụ quản lý mã như GIT\n- Sẵn sàng đi công tác trong và ngoài nước để thiết lập các dự án tự động hóa, dây chuyền thủ công tại các nhà máy OEM\n\nYêu cầu ứng viên\n- 3 năm kinh nghiệm trở lên;\n- Các chuyên ngành liên quan đến phần mềm;\n- Tiếng Trung nghe nói thành thạo, đọc viết cơ bản;\n- Hoặc Tiếng Anh giao tiếp tốt;\n\nQuyền lợi\n- Đóng bảo hiểm ngay tháng đầu tiên vào làm\n- Trong thời gian thử việc được hưởng 100% mức lương, sau thử việc sẽ cộng thêm hiệu suất công việc\n- Có cơ hội đi công tác nước ngoài: Trung Quốc, Ấn Độ,...\n\nĐịa điểm làm việc\n- Bắc Ninh: KCN Yên Phong II-C, Yên Phong\n- Vĩnh Phúc: KCN Bá Hiến, Bình Xuyên\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh, Vĩnh Phúc', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2728, 1465, 2, 'Lập Trình Viên Java', 'Trung tâm Công nghệ thông tin thuộc Viettel Construction tuyển dụng Dev Lead Java (Middle → Leader/PM) phụ trách các phần mềm nội bộ domain ERP, HRM, Kinh doanh, ... Công ty Product, Không yêu cầu Tiếng Anh, Phỏng vấn 1 vòng duy nhất, Cụ thể như sau:\n- Lập trình trong các dự án phần mềm sử dụng ngôn ngữ Java trong tổng công ty, bao gồm các sản phẩm phục vụ quản lý điều hành kinh doanh, quản lý bán hàng, chăm sóc khách hàng và quản trị doanh nghiệp (ERP)\n- Thiết kế tổng thể, thiết kế chi tiết (màn hình, api, cơ sở dữ liệu, luồng dữ liệu...) các module chức năng của phần mềm để đảm bảo các tiêu chức năng và phi chức năng (như đáp ứng hiệu năng, tính mở rộng..)\n- Chịu trách nhiệm triển khai và hỗ trợ sau triển khai các phần mềm. Xử lý phản ánh người dùng cuối và sửa các lỗi về tính năng, hiệu năng, kiến trúc của phần mềm.\n- Quản lý nhóm lập trình của một hoặc nhiều sản phẩm, chịu trách nhiệm giao việc, quản lý tiến độ chất lượng công việc của nhóm, báo cáo lên trưởng phòng hoặc ban giám đốc trung tâm. Đào tạo để nâng cao chất lượng nhóm. Nghiên cứu và phát triển công nghệ mới giúp tăng hiệu suất cho dự án.\n\nYêu cầu ứng viên:\n- Độ tuổi tuyển dụng: Dưới 32 tuổi\n- Đã tốt nghiệp Đại học chính quy trở lên chuyên ngành Công nghệ thông tin, hệ thống thông tin, Khoa học máy hoặc ngành liên quan;\n- Có từ 3 năm kinh nghiệm trở lên với các nền tảng và framework công nghệ Java.\n- Nắm vững các kiến thức cơ bản về lập trình hướng đối tượng, lập trình Java core (multithreading, Collection...) /Java web (J2EE, ORM, Caching...)\n- Có kinh nghiệm thành thạo sử dụng một trong các framework/stack về java đang triển khai tại TCT như sau:\n+ Framework: Spring-boot, Spring MVC, Angular, Các web framework java phổ biến khác\n+ Midware: Kafka, Redis, CEP, BPMN engine...\n+ Cơ sở dữ liệu: Oracle, Postgresql, MariaDB, NoSQL\n\nQuyền lợi:\n- Lương cứng tháng : 20.000.000 - 32.000.000 đồng/ tháng theo từng level và kinh nghiệm. Thử việc 100% Lương\n- Có phụ cấp ăn trưa điện thoại 930.000/tháng\n- 14 Tháng lương/năm ( Thưởng tháng lương T13, T14)\n-  Gói Thưởng các ngày lễ tết dành riêng cho người Viettel: 38.000.000 đồng/năm\n- Nghỉ phép 15 ngày/năm\n- Thời gian làm việc: làm từ T2 - T6 + 1 ngày T7 của tuần đầu tiên của tháng.\n- Được ký hợp đồng lao động và tham gia các loại bảo hiểm theo quy định của Nhà nước.\n- Được đào tạo tại công ty hoặc tham gia các khóa đào tạo nâng cao, bổ ích bên ngoài.\n- Tham gia nhiều hoạt động văn hóa, thể dục, thể thao, giải trí.\n- Chính sách du lịch, nghỉ dưỡng, khám sức khỏe định kỳ cho CBNV.\n\n"Viettel Construction tuyệt đối không thu bất cứ khoản tiền nào của ứng viên khi nộp hồ sơ, tham gia dự tuyển và khi vào làm việc tại Viettel Construction nếu trúng tuyển"\n"Khi ứng tuyển vào Viettel Construction, ứng viên phải cam kết các hồ sơ cá nhân cung cấp như Bằng cấp, Chứng chỉ hành nghề... thông tin thật. Trường hợp rà soát phát hiện ứng viên sử dụng hồ sơ giả sẽ xử lý theo Quy định của Pháp luật" \n\nĐịa điểm làm việc:\n- Hà Nội: Viettel Construction tầng 5 tháp B tòa nhà Central Point, số 219 Trung Kính, Trung Hòa, Cầu Giấy\n\nThời gian làm việc:\n- Từ 8h-17h30 các ngày T2 - T6 + 1 ngày T7 đầu tiên của tháng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2729, 1466, 2, 'Kỹ Sư Vận Hành Máy', 'Mô tả công việc:\n- Xây dựng bản vẽ, quy trình công nghệ để gia công chi tiết.\n- Tối ưu quy trình công nghệ, đạt hiệu quả gia công về thời gian, chất lượng, tối ưu dụng cụ cắt gọt.\n- Thực hiện lập trình & xuất chương trình và gia công.\n- Điều chỉnh, sửa chương trình ngay khi phát hiện sự cố, đảm bảo thời gian chạy máy CNC.\n- Định mức thời gian hoàn thành mỗi công đoạn gia công: Phay\n- Thực hiện các công việc khác khi được cấp trên yêu cầu.\n\nYêu cầu ứng viên:\n- Tốt nghiệp trung cấp trở lên, nhanh nhẹn, nhiệt tình trong công việc;\n- Đọc tốt bản vẽ kỹ thuật, Lập trình 2D+3D. Sử dụng thành thạo phần mềm CAD/CAM.\n- Có kinh nghiệm ít nhất 1 năm về thiết kế, lập trình máy CNC; 1 năm vận hành máy CNC.\n- Có đam mê với nghề kỹ thuật.\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, Hass.\n\nQuyền lợi:\n- Có cơ hội phát triển nghề nghiệp tại công ty.\n- Làm việc trong môi trường năng động, chuyên nghiệp;\n- Cung cấp đồng phục, trang thiết bị đầy đủ để phục vụ công việc;\n- Thưởng các dịp Quốc tế Lao động 1/5, Quốc khánh 2/9, Tết dương lịch, Thưởng Tết theo quy định của công ty.\n- Được đóng đẩy đủ BHXH, BHYT, BHTN;\n- Đi du lịch nghỉ mát hàng năm;\n- Tham gia các hoạt động văn hoá thể thao (bóng đá, chạy...).\n\nĐịa điểm làm việc:\n- Thanh Hoá: Quế Sơn, Thọ Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thanh Hoá', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2730, 1378, 2, 'Lead Mobile App', 'Mô tả công việc\n- Lead the development of high-quality, impactful, and scalable products and systems to achieve business goals.\n- Collaborate closely with engineering managers and engineers across multiple platforms and domains.\n- Support to recruit, develop, and retain exceptional engineering talent who excel in innovative, user-focused, fast-paced environments.\n- Establish and maintain high engineering standards for your team regarding quality practices, delivery speed, architecture, design, and code quality, with clear measurable goals.\n- Contribute to the improvement and scaling of the engineering organization by mentoring engineers, sharing technical knowledge, industry best practices, and leadership skills.\n\nTech stacks\n1. Requirement for Android :\n- Kotlin, Java programming languages\n- MVVM architecture pattern\n- Coroutines for asynchronous programming\n- HTTP client implementation\n- Compose UI framework\n- Unit testing and UI testing\n- Google Play Store policy compliance\n2. Requirement for iOS :\n- Swift programming language\n- MVVM architecture pattern\n- HTTP client implementation\n- SwiftUI framework\n- Unit testing and UI testing\n- Apple App Store policy compliance\n\nYêu cầu ứng viên\n- Bachelor\'s degree or higher in Computer Science or related field.\n- Familiarity with mobile frameworks.\n- Familiarity with Swift/Objective-C; Kotlin/Java.\n- Familiarity with version control tools (e.g., Git).\n- Good understanding of web standards and best practice.\n- Has team collaboration awareness, able to work cooperatively with team members. Experience in Scrum is a plus.\n- Good communication skills and logical thinking/judgment abilities.\n- Proactive and self-motivated to learn.\n- Possesses or is willing to learn multiple languages (including Chinese, English, Vietnamese) to effectively communicate with the team.\n\nQuyền lợi\n- 13-month salary\n- Full social benefits in accordance with the company and the Vietnam Law\n- Premium health care & accident insurance\n- Friendly working environment with strong startup culture\n- Team building, Company trip, Year-end party, etc.\n- 40 flexible working hours per week from Monday to Friday\n- Salary review at least once a year based on employee\'s performance and contribution.\n\nĐịa điểm làm việc\n- Hồ Chí Minh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm \'Ứng tuyển\' ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2731, 1467, 2, 'COBOL Developer Intern', 'Mô tả công việc\nVới định hướng đào tạo nhân sự trẻ, giúp các bạn trẻ có cơ hội phát triển bản thân, SSV đang cần 2 bạn COBOL Developer Intern với các nhiệm vụ:\n● Tham gia và hoàn thành khóa training của công ty (Thời gian 3 tháng trở lên)\n● Tham gia/ học hỏi kinh nghiệm từ các dự án thực tế của công ty (Thời gian 3 tháng trở lên)\n\nYêu cầu ứng viên\n- Sinh viên năm 3 hoặc năm 4, Không yêu cầu đúng chuyên ngành\n- Có hứng thú với lĩnh vực CNTT và nghiệp vụ trong các ngành: Bảo hiểm, Ngân hàng, Chứng khoán.\n- Tinh thần học hỏi cao, chủ động và tích cực trong công việc.\n- Kỹ năng làm việc độc lập tốt, đồng thời phối hợp hiệu quả trong làm việc nhóm.\n- Yêu thích việc học lập trình và phát triển tư duy logic.\n- Có chứng chỉ tiếng Nhật hoặc trình độ tương đương trở lên.\n- Có những điểm sau là lợi thế:\n  - Có khả năng tạo lập tài liệu & thuyết trình\n  - Có hiểu biết hoặc kinh nghiệm về Software Development\n\nQuyền lợi\n- Môi trường làm việc công ty startup trẻ trung, vui vẻ, hòa đồng, thân thiện, được tiếp cận với quy trình làm việc chuyên nghiệp và lộ trình thăng tiến rõ ràng.\n- Trợ cấp ăn trưa và đi lại 150.000VNĐ/ngày trở lên.\n- Sau khi kết thúc thời gian thực tập sẽ có cơ hội thành nhân viên thử việc (Mức lương 3.000.000 – 6.000.000 VNĐ/tháng). Hoặc nhân viên hợp đồng (Lương thỏa thuận).\n- Được đào tạo từ đầu về ngôn ngữ COBOL, quy trình phát triển phần mềm.\n- Được tiếp xúc với nghiệp vụ hệ thống chuyên ngành (Ví dụ: ngân hàng, bảo hiểm, tài chính,...).\n- Được tham gia các hoạt động văn hóa đoàn thể trong năm: Nghỉ mát, teambuilding, thể thao.\n- Tham gia các buổi Seminar chia sẻ về kỹ năng & kiến thức từ các thành viên trong công ty.\n\nĐịa điểm làm việc\n- Thanh Hoá: Tầng 2, Louis Apartment Tower, số 30 Lê Lợi, Đông Hương, Thanh Hoá, Việt Nam, TP Thanh Hoá\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Công ty áp dụng chế độ làm việc linh hoạt Core time.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thanh Hoá', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2732, 1468, 2, 'Nhân Viên Lập Trình & Vận Hành Máy Phay', 'Mô tả công việc\n- Vận hành thành thạo máy phay CNC, hệ điều hành Fanuc, gia công chi tiết, đo, kiểm tra chi tiết sản phẩm làm ra.\n- Lập trình chương trình cho máy chạy.\n- Biết gá sản phẩm, lấy gốc\n- Biết thay dao khi xảy ra sự cố\n- Biết đọc bản vẽ gia công\n- Đảm bảo các yêu cầu kỹ thuật theo bản vẽ gia công của khách hàng\n- Phối hợp với các bộ phận khác như laser, hàn để hoàn thiện sản phẩm\n- Đề xuất dao cụ và phụ kiện đi kèm phù hợp\n- Các công việc khác theo sự phân công của quản lý trực tiếp\n\nYêu cầu ứng viên\n- Tuổi từ 25 – 40 tuổi.\n- Có kinh nghiệm từ 3 năm trở lên về lập trình và vận hành máy phay cnc trong lĩnh vực cơ khí.\n- Tốt nghiệp từ trung cấp, cao đẳng nghề công nghiệp chuyên ngành về cơ khí chế tạo.\n- Có sức khỏe tốt, trung thực, có tinh thần trách nhiệm\n- Chăm chỉ, chịu khó, ham học hỏi, chịu được áp lực cao trong công việc.\n\nQuyền lợi\n- Mức lương từ 13- 15 triệu /tháng.\n- Thưởng các ngày lễ ,tết,sinh nhật... theo qui định của công ty.\n- Luôn có cơ hội thăng tiến trong công việc nghề nghiệp.\n- Được cung cấp trang thiết bị đầy đủ để phục vụ công việc.\n- Nhân viên có năng lực tốt có thể ký hợp đồng chính thức khi chưa hết thời gian thử việc.\n- Môi trường làm việc thân thiện, năng động.\n- Tăng lương theo hiệu quả công tác và cam kết đầy đủ các chế độ dành cho người lao động theo như quy định pháp luật hiện hành (BHYT, BHXH, BHTN...).\n- Được tham gia các hoạt động ngoại khóa: văn nghệ, du lịch, thể thao của Công ty.\n\nĐịa điểm làm việc\n- Bắc Ninh: Lô I7-4-2B KCN Đại Đồng – Hoàn Sơn, Phường Tân Hồng, Từ Sơn.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2733, 72, 2, 'Android Developer Leader', '✓ Phát triển, duy trì và cải tiến mã nguồn Kotlin dùng chung cho cả nền tảng Android và IOS, đảm bảo tích hợp mượt và hiệu quả trên cả hai hệ sinh thái. Thực hiện đánh giá kỹ lưỡng mã nguồn để đảm bảo chất lượng và triển khai hiệu quả với Kotlin Multiplatform, tuân thủ các phương pháp tốt nhất về tính duy trì và khả năng mở rộng.\n✓ Tối ưu hóa mã Kotlin dùng chung, tận dụng thế mạnh riêng của từng nền tảng và duy trì mã nguồn thống nhất.\n✓ Tham gia phát triển dự án về Camera trên đa nền tảng Mobile.\n✓ Tích hợp các cổng thanh toán thông qua (SDK/API bên thứ 3).\n✓ Tích hợp DRM, Watermarking.\n✓ Kiến trúc, review code, tối ưu để tăng trải nghiệm.\n✓ Phân tích, đánh giá, lập kế hoạch phát triển, trao đổi nhóm để đưa ra nhiệm vụ cần thực thi liên quan.\n✓ Cập nhật xu hướng phát triển công nghệ mới để áp dụng vào dự án.\n✓ Làm các dự án khác theo sự phân công của quản lý đơn vị.\n\nYêu cầu ứng viên:\n✓ Tốt nghiệp đại học chuyên ngành CNTT loại khá trở lên.\n✓ Tối thiểu 3 năm kinh nghiệm phát triển Android với Kotlin và có kinh nghiệm với Swift/Objective-C trong phát triển IOS là một lợi thế.\n✓ Thành thạo Jetpack Compose, Coroutines và Flow.\n✓ Kỹ năng làm việc nhóm và giải quyết vấn đề tốt.\n✓ Ưu tiên:\n✓ Biết Swift/Objective C hoặc từng làm việc với ứng dụng native iOS.\n✓ Có kinh nghiệm tích hợp Google Maps, Mapbox, multimedia (audio/video), hoặc WebRTC.\n✓ Kinh nghiệm kết nối và xử lý dữ liệu với các thiết bị IoT qua BLE hoặc WiFi.\n✓ Hiểu và áp dụng tốt Material Design, custom layout.\n✓ Từng tham gia dự án theo mô hình Agile/Scrum thực tế.\n✓ Kỹ năng mềm: lãnh đạo nhóm, giao tiếp, làm việc nhóm, giải quyết vấn đề.\n\nQuyền lợi:\n✓ Gói thu nhập cạnh tranh.\n✓  Đầy đủ các chế độ theo luật lao động hiện hành.\n✓ Chính sách phúc lợi theo quy định của Công ty đa dạng: Chăm sóc sức khỏe định kì hàng năm; Gói bảo hiểm sức khỏe chuyên biệt (FPT Care – Khám chữa bệnh miễn phí tại tất cả các bệnh viện); Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân ...\n✓ Môi trường làm việc thân thiện, cởi mở.\n✓ Cơ sở vật chất và công cụ làm việc hiện đại, tiện nghi.\n✓ ​Nhiều cơ hội phát triển và thăng tiến.\n✓ Văn hóa Doanh nghiệp đặc sắc, sinh động bậc nhất với nhiều các hoạt động hấp dẫn: tân binh, teambuilding, thi trạng, hội làng, hội diễn Sao Chổi, sinh nhật FPT, ngày 08/03, ngày 11/11...\n✓ Hưởng các gói ưu đãi cước khi sử dụng dịch vụ của FPT Telecom.\n\nGhi chú: FPT Telecom không thu bất kỳ chi phí nào của Ứng viên, Sinh viên trong quá trình tuyển dụng, thực tập.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2734, 1469, 2, 'Trưởng Nhóm Lập Trình', 'Mô tả công việc\n- Lên giải pháp, danh mục vật tư các thiết bị điện, lập bản vẽ đấu nối điện layout thiết bị, sử dụng phần mềm Eplan và Cad.\n- Lập trình PLC, HMI, Lập trình Robot 2-4-6 trục (Mitsubishi, Keyence, Omron, ABB, UR robot ...) và các thiết bị tự động hóa để điều khiển máy móc trong công nghiệp.\n- Lập trình điều khiển step motor, servo motor, Inverter và các thiết bị chuyển đổi Analog-Digital, các loại cảm biến và khí nén thủy lực...\n- Lập trình truyền thông công nghiệp RS485, RS232, Ethernet TCP/IP, Modbus,...\n- Lập trình xử lý ảnh, AI deep learning cho các ứng dụng kiểm tra lỗi sản phẩm, đọc mã vạch QR, Datamatrix, Barcode ... , nhận diện kí tự và tích hợp với robot để định vị trí sản phẩm để robot gắp đặt.\n- Setup Camera Vision , lựa chọn camera, lens, đèn phù hợp để thu được hình ảnh tốt nhất và lên cấu hình vision cho từng bài toán.\n- Lập trình thiết kế phần mềm máy tính, visual studio C++, C#, SQLServer,...\n- Lập trình quản lý hệ thống nhà máy, server truyền thông công nghiệp, lưu trữ truy xuất dữ liệu\n\n- Lập kế hoạch dự án, sắp xếp công việc cho các thành viên trong nhóm, quản lý chặt tiến độ dự án\n- Đào tạo kỹ năng khảo sát, hướng dẫn thiết kế, lắp ráp chế tạo máy và xử lý sự cố cho các thành viên\n- Giám sát, kiểm tra và chịu trách nhiệm chính về giải pháp 3D, bản vẽ 2D, bản vẽ điện, gia công, báo cáo kế hoạch, các vấn đề kỹ thuật, các vấn đề phát sinh cho từng dự án\n- Tính toán đánh giá rủi ro về thiết kế, chế tạo, triển khai cho từng dự án\n- Trao đổi công việc với các bộ phận liên quan, đối tác, khách hàng trong quá trình triển khai\n\nYêu cầu ứng viên\n- Có kinh nghiệm trực tiếp thiết kế máy tự động hóa cho các Công ty làm máy hoặc Công ty FDI (ngành điện, điện tử, bán dẫn...), đặc biệt các máy yêu cầu độ chính xác cao (kết hợp robot, thiết bị đo kiểm, lắp ráp...)\n- Thành thạo lập trình các dòng PLC Mitsubishi, Keyence. Điều khiển các thiết bị công nghiệp.\n- Thành thạo sử dụng Biến tần, Servo và các thiết bị điều khiển động cơ khác.\n- Hiểu biết về các loại truyền thông công nghiệp..\n- Ưu tiên biết lập trình Vision: Python, C++ trên nền tảng ROS. Các ứng dụng liên quan tới Web-Base, Database, IOT.\n- Có kinh nghiệm quản lý nhóm, quản lý chất lượng, tiến độ dự án là một lợi thế.\n\nQuyền lợi\n- Mức lương cạnh tranh, phù hợp với năng lực và kinh nghiệm\n- Được đóng BHXH, BHYT, BHTN theo quy định của nhà nước\n- Thưởng các ngày lễ, Tết và thưởng theo hiệu quả công việc\n- Được đào tạo và phát triển kỹ năng chuyên môn\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội thăng tiến rõ ràng\n- Được tham gia các hoạt động team building, du lịch hàng năm\n\nĐịa điểm làm việc\n- Hà Nội: 11TT16 Foresa 8, Xuân Phương, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Làm việc 2 thứ 7/ tháng\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2735, 1137, 2, 'Frontend Developer (Nextjs) Level Middle/Senior', 'Mô tả công việc\n- Phát triển, tối ưu hóa và duy trì các ứng dụng web chất lượng cao, thân thiện với nhiều thiết bị sử dụng NextJS;\n- Hợp tác với các lập trình viên backend, thiết kế UI/UX và các thành viên khác trong nhóm để đảm bảo quy trình phát triển hiệu quả và liền mạch;\n- Áp dụng các phương pháp phát triển web hiện đại, đảm bảo tính mở rộng, hiệu năng và bảo mật;\n- Xây dựng các thành phần và thư viện giao diện có thể tái sử dụng cho các dự án trong tương lai;\n- Gỡ lỗi và khắc phục các điểm nghẽn về hiệu suất, đảm bảo tính năng hoạt động mượt mà trên nhiều trình duyệt và thiết bị;\n- Luôn cập nhật các xu hướng, công nghệ và thực hành tốt nhất trong lĩnh vực phát triển front-end;\n- Đóng góp ý tưởng và giải pháp nhằm cải thiện tính năng sản phẩm và trải nghiệm người dùng.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học chuyên ngành công nghệ thông tin, khoa học máy tính hoặc các ngành có liên quan;\n- Có từ 3 – 5 năm kinh nghiệm làm việc với ReactJS/NextJS;\n- Thành thạo HTML5, CSS3, JavaScript (ES6+) và TypeScript;\n- Hiểu rõ kiến trúc dựa trên component và các phương pháp quản lý trạng thái (ví dụ: Redux, Context API, Zustand,...);\n- Có kinh nghiệm thiết kế giao diện responsive và xây dựng ứng dụng tương thích đa trình duyệt;\n- Quen thuộc với kỹ thuật render phía máy chủ (SSR) và tạo trang tĩnh (SSG) trong NextJS;\n- Am hiểu về RESTful APIs và tích hợp API vào ứng dụng front-end;\n- Sử dụng thành thạo Git hoặc các hệ thống quản lý phiên bản khác;\n- Kỹ năng phân tích và giải quyết vấn đề tốt;\n- Kỹ năng giao tiếp và khả năng làm việc nhóm tốt;\n- Tự chủ trong công việc và có khả năng làm việc độc lập.\n\nQuyền lợi\n- Mức lương (gross): lên đến 30 triệu hoặc lên đến 40 triệu đối với level Senior (thoả thuận khi phỏng vấn);\n- Thưởng tháng 13, thưởng thâm niên, thưởng hàng quý, thưởng chia lợi nhuận;\n- 12 ngày nghỉ phép năm;\n- Xét tăng lương theo hiệu suất vào tháng 6 và tháng 12;\n- Thưởng các dịp lễ như 30/4 - 1/5, 2/9, Tết Dương lịch,...;\n- Tổ chức sinh nhật, tặng quà vào các dịp như Tết Nguyên Đán, Quốc tế Phụ nữ (8/3, 20/10), Trung Thu, Tết Thiếu nhi (1/6), và nhiều dịp khác;\n- Miễn phí trà, đồ ăn nhẹ, cà phê tại văn phòng; hỗ trợ phí gửi xe;\n- Được trang bị đầy đủ thiết bị và công cụ phục vụ công việc hiệu quả;\n- Tham gia vào các hoạt động sôi nổi của công ty: tiệc hàng quý, du lịch thường niên, team building/cắm trại hàng quý, tiệc tất niên và nhiều hoạt động khác.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa MD Complex, 68 Nguyễn Cơ Thạch, Mỹ Đình 1, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2736, 1411, 2, 'Thực Tập Sinh (PHP)', 'Lịch phỏng vấn dự kiến: Từ ngày 01/07/2025 trở đi\nQuy trình tuyển dụng: Test chuyên môn => Phỏng vấn trực tiếp.\nNội dung công việc:\n- Tuỳ theo nhu cầu dự án tại từng thời điểm hiện tại, công ty sẽ đào tạo những ngôn ngữ lập trình khác nhau và các kỹ thuật mới nhất, cụ thể như:\n+ Ngôn ngữ lập trình PHP với các framework phiên bản mới nhất.\n+ Kỹ thuật về OOP, PHP Basic, Database, ...\n+ Frontend và các framework như Vuejs, Reactjs, ...\n- Nắm bắt nghiệp vụ phân tích để phát triển hệ thống trên nền web cùng với các kỹ sư tại Việt Nam và tại Nhật Bản.\n\nYêu cầu ứng viên\n- Sinh viên đang học năm cuối các ngành Khoa học máy tính, Công nghệ phần mềm tại các trường Đại Học và có kết quả học tập loại khá trở lên.\n- Có thể tham gia thực tập tại công ty từ 6 – 10 buổi / tuần ( tương đương 3 – 5 ngày/ tuần).\n- Có hiểu biết hoặc đã tìm hiểu về lập trình website mà có sử dụng một trong các ngôn ngữ lập trình PHP, Java, .Net (C#,VB.NET), NodeJS.\n- Nắm vững kiến thức về SQL Query.\n- Giao tiếp tốt, chủ động trong công việc.\n- Có đam mê phát triển phần mềm.\n- Có kỹ năng làm việc theo nhóm, hòa đồng.\n- Có tư duy logic, sáng tạo.\n\nLợi thế:\n- Có kiến thức về:\n+ PHP, MySQL.\n+ PHP Framework: (CodeIgniter, Laravel, ...).\n+ Javascript và JS Framework (VueJS, ReactJS...).\n- Hoặc đã từng thực tập tại các Công ty phần mềm và thực hiện dự án thực tế về ngôn ngữ PHP và các framework của PHP.\n\nQuyền lợi\n- Công ty sẽ quyết định ký HĐLĐ nếu đánh giá sinh viên đủ năng lực sau thời gian thực tập 2 tháng. Sinh viên sẽ trở thành nhân viên chính thức (BHXH full lương) không qua thử việc và không yêu cầu làm fulltime.\n- Sinh viên sau khi trở thành nhân viên chính thức có thể đi làm từ 3 ngày trở lên trong tuần cho đến khi chính thức tốt nghiệp.\n- Mức trợ cấp thực tập tại công ty: 100,000VND/ngày (sinh viên làm 0.5 ngày cũng được làm tròn thành 1 ngày).\n- Bữa trưa chào mừng nhân viên mới.\n- Thời gian thực tập linh động phù hợp với lịch học của sinh viên.\n- Được tham gia vào dự án phần mềm thực tế cùng các kỹ sư có kinh nghiệm và chuyên môn cao.\n- Môi trường làm việc chuyên nghiệp, với những người trẻ đầy nhiệt huyết, năng động.\n- Biểu dương cho sinh viên đạt được thành tích ưu tú trong quá trình thực tập.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Lầu 12, An Phú Plaza 117-119 Lý Chính Thắng, Phường Võ Thị Sáu, Quận 3\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Internship', '2025-10-07 20:59:18.149534'),
	(2737, 1470, 2, 'Lập Trình Viên', '• Tham gia vào các dự án phát triển sản phẩm của công ty, chỉnh sửa theo yêu cầu đặc thù của khách hàng\n• Làm việc, phối hợp với team để phát triển phần mềm chất lượng cao\n• Áp dụng các kiến thức chuyên môn của mình để giải quyết các vấn đề và đảm bảo tiến độ dự án.\n• Làm việc trong một môi trường trẻ, đầy tính hợp tác, tin tưởng và được tự do sáng tạo.\n• Tối thiểu 2 năm kinh nghiệm về lập trình bằng ASP.Net (C#, .NET).\n• Sử dụng thành thạo javascript, html, css.\n• Tư duy phát triển sản phẩm phần mềm với độ linh hoạt và tính ổn định cao.\n• Ưu tiên có kinh nghiệm làm việc về các dự án Thư viện điện tử, Ngân hàng câu hỏi, ngân hàng đề thi.\n• Có kinh nghiệm về lập trình .Net core, AngularJS, Restful API là một lợi thế. Kĩ năng mềm:\n• Có khả năng hợp tác với nhóm để hoàn thành được công việc 1 cách tối ưu\n• Có khả năng hướng dẫn các thành viên trong nhóm nâng cao kỹ năng chuyên môn\n• Giao tiếp, đọc hiểu tài liệu tiếng anh tốt là một lợi thế\n• Thưởng theo % của từng dự án khi tham gia phát triển sản phẩm. (thưởng theo quý)\n• Cơ hội nghiên cứu phát triển các sản phẩm mang tính ứng dụng thực tế.\n• Cơ hội làm việc trên các nền tảng công nghệ mới để hiện thực nhanh các yêu cầu về nghiệp vụ.\n• Tham gia phát triển các dự án tại Thái Nguyên, Đà nẵng, Đà lạt, Nha trang, HCM khi join vào các dự án trên toàn quốc\n• Lương cạnh tranh và được xem xét đánh giá tăng lương theo năng lực cá nhân đóng góp cho từng dự án theo Quý.\n• Tăng thu nhập khi đăng ký làm thêm các công việc ngoài giờ hành chính\n• Lương tháng 13\n• Du lịch công ty/Team building\n• Làm việc trong môi trường trẻ trung, năng động, chuyên nghiệp, nhiệt tình.\n• Các giải thưởng hàng năm: “Team of the year”, “Employee of the year”,…\n• Được đào tạo, nâng cao kinh nghiệm và kiến thức chuyên môn\n\nĐịa điểm làm việc:\n- Hà Nội: 262 Nguyễn Huy Tưởng, Thanh Xuân\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 (từ 08:00 đến 12:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2738, 1471, 2, 'Nhân Viên Lập Trình CNC', '- Vẽ & lập trình các chi tiết gỗ nội thất cho máy CNC. \n- Set-up máy, thay dao chỉnh cỡ để đánh mẫu & chạy hàng SX. \n- Mài dao, bảo trì máy móc CNC theo kế hoạch bảo dưỡng định kỳ. \n- Vận hành chạy hàng SX theo phân công khi đã xong việc chỉnh cỡ. \n\nYêu cầu ứng viên: \n- Tốt nghiệp Cao đẳng hoặc Đại học \n- Có kinh nghiệm vận hành máy CNC ngành gỗ là ưu tiên \n- Có tính cẩn thận, chịu khó \n- Làm việc tại nhà máy. \n\nQuyền lợi: \n- Lương, thưởng cạnh tranh \n- Được tham gia BHXH, BHYT, BHTN \n- Lương thứ 13 theo hoạt động kinh doanh \n- Hỗ trợ nhà ở miễn phí \n- Hỗ trợ Nhà trẻ, trường học cho con em NLĐ.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2739, 1472, 2, 'Marketing Leader', 'National Housing Organization (N.H.O JSC.) was founded in 2012 with a clear goal: to develop and construct homes in Vietnam to support the increasing demands for home ownership. We create optimal and sustainable solutions for housing and aim to be a leader in quality projects in Vietnam. The combination of local and international experience and expertise enables us to build homes that compliment Vietnamese family culture, while providing higher living standards.\nCurrently, we are looking for a Marketing Leader to join our team.\nResponsibilities:\n• Market & project monitoring\n- Market research to understand the market, competitors, customer journey & behavior.\n- Work closely with brokers, sales men & sales agents to update the market trend, market information.\n- Analysis the sales result, customer profile to evaluate and suggest the new direction for next marketing campaign.\n- Making monitoring report, evaluation report after each campaign and update the plan to ensure the quality of campaigns.\n• Marketing plan\n- Coordinate with the Sales Department to create an overall marketing plan.\n• Campaign deployment and management\n- Develop and manage campaigns including events, social media, communication follow the master plan.\n- Work closely with clients’ internal communication team.\n- Work closely with clients’ executive teams, preparing speaking points and creating formal documents outlining speaking engagements.\n• Sales and marketing materials production\n- Working with vendor/agencies to order & manage marketing materials: Sales kit, CGIs, Rendering video, miniature, Video clips, mock-up units...\n• Budget plan and management\n- Develop marketing budget for the Project, control and evaluate the implementation of the approved budget.\n• Carry out assigned tasks with limited supervision, including coordinating, and implementing projects.\n• Other tasks assigned by line manager.\n\nYêu cầu ứng viên\n• Bachelor or Master Degree in Marketing, Business Management or relevant major.\n• Fluent in English.\n• Have 4-5 years of experience in Marketing field.\n• Experience in the Real Estate industry or Communication agency is preferable.\n• Good knowledge, and experience in the real estate market, market analysis, and creative marketing.\n• Have a deep and broad knowledge of Marketing and Marketing tools, Communication skills, partnerships, project management, and strategic thinking.\n• Good at Microsoft Office.\n• Confident, smart, fast – learner, strong analytical skill.\n• Detailed oriented and out-going characteristics.\n\nQuyền lợi\n• International working environment.\n• Social insurance registered on gross salary.\n• Challenges and promising experience as the company is growing and expanding.\n• 13th month salary, annual salary review, bonus on public holidays (New Year, Liberation & Labor Day, National Day, etc.).\n• Monthly birthday party, quarterly department meal, annual Health check-up, etc.\n• Friendly, supportive and open-minded colleagues and environment.\n• Other competitive benefits.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 44B Nguyen Van Troi, ward 15, Phu Nhuan district, Phú Nhuận\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2740, 1450, 2, 'Frontend Developer (ReactJS + Blockchain)', 'Mô tả công việc\n- Deploy web apps with modern technologies (JavaScript/HTML5/CSS3, etc.) and frameworks (ReactJS)\n- Enhance the performance of existing products\n- Build architecture and design new features, new products\n- Research new technologies to apply in current and future projects\n- Perform security and performance analysis.\n\nYêu cầu ứng viên\nMust have:\n- Have experience working in the Blockchain with Ethereum JS library (Ethers.js, Web3.js), ...\n- Understanding and working with REST API\n- Able to work with a team as well as independently.\n- Have the spirit and responsibility with the assigned work.\n- Be proactive in work to ensure deadlines as well as product quality.\n- Have good English skills (reading skills are required)\n\nNice to have:\n- Good background knowledge: algorithms, problem solving, OOP, design pattern\n\nQuyền lợi\nDevelopment opportunities:\n- Working in an environment with talented engineers who have experience in developing products in the field of Fintech, Blockchain, Cryptocurrencies.\n- Take a key role in building the project from the very beginning;\n- Technical and professional training throughout the working process.\nRemuneration:\n- Earn up to $2000, 13th-month bonus, performance bonus according to the company\'s business situation.\n- Flexible working hours: 9:00-18:30 Monday-Friday, 1h30-minute lunch break\n- Labor contract and all benefits prescribed by the state (pay social insurance, health insurance, unemployment insurance);\n- 16 days leave, 4 days sick leave with full salary;\n- PVI Healthcare Insurance;\n- Annual health check at a reputable hospital;\n- Equipment for work;\n- Daily lunch, happy hour every Thursday, and monthly team outing;\n- Chillax office with gym, swimming pool, free snacks & drink all day;\n- Travel - vacation at least once a year at domestic and international 5-star resorts.\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes West Point, Pham Hung Street, Me Tri Ward, Nam Tu Liem, Ha Noi, Nam Từ Liêm.\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:30).\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2741, 1473, 2, 'Android Engineer', 'As an Android Software Engineer, you will work on building scalable, high-performance applications with a focus on performance optimization and clean architecture.\n\n- Implement Android (Kotlin) and Flutter components of our SaaS product\n- Drive the entire mobile software lifecycle, from prototyping to commercialization and post-launch support\n- Build clean, well-tested, and maintainable code that aligns with our cross-platform architecture and performance goals\n- Participate in design reviews, code reviews, and contribute to cross-functional discussions and continuous improvement\n- Partner with Product, Design, and Backend teams to deliver quality Android applications\n\nFor Senior:\n- Propose architecture and design reviews to ensure high standards in software quality\n- Set a high technical standard for the team through code and design reviews\n- Enhance engineering processes, including sprint planning, stand-ups, and long-term planning\n- Mentor junior/middle engineers, foster growth, and technical skill development within the team\n\n**Yêu cầu ứng viên**\n- Bachelor’s Degree in Computer Science / Information Technology / Software Development or related fields\n\n**Must have:**\n- 1+ year of experience in Kotlin and Flutter cross-platform technologies\n- Hands-on experience in independently completing or participating in large-scale Android projects\n- Good understanding of framework principles, and practical experience in performance optimization for low-end device models, including but not limited to startup, memory, network, etc\n- Understand Jetpack components, familiar with annotation frameworks, and have practical experience\n- Good/Fluent English communication is mandatory\n\n**Nice to have:**\n- Practical experience in catering apps, with architecture ability preferred\n- Experience with hardware knowledge reserves and practical experience (including but not limited to printers, external card machines, USB/Bluetooth communication) is preferred\n\n**Quyền lợi**\nWe are a multinational, product-driven company specializing in proprietary POS solutions — developing in-house and delivering directly to our worldwide customers.\n\n**Recognition & Rewards:**\n- 13th-month salary\n- Loyalty Bonus programs\n- Biannual Performance and Salary review\n\n**Comprehensive Insurance Coverage:**\n- Full government public insurance contributions based on gross salary\n- Premium health insurance\n- Annual health check\n\n**Clear career development and growth structure; Training sessions and Learning workshops**\n\n- 14 days of annual leave and one additional day of leave for every year of service\n- Laptop/MacBook and top-notch facilities are provided based on each role\n- Agile/Scrum-based internal workflows for efficient and collaborative development\n- Company trips, parties and regular team-building activities; Weekly happy hour, coffee, snacks, and board games\n- Overseas travel opportunities based on the individual performance and policies for each evaluation period\n\n**Working Environment & Culture:**\n- International Workplace: English-speaking environment\n- Positive and Open-Minded Culture: Engineers are encouraged to propose innovative solutions that enhance productivity and code quality\n- 1-on-1 Mentorship: Monthly coffee sessions with managers offer personalized feedback, goal setting, and career development opportunities\n- Flexible Working Hours: Promote work-life balance and individual productivity\n\n**Địa điểm làm việc**\n- Hồ Chí Minh: Quận 4\n\n**Cách thức ứng tuyển**\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 4', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2742, 1474, 2, 'Giám Đốc Bảo Dưỡng', '-Chịu trách nhiệm quản lý các thiết bị của hệ thống điện (cao áp, hạ áp), hệ thống điều khiển (thiết bị điều khiển, phần mềm điều khiển); Hệ thống khí nén; hệ thống cầu trục điện; hệ thống chiếu sáng toàn Nhà máy.\n-Chịu trách nhiệm quản lý về mặt kỹ thuật điện và cơ khí của các thiết bị trên các dây chuyền sản xuất.\n-Chịu trách nhiệm quản lý dụng cụ, công cụ được nhà máy giao cho thuộc Phân xưởng điện và phân xưởng cơ khí. Chịu trách nhiệm quản lý các vật tư tiêu hao phục vụ cho công tác sửa chứa và bảo dưỡng.\n-Thiết lập và quản lý danh mục các máy móc thiết bị và lịch bảo trì cho toàn bộ các thiết bị máy móc trong nhà máy.\n-Kiểm tra, giám sát chặt chẽ các hoạt động của phân xưởng cơ điện nhằm đảm bảo đạt các KPI của bộ phận bảo trì.\n-Đảm bảo các thiết bị luôn trong điều kiện sẵn sàng hoạt động và duy trì hiệu suất cao.\n-Đảm bảo các Máy móc thiết bị trong hệ thống phải thực hiện theo đúng tiêu chuẩn Ban hành.\n-Thiết lập chi tiết các kế hoạch bảo trì và dừng máy đảm bảo nhân viên cấp dưới hiểu rõ những công việc cần thực hiện, đảm bảo phân bổ nguồn lực hợp lý.\n-Đào tạo nhân viên bảo trì đảm bảo nhân viên đủ năng lực thực hiện công việc một cách hiệu quả nhất và đào tạo nâng cao nhằm phát triển các kỹ năng của nhân viên Bảo trì.\n-Đào tạo nguyên lý hoạt động của máy móc thiết bị và các hạng mục cần bảo trì cho bộ phận có liên quan.\n-Thực hiện đầy đủ công tác Bảo trì và tối ưu hóa Chi phí, Nguồn lực và Thời gian.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2743, 1288, 2, 'Fresher Flutter', 'Bạn sẽ tham gia phát triển ứng dụng di động cho sản phẩm EasyPos – phần mềm quản lý bán hàng đa nền tảng do Softdreams phát triển, phục vụ các cửa hàng, siêu thị mini, nhà thuốc, và chuỗi bán lẻ,...\n\nNhiệm vụ chính:\n- Phát triển và tối ưu ứng dụng di động (Android/iOS) bằng Flutter.\n- Thiết kế giao diện UI/UX hiện đại, dễ dùng, phù hợp nghiệp vụ bán hàng.\n- Tích hợp hệ thống API (bán hàng, kho, hóa đơn điện tử, khách hàng...).\n- Tham gia phân tích, thiết kế giải pháp kỹ thuật theo yêu cầu từ team sản phẩm.\n- Làm việc nhóm theo quy trình Agile/Scrum, quản lý tiến độ bằng OKRs.\n- Cải tiến hiệu năng, xử lý lỗi, nâng cấp và bảo trì ứng dụng định kỳ.\n\nYêu cầu ứng viên:\n- Tối thiểu 6 tháng - 1 năm kinh nghiệm phát triển ứng dụng Mobile trên Android hoặc iOS.\n- Thành thạo Dart/Flutter, hiểu rõ widget tree, state management (Provider, Bloc hoặc Riverpod), async, RESTful API.\n- Tư duy tốt về thiết kế UI/UX và xây dựng trải nghiệm người dùng tối ưu.\n- Tinh thần trách nhiệm cao, làm việc đúng hạn và hiệu quả.\n- Kỹ năng làm việc nhóm và độc lập tốt.\n- Khả năng đọc hiểu tài liệu tiếng Anh, tự tra cứu, học hỏi.\n- Chủ động, sáng tạo, yêu thích công nghệ và mong muốn phát triển lâu dài.\n- Sẵn sàng làm việc trong môi trường nhiều thử thách, tốc độ cao.\n- Ưu tiên:\n- Có sản phẩm cá nhân đã xuất bản trên CH Play / App Store.\n- Đã từng làm việc trong mô hình Agile/Scrum, sử dụng OKRs.\n- Có kinh nghiệm với hệ thống POS, tài chính kế toán, chữ ký số là lợi thế.\n\nQuyền lợi:\n- Lương: 8 - 15M + phụ cấp (Phụ cấp: ăn trưa (30k/ngày đi làm), gửi xe.)\n- Chế độ lương thưởng hấp dẫn với lương tháng 13, thưởng tết\n- Đánh giá hiệu suất: 2 lần/năm\n- Làm việc tại Doanh nghiệp với sứ mệnh phụng sự xã hội, mang lại các sản phẩm, dịch vụ nhằm thay đổi năng suất cho các doanh nghiệp\n- Văn hóa trao đổi thẳng thắn, hỗ trợ tận tình; Sếp trẻ tâm lý, đồng nghiệp thân thiện\n- Khuyến khích sự chủ động và tích cực học hỏi\n- Cơ hội thăng tiến và thu nhập phù hợp tùy vào chuyên môn hoặc khả năng quản lý.\n- Được học hỏi: SDS tạo điều kiện cho mọi người rèn luyện ở mọi lúc mọi nơi, đồng hành và thúc đẩy phát triển cá nhân từ đồng nghiệp và quản lý giàu kinh nghiệm\n- Du lịch hằng năm với địa điểm hấp dẫn, thường xuyên tổ chức các hoạt động team building gắn kết cộng đồng, các hoạt động vui chơi giải trí cho nhân viên.\n- Tham gia chương trình hàng tháng, các buổi liên hoan, sinh nhật hàng tháng, tiệc noel, tất niên,...\n- Được tham gia BHXH, BHYT, BHTN, chế độ nghỉ có lương full phép theo luật hiện hành.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2744, 1202, 2, 'JAVA/ .NET Fresher Developers', 'Mô tả công việc\n- Tham gia vào các dự án phát triển phần mềm outsource cho khách hàng (Nhật Bản)\n- Tham gia lập trình, kiểm thử sản phẩm theo từng dự án của khách hàng (Nhật Bản)\n- Sẽ được đào tạo thêm trong quá trình thử việc.\n\nYêu cầu ứng viên\n- Tốt nghiệp các trường Đại học, Cao đẳng các ngành liên quan đến CNTT,...\n- Lập trình với Java Web như: Java Core, JSP Servlet, Struts, Spring MVC, Spring Boot, ...\n- Lập trình với .NET (Web) như: ASP.NET, MVC, Entity Framework, LINQ, ...\n- Lập trình với .NET (Winform) như: C# .NET, VB.NET, ...\n- Đã làm việc với: HTML, CSS, Javascript, JQuery, Bootstrap,...\n- Đã từng làm với ít nhất một Database: SQL Server, MySQL, Oracle...\n- Đọc hiểu nhanh tài liệu tiếng Anh chuyên ngành.\n- Nhanh nhẹn, ham học hỏi, tinh thần trách nhiệm cao, trung thực, cẩn thận.\n- Biết tiếng Nhật là một lợi thế.\n- Ứng viên có kiến thức sau là một lợi thế: Angular, React, Vue.js , Jquery, Framework của ngôn ngữ JAVA/ .NET, Sử dụng được tool quản lý source code: Git, SVN..\n\nQuyền lợi\n- Cơ hội onsite FUJINET JAPAN với ứng viên biết tiếng Nhật.\n- Tham gia khóa đào tạo dành cho nhân viên mới, làm quen với môi trường làm việc cũng như trang bị kỹ năng cần thiết cho công việc.\n- Tham gia miễn phí các khóa đào tạo kỹ năng mềm, đào tạo chuyên sâu về kiến thức chuyên ngành cũng như các buổi giới thiệu công nghệ mới tại công ty.\n- Tăng lương 6 tháng/lần.\n- Lương tháng 13, thưởng các ngày lễ, sinh nhật,...\n- Phụ cấp đi lại (phụ thuộc vào khoảng cách từ nhà đến công ty).\n- Khám sức khỏe 1 năm / lần, Du lịch Công ty 1 năm 1 lần.\n- Được học Tiếng Nhật miễn phí (N5 – N1) trong giờ hành chính, nhận phụ cấp khi có Bằng.\n- Thời gian thử việc tối đa 2 tháng.\n- Thời gian làm việc: 5 ngày / tuần (giờ bắt đầu làm việc linh động từ 7:00-9:00)\n- Thời gian làm việc tại nhà (WFH) linh động hơn 50 ngày/năm.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Toà nhà Waseco (Khu C - Tầng 9), Số 10 Phổ Quang, P2, Tân Bình.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:15).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2745, 1250, 2, 'Senior Fullstack Developer (ReactJs + NodeJs)', 'OUR TECH STACK:\nBackend:\n- Node.js, ExpressJs\n- RabbitMQ / Kafka / MSSQL / PostgreSQL / Redis / Elasticsearch\n- Docker / Kubernetes / Jenkins\nFrontend:\n- React.js / React Native\n- ES6 / Typescript\n- Redux / Redux-Saga / Hooks\nRESPONSIBILITIES:\n- Design, code, and review scalable, maintainable software solutions that align with business and system architecture.\n- Identify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\n- Collaborate across squads (frontend, backend, QA…) to share knowledge, align on best practices, and mentor junior team members.\n- Take ownership of features or systems; lead projects or squads when needed, ensuring delivery quality and guiding technical direction.\n\nYêu cầu ứng viên:\nMust-Have:\n- Proactive problem-solver with a bias toward action and ownership.\nQuick to pick up new frameworks, libraries, and tooling as the stack evolves.\n- At least 4 years of real-world experience in software development.\n- Familiarity with macOS or Linux for development and deployment tasks.\n- Hands-on experience or working knowledge in our core stack is required; full expertise in one side (FE or BE) is acceptable:\n- Backend: Node.js, PostgreSQL, Redis, Elasticsearch.\n- Frontend: React.js, Redux, Redux-Saga, Reselect, React Hooks.\n- Commitment to code quality:\n- Strong experience in code reviews.\n- Familiarity with unit testing best practices.\n- Growth mindset: Ready to grow rapidly as the company scales several times a year.\n\nNice-to-Have (Plus):\n- Deep understanding of Webpack, including code splitting, asset optimization, and custom configurations.\n- Strong foundation in computer science: Data structures, algorithms, design patterns.\n- Experience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\n- Familiarity with microservices architecture.\n\nQuyền lợi:\n- Competitive Compensation & Bonuses\n- Attractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n- 100% salary during the probation period.\n- 13th-month salary to ensure financial stability.\n- Performance reviews twice a year with opportunities for salary adjustments.\n- Flexible Work & Growth Opportunities\n- Hybrid working model: Work from home or at the office as needed.\n- Work alongside top CTOs, architects, and tech leaders at Vexere.\n- Build your public profile through:\nPublishing articles on Medium & Vexere Techblog under your name.\nContributing to Open Source projects managed by Vexere.\nSpeaking at tech talks and industry events.\n- Attractive stock options for dedicated developers and team leads.\n- Exclusive Employee Perks\n- Up to 30% discount on bus tickets for Vexere employees and their families.\n- 12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\n- Vibrant and dynamic work environment with a friendly, supportive team.\n- Training sessions on negotiation, communication, work management, interpersonal skills, and software technology.\n- Exciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 384 Hoang Dieu, Ward 6, Quận 4\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2- Thứ 6, Sáng thứ 7\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2746, 20, 2, 'Senior Backend Engineer (Java/Spring Boot)', 'One Mount is Vietnam’s largest technological ecosystem that creates solutions along the entire value chain, starting with retail, distribution, real estate, and financial services. Our mission is to build Vietnam’s most trusted ecosystem, empowering all people and businesses to realize their full potential at the intersection of technology and humanity.\n\nWe are seeking highly skilled Senior Java Developers to enhance our product team. This presents an exceptional opportunity to be part of a prominent and innovative Vietnamese startup, One Mount Group, and contribute to the development of our cobroker platforms.\n\nResponsibilities\n- Writing clean & high-quality code\n- Maintain & improve running- functionality as well as design and develop new system, new feature if needed\n- Deliver end-to-end, including unit test, integration test and deployment to PROD\n- Participate in code reviews & control coding quality standards\n\nQualifications\n- Minimum 5 years of hands-on development experience in Java (Spring Boot framework)\n- Good understanding of Data Structures and Algorithms\n- Expertise in SQL/ NoSQL Databases (MySQL, PostgreSQL, MongoDB)\n- Experience with RESTful APIs, Microservices\n- Familiarity with Redis, Kafka\n- Experience in high-performance, low-latency systems, handling large-scale data processing and real-time transactions\n- Experience with Docker/Kubernetes and Cloud Infrastructure is a plus\n- Experience with Agile or Scrum software development methodologies\n- Familiarity with the financial, banking, or payment gateway domain or PropTech sector is highly desirable.\n\nBenefit and Perks\nSalary & Allowances\n- 13-month salary with annual performance bonus, project incentives, sales incentives (based on position)\n- Lunch allowance: 730.000 VND/month\n- Special occasion bonus: 2.500.000VND/year\n- Annual leaves: Up to 20 days/year (based on levels)\n- Health: Social insurance, premium health insurance, yearly health check\n- Laptop, screen and other needed facilities/ accounts/ tools for work\n\nCareer Growth\n- Yearly salary review and promotion\n- Diverse career path: Management or Expert and functions rotation opportunity\n- Free learning sources in Udemy, Coursera, O\'relly platforms; internal workshop, certification sponsorship, and exclusive mentoring from C-levels\n- Recognition and awards at team and organizational levels.\n\nWorking Environment\n- Open & collaborative working space foster both individual focus and teamwork activities\n- Young, dynamic, and collaborative working atmosphere\n- Unwind zones: gaming, table tennis, yoga, gyms, bath rooms, sleep corner.\n- Quarterly/yearly teambuilding & engaged internal events.\n\nĐịa điểm làm việc\n- Hà Nội: Tower 2 - Times City, 458 Minh Khai Street, Hai Ba Trung District, Hanoi, Hai Bà Trưng\n\nThời gian làm việc\n- Thứ 2 (từ 09:00 đến 18:00)\n- Thứ 7 (từ 09:00 đến 13:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2747, 1343, 2, 'Fullstack Developer (Reactjs & PHP) - Tối Thiểu 2 Năm Kinh Nghiệm', 'Mô tả công việc:\n- Develop apps for e-commerce platforms Shopify/ WooCommerce.\n- Deliver high-quality products on schedule.\n- Communicating and reporting work progress to the manager.\n- Collaborate with the team to enhance/add features to the apps based on personal insights.\n- Supporting colleagues in completing the product together.\n\nYêu cầu ứng viên:\n- FE: Proficient in ReactJS.\n- BE: Proficient in PHP - Laravel.\n- At least 2 years of practical project experience with the mentioned technologies.\n- Proficient in using Git.\n- Solid understanding of MySQL or NoSQL databases.\n- Experience with front-end technologies: HTML, CSS, JavaScript frameworks (jQuery, Vue.js, Bootstrap)\n- Knowledge Shopify, Shopify theme, liquid.\n- Proactive and efficient.\n\nQuyền lợi:\n- Competitive salary (negotiable based on experience);\n- Working from Monday - Friday, 8 AM- 5 PM, no OT;\n- Performance bonus, 13th- month salary, public holidays bonus (30/4, 1/5, 2/9, 1/1);\n- Excellent Employee and Excellent Team;\n- Comprehensive insurance package including social, health, unemployment, and Bao Viet care insurance;\n- Work performance review 2 times/ year (in May and November);\n- 01 hour paid leave per day for women having children under 12 months;\n- Annual health check;\n- 12 - 18 days full paid leave/year;\n- A Learning budget up to 25 million VND per.\n- Yearly company trip and year-end party, quarterly team building and Sports Clubs;\n- Men’s Day, Women’s Day, Mid-Autumn Festival and other benefits under the provisions of the company;\n- Working in a product development environment, owning the product in charge, participating in the process of bringing ideas, improving product innovation.\n- Nice working space with young, dynamic & friendly colleagues and free coffee, tea, and drinks.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2748, 1217, 2, 'Fullstack Developer', 'Mô tả công việc:\n- Collaborate with the software development team to define project scopes and scales.\n- Design robust software architectures to meet project requirements.\n- Implement efficient data structures, design patterns, and scalable web services.\n- Build and maintain internal software tools, troubleshoot issues, and optimize performance.\n\nYêu cầu ứng viên:\nQualifications and Skills:\n- Bachelor’s degree in Computer Engineering or Computer Science.\n- Proven 5+ years experience as a Full-Stack Engineer with a successful project portfolio.\n- Proficiency in front-end (HTML5, CSS, JavaScript, JQuery) and back-end (Java, Golang, Python, Rails, Ruby, .NET, PHP) languages.\n- Strong troubleshooting skills, familiarity with popular JavaScript frameworks, excellent communication, and project management abilities.\n\nDesired Skills, Traits, and Qualities:\n- Previous experience with cloud-based services and EDA applications.\n- Track record of delivering high-quality Full-Stack solutions in fast-paced environments.\n- Passion for ensuring scalability, reliability, and security of cloud-based services.\n- Ability to thrive in collaborative environments, adapt to evolving technologies, and communicate effectively.\n\nQuyền lợi:\n- Flexible work arrangements and remote work opportunities.\n- Competitive salary.\n- Performance-based bonuses/ 13th month salary.\n- Comprehensive health, dental, and vision insurance plans.\n- Professional development and training programs.\n- Paid time off and company holidays.\n- Refer friends to open jobs and receive a cash bonus for every successful referral you make.\n\nĐịa điểm làm việc:\n- Hà Nội\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2749, 1205, 2, 'Kỹ Sư Cầu Nối (C#, Onsite)', 'Là một Công ty hoạt động trong lĩnh vực Y tế số, chúng tôi coi nhân sự là trung tâm của mọi hành động. Ominext đang nỗ lực xây dựng một môi trường sống hạnh phúc, chú trọng tới phát triển chuyên môn và chăm sóc sức khỏe cho từng Cán bộ nhân viên, người thân của họ! Gia nhập Ominext ngay hôm nay để tận hưởng các ưu đãi đặc quyền dành riêng cho người Omi.\n\nVới vai trò là Kỹ sư cầu nối, ứng viên sẽ thực hiện các công việc:\n- Tham gia phát triển dự án Procurement cho khách hàng Nhật Bản.\n- Nghiên cứu, hiểu sâu hệ thống khách hàng, nắm chắc nội dung dự án (nhận tài liệu mô tả, họp spec cùng khách) thực hiện trao đổi Q&A trực tiếp với khách hàng truyền đạt thông tin về team Offshore tại Việt Nam.\n- Phối hợp với đội dự án tại Việt Nam giám sát tiến độ thực hiện dự án, quản lý chất lượng sản phẩm đầu ra của dự án trước khi bàn giao cho khách hàng.\n\nYêu cầu ứng viên:\n- Tiếng Nhật sử dụng thành thạo (trình độ tương đương N2 trở lên).\n- Có từ 3 năm kinh nghiệm SE/BrSE.\n- Có kinh nghiệm code C#, VB.NET là lợi thế lớn.\n- Áp dụng các quy trình Agile/Scrum là lợi thế.\n- Kỹ năng quản lý team và giao tiếp đa quốc gia hiệu quả là lợi thế.\n- Có kinh nghiệm xác định yêu cầu, thiết kế và xây dựng hệ thống (basic design/detail design) là lợi thế lớn.\n- Ưu tiên ứng viên có kinh nghiệm làm các hệ thống liên quan đến warehouse, logistic.\n- Quản lý tiến độ, quản lý rủi ro tốt là 1 lợi thế.\n- Chủ động, tư duy tích cực và có tinh thần trách nhiệm cao với công việc.\n\nĐịa điểm làm việc: Okayama, tại location khách hàng.\n\nQuyền lợi:\n- Môi trường làm việc lý tưởng, được tôn trọng:\n  - Dự án lâu dài, ổn định, tiềm năng phát triển mở rộng rất lớn.\n  - Đội ngũ Quản lý kinh nghiệm dày dạn, có lý tưởng lớn sẵn sàng chia sẻ, đồng hành, là những con người nhiệt huyết, tài năng, tận tâm và đặc biệt chuyên môn sâu rộng (chuyên gia trong lĩnh vực của mình). Được làm việc trực tiếp với CEO và đội ngũ Solution Consultant trong lĩnh vực IT Healthcare.\n  - Đội ngũ chuyên gia với các chứng chỉ hàng đầu về y tế số như chứng chỉ Medical Health Care Certifications, chứng chỉ HL7,... Ominext tự hào khi có nhân sự là người đầu tiên tại Việt Nam đạt chứng chỉ HL7 FHIR.\n  - Cùng với sứ mệnh tiên phong kiến tạo hệ sinh thái Y tế số, tái định vị thương hiệu, OmiGroup khẳng định tinh thần, nhiệt huyết, sẵn sàng đóng góp vì mục tiêu chăm sóc sức khỏe con người và xã hội.\n- Tập trung hỗ trợ sự phát triển cá nhân:\n  - Cơ hội làm việc tại công ty dẫn đầu Việt Nam về IT Healthcare, là thành viên nước ngoài duy nhất tại JAHIS - Hiệp hội Công nghiệp Hệ thống Thông tin Y tế Nhật Bản.\n  - Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng với hệ thống career path (phát triển theo hướng chuyên gia hoặc hướng quản lý) đã được nghiên cứu, thử nghiệm trong nhiều năm.\n  - Cơ hội tham gia nhiều dự án đa dạng, team size từ 10MM - 150MM.\n  - Cơ hội về Việt Nam mở business riêng.\n- Quan tâm đặc biệt tới nhân viên:\n  - Mức lương thưởng: Hấp dẫn, cạnh tranh với thị trường.\n  - Hỗ trợ xin visa (cho ứng viên ở Việt Nam), đổi visa (cho ứng viên tại Nhật Bản).\n  - Tài trợ vé máy bay khứ hồi về Việt Nam thăm gia đình dành cho nhân viên có thâm niên công tác từ 1 năm trở lên.\n  - Hỗ trợ tiền nhà (tối đa 30.000 Yên/tháng), chi phí đi lại (tối đa 20.000 Yên/tháng).\n  - Một số phúc lợi xã hội như: Rèn luyện sức khỏe, trau dồi kiến thức, học tập nâng cao phục vụ công việc (mua sách vở, tập gym, thể thao, …) (tối đa 10.000 Yên/tháng).\n  - Được đóng BHXH, BHYT, BHTN theo quy định của chính phủ Nhật Bản.\n  - Khám sức khỏe định kỳ 1 năm/lần cho nhân viên thâm niên từ 6 tháng.\n\nĐịa điểm làm việc:\n- Nhật Bản\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:30 đến 18:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nhật Bản', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2750, 1242, 2, 'Front End Developer', 'Mô tả công việc:\n- Design, develop, and maintain user interfaces for web applications.\n- Collaborate with UX/UI Designers to ensure intuitive and user-friendly interfaces.\n- Integrate APIs and back-end services to deliver full features.\n- Optimize interface performance (loading speed, cross-device compatibility).\n- Write clean, reusable, and maintainable code.\n- Analyze and troubleshoot front-end issues.\n- Stay updated and apply the latest technologies and frameworks.\n\nYêu cầu ứng viên:\n[Required]\n- Have at least 3 years of experience (Prioritize high experience)\n- Experienced web / mobile application development\n- Can develop HTML, CSS, Javascript, jQuery\n- Can develop based on React.js or Vue.js, Vuex\n- Experienced with collaboration tools like Git, Jira and Confluence\n- Understand and use CI/CD\n- English speaking on average (or TOEIC on 550)\n\n[Preferred]\n- Understand Back-end\n- Use Typescript\n- Experienced with Node.js\n- Experienced with javascript charts (Echarts, Chart.js, d3js, etc.)\n- Experience using Tailwind, MUI\n- OAuth development experience\n- Korean communication\n- Team management experience\n\nQuyền lợi:\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Review capacity annually and adjust salary increases according to work performance.\n- Korean language certificate bonus (TOPIK)\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment, flexible working hours\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 15, Keangnam Landmark 72, Nam Từ Liêm\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2751, 1128, 2, 'Fullstack Developer (Java + Reactjs)', 'Mô tả công việc: Phát triển, tối ưu và bảo trì hệ thống web cho khách hàng Nhật Bản với Java (Spring Boot) ở backend & React ở frontend.\nTham gia toàn bộ SDLC: phân tích yêu cầu, thiết kế, coding, code-review, CI/CD và triển khai trên AWS.\nĐề xuất giải pháp kỹ thuật, nâng cao hiệu năng (multithread, concurrency), đảm bảo bảo mật và chất lượng mã.\nMentor thành viên junior, phối hợp chặt chẽ với PM và khách hàng.\n\nYêu cầu ứng viên:\n- Học vấn: Tốt nghiệp Đại học chuyên ngành CNTT hoặc liên quan.\n- Kinh nghiệm: 4 năm Java/Spring & 2 năm React; từng đảm nhiệm vai trò full-stack.\n- Java: OOP, Clean Code, Design Patterns; thuần thục Collection vs Stream, multithread/async; logging; đọc/ghi & migration dữ liệu DynamoDB.\n- DynamoDB: phân biệt và dùng đúng Query vs Scan, lấy dữ liệu bulk, thiết kế & sử dụng GSI hiệu quả.\n- React: quản lý state toàn cục với useContext hook, hiểu kiến trúc component, tối ưu render.\n- AWS: SSH vào EC2, xuất log, phát hiện & xử lý overload/instance die; kiến thức Auto-Scaling, CloudWatch là lợi thế.\n- Khác:\n  - MySQL hoặc NoSQL (MongoDB).\n  - Thành thạo Git.\n  - Tư duy giải thuật tốt, tự học nhanh.\n  - Giao tiếp tiếng Nhật (N3+) là điểm cộng.\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc.\n- Thu nhập: 13 tháng lương/năm + thưởng kinh doanh cuối năm + thưởng dự án, thưởng các dịp lễ.\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc.\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty.\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30).\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành.\n- Bảo hiểm chăm sóc sức khỏe 24/24.\n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội.\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện).\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày.\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành.\n- Miễn phí đồ uống tại khu ăn uống của công ty.\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan.\n- Phụ cấp thâm niên; phụ cấp chức vụ.\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLUB Dance.\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm.\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín.\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.\n\nĐịa điểm làm việc: Hà Nội: Tầng 4 CT1, Tòa C14 Bắc Hà, Đường Tố Hữu, Phường Trung Văn, Nam Từ Liêm.\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2752, 1271, 2, 'Fullstack Developer', 'Mô tả công việc\n1. Thiết kế, phát triển, triển khai và tối ưu hệ thống phần mềm\n- Phân tích yêu cầu, vấn đề và rủi ro có thể phát sinh trong quá trình thực hiện yêu cầu.\n- Thiết kế tổng thể hệ thống, các module thành phần, các chức năng chi tiết\n- Lập trình phát triển, bảo trì các chức năng hệ thống phía backend.\n- Triển khai và tích hợp các thành phần hệ thống phía backend và frontend\n- Tối ưu các thành phần hệ thống phía backend: code, database.\n- Triển khai và vận hành ứng dụng trên docker, k8s...\n- Tham gia xây dựng pipeline thu thập, xử lý và phân tích dữ liệu từ các thiết bị network, server trong Data center.\n- Xây dựng thuật toán giúp tối ưu cho việc xuất kho, điều chuyển hàng hoá phục vụ xây lắp công trình, trạm..\n\n2. Hợp tác và chia sẻ\n- Hợp tác với các thành viên trong dự án để thiết kế API phù hợp với yêu cầu của tính năng.\n- Chia sẻ kiến thức, công nghệ với các thành viên trong nhóm.\n- Review code giữa các thành viên trong dự án và code của đối tác.\n\nYêu cầu ứng viên\n1. Yêu cầu chuyên môn tối thiểu\n- Hiểu biết cơ bản về mạng máy tính, các giao thức mạng máy tính: UDP, TCP/IP, HTTP\n- Hiểu biết và sử dụng Git để quản lý phiên bản.\n- Có tư duy xác định và giải quyết vấn đề.\n- ⁠Có kinh nghiệm làm việc với Nodejs và các framework: NestJS(TypeORM, Queue, Cache)\n- Có kinh nghiệm code frontend (VueJS, Reactsj)\n- Có kinh nghiệm làm việc với CSDL (Oracle, MySQL/MariaDB, PostgreSQL, Elasticsearch) bao gồm phát triển, viết các truy vấn phức tạp, tối ưu CSDL, SQL\n- Hiểu biết về docker\n- Có kinh nghiệm làm việc với redis để tối ưu hiệu năng\n\nYêu cầu chuyên môn mở rộng\n- Thông thạo nhiều ngôn ngữ lập trình là một lợi thế.\n- Có kinh nghiệm sử dụng hệ điều hành Linux là một lợi thế.\n- Có hiểu biết về REST, RESTful API. Có kinh nghiệm thiết kế và cài đặt RESTful API là một lợi thế.\n- Có hiểu biết về containerization với Docker, container orchestration với Kubernetes là một lợi thế.\n- Có hiểu biết, kinh nghiệm xử lý và phân tích dữ liệu là một lợi thế.\n- Có khả năng tự nghiên cứu về thuật toán để đề xuất hướng giải quyết hoặc trực tiếp triển khai vào sản phẩm là một lợi thế.\n- Có khả năng nghiên cứu về các kiến trúc, nền tảng phù hợp xây dựng hệ thống linh hoạt, dễ mở rộng là một lợi thế.\n\n2. Trình độ học vấn\n- Tốt nghiệp đại học chính quy chuyên ngành: công nghệ thông tin (Information Technology), khoa học máy tính (Computer Science), kỹ nghệ phần mềm (Software Engineer) hoặc tương đương.\n- Yêu cầu tiếng Anh: TOEIC IIG 550 hoặc tương đương.\n- Đã từng tham gia và đạt giải trong các kỳ thi cấp quốc gia, quốc tế như HSG quốc gia, olympic sinh viên, ACM/ICPC,...; tham gia nghiên cứu khoa học, tham gia hoạt động cộng đồng như mã nguồn mở, CLB lập trình; tham gia các cuộc thi lập trình, hackathon... là một lợi thế.\n- Có chứng chỉ chuyên môn được công nhận bởi các tổ chức uy tín là một lợi thế.\n\nQuyền lợi\n- Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn\n- Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel\n- Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm\n- Cơ hội tiếp xúc với các dự án lớn, mới mẻ & tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam\n- Cơ hội thăng tiến rõ ràng với nhiều cấp bậc\n- Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn\n- Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời.\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người.\n- Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,...\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày\n- Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2753, 1267, 2, 'Kỹ Thuật Viên Lập Trình CNC', 'Lập trình gia công cho loại máy CNC: máy cưa, máy cắt dây, máy tiện, máy phay, máy xung điện, máy khoan-taro, máy khắc laser. Tiếp nhận các bản vẽ từ bộ phận thiết kế. Tiến hành kiểm tra, bóc tách bản vẽ thiết kế. Sử dụng phần mềm chuyên dụng thực hiện lập trình gia công các chi tiết, đảm bảo phù hợp với các thông số kỹ thuật của máy CNC. Xuất bản vẽ và gửi lên trưởng bộ phận kiểm tra.\nYêu cầu ứng viên:\n- Sức khỏe tốt\n- Nhanh nhẹn, cẩn thận, kiên nhẫn, tỉ mỉ\n- Yêu thích các loại máy móc cơ khí\n- Sử dụng ít nhất một phần mềm lập trình CNC\n- Có kinh nghiệm làm việc với nhiều loại máy CNC là một lợi thế.\n- Sẵn sàng làm thêm giờ theo yêu cầu.\n- Sẵn sàng đi công tác theo yêu cầu.\nQuyền lợi:\n- Thỏa sức học hỏi về các kỹ năng lập trình máy CNC, gia tăng cơ hội phát triển nghề nghiệp tại công ty hoặc các doanh nghiệp lớn khác. Đến với QCM bạn sẽ lập trình được tất cả các dạng chi tiết 2D, 3D, 4D, 5D, đáp ứng được công việc tại bất kỳ công ty nào khác, vì QCM chúng tôi sản xuất đầy đủ các chủng loại sản phẩm, có đầy đủ các loại máy móc phù hợp từ đơn giản đến hiện đại.\n- Lương cơ bản 6-15tr/1 tháng tùy theo năng lực, trình độ. Thưởng tết 1-1.5 tháng lương tùy theo hiệu quả công việc, thưởng ngày lễ chiến thắng, ngày lễ quốc khánh, du lịch hàng năm.\n- BHYT, BHXH, BHTN theo quy định của nhà nước.\n- Phụ cấp chuyên cần 400k/1 tháng, phụ cấp đi lại 150k/1 tháng, phụ cấp nhà trọ 300k/1 tháng, miễn phí ăn ca, ăn trưa theo chính sách của công ty.\n- Được đào tạo vận hành, sử dụng máy móc thiết bị hỗ trợ, đào tạo nâng cao kỹ năng gá đặt, cài đặt, đào tạo lập trình máy đối với các nhân viên mong muốn học nâng cao.\n- Môi trường làm việc năng động, cơ hội nâng cao kỹ năng, kiến thức, kinh nghiệm thông qua các dự án sản xuất đa dạng các loại máy móc thiết bị công nghiệp, dân dụng, y tế.\nĐịa điểm làm việc:\n- Hà Nội: 57-LÊ HỮU TỰU-NGUYÊN KHÊ, Đông Anh\n- Hà Nội: Sóc Sơn\n- Bắc Giang\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2754, 1122, 2, 'Java Developer (EN Fluent)', 'Mô tả công việc\n- Work as software developer on the web-based application product in JAVA- related and open-source technologies\n- Upgrade existing functionalities and create new ones using data-driven insights.\n- Implement and deliver new customer project development with high quality.\n- Participate in all phases of the development cycle.\n- Actively join planning meetings.\n- Implement new features according to business specifications.\n- Write unit/functional/integration tests and perform unit testing.\n- Conduct code reviews for other team members.\n- Automate maintenance work through development.\n\nRespond to and resolve IT support requests from employees via phone, email, or service request system.\n\nYêu cầu ứng viên\n- Good command of English (both written/verbal) is essential 5+ for senior of experience in designing, implementing, and maintaining Java-based applications (Spring Framework) with JSP frontend\n- Able to analyze, design, develop new functionalities, and provide maintenance or issue fixes.\n- Experience in enterprise-scale projects using: Oracle PL/SQL; MyBatis; Java (Spring Boot/Spring Framework); JSP (JavaScript / JQuery); Git (Git Runner)\n- Proficient in tools/technologies: Azure, AWS, Redis.\n- Familiar with development tools: DBWeaver, Oracle SQL Developer, Eclipse, IntelliJ IDEA, Git, Gradle, Maven, CI/CD tools\n- Database experience in Oracle, MS SQL Server, or MySQL – with strong SQL, stored procedures, functions, schedulers, etc\n- Familiar with debugging, performance tuning, deploying, maintaining, and monitoring complex Java web applications\n- Solid understanding of OOP, design patterns, and coding standards\n\n-PREFERRED QUALIFICATIONS\nExperience with:\n- MS .Net / .Net Core\n- Kubernetes\n- React.js\n- Nginx\n- JUnit\n- Jasper Report\n- ElasticSearch & Kibana (ELK)\n- Grafana\n- Prometheus (monitoring/alerts)\n\nQuyền lợi\n- Probation salary is 100% of official salary\n- 13th-month salary and performance review twice a year\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n- Project Bonus\n- IT Certificate allowance\n- Health Care Insurance Social, health and unemployment Insurance following Government policy\n- Enjoy company summer trips and other team building activities held monthly and quarterly\n- Work five days per week with flexible check-in time\n- Professional, creative and dynamic working environment\n\nĐịa điểm làm việc\n- Hà Nội: Tòa The Nine, số 9 Phạm Văn Đồng, Mai Dịch, Cầu Giấy\n- Hồ Chí Minh: Điện Biên Phủ, Bình Thạnh\n\nThời gian làm việc\n- Check in-out linh hoạt\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2755, 1342, 2, 'Lập Trình Viên Fullstack Developer', '1/ Phân tích nhu cầu và lập kế hoạch triển khai\nTiếp nhận và làm rõ yêu cầu từ các phòng ban liên quan đến các hệ thống nghiệp vụ như CRM, HRM, ERP, POS,.. và các website bán hàng.\nPhối hợp với các phòng ban để phân tích quy trình vận hành, xác định nhu cầu thực tế và đưa ra giải pháp công nghệ phù hợp.\nLập kế hoạch triển khai, xác định mốc thời gian và đề xuất tài nguyên kỹ thuật cần thiết.\n2/ Thiết kế kiến trúc và lập trình hệ thống\nThiết kế chi tiết các giải pháp công nghệ theo yêu cầu nghiệp vụ đã thống nhất, bao gồm tích hợp dịch vụ bên ngoài (thanh toán trực tuyến, đăng nhập qua bên thứ ba,...).\nLựa chọn và triển khai công nghệ phù hợp (ngôn ngữ lập trình, framework, cơ sở dữ liệu...) đảm bảo hệ thống vận hành hiệu quả, bảo mật, dễ bảo trì và tương thích đa nền tảng.\nThực hiện lập trình và kiểm thử nội bộ theo kịch bản giả lập tình huống thực tế trong vận hành.\nPhối hợp với người dùng để kiểm tra tính ổn định, ghi nhận phản hồi và hiệu chỉnh phần mềm khi cần thiết.\n3/ Bảo trì, nâng cấp và hỗ trợ vận hành\nXử lý lỗi kỹ thuật phát sinh trong quá trình sử dụng: lỗi logic, giao diện, thao tác người dùng...\nCập nhật, nâng cấp tính năng và giao diện theo yêu cầu nghiệp vụ từ các bộ phận chuyên môn.\nTheo dõi, đánh giá hiệu năng hệ thống và đề xuất phương án tối ưu hóa định kỳ.\n\nYêu cầu ứng viên\n1/ Kinh nghiệm: Tối thiểu 2 năm làm việc tại vị trí tương đương trong các công ty hoạt động trong lĩnh vực thương mại, bán lẻ, chuỗi cửa hàng, hoặc sàn thương mại điện tử.\n2/ Kỹ năng Front-End:\nThành thạo các ngôn ngữ và framework phát triển giao diện người dùng như Vue.js, React, HTML5, CSS3, Bootstrap hoặc các CSS framework tương tự.\nCó tư duy thiết kế giao diện tối ưu trải nghiệm người dùng (UX/UI).\n3/ Kỹ năng Back-End:\nThành thạo ít nhất một trong các ngôn ngữ lập trình server-side như Node.js, Python, PHP,...\nCó kinh nghiệm xây dựng RESTful API, xử lý nghiệp vụ phức tạp, bảo mật và tối ưu hiệu suất hệ thống.\n4/ Ưu tiên (Điểm cộng):\nCó kinh nghiệm triển khai hệ thống theo kiến trúc Microservices, bao gồm phân tách dịch vụ, giao tiếp nội bộ qua message queue, và đảm bảo tính mở rộng linh hoạt.\nTừng xử lý các bài toán dữ liệu lớn (big data), bao gồm lưu trữ, phân tích, và đồng bộ dữ liệu trên quy mô nhiều hệ thống.\nĐã triển khai hoặc tham gia vào các dự án có yêu cầu cân bằng tải, tối ưu hiệu suất hệ thống và xử lý lượng người dùng lớn cùng lúc.\nThiết kế và giao diện: Có kiến thức và khả năng sử dụng các phần mềm thiết kế như Adobe Photoshop, Sketch, hoặc công cụ tương đương để làm việc với UI/UX designer (nếu có).\nCơ sở dữ liệu: Nắm vững kiến thức về SQL và có khả năng thiết kế, tối ưu hóa cơ sở dữ liệu quan hệ.\nCông cụ phát triển: Sử dụng thành thạo các công cụ quản lý mã nguồn như Git, SVN (ưu tiên ứng viên có kinh nghiệm với Git workflow chuyên nghiệp).\n\n5/ Kỹ năng mềm:\nKhả năng quản lý thời gian, làm việc nhóm hiệu quả và giao tiếp tốt với các bộ phận liên quan.\nKỹ năng tư duy phân tích và giải quyết vấn đề linh hoạt trong môi trường làm việc thực tế.\nCó tinh thần tự học và cập nhật công nghệ mới.\n\nQuyền lợi\nThu nhập: dao động 20.000.000 - 25.000.000 (Lương cơ bản +Thưởng)\nChính sách lương thưởng đầy đủ, rõ ràng.\nThưởng cuối năm theo kết quả kinh doanh.\nĐóng BHXH, BHYT theo quy định Nhà nước.\nTham gia du lịch công ty kết hợp các hoạt động xây dựng đội nhóm.\nMua hàng nội bộ với chính sách ưu đãi hàng tháng.\nNhận quà vào ngày sinh nhật theo chính sách cho từng cấp bậc.\nHoạt động ngoại khóa thường xuyên vào mỗi thứ 5 hàng tuần, bao gồm: bóng đá, cầu lông, chạy bộ...\nLàm việc trong môi trường hoà đồng, không rào chắn, quản lý công việc bằng hệ thống và được tiếp nhận đầy đủ hướng dẫn từ đồng nghiệp và quản lý cấp trên.\nThường xuyên tổ chức những lớp đào tạo kiến thức sản phẩm, PCCC, sử dụng hệ thống công nghệ để quản lý kho hàng...với mong muốn bạn phát triển cùng MIA\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 117 - 119 Bạch Đằng, Phường 15, Bình Thạnh\n\nThời gian làm việc\nThứ 2 – thứ 6: 8h – 17h / Thứ 7: làm 2 ngày, nghỉ 2 ngày\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2756, 1360, 2, 'Lập Trình Viên Backend (Senior)', 'Mô tả công việc:\n- Phát triển và bảo trì hệ thống backend sử dụng .NET Core / ASP.NET Core.\n- Thiết kế kiến trúc hệ thống, phát triển RESTful APIs phục vụ frontend/mobile.\n- Tối ưu hiệu năng, bảo mật và khả năng mở rộng của hệ thống.\n- Tham gia phân tích yêu cầu nghiệp vụ, thiết kế hệ thống và giải pháp kỹ thuật.\n- Thực hiện code review, hướng dẫn và hỗ trợ các thành viên junior.\n- Viết unit tests, tích hợp CI/CD, và tham gia kiểm thử hệ thống.\n- Phối hợp với các team khác (BA, DevOps, QA, Frontend, Mobile) trong toàn bộ SDLC.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc tương đương.\n- Tối thiểu 4–6 năm kinh nghiệm phát triển phần mềm backend bằng .NET Core.\n- Có kinh nghiệm làm việc với SQL Server, PostgreSQL hoặc các hệ quản trị CSDL quan hệ.\n- Hiểu biết tốt về Clean Architecture, SOLID principles, DDD, Design Patterns.\n- Có kinh nghiệm làm việc với Redis, RabbitMQ/Kafka, hoặc các hệ thống message queue.\n- Hiểu và áp dụng tốt các nguyên tắc bảo mật API (JWT, OAuth2) và kiểm soát session.\n- Có kinh nghiệm với các công cụ CI/CD (Azure DevOps, GitLab CI, Jenkins…).\n- Thành thạo Git, quy trình phát triển theo Agile/Scrum.\n\nƯu tiên:\n- Có kinh nghiệm với microservices, Docker, Kubernetes là lợi thế.\n- Đã từng làm việc với các công nghệ như SignalR, gRPC, hoặc GraphQL.\n- Biết các công cụ giám sát như Prometheus, Grafana, ELK Stack.\n\nQuyền lợi:\n- Lương thỏa thuận theo kinh nghiệm và năng lực.\n- KPI tương ứng với 5 tháng lương thực nhận.\n- Tháng lương thứ 13.\n- Thưởng dự án theo các dự án tham gia.\n- Đặc biệt chia cổ tức cho cán bộ nhân viên theo lợi nhuận của công ty.\n- Tham gia các khóa đào tạo kỹ năng mềm phục vụ cho công việc.\n- Thưởng các dịp lễ, Tết và team building hàng năm.\n- Xét duyệt tăng lương 2 lần/năm.\n- Được hưởng đầy đủ BHXH, BHYT và BHTN theo luật lao động Việt Nam hiện hành.\n- Được làm việc trong một môi trường trẻ trung, năng động cùng với các chuyên gia hàng đầu trong nhiều lĩnh vực của công ty để học hỏi và phát triển hàng ngày.\n- Cơ hội làm việc với các tập đoàn lớn: Tham gia các dự án lớn, làm việc với các khách hàng và đối tác uy tín trong ngành công nghệ trong và ngoài nước.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa N03-T3, Khu Ngoại Giao Đoàn, Phường Xuân Tảo, Bắc Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2757, 1180, 2, 'Kỹ Sư Lập Trình', 'Mô tả công việc:\n- Chèn chương trình vào thiết bị\n- Cải tiến chương trình có sẵn để phù hợp với yêu cầu công nghệ.\n- Lên bom list dự toán thiết bị, điều khiển theo từng máy\n- Viết chương trình PC/Vison\n- Chỉnh sửa lỗi máy khi vận hành phát sinh lỗi liên quan đến phần cứng và phần mềm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp CĐ – ĐH chuyên ngành điều khiển - tự động hóa,…\n- Kinh nghiệm 3 năm trở lên\n- Có kinh nghiệm viết và chỉnh sửa chương trình PC\n- Có Kinh nghiệm viết chương trình C++, C# để điều khiển PC và PLC\n- Có khả năng lập trình với ít nhất một trong các ngôn ngữ sau: Python, Java, C++/C, PC/Vision\n- Có kiến thức về các linh kiện hoặc hệ thống điện của máy tự động trong nhà máy sản xuất điện tử.\n- Có kinh nghiệm làm lập trình cho các công ty sản xuất điện tử.\n\nQuyền lợi:\n- Công ty có xe đưa đón miễn phí HN-VP\n- Đóng BHXH ngay từ tháng thử việc\n- Tặng quà các dịp lễ tết, Lương T13, các chế độ phúc lợi khác.\n\nĐịa điểm làm việc:\n- Vĩnh Phúc: Công ty TNHH Cammsys Việt Nam, KCN Bá Thiện 1, Bình Xuyên, Bình Xuyên.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Vĩnh Phúc', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2758, 1182, 2, 'Java Developer', 'Mô tả công việc:\n- Phát triển các tính năng mới theo yêu cầu của hệ thống cho khách hàng\n- Trao đổi, làm rõ yêu cầu với BA\n- Thực hiện fix bug được phát hiện trong quá trình phát triển và triển khai.\n\nYêu cầu ứng viên:\n- Ít nhất 1 năm kinh nghiệm phát triển ứng dụng phần mềm bằng ngôn ngữ Java\n- Có kiến thức về OOP, Design Pattern\n- Có kinh nghiệm làm việc với: Spring Framework, Hibernate, JPA\n- Thành thạo một trong các hệ quản trị CSDL quan hệ: Oralce, MySQL\n- Có kinh nghiệm làm việc với các công cụ: Git, maven\n- Năng động, sáng tạo, có khả năng tự nghiên cứu\n- Ưu tiên ứng viên có chứng chỉ quốc tế của Oracle về phát triển ứng dụng Java: Java SE, Java EE\n\nQuyền lợi:\n- Lương tháng 13\n- Nghỉ phép, nghỉ lễ, Bảo hiểm xã hội, bảo hiểm y tế theo luật lao động\n- Thời gian làm việc: Thứ 2-Thứ 6, từ 8h30-18h00\n\nĐịa điểm làm việc:\n- Hà Nội: 15 hồ xuân hương, Hai Bà Trưng\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2759, 1233, 2, 'Junior Mobile Developer (React Native)', '- Tham gia phát triển trong các dự án với ngôn ngữ JAVASCRIPT.\n- Xây dựng ứng dụng trên mobile với framework REACT NATIVE.\n- Xây dựng components, thư viện, APIs có thể tái sử dụng cho REACT NATIVE, ANDROID, IOS.\n- Xây dựng các quy trình kiểm thử phần mềm (Unit Tests, UI Tests, Integration Tests & End-To-End Tests).\n- Tương tác dữ liệu với APIs được đội BACKEND cung cấp.\n- Phát triển kỹ năng thiết kế UI/UX.\n- Có định hướng nghề nghiệp rõ ràng về soft skills lẫn hard skill.\n\nYêu cầu ứng viên\n- 1 năm kinh nghiệm, mạnh mảng IOS và tốt nghiệp ngành liên quan.\n- Hiểu biết về HTML, CSS, JAVASCRIPT ES6, Có kiến thức về REACTJS, REACT NATIVE (Functional Programming, Hooks).\n- Sử dụng Xcode hoặc Android Studio và các công cụ hỗ trợ: Simulator, Instrument\n- Sử dụng tốt trên môi trường phát triển Linux & macOS.\n- Có kinh nghiệm sử dụng TYPESCRIPT, REDUX, MOBX.\n- Có kiến thức về RESTful APIs.\n- Có khả năng thiết kế giao diện.\n- Hiểu biết về nguyên tắc SOLID (Single Responsibility Principle).\n- Hiểu biết về quy trình kiểm thử phần mềm.\n- Đã từng sử dụng Android (Java/Kotlin) hoặc iOS (Swift).\n- Đã sử dụng qua các công cụ như GITHUB, JIRA, BITBUCKET, TRELLO.\n\nQuyền lợi\n- Thời gian làm việc linh động: 5 ngày/tuần (thứ 2 – thứ 6) ; 8h30 – 17h30 ; nghỉ trưa 1,5 tiếng.\n- 12 ngày phép năm, 4 ngày phép đột xuất + nghỉ lễ, tết.\n- Thử việc: 60 ngày\n- Tham gia đầy đủ BHXH, BHYT, BHTN theo quy định. \n- Khám sức khỏe định kỳ hằng năm.\n- Cung cấp thiết bị làm việc. \n- Được tham gia các buổi training nội bộ nhằm nâng cao kiến thức. \n- Môi trường làm việc năng động, trẻ trung, thoải mái. \n- Team building, tiệc ăn uống, giải trí hằng tháng, year-end party, v.v... \n- Quà, thưởng: Sinh nhật, lễ tết, trung thu, giáng sinh, v.v....\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Cách Mạng Tháng 8, Quận 3\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2760, 1453, 2, 'Nhân Viên Lập Trình PLC', 'Mô tả công việc:\n- Sữa chữa các thiết bị ,Đấu nối sữa chữa phần điện, lắp ráp máy móc, line sản xuất...\n- Lập trình PLC (Mitsu, Omron, Siemen, ...)\n- Khảo sát hệ thống, thu thập thông tin hệ thống.\n- Những yêu cầu khác từ cấp trên.\n- Chi tiết trao đổi khi phỏng vấn.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Trung cấp, Cao đẳng/ Đại học chuyên ngành điện, tự động hóa….\n- Có kinh nghiệm trên 1 năm ở vị trí tương đương.\n- Am hiểu các thiết bị điện.\n- Biết lập trình PLC (Mitsu, Omron, Siemen, ...).\n- Biết đấu nối, sữa chữa, lắp ráp tủ điện.\n- Có kiến thức về tự động hóa.\n- Có thể làm ca.\n\nQuyền lợi:\n- LƯƠNG THỎA THUẬN KHI PHỎNG VẤN\n- Thời gian làm việc từ T2-T7.\n- Nghỉ 1 ngày/ tháng nguyên lương.\n- Được đóng bảo hiểm theo quy định của nhà nước.\n- Lương tháng thứ 13.\n- Thưởng tết, thưởng các ngày lễ, các ngày đặc biệt của công ty.\n- Làm việc trong môi trường chuyên nghiệp.\n- Luôn có cơ hội thăng tiến trong công việc nghề nghiệp.\n- Phỏng vấn và đi làm ngay nếu đạt yêu cầu.\n- Công việc ổn định và lâu dài.\n\nĐịa điểm làm việc:\n- Bắc Ninh: Lô J5, KCN Hoàn Sơn, Tân Hồng, Từ Sơn, Từ Sơn.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2761, 1188, 2, 'Lập Trình Viên Phần Mềm DEV PHP', '- Develop, customize and maintain modules on Vtiger CRM systems.\n- Design and deploy features and integrations within the Vtiger CRM system, including APIs and other software solutions.\n- Collaborate with internal teams to analyze and implement technical solutions related to customer data management.\n- Ensure data accuracy and integrity within the system.\n- Provide technical support and troubleshoot issues related to the system.\n- Create and maintain documentation related to CRM system architecture, configuration and customization with high security.\n\nYêu cầu ứng viên\n- Có từ 3 năm kinh nghiệm ở vị trí tương đương, từ 27 tuổi trở lên.\n- Stay up-to-date with CRM software industry trends and best practices.\n- Technologies used: PHP, JavaScript, Smarty, MySQL, Nodejs, Jquery, SocketIO, Webhook, API, Git…\n\nQuyền lợi\n- Thu nhập: Lương cứng (từ 10 triệu) + các loại phụ cấp: ăn trưa, di chuyển, điện thoại…\n- Tham gia các hoạt động vui chơi, du lịch của công ty theo tuần, quý, năm.\n- BHYT, BHXH, phép năm… đầy đủ theo đúng quy định.\n- Thưởng tháng T13, thưởng các dịp Lễ - Tết theo chính sách của Công ty.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Ree Tower, Quận 4\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2762, 1381, 2, 'Kỹ Sư Phần Mềm', '1. Kiến trúc hệ thống\n- Thiết kế kiến trúc phần mềm cho nền tảng điều phối AGV/AMR/xe nâng – có thể triển khai dạng cloud-based hoặc hybrid (cloud + on-premises).\n- Định nghĩa các tầng hệ thống: giao tiếp thiết bị (robotics control), xử lý nghiệp vụ (business logic), quản lý luồng hàng hóa (cargo workflows), tích hợp hệ thống (WMS/ERP), giao diện người dùng và APIs.\n- Lựa chọn công nghệ phù hợp (frameworks, message brokers, protocol layers, containerization...) đảm bảo khả năng mở rộng, hiệu năng và bảo mật.\n\n2. Quản lý nhóm IT\n- Quản lý nhóm IT, tổ chức và phân công công việc, kiểm soát tiến độ và chất lượng dự án.\n- Hướng dẫn và hỗ trợ kỹ thuật cho thành viên nhóm, xây dựng môi trường làm việc hiệu quả, học hỏi liên tục.\n\n3. Triển khai và tích hợp hệ thống\n- Thiết kế và xây dựng các module điều phối AGV/AMR dựa trên bản đồ nhà kho, thuật toán định tuyến, tránh va chạm và tối ưu nhiệm vụ.\n- Phát triển các cổng kết nối (connectors) với hệ thống WMS, ERP, PLCs và các thiết bị nhà kho khác qua REST, MQTT, OPC UA hoặc các giao thức tùy chỉnh.\n- Phối hợp với nhóm phần cứng và vận hành để kiểm thử và triển khai hệ thống tại thực địa (on-site deployment).\n\n4. Bảo trì và phát triển lâu dài\n- Thiết lập hệ thống giám sát, log, cảnh báo và cập nhật (CI/CD, observability tools).\n- Góp phần xây dựng lộ trình sản phẩm (product roadmap) và đề xuất cải tiến kiến trúc.\n\nYêu cầu ứng viên\n- Tối thiểu 5 năm kinh nghiệm phát triển phần mềm, trong đó có ít nhất 2 năm làm kiến trúc sư phần mềm hoặc team leader.\n- Có kinh nghiệm thiết kế hệ thống phân tán, sử dụng microservices, message queues (Kafka, RabbitMQ), container orchestration (Kubernetes).\n- Thành thạo một hoặc nhiều ngôn ngữ: Python, C++, Java, Go, Node.js.\n- Hiểu biết về giao tiếp với thiết bị IoT/robotics qua MQTT, WebSocket, ROS/ROS2 là lợi thế lớn.\n- Kinh nghiệm tích hợp với WMS/ERP, đặc biệt là SAP, Oracle, Odoo hoặc các hệ thống công nghiệp.\n\nQuyền lợi\n- Thu nhập: thỏa thuận và phụ cấp ăn trưa 30.000 đồng/ngày.\n- Thử việc: 60 ngày, được hưởng 85% lương cứng;\n- Đóng BHXH, BHYT, nghỉ phép hưởng lương theo quy định của Luật;\n- Chế độ phúc lợi: thưởng Lễ Tết, thưởng dự án, lương thứ 13, review lương 01 năm/lần hoặc đột xuất theo đề xuất và năng lực của nhân sự;\n- Chế độ du lịch, teambuilding hàng năm;\n- Được thử sức trong một môi trường làm việc trẻ trung, năng động với chính sách đãi ngộ tốt, có nhiều cơ hội nâng cao năng lực bản thân và tăng thêm thu nhập.\n\nĐịa điểm làm việc\n- Hà Nội: Cụm Công nghiệp Ngọc Hồi, Thanh Trì\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 2 - thứ 6 hàng tuần và 02 ngày thứ 7/tháng.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2763, 1448, 2, 'Senior Mobile Developer', 'Mô tả công việc\n- Phát triển ứng dụng di động bằng React Native hoặc ứng dụng web trên ReactJS/NextJS dựa trên các yêu cầu kỹ thuật và thiết kế đã được phê duyệt.\n- Phối hợp với các nhóm khác như UI/UX, QC, và BE để đảm bảo ứng dụng được phát triển một cách toàn diện.\n- Tham gia phân tích, thiết kế luồng phát triển của ứng dụng di động hoặc ứng dụng web dựa vào yêu cầu của sản phẩm.\n- Đánh giá, phân tích, nâng cấp và tối ưu mã nguồn trong quá trình phát triển.\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai.\n- Tham gia đưa ra những ý tưởng, giải pháp mới cải thiện công việc\n- Support team xử lý những vấn đề khó phát sinh trong quá trình phát triển giải pháp.\n- Thực hiện các công việc do trưởng bộ phận, quản trị dự án giao trong phạm vi công việc.\n\nYêu cầu ứng viên\n- Có ít nhất 4 năm kinh nghiệm hoặc tham gia các dự án Moblie, đặc biệt là React Native\n- Kinh nghiệm phát triển super app là một lợi thế\n- Có kiến ​​thức về HTML và CSS, Javascript, Bootstrap, Redux, Material UI.\n- Kinh nghiệm về React Native, ReactJs, NextJS, Kotlin hoặc Swift.\n- Kinh nghiệm xử lý Restful API, sử dụng các thư viện của bên thứ ba.\n- Kiến thức về OOP, thiết kế hệ thống, cấu trúc thuật toán và tối ưu hóa hiệu suất ứng dụng React Native.\n- Hiểu biết về cơ chế xác thực và ủy quyền, chẳng hạn như JWT, OAuth hoặc xác thực dựa trên phiên.\n- Hiểu biết về các nguyên tắc phát triển không đồng bộ và bảo mật dữ liệu.\n- Kiến thức về Firebase hoặc Onesignal.\n- Khả năng đóng góp và xây dựng các cải tiến UI/UX.\n- Kinh nghiệm trong ngành thanh toán là một lợi thế.\n- Kinh nghiệm làm việc theo phương pháp Agile/Scrum và sử dụng các công cụ quản lý dự án như JIRA hoặc Trello.\n- Hiểu biết về các nguyên tắc bảo mật ứng dụng và kinh nghiệm triển khai các giải pháp bảo mật.\n- Khả năng giao tiếp rõ ràng và hiệu quả, cả bằng văn bản lẫn nói, với các bên liên quan kỹ thuật và phi kỹ thuật.\n- Có tinh thần học hỏi không ngừng và khả năng thích nghi với các công nghệ mới nhanh chóng.\n- Chủ động, sáng tạo, nhiệt tình, trách nhiệm trong công việc.\n- Có khả năng phân tích, tư duy logic và giải quyết vấn đề\n- Sẵn sàng làm thêm giờ hoặc onsite khi có yêu cầu.\n\nQuyền lợi\n- Mức lương cạnh tranh theo đúng năng lực: từ 30,000,000 đến 40,000,000 VND/tháng\n- Môi trường làm việc thân thiện, năng động, có cơ hội phát triển bản thân và thăng tiến lên vị trí team leader, quản lý.\n- Cơ hội tiếp cận với các công nghệ mới, làm việc trong môi trường startup/công nghệ năng động\n- Ghi nhận thành tích, tăng lương và thưởng kịp thời.\n- Chế độ bảo hiểm đầy đủ, nghỉ phép theo quy định\n- Thưởng Lễ Tết, 30/4; 1/ 5; 2/9…. (theo tình hình hoạt động thực tế của Công ty)\n- Sinh nhật, ốm đau, sinh con, ma chay, hiếu hỉ theo mức quy định của Công ty.\n- Teambuilding, nghỉ mát….. (theo tình hình hoạt động thực tế của Công ty)\n- Được tham gia các khóa đào tạo do công ty tổ chức: kĩ năng mềm, nâng cao trình độ chuyên môn…\n- …………\n\nĐịa điểm làm việc\n- Hà Nội: 34 Nguyễn Khánh Toàn, Quan Hoa, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Thứ 7 làm việc luân phiên theo tuần\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2764, 1394, 2, 'Lập Trình Viên Java', 'Mô tả công việc\n- Tiếp nhận yêu cầu từ quản trị dự án và lãnh đạo công ty.\n- Tham gia thiết kế, triển khai các dịch vụ/giải pháp của dự án.\n- Chịu trách nhiệm đảm bảo kiến trúc hệ thống và xử lý các vấn đề kỹ thuật của các dự án.\n- Để xuất các giải pháp công nghệ, công cụ áp dụng trong phát triển sản phẩm.\n- Chịu trách nhiệm chính về các công nghệ mới, hỗ trợ kỹ thuật cho các thành viên trong nhóm.\n- Hỗ trợ, đào tạo và nâng cao năng lực chuyên môn cho các thành viên.\n\nYêu cầu ứng viên\n- Có ít nhất 4 năm kinh nghiệm với Java Spring\n- Có kiến thức về kiến trúc code tốt: OOP, Design Pattern, Design Principle, nắm vững Java Core\n- Ham tìm hiểu, có thể đọc được tài liệu kỹ thuật bằng tiếng Anh\n- Chính trực, nghiêm túc trong công việc\n- Ưu tiên đã có kinh nghiệm với AWS, VueJS/ReactJS\n\nQuyền lợi\n- Chế độ đãi ngộ:\n- Mức lương upto 45M\n- Nghỉ thứ 7, chủ nhật + ngày lễ, tết + 12 ngày phép/năm\n- Xét tăng lương 2 lần/năm vào tháng 1 và tháng 7, có năng lực sẽ được xét ngay tại thời điểm yêu cầu\n- Lương tháng 13, thưởng dự án, thưởng các dịp lễ, tết; thưởng giới thiệu nhân sự\n- Remote 2 ngày/tháng và trong một số trường hợp đặc biệt\n- Văn hóa và Môi trường làm việc:\n- Môi trường trẻ trung, năng động, thoải mái, tạo điều kiện để cá nhân phát triển năng lực nhất có thể\n- Tham gia các hoạt động thể thao nâng cao sức khỏe, teambuilding, dã ngoại, nghỉ mát.\n- Free trà, cà phê,.. \n- Đào tạo và cơ hội thăng tiến:\n- Công ty tổ chức buổi chia sẻ toàn công ty 1 lần/tháng nhằm nâng cao kỹ năng mềm và hiểu biết xã hội\n- Cơ hội phát triển lên Team leader\n- Được học hỏi nhiều kinh nghiệm về Kỹ thuật, quy trình, kỹ năng mềm từ người đi trước\n- Làm việc trực tiếp với CEO học hỏi tư duy về quản lý và kỹ năng chuyên môn\n- Được định hướng phát triển sự nghiệp theo Career Path của công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2765, 1231, 2, 'Nhân Viên Lập Trình Và Vận Hành Máy CNC', 'Mô tả công việc\n+ Lập trình, xuất chương trình vận hành máy tiện CNC\n+ Theo dõi quá trình máy chạy, sửa chương trình ngay khi phát hiện sự cố, đảm bảo thời gian chạy máy CNC\n+ Tối ưu quy trình công nghệ, đạt hiệu quả về thời gian gia công, chất lượng gia công, chế độ cắt, dụng cụ cắt gọt\n+ Báo cáo định mức thời gian hoàn thành một công đoạn\n+ Báo cáo khi Ban Giám đốc yêu cầu\n\nYêu cầu ứng viên\n+ Tốt nghiệp các ngành nghề kỹ thuật, cơ khí, chế tạo máy, cắt gọt kim loại\n+ Thành thạo lập trình tiện CNC\n+ Thành thạo phần mềm Mastercam\n+ Đọc hiểu bản vẽ gia công\n\nQuyền lợi\n+ Lương thỏa thuận theo kinh nghiệm và năng lực\n+ Lương tháng 13, thưởng lễ tết theo hiệu quả kinh doanh\n+ Chế độ BHXH, BHYT, BHTN theo quy định (công ty đóng 100%)\n+ Cơm trưa văn phòng (25.000 đồng/ ngày)\n+ Tăng ca theo Quy định của Nhà nước. Tiền ăn ca đêm 15.000 đồng/đêm (17h-20h)\n+ Cấp phát đồng phục, thiết bị phục vụ cho công việc tương ứng 750.000đ/năm\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 260/16 Tô Ngọc Vân, Linh Đông, Thủ Đức, Thủ Đức\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 07:30 đến 16:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2766, 1416, 2, 'Kỹ Sư Phần Mềm Ứng Dụng Desktop', 'Mô tả công việc\n1. Thiết kế phần mềm\n- Tham gia nghiên cứu/phát triển các phần mềm tích hợp của công ty trên hệ điều hành Windows/Linux\n- Nghiên cứu các công nghệ mới ứng dụng vào sản phẩm và dự án của công ty\n\n2. Các công việc khác\n- Phối hợp với các bộ phận liên quan để hoàn thành phần mềm và tham gia vào quá trình phát triển phần mềm\n- Thực hiện đào tạo nội bộ về phần mềm phát triển\n- Thực hiện báo cáo công việc theo định kỳ hoặc theo yêu cầu phát sinh\n- Thực hiện nhiệm vụ khác theo sự chỉ đạo của Trưởng/Phó phòng và Ban Lãnh đạo Công ty\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học loại Khá trở lên các chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm hoặc các chuyên ngành khác có liên quan\n- Ưu tiên thành thạo Java, Javascript, ...\n- Có khả năng làm việc độc lập và làm việc nhóm\n- Kỹ năng giao tiếp & truyền đạt thông tin tốt\n- Kỹ năng giải quyết vấn đề và tư duy logic\n- Sử dụng thành thạo tiếng Anh 4 kỹ năng: TOEIC 550 trở lên hoặc tương đương\n- Sử dụng thành thạo các phần mềm Office như Microsoft Word, Excel, Power Point...\n- Ưu tiên có kinh nghiệm về các kết nối mạng, giao tiếp phần cứng (như LAN, RS232/485,...)\n- Có kinh nghiệm làm việc với các dữ liệu bản đồ\n- Có khả năng làm việc độc lập và nhóm, ham học hỏi, kỷ luật tốt\n- Nhiệt huyết, chủ động, sáng tạo trong công việc, có khả năng chịu áp lực công việc cao\n- Có đam mê nghiên cứu và muốn làm việc trong môi trường chuyên nghiệp\n- Các ứng viên đã có nhiều năm kinh nghiệm tại vị trí tương đương với vị trí ứng tuyển\n- Các ứng viên tham gia và đạt các giải thưởng tại các cuộc thi cấp quốc gia, quốc tế\n- Các ứng viên đã có thời gian đào tạo, làm việc tại nước ngoài hoặc làm việc trong môi trường công ty nước ngoài\n\nQuyền lợi\n- Mức lương thỏa thuận\n- Lương tháng 13 + thưởng Performance theo quy định của công ty\n- Thưởng các dịp Lễ, Tết trong năm\n- Được nghỉ 12 ngày phép/ năm\n- Được tham gia BHXH, BHYT, BHTN theo quy định của Pháp luật\n- Được tham dự các khóa đào tạo nội bộ và khóa bồi dưỡng của ngành theo yêu cầu công việc\n- Được cử đi học, tham gia các khóa đào tạo nâng cao chuyên môn với chuyên gia trong nước và quốc tế\n- Được tham gia các hoạt động tập thể cùng công ty như: Du lịch, Team Building, New Year Party, các ngày Lễ trong năm,...\n- Được làm việc trong môi trường thân thiện, chuyên nghiệp\n- Cơ hội thăng tiến rõ ràng\n- Gửi xe miễn phí\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 6 tòa Detech Tower - Số 8, Tôn Thất Thuyết, Mỹ Đình 2, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2767, 209, 2, 'Senior React Native Good English', 'Mô tả công việc\n- Build pixel-perfect, buttery smooth UIs across both mobile platforms.\n- Leverage native APIs for deep integrations with both platforms.\n- Diagnose and fix bugs and performance bottlenecks for performance that feels native.\n- Reach out to the open source community to encourage and help implement mission-critical software fixes—React Native moves fast and often breaks things.\n- Maintain code and write automated tests to ensure the product is of the highest quality.\n- Transition existing React web apps to React Native.\n\nYêu cầu ứng viên\nMust have:\n- 5+ years of professional experience working with React Native.\n- Experience working with Swift, Objective C, and Java a plus but not required.\n- Meaningful experience working on large, complex systems.\n- Ability to take extreme ownership over your work. Every day is a challenge to ensure you are performing to the expectations you and your team have agreed upon, both in regards to estimates and to general process.\n- Ability to identify with the goals of FullStack clients, and dedicate yourself to delivering on the commitments you and your team make to them.\n- An understanding of React Native best practices and a commitment to following them.\n- Ability to work through new and difficult React Native issues and contribute to libraries as needed.\n- Ability to create and maintain continuous integration and delivery of React Native applications.\n- A positive mindset and can-do attitude.\n- Forensic attention to detail.\n- Good English\n\nNice to have:\n- Full-stack engineer with React and Node.js experience\n- Experience with at CSS preprocessors \n- Experience with Databases such as MongoDB or PostgreSQL\n\nQuyền lợi\n- “FPT care” health insurance provided by AON and is exclusive for FPT employees.\n- Annual Summer Vacation: follows company’s policy and starts from May every year\n- Salary review time/year or on excellent performance\n- International, dynamic, friendly working environment\n- Annual leave, working conditions follow Vietnam labor laws.\n- Other allowances: lunch allowance, working on-site allowance, etc.\n\nĐịa điểm làm việc\n- Đà Nẵng\n- Đồng Nai\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng, Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2768, 1469, 2, 'Trưởng Nhóm Lập Trình', '- Lên giải pháp, danh mục vật tư các thiết bị điện, lập bản vẽ đấu nối điện layout thiết bị, sử dụng phần mềm Eplan và Cad.\n- Lập trình PLC, HMI, Lập trình Robot 2-4-6 trục (Mitsubishi, Keyence, Omron, ABB, UR robot ...) và các thiết bị tự động hóa để điều khiển máy móc trong công nghiệp.\n- Lập trình điều khiển step motor, servo motor, Inverter và các thiết bị chuyển đổi Analog-Digital, các loại cảm biến và khí nén thủy lực...\n- Lập trình truyền thông công nghiệp RS485, RS232, Ethernet TCP/IP, Modbus,...\n- Lập trình xử lý ảnh, AI deep learning cho các ứng dụng kiểm tra lỗi sản phẩm, đọc mã vạch QR, Datamatrix, Barcode ... , nhận diện kí tự và tích hợp với robot để định vị trí sản phẩm để robot gắp đặt.\n- Setup Camera Vision , lựa chọn camera, lens, đèn phù hợp để thu được hình ảnh tốt nhất và lên cấu hình vision cho từng bài toán.\n- Lập trình thiết kế phần mềm máy tính, visual studio C++, C#, SQLServer,...\n- Lập trình quản lý hệ thống nhà máy, server truyền thông công nghiệp, lưu trữ truy xuất dữ liệu\n- Lập kế hoạch dự án, sắp xếp công việc cho các thành viên trong nhóm, quản lý chặt tiến độ dự án\n- Đào tạo kỹ năng khảo sát, hướng dẫn thiết kế, lắp ráp chế tạo máy và xử lý sự cố cho các thành viên\n- Giám sát, kiểm tra và chịu trách nhiệm chính về giải pháp 3D, bản vẽ 2D, bản vẽ điện, gia công, báo cáo kế hoạch, các vấn đề kỹ thuật, các vấn đề phát sinh cho từng dự án\n- Tính toán đánh giá rủi ro về thiết kế, chế tạo, triển khai cho từng dự án\n- Trao đổi công việc với các bộ phận liên quan, đối tác, khách hàng trong quá trình triển khai\n\nYêu cầu ứng viên:\n- Có kinh nghiệm trực tiếp thiết kế máy tự động hóa cho các Công ty làm máy hoặc Công ty FDI (ngành điện, điện tử, bán dẫn...), đặc biệt các máy yêu cầu độ chính xác cao (kết hợp robot, thiết bị đo kiểm, lắp ráp...)\n- Thành thạo lập trình các dòng PLC Mitsubishi, Keyence. Điều khiển các thiết bị công nghiệp.\n- Thành thạo sử dụng Biến tần, Servo và các thiết bị điều khiển động cơ khác.\n- Hiểu biết về các loại truyền thông công nghiệp..\n- Ưu tiên biết lập trình Vision: Python, C++ trên nền tảng ROS. Các ứng dụng liên quan tới Web-Base, Database, IOT.\n- Có kinh nghiệm quản lý nhóm, quản lý chất lượng, tiến độ dự án là một lợi thế.\n\nQuyền lợi:\n- Mức lương cạnh tranh, phù hợp với năng lực và kinh nghiệm\n- Được đóng BHXH, BHYT, BHTN theo quy định của nhà nước\n- Thưởng các ngày lễ, Tết và thưởng theo hiệu quả công việc\n- Được đào tạo và phát triển kỹ năng chuyên môn\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội thăng tiến rõ ràng\n- Được tham gia các hoạt động team building, du lịch hàng năm\n\nĐịa điểm làm việc:\n- Hà Nội: 11TT16 Foresa 8, Xuân Phương, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Làm việc 2 thứ 7/ tháng\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2769, 1381, 2, 'Kỹ Sư IT Fullstack', 'Mô tả công việc:\n- Phát triển và bảo trì hệ thống quản lý nhà kho/xe tự hành cho cả ứng dụng web và desktop.\n- Xây dựng các dashboard và công cụ trực quan hóa để theo dõi trạng thái kho, vị trí xe tự hành và hoạt động vận hành theo thời gian thực.\n- Thiết kế các tính năng để kết nối giao diện với dữ liệu backend, đảm bảo luồng thông tin mượt mà.\n- Quản lý và tối ưu cơ sở dữ liệu để lưu trữ, truy xuất thông tin hiệu quả.\n- Đảm bảo hệ thống vận hành ổn định, an toàn và dễ dàng mở rộng.\n- Làm việc với đội UI/UX và kỹ sư hệ thống để tạo ra sản phẩm đáp ứng nhu cầu thực tế.\n- Kiểm thử, sửa lỗi và đề xuất cải tiến dựa trên phản hồi từ người dùng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp từ Đại học trở lên chuyên ngành Công nghệ thông tin, kỹ thuật phần mềm, khoa học máy tính...\n- Từ 2 năm làm việc tại các công ty/tập đoàn kinh doanh IT Outsourcing/IT Product.\n- Nắm rõ và sâu về các kiến thức cơ bản: HTML, CSS, OOP, DI... Có hiểu biết về một số design pattern, cơ sở đồ họa...\n- Thành thạo ngôn ngữ lập trình Java hoặc JavaScript.\n- Có kinh nghiệm làm việc phát triển desktop app với các công nghệ như: Java Swing, JavaFX, ElectronJs...\n- Có kinh nghiệm làm việc với một trong các frontend framework: Angular, React/NextJs, Vue.\n- Có kinh nghiệm làm việc với một số thư viện editor như JhotDraw, GoJs, JointJs...\n- Có kinh nghiệm vận hành sản phẩm IT on premise/cloud, có hiểu biết và làm việc với Docker và các tool CI/CD (Jenkins, CircleCI...) là một lợi thế.\n- Có hiểu biết cơ bản về kiểm thử phần mềm.\n- Có kinh nghiệm làm việc với một số nền tảng cung cấp dịch vụ đám mây: AWS, MS Azure... là một lợi thế.\n- Có kinh nghiệm làm việc với các sản phẩm IoT là một lợi thế.\n- Có khả năng đọc hiểu các tài liệu tiếng Anh chuyên ngành.\n- Các kỹ năng giải quyết vấn đề, làm việc nhóm, nghiên cứu...\n\nQuyền lợi:\n- Thử việc: 60 ngày, được hưởng 85% lương cứng;\n- Hỗ trợ ăn trưa 30.000 đồng/ngày.\n- Đóng BHXH, BHYT, nghỉ phép hưởng lương theo quy định của Luật;\n- Chế độ phúc lợi: thưởng Lễ Tết, thưởng dự án, lương thứ 13, review lương 01 năm/lần hoặc đột xuất theo đề xuất và năng lực của nhân sự;\n- Chế độ du lịch, teambuilding hàng năm;\n- Được thử sức trong một môi trường làm việc trẻ trung, năng động với chính sách đãi ngộ tốt, có nhiều cơ hội nâng cao năng lực bản thân và tăng thêm thu nhập.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2770, 1201, 2, 'Lập Trình Backend', '• Phát triển ứng dụng desktop đa nền tảng sử dụng Node.js và SQLite.\n• Thiết kế kiến trúc phần mềm hiệu năng cao, tối ưu bộ nhớ và CPU cho các tác vụ nặng.\n• Thực thi giải pháp caching, xử lý đồng thời và bảo trì hệ thống lâu dài.\n• Quản lý luồng xử lý, ngăn chặn memory leak, nâng cao độ ổn định ứng dụng.\n• Phối hợp với team để triển khai giao diện người dùng và backend tích hợp.\n• Ưu tiên ứng viên đã từng làm việc với Electron.js.\n- Thời gian làm việc:\n+ Từ Thứ hai đến Thứ Sáu: Từ 8h00’ đến 17h30’\n+ Thứ Bảy : Từ 8h00’ đến 12h00’\n+ Trưa nghỉ từ 12h00\' đến 13h30\' \n• Tối thiểu 2 năm kinh nghiệm với Node.js trong môi trường sản phẩm thực tế.\n• Hiểu rõ mô hình bất đồng bộ: Callback, Promise, Async/Await.\n• Có kinh nghiệm với SQLite, hiểu ORM và ưu tiên biết TypeORM.\n• Có hiểu biết về caching (in-memory hoặc disk), tối ưu CPU usage.\n• Biết phát hiện và xử lý memory leak, hiểu lifecycle trong Node.js.\n• Có tư duy về thiết kế ứng dụng high performance: phân luồng, chia module, reuse tài nguyên.\n• Biết sử dụng Git, đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.\n- Lương:15.000.000 – 20.000.000\n- Phỏng vấn 1 vòng duy nhất.\n- Lộ trình thăng tiến lên Sublead, Leader\n- Review lương 2 lần /năm, thưởng nóng hàng tuần, hàng tháng, hàng năm khi đạt thành tích xuất sắc cá nhân hay đội nhóm.\n- Thưởng tháng lương thứ 13, bảo hiểm, chế độ du lịch hàng năm theo chương trình của công ty.\n- Được khám sức khỏe định kỳ tại bệnh viện đa khoa Quốc tế. Được hỗ trợ 50 -100% chi phí sau bảo hiểm nếu không may phải nằm viện.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4, tòa nhà Stellar Garden số 35 Lê Văn Thiêm, Thanh Xuân Trung, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 7 (từ 08:00 đến 12:00)\n- Nghỉ giữa ca: 12h00 - 13h30.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2771, 1126, 2, 'Nhân Viên Lập Trình', 'Mô tả công việc:\n- Nghiên cứu, cải tiến sản phẩm phần mềm hiện có của Công ty.\n- Xây dựng sản phẩm theo đơn đặt hàng của Khách hàng.\n- Triển khai và hướng dẫn và hỗ trợ Khách hàng sử dụng phần mềm.\n- Giờ làm việc là 8h30-12h, 13h30-17h30 từ thứ 2 – thứ 6, Thứ 7 làm buổi sáng.\n- Công việc cụ thể sẽ trao đổi rõ hơn lúc phỏng vấn.\n\nYêu cầu ứng viên:\n1. Tốt nghiệp đại học/cao đẳng chuyên ngành công nghệ thông tin;\n2. Sử dụng thành thạo các ngôn ngữ lập trình .NET C#, VB.NET. Ưu tiên biết cả hai;\n3. Có kinh nghiệm làm việc với MS SQL và tối ưu truy vấn;\n4. Có kiến thức về phân tích thiết kế lập trình và quy trình phát triển phần mềm;\n5. Có khả năng nghiên cứu và nắm bắt các công nghệ mới;\n6. Khả năng tiếng anh đọc hiểu tốt, giao tiếp căn bản;\n7. Ưu tiên các ứng viên có thể đi công tác thường xuyên.\n\nQuyền lợi:\n- Đội ngũ lãnh đạo, quản lý đầy tài năng và nhiệt huyết, luôn trọng dụng nhân tài.\n- Môi trường làm việc năng động, chuyên nghiệp.\n- Lương thưởng xứng đáng theo năng lực.\n- Hưởng đầy đủ BHXH và các chế độ chính sách khác theo quy định của Bộ Luật lao động và công ty;\n- Được nghỉ 15 (mười lăm) ngày phép vẫn hưởng nguyên lương.\n- Thưởng cuối năm, thưởng dự án, thưởng hiệu suất,.. theo thành tích công việc;\n- Môi trường trẻ trung, năng động: Teambuilding hàng năm, Du lịch kỉ niệm ngày thành lập công ty, Year End Party, hoạt động vui chơi, giải trí hấp dẫn khác.\n- Được tham gia các khóa đào tạo kỹ năng, đào tạo nâng cao chuyên môn đáp ứng nhu cầu công việc.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Số 34 Đường Võ Thị Đặng, Phường Tân Phong TP HCM (Số cũ : Số 34 đường 32, P. Tân Phong, Quận 7)\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Thứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2772, 1348, 2, 'Lập Trình Viên Developer', 'Mô tả công việc:\n- Một số nội dung công việc chính:\n- Trực tiếp phát triển phần mềm iDentalsoft theo team Dev hiện tại,\n- Phụ trách Coding, R&D, cải tiến Features có sẵn,...\n- Nghiên cứu viết tool và migrate database cho khách hàng mới,\n- Nghiên cứu & phát triển tính năng mới cho phần mềm iDentalsoft\n- Cải tiến & nâng cao hiệu quả phần mềm iDS\n- Nghiên cứu & cải tiến công nghệ để phát triển sản phẩm trên nền tảng Web Cloud, Window và cả Mobile\n- Nghiên cứu phát triển thêm nhiều tính năng khác cho phần mềm iDS\n\nYêu cầu ứng viên:\n- Kỹ thuật:\n- Có kiến thức về Java, C# (Chính)\n- Có kiến thức về OOB, MySQL\n- Có kỹ năng research\n- Có kỹ năng phân tích, ham học hỏi, làm việc độc lập\n- Có kỷ luật, có khả năng đảm bảo deadline\n\n- Cơ bản:\n- Tốt nghiệp đại học, cao đẳng chuyên ngành Software, IT, Engineer\n- Chấp nhận người mới ra trường. Có kinh nghiệm 1-2 năm càng tốt\n- Chấp nhận bằng cấp tất cả các trường ĐH, CĐ\n\nQuyền lợi:\n- Được hưởng Lương xứng đáng với năng lực\n- Lương rất cạnh tranh \n- Chế độ nâng lương hàng năm và nâng lương đột xuất (đối với cá nhân xuất sắc)\n- Có lương tháng 13 hàng năm\n- Có chế độ thưởng đột xuất\n- Được hưởng Bảo hiểm y tế và bảo hiểm xã hội theo quy định\n- Được đi du lịch hàng năm\n- Công ty có tổ chức Team Building thường xuyên\n- Môi trường làm việc tự do, năng động, theo hiệu quả công việc\n- Có cơ hội học hỏi và phát triển bản thân\n- Đồng nghiệp vui tính, hỗ trợ lẫn nhau\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lầu 6, 15/28 Đoàn Như Hài, Phường 13, Quận 4\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 19:00 đến 06:00)\n- Làm Ca đêm full time, Mỗi ca 8 tiếng; Ca 1 từ 7pm đến 3am, Ca 2 từ 10pm đến 6am\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2773, 1409, 2, 'Fresher Fullstack Developer (English Fluent)', 'Mô tả công việc:\n- Tham gia đào tạo lý thuyết và on job training từ 3 tháng để học về lập trình Fullstack (Javascript) từ cơ bản đến nâng cao.\n- Tham gia vào các dự án lớn của công ty và của khách hàng quốc tế với domain đa dạng.\n- Các công việc khác được giao bởi quản lý trực tiếp.\n\nYêu cầu ứng viên:\n- Sinh viên năm cuối hoặc đã tốt nghiệp trong lĩnh vực Công nghệ thông tin hoặc các ngành liên quan.\n- Tiếng Anh tốt, đặc biệt là kĩ năng giao tiếp.\n- Nắm rõ cơ bản lập trình (Cơ sở dữ liệu, cấu trúc database), javascript, HTML, CSS.\n- Nắm cơ bản lập trình hướng đối tượng.\n- Có các project lập trình web.\n- Good to have: đã từng làm react, nextjs, python, nodejs.\n\nQuyền lợi:\n- Nhận trợ cấp bằng tiền mặt hàng tháng theo năng lực lên.\n- Được tham gia làm các dự án lớn và đa dạng của các khách hàng quốc tế.\n- Cơ hội trở thành nhân viên sau khi hoành thành chương trình đào tạo.\n- Có cơ hội đi onsite tại Châu Âu, Úc, Singapore, Nhật Bản khi trở thành nhân viên.\n- Được làm trong môi trường Văn hóa chuyên nghiệp, trẻ trung và năng động.\n- Trải nghiệm công nghệ mới nhất về Thương mại điện tử.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2774, 1164, 2, 'Full-Stack Java Developer', 'Mô tả công việc:\n- Translate application user stories into functional applications.\n- Design, build, and maintain efficient, reusable, and reliable Java code.\n- Ensure the best possible performance, quality, and responsiveness of the applications.\n- Identify bottlenecks and bugs, and devise solutions to these problems.\n- Maintain code quality, organization, and automatization.\n- Write and maintain high quality unit tests.\n- Perform code review Adhere to the acceptance criteria and the Definition of Done.\n\nYêu cầu ứng viên:\n- Have at least 5 years of experience in a Java Developer.\n- Proficient in Java/JEE and Spring framework, with a good knowledge of its ecosystems.\n- Strong understanding of object-oriented programming.\n- Familiar with various design and architectural patterns.\n- Skill for writing reusable Java libraries.\n- Knowledge of concurrency patterns in Java.\n- Familiarity with concepts of MVC, JDBC, and RESTful.\n- Proficiency with SQL, Hibernate, JPA.\n- Experience with both external and embedded databases.\n- Understanding fundamental design principles behind a scalable application.\n- Creating database schemas that represent and support business processes.\n- Implementing automated testing platforms and unit tests.\n- Proficient understanding of code versioning tools, such as Git.\n- Ability to clearly communicate with both technical and non-technical team members.\n\nOther Requirements:\n- Experience with Agile Scrum.\n- Experience with Ember or other JavaScript.\n- Familiarity with build tools such as Ant, Maven, and Gradle.\n\nQuyền lợi:\n- The attractive salary (Negotiation).\n- 2-month probation period with 100% salary.\n- Full salary insurance coverage after the probation period.\n- Participation in the PVI health insurance package, and annual health check-ups.\n- 13th-month salary, birthday bonus, New Year bonus, Mid-Autumn Festival gifts, March 8th and October 20th gifts, etc.\n- Performance evaluation and regular salary increases.\n- Welfare for personal events, childbirth, and other benefits as per labor regulations and company welfare policies.\n- Dynamic and youthful work environment conducive to personal growth and development.\n\nĐịa điểm làm việc:\n- Hà Nội: 27th Floor, East Tower, Lotte Center Hanoi, 54 Lieu Giai, Ba Đình.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n- Flexible working hours may apply depending on project (e.g., 1:00 PM – 9:00 PM).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2775, 1396, 2, 'Chuyên Viên Lập Trình', 'About this Role:\nWe are seeking a skilled JavaScript Developer with a solid background in cloud-based application development in GCP, specifically using Google Developer tools. The ideal candidate has a strong understanding and use of Google API library, OAuth vs JWT authentication mechanisms, and hands-on experience with ReactJS preferred but other frameworks (Angular, Vue) are acceptable.\nIf you\'re passionate about building scalable web apps and have delivered impactful projects, we’d love to meet you!\n\nKey Responsibilities:\n- Design and develop front-end and/or back-end components using JavaScript and a modern framework, preferably ReactJS other frameworks (Angular, Vue, etc.) are acceptable\n- Integrate third-party and internal RESTful APIs and ensure secure, scalable data flow\n- Work with Google Cloud and Developer tools (such as Firebase, Cloud Functions, Cloud Storage, etc.) to build cloud-native applications\n- Implement and integrate applications using OAuth and JWT-based authentication flows\n- Collaborate with cross-functional teams to define and ship new features\n- Debug and optimize existing applications for speed, scalability, and usability\n- Maintain clear documentation for all development work and project progress\n\nKey Requirements:\n- 2 years of professional JavaScript development experience\n- Proficient in at least one JavaScript framework (e.g., React, Angular, Vue)\n- Strong experience working with Google Cloud Platform (GCP) and Google Developer tools and services\n- Solid experience with RESTful APIs integration\n- Clear understanding of OAuth vs JWT – use cases, flows, and security implications\n- Must be able to communicate effectively in English and Vietnamese\n- Familiar with Git, CI/CD, and agile workflows\n- Strong problem-solving and interpersonal skills\n- Immediate availability is a strong plus\n\nBenefits:\n- Work on cutting-edge, cloud-native applications\n- Collaborative, international team environment\n- Fast-paced learning and direct product impact\n- Competitive compensation\n\nWorking Location:\n- Hà Nội: Nguyễn Chí Thanh, Đống Đa\n\nWorking Hours:\n- Monday to Friday (from 08:30 to 18:00)\n\nApplication Method:\nCandidates can submit applications online by clicking the "Apply" button below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2776, 1194, 2, 'Java Developer (Junior)', 'Mô tả công việc\n- Tham gia các dự án phát triển và triển khai các giải pháp cho công ty và đối tác\n- Tham gia và hoàn thành đúng yêu cầu các dự án được giao.\n- Thực hiện đúng chế độ lập kế hoạch và báo cáo công việc theo quy định.\n- Thực hiện công việc khác theo chỉ đạo và yêu cầu của người quản lý trực tiếp.\n\nYêu cầu ứng viên\n- Trình độ: Tốt nghiệp ĐH chuyên ngành công nghệ thông tin\n- Kinh nghiệm làm việc: \n+ Có kinh nghiệm tham gia các dự án phát triển trên nền tảng Java\n+ Có khả năng phân tích yêu cầu nghiệp vụ để phát triển chức năng hệ thống\n+ Có kinh nghiệm sử dụng framework như: Spring, Hibernate...\n+ Có kinh nghiệm với Angular JS, React Js ...\n+ Có kiến thức về cơ sở dữ liệu như: Oracle, MySQL, MongoDB,...\n\n- Kỹ năng:  \n+ Khả năng giao tiếp, truyền đạt tốt\n+ Kỹ năng làm việc nhóm và làm việc độc lập\n+ Kỹ năng tổ chức và quản lý thời gian\n+ Khả năng làm việc dưới áp lực\n\n- Thái độ:  Chăm chỉ, nhiệt tình, hòa đồng và có trách nhiệm trong công việc.\n- Trách nhiệm đảm bảo an toàn thông tin: Tuân thủ các quy định, quy chế về an toàn thông tin của Công ty\n\nQuyền lợi\n- Mức lương: 8-20tr\n- Lương tháng thứ 13, thưởng lễ tết, thưởng hiệu quả kinh doanh theo quy định và theo kết quả kinh doanh của Công ty\n- Chế độ bảo hiểm xã hội đầy đủ theo quy định của pháp luật.\n- Tham gia các chương trình Teambuilding khác tại công ty\n- Tham gia các chương trình Sinh nhật, Noel, Year and Party...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2777, 1363, 2, 'Java Developer', 'Mô tả công việc\n- Phát triển sản phẩm phần mềm trên nền tảng Java Strust….cho các đối tượng khác nhau\n- Tham gia vào các giai đoạn của dự án: Phân tích, thiết kế, lập trình, bảo trì phần mềm\n- Lập trình các module theo thiết kế và công việc được phân công\n- Tài liệu hóa các đặc tả thiết kế và chức năng\n\nYêu cầu ứng viên\n- Từ 2 năm kinh nghiệm trở lên làm việc với các framework: Springboot, Hibernate, RESTAPI\n- Kinh nghiệm làm việc với Backend, API\n- Có kĩ năng phân tích yêu cầu\n- Có thể review code, phân tích lỗi và đề xuất các giải pháp cho các module phần mềm đơn giản\n- Có kỹ năng phân tích hệ thống vả thiết kế cơ bản. Có thể tham gia làm thiết kế chi tiết dựa trên đặc tả yêu cầu (SRS) và thiết kế kiến trúc (SAD)\n\nQuyền lợi\n- Lương thỏa thuận (upto 25tr)\n- Được cung cấp đầy đủ thiết bị làm việc\n- Thưởng hiệu quả công việc, thưởng dự án\n- Teambuilding 2 lần/năm\n- Tham gia đầy đủ BHXH: BHTN, BHYT, BHTS…\n- Tham gia các hoạt động chung của công ty: Du lịch, 20/10, ngày nam giới, trung thu, giáng sinh, ngày nam giới.....\n- Được thử thách trong dự án lớn, có cơ hội khẳng định bản thân và phát triển sự nghiệp\n- Môi trường làm việc chân thành, cởi mở, gắn bó giúp đỡ nhau cùng phát triển\n\nĐịa điểm làm việc\n- Hà Nội: 25 Trần Hưng Đạo, Hoàn Kiếm, Hoàn Kiếm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2778, 1226, 2, 'Playable Ads Developer (Junior Up)', 'Mô tả công việc\n- Nghiên cứu kịch bản và xây dựng kế hoạch sản xuất Playable Ads trên các nền tảng như Facebook, Google, Unity Ads,...\n- Tham gia thiết kế, lập trình và tối ưu playable với hiệu suất nhẹ, tương thích cao\n- Phối hợp cùng team Marketing, Creative để đảm bảo playable đáp ứng đúng mục tiêu chiến dịch\n- Phân tích dữ liệu A/B testing để đánh giá hiệu quả quảng cáo và đề xuất cải tiến\n- Tìm hiểu, cập nhật xu hướng thiết kế/motion/code trong lĩnh vực quảng cáo tương tác và game marketing\n\nYêu cầu ứng viên\nKnowledge:\n- Tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán-Tin hoặc các lĩnh vực kỹ thuật liên quan\n- Tối thiểu 1 năm kinh nghiệm làm việc ở vị trí tương đương (Unity, Playable Ads)\n- Hiểu rõ quy trình phát triển sản phẩm Playable Ads, hành vi người dùng trong môi trường tương tác ngắn\n- Nắm vững lập trình hướng đối tượng, vòng đời sản phẩm và tối ưu hóa hiệu suất\nSkills\n- Thành thạo lập trình gameplay, UI tương tác và các animation logic đơn giản\n- Biết debug nhanh, tối ưu CPU/memory usage, quản lý asset nhẹ, dùng hiệu quả\n- Có tư duy hệ thống: viết code có cấu trúc tốt, dễ mở rộng và tái sử dụng\n- Ưu tiên nếu có khả năng xây dựng template, thư viện nội bộ hoặc tool hỗ trợ production\nAttitude\n- Chủ động, cầu tiến và có trách nhiệm cao với chất lượng sản phẩm đầu ra\n- Không ngại thử nghiệm, chỉnh sửa nhanh theo vòng lặp A/B testing\n- Có đam mê với game, hứng thú với sản phẩm mang tính tương tác cao, đo lường hiệu suất\n- Mong muốn phát triển lâu dài trong lĩnh vực Performance Creative/Game Tech\n\nQuyền lợi\n- Mức lương: Up to $800\n- Nhận 100% lương cứng, tăng lương theo quy định của công ty\n- Phụ cấp ăn trưa nhân viên chính thức: 1.000.000 VNĐ/tháng\n- Thu nhập dựa theo kết quả và hiệu suất công việc\n\nCƠ HỘI PHÁT TRIỂN\n- Mở rộng, nâng cao kiến thức và kỹ năng chuyên môn\n- Trải nghiệm thực chiến tại các dự án toàn cầu đang chạy\n- Có lộ trình phát triển sự nghiệp được cá nhân hóa rõ ràng\n\nMÔI TRƯỜNG LÀM VIỆC\n- Trải nghiệm môi trường quốc tế năng động, chuyên nghiệp\n- Hưởng 100% đãi ngộ chăm sóc đời sống hàng ngày\n\nCHÍNH SÁCH PHÚC LỢI\n- Công ty đóng đầy đủ các loại Bảo hiểm theo quy định của pháp luật (BHXH, BHYT, BH thất nghiệp,..)\n- Được khám sức khỏe tổng quát định kì miễn phí tại bệnh viện: Hồng Ngọc, Thu Cúc, Vinmec.\n- Chế độ cưới hỏi/đám hiếu, quà ngày Lễ/ Tết và các chế độ phúc lợi khác.\n- Thưởng Tết dương, 8/3, 30/4-1/5, Trung thu, giữa năm, 2/9, 20/10, Giáng sinh.\n- Chia sẻ thành quả liên tục, không giới hạn dựa trên performance.\n- Thời gian làm việc hành chính:\n- Từ Thứ 2 - Thứ 6. Nghỉ Thứ 7, Chủ Nhật\n- Sáng: 8:30 - 12:00, Chiều: 13:00 - 18:00, Nghỉ giữa chiều 15:00 - 15:30\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 10 - The West Tower - 265 Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2779, 1252, 2, 'Nhân Viên Kỹ Thuật Cơ Khí', '-  Nhận bản vẽ, lập chương trình trên máy CNC (máy tiện, máy phay), lên gá, gia công, kiểm tra kích thước.\n-  Kiểm tra các chương trình, chạy thử nghiệm trước khi chạy chính thức trên máy và tiến hành gia công các sản phẩm\n- Thực hiện việc thay đổi các dụng cụ cắt gọt dùng trong gia công cơ khí chính xác\n- Thực hiện những công việc khác do lãnh đạo sắp xếp.\n\nYêu cầu ứng viên:\n- Tốt nghiệp trung cấp chuyên ngành cơ khí.\n- Có kinh nghiệm 3 năm trở lên.\n- Có khả năng làm việc độc lập.\n- Đọc hiểu bản vẽ cơ khí.\n\nQuyền lợi:\n- Mức lương: tùy theo năng lực của ứng viên\n- Xét nâng lương định kỳ theo thâm niên.\n- Thưởng trung thu.\n- Thưởng doanh số (nếu đạt doanh thu).\n- Thưởng tháng 13 theo tổng lương (không bao gồm tiền chuyên cần, giao thông, nhà ở).\n- Trợ cấp hiếu hỷ từ 600,000 đến 900,000 đồng.\n- Phép năm từ 12 đến 14 ngày/năm (tùy bộ phận)\n- Tham gia BHXH, BHYT, BHTN theo tổng lương (không bao gồm tiền chuyên cần, giao thông, nhà ở).\n\nĐịa điểm làm việc:\n- Đồng Nai: KCN Nhơn Trạch 3, Nhơn Trạch\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Nai, Nhơn Trạch', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2780, 1139, 2, 'Flutter Developer (Từ 06 Tháng Kinh Nghiệm) - Offer Upto $1000', 'Mô tả công việc:\n- Phát triển ứng dụng di động sử dụng Flutter theo phân sự phân công của Team Leader.\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động.\n- Phát triển các ứng dụng một cách linh hoạt, có cấu trúc tốt, mã nguồn và thư viện có thể tái sử dụng trong tương lai.\n- Tối ưu hoá hiệu suất và đảm bảo ứng dụng tương thích trên cả Android và iOS..\n- Lập trình các module tính năng theo bản phân tích thiết kế.\n\nYêu cầu ứng viên:\n- Có từ 6 tháng kinh nghiệm phát triển ứng dụng bằng Flutter.\n- Thành thạo ít nhất một trong các state management (Provider. Bloc, GetX,...).\n- Hiểu biết tốt về các UI components & customization/animation, thiết kế giao diện người dùng cho nhiều loại thiết bị có màn hình khác nhau.\n- Có tư duy logic tốt, có khả năng phân tích và giải quyết vấn đề.\n- Hiểu biết Design Pattern, SOLID.\n- Có kiến thức tốt về Data Structures & Algorithm.\n- Có kinh nghiệm tối ưu performance, memory cho ứng dụng.\n- Có kinh nghiệm tích hợp Firebase, Admob, Subscription và In-App Purchases là một lợi thế.\n- Ưu tiên ứng viên có kinh nghiệm về native (Swift hoặc Kotlin/ Java).\n- Có kỹ năng làm việc nhóm, làm việc độc lập, có khả năng tự học hỏi và cập nhật các công nghệ mới.\n- Có đam mê phát triển sản phẩm product.\n\nQuyền lợi:\n- Offer upto 1000$ + trợ cấp ăn trưa + trợ cấp đi lại.\n- Tháng lương 13.\n- Thưởng Tết Âm Lịch từ 01 - 05 tháng lương.\n- Thưởng các ngày lễ: 30/04, 01/05, 02/09, Tết Dương, 08/03, 20/10,... áp dụng cho tất cả nhân sự (chính thức, thử việc, thực tập sinh).\n- Thử việc tối đa 02 tháng 100% lương, có phép trong thời gian thử việc.\n- Được cung cấp hoàn toàn trang thiết bị phù hợp với vị trí công việc.\n- Review hiệu suất & lương thưởng định kỳ 2 lần/năm (tháng 1 & tháng 7).\n- Bảo hiểm, nghỉ lễ, phúc lợi đầy đủ theo quy định pháp luật, được cung cấp các gói khám sức khỏe định kỳ khi trở thành nhân viên chính thức.\n- Startup năng động, tinh thần sáng tạo và nhiệt huyết.\n- Được đào tạo 1-1 bởi leader giàu kinh nghiệm từng làm tại công ty Tech lớn.\n- Cơ hội phát triển và tham gia vào các sản phẩm có hàng triệu - chục triệu người dùng trên toàn cầu.\n- Miễn phí trà, cafe, nước ngọt tại Pantry.\n- Có cơ hội tham gia rất nhiều các CLB do công ty tổ chức và tài trợ: Bóng đá, bóng bàn, Bi-a, Board game, Chạy bộ, cầu lông....\n- Khu vực vui chơi với Bàn Bi-a siêu xịn, bàn bóng bàn, PS4 và nhiều bộ môn hấp dẫn khác\n- Team building/du lịch mỗi 3 tháng – Công ty tài trợ 100% chi phí.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4 Tòa Garden Hill, số 99 Trần Bình, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Thứ 7 (từ 08:30 đến 12:00)\n- 2 buổi sáng Thứ 7 cách tuần: 8h30 - 12h00.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2781, 1256, 2, 'Java Developer', 'Mô tả công việc\nPhát triển dịch vụ web bằng JAVA, Front-end sử dụng HTML, CSS, JavaScript, Jquery,..\nSử dụng Spring Boot, Framework, mô hình MVC\nTham gia phát triển, đề xuất giải pháp kỹ thuật cho các dự án\nPhát triển các hệ thống mới và nâng cấp các hệ thống đã có\nLàm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của Leader\n\nYêu cầu ứng viên\nTrình độ đại học, cao đẳng chuyên ngành CNTT hoặc các chứng chỉ tương đương trở lên\nTừ 02 năm kinh nghiệm về phát triển dịch vụ web với JAVA framework, yêu thích việc lập trình bằng ngôn ngữ JAVA\nCó kiến thức về design patterns và unit test (Junit, TestNG, NUnit)\nNắm vững về HTML, CSS, JavaScript, Jquery là một điểm cộng (các ngôn ngữ khác, nếu không thành thạo sẽ được đào tạo)\nKhả năng tự nghiên cứu, phân tích và giải quyết vấn đề\nCó khả năng tư duy logic và lập trình\nKhả năng làm việc độc lập hoặc theo nhóm\nSẵn sàng học hỏi các công nghệ mới cần thiết cho công việc\nCó kiến thức về Spring/Spring Boot, MySQL, Oracle,...\n\nQuyền lợi\nMức lương: 30 triệu, tùy theo năng lực\nThử việc lên đến 100% lương\nPhụ cấp cơm trưa và vé gửi xe hàng tháng\nCung cấp đầy đủ các thiết bị phục vụ cho công việc\nNghỉ thứ 7, chủ nhật\nĐóng BHXH sau khi thử việc và hưởng các chế độ phúc lợi theo luật lao động Việt Nam\nĐánh giá xét tăng lương 2 lần/năm\nHưởng lương tháng 13\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Bình Thạnh\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Thạnh, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2782, 1130, 2, 'Mobile Developer (Middle/Senior) - IOS/Android', 'Mô tả công việc\nTham gia vào toàn bộ vòng đời phát triển sản phẩm, từ lên ý tưởng, thiết kế, phát triển đến triển khai và bảo trì ứng dụng di động trên cả hai nền tảng iOS và Android.\nPhối hợp trực tiếp với Development Lead để nhận định, lên kế hoạch và triển khai các tác vụ công việc hàng ngày.\nTối ưu hiệu năng (performance) và trải nghiệm người dùng (UX/UI) cho ứng dụng, đảm bảo khả năng đáp ứng lượng truy cập lớn (2 triệu MAU).\nXây dựng và triển khai các tính năng mới, đồng thời cải tiến các tính năng hiện có dựa trên phản hồi của người dùng và phân tích dữ liệu.\nNghiên cứu, đề xuất và áp dụng các giải pháp kỹ thuật, công nghệ mới để giải quyết các thách thức về quy mô và hiệu năng của sản phẩm.\nPhối hợp chặt chẽ với Product Manager, UI/UX Designer và các thành viên khác trong team để định hướng và thực thi roadmap sản phẩm.\nChủ động học hỏi, nâng cao kiến thức chuyên môn và có cơ hội chia sẻ, hướng dẫn các thành viên junior trong đội ngũ.\n\nYêu cầu ứng viên\nTốt nghiệp đại học chuyên ngành CNTT hoặc chuyên ngành liên quan.\nTừ 3-5 năm kinh nghiệm làm việc chuyên nghiệp trong lĩnh vực phát triển ứng dụng di động.\nThành thạo ít nhất một trong hai ngôn ngữ lập trình và nền tảng:\n◦ Swift cho phát triển iOS.\n◦ Kotlin cho phát triển Android.\nCó kinh nghiệm làm việc với các ứng dụng có quy mô lớn, lượng người dùng cao và hiểu biết về các thách thức liên quan.\nHiểu biết sâu sắc về tối ưu hiệu năng (performance optimization) và quản lý bộ nhớ (memory management) trên nền tảng di động.\nCó tư duy sản phẩm tốt, khả năng phân tích và giải quyết vấn đề kỹ thuật một cách hiệu quả.\nTinh thần trách nhiệm cao, chủ động trong công việc, có khả năng làm việc độc lập và phối hợp nhóm tốt.\n\nQuyền lợi\nChế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án\n- Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm theo năng lực.\nChế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn\n- Tham gia BHXH sau thử việc, 12 ngày phép năm.\n- Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ.\n- Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết...\n- Học miễn phí các sản phẩm ngôn ngữ của công ty.\nCơ hội phát triển bản thân\n- Lộ trình phát triển sự nghiệp rõ ràng với cơ hội thăng tiến lên vị trí Development Lead.\n- Làm việc trực tiếp với sản phẩm công nghệ có tác động lớn, phục vụ hơn 2 triệu người dùng.\n- Đối mặt và giải quyết các bài toán kỹ thuật thách thức ở quy mô lớn.\n- Đóng góp trực tiếp vào việc định hình và phát triển sản phẩm giáo dục hàng đầu thị trường Việt Nam.\n- Môi trường làm việc trẻ trung, năng động, chuyên nghiệp tại một công ty công nghệ Việt Nam, nơi khuyến khích sự đổi mới và sáng tạo.\n- Cơ hội liên tục học hỏi, tiếp xúc với các công nghệ mới và các chuyên gia trong ngành.\n- Mức lương cạnh tranh theo năng lực và kinh nghiệm, cùng các chế độ phúc lợi hấp dẫn (thưởng, bảo hiểm, team building, v.v.).\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp\n- Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6\n\nĐịa điểm làm việc\n- Hà Nội: 315 Trường Chinh, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2783, 1359, 2, 'Lập Trình Viên Senior Fullstack (Mạnh Về System) Dự Án Fintech', 'Mô tả công việc:\n- Thiết kế, phát triển và duy trì các dịch vụ backend mạnh mẽ sử dụng Java (Spring Boot) và Node.js (Express.js, SocketCluster, v.v.).\n- Xây dựng và duy trì các hệ thống microservices có khả năng mở rộng và hệ thống giao tiếp thời gian thực.\n- Lập trình Frontend, sử dụng ReactJS/NextJS để mang lại trải nghiệm liền mạch cho người dùng.\n- Tối ưu hiệu suất hệ thống và đảm bảo độ sẵn sàng, độ tin cậy và khả năng mở rộng cao cho các dịch vụ Backend.\n- Hợp tác với đội ngũ DevOps để quản lý các ứng dụng container hóa sử dụng Docker, Kafka và Nginx.\n- Thực hiện thiết kế cơ sở dữ liệu, triển khai và tinh chỉnh hiệu năng trên các hệ quản trị MySQL, MongoDB và Redis.\n- Tham gia các cuộc thảo luận kiến trúc, đánh giá mã nguồn và tư vấn giải pháp cùng các nhóm chức năng chéo.\n- Đảm bảo các tiêu chuẩn tốt nhất về chất lượng mã nguồn, bảo mật và khả năng bảo trì.\n- Đóng vai trò cầu nối kỹ thuật giữa các nhóm và hướng dẫn các lập trình viên cấp dưới.\n\nYêu cầu ứng viên:\nKinh nghiệm và Kỹ năng:\n- Trên 4 năm kinh nghiệm phát triển backend với Java (Spring Boot).\n- Kỹ năng lập trình hướng đối tượng (OOP) vững chắc.\n- Có kinh nghiệm thực tế với Node.js, bao gồm Express.js và các framework thời gian thực như SocketCluster.\n- Ít nhất 2 năm kinh nghiệm với ReactJS và NextJS.\n- Thành thạo trong việc làm việc với cơ sở dữ liệu MySQL, MongoDB và Redis.\n- Hiểu biết chuyên sâu về kiến trúc microservices.\n- Có kinh nghiệm làm việc với Docker, Kafka và Nginx trong môi trường sản xuất thực tế.\n- Tư duy logic và phân tích mạnh mẽ; có kinh nghiệm trong thiết kế hệ thống và kiến trúc phần mềm.\n- Có kinh nghiệm tối ưu hiệu suất ứng dụng và xử lý hệ thống có lưu lượng truy cập cao.\n- Tinh thần trách nhiệm cao; có khả năng làm việc độc lập hoặc dẫn dắt một nhóm nhỏ.\n- Kiến thức trong lĩnh vực chứng khoán tài chính là một điểm cộng.\n\nQuyền lợi:\n- Mức lương và thưởng hấp dẫn\n- 12 ngày nghỉ phép năm\n- Được tham gia đầy đủ bảo hiểm xã hội và bảo hiểm y tế theo quy định của nhà nước\n- Các khoản phụ cấp hấp dẫn (thưởng onsite, gửi xe, sinh nhật, happy hours, v.v.)\n- Xét duyệt tăng lương hàng năm dựa trên hiệu suất và đóng góp của nhân viên\n- Các câu lạc bộ thể thao: chạy bộ, bóng bàn, bóng đá, v.v.\n- Môi trường làm việc thực sự cởi mở. Mọi người đều được tôn trọng và bạn có quyền tự do theo đuổi cũng như đạt được mục tiêu của mình\n- Các quyền lợi khác theo quy định của Bộ luật Lao động Việt Nam.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 3C Tôn Đức Thắng, phường Bến Nghé, Quận 1.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2784, 1475, 2, 'Senior Frontend Developer', '● Collaborate with other team members on projects \n● Develop and maintain web services and interfaces \n● Build web applications with web development best practices \n● Work with back-end developers to integrate UI components with APIs and databases \n● Gather and refine specifications and requirements based on technical requirements or \nUX design \n● Transform app designs into front-end code using HTML, CSS, JavaScript, and React JS \nwith CSS framework (Tailwind or Bootstrap) \n● Develop and manage well-functioning databases and applications \n● Perform tests, troubleshoot, and fix bugs or other coding issues \n● Technical Documentation: Create and maintain comprehensive technical documentation \nfor development, deployment, and operational processes.\n\n● At least 6 years in front-end development, in which 4 years with NextJS\n● Knowledge of HTML, CSS, JavaScript, and TypeScript to develop modern, responsive, and cross-browser-compatible websites.\n● Ability to read and understand PHP code (nice to have).\n● Ability to write clean, proper coding.\n● English skills: able to speak, and with good reading and writing abilities.\n● Ability to collaborate with teams and stakeholders to derive options and solutions to various problems.\n● Ability to plan, prioritize, and effectively manage multiple tasks to achieve objectives.\n● Ability to stay proactive, updated, and adapt to the latest technological advances, innovations, and changes.\n● Demonstrated ability to work effectively both independently and as a collaborative member of a team.\n● Excellent communication, problem-solving, and logical thinking skills.\n● Proactive, open-minded with a “can-do” attitude.\n\n● 100% salary from probationary period.\n● Attractive salary package (negotiable in the interview)\n● Health Insurance provided (Premium package)\n● 24 paid days off.\n● Occasional Gifts (birthday, women’s day, etc.)\n● Yearly learning budget.\n● Yearly Position Level Assessments\n\n- Địa điểm làm việc: Hà Nội: Ngõ 19 Duy Tân, Cầu Giấy\n- Thời gian làm việc: Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Nghỉ thứ 7,chủ nhật\n- Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2785, 1433, 2, 'Blockchain Developer', 'Mô tả công việc:\nNghiên cứu sâu về các giao thức blockchain hiện tại, các mô hình đồng thuận, kiến trúc hệ thống và các tiêu chuẩn về ANTT liên quan tới blockchain.\nPhát triển và đề xuất các tiêu chuẩn kỹ thuật, giao thức và quy trình nhằm tối ưu hóa khả năng mở rộng, bảo mật và khả năng tương tác giữa các blockchain.\nPhân tích các xu hướng công nghệ blockchain, đặc biệt là các tiêu chuẩn quốc tế như ERC (Ethereum Request for Comments), BIP (Bitcoin Improvement Proposals), ISO/TC 307...\nViết báo cáo nghiên cứu, whitepaper và tài liệu kỹ thuật nhằm chia sẻ kiến thức và định hướng công nghệ.\nĐánh giá và kiểm định các giải pháp blockchain để đảm bảo tuân thủ các tiêu chuẩn và đề xuất cải tiến phù hợp.\nPhối hợp với các nhóm phát triển, đối tác công nghệ để triển khai các giải pháp theo tiêu chuẩn nghiên cứu được đề xuất.\n\nYêu cầu ứng viên:\nTốt nghiệp đại học trở lên trong các lĩnh vực liên quan đến Khoa học máy tính, Mật mã học, Kỹ thuật phần mềm hoặc tương đương.\nCó kinh nghiệm làm việc trong lĩnh vực blockchain ít nhất 2 năm, đặc biệt là nghiên cứu về tiêu chuẩn và giao thức.\nKiến thức vững chắc về các thuật toán đồng thuận (PoW, PoS, DPoS, PBFT...), smart contract, tokenomics và các hệ thống phi tập trung.\nHiểu biết sâu về các tiêu chuẩn blockchain phổ biến như ERC, BIP, ISO/TC 307, W3C Blockchain.\nCó kinh nghiệm nghiên cứu và viết báo cáo khoa học, tài liệu kỹ thuật hoặc whitepaper.\nThành thạo ít nhất một trong các ngôn ngữ lập trình liên quan đến blockchain như Solidity, Rust, Go, hoặc Python.\nCó khả năng làm việc độc lập và phối hợp tốt với các nhóm nghiên cứu, cộng đồng blockchain.\nKỹ năng giao tiếp, thuyết trình và truyền đạt ý tưởng rõ ràng.\nƯu tiên có bằng cấp hoặc chứng chỉ liên quan đến blockchain, mật mã học hoặc an ninh mạng.\nƯu tiên Kinh nghiệm làm việc với các tổ chức như Ethereum Foundation, Hyperledger, ISO, hoặc các tổ chức tiêu chuẩn hóa blockchain khác.\n\nQuyền lợi:\nMức lương: Thỏa thuận, tùy theo năng lực. \nThưởng quý, Thưởng Năm \nĐược xét tăng lương 02 lần/ 01 năm.\nĐược nghỉ thứ bảy và chủ nhật.\nĐược đào tạo về các nội dung chuyên môn.\nChế độ nghỉ mát hàng năm, khám sức khỏe hàng năm\nCác hoạt động gắn kết khác: Thank-you party; Team building, Sinh nhật Công ty; Du lịch...\nĐược đóng bảo hiểm y tế, bảo hiểm xã hội và các chế độ phúc lợi khác.\nĐược hưởng chế độ chăm sóc sức khỏe cao cấp PTI.\nĐược vận hành, sử dụng các trang thiết bị hiện đại.\nMôi trường làm việc thân thiện, trẻ trung, chia sẻ, kết nối.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hưng Yên, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2786, 1211, 2, 'Game Developer (Fresher - Thu Nhập 14 Tháng Lương/Năm)', 'Mô tả công việc\n- Chuyển thể các thiết kế của Game Artist và Game Designer thành các chức năng của game.\n- Thiết kế, xây dựng và duy trì Code hiệu quả, có thể tái sử dụng và mở rộng.\n- Đảm bảo hiệu suất, chất lượng và khả năng đáp ứng tốt nhất có thể của các game.\n- Xác định và xử lý các lỗi được phát hiện.\n- Xây dựng các phương pháp, công cụ nhằm nâng cao hiệu suất làm việc cho các thành viên trong dự án.\n\nYêu cầu ứng viên\n- Kinh nghiệm tham gia phát triển game 2D hoặc 3D, sử dụng Unity 2D, 3D là lợi thế.\n- Có kiến thức sâu về C# là lợi thế.\n- Có khả năng nắm bắt công nghệ mới tốt, đam mê và quyết tâm theo nghề.\n- Khả năng diễn đạt, trình bày rõ ràng, dễ hiểu, làm việc việc nhóm tốt.\n- Ứng viên đã có kinh nghiệm từ 6 tháng trở lên tại vị trí tương đương hoặc công việc tương tự là một lợi thế.\n- Có tinh thần trách nhiệm, quản lý tốt deadline và khả năng làm việc nhóm tốt.\n\nQuyền lợi\n- Thử việc 100% lương.\n- Thu nhập 14 - 18 tháng lương/năm.\n- Xét tăng lương định kỳ 1 lần/năm.\n- Được tham gia BHXH, BHTN, BHYT, gói chăm sóc sức khỏe của Bảo hiểm Bảo Việt, gói bảo hiểm Falcon Care của công ty.\n- Được hỗ trợ vay vốn mua nhà lãi 0% bằng Quỹ phúc lợi của công ty.\n- Hưởng 12 ngày phép/năm.\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Hỗ trợ cơm trưa, tea-break,...\n- Du lịch, team building: 3 lần/năm.\n- Môi trường làm việc vô cùng sáng tạo, năng động, được thoải mái chơi các trò chơi tại công ty: bida, PS, board game,...\n- Thời gian làm việc: 8:15 - 17:45 (7,5 giờ/ngày; thứ Hai - thứ Sáu)\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Rivera Park, 69 Đ. Vũ Trọng Phụng, Thanh Xuân\n\nThời gian làm việc\n- 8:15 - 17:45 (7,5 giờ/ngày; thứ Hai - thứ Sáu)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2787, 1156, 2, 'Leader React Native', '- Thiết kế và phát triển hệ thống front-end (giao diện người dùng) cho sản phẩm, dịch vụ Ngân hàng số được phát triển, cụ thể: \n- Phát triển ứng dụng mobile app cho React Native. \n- LEAD TEAM \n- Nhận bàn giao các file thiết kế, graphic asset từ UIUX designer, mô tả chức năng, hệ thống từ BA BU và BA IT. \n- Phối hợp với Kỹ sư DevOps và Kỹ sư Back-end quy trình khác, phát triển toàn bộ hệ thống ứng dụng. \n- Tham gia quản trị kiến trúc tổng thể của giải pháp. \n- Tuân thủ các tiêu chuẩn tích hợp APIS (ie Open Api, Oauth2 etc). \n- Thực hiện phát triển theo các tiêu chí an toàn bảo mật cao nhất. \n- Tích hợp chức năng theo dõi ứng dụng cho các use case phân tích (firebase analytics, Facebook Pixel, Google Analytics ...)\n- Xây dựng chiến lược kiểm thử ứng dụng cho phần mềm mình phụ trách unit test, SIT, regression test, application test, UI test, performance test, security test, đảm bảo an toàn chất lượng ứng dụng. \n- Đảm bảo ứng dụng làm việc tốt trên thiết bị, hệ điều hành, trình duyệt khác nhau (99% coverage). \n- Phát hành ứng dụng trên app store.\n\n- Có từ 1 năm kinh nghiệm vị trí Lead React Native.\n- Đã tham gia phát triển ít nhất 1-2 dự án lớn (quy mô từ 100 Man-month) trong các lĩnh vực: Mobile Banking, Internet Banking, Giao dịch chứng khoán/trái phiếu, Ví điện tử, Fintech, CRM, Ecommerce... \n- Có kiến thức sâu về: \n+ JavaScript, TypeScript, React Native, Redux, Context API. \n+ Các công cụ quản lý state management và tối ưu hiệu suất. \n+ Tích hợp API và xử lý authentication (OAuth2, JWT). \n+ Công cụ CI/CD, Fastlane, Git, Docker là lợi thế. - Ưu tiên ứng viên có kinh nghiệm: \n+ Phát hành và tối ưu ứng dụng trên App Store/Google Play. \n+ Xử lý performance tuning và memory management trên ứng dụng React Native. \n+ Làm việc với GraphQL, WebSocket. \n\n- Mức lương hấp dẫn, phù hợp với năng lực ( Thời gian làm việc: T2-T6)\n- Thưởng lễ tết, thưởng tháng lương thứ \n- 13 Hỗ trợ gửi xe hàng tháng \n- Có cơ hội trở thành “Gương mặt xuất sắc” của Công ty nếu hoàn thành xuất sắc \n nhiệm vụ; \n- Hưởng đầy đủ các chính sách và chế độ như: BHYT, BHXH, BHTN, . theo đúng quy định của Bộ Luật Lao động và của Công ty; \n- Tham gia các hoạt động nghỉ mát, team building \n- Làm việc trong môi trường cởi mở, năng động, khuyến khích sự sáng tạo.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2788, 1294, 2, 'Nhân Viên Lập Trình Cnc', '+Sử dụng các phần mềm để tạo chương trình gia công sản phẩm.\n+Set up hàng mẫu dựa trên các loại máy phay CNC\n+ Giải quyết và khắc phục các sự cố kỹ thuật của sản phẩm trong quá trình sản xuất\n+Thiết kế, chế tạo gia công cho sản phẩm mẫu\n+ Vận hành máy phay CNC\n\nYêu cầu ứng viên\n- Tốt nghiệp  chuyên ngành chuyên ngành Cơ khí, Cơ khí chế tạo máy,hoặc các ngành liên quan.\n- Ít nhất 2 năm kinh nghiệm lập trình máy móc tự động hóa..\n- Kỹ năng giải quyết vấn đề và tư duy logic tốt.\n- Khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Có tinh thần trách nhiệm cao và chủ động trong công việc.\n- Đọc hiểu bản vẽ cơ khí , bản vẽ kỹ thuật tốt\n- Kinh nghiệm với các hệ thống SCADA là một lợi thế.\n\nQuyền lợi\n- Mức lương cạnh tranh tùy thuộc vào kinh nghiệm và năng lực.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế theo luật lao động.\n- Thưởng các ngày lễ, tết và thưởng hiệu quả công việc.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.\n- Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n- Được tham gia các khóa đào tạo nâng cao nghiệp vụ.\n\nĐịa điểm làm việc\n- Bắc Giang: KCN Hoà Phú - Hiệp Hoà, Hiệp Hoà\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n- Tăng ca khi có yêu cầu của khách hàng\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2789, 1108, 2, 'Fullstack Developer (App, Web, AI)', '[Tuyển dụng lập trình viên IT cho thị trường Việt Nam]\nORBRO, một công ty startup IT đang trên đà phát triển nhanh chóng, đang tuyển dụng lập trình viên App, Web, Server và AI! \nChúng tôi là một đội ngũ luôn sẵn sàng đối mặt với thử thách, phá vỡ các khuôn mẫu truyền thống để phát triển công nghệ tiên tiến và mở ra những thị trường mới. Hiện tại, chúng tôi đang tuyển dụng 10 thành viên đầu tiên để gia nhập đội ngũ tại Việt Nam, nhằm mở rộng và vươn ra thị trường toàn cầu. Chúng tôi mong muốn tìm kiếm những tài năng nhiệt huyết, sẵn sàng cùng nghiên cứu và quảng bá để khai phá tương lai.\nORBRO là một công ty IT ứng dụng các công nghệ tiên tiến như thuật toán đa dạng, công nghệ camera AI, dựa trên nền tảng công nghệ theo dõi vị trí. Chúng tôi tự hào sở hữu: \n• Văn hóa tổ chức linh hoạt và cấu trúc ra quyết định nhanh chóng.\n• Môi trường khuyến khích mỗi cá nhân tự chủ trong nghiên cứu và phát triển.\n• Văn hóa không sợ thất bại, đề cao sự học hỏi liên tục và tinh thần thử thách.\nNếu bạn là người muốn hiện thực hóa ý tưởng của mình trong một môi trường tự do, hãy đồng hành cùng chúng tôi!\n\nChúng tôi đang tìm kiếm những ứng viên như sau:\n• Người thích giải quyết vấn đề và không ngại thử thách mới.\n• Người có thể thích nghi và phát triển trong môi trường thay đổi nhanh chóng.\n• Người không chỉ thực hiện công việc một cách đơn thuần mà còn tích cực đề xuất và thực hiện các ý tưởng mới.\n\nNhiệm vụ chính cho từng vị trí như sau:\nLập trình ứng dụng:\n• Phát triển và bảo trì ứng dụng Flutter (Android, iOS).\n• Tối ưu hóa UI/UX và cải thiện trải nghiệm người dùng.\n• Cải thiện và tối ưu hóa hiệu suất, tích hợp module native.\n• Xử lý dữ liệu và tích hợp mạng.\n\nLập trình web:\n• Phát triển và bảo trì website và dịch vụ dựa trên React/TypeScript.\n• Tối ưu hóa công cụ tìm kiếm (SEO) và tối ưu hóa hiệu suất.\n• Phát triển frontend.\n\nLập trình AI:\n• Phát triển hệ thống nhận diện và theo dõi đối tượng dựa trên AI.\n• Nghiên cứu và tối ưu hóa mô hình thị giác máy tính và máy học.\n• Huấn luyện và cải thiện hiệu suất mô hình học sâu (sử dụng TensorFlow, PyTorch, v.v.).\n• Phát triển công nghệ phân tích và xử lý hình ảnh thời gian thực.\n• Nghiên cứu và phát triển thuật toán hậu xử lý (bộ lọc Kalman).\n\nYêu cầu ứng viên\n• Người có đam mê học hỏi công nghệ mới.\n• Người có khả năng hợp tác và giao tiếp xuất sắc.\n• Có bằng cử nhân trở lên trong lĩnh vực liên quan hoặc kinh nghiệm tương đương.\n• Có ít nhất 2 năm kinh nghiệm thực tế trong lĩnh vực liên quan (ứng viên mới tốt nghiệp vẫn có thể ứng tuyển).\n• Ưu tiên người sử dụng tiếng Anh hoặc tiếng Hàn.\n\nQuyền lợi\n• Lương: Thỏa thuận.\n• Tham gia các hoạt động Team Building.\n• Hỗ trợ thiết bị laptop khi cần thiết.\n• Môi trường làm việc trẻ trung năng động, chuyên nghiệp, kích thích sự sáng tạo.\n• Các chế độ khác theo đúng quy định pháp luật.\n\nĐịa điểm làm việc\n• Hà Nội: Cầu Giấy\n\nThời gian làm việc\n• Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n• Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2790, 1217, 2, 'Software Engineer – Theia IDE Development For RISC-V', 'Mô tả công việc\n- Develop and maintain core features of the Theia-based IDE, ensuring a seamless and productive developer experience.\n- Integrate and optimize RISC-V and ARM toolchains (GCC/LLVM) within the IDE, enabling efficient compilation and debugging workflows.\n- Implement and enhance debugging capabilities for RISC-V and ARM using GDB/LLDB, providing advanced features such as real-time system monitoring and multi-core debugging.\n- Design and develop Theia extensions and plugins to support specialized embedded development needs, including tracing, profiling, and hardware-specific interactions.\n- Enable seamless debugging of embedded targets deployed on the cloud, leveraging Theia\'s extensibility to integrate with cloud platforms.\n- Collaborate with cross-functional teams to gather requirements, design solutions, and ensure the IDE meets the evolving needs of embedded developers.\n- Contribute to the development and maintenance of a comprehensive suite of documentation and tutorials to support users.\n\nYêu cầu ứng viên\n- Bachelor’s degree in Computer Science, Software Engineering, or a related field.\n- Proficiency in TypeScript/JavaScript and experience with web-based development.\n- Familiarity with Theia framework or other web-based IDEs is a plus.\n- Knowledge of embedded systems and development (RISC-V or ARM) is a plus.\n- Familiarity with C/C++ and debugging tools (GDB/LLDB) is a plus.\n- Eagerness to learn and a proactive attitude.\n- Focus on web-based applications and cloud technologies.\n- Strong expertise in TypeScript/JavaScript, modern web frameworks (e.g., React), and Electron framework.\n- Experience with cloud platforms and an understanding of cloud-based development workflows.\n- Familiarity with Theia framework and experience or a strong interest in developing Theia extensions or plugins.\n- A willingness to learn and embrace the challenges of embedded systems development, including familiarity with C/C++ and debugging tools (GDB/LLDB).\n- Ability to lead technical discussions, mentor junior engineers, and contribute to the development of a cutting-edge IDE.\n- Hands-on experience with Agile/Scrum, code reviews, and continuous integration.\n\nQuyền lợi\n- Cutting-Edge Projects: Work with the latest technology trends in the RISC-V and ARM ecosystem.\n- Professional Growth: Opportunities for professional development, including mentorship, training, and career advancement.\n- Collaborative Environment: A dynamic and friendly team culture that thrives on innovation.\n- Competitive Compensation: Industry-leading salary, benefits, and bonuses based on experience and contribution.\n- Performance-based bonuses/ 13th month salary.\n- A powerful workspace\n  - MacBook Pro with 64GB RAM and 1TB SSD for smooth development.\n  - 34-inch external display for enhanced productivity and a better workflow experience.\n  - Access to the latest tools, resources, and a supportive team environment.\n- Refer friends to open jobs and receive a cash bonus for every successful referral you make.\n\nĐịa điểm làm việc\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2791, 1110, 2, 'Kỹ Sư Phát Triển Phần Mềm (Làm Việc Tại Nhật)', 'Mô tả công việc:\n- Tham gia phát triển, thiết kế, lập trình các tính năng mới theo yêu cầu của dự án.\n- Nghiên cứu, áp dụng các công nghệ mới để nâng cao hiệu suất và chất lượng phần mềm.\n- Phối hợp với các bộ phận khác để đảm bảo tính chính xác và hoàn thiện của sản phẩm.\n- Thực hiện các công việc khác khi được giao.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học các chuyên ngành liên quan đến Công nghệ thông tin, Khoa học máy tính, Kỹ thuật phần mềm hoặc các ngành liên quan,…\n- Chấp nhận chưa có kinh nghiệm thực tế (được đào tạo trong quá trình làm việc)\n- Có định hướng phát triển lâu dài với công việc\n- Chăm chỉ, cẩn thận, làm việc trên tinh thần trách nhiệm cao\n- Người ham học hỏi, đam mê công việc.\n\nQuyền lợi:\n- Thời gian làm việc: 8:00 - 17:00\n- Nghỉ thứ 7, chủ nhật và nghỉ theo lịch công ty.\n- Tổng số ngày nghỉ 121 ngày/năm\n- Trợ cấp toàn bộ chi phí đi lại, trợ cấp nhà ở lên đến 20000 yên, trợ cấp chuyên cần, trợ cấp chức vụ, ngoài giờ,...\n- Đầy đủ các chế độ bảo hiểm, tăng lương, thưởng dự án,...\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 24 Ấp Bắc, Phường 13, Tân Bình\n- Nước Ngoài\n- Đà Nẵng: 220 Nguyễn Tri Phương, Thạc Gián, Thanh Khê\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh & 3 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2792, 1142, 2, 'Kotlin Developer (Fresher)', 'Mô tả công việc:\nDevelop and integrate Kotlin Multiplatform modules targeting Android and iOS\nDesign and implement clean, maintainable architectures (MVVM / Clean Architecture)\nBuild lightweight back-end services using Ktor\nManage database interactions with SQLDelight (or equivalent)\nLeverage Kotlin Coroutines & Flow for asynchronous processing\nConfigure and customize Compose Multiplatform (themes, navigation, multiplatform previews)\nCollaborate with mobile teams to share common code and handle native interop\n\nYêu cầu ứng viên:\nMust-Have Qualifications\nHands-on experience with Kotlin (Android development is a plus)\nSolid understanding of Kotlin Coroutines, Flow, and MVVM/Clean Architecture\nProficient in Ktor and SQLDelight (or similar frameworks)\nFamiliarity with code-sharing patterns in Kotlin Multiplatform (KMP)\nPractical knowledge of Compose Multiplatform (themes, navigation, previews)\nPreferred Skills\nExperience with Swift or native iOS development\nPrior exposure to deploying KMP projects in production or personal side-projects\nWorking knowledge of dependency injection and serialization libraries (e.g., Koin, Kotlinx.Serialization, Kermit)\nCI/CD pipeline setup and testing (unit tests, integration tests)\nNative interop expertise (expect/actual in KMP or Swift/Objective-C bridges)\nFamiliarity with Flutter or React ecosystems\n\nQuyền lợi:\n• Competitive salary package and specific benefits. You\'ll get a bonus of a half month salary If you are on board before October 1st\n• TET bonus from up to 4-month salary according to seniority, work results, and business situation of the company.\n• The company pays (32%) the costs of social insurance, health insurance, and unemployment insurance for its employees.\n• Performance review twice a year\n• Annual holiday: 12 annual leave and Corporate Birthday 11/27\n• Working in a dynamic and professional environment with many promotion opportunities.\n• Receive benefits according to seniority\n• Being trained in foreign languages, sponsored to learn certificates to improve professional skills and soft skills.\n• Lots of opportunities to go to Onsite at SPLUS JAPAN (for staff with Japanese proficiency from N3 and above)\n• Sports activities: Football\n• Annual company trip, team building, birthdays for employees in the month, and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas ...).\n• Time working: Monday – Friday (9:00 – 18:00).\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tòa nhà HaDo Airport, 2 Hồng Hà, phường 2, Tân Bình\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2793, 1201, 2, 'Lập Trình Backend', '• Phát triển ứng dụng desktop đa nền tảng sử dụng Node.js và SQLite.\n• Thiết kế kiến trúc phần mềm hiệu năng cao, tối ưu bộ nhớ và CPU cho các tác vụ nặng.\n• Thực thi giải pháp caching, xử lý đồng thời và bảo trì hệ thống lâu dài.\n• Quản lý luồng xử lý, ngăn chặn memory leak, nâng cao độ ổn định ứng dụng.\n• Phối hợp với team để triển khai giao diện người dùng và backend tích hợp.\n• Ưu tiên ứng viên đã từng làm việc với Electron.js.\n- Thời gian làm việc:\n+ Từ Thứ hai đến Thứ Sáu: Từ 8h00’ đến 17h30’\n+ Thứ Bảy : Từ 8h00’ đến 12h00’  \n+ Trưa nghỉ từ 12h00\' đến 13h30\' \n\n• Tối thiểu 2 năm kinh nghiệm với Node.js trong môi trường sản phẩm thực tế.\n• Hiểu rõ mô hình bất đồng bộ: Callback, Promise, Async/Await.\n• Có kinh nghiệm với SQLite, hiểu ORM và ưu tiên biết TypeORM.\n• Có hiểu biết về caching (in-memory hoặc disk), tối ưu CPU usage.\n• Biết phát hiện và xử lý memory leak, hiểu lifecycle trong Node.js.\n• Có tư duy về thiết kế ứng dụng high performance: phân luồng, chia module, reuse tài nguyên.\n• Biết sử dụng Git, đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.\n\n- Lương: 15.000.000 – 20.000.000\n- Phỏng vấn 1 vòng duy nhất.\n- Lộ trình thăng tiến lên Sublead, Leader\n- Review lương 2 lần/năm, thưởng nóng hàng tuần, hàng tháng, hàng năm khi đạt thành tích xuất sắc cá nhân hay đội nhóm.\n- Thưởng tháng lương thứ 13, bảo hiểm, chế độ du lịch hàng năm theo chương trình của công ty.\n- Được khám sức khỏe định kỳ tại bệnh viện đa khoa Quốc tế. Được hỗ trợ 50 -100% chi phí sau bảo hiểm nếu không may phải nằm viện.\n\n- Địa điểm làm việc: Tầng 4, tòa nhà Stellar Garden số 35 Lê Văn Thiêm, Thanh Xuân Trung, Thanh Xuân.\n\n- Thời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00).\n\n- Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2794, 1164, 2, 'AI Backend Developer', 'We are seeking an experienced AI Backend Developer with over 5 years of experience in designing, implementing, and optimizing AI-driven backend systems. The ideal candidate will have deep expertise in LangChain, RAG pipeline implementation, and search technologies (OpenSearch/Elasticsearch), along with experience in chatbot/playground development. Knowledge of AI agents, tools, and RAG optimization is a plus\n\n- Design and implement LangChain-based workflows for AI applications.\n- Develop and optimize Retrieval-Augmented Generation (RAG) pipelines.\n- Integrate OpenSearch/Elasticsearch for semantic/hybrid search.\n- Build and maintain chatbot/playground environments (e.g., Streamlit, Gradio, custom UIs).\n- Fine-tune vector search, hybrid search, and relevance ranking.\n- Optimize indexing/query performance for low-latency AI responses.\n- Work with embeddings (OpenAI, Hugging Face, or custom models).\n- Develop scalable APIs (FastAPI, Flask, or similar).\n- Collaborate on frontend-backend integration (Ember.js or other JavaScript frameworks).\n- Use build tools (Ant, Maven, Gradle) for deployment automation.\n- Ensure CI/CD pipelines are efficient and reliable.\n- Work in Agile/Scrum environments, participating in sprints, standups, and retrospectives.\n- Collaborate with frontend engineers, data scientists, and product teams.\n\n**Other Requirements:**\n- 5+ years of backend development (Python preferred).\n- Strong experience with LangChain for LLM orchestration.\n- Hands-on experience with OpenSearch/Elasticsearch (indexing, querying, optimization).\n- Proven track record in RAG pipeline implementation.\n- Experience in developing chatbots or AI playgrounds (e.g., Gradio, Streamlit, custom UIs).\n- Familiarity with LLM APIs (OpenAI, Anthropic, Mistral, etc.).\n- Knowledge of AI agents & tools (AutoGPT, BabyAGI, multi-agent systems).\n- Experience in RAG optimization & evaluation (metrics like precision, answer relevance).\n- Familiarity with vector databases (Pinecone, Weaviate, Milvus).\n- Understanding of NLP techniques (text processing, embeddings, fine-tuning).\n- Experience with both external and embedded databases.\n- Understanding fundamental design principles behind a scalable application.\n- Creating database schemas that represent and support business processes.\n- Implementing automated testing platforms and unit tests.\n- Proficient understanding of code versioning tools, such as Git.\n- Ability to clearly communicate with both technical and non-technical team members.\n- Experience with Agile Scrum.\n- Experience with Ember or other JavaScript.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2795, 1157, 2, 'Junior Dev Odoo', 'Mô tả công việc\n- Tham gia trực tiếp vào team dự án phát triển và triển khai hệ thống Odoo nội bộ và cho các khách hàng\n- Công việc cụ thể:\n+ Phụ trách thiết kế chi tiết, lập trình, unit test, xử lý lỗi của chương trình sử dụng ngôn ngữ lập trình Python trên framework Odoo.\n+ Kết hợp với BA, Tester, Operator và các bên liên quan để xây dựng hệ thống cho khách hàng, giải quyết các nhu cầu chuyển đổi số, phục vụ sự phát triển kinh doanh của khách hàng.\n+ Thực hiện coding, lập trình các module, fix bugs,.. theo yêu cầu công việc\n+ Ưu tiên ứng viên có kinh nghiệm làm modul HRM, kho, kế toán.\n+ Các công việc khác được giao bởi Project Manager và Group Leader.\n\nYêu cầu ứng viên\n– Thành thạo ngôn ngữ Python. Có từ 2 năm kinh nghiệm làm việc với framework Odoo\n– Có mong muốn theo làm Odoo lâu dài.\n– Có kiến thức và kỹ năng lập trình database; ưu tiên thành thạo PostgreSQL\n– Đọc hiểu tiếng Anh tốt\n– Ưu tiên:\n+ Tổt nghiệp chuyên ngành công nghệ thông tin các trường:  Đại học Bách khoa Hà Nội, Học viện Kỹ thuật quân sự, Đại học Công nghệ — ĐHQGHN, Học viện Kỹ thuật Mật mã, …..\n+ Đã có kinh nghiệm làm việc với các hệ thống phần mềm mã nguồn mở\n+ Có khả năng hiểu business logic, tìm tòi hướng giải quyết các vấn đề mới\n+ Có kinh nghiệm về cài đặt và sử dụng Linux , apache\n+ Có kinh nghiệm customize module/report; xử lý đọc/ghi file Excel\n+ Có khả năng quản lý và đào tạo cho những thành viên khác.\n\nQuyền lợi\nLương: Thỏa thuận theo năng lực.\nThưởng:\n- Thưởng tháng 13.\n- Thưởng dựa trên kết quả kinh doanh của công ty.\nBảo hiểm: Đóng bảo hiểm đầy đủ theo mức lương.\nDu lịch: Công ty tổ chức một chuyến du lịch mỗi năm.\nPhúc lợi:\n- Quầy pantry miễn phí.\n- Các sự kiện nội bộ: team building, sinh nhật hàng tháng, ngày Quốc tế Phụ nữ, ngày Quốc tế Nam giới,...\n- Quà tặng nhân dịp Trung Thu, sinh nhật,...\nCơ hội nghề nghiệp:\n- Cơ hội đi onsite tại Nhật Bản (ngắn hạn hoặc dài hạn).\n- Cơ hội chia sẻ ý tưởng, lắng nghe và phát triển nghề nghiệp theo mong muốn cá nhân.\n- Lộ trình thăng tiến rõ ràng.\nThời gian làm việc:\n- Từ thứ 2 đến thứ 6, từ 8h30 đến 17h30 (có thể linh hoạt thời gian vào 30 phút). \n\nĐịa điểm làm việc\n- Hà Nội: Tầng 29, tòa nhà Handico Tower, KĐTM Mễ Trì Hạ, Đường Phạm Hùng, Phường Mễ Trì Thành phố Hà Nội, Việt Nam.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2796, 1152, 2, 'Developer Senior Java', 'Mô tả công việc\n- Xây dựng và phát triển sản phẩm mới, tập trung vào các giải pháp đột phá trong lĩnh vực Chính phủ, Doanh nghiệp, Ngân hàng.\n- Hợp tác chặt chẽ với đội ngũ Phân tích nghiệp vụ (BA) để thiết kế và triển khai các tính năng tối ưu.\n- Phát triển, bảo trì các tính năng mới và cải tiến sản phẩm hiện có.\n- Viết code sạch, hiệu quả, dễ bảo trì theo tiêu chuẩn cao.\n- Tham gia thảo luận, đề xuất và triển khai các giải pháp kỹ thuật.\n- Nghiên cứu, ứng dụng các công nghệ mới, phối hợp hiệu quả với đội ngũ dự án.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin hoặc có chứng chỉ tương đương.\n- Thành thạo Java core, spring và lập trình hướng đối tượng (OOP).\n- Ưu tiên ứng viên có thêm kinh nghiệm với Vuejs và các framework hiện đại.\n- Am hiểu về lập trình, thuật toán và thiết kế hệ thống.\n- Có kiến thức tốt về server, database và tối ưu hệ thống.\n- Tinh thần trách nhiệm cao, làm việc được dưới áp lực lớn, cầu tiến, nhiệt huyết trong công việc.\n- Kỹ năng tổ chức, làm việc nhóm tốt, chủ động giải quyết vấn đề.\n- Có tư duy sáng tạo, khả năng tự học và tiếp cận tài liệu tiếng Anh hiệu quả.\n\nQuyền lợi\n- Thời gian làm việc: Thứ 2 - Thứ 6 (8h30 – 18h00), có thể làm thêm 2 thứ 7/tháng khi cần.\n- Mức lương hấp dẫn: 20.000.000 - 50.000.000 VND/tháng, cùng thưởng dự án, hiệu suất và lương tháng 13.\n- Chế độ bảo hiểm và nghỉ phép đầy đủ theo Luật Lao động.\n- Cơ hội làm việc onsite tại Nhật Bản, Hàn Quốc.\n- Môi trường trẻ trung, năng động, lộ trình thăng tiến rõ ràng.\n- Tham gia các hoạt động: team building, du lịch thường niên và các sự kiện ngoại khóa.\n- Xét tăng lương 2 lần/năm dựa trên năng lực.\n- Đào tạo chuyên sâu về kỹ thuật, tiếp cận công nghệ 4.0 tiên tiến.\n- Lộ trình phát triển nghề nghiệp chuyên nghiệp, lâu dài và ổn định.\n\nĐịa điểm làm việc\n- Hà Nội: Số 38 Đỗ Đức Dục, Phường Mễ Trì, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2797, 1357, 2, 'Nhân Viên Lập Trình Máy Phay CNC _ Thu Nhập Up To 20M++ _ Đi Làm Ngay Tại Hoàng Mai - HN', 'Mô tả công việc\n- Lập trình cho các mã hàng sản xuất theo kế hoạch sản xuất\n- Giảm tỉ lệ lỗi phát sinh trong khi lập trình bao gồm: các lỗi mới phát sinh trong khi lập trình, các lỗi lặp lại trong khi lập trình.\n- Setup các nguyên công chạy các mã hàng trên các máy\n- Giảm tỉ lệ lỗi phát sinh trong quá trình setup trên các máy, bao gồm: Tỉ lệ lỗi NG phải bỏ hàng khi setup hàng lượt đầu do lập trình, tỉ lệ lỗi NG phải bỏ hàng khi setup hàng lượt đầu do gá đặt và xét dao, xét phôi.\n- Tổng hợp và lập báo cáo tỉ lệ lỗi các mã hàng và báo cáo hàng tuần cho cấp trên.\nCải tiến lập trình giúp giảm thời gian gia công và nâng cao tính ổn định khi sản xuất hàng loạt.\nYêu cầu ứng viên\n- Kỹ năng sử dụng thời gian hiệu quả;\n- Tư duy logic, nhạy bén, sáng tạo.\n- Trung thực, thẳng thắn, nhiệt tình công tác;\n- Nam giới, từ 25 tuổi trở lên.\n- Tốt nghiệp Trung cấp trở lên chuyên ngành kỹ thuật hoặc các chuyên ngành liên quan.\n- Ít nhất 1 năm kinh nghiệm ở vị trí tương đương.\nQuyền lợi\n1. Lương & Thưởng\n- Mức lương cạnh tranh, phù hợp với năng năng lực và kinh nghiệm\n- Thưởng theo hiệu suất làm việc, lễ, tết, lương tháng 13.\n- Tăng lương định kỳ\n2. Chế độ Bảo hiểm & Phúc Lợi Xã Hội\n- Chế độ nghỉ thai sản, nghỉ nghỉ, nghỉ phép có lương theo quy định\n3. Môi Trường Làm Việc\n- Môi trường làm việc chuyên nghiệp, năng động, có tiến bộ.\n- Công cụ hỗ trợ hiện tại\n- Văn hóa doanh nghiệp thân thiện, tôn trọng và gắn kết.\n4. Đào Tạo & Phát Triển Nghề Nghiệp\n- Tham gia các khóa đào tạo kỹ năng, chuyên môn\n- Hỗ trợ học phí, nâng cao trình độ\n5. Các Phúc Lợi Khác\n- Du lịch, teambuilding hàng năm.\n- Hỗ trợ ăn trưa\n- Các hoạt động nội bộ như sinh nhật, quà tặng, liên hoan.\nĐịa điểm làm việc\n- Hà Nội: 481 Tam Trinh, Hoàng Văn Thụ, Hoàng Mai, Hoàng Mai\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2798, 1371, 2, 'Android Developer', 'Mô tả công việc\n- Tham gia thực hiện thiết kế, xây dựng và triển khai ứng dụng android mobile\n- Nghiên cứu tìm hiểu những công nghệ mới nhất, giải pháp tốt nhất cho sản phẩm và người dùng\n- Phát triển các ứng dụng trên nền tảng Android, cải thiện tốc độ, hiệu quả và mở rộng ứng dụng.\n\nYêu cầu ứng viên\n- Biết sử dụng Jira, Github, Bitbucket\n- Kiến thức cơ bản và tư duy về Kotlin, lập trình Android, lập trình hướng đối tượng\n- Có kinh nghiệm làm việc với Kotlin là lợi thế lớn.\n- Có kinh nghiệm với Thread, Handler, Rxjava, Coroutines, and scheduling techniques\n- Có kinh nghiệm với Android patterns as MVP, MVVM, Clean architecture, Android Architecture\n- Hiểu biết về CI/CD là điểm cộng, Firebase (FCM / Cloud Storage / Realtime Database).\n\nQuyền lợi\n- Lương NET hàng tháng + thưởng (Thưởng quý, thưởng dự án)\n- Lương thỏa thuận theo năng lực, đảm bảo cạnh tranh với thị trường.\n- Thưởng hiệu suất theo quý, năm, thưởng mặc định tháng 13. Lương tháng 14 theo hiệu quả kinh doanh\n- Review lương 2 lần/năm\n- Môi trường làm việc trẻ trung, năng động, nhiều cơ hội thăng tiến.\n- Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty\n- Cấp thiết bị làm việc (tại công ty hoặc tại nhà tuỳ yêu cầu của nhân sự).\n- Tham gia các sự kiện lớn trong và ngoài nước do các đối tác: Google, Facebook, Tiktok... tổ chức\n- Du lịch, Teambuilding, Sự kiện, Khám sức khỏe thường niên 100% ngân sách công ty chi trả (Không bắt buộc tham gia).\n- Thiết bị giải trí đa dạng tại văn phòng: Bida, Bóng bàn, PS5, Gameboard...\n- Quà tặng các dịp lễ, tết, hoặc các dịp kỷ niệm năm làm việc, sinh nhật...\n- Pantry đầy đủ hoa quả, bánh kẹo, đồ uống, trà, cafe,... free.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2799, 1400, 2, 'C#.NET Developer', 'Mô tả công việc\n・Participate in building the company\'s own product and outsource projects\n・Cooperate with other teams on all phases of project development\n・Contribute to system architecture and design decisions\n・Deliver good quality code\n・Be able to self-study on new technologies\n・Be dynamic and proactive\n\nYêu cầu ứng viên\n1. Basic Skills:\n・ CV with person photo\n・ Someone who takes initiative and can work proactively.\n・Has a positive attitude and forward-thinking mindset.\n・ Enjoys creating new things with a pioneering mindset.\n・Willingness to learn new technologies.\n・Strong communication skills and the ability to collaborate effectively with a team.\n・Able to communicate in English.\n\n2. Technical Skills And Experiences (Required)\n・Experience participating in and developing multiple projects as a programmer.\n・Proficient in at least one programming language.\n\n2.2 Technical Skill And Experience:\n・Has experience working with Japanese clients, markets, or companies.\n・Holds IT-related certifications.\n\nQuyền lợi\n・Salary review:  Once a year \n・Commuting allowance\n・Annual paid leave  (Granted collectively in April), public holidays are in accordance with labor laws.\n・Company trips・Regular health check-ups: Once a year \n・Participation in regular sports activities such (badminton,bowling ,vvv) : Once a month \n・Company parties and other internal events \n\nĐịa điểm làm việc\n- Hồ Chí Minh: Bình Thạnh\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2800, 1182, 2, 'Frontend Developer', '● Chịu trách nhiệm phát triển các sản phẩm Web sử dụng ngôn ngữ/công nghệ: React/JavaScript, WebSocket,...\n● Chuyển đổi thiết kế thành các các giao diện UI/UX thân thiện với người dùng.\n● Onsite theo yêu cầu công việc.\n\nYêu cầu ứng viên\n● Ít nhất 1 năm kinh nghiệm làm việc với ReactJS trong môi trường phát triển web.\n● Thành thạo JavaScript, jQuery, Bootstrap, CSS, HTML5.\n● Có kinh nghiệm phát triển và tích hợp RESTful API, WebSocket, ...\n● Có kinh nghiệm làm việc với các công cụ: Git, Jira.\n● Năng động, sáng tạo, có khả năng tự nghiên cứu.\n\nQuyền lợi\n● Lương tháng 13.\n● Nghỉ phép, nghỉ lễ, Bảo hiểm xã hội, bảo hiểm y tế theo luật lao động.\n● Thời gian làm việc: Thứ 2-Thứ 6, từ 8h30-18h00.\n\nĐịa điểm làm việc\n- Hà Nội: 15 Hồ Xuân Hương, Hai Bà Trưng.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 18:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2801, 1407, 2, 'Nhân Viên Phát Triển Kinh Doanh', 'Mô tả công việc\nPhát triển kinh doanh B2B:\n- Tìm kiếm, tiếp cận và thiết lập mối quan hệ với các doanh nghiệp có nhu cầu tổ chức giải chạy nội bộ hoặc sự kiện truyền thông thể thao. \n- Tư vấn, xây dựng proposal và thương thảo hợp đồng với khách hàng.\nTriển khai dự án:\n- Phối hợp cùng các bộ phận nội bộ (thiết kế, kỹ thuật, vận hành, truyền thông) để đảm bảo tiến độ và chất lượng dịch vụ theo cam kết với khách hàng. \n- Theo dõi kết quả thực hiện, tổng hợp báo cáo và đề xuất cải tiến dịch vụ.\nQuản lý đối tác cộng đồng:\n- Phát triển hệ thống đại lý và nhóm chạy nhằm mở rộng thị trường phân phối sản phẩm sự kiện. \n- Hỗ trợ kỹ thuật, hướng dẫn và xử lý các vấn đề phát sinh trong quá trình bán hàng và vận hành.\nTư vấn sản phẩm bổ trợ:\n- Giới thiệu và tư vấn các sản phẩm đi kèm như áo chạy, huy chương, túi đeo, bình nước,... cho doanh nghiệp và đối tác tổ chức sự kiện.\nDuy trì & phát triển mối quan hệ khách hàng:\n- Chăm sóc khách hàng hiện tại, xây dựng kế hoạch upsell và duy trì hợp tác dài hạn. \n- Phân tích dữ liệu khách hàng để đề xuất các chương trình phù hợp theo thời điểm và mục tiêu truyền thông của đối tác.\nYêu cầu ứng viên\n- Có laptop cá nhân\n- Ưu tiên ứng viên có đam mê thể thao, chạy bộ, fitness hoặc từng tham gia tổ chức các hoạt động cộng đồng\n- Biết Tiếng Anh là một lợi thế\n- Tốt nghiệp đại học chuyên ngành Quản trị Kinh doanh, Marketing, Kinh tế, Truyền thông hoặc các ngành liên quan\n- Tối thiểu 01 năm kinh nghiệm tại vị trí Business Development, Sales, Account hoặc tương đương, ưu tiên ứng viên từng làm trong lĩnh vực sự kiện, thể thao, truyền thông, agency\n- Có khả năng giao tiếp tốt, tư duy dịch vụ, kỹ năng đàm phán và xử lý tình huống linh hoạt\n- Thành thạo tin học văn phòng, biết sử dụng phần mềm CRM là lợi thế\n- Có khả năng làm việc độc lập, chủ động, định hướng mục tiêu và chịu được áp lực về doanh số\n- Siêng năng, nhiệt tình ham học hỏi, nhanh nhẹn, trung thực\n- Có khả năng tư duy đổi mới, chính xác và làm việc đúng đắn\n- Có khả năng làm ngoài giờ khi cần thiết\n- Gắn bó với công ty lâu dài\nThu nhập\n- Thu nhập khi đạt 100% KPI:  15 - 30 triệu VND\n- Thu nhập tính theo tỷ lệ đạt KPI\n- Lương cứng:  10 - 20 triệu VND \n- Lương cứng không phụ thuộc doanh số\nQuyền lợi\n- Tổng thu nhập: từ 10 - 30 triệu (lương cứng + hoa hồng doanh số rõ ràng, hấp dẫn)\n- Thưởng theo hiệu suất KPI, theo năm và các dự án đặc biệt\n- Thưởng lễ / tết theo quy định của Luật lao động\n- Tăng lương theo năng lực/ định kỳ của công ty\n- Tham gia miễn phí các sự kiện thể thao do iRace tổ chức\n- Môi trường năng động, khuyến khích sáng tạo và đề xuất\n- Hưởng đầy đủ chế độ BHXH, BHYT, BHTN và các chế độ khác theo luật Lao Động\n- Được đào tạo chuyên sâu về ngành thể thao và kỹ năng làm việc thực chiến\n- Có nhiều cơ hội phát triển sự nghiệp và thăng tiến\n- Được tham gia các hoạt động teambuilding, dã ngoại với team & công ty...\n- Hưởng các chính sách phúc lợi khác theo quy định của công ty\nĐịa điểm làm việc\n- Hồ Chí Minh: Sảnh B1, Sarica, Đường N7, KĐT Sala, P. An Lợi Đông, Thủ Đức\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)\n- Nghỉ trưa: 12g - 13g30\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2802, 1476, 2, 'NET Developer (Mid/Senior) – Up To $1,300', 'Mô tả công việc: \n- Tham gia phát triển các dự án outsource cho khách hàng Nhật Bản.\n- Đọc và phân tích tài liệu yêu cầu chức năng từ khách hàng để đảm bảo hiểu rõ và đáp ứng chính xác.\n- Viết tài liệu thiết kế chi tiết, thực hiện coding và unit test với các dự án công nghệ .NET/PHP.\n- Triển khai (deploy) ứng dụng và tham gia vào các công việc liên quan đến DevOps (CI/CD, quản lý hạ tầng và tối ưu hóa hệ thống trên nền tảng AWS).\n- Không ngừng nghiên cứu và học hỏi công nghệ mới để nâng cao kỹ năng và năng suất làm việc.\n- Hỗ trợ và hướng dẫn các thành viên khác trong nhóm phát triển.\n- Tham gia các dự án khác theo yêu cầu của quản lý và Project Manager (PM).\n\nYêu cầu ứng viên: \n- Tốt nghiệp Đại Học Công Nghệ Thông Tin hoặc liên quan, ưu tiên Đại Học Quốc gia.\n- Trên 3 năm kinh nghiệm với VB.NET, C, ASP.NET MVC và PHP, Web API, AWS.\n- Ứng viên phải có kỹ năng giao tiếp tốt với thái độ tích cực.\n\nQuyền lợi: \nONETECH ASIA mang đến \n- Thu nhập hấp dẫn: 700$ - 1300$/tháng, thưởng dự án + lương tháng 13.\n- Thời gian linh hoạt: Thứ 2 - Thứ 6, 8:00 - 17:15 (nghỉ trưa 11:45 - 13:00).\n- Môi trường lý tưởng: Đội ngũ trẻ trung, sáng tạo, gắn kết qua team building và du lịch hàng năm.\n- Phúc lợi vượt trội: BHXH đầy đủ, tăng lương theo năng lực, khám sức khỏe định kỳ.\n- Đầu tư phát triển: Hỗ trợ chi phí thi chứng chỉ chuyên môn và phụ cấp khi đạt được.\n- Công nghệ đỉnh cao: Trải nghiệm Hololens 2, Oculus Quest, HTC Vive.\n\nĐịa điểm làm việc: \n- Hồ Chí Minh: 647 Lý Thường Kiệt, Tân Bình.\n\nCách thức ứng tuyển: \nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ho Chi Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2803, 1297, 2, 'Curriculum Developer', 'Mô tả công việc\n- Nghiên cứu, phát triển chương trình đào tạo mảng Coding (các khóa học lập trình, Global Developer; Computer Science, Blockchain, v.v) cho đối tượng sinh viên và người đi làm.\n- Điều phối workload và ra đề bài cho các CTV/chuyên gia ở các lĩnh vực đào tạo, đảm bảo nội dung bám sát với mô hình đào tạo của Trường học công nghệ MindX.\n- Nghiên cứu thị trường, đảm bảo việc phát triển bộ học liệu, đề test, mô hình đào tạo đáp ứng đúng nhu cầu thực tiễn, tiến độ và budget được giao.\n- Điều phối workload của các cộng tác viên, báo cáo và đề xuất định hướng phát triển sản phẩm với với R&D Team Lead.\n- Phối hợp với các phòng ban nội bộ (Marketing, Projects, Teaching, CXO, v.v) để thu nhận feedback và cải tiến chất lượng đào tạo (bao gồm học liệu, thiết kế trải nghiệm và phương pháp truyền đạt).\n\nYêu cầu ứng viên\n- Đã có kinh nghiệm trong lĩnh vực phát triển phần mềm, ưu tiên thành thạo trong lĩnh vực phát triển các ứng dụng Web, Mobile, Làm việc với các hệ thống dữ liệu.\n- Tốt nghiệp các chuyên ngành liên quan đến công nghệ thông tin: Khoa học máy tính, Cơ điện tử, Điện tử viễn thông, Toán tin ứng dụng.\n- Khả năng nghiên cứu, đọc hiểu tiếng Anh khá.\n- Chủ động và có trách nhiệm trong công việc, có kỹ năng giải quyết vấn đề.\n- Có kinh nghiệm giảng dạy hoặc R&D trong lĩnh vực giáo dục-công nghệ là một điểm cộng.\n- Kỹ năng giao tiếp, trình bày vấn đề mạch lạc, lập luận logic, rõ ràng.\n- Kỹ năng tư duy phản biện, hỏi lại khi chưa rõ đề bài, sẵn sàng chất vấn người quản lý trực tiếp và đưa ra quan điểm, đề xuất của mình.\n\nQuyền lợi\n- Lương cứng: 10,000,000 VND - 15,000,000 VND (tùy năng lực) + thưởng theo cơ chế.\n- Chế độ nghỉ phép, nghỉ lễ Tết, tham gia BHXH theo quy định của Nhà Nước.\n- Môi trường làm việc trẻ năng động, khuyến khích sự sáng tạo và tư duy làm chủ công việc.\n- Văn phòng hiện đại, không gian thoáng, có phòng nghỉ trưa, có hỗ trợ chi phí gửi xe.\n- Hỗ trợ tài khoản trên các platform học tập: Udemy, Coursera, EdX, etc.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 5, 71 Nguyễn Chí Thanh, Đống Đa.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2804, 1318, 2, 'Middle Fullstack Developer', 'Mô tả công việc: 1. Frontend UI/UX design and development using Vue.js and Nuxt.js 2. Backend API design and development using Node.js, Express, and MySQL 3. Design and development of payment systems and point management systems 4. Implementation of wallet integration and token issuance utilizing blockchain technology 5. System infrastructure setup and management using AWS and Docker 6. Collaboration with Japanese development teams to promote agile development processes 7. Improvement of code quality, refactoring, and performance optimization.\nYêu cầu ứng viên: 1. Native Vietnamese speaker 2. Experience with Node.js, JavaScript, and TypeScript 3. Experience in frontend design, development, and operation using Vue.js, Nuxt.js, etc. 4. Experience in backend development using Express and MySQL 5. Development and operational experience with AWS 6. Experience in Agile system development 7. Experience developing payment or point management systems 8. Experience developing high-traffic websites, large scale 9. Experience with SQL tuning/optimization.\nQuyền lợi: 1. Phép năm: 18 ngày nghỉ/năm 2. Hỗ trợ ăn trưa 3. Bảo hiểm xã hội toàn lương 4. Phụ cấp công tác 5. Lương tháng 13 6. Thưởng hiệu quả công việc: Tùy chọn cổ phiếu và ưu đãi.\nĐịa điểm làm việc: Hồ Chí Minh: 29 Nguyễn Bá Lân, Thảo Điền, Thủ Đức.\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 09:00 đến 18:00). Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thảo Điền, Thủ Đức, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2805, 209, 2, 'Java Engineer Good English', 'Mô tả công việc\n- Develop, and implement scalable and efficient Backend solutions using Java and Spring Boot.\n- Collaborate with cross-functional teams to understand project requirements and translate them into Backend functionalities.\n- Optimize code, integrate design patterns, and ensure high performance, reliability, and security of Backend systems.\n- Work with relational databases, write efficient SQL queries, and maintain data models.\n- Implement RESTful APIs with authentication, error handling, and versioning.\n- Perform unit testing, code reviews, and maintain code quality.\n- Collaborate with Frontend developers to integrate Frontend components with Backend services.\n- Debug and resolve issues reported by users or identified through testing and monitoring.\n- Stay updated with emerging technologies and industry trends in Backend development.\n- Support system integration according to the data interface specification, \n- Support SIT, UAT, non-functional test, etc.\n- Prepare technical related materials for the architecture, security, service transition and PCQA\n- Performing requirement analyses.\n- Developing high-quality and detailed designs.\n- Conducting unit testing using automated unit test frameworks.\n- Identifying risk and conducting mitigation action planning.\n- Conducting configuration of your own work.\n- Reviewing the work of other developers and providing feedback.\n\nYêu cầu ứng viên\n- Strong experience in Backend development using Java and Spring Boot 5 years +\n- Proficiency in Hibernate or other ORM frameworks.\n- Familiarity with relational databases, writing efficient SQL queries, and optimizing database performance.\n- Knowledge of RESTful API design principles and advance.\n- Familiarity with unit testing, code reviews, and DevOps tools (e.g.: Git, Jenkins, Artifactory, SonarQube, Kubernetes and cluster management / administration etc.).\n- Excellent teamwork and communication skills to manage the team.\n- Problem-solving abilities and attention to detail.\n- Experience with cloud platforms and containerization technologies (AWS, Azure and Private Cloud).\n- API Gateways – AWS, Azure, APIGEE.\n- Familiarity with Agile development methodologies is preferred.\n- Develop and test the solution according to the system design and integration\n- Support SIT, UAT, integration test, non-functional test, etc.\n- Backend technical skills including Java, Springboot, Hibernate, SQL DB, Swagger, Light4J\n- Infrastructure orchestration and initialization scripts to automate creation of complex virtual environments\n\nQuyền lợi\n- “FPT care” health insurance for FPT employees.\n- Annual Summer Vacation: follows company’s policy and starts from May every year\n- Salary review 1 times/year or on excellent performance\n- International, dynamic, friendly working environment\n- Annual leave, working conditions follow Vietnam labor laws.\n- Other allowances: lunch allowance, working on-site allowance, etc.\n\nĐịa điểm làm việc\n- Đà Nẵng\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nRemote hoặc Hybrid. Tuyển dụng cả 3 miền HN, HCM, DN\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2806, 1309, 2, 'Nhân Viên Lập Trình Tự Động Hóa', 'Mô tả công việc\n- Thực hiện các công việc kỹ thuật liên quan đến sản xuất và lắp ráp các sản phẩm cơ khí.\n- Đọc và hiểu bản vẽ kỹ thuật, sơ đồ lắp ráp.\n- Sử dụng các dụng cụ, máy móc cơ khí để gia công, chế tạo sản phẩm.\n- Kiểm tra chất lượng sản phẩm trước khi bàn giao.\n- Tuân thủ các quy trình an toàn lao động trong quá trình làm việc.\n- Thực hiện các nhiệm vụ khác được phân công bởi quản lý.\n\nYêu cầu ứng viên\n- Không yêu cầu kinh nghiệm.\n- Có kiến thức cơ bản về vật liệu, công nghệ gia công cơ khí.\n- Có khả năng sử dụng các dụng cụ, máy móc cơ khí cơ bản.\n- Khả năng đọc hiểu bản vẽ kỹ thuật.\n- Cẩn thận, tỉ mỉ, có trách nhiệm trong công việc.\n- Khả năng làm việc nhóm và tuân thủ kỷ luật.\n- Sức khỏe tốt, có thể làm việc trong môi trường nhà xưởng.\n\nQuyền lợi\n- Thu nhập từ 15 tới 18 triệu / tháng\n- Được đóng bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật.\n- Có chế độ nghỉ phép, nghỉ lễ, tết theo quy định.\n- Môi trường làm việc năng động, chuyên nghiệp.\n- Cơ hội được đào tạo, nâng cao tay nghề.\n- Thưởng các ngày lễ, tết, thưởng hiệu quả công việc.\n\nĐịa điểm làm việc\n- Bắc Giang: Tổ dân phố Phúc Long, Phường Tăng Tiến, Việt Yên\n\nThời gian làm việc\n- Thứ 2 - Chủ nhật (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2807, 1421, 2, 'Chuyên Viên Phát Triển Phần Mềm', 'Mô tả công việc\nXây dựng nhiệm vụ, xây dựng kế hoạch đưa phần mềm vào hoạt động và nghiệm thu:\n- Đề xuất điều chỉnh mục tiêu, mục đích yêu cầu\n- Đề xuất ký kết hợp đồng, phụ lục, thỏa thuận, nghiệm thu\n- Đánh giá test sản phẩm về công năng\n- Bổ sung tính năng và đưa phần mềm vào sử dụng\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chính quy chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan\n- Có kiến thức cơ bản về lập trình, cơ sở dữ liệu và phát triển phần mềm\n- Hiểu biết về quy trình phát triển phần mềm và các phương pháp quản lý dự án\n- Có khả năng tư duy logic và giải quyết vấn đề tốt\n- Kỹ năng giao tiếp và làm việc nhóm hiệu quả\n- Có kiến thức cơ bản về quản lý dự án là một lợi thế\n- Sẵn sàng học hỏi và cập nhật các công nghệ mới trong lĩnh vực bất động sản và xây dựng\n\nQuyền lợi\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội học hỏi và phát triển kỹ năng trong lĩnh vực công nghệ thông tin và bất động sản\n- Được đào tạo về quy trình, nghiệp vụ chuyên môn và kỹ năng mềm\n- Chế độ lương thưởng cạnh tranh, đánh giá năng lực định kỳ để tăng lương\n- Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của pháp luật\n- Tham gia các hoạt động team building, du lịch nghỉ mát hàng năm\n- Môi trường làm việc trẻ trung, cơ hội thăng tiến rõ ràng\n\nĐịa điểm làm việc\n- Hà Nội: 170 Ngọc Khánh, Ba Đình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 7: 9h -12h\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2808, 1328, 2, 'Solution Architect', 'Company Introduction\nDigiEx Group is a rapidly growing technology company based in Vietnam, with a mission to build a technology ecosystem and digital talent-hub in the country to be enabling global Tech companies to find the right resources to drive their digital transformation initiatives.\n\nWe offer a range of innovative solutions to help businesses transform digitally, including digital talent services, custom software development, cloud migration and management, and emerging tech R&D. Our tailored solutions are designed to meet the unique needs of each client, and our experienced team works closely with businesses to ensure their success in the rapidly evolving digital landscape.\n\nJob description\nWe are seeking a seasoned Solution Architect to lead the design and implementation of robust, scalable, and secure software solutions. This role demands a strategic thinker with a deep understanding of technology trends and the ability to align technical solutions with business objectives.\n\nYour responsibilities:\nArchitectural Leadership: Design and oversee the implementation of comprehensive software architectures that meet business requirements and align with industry best practices.\nStakeholder Collaboration: Engage with clients, project managers, and development teams to gather requirements and translate them into technical solutions.\nTechnology Evaluation: Assess emerging technologies and platforms to determine their applicability to our solutions and recommend adoption where beneficial.\nQuality Assurance: Ensure solutions meet performance, scalability, and security standards, conducting regular reviews and audits.\nDocumentation: Create and maintain detailed architectural documentation, including design specifications and integration plans.\nMentorship: Provide guidance and mentorship to development teams, fostering a culture of continuous learning and improvement.\nRisk Management: Identify potential risks in proposed solutions and develop mitigation strategies to address them proactively.\n\nYêu cầu ứng viên\nEducational Background: Bachelor\'s or Master\'s degree in Computer Science, Information Technology, or a related field.\nExperience: Minimum of 5 years in software development, with at least 2 years in a solution architecture role.\nTechnical Proficiency: \nExpertise in designing and implementing solutions using cloud platforms such as AWS, Azure, or Google Cloud.\nProficient in microservices architecture, RESTful APIs, and containerization technologies like Docker and Kubernetes.\nFamiliarity with programming languages such as Java, PHP, or JavaScript.\nCertifications: Relevant certifications (e.g., TOGAF, AWS Certified Solutions Architect) are highly desirable.\nSoft Skills: \nStrong analytical, problem-solving, and communication skills (both verbal and written). Ability to work collaboratively in cross-functional teams. \nExcellent leadership, team-building, and interpersonal communication skills.\nDemonstrated experience mentoring engineers or leading technical teams.\nFluent in English (spoken and written) and strong presentation skills.\nExperience working in startup or fast-growth environments.\nPrior involvement in technical hiring, building development processes, or setting team standards.\nTakes ownership beyond individual projects.\nDemonstrates business acumen alongside technical depth.\nIs passionate about building technology-driven teams that scale.\nHas a strong sense of responsibility in shaping technical culture and company direction.\nThis role is strategically positioned for transition into a CTO role in the near future.\n\nQuyền lợi\nFlexible working hours, a dynamic, innovative, and friendly environment.\nAttractive income package as negotiation.\nGreat opportunity to grow career path, personal development, and challenging projects.\nDevelop a global career path by providing many pieces of training (Technical & Soft skills).\nHave a chance to work directly with the CTO/CEO of many Startups around the world.\nWe have a strong remote workforce & global culture with team members from different countries.\n\nĐịa điểm làm việc\nHồ Chí Minh: Floor 8th, QTSC Building 1, Quang Trung Software Park, 14th Street, Tan Chanh Hiep Ward, District 12, Quận 12\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2809, 1471, 2, 'Nhân Viên Lập Trình CNC', '- Vẽ & lập trình các chi tiết gỗ nội thất cho máy CNC.\n- Set-up máy, thay dao chỉnh cỡ để đánh mẫu & chạy hàng SX.\n- Mài dao, bảo trì máy móc CNC theo kế hoạch bảo dưỡng định kỳ.\n- Vận hành chạy hàng SX theo phân công khi đã xong việc chỉnh cỡ.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Cao đẳng hoặc Đại học\n- Có kinh nghiệm vận hành máy CNC ngành gỗ là ưu tiên\n- Có tính cẩn thận, chịu khó\n- Làm việc tại nhà máy.\n\nQuyền lợi:\n- Lương, thưởng cạnh tranh\n- Được tham gia BHXH, BHYT, BHTN\n- Lương thứ 13 theo hoạt động kinh doanh\n- Hỗ trợ nhà ở miễn phí\n- Hỗ trợ Nhà trẻ, trường học cho con em NLĐ.\n\nĐịa điểm làm việc:\n- Bình Dương: Khu phố Khánh Lộc, P Tân Phước Khánh, Tân Uyên.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 07:30 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2810, 1143, 2, 'Lập Trình Viên ReactJS', 'Mô tả công việc:\n- Phát triển và Xây dựng các hệ thống web sử dụng ReactJS.\n- Tối ưu hóa hiệu suất và đảm bảo tính tương thích trên các thiết bị và trình duyệt khác nhau.\n- Tham gia vào quá trình phân tích yêu cầu, thiết kế và lập kế hoạch dự án.\n- Làm việc với các thành viên khác trong nhóm phát triển để hoàn thành các dự án đúng tiến độ.\n- Cập nhật kiến thức và kỹ năng về các công nghệ mới và xu hướng trong ngành.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Ít nhất 2 năm kinh nghiệm làm việc với ReactJS.\n- Hiểu biết sâu về TypeScript, JavaScript, HTML5, CSS3.\n- Kinh nghiệm làm việc với Redux và Redux Toolkit.\n- Kiến thức về RESTful API và WebSocket.\n- Kỹ năng làm việc với Git và các công cụ quản lý mã nguồn.\n- Khả năng làm việc độc lập và trong môi trường nhóm.\n- Kỹ năng giao tiếp tốt, chủ động và tinh thần trách nhiệm cao.\n- Có tư duy phân tích tốt để cùng team giải quyết các vấn đề trong công việc.\n\nQuyền lợi:\n- Mức lương từ: 15-30 triệu/tháng tùy theo năng lực.\n- Thưởng dự án theo hiệu quả công việc.\n- Môi trường làm việc trẻ trung, chuyên nghiệp và sáng tạo.\n- Cơ hội tham gia vào các dự án lớn của công ty trong lĩnh vực Elearning.\n- Chế độ bảo hiểm và các phúc lợi khác theo quy định của công ty.\n\nĐịa điểm làm việc:\n- Hà Nội: Khu văn phòng Trường mầm non Thành Đông, khu đô thị mới Phùng Khoang, phường Trung Văn, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2811, 1389, 2, 'Lập Trình Viên Java', 'Mô tả công việc\n- Phát triển và bảo trì hệ thống backend sử dụng Java và các framework phổ biến như Spring Boot, Spring MVC, Hibernate, Quarkus, Micronaut,MyBatis.\n- Thiết kế và phát triển RESTful API, GraphQL API.\n- Làm việc với các hệ quản trị cơ sở dữ liệu SQL (MySQL, PostgreSQL, Oracle) và NoSQL (MongoDB, Redis, Cassandra, Elasticsearch).\n- Xây dựng hệ thống xử lý dữ liệu theo kiến trúc Event-driven với Kafka, RabbitMQ, ActiveMQ.\n- Tối ưu hiệu suất, bảo mật hệ thống và xử lý concurrency.\n- Tích hợp với các dịch vụ OAuth 2.0, JWT, OpenID Connect.\n- Làm việc với các công cụ DevOps: Docker, Kubernetes, Jenkins, GitLab CI/CD.\n- Viết tài liệu kỹ thuật và hỗ trợ debugging hệ thống.\n\nYêu cầu ứng viên\n- Tối thiểu 4 năm kinh nghiệm làm việc với Java Backend.\n- Thành thạo ít nhất một framework backend: Spring Boot, Quarkus hoặc Micronaut.\n- Hiểu sâu về mô hình Microservices, Monolithic, Event-driven architecture.\n- Có kinh nghiệm làm việc với Caching (Redis, Ehcache), Message Queue (Kafka, RabbitMQ).\n- Thành thạo SQL và NoSQL, có kinh nghiệm với Hibernate, JPA, Query Optimization.\n- Biết triển khai ứng dụng trên AWS, GCP hoặc Azure là lợi thế.\n- Biết tiếng Anh là lợi thế\n- Có tư duy logic tốt, khả năng làm việc nhóm và giải quyết vấn đề.\n\nQuyền lợi\n- Mức lương hấp dẫn, có thể tự do thỏa thuận;\n- Làm việc 5 ngày/tuần, không tăng ca;\n- Không gian làm việc thoải mái, đồng nghiệp thân thiện;\n- Có cơ hội học hỏi kiến thức mới và nâng cao năng lực chuyên môn;\n- Thử việc 100% lương, lương tháng thứ 13, có xét nâng lương hàng năm;\n- Có chế độ nghỉ hè, nghỉ Trung Thu, Giáng Sinh\n- Bảo hiểm xã hội, khám sức khỏe định kỳ.\n\nĐịa điểm làm việc\n- Hà Nội: Số 3 - A24 Ngõ 385 Hoàng Quốc Việt, Phường Nghĩa Tân, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 07:30 đến 16:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2812, 1137, 2, 'Frontend Developer (Nextjs) Level Middle/Senior', 'Mô tả công việc:\n- Phát triển, tối ưu hóa và duy trì các ứng dụng web chất lượng cao, thân thiện với nhiều thiết bị sử dụng NextJS;\n- Hợp tác với các lập trình viên backend, thiết kế UI/UX và các thành viên khác trong nhóm để đảm bảo quy trình phát triển hiệu quả và liền mạch;\n- Áp dụng các phương pháp phát triển web hiện đại, đảm bảo tính mở rộng, hiệu năng và bảo mật;\n- Xây dựng các thành phần và thư viện giao diện có thể tái sử dụng cho các dự án trong tương lai;\n- Gỡ lỗi và khắc phục các điểm nghẽn về hiệu suất, đảm bảo tính năng hoạt động mượt mà trên nhiều trình duyệt và thiết bị;\n- Luôn cập nhật các xu hướng, công nghệ và thực hành tốt nhất trong lĩnh vực phát triển front-end;\n- Đóng góp ý tưởng và giải pháp nhằm cải thiện tính năng sản phẩm và trải nghiệm người dùng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành công nghệ thông tin, khoa học máy tính hoặc các ngành có liên quan;\n- Có từ 3 – 5 năm kinh nghiệm làm việc với ReactJS/NextJS;\n- Thành thạo HTML5, CSS3, JavaScript (ES6+) và TypeScript;\n- Hiểu rõ kiến trúc dựa trên component và các phương pháp quản lý trạng thái (ví dụ: Redux, Context API, Zustand,...);\n- Có kinh nghiệm thiết kế giao diện responsive và xây dựng ứng dụng tương thích đa trình duyệt;\n- Quen thuộc với kỹ thuật render phía máy chủ (SSR) và tạo trang tĩnh (SSG) trong NextJS;\n- Am hiểu về RESTful APIs và tích hợp API vào ứng dụng front-end;\n- Sử dụng thành thạo Git hoặc các hệ thống quản lý phiên bản khác;\n- Kỹ năng phân tích và giải quyết vấn đề tốt;\n- Kỹ năng giao tiếp và khả năng làm việc nhóm tốt;\n- Tự chủ trong công việc và có khả năng làm việc độc lập.\n\nQuyền lợi:\n- Mức lương (gross): lên đến 30 triệu hoặc lên đến 40 triệu đối với level Senior (thoả thuận khi phỏng vấn);\n- Thưởng tháng 13, thưởng thâm niên, thưởng hàng quý, thưởng chia lợi nhuận;\n- 12 ngày nghỉ phép năm;\n- Xét tăng lương theo hiệu suất vào tháng 6 và tháng 12;\n- Thưởng các dịp lễ như 30/4 - 1/5, 2/9, Tết Dương lịch,...;\n- Tổ chức sinh nhật, tặng quà vào các dịp như Tết Nguyên Đán, Quốc tế Phụ nữ (8/3, 20/10), Trung Thu, Tết Thiếu nhi (1/6), và nhiều dịp khác;\n- Miễn phí trà, đồ ăn nhẹ, cà phê tại văn phòng; hỗ trợ phí gửi xe;\n- Được trang bị đầy đủ thiết bị và công cụ phục vụ công việc hiệu quả;\n- Tham gia vào các hoạt động sôi nổi của công ty: tiệc hàng quý, du lịch thường niên, team building/cắm trại hàng quý, tiệc tất niên và nhiều hoạt động khác.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa MD Complex, 68 Nguyễn Cơ Thạch, Mỹ Đình 1, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2813, 1265, 2, 'Java Backend', 'Mô tả công việc\n- Xây dựng các module lõi cho nền tảng Logistics thế hệ mới của ViettelPost. \n- Tối ưu hóa các nghiệp vụ, thuật toán, kiến trúc để nâng cao chất lượng sản phẩm.  \n- Làm việc trực tiếp với các đội nghiệp vụ để thực thi sản phẩm theo đúng yêu cầu. Tư vấn ngược lại cho đội nghiệp vụ để thông minh hóa quy trình.  \n- Xây dựng các sản phẩm mới phục vụ hàng triệu người dùng của ViettelPost\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học các chuyên ngành CNTT, Khoa học máy tính,... Ưu tiên ứng viên tốt nghiệp các trường Bách Khoa, Học viện kỹ thuật quân sự, Học viện Bưu chính, ĐH Công nghệ-ĐH Quốc gia Hà Nội, Đại học FPT hoặc các trường ĐH quốc tế.\n- Level Senior yêu cầu có 4++ năm kinh nghiệm phát triển phần mềm trở lên với ngôn ngữ JAVA, có kinh nghiệm với các framework như Spring, Quarkus, ZK.\n- Level Junior yêu cầu có 2++ năm kinh nghiệm phát triển phần mềm trở lên với ngôn ngữ JAVA, có kinh nghiệm với các framework như Spring, Quarkus, ZK.\n- Có kinh nghiệm làm việc với một trong các Database Oracle, MariaDB, Postgre, MongoDB, Redis, ElasticSearch.\n- Có kinh nghiệm làm việc với một trong các hệ thống Message Queue (Kafka, RabbitMQ, MQTT)\n- Có hiểu biết về thiết kế hệ thống, design pattern, OOP là một lợi thế.\n- Sử dụng thành thạo các công cụ quản lý code như SVN, Github.\n- Có kiến thức triển khai cơ bản hệ thống trên hệ điều hành Linux.\n- Có khả năng làm việc độc lập và làm việc nhóm, chịu được áp lực cao.\n- Có khả năng tư duy logic và nghiên cứu công nghệ mới\n- Có khả năng đọc hiểu tài liệu tiếng Anh chuyên ngành.\n\nQuyền lợi\n1. Chế độ về lương thưởng, thu nhập\n- Mức lương 15M - 20M với Junior, 20M - 35M với Middle, 35M - 55M với Senior\n- Có chế độ hỗ trợ tiền điện thoại và ăn trưa, nghỉ mát hàng năm; kèm theo là các khoản thưởng vào các dịp lễ lớn (30/4, 1/5, 2/9, ngày thành lập Tập đoàn, Tổng Công ty, Tết Dương/ Âm)\n2. Chương trình chăm sóc sức khỏe\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và các gói bảo hiểm sức khỏe khác.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n- Phụ nữ có con nhỏ dưới 1 tuổi sẽ được nghỉ thêm 1h/ngày\n3. Đào tạo, phát triển\n- Hàng tuần, công ty tổ chức buổi Seminar trao đổi, chia sẻ về các công nghệ mới nhất; là cơ hội để các thành viên học hỏi lẫn nhau.\n- Được tham gia các khóa học bổ ích từ các diễn giả Quốc tế tại Học viện Viettel\n- Có cơ hội thăng tiến trong nghề nghiệp.\n4. Hoạt động tập thể hấp dẫn, phong phú\n- Tham gia vào hoạt động \'Happy Time\' vào chiều thứ 6 hàng tuần cùng với chương trình sinh nhật tháng.\n- Chương trình teambuilding, văn hóa, du lịch nghỉ mát hấp dẫn và đa dạng.\n- Các hoạt động thể dục thể thao cùng các giải đấu được Tập đoàn tổ chức.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Viettel Post, số 2 ngõ 15 Duy Tân, Cầu Giấy.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2814, 1298, 2, 'Lập Trình Viên Java', 'Mô tả công việc:\n- Tham gia vào quá trình phân tích yêu cầu, thiết kế, phát triển và triển khai các ứng dụng phần mềm cho các hệ thống của ngân hàng.\n- Theo dõi hiệu suất hệ thống, phát hiện và khắc phục các lỗi phát sinh.\n- Làm việc chặt chẽ với các thành viên khác trong nhóm và các bộ phận liên quan của ngân hàng.\n- Xây dựng Tài liệu kỹ thuật, tài liệu đào tạo, hướng dẫn theo quy trình của dự án và theo yêu cầu của đơn vị.\n- Thực hiện các công việc khác theo sự phân công của quản lý dự án.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học hệ chính quy chuyên ngành Công nghệ Thông tin, Toán tin, Điện tử Viễn thông hoặc tương đương;\n- Thành thạo ngôn ngữ lập trình Java, Spring Boot, Angular, React JS, Strust, Jsp, Javascript, Ajax, Jquery, HTML, CSS ...\n- Thành thạo cơ sở dữ liệu Oracle, MS SQL, Postgre SQL\n- Có kiến thức về Monolithic, Micro-Service, ...\n- Có kiến thức về DevOps, CI/CD;\n- Có kinh nghiệm phát triển Restful API sử dụng ngôn ngữ Java;\n- Có kinh nghiệm sử dụng git như Git, GitLab, Docker container;\n- Có kinh nghiệm trong việc phát triền FrontEnd, BackEnd API;\n- Có kinh nghiệm (tối thiểu 02 năm) và nắm vững về Java Spring Boot\n- Có kinh nghiệm (tối thiểu 02 năm) làm việc Frontend Angular\n- Có kinh nghiệm (tối thiểu 01 năm) làm việc trên cơ sở dữ liệu PostgreSQL\n- Có kinh nghiệm phát triển trên nền tảng BPM (ví dụ IBM, Camunda )\n- Có khả năng tối ưu xử lý truy vấn dữ liệu lớn, sử dụng caching.\n\nƯu tiên:\n- Ưu tiên ứng viên có kinh nghiệm, hiểu biết về dịch vụ tài chính ngân hàng\n- Ưu tiên ứng viên đã từng làm với một trong các hệ thống như Loan Original System, Trade Finance, Supply Chain Finance, Credit Scoring\n- Có kỹ năng giao tiếp, thuyết trình tốt;\n- Có khả năng làm việc độc lập và theo nhóm tốt;\n- Có khả năng nghe, nói, đọc, viết bằng tiếng Anh;\n- Nhiệt tình, đam mê học hỏi, chịu được áp lực và thử thách.\n\nQuyền lợi:\n- Lương: 20.000.000đ – 30.000.000đ\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30. \n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Làm việc onsite tại ngân hàng số 1 Việt Nam, trực tiếp tham gia vào các dự án tiên phong về chuyển đổi số.\n- Nghỉ phép: 12 ngày/năm\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN cho 100% cán bộ sau thời gian thử việc. \n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Thu nhập: lương tháng 13; thưởng theo dự án, thưởng theo kết quả kinh doanh và mức độ đóng góp; thưởng theo năng lực và mức độ hoàn thành công việc của từng thành viên – đánh giá hàng tháng và trả thưởng theo quý; thưởng các ngày lễ lớn.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 22 tòa nhà Viwaseen, số 48 Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2815, 1400, 2, 'C#.NET Leader', 'Mô tả công việc:\n・Participate in building the company\'s own product and outsource projects\n・Cooperate with other teams on all phases of project development\n・Contribute to system architecture and design decisions\n・Deliver good quality code\n・Be able to self-study on new technologies\n・Be dynamic and proactive\n\nYêu cầu ứng viên:\n1. Basic Skills:\n・ Someone who takes initiative and can work proactively.\n・Has a positive attitude and forward-thinking mindset.\n・ Enjoys creating new things with a pioneering mindset.\n・Willingness to learn new technologies.\n・Strong communication skills and the ability to collaborate effectively with a team.\n・Able to communicate in English.\n\n2. Technical Skills And Experiences (Required)\n・Proficient in C# with advanced features such as LINQ, Delegates, Events, and Lambda Expressions.\n・Strong understanding of .NET Framework features, especially Windows Forms (WinForms), WPF (Windows Presentation Foundation), and UWP (Universal Windows Platform), depending on the application\'s requirements.\n・Experience in handling Exceptions, Debugging, and Unit Testing.\n・Experience with Entity Framework or ADO.NET to connect applications to databases, perform queries, and manipulate data.\n\n3. Technical Skills and Experience (Preferred Qualifications)\n・Has experience working with Japanese clients, markets, or companies.\n・Experienced in source code optimization, refactoring, and code review.\n・Believes that building excellent applications requires more than just delivering “working” code — it must also consider reusability, maintainability, security, and performance.\n\nQuyền lợi:\n・Salary review:  Once a year\n・Commuting allowance\n・Annual paid leave  (Granted collectively in April), public holidays are in accordance with labor laws.\n・Company trips\n・Regular health check-ups: Once a year\n・Participation in regular sports activities such (badminton, bowling, etc.): Once a month\n・Company parties and other internal events\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Bình Thạnh\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2816, 1108, 2, 'Backend Developer', 'ORBRO, một công ty startup IT đang trên đà phát triển nhanh chóng, chúng tôi đang tuyển dụng lập trình viên backend!\nORBRO là một đội ngũ luôn sẵn sàng đối mặt với thử thách, phá vỡ các khuôn mẫu truyền thống để phát triển công nghệ tiên tiến và mở ra những thị trường mới. Hiện tại, chúng tôi đang tuyển dụng 10 thành viên đầu tiên để gia nhập đội ngũ tại Việt Nam, nhằm mở rộng và vươn ra thị trường toàn cầu. Chúng tôi mong muốn tìm kiếm những tài năng nhiệt huyết, sẵn sàng cùng nghiên cứu và quảng bá để khai phá tương lai.\n\nCông ty chúng tôi đang phát triển các hệ thống server và backend cho các thiết bị dựa trên AIoT và Embedded. Lập trình viên sẽ đảm nhận toàn bộ quá trình phát triển backend, từ các lightweight server tích hợp trong sản phẩm đến việc liên kết với cloud, bao gồm thiết kế và tối ưu hóa hệ thống, quản lý luồng dữ liệu và tăng cường bảo mật.\n\nNhiệm vụ chính\n• Thiết kế và triển khai kiến trúc server tối ưu cho môi trường AIoT và Embedded.\n• Thiết kế, tối ưu hóa database để thu thập, xử lý và lưu trữ dữ liệu.\n• Phát triển hệ thống dựa trên multi-thread/multi-process cho xử lý và streaming video thời gian thực.\n• Thiết kế, triển khai và tăng cường bảo mật cho server API dựa trên REST API, WebSocket.\n• Xây dựng, vận hành và bảo trì server trên môi trường cloud như AWS.\n• Tối ưu hóa hiệu suất và lightweight server (tối ưu hóa bộ nhớ/CPU, cải thiện latency).\n\nYêu cầu ứng viên\nKỹ năng cần thiết\n• Kinh nghiệm thiết kế và tối ưu hóa kiến trúc server.\n• Hiểu biết về lập trình multi-thread, multi-process.\n• Kinh nghiệm thiết kế và vận hành database như MySQL, PostgreSQL, MongoDB.\n• Kinh nghiệm phát triển server REST API và WebSocket.\n• Kinh nghiệm về tăng cường bảo mật và xử lý xác thực.\n\nƯu tiên\n• Kinh nghiệm phát triển server AIoT, Embedded.\n• Kinh nghiệm xây dựng dịch vụ dựa trên nền tảng cloud như AWS.\n• Kinh nghiệm phát triển hệ thống xử lý video thời gian thực (Streaming, Encoding, Decoding, v.v.).\n• Kinh nghiệm với nhiều ngôn ngữ lập trình khác nhau như C/C++, Python, Node.js.\n\nQuyền lợi\n• Lương: Thỏa thuận.\n• Tham gia các hoạt động Team Building.\n• Hỗ trợ thiết bị laptop khi cần thiết.\n• Môi trường làm việc trẻ trung năng động, chuyên nghiệp, kích thích sự sáng tạo.\n• Các chế độ khác theo đúng quy định pháp luật.\n\nĐịa điểm làm việc\n- Hà Nội: Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2817, 1122, 2, 'Senior Java Developer', '● Work as software developer on the web-based application product in JAVA- related and open-source technologies \n● Develop applications based on graphical layout designs that follow the strict requirements \n● Take ownership and accountability for production service, including fix on fail, problem investigation, root cause determination, and resolution \n● Participate in and provide quality assurance activities, including code reviews, white-box testing, test coverage for own work and team outcome \n● Accountable for continuously discovering, evaluating and implementing new technologies/processes to optimize development efficiency or improve product quality \n● Establish estimation, proposing development solutions with customers \n● Continuously research and implement new technologies to maximize development efficiency \n\n● Good command of English (both written/verbal) is essential \n● At least 5 years of experience in software & back-end development technologies in general \n● At least 1 year of experience with Finance + eCommerce \n● Proven hands-on experience on Java ecosystem, Spring boot, Microservices, SQL, NoSQL: MongoDB, … \n● Experience in designing & developing RESTful APIs and microservices-based system; \n● Strong knowledge of writing secured codes and good understanding of design patterns \n● Working knowledge of Scala/Spark/Kafka or any functional programming languages is a very BIG plus \n● Experienced in developing and deploying microservices with Cloud based technologies (AWS, Kubernetes, Docker…) \n● Experience in agile scrum-based development process \n● Experience with unit test \n\nDESIRED SKILLS \n● Experience as software engineer in a complex, enterprise-level development projects \n● Establish software development patterns and best practices via examples and shipping code \n● Develop architectures that are inherently secure, robust, scalable, modular, API-centric and global. \n● Collaborate with business team to develop and clarify requirements to enable development of technical solutions \n● Provide executive level support for initiatives, particularly as related to re-use, funding requirements and areas of risk \n● Multi-tasking ability essential to handle multiple priorities with minimal direction from management \n\nBenefits: \n- Probation salary is 100% of official salary; \n- 13th-month salary and performance review twice a year; \n- Bonus for special occasions each year (Labor Day, National Day, Solar New Year, Lunar New Year); \n- Enjoy company summer trip and other team building activities held monthly and quarterly; \n- IT Certificate allowance as regulated; \n- Social, health and unemployment Insurance following Government policy; \n- Health Care Insurance; \n- Have chances to gain knowledge on the latest waves of blockchain, AI, Big Data; Professional, creative and dynamic working environment; \n- Work five days per week with flexible check-in time. \n\nPlace of work: \n- Hà Nội: Tòa The Nine, số 9 Phạm Văn Đồng, Mai Dịch, Cầu Giấy \n- Hồ Chí Minh: Điện Biên Phủ, Bình Thạnh \n\nWorking time: Check in-out linh hoạt. \n\nHow to apply: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2818, 1122, 2, 'Java Technical Lead', 'Mô tả công việc\n- Work as senior software developer on the web-based application product in JAVA- related and open-source technologies\n- Develop applications based on graphical layout designs that follow the strict requirements\n- Take ownership and accountability for production service, including fix on fail, problem investigation, root cause determination, and resolution\n- Participate in and provide quality assurance activities, including code reviews, white-box testing, test coverage for own work and team outcome\n- Accountable for continuously discovering, evaluating and implementing new technologies/processes to optimize development efficiency or improve product quality\n- Establish estimation, proposing development solutions with customers\n- Foster collaboration across technical teams through mentoring and expert guidance as required to develop the most cost-effective solutions\n- Continuously research and implement new technologies to maximize development efficiency\n\nYêu cầu ứng viên\n- At least 5 years of experience in software & back-end development technologies in general\n- Proven hands-on experience on Java ecosystem, Spring boot, Microservices, SQL, NoSQL: MongoDB, Cassandra…\n- Experience in designing & developing RESTful APIs and microservices-based systems.\n- Strong knowledge of writing secured codes and good understanding of design patterns\n- Experienced in developing and deploying microservices with Cloud based technologies (AWS, Kubernetes, Docker…)\n- Experience in agile scrum-based development process\n\nDESIRED SKILLS\n- Experience as software engineer in a complex, enterprise-level development projects\n- Establish software development patterns and best practices via examples and shipping code\n- Develop architectures that are inherently secure, robust, scalable, modular, API-centric and global.\n- Collaborate with business team to develop and clarify requirements to enable development of technical solutions\n- Provide executive level support for initiatives, particularly as related to re-use, funding requirements and areas of risk\n- Multi-tasking ability essential to handle multiple priorities with minimal direction from management\n- Excellent soft skills: leading client and team discussions, team player, ability to train others\n- Good knowledge & experience in other new technologies e.g. Blockchain, AI, etc.\n\nQuyền lợi\n- Probation salary is 100% of official salary\n- 13th-month salary and performance review twice a year\n- Bonus for special occasions each year (Labor Day, National Day, Solar New year, Lunar New Year)\n- Project Bonuses\n- Employee’s professional certification and training allowances subject to company regulations\n- Health Care Insurance\n- Annual Health Assessment\n- Social, health and unemployment Insurance following Government policy\n- Enjoy company summer trips and other team building activities held monthly and quarterly\n- Work five days per week with flexible check in time\n- Professional, creative and dynamic working environment\n\nĐịa điểm làm việc\n- Hà Nội: Tòa The Nine, Số 9 Phạm Văn Đồng, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2819, 1410, 2, 'Senior Fullstack Developer', 'GSV DTech (trực thuộc GSV Group) là công ty công nghệ ra đời với sứ mệnh đồng hành cùng ngành y tế Việt Nam trên hành trình chuyển đổi số toàn diện. Chúng tôi phát triển các giải pháp ứng dụng trí tuệ nhân tạo (AI), dữ liệu lớn (Big Data) và nền tảng số hiện đại – nhằm giải quyết các vấn đề cốt lõi trong quản lý và vận hành hệ thống y tế.\n\nChúng tôi đang cần tìm kiếm Senior Fullstack Developer với nhiệm vụ cụ thể:\n- Tham gia xây dựng, phát triển các dự án phần mềm mới của công ty\n- Bảo trì, nâng cấp, cập nhật các dự án phần mềm hiện có\n- Hỗ trợ vận hành, tìm hiểu nhu cầu và phản hồi từ người sử dụng để đề xuất các cập nhật, nâng cấp hoặc xây mới cần thiết\n- Chủ động ước lượng và kiểm soát công việc đã nhận\n- Tham gia nghiên cứu và trình bày các công nghệ mới\n- Báo cáo và thực hiện các công việc theo yêu cầu của quản lý\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin hoặc tương đương\n- Có ít nhất 4 năm kinh nghiệm với ASP.NET Core, C#, Web API\n- Thành thạo lập trình với hệ CSDL: SQL server hoặc MySQL\n- Bắt buộc thành thạo HTML, CSS, Jquery, Angular hoặc ReactJS\n- Ưu tiên có kinh nghiệm làm việc với RabbitMQ\n- Ưu tiên có kinh nghiệm phát triển các sản phẩm Product, các sản phẩm phần mềm "Software As a Service"\n- Ưu tiên ứng viên có kinh nghiệm phát triển các sản phẩm phần mềm về Y tế\n- Có khả năng giao tiếp tốt, chủ động, trung thực, năng động, khả năng làm việc nhóm tốt. Có trách nhiệm cao, và chịu được áp lực công việc\n- Có khả năng học hỏi nhanh, thích tìm hiểu và thực hiện các công việc mới\n\nQuyền lợi:\n- Thu nhập upto 35 triệu\n- Phụ cấp ăn trưa 35k/ngày\n- Nghỉ 2 ngày/tuần và các ngày lễ tết theo quy định của nhà nước, 12 ngày nghỉ phép\n- Môi trường làm việc chuyên nghiệp, năng động, thân thiện, ổn định\n- Tham gia BHXH theo quy định\n- Được khám sức khỏe hàng năm tại bệnh viện ĐH Y Hà Nội\n- Thưởng quý, năm, thưởng xếp loại nhân viên hàng năm, tháng lương 13, thưởng các ngày lễ, tết và các chế độ khác......\n- Được sử dụng dịch vụ của phòng khám, mua sản phẩm của công ty với giá ưu đãi nhân viên\n- Tham gia nhiều hoạt động của công ty: teambuilding, tất niên, du xuân, du lịch nước ngoài đặc biệt 5 năm/lần, kỷ niệm các ngày lễ, ...\n\nĐịa điểm làm việc:\n- Hà Nội: No 17 Ô 29 Lk 17, Khu đất dịch vụ, La khê, Hà Đông\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Trưa nghỉ 1,5h\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Đông, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2820, 1265, 2, 'Web Frontend Angular', 'Mô tả công việc\n- Thiết kế và triển khai frontend code của các ứng của các ứng dụng web đa nền tảng Javascript bằng cách sử dụng framework/ ngôn ngữ như Angular\n- Xây dựng hệ thống điều khiển cấu hình IoT, thanh toán, ví điện tử, hệ thống bản đồ, ứng dụng Selfcare, sàn thương mại điện tử, hệ thống core chuyển phát.\n- Thiết kế và triển khai các công cụ hỗ trợ theo yêu cầu.\n- Phối hợp với team để đẩy mạnh công nghệ UI hiện có và tạo trải nghiệm người dùng tốt nhất cho các hệ thống hiện tại.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học trở lên, chuyên ngành: công nghệ thông tin, khoa học máy tính,... Ưu tiên ứng viên tốt nghiệp các trường Bách Khoa, Học viện Bưu chính, ĐH Công nghệ-ĐH Quốc gia Hà Nội.\n- 2+ năm kinh nghiệm làm frontend web bằng Angular\n- Có kinh nghiệm xây dựng website sử dụng HTML, CSS, Javascript\n- Có kiến thức về OOP, Design Patterns, REST API và những cơ sở dữ liệu như MongoDB, MySQL, Elastic Search...\n- Có hiểu biết về thiết kế hệ thống, tối ưu và nâng cao hiệu năng, độ ổn định.\n- Tư duy mở, sẵn sàng học và tìm hiêu các công nghệ mới. Có trách nhiệm với công việc.\n\nQuyền lợi\nTại Tổng Công ty Cổ phần Bưu chính Viettel, các ứng viên sẽ được làm việc trong môi trường năng động, trẻ trung và chuyên nghiệp, với các đãi ngộ hấp dẫn sau:\n1.Chế độ về lương thưởng, thu nhập\n- Mức lương từ 15M - 20M đối với Junior, 20M - 30M đối với Mid - Senior, 30M++ đối với Senior\n- Có chế độ hỗ trợ tiền điện thoại và ăn trưa, nghỉ mát hàng năm; kèm theo là các khoản thưởng vào các dịp lễ lớn (30/4, 1/5, 2/9, ngày thành lập Tập đoàn, Tổng Công ty, Tết Dương/ Âm)\n2.Chương trình chăm sóc sức khỏe\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và các gói bảo hiểm sức khỏe khác.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n- Phụ nữ có con nhỏ dưới 1 tuổi sẽ được nghỉ thêm 1h/ngày\n3.Đào tạo, phát triển\n- Hàng tuần, công ty tổ chức buổi Seminar trao đổi, chia sẻ về các công nghệ mới nhất; là cơ hội để các thành viên học hỏi lẫn nhau.\n- Được tham gia các khóa học bổ ích từ các diễn giả Quốc tế tại Học viện Viettel\n- Có cơ hội thăng tiến trong nghề nghiệp.\n4.Hoạt động tập thể hấp dẫn, phong phú\n- Tham gia vào hoạt động \'Happy Time" vào chiều thứ 6 hàng tuần cùng với chương trình sinh nhật tháng.\n- Chương trình teambuilding, văn hóa, du lịch nghỉ mát hấp dẫn và đa dạng.\n- Các hoạt động thể dục thể thao cùng các giải đấu được Tập đoàn tổ chức.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Viettel Post, Số 2, Ngõ 15, Duy Tân, Dịch Vọng Hậu, Cầu Giấy\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2821, 1280, 2, 'AI Engineer ( Artificial Intelligence) / Developer / Kỹ Sư AI', '● Xây dựng pipeline xử lý dữ liệu từ các nguồn như livestream, video, text, audio,...\n● Triển khai các thuật toán AI/ML cho các bài toán như:\n- Natural Language Processing (NLP)\n- Computer Vision (CV)\n- Speech-to-Text / Voice Analysis\n- Recommendation Systems\n● Kết hợp AI với các hệ thống backend / API nội bộ để phục vụ nhu cầu thực tế.\n● Nghiên cứu và ứng dụng các mô hình AI mã nguồn mở (open-source), pre-trained models, fine-tuning phù hợp với dữ liệu của công ty.\n● Làm việc chặt chẽ với các team Backend, Game, Data Analyst để tích hợp AI vào sản phẩm.\n\nYêu cầu ứng viên\nBẮT BUỘC:\n● Tốt nghiệp chuyên ngành CNTT, Khoa học dữ liệu, Toán tin, hoặc tương đương.\n● Thành thạo ít nhất 1 ngôn ngữ lập trình dùng trong AI/ML (Python, PyTorch, TensorFlow,...)\n● Có kinh nghiệm với ít nhất 1 nhóm bài toán AI (NLP / CV / Voice / Recommendation)\n● Có tư duy triển khai thực tế: biết cách chuyển mô hình AI thành sản phẩm sử dụng được.\n● Biết cách xử lý dữ liệu, huấn luyện và đánh giá mô hình ML.\n\nƯU TIÊN:\n● Từng làm việc trong startup hoặc môi trường agile, tốc độ nhanh.\n● Đã triển khai AI lên sản phẩm thực tế (API, hệ thống backend, dịch vụ cloud,...)\n● Có hiểu biết về LLMs, inference optimization (ONNX, quantization, etc.)\n\nQuyền lợi\n●  Mức lương cạnh tranh, thỏa thuận trong quá trình phỏng vấn \n● Làm việc trong môi trường sáng tạo, startup công nghệ, có ứng dụng AI thực tế.\n● Cơ hội tiếp cận mô hình LLM, hệ thống AI mới nhất.\n● Được thử nghiệm và triển khai các ý tưởng AI mới trong các sản phẩm đa dạng.\n● Lương thưởng cạnh tranh, cơ hội tăng trưởng cao theo năng lực.\n● Tham gia team từ giai đoạn đầu, có thể phát triển lên Lead / Architect.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 15, tòa nhà văn phòng Discovery Complex, 302 Cầu Giấy, P.Dịch Vọng Hậu, Cầu Giấy.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2822, 1280, 2, 'Lập Trình Viên Backend', 'Mô tả công việc\n- Xây dựng hệ thống backend cho game thể loại Fantasy và hệ thống Livestreaming.\n- Xây dựng tài liệu thiết kế, tài liệu kiến trúc của sản phẩm.\n- Đề xuất các giải pháp công nghệ, công cụ áp dụng trong phát triển sản phẩm.\n- Phối hợp cùng các thành viên trong nhóm trong quy trình phân tích thiết kế, review code và support các member khác.\n- Phân tích yêu cầu dự án, lên kế hoạch phát triển sản phẩm.\n- Nghiên cứu và ứng dụng các công nghệ, công cụ mới, đặc biệt là các công cụ hỗ trợ phát triển bằng AI, để tối ưu hóa quy trình làm việc và nâng cao chất lượng sản phẩm.\n- Báo cáo tiến độ công việc cho PO/PM.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT.\n- Có ít nhất 3 năm kinh nghiệm làm việc với Javascript/Typescript hoặc Python.\n- Nắm vững các kiến thức về Network, giao tiếp giữa Client và Server.\n- Hiểu biết sâu về tích hợp API, GraphQL, WebSocket và cách ứng dụng nó trong các ứng dụng real time.\n- Thành thạo cấu trúc dữ liệu và cơ sở dữ liệu: MySQL/MongoDB/PostgreSQL.\n- Kinh nghiệm trong việc phân tích yêu cầu và đưa ra giải pháp kỹ thuật.\n- Có khả năng thực hiện code review và đảm bảo chất lượng phần mềm (QA/QC).\n- Kỹ năng phối hợp làm việc với BA, Tester, PM/PO, QA và Khách Hàng.\n- Ðã từng thiết kế hoặc tham gia thiết kế ứng dụng/sản phẩm CNTT.\n- Có kiến thức về bảo mật phần mềm và tối ưu hóa hiệu suất ứng dụng.\n- Có tinh thần lãnh đạo bản thân (trách nhiệm, trung thực, học hỏi liên tục).\n- Ưu tiên ứng viên có kiến thức về Microservices, Docker, K8s, DevOps, GitOps.\n\nQuyền lợi\n- Mức lương thương lượng theo kinh nghiệm, lên đến 45,000,000 VND Gross/tháng.\n- Các chế độ khác theo đúng quy định pháp luật.\n- Xét tăng lương hàng năm\n- 12 ngày phép/ năm và các ngày nghỉ lễ theo quy định\n- Cơ hội tham gia dự án tiềm năng với khả năng phát triển lâu dài.\n- Môi trường làm việc linh hoạt, hỗ trợ học hỏi và tiếp cận công nghệ hiện đại.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 15, tòa nhà văn phòng Discovery Complex, 302 Cầu Giấy, P.Quan Hoa, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2823, 1243, 2, 'Middle Fullstack Developer', 'Mô tả công việc:\n- Phát triển và bảo trì các ứng dụng web sử dụng PHP (ưu tiên Laravel).\n- Thiết kế và xây dựng APIs, tích hợp frontend-backend.\n- Viết code sạch, có thể mở rộng và dễ bảo trì.\n- Tham gia code review, kiểm thử, triển khai và cải tiến hiệu năng hệ thống.\n- Làm việc cùng team để phân tích yêu cầu và đưa ra giải pháp kỹ thuật phù hợp.\n- (Nếu có thể) hỗ trợ xử lý các module sử dụng Ruby on Rails/Java/.Net.\n\nYêu cầu ứng viên:\n- Tối thiểu 4 năm kinh nghiệm phát triển web ở vị trí Fullstack.\n- Thành thạo PHP, đặc biệt là các framework phổ biến như Laravel.\n- Có kinh nghiệm với HTML, CSS, JavaScript (ưu tiên có kinh nghiệm với Vue.js hoặc React).\n- Biết sử dụng MySQL, PostgreSQL hoặc các hệ quản trị cơ sở dữ liệu tương tự.\n- Đã làm việc với Ruby on Rails/Java/.Net là một lợi thế.\n- Có kinh nghiệm sử dụng Git, làm việc nhóm theo mô hình Agile/Scrum.\n- Có tinh thần học hỏi, chủ động và khả năng làm việc độc lập tốt.\n- Có kinh nghiệm tận dụng các tools AI hỗ trợ công việc.\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh.\n\nƯu tiên thêm nếu có:\n- Đã làm việc với Docker, CI/CD, hoặc các dịch vụ cloud (AWS, GCP…).\n- Biết tiếng Nhật là một điểm cộng.\n\nQuyền lợi:\n- Up to 15 tháng lương/năm khi tham gia dự án.\n- Hỗ trợ cơm ca 500,000/tháng cho nhân viên chính thức.\n- Thưởng thâm niên cho nhân viên có từ 03 năm và 06 năm làm việc liên tục tại Rikai.\n- Chế độ thưởng lễ, Tết, sinh nhật, báo hỷ... cho từng cá nhân.\n- Bảo hiểm sức khoẻ cao cấp cho nhân viên chính thức làm việc từ 06 tháng.\n- Chính sách rèn luyện thể thao cho CBNV.\n- Team building theo quý - Company trip mỗi năm.\n- Happy Hour mỗi tháng với nhiều phần quà hấp dẫn.\n\nĐịa điểm làm việc:\n- Đà Nẵng: Tòa nhà Thành Lợi, số 3 Lê Đình Lý, Thanh Khê.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2824, 209, 2, 'SAP BTP CAP Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\nRESPONSIBILITIES\n• Design, develop, and support application solutions focusing on SAP BTP Development.\n• Design and develop data models, queries, and custom services.\n• Develop applications using SAP Cloud Application Programming Model (CAP) on SAP BTP (Node.js/Java).\n• Develop Fiori Elements / SAPUI5 applications integrated with backend services.\n• Develop custom extensions for S/4HANA or other SAP solutions on BTP.\n• Implement and manage application security (roles, authentication, authorization) using XSUAA.\n• Perform debugging and troubleshooting of applications (Logs / Traces).\n• Work with business users to identify process improvement opportunities.\n• Collaborate with team members to perform code reviews and ensure coding best practices.\n\nYêu cầu ứng viên\nRequired Skills:\n• Experience in developing full-stack apps using SAP Business Application Studio (BAS) or Visual Studio Code.\n• Strong experience in SAP CAP Model using Node.js/Java.\n• Experience in Core Data Services (CDS) modeling and consumption.\n• Experience in developing Fiori Elements / SAPUI5 apps (OData V2 & V4).\n• Familiarity with SAP BTP services (App Router, Destination, XSUAA, Cloud Foundry environment).\n• Experience with Multi-Target Application (MTA) deployment on Cloud Foundry.\n• Experience working with SQL Script, designing tables, and managing data loads on HANA Cloud.\n• Basic understanding of Cloud Foundry & DB Security concepts (Roles, Privileges).\n• English communication is required.\n\nPreferred Skills:\n• Knowledge of SAP S/4HANA and SAP API (OData, REST APIs).\n• Experience with CI/CD pipelines on SAP BTP.\n• Familiarity with SAP Event Mesh, SAP Workflow Management is a plus.\n• Experience in code review and mentoring junior developers is a plus.\n• Experience integrating third-party services via SAP Integration Suite is a plus.\n\nQuyền lợi\n• Be part of our hugely international environment; we are currently working for Global projects, where you can have many opportunities to working overseas.\n• Attractive Salary Package based on your competence plus Annual Bonus and Project Performance Bonus.\n• Annual Summer Vacation support from 700 hundred VND to 4 Million VND and up to 3 days off work.\n• 13th-month Salary.\n• Salary review according to Company Policy.\n• Annual leave according to Labor Law and Company Policy.\n• “FPT care” health insurance provided by Petrolimex (PJICO) and is exclusive for FPT employees: 57M – 160M.\n• 20% discount on school fee if your sons/daughters join FPT School.\n• Excellent cost-free learning opportunities: Udemy/ELSA PRO accounts for every employee & Udacity accounts for Managers, English/Japanese/Korean classes, sponsorship for taking certification such as PMP, AWS, etc.\n• International, professional, dynamic and friendly working environment and culture.\n• Be part of a team in an international world-class company and exchange knowledge with technology specialists and experts from the world’s leading companies.\n• Frequent staff activities and company parties;\n• Awesome social events and parties for employees.\n• Etc.\n\nSpecial offer for senior level:\n• Relocating package: Up to 100M (for senior candidates from Hanoi/HCM.C to Da Nang City).\n• Loan support: 4% interest rate (1 – 2 Billion VND package).\n\nĐịa điểm làm việc\n- Đà Nẵng: Tòa Nhà FPT Complex, Ðường Nam Kỳ Khởi Nghĩa, Phường Hoà Hải TP.Ðà Nẵng, Ngũ Hành Sơn\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2825, 1386, 2, 'Backend Engineer (Python/Golang)', 'MỤC ĐÍCH CỦA VỊ TRÍ NÀY:\nTham gia thiết kế, xây dựng và triển khai các hệ thống back-end cho nền tảng Vinbase\nTham gia thiết kế, xây dựng và bàn giao các dự án phát triển Trợ lý ảo triển khai trên nền tảng Vinbase\n\nTRÁCH NHIỆM CỦA VỊ TRÍ NÀY:\nThiết kế giải pháp và triển khai các hệ thống, sản phẩm AI, Machine learning có khả năng co giãn, luôn luôn sẵn sàng và có khả năng chịu lỗi.\nPhát triển sản phẩm phần mềm có khả năng tích hợp hiệu quả và an toàn đến các nền tảng và đối tác bên thứ 3.\nTham gia và tuân thủ các quy trình phát triển phần mềm linh hoạt, thực hành DevOps, CICD để phát triển và triển khai phần mềm với tốc độ cao nhất.\nHướng dẫn các thành viên ít kinh nghiệm hơn, chủ động đóng góp và thực hiện các ý tưởng để cải thiện chất lượng sản phẩm, hiệu suất làm việc của nhóm và môi trường làm việc trong công ty.\nCác công việc khác theo phân công của cấp trên\n\nYÊU CẦU ỨNG VIÊN:\nHỌC VẤN:\nTốt nghiệp Đại học trở lên trong chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc tương đương\nXếp loại bằng từ Khá trở lên\n\nKINH NGHIỆM\nTrên 2 năm làm việc trong lĩnh vực phát triển phần mềm\nTrên 1 năm kinh nghiệm thiết kế và phát triển các hệ thống back-end sử dụng kiến trúc Microservice sử dụng Python/Golang\nCó kinh nghiệm làm việc với các loại cơ sở dữ liệu quan hệ và NoSQL\nCó kinh nghiệm viết kiểm thử tự động, có kinh nghiệm sử dụng Jenkins, CICD, Docker, Kubenetes, có kinh nghiệm sử dụng các phương pháp caching, queue, pubsub\nNắm được kiến thức cơ bản về cấu trúc dữ liệu, thiết kế hướng đối tượng, design pattern\nCó kinh nghiệm làm việc sâu về hệ thống, dữ liệu và thuật toán\nCó hiểu biết về các giao thức kết nối, API như RESTful, Websocket, GRP\n\nNĂNG LỰC CHUYÊN MÔN:\nThành thạo 1 trong các  ngôn ngữ lập trình Python/Golang\nThiết kế, tối ưu và quản lý dữ liệu bằng các hệ quản trị như MySQL, PostgreSQL hoặc MongoDB\nXây dựng kiến trúc phần mềm vững chắc, đảm bảo hiệu suất, khả năng mở rộng và tính ổn định của hệ thống.\nÁp dụng các nguyên tắc OOP (Object-Oriented Programming) để xây dựng mã nguồn sạch, dễ mở rộng và bảo trì, tối ưu hóa cấu trúc hệ thống phần mềm.\n\nYÊU CẦU KHÁC:\nKỹ năng mềm: Tư duy giải quyết vấn đề, Khả năng làm việc nhóm, Khả năng truyền đạt giao tiếp\nKỹ năng máy tính: Sử dụng tốt Linux, Windows, MacOS, Word, Excel\nNgoại ngữ: Tiếng Anh khá\n\nĐIỂM CỘNG/ƯU TIÊN ỨNG VIÊN:\nCó kinh nghiệm làm việc với các nền tảng cloud như AWS, Azure hay GCP\nCó hiểu biết về các nền tảng và công nghệ học máy như TensorFlow hay PyTorch\n\nPHÚC LỢI:\nĐược hưởng đầy đủ các chế độ bảo hiểm theo quy định của Luật Lao động (BHXH, BHYT, BHTN) và được Công ty mua Bảo hiểm sức khỏe cá nhân theo cấp bậc vị trí, khám sức khỏe định kỳ tại Bệnh viện và Trung tâm khám sức khỏe uy tín trên toàn quốc.\nĐược hưởng chế độ ưu đãi khi sử dụng các dịch vụ như: Ưu đãi học phí (Vinschool), khám chữa bệnh (Vinmec), nghỉ dưỡng (Vinpearl), mua xe (VinFast), … theo chế độ của Tập đoàn.\n12 ngày nghỉ phép năm, nghỉ các ngày lễ, Tết theo quy định của pháp luật.\nĐược cấp máy tính xách tay, trang thiết bị làm việc khác phù hợp với yêu cầu công việc.\nPhụ cấp ăn trưa hàng tháng.\nCanteen rộng rãi, trang bị đầy đủ các thiết bị cần thiết như máy pha cà phê, tủ lạnh, lò vi sóng, các loại trà và cà phê hạt được bổ sung hàng ngày.\nChương trình chăm sóc sức khỏe tinh thần cho CBNV.\nTham gia các hoạt động nội bộ, hoạt động teambuilding, du lịch hàng năm của công ty. \n\nCƠ HỘI PHÁT TRIỂN:\nCơ hội làm việc trong môi trường chuyên nghiệp, công nghệ dẫn đầu về AI,  quy tụ hơn 100 nhà khoa học, chuyên gia, kỹ sư đến từ các trường đại học hàng đầu thế giới và Việt Nam như: ĐH Yale (Mỹ), ĐH Johns Hopkins (Mỹ), ĐH Illinois (Mỹ), ĐH Toulouse (Pháp), ĐH Cambridge (Anh Quốc), Đại học Bách Khoa, Đại học Công nghệ – Đại học Quốc gia, …\nĐược xây dựng kế hoạch phát triển cá nhân\nĐược tài trợ các khóa học miễn phí trên Coursera, tham gia các khóa học chuyên môn, kỹ năng mềm, quản lý,… phù hợp với yêu cầu công việc và nhu cầu phát triển của mỗi cá nhân.\nĐược hỗ trợ một phần chi phí thi các chứng chỉ chuyên môn phục vụ công việc.\n\nMÔI TRƯỜNG LÀM VIỆC: \nVăn phòng hiện đại, tiện nghi, trẻ trung và chuyên nghiệp.\nTham gia không giới hạn các câu lạc bộ: cộng đồng đọc sách, CLB cầu lông, bóng bàn, bóng đá (công ty hỗ trợ một phần chi phí cho các hoạt động của CLB).\nMôi trường làm việc cởi mở, khuyến khích CBNV đóng góp ý kiến, sáng kiến, ý tưởng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2826, 1134, 2, 'Frontend Developer', 'Mô tả công việc\n- Phát triển ứng dụng tài chính trên nền tảng Web/Mobile.\n- Nghiên cứu các xu hướng công nghệ và kỹ thuật mới, đặc biệt là trong ngành công nghệ tài chính.\n- Phối hợp chặt chẽ với các chức năng khác để điều tra các vấn đề và sửa lỗi.\n- Cộng tác với các thành viên khác để thu thập yêu cầu và phát triển các tính năng mới.\n- Đảm bảo chất lượng mã nguồn và nâng cao hiệu suất ứng dụng.\n- Tối ưu hoá mã nguồn, đánh giá mã nguồn và kiểm tra đơn vị theo chỉ dẫn của quản lý dự án.\n\nYêu cầu ứng viên\n1. Trình độ học vấn: Tốt nghiệp Cao đẳng trở lên, chuyên ngành Khoa học máy tính, Công nghệ thông tin, Toán – Tin học.\n2. Kinh nghiệm:\n- Có ít nhất 3 năm kinh nghiệm làm việc trong lĩnh vực phần mềm.\n- Có kinh nghiệm trong ngành Tài chính tiêu dùng, Bảo hiểm, Ngân hàng là lợi thế.\n- Có kinh nghiệm phát triển ứng dụng Mobile (Cross-Platform) là lợi thế.\n\n3. Kỹ năng:\n- Sử dụng thành thạo các công nghệ/công cụ: TypeScript/JavaScript, ES6, Redux, ReactJS, Redux, Redux-Saga, Hooks.\n- Có kiến thức về cấu trúc dữ liệu & thuật toán, OOP, quản lý bộ nhớ, mẫu thiết kế, SOLID.\n- Sử dụng thành thạo công cụ kiểm thử: CucumberJS., Jest/Mocha/Chai/Selenium.\n- Am hiểu phương pháp Agile (làm việc trong Scrum) sử dụng Jira/Gitlab/Trello.\n- Lợi thế: Flutter.\n\nQuyền lợi\n- Thử việc 100% mức lương;\n- Ký Hợp đồng Lao động chính thức;\n- Chế độ Bảo hiểm xã hội, Bảo hiểm thất nghiệp, Bảo hiểm y tế theo quy định Nhà nước sau 2 tháng thử việc;\n- Bảo hiểm tai nạn 24/24;\n- Khám sức khỏe định kỳ;\n- Được tham gia khóa đào tạo chuyên môn;\n- 16 ngày phép/năm;\n- Lương tháng 13, thưởng và phụ cấp tùy theo từng vị trí.\n\nĐịa điểm làm việc\n- Hồ Chí Minh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2827, 1474, 2, 'Giám Đốc Bảo Dưỡng', '-Chịu trách nhiệm quản lý các thiết bị của hệ thống điện (cao áp, hạ áp), hệ thống điều khiển (thiết bị điều khiển, phần mềm điều khiển); Hệ thống khí nén; hệ thống cầu trục điện; hệ thống chiếu sáng toàn Nhà máy.\n-Chịu trách nhiệm quản lý về mặt kỹ thuật điện và cơ khí của các thiết bị trên các dây chuyền sản xuất.\n-Chịu trách nhiệm quản lý dụng cụ, công cụ được nhà máy giao cho thuộc Phân xưởng điện và phân xưởng cơ khí. Chịu trách nhiệm quản lý các vật tư tiêu hao phục vụ cho công tác sửa chứa và bảo dưỡng.\n-Thiết lập và quản lý danh mục các máy móc thiết bị và lịch bảo trì cho toàn bộ các thiết bị máy móc trong nhà máy\n-Kiểm tra, giám sát chặt chẽ các hoạt động của phân xưởng cơ điện nhằm đảm bảo đạt các KPI của bộ phận bảo trì\n-Đảm bảo các thiết bị luôn trong điều kiện sẵn sàng hoạt động và duy trì hiệu suất cao\n-Đảm bảo các Máy móc thiết bị trong hệ thống phải thực hiện theo đúng tiêu chuẩn Ban hành\n-Thiết lập chi tiết các kế hoạch bảo trì và dừng máy đảm bảo nhân viên cấp dưới hiểu rõ những công việc cần thực hiện, đảm bảo phân bổ nguồn lực hợp lý\n-Đào tạo nhân viên bảo trì đảm bảo nhân viên đủ năng lực thực hiện công việc một cách hiệu quả nhất và đào tạo nâng cao nhằm phát triển các kỹ năng của nhân viên Bảo trì\n-Đào tạo nguyên lý hoạt động của máy móc thiết bị và các hạng mục cần bảo trì cho bộ phận có liên quan\n-Thực hiện đầy đủ công tác Bảo trì và tối ưu hóa Chi phí, Nguồn lực và Thời gian.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Giang', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2828, 1142, 2, 'Intern/Fresher .NET (Willing To Work With Forguncy)', 'We are looking for passionate and proactive Intern Developers to join our dynamic team. You will participate in real-world projects, receive mentorship from senior developers, and gain hands-on experience with web development technologies.\n\nFamiliar with VB.NET (experience is a big plus).\nWilling to learn and work with Forguncy (we will provide training).\nAble to write and understand JavaScript.\nSolid understanding of Databases: creating databases/tables, writing/editing SQL queries, and optimizing SQL performance.\nBasic knowledge of web development concepts (client-server, HTML/CSS/JS, etc.).\nKnowing Japanese is a plus (not mandatory).\nEagerness to learn, good teamwork, and problem-solving attitude.\n\nWorking in a dynamic and professional environment with many opportunities for advancement.\nThe company provides equipment such as LAPTOP, Phones to serve the working needs of all employees.\nThe company pays all costs of social insurance, health insurance, and unemployment insurance for employees.\nJoin Health and Accident Insurance package 24/7 (according to seniority). Enjoy benefits according to seniority.\nBeing trained in foreign languages, and sponsored to study certificates to improve professional skills and soft skills.\nOpportunity to go Onsite at SPLUS JAPAN (requires Japanese level of N3 or higher)\nPerformance evaluation: 2 times/year\nClubs: Football, Music, ...\nAnnual company trip, quarterly teambuilding, employee birthdays in the month, and special events of the year (8/3, 20/10, Mid-Autumn Festival, Christmas...)\nAnnual leave: 12 vacation days, 11 holidays a year.\nCompany trip, quarterly teambuilding, birthdays for employees in the month and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas ...)\nAnnual holiday: 12 days of annual leave\nTET bonus fund (1-3 months’ salary) according to the results of the work and the business situation of the company.\n\n- Hồ Chí Minh: Tòa nhà HaDo Airport, 2 Hồng Hà, phường 2, Tân Bình\n\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Internship', '2025-10-07 20:59:18.149534'),
	(2829, 1228, 2, 'Business Developer - Project', 'Job Overview\nWe are seeking a dynamic and experienced Business Developer - Northern Project to lead and grow our project sales in the Northern region of Vietnam. The role focuses on residential and hospitality segments, with the responsibility to establish key business relationships, promote the brand, identify new opportunities, and support project execution.\nChúng tôi đang tìm kiếm một ứng viên năng động và giàu kinh nghiệm cho vị trí Nhân viên Kinh doanh Dự án khu vực miền Bắc, tập trung vào phân khúc nhà ở và khách sạn. Ứng viên sẽ chịu trách nhiệm phát triển kinh doanh, xây dựng mối quan hệ chiến lược, quảng bá thương hiệu, tìm kiếm cơ hội mới và phối hợp thực hiện dự án.\n\nKey Responsibilities / Trách nhiệm chính\n- Develop and expand the project sales channels in the Northern region (including residential & hospitality sectors)/Phát triển và mở rộng kênh bán hàng dự án tại khu vực miền Bắc (bao gồm nhà ở và khách sạn).\n- Build strong relationships with developers, construction companies, and industry stakeholders through direct visits/Thiết lập và duy trì mạng lưới quan hệ chặt chẽ với các chủ đầu tư, công ty xây dựng và đối tác trong lĩnh vực dự án thông qua việc gặp gỡ trực tiếp.\n- Promote brand and product portfolio to architects and interior designers/Quảng bá thương hiệu và danh mục sản phẩm đến các kiến trúc sư, nhà thiết kế nội thất.\n- Identify and pursue new project opportunities/Tìm kiếm và phát triển các cơ hội kinh doanh mới.\n- Coordinate with internal departments (sales support, technical, logistics) to ensure smooth project execution/Phối hợp với các bộ phận nội bộ (hỗ trợ kinh doanh, kỹ thuật, logistics) để đảm bảo dự án được triển khai hiệu quả.\n- Develop long-term strategies for project business growth/Xây dựng chiến lược phát triển dài hạn cho kinh doanh dự án.\n- Conduct market research and provide updates on project trends in the residential and hospitality sectors/Nghiên cứu thị trường và cập nhật xu hướng dự án trong lĩnh vực nhà ở và khách sạn ảnh hưởng đến định hướng phát triển của công ty.\n- Prepare weekly and monthly reports to the Head of Hanoi Office/Lập báo cáo hàng tuần/hàng tháng cho Trưởng Văn phòng Hà Nội.\n\nYêu cầu ứng viên\n- University degree (preferably in Architecture, Construction, or Technology)/Tốt nghiệp đại học (ưu tiên chuyên ngành Kiến trúc, Xây dựng hoặc Công nghệ).\n- At least 5 years of experience in project sales or business development/Tối thiểu 5 năm kinh nghiệm trong lĩnh vực kinh doanh dự án hoặc phát triển kinh doanh.\n- Proven track record and existing network with decision-makers in the project business/Có kinh nghiệm và mạng lưới quan hệ với các nhà ra quyết định trong lĩnh vực dự án.\n- Excellent communication and presentation skills in both Vietnamese and English/Kỹ năng giao tiếp và thuyết trình xuất sắc bằng cả tiếng Việt và tiếng Anh.\n- Professional, persuasive, and service-oriented personality/Tác phong chuyên nghiệp, thuyết phục và có tinh thần phục vụ khách hàng.\n- Self-motivated, eager to learn, and proactive in work/Chủ động, cầu tiến và có tinh thần học hỏi.\n- Strong problem-solving and leadership skills are an advantage/Khả năng giải quyết vấn đề và tố chất lãnh đạo là lợi thế.\n- Proficient in Microsoft Office and digital tools/Thành thạo các ứng dụng văn phòng và công cụ kỹ thuật số.\n- Willingness to travel for business/Sẵn sàng đi công tác khi cần thiết.\n- Able to work independently and in team settings/Có khả năng làm việc độc lập cũng như phối hợp nhóm hiệu quả.\n\nThu nhập\n- Thu nhập khi đạt 100% KPI:  Thoả thuận\n- Thu nhập tính theo tỷ lệ đạt KPI\n- Lương cứng:  20 - 30 triệu VND \n- Lương cứng không phụ thuộc doanh số\n\nQuyền lợi\n- 5-day work week (Saturday & Sunday off)/Làm việc 5 ngày/tuần, nghỉ Thứ Bảy & Chủ Nhật.\n- 12 annual leave days/12 ngày nghỉ phép năm theo quy định.\n- 4 paid sick leave days per year/4 ngày nghỉ bệnh nguyên lương mỗi năm.\n- 13th month salary bonus/Lương tháng 13.\n- Full social insurance based on actual salary/Đóng BHXH, BHYT, BHTN trên lương thực tế.\n- MIC personal health insurance package/Gói bảo hiểm sức khỏe cá nhân MIC.\n- After completing 1- year of service, the company will provide an additional MIC personal health insurance package for the employee\'s spouse and children/ Sau khi hoàn thành 1 năm làm việc, công ty sẽ mua thêm gói bảo hiểm sức khỏe cá nhân MIC dành cho vợ/chồng và con của nhân viên.\n- Annual premium health check/ Gói khám sức khỏe định kỳ cao cấp.\n- Annual company trip & monthly team-building activities/Du lịch công ty hằng năm & team building hàng tháng.\n- Training & development opportunities/Cơ hội tham gia các khóa đào tạo chuyên môn và kỹ năng.\n- Annual performance & salary review / Đánh giá hiệu suất và xét tăng lương hàng năm.\n- Professional & friendly work environment/ Môi trường làm việc chuyên nghiệp, thân thiện và gắn kết.\n- Holiday bonuses (New Year, Labor Day, National Day)/Thưởng các dịp lễ lớn: Tết Dương lịch, 1/5, 2/9.\n- Provide phone and transportation support for customer engagement.\nCung cấp điện thoại và phương tiện hỗ trợ cho việc tiếp xúc khách hàng.\n\nĐịa điểm làm việc\n- Hà Nội: Hanoi Rep. office- Trang An complex, No.1 Phùng Chí Kiên, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2830, 1121, 2, 'Lập Trình Viên .Net', '1. Tham gia vào các hoạt động phát triển phần mềm.\n2. Xây dựng các ứng dụng trên nền tảng Web và Net.\n3. Làm việc trong môi trường công ty Nhật Bản.\n\nYêu cầu ứng viên\n1) Có kinh nghiệm lập trình trên .NET Framework (C#, ASP.NET)\n2) Hiểu các cơ sở dữ liệu MySql , SQL Server.\n3) Hiểu HTML5, CSS3, JavaScript, jQuery ,bootstrap.\n4) Hiểu biết về các mô hình lập trình OOP, MVC, Web API.\n5) Biết tiếng Nhật là 1 lợi thế.\n6) Hoan nghênh các ứng viên nữ gia nhập công ty.\n\nQuyền lợi\n- Thưởng lương tháng 13 hàng năm.\n- Thu nhập thoả đáng theo năng lực.\n- Môi trường làm việc thoải mái, năng động.\n- Thời gian làm việc từ T2-T6 (8h-17h), nghỉ T7 và CN.\n- Hưởng đầy đủ các chế độ BHXH + BHYT + các chế độ phúc lợi khác.\n- Công việc ổn định, lâu dài.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 281 Nguyễn Thiện Thuật, Phường 01, Quận 3\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2831, 1163, 2, 'Middle/Senior IOS Developer', 'Mô tả công việc:\n- Tham gia vào quá trình phân tích, thiết kế và phát triển các tính năng của ứng dụng.\n- Phối hợp với các team liên quan để triển khai và hiện thực hóa các yêu cầu sản phẩm.\n- Đề xuất và nghiên cứu các giải pháp, xu hướng công nghệ mới nhằm nâng cao chất lượng và hiệu suất sản phẩm.\n- Đảm bảo ứng dụng hoạt động ổn định, mượt mà và tối ưu hóa trải nghiệm người dùng.\n\nYêu cầu ứng viên:\n- Tối thiểu từ 3 năm kinh nghiệm trong ngành lập trình cho Apple Devices.\n- Thành thạo ngôn ngữ lập trình Swift và các công nghệ liên quan: Concurrency, GCD, UIKit, SwiftUI.\n- Hiểu rõ mô hình server-client.\n- Có kinh nghiệm làm việc với RESTful. Có hiểu biết về GraphQL là lợi thế.\n- Có kinh nghiệm làm việc với các mô hình kiến trúc phổ biến như MVC, MVVM.\n- Có kinh nghiệm làm sản phẩm đáp ứng các yêu cầu cao về UI/UX, có hiểu biết về UI/UX là lợi thế.\n- Có kinh nghiệm làm việc với SQLite, Realm.\n- Có tư duy logic về data structures, algorithms.\n- Có khả năng debug tốt, nắm bắt vấn đề nhanh, hiểu biết về clean code, SOLID, design pattern là một lợi thế.\n- Có khả năng đọc hiểu nhanh, nắm bắt công nghệ mới là một lợi thế.\n- Đã từng tham gia phát triển ứng dụng đáp ứng lượng user sử dụng lớn là một lợi thế.\n\nQuyền lợi:\n- Mức lương và phúc lợi hấp dẫn:\n  - Mức lương NET upto 35.000.000đ/tháng (Middle) và upto 45.000.000đ/tháng (Senior).\n  - Thử việc nhận 100% lương.\n  - Lương tháng 13, thưởng lễ, Tết, thâm niên.\n  - Review lương hàng năm.\n  - Bảo hiểm y tế, bảo hiểm xã hội, bảo hiểm sức khỏe cá nhân (PTI).\n  - Hỗ trợ ăn trưa 500.000 VND/tháng.\n- Các quyền lợi khác:\n  - Miễn phí gửi xe, snacks & drinks tại văn phòng.\n  - Du lịch công ty, team building, sinh nhật.\n  - Hoạt động Well-being 1 tháng/lần (các hoạt động chăm sóc sức khỏe thể chất và tinh thần).\n  - Happy Lunch vào Trưa thứ 4, Teabreak vào chiều Thứ 3 hoặc chiều Thứ 5 hàng tuần.\n  - Các chế độ khác theo đúng Luật lao động hiện hành.\n\nMôi trường làm việc:\n- Môi trường product trẻ trung năng động, sáng tạo cao.\n- Sản phẩm xây dựng ra cho khách hàng quốc tế 100%, hiện có hơn 1.5 triệu người sử dụng trên toàn cầu.\n\nThời gian làm việc:\n- Chấm công/làm việc linh hoạt từ 08h00 - 09h30, miễn đủ 8 tiếng, đảm bảo hiệu suất và tiến độ công việc.\n- Làm việc từ thứ 2 đến thứ 6 hàng tuần, nghỉ trưa từ 12h00 - 13h30, thứ 4 nghỉ trưa từ 12h00 - 14h00.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2832, 1254, 2, 'Senior Java Developer', 'Với sự tham gia của AI vào việc phát triển phần mềm, công việc của developer sẽ thay đổi rất nhanh trong thời gian ngắn tới đây. Developer không còn phát triển các tính năng theo yêu cầu khách hàng nữa, mà phải có khả năng thiết kế các giải pháp, ứng dụng AI/công cụ và các dịch vụ khác (như DevOps, ITSM, Cloud,…) để deliver được giá trị cho khách hàng.\nĐi cùng với xu hướng này, BiPlus tìm kiếm các thành viên hiểu được sự thay đổi này và mong muốn học hỏi để dẫn dắt và nắm bắt các cơ hội mới.\nYêu cầu cụ thể:\n- Tham gia phân tích yêu cầu khách hàng, xây dựng và tư vấn giải pháp cho khách hàng\n- Triển khai các giải pháp, bao gồm việc phát triển (coding) và triển khai các dịch vụ khác đáp ứng nhu cầu khách hàng.\n- Tham gia các hoạt động chia sẻ tri thức và cải tiến liên tục.\n\nYêu cầu ứng viên:\n- Bạn là developer có từ 4 năm kinh nghiệm lập trình với ngôn ngữ Java.\n- Tiếng Anh giao tiếp thành thạo, tự tin làm việc với cộng sự nước ngoài.\n- Có chứng chỉ hoặc được đào tạo về AI, Cloud, Data, DevOps.\n- Thành thạo các công cụ trong quản lý phát triển phần mềm (Jira, Git,…)\n- Có kinh nghiệm và khả năng thiết kế giải pháp.\n- Có khả năng ứng dụng AI hiệu qủa trong công việc.\n- Có kinh nghiệm về triển khai các dịch vụ về DevOps, ITSM,… là một lợi thế\n- Hiểu biết về Agile/Scrum.\n- Có động lực học và kỹ năng tự học tốt, yêu thích và sẵn sàng học hỏi cái mới.\n- Sẵn sàng làm các mảng công việc mới như tư vấn, triển khai các dịch vụ cho khách hàng thay vì tập trung vào coding.\n\nQuyền lợi:\n- Mức lương khởi điểm: 35 – 50 triệu.\n- Thưởng quý, thưởng cuối năm (1-3 tháng lương).\n- Ngày phép hàng năm, ngày phép thâm niên, ngày phép tháng sinh nhật.\n- Đánh giá năng suất và xét tăng lương 1 lần/năm.\n- Tài trợ 100% phí thi các chứng chỉ quốc tế; phụ cấp chứng chỉ chuyên môn.\n- Được đào tạo, huấn luyện để có thể làm tốt công việc.\n- Khám sức khỏe định kỳ; BHXH, nghỉ lễ theo quy định.\n- Tham gia vào các dự án hiệu năng cao, số lượng dữ liệu lớn và tập khách hàng lớn. Được làm việc trên các hệ thống lớn với các bài toán công nghệ phức tạp.\n- Tham gia vào nhóm phát triển Scrum tự chủ, linh hoạt và năng suất cao theo mô hình Agile/Scrum.\n- Môi trường làm việc trẻ, năng động, vui vẻ, hạnh phúc với các hoạt động văn hóa sôi động như retreat, picnic, team building, happy event, BiPlus radio, …\n- Được làm nhiều, được thử nhiều và được sai, học thực chiến trong công việc.\n- Liên tục phát triển năng lực thông qua các hoạt động học tập (company learning hour, team learning hour, club), đào tạo, mentoring, coaching,…\n- Được phản hồi thường xuyên liên tục và huấn luyện để phát triển năng lực và đạt hiệu suất công việc ngày càng cao (CFRs- Conversation – Feedback – Recognition tháng và 6 tháng).\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa nhà Bảo Anh, Số 85, Trần Thái Tông, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2833, 1334, 2, 'Lập Trình Máy CNC', 'Mô tả công việc\nTiếp nhận các bản vẽ từ bộ phận thiết kế.\nSử dụng phần mềm thực hiện lập trình gia công các chi tiết, đảm bảo phù hợp với các thông số kỹ thuật của máy CNC.\nPhối hợp bộ phận chạy máy theo dõi, kiểm soát quá trình gia công, đảm bảo các chi tiết được gia công đạt chất lượng và tiến độ theo yêu cầu.\n\nYêu cầu ứng viên\nNam từ 25-40 tuổi\nCó kinh nghiệm lập trình ít nhất 6 tháng (ưu tiên đã làm về mảng khuôn mẫu)\nThành thạo phần mềm: NX, Mastercam, Cimatron\nChăm chỉ, chịu khó, ham học hỏi, sức khỏe tốt, có trách nhiệm trong công việc.\n\nQuyền lợi\nLương khởi điểm: 10.000.000 – 15.000.000 đồng/ tháng (thỏa thuận khi PV)\nPhụ cấp: ăn ca tại công ty.\nĐược đóng đầy đủ các loại BHXH, BHYT, BHTN, … theo Luật lao động.\nThưởng tháng lương thứ 13, thưởng thâm niên, thưởng các ngày Lễ, Tết, trung thu, sinh nhật, gia đình vợ con ốm đau, hiếu hỷ, trả phép bằng tiền...\n\nĐịa điểm làm việc\n- Hà Nội: Số 12 ngõ 253 Thúy Lĩnh, Lĩnh Nam, Hoàng Mai\n\nThời gian làm việc\nThứ 2 - Chủ nhật (từ 08:00 đến 17:00)\nThứ 3 - Thứ 7 (từ 13:00 đến 22:20)\nCa 1: 8h00- 17h20; Ca 2: 13h00-22h20\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2834, 186, 2, 'Lập Trình Viên Server. Thu Nhập Upto 40M', 'Mô tả công việc\nThiết kế và triển khai các hệ thống phía máy chủ hiệu năng cao bằng ngôn ngữ C trên môi trường Unix/Linux, áp dụng cụ thể cho nền tảng Kiwoom.\n• Tích hợp CSDL & Giao tiếp liên tiến trình:\nSử dụng CISAM, giao tiếp liên tiến trình (IPC) và bộ nhớ dùng chung (Shared Memory) để xử lý dữ liệu hiệu quả và điều phối tiến trình mượt mà.\n• Hợp tác với các nhóm từ xa:\nLàm việc chặt chẽ với các nhóm làm việc từ xa để làm rõ yêu cầu, thống nhất nhiệm vụ phát triển và đảm bảo truyền đạt thông tin hiệu quả giữa các nhóm.\n• Phân tích yêu cầu & thiết kế tính năng:\nTham gia phân tích yêu cầu người dùng và thiết kế kiến trúc hệ thống, đóng góp vào việc phát triển các tính năng mới.\n• Xử lý lỗi và sự cố:\nPhân tích và khắc phục lỗi trong quá trình kiểm thử tích hợp, kiểm thử chấp nhận người dùng (UAT) và kiểm thử bảo trì, đảm bảo độ ổn định và hiệu suất hệ thống.\n• Quản lý dự án:\nQuản lý thời gian và nguồn lực hiệu quả dựa trên Cấu trúc phân rã công việc (WBS) để đảm bảo tiến độ và chất lượng dự án.\n\nYêu cầu ứng viên\n• Bắt buộc ứng viên sử dụng được : .NET (C#)\n• Bắt buộc có kinh nghiệm sử dụng công cụ Git, và có hiểu biết về CI/CD\n• Kinh nghiệm: từ 5 năm trở lên\n• Yêu cầu: Có portfolio, đính kèm mã nguồn (code)\n• Trong quá trình phỏng vấn:\n    + Có thể có bài thi tự luận về Design Pattern\n+ Kèm bài kiểm tra lập trình (coding test) ( nhằm đánh giá cả tư duy lập trình lẫn khả năng thiết kế phần mềm.)\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận. Mức lương cao, có thể thoả thuận theo năng lực của ứng viên\n• 1 năm tăng lương/lần\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước)\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm , Tiêm phòng HPV, cúm,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2835, 485, 2, 'Frontend Developer (ReactJS/NextJS)', 'Mô tả công việc:\n- Xây dựng, phát triển và tối ưu giao diện người dùng (ưu tiên ứng viên mạnh ReactJS, NextJS).\n- Thiết kế và phát triển hệ thống base frontend, xây dựng thư viện component và module có khả năng tái sử dụng.\n- Phát triển các tính năng như đăng nhập, đăng ký, quản lý tài khoản, trình phát video, quản lý thông tin, tích hợp thanh toán online (momo, vnpay),.. \n- Phối hợp chặt chẽ với backend team để tích hợp API, đảm bảo tính đồng bộ và ổn định cho hệ thống.\n- Debug, khắc phục lỗi, tối ưu hiệu năng và đảm bảo chất lượng thông qua kiểm thử kỹ lưỡng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc liên quan.\n- Có kinh nghiệm phát triển frontend từ 3 năm trở lên (ReactJS và NextJS).\n- Thành thạo:\n+ ƯU TIÊN CÓ THỂ ĐI LÀM NGAY SAU KHI NHẬN ĐƯỢC OFFER.\n+ ReactJS: Hooks, React Hook Form + Yup, Redux/Zustand/Context API/React Query, React-dnd (drag-drop), Axios/fetch, TailwindCSS, upload file, xử lý JWT...\n+ NextJS: App Router hoặc SSR/SSG (getServerSideProps), dynamic routing, middleware auth, lazy loading, Next Image, SEO tối ưu.\n+ JavaScript/TypeScript (ES6+), HTML5, CSS3.\n+ Xây dựng giao diện responsive.\n- Có khả năng thiết kế và xây dựng các components/modules có thể tái sử dụng chất lượng cao.\n- Có khả năng làm việc độc lập, xây dựng được nền tảng base cho website, tối ưu hiệu năng.\n- Có khả năng tự chủ động cập nhật công nghệ mới nhanh và có trách nhiệm cao.\n- Có kinh nghiệm với Video.js, HLS.js hoặc công nghệ trình phát video tương tự.\n- Biết về WebRTC, CDN tối ưu hóa streaming video.\n- Hiểu biết về bảo mật frontend và tối ưu hiệu năng.\n- Kinh nghiệm xây dựng dashboard/admin panel.\n\nQuyền lợi:\n- Lương 16-22 triệu.\n- Thưởng tháng 13, theo kết quả kinh doanh.\n- 14 ngày nghỉ phép 1 năm (sinh nhật, lễ giáng sinh).\n- Bảo hiểm xã hội, sinh nhật, hiếu hỉ, quà tặng lễ tết.\n- Làm việc linh hoạt giờ giấc.\n- Trà chiều mỗi ngày.\n- Review lương định kỳ 2 lần/năm (tùy theo năng lực).\n- Môi trường làm việc năng động.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 37 Cao Lỗ Phường 4, Quận 8\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Toàn thời gian nhưng linh động và thoải mái.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2836, 1265, 2, 'Nhân Viên React Native Mobile', '- Tham gia phát triển các dự án phần mềm, ứng dụng trên nền tảng Mobile cho nền tảng Logistics thế hệ mới của ViettelPost (Monthly active user 800k).\n- Phối hợp làm việc với team sản phẩm, UI/UX và Backend để thiết kế, xây dựng và mở rộng các ứng dụng mobile\n- Xây dựng các components có khả năng tái sử dụng cho Mobile trên nên tảng React Native/iOS/Android\n- Giám sát và theo dõi hiệu năng cho cả code và ứng dụng\n- Đánh giá, nắm bắt các kĩ năng và xu hướng công nghệ mới, áp dụng để cải thiện phần mềm.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học trở lên chuyên ngành CNTT hoặc tương đương. Ưu tiên ứng viên tốt nghiệp các trường đại học Bách Khoa, ĐH Công nghệ - ĐH Quốc Gia, Học viện Bưu chính viễn thông, Học viện kỹ thuật quân sự.\n- Có tối thiểu 2 năm kinh nghiệm làm việc với React Native\n- Nắm vững kiến thức và kĩ năng trong Javascript, HTML, CSS, ES6, ES7, Restful API\n- Có kinh nghiệm sử dụng các kĩ thuật tối ưu Frontend\n- Có kinh nghiệm làm việc theo quy trình Agile – Scrum\n- Ứng viên có kinh nghiệm từng làm việc với Flutter là một điểm cộng.\n\nQuyền lợi\nTại Tổng Công ty cổ phần Bưu chính Viettel, các ứng viên sẽ được làm việc trong môi trường năng động, trẻ trung và chuyên nghiệp, với các đãi ngộ hấp dẫn sau:\n1. Chế độ về lương thưởng, thu nhập\n• Mức lương 15M - 20M đối với Junior, 20M - 35M đối với Senior. 35M++ đối với Leader.\n• Có chế độ hỗ trợ tiền điện thoại và ăn trưa, nghỉ mát hàng năm; kèm theo là các khoản thưởng vào các dịp lễ lớn (30/4, 1/5, 2/9, ngày thành lập Tập đoàn, Tổng Công ty, Tết Dương/ Âm)\n2. Chương trình chăm sóc sức khỏe\n• Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và các gói bảo hiểm sức khỏe khác.\n• Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n• Phụ nữ có con nhỏ dưới 1 tuổi sẽ được nghỉ thêm 1h/ngày\n3. Đào tạo, phát triển\n• Hàng tuần, công ty tổ chức buổi Seminar trao đổi, chia sẻ về các công nghệ mới nhất; là cơ hội để các thành viên học hỏi lẫn nhau.\n• Được tham gia các khóa học bổ ích từ các diễn giả Quốc tế tại Học viện Viettel\n• Có cơ hội thăng tiến trong nghề nghiệp.\n4. Hoạt động tập thể hấp dẫn, phong phú\n• Tham gia vào hoạt động ‘Happy Time” vào chiều thứ 6 hàng tuần cùng với chương trình sinh nhật tháng.\n• Chương trình teambuilding, văn hóa, du lịch nghỉ mát hấp dẫn và đa dạng.\n• Các hoạt động thể dục thể thao cùng các giải đấu được Tập đoàn tổ chức.\n\nĐịa điểm làm việc\n- Hà Nội: Số 2, Ngõ 15, Duy Tân, Dịch Vọng Hậu, Cầu Giấy.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2837, 220, 2, 'Chuyên Viên Phát Triển Phần Mềm', 'Mô tả công việc\n- Tham gia phân tích, thiết kế, phát triển và bảo trì các hệ thống phần mềm phục vụ lĩnh vực y tế như: HIS, LIS, RIS, EMR/EHR, Quản lý bệnh viện,...;\n- Tích hợp với các hệ thống phụ trợ và các bên thứ 3;\n- Tối ưu hiệu năng, bảo mật và độ tin cậy của hệ thống phần mềm;\n- Vá lỗi, xây dựng và nâng cấp các module theo yêu cầu nghiệp vụ;\n- Cập nhật các công nghệ mới phục vụ cho việc cải tiến phần mềm và đáp ứng các yêu cầu quản lý Y tế số;\n- Thực hiện các công việc khác theo phân công của Quản lý trực tiếp.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học, cao đẳng chuyên ngành công nghệ thông tin;\n- Yêu cầu có 06 tháng kinh nghiệm trở lên;\n- Có kinh nghiệm làm việc với cơ sở dữ liệu PostgreSQL, SQL Server, MySQL, C#, HTML, CSS, Angular...;\n- Có khả năng tự học, nghiên cứu, kỹ năng làm việc nhóm và giải quyết vấn đề tốt;\n- Chủ động trong công việc, giải quyết vấn đề nhanh, chịu được áp lực công việc.\n- Sẵn sàng đi công tác theo yêu cầu của cấp trên.\n\nQuyền lợi\n- Lương net: Thỏa thuận theo năng lực;\n- Công ty đóng Bảo hiểm xã hội theo quy định;\n- Môi trường làm việc thân thiện, chuyên nghiệp, cơ hội thăng tiến cao;\n- Chế độ bảo hiểm, phúc lợi đầy đủ theo quy định của công ty;\n- Được tham gia vào các dự án, cập nhật công nghệ mới nhất;\n- Được hỗ trợ đào tạo nghiệp vụ và hướng dẫn quy trình vận hành thực tế cùng đội ngũ chuyên gia trong các lĩnh vực: Y tế;\n- Các chế độ theo Luật Lao động hiện hành và các phúc lợi theo quy định của Công ty.\n\nĐịa điểm làm việc\n- Hà Nội: Số 117 Xuân Thủy, Dịch Vọng Hậu, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2838, 1164, 2, 'Frontend Developer', 'The Front-End Developer is responsible to write software applications from design specifications; Plans, executes and documents unit tests; Reports status and issues; Documents detailed designs; Accountable for unit test leakage; Contributes to system architecture and design decisions. Develop and maintain websites and real-time front-end systems across multiple platforms: PC, Mobile, Tablet. Optimize website performance, ensure standardization and SEO best practices, and help build the company\'s brand image. Convert UI/UX design files (PSD, Figma, XD, etc.) into responsive and modern HTML/CSS interfaces. Write clean, well-documented, and tested JavaScript/TypeScript, HTML, and CSS code. Integrate with RESTful APIs and collaborate closely with UI/UX designers, backend developers, and team members. Ensure cross-browser and cross-device compatibility for all front-end features. Participate in improving workflows and sharing knowledge with the team. Requirements: Bachelor’s degree in Computer Science, Software Engineering, or related field. Have at least 5 years of experience in a Front-end Developer. Proficient in HTML5, CSS3, JavaScript (TypeScript is a plus). Solid understanding of at least one modern front-end framework: ReactJS (with Redux), VueJS (with Vuex), or AngularJS (with NgRx, Akita, etc.). Proficient in using state management tools (e.g., Redux for React, Vuex for Vue, NgRx for Angular) to handle complex application state. Good grasp of OOP and basic Design Patterns. Experience handling cross-browser compatibility issues. Familiar with RESTful APIs and integrating data from backend services. Experience with Git and modern build tools (Webpack, Babel, etc.) is a plus. Knowledge of task management tools (Jira, Trello, Asana, etc.) is a plus. Creative thinker with strong problem-solving skills and a proactive, responsible attitude. Able to work independently and as part of a team. Good reading and writing skills in English. Benefits: The attractive salary (Negotiation). 2-month probation period with 100% salary. Full salary insurance coverage after the probation period. Participation in the PVI health insurance package, and annual health check-ups. 13th-month salary, birthday bonus, New Year bonus, Mid-Autumn Festival gifts, March 8th and October 20th gifts, etc. Performance evaluation and regular salary increases. Welfare for personal events, childbirth, and other benefits as per labor regulations and company welfare policies. Dynamic and youthful work environment conducive to personal growth and development.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2839, 1191, 2, 'Backend Developer', 'Mô tả công việc:\n- Phát triển, bảo trì và tối ưu hệ thống backend sử dụng Node.js và PHP (tùy dự án).\n- Thiết kế, phát triển và bảo trì hệ thống backend cho các ứng dụng web.\n- Xây dựng và tối ưu RESTful API / GraphQL để kết nối với frontend và các dịch vụ khác.\n- Làm việc với cơ sở dữ liệu (SQL / NoSQL) để lưu trữ, truy xuất và xử lý dữ liệu hiệu quả.\n- Tối ưu hóa hiệu suất và bảo mật của hệ thống backend.\n- Phối hợp chặt chẽ với frontend, QA, UI/UX, DevOps để đảm bảo chất lượng sản phẩm.\n- Tham gia phân tích yêu cầu, thiết kế kiến trúc hệ thống và đánh giá giải pháp kỹ thuật.\n- Viết tài liệu kỹ thuật, unit test và tham gia review code.\n\nYêu cầu ứng viên:\nBắt buộc:\n- GHI RÕ ĐỊA ĐIỂM MONG MUÔN LÀM VIỆC TRÊN CV ỨNG TUYỂN\n- Có kinh nghiệm phát triển backend với một trong các ngôn ngữ: Node.js (Express.js/NestJS) và/hoặc PHP (Laravel/Lumen/Symfony), Python, Go, ...\n- Thành thạo xử lý API, phân quyền, xác thực (JWT, OAuth2,...).\n- Làm việc tốt với cơ sở dữ liệu quan hệ (MySQL) và/hoặc NoSQL (MongoDB).\n- Có tư duy OOP, MVC, hiểu nguyên lý thiết kế phần mềm (SOLID, DRY,...).\n- Hiểu biết về bảo mật backend: SQL Injection, XSS, CSRF,...\n- Biết sử dụng Git, Docker, và công cụ quản lý mã nguồn.\n\nƯu tiên (không bắt buộc):\n- Đã làm việc với các framework như Express.js, Django, Spring Boot, Laravel,...\n- Có kiến thức về authentication (JWT, OAuth2), bảo mật web (OWASP, CSRF, XSS,...) và tối ưu hiệu suất backend.\n- Kinh nghiệm với message queue (RabbitMQ, Kafka), caching (Redis, Memcached).\n- Biết triển khai CI/CD hoặc từng làm việc với các nền tảng cloud (AWS, GCP, Azure).\n\nTrình độ:\n- Tốt nghiệp Đại học/Cao đẳng ngành CNTT, Khoa học máy tính hoặc tương đương.\n- Hoặc có kinh nghiệm thực tế qua dự án cá nhân hoặc freelance.\n\nQuyền lợi:\n- Thu nhập: 15 triệu – 25 triệu/tháng.\n- Đóng đầy đủ BHXH theo quy định của pháp luật.\n- Thưởng các ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch,...).\n- Nghỉ Lễ/Tết, 12 ngày phép/năm và nghỉ phép theo Quy định của Pháp luật hiện hành.\n- Các chế độ phúc lợi khác theo quy định của Công ty.\n- Cung cấp thiết bị làm việc.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp trẻ trung, năng động, tích cực.\n- Được lựa chọn địa điểm làm việc:\n  Địa điểm 1: V1- A02 Khu đô thị mới An Hưng, Dương Nội, Hà Đông, Hà Nội\n  Địa điểm 2: TechnoPark Tower, xã Đa Tốn, Gia Lâm, Hà Nội (ưu tiên làm việc tại đây).\n\nĐịa điểm làm việc:\n- Hà Nội: V1- A02 Khu đô thị mới An Hưng, Dương Nội, Hà Đông.\n- Hà Nội: TechnoPark Tower, xã Đa Tốn, Gia Lâm.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2840, 1289, 2, 'Media Player Developer', 'Mô tả công việc\n- Phát triển Media Player tối ưu hóa cho các sản phẩm của THINKWARE\n- Áp dụng và bảo trì Media Player đã phát triển trên các nền tảng Android / iOS / Windows PC / Mac PC.\n\nYêu cầu ứng viên\nKinh nghiệm:\n- Không yêu cầu\n- Đối với ứng viên mới ra trường hoặc có kinh nghiệm dưới 1 năm, phỏng vấn sẽ dựa trên những kiến thức đã học ở trường.\nYêu cầu bắt buộc:\n- Chuyên ngành Kỹ thuật hoặc Khoa học Máy tính\n- Có kiến thức hoặc kinh nghiệm lập trình với ngôn ngữ C/C++\n- Có kiến thức về Hệ điều hành (O/S)\n- Bắt buộc ghi rõ các môn học liên quan đã hoàn thành tại đại học trong hồ sơ xin việc\nƯu tiên:\n- Có kiến thức hoặc kinh nghiệm phát triển với FFmpeg\n- Có kiến thức hoặc kinh nghiệm phát triển với DirectX / OpenGL\n- Có kiến thức hoặc kinh nghiệm về giao thức RTP / RTSP\n- Có kiến thức hoặc kinh nghiệm về giao thức mạng (TCP/IP)\n- Có kiến thức hoặc kinh nghiệm với HFS (HTTP File Server)\n\nQuyền lợi\n- Lương tháng 13.\n- Môi trường làm việc năng động, thoải mái, sáng tạo.\n- Review lương hàng năm theo năng lực.\n- Khám sức khỏe tổng quát định kỳ.\n- Cung cấp thiết bị làm việc (laptop + màn hình to).\n- Snack bar đầy ấp đồ ăn.\n- Company trip, party hàng tháng, happy hours.\n- Cơ hội training tại nước ngoài.\n- Lớp học ngoại ngữ.\n- Hỗ trợ chi phí khóa học đào tạo kỹ năng.\n- Đóng BHXH, BHYT, BHTN đầy đủ theo chế độ của Nhà nước.\n- 12 phép năm / nghỉ lễ theo chế độ Nhà nước.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Mach Hub Building, 364 Ung Văn Khiêm, P25, Bình Thạnh.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2841, 186, 2, 'Technical Artist (Generalist)', '• Lập kế hoạch dự án và thời gian thực hiện nhằm đáp ứng các mục tiêu của khách hàng/người dùng.\n• Lập kế hoạch dự án và thời gian thực hiện phù hợp với các mục tiêu của bộ phận CNTT, đặc biệt về bảo mật và tuân thủ quy định.\n• Phối hợp với nhóm quản trị mạng và máy chủ để điều chỉnh các thay đổi, đánh giá tác động và xây dựng kế hoạch dự phòng cho từng dự án hoặc thay đổi trong tổ chức trên toàn cầu.\n• Nắm rõ các tiêu chuẩn CNTT toàn cầu để đảm bảo các kế hoạch và mục tiêu được thảo luận đầy đủ trong nội bộ nhóm CNTT, từ đó đảm bảo tính tuân thủ và tránh lạc hậu.\n• Tổ chức các cuộc họp nội bộ định kỳ trong phạm vi toàn cầu với đội ngũ CNTT để đảm bảo sự phối hợp hiệu quả giữa các khu vực và làm việc từ xa thuận lợi.\n• Quản lý kế hoạch dự án và cung cấp các cập nhật thường xuyên bao gồm tiến độ dự án, hiệu suất tài chính và quản lý nguồn lực.\n• Đảm bảo tuân thủ quy trình vận hành chuẩn (SOP) trong suốt quá trình thực hiện dự án.\n• Hỗ trợ các trưởng bộ phận hoặc nhóm trưởng CNTT nhằm đảm bảo không có rủi ro hay sự cố ảnh hưởng đến dự án và đạt được các mục tiêu đã đề ra.\n\nYêu cầu ứng viên\n• Bắt buộc có khả năng lập trình Shader cho Unity (có thể dùng ShaderLab thay thế)\n• Bắt buộc có hiểu biết sâu rộng về toàn bộ các công cụ dùng trong quy trình phát triển game\n• Có khả năng thiết lập ánh sáng (light rigging)\n• Bắt buộc có kỹ năng quản lý chất lượng và tối ưu hóa tài nguyên (asset)\n• Có thể thiết kế toàn bộ pipeline xử lý asset\n• Kinh nghiệm: Tối thiểu 10 năm (có thể cân nhắc từ 8 năm trở lên)\n• Yêu cầu: Có portfolio (hồ sơ năng lực)\n• Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận. Mức lương cao, có thể thoả thuận theo năng lực của ứng viên\n• 1 năm tăng lương/lần\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước)\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm, Tiêm phòng HPV, cúm,...\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes Gardenia Hàm Nghi, Nam Từ Liêm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2842, 1331, 2, 'Nhân Viên Lập Trình Máy CNC', '• Lập trình gia công máy CNC bằng phần mềm MasterCam, ….\n• Lập phương án gia công chi tiết, gia công đồ gá\n• Theo dõi quản lý sản phẩm đảm bảo tiến độ và chất lượng.\n• Thực hiện các công việc cấp trên giao.\n\n• Yêu cầu bằng cấp: tốt nghiệp trung cấp trở lên\n• Có ít nhất 1 năm kinh nghiệm đứng máy và lập trình CNC biết sử dụng các phần mềm cơ khí Auto CAD, MasterCam.\n• Am hiểu về 1 trong các công nghệ gia công cắt gọt kim loại như Tiện, Phay CNC, mài, xung điện cắt dây.\n\n- Ký HĐLĐ, tham gia BHXH đầy đủ sau thử việc;\n- Thời gian làm việc: Từ thứ 2 đến thứ 7;\n- Phụ cấp cơm trưa, Phụ cấp cơm tăng ca, Hưởng đầy đủ các chế độ theo đúng quy định của nhà nước;\n- Môi trường làm việc ổn định, lâu dài.\n- Du lịch định kỳ hàng năm\n- Lương thưởng cuối năm', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2843, 1142, 2, 'Fresher .NET', '• Developing projects for Japanese, English and domestic customers\n• Creating Backend components with C#, Net core, MVC (Frontend: ReactJS, Backend: VB.NET/C#)\n• Integrating data storage solutions\n• Maintaining and troubleshooting existing web applications\n• Optimize our web applications for maximum speed\n• Participating in all works in the software development process, including requirements inquiry, analysis, design, research new technology ...\n• Contributing ideas to leaders and customers to improve products or work processes\n• Solving issues, executing work according to plan, report work progress for direct management (PM)\n• Detailed information about the project\'s profession will be discussed in the interview.\n\n• Bachelor’s degree in Computer Science Engineering or other related courses.\n• At least 6 months experience working with .Net, C#\n• Experience working with SQL databases, ability to write complex queries and optimize them\n• Proficiency with code versioning tools including Git, Github, SVN\n• Strong knowledge of front-end technologies including HTML5, JavaScript, and CSS3\n• Good problem-solving skills\n• Willing to work hard and learn new technologies\n• Having Japanese (equivalent to N3) or English is an advantage.\n\n• Competitive salary package and specific benefits. You\'ll get a bonus of a half month salary If you are on board before October 1st\n• TET bonus from up to 4-month salary according to seniority, work results, and business situation of the company.\n• The company pays (32%) the costs of social insurance, health insurance, and unemployment insurance for its employees.\n• Performance review twice a year\n• Annual holiday: 12 annual leave and Corporate Birthday 11/27\n• Working in a dynamic and professional environment with many promotion opportunities.\n• Receive benefits according to seniority\n• Being trained in foreign languages, sponsored to learn certificates to improve professional skills and soft skills.\n• Lots of opportunities to go to Onsite at SPLUS JAPAN (for staff with Japanese proficiency from N3 and above)\n• Sports activities: Football\n• Annual company trip, team building, birthdays for employees in the month, and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas ...).\n• Time working: Monday – Friday (9:00 – 18:00).\n\n- Hồ Chí Minh: Tòa nhà HaDo Airport, 2 Hồng Hà, phường 2, Tân Bình\n\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2844, 1382, 2, 'Lập Trình Viên C# WPF', 'Mô tả công việc:\n- Phát triển ứng dụng desktop sử dụng .NET Framework / .NET Core với WPF và XAML\n- Tối ưu hiệu suất ứng dụng, trải nghiệm người dùng và khả năng mở rộng\n- Tham gia phân tích kỹ thuật, thiết kế hệ thống và cải thiện mã nguồn\n- Sửa lỗi, bảo trì và nâng cấp các sản phẩm phần mềm hiện có\n\nYêu cầu ứng viên:\nBắt buộc:\n- Tốt nghiệp chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan\n- Từ 2–5 năm kinh nghiệm thực tế với C#, WPF và XAML\n- Hiểu rõ kiến trúc MVVM, Lập trình hướng đối tượng (OOP), nguyên lý SOLID và các Design Pattern\n- Thành thạo Git, Visual Studio, GitHub/GitLab\n- Có kinh nghiệm làm việc trong môi trường Agile/Scrum\n- Tư duy logic, chủ động, có khả năng tự học và cập nhật công nghệ mới\n\nƯu tiên có:\n- Hiểu biết về DevExpress, Telerik hoặc các bộ công cụ giao diện người dùng khác\n- Kinh nghiệm làm việc với RESTful API, CI/CD pipelines\n- Có khả năng giao tiếp tiếng Anh cơ bản hoặc đọc hiểu tài liệu kỹ thuật tốt\n\nQuyền lợi:\n- Mức lương & thưởng: Thỏa thuận theo năng lực.\n- Thưởng tháng 13 và thưởng theo kết quả công việc.\n- Chế độ bảo hiểm và phúc lợi theo quy định của Bộ luật Lao động.\n- Cơ hội đào tạo chuyên môn nhằm nâng cao kỹ năng nghiệp vụ và chuyên môn kỹ thuật.\n- Môi trường làm việc hiện đại, năng động, thân thiện và cởi mở, khuyến khích sáng tạo và phát triển cá nhân.\n- Các hoạt động gắn kết nhân viên như team building, du lịch hàng năm, sự kiện nội bộ định kỳ.\n- Tham gia các câu lạc bộ thể thao như cầu lông, bóng đá,...\n- Thời gian làm việc: Từ 8:00 đến 17:00, từ thứ Hai đến thứ Sáu (nghỉ Thứ Bảy và Chủ Nhật).\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Công viên phần mềm Quang Trung, Quận 12.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2845, 1341, 2, 'Chuyên Viên Cao Cấp Ngân Hàng Số (Web,App)', 'Mô tả công việc:\n- Tham gia xây dựng các quy trình, hướng dẫn về nghiệp vụ của Đơn vị.\n- Báo cáo và tham gia khắc phục rủi ro của đơn vị trong quá trình vận hành, phối hợp với các đơn vị liên quan để đưa ra các phương pháp đo lường và giảm thiểu rủi ro.\n- Thực hiện các công việc theo đúng các chính sách, quy định, quy trình, hướng dẫn nội bộ,… và cam kết chất lượng dịch vụ (SLAs).\n- Chịu trách nhiệm thực hiện thiết kế, phát triển tích hợp, hỗ trợ cấp độ 3 và vận hành cấp độ 3 các nền tảng và công nghệ ngân hàng số và các hệ thống có liên quan.\n- Tham gia trao đổi cùng BA, RM,… và đề xuất phương án thực hiện các yêu cầu phát triển đảm bảo hiệu quả nhất.\n- Trực tiếp thực hiện và phối hợp với các bộ phận khác trong các dự án có các thành phần liên quan đến nền tảng và công nghệ ngân hàng số và các hệ thống có liên quan trong các dự án công nghệ của Khối.\n- Thực hiện các công việc khác có liên quan theo yêu cầu của các cấp quản lý.\n\nYêu cầu ứng viên:\n- Có khả năng lập trình với một trong các ngôn ngữ sau: Android: Kotlin || Java; iOS Swift; Flutter.\n- Java: Am hiểu framework Springboot; Hiểu biết về các chuẩn message JSON và các cơ sở dữ liệu Oracle, SQL, Redis … là 1 một lợi thế; Có kiến thức triển khai và cấu hình Webserver: Tomcat; GraphQL; Apollo Server.\n- Angular: Nắm vững HTML/CSS, JavaScript; Có kiến thức triển khai và cấu hình. Webserver: Nginx; Có kinh nghiệm sử dụng theme Metronic là lợi thế.\n\nQuyền lợi:\n- Thu nhập hấp dẫn cùng gói phúc lợi toàn diện.\n- Hệ thống các khóa đào tạo phát triển bản thân tương ứng từng vị trí công việc.\n- Lộ trình thăng tiến rõ ràng.\n- Trải nghiệm các hoạt động văn hóa tổ chức đặc sắc.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 25 Trần Hưng Đạo, Hoàn Kiếm, Hoàn Kiếm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2846, 1236, 2, 'Nhân Viên Lập Trình Máy Phay CNC', 'Mô tả công việc\n- Xây dựng và hoàn thiện quy trình công nghệ gia công, trang thiết bị, đồ gá, dao cụ và các thiết bị phụ trợ phục vụ cho việc gia công các sản phẩm cơ khí của Công ty.\n- Học hỏi và làm quen với các phần mềm lập trình máy móc, ngôn ngữ lập trình, và các quy trình sản xuất.\n- Vận hành máy phay CNC: Đọc bản vẽ, chuẩn bị dụng cụ cắt, chỉnh sửa chương trình...\n- Tham gia vào quá trình cải tiến và tối ưu hóa quy trình sản xuất.\n- Tuân thủ các quy định về an toàn lao động và bảo vệ môi trường.\n- Thực hiện các công việc khác theo sự phân công của cấp trên.\n\nYêu cầu ứng viên\n- Tốt nghiệp trung cấp, cao đẳng hoặc đại học chuyên ngành kỹ thuật (Cơ khí, cơ khí chế tạo, cắt gọt kim loại, kỹ thuật cơ khí...).\n- Có kinh nghiệm từ 1 năm trong lĩnh vực lập trình máy móc là một lợi thế.\n- Nắm vững kiến thức cơ bản về phay CNC, gia công cắt gọt kim loại\n- Khả năng làm việc độc lập và làm việc nhóm tốt.\n- Có tinh thần trách nhiệm cao, cẩn thận, tỉ mỉ.\n- Khả năng học hỏi nhanh, tiếp thu kiến thức mới.\n- Có khả năng đọc hiểu tài liệu kỹ thuật, đọc hiểu bản vẽ 2D\n- Có thể làm việc theo ca.\n\nQuyền lợi\n- Mức lương cạnh tranh, phù hợp với năng lực và kinh nghiệm.\n- Được đóng bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật.\n- Được tham gia các chương trình đào tạo, nâng cao nghiệp vụ.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Có cơ hội thăng tiến trong công việc.\n- Được hưởng các chế độ phúc lợi khác theo quy định của công ty.\n\nĐịa điểm làm việc\n- Hà Nội: gần Khu Công Nghiệp Ngọc Hồi, xã Liên Ninh, Thanh Trì\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 06:00 đến 14:30)\n- Thứ 2 - Thứ 7 (từ 14:00 đến 22:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2847, 1134, 2, 'Coding Quality Review Team Lead', 'Mô tả công việc\n- Thực hiện kiểm tra mã nguồn kỹ lưỡng cho các yêu cầu hợp nhất (pull/merge requests) trước khi đóng gói và triển khai.\n- Đảm bảo mã tuân thủ theo các tiêu chuẩn coding, nguyên tắc thiết kế và kiến trúc hệ thống.\n- Phát hiện lỗi logic, bug tiềm ẩn và các khoản nợ kỹ thuật trong mã nguồn.\n- Phối hợp với lập trình viên để đưa ra phản hồi mang tính xây dựng và hướng dẫn cải tiến.\n- Kiểm tra mức độ bao phủ và hiệu quả của các test case tự động (unit test, integration test).\n- Đảm bảo mã đáp ứng các yêu cầu về bảo mật, khả năng mở rộng và bảo trì.\n- Giám sát kết quả phân tích mã tĩnh và thực thi các chính sách kiểm duyệt (VD: SonarQube, ESLint).\n- Phối hợp với nhóm DevOps để đảm bảo mã đã sẵn sàng cho giai đoạn build, đóng gói và triển khai.\n- Ghi lại quy trình kiểm tra mã và đóng góp vào việc xây dựng các chuẩn mực chất lượng mã và DevOps.\n\nYêu cầu ứng viên\n1. Trình độ học vấn: Bằng cử nhân về Kỹ thuật Máy tính, CNTT hoặc ngành tương đương.\n2. Kinh nghiệm:\nTối thiểu có 03 năm phát triển phần mềm, DevOps hoặc vai trò kiểm duyệt mã.\nCó kinh nghiệm trong lĩnh vực tài chính tiêu dùng, ngân hàng là một lợi thế.\n3. Kỹ năng:\nThành thạo ít nhất một ngôn ngữ lập trình (ví dụ: JavaScript, Python, Java, Go).\nCó kiến thức về hệ thống CI/CD (ví dụ: Jenkins, GitLab CI, GitHub Actions, Azure DevOps).\nKinh nghiệm sử dụng Git và các nền tảng như GitHub, GitLab,SonarQube, ESLint, Checkmarx,...\nHiểu rõ về nguyên tắc lập trình an toàn và các công cụ phân tích mã tĩnh.\n4. Yêu cầu khác:\nKỹ năng tư duy logic và chú ý đến chi tiết.\nKỹ năng giao tiếp và làm việc nhóm tốt.\n\nQuyền lợi\n- Thử việc 100% mức lương;\n- Ký Hợp đồng Lao động chính thức;\n- Chế độ Bảo hiểm xã hội, Bảo hiểm thất nghiệp, Bảo hiểm y tế theo quy định Nhà nước sau 2 tháng thử việc;\n- Bảo hiểm tai nạn 24/24;\n- Khám sức khỏe định kỳ;\n- Được tham gia khóa đào tạo chuyên môn;\n- 16 ngày phép/năm;\n- Lương tháng 13, thưởng và phụ cấp tùy theo từng vị trí.\n\nĐịa điểm làm việc\n- Hồ Chí Minh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2848, 1296, 2, 'Fullstack Developer Intern (Hỗ Trợ 4M-5M)', 'Mô tả công việc\n- Phát triển sản phẩm phần mềm theo định hướng của công ty trên nền tảng Shopify.\n- Hỗ trợ khách hàng cài đặt, sử dụng sản phẩm.\n- Fix lỗi và cập nhật sản phẩm liên tục đáp ứng nhu cầu của khách hàng.\n- Phát triển và vận hành sản phẩm trên hệ thống cloud AWS.\n- Làm việc với những công nghệ mới nhất React JS, GraphQL, Node JS, React Native.\n\nYêu cầu ứng viên\n- Sinh viên năm 3,4 ngành CNTT các trường Đại học (UET, HUST, PTIT, FPT, HAUI, HANU,…) tại Hà Nội;\n- Đã từng có kinh nghiệm thực tập 3 tháng tại các Công ty Công nghệ hoặc có dự án cá nhân sử dụng tech stack tương ứng;\n- Có khả năng sử dụng 1 ngôn ngữ lập trình bất kỳ (PHP, Java, JS…) và có hiểu biết căn bản về lập trình web, Javascript, relational database (MySQL). Ưu tiên ứng viên có kinh nghiệm Reactjs, GraphQL, Node JS. Đặc biệt, có hiểu biết về React Native là lợi thế lớn;\n- Tiếng anh cơ bản đọc, hiểu tốt;\n- Tư duy logic tốt, có kỹ năng giải quyết vấn đề và làm việc trong môi trường áp lực cao.\n- Yêu thích làm việc với nền tảng thương mại điện tử.\n- Sẵn sàng được đầu với nhiều thử thách, chịu khó dành nhiều thời gian nghiên cứu và giải quyết vấn đề khi được yêu cầu.\n- Khả năng làm việc độc lập hoặc làm việc nhóm, tự chủ động giải quyết các vấn đề trong công việc theo đúng tiến độ và hướng dẫn.\n- Thẳng thắn trao đổi, có trách nhiệm với công việc, tôn trọng đồng nghiệp.\n\nQuyền lợi\n- Nhận lương hỗ trợ thực tập: 4M – 5M/ tháng\n- Được offer trở thành nhân viên chính thức nếu hoàn thành tốt 2 tháng thực tập với mức lương khởi điểm lên tới 12 triệu/tháng\n- Được tham gia vào phát triển 1 Super App trên Shopify, phát triển kĩ năng sử dụng React JS, NodeJS, React Native. Được làm việc và support nhiệt tình bởi các Senior Shopify Developer\n- Thời gian làm việc 5 ngày/tuần, từ 8h30 đến 17h45. Không khuyến khích OT.\n- Làm việc tại một trong những công ty Magento hàng đầu tại Việt Nam, là đối tác Technology Partner của Magento và Solution Provider cho nhiều khách hàng Magento Enterprise trên thế giới (100% khách hàng nước ngoài).\n- Có cơ hội phát triển kỹ năng thuyết trình, huấn luyện đào tạo qua các buổi chia sẻ, training nội bộ.\n- Nhiều phúc lợi hấp dẫn: 13.5 ngày nghỉ phép/năm (12 ngày nghỉ phép theo quy định và 1.5 ngày nghỉ phép du lịch hàng năm), bảo hiểm, hiếu hỉ, quà sinh nhật, thưởng thâm niên và các phúc lợi khác theo quy định của pháp luật.\n- Môi trường làm việc trẻ trung (95% là 9x), làm hết sức, chơi hết mình. Văn phòng làm việc tiện nghi. Free trà, cafe và có tủ đồ uống.\n- Tham gia các chương trình team building, dã ngoại, sinh nhật thành viên, du lịch, từ thiện… do BSS tổ chức thường xuyên.\n- Tham gia các CLB chạy, đá bóng, boardgame, văn nghệ… sau giờ làm việc.\n- Nghỉ hằng năm và các phúc lợi khác theo quy định của pháp luật.\n\nĐịa điểm làm việc\n- Hà Nội: 48 Tố Hữu, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:45)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2849, 1276, 2, 'Nhân Viên Lập Trình PHP', 'Mô tả công việc:\n- Phát triển và bảo trì hệ thống backend bằng PHP và Laravel.\n- Thiết kế, tối ưu cơ sở dữ liệu và API phục vụ frontend.\n- Hỗ trợ và phối hợp với đội frontend để xây dựng các tính năng mới.\n- Tối ưu hiệu suất hệ thống, xử lý lỗi và nâng cao bảo mật.\n\nYêu cầu ứng viên:\n- Giới tính: Nam\n- Bằng cấp: Đại Học\n- Thành thạo PHP, HTML, CSS, JavaScript, jQuery, Bootstrap.\n- Ít nhất 2 năm kinh nghiệm làm việc với Laravel.\n- Có kinh nghiệm làm việc với cơ sở dữ liệu MySQL hoặc PostgreSQL.\n- Hiểu biết về RESTful API, WebSocket là một lợi thế.\n- Có kinh nghiệm làm việc với dữ liệu lớn, biết phân tích hệ thống.\n- Có kinh nghiệm làm việc với các hệ thống bán hàng, CRM là một lợi thế.\n- Khả năng làm việc nhóm tốt, tư duy logic và giải quyết vấn đề.\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn (từ 15.000.000 đến 25.000.000 VND) đàm phán theo năng lực và mong muốn của ứng viên\n- Thưởng định kỳ và xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Được tham gia 2 gói bảo hiểm:\n- BHXH, BHYT, BHTN theo quy định pháp luật\n- Bảo hiểm chăm sóc sức khỏe cho cá nhân và người thân (OWS Care)\n- Được khám sức khỏe định kỳ hàng năm;\n- Có cơ hội tiếp xúc, học hỏi những công nghệ tiên tiến qua các dự án mới của công ty;\n- Được hưởng đầy đủ các chế độ phúc lợi khác như: thưởng dự án, thưởng lễ Tết, liên hoan, sinh nhật, teambuilding, nghỉ mát, gala,....\n- Weekly Techtalks trao đổi, chia sẻ về các công nghệ mới nhất; là cơ hội để các thành viên học hỏi lẫn nhau.\n\nĐịa điểm làm việc:\n- Hà Nội: 14 Nguyễn Cảnh Dị, Đại Kim, Hoàng Mai, Hoàng Mai\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2850, 1207, 2, 'Java Developer - 2 Năm Kinh Nghiệm', 'Mô tả công việc\n- Phát triển dịch vụ web bằng JAVA, Front-end sử dụng HTML, CSS, JavaScript, Jquery..\n- Sử dụng Spring Boot, Framework, mô hình MVC\n- Tham gia phát triển, đề xuất giải pháp kỹ thuật cho các dự án\n- Phát triển các hệ thống mới và nâng cấp các hệ thống đã có\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của Leader\n\nYêu cầu ứng viên\n- Trình độ đại học, cao đẳng chuyên ngành CNTT hoặc các chứng chỉ tương đương trở lên\n- Từ 02 năm kinh nghiệm về phát triển dịch vụ web với JAVA framework, yêu thích việc lập trình bằng ngôn ngữ JAVA\n- Có kiến thức về design patterns và unit test (Junit, TestNG, NUnit)\n- Nắm vững về HTML, CSS, JavaScript, Jquery là một điểm cộng (các ngôn ngữ khác, nếu không thành thạo sẽ được đào tạo)\n- Khả năng tự nghiên cứu, phân tích và giải quyết vấn đề\n- Có khả năng tư duy logic và lập trình\n- Khả năng làm việc độc lập hoặc theo nhóm\n- Sẵn sàng học hỏi các công nghệ mới cần thiết cho công việc\n- Có kiến thức về Spring/Spring Boot, MySQL, Oracle...\n- Có tiếng Nhật là một lợi thế\n\nQuyền lợi\n- Mức lương: 15 - 45 triệu, tùy theo năng lực\n- Thử việc lên đến 100% lương\n- Phụ cấp cơm trưa và vé gửi xe hàng tháng\n- Cung cấp đầy đủ các thiết bị phục vụ cho công việc\n- Nghỉ thứ 7, chủ nhật\n- Đóng BHXH sau khi thử việc và hưởng các chế độ phúc lợi theo luật lao động Việt Nam\n- Đánh giá xét tăng lương 2 lần/năm\n- Hưởng lương tháng 13\n- Được tham gia các Câu lạc bộ dưới sự tài trợ chính thức của Công ty: CLB Bóng đá, Lớp tiếng Nhật,...\n- Được ham gia các bữa tiệc sinh nhật, team building hàng quý, company trip hàng năm...\n- Cơ hội thăng tiến cao, cơ hội rất lớn để trở thành key member của công ty.\n- Môi trường trẻ trung, năng động, chuyên nghiệp theo tiêu chuẩn chất lượng Nhật Bản.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 25/7 Nguyễn Bỉnh Khiêm, Phường Bến Nghé, Quận 1\n- Hà Nội: Tầng 4, Toà nhà H10, số 2 ngõ 475 Nguyễn Trãi, Thanh Xuân\n- Đà Nẵng: 88 An Hải Đông 1, An Hải Đông, Sơn Trà\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 1, Hà Nội, Thanh Xuân, Đà Nẵng, Sơn Trà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2851, 1242, 2, 'Senior C Language Developer', 'We are looking for a Senior C Language Developer to join our LG CNS Vietnam Build Center. You will be working on high-performance system-level development with deep integration into network protocols and testing environments. The ideal candidate is a strong C programmer with high-level understanding of networking, packet analysis, and testing frameworks.\n\n- Design, implement, and optimize software modules in pure C for embedded or system-level applications.\n- Develop and maintain network-related features, including TCP/UDP stack handling.\n- Analyze and debug network traffic using tools like TCPDump, Wireshark, etc.\n- Integrate and apply testing frameworks/tools to validate and ensure code stability and performance.\n- Work closely with global teams (Korea HQ) to gather requirements, align on architecture and deployment strategy.\n- Review and maintain high standards of code quality, documentation, and security.\n- Participate in performance tuning and issue resolution in production-like environments.\n\n**Candidate Requirements**:\n- Bachelor’s degree or higher in Computer Science, Software Engineering, or related field.\n- 5+ years of experience in C programming in Linux/Unix environments.\n- Strong experience in network programming, including TCP/IP, UDP, socket programming.\n- High-level understanding of TCPDump, Wireshark, and general packet analysis techniques.\n- Experience with unit testing frameworks (e.g. CMocka, Unity) or custom test environments.\n- Good debugging skills using GDB, Valgrind, or similar tools.\n- Familiarity with multi-threaded programming, memory management, and performance optimization.\n- Effective communication skills in English (Korean is a plus).\n\n**Benefits**:\n- Attractive salary and bonus will be discussed after going through CV & Interview.\n- Topik allowance.\n- Review capacity annually and adjust salary increases according to work performance.\n- Health care: Premium health insurance, Annual health check-up.\n- Young working environment.\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.).\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8 hours/day).\n\n**Working Location**:\n- Hà Nội: Onsite 15th Floor, Keangnam Landmark 72, Me Tri, Nam Từ Liêm.\n\n**Working Time**:\n- Monday - Friday (from 08:00 to 17:00).\n\n**Application Method**:\n- Candidates can apply online by clicking "Apply" button below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2852, 1288, 2, '.NET Dev (C#,ASP.Net MVC,SQL)', 'Mô tả công việc:\n- Tham gia phát triển và tối ưu hệ thống phần mềm EasyInvoice trên nền tảng .NET MVC.\n- Phối hợp với các bộ phận BA, Tester, UI/UX để phân tích yêu cầu và triển khai tính năng mới.\n- Xây dựng, cải tiến các module như: chấm công, tính lương, hợp đồng điện tử, bảo hiểm xã hội, KPI...\n- Xử lý dữ liệu lớn, tối ưu truy vấn SQL và hiệu năng hệ thống.\n- Tham gia cải tiến kiến trúc theo hướng dịch vụ (Service-Oriented), tích hợp với Redis, RabbitMQ.\n- Làm việc theo mô hình Agile/Scrum, đảm bảo tiến độ và chất lượng phần mềm.\n\nYêu cầu ứng viên:\n- Kinh nghiệm: từ 6 tháng - 1 năm kinh nghiệm .Net\n- Có kiến thức về HTML/CSS và JS.\n- Có tư duy tốt về thiết kế và phát triển hệ thống\n- Có phát triển hệ thống hướng dịch vụ là một lợi thế\n- Có kinh nghiệm về thiết kế, turning, giám sát SQL-Server.\n\nTech Stack:\n- .NET MVC 5\n- Entity Framework\n- Web API, JSON\n- JQuery, JavaScript, HTML5/CSS3.\n- Đã làm việc với Redis, RabbitMQ, Windows Service là một lợi thế.\n- Đã làm việc với một framework ORM.\n\nQuyền lợi:\n- Lương từ 8 - 15 triệu/tháng+ trợ cấp\n- Có cơ hội thăng tiến cao, xét tăng lương 2 lần/năm\n- Làm việc tại Doanh nghiệp với sứ mệnh phụng sự xã hội, mang lại các sản phẩm, dịch vụ nhằm thay đổi năng suất cho các doanh nghiệp\n- Văn hóa trao đổi thẳng thắn, hỗ trợ tận tình; Sếp trẻ tâm lý, đồng nghiệp thân thiện\n- Làm việc trong môi trường chuyên nghiệp, năng động, nhiều cơ hội học tập, phát triển, và được hưởng đãi ngộ phù hợp với năng lực.\n- Lộ trình thăng tiến rõ ràng, có cơ hội trở thành nhân tố quan trọng và chủ chốt của công ty\n- Được hưởng các chế độ phúc lợi của công ty: thưởng lễ tết, nghỉ mát hàng năm, ...\n- Được hưởng hõ trợ từ quỹ Công đoàn cơ sở: ốm đau, hiếu hỉ, sinh nhật, ...\n- Có cơ hội tham gia các khóa đào tạo, huấn luyện chuyên môn.\n- Du lịch công ty hàng năm.\n- Tham gia các hoạt động văn nghệ, thể thao cùng công ty: sinh nhật tháng, quý, ngày quốc tế phụ nữ, teabreak hang tuần, ..\n- Các chế độ BHXH, BHYT, nghỉ phép full lương theo quy định nhà nước.\n- Hỗ trợ các công cụ dụng cụ cần thiết để đáp ứng công việc.\n\nĐịa điểm làm việc:\n- Hà Nội: Trụ sở chính: Nhà khách ATS, số 8 Phạm Hùng, Phường Mễ Trì, Nam Từ Liêm\n- Hà Nội: Cầu Giấy\n- Hồ Chí Minh: số H56, Phường Tân Thới Nhất, Đường Dương Thị Giang, Quận 12\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2853, 1227, 2, 'Salesforce Developer', 'We are seeking a Salesforce Developer to join our team to help design, build and maintain custom solutions on the Salesforce platform. The ideal candidate will have experience in developing complex solutions using Apex, Visualforce, LWC and Aura components.\nYour role & responsibilities:\nAnalyze business and map with standards Salesforce function.\nDevelop, implement, and maintain custom solutions on the Salesforce platform.\nDesign and build custom objects, fields, formulas, validation rules, workflows, and reports.\nWrite Apex classes, triggers, and Visualforce pages to support business requirements.\nDevelop and maintain integrations with external systems.\nCollaborate with the team to ensure solutions meet business requirements and are delivered on time.\nMentor and support junior team members as needed.\n\nYour skills & qualifications:\nMust Have:\nBachelor’s degree in computer science, Information Systems, Business administration or related field\n1+ years experience in Salesforce.\nGood written and verbal communication skills (English - IELT 6.5)\nNice to have:\nThe Salesforce Certified Platform Developer 1, Developer 2 is a plus.\nThe Salesforce Certified Administrator is a plus.\nExperience working on Salesforce application development, Salesforce Administrator, and experience related to SalesCloud CRM.\nExperience with Salesforce configuration and custom development\nExperience with REST and SOAP APIs\nGood understanding of Salesforce security model and data architecture\nExperience with ERP\nExperience working with Marketing Cloud is a plus.\nBe creative and good at user experiences.\nExcellent communication skills.\nA commitment to quality and a thorough approach to work.\nGood teamwork and reliability.\nDrive and enthusiasm with the ability to manage and co-ordinate multiple projects.\nStrong experience with Apex, Visualforce LWC or Aura components\nKnowledge of Agile software development methodologies\n\n• Competitive & attractive salary (up to 20M).\n• Working time:  8h30 – 17h30 from Mon to Friday\n• 13th, 14th, 15th - month salary, upgrading salary 1 times/year or when you have excellent achievement.\n• Profit bonus and Performance bonus plan.\n• Birthday party / Welcome party / Year-end party / Holidays.\n• Provide devices; monitors for working.\n• Team building activities including annual company trips, parties, and other attractive HR benefits.\n• Various training on trending technologies, best practices, and soft skills.\n• Supportive, fun and flexible work environment that values innovation, creativity and new ideas.\n• Enjoy the benefits of social insurance, health insurance and other benefits under the labor law.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2854, 1411, 2, 'Thực Tập Sinh PHP (Sinh Viên Năm Cuối, Backend)', 'Mô tả công việc:\n- Lịch phỏng vấn dự kiến: Từ ngày 01/07/2025 trở đi\n- Quy trình tuyển dụng: Test chuyên môn => Phỏng vấn trực tiếp.\n- Nội dung công việc:\n    - Tuỳ theo nhu cầu dự án tại từng thời điểm hiện tại, công ty sẽ đào tạo những ngôn ngữ lập trình khác nhau và các kỹ thuật mới nhất, cụ thể như:\n        + Ngôn ngữ lập trình PHP với các framework phiên bản mới nhất.\n        + Kỹ thuật về OOP, PHP Basic, Database, ...\n        + Frontend và các framework như Vuejs, Reactjs, ...\n    - Nắm bắt nghiệp vụ phân tích để phát triển hệ thống trên nền web cùng với các kỹ sư tại Việt Nam và tại Nhật Bản.\n\nYêu cầu ứng viên:\n- Yêu cầu:\n    - Sinh viên đang học năm cuối các ngành Khoa học máy tính, Công nghệ phần mềm tại các trường Đại Học và có kết quả học tập loại khá trở lên.\n    - Có thể tham gia thực tập tại công ty từ 6 – 10 buổi / tuần ( tương đương 3 – 5 ngày/ tuần).\n    - Có hiểu biết hoặc đã tìm hiểu về lập trình website mà có sử dụng một trong các ngôn ngữ lập trình PHP, Java, .Net (C#,VB.NET), NodeJS.\n    - Nắm vững kiến thức về SQL Query.\n    - Giao tiếp tốt, chủ động trong công việc.\n    - Có đam mê phát triển phần mềm.\n    - Có kỹ năng làm việc theo nhóm, hòa đồng.\n    - Có tư duy logic, sáng tạo.\n- Lợi thế:\n    - Có kiến thức về:\n        + PHP, MySQL.\n        + PHP Framework: (CodeIgniter, Laravel, ...).\n        + Javascript và JS Framework (VueJS, ReactJS...).\n    - Hoặc đã từng thực tập tại các Công ty phần mềm và thực hiện dự án thực tế về ngôn ngữ PHP và các framework của PHP.\n\nQuyền lợi:\n- Công ty sẽ quyết định ký HĐLĐ nếu đánh giá sinh viên đủ năng lực sau thời gian thực tập 2 tháng. Sinh viên sẽ trở thành nhân viên chính thức (BHXH full lương) không qua thử việc và không yêu cầu làm fulltime.\n- Sinh viên sau khi trở thành nhân viên chính thức có thể đi làm từ 3 ngày trở lên trong tuần cho đến khi chính thức tốt nghiệp.\n- Mức trợ cấp thực tập tại công ty: 100,000VND/ngày (sinh viên làm 0.5 ngày cũng được làm tròn thành 1 ngày).\n- Bữa trưa chào mừng nhân viên mới.\n- Thời gian thực tập linh động phù hợp với lịch học của sinh viên.\n- Được tham gia vào dự án phần mềm thực tế cùng các kỹ sư có kinh nghiệm và chuyên môn cao.\n- Môi trường làm việc chuyên nghiệp, với những người trẻ đầy nhiệt huyết, năng động.\n- Biểu dương cho sinh viên đạt được thành tích ưu tú trong quá trình thực tập.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lầu 12, An Phú Plaza 117-119 Lý Chính Thắng, Phường Võ Thị Sáu, Quận 3\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 3', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2855, 1268, 2, 'Embedded Systems Developer', 'Mô tả công việc\nPhát triển các hệ thống phần mềm hệ thống cho cho các dòng máy điện, điện lạnh thông minh, IoT;\nTham gia vào phân tích yêu cầu, thiết kế kiến trúc hệ thống, thiết kế phần mềm nhúng;\nPhát triển firmware thiết bị, phần mềm nhúng;\nThu thập và xử lí các yêu cầu thiết kế và kĩ thuật;\nNghiên cứu và áp dụng các công nghệ mới để tối ưu hóa hiệu quả phát triển sản phẩm;\nĐảm bảo sản phẩm làm ra cần phải chạy đúng nghiệp vụ và tốc độ xử lý cũng phải tối ưu cho lượng người dùng và thiết bị kết nối lớn.\n\nYêu cầu ứng viên\nCó kiến thức về lập trình hướng đối tượng;\nTốt nghiệp Cao đẳng/ Đại học chuyên ngành Điện, Tự động hóa, Điện tử, Cơ tin...\nKinh nghiệm ở vị trí lập trình nhúng 5-6 năm\nƯu tiên có kinh nghiệm lập trình nhúng cho các thiết bị điện tử, điện lạnh, gia dụng hoặc vi điều khiển, ESP MCU, Arduino, Mediatek, Qualcomm;\nƯu tiên kinh nghiệm với AWS IoTCore, MQTT, Media Streaming, FOTA, Voice Recognition;\nNắm vững và sử dụng thành thạo C/C++ và Shell. Có khả năng lập trình Python là lợi thế;\nCó kiến thức và kinh nghiệm làm việc với Linux kernel, Drivers;\nCó khả năng làm việc độc lập và làm việc nhóm.\nKhả năng làm việc tốt trong môi trường tốc độ cao, quy trình quản lý Agile.\n\nQuyền lợi\nMức lương cạnh tranh thỏa thuận theo năng lực.\nThử việc hưởng 100% lương\nThời gian làm việc linh hoạt từ T2-T6\nMôi trường làm việc trẻ trung, năng động, tài năng\nMức lương cạnh tranh, Review tăng lương 2 lần/năm\nThưởng ngày Lễ/Tết, hiệu suất công việc, thưởng dự án theo tháng\nĂn chơi du lịch theo tháng + các hoạt động team building\nCó cơ hội được đào tạo phát triển và thăng tiến.\n\nĐịa điểm làm việc\nHà Nội: Số 9A Thanh Liệt, Thanh Trì\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2856, 1354, 2, 'Lập Trình Ứng Dụng', '- Lập trình, triển khai và bảo trì / vận hành các ứng dụng Websitres, di động, hệ thống phần mềm ERP... dựa trên phân tích thiết kế\n- Cập nhật và bố trí nội dung trên các ứng dụng Websites, di động, hệ thống phần mềm ERP cũng như các yêu cầu khác liên quan đến lập trình\n- Trực tiếp làm việc với người dùng chính để tiếp nhận yêu cầu phát triển chức năng và cài đặt những tính năng mới cho các ứng dụng\n- Hỗ trợ người sử dụng khắc phục lỗi của ứng dụng liên quan đến code của phần mềm theo quy trình hoạt động của Phòng IT\n- Lập trình hoặc phát triển các ứng dụng khác theo yêu cầu thực tế từ Công ty\n- Thực hiện một số công việc phát sinh khác theo phân công từ Quản lý trực tiếp trong từng thời điểm.\n\nĐịa điểm làm việc: 12 Nguyễn Hiền, Phường 4, Quận 3, Tp.HCM.\n\nYêu cầu ứng viên:\n- Nam / Nữ có sức khỏe tốt, ngoại hình cân đối và dễ nhìn\n- Tốt nghiệp Cao đẳng trở lên chuyên ngành CNTT phần mềm\n- Kinh nghiệm 2 năm trở lên tại vị trí tương đương, ưu tiên biết ngôn ngữ lập trình C#\n- Có kiến thức về thiết kế Cơ sở dữ liệu, SQL Reporting Service (SSRS) trên môi trường Microsoft SQL Server\n- Có kiến thức cơ bản về HTML / HTML5 / CSS, MVC3, Webservices, Javascript (JQuery, JSON)\n- Kỹ năng phân tích, xử lý vấn đề trên hệ thống\n- Năng động, khéo léo và khả năng chịu được áp lực công việc cao.\n\nQuyền lợi:\n- Thử việc: 02 tháng (100% Lương)\n- Lương cạnh tranh theo năng lực\n- Lương tháng 13 và Thưởng cuối năm theo hiệu quả công việc và kết quả kinh doanh Công ty\n- Tham gia BHXH và Bảo hiểm Sức khỏe theo chính sách Công ty\n- Khám sức khỏe định kỳ, hoạt động Team Building, du lịch hàng năm.\n- Chế độ và phúc lợi khác mang đến nhiều quyền lợi hữu ích cho nhân viên\n- Chính sách Đào tạo mang đến cơ hội trải nghiệm và phát triển nghề nghiệp\n- Thời gian làm việc: từ thứ 2 đến thứ 6 hàng tuần\n- Nghỉ chế độ, Phép năm, các ngày Lễ / Tết theo quy định.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2857, 1310, 2, 'Lập Trình Viên MasterCam', 'Mô tả công việc\n- Sử dụng thành thạo phần mềm Mastercam để lập trình gia công cho máy CNC (Phay/ Tiện).\n- Phân tích bản vẽ kỹ thuật, đọc hiểu yêu cầu kỹ thuật từ bộ phận thiết kế.\n- Thiết kế đường chạy dao, chọn dụng cụ cắt và thông số gia công tối ưu.\n- Mô phỏng chương trình, kiểm tra lỗi va chạm, đảm bảo an toàn và độ chính xác trước khi chuyển sang sản xuất.\n- Phối hợp với bộ phận vận hành máy để hiệu chỉnh chương trình khi cần thiết.\n- Cải tiến chương trình nhằm tăng năng suất, giảm thời gian gia công và hao mòn dao cụ.\n- Chế tạo đồ gá và công cụ hỗ trợ gia công khi gặp những chi tiết phức tạp.\n- Quản lý và lưu trữ dữ liệu chương trình, bản vẽ, tài liệu kỹ thuật có liên quan.\n- Hỗ trợ đào tạo và hướng dẫn kỹ thuật cho nhân viên vận hành máy (nếu cần).\n- Thực hiện các công việc khác theo sự phân công của quản lý.\n\nYêu cầu ứng viên\n- Tốt nghiệp Trung cấp, Cao đẳng, Đại học chuyên ngành Cơ khí chế tạo máy, Cơ điện tử hoặc tương đương.\n- Kinh nghiệm: Tối thiều 2 năm kinh nghiệm lập trình Mastercam (ưu tiên ứng viên từng làm trong lĩnh vực gia công khuôn mẫu, chi tiết cơ khí chính xác).\n- Thành thạo phần mềm Mastercam (phiên bản X8 trở lên), biết sử dụng thêm các phần mềm hỗ trợ như SolidWorks, AutoCAD là lợi thế.\n- Có kiến thức tốt về công nghệ cắt gọt kim loại, vật liệu gia công, dụng cụ và thông số cắt.\n- Đọc hiểu bản vẽ kỹ thuật cơ khí tiêu chuẩn ISO/JIS.\n\nQuyền lợi\n- Thu nhập hấp dẫn: Lên đến 18.000.000 triệu/tháng\n- Thời gian làm việc: từ Thứ 2 đến Thứ 6 (7h30-16h30); Thứ 7 làm luân phiên.\n- Được hỗ trợ cơm trưa tại văn phòng\n- Thưởng lương tháng 13, lễ tết, thưởng đột xuất, quà thiếu nhi 1/6,...\n- Được hưởng các chính sách phúc lợi: khám sức khỏe định kỳ hằng năm, sinh nhật cá nhân, hiếu hỉ, Team-building hằng năm và các hoạt động tập thể... do công ty tổ chức.\n- Tham gia đầy đủ BHXH, BHYT, BHTN, BH tai nạn 24/24 và BHSK.\n- Lương cạnh tranh theo năng lực và được xét tăng lương mỗi năm 1 lần (dựa trên kết quả hoạt động kinh doanh của cty).\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Lô IV-19 (KCN Tân Bình) Đường Tây Thạnh, Phường Tây Thạnh, Tân Phú\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 07:30 đến 16:30)\n- Nghỉ thứ 7 cách tuần\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2858, 1384, 2, 'Backend Developer (C#/.NET) (Domain Fintech)', 'Mô tả công việc:\n- Tham gia phát triển các dự án về giao dịch ngoại hối cho các ngân hàng và hệ thống CCS/IRS.\n- Tham gia vào toàn bộ vòng đời của sản phẩm bao gồm thiết kế database, định nghĩa interface, coding, triển khai dịch vụ lên các môi trường được cấp phát.\n- Tham gia phát triển các module backend của ứng dụng, cùng nghiên cứu, tìm giải pháp cho các yêu cầu mới.\n- Nghiên cứu, tìm hiểu các công nghệ mới để áp dụng cải thiện sản phẩm.\n\nYêu cầu ứng viên:\n- Tối thiểu 03 năm kinh nghiệm.\n- Có kiến thức xây dựng RESTful APIs.\n- Có kinh nghiệm với các dự án phần mềm sử dụng .NET, .NET Core.\n- Có kinh nghiệm làm việc, triển khai dự án với message broker (RabbitMQ).\n- Có hiểu biết và có kinh nghiệm với MySQL, SQL Server/Oracle, Redis, có kiến thức vững chắc về thiết kế Database.\n- Có kinh nghiệm làm việc trên môi trường Linux, Docker.\n- Có hiểu biết về tài chính, giao dịch ngoại hối là một lợi thế.\n\nQuyền lợi:\n- Thỏa thuận lương theo năng lực, upto 35M Net.\n- 100% lương trong thời gian thử việc.\n- Xét tăng lương 2 lần/năm.\n- Thưởng tháng lương 13, thưởng hiệu suất, thưởng Lễ Tết, thưởng sinh nhật,...\n- Bảo hiểm xã hội, Bảo hiểm Y tế, Bảo hiểm thất nghiệp khi trở thành nhân sự chính thức.\n- Chế độ ốm đau, hiếu hỷ, khuyến khích tài năng trẻ,...\n- Môi trường trẻ trung năng động và đầy nhiệt huyết.\n- Thời gian làm việc linh hoạt.\n- Được đào tạo 1-1 với Quản lý hoặc Senior.\n- Du lịch nghỉ mát hàng năm, nhiều hoạt động teambuilding.\n- Hỗ trợ hoạt động CLB như Cầu lông, Yoga, Đá bóng, Bơi-Đạp-Chạy,...\n\nĐịa điểm làm việc:\n- Hà Nội: 106 Hoàng Quốc Việt, Cầu Giấy\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2859, 1125, 2, 'Lập Trình Viên Backend', 'Mô tả công việc\n- Tham gia phát triển và duy trì hệ thống back-end cho các dự án phần mềm hỗ trợ đầu tư chứng khoán, đào tạo trực tuyến và các lĩnh vực khác mà công ty đang mở rộng.\n- Thiết kế, xây dựng và tối ưu hóa các API bảo đảm tính ổn định, hiệu suất và bảo mật.\n- Thu thập dữ liệu tự động từ các nguồn, chuẩn hóa và lưu trữ dữ liệu. \n- Phối hợp với nhóm front-end, QA, PM... trong quá trình phát triển và triển khai dự án.\n- Tham gia nghiên cứu, cập nhật các xu hướng công nghệ mới và ứng dụng vào sản phẩm.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các ngành liên quan; hoặc tốt nghiệp đại học ngành khác nhưng có tối thiểu 2 năm kinh nghiệm lập trình back-end.\n- Thành thạo ít nhất một ngôn ngữ/lộ trình back-end (Java, Node.js, Python, .NET, PHP, v.v.).\n- Có kinh nghiệm làm việc với cơ sở dữ liệu (SQL hoặc NoSQL).\n- Biết sử dụng các công cụ lập trình AI, biết sử dụng các cơ sởi dữ liệu phi truyền thống như Neo4j là lợi thế.\n- Ưu tiên ứng viên đã có kinh nghiệm tham gia dự án thực tế, đặc biệt là các dự án có yếu tố AI.\n- Tinh thần cầu tiến, có khả năng học hỏi nhanh và làm việc nhóm tốt.\n\nQuyền lợi\n- Được làm việc trong các dự án sáng tạo, có hàm lượng công nghệ cao, tiếp cận nhiều thách thức thú vị.\n- Có cơ hội nâng cao chuyên môn, kỹ năng nghiệp vụ và thăng tiến trong công việc.\n- Mức lương cạnh tranh, thưởng theo hiệu quả công việc và đóng góp.\n- Môi trường làm việc thân thiện, khuyến khích sự chủ động và sáng tạo.\n- Tham gia đầy đủ các chế độ bảo hiểm và các phúc lợi khác theo quy định công ty.\n\nĐịa điểm làm việc\n- Hà Nội: 37 Lê Văn Thiêm Phường Nhân Chính, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- 8h-17h, T7 ngày lẻ\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2860, 1286, 2, 'Unity Developer', 'Chúng tôi đang tìm kiếm một Unity Developer tài năng và đam mê game để gia nhập đội ngũ phát triển sản phẩm game của chúng tôi. Bạn sẽ làm việc trực tiếp với các đội ngũ thiết kế (GD), PO, Artist để phát triển các game Puzzle trên thị trường toàn cầu.\n\nTRÁCH NHIỆM VÀ CÔNG VIỆC CỦA BẠN LÀ:\n- Lập trình các tính năng trong game với Code rõ ràng, dễ đọc, tuân thủ quy chuẩn và hướng dẫn của nhóm phát triển.\n- Thực hiện công việc theo kế hoạch theo chu kỳ, đảm bảo tiến độ hoàn thành từng phần công việc trong thời gian quy định.\n- Hoàn thành mục tiêu công việc trong thời gian 2 tuần cho mỗi chu kỳ phát triển, với mục tiêu tiến bộ đều đặn trong quá trình xây dựng dự án.\n- Đảm bảo chất lượng công việc trong suốt quá trình phát triển và hoàn thiện sản phẩm.\n- Phối hợp hiệu quả với các thành viên trong nhóm để đạt được kết quả tốt nhất.\n- Đảm bảo chất lượng trò chơi, từ các khía cạnh kỹ thuật đến trải nghiệm người chơi.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành CNTT, kỹ thuật phần mềm hoặc các ngành liên quan.\n- Có 1 năm kinh nghiệm trở lên phát triển game với Unity\n- Có khả năng đưa ra hướng giải quyết nhanh, nhất là về thuật toán.\n- Thành thạo lập trình C# và hiểu biết sâu sắc về các tính năng của Unity.\n- Kinh nghiệm trong việc phát triển game cho các nền tảng mobile (iOS, Android).\n- Kiến thức về tối ưu hóa hiệu suất game và các kỹ thuật giảm tải tài nguyên.\n- Kinh nghiệm làm việc với các công cụ quản lý mã nguồn như Git.\n- Kỹ năng làm việc nhóm và giao tiếp hiệu quả.\n\nQuyền lợi:\n- Môi trường năng động, tinh gọn, hiệu quả với tầm nhìn và kế hoạch dài hạn.\n- Thưởng bonus theo sản phẩm.\n- Lương cạnh tranh theo thị trường.\n- Thời gian làm việc 7,5 giờ/ ngày, từ thứ 2 đến thứ 6\n- Không gian pantry thoải mái gồm: cafe, nước giải khát, bánh kẹo, thức ăn nhẹ.\n- Thư giãn tại văn phòng cùng board game, bida và bi lắc...\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tòa nhà Republic Plaza, 18e Cộng Hòa, Phường 4, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2861, 1191, 2, 'Frontend Developer', 'Tham gia phát triển giao diện người dùng cho các ứng dụng web theo yêu cầu của dự án.\nPhối hợp với Backend Developer, UI/UX Designer và các bộ phận khác để xây dựng sản phẩm có trải nghiệm người dùng tốt.\nTối ưu hiệu suất, tốc độ tải trang và khả năng tương thích trình duyệt.\nĐảm bảo chất lượng mã nguồn, tuân thủ tiêu chuẩn lập trình và quy trình CI/CD.\nNghiên cứu và áp dụng các công nghệ mới để nâng cao chất lượng sản phẩm.\n\nYêu cầu ứng viên\n\nBắt buộc:\nGHI RÕ ĐỊA ĐIỂM MONG MUỐN LÀM VIỆC TRÊN CV \nCó kinh nghiệm với một hoặc nhiều framework hiện đại như ReactJS, VueJS, Angular,...\nThành thạo HTML5, CSS3, JavaScript (ES6+).\nBiết sử dụng RESTful API và xử lý dữ liệu JSON.\nHiểu biết cơ bản về Git và quy trình làm việc với Git (pull request, merge, conflict resolution,...).\nCó kinh nghiệm với responsive design, cross-browser compatibility.\nKỹ năng giải quyết vấn đề, tư duy logic và teamwork tốt.\n\nƯu tiên (không bắt buộc):\nCó kinh nghiệm với TypeScript, Next.js, Tailwind CSS, hoặc SASS/SCSS.\nBiết sử dụng công cụ quản lý trạng thái như Redux, Pinia, Zustand,...\nHiểu biết về SEO, tối ưu hiệu suất frontend (Lighthouse, Core Web Vitals).\nCó kinh nghiệm làm việc theo mô hình Agile/Scrum.\n\nTrình độ:\nTốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT, Khoa học máy tính hoặc các ngành liên quan.\nHoặc có kỹ năng tương đương được chứng minh qua dự án cá nhân/thực tế.\n\nQuyền lợi\n\nThu nhập:  15 triệu – 25 triệu/tháng\nĐóng đầy đủ BHXH theo quy định của pháp luật \nThưởng các ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch, ...)\nNghỉ Lễ/Tết, 12 ngày phép/năm và nghỉ phép theo Quy định của Pháp luật hiện hành.\nCác chế độ phúc lợi khác theo quy định của Công ty;\nCung cấp thiết bị làm việc. \nMôi trường làm việc chuyên nghiệp, đồng nghiệp trẻ trung, năng động, tích cực\nĐược lựa chọn địa điểm làm việc:\n\nĐịa điểm 1: V1- A02 Khu đô thị mới An Hưng, Dương Nội, Hà Đông, Hà Nội\n\nĐịa điểm 2: TechnoPark Tower, xã Đa Tốn, Gia Lâm, Hà Nội (ưu tiên làm việc tại đây)\n\nĐịa điểm làm việc\n- Hà Nội: 1- A02 Khu đô thị mới An Hưng, Dương Nội, Hà Đông\n- Hà Nội: TechnoPark Tower, xã Đa Tốn, Gia Lâm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2862, 1266, 2, 'Software Developer (JLPT N3)', 'Toshiba Software Development (Vietnam), công ty trực thuộc & được đầu tư 100% bởi Toshiba Japan. Chúng tôi đang tìm kiếm những kỹ sư phát triển phần mềm có mong muốn & quyết tâm được phát triển thành Kĩ sư cầu nối (BrSe) chuyên nghiệp.\n\nKhi bạn gia nhập vị trí Software Engineer (JLPT N3), công việc của bạn sẽ bao gồm:\n- Được đào tạo bài bản để trở thành Kĩ sư cầu nối chuyên nghiệp\n- Tham gia vào dự án với vai trò tổng hợp domain dự án, truyền tải cho team dự án\n- Đóng vai trò là cầu nối trong giao tiếp, đề xuất với khách hàng về tất cả các vấn đề liên quan đến dự án\n\nYêu cầu ứng viên:\n- Đã tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm, Khoa học máy tính, Toán tin, Điện tử viễn thông…\n- Có ít nhất 3 năm kinh nghiệm làm việc trong phát triển phần mềm với 1 trong các công nghệ bất kỳ, như Java, JS, C++, .Net, Python…\n- Có tiếng Nhật JLPT từ N3. Có khả năng giao tiếp được với khách hàng\n- Mong muốn được phát triển theo hướng BrSe\n\nQuyền lợi:\n- Ứng viên sẽ được hưởng trọn quyền lợi như 1 thành viên của tập đoàn Toshiba, bao gồm:\n- Mức lương cạnh tranh. Thỏa thuận theo năng lực. Up to 1500$\n- Package lương up to 15 tháng/năm (bao gồm 2 lần thưởng Incentive/ năm, 1 lần thưởng Bonus)\n- Review lương hàng năm\n- Trợ cấp tiếng Nhật hấp dẫn, cạnh tranh top 1 trên thị trường\n- Bảo hiểm 100% lương, hưởng trọn quyền lợi, an tâm làm việc\n- Quy trình làm việc bài bản, chuyên nghiệp. Cơ hội làm việc với nhiều Seniors, Leaders trong ngành.\n- Nhiều cơ hội onsite tại Nhật\n\nĐịa điểm làm việc:\n- Hà Nội: VIT TOWER, 519 KIM MÃ, PHƯỜNG NGỌC KHÁNH, Ba Đình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2863, 1187, 2, 'Middle/Senior Fullstack (Java, Python & Frontend) Developer', 'Mô tả công việc:\n- Phát triển và duy trì các ứng dụng web với kiến trúc fullstack, sử dụng Java hoặc Python cho backend và các framework hiện đại cho frontend.\n- Thiết kế và xây dựng các RESTful API để giao tiếp giữa các dịch vụ.\n- Xây dựng giao diện người dùng động và phản hồi tốt bằng các framework như ReactJS, Angular hoặc VueJS.\n- Quản lý cơ sở dữ liệu quan hệ và/hoặc NoSQL (MySQL, PostgreSQL, MongoDB, Redis).\n- Đóng gói ứng dụng bằng Docker để đảm bảo môi trường phát triển và triển khai nhất quán.\n- Thiết lập và giám sát tình trạng hệ thống bằng các công cụ logging và alerting hiện đại.\n- Làm việc trong môi trường Agile/Scrum với các công cụ quản lý dự án như JIRA.\n- Phối hợp chặt chẽ với các team khác (BA, QA, DevOps, khách hàng...) để đảm bảo chất lượng và tiến độ sản phẩm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học, cao đẳng chuyên nghành Công nghệ thông tin, hoặc các chuyên ngành liên quan.\n- Có từ 3–6 năm kinh nghiệm phát triển phần mềm, trong đó ít nhất 2 năm kinh nghiệm với Java hoặc Python.\n- Thành thạo một trong các kết hợp công nghệ sau:\n+ Java (Spring Boot, v.v) + Frontend (ReactJS / Angular / Vue)\n+ Java + Python (Flask / FastAPI / Django)\n+ Python + Frontend (ReactJS / Angular / Vue)\n- Hiểu rõ về RESTful API, kiến trúc microservices, authentication/authorization.\n- Có kinh nghiệm làm việc với cơ sở dữ liệu quan hệ (MySQL, PostgreSQL) và/hoặc NoSQL (MongoDB, Redis).\n- Có kỹ năng viết unit test, sử dụng Git, CI/CD.\n- Kỹ năng giao tiếp và làm việc nhóm tốt.\n\nƯu tiên:\n- Có kinh nghiệm làm việc trong các dự án outsource hoặc khách hàng Hàn Quốc.\n- Có kinh nghiệm với DevOps (Docker, Kubernetes) là một lợi thế.\n- Kỹ năng làm việc nhóm tốt, chủ động và tinh thần trách nhiệm cao.\n- Ưu tiên ứng viên có khả năng giao tiếp tiếng Anh cơ bản trở lên.\n\nQuyền lợi:\n- Mức lương: Thỏa thuận theo năng lực khi phỏng vấn.\n- Chế độ phúc lợi:\n+ Lương tháng 13+ và xét tăng lương 2 lần/năm.\n+ Thưởng theo dự án, thưởng lễ/tết, thưởng giới thiệu nhân sự, thưởng hiệu quả công việc...\n+ Phụ cấp thâm niên từ 2 năm làm việc.\n+ Tham gia các hoạt động đào tạo nội bộ và bên ngoài, phát triển lộ trình nghề nghiệp rõ ràng.\n+ Nghỉ thứ 7, Chủ nhật và 12 ngày phép/năm.\n+ Tham gia các câu lạc bộ thể thao – văn hóa – nghệ thuật do công ty tài trợ (bóng đá, cầu lông, bơi lội, âm nhạc, game, tiếng Anh...).\n+ Chăm sóc sức khỏe: Khám sức khỏe định kỳ, bảo hiểm sức khỏe chất lượng cao Rikkei Care.\n+ Văn hoá thoải mái: Âm nhạc hàng ngày, trái cây tươi, team building thường xuyên, du lịch trong và ngoài nước.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy.\n\nThời gian làm việc:\n- Đăng ký linh hoạt 8:00 - 9:00 đến 17:00 - 18:00 từ Thứ 2 - Thứ 6.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2864, 1131, 2, 'Dev Fullstack', '1. Thiết kế, phát triển, triển khai và tối ưu hệ thống phần mềm:\n- Phân tích yêu cầu, vấn đề và rủi ro có thể phát sinh trong quá trình thực hiện yêu cầu.\n- Thiết kế tổng thể hệ thống, các module thành phần, các chức năng chi tiết\n- Lập trình phát triển, bảo trì các chức năng hệ thống phía backend.\n- Triển khai và tích hợp các thành phần hệ thống phía backend và frontend\n- Tối ưu các thành phần hệ thống phía backend: code, database.\n- Triển khai và vận hành ứng dụng trên docker, k8s...\n- Tham gia xây dựng pipeline thu thập, xử lý và phân tích dữ liệu từ các thiết bị network, server trong Data center.\n- Xây dựng thuật toán giúp tối ưu cho việc xuất kho, điều chuyển hàng hoá phục vụ xây lắp công trình, trạm.\n\n2. Hợp tác và chia sẻ\n- Hợp tác với các thành viên trong dự án để thiết kế API phù hợp với yêu cầu của tính năng.\n- Chia sẻ kiến thức, công nghệ với các thành viên trong nhóm.\n- Review code giữa các thành viên trong dự án và code của đối tác.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm Fullstack.\n- Hiểu rõ về API RESTful, tích hợp frontend-backend, và các best practice trong phát triển web hiện đại.\n- Kiến thức vững chắc về lập trình hướng đối tượng (OOP), kiến trúc MVC, và các mẫu thiết kế phần mềm.\n- Tư duy logic, khả năng phân tích và giải quyết vấn đề hiệu quả.\n- Tính cách cẩn thận, siêng năng, chịu khó, và có thể theo đuổi các nhiệm vụ dài hạn một cách kiên trì.\n- Thành thạo công cụ quản lý mã nguồn (Git) và theo dõi công việc (Jira, Trello...).\n- Có kinh nghiệm hoặc hiểu biết về quy trình CI/CD, DevOps.\n\nQuyền lợi:\n- Mức lương cạnh tranh, 13 tháng lương.\n- Cung cấp Laptop/ PC.\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN).\n- Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau.\n- Nghỉ Thứ 7, Chủ nhật, 12 ngày phép/ năm.\n- Phụ cấp gửi xe; ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc.\n- Phụ cấp cơm trưa, bảo hiểm sức khỏe, khám sức khỏe định kỳ 1 lần/năm, du lịch nghỉ mát 1 lần/ năm.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban.\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, ...\n- Cơ hội thăng tiến vào các vị trí quản lý công nghệ cấp cao đối với những thành viên xuất sắc.\n- Review tăng lương định kỳ hàng năm.\n\nĐịa điểm làm việc:\n- Hà Nội: 19-21 Vũ Trọng Phụng, Thanh Xuân Trung, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2865, 1214, 2, 'Chuyên Gia/CVCC Hỗ Trợ Phát Triển Ứng Dụng', 'Mô tả công việc:\n- Lập trình và phát triển các hệ thống và ứng dụng của Công ty Tài chính.\n- Phát triển hoặc phối hợp với các nhà cung cấp để phát triển và triển khai các giải pháp công nghệ thông tin.\n- Quản lý và phát triển các dịch vụ tích hợp với các hệ thống cốt lõi như: T24,LOS,CRM,CIC,...\n- Duy trì hoạt động các phần mềm trong phạm vi quản lý.\n- Nghiên cứu, thử nghiệm, triển khai và ứng dụng các xu hướng công nghệ mới trong phát triển: GraphQL, Docker Container (K8s), CICD, EventSourcing, CQRS, NoSQL...\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học trở lên các chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Phần mềm\n- Có ít nhất 3 năm với việc phát triển các dự án thực tế trong quá trình đi làm.\n- Có khả năng hiểu và giao tiếp Tiếng anh cơ bản.\n- Thành thạo ít nhất 01 ngôn ngữ BackEnd: Java, NodeJS,.. và các framwork kèm theo như SpringBoot, SpringCloud, SpringSecurity, NestJs, Express,.. và 1 trong các framework FrontEnd (ví dụ: Next, Angularjs, ReactJS).\n- Có kinh nghiệm về SOLID, Design Pattern, Microservices, Monolithic Architecture, ... là một lợi thế.\n- Ưu tiên có kinh nghiệm về CI/CD, nền tảng ghi logs, nền tảng giám sát.\n- Quen thuộc với các frameworks kiểm thử như Vitest và Jest.\n- Nắm vững kiến thức khoa học máy tính (lập trình OOP, Cấu trúc dữ liệu & Thuật toán).\n- Hiểu biết về JPA/ORM, Hibernate, ..Sử dụng các công nghệ như Kafka, Elasticsearch, Redis, Cassandra, .v.v. là một lợi thế.\n- Có kỹ năng lập trình tốt như: phân tích và đưa ra giải pháp để giải quyết vấn đề.\n- Thành thạo ít nhất một trong các loại cơ sở dữ liệu sau: Oracle, SQL server, PostgreSQL, Mongodb...\n- Có thể sử dụng asynchronous (JS) hoặc multithread (Java) để cải thiện năng xuất.\n- Có kiến thức Linux OS, Docker hoặc kinh nghiệm DevOps với Kubernetes, Terraform, v.v. là một lợi thế.\n- Có kinh nghiệm phát triển và sử dụng công nghệ đám mây (GCP, AWS) là một lợi thế.\n- Có kinh nghiệm trong lĩnh vực ngân hàng, tài chính là một lợi thế.\n- Có khả năng dẫn dắt, đào tạo thành viên nhóm và bổ sung các kỹ năng như kiểm thử, quản lý dự án, v.v. là một lợi thế.\n\nQuyền lợi:\n- 2 tháng thử việc 100% lương.\n- Phụ cấp ăn trưa.\n- Hưởng đầy đủ các chế độ đãi ngộ theo quy định của pháp luật: BHYT, BHXH, BHTN.\n- Khám sức khỏe định kỳ hàng năm, chương trình Bảo hiểm sức khỏe cao cấp (PVI) theo cấp bậc và thâm niên.\n- Tối thiểu 13 tháng lương, thưởng theo kết quả kinh doanh, thưởng các dịp đặc biệt, các ngày lễ lớn.\n- Được tham gia các chương trình đào tạo để nâng cao nghiệp vụ.\n\nĐịa điểm làm việc:\n- Hà Nội: số 03 Đặng Thái Thân, Hoàn Kiếm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2866, 1398, 2, 'Python Developer', 'Mô tả công việc: Tham gia thiết kế và phát triển API cho các ứng dụng quản lý nhân sự HRM. Xây dựng và tối ưu hóa các API, Microservices. Nghiên cứu, học hỏi các công nghệ mới phục vụ nhu cầu dự án. Thực hiện các công việc khác theo yêu cầu của quản lý sản phẩm.\nYêu cầu ứng viên: Tốt nghiệp các trường chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin. Có ít nhất 2 năm kinh nghiệm & thành thạo ngôn ngữ lập trình Python. Có ít nhất 1 năm với một trong các framework Python như: FastAPI, Flask, Django. Có kinh nghiệm làm việc với các hệ cơ sở dữ liệu: PostgreSQL, MongoDB, MySQL. Có kinh nghiệm làm việc với hệ thống message queue như Celery, Redis Queue. Hiểu biết về các kiến trúc phát triển phần mềm: Microservices, Monolithic. Thành thạo công cụ quản lý mã nguồn Git. Viết tài liệu cho API. Sử dụng các công cụ như JIRA, Clickup hoặc Redmine để quản lý công việc. Đam mê, chủ động trong công việc, có kỹ năng làm việc nhóm và làm việc độc lập. Có khả năng quản lý, sắp xếp, điều phối và đốc thúc công việc. Có khả năng đọc hiểu các tài liệu bằng tiếng Anh. Ưu tiên các ứng viên trẻ từ 2000.\nQuyền lợi: Mức lương thỏa thuận, được trả theo năng lực thực tế. Được tham gia vào môi trường văn hóa năng động, chuyên nghiệp. Hưởng đầy đủ các chế độ theo Luật Lao Động: Nghỉ lễ, tết, phép năm, hiếu, hỷ. Tham gia BHXH - BHYT - BHTN theo quy định của Nhà nước, bảo hiểm tai nạn UIC, bảo hiểm sức khỏe PTI. Được chăm sóc tiếp sức với tủ thức ăn đầy ắp vào cuối tháng. Được cấp phát Laptop, đồng phục thực hiện công việc. Có lộ trình thăng tiến rõ ràng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2867, 1447, 2, 'Embedded Software Engineer', 'ABOUT THE JOB\n- Design and implement embedded software for appliances\n- Analyze and review software requirement specifications\n- Develop unit and integration test cases based on requirements\n- Execute tests, retests, and regression tests on embedded systems\n- Debug software issues and perform root cause analysis\n- Conduct code reviews and maintain high coding standards\n- Document and archive software and test artifacts\n- Create and manage bug reports and monitor defect resolutions\n- Identify and apply suitable tools for testing automation and CI/CD\n- Collaborate with cross-functional teams and stakeholders\n\nABOUT YOU\n- Academic background: Degree in Software Engineering, Computer Science, or Electrical Engineering\n- For Embedded Tester: 3+ years of experience with software testing for embedded systems and testing tools (Python, Pytest, Git, Jira, Confluence, Polarion, Teamcenter, Artifactory, PyCharm, Enterprise Architect)\n- For Embedded Developer: 3+ years of experience with embedded software development and C++\n- Strong knowledge of embedded Linux and system architecture\n- Familiarity with UML for software design\n- Hands-on experience with CI/CD tools: Jenkins, GitHub\n- Good communication skills in English\n- You have an ability to synthesize complex information and work collaboratively in an agile environment\n\nWHY AMARIS?\n- Competitive salary and 13th-month salary\n- 14+ annual leaves per year\n- Premium healthcare insurance, starting from your probation period\n- Project reviews and yearly performance appraisals\n- Annual company trips\n- Teambuilding activities: Team lunch/dinner, events, and celebrations, sports clubs (football, yoga, badminton, etc.)\n- International team with flexible working time\n- Tailor-made career path\n- Technical workshops and training courses\n- Mobility: Opportunities to be on-site abroad in our offices in over 60+ countries\n\nEqual Opportunity\nAmaris Consulting is proud to be an equal opportunity workplace. We are committed to promoting diversity within the workforce and creating an inclusive working environment. For this purpose, we welcome applications from all qualified candidates regardless of gender, sexual orientation, race, ethnicity, beliefs, age, marital status, disability, or other characteristics.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2868, 209, 2, 'RTOS Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\nAs a Smart Meter Software Development Engineer, you will work on critical projects in developing software for smart meter systems using FreeRTOS. You will play an instrumental role in two primary projects:\n• AT Command Development: Designing, implementing, and testing AT command capabilities to support smart meter functionalities and communication interfaces.\n• DLMS Protocol Implementation: Developing and optimizing software modules for DLMS (Device Language Message Specification) protocol to ensure secure and efficient data exchange in smart meter systems.\n\nAdditional responsibilities include:\n• Integrating and optimizing FreeRTOS for smart meter applications, focusing on real-time performance and resource efficiency.\n• Troubleshooting, debugging, and maintaining high-performance, scalable code for smart meters.\n• Collaborating with cross-functional teams to align software functionalities with hardware capabilities and project requirements.\n• Documenting software architecture and processes to support smooth project management and ensure high standards.\n\nYêu cầu ứng viên\n• Operating System: Strong expertise in FreeRTOS for real-time, embedded applications.\n• Platform: STM32\n• AT Command Parser: Experience in developing and parsing AT commands.\n• DLMS Protocol: Solid understanding and experience with the DLMS protocol for secure data exchange in smart metering.\nLanguages\n• C/C++\n\nQuyền lợi\n• Salary range: $2000 - $3500 \n• FPT Care insurance plan tailored for FPT employees\n• Attractive annual summer vacation allowance\n• Sponsored training courses for personal growth and up to 100% coverage for certification costs\n• Global and inclusive workplace with monthly cross-cultural events\n• International exposure and career growth across global locations\n• Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\n\nĐịa điểm làm việc\n- Hà Nội: FPT Building, 17 Duy Tân Str., Cầu Giấy District, Hanoi, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2869, 1359, 2, 'Lập Trình Viên Fullstack (Angular, Laravel, PHP)', 'Mô tả công việc:\n1. Tham gia bảo trì, tối ưu hóa hiệu năng và phát triển mở rộng hệ thống hiện có sử dụng Laravel và Angular.\n2. Phối hợp với BA (Chuyên viên phân tích nghiệp vụ) và khách hàng để phân tích yêu cầu nâng cấp hệ thống.\n3. Phát triển tính năng mới hoặc cải tiến các chức năng hiện tại theo yêu cầu và thiết kế kỹ thuật.\n4. Làm việc chặt chẽ với các nhóm kiểm thử chất lượng (QC), DevOps và các nhóm phát triển khác để đảm bảo chất lượng mã nguồn, tính ổn định của hệ thống và tiến độ triển khai.\n5. Tham gia sửa lỗi, đảm bảo hệ thống hoạt động ổn định trên môi trường thực tế.\n6. Viết mã nguồn sạch sẽ, dễ bảo trì, và dễ kiểm thử theo các tiêu chuẩn và best practices hiện hành.\n7. Góp phần vào các buổi thảo luận kỹ thuật, review mã nguồn, và định hướng kiến trúc hệ thống.\n\nYêu cầu ứng viên:\n-Tối thiểu 3 năm kinh nghiệm làm việc với Laravel (PHP) và Angular (Angular.io).\n-Hiểu rõ về API RESTful, tích hợp frontend-backend, và các best practice trong phát triển web hiện đại.\n-Kiến thức vững chắc về lập trình hướng đối tượng (OOP), kiến trúc MVC, và các mẫu thiết kế phần mềm.\n-Tư duy logic, khả năng phân tích và giải quyết vấn đề hiệu quả.\n-Tính cách cẩn thận, siêng năng, chịu khó, và có thể theo đuổi các nhiệm vụ dài hạn một cách kiên trì.\n-Kỹ năng giao tiếp tốt, có thể phối hợp làm việc nhóm hiệu quả.\nƯu tiên (nice to have):\n-Có kinh nghiệm hoặc có khả năng đọc hiểu hệ thống backend Java, đặc biệt là Spring Boot.\n-Từng làm việc với hệ thống quy mô lớn, có lượng truy cập cao.\n-Thành thạo công cụ quản lý mã nguồn (Git) và theo dõi công việc (Jira, Trello...).\n-Có kinh nghiệm hoặc hiểu biết về quy trình CI/CD, DevOps.\n\nQuyền lợi:\n-Mức lương và thưởng hấp dẫn\n-12 ngày nghỉ phép năm\n-Được tham gia đầy đủ bảo hiểm xã hội và bảo hiểm y tế theo quy định của nhà nước\n-Các khoản phụ cấp hấp dẫn (thưởng onsite, gửi xe, sinh nhật, happy hours, v.v.)\n-Xét duyệt tăng lương hàng năm dựa trên hiệu suất và đóng góp của nhân viên\n-Môi trường làm việc thực sự cởi mở. Mọi người đều được tôn trọng và bạn có quyền tự do theo đuổi cũng như đạt được mục tiêu của mình\n-Các quyền lợi khác theo quy định của Bộ luật Lao động Việt Nam.\n\nĐịa điểm làm việc:\n-Hà Nội: Tòa nhà Capital Place 29 đường Liễu Giai, Ngọc Khánh, Ba Đình\n\nThời gian làm việc:\n-Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n-Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2870, 1364, 2, 'Senior Software Engineer', 'Mô tả công việc:\n- Tiếp nhận và đánh giá hệ thống phần mềm hiện tại (được phát triển bởi đối tác bên ngoài) để đảm bảo phù hợp với quy trình và nhu cầu vận hành nội bộ.\n- Thực hiện điều chỉnh, cải tiến kiến trúc hệ thống, mã nguồn và dữ liệu theo định hướng phát triển lâu dài của công ty.\n- Xây dựng và chuẩn hóa tài liệu kỹ thuật, quy trình triển khai, quản lý source code và vận hành hệ thống.\n- Đầu mối kỹ thuật, phối hợp với các phòng ban để tiếp nhận phản hồi và đề xuất giải pháp cải tiến hệ thống.\n- Trực tiếp sửa chữa hoặc hỗ trợ team xử lý các thay đổi, lỗi phát sinh, tối ưu hiệu suất hệ thống bằng các công nghệ: ReactJS, NestJS, NextJS.\n- Quản lý, vận hành cơ sở dữ liệu SQL / NoSQL, giám sát hệ thống server và bảo mật trên nền tảng Linux.\n- Thực hiện các nghiệp vụ liên quan hệ thống mạng, email, máy tính, server, phần mềm nội bộ.\n- Thực hiện các nhiệm vụ khác được cấp trên phân công.\n\nYêu cầu ứng viên:\n- Có tối thiểu 5 năm kinh nghiệm trong lĩnh vực phát triển phần mềm, trong đó ít nhất 2 năm kinh nghiệm ở vai trò Lead/Tech Lead.\n- Thành thạo ReactJS, NestJS, NextJS – có khả năng đọc hiểu, phân tích và refactor mã nguồn đã có sẵn.\n- Có kinh nghiệm thực tế với cơ sở dữ liệu SQL và NoSQL (ví dụ: MySQL, PostgreSQL, MongoDB...).\n- Có hiểu biết và kinh nghiệm triển khai/vận hành trên môi trường Linux server.\n- Tư duy hệ thống tốt, có khả năng đánh giá kiến trúc phần mềm, đề xuất giải pháp cải tiến phù hợp với thực tế doanh nghiệp.\n- Có khả năng quản lý công việc, tổ chức tài liệu, quy trình, và xây dựng tiêu chuẩn kỹ thuật nội bộ.\n- Giao tiếp Tiếng Anh.\n\nQuyền lợi:\n- Thu nhập: Cạnh tranh theo năng lực\n- 05 ngày làm việc/tuần với 8h/ngày\n- 100% lương trong thời gian thử việc.\n- Xét lương hàng năm\n- 12 ngày phép năm + 01 ngày nghỉ lễ công ty + 0.5 ngày nghỉ sinh nhật\n- Được tham gia đóng BHXH, BHYT theo quy định của nhà nước\n- Môi trường làm việc trẻ trung, năng động\n- Hoạt động team building, du lịch…\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 5 Lotte Mall Võ Chí Công, Tây Hồ\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2871, 1235, 2, 'Kỹ Sư Cơ Khí', 'Mô tả công việc:\n- Thiết kế và lập trình các chương trình điều khiển cho máy móc, thiết bị tự động hóa trong lĩnh vực cơ khí.\n- Phát triển và tối ưu hóa các thuật toán điều khiển, đảm bảo hiệu suất và độ chính xác cao.\n- Lập trình và tích hợp các thiết bị ngoại vi (sensor, actuator) vào hệ thống điều khiển.\n- Viết tài liệu kỹ thuật, hướng dẫn sử dụng cho các chương trình đã lập trình.\n- Hỗ trợ kỹ thuật cho quá trình sản xuất, bảo trì và sửa chữa máy móc.\n- Cập nhật và nâng cấp các hệ thống điều khiển hiện có.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Cơ khí, Tự động hóa, Điện tử viễn thông hoặc các chuyên ngành liên quan.\n- Không yêu cầu kinh nghiệm.\n- Có kiến thức cơ bản về điện tử, cơ khí và lập trình.\n- Có khả năng đọc hiểu bản vẽ kỹ thuật.\n- Khả năng làm việc độc lập và làm việc nhóm.\n- Cẩn thận, tỉ mỉ, chịu được áp lực công việc.\n- Kỹ năng giao tiếp tốt và khả năng giải quyết vấn đề.\n\nQuyền lợi:\n- Mức lương cạnh tranh, tương xứng với năng lực và kinh nghiệm.\n- Chế độ bảo hiểm đầy đủ theo luật lao động.\n- Được tham gia các khóa đào tạo nâng cao nghiệp vụ.\n- Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.\n- Thưởng các ngày lễ, tết và các hoạt động team building.\n\nĐịa điểm làm việc:\n- Hải Phòng: An Đồng - An Dương, An Dương\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 07:30 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2872, 756, 2, 'Junior IOS Developer (Thu Nhập Từ 12 - 25 Triệu)', 'Mô tả công việc:\n- Phát triển ứng dụng, module ứng dụng iOS theo phân phối của Team Leader\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động theo phân phối của team leader.\n- Phối hợp với Mid Level/Senior Developer thực hành code review\n- Phối hợp với các team liên quan vận hành dự án theo quy trình.\n- Được tự do nghiên cứu công nghệ mới và đề xuất ý tưởng sáng tạo để nâng cao chất lượng dự án\n\nYêu cầu ứng viên:\n- Có kinh nghiệm lập trình iOS 1-2 năm\n- Nắm được khái niệm iOS cơ bản (UI Kit, Resource, Storage, Network Handling)\n- Đã từng sử dụng một trong các kiến trúc MVP, MVVM\n- Hiểu biết Design Pattern là một lợi thế\n- Có khả năng dựng module độc lập là một lợi thế\n- Am hiểu Agile Scrum là một lợi thế\n- Đam mê, chủ động công việc, có kỹ năng làm việc nhóm, làm việc độc lập.\n- Có kỹ năng làm việc nhóm/theo quy trình là một lợi thế\n\nQuyền lợi:\n- Mức lương hấp dẫn từ 12.000000 - 25.000.000VNĐ.\n- Cơ chế đãi ngộ tập trung vào phát triển nhân tài và xây dựng theo concept gia tốc: Nhân sự Top đầu tăng lương gấp 6 lần nhân sự Top dưới.\n- Thưởng 3-5 tháng lương 1 năm với nhân sự Top đầu.\n- Bổ nhiệm ngay khi có chiến công đặc biệt.\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN.\n- Các gói bảo hiểm ngoài BHXH: Bảo hiểm PTI, khám sức khỏe định kỳ hàng năm\n- Văn hóa làm việc GenZ,môi trường làm việc trẻ trung, sáng tạo, Dám nghĩ - dám làm, trà đá, bàn tròn, ném đá sếp, áp dụng triệt để văn hóa 6K startup, TSB3C.\n- Du lịch hàng năm, team building, tea break hàng tuần\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Taisei 289 Khuất Duy Tiến, Trung Hòa, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\n- 8:30 - 18:00, nghỉ trưa 1h30’, làm việc từ Thứ 2 - Thứ 6\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2873, 68, 2, 'Frontend Developer', 'Mô tả công việc\n- Use best practices and technologies to develop large SPAs for various users and platforms.\n- Ensure high-quality, performant, and reusable code.\n- Perform benchmarking, performance, and security analysis.\n- Work closely with the backend teams and product design team to iterate quickly on new features and experiments.\n- Accurately translate user and business needs into functional front-end code.\n- Drive the efficient delivery of change through analysis, definition, and documentation of requirements whilst identifying potential solutions using agile delivery frameworks.\n- Solve complex technical and business problems and learn new technology and frameworks.\n- Be part of a team that will take full responsibility for the features you own.\n- Design, develop, test, deploy, monitor, and improve; you are responsible for the entire lifecycle of your product – build it, own it.\n\nYêu cầu ứng viên\nMust Have:\n- 3++ years of experience programming with HTML, CSS, JavaScript, ReactJS.\n- Experience in responsive web and mobile-first applications.\n- Experience with ReactJS, and its ecosystem (Hooks, Context, Redux, Redux Saga, State Management libraries...)\n- Familiar with CSS Frameworks like Material UI, TailwindCSS, Ant Design,...\n- Familiarity with RESTful APIs and asynchronous request handling for partial page updates.\n- Be able to write clean, performance-centric, reusable, and understandable code with unit tests.\n- Familiarity with browser testing and debugging.\n- Hands-on experience with Git.\n- Be structured, solution-oriented, own quality mindset, good problem-solving skills, eagerness to learn, and curiosity.\n- Have good communication skills, have experience with technical coaching and mentoring work.\n- Good command of English (Listening, Reading, Writing).\n\nNice to Have:\n- Previous product company experience.\n- Experience in building mobile application by React Native.\n- Familiar with Agile development methods, especially Scrum.\n- Familiarity with ECMAScript 6, TypeScript.\n- Experience in building JavaScript SDKs, Web Widgets, and unit testing.\n- Expertise in web optimization, security, and user behavior tracking.\n- Experienced in unit tests, automated test frameworks is a plus.\n- Experience with micro-frontend is a plus.\n- Good understanding on how browser rendering works and provide various frontend rendering optimization strategies.\n- Familiarity with UI/UX design principles.\n- Awareness of best practices in UI/UX design and development to ensure optimal user experience.\n\nQuyền lợi\n- Salary for Position 3P: 20M+++ VND/month;\n- Bonus for Position 4:\n- End-of-year bonus (depending on the company\'s business performance at the time;\n- Benefits: Welfare package of 10,500,000 VND/year, Employee welfare policies.\n- Performance bonuses for creativity, achievements, and other types of rewards;\n- Social Insurance and other regimes according to regulations;\n- Participating in training courses according to your requirements;\n- Working in a professional, creative and open-minded environment with many job advancement opportunities;\n- Working time: From 8:45 AM to 6:00 PM, Monday to Friday, at the office. On alternating Saturdays, work is flexible and can be done either remotely or on-site.\n- Working place: 15th floor, Ngoc Khanh Plaza Building - No.1 Pham Huy Thong, Ngoc Khanh Ward, Ba Dinh District, Hanoi.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2874, 1273, 2, 'React Native Developer', 'Mô tả công việc\n- Tham gia xây dựng và phát triển các tính năng mới cho các ứng dụng mobile trên nền tảng React Native, Flutter\n- Nâng cấp các phần mềm hiện có\n- Bảo trì các hệ thống đã triển khai\n- Tham gia nghiên cứu công nghệ mới đáp ứng yêu cầu dự án\n- Các công việc được giao từ quản lý trực tiếp.\n\nYêu cầu ứng viên\n- Tốt nghiệp chuyên ngành CNTT hoặc có liên quan\n- Có ít nhất 03 năm kinh nghiệm làm việc về React-Native, Redux, Flutter\n- Có kinh nghiệm làm việc với Restful API, Firebase, Redux, Socket, Push Notification, Reanimated\n- Có kiến thức về IOS và Android. Đã từng tham gia, giải quyết các vấn đề liên quan native ios, android\n- Cẩn thận, kiên nhẫn và có khả năng nghiên cứu công nghệ mới đáp ứng yêu cầu dự án\n- Biết ReactJS, SpringBoot là một lợi thế\n- Có mong muốn gắn bó lâu dài\n\nQuyền lợi\n- Mức lương hấp dẫn: Up to 35.000.000VND\n- Có cơ hội đi công tác Nhật Bản, trải nghiệm thực tế nghiệp vụ phía khách hàng\n- Được tham dự các chương trình, hỗ trợ trong việc định hướng phát triển nghề nghiệp\n- Thưởng lương tháng 13, thưởng Lễ - Tết, sinh nhật, thưởng kinh doanh tùy vào hoạt động của công ty\n- Được khám sức khỏe định kỳ, nghỉ mát hàng năm, hoạt động team building\n- Được hưởng bảo hiểm theo chế độ nhà nước ban hành\n- Môi trường làm việc chuyên nghiệp, trẻ trung và thân thiện.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2875, 71, 2, 'Junior IOS Developer (Upto 1000$)', 'Mô tả công việc:\nTham gia phát triển các ứng dụng liên quan đến tài chính trên iOS.\nTham gia cài đặt, viết unit test, review mã nguồn của các thành viên trong team.\nNghiên cứu và ứng dụng các công nghệ mới vào phát triển sản phẩm.\nHỗ trợ deploy trên môi trường Development, Stagging, Production.\nLàm việc với các đối tác tại nhiều quốc gia trên thế giới như Singapore, Nhật Bản, Hongkong... để trao đổi về dự án.\nBáo cáo kết quả công việc cho PM.\n\nVề dự án POEMS: Tiếp nối lịch sử 30 năm thành công của Poems, siêu ứng dụng lớn nhất về tài chính ở Singapore - Poems 3.0 là trải nghiệm giao dịch tiên tiến, thích ứng mọi lúc mọi nơi với tham vọng trở thành app tài chính hàng đầu thế giới, tập trung vào nhiều loại giao dịch bao gồm: Stocks/Equities/Shares, ETF, CFD, Future/Forex, kết nối với 26 sàn giao dịch lớn nhất trên thế giới và thậm chí bao gồm cả mạng xã hội cho các traders.\n\nDự án có sự tham gia của khoảng 100 kỹ sư công nghệ trên thế giới đến từ Singapore, Hong Kong, Ấn Độ, Nhật Bản, Việt Nam với 3 giai đoạn trong năm nay và dự kiến sẽ phát triển thêm các giai đoạn với các chức năng và cải tiến mới vào năm tới để mang đến trải nghiệm ứng dụng tốt nhất.\n\nYêu cầu ứng viên:\nMUST HAVE\nTốt nghiệp Đại học/Cao đẳng chuyên ngành liên quan.\nCó từ 1 năm kinh nghiệm phát triển app iOS (Swift/SwiftUI).\nCó hiểu biết về mô hình kiến trúc lập trình MVP/MVVM.\nCó kinh nghiệm làm việc với RXSwift, SnapKit là lợi thế.\nCó tư duy logic, sử dụng thuật toán tốt.\nTiếng Anh giao tiếp là một lợi thế.\nCó khả năng học hỏi công nghệ mới.\nCó kinh nghiệm làm việc với các hệ thống tài chính là một điểm cộng.\nCó kinh nghiệm về UI/UX là một điểm cộng.\n\nNICE TO HAVE\nThích làm việc với các hệ thống lớn trong mảng tài chính.\nCó kinh nghiệm điều phối team là một lợi thế.\n\nQuyền lợi:\nINCOME\nMức lương đàm phán theo năng lực ứng viên, cạnh tranh với thị trường, upto 1000$.\nĐánh giá kết quả công việc hằng năm. Nhiều cơ hội tăng thu nhập từ 50-80%/năm.\nThưởng lương tháng 13: 1 tháng lương.\nThưởng dự án theo quý.\nThưởng hiệu quả kinh doanh: Theo kết quả hoạt động kinh doanh hằng năm của công ty.\nĐược cấp thẻ bảo hiểm sức khỏe được thiết kế riêng cho TDTers.\nVới các nhân sự ở level Manager trở lên, có package benefit riêng.\n\nCAREER PATH IMPROVEMENT\nKhi trở thành 1 TDTer, bạn sẽ có cơ hội phát triển bản thân với tốc độ gấp 2-3 lần thị trường, với nhiều cơ hội và thách thức như:\nĐược tham gia full-cycle vào quy trình phát triển các sản phẩm Tài chính phức tạp, kết hợp nhiều nghiệp vụ khó.\nLàm việc với những dự án chuyên sâu trong lĩnh vực công nghệ tài chính liên quan Quantitative Trading, HFT, ultra very low latency.\nĐược thử sức với nhiều ngôn ngữ lập trình, nhiều framework khác nhau.\nĐược làm việc trong môi trường quốc tế: Sử dụng tiếng Anh hàng ngày, trao đổi với team CNTT của nhiều nước khác nhau, onsite dài ngày/ngắn ngày tại nước ngoài...\nĐược tham gia vào các chương trình đào tạo dài hạn dành cho Core-team theo định hướng phát triển của từng vị trí và từng người.\nĐược thử thách với các vị trí Senior/Teamlead/Project Manager.\n\nCOMPANY ACTIVITIES\nVăn phòng thiết kế theo phong cách Co-working, có nhiều tiện ích giải trí như: Máy pha cafe, máy chạy bộ, bàn bóng bàn...; khu ăn uống với đồ ăn, đồ uống miễn phí; phòng tắm nóng lạnh, máy giặt..\nĐược trang bị các thiết bị hiện đại như Laptop cấu hình cao, Macbook...\nĐược tham gia các câu lạc bộ theo sở thích như: CLB bóng đá, CLB chạy, CLB trading chứng khoán/ forex/crypto vui vẻ, các giải game...\nĐược đài thọ 100% chi phí tham gia các chuyến du lịch cùng công ty: Summer Holiday, Year End Party.\nĐược tặng quà, tham gia các sự kiện trong các dịp 1/6, Trung Thu, 8/3, 20/10...\n\nĐịa điểm làm việc:\nHà Nội: Tầng 5, Tòa nhà PVI số 1 Phạm Văn Bạch, P. Yên Hòa, Cầu Giấy.\n\nThời gian làm việc:\n08h30 – 17h30, Thứ 2 – Thứ 6. Nghỉ Thứ 7, CN và các ngày lễ theo quy định.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2876, 1279, 2, 'Lập Trình Viên Python', 'Giao tiếp trao đổi với khách hàng bằng tiếng anh để nắm rõ yêu cầu.\nThực hiện công việc sử dụng ngôn ngữ Python, HTML/CSS, MongoDB\nHỗ trợ khách hàng trong việc triển khai và tối ưu hóa ứng dụng.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT hoặc các ngành liên quan.\nCó kiến thức/kinh nghiệm Python (Jinja2) trên 6 tháng\nHTML/CSS cơ bản\nCó kiến thức/kinh nghiệm làm việc với low code\nCó ít nhất 1-4 năm kinh nghiệm làm việc trong lĩnh vực cấu hình ứng dụng, triển khai hệ thống.\nTiếng Anh giao tiếp thành thạo (bắt buộc).\nKỹ năng giao tiếp, thuyết trình và đào tạo tốt.\nCó khả năng làm việc độc lập và theo nhóm.\nƯu tiên ứng viên có kinh nghiệm làm việc với khách hàng quốc tế.\n\nQuyền lợi:\n- Được đào tạo bài bản về sản phẩm và kỹ năng chuyên môn.\n- Làm việc trực tiếp với khách hàng tại nhiều quốc gia khác nhau, cơ hội đi onliste Philippines/Hong Kong mỗi tháng từ 3-5 ngày nếu có yêu cầu từ khách hàng\n- Mức lương hấp dẫn, có bonus khi kết thúc hợp đồng.\n- Cơ hội làm việc trong môi trường chuyên nghiệp, năng động và quốc tế.\n- Hỗ trợ chi phí đi lại, ăn ở trong thời gian công tác nước ngoài.\n- Các chế độ phúc lợi khác theo quy định của công ty.\n\nThông tin thêm:\n- Ứng viên sẽ được đào tạo 2 tháng tại Hồ Chí Minh trước khi bắt đầu công tác nước ngoài.\n- Công ty sẽ hỗ trợ xin visa du lịch cho ứng viên (không yêu cầu visa lao động).\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Phước Long B, Thủ Đức.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2877, 1283, 2, 'Nhân Viên Lập Trình CNC - Phần Mềm Creo', '• Tiếp nhận bản vẽ, file chi tiết 3D, lập trình các chi tiết khuôn theo kế hoạch gia công hàng tháng, đảm bảo đúng kế hoạch gia công của tổ CNC.\n• Phụ trách lập trình cho các máy phay CNC đúng theo file 3D và bản vẽ thiết kế khuôn.\n• Kiểm soát quy trình và chương trình gia công để đảm bảo đúng tiến độ, tiêu chuẩn về kích thước, số lượng các chi tiết cần gia công trên máy CNC.\n• Phối hợp với Tổ trưởng và KTV. CNC kiểm soát quá trình gia công, kiểm tra kỹ thuật các khuôn được gia công.\n\nYêu cầu ứng viên:\n• Tốt nghiệp từ Trung cấp các ngành liên quan;\n• Có từ 02 năm kinh nghiệm tại vị trí tương đương;\n• Am hiểu và biết sử dụng thành thạo Vi tính văn phòng, phần mền CREO.\n• Am hiểu về công nghệ gia công cắt gọt, khuôn ép nhựa.\n• Cẩn thận, tập trung tốt, có tinh thần trách nhiệm cao và luôn tận tâm với công việc.\n• Khả năng làm việc theo nhóm.\n\nQuyền lợi:\n• Lương: 14 – 18 triệu;\n• Thưởng Lễ, Tết,...;\n• Đóng Bảo hiểm và chế độ nghỉ phép theo Luật Lao động khi ký chính thức;\n• Hưởng đầy đủ các chế độ phúc lợi theo quy định của Công ty;\n• Xem xét đánh giá năng lực và xét tăng lương hằng năm;\n• Kiểm tra sức khỏe định kỳ.\n\nĐịa điểm làm việc:\n• Hồ Chí Minh: 948 Hương Lộ 2, Bình Trị Đông A, Bình Tân, Bình Tân.\n\nThời gian làm việc:\n• Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n• Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2878, 1375, 2, 'Nhân Viên Lập Trình Phay, Tiện', '1. Mục tiêu công việc\nXây dựng, hiệu chỉnh chương trình gia công CNC chính xác cho các chi tiết cơ khí trên máy phay và tiện CNC, đảm bảo năng suất, chất lượng và an toàn.\n\n2. Nhiệm vụ chính\n- Lập trình gia công CNC cho máy phay và tiện theo bản vẽ kỹ thuật\n- Xác định nguyên công gia công, chọn dao cụ, tốc độ cắt và chế độ cắt phù hợp.\n- Thiết lập quy trình gia công tối ưu, phối hợp với kỹ thuật vận hành để kiểm tra chương trình và hiệu chỉnh nếu cần.\n- Mô phỏng quá trình gia công trên phần mềm để phát hiện lỗi và cải thiện năng suất.\n- Hỗ trợ vận hành khi chạy thử chương trình mới, khắc phục lỗi chương trình thực tế.\n- Lưu trữ, quản lý và cập nhật hệ thống chương trình CNC theo mã sản phẩm.\n- Đảm bảo các yếu tố an toàn, tuân thủ quy trình vận hành và bảo mật dữ liệu lập trình.\n\nYêu cầu ứng viên\n- Trình độ học vấn: Cao đẳng hoặc Đại học chuyên ngành Cơ khí chế tạo, Cắt gọt kim loại, Tự động hóa, hoặc tương đương.\n- Kinh nghiệm:\n  - Tối thiểu 1–2 năm kinh nghiệm lập trình máy CNC.\n  - Ưu tiên ứng viên có kinh nghiệm lập trình đa trục hoặc gia công chi tiết phức tạp.\n- Kiến thức và kỹ năng:\n  - Am hiểu các loại dao cụ, vật liệu gia công, phương pháp gá đặt.\n  - Đọc hiểu bản vẽ kỹ thuật (2D, 3D), tiêu chuẩn dung sai, kỹ thuật đo lường.\n  - Kỹ năng làm việc nhóm, phối hợp với tổ vận hành và kỹ thuật.\n- Tư duy logic, cẩn thận, và chủ động trong công việc.\n\nQuyền lợi\n- Mức lương: thỏa thuận theo năng lực\n- Phụ cấp: Cơm trưa, xăng xe, chuyên cần, tăng ca.\n- Thưởng: Tháng 13, hiệu suất, sáng kiến (nếu có).\n- Chế độ: BHXH, BHYT, BHTN đầy đủ, nghỉ phép, nghỉ lễ.\n- Có cơ hội đào tạo nâng cao tay nghề, tham gia vào các dự án lớn.\n- Môi trường làm việc an toàn, chuyên nghiệp và ổn định lâu dài.\n- Có khu ở lại sạch sẽ nếu nhà xa.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 228/13/3 Nguyễn Thị Lắng, Ấp Phú Lợi, Xã Tân Phú Trung, Củ Chi.\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 07:30 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2879, 74, 2, 'Senior Frontend Developer', 'Mô tả công việc\nPhạm vi công việc\n- Thiết kế và triển khai các chức năng của sản phẩm phụ trách sử dụng VueJS/ReactJS\n- Triển khai giao diện người dùng (UI) và cải thiện trải nghiệm người dùng (UX) phù hợp với hoạt động kinh doanh của khách hàng nhằm thúc đẩy chuyển đổi số (DX)\n- Xác định yêu cầu và xây dựng tài liệu đặc tả phối hợp với quản lý sản phẩm và nhà thiết kế\n- Rà soát thiết kế và lập trình của các kỹ sư khác\nMôi trường phát triển\n- Lập trình: TypeScript/HTML/CSS\n- Khung: VueJS, NuxtJS, ReactJS, NextJS\n- Cơ sở hạ tầng: AWS/GCP\n- CI/CD: Circle CI/Bitrise/GitHub Actions\n- Công cụ kiến ​​thức: Confluence/esa\n- VCS: GitHub\n- Khác: Slack/Jira/Trello\n\nYêu cầu ứng viên\nPhải có:\n- Thấu hiểu sứ mệnh và giá trị của Nodo\n- Hơn 4 năm kinh nghiệm trong vai trò phát triển phần mềm: Lập trình viên Frontend\n- Kinh nghiệm với ngôn ngữ TypeScript\n- Kinh nghiệm với các framework frontend (VueJS, ReactJS, v.v.)\n- Kiến thức và khả năng giải thích các nguyên lý vận hành web và sự khác biệt giữa các trình duyệt\n- Kiến thức cơ bản về bảo mật ứng dụng web\n- Kỹ năng phát triển và vận hành sử dụng các framework khác nhau\n\nƯu tiên:\n- Kiến thức về Java/Python\n- Kinh nghiệm phát triển các front-end microservices\n- Kinh nghiệm phát hiện và giải quyết sự cố từ nhật ký\n- Kinh nghiệm quyết định và triển khai chính sách kỹ thuật của nhóm với vai trò trưởng nhóm kỹ thuật\n- Kinh nghiệm sử dụng và hiểu các thư viện và framework\n- Kinh nghiệm phát hành và đóng góp vào OSS (Open Source Software)\n\nQuyền lợi\n- Mức lương 25 - 35 triệu tùy theo năng lực\n- Cơ hội thăng tiến rõ ràng trong môi trường làm việc năng động\n- Được tham gia các khóa học nâng cao kỹ năng chuyên môn\n- Chế độ bảo hiểm đầy đủ theo quy định của pháp luật\n- Thưởng theo hiệu quả công việc và các dịp lễ tết\n- Được tham gia các hoạt động team building, du lịch hàng năm\n- Môi trường làm việc chuyên nghiệp, thân thiện\n- Văn hóa phẳng, cởi mở và chia sẻ với đội ngũ quản lý thân thiện\n\nĐịa điểm làm việc\n- Hà Nội: Showroom Audi - Số 8 Phạm Hùng - Phường Mễ Trì, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2880, 209, 2, 'Sap Abap Developer', 'Mô tả công việc\nOffshore or onsite ABAP development for implementation/ roll-out/ development/ AMS projects\nReview functional specification (FS) and suggest appropriate technical solution\nWrite technical specification (TS) based on FS\nStrictly adhere to development guidelines for ABAP development\nConduct peer review to guarantee adherence to guidelines and templates\nWrite Unit Test Specification (UTS) and perform Unit Testing (UT)\nRecommend end-to-end technical solutions to improve business processes\nArticulate and manage consultation sessions with functional consultants and end-users\nManage, keep track and follow up on assigned tasks promptly, and escalate countermeasures to supervisor\nWork independently and proactively\nStrong commitment to deliver solutions on time\nFollow documentation processes and guidelines\nMaintain high development quality\nMaintain strong working relationship with peers from all locations\nEnsure proper documentation and provide knowledge transfer to support members\n\nYêu cầu ứng viên\nMandatory:\nỨng viên ngồi ở mọi size: HN, HCM, DN, Nha Trang…\nAt least 4+ years of experience in ABAP and object oriented programming\nExperience in RICEF development in ABAP language (Reports, Interfaces, Conversions, Enhancements, Forms)\nExperience in both Procedural and Object Oriented Programing\nExperience in ECC 6.0 and S/4HANA for at least one of the following modules: FICO/ MM/ SD/ PP/ PM/ HCM\nIn-depth understanding of the Software Development Life Cycle (SDLC)\nDetail-oriented with strong organizational skills\nWork well with minimal supervision and able to deliver results under pressure\nAble to work in a fast-paced and team-oriented environment\nGood English Speaking or Good Japanese is a must\nOthers:\nExperience with OData Gateway, CDS View, SAP BTP, CPI, Fiori, Adobe Forms, BW/BO, PI/PO, SAP Workflows and performance tuning is a plus\nSAP Global Certification is a plus\n\nQuyền lợi\n• Competitive salary, Commensurate with your position and contribution\n• " FPT care" health insurance providaed by AON and is exclusive for FPT employees.\n• Annual Summer Vacation: follows company\'s policy and starts from May every year\n• International, dynamic, friendly working environment\n• Annual leave, working conditions follow Vietnam labor laws.\n• Other allowances: lunch allowance, working on-site allowance, etc\n\nĐịa điểm làm việc\n- Đà Nẵng\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2881, 1138, 2, 'Nhân Viên Thiết Kế - Lập Trình File CNC', 'Mô tả công việc:\nThiết kế và lập trình file điều khiển cho máy CNC (máy cắt, đục, khắc gỗ, v.v.).\nĐọc hiểu và triển khai bản vẽ kỹ thuật 2D, 3D.\nLập trình G-code phục vụ sản xuất trên máy CNC.\nPhối hợp với các bộ phận liên quan để tối ưu hóa quy trình gia công.\nKiểm tra, chỉnh sửa và đảm bảo độ chính xác của file lập trình trước khi sản xuất.\n\nYêu cầu ứng viên:\nTốt nghiệp Trung cấp/Cao đẳng trở lên các ngành: Cơ khí, Thiết kế kỹ thuật, Chế biến gỗ, hoặc chuyên ngành liên quan.\nThành thạo các phần mềm thiết kế và lập trình CNC: AutoCAD, ArtCAM, MasterCAM, SketchUp,...\nCó ít nhất 1 năm kinh nghiệm thiết kế và lập trình file CNC (ưu tiên ngành gỗ).\nHiểu biết về quy trình vận hành máy CNC và các phương pháp gia công gỗ.\nTỉ mỉ, cẩn thận, có tư duy logic và tinh thần cải tiến.\n\nQuyền lợi:\nMức lương:  8-13tr, Thỏa thuận theo năng lực và kinh nghiệm.\nĐược tham gia đầy đủ BHXH, BHYT, BHTN theo quy định pháp luật.\nThưởng lễ, Tết, và các chế độ phúc lợi khác theo quy định công ty.\nĐược đào tạo nâng cao tay nghề và cập nhật công nghệ mới.\nMôi trường làm việc chuyên nghiệp, thân thiện, cơ hội phát triển rõ ràng.\n\nĐịa điểm làm việc:\n- Hà Nội: CN11 - KCN Nguyên Khê, Đông Anh.\n- Hà Nội: 4 Dịch Vọng Hậu, Cầu Giấy.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Đông Anh, Cầu Giấy', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2882, 1312, 2, 'Nhân Viên IT', 'Mô tả công việc\n- Thiết lập hệ thống MES (Manufacturing Execution System) phù hợp với đặc thù sản xuất.\n- Kiểm tra lỗi, cập nhật phần mềm vá bảo mật và đảm bảo hệ thống hoạt động ổn định. Xử lý các vấn đề kỹ thuật phát sinh trong quá trình vận hành.\n- Thu thập, phân tích dữ liệu thời gian thực từ máy móc và quy trình sản xuất đảm bảo tính toàn vẹn của dữ liệu để hỗ trợ ra quyết định.\n- Phân tích hiệu suất SQL.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc chuyên ngành khác có liên quan.\n- Quản trị cơ sở dữ liệu Microsoft SQL Server ít nhất 2 năm.\n- Kiến thức cơ bản về Java để tùy chỉnh hệ thống.\n- Hiểu về nguyên lý hoạt động của MES tích hợp với ERP.\n\nQuyền lợi\n- Được hưởng đầy đủ mọi chế độ quyền lợi của người lao động theo đúng quy định của Pháp luật.\n- Lương: Thỏa thuận.\n- Được tham gia BHXH, BHYT, BHTN ngay từ khi thử việc.\n- Môi trường làm việc chuyên nghiệp, mức thu nhập thỏa đáng và cơ hội phát triển nghề nghiệp.\n- Đánh giá xét tăng lương hàng năm theo chính sách của công ty.\n\nĐịa điểm làm việc\n- Ninh Bình: Lô CN1, KCP Phúc Sơn, phường Ninh Sơn, TP Hoa Lư, TP Ninh Bình.\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ninh Bình', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2883, 1128, 2, 'Winform Developer', 'Mô tả công việc\n- Tham gia các dự án sử dụng ngôn ngữ lập trình Winform (VB/C# .NET),...\n- Phân tích thiết kế, lập trình và viết UT cho các chức năng của các hệ thống nghiệp vụ.\n- Nghiên cứu công nghệ thích hợp để giải quyết vấn đề\n- Làm các công việc khác theo sự phân công của quản lý (nghiên cứu công nghệ mới, quản lý và hỗ trợ đội phát triển dự án,...) \n\nYêu cầu ứng viên\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan\n- Có từ 1-2 năm kinh nghiệm làm việc với C# .NET.\n- Có kinh nghiệm phát triển ứng dụng WPF và Console App\n- Có kinh nghiệm làm việc với Entity Framework/Dapper\n- Có thể làm việc tốt với các hệ quản trị cơ sở dữ liệu thông dụng như: MySQL, SQL Server\n- Hiểu biết về PowerShell, có khả năng viết và triển khai các script tự động hóa\n- Ưu tiên ứng viên có kiến thức về VBA\n\nƯu tiên:\n- Thành thạo các công cụ quản lý source code (Git, SVN...), quản lý task (Jira)\n- Có tiếng Nhật hoặc có kinh nghiệm làm việc với khách hàng Nhật\n- Tư duy logic tốt\n- Có kiến thức tốt về quy trình phát triển phần mềm\n- Có khả năng viết UnitTest\n\nYêu cầu khác:\n- Kỹ năng phân tích và giải quyết vấn đề tốt.\n- Có tinh thần học hỏi, cầu tiến và khả năng làm việc nhóm hiệu quả\n- Khả năng tiếng anh đọc hiểu tài liệu\n\nQuyền lợi\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng dự án + thưởng kinh doanh cuối năm, thưởng Tết và các dịp lễ...;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe 24/24;\n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện);\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày;\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành.\n- Miễn phí đồ uống tại khu ăn uống của công ty;\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan;\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game,...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm....\n\nĐặc biệt:\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín.\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4 CT1, Tòa C14 Bắc Hà, Đường Tố Hữu, Phường Trung Văn, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2884, 1361, 2, 'Game Developer', 'Mô tả công việc\n- Phát triển các game casual, hypercasual, midscore, … trên nền tảng Cocos\n- Cập nhật, nâng cấp các tính năng mới cho danh sách game của công ty\n- Tối ưu hiệu quả các game của công ty\n- Phát triển các game trên nền tảng Android, IOS, Facebook, …\n- Các công việc khác theo sự phân công của quản lý trực tiếp.\n\nYêu cầu ứng viên\nTechnical Skill :\n- Có kinh nghiệm kinh nghiệm trên 1 năm lập trình Mobile (Chấp nhận đào tạo các bạn đã có từ 6 tháng).\n- Kiến thức và kinh nghiệm về ngôn ngữ JavaScript/TypeScripC\n- Yêu thích và đam mê lập trình, lập trình game\n- Kiến thức và kinh nghiệm về cocos creator. Chấp nhận đào tạo cho ứng viên có kinh nghiệm về ngôn ngữ khác như Unity, React, …\n- Có kinh nghiệm về Native là lợi thế\n- Đã có sản phẩm trên store Android hoặc iOS hoặc có thêm kiến thức cocos 2js là lợi thế. Hoặc tham gia phát triển sản phẩm đó là lợi thế.\n\nSoft skill:\n- Có tinh thần trách nhiệm cao trong công việc.\n- Có khả năng làm việc độc lập hoặc theo nhóm, xử ký vấn đề tốt.\n- Có khả năng tiếp thu kiến thức mới tốt.\n- Năng động, cởi mở, có khả năng chịu áp lực công việc lớn.\n\nQuyền lợi\n- Mức thu nhập cạnh tranh, đánh giá hiệu suất định kỳ 2 lần / năm.\n- Tổng thu nhập trung bình 13 – 15 tháng lương/năm. Thưởng các ngày lễ, Tết (Tết dương lịch, Quốc khánh, 30/04, Trung thu, Tết thiếu nhi, Sinh nhật, …)\n- Môi trường trẻ trung, thân thiện, cởi mở, đề cao phát triển cá nhân.\n- Cung cấp bữa trưa, đồ uống, trái cây miễn phí tại văn phòng.\n- Du lịch hàng năm (1-3 lần), khám sức khỏe định kỳ, các câu lạc bộ thể thao nội bộ: Bi-a, Bi-lăc, chạy bộ, ...\n- Đóng BHXH, BHYT, BHTN đầy đủ sau 2 tháng thử việc.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4, tòa Green Park Tower, Lô 33, ngõ 6 Dương Đình Nghệ, phường Yên Hòa TP Hà Nội, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2885, 1204, 2, 'Developer Leader', 'Mô tả công việc:\n- Tham gia vào phát triển các dự án với vai trò Team Leader từ giai đoạn Basic Design, Detail Design, Development, Release;\n- Thiết kế kiến trúc tổng thể hệ thống, Database, phát triển các chức năng đồng thời support các thành viên trong team;\n- Quản lý, lập kế hoạch, review công việc của các thành viên trong team;\n- Transfer lại cho Team về giải pháp, kiến trúc hệ thống;\n- Support các thành viên trong team xử lý những vấn đề khó phát sinh trong quá trình phát triển;\n- Tham gia với PM lập kế hoạch và hỗ trợ quản lý dự án;\n- Làm các công việc khác theo sự phân công của quản lý( Research new Technologies, Support team...).\n\nYêu cầu ứng viên:\n- 5-7 năm kinh nghiệm ở vị trí tương đương.\n- Tốt nghiệp khoa CNTT từ các trường đại học, Cao Đẳng\n- Có kinh nghiệm tối ưu hiệu năng cho những ứng dụng thực tế trên production, phục vụ lượng lớn người dùng và dữ liệu;\n- Sẵn sàng học hỏi và phát triển những ngôn ngữ mới \n- Có kinh nghiệm phát triển phần mềm trên nền công nghệ Java, và các framework như JSP, Servlet, Spring, Hibernet, Struts, ...\n- Có kinh nghiệm phát triển Portlet trên Liferay;\n- Ưu tiên những ứng cử viên có kinh nghiệm cài đặt, quản trị hệ điều hành Linux/Unix, hiểu biết hoặc có kinh nghiệm với các sản phẩm phần mềm mở sau: Alfresco, jBPM/Activiti, Pentaho, jBOSS, Postgre, ...\n- Tiếng Anh giao tiếp nghe nói tốt.\n\nQuyền lợi:\n- Thưởng tháng lương 13.\n- Chế độ nghỉ phép 12 ngày/năm nghỉ lễ, phép theo quy định.\n- Làm việc từ thứ 2 đến thứ 6 hàng tuần nghỉ thứ 7 & CN.\n- Làm việc trong môi trường chuyên nghiệp, thân thiện và hòa đồng với cơ hội thăng tiến lớn.\n- Luôn được đào tạo chuyên môn, học hỏi liên tục các công nghệ mới mang tính thực tế cao và tham gia các dự án lớn.\n- Lương thưởng hấp dẫn theo năng lực.\n- Hưởng thêm trợ cấp ăn trưa, và đi lại nếu có.\n- Hưởng các chế độ BHXH, BHYT, BHTN và nghỉ phép theo luật định khi ký Hợp đồng lao động.\n- Hưởng các chế độ phúc lợi như nghỉ mát, ngoại khóa, các sự kiện hàng quý/năm, các phần quà các ngày lễ, tết…\n\nĐịa điểm làm việc:\n- Hà Nội: Đường 2.2 Gamuda, Trần Phú, Hoàng Mai\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- nghỉ trưa 1,5h\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2886, 1307, 2, 'Mobile App Developer (React Native)', 'Mô tả công việc:\n- Phát triển ứng dụng mobile app cho người dùng app.\n- Tư vấn, phân tích, thiết kế.\n- Phát triển, kiểm thử, sửa lỗi.\n- Vận hành và bảo trì hệ thống.\n- Thực hiện đúng quy trình phát triển phần mềm.\n- Các công việc khác theo phân công của quản lý.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin các trường HUST, UET, PTIT.\n- Có từ 1 năm kinh nghiệm ở vị trí tương đương.\n- Có kinh nghiệm phát triển ứng dụng mobile app sử dụng lập trình React Native.\n- Có kinh nghiệm thiết kế UI/UX.\n- Có hiểu biết về kiến trúc ứng dụng IoT trong smart home, smart building phục vụ phát triển app cho hệ thống.\n- Sáng tạo, nhanh nhẹn, trung thực.\n- Sử dụng tiếng Anh tốt là một lợi thế.\n\nQuyền lợi:\n- Lương/thưởng theo chế độ của công ty.\n- Thưởng upto 3 tháng lương/năm.\n- Môi trường chuyên nghiệp, năng động, thân thiện, cơ hội thăng tiến.\n- Chế độ BHYT, BHXH theo Luật Lao động.\n- Khám sức khỏe định kỳ hàng năm.\n- Tham gia các hoạt động, sự kiện của công ty.\n- Tham gia các khóa đào tạo trong và ngoài nước.\n- Thời gian làm việc: Thứ 2 đến hết sáng thứ 7 (8h30-12h00; 13h00-17h30).\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 2, Tòa N09B2 Thành Thái, Cầu Giấy.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2887, 1203, 2, 'Nhân Viên Lập Trình', 'Mô tả công việc: - Tham gia các dự án phát triển các dự án Website, thương mại điện tử; - Nghiên cứu các công nghệ mới, hỗ trợ phát triển, khắc phục lỗi hệ thống; - Xây dựng và chỉnh sửa các module, tính năng theo yêu cầu; - Các công việc khác theo phân công của cấp trên. \nYêu cầu ứng viên: - Có kiến thức về codegym \n- Có kinh nghiệm lập trình Backend sử dụng java; \n- Có kinh nghiệm lập trình Front end (web) trên nền tảng Spring framework; \n- Ưu tiên người có kinh nghiệm về một trong các nền tảng Spring framework, Angular, AngularJs, React; \n- Có khả năng sử dụng query cơ bản trên MySQL, Oracle; \n- Có khả năng sử dụng Shell Script và câu lệnh cơ bản trên Linux. \n– Cẩn thận, kiên nhẫn, đam mê lập trình và sẵn sàng học hỏi các công nghệ mới. \n– Chịu được áp lực công việc. \n– Có kỹ năng phân tích và giải quyết vấn đề, có khả năng làm việc độc lập và theo nhóm. \nQuyền lợi: - Mức lương cạnh tranh: 10 – 20M. - Con đường sự nghiệp vững vàng, môi trường làm việc năng động, nhanh nhẹn. - Được đào tạo theo định hướng công việc của Công ty và nhu cầu đề xuất cá nhân. - Thưởng KPI, Thưởng dự án, Thưởng hiệu quả công việc, thưởng cuối năm tháng 13+++… - Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc. - Được hưởng BHXH, BHYT, BHTN theo chế độ nhà nước ban hành. - Khám sức khỏe định kỳ 1 năm/1 lần. - Được tham gia các hoạt động thể dục thể thao như: Bóng đá, cầu lông,… - Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding thường xuyên. - Làm việc từ thứ 2 đến thứ 6, nghỉ thứ 7 và CN; - 12 ngày phép/năm và các ngày nghỉ lễ - tết theo quy định;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2888, 1466, 2, 'Kỹ Sư Vận Hành Máy', 'Mô tả công việc:\n- Xây dựng bản vẽ, quy trình công nghệ để gia công chi tiết.\n- Tối ưu quy trình công nghệ, đạt hiệu quả gia công về thời gian, chất lượng, tối ưu dụng cụ cắt gọt.\n- Thực hiện lập trình & xuất chương trình và gia công.\n- Điều chỉnh, sửa chương trình ngay khi phát hiện sự cố, đảm bảo thời gian chạy máy CNC.\n- Định mức thời gian hoàn thành mỗi công đoạn gia công: Phay\n- Thực hiện các công việc khác khi được cấp trên yêu cầu.\n\nYêu cầu ứng viên:\n- Tốt nghiệp trung cấp trở lên, nhanh nhẹn, nhiệt tình trong công việc;\n- Đọc tốt bản vẽ kỹ thuật, Lập trình 2D+3D. Sử dụng thành thạo phần mềm CAD/CAM\n- Có kinh nghiệm ít nhất 1 năm về thiết kế, lập trình máy CNC; 1 năm vận hành máy CNC.\n- Có đam mê với nghề kỹ thuật.\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, Hass.\n\nQuyền lợi:\n- Có cơ hội phát triển nghề nghiệp tại công ty\n- Làm việc trong môi trường năng động, chuyên nghiệp;\n- Cung cấp đồng phục, trang thiết bị đầy đủ để phục vụ công việc;\n- Thưởng các dịp Quốc tế Lao động 1/5, Quốc khánh 2/9, Tết dương lịch, Thưởng Tết theo quy định của công ty\n- Được đóng đẩy đủ BHXH, BHYT, BHTN;\n- Đi du lịch nghỉ mát hàng năm;\n- Tham gia các hoạt động văn hoá thể thao (bóng đá, chạy...);\n\nĐịa điểm làm việc:\n- Thanh Hoá: Quế Sơn, Thọ Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thanh Hoá', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2889, 1143, 2, 'Lập Trình Viên Java', 'Mô tả công việc:\n- Tham gia xây dựng, phát triển và tối ưu hệ thống quản trị đại học, Hệ thống Elearning.\n- Tham gia vào toàn bộ vòng đời phát triển phần mềm: phân tích, thiết kế, lập trình, kiểm thử, triển khai và bảo trì.\n- Đề xuất, triển khai các giải pháp cải thiện hiệu năng hệ thống và nâng cao trải nghiệm người dùng (UI/UX).\n\nYêu cầu ứng viên:\n- Tối thiểu 3 năm kinh nghiệm làm việc với Java Core, Spring MVC hoặc Spring Boot.\n- Có kinh nghiệm thực tế với các công nghệ:\n  - Hibernate, RESTful API, Microservices\n  - Docker/Kubernetes, JUnit\n  - Cơ sở dữ liệu: MySQL, PostgreSQL, MongoDB\n  - JavaScript, HTML, CSS\n- Nắm vững lập trình hướng đối tượng (OOP), thành thạo design patterns, có tư duy hệ thống và khả năng giải quyết các bài toán kỹ thuật phức tạp.\n- Có tư duy tối ưu hệ thống: chú trọng đến hiệu năng, khả năng mở rộng và dễ bảo trì.\n- Tự chủ, chủ động, có tinh thần học hỏi và trách nhiệm cao trong công việc.\n\nQuyền lợi:\n- Mức lương từ: 20-35 triệu/tháng tùy theo năng lực\n- Thưởng performance, dự án\n- Có cơ hội thăng tiến và hỗ trợ học tập công nghệ mới.\n- Được hưởng đầy đủ các chế độ đãi ngộ với người lao động theo Luật lao động Việt Nam.\n- Chế độ đãi ngộ: Được tham gia BHXH và các hưởng các chế độ khác theo quy định của Nhà nước.\n- Thưởng tháng 13, du lịch hàng năm, có cơ hội thăng tiến.\n- Môi trường trẻ trung, năng động.\n\nĐịa điểm làm việc:\n- Hà Nội: Khu văn phòng, Trường mầm non Thành Đông, đường Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2890, 1443, 2, 'Thực Tập Sinh Lập Trình Phần Mềm', '- Thực tập nghiên cứu, phát triển các hệ thống phần mềm ứng dụng công nghệ cao, kỹ thuật hiện đại.\n- Tham gia quá trình phân tích, thiết kế cho một sản phẩm cụ thể.\n- Làm việc theo sự phân công của người quản lý, phối hợp giữa các nhóm để phát triển sản phẩm hoàn chỉnh.\n\nYêu cầu ứng viên:\n- Sinh viên năm 3 trở lên chuyên ngành: CNTT, Điện tử viễn thông, Khoa học máy tính, Toán tin ứng dụng và các chuyên ngành kỹ thuật khác liên quan.\n- Có thành tích học tập đạt loại Khá trở lên tại thời điểm xét duyệt\n- Có kiến thức cơ bản về lập trình front-end: HTML5, CSS3, Javascript\n- Ưu tiên các ứng viên đã biết về ReactJS, VueJS\n- Có kiến thức cơ bản về lập trình back-end: .NET Core, Python, NodeJS, Java\n- Ưu tiên các ứng viên đã biết về .NET Core WebAPI, .Net Core EF\n- Có khả năng đọc hiểu tài liệu tiếng Anh tốt.\n\nQuyền lợi:\n- Được đào tạo về lập trình chuyên nghiệp bởi những chuyên gia công nghệ hàng đầu trong lĩnh vực CNTT\n- Được học nghiệp vụ các sản phẩm CNTT ứng dụng\n- Được hưởng trợ cấp thực tập sau quá trình đào tạo nếu có khả năng tham gia các dự án thực tế của công ty\n- Được thực tập tại môi trường chuyên nghiệp, năng động, văn hóa hiện đại\n- Được tham gia học tập, nghiên cứu và phát triển các ứng dụng trên nền tảng công nghệ chuyên ngành GIS, AI/ML, OCR, OMR...\n- Được học hỏi về phát triển ứng dụng mobile hybrid app trên Flutter\n- Ưu tiên xem xét cho những cơ hội Tuyển dụng chính thức sau khi ra trường\n\nĐịa điểm làm việc:\n- Hà Nội: Liền kề 6B-27 C17 Khu Đô thị Mỗ Lao, Phường Mộ Lao Thành phố Hà Nội, Việt Nam, Hà Đông\n\nThời gian làm việc:\nT2-T6: 9h-12h; 13h-18h\nT7: 9h-12h\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2891, 1123, 2, 'Power Platform Developer (PowerApps)', 'Mô tả công việc:\n- Develop and Design: Build custom applications, workflows, and solutions using Microsoft PowerApps, Power Automate, and Power BI.\n- Integration: Connect PowerApps with various data sources such as SharePoint, SQL Server, Dataverse, Azure, and third-party APIs.\n- Requirement Gathering: Collaborate with stakeholders to understand business needs and translate them into technical requirements.\n- Automation: Implement process automation solutions using Power Automate (Flow) to streamline business operations.\n- Customization: Customize apps with PowerApps formulas, Canvas Apps, Model-Driven Apps, and Portals.\n- Testing and Deployment: Perform thorough testing, debugging, and deployment of Power Platform solutions.\n- Documentation: Create and maintain comprehensive technical documentation, including workflows, processes, and troubleshooting guides.\n- Training and Support: Provide end-user training and support for deployed applications and solutions.\n- Best Practices: Stay updated with Power Platform features and ensure adherence to development best practices and governance.\n\nYêu cầu ứng viên:\n- Technical Expertise:\n  - Proficiency in Microsoft PowerApps, Power Automate, and Power BI.\n  - Experience with Canvas Apps, Model-Driven Apps, and Dataverse.\n  - Strong understanding of relational databases and data modeling.\n  - Knowledge of Azure services and API integration is a plus.\n\n- Development Skills:\n  - Hands-on experience with JavaScript, HTML, CSS, and JSON.\n  - Familiarity with Microsoft 365 ecosystem, including SharePoint, Teams, and Dynamics 365.\n\n- Experience:\n  - 2 years of experience in developing PowerApps solutions (e.g., Canvas Apps, Model-Driven Apps).\n  - Knowledge of RPA (Robotic Process Automation) is a plus.\n\nQuyền lợi:\n- Salary: Negotation\n- Join a global team and work directly with many talents around the world.\n- Opportunities for onsite work in Japan, Singapore, Australia, and many other countries.\n- Work and grow in a dynamic, creative, and professional environment.\n- Healthcare: Premium Health Insurance TECHVIFY Care\n- 13 months’ salary per year.\n- Annual salary evaluation.\n- Sponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.\n\nĐịa điểm làm việc:\n- Hà Nội: HUD Tower, Lê Văn Lương, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2892, 1413, 2, 'Chuyên Viên Phát Triển Phần Mềm', 'Mô tả công việc\nXây dựng nhiệm vụ, xây dựng kế hoạch đưa phần mềm vào hoạt động và nghiệm thu:\n- Đề xuất điều chỉnh mục tiêu, mục đích yêu cầu\n- Đề xuất ký kết hợp đồng, phụ lục, thỏa thuận, nghiệm thu\n- Đánh giá test sản phẩm về công năng\n- Bổ sung tính năng và đưa phần mềm vào sử dụng \n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm trở lên về quản trị thiết kế phần mềm, phát triển phần mềm\n- Tốt nghiệp Đại học chính quy chuyên ngành Công nghệ thông tin, kỹ thuật phần mềm\n- Tuổi: 27-40\n\nQuyền lợi\n- Mức lương: 15 - 17 triệu\n- Được hưởng đầy đủ các chế độ phúc lợi xã hội như BHXH, nghỉ phép theo quy định; nghỉ mát hàng năm...\n- Làm việc trong môi trường chuyên nghiệp, năng động, nhiều cơ hội khẳng định bản thân và thăng tiến\n\nĐịa điểm làm việc\n- Hà Nội: Số 170 Ngọc Khán, Ba Đình\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 09:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2893, 1261, 2, 'DEV-OPS ENGINEER', '- Thiết kế, triển khai và bảo trì các pipeline CI / CD cho các ứng dụng của chúng tôi, bao gồm triển khai tự động, kiểm thử tự động và quản lý mã nguồn.\n- Xây dựng và bảo trì hệ thống và cơ sở hạ tầng bằng cách sử dụng các công nghệ mới nhất như Kubernetes, Docker, GitOps và Ansible.\n- Triển khai và quản lý ứng dụng trên các nền tảng đám mây như AWS, GCP hoặc Azure.\n- Phát triển các kịch bản tự động hóa và tiêu chuẩn hóa các quy trình triển khai và vận hành.\n- Hỗ trợ nhóm phát triển trong việc triển khai và cung cấp hỗ trợ cho các ứng dụng.\n- Giám sát và quản lý hiệu suất của các hệ thống và cơ sở hạ tầng.\n- Liên tục cải thiện và nâng cao chất lượng và độ tin cậy của các hệ thống và cơ sở hạ tầng.\n\nYêu cầu ứng viên:\n- Kinh nghiệm về thiết kế, triển khai và bảo trì các đường ống CI / CD và quản lý các ứng dụng trên các nền tảng đám mây.\n- Kinh nghiệm với các công nghệ như Kubernetes, Docker, GitOps và Ansible.\n- Hiểu biết về các nền tảng đám mây như AWS, GCP hoặc Azure.\n- Kinh nghiệm về quản lý cơ sở hạ tầng và hệ thống lớn, đảm bảo độ tin cậy và hiệu suất cao.\n- Kỹ năng giao tiếp và làm việc nhóm tốt.\n- Kinh nghiệm trong lĩnh vực phát triển phần mềm hoặc quản trị hệ thống.\n- Kỹ năng lập trình với một hoặc nhiều ngôn ngữ như Python, Java, hoặc Go.\n- Kinh nghiệm với các công cụ quản lý mã nguồn như Git và các nền tảng như GitHub hoặc GitLab.\n- Hiểu biết về các cơ chế bảo mật và kiểm soát truy cập, đảm bảo an toàn cho hệ thống và ứng dụng.\n- Sẵn sàng học hỏi và áp dụng các công nghệ mới nhất để cải thiện hiệu suất và độ tin cậy của hệ thống và ứng dụng.\n- Năng động, sáng tạo và có tư duy logic tốt.\n- Tiếng Anh đọc và viết tốt để có thể đọc tài liệu, tương tác.\n\nQuyền lợi:\n- Làm việc tại công ty hàng đầu Việt Nam, luôn không ngừng phát triển với nhiều cơ hội thăng tiến bản thân.\n- Được đào tạo chuyên nghiệp, hoàn toàn miễn phí trước khi làm việc.\n- Môi trường làm việc trẻ, năng động và thân thiện.\n- Tham gia đầy đủ các chế độ BHYT, BHXH, BHTN.\n- Thu nhập hấp dẫn, phù hợp năng lực bản thân.\n- Lương tháng 13 và thưởng theo hiệu quả kinh doanh.\n- Khám sức khỏe định kỳ.\n- Thường xuyên tổ chức các chương trình hội thao, hội diễn văn nghệ, tân niên, tất niên.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 67 Hoàng Văn Thái, Quận 7.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2894, 1468, 2, 'Nhân Viên Lập Trình & Vận Hành Máy Phay', 'Mô tả công việc: - Vận hành thành thạo máy phay CNC, hệ điều hành Fanuc, gia công chi tiết, đo, kiểm tra chi tiết sản phẩm làm ra. - Lập trình chương trình cho máy chạy. - Biết gá sản phẩm, lấy gốc - Biết thay dao khi xảy ra sự cố - Biết đọc bản vẽ gia công - Đảm bảo các yêu cầu kỹ thuật theo bản vẽ gia công của khách hàng - Phối hợp với các bộ phận khác như laser, hàn để hoàn thiện sản phẩm - Đề xuất dao cụ và phụ kiện đi kèm phù hợp - Các công việc khác theo sự phân công của quản lý trực tiếp. Yêu cầu ứng viên: - Tuổi từ 25 – 40 tuổi. - Có kinh nghiệm từ 3 năm trở lên về lập trình và vận hành máy phay cnc trong lĩnh vực cơ khí. - Tốt nghiệp từ trung cấp, cao đẳng nghề công nghiệp chuyên ngành về cơ khí chế tạo. - Có sức khỏe tốt, trung thực, có tinh thần trách nhiệm - Chăm chỉ, chịu khó, ham học hỏi, chịu được áp lực cao trong công việc. Quyền lợi: - Mức lương từ 13- 15 triệu /tháng. - Thưởng các ngày lễ ,tết,sinh nhật... theo qui định của công ty. - Luôn có cơ hội thăng tiến trong công việc nghề nghiệp - Được cung cấp trang thiết bị đầy đủ để phục vụ công việc - Nhân viên có năng lực tốt có thể ký hợp đồng chính thức khi chưa hết thời gian thử việc - Môi trường làm việc thân thiện, năng động. - Tăng lương theo hiệu quả công tác và cam kết đầy đủ các chế độ dành cho người lao động theo như quy định pháp luật hiện hành (BHYT, BHXH, BHTN...) - Được tham gia các hoạt động ngoại khóa: văn nghệ, du lịch, thể thao của Công ty. Địa điểm làm việc: - Bắc Ninh: Lô I7-4-2B KCN Đại Đồng – Hoàn Sơn, Phường Tân Hồng, Từ Sơn. Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh, Từ Sơn', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2895, 1248, 2, 'Business Analyst', 'Mô tả công việc\n+ Hỗ trợ KH sử dụng phần mềm\n+ Trao đổi với KH để làm rõ nhu cầu về tính năng của phần mềm \n+ Chuẩn bị tài liệu đặc tả tính năng, flowchart, mockup để làm việc với team kỹ thuật\n+ Nghiên cứu thị trường, nhu cầu KH \n+ Làm việc nhóm cùng các phòng ban khác và một số công việc cụ thể được giao\n\nYêu cầu ứng viên\n+ Ưu tiên ứng viên ngành Kinh tế, Công nghệ thông tin;\n+ Giao tiếp tiếng anh tốt;\n+ Ham học hỏi, chăm chỉ, có đam mê với ngành công nghệ, thương mại điện tử.\n\nQuyền lợi\n- Các chế độ BHXH, BHYT đầy đủ theo quy định của luật lao động.\n- Lương thưởng theo năng lực của mỗi cá nhân (mức lương có thể deal thêm khi tham gia phỏng vấn), tháng lương thứ 13.\n- Phụ cấp ăn trưa và phí gửi xe.\n- Được hưởng nhiều chế độ đãi ngộ khác theo chính sách của Công ty.\n- Tham gia các sự kiện, workshop của công ty, chế độ du lịch hàng năm, sinh nhật hàng tháng.\n- Môi trường làm việc trẻ, thân thiện, chuyên nghiệp.\n- Được cung cấp máy tính làm việc.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 12A, tòa A3 Ecolife Capitol, số 58 Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 18:00)\nNghỉ 2 thứ 7 luân phiên trong 1 tháng, nghỉ chủ nhật, lễ tết\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2896, 1246, 2, 'Software Internship', 'Chương trình tuyển dụng và đào tạo tài năng trẻ khối ngành Công nghệ thông tin từ một trong những Công ty hàng đầu lĩnh vực IT toàn cầu đã quay trở lại!!!\nLỘ TRÌNH TUYỂN DỤNG:\nVòng 1: Đơn đăng ký (01/06 - 22/06)\nVòng 2: Phỏng vấn (02/07)\nVòng 3: Đào tạo và thi tuyển (14/07 - 05/09)\nVòng 4: Kí hợp đồng chính thức và training on job (09/2025)\n\n• Là sinh viên năm cuối hoặc đã tốt nghiệp Đại học chưa quá 02 năm, ưu tiên các chuyên ngành Công nghệ thông tin hoặc các chương trình đào tạo liên quan đến lập trình và kỹ thuật phần mềm\n• Có định hướng trở thành lập trình viên, mong muốn phát triển lâu dài trong lĩnh vực công nghệ phần mềm\n• Có thể làm việc fulltime khi tham gia chương trình\n• Nắm vững kiến thức nền tảng về cấu trúc dữ liệu, thuật toán và thành thạo ít nhất một ngôn ngữ lập trình (Java, C++, Python,...)\n• Thái độ cầu tiến, ham học hỏi, năng động và sẵn sàng thử thách\n\n• Mức trợ cấp cực kì hấp dẫn trong thời gian đào tạo\n• Cơ hội trở thành nhân viên chính thức sau 08 tuần đào tạo, với mức thu nhập cùng đãi ngộ vượt trội, lên đến 17 tháng lương/ năm\n• Lộ trình đào tạo và phát triển toàn diện dược dẫn dắt bởi đội ngũ mentor giàu kinh nghiệm\n• Cơ hội tham gia các dự án quy mô quốc tế, phát triển, vận hành các hệ thống phần mềm của Tập đoàn Samsung trên toàn cầu, với đa dạng các lĩnh vực: điện tử, điện toán đám mây, trí tuệ nhân tạo, nhà máy thông minh, logistics,...\n• Khai phá tiềm năng với các khóa đào tạo chuyên sâu về chuyên môn, khóa học theo nguyện vọng cá nhân\n• Môi trường đa văn hóa, năng động, sáng tạo và tràn đầy nhiệt huyết\n• Địa điểm làm việc: Văn phòng Samsung SDS Vietnam tại Hà Nội, tòa PVI, Số 1 Phạm Văn Bạch, Yên Hòa, Cầu Giấy\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(2897, 1249, 2, 'Senior .NET Developer (AI)', 'Mô tả công việc:\n- Design, develop, and maintain APIs using .NET Core and C# within a microservices architecture to support logistics, warehouse, and inventory processes.\n- Work with PostgreSQL databases and write efficient SQL queries.\n- Set up and optimize CI/CD pipelines to automate application deployment.\n- Use Docker to package, deploy, and manage applications in containerized environments.\n- Occasionally contribute to user interface (UI) development using frontend technologies (as needed).\n- Optimize backend system performance, ensuring stability and scalability.\n- Collaborate with the team to analyze requirements, design solutions, and implement new features.\n- Ensure code quality through testing, code reviews, and adherence to coding standards.\n\nYêu cầu ứng viên:\n- At least 3-4 years of experience in developing applications using .NET Core and C#.\n- Proficient in SQL and experienced with PostgreSQL or other relational databases.\n- Integrate AI models and APIs into existing systems to enhance functionality.\n- Stay updated on emerging technologies, particularly in AI and software development.\n- Preferred Qualifications: Experience with AI-driven development tools.\n- Knowledge of microservices architecture and designing distributed systems.\n- Experience with CI/CD tools (e.g., GitLab CI, Jenkins) and automated deployment processes.\n- Proficient in using Docker for packaging and deploying applications.\n- Familiarity with RESTful API architecture, design, and implementation.\n- Experience with Golang is a plus.\n- Basic understanding of frontend development (HTML, CSS, JavaScript).\n- Strong problem-solving skills, with the ability to work independently and collaborate effectively in a team.\n- Experience in logistics, warehouse, or inventory management domains is a plus.\n- Logical thinking, attention to detail, and a strong sense of responsibility for work quality.\n\nQuyền lợi:\n- Competitive salary and benefits.\n- Attractive 13th month salary and performance bonus.\n- Annual performance review for salary raise and promotion.\n- Premium private insurance (PTI Insurance) with discount for family members.\n- Annual health check.\n- 12 days of annual leave.\n- Company trips and team buildings.\n- Gifts on special accession: individual/company birthday, Tet and Holidays.\n- Internal activities, sport and social clubs.\n- Opportunity to training both technical and soft skills to develop your career path.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 02nd Floor, FPT Tan Thuan 2, Tan Thuan Processing Zone - No. 8, Tan Thuan Dong, District 7, Quận 7.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2898, 1220, 2, 'Lead Python Fullstack', 'Mô tả công việc\n- Lập trình phát triển và nâng cấp các ứng dụng trên web\n- Tham gia vào phân tích và xây dựng các module mới\n- Nâng cấp và hiệu chỉnh các module, các hệ thống có sẵn của công ty\n- Tối ưu hóa/refactoring code cho các module/services.\n- Thúc đẩy áp dụng mạnh mẽ các phương pháp mới nhất về kỹ thuật, triển khai các quy trình và công cụ tự động (code reviews, code quality, CI/CD to monitoring)\n- Thiết kế và triển khai các ứng dụng và dịch vụ đáp ứng yêu cầu người dùng.\n- Hợp tác với các nhà phát triển giao diện người dùng để tích hợp các yếu tố giao diện người dùng với logic phía máy chủ.\n- Tham gia vào các buổi xem xét, đánh giá mã nguồn và đóng góp các ý kiến thiết thực cho dự án.\n- Cập nhật các xu hướng công nghệ mới và các tiến bộ công nghệ.\n- Khả năng học hỏi và chuyển đổi ngôn ngữ lập trình nhanh theo yêu cầu của công việc là một lời thế.\n- Quản lý đội nhóm.\n\nYêu cầu ứng viên\n- Có từ 3 năm kinh nghiệm với ngôn ngữ lập trình Python\n- Có thể làm full stack là lợi thế lớn.\n- Có kinh nghiệm trong một các framework Python (Django, Flask hoặc Pyramid)\n- Hiểu biết về các công nghệ giao diện người dùng\n- Có kinh nghiệm làm việc với Reactjs\n- Có kinh nghiệm về cơ sở dữ liệu MariaDB hoặc MySQL, Postgres\n- Kiến thức về các công cụ quản lý phiên bản mã nguồn như Github, bitbucket, gitlab,.. \n- Kỹ năng giải quyết vấn đề tốt.\n- Kỹ năng giao tiếp và làm việc nhóm tốt.\n- Bằng Cử nhân/Cử nhân Khoa học Máy tính, Kỹ thuật hoặc lĩnh vực liên quan.\n- Có kinh nghiệm làm việc với các ngôn ngữ và framework như PHP, .Net, Go, ReactJS... là một lợi thế.\n- Có kinh nghiệm tham gia lập trình và xử lý các tính năng liên quan đến dịch vụ về VAS hoặc Education là 1 lợi thế.\n\nQuyền lợi\n- Mức lương 22.000.000 - 32.000.000 gross\n- Giờ làm việc linh hoạt\n- Cơ hội phát triển nghề nghiệp và thăng tiến.\n- Môi trường làm việc thân thiện và hợp tác.\n- Phụ cấp ăn trưa.\n- Thưởng cuối năm: Dựa trên hiệu suất của công ty.\n\nĐịa điểm làm việc\n- Hà Nội: Số 6, Nguyễn Thị Thập, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2899, 1383, 2, 'Nhân Viên Lập Trình Máy, Khuôn Ép Nhựa', 'Mô tả công việc:\n- Lập trình trên phần mềm NX\n- Xây dựng và tối ưu hóa các thuật toán điều khiển cho máy móc, đảm bảo hiệu quả và độ chính xác cao.\n- Thử nghiệm và gỡ lỗi các chương trình điều khiển, đảm bảo hoạt động ổn định của máy móc.\n\nYêu cầu ứng viên:\n- Tốt nghiệp trung cấp trở lên\n- Ít nhất 1 năm kinh nghiệm lập trình điều khiển máy móc, lập trình trên phần mềm NX\n- Hiểu biết về các hệ thống điều khiển tự động, cảm biến, và bộ truyền động.\n- Khả năng đọc hiểu bản vẽ kỹ thuật và tài liệu kỹ thuật.\n- Kỹ năng phân tích, giải quyết vấn đề và làm việc độc lập.\n- Kỹ năng làm việc nhóm và giao tiếp tốt.\n- Khả năng chịu áp lực công việc cao.\n- Biết tiếng Trung là lợi thế\n\nQuyền lợi:\n- Mức lương cạnh tranh, phù hợp với năng lực và kinh nghiệm.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế theo quy định của pháp luật.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Cơ hội học hỏi và phát triển nghề nghiệp.\n- Các chế độ phúc lợi khác (nếu có).\n\nĐịa điểm làm việc:\n- Hải Dương: KCN Phúc Điền, Cẩm Giàng\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2900, 1204, 2, 'Trưởng Phòng Công Nghệ', '- Đánh giá, tư vấn và đưa ra giải pháp công nghệ phù hợp cho quá trình nâng cấp từ monolithic sang microservices.\n- Thiết kế và phát triển các API, tích hợp hệ thống hiện có và các bên thứ ba.\n- Quản lý vòng đời phát triển phần mềm (SDLC), ứng dụng CI/CD để nâng cao hiệu quả phát triển khai thác.\n- Hiểu biết Ứng dụng AI để quản lý và tối ưu hiệu suất, bảo mật và khả năng mở rộng của hệ thống.\n- Kết hợp các bộ phận để đảm bảo hệ thống hoạt động ổn định và đáp ứng yêu cầu nghiệp vụ.\n- Xây dựng và hướng dẫn đội ngũ kỹ thuật về các công nghệ mới.\n- Nghiên cứu các công nghệ mới áp dụng vào dự án.\n- Phát triển các tính năng mới cho sản phẩm theo yêu cầu của khách hàng.\n- Tham gia vào việc phát triển, nâng cấp, cập nhật các sản phẩm (web, ứng dụng, phần mềm) của khách hàng, kiểm tra bảo đảm chất lượng dự án.\n- Xây dựng và quản lý team 5-7 người\n- Chi tiết trao đổi khi phỏng vấn\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học, cao đẳng chuyên ngành IT,\n- Kinh nghiệm: 3-5 năm kinh nghiệm phát triển phần mềm, trong đó ít nhất 2 năm ở vị trí Techlead hoặc tương đương.\n- Kiến trúc: Có kinh nghiệm chuyển đổi hoặc làm việc với microservice, kiến ​trúc hướng sự kiện.\n- Cơ sở dữ liệu: Có kinh nghiệm MariaDB hoặc các hệ thống quản trị cơ sở dữ liệu (RDBMS). Hiểu biết về NoSQL là lợi thế.\n- API & Tích hợp: Kinh nghiệm làm việc với RESTful API, GraphQL , tích hợp với bên ngoài hệ thống.\n- Cloud & DevOps: Có kinh nghiệm về Docker, Kubernetes, CI/CD, nền tảng Cloud (AWS/GCP/Azure).\n- Bảo mật: Nắm vững các hệ thống bảo mật tiêu chuẩn, xác thực & ủy quyền (OAuth2, Keycloak, OpenID).\n- Frontend: Kinh nghiệm với Vue.js hoặc framework frontend hiện đại là lợi thế.\n- Khả năng lãnh đạo: Kinh nghiệm quản lý đội ngũ kỹ thuật, hướng dẫn và đào tạo thành viên.\n- Ưu tiên: Ứng viên có kinh nghiệm trong công việc hệ thống dịch vụ công; chính phủ điện tử hoặc các mô-đun dự án lớn.\n- Có kinh nghiệm ứng dụng, sử dụng AI\n- Có kinh nghiệm làm việc trong các dự án theo mô hình Agile\n- Ưu tiên: Giao tiếp tốt (nói/viết) bằng tiếng Anh.\n\nQuyền lợi\n- Mức lương: Lương cứng cạnh tranh + thưởng dự án ( tùy năng lực), trao đổi khi phỏng vấn.\n- Thu nhập: 25.000.000đ – 40.000.000đ + thưởng dự án.\n- Các chế độ khác theo quy định của Công ty.\n\nĐịa điểm làm việc\n- Hà Nội: BT4 đường Bùi Xuân Phái, Phường Mỹ Đình 2, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2901, 1420, 2, 'Fresher Fullstack Developer (Fluent English)', 'Mô tả công việc\n● Được đào tạo lý thuyết và on job training từ 3 tháng về lập trình Javascript (ReactJS, NodeJS..)\n● Được làm việc với Restful API, GraphQL API\n● Được tham gia làm các dự án thương mại điện tử của các khách hàng quốc tế.\n\nYêu cầu ứng viên\n● Sinh viên năm cuối hoặc đã tốt nghiệp trong lĩnh vực Công nghệ thông tin hoặc các ngành liên quan.\n● Hoặc những ai yêu thích lập trình đã từng viết Code, có tư duy logic tốt, khả năng tự học tốt, Có kiến thức về cấu trúc dữ liệu và giải thuật.\n● Có thể tham gia thực tập fulltime.\n● Tiếng Anh giao tiếp tốt (bắt buộc)\n\nQuyền lợi\n● Nhận trợ cấp bằng tiền mặt hàng tháng theo năng lực lên tới 6.000.000 VND.\n● Cơ hội trở thành nhân viên sau khi hoành thành chương trình đào tạo.\n● Có cơ hội đi onsite tại Châu Âu, Úc, Singapore, Nhật Bản khi trở thành nhân viên.\n● Được làm trong môi trường Văn hóa chuyên nghiệp, trẻ trung và năng động.\n● Trải nghiệm công nghệ mới nhất về Thương mại điện tử.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Handico, đường Phạm Hùng, phường Mễ Trì, Nam Từ Liêm\n- Đà Nẵng: Tầng 6, Tòa nhà G8 Golden, 65 Hải Phòng, phường Thạch Thang, Hải Châu\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:15)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2902, 155, 2, 'Tư Vấn Phát Triển Phần Mềm Website', 'Khai thác thông tin khách hàng thông qua data công ty cung cấp kết hợp tìm kiếm thêm (có leader đồng hành cùng). Thiết lập cuộc gọi, tư vấn, giới thiệu sản phẩm và dịch vụ cho khách hàng. Đàm phán, thương lượng, thực hiện các thủ tục ký kết hợp đồng với khách hàng. Xây dựng, duy trì mối quan hệ tốt với khách hàng. Chăm sóc khách hàng trong quá trình sử dụng sản phẩm để đạt hiệu quả sử dụng tốt nhất và tư vấn nâng cấp sản phẩm. Cung cấp thông tin về nhu cầu hành vi, phản hồi của khách hàng cho bộ phận liên quan. Tham gia đóng góp thông tin để phát triển, cải tiến sản phẩm.\n\nYêu cầu ứng viên:\nGiọng nói dễ nghe, tự tin. Kỹ năng giao tiếp qua điện thoại tốt. Nhiệt tình, vui vẻ hỗ trợ khách hàng. Kinh nghiệm được đào tạo.\n\nThu nhập:\nThu nhập khi đạt 100% KPI: 10 - 15 triệu VND. Thu nhập tính theo tỷ lệ đạt KPI. Lương cứng phụ thuộc vào doanh số.\n\nQuyền lợi:\nĐược hưởng các chế độ, phúc lợi theo quy định của Luật lao động. Được hỗ trợ, đào tạo kỹ năng công việc. Xét tăng tiến khi có thành tích tốt. Tham gia vào các hoạt động tập thể, du lịch, team building.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Toà nhà Saigon Tel, Khu Phần mềm Quang Trung, Quận 12.\n- Hồ Chí Minh: Gò Vấp.\n- Hồ Chí Minh: Củ Chi.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00), sáng thứ 7 08:00 - 12:00.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2903, 1130, 2, 'Middle Android Developer', 'Mô tả công việc\n- Tham gia vào toàn bộ vòng đời phát triển sản phẩm, từ lên ý tưởng, thiết kế, phát triển đến triển khai và bảo trì ứng dụng di động trên cả hai nền tảng Android.\n- Phối hợp trực tiếp với Development Lead để triển khai các tác vụ công việc hàng ngày.\n- Tối ưu hiệu năng (performance) và trải nghiệm người dùng (UX/UI) cho ứng dụng, đảm bảo khả năng đáp ứng lượng truy cập lớn (2 triệu MAU).\n- Xây dựng và triển khai các tính năng mới, đồng thời cải tiến các tính năng hiện có dựa trên phản hồi của người dùng và phân tích dữ liệu.\n- Đề xuất và áp dụng các giải pháp kỹ thuật, công nghệ mới (nếu có).\n- Phối hợp với Product Manager, UI/UX Designer và các thành viên khác trong team để thực thi roadmap sản phẩm.\n- Chủ động học hỏi, nâng cao kiến thức chuyên môn và có cơ hội chia sẻ, hướng dẫn các thành viên junior trong đội ngũ.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc chuyên ngành liên quan.\n- Từ 3-5 năm kinh nghiệm làm việc trong lĩnh vực phát triển ứng dụng di động.\n- Thành thạo ngôn ngữ lập trình và nền tảng: Kotlin cho phát triển Android.\n- Có kinh nghiệm làm việc với các ứng dụng có quy mô lớn, lượng người dùng cao và hiểu biết về các thách thức liên quan.\n- Hiểu biết về tối ưu hiệu năng (performance optimization) và quản lý bộ nhớ (memory management) trên nền tảng di động.\n- Có tư duy sản phẩm tốt, khả năng phân tích và giải quyết vấn đề kỹ thuật một cách hiệu quả.\n- Tinh thần trách nhiệm cao, chủ động trong công việc, có khả năng làm việc độc lập và phối hợp nhóm tốt.\n\nƯu tiên (điểm cộng) nếu ứng viên có:\n- Có kinh nghiệm làm việc với Flutter để phát triển ứng dụng cross-platform, sử dụng các công cụ phân tích như Firebase Analytics, Crashlytics.\n- Hiểu biết về A/B testing và các phương pháp tối ưu hóa tỷ lệ chuyển đổi.\n- Kiến thức về App Store Optimization (ASO), chiến lược push notifications để tăng tương tác người dùng.\n- Kinh nghiệm làm việc với caching mechanisms, tối ưu database, và API cho ứng dụng di động.\n\nQuyền lợi\n1.  Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án\n- Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm theo năng lực.\n2.  Chế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn\n- Tham gia BHXH sau thử việc, 12 ngày phép năm.\n- Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ.\n- Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết...\n- Học miễn phí các sản phẩm ngôn ngữ của công ty.\n3.  Cơ hội phát triển bản thân\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Môi trường product đi sâu chuyên môn về mobile app, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác marketing, sales, chăm sóc khách hàng và khách hàng\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp\n- Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6.\n\nĐịa điểm làm việc\n- Hà Nội: 315 Trường Chinh, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2904, 1418, 2, 'Nhân Viên Lập Trình Vận Hành Máy CNC - Thu Nhập Hấp Dẫn Lên Đến 15 Triệu', '– Tiếp nhận bản vẽ kỹ thuật từ bộ phận kỹ thuật hoặc quản lý trực tiếp.\n– Lập trình gia công chi tiết trên phần mềm CAM (VD: HyperMill, MasterCAM...)(lập trình)\n– Mô phỏng kiểm tra đường chạy dao trước khi xuất chương trình.\n– Chuẩn bị dao cụ, gá kẹp, setup phôi đúng theo hướng dẫn.\n– Thiết lập máy CNC: gốc tọa độ, offset dao, kiểm tra chương trình (vận hành).\n– Chạy chương trình gia công, giám sát trong quá trình cắt.\n– Phối hợp với kỹ thuật và lập trình khi có lỗi phát sinh để xử lý kịp thời.\n\n1. Trình độ học vấn:\n + Tốt nghiệp Trung cấp, Cao đẳng ngành Cơ khí, Cắt gọt kim loại, hoặc các ngành liên quan.\n2. Kỹ năng chuyên môn:\n + Biết phần mềm CAM (ưu tiên biết HyperMill, MasterCAM,......................).\n + Hiểu biết về công nghệ cắt gọt kim loại, vật liệu, dao cụ.\n + Biết cách tính toán và tối ưu hóa thông số cắt.\n + Có khả năng đọc hiểu bản vẽ kỹ thuật (2D, 3D).\n + Có kinh nghiệm xử lý lỗi trong quá trình lập trình và vận hành.\n3. Kinh nghiệm:\n + Có kinh nghiệm lập trình máy phay CNC (3 trục trở lên).\n + Ưu tiên ứng viên từng làm trong lĩnh vực gia công cơ khí chính xác, khuôn mẫu, chi tiết máy phức tạp.\n4. Phẩm chất cá nhân:\n + Tư duy logic, cẩn thận, có tinh thần trách nhiệm cao.\n + Chủ động trong công việc và phối hợp tốt với các bộ phận khác.\n + Sẵn sàng học hỏi và cải tiến liên tục.\n + Độ tuổi yêu cầu: dưới 35 tuổi.\n\n– Lương: 8,000,000 - 15,000,000 triệu theo năng lực + phụ cấp trách nhiệm.\n– Làm việc theo giờ hành chính hoặc theo ca (nếu có).\n– BHXH, BHYT, BHTN đầy đủ sau khi ký HĐLĐ chính thức.\n– Môi trường làm việc chuyên nghiệp, nhiều cơ hội phát triển.\n\n– Hà Nội: Lô 05/9B KCN Hoàng Mai,, Hoàng Mai\n\n– Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hoàng Mai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2905, 1335, 2, 'Lập Trình Viên - Data Engineer', 'Mô tả công việc\n- Cung cấp nhân sự xây dựng, thiết kế các luồng dữ liệu từ khâu tổng hợp số liệu từ Corebanking T24, ETL về Datawarehouse, đến việc chuyển giao cho các vị trí phân tích dữ liệu, khoa học dữ liệu.\n- Nhân sự phát triển, sửa đổi các báo cáo quản trị, báo cáo tuân thủ.\n\nYêu cầu ứng viên\n- Thành thạo ngôn ngữ SQL.\n- Thành thạo sử dụng các công cụ: Confluent, MinIO, Kafka, Iceberg, Dremio, GoldenGate.\n- Hiểu biết sâu về kiến trúc dữ liệu Corebanking T24.\n- Có kiến thức về cơ sở dữ liệu: Oracle, SQL.\n- Có kiến thức về PL/SQL, Oracle Function, Procedure, Package.\n- Có kiến thức về SAP Business Object là lợi thế.\n\nQuyền lợi\n- Chế độ thưởng theo quý, năm; tiền quà các ngày Lễ, Tết, ngày thành lập Tập đoàn; hỗ trợ chi phí nghỉ dưỡng hằng năm.\n- Hưởng Bảo hiểm Xã hội, Bảo hiểm Y tế theo quy định của Luật Lao động và công ty.\n- Làm việc trong môi trường chuyên nghiệp, sáng tạo, cạnh tranh, phát triển, năng động có nhiều cơ hội thăng tiến.\n- Cơ hội học tập, nghiên cứu, làm việc trong nước và các nước trên thế giới.\n- Cơ hội tiếp cận với nhiều công nghệ mới.\n- Cơ hội thăng tiến, phát triển bản thân.\n\nĐịa điểm làm việc\n- Hà Nội: Số 112, Đường Chùa Võ, Khu đô thị Dương Nội, Hà Đông.\n- Hà Nội: Hoàng Cầu, Đống Đa.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00).\n- Thứ 7 (từ 08:00 đến 12:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hà Đông, Đống Đa', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2906, 1144, 2, 'Middle Ruby On Rails', 'Mô tả công việc\n- Participate in the development and maintenance of web applications based on Ruby on Rails.\n- Participating in requirements analysis, building solutions, developing software according to requirements customer demand.\n- Research and learn the features to provide customers with comprehensive solutions.\n\nYêu cầu ứng viên\n- At least 3 year of experience programming in Ruby on Rails.\n- Knowledge of SQL & NoSQL database systems.\n- Strong knowledge of Web (HTML, CSS, Javascript) and OOP.\n- Good use of source code management tools: SVN, GIT.\n- Experience in project development according to Agile/Scrum model.\n- Promote responsibility in work, good product quality awareness.\n- Passion for research, learning new technologies, self-development.\n- English level B1 or higher.\n\nQuyền lợi\n- Income upto 25M.\n- 2-month probation with 100% salary.\n- Participate in social insurance, health insurance, unemployment insurance according to the provisions of the labor law.\n- Salary review twice a year.\n- Receive 13th month salary, bonuses for holidays, New Year, weddings, birthdays, etc.\n- Support for certification exam costs according to the company\'s regulations.\n- Participate in VBI insurance.\n- Parking allowance.\n- Seniority allowance, excellent project bonus.\n- Annual travel and vacation according to the company\'s policy.\n- Annual health check-up.\n- Clear promotion opportunities.\n- Opportunities to work in partner countries: Japan, Korea, Singapore, Australia...\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 10F Mekong Tower, 235 Cong Hoa, Ward 13, Tân Bình.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2907, 1257, 2, 'Japanese Engineer', 'We are seeking a highly skilled Japanese Engineer to join our Vietnam-based development teams in a Senior Engineer/Tech Lead capacity. This role is pivotal in facilitating seamless collaboration between Japanese clients and the Vietnamese development team. The successful candidate will drive project execution, ensure the delivery of high-quality solutions, and contribute to the growth of a dynamic, cross-cultural development environment.\n\nWhat to do:\n- Join actual projects as a Tech Lead, working closely with the Vietnam engineering team.\n- Provide technical mentorship, guidance, and drive decision-making within the project.\n- Identify challenges that are hard to detect from Japan side and propose process and quality improvements.\n- Introduce tools and methodologies to improve development efficiency.\n- Design and execute training plans to upskill local engineers.\n\nPersonal Requirements:\n- Age Range: Late 20s to early 40s (Flexible). Candidates should be adaptable and open to integrating into local life.\n- Career Orientation: Motivated to build a long-term career abroad, gain hands-on IT experience, and grow in a global working environment.\n- Personality Traits: Positive, open-minded, and collaborative. Must be respectful of diverse perspectives and capable of working effectively in multicultural teams.\n- Language Skills: Proficiency in English (equivalent to TOEIC 700 or above) or fluent Vietnamese is required.\n\nSkills Requirements:\n- IT Experience:\n  - 7+ YoE in web or mobile application development (at least one specific technology stack).\n  - 7+ YoE working in cloud environments (AWS, Azure, or GCP).\n  - Hands-on experience with DevOps practices (CI/CD, Docker, etc.).\n  - Strong communication and cultural adaptability.\n  - Desire to grow in a global, cross-cultural environment.\n\n- Nice to have:\n  - Experience with cutting-edge technologies such as AI or Web3.0.\n  - Familiarity with modern engineering practices in a cross-border team setting.\n- Negotiation Skills: Capable of facilitating agreements and aligning expectations between clients and engineering teams.\n- Technical Knowledge: Basic understanding of web application architecture, databases, and IT infrastructure.\n- Business Understanding: Ability to comprehend client business models, operational structures, and key challenges.\n\nCompetitive Salary – Deserved Rewards:\n- Attractive salary, aligned with your skills and contributions.\n- Salary review twice a year to recognize your dedication.\n- Generous year-end bonus, based on individual performance.\n\nComprehensive Healthcare – We Care About You:\n- Premium health insurance package for extra protection.\n- Annual health check-ups at top-tier hospitals.\n- 20 days of annual leave, ensuring a healthy work-life balance.\n\nModern & Innovative Work Environment:\n- Equipped with MacBook/Laptop & the latest technology to enhance productivity.\n- Modern office design with open spaces, fostering creativity and collaboration.\n\nPersonal Development – Unlimited Growth Opportunities:\n- Sponsored international certification exams, supporting professional advancement.\n- Specialized training courses & soft skills development to enhance expertise.\n- Flat organizational structure, enabling direct collaboration with leaders and fostering creativity and innovation.\n\nAgile Mindset – People-Centric Growth:\n- Open, flexible, and supportive work culture, driving collective success.\n- Stronger team connections, creating a dynamic and efficient workplace.\n\nWork Hard – Play Hard:\n- Exciting activities: Open Talks, IT Seminars, Team Building, Project Trips, Sports Day, Year-End Parties…\n- Diverse entertainment: PlayStation, Friday Happy Hours, Mindfulness-related activities…\n\nFlexible Working Hours:\n- Monday - Friday: 8:00 AM - 11:30 AM | 1:00 PM - 5:30 PM.\n\nJoin TechTus, where we work HAPPILY to achieve our DREAMS together!', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2908, 1450, 2, 'Backend Developer', 'Mô tả công việc\n- Design and implement RESTful APIs\n- Build and deploy performant modern web applications in Golang, Rust, Nodejs, ...\n- Build a high-performance and optimized backend system to meet large volumes of traffic.\n- Architect efficient and scalable backend systems\n- Write unit, functional and end-to-end tests\n- Write high-quality code (Go, Rust, NodeJS) that communicates with upstream backend services via HTTP/GRPC APIs\n- Identify and resolve performance and scalability issues\n- Participate in code reviews\n- Participate in research on optimal solutions, and system security; contribute ideas on technology and products\n\nYêu cầu ứng viên\nMust have:\n- At least 1 year of server-side programming (Experience level)\n- Understand CS fundamentals (algorithms and data structures, operating systems, networks, databases, etc)\n- Familiar with common network protocols (TCP, UDP, HTTP) and network programming;\n- Good knowledge of both RDB and NoSQL.\n- Familiar with Linux development environments and multi-threaded programming;\n- Familiar with Version Control System (GIT)\n- Proficiency in at least one programming language – Golang, Rust, Nodejs\n\nNice to have:\n- Having worked with Blockchain, Cryptocurrencies, and/or high-access responsive systems is a big plus\n- Building data lake and analytics skills (Metabase, Dune, BigQuery, Data Studio)\n- Knowledge of information safety and security is an advantage.\n- Strong problem-solving, interpersonal, and communication skills\n- Experience in Docker/Kubernetes and Cloud Infrastructure is a plus\n- Able to work with a team as well as independently.\n- Have spirit, responsibility, and initiative in work.\n\nQuyền lợi\n- Development opportunities:\n    - Working in an environment with talented engineers who have experience in developing products in the field of Fintech, Blockchain, Cryptocurrencies.\n    - Take a key role in building the project from the very beginning;\n    - Technical and professional training throughout the working process.\n- Remuneration:\n    - Earn up to $2000, 13th-month bonus, performance bonus according to the company\'s business situation.\n    - Flexible working hours: 9:00-18:30 Monday-Friday, 1h30-minute lunch break\n    - Labor contract and all benefits prescribed by the state (pay social insurance, health insurance, unemployment insurance);\n    - 16 days leave, 4 days sick leave with full salary;\n    - PVI Healthcare Insurance;\n    - Annual health check at a reputable hospital;\n    - Equipment for work;\n    - Daily lunch, happy hour every Thursday, and monthly team outing;\n    - Chillax office with gym, swimming pool, free snacks & drink all day;\n    - Travel - vacation at least once a year at domestic and international 5-star resorts.\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes West Point, Pham Hung Street, Me Tri Ward, Nam Tu Liem, Ha Noi, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2909, 111, 2, 'Front End Developer', 'Mô tả công việc\n• Phát triển và duy trì ứng dụng mobile/web sử dụng Flutter.\n• Tham gia thiết kế UI/UX, tối ưu hiệu năng và trải nghiệm người dùng.\n• Phối hợp với team backend để xây dựng API tích hợp hệ thống.\n• Có thể đảm nhận các tác vụ backend đơn giản (Node.js/NestJS) nếu cần.\n• Viết unit test, xử lý bug và cải tiến sản phẩm theo feedback người dùng.\n• Tham gia góp ý và cải thiện quy trình phát triển.\n\nYêu cầu ứng viên\n• Tối thiểu 1 năm kinh nghiệm phát triển Flutter (iOS, Android, Web).\n• Tốt nghiệp Đại học chuyên nghành KTPM, CNTT, HTTT, CNPM, KHMT của các trường UIT, Bách khoa, KHTN, BCVT, SPKT.\n• Nắm chắc kiến thức nền, thuật toán và giải thuật.\n• Thành thạo Dart và tư duy OOP tốt.\n• Hiểu vững cấu trúc Flutter: Widget tree, lifecycle, state management (BLoC).\n• Thiết kế UI tương thích nhiều thiết bị và độ phân giải (responsive, theme, animation,..)\n• Hiểu biết về tích hợp RESTful API, Routing, Navigation, Notification, Local Database.\n• Có kiến thức hoặc kinh nghiệm làm việc với Node.js/NestJS là một lợi thế.\n• Biết làm việc với Firebase, Firestore, hoặc các cloud service là điểm cộng.\n• Có tư duy sản phẩm, chủ động và ham học hỏi.\n\nQuyền lợi\n• Lương: 10.000.000 - 15.000.000 VND/tháng.\n• Môi trường làm việc trẻ, năng động.\n• Làm việc với sản phẩm thật, có lượng người dùng lớn.\n• Được training hoặc phát triển kỹ năng backend nếu mong muốn.\n• Hỗ trợ thiết bị làm việc (Mac mini, màn hình).\n• Review lương 6 tháng 1 lần.\n• Được đóng BHXH, BHYT, BHTN theo quy định của nhà nước sau 2 tháng thử việc.\n• Trả lương đều đặn từ 1-10 hàng tháng. Không nợ lương + thưởng của nhân viên.\n• Thưởng tháng 13 + thưởng nhân viên xuất sắc cuối năm.\n• Tham gia chơi thể thao với công ty hàng tuần.\n• Team building và du lịch hàng năm.\n• Phúc lợi tăng theo sự phát triển của Công ty.\n• Các chế độ khác: Theo Luật lao động Việt Nam, theo nội quy lao động và Quy định tài chính của công ty.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Nhà A, Khu công nghệ Phần mềm ĐHQG TPHCM, KP 6, Phường Linh Trung, Thủ Đức.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 18:00).\nSáng thứ 7 làm việc online.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2910, 1419, 2, 'Nhân Viên Lập Trình CNC', '- Lập trình cho máy CNC\n- Kiểm tra chi tiết gia công\n- Khai báo và kiểm soát Job\n- Báo giá chi tiết sửa chữa, thay thế\n- Liên hệ với nhà cung cấp nguyên vật liệu, dụng cụ.\nCông việc chi tiết trao đổi trong buổi phỏng vấn\nĐịa chỉ làm việc: Số 55 Ích Thạnh, phường Trường Thạnh, Tp. Thủ Đức', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh & 2 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2911, 1360, 2, 'Lập Trình Viên Backend', 'Mô tả công việc:  - Xây dựng API và microservices: Thiết kế, triển khai và duy trì API hiệu suất cao.  - Phát triển hệ thống backend: Xây dựng các giải pháp backend mạnh mẽ và tối ưu.  - Tích hợp với hệ thống khác: Làm việc cùng các nhóm Frontend và AI để đảm bảo tích hợp hiệu quả.  - Quản lý dữ liệu và bảo mật: Đảm bảo hệ thống có tính bảo mật và hiệu suất cao.  - Hỗ trợ phát triển AI: Tham gia vào các dự án liên quan đến chatbot, NLP, machine learning, deep learning, computer vision.\n\nYêu cầu ứng viên:  - Kinh nghiệm Python: Ít nhất 1 năm kinh nghiệm lập trình với Python trong phát triển backend.  - Kinh nghiệm API: Thành thạo trong việc xây dựng API trên RESTful API, GraphQL và kiểm thử API trên Postman.  - Microservices: Có hiểu biết về microservices và các công cụ như Docker, Kubernetes.  - Machine Learning/AI: Có kinh nghiệm về NLP, Chatbot, Computer vision, Machine learning, Deep learning là lợi thế.  - Cơ sở dữ liệu: Kinh nghiệm làm việc với ChromaDB, PostgreSQL, NoSQL (Qdrant, MongoDB, Redis...).  - Cloud Services: Có hiểu biết về các cloud như AWS, Google Cloud, Azure hoặc triển khai On-premises.  - Code Quality: Nắm vững các best practices về clean code, reusable code, và unit testing.\n\nƯu tiên:  - Kinh nghiệm thực tế triển khai các giải pháp AI solutions như đọc tài liệu từ các định dạng .doc, .pdf, .xls..., đọc hình ảnh (image2text), hoặc đọc âm thanh (audio2text).  - Kinh nghiệm làm việc với CI/CD, Jenkins, Travis CI.  - Hiểu biết về Agile, Scrum, DevOps.\n\nQuyền lợi:  - Lương thỏa thuận theo kinh nghiệm và năng lực.  - KPI tương ứng với 5 tháng lương thực nhận.  - Tháng lương thứ 13.  - Thưởng dự án theo các dự án tham gia.  - Đặc biệt chia cổ tức cho cán bộ nhân viên theo lợi nhuận của công ty.  - Tham gia các khóa đào tạo kỹ năng mềm phục vụ cho công việc.  - Thưởng các dịp lễ, Tết và team building hàng năm.  - Xét duyệt tăng lương 2 lần/năm.  - Được hưởng đầy đủ BHXH, BHYT và BHTN theo luật lao động Việt Nam hiện hành.  - Được làm việc trong một môi trường trẻ trung, năng động cùng với các chuyên gia hàng đầu trong nhiều lĩnh vực của công ty để học hỏi và phát triển hàng ngày.  - Cơ hội làm việc với các tập đoàn lớn: Tham gia các dự án lớn, làm việc với các khách hàng và đối tác uy tín trong ngành công nghệ trong và ngoài nước.\n\nĐịa điểm làm việc:  - Hà Nội: Tòa nhà N03-T3, Khu Ngoại Giao Đoàn, Phường Xuân Tảo, Bắc Từ Liêm.\n\nThời gian làm việc:  - Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:  - Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2912, 1127, 2, 'Giáo Viên 3D Unity Game Part Time', 'Mô tả công việc\n● Tham gia giảng dạy khóa đào tạo Unity Game Developer theo nội dung và lộ trình của Green Academy.\n● Thiết kế slide và giáo trình giảng dạy cho các buổi học. (Có thể tham khảo sử dụng giáo trình hiện tại của trung tâm).\n● Hướng dẫn học viên làm đồ án cuối khóa, đảm bảo chất lượng đầu ra của học viên.\n\nYêu cầu ứng viên\n● Tốt nghiệp Đại học / Cao đẳng chuyên ngành liên quan đến Công Nghệ Thông Tin.\n● Đã và đang làm việc trong lĩnh vực phát triển Game với UNITY từ 3-4 năm.\n● Có kinh nghiệm và kiến thức liên quan đến xây dựng các thể loại game 2D & 3D.\n● Khả năng thuyết trình, truyền đạt kiến thức và nghiên cứu giảng dạy là một lợi thế.\n● Có tinh thần trách nhiệm cao với công việc.\n\nQuyền lợi\n● Lương giờ dạy: 220-250k/h.\n● Giảng dạy và làm việc trong môi trường chuyên nghiệp mang văn hóa Việt – Hàn.\n● Thời gian dạy được sắp xếp linh động theo lịch.\n● Hỗ trợ củng cố kiến thức chuyên môn và nghiệp vụ liên quan trước khi nhận lớp.\n● Hợp đồng Lao động theo đúng quy định của Luật lao động Việt Nam.\n● Được cung cấp đầy đủ các trang thiết bị giảng dạy hiện đại và tiện nghi theo đúng tiêu chuẩn của Green Academy Hàn Quốc.\n● Hỗ trợ chi phí giữ xe tại trung tâm.\n\nĐịa điểm làm việc\n- Hà Nội: 201 Trường Chinh, Thanh Xuân.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2913, 1308, 2, 'Nhân Viên Lập Trình', 'Mô tả công việc:\n- Tham gia các dự án phát triển các dự án Website, thương mại điện tử;\n- Nghiên cứu các công nghệ mới, hỗ trợ phát triển, khắc phục lỗi hệ thống;\n- Xây dựng và chỉnh sửa các module, tính năng theo yêu cầu;\n- Các công việc khác theo phân công của cấp trên.\n\nYêu cầu ứng viên:\n- Có kiến thức về codegym \n- Có kinh nghiệm lập trình Backend sử dụng java;\n- Có kinh nghiệm lập trình Front end (web) trên nền tảng Spring framework;\n- Ưu tiên người có kinh nghiệm về một trong các nền tảng Spring framework, Angular, AngularJs, React;\n- Có khả năng sử dụng query cơ bản trên MySQL, Oracle;\n- Có khả năng sử dụng Shell Script và câu lệnh cơ bản trên Linux.\n- Cẩn thận, kiên nhẫn, đam mê lập trình và sẵn sàng học hỏi các công nghệ mới.\n- Chịu được áp lực công việc.\n- Có kỹ năng phân tích và giải quyết vấn đề, có khả năng làm việc độc lập và theo nhóm.\n\nQuyền lợi:\n- Mức lương cạnh tranh: 10 – 20M.\n- Con đường sự nghiệp vững vàng, môi trường làm việc năng động, nhanh nhẹn.\n- Được đào tạo theo định hướng công việc của Công ty và nhu cầu đề xuất cá nhân.\n- Thưởng KPI, Thưởng dự án, Thưởng hiệu quả công việc, thưởng cuối năm tháng 13+++…\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc.\n- Được hưởng BHXH, BHYT, BHTN theo chế độ nhà nước ban hành.\n- Khám sức khỏe định kỳ 1 năm/1 lần.\n- Được tham gia các hoạt động thể dục thể thao như: Bóng đá, cầu lông,…\n- Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding thường xuyên.\n- Làm việc từ thứ 2 đến thứ 6, nghỉ thứ 7 và CN;\n- 12 ngày phép/năm và các ngày nghỉ lễ - tết theo quy định;', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2914, 1129, 2, 'Game Developer', 'Tại Nexar, các Developer là trái tim của các dự án, nhân sự sẽ làm việc và phối hợp với tất cả các team để tạo ra những trải nghiệm mới mẻ, những dòng game độc đáo, những sản phẩm chất lượng. Vì thế, chúng tôi đánh giá cao những Developer có chuyên môn tổng quát, có thể làm việc trên nhiều lĩnh vực khác nhau trong quá trình phát triển trò chơi. Bên cạnh đó, bạn sẽ là người suy nghĩ chiến lược, sẵn sàng đưa ra các quyết định khôn ngoan dựa trên các mục tiêu rõ ràng.\n\nTrách nhiệm\n- Phối hợp cùng các thành viên bộ phận khác lên kế hoạch, xây dựng và phát triển game bằng Unity engine.\n- Sửa lỗi, cải thiện tính năng, nâng cao hiệu suất của games.\n- Tham gia đóng góp ý tưởng, nội dung để tối ưu hóa sản phẩm.\n\nYêu cầu ứng viên\n- Đam mê tuyệt đối và mong muốn phát triển chuyên sâu với công việc phát triển trò chơi.\n- Có hiểu biết về C++, nền tảng về kiến trúc máy tính, lập trình đồ họa máy tính, tốt nghiệp các trường đại học chuyên ngành CNTT là một lợi thế.\n- Có kiến thức về thuật toán và cấu trúc dữ liệu, đọc hiểu tiếng Anh, thành thạo ngôn ngữ lập trình C#.\n- Có ít nhất 1 năm kinh nghiệm phát triển game với Unity.\n- Khả năng tư duy logic, phát triển, sáng tạo và cải tiến trong công việc.\n- Ham học hỏi, tự chủ, trách nhiệm trong công việc.\n- Ưu tiên các ứng viên có mong muốn phát triển theo hướng khai phá, nghiên cứu kỹ thuật, công nghệ để áp dụng vào phát triển sản phẩm, tạo lợi thế cạnh tranh trên thị trường.\n\nQuyền lợi\n- Văn hoá làm việc tự chủ, linh hoạt trong việc nghỉ phép và giờ giấc. Trách nhiệm và sự hiệu quả trong công việc là điều chúng tôi quan tâm hơn.\n- Môi trường năng động và chuyên nghiệp thuận lợi cho mục tiêu phát triển sự nghiệp bền vững cũng như nâng cao năng lực chuyên môn.\n- Luôn có những người bạn buddy và mentor giàu kinh nghiệm, sẵn sàng hỗ trợ và dẫn dắt bạn.\n- Mức lương offer: $500 - $1500 Tùy theo kiến thức, kinh nghiệm và tiềm năng phát triển của bạn.\n- Chia sẻ lợi nhuận theo dự án không giới hạn, không tỉ lệ thuận với kiến thức hay kinh nghiệm, nó sẽ phụ thuộc phong độ và sự đóng góp của bạn trong việc tạo ra giá trị cho công ty.\n\nĐịa điểm làm việc\n- Hà Nội: Tháp Thiên Niên Kỷ, Số 4 Quang Trung, Quang Trung, Hà Đông\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2915, 1125, 2, 'Lập Trình Viên Frontend', 'Mô tả công việc: Phát triển giao diện người dùng (UI/UX) cho các sản phẩm/phần mềm của công ty liên quan đến đầu tư chứng khoán, đào tạo trực tuyến, v.v. Chuyển đổi thiết kế (wireframes, mockups) thành các tính năng, trang web, ứng dụng web có tính tương tác cao, mượt mà và hiệu năng tốt. Tích hợp giao diện front-end với back-end thông qua API. Ứng dụng các công cụ lập trình AI để tối ưu trải nghiệm hoặc giao diện người dùng khi cần. Phối hợp chặt chẽ với team thiết kế (designer), back-end, QA để đảm bảo chất lượng sản phẩm. Nghiên cứu và đề xuất các công nghệ, framework front-end phù hợp với xu hướng mới.  Yêu cầu ứng viên: Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các ngành liên quan; hoặc tốt nghiệp đại học ngành khác nhưng có tối thiểu 2 năm kinh nghiệm lập trình front-end. Thành thạo các ngôn ngữ và công nghệ front-end: HTML, CSS, JavaScript (Ưu tiên biết thêm các framework như React, Angular hoặc Vue). Có kinh nghiệm về responsive design, đảm bảo sản phẩm chạy tốt trên đa nền tảng, đa thiết bị. Biết sử dụng các công cụ lập trình AI hoặc đã làm qua các dự án có ứng dụng AI là lợi thế. Ưu tiên ứng viên đã tham gia dự án thực tế, có khả năng tối ưu hiệu năng và trải nghiệm người dùng. Tinh thần học hỏi cao, tư duy logic, làm việc nhóm hiệu quả.  Quyền lợi: Cơ hội tham gia vào các dự án công nghệ và sản phẩm sáng tạo, đa lĩnh vực. Lương cạnh tranh, thưởng theo năng lực và đóng góp. Môi trường làm việc trẻ trung, chuyên nghiệp, khuyến khích tư duy đổi mới và tự do sáng tạo. Cơ hội phát triển nghề nghiệp, nâng cao kỹ năng chuyên môn và quản lý. Tham gia đầy đủ bảo hiểm và các chế độ phúc lợi khác.  Địa điểm làm việc: Hà Nội: 37 Lê Văn Thiêm Phường Nhân Chính, Thanh Xuân  Thời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00) 8h-17h, T7 ngày lẻ.  Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2916, 1193, 2, 'Mobile Developer', 'Headquarter: Daoukiwoom Group\n\nIndustry: Finance & Trading\n\n- Develop Mobile Stock Trading app using JavaScript under the Kiwoom platform\n- Work directly with remote team to clarify tasks and requirements\n- Develop new features based on the user requirements (analyzing requirements and system design)\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance\n- Managing time and resources based on the WBS\n- Compile a weekly-report about the progress of tasks\n- Perform self-learning about a domain knowledge, write a report and conduct a seminar about it\n- Write high-quality, clean, elegant, maintainable, and testable code\n- Maintaining technical documents up-to-date\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the KiwoomFramework for KiwoomIndonesia, Finansia (in Thailand), and so on.\n\nYêu cầu ứng viên\n\nEducation & Experience\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Minimum 3 years of professional experience in mobile app development using JavaScript or iOS/Android native.\n- Experience and knowledge in markup language, including HTML, CSS is a must.\n- Ability to write clean, easy to understand code.\n- Familiarity with version control systems, such as Git or SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n- Solid understanding of the full mobile development life cycle\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nSoft Skills & Communication\n- Strong problem-solving and analytical skills.\n- Able to communicate in English, written and spoken.\n- Strong communication skills and teamwork, international experience is preferred.\n\nNice to have:\n- Over 1 year of experience in developing securities solutions, including a smartphone-based trading platform utilizing the Mobile Trading System (MTS)\n- Proficient in utilizing the Mobile development Framework (Ionic, PhoneGap, React, Vue, Nexacro)\n- Experience on working with oversea team.\n\nQuyền lợi\n\nIncome & Achievement \n- Competitive salary, salary review once a year\n- 13th month salary and Annual Performance Bonus\n- MVP and Shining star awards at the end of year\n- Global and professional working environment\n\nWorkplace Happiness \n- Full SHUI as Vietnamese Law\n- Premium Private Medical Insurance PVI and annual health check\n- 15-day annual leave, Christmas leave and 30-min menstrual leave for women\n- Company trip, YEP and monthly gathering time\n- Gifts on special occasion and fully stocked snack corner\n- Sponsored training courses and book purchase quarterly\n- Be well-equipped with new working equipment\n\nSpecial Offer\n- Providing training and education experience in Korea with Korean Finance/IT expert\n- Providing opportunities to work and support in IT/Finance fields overseas.\n\nHIRING PROCESS: The interview will be conducted at our office in Ho Chi Minh city.\n\nRound 1:\n- Step 1: Live coding test\n- Step 2: Interview with part team leader (upon passing coding test)\n- Step 3: Interview with Director\n\nRound 2: Final interview with Head Office in Korea\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tầng 14, tòa nhà AP, 518B Điện Biên Phủ, Phường 21, Bình Thạnh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2917, 1170, 2, 'PHP Developer (CodeIgniter/Laravel + React/NextJS) Upto 30M', 'Mô tả công việc\n- Develop, test, and maintain high-performance web applications using PHP (CodeIgniter 3 or Laravel).\n- Design and integrate RESTful APIs with best practices in architecture and security.\n- Collaborate with frontend developers to build user-friendly interfaces using ReactJS, NextJS, and standard web technologies (HTML, CSS, JavaScript, Ajax).\n- Optimize database queries and application performance (MySQL, PostgreSQL).\n- Participate in analyzing system requirements and business processes.\n- Conduct code reviews, propose improvements, and follow established coding standards.\n- Work in an Agile/Scrum team: attend daily standups, provide updates, and support sprint goals.\n- Use Git (Git Flow) for version control and collaborate through platforms such as GitHub, GitLab, or Bitbucket.\n- Continuously improve system architecture and stay up to date with modern development trends.\n\nYêu cầu ứng viên\n- Bachelor’s degree in Information Technology, Computer Science, or a related field.\n- At least 3 years of experience developing web applications (ERP, CMS, or eLearning platforms).\n- Proficient in PHP, especially with CodeIgniter 3 or Laravel.\n- Solid knowledge of MySQL, PostgreSQL, or similar relational databases.\n- Strong understanding of RESTful APIs, MVC, OOP, ORM, and Microservices architecture.\n- Experience writing unit tests, integration tests, and functional tests.\n- Familiar with ReactJS, Next JS, or other modern frontend frameworks.\n- Skilled in using Git-based workflows and collaborative development tools.\n- Familiar with Agile/Scrum development processes.\n- Self-motivated, responsible, with strong analytical and communication skills.\n- Ability to work independently or as part of a team.\n- Basic English skills: able to read and understand technical documents, write code comments.\n\nPreferred:\n- Experience working in product-based companies.\n- Knowledge of workflows and modules in ERP, CRM, eLearning systems.\n\nQuyền lợi\n- Attractive Compensation & Benefits\n- Competitive salary: Ranges from 15,000,000 to 30,000,000 VND/month, based on qualifications and experience.\n- Free lunch provided at the company for all staff.\n- Full insurance coverage: Participation in health insurance (BHYT), social insurance (BHXH), and unemployment insurance (BHTN) as required by Vietnamese law.\n- Comprehensive internal benefits: Annual company trips, holidays, year-end bonuses, paid leave, birthday celebrations, and team-building activities.\n- Exclusive perks within the company system: Enjoy free or discounted access to various services such as the swimming pool, restaurant, pickleball courts, internal training courses, and more.\n- Annual performance-based salary reviews, ensuring recognition of individual contributions and achievements.\n- Dynamic, professional, and supportive work environment with clear career advancement opportunities and continuous professional development.\n\nĐịa điểm làm việc\n- Hà Nội: 59 Xuân Diệu, Tây Hồ, Tây Hồ\n\nThời gian làm việc\n- Từ T2- sáng T7, chọn thời gian làm: 9h-18h/8h-17h.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2918, 1111, 2, 'Web Developer (Pass Phỏng Vấn, Đi Làm Luôn)', 'Mô tả công việc\n- Xây dựng, thiết kế Website trên nền tảng mã nguồn WordPress.\n- Sử dụng công cụ Elementor để thiết kế và chỉnh sửa giao diện web.\n- Phối hợp và hỗ trợ bộ phận Design của Công ty để tối ưu giao diện Website.\n- Quản lý và bảo trì website.\n- Các công việc chuyên môn khác theo yêu cầu của Trưởng bộ phận.\n\nYêu cầu ứng viên\n- Tốt nghiệp các ngành Thiết kế, Công nghệ thông tin hoặc đã có ít nhất 1 năm kinh nghiệm thiết kế Website Wordpress.\n- Biết sử dụng Figma để thiết kế giao diện.\n- Am hiểu về các tiêu chuẩn thiết kế giao diện và trải nghiệm người dùng.\n- Hiểu biết tối ưu hóa website với công cụ tìm kiếm.\n- Nhạy bén trong việc cập nhật các xu hướng công nghệ mới.\n- Ưu tiên ứng viên có kiến thức về HTML/CSS.\n- Có sản phẩm đính kèm CV.\n\nQuyền lợi\n- Lương CB: 10 – 15tr + Thưởng. (Có thể cao hơn tùy năng lực)\n- Được đề xuất review ngay khi đạt hiệu quả tốt trong công việc.\n- Không giới hạn cơ hội phát triển và thăng tiến lên các vị trí cấp cao.\n- Được đào tạo nâng cao năng lực chuyên môn.\n- Môi trường năng động, không bị gò bó bởi luật lệ, trang phục tùy sở thích.\n- Khu vực Pantry trang bị sẵn đồ uống, đồ ăn nhẹ.\n- 12 ngày nghỉ phép có lương trong năm.\n- Các chế độ theo Luật lao động hiện hành: Bảo hiểm xã hội,… và các phúc lợi: 20/10, sinh nhật, lễ tết,…. theo quy định của công ty.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 3, Lô (5+6+7+23+24+25) Ô C2-NO, tòa nhà văn phòng KĐT Nam Trung Yên, Đường Mạc Thái Tông, Phường Trung Hòa, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)\n- Từ tháng 5 - tháng 10: làm việc từ thứ 2 - thứ 7\n- Từ tháng 11 - tháng 4 năm sau: làm việc từ thứ 2 - thứ 6\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2919, 1324, 2, 'Kỹ Sư Lập Trình Máy CNC (Citizen Cincom L20) - Thu Nhập Từ 30 Đến 50 Triệu VNĐ/Tháng', 'Mô tả công việc:\n- Lập trình gia công chi tiết phức tạp trên máy tiện tự động Citizen Cincom L20 (hệ điều khiển Mitsubishi M70/M700/M850)\n- Viết và hiệu chỉnh chương trình G-code (bao gồm tiện, phay, khoan nghiêng, có trục phụ, dao sống...)\n- Tối ưu đường chạy dao, lựa chọn thông số cắt phù hợp để giảm thời gian chu kỳ và đảm bảo độ chính xác cao\n- Setup dao, định nghĩa zero offset, cấu hình dao sống và cấu hình trục\n- Kết hợp bộ phận thiết kế CAD/CAM để chuyển đổi từ Fusion 360, Mastercam, hoặc bản vẽ kỹ thuật sang mã NC\n- Chạy thử sản phẩm đầu tiên, tinh chỉnh và phê duyệt (first part approval)\n- Theo dõi, cải tiến quy trình khi thay đổi vật liệu hoặc dao cụ\n- Quản lý, backup dữ liệu chương trình và thông tin máy\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng/đại học chuyên ngành Cơ khí, Chế tạo máy, Cắt gọt kim loại, Cơ điện tử\n- Kinh nghiệm tối thiểu 1 năm lập trình máy Cincom (L12, L20, L32...)\n- Thành thạo lập trình tay G-code, đọc hiểu bản vẽ kỹ thuật\n- Ưu tiên ứng viên biết sử dụng CAM (Fusion 360, Mastercam, Esprit...)\n- Có kiến thức về LFV, phay nghiêng (B-axis), dao whirling, tiện vật liệu khó như titanium là lợi thế lớn\n- Tư duy logic, cẩn thận, làm việc nhóm tốt, chịu được áp lực cao\n\nQuyền lợi:\n- Thu nhập: 30 – 50 triệu VNĐ/tháng\n- Phụ cấp kỹ thuật\n- Thưởng theo hiệu suất làm việc\n- Tăng lương theo năng lực\n- Môi trường làm việc sạch sẽ, hiện đại theo tiêu chuẩn y tế – xuất khẩu\n- Được đào tạo chuyên sâu về vận hành và lập trình máy CNC\n- Có cơ hội phát triển lên vị trí kỹ thuật viên lập trình hoặc quản lý nhóm kỹ thuật\n- Đầy đủ chế độ BHXH, BHYT, nghỉ lễ/tết theo quy định nhà nước\n- Hỗ trợ đồng phục, cơm trưa và các điều kiện làm việc tốt\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 170 Nam Kỳ Khởi Nghĩa, P. Võ Thị Sáu, Quận 3\n- Hồ Chí Minh: Khu Công Nghệ Cao, Quận 9\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2920, 38, 2, 'Tech Lead (.Net)', 'Mô tả công việc:\n- Phát triển, kiểm thử và triển khai các ứng dụng phần mềm sử dụng C# và nền tảng .NET\n- Phối hợp với quản lý sản phẩm và kỹ sư phần mềm để thu thập và phân tích yêu cầu\n- Thiết kế, lập trình và gỡ lỗi ứng dụng, đảm bảo khả năng mở rộng, hiệu suất và khả năng bảo trì\n- Tham gia đánh giá mã nguồn và duy trì chất lượng mã theo các tiêu chuẩn lập trình\n- Chẩn đoán và xử lý các sự cố kỹ thuật ở cấp độ ứng dụng/cấu hình/mã nguồn\n- Kiểm thử phần mềm đã phát triển để đảm bảo đáp ứng yêu cầu về dữ liệu, logic và chức năng\n- Tích hợp các API và thư viện bên thứ ba để nâng cao chức năng ứng dụng\n- Khắc phục lỗi và các sự cố phần mềm một cách kịp thời\n- Cập nhật kiến thức về các công nghệ .NET mới nhất và các phương pháp thực hành tốt\n- Đảm bảo tài liệu kỹ thuật được cập nhật đầy đủ và chính xác\n\nYêu cầu ứng viên:\n- Có kinh nghiệm tối thiểu 2 năm ở vị trí tương đương\n- Tốt nghiệp đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật phần mềm hoặc các ngành liên quan\n- Có kiến thức vững về nền tảng ASP.NET\n- Có kinh nghiệm trong toàn bộ vòng đời phát triển phần mềm: từ phân tích yêu cầu đến thiết kế, lập trình, kiểm thử và triển khai\n- Có kinh nghiệm làm việc ở vị trí Lập trình viên .NET hoặc vai trò tương tự\n- Thành thạo C# và nền tảng .NET\n- Có kinh nghiệm phát triển với ASP.NET, MVC và Web API\n- Thành thạo HTML, Java Script/JQuery, CSS, Bootstrap…\n- Hiểu biết và có kinh nghiệm làm việc với SQL Server, Oracle \n- Nắm vững các nguyên lý lập trình hướng đối tượng (OOP)\n- Kỹ năng giải quyết vấn đề tốt và có khả năng làm việc độc lập\n\nQuyền lợi:\n- Thu nhập: 30M - 35M\n- Thời gian làm việc: Thứ 2 – Thứ 6. Nghỉ Thứ 7, Chủ nhật.\n- Nghỉ phép, nghỉ Lễ Tết, đóng BHXH, BHYT, BHTN theo quy định của Luật lao động\n- Review lương định kỳ 1 lần/năm hoặc tùy theo kết quả thực hiện công việc\n- Khám sức khỏe định kỳ tại bệnh viện tiêu chuẩn quốc tế\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 8, tòa nhà Ladeco, số 266 Đội Cấn,Phường Liễu Giai, Ba Đình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2921, 1207, 2, 'Drupal Developer - Từ 3 Năm Kinh Nghiệm - Up To 35 Triệu/Tháng', 'Mô tả công việc\n- Tham gia vào các dự án làm việc với dự án và các đối tác từ Nhật Bản.\n- Xây dựng website sử dụng Drupal, API server sử dụng PHP hoặc các framework liên quan.\n- Tham gia vào dự án xây dựng product riêng của công ty.\n\nYêu cầu ứng viên\n【KỸ NĂNG CẦN THIẾT】\n- Hiểu biết về PHP core. Có kinh nghiệm 3 năm trở lên sử dụng ngôn ngữ PHP trong công việc.\n- Có khả năng làm việc với MYSQL, Bootstrap, JavaScript, HTML, CSS, jQuery...\n- Có 3 năm kinh nghiệm trở lên với framework Drupal\n- Có 2 năm kinh nghiệm trở lên làm việc với Gitlab, github hoặc Bitbucket.\n- Có khả năng viết unit test, document\n- Có tư duy lập trình hướng đối tượng MVC, đọc hiểu tiếng anh tốt để phục vụ cho công việc.\n\n【KỸ NĂNG MONG MUỐN】\n- Có kiến thức liên quan đến Performance của MySQL Statement và Query.\n- Có kinh nghiệm với framework PHP khác là 1 lợi thế như: Laravel,Wordpress, Cakephp, EC-CUBE, Yii...\n- Có kiến thức về Linux, Windows OS.\n- Những ứng viên có kinh nghiệm sử dụng Docker để phát triển.\n- Có kiến thức về UML.\n- Ưu tiên những ứng viên sẵn sàng va chạm - thử thách với những công nghệ mới.\n- Ưu tiên những ứng viên luôn nỗ lực hết mình trong mọi hoàn cảnh và đưa ra những ý kiến đóng góp để phát triển công việc.\n- Có kiến thức về Cloud Server: AWS, GCP, Azure... là một lợi thế\n- Có kiến thức về Around Security là một lợi thế\n\nQuyền lợi\n- Lương: Từ 20 - 35 triệu tùy theo năng lực.\n- Thử việc lên đến 100% lương\n- Phụ cấp cơm trưa và gửi xe hàng tháng\n- Cung cấp đầy đủ thiết bị phục vụ công việc\n- Nghỉ thứ 7, chủ nhật\n- Đóng BHXH sau khi thử việc, hưởng các chế độ phúc lợi theo luật lao động Việt Nam\n- Đánh giá xét tăng lương: 2 lần/năm\n- Lương tháng 13 + thưởng dự án theo quý tùy vào tình hình kinh doanh của công ty\n- Được tham gia các Câu lạc bộ dưới sự tài trợ chính thức của Công ty: CLB Bóng đá, - Lớp tiếng Nhật, tham gia các bữa tiệc sinh nhật, team building hàng quý, company trip hàng năm\n- Cơ hội thăng tiến cao, cơ hội rất lớn để trở thành key member của công ty.\n- Cơ hội đi công tác và làm việc tại Nhật Bản nếu đáp ứng được năng lực tốt.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4, Toà nhà H10, số 2 ngõ 475 Nguyễn Trãi, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2922, 1166, 2, 'Java Developer (Middle/Senior)', 'Mô tả công việc\n- Work in a team of engineers to implement backend services in the platform\n- Build service definitions, OpenAPI specifications, SDKs, and documentation for other developers that consume these services\n- Integrate with other services and data sources using APIs, messaging systems, databases\n- Collaborate with the DevOps team on microservices design, containerization, and automated deployments\n- Build automated test suites to ensure these services are reliable and performant\n\nYêu cầu ứng viên\n- such as Spring Boot\n- Project experience around web service design and RESTful APIs\n- Expertise with the OpenAPI Specification (Swagger), RESTful APIs, and related tools such as Postman, cURL, and HTTPie\n- Experience integrating with 3rd party services and databases such as Redis, message queues, MongoDB, and ElasticSearch\n- Agile/SCRUM methodology experience\n- English is a must\n- Prefer Senior/Leader candidates\n\nQuyền lợi\n- Salary: Negotiable\n- Performance review: 2 times/year\n- 14th-month salary bonus\n- KPI bonus based on project and performance\n- Extra package: 16 Mil /employee/year (Bonus at Tet, New Year, your birthday, CMC Corp’s birthday, 2/9 and Tet’s gift, Middle-Autumn gift, ...)\n- Opportunity to work in a professional, modern, and dynamic environment, take part in international projects\n- Opportunity to get on-job training and promotion\n- An excellent corporate culture with in/out of office activities that help to develop staffs ability and creativity\n- CMC health care and social insurance\n- Onsite opportunities: short-term and long-term assignments in US, EU,... (members of GEU/US).\n\nĐịa điểm làm việc\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2923, 1439, 2, 'Kỹ Thuật Viên Gia Công Máy CNC (Máy Phay/Máy Tiện)', 'Mô tả công việc:\n- Đọc và hiểu bản vẽ gia công chi tiết.\n- Sử dụng các dụng cụ đo kiểm, dụng cụ gá đặt.\n- Lập trình chương trình trên máy gia công CNC (máy tiện, máy phay, máy cắt,...)\n- Vận hành máy Tiện CNC (Okuma, Miyano, Tsugami, Moriseikii, Mazaktroll...) hoặc máy Phay CNC (Okuma, Brother, Victor-taichung...)\n- Thay đổi các mã hàng, thay đổi căn chỉnh dụng cụ cắt gọt.\n- Kiểm soát chất lượng sản phẩm, xử lý sự cố lỗi phát sinh trong các công đoạn gia công.\n- Các công việc khác liên quan đến kỹ thuật gia công CNC.\n- Tham gia các nhóm cải tiến 6S, TPM.\n\nYêu cầu ứng viên:\n- Tốt nghiệp CĐ hoặc ĐH chuyên ngành cơ khí chế tạo máy.\n- Sử dụng phần mềm gia công & thiết kế 2D, 3D.\n- Ưu tiên kinh nghiệm về thiết kế và lập trình gia công máy phay, máy tiện CNC, có thể vận hành máy gia công phay, tiện CNC (OKUMA, MAZAK, TROLL, BROTHER, TSUGAMI...).\n- Đáp ứng yêu cầu làm ca trong sản xuất (3 ca).\n- Thật thà, cẩn thận, có tinh thần trách nhiệm cao trong công việc.\n\nQuyền lợi:\n- Tham gia BHXH, BHYT theo đúng quy định.\n- Được hưởng chế độ bảo hiểm tai nạn 24h ngay khi được ký kết HĐLĐ chính thức.\n- Thưởng các dịp lễ tết, thưởng lương tháng 13, thưởng hiệu suất làm việc (hệ số lên tới 4,5 tháng lương cơ bản).\n- Ăn trưa tại nhà máy.\n- Môi trường làm việc thân thiện, năng động.\n\nĐịa điểm làm việc:\n- Bắc Ninh: Số 14, đường 8, khu công nghiệp, đô thị và dịch vụ VSIP Bắc Ninh, Phường Phù Chẩn, Từ Sơn.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:15 đến 17:00).\n- Làm 3 ca và 2 thứ 7 luân phiên.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2924, 1157, 2, 'Team Leader', 'Mô tả công việc\nTeam Leadership: Lead, manage, and mentor a team of Odoo developers and implementers. Provide guidance and support to team members in day-to-day tasks and career development. Foster a collaborative and productive team environment.\nProject Management: Plan and oversee the successful implementation of Odoo projects, ensuring they are delivered on time, within scope, and budget. Coordinate with cross-functional teams to define project requirements and deliverables. Maintain regular communication with stakeholders to ensure alignment with business goals.\nOdoo Development & Customization: Lead the customization and configuration of Odoo modules to meet business requirements. Oversee the integration of Odoo with other systems or third-party applications. Troubleshoot and resolve any technical issues related to Odoo implementation.\nTraining & Documentation: Develop and maintain training materials for end-users and new team members. Conduct training sessions to ensure users are proficient in Odoo functionality. Document Odoo system architecture, processes, and customizations.\nQuality Assurance & Continuous Improvement: Monitor the performance and functionality of Odoo and recommend improvements or enhancements. Ensure that all customizations and updates comply with best practices and quality standards. Stay up to date with new Odoo releases and evaluate their potential to improve business processes.\n\nYêu cầu ứng viên\nExperience: Proven experience in leading an Odoo development team or managing ERP implementation projects (3+ years). In-depth knowledge of Odoo’s modules, including but not limited to Sales, Inventory, Accounting, CRM, and HR. Hands-on experience in Odoo customization, configuration, and module development.\nTechnical Skills: Proficient in Python, XML, JavaScript, and PostgreSQL (commonly used in Odoo development). Experience with Odoo integration with other systems or external APIs. Strong understanding of object-oriented programming (OOP) principles.\nManagement Skills: Strong leadership, interpersonal, and communication skills. Ability to manage multiple projects and teams effectively. Strong problem-solving and critical-thinking abilities.\nEducational Qualifications: Bachelor\'s degree in Computer Science, Information Technology, Business Administration, or a related field. Odoo certifications are a plus (Odoo Developer, Odoo Functional Consultant, etc.).\nAdditional Skills: Familiarity with Agile/Scrum project management methodologies. Ability to work in a fast-paced environment and manage changing priorities.\n\nQuyền lợi\nSalary and Bonus: Salary: Negotiable based on ability. Bonuses: 13th-month bonus. Bonus based on the company’s business performance. Insurance: Full insurance coverage based on the salary. Travel: The company organizes an annual trip for employees. Benefits: Free pantry. Internal events: team building, monthly birthdays, International Women\'s Day, International Men\'s Day, etc. Gifts for Mid-Autumn Festival, birthdays, etc. Career Opportunities: Opportunity for onsite work in Japan (short-term or long-term). Opportunity to share ideas, listen, and develop your career according to personal aspirations. Clear career advancement path. Working Hours: Monday to Friday, from 8:30 AM to 5:30 PM (flexible by 30 minutes).\n\nĐịa điểm làm việc\nHà Nội: Tầng 29, tòa nhà Handico Tower, KĐTM Mễ Trì Hạ, Đường Phạm Hùng, Phường Mễ Trì Thành phố Hà Nội, Việt Nam., Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2925, 1250, 2, 'Technical Leader - Hybrid Working', 'Mô tả công việc\n- Lead & Build: Develop and mentor a high-performing engineering team, driving talent growth and performance excellence.\n- Design & Architect: Create robust, scalable, and secure systems to support business expansion.\n- Ensure Code Excellence: Enforce best practices, conduct thorough code reviews, and optimize system performance.\n- Innovate & Optimize: Continuously enhance system reliability, automation, and scalability.\n- Collaborate & Align: Partner with cross-functional teams to build impactful solutions.\n- Monitor & Maintain: Oversee system health, troubleshoot critical issues, and ensure seamless operations.\n\nYêu cầu ứng viên\nTechnical Expertise:\n- 6+ years of experience in software development, with at least 2+ years as a Tech Lead.\n- Strong experience in Frontend (React, Vue, Angular) & Backend (Node.js, Java, Python, Go).\n- Deep knowledge of cloud infrastructure (AWS/GCP), DevOps, CI/CD, and microservices.\n- Experience with high-traffic systems, real-time processing, and database optimization (PostgreSQL, MongoDB, Redis).\n\nLeadership & Problem-Solving:\n- Strong critical thinking & analytical skills to tackle complex technical challenges.\n- Passion for mentorship & team development.\n\nBusiness Mindset:\n- Ability to align tech solutions with business goals and drive impact.\n- Understanding of product lifecycle & agile methodologies.\n\nQuyền lợi\n- Attractive compensation package\n- Monthly bonus (up to 2 months bonus/year in total)\n- 100% salary on your probation period\n- 13th-month salary\n- Performance review conducted 2 times/ year\n- Hybrid working model (flexibility between home & office)\n- Personal branding & industry exposure: Contribute to Vexere’s tech blog, publish posts on Medium, and participate in open-source projects & tech talks.\n- Attractive stock option for hard-core developers/leads\n- Exclusive Vexere travel benefits: Up to 30% discount for you & your family on bus tickets.\n- Annual leave: 12 days + additional leave every 3 years (can be converted to salary).\n- Vibrant and dynamic working environment with a friendly and supportive team, ready to share knowledge and assist each other.\n- Company trips, team-building events, year-end parties, and training programs.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 384 Hoàng Diệu, Quận 4\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Thứ 7 (từ 09:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2926, 1477, 2, 'Lập Trình CNC', 'Mô tả công việc:\n- Đọc và phân tích bản vẽ kỹ thuật: Hiểu rõ các yêu cầu kỹ thuật, vật liệu, dung sai, bề mặt hoàn thiện của chi tiết cần gia công\n- Tính toán đồ gá đề gia công\n- Lập trình gia công: Sử dụng phần mềm Mastercam X5\n- Truyền chương trình vào máy CNC: Gửi chương trình từ máy tính sang máy CNC, thường qua USB.\n- Thời gian làm việc (thứ 2- thứ 7) – Làm việc theo ca (ca 1: 6h-14h; ca 2: 14h-22h)\n- Địa điểm làm việc: Khu Công nghiệp Di Trạch, Hoài Đức, Hà Nội\n\nYêu cầu ứng viên:\n- Tốt nghiệp từ Trung cấp trở lên các ngành nghề liên quan\n- Tối thiểu 1 năm kinh nghiệm gia công những chi tiết đồ gá, hàng lẻ theo yêu cầu của khách hàng\n- Đã từng đứng máy gia công chi tiết đồ gá, jig có kinh nghiệm setup máy, chế tạo đồ gá, thành thạo phần mềm Mastercamx5 (hoặc Mastercam 2018, 2021)\n- Chăm chỉ, chịu khó, chịu được áp lực\n\nQuyền lợi:\n- Mức lương: 9-15 triệu/tháng (Lương cứng + Phụ cấp)\n- Thưởng các ngày lễ, tết, thưởng tháng thứ 13\n- Lương làm thêm giờ theo quy định, phụ cấp ăn ca khi làm thêm giờ\n- Phụ cấp thâm niên 500k/tháng khi gắn bó từ 2 năm trở lên\n- Tham gia BHXH theo quy định ngay sau 1 tháng thử việc\n- Được nghỉ phép 12 ngày / năm theo quy định của nhà nước\n- 1 năm đi du lịch 1 lần\n- Tăng lương hàng năm, làm tốt có thể được xét tăng lương 6 tháng/lần\n- Môi trường năng động, cởi mở, hỗ trợ.\n\nĐịa điểm làm việc:\n- Hà Nội: Khu công nghiệp Di Trạch, Hoài Đức\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 07:30 đến 16:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2927, 1277, 2, 'Fullstack Engineer', 'Mô tả công việc\n- Phát triển và duy trì ứng dụng web bằng ReactJS, NextJS và NodeJS.\n- Hợp tác với product team và backend để phát triển sản phẩm đầu tư hiệu quả và dễ sử dụng.\n- Xây dựng hệ thống web có khả năng mở rộng, bảo mật và hoạt động ổn định trên hạ tầng AWS.\n- Tối ưu hóa hiệu năng, bảo mật và trải nghiệm người dùng.\n- Viết mã chất lượng, tài liệu đầy đủ, tham gia code review và chia sẻ kiến thức trong nhóm.\n- Làm việc trong môi trường Agile, cải tiến sản phẩm liên tục.\n\nYêu cầu ứng viên\n- Ít nhất 5 năm kinh nghiệm phát triển phần mềm, đặc biệt với ReactJS, NextJS, NodeJS.\n- Kinh nghiệm làm việc với AWS (EC2, S3, Lambda, RDS, API Gateway).\n- Ưu tiên có hiểu biết về các API tài chính/đầu tư.\n- Nắm rõ các nguyên tắc bảo mật trong môi trường fintech.\n- Tư duy logic tốt, chủ động, đam mê với công nghệ tài chính.\n\nQuyền lợi\n- Làm việc cùng đội ngũ xây dựng nền tảng công nghệ đầu tư thế hệ mới.\n- Thu nhập cạnh tranh và thưởng theo hiệu quả công việc.\n- Môi trường linh hoạt, cởi mở và hỗ trợ sáng tạo.\n- Cơ hội phát triển năng lực kỹ thuật và vai trò quản lý.\n- Văn hóa đồng đội, học hỏi và phát triển liên tục.\n\nĐịa điểm làm việc\n- Hà Nội: Trung tâm đổi mới sáng tạo quốc gia, tòa NIC, số 6, ngõ 7 Tôn Thất Thuyết, Dịch Vọng, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Thứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2928, 556, 2, 'Backend Developer', 'Mô tả công việc\n- Phát triển và nâng cấp hệ thống Website, WebApp theo yêu cầu khách hàng.\n- Phát triển các giải pháp về ERP(Enterprise Resource Planning), PLM (Product Lifecycle Management) cho các khách hàng là các công ty lớn ở Nhật.\n- Các giải pháp về tự động hóa công nghiệp, thông minh, quản lý và điều khiển hệ thống,dây chuyền sản xuất thông qua giao diện người dùng.\n- Địa điểm làm việc: Nagoya (Nhật Bản)\n- Nhận ứng viên ở cả Hà Nội , Đà Nẵng, Hồ Chí Minh.\n\nYêu cầu ứng viên\n- Tiếng Nhật tương đương với N3 trở lên (bắt buộc, nếu chưa có bằng thì yêu cầu trình độ giao tiếp tương đương level N3).\n- Tối thiểu 3 năm kinh nghiệm Web Developer (Backend).\n- Biết ít nhất về 1 front-end framework (Reactjs, ...).\n- Thành thạo ít nhất 1 trong các ngôn ngữ C#, JS, PHP.\n- Có tư duy về kiến trúc hệ thống web, có khả năng tối ưu tốc độ, số lượng users, request.\n\nQuyền lợi\n- Tham gia các khóa đào tạo tiếng Nhật miễn phí, giúp nâng cao kỹ năng giao tiếp và làm việc hiệu quả hơn.\n- Làm việc cùng các kỹ sư cao cấp về AI, Embedded, nâng cao chuyên môn và mở rộng kiến thức công nghệ.\n- Mức lương từ 320-500 man/1 năm.\n- Nghỉ thứ 7 và CN;\n- Có 3 đợt nghỉ dài trong năm (mỗi đợt khoảng 9-11 ngày nghỉ);\n- Xét tăng lương 1 lần/ năm, Thưởng 2 lần/năm;\n- BHXH, y tế đầy đủ;\n- Khám sức khỏe hàng năm;\n- Có trợ cấp nhà ở, đi lại, vợ, con;\n- Có kí túc xá cho các bạn độc thân;\n- Team building theo quý, du lịch hàng năm, và rất nhiều các hoạt động vui chơi khác.\n- Cơ hội thăng tiến rõ ràng, phát triển sự nghiệp lâu dài tại Nhật Bản.\n\nĐịa điểm làm việc\n- Nhật Bản\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nhật Bản', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2929, 1338, 2, 'Blockchain Developer (Frontend)', 'Mô tả công việc\n- Phát triển và bảo trì giao diện người dùng (UI) cho các ứng dụng DeFi và Crypto trên nền tảng di động (iOS và Android), tích hợp với blockchain (Ethereum, Solana, v.v.).\n- Thiết kế và triển khai các tính năng frontend di động tương tác với smart contract (ví dụ: AMM, staking, lending, NFT).\n- Tối ưu hóa App Listing và App Store Optimization (ASO) cho ứng dụng di động trên App Store và Google Play, bao gồm metadata, từ khóa, hình ảnh và nội dung quảng bá.\n- Phối hợp với đội ngũ backend và blockchain để tích hợp API và dịch vụ on-chain vào ứng dụng di động.\n- Phân tích dữ liệu ASO (tỷ lệ tải, đánh giá, xếp hạng) và đề xuất cải tiến để tăng khả năng hiển thị ứng dụng trên các kho ứng dụng.\n- Đảm bảo giao diện di động thân thiện với người dùng, tuân thủ chính sách của App Store/Google Play và tối ưu hiệu suất trên các thiết bị di động.\n\nYêu cầu ứng viên\n- Tối thiểu 2 năm kinh nghiệm phát triển ứng dụng di động, ưu tiên trong các dự án blockchain/DeFi.\n- Thành thạo các ngôn ngữ và công cụ lập trình di động:\n  - Android: Kotlin, Java, C/C++ (NDK), Dart (Flutter là một lợi thế).\n  - iOS: Swift, Objective-C, React Native (JS) là một lợi thế.\n- Kinh nghiệm tích hợp frontend di động với blockchain qua Web3.js, Ethers.js, hoặc Solana Web3.js.\n- Hiểu biết về smart contract (Solidity, Rust) và các giao thức DeFi (Uniswap, Aave, v.v.).\n- Kiến thức về ASO, bao gồm tối ưu hóa từ khóa, mô tả ứng dụng, và phân tích hiệu suất qua các công cụ như App Annie, Sensor Tower.\n- Thành thạo công cụ phát triển di động: Xcode, Swift Package Manager, Android Studio.\n- Ưu tiên: Kinh nghiệm phát triển ứng dụng di động đa nền tảng (React Native, Flutter) và tích hợp blockchain trên mobile.\n- Có khả năng đọc hiểu tài liệu tiếng Anh.\n\nQuyền lợi\n- Thu nhập cạnh tranh, thưởng dựa trên hiệu quả công việc.\n- Tham gia dự án blockchain thực chiến, ảnh hưởng trực tiếp đến thiết kế và vận hành ứng dụng di động.\n- Môi trường làm việc chuyên nghiệp, cởi mở, khuyến khích sáng tạo và đổi mới.\n- Cơ hội tiếp cận các công nghệ blockchain và công nghệ di động tiên tiến nhất.\n- Đồ ăn vặt, snack giữa giờ thoải mái; hoạt động gắn kết như ăn lẩu Haidilao hàng tháng.\n- Thời gian làm việc linh hoạt: 9h00 - 17h30 (Thứ 2 đến Thứ 6).\n- Công ty chi trả chi phí gửi xe tại tòa nhà.\n\nĐịa điểm làm việc\n- Hà Nội: Cầu Giấy\n- Hà Nội: Thanh Xuân\n- Hà Nội: Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2930, 1323, 2, 'Front-End Developer (Chuyên VueJS)', 'Mô tả công việc:\n- Tham gia vào các quy trình: viết tài liệu, phân tích yêu cầu, thiết kế giao diện, triển khai, code review, kiểm thử đơn vị (Unit testing) và vận hành sản phẩm.\n- Đảm bảo giao diện tải nhanh và hoạt động mượt mà trên nhiều nền tảng khác nhau.\n- Xử lý sự cố phần mềm giao diện và gỡ lỗi mã nguồn ứng dụng.\n- Cập nhật và duy trì giao diện người dùng khi có yêu cầu hoặc theo nhu cầu vận hành.\n- Phối hợp với các thành viên khác trong nhóm phát triển để đảm bảo sự đồng bộ và tương thích giữa các thành phần của ứng dụng.\n- Đào tạo, hỗ trợ và tạo động lực cho các thành viên trong nhóm.\n- Nghiên cứu và phát triển công nghệ mới liên quan đến dự án.\n\nYêu cầu ứng viên:\n- Ưu tiên ứng viên có bằng Cử nhân các ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan.\n- Tối thiểu 01 năm kinh nghiệm phát triển dịch vụ Web.\n- Có kinh nghiệm tham gia đầy đủ các giai đoạn trong vòng đời phát triển dự án từ con số 0.\n- Có kinh nghiệm làm việc với TypeScript, NextJS, NuxtJS.\n- Có tinh thần học hỏi, sẵn sàng chuyển đổi ngôn ngữ lập trình từ ReactJS sang VueJS hoặc ngược lại.\n- Ưu tiên ứng viên biết tiếng Trung.\n\nQuyền lợi:\n- Lương thỏa thuận theo năng lực (từ 20 - 30 triệu/tháng).\n- Được tham gia bảo hiểm xã hội khi trở thành nhân viên chính thức.\n- Cung cấp trang thiết bị làm việc.\n- Off chủ nhật và các ngày lễ theo quy định nhà nước.\n- Các phúc lợi khác trao đổi khi phỏng vấn.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tầng 2 thương mại, Tháp A thuộc chung cư the CBD - 125 Đồng Văn Cống, phường Thạnh Mỹ Lợi, Thủ Đức.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2931, 1301, 2, 'Trưởng Phòng Gia Công CNC', '- Tổ chức sắp xếp công việc gia công đảm bảo : Tiến độ, chất lượng, hiệu suất, chi phí.\n- Phối hợp với kỹ thuật lâp trình & NVVH kiểm soát quá trình gia công đạt yêu cầu.\n- Quản lý, đào tạo và phát triển năng lực chuyên môn cho nhân sự trong bộ phận.\n- Quản lý và sử dụng máy móc, thiết bị, công cụ & vật tư tiêu hao cho tối ưu hiệu quả.\n- Thực hiện các công việc khác khi được cấp trên yêu cầu.\n\n- Tốt nghiệp THPT trở lên, nhanh nhẹn, nhiệt tình trong công việc;\n- Trung thực, trách nhiệm, hòa đồng & kỷ luật tốt;\n- Đọc tốt bản vẽ kỹ thuật, Lập trình 2D+3D. Sử dụng thành thạo phần mềm CAD/CAM , Solidworks\n- Có kinh nghiệm quản lý gia công CNC.\n- Có kinh nghiệm gia công các sản phẩm chi tiết máy cho khách hàng Nhật, Hàn.\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, Hass\n\n- Có cơ hội phát triển tương lai tại công ty.\n- Làm việc trong môi trường năng động, chuyên nghiệp;\n- Cung cấp trang thiết bị đầy đủ để phục vụ công việc;\n- Thưởng các dịp Quốc tế Lao động 1/5, Quốc khánh 2/9, Tết dương lịch, Thưởng Tết theo quy định của công ty\n- Được đóng đẩy đủ BHXH, BHYT, BHTN;\n- Đi du lịch nghỉ mát hàng năm;\n- Tham gia các hoạt động văn hoá thể thao (bóng đá, chạy...);\n- Hỗ trợ ăn cơm trưa tại Công ty;\n- Hỗ trợ tiền điện thoại, công tác phí khi đi gặp Khách Hàng, đi công tác;\n- Nghỉ chủ nhật và 1 thứ 7 trong tháng.\n- Hỗ trợ 400,000VND tiền chuyên cần nếu đi làm đủ số ngày làm việc của tháng.\n\n- Hà Nội: Lô 5 +6 KCN Lai Xá, Xã Kim Chung, Hoài Đức\n\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n- Nghỉ các chủ nhật và 1 thứ 7 cuối tháng\n\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2932, 1207, 2, 'IT Project Manager (Có Base Developer)', 'Mô tả công việc:\n- Tham gia công việc quản lý các dự án làm việc với đối tác Nhật Bản.\n- Xây dựng quy trình làm việc, quy trình phát triển phần mềm, quy trình quản lý chất lượng phần mềm trong công ty.\n- Tham gia vào quản trị dự án xây dựng sản phẩm riêng của công ty.\n- Tiến hành estimate, quản lí tiến độ, quản lí rủi ro dự án.\n- Phỏng vấn, đánh giá năng lực, phân công công việc của các kĩ sư trong dự án.\n- Báo cáo tiến độ dự án, đánh giá nhân sự, đề xuất giải pháp với ban giám đốc.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học các chuyên ngành liên quan như: Công nghệ phần mềm, hệ thống thông tin, quản lý dự án phần mềm...\n- Có kỹ năng lập trình trên 3 năm kinh nghiệm, hiểu biết sâu về ít nhất một trong các ngôn ngữ lập trình như: PHP, JAVA, C/C++, Swift...\n- Đã có kinh nghiệm quản lý dự án với team size từ 5 người trở lên.\n- Đã có ít nhất 2 năm kinh nghiệm phát triển ứng dụng trên smartphone (ios/android).\n- Có kinh nghiệm 3 năm trở lên ở vị trí quản lý dự án hoặc tương đương.\n- Có kiến thức và kinh nghiệm về Linux Cloud Server: AWS, GCP, Azure,v.v\n- Có kiến thức sử dụng UML thiết kế hệ thống phần mềm, thiết kế CSDL quan hệ.\n- Đã có ít nhất 3 năm kinh nghiệm làm việc với GIT hoặc Bitbucket.\n- Kỹ năng quản lý con người để tối ưu hiệu suất công việc.\n- Có kinh nghiệm viết Unit testing, viết document.\n- Có tư duy lập trình hướng đối tượng MVC, đọc hiểu tiếng anh tốt để phục vụ cho công việc.\n- Có kiến thức liên quan đến Performance của MySQL Statement và Query.\n- Ưu tiên ứng viên có kinh nghiệm sử dụng Docker để phát triển dự án, có kiến thức về Bảo mật và tối ưu.\n\nQuyền lợi:\n- Mức lương: up to 60 triệu, tùy theo kinh nghiệm.\n- Thử việc lên đến 100% lương chính thức.\n- Được cung cấp thiết bị làm việc.\n- Phụ cấp cơm trưa và gửi xe hàng tháng.\n- Nghỉ thứ 7, chủ nhật.\n- Đóng BHXH sau khi thử việc, hưởng các chế độ phúc lợi theo luật lao động Việt Nam.\n- Điều chỉnh lương: 2 lần/năm, Lương tháng 13 + thưởng dự án theo quý tùy vào tình hình kinh doanh của công ty.\n- Du lịch 1 năm 1 lần, Team building theo quý, các hoạt động vui chơi giải trí khác như: bóng bàn, bóng đá,...\n- Có cơ hội đi công tác và làm việc tại Nhật Bản nếu đáp ứng được năng lực tốt.\n- Được làm việc trong môi trường trẻ trung, năng động, chuyên nghiệp theo tiêu chuẩn chất lượng Nhật Bản.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4 Tòa nhà H10, số 2 ngõ 475 Nguyễn Trãi, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2933, 1262, 2, 'Lập Trình Viên C# /.Net (WPF, WinForms)', 'Mô tả công việc\n- Lập trình phát triển ứng dụng Desktop Application sử dụng C#/.NET (WPF, WinForms);\n- Xây dựng các module chính như:\n  - Giao diện tương tác (Dashboard, Data Visualization)\n  - Tích hợp API với hệ thống khác\n  - Xử lý dữ liệu (Data Processing, AI Integration)\n  - Quản lý và tối ưu hệ thống lưu trữ dữ liệu\n  - Kết nối với hệ thống AI, xử lý dữ liệu bằng Web API, gRPC hoặc Message Queue (Kafka, RabbitMQ);\n  - Triển khai mô hình MVVM, Clean Architecture để tối ưu tổ chức code;\n  - Phát triển các module sản phẩm theo yêu cầu của dự án;\n  - Làm việc theo sự phân công của Trưởng nhóm / Quản lý dự án, phối hợp giữa các nhóm để phát triển sản phẩm;\n  - Làm việc và phát triển sản phẩm theo Agile/Scrum.\n\nYêu cầu ứng viên\n- Tốt nghiệp ĐH/CĐ chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan;\n- Có tối thiểu 2 – 3 năm kinh nghiệm lập trình C# .NET;\n- Thành thạo WPF, WinForms để phát triển ứng dụng Desktop;\n- Có kinh nghiệm làm việc với SQL Server, PostgreSQL hoặc NoSQL (MongoDB, Redis, Elasticsearch);\n- Hiểu biết về cấu trúc dữ liệu, thuật toán, lập trình hướng đối tượng (OOP);\n- Có kinh nghiệm làm việc với RESTful API, WebSockets hoặc gRPC;\n- Có kinh nghiệm tối ưu hiệu suất, đa luồng, xử lý dữ liệu lớn;\n- Tinh thần hợp tác và làm việc tốt.\n\nQuyền lợi\n- Thu nhập: Cạnh tranh\n- Thưởng: 2 lần/ năm, thưởng các ngày lễ, review lương định kỳ hàng năm;\n- Môi trường làm việc năng động, thân thiện, chuyên nghiệp;\n- Teambuilding, khám sức khỏe hàng năm\n- Tạo điều kiện học hỏi phát triển bản thân và các kỹ năng sống;\n- Được cấp máy tính, công cụ để làm việc;\n- Du lịch 1-2 lần/năm và hưởng các quyền lợi khác theo luật lao độn;\n- Tham gia các câu lạc bộ free: Đá bóng, cầu lông,...\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 16-VP2, Tòa nhà Sun Square, số 21 lê Đức Thọ, Phường Mỹ Đình 2., Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Linh hoạt thời gian làm việc, yêu cầu bắt buộc lên công ty tối thiểu 2 buổi/tuần hoặc 4 buổi sáng/chiều trong tuần.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2934, 1187, 2, 'Frontend Developer (VueJS) Middle', 'Mô tả công việc:\n- Support for development using UI Dev.\n- Skills with Vue.js, Javascript, Typescript, HTML, css,…\n- Experienced of Lego Enterprise framework and OPUS.\n- Interpreting, analyzing and implementing client’s requests.\n- Performing quality verification including code review, code inspection, performance test, etc…\n\nYêu cầu ứng viên:\n- At least 3 years of frontend experience, with strong expertise in Vue.js\n- Work to match the web standard and accessibility of what web designers design.\n- Creating and editing websites through web design work and coding.\n- Creating and editing websites through web design work and coding.\n- Experience developing pages using vue.js on mobile devices (Android, IOS – Hybrid app).\n- Developers are required to have skills in testing and code review.\n\nQuyền lợi:\n- Salary: Negotiate.\n- Package: At least 13 months/ year. Review periodically following company policy.\n- Bonus: Tet bonus, project bonus, holiday bonus, HR referral bonus...\n- Seniority allowance (working time from 2 years or more).\n- Participate in learning and training activities inside and outside the company, accumulate learning points, develop G-Points on the company\'s management system.\n- 2 days of per week and 12 leave days per year.\n- Clubs and many cultural - sports - art activities sponsored or supported by the company (For example: Football, table tennis, badminton, swimming, music, English, games... )\n- Ensure health: Periodic health check, support to buy high quality health insurance...\n- Join the Rikkei Care Health Insurance Plan.\n- Mental comfort: Playing music on demand every day, happy hour, team building activities...\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Đăng ký linh hoạt 8:00 - 9:00 đến 17:00 - 18:00 từ Thứ 2 - Thứ 6\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2935, 1208, 2, 'Java Fullstack (Thu Nhập Đến 25 Triệu)', 'Mô tả công việc:\n- Xây dựng, phát triển phần mềm/ứng dụng.\n• Tiếp nhận yêu cầu về chức năng, nội dung của phần mềm/ứng dụng. Tham gia phân tích, thiết kế chi tiết các chức năng được giao.\n• Trực tiếp xây dựng, phát triển phần mềm/ứng dụng theo tài liệu thiết kế và framework đã được thông qua theo phân công của trưởng nhóm/PM dự án.\n• Làm Unit Test, tiếp nhận ý kiến của bộ phận kiểm thử, liên quan khác để điều chỉnh, bổ sung đến khi phần mềm/ứng dụng được hoàn thiện.\n• Giám sát và kiểm tra hệ thống và các thành phần liên quan để phát hiện các sự cố tiềm ẩn, đưa ra giải pháp kịp thời để ngăn chặn và xử lý. Tối ưu hệ thống.\n• Xây dựng các tài liệu dự án theo phân công của Trưởng nhóm/PM dự án.\n- Sửa chữa, nâng cấp, bảo trì phần mềm.\n- Tích hợp, triển khai phần mềm/ứng dụng.\n- Các công việc khác.\n\nYêu cầu ứng viên:\n- Tốt nghiệp CĐ/ĐH.\n• Tối thiểu 2 năm kinh nghiệm phát triển thực tế với Java và các framework (Spring Framework, Spring Boot).\n• Kiến thức tốt về Cấu trúc Dữ liệu và Thuật toán; Chuyên môn về Cơ sở dữ liệu SQL / NoSQL (Oracle, MongoDB); Kinh nghiệm với các API RESTful, Microservices.\n• Tối thiểu 2 năm kinh nghiệm làm việc với framework JS/UI – Angular.\n• Kinh nghiệm với Typescript, HTML, CSS; Hiểu biết tốt về các thực tiễn tốt nhất về UX.\n- Tuổi: dưới 40 tuổi.\n- Làm theo dự án.\n\nQuyền lợi:\n• Teambuilding 1 năm nhiều lần.\n• Nghỉ thứ 7, CN, đóng BHXH ngay sau khi là cán bộ chính thức.\n• Công ty đóng toàn bộ BHXH, BHYT, BHTN, thuế TNCN.\n\nĐịa điểm làm việc:\n- Hà Nội: CT2 Tràng An Complex, số 1 Phùng Chí Kiên, Nghĩa Đô, Cầu Giấy, Cầu Giấy.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2936, 1434, 2, 'Kĩ Sư Tích Hợp - DotNet Developer', 'Mô tả công việc:\n- Chịu trách nhiệm Lập trình phần mềm, các module tích hợp dựa trên các sản phẩm, giải pháp, nền tảng lõi nhằm đáp ứng đầy đủ và tổng quan cho các yêu cầu cụ thể của khách hàng doanh nghiệp.\n- Tham gia vào các công đoạn khác của Tích hợp hệ thống Phần mềm từ Thiết kế, kiến trúc phần mềm, kiến trúc tích hợp; Phân tích thông tin, yêu cầu; Phát hiện và sửa lỗi phần mềm; Kiểm thử và tối ưu phần mềm.\n- Tham gia xây dựng, soạn thảo và trình bày các giải pháp (solution), đề xuất (proposal), bài thuyết trình (presentation), chứng minh giải pháp (POC) phù hợp đáp ứng các yêu cầu cụ thể của khách hàng và các gói thầu được giao.\n- Chịu trách nhiệm tư vấn thiết kế và triển khai các giải pháp về Tích hợp hệ thống (System Integration) cho khách hàng doanh nghiệp và tổ chức viễn thông\n- Đánh giá, Tích hợp & Tối ưu các thành phần phù hợp vào hệ thống tổng thể đáp ứng cho các yêu cầu vận hành và quản lý của khách hàng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính,...\n- Tối thiểu 02 năm kinh nghiệm về phát triển phần mềm.\n- Yêu cầu ngôn ngữ: C#, ASP.NET, MVC, .NET framework , Entity Framework, OOP.\n- Hiểu biết về python/nodejs là lợi thế\n- Yêu cầu kiến thức về JavaScript, CSS, HTML, bootstrap, Ext.js.\n- Xây dựng Web Service và tích hợp API.\n- Kinh nghiệm về làm việc với API, SOAP, Rest.\n- Kinh nghiệm về sử dụng ứng dụng quản lý source: git, bitbucket .....\n- Kinh nghiệm với SQL và / hoặc cơ sở dữ liệu quan hệ / hoặc cơ sở dữ liệu NoSQL là một lợi thế.\n\nQuyền lợi:\n- Thời gian làm việc: 08h00-17h00 (từ thứ 2- thứ 6) \n- Phúc lợi: chế độ lương hấp dẫn,chế độ phúc lợi khác theo Luật lao động và chính sách của công ty.\n- Được tham gia đầy đủ BHXH theo quy định nhà nước và gói bảo hiểm sức khỏe cho nhân viên.\n- Cấp Laptop làm việc.\n- Du lịch hàng năm, các hoạt động nội bộ mỗi tháng.\n\nĐịa điểm làm việc:\n- Hà Nội: 9 Đào Duy Anh, Đống Đa.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2937, 1178, 2, 'Thực Tập Sinh Tư Vấn Triển Khai Phần Mềm', 'Mô tả công việc\n- Tư vấn về bố cục, màu sắc, chức năng của trang Website\n- Làm việc với khách hàng để xây dựng phương án thiết kế web, app\n- Lập kế hoạch và xây dựng timeline thiết kế website, app cho team\n- Hoàn thiện demo giao diện website,app cho khách hàng (sẽ được training, hướng dẫn cụ thể)\n- Kiểm tra lại web trước khi gửi khách hàng ( đặc tả và test web, app).\n- Nghiệm thu và hướng dẫn sử dụng.\n\nYêu cầu ứng viên\n- Thực Tập Sinh fultime, mới ra trường.\n- Hiểu biết về công nghệ thông tin.\n- Biết làm giao diện web, tester là lợi thế.\n\nQuyền lợi\n- Được hỗ trợ, đào tạo kỹ năng công việc , có thu nhập.\n- Tham gia vào các hoạt động tâp thể, du lịch, teambuilding\n- Hỗ trợ lương (4-10 tr) tùy năng lực.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Lầu 1, tòa nhà SaigonTel, CVPM Quang Trung, Quận 12\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2938, 1478, 2, 'Game Developer', 'Mega Combat Studio là một studio game độc lập tại TP.HCM, chuyên phát triển dòng game MMORPG 2D pixel. Chúng tôi đã thành công với tựa game Treasure Hunter, hiện có mặt trên App Store và Google Play.\n\nĐể mở rộng sản phẩm và tăng tốc phát triển, studio đang tìm kiếm thêm 1 Game Developer và 1 Backend Developer làm việc full-time cùng team hiện tại.\n\nCông việc:\n • Tham gia phát triển tính năng mới, tối ưu server/client, fix bug cho game Treasure Hunter\n • Đồng hành cùng team trong các dự án MMO mới\n\nYêu cầu ứng viên:\n• Có kinh nghiệm Unity từ 1 năm trở lên (ưu tiên từng làm game Multiplayer/MMO)\n• Biết sử dụng Mirror, Photon, hoặc các hệ thống networking là lợi thế\n• Tư duy rõ ràng, code gọn gàng, biết tối ưu hiệu năng\n• Có thể làm client hoặc server (càng tốt nếu làm được cả hai)\n• Yêu thích game, có đam mê tạo ra sản phẩm sáng tạo và có chiều sâu\n\nQuyền lợi:\nLương & đãi ngộ:\n • Thỏa thuận theo năng lực\n • Được làm việc trực tiếp trên sản phẩm game thực tế, thử thách và giàu trải nghiệm\nĐịa điểm làm việc:\n • Văn phòng tại Quận 1, TP.HCM\n • Môi trường thoải mái, không quản lý khắt khe, miễn là bạn có trách nhiệm và hiệu quả\nỨng tuyển bằng cách gửi CV / portfolio / demo sản phẩm đã từng làm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2939, 1132, 2, 'Backend Technical Leader', 'Mô tả công việc:\n- Lãnh đạo đội ngũ phát triển Backend Game Server, đảm bảo chất lượng và tiến độ công việc\n- Thiết kế và phát triển các tính năng hệ thống, API và dịch vụ liên quan đến game server\n- Đảm bảo hiệu suất và khả năng mở rộng của hệ thống backend để hỗ trợ người chơi đồng thời\n- Phối hợp với đội Client Dev và các bộ phận khác để giải quyết vấn đề và tối ưu hệ thống\n- Phát triển và duy trì các giải pháp xử lý dữ liệu lớn và thời gian thực cho game\n- Tích hợp các dịch vụ phân tích dữ liệu và tối ưu hóa quá trình thu thập, xử lý và phân tích dữ liệu người dùng để cung cấp insights cho game và các bộ phận liên quan\n\nYêu cầu ứng viên:\n- Thành thạo Java, Node JS, đặc biệt trong môi trường phát triển Game Server\n- Kinh nghiệm làm việc với các dịch vụ cloud như AWS, GCP hoặc Azure\n- Kiến thức sâu về thiết kế hệ thống phân tán, microservices và quản lý dữ liệu lớn\n- Kinh nghiệm với các công nghệ như Docker, Kubernetes, CI/CD, và các công cụ quản lý container\n- Kinh nghiệm làm việc với các database NoSQL (MongoDB, Cassandra, Redis, v.v.) và SQL (MySQL, PostgreSQL)\n- Kinh nghiệm làm việc với các hệ thống phân tích và logging (ELK stack, Prometheus, Grafana, v.v.)\n- Khả năng lãnh đạo, giải quyết vấn đề và khả năng giao tiếp tốt\n- Kinh nghiệm phát triển các hệ thống có khả năng mở rộng và chịu tải lớn\n- Kỹ năng làm việc độc lập và quản lý đội ngũ, giúp đội phát triển trong môi trường agile\n\nQuyền lợi:\n- Lương: 35.000.000 - 50.000.000 VNĐ/tháng (Tùy level)\n- Thưởng các ngày nghỉ lễ, thưởng lương tháng 13; thưởng tết (1-5 tháng lương)\n- Review lương 2 lần/năm\n- Phụ cấp ăn trưa, thuê trọ, đi lại\n- Xét duyệt thưởng tour du lịch 6 tháng/lần\n- Văn hóa công ty: đọc sách, tập thể dục hàng ngày\n- Làm việc trong môi trường trẻ trung, thân thiện và hướng đến việc phát triển con người\n- Chế độ BHXH, BHYT, BHTN theo luật lao động\n- Trang bị thiết bị hiện đại, laptop, màn hình lớn\n- Du lịch hàng năm, tham gia liên hoan hàng tháng\n- Đồ ăn nhẹ /đồ uống miễn phí\n- Tham gia vào CLB Bóng đá của công ty hàng tuần\n- Quyền lợi dành cho thành viên: Từ > 01 năm được khám sức khỏe tổng quát 1 năm/lần; Từ > 03 năm được cấp vốn mua nhà, mua xe......\n- Thời gian làm việc: Thứ 2 – Thứ 6 + 01 thứ 7 Creative day; nghỉ 03 thứ 7 và 4 chủ nhật (8h30 - 18h, nghỉ trưa 1h30p)\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa The Nine, số 9 Phạm Văn Đồng, Mai Dịc, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Thêm 01 thứ 7 trong tháng (Có hoặc không)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2940, 209, 2, 'Senior Full-Stack Engineering Manager', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 33,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWHY JOIN?\n• This is a mission critical role as our organization shifts toward multiple full-stack, cross-functional teams that are responsible for end-to-end delivery. You’ll play a key part in shaping the future of our engineering and automation culture enabling the transformation of a high-growth company offering products our customers need during a moment that shapes the future for those they love most. Every day you’ll tackle complex challenges working with the latest technologies on cloud-native platforms—all within an inclusive, collaborative environment where each team member is empowered by mission, committed to protection, and dedicated to creating legacies.\n• The Senior Full-Stack Engineering Manager should be well versed in a range of technologies including .NET/C#, Azure SQL (MSSQL), and Vue.js. The role also affords the opportunity to influence how we scale our test automation practices using frameworks like Gherkin. The ideal candidate is someone who is adept at guiding junior engineers, working with key stakeholders, and is comfortable partnering with cross functional teams  Additionally, the role requires a fundamental understanding of system design and architecture with an emphasis on quality, performance and high availability high throughput distributed systems.\n\nJOB OVERVIEW\n• We are seeking a talented Senior Full-Stack Engineering Manager to support our partnership with FPT. This role requires a combination of skills, not only building robust applications but also serving as a liaison and mentor working with across multiple engineering teams on a wide range of initiatives. In this capacity, you will be guiding one or more newly formed engineering teams responsible for making contributions across our technology stack – from building modern UI components to developing secure APIs and ensuring the reliability of our systems through automation-first testing.\n\nRESPONSIBILITIES\nLeading one or more teams of Full Stack Engineers focused on:\n• Full-Stack Development\n• Designing and developing scalable REST APIs and services using .NET/C#.\n• Building modern, responsive UI components using JavaScript, Vue.js or Angular.js.\n• Writing performant, maintainable SQL queries and stored procedures.\n• Collaborating with product and design to implement intuitive user experiences.\n• Automation-Driven Quality\n• Contributing to and expanding our automation-first testing approach using Gherkin, SpecFlow, Playwright, or similar tools.\n• Defining and maintaining automated test suites across UI, API, and integration layers.\n• Participating in test planning and reviews to ensure high coverage and confidence.\n• DevOps & Observability\n• Supporting CI/CD pipelines and advocating for shift-left practices.\n• Implementing and improving monitoring and alerting of deployed services.\n• Participating in root cause analysis and post-incident reviews.\n• Collaboration & Delivery\n• Contributing to team ceremonies, planning, and team retrospectives.\n• Promoting engineering best practices and continuous improvement.\n• Working cross-functionally to remove blockers and accelerate delivery.\n\nBasic Qualifications\n• Demonstratable experience leading one or more teams of 3-5 engineers\n• A history of working effectively with stakeholders across different teams (Data, DevOps, UI/UX)\n• Strong oral and written English language communication skills\n• Significant experience in software engineering with full-stack development exposure.\n• Proficiency in .NET/C#, JavaScript, and MSSQL.\n• Prior experience developing modern web UIs, REST APIs, and database-backed applications.\n• Experience with Azure DevOps for source control, CI/CD pipelines, and release management.\n• Experience with CI/CD tools, Git, and agile methodologies.\n• Previous hands-on experience with test automation frameworks and writing meaningful automated tests.\n\nPreferred Qualifications\n• Exposure to Azure cloud services and containerized deployments (AKS/Kubernetes).\n• Experience with BDD frameworks like Gherkin or SpecFlow.\n• Familiarity with observability tools and infrastructure monitoring.\n• Strong communication and mentoring skills.\n\nQuyền lợi\n• Attractive Salary Package based on your competence plus Annual Bonus and Project Performance Bonus.\n• Signing bonus up to 20M onboard before 02/07/2025\n• Annual Summer Vacation support from 700 hundred VND to 4 Million VND and up to 3 days off work.\n• 13th-month Salary.\n• Salary review according to Company Policy.\n• Annual leave according to Labor Law and Company Policy.\n• “FPT care” health insurance provided by Petrolimex (PJICO) and is exclusive for FPT employees: 57M – 160M.\n• 20% discount on school fee if your sons/daughters join FPT School.\n• Excellent cost-free learning opportunities: Udemy/ELSA PRO accounts for every employee & Udacity accounts for Managers, English/Japanese/Korean classes, sponsorship for taking certification such as PMP, AWS, etc.\n• International, professional, dynamic and friendly working environment and culture.\n• Be part of a team in an international world-class company and exchange knowledge with technology specialists and experts from the world’s leading companies.\n• Frequent staff activities and company parties;\n• Awesome social events and parties for employees.\n• Etc.\n\nSpecial offer for senior level:\n• Relocating package: Up to 100M (for senior candidates from Hanoi/HCM.C to Da Nang City).\n• Loan support: 4% interest rate (1 – 2 Billion VND package).\n\nĐịa điểm làm việc\n- Đà Nẵng: Tòa Nhà FPT Complex, Ðường Nam Kỳ Khởi Nghĩa, Phường Hoà Hải TP.Ðà Nẵng, Ngũ Hành Sơn\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2941, 1193, 2, 'Server Developer (C Language)', 'Mô tả công việc\n- Develop server-side systems using Unix/Linux C programming within the Kiwoom platform, utilizing CISAM, IPC, and Shared Memory\n- Collaborate directly with remote teams to clarify tasks and requirements\n- Analyze user requirements and participate in system design to develop new features\n- Investigate and resolve reported issues and bugs during integration testing, user acceptance testing, and maintenance testing\n- Manage time and resources effectively based on the Work Breakdown Structure (WBS)\n- Compile weekly progress reports detailing task status and developments\n- Engage in continuous self-learning to acquire domain knowledge, prepare reports, and conduct seminars to share insights\n- Write high-quality, clean, maintainable, and testable code following best practices.\n- Ensure technical documentation is accurate and up-to-date\n- Gain hands-on experience in all stages of diverse projects, covering various aspects of software engineering and fostering your professional growth.\n\nYêu cầu ứng viên\n- Education & Experience\n  - Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n  - Minimum 3 years of professional experience in C language\n  - Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\n- Technical skills\n  - Experience with C language focus in: CISAM, IPC, Shared Memory\n  - Prior experience with Korean stock market systems is a significant advantage.\n  - Familiarity with version control systems, such as Git or SVN.\n  - Familiarity with issues tracking tools, such as Redmine.\n\n- Soft Skills & Communication\n  - Able to communicate in English, written and spoken (processed by English interview).\n  - Strong communication skills and teamwork, international experience is preferred.\n  - Strong problem-solving and analytical skills.\n\n- Give Reference\n  - Over 1 year of experience in developing securities solutions under channel server side\n  - Experience on working with oversea team.\n  - Develop and maintain the Channel Server for the Korean stock market system\n  - Providing training and education experience in Korea with Korean Finance/IT expert\n\n- SPECIAL OFFER\n  - Providing opportunities to work and support in IT/Finance fields overseas.\n\nQuyền lợi\n- Income & Achievement\n  - Competitive salary, salary review once a year\n  - 13th month salary and Annual Performance Bonus\n  - MVP and Shining star awards at the end of the year\n  - Global and professional working environment\n\n- Workplace Happiness\n  - Full SHUI as Vietnamese Law\n  - Premium Private Medical Insurance PVI and annual health check\n  - 15-day annual leave, Christmas leave and 30-min menstrual leave for women\n  - Company trip, YEP and monthly gathering time\n  - Gifts on special occasions and fully stocked snack corner\n  - Sponsored training courses and book purchase quarterly\n  - Be well-equipped with new working equipment.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tầng 14, tòa nhà AP, 518B Điện Biên Phủ, Phường 21, Bình Thạnh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2942, 1340, 2, 'Kỹ Sư Lập Trình PC Control', 'Mô tả công việc\n- Development of automation equipment PC control\n- More details to be discussed during interview\n- Working in HAI PHONG office.\n- Collaborate with hardware and software teams to integrate and optimize PC-based control systems for automated machinery.\n\nYêu cầu ứng viên\n- Experience in operating PC machine\n- C#, C++ available\n- Fluent in English, able to abroad business trip\n- Graduated from Electrical & Electronics, Automation, IT related majors\n- Accept new students graduate.\n\nQuyền lợi\n- Nghỉ 2 T7, 4 Chủ Nhật\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội học hỏi và phát triển kỹ năng trong lĩnh vực công nghệ và sản xuất\n- Được đào tạo về quy trình sản xuất và các công nghệ mới trong ngành\n- Chế độ bảo hiểm, phúc lợi đầy đủ theo quy định của pháp luật\n- Lương thưởng cạnh tranh, đánh giá năng lực định kỳ để tăng lương\n- Các chế độ phúc lợi: du lịch hằng năm, teambuilding, sinh nhật, lễ tết\n- Được tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn.\n\nĐịa điểm làm việc\n- Hải Phòng: Thửa đất B31 thuộc Lô CN4, KCN An Dương, Phường Hồng Phong, An Dương.\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2943, 1144, 2, 'Senior Back-End Developer', '- Phân tích, thiết kế và phát triển hệ thống backend sử dụng Python, FastAPI, theo kiến trúc Clean Architecture.\n- Thiết kế và triển khai hệ thống ETL, batch sử dụng Databricks Job.\n- Xây dựng và tối ưu các API chuẩn REST, sử dụng SQLAlchemy/Pydantic/Alembic để quản lý schema và model.\n- Quản lý tiến độ, phân công task, hỗ trợ kỹ thuật cho team backend.\n- Triển khai các API xác thực bằng API Key rotation, quản lý quyền truy cập.\n- Tích hợp ElasticSearch làm công cụ tìm kiếm.\n- Hướng dẫn và đào tạo thành viên team backend (code convention, kiến trúc, review code).\n- Thiết lập và vận hành môi trường CI/CD.\n- Phân tích hành vi người dùng và log truy cập sử dụng BigQuery, Looker Studio, Google Analytics.\n- Tối ưu performance backend, xử lý rollback, blue-green/canary deployment khi release ứng dụng.\n- Phối hợp chặt chẽ với các bên liên quan: frontend, data engineer, infra, QA để đảm bảo luồng phát triển liền mạch.\n\nYêu cầu ứng viên\n\nKỹ năng chuyên môn\n- 5+ năm kinh nghiệm lập trình với Python, thành thạo FastAPI,\n- Có kinh nghiệm xây dựng hệ thống với hiệu năng cao, hiểu rõ kiến trúc microservices.\n- Có kinh nghiệm tích hợp và tối ưu hóa Elasticsearch cho hệ thống tìm kiếm và phân tích dữ liệu.\n- Thành thạo thiết kế kiến trúc và tối ưu cơ sở dữ liệu phục vụ hiệu suất và khả năng mở rộng.\n- Hiểu biết rõ và cách áp dụng design patterns.\n- Có kinh nghiệm triển khai, giám sát và vận hành hệ thống trên các cloud như GCP / Azure / AWS.\n- Nắm vững các nguyên tắc Bảo mật & An toàn hệ thống, đảm bảo an toàn dữ liệu và phòng chống tấn công phổ biến (OWASP, v.v.).\n- Tối ưu hiệu suất hệ thống: caching, queue, async processing.\n- Có kinh nghiệm xây dựng và duy trì quy trình CI/CD, triển khai chuẩn hóa và tự động hóa môi trường DevOps.\n\nKỹ năng quản lý\n- Có 3+ năm kinh nghiệm vai trò leader dẫn dắt nhóm kỹ thuật.\n- Có khả năng review code, hướng dẫn kỹ thuật, kiểm soát chất lượng thông qua quy trình Agile/Scrum.\n- Khả năng định hướng kiến trúc hệ thống, phân chia công việc hợp lý và tối ưu năng lực thành viên trong nhóm.\n- Kỹ năng giao tiếp tốt, có khả năng truyền đạt ý tưởng rõ ràng và thuyết phục.\n- Có kinh nghiệm phối hợp hiệu quả giữa các nhóm chức năng (FE, QA, DevOps...).\n\nQuyền lợi\n\n– Thu nhập upto 45M. \n– Thử việc 2 tháng hưởng 100% lương\n– Tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật lao động\n– Tham gia bảo hiểm VBI\n– Review lương 2 lần/năm\n– Lương tháng 13, thưởng lễ, Tết, Tang lễ, Sinh nhật,...\n– Hỗ trợ chi phí thi chứng chỉ theo quy định của công ty\n– Phụ cấp khi nhận chứng chỉ\n– Phụ cấp gửi xe\n– Phụ cấp thâm niên, thưởng dự án xuất sắc\n– Du lịch hằng năm theo chính sách của công ty\n– Khám sức khỏe định kỳ hằng năm\n– Cơ hội thăng tiến rõ ràng\n– Cơ hội làm việc tại các nước đối tác: Nhật Bản, Hàn Quốc, Singapore, Úc\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: 10F Mekong Tower, 235 Cong Hoa, Ward 13, Tân Bình\n\nThời gian làm việc\n\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2944, 1436, 2, 'Data Integration Engineer / ETL Developer', 'Mô tả công việc\n- Thiết kế, cấu hình và bảo trì flow Asteria Warp để tự động hóa quá trình lấy – biến đổi – xuất dữ liệu giữa nhiều nguồn như DB, FTP/SFTP, API, file CSV/Excel…\n- Tối ưu hiệu năng, giám sát vận hành, xử lý sự cố và đề xuất cải tiến cho các luồng tích hợp dữ liệu.\n- Phân tích yêu cầu nghiệp vụ, lập tài liệu thiết kế, test case, hướng dẫn vận hành; tham gia review chéo bảo đảm chất lượng.\n- Phối hợp chặt chẽ với PM/BrSE và QA để hoàn thành mục tiêu dự án đúng tiến độ và tiêu chuẩn khách hàng Nhật Bản.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Công nghệ Thông tin hoặc tương đương.\n- Kinh nghiệm thực tế với Asteria Warp (hoặc công cụ ETL/low-code tương đương).\n- Kiến thức nền tảng về cơ sở dữ liệu và SQL; kinh nghiệm Oracle hoặc PostgreSQL là lợi thế.\n- Có khả năng lập tài liệu kỹ thuật, tuân thủ quy trình phát triển phần mềm.\n- Tư duy logic, chủ động học hỏi, đam mê công nghệ tích hợp dữ liệu.\n- Tiếng Nhật (N3 trở lên) là điểm cộng lớn.\n- Biết C# /.NET là một lợi thế.\n\nQuyền lợi\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc; \n- Thu nhập: 13 tháng lương/năm + thưởng kinh doanh cuối năm + thưởng dự án, thưởng các dịp lễ…; \n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc; \n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty; \n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30); \n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành; \n- Bảo hiểm chăm sóc sức khỏe 24/24; \n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội; \n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện); \n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày; \n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành;\n- Miễn phí đồ uống tại khu ăn uống của công ty; \n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan; \n- Phụ cấp thâm niên; phụ cấp chức vụ; \n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLUB Dance;...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm;...\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.\n\nĐịa điểm làm việc\n- Hà Nội: Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2945, 1159, 2, '[ĐN/HN] Web3 Frontend Developer (Middle/Senior)', 'Mô tả công việc:\n- Develop and maintain responsive, interactive user interfaces using ReactJS\n- Integrate decentralized Web3 wallets such as MetaMask and WalletConnect into frontend applications\n- Design seamless and intuitive user experiences for blockchain transactions\n- Build scalable and reusable React components using TypeScript for maintainable codebases\n- Implement efficient state management across applications using Redux or Zustand\n- Integrate frontend interfaces with robust backend API endpoints for dynamic data handling\n- Write and maintain comprehensive unit and integration tests to ensure code quality\n- Optimize frontend performance and continuously improve the overall user experience\n- Ensure cross-browser and cross-device compatibility for consistent application behavior\n\nYêu cầu ứng viên:\n- Expertise in building web applications using ReactJs\n- Advanced programming skills in TypeScript\n- Solid understanding of Web3 wallet interactions\n- Experience with modern state management libraries\n- Strong proficiency in responsive design\n- Knowledge of blockchain transaction flows\n- Strong testing skills with Jest and React Testing Library\n- Technical Stack: React, TypeScript Web3.js/ethers.js, Redux/Zustand, Tailwind CSS, Jest, React Testing Library, Vite/Next.js\n- Good English communication (writing, reading, speaking, and listening) is a plus.\n\nQuyền lợi:\n- Build World class product(s): We love to solve complex problems and learn new things.\n- Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n- Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n- Enjoy competitive salary, bonus according to work performance\n- Assistance with operational tools and equipment.\n- Flexible working hours, freestyle attire\n- Perks You\'ll Enjoy:\n  Working in a young, super talented, and supportive team environment\n- Technical, English certificate bonus\n- Day-off: 12 days/year and Vietnam holidays\n- Happy Hour, Football club, English club, and many exciting activities\n- Company trip/ team building/ Year End Party\n- Free coffee, snacks, and drinks\n\nĐịa điểm làm việc:\n- Đà Nẵng: 68 Xô Viết Nghệ Tĩnh, Hải Châu\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2946, 1479, 2, 'Phần Mềm', 'Mô tả công việc\n1. Phát triển và tích hợp hệ thống fullstack:\n- Thiết kế và phát triển các API backend chất lượng cao, có khả năng mở rộng bằng Python, sử dụng các framework như FastAPI, Django hoặc Flask.\n- Phát triển ứng dụng web đáp ứng (responsive) sử dụng ReactJS và ứng dụng mobile/desktop đa nền tảng sử dụng Flutter.\n- Lập trình firmware cho các hệ thống nhúng trên các vi xử lý ARM, PIC, STM32, đảm bảo tích hợp mượt mà với các hệ thống phần cứng và phần mềm.\n\n2. Tích hợp và tối ưu hóa hệ thống:\n- Tích hợp RESTful APIs, các giao thức giao tiếp (như MQTT) và các module phần mềm giao tiếp với thiết bị ngoại vi (Motor Driver, GPS, IMU).\n- Tối ưu hóa hiệu suất ứng dụng trên cả backend, frontend và firmware, đảm bảo tương thích đa nền tảng và trên nhiều thiết bị.\n- Phân tích và tối ưu các thành phần hệ thống dựa trên yêu cầu sản phẩm.\n\n3. Thiết kế và triển khai giao diện người dùng:\n- Chuyển đổi thiết kế từ Figma thành giao diện chất lượng cao cho cả web và mobile, đảm bảo tính nhất quán với yêu cầu từ đội UI/UX.\n- Đảm bảo chất lượng mã nguồn thông qua viết Unit Test, Function Test và Integration Test.\n\n4. Phát triển và kiểm thử:\n- Thiết kế, triển khai và kiểm thử các module phần mềm/firmware có khả năng tái sử dụng và dễ bảo trì.\n- Phát triển các công cụ và chương trình hỗ trợ kiểm thử hệ thống.\n\n5. Hợp tác liên phòng ban:\n- Phối hợp chặt chẽ với các đội frontend, backend, UI/UX, thiết kế phần cứng, và hệ thống để đảm bảo tích hợp liền mạch giữa các thành phần.\n- Hỗ trợ sau triển khai, sửa lỗi và cải tiến sản phẩm dựa trên phản hồi thực tế.\n\n6. Tài liệu hóa:\n- Viết và bổ sung tài liệu thiết kế, mô tả, và hướng dẫn sử dụng sản phẩm.\n- Thực hiện các công việc chuyên môn khác theo sự phân công của quản lý.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học các chuyên ngành Điện, Điện tử Viễn thông, Khoa học Máy tính, Công nghệ Thông tin hoặc các ngành liên quan.\n- Tối thiểu 5 năm kinh nghiệm làm việc với Python (sử dụng FastAPI, Django hoặc Flask), ReactJS hoặc Flutter, và lập trình C trên các hệ thống nhúng.\n- Thành thạo thiết kế giao diện người dùng đáp ứng (responsive) và các nguyên tắc lập trình hướng đối tượng (OOP) cùng Design Patterns.\n- Hiểu biết vững chắc về RESTful APIs, các giao thức giao tiếp web (như MQTT) và các chuẩn công nghệ giao tiếp không dây (Bluetooth, NFC là một lợi thế).\n- Kinh nghiệm làm việc với cơ sở dữ liệu SQL và NoSQL (như Cassandra, PostgreSQL).\n- Thành thạo hệ điều hành Linux, Linux driver, và các công cụ Tool Chain cho kiến trúc ARM Cortex-M.\n- Kỹ năng giải quyết vấn đề, tư duy logic và hiểu biết tốt về cấu trúc dữ liệu và giải thuật.\n- Thành thạo sử dụng Git và có kỹ năng làm việc nhóm tốt.\n- Khả năng đọc hiểu tài liệu kỹ thuật bằng tiếng Anh. Kỹ năng giao tiếp tiếng Anh tốt.\n- Giao tiếp với khách hàng, đồng nghiệp tốt.\nKỹ năng ưu tiên:\n- Kinh nghiệm hoặc hiểu biết về IoT, hệ thống nhúng, vi điều khiển (STM32, ARM, PIC, AVR), thiết kế phần cứng, sơ đồ mạch, và các công cụ PCB như Altium hoặc OrCAD.\n- Kinh nghiệm tích hợp giữa web, mobile và IoT trong các dự án thực tế.\n- Thành thạo các công cụ tối ưu hóa và kiểm soát hiệu suất ứng dụng.\n- Có kinh nghiệm phát triển các module phần mềm giao tiếp với thiết bị ngoại vi (Motor Driver, GPS, IMU).\n\nQuyền lợi\n- Điều chỉnh lương 1 năm/lần. Có chính sách review lương bổ sung đối với các trường hợp nhân viên có nhiều cố gắng hoặc được đánh giá cao trong công việc.\n- Thưởng Tết, thưởng các dịp Lễ, chế độ phúc lợi khác.\n- Du lịch hàng năm, Teambuilding,…\n- Được đảm bảo đầy đủ các chế độ: BHXH, BHYT, BHTN theo luật lao động quy định, Bảo hiểm sức khỏe Bảo Việt.\n- Nghỉ phép: 12 ngày/năm. Cứ mỗi 5 năm thâm niên được công thêm 1 ngày phép. Được trả lương phép.\n- Thời gian làm việc: 44h/tuần. Từ thứ 2 - thứ 5 (8h-18h), Thứ 6 (8h-17h).\n- Có cơ hội được tham gia các khóa đào tạo nâng cao trình độ chuyên môn trong và ngoài nước.\n- Được tham gia vào các dự án lớn, đa quốc gia.\n\nĐịa điểm làm việc\n- Hà Nội: Số 12 BT1 X2 khu đô thị Bắc Linh Đàm, Hoàng Mai.\n\nThời gian làm việc\n- Thứ 2 - Thứ 5 (từ 08:00 đến 18:00)\n- Thứ 6 (từ 08:00 đến 17:00)\n- Có thể làm việc từ thứ 2 đến sáng thứ 7.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2947, 186, 2, 'Lập Trình Viên Client', 'Mô tả công việc\n• Xây dựng và duy trì quan hệ đối tác với các đối tác chiến lược, phụ trách nghiên cứu, phát triển Games/App\n• Mở rộng mạng lưới đối tác bằng cách tiếp cận với các đối tác khu vực, toàn cầu\n• Trao đổi thông tin, đàm phán điều kiện hợp tác\n• Xây dựng và phát triển về hình ảnh của sản phẩm và công ty\n\nYêu cầu ứng viên\n• Bắt buộc ứng viên sử dụng được Unity\n• Thành thạo C# và có thể sử dụng JavaScript\n• Bắt buộc có kinh nghiệm sử dụng công cụ Git, và có hiểu biết về CI/CD\n• Kinh nghiệm: từ 5 năm trở lên\n• Yêu cầu: Có portfolio kèm mã nguồn (code đính kèm để có thể đánh giá kĩ năng thực tế)\n• Trong quá trình phỏng vấn:\n + Có thể có bài thi viết tự luận về design pattern\n + Kèm theo bài kiểm tra lập trình (coding test)\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận.\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước)\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm , Tiêm phòng HPV, cúm,...\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes Gardenia Hàm Nghi, Nam Từ Liêm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2948, 1403, 2, 'Kỹ Sư Phần Mềm / Software Engineer', '1. Hỗ trợ hiện trường và bảo trì phần mềm thiết bị bán dẫn\n- Cài đặt, bảo trì và xử lý sự cố phần mềm thiết bị bán dẫn\n- Thu thập và phân tích yêu cầu từ khách hàng (VoC)\n- Thăm trực tiếp khách hàng trong và ngoài nước, hỗ trợ kỹ thuật (Toàn cầu: Mỹ, Đài Loan, Hàn Quốc, Nhật Bản)\n- Phân tích log phần mềm thiết bị bán dẫn\n\n2. Test chức năng phần mềm\n- Viết và tiếp nhận các trường hợp test (Test Case)\n- Test mô phỏng\n- Viết báo cáo test và đưa ra các điểm cần cải tiến\n- Bảo trì phần mềm điều khiển thiết bị\n\n3. Phát triển chức năng phần mềm\n- Phát triển và gỡ lỗi chức năng phần mềm theo đơn vị/khối \n- Phát triển driver truyền thông\n- Thiết kế và hiện thực giao diện người dùng (GUI)\n\nYêu cầu ứng viên\n- Từ 0 đến 5 năm lĩnh vực có liên quan, hoặc tốt nghiệp Đại học chuyên ngành\n- Am hiểu chương trình C++, C#\n- Tiếng Anh hoặc tiếng Hàn đọc hiểu trong công việc \n- Sẵn sàng tham gia đào tạo, công tác nước ngoài (Hàn, Mỹ, Nhật, Đài Loan,...)\n\nQuyền lợi\n- Thời gian làm việc: từ thứ 2 đến thứ 6 (5 ngày/ tuần)\n- Môi trường làm việc năng động, chuyên nghiệp, với nhiều cơ hội phát triển\n- Thử việc hưởng 100% lương, thường không phát sinh OT (nếu phát sinh sẽ chi trả theo Luật Lao động)\n- Team- building, company trip\n- Lương, thưởng, xét tăng lương hàng năm\n- Đào tạo nước tại Hàn Quốc và phụ cấp đào tạo\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Charmvit Tower, 117 Trần Duy Hưng, Cầu Giấy\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2949, 1216, 2, 'IT Developer/ASP.NET/MES/Kỹ Sư Công Nghệ Thông Tin (Lương Upto 30 Triệu)', 'Mô tả công việc: 1. Design, develop, and maintain MES systems tailored for SMT production lines. 2. Collaborate with manufacturing engineers and production staff to gather system requirements. 3. Develop both backend logic and front-end interfaces using ASP.NET and modern web technologies. 4. Integrate MES with various production equipment and databases. 5. Develop middleware applications using WPF or Windows Forms. 6. Ensure system reliability, scalability, and maintainability. 7. Troubleshoot and resolve issues in existing MES applications. 8. Write documentation for system features and provide technical support when needed.\n\nYêu cầu ứng viên: 1. Bachelor\'s degree in Computer Science, Information Technology, or a related field. 2. At least 2.5 years of hands-on experience with ASP.NET development (Web Forms or MVC). 3. Experience working with HTML, CSS, JavaScript, and Bootstrap for UI development. 4. Experience with relational databases such as SQL Server or Oracle. 5. Familiarity with manufacturing environments, preferably in SMT or electronics industries. 6. Strong problem-solving skills and the ability to work independently or as part of a team. 7. Basic communication skills in English. 8. Preferred experience with MES systems or industrial automation systems. 9. Familiarity with integration protocols (e.g., SECSGEM, Serial) is a plus. 10. Knowledge of version control tools (e.g., Git) and CI/CD pipelines.\n\nQuyền lợi: 1. 100% social insurance contribution based on the basic salary. 2. Lunch and phone allowance according to company regulations. 3. Full participation in insurance as regulated by law. 4. Training and development opportunities. 5. Professional, dynamic, and supportive working environment. 6. Annual health check and company trip.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2950, 1261, 2, 'Backend Developer', 'Mô tả công việc\n- Tham gia vào quá trình phân tích yêu cầu, thiết kế hệ thống và xây dựng các API, microservice\n- Xây dựng các giải pháp backend mạnh mẽ, có khả năng mở rộng và bảo trì cao cho các ứng dụng web và mobile của công ty\n- Tối ưu hóa hiệu suất hệ thống, đảm bảo tính ổn định và bảo mật của dữ liệu\n- Nghiên cứu và áp dụng các công nghệ mới để cải thiện quy trình phát triển và chất lượng sản phẩm\n- Phối hợp với các thành viên khác trong team (Front-end, DevOps, QA) để đảm bảo dự án được hoàn thành đúng tiến độ và đạt chất lượng cao\n- Viết unit test, integration test để đảm bảo chất lượng code\n- Tham gia vào quá trình code review để đảm bảo code được viết theo chuẩn và dễ bảo trì.\n\nYêu cầu ứng viên\n- Có ít nhất 3 năm kinh nghiệm làm việc với vai trò Backend Developer\n- Có kinh nghiệm làm việc với một trong các ngôn ngữ lập trình backend như: Java, Python, Node.js, Go\n- Có kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu như: MySQL, PostgreSQL, MongoDB\n- Có kinh nghiệm làm việc với các framework backend như: Spring, Django, Express.js\n- Có kinh nghiệm làm việc với các công nghệ như: Docker, Kubernetes, AWS, Google Cloud, Azure\n- Có kiến thức vững chắc về các design pattern, clean code, SOLID principles\n- Có khả năng làm việc độc lập và làm việc nhóm tốt\n- Có khả năng giải quyết vấn đề và tư duy logic tốt\n- Có khả năng đọc hiểu tài liệu tiếng Anh chuyên ngành.\n\nQuyền lợi\n- Làm việc tại công ty hàng đầu Việt Nam, luôn không ngừng phát triển với nhiều cơ hội thăng tiến bản thân.\n- Được đào tạo chuyên nghiệp, hoàn toàn miễn phí trước khi làm việc.\n- Môi trường làm việc trẻ, năng động và thân thiện.\n- Tham gia đầy đủ các chế độ BHYT, BHXH, BHTN.\n- Thu nhập hấp dẫn, phù hợp năng lực bản thân.\n- Lương tháng 13 và thưởng theo hiệu quả kinh doanh.\n- Khám sức khỏe định kỳ.\n- Thường xuyên tổ chức các chương trình hội thao, hội diễn văn nghệ, tân niên, tất niên.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tòa nhà 678, số 67 Hoàng Văn Thái, phường Tân Phú, Quận 7.\n\nThời gian làm việc\n- Thứ 2 - Chủ nhật (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2951, 1195, 2, 'Full Stack Developer (Node.Js/ReactJs/VueJs)', 'Mô tả công việc:\n- Tham gia phát triển, bảo trì và tối ưu các dự án phần mềm (web/app) của công ty trên cả frontend và backend.\n- Thiết kế, xây dựng và triển khai các tính năng mới theo yêu cầu nghiệp vụ.\n- Phối hợp với các thành viên trong team để xây dựng giải pháp tổng thể, đảm bảo chất lượng sản phẩm.\n- Tham gia phân tích, thiết kế hệ thống, review code, kiểm thử và triển khai sản phẩm.\n- Khắc phục các lỗi, tối ưu hiệu suất hệ thống và đề xuất cải tiến sản phẩm.\n- Thực hiện các công việc khác theo yêu cầu của cấp trên.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành CNTT\n- Có ít nhất 2 năm kinh nghiệm làm Fullstack Developer.\n- Thành thạo ít nhất một ngôn ngữ lập trình backend (Node.js /C#/Python...).\n- Thành thạo ít nhất một framework frontend hiện đại (ReactJS/VueJS/Angular...).\n- Có kinh nghiệm làm việc với cơ sở dữ liệu quan hệ (MySQL/PostgreSQL/MSSQL) và/hoặc NoSQL (Redis...).\n- Hiểu biết về API (RESTful API, WebSocket), authentication/authorization (JWT, OAuth2...).\n- Có kinh nghiệm với Git và quy trình CI/CD cơ bản.\n- Kỹ năng phân tích, giải quyết vấn đề tốt, tư duy logic, cẩn thận trong công việc.\n- Chủ động, trách nhiệm, tinh thần học hỏi và làm việc nhóm tốt.\n- Ưu tiên có kiến thức và kinh nghiệm công nghệ MessageQueue (MQ, Kafka, Rabbit, ActiveMQ..), Microservice; kinh nghiệm về nền tảng Cloud như AWS Cloud, Google Cloud là một lợi thế;\n- Ưu tiên có kiến thức và kinh nghiệm triển khai về K8s, Docker là một lợi thế;\n\nQuyền lợi:\n1. Lương thưởng cạnh tranh trên thị trường (theo thỏa thuận)\n2. Thời gian làm việc từ 8:30-17:30 các ngày từ thứ 2-6.\n3. Được tham gia đầy đủ các chế độ bảo hiểm theo pháp luật.\n4. Chế độ nghỉ phép 15 ngày/năm.\n5. Chế độ khám sức khỏe định kỳ hàng năm.\n6. Chế độ bảo hiểm nâng cao.\n7. Môi trường làm việc hấp dẫn, có cơ hội học hỏi, thăng tiến cao.\n8. Chế độ nghỉ mát/teambuilding hằng năm.\n9. Môi trường làm việc năng động, trẻ trung, nhiều hoạt động gắn kết.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2952, 1248, 2, 'Flutter Dev', 'Mô tả công việc\n- Tham gia trực tiếp các sản phẩm công ty đang phát triển và các phần mềm hỗ trợ quản lý nội bộ trong công ty\n- Chịu trách nhiệm phát triển các chức năng và đảm bảo chất lượng sản phẩm.\n- Tham gia phát triển dự án công ty do team phát triển từ đầu,\n- Kết hợp với các thành viên trong team cùng phát triển bản thân.\n\nYêu cầu ứng viên\n- Tìm hiểu và nghiên cứu các công nghệ mới.\n- Ham học hỏi, có thể tự làm việc độc lập\n- Ưu tiên có kiến thức với Javascript/ Flutter\n- Gắn link source code thực tế đã làm trước đó\n- Ưu tiên có kinh nghiệm với Reactjs/ Nextjs\n- Ưu tiên có kinh nghiệm làm việc với RestFul Api\n- Đã làm việc với chatbot hoặc AI là 1 lợi thế\n\nQuyền lợi\n- Vị trí Intern với mức lương hỗ trợ tối thiểu 8.000.000đ\n- Cung cấp thiết bị cho công việc: Macbook Pro, màn hình Dell 2k 24-27"\n- Các chế độ BHXH, BHYT đầy đủ theo quy định của luật lao động.\n- Lương thưởng theo năng lực của mỗi cá nhân, tháng lương thứ 13.\n- Phụ cấp ăn trưa và phí gửi xe.\n- Được hưởng nhiều chế độ đãi ngộ khác theo chính sách của Công ty.\n- Tham gia các sự kiện, workshop của công ty, chế độ du lịch hàng năm, sinh nhật hàng quý.\n- Môi trường làm việc trẻ, thân thiện, chuyên nghiệp\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 12A, tòa A3 Ecolife Capitol, số 58 Tố Hữu, Trung Văn, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 18:00)\n- Nghỉ 2 thứ 7 luân phiên trong 1 tháng, nghỉ chủ nhật, lễ tết\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2953, 1329, 2, 'Nhân Viên Lập Trình CNC Khuôn', 'Mô tả công việc\n- Tiếp nhận bản vẽ từ bộ phận thiết kế\n- Tiến hành các thao tác lập trình sử dụng phận mềm NX hoặc các phần mềm tương tự để lập trình gia công các chi tiết khuôn\n- Tách điện cực, điện xung\n- Xuất bản vẽ chương trình\n- Xuất bản vẽ điện cực xung\n- Hỗ trợ chương trình cho tổ vận hành trong quá trình vận hành máy\n\nYêu cầu ứng viên\n- Kinh nghiệm 2 năm trở lên về lập trình CNC \n- Sử dụng thành thạo phần mềm NX\n- Đọc hiểu bản vẽ kỹ thuật\nCó thể làm việc độc lập, chịu được áp lực công việc\n\nQuyền lợi\n- Thử việc nhận 100% lương\n- Mức lương hấp dẫn thỏa thuận theo năng lực \n- Hưởng đầy đủ các chế độ theo quy định của nhà nước: PHÉP NĂM, BHXH, BHYT…\n- Nâng lương hàng năm\n\nĐịa điểm làm việc\n- Bắc Ninh: Cạnh Golden Park, Quế Võ\n- Bắc Ninh: Gần Cầu Ngà, Quế Võ\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nTăng ca theo yêu cầu công việc, sự sắp xếp của quản lý\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2954, 1278, 2, 'Backend Developer', 'Mô tả công việc\n\nProject information:\nDevelop a large scalable website to provide Cloud Hosting service across Asia based on microservices architecture and AWS services.\nDevelop web apps for Cloud Hosting management systems.\nDevelop other management systems based on our core services.\nProject\'s tools & technologies:\nNodeJS\nNestJS\nDevOps CI/CD\nAgile, GitLab\nDocker\nAWS\nPostgreSQL, MySQL, MongoDB, Redis Angular\n\nYêu cầu ứng viên\n\nYour Skills and Experience:\nAt least 3 years of experience.\nDemonstrated design and programming skills using NodeJS, Typescript, JSON, Web Services\nExperience with databases (MySQL, MongoDB)\nExcellent experience in designing and implementing database systems with integrity, scalability, performance, reliability, security in mind.\nHuge plus if you are/have:\nExcellent fullstack developer\nExperience with Nest.js\nExcellent understanding of backend development best practices and standards\nImpeccable leadership skills and able to drive solutions\nExcellent understanding of CI/CD\nExcellent experience designing and developing backend microservices\n\nQuyền lợi\n\nBenefits as below:\nAttractive salary\nA professional and friendly working environment\nLaptop + LCD for working\n13th-month salary\nPerformance bonus\nPrivate Healthcare insurance\nBonus for all holidays\nAnnual company trip\nAnnual leave: 12 days per year\nTechnical training\nSnack and beverage daily, monthly team dinner\nYear end party\nBonus and leaves for wedding/funeral/newborn baby/sickness\nReferral bonus\n\nĐịa điểm làm việc\n-Cần Thơ: Ninh Kiều\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cần Thơ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2955, 272, 2, 'Tech Lead', 'Mô tả công việc\n- Phối hợp, hỗ trợ cùng với Technical Lead trong việc tiếp nhận đầu bài từ Business Analyst/ Business Solution nhằm đánh giá, phân tích tính khả thi việc triển khai sản phẩm.\n- Phối hợp, tham gia cùng với Technical Lead trong việc thiết kế giải pháp phần mềm, giải pháp tích hợp API, Module/Layer, Data storage.\n- Phát triển các sản phẩm phần mềm theo giải pháp, công nghệ do Technical Lead đưa ra (Nghiệp vụ phức tạp nhất; Độ khó sản phẩm cao nhất; Phạm vi ảnh hưởng và độ rủi ro cao nhất).\n- Triển khai các giải pháp bảo mật theo quy định.\n- Đánh giá yêu cầu xây dựng (đánh giá được hết tất cả các trường hợp, hiểu bản chất của vấn đề), sửa đổi tính năng.\n- Xử lý lỗi phát sinh trong quá trình vận hành.\n- Tổ chức chia sẻ/đào tạo chuyên môn nghiệp vụ/ Biz Domain trong mảng công việc phụ trách.\n- Tìm kiếm các phương án tối ưu nhằm nâng cao giải pháp, hiệu suất cho quá trình phát triển sản phẩm.\n- Nghiên cứu, cập nhật các xu hướng, công nghệ liên quan đến phát triển sản phẩm.\n\nYêu cầu ứng viên\n1. Kinh nghiệm làm việc\n- Có tối thiểu từ 5 năm kinh nghiệm phát triển backend sử dụng ngôn ngữ Java.\n- Có kinh nghiệm làm việc với các hệ quản trị dữ liệu quan hệ như MySQL/PostgreSQL và Search Engine như Solr/ElasticSearch...\n- Có kinh nghiệm viết Unit test, Integration test.\n- Ưu tiên có kinh nghiệm: Spring Cloud, Spring Security, Redis, Kafka, CICD ...\n- Có kinh nghiệm triển khai, phát triển phần mềm bằng Agile/ Scrum.\n\n2. Kiến thức/Năng lực chuyên môn/Kỹ năng\n- Có khả năng phân tích, sắp xếp và triển khai công việc theo thứ tự ưu tiên.\n- Có kỹ năng giao tiếp và làm việc nhóm tốt.\n- Có đam mê và định hướng lâu dài với nghề lập trình.\n- Cần phải có hiểu biết về khoa học máy tính.\n- Cần phải có hiểu biết vững chắc về các nguyên tắc cơ bản của JDK 8+, Spring boot 2.x+, Spring framework 5+.\n- Yêu cầu kiến thức và kỹ năng: API RESTful, Microservice architecture, Distributed transaction, Code management (GitHub/JIRA....)\n- Kiến thức về các ngôn ngữ lập trình: Đây là nền tảng cơ bản của lập trình. Một lập trình viên cần biết ít nhất một ngôn ngữ lập trình để có thể viết mã.\n- Kiến thức về các cấu trúc dữ liệu và thuật toán: Đây là những kiến thức cần thiết để viết mã hiệu quả và hiệu suất.\n- Kiến thức về các framework và thư viện: Các framework và thư viện cung cấp các tính năng và chức năng sẵn có, giúp lập trình viên tiết kiệm thời gian và công sức.\n- Kiến thức về cơ sở dữ liệu: Cơ sở dữ liệu lưu trữ dữ liệu của một ứng dụng hoặc trang web. Lập trình viên cần có kiến thức về cách truy cập và quản lý dữ liệu trong cơ sở dữ liệu.\n- Kiến thức về kiến trúc web: Kiến trúc web là cách thức các trang web và ứng dụng được thiết kế và xây dựng. Lập trình viên cần có kiến thức về cách thiết kế và xây dựng các trang web và ứng dụng có thể mở rộng và bảo mật.\n- Kiến thức về bảo mật: Bảo mật là một vấn đề quan trọng đối với các ứng dụng và trang web. Lập trình viên cần có kiến thức về cách bảo vệ các ứng dụng và trang web khỏi các cuộc tấn công bảo mật.\n\n3. Năng lực cốt lõi\n- Có tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty (IPAM & 4C).\n\nQuyền lợi\n1. Cộng đồng những người làm nghề chính trực và dấn thân phụng sự \n- Môi trường làm nghề tài chính chuyên nghiệp.\n- Làm việc với tinh thần làm chủ, sáng tạo và thách thức.\n\n2. Tổng thu nhập theo năng lực\n- Thu nhập xứng đáng theo năng lực và giá trị đóng góp.\n- Xem xét thay đổi thu nhập hàng năm.\n\n3. Chế độ đãi ngộ\n- Tham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động.\n- Được tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24.\n\n4. Tổ chức học tập và văn hóa sôi nổi\n- Không gian làm việc mở với trang thiết bị hiện đại.\n- Các hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.\n\nĐịa điểm làm việc\n- Hà Nội: 43 Lê Văn Lương, Thanh Xuân.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2956, 1136, 2, 'Lập Trình Mobile React Native (Kinh Nghiệm Từ 2 Năm) - Mức Lương 12 - 20 Triệu + Thưởng Dự Án', 'Mô tả công việc:\n- Phát triển và bảo trì các ứng dụng di động trên nền tảng iOS và Android.\n- Thiết kế, xây dựng và triển khai các tính năng mới cho ứng dụng.\n- Viết code sạch, hiệu quả và dễ bảo trì.\n- Thực hiện kiểm thử và gỡ lỗi ứng dụng.\n- Cải thiện hiệu năng và trải nghiệm người dùng của ứng dụng.\n- Hợp tác với các thành viên khác trong nhóm để hoàn thành dự án.\n- Tham gia vào quá trình lên kế hoạch và ước lượng thời gian cho các dự án.\n- Đóng góp ý tưởng và giải pháp để cải thiện chất lượng sản phẩm.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm phát triển ứng dụng di động.\n- Thành thạo React Native, JavaScript, TypeScript. Ưu tiên biết Java Kotlin Object C, Swift.\n- Hiểu biết về kiến trúc ứng dụng di động và các nguyên tắc thiết kế.\n- Có kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu (SQL, NoSQL).\n- Có kinh nghiệm sử dụng các hệ thống quản lý phiên bản như Git.\n- Quen thuộc với các phương pháp Agile (Scrum, Kanban).\n\nQuyền lợi:\n- Mức lương 12 triệu - 20 triệu + thưởng tháng 13 + thưởng dự án.\n- Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n- Cơ hội được làm việc với các công nghệ mới.\n- Được đào tạo và phát triển kỹ năng chuyên môn.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế theo quy định của pháp luật.\n- Thưởng các ngày lễ, tết và các hoạt động team building thường xuyên.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2957, 1337, 2, 'Senior Android Developer (Mini CTO)', 'Sonix là một nền tảng ứng dụng nhạc chuông di động thông minh, hướng đến việc cá nhân hóa trải nghiệm âm thanh trên điện thoại di động theo phong cách trẻ trung, hiện đại và giàu tính giải trí. Dự án tập trung vào khai thác các nội dung âm thanh độc quyền, xu hướng viral, nhạc hot và tích hợp công nghệ AI để đề xuất nhạc chuông phù hợp với cá tính, thói quen và cảm xúc người dùng.\n\nDự án Sonix sẽ được triển khai và vận hành bởi một công ty con chuyên trách, có cơ cấu quản lý riêng, độc lập về mặt vận hành, công nghệ và sản phẩm.\nTP Entertainment – với vai trò là nhà đầu tư chiến lược sẽ đóng góp nguồn lực tài chính, kinh nghiệm trong lĩnh vực Mobile App, đồng thời hỗ trợ định hướng phát triển thị trường và chiến lược thương hiệu cho Sonix.\nVị trí Mini CTO sẽ là lãnh đạo cao nhất về công nghệ trong công ty con phát triển ứng dụng Sonix:\n\nMÔ TẢ CÔNG VIỆC\nPhát triển và vận hành hệ thống:\n- Phát triển ứng dụng mobile trên nền tảng Android (Kotlin), bao gồm cả phía Client và Backend.\n- Quản lý và tối ưu hiệu suất hệ thống, xử lý các sự cố kỹ thuật như crash, ANR, đảm bảo độ ổn định cao cho sản phẩm.\n- Quản lý chất lượng kỹ thuật của source code và quy trình release sản phẩm.\nTư vấn và xây dựng giải pháp kỹ thuật:\n- Đưa ra giải pháp kỹ thuật toàn diện cho PM và đội ngũ kỹ thuật, bao gồm cả kiến trúc Client, Backend và System.\n- Tham gia định hướng, đánh giá và phê duyệt các giải pháp công nghệ quan trọng.\nQuản lý đội ngũ và tiến độ công việc\n- Quản lý nhóm Developers, QA, và làm việc chặt chẽ với các bộ phận Backend/System.\n- Điều phối công việc, theo dõi tiến độ và báo cáo trực tiếp với PM.\n- Đảm bảo tiến độ và chất lượng sản phẩm qua từng giai đoạn phát triển.\nĐào tạo và phát triển nhân sự\nĐánh giá và kiểm thử sản phẩm\n- Trực tiếp test sản phẩm trước khi release, đảm bảo các tiêu chuẩn về nghiệp vụ và trải nghiệm người dùng.\n- Đưa ra đề xuất cải tiến dựa trên hành vi người dùng, chỉ số vận hành và chiến lược sản phẩm.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2958, 1224, 2, 'Nhân Viên Developer Objective C', 'Mô tả công việc:\n- Tham gia phát triển và duy trì các ứng dụng iOS bằng Objective-C.\n- Tối ưu hiệu suất, sửa lỗi và cải tiến trải nghiệm người dùng.\n- Triển khai game/app lên Apple Store.\n- Cập nhật công nghệ mới, đề xuất cải tiến quy trình phát triển.\n- Có khả năng làm việc độc lập và chủ động.\n- Ưu tiên ứng viên có kinh nghiệm với Unity hoặc Cocos Creator.\nYêu cầu ứng viên:\n- Có khả năng làm việc độc lập.\n- Có từ 1–3 năm kinh nghiệm lập trình iOS bằng Objective-C.\n- Thành thạo Xcode, UIKit, CoreData, CoreAnimation, RESTful API.\n- Đã từng làm việc với các thư viện/framework phổ biến trên iOS.\n- Có kinh nghiệm đưa game/app lên Apple Store.\n- Hiểu biết về kiến trúc MVC, MVVM và các Design Patterns trong iOS.\n- Có kinh nghiệm với Unity, Cocos Creator là lợi thế lớn.\n- Biết Swift là một điểm cộng.\nQuyền lợi:\n- Mức lương: 10tr-20tr\n- Thời gian làm việc: 8h-17h30 (từ thứ 2- sáng thứ 7)\n- Cơ hội phát triển sự nghiệp, tham gia các dự án lớn.\n- Làm việc trong môi trường chuyên nghiệp, trẻ trung.\n- Được đào tạo, cập nhật công nghệ mới liên tục.\nĐịa điểm làm việc:\n- Hà Nội: Hà Đông\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n- Thứ 2- Thứ 6: 8h-17h30\n- Thứ 7: 8h-12h\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2959, 1284, 2, 'Lập Trình Viên PHP', 'Mô tả công việc\n- Tham gia phân tích yêu cầu, đề xuất giải pháp và xây dựng kiến trúc kỹ thuật cho các dự án phần mềm.\n- Tham gia xuyên suốt quá trình phát triển sản phẩm: lập trình, kiểm thử, tối ưu hiệu năng và sửa lỗi.\n- Báo cáo tiến độ công việc, đề xuất các cải tiến để nâng cao chất lượng dự án.\n- Hỗ trợ quản lý, tổng hợp và báo cáo công việc đội nhóm khi cần thiết.\n\nYêu cầu ứng viên\n- Tối thiểu 2 năm kinh nghiệm lập trình Backend với PHP và framework Laravel.\n- Có kinh nghiệm lập trình Frontend với VueJS, Bootstrap, jQuery.\n- Thành thạo xử lý và làm việc với các định dạng dữ liệu JSON, XML, SOAP.\n- Có kinh nghiệm với hệ quản trị cơ sở dữ liệu MySQL; ưu tiên ứng viên có hiểu biết về NoSQL, Cache.\n- Ưu tiên ứng viên có kiến thức hoặc kinh nghiệm làm việc với Node.js.\n- Ưu tiên ứng viên có khả năng làm Full Stack, từng tham gia các dự án theo mô hình Agile/Scrum.\n- Có hiểu biết về hệ điều hành Linux, cấu hình máy chủ Nginx là một lợi thế.\n- Có tinh thần trách nhiệm cao, chủ động trong công việc.\n- Tư duy logic tốt, có khả năng phân tích và giải quyết vấn đề hiệu quả.\n\nQuyền lợi\n- Nghỉ phép, nghỉ lễ theo Luật lao động Việt Nam.\n- Xét tăng lương hàng năm theo năng lực.\n- Tham gia BHXH, BHYT, du lịch, teambuilding theo chính sách Công ty.\n- Chế độ phúc lợi Lễ, Tết và thưởng theo quy định của Công ty.\n- Thưởng tháng lương thứ 13 và thưởng doanh số theo quý và năm.\n- Cơ hội thăng tiến nếu có thành tích làm việc tốt. Môi trường làm việc năng động, thân thiện, khuyến khích nhân viên phát triển và đóng góp ý kiến.\n- Được đào tạo kỹ năng và định hướng phát triển nghề nghiệp.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Suced, số 108 đường Nguyễn Hoàng, Mỹ Đình 2, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Nghỉ Thứ Bảy, Chủ Nhật\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2960, 1369, 2, 'Mobile App Developer', 'Mô tả công việc:\nLập trình Mobile app cho phần mềm của công ty \n- Phần mềm chuyên về bán hàng\n- Phần mềm chuyên về Bán lẻ\n- Phần mềm chuyên về CRM\n\nYêu cầu ứng viên:\n+ framework: reactjs, react native or flutter, flux, flow and redux, rxjs, webpack, material ui, javascript top framework,\n+ standard: git, ạjax\n+ solution: nodejs\n+ computer language: typescript, html, css, sass/scss, javascript/ jquery\n+ platform: npm\n+ others: restful api, web communication protocol, javascript development tools...\nPractices:\n+ git/ version control,\n+ debugging,\n+ performance analysis and optimization,\n+ responsive design\n\nĐánh giá cao UV có kinh nghiệm làm việc tích hợp với (cổng thanh toán online; các nền tản tmđt như shopee, tiki...), và có kinh nghiệm về chat websocket...\n\nQuyền lợi:\n- Lương tháng 13\n- BHXH theo quy định của nhà nước\n- Môi trường thân thiện\n- Nghỉ phép  theo quy định \n- Lương/thưởng theo năng lực\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 927/1 Cách Mạng Tháng Tám, Phường 7, Tân Bình\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nThứ 7 (từ 09:00 đến 17:00)\nThời gian làm việc Thứ 2 - Thứ 6: 9h00 - 18h00 \nThứ 7 làm cách tuần (Tuần làm - Tuần nghỉ): 9h00 -17h00\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2961, 1184, 2, 'Bridge Software Engineer - Remote', '❖ Bridge Software Engineer:\nLà cầu nối giữa đội phát triển ở Việt Nam và khách hàng Nhật Bản.\nPhân tích, trao đổi yêu cầu nghiệp vụ và kỹ thuật với khách hàng.\nKiểm soát tiến độ, quản lý dự án và báo cáo công việc định kỳ với khách hàng.\nKiểm tra chất lượng đầu ra của sản phẩm trước khi bàn giao.\n❖ Collaboration and Mentorship:\nLàm việc chặt chẽ với các đội nhóm đa chức năng, bao gồm product managers, designers, và engineers để đáp ứng các mục tiêu kinh doanh.\nCố vấn cho các kỹ sư cấp dưới và thúc đẩy văn hóa học tập, đổi mới trong đội nhóm.\n❖ Optimization and Innovation:\nGiám sát hiệu suất hệ thống, tối ưu hóa để cải thiện khả năng mở rộng và hiệu quả.\nTheo dõi các xu hướng công nghệ mới và đưa ra các đề xuất cải tiến.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học chuyên ngành Khoa học Máy tính, Kỹ thuật hoặc lĩnh vực liên quan.\nÍt nhất 5 năm kinh nghiệm phát triển phần mềm, bao gồm ... năm ở vai trò lãnh đạo, ... năm kinh nghiệm ở vị trí BrSE, tập trung vào các nền tảng như SaaS, PaaS hoặc IaaS.\nTiếng Nhật (JLPT N2 trở lên), tiếng Anh giao tiếp tốt là lợi thế.\nThành thạo cả công nghệ front-end và back-end, bao gồm nhưng không giới hạn ở:\n1. Front-end: HTML/CSS, JavaScript (React, Angular), CSS preprocessors (Sass, Less)\n2. Back-end: Java, Golang, Python.\n3. Databases: SQL (MySQL, PostgreSQL), NoSQL (MongoDB, Redis)\nCó kinh nghiệm với các nền tảng đám mây (AWS, Azure, Google Cloud) và công cụ CI/CD (Jenkins, Docker).\nHiểu biết sâu sắc về các mẫu thiết kế phần mềm, cấu trúc dữ liệu và thuật toán.\nQuen thuộc với phương pháp Agile/Scrum và các công cụ quản lý dự án (Jira, Trello).\n\nNice to have (ưu tiên):\nChứng chỉ về quản lý dự án hoặc công nghệ đám mây (ví dụ: PMP, AWS),\nSở hữu chứng chỉ Scrum là một lợi thế.\nHiểu biết về văn hóa làm việc của người Nhật; có kinh nghiệm trong môi trường gia công phần mềm hoặc Agile/Scrum.\nKỹ năng cố vấn và cộng tác tốt trong đội nhóm.\n\nQuyền lợi:\n-Chính sách bảo hiểm xã hội, bảo hiểm y tế theo quy định của Nhà nước.\n-Bảo hiểm sức khỏe PVI sau 01 năm làm việc.\n-Môi trường làm việc trẻ trung, năng động, thân thiện.\n-Cơ hội làm việc onsite tại Nhật Bản.\n-Thường xuyên tổ chức các seminar do chính nhân viên công ty thực hiện, tạo điều kiện nghiên cứu, trao đổi, phát triển.\n-Hỗ trợ tiền nhà ở trong bán kính 2km.\n-Hỗ trợ chi phí gửi xe và các tiện ích khác.\n\nĐịa điểm làm việc:\n- Đà Nẵng\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2962, 1347, 2, 'Unity Developer', 'Mô tả công việc\n• Implement and improve a variety of fast and efficient core software using Unity.\n• Maintain and build code using C# for all assigned work streams.\n• Provide architectural oversight across the entire application.\n• Collaborate to devise optimal engineering solutions to technical challenges.\n\nYêu cầu ứng viên\n• At least 2 years of experience in Unity.\n• Proficient with the .NET framework and its memory management.\n• Experience in performance optimization.\n• Passion for video games!\n\nDesirable Pluses\n• Experience with multiplayer gameplay systems, network replication, core engine, or tool development.\n• Experience with iOS/Android/PC platforms is a plus.\n• Knowledge of native languages (Objective-C, Swift for iOS, Java, Kotlin for Android, JavaScript for WebGL) is a plus.\n• Have a product published on Play Store or App Store.\n\nQuyền lợi\n• Annual performance bonus\n• Annual salary review\n• 16 annual leave days\n• Health care insurance & Health check\n• Birthday gift, Tet\'s gift\n• Company trip\n• Lunch allowance\n\nĐịa điểm làm việc\n• Hồ Chí Minh: 384/9-9A Nam Ky Khoi Nghia Street, Vo Thi Sau Ward, Quận 3\n\nThời gian làm việc\n• Thứ 2 - Thứ 6 (từ 09:00 đến 17:30)\n\nCách thức ứng tuyển\n• Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2963, 1480, 2, 'Project Manager (Ngành Game)', 'Mô tả công việc:\nQuản lý sản phẩm: \n- Lựa chọn chiến lược tiếp cận và dẫn dắt sự thành công của sản phẩm\n- Phân tích dữ liệu người dùng và thị trường để đưa ra quyết định sản phẩm phù hợp\n- Đảm bảo chất lượng sản phẩm thông qua phản hồi người dùng và cải tiến liên tục\nQuản lý dự án:\n- Lập kế hoạch, phân công công việc, kiểm soát tiến độ và xử lý rủi ro dự án\n- Điều phối nguồn lực trong dự án (GD, Art, Dev) để đảm bảo triển khai hiệu quả\n- Phối hợp các bộ phận liên quan để đảm bảo đúng tiến độ và chất lượng đầu ra\n\nYêu cầu ứng viên:\n- Có ít nhất 2 năm kinh nghiệm PM hoặc PO, có game thành công là 1 lợi thế\n- Có khả năng tổ chức và lên kế hoạch chi tiết, làm việc tốt được với team cross-functional\n- Có kỹ năng giao tiếp, quản lý thời gian, quản lý con người, giải quyết vấn đề tốt\n- Có kỹ năng phân tích và cải tiến sản phẩm tốt\n- Có khả năng đánh giá game và các mô hình kinh doanh game\n- Trung thực và thẳng thắn, trách nhiệm, giao tiếp tốt, tư duy tốt\n\nQuyền lợi:\n- Thu nhập hàng tháng hấp dẫn, cạnh tranh, mức lương cứng upto 30M.\n- Hỗ trợ bảo hiểm sức khỏe PVI khi lên chính thức.\n- Thưởng cố định tháng lương 13 và chia sẻ lợi nhuận theo hiệu suất (tổng thu nhập lên tới 14 – 20 tháng lương/năm).\n- Chính sách học tập hàng năm với mục tiêu phát triển, bồi dưỡng nhân viên từ 5M-20M/cá nhân.\n- Các hệ thống ghi nhận liên tục, vinh danh, khen thưởng trong quý và cuối quý, cuối năm thúc đẩy môi trường làm việc.\n- Các phúc lợi tốt và chăm sóc nhân viên đặc biệt: du lịch 2 lần/năm, team bonding mỗi quý, hỗ trợ chi phí khám sức khỏe định kỳ 1 lần/năm, sinh nhật, quà lễ Tết,...\n- Môi trường làm việc tiện nghi hơn 1000m2, cung cấp trang thiết bị hiện đại.\n\nĐịa điểm làm việc:\n- Hà Nội: 37 Lê Văn Lương, Thanh Xuân.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2964, 1302, 2, 'Junior Salesforce Developer', 'Mô tả công việc:\n- Work closely with customers, business analysts, and architects to understand requirements and translate them into technical designs\n- Develop custom Salesforce components using Apex, LWC, Visualforce, SOQL, and Flow\n- Customize standard and custom objects, workflows, approval processes, and validation rules\n- Implement Salesforce integration with external systems via REST/SOAP APIs, middleware, or third-party connectors\n- Participate in technical planning, estimation, and code reviews\n- Ensure solutions follow Salesforce best practices and comply with security and performance requirements\n- Support data migration, sandbox deployment, and production rollout\n\nYêu cầu ứng viên:\n- Basic understanding and some hands-on experience with Salesforce development.\n- Familiarity with Apex, LWC, Flow Builder, and Salesforce DX.\n- Exposure to Sales Cloud, Service Cloud, or other Salesforce modules.\n- Good understanding of Salesforce platform architecture, security, and governor limits.\n- Familiarity with or exposure to Salesforce integrations with external systems (REST/SOAP APIs, middleware)\n- Familiarity with CI/CD tools for Salesforce (Gearset, Copado, Jenkins, etc.)\n- Experience with Agile/Scrum methodologies\n- Good communication skills and a collaborative mindset.\n- A strong desire to learn and grow within the Salesforce ecosystem.\n\nCertifications:\n- Preferred: Salesforce Platform Developer I\n- Nice to have: Platform Developer II, Sales Cloud Consultant, Service Cloud Consultant, JavaScript Developer I, Sharing & Visibility Designer, Integration Architect\n- Bonus: Application Architect, System Architect (part of CTA path), Admin or Advanced Admin\n\nPreferred Qualifications:\n- Experience working with public sector clients or in regulated environments\n- Prior experience in Salesforce Community Cloud / Experience Cloud\n- Knowledge of Data Loader, SOQL, and deployment tools\n- Background in JavaScript, HTML/CSS for LWC components\n- Familiarity with Salesforce AppExchange packages\n\nQuyền lợi:\n- 5-day workweek\n- Young & vibrant working environment with great career development opportunities\n- Social insurance, medical insurance, unemployment insurance, are based on actual salary.\n- Yearly performance bonus (up to 2 months’ salary)\n- Regular team building events & internal activities (weekly happy hour, quarterly team building events, festival parties, etc.)\n\nĐịa điểm làm việc:\n- Hà Nội: 4th floor, Artemis Building, 3 Le Trong Tan Street, Khuong Mai Ward, Thanh Xuân\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2965, 1131, 2, 'SQL Developer (Oracle – Middle/Senior)', 'Mô tả công việc\n- Phát triển và tối ưu các truy vấn SQL, stored procedures, packages trên Oracle.\n- Thực hiện ETL, xử lý dữ liệu lớn phục vụ báo cáo và phân tích.\n- Phối hợp với các bộ phận liên quan (BA, Dev, Data) để triển khai giải pháp dữ liệu.\n- Đảm bảo hiệu năng, tính toàn vẹn và bảo mật dữ liệu.\n- Tham gia review code, chia sẻ kinh nghiệm (đối với ứng viên senior).\n\nYêu cầu ứng viên\n- Có từ 3 năm kinh nghiệm trở lên trong vai trò SQL Developer, làm việc với Oracle PL/SQL.\n- Thành thạo viết và tối ưu các truy vấn SQL phức tạp.\n- Có hiểu biết về kiến trúc cơ sở dữ liệu Oracle, indexing, performance tuning.\n- Có kinh nghiệm xử lý dữ liệu lớn và các quy trình ETL.\n- Tư duy logic, kỹ năng phân tích và giải quyết vấn đề tốt.\n- Có tinh thần học hỏi, chủ động trong công việc.\n\nQuyền lợi\n- Mức lương cạnh tranh.\n- Lương tháng 13.\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop.\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN).\n- 12 ngày phép/năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau.\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật.\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc.\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Du lịch nghỉ mát 1 lần/năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch.\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban.\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến.\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm.\n- Làm việc với tác đối tác lớn.\n- Review tăng lương định kỳ hàng năm (1 lần / năm).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2966, 1380, 2, 'Unity Developer (Sub Leader)', 'Mô tả công việc:\n・Develop and deploy 3D Unity apps on Mobile, PC, and supported devices.\n・Build and optimize applications on devices.\n・Coordinate directly with members (GD, Artist, Tester,...) to ensure outstanding product quality.\n・Fix bugs, improve features, optimize App performance on devices (tracking, rendering, interaction and UI/UX).\n・Participate in detail design and basic design for features/modules.\n・Write and update technical documents.\n・Analyze business requirements, propose appropriate technical solutions.\n・Mentoring and guiding Junior/Fresher members in the team.\n\nYêu cầu ứng viên:\n■Requirements:\n- At least 3 years of experience in developing Unity engine\n- Proficiency in Unity 3D programming, Csharp or C++ or C\n- Mastery of OOP, Design Patterns, data structures, algorithms and software architecture design\n- Know how to optimize 2d/3d apps in terms of capacity, RAM, CPU, Resources.\n- Experience working with:\nAnimation of Unity\nShader/Shader Graph, AssetBundles...\nUnderstanding of Particle System/3D modeling/Lighting/Texturing\nAbility to work with all aspects of application development including UI, animation...\nAbility to write maintainable code, focusing on performance, reusability and ease of understanding.\n\n■Preferred Skills:\n- Candidates with experience in team management\n- Ability to research, learn and apply AI technology\n- Candidates can communicate in English or Japanese\n\nQuyền lợi:\n・Probation: 1 month (100% full-time salary).\n・Full payment social insurance\n・Laptop or desktop for working (2 monitor)\n・13th-month salary\n・Company Courses, seminars (tech, software, study sessions) or online courses\n・Loyal allowance (from 1 year working)\n・Leader/Manager and Skill allowance\n・Salary based on ability (skill, contribution, result)\n・Review twice a year (January/July)\n・Clear carrer path: management, specialists\n・Medical examination\n・Bao Viet Premium Healthcare Insurance Package\n・New tech challenge\n・Full allowance (parking lot, commuting, lunch)\n・12 days Annual Leaves per annum (each 5 years will +1)\n・Welfare: learning allowance, monthly party, company training...\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 15A Nguyễn Trung Trực, phường 5, Bình Thạnh\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2967, 1232, 2, 'Cocos Developer', 'Mô tả công việc\nLập trình game trên nền tảng Cocos Creator.\nLàm việc với git, hiểu và sử dụng tốt git flow.\nTham gia phát triển các dự án game hướng tới thị trường global\nPhối hợp với các thành viên trong team để vận hành và tối ưu hoá sản phẩm\n\nYêu cầu ứng viên\nTốt nghiệp đại học chuyên ngành CNTT hoặc chuyên ngành liên quan\nKinh nghiệm làm việc với git, hiểu và sử dụng tốt git flow.\nCó kiến thức & kinh nghiệm làm việc với Cocos Creator.\nCó sản phẩm trên store là 1 lợi thế lớn\nHiểu rõ OOP\nĐam mê, yêu thích làm game, khả năng tư duy, sáng tạo tốt\nCó khả năng thiết kế cấu trúc có thể mở rộng và có tính bảo trì tốt\n\nQuyền lợi\nThưởng kinh doanh trực tiếp bằng % (Profit Share) tính theo đóng góp của ứng viên vào các dự án đã tham gia.\nThưởng các ngày lễ: 30/04, 01/05, 02/09, Tết Dương Lịch.\nQuà các ngày lễ: 08/03, 20/10, Trung Thu, Tết Âm Lịch.\nReview tăng lương linh hoạt không giới hạn. Phụ thuộc vào tiềm năng, khả năng và mức độ đóng góp của ứng viên.\nBHXH, BHYT, BHTN, 12 ngày nghỉ phép/năm. Nếu không dùng hết sẽ được chuyển sang năm tiếp theo.\nDu lịch, Team building tối thiểu 2 lần/năm.\nTổ chức sinh nhật hàng tháng. Happy Time (đồ ăn,đồ uống,hoa quả và các trò chơi nội bộ) 2 lần/tuần.\nKhu pantry gồm cafe, trà, đồ uống miến phí.\nKhu giải trí gồm Bàn Bi-a, PS, Board Game...\nKhu nội bộ gồm các phòng ngủ đẩy đủ trang thiết bị giành cho nhân sự cần ở lại công ty.\nTrải nhiệm các hoạt động văn hóa doanh nghiệp chỉ có ở GPLAY.\nĐược cung cấp đầy đủ trang thiết bị, máy móc để làm việc.\nCơ hội học hỏi và tham gia xây dựng các dự án game chất lượng, phát triển long-term.\nCơ hội được đào tạo chuyên môn, phát triển tư duy và tầm nhìn bởi đội ngũ Leader có nhiều năm kinh nghiệm trong ngành.\nCó cơ hội thăng tiến lên các vị trí Manager, Leader.\nMôi trường thân thiện, trẻ trung, hiện đại, không giới hạn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2968, 1246, 2, 'Python Developer', 'The project improves and optimizes data processing performance.\n- Develop and implement new features and functionalities within the existing system.\n- Collaborate effectively with cross-functional teams to ensure successful project delivery\n- Troubleshoot and debug issues related to application performance and functionality.\n\nYêu cầu ứng viên\n- University degree in IT, Computer Science, or related experiences.\n- Good understanding of SQL, Oracle DB and Python.\n- As a fast and eager learner, you enjoy digging into new technologies.\n- Good communication skill\n- Having self-management mindset\n- Having ability to work independently\n\nQuyền lợi\n- Salary negotiable\n- 100% salary during 2-month probation\n- Full-salary insurance starting right from probation period\n- 3 times bonus per year\n- 5 working days per week with flexible check-in\n- Health check once per year\n- Health care insurance package\n- Attractive training budget for each employee per year for personal training & Premium Udemy\n- Online Learning Account\n- Oversea training opportunities\n- Numerous internal activities: team bonding, team training,...\n- Gifts for each employee on 30/4,1/5; 2/9....(in cash)\n- Bonus for employee having Korean certificates or Software Test certificate\n\nĐịa điểm làm việc\n- Hà Nội: Tòa PVI, Số 1 Phạm Văn Bạch, Yên Hòa, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Monday-Friday with flexible check-in time\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2969, 1313, 2, 'Lập Trình Viên AWS', 'We are seeking a highly skilled and experienced AWS Monitoring & Operation Specialist to oversee system operations, monitor infrastructure health, and ensure optimal performance and security. This role involves working within a customer-provided environment to deliver high-quality support and continuous improvement.\n\nKey Responsibilities:\n\nSystem Monitoring & Alert Management\n- Continuously monitor system health using tools such as Amazon CloudWatch, Prometheus, Zabbix, etc.\n- Respond promptly to alerts and incident notifications.\n- Investigate root causes and execute recovery actions.\n- Recommend and implement preventive measures to avoid recurrence.\n\nPerformance Optimization\n- Analyze system performance and resource utilization across EKS clusters, Aurora PostgreSQL databases, and OpenSearch node.\n- Propose and implement tuning strategies to enhance performance and optimize costs.\n\nBackup & Restoration\n- Perform and verify scheduled system backups.\n- Ensure reliable and timely recovery procedures in the event of system failures or incidents.\n\nAccount & Security Management\n- Manage user accounts, roles, and permissions.\n- Conduct access reviews, vulnerability assessments, and security audits.\n- Define, implement, and enforce security policies and standards.\n\nSystem Maintenance\n- Apply operating system and middleware updates as required.\n- Deploy security patches and perform batch update activities in a timely manner.\n\nTechnical Support & Consultation\n- Provide technical guidance and troubleshooting support to internal teams.\n- Contribute to the development and maintenance of operational documentation and best practices.\n\nRequired Skills & Qualifications:\n\nTechnical Skills:\n- Experience with AWS services (EC2, S3, RDS, IAM, CloudWatch, Lambda and especially EKS, Aurora PostgreSQL, and OpenSearch)\n- Experience with AWS CLI, SDKs, and Infrastructure as Code (e.g., CloudFormation, Terraform).\n- Strong Linux/Unix/Windows system administration skills.\n- Scripting and automation experience (e.g., Bash, Python, Ansible).\n- Knowledge of AWS security best practices, access control, and vulnerability scanning.\n- Experience with backup strategies and disaster recovery planning.\n\nSoft Skills:\n- Strong analytical and problem-solving skills.\n- Effective communication and documentation abilities in English.\n- Japanese communication and documentation skills are a plus.\n- Capable of working both independently and as part of a team.\n- Proactive and customer-focused mindset with a commitment to delivering quality support.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2970, 1117, 2, 'Junior Backend Developer (NestJS / FastAPI)', 'Mô tả công việc\n- Thiết kế, phát triển và tối ưu hệ thống backend sử dụng NestJS (Node.js) và FastAPI (Python)\n- Làm việc với các hệ quản trị cơ sở dữ liệu như PostgreSQL, MongoDB, v.v.\n- Thiết kế và phát triển API phục vụ frontend hoặc ứng dụng mobile.\n- Triển khai, bảo trì, giám sát hệ thống backend theo hướng microservice.\n- Viết tài liệu kỹ thuật, API document (Swagger, Postman...).\n- Phối hợp chặt chẽ với frontend, QA, và DevOps để đảm bảo chất lượng hệ thống.\n\nYêu cầu ứng viên\n- Thành thạo NestJS (Node.js) và FastAPI (Python).\n- Hiểu rõ nguyên lý hoạt động RESTful API, WebSocket.\n- Có kinh nghiệm làm việc với PostgreSQL hoặc MongoDB.\n- Biết cách triển khai API bảo mật với JWT, OAuth2.\n- Nắm vững kiến thức về OOP, SOLID, Clean Architecture.\n- Có kinh nghiệm làm việc với Docker, Git.\n- Biết sử dụng Postman hoặc Swagger để kiểm thử API.\n\nƯu tiên:\n- Có kinh nghiệm triển khai hệ thống trên AWS, GCP, Vercel, hoặc DigitalOcean.\n- Biết sử dụng Celery, RabbitMQ, hoặc Redis Queue cho các tác vụ bất đồng bộ.\n- Có kinh nghiệm làm việc với hệ thống microservice.\n- Biết sử dụng các công cụ giám sát như Prometheus, Grafana, hoặc Sentry.\n- Có kinh nghiệm CI/CD (GitHub Actions, GitLab CI...).\n\nQuyền lợi\n- Thưởng các ngày lễ, Tết, sinh nhật, teambuilding... tùy tình hình kinh doanh công ty.\n- Tăng lương định kỳ hàng năm.\n- Các chế độ bảo hiểm đầy đủ theo quy định pháp luật.\n- Cung cấp thiết bị làm việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2971, 1452, 2, 'Kỹ Sư Lập Trình Firmware', 'Mô tả công việc\n- Lập trình Firmware cho các ứng dụng nhúng, IoT sử dụng STM32, Nordic chip, ESP32, Rasp Pi, Jetson và các OS development kit. \n- Xây dựng hệ thống quản lý các thiết bị, xây dựng API, IoT Cloud... \n- Kết hợp với bộ phận phát triển Hardware và Software để hoàn thành dự án.\n\nYêu cầu ứng viên\n- Trình độ: tốt nghiệp Đại học chuyên ngành Điện - Điện tử.\n- Kinh nghiệm: 2 năm kinh nghiệm.\n- Có hiểu biết sâu về các ứng dụng IoT, hệ thống nhúng, làm việc nhiều về OS (Linux, Yocto).\n- Có kinh nghiệm thiết kế PCB, kinh nghiệm test mạch là một lợi thế. \n- Có kinh nghiệm lập trình Python, build custom OS cho các dev kit như Rasp Pi, Orange, Jetson... \n- Làm việc nhiều với các chuẩn giao tiếp không dây: Wifi, BLE, Lora/LoraWAN, Zigbee... \n- Khả năng làm việc độc lập, chịu khó tìm tòi, nghiên cứu.\n\nQuyền lợi\n- Được làm việc trong môi trường trẻ trung và năng động\n- Đóng BHXH, BHYT theo quy định nhà nước.\n- Thời gian làm việc linh động.\n- Có thể làm việc online hoặc offline.\n- Được đào tạo và làm việc với nhiều loại dự án khác nhau để nâng cao năng lực bản thân, làm việc và tiếp xúc với khách hàng nước ngoài.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Khu đô thị Vạn Phúc, Thủ Đức\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nKhung thời gian làm việc trong ngày có thể linh động sắp xếp, tùy vào yêu cầu từng dự án.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2972, 1185, 2, 'C++ Developer', 'Mô tả công việc:\n- Design, develop, and maintain high-performance C++ applications.\n- Collaborate with cross-functional teams to define, design, and ship new features.\n- Optimize existing code for performance and scalability.\n- Conduct code reviews and provide constructive feedback to team members.\n- Troubleshoot and debug applications to ensure optimal functionality.\n- Stay updated with the latest industry trends and technologies related to C++ development.\n- Mentor junior developers and assist in their professional growth.\n\nYêu cầu ứng viên:\n- Proven experience as a C++ Developer, with a strong portfolio of projects.\n- Work independently (acquired another piece of software written in C++ which he is now selling to his clients)\n- In-depth knowledge of C++ programming language and its standard libraries.\n- Experience with software development methodologies such as Agile or Scrum.\n- Familiarity with version control systems, preferably Git.\n- Strong problem-solving skills and the ability to work independently.\n- Excellent communication and teamwork skills.\n\nEnglish: Fluent (at least upper-intermediate level)\nStart date: ASAP\nLocation: Remote Dedicated Fulltime (Not prefer 2nd Job)\nWorking hours: GTM+7\n\nQuyền lợi:\n- 35.000.000 - 50.000.000đ/tháng\n- Working in one of the Best Places to Work in Vietnam\n- Building large-scale & global software products\n- Working & growing with Passionate & Talented Team\n- Diverse careers opportunities with Software Outsourcing, Software Product Development, IT Solutions & Consulting\n- Attractive Salary and Benefits\n- Two performance appraisals every year and performance bonus\n- Onsite opportunities: short-term and long-term assignments in North American (U.S, Canada), Europe, Asia.\n- Flexible working time\n\nĐịa điểm làm việc:\n- Hồ Chí Minh\n- Hà Nội\n- Bình Dương\n- Đà Nẵng\n- Thừa Thiên Huế\n- Hải Phòng\n- Bắc Ninh\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 14:00 đến 23:00)\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh & 6 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2973, 1213, 2, 'Kỹ Sư Lập Trình', 'Mô tả công việc\n- Tham gia giai đoạn triển khai sản phẩm của siêu dự án phần mềm CAD – dự án lớn của tập đoàn DTS Japan, với nhiều modules phần mềm khác nhau, từ Windows App, Web App, iOS App…\n- Tuân thủ quy trình phát triển phần mềm chuẩn PMS của DTS Japan\n\nYêu cầu ứng viên\n- Ứng viên có kinh nghiệm từ 6 tháng đến dưới 2 năm kinh nghiệm về ngôn ngữ phát triển phần mềm ứng dụng\n- Ưu tiên ứng viên có kiến thức về xử lý đồ họa 3D, 2D; có kinh nghiệm làm dự án liên quan đến phần mềm CAD, đồ họa\n- Ưu tiên ứng viên biết tiếng Nhật và có kinh nghiệm làm việc cho công ty/ dự án Nhật\n\nQuyền lợi\nChế độ đãi ngộ\nLương thỏa thuận theo năng lực thực tế của ứng viên. Performance review: 1 lần/năm.\nTrợ cấp đi lại, trợ cấp ăn trưa, trợ cấp tiếng Nhật, trợ cấp onsite khi tham gia dự án bên khách hàng…\nThưởng Lễ Tết, tháng lương thứ 13, thưởng nhân viên xuất sắc quý, năm, nhân viên xuất sắc năm đi du lịch Nhật Bản\nNghỉ theo lịch công ty, nghỉ theo lịch khách hàng Nhật, (ngoài các ngày nghỉ theo quy định, 1 năm có thêm 2 đợt nghỉ dài)\nNghỉ tham gia Ngày hội khai giảng cùng con\nChế độ chăm sóc sức khỏe cho nhân viên\n\nBảo hiểm y tế, bảo hiểm xã hội, bảo hiểm thất nghiệp theo quy định của Luật lao động\nBảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên làm việc trên 1 năm\nKhám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín (Bệnh viện Thu Cúc, bệnh viện Medlatec…)\nVăn phòng làm việc tiện ích: Miễn phí trà, có máy pha coffee tại khu vực ăn uống của công ty\n\nCác hoạt động sôi nổi\nHoạt động team building kết nối đội nhóm hàng quý\nCác CLB thể thao: bóng đá, bi lắc…\nHoạt động du lịch, team building thường niên và các sự kiện lớn trong công ty\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 3 - Tòa nhà Ladeco 266 Đội Cấn, Ba Đình\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2974, 1255, 2, 'Mobile Developer', 'Mô tả công việc\n- Tham gia phân tích, thiết kế luồng phát triển của ứng dụng dựa vào yêu cầu của khách hàng\n- Đánh giá, phân tích, nâng cấp và tối ưu mã nguồn trong quá trình phát triển\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai\n- Tham gia đưa ra những ý tưởng, giải pháp mới cải thiện công việc.\n\nYêu cầu ứng viên\n- Có kinh nghiệm phát triển ứng dụng di động bằng iOS (Swift/Objective-c)\n- Biết sử dụng Git để quản lý mã nguồn\n- Có kinh nghiệm test, debug và tối ưu hiệu năng cho ứng dụng\n- Có kinh nghiệm làm việc, quản lý nhóm sử dụng Agile/Scrum.\n- Có hiểu biết về Design Pattern, Coding convention, cấu trúc dữ liệu và giải thuật, OOP\n- Có hiểu biết về phát triển ứng dụng di động bằng Cross-platform là 1 lợi thế (React Native, Flutter)\n- Có sản phẩm trên chợ ứng dụng CH Play, App Store là một lợi thế\n- Có tinh thần trách nhiệm, học hỏi và cầu tiến trong công việc\n\nQuyền lợi\n- Mức lương: thỏa thuận theo năng lực\n- Làm việc T2 - T6 (từ 08h30 – 18h00, nghỉ trưa 1,5 tiếng), T7 làm việc tại nhà các buổi sáng cách tuần\n- Tài trợ các hoạt động thể dục thể thao, trợ cấp gửi xe, liên hoan, trà bánh, trái cây hàng tuần,...\n- Lương Tháng 13, Thưởng hiệu quả kinh doanh cuối năm\n- BHXH, BHYT, BHTN đầy đủ cho nhân viên theo quy định của pháp luật\n- Xét tăng lương 06 tháng/lần\n- Tổ chức dã ngoại, Teambuilding, picnic công ty hàng năm.\n- Thưởng lễ, tết, sinh nhật,...\n- Nghỉ phép 12 ngày/năm, làm việc đủ 3 năm tăng 01 ngày phép.\n\nĐịa điểm làm việc\n- Đồng Tháp: Tầng 3, PG2-15 & PG2-15A, Nguyễn Đình Chiểu, P1, TP Cao Lãnh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Thứ 7 làm các buổi sáng cách tuần, làm việc tại nhà\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Tháp', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2975, 1351, 2, 'Fullstack Developer (Senior)', 'Mô tả công việc:\n- Thiết kế và tư vấn giải pháp kỹ thuật: Phối hợp với team Data để đưa ra kiến trúc công nghệ phù hợp cho các sản phẩm dữ liệu, API, dashboard và các ứng dụng phục vụ khách hàng.\n- Phát triển hệ thống backend & frontend hiện đại: Xây dựng API linh hoạt, bảo mật, hiệu suất cao với Node.js (Express/NestJS), hướng đến kiến trúc mở rộng và dễ tích hợp dữ liệu lớn. Phát triển frontend bằng Next.js (React) với giao diện tối ưu SEO, tốc độ cao, thân thiện người dùng và đa nền tảng.\n- Giám sát và tối ưu vận hành hệ thống: Đảm bảo hệ thống hoạt động ổn định, khả năng xử lý dữ liệu lớn, hiệu suất cao và sẵn sàng mở rộng theo nhu cầu thực tế.\n- Dẫn dắt và phát triển đội kỹ thuật: Phân công công việc, mentoring, đảm bảo chất lượng kỹ thuật, gắn kết team, xây dựng văn hóa học tập và đổi mới trong nhóm.\n- Chủ động tham gia phát triển và mở rộng sản phẩm dữ liệu và định hình công nghệ: thiết kế kiến trúc và chiến lược công nghệ cho nền tảng dữ liệu mở rộng, bao gồm tích hợp dữ liệu đa nguồn, phát triển hệ thống phân tích tự phục vụ, API thương mại hóa và báo cáo thông minh.\n\nYêu cầu ứng viên:\n- Yêu cầu bắt buộc:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành liên quan.\n- Tối thiểu 4 năm kinh nghiệm phát triển hệ thống web với JavaScript, thành thạo cả Node.js (Express hoặc NestJS) và Next.js (React).\n- Có kinh nghiệm xây dựng kiến trúc hệ thống fullstack JavaScript, tích hợp frontend/backend qua REST API hoặc GraphQL.\n- Thành thạo kiến thức về SSR/SSG, bảo mật ứng dụng web, tối ưu hiệu suất frontend/backend và xử lý dữ liệu lớn.\n- Ưu tiên ứng viên đã làm việc với PostgreSQL, MongoDB, Redis, RabbitMQ, Docker, hoặc các nền tảng cloud như AWS, GCP, Vercel.\n- Có kinh nghiệm thiết lập hoặc cải tiến quy trình CI/CD, tự động hóa kiểm thử, đảm bảo chất lượng mã nguồn.\n- Kỹ năng lãnh đạo và tư duy sản phẩm:\n- Từng quản lý nhóm kỹ thuật; biết cách thúc đẩy tinh thần đội nhóm, hỗ trợ kỹ thuật và truyền cảm hứng đổi mới.\n- Tư duy hệ thống, logic tốt, có khả năng chuyển hóa yêu cầu kinh doanh thành giải pháp kỹ thuật thực tế và hiệu quả.\n- Giao tiếp tốt, biết cách phối hợp liên phòng ban và giải thích giải pháp kỹ thuật cho team không chuyên.\n\nQuyền lợi:\n- Lộ trình phát triển rõ ràng: Cơ hội trở thành Tech Lead / Engineering Manager trong tương lai gần nếu thể hiện tốt.\n- Môi trường cởi mở, team trẻ trung, dễ triển khai ý tưởng mới, chủ động xây dựng quy trình phù hợp.\n- Mức lương cạnh tranh, thưởng theo dự án, đầy đủ chế độ bảo hiểm, nghỉ phép, lương tháng 13.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tòa nhà Jamona Heights, 210 Bùi Văn Ba, Quận 7\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- Thứ 7 (từ 08:30 đến 12:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2976, 389, 2, 'Senior Developer', 'Mô tả công việc\n- Quản lý DEV Team, hướng dẫn và hỗ trợ chuyên môn cho các thành viên trong nhóm.\n- Định hướng, phân tích và thiết kế kiến trúc hệ thống, đảm bảo hệ thống bền vững, an toàn thông tin, hiệu suất cao, dễ bảo trì, nâng cấp và mở rộng.\n- Lập trình Java core/Java web, API trên nền core framework của công ty hoặc các framework khác tùy sản phẩm, dự án.\n- Tham gia phát triển các hệ thống sản phẩm, dịch vụ của công ty: Phát triển các Module của sản phẩm/dịch vụ; Phối hợp với BA, Tester fix bug, update module; Merge code.\n- Thống nhất các mục tiêu, sản phẩm cũng như đưa ra phương án kỹ thuật của dự án.\n- Xử lý các vấn đề kỹ thuật phát sinh trong quá trình phát triển.\n- Các công việc khác theo yêu cầu của Trưởng bộ phận IT.\n\nYêu cầu ứng viên\n- Tốt nghiệp ĐH trở lên chuyên ngành Công nghệ thông tin; Kỹ thuật phần mềm, Hệ thống thông tin, ...hoặc các ngành tương đương.\n- Có từ 5 năm kinh nghiệm trở lên tham gia dự án thực tế, trong đó có ít nhất 2 năm kinh nghiệm Leader.\n- Thành thạo ngôn ngữ lập trình Java; Database: Oracle; Operating System: CentOS\n- Hiểu biết về SQL Language\n- Có kinh nghiệm lập trình Backend (server side), API\n- Có kinh nghiệm lập trình xử lý file PDF, xử lý ảnh.\n- Có thể đọc hiểu tài liệu kỹ thuật bằng tiếng anh.\n\nQuyền lợi\n- Thu nhập: từ 30 đến 35 triệu/tháng, thỏa thuận phù hợp với năng lực ứng viên.\n- Chế độ bảo hiểm, phúc lợi theo quy định của pháp luật và chính sách công ty.\n- Thưởng hằng năm, thưởng lễ tết, thưởng nóng cho những thành tích nổi bật.\n- Tham gia đầy đủ BHXH và các chế độ theo quy định của Bộ Luật lao động.\n- Chế độ du xuân, nghỉ mát cùng Công ty. Các hoạt động gắn kết nội bộ.\n- Môi trường làm việc từ Lãnh đạo đến nhân viên đều rất trẻ trung, năng động.\n- Cơ hội phát triển sự nghiệp bền vững và đề cao các giá trị Văn hóa doanh nghiệp.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 5, Toà nhà ACCI, Số 210 Lê Trọng Tấn, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 7: 8h00 - 12h00.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Thanh Xuân', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2977, 1369, 2, 'Lập Trình Viên BackEnd PHP/Laravel', 'Mô tả công việc:\n- Phát triển và bảo trì hệ thống backend bằng PHP và Laravel.\n- Thiết kế, tối ưu cơ sở dữ liệu và API phục vụ frontend.\n- Hỗ trợ và phối hợp với đội frontend để xây dựng các tính năng mới.\n- Tối ưu hiệu suất hệ thống, xử lý lỗi và nâng cao bảo mật.\n\nYêu cầu ứng viên:\n- Thành thạo PHP, HTML, CSS, JavaScript, jQuery, Bootstrap.\n- Ít nhất 2 năm kinh nghiệm làm việc với Laravel.\n- Có kinh nghiệm làm việc với cơ sở dữ liệu MySQL hoặc PostgreSQL.\n- Hiểu biết về RESTful API, WebSocket là một lợi thế.\n- Có kinh nghiệm làm việc với dữ liệu lớn, biết phân tích hệ thống.\n- Có kinh nghiệm làm việc với các hệ thống bán hàng, CRM là một lợi thế.\n- Khả năng làm việc nhóm tốt, tư duy logic và giải quyết vấn đề.\n\nQuyền lợi:\n- Phụ Cấp ăn trưa\n- Hỗ trợ thiết bị làm việc\n- BHXH/BHYT theo quy định của nhà nước\n- Thưởng cuối năm theo tình hình kinh doanh của công ty\n- Môi trường làm việc năng động thân thiện\n- Đồng nghiệp vui vẻ hoà đồng\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lầu 3, 3A, Phổ Quang, Phường 02, Tân Bình, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Thứ 7 (từ 09:00 đến 17:00)\n- Thời gian làm việc Thứ 2 - Thứ 6: 9h00 - 18h00\nThứ 7 làm cách tuần (Tuần làm - Tuần nghỉ): 9h00 -17h00\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2978, 1339, 2, 'Lập Trình Viên C++ FullStack (3+ Năm Kinh Nghiệm)', 'Mô tả công việc:\n- Tham gia phát triển và duy trì hệ thống phần mềm sử dụng ngôn ngữ C++, theo mô hình Full Stack.\n- Quản lý phân chia công việc cho các thành viên trong team\n- Thiết kế, xây dựng và tối ưu hóa cơ sở dữ liệu với Entity Framework.\n- Kết hợp phát triển ứng dụng giao diện Flutter khi cần thiết (mobile hoặc desktop).\n- Áp dụng Design Pattern vào kiến trúc phần mềm để đảm bảo hệ thống ổn định, dễ bảo trì.\n- Phối hợp với team QA, UI/UX để triển khai tính năng mới và sửa lỗi.\n- Viết tài liệu kỹ thuật cho sản phẩm.\n\nYêu cầu ứng viên:\n- Có từ 3–5 năm kinh nghiệm làm việc với C++ Full Stack.\n- Thành thạo Entity Framework, có khả năng thiết kế và tối ưu hệ thống cơ sở dữ liệu.\n- Có hiểu biết hoặc đã từng làm việc với Flutter là một lợi thế lớn.\n- Nắm vững các Design Pattern phổ biến (MVC, Singleton, Observer, Factory...).\n- Có kỹ năng phân tích yêu cầu, tư duy logic tốt, có tinh thần học hỏi và cầu tiến.\n- Ưu tiên ứng viên có khả năng làm việc độc lập và tinh thần teamwork tốt.\n\nQuyền lợi:\n- Mức lương cạnh tranh: từ 14.000.000 đến 20.000.000 VNĐ/tháng, tùy theo năng lực và kinh nghiệm.\n- Xét tăng lương định kỳ và thưởng theo hiệu suất công việc.\n- Cơ hội tham gia vào các dự án lớn, quy mô thực tế với khách hàng trong và ngoài nước.\n- Làm việc trong môi trường công nghệ chuyên nghiệp, năng động, hỗ trợ phát triển cá nhân.\n- Tham gia BHXH, BHYT đầy đủ, cùng các chế độ phúc lợi khác (teambuilding, nghỉ lễ, quà sinh nhật).\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 331 Trần Xuân Soạn, Phường Tân Kiểng, Quận 7\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2979, 1117, 2, 'Senior Backend Developer (NestJS / FastAPI)', 'Mô tả công việc:\n- Thiết kế kiến trúc hệ thống backend, đảm bảo hiệu năng và khả năng mở rộng\n- Lãnh đạo kỹ thuật, định hướng công nghệ trong team backend\n- Xây dựng và duy trì API sử dụng NestJS và FastAPI\n- Review code, mentor các thành viên junior/intern.\n- Thiết lập các tiêu chuẩn kỹ thuật: coding convention, CI/CD, testing.\n- Tối ưu hoá hệ thống, đảm bảo tính bảo mật, khả năng chịu tải cao.\n- Phối hợp với team DevOps để triển khai, giám sát và vận hành hệ thống.\n\nYêu cầu ứng viên:\n- Kinh nghiệm sâu rộng với NestJS và FastAPI\n- Từng thiết kế hoặc vận hành hệ thống lớn hoặc microservices\n- Thành thạo mô hình thiết kế phần mềm (OOP, SOLID, Clean Architecture, DDD)\n- Kinh nghiệm CI/CD, Docker, git workflow\n- Thành thạo các kỹ thuật tối ưu DB (PostgreSQL/MongoDB)\n- Hiểu biết về bảo mật hệ thống (SQL Injection, XSS, CSRF...)\n- Kỹ năng leadership: mentor, review code, ra quyết định kỹ thuật\n- Biết sử dụng Celery, RabbitMQ, hoặc Redis Queue cho các tác vụ bất đồng bộ.\n\nƯu tiên:\n- Có kinh nghiệm với hệ thống đa tenant, realtime, event-driven.\n- Thành thạo Kubernetes, hệ thống giám sát Prometheus/Grafana.\n- Kinh nghiệm xử lý hàng triệu request mỗi ngày là điểm cộng lớn.\n\nQuyền lợi:\nPhúc lợi:\n- Thưởng các ngày lễ: Sinh nhật, Hiếu hỉ, Trung thu, 30/4, 8/3, 20/10, 2/9... tuỳ tình hình kinh doanh công ty\n- Teambuilding, Tết tây, Tết ta,... Tuỳ hình hình kinh doanh\n- Tăng lương định kỳ tháng 4 hằng năm.\n\nPhụ cấp khác:\n- Các chế độ bảo hiểm đầy đủ theo quy định pháp luật\n- Cung cấp thiết bị nơi làm việc\n- Ngày nghỉ: 12 ngày /năm \n\nĐịa điểm làm việc:\n- Thừa Thiên Huế: Tầng 6, số 2 Lê Quý Đôn, Tòa nhà Vietinbank, Phú Hội, Huế., TP Huế\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2980, 165, 2, '.NET Developer (Product Team)', '- Đóng góp vào việc phát triển sản phẩm KiotViet KAT; - Làm việc với các thành viên team và phòng ban khác trong việc triển khai yêu cầu nghiệp vụ; - Phát triển và bảo trì các tính năng back-end và front-end cho hệ thống nhiều người dùng; - Debug và fix các vấn đề kỹ thuật trong codebase hiện có; - Tham gia vào việc tối ưu hóa code để cải thiện performance hệ thống; - Hỗ trợ triển khai công nghệ và giải pháp mới vào sản phẩm; - Viết code clean, dễ bảo trì theo tiêu chuẩn của team; - Tham gia vào các hoạt động testing và quality assurance; - Viết documentation cho code và quy trình phát triển. 1. Học vấn và kinh nghiệm - Tốt nghiệp đại học chuyên ngành CNTT hoặc các ngành liên quan; - Từ 3 năm kinh nghiệm phát triển phần mềm với công nghệ .NET. 2. Yêu cầu kỹ thuật - Có kiến thức làm việc với C#, .NET Core, ASP.NET / ASP.NET Core; - Kinh nghiệm với các ORM như Entity Framework hoặc Dapper; - Hiểu biết về khái niệm và triển khai RESTful API; - Kinh nghiệm làm việc với database SQL (MS SQL, PostgreSQL): - Viết query cơ bản - Hiểu biết về thiết kế database schema - Tối ưu hóa performance cơ bản - Làm quen với hệ thống message queue (RabbitMQ, Kafka) - Kiến thức cơ bản về cơ chế caching (Redis) - Hiểu biết về coding best practices và design patterns; - Kinh nghiệm với unit testing và công cụ debugging; - Kiến thức cơ bản về công cụ monitoring và logging; - Quen thuộc với hệ thống version control (Git) - Có kinh nghiệm sử dụng AI coding tools và assistants (Cursor, GitHub Copilot, Claude, v.v.) để nâng cao hiệu suất trong phát triển phần mềm là một lợi thế. 3. Kỹ năng mềm - Tư duy logic và khả năng giải quyết vấn đề; - Mong muốn học hỏi công nghệ và concepts mới; - Kỹ năng giao tiếp tốt; - Khả năng làm việc hiệu quả trong môi trường team; - Kỹ năng quản lý thời gian và tổ chức; - Có khả năng tiếp thu tốt. - Mức lương khởi điểm đứng đầu thị trường, tương xứng với năng lực và kinh nghiệm làm việc; - Thưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm; - Làm việc từ Thứ 2 – Thứ 6, giờ làm việc linh hoạt; - Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...); - Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm; - Chăm sóc sức khỏe: Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp dành cho Level 3-3 trở lên theo quy định của công ty; - Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi; - Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại; - Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2981, 209, 2, 'Senior Workato Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\n\nJOB OVERVIEW\n• We are looking for a Senior Workato Developer to design, build, and maintain enterprise-grade automation and integration workflows using the Workato platform. The ideal candidate will have hands-on experience in automating complex business processes, connecting APIs, and developing reusable components to scale automation across departments and systems.\n\nRESPONSIBILITIES\n• Design and develop robust integrations and automation using Workato recipes, connectors, and Workato SDK.\n• Collaborate with business analysts and stakeholders to translate requirements into scalable solutions.\n• Create custom connectors and adapters using Workato SDK when required.\n• Monitor, maintain, and optimize integrations for performance, error handling, and scalability.\n• Integrate systems such as Salesforce, NetSuite, SAP, Workday, ServiceNow, Slack, Microsoft 365, databases, and custom APIs.\n• Implement Workato best practices, governance models, and reusable components (lookup tables, recipes, environments).\n• Maintain documentation, recipes version control, and change management processes.\n• Provide mentorship and support to junior automation developers and ensure code quality.\n\nYêu cầu ứng viên\n• Bachelor’s degree in Computer Science, Engineering, Information Systems, or related field.\n• 5+ years of experience in integration development, with at least 2+ years on Workato.\n\nStrong expertise with:\n• Workato Recipes, Triggers, Actions, Lookup Tables, and Formula mode\n• Workato SDK for creating custom connectors (Node.js, HTTP, JSON, etc.)\n• REST/SOAP APIs and webhooks\n• OAuth2, JWT, and other authentication methods\n• Experience with scripting languages (JavaScript, Python) to support advanced logic.\n• Familiarity with relational databases (SQL), file systems (CSV/XML/JSON), and cloud storage.\n• Proficient in API testing tools (Postman, Swagger, etc.).\n• Understanding of common business applications: ERP, CRM, HRIS, ITSM, etc.\n• Strong debugging, logging, and error-handling practices.\n• Workato certifications (e.g., Workato Automation Pro II/III, Workato Integration Specialist).\n• Experience with other iPaaS platforms (MuleSoft, Boomi, Zapier, Tray.io) is a plus.\n• Experience in industries like healthcare, insurance, finance, or e-commerce with domain-specific integration challenges.\n• Understanding of secure data practices, PII protection, HIPAA or GDPR compliance (as applicable).\n• Familiarity with CI/CD pipelines, Git, and Agile delivery methodologies.\n\nQuyền lợi\n• Attractive salary. Performance based award.\n• Go onsite in Singapore.\n• FPT Care insurance plan tailored for FPT employees\n• Attractive annual summer vacation allowance\n• Sponsored training courses for personal growth and up to 100% coverage for certification costs\n• Global and inclusive workplace with monthly cross-cultural events\n• International exposure and career growth across global locations\n• Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\n\nĐịa điểm làm việc\n- Hà Nội: FPT Building, 17 Duy Tân Str., Cầu Giấy District, Hanoi, Cầu Giấy\n- Nước Ngoài\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm \'Ứng tuyển\' ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Nước Ngoài', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2982, 1456, 2, 'Frontend Developer', 'Mô tả công việc:\n- Phối hợp với các team UI/UX, PO, Backend dev,...để triển khai các tính năng trên sản phẩm đảm bảo yêu cầu về chất lượng, tiến độ của các dự án theo các tiêu chuẩn thiết kế, tiêu chuẩn mã nguồn, bảo mật và hiệu năng cao cho hệ thống.\n- Xây dựng và triển khai hệ thống website builder - dạng kéo thả\n- Email builder (hỗ trợ hiển thị tốt trên Outlook)\n- Landing Page builder\n- Popup builder\n- Contact form\n- Thực hiện Unit Test. Hỗ trợ kiểm thử SIT/UAT, sửa lỗi và nghiệm thu chức năng.\n- Cập nhật và áp dụng các công nghệ mới nhằm cải thiện chất lượng sản phẩm.\n\nYêu cầu ứng viên:\n- Có ít nhất 2 năm kinh nghiệm làm việc với Angular, Typescript, HTML5, CSS3, RxJS, và các kỹ thuật xử lý bất đồng bộ.\n- Pixel Perfect: Xử lý chi tiết trong việc chuyển từ Figma qua HTML, CSS.\n- Hiểu rõ về kiến trúc Single Page Applications, RESTful API.\n- Có kinh nghiệm xử lý HTML/CSS template email hiển thị trên Outlook\n- Có kinh nghiệm làm việc với các sản phẩm Builder (dạng kéo, thả) là một lợi thế\n- Có kỹ năng phân tích, giải quyết vấn đề, tối ưu hóa, chủ động và luôn tìm hiểu trước khi đặt vấn đề\n- Sử dụng thành thạo các IDE phát triển và công cụ quản lý mã nguồn (Git)\n- Có hiểu biết về Backbone JS là một lợi thế\n- Hiểu biết và có kinh nghiệm thực tế với DevOps, CI/CD là một lợi thế\n- Có hiểu biết, kinh nghiệm về SAFe 6.0 là một lợi thế\n- Có mindset UI/UX tốt là một lợi thế.\n\nQuyền lợi:\n- Phúc lợi tài chính minh bạch và xứng đáng:\n- Mức lương: 15M - 25M\n- Thử việc 100% lương chính thức\n- Package 13 tháng lương cố định/năm\n- Lộ trình đánh giá năng lực và điều chỉnh thu nhập 1 – 2 lần/năm (tuỳ cấp độ nhân viên).\n- Trải nghiệm sự trân trọng và săn sóc đặc biệt qua các chế độ phúc lợi độc đáo:\n- Chính sách đào tạo lên tới 20 triệu/năm\n- Chế độ chăm sóc sức khỏe: Bảo hiểm sức khỏe hàng năm cho Nhân viên và người thân; khám sức khỏe định kỳ 1 lần/năm.\n- Chế độ thai sản đặc biệt: 20 triệu/1 Nhân viên nữ sinh con.\n- 12 ngày phép/năm, nhân viên làm việc từ năm thứ 5 trở lên mỗi 5 năm được tăng thêm 01 ngày phép.\n- Mỗi nhân viên sẽ được nghỉ hưởng nguyên lương 0,5 ngày vào ngày sinh nhật của mình.\n- Chính sách CLB thể thao (bóng đá, cầu lông, bơi lội, chạy bộ...): 3 triệu/1 CLB/tháng.\n- Quỹ hoạt động giao lưu, gắn kết Team định kỳ hàng quý.\n- Chế độ thăm hỏi ốm đau, hiếu, hỉ, quà mừng con CBNV chào đời.\n- Cung cấp đầy đủ trang thiết bị làm việc.\n\nThời gian làm việc:\n- Từ Thứ 2 đến Thứ 6 hàng tuần và 1 ngày thứ 7 đầu tháng\n- Thời gian trong ngày: 9h00 - 18h00\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa HL, số 6 ngõ 82 Duy Tân, Dịch Vọng Hậu, Cầu Giấy, Cầu Giấy.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2983, 1372, 2, 'Kỹ Sư ME (Tiếng Trung)', 'Mô tả công việc:\n- Vận hành, bảo dưỡng, gỡ lỗi máy móc\n- Đưa ra các phương án cải tiến chất lượng sản phẩm\n- Các dòng máy trong công ty :\n+ Máy CNC: FANUC, OUKELANG\n+ Máy đột dập AOTU\n+ Máy PVD, máy làm sạch hydrocacbon, mạ và xử lý bề mặt kim loại\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng trở lên\n- Kinh nghiệm 2 năm trở lên trong lĩnh vực gia công kim loại\n- Giao tiếp tiếng Trung\n\nQuyền lợi:\n- Công ty mới thành lập, tuyển cán bộ nguồn, có nhiều cơ hội phát triển\n- Mức lương thỏa thuận, ĐẢM BẢO HẤP DẪN theo năng lực, ưu tiên ứng viên có thể đi làm sớm\n- Hưởng đầy đủ các chính sách phúc lợi theo quyền lợi nhân sự chính thức: BHYT, BHXH, nghỉ phép năm và các thưởng khác nếu có\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nỨng viên có thể tăng ca hoặc làm ca đêm.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh, KCN Yên Phong 2C, Yên Phong', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2984, 1293, 2, 'Mobile Developer', 'Mô tả công việc:\n1. Phát triển sản phẩm: Sử dụng React Native để phát triển và cải tiến sản phẩm của công ty.\n2. Phát triển và bảo trì ứng dụng: Thiết kế, xây dựng các tính năng mới và bảo trì, tối ưu các tính năng hiện có cho ứng dụng trên nền tảng di động (iOS và Android).\n3. Nghiên cứu và ứng dụng công nghệ: Tìm hiểu, nghiên cứu và áp dụng các công nghệ mã nguồn mở vào dự án nhằm nâng cao hiệu quả và tính linh hoạt của sản phẩm.\n4. Quy trình phát triển phần mềm: Tham gia vào các công đoạn phân tích yêu cầu, thiết kế chi tiết (Detail Design), coding và viết tài liệu kỹ thuật.\n5. Hợp tác nhóm: Làm việc chặt chẽ với các thành viên trong nhóm và các phòng ban liên quan để đảm bảo chất lượng và tiến độ của dự án.\n\nYêu cầu ứng viên:\n- Kỹ năng cần có:\n+ Kinh nghiệm: Có kinh nghiệm phát triển ứng dụng di động với React Native; ưu tiên ứng viên có kinh nghiệm trên cả iOS và Android.\n+ Kỹ năng lập trình: Thành thạo JavaScript, ES6+ và hiểu biết vững về React Native.\n+ Kiến thức API: Nắm vững kiến thức về RESTful API và các kỹ thuật tích hợp backend.\n+ Kỹ năng phân tích: Có khả năng phân tích yêu cầu, giải quyết vấn đề và tối ưu hóa hiệu năng ứng dụng.\n+ Tinh thần học hỏi: Luôn chủ động cập nhật các công nghệ mới và sẵn sàng thử nghiệm các giải pháp sáng tạo.\n+ Kỹ năng giao tiếp: Có khả năng làm việc nhóm tốt và giao tiếp hiệu quả với các bộ phận liên quan.\n- Kỹ năng ưu tiên:\n+ Có kinh nghiệm làm Product phần mềm quản lý nội bộ doanh nghiệp, thương mại điện tử, CRM.\n+ Ưu tiên ứng viên thích làm product, tư duy làm sản phẩm cao, hướng tới người dùng cuối.\n+ Ưu tiên ứng viên có trình độ tiếng Anh tốt.\n\nQuyền lợi:\n- Thu nhập hấp dẫn: Upto 25 Triệu KPI.\n- Được cung cấp đầy đủ trang thiết bị làm việc hiện đại.\n- Đóng BHXH, BHYT theo Quy định của Nhà nước.\n- Lộ trình thăng tiến rõ ràng và sếp luôn quan tâm nâng cao năng lực chuyên môn.\n- Được tham gia các khóa đào tạo nâng cao năng lực cá nhân, khóa kỹ năng mềm.\n- Được hưởng chính sách phúc lợi theo Quy định của Công ty: thưởng lễ, Tết, du lịch định kỳ, Thưởng.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 69 Tố Hữu, Vạn Phúc, Hà Đông.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n- Thứ 7 (từ 08:00 đến 12:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2985, 1254, 2, 'Java Developer', 'Mô tả công việc\nTham gia phát triển các hệ thống phần mềm, gồm: \n- Phân tích yêu cầu khách hàng và xây dựng tài liệu giải pháp.\n- Tham gia phát triển và sửa lỗi các tính năng.\n- Đóng góp vào các hoạt động chia sẻ tri thức và cải tiến liên tục.\nYêu cầu ứng viên\n- Có từ 3 năm kinh nghiệm trở lên lập trình với Java.\n- Hiểu biết và có kinh nghiệm làm việc với một trong số nền tảng Java Core, EE, Spring, Struts, Hibernate\n- Yêu cầu có kinh nghiệm về Microservices.\n- Ưu tiên có kinh nghiệm tham gia các dự án tích hợp AWS, Cloud.\n- Có kinh nghiệm làm việc với SQL, PLSQL, có kiến thức về một trong các hệ quản trị cơ sở dữ liệu Oracle/MySQL.\n- Tiếng anh giao tiếp tốt.\n- Kỹ năng giao tiếp, giải quyết vấn đề, kỹ năng làm việc nhóm tốt, luôn sẵn sàng hỗ trợ các thành viên khác trong dự án.\n- Chịu được áp lực cao trong công việc, có khả năng làm việc độc lập, chủ động giải quyết vấn đề để hoàn thành nhiệm vụ.\n- Cam kết, ham học hỏi.\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực.\n- Thưởng cuối năm (1-3 tháng lương).\n- Nghỉ phép hàng năm, ngày phép thâm niên, ngày phép tháng sinh nhật.\n- Đánh giá năng suất và xét tăng lương 1 lần/ năm.\n- Tài trợ 100% phí thi các chứng chỉ quốc tế; phụ cấp chứng chỉ chuyên môn.\n- Khám sức khoẻ định kỳ, BHXH, nghỉ lễ theo qui định.\n- Tham gia vào nhóm phát triển Scrum tự chủ, linh hoạt và năng suất cao theo mô hình Agile/Scrum.\n- Môi trường làm việc trẻ, năng động, vui vẻ, hạnh phúc với các hoạt động văn hóa sôi động như retreat, picnic, team building, happy event, BiPlus radio, ...\n- Được làm nhiều, được thử nhiều và được sai, học thực chiến trong công việc.\n- Liên tục phát triển năng lực thông qua các hoạt động học tập (company learning hour, team learning hour, club), đào tạo, mentoring, coaching,... Được phản hồi thường xuyên liên tục và huấn luyện để phát triển năng lực và đạt hiệu suất công việc ngày càng cao (CFRs- Conversation - Feedback - Recognition tháng và 6 tháng).\nĐịa điểm làm việc\n- Hà Nội: Số 85 - Trần Thái Tông, Cầu Giấy\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2986, 1234, 2, 'Trưởng Nhóm Development (Mobile)', 'Quản lý nhóm phát triển ứng dụng di động, đảm bảo tiến độ, chất lượng dự án và đóng góp vào chiến lược công nghệ của công ty.\nNHIỆM VỤ CHÍNH:\nPhân công, giám sát công việc và hỗ trợ đội ngũ phát triển.\nThiết kế, xây dựng và tối ưu ứng dụng di động (iOS, Android).\nĐảm bảo chất lượng code và trải nghiệm người dùng.\nBáo cáo tiến độ và phối hợp với các bộ phận liên quan.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học chuyên ngành CNTT, Khoa học Máy tính, hoặc tương đương.\nTối thiểu 3 năm kinh nghiệm phát triển ứng dụng di động và 1-2 năm ở vai trò quản lý nhóm.\nThành thạo lập trình native (Swift/Objective-C, Kotlin/Java) và/hoặc cross-platform (React Native, Flutter).\nHiểu biết sâu về API RESTful, giao tiếp dữ liệu và cơ sở dữ liệu (SQLite, Realm, Firebase).\nKỹ năng code review, quản lý dự án và sử dụng các công cụ như Git, Jira.\nƯu tiên biết sử dụng Lark và thành thạo các công cụ AI để tối ưu và nâng cao hiệu suất công việc.\nKỹ năng lãnh đạo và giải quyết vấn đề tốt.\n\nQuyền lợi:\nMức lương: Thỏa thuận theo năng lực (Upto 40tr/th)\nLàm việc trong môi trường chuyên nghiệp, năng động và thân thiện, phát triển với tốc độ rất cao, cơ hội thăng tiến cao, Chế độ đãi ngộ rất tốt, thu nhập với lương thưởng hấp dẫn. Môi trường trẻ năng động.\nĐược hưởng đầy đủ các chế độ theo Luật Lao động Việt Nam (BHXH, BHYT…)\nCác chế độ phúc lợi khác: Thưởng các ngày lễ Tết, sinh nhật, cưới xin,...Tham quan, nghỉ mát. Thưởng tết tháng thứ 13,…\nCông ty cung cấp điện thoại bàn, máy tính, hỗ trợ phí gửi xe tại tòa nhà.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Mipec 229 Tây Sơn, Đống Đa\n\nThời gian làm việc:\nTừ Thứ 2 đến Thứ 6: 08:00 đến 17:00\nThứ 7: 08:00 đến 12:00\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2987, 1319, 2, 'Kỹ Sư Lập Trình Hệ Thống', 'Mô tả công việc:\n- Tham gia nghiên cứu và phát triển các sản phẩm, giải pháp công nghệ trong lĩnh vực An ninh – Quốc phòng, đặc biệt liên quan đến hệ thống điều khiển, giám sát, và truyền dẫn tín hiệu.\n- Nghiên cứu và phát triển các giải pháp truyền tải video real-time, phục vụ các các giải pháp thông tin liên lạc, giám sát hoặc hỗ trợ tác chiến.\n- Tham gia nghiên cứu, cập nhật xu hướng công nghệ mới và đề xuất ứng dụng thực tiễn vào sản phẩm của công ty.\n- Tham gia triển khai và tích hợp các hệ thống CNTT phục vụ cho hoạt động vận hành của công ty, và trong hệ thống sản phẩm/giải pháp của công ty.\n\nYêu cầu ứng viên:\n- Thành thạo một hoặc nhiều ngôn ngữ backend: Python (FastAPI, Flask), Golang, hoặc Node.js.\n- Có kinh nghiệm với các công nghệ truyền video real-time: FFmpeg, GStreamer, WebRTC, RTSP, HLS, DASH...\n- Hiểu và từng làm việc với các giao thức truyền tải video: UDP multicast, TCP streaming, RTP/RTSP, WebSocket.\n- Thành thạo môi trường Linux-based, có kinh nghiệm vận hành ứng dụng với Docker/container, theo dõi và tối ưu tài nguyên hệ thống.\n- Có kinh nghiệm với cơ sở dữ liệu: PostgreSQL, Redis, TimescaleDB, hoặc tương đương.\n\nƯu tiên:\n- Từng làm việc với hệ thống encoder/decoder, camera IP, media gateway, hoặc giải pháp nén/tối ưu hóa truyền dẫn video.\n- Có kinh nghiệm phân tích hiệu năng hệ thống, xử lý đa luồng, tối ưu độ trễ thấp (low-latency) và quản lý dữ liệu thời gian thực.\n- Tư duy hệ thống tốt, có khả năng phối hợp chặt chẽ với các nhóm nhúng, AI, frontend và thiết bị.\n\nQuyền lợi:\n- Mức lương cạnh tranh, thưởng theo dự án và năng lực.\n- Công ty đóng 100% BHXH ngay khi ký HĐLĐ chính thức.\n- Cơ hội làm việc trong lĩnh vực công nghệ cao phục vụ Quốc phòng – An ninh.\n- Tham gia các khóa đào tạo chuyên môn sâu (nhúng, FPGA, truyền dẫn…).\n- Cơ hội phát triển thành trưởng nhóm kỹ thuật theo lộ trình.\n- Tham gia các khóa Đào tạo trong và ngoài nước nâng cao nghiệp vụ chuyên môn.\n- Thưởng tháng 13, 14 thưởng các ngày lễ, tết,…\n- Phụ cấp ăn trưa 40.000 VNĐ/ngày.\n- Khám sức khỏe định kỳ, teambuiding, du lịch, các sự kiện nội bộ.…\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Zodiac, ngõ 19 Duy Tân, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2988, 1378, 2, 'Lead Mobile App', 'Mô tả công việc:\n- Lead the development of high-quality, impactful, and scalable products and systems to achieve business goals.\n- Collaborate closely with engineering managers and engineers across multiple platforms and domains.\n- Support to recruit, develop, and retain exceptional engineering talent who excel in innovative, user-focused, fast-paced environments.\n- Establish and maintain high engineering standards for your team regarding quality practices, delivery speed, architecture, design, and code quality, with clear measurable goals.\n- Contribute to the improvement and scaling of the engineering organization by mentoring engineers, sharing technical knowledge, industry best practices, and leadership skills.\n\nTech stacks:\n1. Requirement for Android :\n- Kotlin, Java programming languages\n- MVVM architecture pattern\n- Coroutines for asynchronous programming\n- HTTP client implementation\n- Compose UI framework\n- Unit testing and UI testing\n- Google Play Store policy compliance\n2. Requirement for iOS :\n- Swift programming language\n- MVVM architecture pattern\n- HTTP client implementation\n- SwiftUI framework\n- Unit testing and UI testing\n- Apple App Store policy compliance\n\nYêu cầu ứng viên:\n- Bachelor\'s degree or higher in Computer Science or related field.\n- Familiarity with mobile frameworks.\n- Familiarity with Swift/Objective-C; Kotlin/Java.\n- Familiarity with version control tools (e.g., Git)\n- Good understanding of web standards and best practice.\n- Has team collaboration awareness, able to work cooperatively with team members. Experience in Scrum is a plus.\n- Good communication skills and logical thinking/judgment abilities.\n- Proactive and self-motivated to learn.\n- Possesses or is willing to learn multiple languages (including Chinese, English, Vietnamese) to effectively communicate with the team.\n\nQuyền lợi:\n- 13-month of salary\n- Full social benefits in accordance with the company and the Vietnam Law\n- Premium health care & accident insurance\n- Friendly working environment with strong startup culture\n- Team building, Company trip, Year-end party, etc.\n- 40 flexible working hours per week from Monday to Friday\n- Salary review at least one time per year based on employee\'s performance and contribution\n\nOther detailed:\n- Department Dinner: 720,000 VND/person/Q\n- Year-end party: 2,000,000 VND/person\n- Health Check: According to the hospital\'s pricing each year\n- Mid-Autumn Festival Gift Box: Together with the union\n- Staff Travel: Maximum VND 6,400,000 per person\n- Company Group Insurance: Company Insurance\n\nĐịa điểm làm việc:\n- Hồ Chí Minh\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2989, 1432, 2, 'Lập Trình Viên', '1. Thiết kế giải pháp\n- Làm việc với các phòng ban để thiết kế giải pháp phần mềm nhằm giảm khối lượng công việc, tăng hiệu quả hoạt động.\n- Áp dụng công nghệ mới và framework mới vào thiết kế giải pháp để tạo ra giải pháp tốt và linh hoạt để thích ứng với các thay đổi kinh doanh.\n\n2. Phát triển phần mềm\n- Phát triển ứng dụng phần mềm để phù hợp với yêu cầu hoạt động và hướng dẫn của cấp trên.\n- Cập nhật tất cả các vấn đề, lỗi, tính năng mới, yêu cầu cải tiến vào hệ thống bàn dịch vụ, cập nhật nhật ký công việc hàng ngày, đẩy mã nguồn vào phần mềm JIRA.\n- Tìm nguyên nhân gốc và khắc phục, trình lên cấp trên nếu không thể giải quyết hoặc khắc phục trong SLA.\n- Giám sát danh sách nhiệm vụ và hoàn thành trong thời gian cam kết\n- Hợp tác với team quản lý dự án, team vận hành để làm bài kiểm tra và UAT cho ứng dụng.\n- Thực hiện, đào tạo cho người dùng cuối.\n\n3. Các công việc khác theo sự phân công từ cấp trên\n\nYêu cầu ứng viên\n- Tốt nghiệp Cao đẳng/ Đại học với chuyên ngành CNTT, viễn thông, khoa học máy tính hoặc các ngành nghề khác có liên quan\n- Ít nhất 1 năm kinh nghiệm tại vị trí tương tự\n- Tiếng Anh trình độ trung cấp\n\nQuyền lợi\n- Lương cạnh tranh + phụ cấp xăng xe\n- Bảo hiểm xã hội & bảo hiểm tai nạn lao động 8/24\n- Lương tháng 13 hàng năm\n- Du lịch hàng năm, teambuilding, khám sức khỏe\n- Môi trường làm việc chuyên nghiệp với nhiều cơ hội đào tạo & phát triển\n\nĐịa điểm làm việc\n- Hà Nội: Xuân Thủy, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2990, 1450, 2, 'Frontend Developer (ReactJS + Blockchain)', 'Mô tả công việc\n- Deploy web apps with modern technologies (JavaScript/HTML5/CSS3, etc.) and frameworks (ReactJS)\n- Enhance the performance of existing products\n- Build architecture and design new features, new products\n- Research new technologies to apply in current and future projects\n- Perform security and performance analysis\n\nYêu cầu ứng viên\nMust have:\n- Have experience working in the Blockchain with Ethereum JS library (Ethers.js, Web3.js), ...\n- Understanding and working with REST API\n- Able to work with a team as well as independently.\n- Have the spirit and responsibility with the assigned work.\n- Be proactive in work to ensure deadlines as well as product quality.\n- Have good English skills (reading skills are required)\n\nNice to have:\n- Good background knowledge: algorithms, problem solving, OOP, design pattern\n\nQuyền lợi\nDevelopment opportunities:\n- Working in an environment with talented engineers who have experience in developing products in the field of Fintech, Blockchain, Cryptocurrencies.\n- Take a key role in building the project from the very beginning;\n- Technical and professional training throughout the working process.\n\nRemuneration:\n- Earn up to $2000, 13th-month bonus, performance bonus according to the company\'s business situation.\n- Flexible working hours: 9:00-18:30 Monday-Friday, 1h30-minute lunch break\n- Labor contract and all benefits prescribed by the state (pay social insurance, health insurance, unemployment insurance);\n- 16 days leave, 4 days sick leave with full salary;\n- PVI Healthcare Insurance;\n- Annual health check at a reputable hospital;\n- Equipment for work;\n- Daily lunch, happy hour every Thursday, and monthly team outing;\n- Chillax office with gym, swimming pool, free snacks & drink all day;\n- Travel - vacation at least once a year at domestic and international 5-star resorts.\n\nĐịa điểm làm việc\n- Hà Nội: Vinhomes West Point, Pham Hung Street, Me Tri Ward, Nam Tu Liem, Ha Noi, Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2991, 1212, 2, 'Chief Technology Officer ( Ứng Dụng SAAS)', 'Mô tả công việc\nTechnology Leadership\n● Build and implement a long-term technology vision aligned with business strategy\n● Develop a detailed technical roadmap with specific measurable milestones\n● Evaluate and recommend emerging technologies suitable for the US market\n● Represent the company at technology events and build technical credibility in the industry\nProduct Development & Engineering\n● Design scalable architecture for CRM and AI platforms that meet US market requirements\n● Implement end-to-end development workflow (CI/CD, automated testing, monitoring)\n● Direct product deployment strategy, ensuring technical quality and meeting user needs\n● Optimize system performance, ensuring scalability and readiness for growth\n● Develop and deploy enterprise-grade solutions (CRM, AI, data pipelines)\nTeam Development\n● Build and scale the engineering team from 2 to 10+ people\n● Establish engineering culture and operational excellence\n● Recruit and mentor high-potential engineers\n● Create an innovation-driven and continuous learning environment\nBudget & Resource Management\n● Effectively manage technology budgets, ensuring investment in priority areas\n● Efficiently allocate resources between parallel projects and ensure return on investment (ROI)\n● Evaluate and select technology partners, vendors, and external solutions\n● Develop strategic partnerships with leading technology companies\n\nYêu cầu ứng viên\nTechnical Expertise\n● Age: 35-50\n● Minimum 4+ years in senior management (CTO, VP Engineering)\n● US Market Experience: Experience implementing SaaS in the US market (requirement)\n● Tech Stack Proficiency: Angular, Java, AWS, Microservices architecture\n● AI/ML Experience: Experience deploying production-grade AI/ML solutions with real-world data\n● CRM Knowledge: Experience with enterprise CRM systems (Salesforce, Hubspot)\n● Cloud Expertise: Advanced AWS architecture and optimization practices\n● Technical Breadth: Experience with web/mobile, backend systems, data pipelines\n● Real-time Systems: Experience with real-time/near real-time systems (advantage)\nBudget & Resource Management\n● Experience managing technology budgets of $200,000+\n● Ability to optimize operational costs on AWS and cloud services\n● Experience efficiently allocating resources across multiple parallel projects\n● Ability to build business cases and ROI calculations for technology investments\n● Knowledge of procurement processes and negotiation with software/hardware vendors\nLeadership Competencies\n● Ability to communicate complex technical vision and lead teams to execute\n● Excellent technical team management skills, experience building and leading teams of 10+ people\n● Ability to balance long-term technical goals with short-term business needs\n● Strategic thinking and data-driven decision making\n● Experience working in startup/high-growth environments is an advantage\nQualifications\n● Bachelor\'s degree or higher in Computer Science, Software Engineering or related fields\n● MBA or management certifications are a plus\n● Fluent in English (listening, speaking, reading, writing)\n● Experience working with US clients/partners\n● Excellent communication skills, ability to present complex ideas to diverse audiences\n● Strong time management, organizational, and problem-solving skills\nOthers:\n● Still passionate about coding\n● Developed Saas application on Amazon Web Service platform & launched to the market. (Priority given to candidates who have worked in CRM, Marketing domain)\n● Developed AI for Saas application.\n● Recruited and managed a team of >10 people.\nManagement responsibility/ Trách nhiệm báo cáo:\n- Make daily reports/weekly/monthly.\n- Perform periodic and irregular work reports at the request of the direct management and the Board of Directors.\nRelationships/ Mối Quan hệ:\nInternal: Closely associated with departments in the Company.\nExternal: Ability to build and develop good relationships.\nProblems/Giải quyết vấn đề:\n- Directly deal with arising arising in the assigned work.\n- Report and ask for timely direction of the direct management or The Board of Directors in case of arising is beyond the ability and authority to make personal decisions.\nAuthority/Quyền hạn:\n- Working time: 5 days/week (Monday to Friday)\n- Compulsory Insurances full salary (Social Insurance, Health Insurance, Unemployment Insurance) based on the Labor Code.\n- Performance bonuses: Quarterly and annual bonuses based on KPIs\n- Comprehensive insurance: Premium health insurance package for you and your family\n- Company Team Building Trip every year.\n- Professional and dynamic working environment.\nInterview Process\n- Round 1: Preliminary interview with HR (30 minutes)\n- Round 2: Technical discussion with CEO and senior leadership (1-2 hours)\n- Round 3: Vision and technology strategy presentation with CEO and senior leadership\nAccountability/Trách nhiệm khác:\n- Sense of responsibility and ability to withstand high pressure at work.\n- Good moral character.\n- Honesty, work in compliance with good discipline.\n- Professional working attitude.\n- Make efforts to learn more new knowledge.\n\nQuyền lợi\nWorking conditions/Điều kiện làm việc:\n- A dynamic, professional, friendly working environment with many opportunities for learning and advancement.\n- Receive training to improve qualifications according to the requirements of the job position.\nPerformance indicators/Đánh giá & nhận xét:\nEvaluation of the working process as well as work efficiency will be considered on a yearly basis.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 56 đường số 6, phường Bình Trưng Tây, Thủ Đức\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 07:30 đến 16:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2992, 1193, 2, 'Web Developer', 'Mô tả công việc:\n- Develop and maintain Web apps using Java Spring Boot.\n- Work directly with remote team to clarify tasks and requirements.\n- Develop new features based on the user requirements (analyzing requirements and system design).\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance.\n- Managing time and resources based on the WBS.\n- Write high-quality, clean, elegant, maintainable, and testable code.\n- Maintaining technical documents up-to-date.\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the Kiwoom Framework for Kiwoom Indonesia, Finansia(in Thailand), and so on.\n\nYêu cầu ứng viên:\nEducation & Technical skills:\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- At least 3 years of relevant experience in Java development, Spring Framework and SQL.\n- Experience and knowledge in markup language, including HTML, CSS.\n- Experience with frontend JavaScript.\n\nSoft Skills & Communication:\n- Able to communicate in English, written and spoken.\n- Strong problem-solving and analytical skills.\n- Strong communication skills and teamwork, international experience is preferred.\n\nNice to have:\n- Understand of API design and implementation.\n- Ability to write clean, easy to understand code.\n- Familiarity with version control systems, such as Git or SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nQuyền lợi:\nIncome & Achievement:\n- Competitive salary, salary review once a year\n- 13th month salary and Annual Performance Bonus\n- MVP and Shining star awards at the end of year\n- Global and professional working environment\n\nWorkplace Happiness:\n- Full SHUI as Vietnamese Law\n- Premium Private Medical Insurance PVI and annual health check\n- 15-day annual leave\n- 01-day Christmas off and 90-min menstrual leave for women\n- Company trip, YEP and monthly gathering time\n- Gifts on special occasion and fully stocked snack corner\n- Sponsored training courses and book purchase quarterly\n- Be well-equipped with new working equipment\n\nSPECIAL OFFER:\n- Providing training and education experience in Korea with Korean Finance/IT expert\n- Providing opportunities to work and support in IT/Finance fields overseas\n\nHIRING PROCESS:\nThe interview will be conducted at our office in Ho Chi Minh city.\nRound 1:\n- Step 1: Live coding test\n- Step 2: Interview with part team leader (upon passing coding test)\n- Step 3: Interview with Director\nRound 2: Final interview with Head Office in Korea.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tầng 14, tòa nhà AP, 518B Điện Biên Phủ, Phường 21, Bình Thạnh.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2993, 756, 2, 'Chương Trình Tuyển Dụng Và Đào Tạo Fresher Android Developer', 'Apero TechTrek là chương trình đào tạo Kỹ sư phần mềm Android dành cho các bạn sinh viên tài năng trong ngành công nghệ thông tin. Chương trình được thiết kế với các module đào tạo kiến thức chuyên ngành từ cơ bản đến chuyên sâu; kỹ năng ứng dụng kiến thức vào vận hành dự án thực tế. Trong chương trình, học viên sẽ được đào tạo dưới sự hướng dẫn và cố vấn trực tiếp bởi các Trưởng phòng và các chuyên gia Phát triển Phần mềm tại Apero Technologies Group. - Đào tạo có lương, được hưởng các cơ chế đãi ngộ như nhân sự Apero. - Review tăng lương sau khi kết thúc khóa đào tạo (6 tháng) - Được hướng dẫn trực tiếp bởi các Trưởng phòng và các chuyên gia Phát triển sản phẩm dày dạn kinh nghiệm phát triển hệ sinh thái các sản phẩm với hơn 500M lượt tải và hơn 100M người dùng hàng tháng. - Có cơ hội trở thành nhân viên chính thức sau 1 tháng đào tạo tập trung và tham gia thực chiến trực tiếp vào các Global Project. - Tham gia dự án thực tế quy mô lớn, Với hàm lượng công nghệ cao, giúp nâng cao kỹ năng chuyên môn, tư duy sáng tạo, và làm quen với quy trình phát triển phần mềm chuyên nghiệp. MÔ TẢ CÔNG VIỆC Trở thành Fresher Android Developer sau 6 tháng đào tạo với lộ trình sau GIA NHẬP APERO: Tổng quát: Hòa nhập với môi trường Apero và những kiến thức cơ bản về android ĐÀO TẠO TẬP TRUNG ( Trong 1 tháng) - Nắm vững ngôn ngữ lập trình Kotlin - Nắm vững cách thiết kế giao diện trong Jetpack Compose - Nắm vững quy trình quản lý phiên bản và quản lý dự án với Git/Github - Ứng dụng AI trong lập trình - Tạo ra một ứng dụng hoàn chỉnh TRẢI NGHIỆM DỰ ÁN THỰC TẾ (5 tháng tiếp theo, các bạn sẽ được làm:) - Tạo ra các thành phần giao diện phức tạp - Ứng dụng một số Design Pattern quan trọng- Ứng dụng mô hình kiến trúc MVI Architecture - Thúc đẩy kỹ năng làm việc nhóm - Ứng dụng AI Agent nâng cao, giúp làm việc và học hỏi hiệu quả - Được phát triển các dự án thực tế, mang lại doanh thu cho công ty. YÊU CẦU ỨNG VIÊN - Sinh viên năm cuối hoặc đã tốt nghiệp Đại học dưới 1 năm, chuyên ngành về Công nghệ Thông tin. - Có thể làm toàn thời gian. - Sở hữu kiến thức nền tảng công nghệ vững thể hiện qua kết quả học tập, giải thưởng, dự án thực tế... - Khả năng tự học và chủ động cao trong công việc. QUYỀN LỢI ỨNG VIÊN - Đào tạo có lương, được hưởng các cơ chế đãi ngộ như nhân sự Apero. - Review tăng lương sau khi kết thúc khóa đào tạo (6 tháng). - Được hướng dẫn trực tiếp bởi các Trưởng phòng và các chuyên gia Phát triển sản phẩm dày dạn kinh nghiệm phát triển hệ sinh thái các sản phẩm với hơn 500M lượt tải và hơn 100M người dùng hàng tháng. - Có cơ hội trở thành nhân viên chính thức sau 1 tháng đào tạo tập trung và tham gia thực chiến trực tiếp vào các Global Project. - Tham gia dự án thực tế quy mô lớn, Với hàm lượng công nghệ cao, giúp nâng cao kỹ năng chuyên môn, tư duy sáng tạo, và làm quen với quy trình phát triển phần mềm chuyên nghiệp. Địa điểm làm việc: - Hà Nội: Tòa Taisei Square, 289 Khuất Duy Tiến, Cầu Giấy, Cầu Giấy. Thời gian làm việc: 8:30 - 18:00, nghỉ trưa 1h30’, làm việc từ Thứ 2 - Thứ 6. Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2994, 1138, 2, 'Kỹ Thuật Viên Vận Hành Máy CNC Thu Nhập 8.000.000 - 13.000.000', 'Vận hành máy CNC phục vụ sản xuất các sản phẩm nội thất gỗ theo kế hoạch.\nLập trình, cài đặt và điều chỉnh thông số máy CNC theo yêu cầu bản vẽ kỹ thuật.\nKiểm tra và giám sát chất lượng sản phẩm sau khi gia công, đảm bảo đúng tiêu chuẩn.\nThực hiện bảo trì, bảo dưỡng máy móc định kỳ để đảm bảo hoạt động ổn định.\nPhối hợp với bộ phận thiết kế/kỹ thuật nhằm tối ưu hóa quy trình sản xuất.\nTuân thủ nghiêm ngặt các quy định về an toàn lao động trong quá trình làm việc.\n\nYêu cầu ứng viên:\nCó kinh nghiệm làm việc trong lĩnh vực cơ khí, cơ điện tử, hoặc ngành chế biến gỗ.\nTối thiểu 1 năm kinh nghiệm vận hành máy CNC trong sản xuất công nghiệp.\nĐọc hiểu bản vẽ kỹ thuật cơ bản (2D, 3D).\nHiểu biết về vật liệu gỗ, các dòng máy CNC và công nghệ gia công gỗ.\nCó tinh thần trách nhiệm, kỹ luật cao và khả năng làm việc nhóm tốt.\n\nQuyền lợi:\nMức lương:  8-13tr, Thỏa thuận theo năng lực và kinh nghiệm.\nĐược tham gia đầy đủ BHXH, BHYT, BHTN theo quy định pháp luật.\nThưởng lễ, Tết, và các chế độ phúc lợi khác theo quy định công ty.\nĐược đào tạo nâng cao tay nghề và cập nhật công nghệ mới.\nMôi trường làm việc chuyên nghiệp, thân thiện, cơ hội phát triển rõ ràng.\n\nĐịa điểm làm việc:\nĐịa điểm làm việc tại nhà máy: CN11 - KCN Nguyên Khê, Đông Anh\nPhỏng vấn tại nhà máy hoặc văn phòng: số 4 Dịch Vọng Hậu- Cầu GIấy - HN.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2995, 1263, 2, 'Thực Tập Sinh Lập Trình SAP Front-End', 'Mô tả công việc:\n- Lập trình Front-end cho các hệ thống SAP ERP – hệ thống quản trị nguồn lực doanh nghiệp\n- Tích hợp các hệ thống thông tin, hệ thống phần mềm trong các doanh nghiệp, công ty lớn.\n\nYêu cầu ứng viên:\n- Là sinh viên năm cuối Đại học đang đi thực tập hoặc sắp ra trường.\n- Có kinh nghiệm ít nhất một trong các ngôn ngữ lập trình Front-end như: Javascript, Typescript…\n- Có kinh nghiệm ít nhất 1 Framework như: React.js, Vue.js, Angular…\n- Có tư duy lập trình tốt, nhất là tư duy lập trình Front-end.\n- Có tinh thần ham học hỏi, cầu tiến, chăm chỉ, có trách nhiệm với công việc mình làm.\n- Có khả năng học hỏi công nghệ, ngôn ngữ lập trình mới.\n\nQuyền lợi:\n1. Chế độ đãi ngộ:\n- Có hỗ trợ phụ cấp thực tập đối với thực tập sinh.\n- Sau thực tập được review và ký Hợp đồng chính thức với công ty.\n- Phụ cấp onsite, phụ cấp tăng ca, thưởng dự án, thưởng vượt chỉ tiêu, thưởng tháng lương thứ 13, thưởng lợi nhuận kinh doanh,...\n- Được hưởng các quyền lợi theo Luật Lao động, Nội quy và Quy chế Công ty: tham gia BHXH, BHYT, BHTN theo quy định, phụ cấp thai sản, cưới hỏi, sinh nhật...\n- Định kỳ xét tăng lương và review chuyên môn.\n- Được hỗ trợ các thiết bị, công cụ cần thiết cho thực hiện công việc.\n- Trợ cấp chứng chỉ liên quan đến vị trí công việc.\n\n2. Cơ hội phát triển bản thân:\n- Làm việc với đội ngũ kỹ sư, nhân viên năng động.\n- Được lắng nghe, tôn trọng ý kiến, quan điểm cá nhân để trao đổi thẳng thắn, chia sẻ cùng phát triển.\n- Được lãnh đạo giàu kinh nghiệm đào tạo và định hướng con đường nghề nghiệp rõ ràng.\n- Được cử tham gia các khóa đào tạo mới, đào tạo nâng cao phù hợp với năng lực và nguyện vọng.\n- Được ghi nhận những đóng góp, nỗ lực kịp thời, chính xác.\n- Được tham gia học hoặc thi các chứng chỉ liên quan với chế độ hỗ trợ về chính sách từ Công ty.\n\n3. Đời sống tinh thần:\n- Môi trường làm việc chuyên nghiệp, thân thiện, cởi mở.\n- Tham gia các hoạt động về trau dồi ngôn ngữ (tiếng Anh).\n- Tham gia các cuộc thi nội bộ của Công ty về văn hóa theo quý.\n- Các thành viên trong công ty gần gũi, gắn bó, quan tâm, giúp đỡ nhau cùng phát triển.\n- Được tham gia các hoạt động teambuilding theo tháng, quý, du lịch hàng năm.\n- Công ty luôn động viên và tạo điều kiện tốt nhất cho toàn thể nhân viên.\n- Công ty tổ chức các buổi sinh nhật cho nhân viên hàng tháng, tổ chức thưởng và kỉ niệm những ngày lễ tết trong năm.\n- Hoạt động văn hóa thể thao đa dạng: câu lạc bộ bóng đá, ....\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 1, Tòa nhà HL, số 6/82 đường Duy Tân, phường Dịch Vọng Hậu, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2996, 209, 2, 'Java Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n• Develop, and implement scalable and efficient Backend solutions using Java and Spring Boot.\n• Collaborate with cross-functional teams to understand project requirements and translate them into Backend functionalities.\n• Optimize code, integrate design patterns, and ensure high performance, reliability, and security of Backend systems.\n• Work with relational databases, write efficient SQL queries, and maintain data models.\n• Implement RESTful APIs with authentication, error handling, and versioning.\n• Perform unit testing, code reviews, and maintain code quality.\n• Collaborate with Frontend developers to integrate Frontend components with Backend services.\n• Debug and resolve issues reported by users or identified through testing and monitoring.\n• Stay updated with emerging technologies and industry trends in Backend development.\n• Support system integration according to the data interface specification,\n• Support SIT, UAT, non-functional test, etc.\n• Prepare technical related materials for the architecture, security, service transition and PCQA\n• Performing requirement analyses.\n• Developing high-quality and detailed designs.\n• Conducting unit testing using automated unit test frameworks.\n• Identifying risk and conducting mitigation action planning.\n• Conducting configuration of your own work.\n• Reviewing the work of other developers and providing feedback.\n• Using coding standards and best practices to ensure quality.\n\nYêu cầu ứng viên\n• Strong experience in Backend development using Java and Spring Boot 7 years +\n• Proficiency in Hibernate or other ORM frameworks.\n• Familiarity with relational databases, writing efficient SQL queries, and optimizing database performance.\n• Knowledge of RESTful API design principles and advance.\n• Familiarity with unit testing, code reviews, and DevOps tools (e.g.: Git, Jenkins, Artifactory, SonarQube, Kubernetes and cluster management / administration etc.).\n• Excellent teamwork and communication skills to manage the team.\n• Problem-solving abilities and attention to detail.\n• Experience with cloud platforms and containerization technologies (AWS, Azure and Private Cloud).\n• API Gateways – AWS, Azure, APIGEE.\n• Familiarity with Agile development methodologies is preferred.\n• Develop and test the solution according to the system design and integration\n• Support SIT, UAT, integration test, non-functional test, etc.\n• Backend technical skills including Java, Springboot, Hibernate, SQL DB, Swagger, Light4J\n• Infrastructure orchestration and initialization scripts to automate creation of complex virtual environments\n\nQuyền lợi\n• FPT Care insurance plan tailored for FPT employees\n• Relocation Policy up to 100 Million VND for the candidate who is willing to relocate to Nha Trang City.\n• Attractive annual summer vacation allowance\n• Sponsored training courses for personal growth and up to 100% coverage for certification costs\n• Global and inclusive workplace with monthly cross-cultural events\n• International exposure and career growth across global locations\n• Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\n\nĐịa điểm làm việc\n- Khánh Hoà: VCN Tower, Số 2 Đường Tố Hữu, Khu đô thị Phước Hải, Thành phố Nha Trang, TP Nha Trang\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khánh Hoà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2997, 1160, 2, 'Backend Developer', 'We are seeking a skilled Backend Developer to join our team and contribute to the development of an exciting new project. You will work on building robust and scalable backend systems using Node.js, MySQL, and Prisma, while also supporting the monitoring and maintenance of our game infrastructure. This role requires a solid understanding of backend development and basic DevOps practices to ensure smooth deployment and operation of our services.\n\nDesign, develop, and maintain backend services for a new platform using Node.js, MySQL, and Prisma.\nImplement APIs and integrate with frontend systems to deliver seamless user experiences.\nBuild and maintain a secure API gateway to facilitate communication between game clients and servers, ensuring protection against hack/cheat attempts.\nCollaborate with the team to integrate WebSocket-based communication for real-time features.\nMonitor and maintain game infrastructure, including servers running Node.js, Nginx, Redis, Grafana, and Docker.\nAssist with basic DevOps tasks, such as configuring load balancers (Nginx), caching systems (Redis), and monitoring tools (Grafana).\nEnsure system scalability, security, and performance through best practices in development and deployment.\nTroubleshoot and resolve issues related to backend services and infrastructure.\n\nRequirements\n\nProven experience in backend development with Node.js and Express.js.\nStrong knowledge of MySQL for designing and managing relational databases.\nHands-on experience with Prisma as an ORM for efficient database operations.\nFamiliarity with WebSocket for real-time communication between clients and servers.\nBasic understanding of DevOps practices, including:\n           + Configuring and managing Nginx as a load balancer.\n           + Using Redis for caching to optimize performance and prevent client-side cheating.\n           + Monitoring infrastructure with Grafana.\n           + Deploying and managing applications using Docker.\nExperience with API development and securing communication channels to prevent unauthorized access.\nUnderstanding of game backend logic to mitigate hack/cheat vulnerabilities.\nAbility to work with deeplinks and user authentication via headers or URL parameters.\nStrong problem-solving skills and attention to detail.\nExcellent communication and collaboration skills to work with cross-functional teams.\n\nPreferred Qualifications\n\nExperience with game development or supporting game server infrastructure.\nFamiliarity with microservices architecture and API gateway implementation.\nKnowledge of security best practices for protecting sensitive user data.\nPrior experience working with cloud-based or on-premise server infrastructure.\n\nQuyền lợi\n\nWork on exciting game-related projects with opportunities to contribute to both development and infrastructure.\nCollaborate in a dynamic environment with opportunities for growth and learning.\nCompetitive salary and benefits package.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2998, 1128, 2, 'C++ Developer (Junior)', 'Mô tả công việc:\n- Tham gia vào phát triển các dự án với vai trò junior hoặc middle từ giai đoạn Basic Design, Detail Design, Development, Release.\n- Thiết kế kiến trúc tổng thể hệ thống, Database, phát triển các chức năng đồng thời support các thành viên trong team.\n- Tham gia vs PM lập kế hoạch và hỗ trợ quản lý dự án.\n- Làm các công việc khác theo sự phân công của quản lý( Research new Technologies, Support team…)\n\nYêu cầu ứng viên:\n- Có kinh nghiệm làm việc với C++ trong các dự án phát triển phần mềm. Ưu tiên có kinh nghiệm với Visual C++ (VC++).\n- Có kiến thức nền tảng tốt về OOP, Web Development, DBMS, ORM, Design Pattern.\n- Có kiến thức nền tảng tốt OOP và các nguyên tắc thiết kế phần mềm, Design Pattern.\n- Kỹ năng đọc hiểu và phân tích tài liệu kỹ thuật tốt, đặc biệt là các tài liệu liên quan đến hệ thống phần mềm.\n- Kỹ năng giao tiếp và làm việc nhóm tốt, có khả năng phối hợp với các bộ phận khác.\n  Ưu tiên:\n- Biết tiếng nhật hoặc đã từng làm trong các công ty outsourcing cho Nhật.\n- Tư duy logic tốt.\nYêu cầu khác:\n- Có tinh thần trách nhiệm cao trong công việc;\n- Có khả năng làm việc độc lập và làm việc theo nhóm;\n- Có khả năng sử dụng tiếng Anh/tiếng Nhật là lợi thế.\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Lương làm thêm giờ theo luật lao động, hỗ trợ đồ ăn OT theo quy định công ty;\n- Làm việc từ thứ 2 - thứ 6 (8h30 - 17h30);\n- Được tham gia BHXH, BHYT, BHTN theo quy định của pháp luật hiện hành;\n- Bảo hiểm chăm sóc sức khỏe cao cấp 24/24;\n- Khám sức khỏe định kỳ 1 năm/1 lần tại bệnh viện Đại học Y Hà Nội;\n- Nghỉ ốm hưởng nguyên lương tối đa 30 ngày/ năm (có giấy chứng nhận của bệnh viện);\n- Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ngày;\n- Nghỉ sinh lý phụ nữ theo luật lao động hiện hành.\n- Miễn phí đồ uống tại khu ăn uống của công ty;\n- Trợ cấp tiếng Nhật và các chứng chỉ IT liên quan;\n- Phụ cấp thâm niên; phụ cấp chức vụ;\n- Được tham gia các câu lạc bộ của công ty: CLB Bóng đá, CLB Game, CLB Beauty, CLB Dance...\n- Được tham gia các hoạt động tập thể sôi động của công ty: nghỉ mát hàng năm, teambuilding hàng quý, gala cuối năm….\n- Tham gia các khóa học nâng cao trình độ chuyên môn qua Portal đào tạo nội bộ hoặc các khóa học trực tiếp với các giảng viên uy tín.\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật.\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(2999, 1174, 2, 'Nhân Viên Vận Hành Máy CNC', 'Mô tả công việc\n- Vận hành máy phay CNC: Đọc bản vẽ, chuẩn bị dụng cụ cắt, căn chỉnh máy, lập trình…\n- Kiểm tra và ghi chép kết quả đo vào biểu đo (bản vẽ).\n- Tổng kết số lượng thành phẩm.\n- Vệ sinh khu vực làm việc.\n- Các công việc khác có liên quan.\n\nYêu cầu ứng viên\n- Tốt nghiệp Trung cấp/ Cao đẳng cơ khí.\n- Có kinh nghiệm vận hành máy CNC (Phay), lập trình 2D, 3D.\n- Ưu tiên biết sử dụng phần mềm Cimatrol\n- Ưu tiên có kinh nghiệm tại các công ty sản xuất, cơ khí.\n- Có tinh thần trách nhiệm cao, cẩn thận và tỉ mỉ trong công việc.\n- Khả năng giải quyết vấn đề và tư duy logic tốt.\n\nQuyền lợi\n- Mức lương đàm phán theo kinh nghiệm, trình độ.\n- Phụ cấp 1.000.000 VNĐ/ tháng.\n- Thưởng chuyên cần 500.000 VNĐ.\n- Trợ cấp chuyên môn sau 6 tháng làm việc.\n- Review tăng lương 1 lần/năm.\n- Cấp phát đồng phục khi làm việc chính thức tại Công ty.\n- Hỗ trợ cơm trưa, bữa phụ đầy đủ.\n- Chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật định.\n- Thưởng các ngày lễ, tết theo quy định của công ty.\n- Cơ hội được đào tạo và nâng cao nghiệp vụ.\n- Cơ hội thăng tiến và phát triển nghề nghiệp.\n- Môi trường làm việc an toàn, thoải mái.\n\nĐịa điểm làm việc\n- Hà Nội: Việt Hùng, Đông Anh.\n\nThời gian làm việc\n- Thứ 2 - Thứ 7\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3000, 1239, 2, 'Chief Developer/Software Architect–ERP Software', 'Mô tả công việc: - Explore, Define, and review technical solutions (.JavaEE, Hibernate/JPA, JSF, PrimeFaces, Postgresql database) - Present and discuss technical solutions with directors - Working in a team of Chief Developers to support modification development for junior Devs - Support the team to create a proposal for a new scope of projects/modies - Communicate directly with 3rd vendor supporter - Support the team to handle production technical issues: debugging, performance, workload, security... - Explore, research, propose, and implement new technology.\n\nYêu cầu ứng viên: - Proven experience in a Chief Dev or leadership role, preferably within an IT company, especially the ERP product. - Ability to analyze complex technical issues and provide innovative solutions. - Strong background in system design, architecture, and development. - Knowledge of the latest technology trends and best practices in the IT industry. - Strong problem-solving skills and a proactive approach to addressing challenges. - Excellent communication and interpersonal skills, with fluency in English. - Integrity and passion for code quality and improvement, passion for sharing knowledge to build a quality Developer team. - Ability to maintain a high level of confidentiality and manage the security risk.\n\nQuyền lợi: - Salary: Negotiate - Monthly salary 13+14 - To be paid insurance according to the provisions of labor law (social insurance, health insurance, unemployment insurance) - Health insurance and medical checking package for manager level - Increase salary 2 times/ year - To celebrate birthday, participate in teambuilding activities, annual travel - Holidays and New Year holidays as prescribed by law - Company holidays, including: 14 days off, 10 days off sick, 01 Christmas day, 0.5 international women\'s day, 0.5 Vietnamese women\'s day... - Fruits every Thursday and free cake, tea, coffee,...\n\nĐịa điểm làm việc: - Hà Nội: Tầng 25, tháp C, tòa nhà Central Point số 219 Phố Trung Kính, Phường Yên Hòa, Cầu Giấy.\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3001, 1295, 2, 'Chuyên Gia Phát Triển Ứng Dụng Ngân Hàng Số (.NET)', 'Mô tả công việc\n- Tham gia việc phân tích, đánh giá các yêu cầu nghiệp vụ ngân hàng trên các kênh ngân hàng điện tử, ngân hàng số dành cho KHCN và KHDN, Branch Teller.\n- Tham gia phát triển, cải tiến và duy trì các ứng dụng kênh ngân hàng điện tử, ngân hàng số dành cho KHCN và KHDN, Branch Teller.\n- Đảm bảo tích hợp liền mạch giữa các ứng dụng kênh ngân hàng điện tử, ngân hàng số và các hệ thống công nghệ hiện có của ngân hàng.\n- Tham gia phối hợp hỗ trợ các đơn vị vận hành giám sát hoạt động và khắc phục các vấn đề phát sinh của các hệ thống trên kênh số khi có yêu cầu bao gồm: Internet Banking, Mobile Banking.\n- Tham gia hỗ trợ level 2 cho các sản phẩm, dịch vụ trên kênh số nhằm phục vụ khách hàng nội bộ (CallCenter, Card Center, Chi nhánh/Phòng giao dịch) và khách hàng bên ngoài thông qua các kênh như Service Desk, email, điện thoại,...\n- Tham gia các dự án số hóa của Ngân hàng và khối CNTT.\n- Theo dõi xu hướng và phát triển trong lĩnh vực ngân hàng điện tử, ngân hàng số, đề xuất các phương án cải tiến và áp dụng các giải pháp sáng tạo để nâng cao trải nghiệm khách hàng.\n- Thực hiện các nhiệm vụ khác theo phân công của cấp quản lý.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học trở lên các chuyên ngành phù hợp như CNTT/Điện tử viễn thông hoặc các chuyên ngành có liên quan đến CNTT.\n- Tối thiểu 3 năm kinh nghiệm trong lĩnh vực phát triển ứng dụng ngân hàng số, tài chính số hoặc các lĩnh vực liên quan (lập trình Java/ .NET, J2EE/Web service/JMS, Oracle Database, My SQL, Postgre SQL).\n- Có kinh nghiệm về tích hợp hệ thống qua ESB (Enterprise Service Bus) sử dụng EIP (Enterprise Integration Patterns).\n- Có kinh nghiệm về microservices, CI/CD.\n- Có kinh nghiệm về các công cụ giám sát như ELK, Splunk, Prometheus, Grafana.\n- Sử dụng thành thạo các IDE phát triển và các tool quản lý source code, quản lý công việc. (CI/CD: Jenkin, GIT, ANT);\n- Nắm vững các design pattern thông dụng, các kiến thức về cấu trúc dữ liệu và giải thuật, lập trình hướng đối tượng,...\n- Đã từng làm việc trong lĩnh vực ngân hàng, có kiến thức về nghiệp vụ và hệ thống thông tin ngân hàng là lợi thế.\n- Kỹ năng Tiếng Anh đọc hiểu tài liệu kỹ thuật.\n\nƯu tiên các ứng viên:\n- Ham học hỏi tìm tòi sáng tạo cái mới.\n- Có hiểu biết về nghiệp vụ tài chính ngân hàng.\n- Đã từng triển khai sản phẩm lên AWS, Azuse.\n- Có kinh nghiệm làm việc theo mô hình Agile/ Scrum/ Waterfall.\n\nQuyền lợi\n- Chế độ phúc lợi\n- Lương và phụ cấp\nLương nhân viên PG Bank được áp dụng từ việc khảo sát mức lương thực tế của ngành và thị trường. Khung lương được xây dựng cho 9 cấp/ bậc của công việc, dải lương rộng cho phép thu hút được những ứng viên tiềm năng và đảm bảo trả mức lương cạnh tranh cao cho mọi vị trí. Ngoài chế độ lương cạnh tranh, nhân viên PG Bank còn được hưởng rất nhiều chế độ phụ cấp khác theo đặc thù công việc như phụ cấp điện thoại, phụ cấp ăn trưa, phụ cấp đi lại ... , chế độ tham quan nghỉ mát hàng năm, tặng quà cho CBNV nhân dịp sinh nhật, thăm hỏi ốm đau, kết hôn, hỗ trợ thai sản.\n- Chế độ khen thưởng: PG Bank có chế độ đãi ngộ nhân viên xứng đáng với năng lực và đóng góp của từng cá nhân. Về cơ bản, PG Bank có chế độ thưởng như sau:\n+ Thưởng theo kết quả kinh doanh.\n+ Thưởng hoàn thành công việc.\n+ Thưởng cho tập thể, cá nhân tiêu biểu trong năm.\n+ Thưởng đột xuất cho tập thể, cá nhân hoàn thành xuất sắc nhiệm vụ, có sáng kiến, đóng góp có giá trị cho Ngân hàng, thưởng do hoàn thành vượt mức kế hoạch được giao.\n+ Thưởng cho toàn bộ CBNV ngân hàng trong các dịp lễ tết.\n- Chế độ bảo hiểm:\nTất cả nhân viên chính thức của PG Bank đều được tham gia Bảo hiểm xã hội, Bảo hiểm y tế và bảo hiểm thất nghiệp theo đúng quy định của Luật lao động hiện hành. Ngoài ra, tất cả nhân viên chính thức của PG Bank đều được mua thêm bảo hiểm Pijico, một gói bảo hiểm rất ưu việt giúp thanh toán các chi phí y tế như tiền thuốc, tiền viện phí... khi khám chữa bệnh tại các bệnh viện tốt nhất tại địa phương.\n- Đào tạo và phát triển nguồn nhân lực\nCông tác đào tạo và phát triển nguồn nhân lực luôn được chú trọng và phát triển tại PG Bank. Với mục tiêu xây dựng nguồn nhân lực có năng lực và tính chuyên nghiệp cao đáp ứng chiến lược phát triển nhanh và bền vững của Ngân hàng, chuẩn bị nhân sự kế nhiệm cấp điều hành cho Ngân hàng, PG Bank thường xuyên tổ chức cho nhân viên tham dự các khóa đào tạo trong và ngoài nước, các khóa đào tạo của NHNN, Hiệp hội ngân hàng, các tổ chức đào tạo có uy tín khác nhằm nâng cao trình độ chuyên môn, nâng cao kỹ năng làm việc hiệu quả và các kỹ năng quản lý, lãnh đạo trong từng giai đoạn, vị trí công tác.\n- Cơ hội thăng tiến\nTại PG Bank, nhân viên được làm việc trong môi trường cạnh tranh lành mạnh, rất nhiều cơ hội phát triển, thăng tiến đang chờ đón các bạn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3002, 1254, 2, 'Trợ Lý Điều Hành Phát Triển Phần Mềm', 'Mô tả công việc:\n- Theo dõi, cập nhật, tổng hợp và chịu trách nhiệm về số liệu sản xuất của toàn công ty, quản lý các dashboard thuộc phạm vi trách nhiệm của mình.\n- Điều phối việc lên kế hoạch sản xuất theo Sprint cho toàn công ty và đảm bảo điều kiện sản xuất cho các team.\n- Rà soát, đối soát và chịu trách nhiệm chốt số liệu nghiệm thu với khách hàng và ký kết các biên bản nghiệm thu.\n- Theo dõi, đôn đốc các nhóm sản xuất thực hiện đúng các lịch bàn giao cho khách hàng, cảnh báo các bộ phận liên quan nếu phát hiện trở ngại, rủi ro hoặc các thay đổi có thể gây ảnh hưởng đến cam kết với khách hàng.\n- Phân tích, báo cáo các dữ liệu về hiệu quả sản xuất (năng suất, sản lượng, lãi lỗ…), cảnh báo và đề xuất biện pháp nâng cao hiệu quả sản xuất, chủ trì thảo luận và triển khai các giải pháp cải tiến với các bên liên quan.\n- Sắp xếp, quản lý các lịch họp của các nhóm trong toàn công ty.\n- Tuân thủ các quy tắc và quy định an toàn thông tin, chịu trách nhiệm đảm bảo an toàn đối với các dữ liệu, thông tin được giao phụ trách.\n- Các công việc khác theo sự phân công của team lead.\nYêu cầu ứng viên:\n- Tốt nghiệp đại học trở lên các chuyên ngành về Công nghệ thông tin hoặc Kinh tế, Quản trị kinh doanh, Ngoại thương, Luật.\n- Có kinh nghiệm làm việc trong ngành Công nghệ thông tin là lợi thế.\n- Kiến thức nền tảng về quản lý sản xuất.\n- Tổng hợp và phân tích số liệu.\n- Kỹ năng giao tiếp tốt.\n- Tư duy phản biện (critical thinking) và tư duy hệ thống (system thinking).\n- Có khả năng đa nhiệm, làm nhiều đầu việc, giao tiếp với nhiều đầu mối cùng lúc.\n- Có khả năng chịu được áp lực cao, có kỹ năng xử lý tình huống tốt.\n- Tiếng Anh nghe nói đọc viết.\n- Ưu tiên ứng viên đã từng làm việc theo mô hình Scrum.\nQuyền lợi:\n- Mức lương thỏa thuận theo năng lực.\n- Thưởng quý, thưởng cuối năm (1-3 tháng lương).\n- Ngày phép hàng năm, ngày phép thâm niên, ngày phép tháng sinh nhật.\n- Đánh giá năng suất và xét tăng lương 1 lần/năm.\n- Tài trợ 100% phí thi các chứng chỉ quốc tế; phụ cấp chứng chỉ chuyên môn.\n- Được đào tạo, huấn luyện để có thể làm tốt công việc.\n- Khám sức khỏe định kỳ; BHXH, nghỉ lễ theo quy định.\n- Tham gia vào các dự án hiệu năng cao, số lượng dữ liệu lớn và tập khách hàng lớn. Được làm việc trên các hệ thống lớn với các bài toán công nghệ phức tạp.\n- Tham gia vào nhóm phát triển Scrum tự chủ, linh hoạt và năng suất cao theo mô hình Agile/Scrum.\n- Môi trường làm việc trẻ, năng động, vui vẻ, hạnh phúc với các hoạt động văn hóa sôi động như retreat, picnic, team building, happy event, BiPlus radio, …\n- Được làm nhiều, được thử nhiều và được sai, học thực chiến trong công việc.\n- Liên tục phát triển năng lực thông qua các hoạt động học tập (company learning hour, team learning hour, club), đào tạo, mentoring, coaching,…\n- Được phản hồi thường xuyên liên tục và huấn luyện để phát triển năng lực và đạt hiệu suất công việc ngày càng cao (CFRs- Conversation – Feedback – Recognition tháng và 6 tháng).\nĐịa điểm làm việc:\n- Hà Nội: Tòa nhà Bảo Anh - Số 85 - Trần Thái Tông, Cầu Giấy.\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3003, 1115, 2, 'Backend Developer', 'Mô tả công việc\n- Build high-performance, scalable backend components using Golang.\n- Design, implement, and optimize database solutions with PostgreSQL, ensuring data integrity and high performance.\n- Develop and maintain GraphQL APIs to support data-driven applications.\n- Deploy and manage containerized applications using Kubernetes, ensuring stability and high availability.\n- Set up and maintain CI/CD pipelines to automate testing, deployment, and integration processes.\n- Collaborate with cross-functional teams to define, design, and develop new features.\n- Participate in code reviews to maintain code quality and share knowledge within the team.\n\nYêu cầu ứng viên\n- Require 2-3 years of experience in Golang\n- Strong proficiency in Golang with experience in building scalable server-side applications.\n- Proficiency in PostgreSQL, including writing complex queries, optimizing performance, and database design.\n- Hands-on experience with Kubernetes for deploying and managing containerized applications.\n- Experience developing and maintaining GraphQL APIs.\n- Familiarity with CI/CD tools and practices.\n- Familiarity with version control systems such as Git.\n- Understanding of microservices architecture and RESTful API design.\n- Experience with cloud platforms like AWS, Google Cloud, or Azure is a plus.\n- Excellent problem-solving skills and a proactive attitude.\n- Strong communication skills and the ability to work effectively in a collaborative environment.\n\nQuyền lợi\n- Competitive salary upto 25,000,000 VND. 100% salary during probation\n- Reference bonus, End year bonus,...\n- Daily lunch support\n- Friendly and open working environment\n- IELTS/ TOEIC Certificate Support.\n- Team-building activities: 1-2 company trips/year\n- Career development opportunities\n- Tea-break\n\nĐịa điểm làm việc\n- Hà Nội: Số 9 Duy Tân, Dịch Vọng Hậu, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3004, 1405, 2, 'Nhân Viên Lập Trình CNC (Gỗ)', 'Mô tả công việc:\n- Bóc tách bản vẽ 3D sang 2D và lập trình máy CNC\n- Thiết lập Quy trình SX và B.O.M \n- Lập tiêu chuẩn SX cho các công đoạn SX ( file cad ), theo dõi và cập nhật khi có thay đổi\n- Báo cáo (mẫu, PP, tuần)\n- Lập các hướng dẫn làm việc cho các công đoạn\n- Các công việc liên quan khác do quản lý giao\n\nYêu cầu ứng viên:\n- Kinh nghiệm từ 2 năm trở lên\n- Thành thạo phần mềm autocad 2D, 3D\n- Biết sử dụng các công cụ Microsoft ( Excel, Word, Outlook..) để thực hiện các yêu cầu về báo cáo, lập kế hoạch\n- Tăng ca theo yêu cầu công việc\n- Ý thức kỷ luật, trách nhiệm.\n\nQuyền lợi:\n- Mức lương tùy năng lực: 11.000.000 -13.000.000 đồng/tháng, chưa bao gồm tăng ca.\n- Thử việc: 02 tháng\n- Thời gian làm việc: 8h00 – 17h00 (Nghỉ Chủ Nhật hàng tuần)\n- Làm việc tại Nhà máy Bình Dương: số 3/35 Đường Bình Chuẩn 34, KP. Bình Phước B, P. Bình Chuẩn, Thuận An, Bình Dương\n- Cơ hội làm việc môi trường năng động và Đào tạo, học hỏi, nâng cao kiến thức chuyên môn\n- Thưởng các dịp lễ/tết (Tết Dương lịch, 30/4, 2/9); Thưởng cuối năm, thưởng tết Nguyên đán,..\n- Đóng BHXH đầy đủ, du lịch hàng năm, khám sức khỏe định kỳ, các chế độ thăm hỏi, phép năm ,phúc lợi khác,..', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3005, 1449, 2, 'Lập Trình Viên Từ N3 (Visa Nhanh)', 'Mô tả công việc\nPhát triển ứng dụng kinh doanh cho các ngành khác nhau như tài chính, truyền thông, sản xuất, phân phối, chăm sóc y tế và vận tải\nPhát triển các phần mềm ứng dụng nội bộ\nLập trình trong các dự án gia công phần mềm cho khách hàng Nhật Bản sử dụng ngôn ngữ chính là Java hoặc C#...\nTham gia các giai đoạn phát triển phần mềm khác tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu công nghệ khi được phân công\n\nYêu cầu ứng viên\nTrình độ tiếng Nhật: N3, giao tiếp tốt, có thể làm việc trực tiếp với khách hàng\nCó trên một năm kinh nghiệm trong ngành lập trình\nThông thạo một số ngôn ngữ lập trình như C#, Java, Javascript, PLSQL\nCó thể ở Nhật trên ba năm, có khả năng chịu được áp lực\nTuyển thẳng sang Nhật làm sau khi làm thủ tục xin visa\n\nQuyền lợi\nThời gian làm việc: 08:45-17:30, nghỉ 60 phút(Làm bảy tiếng 45 phút)\nTăng ca trung bình 11 tiếng/tháng\nTổng ngày nghỉ 123 ngày/năm\nNghỉ thứ bảy, chủ nhật, các ngày nghỉ lễ của Nhật\nMức lương: 400-600 Vạn yên/năm\nTrợ cấp chức vụ 14,000-70,000 yên\nTrợ cấp chủ hộ gia đình 8,000-100,000 yên\nTrợ cấp nếu có người phụ thuộc 20,000 yên\nTrợ cấp con nhỏ 1 con 10,000 yên; 2 con 15,000 yên\nTrợ cấp độc thân phải nuôi dưỡng ông bà, bố mẹ 7,000 yên\nHỗ trợ vé máy bay sang Nhật\nHỗ trợ làm thủ tục xin visa\nCấp cho nhân viên máy tính, Mirosoft365 để có thể làm ở nhà\nCác chế độ bảo hiểm theo quy định của luật lao động Nhật Bản\n\nĐịa điểm làm việc\nNước Ngoài\nHà Nội: Đống Đa\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nước Ngoài, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3006, 1425, 2, 'Fullstack Web Developer', 'Mô tả công việc\n- Being part of the VN Software Development department.\n- Design & develop the high quality web-bases applications for warehouse & robot fleet management. It will enable both internal users or external customers to make better use of our robotics warehouse automation solution.\n- Develop and integrate solutions across various modules, including web-based dashboards, database, and robotics simulation.\n- Create, execute, and maintain comprehensive test plans; identify and fix bugs while ensuring the integrity of the existing codebase.\n- Contribute to system-level software design, ensuring scalability, reliability, and performance.\n- Formulate, document, and maintain detailed requirements specifications.\n- Analyze, brainstorm and evaluate applications of newly emerged tools and technology.\n- And perform similar duties as he deems fit for the proper execution of his duties and duties as delegated by the direct manager or the Employer.\n\nYêu cầu ứng viên\n- At least 5 years of experience in both front-end and back-end platforms (NodeJS & ReactJS preferred).\n- Familiar with development and deployment in Google Cloud and Amazon Web Services.\n- Experience in database development using Kafka and Snowflake.\n- Experience in messaging systems such as RabbitMQ and/or ZeroMQ.\n- (Plus) Hand-on experience with 3D web (threejs) or other 3D simulation engine (Unity, Omniverse).\n- (Plus) Hand-on experience with ROS, Docker & Linux environment.\n- Maintain a good coding standard, familiar with Test Driven development. Experience with writing unit tests for NodeJS, ReactJS application.\n- Exposure to agile development practices and CI/CD pipelines, experience with project management and collaboration tools like JIRA, Confluence.\n- Good teamwork, communication, time management and problem solving skills.\n- Working proficiency and communication skills in verbal and written English, be able to effectively represent the derived results and technical concepts to the leadership team.\n\nQuyền lợi\n- (Gross) Salary $1800-$3500, Yearly adjustment.\n- Social insurance, health/life/disability insurance, annual health check.\n- 13th month salary.\n- Yearly bonus up to 2 month pay depending on performance review.\n- Hybrid working option: 1 work-from-home day per week.\n- 14 days of paid vacation.\n- Work laptop.\n- Company trip and other team benefits.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Quận 7\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n- Can work from home 1 day/week.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3007, 1320, 2, 'Lập Trình CNC', '- Thiết lập quy trình công nghệ, lập trình gia công các sản phẩm cơ khí trên máy gia công CNC (phay, tiện CNC)\n- Quản lý, kiểm soát chất lượng trong quá trình gia công\n- Thực hiện các công việc khác khi có yêu cầu.\n- Chi tiết công việc sẽ trao đổi khi phỏng vấn.\n\n- Nam trong độ tuổi lao động, sức khỏe tốt.\n- Cẩn thận, tỉ mỉ, trung thực, chịu được áp lực trong công việc.\n- Kỹ năng: thành thạo phần mềm NX, Visi, autocad\n- Ưu tiên ứng viên có thể đi làm luôn sau phỏng vấn, có kinh nghiệm trong vị trí ứng tuyển từ 01 năm trở lên\n\n+ Được hưởng toàn bộ các chế độ, quyền lợi của công ty.\n+ Làm việc ca hành chính , tăng ca theo yêu cầu công việc\n+ Mức lương thỏa thuận theo năng lực.\n+ Chế độ lương tháng thứ 13, tăng lương, thưởng hàng năm.\n+ Đóng BHXH, BHYT, BHTN,... trên tổng lương\n\n- Thái Nguyên: KCN Điềm Thụy, Phú Bình\n\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3008, 1260, 2, 'Frontend Website Engineer - Middle', 'Mô tả công việc:\n- Phát triển giao diện website hiện đại, responsive bằng một trong các thư viện/framework như React, Vue.js hoặc tương đương.\n- Tối ưu hóa UI/UX, đảm bảo tương thích với đa trình duyệt và thiết bị.\n- Tích hợp API từ backend, xử lý dữ liệu và trạng thái ứng dụng hiệu quả.\n- Tham gia review code, viết unit test, đóng góp ý tưởng cải thiện kiến trúc frontend.\n- Làm việc chặt chẽ với các team thiết kế, backend và QA để triển khai tính năng.\n( Nếu có năng lực): Hỗ trợ hoặc tham gia vào một số phần việc backend.\n\nYêu cầu ứng viên:\n- Có từ 4 năm kinh nghiệm lập trình website, trong đó ít nhất 2 năm phát triển frontend bằng React, Vue.js, Angular,.. \n- Có kinh nghiệm thiết kế kiến trúc frontend, tổ chức component theo hướng modular, reusable.\n- Biết làm việc với các thư viện quản lý trạng thái (Redux, Pinia, Zustand, Vuex,...) và routing.\n- Có tư duy tối ưu performance frontend (lazy loading, code splitting, SSR là lợi thế).\n- Ưu tiên ứng viên có kiến thức/kinh nghiệm về Three.js, từng tham gia phát triển fullstack hoặc có hiểu biết về kiến trúc backend/API/database.\n\nQuyền lợi:\n- Lương thỏa thuận theo năng lực (thỏa thuận)\n- Thưởng theo hiệu quả, hiệu suất công việc và kết quả kinh doanh của công ty.\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định nhà nước.\n- Được đào tạo và có lộ trình phát triển nghề nghiệp rõ ràng.\n- Cơ hội thăng tiến lên các vị trí cao hơn trong phòng nhân sự hoặc các vị trí cao hơn tùy theo năng lực.\n- Môi trường làm việc chuyên nghiệp, thân thiện, năng động.\n\nĐịa điểm làm việc:\n- Hà Nội: N7-25 Ngõ 59 Láng Hạ,Thành Công, Ba Đình, Ba Đình.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3009, 1465, 2, 'Lập Trình Viên Java Dev (Middle To TechLead)', 'Trung tâm Công nghệ thông tin thuộc Viettel Construction tuyển dụng Dev Lead Java (Middle → Leader/PM) phụ trách các phần mềm nội bộ domain ERP, HRM, Kinh doanh, ... Công ty Product, Không yêu cầu Tiếng Anh, Phỏng vấn 1 vòng duy nhất, Cụ thể như sau:\n- Lập trình trong các dự án phần mềm sử dụng ngôn ngữ Java trong tổng công ty, bao gồm các sản phẩm phục vụ quản lý điều hành kinh doanh, quản lý bán hàng, chăm sóc khách hàng và quản trị doanh nghiệp (ERP)\n- Thiết kế tổng thể, thiết kế chi tiết (màn hình, api, cơ sở dữ liệu, luồng dữ liệu...) các module chức năng của phần mềm để đảm bảo các tiêu chức năng và phi chức năng (như đáp ứng hiệu năng, tính mở rộng..)\n- Chịu trách nhiệm triển khai và hỗ trợ sau triển khai các phần mềm. Xử lý phản ánh người dùng cuối và sửa các lỗi về tính năng, hiệu năng, kiến trúc của phần mềm.\n- Quản lý nhóm lập trình của một hoặc nhiều sản phẩm, chịu trách nhiệm giao việc, quản lý tiến độ chất lượng công việc của nhóm, báo cáo lên trưởng phòng hoặc ban giám đốc trung tâm. Đào tạo để nâng cao chất lượng nhóm. Nghiên cứu và phát triển công nghệ mới giúp tăng hiệu suất cho dự án.\n\nYêu cầu ứng viên:\n- Độ tuổi tuyển dụng: Dưới 32 tuổi\n- Đã tốt nghiệp Đại học chính quy trở lên chuyên ngành Công nghệ thông tin, hệ thống thông tin, Khoa học máy hoặc ngành liên quan;\n- Có từ 3 năm kinh nghiệm trở lên với các nền tảng và framework công nghệ Java.\n- Nắm vững các kiến thức cơ bản về lập trình hướng đối tượng, lập trình Java core (multithreading, Collection...) /Java web (J2EE, ORM, Caching...)\n- Có kinh nghiệm thành thạo sử dụng một trong các framework/stack về java đang triển khai tại TCT như sau:\n + Framework: Spring-boot, Spring MVC, Angular, Các web framework java phổ biến khác\n + Midware: Kafka, Redis, CEP, BPMN engine...\n + Cơ sở dữ liệu: Oracle, Postgresql, MariaDB, NoSQL\n\nQuyền lợi:\n- Lương cứng tháng : 20.000.000 - 32.000.000 đồng/ tháng theo từng level và kinh nghiệm. Thử việc 100% Lương\n- Có phụ cấp ăn trưa điện thoại 930.000/tháng\n- 14 Tháng lương/năm ( Thưởng tháng lương T13, T14)\n-  Gói Thưởng các ngày lễ tết dành riêng cho người Viettel: 38.000.000 đồng/năm\n- Nghỉ phép 15 ngày/năm\n- Thời gian làm việc: làm từ T2 - T6 + 1 ngày T7 của tuần đầu tiên của tháng.\n- Được ký hợp đồng lao động và tham gia các loại bảo hiểm theo quy định của Nhà nước.\n- Được đào tạo tại công ty hoặc tham gia các khóa đào tạo nâng cao, bổ ích bên ngoài.\n- Tham gia nhiều hoạt động văn hóa, thể dục, thể thao, giải trí.\n- Chính sách du lịch, nghỉ dưỡng, khám sức khỏe định kỳ cho CBNV.\n\n"Viettel Construction tuyệt đối không thu bất cứ khoản tiền nào của ứng viên khi nộp hồ sơ, tham gia dự tuyển và khi vào làm việc tại Viettel Construction nếu trúng tuyển"\n"Khi ứng tuyển vào Viettel Construction, ứng viên phải cam kết các hồ sơ cá nhân cung cấp như Bằng cấp, Chứng chỉ hành nghề... thông tin thật. Trường hợp rà soát phát hiện ứng viên sử dụng hồ sơ giả sẽ xử lý theo Quy định của Pháp luật"\n\nĐịa điểm làm việc:\n- Hà Nội: Viettel Construction tầng 5 tháp B tòa nhà Central Point, số 219 Trung Kính, Trung Hòa, Cầu Giấy.\n\nThời gian làm việc:\nTừ 8h-17h30 các ngày T2 - T6 + 1 ngày T7 đầu tiên của tháng.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3010, 1336, 2, 'Kỹ Sư Lập Trình CNC', 'Tóm tắt công việc:\nChúng tôi đang tìm kiếm một Kỹ sư Lập trình CNC có kỹ năng và sự tỉ mỉ để phát triển và tối ưu hóa các chương trình gia công CNC nhằm hỗ trợ quy trình gia công chính xác. Ứng viên lý tưởng sẽ làm việc chặt chẽ với các bộ phận sản xuất, kỹ thuật và chất lượng để đảm bảo các chi tiết được gia công đạt yêu cầu về thiết kế và tiêu chuẩn chất lượng.\nNhiệm vụ chính:\n1. Lập trình máy CNC bằng phần mềm CAM (ví dụ: Mastercam, NX, Fusion 360) dựa trên bản vẽ kỹ thuật 2D/3D hoặc mô hình CAD.\n2. Lựa chọn dao cụ, thông số cắt và chiến lược gia công phù hợp để sản xuất hiệu quả.\n3. Mô phỏng, kiểm tra và xác nhận chương trình CNC để đảm bảo an toàn, chính xác và hiệu quả.\n4. Tối ưu hóa chu trình gia công để giảm thời gian, tăng tuổi thọ dao cụ và đảm bảo chất lượng sản phẩm.\n5. Hỗ trợ việc setup và xử lý sự cố của máy CNC trong quá trình chạy chương trình lần đầu.\n6. Phối hợp với kỹ sư thiết kế để đánh giá khả năng gia công của sản phẩm và đề xuất các điều chỉnh nếu cần thiết.\n7. Quản lý và lưu trữ hệ thống chương trình CNC và tài liệu liên quan một cách khoa học.\n\nYêu cầu ứng viên:\n1. Tốt nghiệp Cao đẳng hoặc Đại học chuyên ngành Cơ khí, Kỹ thuật sản xuất hoặc lĩnh vực liên quan.\n2. Có ít nhất 5 năm kinh nghiệm lập trình CNC trong môi trường sản xuất chính xác. Hiểu rõ về mã G-code, M-code và vận hành máy CNC (phay, tiện, máy nhiều trục).\n3. Thành thạo phần mềm CAD/CAM (ví dụ: Mastercam, Siemens NX, Fusion 360, SolidCAM).\n4. Đọc hiểu tốt bản vẽ kỹ thuật, ký hiệu GD&T và mô hình 3D.\n5. Hiểu biết về các loại vật liệu gia công như thép, nhôm, nhựa,...\n\nQuyền lợi:\n1. Lương cạnh tranh theo năng lực\n2. Đóng Bảo hiểm full lương\n3. Gói bảo hiểm PVIcare\n4. Tháng lương thứ 13\n5. Thưởng hiệu suất\n6. Xe đưa đón từ Hà Nội - Thái Nguyên, Bắc Ninh - Thái Nguyên\n7. Làm thứ 7 luân phiên.\n\nĐịa điểm làm việc:\n- Thái Nguyên: Lô CN1-1. KCN Sông Công II, Xã Tân Quang, Sông Công, TP Sông Công\n- Bắc Ninh\n- Hà Nội\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nLàm thứ 7 luân phiên.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3011, 1189, 2, 'Java Developer (4 Năm Kinh Nghiệm)', 'Mô tả công việc:\n- Phát triển phần mềm, thực hiện kiểm thử nội bộ, viết tài liệu kỹ thuật và triển khai ứng dụng trên các môi trường khác nhau\n- Phân tích nguyên nhân sự cố, tối ưu từ người dùng hoặc các ứng dụng tích hợp của đối tác, đề xuất phương án xử lý tối ưu.\n- Tham gia phân tích, thiết kế và đưa ra giải pháp kỹ thuật dựa trên tài liệu yêu cầu nghiệp vụ.\n- Xác định và rà soát các vấn đề thường xuyên phát sinh lỗi, xây dựng phương án khắc phục triệt để và giám sát thực thi.\n- Phối hợp với các thành viên trong đội dự án (BA, QA, DevOps, Product Owner,...) để hoàn thiện sản phẩm.\n- Nghiên cứu nâng cấp bản thân để cập nhật các công nghệ, thiết kế mới.\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học trở lên chuyên ngành Khoa học Máy tính/ Công nghệ thông tin hoặc tương đương\n- Từ 4 năm lập trình Java/Spring Boot, đã từng triển khai 2-3 dự án\n- Thuần thục Java Core: OOP, multi-threading, collections, exception handling\n- Spring Boot: Dependency Injection, Bean Lifecycle, Configuration\n- JPA: Entity Mapping, Query Performance, Transaction Management\n- Có kinh nghiệm áp dụng Design Pattern & Principle cơ bản: SOLID, Factory, Singleton, Strategy, Repository\n- Kinh nghiệm làm bảo mật, Spring Security: Authentication, Authorization, JWT, OAuth2\n- SQL & Database: Indexing, Query Optimization, ACID, Transaction\n- Phát triển và vận hành các hệ thống với tải cao: caching, loadbalance, Parallel Processing, Monitoring and Performance Tuning, Scalability, Testing and Benchmarking\n- Kinh nghiệm làm việc hoặc có kiến thức trong môi trường áp dụng DevOp. Hiểu rõ các khái niệm quan trọng như CICD, infrastructure as code, Containerization, orchestration.\nQuyền lợi:\n- Gói thu nhập đến 16 tháng lương/ năm\n- Xét tăng lương theo năng lực và kết quả công việc định kỳ 1 lần/ năm hoặc tăng lương đột xuất theo hiệu quả công việc\n- Chế độ Bảo hiểm sức khỏe cho bản thân và người nhà\n- Nghỉ thứ Bảy, Chủ nhật hàng tuần\n- Du lịch, Teambuilding/ dã ngoại định kỳ hàng năm\n- Chế độ mừng sinh con, quà nhân ngày Lễ/ Tết, quà ngày truyền thống và các chế độ phúc lợi khác\n- Tham gia các khóa đào tạo chuyên môn, nâng cao kỹ năng thực hiện công việc, kỹ năng mềm và thi các chứng chỉ CNTT Quốc tế miễn phí tại Công ty\n- Được tham gia các chương trình đào tạo trước khi bắt đầu công việc và trong quá trình làm việc theo yêu cầu công việc\n- Chính sách phát triển, thăng tiến có lộ trình theo từng vị trí, từng phòng ban.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3012, 1322, 2, 'Product Developer', 'Mô tả công việc:\n- Managing the entire product line life cycle from strategic planning to tactical activities.\n- Specifying market requirements for current and future products by conducting market research and gathering insights from customers and non-customers.\n- Driving solution development across teams by aligning market requirements, product contracts, and positioning strategies.\n- Demonstrating high-level critical thinking in cross-functional process analysis and problem resolution for both new and existing products.\n- Analyzing potential partnerships and collaborations that could benefit product development.\n- Coordinating and building strong working relationships with internal teams, including IT, Sales, Marketing, Product Development, and Operations.\n- Leading the development, approval, training, and communication of new products and product changes, ensuring all internal teams are aware of customer, operational, system, and process impacts.\n- Developing and conducting specialized training programs for newly launched products, enhancing awareness and application of relevant knowledge.\n- Monitoring internal processes for efficiency and effectiveness before and after product launches or changes.\n- Providing support for other departmental projects as needed.\n\nYêu cầu ứng viên:\n- Bachelor’s degree or diploma in Business, Tourism, Business Administration, or a related field (preferred)\n- Good communication skills in English.\n- Proficient in Microsoft Office (Word, Excel, Outlook, PowerPoint)\n- At least 1 year of experience as a Product Developer in Travel companies.\n\nQuyền lợi:\n- Salary: Negotiable based on experience and competency.\n- Benefits: Free parking and lunch allowance.\n- Insurance: Social insurance (BHXH) and health card.\n- Work Location: Prime location at Hanoi Tower – 49 Hai Bà Trưng, Hoàn Kiếm, Hanoi.\n- Career Growth: Opportunities for professional development within the Group.\n- Travel & Activities: Chance to travel to various destinations and participate in corporate activities.\n- Working Schedule: Monday to Friday, weekends off (Saturday & Sunday). On Fridays, employees leave 2 hours earlier.\n- Remote Work Policy: Online working mode available for employees living far from the office.\n\nĐịa điểm làm việc:\n- Hà Nội: Tháp Hà Nội, 49 Hai Bà Trưng, Hoàn Kiếm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3013, 1271, 2, 'Kỹ Sư Phát Triển Phần Mềm', '- Lập trình mã nguồn nghiệp vụ theo yêu cầu người dùng, yêu cầu hệ thống, thiết kế chi tiết ở mức tính năng.\n- Lập trình giao diện theo thiết kế giao diện có sẵn.\n- Phối hợp các thành viên khác trong nhóm tích hợp các tính năng hệ thống.\n- Phối hợp với bộ phận quản lý chất lượng đảm bảo chất lượng hệ thống.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chính quy loại Khá trở lên chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Toán – tin, Điện tử viễn thông,...hoặc các chuyên ngành kỹ thuật khác liên quan.\n- Trình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\n- Có tối thiểu 02 năm kinh nghiệm liên quan đến vị trí ứng tuyển.\n- Sử dụng tốt ít nhất 1 ngôn ngữ lập trình (C/C++/Java/Golang/Android/iOS).\n- Có kiến thức nền tảng về công nghệ thông tin, ngôn ngữ mô hình hóa UML; quy trình phát triển phần mềm và toàn bộ vòng đời ứng dụng; mạng máy tính (các loại mạng, kiến trúc mạng, lập trình mạng, giao thức); ngôn ngữ truy vấn dữ liệu SQL, làm việc với hệ quản trị cơ sở dữ liệu, cấu trúc dữ liệu và giải thuật.\n\nQuyền lợi:\n- Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn\n- Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel\n- Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm\n- Cơ hội tiếp xúc với các dự án lớn, mới mẻ & tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam\n- Cơ hội thăng tiến rõ ràng với nhiều cấp bậc\n- Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn\n- Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời.\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người\n- Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,...\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày\n- Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa nhà Viettel, Số 380 Lạc Long Quân, Tây Hồ\n- Hà Nội: Tòa nhà Keangnam Landmark 72 tầng, Phạm Hùng, Nam Từ Liêm\n- Hà Nội: Tòa nhà Viettel, Khu Công nghệ cao Láng Hòa Lạc, Thạch Thất\n- Hồ Chí Minh: Tòa nhà Viettel, số 285 Cách Mạng Tháng 8, Phường 12, Quận 10\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3014, 1137, 2, 'Fullstack Developer (Node/Next) Level Middle/Senior', 'Mô tả công việc\n- Tham gia vào các dự án phát triển ứng dụng Web;\n- Có khả năng đảm nhận vai trò kỹ thuật leader trong dự án, đề xuất giải pháp kỹ thuật cho các vấn đề phát sinh;\n- Thực hiện thiết kế, lập trình, kiểm thử và viết tài liệu theo yêu cầu hệ thống để đảm bảo chất lượng mã nguồn và đáp ứng các mốc phát hành sản phẩm;\n- Sửa lỗi, bảo trì và nâng cấp hệ thống theo yêu cầu.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các ngành có liên quan\n- Có từ 3 - 5 năm kinh nghiệm làm việc với NodeJS/NextJS;\n- Thành thạo công nghệ ReactJS và NodeJS;\n- Vững kiến thức JavaScript, TypeScript và HTML/CSS; hiểu rõ các nguyên tắc cơ bản, nâng cao và các thực hành tốt nhất trong phát triển ứng dụng phía server và client;\n- Kiến thức tốt về thuật toán và cấu trúc dữ liệu;\n- Sẵn sàng tìm hiểu và xử lý các vấn đề liên quan đến hiệu năng, lỗi đa luồng và tối ưu hệ thống.\n\nQuyền lợi\n- Mức lương (gross): lên đến 30 triệu hoặc lên đến 40 triệu đối với level Senior (thoả thuận khi phỏng vấn);\n- Thưởng tháng 13, thưởng thâm niên, thưởng hàng quý, thưởng chia lợi nhuận;\n- 12 ngày nghỉ phép năm;\n- Xét tăng lương theo hiệu suất vào tháng 6 và tháng 12;\n- Thưởng các dịp lễ như 30/4 - 1/5, 2/9, Tết Dương lịch,...;\n- Tổ chức sinh nhật, tặng quà vào các dịp như Tết Nguyên Đán, Quốc tế Phụ nữ (8/3, 20/10), Trung Thu, Tết Thiếu nhi (1/6), và nhiều dịp khác;\n- Miễn phí trà, đồ ăn nhẹ, cà phê tại văn phòng; hỗ trợ phí gửi xe;\n- Được trang bị đầy đủ thiết bị và công cụ phục vụ công việc hiệu quả;\n- Tham gia vào các hoạt động sôi nổi của công ty: tiệc hàng quý, du lịch thường niên, team building/cắm trại hàng quý, tiệc tất niên và nhiều hoạt động khác.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa MD Complex, 68 Nguyễn Cơ Thạch, Mỹ Đình 1, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3015, 1225, 2, 'Middle/Senior Fullstack Developer (PHP/Laravel)', 'Mô tả công việc\n- Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng.\n- Tham gia phát triển các công đoạn phân tích yêu cầu, Detail Design, Coding, viết tài liệu API, Unit Test.\n- Sử dụng ngôn ngữ PHP và các framework như Laravel, Cake...\n- Xây dựng giao diện và backend của các hệ thống sử dụng PHP.\n\nYêu cầu ứng viên\n- Kinh nghiệm 2 năm trở lên về một trong các PHP framework: Laravel, CodeIgniter, Symfony (Ưu tiên Laravel)...\n- Kỹ năng tư duy logic và thuật toán tốt, phân tích và giải quyết vấn đề, khả năng tự học, tự tìm hiểu.\n- Có tinh thần trách nhiệm cao (với công việc, với khách hàng, với thành viên của Team và với chính mình)\n- Có kinh nghiệm tối ưu thiết kế, truy vấn CSDL (Mysql, Mongodb)\n- Có kỹ năng làm việc độc lập, giải quyết vấn đề, kỹ năng giao tiếp\n- Thành thạo 1 framework FE (VueJs, ReactJs...)\n- Thành thạo các công cụ quản lý source code (Github, Gitlab...)\n- Ưu tiên có kinh nghiệm sử dụng Docker, Linux\n- Ưu tiên có kinh nghiệm về Golang.\n\nQuyền lợi\n- Mức lương khởi điểm hấp dẫn tuỳ thuộc năng lực và kinh nghiệm làm việc. (Up to 40M)\n- Định kỳ review 6 tháng/1 lần theo năng lực.\n- Lương thưởng các ngày lễ, thưởng tháng 13. Ngoài ra còn thưởng thêm dự án tùy thuộc vào thành tích đóng góp cho dự án….\n- Được hưởng đầy đủ các chế độ của công ty: thưởng thành tích công việc hàng tháng, sinh nhật, teambuilding, nghỉ mát, gala.\n- Có lộ trình thăng tiến, phát triển theo năng lực rõ ràng.\n- Tham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động VN\n- Thời gian làm việc: Từ 8h00 đến 17h00 (nghỉ Thứ 7, Chủ Nhật).\n\nĐịa điểm làm việc\n- Hà Nội: FLC Landmark Tower Ngõ 60 Dương Khuê, Mỹ Đình, Nam Từ Liêm, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3016, 1163, 2, 'Senior Front-End Developer (React, NextJS)', 'Unstatic là một startup công nghệ "made in Vietnam" ra đời từ 2016, tập trung nâng cao năng suất cá nhân toàn cầu. Sản phẩm đầu tay Habitify là ứng dụng theo dõi thói quen thành công, được Apple vinh danh nhiều lần trên App Store với các danh hiệu như "App of The Day" và "New App We Love". Việc được Apple chủ động quảng bá tới 13 lần là một minh chứng rõ ràng cho chất lượng của ứng dụng. Hiện tại có hơn 2 triệu người dùng quốc tế, khẳng định vị thế sản phẩm Việt trên thị trường cạnh tranh như Mỹ, Nhật, Hàn.\n\nĐằng sau Habitify là một đội ngũ người Việt trẻ trung, sáng tạo, luôn khao khát đưa sản phẩm "made in Vietnam" ra thế giới bằng con đường chất lượng thực sự. Từng dòng code, từng tính năng đều được tạo ra với sự chỉn chu, tâm huyết và tinh thần làm chủ – điều giúp Habitify luôn theo sát những đổi mới công nghệ và mang lại trải nghiệm tốt nhất cho người dùng.\n\nVới chúng mình, Unstatic không chỉ là nơi làm việc – mà còn là nơi để bạn góp phần tạo ra điều có ý nghĩa cho hàng triệu người. Nếu bạn đang tìm kiếm một môi trường để phát triển, thử thách bản thân, và để lại dấu ấn cá nhân trong một sản phẩm và có giá trị toàn cầu – Unstatic sẵn sàng đồng hành cùng bạn.\n\n1. Nhiệm vụ\n   - Phân tích yêu cầu tổng quan và tính năng cụ thể của ứng dụng.\n   - Phân tích thiết kế giao diện, xác định và triển khai tương tác người dùng phù hợp, đảm bảo tính khả thi và khả dụng của công nghệ đối với yêu cầu và thiết kế.\n   - Thiết kế và phát triển các ứng dụng web có độ phản hồi cao, đáp ứng các yêu cầu về tối ưu hóa dung lượng, thời gian tải/nạp/chạy (parse/load/run-time) và khả năng mở rộng, tái ứng dụng cao.\n   - Thiết kế và triển khai các mô hình phát triển dự án dựa trên hệ sinh thái ReactJS (library và các third party framework).\n   - Liên tục thay đổi cách tiếp cận và triển khai ý tưởng.\n\n2. Yêu cầu ứng viên\n   - Từ 3-4 năm kinh nghiệm với ReactJS và hệ sinh thái (hoặc các library/framework có concept tương tự: React Native, Vue, Ember,...).\n   - Nắm vững sâu về Web stack: HTML5, CSS3, Javascript và Web APIs.\n   - Có hiểu biết về Cross-Browser Compatibility và Polyfills.\n   - Nắm vững các khái niệm cơ bản về NodeJS và các development suite liên quan (NPM/Yarn, Task runners, Dev server,...).\n   - Nắm vững kiến trúc, cơ chế vận hành và mục tiêu đầu ra của Single Page App hoặc Server-side Rendering.\n   - Nắm vững các design principles và có khả năng xây dựng Responsive UI với CSS, Styled-components, CSS-in-JS,...\n   - Nắm vững các Web bundler và build tools: Webpack, Parcel,...cùng với các optimization configs.\n   - Nắm vững các development tools: Devtools, Chrome Extensions, ESLint, Husky,...\n   - Hiểu rõ cơ chế làm việc Git Flow cũng như issue-based management.\n   - Các yêu cầu kỹ thuật mang tính lợi thế: UI/UX design, Node APIs, Static webpage/Vanilla web solutions, Low level CSS Utilities, Popular UI Kit, ảo hóa với Docker, docker-compose, CI/CD (GitHub Actions, Gitlab CI,...)\n\n3. Quyền lợi\n   - Mức lương và phúc lợi:  \n     - Mức lương NET cực kì cạnh tranh, từ 30.000.000 - 40.000.000 triệu/tháng\n     - Thử việc nhận 100% lương\n     - Lương tháng 13, thưởng lễ, tết, thâm niên.\n     - Review lương 1 lần/năm.\n     - Bảo hiểm y tế, bảo hiểm xã hội, bảo hiểm sức khỏe cá nhân (PTI)\n     - Hỗ trợ ăn trưa 500.000 VND/tháng.\n   - Các quyền lợi khác:\n     - Miễn phí gửi xe, snacks & drinks tại văn phòng.\n     - Du lịch công ty, team building, sinh nhật.\n     - Hoạt động Well-being 1 tháng/lần (các hoạt động chăm sóc sức khỏe thể chất và tinh thần).\n     - Happy Lunch vào Trưa thứ 4, Teabreak vào chiều Thứ 3 hoặc chiều Thứ 5 hàng tuần.\n     - Các chế độ khác theo đúng Luật lao động hiện hành.\n   - Môi trường làm việc:\n     - Môi trường product trẻ trung năng động, sáng tạo cao.\n     - Sản phẩm xây dựng ra cho khách hàng quốc tế 100%, hiện có hơn 1.5 triệu người sử dụng trên toàn cầu.\n   - Thời gian làm việc:\n     - Chấm công/làm việc linh hoạt từ 08h00 - 09h30, miễn đủ 8 tiếng, đảm bảo hiệu suất và tiến độ công việc\n     - Làm việc từ thứ 2 đến thứ 6 hàng tuần, nghỉ trưa từ 12h00 - 13h30, thứ 4 nghỉ trưa từ 12h00 - 14h00.\n\n4. Địa điểm làm việc\n   - Hà Nội: Tầng 19, Ladeco Building, 266 Đội Cấn, Liễu Giai, Ba Đình\n\n5. Cách thức ứng tuyển\n   - Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3017, 1213, 2, 'Kỹ Sư Lập Trình C', 'Tham gia từ giai đoạn thiết kế đến triển khai sản phẩm của siêu dự án phát triển phần mềm CAD cho khách hàng Nhật Bản. Dự án phần mềm kiến trúc, xây dựng cho khách hàng Nhật Bản là dự án lớn của tập đoàn DTS Japan (top 10 tập đoàn CNTT tại Nhật Bản), với nhiều modules phần mềm khác nhau, từ Windows App, Web App, iOS App…\nPhát triển Plugin cho revit và các ứng dụng CAD khác theo đơn đặt hàng của khách hàng Nhật.\nĐược đào tạo: chuyên sâu về C#, C/C++ và các kiến thức, kỹ năng cần thiết cho phát triển các sản phẩm cho CAD\nLàm việc trong môi trường chuyên nghiệp, tuân thủ quy trình phát triển phần mềm chuẩn PMS của DTS Japan;\nHợp tác làm việc với các Leaders, Project Manager xuất sắc với hàng chục năm kinh nghiệm tại các công ty phần mềm lớn nhất ở Nhật Bản và Việt Nam với các quy trình quản lý dự án bài bản, chuyên nghiệp.\n\nỨng viên có kinh nghiệm 1 năm trở lên về ngôn ngữ C++, chấp nhận ứng viên mới ra trường đã có kinh nghiệm, chấp nhận ứng viên trái ngành (điện, điện tử, tự động hóa) nắm vững kiến thức và kinh nghiệm về lập trình.\nƯu tiên ứng viên biết tiếng Nhật và có kinh nghiệm làm việc cho công ty/ dự án Nhật.\n\nChế độ đãi ngộ\nLương thỏa thuận theo năng lực thực tế của ứng viên. Performance review: 1 lần/năm.\nTrợ cấp đi lại, trợ cấp ăn trưa, trợ cấp tiếng Nhật, trợ cấp onsite khi tham gia dự án bên khách hàng…\nThưởng Lễ Tết, tháng lương thứ 13, thưởng nhân viên xuất sắc quý, năm, nhân viên xuất sắc năm đi du lịch Nhật Bản\nNghỉ theo lịch công ty, nghỉ theo lịch khách hàng Nhật, (ngoài các ngày nghỉ theo quy định, 1 năm có thêm 2 đợt nghỉ dài)\nNghỉ tham gia Ngày hội khai giảng cùng con\nChế độ chăm sóc sức khỏe cho nhân viên\nBảo hiểm y tế, bảo hiểm xã hội, bảo hiểm thất nghiệp theo quy định của Luật lao động\nBảo hiểm sức khỏe cao cấp cho toàn bộ nhân viên làm việc trên 1 năm\nKhám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín (Bệnh viện Thu Cúc, bệnh viện Medlatec…)\nVăn phòng làm việc tiện ích: Miễn phí trà, có máy pha coffee tại khu vực ăn uống của công ty\n\nCác hoạt động sôi nổi\nHoạt động team building kết nối đội nhóm hàng quý\nCác CLB thể thao: bóng đá, bi lắc…\nHoạt động du lịch, team building thường niên và các sự kiện lớn trong công ty\n\nĐịa điểm làm việc\nHà Nội: 266 Đội Cấn, Ba Đình\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3018, 1359, 2, 'Fullstack Team Lead (Angular + Java) Dự Án Fintech', 'Mô tả công việc:\n- Thiết kế, phát triển và duy trì hệ thống fullstack với:\n  + Frontend: Sử dụng Angular (v12–v16) là chính, có thể làm việc với ReactJS hoặc React Native cho các sản phẩm web/mobile.\n  + Backend: Làm việc với Java Spring Boot, kiến trúc Microservices, xử lý nghiệp vụ phức tạp, tích hợp hệ thống tài chính.\n- Làm việc chặt chẽ với các bộ phận liên quan như BA, PO, QA để đảm bảo sản phẩm đúng yêu cầu và chất lượng cao.\n- Tham gia thiết kế kiến trúc hệ thống, đánh giá giải pháp kỹ thuật, tối ưu hiệu năng và độ ổn định.\n- Quản lý nhóm phát triển: phân công công việc, theo dõi tiến độ, review code, hỗ trợ giải quyết vấn đề kỹ thuật.\n\nYêu cầu ứng viên:\n- Frontend:\n  + Thành thạo Angular từ version 12 và 16, nắm vững kiến thức Front-end, có thể viết mới dựa theo design figma và tích hợp API từ backend, tối ưu hiệu năng web/app.\n  + Có kinh nghiệm với ReactJS hoặc React Native là một lợi thế lớn.\n- Backend:\n  + Thành thạo Java Spring Boot, có kinh nghiệm xây dựng microservices, làm việc với các hệ thống phân tán, RESTful APIs, message queues (Kafka, RabbitMQ).\n  + Hiểu biết về database (Oracle và PostgreSQL) và caching (Redis).\n- Team Leadership:\n  + Có kinh nghiệm quản lý nhóm từ 3–10 người, có khả năng mentoring, định hướng kỹ thuật, xây dựng văn hóa nhóm tích cực.\n  + Kỹ năng giao tiếp tốt, phối hợp hiệu quả với các phòng ban và quản lý cấp cao.\n- Domain:\n  + Ưu tiên lớn cho ứng viên đã từng tham gia các dự án trong lĩnh vực tài chính, fintech, ngân hàng, ví điện tử, hoặc chứng khoán.\n- Ngoại ngữ:\n  + Có thể trình bày, giao tiếp, báo cáo bằng Tiếng Anh.\n\nQuyền lợi:\n- Mức lương và thưởng hấp dẫn.\n- 12 ngày nghỉ phép năm.\n- Được tham gia đầy đủ bảo hiểm xã hội và bảo hiểm y tế theo quy định của nhà nước.\n- Các khoản phụ cấp hấp dẫn (thưởng onsite, gửi xe, sinh nhật, happy hours, v.v.)\n- Xét duyệt tăng lương hàng năm dựa trên hiệu suất và đóng góp của nhân viên.\n- Môi trường làm việc thực sự cởi mở. Mọi người đều được tôn trọng và bạn có quyền tự do theo đuổi cũng như đạt được mục tiêu của mình.\n- Các quyền lợi khác theo quy định của Bộ luật Lao động Việt Nam.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 91 Pateur, đường Bến Nghé, Quận 1.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3019, 1326, 2, 'Kỹ Sư Thiết Kế Phần Mềm', 'Mô tả công việc:\n- Thiết kế, cải tiến và phát triển các hệ thống quản lý dữ liệu cho nhà kho như WMS, MCS, ...\n- Cải tiến và phát triển các mã nguồn để tích hợp các phần mềm quản lý dữ liệu vào hệ thống WMS.\n- Thiết kế, quản lý và tối ưu hóa cơ sở dữ liệu để lưu trữ và truy xuất thông tin hiệu quả trong các phần mềm quản lý dữ liệu.\n- Phát triển và duy trì các phần mềm điều khiển và giám sát các mô hình và hệ thống tự động hóa.\n- Nghiên cứu, tối ưu và phát triển các thuật toán ứng với các phần mềm điều khiển các mô hình tự động hóa.\n- Tư vấn kỹ thuật, thiết kế giải pháp quản lý dữ liệu trong lĩnh vực quản lý kho bãi.\n- Lên kế hoạch thiết kế, thực hiện và triển khai dự án.\n\nYêu cầu ứng viên:\n- Yêu cầu trình độ: Tốt nghiệp đại học chuyên ngành Công nghệ thông tin. (Ưu tiên loại Giỏi)\n- Yêu cầu kỹ năng: Sử dụng thành thạo các phần mềm:\n  + Hệ quản trị cơ sở dữ liệu như: MySQL, Mycrosoft SQL Server, PostgreSQL, ....\n  + Công cụ phát triển phần mềm như: Visual Studio, Eclipse, ...\n- Sử dụng thành thạo các ngôn ngữ lập trình như: C#, Python, Java, JavaScript, SQL, ...\n- Ưu tiên:\n  + Có kinh nghiệm hoặc từng thiết kế phần mềm quản lí như: WMS, WCS, RSC, hệ thống IoT, ...\n  + Hiểu biết về kết cấu hạ tầng mạng để đảm bảo kết nối liên tục và an toàn.\n  + Có nền tảng về Scan dữ liệu hay thu thập dữ liệu như: Barcode, QRcode, RFID, ...\n- Yêu cầu kinh nghiệm:\n  + Có kinh nghiệm thiết kế phần mềm quản lý dữ liệu từ 5 năm trở lên.\n- Yêu cầu khác:\n  + Chăm chỉ, nhiệt tình trong công việc, có thể làm việc trong môi trường áp lực cao.\n  + Đam mê nghiên cứu, thiết kế, hoạt động R&D, có tinh thần cầu tiến, ham học hỏi.\n  + Có thể đi công tác tùy theo yêu cầu của công việc.\n\nQuyền lợi:\n- Mức lương: 12-20 triệu/tháng\n- Hưởng lương tháng thứ 13, thưởng Lễ-Tết\n- Được đóng bảo hiểm theo quy định của Luật Lao động\n- Được làm việc trong môi trường chuyên nghiệp, năng động, có cơ hội học hỏi kinh nghiệm và phát triển bản thân.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Trịnh Thị Miếng, Thới Tam Thôn, Hóc Môn.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3020, 1440, 2, 'Kỹ Sư Thiết Kế Máy', '- Nghiên cứu, thiết kế giải pháp máy tự động, dây chuyền sản xuất tự động kết hợp các máy chấn, đột, dập....\n- Hỗ trợ kinh doanh giải quyết các yêu cầu của Khách hàng về mặt kỹ thuật thiết bị và giải pháp.\n- Thiết kế 3D, bóc tách bản vẽ 2D, lập danh mục vật tư tiêu chuẩn chế tạo các máy tự động công nghiệp.\n- Tính toán, phân tích, mô phỏng tính khả thi của ý tưởng, thuyết trình ý tưởng của dự án.\n- Đặt hàng, hỗ trợ lắp ráp, tham gia nghiệm thu máy, hướng dẫn đào tạo vận hành, hoàn thiện hồ sơ thiết kế.\n- Quản lý dự án và triển khai dự án.\n- Thực hiện các công việc khác theo sự phân công của trưởng phòng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Cơ khí chế tạo máy, cơ điện tử.\n- Có ít nhất từ 1 năm kinh nghiệm tại vị trí tương đương.\n- Sử dụng tốt phần mềm thiết kế 3D: Solidwork hoặc Inventor.\n- Có khả năng giao tiếp, đàm phán, ra quyết định.\n- Đọc hiểu tiếng anh chuyên ngành, Tin học thành thạo, Project, Power point, Excel.\n\nQuyền lợi:\n- Lương cơ bản từ 15 đến 20m, kèm thưởng dự án, thưởng hiệu quả, phụ trách công trình, tổng thu nhập >20m.\n- Chế độ lương, thưởng, phúc lợi cạnh tranh.\n- Công ty trang bị máy tính để phục vụ công việc.\n- Công ty trang bị ô tô nếu cần di chuyển để gặp khách hàng.\n- Thời gian làm việc: Từ 08:00 đến 17:00 từ Thứ 2 đến Thứ 6 (nghỉ trưa 1h), 1 tháng làm việc 2 ngày thứ Bảy.\n- Tham gia BHXH, BHYT đầy đủ sau khi kết thúc thử việc.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 285 Phúc Lợi, Long Biên, Long Biên.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3021, 1205, 2, 'Lập Trình Viên C++', 'Là một Công ty hoạt động trong lĩnh vực Y tế số, chúng tôi coi nhân sự là trung tâm của mọi hành động. Ominext đang nỗ lực xây dựng một môi trường sống hạnh phúc, chú trọng tới phát triển chuyên môn và chăm sóc sức khỏe cho từng Cán bộ nhân viên, người thân của họ! Gia nhập Ominext ngay hôm nay để tận hưởng các ưu đãi đặc quyền dành riêng cho người Omi.\n\nVới vai trò là Lập trình viên C++, ứng viên sẽ thực hiện các công việc:\n- Cùng team dự án tìm hiểu phân tích yêu cầu, nghiên cứu công nghệ và review source code những sản phẩm trên nền tảng công nghệ C++.\n- Phát triển và bảo trì ứng dụng sử dụng C++ Builder.\n- Thiết kế giao diện người dùng cho ứng dụng.\n- Tối ưu hóa mã nguồn để đảm bảo hiệu suất tốt nhất.\n- Thực hiện kiểm tra và gỡ lỗi (debug) ứng dụng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Công nghệ thông tin hoặc chuyên ngành liên quan.\n- Có tối thiểu 2 năm kinh nghiệm làm việc với C++\n- Thành thạo lập trình hướng đối tượng (OOP) và các nguyên lý thiết kế phần mềm.\n- Ưu tiên ứng viên có kinh nghiệm lập trình với C++ và C++ Builder hoặc tương đương (ví dụ như WinForm, Java Swing, ...)\n- Có kinh nghiệm làm việc với SQL Server, MySQL, ...\n- Ưu tiên ứng viên có kinh nghiệm làm việc với VCL\n- Kỹ năng phân tích và giải quyết vấn đề tốt.\n- Khả năng làm việc độc lập và theo nhóm.\n- Có khả năng gỡ lỗi (debug).\n\nQuyền lợi:\n- Môi trường làm việc lý tưởng, được tôn trọng:\n  - Được làm việc trong một môi trường đạt được tiêu chuẩn cao về sự hài lòng của nhân viên.\n  - Thời gian làm việc thoải mái: Thứ 2 – Thứ 6, flexible check in (Linh hoạt 8h/ngày, check in tiêu chuẩn 8h-8h45).\n  - Chính sách làm việc remote linh hoạt 2 ngày/tháng. Áp dụng ngay từ thời gian thử việc.\n  - Chính sách đăng ký OT linh hoạt: OT remote và OT offline.\n  - Chính sách Your times: nghỉ có hưởng lương lên tới 12 ngày trong năm và các ngày nghỉ lễ theo luật Lao động.\n  - Văn phòng làm việc với không gian mở, khu pantry miễn phí đồ uống.)\n  - No Dresscode: trang phục đi làm lịch sự, thoải mái, tôn trọng cá nhân.\n- Tập trung hỗ trợ sự phát triển cá nhân:\n  - Mentor 1-1, sát sao tận tình.\n  - Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng với hệ thống career path (phát triển theo hướng chuyên gia hoặc hướng quản lý) đã được nghiên cứu, thử nghiệm trong nhiều năm.\n  - Tham gia khóa học tiếng Nhật, tiếng Anh miễn phí.\n  - Cơ hội tham gia nhiều dự án đa dạng, team size từ 10MM - 150MM.\n  - Quy trình phát triển phần mềm chặt chẽ, theo các mô hình: Agile, Scrum, Waterfall.\n  - Cơ hội thăng tiến lên các vị trí quản lý như: Team Leader, Techlead,...\n- Quan tâm đặc biệt tới nhân viên:\n  - Mức lương: Hấp dẫn, cạnh tranh với thị trường.\n  - Thưởng hiệu quả sản xuất kinh doanh 2 lần/năm. Thưởng nóng, thưởng lễ tết, lương tháng 13.\n  - Xét tăng lương/thăng chức 2 lần/năm.\n  - Trợ cấp tiếng Nhật 12 tháng liên tục lên tới 5.000.000 VNĐ/ tháng.\n  - Hỗ trợ 100% chi phí thi chứng chỉ CNTT theo chính sách công ty.\n  - Chế độ chăm sóc phụ nữ: nghỉ có hưởng lương 1h/ngày nghỉ sau sinh cho nhân viên nữ có con dưới 12 tháng.\n  - Bảo hiểm chăm sóc sức khỏe cao cấp miễn phí dành riêng cho Omizen Care.\n  - Tủ thuốc miễn phí chăm sóc sức khỏe cá nhân tại Văn phòng làm việc.\n  - Khám sức khỏe thường niên tại phòng khám, bệnh viện hàng đầu Việt Nam cùng các chế độ BHXH theo quy định của nhà nước.\n  - Được tham gia các CLB để nâng cao sức khỏe, tinh thần: CLB bóng đá, CLB cầu lông, CLB bóng bàn,...\n  - Du lịch thường niên, hoạt động team building hàng quý/năm.\n\nĐịa điểm làm việc: Tòa nhà 6th Element, khu đô thị Tây Hồ Tây, quận Tây Hồ, Hà Nội\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:15)\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3022, 209, 2, 'Special Projects Engineer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n• Contribute to a wide range of initiatives, including:\n• Integration, automation, and customization of enterprise systems such as Salesforce, NetSuite, Airtable, Jira, and CLM.\n• Application development using Python, Java, React, and SQL.\n• DevOps and infrastructure management using GCP, Argo CD, Terraform, and GitHub.\n• Designing and maintaining data pipelines for orchestration, ingestion, and analytics.\n• Operate effectively in a fast-paced, high-ambiguity environment with shifting priorities and evolving scopes.\n• Collaborate cross-functionally to solve complex and undefined problems.\n• Maintain high standards while delivering rapid iterations.\n• Embrace a culture of continuous learning, feedback, and improvement.\n\nREQUIREMENTS\n• Require robust expertise in Salesforce and NetSuite.\nTechnical proficiency in:\n• Enterprise Platforms: Airtable, Jira, CLM systems\n• Programming Languages: Python, Java, SQL, JavaScript (React)\n• DevOps & Infrastructure: Google Cloud Platform (GCP), Argo CD, Terraform, GitHub\n• Data Engineering: Data orchestration, ingestion, and analytics pipelines\n• Demonstrated ability to learn quickly and work independently.\n• Comfortable with ambiguity and shifting priorities.\n• A “builder” mindset with a bias toward rapid prototyping and iteration.\n• Excellent problem-solving skills in both technical and strategic contexts.\n• Systems-oriented thinking, intellectual curiosity, and a strong sense of ownership.\n• Experience working across multiple technical domains and disciplines.\n• Strong communication and collaboration skills suited to a high-performance, innovation-driven culture.\n\n• Attractive Salary Package based on your competence plus Annual Bonus and Project Performance Bonus.\n• Signing bonus up to 20M onboard before 02/07/2025\n• Annual Summer Vacation support from 700 hundred VND to 4 Million VND and up to 3 days off work.\n• 13th-month Salary.\n• Salary review according to Company Policy.\n• Annual leave according to Labor Law and Company Policy.\n• “FPT care” health insurance provided by Petrolimex (PJICO) and is exclusive for FPT employees: 57M – 160M.\n• 20% discount on school fee if your sons/daughters join FPT School.\n• Excellent cost-free learning opportunities: Udemy/ELSA PRO accounts for every employee & Udacity accounts for Managers, English/Japanese/Korean classes, sponsorship for taking certification such as PMP, AWS, etc.\n• International, professional, dynamic and friendly working environment and culture.\n• Be part of a team in an international world-class company and exchange knowledge with technology specialists and experts from the world’s leading companies.\n• Frequent staff activities and company parties;\n• Awesome social events and parties for employees.\n\n• Đà Nẵng: Tòa Nhà FPT Complex, Ðường Nam Kỳ Khởi Nghĩa, Phường Hoà Hải TP.Ðà Nẵng, Ngũ Hành Sơn\n\n• Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\n• Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3023, 1156, 2, 'React Native Developer Leader', 'Dẫn dắt và quản lý nhóm phát triển React Native để xây dựng các ứng dụng di động phục vụ khách hàng của Bank.\nThiết kế và phát triển kiến trúc ứng dụng React Native, đảm bảo hiệu suất, bảo mật và khả năng mở rộng.\nXây dựng và triển khai API, tích hợp với hệ thống ngân hàng và các đối tác bên ngoài.\nĐịnh hướng và tối ưu codebase, áp dụng Clean Architecture và các phương pháp phát triển hiện đại.\nĐảm bảo chất lượng mã nguồn thông qua code review, unit test và CI/CD.\nPhối hợp với các phòng ban liên quan như BA, PO, UI/UX để hiểu yêu cầu và đưa ra giải pháp phù hợp.\nHướng dẫn và đào tạo các thành viên trong nhóm, đảm bảo đội ngũ phát triển vững mạnh.\nBáo cáo tiến độ công việc và đề xuất giải pháp kỹ thuật với quản lý dự án.\n\nYêu cầu ứng viên:\nTừ 4 năm kinh nghiệm làm việc với React Native.\nĐã có kinh nghiệm leader tối thiêu 1 năm\nĐã tham gia phát triển ứng dụng Web/App (1-3 dự án lớn 100 Man-month): Mobile banking, Internet Banking, app giao dịch chứng khoán, trái phiếu, ví điện tử, ví doanh nghiệp, fintech, Marketing Automation, CRM, Ecommerce.\nKiến thức Công nghệ: Hiểu biết sâu sắc về các công nghệ phát triển ứng dụng, ngôn ngữ lập trình, cơ sở dữ liệu, và các công cụ phát triển phổ biến.\n\nQuyền lợi:\n● Lương khởi điểm từ 30M - 40M\n● Làm việc từ thứ 2 đến thứ 6\n● Hưởng các chế độ, phúc lợi như: Thưởng lễ, thưởng Tết, lương tháng 13\n● Tổ chức sinh nhật cho nhân viên\n● Tổ chức teambuilding, du lịch hàng năm\n● Khám sức khỏe cho nhân viên hàng năm\n● Review lương hàng năm\n● Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n● Môi trường làm việc trẻ và năng động, tôn trọng phát triển cá nhân, công bằng và luôn khuyến khích sáng tạo để tạo nên những giá trị "awesome" cho công ty & cho thế giới\n● Các thành viên công ty thân thiện cởi mở, chia sẻ, giúp đỡ nhau vượt qua mọi khóa khăn trong công việc và đời sống.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 45 Đ. Nguyễn Hữu Thọ, Phước Kiển, Nhà Bè.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3024, 1429, 2, 'Senior Rust Developer', 'About Us\nWe’re building next-generation decentralized infrastructure to power applications at the edge of connectivity and compute. Our platform enables contributors to share bandwidth, compute, and storage – creating a trust-minimized, permissionless network backbone for the future of the internet.\nWe’re looking for a Senior Rust Developer with deep understanding of networking concepts and a passion for low-level systems programming. You\'ll be a core contributor to our protocol stack, working on high-performance services, peer-to-peer systems, and distributed runtime environments.\nLocation: Remote / Hybrid\nType: Full-time\nExperience Level: Senior\nSalary: Competitive, with equity options available\n\nWhat You\'ll Do\n- Architect and implement performant network protocols, proxies, and overlay services in Rust.\n- Build P2P systems, NAT traversal techniques (e.g., STUN, TURN, hole punching), and custom messaging layers.\n- Contribute to our edge runtime, handling bandwidth-sharing, node discovery, and transport layer logic.\n- Develop and maintain safe, efficient async systems using tokio, async-std, or similar frameworks.\n- Collaborate with distributed systems engineers, cryptographers, and DevOps on protocol design and deployment strategy.\n- Mentor junior developers and participate in architecture reviews and code audits.\n\nYêu cầu ứng viên\n- Strong understanding of networking concepts: TCP/UDP, DNS, TLS, WebRTC, gRPC, NAT, Anycast, etc.\n- Experience with asynchronous programming and concurrency patterns in Rust.\n- Deep knowledge of systems-level concepts like memory management, multithreading, and I/O performance.\n- Experience building distributed or peer-to-peer systems.\n- Proficient in debugging, profiling, and performance tuning.\n\nQuyền lợi\n- Gross Salary: $1300-$2000\n- Paid social insurance premiums, project bonuses, monthly and quarterly bonuses for employees, other benefits, and holiday bonuses.\n- Working in a dynamic environment with many interesting projects, developing and applying the latest technologies.\n- Fast growing company with many opportunities for growth and advancement\n- Supported internal courses/training to improve professional skills.\n- Other benefits: periodic team building, annual travel, vacation...\n- Many activities: weekly football club, year-round football tournament, table tennis, ...\n\nBonus Points For\n- Experience with VPNs, proxies, or custom overlay networks\n- Experience with edge computing, IoT, or embedded systems.\n- Understanding of libp2p, QUIC, Noise protocol, or similar stacks.\n\nWhy Join Us\n- Work on cutting-edge decentralized infrastructure with real-world impact.\n- Join a tight-knit, high-caliber team pushing boundaries of distributed tech.\n- Token incentives and equity for long-term contributors.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3025, 1200, 2, 'Middle Fullstack Developer', 'Phát triển sản phẩm phần mềm sử dụng BE: Java spring, ReactJS, Bootstrap, Javascript,... FE: Angular cho các đối tượng khách hàng khác nhau.\nĐược tham gia sâu vào các giai đoạn của một dự án như: phân tích, thiết kế, lập trình, kiểm thử, bảo trì phần mềm\nLập trình các module theo thiết kế và theo công việc được phân công trong dự án tham gia\n\nYêu cầu ứng viên\nKinh nghiệm tối thiểu 02 năm kinh nghiệm lập trình\n1. Kiến thức về Angular, ZK:\nThành thạo Angular, ZK, hiểu rõ các concepts như components, directives, services, modules, và pipes.\nKinh nghiệm làm việc với Angular CLI để xây dựng và quản lý ứng dụng.\nKinh nghiệm với Angular Routing, Forms (Reactive và Template-driven), và Dependency Injection.\nKiến thức vững về TypeScript, bao gồm typing, interfaces, generics và decorators.\nThành thạo HTML5 và CSS3, khả năng xây dựng giao diện responsive.\nKinh nghiệm với JavaScript, ES6+ và các khái niệm như closures, promises, async/await.\n\n2. Frontend Tools:\nKinh nghiệm sử dụng các công cụ build như Webpack, NPM, và các package manager.\nQuen thuộc với Git và quản lý mã nguồn.\n\n3. Java:\nThành thạo OOP, exception handling, collections, streams & lambda.\nHiểu về multithreading và concurrency.\n\n4. Spring Boot:\nBiết cách sử dụng Spring Boot để phát triển ứng dụng nhanh chóng.\nThành thạo Spring Data JPA, Spring Security, và Spring RESTful APIs.\n\n5. Oracle, MariaDB\nKinh nghiệm SQL, PL/SQL, và thiết kế cơ sở dữ liệu.\nQuen với công cụ như Oracle SQL Developer và tối ưu hóa truy vấn.\n\nQuyền lợi\nMức lương up to 30M.\nThời gian làm việc: 8h00-17h30, nghỉ trưa 1,5h (12h – 13h30) từ thứ 2 - thứ 6\n13 tháng lương + thưởng lễ tết; xét tăng lương hàng năm\nDu lịch hàng năm, team building hàng tháng/quý\nBảo hiểm xã hội, BHYT theo quy định của Nhà nước\nGói bảo hiểm sức khỏe\nKhám sức khỏe định kỳ hàng năm\nMôi trường flat trẻ trung, thoải mái\nCơ hội tham gia dự án tiềm năng, thử thách nhưng không kém phần thú vị.\n\nĐịa điểm làm việc\n- Hà Nội: Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Nam Từ Liêm', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3026, 1411, 2, 'PHP Backend Developer (Lavarel,Cake PHP,DB Design)', '■ Thông tin công ty:\nCông ty khách hàng của Lampart là 1 Công ty Start-up Nhật Bản hoạt động trong lĩnh vực in ấn đang tìm kiếm ứng viên đảm nhận công việc phát triển website thương mại điện tử của Công ty.\nChi tiết sẽ được trao đổi cụ thể trong quá trình phỏng vấn.\n■ Mô tả công việc:\n・Tham gia phát triển và triển khai các tính năng mới hệ thống back-end của Website\n・Bảo trì hệ thống Website để nâng cao khả năng phát triển của trang.\n・Các công việc liên quan theo phân công của quản lý.\n\n1. Yêu cầu chung:\n- Tối thiểu 2 năm kinh nghiệm lập trình web sử dụng ngôn ngữ lập trình PHP, trong đó:         \n・Có ít nhất 2 năm kinh nghiệm về PHP Framework như: Lavarel, CakePHP \n・Có ít nhất 2 năm kinh nghiệm về database: MySQL hoặc PostgreSQL và có thể thiết kế Database\n- Có thể đọc hiểu tài liệu kỹ thuật bằng tiếng Anh (ví dụ: tài liệu tham khảo PHP v.v.) \n- Kỹ năng giao tiếp tốt: có khả năng lắng nghe, diễn đạt, hiểu & phản hồi thông tin bằng lời nói một cách hiệu quả.\n- Làm việc nhóm tốt, hòa đồng và giúp đỡ người khác trong công việc \n- Có trách nhiệm cao.\n- Có kỹ năng Quản lý công việc hiệu quả \n- Có khả năng làm việc dưới áp lực cao \n\n2. Lợi thế ứng tuyển:\n- Thành thạo HTML5, CSS3 và JavaScript (bao gồm cả JS Framework)  \n- Có kinh nghiệm thiết lập môi trường phát triển với Docker.   \n- Có kinh nghiệm sử dụng GitHub để quản lý mã nguồn.\n\nQuyền lợi:\n・ Công ty trang bị Laptop/ Monitor.\n・ BHXH full lương.\n・ Đánh giá lương, thưởng hàng năm.\n・ Khám sức khỏe định kỳ.\n・ Du lịch Công ty.\n・ Phụ cấp tăng ca.\n・ Phụ cấp thâm niên.\n・ Nghỉ phép năm.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lầu 12, An Phú Plaza 117-119 Lý Chính Thắng, Phường Võ Thị Sáu, Quận 3\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3027, 1253, 2, 'Fullstack Developer', 'Mô tả công việc\n- Sử dụng Java phát triển các service sử dụng REST API (Java Spring Boot) trong hệ thống kiến trúc Microservices\n- Lập trình frontend cho các dự án phát triển sản phẩm\n- Tham gia phát triển nền tảng quản lý & bán hàng trên hệ thống Sapo: quản lý bán hàng, quản lý kho, quy trình hoàn tất đơn hàng, phát triển các kênh bán hàng POS, Web, Marketplace, Social...\n- Tham gia phân tích nghiệp vụ, đảm bảo chất lượng, tiến độ công việc và trải nghiệm người dùng (hiệu năng, tính dễ sử dụng, cũng như mức độ ổn định của sản phẩm).\n- Triển khai các hạng mục công việc theo nhiệm vụ được giao. Tham gia & kiểm soát các hạng mục phát triển tính năng mới, cải tiến tính năng cũ nhằm đảm bảo chất lượng và khả năng mở rộng.\n- Phối hợp với team nghiên cứu và ứng dụng các công nghệ mới để triển khai tính năng mới, đồng thời cải tiến liên tục các hạng mục đã ra mắt nhằm tối ưu hiệu năng & duy trì ổn định sản phẩm.\nYêu cầu ứng viên\n- Tốt nghiệp chuyên ngành Công nghệ thông tin và các chuyên ngành liên quan khác.\n- Có từ 2 năm kinh nghiệm trở lên lập trình Java Full Stack (Backend Java Springboot + Frontend) \n- Sử dụng thành thạo Git hoặc SVN.\n- Hiểu biết các Framework: Spring, Hibernate.\n- Có hiểu biết tốt về Design pattern, OOP, REST API.\n- Có kinh nghiệm & hiểu biết về xây dựng hệ thống Microservice.\n- Có tư duy logic tốt, khả năng tự tìm hiểu & giải quyết vấn đề tốt\n- Có kiến thức về cơ sở dữ liệu quan hệ Mariadb, MySQL.\n- Ưu tiên có kinh nghiệm về Domain Driven Design, NoSQL (Redis, MongoDB), các hệ thống Message Queue (Kafka, RabbitMQ).\n- Chủ động trong công việc, có tinh thần trách nhiệm cao.\n- Chủ động phối hợp với thành viên trong team để giải quyết vấn đề, thực hiện mục tiêu.\n- Ưu tiên có kinh nghiệm vận hành hệ thống AWS là 1 lợi thế.\nQuyền lợi\n- Thu nhập cạnh tranh cùng chính sách thưởng rõ ràng, minh bạch theo hiệu quả công việc, thỏa thuận theo năng lực của UV\n- Xét duyệt tăng lương định kỳ hằng năm, ghi nhận sự nỗ lực và đóng góp của bạn\n- Môi trường làm việc trẻ trung, năng động, khuyến khích sáng tạo và chủ động phát triển\n- Được đóng đầy đủ BHXH, BHYT theo quy định của pháp luật; đồng thời tham gia chương trình chăm sóc sức khỏe toàn diện Sapo Care\n- Cơ hội đào tạo chuyên sâu với các chuyên gia hàng đầu trong lĩnh vực thương mại điện tử, marketing online, phần mềm, giúp bạn phát triển toàn diện về kỹ năng và kiến thức.\nĐịa điểm làm việc\n- Hà Nội: Tầng 6, Tòa Ladeco 266 Đội Cấn, Ba Đình.\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Nghỉ trưa 1h30\'\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ba Đình, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3028, 1192, 2, 'Nhân Viên Lập Trình Gia Công Phay CNC', 'Mô tả công việc:\n- Setup máy phay Cnc gia công sản phẩm mẫu \n- Lập trình Phay cnc gia công sản phẩm \n- Làm setup sheet cho sản phẩm phay\n- Tạo quy trình công nghệ cho sản phẩm phay\n- Tạo các tài liệu kỹ thuật\n- Có khả năng hướng dẫn đào tạo nhân lực cho phòng kỹ thuật\n- Báo cáo công việc hằng tuần (ngày) qua mail\n\nYêu cầu ứng viên:\n- Sử dụng thành thạo máy phay CNC hệ điều hành Fanuc\n- Sử dụng thành thạo phần mềm: MasterCam2020 và có kiến thức về phần mềm thiết kế Soliwork hoặc Inventor \n\nQuyền lợi:\n- Mức lương được thỏa thuận theo năng lực từ 12-18 triệu (lương chưa bao gồm phụ cấp tăng ca)\n- Môi trường làm việc chuyên nghiệp, hỗ trợ, có lộ trình phát triển rõ ràng\n- Cơ hội tham gia công tác hội nghị triển lãm ở các nước Nhật, Mỹ, Hàn, Châu âu hằng năm\n- Thưởng lương tháng 13\n- Công ty hỗ trợ cơm trưa\n- BHXH- BHYT- BHTN, nghỉ lễ, tết, phép năm đầy đủ theo luật lao động\n- Bảo hiểm tai nạn 24h\n- Tổ chức đi du lịch 2 năm / 1 lần\n- Quà khi sinh nhật, kết hôn, sinh con, ...\n- Xét tăng lương định kỳ 1 lần/năm theo năng lực\n- Thưởng các ngày lễ, tết, lương tháng 13\n- Môi trường làm việc thân thiện, năng động và chuyên nghiệp\n\nĐịa điểm làm việc:\n- Bình Dương: 144/46 Khu phố 2, Phường Đông Hòa, Thị xã Dĩ An, Dĩ An\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3029, 756, 2, 'Junior Android Developer', '- Phát triển ứng dụng, module ứng dụng Android theo phân phối của Team Leader.\n- Tham gia phân tích, thiết kế kiến trúc, luồng nghiệp vụ của ứng dụng di động theo phân phối của team leader.\n- Phối hợp với Mid Level/ Senior Developer thực hành code review.\n- Phối hợp với các team liên quan vận hành dự án theo quy trình.\n- Tham gia hướng dẫn, đào tạo member mới.\n- Được phép tự do nghiên cứu công nghệ mới, đề xuất ý tưởng đóng góp vào dự án.\n\nYêu cầu ứng viên\n- Có tối thiểu 1 năm kinh nghiệm Android (Java/Kotlin)\n- Nắm được khái niệm Android cơ bản (Activity/Service/View System, Resource, Storage, Thread Handling).\n- Có kinh nghiệm sử dụng Jetpack Component, Coroutine/Rx.\n- Đã từng sử dụng một trong các mô hình kiến trúc MVP, MVVM.\n- Hiểu biết Design Pattern là một lợi thế.\n- Có khả năng dựng module độc lập là một lợi thế.\n- Am hiểu Agile Scrum là một lợi thế.\n- Đam mê, chủ động công việc, có kỹ năng làm việc nhóm, làm việc độc lập.\n- Đam mê phát triển sản phẩm.\n- Có kỹ năng làm việc nhóm/ theo quy trình là một lợi thế.\n\nQuyền lợi\n- Mức lương 12.000.000 - 28.000.000 VNĐ.\n- Xét tăng lương 1 lần/năm. Lương tháng 13\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN.\n- Các gói bảo hiểm ngoài BHXH: Bảo hiểm PTI, khám sức khỏe định kỳ hàng năm\n- Văn hóa làm việc GenZ,môi trường làm việc trẻ trung, sáng tạo, Dám nghĩ - dám làm, trà đá, bàn tròn,\n- ném đá sếp, áp dụng triệt để văn hóa 6K startup, TSB3C.\n- Thực chiến cùng quản lý, chuyên gia từ các tập đoàn lớn: Topica, VNG, Samsung,...\n- Du lịch hàng năm, team building, tea break hàng tuần\n\nĐịa điểm làm việc\n- Đà Nẵng: Hải Châu\n\nThời gian làm việc\n8:00 - 17:30, nghỉ trưa 1h30’, làm việc từ T2-T6\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng, Hải Châu', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3030, 1312, 2, 'Kỹ Sư Phát Triển Phần Mềm', 'Mô tả công việc:\n- Tham gia và được đào tạo trong quá trình nghiên cứu phát triển sản phẩm điện tử trên ô tô.\n- Phát triển MCU/AP Bootloader.\n- Thiết kế AUTOSAR và MCU SW.\n- Phát triển Embedded linux/RTOS BSD/middleware.\n- Phát triển PC Tools điều khiển simulator (CAN/Ethernet).\n- Sử dụng ứng dụng auto process (CMMI, ISO26262, A-spice) software.\n- Phối hợp với các thành viên trong dự án để đảm bảo dự án thành công và đúng tiến độ.\n- Nghiên cứu và áp dụng các công nghệ mới.\n\nYêu cầu ứng viên:\n- Bắt buộc:\n  - Tốt nghiệp đại học các chuyên ngành CNTT, Kỹ thuật Điện-Điện tử, Kỹ thuật Cơ điện tử, Kỹ thuật Điều khiển và tự động hoá.\n  - Thành thạo ngôn ngữ lập trình C/C++.\n  - Có kinh nghiệm lập trình cho các dòng vi điều khiển 8, 16, 32 bit.\n  - Giao tiếp thành thạo tiếng Anh, đọc hiểu các tài liệu chuyên ngành.\n- Ưu tiên:\n  - Có kinh nghiệm lập trình với ngôn ngữ C#.\n  - Có kinh nghiệm phát triển giao thức CAN/Ethernet trên tầng ứng dụng.\n  - Có kinh nghiệm phát triển UI/QT.\n  - Có kinh nghiệm phát triển bộ điều khiển xe ô tô (ECU) software.\n  - Có khả năng phát triển PC Tools điều khiển simulator (CAN/Ethernet) là một lợi thế.\n  - Có khả năng tiếp thu và vận dụng công nghệ mới.\n  - Cởi mở trong giao tiếp, sẵn sàng tiếp nhận góp ý từ người khác.\n  - Khả năng làm việc nhóm và độc lập.\n  - Trung thực, có tinh thần trách nhiệm cao, khả năng chịu áp lực công việc tốt.\n\nQuyền lợi:\n- Được hưởng đầy đủ mọi chế độ quyền lợi của người lao động theo đúng quy định của Pháp luật.\n- Lương: Thỏa thuận (cạnh tranh hấp dẫn).\n- Được tham gia BHXH, BHYT, BHTN ngay sau khi ký hợp đồng lao động (trong cả thời gian thử việc).\n- Môi trường làm việc chuyên nghiệp, mức thu nhập thỏa đáng và cơ hội phát triển nghề nghiệp.\n- Được tăng lương, thưởng theo hiệu quả công việc.\n- Ngoài mức lương thương lượng xứng đáng với khả năng của ứng viên, trong quá trình ứng viên làm việc tại Công ty sẽ được đánh giá năng lực thực tế và có chế độ đãi ngộ xứng đáng với các nỗ lực và đóng góp cho Công ty.\n- Có xe đưa đón CBCNV Hà Nội – Ninh Bình hàng ngày.\n\nĐịa điểm làm việc:\n- Ninh Bình: Lô CN1 KCN Phúc Sơn, phường Ninh Sơn, TP Ninh Bình.\n- Nam Định.\n- Thanh Hoá.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Ninh Bình', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3031, 209, 2, 'Java Developer', 'We are looking for an enthusiastic and eager Java Developer to join our growing team. This is an excellent opportunity for individuals with a foundational understanding of software development principles who are keen to learn and build applications using the low-code platform. You will work alongside experienced developers, contributing to the development and maintenance of our applications while gaining valuable hands-on experience.\n\nYêu cầu ứng viên:\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field \n- Basic understanding of software development concepts and methodologies. \n- Possesses knowledge and experience in Java programming\n- Strong logical thinking and problem-solving skills. \n- Good communication and teamwork skills. \n- Strong analytical and problem-solving skills. \n- Fluency in English \n\nQuyền lợi:\n- Attractive income package as negotiation\n- Global and inclusive workplace with monthly cross-cultural events\n- International exposure and career growth across global locations\n- Work-life balance benefits supporting employee well-being\n- Private health insurance with optional family coverage\n- Summer vacation allowance\n- Sponsored training courses for personal growth\n- Comprehensive relocation package\n\nĐịa điểm làm việc: Hồ Chí Minh: Lô E3 Đ. Võ Chí Công, Quận 9\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3032, 1187, 2, 'Senior Operation Engineer', 'As an Operation Engineer at Rikkeisoft, you will be responsible for operating and managing a variety of systems and applications deployed as services. You will ensure stable service delivery through proactive monitoring, system inspections, and collaboration with development and overseas teams.\n\nKey Responsibilities:\n- Manage and respond to service requests (SR) via Jira.\n- Monitor system performance and health to ensure stability and availability.\n- Perform DevOps-based deployments for web, app, and hybrid platforms.\n- Conduct regular preventive maintenance (PM) activities to mitigate service disruptions.\n- Oversee operations across Cloud, Application, and DBaaS platforms (monitoring only; no direct incident resolution required).\n- Handle database operations on cloud platforms.\n- Prepare and submit operation reports summarizing key outcomes and improvement points.\n- Collaborate with the team in Seoul regarding operational processes and updates.\n- Analyze application logs and system behavior to identify improvement areas.\n\nQualifications:\n- Bachelor\'s degree in Software Engineering, Information Technology, or related fields.\n- Certifications in Software Engineering, IT Operations, or relevant areas are a plus.\n\nExperience & Skills:\n- Hands-on experience in system operations and synchronization management.\n- Strong understanding and practical skills in cloud infrastructure (e.g., Kubernetes, Helm, Docker).\n- Familiarity with monitoring and logging systems (e.g., PLG stack).\n- Experience with DevOps tools such as Git, Jenkins.\n- Proficiency in working with databases, especially PostgreSQL.\n- Programming knowledge in Java (Spring Framework, Spring Boot, Spring Security), Node.js, and Vue.js.\n- Experience with application log analysis and issue diagnosis.\n- Understanding of Linux-based environments.\n- Familiarity with authentication and authorization protocols such as OAuth2 and OIDC.\n- Knowledge of message queue systems, particularly RabbitMQ.\n\nPreferred Skills:\n- Ability to collaborate effectively in a bilingual (English/Korean) environment.\n- Experience working in cross-functional teams across regions.\n- Proactive mindset and strong problem-solving skills.\n\nBenefits:\n- Salary: Negotiate.\n- Package: At least 13 months/ year. Review periodically following company policy.\n- Bonus: Tet bonus, project bonus, holiday bonus, HR referral bonus...\n- Seniority allowance (working time from 2 years or more).\n- Participate in learning and training activities inside and outside the company, accumulate learning points, develop G-Points on the company\'s management system.\n- 2 days of per week and 12 leave days per year.\n- Clubs and many cultural - sports - art activities sponsored or supported by the company (For example: Football, table tennis, badminton, swimming, music, English, games... ).\n- Ensure health: Periodic health check, support to buy high quality health insurance...\n- Join the Rikkei Care Health Insurance Plan.\n- Mental comfort: Playing music on demand every day, happy hour, team building activities...\n\nWork Location:\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy.\n\nWorking Time:\n- Monday - Friday (from 08:00 to 17:00).\n- Flexible registration from 8:00 - 9:00 to 17:00 - 18:00 from Monday to Friday.\n\nHow to Apply:\n- Candidates apply online by clicking "Ứng tuyển" below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3033, 1187, 2, 'Senior Backend Developer', 'Mô tả công việc\n- Phát triển và duy trì các ứng dụng web fullstack, sử dụng Java hoặc Python cho backend.\n- Thiết kế, xây dựng và tích hợp RESTful API để giao tiếp giữa các dịch vụ.\n- Xây dựng giao diện người dùng tương tác tốt với các frontend framework như ReactJS, Angular hoặc VueJS.\n- Quản lý cơ sở dữ liệu quan hệ và/hoặc NoSQL như: MySQL, PostgreSQL, MongoDB, Redis.\n- Đóng gói ứng dụng bằng Docker để đảm bảo môi trường phát triển và triển khai nhất quán.\n- Thiết lập và giám sát hệ thống với các công cụ logging & alerting hiện đại.\n- Làm việc theo mô hình Agile/Scrum, sử dụng các công cụ quản lý như JIRA.\n- Phối hợp chặt chẽ với các team BA, QA, DevOps, khách hàng để đảm bảo chất lượng và tiến độ dự án.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành Công nghệ thông tin hoặc lĩnh vực liên quan.\n- Từ 5 năm kinh nghiệm lập trình, trong đó thời gian gần nhất có kinh nghiệm làm việc với Java, Python.\n- Có kinh nghiệm làm việc với Javascript\n- Có kiến thức vững với: RESTful API, microservices, authentication/authorization.\n- Kinh nghiệm làm việc với cơ sở dữ liệu quan hệ và/hoặc NoSQL.\n- Thành thạo Git, viết unit test, triển khai bằng CI/CD pipelines.\n- Kỹ năng giao tiếp và làm việc nhóm tốt.\nĐIỂM CỘNG / ƯU TIÊN\n- Có kinh nghiệm làm việc với dự án outsource, đặc biệt là khách hàng Hàn Quốc.\n- Chủ động, tinh thần trách nhiệm cao.\n- Ưu tiên ứng viên có khả năng giao tiếp tiếng Anh cơ bản trở lên.\n\nQuyền lợi\n1. Thu nhập hấp dẫn:\n- Tối thiểu 13 tháng lương/năm.\n- Đánh giá tăng lương 2 lần/năm.\n- Thưởng hiệu quả công việc hàng tháng, thưởng dự án, thưởng ngày lễ, thưởng Tết,…\n- Phụ cấp thâm niên tối thiểu 6tr/năm.\n- Trợ cấp thai sản cho nhân viên nữ ngoài bảo hiểm xã hội.\n\n2. Chăm sóc sức khỏe:\n- Khám sức khỏe định kỳ hằng năm tại các trung tâm y tế chất lượng cao.\n- Chương trình bảo hiểm sức khỏe toàn diện Rikkei Care.\n\n3. Phát triển sự nghiệp:\n- Tham gia các chương trình đào tạo được tổ chức thường xuyên bởi các chuyên gia trong và ngoài nước.\n- Công ty tài trợ chi phí thi các chứng chỉ quốc tế.\n- Thưởng thành tích khi đạt các chứng chỉ ngoại ngữ.\n- Cơ hội làm việc tại Nhật, Mỹ, Hàn và nhiều quốc gia khác trên thế giới,…\n\n4. Môi trường năng động, tích cực:\n- Thời gian làm việc linh động, nghỉ thứ 7 + chủ nhật hàng tuần.\n- 12 ngày phép/năm + 1 ngày nghỉ du lịch.\n- Chế độ team building hàng quý, du lịch hàng năm.\n- Tham gia các giải đấu thể thao indoor, outdoor, e-sport,…\n- Tham gia các Câu lạc bộ bóng đá, bóng bàn, cầu lông, bơi lội, âm nhạc, tiếng Anh,…\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Vinacomin Dương Đình Nghệ, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n- Đăng ký linh hoạt 8:00 - 9:00 đến 17:00 - 18:00 từ Thứ 2 - Thứ 6.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3034, 1238, 2, 'Nhân Viên Software Developer (Dev)', 'Mô tả công việc\n1. Phát triển Backend:\n- Thiết kế, phát triển và duy trì các dịch vụ phụ trợ bằng Laravel và ecosystem của Laravel.\n- Tối ưu hóa truy vấn cơ sở dữ liệu để đảm bảo hiệu suất và khả năng mở rộng của hệ thống.\n- Triển khai và duy trì API RESTful cho giao diện người dùng và tích hợp của bên thứ ba.\n- Đảm bảo các biện pháp bảo mật tốt nhất được tuân thủ trong hoạt động API và cơ sở dữ liệu.\n\n2. Phát triển Frontend:\n- Xây dựng và duy trì các tính năng hướng tới người dùng bằng VueJS (Vue 3).\n- Làm việc chặt chẽ với các nhà thiết kế UI/UX để tạo ra các thành phần giao diện có thể tái sử dụng và mở rộng quy mô.\n\n3. Các công việc khác:\n- Làm việc chặt chẽ với nhóm nghiệp vụ để chuyển đổi các yêu cầu thành các giải pháp kỹ thuật.\n- Viết code sạch, hiệu quả và dễ bảo trì theo các chuẩn ISO đưa ra.\n- Thực hiện đánh giá mã và đóng góp vào việc cải thiện quy trình phát triển.\n- Cập nhật những xu hướng mới nhất về Laravel, VueJS và các công nghệ liên quan.\n\nYêu cầu ứng viên\n- Trình độ chuyên môn: Tốt nghiệp đại học trở lên\n- Có ít nhất 2 năm kinh nghiệm làm việc với Laravel, VueJs trong môi trường sản xuất.\n- Kinh nghiệm với VueJS (Vue 2 hoặc Vue 3), bao gồm phát triển dựa trên thành phần.\n- Thành thạo MySQL/PostgreSQL, bao gồm tối ưu hóa truy vấn và thiết kế cơ sở dữ liệu.\n- Kinh nghiệm xây dựng và tích hợp API RESTful.\n- Quen thuộc với Git và làm việc trong môi trường phát triển cộng tác.\n- Bằng Cử nhân (hoặc cao hơn) chuyên ngành CNTT hoặc các lĩnh vực liên quan, ưu tiên ứng viên đến từ các trường đại học hàng đầu.\n\nQuyền lợi\n- Tiền lương: thoả thuận khi phỏng vấn\n- Phụ cấp ăn trưa\n- Được làm việc trong môi trường năng động, hiện đại.\n- Tạo điều kiện học hỏi và nâng cao khả năng chuyên môn.\n- Được hưởng các chế độ BHXH, BHYT, BHTN, tham quan, nghỉ phép, thưởng năng suất, nghỉ các ngày lễ theo quy định của Luật lao động hiện hành.\n\nĐịa điểm làm việc\n- Hà Nội: Bệnh viện Đa Khoa Phương Đông, Số 9, Phố Viên, Cổ Nhuế 2, Bắc Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3035, 1303, 2, 'Fresher .NET/JS/CSS', 'Mô tả công việc:\nTham gia nghiên cứu, phát triển sản phẩm phần mềm trong lĩnh vực Ngân hàng và Tài chính: Digital Banking\n- Tìm hiểu tài liệu: Nghiệp vụ, yêu cầu và thiết kế của dự án tham gia;\n- Code các chức năng, module được phân công;\n- Phối hợp với team Test để kiểm tra lỗi, fix bug và hoàn thiện chức năng, sản phẩm;\n- Hỗ trợ khách hàng sau triển khai: Tiếp nhận yêu cầu, kiểm tra lỗi, sửa lỗi dữ liệu, sửa lỗi phát sinh trong quá trình khách hàng vận hành và sử dụng sản phẩm;\nCác công việc khác theo phân công để đảm bảo cùng team hoàn thành dự án, công việc được giao.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, lập trình phần mềm.\n- Không yêu cầu kinh nghiệm, sinh viên mới tốt nghiệp được khuyến khích ứng tuyển. Ưu tiên ứng viên đã có kinh nghiệm thực tập.\n- Có kiến thức tổng quan về quy trình phát triển phần mềm và triển khai phần mềm. Tư duy lập trình hướng đối tượng.\n- Thành thạo ít nhất một ngôn ngữ lập trình backend về .Net/JS/CSS\n- Có kiến thức cơ bản về cơ sở dữ liệu quan hệ SQL Server.\n- Hiểu biết về các hệ thống quản lý Jira, Microsoft Teams\n- Khả năng làm việc độc lập và làm việc nhóm tốt.\n- Có khả năng học hỏi nhanh và thích ứng với công nghệ mới.\n- Kỹ năng giải quyết vấn đề và tư duy logic tốt.\n- Thành thạo đọc hiểu và viết tài liệu tiếng Anh chuyên ngành.\n\nQuyền lợi:\n- Mức lương cạnh tranh và hấp dẫn, tùy thuộc vào kinh nghiệm và năng lực.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Được đào tạo và phát triển chuyên môn thường xuyên.\n- Cơ hội thăng tiến và phát triển nghề nghiệp rõ ràng.\n- Các chế độ phúc lợi đầy đủ theo luật lao động (BHXH, BHYT, BHTN).\n- Tham gia các hoạt động team building, nghỉ mát hàng năm.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 3 - AB - Imperia Garden, 203 Nguyễn Huy Tưởng, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3036, 165, 2, 'Lập Trình Viên .Net - Senior', 'Tham gia phát triển sản phẩm phần mềm quản lý bán hàng Kiotviet;\nPhối hợp các phòng ban khác trong phân tích nghiệp vụ, phát triển và triển khai sản phẩm;\nXây dựng chức năng của sản phẩm cho hệ thống tầm 300K người sử dụng;\nGiải quyết các vấn đề khó về tối ưu hệ thống cũng như nghiệp vụ người dùng;\nNghiên cứu các giải pháp, công nghệ mới để cải tiến sản phẩm;\nTối ưu hóa hiệu suất hệ thống và xử lý các vấn đề kỹ thuật phức tạp;\nTham gia vào quá trình code review và mentoring các thành viên có level thấp hơn trong team;\nThực hiện các công việc liên quan khác được giao.\n\nYêu cầu ứng viên\nHọc vấn, kiến thức và trình độ chuyên môn:\nTốt nghiệp đại học chuyên ngành CNTT.\nKinh nghiệm:\nCó ít nhất 3 năm kinh nghiệm ở vị trí tương đương là lợi thế;\nNhững kỹ năng cần thiết cho công việc;\nYêu cầu kỹ thuật:\nCó ít nhất 3 năm kinh nghiệm phát triển phần mềm sử dụng công nghệ .NET, NET Core;\nThành thạo C#, .NET Core, ASP.NET và các framework liên quan;\nKinh nghiệm làm việc với các ORM như Entity Framework, Entity Framework Core, Dapper;\nHiểu biết sâu về RESTful API và kiến trúc microservices;\nKinh nghiệm làm việc với cơ sở dữ liệu MSSQL và MongoDB;\nKinh nghiệm với hệ thống messaging như RabbitMQ, Kafka;\nHiểu biết về caching (Redis) và công nghệ realtime (MQTT, Websocket)\nThực hành tốt về Coding Principles, Clean Code, Design Patterns và Unit Testing;\nCó kinh nghiệm làm việc với hệ thống có tải cao là một lợi thế;\nCó các kỹ năng debugging và troubleshooting: phân tích giải quyết các vấn đề kỹ thuật;\nCó kinh nghiệm sử dụng các công cụ monitoring và logging như Grafana, ELK, APM, OpenTelemetry;\nKỹ năng mềm:\nKhả năng học hỏi nhanh và tư duy giải quyết vấn đề tốt;\nKỹ năng làm việc nhóm và giao tiếp hiệu quả;\nChủ động, có trách nhiệm và khả năng làm việc độc lập;\nKỹ năng quản lý thời gian và ưu tiên công việc hiệu quả;\nKhả năng mentoring và hướng dẫn các thành viên level thấp hơn;\nQuan hệ công việc (Bên trong công ty, bên ngoài công ty).\n\nQuyền lợi\nMức lương khởi điểm đứng đầu thị trường, tương xứng với năng lực và kinh nghiệm làm việc;\nThưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm;\nLàm việc từ Thứ 2 – Thứ 6, giờ làm việc linh hoạt;\nĐược hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\nThưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\nChăm sóc sức khỏe: Khám sức khỏe định kỳ hàng năm, Bảo hiểm sức khỏe cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\nLàm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\nĐược cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\nCơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 18:30)\nGiờ check in checkout link hoạt từ 8:00-9:00 đến 17:30-18:30\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3037, 1223, 2, 'Senior Developer - Team Lead', 'Chúng tôi đang tìm kiếm Senior Developer giàu kinh nghiệm để tham gia vào đội ngũ phát triển của TechPlus. Vị trí này sẽ chịu trách nhiệm nghiên cứu, thiết kế và phát triển các hệ thống công nghệ cho lĩnh vực Tài chính – Ngân hàng, bao gồm Core Banking, Virtual Account Management (VAM) và các nền tảng tài chính số.\n\nBạn sẽ làm việc chặt chẽ với Product Owner, Business Analyst, và các nhóm liên quan để xây dựng ý tưởng, thiết kế giải pháp và triển khai các sản phẩm/dự án. Đồng thời, bạn sẽ chịu trách nhiệm duy trì tài liệu kỹ thuật, hỗ trợ đào tạo và hướng dẫn người dùng khi cần thiết.\n\nBên cạnh vai trò phát triển phần mềm, bạn cũng sẽ tham gia vào việc bảo trì, nâng cấp hệ thống, tối ưu hiệu suất, cải thiện quy trình phát triển, đảm bảo chất lượng sản phẩm/dự án, và hỗ trợ các nhóm khác trong quá trình triển khai.\n\nCụ thể:\n- Tham gia nghiên cứu, thiết kế, xây dựng, phát triển và triển khai hệ thống Công nghệ Thông tin cho Tài chính, Ngân hàng.\n- Tham gia xây dựng ý tưởng, tham gia thiết kế sản phẩm, giải pháp.\n- Xây dựng tài liệu kỹ thuật sản phẩm, dự án.\n- Tham gia xây dựng tài liệu đào tạo, tham gia đào tạo và hỗ trợ người sử dụng.\n- Bảo trì, nâng cấp hệ thống cho sản phẩm, dự án.\n- Hợp tác với các bộ phận khác trong quá trình thực hiện dự án.\n- Tham gia cải tiến quy trình phát triển sản phẩm, dự án.\n- Các công việc phát sinh khác theo yêu cầu kỹ thuật dự án.\n- Báo cáo kết quả công việc, thời gian làm việc phù hợp với quy định Công ty.\n\nYêu cầu ứng viên:\n- Chuyên ngành đào tạo: Tốt nghiệp Đại học chuyên ngành CNTT hoặc tương đương.\n- Kinh nghiệm làm việc:\n  - Từ 03 - 08 năm kinh nghiệm xây dựng và phát triển dự án trong lĩnh vực CNTT.\n  - Đã tham gia xây dựng, phát triển, triển khai các giải pháp liên quan trong lĩnh vực CNTT cho ngành Tài chính, Ngân hàng là một lợi thế.\n- Kiến thức chuyên môn và kỹ thuật:\n  - Kinh nghiệm thiết kế hệ thống, thiết kế cơ sở dữ liệu, Design Pattern.\n  - Kinh nghiệm lập trình ứng dụng với .Net Framework, Java và các ngôn ngữ lập trình phổ dụng khác.\n  - Kinh nghiệm làm việc với một trong các hệ thống CSDL như: Oracle, MS SQL Server, MySQL, PostgreSQL …\n  - Kinh nghiệm xây dựng các ứng dụng trên nền tảng Cloud Native / kiến trúc Microservice.\n  - Kinh nghiệm triển khai các ứng dụng trên Container / Docker cho môi trường Windows & Linux.\n  - Kinh nghiệm và hiểu biết về các yêu cầu bảo mật trên môi trường Cloud.\n  - Quen thuộc với Continuous Integration / Continuous Deployment.\n  - Tiếng Anh giao tiếp, đọc hiểu tốt.\n  - Khả năng làm việc độc lập và chịu áp lực trong môi trường nhịp độ cao.\n  - Kỹ năng phân tích, phản biện, tư duy logic và giải quyết vấn đề tốt.\n\nQuyền lợi:\nMôi trường làm việc:\n- Đội ngũ trẻ trung, năng động, luôn khuyến khích sáng tạo.\n- Văn phòng hiện đại, đầy đủ tiện nghi.\n- Cơ hội tham gia vào các dự án công nghệ tài chính lớn, có tầm ảnh hưởng lên tới hàng chục triệu người dùng.\n- Cơ hội phát triển bản thân thông qua các buổi đào tạo và workshop định kỳ.\n- Được trực tiếp đào tạo về các kỹ năng Marketing, thị trường và sản phẩm bởi các chuyên gia trong ngành.\n\nPhúc lợi và chế độ đãi ngộ:\n- Thu nhập và Phụ cấp: cạnh tranh với thị trường ở vị trí công việc.\n- Được cung cấp thiết bị phục vụ công việc theo chính sách của Công ty.\n- Đóng BHXH đầy đủ theo quy định nhà nước.\n- Quyền lợi Bảo hiểm sức khỏe tự nguyện (PVI Care hoặc tương đương) theo chính sách của Công ty.\n- Thưởng các ngày lễ tết: Theo quy định chung của Công ty.\n- Chế độ tăng lương hấp dẫn: thù lao và thưởng cho nhân viên dựa trên hiệu suất làm việc và đóng góp cá nhân. Được xem xét ngay khi bạn là một nhân viên xuất sắc mà không cần chờ tới đánh giá định kỳ.\n- Nghỉ phép: 12 ngày/ năm và phép thâm niên.\n- Chế độ du lịch: 1 năm /1 lần, chương trình teambuilding được tổ chức thường niên.\n- Các chế độ khác: theo Luật Lao động Việt Nam – theo Nội quy lao động và Quy định tài chính của Công ty.\n\nĐịa điểm làm việc:\n- Hà Nội: 74 Khúc Thừa Dụ, Dịch Vọng, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3038, 1358, 2, 'Backend Developer (AWS)', 'Mô tả công việc:\n- Develop and maintain high-performance backend systems and APIs using modern technologies such as serverless architectures, microservices, and containerization.\n- Design and implement server-side logic, database schemas, and integrations with third-party services to support scalable and efficient applications.\n- Deploy, monitor, and optimize backend services on AWS cloud infrastructure, ensuring high availability, performance, and cost-efficiency.\n- Collaborate closely with front-end engineers, DevOps, and product owners to deliver seamless, scalable solutions and align with business goals.\n- Ensure adherence to best practices in coding, security, performance, and scalability, including secure coding practices and data encryption.\n- Participate in technical discussions, code reviews, and agile development activities to foster continuous improvement and knowledge sharing.\n- Troubleshoot and resolve issues in production and development environments promptly and effectively to minimize downtime.\n- Stay current with emerging backend technologies and trends, such as AI integration, edge computing, and new programming languages, to drive innovation.\n\nYêu cầu ứng viên:\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- At least 3 years of experience as a Software Engineer, with a focus on Data Engineering or Cloud Computing.\n- Proficient in programming languages such as Python and Node.js.\n- Hands-on experience with AWS services including but not limited to: Amazon S3, DynamoDB, Lambda, Glue, Kinesis, SQS, Serverless Stack, Cloud Observation Tools, Step Functions, RDS, and Data Lake.\n- Solid understanding of ETL processes and database design.\n- Experience with serverless architecture and managed services to ensure high availability and fault tolerance.\n- Strong knowledge of cloud security best practices, including IAM policies, VPC endpoints, and data encryption.\n- Familiarity with CI/CD pipelines and proficient in Infrastructure as Code (IaC) tools such as AWS CDK or Terraform.\n- Excellent problem-solving skills and attention to detail.\n- Strong communication and collaboration skills.\n- Ability to design and troubleshoot distributed systems.\n- Experience with Customer Data Platforms (CDPs) or similar technologies.\n- AWS certifications (e.g., AWS Certified Solutions Architect, AWS Certified Data Analytics – Specialty).\n\nQuyền lợi:\n- Attractive salary, commensurate with capacity.\n- 13th month salary bonus, achievement bonus: 14-15 months, monthly/quarterly/yearly business bonus, Tet holiday bonus.\n- Rice allowance and other allowances (according to the nature of the job).\n- Annual health check-ups.\n- Social insurance; 24/24 accident insurance.\n- Leave regime for employees from 12-14 days/year.\n- Training and career development programs.\n- Professional working environment.\n- Collective activities: Team Building, Family Festival, Arts, Sports Club, Vacation...\n- Community activities: Gifts on the occasion of 8/3, 20/10, International Children\'s Day 1/6, Mid-Autumn Festival.....\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 170E Phan Đăng Lưu, Phú Nhuận\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3039, 1285, 2, 'Giảng Viên', 'Mô tả công việc\n- Giảng dạy các môn học thuộc chuyên ngành CNTT và Ứng dụng phần mềm (Các môn học về lập trình: Java, C, C#, Javascript, PHP, Python, Android,…; các nền tảng: NodeJS, ReactJS, Angular, Laravel, Unity 2D, Spring MVC, Spring Boot,... và các môn Tin học cơ bản: CSDL, Quản trị website, Cài đặt và bảo trì phần mềm/cứng, Thiết lập và quản trị hệ thống mạng, Quản trị server,...)\n- Tham gia các hoạt động phát triển chuyên môn, xây dựng chương trình học, hướng dẫn đồ án tốt nghiệp, coi thi, chấm thi,...\n- Phối hợp tổ chức các hoạt động ngoại khóa cho sinh viên bộ môn (Workshop, Seminar, Talkshow,...)\n- Thực hiện các công việc liên quan khác theo phân công của Bộ môn\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học trở lên các chuyên ngành thuộc khối Công nghệ thông tin (Khoa học máy tính, Kĩ thuật phần mềm, Hệ thống thông tin, Điện tử - Viễn thông,...)\n- Có kiến thức chuyên môn tốt, am hiểu hoặc thông thạo một trong những lĩnh vực sau: Ngôn ngữ lập trình (Java, C#, Javascript, PHP, Python, HTML CSS, Android,…); các nền tảng (NodeJS, ReactJS, Angular, Laravel,...); CSDL (các hệ quản trị CSDL) hoặc quản trị hệ thống mạng (kiến trúc mạng, windows server, tường lửa, bảo mật,...)\n- Ưu tiên ứng viên có kinh nghiệm làm việc trong dự án thực tế hoặc từng tham gia giảng dạy về CNTT\n- Ưu tiên ứng viên có kĩ năng sư phạm, tư duy sáng tạo, cởi mở\n- Ưu tiên ứng viên có chứng chỉ nghiệp vụ sư phạm hoặc có kinh nghiệm về lập trình hoặc triển khai các các dự án CNTT\n\nQuyền lợi\n- Môi trường làm việc năng động, chuyên nghiệp\n- Có mức thu nhập hấp dẫn\n- Có cơ hội tham gia các lớp học, hoạt động đào tạo nâng cao trình độ\n\nĐịa điểm làm việc\n- Bà Rịa-Vũng Tàu: FPT PolySchool - 762 Cách Mạng Tháng 8, Phường Long Toàn, TP Bà Rịa\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bà Rịa-Vũng Tàu', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3040, 1298, 2, 'React Native Developer', 'Mô tả công việc\n- Phát triển ứng dụng di động sử dụng React Native và các công nghệ JavaScript liên quan.\n- Đảm bảo ứng dụng có hiệu năng cao, bảo mật và mang lại trải nghiệm người dùng tốt.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học ngành CNTT, Toán tin, Điện tử viễn thông hoặc tương đương.\n- Kinh nghiệm với ReactJS, HTML/CSS, HTML5/CSS3, SASS, SCSS, Bootstrap, jQuery, Thymeleaf.\n- Kinh nghiệm xử lý Session, Token, Cache trình duyệt.\n- Kinh nghiệm làm việc với Rest API.\n- Kinh nghiệm sử dụng Git.\n- Kinh nghiệm xử lý lập trình an toàn.\n- Kinh nghiệm làm việc FrontEnd (Angular) hoặc BackEnd (Java, NodeJS).\n- Thành thạo các framework JavaScript: ReactJS, Angular 2+, VueJS.\n- Kinh nghiệm tối ưu, xử lý truy vấn dữ liệu lớn, sử dụng các công nghệ caching.\n- Tối thiểu 3 năm kinh nghiệm trong lĩnh vực phát triển ứng dụng, hệ thống CNTT.\n- Tối thiểu 3 năm kinh nghiệm phát triển dự án trên nền tảng BPM.\n- Kinh nghiệm làm Team Lead và quản lý đội nhóm Software Engineer cho ít nhất 1 dự án.\n- Hiểu biết về Cloud.\n- Khả năng lập trình BackEnd bằng Java, Spring Boot, Struts.\n- Kinh nghiệm phát triển ứng dụng đa nền tảng (iOS, Android) sử dụng React Native.\n- Hiểu biết về quy trình phát hành ứng dụng lên App Store và Google Play.\n\nQuyền lợi\n- Lương: 20.000.000 - 40.000.000\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30.\n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Làm việc onsite tại ngân hàng số 1 Việt Nam, trực tiếp tham gia vào các dự án tiên phong về chuyển đổi số.\n- Nghỉ phép: 12 ngày/năm.\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN cho 100% cán bộ sau thời gian thử việc.\n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Thu nhập: lương tháng 13; thưởng theo dự án, thưởng theo kết quả kinh doanh và mức độ đóng góp; thưởng theo năng lực và mức độ hoàn thành công việc của từng thành viên – đánh giá hàng tháng và trả thưởng theo quý; thưởng các ngày lễ lớn.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n- Các hoạt động giao lưu bóng đá, golf, văn nghệ...\n- Chính sách đào tạo về chuyên môn, nghiệp vụ và kỹ năng cho nhân viên. Hỗ trợ 100% kinh phí học và thi các chứng chỉ chuyên môn.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3041, 1119, 2, 'Senior BackEnd (Spring Boot)', 'Mô tả công việc\n- Phát triển và duy trì các ứng dụng Java sử dụng Spring Boot:\n  + Thiết kế, phát triển và duy trì các hệ thống ứng dụng web và dịch vụ backend sử dụng Java và Spring Boot phục vụ cho các giao dịch chứng khoán, quản lý tài khoản và các công cụ hỗ trợ khác.\n  + Lập trình các chức năng liên quan đến giao dịch, xử lý dữ liệu tài chính, báo cáo và các dịch vụ khác trong môi trường chứng khoán.\n  + Đảm bảo các ứng dụng hoạt động ổn định, hiệu suất cao và bảo mật.\n- Tích hợp và phát triển API:\n  + Thiết kế và phát triển các API RESTful sử dụng Spring Boot để kết nối các hệ thống giao dịch, ứng dụng web và cơ sở dữ liệu.\n  + Tích hợp các hệ thống bên ngoài (ví dụ: API của các sàn chứng khoán, ngân hàng) vào hệ thống công ty, đảm bảo tính chính xác và bảo mật khi truyền nhận dữ liệu.\n- Quản lý cơ sở dữ liệu:\n  + Thiết kế và tối ưu hóa các câu lệnh SQL, thao tác với cơ sở dữ liệu quan hệ (MySQL, PostgreSQL, Oracle v.v.) hoặc NoSQL (MongoDB, Cassandra) để lưu trữ và truy xuất dữ liệu hiệu quả.\n  + Thực hiện các nghiệp vụ quản lý giao dịch chứng khoán và dữ liệu tài khoản, đảm bảo tính nhất quán và an toàn của dữ liệu.\n- Kiểm thử và đảm bảo chất lượng phần mềm:\n  + Thực hiện kiểm thử unit, tích hợp và đảm bảo chất lượng mã nguồn phần mềm.\n  + Phối hợp với nhóm kiểm thử để đảm bảo phần mềm được kiểm tra kỹ lưỡng trước khi triển khai.\n- Tối ưu hóa hiệu suất và bảo mật:\n  + Tối ưu hóa hiệu suất hệ thống để xử lý lượng giao dịch lớn trong môi trường chứng khoán.\n  + Áp dụng các biện pháp bảo mật, mã hóa và các kỹ thuật bảo vệ dữ liệu nhằm đảm bảo hệ thống và giao dịch an toàn.\n- Cập nhật và duy trì tài liệu kỹ thuật:\n  + Cập nhật và duy trì tài liệu kỹ thuật cho các ứng dụng và API phát triển.\n  + Đảm bảo các tài liệu dễ hiểu và có thể được sử dụng lại cho các dự án sau.\n- Tham gia vào quá trình phát triển phần mềm:\n  + Tham gia vào các cuộc họp Scrum, giúp giải quyết các vấn đề kỹ thuật và tham gia vào quá trình lên kế hoạch và thiết kế hệ thống.\n  + Cập nhật tiến độ công việc và báo cáo cho các bên liên quan theo yêu cầu.\n\nYêu cầu ứng viên\n- Trình độ học vấn: Tốt nghiệp Đại học trở lên, chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan.\n- Kinh nghiệm:\n  + Ít nhất 3 năm kinh nghiệm phát triển phần mềm với Java, đặc biệt là với Spring Boot.\n  + Kinh nghiệm làm việc với các ứng dụng web và dịch vụ backend trong môi trường chứng khoán, tài chính hoặc ngân hàng là một lợi thế.\n  + Kinh nghiệm với các công cụ quản lý mã nguồn (Git, GitHub, Bitbucket, v.v.).\n  + Kinh nghiệm làm việc với cơ sở dữ liệu SQL (MySQL, PostgreSQL) và NoSQL (MongoDB, Cassandra).\n  + Kinh nghiệm làm việc với các công cụ CI/CD (Jenkins, GitLab CI, v.v.) và containerization (Docker, Kubernetes) là một lợi thế.\n- Kiến thức:\n  + Kiến thức vững về Java, Spring Boot, Spring Security, Hibernate, và các công nghệ liên quan.\n  + Hiểu biết về các nguyên lý thiết kế phần mềm, RESTful API, microservices và các công cụ liên quan.\n  + Hiểu biết về quy trình phát triển phần mềm Agile và Scrum.\n  + Kiến thức về ngành chứng khoán và các quy trình giao dịch chứng khoán sẽ là lợi thế.\n- Kỹ năng:\n  + Kỹ năng lập trình Java xuất sắc và khả năng viết mã sạch, dễ bảo trì.\n  + Kỹ năng phân tích và giải quyết vấn đề tốt, có khả năng tối ưu hóa mã và hệ thống.\n  + Kỹ năng giao tiếp và làm việc nhóm hiệu quả.\n  + Kỹ năng tư duy logic, phân tích và thiết kế hệ thống.\n\nQuyền lợi\n1. Mức lương và phụ cấp:\n  - Thỏa thuận theo năng lực và kinh nghiệm thực tế. Khung lương (25 - 35tr)\n  - Phụ cấp ăn trưa (40k/ngày công thực tế)\n  - Phụ cấp gửi xe (300k/tháng)\n  - Phụ cấp đi lại, xăng xe, điện thoại (tùy thuộc vào từng vị trí)\n\n2. Thưởng:\n  - Thưởng quý/năm (tùy theo tình hình kinh doanh của Công ty)\n  - Thưởng lễ tết, cuối năm\n  - Thưởng tháng lương 13 +++…\n\n3. Phúc lợi:\n  - Tham gia BHXH, BHSK\n  - Teambuildings, HappyFridays, du lịch nghỉ dưỡng\n\n4. Cơ hội thăng tiến:\n  - Được làm việc đúng chuyên môn/sở trường (làm chủ công việc). Hợp tác với cộng sự/quản lý nhiều kinh nghiệm trong lĩnh vực\n  - Được đào tạo trực tiếp nâng cao/bổ sung kiến thức ngành nghề\n  - Đánh giá năng lực, xét tăng lương/thưởng theo quy định của Công ty\n\n5. Môi trường làm việc:\n  - Năng động/ trẻ trung và nhiệt huyết\n  - Định hướng làm việc hybrid\n  - Được trang bị các trang thiết bị/công cụ phù hợp với từng vị trí công việc\n  - Làm việc từ thứ 2 đến thứ 6 (nghỉ thứ 7 và chủ nhật)\n\nĐịa điểm làm việc\n- Hà Nội: 17 Tông Đản, Hoàn Kiếm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3042, 1333, 2, 'Oracle Developer', 'Mô tả công việc\n- Tiếp nhận yêu cầu phát triển từ BA, các đơn vị nghiệp vụ thuộc mảng đơn vị phụ trách, từ các đội nhóm phát triển khác, đánh giá, lên kế hoạch phát triển trên các hệ thống của đơn vị phụ trách (Oracle, OFSAA, CostPerform, Payroll,...) tích hợp dữ liệu, báo cáo, dashboard và thực thi quy hoạch, thiết kế và phát triển;\n- Phát triển tích hợp dữ liệu, báo cáo, Dashboard sử dụng các giải pháp dữ liệu trên các công cụ như: ETL Pentaho, ODI, Oracle BI, Tableau,...;\n- Hỗ trợ xử lý các vấn đề kỹ thuật phát sinh trong quá trình vận hành các hệ thống, dịch vụ\n- Tham gia vào các công đoạn: kiến trúc hệ thống, thiết kế chức năng, lập trình, unit test, viết tài liệu chức năng, tối ưu performance...\n- Lập trình hệ thống các ứng dụng trên nền SQL/PLSQL, Java  và các hệ thống Middleware trên nền tảng của Oracle hay java\n- Tối ưu performance các xử lý giải thuật\n- Tham gia tìm hiểu các công nghệ, kỹ thuật mới.\n\nYêu cầu ứng viên\n- Kiến thức:\n - Tốt nghiệp Đại học trở lên chuyên ngành CNTT hoặc các ngành tương đương hoặc có các chứng chỉ tương đương được công nhận bởi các tổ chức uy tín\n\n- Kinh nghiệm:\n- Có trên 2 năm kinh nghiệm làm Oracle\n- Thành thạo một trong các ngôn ngữ lập trình: SQL/PLSQL, NoSQL, Java, Python\n- Tư duy/khả năng lập trình tốt và có kỹ năng phân tích hệ thống\n- Có khả năng phát triển trên ít nhất 1 công cụ ETL hoặc báo cáo (Pentaho, ODI, GG, Oracle BI, Tableau,...)\n- Có khả năng phát triển ít nhất trên 1 trong các nền tảng: Oracle, OFSAA, Apex, Java Spring, Apache Nifi Air Flow,...\n- Nắm rõ các quy chuẩn về quy trình xây dựng và triển khai một phần mềm\n- Ưu tiên:\n + Có kiến thức làm việc với các công cụ ETL; Công cụ báo cáo BI: Oracle BI, Tableau...;\n + Có hiểu biết phương pháp làm việc như Agile, phương pháp luận triển khai AIM, CDM trên các nền tảng Oracle\n + Có kinh nghiệm phát triển, nền tảng kiến trúc OFSAA tối thiểu 2 năm (đặc biệt các module: AML, Fraud, ALM, ICAAP)\n + Có hiểu biết về lĩnh vực ngân hàng\n + Đã triển khai và phát triển các ứng dụng, mô hình xử lý dữ liệu trong hệ sinh thái dữ liệu lớn (Big Data)\n + Ứng viên có kinh nghiệm về xử lý bất đồng bộ, xử lý đa nhiệm, và xử lý dữ liệu theo thời gian thực (near real time), data streaming trên các nền tảng Oracle, Kafka Streams,... phục vụ nhu cầu khai thác dữ liệu theo thời gian thực\n\n- Ngoại ngữ:\n- Có khả năng đọc viết tiếng Anh (cơ bản) nghe nói (nếu có thể).\n- Ưu tiên ứng viên có chứng chỉ Tiếng Anh quốc tế (TOEIC 450 trở lên hoặc tương đương)\n\n- Yêu cầu khác:\n- Kỹ năng giao tiếp và làm việc nhóm tốt\n- Sẵn sàng làm việc ngoài giờ hành chính\n- Tinh thần trách nhiệm\n- Trung thực, tin cậy, cẩn trọng\n\nQuyền lợi\n• Lương thỏa thuận theo năng lực\n• Tối thiểu 13 tháng lương/năm.\n• Thử việc nhận 100% lương\n• Xét tăng lương 1- 2 lần/năm.\n• Thưởng: Thưởng Tết, thưởng giới thiệu nhân sự...\n• Văn phòng làm việc chuyên nghiệp hạng A.\n• Môi trường làm việc thân thiện và có tính tương hỗ cao, ổn định lâu dài.\n• Có nhiều cơ hội được đào tạo, làm việc nâng cao trình độ và cơ hội thăng tiến.\n• Có nhiều hoạt động bổ trợ tinh thần, du lịch...\n• Có cơ hội làm việc tại nước ngoài.\n\nĐịa điểm làm việc\n- Hà Nội: 18 Lê Văn Lương, Trung Hòa, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3043, 1455, 2, 'Kỹ Sư Lập Trình Khuôn', 'Mô tả công việc\n- Thiết kế và gia công khuôn cối, đồ gá trên máy gia công\n- Sửa chữa khuôn máy khi gặp sự cố\n- Phụ trách thiết kế sản phẩm khuôn mẫu đáp ứng kịp thời nhu cầu sản xuất\n- Quản lý bản vẽ khuôn mẫu, triển khai bản vẽ\n- Kiểm tra chất lượng sản phẩm khuôn mẫu\n- Lập các bản vẽ 2D, 3D cho sản phẩm mới\n- Sản xuất và đánh giá sản phẩm mẫu\n- Thiết kế khuôn mẫu và các chi tiết kỹ thuật\n- Sửa chữa bảo dưỡng duy trì hệ thống khuôn, đồ gá trong toàn nhà máy\n- Kiểm soát máy móc trang thiết bị theo bộ quy trình quản lý thiết bị\n- Thực hiện các công việc theo yêu cầu của người quản lý\n- Đào tạo, hướng dẫn kỹ thuật và vận hành khuôn cho các bộ phận liên quan.\n- Quản lý hồ sơ thiết bị khuôn mẫu, đồ gá\n- Các công việc khác theo sự phân công của trưởng phòng kỹ thuật.\nYêu cầu ứng viên\n- Tốt nghiệp chuyên ngành cơ khí, cơ điện tử\n- Kinh nghiệm: Trên 3 năm kinh nghiệm liên quan đến vị trí Kỹ thuật khuôn\n- Thành thạo AutoCad, phần mềm 3D (Solidwork or inventer)\n- Ưu tiên ứng viên có khả năng sử dụng và vận hành thành thạo các máy công cụ như khoan, bào, vận hành máy hàn và cắt gọt kim loại và vận hành cài đặt máy CNC...\n- Khả năng làm việc dưới áp lực cao\n- Tư duy logic tốt\n- Khả năng giao tiếp, đàm phán tốt\n- Ưu tiên ứng viên ở Hưng Yên\nQuyền lợi\n- Lương thỏa thuận theo năng lực từ 14-17 triệu/tháng chưa kể tăng ca\n- Đóng BHXH đầy đủ\n- Du xuân đầu năm, nghỉ mát hàng năm\n- Tổng thưởng Quý và thưởng Tết lên đến 3-4 tháng lương\nĐịa điểm làm việc\n- Hưng Yên: KCN Yên Mỹ 1, Tân Lập, Yên Mỹ, Yên Mỹ\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n- Nghỉ 01 thứ 7 và 04 chủ nhật\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hưng Yên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3044, 1463, 2, 'Senior Frontend Developer', 'Mô tả công việc:\n- Developing web-based applications (ReactJS, NextJs, Javascript pure- no library)\n- Develop and optimize front end UI to ensure the application is rendered consistently in cross-browser environments\n- Ensure UI/UX of developed pages and software with near pixel-perfect design;\n- Cooperate to connect front end software development with expert backend team\n- Solution consulting, designing, building to create optimal software products, in accordance with the needs of customers.\n- Work as assigned by the team leader / project manager, supporting team members to develop products.\n\nYêu cầu ứng viên:\n- Minimum 04 year experience working with React JS (Senior Level)\n- Proficient in JavaScript and deep understanding of how the browser works.\n- Build reusable components/modules for static websites with responsive design;\n- Excellent skills with HTML, CSS.\n- Friendly with bootstrap\n- Experience with: API, RESTFUL, JSON, XSS, CSRF, sync vs. async, promise2\n- Experience in debugging and optimizing code for application performance through the tools.\n- Teamwork skill\n\nQuyền lợi:\n- Our team members are awesome, fun, and most of all, super talented!\n- 13-month salary per year\n- Exposure to international design industry standards!\n- Bonus for birthday : 500K\n- Monthly company party.\n- Company trip.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tầng 3 Toà nhà RedHomes, B82 Bạch Đằng, Phường 2 Thành phố Hồ Chí Minh, Việt Nam, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3045, 1332, 2, 'Fullstack Developer (PHP/Reactjs)', '• Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng Nhật, Âu, Mỹ.\n• Hợp tác và trao đổi công việc với Team Member, Team Leader.\n• Xây dựng, tối ưu RESTful API, GraphQL, đảm bảo hiệu suất và khả năng mở rộng.\n• Phát triển frontend với React.js, tối ưu UI/UX, đảm bảo hiệu suất trên trình duyệt.\n• Quản lý và tối ưu cơ sở dữ liệu (MySQL, PostgreSQL, MongoDB).\n• Hỗ trợ, hướng dẫn các thành viên trong nhóm phát triển.\n\n• Có kiến thức nền tảng tốt về lập trình (OOP, cấu trúc dữ liệu và giải thuật…).\n• Có kiến thức nền tảng tốt về cơ sở dữ liệu quan hệ (thiết kế, sử dụng…).\n• Có kiến thức nền tảng tốt về hệ điều hành linux, cấu hình, triển khai web server.\n• Từ 3 năm kinh nghiệm lập trình sử dụng ngôn ngữ PHP trên các FrameWork như Laravel, Cake....\n• Từ 3 năm kinh nghiệm lập trình Frontend sử dụng HTML/CSS/Javascript, TypeScript trên các framework như Reactjs, Vuejs…\n• Có trên 1 năm lập trình trên môi trường cloud đặc biệt là AWS (Ec2, lambda…).\n• Có khả năng tìm hiểu, thích ứng tốt với công nghệ mới.\n• Có kinh nghiệm đảm nhiệm các vị trí project team leader là điểm cộng.\n• Nhiệt tình, teamwork tốt, sẵn sàng học hỏi các công nghệ mới để đáp ứng công việc.\n• Có tư duy hệ thống, tư duy logic tốt, có khả năng đề xuất vấn đề và giải quyết vấn đề.\n\n• Mức lương: thỏa thuận.\n• Được xây dựng lộ trình và hỗ trợ phát triển trở thành keymember, team leader.\n• Review lương hằng năm, lương tháng 13 theo hiệu quả kinh doanh của công ty.\n• Tham gia BHXH, BHYT, BHTN đầy đủ theo Luật lao động.\n• Nghỉ phép 12 ngày/năm.\n• Hưởng mọi quyền lợi nghỉ Lễ Tết kèm theo thưởng ngày Lễ/Tết trong năm.\n• Trợ cấp đối với nhân sự có thâm niên.\n• Team building định kỳ hàng Quý, du lịch 1 lần/năm.\n• Thời gian làm việc: 08:00 đến 17:00 từ Thứ Hai đến thứ Sáu.\n• Môi trường làm việc thoải mái, trẻ trung, năng động, có nhiều cơ hội thăng tiến và phát triển bản thân.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 6, số 12 Mễ Trì Hạ, phường Mễ Trì, Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3046, 1393, 2, 'Kỹ Sư Giải Pháp Phần Mềm Tích Hợp', 'Mô tả công việc:\n- Giới thiệu các giải pháp về phần mềm tích hợp như API Management, MQ, Event Streaming, ESB… với khách hàng chủ yếu trong lĩnh vực Tài chính, Ngân hàng.\n- Phối hợp cùng các bạn kỹ sư Amigo, hãng, đối tác thực hiện demo, PoC tính năng sản phẩm, làm thầu, triển khai các dự án về giải pháp phần mềm tích hợp.\n- Nghiên cứu các giải pháp, công nghệ theo định hướng của công ty.\n- Các công việc khác theo yêu cầu.\n\nYêu cầu ứng viên:\n- Tốt nghiệp ĐH chuyên ngành CNTT hoặc tương đương.\n- Có khả năng tư duy và giải quyết vấn đề độc lập.\n- Ham học hỏi, sẵn sàng nghiên cứu công nghệ mới.\n- Có mong muốn phát triển thành Solution Architecture trong tương lai.\n- Tiếng Anh giao tiếp cơ bản, đọc viết tốt.\n- Từ 1 năm kinh nghiệm làm việc trong lĩnh vực CNTT (kể từ khi tốt nghiệp).\n- Thành thạo ngôn ngữ lập trình Java và khả năng lập trình Restful API.\n- Có kiến thức cơ bản về Cơ sở dữ liệu quan hệ.\n- Ưu tiên: Có kinh nghiệm làm việc với các chuẩn giao thức kết nối Socket, Http, Jms, FTP; Có kiến thức chuyên sâu về Cơ sở dữ liệu quan hệ và NoSQL; Sử dụng thành thạo các công cụ test API như Postman; Có kinh nghiệm triển khai các dự án tích hợp sử dụng API hoặc Message Queue; Có kinh nghiệm triển khai về một trong các giải pháp tích hợp/middleware như WebSphere Application Server, WebSphere MQ, API Management, ESB, Kafka; Am hiểu về kiến trúc Microservice; Am hiểu về kiến trúc J2EE; Hiểu biết về các công cụ CI/CD; Hiểu biết về các nền tảng container Docker/Kubernetes (K8S) hoặc OpenShift.\n\nQuyền lợi:\n- Trở thành thành viên AMIGO bạn không chỉ được đảm bảo đầy đủ các chế độ phúc lợi BHXH, BHYT, BHTN, ngày nghỉ phép, lễ tết đầy đủ và trọn vẹn mà còn được hưởng chính sách Thu nhập và Đãi ngộ cạnh tranh trên thị trường, được làm việc trong môi trường chuyên nghiệp với những đồng nghiệp trẻ trung, nhiệt huyết, luôn đoàn kết, yêu thương và chia sẻ để mỗi ngày làm việc là một ngày hạnh phúc vì được cống hiến và phát triển.\n- Thu nhập tháng: Lương tháng + Thưởng KPI (20% lương tháng).\n- Gói thu nhập lên đến 17 tháng/năm. Đặc biệt đối với nhân viên Kinh doanh bạn còn có thêm Lương mềm theo Quý, Thưởng kinh doanh cuối năm.\n- Các hoạt động khen thưởng định kỳ (tháng/quý/chương trình/ thành tích đặc biệt) như: “Man of the month”, “Ngôi sao sáng tạo”, Nhân viên/ team/ bộ phận/ phòng ban xuất sắc; Thưởng khi hoàn thành các khóa đào tạo/chứng chỉ chuyên môn... theo quy chế của công ty.\n- Bảo hiểm sức khỏe toàn diện hàng năm.\n- Thưởng các dịp Lễ, Tết, Sinh nhật...\n- Chế độ nghỉ mát/ Innovation/ Teambuilding hàng năm.\n- Gói Khám sức khỏe định kỳ lên đến 2.500.000 VNĐ/người/năm.\n- Định hướng phát triển nghề nghiệp với chương trình đào tạo chuyên môn và hỗ trợ thi các chứng chỉ quốc tế.\n- Định hướng công việc để trở thành Solution Architecture hàng đầu trong lĩnh vực cung cấp và triển khai các giải pháp tích hợp cho các khách hàng trong lĩnh vực Ngân hàng-Tài chính.\n\nĐịa điểm làm việc:\n- Hà Nội: tầng 10, tòa nhà Indochina Plaza, số 241 Xuân Thủy, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3047, 1167, 2, 'Kỹ Sư Tự Động Hoá', 'I. Kiểm tra hiệu chỉnh, cải tiến máy móc thiết bị tự động hóa\n- Cài đặt, lập trình, hiệu chỉnh, hướng dẫn vận hành các máy móc tự động hóa.\n- Thiết kế, tính toán chọn các thiết bị cho hệ thống tự động hóa.\n- Lập trình PLC và thiết kế HMI cho các thiết bị, dây chuyền tự động hóa.\n- Lập trình máy tính PC, lập trình vision, robot cho các máy, dây chuyền tự động.\n- Lắp đặt biến tần, thiết bị, ứng dụng tự động hóa.\n- Đề xuất cải tiến áp dụng tự động hóa vào trong quá trình sản xuất.\n\nII. Quản lý quy trình công nghệ sản xuất, giảm giá thành sản phẩm\n- Thiết kế layout khu vực sản xuất, phù hợp với nhu cầu thực tế sản xuất sản phẩm\n- Đề xuất và/hoặc thực hiện các dự án giảm giá thành linh kiện.\n- Thiết kế quy trình công nghệ sản xuất, tiếp nhận chuyển giao thiết bị từ bên ngoài về Nhà máy.\n- Đề xuất đầu tư mới trang thiết bị máy móc, công cụ, dụng cụ tăng năng suất, tăng chất lượng, giảm người.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học/ cao đẳng chuyên ngành điện, tự động hóa, điều khiển\n- Có từ 03 năm kinh nghiệp lập trình PLC tại các công ty FDI, các công ty chế tạo máy.\n- Có khả năng lập trình PLC, HMI: Mitsubishi, Siemens, Yaskawa, Inovance\n- Có khả năng làm việc với động cơ Servo, Stepping motor, robo cylinder\n- Có khả năng quản lý công việc, làm việc nhóm, làm việc độc lập\n- Tổng hợp báo cáo\n- Ngoại ngữ Tiếng Anh hoặc Tiếng Nhật\n\nQuyền lợi\n- Lương thỏa thuận theo kinh nghiệm\n- Phụ cấp cha mẹ đẻ từ 70 tuổi trở lên: 400,000 đồng/ bố hoặc mẹ/tháng\n- Thưởng ngày Tết Dương lịch, Tết Nguyên đán, Lễ Quốc Khánh, Thưởng đột xuất theo Nội quy lao động, qui chế khen thưởng và Quy chế tài chính của Công ty.\n- Phúc lợi cho con: Thưởng học sinh giỏi, xuất sắc, tết Thiếu nhi, trung thu...\n- Phúc lợi thăm hỏi: Hôn nhân, sinh nhật, ốm đau, tang gia ...\n- Nghỉ mát hàng năm 100% do Công ty tổ chức và đài thọ\n- Hỗ trợ 30%- 40% - 50% khi mua sắm các sản phẩm Kangaroo\n- Và các phúc lợi khác theo qui định trong cơ chế Chính sách nhân viên cùng nhau phát triển của Tập đoàn.\n\nĐịa điểm làm việc\n- Hưng Yên: Cụm CN Tân Tiến - Tân Tiến - Văn Giang, Văn Giang\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hưng Yên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3048, 1304, 2, 'Fullstack Developer (Java, ReactJS)', 'Mô tả công việc:\n- Analyze the business specs then prepare technical specs and develop the new systems or enhance existing system for supporting business needs.\n- Support the team leader on technical analysis to provide the best technical solution as well as support colleagues for solving technical issues to complete the assigned projects / tasks on timely manner.\n- Investigate and answer daily inquiries on systems functional as well as problem encountered in order to resolve it in timely manner.\n- In charge of unit test on enhancements/ new development under responsibility to ensure developed modules are matched with business requirements.\n- Assist users/team leader on building test scripts to cover all test cases.\n\nYêu cầu ứng viên:\n- IT technical analysis and programming: at least 3 years.\n- Good knowledge of an objective oriented language Java.\n- Good knowledge of web/application containers (Apache Tomcat, Jboss AS, IBM WebSphere …) and web/application deployment.\n- Good experience on SOAP and RESTful Web Services.\n- Good skill at MS SQL Server programming (stored procedure, function, job, trigger, view).\n- Good skill in database design, database management, particularly MS SQL.\n- Solid understanding of the software development life cycle, Agile Scrum.\n- Working knowledge of HTML5, CSS3, React, Flutter, and JavaScript a plus.\n\nQuyền lợi:\n- Competitive salary and benefits.\n- Working time: 8:00AM - 05:30PM, Monday – Friday.\n- 12 days of annual leave + 3 days of sick leave + 1 day of birthday per year.\n- Participated in social insurance, unemployment insurance, health insurance and full policies according to the labor law.\n- 13th month salary & bonus policies, allowances at the Company.\n- UNIT-Care health care insurance by level.\n- Salary increases according to company regulations or unexpected salary raise in case of outstanding ability.\n- Professional and dynamic working environment, unlimited promotion opportunities.\n- Opportunity to participate in many large projects in Vietnam & abroad.\n- Work on the latest technology platform.\n- Join in company trip, teambuilding & community activities.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Phú Nhuận. \n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3049, 1461, 2, 'Web Developer', 'Mô tả công việc:\n- Tìm hiểu phân tích yêu cầu người dùng, thiết kế giao diện web\n- Lập trình, xây dựng website\n- Tham gia lập trình và phát triển thiết kế chi tiết theo các thành phần chức năng\n- Tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu công nghệ công nghệ mới, đưa ra giải pháp áp dụng vào sản phẩm dịch vụ của công ty\n- Tham gia rà soát các yêu cầu thay đổi liên quan đến hoạt động kinh doanh của công ty\n- Tham gia vào quá trình phân tích và thiết kế hệ thống\n- Thu thập và xử lí các yêu cầu thiết kế và kĩ thuật;\n- Tối ưu và nâng cấp mã nguồn để cải tiến hiệu quả, tăng độ ổn định và bảo mật\n- Duy trì và phát triển các website, code và cấu trúc dữ liệu có sẵn của công ty\n- Hoàn thành các công việc khác được cấp trên giao\n- Hỗ trợ các công việc liên quan IT Helpdesk: Cài đặt và cấu hình phần cứng, phần mềm, mạng máy tính, line điện thoại, ứng dụng cho các end user. Lắp ráp, cài đặt các thiết bị máy tính, máy in, camera. Thực hiện sửa chữa các phần cứng kịp thời và nâng cấp phần cứng/mềm theo yêu cầu...\n\nYêu cầu ứng viên:\n- Có kinh nghiệm lập trình viết code, sử dụng thành thạo một trong các Front end & Back end Development, framework như Flask, Django, Big Data Dev ...\n- Có kinh nghiệm làm việc trên hệ điều hành Linux(Ubuntu), Window...\n- Có kiến thức lập trình OOP, design pattern.\n- Có hiểu biết về cơ sở dữ liệu và hệ thống: MySQL, MongoDB hay PostgreSQL – Biết sử dụng công cụ quản lý mã nguồn: Git, Jira, SVN...\n- Khả năng làm việc nhóm, giao tiếp tốt.\n- Kỹ năng giải quyết vấn đề nhanh chóng và hiệu quả.\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc các lĩnh vực liên quan.\n\nQuyền lợi:\n- Mức lương thỏa thuận được deal theo năng lực\n- Tham gia các chế độ theo quy định của công ty và nhà nước: BHXH, BHYT, BHTN...\n- Lương tháng 13, thưởng theo hiệu quả làm việc\n- Phụ cấp cơm trưa\n- Được làm trong môi trường năng động và trẻ trung\n\nĐịa điểm làm việc:\n- Đà Nẵng: Số 109 đường 30 tháng 4, Phường Hòa Cường Bắc, Hải Châu\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3050, 1165, 2, 'Nhân Viên Lập Trình Back-End', 'Mô tả công việc\n- Phối hợp với đội nhóm để phân tích yêu cầu của dự án, xây dựng kiến trúc và tổng hợp thành tài liệu.\n- Chịu trách nhiệm phát triển, tối ưu và duy trì hệ thống backend cho ứng dụng (Android, iOS, web).\n- Tối ưu hóa hệ thống cơ sở dữ liệu (SQL), giải quyết các vấn đề về hiệu năng và scalability.\n- Triển khai các giải pháp bảo mật theo quy định\n- Đánh giá yêu cầu xây dựng (đánh giá được hết tất cả các trường hợp, hiểu bản chất của vấn đề), sửa đổi tính năng.\n- Xử lý lỗi phát sinh trong quá trình vận hành\n- Tìm kiếm các phương án tối ưu nhằm nâng cao giải pháp, hiệu suất cho quá trình phát triển sản phẩm\n- Nghiên cứu, cập nhật các xu hướng, công nghệ liên quan đến phát triển sản phẩm.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học/cao đẳng các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin...\n- Độ tuổi từ 23-30 tuổi.\n- Tối thiểu 1 - 3 năm kinh nghiệm phát triển ứng dụng backend sử dụng Node.js.\n- Thành thạo Node.js và các framework phổ biến như Express, NestJS.\n- Kinh nghiệm với các công cụ quản lý cơ sở dữ liệu như MySQL, PostgreSQL, Microsoft SQL.\n- Thành thạo sử dụng AI trong công việc.\n- Hiểu biết về thiết kế API RESTful.\n- Có khả năng đọc hiểu tiếng Anh & sử dụng tốt công cụ tìm kiếm để giải quyết vấn đề.\n- Kiến thức về bảo mật web và các phương pháp bảo vệ ứng dụng.\n- Có ý thức lập trình viết code theo cấu trúc, theo tài liệu, dễ dàng nâng cấp (clean code).\n- Kỹ năng giải quyết tốt và khả năng làm việc độc lập cũng như làm việc nhóm.\n- Có khả năng giao tiếp và hợp tác cùng các đội nhóm khác.\n- Chủ động, trung thực và có ý thức cầu tiến.\n\nQuyền lợi\n- Thời gian làm việc: 8h00 - 17h00 Từ thứ 2 đến thứ 6, được nghỉ T7&CN\n- Cơ hội huấn luyện: Cơ hội tham gia các chương trình đào tạo trong nước và nước ngoài, đặc biệt dành cho lập trình viên.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, hòa đồng\n- Thu nhập theo năng lực và hiệu quả công việc.\n- Đảm bảo đầy đủ quyền lợi của người lao động theo quy định của Nhà nước.\n- Khám sức khỏe định kỳ hàng năm và tham gia thêm gói bảo hiểm chăm sóc sức khỏe BIC\n- Tham gia các hoạt động teambuilding, bonding, CLB đá bóng hàng tuần tại Công ty.\n- Phụ cấp khác: Phụ cấp cơm trưa, gửi xe, sinh nhật, công tác phí và các phụ cấp khác cho người lao động.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3051, 1281, 2, 'Nhân Viên Lập Trình Máy CNC', '- Nhận bản vẽ và lên kế hoạch gia công\n- Làm chương trình cho máy CNC hoạt động.\n- Kiểm tra chất lượng đầu ra sản phẩm\n- Báo cáo các vấn đề liên quan trong quá trình làm việc\n- Thời gian làm việc: chuyên làm ngày. Hoặc làm theo ca\n- Bóc Tác bản vẽ, kê phôi gia công\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học, Cao đẳng, Trung cấp chuyên ngành cơ khí chế tạo.\n- Hiểu biết ngôn ngữ lập trình máy CNC.\n- Có kinh nghiệm lập trình máy CNC từ 1 năm trở lên.\n- Bắt buộc sử dụng thành thạo 1 trong các phần mềm CAM.\n- Ưu tiên người đã có kinh nghiệm làm việc ở các công ty sản xuất jig, đồ gá, Khuôn mẫu.\n\nQuyền lợi:\n- Lương cơ bản: Từ 10- 12 triệu.\n- Được tham gia bảo hiểm theo quy định của Pháp luật.\n- Thưởng và các chế độ khác theo Luật lao động và quy định của công ty.\n- Chế độ nghỉ mát hàng năm;\n- Môi trường làm việc chuyên nghiệp, thân thiện;\n- Có cơ hội thăng tiến.\nGiờ làm việc: 8:00 – 17:00 thứ 2 đến thứ 7.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3052, 1457, 2, 'Flutter Developer', '- Phát triển ứng dụng ecomerce liên quan đến việc mua bán các sản phẩm về giáo dục như sách, bút và khoá học online\n- Phát triển ứng dụng về Elearning cho phép học tập online Maintain, fixbug và có khả năng research các công nghệ mới\n- Viết các unit test\n- Tham gia brainstorm phát triển các tính năng sản phẩm hoặc các sản phẩm mới cùng product owner\n- Trao đổi và phân tích các yêu cầu cùng team lead\n- Thực hiện việc phát triển dự án theo mô hình Agile\n- Có thể làm hybrid hoặc lên văn phòng, quan trọng là công việc hiệu quả\n\nYêu cầu ứng viên:\n- Có kinh nghiệm ít nhất từ 2-3 năm về Flutter\n- Có ít nhất 1 dự án đã làm trong thực tế, đặc biệt đã làm về ecommerce là 1 lợi thế\n- Có khả năng nghiên cứu và ứng dụng các công nghệ mới\n- Có kĩ năng Problem soving tốt\n- Có khả năng làm việc độc lập\n- Thành thạo sử dụng git\n- Có kinh nghiệm tham gia các dự án quản trị theo phương thức Agile\n- Có thể làm fullstack hoặc có kinh nghiệm làm backend là 1 lợi thế\n\nQuyền lợi:\n- Đóng đầy đủ bảo hiểm\n- Có lương tháng 13\n- Nếu làm tốt trở thành core-team có thể thưởng tiếp hoa hồng theo doanh thu\n- Được đánh giá tăng lương 1 lần/năm hoặc khi có thành tích đặc biệt\n\nĐịa điểm làm việc:\n- Hà Nội: Số 8, ngõ 25 Nguyễn Chánh, Cầu Giấy\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3053, 1226, 2, 'Unity Developer (Casual/Puzzle) - Fresher', 'Mô tả công việc\n- Participate in developing Game projects (Casual/Puzzle) on the Unity platform\n- Coordinate and discuss with team members to build, complete and optimize the game\n- Contribute ideas and content to improve product quality\n- Job details will be discussed specifically if the CV meets the requirements.\n\nYêu cầu ứng viên\nKnowledge:\n- Graduated from University majoring in IT or related fields \n- Good programming thinking, proficient in C# programming language \n- Have at least 4-6 months of experience working with Unity; know how to work with XCode and Android Studio.\n\nSkill:\n- Proficient in Unity, especially experienced in handling issues such as: Animation, Effect, Particle, optimization \n- Skilled in planning Game development, able to work under high pressure \n- Good teamwork and good independent work.\n\nAttitude:\n- Ability to work in a customer-centric and team-oriented environment, detail-oriented \n- Positive, proactive, responsible in work, and have passion for Games\n- Diligent, eager to learn, enthusiastic, with a strong growth mindset and a passion for self-development\n- Commitment to long-term engagement with the company\n- Quick adaptability to work, able to handle pressure\n- Ability to work in a fast-paced environment.\n\nQuyền lợi\nINCOME\n- Salary: Upto 15M/month\n- Receive 100% of fixed salary, salary increase according to company regulations\n- Official employee lunch allowance: 1,000,000 VND/month\n- Income based on results and work performance\n\nDEVELOPMENT OPPORTUNITIES\n- Expand and improve professional knowledge and skills\n- Real-life experience at global projects\n- Have a clear, personalized career development roadmap\n\nWORKING ENVIRONMENT\n- Experience a dynamic, professional international environment\n- Enjoy 100% daily life care benefits\n\nWELFARE POLICY\n- The company pays all types of insurance according to the provisions of law (social insurance, health insurance, unemployment insurance, etc.)\n- Free periodic general health check-ups at hospitals: Hong Ngoc, Thu Cuc, Vinmec.\n- Wedding/filial piety benefits, holiday/New Year gifts and other benefits.\n- New Year bonus, March 8, April 30 - May 1, Mid-Autumn Festival, mid-year, September 2, October 20, Christmas.\n- Share achievements continuously, without limits based on performance.\n- Working hours:\nFrom Monday - Friday. Closed Saturday, Sunday\nMorning: 8:30 - 12:00, Afternoon: 13:00 - 18:00, tea-break 15:00 - 15:30.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3054, 1224, 2, 'Thực Tập Sinh', 'Mô tả công việc\n- Phát triển game 2D/3D trên nền tảng Unity\n- Tham gia các dự án về game. Dev bằng Unity và các phần mềm lập trình khác.\n- Phối hợp với các thành viên trong team để hoàn thiện và tối ưu game: animation, UI, UX...\n- Đóng góp ý tưởng nội dung công việc.\n\nYêu cầu ứng viên\n- Sinh viên năm cuối hoặc vừa tốt nghiệp chuyên ngành CNTT ở các trường Đại học; trung tâm IT.\n- Có sản phẩm game demo.\n- Đã từng làm ít nhất 1-2 minigames dev bằng Unity (cho cá nhân hoặc công ty). Gửi kèm sản phẩm game hoặc game demo trong cv ứng tuyển.\n- Có kiến thức về C#, Java…\n- Yêu thích và đam mêm lập trình phần mềm, quan tâm tới lập trình game di động;\n- Tư duy logic tốt.\n- Ưu tiên có kinh nghiệm làm với Unity.\n- Đã từng tham gia dự án trên iOS/Android/HTML5 là một lợi thế.\n- Kỹ năng phân tích và giải quyết vấn đề tốt.\n- Có khả năng làm việc nhóm cũng như độc lập.\n\nQuyền lợi\n- Lương: 2tr-3tr.\n- Thời gian làm việc: 8h-17h30( từ thứ 2- sáng thứ 7).\n- Được đào tạo về lập trình game 2D/3D trên điện thoại di động và cách thức vận dụng vào dự án cụ thể, nắm vững kiến thức tổng quát trong lập trình game.\n- Cơ hội tiếp cận và học hỏi công nghệ tiên tiến trong môi trường làm việc đa quốc gia năng động, trẻ trung, chuyên nghiệp.\n- Chương trình đào tạo bài bản, chuyên nghiệp.\n- Cơ hội trở thành nhân viên chính thức bất cứ thời gian nào trong quá trình thực tập.\n\nĐịa điểm làm việc\n- Hà Nội: Hà Đông.\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n- Thứ 2- Thứ 6: 8h-17h30\n- Thứ 7: 8h-12h.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hà Đông', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3055, 1448, 2, 'PHP Backend Developer', 'Mô tả công việc:\n- Phát triển, tối ưu và bảo trì các ứng dụng web sử dụng PHP & MySQL.\n- Thiết kế và xây dựng kiến trúc hệ thống hiệu suất cao, có khả năng mở rộng.\n- Phối hợp với các team khác (Frontend, DevOps, QA) để triển khai dự án.\n- Tối ưu truy vấn database, đảm bảo hiệu suất và bảo mật hệ thống.\n- Nghiên cứu và áp dụng công nghệ mới để cải thiện chất lượng sản phẩm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Kinh nghiệm: Ít nhất 2 năm kinh nghiệm làm việc với PHP (Laravel/Symfony/CodeIgniter/Yii2 hoặc thuần PHP) và MySQL.\n- Có kinh nghiệm tham gia các dự án thực tế, từ giai đoạn phân tích đến triển khai.\n- Đã từng xây dựng hoặc tham gia phát triển hệ thống lớn, ứng dụng high-performance.\n- Kỹ năng chuyên môn: Thành thạo PHP, MySQL, RESTful API.\n- Hiểu biết về database optimization, indexing, caching (Redis/Memcached).\n- Có kiến thức về microservices, hệ thống phân tán là một lợi thế.\n- Quen thuộc với Docker, Git, CI/CD.\n- Khả năng phân tích, giải quyết vấn đề và làm việc độc lập. Ưu tiên: Làm việc thành thạo với framework Yii2 là 1 lợi thế.\n\nQuyền lợi:\n- Mức lương cạnh tranh theo đúng năng lực.\n- Môi trường làm việc thân thiện, năng động, có cơ hội phát triển bản thân và thăng tiến lên vị trí team leader, quản lý.\n- Cơ hội tiếp cận với các công nghệ mới, làm việc trong môi trường startup/công nghệ năng động.\n- Ghi nhận thành tích, tăng lương và thưởng kịp thời.\n- Chế độ bảo hiểm đầy đủ, nghỉ phép theo quy định.\n- Thưởng Lễ Tết, 30/4; 1/5; 2/9…. (theo tình hình hoạt động thực tế của Công ty).\n- Sinh nhật, ốm đau, sinh con, ma chay, hiếu hỉ theo mức quy định của Công ty.\n- Teambuilding, nghỉ mát….. (theo tình hình hoạt động thực tế của Công ty).\n- Được tham gia các khóa đào tạo do công ty tổ chức: kĩ năng mềm, nâng cao trình độ chuyên môn.… \n\nĐịa điểm làm việc:\n- Hà Nội: 34 Nguyễn Khánh Toàn, Quan Hoa, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n- Thứ 7 làm việc luân phiên theo tuần.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3056, 1378, 2, 'Lead Software Engineer (Java/.Net)', '1. Lead the development of high-quality, impactful, and scalable products and systems to achieve business goals.\n2. Conduct system analysis, architecture design, and develop technical solutions based on project requirements, while producing corresponding technical documentation.\n3. Develop software applications using Java or .NET technologies.\n4. Collaborate closely with engineering managers and engineers across multiple platforms and domains.\n5. Support to recruit, develop, and retain exceptional engineering talent who excel in innovative, user-focused, fast-paced environments.\n6. Establish and maintain high engineering standards for your team regarding quality practices, delivery speed, architecture, design, and code quality, with clear measurable goals.\n7. Contribute to the improvement and scaling of the engineering organization by mentoring engineers, sharing technical knowledge, industry best practices, and leadership skills.\n\nYêu cầu ứng viên:\n1. Familiarity with J2EE or .Net.\n2. Familiarity with RDBMS (PostgreSQL, Oracle, MSSQL).\n3. Have experience with developing on Cloud Platform (GCP, AWS, Azure).\n4. Familiarity with Git, Docker, Kubernetes is a plus.\n5. Strong analytical and problem-solving skills.\nSoft skills:\n1. Has team collaboration awareness, able to work cooperatively with team members. Experience in Scrum is a plus.\n2. Good communication skills (English and Vietnamese) and logical thinking/judgment abilities.\n3. Proactive and self-motivated to learn.\n4. Possesses or is willing to learn multiple languages (Chinese) to effectively communicate with the team.\n\nQuyền lợi:\nFull social benefits in accordance with the company and the Vietnam Law.\nPremium health care & accident insurance.\nFriendly working environment with strong startup culture.\nTeam building, Company trip, Year-end party, etc.\n40 flexible working hours per week from Monday to Friday.\nSalary review at least one time per year based on employee\'s performance and contribution.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3057, 1153, 2, 'Thực Tập Sinh', 'Mô tả công việc\n- Thiết kế và phát triển hệ thống dữ liệu phù hợp với nhu cầu kinh doanh.\n- Phát triển các thuật toán để chuyển đổi dữ liệu thành thông tin hữu ích, có thể thực hiện được.\n- Xây dựng, thử nghiệm và bảo trì các pipeline cơ sở dữ liệu.\n- Lấy, thêm, sửa đổi dữ liệu theo yêu cầu.\n- Có kỹ năng phối hợp với quản lý để hiểu các mục tiêu của công ty.\n- Phát triển các phương pháp xác thực dữ liệu và các công cụ phân tích dữ liệu.\n- Đảm bảo tuân thủ các chính sách quản trị và bảo mật dữ liệu.\n- Sử dụng các công cụ Business Intelligence để visualize dữ liệu.\n\nYêu cầu ứng viên\n- Sinh viên cuối năm 3, năm 4 hoặc sinh viên mới tốt nghiệp của các trường có chuyên ngành CNTT, điện tử viễn thông\n- Có kinh nghiệm làm việc về các hệ thống Big data\n- Có kinh nghiệm coding SQL và một trong những ngôn ngữ sau NoSQL, Python, Java, R, and Scala \n- Có kinh nghiệm về thiết kế Data-warehouse, xử lý dữ liệu phân tán, xử lý dữ liệu lớn (Hadoop, Spark,  MongoDB, and Kafka…)\n- Có kiến thức về Relational and non-relational databases.\n- Có kinh nghiệm build ETL hay các data pipeline (Airflow…).\n- Có kinh nghiệm viết các script tự động hoá các tác vụ bằng SQL hay Python …\n- Có kiến thức về Data Security\n- Tư duy tốt, có khả năng nghiên cứu, đánh giá và cập nhật công nghệ mới.\n- Tiếng anh đọc hiểu tài liệu Kỹ thuật.\n- Kỹ năng giao tiếp bằng lời nói và bằng văn bản tốt. Tự tin với kỹ năng làm việc nhóm.\n- Có kiến thức về Cloud (Azure, GCP, AWS) là một lợi thế.\n- Có kiến thức về Machine Learning là một lợi thế\n- Có thể sử dụng tiếng Anh, tiếng Nhật là một lợi thế\n- Có thể đi làm ít nhất 8 buổi hoặc 3 ngày full/tuần\n\nQuyền lợi\nChế độ làm việc:\n- Môi trường làm việc trẻ trung, với nhiều cộng sự tài năng.\n- Thời gian làm việc thoải mái: Thứ 2 – Thứ 6, flexible check in.\n- Có chế độ làm việc Remote cho các nhân viên xuất sắc.\n- Nghỉ phép đặc biệt cho nữ: 1 ngày/ tháng.\nQuyền lợi:\n- Mức lương cạnh tranh tương xứng với năng lực.( Đối với TTS sẽ có lương hỗ trợ và có thể trao đổi trong quá trình phỏng vấn)\n- Xét tăng lương/thăng chức 2 lần/năm (Tháng 06 và tháng 12)\n- Tổng thu nhập lên đến 14 tháng lương/năm.\n- Được tham gia BHXH, BHYT, BHTN và các chế độ theo quy định của luật Lao động.\n- Khám sức khỏe định kỳ 1 lần/năm tại các bệnh viện hàng đầu Việt Nam.\n- Cơ hội đi onsite tại Nhật Bản.\n- Tham gia Team Building, party, dã ngoại, thể thao, du lịch công ty.\nPhát triển năng lực cá nhân:\n- Văn hóa học tập mạnh mẽ và thúc đẩy phát triển.\n- Hỗ trợ các khoá học nâng cao nghiệp vụ chuyên môn trên Udemy, Coursera.\n- Tham gia các khóa đào tạo nội bộ về kiến thức chuyên môn, ngoại ngữ và các kỹ năng khác.\n- Hỗ trợ học phí, thưởng nóng khi đỗ các chứng chỉ IT, ngoại ngữ (Tiếng Nhật, Anh)\n- Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp.\n- Cơ hội tham gia nhiều dự án đa dạng với các khách hàng hàng đầu Nhật Bản.\n- Cơ hội thăng tiến, nâng cao thu nhập cho người có năng lực, tâm huyết và gắn bó lâu dài.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 11, Tòa nhà Hồ Gươm Plaza,Trần Phú, Hà Đông\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3058, 1467, 2, 'COBOL Developer Intern', 'Với định hướng đào tạo nhân sự trẻ, giúp các bạn trẻ có cơ hội phát triển bản thân, SSV đang cần 2 bạn COBOL Developer Intern với các nhiệm vụ:\n● Tham gia và hoàn thành khoá training của công ty (Thời gian 3 tháng trở lên)\n● Tham gia/ học hỏi kinh nghiệm từ các dự án thực tế của công ty (Thời gian 3 tháng trở lên)\n\nYêu cầu ứng viên\n- Sinh viên năm 3 hoặc năm 4, Không yêu cầu đúng chuyên ngành\n- Có hứng thú với lĩnh vực CNTT và nghiệp vụ trong các ngành: Bảo hiểm, Ngân hàng, Chứng khoán.\n- Tinh thần học hỏi cao, chủ động và tích cực trong công việc.\n- Kỹ năng làm việc độc lập tốt, đồng thời phối hợp hiệu quả trong làm việc nhóm.\n- Yêu thích việc học lập trình và phát triển tư duy logic.\n- Có chứng chỉ tiếng Nhật hoặc trình độ tương đương trở lên.\nCó những điểm sau là lợi thế:\n- Có khả năng tạo lập tài liệu & thuyết trình.\n- Có hiểu biết hoặc kinh nghiệm về Software Development.\n\nQuyền lợi\n- Môi trường làm việc công ty startup trẻ trung, vui vẻ, hòa đồng, thân thiện, được tiếp cận với quy trình làm việc chuyên nghiệp và lộ trình thăng tiến rõ ràng.\n- Trợ cấp ăn trưa và đi lại 150.000VNĐ/ngày trở lên.\n- Sau khi kết thúc thời gian thực tập sẽ có cơ hội thành nhân viên thử việc (Mức lương 3.000.000 – 6.000.000 VNĐ/tháng). Hoặc nhân viên hợp đồng (Lương thỏa thuận).\n- Được đào tạo từ đầu về ngôn ngữ COBOL, quy trình phát triển phần mềm.\n- Được tiếp xúc với nghiệp vụ hệ thống chuyên ngành (Ví Dụ: ngân hàng, bảo hiểm, tài chính,...).\n- Được tham gia các hoạt động văn hóa đoàn thể trong năm: Nghỉ mát, teambuilding, thể thao.\n- Tham gia các buổi Seminar chia sẻ về kỹ năng & kiến thức từ các thành viên trong công ty.\n\nĐịa điểm làm việc\n- Thanh Hoá: Tầng 2, Louis Apartment Tower, số 30 Lê Lợi, Đông Hương,  Thanh Hoá, Việt Nam, TP Thanh Hoá.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n- Công ty áp dụng chế độ làm việc linh hoạt Core time.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thanh Hoá', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3059, 1368, 2, 'PHP Developer', 'Mô tả công việc\n- Tham gia vào quá trình phát triển sản phẩm cho khách hàng, bao gồm từ các công đoạn research, làm requirement, design, coding, test, operation.\n- Loại hình dự án: Các hệ thống web-application (sử dụng ngôn ngữ PHP NodeJS,...).\n- Kỹ thuật sử dụng: MySQL, PHP Laravel, AWS\n\nYêu cầu ứng viên\n- Kỹ năng bắt buộc:\n  Có từ 04 năm kinh nghiệm trở lên với ngôn ngữ PHP (Laravel)\n  Thành thạo RDB hoặc NoSQL (MongoDB).\n  Thao tác tốt với HTML, CSS, JavaScript, Bootstrap, JSON, XML,...\n  Có kiến thức và khả năng làm việc với công nghệ Frontend (NextJS)\n  Có kinh nghiệm làm việc với Cloud như AWS, Azuze, GCP\n\n- Tốt hơn nếu có:\n  Có kinh nghiệm thiết kế hệ thống theo Microservices là một lợi thế.\n  Có kinh nghiệm về DevOps, CI-CD.\n  Có kinh nghiệm xử lý các bài toán liên quan tới Real time services.\n\n- Kỹ năng khác:\n  Chủ động trong công việc, chủ động trong giao tiếp và raise vấn đề khi cần thiết.\n  Có khả năng tự học, có khả năng phát hiện vấn đề và đưa ra phương án giải quyết.\n  Có khả năng training member.\n  Có khả năng leadership, có ý thức trách nhiệm cao, có tinh thần làm việc teamwork.\n  Có kinh nghiệm outsource cho khách hàng Nhật.\n\nQuyền lợi\n- Cơ hội phát triển\n  Làm việc, học hỏi và phát triển cùng đồng nghiệp là những kỹ sư trẻ tài năng, đam mê và có lý tưởng lớn.\n  Được tham gia các chương trình training về kỹ năng công nghệ và kỹ năng mềm, phương pháp làm việc (Agile, Scrum...).\n  Được tư vấn và chia sẻ về phát triển năng lực và nghề nghiệp bản thân.\n\n- Chế độ đãi ngộ\n  Lương: Thỏa thuận theo năng lực.\n  Thưởng: Lên đến 15 tháng lương/năm, bao gồm:\n  - Bonus cố định: 01 tháng lương (tương ứng với thời gian làm việc trong kỳ đánh giá).\n  - Performance Bonus (Dựa theo kết quả; Performance review): 2 lần/năm.\n  - Thưởng tổng kết doanh thu năm, thưởng nhân viên tiêu biểu tháng.\n  - Du lịch năm, team building tháng (200k/người), tổ chức sinh nhật tháng, Trung thu,...Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n  - Khám sức khỏe định kỳ hàng năm tại bệnh viện uy tín.\n  - Văn phòng rộng rãi, trang thiết bị hiện đại, môi trường làm việc mở.\n\nĐịa điểm làm việc\n- Đà Nẵng: 130 Nguyễn Tư Giản, Mỹ An, Ngũ Hành Sơn, Ngũ Hành Sơn\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3060, 165, 2, 'Flutter Developer', 'Về KiotViet: Sản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ.\n\nVới 15 năm và hơn 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm.\n\nBạn sẽ làm gì:\n- Phát triển các dự án phần mềm công ty trên nền tảng Flutter Cross-Platform (Android/iOS)\n- Thực hiện các nhiệm vụ khác liên quan đảm bảo tiến độ dự án\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học ưu tiên chuyên ngành CNTT hoặc chuyên ngành liên quan;\n- Có kinh nghiệm Flutter từ 2 năm trở lên;\n- Thành thạo state management (Provider, Riverpod, Bloc...).\n- Hiểu biết hoặc đã từng làm việc với kiến trúc MVVM, Clean Architecture.\n- Có kinh nghiệm làm việc với: REST API, Firebase, Isar.\n- Native Android (Kotlin/Java) và/hoặc iOS (Swift/Obj-C) và custom plugin.\n- Nắm rõ Push notification, background tasks, deep link, crash tracking.\n- Biết viết unit test là lợi thế.\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm.\n- Làm việc từ Thứ 2 – Thứ 6, làm việc 8h/ngày và checkin linh hoạt từ 8h-9h;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\n- Chăm sóc sức khoẻ: Khám sức khoẻ định kỳ hàng năm, Bảo hiểm sức khoẻ cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\n- Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc:\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm.\n\nThời gian làm việc:\nThứ 2 - thứ 6 có ca làm việc linh hoạt từ 8h00-9h00 đến 17h30-18h30, làm đủ 8 tiếng.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3061, 1387, 2, 'Frontend Developer (Shopify, Thành Thạo HTML.CSS,JS, Lương Từ 12-20 Triệu)', '- Làm việc với các template theo chuẩn Shopify liquid theo design để xây dựng và phát triển các tính năng hỗ trợ bán hàng thông qua các template sử dụng ngôn ngữ Shopify liquid, javascript, css, html.\n- Xây dựng template cho dự án app page builder.\n- Fix bug phát sinh từ các template khi đưa tới người dùng thật.\n- Tương tác liên tục 2 chiều với team và cấp trên để đảm bảo hoàn thành công việc theo tiêu chí chất lượng cao.\n\nYêu cầu ứng viên\n- Tối thiểu 2 năm kinh nghiệm làm việc với Theme của Shopify hoặc làm việc với các Page builder cho Shopify (là lợi thế).\n- Có kỹ năng chuyên môn cao về Shopify Liquid, Javascript, CSS, HTML.\n- Yêu cầu cao về sự cẩn thận, tỉ mỉ và trách nhiệm với công việc.\n- Có kinh nghiệm dẫn dắt, hướng dẫn, hỗ trợ phát triển các thành viên trong nhóm là một lợi thế.\n\nQuyền lợi\n- Mức lương : 12 - 20M (tùy theo năng lực).\n- Thưởng quý, thưởng lương tháng thứ 13. Xem xét tăng lương 2 lần/năm.\n- Có lộ trình thăng tiến và được các dev nhiều kinh nghiệm đào tạo nâng cao trình độ.\n- Được tham gia những dự án mới giải quyết những vấn đề thực tế của khách hàng.\n- Được đóng bảo hiểm sau khi ký hợp đồng chính thức.\n- Môi trường làm việc trẻ trung thân thiện, đa số ở độ tuổi 9x, 2k.\n- Các phúc lợi khác: hỗ trợ tiền ăn trưa, tiền gửi xe, sinh nhật, du lịch hàng năm.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 6, Số 68 Khúc Thừa Dụ, Dịch Vọng, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc\n- Thời gian làm việc từ 8h-17h15 từ thứ 2-6 (nghỉ thứ 7, CN).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3062, 1146, 2, 'Mobile Flutter Developer (Junior) - Lĩnh Vực Edtech - Up To 15M', 'Mô tả công việc:\n- Trực tiếp tham gia phát triển các dự án phần mềm trọng điểm của công ty về lĩnh vực giáo dục và các lĩnh vực khác.\n- Tham gia phân tích, thiết kế luồng phát triển của ứng dụng di động dựa vào yêu cầu của khách hàng, công ty.\n- Tham gia phát triển ứng dụng di động trên nền tảng Flutter.\n- Đánh giá, phân tích, nâng cấp và tối ưu mã nguồn trong quá trình phát triển.\n- Nghiên cứu các công nghệ mới để áp dụng trong các dự án hiện tại và tương lai.\n- Tham gia đưa ra những ý tưởng, giải pháp mới cải thiện công việc cũng như góp phần tăng doanh thu cho công ty.\n\nYêu cầu ứng viên:\n- Có kinh nghiệm lập trình Flutter/ Dart.\n- Nắm vững các khái niệm lập trình hướng đối tượng OOP, State Management.\n- Có kinh nghiệm về xử lý UI/ UX và các animation.\n- Có kinh nghiệm làm theo thiết kế từ Figma.\n- Có kinh nghiệm sử dụng Git (Gitlab/ Bitbucket/ Azure Devops).\n- Có kinh nghiệm xử lý với Bloc, Provider hoặc GetX.\n- Ưu tiên đã có sản phẩm/ dự án thực tế bằng Flutter.\n- Ưu tiên biết sử dụng thành thạo XCode để build ứng dụng.\n- Có kinh nghiệm trong việc launching sản phẩm lên App Store hoặc Google Play.\n- Có kinh nghiệm sử dụng và triển khai các thư viện như: Google Firebase.\n- Có hiểu biết REST APIs, quen thuộc với tất cả các kiến trúc hiện đại (MVP, MVVM, Redux, ...).\n\nQuyền lợi:\n- Mức lương (gross): up to 15 triệu/tháng\n- Thưởng sinh nhật, thưởng các dịp Lễ, Tết trong năm.\n- Chế độ BHXH, BHYT, BHTN đầy đủ ngay sau khi ký HĐ chính thức.\n- Khám sức khoẻ định kỳ hàng năm.\n- Trang bị máy tính hiện đại phục vụ công việc.\n- Quỹ Team Building lên tới 2.400.000 VNĐ/người/năm.\n- Du lịch nghỉ dưỡng hàng năm.\n- Trà chiều với bánh, hoa quả và đồ ăn vặt miễn phí hàng tuần.\n- Cơ hội tiếp cận với các doanh nghiệp, dự án lớn, xu hướng công nghệ và nền tảng mới nhất.\n- Được tham gia các lớp đào tạo, khóa học chuyên môn để phát triển kỹ năng.\n- Lộ trình thăng tiến lên Middle/Senior/Leader rõ ràng.\n- Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung & trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc.\n- Học tiếng Anh hoàn toàn miễn phí & ưu đãi học phí cho người thân.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3063, 1215, 2, 'Material Developer Staff', 'Mô tả công việc:\n1. Nghiên cứu & Phát triển nguyên phụ liệu:\n- Nghiên cứu và phát triển các loại nguyên phụ liệu mới phù hợp với tiêu chuẩn chất lượng, tính thẩm mỹ và yêu cầu về môi trường. Cải tiến các nguyên phụ liệu hiện có để nâng cao hiệu suất và tối ưu chi phí. Cập nhật xu hướng thị trường, công nghệ và tiêu chuẩn ngành.\n2. Tìm kiếm & Làm việc với nhà cung cấp:\n- Tìm kiếm, đánh giá và làm việc với các nhà cung cấp nguyên phụ liệu. Đàm phán giá cả, thời gian giao hàng và các điều khoản hợp tác. Đảm bảo nguyên phụ liệu tuân thủ các quy định về môi trường và pháp luật.\n3. Kiểm tra & Đảm bảo chất lượng nguyên phụ liệu:\n- Phối hợp với bộ phận Kiểm soát chất lượng để kiểm tra độ bền, màu sắc và hiệu suất của nguyên phụ liệu. Làm việc với bộ phận Sản xuất để đảm bảo nguyên phụ liệu phù hợp với quy trình sản xuất. Xử lý các vấn đề liên quan đến chất lượng và đề xuất giải pháp cải tiến.\n4. Phối hợp với các bộ phận liên quan:\n- Làm việc với các bộ phận R&D, Sản xuất, Thu mua và Thiết kế để lựa chọn nguyên phụ liệu phù hợp. Trao đổi với khách hàng, đối tác về tiêu chuẩn nguyên phụ liệu và phê duyệt sản phẩm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học/ cao đẳng chuyên ngành Kỹ thuật Dệt may, hoặc các ngành liên quan.\n- Ít nhất 2 năm kinh nghiệm trong lĩnh vực phát triển nguyên phụ liệu, tìm nguồn cung ứng hoặc sản xuất dệt may.\n- Kiến thức về vải, vật liệu tổng hợp và xu hướng bền vững.\n- Kỹ năng phân tích, giải quyết vấn đề và đàm phán.\n- Tỉ mỉ, chú ý đến chi tiết và am hiểu các tiêu chuẩn chất lượng.\n- Giao tiếp tốt bằng tiếng Anh (biết tiếng Hàn là một lợi thế).\n\nThu nhập:\n- Thu nhập khi đạt 100% KPI: Thoả thuận\n- Thu nhập tính theo tỷ lệ đạt KPI\n- Lương cứng: 10 - 15 triệu VND\n- Lương cứng không phụ thuộc doanh số.\n\nQuyền lợi:\n- Lương thưởng cạnh tranh, 14 ngày phép năm.\n- BHXH, BHYT, BHTN theo quy định pháp luật.\n- Cơ hội đào tạo và phát triển nghề nghiệp.\n- Môi trường làm việc chuyên nghiệp, năng động.\n\nĐịa điểm làm việc:\n- Đồng Nai: Đường số 3, KCN Amata, Long Bình, Biên Hoà.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 07:30 đến 17:00)\n- Thứ 7 (từ 07:30 đến 12:00).\n\nCách thức ứng tuyển:', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3064, 1179, 2, 'Fullstack Developer', ' Về dự án C-Agent\nC-Agent là nền tảng quản lý tri thức và ứng dụng GenAI dành cho doanh nghiệp Việt Nam. Sản phẩm giúp doanh nghiệp xây dựng hệ tri thức nội bộ, tự động hóa trả lời câu hỏi từ người dùng, kết nối đa nguồn dữ liệu (Google Drive, Notion, GitHub, API...) và tạo quy trình workflow linh hoạt.\nMục tiêu vai trò\nBạn sẽ tham gia xây dựng và phát triển toàn diện sản phẩm C-Agent, tập trung vào phát triển hệ thống backend chịu tải lớn (API, xử lý dữ liệu, tích hợp AI) và đảm bảo frontend hoạt động hiệu quả, trực quan cho người dùng.\nTrách nhiệm chính\n- Thiết kế và phát triển các API hiệu suất cao (RESTful, gRPC) phục vụ AI và ứng dụng web\n- Xây dựng các module backend phức tạp (authentication, authorization, rate limiting, logging, etc.)\n- Tích hợp hệ thống với các dịch vụ AI/LLM và luồng xử lý dữ liệu lớn\n- Làm việc cùng AI Engineer, Product Manager, BA để hiểu yêu cầu nghiệp vụ và xây dựng giải pháp phù hợp\n- Tham gia phát triển frontend (React/Next.js), đảm bảo tính năng và giao diện đồng bộ với backend\n- Đóng góp vào việc tối ưu kiến trúc hệ thống, cải tiến hiệu năng, và nâng cao chất lượng codebase\nYêu cầu ứng viên\nYêu cầu bắt buộc\nBackend (Ưu tiên chính):\n- Thành thạo Node.js (NestJS, Express), có thể tối ưu backend cho hệ thống chịu tải lớn\n- Hiểu rõ về kiến trúc Microservices, thiết kế API, xử lý concurrent requests\n- Kinh nghiệm làm việc với cơ sở dữ liệu SQL (PostgreSQL, MySQL) và NoSQL (MongoDB, Elasticsearch)\n- Hiểu về queue systems như Kafka, RabbitMQ, hoặc Redis Pub/Sub\n- Có kinh nghiệm xử lý auth (JWT, OAuth2) và bảo mật API\nFrontend (Nắm vững):\n- Kinh nghiệm làm việc với React/Next.js hoặc Vue.js\n- Hiểu cách tối ưu hiệu suất frontend (lazy loading, SSR, caching)\nHệ thống & triển khai:\n- Biết làm việc với Docker, Kubernetes là lợi thế\n- Hiểu CI/CD pipeline, testing (unit/integration test)\nQuyền lợi\n-Thu nhập: Lương thỏa thuận theo năng lực, gói thu nhập 13-14 tháng lương/năm.\n- Phúc lợi tiền mặt hơn 9 triệu/năm vào các dịp lễ, tết, sinh nhật tập đoàn.\n- Xét tăng lương định kỳ hằng năm.\n- Bảo hiểm xã hội đầy đủ và bảo hiểm sức khỏe CMC Care.\n- Nghỉ phép: 12 ngày/năm + 1 ngày nghỉ hưởng lương dịp sinh nhật.\n- Đào tạo chuyên môn, tài trợ 100% chi phí học và thi chứng chỉ CNTT quốc tế.\n- Cung cấp laptop/thiết bị công nghệ phục vụ công việc.\n- Môi trường trẻ trung, năng động, chuyên nghiệp.\n- Tham gia team building và các hoạt động văn hóa doanh nghiệp.\n- Nghỉ cuối tuần: Thứ 7 & Chủ Nhật.\nĐịa điểm làm việc\n- Hà Nội: Tòa CMC, số 11 Duy Tân, Cầu Giấy\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:15 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3065, 1226, 2, 'Unity Developer (Casual/Puzzle) - Junior/Middle', '- Participate in developing Game projects (Casual/Puzzle) on the Unity platform\n- Coordinate and discuss with team members to build, complete and optimize the game\n- Contribute ideas and content to improve product quality\n- Job details will be discussed specifically if the CV meets the requirements.\n\nKnowledge:\n- Graduated from University majoring in IT or related fields\n- Good programming thinking, proficient in C# programming language\n- Have at least 1 year of experience working with Unity; know how to work with XCode and Android Studio\n\nSkill:\n- Proficient in Unity, especially experienced in handling issues such as: Animation, Effect, Particle, optimization\n- Skilled in planning Game development, able to work under high pressure\n- Good teamwork and independent work.\n\nAttitude:\n- Ability to work in a customer-centric and team-oriented environment, detail-oriented\n- Positive, proactive, responsible in work, and have passion for Games\n- Diligent, eager to learn, enthusiastic, with a strong growth mindset and a passion for self-development\n- Commitment to long-term engagement with the company\n- Quick adaptability to work, able to handle pressure\n- Ability to work in a fast-paced environment.\n\nINCOME\n- Salary: Up to $1500\n- Opportunities for professional development and growth.\n- Receive 100% of fixed salary, salary increase according to company regulations\n- Official employee lunch allowance: 1,000,000 VND/month\n- Income based on results and work performance\n\nDEVELOPMENT OPPORTUNITIES\n- Expand and improve professional knowledge and skills\n- Real-life experience at global projects\n- Have a clear, personalized career development roadmap\n\nWORKING ENVIRONMENT\n- Experience a dynamic, professional international environment\n- Enjoy 100% daily life care benefits\n\nWELFARE POLICY\n- The company pays all types of insurance according to the provisions of law (social insurance, health insurance, unemployment insurance, etc.)\n- Free periodic general health check-ups at hospitals: Hong Ngoc, Thu Cuc, Vinmec.\n- Wedding/filial piety benefits, holiday/New Year gifts and other benefits.\n- New Year bonus, March 8, April 30 - May 1, Mid-Autumn Festival, mid-year, September 2, October 20, Christmas.\n- Share achievements continuously, without limits based on performance.\n- Working hours:\n\nFrom Monday - Friday. Closed Saturday, Sunday\nMorning: 8:30 - 12:00, Afternoon: 13:00 - 18:00, tea-break 15:00 - 15:30.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 10 - Tòa The West - 265 Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3066, 1258, 2, 'FullStack (NodeJS, ReactJS)', 'Tham gia lập trình, vận hành, tối ưu các sản phẩm của công ty.\nTối ưu hóa hiệu suất và bảo mật của các ứng dụng Web.\nXác định và giải quyết các vấn đề liên quan đến ứng dụng Web.\nTham gia vào các quá trình kiểm soát chất lượng cho sản phẩm.\nCác công việc khác theo sự phân công của Quản lý trực tiếp.\nChi tiết trao đổi qua cuộc phỏng vấn.\nThời gian làm việc: Từ thứ 2 đến hết sáng thứ 7, nghỉ chiều thứ Bảy và các ngày Chủ nhật.\n+ Sáng: từ 8h30 – 12h00.\n+ Chiều: từ 13h30 – 18h00.\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin, hoặc tương đương.\n- Kinh nghiệm: từ 2 năm ở vị trí tương đương.\n- Thành thạo quy trình phát triển phần mềm, từ tiếp nhận yêu cầu, lựa chọn công cụ, ngôn ngữ, thiết kế CSDL, xây dựng frontend, backend, triển khai lên hệ thống server thật.\n- Thành thạo ngôn ngữ lập trình Javascript, CSS, HTML và một framework xây dựng frontend như ReactJS hoặc Angular, biết cách xây dựng website responsive chạy trên mobile.\n- Thành thạo một framework xây dựng backend như NodeJS Express, ngôn ngữ SQL, biết cách sử dụng ORM và vận hành hệ quản trị CSDL như MySQL hoặc Postgres.\n- Biết sử dụng các API và thiết kế API để tương tác với các dịch vụ của khách hàng.\n- Biết đọc tài liệu bằng tiếng anh.\n- Biết phát triển ứng dụng mobile (ReactNative) là một lợi thế.\n- Kỹ năng làm việc độc lập và làm việc nhóm tốt để giải quyết các vấn đề liên quan đến sản phẩm.\nQuyền lợi:\n- Mức lương: thỏa thuận.\n- Phụ cấp ăn trưa.\n- Được hưởng các chế độ BHXH, BHYT, BHTN và các phúc lợi khác theo quy định của Luật lao động và của Công ty.\n- Được đi du lịch và tham gia các hoạt động vui chơi, giải trí khác do công ty tổ chức hàng năm.\n- Được đào tạo bài bản, chuyên sâu nâng cao nghiệp vụ chuyên môn và kỹ năng mềm.\n- Được làm việc trong môi trường chuyên nghiệp, năng động, sáng tạo.\nĐịa điểm làm việc:\n- Hà Nội: Tầng 5 tòa nhà Sannam, 78 Duy Tân, Cầu Giấy.\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00).\n- Thứ 7 (từ 08:30 đến 12:00).\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3067, 1314, 2, 'Senior .Net Developer', '1. Nội dung công việc\n- Xây dựng các ứng dụng phục vụ công việc tại Công ty bao gồm xây dựng và nâng cấp các phần mềm cho dự án nội bộ và các dự án phát triển đối tác\n- Xây dựng phát triển hệ thống backend\n- Tham dự vào các dự án Core và các dự án tái cấu trúc khác\n- Triển khai và đào tạo cho các bộ phận liên quan trong Công ty\n- Chịu trách nhiệm về tiến độ và kết quả công việc được giao\n- Thực hiện các công việc khác theo yêu cầu của cấp trên\n\n2. Thời gian làm việc: Từ 08h30 - 17h30, từ thứ 2 - thứ 6\n\n3. Địa điểm làm việc: Tòa nhà G-Group, 5 Nguyễn Thị Duệ, Yên Hòa, Cầu Giấy, Hà Nội\n\nYêu cầu ứng viên\n- Tối thiểu tốt nghiệp Cao đẳng hoặc Chứng chỉ chuyên ngành CNTT\n- Có ít nhất 3 năm kinh nghiệm phát triển trên môi trường .NET Core, ASP.NET MVC, C#\n- Thành thạo HTML/CSS/Javascript\n- Ưu tiên Có kinh nghiệm làm việc với một trong các ngôn ngữ kịch bản jQuery, Angular, Vue JS, ReactJs\n- Có kiến thức về Design Pattern\n- Có kinh nghiệm lập trình với các hệ cơ sở dữ liệu SQL Server, MySQL\n- Có kinh nghiệm tối ưu code\n- Có kinh nghiệm về nghiệp vụ ngân hàng tài chính là lợi thế\n- Có khả năng phân tích và xử lý yêu cầu nghiệp vụ\n- Kỹ năng sắp xếp công việc và quản lý thời gian hiệu quả\n- Đề cao trách nhiệm trong công việc, ý thức chất lượng sản phẩm tốt\n- Đam mê tìm tòi nghiên cứu học hỏi công nghệ mới, phát triển bản thân\n- Ưu tiên ứng viên có thể đọc hiểu tài liệu tiếng Anh\n- Hiểu biết và mong muốn làm việc trong một môi trường phát triển Agile, chuyên nghiệp\n\nQuyền lợi\n1. Chế độ chính sách\n- Lương thưởng cạnh tranh trên thị trường\n- Thưởng cuối năm + thưởng Lễ/Tết + thưởng sinh nhật + thưởng đột xuất khi hoàn thành tốt nhiệm vụ\n- 12 ngày phép năm + phép thâm niên\n- BHXH + chế độ bảo hiểm đặc biệt dành cho nhân viên (F88 Care)\n- Cơ hội tham gia gắn kết với tập thể thông qua các hoạt động văn hóa sôi động: Teambuilding, Tất niên, 8/3, 20/10, Giáng sinh...\n\n2. Môi trường làm việc\n- Cơ hội làm việc tại Công ty Fintech về dịch vụ tài chính\n- Được làm việc trong môi trường trẻ năng động, luôn coi Công nghệ thông tin là yếu tố trọng tâm để phát triển\n- Áp dụng mô hình phát triển phần mềm theo Agile, Scrum\n- Môi trường làm việc cởi mở và năng động với các giá trị cốt lõi sâu sắc truyền cảm hứng làm việc đến nhân viên\n- Khuyến khích trao đổi ý tưởng, đề cao sự sáng tạo trong công việc\n- Cơ hội tham gia gắn kết với tập thể thông qua các hoạt động văn hóa sôi động: Teambuilding, Tất niên, 8/3, 20/10, Giáng sinh...\n\n3. Cơ hội phát triển\n- F88 cam kết cho bạn nền tảng vững chắc để học hỏi và phát triển\n- Tham gia đào tạo bài bản, chuyên nghiệp từ Học viện F88\n- Sẵn sàng trao quyền, cơ hội đột phá cho nhân viên', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3068, 1223, 2, 'Senior .NET Developer (3-8 Years Experience)', 'Mô tả công việc:\n- Tham gia nghiên cứu, thiết kế, xây dựng, phát triển và triển khai hệ thống Công nghệ Thông tin cho Tài chính, Ngân hàng.\n- Tham gia xây dựng ý tưởng, tham gia thiết kế sản phẩm, giải pháp.\n- Xây dựng tài liệu kỹ thuật sản phẩm, dự án.\n- Tham gia xây dựng tài liệu đào tạo, tham gia đào tạo và hỗ trợ người sử dụng.\n- Bảo trì, nâng cấp hệ thống cho sản phẩm, dự án.\n- Hợp tác với các bộ phận khác trong quá trình thực hiện dự án.\n- Tham gia cải tiến quy trình phát triển sản phẩm, dự án.\n- Các công việc phát sinh khác theo yêu cầu kỹ thuật dự án.\n- Báo cáo kết quả công việc, thời gian làm việc phù hợp với quy định Công ty.\n\nYêu cầu ứng viên:\n- Chuyên ngành đào tạo: Tốt nghiệp Đại học chuyên ngành CNTT hoặc tương đương.\n- Kinh nghiệm làm việc, kiến thức chuyên môn và kỹ thuật: \n  - Từ 03 năm - 08 năm kinh nghiệm xây dựng và phát triển dự án trong lĩnh vực CNTT. \n  - Kinh nghiệm thiết kế hệ thống, thiết kế cơ sở dữ liệu, Design Pattern.\n  - Kinh nghiệm lập trình ứng dụng với Angular, .Net.\n  - Kinh nghiệm làm việc với một trong các hệ thống CSDL như: Oracle, MS SQL Server, PostgreSQL …\n- Ưu tiên ứng viên có kinh nghiệm và kiến thức chuyên môn sau:\n  - Kinh nghiệm xây dựng các ứng dụng trên nền tảng Cloud Native / kiến trúc Microservice.\n  - Kinh nghiệm triển khai các ứng dụng trên Container / Docker cho môi trường Windows & Linux.\n  - Kinh nghiệm và hiểu biết về các yêu cầu bảo mật trên môi trường Cloud.\n  - Quen thuộc với Continuous Integration / Continuous Deployment.\n  - Tiếng Anh giao tiếp, đọc hiểu tốt. \n  - Khả năng làm việc độc lập và chịu áp lực trong môi trường nhịp độ cao.\n  - Kỹ năng phân tích, phản biện, tư duy logic và giải quyết vấn đề tốt.\n  - Đã tham gia xây dựng, phát triển, triển khai các giải pháp liên quan trong lĩnh vực CNTT cho ngành Tài chính, Ngân hàng là một lợi thế lớn.\n\nQuyền lợi:\n- Phúc lợi và chế độ đãi ngộ:\n  - Lương thỏa thuận: cạnh tranh với thị trường ở vị trí công việc.\n  - Thưởng theo kết quả kinh doanh, thưởng các dịp đặc biệt, các ngày lễ lớn.\n  - Xét tăng lương hàng năm theo thành tích đóng góp. Được xem xét ngay khi bạn là một nhân viên xuất sắc mà không cần chờ tới đánh giá định kỳ.\n  - Điều kiện làm việc linh hoạt.\n  - 12 ngày phép/năm + phép thâm niên.\n  - Môi trường sáng tạo, năng động, cởi mở.\n  - Hoạt động gắn kết, du lịch, team building … thường xuyên theo năm.\n  - Chương trình Bảo hiểm sức khỏe cao cấp theo cấp bậc và thâm niên.\n  - Cơ hội thăng tiến lên vị trí Quản lý.\n  - Hưởng đầy đủ các chế độ đãi ngộ khác theo quy định của pháp luật.\n  - Thời gian làm việc: Sáng: 8h00-12h00 (từ thứ 2 - thứ 6).\n\nMôi trường làm việc:\n- Môi trường làm việc năng động, cởi mở.\n- Cơ hội thăng tiến, phát triển sự nghiệp.\n- Ghi nhận sáng kiến, tôn trọng sự khác biệt.\n- Cơ hội tham gia vào các dự án công nghệ tài chính lớn.\n\nĐịa điểm làm việc:\n- Hà Nội: 74 Khúc Thừa Dụ, Dịch Vọng, Cầu Giấy.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3069, 1481, 2, 'Lập Trình Wordpress Developer', '• Thiết kế, lập trình và phát triển các website trên nền tảng Wordpress.\n• Tối ưu hóa hiệu suất, bảo mật và SEO cho các trang web Wordpress.\n• Phát triển và tùy chỉnh các plugin và theme theo yêu cầu.\n• Quản lý và bảo trì các trang web hiện tại, đảm bảo hoạt động ổn định và hiệu quả.\n• Quản lý server, hosting và bảo mật hệ thống website của công ty.\n• Tích hợp các giải pháp thanh toán và dịch vụ bên thứ ba vào trang web.\n• Chịu trách nhiệm xây dựng và tối ưu hóa các website vệ tinh thuộc Flexhouse VN.\n• Hợp tác với các bộ phận khác để đảm bảo chất lượng và tiến độ dự án.\n\n• Tốt nghiệp Đại / Cao đẳng chuyên ngành công nghệ thông . Có ít nhất 2 năm kinh nghiệm làm việc với Wordpress, bao gồm thiết kế và phát triển nhiều website.\n• Thành thạo HTML, CSS, JavaScript, PHP và MySQL.\n• Am hiểu về SEO, tối ưu hóa tốc độ trang web và các tiêu chuẩn web.\n• Kinh nghiệm phát triển theme và plugin Wordpress tùy chỉnh.\n• Kỹ năng bảo mật để bảo vệ trang web khỏi các cuộc tấn công.\n• Kinh nghiệm quản lý server và hosting cho các trang web.\n• Kỹ năng giải quyết vấn đề, quản lý thời gian và làm việc độc lập tốt.\n• Kỹ năng giao tiếp tốt với khách hàng và khả năng viết tài liệu kỹ thuật.\n• Am hiểu về thiết kế giao diện và trải nghiệm người dùng (UX/UI).\n• Sử dụng thành thạo các công cụ phát triển như Git và nắm bắt xu hướng công nghệ web mới.\n\n• Mức lương từ 15 đến 17 triệu VNĐ/tháng.\n• Thưởng theo hiệu suất công việc, lương tháng 13.\n• Tham gia hoạt động team building, du lịch hàng năm.\n• Tham gia vào các dự án đa dạng, có cơ hội phát triển nghề nghiệp.\n• Môi trường làm việc chuyên nghiệp, thân thiện.\n• Các chế độ phúc lợi khác theo quy định của công ty.\n\nĐịa điểm làm việc: Hồ Chí Minh: 101 Bưng Ông Thoàn, P.Phú Hữu, Thủ Đức\n\nThời gian làm việc: Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3070, 1230, 2, 'Senior FE (70% Angular+30% ReactJS)', 'Mô tả công việc:\n- Build UI components for maximum performance and reusability\n- Participate in code reviews and contribute to team knowledge sharing.\n- Troubleshoot and debug applications.\n- Stay up-to-date with the latest industry trends and technologies.\n- Go onsite\n\nYêu cầu ứng viên:\n- At least 4-5 years of experience in web development technologies & have in-depth knowledge of Angular 2+, Reactjs, Javascript.\n- Familiarity with state management libraries (such as NgRx)\n- Ability to present the problem easy to understand, always ready to support the team\n- Knowledge of RESTful APIs and web services.\n- Experience with GIT source control, Agile process\n- Strong problem-solving skills and attention to detail.\n- Good communication and teamwork skills.\n- Eagerness to learn and adapt to new technologies.\n- Experience working with Taiga UI and micro-frontend is an advantage\n\nQuyền lợi:\n- Attractive remuneration package (competitive salary, bonus)\n- Salary review twice a year\n- Social Insurance, Health insurance, Unemployment insurance in accordance with Vietnam Labor Law\n- 12 Annual Leaves & 10 Sick Leaves per year; \n- Flexible training programs\n- Very good working environment with 3 core values: Collaboration as methodology & Behave like family; Compete by high quality\n- Company trip, Monthly happy hour and other interesting activities\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 3 Cenxspace, Tòa Nhà Dolphin 28 Trần Bình, Mĩ Đình 2, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3071, 1173, 2, 'Blockchain Developer (Có Kinh Nghiệm Frontend)', 'Mô tả công việc\n- Tham gia phát triển Frontend của ứng dụng Web hiện đại, giàu tương tác với yêu cầu cao về chất lượng và độ tin cậy\n- Viết chương trình, lập kế hoạch, thiết kế module chức năng, xây dựng công cụ cài đặt, viết thử nghiệm\n- Sử dụng một trong số các thư viện hoặc framework: VueJS / ReactJS / Angular,...\n- Phát triển các tính năng mới cho sản phẩm theo yêu cầu\n- Thực hiện các nhiệm vụ được giao từ cấp quản lý trực tiếp\n- Tham gia phát triển các dự án liên quan đến Blockchain với các chain mới hoặc các sản phẩm research của công ty\n\nYêu cầu ứng viên\n- Từ 2 năm kinh nghiệm làm Frontend Developer thành thạo một trong các js framework sau: Angular, Vue JS, React JS, Electro JS, Ember JS,.. (Ưu tiên ReactJS, VueJS)\n- Có ít nhất 6 tháng kinh nghiệm làm việc với Web3 và Blockchain.\n- Nắm vững kiến thức lập trình cơ bản, lập trình hướng đối tượng\n- Thao tác với các hệ quản trị cơ sở dữ liệu\n- Nắm vững mô hình web MVC, MVVM\n\nQuyền lợi\n- Mức lương: upto 20M\n- Định kỳ review lương 6 tháng/1 lần\n- Lương tháng 13 và các khoản thưởng bonus khác\n- Thưởng các ngày lễ: 30/4, 2/9, Tết Dương Lịch. Quà sinh nhật công ty, quà sinh nhật cá nhân\n- Hưởng 15 ngày phép/năm.\n- Tham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động Việt Nam\n- Khám sức khỏe định kì tại các bệnh viện uy tín (Hồng Ngọc, Thu Cúc, Vinmec...)\n- Du lịch hè 1-2 lần/năm, team building định kỳ hàng quý\n- Đọc sách miễn phí tại thư viện sách của Công ty\n- Hưởng mọi quyền lợi hỗ trợ các chứng chỉ ngoại ngữ và chứng chỉ nghiệp vụ chuyên ngành như: Chứng chỉ tiếng Nhật, chứng chỉ AWS, ISTQB...\n\nĐịa điểm làm việc\n- Hà Nội: 22F Tháp B, Tòa HH4 Sông Đà, Phạm Hùng, Mỹ Đình 1, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3072, 529, 2, 'Junior Frontend Developer (Fulltime)', 'Mô tả công việc\n- Tham gia thiết kế, xây dựng nền tảng học tập cho trung tâm đào tạo IELTS IZONE. Phụ trách phát triển các dự án EdTech tại IZONE.\n- Xây dựng các tính năng cho giao diện người dùng tuân theo các tiêu chuẩn thiết kế, đảm bảo khả năng bảo trì và mở rộng.\n- Bảo trì và hoàn thiện các vấn đề còn tồn đọng và đề xuất cải thiện.\n- Thu thập ý kiến phản hồi và xây dựng các hướng giải quyết cho người sử dụng và khách hàng để cải tiến và nâng cao chất lượng dự án.\n- Là cầu nối giữa việc việc thiết kế và xây dựng mã nguồn, phối hợp giữa các bên để đem tới cho người dùng sản phẩm tốt nhất.\nNội dung TECH liên quan:\n- React kết hợp với CSS framework Tailwind.\n- Quản lý data model với MobX \n- Java, Postgres và Redis ở Backend\n- Git\n- Design system với các thư viện React UI Component\n- Prosemirror-based content editor\n\nYêu cầu ứng viên\n- Có trên 1 năm kinh nghiệm làm việc ở vị trí Frontend Engineer\n- Có kiến thức chuyên môn về HTML, CSS và JavaScript & Typescript\n- Có kinh nghiệm chuyên môn về framework web ReactJS\n- Nắm vững các khái niệm cốt lõi về web và trình duyệt (ví dụ: cách trình duyệt phân tích cú pháp HTML  và xây dựng một trang web)\n- Có kiến thức, hiểu biết sâu và kinh nghiệm làm việc với design system.\n- Có thể phân tích bug và đề xuất giải pháp cho các module phần mềm từ cơ bản đến phức tạp\n\nQuyền lợi\n- Thu nhập: 12.500.000 - 15.000.000 VNĐ /tháng\n- Cung cấp trang thiết bị làm việc\n- Review lương định kỳ, tháng lương thứ 13 cho nhân sự\n- Nghỉ phép 12 ngày/năm\n- Đóng BHXH đầy đủ\n- Môi trường startup năng động, chuyên nghiệp, tư duy mở, không giới hạn các việc đề xuất, phát triển ý tưởng.\n- Học miễn phí các khoá học IELTS tại trung tâm.\n\nĐịa điểm làm việc\n- Hà Nội: Số 4 ngõ 95 Hoàng Cầu, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3073, 209, 2, 'Low-Code Developer', '- We are looking for an enthusiastic and eager Junior Salesforce/Outsystems/Servicenow Developer to join our growing team. This is an excellent opportunity for individuals with a foundational understanding of software development principles who are keen to learn and build applications using the low-code platform. You will work alongside experienced developers, contributing to the development and maintenance of our applications while gaining valuable hands-on experience.\n\nYêu cầu ứng viên:\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field\n- Basic understanding of software development concepts and methodologies.\n- Familiarity with web technologies such as HTML, CSS, and JavaScript is a plus.\n- Basic knowledge of relational databases and SQL.\n- Strong logical thinking and problem-solving skills.\n- Eagerness to learn and work with the Salesforce/Outsystems/Servicenow platform.\n- Good communication and teamwork skills.\n- Strong analytical and problem-solving skills.\n- Fluency in English (both written and verbal)\n\nQuyền lợi:\n- Attractive income package as negotiation.\n- Global and inclusive workplace with monthly cross-cultural events.\n- International exposure and career growth across global locations.\n- Work-life balance benefits supporting employee well-being.\n- Private health insurance with optional family coverage.\n- Summer vacation allowance.\n- Sponsored training courses for personal growth.\n- Comprehensive relocation package.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Lô E3 Đ. Võ Chí Công, Quận 9\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3074, 1282, 2, 'Nhân Viên Lập Trình .Net', 'Mô tả công việc\n- Lập trình và tích hợp (front-end và back-end);\n- Viết tài liệu mô tả chức năng phần mềm;\n- Xử lý phản hồi từ người dùng;\n- Nghiên cứu tối ưu hóa sản phẩm, dịch vụ đã phát triển;\n- Bảo trì và hỗ trợ các vấn đề liên quan đến chuyên môn.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành khác am hiểu về Lập trình\n- Có ít nhất 1 năm kinh nghiệm lập trình sử dụng công nghệ .NET Core (C#, ASP.NET Core, EF Core, LinQ, Restful API, WCF, SOAP)\n- Có kiến thức về Javascript, Typescript, HTML5/CSS3, Ajax, jQuery, React, Angular, Vue\n- Có kinh nghiệm với các công cụ build hiện đại (Docker, CI/CD,...).\n- Kinh nghiệm với các công cụ quản lý mã nguồn như Git, Gitlab\n- Database: SQL Server, Oracle, PostgreSQL;\n- Có khả năng research tài liệu và đọc tài liệu.\n- Có kinh nghiệm và sản phẩm là một lợi thế;\n- Có khả năng phân tích, sáng tạo, chịu được áp lực công việc; có tinh thần học hỏi, hợp tác trong công việc;\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực và kinh nghiệm. Xét tăng lương định kỳ hàng năm hoặc trước hạn theo tình hình đánh giá;\n- Được hưởng các chế độ BHYT, BHXH theo quy định của nhà nước; các chính sách phúc lợi của Công ty: Phép năm; Lương thưởng; Quà tết, thưởng lễ; Du lịch...\n- Làm việc trong môi trường chuyên nghiệp, trẻ trung, năng động, hòa đồng, phát huy tối đa khả năng chủ động sáng tạo của nhân viên;\n- Được trang bị đầy đủ trang thiết bị phục vụ công việc;\n- Được trau dồi kỹ năng về nghiệp vụ và kỹ năng mềm;\n- Được tham gia, đóng góp vào các dự án phát triển có quy mô lớn, lâu dài;\n- Thưởng theo thành tích làm việc.\n\nĐịa điểm làm việc\n- Hà Nội: 101 Láng Hạ, Đống Đa\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3075, 72, 2, 'Python Developer Leader', '• Phát triển và duy trì ứng dụng phần mềm sử dụng Python (Django), bao gồm thiết kế, lập trình, thử nghiệm và triển khai theo định hướng công ty.\n• Tham gia phát triển và xây dựng dự án FPT Medicare.\n• Tham gia vào toàn bộ vòng đời phát triển phần mềm, từ phân tích yêu cầu đến triển khai sản phẩm, phát triển tính năng mới, tối ưu hóa perfomance và bảo mật nền tảng, đảm bảo hệ thống hoạt động ổn định, tin cậy.\n• Xây dựng và tối ưu hóa các API, microservices và hệ thống.\n• Hỗ trợ phát triển các API và các dịch vụ microservices để tích hợp với các nền tảng đối tác.\n• Làm việc với các công nghệ liên quan đến xử lý dữ liệu và trí tuệ nhân tạo.\n• Hỗ trợ việc tích hợp các hệ thống phần mềm khác nhau.\n• Tham gia vào quá trình đánh giá và lựa chọn công nghệ phù hợp cho dự án.\n• Phối hợp với các thành viên trong nhóm và các bộ phận liên quan để đảm bảo dự án được thực hiện hiệu quả.\n• Thực hiện các công việc khác theo yêu cầu của Trưởng bộ phận.\n\n• Nam/Nữ đã tốt nghiệp Đại học trở lên chuyên Ngành Công Nghệ Thông Tin.\n• Có ít nhất 03 năm kinh nghiệm & thành thạo ngôn ngữ lập trình Python.\n• Có kinh nghiệm làm việc ít nhất 01 năm với một trong các framework Python sau: Django/ Fast API/ Starlette, ...\n• Có kinh nghiệm làm việc với các hệ cơ sở dữ liệu: MySQL, PostgreSQL, MongoDB.\n• Thành thạo nguyên tắc lập trình hướng đối tượng (OOP), các kiến thức về thiết kế phần mềm và có kỹ năng lập trình theo mô hình MVC.\n• Có kinh nghiệm làm việc với RESTful API.\n• Có kinh nghiệm làm việc với hệ thống message queue như Celery, Redis queue, Dramatiq,...\n• Có kinh nghiệm làm việc với Docker và các web server: Nginx, Apache.\n• Có kinh nghiệm làm việc với Kibana, Elasticsearch, Kafka, và các công cụ CI/CD.\n• Có hiểu biết về các kiến trúc phát triển phần mềm: Microservices, Monolithic, microservices architecture và event driven programming paradigm.\n• Có hiểu biết về queue như Redis, RabbitMQ, Apache Kafka, Memcached.\n• Có kiến thức cơ bản về HTML/CSS/Javascript/Jquery/ Web services/ OAuth2\n• Thành thạo công cụ quản lý mã nguồn Git. Viết tài liệu cho API.\n• Có hiểu biết về Linux, Ubuntu là một lợi thế.\n• Sử dụng công cụ quản lý kiểm thử và bug tracking.\n• Sử dụng các công cụ như JIRA, Taiga, hoặc Redmine để quản lý công việc\n• Hiểu biết về các phương pháp phát triển phần mềm: Kiến thức về Agile, Scrum, Kanban và có kỹ năng tham gia vào các sprint, daily stand-up meetings, và review meeting.\n• Có khả năng tư duy, làm việc nhóm. Có khả năng giao tiếp tốt.\n• Có khả năng đọc hiểu các tài liệu tiếng Anh.\n• Thích tìm hiểu, nghiên cứu các công nghệ lập trình mới.\n\n• Gói thu nhập cạnh tranh. Lương tháng 13.\n• Đầy đủ các chế độ theo luật lao động hiện hành.\n• Chính sách phúc lợi theo quy định của Công ty đa dạng: Chăm sóc sức khỏe định kì hàng năm; Gói bảo hiểm sức khỏe chuyên biệt (FPT Care – Khám chữa bệnh miễn phí tại tất cả các bệnh viện); Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân ...\n• Môi trường làm việc thân thiện, cởi mở.\n• Cơ sở vật chất và công cụ làm việc hiện đại, tiện nghi.\n• Nhiều cơ hội phát triển và thăng tiến.\n• Văn hóa Doanh nghiệp đặc sắc, sinh động bậc nhất với nhiều các hoạt động hấp dẫn: tân binh, teambuilding, thi trạng, hội làng, hội diễn Sao Chổi, sinh nhật FPT, ngày 08/03, ngày 11/11...\n• Hưởng các gói ưu đãi cước khi sử dụng dịch vụ của FPT Telecom.\nGhi chú: FPT Telecom không thu bất kỳ chi phí nào của Ứng viên, Sinh viên trong quá trình tuyển dụng, thực tập.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Quận 7\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3076, 1301, 2, 'Kỹ Thuật Viên Lập Trình Và Vận Hành Máy CNC', '- Xây dựng bản vẽ, quy trình công nghệ để gia công chi tiết.\n- Tối ưu quy trình công nghệ, đạt hiệu quả gia công về thời gian, chất lượng, tối ưu dụng cụ cắt gọt.\n- Thực hiện lập trình & xuất chương trình và gia công.\n- Điều chỉnh, sửa chương trình ngay khi phát hiện sự cố, đảm bảo thời gian chạy máy CNC.\n- Định mức thời gian hoàn thành mỗi công đoạn gia công: Phay, Tiện\n- Thực hiện các công việc khác khi được cấp trên yêu cầu.\n\nYêu cầu ứng viên\n- Tốt nghiệp trung cấp trở lên, nhanh nhẹn, nhiệt tình trong công việc;\n- Đọc tốt bản vẽ kỹ thuật, Lập trình 2D+3D. Sử dụng thành thạo phần mềm CAD/CAM.\n- Có kinh nghiệm ít nhất 1 năm về thiết kế, lập trình máy CNC; 2 năm vận hành máy CNC.\n- Có đam mê với nghề kỹ thuật.\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, Hass.\n\nQuyền lợi\n- Có cơ hội phát triển nghề nghiệp tại công ty.\n- Làm việc trong môi trường năng động, chuyên nghiệp;\n- Cung cấp đồng phục, trang thiết bị đầy đủ để phục vụ công việc;\n- Thưởng các dịp Quốc tế Lao động 1/5, Quốc khánh 2/9, Tết dương lịch, Thưởng Tết theo quy định của công ty.\n- Được đóng đầy đủ BHXH, BHYT, BHTN;\n- Đi du lịch nghỉ mát hàng năm;\n- Tham gia các hoạt động văn hoá thể thao (bóng đá, chạy...);\n- Hỗ trợ ăn cơm trưa tại Công ty;\n- Hỗ trợ tiền điện thoại, công tác phí khi đi gặp Khách Hàng, đi công tác;\n- Nghỉ chủ nhật và 1 thứ 7 trong tháng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3077, 1207, 2, 'Visual Basic Developer', '- Tham gia phát triển, bảo trì và nâng cấp các dự án sử dụng VB6, VB.NET.\n- Phân tích yêu cầu nghiệp vụ, đề xuất giải pháp kỹ thuật phù hợp.\n- Phối hợp với các bộ phận liên quan trong quá trình triển khai và vận hành hệ thống.\n- Thực hiện kiểm thử, sửa lỗi và cải tiến theo phản hồi người dùng.\n- Tham gia vào các dự án tích hợp với hệ thống viết bằng các ngôn ngữ khác như JAVA, PHP (nếu có kinh nghiệm liên quan).\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của Leader.\n\nYêu cầu ứng viên:\n- Trình độ đại học, cao đẳng chuyên ngành CNTT hoặc các chứng chỉ tương đương trở lên\n- Tối thiểu 2 năm kinh nghiệm làm việc với VB6 và VB.NET.\n- Ưu tiên ứng viên kinh nghiệm với Java, PHP, đặc biệt là trong các dự án tích hợp đa nền tảng.\n- Có ít nhất 2 năm kinh nghiệm làm việc với Oracle, SQL, hoặc các hệ quản trị cơ sở dữ liệu khác.\n- Biết sử dụng công cụ quản lý phiên bản mã nguồn như Git, SVN.\n- Có khả năng phân tích nghiệp vụ, tư duy logic tốt.\n- Có khả năng làm việc độc lập cũng như làm việc nhóm hiệu quả.\n- Ứng viên từng làm dự án với khách hàng Nhật là một lợi thế\n\nQuyền lợi:\n- Mức lương: từ 20-50 triệu/tháng, tùy theo kinh nghiệm.\n- Thử việc lên đến 100% lương\n- Phụ cấp cơm trưa và vé gửi xe hàng tháng\n- Cung cấp đầy đủ các thiết bị phục vụ cho công việc\n- Nghỉ thứ 7, chủ nhật\n- Đóng BHXH sau khi thử việc, hưởng các chế độ phúc lợi theo luật lao động Việt Nam\n- Đánh giá xét tăng lương 2 lần/năm\n- Hưởng lương tháng 13\n- Được tham gia các Câu lạc bộ dưới sự tài trợ chính thức của Công ty: CLB Bóng đá, tham gia các bữa tiệc sinh nhật, team building hàng quý, company trip hàng năm,...\n- Cơ hội thăng tiến cao, cơ hội rất lớn để trở thành key member của công ty.\n- Cơ hội đi công tác và làm việc tại Nhật Bản nếu đáp ứng được năng lực tốt.\n- Môi trường trẻ trung, năng động, chuyên nghiệp theo tiêu chuẩn chất lượng Nhật Bản.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4 Tòa nhà H10, số 2 ngõ 475 Nguyễn Trãi, Thanh Xuân\n- Hồ Chí Minh: 25/7 Nguyễn Bỉnh Khiêm, Phường Bến Nghé, Quận 1\n- Đà Nẵng: 88 An Hải Đông 1, An Hải Đông, Sơn Trà\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Thanh Xuân, Hồ Chí Minh, Quận 1, Đà Nẵng, Sơn Trà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3078, 1392, 2, 'Nhân Viên IT Phần Mềm', 'Mô tả công việc:\n- Xây dựng các hệ thống, công cụ dùng để quản lý, tối ưu hóa công việc trong nội bộ Công ty theo yêu cầu từ Công ty mẹ.\n- Cải tiến web nội bộ của công ty, thực hiện các yêu cầu nội bộ.\n- Đào tạo các thao tác liên quan đến hệ thống quản lý nội bộ cho nhân viên trong công ty.\n\nYêu cầu ứng viên:\n- Có từ 2 năm kinh nghiệm liên quan.\n- Sử dụng thành thạo một trong các hệ quản trị cơ sở dữ liệu MS SQL Server, Postgre SQL, Oracle...\n- Có kiến thức chuyên môn về: OOP, Database & Code Design, .Net, Entity Framework, Javascript, Jquery, Typescript, Angular, Bootstrap.\n- Thành thạo một trong các công cụ quản lý mã nguồn: GIT, SVN ...Có tư duy tốt về UI/UX.\n- Khả năng nắm bắt, nghiên cứu công nghệ mới nhanh.\n- Tư duy lập trình tốt, đam mê và mong muốn học hỏi trong lĩnh vực IT.\n- Có kỹ năng đọc hiểu tài liệu thiết kế phầm mềm.\n- Có khả năng giải quyết vấn đề độc lập cao.\n- Có hiểu biết về kiểm thử phần mềm (Unit Test, Integration Test) là một lợi thế.\n- Có thể giao tiếp Tiếng Anh cơ bản. Biết tiếng Nhật là một lợi thế.\n- Ưu tiên ứng viên có kinh nghiệm lập trình App Mobile.\n\nQuyền lợi:\n- Cơ hội công việc:\n- Thường xuyên được tham gia các buổi đào tạo của Công ty và bộ phận, qua đó nâng cao được kiến thức và kỹ năng công việc của bản thân.\n- Có cơ hội sử dụng các phần mềm và thiết bị hiện đại.\n- Thông qua mối liên hệ với các cơ sở trên toàn cầu của Công ty và công tác nước ngoài có thể mở rộng hiểu biết ra thế giới.\n- Lợi ích và các chế độ phúc lợi xã hội:\n- Được tham gia BHXH, BHYT, BHTN, bảo hiểm 24/7 và các chế độ khác theo luật định.\n- Thời gian làm việc: Từ 8:00-17:00, nghỉ 03 thứ Bảy & các Chủ nhật trong tháng, nghỉ lễ Tết theo quy định Luật Lao động.\n- Có phụ cấp đi lại (600,000VNĐ/tháng)/ xe công ty đưa đón, ăn trưa tại Công ty.\n- Tổ chức tiệc sinh nhật, Free Lunch hằng tháng, thường xuyên tổ chức các hoạt động giao lưu cho nhân viên.\n- Du lịch hằng năm, thưởng 2 lần/năm.\n\nĐịa điểm làm việc:\n- Hải Phòng: Số 02 đường số 09 Khu Công nghiệp VSIP, Thủy Nguyên.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n- Làm việc từ thứ 2 đến thứ 6 và 1 thứ 7/ tháng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3079, 1171, 2, 'IOS Developer (Junior Level)', '-Key Responsibilities :\n- Develop high-quality iOS applications that are ready to be published in Tier-1 countries.\n- Collaborate with cross-functional teams, including designers, product managers, and backend developers, to ensure the best user experience.\n- Write clean, well-documented, and maintainable code.\n- Stay up to date with the latest trends and best practices in iOS development.\n- Assist in testing and debugging applications.\n\n-Requirements :\n- University degree in Computer Science, Software Engineering, or a related field.\n- Minimum of 1 year of experience in iOS development.\n- Proficiency in Swift.\n- Experience with UIKit, SwiftUI, Core Data, Realm.\n- Familiarity or experience with CoreImage, CoreML, AR/VR is a plus.\n- Familiar with version control systems such as Git.\n- Experience working with REST APIs.\n- Strong problem-solving and analytical skills.\n- Ability to work in a fast-paced environment\n\n-Benefits :\n- Competitive negotiable salary\n- Full benefits package (Health care insurance, Life Insurance, Social Insurance etc.)\n- Supportive team environment that values collaboration and growth\n- Company trips, Happy lunch (twice a month), Milk-tea fund...\n\nĐịa điểm làm việc: Đà Nẵng: Astraler Technology Co. Ltd - 6th Floor - Viet Nam Post Building - 271 Nguyen Van Linh street, Vinh Trung ward, Thanh Khe District, Danang, Thanh Khê\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3080, 15, 2, 'Lập Trình Viên Fullstack', 'Weldcom tuyển 03 chuyên viên lập trình, làm việc tại trụ sở chính số 285A Ngô Gia Tự, Long Biên, Hà Nội.\nChi tiết công việc: Lập trình các ứng dụng phần mềm phục vụ cho hoạt động sản xuất, kinh doanh của Công ty trên các nền tảng web, windows form. Cụ thể:\n- Phối hợp với các bộ phận khác để đưa ra ý tưởng cho các mẫu thiết kế phần mềm, ứng dụng mới.\n- Xây dựng phần mềm, ứng dụng mới bằng các ngôn ngữ lập trình thích hợp.\n- Phát triển và xây dựng các tính năng mới cho phần mềm.\n- Nâng cấp phần mềm và các hệ thống để đảm bảo tính bảo mật và hiệu quả hơn.\n- Phối hợp với nhóm Service Desk để viết tài liệu hướng dẫn sử dụng.\n- Kiểm tra và bảo trì các chương trình, ứng dụng định kỳ, tiến hành sửa lỗi khi có vấn đề xảy ra.\n- Triển khai và giới thiệu sản phẩm phần mềm tới khách hàng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp từ đại học chuyên ngành công nghệ thông tin, phần mềm....\n- Sử dụng một số ngôn ngữ lập trình:.NET/C#, Java, Python, Web Service\n- Có kiến thức về SQL, MSSQL\n- Lập trình với hệ CSDL: MSSQL, MySQL, Postgres, Oracle\n- Thành thạo HTML, CSS, Bootstrap, Javascript, Jquery (Ưu tiên sử dụng ReactJs)\n- Kinh nghiệm sử dụng GIT như GitHub/GitLab, Docker container\n- Có khả năng phân tích, tổng hợp dữ liệu ở các nguồn dữ liệu khác nhau.\n- Kỹ năng làm việc độc lập, làm việc nhóm tốt.\n- Hoạt bát, siêng năng, trung thực, chịu áp lực công việc.\n- Ưu tiên có kinh nghiệm triển khai các giải pháp phần mềm quản trị doanh nghiệp đặc biệt các doanh nghiệp có yếu tố sản xuất, xây dựng các phần mềm, thiết kế database, big data.\n\nQUYỀN LỢI ĐƯỢC HƯỞNG:\n- Thu nhập 15 - 30 triệu( Gồm Lương + phụ cấp + thưởng.\n- Được tham gia chính sách phát triển nhân sự ưu việt: được cấp quỹ đào tạo hàng năm để chủ động tham gia các khóa học ngoài, được tham gia chương trình đào tạo inhouse. - Bảo hiểm xã hội đóng trên 100% lương.\n- Các chế độ phép năm, lễ tết,... theo đúng 100% quy định của pháp luật lao động\n- Được làm việc trong một môi trường coi trọng người lao động, văn hóa doanh nghiệp rõ nét. - Các chế độ phúc lợi đầy đủ. - Làm việc 5,5 ngày / tuần, nghỉ chiều thứ 7 và ngày chủ nhật.\n\nĐịa điểm làm việc:\n- Hà Nội: 285A Ngô Gia Tự, Long Biên, Long Biên.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3081, 1130, 2, 'Flutter Developer (Junior)', 'Mô tả công việc\n- Phân tích yêu cầu và thiết kế kiến trúc ứng dụng đa nền tảng.\n- Phát triển mã nguồn bằng ngôn ngữ Dart sử dụng Flutter.\n- Tối ưu hóa hiệu suất và đảm bảo ứng dụng tương thích trên cả iOS và Android.\n- Thực hiện công việc kiểm thử và đảm bảo chất lượng, sửa lỗi và cải tiến ứng dụng dựa trên phản hồi người dùng.\n- Làm việc chặt chẽ với các đội ngũ thiết kế, sản phẩm và backend.\n- Viết tài liệu kỹ thuật và comment mã nguồn.\n- Quản lý mã nguồn bằng các công cụ như Git, đảm bảo quy trình làm việc chuẩn và hiệu quả.\n- Tham gia họp dự án, báo cáo tiến độ và đề xuất giải pháp kỹ thuật khi cần thiết.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học ngành CNTT, ưu tiên ngành Công nghệ thông tin, Khoa học máy tính, Trí tuệ nhân tạo, hoặc các ngành liên quan.\n- Có 1 - 3 năm kinh nghiệm phát triển ứng dụng Flutter.\n- Thành thạo Dart và framework Flutter.\n- Kinh nghiệm với các công cụ phát triển Flutter như Android Studio, VS Code.\n- Hiểu biết về thiết kế UI/UX đa nền tảng.\n- Kinh nghiệm làm việc với API và dịch vụ backend.\n- Có kỹ năng giao tiếp và thuyết trình tốt, có khả năng làm việc nhóm tốt.\n- Có kỹ năng giải quyết vấn đề, xử lý tình huống tốt.\n- Có kỹ năng quản lý thời gian, sắp xếp công việc tốt.\n- Có khả năng làm việc độc lập và làm việc nhóm tốt.\n- Tận tâm, cầu thị có trách nhiệm, chủ động và tích cực trong công việc.\n- Thái độ tốt,lắng nghe, phản hồi tích cực, đổi mới và phát triển.\n\nQuyền lợi\n1.  Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án.\n- Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm theo năng lực.\n\n2.  Chế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n- Tham gia BHXH sau thử việc, 12 ngày phép năm.\n- Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ.\n- Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết...\n- Học miễn phí các sản phẩm ngôn ngữ của công ty.\n\n3.  Cơ hội phát triển bản thân:\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Môi trường product đi sâu chuyên môn về sản phẩm, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác marketing, sales, chăm sóc khách hàng và khách hàng.\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp.\n- Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6.\n\nĐịa điểm làm việc\n- Hà Nội: 315 Trường Chinh, Thanh Xuân.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3082, 72, 2, 'Python Developer', 'Mô tả công việc\n- Phát triển và cung cấp sản phẩm chất lượng cao với đầy đủ tính năng bằng cách tuân thủ các quy trình và tiêu chuẩn của phương pháp Agile.\n- Tham gia vào việc lập kế hoạch về năng lực dịch vụ và nhu cầu, phân tích hiệu suất sản phẩm phần mềm, điều chỉnh và tối ưu hóa.\n- Lên kế hoạch và triển khai đào tạo nâng cao trình độ, mindset cho fresher – junior.\n- Nghiên cứu các giải pháp Công nghệ trên thị trường để áp dụng vào dự án hoặc sản phẩm mới.\n- Báo cáo tiến độ, kết quả công việc của cá nhân.\nYêu cầu ứng viên\n- Tốt nghiệp Đại học Công nghệ thông tin/Khoa học máy tính/Hệ thống thông tin quản lý/Viễn thông. \n- Ít nhất 3 năm kinh nghiệm làm việc với Python.\n1, Kỹ năng chuyên môn:\n- Thành thạo HTTP, Web services, OAuth2, Restful APIs.\n- Thành thạo ít nhất một framework web như Django, Flask, FastAPI, Starlette...\n- Thành thạo áp dụng design patterns vào thực tế\n- Có kinh nghiệm về microservices architecture, event-driven programming paradigm.\n- Có kinh nghiệm làm việc với các framework như Celery, Dramatiq, Confluent Kafka, Pika, Kombu...\n- Có kinh nghiệm làm việc với hệ thống database như PostgreSQL, MongoDB, ELK stack, tối ưu hóa truy vấn cơ sở dữ liệu.\n- Hiểu biết về hệ thống message queue systems, distributed systems và các kỹ thuật liên quan (scaling, load balacing, sharding, replication)\n- Có kinh nghiệm đánh giá, đo kiểm hiệu năng sản phẩm, tối ưu hóa code, truy vấn cơ sở dữ liệu, cache, xử lý đồng thời (concurrency), song song (parallel)\n2, Kỹ năng mềm:\n- Kỹ năng làm việc nhóm và làm việc độc lập tốt. \n- Chủ động, nhiệt tình và trách nhiệm với công việc, có khả năng làm việc độc lập và thúc đẩy các dự án của riêng mình. \n- Chịu được áp lực về mặt thời gian và sẵn sàng OT khi dự án cần.\n- Ham học hỏi, nghiên cứu, có tinh thần sáng tạo.\nƯU TIÊN ỨNG VIÊN:\n+ Có kinh nghiệm triển khai vận hành với nền tảng containerization (Docker, Kubernetes), hệ điều hành Unix/Linux\n+ Có kinh nghiệm thiết lập monitoring, observability với Prometheus, Grafana, ELK,...\n+ Thành thạo các công cụ đo kiểm và tối ưu hiệu suất hệ thống (profiling, benchmarking, tracing, logging).\n+ Có kinh nghiệm sử dụng và tích hợp AI vào ứng dụng web như chatbot AI, tự động hóa quy trình xử lý dữ liệu, gợi ý nội dung, tìm kiếm thông minh, phân tích dữ liệu người dùng.\n+ Có kinh nghiệm thiết kế kiến trúc hệ thống, đảm bảo tính mở rộng, hiệu suất và khả năng bảo trì lâu dài.\nQuyền lợi\n- Mức lương từ 35 - 45 triệu/tháng\n- Gói thu nhập năm tương xứng với năng lực (13 tháng lương, nghỉ mát...). \n- Cơ hội làm việc và phát triển tại FPT, Công ty tiên phong chuyển đổi số và dẫn đầu về tư vấn, cung cấp, triển khai các dịch vụ, giải pháp công nghệ - viễn thông.\n- Được đào tạo nghiệp vụ và kỹ năng liên tục, được tham gia các chương trình huấn luyện chuyên nghiệp.\n- Môi trường làm việc công bằng, minh bạch, thân thiện, cởi mở, năng động và trẻ trung\n- Cơ sở vật chất, công cụ làm việc hiện đại, tiện nghi, ứng dụng công nghệ, chuyển đổi số toàn trình.\n- Văn hóa doanh nghiệp đa dạng, phong phú; các hoạt động tri ân, chăm lo đời sống tinh thần Cán bộ nhân viên và người thân, Teambuilding, Ngày hội văn hóa, các Câu lạc bộ, Nghỉ hè,....\n- Tham gia đầy đủ các chế độ theo Luật lao động hiện hành (BHXH, BHYT, BHTN, ngày phép); Khám sức khỏe định kỳ, nghỉ hè hàng năm; Gói bảo hiểm sức khỏe chuyên biệt FPT Care (ngân sách >65 triệu/năm/cán bộ nhân viên dành cho việc khám và chữa bệnh Nội, Ngoại trú.)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3083, 1355, 2, 'Kỹ Sư Lập Trình Thiết Bị Đo Lường & JIG TEST', 'Mô tả công việc\n- Phát triển phần mềm giao tiếp với các thiết bị đo lường, kiểm tra chất lượng sản phẩm (ATE, DAQ, PLC, đồng hồ đo điện, cảm biến...).\n- Thiết kế, lắp đặt và vận hành hệ thống jig test phục vụ sản xuất, R&D hoặc kiểm tra end-of-line.\n- Tham gia vào quá trình tích hợp phần mềm, phần cứng và xây dựng các giải pháp tự động hóa kiểm tra.\n- Phối hợp với các bộ phận liên quan để làm rõ yêu cầu kỹ thuật, hỗ trợ khắc phục sự cố, bảo trì thiết bị đo lường và jig test.\n- Đào tạo, chuyển giao công nghệ cho đội vận hành và kỹ thuật viên.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học các ngành: Tự động hóa, Điện - Điện tử, Cơ điện tử, Công nghệ thông tin hoặc các ngành liên quan.\n- Có kinh nghiệm lập trình giao tiếp với các thiết bị đo lường qua các giao thức như RS232/485, LAN, USB, GPIB, CAN, Modbus, v.v.\n- Thành thạo một trong các ngôn ngữ lập trình: Python, C#, C++, LabVIEW, hoặc tương đương. Có hiểu biết về thiết kế mạch điện, hệ thống điều khiển, cảm biến, actuator, và các hệ thống đo lường.\n- Ưu tiên ứng viên có kinh nghiệm thực tế trong việc xây dựng jig test, hệ thống kiểm tra tự động, hoặc từng làm việc trong môi trường sản xuất công nghiệp.\n- Kỹ năng giải quyết vấn đề, tư duy logic và khả năng làm việc độc lập/tập thể tốt.\n- Đọc hiểu tài liệu tiếng Anh kỹ thuật.\n\nQuyền lợi\n- Thu nhập hấp dẫn, thưởng theo hiệu quả công việc.\n- Môi trường làm việc năng động, chuyên nghiệp, cơ hội phát triển và thăng tiến.\n- Được đào tạo, tham gia các dự án lớn cùng các chuyên gia đầu ngành.\n- Chế độ bảo hiểm, phúc lợi đầy đủ theo quy định.\n\nĐịa điểm làm việc\n- Hà Nội: Trung Kính, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Từ thứ 2 đến thứ 6\n- Nghỉ thứ 7 - Chủ nhật\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3084, 1459, 2, 'Management Trainee Digital Channel Program - 1Y560', 'Giới thiệu về chương trình Management Trainee tại MSB: Là ngân hàng đầu tiên tại Việt Nam triển khai chương trình Management Trainee (Quản trị viên Tài năng), qua 07 mùa từ 2011, MSB tự hào mang đến bệ phóng sự nghiệp lý tưởng cho sinh viên mới tốt nghiệp. Chương trình đã đào tạo thành công nhiều lãnh đạo cấp cao hiện tại của MSB.\nTại MSB, bạn sẽ được tham gia chương trình đào tạo bài bản, chuyên sâu với lộ trình phát triển rõ ràng qua 04 kỳ luân chuyển tại nhiều phòng ban trong 24 tháng, giúp bạn khám phá tiềm năng và tích lũy kinh nghiệm toàn diện. Bạn sẽ được hướng dẫn bởi lãnh đạo cấp trung, lãnh đạo cấp cao và nhận được chế độ đãi ngộ hấp dẫn, từ đó xây dựng sự nghiệp vững chắc cho bản thân.\nGiới thiệu về Digital Channel Program: Chương trình xây dựng nền tảng giao dịch số Internet Banking/Mobile Banking đẳng cấp dành cho Khách hàng của Ngân hàng Bán lẻ/Ngân hàng Doanh nghiệp. Đóng vai trò là động lực tăng trưởng cho thu hút khách hàng mới và thúc đẩy chuyển đổi giao dịch từ chi nhánh sang kênh online.\nDigital Channel đặt ra mục tiêu xây dựng nền tảng kỹ thuật số hàng đầu cho ngân hàng:\n• Đáp ứng tính ổn định, khả năng mở rộng và đảm bảo tính tin cậy cho toàn bộ hoạt động kinh doanh.\n• Triển khai nền tảng chung cho ứng dụng di động (Mobile banking), ngân hàng trực tuyến (internet banking) và các ứng dụng trực tuyến khác cho RB & EB.\n• Digital Channel hướng đến trải nghiệm người dùng trực quan, liền mạch ứng dụng trong việc thu hút và giữ chân khách hàng, bán hàng và phục vụ khách hàng, liên tục bàn giao các sản phẩm thông qua DevSecOps.\n• Cho phép khách hàng tự phục vụ mọi lúc, mọi nơi.\n• Chương trình dự định sẽ chia làm 03 giai đoạn chính: Giai đoạn thiết kế, Giai đoạn triển khai phát triển và Giai đoạn mở rộng.\n\nYêu cầu ứng viên:\n• Tốt nghiệp chuyên ngành Tài chính – Ngân hàng hoặc các ngành liên quan.\n• Ưu tiên ứng viên có kiến thức hoặc bằng cấp bổ trợ về Công nghệ Thông tin, Agile, hoặc Design Thinking.\n• Có tư duy đổi mới, khả năng quan sát và xây dựng hành trình khách hàng hiệu quả.\n• Yêu thích sáng tạo, có định hướng phát triển trong môi trường công nghệ và kinh doanh số.\n\nQuyền lợi:\n• Lộ trình 24 tháng với 4 vòng luân chuyển tại các phòng ban trọng điểm.\n• Nhận mức lương khởi điểm hoàn toàn khác biệt, kí hợp đồng lao động chính thức và chế độ đãi ngộ hấp dẫn top ngành Ngân hàng.\n• Trải nghiệm thực tiễn tại các dự án chuyển đổi chiến lược.\n• Đào tạo chuyên sâu theo chương trình đào tạo được thiết kế riêng & Đồng hành bởi các mentor là lãnh đạo cấp cao.\n• Cơ hội "fast-track" trở thành lãnh đạo trong 02 năm.\n\nĐịa điểm làm việc:\n- Hà Nội\n- Hồ Chí Minh\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3085, 1395, 2, 'Database Developer', '• Tham gia phát triển các hệ thống web cho Ngân Hàng\n• Thực hiện các công việc được phân công:\n- Tham gia thiết kế/xây dựng các kho dữ liệu, mô hình dữ liệu (DataMart) và khai thác dữ liệu.\n- Phát triển các báo cáo quản trị\n• Tuân thủ các chính sách, quy trình, quy định, tiêu chuẩn về An toàn CNTT\n• Thực hiện các nhiệm vụ khác do Ban Lãnh đạo Khối CNTT giao\n• Nghiên cứu và cập nhật các kiến thức mới hỗ trợ cho công việc\n• Làm việc nhóm hoặc độc lập, giao tiếp với cấp trên và thành viên liên quan đến công việc.\n\nYêu cầu ứng viên:\n• Có tối thiểu 3 năm kinh nghiệm (đặc biệt trong các dự án ngân hàng)\n• Có kiến thức tốt về quản trị ứng dụng trên nhiều nền tảng công nghệ\n• Có kiến thức về cơ sở dữ liệu: Oracle, SQL\n• Thành thạo sử dụng các công cụ: Confluent, MinIO, Kafka, Iceberg, Dremio GoldenGate\n• Có kiến thức về PL/SQL, Oracle Function, Procedure, Package\n• Có kiến thức về Oracle BI, Oracle warehouse builder, SAP Business Object, Power BI, Tabular, Python, Kapka. Pentaho là lợi thế\n\nQuyền lợi:\n• Làm việc từ thứ 2 đến thứ 6\n• Offer: 23,000,000VNĐ - 30,000,000VNĐ Net/ tháng\n• Không cần thử việc, ký luôn hợp đồng chính thức và đóng bảo hiểm từ tháng đầu nhận việc\n• Cố định 13 tháng lương Net/ năm\n• Được tham gia vào các dự án lớn của Ngân hàng\n• Có lộ trình phát triển, thăng tiến rõ ràng đánh giá theo level nhân sự từ member => key member => Teamlead\n• Thưởng lễ tết; Quy đổi phép thành tiền/ cộng dồn phép\n• Có cơ hội tiếp cận và học hỏi công nghệ mới\n• Môi trường công bằng, đảm bảo mọi người đều có thể phát huy hết khả năng của mình\n• Được làm việc với những cá nhân xuất sắc, có nhiều kinh nghiệm.\n• Được hưởng Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo chế độ nhà nước ban hành.\n• Khám sức khỏe định kỳ 1 năm/1 lần\n• Chế độ du lịch hàng năm\n\nĐịa điểm làm việc:\n- Hà Nội: Dịch Vọng Hậu, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3086, 1377, 2, 'Lập Trình Viên Fresher (Tiếng Nhật)', 'Mô tả công việc:\n- Tham gia các dự án của công ty theo sự hướng dẫn của quản lý.\n- Phát triển phần mềm theo tài liệu được cung cấp.\n- Báo cáo tiến độ, chủ động đưa phương án xử lý khi gặp vấn đề & báo cáo với quản lý trực tiếp.\n- Tìm hiểu công nghệ mới để hỗ trợ dự án nếu cần.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học trong và ngoài nước chuyên ngành công nghệ thông tin hoặc các ngành liên quan.\n- Bắt buộc: trình độ tiếng Nhật N2 hoặc tương đương trở lên, có thể giao tiếp bằng tiếng Nhật.\n- Kinh nghiệm: không yêu cầu kinh nghiệm, chấp nhận các sinh viên mới hoặc chuẩn bị ra trường.\n- Nắm chắc kiến thức về lập trình một trong các ngôn ngữ thông dụng như .NET, JAVA, Python,...\n- Năng động, sáng tạo, có khả năng tự nghiên cứu. Có tinh thần trách nhiệm và khả năng làm việc độc lập & làm việc nhóm.\n\nQuyền lợi:\n- Thu nhập: Thỏa thuận theo năng lực, up to 15 triệu.\n- Xét tăng lương 1 lần/năm, mức thu nhập gia tăng theo năng suất và hiệu quả công việc, đóng góp thực tế vào dự án của công ty.\n- Thưởng cuối năm, thưởng sinh nhật và thưởng các ngày lễ khác.\n- Lộ trình thăng tiến rõ ràng và làm việc với các chuyên gia Nhật Bản (có cơ hội được làm việc onsite tại Nhật).\n- Được tham gia vào các buổi đào tạo, seminar hàng tháng để nâng cao kỹ năng công việc và cùng nhau chia sẻ: knowledge base, working experience, lessons learned, best practices...\n- Các chế độ theo quy định của pháp luật và phúc lợi đãi ngộ của công ty: BHXH, hiếu hỉ, ốm đau...\n- Chế độ lương làm thêm giờ (OT) theo đúng quy định của pháp luật.\n- Được tham gia vào các hoạt động teambuilding, du lịch thường niên, sinh nhật, .\n- Tham gia vào câu lạc bộ thể thao: cầu lông, bóng đá,...\n- Thời gian làm việc: từ thứ 2 đến thứ 6 (Nghỉ thứ 7, CN).\n- Môi trường làm việc trẻ và năng động, tôn trọng phát triển cá nhân, công bằng và luôn khuyến khích sáng tạo để phát huy tối đa năng lực.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3087, 1345, 2, 'Senior Android Kotlin (English)', 'REMOTE JOB- WFH\n\n- Work closely with Product Managers, technical stakeholders, to craft, design and propose mobile solutions, and agile delivery plans.\n- Lead and manage the mobile application team in delivering the product features according to plan, using agile delivery methodology.\n- Develop Android applications. Design, develop and optimize the performance of Mobile Apps products.\n- Participate in all stages of the software development process, including: requirements analysis, design, research new technologies...\n- Participate in contributing ideas with leaders and customers to improve products or work processes.\n- Solve issues, perform tasks according to plan, report work progress to the Line Manager Job.\n\nYêu cầu ứng viên\n\n- Have at least 5 years of experience in developing Android applications using Kotlin.\n- Have an understanding of the architecture of Android applications and use design patterns proficiently;\n- Have a solid knowledge of Kotlin Android.\n- Have strong knowledge on OOP (Object Oriented Programming) and SOLID principles.\n- Have knowledge in application architecture, data structure, clean code, design patterns, refactoring, code efficiency, memory, caching, multi-threading, test driven development and application profiling, jetpack component.\n- Have knowledge in coroutine and kotlin flow.\n- Have knowledge in source version control: SVN, Git.\n\nQuyền lợi\n\n- Salary up to 40 million.\n- Be able to work in a comfortable working environment.\n- The foreign working environment uses skills and English.\n- Being able to work in a youthful and dynamic environment, flexible time.\n- To participate in company activities.\n- Remote Job.\n\nĐịa điểm làm việc\n\n- Hà Nội\n- Hồ Chí Minh\n- Đà Nẵng\n- Bình Dương\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 3 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3088, 1390, 2, 'Java Developer', 'Mô tả công việc\n- Develop minor and simple components or modules of the products\n- Use common development tools such as compilers, debuggers, profiling tools and source control system as prescribed by the engineering standards.\n- Participate in the meetings, training programs.\n- Report to Leader and Line Manager.\n\nYêu cầu ứng viên\n- Graduated from College or University majoring in Information Technology, Computer Science, Computer Engineering or any other IT-related fields\n- 5+ years experience as Java EE Developer (HTML/JavaScript/CSS, Spring Framework/Spring Boot, JPA or Hibernate, ANSI SQL or PostgreSQL) or equivalent backend tech stack\n- Good design documentation is required.\n- Strong problem-solving skill, with a logical, analytical and approach to work.\n\nQuyền lợi\n- Hybrid working mode\n- Salary will be based on agreement, with full salary during probation.\n- Social insurance based on full salary.\n- Once-yearly bonuses and annual salary review.\n- Premium health care insurance coverage for staff and family.\n- Regular health check-ups.\n- 36+ days of paid leave per year.\n\nĐịa điểm làm việc\n- Hà Nội: HITC Building - 239 Xuân Thủy, Dịch Vọng Hậu, Cầu Giấy\n- Hồ Chí Minh: 8th floor, Saigon Trade Center, 37 Ton Duc Thang Street, Ben Nghe Ward, Quận 1\n- Đà Nẵng: 11th Floor - Vietinbank Building, 36 Tran Quoc Toan Street, Hai Chau Ward, Hải Châu.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Cầu Giấy, Hồ Chí Minh, Quận 1, Đà Nẵng, Hải Châu', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3089, 1218, 2, 'Frontend Developer (ReactJs)', 'Mô tả công việc\n- Use best practices and technologies to develop large SPAs for various users and platforms\n- Ensure high-quality, performant, and reusable code.\n- Perform benchmarking, performance, and security analysis.\n- Work closely with the backend teams and product design team to iterate quickly on new features and experiments.\n- Lead and manage a team of 2 - 4 engineers.\n\nYêu cầu ứng viên\n- 3+ years of experience programming with JavaScript, ReactJS, HTML, and CSS.\n- Previous product company experience.\n- Be able to write clean, performance-centric, reusable, and understandable code with unit tests.\n- Experience in responsive web and mobile-first applications.\n- Experience in CSS frameworks and tools (like SASS, LESS, and Bootstrap).\n- Understanding REST APIs, and client-server communication.\n- Good command of English.\n\nQuyền lợi\n- Hybrid working model: Enjoy 2 work-from-home days per week while fostering a collaborative environment to achieve outstanding results together.\n- 21++ paid leave days per year: Besides national holidays, annual sick leaves, and paid leaves, we have a paid leave called Got It Day for every month that doesn’t have any national holiday.\n- Amazing team: Work with the smartest and most hard-working people you’ve ever met. Our team is from Google, Meta, Apple, Amazon, and other best companies in Vietnam.\n- Competitive compensation package: Attractive salary and optional stock options. There is no upper limit on how much you can earn. It’s all based on your performance and contributions.\n- Best working environment: Coffee shop-like open office space, kitchen full of snacks and drinks, West Lake view bar, PlayStation, pool table, etc.\n- Gadgets for work: MacBook, external displays. Everything you need for your job is fully provided.\n- Training and personal development: Tuition and textbook reimbursement for approved work-related courses; free video training programs from Udacity, Udemy, and The Great Courses Plus; company library with the newest technology and business books.\n- Flexible working hours: Enjoy flexibility without strict timekeeping; our core working hours are from 10 AM to 5:30 PM (Monday to Friday).\n- Free daily lunches and dinners: Enjoy fresh meals of your choice delivered straight to the office.\n- Others: Office happy hours, team outings, participating in self-organized clubs like sports, games, algorithms, piano, etc.\n\nĐịa điểm làm việc\n- Hà Nội: HCMCC Building, số 249A Thuỵ Khuê, Tây Hồ, Tây Hồ\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 10:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3090, 1259, 2, 'Front-End Developer', 'Mô tả công việc\\n- Phát triển giao diện website/app bằng HTML, CSS, JavaScript và các framework như ReactJS, VueJS,...\\n- Tối ưu hóa giao diện cho các thiết bị khác nhau và hiệu suất tải trang.\\n- Kết nối API từ back-end để hiển thị dữ liệu trên giao diện người dùng.\\n- Tham gia đóng góp ý tưởng, cải tiến sản phẩm và trải nghiệm người dùng.\\n- Sửa lỗi và bảo trì giao diện theo yêu cầu.\\n\\nYêu cầu ứng viên\\n- Hiểu biết về HTML5, CSS3, Responsive Web Design, và các công cụ build front-end (Webpack, Vite, Babel,...).\\n- Biết sử dụng Git để quản lý source code.\\n- Có tư duy logic tốt, khả năng làm việc nhóm và chủ động trong công việc.\\n- Ưu tiên ứng viên từng làm việc với RESTful API, Axios, Tailwind CSS hoặc Ant Design.\\n- Ham học hỏi, sẵn sàng tiếp nhận công nghệ mới.\\n\\nQuyền lợi\\n- Môi trường sáng tạo, năng động, đề cao cá tính và ý tưởng thiết kế.\\n- Được hỗ trợ công cụ làm việc máy tính, tai nghe,...\\n- Được đánh giá và xét tăng lương định kỳ.\\n- Đầy đủ chế độ BHXH, nghỉ lễ/tết theo quy định.\\n\\nĐịa điểm làm việc\\n- Thái Nguyên: Tổ 1, phường Phố Cò, thành phố Sông Công, TP Sông Công\\n\\nThời gian làm việc\\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\\n\\nCách thức ứng tuyển\\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên, TP Sông Công', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3091, 1117, 2, 'Backend Intern (NestJS / FastAPI)', 'Mô tả công việc:\n- Tham gia vào dự án thật dưới sự hướng dẫn của mentor\n- Học và thực hành phát triển API sử dụng NestJS và FastAPI\n- Viết tài liệu kỹ thuật, unit test cho các module được giao.\n- Hỗ trợ fix bug, nâng cấp tính năng backend.\n- Học cách làm việc nhóm.\n\nYêu cầu ứng viên:\n- Sinh viên năm 3 trở lên ngành CNTT hoặc liên quan\n- Đã từng làm project thực hành hoặc đồ án sử dụng Node.js hoặc Python\n- Biết sử dụng Git, REST API, database cơ bản (PostgreSQL/MongoDB).\n- Tư duy logic tốt, ham học hỏi, cầu tiến.\n\nƯu tiên:\n- Từng thử qua NestJS, FastAPI là lợi thế lớn\n- Có tinh thần tự học và khả năng đọc hiểu tài liệu tiếng Anh\n\nQuyền lợi:\n- Hưởng mức hỗ trợ xứng đáng theo năng lực;\n- Được đào tạo bài bản, đầy đủ trước khi bắt đầu và trong suốt quá trình làm việc;\n- Được xem xét trở thành nhân viên chính thức sau quá trình học việc, thực tập tại công ty;\n- Có cơ hội làm việc trong môi trường chuyên nghiệp, trẻ trung và năng động.\n\nĐịa điểm làm việc:\n- Thừa Thiên Huế: Tầng 6, số 2 Lê Quý Đôn, Tòa nhà Vietinbank, Phú Hội, Huế., TP Huế\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thừa Thiên Huế', 'Internship', '2025-10-07 20:59:18.149534'),
	(3092, 1242, 2, 'Software Engineer - Kỹ Sư Cầu Nối Tiếng Hàn', 'Mô tả công việc\n- Bridge in communication with Korean clients on all project-related matters.\n- Analyze, clarify, and transfer client’s requests and requirements to project team members.\n- Control all project’s materials.\n- Manage or work closely with Delivery team/ sales team to monitor and control project.\n- Perform testing if needed.\n\nYêu cầu ứng viên\n[Required]\n- Bachelor\'s Degree.\n- From 1 year of experience translating/interpreting in the IT field.\n- Strong written and verbal communication skills in Korean.\n- TOPIK 5 or higher.\n- Strong written and reading in English (TOEIC 650).\n- Self-motivated and eager to learn (in business domain, software engineering, language).\n- High responsibility and teamwork spirit.\n\n[Nice to have]\n- Project management/BA/Tester experience.\n\nQuyền lợi\n- Attractive salary and bonus will be discussed after going through CV & Interview.\n- Review capacity annually and adjust salary increases according to work performance.\n- Health care: Premium health insurance, Annual health check-up.\n- Young working environment.\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.).\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8:00 - 12:00 - 13:00 - 17:00).\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 15, Keangnam Landmark 72, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3093, 1367, 2, 'Backend Developer (.Net/NodeJS)', '• Phát triển và tối ưu hóa hệ thống backend cho các ứng dụng web, mobile;\n• Xây dựng APl, đảm bảo hiệu suất và bảo mật;\n• Làm việc với cơ sở dữ liệu SQL/ NoSQL, tối ưu truy vấn;\n• Hỗ trợ triển khai và vận hành hệ thống;\n• Phối hợp với team Frontend, QA, BA để đảm bảo yêu cầu và chất lượng sản phẩm;\n• Nghiên cứu, áp dụng công nghệ mới vào dự án.\n\n• Kinh nghiệm: Tối thiểu 1 năm lĩnh vực lập trình;\n• Trình độ tiếng Anh: Toeic > 600;\n• Kỹ năng: Thành thạo NET hoặc Node.js, có tinh thần chủ động, trách nhiệm cao;\n• Kinh nghiệm dự án: Ưu tiên ứng viên đã tham gia các dự án từ 5 thành viên trở lên;\n• Kiến thức bổ trợ: Ưu tiên hiểu biết về Cloud, Security, Network (thông qua dự án thực tế hoặc chứng chỉ), sử dụng Al tools trong công việc.\n\n• Mức lương: 10-18M;\n• Thưởng hiệu quả công việc;\n• Các chế độ ngày phép, BHXH, BHYT, BHTN… theo quy định của pháp luật lao động hiện hành;\n• Cơ hội được học hỏi, làm việc với công nghệ mới;\n• Hỗ trợ tham gia các khóa đào tạo nâng cao kiến thức và kỹ năng;\n• Môi trường làm việc năng động, nhiều thử thách và cơ hội thăng tiến;\n• Tham gia các hoạt động teambuilding.\n\nĐịa điểm làm việc: Hà Nội\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3094, 1198, 2, 'Mobile Developer Intern (IOS/Android/Flutter)', 'Mô tả công việc:\n- Assist in coding basic features of the stock trading application under the guidance of senior developers.\n- Integrate APIs from the backend to display stock data (e.g., stock prices, charts).\n- Perform testing of the application on iOS/Android devices to identify UI or functional issues.\n- Assist in fixing minor bugs as assigned.\n- Update the application’s UI based on designs from the UX/UI team.\n- Prepare simple technical documentation (e.g., API descriptions, setup guides).\n- Explore new technologies related to mobile development (Flutter, NFC, app security) and suggest improvements.\n- Attend team meetings to contribute ideas and learn from team members.\nYêu cầu ứng viên:\n- Bachelor’s degree (or final-year student) in Information Technology or a related field.\n- Familiarity with mobile programming languages such as Swift (iOS), Kotlin/Java (Android), or Flutter/Dart (cross-platform).\n- Basic understanding of Object-Oriented Programming (OOP) and data structures.\n- Basic knowledge of RESTful APIs and how to integrate them with applications.\n- Experience using Git for source code management (GitHub, GitLab).\n- Familiarity with UI design tools such as Figma or Adobe XD.\n- Intermediate English language skills (written and verbal).\nQuyền lợi:\n- Full-time internship allowance: 2.000000 VND/month and parking fee support: 400.000 VND/month.\n- Participate in company training programs (professional skills, communication skills).\n- Support for internship certification stamping (if required).\n- Opportunity to join team-building activities, internal events, and other company recreational activities.\n- Dynamic and professional working environment, with opportunities to work and learn about investment knowledge directly from industry experts in the securities sector.\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tầng 21, Phú Mỹ Hưng Tower, 08 Hoàng Văn Thái, Phường Tân Phú, Quận 7\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3095, 1173, 2, 'Kỹ Sư Phần Mềm (Mạnh NodeJs, Làm Được Cả ReactJs)', 'Mô tả công việc:\n- Tham gia vào các dự án phát triển phần mềm cho khách hàng Nhật Bản, sử dụng công nghệ JavaScript như VueJS, ReactJS, Angular và NodeJS.\n- Đề xuất các giải pháp kỹ thuật và xu hướng công nghệ mới nhằm nâng cao chất lượng sản phẩm.\n- Phối hợp chặt chẽ với nhóm thiết kế và lập trình để xây dựng sản phẩm tối ưu.\n- Thực hiện các nhiệm vụ khác theo sự phân công của cấp trên.\n\nYêu cầu ứng viên:\n- Có ít nhất 01 năm kinh nghiệm lập trình JavaScript cho cả FE và BE.\n- Thành thạo HTML, CSS và sử dụng thành thạo các framework/library phổ biến như ReactJS, VueJS (FE) và NodeJS (BE).\n- Nắm vững kiến thức nền tảng về lập trình, lập trình hướng đối tượng (OOP) và hệ quản trị cơ sở dữ liệu (DBMS).\n- Tư duy hệ thống và logic tốt, khả năng học hỏi nhanh, chủ động đề xuất giải pháp và xử lý vấn đề hiệu quả.\n\nQuyền lợi:\n- Mức lương: Upto 24M, có thể thỏa thuận theo năng lực của ứng viên.\n- Nói KHÔNG với chậm lương, nợ lương.\n- Review lương 02 lần/năm.\n- Lương tháng 13, tháng lương 14 và các khoản bonus.\n- Thưởng các ngày lễ: 30/4, 2/9, Tết Dương Lịch. Quà sinh nhật công ty, quà sinh nhật cá nhân,…\n- Hưởng 15 ngày phép/năm.\n- Tham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động Việt Nam.\n- Khám sức khỏe định kỳ tại các bệnh viện uy tín (Hồng Ngọc, Thu Cúc, …).\n- Du lịch hè 1-2 lần/năm, trợ cấp team-building cá nhân định kỳ hàng quý.\n- Đọc sách miễn phí tại thư viện sách của Công ty.\n- Hưởng mọi quyền lợi hỗ trợ các chứng chỉ ngoại ngữ và chứng chỉ nghiệp vụ chuyên ngành như:\n- Chứng chỉ tiếng Nhật, chứng chỉ AWS, ISTQB…\n- Tham gia các khóa học thay đổi mindset từ Học viện Agile miễn phí.\n- Thời gian làm việc: Từ 8h00 đến 17h00, nghỉ Thứ Bảy và Chủ Nhật.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 22, tháp B, tòa nhà Sông Đà (HH4), Đường Phạm Hùng, Phường Mỹ Đình 1, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3096, 1130, 2, 'Thực Tập Sinh IT', 'Chương trình được thiết kế với định hướng giúp thực tập sinh phát triển toàn diện về kỹ năng, tư duy và kinh nghiệm thực tế trong lĩnh vực lập trình. Thông qua môi trường học tập chuyên nghiệp, sự dẫn dắt từ các mentor giàu kinh nghiệm và cơ hội tham gia các dự án thực tế, eUp Group mong muốn:\n- Mang lại trải nghiệm học tập và làm việc thực tế, giúp sinh viên tự tin hơn khi bước vào thị trường lao động\n- Khơi dậy và khai thác tối đa sự sáng tạo, chủ động của các bạn trẻ ngay từ những bước đầu sự nghiệp\n- Cung cấp nền tảng kỹ thuật vững chắc để tham gia phát triển các sản phẩm công nghệ có giá trị\n- Đồng hành cùng những thực tập sinh xuất sắc nhất và mở ra cơ hội trở thành nhân sự chính thức tại eUp Group và trực tiếp được phát triển sản phẩm mới có giá trị.\n- Thời gian: Tháng 6/2025\n- Thời lượng: 2 buổi/tuần (có mặt tại văn phòng)\n- Lộ trình chi tiết theo mô hình bootcamp kéo dài 3-4 tháng\n- Tài liệu về coding best practices cho các ngôn ngữ lập trình liên quan\n- Hình thức: fulltime hoặc part-time\n\nYêu cầu ứng viên\n- Sinh viên năm 3,4 của các trường: Đại học Bách Khoa Hà Nội, Đại học Công nghệ, Đại học Bưu chính viễn thông,...\n- Theo học chuyên ngành Công nghệ thông tin (GPA: từ 3.2 trở lên)\n- Có mong muốn trau dồi kiến thức vững chắc về lập trình (Fullstack) và tìm kiếm cơ hội phát triển sự nghiệp theo hướng IT\n- Có kiến thức về thuật toán và có khả năng giải thuật tốt\n- Có thể đăng ký tham gia fulltime/parttime, thời gian linh hoạt.\n\nQuyền lợi\n- Có hỗ trợ dấu thực tập và có hỗ trợ tài chính cho thực tập sinh tham gia vào dự án thực tế tại eUp\n- Cơ hội tham gia vào các dự án thực tế: eUp sẽ thiết kế các dự án thực tế có giá trị cho đội ngũ thực tập sinh tham gia để phát triển kỹ năng và đánh giá năng lực\n- Được đào tạo bởi chuyên gia đầu ngành Công nghệ thông tin\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Làm việc tại trường product đi sâu chuyên môn về mobile app, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác marketing, sales, chăm sóc khách hàng và khách hàng\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng\n\nĐịa điểm làm việc\n- Hà Nội: 315 Trường Chinh, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3097, 1346, 2, 'Embedded Software/Android Driver Developer', 'We are looking for a skilled and proactive Embedded Software Engineer or Android Driver Developer to join our team. The ideal candidate will have hands-on experience in embedded systems or Android driver development, with solid knowledge of Linux systems and scripting. You will work closely with R&D teams to support product testing, debugging, and production processes.\n- Working Location: Thai Nguyen factory\n- Qty: 5 (including one Team Lead)\n\n- Develop and maintain embedded software or Android device drivers.\n- Analyze and debug system issues using various Android and Linux logs (e.g., logcat, kernel logs, UART).\n- Write and execute automation scripts using Shell, Python, or batch scripting.\n- Support production line testing and initial fault analysis.\n- Collaborate with R&D teams to assist in debugging, stress testing, and performance verification.\n- Contribute to continuous improvements in development and testing workflows.\n\n- Experience in embedded software development or Android driver development.\n- Familiarity with Linux systems and common Linux commands.\n- Experience with automation scripting using Shell, Python, or Batch scripts.\n- Proficiency in capturing and analyzing Android system logs (logcat, kernel logs, UART, etc.).\n- Understanding of production line testing processes and ability to perform basic issue analysis.\n- Ability to communicate in either Mandarin Chinese or English for daily work.\n\n- Thái Nguyên: KCN Yên Bình, phường Hồng Tiến, TP. Phổ Yên, TP Thái Nguyên\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3098, 770, 2, 'Java Developer (Middle)', 'Mô tả công việc:\n- Tham gia phát triển các dự án Hệ sinh thái Tài chính số (Viettel Money, Mobile Money, ví cá nhân, ví doanh nghiệp, ...). Cung cấp sản phẩm ứng dụng thanh toán và chuyển tiền với số lượng giao dịch rất lớn, đòi hỏi hiệu năng xử lý cao.\n- Xây dựng các hệ thống Tài chính điện tử cho các thị trường nước ngoài mà Viettel đầu tư.\n- Tham gia làm rõ nghiệp vụ, thiết kế giải pháp, phát triển nâng cấp hệ thống theo yêu cầu.\n- Tham gia review thiết kế, review code, tối ưu hệ thống đáp ứng lưu lượng truy cập cao.\n- Nghiên cứu áp dụng công nghệ mới nâng cao chất lượng, tối ưu nguồn lực phát triển.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học loại Khá trở lên, chuyên ngành Công nghệ thông tin, Kỹ sư phần mềm. Đặc biệt ưu tiên các trường Học viện Công nghệ Bưu chính Viễn thông, Đại học Bách khoa Hà Nội, …\n- Tiếng Anh tương đương 550+ TOEIC.\n- Ưu tiên ứng viên có từ 02 năm kinh nghiệm Java trở lên.\n- Thành thạo Java Core, các framework Java như EE, Spring, Struts, Hibernate ... và một số design pattern thông dụng.\n- Tư duy về thiết kế hướng đối tượng và nắm vững kiến thức về cấu trúc dữ liệu và giải thuật, lập trình hướng đối tượng ...\n- Thành thạo SQL, PLSQL, có kiến thức về các hệ quản trị cơ sở dữ liệu Oracle/MySQL, noSQL, có khả năng tối ưu CSDL.\n- Ưu tiên có hiểu biết về nghiệp vụ tài chính, có kinh nghiệm về microservices, ham học hỏi tìm tòi sáng tạo cái mới.\n- Ưu tiên ứng viên có khả năng ứng dụng công cụ AI để hỗ trợ phân tích, lập trình, viết tài liệu hoặc tối ưu quy trình làm việc.\n- Có kinh nghiệm hoặc có nghiên cứu đến việc tích hợp AI vào sản phẩm, dịch vụ là một lợi thế.\n\nQuyền lợi:\n- Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn.\n- Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel.\n- Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm.\n- Cơ hội tiếp xúc với các dự án lớn, mới mẻ & tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam.\n- Cơ hội thăng tiến rõ ràng với nhiều cấp bậc.\n- Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn.\n- Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời.\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người.\n- Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,…\n- Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày.\n- Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Keangnam, Phạm Hùng, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3099, 1146, 2, 'Thực Tập Sinh Back-End / Intern Back-End (.NET)', 'Mô tả công việc:\n- Lập trình các chức năng được giao theo tài liệu giải pháp chi tiết.\n- Tham gia phát triển các dự án về web, xây dựng các chức năng frontend của website, web application.\n- Thực hiện thiết kế, coding, testing các module.\n- Tùy chỉnh và nâng cấp hệ thống đáp ứng yêu cầu của khách hàng.\n- Tham gia phát triển các module backend của ứng dụng.\n- Nghiên cứu, tìm hiểu các công nghệ mới để áp dụng cải thiện sản phẩm.\n\nYêu cầu ứng viên:\n- Đang là sinh viên năm cuối hoặc đã tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán tin... hoặc chuyên ngành khác có liên quan.\n- Kiến thức tốt về HTML, CSS, JavaScript là một lợi thế.\n- Kiến thức tốt về HTML/CSS, AJAX và các thư viện / framework liên quan.\n- Có kinh nghiệm làm việc với RESTful API.\n- Có tư duy logic - thuật toán tốt, yêu thích công việc lập trình.\n- Có thái độ cầu tiến, khả năng học hỏi, chủ động, trách nhiệm trong công việc.\n- Tinh thần làm việc theo đội nhóm tốt.\n- Có máy tính cá nhân.\n\nQuyền lợi:\n- Cơ hội nhận mức hỗ trợ thực tập 3.000.000 VND/tháng từ tháng thứ 2.\n- Được đào tạo phát triển bản thân, nâng cao các kỹ năng và chuyên môn nghề nghiệp.\n- Làm việc tại môi trường chuyên nghiệp, năng động, trẻ trung và trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc.\n- Được tham gia các lớp đào tạo, khóa học về chuyên môn, kỹ năng.\n- Cơ hội tiếp cận với những doanh nghiệp, dự án lớn, những xu hướng công nghệ/nền tảng mới nhất, thỏa sức sáng tạo phát triển bản thân.\n- Sau 1-2 tháng thực tập sẽ có đánh giá kết quả của Leader và được xem xét nâng lên thử việc và ký hợp đồng lao động.\n- Tham gia các chuyến du lịch, teambuilding.\n\nĐịa điểm làm việc:\n- Hà Nội: 35 Lạc Trung, Hai Bà Trưng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3100, 237, 2, 'Lập Trình Viên NodeJS - Từ 2 Năm Kinh Nghiệm', 'Mô tả công việc\n - Tham gia lập trình, vận hành, tối ưu các sản phẩm của công ty.\n - Thiết kế và triển khai các ứng dụng Web động bằng các ngôn ngữ lập trình như Java, Javascript...\n - Tối ưu hóa hiệu suất và bảo mật của các ứng dụng Web.\n - Xác định và giải quyết các vấn đề liên quan đến ứng dụng Web.\n - Tham gia vào các quá trình kiểm soát chất lượng cho sản phẩm.\n - Các công việc khác theo sự phân công của Quản lý trực tiếp.\n - Chi tiết trao đổi qua cuộc phỏng vấn.\n\nYêu cầu ứng viên\n - Tốt nghiệp Đại học chuyên ngành CNTT\n - Kinh nghiệm tối thiểu 02 năm ở vị trí tương đương.\n - Thành thạo quy trình phát triển phần mềm, từ tiếp nhận yêu cầu, lựa chọn công cụ, ngôn ngữ, thiết kế CSDL, xây dựng frontend, backend, triển khai lên hệ thống server thật.\n - Thành thạo ngôn ngữ lập trình Javascript, CSS, HTML và một framework xây dựng frontend như ReactJS hoặc Angular, biết cách xây dựng website responsive chạy trên mobile.\n - Thành thạo một framework xây dựng backend như NodeJS Express, ngôn ngữ SQL, biết cách sử dụng ORM và vận hành hệ quản trị CSDL như MySQL hoặc Postgres.\n - Biết sử dụng các API và thiết kế API để tương tác với các dịch vụ của khách hàng.\n - Biết đọc tài liệu bằng tiếng anh.\n - Biết phát triển ứng dụng mobile (ReactNative) là một lợi thế.\n\nQuyền lợi\n - Thu nhập: thỏa thuận.\n - Thời gian làm việc: Nghỉ chiều thứ Bảy và các ngày Chủ nhật trong tuần\n + Sáng: từ 8h30 – 12h00.\n + Chiều: từ 13h30 – 18h00.\n - Nghỉ phép năm, chế độ BHXH, BHYT, BHTN theo quy định của nhà nước.\n - Thưởng Lễ, Tết, du lịch hàng năm.\n - Môi trường làm việc trẻ và năng động, tôn trọng phát triển cá nhân, công bằng và luôn khuyến khích sáng tạo để phát huy tối đa năng lực.\n\nĐịa điểm làm việc\n - Hà Nội: Tầng 5, tòa nhà SanNam, 78 Duy Tân, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n - Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n - Thứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển\n - Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3101, 1131, 2, 'Nhân Viên Triển Khai Phần Mềm ERP', 'Mô tả công việc\n- Triển khai kho dữ liệu tích hợp với nguồn ERP cho khách hàng/doanh nghiệp nội bộ: phân tích nghiệp vụ, cấu hình hệ thống, hỗ trợ đào tạo và vận hành.\n- Trích xuất và xử lý dữ liệu từ hệ thống ERP để phục vụ mục đích báo cáo, phân tích, hoặc chuyển đổi hệ thống.\n- Phối hợp với team Data để chuẩn hóa dữ liệu, đồng bộ về hệ thống lưu trữ tập trung (Data Warehouse).\n- Tham gia vào các dự án dữ liệu cho khách hàng:\n  - Làm việc với dữ liệu tài chính, bán hàng, vận hành,... từ các hệ thống ERP\n  - Viết truy vấn SQL, làm sạch dữ liệu, xử lý ETL\n  - Học và áp dụng các công cụ như Airflow, dbt, BigQuery, v.v.\n  - Học và thực hành các kỹ thuật data engineering thông qua mentor nội bộ và dự án thực tế.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Hệ thống thông tin, CNTT, Kinh tế, hoặc tương đương.\n- Có kiến thức cơ bản về quy trình nghiệp vụ doanh nghiệp (kế toán, mua bán, tồn kho…)\n- Đã từng làm việc với hệ thống ERP, phần mềm kế toán, hoặc có kinh nghiệm xử lý dữ liệu là lợi thế.\n- Biết SQL cơ bản, có tư duy logic, phân tích dữ liệu tốt.\n- Chủ động học hỏi, có định hướng rõ ràng trở thành Data Engineer trong thời gian ngắn.\n\nQuyền lợi\n- Mức lương cạnh tranh,\n- Lương tháng 13\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop….\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Khám sức khỏe định kỳ 1 lần/năm\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm\n- Làm việc với tác đối tác lớn\n- Review tăng lương định kỳ hàng năm\n\nĐịa điểm làm việc\n- Hà Nội: 19-21 Vũ Trọng Phụng, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 00:00 đến 00:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3102, 397, 2, 'Senior Software Engineer', 'MỤC TIÊU CÔNG VIỆC: Thiết kế và phát triển các ứng dụng Java hiệu suất cao cho hệ thống LOS/CRM, đóng góp vào toàn bộ vòng đời phát triển phần mềm và cung cấp các giải pháp phần mềm có thể mở rộng và chất lượng cao.\n\nNHIỆM VỤ, TRÁCH NHIỆM CHÍNH:\n- Cộng tác với các đơn vị nghiệp vụ, bao gồm kiến trúc sư phần mềm, quản lý sản phẩm, các đơn vị kinh doanh, thiết kế để phát triển các ứng dụng Java.\n- Thiết kế và triển khai ứng dụng bằng ngôn ngữ Java hiệu quả và đáng tin cậy, đảm bảo hiệu suất và bảo mật.\n- Thực hiện đánh giá mã nguồn để duy trì chất lượng và tuân theo các tiêu chuẩn mã hóa.\n- Gỡ lỗi, khắc phục sự cố và giải quyết các nhược điểm và sự cố phần mềm, đảm bảo độ tin cậy của ứng dụng.\n- Tham gia phân tích yêu cầu và thảo luận thiết kế phần mềm để đề xuất các giải pháp sáng tạo.\n- Phát triển và duy trì tài liệu kỹ thuật để tham khảo và báo cáo.\n- Cập nhật thông tin về xu hướng công nghệ liên quan đến Java, các cách thực hành tốt nhất và tiêu chuẩn ngành.\n- Xác định tầm nhìn kỹ thuật cho việc phát triển phần mềm, phù hợp với mục tiêu kinh doanh và thực tiễn tốt nhất của ngành.\n- Cộng tác với các nhà phát triển khác để xây dựng các giải pháp phần mềm có thể mở rộng và hiệu quả.\n- Góp phần vào toàn bộ vòng đời phát triển phần mềm, từ khái niệm và thiết kế đến thử nghiệm, triển khai và hỗ trợ.\n\nYÊU CẦU ỨNG VIÊN:\n- Bằng cử nhân về Khoa học máy tính, Kỹ thuật phần mềm hoặc lĩnh vực liên quan trở lên.\n- Đã có kinh nghiệm tương đương trong vai trò kỹ sư cao cấp phát triển phần mềm với ngôn ngữ Java, ưu tiên nếu có thêm kinh nghiệm phát triển phần mềm với ngôn ngữ PHP.\n- Ưu tiên am hiểu lĩnh vực tài chính ngân hàng, hệ thống LOS.\n- Thông thạo các nguyên tắc phát triển phần mềm, lập trình hướng đối tượng và các cách thực hành tốt nhất của Java.\n- Kỹ năng thiết kế cơ sở dữ liệu và SQL (ví dụ: MySQL, PostgreSQL, Oracle).\n- Kỹ năng phát triển ứng dụng web (HTML, CSS, JavaScript).\n- Thành thạo quy trình kiểm thử, gỡ lỗi và khắc phục sự cố phần mềm.\n- Kỹ năng về các công nghệ container hóa và điều phối quy trình (ví dụ: Docker, Kubernetes).\n- Thành thạo hệ thống kiểm soát phiên bản (ví dụ: Git).\n- Thành thạo về BPMN, DMN, lược đồ cơ sở dữ liệu, giao thức truyền thông hệ thống như HTTP, Restful API, Dịch vụ web.\n- Có kinh nghiệm với các nền tảng và dịch vụ đám mây (ví dụ: AWS, Azure) là một lợi thế.\n- Khả năng làm việc theo nhóm / tổ chức.\n- Khả năng làm việc hiệu quả trong sự thay đổi.\n- Khả năng lập kế hoạch và tổ chức.\n- Kỹ năng giải quyết vấn đề.\n\nQUYỀN LỢI:\nLÝ DO ĐỒNG HÀNH CÙNG SHBFINANCE:\n- Môi trường làm việc chuyên nghiệp, cởi mở.\n- Thời gian làm việc từ thứ 2 – thứ 6, nghỉ trưa 1h30’ (40h/tuần).\n- Chế độ làm việc Hybrid working từ 1 -  2 ngày làm việc từ xa/ tuần.\n- Đồng nghiệp thân thiện, cởi mở với tư duy đề cao sự phát triển của mỗi cá nhân.\n- Văn phòng làm việc với không gian mở, rộng rãi, được cung cấp đầy đủ các trang thiết bị để phục vụ cho công việc.\n\nQuan tâm đặc biệt đến nhân viên:\n- Gói đãi ngộ cạnh tranh cùng chính sách nâng lương theo định kỳ. Tổng thu nhập TB 14 tháng lương/năm.\n- Hỗ trợ ăn trưa lên tới 1.200.000 VND/tháng; Hỗ trợ gửi xe 200.000 VND/ tháng.\n- Nghỉ hưởng lương ngày sinh nhật + quà sinh nhật.\n- Quyền lợi chăm sóc sức khỏe đặc quyền bảo hiểm sức khỏe toàn diện SHBFC Care.\n- Khám sức khỏe thường niên tại bệnh viện hàng đầu Việt Nam.\n- Du lịch thường niên, hoạt động team building năm.\n- Tập trung hỗ trợ sự phát triển cá nhân.\n- Được tư vấn, đồng hành và hỗ trợ phát triển sự nghiệp cùng các cấp quản lý tài năng, giàu kinh nghiệm.\n- Cơ hội tham gia các dự án lớn, đối tác quốc tế, đi đầu trong lĩnh vực tài chính tiêu dùng.\n- Chính sách hỗ trợ các hoạt động học tập, nâng cao trình độ ngoại ngữ, trao đổi, chia sẻ kiến thức, giao lưu văn hoá (Training, Seminar...).\n\nĐỊA ĐIỂM LÀM VIỆC:\n- Hà Nội: 52 Lê Đại Hành, Hai Bà Trưng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3103, 1374, 2, 'Kỹ Sư Lập Trình Nhúng Linux, Android', '- Phát triển các thiết bị đầu terminal thông minh (Smart phone, Tablet), thiết bị IoT, thiết bị xử lý trí tuệ nhân tạo tại biên dựa trên các nền tảng của Qualcomm, NXP…;\n• Porting hệ điều hành Android, Linux, RTOS cho các nền tảng phần cứng của Qualcomm, NXP;\n• Phối hợp với bộ phận phần cứng để debug, bring up thiết bị;\n• Tham gia vào tất cả các giai đoạn phát triển phần mềm từ phân tích yêu cầu, thiết kế, triển khai, kiểm tra hệ thống;\n• Thực hiện các công việc được quản lý phân công;\n\n• Tốt nghiệp Đại học loại Khá trở lên các chuyên ngành Cơ điện tử, Điện tử - Viễn thông, Điện - tự động hóa, CNTT, Kỹ thuật máy tính;\n• Tiếng Anh: TOEIC từ 550 trở lên hoặc tương đương;\n• Kiến thức nền tảng\n- Hệ điều hành Linux:\n + Hiểu biết về cấu trúc và hoạt động của Linux;\n + Quản lý hệ thống, cấu hình, và sử dụng các công cụ dòng lệnh.\n- Hệ điều hành Android:\n + Kiến thức về hệ điều hành Android, từ phiên bản cơ bản đến các phiên bản mới nhất;\n + Hiểu biết về Android SDK và NDK.\n- Kỹ năng lập trình: Thành thạo C/C++; có kiến thức về các ngôn ngữ Java/Kotlin/Python là một lợi thế;\n- Kỹ năng phát triển phần mềm\n + Quản lý mã nguồn: Sử dụng Git để quản lý và phối hợp công việc.\n + Phát triển phần mềm nhúng: Hiểu biết về các giao thức truyền thông (I2C, SPI, UART); Kinh nghiệm làm việc với các vi điều khiển và vi xử lý.\n + Hiểu biết về kiến trúc ARM, x86, SoC, ...\n + Debugging: Sử dụng các công cụ như GDB, các công cụ phân tích bộ nhớ khác.\n• Kỹ năng mềm:\n• Kỹ năng làm việc nhóm và giao tiếp hiệu quả\n\n+ Thu nhập hấp dẫn, xứng đáng với năng lực, thưởng theo hiệu quả công việc.\n+ Được làm việc trong Công ty sản xuất hàng đầu Việt nam với quy mô lớn (1.000 người); có bề dày lịch sử và văn hóa truyền thống với 2 lần được Đảng + Nhà nước phong tặng “Anh hùng lực lượng vũ trang nhân dân”.\n+ Có cơ hội được đào tạo nâng cao nghiệp vụ thường xuyên. Được cung cấp các trang thiết bị hiện đại cần thiết để nâng cao hiệu quả làm việc.\n+ Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.\n+ Được làm việc trong môi trường năng động, hiệu quả, nhiều hoạt động văn hóa sôi nổi quan tâm đến đời sống tinh thần của nhân viên và nhiều cơ hội để phát triển nghề nghiệp cho bản thân.\n\n- Hà Nội: An Khánh, Hoài Đức\n- Hà Nội: Khu CNC Hòa Lạc, Thạch Thất\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 đầu tiên của tháng\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hoài Đức, Thạch Thất', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3104, 1374, 2, 'Kỹ Sư Lập Trình Nhúng Vi Điều Khiển', 'Mô tả công việc\n• Phát triển phần mềm nhúng sử dụng các nền tảng vi xử lý của Microchip, ST, NXP …\n• Tham gia vào tất cả các giai đoạn phát triển phần mềm từ phân tích yêu cầu, thiết kế, triển khai, kiểm tra hệ thống;\n• Thực hiện các công việc được quản lý phân công.\n\nYêu cầu ứng viên\n• Tốt nghiệp Đại học loại Khá trở lên các chuyên ngành Cơ điện tử, Điện tử - Viễn thông, Điện - tự động hóa, CNTT, Kỹ thuật máy tính;\n• Tốt nghiệp Đại học loại Khá trở lên các chuyên ngành Cơ điện tử, Điện tử - Viễn thông, Điện - tự động hóa, CNTT, Kỹ thuật máy tính;\n• Tiếng Anh: TOEIC từ 550 trở lên hoặc tương đương;\n• Kỹ năng:\n- Thành thạo C/C++; có kiến thức về các ngôn ngữ C#/Python là một lợi thế;\n- Hiểu biết về các giao thức truyền thông (I2C, SPI, UART);\n- Kinh nghiệm làm việc với các vi điều khiển và vi xử lý;\n- Hiểu biết về kiến trúc ARM, SoC, ...\n- Quản lý mã nguồn: Sử dụng Git để quản lý và phối hợp công việc;\n- Debugging: Sử dụng các công cụ như GDB, các công cụ phân tích bộ nhớ;\n- Kỹ năng làm việc nhóm và giao tiếp hiệu quả;\n\nQuyền lợi\n+ Thu nhập hấp dẫn, xứng đáng với năng lực, thưởng theo hiệu quả công việc.\n+ Được làm việc trong Công ty sản xuất hàng đầu Việt nam với quy mô lớn (1.000 người); có bề dày lịch sử và văn hóa truyền thống với 2 lần được Đảng + Nhà nước phong tặng “Anh hùng lực lượng vũ trang nhân dân”.\n+ Có cơ hội được đào tạo nâng cao nghiệp vụ thường xuyên. Được cung cấp các trang thiết bị hiện đại cần thiết để nâng cao hiệu quả làm việc.\n+ Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.\n+ Được làm việc trong môi trường năng động, hiệu quả, nhiều hoạt động văn hóa sôi nổi quan tâm đến đời sống tinh thần của nhân viên và nhiều cơ hội để phát triển nghề nghiệp cho bản thân.\n\nĐịa điểm làm việc\n- Hà Nội: An Khánh, Hoài Đức\n- Hà Nội: Khu CNC Hòa Lạc, Thạch Thất\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\nThứ 7 đầu tiên của tháng\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hoài Đức, Thạch Thất', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3105, 1240, 2, 'Nhân Viên IT (Thiết Kế Và Hoàn Thiện Store Shopify) - Thu Nhập 20 Triệu +++', 'Mô tả công việc\n- Thiết kế và hoàn thiện store Shopify bao gồm: \n  - Trang chủ, trang sản phẩm, trang bộ sưu tập, trang add to cart, tối ưu hóa trang checkout, \n  - Cài đặt và sử dụng các app trên shopify như bootsale, upsale, klaviyo, \n  - Tối ưu hóa tốc độ load trang, khả năng chuyển đổi ... \n  - Am hiểu sử dụng các công cụ xây dựng website, cũng như cài đặt và cấu hình các ứng dụng cơ bản trên Shopify.\n\nYêu cầu ứng viên\n- Frontend, backend thành thạo.\n- Thành thạo JavaScript/TypeScript\n- Hiểu biết sâu sắc về RESTful API và dịch vụ web\n- Có kỹ năng thiết kế wireframe, layout website .\n- Ưu tiên các ứng viên chưa lập gia đình để đảm bảo sự tập trung cao và khả năng phát triển không gián đoạn.\n- Có khả năng sử dụng tiếng Anh tốt, đặc biệt trong đọc hiểu tài liệu.\n- Làm việc chăm chỉ và chủ động.\n\nQuyền lợi\n- Thời gian làm việc: 8h - 17h30 từ Thứ Hai đến Sáng Thứ Bảy, nghỉ trưa từ 12h - 14h\n- Mức lương : 9.000.000 - 20.000.000/tháng \n- Thưởng tháng lương thứ 13\n- Thưởng vào các dịp Lễ_ tết,…\n- Nhân sự làm việc chính thức có 12 ngày nghỉ phép/ năm\n- Chế độ bảo hiểm theo Luật lao động quy định.\n- Teambuilding, nghỉ mát , du lịch hàng năm\n- Chế độ sinh nhật , hiếu hỉ, thai sản vv... theo quy định pháp luật và hỗ trợ thêm từ Công ty', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3106, 1154, 2, 'Back-End Developer', 'Phát triển và duy trì hệ thống back-end cho các trang web và ứng dụng web, đảm bảo khả năng mở rộng, bảo mật, và hiệu suất cao. Viết mã nguồn (coding) theo chuẩn kỹ thuật, đảm bảo mã dễ đọc, dễ bảo trì và tối ưu hóa. Sử dụng các framework và ngôn ngữ lập trình back-end như: + Node.js với Express.js hoặc NestJS + Java với Spring Boot + Python với Django hoặc Flask + PHP với Laravel hoặc Symfony + Ruby on Rails Tích hợp hệ thống API: Thiết kế, phát triển và duy trì các API (RESTful, GraphQL) để kết nối các dịch vụ front-end và back-end, cũng như tích hợp với các hệ thống bên ngoài (thanh toán, dịch vụ giao hàng, các bên thứ ba khác). Thiết kế và quản lý cơ sở dữ liệu: Xây dựng và tối ưu hóa cơ sở dữ liệu (SQL và NoSQL) cho các trang web lớn, đảm bảo khả năng mở rộng, tốc độ truy vấn và tính toàn vẹn của dữ liệu. + SQL: MySQL, PostgreSQL + NoSQL: MongoDB, Redis Xây dựng hệ thống xử lý và quản lý phiên truy cập người dùng: Xây dựng các cơ chế xác thực, phân quyền (OAuth2, JWT), bảo mật thông tin người dùng, xử lý phiên đăng nhập và tối ưu hóa trải nghiệm người dùng. Xử lý hiệu suất hệ thống: Tối ưu hóa hiệu suất tải trang, thời gian phản hồi máy chủ, quản lý bộ nhớ cache (Redis, Memcached) và sử dụng các công cụ phân tích hiệu suất để phát hiện và giải quyết các vấn đề về hiệu suất. Đảm bảo bảo mật cho website: Áp dụng các kỹ thuật bảo mật như mã hóa dữ liệu, bảo vệ chống lại các cuộc tấn công phổ biến (SQL Injection, XSS, CSRF), và xử lý các vấn đề liên quan đến bảo mật web. Thực hiện các báo cáo được giao. Thực hiện những nhiệm vụ khác được giao bởi cấp Quản lý trực tiếp và Ban Giám đốc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3107, 1454, 2, 'Lập Trình Viên NodeJS', 'Mô tả công việc:\n- Phát triển sản phẩm về lĩnh vực giáo dục của công ty\n- Xây dựng tính năng mới và tối ưu hiệu suất, bảo mật của Fronted\n- Làm việc cùng các thành viên khác để xây dựng và phát triển sản phẩm\n\nYêu cầu ứng viên:\n- Có kiến thức nền tảng về Javascript\n- Có kinh nghiệm làm việc với NodeJS và ExpressJS\n- Có kiến thức về Cơ Sở Dữ liệu MongoDB hoặc MySQL\n- Có kiến thức về Git\n- Có kỹ năng năng làm việc độc lập và làm việc nhóm\n- Sẵn sàng học hỏi và làm việc với công nghệ mới\n- Có kỹ năng về Tiếng Anh là một lợi thế\n\nQuyền lợi:\n- Mức lương khởi điểm: 7.000.000 VNĐ - 11.000.000 VNĐ/ tháng\n- Hỗ trợ máy tính làm việc\n- Xét tăng lương hàng năm, thưởng (các dịp lễ Tết, ...) phụ cấp theo quy chế công ty\n- Hưởng các quyền lợi theo quy định của Nhà nước (đóng BHYT, BHXH)\n- Được hưởng các chế độ phúc lợi theo quy định công ty: sinh nhật, ốm đau, hiếu hỉ\n- Nghỉ phép 12 ngày/ năm, lễ, Tết theo quy định Nhà nước\n- Tham gia các hoạt động Company Trip mỗi năm\n- Tham gia các hoạt động - sự kiện của công ty\n- Tự do trong trang phục, không bắt buộc mặc phong cách công sở\n- Môi trường trẻ trung, văn hóa cởi mở, thoải mái, chuyên nghiệp trong công việc\n- Được đào tạo và tạo điều kiện bồi dưỡng nâng cao chuyên môn\n\nĐịa điểm làm việc:\n- Hà Tĩnh: Tầng 5, Toà nhà số 15 Trần phú đường Trần Phú, Phường Trần Phú, TP Hà Tĩnh\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 07:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Tĩnh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3108, 1251, 2, 'Trưởng Nhóm Kinh Doanh & Phát Triển Phần Mềm', 'Mô tả công việc\n- Xây dựng và triển khai chiến lược, mô hình kinh doanh cho từng sản phẩm Số của Công ty\n- Phân tích thị trường và nhu cầu khách hàng và để kịp thời đề xuất các cơ hội hợp tác.\n- Quản lý vòng đời sản phẩm: từ ý tưởng, xây dựng, thử nghiệm, ra mắt và cải tiến.\n- Làm việc với team sản phẩm để đề xuất, định hướng phát triển hoặc cải tiến các sản phẩm của Cty trên cơ sở hiểu biết insight khách hàng và thị trường.\n- Phối hợp với team marketing/ dự án để lên ý tưởng và thực thi các chương trình nhằm thu hút khách hàng.\n- Xây dựng mối quan hệ với đối tác, khách hàng chiến lược. Là cầu nối giữa khách hàng và team nội bộ sao cho thông tin được thông suốt.\n- Cùng với team Dự án, nghiên cứu hiệu quả của sản phẩm/dịch vụ để kịp thời điều chỉnh, cải tiến cho phù hợp.\n- Quản lý, đào tạo và phát triển đội ngũ kinh doanh, đảm bảo đạt KPI và mục tiêu đã đề ra.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành Kinh doanh, Quản trị, Công nghệ thông tin hoặc các ngành liên quan.\n- Tối thiểu 3 năm kinh nghiệm ở vị trí quản lý kinh doanh hoặc phát triển sản phẩm, ưu tiên trong lĩnh vực công nghệ.\n- Hiểu biết sâu về mô hình kinh doanh SaaS, sản phẩm số, nhà mạng hoặc phần mềm là một lợi thế.\n- Kỹ năng phân tích thị trường, xây dựng chiến lược và quản lý dự án tốt.\n- Có khả năng làm việc đa nhiệm và phối hợp liên phòng ban hiệu quả.\n- Kỹ năng lãnh đạo, giao tiếp và đàm phán tốt.\n- Tư duy sáng tạo, nhạy bén với xu hướng công nghệ và hành vi người dùng.\n\nThu nhập\n- Thu nhập khi đạt 100% KPI: 21 - 23 triệu VND\n- Thu nhập tính theo tỷ lệ đạt KPI\n- Lương cứng phụ thuộc vào doanh số\n\nQuyền lợi\n- Được tiếp cận với các công nghệ tiên phong trong lĩnh vực CNTT. Được tiếp làm việc với nhiều đối tác lớn trong nước và quốc tế.\n- Thu nhập: Lương từ 21.000.000 - 23.000.000 VND/tháng + KPI\n- Thưởng tối thiểu tháng lương thứ 13\n- BHXH, BHYT, BHTN theo pháp luật hiện hành\n- Môi trường làm việc trẻ trung, năng động, phát huy khả năng sáng tạo và lợi thế của bản thân.\n- Đội ngũ nhân viên trẻ, năng động, đầy nhiệt huyết, sẵn sàng hỗ trợ nhau trong công việc.\n- Làm việc từ 8:30 đến 17:30, từ thứ 2 – thứ 6.\n\nĐịa điểm làm việc\n- Hà Nội: 96 Hoàng Ngân, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3109, 1335, 2, '.NET Developer Thu Nhập Hấp Dẫn', 'Mô tả công việc:\n- Phát triển và bảo trì các ứng dụng Web sử dụng C# và ASP.NET MVC.\n- Tham gia vào quá trình thiết kế, xây dựng và tối ưu hóa hệ thống Web App.\n- Làm việc với cơ sở dữ liệu SQL Server\n- Phối hợp với các thành viên trong nhóm để đảm bảo tiến độ và chất lượng dự án.\n- Xử lý lỗi, tối ưu hiệu suất và cải thiện trải nghiệm người dùng.\n\nYêu cầu ứng viên:\n- Tối thiểu 3 năm kinh nghiệm, trong đó có 1 năm phát triển Web App bằng C#.\n- Thành thạo ASP.NET MVC, ưu tiên ứng viên chuyên về phát triển Web.\n- Có kinh nghiệm làm việc với SQL Server, Entity Framework.\n- Biết sử dụng HTML, CSS, JavaScript, jQuery là lợi thế.\n- Có tư duy logic, kỹ năng giải quyết vấn đề tốt.\n- Chủ động, có trách nhiệm với công việc.\n\nQuyền lợi:\n- Chế độ thưởng theo quý, năm; tiền quà các ngày Lễ, Tết, ngày thành lập Tập đoàn; hỗ trợ chi phí nghỉ dưỡng hằng năm...\n- Hưởng Bảo hiểm Xã hội, Bảo hiểm Y tế theo quy định của Luật Lao động và công ty\n- Làm việc trong môi trường chuyên nghiệp, sáng tạo, cạnh tranh, phát triển, năng động có nhiều cơ hội thăng tiến.\n- Cơ hội học tập, nghiên cứu, làm việc trong nước và các nước trên thế giới.\n- Cơ hội tiếp cận với nhiều công nghệ mới.\n- Cơ hội thăng tiến, phát triển bản thân.\n\nĐịa điểm làm việc:\n- Hà Nội: Số 112, Đường Chùa võ, Khu đô thị Dương Nội, Hà Đông\n- Hà Nội: Hoàng Cầu, Đống Đa\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3110, 1358, 2, 'Middle Frontend Developer', 'Chúng tôi đang tìm kiếm một Middle Frontend Developer có định hướng phát triển thành Fullstack Developer, để đồng hành trong hành trình xây dựng các sản phẩm thương mại điện tử quy mô lớn, chịu tải cao, tập trung vào hành trình trải nghiệm khách hàng và khai thác AI để nâng cao hiệu quả phát triển.\n\nBạn sẽ làm việc trong một môi trường đề cao đổi mới sáng tạo, tinh thần tự học và ứng dụng công nghệ mới nhằm tạo ra các giải pháp thông minh, tối ưu cho người dùng và doanh nghiệp.\n\nTrách nhiệm chính\n• Phát triển và tối ưu hóa giao diện người dùng (SPA/PWA) trên nền tảng thương mại điện tử hiệu suất cao.\n• Kết hợp cùng backend team để thiết kế và xây dựng API hiệu quả, bảo mật.\n• Áp dụng các công nghệ AI (như ChatGPT, AI assistant, code suggestion tools) vào quy trình phát triển sản phẩm và tự động hóa.\n• Tham gia cải tiến hiệu suất, SEO, trải nghiệm người dùng dựa trên Customer Journey thực tế.\n• Tích hợp và vận hành các dịch vụ AWS: S3, CloudFront, Cognito, Lambda, v.v.\n• Viết mã chất lượng cao, dễ đọc, dễ bảo trì.\n• Đề xuất các cải tiến kỹ thuật mới, thử nghiệm các giải pháp sáng tạo để nâng cao hiệu quả sản phẩm và quy trình.\n\nYêu cầu ứng viên\n• 2–4 năm kinh nghiệm với React.js, Next.js, hoặc Vue.js.\n• Có định hướng hoặc kinh nghiệm với backend như Node.js, NestJS, hoặc RESTful APIs.\n• Thành thạo HTML5, CSS3, JavaScript (ES6+), TypeScript.\n• Kinh nghiệm thực tế với AWS: S3, Lambda, CloudFront, Cognito, RDS/DynamoDB.\n• Đã từng tham gia phát triển hệ thống eCommerce quy mô lớn (100.000+ người dùng).\n• Am hiểu UX/UI, hành trình khách hàng, tracking (GA4, Mixpanel…).\n• Có kinh nghiệm sử dụng các công cụ AI hỗ trợ lập trình (ChatGPT, GitHub Copilot, v.v.).\n• Tư duy sản phẩm và tinh thần cầu tiến, không ngừng học hỏi cái mới.\n• Sử dụng tốt Git và có kinh nghiệm làm việc theo mô hình Agile/Scrum.\n\nQuyền lợi\nAttractive salary, commensurate with capacity.\n13th month salary bonus, achievement bonus: 14-15 months, monthly/quarterly/yearly business bonus, Tet holiday bonus.\nRice allowance and other allowances (according to the nature of the job)\nAnnual health check-ups\nSocial insurance; 24/24 accident insurance\nLeave regime for employees from 12-14 days/year\nTraining and career development programs.\nProfessional working environment.\nCollective activities: Team Building, Family Festival, Arts, Sports Club, Vacation...\nCommunity activities: Gifts on the occasion of 8/3, 20/10, International Children\'s Day 1/6, Mid-Autumn Festival.....\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 170E Phan Đăng Lưu, Phú Nhuận\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3111, 1460, 2, 'Junior Frontend Developer', 'Mô tả công việc\n- Tham gia phát triển nền tảng quản trị giáo dục: Xây dựng và nâng cấp các ứng dụng web, di động (iOS, Android) và/hoặc desktop (Windows, macOS) nhằm cải thiện trải nghiệm học tập và tối ưu hóa quy trình vận hành.\n- Thiết kế và xây dựng giao diện người dùng (UI): Phát triển các tính năng giao diện thân thiện, tuân thủ tiêu chuẩn thiết kế, đảm bảo khả năng bảo trì, mở rộng và tương thích đa nền tảng.\n- Bảo trì và tối ưu hóa hệ thống: Xử lý các lỗi kỹ thuật, cải thiện hiệu suất và đề xuất các giải pháp nâng cao chất lượng sản phẩm.\n- Thu thập và phân tích phản hồi: Làm việc với người dùng và khách hàng để thu thập ý kiến, từ đó đề xuất và triển khai các giải pháp cải tiến nhằm nâng cao trải nghiệm người dùng.\nYêu cầu ứng viên\n- Kỹ thuật:\n+ React/React Native: Thành thạo các khái niệm cốt lõi của React (component, state, props, hooks) và/hoặc React Native để phát triển giao diện web hoặc di động.\n+ HTML, CSS, JavaScript/TypeScript: Nắm vững các công nghệ frontend cơ bản, có khả năng xây dựng giao diện responsive và tối ưu trải nghiệm người dùng.\n+ Flutter/Dart: Có kinh nghiệm phát triển ứng dụng di động hoặc desktop với Flutter, bao gồm xây dựng giao diện (Widgets) và quản lý trạng thái (Provider, Riverpod, hoặc Bloc), là một lợi thế lớn.\n+ Git: Thành thạo sử dụng Git (GitHub, GitLab, Bitbucket) để quản lý mã nguồn và làm việc nhóm.\n+ Kiến thức nền tảng: Hiểu rõ các khái niệm cốt lõi về phát triển web (DOM, event handling) và ứng dụng di động/desktop (vòng đời ứng dụng, quản lý tài nguyên).\n+ Phân tích và xử lý lỗi: Có khả năng phân tích, phát hiện và đề xuất giải pháp cho các vấn đề kỹ thuật từ cơ bản đến phức tạp trong các module phần mềm.\n- Kinh nghiệm:\n+ Tối thiểu 1 năm kinh nghiệm ở vị trí Frontend Engineer hoặc tương đương, đã tham gia phát triển ứng dụng thực tế sử dụng React/React Native.\n+ Có kinh nghiệm với Flutter (đặc biệt là ứng dụng desktop) là một lợi thế, nhưng không bắt buộc.\n+ Có ít nhất 1-2 dự án thực tế (cá nhân, thực tập, hoặc đồ án) thể hiện kỹ năng phát triển frontend, ưu tiên nếu đã publish hoặc có mã nguồn trên GitHub.\n- Ưu tiên:\n+ Có kinh nghiệm tích hợp API (REST, GraphQL).\n+ Hiểu biết về UI/UX và sử dụng công cụ thiết kế như Figma để phối hợp với đội ngũ thiết kế.\n+ Có kinh nghiệm viết unit test hoặc integration test để đảm bảo chất lượng mã nguồn.\n+ Có kinh nghiệm với cơ sở dữ liệu (SQL Server, hoặc NoSQL) là một lợi thế.\nQuyền lợi\n- Lương từ 20 – 50 triệu/tháng tùy kinh nghiệm và năng lực.\n- Nâng cao kỹ năng chuyên sâu về React/React Native và cơ hội học hỏi Flutter để phát triển ứng dụng đa nền tảng.\n- Phát triển lên các vị trí như Middle/Senior Frontend Developer hoặc chuyển hướng sang vai trò Full-stack Developer.\n- Tham gia các dự án đa dạng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3112, 1298, 2, 'Senior Java', 'Mô tả công việc:\n- Phát triển ứng dụng website sử dụng Java Spring Boot để quản trị dữ liệu, quản lý kết nối, tích hợp và phát triển API phục vụ hệ thống.\n- Đảm bảo hiệu suất, chất lượng và khả năng đáp ứng tốt nhất có thể của các ứng dụng ở phía Back-end.\n- Có kinh nghiệm làm việc với bảng biểu, dữ liệu từ SuperSet, Data Engineer và Data Analyst làm một lợi thế.\n\nYêu cầu ứng viên:\n- Trên 5 năm kinh nghiệm phát triển ứng dụng với Java, Spring Boot, Spring Boot RESTful Services, Spring Security, Spring Data JPA.\n- Database: Kỹ năng làm việc với các cơ sở dữ liệu quan hệ như SQL Server, PostgreSQL, MySQL, hoặc Oracle.\n- Kinh nghiệm với các công cụ ORM (Object Relational Mapping) như Hibernate để quản lý và truy xuất dữ liệu trong ứng dụng.\n- Front-end Skills: Kỹ năng cơ bản với các công nghệ front-end như HTML, CSS, JavaScript (React hoặc Vue).\n- Hiểu và áp dụng CI/CD.\n\nYêu cầu các kỹ năng khác:\n- DevOps và CI/CD.\n- Docker, Kubernetes hoặc Jenkins.\n- OAuth và Bảo mật ứng dụng: Kiến thức về OAuth 2.0, JWT, và các tiêu chuẩn bảo mật ứng dụng web khác để đảm bảo bảo mật cho ứng dụng.\n- Có kinh nghiệm làm việc với bảng biểu, dữ liệu từ SuperSet, Data Engineer và Data Analyst làm một lợi thế.\n\nQuyền lợi:\n- Lương: 30.000.000 - 40000.000.\n- Thưởng dự án/thưởng kinh doanh: từ 1 – 5 tháng lương.\n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30.\n- Nghỉ phép: 12 ngày/năm.\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN, Bảo hiểm Bảo Việt cho 100% cán bộ sau thời gian thử việc.\n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n- Các hoạt động giao lưu bóng đá, golf, văn nghệ...\n- Đào tạo chuyên sâu theo yêu cầu công việc.\n- Được tham gia các dự án lớn triển khai toàn quốc.\n- Được tiếp cận các kỹ thuật, công nghệ hiện đại.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3113, 1472, 2, 'Marketing Leader', 'National Housing Organization (N.H.O JSC.) was founded in 2012 with a clear goal: to develop and construct homes in Vietnam to support the increasing demands for home ownership. We create optimal and sustainable solutions for housing and aim to be a leader in quality projects in Vietnam. The combination of local and international experience and expertise enables us to build homes that compliment Vietnamese family culture, while providing higher living standards. Currently, we are looking for a Marketing Leader to join our team.\nResponsibilities:\n• Market & project monitoring\n- Market research to understand the market, competitors, customer journey & behavior.\n- Work closely with brokers, sales men & sales agents to update the market trend, market information.\n- Analysis the sales result, customer profile to evaluate and suggest the new direction for next marketing campaign.\n- Making monitoring report, evaluation report after each campaign and update the plan to ensure the quality of campaigns.\n• Marketing plan\n- Coordinate with the Sales Department to create an overall marketing plan.\n• Campaign deployment and management\n- Develop and manage campaigns including events, social media, communication follow the master plan.\n- Work closely with clients’ internal communication team.\n- Work closely with clients’ executive teams, preparing speaking points and creating formal documents outlining speaking engagements.\n• Sales and marketing materials production\n- Working with vendor/agencies to order & manage marketing materials: Sales kit, CGIs, Rendering video, miniature, Video clips, mock-up units...\n• Budget plan and management\n- Develop marketing budget for the Project, control and evaluate the implementation of the approved budget.\n• Carry out assigned tasks with limited supervision, including coordinating, and implementing projects.\n• Other tasks assigned by line manager.\n\nRequirements:\n• Bachelor or Master Degree in Marketing, Business Management or relevant major.\n• Fluent in English.\n• Have 4-5 years of experience in Marketing field.\n• Experience in the Real Estate industry or Communication agency is preferable.\n• Good knowledge, and experience in the real estate market, market analysis, and creative marketing.\n• Have a deep and broad knowledge of Marketing and Marketing tools, Communication skills, partnerships, project management, and strategic thinking.\n• Good at Microsoft Office.\n• Confident, smart, fast – learner, strong analytical skill.\n• Detailed oriented and outgoing characteristics.\n\nBenefits:\n• International working environment.\n• Social insurance registered on gross salary.\n• Challenges and promising experience as the company is growing and expanding.\n• 13th month salary, annual salary review, bonus on public holidays (New Year, Liberation & Labor Day, National Day, etc.).\n• Monthly birthday party, quarterly department meal, annual Health check-up, etc.\n• Friendly, supportive and open-minded colleagues and environment.\n• Other competitive benefits.\n\nWorking location:\n- Hồ Chí Minh: 44B Nguyen Van Troi, ward 15, Phu Nhuan district, Phú Nhuận.\n\nWorking time:\nFrom Monday to Friday (from 08:00 to 17:00).\n\nHow to apply:\nCandidates can apply online by clicking the "Apply Now" button below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3114, 1221, 2, 'Golang Developer', 'Mô tả công việc:\n- Tham gia phát triển hệ thống backend sử dụng Golang cho các dự án IT phần mềm;\n- Tham gia các công đoạn phát triển phần mềm: tìm hiểu yêu cầu, phân tích, thiết kế...;\n- Phối hợp làm việc cùng đội ngũ có chuyên môn cao;\n- Cùng bộ phận tham gia nghiên cứu & phát triển các sản phẩm Web sử dụng ngôn ngữ/công nghệ khác như PHP(Basic / Laravel / CodeIgniter / Yii2), JavaScript/Vuejs (NuxtJS) / ReactJS (NextJS), NodeJS(NestJS), Python (Flask), PosgreSQL, MongoDB, Redis, Docker, Serverless, Kubernetes, AWS (ECS / EKS), Kafka, Elasticsearch...;\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của team leader;\n- Làm việc, phối hợp công việc theo nhóm dưới sự phân công công việc của quản lý trực tiếp.\n\nYêu cầu ứng viên:\n- Có ít nhất 3 năm kinh nghiệm phát triển dự án với Golang;\n- Nắm vững kiến thức về phát triển Back-end;\n- Tư duy logic tốt về cấu trúc dữ liệu và giải thuật và thuật toán;\n- Có kinh nghiệm làm việc với Docker;\n- Có kinh nghiệm với MySQL hoặc PostgreSQL, thiết kế cơ sở dữ liệu, tối ưu hóa câu truy vấn;\n- Có kinh nghiệm làm việc chuyên sâu với git, git flow và github flow;\n- Có kinh nghiệm về UnitTest;\n- Có kinh nghiệm deploy dự án lên môi trường test, staging hoặc production cho khách hàng.\n\nƯu tiên ứng viên (không bắt buộc):\n- Có kinh nghiệm làm việc với cloud: AWS là 1 lợi thế;\n- Có kinh nghiệm với các framework Frontend, như VueJS, ReactJS, Angular… là một lợi thế;\n- Có kiến thức và tư duy tốt, sáng tạo và đam mê công nghệ, kiên trì và khả năng tự học tốt;\n- Có khả năng làm việc teamwork tốt cũng như làm việc độc lập, có kinh nghiệm làm việc trong các dự án theo mô hình Agile/Scrum là lợi thế.\n\nQuyền lợi:\n- Mức lương up to 30,000,000 VND/tháng (chưa bao gồm thưởng dự án, thưởng lễ tết, và các khoản thưởng khác...);\n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Nghỉ thứ 7, Chủ nhật + Nghỉ phép theo Quy định của Pháp luật hiện hành;\n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty;\n- Khám sức khỏe định kỳ 1 năm/1 lần;\n- Bảo hiểm chăm sóc sức khỏe 24/24 ( PVI Care);\n- Tham gia các Câu lạc bộ văn hóa, thể thao trong công ty: CLB Bóng đá, CLB Game…\n- Tham gia các hoạt động tập thể sôi động theo tháng/quý/năm: Nghỉ mát hàng năm, Teambuilding, Gala cuối năm…\n\nĐặc biệt:\n- Được hỗ trợ 100% chi phí tham gia các khóa học kỹ năng mềm, các khóa đào tạo chuyên môn, luyện thi các chứng chỉ uy tín trong và ngoài nước và khen thưởng khi đạt chứng chỉ chuyên môn;\n- Học tập không giới hạn qua tài khoản học trực tuyến Udemy;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật;\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3115, 1219, 2, 'Thực Tập Sinh', 'Mô tả công việc\n- Phân tích yêu cầu và thiết kế hệ thống phần mềm.\n- Phát triển và bảo trì các ứng dụng web và mobile.\n- Viết code sạch, hiệu quả và dễ bảo trì.\n- Thực hiện các bài test đơn vị và tích hợp.\n- Cộng tác với các thành viên khác trong nhóm để hoàn thành dự án.\n- Tham gia vào các cuộc họp và thảo luận về kỹ thuật.\n- Học hỏi và cập nhật kiến thức công nghệ mới.\n- Có khả năng làm việc độc lập và làm việc nhóm.\n- Có khả năng giải quyết vấn đề và đưa ra các giải pháp hiệu quả.\n- Có tinh thần trách nhiệm cao và cam kết với công việc.\n\nYêu cầu ứng viên\n- Có kiến thức cơ bản về các ngôn ngữ lập trình như Java, Python, PHP, Ruby on Rails, Node.js, React, Angular, Vue.js, ... (ít nhất 1 ngôn ngữ backend và 1 ngôn ngữ frontend). Và các cơ sở dữ liệu như MySQL, PostgreSQL, MongoDB, ...\n- Có kiến thức về các framework và thư viện phổ biến, kiến trúc phần mềm, thiết kế mô hình dữ liệu.\n- Có khả năng làm việc độc lập và làm việc nhóm.\n- Có khả năng giải quyết vấn đề và đưa ra các giải pháp hiệu quả.\n- Có tinh thần trách nhiệm cao và cam kết với công việc.\n- Có khả năng giao tiếp tốt và làm việc hiệu quả trong môi trường năng động.\n- Có khả năng đọc hiểu tài liệu tiếng Anh (hoặc tiếng Nhật thì càng tốt)\n\nQuyền lợi\n- Được làm việc trong môi trường năng động và chuyên nghiệp.\n- Được đào tạo và phát triển kỹ năng chuyên môn.\n- Được hưởng các chế độ phúc lợi tốt theo quy định của pháp luật.\n- Có cơ hội thăng tiến và phát triển nghề nghiệp.\n- Được tham gia các hoạt động team building và các hoạt động ngoại khác.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 25/1 Cửu Long Phường 2, Tân Bình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3116, 72, 2, 'Android Developer Leader', 'Mô tả công việc\n✓ Phát triển, duy trì và cải tiến mã nguồn Kotlin dùng chung cho cả nền tảng Android và IOS, đảm bảo tích hợp mượt và hiệu quả trên cả hai hệ sinh thái. Thực hiện đánh giá kỹ lưỡng mã nguồn để đảm bảo chất lượng và triển khai hiệu quả với Kotlin Multiplatform, tuân thủ các phương pháp tốt nhất về tính duy trì và khả năng mở rộng.\n✓ Tối ưu hóa mã Kotlin dùng chung, tận dụng thế mạnh riêng của từng nền tảng và duy trì mã nguồn thống nhất.\n✓ Tham gia phát triển dự án về Camera trên đa nền tảng Mobile.\n✓ Tích hợp các cổng thanh toán thông qua (SDK/API bên thứ 3).\n✓ Tích hợp DRM, Watermarking.\n✓ Kiến trúc, review code, tối ưu để tăng trải nghiệm.\n✓ Phân tích, đánh giá, lập kế hoạch phát triển, trao đổi nhóm để đưa ra nhiệm vụ cần thực thi liên quan.\n✓ Cập nhật xu hướng phát triển công nghệ mới để áp dụng vào dự án.\n✓ Làm các dự án khác theo sự phân công của quản lý đơn vị.\n\nYêu cầu ứng viên\n✓ Tốt nghiệp đại học chuyên ngành CNTT loại khá trở lên.\n✓ Tối thiểu 3 năm kinh nghiệm phát triển Android với Kotlin và có kinh nghiệm với Swift/Objective-C trong phát triển IOS là một lợi thế.\n✓ Thành thạo Jetpack Compose, Coroutines và Flow.\n✓ Kỹ năng làm việc nhóm và giải quyết vấn đề tốt.\n✓ Ưu tiên:\n✓ Biết Swift/Objective C hoặc từng làm việc với ứng dụng native iOS.\n✓ Có kinh nghiệm tích hợp Google Maps, Mapbox, multimedia (audio/video), hoặc WebRTC.\n✓ Kinh nghiệm kết nối và xử lý dữ liệu với các thiết bị IoT qua BLE hoặc WiFi.\n✓ Hiểu và áp dụng tốt Material Design, custom layout.\n✓ Từng tham gia dự án theo mô hình Agile/Scrum thực tế.\n✓ Kỹ năng mềm: lãnh đạo nhóm, giao tiếp, làm việc nhóm, giải quyết vấn đề.\n\nQuyền lợi\n✓ Gói thu nhập cạnh tranh.\n✓ Đầy đủ các chế độ theo luật lao động hiện hành.\n✓ Chính sách phúc lợi theo quy định của Công ty đa dạng: Chăm sóc sức khỏe định kì hàng năm; Gói bảo hiểm sức khỏe chuyên biệt (FPT Care – Khám chữa bệnh miễn phí tại tất cả các bệnh viện); Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân...\n✓ Môi trường làm việc thân thiện, cởi mở.\n✓ Cơ sở vật chất và công cụ làm việc hiện đại, tiện nghi.\n✓ Nhiều cơ hội phát triển và thăng tiến.\n✓ Văn hóa Doanh nghiệp đặc sắc, sinh động bậc nhất với nhiều các hoạt động hấp dẫn: tân binh, teambuilding, thi trạng, hội làng, hội diễn Sao Chổi, sinh nhật FPT, ngày 08/03, ngày 11/11...\n✓ Hưởng các gói ưu đãi cước khi sử dụng dịch vụ của FPT Telecom.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3117, 1344, 2, 'Mobile Developer (React Native)', 'Mô tả công việc\n- Thiết kế, phát triển và duy trì ứng dụng di động đa nền tảng (iOS & Android) bằng React Native (bao gồm tích hợp Native code nếu cần).\n- Phối hợp chặt chẽ với đội ngũ sản phẩm, thiết kế và backend để mang lại trải nghiệm mượt mà, thân thiện và bảo mật cho người dùng.\n- Tối ưu hiệu suất ứng dụng, giao diện người dùng (UI/UX) và đảm bảo tính ổn định khi xử lý dữ liệu chuyển động và hệ thống phần thưởng.\n- Viết mã sạch, có cấu trúc rõ ràng và dễ bảo trì; tham gia đánh giá mã (code review) cùng đội ngũ kỹ thuật.\n- Góp phần cải tiến liên tục sản phẩm dựa trên phản hồi từ người dùng và số liệu hành vi sử dụng.\n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm phát triển phần mềm, trong đó có kinh nghiệm vững với React Native.\n- Đã từng phát triển và đưa ứng dụng lên App Store và Google Play.\n- Hiểu rõ kiến trúc ứng dụng di động, quản lý trạng thái, tối ưu hiệu năng, và đảm bảo an toàn bảo mật dữ liệu người dùng.\n- Ưu tiên ứng viên có kinh nghiệm tích hợp thiết bị đo bước chân (Google Fit, Apple HealthKit) và/hoặc ứng dụng liên quan tới tiền mã hóa, phần thưởng token, hệ thống ví tiền số. Hoặc ưu tiên có kinh nghiệm tích hợp các eKYC, Cổng thanh toán, Social Login, Tracking, Analytics, Marketing Tool,…\n- Có tư duy sản phẩm tốt, chủ động đề xuất cải tiến và làm việc theo mô hình Agile/Scrum.\n\nQuyền lợi\n- Mức thu nhập 23-30 triệu gross, thỏa thuận khi phỏng vấn.\n- Cơ hội phát triển, khẳng định chính mình và thăng tiến cực lớn, trở thành nhà quản lý chỉ sau 2 - 3 năm.\n- Văn phòng đẹp nhất, sáng tạo và thân thiện với môi trường do chính những thế hệ trẻ của Apec kiến tạo nên.\n- Hoạt động nội bộ (du lịch, team building,...)\n- Thưởng lễ tết, thưởng quý, thưởng cuối năm, lương tháng thứ 13+++.\n\nCó cơ hội được tham gia một số dự án đã và đang phát triển của p.CNTT:\n- Hệ thống giao dịch thị trường chứng khoán trái phiếu, website bảng giá, Mobile App giao dịch cho nhà đầu tư.\n- Vận hành, phát triển các website công ty, các dự án.\n- Hệ thống ERP cho tập đoàn (Quản trị nhân sự, tuyển dụng, tính lương, giao việc, dự án).\n- Các ứng dụng quản trị, giao dịch khác trong tập đoàn: Bất động sản, nội thất, trái phiếu...\n- Đang phát triển hệ thống quản lý chuỗi khách sạn SmartHotel tích hợp eKYC, Payment, hệ thống quản lý kho phòng: Channel Manager, CRM, Loyalty, Booking.\n- Vận hành, phát triển hệ thống tài chính độc nhất tại Việt Nam và hệ thống giao dịch chứng khoán hiện đại bậc nhất Việt Nam.\n- Và nhiều dự án khác.\n\nĐịa điểm làm việc\n- Hà Nội: 117 Trần Duy Hưng, Trung Hòa, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:50).\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:20).\n- 2 ca làm việc được lựa chọn.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3118, 1176, 2, 'C Developer', 'Mô tả công việc\n• Tham gia phát triển phần mềm cho trạm phát sóng 4G, 5G.\n• Phân tích thiết kế và vẽ call flow cho các luồng tính năng được giao phát triển mới.\n• Tìm hiểu, nghiên cứu về mạng viễn thông 5G.\n• Viết các tài liệu phân tích yêu cầu, tài liệu thiết kế SDD.\n• Kiểm thử chất lượng, hiệu năng phần mềm theo yêu cầu.\n\nYêu cầu ứng viên\n• Tốt nghiệp hệ chính quy các Trường Đại học, chuyên ngành đào tạo: Công nghệ thông tin, Điện tử Viễn thông, Tự động hóa..\n• Có từ 1 năm kinh nghiệm vị trí tương đương.\n• Tư duy, kỹ năng lập trình tốt, nắm vững các kiến thức nền tảng về lập trình C.\n• Có kiến thức về các cấu trúc dữ liệu và giải thuật cơ bản.\n• Nắm vững kiến thức về hệ điều hành.\n• Chấp nhận ứng viên sắp hoặc mới tốt nghiệp với điều kiện bắt buộc: tốt nghiệp loại Khá trở lên (CPA > 3.0) các trường Đại học;\n• Ưu tiên các ứng viên có kiến thức cơ bản về mạng viễn thông 4G, 5G.\n• Ưu tiên các ứng viên có kinh nghiệm lập trình đa luồng, đa tiến trình, lập trình mạng ở tầng giao vận hoặc thấp hơn.\n• Ưu tiên các ứng viên có kinh nghiệm lập trình và debug trên hệ điều hành linux.\n\nQuyền lợi\n• Chế độ lương hấp dẫn 15 – 25M/tháng;\n• Xét lương hàng năm,  lương tháng 13, thưởng kinh doanh dựa trên kết quả công việc và hiệu quả hoạt động của công ty;\n• Bảo hiểm chăm sóc sức khỏe cao cấp, bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp;\n• Được khám sức khỏe định kỳ 1 lần/1 năm;\n• 01 giờ nghỉ phép có lương mỗi ngày cho phụ nữ có con dưới 12 tháng;\n• Môi trường làm việc hiện đại với những đồng nghiệp trẻ trung, năng động & thân thiện ;\n• Du lịch công ty hàng năm và tiệc cuối năm, team building hàng quý và ăn uống cùng nhau hàng tuần. Câu lạc bộ: chạy, bóng đá, game,...\n• Thời gian làm làm việc: 8h30 - 17h30 Thứ 2 - Thứ 6.\n\nĐịa điểm làm việc\n• Hà Nội: Tòa Detech, số 8 Tôn Thất Thuyết, Nam Từ Liêm.\n\nThời gian làm việc\n• Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển\n• Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3119, 1196, 2, 'Thực Tập Sinh IT, Lập Trình Frontend', 'Mô tả công việc\n- Phối hợp cùng các chuyên gia và giảng viên để chuyển đổi tài liệu học thuật thành bài giảng số, khóa học và các bài kiểm tra tương tác.\n- Sử dụng các công cụ do công ty cung cấp để xây dựng nội dung học tập tương tác, đa phương tiện (video, hình ảnh, âm thanh, game giáo dục) và ứng dụng trên nền tảng web, di động, thiết bị thông minh, bảng thông minh…\n- Sử dụng công cụ tương tác, kéo thả đối tượng để phát triển các game giáo dục, các mô phỏng, thí nghiệm cho các môn Toán, Lý, Hoá, Sinh, Địa, Sử, Ngoại Ngữ…\n- Làm việc và trao đổi cùng đội nhóm để tối ưu hóa hiệu năng và nâng cao trải nghiệm người dùng.\n- Thực hiện các công việc khác theo phân công của công ty.\n\nThực tập sinh sẽ được hướng dẫn và đào tạo bài bản theo một trong hai roadmap tùy chọn:\n- Content Creator: Chuyên xây dựng nội dung bài giảng số, không yêu cầu kỹ năng lập trình sâu.\n- Component Creator: Tham gia lập trình, phát triển ứng dụng và các nội dung tương tác phức tạp hơn (yêu cầu kiến thức và kỹ năng lập trình).\n\nYêu cầu ứng viên\n- Sinh viên năm 3, 4 đang trong thời gian thực tập hoặc đang chờ bằng; Sinh viên mới ra trường, sinh viên năm cuối Cao đẳng, Đại học chuyên ngành Công nghệ thông tin (phần mềm, thiết kế, lập trình)... hoặc các ngành có liên quan.\n- Có kiến thức cơ bản về lập trình, biết sử dụng một ngôn ngữ lập trình là một lợi thế\n- Có kiến thức nền tảng về khả năng lập trình OPP.\n- Có tư duy logic tốt\n- Đam mê học hỏi, chủ động trong công việc, có tinh thần làm việc nhóm tốt.\n\nQuyền lợi\n- Cơ hội học hỏi, phát triển kỹ năng, làm việc với đội ngũ chuyên gia và có thể được giữ lại làm nhân viên chính thức sau kỳ thực tập.\n- Hỗ trợ: 3 triệu/tháng (bao gồm ăn trưa)\n- Hỗ trợ dấu thực tập\n- Có khả năng lên chính thức sau 3 tháng thực tập\n- Nhân viên chính thức được review lương 2 lần/năm + các chế độ phúc lợi hấp dẫn\n- Được tham gia phát triển Product phục vụ số lượng hàng triệu user\n- Được ứng dụng các công nghệ mới nhất và là xu hướng hiện tại (AI, IoT, Thiết bị thông minh)\n- Môi trường làm việc startup năng động, thân thiện, chuyên nghiệp\n- Tạo điều kiện học hỏi phát triển bản thân và các kỹ năng mềm\n- Lương tháng 13 + thưởng\n- Đóng BHXH ngay khi ký Hợp đồng lao động.\n\nĐịa điểm làm việc\n- Hà Nội: Khu Ngoại Giao Đoàn, Xuân Tảo, Bắc Từ Liêm, Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3120, 1431, 2, 'Lập Trình Viên PHP (Senior)', 'Mô tả công việc\n● Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng \n● Làm việc onsite Nhật tùy theo yêu cầu khách hàng.\n● Hợp tác và trao đổi công việc với Team Member, Team Leader.\n● Tham gia phát triển các công đoạn phân tích yêu cầu, Detail Design, Coding, viết tài liệu API, Unit Test.\n● Sử dụng ngôn ngữ PHP và các framework như Laravel, Yii2, ...\n● Báo cáo hàng ngày, hàng tuần cho PM và các member khác theo mô hình Agile.\n● Quản lý Tranning member\n\nYêu cầu ứng viên\n- Từ 3 năm kinh nghiệm sử dụng Framework Laravel, 1 năm kinh nghiệm teamleader\n- Có kinh nghiệm làm việc với MySQL, SQL.\n- Hiểu biết mô hình MVC Framework, ORM, RESTful, OOP.\n- Có kinh nghiệm làm việc với HTML/CSS/Javascript (jQuery/Ajax/JSON), Bootstrap,...\n-Có kiến thức về cloud, AWS\n- Viết code rõ ràng, dễ hiểu, dễ bảo trì, tuân thủ chặt chẽ coding convention.\n- Sử dụng tốt Git, SVN.\n- Có kinh nghiệm làm việc với NoSQL, MongoDB.\n- Hiểu biết và sử dụng Design Pattern.\n- Có kinh nghiệm phân tích yêu cầu, thiết kế hệ thống web.\n- Có kinh nghiệm thiết kế cơ sở dữ liệu quan hệ, tối ưu hoá SQL query.\n- Có tinh thần ham học hỏi, làm việc độc lập và tư duy lập trình tốt.\n\nQuyền lợi\n1. Thời gian và môi trường làm việc\n- Thời gian làm việc linh động 5 ngày/tuần từ 8h00 -17h30 hoặc 8h30 - 18h00 (nghỉ Thứ 7, Chủ Nhật).\n- Môi trường làm việc chuyên nghiệp, năng động, công bằng, đồng nghiệp dễ thương.\n- Tôn trọng ý kiến cá nhân, đề cao sự sáng tạo.\n- Văn phòng làm việc rộng rãi, trang phục tự do thoải mái.\n- Tham gia các câu lạc bộ: Tiếng Nhật, tiếng Anh, bóng đá, game,...\n2. Lương và Phúc Lợi\n- Đánh giá tăng lương 2 lần/năm,mức tăng lên đến 30%/lần.\n- Thu nhập năm 13 - 15 tháng lương (tối thiểu 13 tháng lương, tùy theo kết quả có thể lên đến 15 tháng lương).\n- Thưởng: 2 lần/năm, ngoài ra có thưởng nhân viên xuất sắc, thưởng Tết, thưởng giới thiệu nhân sự,...\n- Trợ cấp ăn trưa: 30.000/ngày, gửi xe, tiếng Nhật, tiếng Anh, chứng chỉ IT, trợ cấp chức vụ.\n- Nghỉ phép 12 ngày/năm, nghỉ ngày lễ kỷ niệm của gia đình: 1 ngày/năm, làm việc từ 6 tháng được tăng thêm ngày nghỉ phép.\n- Chế độ chăm sóc phụ nữ: nghỉ sinh lý 0.5 ngày/tháng.\n- Du lịch 1 lần/năm trong nước hoặc nước ngoài.\n- Tham gia các hoạt động Team Building thường xuyên như: Tiệc sinh nhật, Happy Lunch, Workshop,...\n- Khám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín.\n- Được cung cấp thiết bị phục vụ công việc: MacBook, iPad,...\n- Tham gia đầy đủ Bảo hiểm tuân thủ theo Luật Lao động hiện hành.\n3. Cơ hội phát triển, thăng tiến\n- Được training từ chuyên gia công nghệ người Nhật giàu kinh nghiệm.\n- Có nhiều hoạt động nâng cao chuyên môn (Seminar, Workshop, Techtalk,...)\n- Có cơ hội thăng tiến lên các vị trí Manager.\n- Có cơ hội làm việc và đào tạo tại Nhật Bản.\n\nĐịa điểm làm việc\n- Hà Nội\n- Hà Nội: Tòa Nhà Việt, số 1 Thái Hà, Đống Đa\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3121, 1250, 2, 'Senior Fullstack Developer (ReactJS + NodeJS)', 'Mô tả công việc:\nOUR TECH STACK:\nBackend:\nNode.js / ExpressJs\nRabbitMQ / Kafka / MSSQL\nDocker / Kubernetes / Jenkins\nFrontend:\nReactJS/ NextJs\nES6 / Webpack\nRedux / Redux-Saga / Reselect / Hooks\nRESPONSIBILITIES:\nDesign, code, and review scalable, maintainable software solutions that align with business and system architecture.\nIdentify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\nCollaborate across squads (frontend, backend, QA…) to share knowledge, align on best practices, and mentor junior team members.\nTake ownership of features or systems; lead projects or squads when needed, ensuring delivery quality and guiding technical direction.\n\nYêu cầu ứng viên:\nMust-Have:\nProactive problem-solver with a bias toward action and ownership.\nQuick to pick up new frameworks, libraries, and tooling as the stack evolves.\nAt least 4 years of real-world experience in software development.\nFamiliarity with macOS or Linux for development and deployment tasks.\nHands-on experience or working knowledge in our core stack is required; full expertise in one side (FE or BE) is acceptable:\nBackend: Node.js, PostgreSQL, Redis, Elasticsearch.\nFrontend: React.js, Redux, Redux-Saga, Reselect, React Hooks.\nCommitment to code quality:\nStrong experience in code reviews.\nFamiliarity with unit testing best practices.\nGrowth mindset: Ready to grow rapidly as the company scales several times a year.\nNice-to-Have (Plus):\nDeep understanding of Webpack, including code splitting, asset optimization, and custom configurations.\nStrong foundation in computer science: Data structures, algorithms, design patterns.\nExperience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\nFamiliarity with microservices architecture.\n\nQuyền lợi:\nCompetitive Compensation & Bonuses\nAttractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n100% salary during the probation period.\n13th-month salary to ensure financial stability.\nPerformance reviews twice a year with opportunities for salary adjustments.\nFlexible Work & Growth Opportunities\nHybrid working model: Work from home or at the office as needed.\nWork alongside top CTOs, architects, and tech leaders at Vexere.\nBuild your public profile through:\nPublishing articles on Medium & Vexere Techblog under your name.\nContributing to Open Source projects managed by Vexere.\nSpeaking at tech talks and industry events.\nAttractive stock options for dedicated developers and team leads.\nExclusive Employee Perks\nUp to 30% discount on bus tickets for Vexere employees and their families.\n12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\nVibrant and dynamic work environment with a friendly, supportive team.\nTraining sessions on negotiation, communication, work management, interpersonal skills, and software technology.\nExciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nĐịa điểm làm việc:\nHồ Chí Minh: 384 Hoàng Diệu, Quận 4\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nThứ 7 (từ 09:00 đến 12:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3122, 1482, 2, 'C++/C# Developer (Remote)', 'We are looking for talented C++/C# developers to join our dynamic team in Vietnam. If you have experience with C++/C# programing and have a passion for front-end or back-end development, we want to hear from you. Excellent communication in English is a must.\n\nResponsibilities:\n\nFront-End Development:\nDesign and develop user interfaces using MFC (for C++) or WPF (for C#).\nEnsure the UI is responsive, user-friendly, and adheres to design specifications.\n\nBack-End Development:\nDevelop back-end logic and integrate with front-end components.\nEnsure robust, scalable, and secure application architecture.\n\nApplication Development:\nWrite clean, maintainable, and efficient code in C++ or C#.\nDebug, test, and fix issues in the application codebase.\nParticipate in code reviews and adhere to coding standards.\n\nCollaboration and Communication:\nWork closely with other developers, designers to gather and understand requirements.\nParticipate in agile development processes, including sprint planning, stand-up meetings, and retrospectives.\nDocument development processes, code changes, and other relevant information.\n\nQualifications:\nBachelor\'s degree in Computer Science, Information Technology, or a related field (or equivalent experience).\nFluency in English is a must.\nProficiency in C++ or C# programming.\nStrong knowledge of algorithms, data structures, and object-oriented programming.\nExperience with MVC and MVVM software architecture patterns.\nFamiliarity with version control systems, including Git and SVN.\n\nPreferred Qualifications:\nStrong knowledge of spatial data structures, computational geometry, and linear algebra.\nExperient with Qt.\nProficiency in Python.\nProficiency in DevExpress/EyeShot.\nKnowledge of MFC (Microsoft Foundation Classes) and WPF (Windows Presentation Foundation).\n\nBenefits:\nSalary up to 2200$/month.\nCollaborate with diverse teams and influence technical decisions that align with business goals.\nFlexible working style.\nWorking remotely.\nWorking directly with Canadian developers using modern technologies.\nHolidays bonus and 13 months salary.\nSalary increase every year based on performance.\nNational holidays.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 20 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3123, 1140, 2, 'Nhân Viên Kỹ Thuật Ra File CNC Gỗ Công Nghiệp', 'Mô tả công việc\n• Tiếp nhận bản vẽ thiết kế, triển khai bản vẽ chi tiết 2D/3D từ bộ phận thiết kế.\n• Vẽ file cắt CNC (gỗ) bằng phần mềm Sketchup.\n• Thực hiện bóc tách khối lượng, lập dự trù vật tư.\n• Chịu trách nhiệm giao file cho nhân viên chạy CNC (file cắt, bản vẽ kỹ thuật, tem dán...)\n• Kiểm tra chất lượng sản phẩm cắt CNC.\n• Thực hiện các yêu cầu khác có liên quan do cấp trên giao.\n\nYêu cầu ứng viên\n• Sử dụng thành thạo phần mềm thiết kế Sketchup, Autocad,...nắm vững kết cấu các hạng mục nội thất chính như tủ - kệ trưng bày...\n• Có khả năng đọc hiểu bản vẽ.\n• Cẩn thận, nghiêm túc và có trách nhiệm với công việc.\n• Có kinh nghiệm ít nhất 2 năm tại các công ty sản xuất đồ nội thất.\n\nQuyền lợi\nChế độ BHXH, BHTN, BHYT đầy đủ theo quy định pháp luật.\nĐược học hỏi nâng cao trình độ chuyên môn.\nNghỉ lễ, tết theo quy định pháp luật.\nThưởng lễ, tết và các chế độ phúc lợi khác.\nCó công tác phí.\nTăng lương theo năng lực.\n\nĐịa điểm làm việc\n- Bắc Ninh: Tầng 2 Chung cư Cường Thịnh, Lê Thái Tổ, TP Bắc Ninh.\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3124, 165, 2, 'Lập Trình Viên Flutter', 'Về KiotViet:\nSản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ.\nVới hơn 13 năm và trên 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm.\n\nBạn sẽ làm gì:\n- Phát triển các dự án phần mềm công ty trên nền tảng Flutter Cross-Platform (Android/iOS)\n- Thực hiện các nhiệm vụ khác liên quan đảm bảo tiến độ dự án\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học ưu tiên chuyên ngành CNTT hoặc chuyên ngành liên quan;\n- Có kinh nghiệm Flutter từ 4 năm trở lên;\n- Thành thạo state management (Provider, Riverpod, Bloc…).\n- Hiểu biết hoặc đã từng làm việc với kiến trúc MVVM, Clean Architecture.\n- Có kinh nghiệm làm việc với: REST API, Firebase, Isar.\n- Native Android (Kotlin/Java) và/hoặc iOS (Swift/Obj-C) và custom plugin.\n- Nắm rõ Push notification, background tasks, deep link, crash tracking.\n- Biết viết unit test là lợi thế.\n\nQuyền lợi:\n- Mức lương khởi điểm hấp dẫn, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả làm việc lên đến 2 tháng lương; Thưởng cuối năm.\n- Làm việc từ Thứ 2 – Thứ 6, làm việc 8h/ngày và checkin linh hoạt từ 8h-9h;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...)\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm;\n- Chăm sóc sức khoẻ: Khám sức khoẻ định kỳ hàng năm, Bảo hiểm sức khoẻ cao cấp dành cho Level 3-3 trở lên theo quy định của công ty;\n- Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi;\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3125, 1245, 2, 'Nhân Viên Kỹ Thuật Điện', 'Mô tả công việc\n- Lập trình PLC, HMI\n- Thiết kế và lắp đặt tủ điện\n- Ưu tiên biết Sửa chưa mạch điện tử, biết về máy CNC, máy In Công nghiệp\n- Kiểm tra phát hiện hỏng hóc của máy và thiết bị công nghiệp tại cơ sở, nhà máy của khách hàng.\n- Nghiệm thu, chạy thử thiết bị sau sửa chữa theo sự phân công. \n- Bảo hành – bảo trì và chăm sóc khách hàng về các vấn đề kỹ thuật\n- Thực hiện các công việc khác theo sự phân công, hướng dẫn của cấp trên\n\nYêu cầu ứng viên\n- Cần cù, chịu khó, tính kỷ luật tốt và có chí cầu tiến.\n- Tốt nghiệp trung cấp, cao đẳng, đại học về chuyên ngành điện là một lợi thế.\n- Có kinh nghiệm về lập trình PCL - HMI, servo, lắp đặt tủ điện công nghiệp\n- Thái độ hơn trình độ, luôn nỗ lực trong công việc.\n- Độ tuổi: 24-38 tuổi\n\nQuyền lợi\n- Mức lương: 10.000.000-30.000.000 VNĐ \n- Được đào tạo kỹ năng về công việc.\n- Thưởng vào dịp Lễ, Tết.\n- Được hưởng các chế độ theo đúng quy định của pháp luật hiện hành: BHXH, BHYT, BHTN...và các chế độ đãi ngộ khác của Công ty.\n- Môi trường làm việc năng động, sáng tạo.\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3126, 1376, 2, 'Mid-Level ReactJS Developer', 'Mô tả công việc:\n- Tham gia nghiên cứu và phát triển sản phẩm LMS, CRM, CMS\n- Làm việc theo sự phân công của Leader\n- Phối hợp giữa các nhóm để phát triển dự án\n- Tham gia các công đoạn tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu các dự án Web - Application\n- Thiết kế và triển khai API RESTful và tích hợp với các dịch vụ của bên thứ ba (VNPay, Facebook ads, Google ads...)\n\nYêu cầu ứng viên:\n- Thành thạo HTML/CSS.\n- Xử lý thành thạo React Hook, Redux, Redux toolkit.\n- Có kiến thức về Responsive Design.\n- Có kiến thức về CSR, SSR, Websocket.\n- Sử dụng các thư viện component (e.g. Material UI).\n- Hiểu về CSS Frameworks (e.g. Tailwind CSS) và Preprocessors (e.g. Sass, SCSS).\n- Làm việc hiệu quả với các công cụ quản lý version (e.g. gitlab).\n- Có kiến thức về RestAPI, WebSocket.\n- Thành thạo git, Github, Gitlab\n- Tư duy logic tốt.\n\nQuyền lợi:\n- Luôn được hướng dẫn tư duy Logic nghiệp vụ\n- Xét lương tối thiểu 1 năm 1 lần và không dưới 10%\n- Ngày nghỉ: 12 Ngày phép trong năm + Các ngày Lễ/ Tết, Thưởng tháng 13, Tham gia BHXH, Team building\n- Các buổi training chuyên sâu kỹ thuật/ kỹ năng mềm định kỳ\n- Các giải thể thao điện tử định kỳ\n- Hoạt động bóng đá mỗi thứ 5 hàng tuần\n- Team Building tối thiểu 1 lần/năm\n- Làm việc tại một môi trường thoải mái về đồng phục nhưng chuẩn mực về thái độ\n- Cạnh tranh tại đấu trường Mona E-Sport với các môn thể thao HOT như Counter Strike, PES, Fifa... cùng nhiều giải thưởng hấp dẫn\n- Hoạt động thể thao, nâng cao sức khỏe thông qua những trận banh siêu kinh điển mỗi tuần\n- Leader luôn tạo điều kiện học hỏi và phát triển thông qua các buổi Seminar, giúp nâng cao tay nghề, tư duy làm việc chuyên nghiệp.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 1073/23 Cách Mạng Tháng 8, Phường 7, Tân Bình.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3127, 1462, 2, 'Back-End Developer', 'Mô tả công việc\n- Thiết kế, phát triển, vận hành và tối ưu hệ thống Back-End phục vụ:\nSản xuất (quản lý vật tư, nesting AI, CNC, ... )\nKinh doanh (Shopify, Amazon, website, thương mại điện tử, đơn hàng, quảng cáo, marketing, ... )\nDVKH & CRM (chatbot AI, hệ thống phản hồi, CS automation, ... )\nBáo cáo dữ liệu & phân tích BI (Power BI, Dashboard nội bộ, ... )\nXây dựng kiến trúc hệ thống: đảm bảo khả năng mở rộng, ổn định, bảo mật và hiệu suất cao (API, Microservices, background jobs, real-time pipelines, ... ).\nTích hợp với hệ thống bên ngoài: Shopify API, Amazon API, CRM, dịch vụ đám mây, ... \nXây dựng, triển khai và vận hành CI/CD pipelines, logging, monitoring, alerting, fault-tolerant recovery, xử lý sự cố sản phẩm (production troubleshooting), ... \nTham gia phân tích yêu cầu nghiệp vụ từ các phòng ban (sản xuất, kinh doanh, marketing, AI, ... ) và hiện thực hóa bằng giải pháp kỹ thuật.\nPhối hợp chặt chẽ với Front-End Developer, Data Engineer, AI Engineer, ... để xây dựng sản phẩm công nghệ hiệu quả, dễ mở rộng.\nLàm việc trực tiếp với CTO & CEO để triển khai giải pháp toàn diện, thực chiến và có tác động thực tế.\nGóp phần xây dựng tài liệu kỹ thuật, tiêu chuẩn codebase và văn hóa công nghệ nội bộ.\nLàm các công việc khác theo yêu cầu từ cấp trên (nếu có).\n\nYêu cầu ứng viên\nHọc vấn & nền tảng:\n- Tốt nghiệp Đại học loại Khá – Giỏi trở lên, chuyên ngành CNTT, Khoa học máy tính, Kỹ thuật phần mềm, Toán – Tin hoặc các ngành liên quan.\n- Ưu tiên có giải thưởng học thuật, học bổng, hoặc tham gia các cuộc thi về công nghệ (Olympic Toán – Tin học, Hackathon, Competition, ... ).\nKỹ năng & kinh nghiệm:\n- Có tối thiểu 3 năm kinh nghiệm làm Back-End Developer.\n- Thành thạo ít nhất một trong các ngôn ngữ sau: Node.js, C, C++, Python, Go, Java – ưu tiên Node.js & Python.\n- Kiến thức vững chắc về: RESTful API, GraphQL APIs, Webhook, Microservices, Pub/Sub, Message Queue (RabbitMQ, Kafka), ... \n- Thành thạo: PostgreSQL, MongoDB, Redis. Biết tối ưu query, schema, indexing.\n- Thành thạo: FastAPI, Flask, Django, ... \n- Triển khai thành thạo: CI/CD (GitHub Actions, GitLab CI, ... ), Docker, Git, môi trường Linux.\n- Biết cách xử lý lỗi production, log tracing, performance tuning.\n- Có kinh nghiệm thực tế với các nền tảng thương mại điện tử: Shopify, Amazon, ... \n- Đã từng làm việc trong các dự án vừa – lớn, yêu cầu uptime cao.\n- Có kiến thức hoặc từng làm việc cùng team AI, hiểu quy trình train/deploy AI models.\n- Có GitHub nổi bật, blog kỹ thuật, dự án side project là điểm cộng.\n- Chủ động, có trách nhiệm cao, tư duy phản biện, không chỉ “nhận task – làm task” mà còn đề xuất giải pháp – tối ưu hệ thống.\n- Tư duy hệ thống, có khả năng thiết kế giải pháp toàn diện, phù hợp với bài toán thực tế doanh nghiệp.\n- Giao tiếp rõ ràng, teamwork tốt, biết diễn đạt kỹ thuật theo ngôn ngữ kinh doanh.\n- Thích nghi nhanh, chịu được môi trường thay đổi liên tục, không ổn định, chịu áp lực tốt, làm việc tốt trong môi trường startup – nơi chưa có sẵn mọi thứ.\n- Biết cân bằng giữa “đúng kỹ thuật” và “đủ để vận hành hiệu quả”.\n- Có tinh thần học hỏi, cầu thị, dám thử – dám sửa, sẵn sàng học công nghệ mới nếu cần.\n- Có kỹ năng giải quyết vấn đề và tư duy logic tốt.\n- Có khả năng tổ chức công việc và quản lý thời gian hiệu quả.\n\nQuyền lợi\n- Lương cạnh tranh theo năng lực, có thưởng dự án rõ ràng.\n- Chế độ phúc lợi theo Luật lao động và chính sách của công ty.\n- Được tham gia đầy đủ BHXH theo quy định nhà nước và gói bảo hiểm sức khỏe cho nhân viên.\n- Du lịch hàng năm, các hoạt động nội bộ mỗi tháng.\n- Được giao nhiệm vụ trực tiếp từ CTO & CEO – tạo ảnh hưởng thật lên vận hành doanh nghiệp.\n- Tham gia các dự án AI, automation, thương mại điện tử, sản xuất thông minh.\n- Môi trường startup Mỹ – sáng tạo, chuyên nghiệp, minh bạch.\n- Làm việc từ xa hoặc tại văn phòng – linh hoạt theo năng lực.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 88 Nguyễn Gia Trí, Bình Thạnh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 17:30)\n- Thứ 7 (từ 09:00 đến 12:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3128, 165, 2, 'Flutter Developer (Middle, Product)', 'Về KiotViet: Sản phẩm công nghệ của KiotViet được nghiên cứu và sáng tạo tại Việt Nam, bởi kỹ sư phần mềm Việt, dựa vào đóng góp từ hàng trăm nghìn chủ doanh nghiệp, với sứ mệnh mang lại giá trị cho cộng đồng kinh doanh lớn nhỏ trên khắp mọi miền tổ quốc và các quốc gia đang trên đà phát triển hưng thịnh. KiotViet cam kết đồng hành cùng cộng đồng kinh doanh vừa, nhỏ và siêu nhỏ. Với hơn 13 năm và hơn 1,500 con người để tạo nên một KiotViet của ngày hôm nay, chúng tôi hiểu rằng các thành viên, từ quá khứ tới tương lai, là nền tảng cho KiotViet của ngày hôm nay và bệ phóng để vươn tới một KiotViet của ngày mai. KiotViet cam kết một môi trường làm việc chia sẻ thành công, cùng chung trách nhiệm. Bạn sẽ làm gì: - Phát triển app Phần mềm quản lý bán hàng KiotViet trên nền tảng Flutter Cross-Platform (Android/iOS) - Phối hợp với team phát triển các tính năng mới theo Agile/Scrum - Thực hiện các nhiệm vụ khác liên quan đảm bảo tiến độ dự án \n\nYêu cầu ứng viên: - Tốt nghiệp cao đẳng, đại học; ưu tiên tốt nghiệp chuyên ngành CNTT hoặc chuyên ngành liên quan - Có từ 3 năm kinh nghiệm với Mobile, trong đó kinh nghiệm Flutter từ 2 năm, native từ 01 năm - Bạn có kiến thức về MVP, MVVM, hiểu biết về Clean Architecture là một lợi thế - Bạn có kiến thức Bloc + Cubit (optional), Domain driven design - Ưu tiên có kinh nghiệm coding tool (AI coding tool: Cursor/ Github copilot/ Windsurf) - Có tinh thần học hỏi, chủ động trong công việc và có kỹ năng quản lý sắp xếp công việc và thời gian tốt\n\nQuyền lợi: - Mức lương khởi điểm cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc; - Thưởng hiệu quả làm việc lên đến 2 tháng lương, Thưởng cuối năm; - Làm việc từ Thứ 2 – Thứ 6, checkin linh hoạt trong khung từ 08h-09h - Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...) - Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, và các hoạt động thú vị khác trong năm; - Chăm sóc sức khoẻ : Khám sức khoẻ định kỳ hàng năm, Bảo hiểm sức khoẻ cao cấp dành cho Level 3-3 trở lên theo quy định của công ty; - Làm việc trong môi trường trẻ trung, năng động; Không gian làm việc đẹp, không gian pantry rộng rãi; - Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại; - Cơ hội được đào tạo và thăng tiến tốt trong công việc. Lộ trình phát triển công việc rõ ràng.\n\nĐịa điểm làm việc: - Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm, Hoàn Kiếm.\n\nThời gian làm việc: Thứ 2 - Thứ 6, làm việc 8 tiếng/ngày và checkin linh hoạt trong khung 8h-9h.\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3129, 165, 2, '.NET Developer', '1. Nhiệm vụ chính:\n- Tham gia cùng team thiết kế và làm rõ yêu cầu tính năng người dùng theo mô hình ATDD\n- Xây dựng chức năng của sản phẩm bao gồm back-end và front-end cho hệ thống, đảm bảo chất lượng code cũng như yêu cầu nghiệp vụ và hiệu năng hệ thống.\n- Giải quyết các vấn đề khó về tối ưu hệ thống cũng như nghiệp vụ người dùng.\n- Nghiên cứu các giải pháp, công nghệ mới để cải tiến sản phẩm.\n- Làm việc cùng các vai trò khác trong feature team để đạt mục tiêu chung của sản phẩm.\n\n2. Cơ hội phát triển:\n- Làm việc với hệ thống hàng triệu user, với một lượng lớn giao dịch và truy vấn.\n- Công nghệ đa dạng và hệ thống code base lớn, bạn có cơ hội rèn dũa / training nâng cao kỹ năng software craftsmanship để đảm bảo chất lượng, hiệu suất tốt, trải nghiệm người dùng và khả năng tái sử dụng tốt hơn.\n- Cùng với các bài toán về kỹ thuật cũng như sản phẩm thử thách và thú vị, cũng là cơ hội để phát triển tư duy giải quyết vấn đề và thiết kế hệ thống tốt hơn, theo cách đơn giản và tinh tế nhất có thể.\n- Career path rõ ràng cho lộ trình phát triển và trưởng thành của thành viên.\n\n1. Học vấn, kiến thức và trình độ chuyên môn: Tốt nghiệp đại học chuyên ngành CNTT\n2. Kinh nghiệm:\n- Có kinh nghiệm với Asp.net MVC, Web API\n- Có năng lực kinh nghiệm làm việc với design pattern, clean code.\n3. Những kỹ năng cần thiết cho công việc\n- Có kỹ năng C#.NET 4.0/4.5, OOP, Design Pattern, IoC\n- Có kiến thức nền tảng và kinh nghiệm về:: JQuery, Typescript, HTML5/CSS3, HTML/XHTML/XML,CSS, Bootstrap, IIS\n- Có hiểu biết về các công nghệ Redis, Realtime\n- Có hiểu biết Database, SQL Server, Queue Messaging, Front end framework (Angular, React)…\n- Có khả năng học hỏi nhanh, tích cực và chủ động trong công việc. Khả năng làm việc độc lập và làm việc nhóm tốt.\n\n- Mức lương khởi điểm hấp dẫn, cạnh tranh, tương xứng với năng lực và kinh nghiệm làm việc;\n- Thưởng hiệu quả lên đến 3 tháng lương/năm.\n- Thưởng dự án, thưởng quý;\n- Làm việc từ Thứ 2 – Thứ 6, ca làm việc linh hoạt;\n- Cơ hội được đào tạo và thăng tiến tốt trong công việc.Lộ trình phát triển công việc rõ ràng;\n- Được hưởng các quyền lợi và chế độ theo luật quy định (Các ngày nghỉ lễ, BHXH, BHYT...);\n- Thưởng lễ, Tết, sinh nhật các chế độ đãi ngộ dành cho người thân, du lịch hàng năm;\n- Làm việc trong môi trường trẻ trung, năng động\n- Được cung cấp máy tính cấu hình cao, trang thiết bị làm việc hiện đại;\n\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Chấm công linh hoạt từ 8:00-9:00 đến 17:30-18:30.\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3130, 1221, 2, 'Front-End Developer', 'Mô tả công việc:\n- Tham gia phát triển các dự án phần mềm cho khách hàng Nhật Bản;\n- Phối hợp xử lý sự cố, khắc phục lỗi trong quá trình phát triển và vận hành hệ thống;\n- Xây dựng giao diện website dựa trên bản thiết kế từ Figma, đảm bảo đúng yêu cầu UI/UX;\n- Phát triển các ứng dụng hiệu suất cao, có khả năng mở rộng (scalable) và dễ dàng cải tiến trong tương lai.\n\nYêu cầu ứng viên:\n- Tối thiểu 3 năm kinh nghiệm lập trình phát triển Web;\n- Trong đó có ít nhất 2 năm kinh nghiệm chuyên sâu với ReactJS và Next.js;\n- Hiểu rõ Server-Side Rendering (SSR), Static Site Generation (SSG), Incremental Static Regeneration (ISR) và tối ưu hóa hiệu suất của ứng dụng Next.js;\n- Thành thạo ReactJS và công nghệ liên quan: JavaScript/TypeScript ES6+; Hooks, Context API, Redux, Redux Thunk, Redux Saga...;\n- Có kinh nghiệm làm việc với ít nhất một trong các UI Framework/Library phổ biến như Material UI, Ant Design, Tailwind CSS, Bootstrap, Chakra UI...;\n- Có khả năng thiết kế và xây dựng các components/modules có thể tái sử dụng (reusable components/modules) chất lượng cao;\n- Thành thạo làm việc với RESTful API và sử dụng Axios để gọi API;\n- Có khả năng phối hợp chặt chẽ với đội ngũ Backend để tích hợp API và triển khai các tính năng, đặc biệt là trong các dự án có kiến trúc server-side rendering hoặc fullstack với Next.js;\n- Hiểu rõ về clean code, coding convention và các nguyên tắc thiết kế phần mềm;\n- Có kinh nghiệm trong việc tối ưu hóa hiệu suất và nâng cao chất lượng source code;\n- Nắm vững các kỹ thuật debug trong môi trường Frontend;\n- Có kinh nghiệm làm việc với Git và các Git Workflow phổ biến như Git Flow, GitHub Flow, đặc biệt trong các dự án lớn.\n\nQuyền lợi:\n- Mức lương up to 24,000,000 VND/tháng (chưa bao gồm thưởng dự án, thưởng lễ tết, và các khoản thưởng khác...);\n- Thu nhập: 13 tháng lương/năm + thưởng dự án, thưởng Tết và các dịp lễ…;\n- Xét tăng lương 2 lần/năm theo năng lực và hiệu quả công việc;\n- Nghỉ thứ 7, Chủ nhật + Nghỉ phép theo Quy định của Pháp luật hiện hành;\n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty;\n- Khám sức khỏe định kỳ 1 năm/1 lần;\n- Bảo hiểm chăm sóc sức khỏe 24/24 ( PVI Care);\n- Tham gia các Câu lạc bộ văn hóa, thể thao trong công ty: CLB Bóng đá, CLB Game…\n- Tham gia các hoạt động tập thể sôi động theo tháng/quý/năm: Nghỉ mát hàng năm, Teambuilding, Gala cuối năm…\n\nĐặc biệt:\n- Được hỗ trợ 100% chi phí tham gia các khóa học kỹ năng mềm, các khóa đào tạo chuyên môn, luyện thi các chứng chỉ uy tín trong và ngoài nước và khen thưởng khi đạt chứng chỉ chuyên môn;\n- Học tập không giới hạn qua tài khoản học trực tuyến Udemy;\n- Cơ hội làm việc và đào tạo tại Nhật Bản với các ứng viên có tiếng Nhật;\n- Làm việc trong môi trường chuyên nghiệp, được hỗ trợ phát huy khả năng, phát triển công việc tối đa.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 17, 18, 19 Tòa Central Point, 219 Trung Kính, Cầu Giấy.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3131, 1211, 2, 'Unity Developer Intern', 'Mô tả công việc\n- Tham gia vào các dự án game của công ty.\n- Chuyển thể các thiết kế của Game Artist và Game Design thành các chức năng của game.\n- Thiết kế, xây dựng và duy trì Code hiệu quả, có thể tái sử dụng và đáng tin cậy.\n- Làm việc theo hướng dẫn và phân công của leader.\n\nYêu cầu ứng viên\n- Sinh viên năm thứ 4 - 5 các trường đại học chính quy ngành Công nghệ thông tin hoặc tương đương.\n- Yêu cầu đi làm tối thiểu 8 buổi/tuần.\n- Có kinh nghiệm lập trình C#.\n- Tư duy logic tốt, ham học hỏi và sẵn sàng trải nghiệm những thử thách mới.\n- Ưu tiên có kinh nghiệm về Unity, hoặc đã nghiên cứu về Unity.\n\nQuyền lợi\n- Cơ hội lên chính thức sau thực tập.\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Hỗ trợ cơm trưa, tea-break,...\n- Hỗ trợ đóng dấu thực tập.\n- Du lịch, team building: 3 lần/năm.\n- Môi trường làm việc vô cùng sáng tạo, năng động, được thoải mái chơi các trò chơi tại công ty: bida, PS, board game,...\n- Thời gian làm việc: 8:15 - 17:45 (7,5 giờ/ngày; thứ Hai - thứ Sáu).\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Rivera Park, 69 Đ. Vũ Trọng Phụng, Thanh Xuân.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:45).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3132, 1321, 2, 'Nhân Viên Lập Trình Web', 'Mô tả công việc:\n- Lập trình website bằng PHP, sử dụng các framework phổ biến như Laravel, CodeIgniter hoặc CMS như WordPress.\n- Chuyển đổi thiết kế Figma thành mã nguồn HTML/CSS, kết hợp với các framework Frontend (Bootstrap, Tailwind, v.v.). - Có khả năng thiết kế giao diện website trên Figma hoặc sử dụng Figma thành thạo là một lợi thế.\n- Tích hợp API, tối ưu hiệu suất website, đảm bảo tốc độ tải trang nhanh, bảo mật tốt.\n- Hỗ trợ kỹ thuật, chỉnh sửa, nâng cấp website theo yêu cầu của khách hàng.\n\nYêu cầu ứng viên:\n- Thành thạo Figma, có tư duy thiết kế UI/UX tốt.\n- Có kinh nghiệm làm việc với HTML, CSS, JavaScript (jQuery, Vue.js là lợi thế).\n- Thành thạo lập trình PHP & MySQL, ưu tiên biết sử dụng Laravel, CodeIgniter.\n- Am hiểu về WordPress là một lợi thế lớn.\n- Có tư duy logic, khả năng giải quyết vấn đề kỹ thuật nhanh chóng.\n- Có kinh nghiệm tối ưu website (SEO, bảo mật, tốc độ tải trang) là điểm cộng.\n\nQuyền lợi:\n- Thu nhập từ 10 - 20 triệu/tháng (Lương cứng + thưởng theo dự án).\n- Cơ hội nâng cao chuyên môn với các dự án thực tế, làm việc với công nghệ tiên tiến.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, hỗ trợ lẫn nhau.\n- Tham gia các dự án lớn, hợp tác cùng đối tác Google, Lark, Microsoft.\n- Chế độ đãi ngộ đầy đủ: BHXH, nghỉ phép, lương tháng 13, thưởng lễ Tết.\n- Địa điểm làm việc: Văn phòng Vinaweb - Hải Phòng.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 07:30 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3133, 1200, 2, 'Middle Frontend', 'Mô tả công việc\n- Thiết kế và phát triển các mô-đun và thành phần frontend có thể tái sử dụng, tạo thành nền tảng cho các ứng dụng của chúng tôi.\n- Lập kiến trúc và triển khai các giải pháp frontend có thể mở rộng bằng cách sử dụng các framework JavaScript hiện đại.\n- Đưa ra các quyết định kỹ thuật cho kiến trúc frontend và thiết lập các tiêu chuẩn mã hóa.\n- Tạo mã code hiệu quả, dễ bảo trì và tối ưu hiệu suất.\n- Xây dựng và duy trì các thư viện thành phần UI cốt lõi để sử dụng trên toàn công ty.\n- Dẫn dắt việc triển khai các tính năng frontend phức tạp và đảm bảo chất lượng mã.\n- Làm việc chặt chẽ với đội ngũ thiết kế và backend của chúng tôi để tạo ra giao diện người dùng liền mạch.\n- Học hỏi và áp dụng các tiêu chuẩn phát triển và thực tiễn tốt nhất của Nhật Bản thông qua sự hướng dẫn trực tiếp.\n- Tham gia trong quy trình phát triển linh hoạt của chúng tôi từ lập kế hoạch kiến trúc đến kiểm tra.\n\nYêu cầu ứng viên\n- Ít nhất 3 năm kinh nghiệm phát triển front-end chuyên nghiệp.\n- Kinh nghiệm sâu rộng với Next.js và TypeScript.\n- Thành thạo Tailwind CSS và có kinh nghiệm xây dựng UI component tùy chỉnh.\n- Có kinh nghiệm triển khai giải pháp xác thực người dùng, ưu tiên Auth.js.\n- Hiểu biết về quy trình CI/CD và kinh nghiệm làm việc với Azure DevOps.\n\nQuyền lợi\n- Mức lương 18.000.000 - 32.000.000.\n- Thời gian làm việc: 8h00-17h30, nghỉ trưa 1,5h (12h – 13h30) từ thứ 2 - thứ 6.\n- 13 tháng lương + thưởng lễ tết; xét tăng lương hàng năm.\n- Du lịch hàng năm, team building hàng tháng/quý.\n- Bảo hiểm xã hội, BHYT theo quy định của Nhà nước.\n- Gói bảo hiểm sức khỏe.\n- Khám sức khoẻ định kỳ hàng năm.\n- Môi trường flat trẻ trung, thoải mái.\n- Cơ hội tham gia dự án tiềm năng, thử thách nhưng không kém phần thú vị.\n\nĐịa điểm làm việc\n- Hà Nội: Hoàng Mai.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hoàng Mai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3134, 1327, 2, 'Product Developer (Merchandiser)', 'Chi tiết tin tuyển dụng:\n\nMô tả công việc:\n\n- Maintains accuracy of technical specification packs for each product, including BOM and measurements.\n- Tracks prototypes and samples for development, marketing, and sales needs. Ensures every stage is on time per the published timeline.\n- Manage end-to-end product development, from timeline adherence, material sourcing, costing through to production handover.\n- Be the voice of Product Development cross functionally communicating product status, costing and suggesting process improvement where possible. \n- Build and maintain material library for products in line with design needs and category vision.\n- Work hand in hand with QA, Production, Sourcing, Packaging, Design team and other necessary teams ensuring product cycle deadlines are met and product standards are upheld.\n- Source new suppliers based on category growth and needs.\n- Facilitate day-to-day communications with existing suppliers and manufacturers focusing on in building strong and trusted relationships with overseas partners.\n- Responsible for the main sketches and drawings of each product.\n- Sketch out the design spec sheets by Adobe Illustrator.\n- Make packaging instructions.\n- Participate in meetings to discuss designs and line development, and present and review line and concepts regularly.\n\nYêu cầu ứng viên:\n\n- Good verbal and written communication skills in English.\n- Minimum 1 years’ experience in backpack or at factory.\n- Proficiency in Adobe Illustrator is mandatory.\n- Can work under high pressure, hard-working and honestly.\n- Communication skills: considering work in teams, a great communicator needed.\n- Must be able to learn and collaborate with other members.\n\nQuyền lợi:\n\n- Working days: 5 days/week, from Monday to Friday.\n- Working time: 7:30 – 16:30.\n- Full pay social insurance.\n- Paid Leave: Follow VN Labor Law.\n- Have 13th-month salary and other benefits follow the company’s policy.\n- Allowance: daily meal allowance on working days.\n- Company’s Library for all employees with collections of books.\n- Top-level All-Free Pantry.\n- Annual or Seasonal Outdoor Activity with employees.\n- Participating other annual events.\n- Free Learning Courses to develop working skills (photoshop / MS office / etc).\n- Loyalty Program:\n  - Private Health Insurance to all employees and employees’ families (According to the length of service).\n  - Annual employee gifts.\n  - Senior staff benefits.\n  - Oversea trip opportunities (Korea, Japan, US, EU / etc).\n  - Others.\n- Basic Annual leave: 15 days/ year.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3135, 1222, 2, 'Kỹ Thuật Viên Lập Trình CAD-CAM & Vận Hành Máy CNC', 'Mô tả công việc\n- Nhận file thiết kế khuôn, jig, chi tiết máy từ bộ phận thiết kế, kiểm tra độ chính xác, độ phù hợp của các thiết kế và thực hiện đề xuất/ điều chỉnh nếu cần thiết;\n- Trên cơ sở thiết kế tiến hành bóc tách vật tư, linh kiện và thực hiện lập trình chương trình gia công CNC trên các phần mềm chuyên dụng;\n- Trực tiếp setup, đứng máy vận hành & theo dõi quá trình máy chạy, điều chỉnh chương trình ngay khi phát hiện sự cố, đảm bảo quá trình vận hành máy an toàn và chính xác, thời gian gia công tối ưu;\n- Thực hiện các công việc khác theo sự phân công của cấp trên.\n\nYêu cầu ứng viên\n- Tốt nghiệp Trung cấp trở lên chuyên ngành Cơ khí, Cơ điện tử, Cơ khí chế tạo, Công nghệ kĩ thuật cơ khí,...và các chuyên ngành có liên quan;\n- Đọc hiểu bản vẽ cơ khí;\n- Sử dụng các phần mềm lập trình CAM, phần mềm thiết kế CAD 2D, 3D như SolidCAM, MasterCAM, Siemens NX;\n- Có kinh nghiệm lập trình CAD/CAM và vận hành máy phay CNC. Có khả năng lập trình đường chạy dao/chọn dao phù hợp với từng thiết kế đảm bảo sự chính xác khi gia công và tối ưu hóa thời gian gia công;\n- Có khả năng vận hành các dòng máy phay CNC sử dụng hệ điều hành Fanuc, Mitsubishi như Doosan, Makino, Fanuc Robodilll;\n- Có trách nhiệm, chịu khó, chủ động cải tiến trong công việc;\n- Đã làm việc trong các nhà máy áp dụng tiêu chuẩn 5S, ISO là một lợi thế;\n- Ứng viên có kinh nghiệm lập trình chương trình gia công cho các dòng máy cắt dây, xung điện như Sodick, CHMER là một lợi thế;\n- Ưu tiên ứng viên người địa phương, ở gần nhà máy tại Khu công nghiệp Yên Phong; có khả năng đi làm theo ca.\n\nQuyền lợi\n- Mức lương khởi điểm sau khi tiếp nhận chính thức từ 7.500.000 đến 15.000.000 đồng (Có thể thỏa thuận với trường hợp ứng viên vượt trội về năng lực/kinh nghiệm);\n- Môi trường làm việc an toàn, chuyên nghiệp, thân thiện (áp dụng hệ thống Quản lý chất lượng/ Quản lý môi trường theo tiêu chuẩn ISO 9001/ ISO 14001 và phương pháp 5S, Kaizen);\n- Cơ hội được đào tạo chuyên môn, kỹ năng làm việc; nhiều cơ hội phát triển, thăng tiến;\n- Được đóng BHXH, BHYT, ngày nghỉ phép năm theo quy định;\n- Được hưởng các chế độ phúc lợi; thưởng các dịp Lễ, Tết theo quy định của Công ty; thưởng sáng kiến, thưởng nhân viên của năm;\n- Được tham gia các hoạt động do Công ty tổ chức: du lịch, teambuilding...;\n- Được cấp phát đồng phục làm việc theo tiêu chuẩn Công ty;\n- Khám sức khỏe định kì tại các cơ sở bệnh viện uy tín; phụ cấp ăn trưa tại Nhà máy và một số phụ cấp khác theo quy định của Công ty.\n\nĐịa điểm làm việc\n- Bắc Ninh: Khu Công nghiệp Yên Phong, Xã Long Châu, Yên Phong\n\nThời gian làm việc\n- Làm ca\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3136, 72, 2, 'Android Developer (Kotlin)', 'Mô tả công việc\n✓ Phát triển, duy trì và cải tiến mã nguồn Kotlin dùng chung cho cả nền tảng Android và IOS, đảm bảo tích hợp mượt và hiệu quả trên cả hai hệ sinh thái. \n✓ Thực hiện đánh giá kỹ lưỡng mã nguồn để đảm bảo chất lượng và triển khai hiệu quả với Kotlin Multiplatform, tuân thủ các phương pháp tốt nhất về tính duy trì và khả năng mở rộng.\n✓ Tối ưu hóa mã Kotlin dùng chung, tận dụng thế mạnh riêng của từng nền tảng và duy trì mã nguồn thống nhất.\n✓ Kiến trúc, review code, tối ưu để tăng trải nghiệm.\n✓ Phân tích, đánh giá, lập kế hoạch phát triển, trao đổi nhóm để đưa ra nhiệm vụ cần thực thi liên quan. \n✓ Cập nhật xu hướng phát triển công nghệ mới để áp dụng vào dự án. \n\nYêu cầu ứng viên\n✓ Tốt nghiệp đại học chuyên ngành CNTT loại khá trở lên.\n✓ Tối thiểu 3 - 5 năm kinh nghiệm phát triển Android với Kotlin và có kinh nghiệm với Swift/Objective-C trong phát triển IOS là một lợi thế.\n✓ Thành thạo Jetpack Compose, Coroutines và Flow.\n✓ Kỹ năng làm việc nhóm và giải quyết vấn đề tốt.\nƯu tiên:\n✓ Biết Swift/Objective C hoặc từng làm việc với ứng dụng native iOS.\n✓ Có kinh nghiệm tích hợp Google Maps, Mapbox, multimedia (audio/video), hoặc WebRTC.\n✓ Kinh nghiệm kết nối và xử lý dữ liệu với các thiết bị IoT qua BLE hoặc WiFi.\n✓ Hiểu và áp dụng tốt Material Design, custom layout.\n✓ Từng tham gia dự án theo mô hình Agile/Scrum thực tế.\n✓ Kỹ năng mềm: lãnh đạo nhóm, giao tiếp, làm việc nhóm, giải quyết vấn đề.\n✓ Kinh nghiệm quản lý đội nhóm.\n\nQuyền lợi\n✓ Gói thu nhập cạnh tranh.\n✓ Đầy đủ các chế độ theo luật lao động hiện hành.\n✓ Chính sách phúc lợi theo quy định của Công ty đa dạng: Chăm sóc sức khỏe định kì hàng năm; Gói bảo hiểm sức khỏe chuyên biệt (FPT Care – Khám chữa bệnh miễn phí tại tất cả các bệnh viện); Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân ...\n✓ Môi trường làm việc thân thiện, cởi mở.\n✓ Cơ sở vật chất và công cụ làm việc hiện đại, tiện nghi.\n✓ ​Nhiều cơ hội phát triển và thăng tiến.\n✓ Văn hóa Doanh nghiệp đặc sắc, sinh động bậc nhất với nhiều các hoạt động hấp dẫn: tân binh, teambuilding, thi trạng, hội làng, hội diễn Sao Chổi, sinh nhật FPT, ngày 08/03, ngày 11/11...\n✓ Hưởng các gói ưu đãi cước khi sử dụng dịch vụ của FPT Telecom.\n✓ Ghi chú: FPT Telecom không thu bất kỳ chi phí nào của Ứng viên, Sinh viên trong quá trình tuyển dụng, thực tập.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Lô L.29B-31B-33B đường Tân Thuận, Khu chế xuất Tân Thuận, phường Tân Thuận Đông, Quận 7\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3137, 1113, 2, 'IT Manager', 'Mô tả công việc:\n- Develop, maintain, and optimize internal software systems to support operations at AEON Fantasy entertainment centers.\n- Participate in requirements analysis, system design, coding, and testing of software applications.\n- Support the rollout of new software at branches and ensure stable system performance.\n- Work closely with various departments (Operations, Sales, HR, etc.) to gather requirements and provide technical support.\n- Ensure security, performance, and scalability of software systems.\n- Install POS systems, game card readers; troubleshoot errors or coordinate with Speed, Semnox, or IM Link to resolve software and hardware issues; set up product pricing, game machine pricing, promotion programs, etc.\n- Review, negotiate, and sign annual maintenance contracts for systems.\n- Perform other IT-related tasks as assigned by the Board of Directors.\n\nYêu cầu ứng viên:\n- Bachelor\'s degree in Information Technology or a related field.\n- 5–7 years of experience in software development (candidates with experience in internal systems or retail systems are preferred).\n- Proficient in at least one of the following programming languages: Java, C#, PHP, Python, or JavaScript.\n- Experience working with databases such as MySQL, SQL Server, or equivalent.\n- Preferably experienced in developing software on web platforms (ReactJS, VueJS, etc.) or mobile platforms (Android/iOS).\n- Knowledge of MVC architecture, RESTful APIs, Git, and Agile/Scrum methodology is an advantage.\n- Strong teamwork and communication skills.\n- Proactive, responsible, detail-oriented, and eager to learn.\n\nQuyền lợi:\n- Working from Monday to Friday\n- Contribute social insurance at 100%\n- A dynamic, youthful, and international working environment\n- Opportunities for career advancement\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 36 Bùi Thị Xuân, Quận 1\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3138, 1237, 2, 'Senior Developer', 'Mô tả công việc:\n- Tuân thủ các tiêu chuẩn lập trình, xây dựng mã nguồn chất lượng cao, dễ bảo trì.\n- Luôn duy trì động lực và cập nhật các xu hướng, công nghệ mới nhất trong lĩnh vực phát triển web.\n- Hướng dẫn và hỗ trợ các thành viên cấp dưới nâng cao kỹ năng, đảm bảo đạt được hiệu suất và năng lực phù hợp với mục tiêu dự án.\n- Tích cực tham gia các hoạt động chia sẻ kiến thức và cải tiến quy trình làm việc liên tục.\n\nYêu cầu ứng viên:\n[Bắt buộc]\n- Tối thiểu 2 năm kinh nghiệm thiết kế và tối ưu các hệ thống hiệu suất cao.\n- Hiểu rõ và vận dụng tốt các mô hình lập trình hướng đối tượng (OOP) và lập trình hàm (Functional Programming).\n- Thành thạo ít nhất một trong các ngôn ngữ lập trình như: Java, Scala, Python, TypeScript.\n- Có kinh nghiệm làm việc với các frontend framework như: React, Vue hoặc Angular; và giao tiếp với RESTful hoặc GraphQL APIs.\n- Nắm vững quy trình phát triển phần mềm theo phương pháp Agile/Scrum.\n- Có hiểu biết về ít nhất một trong các nền tảng đám mây như AWS, GCP hoặc Azure.\n\n[Không bắt buộc]\n- Có kinh nghiệm lập trình với Scala là một lợi thế.\n- Đã từng sử dụng các công cụ hỗ trợ lập trình bằng AI như GitHub Copilot, Cursor AI hoặc Windsurf AI.\n- Có kinh nghiệm thiết kế, tối ưu truy vấn và truy cập cơ sở dữ liệu.\n- Thành thạo kỹ thuật viết kiểm thử (Test-Driven Development - TDD) và thiết kế testcase.\n- Khả năng giao tiếp hoặc đọc hiểu tiếng Nhật là một điểm cộng.\n\nQuyền lợi:\n- Mức lương đến 1500$\n- Chế độ làm việc linh hoạt Flexible time (7:30 AM - 06:30PM). VD: Check in 7:30 có thể check out 16:30.\n- Địa điểm làm việc: làm việc tại văn phòng Hà Nội\n- Tăng lương và thưởng 2 lần/năm\n- Bảo hiểm sức khỏe Bảo Việt, khám sức khỏe hàng năm ở bệnh viện uy tín\n- Du lịch Công ty, các câu lạc bộ bóng đá, bơi, gym ...\n\nĐịa điểm làm việc:\n- Hà Nội: Discovery Complex, 302 Cầu Giấy, Dịch Vọng, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3139, 1344, 2, 'Senior Backend Developer (C#, Java, Python)', 'Mô tả công việc\n- Thiết kế kiến trúc hệ thống backend hiệu quả, linh hoạt và dễ mở rộng.\n- Viết code clean, có thể kiểm thử, hiệu quả và bảo trì tốt.\n- Định hướng kỹ thuật, code review, và hỗ trợ thành viên trong team backend.\n- Phối hợp với các team frontend, mobile, sản phẩm và QA để đảm bảo tiến độ và chất lượng dự án.\n- Đưa ra các quyết định kỹ thuật quan trọng, định hướng công nghệ phù hợp cho dự án.\n- Quản lý, phân chia công việc và theo dõi tiến độ của nhóm backend.\n- Đào tạo, mentoring và phát triển năng lực cho các thành viên junior.\n- Hỗ trợ, xử lý kỹ thuật trong quá trình bàn giao, sử dụng.\n- Đảm bảo hiệu suất, bảo mật và độ tin cậy của hệ thống backend.\n\nYêu cầu ứng viên\n- Hiểu về quy trình phát triển phần mềm theo mô hình Agile Scrum.\n- Có từ hơn 4 năm kinh nghiệm phát triển backend, ưu tiên sử dụng một trong các ngôn ngữ: C#, Java, Python, NodeJS.\n- Hiểu biết sâu về kiến trúc microservices, RESTful API, WebSocket, GraphQL.\n- Thành thạo với cơ sở dữ liệu quan hệ (MySQL/PostgreSQL) và NoSQL (MongoDB/Redis).\n- Kinh nghiệm với CI/CD, Docker, Kubernetes, và các hệ thống triển khai thực tế.\n- Có hiểu biết tốt về các vấn đề liên quan đến bảo mật hệ thống backend.\n- Kinh nghiệm tối ưu hóa hiệu suất hệ thống và xử lý tải lớn là một lợi thế.\n- Lĩnh vực làm việc: ưu tiên ứng viên đã làm việc tại các công ty phần mềm giải pháp cho khách sạn, thương mại điện tử, ERP\n- Có khả năng học hỏi nhanh, luôn cập nhật các nghiệp vụ liên quan tới du lịch, khách sạn, tài chính là lợi thế.\n- Có kinh nghiệm dẫn dắt team từ 3–5 người trở lên là lợi thế.\n- Kỹ năng giao tiếp rõ ràng, truyền đạt ý tưởng mạch lạc với cả team kỹ thuật lẫn non-tech.\n- Có khả năng phân tích và ra quyết định kỹ thuật nhanh, chính xác.\n- Tư duy logic, trách nhiệm cao, chủ động và cầu tiến trong công việc.\n\nQuyền lợi\n- Mức thu nhập 28-33 triệu gross, thỏa thuận khi phỏng vấn.\n- Cơ hội phát triển, khẳng định chính mình và thăng tiến cực lớn, trở thành nhà quản lý chỉ sau 2 - 3 năm\n- Văn phòng đẹp nhất, sáng tạo và thân thiện với môi trường do chính những thế hệ trẻ của Apec kiến tạo nên\n- Hoạt động nội bộ (du lịch, team building,...)\n- Thưởng lễ tết, thưởng quý, thưởng cuối năm, lương tháng thứ 13+++.\n- Có cơ hội được tham gia một số dự án đã và đang phát triển của p.CNTT:\n- Hệ thống giao dịch thị trường chứng khoán trái phiếu, website bảng giá, Mobile App giao dịch cho nhà đầu tư.\n- Vận hành, phát triển các website công ty, các dự án.\n- Hệ thống ERP cho tập đoàn (Quản trị nhân sự, tuyển dụng, tính lương, giao việc, dự án).\n- Các ứng dụng quản trị, giao dịch khác trong tập đoàn: Bất động sản, nội thất, trái phiếu...\n- Hệ thống quản lý chuỗi khách sạn SmartHotel tích hợp eKYC, Payment, hệ thống quản lý kho phòng: Channel Manager, CRM, Loyalty, Booking.\n- Vận hành, phát triển hệ thống tài chính độc nhất tại Việt Nam và hệ thống giao dịch chứng khoán hiện đại bậc nhất Việt Nam.\n- Và nhiều dự án khác.\n\nĐịa điểm làm việc\n- Hà Nội: 117 Trần Duy Hưng, Trung Hòa, Cầu Giấy, Cầu Giấy.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:50).\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:20).\n- 2 ca làm việc được lựa chọn.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3140, 1272, 2, 'Front-End Developer', 'Mô tả công việc\n- Phối hợp với team backend, thiết kế, QA để đảm bảo chất lượng và tiến độ sản phẩm. Khởi tạo project, thiết lập các base cơ bản;\n- Tham gia phát triển các sản phẩm và chịu trách nhiệm phát triển về Front End cho các ứng dụng nền Web và di động với HTML/CSS, JavaScript, sử dụng các framework/thư viện như Angular / VueJS / ReactJS, Bootstrap…\n- Phân tích, xem xét, phản hồi cho các yêu cầu và thiết kế sản phẩm. Viết các tài liệu chức năng được yêu cầu.\n- Cắt giao diện website từ file thiết kế photoshop (PSD) sang HTML5/CSS3 & Javascript theo chuẩn W3C.\n- Đề xuất và triển khai các best practices, coding standard cho team frontend. Hướng dẫn, hỗ trợ đồng đội trong quá trình phát triển sản phẩm\n- Tối ưu hiệu suất ứng dụng, bao gồm cải thiện tốc độ tải trang (lazy loading, code splitting), tối ưu re-render, tối ưu Web Vitals (LCP, FID, CLS).\n- Áp dụng các kỹ thuật bảo mật frontend để ngăn chặn các cuộc tấn công phổ biến như XSS, CSRF.\n- Tích hợp quy trình CI/CD, viết unit test (Jest, Testing Library) để đảm bảo chất lượng code.\n\nYêu cầu ứng viên\n- Tốt nghiệp ĐH, CD chuyên ngành Công nghệ thông tin; Kĩ thuật phần mềm, Hệ thống thông tin, ...hoặc các ngành tương đương\n- Có từ 2 năm kinh nghiệm trở lên\n- Có kinh nghiệm lập trình trong Frontend development với Angular hoặc VueJS (HTML5/ CSS3 /JavaScript), làm việc với Restful API, Websocket\n- Có kinh nghiệm thiết kế kiến trúc frontend cho các dự án lớn, xây dựng component library có thể tái sử dụng.\n- Có kinh nghiệm làm việc với các thư viện quản lý state nâng cao như Redux, Zustand (React) hoặc NgRx (Angular).\n- Kinh nghiệm tối ưu hiệu suất frontend, bao gồm code splitting, lazy loading, SSR (Server-side rendering) với Next.js hoặc Angular Universal\n- Ưu tiên các ứng viên có kinh nhiệm sử dụng các JavaScript Libraries/Frameworks khác nhau (Angular, VueJS, ReactJS), các Frontend Developer Tools (Webpack, npm, bower, grunt…).\n- Chủ động và có tinh thần trách nhiệm cao trong công việc;\n- Sử dụng thành thạo Git, hiểu biết về quy trình làm việc Git Flow.\n- Kinh nghiệm với công cụ quản lý task như Jira, công cụ design như Figma.\n\nQuyền lợi\n- Mức lương UPTO 25 triệu, thỏa thuận theo năng lực ứng viên\n- Thưởng dịp tết (tết dương và tết âm), dịp lễ (30/04-1/5; 2/9; Trung thu…) sinh nhật, hiếu hỷ…\n- Được tài trợ, tham gia các khóa đào tạo kỹ năng, chuyên môn hàng năm, thi lấy chứng chỉ để phục vụ cho công việc.\n- Review đánh giá tăng lương hàng năm\n- Nghỉ phép 12 ngày/năm, nghỉ ốm/nghỉ chế độ thai sản/hiếu hỷ… theo luật lao động\n- Làm việc tại công ty quy mô lớn, quy trình làm việc chuyên nghiệp, được khuyến khích sáng tạo và phát triển các ý tưởng mới\n- Môi trường trẻ, năng động, chuyên nghiệp, sếp trẻ tâm lý, đồng nghiệp thân thiện, văn hóa trao đổi thẳng thắn, cởi mở trên tinh thần hỗ trợ cùng phát triển\n- Dự án lớn áp dụng các công nghệ tiên tiến nhiều cơ hội thăng tiến và phát triển\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 4, Tòa The Garden Hill, 99 Trần Bìn, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3141, 1292, 2, 'Lập Trình Web', 'Mô tả công việc:\nTham gia phát triển và bảo trì hệ thống backend (Laravel/NodeJS/Python...)\nViết các công cụ nội bộ hỗ trợ quy trình làm việc: xử lý dữ liệu, tự động hóa thao tác, tạo báo cáo,...\nLàm việc với cơ sở dữ liệu (MySQL, MongoDB...) và thiết kế API\nCó kiến thức cơ bản về lập trình backend: PHP (Laravel), NodeJS hoặc Python\nBiết cách làm việc với cơ sở dữ liệu và logic xử lý dữ liệu\nCó đam mê phát triển hệ thống và thích xây dựng các tool hỗ trợ công việc\nCó kinh nghiệm thực tế là một lợi thế, chỉ cần có năng lực và tư duy lập trình tốt\nCó tinh thần chịu khó học hỏi, trách nhiệm trong công việc.\nCó thể chuyển đổi giữa frontend + backend là 1 lợi thế. Làm việc với git.\n\nYêu cầu ứng viên:\n• Tốt nghiệp Cao đẳng, Đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành liên quan.\n• Có làm qua PHP, Laravel\n• Kỹ năng lập trình tốt với: PHP, MySQL, Javascript, HTML, CSS.\n• Có kiến thức với MySQL và REST API.\n\nQuyền lợi:\n- Đồng phục, điện thoại, công cụ dụng cụ làm việc...\n- Được đào tạo kỹ năng mềm, kiến thức chuyên môn.\n- Lương tháng 13, 12 ngày phép...\n- Thưởng đóng góp sáng kiến, ý tưởng mới trong công việc.\n- Thưởng thâm niên 3 năm, 5 năm, 10 năm.\n- Chính sách phúc lợi cưới hỏi, ốm đau, thai sản.\n- Quà trong các dịp Tết, Trung thu, sinh nhật.\n- Cơm canh trưa, mì gói, trứng, chà bông...\n- BHXH, BHYT, BHTN, BH 24/24, Bảo hiểm cao cấp.\n- Tiêm ngừa Cúm.....\n- Khám sức khỏe định kỳ.\n- Phòng tập GYM miễn phí.\n- Du lịch hàng năm trong/ngoài nước.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 245B Trần Quang Khải, Phường Tân Định, Quận 1.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:45)\nThứ 7 (từ 08:00 đến 16:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3142, 1172, 2, 'Game Developer ( Cocos Creator )', 'Mô tả công việc\n- Designing and implementing code that is fit for purpose, scalable, human-readable, and in line with industry best practice.\n- Quality control of the entire product lifecycle by testing intuitiveness, user experience, and debugging where necessary.\n- Communicating with clients to understand their business goals and objectives, and interpreting that into the required changes to the platform where necessary.\n- Liaising with other developers, designers, and system administrators to identify new features and create relevant prototypes for new product ideas.\n- Deploying production code.\n- Communicating the effectiveness of emerging technologies to decision-makers.\n- Working on full production cycles from brainstorming and rapid prototyping to developing fully fledged systems and fine-tuning mechanics, as well as stress testing and bug fixing.\n- Developing innovative gameplay, AI, physics, UI, vehicles, weapons, and character controls.\n- Solving technical problems with simple, efficient, and creative code.\n- Helping ship game projects across multiple platforms on Web, iOS and Android.\n- Providing feedback and advice to junior team members.\n- Other tasks assigned by Line Manager.\n\nYêu cầu ứng viên\n- 4+ years of experience with game engines such as Cocos Creator, Cocos 2d-x, Unity, Pixi, Defold, Godot...\n- Experience working with native Android and iOS is a big plus.\n- History of working within rapid prototyping environments, such as game jams.\n- Passion for video games, films, and other creative mediums.\n- Knowing how to use git to collaborate with other teammates, understanding and applying Git Standards is a must.\n- Experience with remote config, dynamic assets loading.\n- Have knowledge of optimizing games.\n- Ability to build and maintain positive working relationships with teammates.\n- Excellent attention to detail and willingness to learn new software/processes.\n- Flexibility on working hours if required in the light of ad-hoc business demands.\n- Able to use initiative and remain self-motivated.\n- Able to work calmly and effectively under pressure.\n- Maintaining confidentiality/discretion where required.\n\nQuyền lợi\n- A competitive salary package that fits your skills, experiences, and contributions.\n- Holiday and New Year bonus.\n- Provision of necessary working equipment.\n- A professional, dynamic, and inclusive working environment.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 292 Ung Văn Khiêm Phường 25, Bình Thạnh\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3143, 1366, 2, 'Java Developer Lead', 'Mô tả công việc\n- Phát triển, triển khai và duy trì các ứng dụng web sử dụng Java và các framework liên quan.\n- Tham gia vào quá trình thiết kế, phát triển và kiểm thử các thành phần của ứng dụng.\n- Hợp tác với nhóm phát triển và các bên liên quan để thu thập yêu cầu và đưa ra giải pháp.\n- Sử dụng và quản lý mã nguồn thông qua Git.\n- Đảm bảo hiệu xuất và duy trì sự hoạt động của các hệ thống.\n- Tham gia đào tạo, hướng dẫn đội ngũ Fresher\n- Quản lý và đảm bảo hiệu quả công việc của team backend\n- Thực hiện các công việc theo yêu cầu của Manager\n\nYêu cầu ứng viên\n- Có ít nhất 4 năm kinh nghiệm làm việc với Java\n- Có kinh nghiệm xây dựng ứng dụng với Springboot\n- Có tư duy giải thuật tốt, hiểu biết về ORM, RESTful, OOP\n- Có kinh nghiệm làm việc với SQL (MySQL, PostgreSQL...): thiết kế, truy vấn, tối ưu....\n- Sẵn sàng học hỏi và đáp ứng nhanh các yêu cầu của dự án.\n- Có kinh nghiệm làm việc với Git, Maven, Redis.\n- Nắm chắc trong xử lý Caching, Queue\n- Có kinh nghiệm phát triển các dự án phần mềm về tài chính, bảo hiểm, ngân hàng là một lợi thế.\n- Có khả năng quản lý công việc, quản lý thời gian tốt, Tiếng Anh cơ bản trở lên.\n- Kinh nghiệm làm việc nhóm, quản lý đội nhóm\n- Ưu tiên sử dụng Laptop cá nhân (có trợ cấp)\n\nTốt nếu có:\n- Có kinh nghiệm về bảo mật dữ liệu (OAuth2, OIDC, OWASP, SAST, DAST,...), kinh nghiệm về Modern protocol (MQTT, WebSocket, RPC,...).\n- Có kinh nghiệm về xử lý tối ưu xử lý dữ liệu, dữ liệu lớn.\n- Có kinh nghiệm với Logging (ELK) và Monitoring (Grafana, Prometheus).\n- Có kinh nghiệm trong việc nâng cao hiệu suất ứng dụng (Performance test - JMeter, Profilers).\n- Có kinh nghiệm làm việc với các dịch vụ Cloud (AWS, Azure)\n- Có kinh nghiệm với các công cụ CI/CD (GitlabCI, ArgoCD...) và triển khai (Docker, K8s).\n- Có hiểu biết về các API Gateway (KONG API...).\n\nQuyền lợi\n- Mức lương cạnh tranh thỏa thuận theo năng lực và kinh nghiệm, upto 35M (Middle - Senior)\n- Review hiệu quả công việc: 1-2 lần/1 năm.\n- Môi trường trẻ, năng động, có nhiều cơ hội phát triển bản thân.\n- Được đào tạo về kỹ năng công nghệ, các kỹ năng mềm, các kỹ năng quản lý dự án,...\n- Nghỉ Thứ 7, Chủ nhật, 12 ngày phép/năm\n- Khám sức khỏe định kỳ 1 năm 1 lần\n- Các hoạt động thể thao, văn hóa đa dạng: CLB đá bóng, cầu lông,...\n- Hưởng đầy đủ các chế độ theo quy định pháp luật (BHXH, BHYT, BHTN) và công ty (nghỉ mát, team building, sinh nhật,...)\n- Địa chỉ công ty: Gần Đại học Công nghiệp Hà Nội\n\nĐịa điểm làm việc\n- Hà Nội: Số 92 Liền kề 22, KĐT Vân Canh, Hoài Đức\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:45)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3144, 1282, 2, 'Nhân Viên Lập Trình Mobile', 'Mô tả công việc:\n- Xây dựng và lập kế hoạch phát triển các ứng dụng trên mobile (Android,IOS) theo định hướng của Công ty;\n- Phát triển ứng dụng mobile trên nền tảng (Android, IOS);\n- Cập nhật phản hồi từ người dùng, xử lý lỗi phát sinh;\n- Bảo trì và hỗ trợ các vấn đề liên quan đến chuyên môn;\n- Nghiên cứu tối ưu hóa sản phẩm, dịch vụ đã phát triển, cải thiện trải nghiệm của người dùng;\n- Thực hiện các công việc khác theo chỉ đạo và phân công của Trưởng bộ phận và BLĐ.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành khác am hiểu lập trình;\n- Có kỹ năng lập trình Mobile bằng Flutter; React Native hoặc tương đương.\n- Có khả năng phân tích, sáng tạo, chịu áp lực công việc, có tinh thần học hỏi, tận tâm trong công việc;\n- Đã có kinh nghiệm chủ trì hoặc tham gia phát triển ứng dụng Mobile tối thiểu 1 năm.\n- Làm việc ổn định tại Hà Nội.\n\nQuyền lợi:\n- Mức lương thỏa thuận theo năng lực và kinh nghiệm;\n- Được hưởng các chế độ BHYT, BHXH theo quy định của Nhà nước; Các chính sách phúc lợi của Công ty;\n- Làm việc trong môi trường năng động, chuyên nghiệp, bình đẳng, phát huy tính sáng tạo của nhân viên;\n- Được trang bị đầy đủ trang thiết bị làm việc;\n- Được trau dồi kỹ năng về chuyên môn và nghiệp vụ;\n- Được tham gia, đóng góp vào các dự án phát triển của Công ty;\n- Thưởng theo thành tích làm việc.\n\nĐịa điểm làm việc:\n- Hà Nội: 101 Láng Hạ, Đống Đa.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3145, 1264, 2, 'Kỹ Sư Lập Trình PLC - Thiết Kế Điện', '- Lập kế hoạch dự án, lên giải pháp, danh mục vật tư các thiết bị điện, lập bản vẽ đấu nối điện layout thiết bị, sử dụng phần mềm Eplan và Cad.\n- Lập trình PLC, HMI, Lập trình Robot 2-4-6 trục (Mitsubishi, Keyence, Omron, ABB, UR robot ...) và các thiết bị tự động hóa để điều khiển máy móc trong công nghiệp. \n- Lập trình điều khiển step motor, servo motor, Inverter và các thiết bị chuyển đổi Analog-Digital, các loại cảm biến và khí nén thủy lực...\n- Lập trình truyền thông công nghiệp RS485, RS232, Ethernet TCP/IP, Modbus,...\n\nYêu cầu ứng viên:\n- Học vấn : Tốt nghiệp Đại học trở lên các trường kỹ thuật ( Bách khoa, công nghiệp, học viện kỹ thuật quân sự, Giao thông vận tải và các trường kỹ thuật khác)\n- Biết lập trình các dòng PLC Mitsubishi, Keyence. Điều khiển các thiết bị công nghiệp.\n- Biết sử dụng Biến tần, Servo và các thiết bị điều khiển động cơ khác.\n- Hiểu biết về các loại truyền thông công nghiệp..\n- Có khả năng làm việc độc lập và làm việc theo nhóm tốt\n- Chịu được áp lực công việc, ham học hỏi, đam mê kỹ thuật.\n- Chấp nhận ra Hà Nội đào tạo từ 9 - 12 tháng.\n\nQuyền lợi:\n- Thu nhập từ 9.000.000đ - 15.000.000đ++/tháng. Performance review 2 lần/năm và đột xuất;\n- Thưởng sinh nhật, lễ, tết, quý, tháng lương 13,...;\n- Công tác: Công tác phí, Phụ cấp ăn, xe Công ty đưa đón,..;\n- Chế độ phép linh hoạt 1 ngày/tháng áp dụng từ khi thử việc.\n\nChế độ sức khỏe cho nhân viên:\n- Chế độ BHXH theo cấp bậc và thâm niên công tác;\n- Tài trợ 100% thẻ BHSK Bảo Việt cho NLĐ và con đầu tiên, 70% cho con thứ 2,... khám tại tất cả các BV Công và Quốc tế;\n- Khám sức khỏe định kỳ 01 lần/năm tại Bệnh viện dịch vụ 5 sao.\n\nTiện ích văn phòng:\n- Không gian làm việc đầy đủ tiện nghi (văn phòng làm việc xanh, tủ lạnh, lò vi sóng..;  siêu thị, nhà hàng, bể bơi, gym, bi-a, hair salon, trường mầm non ngay bên cạnh)\n- Cơm văn phòng tự chọn.\n\nĐào tạo:\n- Đào tạo nội bộ, đào tạo ngoài kiến thức chuyên môn, kỹ năng... phục vụ công việc.\n\nCác hoạt động sôi nổi:\n- Du xuân, du lịch hè, family day 3 lần/năm;\n- Cấp quỹ Entertainment 100k/người/tháng theo team/phòng ban;\n- Tổ chức sinh nhật cho CBNV định kỳ 01 lần/tháng;\n- Câu lạc bộ, giải bóng đá, bóng bàn, cầu lông, bi-a, esport,...\n\nThời gian làm việc: Từ T2 - hết thứ 6, thứ 7 làm việc/ nghỉ cách tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3146, 1425, 2, 'Back End Developer', 'Mô tả công việc:\n- Transforming User Stories: You will take application user stories and translate them into functional applications. This process involves understanding user requirements and ensuring that the final product aligns with their expectations.\n- Designing and Building Components: You will design, build, and maintain reusable and testable components that are crucial for the application’s architecture. Your focus on reusability will help streamline development processes and enhance overall efficiency.\n- API Development: You will be responsible for building APIs that adhere to microservices principles. This includes ensuring that the APIs are scalable, maintainable, and designed for optimal performance.\n- Performance and Quality Assurance: Ensuring the performance, quality, and responsiveness of applications will be a key part of your role. You will employ best practices and methodologies to monitor and improve application performance.\n- Identifying and Fixing Issues: You will actively identify bottlenecks and bugs within the application. Your problem-solving skills will be essential in implementing effective fixes and enhancements to improve the user experience.\n- Maintaining Code Quality: You will help uphold the highest standards of code quality, organization, and automation. This includes participating in code reviews, advocating for best practices, and contributing to a culture of continuous improvement.\n\nYêu cầu ứng viên:\n- Languages: Proficiency in Java and SQL is essential for developing robust back-end applications and managing database interactions effectively.\n- Frameworks: Experience with frameworks such as SpringMVC and SpringBoot is crucial for building scalable web applications. Familiarity with Hibernate for ORM (Object-Relational Mapping) will enhance your ability to manage database operations. Knowledge of JUnit and Mockito is important for testing and ensuring code quality.\n- API Specification: Understanding RESTful API design and documentation using Swagger is necessary for creating and maintaining APIs that are both efficient and user-friendly.\n- Security: A strong grasp of Java API security principles, including authentication and authorization, along with common security standards, is vital to protect applications from vulnerabilities.\n- Databases: Proficiency in working with various database systems, including SQL Server, MariaDB, MySQL, and PostgreSQL, will enable you to manage data effectively and ensure seamless integration with applications.\n- Tools: Familiarity with build tools like Gradle and Maven, along with version control systems such as GIT, is essential for managing project dependencies and collaborating with team members. Experience with project management tools like JIRA and Confluence will facilitate effective task tracking and documentation.\n- Cloud Knowledge: Basic knowledge of AWS Cloud and deployment processes is important for leveraging cloud services to enhance application scalability and performance.\n\nQuyền lợi:\n- Base Salary: The monthly base salary ranges from 55 million to 80 million VND, depending on experience and qualifications.\n- Hybrid Working Environment: Enjoy the flexibility of a hybrid working model, allowing you to work both remotely and in the office.\n- Full Salary Package Insurance: Comprehensive insurance coverage that includes full salary package insurance, ensuring your financial security.\n- Performance Bonus: Eligibility for performance bonuses based on individual and team contributions, rewarding your hard work and dedication.\n- Project Bonus: Additional bonuses tied to project success, providing incentives for achieving project milestones.\n- 13th Month Salary: Receive a 13th-month salary as a standard practice, enhancing your annual earnings.\n- Insurance for Dependents: Coverage options are available for dependents, ensuring that your family is also protected.\n- Other Benefits: Additional benefits in accordance with current laws, which may include health and wellness programs, professional development opportunities, and more.\n\nĐịa điểm làm việc:\n- Hà Nội\n\nThời gian làm việc:\n- Từ thứ 2 đến thứ 6, làm việc onsite 2-3 ngày/tuần.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3147, 399, 2, 'Giám Đốc Khối Công Nghệ Thông Tin', '1. Lập kế hoạch và chiến lược công nghệ:\n- Xây dựng và triển khai chiến lược công nghệ thông tin phù hợp với mục tiêu phát triển của công ty.\n- Đánh giá và đề xuất các công nghệ mới nhằm nâng cao hiệu quả hoạt động kinh doanh.\n- Tìm hiểu các công nghệ mới nhất và lên chiến lược áp dụng cho hệ thống hiện tại.\n\n2. Đảm bảo an ninh thông tin:\n- Thiết lập và duy trì các chính sách bảo mật thông tin, đảm bảo an toàn cho dữ liệu và hệ thống của công ty.\n- Phối hợp với các bộ phận liên quan để quản lý rủi ro và xử lý các sự cố an ninh thông tin kịp thời.\n\n3. Quản lý phát triển phần mềm:\n- Giữ vai trò đầu mối tổ chức, điều phối và tham gia vào việc thiết kế, phát triển và triển khai các ứng dụng phục vụ cho giao dịch chứng khoán và quản lý tài sản.\n- Đảm bảo các sản phẩm phần mềm được phát triển đúng tiến độ, chất lượng và đáp ứng yêu cầu của người dùng.\n\n4. Quản lý hạ tầng công nghệ:\n- Giám sát hạ tầng CNTT, hệ thống giao dịch chứng khoán, đảm bảo hệ thống hoạt động ổn định, bảo mật và có khả năng mở rộng.\n- Kiểm tra, rà soát và tối ưu data-center để đảm bảo môi trường Core chứng khoán trên Production hoạt động liên tục, hạn chế downtime.\n- Giám sát và quản lý các dự án công nghệ thông tin, bao gồm việc triển khai các giải pháp phần mềm và hạ tầng.\n- Giám sát việc quản lý mạng nội bộ, hệ thống máy chủ, tài nguyên CNTT và bảo mật thông tin.\n\n5. Đào tạo và phát triển nhân sự:\n- Xây dựng và phát triển đội ngũ nhân viên công nghệ thông tin, tổ chức các khóa đào tạo nâng cao kỹ năng cho nhân viên.\n- Khuyến khích văn hóa đổi mới và sáng tạo trong đội ngũ.\n\nCông nghệ ABS đang sử dụng\n- Kiến trúc: Microservices\n- Ngôn ngữ lập trình: Java, Spring Boot, NodeJS, React, Flutter\n- Message broker: Kafka, RabbitMQ, ActiveMQ\n- Cơ sở dữ liệu: Oracle, Redis, Postgres, MongoDB\n- Công nghệ xử lý realtime: Apache Flink, Kafka\n- Công nghệ triển khai vận hành: Docker, VMWare, Jenkins, Ansible, ElasticSearch, Elastic APM, WSO2 API Manager.\n\nYêu cầu ứng viên\n- Kinh nghiệm: Trên 10 năm kinh nghiệm, trong đó tối thiểu 03 năm kinh nghiệm ở vị trí tương đương.\n- Trách nhiệm, trung thực, nhiệt huyết, tư duy thiết kế hệ thống xuất sắc.\n\nQuyền lợi\n- Thu nhập hấp dẫn.\n- Lương cạnh tranh, thưởng KPI hấp dẫn. Review lương hàng năm.\n- Lương tháng 13 và thưởng các ngày Lễ tết, phụ cấp ăn trưa, gửi xe miễn phí.\n- Chương trình mua cổ phiếu Công ty với giá ưu đãi dành riêng cho CBNV trong Công ty.\n- BH sức khỏe cá nhân chuyên biệt và Khám sức khỏe tại các cơ sở uy tín.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, công ty đang trên đà tăng trưởng mạnh mẽ.\n- Thời gian làm việc: thứ 2 đến thứ 6.\n\nĐịa điểm làm việc\n- Hà Nội: 36 Hoàng Cầu, Đống Đa.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3148, 1483, 2, 'Nodejs Developer', 'Mô tả công việc\n- Code and test backend services in NodeJS.\n- Design, implement, and/or use RESTful web services Building scalable microservices-based system.\n- Understand the needs of the customer or business and utilize this knowledge to develop applications that are consistent with the specific needs and requests of the customer.\n- Participate in agile software development, prototyping, and code reviews with a small team of developers.\n\nYêu cầu ứng viên\n- From 3 years of NodeJS experience Experienced in Agile/Scrum development environment\n- Ability to write structured, well-documented and maintainable code\n- Strong background in NodeJS (ES6) Practically experienced with REST APIs design and implementation\n- Expert knowledge of developing projects based on NodeJS and Express framework\n- Practically experienced with MongoDB, Redis and PostgreSQL Solid professional experience in using NodeJS unit testing frameworks (Jest, Mocha, etc.)\n- Good problem-solving and analytical skills English communication\n\n[Nice to have]\n- Experience with AWS services (e.g., S3, ECS, Lambda).\n- Experience with message queuing systems (e.g.,Kafka, SQS)\n- Knowledge of containerization and orchestration (e.g., Docker, ECS).\n- Understanding of microservices architecture.\n- Familiarity with authentication and authorization mechanisms (e.g., OAuth, JWT).\n\nQuyền lợi\n- Very attractive salary with a 13th-month salary\n- Performance bonus based on effort and output\n- Monitor, laptop... will be provided\n- A professional working environment with Agile–Scrum\n- PVI health care program\n- Sports clubs (football, badminton...)\n- Team-building activities, company trip every year\n- Enjoy Relax and beautiful Pantry in the company\n- Periodic health examination\n- Annual sponsored retreat trip\n- PTO / Sick leave\n- Weekly happy dinner, party celebration (Christmas, Birthday,...)\n\nĐịa điểm làm việc\n- Đà Nẵng: 36 Tran Quoc Toan, Hải Châu\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3149, 1397, 2, 'Lập Trình Viên .NET', 'Mô tả công việc\n- Tiếp nhận thông tin dự án \n- Khảo sát, phân tích, thiết kế hệ thống dự án \n- Lập trình ứng dụng cho dự án \n- Triển khai ứng dụng sau khi xây dựng xong \n- Tham gia nghiên cứu và trình bày các công nghệ mới liên quan đến các dự án của công ty. \n- Hỗ trợ, đào tạo các thành viên trong nhóm lập trình\n\nYêu cầu ứng viên\n- Thành thạo .NET, ngôn ngữ lập trình C#. \n- Sử dụng thành thạo SQL Server. \n- Có khả năng phân tích thiết kế hệ thống, thiết kế database. \n- Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin. \n- Ưu tiên các ứng viên đã có kinh nghiệm tham gia lập trình, triển khai các dự án về phần mềm quản trị doanh nghiệp.  \n- Có tính cách cẩn thận, tỉ mỉ, tư duy logic nhanh, có kỹ năng làm việc nhóm tốt, có trách nhiệm trong công việc. \n- Có khả năng làm việc độc lập.\n\nQuyền lợi\n- Môi trường làm việc thoải mái, năng động, thời gian làm việc (8h-17h, trưa nghỉ 1h)\n- Phép năm theo quy định của pháp luật. Đầy đủ các chế độ về BHXH, BHYT, BHTN. Chế độ khám sức khỏe hàng năm.\n- Review lương hàng năm theo năng lực làm việc\n- Du lịch hàng năm, tổng kết cuối năm, liên hoan kỷ niệm sinh nhật công ty...\n- Thưởng lễ tết (thưởng 2/9, tết dương lịch, tết lao động, tết âm lịch)\n\nĐịa điểm làm việc\n- Thái Nguyên: 434 Bắc Kạn, phường Hoàng Văn Thụ, TP Thái Nguyên\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3150, 1264, 2, 'Kỹ Sư Lập Trình Machine Vision', '- Lập trình xử lý ảnh, AI deep learning cho các ứng dụng kiểm tra lỗi sản phẩm, đọc mã vạch QR, Datamatrix, Barcode ... , nhận diện kí tự và tích hợp với robot để định vị trí sản phẩm để robot gắp đặt.\n- Setup Camera Vision , lựa chọn camera, lens, đèn phù hợp để thu được hình ảnh tốt nhất và lên cấu hình vision cho từng bài toán.\n- Lập trình thiết kế phần mềm máy tính, visual studio C++, C#, SQLServer,...\n- Lập trình quản lý hệ thống nhà máy, server truyền thông công nghiệp, lưu trữ truy xuất dữ liệu.\n\nYêu cầu ứng viên:\n- Kinh nghiệm: Ứng viên Fresher/ mới ra trường/ đang chờ bằng/ dưới 1 năm kinh nghiệm (Có nhận thực tập sinh)\n- Đối với ứng viên Fresher khu vực Hồ Chí Minh yêu cầu đào tạo, làm việc tại trụ sở chính Hà Nội tối thiểu 06 tháng.\n- Học vấn: Tốt nghiệp Đại học trở lên các trường kỹ thuật (Bách khoa, công nghiệp, học viện kỹ thuật quân sự, Giao thông vận tải và các trường kỹ thuật khác).\n- Ưu tiên biết lập trình Python, C++ trên nền tảng ROS. Các ứng dụng liên quan tới Web-Base, Database, IOT.\n- Có khả năng làm việc độc lập và làm việc theo nhóm tốt.\n- Chịu được áp lực công việc, ham học hỏi, đam mê kỹ thuật.\n\nQuyền lợi:\nChế độ đãi ngộ:\n- Thu nhập từ 9.000.000đ - 15.000.000đ++/tháng. Performance review 2 lần/năm và đột xuất;\n- Thưởng sinh nhật, lễ, tết, quý, tháng lương 13,...;\n- Công tác: Công tác phí, Phụ cấp ăn, xe Công ty đưa đón,..;\n- Chế độ phép linh hoạt 1 ngày/tháng áp dụng từ khi thử việc.\n\nChế độ sức khỏe cho nhân viên:\n- Chế độ BHXH theo cấp bậc và thâm niên công tác;\n- Tài trợ 100% thẻ BHSK Bảo Việt cho NLĐ và con đầu tiên, 70% cho con thứ 2,... khám tại tất cả các BV Công và Quốc tế;\n- Khám sức khỏe định kỳ 01 lần/năm tại Bệnh viện dịch vụ 5 sao.\n\nTiện ích văn phòng:\n- Không gian làm việc đầy đủ tiện nghi (văn phòng làm việc xanh, tủ lạnh, lò vi sóng..; siêu thị, nhà hàng, bể bơi, gym, bi-a, hair salon, trường mầm non ngay bên cạnh).\n- Cơm văn phòng tự chọn.\n\nĐào tạo:\n- Đào tạo nội bộ, đào tạo ngoài kiến thức chuyên môn, kỹ năng... phục vụ công việc.\n\nCác hoạt động sôi nổi:\n- Du xuân, du lịch hè, family day 3 lần/năm;\n- Cấp quỹ Entertainment 100k/người/tháng theo team/phòng ban;\n- Tổ chức sinh nhật cho CBNV định kỳ 01 lần/tháng;\n- Câu lạc bộ, giải bóng đá, bóng bàn, cầu lông, bi-a, esport,...\nThời gian làm việc: Từ T2 - hết thứ 6, thứ 7 làm việc/ nghỉ cách tuần.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 2 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3151, 1311, 2, 'Mobile App Developer', '- Phân tích yêu cầu và thiết kế kiến trúc ứng dụng đa nền tảng.\n- Phát triển mã nguồn bằng ngôn ngữ Dart (sử dụng Flutter), JavaScript (sử dụng React Native).\n- Tối ưu hóa hiệu suất và đảm bảo ứng dụng tương thích trên IOS/Android.\n- Tham gia họp dự án, báo cáo tiến độ và đề xuất giải pháp kỹ thuật khi cần thiết.\n- Cập nhật các xu hướng và công nghệ mới trong lĩnh vực phát triển ứng dụng di động.\n- Áp dụng các công nghệ tiên tiến để cải thiện chất lượng và hiệu suất của ứng dụng.\n\n- Tốt nghiệp Đại học ngành Công nghệ thông tin chuyên ngành phát triển ứng dụng di động.\n- Có 1-3 năm kinh nghiệm phát triển ứng dụng IOS/Android bằng Flutter hoặc React Native (ưu tiên ứng viên có kinh nghiệm về project tương tự).\n- Hiểu biết về thiết kế UI/UX đa nền tảng.\n- Kinh nghiệm làm việc với API và dịch vụ backend.\n- Biết tiếng Anh, sử dụng tiếng Anh trong công việc (Toiec 650 trở lên, Ielts 5.0 trở lên).\n- Có kỹ năng quản lý thời gian, sắp xếp công việc, làm việc độc lập và hợp tác tốt với đội nhóm.\n- Tận tâm, cầu thị có trách nhiệm, chủ động và tích cực trong công việc.\n- Thái độ tốt, lắng nghe, phản hồi tích cực, đổi mới và phát triển.\n\n- Thu nhập: 15.000.000 - 18.000.000 vnđ/tháng (lương cơ bản 10 - 15tr/tháng, được deal theo năng lực và kinh nghiệm làm việc).\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp\n- Văn hóa tích cực, tinh thần đồng đội, lắng nghe, chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện qua các khoá học do công ty hỗ trợ.\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn, cơ hội phát triển trong thị trường nước ngoài, được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Các phúc lợi khác (du lịch, sinh nhật, thưởng lễ tết, BHXH, phép năm,…) theo quy định của pháp luật.\n\n- Đà Nẵng: 14 Bình Minh 3, Hải Châu\n\n- Thời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nLịch làm từ thứ 2 đến thứ 7 (làm xen kẽ 2 thứ 7/tháng)\n- Sáng: 8h00-11h30\n- Chiều: 13h30-17h30\n\n- Cách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3152, 1112, 2, 'Lập Trình Viên Wordpress', 'Mô tả công việc:\n- Chuyển đổi thiết kế sang website WordPress hoàn chỉnh (HTML, PHP, ACF, Elementor/Divi/Astra/Gurtenberg,…).\n- Tích hợp các plugin và API của bên thứ ba\n- Sửa lỗi, nâng cấp và bảo trì website định kỳ.\n- Tối ưu hóa hiệu suất và bảo mật WordPress.\n- Các công việc khác liên quan đến website WordPress.\n\nYêu cầu ứng viên:\n- Có kinh nghiệm HTML, CSS, JS\n- Tối thiểu 1 năm kinh nghiệm làm việc thực tế với Wordpress (ACF, Divi, Elementor, ...)\n- Đọc hiểu tài liệu tiếng anh và có khả năng làm việc trực tiếp với người nước ngoài \n- Biết Angular và React JS là lợi thế lớn\n- Biết xây dựng mobile apps là lợi thế\n\nQuyền lợi:\n- Chế độ đãi ngộ tốt\n- Được cấp máy tính bàn để làm việc\n- Thưởng lễ, Tết theo kết quả hoạt động công ty\n- Chế độ BHXH theo quy định\n\nĐịa điểm làm việc:\n- Nghệ An: Trường Thi, TP Vinh\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nghệ An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3153, 1151, 2, 'Lập Trình Viên (Tiếng Nhật N3 Trở Lên)', 'Mô tả công việc\n- Triển khai tính năng mới đúng theo lịch trình\n- Điều tra và sửa lỗi\n- Điều tra các câu hỏi nhận được từ user\n- Upload các chính sách định kỳ trong bảo trì\n\nYêu cầu ứng viên\n- Nộp CV tiếng Nhật\n- Giao tiếp được tiếng Nhật (từ N3 trở lên)\n- Có thể lập trình bằng ngôn ngữ C hoặc C++\n- Biết thêm về Objective-C, Java, MySQL, HTML5, JavaScript, Unity là một điểm cộng\n- Có thể tự suy nghĩ và hành động độc lập\n- Có thể nỗ lực trong công việc với tinh thần trách nhiệm cao mà không từ bỏ giữa chừng\n- Người không bị bó buộc bởi những khái niệm cố định mà có thể linh hoạt đối ứng với bất kỳ thay đổi nào\n- Người có hứng thú đến nhiều lĩnh vực khác nhau và có thể chủ động tiếp thu kiến thức và thông tin một cách tích cực\n\nQuyền lợi\n1. Hàng năm sẽ chi trả lương thưởng vào trước Tết. Được quyết định dựa theo đánh giá và thành quả của cá nhân so với thành tích kinh doanh của công ty. Lấy cả mức độ đạt được mục tiêu và mức độ cống hiến của cá nhân làm đối tượng đánh giá và cung cấp môi trường mà mọi người có thể làm việc với động lực cao hơn.\n2. Ngày nghỉ căn cứ theo luật Lao động và kỳ nghỉ hè theo luật Công ty. Ở công ty chúng tôi, không chỉ có ngày nghỉ dựa theo luật Lao động như ma chay hiếu hỉ, nghỉ thai sản, nghỉ nuôi con nhỏ ... mà còn có kỳ nghỉ hè, nhằm thúc đẩy cách làm việc chú trọng tới sự cân bằng giữa công việc và cuộc sống để nhân viên có thể sảng khoái cả về thể chất lẫn tinh thần.\n3. Tham gia bảo hiểm xã hội, bảo hiểm y tế và khám sức khỏe mỗi năm một lần. Thực hiện khám sức khỏe mỗi năm một lần để hỗ trợ sức khỏe cho người lao động.\n4. Sự kiện: Tổ chức Tiệc tất niên vào cuối năm. Sẽ tổ chức Tiệc tất niên mỗi năm một lần để làm sâu sắc thêm sự gắn bó giữa các nhân viên.\n5. Chi trả trợ cấp chứng chỉ năng lực tiếng Nhật tùy theo bằng cấp JLPT・BJT\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 48 Huỳnh Mẫn Đạt, Phường 19, Bình Thạnh\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3154, 1272, 2, 'Java Developer', 'Mô tả công việc:\n- Tham gia phân tích yêu cầu, thiết kế và phát triển hệ thống backend sử dụng Java (Spring Boot, Spring MVC, Hibernate).\n- Phát triển các API RESTful phục vụ frontend hoặc tích hợp với hệ thống khác theo kiến trúc microservices.\n- Thiết kế và triển khai các service sử dụng Redis, Kafka, RabitMQ … để caching hoặc xử lý bất đồng bộ (pub/sub, queue).\n- Làm việc với cơ sở dữ liệu quan hệ như MariaDB, PostgreSQL, Oracle … bao gồm thiết kế schema, viết stored procedures, tối ưu truy vấn.\n- Tích hợp và triển khai hệ thống trên môi trường Linux, Windows server, sử dụng Docker, Git, CI/CD pipelines.\n- Tham gia xây dựng, vận hành các hệ thống sử dụng Spring Boot, Spring MVC, Spring  Cloud, Config Server, Service Discovery (Eureka/Consul), Gateway, Hystrix, v.v.\n- Phối hợp với BA, frontend, tester trong quá trình phát triển, kiểm thử và fix bugs.\n- Viết tài liệu kỹ thuật: mô tả API, tài liệu cấu hình triển khai, hướng dẫn sử dụng.\n- Hỗ trợ triển khai, bảo trì, vận hành các hệ thống đã phát triển.\n- Tham gia review code, đề xuất cải tiến hiệu năng, kiến trúc hệ thống.\n- Các công việc khác theo phân công của quản lý.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm, Hệ thống thông tin hoặc các ngành liên quan.\n- Có từ 2 năm kinh nghiệm trở lên.\n- Có kiến thức nền tảng tốt về Java Core, Java Web, lập trình hướng đối tượng (OOP).\n- Có kinh nghiệm phát triển, triển khai hệ thống theo kiến trúc microservices.\n- Thành thạo SQL, hiểu biết cơ bản về các hệ quản trị cơ sở dữ liệu như Oracle, MySQL, PostgreSQL.\n- Hiểu và từng làm việc với một số message broker như Kafka, RabbitMQ là lợi thế.\n- Có kiến thức về các công nghệ frontend căn bản như HTML/XHTML, CSS, JavaScript, AJAX, XML, Web Services.\n- Hiểu biết và từng làm việc trên môi trường Linux.\n- Thành thạo sử dụng hệ thống quản lý mã nguồn như Git, SVN.\n- Ưu tiên có hiểu biết hoặc kinh nghiệm với Spring Security, OAuth2, JWT.\n- Có kinh nghiệm xây dựng RESTful API, viết unit test bằng JUnit, Mockito… là lợi thế.\n\nQuyền lợi:\n- Mức lương UPTO 30 triệu, thỏa thuận theo năng lực ứng viên.\n- Thưởng dịp tết (tết dương và tết âm), dịp lễ (30/04-1/5; 2/9; Trung thu…) sinh nhật, hiếu hỷ…\n- Được tài trợ, tham gia các khóa đào tạo kỹ năng, chuyên môn hàng năm, thi lấy chứng chỉ để phục vụ cho công việc.\n- Review đánh giá tăng lương hàng năm.\n- Nghỉ phép 12 ngày/năm, nghỉ ốm/nghỉ chế độ thai sản/hiếu hỷ… theo luật lao động.\n- Làm việc tại công ty quy mô lớn, quy trình làm việc chuyên nghiệp, được khuyến khích sáng tạo và phát triển các ý tưởng mới.\n- Môi trường trẻ, năng động, chuyên nghiệp, sếp trẻ tâm lý, đồng nghiệp thân thiện, văn hóa trao đổi thẳng thắn, cởi mở trên tinh thần hỗ trợ cùng phát triển.\n- Dự án lớn áp dụng các công nghệ tiên tiến nhiều cơ hội thăng tiến và phát triển.\n- Cung cấp đầy đủ trang thiết bị làm việc.\n- Được hưởng đầy đủ các chế độ BHYT, BHXH, BHTN.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 4, Tòa The Garden Hill, 99 Trần Bìn, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3155, 1169, 2, 'Nhà Phát Triển Phần Mềm', '1. Design and Development\n● Build, test, and maintain highly scalable Java applications.\n● Collaborate with cross-functional teams to translate business requirements into technical solutions.\n\n2. System Architecture\n● Contribute to the design and architecture of software solutions, ensuring best practices and optimal\nperformance.\n● Conduct code reviews and provide guidance on coding standards and design patterns.\n\n3. Quality Assurance & Risk Management\n● Troubleshoot, debug, and optimize applications for maximum speed and scalability.\n● Resolve technical challenges and identify opportunities for continuous improvement.\n\n4. Collaboration and Mentoring\n● Work closely with product managers, designers, and other engineers to deliver high-quality features.\n● Mentor and guide junior engineers, fostering a culture of knowledge sharing and continuous learning.\n\n5. Continuous Improvement\n● Stay updated on emerging technologies and apply them to improve existing systems.\n● Lead and contribute to technical discussions, ensuring the team follows Agile practices.\n\n++ Must have:\n● 2 years of hands-on experience in Java development, with a strong grasp of Java 8 features (e.g.,streams, lambdas).\n● Proficiency in frameworks like Spring Boot, Hibernate, or JPA.\n● Experience with RESTful APIs and microservices architecture.\n● Familiarity with relational databases (e.g., MySQL, PostgreSQL and NoSQL databases (e.g., MongoDB\n● Proficient in building tools like Maven or Gradle, and version control systems like Git.\n● Strong problem-solving and analytical abilities.\n● Knowledge of CI/CD pipelines and DevOps practices.\n● Experience with messaging systems such as Kafka or RabbitMQ.\n● Good at English.\n\n++ Nice to have:\n● Prior experience with data engineering tasks, such as building ETL pipelines, handling large datasets, or\ndesigning data storage solutions.\n● Hands-on experience with cloud platforms like AWS, Azure, or GCP.\n● Familiarity with containerization technologies like Docker and orchestration tools like Kubernetes.\n● Understanding of front-end technologies (e.g., Angular, React) is a plus.\n\n• Competitive salary, performance bonus.\n• Social insurance, health insurance, unemployment insurance according to the law.\n• Clear career advancement and development opportunities.\n• Dynamic, professional and friendly working environment.\n• Professional and technical skills training.\n• Participate in team building activities, annual vacations.\n• Holiday bonuses according to company regulations.\n\n- Hồ Chí Minh: Số 74 đường 101, Phường Thạnh Mỹ Lợi, Thủ Đức\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3156, 1166, 2, 'Fresher Software Engineer (Java, .NET, NodeJS)', 'Tham gia chương trình đào tạo kỹ sư lập trình và tham gia thực tập tại các dự án quan trọng của CMC Global, cụ thể: \nĐào tạo về chuyên môn lập trình và quy trình phát triển phần mềm, quản lý dự án theo chuẩn quốc tế CMMi, có điều kiện phát triển kỹ năng mềm và ngoại ngữ; \nĐược hướng dẫn và hỗ trợ bởi các mentor là Technical Lead hoặc chuyên gia công nghệ của CMC Global; \nCơ hội tham gia vào các dự án lớn hoặc onsite tại các Công ty của CMC Global tại nước ngoài. \nĐịa điểm đào tạo & thực tập: Hà Nội \n\nYêu cầu ứng viên: \nLà sinh viên đã/sắp tốt nghiệp chuyên ngành Công nghệ thông tin, Toán tin, Khoa học máy tính, Kỹ thuật phần mềm,... \nNắm vững kiến thức cơ bản trong các ngôn ngữ/nền tảng sau:\n(BE) Java/NodeJS/Python/Golang \n(FE) HTML, CSS, JS \nƯu tiên ứng viên có khả năng giao tiếp tiếng Anh tốt (tương đương IELTS 6.0 trở lên,  TOEIC 650 trở lên); và GPA: 7/10 hoặc 3/4 \nCó thể tham gia đào tạo/làm việc Full-time từ thứ 2 - thứ 6 \nHam học hỏi, nhiệt huyết\n\nQuyền lợi: \nCó hỗ trợ thu nhập trong thời gian đào tạo. \nSau khi ký HĐLĐ chính thức, mức lương 7 - 11 triệu/ tháng tuỳ thuộc vào kết quả đào tạo và khả năng đáp ứng yêu cầu công việc.\nMôi trường làm việc năng động, trẻ trung và đầy sáng tạo \nĐịa điểm làm việc: \nHà Nội: Tòa nhà CMC Tower, Phố Duy Tân, Cầu Giấy.\nCách thức ứng tuyển: \nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3157, 1147, 2, 'Middle Java Software Engineer', 'We are seeking a skilled Middle Java Software Engineer to join our team for a healthcare project based in the US. The successful candidate will contribute to the development of scalable software solutions using Java technologies, with a focus on system design and cloud-based architectures. This role requires technical expertise and effective collaboration within the team to deliver high-quality applications that meet the standards of the US healthcare industry.\n\nKey Responsibilities\n- Design, develop, and maintain applications using Java 8+ and Spring Boot, ensuring scalability through robust system architecture for a US-based healthcare project.\n- Build and implement RESTful APIs within a microservices framework to support healthcare-related functionalities.\n- Utilize containerization technologies such as Docker and Kubernetes (K8S) for deployment and orchestration.\n- Work with SQL (e.g., MySQL) and NoSQL (e.g., MongoDB) databases to optimize data management, ensuring compliance with healthcare data standards.\n- Integrate messaging systems like Kafka to support distributed systems in a healthcare context.\n- Apply system design principles to architect reliable and maintainable solutions tailored to healthcare requirements.\n- Leverage AWS services (e.g., S3, RDS, CloudWatch) for cloud-based application development and deployment, ensuring secure and efficient handling of sensitive healthcare data.\n- Use Git for version control and collaborative development within the team.\n- Participate in Agile/Scrum processes, including code reviews, to ensure team alignment and quality deliverables for the healthcare project.\n- Communicate effectively with team members to foster collaboration and project success.\n\nRequired Skills and Qualifications\n- At least 3 years of professional experience in software development with Java.\n- Strong proficiency in Java 8+, Spring Boot, and Spring Framework.\n- Experience with microservices architecture and RESTful API development.\n- Knowledge of system design and architecture principles for scalable applications.\n- Familiarity with containerization (Docker) and orchestration (Kubernetes).\n- Proficiency in SQL and NoSQL databases (e.g., MySQL, MongoDB).\n- Experience with messaging systems like Kafka and distributed systems.\n- Experience in AWS (e.g., S3, RDS, CloudWatch) for cloud-based solutions.\n- Proficiency in Git for version control.\n- Ability to work effectively within an Agile/Scrum environment.\n\nPreferred Qualifications\n- Strong English communication skills, both verbal and written, for effective team collaboration, especially given the project’s US-based context.\n- Familiarity with CI/CD tools such as Jenkins or GitLab CI.\n- Exposure to caching mechanisms (e.g., Redis).\n- Experience or familiarity with healthcare industry standards and regulations (e.g., HIPAA compliance) is a plus.\n\nJoin a dedicated team working on a meaningful US-based healthcare project, where your contributions will directly impact the improvement of healthcare services. We offer a collaborative and innovative work environment that values your growth and well-being. You will have the opportunity to work with cutting-edge technologies, including cloud platforms and modern Java frameworks, while gaining exposure to the US healthcare sector. We provide competitive compensation, comprehensive health benefits, and flexible working arrangements to support a healthy work-life balance. Additionally, our company is committed to continuous learning, offering access to training programs, certifications, and mentorship opportunities to help you advance your career. Be part of a team that values diversity, fosters creativity, and celebrates success together.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3158, 1222, 2, 'Kỹ Sư Thiết Kế Lập Trình CNC', 'Mô tả công việc\n- Bóc tách chi tiết phần gia công cho từng bản vẽ, lên quy trình công nghệ, tính toán phương án gia công;\n- Sử dụng phần mềm chuyên dụng thực hiện lập trình gia công các chi tiết, sản phẩm đảm bảo phù hợp với các thông số kỹ thuật của máy CNC;\n- Sử dụng 1 trong các phần mềm vẽ 3D (NX, Solidword, Mastercam...) để thiết kế đồ gá, jig gá phục vụ sản xuất;\n- Kịp thời chỉnh sửa bản vẽ lập trình khi phát hiện sai sót;\n- Thực hiện các công việc khác theo sự phân công của cấp Quản lý.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học; ưu tiên các chuyên ngành kỹ thuật: Cơ khí, Cơ điện tử, Tự động hóa và các chuyên ngành có liên quan;\n- Có ít nhất 1 năm về thiết kế, lập trình máy CNC trở lên; am hiểu IATF & kinh nghiệm về ngành ô tô là 1 lợi thế;\n- Sử dụng tiếng Anh trong công việc là một lợi thế;\n- Ưu tiên ứng viên đã từng làm việc trên máy CNC như: Fanuc, Makino, JIH, ... chuyên về sản xuất nhôm định hình;\n- Có trách nhiệm, chịu khó, chủ động, cải tiến trong công việc.\n\nQuyền lợi\n- Mức thu nhập khởi điểm sau khi tiếp nhận chính thức từ khoảng 13 triệu đến 20 triệu đồng (Có thể thỏa thuận với trường hợp ứng viên vượt trội về năng lực/kinh nghiệm);\n- Lương tháng 13 + thưởng hiệu quả kinh doanh sản xuất, thưởng Lễ, Tết...;\n- Môi trường làm việc an toàn, chuyên nghiệp, thân thiện (áp dụng hệ thống Quản lý chất lượng/ Quản lý môi trường theo tiêu chuẩn ISO 9001/ ISO 14001/ IATF 16949 và phương pháp 5S, Kaizen);\n- Cơ hội được đào tạo chuyên môn, kỹ năng làm việc; nhiều cơ hội phát triển, thăng tiến;\n- Được đóng BHXH, BHYT, ngày nghỉ phép năm theo quy định;\n- Được hưởng các chế độ phúc lợi; thưởng các dịp Lễ, Tết theo quy định của Công ty; thưởng sáng kiến, thưởng nhân viên của năm...;\n- Được tham gia các hoạt động do Công ty tổ chức: du lịch, teambuilding...;\n- Được cấp phát đồng phục làm việc theo tiêu chuẩn Công ty;\n- Khám sức khỏe định kì tại các cơ sở uy tín;\n- Phụ cấp ăn trưa tại Nhà máy và một số phụ cấp khác theo quy định của Công ty;\n- Công ty có xe đưa đón nhân viên theo tuyến Hà Nội - Bắc Ninh và Bắc Giang – Bắc Ninh.\n\nĐịa điểm làm việc\n- Bắc Ninh: Yên Phong\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n- Được nghỉ 01 thứ 7 cuối tháng.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3159, 1250, 2, 'Junior Mid Fullstack Developer (ReactJS + NodeJS)', 'OUR TECH STACK:\nBackend:\nNode.js / ExpressJs\nRabbitMQ / Kafka / MSSQL\nDocker / Kubernetes / Jenkins\nFrontend:\nReactJS/ NextJs\nES6 / Webpack\nRedux / Redux-Saga / Reselect / Hooks\n\nRESPONSIBILITIES:\n- Design, code, and review scalable, maintainable software solutions that align with business and system architecture.\n- Identify and address technical debt & challenges: Proactively analyze areas for improvement and implement changes to enhance system performance and scalability.\n- Collaborate across squads (frontend, backend, QA…) to share knowledge, align on best practices, and mentor junior team members\n- Take ownership of features or systems; lead projects or squads when needed, ensuring delivery quality and guiding technical direction.\n\nMust-Have:\n- Proactive problem-solver with a bias toward action and ownership.\n- Quick to pick up new frameworks, libraries, and tooling as the stack evolves.\n- At least 2 years of real-world experience in software development.\n- Familiarity with macOS or Linux for development and deployment tasks.\n- Hands-on experience or working knowledge in our core stack is required; full expertise in one side (FE or BE) is acceptable:\n- Backend: Node.js, PostgreSQL, Redis, Elasticsearch.\n- Frontend: React.js, Redux, Redux-Saga, Reselect, React Hooks.\n\nCommitment to code quality:\n- Strong experience in code reviews.\n- Familiarity with unit testing best practices.\n- Growth mindset: Ready to grow rapidly as the company scales several times a year.\n\nNice-to-Have (Plus):\n- Deep understanding of Webpack, including code splitting, asset optimization, and custom configurations.\n- Strong foundation in computer science: Data structures, algorithms, design patterns.\n- Experience in DevOps tasks: Deployment, scaling, monitoring, and performance tuning.\n- Familiarity with microservices architecture.\n\nCompetitive Compensation & Bonuses\n- Attractive salary package with performance-based monthly bonuses (up to 2 months’ salary per year).\n- 100% salary during the probation period.\n- 13th-month salary to ensure financial stability.\n- Performance reviews twice a year with opportunities for salary adjustments.\n\nFlexible Work & Growth Opportunities\n- Hybrid working model: Work from home or at the office as needed.\n- Work alongside top CTOs, architects, and tech leaders at Vexere.\n- Build your public profile through:\n- Publishing articles on Medium & Vexere Techblog under your name.\n- Contributing to Open Source projects managed by Vexere.\n- Speaking at tech talks and industry events.\n- Attractive stock options for dedicated developers and team leads.\n\nExclusive Employee Perks\n- Up to 30% discount on bus tickets for Vexere employees and their families.\n- 12 days of annual leave, with 1 extra day off every 3 years, convertible into salary.\n- Vibrant and dynamic work environment with a friendly, supportive team.\n- Training sessions on negotiation, communication, work management, interpersonal skills, and software technology.\n- Exciting company activities: Annual trips, team-building events, year-end parties, and more.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2- Thứ 6, Sáng thứ 7\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3160, 1150, 2, 'Backend (Python, NodeJS)', 'Mô tả công việc:\n- Thiết kế và triển khai các hệ thống backend cho các ứng dụng AI.\n- Xây dựng APIs để hỗ trợ tương tác từ frontend với các hệ thống backend.\n- Tối ưu hiệu suất, tính bảo mật và khả năng mở rộng của hệ thống cho các trường hợp sử dụng có tải cao.\n- Tham gia vào quá trình phân tích yêu cầu và lập kế hoạch phát triển sản phẩm.\n\nYêu cầu ứng viên:\n- Có ít nhất 3 năm làm việc thực tế với Backend.\n- Thành thạo các ngôn ngữ Python (FastAPI) và Node.js.\n- Thành thạo về RESTful API và các giao thức.\n- Thành thạo về mô hình như MVC.\n- Có kiến thức về Docker, Linux terminal, Bash.\n- Có kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu như Mongodb, PostgreSQL.\n\nƯu tiên ( yêu cầu không bắt buộc):\n- Hiểu biết về các kỹ thuật server push và giả server push.\n- Hiểu biết về reverse proxy, load balancer, zero downtime deployment.\n- Có kiến thức về LLM, RAG, Agent và có khả năng sử dụng CI/CD tools, Docker, Kubernetes là lợi thế.\n\nQuyền lợi:\n- Lương từ 17 triệu - 25 triệu.\n- Thưởng: thưởng năng suất, thưởng ngày lễ, tháng 13, …\n- Review năng lực định kỳ 6 tháng/lần.\n- Trà, cà phê free, tham gia nghỉ mát, hoạt động team building của công ty.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Hỗ trợ tối đa các thiết bị phục vụ công việc.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 2, Sàn dịch vụ thương mại tòa nhà CT2D, VOV Mễ Trì,, Nam Từ Liêm.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Sáng thứ 7 ( 8h-12h)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3161, 1350, 2, 'Frontend Developer', 'Mô tả công việc\n- Design and Development:\n- Build and maintain complex user interfaces using React and React Native.\n- Translate design mockups and wireframes into high-quality code.\n- Ensure responsive and adaptive design for cross-platform compatibility (web and mobile).\n- Performance Optimization:\n- Optimize components for maximum performance across a wide range of devices and browsers.\n- Address performance bottlenecks and ensure the app runs smoothly.\n- State Management:\n- Implement state management using tools like Redux, MobX, or Context API.\n- Manage application state efficiently in large-scale applications.\n- API Integration:\n- Work with backend developers to integrate RESTful or GraphQL APIs.\n- Handle asynchronous data flow with tools like Axios, Fetch, or Apollo Client.\n- Code Review and Mentoring:\n- Conduct code reviews and ensure coding standards and best practices.\n- Mentor junior developers and assist with technical problem-solving.\n- Testing and Debugging:\n- Write unit, integration, and end-to-end tests using tools like Jest, Enzyme, or Cypress.\n- Debug and fix production issues efficiently.\n- Collaboration:\n- Collaborate closely with UX/UI designers, backend developers, and product managers to ensure the frontend aligns with user needs and technical requirements.\n- Participate in agile processes like sprint planning, standups, and retrospectives.\n- Version Control and Deployment:\n- Manage codebase using Git for version control.\n- Participate in the CI/CD pipeline and handle code deployments for web and mobile apps.\n- Stay Updated:\n- Stay up-to-date with the latest trends in React, React Native, and frontend technologies.\n- Evaluate and integrate new libraries and tools to improve development processes.\n- Accessibility and SEO:\n- Ensure web applications are accessible to all users, including those with disabilities (ARIA standards).\n- Implement SEO best practices for React applications.\nYêu cầu ứng viên\n- A higher education degree in Computer Science or equivalent knowledge acquired through professional experience.\n- Minimum of 5 years of experience in software development, with a strong focus on browser-based user interfaces.\n- Proficiency in HTML, CSS, JavaScript (ES6+), and frontend frameworks (React, Vue.js, or Angular).\n- Experience with responsive design, cross-browser compatibility, and web performance optimization.\n- Familiarity with state management (Redux, Vuex) and API integration.\n- Knowledge of Git, CI/CD pipelines, and Agile methodologies.\n- Strong problem-solving skills and attention to detail.\nQuyền lợi\n- Competitive salary commensurate with experience.\n- Flexible working hours to support work-life balance and productivity.\n- Opportunity to work in a dynamic startup environment with a passionate and talented team.\n- Chance to make a significant impact on the growth and success of innovative products in the D2C industry.\n- Collaborative culture that values creativity, diversity, and continuous learning.\n- Career growth and skill development opportunities.\nĐịa điểm làm việc\n- Hồ Chí Minh: Huỳnh Khương Ninh, Quận 1\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3162, 1298, 2, 'FullStack Developer (.NET+React+MongoDB/Postgres)', 'Mô tả công việc\n- Phát triển giao diện người dùng hiện đại, responsive bằng ReactJS.\n- Thiết kế và xây dựng các dịch vụ web/API sử dụng .NET Core.\n- Thiết kế và tối ưu cơ sở dữ liệu PostgreSQL, MongoDB.\n- Tích hợp và tối ưu hệ thống tìm kiếm sử dụng ElasticSearch.\n- Xây dựng kiến trúc phần mềm chất lượng, dễ mở rộng.\n- Viết tài liệu kỹ thuật và hỗ trợ kiểm thử phần mềm.\n- Đóng góp ý tưởng cải tiến kỹ thuật và quy trình làm việc.\n\nYêu cầu ứng viên\n- Tốt nghiệp ngành CNTT, Khoa học máy tính hoặc tương đương.\n- Tối thiểu 2 năm kinh nghiệm với ReactJS và .NET Core.\n- Có kinh nghiệm làm việc với ElasticSearch để xây dựng tính năng tìm kiếm, lọc dữ liệu nâng cao.\n- Thành thạo làm việc với PostgreSQL và/hoặc MongoDB.\n- Có kiến thức tốt về RESTful APIs, JSON, Entity Framework, LINQ.\n- Sử dụng thành thạo Git, biết làm việc theo mô hình Agile/Scrum.\n\nQuyền lợi\n- Lương: 20.000.000 - 35.000.000\n- Thưởng dự án/thưởng kinh doanh: từ 1 – 5 tháng lương\n- Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần.\n- Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30.\n- Nghỉ phép: 12 ngày/năm\n- Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động.\n- BHXH, BHYT, BHTN, Bảo hiểm Bảo Việt cho 100% cán bộ sau thời gian thử việc.\n- Chính sách thu hút và đãi ngộ nhân tài.\n- Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty.\n- Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình.\n- Các hoạt động giao lưu bóng đá, golf, văn nghệ...\n- Đào tạo chuyên sâu theo yêu cầu công việc\n- Được tham gia các dự án lớn triển khai toàn quốc\n- Được tiếp cận các kỹ thuật, công nghệ hiện đại\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 22 tòa nhà Viwaseen, số 48 Tố Hữu, Trung Văn, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3163, 1116, 2, 'Kỹ Sư PLC_Không Yêu Cầu Kinh Nghiệm', 'Mô tả công việc:\n- Mô phỏng, lập trình, chạy thử hệ thống tự động hóa tích hợp PLC siemens, robot công nghiệp ABB và các thiết bị tiên tiến tại nhà máy sản suất ô tô Vinfast.\n- Phụ trách kỹ thuật chính cho các vấn đề điện điều khiển & PLC trong dây chuyền sản xuất hàng ngày.\n- Điều tra lỗi, phân tích nguyên nhân gốc rễ và hành động khắc phục cho phần điện điều khiển và PLC.\n- Trình bày các vấn đề kỹ thuật cho Kỹ sư trưởng PLC & Điện/quản lý công trường và đảm bảo trình bày chính xác cho các bên liên quan.\n- Tham gia vào công việc cải tiến/cải tạo hệ thống điện và điều khiển, tiến hành hiệu chuẩn, thử nghiệm và gỡ lỗi.\n- Phối hợp với kỹ sư OSS Robot & Cơ khí, nhân viên vận hành khách hàng và các bên liên quan chức năng khác trong công việc hàng ngày.\n\nYêu cầu ứng viên:\n- Có từng tiếp xúc qua về Siemens, ngoài ra sẽ được đào tạo để nắm bắt công việc.\n- Tốt nghiệp đại học, các chuyên nghành tự động hóa, cơ điện tử,…\n- Nhiệt tình, chăm chỉ.\n- Biết tiếng anh là 1 lợi thế.\n\nQuyền lợi:\n- Thưởng lương tháng 13 và đánh giá thưởng KPI hàng năm.\n- Lương cơ bản thương lượng theo năng lực.\n- Trợ cấp dự án, trợ cấp công tác theo từng dự án và khả năng đáp ứng công việc.\n- Hỗ trợ chỗ ở, ăn trưa, xăng xe đi lại làm việc.\n- Đóng bảo hiểm xã hội đầy đủ.\n- Du lịch hằng năm theo chế độ công ty.\n\nĐịa điểm làm việc:\n- Hà Tĩnh: Tx Kỳ Anh\n- Hải Phòng: Cát Hải\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Tĩnh, Hải Phòng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3164, 1175, 2, 'Lập Trình Viên C, C++', '• Làm việc tại Kobe Nhật Bản\n• Đối tượng: Nhận ứng viên từ Việt Nam sang Nhật hoặc đang sinh sống và làm việc tại Nhật\n• Lập trình bằng ngôn ngữ C, C++\n• Phân tích, thiết kế, lập trình và fix bug.\n• Thực hiện kiểm tra chất lượng sản phẩm đầu ra của dự án trước khi deliver cho khách hàng.\n• Thực hiện unit test theo nhu cầu dự án\n• Báo cáo hàng ngày với TBP\n• Hỗ trợ team cùng phát triển\n• Cập nhật tiến độ công việc hàng ngày vào tool quản lý dự án\n• Thực hiện đúng quy trình phát triển phần mềm\n\nYêu cầu ứng viên\n• Có kinh nghiệm code C, C++ từ 3 năm trở lên.\n• Tiếng Anh giao tiếp tốt hoặc tiếng Nhật N3+.\n• Có ý thức trách nhiệm cao.\n• Có khả năng đàm phán, thuyết phục, đề xuất ý kiến và giải pháp\n• Có khả năng tạo các tài liệu mô tả yêu cầu\n• Có khả năng giao tiếp, làm việc nhóm, khả năng giao tiếp với khách hàng.\n• Tích cực, chủ động, yêu thích việc quản lý dự án và dám đương đầu với thách thức\n\nQuyền lợi\nLương up to 550Man/năm\nNgồi làm việc trực tiếp tại công ty khách hàng bên Nhật.\nMôi trường làm việc chuyên nghiệp, ổn định lâu dài.\nNghỉ lễ theo ngày lễ của Nhật, và các chế độ theo công ty khách hàng Nhật.\nTham gia tất cả các chế độ BHXH, BHYT và chế độ đãi ngộ khác.\nXét tăng lương 1 năm 1 lần.\n\nLương OT: theo thời gian OT.\nCác loại lương thưởng khác.\n\nHỗ trợ nhà ở: 3 man/tháng.\nVé máy bay về Việt Nam: 8 man/năm.\nHỗ trợ chi phí đi lại: Theo thực tế.\nChi phí tham gia khoá học chuyên môn: Được công ty hỗ trợ.\n\nQuà lễ, Tết, party, du lịch công ty hàng năm.\nHỗ trợ gia hạn visa tại Nhật.\nĐối với ứng viên từ Việt Nam snag Nhật: Hỗ trợ toàn bộ chi phí sang Nhật\n\nĐịa điểm làm việc\n- Nhật Bản\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nhật Bản', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3165, 1315, 2, 'Devops Engineer', '1. Xây dựng & duy trì hạ tầng hiện tại\nCI/CD Pipeline: Thiết lập và duy trì các pipeline tự động hóa quy trình phát triển phần mềm, bao gồm GitHub Actions, GitLab CI, Jenkins, v.v.\nMôi trường triển khai: Quản lý và cấu hình môi trường staging và production, đảm bảo quá trình auto-deploy diễn ra an toàn và hiệu quả.\nCloud Infrastructure: Quản lý và tối ưu hóa hạ tầng trên các nền tảng cloud như AWS, bao gồm việc triển khai, giám sát và tối ưu hóa chi phí\n2. Giám sát & phản ứng nhanh với hệ thống\nMonitoring & Alerting: Thiết lập hệ thống giám sát với các công cụ như Prometheus, Grafana, Sentry, ELK Stack để theo dõi hiệu suất và phát hiện sớm sự cố.\nIncident Response: Phân tích và xử lý sự cố kịp thời, thực hiện root-cause analysis và cải tiến quy trình để giảm thiểu rủi ro trong tương lai.\n3. Bảo mật & ổn định\nQuản lý Secrets: Sử dụng các công cụ như Vault, AWS Secrets Manager để quản lý và bảo vệ thông tin nhạy cảm.\nAccess Control: Cấu hình và duy trì các chính sách bảo mật như security groups, tường lửa, Single Sign-On (SSO) để đảm bảo an toàn cho hệ thống.\n4. Tối ưu hệ thống\nHiệu suất & Chi phí: Theo dõi và phân tích hiệu suất hệ thống, đề xuất và triển khai các giải pháp tối ưu hóa để cải thiện hiệu suất và giảm thiểu chi phí vận hành.\nScalability: Làm việc chặt chẽ với các nhóm kỹ thuật để thiết kế và triển khai các kiến trúc hạ tầng có thể mở rộng (scale up, scale out) theo nhu cầu phát triển của công ty.\n5. Tự độ hoá & Infrastructure as Code (IaC)\nIaC: Sử dụng các công cụ như Terraform, Pulumi để tự động hóa việc triển khai và quản lý hạ tầng.\nDocumentation: Viết và duy trì tài liệu chi tiết về hạ tầng, quy trình triển khai và các best practices để đảm bảo tính nhất quán và dễ dàng bảo trì.\n\nYêu cầu ứng viên\nKinh nghiệm & Kiến thức\nKinh nghiệm: Có từ 2-3 năm kinh nghiệm thực tế trong lĩnh vực DevOps.\nCI/CD: Thành thạo trong việc thiết lập và duy trì các pipeline CI/CD, bao gồm việc tích hợp và triển khai tự động.\nCloud Platforms: Kinh nghiệm làm việc với ít nhất 1 trong các nền tảng cloud như AWS, GCP hoặc Azure.\nContainerization: Kinh nghiệm với Docker và Kubernetes, bao gồm việc triển khai và quản lý container trong môi trường sản xuất.\nScripting: Kỹ năng lập trình với ít nhất một ngôn ngữ như Bash, Python hoặc Go để tự động hoá các tác vụ và quy trình.\nNetworking: Kiến thức cơ bản về mạng, bao gồm DNS, VPN, firewall và các giao thức mạng phổ biến.\nKỹ năng bổ sung\nIaC: Kinh nghiệm với các công cụ Infrastructure as Code như Terraform hoặc Pulumi.\nMonitoring Tools: Kinh nghiệm với các công cụ giám sát như Prometheus, Grafana, Sentry hoặc ELK Stack.\nSecurity: Hiểu biết về các best practices bảo mật trong DevOps, bao gồm việc quản lý secrets, cấu hình quyền truy cập và bảo vệ hệ thống khỏi các mối đe doạ.\nTư duy & phẩm chất\nTư duy hệ thống: Khả năng phân tích và thiết kế các hệ thống phức tạp, đảm bảo tính ổn định và hiệu suất cao.\nChủ động & Trách nhiệm: Có khả năng làm việc độc lập, chủ động đề xuất giải pháp và chịu trách nhiệm với công việc của mình.\nKhả năng làm việc nhóm: Kỹ năng giao tiếp tiếp, có khả năng phối hợp hiệu quả với các nhóm kỹ thuật và không kỹ thuật trong công ty.\n\nQuyền lợi\nMức lương: 20.000.000 - 30.000.000\nMôi trường làm việc năng động: Làm việc trong một đội ngũ trẻ, năng động, với cơ hội học hỏi và phát triển nghề nghiệp\nSản phẩm có tầm ảnh hưởng: Tham gia phát triển các sản phẩm công nghệ giáo dục có ảnh hưởng sâu rộng tại Việt Nam.\nChế độ đãi ngộ hấp dẫn: Mức lương cạnh tranh, cùng các phúc lợi đầy đủ và môi trường làm việc linh hoạt.\n\nĐịa điểm làm việc\n- Hà Nội: Đường Đỗ Đức Dục, Mễ Trì, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 7 (từ 08:30 đến 12:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3166, 1247, 2, 'Chuyên Viên Phát Triển Phần Mềm', '• Tham gia phát triển lập trình phần mềm ứng dụng mới theo yêu cầu nghiệp vụ\n• Tham gia nghiên cứu, đánh giá, và áp dụng các giải pháp công nghệ mới\n• Bảo trì, nâng cấp, cập nhật, sửa lỗi các hệ thống phần mềm ứng dụng hiện có\n\nJob description:\n• Participate in the development of new system applications, based on business requirements\n• Participate in research, evaluation, and application of new technology solutions\n• Maintain, upgrade, update, fix errors of existing application systems and software\n\nYêu cầu ứng viên:\n• Sử dụng thành thạo ngôn ngữ lập trình: Java, Python\n• Lập trình thành thạo với hệ CSDL: MySQL, Oracle (Oracle là lợi thế)\n• Thành thạo HTML, CSS, Bootstrap, Javascript, Jquery\n• Kinh nghiệm sử dụng GIT như GitHub/GitLab, Docker container là một lợi thế\n• Tốt nghiệp đại học trở lên, ưu tiên ứng viên tốt nghiệp chuyên ngành Công nghệ thông tin\n• Thành thạo tiếng Anh giao tiếp, đọc viết tốt\n• Có tối thiểu 2 năm kinh nghiệm đảm nhiệm vị trí Chuyên viên Phát triển phần mềm\n• Có kĩ năng giao tiếp tốt, chủ động, chăm chỉ và cầu tiến trong công việc\n• Có kĩ năng làm việc theo nhóm\n• Có kĩ năng tư duy logic, xử lý tình huống nhanh, hiệu quả\n• Có kĩ năng phân tích và đánh giá yêu cầu\n\nBenefits:\n• Receive attractive income & benefits, competitive in the market\n• Enjoy social insurance, health insurance, health insurance according to the Company\'s regulations\n• Enjoy annual leave, public holidays in accordance with the law\n• Enjoy lunch allowance\n• Participate in annual vacation, travel, teambuilding, sports tournaments, and cultural activities\n• Work in a professional, dynamic and effective environment\n• Participate in regular professional training courses to help improve technical expertise and personal skills\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 10&11 tòa Discovery Complex, 302 Cầu Giấy, P. Dịch Vọng, Cầu Giấy\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3167, 1120, 2, 'Nhân Viên Mobile App Developer (React Native)', 'Mô tả công việc\n- Tham gia phát triển và xây dựng các sản phẩm dựa trên nền React Native.\n- Tìm hiểu công nghệ, xây dựng mới và phát triển tính năng hiện tại của các dự án.\n- Nâng cấp, phát triển thêm tính năng theo yêu cầu khách hàng\n- Quản lý và bảo trì các ứng dụng đảm bảo chất lượng.\n- Hỗ trợ, sửa lỗi trong quá trình triển khai.\n- Đảm bảo tiến độ, chất lượng công việc và báo cáo thường xuyên tới quản lý.\n- Thực hiện một số công việc khác khi có yêu cầu của cấp trên.\n\nYêu cầu ứng viên\n- Thành thạo lập trình mobile app cross-platform trên React Native framework\n- Nắm vững kiến thức lập trình trên mobile\n- Có kinh nghiệm chuyên phát triển trên Android (ưu tiên) hoặc iOS là một lợi thế\n- Có kinh nghiệm phát triển mobile app trên các nền tảng cross-platform (Ionic/Native script) khác là một lợi thế\n- Kinh nghiệm phát triển App với React Native tối thiểu từ 1-2 năm.\n- Có kinh nghiệm lập trình giao tiếp giữa mobile với server qua các giao thức TCP/IP, Firebase, Websocket, WebService và JSON/XML\n- Nhiệt tình trong công việc và chủ động trao đổi, học hỏi\n\nQuyền lợi\n- Mức lương cơ bản từ 8 - 20 triệu tùy theo năng lực và vị trí công việc.\n- Được tổ chức sinh nhât, nghỉ lễ, nghỉ phép và hưởng quyền lợi theo Luật lao động.\n- Đồng nghiệp và môi trường làm việc năng động\n- Cơ hội được học tập và đào tạo nội bộ về các kỹ năng trong công việc.\n\nĐịa điểm làm việc\n- Nghệ An: Tầng 22 Handico 30 Quang Trung, TP Vinh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 07:45 đến 17:00)\n- Thứ 7 luân phiên nghỉ/ làm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nghệ An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3168, 1274, 2, 'Java Developer -  3 Năm Kinh Nghiệm', 'Mô tả công việc\nPhát triển, tối ưu và bảo trì các hệ thống backend sử dụng Java Spring Boot.\nThiết kế và triển khai các API phục vụ frontend và mobile app.\nTham gia phân tích yêu cầu và đề xuất giải pháp kỹ thuật.\nTối ưu hiệu suất hệ thống, xử lý lỗi và các tình huống bất thường.\nLàm việc với Redis, Kafka trong các hệ thống realtime, phân tán là một lợi thế lớn.\nPhối hợp với các thành viên team BA, QA, DevOps để đảm bảo chất lượng và tiến độ dự án.\n\nYêu cầu ứng viên\nCó trên 3 năm kinh nghiệm phát triển ứng dụng backend với Java Spring Boot.\nThành thạo RESTful API, OOP, và mô hình MVC.\nKinh nghiệm với cơ sở dữ liệu quan hệ (MySQL, PostgreSQL) và NoSQL là điểm cộng.\nƯu tiên có kinh nghiệm làm việc với:\nRedis (caching, pub/sub...)\nApache Kafka (message broker, event-driven architecture)\nNắm vững Git và quy trình làm việc Agile/Scrum.\nTinh thần học hỏi, chủ động và trách nhiệm trong công việc.\nTốt nghiệp Đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính hoặc các lĩnh vực liên quan.\nƯu Tên nhận việc luôn.\n\nQuyền lợi\nMức lương cạnh tranh: up to 25M gross, review 2 lần/năm.\nLộ trình thăng tiến rõ ràng, hỗ trợ phát triển kỹ năng chuyên sâu.\nMôi trường làm việc năng động, thân thiện, có cơ hội học hỏi từ các dự án thực tế.\nTham gia BHXH, BHYT, các hoạt động teambuilding, du lịch cùng công ty.\nThời gian làm việc: Thứ 2 – Thứ 6, nghỉ T7 & CN.\n\nĐịa điểm làm việc\n- Hà Nội: Số 1 Trần Hữu Dực, Nam Từ Liêm.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3169, 486, 2, 'Game Server Developer - Middle - Senior', 'Mô tả công việc:\n- Phát triển server-side cho game mobile mới trên iOS/Android\n- Client sử dụng Unity\n- Sử dụng PHP (CodeIgniter) & Node.js\n- Thiết kế API, database, logic hệ thống\n- Thực hiện các công việc khác theo yêu cầu\n\nYêu cầu ứng viên:\n- Trên 3 năm kinh nghiệm phát triển game server-side\n- Thành thạo thiết kế hệ thống server-side\n- Có tư duy logic và khả năng giải quyết vấn đề tốt\n- Chỉ nhận CV tiếng Anh\n\nƯu Tiên:\n- Kinh nghiệm phát triển game bằng Unity\n- Kinh nghiệm MMO & real-time game (Node.js)\n- Kỹ năng lãnh đạo & giao tiếp tiếng Anh cơ bản\n\nCông nghệ sử dụng:\n- Ngôn ngữ: PHP (CodeIgniter), Unity (C++), Node.js\n- Database: MySQL, MongoDB\n- Tool khác: Redis\n\nQuyền lợi:\n- Thưởng tháng thứ 13\n- Thưởng nhân viên chuyên cần mỗi tháng\n- Tiền mừng sinh nhật, mừng cưới, mừng sinh em bé...\n- Tổ chức Event, Party, quà mừng v.v vào các dịp lễ\n- Quầy Pantry với đồ ăn nhẹ phong phú. Đặc biệt Happy Friday mỗi tuần\n- Review lương định kỳ mỗi năm\n- Môi trường làm việc chuyên nghiệp, cởi mở, hòa đồng và thân thiện\n- Khám sức khỏe định kỳ mỗi năm tại bệnh viện của Nhật.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Bình Thạnh\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3170, 1131, 2, 'Software Engineer', 'Mô tả công việc:\n- Phát triển, kiểm thử và sửa lỗi phần mềm theo yêu cầu.\n- Bảo trì, nâng cấp để đảm bảo hiệu năng hệ thống.\n- Đề xuất các giải pháp kỹ thuật nhằm đáp ứng yêu cầu nghiệp vụ.\n- Tham gia thiết kế hệ thống phần mềm.\n- Cung cấp tài liệu kỹ thuật đầy đủ trong quá trình phát triển.\n- Phối hợp với các bộ phận liên quan để đảm bảo tiến độ dự án.\n\nYêu cầu ứng viên:\n- Tốt nghiệp ngành CNTT, Kỹ thuật máy tính hoặc tương đương.\n- Tối thiểu 5 năm kinh nghiệm làm việc với Java, đặc biệt các framework như Spring Boot, Spring MVC, Spring Data,...\n- Thành thạo cơ sở dữ liệu SQL và NoSQL, có khả năng tối ưu truy vấn và thiết kế DB hiệu quả.\nƯu tiên:\n- Kinh nghiệm trong lĩnh vực tài chính – ngân hàng.\n- Có kinh nghiệm làm việc với nền tảng đa kênh (Omni-channel).\n\nQuyền lợi:\n- Lương tháng 13\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop….\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm\n- Làm việc với tác đối tác lớn\n- Review tăng lương định kỳ hàng năm (1 lần / năm)\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Quận 4\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 4', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3171, 72, 2, 'Flutter Developer Leader', 'Phát triển ứng dụng:\n- Chịu trách nhiệm phát triển các tính năng mới và duy trì ứng dụng FPT Medicare/ HiFPT hiện có trên nền tảng iOS và Android bằng Flutter.\n- Tham gia vào việc thiết kế kiến trúc ứng dụng, đảm bảo tính ổn định, khả năng mở rộng và hiệu năng cao.\n- Viết code chất lượng cao, dễ đọc, dễ bảo trì và tuân thủ các tiêu chuẩn coding của công ty.\n\nNghiên cứu và áp dụng công nghệ:\n- Nghiên cứu, thử nghiệm và áp dụng các công nghệ mới nhất liên quan vào dự án.\n- Đề xuất các giải pháp kỹ thuật sáng tạo để giải quyết các vấn đề phức tạp trong quá trình phát triển.\n\nTích hợp và kiểm thử:\n- Tích hợp các thư viện, SDK của bên thứ ba (ví dụ: SDK camera, SDK IoT) vào ứng dụng.\n- Thực hiện kiểm thử đơn vị (unit test), kiểm thử tích hợp (integration test) và kiểm thử giao diện người dùng (UI test) để đảm bảo chất lượng sản phẩm.\n- Phối hợp với bộ phận kiểm thử (QA) để xác định và sửa lỗi.\n\nHợp tác và giao tiếp:\n- Quản lý tasks công việc, làm việc chặt chẽ với các thành viên khác trong nhóm (designer, product manager, backend developer) để đảm bảo dự án được hoàn thành đúng thời hạn và đạt chất lượng cao.\n- Tham gia vào các buổi họp nhóm để chia sẻ kiến thức, kinh nghiệm và đưa ra các giải pháp.\n- Báo cáo tiến độ công việc thường xuyên cho cấp trên.\n- Thực hiện các nhiệm vụ khác theo yêu cầu của cấp trên, phù hợp với năng lực và kinh nghiệm.\n\nYêu cầu ứng viên:\n- Học vấn:Tốt nghiệp Đại học trở lên chuyên ngành Khoa học máy tính, Kỹ thuật phần mềm hoặc các ngành liên quan.\n- Kinh nghiệm: Ít nhất 03 năm kinh nghiệm phát triển ứng dụng di động bằng Flutter.\n- Am hiểu phát triển ứng dụng iOS bằng Swift/Objective C.\n- Ưu tiên ứng viên có kinh nghiệm triển khai và quản lý 1 nhóm nhỏ nhân sự Mobile Dev.\n- Kỹ năng chuyên môn: Sử dụng thành thạo Flutter framework.\n- Am hiểu về Swift/ Objective C.\n- Hiểu sâu về các widget, layout, animation, state management trong Flutter.\n- Có kinh nghiệm xây dựng UI/UX phức tạp và tùy biến giao diện theo yêu cầu.\n- Kiến trúc và Design Patterns:\n- Có tư duy logic tốt, hiểu biết về cấu trúc dữ liệu, thuật toán, design pattern (ví dụ: Singleton, Factory, Observer, MVVM, BLoC).\n- Nắm vững các nguyên tắc Clean Architecture, MVVM, SOLID principles.\n- Có khả năng tổ chức code rõ ràng, dễ đọc, dễ bảo trì và có khả năng tái sử dụng cao.\n- Có kinh nghiệm kết nối client-server sử dụng các giao thức webservice, MQTT, RESTful, JSON, REST API.\n- Có kinh nghiệm làm việc với push notification (Firebase Cloud Messaging), maps (Google Maps, Mapbox), multimedia (video, audio), WebRTC.\n- Biết tích hợp các dịch vụ của Google (Firebase, Google Analytics, Google Play Services), Facebook (Facebook Login, Facebook SDK).\n- Thành thạo về Material Design, custom layout là một lợi thế.\n- Biết sử dụng các công cụ hỗ trợ lập trình: Git (Github, Gitlab, Bitbucket), IDE (Android Studio, VS Code).\n- Có kinh nghiệm làm việc với quy trình Agile/Scrum.\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh chuyên ngành.\n- Có tinh thần học hỏi, chủ động nghiên cứu và cập nhật các công nghệ mới.\n- Kỹ năng giao tiếp tốt, có khả năng trình bày ý tưởng rõ ràng và thuyết phục.\n- Có khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Nhiệt tình, trách nhiệm cao trong công việc và có khả năng chịu áp lực tốt.\n\nQuyền lợi:\n- Gói thu nhập cạnh tranh, hấp dẫn, tương xứng với năng lực và kinh nghiệm.\n- Thưởng lương tháng 13, thưởng hiệu suất làm việc, thưởng nghỉ mát.\n- Đầy đủ các chế độ bảo hiểm theo luật lao động Việt Nam (Bảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp).\n- Chính sách phúc lợi đa dạng: Chăm sóc sức khỏe định kỳ hàng năm, gói bảo hiểm sức khỏe chuyên biệt FPT Care (khám chữa bệnh miễn phí tại tất cả các bệnh viện).\n- Các hoạt động tri ân, chăm lo đời sống tinh thần cho CBNV và người thân.\n- Chế độ nghỉ phép năm, nghỉ lễ theo quy định.\n- Được tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn và kỹ năng mềm.Nhiều cơ hội phát triển và thăng tiến trong công việc.\n- Môi trường làm việc thân thiện, cởi mở, năng động, sáng tạo và chuyên nghiệp.\n- Đồng nghiệp nhiệt tình, sẵn sàng hỗ trợ.\n- Cơ sở vật chất và công cụ làm việc hiện đại, tiện nghi.\n- Văn hóa doanh nghiệp đặc sắc, sinh động bậc nhất với nhiều hoạt động hấp dẫn: Tân binh, Teambuilding, Hội diễn Sao Chổi, Sinh nhật công ty, các sự kiện ngày lễ...\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Quận 7\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3172, 1415, 2, 'Web Developer', 'Làm việc cho Công Ty Cổ Phần Công Nghệ Khí Tượng Thủy Văn Và Môi Trường Dicom - Trực thuộc Hệ sinh thái của Tập Đoàn Dicom.\n- Tham gia phát triển và triển khai các phần mềm, ứng dụng web-based trong lĩnh vực Hàng không trong nước và nước ngoài.\n- Tham gia đầy đủ quá trình phát triển phần mềm từ phân tích yêu cầu,  thiết kế hệ thống, thiết kế CSDL, lập trình đến kiểm thử chất lượng phần mềm.\n- Xây dựng giải pháp kỹ thuật, lựa chọn công nghệ để phát triển các sản phẩm phần mềm phù hợp với yêu cầu của các dự án và nhu cầu của khách hàng.\n- Viết thuyết minh dự án, các quy trình nghiệm thu, tài liệu mô tả sản phẩm và hướng dẫn sử dụng.\n- Phối hợp với các thành viên trong các dự án để tích hợp, triển khai, nghiệm thu toàn hệ thống.\n- Thực hiện các công việc khác trong phòng khi được yêu cầu.\n\nYêu cầu ứng viên:\n- Trình độ học vấn: Tốt nghiệp đại học chuyên ngành Công nghệ thông tin.\n- Thành thạo PHP, HTML, Javascript, CSS, jQuery.\n- Có kinh nghiệm sử dụng ít nhất 1 hệ quản trị cơ sở dữ liệu MySQL hoặc PostgreSQL.\n- Có kinh nghiệm sử dụng và phát triển hệ thống WebGIS mã nguồn mở: Geoserver.\n- Có tư duy logic, phân tích yêu cầu và giải quyết vấn đề.\n- Biết sử dụng các công cụ như Jira, Git, Figma...\n- Tiếng Anh đọc hiểu tài liệu, viết email.\n- Có kinh nghiệm ít nhất 1 library/framework để phát triển front-end: Typescript, VueJS, ReactJS, v.v... là một lợi thế.\n- Ưu tiên ứng viên tốt nghiệp loại giỏi ở các trường top đầu VN về công nghệ hoặc đã từng thi quốc gia về các môn tự nhiên.\n- Có khả năng tìm kiếm, nghiên cứu tài liệu bằng tiếng Anh là một lợi thế.\n- Kỹ năng làm việc nhóm tốt, tinh thần học hỏi và sẵn sàng tiếp nhận công nghệ mới.\n\nQuyền lợi:\n- Mức lương thỏa thuận: hấp dẫn theo năng lực.\n- Đóng BHXH sau 2 tháng thử việc thành công.\n- Thưởng 6 tháng, thưởng cuối năm.\n- Thời gian làm việc từ thứ 2 - thứ 6 (nghỉ thứ 7, chủ nhật).\n- Du lịch, khám sức khỏe hàng năm.\n- Thưởng lễ tết, sinh nhật, ốm đau, hiếu hỉ.\n- Môi trường làm việc chuyên nghiệp, thân thiện.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 15, tòa nhà Center Building, số 1 Nguyễn Huy Tưởng, Phường Thanh Xuân Trung, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3173, 1274, 2, 'ReactJS Developer', 'Mô tả công việc\nTham gia phát triển giao diện người dùng (UI) cho các sản phẩm web hiện đại sử dụng ReactJS, TypeScript, Next.js. Xây dựng giao diện responsive, tối ưu hiệu suất và thân thiện với người dùng bằng Tailwind CSS và Ant Design (Antd). Phối hợp chặt chẽ với team thiết kế, backend và QA để triển khai các tính năng mới. Tối ưu trải nghiệm người dùng và hiệu suất ứng dụng web. Đóng góp ý tưởng cải thiện sản phẩm, quy trình làm việc, chất lượng code. Tham gia review code, chia sẻ kiến thức với team.\nYêu cầu ứng viên\nThành thạo TypeScript, có khả năng áp dụng vào dự án thực tế. Kinh nghiệm phát triển giao diện với React.js. Sử dụng thành thạo Next.js (ưu tiên ứng viên đã làm việc với cả App Router và Pages Router). Có gu thẩm mỹ tốt và khả năng xây dựng giao diện hiện đại, đẹp mắt với Tailwind CSS. Thành thạo Ant Design: biết tùy chỉnh và sử dụng hiệu quả các component. Biết sử dụng Git, nắm vững các thao tác cơ bản và làm việc nhóm trên Git. Tư duy sản phẩm tốt, chủ động trong công việc. Kỹ năng làm việc độc lập và phối hợp nhóm hiệu quả.\nQuyền lợi\nMôi trường làm việc trẻ, năng động, đồng nghiệp thân thiện. Được tham gia các dự án thực tế với quy mô lớn, công nghệ mới. Thời gian làm việc linh hoạt (có thể remote tùy chính sách). Review lương định kỳ 2 lần/năm, thưởng hiệu suất. Được cấp thiết bị làm việc (laptop, màn hình… nếu onsite). Các chế độ BHXH, nghỉ phép, team building đầy đủ theo luật.\nĐịa điểm làm việc\n- Hà Nội: Hoàng Quốc Việt, Cầu Giấy\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3174, 1144, 2, 'Frontend Leader', 'Mô tả công việc\n- Thiết kế kiến trúc frontend sử dụng NextJS, Typescript, xây dựng theo component-based và tách biệt UI/logic theo chuẩn industry.\n- Quản lý tiến độ, phân công task, theo dõi và hỗ trợ team frontend xử lý task và bugs.\n- Phát triển UI sử dụng Tailwind CSS/Ant Design, đảm bảo tính tái sử dụng và maintainable.\n- Review source code, đảm bảo chuẩn coding convention và performance (SSR/CSR, lazy loading, hydration).\n- Tối ưu SEO, performance và trải nghiệm người dùng.\n- Tích hợp frontend với các API backend qua RESTful API, đảm bảo bảo mật với JWT, API key, xử lý timeout và fallback.\n- Hướng dẫn frontend developers về kiến trúc NextJS, phân tách logic UI/state, tích hợp hiệu quả với backend và external services.\n- Phối hợp với team backend để đảm bảo tính nhất quán của UI/UX và logic nghiệp vụ.\n- Đề xuất giải pháp UI nâng cao để cải thiện hiệu suất và khả năng mở rộng, sử dụng caching strategy phù hợp.\nYêu cầu ứng viên\nKỹ năng chuyên môn\n- 4+ năm kinh nghiệm về ReactJS, TypeScript, và Next.js.\n- Hiểu rõ về bất đồng bộ trong JavaScript, React Hooks, và đặc biệt là các phương pháp tốt nhất khi sử dụng Redux, quản lý Store, State, Context API, Redux Middleware và tối ưu hóa hiệu suất.\n- Thành thạo kỹ thuật tối ưu SEO cho SPA/SSR (Server-Side Rendering, Head management...).\n- Có kinh nghiệm nâng cao hiệu suất và trải nghiệm người dùng: lazy loading, code splitting, UI responsiveness.\n- Hiểu rõ các nguyên tắc bảo mật phía frontend: XSS, CSRF, input sanitization...\n- Kỹ năng clean code, tối ưu UI/UX, và phát triển component theo hướng tái sử dụng.\nKỹ năng quản lý\n- 2+ năm kinh nghiệm trong vai trò team lead hoặc technical lead frontend.\n- Khả năng định hướng kiến trúc frontend, đảm bảo khả năng mở rộng và tích hợp hiệu quả với backend qua REST API / GraphQL.\n- Có kinh nghiệm review code, kiểm soát chất lượng source code và áp dụng tiêu chuẩn coding.\n- Khả năng giao tiếp và phối hợp hiệu quả với UI/UX, backend và quản lý sản phẩm.\n- Kỹ năng giải quyết vấn đề tốt.\nQuyền lợi\n– Thu nhập upto 45M\n– Thử việc 2 tháng hưởng 100% lương\n– Tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật lao động\n– Tham gia bảo hiểm VBI\n– Review lương 2 lần/năm\n– Lương tháng 13, thưởng lễ, Tết, Tang lễ, Sinh nhật,...\n– Hỗ trợ chi phí thi chứng chỉ theo quy định của công ty\n– Phụ cấp khi nhận chứng chỉ\n– Phụ cấp gửi xe\n– Phụ cấp thâm niên, thưởng dự án xuất sắc\n– Du lịch hằng năm theo chính sách của công ty\n– Khám sức khỏe định kỳ hằng năm\n– Cơ hội thăng tiến rõ ràng\n– Cơ hội làm việc tại các nước đối tác: Nhật Bản, Hàn Quốc, Singapore, Úc\nĐịa điểm làm việc\n- Hồ Chí Minh: 10F Mekong Tower, 235 Cong Hoa, Ward 13, Tân Bình\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3175, 1448, 2, 'Leader Java Backend', 'Mô tả công việc\n- Tham gia thiết kế, kiến trúc và phát triển hệ thống backend cho sàn giao dịch P2P crypto.\n- Xây dựng các module core: quản lý người dùng, ví điện tử, xử lý đơn hàng P2P, escrow (giao dịch ký quỹ), hệ thống reward, settlement, KYC/AML...\n- Phát triển và tối ưu các API RESTful phục vụ frontend/web app và tích hợp hệ thống với bên thứ ba như Fireblocks, Chainalysis, dịch vụ blockchain node...\n- Đảm bảo các tiêu chuẩn bảo mật, hiệu năng và khả năng mở rộng (scalability) của hệ thống.\n- Định hướng kỹ thuật, mentor các thành viên junior trong team.\n- Tham gia review code, thiết kế kỹ thuật, chuẩn hóa coding convention và CI/CD pipeline.\n- Theo dõi hệ thống production, xử lý sự cố, log, giám sát hiệu suất (monitoring, alerting).\n- Cập nhật và áp dụng các công nghệ, giải pháp mới trong lĩnh vực Web3, crypto, blockchain.\n- Phản hồi nhanh chóng và hiệu quả đối về các vấn đề kỹ thuật phát sinh trong quá trình phát triển và sau khi sản phẩm được triển khai.\n- Phối hợp với các nhóm khác như UI/UX, QC, và DevOps để đảm bảo ứng dụng được phát triển một cách toàn diện.\n\nYêu cầu ứng viên\n- Tối thiểu 4–5 năm kinh nghiệm phát triển hệ thống Backend với Java, trong đó ít nhất 2 năm kinh nghiệm làm hệ thống sàn giao dịch tập trung hoặc P2P crypto.\n- Thành thạo Java JDK 17, Spring Boots, Spring Cloud, Redis, Message Bus: Kafka/RabbitMQ, MySQL/PostgreSQL, MongoDB.\n- Hiểu sâu về các mô hình thiết kế phần mềm (Design Patterns), kiến trúc microservices và event-driven architecture.\n- Kinh nghiệm xử lý giao dịch tài chính, đảm bảo tính nhất quán dữ liệu (consistency), độ trễ thấp (low latency) và độ an toàn cao (security-first).\n- Có kiến thức về blockchain, ví crypto, smart contract, bảo mật trong Web3 là lợi thế lớn;\n- Thành thạo thiết kế API, thiết kế hệ thống, kiến ​​trúc phần mềm\n- Thành thạo Clean Code và SOLID\n- Khả năng thiết kế và tối ưu hóa cơ sở dữ liệu SQL và NoSQL\n- Kinh nghiệm làm việc theo phương pháp Agile/Scrum và sử dụng các công cụ quản lý dự án như JIRA hoặc Trello.\n- Hiểu biết về các nguyên tắc bảo mật ứng dụng và kinh nghiệm triển khai các giải pháp bảo mật.\n- Khả năng giao tiếp rõ ràng và hiệu quả, cả bằng văn bản lẫn nói, với các bên liên quan kỹ thuật và phi kỹ thuật.\n- Có tinh thần học hỏi không ngừng và khả năng thích nghi với các công nghệ mới nhanh chóng.\n- Chủ động, sáng tạo, nhiệt tình, trách nhiệm trong công việc.\n- Có khả năng phân tích, tư duy logic và giải quyết vấn đề\n- Sẵn sàng làm thêm giờ hoặc onsite khi có yêu cầu.\n\nQuyền lợi\n- Mức lương cạnh tranh theo đúng năng lực.\n- Môi trường làm việc thân thiện, năng động, có cơ hội phát triển bản thân và thăng tiến.\n- Cơ hội tiếp cận với các công nghệ mới, làm việc trong môi trường công nghệ năng động.\n- Tham gia vào các dự án thú vị và thử thách trong lĩnh vực mới như blockchain/web3/fintech\n- Chế độ bảo hiểm đầy đủ, nghỉ phép theo quy định\n- Thưởng Lễ Tết, 30/4; 1/ 5; 2/9…. (theo tình hình hoạt động thực tế của Công ty)\n- Sinh nhật, ốm đau, sinh con, ma chay, hiếu hỉ theo mức quy định của Công ty.\n- Teambuilding, nghỉ mát….. (theo tình hình hoạt động thực tế của Công ty).\n\nĐịa điểm làm việc\n- Hà Nội: 34 Nguyễn Khánh Toàn, Quan Hoa, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nThứ 7 làm việc luân phiên theo tuần\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3176, 1150, 2, 'ReactJs (Desktop App) Developer', 'Mô tả công việc:\n- Thiết kế phần mềm hoạt động trên nền tảng desktop (windows, linux).\n- Phát triển phần mềm cho hệ thống AI và robot tự động hoá (phần mềm đòi hỏi hoạt động chính xác, ổn định, thân thiện với người dùng, tương tác thời gian thực, bảo mật).\n- Làm việc nhóm, phối hợp phát triển với team Backend khác để tạo ra những sản phẩm hoàn thiện, đồng bộ nhất.\n\nYêu cầu ứng viên:\n- Tối thiểu 1 năm kinh nghiệm thực chiến trong việc xây dựng giao diện người dùng (UI) bằng ReactJS.\n- Sẽ là một lợi thế lớn nếu bạn có kiến thức hoặc đã từng làm việc với:\n  - Electron.js: Để đóng gói ứng dụng web thành ứng dụng desktop đa nền tảng.\n  - Three.js (hoặc các thư viện đồ họa 3D tương tự): Để hiển thị và tương tác với mô hình robot 3D.\n  - URDF, STL: Các định dạng phổ biến để mô tả và hiển thị robot.\n- Luôn chủ động tìm tòi, không ngừng học hỏi để nắm bắt các công nghệ và giải pháp mới.\n\nQuyền lợi:\n- Mức lương: từ 10 - 15 triệu/tháng\n- Thưởng: Thưởng hiệu quả công việc, ngày lễ tết, tháng lương thứ 13,...\n- Review năng lực định kỳ 01 năm/lần\n- Môi trường làm việc thoải mái, sáng tạo, năng động\n- Du lịch, nghỉ mát, team building,... hằng năm\n- Được cung cấp trang thiết bị làm việc hiện đại. Case xịn + 2 màn hình, server và các tài nguyên liên quan phục vụ công việc.\n- Nghỉ phép hưởng nguyên lương 12 ngày/năm.\n- Được hưởng đầy đủ các chính sách BHXH, BHYT, các phúc lợi khác theo đúng quy định của Luật lao động và các chế độ đãi ngộ của Công ty.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Nam Từ Liêm', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3177, 1268, 2, 'Senior Full Stack Developer - Odoo', 'Mô tả công việc\n- Phát triển các hệ thống phần mềm dành cho doanh nghiệp như CRM, HRM, IoT, MES... dựa trên nền tảng Odoo.\n- Tham gia toàn diện vào vòng đời phát triển phần mềm: từ khảo sát yêu cầu, thiết kế giải pháp hệ thống, phát triển tính năng, kiểm thử cho đến bảo trì sau triển khai.\n- Tùy biến và xây dựng các mô-đun Odoo đảm bảo đúng nghiệp vụ, tối ưu về hiệu suất và khả năng mở rộng cho tương lai.\n- Thiết kế, phát triển API (REST/XML-RPC) để tích hợp Odoo với ứng dụng di động, thiết bị IoT và các nền tảng bên ngoài.\n- Làm việc chủ yếu với cơ sở dữ liệu PostgreSQL; có hiểu biết về các hệ quản trị khác là một lợi thế.\n- Đảm bảo hệ thống vận hành ổn định trên môi trường điện toán đám mây (ưu tiên AWS), tối ưu hiệu năng để phục vụ lượng lớn người dùng và thiết bị.\n- Xây dựng mã nguồn có thể tái sử dụng, phát triển thư viện dùng chung nội bộ và chuẩn hóa quy trình lập trình dự án.\n- Chủ động tìm hiểu, cập nhật công nghệ mới nhằm cải tiến chất lượng phần mềm và tối ưu hóa các quy trình DevOps, CI/CD.\n\nYêu cầu ứng viên\n- Ít nhất 3 năm làm việc với Odoo.\n- Có kinh nghiệm làm việc với PostgreSQL, hiểu về indexing, optimization, data modeling.\n- Hiểu cơ bản về HTML, CSS, JavaScript; biết tùy chỉnh giao diện Odoo là lợi thế.\n- Từng triển khai hệ thống Odoo trên môi trường AWS/Cloud.\n- Có kinh nghiệm thiết kế API tích hợp giữa Odoo và hệ thống bên ngoài.\n- Ưu tiên: Có hiểu biết hoặc từng làm việc với IoT, hệ thống streaming, Biết DevOps, CI/CD, Docker là điểm cộng lớn.\n- Kỹ năng làm việc nhóm tốt, chủ động và linh hoạt trong môi trường Agile/Scrum.\n\nQuyền lợi\n- Mức lương cạnh tranh, thỏa thuận theo kinh nghiệm/năng lực;\n- Thời gian làm việc: Thứ Hai – Thứ Sáu, thời gian làm việc linh hoạt;\n- Thử việc hưởng 100% lương, được trang bị công cụ làm việc theo chính sách của công ty;\n- Môi trường làm việc trẻ trung, năng động, tài năng;\n- Được đánh giá review lương định kì 6 tháng/lần;\n- Thưởng ngày Lễ/Tết, thưởng KPI, thưởng dự án;\n- Được khám sức khỏe định kỳ;\n- Du lịch/nghỉ mát cùng công ty hàng năm;\n- Các chế độ khác theo quy định của pháp luật.\n\nĐịa điểm làm việc\n- Hà Nội\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Từ Thứ 2 đến Sáng Thứ 7.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3178, 1305, 2, 'Nhân Viên Wordpress Developer', 'Mô tả công việc:\n•Tham gia xây dựng hệ thống website \n• Lập trình Web dựa trên mã nguồn WordPress.\n• Có kinh nghiệm về UI/UX\n• Xây dựng, chỉnh sửa hoặc bổ sung các tính năng cho Plugin của WordPress.\n• Nắm rõ đầu việc được phân bổ và báo cáo tiến độ cho quản lý.\n\nYêu cầu ứng viên:\n• Có kinh nghiệm tối thiểu 6 tháng làm việc, tham gia vào các dự án WordPress.\n• Bằng cấp: Không yêu cầu, quan trọng là năng lực.\n• Thành thạo lập trình PHP, có kiến thức về HTML/CSS, MySQL, JavaScript…\n• Đặc biệt am hiểu về mã nguồn WordPress (cài đặt, chỉnh sửa Theme, Plugin, Function,...).\n• Có đam mê với lập trình Web.\n• Ưu tiên ứng viên có khả năng Tiếng Anh và có kiến thức về SEO.\n\nQuyền lợi:\n• Mức Lương 8-11 triệu + Thưởng theo kết quả kinh doanh.\n• Được hưởng các chính sách phúc lợi, chế độ BHXH, BHYT, BHTN theo quy định.\n• Đề xuất tăng lương 6 tháng 1 lần.\n• Du lịch nghỉ dưỡng, teambuilding 1 năm 2 lần.\n• Văn phòng sạch sẽ, view đỉnh.\n• Môi trường làm việc năng động, trẻ trung, chuyên nghiệp, chủ yếu là GENZ.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 10, tòa BIDV 157 Cầu diễn, Bắc từ liêm, Bắc Từ Liêm.\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nThứ 7 được về sớm.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3179, 1404, 2, 'Developer (BA)', 'Mô tả công việc\n1. Hỗ trợ vận hành và giám sát hệ thống:\n- Vận hành, giám sát và đảm bảo hoạt động ổn định của các hệ thống quản lý chuỗi nhà thuốc, hệ thống quản lý kênh phân phối DMS, hệ thống kế toán.\n- Vận hành và bảo trì hệ thống website của công ty, đảm bảo truy cập ổn định và kịp thời xử lý các lỗi phát sinh.\n- Hỗ trợ người dùng nội bộ khi gặp các vấn đề liên quan đến hệ thống và công nghệ.\n- Là đầu mối trao đổi, phối hợp trong Ban Công nghệ và các đối tác phát triển để khắc phục sự cố, nâng cấp hệ thống.\n\n2. Vai trò BA (Business Analyst):\n- Thu thập và phân tích yêu cầu từ các phòng ban và người dùng nội bộ.\n- Xây dựng tài liệu yêu cầu nghiệp vụ (BRD) chuyển đối tác để phát triển các tính năng mới hoặc tự phát triển trong Ban Công nghệ.\n- Theo dõi tiến độ triển khai và hỗ trợ trong quá trình phát triển, kiểm tra và bàn giao tính năng mới.\n\n3. Tham gia phát triển tính năng:\n- Sử dụng Python để thu thập, xử lý dữ liệu từ các hệ thống thông qua API.\n- Sử dụng các nền tảng Javascript (như React) tham gia xây dựng hệ thống BI portal.\n- Phối hợp trong Ban công nghệ để phát triển hoặc nâng cấp các tính năng mới theo yêu cầu.\n\n4. Kiểm thử và đảm bảo chất lượng hệ thống:\n- Thực hiện test và kiểm thử các tính năng, đảm bảo chất lượng, tính ổn định của hệ thống trước khi bàn giao cho người dùng trong công ty.\n- Ghi nhận, báo cáo lỗi và theo dõi quá trình khắc phục, cải tiến tính năng từ đối tác hoặc Ban công nghệ.\n\n5. Nghiên cứu và ứng dụng công nghệ mới:\n- Thường xuyên ứng dụng các công cụ AI như ChatGPT, Gemini vào công việc để nâng cao hiệu quả vận hành và phân tích.\n- Luôn sẵn sàng học hỏi và cập nhật công nghệ mới để cải tiến và tối ưu hóa.\n\nYêu cầu ứng viên\n1. Kinh nghiệm và kỹ năng:\n- Tối thiểu 3-4 năm kinh nghiệm trong vai trò Developer/BA.\n- Có khả năng lập trình với Python để thu thập, xử lý dữ liệu.\n- Có khả năng lập trình nền tảng Javascript (như React).\n- Có khả năng test, kiểm thử và đảm bảo chất lượng hệ thống.\n- Hiểu biết về vận hành hệ thống website và các nền tảng hỗ trợ người dùng nội bộ.\n\n2. Kiến thức chuyên môn:\n- Có kinh nghiệm hoặc hiểu biết về các hệ thống như:\n   - Hệ thống bán hàng\n   - Hệ thống DMS (Hệ thống quản lý kênh phân phối)\n   - Hệ thống kế toán\n- Ưu tiên ứng viên có kinh nghiệm vận hành hoặc phát triển các hệ thống này.\n\n3. Kỹ năng mềm:\n- Kỹ năng thu thập, phân tích yêu cầu từ người dùng và các phòng ban.\n- Cẩn thận, tỉ mỉ và có tư duy logic trong xử lý vấn đề.\n- Kỹ năng giao tiếp tốt, khả năng hỗ trợ và đào tạo người dùng nội bộ hiệu quả.\n- Nhanh nhẹn, linh hoạt và sẵn sàng học hỏi.\n\n4. Ưu tiên:\n- Khả năng thích ứng nhanh với công nghệ mới và môi trường làm việc năng động.\n- Có kinh nghiệm triển khai ERP là một lợi thế.\n\nQuyền lợi\n- Mức lương: Cạnh tranh theo năng lực.\n- Được đào tạo và tiếp cận các công nghệ mới nhất.\n- Môi trường làm việc chuyên nghiệp, trực thuộc Ban Công nghệ.\n- Đầy đủ các chế độ phúc lợi: BHXH, BHYT, nghỉ phép năm và các chính sách khác của công ty.\n\nĐịa điểm làm việc\n- Hà Nội.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3180, 1259, 2, 'Mobile Developer', 'Phát triển và duy trì các ứng dụng di động trên nền tảng Android cho khách hàng.\nThiết kế giao diện người dùng thân thiện, tương thích nhiều thiết bị và phiên bản Android.\nTích hợp API, tối ưu hóa hiệu năng, thực hiện kiểm thử và đảm bảo chất lượng ứng dụng.\nTriển khai ứng dụng lên Google Play Store và hỗ trợ bảo trì sau phát hành.\nHợp tác chặt chẽ với đội nhóm (developer, designer, tester) để hoàn thành các yêu cầu dự án.\n\nYêu cầu ứng viên: \nTối thiểu 1 Kinh nghiệm với Android Developer: Kotlin/Java, MVVM, Jetpack, Material Design\nKinh nghiệm tích hợp RESTful API, xử lý dữ liệu an toàn và tối ưu hiệu năng ứng dụng.\nThành thạo Git, GitFlow và có kinh nghiệm với CI/CD là một lợi thế.\nHiểu biết về kiểm thử (Espresso, JUnit) và các mô hình phát triển phần mềm (Agile, Scrum).\nĐã từng phát triển ít nhất 1 ứng dụng hoàn chỉnh và triển khai lên Google Play Store (ưu tiên có portfolio).\nKỹ năng làm việc nhóm tốt, tư duy logic, chủ động, thông minh, chăm chỉ, trung thực.\n\nQuyền lợi: \nChế độ phúc lợi xã hội như: BHYT, BHXH,... theo quy định của luật Lao động\nHưởng chế độ phúc lợi hấp dẫn: Du lịch, sinh nhật, các hoạt động team building và các chế độ khác theo quy định của Công ty.\nĐược làm việc trong môi trường trẻ trung, năng động, có cơ hội phát triển nghề nghiệp phù hợp với năng lực và định hướng nghề nghiệp.\nĐược cấp máy tính và các thiết bị phục vụ công việc.\n\nĐịa điểm làm việc: \n- Thái Nguyên: Tổ 1, phường Phố Cò, thành phố Sông Công, TP Sông Công\n\nThời gian làm việc: \nThứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển: \nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Thái Nguyên', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3181, 1144, 2, 'Fullstack Developer', 'Mô tả công việc\n- Lập trình Frontend, Backend cho các dự án sản phẩm của Công ty và khách hàng.\n- Thiết kế và triển khai phần mềm đáp ứng các yêu cầu kinh doanh và công nghệ của khách hàng.\n- Quản lý và giám sát các nhân viên cấp dưới trong dự án phát triển phần mềm, đảm bảo các nhân viên hoàn thành công việc đúng tiến độ và đạt được chất lượng mong đợi.\n- Đưa ra các giải pháp về phần mềm đảm bảo hiệu suất và tính ổn định của hệ thống.\n- Đảm bảo chất lượng và hiệu suất của sản phẩm đạt được tiêu chuẩn và yêu cầu của khách hàng.\n- Tư vấn và đề xuất giải pháp công nghệ thông tin mới nhất để giúp công ty phát triển bền vững và cạnh tranh trong thị trường.\n- Tìm kiếm và áp dụng công nghệ mới nhất, đưa ra đánh giá và áp dụng chúng vào các dự án để tối ưu hóa hiệu suất và tính ổn định của hệ thống.\n\nYêu cầu ứng viên\n- Tổt nghiệp các trường ĐH, CĐ chuyên ngành CNTT, Khoa học máy tính hoặc chuyên ngành có liên quan.\n- Ít nhất 4 năm kinh nghiệm ở vị trí tường đương trở lên.\n- Thành thạo ít nhất 2 trong các ngôn ngữ sau:\n- Backend: C#, Java, Python, Ruby(RoR), PHP, Golang, NodeJS\n- Frontend: Java script (ReactJS/VueJS/AngularJS/...).\n- Có kinh nghiệm quản lý team 2 member trở lên.\n- Hiểu biết và có kinh nghiệm thiết kế, triển khai, cài đặt cloud service (AWS, Azure, ...), micro servive\n- Có các chứng chỉ phát triển phần mềm liên quan.\n- Tiếng anh giao tiếp tốt.\n\nQuyền lợi\n- Thu nhập Upto 40M\n- Thử việc 2 tháng full 100% lương\n- Tham gia BHXH, BHYT, BHTN theo quy định luật lao động\n- Tham gia BH sức khoẻ VBI\n- Review lương 2 lần/năm\n- Lương tháng 13, thưởng các dịp Lễ, Tết, Hiếu hỉ, Sinh nhật,...\n- Hỗ trợ chi phí thì chứng chỉ JLPT, ISTQB, AWS,...\n- Phụ cấp chi phí gửi xe\n- Phụ cấp thâm niên, thưởng project xuất sắc\n- Quỷ cầu lông, bóng đá hằng tuần\n- Du lịch, nghỉ dưỡng hằng năm theo chính sách của công ty\n- Khám sức khỏe định kỳ hàng năm\n- Cơ hội thăng tiến rõ ràng\n- Cơ hội đến các nước đối tác làm việc: Nhật Bản, Hàn Quốc, Singapore, Úc\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Lầu 10 Mekong Tower, 235 Cộng Hoà, Phường 13, Tân Bình\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3182, 1229, 2, 'Backend Developer', 'Lập trình viên Backend (Backend Developer) chịu trách nhiệm xây dựng, phát triển và duy trì các thành phần phía server của ứng dụng web, mobile hoặc hệ thống phần mềm. Công việc chính của BE Developer là xử lý logic nghiệp vụ, truy xuất cơ sở dữ liệu, quản lý API và tối ưu hóa hiệu suất hệ thống.\n\n2.1 Nhiệm vụ chính\n\n- Thiết kế và phát triển API: Xây dựng các API RESTful hoặc GraphQL để phục vụ dữ liệu cho frontend và các hệ thống khác.\n- Quản lý cơ sở dữ liệu: Thiết kế, tối ưu truy vấn SQL (PostgreSQL, MySQL, SQL Server) hoặc NoSQL (MongoDB, Firebase, Redis).\n- Xây dựng hệ thống xử lý dữ liệu: Tối ưu logic nghiệp vụ, thực hiện các tác vụ batch, xử lý hàng đợi (queue) bằng Redis, RabbitMQ, BullMQ.\n- Quản lý bảo mật và phân quyền: Xử lý xác thực người dùng (JWT, OAuth, OpenID Connect), bảo vệ dữ liệu và chống các cuộc tấn công như SQL Injection, XSS, CSRF.\n- Tích hợp API với các hệ thống khác: Làm việc với các hệ thống thanh toán (PayPal, Stripe, VNPAY), email (SendGrid, Mailgun), SMS (Zalo ZNS),...\n- Quản lý hiệu suất và tối ưu hệ thống: Caching (Redis, Memcached), load balancing, tối ưu tốc độ truy vấn, giảm độ trễ API.\n- Triển khai và vận hành hệ thống: Sử dụng Docker, Kubernetes, CI/CD (GitHub Actions, GitLab CI).\n- Xử lý lỗi và gỡ lỗi: Phân tích log, debugging hệ thống, xử lý lỗi runtime.\n- Ứng dụng AI hỗ trợ trong coding: code completion, debug, refactor, unit test…\n\n2.2. Trách nhiệm\n\n- Đảm bảo chất lượng mã nguồn: Viết code sạch, dễ bảo trì, tuân thủ các tiêu chuẩn lập trình và best practices.\n- Thực hiện theo quy trình Agile/Scrum: Tham gia họp sprint planning, daily stand-up, review, và retrospective để đảm bảo tiến độ và chất lượng sản phẩm.\n- Nghiên cứu và áp dụng công nghệ mới: Cập nhật xu hướng công nghệ, đề xuất giải pháp cải tiến hiệu suất và tối ưu hệ thống.\n- Xử lý sự cố kỹ thuật và bảo trì hệ thống: Giám sát, phát hiện lỗi, tối ưu hiệu suất và đảm bảo hệ thống vận hành ổn định.\n\n- Phối hợp với các thành viên trong nhóm: Làm việc chặt chẽ với frontend, QA, product owner để phát triển và triển khai sản phẩm hiệu quả.\n\nYêu cầu ứng viên\n\nChúng tôi cần những người tài năng để thảo luận, định hướng giải pháp, giải quyết vấn đề, tập trung vào khách hàng và tin rằng bất kỳ thử thách nào cũng có thể được thu nhỏ với tư duy, công cụ và thái độ đúng đắn. Chúng tôi đang tìm kiếm:\n\n1. Trình Độ & Kinh Nghiệm\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Phần mềm, Khoa học Máy tính hoặc lĩnh vực liên quan.\n- Tối thiểu 3 năm kinh nghiệm làm Backend Developer với một trong các ngôn ngữ sau:\n- Node.js (NestJS, ExpressJS)\n- C# (.NET Core 5+)\n- Có kinh nghiệm xây dựng và triển khai hệ thống Microservices.\n\n2. Kiến Thức & Kỹ Năng Kỹ Thuật\n- Thành thạo Docker, Linux, Git, CI/CD.\n- Hiểu và triển khai tốt RESTful API, WebSocket, tối ưu hiệu suất API.\n- Kinh nghiệm làm việc với cơ sở dữ liệu SQL & NoSQL, bao gồm:\n- PostgreSQL, MySQL, MongoDB\n- Viết và tối ưu truy vấn, cải thiện hiệu suất database.\n- Tích hợp hệ thống bên thứ ba: Firebase, cổng giao hàng, cổng thanh toán (Stripe, PayPal, VNPAY).\n- Có kinh nghiệm xử lý Task Scheduler, Background Job, Queue Processing (BullMQ, RabbitMQ, Kafka).\n- Ưu tiên ứng viên có kinh nghiệm làm việc trên nền tảng SaaS.\n- Khả năng thiết kế và đề xuất giải pháp kiến trúc hệ thống phù hợp với yêu cầu dự án.\n- Lợi thế nếu có kinh nghiệm với Python (Flask, Django).\n\n3. Hiểu Biết Về Bảo Mật & Quy Trình Phát Triển\n- Nắm vững các tiêu chuẩn bảo mật API & bảo vệ dữ liệu (JWT, OAuth2, OWASP Top 10).\n- Có hiểu biết về quy trình phát triển phần mềm Agile/Scrum, tham gia Sprint Planning, Daily Standup, Code Review.\n\n3.2. Kỹ năng mềm\n- Khả năng tự học nhanh và thích nghi với công nghệ mới, sẵn sàng cập nhật xu hướng.\n- Chủ động trong công việc, có tinh thần trách nhiệm cao, cam kết với tiến độ và chất lượng.\n- Kỹ năng làm việc nhóm tốt, sẵn sàng hỗ trợ đồng đội để đạt mục tiêu chung.\n- Đam mê công nghệ, linh hoạt trong việc tiếp cận và sử dụng các công cụ, framework mới.\n\nQuyền lợi\n\n- Thu nhập cạnh tranh, tùy thuộc vào kinh nghiệm và khả năng\n- Chế độ chính sách lương, thưởng, BHXH, BHYT, BHTN,... đầy đủ.\n- Có cơ hội trở thành một trong những vị trí key của Công ty \n- Môi trường làm việc trẻ trung, năng động và chuyên nghiệp\n- Được đào tạo kỹ năng, công nghệ mới Chuyển đổi số, AI,..  \n- Được huấn luyện đào tạo phát triển năng lực (Kiến thức, kỹ năng, thái độ, thói quen) và định hướng phát triển sự nghiệp để thành công.\n\nĐịa điểm làm việc\n\n- Hồ Chí Minh: Tòa nhà SBI, Đường 03, CVPM Quang Trung, P. Tân Chánh Hiệp, Quận 12\n\nThời gian làm việc\n\n- Thứ 2 - Thứ 6 (8h00 -17h00)\n- Thứ 7 (8h00 -12h00) - Online\n\nCách thức ứng tuyển\n\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3183, 1130, 2, 'Middle Mobile Developer (IOS/Flutter)', 'Mô tả công việc\n- Thiết kế, xây dựng và tối ưu kiến trúc hệ thống mobile (IOS hoặc Flutter).\n- Refactor toàn bộ codebase cũ để nâng cao tính maintainable, scalability và performance.\n- Tối ưu hiệu suất, giảm thiểu lỗi, nâng cao trải nghiệm người dùng.\n- Xây dựng các mô-đun core, SDK tái sử dụng cho hệ sinh thái sản phẩm học tập.\n- Làm việc chặt chẽ với Product Manager, Design, Backend để định hướng chức năng và trải nghiệm của sản phẩm.\n- Góp phần vào roadmap sản phẩm mobile, đảm bảo tiến độ & chất lượng kỹ thuật.\n- Đề xuất công nghệ, framework, quy trình phù hợp cho từng giai đoạn phát triển.\n- Hỗ trợ kỹ thuật và mentoring cho các bạn Developer trong team mobile.\n- Xây dựng quy chuẩn coding, review code, đào tạo kỹ năng phát triển sản phẩm mobile.\n- Định hướng phát triển cá nhân, thúc đẩy tinh thần làm việc nhóm.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc liên quan.\n- Có 3-5 năm kinh nghiệm phát triển mobile. Thành thạo một hoặc nhiều nền tảng: Swift (iOS) hoặc Flutter (Dart)\n- Kinh nghiệm thiết kế kiến trúc app (MVVM, Clean Architecture), quản lý module, xử lý hiệu năng & nợ kỹ thuật.\n- Có ít nhất 2 năm kinh nghiệm làm việc trong công ty product.\n- Hiểu sâu về testing, CI/CD, deployment mobile.\n- Ưu tiên có kinh nghiệm quản lý team, làm việc với team size từ 5 người trở lên là một điểm cộng.\n- Kinh nghiệm làm việc với sản phẩm lớn có hàng trăm ngàn đến hàng triệu người dùng.\n- Tư duy sản phẩm và kỹ năng làm việc đa chức năng với các team (Design, PM, Marketing,...).\n- Kinh nghiệm quản lý team kỹ thuật hoặc định hướng trở thành Head of Mobile trong tương lai gần.\n- Đã làm việc trong môi trường startup hoặc product-first.\n- Kỹ năng trình bày, giao tiếp tốt và khả năng tự học mạnh.\n\nQuyền lợi\n1. Chế độ lương, thưởng, thu nhập:\n- Thu nhập cạnh tranh: Lương cứng (thỏa thuận) + phụ cấp hàng tháng + thưởng dự án Lương tháng 13.\n- Đánh giá, xét tăng lương 1 lần/năm theo năng lực.\n2. Chế độ phúc lợi:\n- Được đóng đầy đủ về các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của Nhà nước.\n- Hàng năm CBNV được tham gia khám sức khỏe định kỳ tại các bệnh viện lớn.\n- Tham gia BHXH sau thử việc, 12 ngày phép năm.\n- Quà sinh nhật, chính sách thăm hỏi, Chương trình Happy Time, Vinh danh, Ghi nhận, Team building, du lịch định kỳ.\n- Chính sách thưởng dự án, thưởng KPI, thưởng các dịp Lễ - Tết...\n- Học miễn phí các sản phẩm ngôn ngữ của công ty.\n3. Cơ hội phát triển bản thân\n- Có cơ hội thử sức trong lĩnh vực công nghệ tiên tiến, hiện đại nhất.\n- Môi trường product đi sâu chuyên môn về mobile app, áp dụng công nghệ mới.\n- Mở rộng góc nhìn ngoài chuyên môn, phối hợp với các phòng ban khác marketing, sales, chăm sóc khách hàng và khách hàng.\n- Được thử sức với các dự án hấp dẫn, thử thách đủ lớn trong và ngoài nước.\n- Được trao quyền sáng tạo với đam mê của tuổi trẻ.\n- Cơ hội học hỏi từ các chuyên gia hàng đầu, lãnh đạo và đồng nghiệp ưu tú.\n- Cơ hội tham gia các khóa đào tạo, trau dồi kỹ năng, chuyên môn để phát triển toàn diện.\n- Môi trường làm việc trẻ, năng động, nhiều cơ hội thăng tiến, luôn được hỗ trợ bởi Sếp và đồng nghiệp.\n- Văn hóa Tận tâm, Tinh thần đồng đội, Lắng nghe, Chia sẻ được cam kết được thống nhất từ Ban lãnh đạo xuống toàn thể Cán bộ nhân viên - là môi trường lý tưởng để nhân sự trẻ và tài năng được phát triển năng lực bản thân.\n- Thời gian làm việc: 8h - 17h30, từ thứ 2 - thứ 6.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3184, 1299, 2, 'Mobile Developer', 'We are looking for an experienced Mobile App Developer to join our team. As a Mobile App Developer, you will be responsible for the development and maintenance of high-quality mobile applications. You will collaborate with cross-functional teams to define, design, and ship new features and functionality.\n- Develop and maintain high-quality mobile applications for iOS and Android platforms.\n- Collaborate with cross-functional teams to define, design, and ship new features and functionality.\n- Identify and fix bugs, and improve application performance.\n- Conduct thorough testing of mobile applications to ensure high quality and user satisfaction.\n- Stay up-to-date with emerging trends and technologies in mobile development.\n- Participate in code reviews and contribute to a positive and collaborative team culture.\n\nRequirements:\n- 1 years of experience in mobile application development, with a strong portfolio of applications developed.\n- Strong experience in Swift/Objective-C or Java/Kotlin programming languages.\n- Proficiency in using popular mobile app development frameworks such as React Native.\n- Understanding of RESTful APIs, JSON, and other web technologies.\n- Experience with version control systems such as Git or SVN.\n- Excellent problem-solving skills and attention to detail.\n- Ability to work independently and in a team environment.\n- Good communication and interpersonal skills.\n- Intermediate or higher graduation.\n\nBenefits:\n- Opportunity to work with an experienced team and gain valuable experience in testing across various platforms.\n- Performance-based bonuses twice a year.\n- Training on the Scrum framework and how to write effective test cases.\n- Opportunities for professional growth and improvement of skills.\n- Work in an open, friendly, and professional environment.\n- Enrollment in life insurance and premium health insurance plans after a period of long-term commitment to our company.\n\nWork location:\n- Khánh Hoà: Công ty WIDOSOFT, 23 Thái Nguyên, Phước Tân, Nha Trang, TP Nha Trang.\n\nApplication method:\nCandidates submit applications online by clicking \'Apply\' just below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khánh Hoà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3185, 1288, 2, 'Junior Java Developer', 'Mô tả công việc\n- Hệ sinh thái phần mềm của Softdreams đang có hơn 300.000 doanh nghiệp sử dụng tại Việt Nam và có tốc độ tăng trưởng top 1 cả nước.\n- Xây dựng ứng dụng Saas bán hàng (EasyPOS), Kế toán (EasyBooks), Chữ ký số (EasyCA). Các ứng dụng đều hướng đến việc cung cấp giải pháp phần mềm Saas mạnh mẽ, cho 5 triệu người dùng cá nhân, hộ kinh doanh, doanh nghiệp.\n- Tham gia nghiên cứu, phát triển các ứng dụng, hệ thống dựa trên công nghệ Big Data.\n- Có cơ hội tham gia trong các công việc thiết kế kiến trúc hệ thống, tối ưu hệ thống Microservice/CSDL.\n- Tham gia phát triển trong nhiều thành phần ở kiến trúc tổng thể của hệ thống phần mềm ( Frontend - Angular/ Backend/ Services).\n- Phát triển phần mềm theo mô hình Agile, áp dụng cả Kanban và Scrum.\n\nYêu cầu ứng viên\n- Kinh nghiệm: Có ít nhất 2 năm kinh nghiệm về Java/Angular.\n- Có kiến thức vững chắc về truy vấn với CSDL (SQL hoặc NoSQL). Ứng viên có kinh nghiệm về SQL Server và MongoDB là lợi thế.\n- Rất ưu tiên ứng viên có tư duy nền tảng tốt và sẵn sàng tham gia vào các bài toán tối ưu lớn.\n- Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực tương đương (PM bán hàng/PM kế toán/ERP).\n- Có kinh nghiệm làm việc nhóm theo mô hình Agile.\n\nQuyền lợi\n- Thu nhập: 12,000,000-20,000,000/tháng + trợ cấp (700-900k/tháng)\n- Môi trường công nghệ trẻ, có cơ hội đề xuất, phát triển ý tưởng & thăng tiến cao\n- Xét tăng lương 2 lần/năm, thưởng tháng lương 13,14; thưởng lễ tết, sinh nhật\n- Được học hỏi: SDS tạo điều kiện cho mọi người rèn luyện ở mọi lúc mọi nơi, đồng hành và thúc đẩy phát triển cá nhân từ đồng nghiệp và quản lý giàu kinh nghiệm\n- Được thử sức trong một môi trường làm việc trẻ trung, cởi mở với chính sách đãi ngộ tốt\n- Du lịch hằng năm với địa điểm hấp dẫn, thường xuyên tổ chức các hoạt động team building gắn kết cộng đồng, các hoạt động vui chơi giải trí cho nhân viên.\n- Tham gia chương trình hàng tháng, các buổi liên hoan, sinh nhật hàng tháng, tiệc noel, tất niên,…\n- Được tham gia BHXH, BHYT, BHTN, chế độ nghỉ phép theo luật hiện hành.\n\nĐịa điểm làm việc\n- Hà Nội: số 8 Phạm Hùng, Mễ Trì, Nam Từ Liêm\n- Hà Nội: Cầu Giấy\n- Hà Nội: Thanh Xuân\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3186, 1319, 2, 'Kỹ Sư Lập Trình Nhúng', 'Mô tả công việc\n- Tham gia phát triển và tối ưu firmware cho các thiết bị nhúng thuộc lĩnh vực An ninh Quốc phòng (vệ tinh, truyền thông vô tuyến, radar…).\n- Tham gia nghiên cứu áp dụng/cập nhật công nghệ mới cho các sản phẩm.\n- Tham gia khảo sát, đánh giá các sản phẩm thương mại, và đề xuất phương án nội địa hóa/phát triển sản phẩm tương đương.\n- Thiết kế và triển khai các module phần mềm điều khiển thiết bị phần cứng (MCU, FPGA, RF, cảm biến, truyền thông...).\n- Tích hợp và kiểm thử hệ thống nhúng: truyền nhận dữ liệu, giao tiếp UART, SPI, I2C, CAN, RS485, Ethernet...\n- Đánh giá linh kiện và phối hợp cùng nhóm thiết kế phần cứng để tối ưu giải pháp sản xuất nội địa.\n\nYêu cầu ứng viên\n1. Trình độ & Kinh nghiệm\n- Tốt nghiệp đại học các ngành: Công nghệ thông tin, Khoa học máy tính, Điện – Điện tử, Tự động hóa, Viễn thông… hoặc chuyên ngành liên quan.\n- Có tối thiểu 02 năm kinh nghiệm lập trình hệ thống nhúng (firmware/hệ điều hành nhúng).\n\n2. Kỹ năng & chuyên môn\n- Thành thạo ít nhất một trong các ngôn ngữ lập trình: C/C++, Python, Shell Script.\n- Có kinh nghiệm làm việc với các nền tảng MCU (STM32, ESP32, NXP…), hoặc SoC, RTOS (FreeRTOS, Zephyr…).\n- Hiểu biết tốt về cấu trúc hệ thống nhúng, lập trình giao tiếp ngoại vi (SPI, I2C, UART…).\n- Ưu tiên ứng viên có kinh nghiệm làm việc với thiết bị trong các hệ thống: vệ tinh, truyền thông VHF/UHF, radar, tín hiệu số….\n\n3. Tư duy & năng lực khác\n- Tư duy logic, chủ động giải quyết vấn đề.\n- Có khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Sử dụng tốt tài liệu kỹ thuật tiếng Anh.\n\nQuyền lợi\n- Mức lương cạnh tranh, thưởng theo dự án và năng lực.\n- Công ty đóng 100% BHXH ngay khi ký HĐLĐ chính thức.\n- Cơ hội làm việc trong lĩnh vực công nghệ cao phục vụ Quốc phòng – An ninh.\n- Tham gia các khóa đào tạo chuyên môn sâu (nhúng, FPGA, truyền dẫn…).\n- Cơ hội phát triển thành trưởng nhóm kỹ thuật theo lộ trình.\n- Tham gia các khóa Đào tạo trong và ngoài nước nâng cao nghiệp vụ chuyên môn.\n- Thưởng tháng 13, 14 thưởng các ngày lễ, tết,…\n- Phụ cấp ăn trưa 40.000 VNĐ/ngày.\n- Khám sức khỏe định kỳ, teambuiding, du lịch, các sự kiện nội bộ.…\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Zodiac, ngõ 19 Duy Tân, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3187, 1304, 2, 'Middle Backend Developer (Java)', 'Mô tả công việc\n- In charge of programming, error checking & reporting to line manager.\n- Participate in big Banking, Finance & Insurance projects.\n- Participate in developing projects using Java & other technologies.\n- Solutions: Banking and Finance, Insurance, Cross industries: (Paperless; CheckinPro; BPM Hub; Napas ACH; CIC Host to Host; DMS; eP2P; eInvoice; Agency Portal; LDMS products; eRecruitment; ConstructionEMS).\n- Work closely with Developers and PMs/Directors.\n- Solving issues and developing workarounds and alternative solutions.\n- Overseeing deployments and new releases.\n- Supporting training and motivating team members.\n\nYêu cầu ứng viên\n- Bachelor/ college’s degree in Computer Science, Information Technology or equivalent.\n- Knowledge/experience in Finance, Banking & Enterprise.\n- 3+ years of experience in Java development on Linux/Windows platform.\n- Experience in Java frameworks: Spring (Spring MVC, Spring Boot, Spring Security), Hibernate.\n- Experience in Web Service (RESTful, SOAP) and knowledge in queue processing (Active MQ, IBM MQ).\n- Experience in Java Application Servers, Database Servers.\n- Proficient in version control systems: Git, SVN.\n- Good knowledge of an objective oriented language (Java)\n- Good knowledge of web/application containers (Apache Tomcat, JBoss, IBM WebSphere ...) and web/application deployment.\n- Good skill at MS SQL Server programming (stored procedure, function, job, trigger, view).\n- Good skill in database design, database management, particularly MS SQL.\n- Solid understanding of the software development life cycle, Agile Scrum.\n- Working knowledge of HTML5, CSS3, React, Flutter, and JavaScript a plus.\n- Ability to work in a team and work independently.\n- Flexible, dynamic attitude and reliable.\n\nQuyền lợi\n- Competitive salary and benefits.\n- Working time: 8:00AM - 05:30PM, Monday – Friday.\n- 12 days of annual leave + 3 days of sick leave + 1 day of birthday per year.\n- Participated in social insurance, unemployment insurance, health insurance and full policies according to the labor law.\n- 13th month salary & bonus policies, allowances at the Company.\n- UNIT-Care health care insurance by level.\n- Salary increases according to company regulations or unexpected salary raise in case of outstanding ability.\n- Professional and dynamic working environment, unlimited promotion opportunities.\n- Opportunity to participate in many large projects in Vietnam & abroad.\n- Work on the latest technology platform.\n- Join in company trip, teambuilding & community activities.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 374 Võ Văn Tần, phường 5, Quận 3\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3188, 1146, 2, 'Junior Back-End (.Net) - Lĩnh Vực Edtech - Mức Lương Up To 15M', 'Mô tả công việc:\n- Tham gia phát triển hệ thống học trực tuyến trên nền tảng .NET (.NET Framework, .NET Core) phục vụ hàng trăm nghìn người dùng\n- Xây dựng API và xử lý nghiệp vụ phía server, đảm bảo hiệu năng và độ ổn định cao\n- Tối ưu hệ thống để đáp ứng nhu cầu sử dụng đồng thời lớn, cải thiện tốc độ và khả năng mở rộng\n- Phối hợp với team BA, Front-end và QA để phân tích yêu cầu, thiết kế giải pháp và triển khai tính năng mới\n- Nghiên cứu – ứng dụng công nghệ mới, hỗ trợ phân tích dữ liệu người dùng, áp dụng Big Data, caching, tối ưu cơ sở dữ liệu...\n- Tham gia quy trình Agile/Scrum, đóng góp ý tưởng cải tiến liên tục sản phẩm và quy trình làm việc.\n\nYêu cầu ứng viên:\n- Có ít nhất 1 năm kinh nghiệm trong các dự án .NET.\n- Có kinh nghiệm công nghệ dữ liệu nâng cao của Microsoft: ADO.NET, .NET Core, ASP.NET (Core), MVC, Entity Framework (Core), Linq, SQL Server.\n- Có khả năng triển khai & tối ưu hóa các công nghệ .NET Server-side thành thạo.\n- Có kinh nghiệm thiết kế các API RESTful với ASP.NET.\n- Rất tốt trong việc hiểu và áp dụng các Mẫu thiết kế / Nguyên tắc thiết kế.\n- Thành thạo trong việc duyệt mã, tái cấu trúc mã.\n- Có kiến ​​thức cơ bản về HTML, CSS, JavaScript là một lợi thế.\n- Có kinh nghiệm làm việc trong môi trường Phát triển phần mềm Agile / Scrums.\n\nQuyền lợi:\n- Mức lương (gross): up to 15 triệu/tháng\n- Thưởng sinh nhật, thưởng các dịp Lễ, Tết trong năm\n- Chế độ BHXH, BHYT, BHTN đầy đủ ngay sau khi ký HĐ chính thức\n- Khám sức khoẻ định kỳ hàng năm\n- Trang bị máy tính hiện đại phục vụ công việc\n- Quỹ Team Building lên tới 2.400.000 VNĐ/người/năm\n- Du lịch nghỉ dưỡng hàng năm\n- Trà chiều với bánh, hoa quả và đồ ăn vặt miễn phí hàng tuần\n- Cơ hội tiếp cận với các doanh nghiệp, dự án lớn, xu hướng công nghệ và nền tảng mới nhất\n- Được tham gia các lớp đào tạo, khóa học chuyên môn để phát triển kỹ năng\n- Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung & trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc\n- Học tiếng Anh hoàn toàn miễn phí & ưu đãi học phí cho người thân.\n\nĐịa điểm làm việc:\n- Hà Nội: 35 Lạc Trung, Hai Bà Trưng\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:20)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3189, 1181, 2, 'Nhân Viên Lập Trình Nhúng', 'Mô tả công việc\n- Tham gia phát triển phần mềm điều khiển và quản lý oạt động của vệ tinh cỡ nhỏ\n- Thiết kế và lập trình phần mềm nhúng cho hệ thống OBC (On-Board Computer)\n- Giao tiếp với các cảm biến và module ngoại vi (IMU, GPS, camera, transceiver RF, v.v.)\n- Phát triển giao thức liên lạc giữa các module nội bộ (I2C, SPI, UART) và truyền thông mặt đất\n- Tối ưu hóa hiệu suất, bộ nhớ, và mức tiêu thụ năng lượng cho phần mềm nhúng\n- Viết tài liệu kỹ thuật và hỗ trợ thử nghiệm tích hợp hệ thống (SIT) và kiểm tra môi trường (TVAC, Vibration…)\n- Trao đổi chi tiết hơn khi phỏng vấn.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học chính quy loại Khá trở lên các chuyên ngành Kỹ thuật như Công nghệ thông tin, Hàng không Vũ trụ, Khoa học máy tính, Toán – tin, Điện tử viễn thông,.. \n- Trình độ tiếng Anh tương đương tối thiểu 550 điểm Toeic.\n- Hiểu về hệ thống nhúng, có kinh nghiệm lập trình C/C++ cho vi điều khiển (ARM, STM32, ATmega, ESP32, v.v.)\n- Có khả năng đọc hiểu sơ đồ mạch điện và datasheet thiết bị\n- Thành thạo các giao thức truyền thông phổ biến (I2C, SPI, UART,…)\n- Có khả năng sử dụng MATLAB/Simulink để mô phỏng và thiết kế thuật toán điều khiển nhúng (control systems, signal processing, code generation)\n- Ưu tiên:\n- Tiếng Anh có thể làm việc được với chuyên gia nước ngoài\n- Có kinh nghiệm làm việc với RTOS hoặc các hệ điều hành nhúng\n- Có hiểu biết về hệ thống định thời (watchdog, scheduler, RTC, low-power modes…)\n- Biết sử dụng công cụ mô phỏng và kiểm thử phần mềm nhúng\n- Kỹ năng debug tốt trên phần cứng thật (oscilloscope, logic analyzer…)Tiếng Anh tốt (có thể trao đổi, tham gia đào tạo, học tập với chuyên gia nước ngoài)\n\nQuyền lợi\n- Lương: hấp dẫn, tăng lương theo thâm niên công tác.\n- Thu Nhập lên Tới 30 triệu\n- Thưởng: có nhiều đợt thưởng trong năm. Thưởng lễ 30-4, thưởng ngày truyền thống, thưởng 6 tháng đầu năm, thưởng ngày thành lập công ty, thưởng Tết Dương, thưởng Tết âm (thưởng năm) và các giải thưởng cá nhân khác: Tiên tiến, xuất sắc, tiềm năng, có cố gắng.... \n- Hỗ trợ tiền ăn trưa tại căng tin công ty.\n- Có chế độ chăm sóc y tế cho nhân viên và gia đình, du lịch 1 năm/1 lần (trong nước hoặc nước ngoài) và tham gia các hoạt động vui chơi giải trí khác (sinh nhật công ty, sinh nhật các thành viên...)\n- Có cơ hội được làm việc với đối tác nước ngoài, công tác và đào tạo ở nước ngoài\n- Các chế độ BHXH, nghỉ thứ 7, chủ nhật, chế độ phép đầy đủ theo quy định \n\nĐịa điểm làm việc\n- Hà Nội: Số 37 Phố Thi Sách, Hai Bà Trưng\n- Hà Nội: 15 Trần Xuân Soạn, Hai Bà Trưng\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3190, 1473, 2, 'Android Engineer', 'As an Android Software Engineer, you will work on building scalable, high-performance applications with a focus on performance optimization and clean architecture.\n\nImplement Android (Kotlin) and Flutter components of our SaaS product\nDrive the entire mobile software lifecycle, from prototyping to commercialization and post-launch support\nBuild clean, well-tested, and maintainable code that aligns with our cross-platform architecture and performance goals\nParticipate in design reviews, code reviews, and contribute to cross-functional discussions and continuous improvement\nPartner with Product, Design, and Backend teams to deliver quality Android applications\n\nFor Senior:\nPropose architecture and design reviews to ensure high standards in software quality\nSet a high technical standard for the team through code and design reviews\nEnhance engineering processes, including sprint planning, stand-ups, and long-term planning\nMentor junior/middle engineers, foster growth, and technical skill development within the team\n\nYêu cầu ứng viên\n\nBachelor’s Degree in Computer Science / Information Technology / Software Development or related fields\n\nMust have:\n1+ year of experience in Kotlin and Flutter cross-platform technologies\nHands-on experience in independently completing or participating in large-scale Android projects\nGood understanding of framework principles, and practical experience in performance optimization for low-end device models, including but not limited to startup, memory, network, etc\nUnderstand Jetpack components, familiar with annotation frameworks, and have practical experience\nGood/Fluent English communication is mandatory\n\nNice to have:\nPractical experience in catering apps, with architecture ability preferred\nExperience with hardware knowledge reserves and practical experience (including but not limited to printers, external card machines, USB/Bluetooth communication) is preferred\n\nQuyền lợi\n\nWe are a multinational, product-driven company specializing in proprietary POS solutions — developing in-house and delivering directly to our worldwide customers.\n\nRecognition & Rewards:\n13th-month salary\nLoyalty Bonus programs\nBiannual Performance and Salary review\n\nComprehensive Insurance Coverage:\nFull government public insurance contributions based on gross salary\nPremium health insurance\nAnnual health check\n\nClear career development and growth structure; Training sessions and Learning workshops\n14 days of annual leave and one additional day of leave for every year of service\nLaptop/MacBook and top-notch facilities are provided based on each role\nAgile/Scrum-based internal workflows for efficient and collaborative development\nCompany trips, parties and regular team-building activities; Weekly happy hour, coffee, snacks, and board games\nOverseas travel opportunities based on the individual performance and policies for each evaluation period\n\nWorking Environment & Culture:\nInternational Workplace: English-speaking environment\nPositive and Open-Minded Culture: Engineers are encouraged to propose innovative solutions that enhance productivity and code quality\n1-on-1 Mentorship: Monthly coffee sessions with managers offer personalized feedback, goal setting, and career development opportunities\nFlexible Working Hours: Promote work-life balance and individual productivity\n\nĐịa điểm làm việc\n\nHồ Chí Minh: Quận 4\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3191, 1423, 2, 'Lập Trình Viên PHP', 'Mô tả công việc:\nLập trình website bằng CMS Wordpress dựa trên yêu cầu hoặc thiết kế có sẵn.\nLập trình plugin tính năng theo yêu cầu phát sinh.\nPhát triển các tính năng mới và cải tiến các tính năng của website.\nChỉnh sửa các lỗi liên quan tới giao diện, chức năng website.\nKiểm tra và khắc phục khi website bị hack, nhiễm mã độc.\n\nYêu cầu ứng viên:\nTốt nghiệp Đại học, Cao đẳng chuyên ngành công nghệ thông tin.\nCó từ 02 năm kinh nghiệm phát triển website trên nền tảng WordPress, ngôn ngữ PHP.\nThành thạo HTML/Javascript/jQuery/CSS/AJAX, CMS WordPress.\nCó kiến thức hệ quản trị cơ sở dữ liệu MySql là một lợi thế.\nƯu tiên có kinh nghiệm tiếp xúc và làm việc với các nền tảng thiết kế website (PHP framework như laravel, codeigniter; các CMS wordpress, joomla,..)\nTư duy logic và khả năng Research tốt.\n\nQuyền lợi:\nCơ hội thăng tiến, gắn bó và làm việc lâu dài tại công ty.\nMôi trường làm việc năng động, cơ hội phát triển nghề nghiệp.\nĐược hưởng đầy đủ các chế độ dành cho người lao động theo quy định pháp luật hiện hành (BHYT, BHXH, BHTN…) Thưởng tháng lương thứ 13, 12 ngày phép năm, thưởng Lễ/tết (theo quy định công ty), lương thưởng bảo hiểm trả/đóng đúng hạn, thưởng cuối năm, thưởng Nhân viên xuất sắc, thưởng thâm niên…\nTham gia và tận hưởng các hoạt động, sự kiện nội bộ, Team Building, du lịch, … của công ty.\n\nĐịa điểm làm việc:\n- Bình Dương: 4/567 Tổ 10, khu phố Hoà Lân 1, phường Thuận Giao, Thuận An.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\nThứ 7 (từ 08:00 đến 11:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3192, 1131, 2, '.Net Engineer', 'Mô tả công việc: \n- Phát triển và bảo trì các ứng dụng Web sử dụng C# và ASP.NET MVC.\n- Tham gia vào quá trình thiết kế, xây dựng và tối ưu hóa hệ thống Web App.\n- Làm việc với cơ sở dữ liệu SQL Server.\n- Phối hợp với các thành viên trong nhóm để đảm bảo tiến độ và chất lượng dự án.\n- Xử lý lỗi, tối ưu hiệu suất và cải thiện trải nghiệm người dùng.\n\nYêu cầu ứng viên: \n- Tối thiểu 2 năm kinh nghiệm, trong đó có 1 năm phát triển Web App bằng C#.\n- Thành thạo ASP.NET MVC, ưu tiên ứng viên chuyên về phát triển Web.\n- Có kinh nghiệm làm việc với SQL Server, Entity Framework.\n- Biết sử dụng HTML, CSS, JavaScript, jQuery là lợi thế.\n- Có tư duy logic, kỹ năng giải quyết vấn đề tốt.\n- Chủ động, có trách nhiệm với công việc.\n\nQuyền lợi: \n- Mức lương cạnh tranh. \n- Lương tháng 13.\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop….\n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN).\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau.\n- Làm việc thứ 2 đến thứ 6, Nghỉ Thứ 7, Chủ nhật.\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc.\n- Khám sức khỏe định kỳ 1 lần/năm.\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n\nĐịa điểm làm việc: \n- Hà Nội: Dịch Vọng Hậu, Cầu Giấy.\n\nThời gian làm việc: \n- Thứ 2 - Thứ 6 (từ 00:00 đến 00:00).\n\nCách thức ứng tuyển: \n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3193, 1150, 2, 'Frontend Developer', 'Mô tả công việc:\n- Tham gia quá trình thiết kế, phát triển giao diện cho các sản phẩm của công ty (chủ yếu Web based).\n- Xây dựng, phát triển và tối ưu các chức năng của sản phẩm.\n- Sáng tạo, đề xuất các cải tiến mới trong quá trình phát triển product.\n\nYêu cầu ứng viên:\n- Có ít nhất 2 năm làm việc thực tế với Front-end (Trong đó ít nhất hơn 1 năm làm Reactjs, biết Nextjs là điểm cộng).\n- Thành thạo JavaScript (ES6+), HTML, CSS.\n- Kinh nghiệm thao tác DOM và xử lý sự kiện trình duyệt.\n- Có khả năng làm việc độc lập, xây dựng được nền tảng base cho app.\n- Hiểu biết về các kỹ thuật server push và giả server push.\n- Biết sử dụng các công cụ AI để hỗ trợ code.\n\nQuyền lợi:\n- Lương từ 15 triệu - 25 triệu.\n- Thưởng: thưởng năng suất, thưởng ngày lễ, tháng 13, …\n- Review năng lực định kỳ 6 tháng/ lần.\n- Trà, cà phê free, tham gia nghỉ mát, hoạt động team building của công ty.\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Hỗ trợ tối đa các thiết bị phục vụ công việc.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 2, Sàn dịch vụ thương mại tòa nhà CT2D, VOV Mễ Trì,, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Sáng thứ 7 ( 8h-12h)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3194, 186, 2, 'Lập Trình Viên Backend', 'Mô tả công việc:\n• Tham gia vào việc xây dựng và phát triển ứng dụng Backend dựa trên các yêu cầu của công ty.\n• Tham gia vào việc thiết kế hệ thống và triển khai sản phẩm CNTT nội bộ.\n• Tối ưu hiệu năng các ứng dụng trong hệ thống.\n• Phát triển và triển khai API cho các sản phẩm Core.\n• Phối hợp với đội ngũ phát triển Frontend và quản trị dự án để đảm bảo sự liên kết và hiệu suất công việc cao nhất.\n\nYêu cầu ứng viên:\n+ Thành thạo .NET (C#)\n+ Thành thạo SQL\n+ Sử dụng thành thạo công cụ làm việc nhóm Git\n+ Có hiểu biết về CI/CD\n+ Kinh nghiệm từ 5 năm trở lên\n+ Bắt buộc nộp portfolio kèm mã nguồn\n- Khi phỏng vấn:\n+ Có thể kiểm tra viết luận liên quan đến design pattern\n+ Có bài kiểm tra coding trong quá trình phỏng vấn\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi:\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận. Mức lương cao, có thể thoả thuận theo năng lực của ứng viên\n• 1 năm tăng lương/lần\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus  theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước)\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm , Tiêm phòng HPV, cúm,...', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3195, 1402, 2, 'Tech Lead (Java)', 'Mô tả công việc:\n- Tham gia phát triển sản phẩm theo yêu cầu của khách hàng theo Java\n- Đảm bảo chất lượng code, các vấn đề về hiệu năng và bảo mật\n- Quản lý công việc của team, phân công công việc, nghiệm thu và Báo cáo kết quả.\n- Đưa ra giải pháp kỹ thuật, nghiên cứu các công nghệ mới áp dụng vào dự án.\n- Một số công việc khác theo chỉ đạo của cấp trên.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật phần mềm hoặc các ngành liên quan.\n- Ít nhất 3 năm kinh nghiệm làm lập trình viên Java, trong đó ít nhất 1 năm ở vị trí quản lý hoặc lãnh đạo nhóm.\n- Kinh nghiệm vững về Java, Spring Framework, Hibernate, RESTful APIs, Maven, và các công nghệ Java khác.\n- Kinh nghiệm làm việc với các cơ sở dữ liệu quan hệ như MySQL, PostgreSQL hoặc các hệ thống NoSQL.\n- Có kiến thức về các công cụ quản lý mã nguồn như Git, và quy trình phát triển Agile/Scrum.\n- Khả năng lãnh đạo và truyền cảm hứng cho đội ngũ, với kỹ năng giao tiếp tốt và khả năng giải quyết vấn đề hiệu quả.\n- Có khả năng làm việc dưới áp lực và quản lý thời gian hiệu quả.\n- Tiếng Anh đọc hiểu tài liệu kỹ thuật là một lợi thế.\n\nQuyền lợi:\nChế độ đãi ngộ:\n- Lương thỏa thuận theo năng lực thực tế của ứng viên, Review performance: 1 lần/ năm.\n- Trợ cấp đi lại, trợ cấp học phí các chứng chỉ IT, trợ cấp OT, trợ cấp onsite khi đi tham gia dự án thuê ngoài;\n- Thưởng lễ tết (theo quy định và tình hình thực tế của công ty); lương tháng thứ 13, thưởng nhân viên xuất sắc quý, năm;\n- Chế độ chăm sóc nữ giới: Nghỉ sinh lý phụ nữ: 1 ngày/ tháng. Nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi: 1h/ ngày.\nChế độ chăm sóc sức khỏe cho nhân viên:\n- Bảo hiểm y tế, bảo hiểm thất nghiệp, bảo hiểm xã hội theo quy định của Luật Lao động;\n- Khám sức khỏe định kỳ hàng năm tại các bệnh viện uy tín (ĐH Y, BV 103, Thu cúc, Medlatec,..v..v.)\nVăn phòng làm việc tiện ích:\n- Miễn phí trà, cà phê tại khu vực ăn uống của công ty;\n- Máy pha cà phê tiện ích tại văn phòng;\n- Đồ ăn nhẹ cho team OT.\nCác hoạt động sôi nổi:\n- Hoạt động team building kết nối đội nhóm hàng quý;\n- Party cuối thứ 6 hàng tuần;\n- Các CLB thể thao: bóng đá, cầu lông, bilac, game,..v..v; thể dục nhẹ nhàng sau giờ ngủ trưa;\n- Chương trình radio phát nhạc, confession theo yêu cầu;\n- Hoạt động du lịch thường niên và các sự kiện lớn trong công ty;\n- Seminar về kiến thức chuyên môn, ngoại ngữ và các kỹ năng khác.\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Roman Plaza, Tố Hữu, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:15)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3196, 1199, 2, 'Java Backend Developer (Onsite)', '- Phát triển các tính năng của hệ thống quản lý, kiểm soát các nghiệp vụ nội bộ ngân hàng bao gồm: mua sắm, ngân sách, tài sản, thanh quyết toán chi tiêu nội bộ, quản lý nhân sự ... \n- Tham gia vào các công đoạn: kiến trúc hệ thống, thiết kế chức năng, lập trình, unit test, viết tài liệu chức năng, tối ưu performance… \n- Lập trình hệ thống các ứng dụng trên nền Java Core, Java Spring Boot và các hệ thống Middleware trên nền tảng java \n- Viết code và Unit test theo mô hình phát triển DevOps CI/CD \n- Tối ưu performance các xử lý giải thuật \n- Tham gia tìm hiểu các công nghệ, kỹ thuật mới.\nKiến thức:\n- Tốt nghiệp Đại học trở lên chuyên ngành CNTT hoặc các ngành tương đương \nKinh nghiệm:\n-  2 năm kinh nghiệm làm việc thực tế tại các tổ chức CNTT\n-  Nắm rõ quy trình xây dựng và triển khai phần mềm\n-  Sử dụng thành thạo Java core, có kinh nghiệm phát triển trên framework Spring Boot.\n-  Có hiểu biết về cơ sở dữ liệu: SQL, noSQL\n-  Có hiểu biết về việc sử dụng các công cụ quản trị như: Jija, Git,...\nƯu tiên:\n-  Ưu tiên ứng viên có kinh nghiệm về phát triển ứng dụng theo dạng Cloud Native như: Microservice, CICD, DepOps, Containerization...\n-  Ưu tiên Nhân sự đã từng tham gia triển khai các dự án theo mô hình Agile/Scrum\n-  Ưu tiên nhân sự có kinh nghiệm về xử lý bất đồng bộ, xử lý đa nhiệm, event sourcing, có kinh nghiệm về các hệ thống Message Queue (Kafka, RabbitMQ), có hiểu biết về xử lý cache, job.\nNgoại ngữ:\n- Có khả năng đọc viết tiếng Anh (cơ bản) nghe nói (nếu có thể).\nYêu cầu khác:\n- Kỹ năng giao tiếp và làm việc nhóm tốt\n- Sẵn sàng làm việc ngoài giờ hành chính\n- Tinh thần trách nhiệm, ham học hỏi\n\n---Ưu tiên nộp hồ sơ sớm---\nQuyền lợi:\n- Thời gian làm việc 5 ngày/tuần (từ thứ Hai đến thứ Sáu).\n- Cơ hội thăng tiến, phát triển nghề nghiệp công bằng.\n- Thu nhập hấp dẫn, cạnh tranh.\n- Được hưởng chế độ BHXH, BHYT, BHTN và thưởng các ngày lễ tết theo quy định.\n- Được tham gia các chương trình đào tạo, huấn luyện của Công ty.\n- Môi trường làm việc chuyên nghiệp, thân thiện, năng động.\n- Thu nhập: 15 - 28 triệu (Tùy theo năng lực)\nĐịa điểm làm việc:\n- Hà Nội: Lê Văn Lương, Cầu Giấy\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3197, 1316, 2, 'Mobile Developer (Flutter)', 'Mô tả công việc\n- Phân tích yêu cầu nghiệp vụ, tư vấn giải pháp kỹ thuật cho các sản phẩm mobile app.\n- Thiết kế kiến trúc tổng thể, luồng xử lý và giao diện người dùng cho ứng dụng mobile.\n- Trực tiếp tham gia phát triển, tối ưu hóa và tích hợp ứng dụng mobile với hệ thống backend và bên thứ 3.\n- Hướng dẫn, đào tạo và hỗ trợ kỹ thuật cho các thành viên trong team mobile.\n- Xây dựng và duy trì văn hóa làm việc tích cực, chuyên nghiệp trong nhóm phát triển mobile.\n- Thúc đẩy tinh thần làm việc nhóm, kết nối các thành viên, truyền cảm hứng và tạo động lực phát triển cá nhân cho từng thành viên.\n- Tham gia cùng cấp quản lý trong việc xây dựng lộ trình phát triển đội ngũ, phân bổ công việc, đánh giá hiệu suất và định hướng phát triển năng lực nhân sự.\n\nYêu cầu ứng viên\n- Từ 3 năm kinh nghiệm phát triển ứng dụng mobile (iOS/Android).\n- Ưu tiên từng có kinh nghiệm lead dự án, lead team\n- Thành thạo ngôn ngữ Dart và framework Flutter.\n- Có kinh nghiệm với các ngôn ngữ native: Java/Kotlin (Android), Swift/Objective-C (iOS).\n- Hiểu rõ kiến trúc mobile app, các pattern thiết kế như MVVM, BLoC, Clean Architecture…\n- Sử dụng thành thạo GetX hoặc các công cụ quản lý state phổ biến.\n- Kinh nghiệm tích hợp RESTful API, xử lý dữ liệu định dạng JSON/XML.\n- Kỹ năng tối ưu hóa hiệu suất, quản lý bộ nhớ và xử lý sự cố mobile app.\n- Có kiến thức về thiết kế giao diện người dùng (UI/UX) là lợi thế.\n- Có kinh nghiệm triển khai được app lên các nền tảng apple store, google play\n- Có khả năng review code, khả năng mentor, đào tạo thành viên\n\nQuyền lợi\n- Thu nhập: Thỏa thuận theo năng lực.\n- Thưởng hiệu quả kinh doanh theo quy định và theo kết quả kinh doanh của công ty.\n- Bảo hiểm sức khỏe và Chương trình Khám sức khỏe định kỳ hàng năm chất lượng cao.\n- Các hoạt động văn hóa định kì như: Ngày lễ, Sinh nhật Công ty; … Du lịch, team building 2-3 lần/năm.\n- Các chế độ theo quy định của pháp luật (BHYT, BHXH, BHTN) và các chế độ phúc lợi theo nội quy, quy chế của Công ty (tham quan, nghỉ mát, lương thưởng, nghỉ Tết lễ, …)\n- Môi trường làm việc chuyên nghiệp, lắng nghe, tôn trọng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3198, 1384, 2, 'Senior Backend Developer', 'Mô tả công việc\n- Tham gia phát triển các thành phần backend sử dụng NodeJS cho hệ thống trading (crypto/stock/forex…).\n- Xây dựng và tối ưu API (RESTful/GraphQL) real-time, phục vụ truyền dữ liệu giao dịch, lệnh mua bán, cập nhật giá, khớp lệnh.\n- Thiết kế, xây dựng và quản lý hệ thống microservice đảm bảo khả năng mở rộng, độ tin cậy cao, latency thấp.\n- Tối ưu hiệu năng cho các module quan trọng: quản lý lệnh, sổ lệnh (order book), xử lý signal (tín hiệu giá), đồng bộ dữ liệu liên tục.\n- Tích hợp và đảm bảo an toàn khi làm việc với các bên thứ ba: sàn giao dịch, ngân hàng, ví, data feed (Websocket, REST API).\n- Triển khai, giám sát, nâng cấp hệ thống trên môi trường Docker, Kubernetes.\n- Phối hợp với team DevOps, Frontend, Data, QA để phân tích, thiết kế, triển khai và kiểm thử tính năng mới.\n- Đảm bảo code chất lượng, bảo mật, thực hiện unit test, integration test và tối ưu hóa hệ thống.\n- Xử lý sự cố hệ thống (incident, outage) nhanh chóng, đặc biệt là trong thời gian cao điểm giao dịch.\n- Nghiên cứu, đề xuất các giải pháp công nghệ mới phục vụ yêu cầu giao dịch real-time, big data, machine learning (nếu có).\n- Tham gia phân tích và nâng cấp kiến trúc để hệ thống sẵn sàng chịu tải lớn, mở rộng thị trường hoặc sản phẩm mới.\nYêu cầu ứng viên\n- Từ 3 năm kinh nghiệm trở lên với Java production.\n- Có vai trò thiết kế, kiến trúc, bảo trì hệ thống trading real-time xuyên suốt (order book, matching engine, event sourcing…).\n- Thành thạo websocket, xử lý event, anti-pattern, đồng bộ hóa, thời gian thực (pub/sub, message queue).\n- Có kỹ năng tối ưu hiệu năng, scale service hệ thống trading chịu tải lớn, latency thấp (cực kỳ quan trọng).\n- Biết kiểm thử, phân tích log, xử lý sự cố production.\n- Thực chiến với Docker, Kubernetes, cloud (AWS, GCP…) là ưu thế.\n- Kinh nghiệm xây dựng hệ thống fault-tolerant, high-availability.\n- Có kiến thức sâu rộng về bảo mật hệ thống (đặc thù tài chính/trading) là ưu thế.\n- Có khả năng mentoring, review code, đề xuất giải pháp.\nQuyền lợi\n- Thỏa thuận lương theo năng lực, upto 50M Gross.\n- 100% lương trong thời gian thử việc.\n- Xét tăng lương 1 lần/năm.\n- Thưởng tháng lương 13, thưởng hiệu suất, thưởng Lễ Tết, thưởng sinh nhật,...\n- Bảo hiểm xã hội, Bảo hiểm Y tế, Bảo hiểm thất nghiệp khi trở thành nhân sự chính thức.\n- Chế độ ốm đau, hiếu hỉ, khuyến khích tài năng trẻ,...\n- Môi trường trẻ trung năng động và đầy nhiệt huyết.\n- Thời gian làm việc linh hoạt.\n- Được đào tạo 1-1 với Quản lý hoặc Senior.\n- Du lịch nghỉ mát hàng năm, nhiều hoạt động teambuilding.\n- Hỗ trợ hoạt động CLB như Cầu lông, Yoga, Đá bóng, Bơi-Đạp-Chạy,...\nĐịa điểm làm việc\n- Hà Nội: 106 Hoàng Quốc Việt, Cầu Giấy\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3199, 1159, 2, 'Fullstack Developer (Junior)', 'We are looking for web engineers to join our team with NodeJS and TypeScript (JavaScript) experience with a strong background in API design, databases, performance, scalability, security, SPA, etc. This position will work directly with customers (using English) in Singapore and their partners in Europe to build a game marketplace & Crypto Trading Platform up from scratch.\n\nYou will:\n\n- Working with Product Owners to convert business requirements into technical designs.\n- Working and pair programming with other developers to build applications with Node.JS and ReactJS.\n- Designing & implementing back-end API using NodeJS.\n- Applying proven technologies and best practices to level up your technical skills: NestJS, Redux.\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n\nYour Skills and Experience:\n\n- Experience on ReactJS, NodeJS is a requirement.\n- Experience in design patterns.\n- Experience in MySQL, MongoDB, Redis administration.\n- Good English communication (writing, reading, speaking, and listening) is a plus.\n- Knowledge of solidity is a plus.\n- Knowledge of cryptography and blockchain is a plus.\n\nWhy You\'ll Love Working Here:\n\n- Build World class product(s): We love to solve complex problems and learn new things.\n- Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n- Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n- Enjoy competitive salary, bonus according to work performance\n- 13th Salary\n- Assistance with operational tools and equipment.\n- Health insurance program up to 100 million VND/year for employees provided by PVI.\n- Annual health check-up from Medlatec Clinic\n- Participate in social insurance after becoming an official employee\n- Salary review twice a year. It means we are pushing each other to be better everyday.\n- Flexible working hours, freestyle attire.\n\nPerks You\'ll Enjoy:\n\n- Working in a young, super talented, and supportive team environment\n- Technical, English certificate bonus\n- Day-off: 12 days/year and Vietnam holidays\n- Happy Hour, Football club, English club, and many exciting activities\n- Company trip/team building/ Year End Party.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3200, 1330, 2, 'Backend Developer', 'Job description\n\nResponsibility\n- The Senior Software Engineer is responsible to write software programs from design specifications\n- Determining requirements and providing project estimates and timelines and high level architecture design\n- Implement task lists, estimate deliver assignments as functional specifications, quality standards and project schedules.\n- Reports status and issues\n- Documents detailed designs\n- Contributes to system architecture and design decisions.\n- Perform other tasks assigned by the Product Owner, Project Manager & Technical Manager to figure out user’s needs, problems, expectations to contribute ideas & solution as well as to resolve them\n\nYêu cầu ứng viên\nMust have\n- Good knowledge of OOP, SOLID principles\n- 3+ years experienced in NodeJS, NestJS (static module, dynamic module)\n- 2+ year experienced Postgresql / MongoDB\n- Creative thinking and good at problem solving\n- Strong knowledge of web service development (RESTful)\n- Excellent communication, motivational, and interpersonal skills.\nNice to have\n- Having experiences mentoring and leading teams\n- Knowledge of cloud services – especially Google Cloud\n- Good knowledge of Docker Engine and K8S, cloud deployment, security\n\nQuyền lợi\n- Fixed salary negotiable based on competency + bonuses.\n- 13th-month salary and performance-based bonuses.\n- Bonuses according to company policies, including holiday, Tet, and company event bonuses.\n- Comfortable, dynamic, and friendly working environment with high promotion opportunities.\n- 12 annual leave days + birthday leave; leave days increase based on internal level and years of service.\n- Full social insurance (BHXH), health insurance (BHYT), and participation in the company’s labor union.\n- Benefits for personal events such as birthdays, weddings, illness, and maternity leave.\n- Regular salary reviews based on company policies.\n- Uniforms and gifts for company events.\n- Clear career advancement path with comprehensive training and maximum support in work.\n\nĐịa điểm làm việc\n- Hà Nội: 219 Trung Kính, Yên Hòa, Cầu Giấy, Cầu Giấy\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3201, 1417, 2, 'Middle Frontend Developer', 'We\'re seeking an experienced Frontend Developer (Middle level) to lead and contribute to the development of our core frontend modules. As part of our international team, you\'ll have the unique opportunity to work directly with leading Japanese developers and shape the architecture of our web applications.\n- Design and develop reusable frontend modules and components that form the foundation of our applications\n- Architect and implement scalable frontend solutions using modern JavaScript frameworks\n- Drive technical decisions for frontend architecture and establish coding standards\n- Create efficient, maintainable, and performance-optimized code\n- Build and maintain core UI component libraries for company-wide use\n- Lead the implementation of complex frontend features and ensure code quality\n- Work closely with our design and backend teams to create seamless user interfaces\n- Learn and apply Japanese development standards and best practices through direct mentorship\n- Participate in our agile development process from architecture planning to testing\n\nYêu cầu ứng viên:\n- Minimum 3+ years of professional frontend development experience\n- Strong command of JavaScript and TypeScript\n- English communication skills (TOEIC 700 or equivalent)\n- Advanced experience with:\nVue.js ecosystem and state management\nModern frontend architecture patterns\nComponent-based development\nHTML5/CSS3 best practices\nGit version control\nTest-Driven Development\nSEO optimization techniques\nModern UI component libraries\n- Experience in building and maintaining large-scale applications\nPersonal Qualities:\nStrong technical leadership and decision-making abilities\nPassionate about creating maintainable, scalable code\nSelf-motivated problem solver\nTeam player with excellent collaboration skills\n\nQuyền lợi:\nWork-Life Balance\n- Hybrid work model (2-3 days remote per week)\n- Flexible hours (9-6 or 10-7)\n- Business casual environment\n- New laptop/PC provided\nCompensation & Benefits\n- Competitive base salary matching your experience level - 13th month bonus\n- Full insurance coverage\n- Paid time off as per labor law\n- Free lunch, snacks & beverages\nGrowth & Development\n- Direct mentorship from Japanese tech experts\n- Modern workspace fostering open communication\n- Flat organizational structure\n- Chance to work on real, impactful products\n- Be part of an innovative Japanese tech startup\nJoin a Japanese tech startup at the forefront of Web3 and crypto, offering a holistic learning experience beyond programming Join us in building impactful digital solutions while growing your career in a supportive, international environment!\n\nĐịa điểm làm việc:\n- Hà Nội: Duy Tân, Cầu Giấy\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3202, 1288, 2, 'Fresher Flutter', 'Bạn sẽ tham gia phát triển ứng dụng di động cho sản phẩm EasyPos – phần mềm quản lý bán hàng đa nền tảng do Softdreams phát triển, phục vụ các cửa hàng, siêu thị mini, nhà thuốc, và chuỗi bán lẻ,...\n\nNhiệm vụ chính:\n- Phát triển và tối ưu ứng dụng di động (Android/iOS) bằng Flutter.\n- Thiết kế giao diện UI/UX hiện đại, dễ dùng, phù hợp nghiệp vụ bán hàng.\n- Tích hợp hệ thống API (bán hàng, kho, hóa đơn điện tử, khách hàng...).\n- Tham gia phân tích, thiết kế giải pháp kỹ thuật theo yêu cầu từ team sản phẩm.\n- Làm việc nhóm theo quy trình Agile/Scrum, quản lý tiến độ bằng OKRs.\n- Cải tiến hiệu năng, xử lý lỗi, nâng cấp và bảo trì ứng dụng định kỳ.\n\nYêu cầu ứng viên:\n- Tối thiểu 6 tháng - 1 năm kinh nghiệm phát triển ứng dụng Mobile trên Android hoặc iOS.\n- Thành thạo Dart/Flutter, hiểu rõ widget tree, state management (Provider, Bloc hoặc Riverpod), async, RESTful API.\n- Tư duy tốt về thiết kế UI/UX và xây dựng trải nghiệm người dùng tối ưu.\n- Tinh thần trách nhiệm cao, làm việc đúng hạn và hiệu quả.\n- Kỹ năng làm việc nhóm và độc lập tốt.\n- Khả năng đọc hiểu tài liệu tiếng Anh, tự tra cứu, học hỏi.\n- Chủ động, sáng tạo, yêu thích công nghệ và mong muốn phát triển lâu dài.\n- Sẵn sàng làm việc trong môi trường nhiều thử thách, tốc độ cao.\n- Ưu tiên:\n- Có sản phẩm cá nhân đã xuất bản trên CH Play / App Store.\n- Đã từng làm việc trong mô hình Agile/Scrum, sử dụng OKRs.\n- Có kinh nghiệm với hệ thống POS, tài chính kế toán, chữ ký số là lợi thế.\n\nQuyền lợi:\n- Lương: 8 - 15M + phụ cấp (Phụ cấp: ăn trưa (30k/ngày đi làm), gửi xe.)\n- Chế độ lương thưởng hấp dẫn với lương tháng 13, thưởng tết\n- Đánh giá hiệu suất: 2 lần/năm\n- Làm việc tại Doanh nghiệp với sứ mệnh phụng sự xã hội, mang lại các sản phẩm, dịch vụ nhằm thay đổi năng suất cho các doanh nghiệp\n- Văn hóa trao đổi thẳng thắn, hỗ trợ tận tình; Sếp trẻ tâm lý, đồng nghiệp thân thiện\n- Khuyến khích sự chủ động và tích cực học hỏi\n- Cơ hội thăng tiến và thu nhập phù hợp tùy vào chuyên môn hoặc khả năng quản lý.\n- Được học hỏi: SDS tạo điều kiện cho mọi người rèn luyện ở mọi lúc mọi nơi, đồng hành và thúc đẩy phát triển cá nhân từ đồng nghiệp và quản lý giàu kinh nghiệm\n- Du lịch hằng năm với địa điểm hấp dẫn, thường xuyên tổ chức các hoạt động team building gắn kết cộng đồng, các hoạt động vui chơi giải trí cho nhân viên.\n- Tham gia chương trình hàng tháng, các buổi liên hoan, sinh nhật hàng tháng, tiệc noel, tất niên,...\n- Được tham gia BHXH, BHYT, BHTN, chế độ nghỉ có lương full phép theo luật hiện hành.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3203, 1123, 2, 'Java Developer', 'Mô tả công việc\n- Develop and maintain backend systems and services in Java.\n- Collaborate with frontend developers and other team members to design and implement robust solutions.\n- Write clean, scalable, and efficient code while adhering to best practices.\n- Troubleshoot and debug applications to ensure optimal performance.\n- Participate in code reviews and contribute to the continuous improvement of development processes.\n\nYêu cầu ứng viên\n- Bachelor’s degree in Computer Science, Software Engineering, or a related field.\n- 3 years of experience in Java development with a solid understanding of backend technologies.\n- Familiarity with frameworks such as Spring or Hibernate.\n- Strong problem-solving skills and the ability to work independently and as part of a team.\n- Good English communication skills, both written and verbal.\n\nQuyền lợi\n- Salary: Negotiation\n- Join a global team and work directly with many talents around the world.\n- Opportunities for onsite work in Japan, Singapore, Australia, and many other countries.\n- Work and grow in a dynamic, creative, and professional environment.\n- Healthcare: Premium Health Insurance TECHVIFY Care\n- 13 months’ salary per year.\n- Annual salary evaluation.\n- Sponsor and encourage staff to study courses by covering tuition fees, such as Udemy, Coursera.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 9, tháp A, tòa HUDTOWER, số 37 Lê Văn Lương, Phường Nhân Chính, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3204, 1145, 2, 'Nhân Viên Lập Trình Ứng Dụng', 'Mô tả công việc:\nCó kinh nghiệm phát triển và triển khai ứng dụng trên nền tảng .NET\nCó kiến thức về Build cross-platform: Electronjs\nBiết ứng dụng AI trong lĩnh vực lập trình ứng dụng\nCó kinh nghiệm hỗ trợ/ tư vấn giải pháp phần mềm cho đơn vị/tổ chức\nBiết sử dụng công cụ DevExpress, Material Design UI, WinUI, WPF UI\nĐã từng tham gia phát triển phần mềm trong lĩnh vực giáo dục là một lợi thế.\n\nYêu cầu ứng viên:\nỨng viên có từ 2 năm kinh nghiệm trở lên.\nTốt nghiệp Đại học trở lên thuộc chuyên ngành Công nghệ thông tin, Kỹ thuật phần mềm, Khoa học máy tính hoặc chuyên ngành có liên quan.\n\nQuyền lợi:\nLương theo thỏa thuận.\nĐược ký hợp đồng chính thức sau thời gian thử việc và có chế độ tham gia BHXH, BHYT, BHTN… đầy đủ.\nĐược thưởng dịp Lễ, Tết.\n\nĐịa điểm làm việc:\nCần Thơ: 168, Nguyễn Văn Cừ (nối dài), Ninh Kiều.\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 07:30 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Cần Thơ', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3205, 1146, 2, 'Lập Trình Viên BAck-End (.NET) - Lĩnh Vực Edtech  - Mức Lương Up To 30 Triệu', 'Chúng tôi đang tìm kiếm ứng viên nhiệt huyết và đam mê công việc để gia nhập đội ngũ nhân viên trẻ tuổi và tài năng của  công ty FSEL với yêu cầu như sau:\n\n● Tham gia phát triển các sản phẩm phục vụ cho hàng trăm nghìn khách hàng về các dịch vụ học trực tuyến E-learning\n● Xây dựng và tối ưu sản phẩm đáp ứng hàng trăm nghìn người sử dụng đồng thời\n● Tham gia nghiên cứu và ứng dụng các công nghệ mới vào sản phẩm: Blockchain, AI, Machine Learning, BigData, RPA, …\n● Phối hợp cùng đội ngũ BA phân tích, thiết kế, đưa ra giải pháp để phát triển phần mềm đáp ứng đúng, đủ, tiện các yêu cầu của người dùng cuối\n● Tham gia tất cả các giai đoạn phát triển phần mềm được yêu cầu từ lập kế hoạch, ước tính, thiết kế và phát triển việc thực hiện.\n● Tham gia vào các quy trình Agile như Scrum hoặc Kanban.\n\nYêu cầu ứng viên:\n\n- Tốt nghiệp đại học các chuyên ngành Khoa học máy tính hoặc Công nghệ thông tin.\n- Có ít nhất 3 năm kinh nghiệm trong các dự án .NET.\n- Có kinh nghiệm công nghệ dữ liệu nâng cao của Microsoft: ADO.NET, .NET Core, ASP.NET (Core), MVC, Entity Framework (Core), Linq, SQL Server.\n- Có khả năng triển khai & tối ưu hóa các công nghệ .NET Server-side thành thạo.\n- Có kinh nghiệm thiết kế các API RESTful với ASP.NET.\n- Rất tốt trong việc hiểu và áp dụng các Mẫu thiết kế / Nguyên tắc thiết kế.\n- Thành thạo trong việc duyệt mã, tái cấu trúc mã.\n- Có kiến ​​thức cơ bản về HTML, CSS, JavaScript. Có kinh nghiệm về bất kỳ JavaScript nào, ví dụ: Angular, React, Vue.\n- Kiến thức cơ bản về công nghệ cloud, v.d. Azure, AWS.\n- Có kinh nghiệm làm việc trong môi trường Phát triển phần mềm Agile / Scrums.\n- Có thái độ tốt về tự kiểm tra và tự học.\n\nQuyền lợi:\n\n- Mức lương (gross): up to 30 triệu/tháng\n- Thưởng sinh nhật, thưởng các dịp Lễ, Tết trong năm\n- Chế độ BHXH, BHYT, BHTN đầy đủ ngay sau khi ký HĐ chính thức\n- Khám sức khoẻ định kỳ hàng năm\n- Trang bị máy tính hiện đại phục vụ công việc\n- Quỹ Team Building lên tới 2.400.000 VNĐ/người/năm\n- Du lịch nghỉ dưỡng hàng năm\n- Trà chiều với bánh, hoa quả và đồ ăn vặt miễn phí hàng tuần\n- Cơ hội tiếp cận với các doanh nghiệp, dự án lớn, xu hướng công nghệ và nền tảng mới nhất\n- Được tham gia các lớp đào tạo, khóa học chuyên môn để phát triển kỹ năng\n- Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung & trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắc\n- Học tiếng Anh hoàn toàn miễn phí & ưu đãi học phí cho người thân.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3206, 209, 2, 'ReactJS Developer', 'ABOUT COMPANY\nA subsidiary of the FPT Group, FPT Software is known as a leading global information technology service provider headquartered in Vietnam. With over 30,000 employees working in 83 offices across 30 countries on five continents, FPT Software consistently delivers the best solutions to more than 1000 clients, including 100 Fortune 500 companies. Placing human resources as the cornerstone of its achievements, employee experience is our top priority in continually creating an innovative, open, and enjoyable work environment for every member.\n\nIn 2023, FPT Software officially made its mark on the global billion-dollar company list. This is evidence of the talent and efforts of multiple generations of employees at FPT Software.\n\nWhy not explore your potential and embark on a brilliant journey with us?\n\nRESPONSIBILITIES\n• Leading the development of high-impact features\n• Architecting scalable, efficient React.js solutions\n• Collaborating with cross-functional teams and stakeholders\n• Ensuring the highest standards of code quality and performance\n• Identifying and addressing technical issues proactively\n• Innovating and implementing best practices in React.js development\n• Participating in strategic planning and decision-making\n• Driving continuous improvement in development processes\n• Mentoring and providing guidance to junior team members\n\nYêu cầu ứng viên\n• Extensive experience with React.js and JavaScript\n• Experience with dynamic rendering\n• Proven track record in architecting complex UI solutions\n• Expertise in front-end build tools and pipelines\n• In-depth knowledge of RESTful APIs and integration\n• Familiarity with security best practices\n• Experience with performance optimization techniques\n• Ability to work effectively in Agile and with cross-functional teams\n• Strong leadership, communication, and problem-solving skills\n• Previous mentoring or leadership experience is a plus\n• A degree in software engineering, information technology, or a related field\n\nQuyền lợi\n• FPT Care insurance plan tailored for FPT employees\n• Relocation Policy up to 100 Million VND for the candidate who is willing to relocate to Nha Trang City.\n• Attractive annual summer vacation allowance\n• Sponsored training courses for personal growth and up to 100% coverage for certification costs\n• Global and inclusive workplace with monthly cross-cultural events\n• International exposure and career growth across global locations\n• Work-life balance benefits with a flexible leave policy and annual health check-ups to support employee well-being\n\nĐịa điểm làm việc\n- Khánh Hoà: VCN Tower, Số 2 Đường Tố Hữu, Khu đô thị Phước Hải, Thành phố Nha Trang, TP Nha Trang\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Khánh Hoà', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3207, 1427, 2, 'Lập Trình Viên .NET', 'Mô tả công việc:\n- Tham gia thiết kế, phát triển, kiểm thử và bảo trì các ứng dụng sử dụng nền tảng .NET (C#, ASP.NET MVC, .NET Core/8).\n- Áp dụng các nguyên tắc lập trình hướng đối tượng (OOP), các mẫu thiết kế (Design Patterns) và nguyên tắc SOLID để xây dựng mã nguồn chất lượng cao, dễ bảo trì.\n- Thiết kế và tối ưu hóa cấu trúc cơ sở dữ liệu sử dụng Microsoft SQL Server, bao gồm viết truy vấn SQL, stored procedures, triggers và views để đảm bảo hiệu suất và tính toàn vẹn dữ liệu.\n- Phân tích yêu cầu, thiết kế kiến trúc hệ thống, và tham gia thảo luận để đưa ra các giải pháp kỹ thuật hiệu quả.\n- Xử lý, gỡ lỗi và khắc phục các vấn đề kỹ thuật trong môi trường production.\n- Phối hợp với các nhóm liên quan (BA, QA,) để đảm bảo chất lượng sản phẩm phần mềm.\n- Soạn thảo và cập nhật tài liệu kỹ thuật, bao gồm tài liệu thiết kế và hướng dẫn sử dụng.\n- Ứng dụng các công nghệ AI/ML để hỗ trợ phát triển sản phẩm (lợi thế).\n- Có kinh nghiệm sử dụng n8n để tự động hóa quy trình là một điểm cộng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp chuyên ngành Công nghệ Thông tin, Khoa học Máy tính hoặc các ngành liên quan.\n- Có ít nhất 2 năm kinh nghiệm phát triển phần mềm với .NET Framework/.NET Core, bao gồm C#, ASP.NET MVC, và Web API.\n- Thành thạo Microsoft SQL Server, có kinh nghiệm thiết kế cơ sở dữ liệu, tối ưu hóa truy vấn SQL, viết stored procedures và tối ưu hiệu suất.\n- Hiểu biết sâu về các nguyên tắc OOP, Design Patterns (ví dụ: Singleton, Factory, Repository) và áp dụng nguyên tắc SOLID trong phát triển phần mềm.\n- Ưu tiên ứng viên có kinh nghiệm với các công nghệ front-end: HTML, CSS, JavaScript, jQuery.\n- Thành thạo sử dụng hệ thống quản lý mã nguồn như Git hoặc SVN.\n- Kỹ năng phân tích, giải quyết vấn đề và tư duy logic tốt.\n- Khả năng giao tiếp, làm việc nhóm hiệu quả và thích nghi với môi trường làm việc năng động.\n\nQuyền lợi:\n- Lương và thu nhập: 15.000.000 – 20.000.000\n- Được hưởng đầy đủ các quyền lợi về BHXH, BHYT theo luật lao động, và Bảo hiểm Tai nạn 24/7\n- Thưởng lễ tết, du lịch nghỉ mát hàng năm, trải nghiệm nội bộ\n- Môi trường làm việc chuyên nghiệp, ổn định, thân thiện và năng động\n- Được xem xét đánh giá năng lực. Lương tháng 13 và xét tăng lương 6 tháng/lần.\n- Cơ hội phát triển cao trong nghề nghiệp, phát triển khả năng của bản thân\n- Các hoạt động tập thể: CLB Thể thao, Team Building...\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 12A Núi Thành, Phường 13, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)\n- Sáng thứ 7: từ 08:30-12:00\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm \'Ứng tuyển\' ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3208, 1282, 2, 'Lập Trình Viên / Fullstack Developer', 'Mô tả công việc:\n- Lập trình và tích hợp (front-end và back-end);\n- Viết tài liệu mô tả chức năng phần mềm;\n- Xử lý phản hồi từ người sử dụng;\n- Nghiên cứu tối ưu hóa sản phẩm, dịch vụ đã phát triển;\n- Bảo trì và hỗ trợ các vấn đề liên quan đến chuyên môn.\n\nYêu cầu ứng viên:\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành khác am hiểu về Lập trình;\n- Có khả năng research tài liệu và đọc tài liệu.\n- Có kinh nghiệm và sản phẩm là một lợi thế;\n- Có khả năng phân tích, sáng tạo, chịu được áp lực công việc; có tinh thần học hỏi, hợp tác trong công việc;\n- Làm việc ổn định tại Hà Nội\n\nFront-end:\n- Có kinh nghiệm lập trình Web Front-end sử dụng Angular/ReactJS/VueJS. sử dụng thành thạo Typescript, ES6, CSS3, HTML5, Node.js, NPM\n- Có kinh nghiệm phát triển và tích hợp RESTful APIs,\n- Kiến thức về UI/UX, Hiểu biết về Responsive Design và các kĩ thuật tối ưu hóa giao diện,\n- Đã từng dùng các liberary Ui như Boostrap, Antd design, Material, Argon, Jquery…vv\n- Làm quen với Redux, React Hook Form, NextJS, Thư viện thử nghiệm React\n\nBack-end:\n- Có kỹ năng lập trình về .NET Core (C#, ASP.NET Core), RESTful APIs, SOAP; EF Core\n- Có kinh nghiệm với các công cụ build hiện đại (Docker, CI/CD,...).\n- Kinh nghiệm với các công cụ quản lý mã nguồn như Git.\n- Database: SQL Server, Oracle, PostgreSQL;\n\nQuyền lợi:\n- Mức lương: từ 17 triệu - 25 triệu tùy theo năng lực và kinh nghiệm. Xét tăng lương định kỳ hàng năm hoặc trước hạn theo tình hình đánh giá;\n- Được hưởng các chế độ BHYT, BHXH theo quy định của nhà nước; các chính sách phúc lợi của Công ty: Phép năm; Lương thưởng; Quà tết, thưởng lễ; Du lịch...\n- Làm việc trong môi trường chuyên nghiệp, trẻ trung, năng động, hòa đồng, phát huy tối đa khả năng chủ động sáng tạo của nhân viên;\n- Được trang bị đầy đủ trang thiết bị phục vụ công việc;\n- Được trau dồi kỹ năng về nghiệp vụ và kỹ năng mềm;\n- Được tham gia, đóng góp vào các dự án phát triển có quy mô lớn, lâu dài;\n- Thưởng theo thành tích làm việc.\n\nĐịa điểm làm việc:\n- Hà Nội: 101 Láng Hạ, Đống Đa, Đống Đa\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n- Thứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3209, 1389, 2, 'Frontend Developer', 'Mô tả công việc\nPhát triển giao diện người dùng cho các ứng dụng web hướng đến thị trường Hàn Quốc.\nTham gia vào các dự án sử dụng công nghệ Vue3, DevExtreme, Ant Design, TypeScript, GraphQL, REST API, Node.js.\nThiết kế và hiện thực các UI/UX hiện đại, thân thiện và hiệu quả.\nHợp tác với team backend, designer và QA để đảm bảo chất lượng sản phẩm.\nCó thể tham gia các dự án mobile sử dụng React Native (nếu có).\nTự nghiên cứu công nghệ mới, cải tiến quy trình phát triển và đề xuất giải pháp kỹ thuật phù hợp.\n\nYêu cầu ứng viên\nCHỈ TUYỂN ỨNG VIÊN ĐÃ CÓ KINH NGHIỆM LÀM VIỆC ÍT NHẤT 1 HOẶC 2 DỰ ÁN VỚI VUE3 HOẶC NẮM CHẮC KIẾN THỨC VUE2.\nTối thiểu 4 năm kinh nghiệm làm việc với frontend, ưu tiên với Vue3.\nThành thạo TypeScript, HTML, CSS/SCSS.\nCó kinh nghiệm làm việc với các thư viện UI như DevExtreme, Ant Design...\nHiểu biết tốt về kiến trúc SPA, quản lý state, tối ưu performance frontend.\nBiết sử dụng GraphQL, REST API.\nCó kiến thức cơ bản về Node.js là một lợi thế.\nCó khả năng tự nghiên cứu, tìm kiếm và giải quyết vấn đề độc lập.\nChủ động, trách nhiệm trong công việc. Ham học hỏi, có tinh thần cầu tiến.\nBiết ứng dụng AI (như ChatGPT, Copilot...) vào công việc để tăng hiệu quả là một lợi thế.\n\nQuyền lợi\nLàm việc với các dự án thực tế cho khách hàng Hàn Quốc.\nMôi trường làm việc chuyên nghiệp, cởi mở, đề cao tinh thần chủ động.\nLương thưởng cạnh tranh theo năng lực.\nReview định kỳ, cơ hội phát triển lên các vị trí team lead, kỹ thuật chuyên sâu.\nPhụ cấp nếu có các loại bằng hoặc chứng chỉ.\n\nĐịa điểm làm việc\n- Hà Nội: Số 3 - A24 Ngõ 385 Hoàng Quốc Việt, Phường Nghĩa Tân, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 07:30 đến 16:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3210, 1159, 2, 'Fullstack Developer (Senior)', 'About this opportunity: We\'re looking for a Full-Stack Developer to join our team with NodeJS & ReactJS experience with a strong background in API design, databases, performance, scalability, security, etc. who will help us continue to build industry-disruptive tech products and revolutionize the way our customers use technology.\n\nYou will:\n- Working with Product Owners to convert business requirements into technical designs.\n- Working and pair programming with other developers to build applications with Node.JS and ReactJS.\n- Design and develop scalable front-end solutions using ReactJS\n- Build and maintain robust back-end systems with NodeJS\n- Learning new languages and frameworks to improve yourself and stay current in an ever-changing environment.\n- Collaborate with cross-functional teams to define, design, and ship new features\n- Ensure code quality, security, and performance optimization.\n\nYour Skills and Experience:\n- Knowledge of responsive design techniques and front-end optimization methods.\n- At least 3 years of experience as a Full-Stack Developer (Node.js & React.js).\n- Strong proficiency in front-end technologies, particularly React.\n- Expertise in back-end development using Node.js.\n- Hands-on experience with Web3 integration.\n- Solid understanding of smart contract development and deployment.\n- Good command of English (both verbal and written).\n- Knowledge of cryptography and blockchain is a plus.\n\nWhy You\'ll Love Working Here:\n- Build World class product(s): We love to solve complex problems and learn new things.\n- Collaborating directly on projects alongside international partners provides valuable opportunities to engage and enhance skills through interactions with esteemed professionals in the region.\n- Learning culture: At Var Meta, we believe that people are key to the success of a company, so we invest in training whether it is communication skills, technical skills.\n- Enjoy competitive salary, bonus according to work performance\n- 13th Salary\n- Assistance with operational tools and equipment.\n- Health insurance program up to 100 million VND/year for employees provided by PVI.\n- Annual health check-up from Medlatec Clinic\n- Participate in social insurance after becoming an official employee\n- Salary review twice a year. It means we are pushing each other to be better every day.\n- Flexible working hours, freestyle attire.\n\nPerks You\'ll Enjoy:\n- Working in a young, super talented, and supportive team environment\n- Technical, English certificate bonus \n- Day-off: 12 days/year and Vietnam holidays\n- Happy Hour, Football club, English club, and many exciting activities\n- Company trip/ team building/ Year End Party\n- Free coffee, snacks, and drinks.\n\nĐịa điểm làm việc:\n- Đà Nẵng: 68 Xô Viết Nghệ Tĩnh, Cẩm Lệ\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3211, 1154, 2, 'Front-End Developer', 'Mô tả công việc:\n- Phát triển giao diện người dùng cho website thương mại điện tử, đảm bảo tính thân thiện và dễ sử dụng cho khách hàng B2B, B2C và B2B2C.\n- Xây dựng và duy trì mã nguồn cho phần front-end của trang web, sử dụng các framework hiện đại như React, Vue.js hoặc Angular.\n- Tối ưu hóa trải nghiệm người dùng (UI/UX), đảm bảo website hoạt động mượt mà trên nhiều thiết bị và trình duyệt khác nhau. \n- Thực hiện các báo cáo được giao.\n- Thực hiện những nhiệm vụ khác được giao bởi cấp Quản lý trực tiếp và Ban Giám đốc.\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng/đại học chuyên ngành Công nghệ thông tin, Khoa học máy tính, hoặc các ngành liên quan.\n- Có 2-3 năm kinh nghiệm phát triển front-end với các framework React, Vue.js, hoặc Angular.\n- Thành thạo HTML, CSS, JavaScript và các công cụ build front-end như Webpack, Babel.\n- Hiểu biết về phát triển responsive và tối ưu hóa hiệu suất website. \n- Có kinh nghiệm làm việc với RESTful API và các công cụ kiểm thử front-end.\n- Kỹ năng giao tiếp tốt, có khả năng trình bày kết quả phân tích cho các bên liên quan.\n- Tin học văn phòng tốt\n- Có khả năng ra quyết định và có khả năng phân tích tốt.\n- Có khả năng làm việc độc lập, làm việc theo nhóm và khả năng chịu áp lực cao. \n\nQuyền lợi:\n- Môi trường làm việc hiện đại, chuyên nghiệp, năng động, thân thiện, nhiều điều kiện, học hỏi và thăng tiến\n- Thời gian làm việc: 7h45 đến 16h45, từ thứ 2 - thứ 7.\n- Lương Thỏa thuận theo năng lực\n- Lương tháng 13, lương thâm niên quy định Công ty.\n- Được hỗ trợ cơm trưa. \n- Thưởng chuyên cần 800.000 đồng/tháng.\n- Được hưởng các chế độ dành cho người lao động theo quy định pháp luật hiện hành (nghỉ phép, lễ, tết,...).\n- Được hưởng các chính sách phúc lợi theo quy định của Công ty: sinh nhật cá nhân, cưới hỏi, thăm hỏi ốm đau, du lịch nghỉ mát, khám sức khỏe định kỳ hằng năm.\n- Tham gia đầy đủ BHYT, BHXH, BHTN theo quy định và các quyền lợi khác theo quy định của luật lao động.\n- Công ty có chính sách đầu tư đào tạo và nâng cao kỹ năng nhân sự nắm giữ vị trí quản lý trong tương lai.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 200 Nguyễn Văn Bá, P. Trường Thọ, Thủ Đức\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 07:45 đến 16:45)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3212, 1379, 2, 'Lập Trình Viên Senior Fullstack Developer', 'Mô tả công việc:\n- Lead và bảo trì các dịch vụ dựa trên AI\n- Thiết kế, quản lý phát triển frontend và backend\n- Thiết kế giải pháp AI và định hướng kỹ thuật\n- Xây dựng và quản lý mạng nội bộ (Intranet) công ty\n- Thiết kế và phát triển hệ thống chat nội bộ\nQUY TRÌNH PHỎNG VẤN : Phỏng vấn từ xa và thông báo kết quả nhanh chóng\n\nYêu cầu ứng viên:\n- Kinh nghiệm từ 3-5 năm trở lên\n- Có đam mê sâu sắc và kinh nghiệm thực tế với AI (mô hình AI, ChatGPT, Midjourney, Stable Diffusion, v.v.)\n- Hiểu biết tổng quát về phát triển web và ứng dụng (có thể sử dụng HTML, CSS, JavaScript, Python, v.v.)\n- Đã từng xây dựng hệ thống intranet và chat nội bộ\n- Có khả năng sử dụng đa dạng các ngôn ngữ lập trình chính (Java, C#, Ruby, v.v.)\nƯU TIÊN:\n- Thành thạo các framework như React, Node.js, Next.js\n- Có kinh nghiệm làm việc với các nền tảng đám mây (AWS, Azure, Google Cloud)\n- Đã từng dẫn dắt các dự án mã nguồn mở\n\nQuyền lợi:\n- Mức lương: Thỏa thuận theo năng lực (25tr/tháng trở lên)\n- Chi trả bảo hiểm đầy đủ theo chính sách nhà nước.\n- Phụ cấp ăn trưa+ bonus % hoa hồng Video.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 19B Đường số 30, Phường An Khánh, Thủ Đức.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3213, 1190, 2, 'Chief Technology Officer', 'Mô tả công việc\n- Theo dõi các xu hướng công nghệ mới (AI, Blockchain, Cloud, DevOps…) và chủ động đánh giá, lựa chọn, xây dựng & triển khai các giải pháp công nghệ phù hợp với định hướng phát triển của công ty.\n- Định hướng và xây dựng lộ trình ứng dụng các công nghệ mới (đặc biệt là AI) vào từng khâu của quy trình phát triển và vận hành, nhằm tối ưu hiệu suất, tăng năng suất lao động và nâng cao chất lượng sản phẩm/dịch vụ.\n- Thiết lập và quản lý ngân sách công nghệ ở cả cấp công ty và dự án, kiểm soát chi phí đầu tư và vận hành, đảm bảo sử dụng nguồn lực hiệu quả và tối ưu hóa giá trị mang lại cho doanh nghiệp.\n- Xây dựng, triển khai và giám sát các chính sách, quy trình bảo mật hệ thống, đảm bảo tuân thủ nghiêm ngặt các tiêu chuẩn quốc tế về an toàn thông tin (ví dụ: ISO 27001, GDPR…) và liên tục cập nhật phù hợp với quy định mới.\n- Chủ động giám sát, đánh giá và quản trị các rủi ro công nghệ. Xây dựng, cập nhật và triển khai kịch bản ứng phó sự cố nhằm đảm bảo hệ thống vận hành liên tục, hạn chế tối đa rủi ro và thiệt hại cho doanh nghiệp.\n- Làm việc chặt chẽ với khách hàng để hiểu rõ nhu cầu của họ, đồng thời cung cấp tư vấn kỹ thuật chuyên sâu và giải pháp phù hợp, đảm bảo các giải pháp đề xuất đáp ứng mục tiêu kinh doanh cũng như yêu cầu kỹ thuật của khách hàng.\n- Dẫn dắt việc thiết kế và xây dựng kiến trúc cho các hệ thống và ứng dụng phức tạp.\n- Đảm bảo toàn bộ tài liệu kỹ thuật được cập nhật đầy đủ và chính xác.\n- Dẫn dắt và cố vấn cho đội ngũ công nghệ, xây dựng văn hóa đổi mới sáng tạo và không ngừng cải tiến.\n- Tham gia tuyển dụng, đào tạo và giữ chân các nhân tài kỹ thuật tại công ty.\n\nYêu cầu ứng viên\n- Có kinh nghiệm đảm nhiệm vai trò CTO hoặc vị trí lãnh đạo công nghệ cấp cao, ưu tiên trong các công ty chuyên về gia công phần mềm (IT outsourcing).\n- Nền tảng vững chắc về thiết kế hệ thống, kiến trúc và phát triển phần mềm.\n- Có khả năng nhận diện, đánh giá, quản trị và xây dựng kịch bản phòng ngừa, ứng phó rủi ro công nghệ. Tư vấn giải pháp kỹ thuật cho khách hàng và đảm bảo kết quả triển khai đạt chất lượng cao.\n- Có kinh nghiệm quản lý dự án và dẫn dắt các nhóm đa chức năng.\n- Kinh nghiệm xây dựng, phát triển đội ngũ kỹ thuật, khả năng truyền cảm hứng, giải quyết xung đột và giữ chân nhân tài.\n- Có kinh nghiệm thực chiến xử lý sự cố sản xuất, đảm bảo hệ thống hoạt động liên tục.\n- Kỹ năng giải quyết vấn đề xuất sắc và tư duy chủ động trong việc xử lý thách thức.\n- Am hiểu các xu hướng công nghệ mới nhất và các thông lệ tốt nhất trong ngành CNTT. Từ đó, định hướng và triển khai roadmap công nghệ và chuyển đổi số, đặc biệt là các chiến lược ứng dụng AI để nâng cao hiệu suất sản xuất.\n- Kỹ năng giao tiếp và ứng xử xuất sắc, thông thạo tiếng Anh.\n- Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin, Kỹ thuật hoặc lĩnh vực liên quan; có bằng MBA hoặc các văn bằng sau đại học liên quan là một lợi thế.\n\nQuyền lợi\n- Mức lương: Upto 4000$\n- Được đánh giá và xét tăng lương hàng năm theo năng lực và hiệu quả công việc.\n- Thưởng: Thưởng ngày lễ (ngày 2/9, ngày 30/4, tết Dương lịch, Âm lịch, …) \nThưởng theo hiệu quả công việc, kết quả doanh thu.\n- Tổng thu nhập: Từ 14 -15 tháng lương/năm.\n\nMôi trường làm việc\n- Nghỉ thứ 7, Chủ nhật, nghỉ Lễ/Tết và nghỉ phép theo Quy định của Pháp luật hiện hành.\n- Được tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Quy định của Pháp luật hiện hành và quy định công ty.\n- Khám sức khỏe định kỳ 1 năm/1 lần. Bảo hiểm sức khoẻ AMELA CARE ở chương trình cao nhất.\n- Quỹ học tập 3.000.000+/ người/ năm hỗ trợ chi phí thi chứng chỉ, tham gia khoá học.\n- Môi trường trẻ trung, năng động, thẳng thắn trao đổi và chia sẻ, thúc đẩy sự sáng tạo và phát triển.\n- Được tham gia các Câu lạc bộ của Công ty: CLB Bóng đá, Bilac …\n- Được tham gia các hoạt động tập thể sôi động của công ty: Nghỉ mát hàng năm, Teambuilding hàng quý, Gala cuối năm…\n\nCơ hội phát triển\n- Được sử dụng các nguồn lực của công ty (nhân sự, tài chính) để phục vụ cho việc nghiên cứu và phát triển công nghệ.\n- Được đề xuất hoặc tham gia vào các dự án hoặc business mới của công ty trong tương lai.\n- Được hưởng stock option theo cống hiến.\n- Tham gia vai trò chính trong việc tư vấn, xây dựng dự án từ giai đoạn đầu tiên.\n- Tham gia nhiều chương trình đào tạo công nghệ, phương pháp làm việc.\n- Được tham gia các chương trình đào tạo đa dạng và có nhiều cơ hội thăng tiến.\n- Cơ hội đi công tác tại Nhật Bản.\n\nĐịa điểm làm việc\n- Hà Nội: Tháp A Keangnam, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm "Ứng tuyển" ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3214, 1149, 2, 'React Native Developer', 'Mô tả công việc:\n- Tham gia phát triển và tối ưu hóa ứng dụng mobile cross-platform (iOS & Android) bằng React Native.\n- Tham gia xây dựng kiến trúc, tổ chức mã nguồn và thiết kế module phù hợp với quy mô sản phẩm.\n- Hợp tác với đội ngũ thiết kế (UI/UX) để biến bản thiết kế thành sản phẩm thực tế mượt mà, trực quan.\n- Tích hợp API, làm việc chặt chẽ với backend để xử lý dữ liệu hiệu quả và đồng bộ.\n- Viết mã sạch, dễ bảo trì, có khả năng tái sử dụng và viết test khi cần thiết.\n- Tham gia vào các buổi họp sprint, đánh giá và cải tiến quy trình làm việc.\n- Theo dõi lỗi sản phẩm, xử lý phản hồi từ người dùng và hỗ trợ bảo trì ứng dụng.\n\nYêu cầu ứng viên:\n- CÓ TỪ 1 ĐẾN 3 NĂM KINH NGHIỆM LÀM VIỆC VỚI REACT NATIVE.\n- Đã tốt nghiệp hoặc đang chờ bằng cao đẳng/đại học.\n- Thành thạo JavaScript (ES6+), nắm rõ React Hooks, Context API.\n- Có kinh nghiệm với Redux / Zustand / Recoil, hiểu nguyên tắc quản lý state hiệu quả.\n- Hiểu biết tốt về cấu trúc dự án mobile, quản lý dependencies, build tool (Metro, Gradle, Fastlane).\n- Đã từng tích hợp REST API, WebSocket, Firebase hoặc các dịch vụ bên thứ ba.\n- Biết deploy ứng dụng lên App Store và Google Play (là một lợi thế lớn).\n- Có khả năng đọc hiểu tài liệu kỹ thuật tiếng Anh tốt.\n- Chủ động trong công việc, có tư duy giải quyết vấn đề và trách nhiệm cao.\n\nĐiểm cộng nếu bạn có:\n- Kinh nghiệm với TypeScript, Expo, hoặc native module (Java/Kotlin, Swift).\n- Hiểu biết về CI/CD cho mobile app, Firebase Analytics, Crashlytics.\n- Kinh nghiệm A/B testing, performance monitoring, push notification, deep linking.\n- Có khả năng giao tiếp tiếng Anh là một lợi thế.\n\nQuyền lợi:\n- Mức lương:\n	- Đối với ứng viên có từ 1 đến 2 năm kinh nghiệm: 7 - 13 triệu.\n	- Đối với ứng viên có từ 2 đến 3 năm kinh nghiệm: 14 - 18 triệu.\n- Đóng bảo hiểm y tế, bảo hiểm xã hội.\n- Review lương 1 năm/lần.\n- Thưởng các dịp lễ Tết, thưởng quý, thưởng thâm niên.\n- Quà tặng dịp sinh nhật cá nhân.\n- Cơ hội được học hỏi, làm việc với công nghệ mới.\n- Được làm việc trong một môi trường chuyên nghiệp với các đối tác nước ngoài.\n- Du lịch, teambuilding 2-3 lần/năm.\n- Hỗ trợ tham gia các khóa đào tạo nâng cao kiến thức và kỹ năng.\n\nĐịa điểm làm việc:\n- Hà Nội: Tây Mỗ, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:30 đến 18:30)\n- Đi làm 2 ngày thứ 7 trong tháng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Nam Từ Liêm', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3215, 1131, 2, 'Backend Developer', 'Mô tả công việc\n\n-Thiết kế và phát triển: Xây dựng kiến trúc backend và các API hỗ trợ cho các ứng dụng và dịch vụ frontend.\n- Phát triển tính năng: Tham gia phát triển các tính năng mới của hệ thống backend và cải tiến các chức năng hiện có theo yêu cầu của dự án.\n- Tối ưu hóa mã nguồn: Cải thiện hiệu suất mã nguồn và đảm bảo hệ thống hoạt động ổn định.\n- Tích hợp hệ thống: Làm việc với nhóm frontend và QA để tích hợp các dịch vụ backend với các hệ thống frontend và đảm bảo tính đồng nhất.\n- Bảo trì hệ thống: Hỗ trợ giám sát và khắc phục các sự cố kỹ thuật để đảm bảo tính ổn định và hiệu quả của hệ thống backend.\n- Quản lý cơ sở dữ liệu: Thiết kế và tối ưu hóa cơ sở dữ liệu, xử lý dữ liệu lớn và đảm bảo tính toàn vẹn của dữ liệu.\n\nYêu cầu ứng viên\n\n- Tốt nghiệp Cao đẳng trở lên chuyên ngành Công nghệ thông tin, Điện tử viễn thông hoặc tương đương.\n- Kinh nghiệm: 2-4 năm kinh nghiệm phát triển backend với các công nghệ và frameworks như Java, Python, Node.js hoặc tương đương.\n- Kỹ năng lập trình: Thành thạo một hoặc nhiều ngôn ngữ backend (Java, Python, Node.js, Go, v.v.), có kinh nghiệm làm việc với API RESTful.\n- Cơ sở dữ liệu: Hiểu biết về các hệ quản trị cơ sở dữ liệu JAVA, SQL và NoSQL như MySQL, PostgreSQL, MongoDB, v.v.\n- Kiến thức về kiến trúc hệ thống: Có kiến thức cơ bản về microservices và các mô hình thiết kế hệ thống backend.\n- Công nghệ DevOps: Có kinh nghiệm cơ bản với các công cụ CI/CD, Docker hoặc các công nghệ tương tự là một lợi thế.\n- Bảo mật: Có hiểu biết cơ bản về bảo mật dữ liệu và bảo mật API.\n- Kỹ năng mềm: Kỹ năng làm việc nhóm tốt, cởi mở trong giao tiếp và chủ động học hỏi.\n\nQuyền lợi\n\n- Mức lương cạnh tranh, \n- Lương tháng 13\n- Hỗ trợ đầy đủ trang thiết bị làm việc PC/ Laptop…. \n- Đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- 12 ngày phép/ năm và Thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Làm việc thứ 2 đến sáng Thứ 7\n- Phụ cấp gửi xe; Phụ cấp cơm trưa, ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Khám sức khỏe định kỳ 1 lần/năm\n- Du lịch nghỉ mát 1 lần/ năm.\n- Tổ chức teambuilding định kỳ, tổ chức sinh nhật, team lunch, …\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động, nhiều cơ hội thăng tiến\n- Đội ngũ kỹ sư, nhân viên tài năng, giàu kinh nghiệm\n- Làm việc với tác đối tác lớn\n- Review tăng lương định kỳ hàng năm (1 lần / năm)\n\nĐịa điểm làm việc\n\n- Hà Nội: 19 Vũ Trọng Phụng, Thanh Xuân, Thanh Xuân\n\nThời gian làm việc\n\nThứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3216, 1165, 2, 'Nhân Viên Lập Trình Front-End', 'Mô tả công việc:\n- Phối hợp với đội nhóm để phân tích yêu cầu của dự án, xây dựng kiến trúc và tổng hợp thành tài liệu.\n- Chịu trách nhiệm phát triển, tối ưu và duy trì hệ thống Frontend cho ứng dụng web.\n- Trao đổi với quản lý dự án và tiến hành phân tích thiết kế và triển khai các giải pháp để có thể tạo giao diện tối ưu về UI/UX. Tạo ra các component có thể tái sử dụng trong quá trình thực hiện dự án.\n- Đánh giá yêu cầu xây dựng (đánh giá được hết tất cả các trường hợp, hiểu bản chất của vấn đề), sửa đổi tính năng.\n- Xử lý lỗi phát sinh trong quá trình vận hành\n- Tìm kiếm các phương án tối ưu nhằm nâng cao giải pháp, hiệu suất cho quá trình phát triển sản phẩm\n- Nghiên cứu, cập nhật các xu hướng, công nghệ liên quan đến phát triển sản phẩm.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học/cao đẳng các chuyên ngành Công nghệ thông tin, Khoa học máy tính, Điện tử viễn thông, Công nghệ phần mềm, Hệ thống thông tin...\n- Độ tuổi từ 23-30 tuổi.\n- Tối thiểu 1 - 3 năm kinh nghiệm phát triển ứng dụng frontend sử dụng ReactJS, VueJS, Angular.\n- Thành thạo HTML, CSS (SCSS, Tailwind, …), JavaScript.\n- Có kinh nghiệm với quản lý state phức tạp (Redux, Zustand, Vuex, Pinia), hiểu rõ luồng dữ liệu trong một SPA.\n- Thành thạo sử dụng AI trong công việc.\n- Thành thạo tích hợp nhiều loại API (REST/GraphQL/…) và hiểu rõ cách xử lý dữ liệu bất đồng bộ.\n- Có tư duy tối ưu giao diện: responsive, cross-browser, thân thiện với SEO (có kinh nghiệm SSR với Nuxt.js/Next.js là điểm cộng lớn).\n- Có khả năng đọc hiểu tiếng Anh & sử dụng tốt công cụ tìm kiếm để giải quyết vấn đề.\n- Có ý thức lập trình viết code theo cấu trúc, theo tài liệu, dễ dàng nâng cấp (clean code).\n- Kỹ năng giải quyết tốt và khả năng làm việc độc lập cũng như làm việc nhóm.\n- Có khả năng giao tiếp và hợp tác cùng các đội nhóm khác.\n- Chủ động, trung thực và có ý thức cầu tiến.\n\nQuyền lợi:\n- Thời gian làm việc: 8h00 - 17h00 Từ thứ 2 đến thứ 6, được nghỉ T7&CN\n- Cơ hội huấn luyện: Cơ hội tham gia các chương trình đào tạo trong nước và nước ngoài, đặc biệt dành cho lập trình viên.\n- Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện, hòa đồng\n- Thu nhập theo năng lực và hiệu quả công việc.\n- Đảm bảo đầy đủ quyền lợi của người lao động theo quy định của Nhà nước.\n- Khám sức khỏe định kỳ hàng năm và tham gia thêm gói bảo hiểm chăm sóc sức khỏe BIC.\n- Tham gia các hoạt động teambuilding, bonding, CLB đá bóng hàng tuần tại Công ty.\n- Phụ cấp khác: Phụ cấp cơm trưa, gửi xe, sinh nhật, công tác phí và các phụ cấp khác cho người lao động.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 614 Điện Biên Phủ, Quận 10\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3217, 1171, 2, 'Android Developer (Junior Level)', '-Key Responsibilities :\nDevelop and maintain Android applications using Java or Kotlin.\nWrite clean, well-documented, and testable code.\nCollaborate with the team to design, implement, and test new features.\nTroubleshoot and fix bugs.\nEnsure application performance, quality, and user experience.\nStay up-to-date with the latest Android technologies and best practices.\n\n-Requirements:\nUniversity graduate with computer science, software, application programming related major.\nGood background knowledge about Design pattern, Data structures and Algorithms.\nGood for logical thinking and problem-solving.\nAbility to self-learn and adapt to new technologies quickly.\nBeing able to use English for work.\nExperience in native Android development with Java/Kotlin.\nKnowledge of Android SDK, different versions of Android, and how to deal with different screen sizes.\nUnderstanding of Object Oriental Programming, Data Structures & Algorithms.\nExperience with REST/SOAP-based web services, AJAX and JSON.\nExperience with source code control systems such as SVN, CVS or Git.\nGood familiarity with third-party libraries and APIs, such as OKHTTP, RxJava, Firebase, Coroutine.\nKnowledge of security and experience in writing secure and efficient codes.\nExperience in implementing & maintaining Android Continuous Integration and Deployment process.\n\n-Benefits:\nCompetitive negotiable salary.\nFull benefits package (Health care insurance, Life Insurance, Social Insurance etc.)\nSupportive team environment that values collaboration and growth.\nCompany trips, Happy lunch (twice a month), Milk-tea fund...\n\nĐịa điểm làm việc:\n- Đà Nẵng: Astraler Technology Co. Ltd - 6th Floor - Viet Nam Post Building - 271 Nguyen Van Linh street, Vinh Trung ward, Thanh Khe District, Danang, Thanh Khê\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nWorking Hours: 8:00 AM – 5:30 PM, Monday to Friday.\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3218, 1424, 2, 'Unity Developer', 'Mô tả công việc: Lập trình game online - multiplayer trên nền tảng Unity. Phát triển các dự án game với hạ tầng kĩ thuật cho hàng triệu User. Môi trường Agile - trẻ năng động, linh hoạt. Có cơ hội phát triển thành Full-Stack Developer.\n\nYêu cầu ứng viên: Kinh nghiệm làm việc với Unity tối thiểu 2 năm. Nắm chắc cấu trúc dữ liệu giải thuật và các thuật toán phổ biến. Nắm chắc lập trình hướng đối tượng và các design pattern phổ biến. Hiểu và sử dụng tốt Git Flow. Có khả năng đọc hiểu tiếng Anh. Có tinh thần trách nhiệm; Chịu áp lực cao trong công việc. Làm việc độc lập, làm việc nhóm tốt. Cởi mở, sẵn sàng học tập, chia sẻ công nghệ mới. Thích chơi game, có kiến thức về game là lợi thế. Có sản phẩm/dự án thành công của cá nhân hoặc công ty là lợi thế.\n\nQuyền lợi: Lương thỏa thuận tùy theo năng lực. Review liên tục công việc, lương thưởng. Được tham gia các chương trình đào tạo nâng cao năng lực, phát triển bản thân; Có cơ hội thăng tiến lên các vị trí trưởng nhóm, quản lý. Môi trường Agile - Năng động, Linh hoạt. Phát huy tối đa khả năng và tính sáng tạo của nhân tài. Team building hàng quý, du lịch hàng năm trong hoặc ngoài nước. Hưởng tất cả các chế độ bảo hiểm xã hội, y tế theo quy định của nhà nước, khám sức khỏe định kỳ hàng năm.\n\nĐịa điểm làm việc: - Hà Nội: 23 Duy Tân - Dịch Vọng Hậu, Cầu Giấy.\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3219, 1406, 2, 'Software Engineer', '- Receive and take over the WMS system source code from the current development team.\n- Analyze system architecture, understand backend, frontend, database components, and API connections.\n- Modify, maintain, or develop new features based on user requests.\n- Work closely with internal departments to gather requirements, analyze feasibility, and implement technical solutions.\n- Ensure system stability, perform data backups, monitor logs, and resolve technical issues.\n- Write technical documents and user manuals, and standardize operational procedures.\n- Participate in periodic meetings to report system status, propose improvements, and identify risks.\n- Identify causes of issues (system, software, user acces, etc.).\n- Advise employees on appropriate actions.\n- Provide guidance on all company-supported applications.\n- Develop processes, regulations, and guidelines for system operation and administration, related to business functions.\n- Compile and report on expenses as requested by the Head of Department.\n- Manage and archive assigned related documents.\n- Perform other tasks assigned by the Head of Department.\n\nYêu cầu ứng viên:\n- Bachelor’s degree in Computer Science, Information Technology, or related fields.\n- At least 3 years of hands-on experience in software development and system maintenance.\n- Proficient in at least one backend programming language PHP, C# (Java/Python), with basic frontend skills (HTML/CSS/JavaScript; React is a plus).\n- Experienced with relational database systems (SQL Server, MySQL, or equivalent).\n- Strong system thinking: ability to understand data flows, logic, and module interconnections.\n- Good communication skills with internal users to collect requirements and deliver effective solutions.\n- Experience in enterprise software maintenance projects is an advantage.\n\nQuyền lợi:\n- Thưởng theo hiệu suất công việc\n- Đóng bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm tai nạn theo quy định nhà nước\n- Tham gia Company trip/Company Outing\n\nĐịa điểm làm việc:\n- Bình Dương: Lot G7, Road 06, Song Than 2 IDZ, Di An Ward, Di An City, Binh Duong Province, Dĩ An\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3220, 1200, 2, 'Middle Flutter', 'Mô tả công việc: Tham gia các dự án phát triển ứng dụng di động (cả iOS và Android), trực tiếp phát triển và hỗ trợ các thành viên trong nhóm gồm 03 - 06 thành viên. Tham gia phân tích nghiệp vụ, đề xuất giải pháp, phương án triển khai nhằm cải tiến, nâng cao hiệu quả của các dự án. Phối hợp cùng các nhà cung cấp triển khai các giải pháp Công nghệ. Nghiên cứu, thử nghiệm áp dụng các xu hướng công nghệ mới.\n\nYêu cầu ứng viên: Kinh nghiệm tối thiếu 02 năm kinh nghiệm phát triển ứng dụng di động. Kiến thức và kỹ năng lập trình: Thành thạo ngôn ngữ lập trình Dart và framework Flutter2 hoặc Native. Có kiến thức về lập trình hướng đối tượng, cấu trúc dữ liệu và giải thuật. Kinh nghiệm làm việc: Có kinh nghiệm làm việc với các hệ điều hành di động (Android/iOS), vòng đời ứng dụng và các thành phần chính của hệ điều hành. Kinh nghiệm tích hợp với các hệ thống Firebase (Push notification, analytics, authentication), OneSignal. Có kinh nghiệm đưa ứng dụng lên Apple Store và Play Store. Kinh nghiệm làm việc với RESTful API và các công cụ quản lý phiên bản như Git.\n\nQuyền lợi: Mức lương thoả thuận. Thời gian làm việc: 8h00-17h30, nghỉ trưa 1,5h (12h – 13h30) từ thứ 2 - thứ 6. 13 tháng lương + thưởng lễ tết; xét tăng lương hàng năm. Du lịch hàng năm, team building hàng tháng/quý. Bảo hiểm xã hội, BHYT theo quy định của Nhà nước. Gói bảo hiểm sức khỏe. Khám sức khoẻ định kỳ hàng năm. Môi trường flat trẻ trung, thoải mái. Cơ hội tham gia dự án tiềm năng, thử thách nhưng không kém phần thú vị.\n\nĐịa điểm làm việc: Hà Nội: Lê Đức Thọ, Nam Từ Liêm\n\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3221, 1352, 2, 'Full-Stack Developer (.Net, ReactJs)', 'VỀ AWING\nAWING dẫn đầu trong lĩnh vực tiếp thị di động, chuyên về quảng cáo qua Wi-Fi thông qua tư vấn chiến lược truyền thông thương hiệu cho doanh nghiệp, quảng cáo và triển khai hạ tầng Wi-Fi miễn phí tốc độ cao tại các địa điểm cao cấp trên toàn quốc. Để mở rộng phạm vi dịch vụ, AWING đã tích hợp phần mềm quản lý chiến dịch AWING Campaign Management (ACM) tự phát triển với các triển khai Wi-Fi miễn phí khác, tạo ra một mạng lưới quảng cáo rộng lớn phục vụ khách hàng trung và cao cấp. Ngoài việc cung cấp Wi-Fi miễn phí tốc độ cao, AWING còn mang đến những tiện ích giúp người dùng có trải nghiệm thân thiện nhất với các hệ thống bản đồ số phát triển trong các trung tâm mua sắm. Chất lượng và tiện ích thực tiễn của hệ thống AWING giúp quá trình quảng cáo và truyền tải thông điệp thương hiệu đến người tiêu dùng trở nên dễ dàng và hiệu quả hơn.\n\nTrong năm 2024, AWING nhận được khoản đầu tư lớn từ NTT e-Asia (Công ty trực thuộc Tập đoàn viễn thông NTT), chính thức trở thành đối tác kinh doanh chiến lược, hỗ trợ AWING mở rộng sang thị trường trong khu vực ASEAN. Với sự hợp tác này, AWING sẽ được tiếp cận với hỗ trợ công nghệ và các sáng kiến phát triển thị trường từ NTT e-Asia, đảm bảo rằng AWING có đầy đủ nguồn lực và chuyên môn cần thiết để phát triển mạnh mẽ trong thị trường ASEAN đầy cạnh tranh.\n\nBẠN HÃY VỀ VỚI AWING\nVới chiến lược mở rộng kinh doanh sang các nước trong khu vực, AWING đang có những bước tiến lớn trong việc mở rộng nhân sự cũng như thị trường sang các nước ASEAN. Đây là cơ hội tuyệt vời để bạn gia nhập công ty và trở thành một phần của giai đoạn phát triển thú vị này. Khi gia nhập bạn sẽ có cơ hội học hỏi và phát triển nhanh chóng, tận dụng nhiều cơ hội thăng tiến trong sự nghiệp lên các vị trí quản lý cấp cao. AWING hiện có phúc lợi cạnh tranh, môi trường làm việc năng động và cam kết phát triển chuyên môn, những điều này giúp cho công ty trở thành nơi lý tưởng để bạn xây dựng sự nghiệp vững chắc.\n\nCHI TIẾT CÔNG VIỆC\n- Tham gia vào quy trình phân tích, thiết kế và phát triển các sản phẩm phần mềm của công ty.\n- Phối hợp chặt chẽ với đội ngũ backend & frontend để tích hợp giao diện người dùng với các API.\n- Tối ưu hóa hiệu suất hệ thống nhằm đảm bảo tốc độ truy cập cao và tiết kiệm tài nguyên.\n- Nghiên cứu và áp dụng các công nghệ mới nhằm cải tiến và nâng cao chất lượng sản phẩm.\n- Xây dựng và duy trì cơ sở dữ liệu, đảm bảo tính bảo mật và hiệu suất.\n- Viết và duy trì tài liệu kỹ thuật và tài liệu hướng dẫn sử dụng.\n- Thực hiện kiểm thử và gỡ lỗi (debug) để đảm bảo sản phẩm hoạt động ổn định và không có lỗi.\n- Hỗ trợ và giải quyết các vấn đề kỹ thuật phát sinh trong quá trình vận hành sản phẩm.\n- Đóng góp ý tưởng và giải pháp để cải tiến quy trình phát triển và tối ưu hóa hệ thống.\n\nYÊU CẦU ỨNG VIÊN\n- Tốt nghiệp đại học hoặc cao đẳng chuyên ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- Có ít nhất 3 năm kinh nghiệm làm việc với Backend (sử dụng .NET Core, C#).\n- Có ít nhất 1 năm kinh nghiệm làm việc với Frontend (sử dụng ReactJS, TypeScript).\n- Kiến thức vững chắc về SQL và hệ quản trị cơ sở dữ liệu quan hệ (RDBMS) như MySQL.\n- Kinh nghiệm làm việc với Apache Kafka hoặc bất kỳ giải pháp Message Queue nào.\n- Có kinh nghiệm trong thiết kế và phát triển các ứng dụng có độ sẵn sàng cao, khả năng mở rộng, hiệu suất cao và độ trễ thấp.\n- Tư duy sản phẩm tốt, khả năng phân tích và giải quyết vấn đề hiệu quả.\n\nQUYỀN LỢI\n- Lương thỏa thuận lên đến 2500 USD/tháng.\n- Lương tháng 13, thưởng quý theo kết quả kinh doanh.\n- Xét tăng lương hàng năm theo thành tích đóng góp.\n- Điều kiện làm việc linh hoạt.\n- Môi trường sáng tạo, năng động.\n- Thường xuyên tổ chức du lịch, team building.\n- Cơ hội thăng tiến lên vị trí Leader, Manager.\n- Chính sách thưởng cổ phần cho Key member, có đóng góp quan trọng cho công ty.\n- Phụ cấp ăn trưa.\n- Hưởng đầy đủ các chế độ đãi ngộ theo quy định của pháp luật.\n\nĐỊA ĐIỂM LÀM VIỆC\n- Hà Nội: King Building, Số 7 P. Chùa Bộc, Kim Liên, Đống Đa, Đống Đa.\n\nTHỜI GIAN LÀM VIỆC\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:30).\n- Break time: 1.30h.\n\nCÁCH THỨC ỨNG TUYỂN\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3222, 1385, 2, 'Chuyên Viên Lập Trình', 'Mô tả công việc\n- Tham gia phát triển các dự án từ Thiết kế cơ bản, Thiết kế chi tiết, Phát triển đến Triển khai.\n- Lập trình WinForm, Ứng dụng di động, Web, thiết kế báo cáo tích hợp SAP ECC (SAP Crystal Report), quản lý, chỉnh sửa, bảo trì và phát triển phần mềm liên quan đến sản xuất và IoT.\n- Thiết kế và phát triển Web API cho ứng dụng Mobile App, Web App.\n- Lập trình chức năng mới hoặc nâng cấp và chỉnh sửa tính năng hiện có (SAP/MES/HR/Web…).\n- Hỗ trợ và xử lý các vấn đề liên quan đến hệ thống ERP (SAP ECC/IRS).\n- Hỗ trợ Trưởng phòng IT trong việc tư vấn, thiết kế, triển khai, giám sát, hỗ trợ và đào tạo liên quan đến phát triển, nâng cấp và tối ưu phần mềm.\n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học ngành Công nghệ Thông tin hoặc các ngành liên quan.\n- 5 năm kinh nghiệm tại vị trí tương đương (trong đó có ít nhất 3 năm kinh nghiệm làm việc với PHP/Python/.NET và quản lý dự án có từ 3 lập trình viên trở lên).\n- Thành thạo tiếng Anh trong việc đọc và hiểu tài liệu chuyên ngành.\n- Thành thạo Git, HTML, CSS, JavaScript (JQuery,...), Bootstrap, JSON, XML.\n- Kiến thức vững chắc về API (Application Programming Interface); cơ sở dữ liệu (SQL, PostgreSQL, DB2); ngôn ngữ lập trình (C++, C#, .NET, Java, Ruby on Rails, v.v.); lập trình hướng đối tượng (OOP) và mô hình kiến trúc 3 tầng.\n- Có kinh nghiệm hỗ trợ hệ thống SAP, phát triển báo cáo mới, phát triển Web với framework (ReactJS, NextJS, Spring MVC).\n- Ưu tiên ứng viên có kinh nghiệm sử dụng Restful API, DB2, SQL, HTML5, CSS3, JavaScript, jQuery, AJAX, JSON và kinh nghiệm phân tích thiết kế cơ sở dữ liệu & prototype.\n- Có kinh nghiệm quản lý dự án phần mềm và triển khai phần mềm sản xuất (IOT & MES) là một lợi thế.\n\nQuyền lợi\n- Xe đưa đón TP.HCM – Biên Hòa\n- Laptop, tiền xăng xe, tiền điện thoại phục vụ công việc\n- 16 ngày phép có hưởng lương trong 1 năm\n- Bảo hiểm chăm sóc sức khỏe MSIG & Bảo hiểm tai nạn\n- Chế độ work from home & giờ làm việc linh hoạt\n- Thưởng chuyên cần và năng suất chất lượng hàng tháng\n- Lương tháng 13 & Thưởng bonus\n- Tham quan du lịch và teambuilding hàng năm\n- Quà nhân dịp sinh nhật, lễ, Tết,…\n\nĐịa điểm làm việc\n- Đồng Nai: 231-237 KCN Amata, Biên Hòa, Biên Hoà\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 07:30 đến 16:15)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Nai', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3223, 1451, 2, 'Nhân Viên Phần Mềm', '+ Triển khai, vận hành, xử lý lỗi, sự cố,... và các phần mềm ứng dụng khác trong công ty.\n+ Lập trình các phần mềm ứng dụng theo nhu cầu hoạt động sản xuất kinh doanh của Công ty.\n+ Hỗ trợ lắp đặt thiết bị, vận hành, hướng dẫn sử dụng các phần mềm ứng dụng trong công ty.\n\nYêu cầu ứng viên:\n- Trình độ chuyên môn: Tốt nghiệp Đại học chuyên ngành Công nghệ thông tin\n- Hiểu biết về: phần mềm quản lý doanh nghiệp ERP\n- Ngoại ngữ: ưu tiên ngoại ngữ lưu loát là lợi thế\n- Tin học: trình độ A hoặc các chứng chỉ tương đương trở lên\n- Kinh nghiệm: ít nhất 1 năm kinh nghiệm ở vị trí tương đương.\n- Tuổi: không quá 35 tuổi.\n- Sức khỏe: tốt, đáp ứng được yêu cầu sức khỏe đầu vào của công ty\n- Tính cách: sáng tạo, linh hoạt\n\nQuyền lợi:\n- Mức lương: Lương cạnh tranh + thưởng theo kết quả kinh doanh, tùy thuộc vào năng lực của từng ứng viên\n- Hỗ trợ tiền nhà cho các ứng viên chấp nhận điều động đi công tác xa.\n- Được đào tạo trong thời gian thử việc và các đào tạo thực tế trong khi làm việc theo chương trình đào tạo hàng năm của công ty.\n- Được trang bị đồng phục và các công cụ, thiết bị hỗ trợ để phục vụ cho quá trình làm việc\n- Được đóng BHXH, BHYT, BHTN theo quy định của Nhà nước.\n- Mua bảo hiểm tai nạn 24 giờ ngay khi làm việc\n- Được hưởng các khoản phụ cấp theo quy định của Nhà nước và các phụ cấp khác theo quy định của công ty.\n- Thưởng tháng lương thứ 13 (theo thực tế tháng làm việc trong năm)\n- Được khen thưởng đột xuất cho các sáng kiến, cải tiến kỹ thuật mang lại hiệu quả cao cho hoạt động sản xuất kinh doanh.\n- Các chính sách thưởng khác theo quy định của công ty, thưởng các ngày lễ trong năm và theo thực tế tháng làm việc của thời gian xét thưởng.\n- Các phúc lợi liên quan: du lịch, quà sinh nhật ....\n\nĐịa điểm làm việc:\n- Đồng Tháp: Số 346, đường Nguyễn Huệ, Phường Mỹ Phú, TP Cao Lãnh\n- Hồ Chí Minh: 37, Thành Thái, Quận 10\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đồng Tháp, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3224, 1193, 2, 'Home Trading System Developer (Frontend - JavaScript)', 'Mô tả công việc\n- Develop a Trading Desktop Application using JavaScript on an internal platform built with C++\n- Work directly with remote team to clarify tasks and requirements\n- Develop new features based on the user requirements. (analyzing requirements and system design)\n- Fix the reported problems/bugs of the system during the integration test, the user acceptance test, and the test for maintenance (need to communicate with backend developers and testers)\n- Managing time and resources based on the WBS\n- Compile a weekly-report about the progress of tasks\n- Perform self-learning about a domain knowledge, write a report and conduct a seminar about it\n- Write high-quality, clean, elegant, maintainable, and testable code\n- Maintaining technical documents up-to-date Mentor junior developers and conduct technical training when needed\n- You will have the chance to be involved with each stage of different projects, to various aspects of software engineering and fostering your career growth.\n\nYêu cầu ứng viên\nSkill Required\n- Minimum 3 years experience on developing with Javascript.\n- Strong understanding of object-oriented programming and design pattern (MVC, MVVM).\n- Ability to write clean, easy to understand code.\n- Familiarity with version control systems, such as SVN.\n- Familiarity with issues tracking tools, such as Redmine.\n- Strong problem-solving and analytical skills.\n- Bachelor\'s Degree in Computer Science/Information Technology or relevant fields.\n- Able to communicate in English, written and spoken (processed by English interview).\n- Strong communication skills and teamwork, international experience is preferred.\n- Experience operating in an Agile environment, with a deep understanding of agile development principles.\n\nGive Reference\n- Over 1 year of experience in developing securities solutions, including a PC-based trading platform – HTS(Home Trading System).\n- Experience on developing with MFC C++.\n- Experience on working with oversea team.\n\nMission\n- Supporting IT Development and Maintenance of the Stock Trading Platform developed based on the Kiwoom Framework for Kiwoom Indonesia, Finansia(in Thailand), and so on\n\nQuyền lợi\n- Competitive salary, salary review once a year\n- 13th month salary and Annual Performance Bonus\n- Full SHUI as Vietnamese Law\n- PVI - Premium Private Medical Insurance and annual health check\n- 15-day annual leave, Christmas leave and 30-mins menstrual leave for women\n- MVP and Shining star awards at the end of year\n- Global and professional working environment\n- Company trip, YEP and monthly gathering time\n- Gifts on special occasion and fully stocked snack corner\n- Sponsored training courses and book purchase quarterly\n- Be well-equipped with new working equipment\n\nSPECIAL OFFER\n- Providing training and education experience in Korea with Korean Finance/IT expert \n- Providing opportunities to work and support in IT/Finance fields overseas\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tầng 14, tòa nhà AP, 518B Điện Biên Phủ, Phường 21, Bình Thạnh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3225, 1290, 2, 'Front End Developer', 'Chúng tôi đang tìm kiếm một Vue.js Developer đầy nhiệt huyết và tiềm năng để tham gia vào đội ngũ phát triển của chúng tôi. Bạn sẽ có cơ hội làm việc trên các ứng dụng web hiện đại, thân thiện với người dùng và sử dụng framework Vue.js. Đồng hành cùng các lập trình viên cấp cao, bạn sẽ xây dựng những giao diện hiệu quả, mở rộng và hấp dẫn.\n\n- Phát triển và duy trì các ứng dụng web sử dụng Vue.js và các công nghệ liên quan.\n- Phối hợp với đội ngũ thiết kế, quản lý sản phẩm và lập trình viên backend để tạo ra trải nghiệm người dùng mượt mà.\n- Viết mã sạch, dễ bảo trì và hiệu quả.\n- Gỡ lỗi và giải quyết các vấn đề nhằm đảm bảo hiệu suất và trải nghiệm người dùng tối ưu.\n- Tham gia review mã nguồn và đóng góp cải thiện tiêu chuẩn nhóm.\n- Cập nhật kiến thức về các xu hướng và thực tiễn tốt nhất trong Vue.js và phát triển frontend.\n\nYêu cầu ứng viên\n\n- Kỹ năng chuyên môn\n- Thành thạo Vue.js, Vue Router và Vuex (hoặc Pinia).\n- Kinh nghiệm chuyên sâu với HTML5, CSS3, JavaScript (ES6+), và TypeScript.\n- Hiểu biết sâu về tích hợp API, WebSocket, GraphQL, hoặc các dịch vụ tương tự.\n- Kinh nghiệm với các công cụ quản lý mã nguồn như Git và quy trình CI/CD.\n- Sử dụng thành thạo các framework UI như AntDesignVue, Vuetify, Tailwind CSS hoặc BootstrapVue.\n- Hiểu biết về kiến trúc microservices và Docker là một lợi thế.\n- Kỹ năng giải quyết vấn đề và phân tích tốt.\n- Sẵn sàng học hỏi và thích nghi với các công nghệ, công cụ mới.\n- Có khả năng làm việc độc lập cũng như làm việc nhóm.\n- Kỹ năng giao tiếp tốt và thái độ chủ động trong công việc.\n- Tinh thần chủ động, sẵn sàng đón nhận thử thách và học hỏi công nghệ mới.\n\nƯu tiên (không bắt buộc)\n- Có kinh nghiệm với các thư viện giao diện người dùng như Ant Design.\n- Kiến thức về các framework kiểm thử như Jest hoặc Cypress.\n\nQuyền lợi\n- Lương thỏa thuận cạnh tranh theo năng lực\n- Thưởng lễ tết, bonus cuối năm\n- Bảo hiểm sức khỏe, BHXH đầy đủ theo luật lao động\n- Được đào tạo trực tiếp nâng cao/bổ sung các kiến thức về ngành nghề\n- Đánh giá năng lực, xét tăng lương/thưởng theo quy định của Công ty\n\nĐịa điểm làm việc\n- Hà Nội: Tòa nhà Tasco, Nam Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3226, 363, 2, 'IT System & Solution Leader/ Leader Hệ Thống & Giải Pháp CNTT', '1. Tiếp nhận và quản trị hệ thống giải pháp/phần mềm Công ty đã phát triển\n2. Cập nhật, đánh giá và đề xuất cải tiến giải pháp/phần mềm\n3. Tham gia thiết kế, phát triển module/sản phẩm mới \n4. Theo dõi, giám sát hoạt động hệ thống, phần mềm, phát hiện và xử lý sự cố kịp thời\n5. Xử lý các sự cố liên quan đến hệ thống mạng LAN/WAN, database, server\n6. Đánh giá, tối ưu hiệu năng ứng dụng và hệ thống backend\n7. Hỗ trợ team dev trong việc troubleshoot, debug và tối ưu code\n8. Nghiên cứu công nghệ mới và đề xuất cải tiến hệ thống\n9. Phân tích luồng nghiệp vụ, đề xuất giải pháp kỹ thuật phù hợp\n10. Thực hiện demo, triển khai setup hệ thống cho đối tác, khách hàng khi có yêu cầu\n11. Tư vấn, triển khai các giải pháp công nghệ, sản phẩm phục vụ chiến lược chuyển đổi số, số hóa quy trình hoạt động của công ty\n12. Nghiên cứu, đề xuất các sáng kiến cải tiến hạ tầng, hệ thống CNTT nhằm nâng cao năng suất, hiệu quả.\n\n- Tốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT, Kỹ thuật phần mềm hoặc lĩnh vực liên quan.\n- Có ít nhất 03 năm kinh nghiệm ở vị trí quản trị hệ thống, hạ tầng, hỗ trợ người dùng.\n- Có ít nhất 01 năm kinh nghiệm team leader ngành CNTT.\n- Kinh nghiệm quản trị Windows Server, Active Directory, email server, cloud service cơ bản (Google Workspace, Office 365, AWS/Azure cơ bản).\n- Khả năng xử lý sự cố hệ thống, phần mềm, mạng, hỗ trợ người dùng hiệu quả.\n- Kỹ năng giao tiếp, phối hợp nhóm, hỗ trợ người dùng tốt.\n- Có kinh nghiệm triển khai, demo giải pháp CNTT cho khách hàng/đối tác là một lợi thế.\n- Am hiểu các giải pháp bảo mật, firewall, VPN, NAS, backup, DRP.\n- Tư duy chủ động, ham học hỏi công nghệ mới, sẵn sàng nghiên cứu các giải pháp chuyển đổi số.\n- Sẵn sàng đi công tác khi có yêu cầu.\n\n- Mức lương cạnh tranh (tùy theo năng lực).\n- Tham gia đầy đủ chế độ BHXH, BHYT, BHTN theo quy định.\n- Môi trường làm việc chuyên nghiệp, năng động, nhiều cơ hội phát triển nghề nghiệp.\n- Cơ hội tham gia các dự án công nghệ mới, giải pháp chuyển đổi số tiên tiến.\n- Được đào tạo, nâng cao kiến thức về hệ thống, giải pháp, kỹ năng mềm.\n\n- Hồ Chí Minh: 120 Nguyễn Minh Hoàng, Phường 12, Tân Bình\n\n- Từ Thứ 2 đến sáng Thứ 7 hàng tuần.\n- Thời gian: 8h đến 17h.\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3227, 1412, 2, 'Fullstack NodeJS Developer', '- Participate in the entire application lifecycle, focusing on coding and debugging\n- Write clean code to develop functional web applications\n- Troubleshoot and debug applications\n- Manage cutting-edge technologies to improve legacy applications\n- Gather and address technical and design requirements\n- Provide training and support to internal teams\n- Build reusable code and libraries for future use\n- Liaise with developers, designers and system administrators to identify new features\n- Follow emerging technologies.\n\n- Proven work experience as a fullstack developer and at least five year of experience in an equivalent position.\n- An in-depth understanding of the entire web development process (design, development, and deployment).\n- Hands-on experience with programming languages such as Nodejs.\n- Familiarity with front-end languages (e.g., HTML, JavaScript, and CSS).\n- Strong teamwork skills with a problem-solving attitude.\n- Bachelor\'s degree in Computer Science or a relevant field.\n- Preference will be given to candidates with experience in the ecommerce field.\n\n- Salary up to 45 millions VND\n- Holiday and Tet bonuses according to Vietnamese regulations.\n- Review your salary once a year.\n- Young, friendly and professional teamwork environment.\n- Join company trips, other activities for members\n\n- Hồ Chí Minh: 281/15 Bình Lợi, Phường 13, Bình Thạnh\n\n- From Monday to Saturday (from 08:30 to 17:30)\n- Monday to Friday: 8:30 - 17:30\n- Saturday: 8:30 - 12:30\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3228, 1445, 2, 'Senior Fullstack Developer', 'Mô tả công việc:\n- Thiết kế, phát triển và tối ưu Backend (Java Spring Boot, MongoDB) và Frontend (Angular) cho các hệ thống phần mềm doanh nghiệp.\n- Xây dựng RESTful APIs, WebSocket, đảm bảo hiệu năng, bảo mật và khả năng mở rộng.\n- Thiết kế kiến trúc hệ thống Microservices, tích hợp với các dịch vụ bên ngoài và hệ thống nội bộ.\n- Làm việc với MongoDB và MariaDB, tối ưu truy vấn dữ liệu và quản lý cơ sở dữ liệu NoSQL và SQL.\n- Thực hiện code review, Unit Test, hỗ trợ SIT/UAT, fix bug và tối ưu hiệu năng hệ thống.\n- Phối hợp với BA, UI/UX, DevOps, QA để triển khai dự án đúng tiến độ và chất lượng.\n- Nghiên cứu và áp dụng các công nghệ mới vào hệ thống.\n- Hướng dẫn, đào tạo đội ngũ Developer trong nhóm.\n\nYêu cầu ứng viên:\n- Tối thiểu 3 năm kinh nghiệm lập trình với Java Spring Boot.\n- Thành thạo Angular, có kinh nghiệm phát triển giao diện frontend theo kiến trúc component.\n- Thành thạo Spring Boot, Spring MVC, Spring Security, Hibernate, Maven.\n- Có kinh nghiệm làm việc với MongoDB và MariaDB.\n- Hiểu sâu về Microservices Architecture, Event-Driven Architecture (EDA), SOA.\n- Có kinh nghiệm triển khai trên Cloud, sử dụng Docker, Kubernetes.\n- Thành thạo Git, CI/CD, có kinh nghiệm với Agile/Scrum.\n- Có kinh nghiệm với OAuth 2.0, OpenID Connect, JWT.\n- Có kinh nghiệm tối ưu hệ thống và xử lý scalability.\n- Kinh nghiệm làm việc với Kafka, RabbitMQ hoặc các hệ thống Message Queue khác.\n\nQuyền lợi:\n- Thu nhập 15-30 triệu (thỏa thuận theo năng lực và kinh nghiệm làm việc thực tế)\n- Lương tháng 13, thưởng theo kết quả kinh doanh hàng năm.\n- Hưởng các chính sách, chế độ bảo hiểm theo đúng quy định của Luật lao động Việt Nam : Đóng Bảo hiểm theo đúng quy định của Luật lao động Việt Nam. Nghỉ lễ tết theo quy định và quà từ 500.000 - 1.000.000đ (sinh nhật, 8.3,20.10, 30.4,2.9, tết Dương lịch, chế độ tứ thân phụ mẫu và các chế độ cho con CBNV: tết thiếu nhi, học sinh giỏi) ......\n- Tham gia các hoạt động gắn kết nội bộ hằng quý, hằng năm, hay các dịp lễ tết, du lịch, sinh nhật, team building,...\n- Được định hướng nghề nghiệp và có lộ trình thăng tiến\n- Được tham gia các khóa đào tạo theo chương trình huấn luyện của Công ty.\n- Được đào tạo bài bản về sản phẩm và kiến thức kinh doanh, kỹ năng chuyên môn.\n- Môi trường làm việc trẻ, năng động, chuyên nghiệp, khuyến khích sự phát triển của từng nhân viên.\n\nĐịa điểm làm việc:\n- Hà Nội: BT01-7 KĐT An Hưng, Dương Nội, Hà Đông.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 7 (từ 08:00 đến 12:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Đông, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3229, 227, 2, '.NET Backend Engineer (Senior)', 'ABOUT THE ROLE\nJoin our Technology Innovations Center of Excellence (CoE) at Crossian, a fast-growing startup that achieved a milestone of $100M in 2024. In this dynamic role, you\'ll check in daily with your team to stay aligned on project goals and collaborate across our ecosystem with an Agile mindset infused with a unicorn-worthy startup culture.\n\nWHAT YOU WILL DO\n- Participate in Technical Specification & Test Cases in the Agile/Scrum development process\n- Develop clean, scalable code using .NET Core in Micro-service Architecture & Cloud-native\n- Develop backend Data-storage & Data-flows with Postgres, ES, Kafka and various Cloud data toolsets\n- Test and deploy system (micro-)services & (micro-)apps on AWS EKS/Kubernetes with Docker toolset\n- Improve existing system: revising, updating, refactoring and debugging code\n- Monitor and optimize system performance, addressing any issues as they arise.\n- Develop documentation throughout the software development life cycle (SDLC)\n- Serve as an expert on the system and provide technical support to other Internal teams\n\nWHAT WE ARE LOOKING FOR\n- Bachelor’s degree in computer programming, computer science, or a related field\n- At least 3+ years of development experience\n- Proficient in backend technologies: C#, .NET, .NET Core, ASP.NET Core, Entity Framework Core, LINQ\n- Proficient in Relational database modeling & design with Postgres/MSSQL\n- Knowledge of Microservices, Clean-code, Clean-Architecture & SOLID principles\n- Having experience in Message Queues with Kafka/RabbitMQ\n- Having experience with Docker, Kubernetes\n- Understanding of Agile/Scrum methodologies\n- English Professional working proficiency\n\nPreferred (but not required)\n- Document DB modeling & design with Elasticsearch\n- Object Storages with AWS S3\n- Messaging with Sendgrid, Twilio, AWS SNS,...\n- Having experience in Cloud Native Computing\n- DevOps, SysOps in AWS and Git CI/CD experience\n\nWHAT YOU CAN EXPECT\nWhy Join Us?\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\n\nExceptional Compensation\n- Up to 30 months of salary per year through competitive salary packages and performance-based bonuses.\n- Total annual compensation $55,000, reflecting your expertise and contribution.\n- Full salary during probation & Guaranteed 13th month salary\n- 12 days work-from-home & 12 days of paid annual leave, plus seniority paid leave\n- Global health insurance package for yourself and direct family members, plus annual health checkup\n\nGrowth Opportunities\n- Hands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\n- Clear career advancement pathways and access to continuous professional development programs.\n\nGlobal Vision\n- Contribute to projects that redefine how brands connect with consumers globally.\n- Opportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\n\nIn addition to development tasks, you’ll collaborate closely with other CoEs to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.\n\nĐịa điểm làm việc\n- Hà Nội: 65 Ngô Thì Nhậm, Hai Bà Trưng\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3230, 1177, 2, 'Lập Trình Viên Python', 'Mô tả công việc:\n- Tham gia trực tiếp vào các dự án phát triển và triển khai hệ thống Odoo cho các doanh nghiệp.\n- Phụ trách thiết kế chi tiết, lập trình, unit test, xử lý lỗi của chương trình sử dụng ngôn ngữ lập trình Python trên framework Odoo.\n- Tham gia xây dựng các giải pháp, viết phần mềm, lập trình các module theo yêu cầu công việc.\n- Thiết kế, phát triển và bảo trì các ứng dụng Python theo kiến trúc Micro-services.\n- Phát triển các API Services với Python.\n- Mở rộng, cải thiện và sửa lỗi phần mềm hiện có.\n- Lập kế hoạch và thực hiện bảo trì các phần mềm theo kế hoạch lập ra.\n- Thực hiện các công việc khác theo sự phân công của Trưởng phòng.\n\nYêu cầu ứng viên:\n- Tốt nghiệp các trường đại học, cao đẳng liên quan đến CNTT, có kiến thức cơ bản với lập trình tốt, đam mê công nghệ.\n- Có kiến thức, kinh nghiệm về: lập trình python, đã từng code framework Odoo là lợi thế.\n- Lập trình hướng đối tượng (OOP).\n- Lập trình trên các hệ quản trị cơ sở dữ liệu có cấu trúc MariaDB, PostgresDB, đã từng làm việc với MongoDB, HBase hoặc các NoSQL.\n- Kỹ năng tư duy logic.\n- Kỹ năng ứng dụng công nghệ thông tin.\n- Kỹ năng lập kế hoạch và triển khai công việc.\n- Kỹ năng xử lý tình huống.\n- Cẩn thận, chi tiết, nhiệt tình, trung thực.\n- Đam mê công nghệ thông tin.\n- Bảo mật thông tin.\n- Có tinh thần trách nhiệm.\n\nQuyền lợi:\n- Tham gia BHXH, BHYT, BHTN\n- Đánh giá xét lương thâm niên hàng năm\n- Khám sức khỏe định kỳ 1-2 lần/ năm tùy theo vị trí công việc\n- Thưởng các ngày lễ tết, thưởng cuối năm theo tình hình kinh doanh\n- Tham gia tổ chức công đoàn, được quan tâm thăm hỏi ốm đau, hiếu hỉ\n- Tham quan, nghỉ mát hàng năm theo chính sách công ty\n- CBNV được hưởng các chính sách chế độ khám chữa bệnh của hệ thống\n- Làm việc trong môi trường năng động, chuyên nghiệp và có cơ hội thăng tiến cao.\n\nĐịa điểm làm việc:\n- Hà Nội: 444 Hoàng Hoa Thám, Tây Hồ\n\nThời gian làm việc:\nThứ 2 - Thứ 6: 08h00 - 18h00\nThứ 7: 8h00 - 15h00  (làm 2 thứ 7 cách tuần)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3231, 1444, 2, 'User Acquisition Marketing Game', '• Quảng bá game mobile ra thị trường toàn cầu (ưu tiên Việt Nam, Trung Quốc).\n• Nghiên cứu thị trường, phân tích đối thủ và hành vi người chơi.\n• Phối hợp với team sản phẩm lên chiến lược marketing.\n• Chuẩn bị nội dung, thiết lập quảng cáo Facebook, Google.\n• Thiết lập và tối ưu quảng cáo trên Facebook, Google, Tiktok.\n• Theo dõi và tối ưu quảng cáo hàng ngày.\n• Đóng góp ý tưởng và cập nhật nội dung quảng cáo.\n• Phân tích và báo cáo dữ liệu theo tuần/ tháng.\n• Thực hiện hoạt động mở rộng thị trường.\n• Thực hiện các công việc khác theo yêu cầu quản lý.\n\nYêu cầu ứng viên\n• Có kinh nghiệm trong lĩnh vực Marketing Game từ 1 năm trở lên Có kiến thức chung về Marketing và Business, dự án Game.\n• Chuyên môn vững về Advertising Facebook, Google, Tiktok, Apple Search và tư duy về Marketing User Acquistion\n• Hiểu các chỉ số về CPL, CPI, CPM, CPC, CPA, ROAS\n• Có đam mê về game\n• Năng động, nhiệt tình, nhẫn nại, chấp nhận thử thách.\n• Có khả năng xử lý vấn đề khi gặp sự cố hoặc đối thủ cạnh tranh cùng thời điểm.\n• Khả năng đọc/ dịch tiếng Anh.\n\nQuyền lợi\n• Mức lương: 15 – 25 triệu VNĐ\n• Thử việc: 2 tháng, trong thời gian thử việc mỗi tháng được nghỉ phép 1 ngày\n• Thưởng hiệu suất, thưởng cuối năm, quà tặng dịp lễ – Tết, quà sinh nhật...\n• Có 12 ngày nghỉ phép có lương mỗi năm\n• Có thể đăng ký tham gia các khóa đào tạo nâng cao kỹ năng và năng lực\n• Công ty hỗ trợ bữa trưa\n• Tham gia đầy đủ bảo hiểm y tế, bảo hiểm xã hội theo quy định\n• Miễn phí đồ ăn nhẹ, nước uống; sử dụng không gian nghỉ ngơi miễn phí\n• Thường xuyên tổ chức các hoạt động team building\n• Cơ hội thăng tiến 2 lần mỗi năm.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: LK2-L10, Khu Biệt Thự Green Star, Số 600 Nguyễn Lương Bằng, Phường Phú Mỹ, Quận 7\n\nThời gian làm việc\nThời gian làm việc: Thứ 2 đến Thứ 6, nghỉ Thứ Bảy và Chủ Nhật (không làm thêm giờ)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3232, 1353, 2, 'Nhân Viên Vận Hành Máy CNC', '- Đọc bản vẽ, lập chương trình gia công, vận hành các máy phay CNC.\n- Bảo dưỡng và bảo trì máy móc.\n- Làm việc theo sự chỉ đạo của cấp trên\n- Chi tiết sẽ trao đổi cụ thể khi phỏng vấn.\n\nYêu cầu ứng viên\n- Tốt nghiệp Cao đẳng trở lên nghành kỹ thuật\n- Có ít nhất 3 năm kinh nghiệm sử dụng máy gia công phay CNC và biết lập trình gia công.\n- Biết đọc bản vẽ kĩ thuật, Autocad\n\nQuyền lợi\n- Lương từ 9.000.000 - 12.000.000VND tùy vào kinh nghiệm làm việc.\n- Làm việc giờ hành chính.\n- Một năm 12 ngày phép năm, một tháng công ty được nghỉ 1 ngày thứ bảy hoặc 2 ngày tùy từng tháng.\n- Được làm việc trong môi trường chuyên nghiệp, thân thiện, có cơ hội thăng tiến trong công việc.\n- Được hưởng các ngày nghỉ tết, ngày lễ, tăng lương hằng năm, thưởng lương tháng thứ 13.\n- Được hưởng các quyền lợi theo quy định của Luật lao động và BHXH.\n\nĐịa điểm làm việc\n- Đà Nẵng: Lô E, đường số 7, KCN Hòa Khánh, Liên Chiểu.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3233, 1148, 2, 'Fullstack Engineer (Typescipt/English Fluency)', 'At Sun Asterisk, we build cutting-edge, high-performance systems to tackle complex challenges. As a developer, you will:\n- Develop frontend and backend features using React, Next.js, and tRPC.\n- Build responsive UI components and seamless user experiences for AI tool creation.\n- Design and implement backend business logic and API layers with tRPC.\n- Integrate and optimize database queries using Prisma and Kysely.\n- Collaborate with Product and AI teams to ensure feature completeness and performance. Ensure quality via code reviews, testing (unit/integration), and observability.\n\nYêu cầu ứng viên\nExperience Requirements\nMandatory Skills:\n- 3+ years of experience as a Full Stack or Frontend/Backend Engineer.\n- Proficiency with TypeScript and React.\n- Experience building apps with Next.js (preferably using App Router).\n- Solid backend experience with tRPC or similar RPC/GraphQL APIs.\n- Familiarity with PostgreSQL and query performance optimization.\n- Experience using Prisma, Kysely, or any modern query builders.\n- Good communication skills, team-oriented, and comfortable in startup-paced environments.\n\nDesired Skills:\n- Familiarity with AI tools or LLM-powered platforms.\n- Experience with Neon PostgreSQL or serverless databases.\n- Experience with Tailwind CSS, Zod, Vercel, or PlanetScale.\n- Understanding of Edge Functions or Serverless API patterns.\n\nSkill requirements\n- Excellent English communication skills\n- Outstanding teamwork abilities\n- Proven ability to prioritize and allocate work\n- Sharp critical thinking and logical reasoning\n- Effective problem-solving skills\n\nAttitude Requirements\n- Customer-centric mindset\n- Adaptability to change\n- Commitment to continuous learning and growth.\n\nQuyền lợi\nProfessional, open-minded, and creative environment:\n- Work with colleagues who embrace ideas to change the society\n- Respect different perspectives within a team\n- Strong learning culture that promotes individual development\n- The culture of taking risks to experience and thrive\n\nFocus on individual development\n- Be consulted, accompanied, and supported in career development with the career path system (developing in expertise or management direction) that has been studied and tested for many years.\n- Be oriented for individual, group, and organizational goals\n- Be empowered\n- Be supported to define a 3-month or 6-month goal (Goal Define Support)\n- Get access to company Learning Hub online library with various courses provided by Udemy, LinkedIn,…\n\nSpecial care for employees\n- Salary: Negotiable + competitive allowance (lunch, living allowance, beauty care, Japanese and IT certificates, etc.)\n- 13th-month salary bonus\n- Performance review: Twice/a year\n- Hybrid working policy; flexible check-in, check-out\n- Comprehensive health insurance Sun Care\n- Seniority Allowance\n- Women care allowance: Women’s physiological leave: 2.5 hours/month; Postpartum leave for female employees with under 1-year-old children: 1 hour/day\n- Policies supporting learning activities, knowledge sharing, and cultural exchange (Technology Seminar – Tech Expert, Club: Reading, Japanese, Music Club, …)\n- Annual company trip and quarterly team-building activities.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 13, Keangnam Landmark Tower 72, Nam Từ Liêm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3234, 1438, 2, 'Senior PHP Fullstack', 'Mô tả công việc\n- Tham gia thiết kế, phát triển và hoàn thiện trang web, phần mềm của Cty với đối tác;\n- Tham mưu, tư vấn, làm cầu nối để phát triển, hoàn thiện app Androi và IOS của Cty với đối tác;\n- Tham gia phát triển phần định vị lên IOS, hiện thời chỉ dung được với Androi hoặc tham mưu, tư vấn để làm việc với đối tác;\n- Tham mưu, tư vấn để phát triển phần mềm mua hàng, ghi âm điện thoại hiện cty đang sử dụng;\n- Tham mưu, tư vấn trong việc số hóa các công việc mà TCT đang thực hiện;\n- Làm các công việc theo yêu cầu của Ban Giám đốc;\n- Làm việc và hỗ trợ trực tiếp với các Team sản phẩm, Mobile Developer, CSKH, Quản lý kho sản xuất...  \n\nYêu cầu ứng viên\n- Tốt nghiệp Đại học chuyên ngành công nghệ thông tin, khoa học máy tính, kỹ thuật máy tính hoặc một lĩnh vực tương tự\n- Có ít nhất 7 năm kinh nghiệm làm các dự án PHP, sử dụng thành thạo một trong các framework PHP (Laravel, WordPress, CakePHP, Zend, CodeIgniter)\n- Sử dụng thành thạo ít nhất từ Laravel 10\n- Có ít nhất 5 năm kinh nghiệm về DevOps và AWS\n- Hiểu biết sâu về ngôn ngữ PHP hoặc JS, OOP.\n- Đã từng làm việc/hiểu biết về API RestFul.\n- Có kinh nghiệm làm việc với một trong các hệ quản trị CSDL như MySQL, Maria DB, MongoDB.\n- Cẩn thận, kiên nhẫn, đam mê lập trình và sẵn sàng học hỏi các công nghệ mới.\n- Chịu được áp lực công việc.\n- Có kỹ năng phân tích và giải quyết vấn đề.\n- Ưu tiên CV ứng tuyển bằng tiếng Anh\n\nQuyền lợi\n- Thu nhập: 30 – 35 triệu/ tháng (theo năng lực từng ứng viên) + 700k phụ cấp ăn trưa/ tháng\n- Phúc lợi: BHXH, Thưởng lễ tết/ dự án, Sinh nhật, Du lịch hàng năm.\n- Làm việc trong môi trường giáo dục - công nghệ năng động.\n- Cơ hội phát triển kỹ năng sư phạm, quản lý nhóm.\n\nĐịa điểm làm việc\n- Hà Nội: 357 Nguyễn Khang, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3235, 1172, 2, 'Unity Developer', 'Responsibilities:\n- Designing and implementing code that is fit for purpose, scalable, human-readable, and in line with industry best practice.\n- Quality control of the entire product lifecycle by testing intuitiveness, user experience, and debugging where necessary.\n- Communicating with clients to understand their business goals and objectives, and interpreting that into the required changes to the platform where necessary.\n- Liaising with other developers, designers, and system administrators to identify new features and create relevant prototypes for new product ideas.\n- Deploying production code.\n- Communicating the effectiveness of emerging technologies to decision-makers.\n- Working on full production cycles from brainstorming and rapid prototyping to developing fully fledged systems and fine-tuning mechanics, as well as stress testing and bug fixing.\n- Developing innovative gameplay, AI, physics, UI, vehicles, weapons, and character controls.\n- Solving technical problems with simple, efficient, and creative code.\n- Helping ship game projects across multiple platforms on Web, iOS and Android.\n- Providing feedback and advice to junior team members.\n- Other tasks assigned by Line Manager.\n\nRequirements:\n- 4+ years of experience with game engines such as Unity, Pixi, Defold, Godot...\n- Experience working with native Android and iOS is a big plus.\n- History of working within rapid prototyping environments, such as game jams.\n- Passion for video games, films, and other creative mediums.\n- Knowing how to use git to collaborate with other teammates, understanding and applying Git Standards is a must.\n- Experience with remote config, dynamic assets loading.\n- Have knowledge of optimizing games.\n- Ability to build and maintain positive working relationships with teammates.\n- Excellent attention to detail and willingness to learn new software/processes.\n- Flexibility on working hours if required in the light of ad-hoc business demands.\n- Able to use initiative and remain self-motivated.\n- Able to work calmly and effectively under pressure.\n- Maintaining confidentiality/discretion where required.\n\nWhat we offer:\n- A competitive salary package that fits your skills, experiences, and contributions.\n- Holiday and New Year bonus.\n- Provision of necessary working equipment.\n- A professional, dynamic, and inclusive working environment.\n\nLocation:\n- Hồ Chí Minh: 292 Ung Văn Khiêm, Bình Thạnh.\n\nWorking time:\n- Monday - Friday (from 08:00 to 17:00).\n\nApplication method:\n- Candidates submit online applications by clicking "Apply" below.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3236, 1134, 2, 'Senior Backend Developer', 'Mô tả công việc:\n- Programming and developing company systems and applications.\n- Manage and develop integration services with core systems and other providers.\n- Manage and develop APIs on API Gateway to serve integration with partners.\n- Research, test, and apply new technology trends to development.\n- Maintain the operation of products and services within the scope of management.\n- Participate in business analysis, propose solutions and implementation plans to improve and increase the efficiency of projects during the working process.\nYêu cầu ứng viên:\n- College Graduate, major: Computer Science, IT.\n- At least 3 years’ experience working in software industry.\n- Plus/Optional: experience in consumer finance, insurance, banking industry.\n- SOLID Computer Science fundamentals.\n- Experience in design patterns, database, micro-service, optimization.\n- Backend stack: Java 8+(Must)/C/C#, NodeJS(must), Python, Lambda.\n- DB: Relational databases (must), NoSql, Redis.\n- Knowledge of Data Structure & Algorithms, OOP, Memory Management, Design Patterns, SOLID.\n- Testing: CucumberJS, Jest, Mocha, Chai, Selenium – at least one.\n- Agile methodology (working in Scrum) using Gitlab/Jira.\n- Linux OS.\n- Plus/Optional:\n    - Docker(MUST), CI/CD, Kubernetes, DevSecOps.\n    - Cloud AWS, Google Cloud.\n    - Message Queue, Kafka, Git flow.\nQuyền lợi:\n- Probation with 100% salary;\n- Official labor contract;\n- Social insurance, unemployment insurance, and health insurance;\n- 24/7 accident insurance;\n- Regular Medical Checkups;\n- Professional training courses;\n- 16 days leave /year;\n- 13th month salary, bonus and allowance.\nĐịa điểm làm việc:\n- Hồ Chí Minh\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3237, 1160, 2, 'Junior AI Agent Developer', 'We\'re looking for a Junior AI Agent Developer interested in exploring and building intelligent agents powered by AI. This role involves hands-on research, prototyping, and implementation of AI-driven agents, with direct mentorship from experienced team members. You\'ll grow your AI skills and contribute directly to meaningful projects.\n\n• Research and experiment with AI-driven agents using popular frameworks and tools such as LangChain, Hugging Face, and OpenAI APIs.\n• Build and prototype intelligent agents capable of basic autonomous interactions.\n• Collaborate with senior team members and engineers to integrate AI agents into Bitcover’s products.\n• Document experiments, findings, and technical solutions clearly.\n• Stay current with AI trends and proactively suggest new ideas and approaches.\n\n**Required**\n• Bachelor\'s degree or final-year student in Computer Science, Data Science, AI, or related field.\n• Good programming skills in Python.\n• Basic knowledge of Machine Learning fundamentals, Natural Language Processing, and conversational AI.\n• Experience from personal projects, internships, or academic coursework involving AI or software development.\n• Strong willingness to learn and adapt quickly.\n\n**Preferred**\n• Experience with cloud platforms (AWS, Azure, Google Cloud) is a plus but not required.\n• Familiarity with vector databases (Pinecone, Chroma, Weaviate) and embedding techniques.\n• Prior participation in hackathons, coding contests, or AI-related competitions.\n\n**Ideal Characteristics**\n• Curious and passionate about emerging AI technologies.\n• Self-motivated, proactive, and eager for growth opportunities.\n• Adaptable, resourceful, and comfortable working in a startup environment.\n• Good communication and collaboration skills.\n\n**Quyền lợi**\n• Opportunity to build hands-on experience in AI development.\n• Direct mentorship from senior team members.\n• Flexible working conditions (Hybrid/Remote options).\n• Dynamic and innovative startup environment.\n\nĐịa điểm làm việc: Hồ Chí Minh: Tân Bình\nThời gian làm việc: Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\nCách thức ứng tuyển: Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3238, 1430, 2, 'Fullstack Developer (NodeJS/PHP/Python) - Upto 40 Tr', 'Mô tả công việc:\n- Tham gia phát triển các dự án Web của khách hàng.\n- Tham gia phân tích yêu cầu, thiết kế hệ thống, thiết kế Database, phát triển các chức năng.\n- Thực hiện công việc theo mô hình Agile/ Scrum, lập kế hoạch, thực hiện, kiểm soát và báo cáo công việc theo từng Sprint.\n- Hỗ trợ đào tạo, chia sẻ kiến thức, review code cho các thành viên trong team.\n- Tham gia build team, quản lý team (nếu đã có kinh nghiệm).\n- Nghiên cứu và định hướng các công nghệ mới áp dụng vào dự án.\n\nYêu cầu ứng viên:\n- Tốt nghiệp CĐ/ĐH chuyên ngành CNTT hoặc có liên quan.\n- Ít nhất 3 năm kinh nghiệm Backend (NodeJS/PHP/Python) và 2 năm Frontend (VueJS/ReactJS/Angular)\n- Thao tác tốt với HTML/ CSS/ jQuery/ AJAX/...\n- Có kiến thức nền tảng tốt về OOP, Coding Convention, Architecture Patterns (MVC, MVP, MVVM).\n- Hiểu biết về Restful API, Design Pattern,...\n- Có kinh nghiệm thiết kế và xây dựng cơ sở dữ liệu với SQL/ NoSQL.\n- Có khả năng tư duy, học hỏi nhanh; chủ động trong công việc; làm việc độc lập và làm việc nhóm tốt..\n- Ứng dụng AI trong công việc.\n\nLợi thế (không bắt buộc):\n- Ưu tiên ứng viên đã làm trong các dự án theo mô hình Agile/ Scrum.\n- Có kinh nghiệm team leader là lợi thế.\n- Có các chứng chỉ ngoại ngữ/ chuyên môn như IELTS, JLPT, AWS, PSM,... là lợi thế.\n\nQuyền lợi:\n- Mức lương: 20.000.000 - 40.000.000 VND (thỏa thuận theo từng level).\n- Thưởng cuối năm theo hiệu suất làm việc và tình hình kinh doanh của công ty.\n- Thưởng hoặc quà tặng các dịp lễ, sinh nhật.\n- Review tăng lương 6 tháng/lần.\n- Hỗ trợ 100% học phí và lệ phí thi các chứng chỉ chuyên môn.\n- Gói khám sức khỏe định kỳ hàng năm; đóng bảo hiểm (BHXH, BHYT, BHTN) và các chế độ khác đầy đủ theo quy định của Luật lao động (chế độ nghỉ phép, lương làm thêm giờ...).\n- Cơ hội thăng tiến cao trở thành Team Leader, Techlead, PM.\n- Được hỗ trợ nâng cao kiến thức, kỹ năng thông qua các hoạt động: Seminar; CLB chuyên môn; Các khóa đào tạo từ học viện uy tín,...\n- Hỗ trợ định hướng lộ trình phát triển bản thân, định hướng mục tiêu cá nhân (OKR, 1on1 với mentor nhiều kinh nghiệm).\n- Luôn tạo môi trường làm việc IT thoải mái, năng động và đặc biệt hỗ trợ nhau trong công việc.\n- Tham gia các hoạt động tập thể của công ty: Team building, du lịch, CLB bóng đá, happy hour hàng tháng...\n- Cung cấp đầy đủ thiết bị làm việc; Free trà, cafe,...\n\nĐịa chỉ văn phòng mới: Tòa nhà NHS Trung Văn, Tố Hữu, Nam Từ Liêm, Hà Nội (từ 01/08/2025).', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3239, 1114, 2, 'ReactJS Technical Leader', 'Mô tả công việc:\n- Quản lý Team FE, hướng dẫn và hỗ trợ chuyên môn cho các thành viên trong nhóm.\n- Định hướng, phân tích và thiết kế kiến trúc hệ thống, đảm bảo hệ thống bền vững, an toàn thông tin, hiệu suất cao, dễ bảo trì, nâng cấp và mở rộng.\n- Tham gia phát triển các hệ thống sản phẩm, dịch vụ của công ty: Phát triển các Module của sản phẩm/dịch vụ; Phối hợp với BA, Tester fix bug, update module; Merge code.\n- Thống nhất các mục tiêu, sản phẩm cũng như đưa ra phương án kỹ thuật của dự án.\n- Xử lý các vấn đề kỹ thuật phát sinh trong quá trình phát triển.\n\nYêu cầu ứng viên:\n- Tốt nghiệp ĐH trở lên chuyên ngành Công nghệ thông tin; Kỹ thuật phần mềm, Hệ thống thông tin, ...hoặc các ngành tương đương.\n- Trên 5 năm kinh nghiệm phát triển React JS, trong đó ít nhất 1 năm đảm nhận vai trò Technical Leader.\n- Có kinh nghiệm phát triển web sử dụng các framework React JS.\n- Từng tham gia các hệ thống về Tài chính/Chứng khoán/Ngân hàng,…\n\nChuyên môn kỹ thuật:\n- Thành thạo React JS, JavaScript/TypeScript, HTML5, CSS3 và hệ sinh thái (hoặc các library/framework có concept tương tự: React Native, Vue, Ember,...).\n- Có kinh nghiệm với các công cụ frontend như Webpack, Babel, ESLint và các framework kiểm thử (Jest, React Testing Library).\n- Kinh nghiệm với CI/CD, Git và các nền tảng đám mây (AWS, Azure) là một điểm cộng.\n\nKỹ năng quản lý và giao tiếp:\n- Có khả năng quản lý và hướng dẫn các nhóm kỹ thuật, tạo dựng môi trường làm việc hợp tác và hiệu quả.\n\nKỹ năng mềm:\n- Kỹ năng giải quyết vấn đề tốt và chủ động trong việc nhận diện và khắc phục các thách thức kỹ thuật.\n- Nhận thức văn hóa và khả năng thích nghi để làm việc hiệu quả với các bên liên quan.\n- Kỹ năng tổ chức tốt, chú ý đến chi tiết và quản lý thời gian hiệu quả.\n\nQuyền lợi:\n- Lương: upto 32M\n- Được hưởng chế độ ưu đãi về lương, thưởng theo năng lực, hiệu quả công việc, kết quả sản xuất kinh doanh chung công ty.\n- Tháng lương thứ 13 tùy theo thời gian làm việc tương ứng.\n- Tham gia đầy đủ các chế độ bảo hiểm (BHXH, BHYT, BHTN...)\n- Thưởng theo dự án, thưởng CBNV xuất sắc, ngoài ra còn có các khoản trợ cấp hàng tháng như sau:\n  - Trợ cấp đi lại\n  - Trợ cấp ăn trưa\n  - Du lịch hằng năm trong, ngoài nước\n- Thời gian làm việc: từ thứ 2 đến thứ 6 và 2 sáng thứ 7 trong tháng.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 14, Center Building Hapulico Số 85 Vũ Trọng Phụng, Thanh Xuân, Thanh Xuân.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:15 đến 17:30)\n- 2 Sáng thứ 7/tháng.\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3240, 1162, 2, 'Kỹ Sư Lập Trình Ứng Dụng Phần Cứng', 'Mô tả công việc:\n- Nghiên cứu và phát triển sản phẩm thiết bị giám sát hành trình\n- Phân tích, đánh giá và lập kế hoạch công việc triển khai theo các yêu cầu chức năng (một phần hoặc toàn bộ 1 sản phẩm) và viết tài liệu nghiệp vụ\n- Kế thừa và ứng dụng mã nguồn sẵn có lên các nền tảng phần cứng khác nhau (Porting)\n- Phân tích, Triển khai thư viện hoặc tích hợp thư viện cho các thiết bị ngoại vi khác nhau và viết tài liệu\n- Xây dựng các công cụ vận hành, phân tích và gỡ lỗi cho sản phẩm\n- Xác minh các sự cố liên quan tới chức năng của sản phẩm và đưa ra giải pháp xử lý\n- Thực hiện triển khai công việc theo hướng dẫn và báo cáo định kỳ của cấp trên\n\nYêu cầu ứng viên:\n- Nam 23-35 tuổi không yêu cầu kinh nghiệm\n- Tốt nghiệp hệ đào tạo chính quy Cử nhân, Kỹ sư chuyên ngành Điện,  Điện Tử viễn thông, Tự động hóa …\n- Trình độ ngoại ngữ: Đọc/Viết tài liệu Tiếng Anh - Tin học văn phòng cơ bản (Word, excel,…)\n- Kỹ năng: Sử dụng ngôn ngữ lập trình C/C++, Java trong phát triển ứng dụng trên các phần cứng sử dụng hệ điều hành Android, BSP Linux; Làm việc với design patents; Hiểu biết về xử lý đồng bộ/Bất đồng bộ, giao tiếp giữa các Process, multi-threading; Đọc hiểu và thích nghi tốt với sự thay đổi về SDK/Framework/driver/libraries của các nền tảng khác nhau…..\n\n- Yêu cầu chuyên môn:\n+ Có hiểu biết cơ bản về Network Topology cho Live streaming, audio/Photo/video codec, video container và các giao thức về media streaming;\n+ Có hiểu biết về hệ thống giám sát hành trình tích hợp Camera ghi hình DASHCAM, đầu ghi Mobile Digital Video Recorder (MDVR) của Gotrack.\n+ Có hiểu biết về thành phần cấu tạo, chức năng và vận hành của các thiết bị DASHCAM, MDVR…\n- Ưu tiên: Đã tham gia nghiên cứu, phát triển và chế tạo sản phẩm được triển khai thực tế. Hoặc đã tham gia bảo trì, nâng cấp liên tục một sản phẩm trong thời gian dài; Được đào tạo từ các môi trường như FPT, Đại học Bách Khoa Hà Nội, Đại học Quốc Gia Hà Nội, Sư phạm kỹ thuật …\n\nQuyền lợi:\n- Mức lương 16.000.000đ - 20.000.000đ, phù hợp với năng lực và kinh nghiệm\n- Được đóng BHXH, BHYT, BHTN theo quy định của pháp luật\n- Chế độ nghỉ phép, nghỉ lễ theo quy định\n- Được xét tăng lương 2 lần/năm, xét tăng lương thâm niên vào cuối năm, thưởng lễ tết, sinh nhật,...\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện\n- Cơ hội học hỏi và phát triển kỹ năng với các công nghệ mới nhất trong lĩnh vực nhúng\n- Được tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn\n- Tham gia các hoạt động team building, du lịch hàng năm\n- Được trang bị đầy đủ các thiết bị, công cụ cần thiết cho công việc\n\nĐịa điểm làm việc:\n- Hà Nội: Lô B13, Khu đấu giá Vạn Phúc, Lê Văn Tám, Vạn Phúc, Hà Đông\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:15 đến 17:30)\n- Các buổi sáng thứ 7 hoặc 2 thứ 7 trong tháng\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3241, 1244, 2, 'Bridge Software Engineer', 'Mô tả công việc:\n- Hiểu và truyền đạt chính xác các yêu cầu, đặc tả của dự án cho team\n- Họp, thảo luận với khách hàng trực tiếp hoặc thông qua call/chat/email\n- Quản lý dự án/team để đảm bảo dự án release đúng tiến độ\n- Kiểm tra (test) dự án để đảm bảo chất lượng trước khi release\n- Chi tiết công việc sẽ được thảo luận khi phỏng vấn\n\nYêu cầu ứng viên:\n- Tốt nghiệp các trường đại học chuyên ngành CNTT/Toán Tin\n- Ít nhất 1 năm kinh nghiệm phát triển các hệ thống web dùng PHP\n- Có kinh nghiệm và am hiểu về các giai đoạn phát triển phần mềm (từ khâu nhận yêu cầu)\n- Ít nhất 1 năm kinh nghiệm làm BrSE cho các dự án phần mềm với khách hàng Nhật\n- Tiếng Nhật giao tiếp lưu loát, từ N2 trở lên; từng du học hoặc làm làm việc tại Nhật\n- Có kỹ năng tự tìm hiểu kỹ thuật, công nghệ mới\n- Yêu thích văn hoá Nhật Bản và có mong muốn làm việc lâu dài tại Nhật Bản\n- Làm việc cẩn thận với tinh thần trách nhiệm cao\n\nQuyền lợi:\n- Môi trường làm việc năng động, thân thiện\n- Được trang bị máy Macbook Pro và màn hình LCD\n- Lương tháng 13, du lịch công ty hàng năm, khám sức khỏe định kỳ và các hoạt động thể thao\n- Thử việc 100% lương\n- Phụ cấp tiền gửi xe, sinh nhật...\n- Ghi chú: Bộ phận HR chỉ liên lạc những CV đạt yêu cầu để mời phỏng vấn\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 103A-105-107 Nguyễn Thông, Phường 9, Quận 3\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3242, 1241, 2, 'Chuyên Viên Lập Trình', 'Mô tả công việc\n- Tham gia phát triển, bảo trì và tối ưu hoá các hệ thống website, ứng dụng web sử dụng ngôn ngữ PHP\n- Làm việc với các framework phổ biến như Laravel, Symfony, Codelgniter,...\n- Thiết kế và triển khai các API, tích hợp với hệ thống bên thứ ba\n- Tham gia phân tích yêu cầu, đề xuất giải pháp kỹ thuật phù hợp\n- Phối hợp với các team khác (Frontend, QA, UI/UX) để đảm bảo chất lượng sản phẩm\n- Tham gia review code và cải tiến quy trình phát triển phần mềm.\n\nYêu cầu ứng viên\n- Kinh nghiệm: Có từ 2 năm kinh nghiệm\n- Kiến thức:\n  + Có kiến thức về cơ sở dữ liệu\n  + Có kiến thức về ngôn ngữ lập trình PHP\n  + Có kiến thức về tìm kiếm trong lập trình\n  + Có kiến thức về lập trình hướng đối tượng\n- Kỹ năng/khả năng:\n  + Có kỹ năng code các ngôn ngữ backend (ưu tiên PHP)\n  + Có kinh nghiệm trong việc xây dựng hệ thống, xây dựng server\n  + Có khả năng tư duy và thiết kế database\n  + Có khả năng viết API\n\nQuyền lợi\n- Chế độ đãi ngộ\n  + Mức lương: cạnh tranh hấp dẫn (sẵn sàng offer cao khi đủ năng lực) + Phụ cấp (Ăn ca: 700.000 VNĐ/tháng; Gửi xe: 120.000 VNĐ/tháng; trợ cấp máy tính cá nhân (nếu có): 300.000 VNĐ/tháng).\n  + Chính sách thưởng: Thưởng Lễ, Tết, sinh nhật + thưởng dự án + thưởng thâm niên + Lương tháng 13 + các thưởng khác theo quy định Công ty tại thời điểm hiện hành.\n  + Làm việc trong môi trường trẻ trung, năng động, coi trọng năng lực và khả năng sáng tạo\n  + Thường xuyên tổ chức các hoạt động mini game, chương trình các ngày Lễ, Tết, sinh nhật, tham gia hoạt động Teambuilding của công ty...\n- Đào tạo – Phát triển\n  + Cơ hội tiếp cận và học hỏi công nghệ tiên tiến, công nghệ mới\n  + Được công ty tạo điều kiện và hỗ trợ khi tham gia các khóa đào tạo, phát triển năng lực.\n  + Có cơ hội làm những việc thách thức, phát huy hết khả năng bản thân.\n  + Tham gia các sản phẩm công nghệ mới theo kế hoạch phát triển của công ty.\n- Chăm sóc sức khỏe, đời sống\n  + Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n  + Được tặng quà, thăm hỏi nhân các dịp: sinh nhật, cưới hỏi, hiếu hỉ, ốm đau...\n  + Có thể tham gia các câu lạc bộ thể thao: đá bóng, tập yoga, thể dục cải thiện sức khoẻ...\n\nĐịa điểm làm việc\n- Hà Nội: 97-99 Láng Hạ, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n- Checkin linh hoạt từ 7.30-9.00 am\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3243, 1300, 2, 'Senior Tester', 'Mô tả công việc:\n- Review and clarify customer and business requirements.\nCollaborate closely with the development team to develop, maintain, and execute manual test cases.\nWork with business/requirement analysts to write and execute operational test scenarios.\n- Perform exploratory testing to detect potential issues not covered by formal test cases.\n- Report, track, and monitor bugs in the defect tracking system.\n- Update and maintain test documentation, including test plans, test cases, and test reports.\n- Estimate effort and time required for testing activities.\n\nYêu cầu ứng viên:\n- At least 4 years of experience as a QA/QC or tester in software development projects.\n- Strong experience in writing test cases using black-box testing techniques.\n- Solid understanding of software development and testing processes.\n- Good knowledge of SQL and data modeling.\n- Strong analytical skills and a detail-oriented, structured working approach.\n- Ability to work independently as well as collaboratively within a team.\n- Able to understand spoken and written English in a working environment.\n- Familiarity with testing methodologies and tools.\n\nQuyền lợi:\n- Performance bonus\n- 23 annual leave days per year (Annual/Birthday/Sick/Christmas/mental world leave)\n- 05 cub care leave days\n- 04 training leave days\n- 100% full of income in Probation\n- 100% Full of social insurance\n- Join Football, Ping-pong, Foosball, Clubs\n- Spring & Summer & Birthday Teambuilding trip\n- Free snacks & beverages\n- Private health insurance package: Golden Card of AON insurance\n- Team building activities\n- Highly talented and dynamic team\n- Travel opportunities\n\nĐịa điểm làm việc:\n- Hà Nội: 165 Bà Triệu, Lê Đại Hành, Hai Bà Trưng\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3244, 1109, 2, 'Trưởng Bộ Phận ERP', '- Nghiên cứu, thiết kế và phát triển hệ thống ERP cho công ty\n- Kết nối các bộ phận để phát triển và ứng dụng phần mềm vào thực tế\n- Lập kế hoạch phát triển phần mềm quản trị doanh nghiệp theo yêu cầu\n- Phân tích đánh giá tính hiệu quả của hệ thống\n- Báo cáo tiến độ và tình trạng công việc cho người quản lý trực tiếp.\n- Quản lý đội ngũ nhân viên bộ phận\n- Hỗ trợ, bảo trì hệ thống trong quá trình vận hành.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học chuyên ngành CNTT hoặc tương đương\n- Kiến thức về quy trình phát triển, vận hành phần mềm.\n- Quản lý yêu cầu người dùng, đào tạo và hướng dẫn\n- Giao tiếp, trình bày, tâm huyết, chuyên nghiệp\n- Kinh nghiệm làm các dự án ERP tối thiểu 3 năm, vị trí quản lý 2 năm\n\nQuyền lợi\n- Lương: Thỏa thuận (22 đến 30 triệu) \n- Có thưởng theo từng dự án khi hoàn thành mỗi giai đoạn.\n- Có thưởng dài hạn theo lợi nhuận phát sinh của mỗi sản phẩm mà cá nhân có tham gia theo tỷ lệ tương ứng với đóng góp.\n- Xét điều chỉnh lương 02 lần/năm.\n- Các chế độ bảo hiểm xã hội và bảo hiểm y tế theo Luật Lao Động.\n- Được ăn trưa miễn phí, được tham gia hoạt động tập thể do Công Đoàn tổ chức.\n- Chế độ phúc lợi (Nghỉ mát, sinh nhật, cưới hỏi...).\n\nĐịa điểm làm việc\n- Hà Nội: Lô 14 nguyễn Cảnh Dị, Hoàng Mai, Hoàng Mai\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:45)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm \'Ứng tuyển\' ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3245, 1337, 2, 'Java BackEnd Developer', 'Mô tả công việc\n- Phát triển, tối ưu các chức năng hệ thống backend theo sự phân công và định hướng từ PM hoặc Leader.\n- Tham gia phân tích nghiệp vụ, phân rã chức năng, phân tích hệ thống, kiểm thử logic và trải nghiệm, sửa lỗi, triển khai hệ thống\n- Chịu trách nhiệm về chất lượng và hiệu quả code của các module được giao. Đảm bảo sản phẩm backend ổn định, hiệu suất tốt và dễ bảo trì.\n- Hợp tác chặt chẽ với các team liên quan (FE, QA, BA, DevOps...) để đảm bảo tiến độ và chất lượng sản phẩm.\n- Tham gia vào quy trình kiểm thử, fix bugs, triển khai và bảo trì hệ thống.\n- Chủ động tìm hiểu nghiệp vụ và tham gia đề xuất cải tiến sản phẩm.\n- Hỗ trợ các thành viên junior khi cần và có thể review code nếu được giao.\n- Báo cáo tiến độ, vấn đề, kết quả công việc đến quản lý trực tiếp.\n- Trải nghiệm sản phẩm định kỳ để hiểu hành vi người dùng, từ đó đưa ra các đề xuất cải tiến.\n\nYêu cầu ứng viên\n1.Kiến thức bắt buộc:\n- Có tối thiểu 02 năm kinh nghiệm tương đương\n- Thành thạo ngôn ngữ lập trình Java và lập trình hướng đối tượng (OOP).\n- Có kinh nghiệm làm việc với hệ quản trị cơ sở dữ liệu RDBMS, NoSQL, có khả năng viết, tối ưu truy vấn, phân tích dữ liệu.\n- Có hiểu biết về các Framework Spring Boot, Vert.x, Microservice.\n- Hiểu rõ mô hình backend MVC và các khái niệm RESTful API.\n- Có kinh nghiệm triển khai hệ thống trên môi trường production, biết cách vận hành và giám sát hệ thống.\n- Có khả năng sử dụng AI trong lập trình.\n\nKiến thức nâng cao (lợi thế):\n- Biết sử dụng các ngôn ngữ lập trình khác: PHP, Python, Shell-script, Jenkin, HAProxy\n- Kỹ năng làm việc theo quy trình JIRA, Agile, SCRUM\n- Có hiểu biết về UI/UX, hành vi người dùng là một điểm cộng.\n\n2. Kỹ năng\n- Problem solving: Có khả năng phân tích vấn đề, tìm giải pháp kỹ thuật phù hợp.\n- Design thinking: Có tư duy xây dựng giải pháp tối ưu, hướng đến trải nghiệm người dùng.\n- Giao tiếp, làm việc nhóm, lắng nghe và truyền đạt thông tin\n- Học hỏi và tự học tốt; Tổ chức và quản lý thời gian\n\n3. Tố chất\n- Tư duy logic\n- Tư duy hệ thống\n- Tỉ mỉ, cẩn thận\n\nQuyền lợi\n3 Lý do bạn chọn TP Entertainment:\n1 là bạn có cơ hội phát triển bản thân thần tốc:\n- Môi trường TP Entertainment luôn phát huy hết điểm mạnh và khả năng sáng tạo của bạn, nhờ đó bạn có cơ hội được tỏa sáng\n- Được làm việc và hướng dẫn trực tiếp bởi Leader giàu kinh nghiệm\n\n2 là bạn có cơ hội tăng thu nhập không giới hạn:\n- Những đóng góp của bạn luôn được công ty ghi nhận rõ ràng nhờ đó thu nhập của bạn được cải thiện nhanh chóng và không giới hạn\n\n3 là môi trường làm việc lý tưởng:\n- Văn hoá công ty đậm đà sâu sắc với 4 giá trị cốt lõi: Hiệu quả, sáng tạo, lấy khách hàng là trung tâm, nhân văn\n- Làm việc tại công ty công nghệ hàng đầu về Mobile app với môi trường trẻ trung, năng động, thân thiện, sáng tạo\n- Du lịch hàng năm, dã ngoại hàng quý cùng người thân (4 lần/năm)\nNgoài ra bạn được hưởng các chính sách đãi ngộ của công ty như:\n- Trợ cấp ăn trưa (Khi trở thành thân viên thử việc)\n- Hưởng đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định của nhà nước (Khi là nhân viên chính thức)\n- Khám sức khỏe định kỳ hàng năm\n- Trà chiều, hoa quả, sữa bánh\n- Tham gia các hoạt động vui chơi thể thao hàng ngày tại công ty\n- Thử việc 02 tháng hưởng 100% mức lương chính thức\n- Review lương 2 lần/năm\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 2 tháp A, Toà nhà Rivera Park, 69 Vũ Trọng Phụng, P. Thanh Xuân Trung, Thanh Xuân\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3246, 165, 2, 'Frontend Developer (HTML/CSS/JS)', 'About KiotViet:\nKiotViet aims to extend the significant power of technology to every business model in Vietnam and Southeast Asia through our simple and effective solutions. We are committed to creating efficient, convenient products for micro, small, and medium-sized businesses. Over the past 13 years, with a current team of over 1500 people at KiotViet, we recognize that our members are the foundation of KiotViet and a launchpad for achieving a better KiotViet in the future. KiotViet is dedicated to creating a work environment that fosters shared success and responsibilities.\n\nKiotviet is Vietnam’s largest POS provider, with over 200,000 merchants across various industries. We are expanding into other South-east Asian countries with our POS offerings and are expanding our product portfolio with new offerings in the fintech space.\n\nWhat you will do:\n- Convert designs from Figma/PSD to HTML/CSS\n- Maintain and develop UI components\n- Ensure responsive design across all devices\n- Collaborate with team to deliver quality products\n\nEXPERIENCE REQUIREMENTS:\n- Bachelor\'s degree in Computer Science/IT/Design or equivalent\n- 4+ years of Frontend Development experience\n\nREQUIRED SKILLS:\n- Proficient in HTML5, CSS3, JavaScript\n- Experience with SASS/SCSS\n- Knowledge of Bootstrap or Tailwind CSS\n- Ability to convert responsive designs from Figma/PSD\n- Basic understanding of Angular & TypeScript\n- Proficient with Git version control\n\nPREFERRED:\n- Experience with AI coding tools (Cursor, GitHub Copilot, Claude...)\n- Web performance optimization knowledge\n- Understanding of web accessibility standards\n\nSOFT SKILLS:\n- Attention to detail in UI implementation\n- Strong communication with design & development teams\n- Self-motivated and continuous learner\n- Ability to work independently\n\nQuyền lợi:\n- Top salary range in the market (willing to negotiate)\n- Compensation, pay a 13th month salary depending on employee’s performance;\n- Performance bonus (up to 2-month salary)\n- Social – Health – Insurance paid fully. Healthcare: Annual health check-up, Premium Health Insurance (from level senior according to the company\'s regulations)\n- Advantageous and yield benefits, other benefits such as holiday vacations, benefits for employee’s relatives;\n- Unlimited chance of being promoted based on employee’s performance.\n\nĐịa điểm làm việc:\n- Hà Nội: 1A Yết Kiêu, Trần Hưng Đạo, Hoàn Kiếm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2 đến thứ 6. Làm việc 8 tiếng/ngày và checkin linh hoạt trong khung từ 08h - 09h\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3247, 1184, 2, 'Senior Java', 'Mô tả công việc:\n- Làm việc với những dự án sản phẩm công nghệ của công ty và đối tác.\n- Phân tích giải pháp, xác định các yêu cầu về hệ thống, tính năng của sản phẩm.\n- Lập kế hoạch, xây dựng phương án, công cụ code đối với từng sản phẩm.\n- Báo cáo thường xuyên về kết quả làm việc với nhóm và cấp trên.\n- Quản lý chất lượng sản phẩm đạt đúng yêu cầu đề ra.\n\nYêu cầu ứng viên:\n- Có từ 3 năm kinh nghiệm trở lên trong việc phát triển Web Service.\n- Nắm vững kiến thức và có kinh nghiệm làm việc với Java core, JavaEE, Spring MVC/ Boots, Hibernate.\n- Hiểu rõ về SQL và NOSQL.\n- Đã làm qua các dự án với mô hình Microservice, MVC.\n- Có kiến thức chuyên sâu về OOP và Design pattern.\n- Có kinh nghiệm liên quan đến vấn đề performance và security của hệ thống.\n- Có kiến thức về unit test, integration test,...\n- Biết qua HTML5, CSS3, JS, có kinh nghiệm với ReactJS là một điểm cộng.\n- Thành thạo các câu lệnh và cách quản lý source repository trên GIT, có kinh nghiệm review code là một lợi thế.\n- Có kiến thức về quy trình phát triển phần mềm.\n- Chấp nhận những thử thách mới và không ngại khó.\n- Có khả năng lãnh đạo và mong muốn trở thành Leader, Manager.\n\nTechnical Skills:\n- Programming Languages: Java, Python, Golang.\n- Software: Visual Studio Code, ControlIO.\n- Cloud Skills: AWS (CloudFormation, SES, EC2, RDS, S3, Lambda, CloudWatch).\n- Data Skills: Data Integration, PQL Queries, Action Flows, Analyses, Views.\n\nPersonal Skills:\n- Office Skills: Excel, Word.\n- Project Management Tools: JIRA, Rocket Chat.\n\nQuyền lợi:\n- Chính sách bảo hiểm xã hội, bảo hiểm y tế theo quy định của Nhà nước.\n- Bảo hiểm sức khỏe PVI sau 01 năm làm việc.\n- Môi trường làm việc trẻ trung, năng động, thân thiện.\n- Cơ hội làm việc onsite tại Nhật Bản.\n- Thường xuyên tổ chức các seminar do chính nhân viên công ty thực hiện, tạo điều kiện nghiên cứu, trao đổi, phát triển.\n- Được hướng dẫn tận tình, tạo nhiều cơ hội phát triển, thăng tiến trong công việc.\n- Hỗ trợ tiền nhà ở trong bán kính 2km.\n- Hỗ trợ chi phí gửi xe và các tiện ích khác.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Vinhome Grand Park, Nguyễn Xiển, Phường Long Thạnh Mỹ, Quận 9\n- Hồ Chí Minh: Charmingtin La Pointe, 181 Cao Thắng, Phường 12 0, Quận 10\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3248, 1199, 2, 'Junior Backend Java Developer', 'Mô tả công việc\n• Tham gia thiết kế và triển khai các ứng dụng hiệu năng cao bằng Microservice phục vụ cho các nhu cầu kinh doanh của Ngân hàng như: khách hàng, tài khoản, vay vốn, tiết kiệm, chuyển tiền, thanh toán hóa đơn, ví điện tử, gửi tin nhắn...\n• Quản lý, phát triển dịch vụ tích hợp với các hệ thống core như: T24, WAY4, BPM, CRM, CIC...\n• Tham gia phát triển API trên API Gateway phục vụ tích hợp với các đối tác trong nước và quốc tế.\n• Làm việc onsite tại bank.\n\nYêu cầu ứng viên\nKiến thức:\n- Tốt nghiệp Đại học trở lên chuyên ngành CNTT hoặc các ngành tương đương hoặc có các chứng chỉ tương đương được công nhận bởi các tổ chức uy tín\nKinh nghiệm:\n-  2 năm kinh nghiệm  làm việc thực tế tại các tổ chức CNTT\n-  Nắm rõ quy trình xây dựng và triển khai phần mềm\n-  Sử dụng thành thạo Java core, có kinh nghiệm phát triển trên framework Spring Boot.\n-  Có hiểu biết về cơ sở dữ liệu: SQL, noSQL\n-  Có hiểu biết về việc sử dụng các công cụ quản trị như: Jija, Git,...\nƯu tiên:\n-  Ưu tiên kinh nghiệm làm việc trong lĩnh vực tài chính / ngân hàng\n-  Ưu tiên ứng viên có kinh nghiệm về phát triển ứng dụng theo dạng Cloud Native như: Microservice, CICD, DepOps, Containerization...\n-  Ưu tiên Nhân sự đã từng tham gia triển khai các dự án theo mô hình Agile/Scrum\n-  Ưu tiên nhân sự có kinh nghiệm về xử lý bất đồng bộ, xử lý đa nhiệm, event sourcing, có kinh nghiệm về các hệ thống Message Queue (Kafka, RabbitMQ), có hiểu biết về xử lý cache, job.\nNgoại ngữ:\n- Có khả năng đọc viết tiếng Anh (cơ bản) nghe nói (nếu có thể).\n- Ưu tiên ứng viên có chứng chỉ Tiếng Anh quốc tế (TOEICS 450 trở lên hoặc tương đương)\nYêu cầu khác:\n- Kỹ năng giao tiếp và làm việc nhóm tốt\n- Sẵn sàng làm việc ngoài giờ hành chính\n- Tinh thần trách nhiệm, ham học hỏi\n\n---Ưu tiên nộp hồ sơ sớm---\n\nQuyền lợi\n• Thời gian làm việc 5 ngày/tuần (từ thứ Hai đến thứ Sáu).\n• Cơ hội thăng tiến, phát triển nghề nghiệp công bằng.\n• Thu nhập hấp dẫn, cạnh tranh.\n• Được hưởng chế độ BHXH, BHYT, BHTN.\n• Được tham gia các chương trình đào tạo, huấn luyện của Công ty.\n• Môi trường làm việc chuyên nghiệp, thân thiện, năng động.\n• Thu nhập: 15 - 28 triệu (Tùy theo năng lực)\n\nĐịa điểm làm việc\n- Hà Nội: Lê Văn Lương, Cầu Giấy\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển\n• Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3249, 1173, 2, 'Technical Leader', 'Mô tả công việc:\n1. Tiên phong nghiên cứu và ứng dụng các công nghệ, kỹ thuật mới nhằm nâng cao năng lực kỹ thuật của đội ngũ và chất lượng sản phẩm.\n2. Phân tích yêu cầu dự án, từ đó đưa ra các tư vấn, đề xuất, đánh giá và triển khai giải pháp kỹ thuật phù hợp cho khách hàng và đội dự án.\n3. Xây dựng công cụ, hệ thống và giải pháp kỹ thuật nhằm tối ưu hiệu suất làm việc và nâng cao chất lượng đầu ra.\n4. Mentor, hỗ trợ và định hướng thành viên trong việc giải quyết các vấn đề kỹ thuật trong dự án.\n5. Tham gia tuyển dụng, đào tạo nhân sự mới và tổ chức các chương trình nâng cao kỹ năng kỹ thuật cho các thành viên trong team.\n6. Tư vấn và định hướng kỹ thuật, xây dựng lộ trình phát triển cá nhân cho các thành viên; đồng hành và hỗ trợ trong quá trình phát triển đó.\n7. Chia sẻ kiến thức, tổ chức các buổi chia sẻ công nghệ nội bộ, lan tỏa văn hóa học hỏi và phát triển liên tục trong team.\n\nYêu cầu ứng viên:\n1. Có kinh nghiệm phân tích và thiết kế hệ thống, bao gồm thiết kế cơ sở dữ liệu (DB Design), thiết kế tổng thể và chi tiết (Basic Design, Detail Design), sử dụng các công cụ và phương pháp như UML.\n2. Thành thạo các best practices trong lập trình như Clean Code, Design Patterns và các kiến trúc hệ thống nền tảng.\n3. Có kinh nghiệm lập trình full-stack với một trong các ngôn ngữ như JavaScript hoặc PHP.\n4. Kỹ năng tổ chức và lãnh đạo tốt, từng đảm nhiệm vai trò quản lý và dẫn dắt nhóm phát triển phần mềm.\n5. Am hiểu về server, hệ thống cloud (là một lợi thế).\n6. Có khả năng tổ chức, sắp xếp công việc một cách khoa học và chịu được áp lực cao trong công việc.\n7. Kỹ năng giao tiếp tốt, có tinh thần chia sẻ, yêu thích việc lan tỏa kiến thức tới đồng nghiệp.\n8. Tư duy logic tốt, có khả năng phân tích và giải quyết vấn đề một cách hiệu quả.\n\nQuyền lợi:\n1. Mức lương: Upto 50TR\n2. Nói KHÔNG với chậm lương, nợ lương.\n3. Review lương 02 lần/năm\n4. Tối thiểu 13 tháng lương, thưởng theo hiệu quả công việc) và các khoản hỗ trợ khác\n5. Thưởng các ngày lễ: 30/4, 2/9, Tết Dương Lịch. Quà sinh nhật công ty, quà sinh nhật cá nhân,...\n6. Hưởng 15 ngày nghỉ phép nguyên lương/năm\n7. Tham gia miễn phí các khóa học đạo tạo nội bộ do công ty thiết kế, tổ chức.\n8. Tham gia mọi chế độ BHXH, BHYT, BHTN theo quy định của Luật lao động Việt Nam\n9. Khám sức khỏe định kì tại các bệnh viện uy tín (Hồng Ngọc, Thu Cúc, ...)\n10. Du lịch hè 1-2 lần/năm, trợ cấp team-building cá nhân định kỳ hàng quý\n11. Đọc sách miễn phí tại thư viện sách của Công ty\n12. Thời gian làm việc: Từ 8h00 đến 17h00, nghỉ Thứ Bảy và Chủ Nhật\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 22, tháp B, tòa nhà Sông Đà (HH4), Đường Phạm Hùng, Phường Mỹ Đình 1, Nam Từ Liêm.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3250, 1141, 2, 'Flutter Developer', 'Mô tả công việc\n- Thiết kế, phát triển và tối ưu hiệu suất ứng dụng trên nền tảng Android / iOS. Chủ yếu là Flutter.\n- Cùng team lên ý tưởng và giải pháp cho các tính năng mới của ứng dụng ;\n- Sửa lỗi và cải thiện tính năng, hiệu suất sản phẩm ;\n- Phối hợp với các thành viên trong team để vận hành và tối ưu hoá sản phẩm ;\n- Nghiên cứu công nghệ mới, phù hợp với chiến lược sản phẩm ;\n- Chi tiết công việc sẽ trao đổi thêm khi phỏng vấn.\n\nYêu cầu ứng viên\n- Thành thạo lập trình hướng đối tượng (OOP), cấu trúc dữ liệu, giải thuật và thiết kế giao diện người dùng (UI/UX).\n- Có ít nhất 2 năm kinh nghiệm làm việc với API dạng RESTful.\n- Sử dụng thành thạo hệ thống quản lý mã nguồn Git.\n- Kỹ năng phân tích, tư duy giải quyết vấn đề tốt.\n- Tinh thần trách nhiệm cao, chủ động và khả năng làm việc nhóm hiệu quả.\n- Có khả năng tự học hỏi, cập nhật công nghệ mới và kỷ luật bản thân.\n\nQuyền lợi\n- Mức lương: Up to 20 triệu/tháng, tùy năng lực.\n- Làm việc cùng team kỹ sư trẻ, tài năng, đam mê công nghệ.\n- Cơ hội tiếp cận công nghệ mới.\n- Chế độ đầy đủ: BHXH, sinh nhật, thưởng Tết (tháng lương thứ 13), du lịch hàng năm.\n- Tham gia hoạt động thể thao như bóng đá hàng tuần.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 3, Tòa Tháp Đông, Chung cư Học viện Quốc Phòng, Xuân La, Tây Hồ\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)\n- Nghỉ thứ 7 cách tuần.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3251, 1349, 2, 'Kỹ Sư Lập Trình Nhúng', 'Mô tả công việc\n- Phát triển firmware cho các dòng sản phẩm gia dụng như: Bếp từ, điều hòa, bình nóng lạnh, máy lọc nước, …\n- Tham gia vào phân tích yêu cầu, thiết kế kiến trúc hệ thống, thiết kế phần mềm nhúng;\n- Thu thập và xử lí các yêu cầu thiết kế và kĩ thuật;\n- Nghiên cứu và áp dụng các công nghệ mới để tối ưu hóa hiệu quả phát triển sản phẩm.\n\nYêu cầu ứng viên\n- Tốt nghiệp cao đẳng, đại học chuyên ngành Kỹ thuật điện tử, Tự động hóa, Cơ điện tử hoặc liên quan.\n- Có kinh nghiệm từ 3 năm trong vị trí lập trình nhúng liên quan đến:\n  + Điều khiển động cơ, đo và điều khiển nhiệt độ sử dụng thuật toán PID.\n  + Nắm chắc việc sử dụng các ngoại vi phần cứng như: SPI, I2C, USART, TIMER, PWM, ADC, INTERRUPT, …\n  + Nắm chắc việc sử dụng các nền tảng phần nhúng như: RTOS, MODBUS RTU, CRC, …\n  + Đã từng làm một hoặc nhiều các dự án chế tạo máy, thiết bị điều khiển công nghiệp, ROBOT, AGV, DATALOGGER; các dự án chế tạo sản phẩm, thiết bị điện gia dụng như bếp từ, điều hòa, …\n  + Đã có sản phẩm ra thị trường là lợi thế.\n- Kỹ năng đọc hiểu tài liệu tiếng Anh tốt trong lĩnh vực chuyên môn.\n- Có kỹ năng đọc hiểu tài liệu thiết kế nguyên lý phần cứng.\n- Thành thạo nền tảng GIT trong quản lý phiên bản phần mềm là một lợi thế.\n- Thành thạo các công cụ soạn thảo văn bản, bảng tính, báo cáo, …\n- Có khả năng giao tiếp, hòa đồng và làm việc nhóm tốt.\n- Có tinh thần làm việc tận tâm, quyết liệt và trách nhiệm.\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực. Đánh giá tăng lương 2 lần/năm.\n- Thử việc hưởng 100% lương.\n- Thời gian làm việc linh hoạt từ T2-T6.\n- Môi trường làm việc trẻ trung, năng động.\n- Thưởng ngày Lễ/Tết, thưởng KPI, thưởng dự án theo tháng.\n- Có cơ hội được đào tạo phát triển và thăng tiến.\n\nĐịa điểm làm việc\n- Hà Nội: 9A Thanh Liệt, Thanh Trì.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:48).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3252, 1176, 2, 'Senior Java Developer', 'Mô tả công việc:\n- Tham gia phân tích yêu cầu của khách hàng\n- Đưa ra thiết kế chi tiết để xử lý nghiệp vụ theo thiết kế kiến trúc của hệ thống\n- Quản lý team dev (5-7 người) và review code.\n- Làm việc với SA và Tech Lead để đưa ra thiết kế một số module trong hệ thống\n- Xây dựng code base và đảm bảo team phát triển theo đúng thiết kế\n\nYêu cầu ứng viên:\n- Nắm vững ngôn ngữ lập trình Java, Spring Framework và ORM Framework\n- Nắm vững các design pattern trong thiết kế hướng đối tượng\n- Nắm vững spring boot và ORM framework\n- Nắm vững về Kafka, Redis, các hệ quản trị cơ sở dữ liệu SQL, NoSQL\n- Đọc hiểu và viết tốt các tài liệu thiết kế UML\n- Có khả năng phân tích và đưa ra giải pháp xử lý tốt.\n- Làm việc với hệ điều hành Linux thành thạo.\n- Nắm vững kiến trúc dữ liệu và giải thuật, các loại giao tiếp trong hệ thống\n- Có kinh nghiệm làm việc với CI/CD.\n- Có kinh nghiệm làm việc với kiến trúc Microservice, SOA,...\n- Nắm vững quy trình phát triển phần mềm waterfall, Agile\n- Có kinh nghiệm lead team nhỏ, quản lý plan, task của các thành viên trong team tốt.\n- Có kinh nghiệm thiết kế hệ thống, thiết kế database cho toàn bộ hệ thống là lợi thế\n\nQuyền lợi:\n- Chế độ lương hấp dẫn upto 45M\n- Lương tháng 13, tiền thưởng cho nhân viên xuất sắc và tập thể xuất sắc\n- Bảo hiểm chăm sóc sức khỏe cao cấp, bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp\n- Được khám sức khỏe định kỳ 1 lần/1 năm\n- Tối thiểu 12 ngày nghỉ phép có lương mỗi năm cho tất cả nhân viên chính thức\n- Môi trường làm việc hiện đại với những đồng nghiệp trẻ trung, năng động & thân thiện và cà phê, trà, đồ uống miễn phí\n- Du lịch công ty hàng năm và tiệc cuối năm, team building hàng quý và ăn uống cùng nhau hàng tuần. Câu lạc bộ: chạy, bóng đá, game,...\n- Văn hóa phẳng, cởi mở và chia sẻ với đội ngũ quản lý thân thiện\n- Thời gian làm làm việc: 8h30 - 17h30 Thứ 2 - Thứ 6\n\nĐịa điểm làm việc:\n- Hà Nội: Tòa Detech, số 8 Tôn Thất Thuyết, Nam Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3253, 1365, 2, 'Thực Tập Sinh Lập Trình', 'Mô tả công việc\nBackend - NestJS hoặc .NET C# -Biết 1 backend framework là lợi thế (NestJS, ASP.NET Core...) -Hiểu mô hình REST API, HTTP method, status code -Có tư duy xử lý logic nghiệp vụ, thao tác database, tổ chức code rõ ràng\nFrontend Web - ReactJS -Biết ReactJS hoặc từng làm giao diện bằng HTML/CSS/JS -Có gu thẩm mỹ, hiểu cơ bản về UI/UX, bố cục layout hợp lý -Biết gọi API, xử lý dữ liệu là điểm cộng\nFrontend Mobile - React Native -Biết React Native cơ bản, hiểu layout đa nền tảng (Android/iOS) -Biết debug, test trên thiết bị thật hoặc giả lập -Không yêu cầu publish Store, chỉ cần từng làm app thử\nƯu tiên: Ứng viên có sử dụng thiết bị Mac (Macbook/iMac) để hỗ trợ nhóm build/test iOS. Vui lòng ghi rõ trong CV nếu có\n\nYêu cầu ứng viên\nYêu cầu bắt buộc - Ưu tiên ứng viên có nền tảng tốt và tư duy rõ ràng -Tư duy lập trình tốt: biết phân tích bài toán, viết code rõ ràng, có logic, biết debug đúng cách. -Có kiến thức cơ bản và nghiêm túc với ngành lập trình: -Biến, kiểu dữ liệu, hàm, vòng lặp, đệ quy, con trỏ, tham trị/tham chiếu -Cấu trúc dữ liệu & giải thuật: mảng, danh sách, stack, queue, hash map, sắp xếp, độ phức tạp Big-O -Cơ sở dữ liệu - SQL & T-SQL: SELECT, JOIN, GROUP BY, index, stored procedure, trigger, transaction -Kiến thức hệ thống & mạng: mô hình OSI, HTTP/HTTPS, request-response, status code... -Sử dụng Git: commit, branch, pull, merge cơ bản -Có khả năng đọc hiểu tài liệu tiếng Anh kỹ thuật -Tinh thần học hỏi nghiêm túc, chủ động cải thiện sau mỗi lần review\nƯu tiên (không bắt buộc): -Đã làm đồ án chỉn chu (có GitHub càng tốt) -Từng tham gia cuộc thi lập trình, giải thuật, hoặc sự kiện công nghệ -Có sản phẩm cá nhân nhỏ, project nhóm hoặc freelance thật\n\nQuyền lợi\nHỗ trợ thực tập: 1.500.000đ/tháng -Lộ trình thực tập 4-6 tháng giúp đủ thời gian làm quen quy trình, phát triển kỹ năng, và sẵn sàng chuyển lên thử việc/chính thức -Khi được đánh giá lên chính thức: Ký hợp đồng lao động và được tham gia đầy đủ chế độ BHXH, BHYT, thuế TNCN theo quy định -Được hướng dẫn bài bản bởi senior, thực chiến với sản phẩm thật -Không chấm công cứng - chỉ cần đảm bảo tiến độ và tinh thần nghiêm túc -Tham gia các hoạt động nội bộ: meeting, onboarding, happy hour -Cung cấp thư xác nhận thực tập, dấu mộc công ty nếu cần cho nhà trường -Không gian làm việc yên tĩnh, đầu tư chỉn chu -Cơ hội phát triển và mở rộng vai trò nếu mong muốn -Ưu tiên tham gia dự án công ty hoặc đào tạo chéo nếu có mong muốn\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 86/11 Ngô Chí Quốc, P. Bình Chiểu, Thủ Đức\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 09:00 đến 18:00)\nThứ 2 – Thứ 7: 09:00 – 18:00 (nghỉ trưa 1 tiếng)\nLưu ý: Thứ 7 có thể linh hoạt thời gian.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Internship', '2025-10-07 20:59:18.149534'),
	(3254, 1414, 2, 'Lập Trình Viên IOS (Swift, Objective-C)', 'Mô tả công việc\n+ Xây dựng các ứng dụng Mobile liên quan đến các mảng Tài chính, Ngân hàng, Ví điện tử, hệ sinh thái (Các dịch vụ đặt vé, mua sắm, du lịch, giải trí...) trên nền tảng IOS.\n+ Xây dựng các ứng dụng liên quan đến các phần tiện ích Ecommerce\n+ Nghiên cứu, tìm kiếm giải pháp về việc áp dụng các tính năng của thiết bị di động vào mảng tài chính, Ngân hàng, Viễn thông.\n+ Duy trì, hỗ trợ, nâng cấp các ứng dụng dịch vụ đã phát triển của Công ty\n+ Phát triển mới, nâng cấp ứng dụng cho các ngân hàng trong giai đoạn sắp tới.\n\nYêu cầu ứng viên\n+ Tốt nghiệp Đại học hoặc Cao đẳng chuyên ngành Công nghệ thông tin, Công nghệ phần mềm,… hoặc Trường đào tạo lập trình viên Quốc Tế (NIIT, Aptech) trở lên.\n+ Có hiểu biết về kiến trúc công nghệ, ứng dụng và mô hình phát triển cho nền tảng hệ điều hành IOS\n+ Kiến thức cơ bản và tư duy về Objective-C, Swift, lập trình IOS, lập trình hướng đối tượng.\n+ Ưu tiên ứng viên có hiểu biết công nghệ liên quan đến nền tảng thiết bị di động khác.\n+ Ưu tiên ứng viên có ứng dụng demo trên Appstore\n+ Có kinh nghiệm làm việc với SVN/GIT\n+ Chịu khó tìm tòi và nghiêm túc trong công việc.\n+ Chủ động trong công việc cũng như tìm hiểu công nghệ mới.\n+ Có trách nhiệm cao với công việc, gắn bó lâu dài với công ty.\n\nQuyền lợi\n1. Chế độ lương & thưởng hấp dẫn:\nMức lương thỏa thuận theo năng lực, đánh giá năng lực hàng năm\nChế độ thưởng phong phú và hấp dẫn (Theo quy định và chính sách công ty)\nHỗ trợ ăn sáng miễn phí\nHỗ trợ ăn trưa: 50.000đ/ngày\nHỗ trợ gửi xe, xăng xe, điện thoại (tùy vị trí)\nHỗ trợ trang điểm cho CBNV nữ\nQuà tặng các ngày lễ trong năm\n2. Bảo hiểm & chăm sóc sức khỏe toàn diện:\nBHXH, BHYT, BHTN theo pháp luật hiện hành\nGói bảo hiểm sức khỏe cao cấp 24/7 mua cho nhân viên & người thân nhân viên\nKhám sức khỏe định kỳ hàng năm\n3. Môi trường làm việc hiện đại:\nCung cấp máy tính & thiết bị làm việc hiện đại\nVăn phòng làm việc hiện đại, thiết bị làm việc Hi- tech\nKhông gian ăn nhẹ miễn phí (nước uống, trà cafe, hoa quả, sữa chua)\n4. Phát triển nghề nghiệp:\nCơ hội tiếp cận với những công nghệ mới, những dự án quy mô lớn\nLàm việc cùng đội ngũ hơn 2000 nhân sự tài năng, có chuyên môn giỏi, dày dạn kinh nghiệm, tư duy chia sẻ\nĐược tài trợ kinh phí tham gia các chương trình đào tạo nâng cao năng lực\nCông ty thành lập gần 20 năm với các sản phẩm & dịch vụ đã được khẳng định vị thế trên thị trường\n5. Hoạt động ngoại khóa phong phú:\nVăn hóa công ty đặc sắc với nhiều hoạt động đoàn thể được quan tâm đầu tư: Team building, Nghỉ mát (trong nước và nước ngoài), 20/10, Year End Party, hoạt động thiện nguyện,…\nCác câu lạc bộ: CLB Cầu lông, CLB Bóng đá, CLB Yoga, CLB Điền kinh, CLB Bơi\nChúng tôi sẽ liên hệ qua điện thoại với những CV phù hợp trong vòng 7 ngày làm việc kể từ ngày ứng tuyển.\nLưu ý: Công ty đang tuyển tại 2 văn phòng Hà Nội và Tp. Hồ Chí Minh, ứng viên vui lòng ghi rõ địa chỉ trên CV.\n\nĐịa điểm làm việc\n- Hà Nội: 22 Láng Hạ, Đống Đa\n- Hồ Chí Minh: Tầng 12, tòa nhà Minh Long, số 17 Bà Huyện Thanh Quan, P. Võ Thị Sáu, Quận 3.\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội, Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3255, 1426, 2, 'AI Developer', '1. Giới thiệu công việc\nChúng tôi đang tìm kiếm một Chuyên gia AI có kinh nghiệm chuyên sâu trong lĩnh vực xử lý hình ảnh, đặc biệt là các ứng dụng làm đẹp, thay đổi khuôn mặt, kiểu tóc và trang phục bằng công nghệ AI. Bạn sẽ tham gia phát triển các sản phẩm sáng tạo hướng tới người dùng cuối, tập trung vào việc cá nhân hóa hình ảnh theo thời gian thực.\n\n2. Trách nhiệm chính\n• Thiết kế, huấn luyện và tối ưu các mô hình AI cho các tác vụ như:\n• Làm đẹp khuôn mặt (skin retouching, makeup synthesis)\n• Biến đổi khuôn mặt (face swap, age progression/regression)\n• Thay đổi kiểu tóc, trang phục bằng AI (hair segmentation, virtual try-on)\n• Xử lý và cải thiện chất lượng ảnh (denoising, super-resolution, background removal…)\n• Phối hợp với đội ngũ sản phẩm và thiết kế để xây dựng giải pháp có thể triển khai trên thiết bị di động hoặc nền tảng web.\n• Tối ưu hiệu suất mô hình để đạt thời gian phản hồi nhanh và tiêu tốn ít tài nguyên.\n• Nghiên cứu và tích hợp các công nghệ AI mới nhất (GAN, diffusion, NeRF…).\n\nYêu cầu ứng viên\n• Có từ 2 năm kinh nghiệm trong lĩnh vực Computer Vision hoặc AI/Deep Learning.\n• Có kinh nghiệm về các kiến trúc mô hình như GAN, UNet, Transformer, Diffusion Models.\n• Có kinh nghiệm xử lý dữ liệu ảnh và xây dựng pipeline huấn luyện mô hình.\n• Ưu tiên ứng viên đã từng làm việc với các dự án như:\n• Face beautification app\n• Virtual try-on / makeup app\n• 3D face modeling hoặc image-based rendering\n\nQuyền lợi\n• Được lựa chọn làm remote linh hoạt thời gian hoặc fulltime tại văn phòng\n• Thu nhập hấp dẫn, deal theo năng lực, fix 13 tháng lương\n• Thưởng tiền mặt và quà tặng vào các dịp lễ tết,… theo chính sách của Công ty.\n• Ăn trưa tại công ty.\n• Cung cấp đầy đủ máy tính, thiết bị làm việc hiện đại, cấu hình cao.\n• 12 ngày phép/năm.\n• Được hỗ trợ chi phí tham gia các khóa học nâng cao chuyên môn theo định hướng của Công ty.\n• Các hoạt động team building, các event chăm lo đời sống tinh thần của nhân viên như sinh nhật, liên hoan hàng tháng,... \n• Môi trường làm việc trẻ trung, năng động, đề cao và tôn trọng ý kiến cá nhân, ý tưởng sáng tạo nhằm nâng cao năng suất và hiệu quả công việc.\n\nĐịa điểm làm việc\n- Hà Nội: Tòa Golden Palace, Mễ Trì, Nam Từ Liêm, Nam Từ Liêm\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3256, 1219, 2, 'Fulltime IOS', 'Mô tả công việc:\n- Phát triển và duy trì các ứng dụng iOS chất lượng cao trên nền tảng Swift/Objective-C.\n- Tham gia vào toàn bộ vòng đời phát triển ứng dụng: từ phân tích yêu cầu, thiết kế, coding, testing đến triển khai và bảo trì.\n- Phối hợp chặt chẽ với team UI/UX, backend và các bộ phận liên quan để đảm bảo tính ổn định và trải nghiệm người dùng tối ưu.\n- Tối ưu hiệu suất và khả năng mở rộng của ứng dụng.\n- Sửa lỗi và cải tiến sản phẩm hiện tại theo phản hồi của người dùng và yêu cầu kinh doanh.\n- Cập nhật công nghệ mới và đề xuất áp dụng vào dự án.\n\nYêu cầu ứng viên:\n- Ưu tiên có kinh nghiệm phát triển ứng dụng iOS.\n- Thành thạo Swift, có hiểu biết về Objective-C là lợi thế.\n- Có kinh nghiệm làm việc với UIKit, CoreData, CoreAnimation, RESTful APIs, JSON, Push Notification...\n- Hiểu rõ về mô hình MVC/MVVM, quản lý bộ nhớ, vòng đời ứng dụng iOS.\n- Biết sử dụng Git và làm việc trong môi trường CI/CD.\n- Có kinh nghiệm sử dụng CocoaPods, Swift Package Manager.\n- Tư duy logic tốt, chủ động trong công việc, có trách nhiệm và tinh thần học hỏi.\n\nQuyền lợi:\n- Mức lương cạnh tranh, thưởng theo kết quả công việc.\n- Môi trường làm việc chuyên nghiệp, thân thiện và sáng tạo.\n- Cơ hội học hỏi và phát triển trong các dự án quốc tế.\n- Bảo hiểm y tế, bảo hiểm xã hội và các phúc lợi khác theo quy định của công ty.\n- Cơ hội tham gia các khóa đào tạo, nâng cao kỹ năng chuyên môn.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 25/1 Cửu Long Phường 2, Tân Bình\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3257, 1131, 2, 'Junior Dev', 'Mô tả công việc:\n- Phát triển và triển khai các phần mềm, giải pháp AI Automation để tự động hóa quy trình trong doanh nghiệp\n- Nghiên cứu và tích hợp các giải pháp AI Automation vào quy trình làm việc của doanh nghiệp\n- Tham gia các dự án tự động hóa quy trình doanh nghiệp bằng các nền tảng Low-code/No-code như: Power Automate, Power Apps (Microsoft), Oracle Apex và các nền tảng tự động hóa khác theo yêu cầu\n- Tích hợp dữ liệu từ các hệ thống như KiotViet, Google Analytics, Facebook Ads, Shoppe, Tiktok Shop, Misa, Bravo…. và các nền tảng khác thông qua API.\n- Xây dựng các pipeline dữ liệu tự động, đảm bảo thu thập và đồng bộ hóa dữ liệu một cách chính xác và liên tục.\n- Phối hợp với các bộ phận liên quan để xác định yêu cầu và triển khai giải pháp.\n- Báo cáo định kỳ về tiến độ và kết quả công việc.\n\nYêu cầu ứng viên:\n- Đã tốt nghiệp công nghệ thông tin hoặc chuyên ngành kỹ thuật liên quan\n- Có 6 tháng kinh nghiệm trở lên trong lập trình hoặc phát triển giải pháp tự động hóa.\n- Thành thạo ít nhất một ngôn ngữ lập trình như Python, Java, Node.js, hoặc JavaScript.\n- Kinh nghiệm làm việc với API từ các nền tảng như KiotViet, Google Analytics, Facebook Ads…..\n- Hiểu biết về công cụ Low-code/No-code như Power Automate, Power Apps, Oracle Apex là một lợi thế lớn\n- Kỹ năng làm việc với cơ sở dữ liệu như Oracle, SQL Server, MySQL, PostgreSQL, hoặc MongoDB.\n- Đọc hiểu tài liệu kỹ thuật tiếng Anh là một lợi thế.\n- Có khả năng tìm kiếm, nghiên cứu và nắm bắt công nghệ mới.\n- Chủ động trong công việc.\n\nQuyền lợi:\n- Lương + Thưởng cuối năm, thưởng dự án, 13 tháng lương\n- Cung cấp Laptop/ PC\n- Được đóng bảo hiểm theo luật lao động Việt Nam (BHXH, BHYT, BHTN)\n- Ngoài ra, thưởng vào các dịp lễ khác trong năm (1/1, 30/4-1/5; 2/9, 8/3, 20/10...), Sinh nhật; Chi phí công đoàn thăm hỏi vào các dịp hiếu, hỉ, ốm đau;\n- Phụ cấp gửi xe; ngoài ra phụ cấp điện thoại và đi lại tùy thuộc vào một số vị trí và cấp bậc;\n- Phụ cấp cơm trưa, bảo hiểm sức khỏe, khám sức khỏe định kỳ 1 lần/năm, du lịch nghỉ mát 1 lần/ năm.\n- Môi trường làm việc chuyên nghiệp, trẻ trung, năng động\n- Nghỉ Thứ 7, Chủ nhật, 12 ngày phép/ năm\n- Tổ chức teambuilding.\n- Tổ chức tham quan, nghỉ mát.\n- Cung cấp đồ ăn nhẹ, trà và cà phê miễn phí.\n- Cơ hội thăng tiến vào các vị trí quản lý công nghệ cấp cao đối với những thành viên xuất sắc\n- Happy hours hàng tháng, free snacks, hoa quả, đồ uống.\n- Tổ chức sinh nhật, team lunch, ...\n- Review lương 1 năm / 1 lần\n- Được đào tạo và trau dồi không chỉ kiến thức chuyên môn, kỹ năng mềm mà cả kỹ năng quản lý nhóm, quản lý dự án thông qua các buổi đào tạo nội bộ chung do phòng Đào tạo tổ chức hoặc các buổi đào tạo của riêng phòng ban;\n\nĐịa điểm làm việc:\n- Hà Nội: 19-21 Vũ Trọng Phụng, Thanh Xuân Trung, Thanh Xuân\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n- 19 Vũ Trọng Phụng, Thanh Xuân Trung, Thanh Xuân, Hà Nội\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3258, 1271, 2, 'Product Management Trainee - Quản Lý Sản Phẩm', 'Chương trình Viettel Future Changemakers kéo dài 18 tháng, dự kiến triển khai từ tháng 08/2025 – 01/2027, chia làm 02 giai đoạn:\n- Giai đoạn 1 (1 tháng): Trại huấn luyện tập trung - Được đào tạo tập trung bởi nhiều chuyên gia của Viettel và các Tập đoàn công nghệ lớn thế giới\n+ Tổng quan về Quản lý sản phẩm\n+ Kiến thức về Lập chiến lược sản phẩm (Ideas & User needs, Competitive & Market Analysis, Customer Development)\n+ Kiến thức về Thiết kế và phát triển sản phẩm\n+ Kiến thức về Marketing & Ra mắt sản phẩm\n+ Các kỹ năng cần thiết về Quản lý sản phẩm\n- Giai đoạn 2 (17 tháng): Thực tập tại các dự án trọng điểm thuộc đơn vị\n+ Tập sự viên được tham gia các dự án, công việc tại các phòng ban liên quan để hiểu rõ về 03 khía cạnh của Quản lý sản phẩm (1) Kinh doanh (2) Công nghệ (3) Khách hàng.\n+ Mentor là người có chuyên môn cao trong lĩnh vực sẽ hướng dẫn tập sự viên\n+ Management coach là cán bộ quản lý có kỹ năng lãnh đạo tốt sẽ tư vấn cho tập sự viên\n+ Tham gia lên ý tưởng cho các sản phẩm trọng điểm của Viettel và tham gia cuộc thi “The Changemakers” với cơ hội nhận thưởng lên đến 30 triệu/ đồng và được trình bày đề xuất trước Ban Tổng Giám đốc Tập đoàn.\n- Các hoạt động kết nối: Tham gia nhiều hoạt động kết nối tài năng, cán bộ quản lý tại Viettel.\n\nYêu cầu ứng viên:\n- Ứng viên bên trong và bên ngoài Viettel tốt nghiệp đại học loại Giỏi trở lên các ngành Công nghệ thông tin, Khoa học máy tính, Quản trị kinh doanh, Tài chính ngân hàng, Marketing, Kinh tế và các ngành tương đương; hoặc đạt các thưởng quốc gia/quốc tế trong các lĩnh vực liên quan; hoặc có thành tích xuất sắc khi tham gia các dự án lớn trong lĩnh vực liên quan.\n- Ưu tiên ứng viên có 02 năm kinh nghiệm làm Marketing, Product Owner, Phân tích nghiệp vụ, Phát triển phần mềm cho các sản phẩm công nghệ.\n- Tiếng Anh tối thiểu 700 điểm TOEIC hoặc tương đương (Chấp nhận điểm thi trên E-learning bài TOEIC đầy đủ và các chứng chỉ quốc tế tương đương).\n- Hình thức thi: Vòng 1 - IQ, Tiếng Anh Toeic, Vòng 2: Online test, Vòng 3: Assessment day tại Hà Nội, Vòng 4: Phỏng vấn hội đồng\n- Địa điểm: Hà Nội (Đối với ứng viên khác khu vực Hà Nội sẽ được tài trợ máy bay 02 chiều nếu trúng tuyển và tham gia đầy đủ chương trình).\n\nQuyền lợi:\n- 30-47 triệu/tháng\n- Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình.\n- Các hoạt động kết nối: Tham gia nhiều hoạt động kết nối tài năng, cán bộ quản lý tại Viettel.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3259, 1306, 2, 'Full Stack Developer', 'Mô tả công việc:\n- Lập trình các tính năng cho phần mềm ERP và các dịch vụ liên quan nằm trong hệ sinh thái chung của GOLAZY.\n- Tham gia xây dựng các component trong hệ sinh thái sản phẩm dựa trên nền tảng Core của GOLAZY phát triển.\n- Tham gia phân tích, hợp tác với các nhóm phát triển để xây dựng các nghiệp vụ trong sản phẩm khi được yêu cầu.\n- Tìm hiểu các công nghệ, tích hợp mới được giao để đưa vào áp dụng cho phần mềm khi phát sinh kế hoạch cập nhật sản phẩm theo yêu cầu.\n- Làm việc & phát triển bản thân trong các phòng kỹ thuật, tham gia vào hoạt động xây dựng các gói tính năng mới, bảo trì và tối ưu các tính năng cũ theo mô hình Agile Scrum.\n\nYêu cầu ứng viên:\n- Tối thiểu một năm kinh nghiệm với vị trí Fullstack Developer hoặc tối thiểu một năm kinh nghiệm với vị trí Frontend/Backend Developer và có định hướng phát triển trở thành Fullstack Developer.\n- Hiểu và lập trình RESTful API, Background Job, PHP-Laravel.\n- Kỹ năng: PHP, MySQL, Laravel, NextJS, VueJS, Docker, Design pattern.\n- Có kinh nghiệm làm việc, thiết kế CSDL quan hệ như MySQL, Postgresql.\n- Có kỹ năng xử lý vấn đề, tối ưu hóa, refactor, debug.\n- Có kinh nghiệm làm việc theo phương pháp Agile/Scrum và sử dụng các công cụ hỗ trợ như KanBan, Gantt Chart, Project Manager, Git.\n- Có kỹ năng giao tiếp tốt, làm việc nhóm hiệu quả và có tinh thần học hỏi cao.\n- Chăm chỉ, đam mê lập trình, ham học hỏi kiến thức, công nghệ mới.\n- Ưu tiên ứng viên đã từng làm việc trong môi trường product với các sản phẩm SaaS, ERP, HRM, CRM; hiểu rõ quy trình phát triển các sản phẩm này. Đặc biệt những hiểu biết về các phần mềm Base, 1Office, Zoho, Jira, Asana, VtigerCRM … là một lợi thế.\n\nQuyền lợi:\n- Mức lương: Upto 20m++\n- Cơ hội tiếp cận với các công nghệ mới.\n- Môi trường làm việc trẻ, năng động, đa văn hóa.\n- Thưởng lương tháng 13.\n- Review lương tối thiểu 2 lần/năm theo năng lực và đóng góp.\n- Đóng BHXH đầy đủ theo quy định nhà nước.\n\nĐịa điểm làm việc:\n- Hà Nội: Số nhà 76 đường 23 Khu đô thị thành phố Giao lưu, Bắc Từ Liêm\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n- Thứ 7 (từ 09:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3260, 1120, 2, 'Lập Trình Web App ( .Net, C#)', 'Mô tả công việc\n- Xây dựng các ứng dụng trên nền tảng web bằng React và Dotnet/NodeJs/PHP\n- Tham gia công đoạn tìm hiểu yêu cầu, phân tích, thiết kế, nghiên cứu công nghệ khi được phân công\n- Thực hiện công việc theo yêu cầu từ quả lý\n\nYêu cầu ứng viên\n- Thành thạo HTML/CSS\n- Có kinh nghiệm xây dựng web bằng React\n- Có khả năng xây dựng API bằng một trong những ngôn ngữ lập trình C sharp, php, java, js (node js), python...\n- Thành thạo các câu lệnh truy vấn SQL\n- Am hiểu về dotnet là một lợi thế\n\nQuyền lợi\n- Mức lương cơ bản từ  10 - 20 triệu tùy theo năng lực và vị trí công việc:\n10 - 12 triệu với kinh nghiệm 1-2 năm.\n12- 20 triệu với kinh nghiệm trên 2+ năm.\n- Sẽ được trao đổi mức lương cụ thể khi phỏng vấn.\n- Được tổ chức sinh nhật, nghỉ lễ, nghỉ phép và hưởng quyền lợi theo Luật lao động.\n- Đồng nghiệp và môi trường làm việc năng động\n- Cơ hội được học tập và đào tạo nội bộ về các kỹ năng trong công việc.\n\nĐịa điểm làm việc\n- Nghệ An: Tầng 22 Handico 30 Quang Trung, TP Vinh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 07:45 đến 17:00)\n- Thứ 7 luân phiên nghỉ/làm\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Nghệ An', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3261, 1304, 2, 'Database Developer (Mid Level)', 'Mô tả công việc:\n- Join Workshop with customers to grasp requirements.\n- Work with business analysts to understand requirements.\n- Design & implement database handling: create table, write store procedure / function / view/ trigger... with database management systems (e.g., Oracle, SQL Server, MySQL, PostgreSQL...)\n- Experience with data modeling and normalization\n- Experience with database security\n- Monitor database performance\n- Troubleshoot database problems\n- Present the database structure to the project\'s IT team handle data migration (handling of putting old data into system).\n- Experience with NoSQL database\n- Support DEV about related issues.\n\nYêu cầu ứng viên:\n- Required Skills\n- 3 years experience as Database Developer.\n- Ability to learn quickly new technologies.\n- Able to work both independently and as part of a team.\n- Ability to effectively prioritize and execute tasks in a high-pressure environment.\n- Ability to openly present her/his own ideas.\n- Good understanding at software development processes.\n- Excellent logical thinking ability.\n\nEducation:\n- Bachelor Degree in Computer Science/ Information Technology or equivalent;\n\nLanguage skills:\n- Vietnamese - Fluent Native\n- English Language Skills\n\nQuyền lợi:\n- Competitive salary and benefits\n- Working time: 8:30AM - 05:30PM, Monday – Friday;\n- 12 days of annual leave + 3 days of sick leave + 1 day of birthday per year\n- Participated in social insurance, unemployment insurance, health insurance and full policies according to the labor law;\n- 13th month salary & bonus policies, allowances at the Company;\n- UNIT-Care health care insurance by level;\n- Salary increases according to company regulations or unexpected salary raise in case of outstanding ability;\n- Professional and dynamic working environment, unlimited promotion opportunities;\n- Opportunity to participate in many large projects in Vietnam & abroad;\n- Work on the latest technology platform;\n- Join in company trip, teambuilding & community activities.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 374 Võ Văn Tần, phường 5, Quận 3\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3262, 1242, 2, 'Back End Python Developer (Python, AWS)', 'LG CNS is a leading IT service provider, delivering innovative solutions in AI, cloud computing, big data, and smart factory automation. Our Vietnam Build Center is expanding, and we are looking for talented Python Developers to join our growing team.\n\n- Develop, optimize, and maintain scalable Python applications.\n- Collaborate with cross-functional teams to design, develop, and deploy software solutions.\n- Write clean, efficient, and well-documented code following best practices.\n- Debug and troubleshoot issues to ensure application stability and performance.\n- Work with databases, APIs, and third-party libraries to build robust applications.\n- Participate in code reviews, design discussions, and Agile development processes.\n\n[Yêu cầu ứng viên]\n\n[Required]\n- 3+ years of experience in Python development.\n- Bachelor\'s degree\n- Proficiency in Python frameworks such as Fast API\n- Experience in working with ORM such as SlqAlchemy, JPA\n- Experience working with DB Configuration Management such as Alembic, Flyway\n- Experience in debugging in Kubernetes, Docker/Container, Cloud (AWS) environment\n- Experience in AWS Cognito/AWS S3/AWS SES/AWS Lambda\n- Strong problem-solving and analytical skills.\n- Good communication skills and the ability to work in a team environment.\n\n[Preferred]\n- Experience with Resource optimization\n- Experience in solving complex problems with Application and Cloud resource\n- Experience in Digital Marketing domain\n\n[Quyền lợi]\n- Attractive salary and bonus will be discussed after going through CV & Interview\n- Topik allowance\n- Review capacity annually and adjust salary increases according to work performance.\n- Health care: Premium health insurance, Annual health check-up\n- Young working environment\n- Good career development opportunities with interesting and challenging projects.\n- English, Korean, technical, soft skills training courses.\n- Opportunity to learn special courses from LG CNS, new technology and security.\n- Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)\n- Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.\n- Working hours: 8 hours from Monday - Friday (8 hours/day)\n\n[Địa điểm làm việc]\nHà Nội: Tầng 15, Keangnam Landmark 72, Nam Từ Liêm\n\n[Thời gian làm việc]\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\n[Cách thức ứng tuyển]\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3263, 1229, 2, 'Frontend Developer (Asp.Net, Blazor)', 'Mô tả công việc\n- Tham gia phát triển giao diện người dùng cho các ứng dụng web trên nền tảng ASP.NET và Blazor.\n- Phối hợp với team Backend để tích hợp API, xử lý dữ liệu và tối ưu trải nghiệm người dùng.\n- Đảm bảo hiệu năng, khả năng phản hồi và khả năng mở rộng của giao diện người dùng.\n- Tham gia vào quy trình phân tích, thiết kế và đề xuất giải pháp kỹ thuật cho sản phẩm.\n- Tối ưu code, review code, viết unit test và đảm bảo tuân thủ coding standards của dự án\n\nYêu cầu ứng viên\n- Có kinh nghiệm từ 3 năm phát triển frontend sử dụng ASP.NET (Razor/Blazor).\n- Hiểu rõ về C#, .NET Core, Entity Framework, WebAssembly là một lợi thế.\n- Thành thạo HTML5, CSS3, JavaScript, Bootstrap hoặc các UI framework tương tự.\n- Có kinh nghiệm làm việc với RESTful API.\n- Tư duy logic tốt, khả năng giải quyết vấn đề và chủ động trong công việc.\n- Ưu tiên ứng viên từng làm việc trong môi trường Agile/Scrum.\n- Tinh thần, thái độ làm việc hợp tác\n- Có tổ chức và tinh thần tích cực thúc đẩy team\n- Chú trọng vào kết quả công việc\n- Có đam mê, không e ngại công cụ và công nghệ mới.\n\nQuyền lợi\n- Mức lương hấp dẫn, review định kỳ 2 lần/năm.\n- Làm việc trong môi trường công nghệ hiện đại, chuyên nghiệp.\n- Thưởng theo hiệu suất và các chính sách phúc lợi cạnh tranh.\n- Tham gia các dự án đa dạng về công nghệ, cơ hội phát triển lên vị trí Leader hoặc Fullstack Developer.\n- Được đào tạo nâng cao kỹ năng lập trình, soft skills và các công nghệ mới.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Tòa nhà SBI, Đường 03, CVPM Quang Trung, P. Tân Chánh Hiệp, Quận 12\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n- Thứ 2 - Thứ 6 ( 8h00 -17h00)\nThứ 7 (8h00 - 12h) - Làm online\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3264, 1338, 2, 'Blockchain Developer', 'Mô tả công việc:\n- Phát triển và bảo trì giao diện người dùng (UI) cho các ứng dụng DeFi và Crypto trên nền tảng di động (iOS và Android), tích hợp với blockchain (Ethereum, Solana, v.v.).\n- Thiết kế và triển khai các tính năng frontend di động tương tác với smart contract (ví dụ: AMM, staking, lending, NFT).\n- Tối ưu hóa App Listing và App Store Optimization (ASO) cho ứng dụng di động trên App Store và Google Play, bao gồm metadata, từ khóa, hình ảnh và nội dung quảng bá.\n- Phối hợp với đội ngũ backend và blockchain để tích hợp API và dịch vụ on-chain vào ứng dụng di động.\n- Phân tích dữ liệu ASO (tỷ lệ tải, đánh giá, xếp hạng) và đề xuất cải tiến để tăng khả năng hiển thị ứng dụng trên các kho ứng dụng.\n- Đảm bảo giao diện di động thân thiện với người dùng, tuân thủ chính sách của App Store/Google Play và tối ưu hiệu suất trên các thiết bị di động.\n\nYêu cầu ứng viên:\n- Tối thiểu 2 năm kinh nghiệm phát triển ứng dụng di động, ưu tiên trong các dự án blockchain/DeFi.\n- Thành thạo các ngôn ngữ và công cụ lập trình di động:\n  - Android: Kotlin, Java, C/C++ (NDK), Dart (Flutter là một lợi thế).\n  - iOS: Swift, Objective-C, React Native (JS) là một lợi thế.\n- Kinh nghiệm tích hợp frontend di động với blockchain qua Web3.js, Ethers.js, hoặc Solana Web3.js.\n- Hiểu biết về smart contract (Solidity, Rust) và các giao thức DeFi (Uniswap, Aave, v.v.).\n- Kiến thức về ASO, bao gồm tối ưu hóa từ khóa, mô tả ứng dụng, và phân tích hiệu suất qua các công cụ như App Annie, Sensor Tower.\n- Thành thạo công cụ phát triển di động: Xcode, Swift Package Manager, Android Studio.\n- Ưu tiên: Kinh nghiệm phát triển ứng dụng di động đa nền tảng (React Native, Flutter) và tích hợp blockchain trên mobile.\n- Có khả năng đọc hiểu tài liệu tiếng Anh.\n\nQuyền lợi:\n- Thu nhập cạnh tranh, thưởng dựa trên hiệu quả công việc.\n- Tham gia dự án blockchain thực chiến, ảnh hưởng trực tiếp đến thiết kế và vận hành ứng dụng di động.\n- Môi trường làm việc chuyên nghiệp, cởi mở, khuyến khích sáng tạo và đổi mới.\n- Cơ hội tiếp cận các công nghệ blockchain và công nghệ di động tiên tiến nhất.\n- Đồ ăn vặt, snack giữa giờ thoải mái; hoạt động gắn kết như ăn lẩu Haidilao hàng tháng.\n- Thời gian làm việc linh hoạt: 9h00 - 17h30 (Thứ 2 đến Thứ 6).\n- Công ty chi trả chi phí gửi xe tại tòa nhà.\n\nĐịa điểm làm việc:\n- Hà Nội: Cầu Giấy\n- Hà Nội: Thanh Xuân\n- Hà Nội: Nam Từ Liêm\n- Hà Nội: Ba Đình\n- Hà Nội: Đống Đa\n- Hà Nội: Hoàn Kiếm\n- Hà Nội: Hai Bà Trưng\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 09:00 đến 17:30)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3265, 1298, 2, 'Lập Trình Viên .NET', 'Mô tả công việc: - Tham gia vào giai đoạn thiết kế phần mềm. - Lập trình, phát triển các phần mềm trên nền Webform APS.NET (C#), ADO.NET Entity Framework, .NET Core, Bootstrap CSS framework, MVC4 / 5, MVVM, WCF, WebAPI, Angular, ReactJS, NextJS, Micro Service. - Sử dụng thành thạo các công cụ: Visual Studio.NET, IIS, MS SQL Server, Oracle Database, Crystal Report, Visual Studio Code. - Có khả năng thiết kế cơ sở dữ liệu. - Phát triển các báo cáo sử dụng Crystal Report, Microsoft Report, T-SQL, PL/SQL. - Cài đặt, triển khai phần mềm trên môi trường của khách hàng. Hiểu biết về kiến trúc hệ thống. - Tham gia hỗ trợ tổ chức đào tạo, hỗ trợ người dùng trong quá trình chạy UAT và vận hành.\n\nYêu cầu ứng viên: - Tối thiểu 2 năm kinh nghiệm lập trình trên .NET. - Ưu tiên ứng viên có kinh nghiệm với .Net Core, ReactJS, NextJS. - Trình độ Đại học chuyên ngành CNTT hoặc tương đương. - Có kinh nghiệm làm theo phương thức agile scrum and waterfall. - Ưu tiên ứng viên có kinh nghiệm làm việc theo quy trình CMMI.\n\nQuyền lợi: - Lương: 12.000.000 - 25.000.000 (tùy theo level). - Thời gian làm việc: thứ 2 đến thứ 6, 08h30 đến 17h30. - Đánh giá nhân sự và điều chỉnh lương: định kỳ 1 năm 1 lần. - Nghỉ phép: 12 ngày/năm. - Nghỉ lễ, nghỉ thai sản, nghỉ ốm, nghỉ hiếu hỉ: theo quy định chung của luật Lao động. - BHXH, BHYT, BHTN cho 100% cán bộ sau thời gian thử việc. - Chính sách thu hút và đãi ngộ nhân tài. - Chính sách ưu đãi đối với nhân viên có thâm niên làm việc tại công ty. - Thu nhập: lương tháng 13; thưởng theo dự án, thưởng theo kết quả kinh doanh và mức độ đóng góp; thưởng theo năng lực và mức độ hoàn thành công việc của từng thành viên – đánh giá hàng tháng và trả thưởng theo quý; thưởng các ngày lễ lớn. - Chế độ nghỉ mát, du xuân, liên hoan cuối năm cho nhân viên và gia đình. - Các hoạt động giao lưu bóng đá, golf, văn nghệ... - Chính sách đào tạo về chuyên môn, nghiệp vụ và kỹ năng cho nhân viên. Hỗ trợ 100% kinh phí học và thi các chứng chỉ chuyên môn.\n\nĐịa điểm làm việc: - Hà Nội: Tầng 22 tòa nhà Viwaseen, số 48 Tố Hữu, Trung Văn, Nam Từ Liêm. \n\nThời gian làm việc: - Thứ 2 - Thứ 6 (từ 08:30 đến 17:30).\n\nCách thức ứng tuyển: - Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3266, 1391, 2, 'Lập Trình Viên .NET', '1. Tham gia xây dựng, phát triển các dự án phần mềm mới của công ty \n2. Bảo trì, nâng cấp, cập nhật các dự án phần mềm hiện có \n3. Hỗ trợ vận hành, tìm hiểu nhu cầu và phản hồi từ người sử dụng để đề xuất các cập nhật, nâng cấp hoặc xây mới cần thiết \n4. Chủ động ước lượng và kiểm soát công việc đã nhận \n5. Tham gia nghiên cứu và trình bày các công nghệ mới \n6. Báo cáo và thực hiện các công việc theo yêu cầu của quản lý\n\nYêu cầu ứng viên\n1. Tốt nghiệp Đại học chuyên ngành CNTT, Toán Tin hoặc tương đương \n2. Có ít nhất 1 năm kinh nghiệm với ASP.NET, MVC5, ASP.NET Core, C++/C#, Web API, RESTful API \n3. Có kinh nghiệm lập trình với hệ CSDL: SQL server, MySQL, và 1 số No-SQL: Elasticsearch, Redis \n4. Thành thạo HTML, CSS, Bootstrap, Javascript, Jquery. Đã làm việc với Angular hoặc ReactJS \n5. Có kinh nghiệm làm việc với Kafka, RabbitMQ là một lợi thế. \n6. Làm việc nhóm hiệu quả với công cụ Git, Gitflow hoặc TortoiseSVN \n7. Tiếng Anh giao tiếp, đọc viết tốt \n8. Có khả năng giao tiếp tốt, chủ động, trung thực, năng động, khả năng làm việc nhóm tốt. Có trách nhiệm cao, và chịu được áp lực công việc \n9. Có khả năng học hỏi nhanh, thích tìm hiểu và thực hiện các công việc mới\n\nQuyền lợi\nLương: up to 20.000.000 (thương lượng)\nNgày nghỉ lễ theo quy định của Nhà nước\nThời gian làm việc 8:30 đến 17:30 từ thứ 2 đến thứ 6, thứ 7 cách tuần (nghỉ trưa 1h30)\nTham gia bảo hiểm xã hội đầy đủ cho nhân viên trên tổng lương. Ngoài ra có thêm gói bảo hiểm sức khỏe mở rộng và hỗ trợ gói tập sức khỏe cho nhân viên\nReview lương: 2 lần/ năm, thưởng hè + thưởng Tết...\nDu lịch công ty, teambuilding, tiệc sinh nhật hàng tháng và các phúc lợi khác\n\nĐịa điểm làm việc\n- Hà Nội: Bằng Liệt, Hoàng Mai\n\nThời gian làm việc\nThứ 2 - Thứ 6 (từ 08:30 đến 18:00)\nThứ 7 cách tuần\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3267, 1388, 2, 'Thực Tập Sinh Lập Trình (FE/BE)', '- Tham gia đào tạo trong vòng từ 2 - 3 tháng theo lộ trình của công ty.\n- Được đào tạo kiến thức chuyên môn và kỹ năng mềm để phục vụ công việc.\n- Hoàn thành dự án training cá nhân theo yêu cầu của công ty.\n- Tham gia training on job qua các dự án phát triển phần mềm với khách hàng.\n\nYêu cầu ứng viên\nMust have\n- Sinh viên năm 3 trở lên, chuyên ngành CNTT, khoa học máy tính hoặc các chuyên ngành liên quan; hoặc có chứng chỉ tham gia các khóa học lập trình.\n- Thời gian thực tập tối thiểu 5 buổi/tuần.\n- Có máy tính cá nhân.\n- Chủ động, ham học hỏi, chăm chỉ, tư duy tốt.\n\nNice to have\n- Đã từng thực tập vị trí tương đương là một lợi thế;\n- Ưu tiên ứng viên có dự án cá nhân.\n- Có hiểu biết về các mô hình MVC, MVVM\n- Ưu tiên ứng viên đã từng làm việc với các ngôn ngữ lập trình như: NodeJS, PHP, ReactJS.\n- Ưu tiên ứng viên đã từng làm việc với các database như MySQL, PostgreSQL, MongoDB\n\nQuyền lợi\n- Được training on job, tham gia trực tiếp vào các dự án thực tế của công ty ngay trong thời gian đào tạo.\n- Được hỗ trợ thủ tục dấu đỏ, giấy xác nhận thực tập.\n- Được đào tạo kỹ năng lập trình web, mobile để lựa chọn ngôn ngữ lập trình phù hợp.\n- Thử sức với các dự án hấp dẫn trong và ngoài nước.\n- Được làm việc trong môi trường cởi mở, năng động.\n- Cơ hội trở thành nhân viên chính thức sau khi hoàn thành khóa đào tạo.\n- Lộ trình: thực tập (tối thiểu 3 tháng) -> Thử việc (2 tháng) -> Nhân viên chính thức.\nQuyền lợi sau khi ký hợp đồng chính thức:\n- Mức lương khởi điểm hấp dẫn, tương xứng với năng lực làm việc.\n- Vé xe hàng tháng tại công ty.\n- Được hưởng đầy đủ các chế độ bảo hiểm, bảo hiểm y tế theo luật Việt Nam và quy định của công ty.\n- Công ty cung cấp đầy đủ thiết bị máy tính để làm việc.\n- Đánh giá tăng lương định kỳ từ 6 tháng/lần (tháng 3 và tháng 9).\n- Tối thiểu 13 tháng lương, thưởng định kỳ ngày lễ 30/4, 2/9,...\n- Hoạt động thể thao, câu lạc bộ bóng đá được công ty hỗ trợ.\n- Khám sức khỏe định kỳ 1 năm/1 lần.\n- Nghỉ thứ 7, chủ nhật + 12 ngày phép/năm.\n- Thời gian làm việc từ đủ 3 năm sẽ được cộng thêm 1 ngày phép vào các năm tiếp theo.\n- Nghỉ ngày lễ Tết, 30/4, giỗ tổ Hùng Vương, Tết dương lịch,...\n- Team building hàng tháng, du lịch hàng năm, sinh nhật hàng tháng cho nhân viên.\n- Môi trường làm việc thoải mái theo phong cách Âu Mỹ (Western Style) với chế độ môi trường vui vẻ, thoải mái;\n- Được làm việc với thời gian linh hoạt từ T2 – T6 (9h – 18h), nghỉ trưa 1h30p.\n- Cơ hội học hỏi và phát triển năng lực bản thân thông qua những dự án thực tế.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3268, 1428, 2, 'Nhân Viên Lập Trình  C#', '- Lập trình chương trình C# điều khiển Máy tự động tích hợp I/O card, motion card (Ajinextek, ADLINK, Advandtech) và các thiết bị khác.\n- Có kinh nghiệm lập trình truyền thông công nghiệp RS485, RS232, Ethernet TCP/IP, Modbus...\n- Có kinh nghiệm lập trình liên quan tới hệ thống MES, GMES, CIM\n- Làm việc với các loại máy Handler, Tester Machine\n- Có kiến thức về các linh kiện, thiết bị hệ thống điện của máy tự động\n- Cải tiến chương trình có sẵn để phù hợp với yêu cầu công nghệ.\n- Chỉnh sửa lỗi máy khi vận hành phát sinh lỗi liên quan đến phần cứng và phần mềm.\n- Có khả năng đi setup máy tại các nhà máy của Samsung.\n\nYêu cầu ứng viên:\n- Có kiến thức cơ bản về lập trình C#. Đã setup máy tự động hóa của Samsung.\n- Hiểu biết về các nguyên tắc phát triển phần mềm và quy trình phát triển phần mềm.\n- Có khả năng học hỏi nhanh và thích nghi với công nghệ mới.\n- Kỹ năng phân tích và giải quyết vấn đề tốt.\n- Có kiến thức cơ bản về cơ sở dữ liệu và SQL.\n- Khả năng làm việc độc lập và làm việc nhóm hiệu quả.\n- Tinh thần trách nhiệm cao, chủ động trong công việc.\n- Có hiểu biết cơ bản về lĩnh vực tự động hóa là một lợi thế.\n\nQuyền lợi:\n- Môi trường làm việc chuyên nghiệp, năng động và thân thiện.\n- Cơ hội học hỏi và phát triển kỹ năng trong lĩnh vực tự động hóa và phát triển phần mềm.\n- Được đào tạo và hướng dẫn bởi các chuyên gia có kinh nghiệm trong ngành.\n- Lương thưởng cạnh tranh, phù hợp với năng lực.\n- Được tham gia đầy đủ các chế độ bảo hiểm theo quy định của pháp luật.\n- Chế độ nghỉ phép, nghỉ lễ theo quy định.\n- Cơ hội thăng tiến rõ ràng dựa trên năng lực và đóng góp.\n\nĐịa điểm làm việc:\n- Bắc Ninh: CÔNG TY TNHH KNK VINA, Lô CN5B-2, KCN QUẾ VÕ III, PHƯỜNG VIỆT HÙNG, THỊ XÃ QUẾ VÕ, TP Bắc Ninh.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bắc Ninh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3269, 583, 2, 'Java Developer', 'Mô tả công việc\n- Investigate technical issues reported by customers, troubleshoot, propose recommendations / workarounds to resolve the issues.\n- Lead customer troubleshooting calls when being requested.\n- Assist in creating and updating technical documentation, FAQs, and self-service resources to improve customer self-support.\n- Gather insights from recurring customer feedback, issues and collaborating with Product Engineering team to prioritize fixes and feature enhancements.\n\nYêu cầu ứng viên\n- A Bachelor\'s degree in Computer Science, Engineering, or a related technical field.\n- 5+ years of experience in software development.\n- Proficiency in analyzing and debugging software systems, including reading logs and investigating backend workflows.\n- Excellent verbal and written communication skills in English.\n- Hands-on experience with Java.\n- Strong problem-solving, analytical, and organizational skills with a detail-oriented mindset.\n- Experience supporting customers is a plus.\n\nQuyền lợi\n- Free snack-drink, coffee, weekly happy hour, monthly birthday party\n- Working time: Monday – Friday | 9am - 6pm to some extent flexible working hours Friendly, professional and open working environment\n- Opportunities to improve English skills within an international team – English is an official language\n- You will become a key member of WATA TECH as we are growing faster and bigger now\n- Skills up plan with Tech talk, soft skill talk, English club, working process training\n- Company trip yearly\n- Friendly, professional and open working environment\n\nĐịa điểm làm việc\n- Hồ Chí Minh\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3270, 1332, 2, 'Fullstack Web Developer (Python/Reactjs)', '• Tham gia phát triển website và các tính năng theo yêu cầu của khách hàng Nhật, Âu, Mỹ.\n• Hợp tác và trao đổi công việc với Team Member, Team Leader.\n• Tham gia phát triển các công đoạn phân tích yêu cầu, Coding, viết tài liệu API, Unit Test sử dụng Python và React.JS\n• Tham gia thiết kế cơ sở dữ liệu, thiết kế kiến trúc dự án.\n• Có thể đảm nhận các công việc phát triển cả backend, frontend.\n\n• Có kiến thức nền tảng tốt về lập trình (OOP, cấu trúc dữ liệu và giải thuật…).\n• Có kiến thức nền tảng tốt về cơ sở dữ liệu quan hệ (thiết kế, sử dụng…).\n• Có kiến thức nền tảng tốt về hệ điều hành linux, cấu hình, triển khai web server.\n• Từ 2 năm kinh nghiệm lập trình sử dụng ngôn ngữ Python trên các FrameWork như Django, FastAPI...\n• Từ 1 năm kinh nghiệm lập trình Frontend sử dụng HTML/CSS/Javascript, TypeScript trên các framework như Reactjs, Vuejs…\n• Có kinh nghiệm lập trình trên môi trường cloud đặc biệt là AWS (Ec2, lambda…) là điểm cộng\n• Có khả năng tìm hiểu, thích ứng tốt với công nghệ mới.\n• Có kinh nghiệm đảm nhiệm các vị trí project team leader là điểm cộng.\n• Nhiệt tình, teamwork tốt, sẵn sàng học hỏi các công nghệ mới để đáp ứng công việc.\n• Có tư duy hệ thống, tư duy logic tốt, có khả năng đề xuất vấn đề và giải quyết vấn đề.\n\n• Mức lương: thỏa thuận.\n• Được xây dựng lộ trình và hỗ trợ phát triển trở thành keymember, team leader.\n• Review lương hằng năm, lương tháng 13 theo hiệu quả kinh doanh của công ty.\n• Tham gia BHXH, BHYT, BHTN đầy đủ theo Luật lao động.\n• Nghỉ phép 12 ngày/năm.\n• Hưởng mọi quyền lợi nghỉ Lễ Tết kèm theo thưởng ngày Lễ/Tết trong năm.\n• Trợ cấp đối với nhân sự có thâm niên.\n• Team building định kỳ hàng Quý, du lịch 1 lần/năm.\n• Thời gian làm việc: 08:00 đến 17:00 từ Thứ Hai đến thứ Sáu.\n• Môi trường làm việc thoải mái, trẻ trung, năng động, có nhiều cơ hội thăng tiến và phát triển bản thân.\n\n- Hà Nội: Tầng 6, số 12 Mễ Trì Hạ, phường Mễ Trì, Nam Từ Liêm\n\nThứ 2 - Thứ 6 (từ 08:00 đến 17:00)\n\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3271, 1141, 2, 'Lập Trình Viên Backend', '- Lập trình web (backend) bằng PHP, trên framework do công ty tự phát triển hơn 17 năm, gồm các nhóm ứng dụng chính: Website doanh nghiệp, trường học, Portal bộ ban ngành, TMĐT, ERP,….\n- Quản lý source code bằng SVN.\n- Quản lý công việc bằng công cụ quản trị dự án nội bộ.\n- Làm việc với bộ phận kiểm thử và phát triển sản phẩm để tối ưu, sửa lỗi, phát triển chức năng mới.\n- Code theo các tiêu chuẩn ATTT, hiệu năng của tập đoàn Viettel.\n\n- Tốt nghiệp chuyên ngành Công nghệ thông tin, Khoa học máy tính, Toán tin... hoặc chuyên ngành khác có liên quan\n- Từ một năm kinh nghiệm ở vị trí tương đương\n- Có kiến thức cơ bản về lập trình WEB (PHP / HTML / CSS / JAVASCRIPT).\n- Hiểu biết về MVC Framework\n- Có kiến thức về các hệ quản trị cơ sở dữ liệu, nhất là NoSQL (MongoDB), Solr, nếu chưa biết sẽ được đào tạo.\n- Đảm bảo nghiêm túc giờ giấc theo giờ hành chính.\n\n- Thu nhập lên tới 20M/tháng, 2-6 tháng xét tăng lương 1 lần\n- Chính sách phát triển bản thân phù hợp với từng vị trí. Có cơ hội tiếp cận với các công nghệ mới nhất.\n- Sau 2 tháng thử việc sẽ được cân nhắc lên nhân viên chính thức, hưởng đầy đủ quyền lợi về BHXH\n- Nghỉ phép: 12 ngày/ năm\n- Thưởng lương tháng 13\n- Môi trường làm việc năng động, sáng tạo với đội ngũ CBNV đầy nhiệt huyết. Chế độ du lịch hàng năm và tham gia các hoạt động teambuilding, sự kiện công ty, tiệc mặn ngọt,....\n\n- Hà Nội: Xuân La, Tây Hồ\n\n- Thời gian làm việc: Thứ 2 - Thứ 7 (từ 08:00 đến 17:30), nghỉ thứ 7 cách tuần.\n\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3272, 1241, 2, 'Chuyên Viên Lập Trình', 'Mô tả công việc\n- Phát triển và tối ưu hóa giao diện người dùng bằng Angular\n- Phối hợp với Designer để đảm bảo UI/UX theo đúng bản vẽ thiết kế (Figma, Zeplin...)\n- Viết mã sạch, tối ưu, dễ bảo trì và có tính mở rộng cao\n- Phối hợp với Tester để fix bug và hoàn thiện chức năng\n- Tham gia code review, đóng góp ý kiến kỹ thuật và cải tiến UI/UX\n- Đảm bảo hiệu suất, bảo mật và tương thích trình duyệt / thiết bị\n\nYêu cầu ứng viên\n- Trình độ học vấn: Tốt nghiệp Đại học/ Cao đẳng chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Thiết kế phần mềm hoặc liên quan.\n- Kinh nghiệm: Tối thiểu 2 năm kinh nghiệm lập trình Frontend, trong đó ít nhất 1 năm sử dụng Angular.\n- Kiến thức:\n  + Thành thạo Angular (từ version 9 trở lên), hiểu rõ các concepts: component, module, service, routing, reactive forms, RxJS...\n  + Hiểu biết tốt về HTML5, CSS3, SASS/SCSS, JavaScript/TypeScript.\n  + Có kiến thức cơ bản về UI/UX, responsive web design, RESTful API.\n  + Ưu tiên biết thêm ReactJS, VueJS, hoặc framework frontend khác.\n  + Ưu tiên có kinh nghiệm làm việc với Git, CI/CD, quản lý source code.\n- Khả năng:\n  + Kỹ năng debug, tối ưu mã nguồn, tối ưu tốc độ tải trang.\n  + Kỹ năng đọc tài liệu kỹ thuật và phối hợp nhóm tốt.\n  + Khả năng tự học nhanh, nắm bắt công nghệ mới.\n  + Kỹ năng viết mã sạch, dễ maintain, tuân thủ guideline.\n- Yêu cầu khác:\n  + Ưu tiên ứng viên có sản phẩm demo / GitHub repo / đã từng làm dự án thực tế.\n  + Có khả năng sử dụng công cụ quản lý dự án: Jira, GitLab, hoặc tương đương.\n\nQuyền lợi\n- Chế độ đãi ngộ\n  + Mức lương: cạnh tranh hấp dẫn (sẵn sàng offer cao khi đủ năng lực) + Phụ cấp (Ăn ca: 700.000 VNĐ/tháng; Gửi xe: 120.000 VNĐ/tháng; trợ cấp máy tính cá nhân (nếu có): 300.000 VNĐ/tháng).\n  + Chính sách thưởng: Thưởng Lễ, Tết, sinh nhật + thưởng dự án + thưởng thâm niên + Lương tháng 13 + các thưởng khác theo quy định Công ty tại thời điểm hiện hành.\n  + Làm việc trong môi trường trẻ trung, năng động, coi trọng năng lực và khả năng sáng tạo\n  + Thường xuyên tổ chức các hoạt động mini game, chương trình các ngày Lễ, Tết, sinh nhật, tham gia hoạt động Teambuilding của công ty..\n- Đào tạo – Phát triển\n  + Cơ hội tiếp cận và học hỏi công nghệ tiên tiến, công nghệ mới\n  + Được công ty tạo điều kiện và hỗ trợ khi tham gia các khóa đào tạo, phát triển năng lực.\n  + Có cơ hội làm những việc thách thức, phát huy hết khả năng bản thân.\n  + Tham gia các sản phẩm công nghệ mới theo kế hoạch phát triển của công ty.\n- Chăm sóc sức khỏe, đời sống\n  + Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm.\n  + Được tặng quà, thăm hỏi nhân các dịp: sinh nhật, cưới hỏi, hiếu hỉ, ốm đau...\n  + Có thể tham gia các câu lạc bộ thể thao: đá bóng, tập yoga, thể dục cải thiện sức khoẻ...\n\nĐịa điểm làm việc\n- Hà Nội: 97-99 Láng Hạ, Đống Đa\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n- Checkin linh hoạt từ 7.30-9.00 am\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3273, 1179, 2, 'Net Developer', '1/ Tham gia trực tiếp Phát triển sản phẩm :\nPhát triển hệ thống phần mềm Hợp đồng điện tử và quản lý ký số\nPhát triển web backend/fontend liên quan tới sản phẩm\nPhát triển API phục vụ xây dựng Mobile Apps và tích hợp hệ thống\nTham gia viết các tài liệu cấu trúc phục vụ phát triển phần mềm\nKiểm tra, đánh giá chất lượng phần mềm sau khi lập trình, đảm bảo phần mềm ổn định, không có lỗi sảy ra khi phát hành.\n\n2/ Triển khai\nNhận yêu cầu, thiết kế và xử lý công việc được giao bởi PM/BA dự án\nĐảm bảo các dự án hoàn thành đúng tiến độ và đạt chất lượng cao\nLàm việc và hỗ trợ trực tiếp với các Team sản phẩm, Mobile Developer, CSKH, Khối Vận hành,…\nTham gia tư vấn, giải đáp kỹ thuật trong quá trình chào sản phẩm\nHướng dẫn hỗ trợ khách hàng level kỹ thuật, hệ thống.\n\nYêu cầu ứng viên:\nCó 3  năm kinh nghiệm lập trình với công nghệ như ASP.Net,.Netcore, MVC, Entity Framework, LinQ, Restful API, WCF.\nCó kiến thức về Javascript, XML/HTML/CSS, Ajax, jQuery, React, Angular, Vue.\nHệ quản trị CSDL MS SQL Server, Mongo DB, PostgreSQL.\nCó kiến thức về kiến trúc MicroService, Containers/Docker.\nĐam mê công việc, sự sáng tạo và đổi mới.\nKỹ năng giải quyết vấn đề linh hoạt, sẵn sàng phá bỏ các rào cản, tích cực tìm kiếm các giải pháp thay thế để đạt mục tiêu cần có.\nTinh tần hợp tác, chủ động, nhiệt tình, hòa đồng trong công việc, làm việc tốt theo nhóm.\nCó tinh thần trách nhiệm cao. Cầu thị, tự tin, quyết đoán.\n\nQuyền lợi:\nQUYỀN LỢI ỨNG VIÊN\nTHU NHẬP\nLương tháng thỏa thuận theo năng lực ứng viên\nThưởng KPIs năm từ upto 2 tháng lương/năm\nGói phúc lợi tiền mặt hơn 9 triệu/năm vào các dịp Lễ, Tết, Sinh nhật Tập đoàn...\nXét tăng lương theo năng lực và kết quả công việc định kỳ 1 lần/năm. Hoặc tăng lương đột xuất theo hiệu quả công việc.\n\nCHẾ ĐỘ ĐÀO TẠO VÀ PHÁT TRIỂN  \nĐài thọ 100% chi phí tham gia các khóa học, thi chứng chỉ CNTT Quốc tế.\nChính sách phát triển, thăng tiến theo Career Path phù hợp với từng vị trí, từng phòng ban.\nCơ hội tiếp cận với các công nghệ mới nhất: Cloud, Big data...\nCơ hội làm việc trong Công ty là Top 1 đối tác tư vấn và cung cấp, triển khai giải pháp Chuyển đổi số, Bảo mật, Cloud cho tổ chức và doanh nghiệp tại Việt Nam.\n\nBẢO HIỂM VÀ CHÍNH SÁCH ĐÃI NGỘ\nThời gian làm việc: Thứ Hai – Thứ Sáu; Nghỉ thứ 7 & Chủ Nhật.\nNghỉ phép: 12 ngày/ năm + 1 ngày nghỉ hưởng lương vào dịp sinh nhật bản thân CBNV.\nBảo hiểm xã hội, Bảo hiểm y tế, Bảo hiểm thất nghiệp theo quy định Nhà nước.\nChế độ bảo hiểm nâng cao: CMC Care.\nChế độ đãi ngộ thai sản nâng cao dành cho nhân viên nữ.\nDu lịch hàng năm 1 tuần, teambuilding/dã ngoại định kì 2 lần/năm.\nTham gia các Câu lạc bộ của Công ty và các chương trình trải nghiệm nhân viên đa dạng và phong phú.\nĐược trang bị laptop/thiết bị công nghệ trong quá trình làm việc.\nMôi trường làm việc trẻ trung, chuyên nghiệp.\n\nĐịa điểm làm việc:\n- Hà Nội: Tầng 16, Tòa nhà CMC, 11 Duy Tân, P. Dịch Vọng Hậu, Cầu Giấy.\n\nThời gian làm việc:\nThứ 2 - Thứ 6 (từ 08:00 đến 17:30).\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3274, 1227, 2, 'Kỹ Sư AI (Junior)', 'Mô tả công việc:\n- Phát triển mô hình AI/ML: Tham gia vào việc thiết kế, xây dựng và thử nghiệm các mô hình Machine Learning (ML) và Deep Learning (DL) dưới sự hướng dẫn của các kỹ sư cấp cao.\n- Xây dựng và ứng dụng LLM: Hỗ trợ triển khai và tối ưu hóa các mô hình ngôn ngữ lớn (LLM) trong các dự án liên quan đến xử lý ngôn ngữ tự nhiên (NLP).\n- Phân tích dữ liệu: Tham gia vào các giai đoạn tiền xử lý dữ liệu, phân tích dữ liệu để hỗ trợ phát triển các giải pháp AI.\n- Nghiên cứu và phát triển: Học hỏi, nghiên cứu các công nghệ mới trong lĩnh vực AI/ML, và áp dụng vào các dự án thực tế.\n- Hợp tác nhóm: Làm việc chặt chẽ với các nhóm kỹ thuật và sản phẩm để phát triển và triển khai các giải pháp AI.\n\nYêu cầu ứng viên:\n- Bằng cấp: Tốt nghiệp đại học hoặc sắp tốt nghiệp chuyên ngành Khoa học Máy tính, Công nghệ Thông tin, Toán Tin hoặc các ngành liên quan.\n- Kinh nghiệm: 1-2 năm kinh nghiệm trong phát triển AI/ML là một lợi thế, nhưng không bắt buộc. Chấp nhận sinh viên mới ra trường có kiến thức nền tảng vững chắc về AI/ML.\n- Kỹ năng: Thành thạo một ngôn ngữ lập trình như Python, R, hoặc Java. Khả năng sử dụng Tiếng Anh giao tiếp thành thạo (IELTS 6.5 trở lên). Hiểu biết về các framework ML/DL như TensorFlow, PyTorch, Keras là một lợi thế. Có kiến thức cơ bản về xử lý và phân tích dữ liệu. Tinh thần học hỏi, có khả năng làm việc nhóm và chịu được áp lực công việc. Ưu tiên: Ứng viên đã từng thực hiện các dự án liên quan đến AI/ML trong quá trình học tập hoặc thực tập. Ưu tiên các bạn có thành tích giải thưởng quốc gia, đại học.\n\nQuyền lợi:\n1. Cơ hội thăng tiến: Đến với UPP Global Technology, ứng viên có cơ hội được làm việc trong môi trường trẻ, minh bạch với cơ hội thăng tiến rõ ràng, được tạo điều kiện tối đa để phát triển năng lực cá nhân, tập thể và năng suất làm việc.\n2. Lương thưởng: Lương thỏa thuận theo năng lực up to 20M, nhận 100% lương trong quá trình thử việc. Lương tháng 13, định kỳ đánh giá hiệu quả công việc hàng năm. Thưởng khi có thành tích xuất sắc. Chăm sóc sức khỏe định kỳ hàng năm. Ngoài các gói bảo hiểm cơ bản theo quy định của Luật Lao Động, bạn còn được tham gia gói bảo hiểm sức khỏe của PTI sau thời gian thử việc. Được cấp laptop, máy tính làm việc. Tiền lương làm thêm giờ theo quy định của nhà nước.\n\nCách thức ứng tuyển: Ứng viên gửi 1 bản CV Tiếng Anh kèm link các dự án đã làm. Ngày làm việc: Làm việc từ T2-T6; nghỉ T7, CN, Lễ Tết. Thời gian làm việc linh hoạt: 8 tiếng/ngày, trong khoảng 8h00 - 10h00 và kết thúc trong khoảng 17h00 đến 19h00.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3275, 1317, 2, 'Unity Developer', 'Mô tả công việc\n- Chịu trách nhiệm xây dựng hệ thống và phát triển các dự án mobile game bằng Unity trên Android, iOS (dòng game hyper-casual, puzzle)\n- Chịu trách nhiệm tích hợp các hệ thống SDK, MMP, Ads, Tracking cho các dự án game.\n- Tham gia đóng góp xây dựng, cải tiến ý tưởng sản phẩm game để tăng trải nghiệm người dùng, hoàn thiện sản phẩm tốt nhất.\n- Kết hợp với các bộ phận Artist, Marketing, Game Design để sản xuất các game mobile chất lượng và hữu ích đến người dùng\n- Phối hợp với các thành viên trong team để xây dựng game\n\nYêu cầu ứng viên\n- Có ít nhất 3 năm kinh nghiệm lập trình game di động, ít nhất 2 năm trên nền tảng Unity\n- Nắm vững kiến thức về OOP, SOLID và các nguyên tắc trong lập trình;\n- Kinh nghiệm áp dụng các thuật toán, design patterns để giải quyết vấn đề;\n- Kiến thức về tối ưu assets, cache, memory;\n- Có kinh nghiệm build, xử lý tích hợp SDK, MMP, các định dạng quảng cáo;\n- Nắm vững các thành phần trong Unity và thành thạo C#;\n- Có kinh nghiệm trong việc tối ưu app size, memory, fps, anr, crashes;\n- Tư duy tốt, rành mạch, tập trung vào giải pháp;\n- Có khả năng làm việc độc lập và đội nhóm tốt, tính cách hoà đồng;\n- Chịu được áp lực trong công việc, ưu tiên các ứng viên mong muốn trở thành người dẫn dắt.\n\nQuyền lợi\n- Mức lương: 20tr -30tr++ (thỏa thuận theo năng lực); xét tăng lương định kỳ 2 lần/năm;\n- Nghỉ các chủ nhật và 2 thứ 7/tháng.\n- Thưởng lễ tết, thưởng hiệu quả kinh doanh hàng năm.\n- Được tham gia đầy đủ BHXH/ BHYT/ BHTN theo quy định của luật lao động.\n- Làm việc theo quy trình chuyên nghiệp.\n- Du lịch ít nhất 2 lần/năm, cơ hội du lịch nước ngoài; nhiều hoạt động thể thao/ Teambuilding/ Gala trong năm.\n- Được tham gia các chương trình đào tạo nâng cao năng lực, phát triển bản thân.\n- Cơ hội được làm việc trong môi trường chuyên nghiệp, nhân sự trẻ, năng động.\n- Có cơ hội thăng tiến lên các vị trí Lead, C-Level.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3276, 1210, 2, 'Lập Trình Viên Java (Spring Boot)', 'Mô tả công việc\n- Phân tích yêu cầu và phát triển các tính năng backend: Core, API… cho các dự án của Công ty.\n- Kết nối với các nền tảng e-Commerce (Amazon, Ebay, Etsy, Shopify, Woo Commerce …).\n- Nghiên cứu và áp dụng công nghệ mới phục vụ nhu cầu phát triển hệ thống của Công ty.\n\nYêu cầu ứng viên\n- Tối thiểu 3 năm kinh nghiệm lập trình bằng ngôn ngữ Java sử dụng framework Spring Boot.\n- Nắm vững kiến thức về OOP, Design Pattern, giao tiếp mạng, multi-threading, schedule...\n- Có kinh nghiệm sử dụng ít nhất 1 hệ quản trị cơ sở dữ liệu MySQL, PostgreSQL, Oracle.\n- Nắm chắc kiến thức về thiết kế, chuẩn hóa, tối ưu Database và câu lệnh SQL.\n- Có kinh nghiệm về hệ điều hành Linux.\n- Có kinh nghiệm làm việc với NoSQL, hệ thống Cluster, Caching, MQ, Webhook là một lợi thế.\n- Sử dụng tốt Git.\n- Tư duy logic rõ ràng, rành mạch, khả năng xử lý vấn đề phức tạp.\n- Đề cao tính chủ động và trách nhiệm trong công việc, ý thức chất lượng sản phẩm tốt, chịu được áp lực công việc.\n- Đam mê tìm tòi nghiên cứu học hỏi công nghệ mới, phát triển bản thân.\n- Đọc viết tiếng Anh khá là một lợi thế.\n\nQuyền lợi\n- Lương trả theo năng lực: range lương 18.000.000 => 25.000.000 + thưởng (thỏa thuận theo năng lực khi phỏng vấn) \n- Môi trường trẻ trung với nhiều chế độ đãi ngộ lý tưởng: thưởng lễ tết, lương tháng thứ 13, thưởng theo dự án, thưởng mềm theo hiệu quả công việc, xét tăng lương hàng năm \n- Bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo luật bảo hiểm \n- Chế độ nghỉ mát, du lịch trong nước hoặc nước ngoài từ 1-2 lần/năm \n- Phụ cấp ăn trưa, gửi xe, công tác phí… \n- Đồng nghiệp Mỹ/Việt Nam thân thiện, trẻ trung 9x, môi trường làm việc thoải mái.\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 1 toà nhà Sông Đà 9, số 2 Nguyễn Hoàng, Phường Mỹ Đình 2, Nam Từ Liêm, Nam Từ Liêm.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:00).\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3277, 1118, 2, 'Java Developer', 'Mô tả công việc\n- Chịu trách nhiệm nghiên cứu & phát triển backend sử dụng ngôn ngữ/công nghệ: Java, MySQL, Redis, Memcached, Kafka, ElasticSearch, Docker, K8S,...\n- Thiết kế/lập trình các module, thiết kế giao tiếp cho hệ thống tải lớn hàng trăm triệu người dùng (sử dụng cả Java).\n- Nghiên cứu sử dụng, chỉnh sửa các open source về VoIP, streaming phổ biến.\n- Chi tiết sẽ trao đổi cụ thể khi phỏng vấn.\n\nGiới thiệu về Công ty:\n- Stringee là công ty công nghệ cung cấp nền tảng quản trị doanh nghiệp hợp nhất – Cogover, giúp số hóa toàn diện hoạt động quản trị và vận hành doanh nghiệp. Cogover ứng dụng công nghệ No-code/Low-code và AI, cho phép doanh nghiệp tự xây dựng và tùy chỉnh hệ thống qua thao tác kéo - thả và cấu hình đơn giản, mà không cần lập trình.\n- Hiện tại, Stringee cung cấp 3 bộ sản phẩm chính:\n  - Quản trị khách hàng: CRM, Service, CDP\n  - Quản trị nội bộ: HRM, Recruit, Marketing, Process, Site, Finance\n  - Số hóa giao tiếp: Communication APIs\n- Với hơn 3,000 doanh nghiệp sử dụng, 70 triệu người dùng cuối, và nhiều khách hàng lớn như Viettel, Mobifone, VNDIRECT, Techcombank, TPBank,... Stringee là một trong những nền tảng số Make in Vietnam tiên phong trong chuyển đổi số.\n- Stringee từng đạt giải Nhân tài Đất Việt 2018, Top 10 Sao Khuê 2023, và được Bộ TT&TT công nhận là Nền tảng số xuất sắc Make in Vietnam.\n\nYêu cầu ứng viên\n- Thành thạo Java.\n- Nắm rất vững lập trình hướng đối tượng, Design Pattern.\n- Có kinh nghiệm về unit test và integration test.\n- Hiểu về lập trình đa luồng, non-blocking IO, xử lý bất đồng bộ,...\n- Đã từng làm việc với Socket, TCP/IP, các thư viện như SpringBoot, Netty, Apache MINA là lợi thế.\n- Đã từng làm việc với RabbitMQ, ActiveMQ, Kafka, Docker, K8S,... là lợi thế.\n- Có khả năng làm việc với Linux.\n\nQuyền lợi\n- Lương từ $1000 - $2500 (phụ thuộc vào năng lực và kinh nghiệm của bạn, chúng tôi không bao giờ đãi ngộ thấp hơn khả năng của bạn).\n- Thưởng theo hiệu quả công việc (hoàn thành milestone, deadline, ...), thưởng năm, các dịp lễ tết.\n- Môi trường trẻ, năng động, sáng tạo, hỗ trợ tối đa sự phát triển và công việc của nhân viên.\n- Được đào tạo để thường xuyên nâng cao nghiệp vụ. Cơ hội được học hỏi, làm việc với công nghệ mới.\n- Môi trường chuyên nghiệp với các đối tác nước ngoài.\n- Đóng bảo hiểm và các chế độ khác theo Luật lao động; khám sức khoẻ định kỳ hàng năm.\n- Tham gia các câu lạc bộ thể thao: bóng đá, chạy bộ,...\n- Tham dự các buổi đi chơi, dã ngoại, nghỉ mát,...\n\nĐịa điểm làm việc\n- Hà Nội: Tầng 19, Leadvisors Tower, 643 Phạm Văn Đồng, Cổ Nhuế, Bắc Từ Liêm\n\nThời gian làm việc\n- 8h30 – 17h45 từ thứ 2 đến thứ 6 và ngày thứ 7 đầu tiên của tháng (mỗi tháng chỉ làm 1 ngày thứ 7)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3278, 272, 2, 'Fullstack Developer (Java/ Angular/ ReactJS)', 'Mô tả công việc\n- Thiết kế, phát triển, nâng cấp, bảo trì các dự án với công nghệ Java/ Angular/ ReatJS.\n- Đảm bảo hiệu suất, chất lượng, khả năng đáp ứng tốt nhất của hệ thống.\n- Tương tác với bộ phận kinh doanh, vận hành để hiểu nhu cầu của người sử dụng hệ thống.\n\nYêu cầu ứng viên\n1. Trình độ học vấn/Chứng chỉ\n- Tốt nghiệp đại học chuyên ngành Công nghệ thông tin, Hệ thống thông tin hoặc các lĩnh vực liên quan.\n2. Kinh nghiệm làm việc\n- Có từ 2 năm kinh nghiệm trở lên trong lĩnh vực phân tích, thiết kế, phát triển, mô tả tài liệu, triển khai và thử nghiệm các hệ thống phần mềm với các công nghệ Java/ Angular/ ReactJS.\n3. Kiến thức/Kỹ năng/Năng lực chuyên môn\n- Có kinh nghiệm thực hiện các mẫu thiết kế Java EE như MVC, Singleton, Session Facade, DAO\n- Kinh nghiệm trong lập trình đa luồng, collections, IO, mạng, JSP/Servlets và JDBC.\n- Có kinh nghiệm trong Spring Framework như Spring Boot, Spring MVC, Spring JDBC/Data, Spring Security.\n- Có kinh nghiệm cấu hình và triển khai ứng dụng trên nền tảng máy chủ Tomcat 7.0+\n- Kinh nghiệm tốt với hệ quản trị dữ liệu quan hệ (RDBMS MySQL, PostgreSQL) và kỹ thuật ORM (JPA2, Hibernate).\n- Có kinh nghiệm trong phát triển Angular 12+ hoặc ReactJS 15+\n- Có kinh nghiệm thiết kế giao diện frontend sử dụng HMTL5, JSP, CSS, JavaScript, jQuery và Ajax.\n- Có kiến thức về XML Suite of Technologies XML (XSL) và REST/JSON.\n- Có khả năng thiết kế, viết Stored procedure, Function, tunning database với MySQL\n- Kinh nghiệm với các công cụ xây dựng và triển khai bao gồm Maven, logging và debugging bằng Log4j, Unit và Integration test sử dụng JUnit.\n- Có kiến thức về phát triển ứng dụng sử dụng Software Development Life Cycle SDLC bằng cách sử dụng các phương pháp khác nhau như Agile/Scrum\n- Có khả năng phân tích tốt, lập kế hoạch chiến lược tốt và kỹ năng giao tiếp. Có động lực cao, nhiệt tình và tự tạo cảm hứng.\n- Có kinh nghiệm với Angular Progressive Web App (PWA)\n- Có kinh nghiệm với Angular Mobile App with Ionic, Capacitor hoặc React Native\n- Có kinh nghiệm lập trình Asp .NET Core\n- Có kinh nghiệm với Oracle, MS SQL Server\n4. Năng lực cốt lõi\n- Có tố chất và tư duy phù hợp với hệ giá trị cốt lõi của công ty (IPAM & 4C)\n\nQuyền lợi\n1. Cộng đồng những người làm nghề chính trực và dấn thân phụng sự\n- Môi trường làm nghề tài chính chuyên nghiệp.\n- Làm việc với tinh thần làm chủ, sáng tạo và thách thức.\n2. Tổng thu nhập theo năng lực\n- Thu nhập xứng đáng theo năng lực và giá trị đóng góp.\n- Xem xét thay đổi thu nhập hàng năm.\n3. Chế độ đãi ngộ\n- Tham gia BHXH, BHYT, BHTN theo đúng quy định luật lao động.\n- Được tham gia đóng bảo hiểm sức khỏe và bảo hiểm tai nạn 24/24.\n4. Tổ chức học tập và văn hóa sôi nổi\n- Không gian làm việc mở với trang thiết bị hiện đại.\n- Các hoạt động văn hóa, gắn kết đội ngũ, thiện nguyện phong phú, ý nghĩa.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3279, 1142, 2, 'Middle/Senior C/C++ Developer', 'Mô tả công việc:\n- Developing new functions.\n- Maintaining existing functions of semiconductor manufacturing processing systems.\n- Control robotic arms, sensors, grinder, wafer, … in chip manufacturing machines.\n- Host software project team daily/weekly/monthly project meeting;\n- Ensure software delivery on time and quality according to customer requirement.\n- Maintain good communication with cross-function teams to ensure all software development activity meet project strategy.\n- Make reports and communicate with Operation Manager.\n\nYêu cầu ứng viên:\n- Minimum of 3 years of professional experience in C++ development.\n- Language: C++, Modern C++11/14/17, Singleton/Prototype/Factory/Design pattern.\n- Good basic knowledge, good logical thinking.\n- Related skills: HTTP, Websocket, Restful APIs, etherCat.\n- OS: Windows 10/Windows 11, Linux/Debian/Ubuntu.\n- Have skills in manipulating and managing Package Format and using linux command.\n- IDE: Visual Studio 2019/Vscode.\n- Framework: MFC, Boost.\n- Database: Postgres/sqlite.\n- SOFT SKILLS: \n- Experience working directly with English/Japanese speaking customers.\n- Reporting skills: Ability to convey information in an easy-to-understand and accurate way, while listening to feedback from others.\n- Teamwork ability: Ability to work in a multi-employee, multi-project environment and share information effectively.\n- Problem solving skills.\n- Progressive spirit: Always looking for ways to improve and learn new skills.\n- Sense of responsibility: Ensure work is completed on time and ensure product quality.\n\nQuyền lợi:\n- Working in a dynamic and professional environment with many opportunities for advancement.\n- The company provides equipment such as LAPTOP, Phones to serve the working needs of all employees.\n- The company pays all costs of social insurance, health insurance, and unemployment insurance for employees.\n- Join Health and Accident Insurance package 24/7 (according to seniority). Enjoy benefits according to seniority.\n- Being trained in foreign languages, and sponsored to study certificates to improve professional skills and soft skills.\n- Opportunity to go Onsite at SPLUS JAPAN (requires Japanese level of N3 or higher).\n- Performance evaluation: 2 times/year.\n- Clubs: Football, Music, …\n- Annual company trip, quarterly teambuilding, employee birthdays in the month, and special events of the year (8/3, 20/10, Mid-Autumn Festival, Christmas…).\n- Annual leave: 12 vacation days, 11 holidays a year.\n- Company trip, quarterly teambuilding, birthdays for employees in the month and special events of the year (March 8, October 20, Mid-Autumn Festival, Christmas …).\n- TET bonus fund (1-3 months’ salary) according to the results of the work and the business situation of the company.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: Tòa nhà HaDo Airport, 2 Hồng Hà, phường 2, Tân Bình.\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3280, 1350, 2, 'Senior Backend Developer', 'Mô tả công việc\n1. Backend Development & Microservices\n- Design, develop, and optimize high-performance REST/GraphQL APIs and microservices.\n- Build backend services using NodeJS (MERN Stack) and Golang (Nice to have).\n- Enhance system performance and scalability.\n\n2. Technology & Architecture\n- Work with distributed systems and microservices architecture.\n- Deploy applications on cloud platforms.\n- Integrate AI/ML solutions into the system.\n- Proficient in containerization using Docker and Kubernetes.\n\n3. DevOps & CI/CD\n- Develop and maintain CI/CD pipelines using GitLab.\n- Apply best practices in DevOps.\n- Monitor and optimize the development workflow.\n\nYêu cầu ứng viên\n1. Technical Experience\n- At least 5+ years of experience in backend development with NodeJS (MERN Stack) and Golang.\n- Strong experience in designing RESTful APIs and microservices.\n- Proficiency in working with PostgreSQL, MongoDB, and Redis.\n- Experience in database design for large-scale systems.\n\n2. Technical Skills\n- In-depth understanding of distributed systems and microservices architecture.\n- Proficiency in Docker, Kubernetes, and cloud platforms (AWS, GCP).\n- Strong knowledge of data structures and algorithms.\n- Proficient in Git and source code management tools.\n- Ability to apply AI in enhancing development speed and quality.\n\n3. Soft Skills\n- Strong analytical and problem-solving skills.\n- Effective teamwork and collaboration.\n- Proactive in learning new technologies.\n- High sense of responsibility and passion for software development.\n\nQuyền lợi\n- Competitive salary commensurate with experience.\n- Flexible working hours to support work-life balance and productivity.\n- Opportunity to work in a dynamic startup environment with a passionate and talented team.\n- Chance to make a significant impact on the growth and success of innovative products in the D2C industry.\n- Collaborative culture that values creativity, diversity, and continuous learning.\n- Career growth and skill development opportunities.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 24 Huỳnh Khương Ninh, Đa Kao, Quận 1\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3281, 1442, 2, 'Lập Trình Viên VueJS', '• Tham gia phát triển phần mềm cho các Tập đoàn khách sạn, resort hàng đầu tại Nhật Bản.\n• Teamwork, họp bàn, phát triển sản phẩm cùng với đội ngũ phía Nhật Bản.\n• Maintain code hiện tại và phát triển các chức năng mới.\n• Báo cáo công việc với cấp trên.\n\nYêu cầu ứng viên:\n• Từ một năm kinh nghiệm lập trình VueJs/Angular\n• Thuần thục CSS/SCSS, HTML, Javascript, TypeScript\n• Có kinh nghiệm về UX, UI, State Management, Functional Programming là một lợi thế.\n• Có kinh nghiệm làm việc với Web Application, API, DataBase.\n• Hiểu rõ authentication, RESTful API, Git, Virtual Machine và quy trình phát triển phần mềm\n• Có kiến thức cơ bản, kinh nghiệm về các dịch vụ AWS, Microservices, Docker, Kubernetes và cơ sở hạ tầng đám mây (Cloud Infrastructure)\n\nQuyền lợi:\n- Thời gian làm việc: Từ thứ 2 đến thứ 6, nghỉ Thứ 7 & Chủ Nhật. Đặc biệt bạn có thể tự chủ động giờ bắt đầu làm việc (đến trước 9h sáng), đến sớm về sớm. Miễn đảm bảo đủ 8 tiếng/ngày và tiến độ dự án.\n- Kết hợp linh hoạt giữa làm tại văn phòng và remote\n- Mức lương cạnh tranh (tùy theo kỹ năng và kinh nghiệm)\n- Review tăng lương hàng năm\n- Thưởng Tết, quà sinh nhật, Trung thu, 30/4, 2/9, 8/3, 20/10...\n- Trợ cấp ăn trưa, cung cấp cung cấp trà, cà phê, trợ cấp đi lại, trợ cấp ngoại ngữ v.v..\n- Thanh toán OT theo quy định của luật lao động\n- Có cơ hội đi onsite tại Tokyo hoặc Okinawa ngắn và dài hạn\n- Bảo hiểm full lương\n- Ngày phép: 12 ngày/năm và tăng dần theo thời gian làm việc\n- Du lịch công ty hàng năm\n- Khám sức khỏe định kỳ 01 lần/năm tại BV Quốc tế\n- Hoạt động giải trí và Team Building phong phú (Câu lạc bộ bóng đá, chạy bộ, đạp xe, PES...)', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3282, 1446, 2, 'Lập Trình Viên C#, .NET', 'Mô tả công việc:\n- Lập trình, tùy biến phần mềm\n- Tham gia phân tích và phát triển hệ thống ERP\n- Tư duy logic tốt, biết định hướng khách hàng, định hướng kết quả, cẩn thận và tỉ mỉ trong công việc\n\nYêu cầu ứng viên:\n- Kỹ năng tư duy logic và thuật toán tốt.\n- Yêu thích lập trình, có khả tự giải quyết vấn đề và tìm hiểu kiến thức.\n- Ưu tiên hiểu biết khái niệm căn bản về lập trình\n- Chịu được áp lực trong công việc và tinh thần trách nhiệm cao.\n\nQuyền lợi:\n- Được công ty đào tạo miễn phí trong khoảng thời gian 3 đến 6 tháng.\n- Lương thỏa thuận.\n- Thưởng tháng lương 13, các dịp lễ.\n- Hộ trợ tiền ăn trưa: 55,000 VND/ngày.\n- Trợ cấp sinh nhật: 1.000.0000 vnđ\n- Hỗ trợ tiền khám chữa bệnh\n- Hỗ trợ nuôi con nhỏ: 50USD/ tháng.\n- Trợ cấp đi dự án 150$ / tháng\n- Chế độ BHXH theo quy định của pháp luật.\n\nĐịa điểm làm việc:\n- Đà Nẵng\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Đà Nẵng', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3283, 1441, 2, 'Lập Trình Viên Mobile', 'Mô tả công việc\n- Xây dựng các giải pháp ứng dụng mobile với nền tảng Flutter, đảm bảo hiệu suất cao và trải nghiệm người dùng tối ưu\n- Nghiên cứu các dự án theo định hướng phát triển của công ty.\n- Đảm bảo chất lượng mã nguồn, thực hiện code review và hướng dẫn đội ngũ\n- Theo dõi và báo cáo tiến độ của dự án đối với các bên liên quan, đưa ra biện pháp khi có rủi ro hoặc thay đổi không mong muốn.\n- Theo dõi xu hướng công nghệ mới và đề xuất cách tích hợp chúng vào dự án.\n- Lập kế hoạch phát triển sản phẩm và báo cáo tiến độ cho ban lãnh đạo\n- Thực hiện các công việc khác theo chỉ đạo của Ban Giám đốc.\n\nYêu cầu ứng viên\n- Trình độ học vấn: Đại học trở lên.\n- Trình độ chuyên môn: CNTT, Lập trình hoặc ngành nghề tương đương.\n- Chuyên sâu về công nghệ Flutter và Dart\n- Thành thạo các ngôn ngữ lập trình: Dart, Java/Kotlin (Android), Swift (iOS)\n- Kinh nghiệm: Có ít nhất 03 năm kinh nghiệm tại vị trí tương đương. Kinh nghiệm làm việc với các nền tảng phát triển ứng dụng di động.\n- Hiểu biết sâu về kiến trúc ứng dụng, design pattern\n- Kỹ năng giao tiếp tốt, nhạy bén, phân tích, đánh giá, có kỹ năng thuyết phục và kỹ năng đàm phán, giải quyết xung đột tốt.\n\nQuyền lợi\n- Mức lương thỏa thuận theo năng lực\n- Lương tháng 13 + Thưởng KPI\n- Chính sách hiếu hỉ\n- Kiểm tra sức khỏe thường niên\n- Team building / du lịch hàng năm\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Số 2A Đường số 5, An Phú, Thủ Đức.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:30 đến 16:45).\n- Thứ 7 (từ 09:00 đến 12:00).\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3284, 1124, 2, 'Java Developer', 'Mô tả công việc:\n- Designing, developing, and maintaining Java applications\n- Performing technical analysis to identify solutions and creating technical documentation\n- Developing functionalities for applications/systems\n- Writing APIs, Unit Tests, and optimizing performance for APIs and databases\n- Participating in database design to meet customer requirements\n- Designing high-level and low-level solutions for products\n- Participating in project supervision to ensure technical quality and coding standards\n- Being responsible for mentoring team members on coding and technology, and guiding the development of features based on design and architecture documentation\n- Exploring core technologies and company technologies\n- Researching and exploring new technologies such as K8S, Microservices, Cloud Native,…\n\nYêu cầu ứng viên:\n- A minimum of 3 years of experience in software development, with a strong preference for candidates with a background in Finance, Banking, or Insurance sectors\n- Being proficient in object-oriented programming with Java, RESTful API, WebSocket, and Microservice\n- Possessing a solid understanding of the software development process (preferring candidates with experience in Scrum/Agile/Kanban)\n- Demonstrating strong knowledge of OOP, OOA/D, and design patterns such as GoF, Dependency Injection, IoC, SOLID, etc\n- Having experience in multi-threading, synchronous, and asynchronous processing\n- Being capable of conducting in-depth research and problem-solving\n- Possessing good knowledge of databases (RDBMS, NoSQL), ORM, and persistence frameworks\n- Being capable of performing code review, code standardization, and ensuring adherence to coding conventions\n- Having experience working with Microservices architecture, Layered architecture, SOA, and Distributed Systems\n- Having experience with Docker, Docker Swarm, and Kubernetes is an advantage\n- Having experience with streaming/messaging frameworks like MQTT, RabbitMQ, and Kafka is a plus\n\nQuyền lợi:\n- Attractive salary, suitable for working capacity\n- Review performance twice a year ( In working process, Candidate can be reviewed continuously before the term if the job is successfully completed)\n- Devices provided (Laptop, PC, mouse, monitor…)\n- Working hours: HN, Vinh: 8:30 - 17:30, HCM: 9:00 - 18:00, 5 days/ week\n- Enjoying good remuneration of company when becoming an employee: social insurance, PTI insurance, annual company trip,…\n- Recognition and rewards based on your performance\n- High promotion opportunity\n- Good career path development\n- Creative, modern and open working place\n- Continuous and professional training to fully develop your potential\n\nĐịa điểm làm việc:\n- Hà Nội: Đống Đa\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3285, 1168, 2, 'Nhân Viên Điện Tự Động Hóa', 'Mô tả công việc:\n- Chịu trách nhiệm phát triển các dự án tự động hóa trong dây chuyền sản xuất.\n- Thiết kế và chuẩn bị dụng cụ, khuôn mẫu, đồ gá và thiết bị bán tự động phục vụ sản xuất.\n- Quản lý và xử lý các tài liệu, hồ sơ liên quan đến kỹ thuật.\n\nYêu cầu ứng viên:\n- Tốt nghiệp cao đẳng trở lên chuyên ngành kỹ thuật hoặc công nghệ, ưu tiên ngành điện hoặc điện tử.\n- Tối thiểu 2 năm kinh nghiệm trong vai trò kỹ sư bảo trì, phát triển máy móc tự động.\n- Giao tiếp tiếng Anh cơ bản.\n- Hiểu biết sâu về các thiết bị tự động hóa như PLC, Servo, bộ điều khiển, cảm biến, robot và linh kiện điện.\n- Ưu tiên ứng viên có kinh nghiệm:\n  - Tham gia lắp ráp máy móc tự động\n  - Xử lý lỗi hệ thống tự động\n  - Lập trình và vận hành PLC (đặc biệt là Mitsubishi, Omron, Keyence)\n  - Có kinh nghiệm triển khai các hệ thống phục vụ Công nghiệp 4.0 – IOT.\n  - Có kinh nghiệm thiết kế, phát triển đồ gá/khuôn/dụng cụ bán tự động cho dây chuyền sản xuất.\n  - Có kỹ năng quản lý, giám sát tiến độ phát triển dự án kỹ thuật mới.\n  - Kỹ năng giải quyết vấn đề,\n  - Kỹ năng làm việc nhóm,\n  - Kỹ năng giao tiếp hiệu quả.\n\nQuyền lợi:\n- Miễn phí ăn ca tại nhà máy.\n- Miễn phí bảo hiểm sức khỏe và bảo hiểm rủi ro 24/7.\n- Được hỗ trợ tiền đóng BHXH, BHYT, BHTN trong 2 tháng thử việc trả trực tiếp vào lương.\n- Miễn phí khám sức khỏe đầu vào, được khám sức khỏe định kỳ hàng năm.\n- Có xe đưa đón nhân viên từ Hà Nội và TP Hòa Bình.\n- Môi trường làm việc hoà đồng, được đào tạo nâng cao kỹ năng, chuyên môn nghiệp vụ.\n- Sau thử việc được tham gia BHXH, BHYT, BHTN theo qui định.\n- Cơ hội thăng tiến nhanh.\n- Thưởng tháng 13, xem xét tăng lương hàng năm.\n- 14 ngày phép/năm.\n- Hưởng 100% lương khi thử việc.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hoà Bình, Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3286, 227, 2, 'Senior Frontend Engineer (React/NextJS), StoreFront ECommerce Platform', 'ABOUT THE ROLE\nJoin our Technology Innovations Center of Excellence (CoE) at Crossian, a fast-growing startup that achieved a milestone of $100M in 2024. In this dynamic role, you\'ll check in daily with your team to stay aligned on project goals and collaborate across our ecosystem with an Agile mindset infused with a unicorn-worthy startup culture.\n\nWe are building a cutting-edge Global eCommerce Platform, offering end-to-end solutions for:\n\nStorefront: Designing customizable and scalable online store systems that provide seamless shopping experiences and support dynamic business growth.\nAds Manager: Integrating and optimizing advertising tools across platforms like Facebook, Google and more, enabling businesses to launch, track, and analyze marketing campaigns efficiently.\nMarketing Insights & CRM: Turning raw data from marketing campaigns, transactions, and user behavior into actionable insights to enhance customer engagement and drive smarter decision-making.\n\nWHAT YOU WILL DO\nFrontend Development & Optimization\nDesign, develop, and implement user-facing features using ReactJS and NextJS.\nOptimize web applications for performance, scalability, and cross-browser compatibility.\nLead the implementation of Server-Side Rendering (SSR) and Client-Side Rendering (CSR) for complex features.\nEnsure clean, maintainable, and scalable code through adherence to industry standards and peer code reviews.\nDebug and resolve performance bottlenecks using tools like Sentry, Kong logs, and Cloudflare.\nTranslate wireframes and prototypes into high-quality, responsive, and accessible code.\nCollaborate with UI/UX designers to deliver user-centric and consistent experiences.\nSystem Integration & Maintenance\nWork closely with backend teams to integrate APIs seamlessly into the frontend.\nParticipate in deployment processes and ensure system stability through efficient debugging and issue resolution.\nCross-Functional Collaboration\nCollaborate with stakeholders to analyze requirements and break them into actionable technical tasks.\nWork with cross-functional teams (backend, QA, DevOps) to ensure the successful delivery of projects.\nKnowledge Sharing & Continuous Improvement\nShare knowledge with team members and provide guidance on frontend best practices.\nProactively suggest improvements to workflows, tools, and code quality to enhance team productivity and product quality.\n\nWHAT WE ARE LOOKING FOR\nEducation: Bachelor’s degree in Information Technology, Computer Science, or related fields.\nExperience\n3-6 years of experience in frontend development with strong expertise in ReactJS, NextJS, and modern JavaScript.\nProficient in state management tools like Redux, Recoil, or similar libraries.\nHands-on experience in building responsive, cross-browser-compatible, and accessible web applications.\nHands-on experience with Node.js to develop APIs and optimize SSR logic.\nFamiliarity with modern frontend tools and workflows (e.g., Webpack, Vite, Git).\nBasic understanding of AWS S3, Cloudflare, or similar tools for asset delivery.\nCapable of translating business requirements into technical solutions.\nEnglish proficiency.\nSoft Skills:\nStrong problem-solving skills.\nFamiliarity with Agile/Scrum.\nPreferred Skills (but not required):\nHas knowledge of design, and coding principles (e.g.: clean code, DRY/KISS, SOLID)\nHas knowledge of Postgres, KAFKA, Elasticsearch, S3/Minio.\nKnowledge of testing frameworks like Jest, React Testing Library.\nFamiliarity with CI/CD pipelines for frontend applications.\nExperience with eCommerce platforms is a plus.\n\nWHAT YOU CAN EXPECT\nWe’re not just about building platforms; we’re about creating a workplace where talent thrives. Here\'s what you’ll gain:\nExceptional Total Compensation Package\nUp to 30 months of salary per year through competitive salary packages and performance-based bonuses.\nTotal annual compensation $55,000, reflecting your expertise and contribution.\nFull salary during probation & Guaranteed 13th month salary.\n12 days work-from-home & 12 days of paid annual leave, plus seniority paid leave.\nGlobal health insurance package for yourself and direct family members, plus annual health checkup.\nGrowth Opportunities\nHands-on exposure to cutting-edge technologies and complex system architecture in a global-scale project.\nClear career advancement pathways and access to continuous professional development programs.\nGlobal Vision\nContribute to projects that redefine how brands connect with consumers globally.\nOpportunity to work on challenging problems in data analytics, customer engagement, and operational efficiency.\nIn addition to development tasks, you’ll collaborate closely with other CoEs to understand their unique challenges. With your technical expertise, you’ll continuously propose innovative solutions to elevate their performance and contribute to the overall success of the organization.\n\nĐịa điểm làm việc\nHà Nội: 65 Ngô Thì Nhậm, Hai Bà Trưng.\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3287, 1158, 2, 'Software Engineer - Data Engineering', 'Mô tả công việc\n- Develop and maintain database scripts, functions, stored procedures to support application development.\n- Assist Developers/Testers with database activities.\n- Process the client’s requests, feedback and fix the bugs.\n- Tune SQL queries and troubleshoot performance issues.\n- Attend all regular meetings of the assigned project.\n\nYêu cầu ứng viên\n- Has 1+ years of experience.\n- Good at English speaking/writing skills; can confidently discuss with clients about technical approaches or issues in detail;\n- Familiar with at least one of well-known RDBMS such as SQL Server, Oracle, PostgreSQL, MySQL\n- SQL Development – ability to write and troubleshoot SQL Code and design (stored procedures, functions, tables, views, triggers, indexes, constraints)\n- Knowledge of ETL, Data migration process\n- Ability to work independently with good self-motivation and minimal supervision.\n- Can handle the communication related to the work assignments.\n- Other nice-to-have skills: Knowledge of Data warehouse/Business Intelligence concept\n\nQuyền lợi\n- Performance bonus\n- Hybrid Working Model\n- Social – Health – Insurance paid fully\n- Healthcare: Annual health check-up, Premium Health Insurance\n- Annual leaves: 14 days\n- Clubs program: Football, Badminton, Swimming, Tennis, Rock, Yoga...\n- Training courses: Technical skills – Soft skills – English\n\nĐịa điểm làm việc\n- Hà Nội: HiTC Building, 239 Xuân Thủy, Cầu Giấy\n- Hồ Chí Minh: Etown Tower, 364 Cong Hoa Street, Ward 13, Tân Bình\n- Đà Nẵng: 36 Tran Quoc Toan Street, Hải Châu\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội & 2 nơi khác', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3288, 1270, 2, 'Odoo Developer', 'Mô tả công việc\n- Lập trình viên Python trên nền tảng Odoo\n- Tham gia phát triển, bảo trì, triển khai phần mềm quản trị doanh nghiệp cung cấp cho khách hàng vừa và nhỏ\n- Dựa trên nền tảng Odoo phát triển các công cụ quản trị cho doanh nghiệp như: Quản lý kho, quản lý sản xuất, quản lý nhân sự, quản lý dự án, quản lý khách hàng (CRM), thương mại điện tử,...\n- Phối hợp với thành viên nhóm dự án, nhóm BA, kiểm thử và khách hàng triển khai dự án\n- Xây dựng kế hoạch công việc, báo cáo, đánh giá công việc của cá nhân, đóng góp các sáng kiến nâng cao chất lượng, năng suất công việc\n\nYêu cầu ứng viên\n- Có từ 2 năm kinh nghiệm Developer và tiếp xúc/làm việc với Odoo/OpenERP\n- Có khả năng làm việc với phần mềm quản lý mã nguồn (VD: Github, Gitlab,...)\n- Có kiến thức và kỹ năng lập trình database; ưu tiên thành thạo PostgreSQL\n- Ưu tiên ứng viên có khả năng làm việc với Linux\n\nQuyền lợi\n- Mức lương cạnh tranh thị trường, theo năng lực;\n- Phụ cấp ăn trưa;\n- Cơ hội thăng tiến cao;\n- Môi trường làm việc năng động,trẻ trung, bứt phá;\n- Xét tăng lươnghàng năm;\n- Chế độ sinh nhật, cưới hỏi, ốm đau, ...;\n- Thưởng tháng- quý, thưởng nóng, thưởngdự án, thưởng Lễ/Tết, thángLương thứ 13 ...;\n- Chế độ du lịch hàng năm;\n- Chế độ mua hàng ưu đãi cho CBNV, miễn phí khu vui chơi cho con em CBNV;\n- Được tham gia các khóa đào tạo nội bộ để nâng cao chuyênmôn;\n- Được tham gia BHYT, BHXH và các chế độ phúc lợi khác theo quy định của nhà sách\n\nĐịa điểm làm việc\n- Hà Nội: Số 424 Nguyễn Trãi, Thanh Xuân\n\nThời gian làm việc\nThứ 2 - Thứ 6: 8h - 17h\nThứ 7: 8h - 12h\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3289, 1291, 2, 'Middle Mobile Developer (Lập Trình Viên Mobile) - Thu Nhập Lên Đến 25 Triệu/Tháng', 'Làm việc với các công nghệ hiện đại, tham gia vào các dự án phát triển hệ thống quy mô lớn, ứng dụng công nghệ AI và kiến trúc Microservice.\n1. Mô tả công việc:\n· Phát triển và bảo trì các ứng dụng di động sử dụng React Native.\n· Tham gia xây dựng các API backend bằng Java Spring Boot và Python khi cần thiết.\n· Làm việc với kiến trúc hệ thống Microservice, triển khai bằng Docker Swarm, tích hợp với Nginx, Cloud Config, và Cloud Gateway.\n· Tích hợp các module AI, OCR, và các tác tử thông minh (AI Agent) vào ứng dụng.\n· Thiết kế, tối ưu hóa truy vấn và xử lý dữ liệu từ các hệ quản trị cơ sở dữ liệu: MS SQL, Oracle, MongoDB, MariaDB, MySQL, Elasticsearch, Redis.\n· Phối hợp với các thành viên trong nhóm phát triển, tester, và quản lý dự án để đảm bảo chất lượng và tiến độ dự án.\nYêu cầu ứng viên:\n· Từ 2-4 năm kinh nghiệm phát triển ứng dụng di động bằng React Native.\n· Có kinh nghiệm làm việc với ít nhất một trong các ngôn ngữ backend: Java Spring Boot, Python.\n· Có hiểu biết hoặc kinh nghiệm triển khai hệ thống theo mô hình Microservice.\n· Ưu tiên ứng viên có kinh nghiệm làm việc với Docker Swarm, Cloud Config, Cloud Gateway.\n· Khả năng làm việc độc lập, chủ động, có tư duy logic tốt và tinh thần học hỏi.\n· Ưu tiên ứng viên tốt nghiệp các trường: Đại học Bách Khoa, Đại học Khoa Học Tự Nhiên, Học Viện Bưu Chính Viễn Thông hoặc các trường kỹ thuật uy tín khác.\nQuyền lợi:\n· Mức lương cạnh tranh, xét tăng lương định kỳ.\n· Môi trường làm việc chuyên nghiệp, năng động, nhiều cơ hội học hỏi và phát triển.\n· Tham gia các dự án thực tế, được tiếp cận công nghệ hiện đại, AI, kiến trúc Microservice.\n· Chế độ BHXH, BHYT đầy đủ, nghỉ phép năm, lương tháng 13, thưởng sản xuất kinh doanh, khám sức khỏe định kỳ, team building....\nĐịa điểm làm việc:\n- Hà Nội: Cầu Giấy\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3290, 1119, 2, 'Mobile App (Flutter)', '- Tham gia vào quá trình phát triển ứng dụng di động sử dụng Flutter framework\n- Thiết kế và triển khai giao diện người dùng ứng dụng dựa trên yêu cầu từ đội thiết kế UI/UX\n- Tối ưu hóa hiệu suất và đảm bảo sự tương thích đa nền tảng\n- Đảm bảo chất lượng mã nguồn trong quá trình phát triển.\n- Sử dụng công cụ test để đảm bảo chất lượng code\n- Làm việc chặt chẽ với các thành viên khác trong nhóm phát triển, bao gồm thiết kế UI/UX, quản lý dự án và nhóm phát triển backend\n- Nghiên cứu và ứng dụng công nghệ mới\n- Quản lý tiến độ và báo cáo hàng ngày\n- Thực hiện các nhiệm vụ được các cấp quản lý giao cho', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3291, 244, 2, 'Software Developer (E-Commerce & AI Integration) - 2 EXP', '1. Thiết kế và xây dựng hệ thống sàn thương mại điện tử\n2. Phát triển hệ thống Affiliate (tiếp thị liên kết)\n3. Tích hợp AI:\n- Gợi ý sản phẩm (recommender system)\n- Chatbot hỗ trợ khách hàng\n- Phân tích hành vi người dùng\n- Tự động tối ưu hóa quảng cáo/sản phẩm\n4. Vận hành và bảo trì hệ thống:\n- Quản lý cơ sở dữ liệu\n- Giám sát hiệu suất, bảo mật\n- Tối ưu trải nghiệm người dùng\n\nYêu cầu ứng viên:\n- Thành thạo ngôn ngữ lập trình Web (JavaScript/TypeScript, Python, PHP,...)\n- Hiểu kiến trúc hệ thống thương mại điện tử\n- Có kinh nghiệm với các mô hình Affiliate\n- Biết sử dụng hoặc tích hợp AI (OpenAI API, TensorFlow, hoặc thư viện ML cơ bản)\n- Hiểu về bảo mật, phân quyền người dùng\n- Có kinh nghiệm tích hợp cổng thanh toán.\n- Làm việc tại khu vực Quận 3.\n\nQuyền lợi:\n- Lương có kinh nghiệm từ 2 năm trở lên Junior / Fresher+ ( 12-20 Triệu )/ Lương thỏa thuận cho những trường hợp có kinh nghiệm đặc biệt.\n- Thù lao và phụ cấp theo chính sách chung của công ty.\n- Thù lao đặc thù theo tiến độ công việc.\n- Thưởng lễ, Tết, tháng lương thứ 13 đầy đủ.\n- Đóng bảo hiểm và các chế độ theo luật lao động sau khi ký hợp đồng chính thức.\n- Nghỉ lễ, Tết theo quy định.\n- Môi trường làm việc chuyên nghiệp, có khả năng định tâm, phát triển bản thân.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 213 Điện Biên Phủ, Phường Võ Thị Sáu, Quận 3\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3292, 1271, 2, 'Senior Java Developer', 'Mô tả công việc: Tham gia phát triển các dự án mảng Tài chính số (Viettel Pay, ví cá nhân, ví doanh nghiệp, ...). Cung cấp sản phẩm ứng dụng thanh toán và chuyển tiền với số lượng giao dịch rất lớn, đòi hỏi hiệu năng xử lý cao. Tham gia làm rõ nghiệp vụ, thiết kế giải pháp, phát triển nâng cấp hệ thống theo yêu cầu. Tham gia review thiết kế, review code, tối ưu hệ thống đáp ứng lưu lượng truy cập cao. Nghiên cứu áp dụng công nghệ mới nâng cao chất lượng, tối ưu nguồn lực phát triển.\n\nYêu cầu ứng viên: Tốt nghiệp đại học loại Khá trở lên, chuyên ngành Công nghệ thông tin, Kỹ sư phần mềm. Đặc biệt ưu tiên các trường Học viện Công nghệ Bưu chính Viễn thông, Đại học Bách khoa Hà Nội, ... Tiếng Anh tương đương 650+ TOEIC. Ít nhất 05 năm kinh nghiệm phát triển các sản phẩm/dự án xây dựng bằng ngôn ngữ Java. Thành thạo Java Core, các framework Java như EE, Spring, Struts, Hibernate ... và một số design pattern thông dụng. Tư duy về thiết kế hướng đối tượng và nắm vững kiến thức về cấu trúc dữ liệu và giải thuật, lập trình hướng đối tượng ... Thành thạo SQL, PLSQL, có kiến thức về các hệ quản trị cơ sở dữ liệu Oracle/MySQL, noSQL, có khả năng tối ưu CSDL. Ưu tiên có hiểu biết về nghiệp vụ tài chính, có kinh nghiệm về microservices, ham học hỏi tìm tòi sáng tạo cái mới.\n\nQuyền lợi: Thời gian làm việc: 8h00 - 17h30 từ thứ 2 tới thứ 6. Địa điểm làm việc: Làm việc tại tòa nhà văn phòng hạng A cao nhất Thủ đô – Keangnam Landmark 72, Phạm Hùng, Nam Từ Liêm, Hà Nội. Mức lương thu hút và cạnh tranh, ứng viên thỏa thuận khi tham gia phỏng vấn. Chính sách thưởng hấp dẫn: thưởng năm, thưởng ngày lễ Tết, ... theo quy định chung của Tập đoàn Viettel. Đóng BHXH, BHYT, BHTN theo quy định Nhà nước; khám sức khỏe định kỳ hàng năm. Cơ hội tiếp xúc với các dự án lớn, mới mẻ &amp; tham gia xây dựng những sản phẩm lớn và có chỗ đứng trên thị trường Fintech Việt Nam. Cơ hội thăng tiến rõ ràng với nhiều cấp bậc. Cơ hội ứng tuyển thử sức đi học tập và làm việc tại nước ngoài theo các khóa ngắn hạn, dài hạn. Công việc luôn thay đổi, thách thức, không thỏa hiệp với sự lỗi thời. Lãnh đạo trẻ trung, biết lắng nghe và sẵn sàng tạo cơ hội để cá nhân phát triển bản thân. Đồng nghiệp thân thiện và nhiệt tình. Nghỉ dưỡng 3 ngày nguyên lương trong năm, hỗ trợ nghỉ dưỡng lên đến 9 triệu/ người. Tham gia các hoạt động thể thao văn hóa, team building, Ngày hội Sáng tạo, giải bóng đá, Viettel’s Got Talent, event quý, event năm, event ngày nghỉ lễ tết,... Được thư giãn, khơi nguồn sáng tạo với Happy Time mỗi ngày. Thưởng thức bữa trưa được phục vụ ngay tại VDS, được chọn lọc bởi các chuyên gia dinh dưỡng.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3293, 1458, 2, 'Automation & System Developer', 'Mô tả công việc: Chúng tôi đang xây một hệ thống bán hàng tự động – vận hành từ A đến Z mà không cần phụ thuộc vào ads. Để làm được điều đó, bạn sẽ:\n- Thiết kế và triển khai các workflow automation sử dụng n8n self-host\n- Scrape và thu thập dữ liệu trend/ngách từ nhiều nguồn (Google Trends, Redbubble, TikTok…)\n- Kết hợp AI (LLM, image generation, mockup automation…) để tạo nội dung đăng tải đa kênh\n- Phối hợp với team marketing để đẩy sản phẩm ra TikTok, IG, Pinterest, Reddit, v.v.\n- Đo lường hiệu suất nội dung, trigger tái đăng hoặc chạy ads tự động khi đạt ngưỡng\n- Tự động hoá toàn bộ quy trình “phát hiện → thiết kế → đăng → theo dõi → tối ưu”.\n\nYêu cầu ứng viên:\n1. Kỹ năng chuyên môn bắt buộc\n- Thành thạo Python: xử lý request, API, scraping, automation, session/cookie/proxy…\n- Sử dụng thành thạo n8n self-hosted (hoặc tương đương như Airflow, Make)\n- Có kinh nghiệm với Selenium, Requests, Playwright, xử lý anti-bot logic\n- Biết cách tích hợp & gọi API từ các nền tảng như OpenAI, Google Gemini, Stable Diffusion\n- Biết dùng FFMPEG, Flux.1, hoặc tương đương để tạo mockup video chuyên nghiệp\n- Có hiểu biết về REST API, OAuth, webhook, retry logic, xử lý lỗi hệ thống\n\n2. Tư duy & mindset\n- Yêu thích xây hệ thống, tối ưu workflow, thích tự động hóa mọi thứ\n- Chủ động học hỏi, tự test, tự debug, không cần ai nhắc việc\n- Có growth hacker, thích thử – đo – lặp lại – scale\n\nPHÙ HỢP VỚI ỨNG VIÊN:\n- Muốn thấy thứ mình code ra chạy thật, tạo ra tiền thật, trong hệ thống thật\n- Muốn làm việc với đội ngũ yêu automation, yêu AI, yêu công nghệ để apply vào cuộc sống\n- Vui vẻ, cởi mở, thích trao đổi thẳng thắn và làm việc teamwork thực chiến\n\nQuyền lợi:\n- Mức lương cạnh tranh theo năng lực + lộ trình tăng lương rõ ràng\n- Làm việc trực tiếp với founder có tư duy sản phẩm và hệ thống mạnh\n- Có quyền xây dựng hệ thống từ đầu, được công nhận là builder chứ không phải người làm thuê\n- Làm việc trong môi trường đề cao việc học hỏi, đổi mới và ứng dụng AI\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 128 Phan Xích Long, P. 7, Phú Nhuận.\n\nThời gian làm việc:\n- Thời gian làm việc từ 9:00 - 18:00, từ thứ 2 đến thứ 7 (thứ 7 làm việc cách tuần).\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3294, 1184, 2, 'Bridge Software Engineer', '❖ Bridge Software Engineer:\n- Là cầu nối giữa đội phát triển ở Việt Nam và khách hàng Nhật Bản.\n- Phân tích, trao đổi yêu cầu nghiệp vụ và kỹ thuật với khách hàng.\n- Kiểm soát tiến độ, quản lý dự án và báo cáo công việc định kỳ với khách hàng.\n- Kiểm tra chất lượng đầu ra của sản phẩm trước khi bàn giao.\n\n❖ Collaboration and Mentorship:\n- Làm việc chặt chẽ với các đội nhóm đa chức năng, bao gồm product managers, designers, và engineers để đáp ứng các mục tiêu kinh doanh.\n- Cố vấn cho các kỹ sư cấp dưới và thúc đẩy văn hóa học tập, đổi mới trong đội nhóm.\n\n❖ Optimization and Innovation:\n- Giám sát hiệu suất hệ thống, tối ưu hóa để cải thiện khả năng mở rộng và hiệu quả.\n- Theo dõi các xu hướng công nghệ mới và đưa ra các đề xuất cải tiến.\n\nYêu cầu ứng viên:\n- Tốt nghiệp Đại học chuyên ngành Khoa học Máy tính, Kỹ thuật hoặc lĩnh vực liên quan.\n- Ít nhất 5 năm kinh nghiệm phát triển phần mềm, bao gồm ... năm ở vai trò lãnh đạo, ... năm kinh nghiệm ở vị trí BrSE, tập trung vào các nền tảng như SaaS, PaaS hoặc IaaS.\n- Tiếng Nhật (JLPT N2 trở lên), tiếng Anh giao tiếp tốt là lợi thế.\n- Thành thạo cả công nghệ front-end và back-end, bao gồm nhưng không giới hạn ở:\n  1. Front-end: HTML/CSS, JavaScript (React, Angular), CSS preprocessors (Sass, Less)\n  2. Back-end: Java, Golang, Python.\n  3. Databases: SQL (MySQL, PostgreSQL), NoSQL (MongoDB, Redis)\n- Có kinh nghiệm với các nền tảng đám mây (AWS, Azure, Google Cloud) và công cụ CI/CD (Jenkins, Docker).\n- Hiểu biết sâu sắc về các mẫu thiết kế phần mềm, cấu trúc dữ liệu và thuật toán.\n- Quen thuộc với phương pháp Agile/Scrum và các công cụ quản lý dự án (Jira, Trello).\n\nNice to have (ưu tiên):\n- Chứng chỉ về quản lý dự án hoặc công nghệ đám mây (ví dụ: PMP, AWS),\n- Sở hữu chứng chỉ Scrum là một lợi thế.\n- Hiểu biết về văn hóa làm việc của người Nhật; có kinh nghiệm trong môi trường gia công phần mềm hoặc Agile/Scrum.\n- Kỹ năng cố vấn và cộng tác tốt trong đội nhóm\n\nQuyền lợi:\n- Chính sách bảo hiểm xã hội, bảo hiểm y tế theo quy định của Nhà nước. Bảo hiểm sức khỏe PVI sau 01 năm làm việc\n- Môi trường làm việc trẻ trung, năng động, thân thiện.\n- Cơ hội làm việc onsite tại Nhật Bản.\n- Thường xuyên tổ chức các seminar do chính nhân viên công ty thực hiện, tạo điều kiện nghiên cứu, trao đổi, phát triển.\n- Hỗ trợ tiền nhà ở trong bán kính 2km.\n- Hỗ trợ chi phí gửi xe và các tiện ích khác.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 181 Cao Thắng, Phường 12 0, Quận 10\n- Hồ Chí Minh: Vinhome Grand Park, Nguyễn Xiển, Phường Long Thạnh Mỹ, Quận 9\n\nThời gian làm việc:\n- Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)\n\nCách thức ứng tuyển:\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3295, 1275, 2, 'Nhân Viên IT', '1. Manage and maintain the company\'s network systems, servers, computers, and peripheral devices.\n2. Support and administer Odoo software, troubleshoot issues, and optimize its usage.\n3. Install, configure, and troubleshoot hardware, office software, and operating systems.\n4. Ensure system security, perform data backup, and restore data when necessary.\n5. Assist and guide employees in using computers and office software effectively.\n6. Manage printers, cameras, and other office equipment.\n7. Perform other tasks as assigned by superiors.\n\nYêu cầu ứng viên\n1. Graduated from College or University in Information Technology, Computer Networks, or related fields.\n2. At least 2 year of experience in IT hardware; experience in managing Odoo software is a plus.\n3. Proficient in troubleshooting hardware, software issues, and network security.\n4. Able to read and understand technical documents in English and communicate at a basic level.\n5. Male candidates preferred; proactive, responsible, and disciplined.\n6. Strong teamwork and independent working skills; ethical and self-motivated.\n7. Responsible for all IT-related tasks in the company.\n\nQuyền lợi\n1. Opportunity for high development for individuals who are truly capable of working in accordance with the support of the company.\n2. Ensure compliance with the regulations of the State: social insurance, health insurance, 13th month salary.\n\nĐịa điểm làm việc\n- Bình Dương: Lô E2, KCN Đồng An, Bình Hòa, Thuận An\n\nThời gian làm việc\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\nMonday to Friday and alternative Saturday (during 2-month probation, full Saturday is required)\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3296, 186, 2, 'Lập Trình Viên Backend', '• Tham gia vào việc xây dựng và phát triển ứng dụng Backend dựa trên các yêu cầu của công ty.\n• Tham gia vào việc thiết kế hệ thống và triển khai sản phẩm CNTT nội bộ.\n• Tối ưu hiệu năng các ứng dụng trong hệ thống.\n• Phát triển và triển khai API cho các sản phẩm Core.\n• Phối hợp với đội ngũ phát triển Frontend và quản trị dự án để đảm bảo sự liên kết và hiệu suất công việc cao nhất.\n\nYêu cầu ứng viên:\n+ Thành thạo .NET (C#)\n+ Thành thạo SQL\n+ Sử dụng thành thạo công cụ làm việc nhóm Git\n+ Có hiểu biết về CI/CD\n+ Kinh nghiệm từ 5 năm trở lên\n+ Bắt buộc nộp portfolio kèm mã nguồn\n- Khi phỏng vấn:\n+ Có thể kiểm tra viết luận liên quan đến design pattern\n+ Có bài kiểm tra coding trong quá trình phỏng vấn\n- Nhận CV song ngữ Tiếng Anh/ Tiếng Việt\n\nQuyền lợi:\n• Thử việc 1 tháng, hưởng 85% lương thoả thuận. Mức lương cao, có thể thoả thuận theo năng lực của ứng viên\n• 1 năm tăng lương/lần\n• Ngoài Lương cố định hàng tháng, công ty có khoản bonus theo tình hình kinh doanh công ty.\n• Hỗ trợ bữa trưa tại công ty\n• Bảo hiểm xã hội, y tế và các quyền lợi khác theo quy định của pháp luật.\n• Du lịch team building hàng quý, năm (trong và ngoài nước)\n• Môi trường làm việc năng động, chuyên nghiệp và thân thiện.\n• Khám sức khoẻ định kỳ hàng năm, Tiêm phòng HPV, cúm,...\n\nĐịa điểm làm việc:\n- Hà Nội: Vinhomes Gardenia Hàm Nghi, Nam Từ Liêm\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3297, 1425, 2, 'Fullstack Web Developer', 'Mô tả công việc\n- Being part of the VN Software Development department.\n- Design & develop the high quality web-bases applications for warehouse & robot fleet management. It will enable both internal users or external customers to make better use of our robotics warehouse automation solution.\n- Develop and integrate solutions across various modules, including web-based dashboards, database, and robotics simulation.\n- Create, execute, and maintain comprehensive test plans; identify and fix bugs while ensuring the integrity of the existing codebase.\n- Contribute to system-level software design, ensuring scalability, reliability, and performance.\n- Formulate, document, and maintain detailed requirements specifications.\n- Analyze, brainstorm and evaluate applications of newly emerged tools and technology.\n- And perform similar duties as he deems fit for the proper execution of his duties and duties as delegated by the direct manager or the Employer.\n\nYêu cầu ứng viên\n- At least 5 years of experience in both front-end and back-end platforms (NodeJS & ReactJS preferred).\n- Familiar with development and deployment in Google Cloud and Amazon Web Services.\n- Experience in database development using Kafka and Snowflake\n- Experience in messaging systems such as RabbitMQ and/or ZeroMQ\n- (Plus) Hand-on experience with 3D web (threejs) or other 3D simulation engine (Unity, Omniverse)\n- (Plus) Hand-on experience with ROS, Docker & Linux environment\n- Maintain a good coding standard, familiar with Test Driven development. Experience with writing unit tests for NodeJS, ReactJS application\n- Exposure to agile development practices and CI/CD pipelines, experience with project management and collaboration tools like JIRA, Confluence\n- Good teamwork, communication, time management and problem solving skills.\n- Working proficiency and communication skills in verbal and written English, be able to to effectively represent the derived results and technical concepts to the leadership team.\n\nQuyền lợi\n- (Gross) Salary $1800-$3500, Yearly adjustment\n- Social insurance, health/life/disability insurance, annual health check\n- 13th month salary\n- Yearly bonus up to 2 month pay depending on performance review\n- Hybrid working option: 1 work-from-home day per week\n- 14 days of paid vacation\n- Work laptop\n- Company trip and other team benefits.\n\nĐịa điểm làm việc\n- Hồ Chí Minh: Quận 7.\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)\n- Can work from home 1 day/week.\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh, Quận 7', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3298, 1358, 2, 'Backend Developer (AWS)', 'Mô tả công việc\n- Develop and maintain high-performance backend systems and APIs using modern technologies such as serverless architectures, microservices, and containerization.\n- Design and implement server-side logic, database schemas, and integrations with third-party services to support scalable and efficient applications.\n- Deploy, monitor, and optimize backend services on AWS cloud infrastructure, ensuring high availability, performance, and cost-efficiency.\n- Collaborate closely with front-end engineers, DevOps, and product owners to deliver seamless, scalable solutions and align with business goals.\n- Ensure adherence to best practices in coding, security, performance, and scalability, including secure coding practices and data encryption.\n- Participate in technical discussions, code reviews, and agile development activities to foster continuous improvement and knowledge sharing.\n- Troubleshoot and resolve issues in production and development environments promptly and effectively to minimize downtime.\n- Stay current with emerging backend technologies and trends, such as AI integration, edge computing, and new programming languages, to drive innovation.\n\nYêu cầu ứng viên\n- Bachelor\'s degree in Computer Science, Information Technology, or a related field.\n- At least 3 years of experience as a Software Engineer, with a focus on Data Engineering or Cloud Computing.\n- Proficient in programming languages such as Python and Node.js.\n- Hands-on experience with AWS services including but not limited to: Amazon S3, DynamoDB, Lambda, Glue, Kinesis, SQS, Serverless Stack, Cloud Observation Tools, Step Functions, RDS, and Data Lake.\n- Solid understanding of ETL processes and database design.\n- Experience with serverless architecture and managed services to ensure high availability and fault tolerance.\n- Strong knowledge of cloud security best practices, including IAM policies, VPC endpoints, and data encryption.\n- Familiarity with CI/CD pipelines and proficient in Infrastructure as Code (IaC) tools such as AWS CDK or Terraform.\n- Excellent problem-solving skills and attention to detail.\n- Strong communication and collaboration skills.\n- Ability to design and troubleshoot distributed systems.\n- Experience with Customer Data Platforms (CDPs) or similar technologies.\n- AWS certifications (e.g., AWS Certified Solutions Architect, AWS Certified Data Analytics – Specialty).\n\nQuyền lợi\n- Attractive salary, commensurate with capacity.\n- 13th month salary bonus, achievement bonus: 14-15 months, monthly/quarterly/yearly business bonus, Tet holiday bonus.\n- Rice allowance and other allowances (according to the nature of the job).\n- Annual health check-ups.\n- Social insurance; 24/24 accident insurance.\n- Leave regime for employees from 12-14 days/year.\n- Training and career development programs.\n- Professional working environment.\n- Collective activities: Team Building, Family Festival, Arts, Sports Club, Vacation...\n- Community activities: Gifts on the occasion of 8/3, 20/10, International Children\'s Day 1/6, Mid-Autumn Festival.....\n\nĐịa điểm làm việc\n- Hồ Chí Minh: 170E Phan Đăng Lưu, Phú Nhuận\n\nThời gian làm việc\n- Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3299, 1481, 2, 'Lập Trình Wordpress Developer', '• Thiết kế, lập trình và phát triển các website trên nền tảng Wordpress.\n• Tối ưu hóa hiệu suất, bảo mật và SEO cho các trang web Wordpress.\n• Phát triển và tùy chỉnh các plugin và theme theo yêu cầu.\n• Quản lý và bảo trì các trang web hiện tại, đảm bảo hoạt động ổn định và hiệu quả.\n• Quản lý server, hosting và bảo mật hệ thống website của công ty.\n• Tích hợp các giải pháp thanh toán và dịch vụ bên thứ ba vào trang web.\n• Chịu trách nhiệm xây dựng và tối ưu hóa các website vệ tinh thuộc Flexhouse VN.\n• Hợp tác với các bộ phận khác để đảm bảo chất lượng và tiến độ dự án.\n\n• Tốt nghiệp Đại / Cao đẳng chuyên ngành công nghệ thông. Có ít nhất 2 năm kinh nghiệm làm việc với Wordpress, bao gồm thiết kế và phát triển nhiều website.\n• Thành thạo HTML, CSS, JavaScript, PHP và MySQL.\n• Am hiểu về SEO, tối ưu hóa tốc độ trang web và các tiêu chuẩn web.\n• Kinh nghiệm phát triển theme và plugin Wordpress tùy chỉnh.\n• Kỹ năng bảo mật để bảo vệ trang web khỏi các cuộc tấn công.\n• Kinh nghiệm quản lý server và hosting cho các trang web.\n• Kỹ năng giải quyết vấn đề, quản lý thời gian và làm việc độc lập tốt.\n• Kỹ năng giao tiếp tốt với khách hàng và khả năng viết tài liệu kỹ thuật.\n• Am hiểu về thiết kế giao diện và trải nghiệm người dùng (UX/UI).\n• Sử dụng thành thạo các công cụ phát triển như Git và nắm bắt xu hướng công nghệ web mới\n\n• Mức lương từ 15 đến 17 triệu VNĐ/tháng.\n• Thưởng theo hiệu suất công việc, lương tháng 13.\n• Tham gia hoạt động team building, du lịch hàng năm.\n• Tham gia vào các dự án đa dạng, có cơ hội phát triển nghề nghiệp.\n• Môi trường làm việc chuyên nghiệp, thân thiện.\n• Các chế độ phúc lợi khác theo quy định của công ty.\n\nĐịa điểm làm việc:\n- Hồ Chí Minh: 101 Bưng Ông Thoàn, P.Phú Hữu, Thủ Đức\n\nThời gian làm việc:\nThứ 2 - Thứ 7 (từ 08:00 đến 17:00)\n\nCách thức ứng tuyển:\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hồ Chí Minh', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3300, 1479, 2, 'Phần Mềm', 'Mô tả công việc\n1. Phát triển và tích hợp hệ thống fullstack:\n- Thiết kế và phát triển các API backend chất lượng cao, có khả năng mở rộng bằng Python, sử dụng các framework như FastAPI, Django hoặc Flask.\n- Phát triển ứng dụng web đáp ứng (responsive) sử dụng ReactJS và ứng dụng mobile/desktop đa nền tảng sử dụng Flutter.\n- Lập trình firmware cho các hệ thống nhúng trên các vi xử lý ARM, PIC, STM32, đảm bảo tích hợp mượt mà với các hệ thống phần cứng và phần mềm.\n\n2. Tích hợp và tối ưu hóa hệ thống:\n- Tích hợp RESTful APIs, các giao thức giao tiếp (như MQTT) và các module phần mềm giao tiếp với thiết bị ngoại vi (Motor Driver, GPS, IMU).\n- Tối ưu hóa hiệu suất ứng dụng trên cả backend, frontend và firmware, đảm bảo tương thích đa nền tảng và trên nhiều thiết bị.\n- Phân tích và tối ưu các thành phần hệ thống dựa trên yêu cầu sản phẩm.\n\n3. Thiết kế và triển khai giao diện người dùng:\n- Chuyển đổi thiết kế từ Figma thành giao diện chất lượng cao cho cả web và mobile, đảm bảo tính nhất quán với yêu cầu từ đội UI/UX.\n- Đảm bảo chất lượng mã nguồn thông qua viết Unit Test, Function Test và Integration Test.\n\n4. Phát triển và kiểm thử:\n- Thiết kế, triển khai và kiểm thử các module phần mềm/firmware có khả năng tái sử dụng và dễ bảo trì.\n- Phát triển các công cụ và chương trình hỗ trợ kiểm thử hệ thống.\n\n5. Hợp tác liên phòng ban:\n- Phối hợp chặt chẽ với các đội frontend, backend, UI/UX, thiết kế phần cứng, và hệ thống để đảm bảo tích hợp liền mạch giữa các thành phần.\n- Hỗ trợ sau triển khai, sửa lỗi và cải tiến sản phẩm dựa trên phản hồi thực tế.\n\n6. Tài liệu hóa:\n- Viết và bổ sung tài liệu thiết kế, mô tả, và hướng dẫn sử dụng sản phẩm.\n- Thực hiện các công việc chuyên môn khác theo sự phân công của quản lý.\n\nYêu cầu ứng viên\n- Tốt nghiệp đại học các chuyên ngành Điện, Điện tử Viễn thông, Khoa học Máy tính, Công nghệ Thông tin hoặc các ngành liên quan.\n- Tối thiểu 5 năm kinh nghiệm làm việc với Python (sử dụng FastAPI, Django hoặc Flask), ReactJS hoặc Flutter, và lập trình C trên các hệ thống nhúng.\n- Thành thạo thiết kế giao diện người dùng đáp ứng (responsive) và các nguyên tắc lập trình hướng đối tượng (OOP) cùng Design Patterns.\n- Hiểu biết vững chắc về RESTful APIs, các giao thức giao tiếp web (như MQTT) và các chuẩn công nghệ giao tiếp không dây (Bluetooth, NFC là một lợi thế).\n- Kinh nghiệm làm việc với cơ sở dữ liệu SQL và NoSQL (như Cassandra, PostgreSQL).\n- Thành thạo hệ điều hành Linux, Linux driver, và các công cụ Tool Chain cho kiến trúc ARM Cortex-M.\n- Kỹ năng giải quyết vấn đề, tư duy logic và hiểu biết tốt về cấu trúc dữ liệu và giải thuật.\n- Thành thạo sử dụng Git và có kỹ năng làm việc nhóm tốt.\n- Khả năng đọc hiểu tài liệu kỹ thuật bằng tiếng Anh. Kỹ năng giao tiếp tiếng Anh tốt.\n- Giao tiếp với khách hàng, đồng nghiệp tốt.\n\nKỹ năng ưu tiên:\n- Kinh nghiệm hoặc hiểu biết về IoT, hệ thống nhúng, vi điều khiển (STM32, ARM, PIC, AVR), thiết kế phần cứng, sơ đồ mạch, và các công cụ PCB như Altium hoặc OrCAD.\n- Kinh nghiệm tích hợp giữa web, mobile và IoT trong các dự án thực tế.\n- Thành thạo các công cụ tối ưu hóa và kiểm soát hiệu suất ứng dụng.\n- Có kinh nghiệm phát triển các module phần mềm giao tiếp với thiết bị ngoại vi (Motor Driver, GPS, IMU).\n\nQuyền lợi\n- Điều chỉnh lương 1 năm/lần. Có chính sách review lương bổ sung đối với các trường hợp nhân viên có nhiều cố gắng hoặc được đánh giá cao trong công việc.\n- Thưởng Tết, thưởng các dịp Lễ, chế độ phúc lợi khác.\n- Du lịch hàng năm, Teambuilding,…\n- Được đảm bảo đầy đủ các chế độ: BHXH, BHYT, BHTN theo luật lao động quy định, Bảo hiểm sức khỏe Bảo Việt.\n- Nghỉ phép: 12 ngày/năm. Cứ mỗi 5 năm thâm niên được công thêm 1 ngày phép. Được trả lương phép.\n- Thời gian làm việc: 44h/tuần. Từ thứ 2 - thứ 5 (8h-18h), Thứ 6 (8h-17h).\n- Có cơ hội được tham gia các khóa đào tạo nâng cao trình độ chuyên môn trong và ngoài nước.\n- Được tham gia vào các dự án lớn, đa quốc gia.\n\nĐịa điểm làm việc\n- Hà Nội: Số 12 BT1 X2 khu đô thị Bắc Linh Đàm, Hoàng Mai.\n\nThời gian làm việc\n- Thứ 2 - Thứ 5 (từ 08:00 đến 18:00).\n- Thứ 6 (từ 08:00 đến 17:00).\n- Có thể làm việc từ thứ 2 đến sáng thứ 7.\n\nCách thức ứng tuyển\nỨng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3301, 1373, 2, 'Kỹ Sư Lập Trình Đứng Máy Phay CNC', 'Mô tả công việc\n- Lập trình gia công trên phần mềm CAM (Mastercam, NX, Powermill, hoặc phần mềm khác tùy theo yêu cầu).\n- Vận hành, cài đặt, chỉnh sửa chương trình gia công trên máy CNC (phay, tiện).\n- Đọc và hiểu bản vẽ kỹ thuật, bóc tách yêu cầu gia công, lựa chọn dao cụ và phương pháp gia công tối ưu.\n- Kiểm tra, đánh giá chất lượng sản phẩm sau gia công, điều chỉnh chương trình hoặc gá đặt nếu cần.\n- Bảo trì, bảo dưỡng định kỳ máy CNC, đảm bảo máy hoạt động ổn định.\n- Hỗ trợ các bộ phận liên quan trong việc cải tiến quy trình gia công nhằm nâng cao năng suất, chất lượng sản phẩm.\n- Thực hiện các công việc khác theo yêu cầu của cấp trên.\n\nYêu cầu ứng viên\n- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Cơ khí, Chế tạo máy, Cơ điện tử hoặc liên quan.\n- Có kinh nghiệm từ 1-3 năm lập trình, vận hành máy CNC (chấp nhận ứng viên có ít kinh nghiệm nhưng có nền tảng tốt).\n- Thành thạo phần mềm lập trình CAM (Mastercam, NX, Powermill...) và phần mềm thiết kế CAD (SolidWorks, AutoCAD...).\n- Hiểu biết về các loại vật liệu gia công (nhôm, thép, inox, nhựa kỹ thuật…).\n- Kỹ năng đọc bản vẽ kỹ thuật, sử dụng các dụng cụ đo cơ khí chính xác (thước cặp, panme, đồng hồ so…).\n- Có tinh thần trách nhiệm, cẩn thận, chủ động trong công việc.\n- Ưu tiên ứng viên có kinh nghiệm làm việc trong ngành gia công cơ khí chính xác.\n\nQuyền lợi\n- Lương: Thoả thuận theo năng lực, có thưởng theo hiệu suất công việc.\n- Thời gian tăng ca được tính phụ cấp tăng ca, công ty chi trả tiền ăn trưa và ăn ca.\n- Được làm việc trong môi trường chuyên nghiệp, có cơ hội học hỏi và phát triển.\n- Được đào tạo nâng cao kỹ năng lập trình, vận hành máy CNC.\n- Hưởng đầy đủ chế độ theo quy định của công ty và pháp luật: BHXH, BHYT, BHTN.\n- Thưởng các ngày lễ, tết, lương tháng 13.\n\nĐịa điểm làm việc\n- Hà Nội: CN1, Minh Khai, Bắc Từ Liêm, Bắc Từ Liêm\n\nThời gian làm việc\n- Thứ 2 - Thứ 7 (từ 08:00 đến 17:20)\n\nCách thức ứng tuyển\n- Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Requirements and qualifications as described in the job description.', 0.00, 1000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3302, 1484, 182, 'Leader Marketing', 'Chiến lược & Kế hoạch\nNghiên cứu thị trường, xu hướng tiêu dùng và đối thủ ở cả hai mảng bán lẻ và bán sỉ.\nXây dựng chiến lược marketing tổng thể theo năm và kế hoạch chi tiết theo quý/tháng.\nPhân bổ ngân sách marketing hợp lý giữa bán lẻ và bán sỉ, đảm bảo ROI tối ưu.\nQuản lý mảng Bán lẻ\nXây dựng và triển khai các chương trình quảng bá thương hiệu, khuyến mãi, sự kiện tại cửa hàng và online.\nPhát triển hoạt động digital marketing (SEO, SEM, social media, influencer, email marketing…).\nTriển khai CRM & loyalty program nhằm tăng tỷ lệ quay lại và giá trị đơn hàng trung bình.\nĐảm bảo hình ảnh nhận diện thương hiệu thống nhất trên tất cả điểm bán.\nQuản lý mảng Bán sỉ\nXây dựng chiến lược trade marketing và hỗ trợ đội ngũ kinh doanh trong việc tiếp cận khách hàng B2B.\nThiết kế bộ tài liệu bán hàng (catalogue, brochure, profile…) và các công cụ hỗ trợ chào hàng.\nTổ chức hội thảo, triển lãm, chương trình hợp tác đại lý/nhà phân phối.\nPhát triển các kênh truyền thông phù hợp cho khách hàng doanh nghiệp (LinkedIn, hội chợ ngành, email B2B…).\nQuản lý mảng E-commerce\nXây dựng và triển khai chiến lược marketing cho các kênh thương mại điện tử (website, sàn TMĐT, social commerce).\nQuản lý gian hàng trực tuyến, tối ưu sản phẩm, nội dung và hình ảnh.\nThực hiện các chiến dịch quảng cáo, flash sale, voucher, affiliate để tăng doanh số online.\nTheo dõi số liệu bán hàng, tỷ lệ chuyển đổi và hành vi mua sắm để tối ưu trải nghiệm khách hàng.\nQuản lý hình ảnh thương hiệu\nXây dựng, duy trì và phát triển bộ nhận diện thương hiệu cho toàn công ty.\nGiám sát và đảm bảo hình ảnh thương hiệu nhất quán trên tất cả các kênh truyền thông, ấn phẩm và hoạt động marketing.\nTheo dõi, đánh giá cảm nhận thương hiệu trên thị trường và đề xuất giải pháp cải thiện.\nQuản lý & Phát triển đội ngũ nhân sự Marketing\nĐào tạo, huấn luyện và phát triển kỹ năng cho đội ngũ nhân sự phòng Marketing.\nĐánh giá hiệu quả công việc, xây dựng KPIs và kế hoạch phát triển cá nhân.\nTạo động lực, xây dựng văn hóa làm việc tích cực trong đội ngũ.\nQuản lý & Tối ưu hoạt động\nTheo dõi, phân tích và báo cáo hiệu quả các chiến dịch marketing bằng KPI rõ ràng.\nĐiều chỉnh chiến lược dựa trên dữ liệu và phản hồi từ thị trường.\nQuản lý mối quan hệ với nhà cung cấp dịch vụ marketing, media agency, KOL/đối tác chiến lược.', 'Tốt nghiệp đại học chuyên ngành Marketing, Quản trị Kinh doanh, Thương mại hoặc các ngành liên quan.\nTừ 2 năm ở vị trí quản lý marketing, ưu tiên đã làm từng làm bên mảng bán lẻ \nHiểu rõ mô hình vận hành hệ thống bán lẻ (offline & online), hành vi mua sắm của người tiêu dùng.\nCó kinh nghiệm triển khai các chiến dịch Digital Marketing, Trade Marketing, khuyến mãi và chăm sóc khách hàng.\nKỹ năng lãnh đạo, quản lý ngân sách, giao tiếp và phân tích thị trường tốt.\nTư duy chiến lược, chủ động, sáng tạo và thích ứng nhanh với thay đổi.', 10000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3303, 1485, 183, 'Trưởng Phòng Marketing / Brand Marketing Manager', '- Quản lý hệ thống nhận diện thương hiệu (Brand Guideline), đảm bảo sự đồng bộ trên toàn bộ nền tảng: ứng dụng, website, social media, tài liệu đối tác…\n- Lên ý tưởng, viết brief và phối hợp với các team triển khai chiến dịch truyền thông đa kênh (IMC).\n- Phát triển và chuẩn hóa các tài liệu bán hàng: bộ Sale Kit, Proposal mẫu, brochure đầu tư, hồ sơ giới thiệu dịch vụ…\n- Làm việc trực tiếp cùng Content, Digital, Design và Product để đảm bảo xuyên suốt trải nghiệm thương hiệu.\n- Theo dõi, đánh giá hiệu quả thương hiệu qua các chỉ số: độ nhận biết (brand awareness), mức độ quan tâm (brand engagement), lượt tìm kiếm thương hiệu (search volume).\n- Quản lý hoặc hướng dẫn nhóm thực thi nội bộ hoặc agency đối tác.', '- Tốt nghiệp các chuyên ngành Marketing, Truyền thông, Thương mại điện tử,…\n- 3 năm kinh nghiệm thực tế tại vị trí tương đương.\n- Thành thạo Meta Ads, Google Ads, TikTok Ads và các công cụ đo lường (GA, Pixel, Looker Studio,...).\n- Có tư duy logic, khả năng đọc dữ liệu và tối ưu ngân sách hiệu quả.\n- Ưu tiên ứng viên có kinh nghiệm trong ngành mỹ phẩm, tiêu dùng nhanh, bán lẻ.', 15000000.00, 20000000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3304, 1486, 184, 'Nhân Viên Vận Hành Sàn Tmđt (Tiktok Shop)', 'Phụ trách và vận hành sàn TMĐT ( Tiktok Shop , Shope , Facebook ,…) \nAm hiểu và thiết lập hồ sơ tạo kênh TIKTOK SHOP .\nQuảng cáo sản phẩm thông qua các nền tảng xã hội , tiktok , facebook , Instagram …\nCập nhật hình ảnh sản phẩm .\nBiết set up deal , CSKH, triển khai các chương trình do hệ thống các trang TMĐT đề xuất \nTheo dõi đơn hàng , xử lý khiếu nại , cập nhật số liệu tồn kho .\nCông việc phát sinh theo yên cầu BGĐ', 'Nam/Nữ Tuổi từ 22 – 35  tốt nghiệp Cao đẳng trở lên. \nKinh nghiệm ít nhất 01 vị trí tương đương                                                            \nKỹ năng làm việc độc lập , chính xác , trung thực .\nHiểu về sàn TMĐT , nắm bắt được trào lưu hiện nay , về đồ chơi \nNăng động, hoạt bát ,chịu khó', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3305, 1487, 185, 'Thực Tập Sinh / CTV Tư Vấn Truyền Thông (Sinh Viên Năm 3, 4)', 'Tìm kiếm và phát triển khách hàng mới trong lĩnh vực báo chí, truyền hình và tổ chức sự kiện. \nHỗ trợ thực hiện các công việc tư vấn, chăm sóc khách hàng, theo sát quy trình từ tư vấn đến ký hợp đồng. \nHọc hỏi kỹ năng xây dựng mối quan hệ, tư vấn và phát triển khách hàng. \nCập nhật kiến thức về các dịch vụ truyền thông để giới thiệu đến khách hàng. \nTham gia cùng đội nhóm để hoàn thành mục tiêu doanh số và mở rộng thị trường.\nWebsite công ty : gmm.vn', 'Là sinh viên năm 3, năm 4 hoặc năm cuối các ngành: Kinh tế, Marketing, Báo chí, Truyền thông, Quản trị kinh doanh hoặc các ngành liên quan. \nKhông yêu cầu kinh nghiệm, sẽ được đào tạo bài bản – cầm tay chỉ việc. \nCó đam mê và mong muốn phát triển trong lĩnh vực truyền thông, sự kiện, quảng cáo. \nGiao tiếp tốt, tự tin, ham học hỏi, có tinh thần trách nhiệm. \nCó laptop cá nhân để hỗ trợ công việc.', 8000000.00, 15000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(3306, 1488, 186, 'Nhân Viên Văn Phòng', '- Hỗ trợ công việc hành chính – admin (soạn thảo, sắp xếp hồ sơ, xử lý giấy tờ, theo dõi tiến độ công việc).\n- Phối hợp hỗ trợ marketing (đăng bài, chăm sóc fanpage, hỗ trợ chạy chiến dịch cơ bản).\n- Thực hiện các công việc theo yêu cầu trực tiếp từ quản lý.\n- Hỗ trợ công việc hành chính – admin (soạn thảo, sắp xếp hồ sơ, xử lý giấy tờ, theo dõi tiến độ công việc).\n- Phối hợp hỗ trợ marketing (đăng bài, chăm sóc fanpage, hỗ trợ chạy chiến dịch cơ bản)\n- Thực hiện các công việc theo yêu cầu trực tiếp từ quản lý.', '- Tốt nghiệp cao đẳng/đại học (ưu tiên ngành quản trị kinh doanh, marketing, hành chính…).\n- Thành thạo tin học văn phòng.\n- Năng động, chịu khó học hỏi, giao tiếp tốt, có tinh thần trách nhiệm.\n- Tốt nghiệp cao đẳng/đại học (ưu tiên ngành quản trị kinh doanh, marketing, hành chính…)\n- Thành thạo tin học văn phòng\n- Năng động, chịu khó học hỏi, giao tiếp tốt, có tinh thần trách nhiệm', 7000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3307, 1489, 187, 'Nhân Viên Văn Phòng Tổng Hợp Kiêm Marketing', '• Thực hiện các công việc văn phòng tổng hợp. \n• Triển khai Marketing online: viết bài, đăng bài trên các kênh (website, Facebook, Zalo, TikTok…). \n• Làm video, hình ảnh sản phẩm để quảng bá thương hiệu. \n• Tìm kiếm và khai thác khách hàng mới, chăm sóc khách hàng hiện có.\n• Tư vấn khách hàng về quy trình sản xuất khi có khách hàng đến công ty\n• Đi ra ngoài check nguồn vải khi công ty yêu cầu\n• Soạn hàng order , tạo đơn hàng khi có hàng Order về - tạo soạn hợp đồng khi có yêu cầu và các công việc khác liên quan \n• Thực hiện báo cáo và các công việc liên quan', '• Có kinh nghiệm Marketing online (ưu tiên ngành thời trang/thể thao). \n• Biết cơ bản về chỉnh sửa hình ảnh, video. \n• Kỹ năng viết nội dung tốt, sáng tạo. \n• Nhanh nhẹn, chủ động, chịu khó học hỏi.\n• Yêu cầu ứng viên: Có định hướng gắn bó lâu dài với công ty\nĐịa chỉ làm việc: 77/20/4 Võ Thị Thừa, Phường An Phú Đông, TP Hồ Chí Minh', 7000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3308, 1490, 188, 'Marketing Digital', '- Thực hiện và quản lý các chiến dịch quảng cáo trên các nền tảng số (Facebook Ads, Google Ads, TikTok Ads...).\n- Hỗ trợ xây dựng, triển khai và tối ưu chiến dịch quảng cáo để đạt KPI đã đề ra.\n- Phối hợp với bộ phận content và design để tạo ra nội dung quảng cáo phù hợp với từng kênh.\n- Quản trị và tối ưu SEO/SEM cho website, fanpage, landing page.\n- Theo dõi, phân tích dữ liệu, lập báo cáo hiệu quả chiến dịch định kỳ.\n- Cập nhật xu hướng digital marketing, đề xuất ý tưởng mới để nâng cao hiệu quả truyền thông.', '- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing, Truyền thông, Kinh tế hoặc các ngành liên quan.\n- Có kinh nghiệm từ 6 tháng – 1 năm trong lĩnh vực Digital Marketing hoặc vị trí tương đương.\n- Hiểu biết cơ bản về các công cụ chạy quảng cáo (Facebook Ads, Google Ads, TikTok Ads...).\n- Biết sử dụng các công cụ đo lường và phân tích (Google Analytics, Facebook Business Manager...).\n- Khả năng viết nội dung quảng cáo và tư duy hình ảnh tốt.\n- Năng động, học hỏi nhanh, chịu được áp lực công việc.', 10000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3309, 1491, 189, 'Nhân Viên Marketing', '1. Triển khai các hoạt động Marketing tại chi nhánh theo phân công của quản lý. \n2. Triển khai, theo dõi và tổng kết các chương trình khuyến mãi Trade thực hiện tại chi nhánh và POSM tại nhà thuốc. \n3. Vận hành kênh Tiktok của nhãn hàng triển khai tại chi nhánh như làm nội dung, livestream.\n4. Lập kế hoạch, liên hệ tổ chức sự kiện, hoạt động giới thiệu sản phẩm của công ty. \n5. Hỗ trợ các hoạt động của Phòng Kinh doanh, hỗ trợ xử lí cung cấp các ấn phẩm, vật phẩm cho Phòng kinh doanh.\n6. Các công việc khác theo phân công của quản lý.', 'Yêu cầu khác: \n- Có thể đi công tác. \n- Về chuyên môn: \n + Tốt nghiệp Cao đẳng, Đại học chuyên ngành liên quan về Kinh tế, Marketing, Y, Dược.\n + Có tối thiểu 1 năm kinh nghiệm tại vị trí Nhân viên Marketing.\n- Về phẩm chất: \n + Sáng tạo, chính trực, có trách nhiệm trong công việc.\n- Về kỹ năng:\n + Kỹ năng giao tiếp, thuyết phục tốt.\n + Kỹ năng tin học tốt: tin học văn phòng ( Word, Excel, Power point…), SEO, Internet.\n + Có khả năng chịu được áp lực cao trong công việc.\n + Phản ứng và xử lí vấn đề nhanh, linh hoạt.\n + Kỹ năng viết content.', 9000000.00, 11000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(3310, 1492, 190, 'Nhân Viên Marketing - Google Ads [Thủ Đức]', '- Tham gia các chương trình Affiliate, triển khai các chiến dịch Google Ads, bao gồm Search Ads, Display Ads và Performance Max.\n- Phân tích dữ liệu hiệu suất chiến dịch (như CTR, CPC, ROAS) để tối ưu hóa ngân sách, tăng doanh số và hoa hồng từ Affiliate.\n- Thực hiện nghiên cứu thị trường sâu rộng, bao gồm phân tích đối thủ, hành vi người dùng và xu hướng ngành để đề xuất chiến lược quảng cáo hiệu quả, giúp tăng tỷ lệ chuyển đổi và hoa hồng.\n- Theo dõi và báo cáo kết quả chiến dịch định kỳ, sử dụng công cụ như Google Analytics (GA4), Google Ads Editor.\n- Xử lý vấn đề phát sinh như quảng cáo bị từ chối hoặc biến động thị trường để duy trì hiệu suất ổn định và tối đa hóa lợi nhuận từ hoa hồng.', '- Kỹ năng Research tốt, thành thạo các công cụ như Semrush, GA4, Google Trends và các công cụ tương đương.\n- Tốt nghiệp Cao đẳng chuyên ngành Marketing, TMĐT, QTKD, Kinh tế,…\n- Có ít nhất 1 năm kinh nghiệm chạy Google Ads\n- Sử dụng thành thạo Google Ads, Google Analytics và các nền tảng Affiliate.\n- Khả năng làm việc độc lập, phân tích dữ liệu và giải quyết vấn đề nhanh chóng.\n- Kỹ năng giao tiếp tốt, khả năng làm việc nhóm và làm việc dưới áp lực cao.\n- Thành thạo tin học văn phòng, đặc biệt là Excel để xử lý dữ liệu, phân tích báo cáo và tối ưu hóa chiến dịch.\n- Tiếng Anh đọc viết Tốt, có khả năng đọc hiểu các tài liệu nghiên cứu bằng tiếng Anh.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3311, 1493, 191, 'Nhân Viên Marketing - Trên 2 Năm Kinh Nghiệm', 'Quản lý, chăm sóc, tối ưu các website/minisite của công ty\nTạo, quản lý  fanpage, các kênh social media khác của công ty.\nPhân tích, lập kế hoạch, phương án, thực hiện SEO website của công ty.\nQuảng bá hình ảnh công ty, các sản phẩm của công ty lên các diễn đàn chuyên ngành, mạng xã hội…\nQuản lý chat fanpage\nLên chiến lược, chọn chiến thuật, lập kế hoạch thực thi và quản lý các chiến dịch quảng cáo trực tuyến\nQuản lý các dịch vụ thuê ngoài của công ty liên quan đến lĩnh vực Marketing \nTìm hiểu, đề xuất kế hoạch tham gia các hội chợ, triển lãm chuyên ngành (nếu cần)\nCác công việc khác được giao từ Ban Giám đốc', 'Tốt nghiệp cao đẳng, đại học các chuyên ngành có liên quan.\nƯu tiên có kinh nghiệm SEO, viết bài chuẩn SEO (Sử dụng thành thạo các công cụ hỗ trợ SEO như: Google Webmaster Tools, Google Analytics,… và các công cụ phụ trợ khác.\nÍt nhất 2 năm kinh nghiệm ở vị trí tương đương\nBiết tạo, sử dụng và quản lý fapage trên facebook, google+.\nBiết viết, đăng bài, quản trị nội dung website, đăng tin vào diễn đàn.\nAm hiểu các công cụ Marketing Online.\nBiết sử dụng Photoshop, AI ( là lợi thế)\nLàm việc độc lập và chịu được áp lực cao trong công việc. Có tinh thần trách nhiệm, cẩn thận, nhiệt tình, trung thực.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3312, 1494, 192, 'Nhân Viên Content Marketing - Từ 6 Tháng Kinh Nghiệm', '•    Lên ý tưởng & viết bài cho Facebook, TikTok, Website, Zalo,…\n    •    Phối hợp sản xuất nội dung ảnh/video theo định hướng thương hiệu.\n    •    Cập nhật xu hướng & đề xuất ý tưởng sáng tạo hàng tuần.\n    •    Hỗ trợ triển khai các chiến dịch truyền thông, booking, viral.\n\n    •    Địa điểm làm việc: 132 Võ Chí Công, Tây Hồ, Hà Nội \n    •    Thời gian làm việc: thứ 2- thứ 7', '•    Tối thiểu 6 tháng kinh nghiệm ở vị trí Content\n    •    Tự tin, năng động, có khả năng giao tiếp, ăn nói mạch lạc, tự nhiên trước ống kính\n    •    Có gu thẩm mỹ & khả năng viết đa dạng (trẻ trung, cảm xúc, chuyên nghiệp).\n    •    Biết Canva/CapCut cơ bản là lợi thế.', 8000000.00, 12000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3313, 1495, 193, 'Nhân Viên Marketing', '- Nghiên cứu, phân tích các dữ liệu thị trường và bán hàng đưa ra ý tưởng marketing. \n- Xây dựng kế hoạch marketing, chương trình quảng cáo, tổ chức sự kiện, các chương trình giảm giá, khuyến mãi,... \n- Xác lập kinh phí, nhân sự thực hiện các chiến dịch marketing, quảng cáo. \n- Triển khai, theo dõi và đánh giá hiệu quả các chương trình truyền thông, tiếp thị sản phẩm/dịch vụ của doanh nghiệp với khách hàng. \n- Thiết lập, duy trì và phát triển các mối quan hệ với khách hàng, với đối tác chiến lược trong chiến dịch truyền thông của doanh nghiệp. \n- Phối hợp với các phòng ban, bộ phận liên quan thực hiện các hoạt động truyền thông nâng cao độ nhận diện thương hiệu tới khách hàng và đối tác.\n - Thực hiện các chương trình truyền thông nội bộ, gắn kết các phòng ban và phát triển văn hóa doanh nghiệp.\'', '- Biết sử dụng photoshop, canva, quản lý webside, fanpage...\n- Tốt nghiệp các ngành liên quan đến Kinh tế, Marketing, Truyền thông, PR hoặc các chuyên ngành liên quan\n- Kỹ năng giao tiếp tốt, chủ động, ham học hỏi\n- Chịu được áp lực công việc, có tinh thần cầu tiến', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3314, 1496, 194, 'Trợ Lý Giám Đốc', '+ Thực hiện các công việc hành chính: soạn thảo văn bản, lập báo cáo, quản lý công văn, Tiếp nhận và xử lý thông tin, Sắp xếp và chuẩn bị hồ sơ, tài liệu\n+ Đón tiếp khách hàng\n+ Chuẩn bị các chuyến công tác cho cấp trên \n+ Hỗ trợ phiên dịch khi cấp trên giao việc cho các phòng ban khác\n+ Báo cáo công việc hàng ngày/hàng tuần.\n+ Thời gian làm việc: T2 - T7: 8h00 - 17h00', '+ Giao tiếp tự tin được bằng tiếng Anh hoặc tiếng Hàn\n+ Tốt nghiệp trung cấp trở lên\n+ Sử dụng thành thạo tiếng anh (nghe, nói, đọc, viết)\n+ Kỹ năng tin học văn phòng (Word, excel, Powerpoint)', 10000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3315, 1497, 195, 'Giám Đốc Phát Triển Thị Trường', '- Nghiên cứu, phân tích thị trường thiết bị văn phòng tại Việt Nam (máy in, máy photocopy, máy chiếu, thiết bị lưu điện…).\n- Lập và triển khai kế hoạch mở rộng thị trường\n- Xây dựng và phát triển hệ thống đại lý, nhà phân phối, đối tác chiến lược toàn quốc.\n- Tuyển dụng, huấn luyện và quản lý đội ngũ nhân sự phát triển thị trường – kinh doanh tại các khu vực.\n- Phân tích hiệu quả hoạt động, báo cáo định kỳ cho Ban Giám đốc và đề xuất cải tiến.', '- Tốt nghiệp đại học trở lên chuyên ngành Quản trị Kinh doanh, Marketing, Kinh tế, hoặc các ngành liên quan.\nKinh nghiệm:\n- Tối thiểu 5 năm kinh nghiệm trong ngành thiết bị văn phòng, trong đó có ít nhất 2 năm giữ vị trí quản lý cấp trung hoặc cao.\n- Có hiểu biết tốt về sản phẩm, công nghệ, thương hiệu và chuỗi cung ứng thiết bị văn phòng.\nKỹ năng:\n- Kỹ năng nghiên cứu thị trường và lập kế hoạch phát triển vùng thị trường hiệu quả.\n- Kỹ năng quản lý đội nhóm, tạo động lực và đào tạo nhân sự kinh doanh.\n- Kỹ năng đàm phán, làm việc với nhà cung cấp và đối tác phân phối.\nPhẩm chất:\n- Tư duy thị trường nhạy bén, thích ứng nhanh với thay đổi công nghệ.\n- Chủ động, trách nhiệm, định hướng kết quả và có tinh thần phục vụ khách hàng cao.', 0.00, 1000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3316, 1498, 196, 'SEO Specialist - Chuyên Viên SEO', '- Build and execute SEO strategies tailored to the US F&B market. \n- Conduct keyword research & competitor analysis — with a focus on long-tail keywords targeting restaurant customer search intent. \n- Optimize website, blogs, landing pages, and customer knowledge base for search visibility. \n- Improve Local SEO performance for our merchants so their websites rank, driving more traffic and sales. \n- Track, analyze, and improve SEO performance using Google Search Console, SEMrush, GA4, and other tools. \n- Collaborate with content creators, developers, and analysts to deliver high-impact SEO initiatives.\n- Xây dựng và triển khai chiến lược SEO phù hợp với thị trường F&B (Food & Beverage) tại Mỹ.\n- Thực hiện nghiên cứu từ khóa & phân tích đối thủ — tập trung vào từ khóa dài (long-tail keywords) gắn liền với nhu cầu tìm kiếm của khách hàng nhà hàng.\n- Tối ưu hóa website, blog, landing page, và hệ thống kiến thức khách hàng để nâng cao khả năng hiển thị trên công cụ tìm kiếm.\n- Cải thiện hiệu suất SEO Local cho các đối tác/nhà hàng, giúp website của họ đạt thứ hạng cao hơn, tăng lượng truy cập và doanh số.\n- Theo dõi, phân tích và cải thiện hiệu suất SEO bằng các công cụ như Google Search Console, SEMrush, GA4 và các công cụ liên quan.\n- Phối hợp với team content, developer và analyst để triển khai các sáng kiến SEO hiệu quả.', '- 2–3 years of SEO experience (preferably in F&B, POS, or hospitality). \n- Strong knowledge of on-page, off-page, technical SEO, and local SEO. \n- Skilled in keyword research tools (SEMrush, Ahrefs, Google Keyword Planner…). \n- Proven experience identifying and ranking for long-tail keywords. \n- Hands-on with Google Search Console & GA4. \n- Understanding of US restaurant/dining search behavior. \n- English proficiency (reading/writing).\n- Kinh nghiệm SEO quốc tế hoặc đa ngôn ngữ.\n- Hiểu biết về WordPress hoặc CMS tương tự.\n- Kiến thức cơ bản về HTML/CSS.\n- Kinh nghiệm xây dựng backlink & hợp tác nội dung.\n- Nền tảng SaaS hoặc sản phẩm công nghệ.', 15000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3317, 40, 43, 'Cộng Tác Viên Marketing (Digital Marketing)', 'Giới thiệu về HMH\nHMH là công ty công nghệ thông tin chuyên cung cấp giải pháp phần mềm bản quyền và dịch vụ CNTT cho doanh nghiệp.\nChúng tôi là đối tác chính thức của nhiều hãng công nghệ lớn như Microsoft, Bitdefender, Google, ManageEngine, Adobe, AutoDesk, Zoom, Fortinet…, mang đến cho khách hàng các gói giải pháp tối ưu chi phí, bảo mật và hiệu quả vận hành.\nVới tầm nhìn trở thành đơn vị tiên phong trong lĩnh vực phân phối phần mềm và dịch vụ online cho SMB (doanh nghiệp vừa và nhỏ) tại Việt Nam, HMH không ngừng mở rộng kênh digital marketing, xây dựng thương hiệu chuyên nghiệp để kết nối với nhiều doanh nghiệp hơn.\n Gia nhập HMH, bạn sẽ có cơ hội\nHọc hỏi & phát huy kỹ năng thực chiến về digital marketing B2B trong ngành công nghệ.\nTrực tiếp triển khai các chiến dịch quảng cáo, content, xây dựng thương hiệu.\nĐồng hành cùng CEO và đội ngũ sales giàu kinh nghiệm, phát triển sự nghiệp marketing.\nCơ hội trở thành nhân sự chính thức nếu thể hiện năng lực tốt.\n Mục tiêu công việc\nHỗ trợ HMH triển khai hoạt động Digital Marketing tinh gọn nhằm tạo lead khách hàng tiềm năng (SMB, doanh nghiệp) trong mảng phần mềm bản quyền & dịch vụ CNTT.', 'NHIỆM VỤ CHÍNH\n 1. Content Marketing\nViết & đăng bài định kỳ trên Facebook, Zalo OA, LinkedIn (2–3 bài/tuần).\nNội dung tập trung vào giới thiệu sản phẩm (Microsoft, Bitdefender, ManageEngine, Adobe, AutoDesk, Zoom, Fortinet, Google Workspace…), chia sẻ tips công nghệ, case study SMB.\n 2. Quảng cáo Digital\nThực hiện và theo dõi quảng cáo Google Ads / Zalo Ads với ngân sách nhỏ, tối ưu để tạo lead chất lượng.\nBáo cáo hiệu quả ads hàng tuần, đề xuất cải tiến.\n 3. Thiết kế & Truyền thông\nSử dụng Canva hoặc công cụ tương đương để thiết kế poster, banner, hình ảnh minh họa cơ bản.\nHỗ trợ làm landing page/mini page (nếu có).\n 4. Nghiên cứu thị trường & khách hàng\nThu thập thông tin khách hàng tiềm năng (SMB, doanh nghiệp trong nước).\nTìm kiếm & tổng hợp insight ngành (VD: nhu cầu Microsoft 365, Fortinet, Adobe…).\n5. Báo cáo & phối hợp\nGửi báo cáo ngắn gọn hàng tuần: số bài viết, hiệu quả ads, số lead thu được.\nPhối hợp với Sales để chuyển lead đủ chất lượng.\n YÊU CẦU\nCó tối thiểu 1 năm kinh nghiệm ở vị trí tương đương (CTV / Part-time / Nhân viên Marketing Digital).\nCó kinh nghiệm thực tế trong:\nViết content marketing (social, website, landing page).\nTriển khai và tối ưu quảng cáo online (Google Ads, Facebook Ads/Zalo Ads cơ bản).\nBiết sử dụng Canva hoặc công cụ thiết kế cơ bản.\nKhả năng viết nội dung súc tích, dễ hiểu, định hướng khách hàng SMB.\nTư duy chủ động, cam kết hoàn thành công việc đúng deadline.', 6000000.00, 10000000.00, 'TP.HCM', 'Part-time', '2025-10-07 20:59:18.149534'),
	(3318, 1499, 197, 'Nhân Viên Kinh Doanh Chưa Có Kinh Nghiệm Được Đào Tạo', '1. Tư vấn và bán hàng: \nTìm kiếm, tiếp cận khách hàng tiềm năng qua các kênh như gọi điện, email, mạng xã hội hoặc các mối quan hệ sẵn có và các tệp khách hang từ các kênh chạy quảng cáo của công ty (Web, Fanpage, Group Facebook, Zalo…) \nTư vấn và giới thiệu các sản phẩm/dịch vụ của công ty phù hợp với nhu cầu khách hàng. \nChốt hợp đồng và theo dõi tiến độ thanh toán. \n2. Quản lý và phát triển khách hàng: \nDuy trì và phát triển mối quan hệ lâu dài với khách hàng hiện tại. \nQuản lý thông tin khách hàng trong hệ thống có sẵn của công ty \nGiải đáp thắc mắc và xử lý các vấn đề phát sinh của khách hàng. \n3. Lập kế hoạch và báo cáo: \nĐề xuất chiến lược kinh doanh, kế hoạch tiếp cận khách hàng. \nLập báo cáo định kỳ về kết quả kinh doanh, tỷ lệ chuyển đổi và dự báo doanh thu. \nTham gia các buổi họp, đào tạo và huấn luyện do công ty tổ chức. \n4. Phối hợp nội bộ: \nPhối hợp với phòng Marketing để triển khai các chương trình bán hàng, quảng cáo.', '1. Trình độ: \nTốt nghiệp Cao đẳng/Đại học, ưu tiên các ngành: Du lịch, quản trị du lịch, lữ hành và khách sạn, Kinh doanh, Quản trị kinh doanh, Marketing hoặc các lĩnh vực liên quan. \n2. Kinh nghiệm: \nChưa có kinh nghiệm được đào tạo\n3. Kỹ năng: \nKỹ năng giao tiếp và thuyết phục tốt. \nKỹ năng làm việc nhóm và làm việc độc lập. \nKỹ năng quản lý thời gian, xử lý tình huống linh hoạt. \n4. Tính cách và phẩm chất: \nNhiệt tình, năng động, chịu được áp lực công việc. \nCó tinh thần học hỏi, cầu tiến và sẵn sàng đổi mới. \n5. Ưu tiên: \nỨng viên có sẵn mối quan hệ khách hàng \nBiết sử dụng các công cụ CRM hoặc phần mềm bán hàng là một lợi thế.', 10000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3319, 1500, 198, 'Nhân Viên Digital Marketing (Lương Từ 13 - 14 Triệu)', '- Xây dựng, quản lý và phát triển nội dung trên hệ thống social của đơn vị. \n- Lên kế hoạch ngắn hạn và dài hạn, triển khai các hoạt động Marketing Online. \n- Triển khai, kiểm soát, tối ưu các chiến dịch digital và social marketing.\n- Phụ trách triển khai SEO, Google Ads…\n- Quản lý website, fanpage của công ty.\n- Phối hợp với các phòng ban để thực hiện các công việc liên quan \n- Thực hiện các công việc Marketing theo yêu cầu của cấp trên.\n- Địa điểm làm việc:    140/45 Hàn Hải Nguyên, Phường Bình Thới , Tp. Hồ Chí Minh (Phường 8 Quận 11 cũ)', '- Nam/Nữ/LGBT độ tuổi 21 - 34 tuổi\n- Có 2 năm kinh nghiệm \n- Tốt nghiệp Cao đẳng, đại học.\n- Nhiệt huyết, ứng biến tốt', 13000000.00, 14000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3320, 1501, 199, 'Nhân Viên Kinh Doanh - Thu Nhập 10-25 Triệu', 'Tìm kiếm, sàng lọc, phát triển khách hàng tiềm năng.\nTư vấn, báo giá và chốt hợp đồng với khách hàng, đảm bảo chỉ tiêu doanh thu.\nChăm sóc, duy trì và phát triển mối quan hệ với các khách hàng.\nBáo cáo định kỳ hàng tuần, tháng, quý và năm cho Trưởng bộ phận.\nCó cơ hội tiếp cận với lãnh đạo các doanh nghiệp lớn.\nThực hiện các công việc khác được giao.\nChi tiết trao đổi khi phỏng vấn.\nĐịa điểm làm việc: \nHồ Chí Minh: 21 Đường số 12G, Lovera Park, Phong Phú, Bình Chánh, Tp HCM\nHà Nội: Lầu 5, 74 Đền Lừ, Hoàng Mai, TP.Hà Nội.', 'Ưu tiên ứng viên đã từng làm NVKD B2B.\nĐam mê và yêu thích kinh doanh.\nThái độ tích cực, chịu khó học hỏi, làm việc và chịu được áp lực trong công việc.\nTinh thần trách nhiệm, chủ động, làm việc độc lập/nhóm.\nTư duy sáng tạo, năng động, nhiệt tình.\nKỹ năng bán hàng\nKỹ năng giao tiếp tốt, đàm phám, thương lượng\nKhả năng xây dựng, duy trì và phát triển mối quan hệ với khách hàng tốt.\nThành thạo word, excel, powerpoint và các thiết bị văn phòng.', 10000000.00, 25000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3321, 1502, 200, 'Thư Ký Kinh Doanh', 'Hỗ trợ lập báo cáo, hợp đồng, hồ sơ khách hàng.\nQuản lý lịch họp, lịch công tác và liên hệ đối tác.\nTheo dõi tiến độ dự án kinh doanh và chăm sóc khách hàng.\nHỗ trợ các công việc hành chính liên quan đến phòng kinh doanh.', 'Tốt nghiệp Cao đẳng/Đại học, ưu tiên chuyên ngành Quản trị Kinh doanh, Marketing, Ngoại ngữ.\nThành thạo tin học văn phòng, email, công cụ quản lý dữ liệu.\nGiao tiếp tốt, cẩn thận, nhanh nhẹn, chủ động.\nKinh nghiệm làm thư ký hoặc hỗ trợ phòng kinh doanh là lợi thế.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3322, 1503, 201, 'Nam Nhân Viên Kinh Doanh - Lương 15-25 Triệu', 'Hoạt động trong lĩnh vực đang rất phát triển và sôi động hiện nay: tư vấn và cung cấp sản phẩm, dịch vụ tiết kiệm năng lượng cho các doanh nghiệp lớn, tiêu thụ năng lượng trọng điểm trên cả nước: Dịch vụ Kiểm toán năng lượng; Xây dựng hệ thống quản lý năng lượng theo tiêu chuẩn ISO50001; Kiểm kê phát thải khí nhà kính; Cung cấp các khóa đào tạo về năng lượng – môi trường tại doanh nghiệp; dịch vụ chuyển đổi số trong lĩnh vực năng lượng – môi trường..\n- Chủ động tìm kiếm khách hàng mới tiềm năng thông qua cuộc gọi telesales, mạng lưới quan hệ, theo data sẵn có của công ty. Khách hàng là các doanh nghiệp lớn, tiêu thụ năng lượng trọng điểm trên cả nước.\n- Gặp gỡ khách hàng, thuyết phục khách hàng sử dụng sản phẩm, dịch vụ.\n- Quản lý, chăm sóc và giữ mối quan hệ thường xuyên với khách hàng.\n- Theo dõi, giám sát quá trình thực hiện các dự án.\n- Lập, thực hiện kế hoạch kinh doanh định kỳ.\n- Báo cáo kết quả kinh doanh định kỳ cho cấp quản lý trực tiếp/TPKD.', '- Độ tuổi: Không giới hạn, ưu tiên độ tuổi 24-35\n- Giới tính: Nam\n- Trung thực, năng động, nhiệt tình trong công việc, có ý chí cầu tiến\n- Có khả năng giao tiếp tốt\n- Ưu tiên các ứng viên có kinh nghiệm làm việc với các khách hàng doanh nghiệp', 15000000.00, 25000000.00, 'Hà Nội,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3323, 1504, 202, 'Nhân Viên Trade Marketing (Chuyên Kênh Mt & Hệ Thống Health & Beauty)', '- Làm việc với các đối tác kênh hiện đại như Pharmacity, An Khang, Con Cưng, Hasaki, Medicare, Lotte, Aeon, Emart... để xây dựng chiến lược theo từng giai đoạn. \n- Quản lý và triển khai hiệu quả các kế hoạch thúc đẩy doanh số và thương hiệu\n- Phối hợp với các team Brand để xây dựng và triển khai các chương trình Marketing phù hợp cho từng kênh và nhóm khách hàng\n- Lên kế hoạch chi tiết và triển khai: CTKM, trưng bày sản phẩm, chất lượng truyền thông tại điểm bán đảm bảo sự nhất quán với các kênh khác. \n- Kết nối và phối hợp với đối tác/kênh để tổ chức các hoạt động hỗ trợ bán hàng, như: Đào tạo kiến thức sản phẩm, chương trình thúc đẩy bán hàng nội bộ. \n- Theo dõi, phân tích xu hướng thị trường, báo cáo kịp thời cho Ban lãnh đạo để hỗ trợ ra quyết định chiến lược\n- Kiểm soát tình trạng hàng hóa (tồn kho, date, luân chuyển hàng...) tại kênh phụ trách; đề xuất giải pháp kịp thời khi phát sinh vấn đề\n- Thực hiện các nhiệm vụ khác theo sự phân công của Giám sát/Trưởng bộ phận.\n- Địa chỉ làm việc: 37 Đường số 39, Khu đô thị Vạn Phúc, Hiệp Bình Phước, Thủ Đức', '- Tốt nghiệp Cao đẳng trở lên chuyên ngành Marketing, QTKD, Kinh tế hoặc các lĩnh vực liên quan \n- Tối thiếu 1 năm kinh nghiệm tại các vị trí tương đương (Trade Marketing, Marketing Kênh MT, chuỗi bán lẻ,...)\n- Ưu tiên ứng viên có kinh nghiệm trong ngành hàng FMCG, Beauty, Retail\n- Kỹ năng giao tiếp, đàm phán và thuyết trình tốt\n- Có tinh thần trách nhiệm, chủ động, linh hoạt và khả năng làm việc nhóm\n- Kỹ năng phân tích và giải quyết vấn đề tốt\n- Thành thạo tin học văn phòng: Excel, PowerPoint, Word', 10000000.00, 13000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3324, 1505, 203, 'Nhân Viên Kinh Doanh', 'Đăng tuyển theo các job yêu cầu có sẵn, kết nối và tư vấn cho ứng viên các job phù hợp với chuyên ngành tốt nghiệp, kinh nghiệm làm việc đã có tại Việt Nam.\nKết nối với các Trường Cao đẳng và Đại học trong khu vực tổ chức chương trình hội thảo, ngày hội việc làm truyền thông về các Job đang tuyển dụng.\nChăm sóc data ứng viên tiềm năng của công ty, tìm kiếm khách hàng tiềm năng.\nDuy trì và phát triển các mối quan hệ hợp tác với các đối tác của Công ty.\nTiếp cận nguồn data khách hàng online từ các chiến dịch chạy quảng cáo của Công ty.', 'Tốt nghiệp Trung cấp trở lên các chuyên ngành liên quan.\nCó kinh nghiệm là một lợi thế (không có kinh nghiệm sẽ được đào tạo).\nCó laptop cá nhân\nThành thạo tin học văn phòng.\nKỹ năng thuyết trình.\nKỹ năng giao tiếp và giải quyết vấn đề\nThành thạo kỹ năng quản trị mối quan hệ.\nĐam mê công tác tư vấn, nhiệt huyết, chịu khó, có tinh thần trách nhiệm cao trong công việc.\nTác phong chuyên nghiệp, ngoại hình khá.', 10000000.00, 30000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3325, 1506, 204, 'Chuyên Viên / Phó Phòng Nghiên Cứu Thị Trường', 'Soạn thảo các báo cáo phân tích ngành hàng điện máy và viễn thông, kỹ thuật số trong và ngoài nước (báo cáo tuần, tháng, quý, năm)\nĐề xuất các báo cáo mới nhằm cải thiện và đáp ứng nhu cầu đặc trưng của từng khách hàng.\nXây dựng các form mẫu thu thập dữ liệu cho đội ngũ chuyên viên thị trường.\nHướng dẫn cho đội ngũ chuyên viên thị trường thu thập đúng dữ liệu mục tiêu cũng như giải đáp kịp thời cho khách hàng.\nHỗ trợ hoàn thành việc xây dựng hệ thống truy cập cơ sở dữ liệu ngành điện máy và viễn thông, kỹ thuật số; tham gia khai thác nhu cầu cho các dự án nghiên cứu và tùy chỉnh của doanh nghiệp ngành điện máy và viễn thông, kỹ thuật số, cũng như thực hiện các nghiên cứu định tính và định lượng trong dự án.\nNắm bắt các điểm nóng thông tin trong ngành, đưa ra các quan điểm và bài viết dựa trên biến động của ngành.\nĐịnh kỳ kết xuất các báo cáo chuyên sâu về ngành, thuyết trình và trao đổi với doanh nghiệp, đối tác.\nTham gia trao đổi với các hiệp hội ngành nghề, doanh nghiệp, công ty chứng khoán, v.v. và thu thập những thông tin có giá trị khác.\nHỗ trợ đàm phán và thúc đẩy các giao dịch thương mại với khách hàng.', 'Tốt nghiệp cao đẳng/ đại học trở lên, ưu tiên ứng viên có bằng chuyên ngành liên quan đến phân tích dữ liệu, kinh tế, quản trị, thống kê. Có nền tảng về phân tích kinh doanh và phương pháp nghiên cứu, nhạy bén trong việc nhận diện cơ hội thị trường và các điểm nóng của ngành\nCó ít nhất 3 năm kinh nghiệm trong lĩnh vực nghiên cứu chuyên ngành, nghiên cứu thị trường, hoặc nghiên cứu người tiêu dùng; ưu tiên ứng viên đã quản lý hoặc tham gia với vai trò thành viên nòng cốt trong các dự án tư vấn nghiên cứu quy mô lớn. Yêu cầu tư duy nhạy bén, khả năng suy luận tốt và hiệu suất làm việc cao.\nCó kỹ năng giao tiếp và trình bày tốt với khách hàng. Thành thạo tiếng Trung hoặc tiếng Anh, có khả năng sử dụng ngôn ngữ này trong công việc, bao gồm viết báo cáo và thuyết trình cho khách hàng. Ưu tiên ứng viên có kinh nghiệm làm việc tại các công ty tư vấn quốc tế, ưu tiên ứng viên có nền tảng du học.\nƯu tiên ứng viên có kinh nghiệm làm việc trong ngành điện máy và viễn thông, kỹ thuật số, ngành bán lẻ, hoặc công ty chứng khoán.\nChịu áp lực công việc tốt, sẵn sàng đi công tác nước ngoài ở mức độ vừa phải.\nCó kỹ năng phân tích dữ liệu tốt và khả năng thiết kế slide (PPT) chuyên nghiệp.\nKhi gửi hồ sơ, vui lòng nộp đồng thời bản CV tiếng Việt, tiếng Trung hoặc tiếng Anh.', 15000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3326, 1507, 205, 'Nhân Viên Digital Marketing', '- Xác định, phân tích và đào insight của nhóm đối tượng mục tiêu trên các nền tảng Google, website, Fanpage, Zalo, Tiktok, Youtube ...\n- Triển khai các hoạt động quảng bá thương hiệu và sản phẩm trên các kênh truyền thông số theo kế hoạch đã đề ra.\n- Lập kế hoạch & triển khai SEO, SEM, Google Adwords tối ưu hóa thứ hạng của website trên các trang tìm kiếm.\n- Viết tin bài quảng cáo cho web và facebook; triển khai hệ thống Seeding, backlink theo kế hoạch đề ra.\n- Đăng ký & quản lý các điểm bán sản phẩm của Cty trên Google map.\n- Thu thập thông tin từ thị trường, thông tin về sản phẩm, thông tin về các chương trình Digital Marketing, Social Media của đối thủ cạnh tranh.\n- Phát triển các chương trình kết nối cộng đồng, hệ sinh thái yêu thích thương hiệu Ý MỸ.\n- Quản trị & phối hợp nhập số liệu sản phẩm, tồn kho trên website bán lẻ mới của Cty.\n- Theo dõi đơn hàng, tư vấn sản phẩm online và phối hợp Phòng kinh doanh để bán hàng, báo cáo kết quả cuối cùng.\n- Thực hiện các công việc hỗ trợ khách hàng, trao đổi thông tin, tư vấn, phản hồi, giải đáp thắc mắc về sản phẩm của công ty, chuyển & theo dõi khiếu nại nếu có.', '- Tốt nghiệp Cao Đẳng trở lên.\n- Kinh nghiệm Marketing tử 3 năm trở lên\n- Kinh nghiệm PR, báo chí, truyền thông.\n- Am hiểu kỹ năng SEO và SEO Google Map.\n- Khả năng tự viết bài Content và Seeding, Backlink', 15000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3327, 1508, 206, 'Graphic Designer - Video Editor', '- Thiết kế hình ảnh tĩnh (banner, thumbnail, poster...) phục vụ các chiến dịch truyền thông hàng ngày.\n- Dựng video theo các định dạng phù hợp từng nền tảng (TikTok, Facebook, YouTube)\n- Chỉnh sửa video chuyên nghiệp: cắt dựng, chèn hiệu ứng, âm thanh, phụ đề... đảm bảo nội dung mượt mà, thu hút và đúng định hướng thương hiệu.\n- Sử dụng thành thạo các phần mềm dựng phim và thiết kế: Premiere Pro, After Effects, Photoshop,CapCup... để đảm bảo chất lượng và sự đồng bộ hình ảnh.\n- Phối hợp với team Marketing để lên ý tưởng và triển khai nội dung video – hình ảnh theo từng chiến dịch hoặc chủ đề cụ thể.\n- Quản lý thư viện media nội bộ: phân loại, lưu trữ khoa học theo từng dự án hoặc chủ đề.\n- Chủ động đề xuất ý tưởng sáng tạo, đảm bảo tiến độ và chất lượng sản phẩm theo yêu cầu từng tuần/tháng.\n- Thời gian làm việc:\n•   Từ thứ 2 – thứ 6: Sáng từ 8:00 đến 12:00, chiều từ 13:00 đến 17:00, \n•   Thứ 7 làm việc buổi sáng từ 8:00 đến 12:00\n•   Hoặc linh hoạt khi có lịch quay', '- Độ tuổi: 24 – 35 tuổi\n- Trình Độ; Cao đẳng trở lên các Ngành Thiết kế đồ hoạ, Truyền thông đa phương tiện, hoặc liên quan.\n- Có kinh nghiệm cơ bản về quay dựng, edit và thiết kế video cho các nền tảng mạng xã hội (TikTok, Facebook, Instagram).\n- Thành thạo ít nhất một công cụ dựng video (CapCut, Premiere, After Effects, Final Cut, v.v.), biết sử dụng app edit nhanh để bắt trend kịp thời.\n- Hiểu rõ đặc thù video ngắn, có khả năng nắm bắt insight người dùng mạng xã hội.\n- Có mắt thẩm mỹ tốt về bố cục, màu sắc, âm thanh; biết phối nhạc, ghép hiệu ứng tạo điểm nhấn.\n- Sáng tạo, chủ động, năng động, có trách nhiệm với deadline và chất lượng sản phẩm.\n- Ưu tiên ứng viên có kiến thức cơ bản về content marketing: Biết đặt caption, tiêu đề video thu hút, định hướng thông điệp phù hợp để tăng hiệu quả truyền thông.', 8000000.00, 15000000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3328, 1509, 207, 'Nhân Viên Sales Logistic (Xuất Nhập Khẩu) Đi Làm Ngay Tại Tân Bình Và Nam Từ Liêm', 'Nghiên cứu thị trường vận chuyển và hàng hóa XNK; đối thủ cạnh tranh\n– Tìm kiếm KH có nhu cầu xuất khẩu và vận chuyển hàng hóa đường biển\n– Liên hệ qua điện thoại, email, gặp gỡ KH để giới thiệu dịch vụ tới các khách hàng tiềm năng\n– Lập kế hoạch phát triển, mở rộng khách hàng, duy trì và phát triển khách hàng cũ, mới trong lĩnh vực giao nhận vận tải – Chủ yếu là cước và tải đường biển cho hàng xuất (bao gồm cả cước vận tải quốc tế, nội địa và các thủ tục liên quan đến xuất nhập khẩu)\n– Thường xuyên theo dõi, cung cấp các thông tin, tư vấn, đưa ra giải pháp phù hợp cho khách hàng để củng cố quan hệ và thúc đẩy kinh doanh\n– Chào dịch vụ và đàm phán các điều khoản liên quan đến dịch vụ logistics: giá, dịch vụ, lịch tàu, hợp đồng,\n– Duy trì, chăm sóc và phát triển mối quan hệ với các nhà cung cấp (Hãng Tàu, Cảng, Đại lý vận chuyển…)\n– Phối hợp chặt chẽ với các bộ phận nghiệp vụ, đảm bảo tư vấn và cung cấp cho khách hàng dịch vụ hợp lý nhất/ tốt nhất trên cơ sở dịch vụ sẵn có và dịch vụ mở rộng của công ty\n– Đảm bảo tuân thủ các qui định của phòng ban, công ty. Báo cáo trực tiếp công việc hàng ngày, hàng tuần, hàng tháng cho Quản lý phụ trách trực tiếp.\n– Các công việc khác trong phạm vi chức năng của Phòng Kinh doanh do Quản lý, Trưởng bộ phận hoặc Ban Giám đốc phân công.', 'Yêu thích kinh doanh, nhiệt tình, năng động, nhanh nhạy, sáng tạo trong công việc, có tinh thần trách nhiệm, kiên trì, nhẫn nại, chu đáo.\n– Ứng viên có trên 1 năm kinh nghiệm Sales tại các công ty forwarder hàng sea, hãng tàu.\n– Nhanh nhẹn, có khả năng, giao tiếp, đàm phàn, thuyết phục\n– Có khả năng làm việc độc lập, và phối hợp nhóm, chịu được áp lực cao trong công việc.\n– Có tư duy quản lý công việc, khả năng quản lý, sắp xếp thời gian và xử lý tình huống.\n– Thân thiện, hòa đồng, có khả năng thích nghi\n– Tốt nghiệp Đại học, Cao đẳng\n– Giao tiếp bằng tiếng Anh : nghe, nói, đọc , viết phục vụ trong công việc giao dịch\n– Có kỹ năng sử dụng phần mềm văn phòng,  (MS OFFICE, các phần mềm liên quan), sử dụng phần mềm\n– Ưu tiên:\n+ Tốt nghiệp đại học chuyên ngành ngoại thương/ kinh tế & vận tải\n+ Có kinh nghiệm 1 năm trở lên ở vị trí Sales cước tàu biển\n+ Có quan hệ tốt với các hãng tàu và các forwarder', 12000000.00, 20000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3329, 1510, 208, 'Nhân Viên Kinh Doanh Lương Trên 30 Triệu / Tháng - Đi Làm Ngay', 'Công ty Winsun chuyên sản xuất rèm cửa, bạt che nắng cần tuyển\n- 5 NVKD làm việc tại Hà Nội\n- 5 NVKD làm việc tại HCM\n - Tìm kiếm khách hàng – Báo giá – Tư vấn – Chốt Sales.\n- Chăm sóc, quản lý tập khách hàng có sẵn.\n- Nhận đơn đặt hàng của khách. Báo xưởng sản xuất.\n- Giải quyết, xử lý khiếu nại của khách hàng về sản phẩm dịch vụ.\n- Tạo mối quan hệ với khách hàng mới để bán hàng đạt KPI đề ra.\n- Lập kế hoạch bán hàng và nộp báo cáo cấp trên hàng tuần/hàng tháng.\nTiktok: Winsun việt nam ; Web: Winsun.com.VN; Web: Winsun.net.VN\n* Ưu điểm:\n- Khách hàng tiềm năng: là toàn bộ các cửa hàng rèm trên toàn quốc.\n- Khách đại lý: mở 1 lần chăm sóc tốt, khách đặt đơn mãi mãi, hưởng doanh số lâu dài.\n- Bớt áp lực khi là KHÁCH ĐẠI LÝ không phải luôn luôn tìm kiếm khách lẻ chỉ lấy 1 lần.\n- Sản phẩm hữu hình, dễ vào khách, ngành rèm ít cạnh tranh k vất vả như hàng tiêu dùng.\n- Được hỗ trợ khách hàng khi mới làm, được hỗ trợ đi thị trường.\n * Nơi làm việc: Công ty CP SX và TM WINSUN Việt Nam.\n+ Hà nội: Đường Tứ Hiệp, xã Tứ Hiệp, Thanh Trì, Hà Nội. (Cách bến xe nước ngầm 3km).\n+ HCM: 824/9 QL1A, Bình Trị Đông A, Bình Tân, HCM', '- NVKD Nam có ít nhất 1 năm kinh nghiệm trong các lĩnh lực bán hàng/kinh doanh khác.\n- Ưu tiên biết lái xe ô tô\n- Yêu thích kinh doanh, mục tiêu kiếm tiền rõ ràng.\n- Giọng nói dễ nghe, biết cách giao tiếp trực tiếp và làm việc qua điện thoại.\n- Tác phong chuyên nghiệp, nhiệt tình, biết cách giao tiếp với người lạ.\n- Làm việc độc lập, chịu được áp lực và biết phối hợp nhóm khi cần thiết.', 15000000.00, 30000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3330, 1511, 209, 'Nhân Viên Kinh Doanh Thị Trường (Lương Cứng 10-12Tr / Tháng + Hoa Hồng)', 'Tìm hiểu thị trường; khai thác và tiếp xúc trực tiếp với khách hàng (Phòng khám, nha khoa) để giới thiệu, tư vấn về sản phẩm và bán hàng.\nLập kế hoạch bán hàng, đảm bảo hoàn thành mục tiêu doanh số được phân giao\nChăm sóc khách hàng theo các chương trình chung của công ty;\nPhối hợp cùng bộ phận kế toán quản lý và thu hồi công nợ;\nThực hiện báo cáo kết quả kinh doanh cho quản lý', 'Tốt nghiệp trung cấp, cao đẳng, đại học. Không yêu cầu các bạn tốt nghiệp chuyên ngành về Y, Dược, công ty sẽ đào tạo các bạn, miễn là các bạn có tố chất và thái độ tốt.\nLà nam giới có ngoại hình khá trở lên;\nCó khả năng đi công tác tỉnh;\nCó kinh nghiệm trong lĩnh vực sale thị trường từ 1-2 năm là một lợi thế;\nKỹ năng giao tiếp, đàm phán, thương lượng, thuyết phục khách hàng tốt\nTính trung thực, có tinh thần cầu tiến, có ý chí phát triển sự nghiệp\nChủ động trong công việc, có tinh thần trách nhiệm cao', 20000000.00, 30000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3331, 1512, 210, 'Chuyên Viên Phát Triển Thị Trường', '- Phát triển thị trường: tìm kiếm, chăm sóc hệ thống cộng tác viên bán hàng, xây dựng mối quan hệ bền chặt lâu dài với khách hàng\n- Nghiên cứu thị trường: Xác định các thị trường tiềm năng cùng những biến động thị trường, đồng thời luôn cập nhật các tình hình của đối thủ và các sản phẩm mới\n- Lên kế hoạch đặt hàng theo tháng/ quý/ năm dựa trên phân tích báo cáo hàng hóa, dự báo xu hướng thị trường\n- Xây dựng, đào tạo và quản lý đội ngũ nhân viên kinh doanh nhằm đạt mục tiêu tăng trưởng và mục tiêu doanh số', '- Nam/Nữ độ tuổi từ 22 -35.\n- Ít nhất 1 năm kinh nghiệm làm các công việc liên quan đến xây dựng và phát triển quan hệ khách hàng\n- Kỹ năng chăm sóc khách hàng \n- Cẩn thận, nhanh nhẹn, xử lý vấn đề linh hoạt.\n- Kỹ năng tin học văn phòng tốt: word, excel, google sheets,....', 9000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3332, 1513, 211, 'Chuyên Viên Kinh Doanh Các Sản Phẩm Truyền Thông - Quảng Cáo Ooh Tại Hà Nội', 'Tìm kiếm và phát triển khách hàng tiềm năng trong lĩnh vực truyền thông quảng cáo (OOH, digital marketing, social, media, TVC, PR…).\nGặp gỡ, xây dựng mối quan hệ với khách hàng, khai thác nhu cầu và tư vấn giải pháp quảng cáo phù hợp.\nPhối hợp với các bộ phận liên quan để đề xuất ý tưởng, xây dựng kế hoạch và triển khai chiến dịch hiệu quả.\nChăm sóc khách hàng sau bán hàng, duy trì mối quan hệ dài hạn, thúc đẩy tái ký hợp đồng và mở rộng dịch vụ. \nThực hiện các hoạt động đàm phán, ký kết hợp đồng, theo dõi tiến độ thanh toán và công nợ.\nThực hiện các công việc khác theo chỉ đạo của quản lý trực tiếp.\nMôi trường làm việc chuyên nghiệp, nhiều cơ hội phát triển và thăng tiến', '●    Tốt nghiệp Đại học, ngoại hình ưa nhìn, tác phong chuyên nghiệp.\n●    Có kinh nghiệm sale trong lĩnh vực truyền thông, quảng cáo.\n●    Kỹ năng giao tiếp, tư vấn và đàm phán tốt; chủ động, độc lập trong công việc', 7000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3333, 1514, 212, 'Nhân Viên Media', 'Quay video lộ mặt giới thiệu sản phẩm (theo kịch bản có sẵn).\nDựng video ngắn, thêm text/nhạc, bắt trend TikTok, Shopee, Facebook.\nĐóng góp ý tưởng, sáng tạo nội dung để video viral.', 'Nữ, ngoại hình sáng, trẻ trung, tự tin xuất hiện trước ống kính.\n Giọng nói rõ ràng, không ngọng, nói chuyện tự nhiên.\n Năng động, bắt trend nhanh, có tinh thần trách nhiệm.\n Không cần kinh nghiệm – sẽ được training.', 9000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3334, 1515, 213, 'Nhân Viên Content Marketing Mỹ Phẩm Tại Thủ Đức', '- Viết, xây dựng kịch bản content quảng cáo sản phẩm cho công công ty về Mỹ Phẩm\n- Quay video, chụp ảnh, edit video trên phần mềm CapCut.\n- Thực hiện các công việc khác do cấp trên sắp xếp.', '- Có kỹ năng viết content ấn tượng, thu hút.\n- Có khả năng xử lý tình huống, làm việc trách nhiệm, chủ động.', 8000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3335, 1516, 214, 'Chuyên Viên Digital Marketing', '- Lập kế hoạch và triển khai Digital Marketing cho các mảng kinh doanh Điện Mặt Trời của SUNEMIT (SEO, tối ưu Fanpage, triển khai Youtube, tiktok...)\n- Lập kế hoạch nội dung cho website, Fanpage của công ty với phương châm: nội dung chất lượng, tối ưu chuyển đổi\n- SEO tổng thể website của công ty giúp tăng thứ hạng trên các phương tiện tìm kiếm, Chat AI và mạng xã hội theo định hướng của công ty.\n- Chịu trách nhiệm Tăng trưởng số lượng khách hàng tương tác từ các kênh Digital mà mình phụ trách.\n- Xây dựng hình ảnh thống nhất của Brand trên các kênh truyền thông Digital mà mình phụ trách. \n- Nghiên cứu và lập báo cáo hàng tuần/tháng về hiệu quả các chiến dịch Marketing đã thực hiện, báo cáo thực trạng thị trường cho BGĐ.', '- Yêu cầu tốt nghiệp Cao Đẳng trở lên chuyên ngành Marketing, Truyền thông, IT hoặc liên quan tới công việc.\n- Có khả năng đào tạo, giao tiếp tốt, truyền đạt vấn đề tốt\n- Có am hiểu về SEO, PR, Ads, AI \n- Đã được đào tạo và có kinh nghiệm về các thể loại Content, chịu khó tìm hiểu và áp dụng AI giúp nâng cao chất lượng công việc.\n- Có kinh nghiệm phát triển bằng phương pháp chính thống Whitehat. \n- Có khả năng sáng tạo', 12000000.00, 18000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3336, 1517, 215, 'Nhân Viên Kinh Doanh Phân Phối Ngành Hàng CNTT-Thiết Bị Hiển Thị Trình Chiếu [Tân Bình-Hồ Chí Minh]', 'Thực hiện tư vấn bán hàng cho các khách hàng đại lý, công ty tin học....(từ nguồn khách hàng có sẵn của công ty, khách hàng mới)\nBáo giá sản phẩm, dịch vụ theo yêu cầu của khách hàng; đàm phán, thỏa thuận ký kết hợp đồng với khách hàng\nTheo dõi, kiểm soát đơn hàng bán ra. Quản lý công nợ của khách hàng.\nHỗ trợ khách hàng, xử lý các phát sinh sau bán hàng. Chăm sóc, duy trì mối quan hệ với khách hàng.\nThực hiện một số nhiệm vụ khác theo yêu cầu của cấp trên và BGĐ.', 'Nữ/Nam tuổi từ 18 đến dưới 35, ngoại hình ưa nhìn. Có kinh nghiệm ít nhất 2 năm bán hàng trong lĩnh vực bán phân phối IT,thiết bị trình chiếu hiển thị… là một lợi thế.\nTốt nghiệp Trung Cấp trở lên (Ưu tiên chuyên ngành: Công nghệ thông tin, Quản trị Kinh doanh, Marketing, …)\nCó kiến thức về các sản phầm công nghệ thông tin, IT,máy vă phòng\nĐam mê kinh doanh, khả năng giao tiếp và thuyết phục hiệu quả, không nói ngọng.\nCó kỹ năng lắng nghe, kỹ năng thuyết phục khách hàng\nThái độ lịch sự, tự tin, thân thiện, tư duy nhanh nhạy, linh hoạt, xử lý tình huống tốt\nChăm chỉ,nhiệt tình, kiên trì, trung thực,cầu tiến và có trách nhiệm trong công việc và chịu được áp lực công việc.', 10000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3337, 1518, 216, 'Nhân Viên Quay Dựng Video Tiktok', '- Lên ý tưởng, kịch bản video ngắn phù hợp xu hướng TikTok và định hướng thương hiệu.\n- Quay video sản phẩm, dịch vụ, sự kiện… theo yêu cầu của công ty.\n- Dựng và chỉnh sửa video bằng các phần mềm chuyên dụng\n- Chèn hiệu ứng, âm nhạc, text, phụ đề để video thu hút người xem.\n- Quản lý, lưu trữ dữ liệu video và tối ưu chất lượng hình ảnh/âm thanh.', '- Có kinh nghiệm quay dựng video ngắn, ưu tiên đã làm việc với TikTok, Reels, Shorts.\n- Thành thạo các phần mềm dựng video cơ bản (CapCut, Adobe Premiere, After Effects…).\n- Có mắt thẩm mỹ, khả năng bắt trend nhanh.', 10000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3338, 1519, 217, 'Nhân Viên Sàn Thương Mại Điện Tử (Full Time)', '+ Trực tiếp livestream trên các sàn thương mại điện tử \n+ Tư vấn bán hàng, hướng dẫn khách sử dụng sản phẩm\n+ Phát triển nội dung bán hàng trên kênh bán hàng onl \n+ Thực hiện quay và edit video hàng hóa\n+ Làm việc full time hoặc ca 8 tiếng (sáng 8h30 tới 5h30 – chiều từ 2h chiều – 10h tối)', '+ Nam/Nữ tuổi từ 18 – 30 tuổi\n+ Có bằng THPT trở lên\n+ Không yêu cầu kinh nghiệm, được training kiến thức sản phẩm\n+ Ưu tiên nếu đã làm việc trên sàn shopee, Lazada, tiktok\n+ Có tư duy tốt, sáng tạo, chủ động trong công việc, hoạt ngôn', 8000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3339, 1520, 218, 'Nhân Viên Digital Marketing / Marketing Online', 'Tham gia lập kế hoạch và tổ chức thực hiện các chương trình, sự kiện, hoạt động truyền thông, quảng cáo trên Internet.\nPhụ trách các hoạt động digital ads marketing theo từng campaign trên Google Ads, Landing Page, Meta Ads,, Tiktok Ads, Zalo Ads, Forum, Email Marketing...\nCùng team quản lý các tools đánh giá hiệu quả online: Google Analytics, Google webmaster tools, Google Ad Planner,…\nCùng team quản lý nội dung website và tối ưu hoá cho mục đích tìm kiếm (SEO), backlink.\nTrực tiếp quản lý các kênh quảng cáo online như Facebook, CPC Admarket, Mobile Admarket, Cốc Cốc,...\nSetup quảng cáo, quản lý nội dung, ngân sách và đánh giá hiệu quả.\nQuản lý các kênh owned-media khác (FB Fanpage, Group cộng đồng, Youtube, Google +,Zalo doanh nghiệp).\nBáo cáo số liệu và hiệu quả online marketing.\nTham gia xây dựng và tối ưu hóa hệ thống Landing Pages, Link tracking và Pixel.', 'Thường xuyên cập nhật xu hướng thị trường.\nCó kiến thức thực tế về Facebook Ads, Google Ads, SEO, social media.\nCó ít nhất 2 năm kinh nghiệm.\nKỹ năng lập kế hoạch, quản lý thời gian tốt.\nNhanh nhẹn, trung thực, chủ động và có trách nhiệm cao với công việc, có tinh thần làm việc nhóm.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3340, 1521, 219, 'Nhân Viên Hành Chính Tổng Hợp - Đi Làm Ngay', 'Làm việc tại: 36 đường số 36, KĐT Vạn Phúc, Phường Hiệp Bình, TP.HCM\nThời gian: 8h00 - 17h30 (nghỉ trưa 2 tiếng).\nThời gian làm việc: 1 tuần làm 5 ngày, nghỉ cố định vào Thứ 2 và Thứ 5.\nCông việc chính:\nCông tác hành chính – văn phòng:\n-  Đăng tin, lọc hồ sơ, soạn thảo và lưu trữ giấy tờ liên quan.\n-  Quản lý, cập nhật dữ liệu, hợp đồng, giấy tờ, hồ sơ khách hàng.\nHỗ trợ & phối hợp cùng bộ phận Kinh Doanh và CSKH:\n-  Chuẩn bị tài liệu, hợp đồng, bảng báo giá phục vụ quá trình làm việc với khách hàng.\nHỗ trợ các công việc chăm sóc khách hàng cơ bản: tiếp nhận thông tin, phản hồi ban đầu, sắp xếp lịch hẹn.\n-  Đồng hành cùng đội ngũ Nhân viên kinh doanh, CSKH để đảm bảo tiến độ và hiệu quả công việc.', '•  Kỹ năng giao tiếp & xử lý tình huống tốt.\n•  Cẩn thận, trách nhiệm, chủ động trong công việc.\n•  Ưu tiên ứng viên có kinh nghiệm, chưa có sẽ được đào tạo từ đầu.', 8000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3341, 1522, 220, 'Nhân Viên Kinh Doanh (Mảng Vật Tư Y Tế / Test Nhanh)', '1. Công việc tiếp thị\nTiếp xúc tạo quan hệ với khách hàng trong vùng phụ trách.\nPhân tích, đánh giá tiềm năng, nhu cầu để dự báo doanh số bán hàng, đề xuất chỉ tiêu doanh số năm để trình cấp trên vào cuối năm để xây dựng kế hoạch chỉ tiêu cả năm cho cả Phòng.\nLập kế hoạch tiếp thị tháng, tuần dựa trên chỉ tiêu doanh số, cũng như nhu cầu mở rộng thị trường, mở rộng quan hệ,… với khách hàng trong vùng phụ trách và thực hiện công việc tiếp thị theo hướng dẫn của Quy trình Kiểm soát hoạt động tiếp thị\nBáo cáo tổng kết công việc hàng tuần, hàng tháng, danh sách khách hàng tiềm năng theo quy định của phòng.\nTạo nhu cầu cho khách hàng: dùng các kiến thức, kỹ năng chuyên môn để giới thiệu các sản phẩm của công ty đến khách hàng (awareness), kích thích sự mong muốn của khách hàng (need) và chuyển mong muốn của khách hàng thành nhu cầu (demand).\nChăm sóc khách hàng: tư vấn khách hàng sử dụng hết công năng của các sản phẩm đã cung cấp, theo dõi sự thoả mãn của khách hàng, nhận và giải quyết phàn nàn của khách hàng: chất lượng sản phẩm, thời gian giao hàng, các vấn đề kỹ thuật, cung cách phục vụ, dịch vụ hậu mãi,… \nMời dự hội nghị, hội thảo, tài trợ,…\nThực hiện các chiến dịch tiếp thị của phòng, các công việc khác theo sự phân công của cấp trên.\n 2. Công việc kinh doanh\nTiếp xúc tạo quan hệ với khách hàng trong vùng phụ trách.\nDự báo nhu cầu đặt hàng của khách hàng trước để đặt stock cho khách hàng hoặc đề nghị khách hàng đặt hàng trước, giảm thiểu số lần khách hàng đặt hàng & yêu cầu giao gấp.\nBáo cáo tổng kết công việc hàng tuần, hàng tháng.\nChăm sóc khách hàng\nSẵn sàng tiếp nhận việc triển khai kinh doanh sản phẩm mới, các công việc khác theo sự phân công của cấp trên.\n Khu vực làm việc:\nVăn phòng Hồ Chí Minh: 849 Trần Xuân Soạn, P. Tân Hưng, Quận 7, TP Hồ Chí Minh\nVăn phòng Hà Nội: Phố Nguyên Hồng, Phường Láng Hạ, Quận Đống Đa, Hà Nội\nĐà Nẵng: Linh động', 'Tốt nghiệp Cao đẳng trở lên chuyên ngành Kinh doanh, Hóa – Sinh – Dược – Y, Kỹ thuật Y Sinh hoặc ngành tương tương\nCó ít nhất 1 năm kinh nghiệm tại vị trí tương đương. Ưu tiên ứng viên có kinh nghiệm ở lĩnh vực xét nghiệm, dược, vật tư tiêu hao, thiết bị y tế.\nThành thạo Tin học văn phòng.\nGiao tiếp tốt, kỹ năng thương thảo, thuyết phục, chăm sóc khách hàng tốt.\nChịu khó, học hỏi nhanh, có thể đi công tác thường xuyên.', 13000000.00, 20000000.00, 'TP.HCM,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3342, 1523, 221, 'Trưởng Phòng Marketing, Lương Upto 30 Triệu', 'Quản lý và vận hành công việc phòng Marketing\nNghiên cứu, phân tích thị trường, phân khúc khách hàng tiềm năng;\nTổ chức và quản lý các chiến dịch quảng cáo/truyền thông (trên mạng xã hội, TV), các triển lãm và sự kiện truyền thông;\nSử dụng các công cụ Marketing Offline và Online để quảng bá sản phẩm và thương hiệu công ty.\nNghiên cứu, lập phương án xây dựng các chương trình quảng cáo, khuyến mãi, giảm giá, tri ân khách hàng.\nĐánh giá hiệu quả, kết quả đo lường sau khi kết thúc các chiến dịch Marketing quảng bá sản phẩm.\nThực hiện các công việc liên quan khác khi có các yêu cầu của Ban Giám Đốc.', 'Tốt nghiệp từ Đại Học trở lên chuyên ngành Marketing, Kinh tế.\nCó kinh nghiệm vị trí trưởng phòng MKT từ 2 năm trở lên. Có kinh nghiệm tổ chức sự kiện\nHiểu biết về các kênh Digital Marketing, Content Marketing\nGiới tính: Nam\nĐộ tuổi: Từ 30-38 tuổi', 25000000.00, 30000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3343, 1524, 222, 'Chuyên Viên Content SEO', 'Giới thiệu\nPickler.VN là nền tảng đầu tiên tại Việt Nam dành riêng cho cộng đồng Pickleball – bộ môn thể thao đang phát triển nhanh chóng trên toàn cầu. Chúng tôi đang tìm kiếm một SEO Specialist đam mê thể thao, yêu thích content marketing và có tư duy dữ liệu để cùng xây dựng hệ thống SEO bền vững, mở rộng cộng đồng Pickleball và lan tỏa lối sống năng động – khỏe mạnh.\n Mô tả công việc\nPhát triển & tối ưu nội dung SEO cho website, blog và landing page của Pickler nhằm nâng cao thứ hạng từ khóa liên quan đến:\nPickleball & đặt sân\nCộng đồng người chơi\nSức khỏe – cơ – xương – khớp\nPhục hồi & fitness\nXu hướng thể thao tại Việt Nam\nNghiên cứu & phân tích từ khóa (keyword research) theo từng nhóm chủ đề, xây dựng SEO content hub dài hạn.\nPhân tích đối thủ, hành vi người dùng và xu hướng tìm kiếm để đề xuất chiến lược nội dung, SEO roadmap và content pillar.\nXây dựng, chỉnh sửa và tối ưu nội dung (blog, bài viết chuyên sâu, trang dịch vụ, landing page) đảm bảo chuẩn SEO, dễ đọc, hấp dẫn và mang tính giáo dục.\nPhối hợp với team Content, Design, Kỹ thuật để triển khai:\nSEO Onpage: tối ưu cấu trúc website, internal link, metadata, tốc độ tải trang, mobile-first.\nSEO Offpage: link building, guest post, digital PR, social signal.\nTheo dõi hiệu quả SEO thông qua Google Analytics, Search Console, Ahrefs, SEMrush… Lập báo cáo định kỳ và đưa ra đề xuất cải tiến.\nCập nhật xu hướng SEO, thuật toán Google và các kỹ thuật mới (E-E-A-T, Core Web Vitals, Schema, AI Content, Voice Search).\nHỗ trợ phát triển nội dung đa kênh: Social, Email, Video SEO (YouTube/Short-form), tăng nhận diện thương hiệu.', 'Tối thiểu 2–3 năm kinh nghiệm SEO (ưu tiên lĩnh vực thể thao, sức khỏe, fitness hoặc wellness).\nThành thạo các công cụ SEO: Google Analytics, Google Search Console, Ahrefs, SEMrush, Screaming Frog.\nCó khả năng nghiên cứu & viết content chuẩn SEO bằng tiếng Việt và có thể đọc/viết tiếng Anh (bài dịch, tổng hợp thông tin quốc tế).\nKỹ năng phân tích dữ liệu, theo dõi KPIs (traffic, ranking, conversion) và đưa ra giải pháp tối ưu.\nHiểu biết về HTML/CSS, WordPress/Drupal, schema markup là một lợi thế.\nCó kiến thức hoặc kinh nghiệm về Social SEO, Video SEO, Entity SEO càng tốt.\nĐam mê thể thao hoặc quan tâm đặc biệt đến Pickleball là một điểm cộng cực lớn (ưu tiên ứng viên biết chơi Pickleball).', 11000000.00, 16000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3344, 1525, 223, 'Nhân Viên Google Ads - Thu Nhập 10-20M', '- Xây dựng, quản lý và tối ưu các chiến dịch chạy quảng cáo trực tuyến trên Google, Facebook, Tiktok, các trang mạng xã hội và mạng nghề nghiệp. \n- Nghiên cứu, viết bài và biên tập nội dung tin tức để xây dựng kênh truyền thông chất lượng, hấp dẫn. \n- Triển khai, đăng tin và quản lý nội dung trên website, facebook, zalo và các chiến dịch Marketing được phân công nhằm tối ưu hoá mục tiêu tìm kiếm. \n- Tổ chức triển khai các chương trình khuyến mại, thúc đẩy kênh truyền thông trực tuyến. \n- Phân tích, đánh giá và báo cáo hiệu quả các chiến dịch quảng cáo. \n- Thực hiện các nhiệm vụ khác theo sự phân công của Trưởng phòng. \n- Chi tiết công việc trao đổi tại buổi phỏng vấn.\nĐịa điểm làm việc: 186 Đường Láng, Đống Đa, Hà Nội', '- Tốt nghiệp Cao đẳng trở lên chuyên ngành Marketing \n- Có kinh nghiệm chạy quảng cáo trên Google, Facebook, Tiktok và các nền tảng số ( khoảng 6 tháng trở lên)\n- Khai thác tốt thông tin trên Internet, nhạy bén, sáng tạo và bắt kịp xu thế Marketing hiện đại. \n- Có tinh thần học hỏi, năng động, nhiệt tình, có trách nhiệm, chủ động trong công việc \n- Ưu tiên ứng viên có kinh nghiệm và thành thạo quảng cáo trực tuyến.', 10000000.00, 20000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(3345, 1526, 224, 'Nhân Viên Quản Lý Kênh Youtube - Marketing (Không Yêu Cầu Kinh Nghiệm)', 'Quản lý, phát triển kênh YouTube của công ty.\nHỗ trợ chỉnh sửa video, thiết kế thumbnail, đăng video.\nTối ưu video chuẩn SEO, tăng view, tăng tương tác.\nTìm trend, từ khóa hot, xây nội dung thu hút.\nTheo dõi chỉ số kênh và đề xuất cải thiện.', 'KHÔNG CẦN KINH NGHIỆM – sẽ được đào tạo từ A–Z.\nNữ, 18–26 tuổi.\nBiết dùng máy tính cơ bản.\nChăm chỉ, trung thực, nhanh nhẹn.\nĐam mê YouTube, yêu thích sáng tạo nội dung.', 6000000.00, 30000000.00, 'Nghệ An,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3346, 1527, 225, 'Nhân Viên Truyền Thông – Marketing (Online & Offline) - Nhà Sách Bạch Đằng', 'a. Truyền thông Online:\n- Quản lý và phát triển kênh Facebook, TikTok, Zalo OA, Website.\n- Lên kế hoạch content marketing theo tuần/tháng, tối thiểu 8 – 10 bài post/tháng.\n- Triển khai quảng cáo trả phí (Facebook Ads, TikTok Ads, Google Ads).\n- Xây dựng chương trình chăm sóc khách hàng cũ (Email, Zalo, mini game, voucher thành viên).\n- Đo lường hiệu quả truyền thông (reach, engagement, khách hàng mới, chi phí/hiệu quả).\n\nb. Truyền thông Offline tại chi nhánh:\n- Lên kế hoạch và triển khai các chương trình truyền thông trực tiếp tại chi nhánh: Back To School, Hội Sách Hè, Trung Thu, Noel, Tết, Black Friday…\n- Quản lý thiết kế và triển khai standee, banner, backdrop, tờ rơi, loa phát thanh, voucher offline.\n- Tổ chức sự kiện khai trương chi nhánh mới, ngày hội khách hàng.\n- Thu hút khách hàng mới từ cộng đồng địa phương (trường học, CLB thiếu nhi, hội phụ huynh).\n- Thu thập hình ảnh, clip sự kiện để sử dụng cho kênh truyền thông online.', '- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing, Truyền thông, Quan hệ công chúng, Báo chí, Quản trị kinh doanh hoặc liên quan.\n- Có kiến thức về truyền thông đa kênh (digital + offline) và hành vi tiêu dùng trong bán lẻ/sách.\n- Hiểu phễu marketing (AIDA: Awareness – Interest – Desire – Action).\n- Content Marketing: Viết nội dung quảng bá sáng tạo, storytelling.\n- Thiết kế & sáng tạo nội dung số: Canva, Photoshop; quay dựng video ngắn.\n- Quảng cáo & Digital Ads: chạy Facebook/TikTok Ads, Google Ads.\n- Sự kiện & offline marketing: tổ chức sự kiện, thiết kế POSM, điều phối MC, minigame, quà tặng.\n- Chăm sóc khách hàng: triển khai loyalty, voucher, email/zalo marketing.', 11000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3347, 1528, 226, 'Nhân Viên Marketing', '* Tiến hành nghiên cứu, phân tích dữ liệu về thị trường - khách hàng - đối thủ cạnh tranh.\n* Đề xuất các phương án tiếp thị sản phẩm.\n* Triển khai các hoạt động quảng cáo, PR và tiếp thị trên các nền tảng khác nhau (truyền thông đại chúng, số hóa, offline).\n* Quản lý và giám sát các chiến dịch để đảm bảo hiệu quả.\n* Đảm bảo các nội dung trên fanpage và website, sàn thương mại điện tử của công ty được thiết kế và quản lý hiệu quả.\n* Tổng hợp kết quả, lập báo cáo định kỳ về các hoạt động marketing và hiệu quả kinh doanh.\n* Cung cấp tài liệu và hỗ trợ marketing cho bộ phận bán hàng.\n* Thực hiện, đề xuất, giám sát đề xuất các chương trình quảng bá thương hiệu của công ty.\n* Theo dõi xu hướng và xu thế phát triển nhằm tăng sức hút về thương hiệu.\n* Kết hợp với các bộ phận khác như sản xuất, kinh doanh, và nghiên cứu phát triển sản\nphẩm để đảm bảo sự hài hòa trong chiến lược tổng thể của công ty.\n* Thiết kế nội dung in trên các chất liệu.\n* Thực hiện các công việc theo chỉ đạo của cấp trên.', '+ Có kinh nghiệm ở vị trí Nhân viên marketing hoặc các công việc tương tự.\n+ Có kiến thức marketing căn bản.\n+ Ưu tiên ứng viên có kinh nghiệm quản lý các kênh marketing và có thể sử dụng các công cụ marketing.\n+ Có kỹ năng làm việc nhóm tốt.\n+ Có kỹ năng tổ chức và quản lý thời gian.\n+ Tư duy phân tích tốt.\n+ Sáng tạo, linh hoạt', 10000000.00, 20000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3348, 1529, 227, 'Nhân Viên SEO – Marketing Online', '- Quản trị các Website của công ty (đăng sản phẩm, chỉnh sửa sản phẩm chuẩn SEO,...), tối ưu hoá website, đưa các từ khoá lên vị trí top của công cụ tìm kiếm \n- Quản trị Google Adwords, google maps, SEO website, SEO từ khóa, làm video up lên Yutube \n- Chỉnh sửa hình ảnh đăng quảng cáo \n- Biên tập nội dung, tài liệu và chỉnh sửa hình ảnh phục vụ cho quá trình Maketing Online \n- Lập báo cáo chi tiết về hiệu quả các chiến dịch. \n- Hỗ trợ thực hiện các công việc khác theo yêu cầu của cấp trên. \n- Thời gian làm việc: giờ hành chính từ thứ 2 tới sáng thứ 7\n- Địa chỉ làm việc: 786 quốc lộ 1A, P.Bình Hưng Hòa B, Q.Bình Tân, TP.HCM (đối diện đường Ao Đôi, gần cầu vượt Hương Lộ 2)', '- Ưu tiên nữ \n- Có kỹ thuật SEO cao. \n- On-page, off-page và tối ưu hóa websie tốt. \n- Kinh nghiệm với chiến lược nội dung SEO \n- Khả năng chạy quảng cáo Google Ads \n- Biết chỉnh sửa hình ảnh (bằng Photoshop…)', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3349, 1530, 228, 'Thực Tập Sinh Marketing', '- Hỗ trợ viết bài và chăm sóc website, các kênh của Công ty.\n- Thiết kế poster, nội dung bài viết truyền thông.\n- Thực hiện các hoạt động marketing (content, sự kiện, khảo sát khách hàng, chăm sóc kênh fb, youtube, tiktok…)\n- Chấp hành quy định, quy trình, chế độ báo cáo cho các cấp quản lý của công ty.', '- Không yêu cầu kinh nghiệm\n- Sinh viên năm cuối các ngành liên quan\n- Yêu thích Du lịch và đam mê kinh doanh\n- Kỹ năng giao tiếp, Kỹ năng lập kế hoạch, Quản lý sắp xếp tốt công việc', 1000000.00, 3000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(3350, 1531, 229, 'Chuyên Viên Thiết Kế 3D Nội Thất - Lương Từ 20 - 25 Triệu', 'Trực quan hóa 3D: Sử dụng phần mềm 3D để sáng tạo kết xuất ra hình ảnh chân thật không gian làm nổi bật tính năng sản phẩm nội thất của khách hàng\nLàm việc với khách hàng  để tạo nên khung cảnh, chọn lọc đạo cụ nội thất cho những bức hình, đảm bảo hình ảnh cuối đạt tiêu chuẩn chất lượng cao\nThiết kế đồ họa: Thiết kế hình ảnh nội thất trong nhiều không gian nội thất khác nhau\nThiết kế, dựng phối cảnh 3D nội thất (ưu tiên hàng nội thất)\nRender hình ảnh và video chất lượng cao theo yêu cầu', 'Có chứng chỉ về thiết kế nội thất, thiết kế đồ họa, hay những lĩnh vực liên quan\nKinh nghiệm trong thiết kế nội thất, ưu tiên hàng nội thất dự án từ 2 năm trở lên\nThành thạo phần mềm tạo mô hình và kết xuất 3D (VD: AutoCAD, SketchUp, Blender, V-ray hoặc tương đương)\nNắm vững kỹ năng thiết kế đồ họa và thành thạo sử dụng Adobe Creative Suite (Photoshop, Illustrator, InDesign, v.v)\nTinh thần trách nhiệm, làm việc đúng deadine', 20000000.00, 25000000.00, 'Bình Dương,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3351, 1532, 230, 'Nhân Viên Livestream (Shopee Hoặc Tiktok Shop)', '- Thực hiện toàn bộ việc lên kế hoạch, lịch trình cho các buổi video livestream phục vụ cho việc bán hàng cho các cửa hàng trên kênh .\n- Đảm bảo Host theo đúng kịch bản, thông tin truyền tải chính xác và kịp thời xử lý những câu hỏi, vấn đề của người xem khi diễn ra livestream, giúp cho buổi ghi hình được suôn sẻ và tạo hình ảnh chuyên nghiệp cho nhãn hàng.\n- Lên ý tưởng và đề xuất về concept, chủ đề, nội dung, kịch bản, sẽ được đề cập đến trong livestream để thu hút và giữ chân người xem.\n- Phối hợp với Marketing Planner để lựa chọn và xoay tua các nhãn hàng cần được lên livestream phục vụ ngày thường cũng như chiến dịch; các dòng sản phẩm cần được đẩy mạnh, thông tin giá bán & tính năng sản phẩm cần được truyền thông, mã giảm giá cũng như các chương trình khuyến mãi sẽ được truyền tải tới người xem livestream.\n- Đề xuất & xây dựng chi tiết cấu trúc chương trình cho từng livestream, bao gồm các phần giới thiệu sản phẩm, nhãn hàng, tính năng sản phẩm, giá bán, chương trình khuyến mãi……..cũng như tương tác với khán giả', '- Tự tin, mạnh dạn & hoạt ngôn trước ống kính, ứng biến linh hoạt theo tình huống.\n- Đã từng tham gia thực hiện các dự án về làm livestream, VJ, MC, Video clip,… \n- Có khả năng giao tiếp tốt và biết cách làm chủ giao tiếp\n- Nhạy bén với các xu hướng trên mạng xã hội\n- Không ngại lên ý tưởng, sáng tạo và biên tập nội dung, lên kịch bản nói', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3352, 1533, 231, 'Nhân Viên Marketing - Lĩnh Vực Visa', 'Lập kế hoạch chi tiết và triển khai hoạt động Marketing Online trên các nền tảng Social Media: Facebook, Instagram, Facebook Ads, hệ thống Website\nCó khả năng phân tích các chỉ số đánh giá khi chạy Google Ads để điều chỉnh, đưa ra chiến lược chạy Ads hiệu quả\nViết bài PR, bài chuẩn SEO \nTìm hiểu, nghiên cứu thị trường để nâng cao chất lượng, dịch vụ phục vụ khách hàng\nThời gian làm việc: T2 - T6: 9h - 18h, nghỉ trưa 12 - 13h', 'Có khả năng giao tiếp tiếng Anh tốt\nƯu tiên người có kinh nghiệm marketing trong lĩnh vực IRC, ERC, visa, work permit, TRC,…', 10000000.00, 25000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3353, 1534, 232, 'Chuyên Viên Truyền Thông - Sự Kiện (Quận Hà Đông)', 'Mảng Sự kiện (Event):\n- Là gương mặt đại diện chính của Trà Shanam tại các sự kiện, triển lãm, hội thảo.\n- Trực tiếp thực hiện các buổi trình diễn pha trà, mời trà và giới thiệu sản phẩm, lan tỏa văn hóa trà Việt.\n- Lên kế hoạch và triển khai các hoạt động truyền thông, PR trước, trong và sau sự kiện để tối đa hiệu quả.\n- Thực hiện các tour trà về rừng trà và nhà máy\nMảng Truyền thông (Content & PR): \n- Sản xuất nội dung đăng bài trên page và web, mạng xã hội\n- Xây dựng và duy trì mối quan hệ tốt với các đơn vị báo chí, truyền thông.\n- Lên tuyến bài, quản lý lịch đăng bài trên các kênh truyền thông của công ty.', 'Ưu tiên ứng viên Tốt nghiệp chuyên ngành Báo chí, Truyền thông, Quan hệ công chúng hoặc các ngành liên quan.\nKỹ năng viết lách và kể chuyện xuất sắc, hành văn mạch lạc, lôi cuốn.\nTự tin, giao tiếp tốt, không ngại đứng trước đám đông và ống kính.\nNgoại hình sáng, phong thái thanh lịch, phù hợp với hình ảnh thương hiệu cao cấp.\nChủ động, linh hoạt và sẵn sàng di chuyển, công tác khi có sự kiện.', 12000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3354, 1535, 233, 'Nhân Viên Quay Dựng Video', 'Thực hiện dựng và quay sản phẩm theo kịch bản.\nĐề xuất ý tưởng, triển khai video trên các kênh online.\nChỉnh sửa và sản xuất nội dung video kênh Youtube, Facebook và Website của công ty.\nThực hiện các video theo chiến dịch truyền thông của công ty.\nPhát triển các ý tưởng và triển khai các ý tưởng dựng phục vụ kênh Marketing của công ty như Website, mạng xã hội và các kênh offline theo yêu cầu.\nPhụ trách chụp ảnh sản phẩm, chỉnh sửa hình ảnh và chụp hình thể thao, sự kiện,…\nCác công việc khác do cấp trên chỉ đạo.', 'Tốt nghiệp Cao đẳng trở lên chuyên ngành thiết kế đồ họa, quay phim hoặc các chuyên ngành có liên quan.\nDưới 1 năm ở vị trí tương đương.\nSử dụng tốt các phần mềm thiết kế Adobe: Photoshop, illustrator,...\nSử dụng tốt các công cụ Video Editing là một lợi thế.', 8000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3355, 1536, 234, 'Nhân Viên Truyền Thông Mạng Xã Hội', '• Lập kế hoạch và triển khai truyền thông các kênh MXH \n• Quay, dựng video, chỉnh sửa chụp ảnh, cắt ghép các clip để tạo thành 1 clip hoàn chỉnh. \n• Tìm tư liệu và dựng các clip content có sẵn. \n• Sáng tạo các nội dung video mới theo trend và định hướng của tổ chức. \n• Hỗ trợ các công việc khác trong nhóm truyền thông nội bộ', '• Biết sử dụng phần mềm Video Scribe \n• Biết thiết kế hình ảnh cơ bản \n• Hiểu biết về truyền thông mạng xã hội (Tiktok, youtube, face…) \n• Có kiến thức cơ bản về quản trị website', 8000000.00, 10000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3356, 163, 166, 'Chuyên Viên Social Content', 'Chịu trách nhiệm sáng tạo, điều phối và triển khai nội dung đa dạng trên các nền tảng mạng xã hội (Facebook, TikTok, Instagram, YouTube...) nhằm tăng tương tác, thu hút người theo dõi, và xây dựng hình ảnh thương hiệu/nhãn hàng một cách nhất quán, hấp dẫn và phù hợp xu hướng y tế;\nTrực tiếp tham gia các sự kiện khai trương, livestream… để lấy tin, dữ liệu bao gồm ảnh, clip… phục vụ cho truyền thông;\nLiên hệ booking các Fanpage địa phương cho các hoạt động của nhãn hàng;\nViết bài Social Post và các công việc khác liên quan theo yêu cầu từ cấp quản lý trực tiếp;\nTheo dõi các hoạt động Social liên quan đến nhãn hàng trên các hội nhóm;\nLên plan seeding tổng thể, seeding các thông tin về nhãn hàng trên kênh Social;\nQuản lý các trang kênh mạng xã hội và xây dựng nội dung bao gồm bài viết, hình ảnh, video… đăng tải lên các kênh social media của công ty (bao gồm FB, Youtube, Tiktok) để tăng tương tác;\nTrao đổi và tương tác với khách hàng mục tiêu trên các kênh Social media hàng ngày.', 'Tốt nghiệp chuyên ngành Marketing, Content…;\nCó kinh nghiệm ít nhất 3 năm làm ở vị trí tương đương;\nCó kỹ năng viết lách và năng lực biến hoá với từ ngữ tốt;\nNắm bắt tốt với các xu hướng trên thị trường, hiểu được cách viết một tiêu đề bài viết bắt trend, hợp thời để gia tăng khả năng tìm kiếm trên Social media, trên công cụ tìm kiếm Google;\nCó tính sáng tạo cao để có thể làm ra những content với đa dạng hoá hình thức;\nLuôn làm mới nội dung quảng cáo đến khách hàng để tạo sự mới mẻ, không gây nhàm chán.\nCó kiến thức về bệnh học, am hiểu kiến thức y khoa là một lợi thế;\nNắm bắt nhanh các trend trên mạng xã hội;\nHiểu rõ về thương hiệu và quảng bá hình ảnh nhãn hàng trên các phương tiện Internet và Social media;\nCó khả năng làm việc độc lập và theo nhóm tốt;\nCó kinh nghiệm sử dụng các công cụ chỉnh sửa cơ bản (CapCut, Canva, Premiere… là lợi thế).', 14000000.00, 18000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(3357, 1490, 188, 'Video Editor (Digital Marketing)', '- Chịu trách nhiệm quay dựng video phục vụ chiến dịch Digital Marketing (Facebook, TikTok, YouTube, Google Ads…).\n- Cắt ghép, chỉnh sửa video theo kịch bản, đảm bảo nhanh, bắt trend, thu hút và đúng thông điệp marketing.\n- Phối hợp với team Content & Ads để tạo video bán hàng, video quảng cáo, video phễu (audit ads, landing page, logo, v.v.).\n- Tối ưu chất lượng hình ảnh, âm thanh, hiệu ứng để đạt hiệu quả cao trên các nền tảng social & ads.\n- Tham gia xây dựng ý tưởng kịch bản, concept video cho chiến dịch chạy ads & xây kênh TikTok/Facebook.\n- Quản lý kho dữ liệu video, hình ảnh, template phục vụ các dự án media.\n- Hỗ trợ thiết kế banner, thumbnail, short video khi cần.', '- Thành thạo Adobe Premiere, After Effects, CapCut, Canva hoặc phần mềm dựng video tương tự.\n- Có kinh nghiệm dựng video cho Facebook Ads, TikTok Ads hoặc kênh social là lợi thế.\n- Nắm bắt trend mạng xã hội và biết ứng dụng vào video marketing.\n- Có mắt thẩm mỹ, khả năng cảm nhạc và phối màu tốt.\n- Chủ động, sáng tạo, chịu áp lực tiến độ.\n- Ưu tiên ứng viên từng làm trong agency digital marketing hoặc thương mại điện tử.', 10000000.00, 12000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3358, 1537, 235, 'Nhân Viên Kinh Doanh Thị Trường (Thu Nhập Lên Tới 20 Triệu)', 'Tìm kiếm và phát triển hệ thống khách hàng mới trong khu vực được phân công\nChăm sóc, tư vấn và duy trì mối quan hệ với khách hàng cũ.\nGiới thiệu, tư vấn sản phẩm phụ kiện điện thoại.\nĐàm phán, ký kết hợp đồng, theo dõi đơn hàng.', 'Nam tuổi từ 20 - 30, tốt nghiệp THPT trở lên\nCó phương tiện cá nhân đi lại \nGiao tiếp tốt, siêng năng, ham học hỏi.\nKhông có kinh nghiệm sẽ được đào tạo. \nƯu tiên có kinh nghiệm sale, telesale, hoặc từng làm thị trường.', 8000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3359, 1538, 236, 'Marketing Specialist (KOL / KOC Cooperation)', 'KOL/KOC Collaboration Management: Establish and maintain partnerships with Key Opinion Leaders (KOLs) and Key Opinion Consumers (KOCs) for marketing campaigns.\nAgency Networking: Utilize existing talent agency resources to source high-performing KOLs, ensuring collaboration efficiency.\nPerformance-Based KOL Partnerships: Identify and work with result-oriented KOLs or agencies, focusing on performance-driven marketing campaigns.\nDirect & Indirect Influencer Negotiation: Engage directly with influencers and their management teams to establish strategic collaborations.\nCampaign Execution & Monitoring: Oversee influencer marketing campaigns, ensuring content aligns with branding and performance objectives.\nApp & E-commerce Promotion Experience (Preferred): Experience in managing influencer campaigns for app promotions or e-commerce platforms is a strong advantage.\nMulti-Platform Coordination: Manage influencer marketing strategies across platforms such as Facebook, TikTok, Instagram, and YouTube.\nLong-Term Relationship Building: Develop long-term partnerships with high-value influencers and agencies for continuous brand exposure.', 'Minimum 2 years of experience in PR, influencer marketing, or related fields.\nStrong network of KOLs/KOCs and talent agencies, with a proven track record of successful collaborations.\nExperience in handling multiple influencer marketing campaigns with measurable results.\nAbility to negotiate and manage contracts with influencers and agencies.\nPrior app promotion or e-commerce marketing experience is highly preferred.\nStrong communication and relationship-building skills to maintain long-term partnerships.\nAbility to track campaign performance and optimize influencer strategies for higher engagement and convers', 13000000.00, 20000000.00, 'TP.HCM', 'Contract', '2025-10-07 20:59:18.149534'),
	(3360, 1539, 237, 'Nhân Viên Marketing', 'Xây dựng và đề xuất kế hoạch marketing.\nTìm kiếm, làm việc với freelancer, KOLs, nhà sản xuất nội dungm  hoặc agency (dựng video, thiết kế, quay chụp,...).  Phối hợp với đối tác để lên ý tưởng kịch bản. Đảm bảo tiến độ và chất lượng đầu ra. \nThu thập phản hồi thị trường từ bộ phận sales. Hỗ trợ làm tài liệu bán hàng, quảng bá sản phẩm.\nTìm kiếm và bắt trend, tạo nội dung theo xu hướng trên TikTok/Facebook, website. \nTheo dõi hiệu suất clip (số lượt xem, tương tác, chuyển đổi...). Đánh giá hiệu quả chiến dịch & đề xuất cải tiến.\nThực hiện các công việc khác theo yêu cầu của Quản lý.', 'Có từ 1 – 2 năm kinh nghiệm ở vị trí liên quan đến sản xuất nội dung/video hoặc làm việc với đối tác.\nHiểu biết về Digital Marketing, Social Media, Content Marketing. Sử dụng các công cụ: Google Ads, Facebook Ads, Canva,… là lợi thế.', 12000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3361, 1540, 238, 'Marketing & Content Team Leader', 'Phụ trách lên kế hoạch, sắp xếp và điều phối việc sản xuất sản phẩm truyền thông (hình ảnh & video) cho công ty, bao gồm: quay chụp album mẫu, chụp áo cưới/vest mẫu, chụp Lookbook, chụp Makeup Look... nhằm phục vụ cho các hoạt động bán hàng của team kinh doanh.\nPhụ trách lên kế hoạch và phát triển nội dung trên các kênh Social Media của công ty bao gồm: Facebook, Instagram, TikTok. Phân công, sắp xếp, điều phối nhân sự thực hiện các kế hoạch nội dung theo tuần, tháng, quý và theo trends.\nPhụ trách lập kế hoạch & phát triển mảng Website của công ty.\nLập kế hoạch và tổ chức thực hiện các chương trình ưu đãi, hoạt động CSKH, giới thiệu bộ sưu tập, các sự kiện khác... nhằm nâng cao nhận diện thương hiệu và thúc đẩy doanh số.\nTham gia giám sát công việc quản lý chất lượng sản phẩm & dịch vụ của công ty.\nTuyển dụng và đào tạo nhân sự trong team.\nChạy quảng cáo FB Ads, TikTok Ads, Zalo Ads, Google Ads.\nThực hiện các công việc khác theo yêu cầu của cấp trên.', 'Nam/Nữ tuổi từ 26 – 35.\nGu thẩm mỹ tốt, có thế mạnh về content và sản xuất hình ảnh.\nTốt nghiệp Đại học trở lên chuyên ngành Quản trị kinh doanh, Kinh tế, Marketing.\nCó kinh nghiệm hoạt động trong ngành Marketing từ 05 năm trở lên, từng giữ vị trí Marketing Leader ít nhất 2 năm.\nƯu tiên ứng viên từng làm việc trong lĩnh vực cưới, thời trang, làm đẹp.\nBiết Tiếng Anh là một lợi thế.\nSáng tạo, nhạy bén, tư duy tốt, khả năng chịu áp lực công việc cao.\nCó khả năng làm việc nhóm và phát triển đội ngũ.', 18000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3362, 1541, 239, 'Nhân Viên Thiết Kế Bao Bì Mỹ Phẩm - Thu Nhập Từ 12 Đến 17 Triệu (Hồ Chí Minh)', 'Thiết kế bao bì sản phẩm\nPhối hợp lên kịch bản, giới thiệu sản phẩm\nHỗ trợ content Video\nCông việc khác thuộc phòng ban', 'Có kinh nghiệm thiết kế bao bì > 2 năm\nTư duy hình ảnh sáng tạo\nSử dụng thành thạo các phần mềm thiết kế (AI, Photoshop, v.v.)', 12000000.00, 17000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3363, 72, 75, 'Nhân Viên Kinh Doanh Internet - Fpt Telecom Khu Vực Gò Vấp, Quận 12, Hóc Môn', '- Tư vấn, giải thích cho khách hàng về dịch vụ do FPT Telecom đang cung cấp;\n- Mặt hàng: viễn thông (Internet và Truyền hình)\n- Đàm phán, thương lượng, xúc tiến ký kết hợp đồng với khách hàng;\n- Tìm kiếm khách hàng tiềm năng, chăm sóc khách hàng sau bán hàng và phát triển thị trường;\n- Làm việc tại văn phòng hoặc theo yêu cầu, hướng dẫn của quản lý trực tiếp;', '- Nam/ Nữ, tốt nghiệp trung cấp trở lên, tuổi từ 20 - 30;\n- Có phương tiện di chuyển và smartphone;\n- Đam mêm kinh doanh, đam mê kiếm tiền, yêu thích công việc tiếp xúc với khách hàng;\n- Giao tiếp tốt, có kỹ năng thuyết phục;\n- Nhanh nhẹn, linh hoạt, giải quyết tình huống tốt;\n- Ngoại hình dễ nhìn, không nói ngọng, nói lắp;\n- Chịu được áp lực cao trong công việc.', 8000000.00, 25000000.00, 'TP.HCM', 'Internship', '2025-10-07 20:59:18.149534'),
	(3364, 1542, 240, 'Nhân Viên Marketing', '1. Xây Dựng Ý Tưởng Sáng Tạo:\n- Phát triển và triển khai các ý tưởng mới, sáng tạo trong nội dung (bài PR, bài chuẩn SEO, kịch bản, ấn phẩm truyền thông) trên các kênh truyền thông online, offline của Công ty phù hợp với chiến lược thương hiệu và mục tiêu tiếp thị.\n- Tìm kiếm và áp dụng các xu hướng mới trong lĩnh vực sáng tạo nội dung, liên tục cải tiến ý tưởng và phong cách để tạo ra nội dung thú vị và thu hút\n- Chịu trách nhiệm sản xuất nội dung truyền thông Digital/Offline (Kịch bản video, content sản phẩm, thương hiệu, feedback khách hàng...) và quản lý nội dung trên các nền tảng mạng xã hội (Fanpage, Website, Tiktok, shopee, Zalo)\n- Tham gia cùng team đóng góp các ý tưởng nội dung sáng tạo cho chiến dịch Digital Marketing.\n- Thực hiện các công việc khác theo sự phân công của người quản lý\n2. Viết Kịch Bản Video:\n- Tạo ra các kịch bản video hấp dẫn, gây ấn tượng để truyền tải thông điệp của sản phẩm/dịch vụ.\n- Quản lý quy trình sản xuất video từ ý tưởng ban đầu đến bản hoàn thiện.', '- Tốt nghiệp Đại học các chuyên ngành Marketing, Truyền thông, Kinh tế.\n- Có ít nhất 1 năm kinh nghiệm tại vị trí tương đương.\n- Am hiểu về nội dung và các mạng xã hội. Có kiến thức về quản trị thương hiệu.\n- Khả năng viết tốt và linh hoạt các dạng nội dung (branding, social media, blog, review, press release…).\n- Có tư duy sáng tạo, đổi mới và cải tiến liên tục trong việc phát triển nội dung các kênh truyền thông.\n- Có trách nhiệm với công việc, khả năng làm việc độc lập, chủ động.\n- Kỹ năng giao tiếp tốt; thái độ tích cực, chủ động, ham học hỏi và không ngại cái mới.\n- Có kỹ năng sử dụng các phần mềm thiết kế, dựng video là một lợi thế.\n- Loại hình công việc: Toàn thời gian\n- Thời gian làm việc (Từ thứ 2 đến hết sáng thứ 7 trong tuần)', 10000000.00, 15000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3365, 1543, 241, 'Thực Tập Sinh Marketing Parttime', '- Tìm kiếm và tư vấn cho học viên thông qua fanpage của SOC hoặc đăng bài cá nhân.\n- Tìm kiếm và xây dựng cơ sở dữ liệu của ứng viên tiềm năng.\n- Lên kế hoạch chi tiết tổ chức, định hướng và nội dung cho chiến dịch quảng cáo sự kiện của SOC.\n- Lập kế hoạch đăng bài trên các fanpage sản phẩm của SOC.\n- Hỗ trợ lên ý tưởng trong các hoạt động sale của nhóm sản phẩm.\n- Lưu trữ thông tin, hình ảnh và báo cáo sau mỗi chương trình.\n- Phối hợp với các phòng ban khác trong các chương trình, hoạt động của công ty.\n- Liên kết với các CLB để kết nối cộng động SOC với cộng đồng sinh viên trẻ.\nThời gian làm việc: 8h00 - 11h30 (Sáng)\n                                 13h - 16h30 (Chiều)', '- Có kỹ năng giao tiếp linh hoạt, khéo léo, lắng nghe, thuyết phục và xử lý vấn đề tốt.\n- Biết sử dụng đồ họa, các công cụ photoshop .. là một lợi thế.\n- Yêu thích viết lách, tư vấn, tìm tòi những xu hướng hay thông tin kiến thức mới về giáo dục.\n- Thái độ tích cực, chủ động, hòa đồng, vui vẻ, làm việc có trách nhiệm.\n- Có định hướng gắn bó lâu dài và mong muốn trở thành những team leader trong tương lai.', 1000000.00, 15000000.00, 'Hà Nội', 'Internship', '2025-10-07 20:59:18.149534'),
	(3366, 1532, 230, 'Nhân Viên Quay - Dựng Video', 'Quay phim:\nThực hiện quay phim các sản phẩm, sự kiện, hoạt động của công ty.\nLựa chọn góc máy, ánh sáng, âm thanh phù hợp để đảm bảo chất lượng hình ảnh và âm thanh tốt nhất.\nSử dụng thành thạo các thiết bị quay phim, máy ảnh, thiết bị âm thanh.\nChuẩn bị và thiết lập không gian livestream, bao gồm bố trí góc quay đẹp, điều chỉnh ánh sáng phù hợp, kiểm tra và đảm bảo chất lượng âm thanh tốt nhất để tạo ra trải nghiệm chuyên nghiệp cho người xem.\nDựng phim:\nBiên tập, cắt ghép, chỉnh sửa các đoạn phim thô thành video hoàn chỉnh.\nThêm hiệu ứng, âm nhạc, đồ họa, phụ đề vào video để tăng tính hấp dẫn và truyền tải thông điệp rõ ràng.\nSử dụng thành thạo các phần mềm dựng phim chuyên nghiệp như Adobe Premiere Pro, Final Cut Pro, hoặc các phần mềm tương tự.\nPhối hợp:\nLàm việc chặt chẽ với team Marketing, Content để hiểu rõ mục tiêu, thông điệp cần truyền tải của video.\nTiếp thu ý kiến đóng góp và chỉnh sửa video cho đến khi đạt yêu cầu.\nCác nhiệm vụ khác:\nNghiên cứu, cập nhật các xu hướng mới trong lĩnh vực quay dựng video.\nQuản lý, bảo quản các thiết bị quay phim, dựng phim.\nThực hiện các công việc khác theo yêu cầu của cấp trên.\nĐịa điểm làm việc: Tầng 17, Toà nhà Flemington, 182 Lê Đại Hành, Phường 15, Quận 11, TPHCM', 'Kinh nghiệm: Có ít nhất 2 năm kinh nghiệm ở vị trí tương đương.\nKỹ năng:\nThành thạo các kỹ thuật quay phim, dựng phim.\nSử dụng thành thạo các phần mềm dựng phim chuyên nghiệp.\nCó kiến thức về đồ họa, âm thanh, ánh sáng.\nCó khả năng sáng tạo, tư duy thẩm mỹ tốt.\nCó khả năng làm việc độc lập và làm việc nhóm.\nYêu cầu khác:\nCẩn thận, tỉ mỉ, có trách nhiệm cao trong công việc.\nSẵn sàng làm việc ngoài giờ khi cần thiết.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3367, 1544, 242, 'Nhân Viên Kinh Doanh', 'Tư vấn, giới thiệu sản phẩm tiềm năng của công ty đến khách hàng từ nguồn data có sẵn.\nChăm sóc, hỗ trợ khách hàng trong suốt quá trình giao dịch.\nTham gia tổ chức sự kiện, mở bán, chiến dịch truyền thông.\nMột số công việc khác theo yêu cầu và sắp xếp của quản lý.', 'Không yêu cầu kinh nghiệm sẽ được đào tạo từ A–Z.\nGiao tiếp tự tin, phong thái chuyên nghiệp.\nNhanh nhẹn, cẩn thận, chịu khó học hỏi.\nLàm việc nhóm, khả năng sáng tạo, chủ động trong công việc', 9000000.00, 50000000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3368, 1545, 243, 'Nhân Viên Content Creator Marketing', 'Sáng tạo nội dung video, hình ảnh, bài viết, kịch bản trên Facebook, TikTok, YouTube, Instagram.\nPhối hợp với team để sản xuất nội dung chất lượng.\nTheo dõi xu hướng, đề xuất ý tưởng mới để viral mạnh mẽ', 'Có kinh nghiệm 1 - 2 năm lĩnh vực Content/Digital Marketing\nThành thạo các công cụ Canva, CapCut, Photoshop, Premiere…\nTư duy sáng tạo, nhanh nhạy với xu hướng mới', 8000000.00, 14000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3369, 1546, 244, 'Nhân Viên Tư Vấn Bán Hàng Ô Tô Cũ / Mới - Không Cần Kinh Nghiệm (Phỏng Vấn Đi Làm Ngay)', '- Tìm kiếm thông tin khách hàng trên các nền tảng online, mạng xã hội: facebook, zalo, tiktok, youtube, Website,..;\n- Tiếp cận trực tiếp khách hàng để tư vấn và xây dựng mối quan hệ lâu dài với khách hàng;\n- Đàm phán và ký kết hợp đồng với khách hàng;\n- Làm việc : Giờ hành chính: 8h -17h ( Được nghỉ 02 ngày thứ bảy và 04 ngày chủ nhật)\n- Địa điểm làm việc : 220 Nguyễn Hữu Cảnh, Phường Thạnh Mỹ Tây, TP.HCM (Ngay cạnh Khu Dân cư Vinhome Bình Thạnh – Landmark 81 tầng)', '- Không cần kinh nghiệm, chỉ cần đam mê ô tô;\n- Có ngoại hình, năng động, tự tin, giao tiếp tốt, có thể làm việc độc lập;\n- Tốt nghiệp Cao Đẳng trở lên các chuyên ngành kinh tế, marketing hoặc công nghệ kĩ thuật ô tô', 17000000.00, 50000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3370, 1547, 245, 'Nhân Viên Media - Quay Dựng', '- Quay clip phục vụ truyền thông quảng cáo, Tiktok, Youtube…Công ty.\n- Set up thiết bị, ánh sáng cho livestream và quay clip.\n- Chụp hình sản phẩm, các sự kiện của Công ty.\n- Phối hợp với bộ phận Content xây dựng ý tưởng theo yêu cầu của chiến dịch\n- Phối hợp với bộ phận Thiết kế sản xuất giao diện, đồ họa cho các video\n- Lập báo cáo định kỳ.\n- Các công việc liên quan theo sự phân công của trưởng bộ phận.', '- Ít nhất 1 năm kinh nghiệm ở vị trí tương đương.\n- Có khả năng setup ánh sáng, bố cục và màu sắc tốt\n- Biết edit video bằng các phần mềm chuyên dụng cơ bản\n- Có gu thẩm mỹ và nhiều ý tưởng trong quay dựng\n- Làm việc nhóm\n- Chỉnh chu, cẩn thận, có trách nhiệm\n- Sức khỏe tốt, nhiệt tình, không ngại công tác khi phát sinh\n Ưu tiên\n- Có kinh nghiệm tại các công ty dược mỹ phẩm, beauty\n- Sử dụng thành thạo các phần mềm After Effect/Adobe Premiere/Final Cut, Photoshop/AI, Illustrator… và các công cụ hỗ trợ khác.', 12000000.00, 16000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3371, 1548, 246, 'Nhân Viên Digital Marketing', 'Tham gia xây dựng và triển khai các kế hoạch Digital Marketing \nThực hiện nghiên cứu thị trường, phân tích đối thủ và hành vi khách hàng để hỗ trợ xây dựng định hướng truyền thông phù hợp.\nPhối hợp với các bộ phận có liên quan, triển khai quảng cáo đa kênh trên các nền tảng như Facebook, Google, TikTok, và các sàn thương mại điện tử (Shopee, Lazada,...).\nPhối hợp với team content và thiết kế để tạo nội dung truyền thông hiệu quả (hình ảnh, bài viết, video,...).\nTheo dõi, đánh giá và tối ưu hiệu suất các chiến dịch quảng cáo dựa trên các chỉ số KPIs. \nLập báo cáo định kỳ hiệu quả chiến dịch marketing.', 'Tối thiểu 03 năm kinh nghiệm ở vị trí tương tự (ưu tiên FMCG).\nTốt nghiệp Đại học các chuyên ngành về Marketing, Truyền thông, Thương mại điện tử, hoặc các ngành liên quan.\nThành thạo các công cụ về Digital\nThành thạo các công cụ quảng cáo Facebook Ads, Google Ads, TikTok Ads, Shopee Ads...\nCập nhật xu hướng Digital Marketing mới để ứng dụng vào chiến lược thương hiệu.\nBiết sử dụng các công cụ đo lường và phân tích như: Google Analytics, Meta Business Suite,...', 13000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3372, 1520, 218, 'Nhân Viên Digital Marketing (Arena Multimedia)', 'Tham gia lập kế hoạch và tổ chức thực hiện các chương trình, sự kiện, hoạt động truyền thông, quảng cáo trên Internet.\nPhụ trách các hoạt động digital ads marketing theo từng campaign trên Google Ads, Landing Page, Meta Ads,, Tiktok Ads, Zalo Ads, Forum, Email Marketing...\nTham gia cùng team Quản lý các tools đánh giá hiệu quả online: Google Analytics, Google webmaster tools, Google Ad Planner, ......\nQuản lý nội dung website và tối ưu hoá cho mục đích tìm kiếm (SEO), backlink.\nTrực tiếp quản lý các kênh quảng cáo online như Facebook, CPC Admarket, Mobile Admarket, Cốc Cốc,...\nSetup quảng cáo, quản lý nội dung, ngân sách và đánh giá hiệu quả.\nQuản lý các kênh owned-media khác (FB Fanpage, Group cộng đồng, Youtube, Google +,Zalo doanh nghiệp).\nBáo cáo số liệu và hiệu quả online marketing.\nXây dựng và tối ưu hóa hệ thống Landing Pages, Link tracking và Pixel', 'Thường xuyên cập nhật xu hướng thị trường\nCó ít nhất 2 năm kinh nghiệm ở vị trí tương đương\nKỹ năng lập kế hoạch, quản lý thời gian tốt\nNhanh nhẹn, trung thực, chủ động và có trách nhiệm cao với công việc, có tinh thần làm việc nhóm.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3373, 1549, 247, 'Nhân Viên Chăm Sóc Khách Hàng (Full Time)', 'Tiếp nhận và tư vấn, giải đáp thắc mắc của khách hàng qua điện thoại, email và các kênh hỗ trợ khác.\nCập nhật và thông báo các chương trình khuyến mãi, ưu đãi đến khách hàng.\nGhi nhận & phản hồi yêu cầu của khách hàng kịp thời, chuyên nghiệp.\nHỗ trợ livestream bán hàng (có lương riêng).\nThực hiện các công việc khác theo chỉ đạo từ quản lý.', 'Giới tính: Nữ, độ tuổi từ 19 – 30.\nGiọng nói dễ nghe, rõ ràng, truyền cảm.\nƯu tiên ứng viên có kinh nghiệm chăm sóc khách hàng hoặc bán hàng.\nKỹ năng giao tiếp tốt, khéo léo, tinh tế, kiên nhẫn.\nNăng động, nhiệt huyết, thái độ tích cực.\nNgoại hình ưa nhìn là một lợi thế.', 8000000.00, 12000000.00, 'Hà Nội', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3374, 1550, 248, 'Trưởng Phòng Truyền Thông - Tuyển Sinh', 'Phối hợp, lập kế hoạch, chiến lược truyền thông nhằm quảng bá hình ảnh, chương trình đào tạo của công ty.\nTriển khai và giám sát các hoạt động tuyển sinh qua các kênh truyền thông như website, mạng xã hội, quảng cáo online và offline.\nQuản lý và điều phối đội ngũ nhân viên trong phòng, đảm bảo tiến độ và hiệu quả công việc.\nPhối hợp với các phòng ban khác để tổ chức các sự kiện, hội thảo, hoạt động quảng bá thu hút học viên.\nTheo dõi, phân tích và đánh giá hiệu quả các chiến dịch truyền thông, từ đó đưa ra các biện pháp cải tiến phù hợp.\nĐề xuất các kế hoạch truyền thông sáng tạo và hiệu quả nhằm tăng cường thương hiệu và thu hút học viên.\nThời gian làm việc: T2-T6 từ 7h30-12h và chiều 13h30-17h, Thứ 7: sáng 8h30 - 12h', 'Tốt nghiệp đại học trở lên chuyên ngành quản trị kinh doanh hoặc các ngành liên quan.\nÍt nhất 1 năm kinh nghiệm trong lĩnh vực tư vấn tuyển sinh. Ưu tiên am hiểu hoạt động trong lĩnh vực giáo dục.\nKỹ năng giao tiếp, thuyết trình, và xử lý tình huống nhanh nhạy.\nKhả năng lập kế hoạch, tổ chức và triển khai các chiến dịch truyền thông hiệu quả.\nCó tinh thần trách nhiệm, tuân thủ kỷ luật, trung thực.\nKhả năng lập kế hoạch, tổ chức và triển khai các chiến dịch truyền thông hiệu quả.\nKỹ năng lãnh đạo, quản lý đội ngũ tốt, có khả năng phân công công việc và giám sát tiến độ.\nThành thạo các công cụ truyền thông, quảng cáo trực tuyến, và các kênh mạng xã hội.', 12000000.00, 17000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3375, 1551, 249, 'Nhân Viên Video Editor - Lương Up To 18Tr / Tháng', 'Phối hợp triển khai cùng các bộ phận có liên quan để xây dựng hình ảnh cho các chiến dịch quảng cáo tiếp thị sản phẩm của công ty.\nThực hiện các công việc quay dựng, chỉnh sửa video, chụp ảnh trong các chương trình, sự kiện của công ty.\nNhận kịch bản sẵn có, xây dựng các ý tưởng cảnh quay và setup cảnh quay cho các clip quảng cáo, video giới thiệu sản phẩm, dịch vụ mà công ty phân phối.\nChỉnh sửa, xử lý cắt ghép, biên tập (cân bằng tiếng, hình ảnh, âm thanh,…) video để phục vụ PR, Marketing theo yêu cuầ của công ty.\nXây dựng ý tưởng theo yêu cầu của các phòng ban.\n Chi tiết trao đổi khi phỏng vấn..', 'Trình độ tốt nghiệp Cao đẳng các chuyên ngành liên quan đến media, đồ họa, marketing, truyền thông, quảng cáo.\nCó kinh nghiệm ít nhất 2 năm ở vị trí tương đương\nSử dụng thành thạo phần mềm Adobe Premiere, Affter Effect, photoshop, Lightroom.\nCó khả năng sử dụng, làm chủ các thiết bị, phụ kiện quay, studio & ánh sáng, âm thanh.\nCó khả năng tư duy thẩm mỹ, đề xuất các sáng kiến mới cho các sản phẩm hình ảnh chủ đề được giao', 12000000.00, 18000000.00, 'Bình Dương', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3376, 1552, 250, 'Nhân Viên Video Editor & Graphic Design', 'Nơi làm việc: Trực tuyến (remote hoặc work from home)\nThời gian làm việc: Full-time: Thứ 2 - 6, và sáng thứ 7.\nChịu trách nhiệm sản xuất, chỉnh sửa video và hỗ trợ thiết kế hình ảnh phục vụ cho các chiến dịch truyền thông, quảng cáo, mạng xã hội và nội dung nội bộ của công ty và cho khách hàng.\n1. 85% – Video Editing:\nChỉnh sửa video cho các nền tảng Facebook, Instagram, TikTok, YouTube, v.v. \nSáng tạo nội dung video theo xu hướng (shorts, reels, TikTok...) \nCắt dựng, xử lý hiệu ứng chuyển cảnh, chèn text, nhạc nền, màu sắc, hiệu ứng phù hợp với định hướng thương hiệu. \nBiên tập từ footage thô (phỏng vấn, vlog, sự kiện, story ngắn…) thành sản phẩm hoàn chỉnh có câu chuyện rõ ràng. \nPhối hợp với Content & Marketing team để nắm bắt ý tưởng và triển khai nội dung hiệu quả. \nTối ưu hóa định dạng, kích thước video cho từng kênh phân phối\n2. 15% – Graphic Design:\nThiết kế hình ảnh cho bài đăng mạng xã hội, banner digital, email marketing, slide thuyết trình... \nHỗ trợ thiết kế các tài liệu truyền thông nội bộ & cho khác hàng khi cần.', 'Tốt nghiệp Đại học các chuyên ngành: Thiết kế, Mỹ thuật, MKT… hoặc các văn bằng tương đương \nTối thiểu 02 năm kinh nghiệm trong công việc tương đương \nSử dụng thành thạo phần mềm (Premiere, AE, Capcut,) và phần mềm thiết kế (PTS, AI...) có hiểu biết Branding Design \nCó tư duy thẩm mỹ, yêu thích sáng tạo \nTích cực học hỏi, tinh thần cầu tiến \nKhả năng giao tiếp và truyền đạt ý tưởng tot \nLàm việc có trách nhiệm, chịu được áp lực và đáp ứng deadline gấp tốt \nCó khả năng sử dụng tiếng Anh là một lợi thế \nCó khả năng sử dụng tốt AI phục vụ cho công việc\nƯu tiên ứng viên ở các tỉnh thành miền Bắc gần Hà Nội, Hải Phòng.', 15000000.00, 18000000.00, 'Hà Nội,', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3377, 1553, 251, 'Nhân Viên SEO Marketing _ Đi Làm Ngay', '- Lập kế hoạch và triển khai chiến lược SEO để cải thiện thứ hạng website trên Google.\n- Phân tích từ khóa, tối ưu nội dung, xây dựng liên kết (Onpage & Offpage).\n- Quản lý và tối ưu quảng cáo Google Ads, Facebook Ads.\n- Viết bài chuẩn SEO, tối ưu content trên website/facebook.\n- Theo dõi, phân tích dữ liệu, báo cáo hiệu quả chiến dịch theo tuần/tháng/quý...\n- Đưa ra kế hoạch, lộ trình SEO theo tháng, quý, năm và mục tiêu dự kiến.\n- Phối hợp với các bộ phận khác để triển khai kế hoạch marketing tổng thể.\n- Các hoạt động, công việc liên quan theo yêu cầu của cấp trên.\nCó thể tham khảo chi tiết trên website công ty : https://xaydungducthao.com/', '- Trình độ học vấn: Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing hoặc các ngành liên quan.\n- Có kinh nghiệm 2 năm trong lĩnh vực SEO & Digital Marketing.\n- Hiểu biết sâu về thuật toán Google, các công cụ SEO\n- Kỹ năng viết content SEO tốt, tư duy sáng tạo.\n- Có kinh nghiệm chạy Google Ads, Facebook Ads là một lợi thế.\n- Chủ động, có trách nhiệm trong công việc.\n- Biết dùng các công cụ: canva, video edit phục vụ cho nội dung SEO.', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3378, 1554, 252, 'Digital Marketing', 'Lên kế hoạch, triển khai và quản lý các chiến dịch Digital Marketing trên các kênh: Facebook, Google Ads, TikTok, Zalo, Email Marketing, SEO, Website,…\nQuản lý nội dung (content, hình ảnh, video) trên các nền tảng mạng xã hội, website, fanpage.\nTối ưu hiệu quả các kênh quảng cáo để đạt KPI (tương tác, lead, doanh số,…).\nTheo dõi, phân tích số liệu, báo cáo kết quả chiến dịch và đưa ra đề xuất cải thiện.\nPhối hợp với bộ phận Content, Design, Sales để triển khai các hoạt động Marketing đồng bộ.\nNghiên cứu thị trường, đối thủ và xu hướng digital mới để áp dụng vào chiến dịch.', 'Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing, Truyền thông, Thương mại điện tử hoặc liên quan.\nCó kinh nghiệm từ 6 tháng – 2 năm ở vị trí tương đương.\nThành thạo ít nhất 1–2 kênh digital (Facebook Ads, Google Ads, SEO, TikTok,…).\nKỹ năng phân tích số liệu, lập báo cáo và tối ưu chi phí.\nSáng tạo, chủ động, cập nhật nhanh các xu hướng Digital Marketing.\nƯu tiên ứng viên có kỹ năng thiết kế cơ bản (Canva, Photoshop) hoặc quay/chỉnh sửa video.\nTrao đổi thêm chi tiết khi phỏng vấn', 10000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3379, 1555, 253, 'Nhân Viên Thiết Kế (Graphic Designer)', '- Thiết kế banner, thumbnail, bộ ảnh sản phẩm phục vụ các sàn Thương mại điện tử (Shopee, Lazada, TikTokShop, ...). \n- Tối ưu hình ảnh gian hàng: đảm bảo giao diện bắt mắt, dễ nhìn và đúng nhận diện thương hiệu. \n- Hỗ trợ triển khai các chiến dịch marketing, chương trình khuyến mãi bằng các hình ảnh sáng tạo, thu hút. \n- Chủ động cập nhật xu hướng thiết kế mới, đề xuất ý tưởng hình ảnh phù hợp với từng Campaign.', '- Có ít nhất 2 năm kinh nghiệm trong lĩnh vực thiết kế, ưu tiên từng làm trong môi trường TMĐT. \n- Có laptop cá nhân \n- Thành thạo các phần mềm thiết kế: Adobe Illustrator, Photoshop, ... \n- Tư duy sáng tạo tốt, khả năng thẩm mỹ cao, hiểu tâm lý người dùng online. \n- Có khả năng làm việc độc lập và phối hợp tốt với các bộ phận khác (marketing, vận hành…). \n- Quản lý thời gian tốt, đảm bảo deadline và xử lý công việc linh hoạt. \n- Nhiệt tình, chủ động, chịu được áp lực, mong muốn gắn bó lâu dài với công ty. \n- Bắt buộc gửi kèm portfolio các sản phẩm đã từng thực hiện (file đính kèm hoặc link trực tuyến)', 8000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3380, 1490, 188, 'Trưởng Phòng Kinh Doanh Marketing Digital', '- Xây dựng, triển khai và giám sát kế hoạch kinh doanh & marketing digital theo mục tiêu công ty.\n- Quản lý và phát triển đội ngũ sale & marketing: đào tạo, phân bổ KPI, giám sát hiệu quả.\n- Định hướng chiến lược dịch vụ phễu marketing: audit ads, landing page, SEO, media, Tiktok/Meta/Google…\n- Phối hợp với đội sale để tìm kiếm, tiếp cận và chốt khách hàng tiềm năng (DN nhỏ, shop online, spa, F&B…).\n- Phát triển & tối ưu phễu thu hút khách hàng: tạo offer miễn phí, case study, quà tặng, nội dung hữu ích.\n- Xây dựng & quản lý quan hệ đối tác (agency khác, freelancer, KOLs…) để mở rộng nguồn khách hàng.\n- Theo dõi thị trường, nghiên cứu đối thủ, đề xuất giải pháp nâng cao hiệu quả marketing & bán hàng.\n- Báo cáo trực tiếp cho Ban Giám Đốc về hiệu quả kinh doanh – marketing định kỳ (tuần/tháng/quý).', '- Tối thiểu 2 năm kinh nghiệm ở vị trí trưởng nhóm/trưởng phòng kinh doanh hoặc marketing digital.\n- Am hiểu các kênh digital (Meta, Google, Tiktok, SEO, landing page, full-funnel marketing).\n- Có kỹ năng lập kế hoạch, phân tích data, tối ưu chi phí quảng cáo & tăng trưởng khách hàng.\n- Có tư duy kinh doanh, định hướng kết quả, khả năng xây dựng và dẫn dắt đội nhóm.\n- Ưu tiên ứng viên có kinh nghiệm trong các ngành: F&B, spa, giáo dục, bán hàng online.\n- Kỹ năng giao tiếp, đàm phán, thuyết phục khách hàng tốt.', 10000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3381, 1556, 254, 'Nhân Viên Kinh Doanh (Làm Việc T2 ~ T6)', 'Hỗ trợ khách hàng trong nước và nước ngoài tiếp cận với sản phẩm công ty\nTư vấn sản phẩm công ty mặt hàng phong thủy với khách hàng\nTham gia các buổi tranning do công ty tổ chức\nCác công việc khác mà cấp trên bàn giao', 'Không yêu cầu kinh nghiệm \nKhông yêu cầu tuổi tác\nKhông yêu cầu trình độ học vấn, biết tiếng trung là một lợi thế\nChỉ yêu cầu có “một trái tim” nhiệt tình với công ty', 10000000.00, 50000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3382, 1557, 255, 'Nhân Viên Marketing', '1. Thông tin chung.\n- Tuyển nhân viên content và quay dựng edit video.\n- Nhận sinh viên làm Partime về mảng viết content cho fanpage, web.\n- Nhận sinh viên làm Partime về mảng quay dựng và edit video.\n- Thời gian làm việc linh hoạt (được trao đổi cụ thể hơn khi phỏng vấn trực tiếp).\n- Địa chỉ làm việc: 19A Nguyễn Văn Vịnh, Hiệp Tân, Tân Phú, TP.HCM.\n2. Mục đích công việc:\n- Quảng bá, truyền thông các sản phẩm và dịch vụ của cửa hàng trên các kênh online và offline\n- Tương tác, thu hút, mở rộng tệp khách hàng trên các kênh MXH, điều hướng về cửa hàng.', 'Tốt nghiệp hoặc đang theo học Cao đẳng, Đại học chuyên ngành Marketing, truyền thông hoặc các chuyên ngành liên quan.\nGiọng nói dễ nghe, khả năng nói và quan sát tốt.\nNgoại hình ưa nhìn.\nCó laptop cá nhân.\nKhông ngại ống kính.\nCó khả năng làm việc độc lập và làm việc theo nhóm.\nCó hiểu biết, kinh nghiệm và tư duy quay dựng làm Content video ngắn là 1 lợi thế.', 6000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3383, 1558, 256, 'Nhân Viên Kinh Doanh 15 -20 Triệu - Cơ Hội Thăng Tiến Giám Sát, Quản Lý Bán Hàng', 'Tìm kiếm và đặt lịch hẹn gặp khách hàng.\nChào sản phẩm của công ty tại nhà của khách hàng. (Thiết bị làm sạch của Mỹ và Ý).\nTư vấn khách hàng về sản phẩm. (Sẽ được training đầy đủ các bước).\nNhững việc khác theo sự phân công của giám đốc và quản lý.\nThời gian làm việc:  5.5 ngày/tuần: Thứ Ba - Thứ Bảy (8h00 - 17h00); Chủ Nhật hoặc Thứ Hai làm nửa buổi (ứng viên có thể chọn làm nửa buổi Chủ Nhật hoặc nửa buổi Thứ Hai).', 'Yêu cầu có ít nhất 1 năm kinh nghiệm sau khi tốt nghiệp (mọi lĩnh vực đều được chào đón)\nSiêng năng, chịu khó, trung thực, cố gắng học hỏi cái mới.\nNgoại hình dễ nhìn.\nCó thể thu xếp gặp khách hàng vào cuối tuần hoặc buổi tối.', 15000000.00, 20000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534'),
	(3384, 1559, 257, 'Content Marketing', '1. Viết và chỉnh sửa:\nPhát triển nội dung chiến lược dựa trên mục tiêu kinh doanh và yêu cầu của đối tượng mục tiêu.\nChịu trách nhiệm xây dựng nội dung cho các vấn đề khác nhau: Các bài báo, bài đăng trên mạng xã hội, các bài nghiên cứu, mô tả sản phẩm, thông cáo truyền thông và những tài liệu bằng văn bản khác theo những yêu cầu được phân công.\n2. Nghiên cứu: Đảm bảo tính chính xác và tin cậy.\nThu thập thông tin từ những nguồn đáng tin cậy, sử dụng dữ liệu cũng như số liệu thống kê để tăng tin cậy cho tuyên bố của mình.\n3. Tối ưu hóa SEO: \nNghiên cứu các từ khoá để tối ưu hoá nội dung cho công cụ tìm kiếm (SEO).\nYêu cầu liên quan đến vấn đề kết hợp những từ khoá, ngôn ngữ tự nhiên và các liên kết ngược phù hợp trong nội dung chủ đề.\n4. Phân tích đối tượng: giúp gây được tiếng vang và tạo ra sự tương tác tốt nhất.\nHiểu được đối tượng mục tiêu hướng đến.\nTương tác với độc giả thông qua bình luận, chia sẻ, phản hồi.\nXác định nhu cầu, sở thích của độc giả để điều chỉnh nội dung cho phù hợp.\n5. Quảng bá nội dung: \nChịu trách nhiệm quảng bá tác phẩm của mình trên các nền tảng khác nhau, chẳng hạn như các kên truyền thông xã hội, email và các diễn đàn.\nTạo ra những tiêu đề hấp dẫn và những đoạn trích thú vị để thu hút người xem.\n6. Hợp tác:\nPhối hợp với các thành viên khác trong nhóm, bao gồm thiết kế đồ hoạ, tiếp thị…\nYêu cầu khả năng giao tiếp hiệu quả, kết hợp những phản hồi và thích ứng các phong cách và giọng điệu khác nhau.\n7. Kiểm tra và chỉnh sửa: Đảm bảo nội dung luôn chính xác và không có lỗi.', 'Có laptop cá nhân.\nTrình độ học vấn : Cao Đẳng/Đại Học trở lên.\nTrình độ chuyên môn: Marketing, Truyền thông, Báo chí hoặc các ngành liên quan.\nTrình độ vi tính: Sử dụng thành thạo tin học văn phòng.\nTrình độ ngoại ngữ: IELTS 6.5 trở lên.\nKinh nghiệm: Ưu tiên có kinh nghiệm trên 02 năm (vững chính tả, ngữ pháp)\nKỹ năng giao tiếp tốt, nhạy bén, phân tích, đánh giá, có kỹ năng thuyết phục và kỹ năng đàm phán, giải quyết xung đột tốt.\nKhả năng làm việc độc lập và chịu áp lực cao, cẩn thận, khả năng bao quát công việc tốt.\nTrung thực, siêng năng, nhiệt tình với công việc, thân thiện với mọi người.', 12000000.00, 15000000.00, 'TP.HCM', 'Full-time', '2025-10-07 20:59:18.149534');
